                          EDGE_TOP | EDGE_BOTTOM);

        s->dsp.draw_edges(s->current_picture.f.data[1], s->current_picture.f.linesize[1],

                          s->h_edge_pos >> hshift, s->v_edge_pos >> vshift,

                          EDGE_WIDTH >> hshift, EDGE_WIDTH >> vshift,

