        if (hwaccels[i].pix_fmt == pix_fmt)

            return &hwaccels[i];

    return NULL;

}

int ff_get_cpu_flags_x86(void)

{

    int rval = 0;



#ifdef cpuid



    int eax, ebx, ecx, edx;

    int max_std_level, max_ext_level, std_caps = 0, ext_caps = 0;

    int family = 0, model = 0;

    union { int i[3]; char c[12]; } vendor;



    if (!cpuid_test())

        return 0; /* CPUID not supported */



    cpuid(0, max_std_level, vendor.i[0], vendor.i[2], vendor.i[1]);



    if (max_std_level >= 1) {

        cpuid(1, eax, ebx, ecx, std_caps);

        family = ((eax >> 8) & 0xf) + ((eax >> 20) & 0xff);

        model  = ((eax >> 4) & 0xf) + ((eax >> 12) & 0xf0);

        if (std_caps & (1 << 15))

            rval |= AV_CPU_FLAG_CMOV;

        if (std_caps & (1 << 23))

            rval |= AV_CPU_FLAG_MMX;

        if (std_caps & (1 << 25))

            rval |= AV_CPU_FLAG_MMXEXT;

#if HAVE_SSE

        if (std_caps & (1 << 25))

            rval |= AV_CPU_FLAG_SSE;

        if (std_caps & (1 << 26))

            rval |= AV_CPU_FLAG_SSE2;

        if (ecx & 1)

            rval |= AV_CPU_FLAG_SSE3;

        if (ecx & 0x00000200 )

            rval |= AV_CPU_FLAG_SSSE3;

        if (ecx & 0x00080000 )

            rval |= AV_CPU_FLAG_SSE4;

        if (ecx & 0x00100000 )

            rval |= AV_CPU_FLAG_SSE42;

#if HAVE_AVX

        /* Check OXSAVE and AVX bits */

        if ((ecx & 0x18000000) == 0x18000000) {

            /* Check for OS support */

            xgetbv(0, eax, edx);

            if ((eax & 0x6) == 0x6) {

                rval |= AV_CPU_FLAG_AVX;

                if (ecx & 0x00001000)

                    rval |= AV_CPU_FLAG_FMA3;

            }

        }

#endif /* HAVE_AVX */

#endif /* HAVE_SSE */

    }

    if (max_std_level >= 7) {

        cpuid(7, eax, ebx, ecx, edx);

#if HAVE_AVX2

        if (ebx & 0x00000020)

            rval |= AV_CPU_FLAG_AVX2;

#endif /* HAVE_AVX2 */

        /* BMI1/2 don't need OS support */

        if (ebx & 0x00000008) {

            rval |= AV_CPU_FLAG_BMI1;

            if (ebx & 0x00000100)

                rval |= AV_CPU_FLAG_BMI2;

        }

    }



    cpuid(0x80000000, max_ext_level, ebx, ecx, edx);



    if (max_ext_level >= 0x80000001) {

        cpuid(0x80000001, eax, ebx, ecx, ext_caps);

        if (ext_caps & (1U << 31))

            rval |= AV_CPU_FLAG_3DNOW;

        if (ext_caps & (1 << 30))

            rval |= AV_CPU_FLAG_3DNOWEXT;

        if (ext_caps & (1 << 23))

            rval |= AV_CPU_FLAG_MMX;

        if (ext_caps & (1 << 22))

            rval |= AV_CPU_FLAG_MMXEXT;



        /* Allow for selectively disabling SSE2 functions on AMD processors

           with SSE2 support but not SSE4a. This includes Athlon64, some

           Opteron, and some Sempron processors. MMX, SSE, or 3DNow! are faster

           than SSE2 often enough to utilize this special-case flag.

           AV_CPU_FLAG_SSE2 and AV_CPU_FLAG_SSE2SLOW are both set in this case

           so that SSE2 is used unless explicitly disabled by checking

           AV_CPU_FLAG_SSE2SLOW. */

        if (!strncmp(vendor.c, "AuthenticAMD", 12) &&

            rval & AV_CPU_FLAG_SSE2 && !(ecx & 0x00000040)) {

            rval |= AV_CPU_FLAG_SSE2SLOW;

        }



        /* XOP and FMA4 use the AVX instruction coding scheme, so they can't be

         * used unless the OS has AVX support. */

        if (rval & AV_CPU_FLAG_AVX) {

            if (ecx & 0x00000800)

                rval |= AV_CPU_FLAG_XOP;

            if (ecx & 0x00010000)

                rval |= AV_CPU_FLAG_FMA4;

        }

    }



    if (!strncmp(vendor.c, "GenuineIntel", 12)) {

        if (family == 6 && (model == 9 || model == 13 || model == 14)) {

            /* 6/9 (pentium-m "banias"), 6/13 (pentium-m "dothan"), and

             * 6/14 (core1 "yonah") theoretically support sse2, but it's

             * usually slower than mmx, so let's just pretend they don't.

             * AV_CPU_FLAG_SSE2 is disabled and AV_CPU_FLAG_SSE2SLOW is

             * enabled so that SSE2 is not used unless explicitly enabled

             * by checking AV_CPU_FLAG_SSE2SLOW. The same situation

             * applies for AV_CPU_FLAG_SSE3 and AV_CPU_FLAG_SSE3SLOW. */

            if (rval & AV_CPU_FLAG_SSE2)

                rval ^= AV_CPU_FLAG_SSE2SLOW | AV_CPU_FLAG_SSE2;

            if (rval & AV_CPU_FLAG_SSE3)

                rval ^= AV_CPU_FLAG_SSE3SLOW | AV_CPU_FLAG_SSE3;

        }

        /* The Atom processor has SSSE3 support, which is useful in many cases,

         * but sometimes the SSSE3 version is slower than the SSE2 equivalent

         * on the Atom, but is generally faster on other processors supporting

         * SSSE3. This flag allows for selectively disabling certain SSSE3

         * functions on the Atom. */

        if (family == 6 && model == 28)

            rval |= AV_CPU_FLAG_ATOM;

    }



#endif /* cpuid */



    return rval;

}

static int read_sl_header(PESContext *pes, SLConfigDescr *sl, const uint8_t *buf, int buf_size)

{

    GetBitContext gb;

    int au_start_flag = 0, au_end_flag = 0, ocr_flag = 0, idle_flag = 0;

    int padding_flag = 0, padding_bits = 0, inst_bitrate_flag = 0;

    int dts_flag = -1, cts_flag = -1;

    int64_t dts = AV_NOPTS_VALUE, cts = AV_NOPTS_VALUE;

    init_get_bits(&gb, buf, buf_size*8);



    if (sl->use_au_start)

        au_start_flag = get_bits1(&gb);

    if (sl->use_au_end)

        au_end_flag = get_bits1(&gb);

    if (!sl->use_au_start && !sl->use_au_end)

        au_start_flag = au_end_flag = 1;

    if (sl->ocr_len > 0)

        ocr_flag = get_bits1(&gb);

    if (sl->use_idle)

        idle_flag = get_bits1(&gb);

    if (sl->use_padding)

        padding_flag = get_bits1(&gb);

    if (padding_flag)

        padding_bits = get_bits(&gb, 3);



    if (!idle_flag && (!padding_flag || padding_bits != 0)) {

        if (sl->packet_seq_num_len)

            skip_bits_long(&gb, sl->packet_seq_num_len);

        if (sl->degr_prior_len)

            if (get_bits1(&gb))

                skip_bits(&gb, sl->degr_prior_len);

        if (ocr_flag)

            skip_bits_long(&gb, sl->ocr_len);

        if (au_start_flag) {

            if (sl->use_rand_acc_pt)

                get_bits1(&gb);

            if (sl->au_seq_num_len > 0)

                skip_bits_long(&gb, sl->au_seq_num_len);

            if (sl->use_timestamps) {

                dts_flag = get_bits1(&gb);

                cts_flag = get_bits1(&gb);

            }

        }

        if (sl->inst_bitrate_len)

            inst_bitrate_flag = get_bits1(&gb);

        if (dts_flag == 1)

            dts = get_bits64(&gb, sl->timestamp_len);

        if (cts_flag == 1)

            cts = get_bits64(&gb, sl->timestamp_len);

        if (sl->au_len > 0)

            skip_bits_long(&gb, sl->au_len);

        if (inst_bitrate_flag)

            skip_bits_long(&gb, sl->inst_bitrate_len);

    }



    if (dts != AV_NOPTS_VALUE)

        pes->dts = dts;

    if (cts != AV_NOPTS_VALUE)

        pes->pts = cts;



    avpriv_set_pts_info(pes->st, sl->timestamp_len, 1, sl->timestamp_res);



    return (get_bits_count(&gb) + 7) >> 3;

}

static enum AVHWDeviceType hw_device_match_type_in_name(const char *codec_name)

{

    const char *type_name;

    enum AVHWDeviceType type;

    for (type = av_hwdevice_iterate_types(AV_HWDEVICE_TYPE_NONE);

         type != AV_HWDEVICE_TYPE_NONE;

         type = av_hwdevice_iterate_types(type)) {

        type_name = av_hwdevice_get_type_name(type);

        if (strstr(codec_name, type_name))

            return type;

    }

    return AV_HWDEVICE_TYPE_NONE;

}

