int avpicture_deinterlace(AVPicture *dst, const AVPicture *src,

                          enum AVPixelFormat pix_fmt, int width, int height)

{

    int i;



    if (pix_fmt != AV_PIX_FMT_YUV420P &&

        pix_fmt != AV_PIX_FMT_YUVJ420P &&

        pix_fmt != AV_PIX_FMT_YUV422P &&

        pix_fmt != AV_PIX_FMT_YUVJ422P &&

        pix_fmt != AV_PIX_FMT_YUV444P &&

        pix_fmt != AV_PIX_FMT_YUV411P &&

        pix_fmt != AV_PIX_FMT_GRAY8)

        return -1;

    if ((width & 3) != 0 || (height & 3) != 0)

        return -1;



    for(i=0;i<3;i++) {

        if (i == 1) {

            switch(pix_fmt) {

            case AV_PIX_FMT_YUVJ420P:

            case AV_PIX_FMT_YUV420P:

                width >>= 1;

                height >>= 1;

                break;

            case AV_PIX_FMT_YUV422P:

            case AV_PIX_FMT_YUVJ422P:

                width >>= 1;

                break;

            case AV_PIX_FMT_YUV411P:

                width >>= 2;

                break;

            default:

                break;

            }

            if (pix_fmt == AV_PIX_FMT_GRAY8) {

                break;

            }

        }

        if (src == dst) {

            deinterlace_bottom_field_inplace(dst->data[i], dst->linesize[i],

                                 width, height);

        } else {

            deinterlace_bottom_field(dst->data[i],dst->linesize[i],

                                        src->data[i], src->linesize[i],

                                        width, height);

        }

    }

    emms_c();

    return 0;

}

static void chroma_mc(HEVCContext *s, int16_t *dst1, int16_t *dst2,

                      ptrdiff_t dststride, AVFrame *ref, const Mv *mv,

                      int x_off, int y_off, int block_w, int block_h)

{

    HEVCLocalContext *lc = &s->HEVClc;

    uint8_t *src1        = ref->data[1];

    uint8_t *src2        = ref->data[2];

    ptrdiff_t src1stride = ref->linesize[1];

    ptrdiff_t src2stride = ref->linesize[2];

    int pic_width        = s->ps.sps->width >> 1;

    int pic_height       = s->ps.sps->height >> 1;



    int mx = mv->x & 7;

    int my = mv->y & 7;



    x_off += mv->x >> 3;

    y_off += mv->y >> 3;

    src1  += y_off * src1stride + (x_off << s->ps.sps->pixel_shift);

    src2  += y_off * src2stride + (x_off << s->ps.sps->pixel_shift);



    if (x_off < EPEL_EXTRA_BEFORE || y_off < EPEL_EXTRA_AFTER ||

        x_off >= pic_width - block_w - EPEL_EXTRA_AFTER ||

        y_off >= pic_height - block_h - EPEL_EXTRA_AFTER) {

        const int edge_emu_stride = EDGE_EMU_BUFFER_STRIDE << s->ps.sps->pixel_shift;

        int offset1 = EPEL_EXTRA_BEFORE * (src1stride + (1 << s->ps.sps->pixel_shift));

        int buf_offset1 = EPEL_EXTRA_BEFORE *

                          (edge_emu_stride + (1 << s->ps.sps->pixel_shift));

        int offset2 = EPEL_EXTRA_BEFORE * (src2stride + (1 << s->ps.sps->pixel_shift));

        int buf_offset2 = EPEL_EXTRA_BEFORE *

                          (edge_emu_stride + (1 << s->ps.sps->pixel_shift));



        s->vdsp.emulated_edge_mc(lc->edge_emu_buffer, src1 - offset1,

                                 edge_emu_stride, src1stride,

                                 block_w + EPEL_EXTRA, block_h + EPEL_EXTRA,

                                 x_off - EPEL_EXTRA_BEFORE,

                                 y_off - EPEL_EXTRA_BEFORE,

                                 pic_width, pic_height);



        src1 = lc->edge_emu_buffer + buf_offset1;

        src1stride = edge_emu_stride;

        s->hevcdsp.put_hevc_epel[!!my][!!mx](dst1, dststride, src1, src1stride,

                                             block_w, block_h, mx, my, lc->mc_buffer);



        s->vdsp.emulated_edge_mc(lc->edge_emu_buffer, src2 - offset2,

                                 edge_emu_stride, src2stride,

                                 block_w + EPEL_EXTRA, block_h + EPEL_EXTRA,

                                 x_off - EPEL_EXTRA_BEFORE,

                                 y_off - EPEL_EXTRA_BEFORE,

                                 pic_width, pic_height);

        src2 = lc->edge_emu_buffer + buf_offset2;

        src2stride = edge_emu_stride;



        s->hevcdsp.put_hevc_epel[!!my][!!mx](dst2, dststride, src2, src2stride,

                                             block_w, block_h, mx, my,

                                             lc->mc_buffer);

    } else {

        s->hevcdsp.put_hevc_epel[!!my][!!mx](dst1, dststride, src1, src1stride,

                                             block_w, block_h, mx, my,

                                             lc->mc_buffer);

        s->hevcdsp.put_hevc_epel[!!my][!!mx](dst2, dststride, src2, src2stride,

                                             block_w, block_h, mx, my,

                                             lc->mc_buffer);

    }

}

static void mpegts_push_data(void *opaque,

                             const uint8_t *buf, int buf_size, int is_start)

{

    PESContext *pes = opaque;

    MpegTSContext *ts = pes->stream->priv_data;

    AVStream *st;

    const uint8_t *p;

    int len, code, codec_type, codec_id;



    if (is_start) {

        pes->state = MPEGTS_HEADER;

        pes->data_index = 0;

    }

    p = buf;

    while (buf_size > 0) {

        switch(pes->state) {

        case MPEGTS_HEADER:

            len = PES_START_SIZE - pes->data_index;

            if (len > buf_size)

                len = buf_size;

            memcpy(pes->header + pes->data_index, p, len);

            pes->data_index += len;

            p += len;

            buf_size -= len;

            if (pes->data_index == PES_START_SIZE) {

                /* we got all the PES or section header. We can now

                   decide */

#if 0

                av_hex_dump(pes->header, pes->data_index);

#endif

                if (pes->header[0] == 0x00 && pes->header[1] == 0x00 &&

                    pes->header[2] == 0x01) {

                    /* it must be an mpeg2 PES stream */

                    /* XXX: add AC3 support */

                    code = pes->header[3] | 0x100;

                    if (!((code >= 0x1c0 && code <= 0x1df) ||

                          (code >= 0x1e0 && code <= 0x1ef)))

                        goto skip;

                    if (!pes->st) {

                        /* allocate stream */

                        if (code >= 0x1c0 && code <= 0x1df) {

                            codec_type = CODEC_TYPE_AUDIO;

                            codec_id = CODEC_ID_MP2;

                        } else {

                            codec_type = CODEC_TYPE_VIDEO;

                            codec_id = CODEC_ID_MPEG1VIDEO;

                        }

                        st = av_new_stream(pes->stream, pes->pid);

                        if (st) {

                            st->priv_data = pes;

                            st->codec.codec_type = codec_type;

                            st->codec.codec_id = codec_id;

                            pes->st = st;

                        }

                    }

                    pes->state = MPEGTS_PESHEADER_FILL;

                    pes->total_size = (pes->header[4] << 8) | pes->header[5];

                    /* NOTE: a zero total size means the PES size is

                       unbounded */

                    if (pes->total_size)

                        pes->total_size += 6;

                    pes->pes_header_size = pes->header[8] + 9;

                } else {

                    /* otherwise, it should be a table */

                    /* skip packet */

                skip:

                    pes->state = MPEGTS_SKIP;

                    continue;

                }

            }

            break;

            /**********************************************/

            /* PES packing parsing */

        case MPEGTS_PESHEADER_FILL:

            len = pes->pes_header_size - pes->data_index;

            if (len > buf_size)

                len = buf_size;

            memcpy(pes->header + pes->data_index, p, len);

            pes->data_index += len;

            p += len;

            buf_size -= len;

            if (pes->data_index == pes->pes_header_size) {

                const uint8_t *r;

                unsigned int flags;



                flags = pes->header[7];

                r = pes->header + 9;

                pes->pts = AV_NOPTS_VALUE;

                pes->dts = AV_NOPTS_VALUE;

                if ((flags & 0xc0) == 0x80) {

                    pes->pts = get_pts(r);

                    r += 5;

                } else if ((flags & 0xc0) == 0xc0) {

                    pes->pts = get_pts(r);

                    r += 5;

                    pes->dts = get_pts(r);

                    r += 5;

                }

                /* we got the full header. We parse it and get the payload */

                pes->state = MPEGTS_PAYLOAD;

            }

            break;

        case MPEGTS_PAYLOAD:

            if (pes->total_size) {

                len = pes->total_size - pes->data_index;

                if (len > buf_size)

                    len = buf_size;

            } else {

                len = buf_size;

            }

            if (len > 0) {

                AVPacket *pkt = ts->pkt;

                if (pes->st && av_new_packet(pkt, len) == 0) {

                    memcpy(pkt->data, p, len);

                    pkt->stream_index = pes->st->index;

                    pkt->pts = pes->pts;

                    /* reset pts values */

                    pes->pts = AV_NOPTS_VALUE;

                    pes->dts = AV_NOPTS_VALUE;

                    ts->stop_parse = 1;

                    return;

                }

            }

            buf_size = 0;

            break;

        case MPEGTS_SKIP:

            buf_size = 0;

            break;

        }

    }

}

static int libopenjpeg_encode_frame(AVCodecContext *avctx, AVPacket *pkt,

                                    const AVFrame *frame, int *got_packet)

{

    LibOpenJPEGContext *ctx = avctx->priv_data;

    opj_cinfo_t *compress = ctx->compress;

    opj_image_t *image    = ctx->image;

    opj_cio_t *stream     = ctx->stream;

    int cpyresult = 0;

    int ret, len;

    AVFrame *gbrframe;



    switch (avctx->pix_fmt) {

    case AV_PIX_FMT_RGB24:

    case AV_PIX_FMT_RGBA:

    case AV_PIX_FMT_GRAY8A:

        cpyresult = libopenjpeg_copy_packed8(avctx, frame, image);

        break;

    case AV_PIX_FMT_XYZ12:

        cpyresult = libopenjpeg_copy_packed12(avctx, frame, image);

        break;

    case AV_PIX_FMT_RGB48:

    case AV_PIX_FMT_RGBA64:

        cpyresult = libopenjpeg_copy_packed16(avctx, frame, image);

        break;

    case AV_PIX_FMT_GBR24P:

    case AV_PIX_FMT_GBRP9:

    case AV_PIX_FMT_GBRP10:

    case AV_PIX_FMT_GBRP12:

    case AV_PIX_FMT_GBRP14:

    case AV_PIX_FMT_GBRP16:

        gbrframe = av_frame_alloc();



        av_frame_ref(gbrframe, frame);

        gbrframe->data[0] = frame->data[2]; // swap to be rgb

        gbrframe->data[1] = frame->data[0];

        gbrframe->data[2] = frame->data[1];

        gbrframe->linesize[0] = frame->linesize[2];

        gbrframe->linesize[1] = frame->linesize[0];

        gbrframe->linesize[2] = frame->linesize[1];

        if (avctx->pix_fmt == AV_PIX_FMT_GBR24P) {

            cpyresult = libopenjpeg_copy_unpacked8(avctx, gbrframe, image);

        } else {

            cpyresult = libopenjpeg_copy_unpacked16(avctx, gbrframe, image);

        }

        av_frame_free(&gbrframe);

        break;

    case AV_PIX_FMT_GRAY8:

    case AV_PIX_FMT_YUV410P:

    case AV_PIX_FMT_YUV411P:

    case AV_PIX_FMT_YUV420P:

    case AV_PIX_FMT_YUV422P:

    case AV_PIX_FMT_YUV440P:

    case AV_PIX_FMT_YUV444P:

    case AV_PIX_FMT_YUVA420P:

    case AV_PIX_FMT_YUVA422P:

    case AV_PIX_FMT_YUVA444P:

        cpyresult = libopenjpeg_copy_unpacked8(avctx, frame, image);

        break;

    case AV_PIX_FMT_GRAY16:

    case AV_PIX_FMT_YUV420P9:

    case AV_PIX_FMT_YUV422P9:

    case AV_PIX_FMT_YUV444P9:

    case AV_PIX_FMT_YUVA420P9:

    case AV_PIX_FMT_YUVA422P9:

    case AV_PIX_FMT_YUVA444P9:

    case AV_PIX_FMT_YUV444P10:

    case AV_PIX_FMT_YUV422P10:

    case AV_PIX_FMT_YUV420P10:

    case AV_PIX_FMT_YUVA444P10:

    case AV_PIX_FMT_YUVA422P10:

    case AV_PIX_FMT_YUVA420P10:

    case AV_PIX_FMT_YUV420P12:

    case AV_PIX_FMT_YUV422P12:

    case AV_PIX_FMT_YUV444P12:

    case AV_PIX_FMT_YUV420P14:

    case AV_PIX_FMT_YUV422P14:

    case AV_PIX_FMT_YUV444P14:

    case AV_PIX_FMT_YUV444P16:

    case AV_PIX_FMT_YUV422P16:

    case AV_PIX_FMT_YUV420P16:

    case AV_PIX_FMT_YUVA444P16:

    case AV_PIX_FMT_YUVA422P16:

    case AV_PIX_FMT_YUVA420P16:

        cpyresult = libopenjpeg_copy_unpacked16(avctx, frame, image);

        break;

    default:

        av_log(avctx, AV_LOG_ERROR,

               "The frame's pixel format '%s' is not supported\n",

               av_get_pix_fmt_name(avctx->pix_fmt));

        return AVERROR(EINVAL);

        break;

    }



    if (!cpyresult) {

        av_log(avctx, AV_LOG_ERROR,

               "Could not copy the frame data to the internal image buffer\n");

        return -1;

    }



    cio_seek(stream, 0);

    if (!opj_encode(compress, stream, image, NULL)) {

        av_log(avctx, AV_LOG_ERROR, "Error during the opj encode\n");

        return -1;

    }



    len = cio_tell(stream);

    if ((ret = ff_alloc_packet2(avctx, pkt, len)) < 0) {

        return ret;

    }



    memcpy(pkt->data, stream->buffer, len);

    pkt->flags |= AV_PKT_FLAG_KEY;

    *got_packet = 1;

    return 0;

}

static int rtp_parse_one_packet(RTPDemuxContext *s, AVPacket *pkt,

                                uint8_t **bufptr, int len)

{

    uint8_t *buf = bufptr ? *bufptr : NULL;

    int flags = 0;

    uint32_t timestamp;

    int rv = 0;



    if (!buf) {

        /* If parsing of the previous packet actually returned 0 or an error,

         * there's nothing more to be parsed from that packet, but we may have

         * indicated that we can return the next enqueued packet. */

        if (s->prev_ret <= 0)

            return rtp_parse_queued_packet(s, pkt);

        /* return the next packets, if any */

        if (s->handler && s->handler->parse_packet) {

            /* timestamp should be overwritten by parse_packet, if not,

             * the packet is left with pts == AV_NOPTS_VALUE */

            timestamp = RTP_NOTS_VALUE;

            rv        = s->handler->parse_packet(s->ic, s->dynamic_protocol_context,

                                                 s->st, pkt, &timestamp, NULL, 0, 0,

                                                 flags);

            finalize_packet(s, pkt, timestamp);

            return rv;

        }

    }



    if (len < 12)

        return -1;



    if ((buf[0] & 0xc0) != (RTP_VERSION << 6))

        return -1;

    if (RTP_PT_IS_RTCP(buf[1])) {

        return rtcp_parse_packet(s, buf, len);

    }



    if (s->st) {

        int64_t received = av_gettime_relative();

        uint32_t arrival_ts = av_rescale_q(received, AV_TIME_BASE_Q,

                                           s->st->time_base);

        timestamp = AV_RB32(buf + 4);

        // Calculate the jitter immediately, before queueing the packet

        // into the reordering queue.

        rtcp_update_jitter(&s->statistics, timestamp, arrival_ts);

    }



    if ((s->seq == 0 && !s->queue) || s->queue_size <= 1) {

        /* First packet, or no reordering */

        return rtp_parse_packet_internal(s, pkt, buf, len);

    } else {

        uint16_t seq = AV_RB16(buf + 2);

        int16_t diff = seq - s->seq;

        if (diff < 0) {

            /* Packet older than the previously emitted one, drop */

            av_log(s->st ? s->st->codec : NULL, AV_LOG_WARNING,

                   "RTP: dropping old packet received too late\n");

            return -1;

        } else if (diff <= 1) {

            /* Correct packet */

            rv = rtp_parse_packet_internal(s, pkt, buf, len);

            return rv;

        } else {

            /* Still missing some packet, enqueue this one. */

            enqueue_packet(s, buf, len);

            *bufptr = NULL;

            /* Return the first enqueued packet if the queue is full,

             * even if we're missing something */

            if (s->queue_len >= s->queue_size) {

                av_log(s->st ? s->st->codec : NULL, AV_LOG_WARNING,

                       "jitter buffer full\n");

                return rtp_parse_queued_packet(s, pkt);

            }

            return -1;

        }

    }

}

static inline void RENAME(rgb16to15)(const uint8_t *src,uint8_t *dst,long src_size)

{

  register const uint8_t* s=src;

  register uint8_t* d=dst;

  register const uint8_t *end;

  const uint8_t *mm_end;

  end = s + src_size;

#ifdef HAVE_MMX

  __asm __volatile(PREFETCH"	%0"::"m"(*s));

  __asm __volatile("movq	%0, %%mm7"::"m"(mask15rg));

  __asm __volatile("movq	%0, %%mm6"::"m"(mask15b));

  mm_end = end - 15;

  while(s<mm_end)

  {

	__asm __volatile(

		PREFETCH"	32%1\n\t"

		"movq	%1, %%mm0\n\t"

		"movq	8%1, %%mm2\n\t"

		"movq	%%mm0, %%mm1\n\t"

		"movq	%%mm2, %%mm3\n\t"

		"psrlq	$1, %%mm0\n\t"

		"psrlq	$1, %%mm2\n\t"

		"pand	%%mm7, %%mm0\n\t"

		"pand	%%mm7, %%mm2\n\t"

		"pand	%%mm6, %%mm1\n\t"

		"pand	%%mm6, %%mm3\n\t"

		"por	%%mm1, %%mm0\n\t"

		"por	%%mm3, %%mm2\n\t"

		MOVNTQ"	%%mm0, %0\n\t"

		MOVNTQ"	%%mm2, 8%0"

		:"=m"(*d)

		:"m"(*s)

		);

	d+=16;

	s+=16;

  }

  __asm __volatile(SFENCE:::"memory");

  __asm __volatile(EMMS:::"memory");

#endif

    mm_end = end - 3;

    while(s < mm_end)

    {

	register uint32_t x= *((uint32_t *)s);

	*((uint32_t *)d) = ((x>>1)&0x7FE07FE0) | (x&0x001F001F);

	s+=4;

	d+=4;

    }

    if(s < end)

    {

	register uint16_t x= *((uint16_t *)s);

	*((uint16_t *)d) = ((x>>1)&0x7FE0) | (x&0x001F);

	s+=2;

	d+=2;

    }

}

