static inline void RENAME(hyscale)(SwsContext *c, uint16_t *dst, long dstWidth, const uint8_t *src, int srcW, int xInc,

                                   const int16_t *hLumFilter,

                                   const int16_t *hLumFilterPos, int hLumFilterSize,

                                   uint8_t *formatConvBuffer,

                                   uint32_t *pal, int isAlpha)

{

    void (*toYV12)(uint8_t *, const uint8_t *, long, uint32_t *) = isAlpha ? c->alpToYV12 : c->lumToYV12;

    void (*convertRange)(int16_t *, int) = isAlpha ? NULL : c->lumConvertRange;



    src += isAlpha ? c->alpSrcOffset : c->lumSrcOffset;



    if (toYV12) {

        toYV12(formatConvBuffer, src, srcW, pal);

        src= formatConvBuffer;

    }



    if (c->hScale16) {

        c->hScale16(dst, dstWidth, (uint16_t*)src, srcW, xInc, hLumFilter, hLumFilterPos, hLumFilterSize, av_pix_fmt_descriptors[c->srcFormat].comp[0].depth_minus1);

    } else if (!c->hyscale_fast) {

        c->hScale(dst, dstWidth, src, srcW, xInc, hLumFilter, hLumFilterPos, hLumFilterSize);

    } else { // fast bilinear upscale / crap downscale

        c->hyscale_fast(c, dst, dstWidth, src, srcW, xInc);

    }



    if (convertRange)

        convertRange(dst, dstWidth);

}

static void dv_decode_ac(GetBitContext *gb, BlockInfo *mb, DCTELEM *block)

{

    int last_index = get_bits_size(gb);

    const uint8_t *scan_table = mb->scan_table;

    const uint8_t *shift_table = mb->shift_table;

    int pos = mb->pos;

    int partial_bit_count = mb->partial_bit_count;

    int level, pos1, run, vlc_len, index;



    OPEN_READER(re, gb);

    UPDATE_CACHE(re, gb);



    /* if we must parse a partial vlc, we do it here */

    if (partial_bit_count > 0) {

        re_cache = ((unsigned)re_cache >> partial_bit_count) |

	           (mb->partial_bit_buffer << (sizeof(re_cache)*8 - partial_bit_count));

	re_index -= partial_bit_count;

	mb->partial_bit_count = 0;

    }



    /* get the AC coefficients until last_index is reached */

    for(;;) {

#ifdef VLC_DEBUG

        printf("%2d: bits=%04x index=%d\n", pos, SHOW_UBITS(re, gb, 16), re_index);

#endif

        /* our own optimized GET_RL_VLC */

        index = NEG_USR32(re_cache, TEX_VLC_BITS);

	vlc_len = dv_rl_vlc[index].len;

        if (vlc_len < 0) {

            index = NEG_USR32((unsigned)re_cache << TEX_VLC_BITS, -vlc_len) + dv_rl_vlc[index].level;

            vlc_len = TEX_VLC_BITS - vlc_len;

        }

        level = dv_rl_vlc[index].level;

	run = dv_rl_vlc[index].run;



	/* gotta check if we're still within gb boundaries */

	if (re_index + vlc_len > last_index) {

	    /* should be < 16 bits otherwise a codeword could have been parsed */

	    mb->partial_bit_count = last_index - re_index;

	    mb->partial_bit_buffer = NEG_USR32(re_cache, mb->partial_bit_count);

	    re_index = last_index;

	    break;

	}

	re_index += vlc_len;



#ifdef VLC_DEBUG

	printf("run=%d level=%d\n", run, level);

#endif

	pos += run; 	

	if (pos >= 64)

	    break;



	if (level) {

            pos1 = scan_table[pos];

            block[pos1] = level << shift_table[pos1];

        } 



        UPDATE_CACHE(re, gb);

    }

    CLOSE_READER(re, gb);

    mb->pos = pos;

}

int opt_default(const char *opt, const char *arg){

    int type;

    const AVOption *o= NULL;

    int opt_types[]={AV_OPT_FLAG_VIDEO_PARAM, AV_OPT_FLAG_AUDIO_PARAM, 0, AV_OPT_FLAG_SUBTITLE_PARAM, 0};



    for(type=0; type<CODEC_TYPE_NB; type++){

        const AVOption *o2 = av_find_opt(avctx_opts[0], opt, NULL, opt_types[type], opt_types[type]);

        if(o2)

            o = av_set_string2(avctx_opts[type], opt, arg, 1);

    }

    if(!o)

        o = av_set_string2(avformat_opts, opt, arg, 1);

    if(!o)

        o = av_set_string2(sws_opts, opt, arg, 1);

    if(!o){

        if(opt[0] == 'a')

            o = av_set_string2(avctx_opts[CODEC_TYPE_AUDIO], opt+1, arg, 1);

        else if(opt[0] == 'v')

            o = av_set_string2(avctx_opts[CODEC_TYPE_VIDEO], opt+1, arg, 1);

        else if(opt[0] == 's')

            o = av_set_string2(avctx_opts[CODEC_TYPE_SUBTITLE], opt+1, arg, 1);

    }

    if(!o)

        return -1;



//    av_log(NULL, AV_LOG_ERROR, "%s:%s: %f 0x%0X\n", opt, arg, av_get_double(avctx_opts, opt, NULL), (int)av_get_int(avctx_opts, opt, NULL));



    //FIXME we should always use avctx_opts, ... for storing options so there will not be any need to keep track of what i set over this

    opt_names= av_realloc(opt_names, sizeof(void*)*(opt_name_count+1));

    opt_names[opt_name_count++]= o->name;



    if(avctx_opts[0]->debug || avformat_opts->debug)

        av_log_set_level(AV_LOG_DEBUG);

    return 0;

}

static float quantize_band_cost(struct AACEncContext *s, const float *in,

                                const float *scaled, int size, int scale_idx,

                                int cb, const float lambda, const float uplim,

                                int *bits)

{

    const float IQ = ff_aac_pow2sf_tab[200 + scale_idx - SCALE_ONE_POS + SCALE_DIV_512];

    const float  Q = ff_aac_pow2sf_tab[200 - scale_idx + SCALE_ONE_POS - SCALE_DIV_512];

    const float CLIPPED_ESCAPE = 165140.0f*IQ;

    int i, j, k;

    float cost = 0;

    const int dim = cb < FIRST_PAIR_BT ? 4 : 2;

    int resbits = 0;

#ifndef USE_REALLY_FULL_SEARCH

    const float  Q34 = sqrtf(Q * sqrtf(Q));

    const int range  = aac_cb_range[cb];

    const int maxval = aac_cb_maxval[cb];

    int offs[4];

#endif /* USE_REALLY_FULL_SEARCH */



    if (!cb) {

        for (i = 0; i < size; i++)

            cost += in[i]*in[i]*lambda;

        if (bits)

            *bits = 0;

        return cost;

    }

#ifndef USE_REALLY_FULL_SEARCH

    offs[0] = 1;

    for (i = 1; i < dim; i++)

        offs[i] = offs[i-1]*range;

    quantize_bands(s->qcoefs, in, scaled, size, Q34, !IS_CODEBOOK_UNSIGNED(cb), maxval);

#endif /* USE_REALLY_FULL_SEARCH */

    for (i = 0; i < size; i += dim) {

        float mincost;

        int minidx  = 0;

        int minbits = 0;

        const float *vec;

#ifndef USE_REALLY_FULL_SEARCH

        int (*quants)[2] = &s->qcoefs[i];

        mincost = 0.0f;

        for (j = 0; j < dim; j++)

            mincost += in[i+j]*in[i+j]*lambda;

        minidx = IS_CODEBOOK_UNSIGNED(cb) ? 0 : 40;

        minbits = ff_aac_spectral_bits[cb-1][minidx];

        mincost += minbits;

        for (j = 0; j < (1<<dim); j++) {

            float rd = 0.0f;

            int curbits;

            int curidx = IS_CODEBOOK_UNSIGNED(cb) ? 0 : 40;

            int same   = 0;

            for (k = 0; k < dim; k++) {

                if ((j & (1 << k)) && quants[k][0] == quants[k][1]) {

                    same = 1;

                    break;

                }

            }

            if (same)

                continue;

            for (k = 0; k < dim; k++)

                curidx += quants[k][!!(j & (1 << k))] * offs[dim - 1 - k];

            curbits =  ff_aac_spectral_bits[cb-1][curidx];

            vec     = &ff_aac_codebook_vectors[cb-1][curidx*dim];

#else

        mincost = INFINITY;

        vec = ff_aac_codebook_vectors[cb-1];

        for (j = 0; j < ff_aac_spectral_sizes[cb-1]; j++, vec += dim) {

            float rd = 0.0f;

            int curbits = ff_aac_spectral_bits[cb-1][j];

#endif /* USE_REALLY_FULL_SEARCH */

            if (IS_CODEBOOK_UNSIGNED(cb)) {

                for (k = 0; k < dim; k++) {

                    float t = fabsf(in[i+k]);

                    float di;

                    //do not code with escape sequence small values

                    if (vec[k] == 64.0f && t < 39.0f*IQ) {

                        rd = INFINITY;

                        break;

                    }

                    if (vec[k] == 64.0f) { //FIXME: slow

                        if (t >= CLIPPED_ESCAPE) {

                            di = t - CLIPPED_ESCAPE;

                            curbits += 21;

                        } else {

                            int c = av_clip(quant(t, Q), 0, 8191);

                            di = t - c*cbrt(c)*IQ;

                            curbits += av_log2(c)*2 - 4 + 1;

                        }

                    } else {

                        di = t - vec[k]*IQ;

                    }

                    if (vec[k] != 0.0f)

                        curbits++;

                    rd += di*di*lambda;

                }

            } else {

                for (k = 0; k < dim; k++) {

                    float di = in[i+k] - vec[k]*IQ;

                    rd += di*di*lambda;

                }

            }

            rd += curbits;

            if (rd < mincost) {

                mincost = rd;

                minidx  = j;

                minbits = curbits;

            }

        }

        cost    += mincost;

        resbits += minbits;

        if (cost >= uplim)

            return uplim;

    }



    if (bits)

        *bits = resbits;

    return cost;

}

static int encode_subband_c0run(SnowContext *s, SubBand *b, DWTELEM *src, DWTELEM *parent, int stride, int orientation){

    const int w= b->width;

    const int h= b->height;

    int x, y;



    if(1){

        int run=0;

        int runs[w*h];

        int run_index=0;



        for(y=0; y<h; y++){

            for(x=0; x<w; x++){

                int v, p=0;

                int /*ll=0, */l=0, lt=0, t=0, rt=0;

                v= src[x + y*stride];



                if(y){

                    t= src[x + (y-1)*stride];

                    if(x){

                        lt= src[x - 1 + (y-1)*stride];

                    }

                    if(x + 1 < w){

                        rt= src[x + 1 + (y-1)*stride];

                    }

                }

                if(x){

                    l= src[x - 1 + y*stride];

                    /*if(x > 1){

                        if(orientation==1) ll= src[y + (x-2)*stride];

                        else               ll= src[x - 2 + y*stride];

                    }*/

                }

                if(parent){

                    int px= x>>1;

                    int py= y>>1;

                    if(px<b->parent->width && py<b->parent->height) 

                        p= parent[px + py*2*stride];

                }

                if(!(/*ll|*/l|lt|t|rt|p)){

                    if(v){

                        runs[run_index++]= run;

                        run=0;

                    }else{

                        run++;

                    }

                }

            }

        }

        runs[run_index++]= run;

        run_index=0;

        run= runs[run_index++];



        put_symbol2(&s->c, b->state[1], run, 3);



        for(y=0; y<h; y++){

            if(s->c.bytestream_end - s->c.bytestream < w*40){

                av_log(s->avctx, AV_LOG_ERROR, "encoded frame too large\n");

                return -1;

            }

            for(x=0; x<w; x++){

                int v, p=0;

                int /*ll=0, */l=0, lt=0, t=0, rt=0;

                v= src[x + y*stride];



                if(y){

                    t= src[x + (y-1)*stride];

                    if(x){

                        lt= src[x - 1 + (y-1)*stride];

                    }

                    if(x + 1 < w){

                        rt= src[x + 1 + (y-1)*stride];

                    }

                }

                if(x){

                    l= src[x - 1 + y*stride];

                    /*if(x > 1){

                        if(orientation==1) ll= src[y + (x-2)*stride];

                        else               ll= src[x - 2 + y*stride];

                    }*/

                }

                if(parent){

                    int px= x>>1;

                    int py= y>>1;

                    if(px<b->parent->width && py<b->parent->height) 

                        p= parent[px + py*2*stride];

                }

                if(/*ll|*/l|lt|t|rt|p){

                    int context= av_log2(/*ABS(ll) + */3*ABS(l) + ABS(lt) + 2*ABS(t) + ABS(rt) + ABS(p));



                    put_rac(&s->c, &b->state[0][context], !!v);

                }else{

                    if(!run){

                        run= runs[run_index++];



                        put_symbol2(&s->c, b->state[1], run, 3);

                        assert(v);

                    }else{

                        run--;

                        assert(!v);

                    }

                }

                if(v){

                    int context= av_log2(/*ABS(ll) + */3*ABS(l) + ABS(lt) + 2*ABS(t) + ABS(rt) + ABS(p));

                    int l2= 2*ABS(l) + (l<0);

                    int t2= 2*ABS(t) + (t<0);



                    put_symbol2(&s->c, b->state[context + 2], ABS(v)-1, context-4);

                    put_rac(&s->c, &b->state[0][16 + 1 + 3 + quant3bA[l2&0xFF] + 3*quant3bA[t2&0xFF]], v<0);

                }

            }

        }

    }

    return 0;

}

static int g722_decode_frame(AVCodecContext *avctx, void *data,

                             int *data_size, AVPacket *avpkt)

{

    G722Context *c = avctx->priv_data;

    int16_t *out_buf = data;

    int j, out_len = 0;

    const int skip = 8 - avctx->bits_per_coded_sample;

    const int16_t *quantizer_table = low_inv_quants[skip];

    GetBitContext gb;



    init_get_bits(&gb, avpkt->data, avpkt->size * 8);



    for (j = 0; j < avpkt->size; j++) {

        int ilow, ihigh, rlow, rhigh, dhigh;

        int xout1, xout2;



        ihigh = get_bits(&gb, 2);

        ilow = get_bits(&gb, 6 - skip);

        skip_bits(&gb, skip);



        rlow = av_clip((c->band[0].scale_factor * quantizer_table[ilow] >> 10)

                      + c->band[0].s_predictor, -16384, 16383);



        ff_g722_update_low_predictor(&c->band[0], ilow >> (2 - skip));



        dhigh = c->band[1].scale_factor * ff_g722_high_inv_quant[ihigh] >> 10;

        rhigh = av_clip(dhigh + c->band[1].s_predictor, -16384, 16383);



        ff_g722_update_high_predictor(&c->band[1], dhigh, ihigh);



        c->prev_samples[c->prev_samples_pos++] = rlow + rhigh;

        c->prev_samples[c->prev_samples_pos++] = rlow - rhigh;

        ff_g722_apply_qmf(c->prev_samples + c->prev_samples_pos - 24,

                          &xout1, &xout2);

        out_buf[out_len++] = av_clip_int16(xout1 >> 12);

        out_buf[out_len++] = av_clip_int16(xout2 >> 12);

        if (c->prev_samples_pos >= PREV_SAMPLES_BUF_SIZE) {

            memmove(c->prev_samples, c->prev_samples + c->prev_samples_pos - 22,

                    22 * sizeof(c->prev_samples[0]));

            c->prev_samples_pos = 22;

        }

    }

    *data_size = out_len << 1;

    return avpkt->size;

}

static av_cold int v410_decode_init(AVCodecContext *avctx)

{

    avctx->pix_fmt             = PIX_FMT_YUV444P10;

    avctx->bits_per_raw_sample = 10;



    if (avctx->width & 1) {

        av_log(avctx, AV_LOG_ERROR, "v410 requires width to be even.\n");

        return AVERROR_INVALIDDATA;

    }



    avctx->coded_frame = avcodec_alloc_frame();



    if (!avctx->coded_frame) {

