    }



    return 0;

}

static int alloc_picture(H264Context *h, Picture *pic)

{

    int i, ret = 0;



    av_assert0(!pic->f.data[0]);



    if (h->avctx->hwaccel) {

        const AVHWAccel *hwaccel = h->avctx->hwaccel;

        av_assert0(!pic->hwaccel_picture_private);

        if (hwaccel->priv_data_size) {

            pic->hwaccel_priv_buf = av_buffer_allocz(hwaccel->priv_data_size);

            if (!pic->hwaccel_priv_buf)

                return AVERROR(ENOMEM);

            pic->hwaccel_picture_private = pic->hwaccel_priv_buf->data;

        }

    }

    pic->tf.f = &pic->f;

    ret = ff_thread_get_buffer(h->avctx, &pic->tf, pic->reference ?

                                                   AV_GET_BUFFER_FLAG_REF : 0);

    if (ret < 0)

        goto fail;



    h->linesize   = pic->f.linesize[0];

    h->uvlinesize = pic->f.linesize[1];



    if (!h->qscale_table_pool) {

        ret = init_table_pools(h);

        if (ret < 0)

            goto fail;

    }



    pic->qscale_table_buf = av_buffer_pool_get(h->qscale_table_pool);

    pic->mb_type_buf      = av_buffer_pool_get(h->mb_type_pool);

    if (!pic->qscale_table_buf || !pic->mb_type_buf)

        goto fail;



    pic->mb_type      = (uint32_t*)pic->mb_type_buf->data + 2 * h->mb_stride + 1;

    pic->qscale_table = pic->qscale_table_buf->data + 2 * h->mb_stride + 1;



    for (i = 0; i < 2; i++) {

        pic->motion_val_buf[i] = av_buffer_pool_get(h->motion_val_pool);

        pic->ref_index_buf[i]  = av_buffer_pool_get(h->ref_index_pool);

        if (!pic->motion_val_buf[i] || !pic->ref_index_buf[i])

            goto fail;



        pic->motion_val[i] = (int16_t (*)[2])pic->motion_val_buf[i]->data + 4;

        pic->ref_index[i]  = pic->ref_index_buf[i]->data;

    }



    return 0;

fail:

    unref_picture(h, pic);

    return (ret < 0) ? ret : AVERROR(ENOMEM);

}

static int mov_read_dvc1(MOVContext *c, AVIOContext *pb, MOVAtom atom)

{

    AVStream *st;

    uint8_t profile_level;



    if (c->fc->nb_streams < 1)

        return 0;

    st = c->fc->streams[c->fc->nb_streams-1];



    if (atom.size >= (1<<28) || atom.size < 7)

        return AVERROR_INVALIDDATA;



    profile_level = avio_r8(pb);

    if ((profile_level & 0xf0) != 0xc0)

        return 0;



    av_free(st->codec->extradata);

    st->codec->extradata = av_mallocz(atom.size - 7 + FF_INPUT_BUFFER_PADDING_SIZE);

    if (!st->codec->extradata)

        return AVERROR(ENOMEM);

    st->codec->extradata_size = atom.size - 7;

    avio_seek(pb, 6, SEEK_CUR);

    avio_read(pb, st->codec->extradata, st->codec->extradata_size);

    return 0;

}

static void zero_remaining(unsigned int b, unsigned int b_max,

                           const unsigned int *div_blocks, int32_t *buf)

{

    unsigned int count = 0;



    while (b < b_max)

        count += div_blocks[b];



    if (count)

        memset(buf, 0, sizeof(*buf) * count);

}

static int push_samples(AVFilterContext *ctx, int nb_samples)

{

    AVFilterLink *outlink = ctx->outputs[0];

    LoopContext *s = ctx->priv;

    AVFrame *out;

    int ret, i = 0;



    while (s->loop != 0 && i < nb_samples) {

        out = ff_get_audio_buffer(outlink, FFMIN(nb_samples, s->nb_samples - s->current_sample));

        if (!out)

            return AVERROR(ENOMEM);

        ret = av_audio_fifo_peek_at(s->fifo, (void **)out->extended_data, out->nb_samples, s->current_sample);

        if (ret < 0)

            return ret;

        out->pts = s->pts;

        out->nb_samples = ret;

        s->pts += out->nb_samples;

        i += out->nb_samples;

        s->current_sample += out->nb_samples;



        ret = ff_filter_frame(outlink, out);

        if (ret < 0)

            return ret;



        if (s->current_sample >= s->nb_samples) {

            s->current_sample = 0;



            if (s->loop > 0)

                s->loop--;

        }

    }



    return ret;

}

static int img_set_parameters(AVFormatContext *s, AVFormatParameters *ap)

{

    VideoData *img = s->priv_data;

    AVStream *st;

    AVImageFormat *img_fmt;

    int i;



    /* find output image format */

    if (ap && ap->image_format) {

        img_fmt = ap->image_format;

    } else {

        img_fmt = guess_image_format(s->filename);

    }

    if (!img_fmt)

        return -1;



    if (s->nb_streams != 1)

        return -1;



    st = s->streams[0];

    /* we select the first matching format */

    for(i=0;i<PIX_FMT_NB;i++) {

        if (img_fmt->supported_pixel_formats & (1 << i))

            break;

    }

    if (i >= PIX_FMT_NB)

        return -1;

    img->img_fmt = img_fmt;

    img->pix_fmt = i;

    st->codec->pix_fmt = img->pix_fmt;

    return 0;

}

