int mm_support(void)

{

    int rval;

    int eax, ebx, ecx, edx;



    __asm__ __volatile__ (

                          /* See if CPUID instruction is supported ... */

                          /* ... Get copies of EFLAGS into eax and ecx */

                          "pushf\n\t"

                          "pop %0\n\t"

                          "movl %0, %1\n\t"



                          /* ... Toggle the ID bit in one copy and store */

                          /*     to the EFLAGS reg */

                          "xorl $0x200000, %0\n\t"

                          "push %0\n\t"

                          "popf\n\t"



                          /* ... Get the (hopefully modified) EFLAGS */

                          "pushf\n\t"

                          "pop %0\n\t"

                          : "=a" (eax), "=c" (ecx)

                          :

                          : "cc" 

                          );



    if (eax == ecx)

        return 0; /* CPUID not supported */



    cpuid(0, eax, ebx, ecx, edx);



    if (ebx == 0x756e6547 &&

        edx == 0x49656e69 &&

        ecx == 0x6c65746e) {



        /* intel */

    inteltest:

        cpuid(1, eax, ebx, ecx, edx);

        if ((edx & 0x00800000) == 0)

            return 0;

        rval = MM_MMX;

        if (edx & 0x02000000) 

            rval |= MM_MMXEXT | MM_SSE;

        if (edx & 0x04000000) 

            rval |= MM_SSE2;

        return rval;

    } else if (ebx == 0x68747541 &&

               edx == 0x69746e65 &&

               ecx == 0x444d4163) {

        /* AMD */

        cpuid(0x80000000, eax, ebx, ecx, edx);

        if ((unsigned)eax < 0x80000001)

            goto inteltest;

        cpuid(0x80000001, eax, ebx, ecx, edx);

        if ((edx & 0x00800000) == 0)

            return 0;

        rval = MM_MMX;

        if (edx & 0x80000000)

            rval |= MM_3DNOW;

        if (edx & 0x00400000)

            rval |= MM_MMXEXT;

        return rval;

    } else if (ebx == 0x746e6543 &&

               edx == 0x48727561 &&

               ecx == 0x736c7561) {  /*  "CentaurHauls" */

        /* VIA C3 */

        cpuid(0x80000000, eax, ebx, ecx, edx);

        if ((unsigned)eax < 0x80000001)

            goto inteltest;	

	cpuid(0x80000001, eax, ebx, ecx, edx);

	rval = 0;      

	if( edx & ( 1 << 31) )

	  rval |= MM_3DNOW;

	if( edx & ( 1 << 23) )

	  rval |= MM_MMX;

	if( edx & ( 1 << 24) )

	  rval |= MM_MMXEXT;

        if(rval==0)

            goto inteltest;

	return rval;

    } else if (ebx == 0x69727943 &&

               edx == 0x736e4978 &&

               ecx == 0x64616574) {

        /* Cyrix Section */

        /* See if extended CPUID level 80000001 is supported */

        /* The value of CPUID/80000001 for the 6x86MX is undefined

           according to the Cyrix CPU Detection Guide (Preliminary

           Rev. 1.01 table 1), so we'll check the value of eax for

           CPUID/0 to see if standard CPUID level 2 is supported.

           According to the table, the only CPU which supports level

           2 is also the only one which supports extended CPUID levels.

        */

        if (eax != 2) 

            goto inteltest;

        cpuid(0x80000001, eax, ebx, ecx, edx);

        if ((eax & 0x00800000) == 0)

            return 0;

        rval = MM_MMX;

        if (eax & 0x01000000)

            rval |= MM_MMXEXT;

        return rval;

    } else if (ebx == 0x756e6547 &&

               edx == 0x54656e69 &&

               ecx == 0x3638784d) {

        /* Tranmeta Crusoe */

        cpuid(0x80000000, eax, ebx, ecx, edx);

        if ((unsigned)eax < 0x80000001)

            return 0;

        cpuid(0x80000001, eax, ebx, ecx, edx);

        if ((edx & 0x00800000) == 0)

            return 0;

        return MM_MMX;

    } else {

        return 0;

    }

}

static void init_quantization(Jpeg2000EncoderContext *s)

{

    int compno, reslevelno, bandno;

    Jpeg2000QuantStyle  *qntsty = &s->qntsty;

    Jpeg2000CodingStyle *codsty = &s->codsty;



    for (compno = 0; compno < s->ncomponents; compno++){

        int gbandno = 0;

        for (reslevelno = 0; reslevelno < codsty->nreslevels; reslevelno++){

            int nbands, lev = codsty->nreslevels - reslevelno - 1;

            nbands = reslevelno ? 3 : 1;

            for (bandno = 0; bandno < nbands; bandno++, gbandno++){

                int expn, mant;



                if (codsty->transform == FF_DWT97){

                    int bandpos = bandno + (reslevelno>0),

                        ss = 81920000 / dwt_norms[0][bandpos][lev],

                        log = av_log2(ss);

                    mant = (11 - log < 0 ? ss >> log - 11 : ss << 11 - log) & 0x7ff;

                    expn = s->cbps[compno] - log + 13;

                } else

                    expn = ((bandno&2)>>1) + (reslevelno>0) + s->cbps[compno];



                qntsty->expn[gbandno] = expn;

                qntsty->mant[gbandno] = mant;

            }

        }

    }

}

static int sap_fetch_packet(AVFormatContext *s, AVPacket *pkt)

{

    struct SAPState *sap = s->priv_data;

    int fd = url_get_file_handle(sap->ann_fd);

    int n, ret;

    fd_set rfds;

    struct timeval tv;

    uint8_t recvbuf[1500];



    if (sap->eof)

        return AVERROR_EOF;



    while (1) {

        FD_ZERO(&rfds);

        FD_SET(fd, &rfds);

        tv.tv_sec = tv.tv_usec = 0;

        n = select(fd + 1, &rfds, NULL, NULL, &tv);

        if (n <= 0 || !FD_ISSET(fd, &rfds))

            break;

        ret = url_read(sap->ann_fd, recvbuf, sizeof(recvbuf));

        if (ret >= 8) {

            uint16_t hash = AV_RB16(&recvbuf[2]);

            /* Should ideally check the source IP address, too */

            if (recvbuf[0] & 0x04 && hash == sap->hash) {

                /* Stream deletion */

                sap->eof = 1;

                return AVERROR_EOF;

            }

        }

    }

    ret = av_read_frame(sap->sdp_ctx, pkt);

    if (ret < 0)

        return ret;

    if (s->ctx_flags & AVFMTCTX_NOHEADER) {

        while (sap->sdp_ctx->nb_streams > s->nb_streams) {

            int i = s->nb_streams;

            AVStream *st = av_new_stream(s, i);

            if (!st) {

                av_free_packet(pkt);

                return AVERROR(ENOMEM);

            }

            avcodec_copy_context(st->codec, sap->sdp_ctx->streams[i]->codec);

            st->time_base = sap->sdp_ctx->streams[i]->time_base;

        }

    }

    return ret;

}

int get_partial_buffer(ByteIOContext *s, unsigned char *buf, int size)
{
    int len;
    len = s->buf_end - s->buf_ptr;
    if (len == 0) {
        fill_buffer(s);
        len = s->buf_end - s->buf_ptr;
    }
    if (len > size)
        len = size;
    memcpy(buf, s->buf_ptr, len);
    s->buf_ptr += len;
    return len;
}

static int decode_cce(AACContext *ac, GetBitContext *gb, ChannelElement *che)

{

    int num_gain = 0;

    int c, g, sfb, ret;

    int sign;

    INTFLOAT scale;

    SingleChannelElement *sce = &che->ch[0];

    ChannelCoupling     *coup = &che->coup;



    coup->coupling_point = 2 * get_bits1(gb);

    coup->num_coupled = get_bits(gb, 3);

    for (c = 0; c <= coup->num_coupled; c++) {

        num_gain++;

        coup->type[c] = get_bits1(gb) ? TYPE_CPE : TYPE_SCE;

        coup->id_select[c] = get_bits(gb, 4);

        if (coup->type[c] == TYPE_CPE) {

            coup->ch_select[c] = get_bits(gb, 2);

            if (coup->ch_select[c] == 3)

                num_gain++;

        } else

            coup->ch_select[c] = 2;

    }

    coup->coupling_point += get_bits1(gb) || (coup->coupling_point >> 1);



    sign  = get_bits(gb, 1);

    scale = AAC_RENAME(cce_scale)[get_bits(gb, 2)];



    if ((ret = decode_ics(ac, sce, gb, 0, 0)))

        return ret;



    for (c = 0; c < num_gain; c++) {

        int idx  = 0;

        int cge  = 1;

        int gain = 0;

        INTFLOAT gain_cache = FIXR10(1.);

        if (c) {

            cge = coup->coupling_point == AFTER_IMDCT ? 1 : get_bits1(gb);

            gain = cge ? get_vlc2(gb, vlc_scalefactors.table, 7, 3) - 60: 0;

            gain_cache = GET_GAIN(scale, gain);

        }

        if (coup->coupling_point == AFTER_IMDCT) {

            coup->gain[c][0] = gain_cache;

        } else {

            for (g = 0; g < sce->ics.num_window_groups; g++) {

                for (sfb = 0; sfb < sce->ics.max_sfb; sfb++, idx++) {

                    if (sce->band_type[idx] != ZERO_BT) {

                        if (!cge) {

                            int t = get_vlc2(gb, vlc_scalefactors.table, 7, 3) - 60;

                            if (t) {

                                int s = 1;

                                t = gain += t;

                                if (sign) {

                                    s  -= 2 * (t & 0x1);

                                    t >>= 1;

                                }

                                gain_cache = GET_GAIN(scale, t) * s;

                            }

                        }

                        coup->gain[c][idx] = gain_cache;

                    }

                }

            }

        }

    }

    return 0;

}

void rgb16tobgr15(const uint8_t *src, uint8_t *dst, long src_size)

{

	long i;

	long num_pixels = src_size >> 1;



	for(i=0; i<num_pixels; i++)

	{

	    unsigned b,g,r;

	    register uint16_t rgb;

	    rgb = src[2*i];

	    r = rgb&0x1F;

	    g = (rgb&0x7E0)>>5;

	    b = (rgb&0xF800)>>11;

	    dst[2*i] = (b&0x1F) | ((g&0x1F)<<5) | ((r&0x1F)<<10);

	}

}

static inline void RENAME(uyvyToUV)(uint8_t *dstU, uint8_t *dstV, const uint8_t *src1, const uint8_t *src2, int width, uint32_t *unused)

{

#if COMPILE_TEMPLATE_MMX

    __asm__ volatile(

        "movq "MANGLE(bm01010101)", %%mm4           \n\t"

        "mov                    %0, %%"REG_a"       \n\t"

        "1:                                         \n\t"

        "movq    (%1, %%"REG_a",4), %%mm0           \n\t"

        "movq   8(%1, %%"REG_a",4), %%mm1           \n\t"

        "pand                %%mm4, %%mm0           \n\t"

        "pand                %%mm4, %%mm1           \n\t"

        "packuswb            %%mm1, %%mm0           \n\t"

        "movq                %%mm0, %%mm1           \n\t"

        "psrlw                  $8, %%mm0           \n\t"

        "pand                %%mm4, %%mm1           \n\t"

        "packuswb            %%mm0, %%mm0           \n\t"

        "packuswb            %%mm1, %%mm1           \n\t"

        "movd                %%mm0, (%3, %%"REG_a") \n\t"

        "movd                %%mm1, (%2, %%"REG_a") \n\t"

        "add                    $4, %%"REG_a"       \n\t"

        " js                    1b                  \n\t"

        : : "g" ((x86_reg)-width), "r" (src1+width*4), "r" (dstU+width), "r" (dstV+width)

        : "%"REG_a

    );

