static int multiple_resample(ResampleContext *c, AudioData *dst, int dst_size, AudioData *src, int src_size, int *consumed){

    int i, ret= -1;

    int av_unused mm_flags = av_get_cpu_flags();

    int need_emms = c->format == AV_SAMPLE_FMT_S16P && ARCH_X86_32 &&

                    (mm_flags & (AV_CPU_FLAG_MMX2 | AV_CPU_FLAG_SSE2)) == AV_CPU_FLAG_MMX2;

    int64_t max_src_size = (INT64_MAX/2 / c->phase_count) / c->src_incr;



    if (c->compensation_distance)

        dst_size = FFMIN(dst_size, c->compensation_distance);

    src_size = FFMIN(src_size, max_src_size);



    for(i=0; i<dst->ch_count; i++){

        ret= swri_resample(c, dst->ch[i], src->ch[i],

                           consumed, src_size, dst_size, i+1==dst->ch_count);

    }

    if(need_emms)

        emms_c();



    if (c->compensation_distance) {

        c->compensation_distance -= ret;

        if (!c->compensation_distance) {

            c->dst_incr     = c->ideal_dst_incr;

            c->dst_incr_div = c->dst_incr / c->src_incr;

            c->dst_incr_mod = c->dst_incr % c->src_incr;

        }

    }



    return ret;

}

static int try_decode_frame(AVStream *st, AVPacket *avpkt)

{

    int16_t *samples;

    AVCodec *codec;

    int got_picture, data_size, ret=0;

    AVFrame picture;



    if(!st->codec->codec){

        codec = avcodec_find_decoder(st->codec->codec_id);

        if (!codec)

            return -1;

        ret = avcodec_open(st->codec, codec);

        if (ret < 0)

            return ret;

    }



    if(!has_codec_parameters(st->codec)){

        switch(st->codec->codec_type) {

        case CODEC_TYPE_VIDEO:


            ret = avcodec_decode_video2(st->codec, &picture,

                                        &got_picture, avpkt);

            break;

        case CODEC_TYPE_AUDIO:

            data_size = FFMAX(avpkt->size, AVCODEC_MAX_AUDIO_FRAME_SIZE);

            samples = av_malloc(data_size);

            if (!samples)

                goto fail;

            ret = avcodec_decode_audio3(st->codec, samples,

                                        &data_size, avpkt);

            av_free(samples);

            break;

        default:

            break;

        }

    }

 fail:

    return ret;

}

int attribute_align_arg avcodec_decode_video2(AVCodecContext *avctx, AVFrame *picture,

                         int *got_picture_ptr,

                         AVPacket *avpkt)

{

    int ret;



    *got_picture_ptr= 0;

    if((avctx->coded_width||avctx->coded_height) && av_image_check_size(avctx->coded_width, avctx->coded_height, 0, avctx))

        return -1;



    if((avctx->codec->capabilities & CODEC_CAP_DELAY) || avpkt->size || (avctx->active_thread_type&FF_THREAD_FRAME)){

        av_packet_split_side_data(avpkt);

        apply_param_change(avctx, avpkt);

        avctx->pkt = avpkt;

        if (HAVE_THREADS && avctx->active_thread_type&FF_THREAD_FRAME)

             ret = ff_thread_decode_frame(avctx, picture, got_picture_ptr,

                                          avpkt);

        else {

            ret = avctx->codec->decode(avctx, picture, got_picture_ptr,

                              avpkt);

            picture->pkt_dts= avpkt->dts;



            if(!avctx->has_b_frames){

            picture->pkt_pos= avpkt->pos;

            }

            //FIXME these should be under if(!avctx->has_b_frames)

            if (!picture->sample_aspect_ratio.num)

                picture->sample_aspect_ratio = avctx->sample_aspect_ratio;

            if (!picture->width)

                picture->width = avctx->width;

            if (!picture->height)

                picture->height = avctx->height;

            if (picture->format == PIX_FMT_NONE)

                picture->format = avctx->pix_fmt;

        }



        emms_c(); //needed to avoid an emms_c() call before every return;





        if (*got_picture_ptr){

            avctx->frame_number++;

            picture->best_effort_timestamp = guess_correct_pts(avctx,

                                                            picture->pkt_pts,

                                                            picture->pkt_dts);

        }

    }else

        ret= 0;



    return ret;

}

static void IMLT(float *pInput, float *pOutput, int odd_band)

{

    int     i;



    if (odd_band) {

        /**

        * Reverse the odd bands before IMDCT, this is an effect of the QMF transform

        * or it gives better compression to do it this way.

        * FIXME: It should be possible to handle this in ff_imdct_calc

        * for that to happen a modification of the prerotation step of

        * all SIMD code and C code is needed.

        * Or fix the functions before so they generate a pre reversed spectrum.

        */



        for (i=0; i<128; i++)

            FFSWAP(float, pInput[i], pInput[255-i]);

    }



    ff_imdct_calc(&mdct_ctx,pOutput,pInput);



    /* Perform windowing on the output. */

    dsp.vector_fmul(pOutput,mdct_window,512);



}

static void mxf_write_generic_sound_common(AVFormatContext *s, AVStream *st, const UID key, unsigned size)

{

    AVIOContext *pb = s->pb;



    mxf_write_generic_desc(s, st, key, size+5+12+8+8);



    // audio locked

    mxf_write_local_tag(pb, 1, 0x3D02);

    avio_w8(pb, 1);



    // write audio sampling rate

    mxf_write_local_tag(pb, 8, 0x3D03);

    avio_wb32(pb, st->codec->sample_rate);

    avio_wb32(pb, 1);



    mxf_write_local_tag(pb, 4, 0x3D07);

    avio_wb32(pb, st->codec->channels);



