static void revert_cdlms(WmallDecodeCtx *s, int tile_size)

{

    int icoef, ich;

    int32_t pred, channel_coeff;

    int ilms, num_lms;



    for (ich = 0; ich < s->num_channels; ich++) {

        if (!s->is_channel_coded[ich])

            continue;

        for (icoef = 0; icoef < tile_size; icoef++) {

            num_lms = s->cdlms_ttl[ich];

            channel_coeff = s->channel_residues[ich][icoef];

            if (icoef == s->transient_pos[ich]) {

                s->transient[ich] = 1;

                use_high_update_speed(s, ich);

            }

            for (ilms = num_lms; ilms >= 0; ilms--) {

                pred = lms_predict(s, ich, ilms);

                channel_coeff += pred;

                lms_update(s, ich, ilms, channel_coeff, pred);

            }

            if (s->transient[ich]) {

                --s->channel[ich].transient_counter;

                if(!s->channel[ich].transient_counter)

                    use_normal_update_speed(s, ich);

            }

            s->channel_coeffs[ich][icoef] = channel_coeff;

        }

    }

}

static void decode_mb_b(AVSContext *h, enum cavs_mb mb_type) {

    int block;

    enum cavs_sub_mb sub_type[4];

    int flags;



    ff_cavs_init_mb(h);



    /* reset all MVs */

    h->mv[MV_FWD_X0] = ff_cavs_dir_mv;

    set_mvs(&h->mv[MV_FWD_X0], BLK_16X16);

    h->mv[MV_BWD_X0] = ff_cavs_dir_mv;

    set_mvs(&h->mv[MV_BWD_X0], BLK_16X16);

    switch(mb_type) {

    case B_SKIP:

    case B_DIRECT:

        if(!h->col_type_base[h->mbidx]) {

            /* intra MB at co-location, do in-plane prediction */

            ff_cavs_mv(h, MV_FWD_X0, MV_FWD_C2, MV_PRED_BSKIP, BLK_16X16, 1);

            ff_cavs_mv(h, MV_BWD_X0, MV_BWD_C2, MV_PRED_BSKIP, BLK_16X16, 0);

        } else

            /* direct prediction from co-located P MB, block-wise */

            for(block=0;block<4;block++)

                mv_pred_direct(h,&h->mv[mv_scan[block]],

                                 &h->col_mv[h->mbidx*4 + block]);

        break;

    case B_FWD_16X16:

        ff_cavs_mv(h, MV_FWD_X0, MV_FWD_C2, MV_PRED_MEDIAN, BLK_16X16, 1);

        break;

    case B_SYM_16X16:

        ff_cavs_mv(h, MV_FWD_X0, MV_FWD_C2, MV_PRED_MEDIAN, BLK_16X16, 1);

        mv_pred_sym(h, &h->mv[MV_FWD_X0], BLK_16X16);

        break;

    case B_BWD_16X16:

        ff_cavs_mv(h, MV_BWD_X0, MV_BWD_C2, MV_PRED_MEDIAN, BLK_16X16, 0);

        break;

    case B_8X8:

        for(block=0;block<4;block++)

            sub_type[block] = get_bits(&h->s.gb,2);

        for(block=0;block<4;block++) {

            switch(sub_type[block]) {

            case B_SUB_DIRECT:

                if(!h->col_type_base[h->mbidx]) {

                    /* intra MB at co-location, do in-plane prediction */

                    ff_cavs_mv(h, mv_scan[block], mv_scan[block]-3,

                            MV_PRED_BSKIP, BLK_8X8, 1);

                    ff_cavs_mv(h, mv_scan[block]+MV_BWD_OFFS,

                            mv_scan[block]-3+MV_BWD_OFFS,

                            MV_PRED_BSKIP, BLK_8X8, 0);

                } else

                    mv_pred_direct(h,&h->mv[mv_scan[block]],

                                   &h->col_mv[h->mbidx*4 + block]);

                break;

            case B_SUB_FWD:

                ff_cavs_mv(h, mv_scan[block], mv_scan[block]-3,

                        MV_PRED_MEDIAN, BLK_8X8, 1);

                break;

            case B_SUB_SYM:

                ff_cavs_mv(h, mv_scan[block], mv_scan[block]-3,

                        MV_PRED_MEDIAN, BLK_8X8, 1);

                mv_pred_sym(h, &h->mv[mv_scan[block]], BLK_8X8);

                break;

            }

        }

        for(block=0;block<4;block++) {

            if(sub_type[block] == B_SUB_BWD)

                ff_cavs_mv(h, mv_scan[block]+MV_BWD_OFFS,

                        mv_scan[block]+MV_BWD_OFFS-3,

                        MV_PRED_MEDIAN, BLK_8X8, 0);

        }

        break;

    default:

        av_assert2((mb_type > B_SYM_16X16) && (mb_type < B_8X8));

        flags = ff_cavs_partition_flags[mb_type];

        if(mb_type & 1) { /* 16x8 macroblock types */

            if(flags & FWD0)

                ff_cavs_mv(h, MV_FWD_X0, MV_FWD_C2, MV_PRED_TOP,  BLK_16X8, 1);

            if(flags & SYM0)

                mv_pred_sym(h, &h->mv[MV_FWD_X0], BLK_16X8);

            if(flags & FWD1)

                ff_cavs_mv(h, MV_FWD_X2, MV_FWD_A1, MV_PRED_LEFT, BLK_16X8, 1);

            if(flags & SYM1)

                mv_pred_sym(h, &h->mv[MV_FWD_X2], BLK_16X8);

            if(flags & BWD0)

                ff_cavs_mv(h, MV_BWD_X0, MV_BWD_C2, MV_PRED_TOP,  BLK_16X8, 0);

            if(flags & BWD1)

                ff_cavs_mv(h, MV_BWD_X2, MV_BWD_A1, MV_PRED_LEFT, BLK_16X8, 0);

        } else {          /* 8x16 macroblock types */

            if(flags & FWD0)

                ff_cavs_mv(h, MV_FWD_X0, MV_FWD_B3, MV_PRED_LEFT, BLK_8X16, 1);

            if(flags & SYM0)

                mv_pred_sym(h, &h->mv[MV_FWD_X0], BLK_8X16);

            if(flags & FWD1)

                ff_cavs_mv(h,MV_FWD_X1,MV_FWD_C2,MV_PRED_TOPRIGHT,BLK_8X16,1);

            if(flags & SYM1)

                mv_pred_sym(h, &h->mv[MV_FWD_X1], BLK_8X16);

            if(flags & BWD0)

                ff_cavs_mv(h, MV_BWD_X0, MV_BWD_B3, MV_PRED_LEFT, BLK_8X16, 0);

            if(flags & BWD1)

                ff_cavs_mv(h,MV_BWD_X1,MV_BWD_C2,MV_PRED_TOPRIGHT,BLK_8X16,0);

        }

    }

    ff_cavs_inter(h, mb_type);

    set_intra_mode_default(h);

    if(mb_type != B_SKIP)

        decode_residual_inter(h);

    ff_cavs_filter(h,mb_type);

}

static int transcode_audio(InputStream *ist, AVPacket *pkt, int *got_output)

{

    AVFrame *decoded_frame;

    AVCodecContext *avctx = ist->st->codec;

    int bps = av_get_bytes_per_sample(ist->st->codec->sample_fmt);

    int i, ret;



    if (!ist->decoded_frame && !(ist->decoded_frame = avcodec_alloc_frame()))

        return AVERROR(ENOMEM);

    else

        avcodec_get_frame_defaults(ist->decoded_frame);

    decoded_frame = ist->decoded_frame;



    ret = avcodec_decode_audio4(avctx, decoded_frame, got_output, pkt);

    if (ret < 0) {

        return ret;

    }



    if (!*got_output) {

        /* no audio frame */

        return ret;

    }



    /* if the decoder provides a pts, use it instead of the last packet pts.

       the decoder could be delaying output by a packet or more. */

    if (decoded_frame->pts != AV_NOPTS_VALUE)

        ist->next_dts = decoded_frame->pts;



    /* increment next_dts to use for the case where the input stream does not

       have timestamps or there are multiple frames in the packet */

    ist->next_dts += ((int64_t)AV_TIME_BASE * decoded_frame->nb_samples) /

                     avctx->sample_rate;



    // preprocess audio (volume)

    if (audio_volume != 256) {

        int decoded_data_size = decoded_frame->nb_samples * avctx->channels * bps;

        void *samples = decoded_frame->data[0];

        switch (avctx->sample_fmt) {

        case AV_SAMPLE_FMT_U8:

        {

            uint8_t *volp = samples;

            for (i = 0; i < (decoded_data_size / sizeof(*volp)); i++) {

                int v = (((*volp - 128) * audio_volume + 128) >> 8) + 128;

                *volp++ = av_clip_uint8(v);

            }

            break;

        }

        case AV_SAMPLE_FMT_S16:

        {

            int16_t *volp = samples;

            for (i = 0; i < (decoded_data_size / sizeof(*volp)); i++) {

                int v = ((*volp) * audio_volume + 128) >> 8;

                *volp++ = av_clip_int16(v);

            }

            break;

        }

        case AV_SAMPLE_FMT_S32:

        {

            int32_t *volp = samples;

            for (i = 0; i < (decoded_data_size / sizeof(*volp)); i++) {

                int64_t v = (((int64_t)*volp * audio_volume + 128) >> 8);

                *volp++ = av_clipl_int32(v);

            }

            break;

        }

        case AV_SAMPLE_FMT_FLT:

        {

            float *volp = samples;

            float scale = audio_volume / 256.f;

            for (i = 0; i < (decoded_data_size / sizeof(*volp)); i++) {

                *volp++ *= scale;

            }

            break;

        }

        case AV_SAMPLE_FMT_DBL:

        {

            double *volp = samples;

            double scale = audio_volume / 256.;

            for (i = 0; i < (decoded_data_size / sizeof(*volp)); i++) {

                *volp++ *= scale;

            }

            break;

        }

        default:

            av_log(NULL, AV_LOG_FATAL,

                   "Audio volume adjustment on sample format %s is not supported.\n",

                   av_get_sample_fmt_name(ist->st->codec->sample_fmt));

            exit_program(1);

        }

    }



    rate_emu_sleep(ist);



    for (i = 0; i < nb_output_streams; i++) {

        OutputStream *ost = output_streams[i];



        if (!check_output_constraints(ist, ost) || !ost->encoding_needed)

            continue;

        do_audio_out(output_files[ost->file_index]->ctx, ost, ist, decoded_frame);

    }



    return ret;

}

static int opt_preset(const char *opt, const char *arg)

{

    FILE *f=NULL;

    char tmp[1000], tmp2[1000], line[1000];

    int i;

    const char *base[3]= { getenv("HOME"),

                           "/usr/local/share",

                           "/usr/share",

                         };



    for(i=!base[0]; i<3 && !f; i++){

        snprintf(tmp, sizeof(tmp), "%s/%sffmpeg/%s.ffpreset", base[i], i ? "" : ".", arg);

        f= fopen(tmp, "r");

        if(!f){

            char *codec_name= *opt == 'v' ? video_codec_name :

                              *opt == 'a' ? audio_codec_name :

                                            subtitle_codec_name;

              snprintf(tmp, sizeof(tmp), "%s/%sffmpeg/%s-%s.ffpreset", base[i],  i ? "" : ".", codec_name, arg);

            f= fopen(tmp, "r");

        }

    }

    if(!f && ((arg[0]=='.' && arg[1]=='/') || arg[0]=='/')){

        f= fopen(arg, "r");

    }



    if(!f){

        fprintf(stderr, "Preset file not found\n");

        av_exit(1);

    }



    while(!feof(f)){

        int e= fscanf(f, "%999[^\n]\n", line) - 1;

        if(line[0] == '#' && !e)

            continue;

        e|= sscanf(line, "%999[^=]=%999[^\n]\n", tmp, tmp2) - 2;

        if(e){

            fprintf(stderr, "Preset file invalid\n");

            av_exit(1);

        }

        if(!strcmp(tmp, "acodec")){

            opt_audio_codec(tmp2);

        }else if(!strcmp(tmp, "vcodec")){

            opt_video_codec(tmp2);

        }else if(!strcmp(tmp, "scodec")){

            opt_subtitle_codec(tmp2);

        }else

            opt_default(tmp, tmp2);

    }



    fclose(f);



    return 0;

}

static void codebook_trellis_rate(AACEncContext *s, SingleChannelElement *sce,

                                  int win, int group_len, const float lambda)

{

    BandCodingPath path[120][12];

    int w, swb, cb, start, size;

    int i, j;

    const int max_sfb  = sce->ics.max_sfb;

    const int run_bits = sce->ics.num_windows == 1 ? 5 : 3;

    const int run_esc  = (1 << run_bits) - 1;

    int idx, ppos, count;

    int stackrun[120], stackcb[120], stack_len;

    float next_minbits = INFINITY;

    int next_mincb = 0;



    abs_pow34_v(s->scoefs, sce->coeffs, 1024);

    start = win*128;

    for (cb = 0; cb < 12; cb++) {

        path[0][cb].cost     = run_bits+4;

        path[0][cb].prev_idx = -1;

        path[0][cb].run      = 0;

    }

    for (swb = 0; swb < max_sfb; swb++) {

        size = sce->ics.swb_sizes[swb];

        if (sce->zeroes[win*16 + swb]) {

            float cost_stay_here = path[swb][0].cost;

            float cost_get_here  = next_minbits + run_bits + 4;

            if (   run_value_bits[sce->ics.num_windows == 8][path[swb][0].run]

                != run_value_bits[sce->ics.num_windows == 8][path[swb][0].run+1])

                cost_stay_here += run_bits;

            if (cost_get_here < cost_stay_here) {

                path[swb+1][0].prev_idx = next_mincb;

                path[swb+1][0].cost     = cost_get_here;

                path[swb+1][0].run      = 1;

            } else {

                path[swb+1][0].prev_idx = 0;

                path[swb+1][0].cost     = cost_stay_here;

                path[swb+1][0].run      = path[swb][0].run + 1;

            }

            next_minbits = path[swb+1][0].cost;

            next_mincb = 0;

            for (cb = 1; cb < 12; cb++) {

                path[swb+1][cb].cost = 61450;

                path[swb+1][cb].prev_idx = -1;

                path[swb+1][cb].run = 0;

            }

        } else {

            float minbits = next_minbits;

            int mincb = next_mincb;

            int startcb = sce->band_type[win*16+swb];

            next_minbits = INFINITY;

            next_mincb = 0;

            for (cb = 0; cb < startcb; cb++) {

                path[swb+1][cb].cost = 61450;

                path[swb+1][cb].prev_idx = -1;

                path[swb+1][cb].run = 0;

            }

            for (cb = startcb; cb < 12; cb++) {

                float cost_stay_here, cost_get_here;

                float bits = 0.0f;

                for (w = 0; w < group_len; w++) {

                    bits += quantize_band_cost(s, sce->coeffs + start + w*128,

                                               s->scoefs + start + w*128, size,

                                               sce->sf_idx[(win+w)*16+swb], cb,

                                               0, INFINITY, NULL);

                }

                cost_stay_here = path[swb][cb].cost + bits;

                cost_get_here  = minbits            + bits + run_bits + 4;

                if (   run_value_bits[sce->ics.num_windows == 8][path[swb][cb].run]

                    != run_value_bits[sce->ics.num_windows == 8][path[swb][cb].run+1])

                    cost_stay_here += run_bits;

                if (cost_get_here < cost_stay_here) {

                    path[swb+1][cb].prev_idx = mincb;

                    path[swb+1][cb].cost     = cost_get_here;

                    path[swb+1][cb].run      = 1;

                } else {

                    path[swb+1][cb].prev_idx = cb;

                    path[swb+1][cb].cost     = cost_stay_here;

                    path[swb+1][cb].run      = path[swb][cb].run + 1;

                }

                if (path[swb+1][cb].cost < next_minbits) {

                    next_minbits = path[swb+1][cb].cost;

                    next_mincb = cb;

                }

            }

        }

        start += sce->ics.swb_sizes[swb];

    }



    //convert resulting path from backward-linked list

    stack_len = 0;

    idx       = 0;

    for (cb = 1; cb < 12; cb++)

        if (path[max_sfb][cb].cost < path[max_sfb][idx].cost)

            idx = cb;

    ppos = max_sfb;

    while (ppos > 0) {

        av_assert1(idx >= 0);

        cb = idx;

        stackrun[stack_len] = path[ppos][cb].run;

        stackcb [stack_len] = cb;

        idx = path[ppos-path[ppos][cb].run+1][cb].prev_idx;

        ppos -= path[ppos][cb].run;

        stack_len++;

    }

    //perform actual band info encoding

    start = 0;

    for (i = stack_len - 1; i >= 0; i--) {

        put_bits(&s->pb, 4, stackcb[i]);

        count = stackrun[i];

        memset(sce->zeroes + win*16 + start, !stackcb[i], count);

        //XXX: memset when band_type is also uint8_t

        for (j = 0; j < count; j++) {

            sce->band_type[win*16 + start] =  stackcb[i];

            start++;

        }

        while (count >= run_esc) {

            put_bits(&s->pb, run_bits, run_esc);

            count -= run_esc;

        }

        put_bits(&s->pb, run_bits, count);

    }

}

