int ffio_ensure_seekback(AVIOContext *s, int64_t buf_size)

{

    uint8_t *buffer;

    int max_buffer_size = s->max_packet_size ?

                          s->max_packet_size : IO_BUFFER_SIZE;

    int filled = s->buf_end - s->buffer;

    ptrdiff_t checksum_ptr_offset = s->checksum_ptr ? s->checksum_ptr - s->buffer : -1;



    buf_size += s->buf_ptr - s->buffer + max_buffer_size;



    if (buf_size < filled || s->seekable || !s->read_packet)

        return 0;

    av_assert0(!s->write_flag);



    buffer = av_malloc(buf_size);

    if (!buffer)

        return AVERROR(ENOMEM);



    memcpy(buffer, s->buffer, filled);

    av_free(s->buffer);

    s->buf_ptr = buffer + (s->buf_ptr - s->buffer);

    s->buf_end = buffer + (s->buf_end - s->buffer);

    s->buffer = buffer;

    s->buffer_size = buf_size;



    return 0;

}

static int decode_frame(WmallDecodeCtx *s)

{

    GetBitContext* gb = &s->gb;

    int more_frames = 0;

    int len = 0;

    int i;



    /** check for potential output buffer overflow */

    if (s->num_channels * s->samples_per_frame > s->samples_end - s->samples) {

        /** return an error if no frame could be decoded at all */

        av_log(s->avctx, AV_LOG_ERROR,

               "not enough space for the output samples\n");

        s->packet_loss = 1;

        return 0;

    }



    /** get frame length */

    if (s->len_prefix)

        len = get_bits(gb, s->log2_frame_size);



    /** decode tile information */

    if (decode_tilehdr(s)) {

        s->packet_loss = 1;

        return 0;

    }



    /** read drc info */

    if (s->dynamic_range_compression) {

        s->drc_gain = get_bits(gb, 8);

    }



    /** no idea what these are for, might be the number of samples

        that need to be skipped at the beginning or end of a stream */

    if (get_bits1(gb)) {

        int skip;



        /** usually true for the first frame */

        if (get_bits1(gb)) {

            skip = get_bits(gb, av_log2(s->samples_per_frame * 2));

            dprintf(s->avctx, "start skip: %i\n", skip);

        }



        /** sometimes true for the last frame */

        if (get_bits1(gb)) {

            skip = get_bits(gb, av_log2(s->samples_per_frame * 2));

            dprintf(s->avctx, "end skip: %i\n", skip);

        }



    }



    /** reset subframe states */

    s->parsed_all_subframes = 0;

    for (i = 0; i < s->num_channels; i++) {

        s->channel[i].decoded_samples = 0;

        s->channel[i].cur_subframe    = 0;

        s->channel[i].reuse_sf        = 0;

    }



    /** decode all subframes */

    while (!s->parsed_all_subframes) {

        if (decode_subframe(s) < 0) {

            s->packet_loss = 1;

            return 0;

        }

    }



    dprintf(s->avctx, "Frame done\n");



    if (s->skip_frame) {

        s->skip_frame = 0;

    } else

        s->samples += s->num_channels * s->samples_per_frame;



    if (s->len_prefix) {

        if (len != (get_bits_count(gb) - s->frame_offset) + 2) {

            /** FIXME: not sure if this is always an error */

            av_log(s->avctx, AV_LOG_ERROR,

                   "frame[%i] would have to skip %i bits\n", s->frame_num,

                   len - (get_bits_count(gb) - s->frame_offset) - 1);

            s->packet_loss = 1;

            return 0;

        }



        /** skip the rest of the frame data */

        skip_bits_long(gb, len - (get_bits_count(gb) - s->frame_offset) - 1);

    } else {

/*

        while (get_bits_count(gb) < s->num_saved_bits && get_bits1(gb) == 0) {

	    dprintf(s->avctx, "skip1\n");

        }

*/

    }



    /** decode trailer bit */

    more_frames = get_bits1(gb);

    ++s->frame_num;

    return more_frames;

}

static void rv34_idct_dc_add_c(uint8_t *dst, int stride, int dc)

{

    const uint8_t *cm = ff_cropTbl + MAX_NEG_CROP;

    int i, j;



    cm += (13*13*dc + 0x200) >> 10;



    for (i = 0; i < 4; i++)

    {

        for (j = 0; j < 4; j++)

            dst[j] = cm[ dst[j] ];



        dst += stride;

    }

}

static void pre_process_video_frame(InputStream *ist, AVPicture *picture, void **bufp)

{

    AVCodecContext *dec;

    AVPicture *picture2;

    AVPicture picture_tmp;

    uint8_t *buf = 0;



    dec = ist->st->codec;



    /* deinterlace : must be done before any resize */

    if (FF_API_DEINTERLACE && do_deinterlace) {

        int size;



        /* create temporary picture */

        size = avpicture_get_size(dec->pix_fmt, dec->width, dec->height);

        if (size < 0)

            return;

        buf  = av_malloc(size);

        if (!buf)

            return;



        picture2 = &picture_tmp;

        avpicture_fill(picture2, buf, dec->pix_fmt, dec->width, dec->height);



        if (avpicture_deinterlace(picture2, picture,

                                 dec->pix_fmt, dec->width, dec->height) < 0) {

            /* if error, do not deinterlace */

            av_log(NULL, AV_LOG_WARNING, "Deinterlacing failed\n");

            av_free(buf);

            buf = NULL;

            picture2 = picture;

        }

    } else {

        picture2 = picture;

    }



    if (picture != picture2)

        *picture = *picture2;

    *bufp = buf;

}

static int vc1_decode_p_mb_intfi(VC1Context *v)

{

    MpegEncContext *s = &v->s;

    GetBitContext *gb = &s->gb;

    int i;

    int mb_pos = s->mb_x + s->mb_y * s->mb_stride;

    int cbp = 0; /* cbp decoding stuff */

    int mqdiff, mquant; /* MB quantization */

    int ttmb = v->ttfrm; /* MB Transform type */



    int mb_has_coeffs = 1; /* last_flag */

    int dmv_x, dmv_y; /* Differential MV components */

    int val; /* temp values */

    int first_block = 1;

    int dst_idx, off;

    int pred_flag = 0;

    int block_cbp = 0, pat, block_tt = 0;

    int idx_mbmode = 0;



    mquant = v->pq; /* Lossy initialization */



    idx_mbmode = get_vlc2(gb, v->mbmode_vlc->table, VC1_IF_MBMODE_VLC_BITS, 2);

    if (idx_mbmode <= 1) { // intra MB

        v->is_intra[s->mb_x] = 0x3f; // Set the bitfield to all 1.

        s->mb_intra          = 1;

        s->current_picture.motion_val[1][s->block_index[0] + v->blocks_off][0] = 0;

        s->current_picture.motion_val[1][s->block_index[0] + v->blocks_off][1] = 0;

        s->current_picture.mb_type[mb_pos + v->mb_off] = MB_TYPE_INTRA;

        GET_MQUANT();

        s->current_picture.qscale_table[mb_pos] = mquant;

        /* Set DC scale - y and c use the same (not sure if necessary here) */

        s->y_dc_scale = s->y_dc_scale_table[mquant];

        s->c_dc_scale = s->c_dc_scale_table[mquant];

        v->s.ac_pred  = v->acpred_plane[mb_pos] = get_bits1(gb);

        mb_has_coeffs = idx_mbmode & 1;

        if (mb_has_coeffs)

            cbp = 1 + get_vlc2(&v->s.gb, v->cbpcy_vlc->table, VC1_ICBPCY_VLC_BITS, 2);

        dst_idx = 0;

        for (i = 0; i < 6; i++) {

            v->a_avail = v->c_avail          = 0;

            v->mb_type[0][s->block_index[i]] = 1;

            s->dc_val[0][s->block_index[i]]  = 0;

            dst_idx += i >> 2;

            val = ((cbp >> (5 - i)) & 1);

            if (i == 2 || i == 3 || !s->first_slice_line)

                v->a_avail = v->mb_type[0][s->block_index[i] - s->block_wrap[i]];

            if (i == 1 || i == 3 || s->mb_x)

                v->c_avail = v->mb_type[0][s->block_index[i] - 1];



            vc1_decode_intra_block(v, s->block[i], i, val, mquant,

                                   (i & 4) ? v->codingset2 : v->codingset);

            if ((i>3) && (s->flags & CODEC_FLAG_GRAY))

                continue;

            v->vc1dsp.vc1_inv_trans_8x8(s->block[i]);

            off  = (i & 4) ? 0 : ((i & 1) * 8 + (i & 2) * 4 * s->linesize);

            s->idsp.put_signed_pixels_clamped(s->block[i],

                                              s->dest[dst_idx] + off,

                                              (i & 4) ? s->uvlinesize

                                                      : s->linesize);

            // TODO: loop filter

        }

    } else {

        s->mb_intra = v->is_intra[s->mb_x] = 0;

        s->current_picture.mb_type[mb_pos + v->mb_off] = MB_TYPE_16x16;

        for (i = 0; i < 6; i++) v->mb_type[0][s->block_index[i]] = 0;

        if (idx_mbmode <= 5) { // 1-MV

            dmv_x = dmv_y = pred_flag = 0;

            if (idx_mbmode & 1) {

                get_mvdata_interlaced(v, &dmv_x, &dmv_y, &pred_flag);

            }

            ff_vc1_pred_mv(v, 0, dmv_x, dmv_y, 1, v->range_x, v->range_y, v->mb_type[0], pred_flag, 0);

            ff_vc1_mc_1mv(v, 0);

            mb_has_coeffs = !(idx_mbmode & 2);

        } else { // 4-MV

            v->fourmvbp = get_vlc2(gb, v->fourmvbp_vlc->table, VC1_4MV_BLOCK_PATTERN_VLC_BITS, 1);

            for (i = 0; i < 6; i++) {

                if (i < 4) {

                    dmv_x = dmv_y = pred_flag = 0;

                    val   = ((v->fourmvbp >> (3 - i)) & 1);

                    if (val) {

                        get_mvdata_interlaced(v, &dmv_x, &dmv_y, &pred_flag);

                    }

                    ff_vc1_pred_mv(v, i, dmv_x, dmv_y, 0, v->range_x, v->range_y, v->mb_type[0], pred_flag, 0);

                    ff_vc1_mc_4mv_luma(v, i, 0, 0);

                } else if (i == 4)

                    ff_vc1_mc_4mv_chroma(v, 0);

            }

            mb_has_coeffs = idx_mbmode & 1;

        }

        if (mb_has_coeffs)

            cbp = 1 + get_vlc2(&v->s.gb, v->cbpcy_vlc->table, VC1_CBPCY_P_VLC_BITS, 2);

        if (cbp) {

            GET_MQUANT();

        }

        s->current_picture.qscale_table[mb_pos] = mquant;

        if (!v->ttmbf && cbp) {

            ttmb = get_vlc2(gb, ff_vc1_ttmb_vlc[v->tt_index].table, VC1_TTMB_VLC_BITS, 2);

        }

        dst_idx = 0;

        for (i = 0; i < 6; i++) {

            s->dc_val[0][s->block_index[i]] = 0;

            dst_idx += i >> 2;

            val = ((cbp >> (5 - i)) & 1);

            off = (i & 4) ? 0 : (i & 1) * 8 + (i & 2) * 4 * s->linesize;

            if (val) {

                pat = vc1_decode_p_block(v, s->block[i], i, mquant, ttmb,

                                         first_block, s->dest[dst_idx] + off,

                                         (i & 4) ? s->uvlinesize : s->linesize,

                                         (i & 4) && (s->flags & CODEC_FLAG_GRAY),

                                         &block_tt);

                block_cbp |= pat << (i << 2);

                if (!v->ttmbf && ttmb < 8) ttmb = -1;

                first_block = 0;

            }

        }

    }

    if (s->mb_x == s->mb_width - 1)

        memmove(v->is_intra_base, v->is_intra, sizeof(v->is_intra_base[0]) * s->mb_stride);

    return 0;

}

static uint8_t get_tlm(Jpeg2000DecoderContext *s, int n)

{

    uint8_t Stlm, ST, SP, tile_tlm, i;

    bytestream_get_byte(&s->buf);               /* Ztlm: skipped */

    Stlm = bytestream_get_byte(&s->buf);



    // too complex ? ST = ((Stlm >> 4) & 0x01) + ((Stlm >> 4) & 0x02);

    ST = (Stlm >> 4) & 0x03;

    // TODO: Manage case of ST = 0b11 --> raise error

    SP       = (Stlm >> 6) & 0x01;

    tile_tlm = (n - 4) / ((SP + 1) * 2 + ST);

    for (i = 0; i < tile_tlm; i++) {

        switch (ST) {

        case 0:

            break;

        case 1:

            bytestream_get_byte(&s->buf);

            break;

        case 2:

            bytestream_get_be16(&s->buf);

            break;

        case 3:

            bytestream_get_be32(&s->buf);

            break;

        }

        if (SP == 0) {

            bytestream_get_be16(&s->buf);

        } else {

            bytestream_get_be32(&s->buf);

        }

    }

    return 0;

}

static int decode_seq_header(AVSContext *h) {

    MpegEncContext *s = &h->s;

    int frame_rate_code;

    int width, height;



    h->profile =         get_bits(&s->gb,8);

    h->level =           get_bits(&s->gb,8);

    skip_bits1(&s->gb); //progressive sequence

       width =           get_bits(&s->gb,14);

       height =          get_bits(&s->gb,14);

    if ((s->width || s->height) && (s->width != width || s->height != height)) {

        av_log_missing_feature(s, "Width/height changing in CAVS is", 0);

        return -1;






    s->width  = width;

    s->height = height;

    skip_bits(&s->gb,2); //chroma format

    skip_bits(&s->gb,3); //sample_precision

    h->aspect_ratio =    get_bits(&s->gb,4);

    frame_rate_code =    get_bits(&s->gb,4);

    skip_bits(&s->gb,18);//bit_rate_lower

    skip_bits1(&s->gb);  //marker_bit

    skip_bits(&s->gb,12);//bit_rate_upper

    s->low_delay =       get_bits1(&s->gb);

    h->mb_width  = (s->width  + 15) >> 4;

    h->mb_height = (s->height + 15) >> 4;

    h->s.avctx->time_base.den = avpriv_frame_rate_tab[frame_rate_code].num;

    h->s.avctx->time_base.num = avpriv_frame_rate_tab[frame_rate_code].den;

    h->s.avctx->width  = s->width;

    h->s.avctx->height = s->height;

    if(!h->top_qp)

        ff_cavs_init_top_lines(h);

    return 0;

void FUNC(ff_emulated_edge_mc)(uint8_t *buf, const uint8_t *src,

                                      ptrdiff_t linesize_arg,

                                      int block_w, int block_h,

                                      int src_x, int src_y, int w, int h)

{

    int x, y;

    int start_y, start_x, end_y, end_x;

    emuedge_linesize_type linesize = linesize_arg;



    if (!w || !h)

        return;



    if (src_y >= h) {

        src -= src_y * linesize;

        src += (h - 1) * linesize;

        src_y = h - 1;

    } else if (src_y <= -block_h) {

        src -= src_y * linesize;

        src += (1 - block_h) * linesize;

        src_y = 1 - block_h;

    }

    if (src_x >= w) {

        src  += (w - 1 - src_x) * sizeof(pixel);

        src_x = w - 1;

    } else if (src_x <= -block_w) {

        src  += (1 - block_w - src_x) * sizeof(pixel);

        src_x = 1 - block_w;

    }



    start_y = FFMAX(0, -src_y);

    start_x = FFMAX(0, -src_x);

    end_y = FFMIN(block_h, h-src_y);

    end_x = FFMIN(block_w, w-src_x);

    av_assert2(start_y < end_y && block_h);

    av_assert2(start_x < end_x && block_w);



    w    = end_x - start_x;

    src += start_y * linesize + start_x * sizeof(pixel);

    buf += start_x * sizeof(pixel);



    // top

    for (y = 0; y < start_y; y++) {

        memcpy(buf, src, w * sizeof(pixel));

        buf += linesize;

    }



    // copy existing part

    for (; y < end_y; y++) {

        memcpy(buf, src, w * sizeof(pixel));

        src += linesize;

        buf += linesize;

    }



    // bottom

    src -= linesize;

    for (; y < block_h; y++) {

        memcpy(buf, src, w * sizeof(pixel));

        buf += linesize;

    }



    buf -= block_h * linesize + start_x * sizeof(pixel);

    while (block_h--) {

        pixel *bufp = (pixel *) buf;



        // left

        for(x = 0; x < start_x; x++) {

            bufp[x] = bufp[start_x];

        }



        // right

        for (x = end_x; x < block_w; x++) {

            bufp[x] = bufp[end_x - 1];

        }

        buf += linesize;

    }

}

static int draw_glyphs(DrawTextContext *s, AVFrame *frame,

                       int width, int height,

                       const uint8_t rgbcolor[4], const uint8_t yuvcolor[4],

                       int x, int y)

{

    char *text = HAVE_LOCALTIME_R ? s->expanded_text : s->text;

    uint32_t code = 0;

    int i;

    uint8_t *p;

    Glyph *glyph = NULL;



    for (i = 0, p = text; *p; i++) {

        Glyph dummy = { 0 };

        GET_UTF8(code, *p++, continue;);



        /* skip new line chars, just go to new line */

        if (code == '\n' || code == '\r' || code == '\t')

            continue;



        dummy.code = code;

        glyph = av_tree_find(s->glyphs, &dummy, (void *)glyph_cmp, NULL);



        if (glyph->bitmap.pixel_mode != FT_PIXEL_MODE_MONO &&

            glyph->bitmap.pixel_mode != FT_PIXEL_MODE_GRAY)

            return AVERROR(EINVAL);



        if (s->is_packed_rgb) {

            draw_glyph_rgb(frame, &glyph->bitmap,

                           s->positions[i].x+x, s->positions[i].y+y, width, height,

                           s->pixel_step[0], rgbcolor, s->rgba_map, s->alpha);

        } else {

            draw_glyph_yuv(frame, &glyph->bitmap,

                           s->positions[i].x+x, s->positions[i].y+y, width, height,

                           yuvcolor, s->hsub, s->vsub, s->alpha);

        }

    }



    return 0;

}

static void decode_pitch_lag_low(int *lag_int, int *lag_frac, int pitch_index,

                                 uint8_t *base_lag_int, int subframe, enum Mode mode)

{

    if (subframe == 0 || (subframe == 2 && mode != MODE_6k60)) {

        if (pitch_index < 116) {

            *lag_int  = (pitch_index + 69) >> 1;

            *lag_frac = (pitch_index - (*lag_int << 1) + 68) << 1;

        } else {

            *lag_int  = pitch_index - 24;

            *lag_frac = 0;

        }

        // XXX: same problem as before

        *base_lag_int = av_clip(*lag_int - 8 - (*lag_frac < 0),

                                AMRWB_P_DELAY_MIN, AMRWB_P_DELAY_MAX - 15);

    } else {

        *lag_int  = (pitch_index + 1) >> 1;

        *lag_frac = (pitch_index - (*lag_int << 1)) << 1;

        *lag_int += *base_lag_int;

    }

}

int ffurl_open(URLContext **puc, const char *filename, int flags,

               const AVIOInterruptCB *int_cb, AVDictionary **options)

{

    int ret = ffurl_alloc(puc, filename, flags, int_cb);

    if (ret < 0)

        return ret;

    if (options && (*puc)->prot->priv_data_class &&

        (ret = av_opt_set_dict((*puc)->priv_data, options)) < 0)

        goto fail;

    if ((ret = av_opt_set_dict(*puc, options)) < 0)

        goto fail;

    ret = ffurl_connect(*puc, options);

    if (!ret)

        return 0;

fail:

    ffurl_close(*puc);

    *puc = NULL;

    return ret;

}

static int mpeg4_decode_video_packet_header(MpegEncContext *s)

{

    int mb_num_bits= av_log2(s->mb_num - 1) + 1;

    int header_extension=0, mb_num, len;



    /* is there enough space left for a video packet + header */

    if( get_bits_count(&s->gb) > s->gb.size*8-20) return -1;



    for(len=0; len<32; len++){

        if(get_bits1(&s->gb)) break;

    }



    if(len!=ff_mpeg4_get_video_packet_prefix_length(s)){

        printf("marker does not match f_code\n");

        return -1;

    }



    if(s->shape != RECT_SHAPE){

        header_extension= get_bits1(&s->gb);

        //FIXME more stuff here

    }



    mb_num= get_bits(&s->gb, mb_num_bits);

    if(mb_num>=s->mb_num){

        fprintf(stderr, "illegal mb_num in video packet (%d %d) \n", mb_num, s->mb_num);

        return -1;

    }

    s->mb_x= mb_num % s->mb_width;

    s->mb_y= mb_num / s->mb_width;



    if(s->shape != BIN_ONLY_SHAPE){

        int qscale= get_bits(&s->gb, s->quant_precision); 

        if(qscale)

            s->qscale= qscale;

    }



    if(s->shape == RECT_SHAPE){

        header_extension= get_bits1(&s->gb);

    }

    if(header_extension){

        int time_increment;

        int time_incr=0;



        while (get_bits1(&s->gb) != 0) 

            time_incr++;



        check_marker(&s->gb, "before time_increment in video packed header");

        time_increment= get_bits(&s->gb, s->time_increment_bits);

        check_marker(&s->gb, "before vop_coding_type in video packed header");



        skip_bits(&s->gb, 2); /* vop coding type */

        //FIXME not rect stuff here



        if(s->shape != BIN_ONLY_SHAPE){

            skip_bits(&s->gb, 3); /* intra dc vlc threshold */

//FIXME dont just ignore everything

            if(s->pict_type == S_TYPE && s->vol_sprite_usage==GMC_SPRITE){

                mpeg4_decode_sprite_trajectory(s);

                fprintf(stderr, "untested\n");

            }



            //FIXME reduced res stuff here



            if (s->pict_type != I_TYPE) {

                int f_code = get_bits(&s->gb, 3);	/* fcode_for */

                if(f_code==0){

                    printf("Error, video packet header damaged (f_code=0)\n");

                }

            }

            if (s->pict_type == B_TYPE) {

                int b_code = get_bits(&s->gb, 3);

                if(b_code==0){

                    printf("Error, video packet header damaged (b_code=0)\n");

                }

            }       

        }

    }

    //FIXME new-pred stuff



//printf("parse ok %d %d %d %d\n", mb_num, s->mb_x + s->mb_y*s->mb_width, get_bits_count(gb), get_bits_count(&s->gb));



    return 0;

}

int avfilter_link(AVFilterContext *src, unsigned srcpad,

                  AVFilterContext *dst, unsigned dstpad)

{

    AVFilterLink *link;



    if (src->nb_outputs <= srcpad || dst->nb_inputs <= dstpad ||

        src->outputs[srcpad]      || dst->inputs[dstpad])

        return -1;



    if (src->output_pads[srcpad].type != dst->input_pads[dstpad].type) {

        av_log(src, AV_LOG_ERROR,

               "Media type mismatch between the '%s' filter output pad %d and the '%s' filter input pad %d\n",

               src->name, srcpad, dst->name, dstpad);

        return AVERROR(EINVAL);

    }



    src->outputs[srcpad] =

    dst-> inputs[dstpad] = link = av_mallocz(sizeof(AVFilterLink));



    link->src     = src;

    link->dst     = dst;

    link->srcpad  = &src->output_pads[srcpad];

    link->dstpad  = &dst->input_pads[dstpad];

    link->type    = src->output_pads[srcpad].type;

    assert(AV_PIX_FMT_NONE == -1 && AV_SAMPLE_FMT_NONE == -1);

    link->format  = -1;



    return 0;

}

