void FUNCC(ff_h264_chroma_dc_dequant_idct)(int16_t *_block, int qmul){

    const int stride= 16*2;

    const int xStride= 16;

    int a,b,c,d,e;

    dctcoef *block = (dctcoef*)_block;



    a= block[stride*0 + xStride*0];

    b= block[stride*0 + xStride*1];

    c= block[stride*1 + xStride*0];

    d= block[stride*1 + xStride*1];



    e= a-b;

    a= a+b;

    b= c-d;

    c= c+d;



    block[stride*0 + xStride*0]= ((a+c)*qmul) >> 7;

    block[stride*0 + xStride*1]= ((e+b)*qmul) >> 7;

    block[stride*1 + xStride*0]= ((a-c)*qmul) >> 7;

    block[stride*1 + xStride*1]= ((e-b)*qmul) >> 7;

}

static inline int mpeg2_decode_block_intra(MpegEncContext *s,

                                           int16_t *block, int n)

{

    int level, dc, diff, i, j, run;

    int component;

    RLTable *rl;

    uint8_t *const scantable = s->intra_scantable.permutated;

    const uint16_t *quant_matrix;

    const int qscale = s->qscale;

    int mismatch;



    /* DC coefficient */

    if (n < 4) {

        quant_matrix = s->intra_matrix;

        component    = 0;

    } else {

        quant_matrix = s->chroma_intra_matrix;

        component    = (n & 1) + 1;

    }

    diff = decode_dc(&s->gb, component);

    if (diff >= 0xffff)

        return AVERROR_INVALIDDATA;

    dc  = s->last_dc[component];

    dc += diff;

    s->last_dc[component] = dc;

    block[0] = dc << (3 - s->intra_dc_precision);

    ff_tlog(s->avctx, "dc=%d\n", block[0]);

    mismatch = block[0] ^ 1;

    i = 0;

    if (s->intra_vlc_format)

        rl = &ff_rl_mpeg2;

    else

        rl = &ff_rl_mpeg1;



    {

        OPEN_READER(re, &s->gb);

        /* now quantify & encode AC coefficients */

        for (;;) {

            UPDATE_CACHE(re, &s->gb);

            GET_RL_VLC(level, run, re, &s->gb, rl->rl_vlc[0],

                       TEX_VLC_BITS, 2, 0);



            if (level == 127) {

                break;

            } else if (level != 0) {

                i += run;

                if (i > MAX_INDEX)

                    break;

                j = scantable[i];

                level = (level * qscale * quant_matrix[j]) >> 4;

                level = (level ^ SHOW_SBITS(re, &s->gb, 1)) -

                        SHOW_SBITS(re, &s->gb, 1);

                LAST_SKIP_BITS(re, &s->gb, 1);

            } else {

                /* escape */

                run = SHOW_UBITS(re, &s->gb, 6) + 1;

                LAST_SKIP_BITS(re, &s->gb, 6);

                UPDATE_CACHE(re, &s->gb);

                level = SHOW_SBITS(re, &s->gb, 12);

                SKIP_BITS(re, &s->gb, 12);

                i += run;

                if (i > MAX_INDEX)

                    break;

                j = scantable[i];

                if (level < 0) {

                    level = (-level * qscale * quant_matrix[j]) >> 4;

                    level = -level;

                } else {

                    level = (level * qscale * quant_matrix[j]) >> 4;

                }

            }



            mismatch ^= level;

            block[j]  = level;

        }

        CLOSE_READER(re, &s->gb);

    }

    block[63] ^= mismatch & 1;



    check_scantable_index(s, i);



    s->block_last_index[n] = i;

    return 0;

}

static void vc1_draw_sprites(VC1Context *v, SpriteData* sd)

{

    int i, plane, row, sprite;

    int sr_cache[2][2] = { { -1, -1 }, { -1, -1 } };

    uint8_t* src_h[2][2];

    int xoff[2], xadv[2], yoff[2], yadv[2], alpha;

    int ysub[2];

    MpegEncContext *s = &v->s;



    for (i = 0; i < 2; i++) {

        xoff[i] = av_clip(sd->coefs[i][2], 0, v->sprite_width-1 << 16);

        xadv[i] = sd->coefs[i][0];

        if (xadv[i] != 1<<16 || (v->sprite_width << 16) - (v->output_width << 16) - xoff[i])

            xadv[i] = av_clip(xadv[i], 0, ((v->sprite_width<<16) - xoff[i] - 1) / v->output_width);



        yoff[i] = av_clip(sd->coefs[i][5], 0, v->sprite_height-1 << 16);

        yadv[i] = av_clip(sd->coefs[i][4], 0, ((v->sprite_height << 16) - yoff[i]) / v->output_height);

    }

    alpha = av_clip(sd->coefs[1][6], 0, (1<<16) - 1);



    for (plane = 0; plane < (s->flags&CODEC_FLAG_GRAY ? 1 : 3); plane++) {

        int width = v->output_width>>!!plane;



        for (row = 0; row < v->output_height>>!!plane; row++) {

            uint8_t *dst = v->sprite_output_frame.data[plane] +

                           v->sprite_output_frame.linesize[plane] * row;



            for (sprite = 0; sprite <= v->two_sprites; sprite++) {

                uint8_t *iplane = s->current_picture.f.data[plane];

                int      iline  = s->current_picture.f.linesize[plane];

                int      ycoord = yoff[sprite] + yadv[sprite] * row;

                int      yline  = ycoord >> 16;

                ysub[sprite] = ycoord & 0xFFFF;

                if (sprite) {

                    iplane = s->last_picture.f.data[plane];

                    iline  = s->last_picture.f.linesize[plane];

                }

                if (!(xoff[sprite] & 0xFFFF) && xadv[sprite] == 1 << 16) {

                        src_h[sprite][0] = iplane + (xoff[sprite] >> 16) +  yline      * iline;

                    if (ysub[sprite])

                        src_h[sprite][1] = iplane + (xoff[sprite] >> 16) + (yline + 1) * iline;

                } else {

                    if (sr_cache[sprite][0] != yline) {

                        if (sr_cache[sprite][1] == yline) {

                            FFSWAP(uint8_t*, v->sr_rows[sprite][0], v->sr_rows[sprite][1]);

                            FFSWAP(int,        sr_cache[sprite][0],   sr_cache[sprite][1]);

                        } else {

                            v->vc1dsp.sprite_h(v->sr_rows[sprite][0], iplane + yline * iline, xoff[sprite], xadv[sprite], width);

                            sr_cache[sprite][0] = yline;

                        }

                    }

                    if (ysub[sprite] && sr_cache[sprite][1] != yline + 1) {

                        v->vc1dsp.sprite_h(v->sr_rows[sprite][1], iplane + (yline + 1) * iline, xoff[sprite], xadv[sprite], width);

                        sr_cache[sprite][1] = yline + 1;

                    }

                    src_h[sprite][0] = v->sr_rows[sprite][0];

                    src_h[sprite][1] = v->sr_rows[sprite][1];

                }

            }



            if (!v->two_sprites) {

                if (ysub[0]) {

                    v->vc1dsp.sprite_v_single(dst, src_h[0][0], src_h[0][1], ysub[0], width);

                } else {

                    memcpy(dst, src_h[0][0], width);

                }

            } else {

                if (ysub[0] && ysub[1]) {

                    v->vc1dsp.sprite_v_double_twoscale(dst, src_h[0][0], src_h[0][1], ysub[0],

                                                       src_h[1][0], src_h[1][1], ysub[1], alpha, width);

                } else if (ysub[0]) {

                    v->vc1dsp.sprite_v_double_onescale(dst, src_h[0][0], src_h[0][1], ysub[0],

                                                       src_h[1][0], alpha, width);

                } else if (ysub[1]) {

                    v->vc1dsp.sprite_v_double_onescale(dst, src_h[1][0], src_h[1][1], ysub[1],

                                                       src_h[0][0], (1<<16)-1-alpha, width);

                } else {

                    v->vc1dsp.sprite_v_double_noscale(dst, src_h[0][0], src_h[1][0], alpha, width);

                }

            }

        }



        if (!plane) {

            for (i = 0; i < 2; i++) {

                xoff[i] >>= 1;

                yoff[i] >>= 1;

            }

        }



    }

}

static av_cold int xan_decode_init(AVCodecContext *avctx)

{

    XanContext *s = avctx->priv_data;



    s->avctx = avctx;

    s->frame_size = 0;



    if ((avctx->codec->id == CODEC_ID_XAN_WC3) &&

        (s->avctx->palctrl == NULL)) {

        av_log(avctx, AV_LOG_ERROR, "palette expected\n");

        return AVERROR(EINVAL);

    }



    avctx->pix_fmt = PIX_FMT_PAL8;



    s->buffer1_size = avctx->width * avctx->height;

    s->buffer1 = av_malloc(s->buffer1_size);

    if (!s->buffer1)

        return AVERROR(ENOMEM);

    s->buffer2_size = avctx->width * avctx->height;

    s->buffer2 = av_malloc(s->buffer2_size + 130);

    if (!s->buffer2) {

        av_freep(&s->buffer1);

        return AVERROR(ENOMEM);

    }



    return 0;

}

static void init_uni_ac_vlc(RLTable *rl, uint8_t *uni_ac_vlc_len){

    int i;



    for(i=0; i<128; i++){

        int level= i-64;

        int run;



        for(run=0; run<64; run++){

            int len, bits, code;



            int alevel= FFABS(level);

            int sign= (level>>31)&1;



            if (alevel > rl->max_level[0][run])

                code= 111; /*rl->n*/

            else

                code= rl->index_run[0][run] + alevel - 1;



            if (code < 111 /* rl->n */) {

                /* store the vlc & sign at once */

                len=   rl->table_vlc[code][1]+1;

                bits= (rl->table_vlc[code][0]<<1) + sign;

            } else {

                len=  rl->table_vlc[111/*rl->n*/][1]+6;

                bits= rl->table_vlc[111/*rl->n*/][0]<<6;



                bits|= run;

                if (alevel < 128) {

                    bits<<=8; len+=8;

                    bits|= level & 0xff;

                } else {

                    bits<<=16; len+=16;

                    bits|= level & 0xff;

                    if (level < 0) {

                        bits|= 0x8001 + level + 255;

                    } else {

                        bits|= level & 0xffff;

                    }

                }

            }



            uni_ac_vlc_len [UNI_AC_ENC_INDEX(run, i)]= len;

        }

    }

}

float ff_rate_estimate_qscale(MpegEncContext *s, int dry_run)

{

    float q;

    int qmin, qmax;

    float br_compensation;

    double diff;

    double short_term_q;

    double fps;

    int picture_number = s->picture_number;

    int64_t wanted_bits;

    RateControlContext *rcc = &s->rc_context;

    AVCodecContext *a       = s->avctx;

    RateControlEntry local_rce, *rce;

    double bits;

    double rate_factor;

    int var;

    const int pict_type = s->pict_type;

    Picture * const pic = &s->current_picture;

    emms_c();



#if CONFIG_LIBXVID

    if ((s->flags & CODEC_FLAG_PASS2) &&

        s->avctx->rc_strategy == FF_RC_STRATEGY_XVID)

        return ff_xvid_rate_estimate_qscale(s, dry_run);

#endif



    get_qminmax(&qmin, &qmax, s, pict_type);



    fps = get_fps(s->avctx);

    /* update predictors */

    if (picture_number > 2 && !dry_run) {

        const int last_var = s->last_pict_type == AV_PICTURE_TYPE_I ? rcc->last_mb_var_sum

                                                                    : rcc->last_mc_mb_var_sum;

        av_assert1(s->frame_bits >= s->stuffing_bits);

        update_predictor(&rcc->pred[s->last_pict_type],

                         rcc->last_qscale,

                         sqrt(last_var),

                         s->frame_bits - s->stuffing_bits);

    }



    if (s->flags & CODEC_FLAG_PASS2) {

        assert(picture_number >= 0);

        if (picture_number >= rcc->num_entries) {

            av_log(s, AV_LOG_ERROR, "Input is longer than 2-pass log file\n");

            return -1;

        }

        rce         = &rcc->entry[picture_number];

        wanted_bits = rce->expected_bits;

    } else {

        Picture *dts_pic;

        rce = &local_rce;



        /* FIXME add a dts field to AVFrame and ensure it is set and use it

         * here instead of reordering but the reordering is simpler for now

         * until H.264 B-pyramid must be handled. */

        if (s->pict_type == AV_PICTURE_TYPE_B || s->low_delay)

            dts_pic = s->current_picture_ptr;

        else

            dts_pic = s->last_picture_ptr;



        if (!dts_pic || dts_pic->f.pts == AV_NOPTS_VALUE)

            wanted_bits = (uint64_t)(s->bit_rate * (double)picture_number / fps);

        else

            wanted_bits = (uint64_t)(s->bit_rate * (double)dts_pic->f.pts / fps);

    }



    diff = s->total_bits - wanted_bits;

    br_compensation = (a->bit_rate_tolerance - diff) / a->bit_rate_tolerance;

    if (br_compensation <= 0.0)

        br_compensation = 0.001;



    var = pict_type == AV_PICTURE_TYPE_I ? pic->mb_var_sum : pic->mc_mb_var_sum;



    short_term_q = 0; /* avoid warning */

    if (s->flags & CODEC_FLAG_PASS2) {

        if (pict_type != AV_PICTURE_TYPE_I)

            assert(pict_type == rce->new_pict_type);



        q = rce->new_qscale / br_compensation;

        av_dlog(s, "%f %f %f last:%d var:%d type:%d//\n", q, rce->new_qscale,

                br_compensation, s->frame_bits, var, pict_type);

    } else {

        rce->pict_type     =

        rce->new_pict_type = pict_type;

        rce->mc_mb_var_sum = pic->mc_mb_var_sum;

        rce->mb_var_sum    = pic->mb_var_sum;

        rce->qscale        = FF_QP2LAMBDA * 2;

        rce->f_code        = s->f_code;

        rce->b_code        = s->b_code;

        rce->misc_bits     = 1;



        bits = predict_size(&rcc->pred[pict_type], rce->qscale, sqrt(var));

        if (pict_type == AV_PICTURE_TYPE_I) {

            rce->i_count    = s->mb_num;

            rce->i_tex_bits = bits;

            rce->p_tex_bits = 0;

            rce->mv_bits    = 0;

        } else {

            rce->i_count    = 0;    // FIXME we do know this approx

            rce->i_tex_bits = 0;

            rce->p_tex_bits = bits * 0.9;

            rce->mv_bits    = bits * 0.1;

        }

        rcc->i_cplx_sum[pict_type]  += rce->i_tex_bits * rce->qscale;

        rcc->p_cplx_sum[pict_type]  += rce->p_tex_bits * rce->qscale;

        rcc->mv_bits_sum[pict_type] += rce->mv_bits;

        rcc->frame_count[pict_type]++;



        bits        = rce->i_tex_bits + rce->p_tex_bits;

        rate_factor = rcc->pass1_wanted_bits /

                      rcc->pass1_rc_eq_output_sum * br_compensation;



        q = get_qscale(s, rce, rate_factor, picture_number);

        if (q < 0)

            return -1;



        assert(q > 0.0);

        q = get_diff_limited_q(s, rce, q);

        assert(q > 0.0);



        // FIXME type dependent blur like in 2-pass

        if (pict_type == AV_PICTURE_TYPE_P || s->intra_only) {

            rcc->short_term_qsum   *= a->qblur;

            rcc->short_term_qcount *= a->qblur;



            rcc->short_term_qsum += q;

            rcc->short_term_qcount++;

            q = short_term_q = rcc->short_term_qsum / rcc->short_term_qcount;

        }

        assert(q > 0.0);



        q = modify_qscale(s, rce, q, picture_number);



        rcc->pass1_wanted_bits += s->bit_rate / fps;



        assert(q > 0.0);

    }



    if (s->avctx->debug & FF_DEBUG_RC) {

        av_log(s->avctx, AV_LOG_DEBUG,

               "%c qp:%d<%2.1f<%d %d want:%d total:%d comp:%f st_q:%2.2f "

               "size:%d var:%"PRId64"/%"PRId64" br:%d fps:%d\n",

               av_get_picture_type_char(pict_type),

               qmin, q, qmax, picture_number,

               (int)wanted_bits / 1000, (int)s->total_bits / 1000,

               br_compensation, short_term_q, s->frame_bits,

               pic->mb_var_sum, pic->mc_mb_var_sum,

               s->bit_rate / 1000, (int)fps);

    }



    if (q < qmin)

        q = qmin;

    else if (q > qmax)

        q = qmax;



    if (s->adaptive_quant)

        adaptive_quantization(s, q);

    else

        q = (int)(q + 0.5);



    if (!dry_run) {

        rcc->last_qscale        = q;

        rcc->last_mc_mb_var_sum = pic->mc_mb_var_sum;

        rcc->last_mb_var_sum    = pic->mb_var_sum;

    }

    return q;

}

static void pred_spatial_direct_motion(H264Context * const h, int *mb_type){

    MpegEncContext * const s = &h->s;

    int b8_stride = 2;

    int b4_stride = h->b_stride;

    int mb_xy = h->mb_xy, mb_y = s->mb_y;

    int mb_type_col[2];

    const int16_t (*l1mv0)[2], (*l1mv1)[2];

    const int8_t *l1ref0, *l1ref1;

    const int is_b8x8 = IS_8X8(*mb_type);

    unsigned int sub_mb_type= MB_TYPE_L0L1;

    int i8, i4;

    int ref[2];

    int mv[2];

    int list;



    assert(h->ref_list[1][0].f.reference & 3);



    await_reference_mb_row(h, &h->ref_list[1][0], s->mb_y + !!IS_INTERLACED(*mb_type));



#define MB_TYPE_16x16_OR_INTRA (MB_TYPE_16x16|MB_TYPE_INTRA4x4|MB_TYPE_INTRA16x16|MB_TYPE_INTRA_PCM)





    /* ref = min(neighbors) */

    for(list=0; list<2; list++){

        int left_ref = h->ref_cache[list][scan8[0] - 1];

        int top_ref  = h->ref_cache[list][scan8[0] - 8];

        int refc = h->ref_cache[list][scan8[0] - 8 + 4];

        const int16_t *C= h->mv_cache[list][ scan8[0] - 8 + 4];

        if(refc == PART_NOT_AVAILABLE){

            refc = h->ref_cache[list][scan8[0] - 8 - 1];

            C    = h-> mv_cache[list][scan8[0] - 8 - 1];


        ref[list] = FFMIN3((unsigned)left_ref, (unsigned)top_ref, (unsigned)refc);

        if(ref[list] >= 0){

            //this is just pred_motion() but with the cases removed that cannot happen for direct blocks

            const int16_t * const A= h->mv_cache[list][ scan8[0] - 1 ];

            const int16_t * const B= h->mv_cache[list][ scan8[0] - 8 ];



            int match_count= (left_ref==ref[list]) + (top_ref==ref[list]) + (refc==ref[list]);

            if(match_count > 1){ //most common

                mv[list]= pack16to32(mid_pred(A[0], B[0], C[0]),

                                     mid_pred(A[1], B[1], C[1]) );

            }else {

                assert(match_count==1);

                if(left_ref==ref[list]){

                    mv[list]= AV_RN32A(A);

                }else if(top_ref==ref[list]){

                    mv[list]= AV_RN32A(B);

                }else{

                    mv[list]= AV_RN32A(C);



        }else{

            int mask= ~(MB_TYPE_L0 << (2*list));

            mv[list] = 0;

            ref[list] = -1;

            if(!is_b8x8)

                *mb_type &= mask;

            sub_mb_type &= mask;



    if(ref[0] < 0 && ref[1] < 0){

        ref[0] = ref[1] = 0;

        if(!is_b8x8)

            *mb_type |= MB_TYPE_L0L1;

        sub_mb_type |= MB_TYPE_L0L1;




    if(!(is_b8x8|mv[0]|mv[1])){

        fill_rectangle(&h->ref_cache[0][scan8[0]], 4, 4, 8, (uint8_t)ref[0], 1);

        fill_rectangle(&h->ref_cache[1][scan8[0]], 4, 4, 8, (uint8_t)ref[1], 1);

        fill_rectangle(&h->mv_cache[0][scan8[0]], 4, 4, 8, 0, 4);

        fill_rectangle(&h->mv_cache[1][scan8[0]], 4, 4, 8, 0, 4);

        *mb_type= (*mb_type & ~(MB_TYPE_8x8|MB_TYPE_16x8|MB_TYPE_8x16|MB_TYPE_P1L0|MB_TYPE_P1L1))|MB_TYPE_16x16|MB_TYPE_DIRECT2;

        return;




    if (IS_INTERLACED(h->ref_list[1][0].f.mb_type[mb_xy])) { // AFL/AFR/FR/FL -> AFL/FL

        if (!IS_INTERLACED(*mb_type)) {                          //     AFR/FR    -> AFL/FL

            mb_y = (s->mb_y&~1) + h->col_parity;

            mb_xy= s->mb_x + ((s->mb_y&~1) + h->col_parity)*s->mb_stride;

            b8_stride = 0;

        }else{

            mb_y  += h->col_fieldoff;

            mb_xy += s->mb_stride*h->col_fieldoff; // non zero for FL -> FL & differ parity


        goto single_col;

    }else{                                               // AFL/AFR/FR/FL -> AFR/FR

        if(IS_INTERLACED(*mb_type)){                     // AFL       /FL -> AFR/FR

            mb_y = s->mb_y&~1;

            mb_xy= s->mb_x + (s->mb_y&~1)*s->mb_stride;

            mb_type_col[0] = h->ref_list[1][0].f.mb_type[mb_xy];

            mb_type_col[1] = h->ref_list[1][0].f.mb_type[mb_xy + s->mb_stride];

            b8_stride = 2+4*s->mb_stride;

            b4_stride *= 6;







            sub_mb_type |= MB_TYPE_16x16|MB_TYPE_DIRECT2; /* B_SUB_8x8 */

            if(    (mb_type_col[0] & MB_TYPE_16x16_OR_INTRA)

                && (mb_type_col[1] & MB_TYPE_16x16_OR_INTRA)

                && !is_b8x8){

                *mb_type   |= MB_TYPE_16x8 |MB_TYPE_DIRECT2; /* B_16x8 */

            }else{

                *mb_type   |= MB_TYPE_8x8;


        }else{                                           //     AFR/FR    -> AFR/FR

single_col:

            mb_type_col[0] =

            mb_type_col[1] = h->ref_list[1][0].f.mb_type[mb_xy];



            sub_mb_type |= MB_TYPE_16x16|MB_TYPE_DIRECT2; /* B_SUB_8x8 */

            if(!is_b8x8 && (mb_type_col[0] & MB_TYPE_16x16_OR_INTRA)){

                *mb_type   |= MB_TYPE_16x16|MB_TYPE_DIRECT2; /* B_16x16 */

            }else if(!is_b8x8 && (mb_type_col[0] & (MB_TYPE_16x8|MB_TYPE_8x16))){

                *mb_type   |= MB_TYPE_DIRECT2 | (mb_type_col[0] & (MB_TYPE_16x8|MB_TYPE_8x16));

            }else{

                if(!h->sps.direct_8x8_inference_flag){

                    /* FIXME save sub mb types from previous frames (or derive from MVs)

                    * so we know exactly what block size to use */

                    sub_mb_type += (MB_TYPE_8x8-MB_TYPE_16x16); /* B_SUB_4x4 */


                *mb_type   |= MB_TYPE_8x8;






    await_reference_mb_row(h, &h->ref_list[1][0], mb_y);



    l1mv0  = &h->ref_list[1][0].f.motion_val[0][h->mb2b_xy [mb_xy]];

    l1mv1  = &h->ref_list[1][0].f.motion_val[1][h->mb2b_xy [mb_xy]];

    l1ref0 = &h->ref_list[1][0].f.ref_index [0][4 * mb_xy];

    l1ref1 = &h->ref_list[1][0].f.ref_index [1][4 * mb_xy];

    if(!b8_stride){

        if(s->mb_y&1){

            l1ref0 += 2;

            l1ref1 += 2;

            l1mv0  +=  2*b4_stride;

            l1mv1  +=  2*b4_stride;







        if(IS_INTERLACED(*mb_type) != IS_INTERLACED(mb_type_col[0])){

            int n=0;

            for(i8=0; i8<4; i8++){

                int x8 = i8&1;

                int y8 = i8>>1;

                int xy8 = x8+y8*b8_stride;

                int xy4 = 3*x8+y8*b4_stride;

                int a,b;



                if(is_b8x8 && !IS_DIRECT(h->sub_mb_type[i8]))

                    continue;

                h->sub_mb_type[i8] = sub_mb_type;



                fill_rectangle(&h->ref_cache[0][scan8[i8*4]], 2, 2, 8, (uint8_t)ref[0], 1);

                fill_rectangle(&h->ref_cache[1][scan8[i8*4]], 2, 2, 8, (uint8_t)ref[1], 1);

                if(!IS_INTRA(mb_type_col[y8]) && !h->ref_list[1][0].long_ref

                   && (   (l1ref0[xy8] == 0 && FFABS(l1mv0[xy4][0]) <= 1 && FFABS(l1mv0[xy4][1]) <= 1)

                       || (l1ref0[xy8]  < 0 && l1ref1[xy8] == 0 && FFABS(l1mv1[xy4][0]) <= 1 && FFABS(l1mv1[xy4][1]) <= 1))){

                    a=b=0;

                    if(ref[0] > 0)

                        a= mv[0];

                    if(ref[1] > 0)

                        b= mv[1];

                    n++;

                }else{

                    a= mv[0];

                    b= mv[1];


                fill_rectangle(&h->mv_cache[0][scan8[i8*4]], 2, 2, 8, a, 4);

                fill_rectangle(&h->mv_cache[1][scan8[i8*4]], 2, 2, 8, b, 4);


            if(!is_b8x8 && !(n&3))

                *mb_type= (*mb_type & ~(MB_TYPE_8x8|MB_TYPE_16x8|MB_TYPE_8x16|MB_TYPE_P1L0|MB_TYPE_P1L1))|MB_TYPE_16x16|MB_TYPE_DIRECT2;

        }else if(IS_16X16(*mb_type)){

            int a,b;



            fill_rectangle(&h->ref_cache[0][scan8[0]], 4, 4, 8, (uint8_t)ref[0], 1);

            fill_rectangle(&h->ref_cache[1][scan8[0]], 4, 4, 8, (uint8_t)ref[1], 1);

            if(!IS_INTRA(mb_type_col[0]) && !h->ref_list[1][0].long_ref

               && (   (l1ref0[0] == 0 && FFABS(l1mv0[0][0]) <= 1 && FFABS(l1mv0[0][1]) <= 1)

                   || (l1ref0[0]  < 0 && l1ref1[0] == 0 && FFABS(l1mv1[0][0]) <= 1 && FFABS(l1mv1[0][1]) <= 1

                       && h->x264_build>33U))){

                a=b=0;

                if(ref[0] > 0)

                    a= mv[0];

                if(ref[1] > 0)

                    b= mv[1];

            }else{

                a= mv[0];

                b= mv[1];


            fill_rectangle(&h->mv_cache[0][scan8[0]], 4, 4, 8, a, 4);

            fill_rectangle(&h->mv_cache[1][scan8[0]], 4, 4, 8, b, 4);

        }else{

            int n=0;

            for(i8=0; i8<4; i8++){

                const int x8 = i8&1;

                const int y8 = i8>>1;



                if(is_b8x8 && !IS_DIRECT(h->sub_mb_type[i8]))

                    continue;

                h->sub_mb_type[i8] = sub_mb_type;



                fill_rectangle(&h->mv_cache[0][scan8[i8*4]], 2, 2, 8, mv[0], 4);

                fill_rectangle(&h->mv_cache[1][scan8[i8*4]], 2, 2, 8, mv[1], 4);

                fill_rectangle(&h->ref_cache[0][scan8[i8*4]], 2, 2, 8, (uint8_t)ref[0], 1);

                fill_rectangle(&h->ref_cache[1][scan8[i8*4]], 2, 2, 8, (uint8_t)ref[1], 1);



                assert(b8_stride==2);

                /* col_zero_flag */

                if(!IS_INTRA(mb_type_col[0]) && !h->ref_list[1][0].long_ref && (   l1ref0[i8] == 0

                                              || (l1ref0[i8] < 0 && l1ref1[i8] == 0

                                                  && h->x264_build>33U))){

                    const int16_t (*l1mv)[2]= l1ref0[i8] == 0 ? l1mv0 : l1mv1;

                    if(IS_SUB_8X8(sub_mb_type)){

                        const int16_t *mv_col = l1mv[x8*3 + y8*3*b4_stride];

                        if(FFABS(mv_col[0]) <= 1 && FFABS(mv_col[1]) <= 1){

                            if(ref[0] == 0)

                                fill_rectangle(&h->mv_cache[0][scan8[i8*4]], 2, 2, 8, 0, 4);

                            if(ref[1] == 0)

                                fill_rectangle(&h->mv_cache[1][scan8[i8*4]], 2, 2, 8, 0, 4);

                            n+=4;


                    }else{

                        int m=0;

                    for(i4=0; i4<4; i4++){

                        const int16_t *mv_col = l1mv[x8*2 + (i4&1) + (y8*2 + (i4>>1))*b4_stride];

                        if(FFABS(mv_col[0]) <= 1 && FFABS(mv_col[1]) <= 1){

                            if(ref[0] == 0)

                                AV_ZERO32(h->mv_cache[0][scan8[i8*4+i4]]);

                            if(ref[1] == 0)

                                AV_ZERO32(h->mv_cache[1][scan8[i8*4+i4]]);

                            m++;



                    if(!(m&3))

                        h->sub_mb_type[i8]+= MB_TYPE_16x16 - MB_TYPE_8x8;

                    n+=m;




            if(!is_b8x8 && !(n&15))

                *mb_type= (*mb_type & ~(MB_TYPE_8x8|MB_TYPE_16x8|MB_TYPE_8x16|MB_TYPE_P1L0|MB_TYPE_P1L1))|MB_TYPE_16x16|MB_TYPE_DIRECT2;

int avformat_seek_file(AVFormatContext *s, int stream_index, int64_t min_ts, int64_t ts, int64_t max_ts, int flags)

{

    if(min_ts > ts || max_ts < ts)

        return -1;



    if (s->iformat->read_seek2) {

        int ret;

        ff_read_frame_flush(s);



        if (stream_index == -1 && s->nb_streams == 1) {

            AVRational time_base = s->streams[0]->time_base;

            ts = av_rescale_q(ts, AV_TIME_BASE_Q, time_base);

            min_ts = av_rescale_rnd(min_ts, time_base.den,

                                    time_base.num * (int64_t)AV_TIME_BASE,

                                    AV_ROUND_UP);

            max_ts = av_rescale_rnd(max_ts, time_base.den,

                                    time_base.num * (int64_t)AV_TIME_BASE,

                                    AV_ROUND_DOWN);

        }



        ret = s->iformat->read_seek2(s, stream_index, min_ts, ts, max_ts, flags);



        if (ret >= 0)

            avformat_queue_attached_pictures(s);

        return ret;

    }



    if(s->iformat->read_timestamp){

        //try to seek via read_timestamp()

    }



    //Fallback to old API if new is not implemented but old is

    //Note the old has somewhat different semantics

    if (s->iformat->read_seek || 1) {

        int dir = (ts - (uint64_t)min_ts > (uint64_t)max_ts - ts ? AVSEEK_FLAG_BACKWARD : 0);

        int ret = av_seek_frame(s, stream_index, ts, flags | dir);

        if (ret<0 && ts != min_ts && max_ts != ts) {

            ret = av_seek_frame(s, stream_index, dir ? max_ts : min_ts, flags | dir);

            if (ret >= 0)

                ret = av_seek_frame(s, stream_index, ts, flags | (dir^AVSEEK_FLAG_BACKWARD));

        }

        return ret;

    }



    // try some generic seek like seek_frame_generic() but with new ts semantics

}

static inline void render_line_unrolled(intptr_t x, uint8_t y, int x1,

                                        intptr_t sy, int ady, int adx,

                                        float *buf)

{

    int err = -adx;

    x -= x1 - 1;

    buf += x1 - 1;

    while (++x < 0) {

        err += ady;

        if (err >= 0) {

            err += ady - adx;

            y   += sy;

            buf[x++] = ff_vorbis_floor1_inverse_db_table[y];

        }

        buf[x] = ff_vorbis_floor1_inverse_db_table[y];

    }

    if (x <= 0) {

        if (err + ady >= 0)

            y += sy;

        buf[x] = ff_vorbis_floor1_inverse_db_table[y];

    }

}

static inline void s_zero(int cur_diff, struct G722Band *band)

{

    int s_zero = 0;



    #define ACCUM(k, x, d) do { \

            int tmp = x; \

            band->zero_mem[k] = ((band->zero_mem[k] * 255) >> 8) + \

               d*((band->diff_mem[k]^cur_diff) < 0 ? -128 : 128); \

            band->diff_mem[k] = tmp; \

            s_zero += (tmp * band->zero_mem[k]) >> 15; \

        } while (0)

    if (cur_diff) {

        ACCUM(5, band->diff_mem[4], 1);

        ACCUM(4, band->diff_mem[3], 1);

        ACCUM(3, band->diff_mem[2], 1);

        ACCUM(2, band->diff_mem[1], 1);

        ACCUM(1, band->diff_mem[0], 1);

        ACCUM(0, cur_diff << 1, 1);

    } else {

        ACCUM(5, band->diff_mem[4], 0);

        ACCUM(4, band->diff_mem[3], 0);

        ACCUM(3, band->diff_mem[2], 0);

        ACCUM(2, band->diff_mem[1], 0);

        ACCUM(1, band->diff_mem[0], 0);

        ACCUM(0, cur_diff << 1, 0);

    }

    #undef ACCUM

    band->s_zero = s_zero;

}

static av_cold int decode_init(AVCodecContext * avctx)

{

    KmvcContext *const c = avctx->priv_data;

    int i;



    c->avctx = avctx;



    if (avctx->width > 320 || avctx->height > 200) {

        av_log(avctx, AV_LOG_ERROR, "KMVC supports frames <= 320x200\n");

        return -1;

    }



    c->frm0 = av_mallocz(320 * 200);

    c->frm1 = av_mallocz(320 * 200);

    c->cur = c->frm0;

    c->prev = c->frm1;



    for (i = 0; i < 256; i++) {

        c->pal[i] = 0xFF << 24 | i * 0x10101;

    }



    if (avctx->extradata_size < 12) {

        av_log(avctx, AV_LOG_WARNING,

               "Extradata missing, decoding may not work properly...\n");

        c->palsize = 127;

    } else {

        c->palsize = AV_RL16(avctx->extradata + 10);

        if (c->palsize >= (unsigned)MAX_PALSIZE) {

            c->palsize = 127;

            av_log(avctx, AV_LOG_ERROR, "KMVC palette too large\n");

            return AVERROR_INVALIDDATA;

        }

    }



    if (avctx->extradata_size == 1036) {        // palette in extradata

        uint8_t *src = avctx->extradata + 12;

        for (i = 0; i < 256; i++) {

            c->pal[i] = AV_RL32(src);

            src += 4;

        }

        c->setpal = 1;

    }



    avcodec_get_frame_defaults(&c->pic);

    avctx->pix_fmt = AV_PIX_FMT_PAL8;



    return 0;

}

