        my > ymin && my < ymax) {

        int dx=0, dy=0;

        int d, pen_x, pen_y;

        const int index= (my<<ME_MAP_SHIFT) + mx;

        const int t= score_map[(index-(1<<ME_MAP_SHIFT))&(ME_MAP_SIZE-1)];

        const int l= score_map[(index- 1               )&(ME_MAP_SIZE-1)];

        const int r= score_map[(index+ 1               )&(ME_MAP_SIZE-1)];

        const int b= score_map[(index+(1<<ME_MAP_SHIFT))&(ME_MAP_SIZE-1)];

        mx<<=1;

        my<<=1;





        pen_x= pred_x + mx;

        pen_y= pred_y + my;



        ptr-= stride;

        if(t<=b){

            CHECK_SAD_HALF_MV(y2 , 0, -1)

            if(l<=r){

                CHECK_SAD_HALF_MV(xy2, -1, -1)

                if(t+r<=b+l){

                    CHECK_SAD_HALF_MV(xy2, +1, -1)

                    ptr+= stride;

                }else{

                    ptr+= stride;

                    CHECK_SAD_HALF_MV(xy2, -1, +1)

                }

                CHECK_SAD_HALF_MV(x2 , -1,  0)

            }else{

                CHECK_SAD_HALF_MV(xy2, +1, -1)

                if(t+l<=b+r){

                    CHECK_SAD_HALF_MV(xy2, -1, -1)

                    ptr+= stride;

                }else{

                    ptr+= stride;

                    CHECK_SAD_HALF_MV(xy2, +1, +1)

                }

                CHECK_SAD_HALF_MV(x2 , +1,  0)

            }

        }else{

            if(l<=r){

                if(t+l<=b+r){

                    CHECK_SAD_HALF_MV(xy2, -1, -1)

                    ptr+= stride;

                }else{

                    ptr+= stride;

                    CHECK_SAD_HALF_MV(xy2, +1, +1)

                }

                CHECK_SAD_HALF_MV(x2 , -1,  0)

                CHECK_SAD_HALF_MV(xy2, -1, +1)

            }else{

                if(t+r<=b+l){

                    CHECK_SAD_HALF_MV(xy2, +1, -1)

                    ptr+= stride;

                }else{

                    ptr+= stride;

                    CHECK_SAD_HALF_MV(xy2, -1, +1)

                }

                CHECK_SAD_HALF_MV(x2 , +1,  0)

                CHECK_SAD_HALF_MV(xy2, +1, +1)

            }

            CHECK_SAD_HALF_MV(y2 ,  0, +1)

        }

        mx+=dx;

        my+=dy;



    }else{

        mx<<=1;

        my<<=1;

    }



    *mx_ptr = mx;

    *my_ptr = my;

    return dminh;

}

void ff_flac_compute_autocorr(const int32_t *data, int len, int lag,

                              double *autoc)

{

    int i, j;

    double tmp[len + lag + 1];

    double *data1= tmp + lag;



    apply_welch_window(data, len, data1);



    for(j=0; j<lag; j++)

        data1[j-lag]= 0.0;

    data1[len] = 0.0;



    for(j=0; j<lag; j+=2){

        double sum0 = 1.0, sum1 = 1.0;

        for(i=0; i<len; i++){

            sum0 += data1[i] * data1[i-j];

            sum1 += data1[i] * data1[i-j-1];

        }

        autoc[j  ] = sum0;

        autoc[j+1] = sum1;

    }



    if(j==lag){

        double sum = 1.0;

        for(i=0; i<len; i+=2){

            sum += data1[i  ] * data1[i-j  ]

                 + data1[i+1] * data1[i-j+1];

        }

        autoc[j] = sum;

    }

}

static unsigned int rms(const int *data)

{

    int x;

    unsigned int res = 0x10000;

    int b = 0;



    for (x=0; x<10; x++) {

        res = (((0x1000000 - (*data) * (*data)) >> 12) * res) >> 12;



        if (res == 0)

            return 0;



        while (res <= 0x3fff) {

            b++;

            res <<= 2;

        }

        data++;

    }



    if (res > 0)

        res = t_sqrt(res);



    res >>= (b + 10);

    return res;

}

static void mm_decode_inter(MmContext * s, int half_horiz, int half_vert, const uint8_t *buf, int buf_size)
{
    const int data_ptr = 2 + AV_RL16(&buf[0]);
    int d, r, y;
    d = data_ptr; r = 2; y = 0;
    while(r < data_ptr) {
        int i, j;
        int length = buf[r] & 0x7f;
        int x = buf[r+1] + ((buf[r] & 0x80) << 1);
        r += 2;
        if (length==0) {
            y += x;
            continue;
        }
        for(i=0; i<length; i++) {
            for(j=0; j<8; j++) {
                int replace = (buf[r+i] >> (7-j)) & 1;
                if (replace) {
                    int color = buf[d];
                    s->frame.data[0][y*s->frame.linesize[0] + x] = color;
                    if (half_horiz)
                        s->frame.data[0][y*s->frame.linesize[0] + x + 1] = color;
                    if (half_vert) {
                        s->frame.data[0][(y+1)*s->frame.linesize[0] + x] = color;
                        if (half_horiz)
                            s->frame.data[0][(y+1)*s->frame.linesize[0] + x + 1] = color;
                    }
                    d++;
                }
                x += 1 + half_horiz;
            }
        }
        r += length;
        y += 1 + half_vert;
    }
}

