static inline int svq3_mc_dir(SVQ3Context *s, int size, int mode,

                              int dir, int avg)

{

    int i, j, k, mx, my, dx, dy, x, y;

    const int part_width    = ((size & 5) == 4) ? 4 : 16 >> (size & 1);

    const int part_height   = 16 >> ((unsigned)(size + 1) / 3);

    const int extra_width   = (mode == PREDICT_MODE) ? -16 * 6 : 0;

    const int h_edge_pos    = 6 * (s->h_edge_pos - part_width)  - extra_width;

    const int v_edge_pos    = 6 * (s->v_edge_pos - part_height) - extra_width;



    for (i = 0; i < 16; i += part_height)

        for (j = 0; j < 16; j += part_width) {

            const int b_xy = (4 * s->mb_x + (j >> 2)) +

                             (4 * s->mb_y + (i >> 2)) * s->b_stride;

            int dxy;

            x = 16 * s->mb_x + j;

            y = 16 * s->mb_y + i;

            k = (j >> 2 & 1) + (i >> 1 & 2) +

                (j >> 1 & 4) + (i      & 8);



            if (mode != PREDICT_MODE) {

                svq3_pred_motion(s, k, part_width >> 2, dir, 1, &mx, &my);

            } else {

                mx = s->next_pic->motion_val[0][b_xy][0] << 1;

                my = s->next_pic->motion_val[0][b_xy][1] << 1;



                if (dir == 0) {

                    mx = mx * s->frame_num_offset /

                         s->prev_frame_num_offset + 1 >> 1;

                    my = my * s->frame_num_offset /

                         s->prev_frame_num_offset + 1 >> 1;

                } else {

                    mx = mx * (s->frame_num_offset - s->prev_frame_num_offset) /

                         s->prev_frame_num_offset + 1 >> 1;

                    my = my * (s->frame_num_offset - s->prev_frame_num_offset) /

                         s->prev_frame_num_offset + 1 >> 1;

                }

            }



            /* clip motion vector prediction to frame border */

            mx = av_clip(mx, extra_width - 6 * x, h_edge_pos - 6 * x);

            my = av_clip(my, extra_width - 6 * y, v_edge_pos - 6 * y);



            /* get (optional) motion vector differential */

            if (mode == PREDICT_MODE) {

                dx = dy = 0;

            } else {

                dy = get_interleaved_se_golomb(&s->gb_slice);

                dx = get_interleaved_se_golomb(&s->gb_slice);



                if (dx != (int16_t)dx || dy != (int16_t)dy) {

                    av_log(s->avctx, AV_LOG_ERROR, "invalid MV vlc\n");

                    return -1;

                }

            }



            /* compute motion vector */

            if (mode == THIRDPEL_MODE) {

                int fx, fy;

                mx  = (mx + 1 >> 1) + dx;

                my  = (my + 1 >> 1) + dy;

                fx  = (unsigned)(mx + 0x30000) / 3 - 0x10000;

                fy  = (unsigned)(my + 0x30000) / 3 - 0x10000;

                dxy = (mx - 3 * fx) + 4 * (my - 3 * fy);



                svq3_mc_dir_part(s, x, y, part_width, part_height,

                                 fx, fy, dxy, 1, dir, avg);

                mx += mx;

                my += my;

            } else if (mode == HALFPEL_MODE || mode == PREDICT_MODE) {

                mx  = (unsigned)(mx + 1 + 0x30000) / 3 + dx - 0x10000;

                my  = (unsigned)(my + 1 + 0x30000) / 3 + dy - 0x10000;

                dxy = (mx & 1) + 2 * (my & 1);



                svq3_mc_dir_part(s, x, y, part_width, part_height,

                                 mx >> 1, my >> 1, dxy, 0, dir, avg);

                mx *= 3;

                my *= 3;

            } else {

                mx = (unsigned)(mx + 3 + 0x60000) / 6 + dx - 0x10000;

                my = (unsigned)(my + 3 + 0x60000) / 6 + dy - 0x10000;



                svq3_mc_dir_part(s, x, y, part_width, part_height,

                                 mx, my, 0, 0, dir, avg);

                mx *= 6;

                my *= 6;

            }



            /* update mv_cache */

            if (mode != PREDICT_MODE) {

                int32_t mv = pack16to32(mx, my);



                if (part_height == 8 && i < 8) {

                    AV_WN32A(s->mv_cache[dir][scan8[k] + 1 * 8], mv);



                    if (part_width == 8 && j < 8)

                        AV_WN32A(s->mv_cache[dir][scan8[k] + 1 + 1 * 8], mv);

                }

                if (part_width == 8 && j < 8)

                    AV_WN32A(s->mv_cache[dir][scan8[k] + 1], mv);

                if (part_width == 4 || part_height == 4)

                    AV_WN32A(s->mv_cache[dir][scan8[k]], mv);

            }



            /* write back motion vectors */

            fill_rectangle(s->cur_pic->motion_val[dir][b_xy],

                           part_width >> 2, part_height >> 2, s->b_stride,

                           pack16to32(mx, my), 4);

        }



    return 0;

}

static int mpegts_probe(AVProbeData *p)

{

    const int size = p->buf_size;

    int maxscore = 0;

    int sumscore = 0;

    int i;

    int check_count = size / TS_FEC_PACKET_SIZE;

#define CHECK_COUNT 10

#define CHECK_BLOCK 100



    if (check_count < CHECK_COUNT)

        return 0;



    for (i = 0; i<check_count; i+=CHECK_BLOCK) {

        int left = FFMIN(check_count - i, CHECK_BLOCK);

        int score      = analyze(p->buf + TS_PACKET_SIZE     *i, TS_PACKET_SIZE     *left, TS_PACKET_SIZE     , NULL, 1);

        int dvhs_score = analyze(p->buf + TS_DVHS_PACKET_SIZE*i, TS_DVHS_PACKET_SIZE*left, TS_DVHS_PACKET_SIZE, NULL, 1);

        int fec_score  = analyze(p->buf + TS_FEC_PACKET_SIZE *i, TS_FEC_PACKET_SIZE *left, TS_FEC_PACKET_SIZE , NULL, 1);

        score = FFMAX3(score, dvhs_score, fec_score);

        sumscore += score;

        maxscore = FFMAX(maxscore, score);

    }



    sumscore = sumscore * CHECK_COUNT / check_count;

    maxscore = maxscore * CHECK_COUNT / CHECK_BLOCK;



    av_dlog(0, "TS score: %d %d\n", sumscore, maxscore);



    if      (sumscore > 6) return AVPROBE_SCORE_MAX   + sumscore - CHECK_COUNT;

    else if (maxscore > 6) return AVPROBE_SCORE_MAX/2 + sumscore - CHECK_COUNT;

    else

        return 0;

}

static inline int mpeg4_decode_block(MpegEncContext * s, DCTELEM * block,

                              int n, int coded, int intra, int rvlc)

{

    int level, i, last, run;

    int dc_pred_dir;

    RLTable * rl;

    RL_VLC_ELEM * rl_vlc;

    const uint8_t * scan_table;

    int qmul, qadd;



    //Note intra & rvlc should be optimized away if this is inlined



    if(intra) {

      if(s->qscale < s->intra_dc_threshold){

        /* DC coef */

        if(s->partitioned_frame){

            level = s->dc_val[0][ s->block_index[n] ];

            if(n<4) level= FASTDIV((level + (s->y_dc_scale>>1)), s->y_dc_scale);

            else    level= FASTDIV((level + (s->c_dc_scale>>1)), s->c_dc_scale);

            dc_pred_dir= (s->pred_dir_table[s->mb_x + s->mb_y*s->mb_stride]<<n)&32;

        }else{

            level = mpeg4_decode_dc(s, n, &dc_pred_dir);

            if (level < 0)

                return -1;

        }

        block[0] = level;

        i = 0;

      }else{

            i = -1;

            ff_mpeg4_pred_dc(s, n, 0, &dc_pred_dir, 0);

      }

        if (!coded)

            goto not_coded;



        if(rvlc){

            rl = &rvlc_rl_intra;

            rl_vlc = rvlc_rl_intra.rl_vlc[0];

        }else{

            rl = &rl_intra;

            rl_vlc = rl_intra.rl_vlc[0];

        }

        if (s->ac_pred) {

            if (dc_pred_dir == 0)

                scan_table = s->intra_v_scantable.permutated; /* left */

            else

                scan_table = s->intra_h_scantable.permutated; /* top */

        } else {

            scan_table = s->intra_scantable.permutated;

        }

        qmul=1;

        qadd=0;

    } else {

        i = -1;

        if (!coded) {

            s->block_last_index[n] = i;

            return 0;

        }

        if(rvlc) rl = &rvlc_rl_inter;

        else     rl = &rl_inter;



        scan_table = s->intra_scantable.permutated;



        if(s->mpeg_quant){

            qmul=1;

            qadd=0;

            if(rvlc){

                rl_vlc = rvlc_rl_inter.rl_vlc[0];

            }else{

                rl_vlc = rl_inter.rl_vlc[0];

            }

        }else{

            qmul = s->qscale << 1;

            qadd = (s->qscale - 1) | 1;

            if(rvlc){

                rl_vlc = rvlc_rl_inter.rl_vlc[s->qscale];

            }else{

                rl_vlc = rl_inter.rl_vlc[s->qscale];

            }

        }

    }

  {

    OPEN_READER(re, &s->gb);

    for(;;) {

        UPDATE_CACHE(re, &s->gb);

        GET_RL_VLC(level, run, re, &s->gb, rl_vlc, TEX_VLC_BITS, 2, 0);

        if (level==0) {

          /* escape */

          if(rvlc){

                if(SHOW_UBITS(re, &s->gb, 1)==0){

                    av_log(s->avctx, AV_LOG_ERROR, "1. marker bit missing in rvlc esc\n");

                    return -1;

                }; SKIP_CACHE(re, &s->gb, 1);



                last=  SHOW_UBITS(re, &s->gb, 1); SKIP_CACHE(re, &s->gb, 1);

                run=   SHOW_UBITS(re, &s->gb, 6); LAST_SKIP_CACHE(re, &s->gb, 6);

                SKIP_COUNTER(re, &s->gb, 1+1+6);

                UPDATE_CACHE(re, &s->gb);



                if(SHOW_UBITS(re, &s->gb, 1)==0){

                    av_log(s->avctx, AV_LOG_ERROR, "2. marker bit missing in rvlc esc\n");

                    return -1;

                }; SKIP_CACHE(re, &s->gb, 1);



                level= SHOW_UBITS(re, &s->gb, 11); SKIP_CACHE(re, &s->gb, 11);



                if(SHOW_UBITS(re, &s->gb, 5)!=0x10){

                    av_log(s->avctx, AV_LOG_ERROR, "reverse esc missing\n");

                    return -1;

                }; SKIP_CACHE(re, &s->gb, 5);



                level=  level * qmul + qadd;

                level = (level ^ SHOW_SBITS(re, &s->gb, 1)) - SHOW_SBITS(re, &s->gb, 1); LAST_SKIP_CACHE(re, &s->gb, 1);

                SKIP_COUNTER(re, &s->gb, 1+11+5+1);



                i+= run + 1;

                if(last) i+=192;

          }else{

            int cache;

            cache= GET_CACHE(re, &s->gb);



            if(IS_3IV1)

                cache ^= 0xC0000000;



            if (cache&0x80000000) {

                if (cache&0x40000000) {

                    /* third escape */

                    SKIP_CACHE(re, &s->gb, 2);

                    last=  SHOW_UBITS(re, &s->gb, 1); SKIP_CACHE(re, &s->gb, 1);

                    run=   SHOW_UBITS(re, &s->gb, 6); LAST_SKIP_CACHE(re, &s->gb, 6);

                    SKIP_COUNTER(re, &s->gb, 2+1+6);

                    UPDATE_CACHE(re, &s->gb);



                    if(IS_3IV1){

                        level= SHOW_SBITS(re, &s->gb, 12); LAST_SKIP_BITS(re, &s->gb, 12);

                    }else{

                        if(SHOW_UBITS(re, &s->gb, 1)==0){

                            av_log(s->avctx, AV_LOG_ERROR, "1. marker bit missing in 3. esc\n");

                            return -1;

                        }; SKIP_CACHE(re, &s->gb, 1);



                        level= SHOW_SBITS(re, &s->gb, 12); SKIP_CACHE(re, &s->gb, 12);



                        if(SHOW_UBITS(re, &s->gb, 1)==0){

                            av_log(s->avctx, AV_LOG_ERROR, "2. marker bit missing in 3. esc\n");

                            return -1;

                        }; LAST_SKIP_CACHE(re, &s->gb, 1);



                        SKIP_COUNTER(re, &s->gb, 1+12+1);

                    }



#if 0

                    if(s->error_resilience >= FF_ER_COMPLIANT){

                        const int abs_level= ABS(level);

                        if(abs_level<=MAX_LEVEL && run<=MAX_RUN){

                            const int run1= run - rl->max_run[last][abs_level] - 1;

                            if(abs_level <= rl->max_level[last][run]){

                                av_log(s->avctx, AV_LOG_ERROR, "illegal 3. esc, vlc encoding possible\n");

                                return -1;

                            }

                            if(s->error_resilience > FF_ER_COMPLIANT){

                                if(abs_level <= rl->max_level[last][run]*2){

                                    av_log(s->avctx, AV_LOG_ERROR, "illegal 3. esc, esc 1 encoding possible\n");

                                    return -1;

                                }

                                if(run1 >= 0 && abs_level <= rl->max_level[last][run1]){

                                    av_log(s->avctx, AV_LOG_ERROR, "illegal 3. esc, esc 2 encoding possible\n");

                                    return -1;

                                }

                            }

                        }

                    }

#endif

                    if (level>0) level= level * qmul + qadd;

                    else         level= level * qmul - qadd;



                    if((unsigned)(level + 2048) > 4095){

                        if(s->error_resilience > FF_ER_COMPLIANT){

                            if(level > 2560 || level<-2560){

                                av_log(s->avctx, AV_LOG_ERROR, "|level| overflow in 3. esc, qp=%d\n", s->qscale);

                                return -1;

                            }

                        }

                        level= level<0 ? -2048 : 2047;

                    }



                    i+= run + 1;

                    if(last) i+=192;

                } else {

                    /* second escape */

#if MIN_CACHE_BITS < 20

                    LAST_SKIP_BITS(re, &s->gb, 2);

                    UPDATE_CACHE(re, &s->gb);

#else

                    SKIP_BITS(re, &s->gb, 2);

#endif

                    GET_RL_VLC(level, run, re, &s->gb, rl_vlc, TEX_VLC_BITS, 2, 1);

                    i+= run + rl->max_run[run>>7][level/qmul] +1; //FIXME opt indexing

                    level = (level ^ SHOW_SBITS(re, &s->gb, 1)) - SHOW_SBITS(re, &s->gb, 1);

                    LAST_SKIP_BITS(re, &s->gb, 1);

                }

            } else {

                /* first escape */

#if MIN_CACHE_BITS < 19

                LAST_SKIP_BITS(re, &s->gb, 1);

                UPDATE_CACHE(re, &s->gb);

#else

                SKIP_BITS(re, &s->gb, 1);

#endif

                GET_RL_VLC(level, run, re, &s->gb, rl_vlc, TEX_VLC_BITS, 2, 1);

                i+= run;

                level = level + rl->max_level[run>>7][(run-1)&63] * qmul;//FIXME opt indexing

                level = (level ^ SHOW_SBITS(re, &s->gb, 1)) - SHOW_SBITS(re, &s->gb, 1);

                LAST_SKIP_BITS(re, &s->gb, 1);

            }

          }

        } else {

            i+= run;

            level = (level ^ SHOW_SBITS(re, &s->gb, 1)) - SHOW_SBITS(re, &s->gb, 1);

            LAST_SKIP_BITS(re, &s->gb, 1);

        }

        if (i > 62){

            i-= 192;

            if(i&(~63)){

                av_log(s->avctx, AV_LOG_ERROR, "ac-tex damaged at %d %d\n", s->mb_x, s->mb_y);

                return -1;

            }



            block[scan_table[i]] = level;

            break;

        }



        block[scan_table[i]] = level;

    }

    CLOSE_READER(re, &s->gb);

  }

 not_coded:

    if (intra) {

        if(s->qscale >= s->intra_dc_threshold){

            block[0] = ff_mpeg4_pred_dc(s, n, block[0], &dc_pred_dir, 0);



            i -= i>>31; //if(i == -1) i=0;

        }



        mpeg4_pred_ac(s, block, n, dc_pred_dir);

        if (s->ac_pred) {

            i = 63; /* XXX: not optimal */

        }

    }

    s->block_last_index[n] = i;

    return 0;

}

