static int decode_coeffs(WMAProDecodeCtx *s, int c)

{

    /* Integers 0..15 as single-precision floats.  The table saves a

       costly int to float conversion, and storing the values as

       integers allows fast sign-flipping. */

    static const int fval_tab[16] = {

        0x00000000, 0x3f800000, 0x40000000, 0x40400000,

        0x40800000, 0x40a00000, 0x40c00000, 0x40e00000,

        0x41000000, 0x41100000, 0x41200000, 0x41300000,

        0x41400000, 0x41500000, 0x41600000, 0x41700000,

    };

    int vlctable;

    VLC* vlc;

    WMAProChannelCtx* ci = &s->channel[c];

    int rl_mode = 0;

    int cur_coeff = 0;

    int num_zeros = 0;

    const uint16_t* run;

    const float* level;



    av_dlog(s->avctx, "decode coefficients for channel %i\n", c);



    vlctable = get_bits1(&s->gb);

    vlc = &coef_vlc[vlctable];



    if (vlctable) {

        run = coef1_run;

        level = coef1_level;

    } else {

        run = coef0_run;

        level = coef0_level;

    }



    /** decode vector coefficients (consumes up to 167 bits per iteration for

      4 vector coded large values) */

    while ((s->transmit_num_vec_coeffs || !rl_mode) &&

           (cur_coeff + 3 < ci->num_vec_coeffs)) {

        int vals[4];

        int i;

        unsigned int idx;



        idx = get_vlc2(&s->gb, vec4_vlc.table, VLCBITS, VEC4MAXDEPTH);



        if (idx == HUFF_VEC4_SIZE - 1) {

            for (i = 0; i < 4; i += 2) {

                idx = get_vlc2(&s->gb, vec2_vlc.table, VLCBITS, VEC2MAXDEPTH);

                if (idx == HUFF_VEC2_SIZE - 1) {

                    int v0, v1;

                    v0 = get_vlc2(&s->gb, vec1_vlc.table, VLCBITS, VEC1MAXDEPTH);

                    if (v0 == HUFF_VEC1_SIZE - 1)

                        v0 += ff_wma_get_large_val(&s->gb);

                    v1 = get_vlc2(&s->gb, vec1_vlc.table, VLCBITS, VEC1MAXDEPTH);

                    if (v1 == HUFF_VEC1_SIZE - 1)

                        v1 += ff_wma_get_large_val(&s->gb);

                    ((float*)vals)[i  ] = v0;

                    ((float*)vals)[i+1] = v1;

                } else {

                    vals[i]   = fval_tab[symbol_to_vec2[idx] >> 4 ];

                    vals[i+1] = fval_tab[symbol_to_vec2[idx] & 0xF];

                }

            }

        } else {

            vals[0] = fval_tab[ symbol_to_vec4[idx] >> 12      ];

            vals[1] = fval_tab[(symbol_to_vec4[idx] >> 8) & 0xF];

            vals[2] = fval_tab[(symbol_to_vec4[idx] >> 4) & 0xF];

            vals[3] = fval_tab[ symbol_to_vec4[idx]       & 0xF];

        }



        /** decode sign */

        for (i = 0; i < 4; i++) {

            if (vals[i]) {

                int sign = get_bits1(&s->gb) - 1;

                *(uint32_t*)&ci->coeffs[cur_coeff] = vals[i] ^ sign<<31;

                num_zeros = 0;

            } else {

                ci->coeffs[cur_coeff] = 0;

                /** switch to run level mode when subframe_len / 128 zeros

                    were found in a row */

                rl_mode |= (++num_zeros > s->subframe_len >> 8);

            }

            ++cur_coeff;

        }

    }



    /** decode run level coded coefficients */

    if (cur_coeff < s->subframe_len) {

        memset(&ci->coeffs[cur_coeff], 0,

               sizeof(*ci->coeffs) * (s->subframe_len - cur_coeff));

        if (ff_wma_run_level_decode(s->avctx, &s->gb, vlc,

                                    level, run, 1, ci->coeffs,

                                    cur_coeff, s->subframe_len,

                                    s->subframe_len, s->esc_len, 0))

            return AVERROR_INVALIDDATA;

    }



    return 0;

}

static void decode_delta_e(uint8_t *dst,

                           const uint8_t *buf, const uint8_t *buf_end,

                           int w, int flag, int bpp, int dst_size)

{

    int planepitch = FFALIGN(w, 16) >> 3;

    int pitch = planepitch * bpp;

    int planepitch_byte = (w + 7) / 8;

    unsigned entries, ofssrc;

    GetByteContext gb, ptrs;

    PutByteContext pb;

    int k;



    if (buf_end - buf <= 4 * bpp)

        return;



    bytestream2_init_writer(&pb, dst, dst_size);

    bytestream2_init(&ptrs, buf, bpp * 4);



    for (k = 0; k < bpp; k++) {

        ofssrc = bytestream2_get_be32(&ptrs);



        if (!ofssrc)

            continue;



        if (ofssrc >= buf_end - buf)

            continue;



        bytestream2_init(&gb, buf + ofssrc, buf_end - (buf + ofssrc));



        entries = bytestream2_get_be16(&gb);

        while (entries) {

            int16_t opcode  = bytestream2_get_be16(&gb);

            unsigned offset = bytestream2_get_be32(&gb);



            bytestream2_seek_p(&pb, (offset / planepitch_byte) * pitch + (offset % planepitch_byte) + k * planepitch, SEEK_SET);

            if (opcode >= 0) {

                uint16_t x = bytestream2_get_be16(&gb);

                while (opcode && bytestream2_get_bytes_left_p(&pb) > 0) {

                    bytestream2_put_be16(&pb, x);

                    bytestream2_skip_p(&pb, pitch - 2);

                    opcode--;

                }

            } else {

                opcode = -opcode;

                while (opcode && bytestream2_get_bytes_left(&gb) > 0) {

                    bytestream2_put_be16(&pb, bytestream2_get_be16(&gb));

                    bytestream2_skip_p(&pb, pitch - 2);

                    opcode--;

                }

            }

            entries--;

        }

    }

}

static void filter1(int32_t *dst, const int32_t *src, int32_t coeff, ptrdiff_t len)

{

    int i;



    for (i = 0; i < len; i++)

        dst[i] -= mul23(src[i], coeff);

}

static int mpegts_write_end(AVFormatContext *s)

{

    MpegTSWrite *ts = s->priv_data;

    MpegTSWriteStream *ts_st;

    MpegTSService *service;

    AVStream *st;

    int i;



    /* flush current packets */

    for(i = 0; i < s->nb_streams; i++) {

        st = s->streams[i];

        ts_st = st->priv_data;

        if (ts_st->payload_index > 0) {

            mpegts_write_pes(s, st, ts_st->payload, ts_st->payload_index,

                             ts_st->payload_pts);

        }

    }

    put_flush_packet(&s->pb);



    for(i = 0; i < ts->nb_services; i++) {

        service = ts->services[i];

        av_freep(&service->provider_name);

        av_freep(&service->name);

        av_free(service);

    }

    av_free(ts->services);



    for(i = 0; i < s->nb_streams; i++) {

        st = s->streams[i];

        av_free(st->priv_data);

    }

    return 0;

}

static int microdvd_probe(AVProbeData *p)

{

    unsigned char c;

    const uint8_t *ptr = p->buf;

    int i;



    if (AV_RB24(ptr) == 0xEFBBBF)

        ptr += 3;  /* skip UTF-8 BOM */



    for (i=0; i<3; i++) {

        if (sscanf(ptr, "{%*d}{}%c",     &c) != 1 &&

            sscanf(ptr, "{%*d}{%*d}%c",  &c) != 1 &&

            sscanf(ptr, "{DEFAULT}{}%c", &c) != 1)

            return 0;

        ptr += strcspn(ptr, "\n") + 1;

    }

    return AVPROBE_SCORE_MAX;

}

static void draw_char(AVCodecContext *avctx, int c)

{

    AnsiContext *s = avctx->priv_data;

    int fg = s->fg;

    int bg = s->bg;



    if ((s->attributes & ATTR_BOLD))

        fg += 8;

    if ((s->attributes & ATTR_BLINK))

        bg += 8;

    if ((s->attributes & ATTR_REVERSE))

        FFSWAP(int, fg, bg);

    if ((s->attributes & ATTR_CONCEALED))

        fg = bg;

    ff_draw_pc_font(s->frame->data[0] + s->y * s->frame->linesize[0] + s->x,

                    s->frame->linesize[0], s->font, s->font_height, c, fg, bg);

    s->x += FONT_WIDTH;

    if (s->x >= avctx->width) {

        s->x = 0;

        hscroll(avctx);

    }

}

static av_always_inline int vorbis_residue_decode_internal(vorbis_context *vc,

                                                           vorbis_residue *vr,

                                                           unsigned ch,

                                                           uint8_t *do_not_decode,

                                                           float *vec,

                                                           unsigned vlen,

                                                           unsigned ch_left,

                                                           int vr_type)

{

    GetBitContext *gb = &vc->gb;

    unsigned c_p_c        = vc->codebooks[vr->classbook].dimensions;

    uint8_t *classifs = vr->classifs;

    unsigned pass, ch_used, i, j, k, l;

    unsigned max_output = (ch - 1) * vlen;

    int ptns_to_read = vr->ptns_to_read;



    if (vr_type == 2) {

        for (j = 1; j < ch; ++j)

            do_not_decode[0] &= do_not_decode[j];  // FIXME - clobbering input

        if (do_not_decode[0])

            return 0;

        ch_used = 1;

        max_output += vr->end / ch;

    } else {

        ch_used = ch;

        max_output += vr->end;

    }



    if (max_output > ch_left * vlen) {

        av_log(vc->avctx, AV_LOG_ERROR, "Insufficient output buffer\n");

        return AVERROR_INVALIDDATA;

    }



    av_dlog(NULL, " residue type 0/1/2 decode begin, ch: %d  cpc %d  \n", ch, c_p_c);



    for (pass = 0; pass <= vr->maxpass; ++pass) { // FIXME OPTIMIZE?

        int voffset, partition_count, j_times_ptns_to_read;



        voffset = vr->begin;

        for (partition_count = 0; partition_count < ptns_to_read;) {  // SPEC        error

            if (!pass) {

                setup_classifs(vc, vr, do_not_decode, ch_used, partition_count);

            }

            for (i = 0; (i < c_p_c) && (partition_count < ptns_to_read); ++i) {

                for (j_times_ptns_to_read = 0, j = 0; j < ch_used; ++j) {

                    unsigned voffs;



                    if (!do_not_decode[j]) {

                        unsigned vqclass = classifs[j_times_ptns_to_read + partition_count];

                        int vqbook  = vr->books[vqclass][pass];



                        if (vqbook >= 0 && vc->codebooks[vqbook].codevectors) {

                            unsigned coffs;

                            unsigned dim  = vc->codebooks[vqbook].dimensions;

                            unsigned step = FASTDIV(vr->partition_size << 1, dim << 1);

                            vorbis_codebook codebook = vc->codebooks[vqbook];



                            if (vr_type == 0) {



                                voffs = voffset+j*vlen;

                                for (k = 0; k < step; ++k) {

                                    coffs = get_vlc2(gb, codebook.vlc.table, codebook.nb_bits, 3) * dim;

                                    for (l = 0; l < dim; ++l)

                                        vec[voffs + k + l * step] += codebook.codevectors[coffs + l];

                                }

                            } else if (vr_type == 1) {

                                voffs = voffset + j * vlen;

                                for (k = 0; k < step; ++k) {

                                    coffs = get_vlc2(gb, codebook.vlc.table, codebook.nb_bits, 3) * dim;

                                    for (l = 0; l < dim; ++l, ++voffs) {

                                        vec[voffs]+=codebook.codevectors[coffs+l];



                                        av_dlog(NULL, " pass %d offs: %d curr: %f change: %f cv offs.: %d  \n",

                                                pass, voffs, vec[voffs], codebook.codevectors[coffs+l], coffs);

                                    }

                                }

                            } else if (vr_type == 2 && ch == 2 && (voffset & 1) == 0 && (dim & 1) == 0) { // most frequent case optimized

                                voffs = voffset >> 1;



                                if (dim == 2) {

                                    for (k = 0; k < step; ++k) {

                                        coffs = get_vlc2(gb, codebook.vlc.table, codebook.nb_bits, 3) * 2;

                                        vec[voffs + k       ] += codebook.codevectors[coffs    ];

                                        vec[voffs + k + vlen] += codebook.codevectors[coffs + 1];

                                    }

                                } else if (dim == 4) {

                                    for (k = 0; k < step; ++k, voffs += 2) {

                                        coffs = get_vlc2(gb, codebook.vlc.table, codebook.nb_bits, 3) * 4;

                                        vec[voffs           ] += codebook.codevectors[coffs    ];

                                        vec[voffs + 1       ] += codebook.codevectors[coffs + 2];

                                        vec[voffs + vlen    ] += codebook.codevectors[coffs + 1];

                                        vec[voffs + vlen + 1] += codebook.codevectors[coffs + 3];

                                    }

                                } else

                                for (k = 0; k < step; ++k) {

                                    coffs = get_vlc2(gb, codebook.vlc.table, codebook.nb_bits, 3) * dim;

                                    for (l = 0; l < dim; l += 2, voffs++) {

                                        vec[voffs       ] += codebook.codevectors[coffs + l    ];

                                        vec[voffs + vlen] += codebook.codevectors[coffs + l + 1];



                                        av_dlog(NULL, " pass %d offs: %d curr: %f change: %f cv offs.: %d+%d  \n",

                                                pass, voffset / ch + (voffs % ch) * vlen,

                                                vec[voffset / ch + (voffs % ch) * vlen],

                                                codebook.codevectors[coffs + l], coffs, l);

                                    }

                                }



                            } else if (vr_type == 2) {

                                unsigned voffs_div = FASTDIV(voffset << 1, ch <<1);

                                unsigned voffs_mod = voffset - voffs_div * ch;



                                for (k = 0; k < step; ++k) {

                                    coffs = get_vlc2(gb, codebook.vlc.table, codebook.nb_bits, 3) * dim;

                                    for (l = 0; l < dim; ++l) {

                                        vec[voffs_div + voffs_mod * vlen] +=

                                            codebook.codevectors[coffs + l];



                                        av_dlog(NULL, " pass %d offs: %d curr: %f change: %f cv offs.: %d+%d  \n",

                                                pass, voffs_div + voffs_mod * vlen,

                                                vec[voffs_div + voffs_mod * vlen],

                                                codebook.codevectors[coffs + l], coffs, l);



                                        if (++voffs_mod == ch) {

                                            voffs_div++;

                                            voffs_mod = 0;

                                        }

                                    }

                                }

                            }

                        }

                    }

                    j_times_ptns_to_read += ptns_to_read;

                }

                ++partition_count;

                voffset += vr->partition_size;

            }

        }

    }

    return 0;

}

static int init_quantization_noise(DCAEncContext *c, int noise)

{

    int ch, band, ret = 0;



    c->consumed_bits = 132 + 493 * c->fullband_channels;

    if (c->lfe_channel)

        c->consumed_bits += 72;



    /* attempt to guess the bit distribution based on the prevoius frame */

    for (ch = 0; ch < c->fullband_channels; ch++) {

        for (band = 0; band < 32; band++) {

            int snr_cb = c->peak_cb[band][ch] - c->band_masking_cb[band] - noise;



            if (snr_cb >= 1312) {

                c->abits[band][ch] = 26;

                ret |= USED_26ABITS;

            } else if (snr_cb >= 222) {

                c->abits[band][ch] = 8 + mul32(snr_cb - 222, 69000000);

                ret |= USED_NABITS;

            } else if (snr_cb >= 0) {

                c->abits[band][ch] = 2 + mul32(snr_cb, 106000000);

                ret |= USED_NABITS;

            } else {

                c->abits[band][ch] = 1;

                ret |= USED_1ABITS;

            }

        }

    }



    for (band = 0; band < 32; band++)

        for (ch = 0; ch < c->fullband_channels; ch++) {

            c->consumed_bits += bit_consumption[c->abits[band][ch]];

        }



    return ret;

}

