static int nppscale_resize(AVFilterContext *ctx, NPPScaleStageContext *stage,

                           AVFrame *out, AVFrame *in)

{

    NPPScaleContext *s = ctx->priv;

    NppStatus err;

    int i;



    for (i = 0; i < FF_ARRAY_ELEMS(in->data) && in->data[i]; i++) {

        int iw = stage->planes_in[i].width;

        int ih = stage->planes_in[i].height;

        int ow = stage->planes_out[i].width;

        int oh = stage->planes_out[i].height;



        err = nppiResizeSqrPixel_8u_C1R(in->data[i], (NppiSize){ iw, ih },

                                        in->linesize[i], (NppiRect){ 0, 0, iw, ih },

                                        out->data[i], out->linesize[i],

                                        (NppiRect){ 0, 0, ow, oh },

                                        (double)ow / iw, (double)oh / ih,

                                        0.0, 0.0, s->interp_algo);

        if (err != NPP_SUCCESS) {

            av_log(ctx, AV_LOG_ERROR, "NPP resize error: %d\n", err);

            return AVERROR_UNKNOWN;

        }

    }



    return 0;

}

static int init_report(const char *env)

{

    const char *filename_template = "%p-%t.log";

    char *key, *val;

    int ret, count = 0;

    time_t now;

    struct tm *tm;

    AVBPrint filename;



    if (report_file) /* already opened */

        return 0;

    time(&now);

    tm = localtime(&now);



    while (env && *env) {

        if ((ret = av_opt_get_key_value(&env, "=", ":", 0, &key, &val)) < 0) {

            if (count)

                av_log(NULL, AV_LOG_ERROR,

                       "Failed to parse FFREPORT environment variable: %s\n",

                       av_err2str(ret));

            break;

        }

        if (*env)

            env++;

        count++;

        if (!strcmp(key, "file")) {

            filename_template = val;

            val = NULL;

        } else {

            av_log(NULL, AV_LOG_ERROR, "Unknown key '%s' in FFREPORT\n", key);

        }

        av_free(val);

        av_free(key);

    }



    av_bprint_init(&filename, 0, 1);

    expand_filename_template(&filename, filename_template, tm);

    if (!av_bprint_is_complete(&filename)) {

        av_log(NULL, AV_LOG_ERROR, "Out of memory building report file name\n");

        return AVERROR(ENOMEM);

    }



    report_file = fopen(filename.str, "w");

    if (!report_file) {

        av_log(NULL, AV_LOG_ERROR, "Failed to open report \"%s\": %s\n",

               filename.str, strerror(errno));

        return AVERROR(errno);

    }

    av_log_set_callback(log_callback_report);

    av_log(NULL, AV_LOG_INFO,

           "%s started on %04d-%02d-%02d at %02d:%02d:%02d\n"

           "Report written to \"%s\"\n",

           program_name,

           tm->tm_year + 1900, tm->tm_mon + 1, tm->tm_mday,

           tm->tm_hour, tm->tm_min, tm->tm_sec,

           filename.str);

    av_log_set_level(FFMAX(av_log_get_level(), AV_LOG_VERBOSE));

    av_bprint_finalize(&filename, NULL);

    return 0;

}

void rgb15tobgr16(const uint8_t *src, uint8_t *dst, unsigned int src_size)

{

	unsigned i;

	unsigned num_pixels = src_size >> 1;



	for(i=0; i<num_pixels; i++)

	{

	    unsigned b,g,r;

	    register uint16_t rgb;

	    rgb = src[2*i];

	    r = rgb&0x1F;

	    g = (rgb&0x3E0)>>5;

	    b = (rgb&0x7C00)>>10;

	    dst[2*i] = (b&0x1F) | ((g&0x3F)<<5) | ((r&0x1F)<<11);

	}

}

void avformat_close_input(AVFormatContext **ps)

{

    AVFormatContext *s = *ps;

    AVIOContext *pb = (s->iformat->flags & AVFMT_NOFILE) || (s->flags & AVFMT_FLAG_CUSTOM_IO) ?

                       NULL : s->pb;

    flush_packet_queue(s);

    if (s->iformat->read_close)

        s->iformat->read_close(s);

    avformat_free_context(s);

    *ps = NULL;

    if (pb)

        avio_close(pb);

}

static int decode_frame(AVCodecContext *avctx,

                             void *data, int *data_size,

                             uint8_t *buf, int buf_size)

{

    H264Context *h = avctx->priv_data;

    MpegEncContext *s = &h->s;

    AVFrame *pict = data;

    int buf_index;



    s->flags= avctx->flags;

    s->flags2= avctx->flags2;



   /* no supplementary picture */

    if (buf_size == 0) {

        return 0;

    }



    if(s->flags&CODEC_FLAG_TRUNCATED){

        int next= find_frame_end(h, buf, buf_size);



        if( ff_combine_frame(&s->parse_context, next, &buf, &buf_size) < 0 )

            return buf_size;

//printf("next:%d buf_size:%d last_index:%d\n", next, buf_size, s->parse_context.last_index);

    }



    if(h->is_avc && !h->got_avcC) {

        int i, cnt, nalsize;

        unsigned char *p = avctx->extradata;

        if(avctx->extradata_size < 7) {

            av_log(avctx, AV_LOG_ERROR, "avcC too short\n");

            return -1;

        }

        if(*p != 1) {

            av_log(avctx, AV_LOG_ERROR, "Unknown avcC version %d\n", *p);

            return -1;

        }

        /* sps and pps in the avcC always have length coded with 2 bytes,

           so put a fake nal_length_size = 2 while parsing them */

        h->nal_length_size = 2;

        // Decode sps from avcC

        cnt = *(p+5) & 0x1f; // Number of sps

        p += 6;

        for (i = 0; i < cnt; i++) {

            nalsize = BE_16(p) + 2;

            if(decode_nal_units(h, p, nalsize) < 0) {

                av_log(avctx, AV_LOG_ERROR, "Decoding sps %d from avcC failed\n", i);

                return -1;

            }

            p += nalsize;

        }

        // Decode pps from avcC

        cnt = *(p++); // Number of pps

        for (i = 0; i < cnt; i++) {

            nalsize = BE_16(p) + 2;

            if(decode_nal_units(h, p, nalsize)  != nalsize) {

                av_log(avctx, AV_LOG_ERROR, "Decoding pps %d from avcC failed\n", i);

                return -1;

            }

            p += nalsize;

        }

        // Now store right nal length size, that will be use to parse all other nals

        h->nal_length_size = ((*(((char*)(avctx->extradata))+4))&0x03)+1;

        // Do not reparse avcC

        h->got_avcC = 1;

    }



    if(!h->is_avc && s->avctx->extradata_size && s->picture_number==0){

        if(decode_nal_units(h, s->avctx->extradata, s->avctx->extradata_size) < 0)

            return -1;

    }



    buf_index=decode_nal_units(h, buf, buf_size);

    if(buf_index < 0)

        return -1;



    //FIXME do something with unavailable reference frames



//    if(ret==FRAME_SKIPPED) return get_consumed_bytes(s, buf_index, buf_size);

    if(!s->current_picture_ptr){

        av_log(h->s.avctx, AV_LOG_DEBUG, "error, NO frame\n");

        return -1;

    }



    {

        Picture *out = s->current_picture_ptr;

#if 0 //decode order

        *data_size = sizeof(AVFrame);

#else

        /* Sort B-frames into display order */

        Picture *cur = s->current_picture_ptr;

        Picture *prev = h->delayed_output_pic;

        int out_idx = 0;

        int pics = 0;

        int out_of_order;

        int cross_idr = 0;

        int dropped_frame = 0;

        int i;



        if(h->sps.bitstream_restriction_flag

           && s->avctx->has_b_frames < h->sps.num_reorder_frames){

            s->avctx->has_b_frames = h->sps.num_reorder_frames;

            s->low_delay = 0;

        }



        while(h->delayed_pic[pics]) pics++;

        h->delayed_pic[pics++] = cur;

        if(cur->reference == 0)

            cur->reference = 1;



        for(i=0; h->delayed_pic[i]; i++)

            if(h->delayed_pic[i]->key_frame || h->delayed_pic[i]->poc==0)

                cross_idr = 1;



        out = h->delayed_pic[0];

        for(i=1; h->delayed_pic[i] && !h->delayed_pic[i]->key_frame; i++)

            if(h->delayed_pic[i]->poc < out->poc){

                out = h->delayed_pic[i];

                out_idx = i;

            }



        out_of_order = !cross_idr && prev && out->poc < prev->poc;

        if(prev && pics <= s->avctx->has_b_frames)

            out = prev;

        else if((out_of_order && pics-1 == s->avctx->has_b_frames && pics < 15)

           || (s->low_delay &&

            ((!cross_idr && prev && out->poc > prev->poc + 2)

             || cur->pict_type == B_TYPE)))

        {

            s->low_delay = 0;

            s->avctx->has_b_frames++;

            out = prev;

        }

        else if(out_of_order)

            out = prev;



        if(out_of_order || pics > s->avctx->has_b_frames){

            dropped_frame = (out != h->delayed_pic[out_idx]);

            for(i=out_idx; h->delayed_pic[i]; i++)

                h->delayed_pic[i] = h->delayed_pic[i+1];

        }



        if(prev == out && !dropped_frame)

            *data_size = 0;

        else

            *data_size = sizeof(AVFrame);

        if(prev && prev != out && prev->reference == 1)

            prev->reference = 0;

        h->delayed_output_pic = out;

#endif



        if(out)

            *pict= *(AVFrame*)out;

        else

            av_log(avctx, AV_LOG_DEBUG, "no picture\n");

    }



    assert(pict->data[0] || !*data_size);

    ff_print_debug_info(s, pict);

//printf("out %d\n", (int)pict->data[0]);

#if 0 //?



    /* Return the Picture timestamp as the frame number */

    /* we substract 1 because it is added on utils.c    */

    avctx->frame_number = s->picture_number - 1;

#endif

    return get_consumed_bytes(s, buf_index, buf_size);

}

int av_open_input_file(AVFormatContext **ic_ptr, const char *filename,

                       AVInputFormat *fmt,

                       int buf_size,

                       AVFormatParameters *ap)

{

    int err, probe_size;

    AVProbeData probe_data, *pd = &probe_data;

    ByteIOContext *pb = NULL;



    pd->filename = "";

    if (filename)

        pd->filename = filename;

    pd->buf = NULL;

    pd->buf_size = 0;



    if (!fmt) {

        /* guess format if no file can be opened */

        fmt = av_probe_input_format(pd, 0);

    }



    /* Do not open file if the format does not need it. XXX: specific

       hack needed to handle RTSP/TCP */

    if (!fmt || !(fmt->flags & AVFMT_NOFILE)) {

        /* if no file needed do not try to open one */

        if ((err=url_fopen(&pb, filename, URL_RDONLY)) < 0) {

            goto fail;

        }

        if (buf_size > 0) {

            url_setbufsize(pb, buf_size);

        }



        for(probe_size= PROBE_BUF_MIN; probe_size<=PROBE_BUF_MAX && !fmt; probe_size<<=1){

            int score= probe_size < PROBE_BUF_MAX ? AVPROBE_SCORE_MAX/4 : 0;

            /* read probe data */

            pd->buf= av_realloc(pd->buf, probe_size + AVPROBE_PADDING_SIZE);

            pd->buf_size = get_buffer(pb, pd->buf, probe_size);

            memset(pd->buf+pd->buf_size, 0, AVPROBE_PADDING_SIZE);

            if (url_fseek(pb, 0, SEEK_SET) < 0) {

                url_fclose(pb);

                if (url_fopen(&pb, filename, URL_RDONLY) < 0) {

                    pb = NULL;

                    err = AVERROR(EIO);

                    goto fail;

                }

            }

            /* guess file format */

            fmt = av_probe_input_format2(pd, 1, &score);

        }

        av_freep(&pd->buf);

    }



    /* if still no format found, error */

    if (!fmt) {

        err = AVERROR_NOFMT;

        goto fail;

    }



    /* check filename in case an image number is expected */

    if (fmt->flags & AVFMT_NEEDNUMBER) {

        if (!av_filename_number_test(filename)) {

            err = AVERROR_NUMEXPECTED;

            goto fail;

        }

    }

    err = av_open_input_stream(ic_ptr, pb, filename, fmt, ap);

    if (err)

        goto fail;

    return 0;

 fail:

    av_freep(&pd->buf);

    if (pb)

        url_fclose(pb);

    *ic_ptr = NULL;

    return err;



}

static int hevc_parse_slice_header(AVCodecParserContext *s, H2645NAL *nal,

                                   AVCodecContext *avctx)

{

    HEVCParserContext *ctx = s->priv_data;

    GetBitContext *gb = &nal->gb;



    HEVCPPS *pps;

    HEVCSPS *sps;

    unsigned int pps_id;



    get_bits1(gb);          // first slice in pic

    if (IS_IRAP_NAL(nal))

        get_bits1(gb);      // no output of prior pics



    pps_id = get_ue_golomb_long(gb);

    if (pps_id >= HEVC_MAX_PPS_COUNT || !ctx->ps.pps_list[pps_id]) {

        av_log(avctx, AV_LOG_ERROR, "PPS id out of range: %d\n", pps_id);

        return AVERROR_INVALIDDATA;

    }

    pps = (HEVCPPS*)ctx->ps.pps_list[pps_id]->data;

    sps = (HEVCSPS*)ctx->ps.sps_list[pps->sps_id]->data;



    /* export the stream parameters */

    s->coded_width  = sps->width;

    s->coded_height = sps->height;

    s->width        = sps->output_width;

    s->height       = sps->output_height;

    s->format       = sps->pix_fmt;

    avctx->profile  = sps->ptl.general_ptl.profile_idc;

    avctx->level    = sps->ptl.general_ptl.level_idc;



    /* ignore the rest for now*/



    return 0;

}

static int do_qsv_decode(AVCodecContext *avctx, QSVContext *q,

                  AVFrame *frame, int *got_frame,

                  AVPacket *avpkt)

{

    QSVFrame *out_frame;

    mfxFrameSurface1 *insurf;

    mfxFrameSurface1 *outsurf;

    mfxSyncPoint *sync;

    mfxBitstream bs = { { { 0 } } };

    int ret;

    int n_out_frames;

    int buffered = 0;

    int flush    = !avpkt->size || q->reinit_pending;



    if (!q->engine_ready) {

        ret = qsv_decode_init(avctx, q, avpkt);

        if (ret)

            return ret;

    }



    if (!flush) {

        if (av_fifo_size(q->input_fifo)) {

            /* we have got rest of previous packet into buffer */

            if (av_fifo_space(q->input_fifo) < avpkt->size) {

                ret = av_fifo_grow(q->input_fifo, avpkt->size);

                if (ret < 0)

                    return ret;

            }

            av_fifo_generic_write(q->input_fifo, avpkt->data, avpkt->size, NULL);

            bs.Data       = q->input_fifo->rptr;

            bs.DataLength = av_fifo_size(q->input_fifo);

            buffered = 1;

        } else {

            bs.Data       = avpkt->data;

            bs.DataLength = avpkt->size;

        }

        bs.MaxLength  = bs.DataLength;

        bs.TimeStamp  = avpkt->pts;

    }



    sync = av_mallocz(sizeof(*sync));

    if (!sync) {

        av_freep(&sync);

        return AVERROR(ENOMEM);

    }



    while (1) {

        ret = get_surface(avctx, q, &insurf);

        if (ret < 0)

            return ret;

        do {

            ret = MFXVideoDECODE_DecodeFrameAsync(q->session, flush ? NULL : &bs,

                                                  insurf, &outsurf, sync);

            if (ret != MFX_WRN_DEVICE_BUSY)

                break;

            av_usleep(500);

        } while (1);



        if (MFX_WRN_VIDEO_PARAM_CHANGED==ret) {

            /* TODO: handle here minor sequence header changing */

        } else if (MFX_ERR_INCOMPATIBLE_VIDEO_PARAM==ret) {

            av_fifo_reset(q->input_fifo);

            flush = q->reinit_pending = 1;

            continue;

        }



        if (*sync) {

            QSVFrame *out_frame = find_frame(q, outsurf);



            if (!out_frame) {

                av_freep(&sync);

                av_log(avctx, AV_LOG_ERROR,

                       "The returned surface does not correspond to any frame\n");

                return AVERROR_BUG;

            }



            out_frame->queued = 1;

            av_fifo_generic_write(q->async_fifo, &out_frame, sizeof(out_frame), NULL);

            av_fifo_generic_write(q->async_fifo, &sync,      sizeof(sync),      NULL);



            continue;

        } else {

            av_freep(&sync);

        }

        if (MFX_ERR_MORE_SURFACE != ret && ret < 0)

            break;

    }



    /* make sure we do not enter an infinite loop if the SDK

     * did not consume any data and did not return anything */

    if (!*sync && !bs.DataOffset && !flush) {

        av_log(avctx, AV_LOG_WARNING, "A decode call did not consume any data\n");

        bs.DataOffset = avpkt->size;

    }



    if (buffered) {

        qsv_fifo_relocate(q->input_fifo, bs.DataOffset);

    } else if (bs.DataOffset!=avpkt->size) {

        /* some data of packet was not consumed. store it to local buffer */

        av_fifo_generic_write(q->input_fifo, avpkt->data+bs.DataOffset,

                              avpkt->size - bs.DataOffset, NULL);

    }



    if (MFX_ERR_MORE_DATA!=ret && ret < 0) {

        av_freep(&sync);

        av_log(avctx, AV_LOG_ERROR, "Error %d during QSV decoding.\n", ret);

        return ff_qsv_error(ret);

    }

    n_out_frames = av_fifo_size(q->async_fifo) / (sizeof(out_frame)+sizeof(sync));



    if (n_out_frames > q->async_depth || (flush && n_out_frames) ) {

        AVFrame *src_frame;



        av_fifo_generic_read(q->async_fifo, &out_frame, sizeof(out_frame), NULL);

        av_fifo_generic_read(q->async_fifo, &sync,      sizeof(sync),      NULL);

        out_frame->queued = 0;



        do {

            ret = MFXVideoCORE_SyncOperation(q->session, *sync, 1000);

        } while (ret == MFX_WRN_IN_EXECUTION);



        av_freep(&sync);



        src_frame = out_frame->frame;



        ret = av_frame_ref(frame, src_frame);

        if (ret < 0)

            return ret;



        outsurf = out_frame->surface;



        frame->pkt_pts = frame->pts = outsurf->Data.TimeStamp;



        frame->repeat_pict =

            outsurf->Info.PicStruct & MFX_PICSTRUCT_FRAME_TRIPLING ? 4 :

            outsurf->Info.PicStruct & MFX_PICSTRUCT_FRAME_DOUBLING ? 2 :

            outsurf->Info.PicStruct & MFX_PICSTRUCT_FIELD_REPEATED ? 1 : 0;

        frame->top_field_first =

            outsurf->Info.PicStruct & MFX_PICSTRUCT_FIELD_TFF;

        frame->interlaced_frame =

            !(outsurf->Info.PicStruct & MFX_PICSTRUCT_PROGRESSIVE);



        *got_frame = 1;

    }



    return avpkt->size;

}

static int16_t long_term_filter(DSPContext *dsp, int pitch_delay_int,

                                const int16_t* residual, int16_t *residual_filt,

                                int subframe_size)

{

    int i, k, tmp, tmp2;

    int sum;

    int L_temp0;

    int L_temp1;

    int64_t L64_temp0;

    int64_t L64_temp1;

    int16_t shift;

    int corr_int_num, corr_int_den;



    int ener;

    int16_t sh_ener;



    int16_t gain_num,gain_den; //selected signal's gain numerator and denominator

    int16_t sh_gain_num, sh_gain_den;

    int gain_num_square;



    int16_t gain_long_num,gain_long_den; //filtered through long interpolation filter signal's gain numerator and denominator

    int16_t sh_gain_long_num, sh_gain_long_den;



    int16_t best_delay_int, best_delay_frac;



    int16_t delayed_signal_offset;

    int lt_filt_factor_a, lt_filt_factor_b;



    int16_t * selected_signal;

    const int16_t * selected_signal_const; //Necessary to avoid compiler warning



    int16_t sig_scaled[SUBFRAME_SIZE + RES_PREV_DATA_SIZE];

    int16_t delayed_signal[ANALYZED_FRAC_DELAYS][SUBFRAME_SIZE+1];

    int corr_den[ANALYZED_FRAC_DELAYS][2];



    tmp = 0;

    for(i=0; i<subframe_size + RES_PREV_DATA_SIZE; i++)

        tmp |= FFABS(residual[i]);



    if(!tmp)

        shift = 3;

    else

        shift = av_log2(tmp) - 11;



    if (shift > 0)

        for (i = 0; i < subframe_size + RES_PREV_DATA_SIZE; i++)

            sig_scaled[i] = residual[i] >> shift;

    else

        for (i = 0; i < subframe_size + RES_PREV_DATA_SIZE; i++)

            sig_scaled[i] = residual[i] << -shift;



    /* Start of best delay searching code */

    gain_num = 0;



    ener = dsp->scalarproduct_int16(sig_scaled + RES_PREV_DATA_SIZE,

                                    sig_scaled + RES_PREV_DATA_SIZE,

                                    subframe_size);

    if (ener) {

        sh_ener = FFMAX(av_log2(ener) - 14, 0);

        ener >>= sh_ener;

        /* Search for best pitch delay.



                       sum{ r(n) * r(k,n) ] }^2

           R'(k)^2 := -------------------------

                       sum{ r(k,n) * r(k,n) }





           R(T)    :=  sum{ r(n) * r(n-T) ] }





           where

           r(n-T) is integer delayed signal with delay T

           r(k,n) is non-integer delayed signal with integer delay best_delay

           and fractional delay k */



        /* Find integer delay best_delay which maximizes correlation R(T).



           This is also equals to numerator of R'(0),

           since the fine search (second step) is done with 1/8

           precision around best_delay. */

        corr_int_num = 0;

        best_delay_int = pitch_delay_int - 1;

        for (i = pitch_delay_int - 1; i <= pitch_delay_int + 1; i++) {

            sum = dsp->scalarproduct_int16(sig_scaled + RES_PREV_DATA_SIZE,

                                           sig_scaled + RES_PREV_DATA_SIZE - i,

                                           subframe_size);

            if (sum > corr_int_num) {

                corr_int_num = sum;

                best_delay_int = i;

            }

        }

        if (corr_int_num) {

            /* Compute denominator of pseudo-normalized correlation R'(0). */

            corr_int_den = dsp->scalarproduct_int16(sig_scaled - best_delay_int + RES_PREV_DATA_SIZE,

                                                    sig_scaled - best_delay_int + RES_PREV_DATA_SIZE,

                                                    subframe_size);



            /* Compute signals with non-integer delay k (with 1/8 precision),

               where k is in [0;6] range.

               Entire delay is qual to best_delay+(k+1)/8

               This is archieved by applying an interpolation filter of

               legth 33 to source signal. */

            for (k = 0; k < ANALYZED_FRAC_DELAYS; k++) {

                ff_acelp_interpolate(&delayed_signal[k][0],

                                     &sig_scaled[RES_PREV_DATA_SIZE - best_delay_int],

                                     ff_g729_interp_filt_short,

                                     ANALYZED_FRAC_DELAYS+1,

                                     8 - k - 1,

                                     SHORT_INT_FILT_LEN,

                                     subframe_size + 1);

            }



            /* Compute denominator of pseudo-normalized correlation R'(k).



                 corr_den[k][0] is square root of R'(k) denominator, for int(T) == int(T0)

                 corr_den[k][1] is square root of R'(k) denominator, for int(T) == int(T0)+1



              Also compute maximum value of above denominators over all k. */

            tmp = corr_int_den;

            for (k = 0; k < ANALYZED_FRAC_DELAYS; k++) {

                sum = dsp->scalarproduct_int16(&delayed_signal[k][1],

                                               &delayed_signal[k][1],

                                               subframe_size - 1);

                corr_den[k][0] = sum + delayed_signal[k][0            ] * delayed_signal[k][0            ];

                corr_den[k][1] = sum + delayed_signal[k][subframe_size] * delayed_signal[k][subframe_size];



                tmp = FFMAX3(tmp, corr_den[k][0], corr_den[k][1]);

            }



            sh_gain_den = av_log2(tmp) - 14;

            if (sh_gain_den >= 0) {



                sh_gain_num =  FFMAX(sh_gain_den, sh_ener);

                /* Loop through all k and find delay that maximizes

                   R'(k) correlation.

                   Search is done in [int(T0)-1; intT(0)+1] range

                   with 1/8 precision. */

                delayed_signal_offset = 1;

                best_delay_frac = 0;

                gain_den = corr_int_den >> sh_gain_den;

                gain_num = corr_int_num >> sh_gain_num;

                gain_num_square = gain_num * gain_num;

                for (k = 0; k < ANALYZED_FRAC_DELAYS; k++) {

                    for (i = 0; i < 2; i++) {

                        int16_t gain_num_short, gain_den_short;

                        int gain_num_short_square;

                        /* Compute numerator of pseudo-normalized

                           correlation R'(k). */

                        sum = dsp->scalarproduct_int16(&delayed_signal[k][i],

                                                       sig_scaled + RES_PREV_DATA_SIZE,

                                                       subframe_size);

                        gain_num_short = FFMAX(sum >> sh_gain_num, 0);



                        /*

                                      gain_num_short_square                gain_num_square

                           R'(T)^2 = -----------------------, max R'(T)^2= --------------

                                           den                                 gain_den

                        */

                        gain_num_short_square = gain_num_short * gain_num_short;

                        gain_den_short = corr_den[k][i] >> sh_gain_den;



                        tmp = MULL(gain_num_short_square, gain_den, FRAC_BITS);

                        tmp2 = MULL(gain_num_square, gain_den_short, FRAC_BITS);



                        // R'(T)^2 > max R'(T)^2

                        if (tmp > tmp2) {

                            gain_num = gain_num_short;

                            gain_den = gain_den_short;

                            gain_num_square = gain_num_short_square;

                            delayed_signal_offset = i;

                            best_delay_frac = k + 1;

                        }

                    }

                }



                /*

                       R'(T)^2

                  2 * --------- < 1

                        R(0)

                */

                L64_temp0 =  (int64_t)gain_num_square  << ((sh_gain_num << 1) + 1);

                L64_temp1 = ((int64_t)gain_den * ener) << (sh_gain_den + sh_ener);

                if (L64_temp0 < L64_temp1)

                    gain_num = 0;

            } // if(sh_gain_den >= 0)

        } // if(corr_int_num)

    } // if(ener)

    /* End of best delay searching code  */



    if (!gain_num) {

        memcpy(residual_filt, residual + RES_PREV_DATA_SIZE, subframe_size * sizeof(int16_t));



        /* Long-term prediction gain is less than 3dB. Long-term postfilter is disabled. */

        return 0;

    }

    if (best_delay_frac) {

        /* Recompute delayed signal with an interpolation filter of length 129. */

        ff_acelp_interpolate(residual_filt,

                             &sig_scaled[RES_PREV_DATA_SIZE - best_delay_int + delayed_signal_offset],

                             ff_g729_interp_filt_long,

                             ANALYZED_FRAC_DELAYS + 1,

                             8 - best_delay_frac,

                             LONG_INT_FILT_LEN,

                             subframe_size + 1);

        /* Compute R'(k) correlation's numerator. */

        sum = dsp->scalarproduct_int16(residual_filt,

                                       sig_scaled + RES_PREV_DATA_SIZE,

                                       subframe_size);



        if (sum < 0) {

            gain_long_num = 0;

            sh_gain_long_num = 0;

        } else {

            tmp = FFMAX(av_log2(sum) - 14, 0);

            sum >>= tmp;

            gain_long_num = sum;

            sh_gain_long_num = tmp;

        }



        /* Compute R'(k) correlation's denominator. */

        sum = dsp->scalarproduct_int16(residual_filt, residual_filt, subframe_size);



        tmp = FFMAX(av_log2(sum) - 14, 0);

        sum >>= tmp;

        gain_long_den = sum;

        sh_gain_long_den = tmp;



        /* Select between original and delayed signal.

           Delayed signal will be selected if it increases R'(k)

           correlation. */

        L_temp0 = gain_num * gain_num;

        L_temp0 = MULL(L_temp0, gain_long_den, FRAC_BITS);



        L_temp1 = gain_long_num * gain_long_num;

        L_temp1 = MULL(L_temp1, gain_den, FRAC_BITS);



        tmp = ((sh_gain_long_num - sh_gain_num) << 1) - (sh_gain_long_den - sh_gain_den);

        if (tmp > 0)

            L_temp0 >>= tmp;

        else

            L_temp1 >>= -tmp;



        /* Check if longer filter increases the values of R'(k). */

        if (L_temp1 > L_temp0) {

            /* Select long filter. */

            selected_signal = residual_filt;

            gain_num = gain_long_num;

            gain_den = gain_long_den;

            sh_gain_num = sh_gain_long_num;

            sh_gain_den = sh_gain_long_den;

        } else

            /* Select short filter. */

            selected_signal = &delayed_signal[best_delay_frac-1][delayed_signal_offset];



        /* Rescale selected signal to original value. */

        if (shift > 0)

            for (i = 0; i < subframe_size; i++)

                selected_signal[i] <<= shift;

        else

            for (i = 0; i < subframe_size; i++)

                selected_signal[i] >>= -shift;



        /* necessary to avoid compiler warning */

        selected_signal_const = selected_signal;

    } // if(best_delay_frac)

    else

        selected_signal_const = residual + RES_PREV_DATA_SIZE - (best_delay_int + 1 - delayed_signal_offset);

#ifdef G729_BITEXACT

    tmp = sh_gain_num - sh_gain_den;

    if (tmp > 0)

        gain_den >>= tmp;

    else

        gain_num >>= -tmp;



    if (gain_num > gain_den)

        lt_filt_factor_a = MIN_LT_FILT_FACTOR_A;

    else {

        gain_num >>= 2;

        gain_den >>= 1;

        lt_filt_factor_a = (gain_den << 15) / (gain_den + gain_num);

    }

#else

    L64_temp0 = ((int64_t)gain_num) << (sh_gain_num - 1);

    L64_temp1 = ((int64_t)gain_den) << sh_gain_den;

    lt_filt_factor_a = FFMAX((L64_temp1 << 15) / (L64_temp1 + L64_temp0), MIN_LT_FILT_FACTOR_A);

#endif



    /* Filter through selected filter. */

    lt_filt_factor_b = 32767 - lt_filt_factor_a + 1;



    ff_acelp_weighted_vector_sum(residual_filt, residual + RES_PREV_DATA_SIZE,

                                 selected_signal_const,

                                 lt_filt_factor_a, lt_filt_factor_b,

                                 1<<14, 15, subframe_size);



    // Long-term prediction gain is larger than 3dB.

    return 1;

}

static int64_t asf_read_pts(AVFormatContext *s, int64_t *ppos, int stream_index)

{

    ASFContext *asf = s->priv_data;

    AVPacket pkt1, *pkt = &pkt1;

    int64_t pos= *ppos;

    int64_t pts;



    // ensure we are on the packet boundry

    assert(pos % asf->packet_size == 0);



    url_fseek(&s->pb, pos + s->data_offset, SEEK_SET);

    do{

        pos= url_ftell(&s->pb) - s->data_offset;

        asf_reset_header(s);

        if (av_read_frame(s, pkt) < 0)

    	    return AV_NOPTS_VALUE;

        pts= pkt->pts;



        av_free_packet(pkt);

    }while(pkt->stream_index != stream_index);



    *ppos= pos;



    return pts;

}

static int xmv_process_packet_header(AVFormatContext *s)

{

    XMVDemuxContext *xmv = s->priv_data;

    AVIOContext     *pb  = s->pb;



    uint8_t  data[8];

    uint16_t audio_track;

    uint64_t data_offset;



    /* Next packet size */

    xmv->next_packet_size = avio_rl32(pb);



    /* Packet video header */



    if (avio_read(pb, data, 8) != 8)

        return AVERROR(EIO);



    xmv->video.data_size     = AV_RL32(data) & 0x007FFFFF;



    xmv->video.current_frame = 0;

    xmv->video.frame_count   = (AV_RL32(data) >> 23) & 0xFF;



    xmv->video.has_extradata = (data[3] & 0x80) != 0;



    /* Adding the audio data sizes and the video data size keeps you 4 bytes

     * short for every audio track. But as playing around with XMV files with

     * ADPCM audio showed, taking the extra 4 bytes from the audio data gives

     * you either completely distorted audio or click (when skipping the

     * remaining 68 bytes of the ADPCM block). Subtracting 4 bytes for every

     * audio track from the video data works at least for the audio. Probably

     * some alignment thing?

     * The video data has (always?) lots of padding, so it should work out...

     */

    xmv->video.data_size -= xmv->audio_track_count * 4;



    xmv->current_stream = 0;

    if (!xmv->video.frame_count) {

        xmv->video.frame_count = 1;

        xmv->current_stream    = xmv->stream_count > 1;

    }



    /* Packet audio header */



    for (audio_track = 0; audio_track < xmv->audio_track_count; audio_track++) {

        XMVAudioPacket *packet = &xmv->audio[audio_track];



        if (avio_read(pb, data, 4) != 4)

            return AVERROR(EIO);



        packet->data_size = AV_RL32(data) & 0x007FFFFF;

        if ((packet->data_size == 0) && (audio_track != 0))

            /* This happens when I create an XMV with several identical audio

             * streams. From the size calculations, duplicating the previous

             * stream's size works out, but the track data itself is silent.

             * Maybe this should also redirect the offset to the previous track?

             */

            packet->data_size = xmv->audio[audio_track - 1].data_size;



        /* Carve up the audio data in frame_count slices */

        packet->frame_size  = packet->data_size  / xmv->video.frame_count;

        packet->frame_size -= packet->frame_size % packet->block_align;

    }



    /* Packet data offsets */



    data_offset = avio_tell(pb);



    xmv->video.data_offset = data_offset;

    data_offset += xmv->video.data_size;



    for (audio_track = 0; audio_track < xmv->audio_track_count; audio_track++) {

        xmv->audio[audio_track].data_offset = data_offset;

        data_offset += xmv->audio[audio_track].data_size;

    }



    /* Video frames header */



    /* Read new video extra data */

    if (xmv->video.data_size > 0) {

        if (xmv->video.has_extradata) {

            xmv_read_extradata(xmv->video.extradata, pb);



            xmv->video.data_size   -= 4;

            xmv->video.data_offset += 4;



            if (xmv->video.stream_index >= 0) {

                AVStream *vst = s->streams[xmv->video.stream_index];



                av_assert0(xmv->video.stream_index < s->nb_streams);



                if (vst->codec->extradata_size < 4) {

                    av_freep(&vst->codec->extradata);



                    ff_alloc_extradata(vst->codec, 4);

                }



                memcpy(vst->codec->extradata, xmv->video.extradata, 4);

            }

        }

    }



    return 0;

}

static av_cold int qtrle_decode_init(AVCodecContext *avctx)

{

    QtrleContext *s = avctx->priv_data;



    s->avctx = avctx;

    switch (avctx->bits_per_coded_sample) {

    case 1:

    case 33:

        avctx->pix_fmt = AV_PIX_FMT_MONOWHITE;

        break;



    case 2:

    case 4:

    case 8:

    case 34:

    case 36:

    case 40:

        avctx->pix_fmt = AV_PIX_FMT_PAL8;

        break;



    case 16:

        avctx->pix_fmt = AV_PIX_FMT_RGB555;

        break;



    case 24:

        avctx->pix_fmt = AV_PIX_FMT_RGB24;

        break;



    case 32:

        avctx->pix_fmt = AV_PIX_FMT_RGB32;

        break;



    default:

        av_log (avctx, AV_LOG_ERROR, "Unsupported colorspace: %d bits/sample?\n",

            avctx->bits_per_coded_sample);

        return AVERROR_INVALIDDATA;

    }



    s->frame.data[0] = NULL;



    return 0;

}

static void fft_ref_init(int nbits, int inverse)

{

    int i, n = 1 << nbits;



    exptab = av_malloc((n / 2) * sizeof(*exptab));



    for (i = 0; i < (n/2); i++) {

        double alpha = 2 * M_PI * (float)i / (float)n;

        double c1 = cos(alpha), s1 = sin(alpha);

        if (!inverse)

            s1 = -s1;

        exptab[i].re = c1;

        exptab[i].im = s1;

    }

}

inline static int push_frame(AVFilterLink *outlink)

{

    AVFilterContext *ctx = outlink->src;

    AVFilterLink *inlink = ctx->inputs[0];

    ShowWavesContext *showwaves = outlink->src->priv;

    int nb_channels = inlink->channels;

    int ret, i;



    if ((ret = ff_filter_frame(outlink, showwaves->outpicref)) >= 0)

        showwaves->req_fullfilled = 1;

    showwaves->outpicref = NULL;

    showwaves->buf_idx = 0;

    for (i = 0; i < nb_channels; i++)

        showwaves->buf_idy[i] = 0;

    return ret;

}

static void ffmpeg_cleanup(int ret)
{
    int i, j;
    if (do_benchmark) {
        int maxrss = getmaxrss() / 1024;
        av_log(NULL, AV_LOG_INFO, "bench: maxrss=%ikB\n", maxrss);
    }
    for (i = 0; i < nb_filtergraphs; i++) {
        FilterGraph *fg = filtergraphs[i];
        avfilter_graph_free(&fg->graph);
        for (j = 0; j < fg->nb_inputs; j++) {
            av_freep(&fg->inputs[j]->name);
            av_freep(&fg->inputs[j]);
        }
        av_freep(&fg->inputs);
        for (j = 0; j < fg->nb_outputs; j++) {
            av_freep(&fg->outputs[j]->name);
            av_freep(&fg->outputs[j]);
        }
        av_freep(&fg->outputs);
        av_freep(&fg->graph_desc);
        av_freep(&filtergraphs[i]);
    }
    av_freep(&filtergraphs);
    av_freep(&subtitle_out);
    /* close files */
    for (i = 0; i < nb_output_files; i++) {
        OutputFile *of = output_files[i];
        AVFormatContext *s;
        if (!of)
            continue;
        s = of->ctx;
        if (s && s->oformat && !(s->oformat->flags & AVFMT_NOFILE))
            avio_closep(&s->pb);
        avformat_free_context(s);
        av_dict_free(&of->opts);
        av_freep(&output_files[i]);
    }
    for (i = 0; i < nb_output_streams; i++) {
        OutputStream *ost = output_streams[i];
        AVBitStreamFilterContext *bsfc;
        if (!ost)
            continue;
        bsfc = ost->bitstream_filters;
        while (bsfc) {
            AVBitStreamFilterContext *next = bsfc->next;
            av_bitstream_filter_close(bsfc);
            bsfc = next;
        }
        ost->bitstream_filters = NULL;
        av_frame_free(&ost->filtered_frame);
        av_frame_free(&ost->last_frame);
        av_parser_close(ost->parser);
        av_freep(&ost->forced_keyframes);
        av_expr_free(ost->forced_keyframes_pexpr);
        av_freep(&ost->avfilter);
        av_freep(&ost->logfile_prefix);
        av_freep(&ost->audio_channels_map);
        ost->audio_channels_mapped = 0;
        avcodec_free_context(&ost->enc_ctx);
        av_freep(&output_streams[i]);
    }
#if HAVE_PTHREADS
    free_input_threads();
#endif
    for (i = 0; i < nb_input_files; i++) {
        avformat_close_input(&input_files[i]->ctx);
        av_freep(&input_files[i]);
    }
    for (i = 0; i < nb_input_streams; i++) {
        InputStream *ist = input_streams[i];
        av_frame_free(&ist->decoded_frame);
        av_frame_free(&ist->filter_frame);
        av_dict_free(&ist->decoder_opts);
        avsubtitle_free(&ist->prev_sub.subtitle);
        av_frame_free(&ist->sub2video.frame);
        av_freep(&ist->filters);
        av_freep(&ist->hwaccel_device);
        avcodec_free_context(&ist->dec_ctx);
        av_freep(&input_streams[i]);
    }
    if (vstats_file) {
        if (fclose(vstats_file))
            av_log(NULL, AV_LOG_ERROR,
                   "Error closing vstats file, loss of information possible: %s\n",
                   av_err2str(AVERROR(errno)));
    }
    av_freep(&vstats_filename);
    av_freep(&input_streams);
    av_freep(&input_files);
    av_freep(&output_streams);
    av_freep(&output_files);
    uninit_opts();
    avformat_network_deinit();
    if (received_sigterm) {
        av_log(NULL, AV_LOG_INFO, "Exiting normally, received signal %d.\n",
               (int) received_sigterm);
    } else if (ret && transcode_init_done) {
        av_log(NULL, AV_LOG_INFO, "Conversion failed!\n");
    }
    term_exit();
    ffmpeg_exited = 1;
}

void av_image_copy(uint8_t *dst_data[4], int dst_linesizes[4],

                   const uint8_t *src_data[4], const int src_linesizes[4],

                   enum PixelFormat pix_fmt, int width, int height)

{

    const AVPixFmtDescriptor *desc = &av_pix_fmt_descriptors[pix_fmt];



    if (desc->flags & PIX_FMT_HWACCEL)

        return;



    if (desc->flags & PIX_FMT_PAL) {

        av_image_copy_plane(dst_data[0], dst_linesizes[0],

                            src_data[0], src_linesizes[0],

                            width, height);

        /* copy the palette */

        memcpy(dst_data[1], src_data[1], 4*256);

    } else {

        int i, planes_nb = 0;



        for (i = 0; i < desc->nb_components; i++)

            planes_nb = FFMAX(planes_nb, desc->comp[i].plane + 1);



        for (i = 0; i < planes_nb; i++) {

            int h = height;

            int bwidth = av_image_get_linesize(pix_fmt, width, i);

            if (i == 1 || i == 2) {

                h= -((-height)>>desc->log2_chroma_h);

            }

            av_image_copy_plane(dst_data[i], dst_linesizes[i],

                                src_data[i], src_linesizes[i],

                                bwidth, h);

        }

    }

}

static int webm_dash_manifest_cues(AVFormatContext *s)

{

    MatroskaDemuxContext *matroska = s->priv_data;

    EbmlList *seekhead_list = &matroska->seekhead;

    MatroskaSeekhead *seekhead = seekhead_list->elem;

    char *buf;

    int64_t cues_start = -1, cues_end = -1, before_pos, bandwidth;

    int i;



    // determine cues start and end positions

    for (i = 0; i < seekhead_list->nb_elem; i++)

        if (seekhead[i].id == MATROSKA_ID_CUES)

            break;



    if (i >= seekhead_list->nb_elem) return -1;



    before_pos = avio_tell(matroska->ctx->pb);

    cues_start = seekhead[i].pos + matroska->segment_start;

    if (avio_seek(matroska->ctx->pb, cues_start, SEEK_SET) == cues_start) {

        // cues_end is computed as cues_start + cues_length + length of the

        // Cues element ID + EBML length of the Cues element. cues_end is

        // inclusive and the above sum is reduced by 1.

        uint64_t cues_length = 0, cues_id = 0, bytes_read = 0;

        bytes_read += ebml_read_num(matroska, matroska->ctx->pb, 4, &cues_id);

        bytes_read += ebml_read_length(matroska, matroska->ctx->pb, &cues_length);

        cues_end = cues_start + cues_length + bytes_read - 1;

    }

    avio_seek(matroska->ctx->pb, before_pos, SEEK_SET);

    if (cues_start == -1 || cues_end == -1) return -1;



    // parse the cues

    matroska_parse_cues(matroska);



    // cues start

    av_dict_set_int(&s->streams[0]->metadata, CUES_START, cues_start, 0);



    // cues end

    av_dict_set_int(&s->streams[0]->metadata, CUES_END, cues_end, 0);



    // bandwidth

    bandwidth = webm_dash_manifest_compute_bandwidth(s, cues_start);

    if (bandwidth < 0) return -1;

    av_dict_set_int(&s->streams[0]->metadata, BANDWIDTH, bandwidth, 0);



    // check if all clusters start with key frames

    av_dict_set_int(&s->streams[0]->metadata, CLUSTER_KEYFRAME, webm_clusters_start_with_keyframe(s), 0);



    // store cue point timestamps as a comma separated list for checking subsegment alignment in

    // the muxer. assumes that each timestamp cannot be more than 20 characters long.

    buf = av_malloc_array(s->streams[0]->nb_index_entries, 20 * sizeof(char));

    if (!buf) return -1;

    strcpy(buf, "");

    for (i = 0; i < s->streams[0]->nb_index_entries; i++) {

        snprintf(buf, (i + 1) * 20 * sizeof(char),

                 "%s%" PRId64, buf, s->streams[0]->index_entries[i].timestamp);

        if (i != s->streams[0]->nb_index_entries - 1)

            strncat(buf, ",", sizeof(char));

    }

    av_dict_set(&s->streams[0]->metadata, CUE_TIMESTAMPS, buf, 0);

    av_free(buf);



    return 0;

}

static int ljpeg_decode_rgb_scan(MJpegDecodeContext *s, int nb_components, int predictor, int point_transform)
{
    int i, mb_x, mb_y;
    uint16_t (*buffer)[4];
    int left[4], top[4], topleft[4];
    const int linesize = s->linesize[0];
    const int mask     = (1 << s->bits) - 1;
    int resync_mb_y = 0;
    int resync_mb_x = 0;
    s->restart_count = s->restart_interval;
    av_fast_malloc(&s->ljpeg_buffer, &s->ljpeg_buffer_size,
                   (unsigned)s->mb_width * 4 * sizeof(s->ljpeg_buffer[0][0]));
    buffer = s->ljpeg_buffer;
    for (i = 0; i < 4; i++)
        buffer[0][i] = 1 << (s->bits - 1);
    for (mb_y = 0; mb_y < s->mb_height; mb_y++) {
        uint8_t *ptr = s->picture.data[0] + (linesize * mb_y);
        if (s->interlaced && s->bottom_field)
            ptr += linesize >> 1;
        for (i = 0; i < 4; i++)
            top[i] = left[i] = topleft[i] = buffer[0][i];
        for (mb_x = 0; mb_x < s->mb_width; mb_x++) {
            int modified_predictor = predictor;
            if (s->restart_interval && !s->restart_count){
                s->restart_count = s->restart_interval;
                resync_mb_x = mb_x;
                resync_mb_y = mb_y;
                for(i=0; i<4; i++)
                    top[i] = left[i]= topleft[i]= 1 << (s->bits - 1);
            }
            if (mb_y == resync_mb_y || mb_y == resync_mb_y+1 && mb_x < resync_mb_x || !mb_x)
                modified_predictor = 1;
            for (i=0;i<nb_components;i++) {
                int pred, dc;
                topleft[i] = top[i];
                top[i]     = buffer[mb_x][i];
                PREDICT(pred, topleft[i], top[i], left[i], modified_predictor);
                dc = mjpeg_decode_dc(s, s->dc_index[i]);
                if(dc == 0xFFFF)
                    return -1;
                left[i] = buffer[mb_x][i] =
                    mask & (pred + (dc << point_transform));
            }
            if (s->restart_interval && !--s->restart_count) {
                align_get_bits(&s->gb);
                skip_bits(&s->gb, 16); /* skip RSTn */
            }
        }
        if (s->nb_components == 4) {
            for(i=0; i<nb_components; i++) {
                int c= s->comp_index[i];
                for(mb_x = 0; mb_x < s->mb_width; mb_x++) {
                    ptr[4*mb_x+3-c] = buffer[mb_x][i];
                }
            }
        } else if (s->rct) {
            for (mb_x = 0; mb_x < s->mb_width; mb_x++) {
                ptr[3*mb_x + 1] = buffer[mb_x][0] - ((buffer[mb_x][1] + buffer[mb_x][2] - 0x200) >> 2);
                ptr[3*mb_x + 0] = buffer[mb_x][1] + ptr[3*mb_x + 1];
                ptr[3*mb_x + 2] = buffer[mb_x][2] + ptr[3*mb_x + 1];
            }
        } else if (s->pegasus_rct) {
            for (mb_x = 0; mb_x < s->mb_width; mb_x++) {
                ptr[3*mb_x + 1] = buffer[mb_x][0] - ((buffer[mb_x][1] + buffer[mb_x][2]) >> 2);
                ptr[3*mb_x + 0] = buffer[mb_x][1] + ptr[3*mb_x + 1];
                ptr[3*mb_x + 2] = buffer[mb_x][2] + ptr[3*mb_x + 1];
            }
        } else {
            for(i=0; i<nb_components; i++) {
                int c= s->comp_index[i];
                for(mb_x = 0; mb_x < s->mb_width; mb_x++) {
                    ptr[3*mb_x+2-c] = buffer[mb_x][i];
                }
            }
        }
    }
    return 0;
}

static av_cold int vp8_init(AVCodecContext *avctx)

{

    VP8Context *ctx = avctx->priv_data;

    const struct vpx_codec_iface *iface = &vpx_codec_vp8_cx_algo;

    struct vpx_codec_enc_cfg enccfg;

    int res;



    av_log(avctx, AV_LOG_INFO, "%s\n", vpx_codec_version_str());

    av_log(avctx, AV_LOG_VERBOSE, "%s\n", vpx_codec_build_config());



    if ((res = vpx_codec_enc_config_default(iface, &enccfg, 0)) != VPX_CODEC_OK) {

        av_log(avctx, AV_LOG_ERROR, "Failed to get config: %s\n",

               vpx_codec_err_to_string(res));

        return AVERROR(EINVAL);

    }

    dump_enc_cfg(avctx, &enccfg);



    enccfg.g_w            = avctx->width;

    enccfg.g_h            = avctx->height;

    enccfg.g_timebase.num = avctx->time_base.num;

    enccfg.g_timebase.den = avctx->time_base.den;

    enccfg.g_threads      = avctx->thread_count;

    enccfg.g_lag_in_frames= ctx->lag_in_frames;



    if (avctx->flags & CODEC_FLAG_PASS1)

        enccfg.g_pass = VPX_RC_FIRST_PASS;

    else if (avctx->flags & CODEC_FLAG_PASS2)

        enccfg.g_pass = VPX_RC_LAST_PASS;

    else

        enccfg.g_pass = VPX_RC_ONE_PASS;



    if (avctx->rc_min_rate == avctx->rc_max_rate &&

        avctx->rc_min_rate == avctx->bit_rate)

        enccfg.rc_end_usage = VPX_CBR;

    else if (ctx->crf)

        enccfg.rc_end_usage = VPX_CQ;

    enccfg.rc_target_bitrate = av_rescale_rnd(avctx->bit_rate, 1, 1000,

                                              AV_ROUND_NEAR_INF);

    if (avctx->qmin > 0)

        enccfg.rc_min_quantizer = avctx->qmin;

    if (avctx->qmax > 0)

        enccfg.rc_max_quantizer = avctx->qmax;

    enccfg.rc_dropframe_thresh = avctx->frame_skip_threshold;



    //0-100 (0 => CBR, 100 => VBR)

    enccfg.rc_2pass_vbr_bias_pct           = round(avctx->qcompress * 100);

    enccfg.rc_2pass_vbr_minsection_pct     =

        avctx->rc_min_rate * 100LL / avctx->bit_rate;

    if (avctx->rc_max_rate)

        enccfg.rc_2pass_vbr_maxsection_pct =

            avctx->rc_max_rate * 100LL / avctx->bit_rate;



    if (avctx->rc_buffer_size)

        enccfg.rc_buf_sz         =

            avctx->rc_buffer_size * 1000LL / avctx->bit_rate;

    if (avctx->rc_initial_buffer_occupancy)

        enccfg.rc_buf_initial_sz =

            avctx->rc_initial_buffer_occupancy * 1000LL / avctx->bit_rate;

    enccfg.rc_buf_optimal_sz     = enccfg.rc_buf_sz * 5 / 6;

    enccfg.rc_undershoot_pct     = round(avctx->rc_buffer_aggressivity * 100);



    //_enc_init() will balk if kf_min_dist differs from max w/VPX_KF_AUTO

    if (avctx->keyint_min >= 0 && avctx->keyint_min == avctx->gop_size)

        enccfg.kf_min_dist = avctx->keyint_min;

    if (avctx->gop_size >= 0)

        enccfg.kf_max_dist = avctx->gop_size;



    if (enccfg.g_pass == VPX_RC_FIRST_PASS)

        enccfg.g_lag_in_frames = 0;

    else if (enccfg.g_pass == VPX_RC_LAST_PASS) {

        int decode_size;



        if (!avctx->stats_in) {

            av_log(avctx, AV_LOG_ERROR, "No stats file for second pass\n");

            return AVERROR_INVALIDDATA;

        }



        ctx->twopass_stats.sz  = strlen(avctx->stats_in) * 3 / 4;

        ctx->twopass_stats.buf = av_malloc(ctx->twopass_stats.sz);

        if (!ctx->twopass_stats.buf) {

            av_log(avctx, AV_LOG_ERROR,

                   "Stat buffer alloc (%zu bytes) failed\n",

                   ctx->twopass_stats.sz);

            return AVERROR(ENOMEM);

        }

        decode_size = av_base64_decode(ctx->twopass_stats.buf, avctx->stats_in,

                                       ctx->twopass_stats.sz);

        if (decode_size < 0) {

            av_log(avctx, AV_LOG_ERROR, "Stat buffer decode failed\n");

            return AVERROR_INVALIDDATA;

        }



        ctx->twopass_stats.sz      = decode_size;

        enccfg.rc_twopass_stats_in = ctx->twopass_stats;

    }



    /* 0-3: For non-zero values the encoder increasingly optimizes for reduced

       complexity playback on low powered devices at the expense of encode

       quality. */

   if (avctx->profile != FF_PROFILE_UNKNOWN)

       enccfg.g_profile = avctx->profile;



    enccfg.g_error_resilient = ctx->error_resilient || ctx->flags & VP8F_ERROR_RESILIENT;



    dump_enc_cfg(avctx, &enccfg);

    /* Construct Encoder Context */

    res = vpx_codec_enc_init(&ctx->encoder, iface, &enccfg, 0);

    if (res != VPX_CODEC_OK) {

        log_encoder_error(avctx, "Failed to initialize encoder");

        return AVERROR(EINVAL);

    }



    //codec control failures are currently treated only as warnings

    av_log(avctx, AV_LOG_DEBUG, "vpx_codec_control\n");

    if (ctx->cpu_used != INT_MIN)

        codecctl_int(avctx, VP8E_SET_CPUUSED,          ctx->cpu_used);

    if (ctx->flags & VP8F_AUTO_ALT_REF)

        ctx->auto_alt_ref = 1;

    if (ctx->auto_alt_ref >= 0)

        codecctl_int(avctx, VP8E_SET_ENABLEAUTOALTREF, ctx->auto_alt_ref);

    if (ctx->arnr_max_frames >= 0)

        codecctl_int(avctx, VP8E_SET_ARNR_MAXFRAMES,   ctx->arnr_max_frames);

    if (ctx->arnr_strength >= 0)

        codecctl_int(avctx, VP8E_SET_ARNR_STRENGTH,    ctx->arnr_strength);

    if (ctx->arnr_type >= 0)

        codecctl_int(avctx, VP8E_SET_ARNR_TYPE,        ctx->arnr_type);

    codecctl_int(avctx, VP8E_SET_NOISE_SENSITIVITY, avctx->noise_reduction);

    codecctl_int(avctx, VP8E_SET_TOKEN_PARTITIONS,  av_log2(avctx->slices));

    codecctl_int(avctx, VP8E_SET_STATIC_THRESHOLD,  avctx->mb_threshold);

    codecctl_int(avctx, VP8E_SET_CQ_LEVEL,          ctx->crf);

    if (ctx->max_intra_rate >= 0)

        codecctl_int(avctx, VP8E_SET_MAX_INTRA_BITRATE_PCT, ctx->max_intra_rate);



    av_log(avctx, AV_LOG_DEBUG, "Using deadline: %d\n", ctx->deadline);



    //provide dummy value to initialize wrapper, values will be updated each _encode()

    vpx_img_wrap(&ctx->rawimg, VPX_IMG_FMT_I420, avctx->width, avctx->height, 1,

                 (unsigned char*)1);



    avctx->coded_frame = avcodec_alloc_frame();

    if (!avctx->coded_frame) {

        av_log(avctx, AV_LOG_ERROR, "Error allocating coded frame\n");

        vp8_free(avctx);

        return AVERROR(ENOMEM);

    }

    return 0;

}

static int vmdaudio_decode_frame(AVCodecContext *avctx, void *data,

                                 int *got_frame_ptr, AVPacket *avpkt)

{

    AVFrame *frame     = data;

    const uint8_t *buf = avpkt->data;

    const uint8_t *buf_end;

    int buf_size = avpkt->size;

    VmdAudioContext *s = avctx->priv_data;

    int block_type, silent_chunks, audio_chunks;

    int ret;

    uint8_t *output_samples_u8;

    int16_t *output_samples_s16;



    if (buf_size < 16) {

        av_log(avctx, AV_LOG_WARNING, "skipping small junk packet\n");

        *got_frame_ptr = 0;

        return buf_size;

    }



    block_type = buf[6];

    if (block_type < BLOCK_TYPE_AUDIO || block_type > BLOCK_TYPE_SILENCE) {

        av_log(avctx, AV_LOG_ERROR, "unknown block type: %d\n", block_type);

        return AVERROR(EINVAL);

    }

    buf      += 16;

    buf_size -= 16;



    /* get number of silent chunks */

    silent_chunks = 0;

    if (block_type == BLOCK_TYPE_INITIAL) {

        uint32_t flags;

        if (buf_size < 4) {

            av_log(avctx, AV_LOG_ERROR, "packet is too small\n");

            return AVERROR(EINVAL);

        }

        flags         = AV_RB32(buf);

        silent_chunks = av_popcount(flags);

        buf      += 4;

        buf_size -= 4;

    } else if (block_type == BLOCK_TYPE_SILENCE) {

        silent_chunks = 1;

        buf_size = 0; // should already be zero but set it just to be sure

    }



    /* ensure output buffer is large enough */

    audio_chunks = buf_size / s->chunk_size;



    /* get output buffer */

    frame->nb_samples = ((silent_chunks + audio_chunks) * avctx->block_align) /

                        avctx->channels;

    if ((ret = ff_get_buffer(avctx, frame, 0)) < 0) {

        av_log(avctx, AV_LOG_ERROR, "get_buffer() failed\n");

        return ret;

    }

    output_samples_u8  =            frame->data[0];

    output_samples_s16 = (int16_t *)frame->data[0];



    /* decode silent chunks */

    if (silent_chunks > 0) {

        int silent_size = avctx->block_align * silent_chunks;

        if (s->out_bps == 2) {

            memset(output_samples_s16, 0x00, silent_size * 2);

            output_samples_s16 += silent_size;

        } else {

            memset(output_samples_u8,  0x80, silent_size);

            output_samples_u8 += silent_size;

        }

    }



    /* decode audio chunks */

    if (audio_chunks > 0) {

        buf_end = buf + buf_size;

        while (buf < buf_end) {

            if (s->out_bps == 2) {

                decode_audio_s16(output_samples_s16, buf, s->chunk_size,

                                 avctx->channels);

                output_samples_s16 += avctx->block_align;

            } else {

                memcpy(output_samples_u8, buf, s->chunk_size);

                output_samples_u8  += avctx->block_align;

            }

            buf += s->chunk_size;

        }

    }



    *got_frame_ptr = 1;



    return avpkt->size;

}

static int convert_sub_to_old_ass_form(AVSubtitle *sub, const AVPacket *pkt, AVRational tb)

{

    int i;

    AVBPrint buf;



    av_bprint_init(&buf, 0, AV_BPRINT_SIZE_UNLIMITED);



    for (i = 0; i < sub->num_rects; i++) {

        char *final_dialog;

        const char *dialog;

        AVSubtitleRect *rect = sub->rects[i];

        int ts_start, ts_duration = -1;

        long int layer;



        if (rect->type != SUBTITLE_ASS || !strncmp(rect->ass, "Dialogue ", 10))

            continue;



        av_bprint_clear(&buf);



        /* skip ReadOrder */

        dialog = strchr(rect->ass, ',');

        if (!dialog)

            continue;

        dialog++;



        /* extract Layer or Marked */

        layer = strtol(dialog, (char**)&dialog, 10);

        if (*dialog != ',')

            continue;

        dialog++;



        /* rescale timing to ASS time base (ms) */

        ts_start = av_rescale_q(pkt->pts, tb, av_make_q(1, 100));

        if (pkt->duration != -1)

            ts_duration = av_rescale_q(pkt->duration, tb, av_make_q(1, 100));

        sub->end_display_time = FFMAX(sub->end_display_time, 10 * ts_duration);



        /* construct ASS (standalone file form with timestamps) string */

        av_bprintf(&buf, "Dialogue: %ld,", layer);

        insert_ts(&buf, ts_start);

        insert_ts(&buf, ts_duration == -1 ? -1 : ts_start + ts_duration);

        av_bprintf(&buf, "%s\r\n", dialog);



        final_dialog = av_strdup(buf.str);

        if (!av_bprint_is_complete(&buf) || !final_dialog) {

            av_freep(&final_dialog);

            av_bprint_finalize(&buf, NULL);

            return AVERROR(ENOMEM);

        }

        av_freep(&rect->ass);

        rect->ass = final_dialog;

    }



    av_bprint_finalize(&buf, NULL);

    return 0;

}

static av_cold int bmp_encode_init(AVCodecContext *avctx){

    switch (avctx->pix_fmt) {

    case AV_PIX_FMT_BGR24:

        avctx->bits_per_coded_sample = 24;

        break;

    case AV_PIX_FMT_RGB555:

    case AV_PIX_FMT_RGB565:

    case AV_PIX_FMT_RGB444:

        avctx->bits_per_coded_sample = 16;

        break;

    case AV_PIX_FMT_RGB8:

    case AV_PIX_FMT_BGR8:

    case AV_PIX_FMT_RGB4_BYTE:

    case AV_PIX_FMT_BGR4_BYTE:

    case AV_PIX_FMT_GRAY8:

    case AV_PIX_FMT_PAL8:

        avctx->bits_per_coded_sample = 8;

        break;

    case AV_PIX_FMT_MONOBLACK:

        avctx->bits_per_coded_sample = 1;

        break;

    default:

        av_log(avctx, AV_LOG_INFO, "unsupported pixel format\n");

        return -1;

    }



    avctx->coded_frame = av_frame_alloc();

    if (!avctx->coded_frame)

        return AVERROR(ENOMEM);



    return 0;

}

static int ape_read_header(AVFormatContext * s)

{

    AVIOContext *pb = s->pb;

    APEContext *ape = s->priv_data;

    AVStream *st;

    uint32_t tag;

    int i;

    int total_blocks, final_size = 0;

    int64_t pts, file_size;



    /* Skip any leading junk such as id3v2 tags */

    ape->junklength = avio_tell(pb);



    tag = avio_rl32(pb);

    if (tag != MKTAG('M', 'A', 'C', ' '))

        return -1;



    ape->fileversion = avio_rl16(pb);



    if (ape->fileversion < APE_MIN_VERSION || ape->fileversion > APE_MAX_VERSION) {

        av_log(s, AV_LOG_ERROR, "Unsupported file version - %d.%02d\n",

               ape->fileversion / 1000, (ape->fileversion % 1000) / 10);

        return -1;

    }



    if (ape->fileversion >= 3980) {

        ape->padding1             = avio_rl16(pb);

        ape->descriptorlength     = avio_rl32(pb);

        ape->headerlength         = avio_rl32(pb);

        ape->seektablelength      = avio_rl32(pb);

        ape->wavheaderlength      = avio_rl32(pb);

        ape->audiodatalength      = avio_rl32(pb);

        ape->audiodatalength_high = avio_rl32(pb);

        ape->wavtaillength        = avio_rl32(pb);

        avio_read(pb, ape->md5, 16);



        /* Skip any unknown bytes at the end of the descriptor.

           This is for future compatibility */

        if (ape->descriptorlength > 52)

            avio_skip(pb, ape->descriptorlength - 52);



        /* Read header data */

        ape->compressiontype      = avio_rl16(pb);

        ape->formatflags          = avio_rl16(pb);

        ape->blocksperframe       = avio_rl32(pb);

        ape->finalframeblocks     = avio_rl32(pb);

        ape->totalframes          = avio_rl32(pb);

        ape->bps                  = avio_rl16(pb);

        ape->channels             = avio_rl16(pb);

        ape->samplerate           = avio_rl32(pb);

    } else {

        ape->descriptorlength = 0;

        ape->headerlength = 32;



        ape->compressiontype      = avio_rl16(pb);

        ape->formatflags          = avio_rl16(pb);

        ape->channels             = avio_rl16(pb);

        ape->samplerate           = avio_rl32(pb);

        ape->wavheaderlength      = avio_rl32(pb);

        ape->wavtaillength        = avio_rl32(pb);

        ape->totalframes          = avio_rl32(pb);

        ape->finalframeblocks     = avio_rl32(pb);



        if (ape->formatflags & MAC_FORMAT_FLAG_HAS_PEAK_LEVEL) {

            avio_skip(pb, 4); /* Skip the peak level */

            ape->headerlength += 4;

        }



        if (ape->formatflags & MAC_FORMAT_FLAG_HAS_SEEK_ELEMENTS) {

            ape->seektablelength = avio_rl32(pb);

            ape->headerlength += 4;

            ape->seektablelength *= sizeof(int32_t);

        } else

            ape->seektablelength = ape->totalframes * sizeof(int32_t);



        if (ape->formatflags & MAC_FORMAT_FLAG_8_BIT)

            ape->bps = 8;

        else if (ape->formatflags & MAC_FORMAT_FLAG_24_BIT)

            ape->bps = 24;

        else

            ape->bps = 16;



        if (ape->fileversion >= 3950)

            ape->blocksperframe = 73728 * 4;

        else if (ape->fileversion >= 3900 || (ape->fileversion >= 3800  && ape->compressiontype >= 4000))

            ape->blocksperframe = 73728;

        else

            ape->blocksperframe = 9216;



        /* Skip any stored wav header */

        if (!(ape->formatflags & MAC_FORMAT_FLAG_CREATE_WAV_HEADER))

            avio_skip(pb, ape->wavheaderlength);

    }



    if(!ape->totalframes){

        av_log(s, AV_LOG_ERROR, "No frames in the file!\n");

        return AVERROR(EINVAL);

    }

    if(ape->totalframes > UINT_MAX / sizeof(APEFrame)){

        av_log(s, AV_LOG_ERROR, "Too many frames: %"PRIu32"\n",

               ape->totalframes);

        return -1;

    }

    if (ape->seektablelength / sizeof(*ape->seektable) < ape->totalframes) {

        av_log(s, AV_LOG_ERROR,

               "Number of seek entries is less than number of frames: %zu vs. %"PRIu32"\n",

               ape->seektablelength / sizeof(*ape->seektable), ape->totalframes);

        return AVERROR_INVALIDDATA;

    }

    ape->frames       = av_malloc(ape->totalframes * sizeof(APEFrame));

    if(!ape->frames)

        return AVERROR(ENOMEM);

    ape->firstframe   = ape->junklength + ape->descriptorlength + ape->headerlength + ape->seektablelength + ape->wavheaderlength;

    if (ape->fileversion < 3810)

        ape->firstframe += ape->totalframes;

    ape->currentframe = 0;





    ape->totalsamples = ape->finalframeblocks;

    if (ape->totalframes > 1)

        ape->totalsamples += ape->blocksperframe * (ape->totalframes - 1);



    if (ape->seektablelength > 0) {

        ape->seektable = av_malloc(ape->seektablelength);

        if (!ape->seektable)

            return AVERROR(ENOMEM);

        for (i = 0; i < ape->seektablelength / sizeof(uint32_t) && !pb->eof_reached; i++)

            ape->seektable[i] = avio_rl32(pb);

        if (ape->fileversion < 3810) {

            ape->bittable = av_malloc(ape->totalframes);

            if (!ape->bittable)

                return AVERROR(ENOMEM);

            for (i = 0; i < ape->totalframes && !pb->eof_reached; i++)

                ape->bittable[i] = avio_r8(pb);

        }

    }



    ape->frames[0].pos     = ape->firstframe;

    ape->frames[0].nblocks = ape->blocksperframe;

    ape->frames[0].skip    = 0;

    for (i = 1; i < ape->totalframes; i++) {

        ape->frames[i].pos      = ape->seektable[i] + ape->junklength;

        ape->frames[i].nblocks  = ape->blocksperframe;

        ape->frames[i - 1].size = ape->frames[i].pos - ape->frames[i - 1].pos;

        ape->frames[i].skip     = (ape->frames[i].pos - ape->frames[0].pos) & 3;

    }

    ape->frames[ape->totalframes - 1].nblocks = ape->finalframeblocks;

    /* calculate final packet size from total file size, if available */

    file_size = avio_size(pb);

    if (file_size > 0) {

        final_size = file_size - ape->frames[ape->totalframes - 1].pos -

                     ape->wavtaillength;

        final_size -= final_size & 3;

    }

    if (file_size <= 0 || final_size <= 0)

        final_size = ape->finalframeblocks * 8;

    ape->frames[ape->totalframes - 1].size = final_size;



    for (i = 0; i < ape->totalframes; i++) {

        if(ape->frames[i].skip){

            ape->frames[i].pos  -= ape->frames[i].skip;

            ape->frames[i].size += ape->frames[i].skip;

        }

        ape->frames[i].size = (ape->frames[i].size + 3) & ~3;

    }

    if (ape->fileversion < 3810) {

        for (i = 0; i < ape->totalframes; i++) {

            if (i < ape->totalframes - 1 && ape->bittable[i + 1])

                ape->frames[i].size += 4;

            ape->frames[i].skip <<= 3;

            ape->frames[i].skip  += ape->bittable[i];

        }

    }



    ape_dumpinfo(s, ape);



    av_log(s, AV_LOG_DEBUG, "Decoding file - v%d.%02d, compression level %"PRIu16"\n",

           ape->fileversion / 1000, (ape->fileversion % 1000) / 10,

           ape->compressiontype);



    /* now we are ready: build format streams */

    st = avformat_new_stream(s, NULL);

    if (!st)

        return -1;



    total_blocks = (ape->totalframes == 0) ? 0 : ((ape->totalframes - 1) * ape->blocksperframe) + ape->finalframeblocks;



    st->codecpar->codec_type      = AVMEDIA_TYPE_AUDIO;

    st->codecpar->codec_id        = AV_CODEC_ID_APE;

    st->codecpar->codec_tag       = MKTAG('A', 'P', 'E', ' ');

    st->codecpar->channels        = ape->channels;

    st->codecpar->sample_rate     = ape->samplerate;

    st->codecpar->bits_per_coded_sample = ape->bps;



    st->nb_frames = ape->totalframes;

    st->start_time = 0;

    st->duration  = total_blocks / MAC_SUBFRAME_SIZE;

    avpriv_set_pts_info(st, 64, MAC_SUBFRAME_SIZE, ape->samplerate);



    st->codecpar->extradata = av_malloc(APE_EXTRADATA_SIZE);

    st->codecpar->extradata_size = APE_EXTRADATA_SIZE;

    AV_WL16(st->codecpar->extradata + 0, ape->fileversion);

    AV_WL16(st->codecpar->extradata + 2, ape->compressiontype);

    AV_WL16(st->codecpar->extradata + 4, ape->formatflags);



    pts = 0;

    for (i = 0; i < ape->totalframes; i++) {

        ape->frames[i].pts = pts;

        av_add_index_entry(st, ape->frames[i].pos, ape->frames[i].pts, 0, 0, AVINDEX_KEYFRAME);

        pts += ape->blocksperframe / MAC_SUBFRAME_SIZE;

    }



    /* try to read APE tags */

    if (pb->seekable) {

        ff_ape_parse_tag(s);

        avio_seek(pb, 0, SEEK_SET);

    }



    return 0;

}

static void ERROR(const char *str)

{

        fprintf(stderr, "%s\n", str);

        exit(1);

}

static int asf_write_header1(AVFormatContext *s, int64_t file_size,

                             int64_t data_chunk_size)

{

    ASFContext *asf = s->priv_data;

    AVIOContext *pb = s->pb;

    AVDictionaryEntry *tags[5];

    int header_size, n, extra_size, extra_size2, wav_extra_size, file_time;

    int has_title, has_aspect_ratio = 0;

    int metadata_count;

    AVCodecContext *enc;

    int64_t header_offset, cur_pos, hpos;

    int bit_rate;

    int64_t duration;



    ff_metadata_conv(&s->metadata, ff_asf_metadata_conv, NULL);



    tags[0] = av_dict_get(s->metadata, "title", NULL, 0);

    tags[1] = av_dict_get(s->metadata, "author", NULL, 0);

    tags[2] = av_dict_get(s->metadata, "copyright", NULL, 0);

    tags[3] = av_dict_get(s->metadata, "comment", NULL, 0);

    tags[4] = av_dict_get(s->metadata, "rating", NULL, 0);



    duration       = asf->duration + PREROLL_TIME * 10000;

    has_title      = tags[0] || tags[1] || tags[2] || tags[3] || tags[4];

    metadata_count = av_dict_count(s->metadata);



    bit_rate = 0;

    for (n = 0; n < s->nb_streams; n++) {

        enc = s->streams[n]->codec;



        avpriv_set_pts_info(s->streams[n], 32, 1, 1000); /* 32 bit pts in ms */



        bit_rate += enc->bit_rate;

        if (   enc->codec_type == AVMEDIA_TYPE_VIDEO

            && enc->sample_aspect_ratio.num > 0

            && enc->sample_aspect_ratio.den > 0)

            has_aspect_ratio++;

    }



    if (asf->is_streamed) {

        put_chunk(s, 0x4824, 0, 0xc00); /* start of stream (length will be patched later) */

    }



    ff_put_guid(pb, &ff_asf_header);

    avio_wl64(pb, -1); /* header length, will be patched after */

    avio_wl32(pb, 3 + has_title + !!metadata_count + s->nb_streams); /* number of chunks in header */

    avio_w8(pb, 1); /* ??? */

    avio_w8(pb, 2); /* ??? */



    /* file header */

    header_offset = avio_tell(pb);

    hpos          = put_header(pb, &ff_asf_file_header);

    ff_put_guid(pb, &ff_asf_my_guid);

    avio_wl64(pb, file_size);

    file_time = 0;

    avio_wl64(pb, unix_to_file_time(file_time));

    avio_wl64(pb, asf->nb_packets); /* number of packets */

    avio_wl64(pb, duration); /* end time stamp (in 100ns units) */

    avio_wl64(pb, asf->duration); /* duration (in 100ns units) */

    avio_wl64(pb, PREROLL_TIME); /* start time stamp */

    avio_wl32(pb, (asf->is_streamed || !pb->seekable) ? 3 : 2);  /* ??? */

    avio_wl32(pb, s->packet_size); /* packet size */

    avio_wl32(pb, s->packet_size); /* packet size */

    avio_wl32(pb, bit_rate ? bit_rate : -1); /* Maximum data rate in bps */

    end_header(pb, hpos);



    /* unknown headers */

    hpos = put_header(pb, &ff_asf_head1_guid);

    ff_put_guid(pb, &ff_asf_head2_guid);

    avio_wl16(pb, 6);

    if (has_aspect_ratio) {

        int64_t hpos2;

        avio_wl32(pb, 26 + has_aspect_ratio * 84);

        hpos2 = put_header(pb, &ff_asf_metadata_header);

        avio_wl16(pb, 2 * has_aspect_ratio);

        for (n = 0; n < s->nb_streams; n++) {

            enc = s->streams[n]->codec;

            if (   enc->codec_type == AVMEDIA_TYPE_VIDEO

                && enc->sample_aspect_ratio.num > 0

                && enc->sample_aspect_ratio.den > 0) {

                AVRational sar = enc->sample_aspect_ratio;

                avio_wl16(pb, 0);

                // the stream number is set like this below

                avio_wl16(pb, n + 1);

                avio_wl16(pb, 26); // name_len

                avio_wl16(pb,  3); // value_type

                avio_wl32(pb,  4); // value_len

                avio_put_str16le(pb, "AspectRatioX");

                avio_wl32(pb, sar.num);

                avio_wl16(pb, 0);

                // the stream number is set like this below

                avio_wl16(pb, n + 1);

                avio_wl16(pb, 26); // name_len

                avio_wl16(pb,  3); // value_type

                avio_wl32(pb,  4); // value_len

                avio_put_str16le(pb, "AspectRatioY");

                avio_wl32(pb, sar.den);

            }

        }

        end_header(pb, hpos2);

    } else {

        avio_wl32(pb, 0);

    }

    end_header(pb, hpos);



    /* title and other infos */

    if (has_title) {

        int len;

        uint8_t *buf;

        AVIOContext *dyn_buf;



        if (avio_open_dyn_buf(&dyn_buf) < 0)

            return AVERROR(ENOMEM);



        hpos = put_header(pb, &ff_asf_comment_header);



        for (n = 0; n < FF_ARRAY_ELEMS(tags); n++) {

            len = tags[n] ? avio_put_str16le(dyn_buf, tags[n]->value) : 0;

            avio_wl16(pb, len);

        }

        len = avio_close_dyn_buf(dyn_buf, &buf);

        avio_write(pb, buf, len);

        av_freep(&buf);

        end_header(pb, hpos);

    }

    if (metadata_count) {

        AVDictionaryEntry *tag = NULL;

        hpos = put_header(pb, &ff_asf_extended_content_header);

        avio_wl16(pb, metadata_count);

        while ((tag = av_dict_get(s->metadata, "", tag, AV_DICT_IGNORE_SUFFIX))) {

            put_str16(pb, tag->key);

            avio_wl16(pb, 0);

            put_str16(pb, tag->value);

        }

        end_header(pb, hpos);

    }

    /* chapters using ASF markers */

    if (!asf->is_streamed && s->nb_chapters) {

        int ret;

        if (ret = asf_write_markers(s))

            return ret;

    }

    /* stream headers */

    for (n = 0; n < s->nb_streams; n++) {

        int64_t es_pos;

        //        ASFStream *stream = &asf->streams[n];



        enc                 = s->streams[n]->codec;

        asf->streams[n].num = n + 1;

        asf->streams[n].seq = 1;



        switch (enc->codec_type) {

        case AVMEDIA_TYPE_AUDIO:

            wav_extra_size = 0;

            extra_size     = 18 + wav_extra_size;

            extra_size2    = 8;

            break;

        default:

        case AVMEDIA_TYPE_VIDEO:

            wav_extra_size = enc->extradata_size;

            extra_size     = 0x33 + wav_extra_size;

            extra_size2    = 0;

            break;

        }



        hpos = put_header(pb, &ff_asf_stream_header);

        if (enc->codec_type == AVMEDIA_TYPE_AUDIO) {

            ff_put_guid(pb, &ff_asf_audio_stream);

            ff_put_guid(pb, &ff_asf_audio_conceal_spread);

        } else {

            ff_put_guid(pb, &ff_asf_video_stream);

            ff_put_guid(pb, &ff_asf_video_conceal_none);

        }

        avio_wl64(pb, 0); /* ??? */

        es_pos = avio_tell(pb);

        avio_wl32(pb, extra_size); /* wav header len */

        avio_wl32(pb, extra_size2); /* additional data len */

        avio_wl16(pb, n + 1); /* stream number */

        avio_wl32(pb, 0); /* ??? */



        if (enc->codec_type == AVMEDIA_TYPE_AUDIO) {

            /* WAVEFORMATEX header */

            int wavsize = ff_put_wav_header(pb, enc, FF_PUT_WAV_HEADER_FORCE_WAVEFORMATEX);



            if (wavsize < 0)

                return -1;

            if (wavsize != extra_size) {

                cur_pos = avio_tell(pb);

                avio_seek(pb, es_pos, SEEK_SET);

                avio_wl32(pb, wavsize); /* wav header len */

                avio_seek(pb, cur_pos, SEEK_SET);

            }

            /* ERROR Correction */

            avio_w8(pb, 0x01);

            if (enc->codec_id == AV_CODEC_ID_ADPCM_G726 || !enc->block_align) {

                avio_wl16(pb, 0x0190);

                avio_wl16(pb, 0x0190);

            } else {

                avio_wl16(pb, enc->block_align);

                avio_wl16(pb, enc->block_align);

            }

            avio_wl16(pb, 0x01);

            avio_w8(pb, 0x00);

        } else {

            avio_wl32(pb, enc->width);

            avio_wl32(pb, enc->height);

            avio_w8(pb, 2); /* ??? */

            avio_wl16(pb, 40 + enc->extradata_size); /* size */



            /* BITMAPINFOHEADER header */

            ff_put_bmp_header(pb, enc, ff_codec_bmp_tags, 1, 0);

        }

        end_header(pb, hpos);

    }



    /* media comments */



    hpos = put_header(pb, &ff_asf_codec_comment_header);

    ff_put_guid(pb, &ff_asf_codec_comment1_header);

    avio_wl32(pb, s->nb_streams);

    for (n = 0; n < s->nb_streams; n++) {

        const AVCodecDescriptor *codec_desc;

        const char *desc;



        enc  = s->streams[n]->codec;

        codec_desc = avcodec_descriptor_get(enc->codec_id);



        if (enc->codec_type == AVMEDIA_TYPE_AUDIO)

            avio_wl16(pb, 2);

        else if (enc->codec_type == AVMEDIA_TYPE_VIDEO)

            avio_wl16(pb, 1);

        else

            avio_wl16(pb, -1);



        if (enc->codec_id == AV_CODEC_ID_WMAV2)

            desc = "Windows Media Audio V8";

        else

            desc = codec_desc ? codec_desc->name : NULL;



        if (desc) {

            AVIOContext *dyn_buf;

            uint8_t *buf;

            int len;



            if (avio_open_dyn_buf(&dyn_buf) < 0)

                return AVERROR(ENOMEM);



            avio_put_str16le(dyn_buf, desc);

            len = avio_close_dyn_buf(dyn_buf, &buf);

            avio_wl16(pb, len / 2); // "number of characters" = length in bytes / 2



            avio_write(pb, buf, len);

            av_freep(&buf);

        } else

            avio_wl16(pb, 0);



        avio_wl16(pb, 0); /* no parameters */



        /* id */

        if (enc->codec_type == AVMEDIA_TYPE_AUDIO) {

            avio_wl16(pb, 2);

            avio_wl16(pb, enc->codec_tag);

        } else {

            avio_wl16(pb, 4);

            avio_wl32(pb, enc->codec_tag);

        }

        if (!enc->codec_tag)

            return -1;

    }

    end_header(pb, hpos);



    /* patch the header size fields */



    cur_pos     = avio_tell(pb);

    header_size = cur_pos - header_offset;

    if (asf->is_streamed) {

        header_size += 8 + 30 + DATA_HEADER_SIZE;



        avio_seek(pb, header_offset - 10 - 30, SEEK_SET);

        avio_wl16(pb, header_size);

        avio_seek(pb, header_offset - 2 - 30, SEEK_SET);

        avio_wl16(pb, header_size);



        header_size -= 8 + 30 + DATA_HEADER_SIZE;

    }

    header_size += 24 + 6;

    avio_seek(pb, header_offset - 14, SEEK_SET);

    avio_wl64(pb, header_size);

    avio_seek(pb, cur_pos, SEEK_SET);



    /* movie chunk, followed by packets of packet_size */

    asf->data_offset = cur_pos;

    ff_put_guid(pb, &ff_asf_data_header);

    avio_wl64(pb, data_chunk_size);

    ff_put_guid(pb, &ff_asf_my_guid);

    avio_wl64(pb, asf->nb_packets); /* nb packets */

    avio_w8(pb, 1); /* ??? */

    avio_w8(pb, 1); /* ??? */

    return 0;

}

static unsigned int codec_get_asf_tag(const CodecTag *tags, unsigned int id)

{

    while (tags->id != 0) {

        if (!tags->invalid_asf && tags->id == id)

            return tags->tag;

        tags++;

    }

    return 0;

}

static int decode_cblk(J2kDecoderContext *s, J2kCodingStyle *codsty, J2kT1Context *t1, J2kCblk *cblk,

                       int width, int height, int bandpos)

{

    int passno = cblk->npasses, pass_t = 2, bpno = cblk->nonzerobits - 1, y, clnpass_cnt = 0;

    int bpass_csty_symbol = J2K_CBLK_BYPASS & codsty->cblk_style;

    int vert_causal_ctx_csty_symbol = J2K_CBLK_VSC & codsty->cblk_style;



    for (y = 0; y < height+2; y++)

        memset(t1->flags[y], 0, (width+2)*sizeof(int));



    for (y = 0; y < height; y++)

        memset(t1->data[y], 0, width*sizeof(int));



    ff_mqc_initdec(&t1->mqc, cblk->data);

    cblk->data[cblk->length] = 0xff;

    cblk->data[cblk->length+1] = 0xff;



    while(passno--){

        switch(pass_t){

            case 0: decode_sigpass(t1, width, height, bpno+1, bandpos,

                                  bpass_csty_symbol && (clnpass_cnt >= 4), vert_causal_ctx_csty_symbol);

                    break;

            case 1: decode_refpass(t1, width, height, bpno+1);

                    if (bpass_csty_symbol && clnpass_cnt >= 4)

                        ff_mqc_initdec(&t1->mqc, cblk->data);

                    break;

            case 2: decode_clnpass(s, t1, width, height, bpno+1, bandpos,

                                   codsty->cblk_style & J2K_CBLK_SEGSYM);

                    clnpass_cnt = clnpass_cnt + 1;

                    if (bpass_csty_symbol && clnpass_cnt >= 4)

                       ff_mqc_initdec(&t1->mqc, cblk->data);

                    break;

        }



        pass_t++;

        if (pass_t == 3){

            bpno--;

            pass_t = 0;

        }

    }

    return 0;

}

int ff_eac3_parse_header(AC3DecodeContext *s)

{

    int i, blk, ch;

    int ac3_exponent_strategy, parse_aht_info, parse_spx_atten_data;

    int parse_transient_proc_info;

    int num_cpl_blocks;

    GetBitContext *gbc = &s->gbc;



    /* An E-AC-3 stream can have multiple independent streams which the

       application can select from. each independent stream can also contain

       dependent streams which are used to add or replace channels. */

    if (s->frame_type == EAC3_FRAME_TYPE_DEPENDENT) {

        avpriv_request_sample(s->avctx, "Dependent substream decoding");

        return AAC_AC3_PARSE_ERROR_FRAME_TYPE;

    } else if (s->frame_type == EAC3_FRAME_TYPE_RESERVED) {

        av_log(s->avctx, AV_LOG_ERROR, "Reserved frame type\n");

        return AAC_AC3_PARSE_ERROR_FRAME_TYPE;

    }



    /* The substream id indicates which substream this frame belongs to. each

       independent stream has its own substream id, and the dependent streams

       associated to an independent stream have matching substream id's. */

    if (s->substreamid) {

        /* only decode substream with id=0. skip any additional substreams. */

        avpriv_request_sample(s->avctx, "Additional substreams");

        return AAC_AC3_PARSE_ERROR_FRAME_TYPE;

    }



    if (s->bit_alloc_params.sr_code == EAC3_SR_CODE_REDUCED) {

        /* The E-AC-3 specification does not tell how to handle reduced sample

           rates in bit allocation.  The best assumption would be that it is

           handled like AC-3 DolbyNet, but we cannot be sure until we have a

           sample which utilizes this feature. */

        avpriv_request_sample(s->avctx, "Reduced sampling rate");

        return AVERROR_PATCHWELCOME;

    }

    skip_bits(gbc, 5); // skip bitstream id



    /* volume control params */

    for (i = 0; i < (s->channel_mode ? 1 : 2); i++) {

        skip_bits(gbc, 5); // skip dialog normalization

        if (get_bits1(gbc)) {

            skip_bits(gbc, 8); // skip compression gain word

        }

    }



    /* dependent stream channel map */

    if (s->frame_type == EAC3_FRAME_TYPE_DEPENDENT) {

        if (get_bits1(gbc)) {

            skip_bits(gbc, 16); // skip custom channel map

        }

    }



    /* mixing metadata */

    if (get_bits1(gbc)) {

        /* center and surround mix levels */

        if (s->channel_mode > AC3_CHMODE_STEREO) {

            s->preferred_downmix = get_bits(gbc, 2);

            if (s->channel_mode & 1) {

                /* if three front channels exist */

                s->center_mix_level_ltrt = get_bits(gbc, 3);

                s->center_mix_level      = get_bits(gbc, 3);

            }

            if (s->channel_mode & 4) {

                /* if a surround channel exists */

                s->surround_mix_level_ltrt = av_clip(get_bits(gbc, 3), 3, 7);

                s->surround_mix_level      = av_clip(get_bits(gbc, 3), 3, 7);

            }

        }



        /* lfe mix level */

        if (s->lfe_on && (s->lfe_mix_level_exists = get_bits1(gbc))) {

            s->lfe_mix_level = get_bits(gbc, 5);

        }



        /* info for mixing with other streams and substreams */

        if (s->frame_type == EAC3_FRAME_TYPE_INDEPENDENT) {

            for (i = 0; i < (s->channel_mode ? 1 : 2); i++) {

                // TODO: apply program scale factor

                if (get_bits1(gbc)) {

                    skip_bits(gbc, 6);  // skip program scale factor

                }

            }

            if (get_bits1(gbc)) {

                skip_bits(gbc, 6);  // skip external program scale factor

            }

            /* skip mixing parameter data */

            switch(get_bits(gbc, 2)) {

                case 1: skip_bits(gbc, 5);  break;

                case 2: skip_bits(gbc, 12); break;

                case 3: {

                    int mix_data_size = (get_bits(gbc, 5) + 2) << 3;

                    skip_bits_long(gbc, mix_data_size);

                    break;

                }

            }

            /* skip pan information for mono or dual mono source */

            if (s->channel_mode < AC3_CHMODE_STEREO) {

                for (i = 0; i < (s->channel_mode ? 1 : 2); i++) {

                    if (get_bits1(gbc)) {

                        /* note: this is not in the ATSC A/52B specification

                           reference: ETSI TS 102 366 V1.1.1

                                      section: E.1.3.1.25 */

                        skip_bits(gbc, 8);  // skip pan mean direction index

                        skip_bits(gbc, 6);  // skip reserved paninfo bits

                    }

                }

            }

            /* skip mixing configuration information */

            if (get_bits1(gbc)) {

                for (blk = 0; blk < s->num_blocks; blk++) {

                    if (s->num_blocks == 1 || get_bits1(gbc)) {

                        skip_bits(gbc, 5);

                    }

                }

            }

        }

    }



    /* informational metadata */

    if (get_bits1(gbc)) {

        s->bitstream_mode = get_bits(gbc, 3);

        skip_bits(gbc, 2); // skip copyright bit and original bitstream bit

        if (s->channel_mode == AC3_CHMODE_STEREO) {

            s->dolby_surround_mode  = get_bits(gbc, 2);

            s->dolby_headphone_mode = get_bits(gbc, 2);

        }

        if (s->channel_mode >= AC3_CHMODE_2F2R) {

            s->dolby_surround_ex_mode = get_bits(gbc, 2);

        }

        for (i = 0; i < (s->channel_mode ? 1 : 2); i++) {

            if (get_bits1(gbc)) {

                skip_bits(gbc, 8); // skip mix level, room type, and A/D converter type

            }

        }

        if (s->bit_alloc_params.sr_code != EAC3_SR_CODE_REDUCED) {

            skip_bits1(gbc); // skip source sample rate code

        }

    }



    /* converter synchronization flag

       If frames are less than six blocks, this bit should be turned on

       once every 6 blocks to indicate the start of a frame set.

       reference: RFC 4598, Section 2.1.3  Frame Sets */

    if (s->frame_type == EAC3_FRAME_TYPE_INDEPENDENT && s->num_blocks != 6) {

        skip_bits1(gbc); // skip converter synchronization flag

    }



    /* original frame size code if this stream was converted from AC-3 */

    if (s->frame_type == EAC3_FRAME_TYPE_AC3_CONVERT &&

            (s->num_blocks == 6 || get_bits1(gbc))) {

        skip_bits(gbc, 6); // skip frame size code

    }



    /* additional bitstream info */

    if (get_bits1(gbc)) {

        int addbsil = get_bits(gbc, 6);

        for (i = 0; i < addbsil + 1; i++) {

            skip_bits(gbc, 8); // skip additional bit stream info

        }

    }



    /* audio frame syntax flags, strategy data, and per-frame data */



    if (s->num_blocks == 6) {

        ac3_exponent_strategy = get_bits1(gbc);

        parse_aht_info        = get_bits1(gbc);

    } else {

        /* less than 6 blocks, so use AC-3-style exponent strategy syntax, and

           do not use AHT */

        ac3_exponent_strategy = 1;

        parse_aht_info = 0;

    }



    s->snr_offset_strategy    = get_bits(gbc, 2);

    parse_transient_proc_info = get_bits1(gbc);



    s->block_switch_syntax = get_bits1(gbc);

    if (!s->block_switch_syntax)

        memset(s->block_switch, 0, sizeof(s->block_switch));



    s->dither_flag_syntax = get_bits1(gbc);

    if (!s->dither_flag_syntax) {

        for (ch = 1; ch <= s->fbw_channels; ch++)

            s->dither_flag[ch] = 1;

    }

    s->dither_flag[CPL_CH] = s->dither_flag[s->lfe_ch] = 0;



    s->bit_allocation_syntax = get_bits1(gbc);

    if (!s->bit_allocation_syntax) {

        /* set default bit allocation parameters */

        s->bit_alloc_params.slow_decay = ff_ac3_slow_decay_tab[2];

        s->bit_alloc_params.fast_decay = ff_ac3_fast_decay_tab[1];

        s->bit_alloc_params.slow_gain  = ff_ac3_slow_gain_tab [1];

        s->bit_alloc_params.db_per_bit = ff_ac3_db_per_bit_tab[2];

        s->bit_alloc_params.floor      = ff_ac3_floor_tab     [7];

    }



    s->fast_gain_syntax  = get_bits1(gbc);

    s->dba_syntax        = get_bits1(gbc);

    s->skip_syntax       = get_bits1(gbc);

    parse_spx_atten_data = get_bits1(gbc);



    /* coupling strategy occurrence and coupling use per block */

    num_cpl_blocks = 0;

    if (s->channel_mode > 1) {

        for (blk = 0; blk < s->num_blocks; blk++) {

            s->cpl_strategy_exists[blk] = (!blk || get_bits1(gbc));

            if (s->cpl_strategy_exists[blk]) {

                s->cpl_in_use[blk] = get_bits1(gbc);

            } else {

                s->cpl_in_use[blk] = s->cpl_in_use[blk-1];

            }

            num_cpl_blocks += s->cpl_in_use[blk];

        }

    } else {

        memset(s->cpl_in_use, 0, sizeof(s->cpl_in_use));

    }



    /* exponent strategy data */

    if (ac3_exponent_strategy) {

        /* AC-3-style exponent strategy syntax */

        for (blk = 0; blk < s->num_blocks; blk++) {

            for (ch = !s->cpl_in_use[blk]; ch <= s->fbw_channels; ch++) {

                s->exp_strategy[blk][ch] = get_bits(gbc, 2);

            }

        }

    } else {

        /* LUT-based exponent strategy syntax */

        for (ch = !((s->channel_mode > 1) && num_cpl_blocks); ch <= s->fbw_channels; ch++) {

            int frmchexpstr = get_bits(gbc, 5);

            for (blk = 0; blk < 6; blk++) {

                s->exp_strategy[blk][ch] = ff_eac3_frm_expstr[frmchexpstr][blk];

            }

        }

    }

    /* LFE exponent strategy */

    if (s->lfe_on) {

        for (blk = 0; blk < s->num_blocks; blk++) {

            s->exp_strategy[blk][s->lfe_ch] = get_bits1(gbc);

        }

    }

    /* original exponent strategies if this stream was converted from AC-3 */

    if (s->frame_type == EAC3_FRAME_TYPE_INDEPENDENT &&

            (s->num_blocks == 6 || get_bits1(gbc))) {

        skip_bits(gbc, 5 * s->fbw_channels); // skip converter channel exponent strategy

    }



    /* determine which channels use AHT */

    if (parse_aht_info) {

        /* For AHT to be used, all non-zero blocks must reuse exponents from

           the first block.  Furthermore, for AHT to be used in the coupling

           channel, all blocks must use coupling and use the same coupling

           strategy. */

        s->channel_uses_aht[CPL_CH]=0;

        for (ch = (num_cpl_blocks != 6); ch <= s->channels; ch++) {

            int use_aht = 1;

            for (blk = 1; blk < 6; blk++) {

                if ((s->exp_strategy[blk][ch] != EXP_REUSE) ||

                        (!ch && s->cpl_strategy_exists[blk])) {

                    use_aht = 0;

                    break;

                }

            }

            s->channel_uses_aht[ch] = use_aht && get_bits1(gbc);

        }

    } else {

        memset(s->channel_uses_aht, 0, sizeof(s->channel_uses_aht));

    }



    /* per-frame SNR offset */

    if (!s->snr_offset_strategy) {

        int csnroffst = (get_bits(gbc, 6) - 15) << 4;

        int snroffst = (csnroffst + get_bits(gbc, 4)) << 2;

        for (ch = 0; ch <= s->channels; ch++)

            s->snr_offset[ch] = snroffst;

    }



    /* transient pre-noise processing data */

    if (parse_transient_proc_info) {

        for (ch = 1; ch <= s->fbw_channels; ch++) {

            if (get_bits1(gbc)) { // channel in transient processing

                skip_bits(gbc, 10); // skip transient processing location

                skip_bits(gbc, 8);  // skip transient processing length

            }

        }

    }



    /* spectral extension attenuation data */

    for (ch = 1; ch <= s->fbw_channels; ch++) {

        if (parse_spx_atten_data && get_bits1(gbc)) {

            s->spx_atten_code[ch] = get_bits(gbc, 5);

        } else {

            s->spx_atten_code[ch] = -1;

        }

    }



    /* block start information */

    if (s->num_blocks > 1 && get_bits1(gbc)) {

        /* reference: Section E2.3.2.27

           nblkstrtbits = (numblks - 1) * (4 + ceiling(log2(words_per_frame)))

           The spec does not say what this data is or what it's used for.

           It is likely the offset of each block within the frame. */

        int block_start_bits = (s->num_blocks-1) * (4 + av_log2(s->frame_size-2));

        skip_bits_long(gbc, block_start_bits);

        avpriv_request_sample(s->avctx, "Block start info");

    }



    /* syntax state initialization */

    for (ch = 1; ch <= s->fbw_channels; ch++) {

        s->first_spx_coords[ch] = 1;

        s->first_cpl_coords[ch] = 1;

    }

    s->first_cpl_leak = 1;



    return 0;

}

static int calc_bit_demand(AacPsyContext *ctx, float pe, int bits, int size,

                           int short_window)

{

    const float bitsave_slope  = short_window ? PSY_3GPP_SAVE_SLOPE_S  : PSY_3GPP_SAVE_SLOPE_L;

    const float bitsave_add    = short_window ? PSY_3GPP_SAVE_ADD_S    : PSY_3GPP_SAVE_ADD_L;

    const float bitspend_slope = short_window ? PSY_3GPP_SPEND_SLOPE_S : PSY_3GPP_SPEND_SLOPE_L;

    const float bitspend_add   = short_window ? PSY_3GPP_SPEND_ADD_S   : PSY_3GPP_SPEND_ADD_L;

    const float clip_low       = short_window ? PSY_3GPP_CLIP_LO_S     : PSY_3GPP_CLIP_LO_L;

    const float clip_high      = short_window ? PSY_3GPP_CLIP_HI_S     : PSY_3GPP_CLIP_HI_L;

    float clipped_pe, bit_save, bit_spend, bit_factor, fill_level;



    ctx->fill_level += ctx->frame_bits - bits;

    ctx->fill_level  = av_clip(ctx->fill_level, 0, size);

    fill_level = av_clipf((float)ctx->fill_level / size, clip_low, clip_high);

    clipped_pe = av_clipf(pe, ctx->pe.min, ctx->pe.max);

    bit_save   = (fill_level + bitsave_add) * bitsave_slope;

    assert(bit_save <= 0.3f && bit_save >= -0.05000001f);

    bit_spend  = (fill_level + bitspend_add) * bitspend_slope;

    assert(bit_spend <= 0.5f && bit_spend >= -0.1f);

    /* The bit factor graph in the spec is obviously incorrect.

     *      bit_spend + ((bit_spend - bit_spend))...

     * The reference encoder subtracts everything from 1, but also seems incorrect.

     *      1 - bit_save + ((bit_spend + bit_save))...

     * Hopefully below is correct.

     */

    bit_factor = 1.0f - bit_save + ((bit_spend - bit_save) / (ctx->pe.max - ctx->pe.min)) * (clipped_pe - ctx->pe.min);

    /* NOTE: The reference encoder attempts to center pe max/min around the current pe. */

    ctx->pe.max = FFMAX(pe, ctx->pe.max);

    ctx->pe.min = FFMIN(pe, ctx->pe.min);



    return FFMIN(ctx->frame_bits * bit_factor, ctx->frame_bits + size - bits);

}

static void RENAME(yuyvtoyuv420)(uint8_t *ydst, uint8_t *udst, uint8_t *vdst, const uint8_t *src,

                                      long width, long height,

                                      long lumStride, long chromStride, long srcStride)

{

    long y;

    const long chromWidth= -((-width)>>1);



    for (y=0; y<height; y++) {

        RENAME(extract_even)(src, ydst, width);

        if(y&1) {

            RENAME(extract_odd2avg)(src-srcStride, src, udst, vdst, chromWidth);

            udst+= chromStride;

            vdst+= chromStride;

        }



        src += srcStride;

        ydst+= lumStride;

    }

#if COMPILE_TEMPLATE_MMX

    __asm__(

            EMMS"       \n\t"

            SFENCE"     \n\t"

            ::: "memory"

        );

#endif

}

static uint64_t log16(uint64_t a){

    int i;

    int out=0;



    assert(a >= (1<<16));

    a<<=16;



    for(i=19;i>=0;i--){

        if(a<(exp16_table[i]<<16)) continue;

        out |= 1<<i;

        a = ((a<<16) + exp16_table[i]/2)/exp16_table[i];

    }

    return out;

}

static int mxf_read_track(void *arg, AVIOContext *pb, int tag, int size, UID uid)

{

    MXFTrack *track = arg;

    switch(tag) {

    case 0x4801:

        track->track_id = avio_rb32(pb);

        break;

    case 0x4804:

        avio_read(pb, track->track_number, 4);

        break;

    case 0x4B01:

        track->edit_rate.den = avio_rb32(pb);

        track->edit_rate.num = avio_rb32(pb);

        break;

    case 0x4803:

        avio_read(pb, track->sequence_ref, 16);

        break;

    }

    return 0;

}

static int dxva2_get_decoder_configuration(AVCodecContext *s, const GUID *device_guid,

                                           const DXVA2_VideoDesc *desc,

                                           DXVA2_ConfigPictureDecode *config)

{

    InputStream  *ist = s->opaque;

    int loglevel = (ist->hwaccel_id == HWACCEL_AUTO) ? AV_LOG_VERBOSE : AV_LOG_ERROR;

    DXVA2Context *ctx = ist->hwaccel_ctx;

    unsigned cfg_count = 0, best_score = 0;

    DXVA2_ConfigPictureDecode *cfg_list = NULL;

    DXVA2_ConfigPictureDecode best_cfg = {{0}};

    HRESULT hr;

    int i;



    hr = IDirectXVideoDecoderService_GetDecoderConfigurations(ctx->decoder_service, device_guid, desc, NULL, &cfg_count, &cfg_list);

    if (FAILED(hr)) {

        av_log(NULL, loglevel, "Unable to retrieve decoder configurations\n");

        return AVERROR(EINVAL);

    }



    for (i = 0; i < cfg_count; i++) {

        DXVA2_ConfigPictureDecode *cfg = &cfg_list[i];



        unsigned score;

        if (cfg->ConfigBitstreamRaw == 1)

            score = 1;

        else if (s->codec_id == AV_CODEC_ID_H264 && cfg->ConfigBitstreamRaw == 2)

            score = 2;

        else

            continue;

        if (IsEqualGUID(&cfg->guidConfigBitstreamEncryption, &DXVA2_NoEncrypt))

            score += 16;

        if (score > best_score) {

            best_score = score;

            best_cfg   = *cfg;

        }

    }

    CoTaskMemFree(cfg_list);



    if (!best_score) {

        av_log(NULL, loglevel, "No valid decoder configuration available\n");

        return AVERROR(EINVAL);

    }



    *config = best_cfg;

    return 0;

}

static inline int RENAME(yuv420_rgb15)(SwsContext *c, uint8_t* src[], int srcStride[], int srcSliceY,

             int srcSliceH, uint8_t* dst[], int dstStride[]){

    int y, h_size;



    if(c->srcFormat == PIX_FMT_YUV422P){

	srcStride[1] *= 2;

	srcStride[2] *= 2;

    }



    h_size= (c->dstW+7)&~7;

    if(h_size*2 > dstStride[0]) h_size-=8;



    __asm__ __volatile__ ("pxor %mm4, %mm4;" /* zero mm4 */ );

//printf("%X %X %X %X %X %X %X %X %X %X\n", (int)&c->redDither, (int)&b5Dither, (int)src[0], (int)src[1], (int)src[2], (int)dst[0],

//srcStride[0],srcStride[1],srcStride[2],dstStride[0]);

    for (y= 0; y<srcSliceH; y++ ) {

	uint8_t *_image = dst[0] + (y+srcSliceY)*dstStride[0];

	uint8_t *_py = src[0] + y*srcStride[0];

	uint8_t *_pu = src[1] + (y>>1)*srcStride[1];

	uint8_t *_pv = src[2] + (y>>1)*srcStride[2];

	long index= -h_size/2;



	b5Dither= dither8[y&1];

	g6Dither= dither4[y&1];

	g5Dither= dither8[y&1];

	r5Dither= dither8[(y+1)&1];

	    /* this mmx assembly code deals with SINGLE scan line at a time, it convert 8

	       pixels in each iteration */

	    __asm__ __volatile__ (

	/* load data for start of next scan line */

		     "movd (%2, %0), %%mm0;" /* Load 4 Cb 00 00 00 00 u3 u2 u1 u0 */

		     "movd (%3, %0), %%mm1;" /* Load 4 Cr 00 00 00 00 v3 v2 v1 v0 */

		     "movq (%5, %0, 2), %%mm6;" /* Load 8  Y Y7 Y6 Y5 Y4 Y3 Y2 Y1 Y0 */

//		    ".balign 16			\n\t"

		    "1:				\n\t"

YUV2RGB



#ifdef DITHER1XBPP

			"paddusb "MANGLE(b5Dither)", %%mm0	\n\t"

			"paddusb "MANGLE(g5Dither)", %%mm2	\n\t"

			"paddusb "MANGLE(r5Dither)", %%mm1	\n\t"

#endif



		     /* mask unneeded bits off */

		     "pand "MANGLE(mmx_redmask)", %%mm0;" /* b7b6b5b4 b3_0_0_0 b7b6b5b4 b3_0_0_0 */

		     "pand "MANGLE(mmx_redmask)", %%mm2;" /* g7g6g5g4 g3_0_0_0 g7g6g5g4 g3_0_0_0 */

		     "pand "MANGLE(mmx_redmask)", %%mm1;" /* r7r6r5r4 r3_0_0_0 r7r6r5r4 r3_0_0_0 */



		     "psrlw $3,%%mm0;" /* 0_0_0_b7 b6b5b4b3 0_0_0_b7 b6b5b4b3 */

		     "psrlw $1,%%mm1;"            /* 0_r7r6r5  r4r3_0_0 0_r7r6r5 r4r3_0_0 */

		     "pxor %%mm4, %%mm4;" /* zero mm4 */



		     "movq %%mm0, %%mm5;" /* Copy B7-B0 */

		     "movq %%mm2, %%mm7;" /* Copy G7-G0 */



		     /* convert rgb24 plane to rgb16 pack for pixel 0-3 */

		     "punpcklbw %%mm4, %%mm2;" /* 0_0_0_0 0_0_0_0 g7g6g5g4 g3_0_0_0 */

		     "punpcklbw %%mm1, %%mm0;" /* r7r6r5r4 r3_0_0_0 0_0_0_b7 b6b5b4b3 */



		     "psllw $2, %%mm2;" /* 0_0_0_0 0_0_g7g6 g5g4g3_0 0_0_0_0 */

		     "por %%mm2, %%mm0;" /* 0_r7r6r5 r4r3g7g6 g5g4g3b7 b6b5b4b3 */



		     "movq 8 (%5, %0, 2), %%mm6;" /* Load 8 Y Y7 Y6 Y5 Y4 Y3 Y2 Y1 Y0 */

		     MOVNTQ " %%mm0, (%1);" /* store pixel 0-3 */



		     /* convert rgb24 plane to rgb16 pack for pixel 0-3 */

		     "punpckhbw %%mm4, %%mm7;" /* 0_0_0_0 0_0_0_0 0_g7g6g5 g4g3_0_0 */

		     "punpckhbw %%mm1, %%mm5;" /* r7r6r5r4 r3_0_0_0 0_0_0_b7 b6b5b4b3 */



		     "psllw $2, %%mm7;" /* 0_0_0_0 0_0_g7g6 g5g4g3_0 0_0_0_0 */

		     "movd 4 (%2, %0), %%mm0;" /* Load 4 Cb 00 00 00 00 u3 u2 u1 u0 */



		     "por %%mm7, %%mm5;" /* 0_r7r6r5 r4r3g7g6 g5g4g3b7 b6b5b4b3 */

		     "movd 4 (%3, %0), %%mm1;" /* Load 4 Cr 00 00 00 00 v3 v2 v1 v0 */



		     MOVNTQ " %%mm5, 8 (%1);" /* store pixel 4-7 */



		     "add $16, %1			\n\t"

		     "add $4, %0			\n\t"

		     " js 1b				\n\t"

		     : "+r" (index), "+r" (_image)

		     : "r" (_pu - index), "r" (_pv - index), "r"(&c->redDither), "r" (_py - 2*index)

		     );

    }



    __asm__ __volatile__ (EMMS);

    return srcSliceH;

}

static void sdp_parse_line(AVFormatContext *s, SDPParseState *s1,

                           int letter, const char *buf)

{

    RTSPState *rt = s->priv_data;

    char buf1[64], st_type[64];

    const char *p;

    int codec_type, payload_type, i;

    AVStream *st;

    RTSPStream *rtsp_st;

    struct in_addr sdp_ip;

    int ttl;



#ifdef DEBUG

    printf("sdp: %c='%s'\n", letter, buf);

#endif



    p = buf;

    switch(letter) {

    case 'c':

        get_word(buf1, sizeof(buf1), &p);

        if (strcmp(buf1, "IN") != 0)

            return;

        get_word(buf1, sizeof(buf1), &p);

        if (strcmp(buf1, "IP4") != 0)

            return;

        get_word_sep(buf1, sizeof(buf1), "/", &p);

        if (inet_aton(buf1, &sdp_ip) == 0)

            return;

        ttl = 16;

        if (*p == '/') {

            p++;

            get_word_sep(buf1, sizeof(buf1), "/", &p);

            ttl = atoi(buf1);

        }

        if (s->nb_streams == 0) {

            s1->default_ip = sdp_ip;

            s1->default_ttl = ttl;

        } else {

            st = s->streams[s->nb_streams - 1];

            rtsp_st = st->priv_data;

            rtsp_st->sdp_ip = sdp_ip;

            rtsp_st->sdp_ttl = ttl;

        }

        break;

    case 's':

        pstrcpy(s->title, sizeof(s->title), p);

        break;

    case 'i':

        if (s->nb_streams == 0) {

            pstrcpy(s->comment, sizeof(s->comment), p);

            break;

        }

        break;

    case 'm':

        /* new stream */

        get_word(st_type, sizeof(st_type), &p);

        if (!strcmp(st_type, "audio")) {

            codec_type = CODEC_TYPE_AUDIO;

        } else if (!strcmp(st_type, "video")) {

            codec_type = CODEC_TYPE_VIDEO;

        } else {

            return;

        }

        rtsp_st = av_mallocz(sizeof(RTSPStream));

        if (!rtsp_st)

            return;

        rtsp_st->stream_index = -1;

        dynarray_add(&rt->rtsp_streams, &rt->nb_rtsp_streams, rtsp_st);



        rtsp_st->sdp_ip = s1->default_ip;

        rtsp_st->sdp_ttl = s1->default_ttl;



        get_word(buf1, sizeof(buf1), &p); /* port */

        rtsp_st->sdp_port = atoi(buf1);



        get_word(buf1, sizeof(buf1), &p); /* protocol (ignored) */



        /* XXX: handle list of formats */

        get_word(buf1, sizeof(buf1), &p); /* format list */

        rtsp_st->sdp_payload_type = atoi(buf1);



        if (rtsp_st->sdp_payload_type == RTP_PT_MPEG2TS) {

            /* no corresponding stream */

        } else {

            st = av_new_stream(s, 0);

            if (!st)

                return;

            st->priv_data = rtsp_st;

            rtsp_st->stream_index = st->index;

            st->codec.codec_type = codec_type;

            if (rtsp_st->sdp_payload_type < 96) {

                /* if standard payload type, we can find the codec right now */

                rtp_get_codec_info(&st->codec, rtsp_st->sdp_payload_type);

            }

        }

        /* put a default control url */

        pstrcpy(rtsp_st->control_url, sizeof(rtsp_st->control_url), s->filename);

        break;

    case 'a':

        if (strstart(p, "control:", &p) && s->nb_streams > 0) {

            char proto[32];

            /* get the control url */

            st = s->streams[s->nb_streams - 1];

            rtsp_st = st->priv_data;



            /* XXX: may need to add full url resolution */

            url_split(proto, sizeof(proto), NULL, 0, NULL, NULL, 0, p);

            if (proto[0] == '\0') {

                /* relative control URL */

                pstrcat(rtsp_st->control_url, sizeof(rtsp_st->control_url), "/");

                pstrcat(rtsp_st->control_url, sizeof(rtsp_st->control_url), p);

            } else {

                pstrcpy(rtsp_st->control_url, sizeof(rtsp_st->control_url), p);

            }

        } else if (strstart(p, "rtpmap:", &p)) {

            /* NOTE: rtpmap is only supported AFTER the 'm=' tag */

            get_word(buf1, sizeof(buf1), &p); 

            payload_type = atoi(buf1);

            for(i = 0; i < s->nb_streams;i++) {

                st = s->streams[i];

                rtsp_st = st->priv_data;

                if (rtsp_st->sdp_payload_type == payload_type) {

                    sdp_parse_rtpmap(&st->codec, p);

                }

            }

        } else if (strstart(p, "fmtp:", &p)) {

            /* NOTE: fmtp is only supported AFTER the 'a=rtpmap:xxx' tag */

            get_word(buf1, sizeof(buf1), &p); 

            payload_type = atoi(buf1);

            for(i = 0; i < s->nb_streams;i++) {

                st = s->streams[i];

                rtsp_st = st->priv_data;

                if (rtsp_st->sdp_payload_type == payload_type) {

                    sdp_parse_fmtp(&st->codec, p);

                }

            }

        }

        break;

    }

}

int avformat_alloc_output_context2(AVFormatContext **avctx, AVOutputFormat *oformat,

                                   const char *format, const char *filename)

{

    AVFormatContext *s = avformat_alloc_context();

    int ret = 0;



    *avctx = NULL;

    if (!s)

        goto nomem;



    if (!oformat) {

        if (format) {

            oformat = av_guess_format(format, NULL, NULL);

            if (!oformat) {

                av_log(s, AV_LOG_ERROR, "Requested output format '%s' is not a suitable output format\n", format);

                ret = AVERROR(EINVAL);

                goto error;

            }

        } else {

            oformat = av_guess_format(NULL, filename, NULL);

            if (!oformat) {

                ret = AVERROR(EINVAL);

                av_log(s, AV_LOG_ERROR, "Unable to find a suitable output format for '%s'\n",

                       filename);

                goto error;

            }

        }

    }



    s->oformat = oformat;

    if (s->oformat->priv_data_size > 0) {

        s->priv_data = av_mallocz(s->oformat->priv_data_size);

        if (!s->priv_data)

            goto nomem;

        if (s->oformat->priv_class) {

            *(const AVClass**)s->priv_data= s->oformat->priv_class;

            av_opt_set_defaults(s->priv_data);

        }

    } else

        s->priv_data = NULL;



    if (filename)

        av_strlcpy(s->filename, filename, sizeof(s->filename));

    *avctx = s;

    return 0;

nomem:

    av_log(s, AV_LOG_ERROR, "Out of memory\n");

    ret = AVERROR(ENOMEM);

error:

    avformat_free_context(s);

    return ret;

}

static av_cold int gif_encode_init(AVCodecContext *avctx)

{

    GIFContext *s = avctx->priv_data;



    if (avctx->width > 65535 || avctx->height > 65535) {

        av_log(avctx, AV_LOG_ERROR, "GIF does not support resolutions above 65535x65535\n");

        return AVERROR(EINVAL);

    }

#if FF_API_CODED_FRAME

FF_DISABLE_DEPRECATION_WARNINGS

    avctx->coded_frame->pict_type = AV_PICTURE_TYPE_I;

    avctx->coded_frame->key_frame = 1;

FF_ENABLE_DEPRECATION_WARNINGS

#endif



    s->transparent_index = -1;



    s->lzw = av_mallocz(ff_lzw_encode_state_size);

    s->buf = av_malloc(avctx->width*avctx->height*2);

    s->tmpl = av_malloc(avctx->width);

    if (!s->tmpl || !s->buf || !s->lzw)

        return AVERROR(ENOMEM);



    if (avpriv_set_systematic_pal2(s->palette, avctx->pix_fmt) < 0)

        av_assert0(avctx->pix_fmt == AV_PIX_FMT_PAL8);



    return 0;

}

static int mpeg4_decode_sprite_trajectory(Mpeg4DecContext *ctx, GetBitContext *gb)

{

    MpegEncContext *s = &ctx->m;

    int a     = 2 << s->sprite_warping_accuracy;

    int rho   = 3  - s->sprite_warping_accuracy;

    int r     = 16 / a;

    int alpha = 0;

    int beta  = 0;

    int w     = s->width;

    int h     = s->height;

    int min_ab, i, w2, h2, w3, h3;

    int sprite_ref[4][2];

    int virtual_ref[2][2];



    // only true for rectangle shapes

    const int vop_ref[4][2] = { { 0, 0 },         { s->width, 0 },

                                { 0, s->height }, { s->width, s->height } };

    int d[4][2]             = { { 0, 0 }, { 0, 0 }, { 0, 0 }, { 0, 0 } };



    if (w <= 0 || h <= 0)

        return AVERROR_INVALIDDATA;



    for (i = 0; i < ctx->num_sprite_warping_points; i++) {

        int length;

        int x = 0, y = 0;



        length = get_vlc2(gb, sprite_trajectory.table, SPRITE_TRAJ_VLC_BITS, 3);

        if (length)

            x = get_xbits(gb, length);



        if (!(ctx->divx_version == 500 && ctx->divx_build == 413))

            skip_bits1(gb);     /* marker bit */



        length = get_vlc2(gb, sprite_trajectory.table, SPRITE_TRAJ_VLC_BITS, 3);

        if (length)

            y = get_xbits(gb, length);



        skip_bits1(gb);         /* marker bit */

        ctx->sprite_traj[i][0] = d[i][0] = x;

        ctx->sprite_traj[i][1] = d[i][1] = y;

    }

    for (; i < 4; i++)

        ctx->sprite_traj[i][0] = ctx->sprite_traj[i][1] = 0;



    while ((1 << alpha) < w)

        alpha++;

    while ((1 << beta) < h)

        beta++;  /* typo in the mpeg4 std for the definition of w' and h' */

    w2 = 1 << alpha;

    h2 = 1 << beta;



    // Note, the 4th point isn't used for GMC

    if (ctx->divx_version == 500 && ctx->divx_build == 413) {

        sprite_ref[0][0] = a * vop_ref[0][0] + d[0][0];

        sprite_ref[0][1] = a * vop_ref[0][1] + d[0][1];

        sprite_ref[1][0] = a * vop_ref[1][0] + d[0][0] + d[1][0];

        sprite_ref[1][1] = a * vop_ref[1][1] + d[0][1] + d[1][1];

        sprite_ref[2][0] = a * vop_ref[2][0] + d[0][0] + d[2][0];

        sprite_ref[2][1] = a * vop_ref[2][1] + d[0][1] + d[2][1];

    } else {

        sprite_ref[0][0] = (a >> 1) * (2 * vop_ref[0][0] + d[0][0]);

        sprite_ref[0][1] = (a >> 1) * (2 * vop_ref[0][1] + d[0][1]);

        sprite_ref[1][0] = (a >> 1) * (2 * vop_ref[1][0] + d[0][0] + d[1][0]);

        sprite_ref[1][1] = (a >> 1) * (2 * vop_ref[1][1] + d[0][1] + d[1][1]);

        sprite_ref[2][0] = (a >> 1) * (2 * vop_ref[2][0] + d[0][0] + d[2][0]);

        sprite_ref[2][1] = (a >> 1) * (2 * vop_ref[2][1] + d[0][1] + d[2][1]);

    }

    /* sprite_ref[3][0] = (a >> 1) * (2 * vop_ref[3][0] + d[0][0] + d[1][0] + d[2][0] + d[3][0]);

     * sprite_ref[3][1] = (a >> 1) * (2 * vop_ref[3][1] + d[0][1] + d[1][1] + d[2][1] + d[3][1]); */



    /* this is mostly identical to the mpeg4 std (and is totally unreadable

     * because of that...). Perhaps it should be reordered to be more readable.

     * The idea behind this virtual_ref mess is to be able to use shifts later

     * per pixel instead of divides so the distance between points is converted

     * from w&h based to w2&h2 based which are of the 2^x form. */

    virtual_ref[0][0] = 16 * (vop_ref[0][0] + w2) +

                         ROUNDED_DIV(((w - w2) *

                                      (r * sprite_ref[0][0] - 16 * vop_ref[0][0]) +

                                      w2 * (r * sprite_ref[1][0] - 16 * vop_ref[1][0])), w);

    virtual_ref[0][1] = 16 * vop_ref[0][1] +

                        ROUNDED_DIV(((w - w2) *

                                     (r * sprite_ref[0][1] - 16 * vop_ref[0][1]) +

                                     w2 * (r * sprite_ref[1][1] - 16 * vop_ref[1][1])), w);

    virtual_ref[1][0] = 16 * vop_ref[0][0] +

                        ROUNDED_DIV(((h - h2) * (r * sprite_ref[0][0] - 16 * vop_ref[0][0]) +

                                     h2 * (r * sprite_ref[2][0] - 16 * vop_ref[2][0])), h);

    virtual_ref[1][1] = 16 * (vop_ref[0][1] + h2) +

                        ROUNDED_DIV(((h - h2) * (r * sprite_ref[0][1] - 16 * vop_ref[0][1]) +

                                     h2 * (r * sprite_ref[2][1] - 16 * vop_ref[2][1])), h);



    switch (ctx->num_sprite_warping_points) {

    case 0:

        s->sprite_offset[0][0] =

        s->sprite_offset[0][1] =

        s->sprite_offset[1][0] =

        s->sprite_offset[1][1] = 0;

        s->sprite_delta[0][0]  = a;

        s->sprite_delta[0][1]  =

        s->sprite_delta[1][0]  = 0;

        s->sprite_delta[1][1]  = a;

        ctx->sprite_shift[0]   =

        ctx->sprite_shift[1]   = 0;

        break;

    case 1:     // GMC only

        s->sprite_offset[0][0] = sprite_ref[0][0] - a * vop_ref[0][0];

        s->sprite_offset[0][1] = sprite_ref[0][1] - a * vop_ref[0][1];

        s->sprite_offset[1][0] = ((sprite_ref[0][0] >> 1) | (sprite_ref[0][0] & 1)) -

                                 a * (vop_ref[0][0] / 2);

        s->sprite_offset[1][1] = ((sprite_ref[0][1] >> 1) | (sprite_ref[0][1] & 1)) -

                                 a * (vop_ref[0][1] / 2);

        s->sprite_delta[0][0]  = a;

        s->sprite_delta[0][1]  =

        s->sprite_delta[1][0]  = 0;

        s->sprite_delta[1][1]  = a;

        ctx->sprite_shift[0]   =

        ctx->sprite_shift[1]   = 0;

        break;

    case 2:

        s->sprite_offset[0][0] = (sprite_ref[0][0] << (alpha + rho)) +

                                 (-r * sprite_ref[0][0] + virtual_ref[0][0]) *

                                 (-vop_ref[0][0]) +

                                 (r * sprite_ref[0][1] - virtual_ref[0][1]) *

                                 (-vop_ref[0][1]) + (1 << (alpha + rho - 1));

        s->sprite_offset[0][1] = (sprite_ref[0][1] << (alpha + rho)) +

                                 (-r * sprite_ref[0][1] + virtual_ref[0][1]) *

                                 (-vop_ref[0][0]) +

                                 (-r * sprite_ref[0][0] + virtual_ref[0][0]) *

                                 (-vop_ref[0][1]) + (1 << (alpha + rho - 1));

        s->sprite_offset[1][0] = ((-r * sprite_ref[0][0] + virtual_ref[0][0]) *

                                  (-2 * vop_ref[0][0] + 1) +

                                  (r * sprite_ref[0][1] - virtual_ref[0][1]) *

                                  (-2 * vop_ref[0][1] + 1) + 2 * w2 * r *

                                  sprite_ref[0][0] - 16 * w2 + (1 << (alpha + rho + 1)));

        s->sprite_offset[1][1] = ((-r * sprite_ref[0][1] + virtual_ref[0][1]) *

                                  (-2 * vop_ref[0][0] + 1) +

                                  (-r * sprite_ref[0][0] + virtual_ref[0][0]) *

                                  (-2 * vop_ref[0][1] + 1) + 2 * w2 * r *

                                  sprite_ref[0][1] - 16 * w2 + (1 << (alpha + rho + 1)));

        s->sprite_delta[0][0] = (-r * sprite_ref[0][0] + virtual_ref[0][0]);

        s->sprite_delta[0][1] = (+r * sprite_ref[0][1] - virtual_ref[0][1]);

        s->sprite_delta[1][0] = (-r * sprite_ref[0][1] + virtual_ref[0][1]);

        s->sprite_delta[1][1] = (-r * sprite_ref[0][0] + virtual_ref[0][0]);



        ctx->sprite_shift[0]  = alpha + rho;

        ctx->sprite_shift[1]  = alpha + rho + 2;

        break;

    case 3:

        min_ab = FFMIN(alpha, beta);

        w3     = w2 >> min_ab;

        h3     = h2 >> min_ab;

        s->sprite_offset[0][0] = (sprite_ref[0][0] << (alpha + beta + rho - min_ab)) +

                                 (-r * sprite_ref[0][0] + virtual_ref[0][0]) *

                                 h3 * (-vop_ref[0][0]) +

                                 (-r * sprite_ref[0][0] + virtual_ref[1][0]) *

                                 w3 * (-vop_ref[0][1]) +

                                 (1 << (alpha + beta + rho - min_ab - 1));

        s->sprite_offset[0][1] = (sprite_ref[0][1] << (alpha + beta + rho - min_ab)) +

                                 (-r * sprite_ref[0][1] + virtual_ref[0][1]) *

                                 h3 * (-vop_ref[0][0]) +

                                 (-r * sprite_ref[0][1] + virtual_ref[1][1]) *

                                 w3 * (-vop_ref[0][1]) +

                                 (1 << (alpha + beta + rho - min_ab - 1));

        s->sprite_offset[1][0] = (-r * sprite_ref[0][0] + virtual_ref[0][0]) *

                                 h3 * (-2 * vop_ref[0][0] + 1) +

                                 (-r * sprite_ref[0][0] + virtual_ref[1][0]) *

                                 w3 * (-2 * vop_ref[0][1] + 1) + 2 * w2 * h3 *

                                 r * sprite_ref[0][0] - 16 * w2 * h3 +

                                 (1 << (alpha + beta + rho - min_ab + 1));

        s->sprite_offset[1][1] = (-r * sprite_ref[0][1] + virtual_ref[0][1]) *

                                 h3 * (-2 * vop_ref[0][0] + 1) +

                                 (-r * sprite_ref[0][1] + virtual_ref[1][1]) *

                                 w3 * (-2 * vop_ref[0][1] + 1) + 2 * w2 * h3 *

                                 r * sprite_ref[0][1] - 16 * w2 * h3 +

                                 (1 << (alpha + beta + rho - min_ab + 1));

        s->sprite_delta[0][0] = (-r * sprite_ref[0][0] + virtual_ref[0][0]) * h3;

        s->sprite_delta[0][1] = (-r * sprite_ref[0][0] + virtual_ref[1][0]) * w3;

        s->sprite_delta[1][0] = (-r * sprite_ref[0][1] + virtual_ref[0][1]) * h3;

        s->sprite_delta[1][1] = (-r * sprite_ref[0][1] + virtual_ref[1][1]) * w3;



        ctx->sprite_shift[0]  = alpha + beta + rho - min_ab;

        ctx->sprite_shift[1]  = alpha + beta + rho - min_ab + 2;

        break;

    }

    /* try to simplify the situation */

    if (s->sprite_delta[0][0] == a << ctx->sprite_shift[0] &&

        s->sprite_delta[0][1] == 0 &&

        s->sprite_delta[1][0] == 0 &&

        s->sprite_delta[1][1] == a << ctx->sprite_shift[0]) {

        s->sprite_offset[0][0] >>= ctx->sprite_shift[0];

        s->sprite_offset[0][1] >>= ctx->sprite_shift[0];

        s->sprite_offset[1][0] >>= ctx->sprite_shift[1];

        s->sprite_offset[1][1] >>= ctx->sprite_shift[1];

        s->sprite_delta[0][0] = a;

        s->sprite_delta[0][1] = 0;

        s->sprite_delta[1][0] = 0;

        s->sprite_delta[1][1] = a;

        ctx->sprite_shift[0] = 0;

        ctx->sprite_shift[1] = 0;

        s->real_sprite_warping_points = 1;

    } else {

        int shift_y = 16 - ctx->sprite_shift[0];

        int shift_c = 16 - ctx->sprite_shift[1];

        for (i = 0; i < 2; i++) {

            s->sprite_offset[0][i] <<= shift_y;

            s->sprite_offset[1][i] <<= shift_c;

            s->sprite_delta[0][i]  <<= shift_y;

            s->sprite_delta[1][i]  <<= shift_y;

            ctx->sprite_shift[i]     = 16;

        }

        s->real_sprite_warping_points = ctx->num_sprite_warping_points;

    }



    return 0;

}

static int decode_frame(AVCodecContext *avctx, void *data, int *got_frame,

                        AVPacket *avpkt)

{

    const uint8_t *buf = avpkt->data;

    int buf_size = avpkt->size;

    UtvideoContext *c = avctx->priv_data;

    int i, j;

    const uint8_t *plane_start[5];

    int plane_size, max_slice_size = 0, slice_start, slice_end, slice_size;

    int ret;

    GetByteContext gb;

    ThreadFrame frame = { .f = data };



    if ((ret = ff_thread_get_buffer(avctx, &frame, 0)) < 0)

        return ret;



    /* parse plane structure to get frame flags and validate slice offsets */

    bytestream2_init(&gb, buf, buf_size);

    for (i = 0; i < c->planes; i++) {

        plane_start[i] = gb.buffer;

        if (bytestream2_get_bytes_left(&gb) < 256 + 4 * c->slices) {

            av_log(avctx, AV_LOG_ERROR, "Insufficient data for a plane\n");

            return AVERROR_INVALIDDATA;

        }

        bytestream2_skipu(&gb, 256);

        slice_start = 0;

        slice_end   = 0;

        for (j = 0; j < c->slices; j++) {

            slice_end   = bytestream2_get_le32u(&gb);

            slice_size  = slice_end - slice_start;

            if (slice_end < 0 || slice_size < 0 ||

                bytestream2_get_bytes_left(&gb) < slice_end) {

                av_log(avctx, AV_LOG_ERROR, "Incorrect slice size\n");

                return AVERROR_INVALIDDATA;

            }

            slice_start = slice_end;

            max_slice_size = FFMAX(max_slice_size, slice_size);

        }

        plane_size = slice_end;

        bytestream2_skipu(&gb, plane_size);

    }

    plane_start[c->planes] = gb.buffer;

    if (bytestream2_get_bytes_left(&gb) < c->frame_info_size) {

        av_log(avctx, AV_LOG_ERROR, "Not enough data for frame information\n");

        return AVERROR_INVALIDDATA;

    }

    c->frame_info = bytestream2_get_le32u(&gb);

    av_log(avctx, AV_LOG_DEBUG, "frame information flags %"PRIX32"\n",

           c->frame_info);



    c->frame_pred = (c->frame_info >> 8) & 3;



    if (c->frame_pred == PRED_GRADIENT) {

        avpriv_request_sample(avctx, "Frame with gradient prediction");

        return AVERROR_PATCHWELCOME;

    }



    av_fast_malloc(&c->slice_bits, &c->slice_bits_size,

                   max_slice_size + AV_INPUT_BUFFER_PADDING_SIZE);



    if (!c->slice_bits) {

        av_log(avctx, AV_LOG_ERROR, "Cannot allocate temporary buffer\n");

        return AVERROR(ENOMEM);

    }



    switch (c->avctx->pix_fmt) {

    case AV_PIX_FMT_RGB24:

    case AV_PIX_FMT_RGBA:

        for (i = 0; i < c->planes; i++) {

            ret = decode_plane(c, i, frame.f->data[0] + ff_ut_rgb_order[i],

                               c->planes, frame.f->linesize[0], avctx->width,

                               avctx->height, plane_start[i],

                               c->frame_pred == PRED_LEFT);

            if (ret)

                return ret;

            if (c->frame_pred == PRED_MEDIAN) {

                if (!c->interlaced) {

                    restore_median(frame.f->data[0] + ff_ut_rgb_order[i],

                                   c->planes, frame.f->linesize[0], avctx->width,

                                   avctx->height, c->slices, 0);

                } else {

                    restore_median_il(frame.f->data[0] + ff_ut_rgb_order[i],

                                      c->planes, frame.f->linesize[0],

                                      avctx->width, avctx->height, c->slices,

                                      0);

                }

            }

        }

        restore_rgb_planes(frame.f->data[0], c->planes, frame.f->linesize[0],

                           avctx->width, avctx->height);

        break;

    case AV_PIX_FMT_YUV420P:

        for (i = 0; i < 3; i++) {

            ret = decode_plane(c, i, frame.f->data[i], 1, frame.f->linesize[i],

                               avctx->width >> !!i, avctx->height >> !!i,

                               plane_start[i], c->frame_pred == PRED_LEFT);

            if (ret)

                return ret;

            if (c->frame_pred == PRED_MEDIAN) {

                if (!c->interlaced) {

                    restore_median(frame.f->data[i], 1, frame.f->linesize[i],

                                   avctx->width >> !!i, avctx->height >> !!i,

                                   c->slices, !i);

                } else {

                    restore_median_il(frame.f->data[i], 1, frame.f->linesize[i],

                                      avctx->width  >> !!i,

                                      avctx->height >> !!i,

                                      c->slices, !i);

                }

            }

        }

        break;

    case AV_PIX_FMT_YUV422P:

        for (i = 0; i < 3; i++) {

            ret = decode_plane(c, i, frame.f->data[i], 1, frame.f->linesize[i],

                               avctx->width >> !!i, avctx->height,

                               plane_start[i], c->frame_pred == PRED_LEFT);

            if (ret)

                return ret;

            if (c->frame_pred == PRED_MEDIAN) {

                if (!c->interlaced) {

                    restore_median(frame.f->data[i], 1, frame.f->linesize[i],

                                   avctx->width >> !!i, avctx->height,

                                   c->slices, 0);

                } else {

                    restore_median_il(frame.f->data[i], 1, frame.f->linesize[i],

                                      avctx->width >> !!i, avctx->height,

                                      c->slices, 0);

                }

            }

        }

        break;

    }



    frame.f->key_frame = 1;

    frame.f->pict_type = AV_PICTURE_TYPE_I;

    frame.f->interlaced_frame = !!c->interlaced;



    *got_frame = 1;



    /* always report that the buffer was completely consumed */

    return buf_size;

}

