static int vp8_packet(AVFormatContext *s, int idx)

{

    struct ogg *ogg = s->priv_data;

    struct ogg_stream *os = ogg->streams + idx;

    uint8_t *p = os->buf + os->pstart;



    if ((!os->lastpts || os->lastpts == AV_NOPTS_VALUE) &&

        !(os->flags & OGG_FLAG_EOS)) {

        int seg;

        int duration;

        uint8_t *last_pkt = p;

        uint8_t *next_pkt;



        seg = os->segp;

        duration = (last_pkt[0] >> 4) & 1;

        next_pkt = last_pkt += os->psize;

        for (; seg < os->nsegs; seg++) {

            if (os->segments[seg] < 255) {

                duration += (last_pkt[0] >> 4) & 1;

                last_pkt  = next_pkt + os->segments[seg];

            }

            next_pkt += os->segments[seg];

        }

        os->lastpts =

        os->lastdts = vp8_gptopts(s, idx, os->granule, NULL) - duration;

        if(s->streams[idx]->start_time == AV_NOPTS_VALUE) {

            s->streams[idx]->start_time = os->lastpts;

            if (s->streams[idx]->duration)

                s->streams[idx]->duration -= s->streams[idx]->start_time;

        }

    }



    if (os->psize > 0)

        os->pduration = (p[0] >> 4) & 1;



    return 0;

}

static void intra_predict_vert_dc_8x8_msa(uint8_t *src, int32_t stride)

{

    uint8_t lp_cnt;

    uint32_t out0 = 0, out1 = 0;

    v16u8 src_top;

    v8u16 add;

    v4u32 sum;

    v4i32 res0, res1;



    src_top = LD_UB(src - stride);

    add = __msa_hadd_u_h(src_top, src_top);

    sum = __msa_hadd_u_w(add, add);

    sum = (v4u32) __msa_srari_w((v4i32) sum, 2);

    res0 = (v4i32) __msa_splati_b((v16i8) sum, 0);

    res1 = (v4i32) __msa_splati_b((v16i8) sum, 4);

    out0 = __msa_copy_u_w(res0, 0);

    out1 = __msa_copy_u_w(res1, 0);



    for (lp_cnt = 8; lp_cnt--;) {

        SW(out0, src);

        SW(out1, src + 4);

        src += stride;

    }

}

static int get_cv_transfer_function(AVCodecContext *avctx,

                                    CFStringRef *transfer_fnc,

                                    CFNumberRef *gamma_level)

{

    enum AVColorTransferCharacteristic trc = avctx->color_trc;

    Float32 gamma;

    *gamma_level = NULL;



    switch (trc) {

        case AVCOL_TRC_UNSPECIFIED:

            *transfer_fnc = NULL;

            break;



        case AVCOL_TRC_BT709:

            *transfer_fnc = kCVImageBufferTransferFunction_ITU_R_709_2;

            break;



        case AVCOL_TRC_SMPTE240M:

            *transfer_fnc = kCVImageBufferTransferFunction_SMPTE_240M_1995;

            break;



        case AVCOL_TRC_GAMMA22:

            gamma = 2.2;

            *transfer_fnc = kCVImageBufferTransferFunction_UseGamma;

            *gamma_level = CFNumberCreate(NULL, kCFNumberFloat32Type, &gamma);

            break;



        case AVCOL_TRC_GAMMA28:

            gamma = 2.8;

            *transfer_fnc = kCVImageBufferTransferFunction_UseGamma;

            *gamma_level = CFNumberCreate(NULL, kCFNumberFloat32Type, &gamma);

            break;



        case AVCOL_TRC_BT2020_10:

        case AVCOL_TRC_BT2020_12:

            *transfer_fnc = kCVImageBufferTransferFunction_ITU_R_2020;

            break;



        default:

            av_log(avctx, AV_LOG_ERROR, "Transfer function %s is not supported.\n", av_color_transfer_name(trc));

            return -1;

    }



    return 0;

}

void rgb16tobgr24(const uint8_t *src, uint8_t *dst, unsigned int src_size)

{

	const uint16_t *end;

	uint8_t *d = (uint8_t *)dst;

	const uint16_t *s = (const uint16_t *)src;

	end = s + src_size/2;

	while(s < end)

	{

		register uint16_t bgr;

		bgr = *s++;

		*d++ = (bgr&0xF800)>>8;

		*d++ = (bgr&0x7E0)>>3;

		*d++ = (bgr&0x1F)<<3;

	}

}

static int dyn_buf_write(void *opaque, uint8_t *buf, int buf_size)

{

    DynBuffer *d = opaque;

    int new_size, new_allocated_size;



    /* reallocate buffer if needed */

    new_size = d->pos + buf_size;

    new_allocated_size = d->allocated_size;

    if(new_size < d->pos || new_size > INT_MAX/2)

        return -1;

    while (new_size > new_allocated_size) {

        if (!new_allocated_size)

            new_allocated_size = new_size;

        else

            new_allocated_size += new_allocated_size / 2 + 1;

    }



    if (new_allocated_size > d->allocated_size) {

        d->buffer = av_realloc(d->buffer, new_allocated_size);

        if(d->buffer == NULL)

             return -1234;

        d->allocated_size = new_allocated_size;

    }

    memcpy(d->buffer + d->pos, buf, buf_size);

    d->pos = new_size;

    if (d->pos > d->size)

        d->size = d->pos;

    return buf_size;

}

static inline void RENAME(rgb32to24)(const uint8_t *src,uint8_t *dst,unsigned src_size)

{

  uint8_t *dest = dst;

  const uint8_t *s = src;

  const uint8_t *end;

#ifdef HAVE_MMX

  const uint8_t *mm_end;

#endif

  end = s + src_size;

#ifdef HAVE_MMX

  __asm __volatile(PREFETCH"	%0"::"m"(*s):"memory");

  mm_end = end - 31;

  while(s < mm_end)

  {

    __asm __volatile(

	PREFETCH"	32%1\n\t"

	"movq	%1, %%mm0\n\t"

	"movq	8%1, %%mm1\n\t"

	"movq	16%1, %%mm4\n\t"

	"movq	24%1, %%mm5\n\t"

	"movq	%%mm0, %%mm2\n\t"

	"movq	%%mm1, %%mm3\n\t"

	"movq	%%mm4, %%mm6\n\t"

	"movq	%%mm5, %%mm7\n\t"

	"psrlq	$8, %%mm2\n\t"

	"psrlq	$8, %%mm3\n\t"

	"psrlq	$8, %%mm6\n\t"

	"psrlq	$8, %%mm7\n\t"

	"pand	%2, %%mm0\n\t"

	"pand	%2, %%mm1\n\t"

	"pand	%2, %%mm4\n\t"

	"pand	%2, %%mm5\n\t"

	"pand	%3, %%mm2\n\t"

	"pand	%3, %%mm3\n\t"

	"pand	%3, %%mm6\n\t"

	"pand	%3, %%mm7\n\t"

	"por	%%mm2, %%mm0\n\t"

	"por	%%mm3, %%mm1\n\t"

	"por	%%mm6, %%mm4\n\t"

	"por	%%mm7, %%mm5\n\t"



	"movq	%%mm1, %%mm2\n\t"

	"movq	%%mm4, %%mm3\n\t"

	"psllq	$48, %%mm2\n\t"

	"psllq	$32, %%mm3\n\t"

	"pand	%4, %%mm2\n\t"

	"pand	%5, %%mm3\n\t"

	"por	%%mm2, %%mm0\n\t"

	"psrlq	$16, %%mm1\n\t"

	"psrlq	$32, %%mm4\n\t"

	"psllq	$16, %%mm5\n\t"

	"por	%%mm3, %%mm1\n\t"

	"pand	%6, %%mm5\n\t"

	"por	%%mm5, %%mm4\n\t"



	MOVNTQ"	%%mm0, %0\n\t"

	MOVNTQ"	%%mm1, 8%0\n\t"

	MOVNTQ"	%%mm4, 16%0"

	:"=m"(*dest)

	:"m"(*s),"m"(mask24l),

	 "m"(mask24h),"m"(mask24hh),"m"(mask24hhh),"m"(mask24hhhh)

	:"memory");

    dest += 24;

    s += 32;

  }

  __asm __volatile(SFENCE:::"memory");

  __asm __volatile(EMMS:::"memory");

#endif

  while(s < end)

  {

#ifdef WORDS_BIGENDIAN

    s++;

    *dest++ = *s++;

    *dest++ = *s++;

    *dest++ = *s++;

#else

    *dest++ = *s++;

    *dest++ = *s++;

    *dest++ = *s++;

    s++;

#endif

  }

}

static void uncouple_channels(AC3DecodeContext * ctx)

{

    ac3_audio_block *ab = &ctx->audio_block;

    int ch, sbnd, bin;

    int index;

    int16_t mantissa;



    /* uncouple channels */

    for (ch = 0; ch < ctx->bsi.nfchans; ch++)

        if (ab->chincpl & (1 << ch))

            for (sbnd = ab->cplbegf; sbnd < 3 + ab->cplendf; sbnd++)

                for (bin = 0; bin < 12; bin++) {

                    index = sbnd * 12 + bin + 37;

                    ab->transform_coeffs[ch + 1][index] = ab->cplcoeffs[index] * ab->cplco[ch][sbnd] * ab->chcoeffs[ch];

                    /* generate dither if required */

                    if (!ab->bap[ch][index] && (ab->chincpl & (1 << ch)) && (ab->dithflag & (1 << ch))) {

                        mantissa = dither_int16(&ctx->state);

                        ab->transform_coeffs[ch + 1][index] = to_float(ab->dexps[ch][index], mantissa) * ab->chcoeffs[ch];

                    }

                }

}

static int convert_zp2tf(AVFilterContext *ctx, int channels)

{

    AudioIIRContext *s = ctx->priv;

    int ch, i, j, ret;



    for (ch = 0; ch < channels; ch++) {

        IIRChannel *iir = &s->iir[ch];

        double *topc, *botc;



        topc = av_calloc((iir->nb_ab[0] + 1) * 2, sizeof(*topc));

        botc = av_calloc((iir->nb_ab[1] + 1) * 2, sizeof(*botc));

        if (!topc || !botc)

            return AVERROR(ENOMEM);



        ret = expand(ctx, iir->ab[0], iir->nb_ab[0], botc);

        if (ret < 0) {

            av_free(topc);

            av_free(botc);

            return ret;

        }



        ret = expand(ctx, iir->ab[1], iir->nb_ab[1], topc);

        if (ret < 0) {

            av_free(topc);

            av_free(botc);

            return ret;

        }



        for (j = 0, i = iir->nb_ab[1]; i >= 0; j++, i--) {

            iir->ab[1][j] = topc[2 * i];

        }

        iir->nb_ab[1]++;



        for (j = 0, i = iir->nb_ab[0]; i >= 0; j++, i--) {

            iir->ab[0][j] = botc[2 * i];

        }

        iir->nb_ab[0]++;



        av_free(topc);

        av_free(botc);

    }



    return 0;

}

static int decode_hybrid(const uint8_t *sptr, uint8_t *dptr, int dx, int dy,

                         int h, int w, int stride, const uint32_t *pal)

{

    int x, y;

    const uint8_t *orig_src = sptr;



    for (y = dx + h; y > dx; y--) {

        uint8_t *dst = dptr + (y * stride) + dy * 3;

        for (x = 0; x < w; x++) {

            if (*sptr & 0x80) {

                /* 15-bit color */

                unsigned c = AV_RB16(sptr) & ~0x8000;

                unsigned b =  c        & 0x1F;

                unsigned g = (c >>  5) & 0x1F;

                unsigned r =  c >> 10;

                /* 000aaabb -> aaabbaaa  */

                *dst++ = (b << 3) | (b >> 2);

                *dst++ = (g << 3) | (g >> 2);

                *dst++ = (r << 3) | (r >> 2);

                sptr += 2;

            } else {

                /* palette index */

                uint32_t c = pal[*sptr++];

                bytestream_put_le24(&dst, c);

            }

        }

    }

    return sptr - orig_src;

}

static void put_frame(

                    AVFormatContext *s,

                    ASFStream       *stream,

		    int             timestamp,

                    const uint8_t   *buf,

		    int             m_obj_size

		)

{

    ASFContext *asf = s->priv_data;

    int m_obj_offset, payload_len, frag_len1;



    m_obj_offset = 0;

    while (m_obj_offset < m_obj_size) {

        payload_len = m_obj_size - m_obj_offset;

        if (asf->packet_timestamp_start == -1) {

            asf->multi_payloads_present = (payload_len < MULTI_PAYLOAD_CONSTANT);



            if (asf->multi_payloads_present){

                asf->packet_size_left = PACKET_SIZE; //For debug

                asf->packet_size_left = PACKET_SIZE - PACKET_HEADER_MIN_SIZE - 1;

                frag_len1 = MULTI_PAYLOAD_CONSTANT - 1;

            }

            else {

                asf->packet_size_left = PACKET_SIZE - PACKET_HEADER_MIN_SIZE;

                frag_len1 = SINGLE_PAYLOAD_DATA_LENGTH;

            }

            if (asf->prev_packet_sent_time > timestamp)

                asf->packet_timestamp_start = asf->prev_packet_sent_time;

            else

                asf->packet_timestamp_start = timestamp;

        }

        else {

            // multi payloads

            frag_len1 = asf->packet_size_left - PAYLOAD_HEADER_SIZE_MULTIPLE_PAYLOADS;



            if (asf->prev_packet_sent_time > timestamp)

                asf->packet_timestamp_start = asf->prev_packet_sent_time;

            else if (asf->packet_timestamp_start >= timestamp)

                asf->packet_timestamp_start = timestamp;

        }

        if (frag_len1 > 0) {

            if (payload_len > frag_len1)

                payload_len = frag_len1;

            else if (payload_len == (frag_len1 - 1))

                payload_len = frag_len1 - 2;  //additional byte need to put padding length



            put_payload_header(s, stream, timestamp+preroll_time, m_obj_size, m_obj_offset, payload_len);

            put_buffer(&asf->pb, buf, payload_len);



            if (asf->multi_payloads_present)

                asf->packet_size_left -= (payload_len + PAYLOAD_HEADER_SIZE_MULTIPLE_PAYLOADS);

            else

                asf->packet_size_left -= (payload_len + PAYLOAD_HEADER_SIZE_SINGLE_PAYLOAD);

            asf->packet_timestamp_end = timestamp;



            asf->packet_nb_payloads++;

        } else {

            payload_len = 0;

        }

        m_obj_offset += payload_len;

        buf += payload_len;



        if (!asf->multi_payloads_present)

            flush_packet(s);

        else if (asf->packet_size_left <= (PAYLOAD_HEADER_SIZE_MULTIPLE_PAYLOADS + 1))

            flush_packet(s);

    }

    stream->seq++;

}

static int ftp_flush_control_input(FTPContext *s)

