static int mpeg_field_start(MpegEncContext *s){

    AVCodecContext *avctx= s->avctx;

    Mpeg1Context *s1 = (Mpeg1Context*)s;



    /* start frame decoding */

    if(s->first_field || s->picture_structure==PICT_FRAME){

        if(MPV_frame_start(s, avctx) < 0)

            return -1;



        ff_er_frame_start(s);



        /* first check if we must repeat the frame */

        s->current_picture_ptr->repeat_pict = 0;

        if (s->repeat_first_field) {

            if (s->progressive_sequence) {

                if (s->top_field_first)

                    s->current_picture_ptr->repeat_pict = 4;

                else

                    s->current_picture_ptr->repeat_pict = 2;

            } else if (s->progressive_frame) {

                s->current_picture_ptr->repeat_pict = 1;

            }

        }



        *s->current_picture_ptr->pan_scan= s1->pan_scan;

    }else{ //second field

            int i;



            if(!s->current_picture_ptr){

                av_log(s->avctx, AV_LOG_ERROR, "first field missing\n");

                return -1;

            }



            for(i=0; i<4; i++){

                s->current_picture.data[i] = s->current_picture_ptr->data[i];

                if(s->picture_structure == PICT_BOTTOM_FIELD){

                    s->current_picture.data[i] += s->current_picture_ptr->linesize[i];

                }

            }

    }

#if CONFIG_MPEG_XVMC_DECODER

// MPV_frame_start will call this function too,

// but we need to call it on every field

    if(s->avctx->xvmc_acceleration)

         ff_xvmc_field_start(s,avctx);

#endif



    return 0;

}

static inline void RENAME(bgr24ToUV)(uint8_t *dstU, uint8_t *dstV, const uint8_t *src1, const uint8_t *src2, int width, uint32_t *unused)

{

#if COMPILE_TEMPLATE_MMX

    RENAME(bgr24ToUV_mmx)(dstU, dstV, src1, width, PIX_FMT_BGR24);

#else

    int i;

    for (i=0; i<width; i++) {

        int b= src1[3*i + 0];

        int g= src1[3*i + 1];

        int r= src1[3*i + 2];



        dstU[i]= (RU*r + GU*g + BU*b + (257<<(RGB2YUV_SHIFT-1)))>>RGB2YUV_SHIFT;

        dstV[i]= (RV*r + GV*g + BV*b + (257<<(RGB2YUV_SHIFT-1)))>>RGB2YUV_SHIFT;

    }

#endif /* COMPILE_TEMPLATE_MMX */

    assert(src1 == src2);

}

static void hScale16_c(SwsContext *c, int16_t *_dst, int dstW, const uint8_t *_src,

                       const int16_t *filter,

                       const int16_t *filterPos, int filterSize)

{

    int i;

    int32_t *dst = (int32_t *) _dst;

    const uint16_t *src = (const uint16_t *) _src;

    int bits = av_pix_fmt_descriptors[c->srcFormat].comp[0].depth_minus1;

    int sh = (bits <= 7) ? 11 : (bits - 4);



    for (i = 0; i < dstW; i++) {

        int j;

        int srcPos = filterPos[i];

        unsigned int val = 0;



        for (j = 0; j < filterSize; j++) {

            val += src[srcPos + j] * filter[filterSize * i + j];

        }

        // filter=14 bit, input=16 bit, output=30 bit, >> 11 makes 19 bit

        dst[i] = FFMIN(val >> sh, (1 << 19) - 1);

    }

}

