static int opt_map(OptionsContext *o, const char *opt, const char *arg)

{

    StreamMap *m = NULL;

    int i, negative = 0, file_idx;

    int sync_file_idx = -1, sync_stream_idx;

    char *p, *sync;

    char *map;



    if (*arg == '-') {

        negative = 1;

        arg++;

    }

    map = av_strdup(arg);



    /* parse sync stream first, just pick first matching stream */

    if (sync = strchr(map, ',')) {

        *sync = 0;

        sync_file_idx = strtol(sync + 1, &sync, 0);

        if (sync_file_idx >= nb_input_files || sync_file_idx < 0) {

            av_log(NULL, AV_LOG_FATAL, "Invalid sync file index: %d.\n", sync_file_idx);

            exit_program(1);

        }

        if (*sync)

            sync++;

        for (i = 0; i < input_files[sync_file_idx].nb_streams; i++)

            if (check_stream_specifier(input_files[sync_file_idx].ctx,

                                       input_files[sync_file_idx].ctx->streams[i], sync) == 1) {

                sync_stream_idx = i;

                break;

            }

        if (i == input_files[sync_file_idx].nb_streams) {

            av_log(NULL, AV_LOG_FATAL, "Sync stream specification in map %s does not "

                                       "match any streams.\n", arg);

            exit_program(1);

        }

    }





    file_idx = strtol(map, &p, 0);

    if (file_idx >= nb_input_files || file_idx < 0) {

        av_log(NULL, AV_LOG_FATAL, "Invalid input file index: %d.\n", file_idx);

        exit_program(1);

    }

    if (negative)

        /* disable some already defined maps */

        for (i = 0; i < o->nb_stream_maps; i++) {

            m = &o->stream_maps[i];

            if (check_stream_specifier(input_files[m->file_index].ctx,

                                       input_files[m->file_index].ctx->streams[m->stream_index],

                                       *p == ':' ? p + 1 : p) > 0)

                m->disabled = 1;

        }

    else

        for (i = 0; i < input_files[file_idx].nb_streams; i++) {

            if (check_stream_specifier(input_files[file_idx].ctx, input_files[file_idx].ctx->streams[i],

                        *p == ':' ? p + 1 : p) <= 0)

                continue;

            o->stream_maps = grow_array(o->stream_maps, sizeof(*o->stream_maps),

                                        &o->nb_stream_maps, o->nb_stream_maps + 1);

            m = &o->stream_maps[o->nb_stream_maps - 1];



            m->file_index   = file_idx;

            m->stream_index = i;



            if (sync_file_idx >= 0) {

                m->sync_file_index   = sync_file_idx;

                m->sync_stream_index = sync_stream_idx;

            } else {

                m->sync_file_index   = file_idx;

                m->sync_stream_index = i;

            }

        }



    if (!m) {

        av_log(NULL, AV_LOG_FATAL, "Stream map '%s' matches no streams.\n", arg);

        exit_program(1);

    }



    av_freep(&map);

    return 0;

}

static void id3v2_parse(AVIOContext *pb, AVDictionary **metadata,

                        AVFormatContext *s, int len, uint8_t version,

                        uint8_t flags, ID3v2ExtraMeta **extra_meta)

{

    int isv34, unsync;

    unsigned tlen;

    char tag[5];

    int64_t next, end = avio_tell(pb) + len;

    int taghdrlen;

    const char *reason = NULL;

    AVIOContext pb_local;

    AVIOContext *pbx;

    unsigned char *buffer = NULL;

    int buffer_size       = 0;

    const ID3v2EMFunc *extra_func = NULL;

    unsigned char *uncompressed_buffer = NULL;

    av_unused int uncompressed_buffer_size = 0;



    av_log(s, AV_LOG_DEBUG, "id3v2 ver:%d flags:%02X len:%d\n", version, flags, len);



    switch (version) {

    case 2:

        if (flags & 0x40) {

            reason = "compression";

            goto error;

        }

        isv34     = 0;

        taghdrlen = 6;

        break;



    case 3:

    case 4:

        isv34     = 1;

        taghdrlen = 10;

        break;



    default:

        reason = "version";

        goto error;

    }



    unsync = flags & 0x80;



    if (isv34 && flags & 0x40) { /* Extended header present, just skip over it */

        int extlen = get_size(pb, 4);

        if (version == 4)

            /* In v2.4 the length includes the length field we just read. */

            extlen -= 4;



        if (extlen < 0) {

            reason = "invalid extended header length";

            goto error;

        }

        avio_skip(pb, extlen);

        len -= extlen + 4;

        if (len < 0) {

            reason = "extended header too long.";

            goto error;

        }

    }



    while (len >= taghdrlen) {

        unsigned int tflags = 0;

        int tunsync         = 0;

        int tcomp           = 0;

        int tencr           = 0;

        unsigned long av_unused dlen;



        if (isv34) {

            if (avio_read(pb, tag, 4) < 4)

                break;

            tag[4] = 0;

            if (version == 3) {

                tlen = avio_rb32(pb);

            } else

                tlen = get_size(pb, 4);

            tflags  = avio_rb16(pb);

            tunsync = tflags & ID3v2_FLAG_UNSYNCH;

        } else {

            if (avio_read(pb, tag, 3) < 3)

                break;

            tag[3] = 0;

            tlen   = avio_rb24(pb);

        }

        if (tlen > (1<<28))

            break;

        len -= taghdrlen + tlen;



        if (len < 0)

            break;



        next = avio_tell(pb) + tlen;



        if (!tlen) {

            if (tag[0])

                av_log(s, AV_LOG_DEBUG, "Invalid empty frame %s, skipping.\n",

                       tag);

            continue;

        }



        if (tflags & ID3v2_FLAG_DATALEN) {

            if (tlen < 4)

                break;

            dlen = avio_rb32(pb);

            tlen -= 4;

        } else

            dlen = tlen;



        tcomp = tflags & ID3v2_FLAG_COMPRESSION;

        tencr = tflags & ID3v2_FLAG_ENCRYPTION;



        /* skip encrypted tags and, if no zlib, compressed tags */

        if (tencr || (!CONFIG_ZLIB && tcomp)) {

            const char *type;

            if (!tcomp)

                type = "encrypted";

            else if (!tencr)

                type = "compressed";

            else

                type = "encrypted and compressed";



            av_log(s, AV_LOG_WARNING, "Skipping %s ID3v2 frame %s.\n", type, tag);

            avio_skip(pb, tlen);

        /* check for text tag or supported special meta tag */

        } else if (tag[0] == 'T' ||

                   (extra_meta &&

                    (extra_func = get_extra_meta_func(tag, isv34)))) {

            pbx = pb;



            if (unsync || tunsync || tcomp) {

                av_fast_malloc(&buffer, &buffer_size, tlen);

                if (!buffer) {

                    av_log(s, AV_LOG_ERROR, "Failed to alloc %d bytes\n", tlen);

                    goto seek;

                }

            }

            if (unsync || tunsync) {

                int64_t end = avio_tell(pb) + tlen;

                uint8_t *b;



                b = buffer;

                while (avio_tell(pb) < end && b - buffer < tlen && !pb->eof_reached) {

                    *b++ = avio_r8(pb);

                    if (*(b - 1) == 0xff && avio_tell(pb) < end - 1 &&

                        b - buffer < tlen &&

                        !pb->eof_reached ) {

                        uint8_t val = avio_r8(pb);

                        *b++ = val ? val : avio_r8(pb);

                    }

                }

                ffio_init_context(&pb_local, buffer, b - buffer, 0, NULL, NULL, NULL,

                                  NULL);

                tlen = b - buffer;

                pbx  = &pb_local; // read from sync buffer

            }



#if CONFIG_ZLIB

                if (tcomp) {

                    int err;



                    av_log(s, AV_LOG_DEBUG, "Compresssed frame %s tlen=%d dlen=%ld\n", tag, tlen, dlen);



                    av_fast_malloc(&uncompressed_buffer, &uncompressed_buffer_size, dlen);

                    if (!uncompressed_buffer) {

                        av_log(s, AV_LOG_ERROR, "Failed to alloc %ld bytes\n", dlen);

                        goto seek;

                    }



                    if (!(unsync || tunsync)) {

                        err = avio_read(pb, buffer, tlen);

                        if (err < 0) {

                            av_log(s, AV_LOG_ERROR, "Failed to read compressed tag\n");

                            goto seek;

                        }

                        tlen = err;

                    }



                    err = uncompress(uncompressed_buffer, &dlen, buffer, tlen);

                    if (err != Z_OK) {

                        av_log(s, AV_LOG_ERROR, "Failed to uncompress tag: %d\n", err);

                        goto seek;

                    }

                    ffio_init_context(&pb_local, uncompressed_buffer, dlen, 0, NULL, NULL, NULL, NULL);

                    tlen = dlen;

                    pbx = &pb_local; // read from sync buffer

                }

#endif

            if (tag[0] == 'T')

                /* parse text tag */

                read_ttag(s, pbx, tlen, metadata, tag);

            else

                /* parse special meta tag */

                extra_func->read(s, pbx, tlen, tag, extra_meta, isv34);

        } else if (!tag[0]) {

            if (tag[1])

                av_log(s, AV_LOG_WARNING, "invalid frame id, assuming padding\n");

            avio_skip(pb, tlen);

            break;

        }

        /* Skip to end of tag */

seek:

        avio_seek(pb, next, SEEK_SET);

    }



    /* Footer preset, always 10 bytes, skip over it */

    if (version == 4 && flags & 0x10)

        end += 10;



error:

    if (reason)

        av_log(s, AV_LOG_INFO, "ID3v2.%d tag skipped, cannot handle %s\n",

               version, reason);

    avio_seek(pb, end, SEEK_SET);

    av_free(buffer);

    av_free(uncompressed_buffer);

    return;

}

yuv2mono_X_c_template(SwsContext *c, const int16_t *lumFilter,

                      const int16_t **lumSrc, int lumFilterSize,

                      const int16_t *chrFilter, const int16_t **chrUSrc,

                      const int16_t **chrVSrc, int chrFilterSize,

                      const int16_t **alpSrc, uint8_t *dest, int dstW,

                      int y, enum PixelFormat target)

{

    const uint8_t * const d128=dither_8x8_220[y&7];

    uint8_t *g = c->table_gU[128] + c->table_gV[128];

    int i;

    int acc = 0;



    for (i = 0; i < dstW - 1; i += 2) {

        int j;

        int Y1 = 1 << 18;

        int Y2 = 1 << 18;



        for (j = 0; j < lumFilterSize; j++) {

            Y1 += lumSrc[j][i]   * lumFilter[j];

            Y2 += lumSrc[j][i+1] * lumFilter[j];

        }

        Y1 >>= 19;

        Y2 >>= 19;

        if ((Y1 | Y2) & 0x100) {

            Y1 = av_clip_uint8(Y1);

            Y2 = av_clip_uint8(Y2);

        }

        acc += acc + g[Y1 + d128[(i + 0) & 7]];

        acc += acc + g[Y2 + d128[(i + 1) & 7]];

        if ((i & 7) == 6) {

            output_pixel(*dest++, acc);

        }

    }

}

static void avi_read_nikon(AVFormatContext *s, uint64_t end)

{

    while (avio_tell(s->pb) < end) {

        uint32_t tag  = avio_rl32(s->pb);

        uint32_t size = avio_rl32(s->pb);

        switch (tag) {

        case MKTAG('n', 'c', 't', 'g'):  /* Nikon Tags */

        {

            uint64_t tag_end = avio_tell(s->pb) + size;

            while (avio_tell(s->pb) < tag_end) {

                uint16_t tag     = avio_rl16(s->pb);

                uint16_t size    = avio_rl16(s->pb);

                const char *name = NULL;

                char buffer[64]  = { 0 };

                if (avio_tell(s->pb) + size > tag_end)

                    size = tag_end - avio_tell(s->pb);

                size -= avio_read(s->pb, buffer,

                                  FFMIN(size, sizeof(buffer) - 1));

                switch (tag) {

                case 0x03:

                    name = "maker";

                    break;

                case 0x04:

                    name = "model";

                    break;

                case 0x13:

                    name = "creation_time";

                    if (buffer[4] == ':' && buffer[7] == ':')

                        buffer[4] = buffer[7] = '-';

                    break;

                }

                if (name)

                    av_dict_set(&s->metadata, name, buffer, 0);

                avio_skip(s->pb, size);

            }

            break;

        }

        default:

            avio_skip(s->pb, size);

            break;

        }

    }

}

static int decode_slice(MpegEncContext *s)

{

    const int part_mask = s->partitioned_frame

                          ? (ER_AC_END | ER_AC_ERROR) : 0x7F;

    const int mb_size = 16;

    int ret;



    s->last_resync_gb   = s->gb;

    s->first_slice_line = 1;

    s->resync_mb_x      = s->mb_x;

    s->resync_mb_y      = s->mb_y;



    ff_set_qscale(s, s->qscale);



    if (s->avctx->hwaccel) {

        const uint8_t *start = s->gb.buffer + get_bits_count(&s->gb) / 8;

        const uint8_t *end   = ff_h263_find_resync_marker(start + 1,

                                                          s->gb.buffer_end);

        skip_bits_long(&s->gb, 8 * (end - start));

        return s->avctx->hwaccel->decode_slice(s->avctx, start, end - start);

    }



    if (s->partitioned_frame) {

        const int qscale = s->qscale;



        if (CONFIG_MPEG4_DECODER && s->codec_id == AV_CODEC_ID_MPEG4)

            if ((ret = ff_mpeg4_decode_partitions(s->avctx->priv_data)) < 0)

                return ret;



        /* restore variables which were modified */

        s->first_slice_line = 1;

        s->mb_x             = s->resync_mb_x;

        s->mb_y             = s->resync_mb_y;

        ff_set_qscale(s, qscale);

    }



    for (; s->mb_y < s->mb_height; s->mb_y++) {

        /* per-row end of slice checks */

        if (s->msmpeg4_version) {

            if (s->resync_mb_y + s->slice_height == s->mb_y) {

                ff_er_add_slice(&s->er, s->resync_mb_x, s->resync_mb_y,

                                s->mb_x - 1, s->mb_y, ER_MB_END);



                return 0;

            }

        }



        if (s->msmpeg4_version == 1) {

            s->last_dc[0] =

            s->last_dc[1] =

            s->last_dc[2] = 128;

        }



        ff_init_block_index(s);

        for (; s->mb_x < s->mb_width; s->mb_x++) {

            int ret;



            ff_update_block_index(s);



            if (s->resync_mb_x == s->mb_x && s->resync_mb_y + 1 == s->mb_y)

                s->first_slice_line = 0;



            /* DCT & quantize */



            s->mv_dir  = MV_DIR_FORWARD;

            s->mv_type = MV_TYPE_16X16;

            ff_dlog(s, "%d %d %06X\n",

                    ret, get_bits_count(&s->gb), show_bits(&s->gb, 24));

            ret = s->decode_mb(s, s->block);



            if (s->pict_type != AV_PICTURE_TYPE_B)

                ff_h263_update_motion_val(s);



            if (ret < 0) {

                const int xy = s->mb_x + s->mb_y * s->mb_stride;

                if (ret == SLICE_END) {

                    ff_mpv_decode_mb(s, s->block);

                    if (s->loop_filter)

                        ff_h263_loop_filter(s);



                    ff_er_add_slice(&s->er, s->resync_mb_x, s->resync_mb_y,

                                    s->mb_x, s->mb_y, ER_MB_END & part_mask);



                    s->padding_bug_score--;



                    if (++s->mb_x >= s->mb_width) {

                        s->mb_x = 0;

                        ff_mpeg_draw_horiz_band(s, s->mb_y * mb_size, mb_size);

                        ff_mpv_report_decode_progress(s);

                        s->mb_y++;

                    }

                    return 0;

                } else if (ret == SLICE_NOEND) {

                    av_log(s->avctx, AV_LOG_ERROR,

                           "Slice mismatch at MB: %d\n", xy);

                    ff_er_add_slice(&s->er, s->resync_mb_x, s->resync_mb_y,

                                    s->mb_x + 1, s->mb_y,

                                    ER_MB_END & part_mask);

                    return AVERROR_INVALIDDATA;

                }

                av_log(s->avctx, AV_LOG_ERROR, "Error at MB: %d\n", xy);

                ff_er_add_slice(&s->er, s->resync_mb_x, s->resync_mb_y,

                                s->mb_x, s->mb_y, ER_MB_ERROR & part_mask);



                return AVERROR_INVALIDDATA;

            }



            ff_mpv_decode_mb(s, s->block);

            if (s->loop_filter)

                ff_h263_loop_filter(s);

        }



        ff_mpeg_draw_horiz_band(s, s->mb_y * mb_size, mb_size);

        ff_mpv_report_decode_progress(s);



        s->mb_x = 0;

    }



    assert(s->mb_x == 0 && s->mb_y == s->mb_height);



    if (s->codec_id == AV_CODEC_ID_MPEG4         &&

        (s->workaround_bugs & FF_BUG_AUTODETECT) &&

        get_bits_left(&s->gb) >= 48              &&

        show_bits(&s->gb, 24) == 0x4010          &&

        !s->data_partitioning)

        s->padding_bug_score += 32;



    /* try to detect the padding bug */

    if (s->codec_id == AV_CODEC_ID_MPEG4         &&

        (s->workaround_bugs & FF_BUG_AUTODETECT) &&

        get_bits_left(&s->gb) >= 0               &&

        get_bits_left(&s->gb) < 48               &&

        !s->data_partitioning) {

        const int bits_count = get_bits_count(&s->gb);

        const int bits_left  = s->gb.size_in_bits - bits_count;



        if (bits_left == 0) {

            s->padding_bug_score += 16;

        } else if (bits_left != 1) {

            int v = show_bits(&s->gb, 8);

            v |= 0x7F >> (7 - (bits_count & 7));



            if (v == 0x7F && bits_left <= 8)

                s->padding_bug_score--;

            else if (v == 0x7F && ((get_bits_count(&s->gb) + 8) & 8) &&

                     bits_left <= 16)

                s->padding_bug_score += 4;

            else

                s->padding_bug_score++;

        }

    }



    if (s->workaround_bugs & FF_BUG_AUTODETECT) {

        if (s->codec_id == AV_CODEC_ID_H263 ||

            (s->padding_bug_score > -2 && !s->data_partitioning))

            s->workaround_bugs |= FF_BUG_NO_PADDING;

        else

            s->workaround_bugs &= ~FF_BUG_NO_PADDING;

    }



    // handle formats which don't have unique end markers

    if (s->msmpeg4_version || (s->workaround_bugs & FF_BUG_NO_PADDING)) { // FIXME perhaps solve this more cleanly

        int left      = get_bits_left(&s->gb);

        int max_extra = 7;



        /* no markers in M$ crap */

        if (s->msmpeg4_version && s->pict_type == AV_PICTURE_TYPE_I)

            max_extra += 17;



        /* buggy padding but the frame should still end approximately at

         * the bitstream end */

        if ((s->workaround_bugs & FF_BUG_NO_PADDING) &&

            (s->avctx->err_recognition & AV_EF_BUFFER))

            max_extra += 48;

        else if ((s->workaround_bugs & FF_BUG_NO_PADDING))

            max_extra += 256 * 256 * 256 * 64;



        if (left > max_extra)

            av_log(s->avctx, AV_LOG_ERROR,

                   "discarding %d junk bits at end, next would be %X\n",

                   left, show_bits(&s->gb, 24));

        else if (left < 0)

            av_log(s->avctx, AV_LOG_ERROR, "overreading %d bits\n", -left);

        else

            ff_er_add_slice(&s->er, s->resync_mb_x, s->resync_mb_y,

                            s->mb_x - 1, s->mb_y, ER_MB_END);



        return 0;

    }



    av_log(s->avctx, AV_LOG_ERROR,

           "slice end not reached but screenspace end (%d left %06X, score= %d)\n",

           get_bits_left(&s->gb), show_bits(&s->gb, 24), s->padding_bug_score);



    ff_er_add_slice(&s->er, s->resync_mb_x, s->resync_mb_y, s->mb_x, s->mb_y,

                    ER_MB_END & part_mask);



    return AVERROR_INVALIDDATA;

}

DVMuxContext* dv_init_mux(AVFormatContext* s)

{

    DVMuxContext *c;

    AVStream *vst = NULL;

    int i;



    /* we support at most 1 video and 2 audio streams */

    if (s->nb_streams > 3)

        return NULL;



    c = av_mallocz(sizeof(DVMuxContext));

    if (!c)

        return NULL;



    c->n_ast = 0;

    c->ast[0] = c->ast[1] = NULL;



    /* We have to sort out where audio and where video stream is */

    for (i=0; i<s->nb_streams; i++) {

         switch (s->streams[i]->codec->codec_type) {

         case CODEC_TYPE_VIDEO:

               vst = s->streams[i];

               break;

         case CODEC_TYPE_AUDIO:

             c->ast[c->n_ast++] = s->streams[i];

             break;

         default:

               goto bail_out;

         }

    }



    /* Some checks -- DV format is very picky about its incoming streams */

    if (!vst || vst->codec->codec_id != CODEC_ID_DVVIDEO)

        goto bail_out;

    for (i=0; i<c->n_ast; i++) {

        if (c->ast[i] && (c->ast[i]->codec->codec_id != CODEC_ID_PCM_S16LE ||

                          c->ast[i]->codec->sample_rate != 48000 ||

                          c->ast[i]->codec->channels != 2))

            goto bail_out;

    }

    c->sys = dv_codec_profile(vst->codec);

    if (!c->sys)

        goto bail_out;



    if((c->n_ast > 1) && (c->sys->n_difchan < 2)) {

        /* only 1 stereo pair is allowed in 25Mbps mode */

        goto bail_out;

    }



    /* Ok, everything seems to be in working order */

    c->frames = 0;

    c->has_audio = 0;

    c->has_video = 0;

    c->start_time = (time_t)s->timestamp;



    for (i=0; i<c->n_ast; i++) {

        if (c->ast[i] && av_fifo_init(&c->audio_data[i], 100*AVCODEC_MAX_AUDIO_FRAME_SIZE) < 0) {

            while (i>0) {

                i--;

                av_fifo_free(&c->audio_data[i]);

            }

            goto bail_out;

        }

    }



    return c;



bail_out:

    av_free(c);

    return NULL;

}

int ff_rv34_decode_init_thread_copy(AVCodecContext *avctx)

{

    int err;

    RV34DecContext *r = avctx->priv_data;



    r->s.avctx = avctx;



    if (avctx->internal->is_copy) {

        r->tmp_b_block_base = NULL;

        if ((err = ff_MPV_common_init(&r->s)) < 0)

            return err;

        if ((err = rv34_decoder_alloc(r)) < 0)

            return err;

    }



    return 0;

}

static int shall_we_drop(AVFormatContext *s, int index)

{

    struct dshow_ctx *ctx = s->priv_data;

    static const uint8_t dropscore[] = {62, 75, 87, 100};

    const int ndropscores = FF_ARRAY_ELEMS(dropscore);

    unsigned int buffer_fullness = (ctx->curbufsize[index]*100)/s->max_picture_buffer;



    if(dropscore[++ctx->video_frame_num%ndropscores] <= buffer_fullness) {

        av_log(s, AV_LOG_ERROR,

              "real-time buffer[%d] too full (%d%% of size: %d)! frame dropped!\n", index, buffer_fullness, s->max_picture_buffer);

        return 1;

    }



    return 0;

}

static int mimic_decode_update_thread_context(AVCodecContext *avctx, const AVCodecContext *avctx_from)

{

    MimicContext *dst = avctx->priv_data, *src = avctx_from->priv_data;

    int i, ret;



    if (avctx == avctx_from)

        return 0;



    dst->cur_index  = src->next_cur_index;

    dst->prev_index = src->next_prev_index;



    memcpy(dst->flipped_ptrs, src->flipped_ptrs, sizeof(src->flipped_ptrs));



    for (i = 0; i < FF_ARRAY_ELEMS(dst->frames); i++) {

        ff_thread_release_buffer(avctx, &dst->frames[i]);

        if (src->frames[i].f->data[0]) {

            ret = ff_thread_ref_frame(&dst->frames[i], &src->frames[i]);

            if (ret < 0)

                return ret;

        }

    }



    return 0;

}

static int asf_read_stream_properties(AVFormatContext *s, int64_t size)

{

    ASFContext *asf = s->priv_data;

    AVIOContext *pb = s->pb;

    AVStream *st;

    ASFStream *asf_st;

    ff_asf_guid g;

    enum AVMediaType type;

    int type_specific_size, sizeX;

    uint64_t total_size;

    unsigned int tag1;

    int64_t pos1, pos2, start_time;

    int test_for_ext_stream_audio, is_dvr_ms_audio=0;



    if (s->nb_streams == ASF_MAX_STREAMS) {

        av_log(s, AV_LOG_ERROR, "too many streams\n");

        return AVERROR(EINVAL);

    }



    pos1 = avio_tell(pb);



    st = av_new_stream(s, 0);

    if (!st)

        return AVERROR(ENOMEM);

    av_set_pts_info(st, 32, 1, 1000); /* 32 bit pts in ms */

    asf_st = av_mallocz(sizeof(ASFStream));

    if (!asf_st)

        return AVERROR(ENOMEM);

    st->priv_data = asf_st;

    st->start_time = 0;

    start_time = asf->hdr.preroll;



    asf_st->stream_language_index = 128; // invalid stream index means no language info



    if(!(asf->hdr.flags & 0x01)) { // if we aren't streaming...

        st->duration = asf->hdr.play_time /

            (10000000 / 1000) - start_time;

    }

    ff_get_guid(pb, &g);



    test_for_ext_stream_audio = 0;

    if (!ff_guidcmp(&g, &ff_asf_audio_stream)) {

        type = AVMEDIA_TYPE_AUDIO;

    } else if (!ff_guidcmp(&g, &ff_asf_video_stream)) {

        type = AVMEDIA_TYPE_VIDEO;

    } else if (!ff_guidcmp(&g, &ff_asf_jfif_media)) {

        type = AVMEDIA_TYPE_VIDEO;

        st->codec->codec_id = CODEC_ID_MJPEG;

    } else if (!ff_guidcmp(&g, &ff_asf_command_stream)) {

        type = AVMEDIA_TYPE_DATA;

    } else if (!ff_guidcmp(&g, &ff_asf_ext_stream_embed_stream_header)) {

        test_for_ext_stream_audio = 1;

        type = AVMEDIA_TYPE_UNKNOWN;

    } else {

        return -1;

    }

    ff_get_guid(pb, &g);

    total_size = avio_rl64(pb);

    type_specific_size = avio_rl32(pb);

    avio_rl32(pb);

    st->id = avio_rl16(pb) & 0x7f; /* stream id */

    // mapping of asf ID to AV stream ID;

    asf->asfid2avid[st->id] = s->nb_streams - 1;



    avio_rl32(pb);



    if (test_for_ext_stream_audio) {

        ff_get_guid(pb, &g);

        if (!ff_guidcmp(&g, &ff_asf_ext_stream_audio_stream)) {

            type = AVMEDIA_TYPE_AUDIO;

            is_dvr_ms_audio=1;

            ff_get_guid(pb, &g);

            avio_rl32(pb);

            avio_rl32(pb);

            avio_rl32(pb);

            ff_get_guid(pb, &g);

            avio_rl32(pb);

        }

    }



    st->codec->codec_type = type;

    if (type == AVMEDIA_TYPE_AUDIO) {

        ff_get_wav_header(pb, st->codec, type_specific_size);

        if (is_dvr_ms_audio) {

            // codec_id and codec_tag are unreliable in dvr_ms

            // files. Set them later by probing stream.

            st->codec->codec_id = CODEC_ID_PROBE;

            st->codec->codec_tag = 0;

        }

        if (st->codec->codec_id == CODEC_ID_AAC) {

            st->need_parsing = AVSTREAM_PARSE_NONE;

        } else {

            st->need_parsing = AVSTREAM_PARSE_FULL;

        }

        /* We have to init the frame size at some point .... */

        pos2 = avio_tell(pb);

        if (size >= (pos2 + 8 - pos1 + 24)) {

            asf_st->ds_span = avio_r8(pb);

            asf_st->ds_packet_size = avio_rl16(pb);

            asf_st->ds_chunk_size = avio_rl16(pb);

            avio_rl16(pb); //ds_data_size

            avio_r8(pb);   //ds_silence_data

        }

        //printf("Descrambling: ps:%d cs:%d ds:%d s:%d  sd:%d\n",

        //       asf_st->ds_packet_size, asf_st->ds_chunk_size,

        //       asf_st->ds_data_size, asf_st->ds_span, asf_st->ds_silence_data);

        if (asf_st->ds_span > 1) {

            if (!asf_st->ds_chunk_size

                    || (asf_st->ds_packet_size/asf_st->ds_chunk_size <= 1)

                    || asf_st->ds_packet_size % asf_st->ds_chunk_size)

                asf_st->ds_span = 0; // disable descrambling

        }

        switch (st->codec->codec_id) {

            case CODEC_ID_MP3:

                st->codec->frame_size = MPA_FRAME_SIZE;

                break;

            case CODEC_ID_PCM_S16LE:

            case CODEC_ID_PCM_S16BE:

            case CODEC_ID_PCM_U16LE:

            case CODEC_ID_PCM_U16BE:

            case CODEC_ID_PCM_S8:

            case CODEC_ID_PCM_U8:

            case CODEC_ID_PCM_ALAW:

            case CODEC_ID_PCM_MULAW:

                st->codec->frame_size = 1;

                break;

            default:

                /* This is probably wrong, but it prevents a crash later */

                st->codec->frame_size = 1;

                break;

        }

    } else if (type == AVMEDIA_TYPE_VIDEO &&

            size - (avio_tell(pb) - pos1 + 24) >= 51) {

        avio_rl32(pb);

        avio_rl32(pb);

        avio_r8(pb);

        avio_rl16(pb);        /* size */

        sizeX= avio_rl32(pb); /* size */

        st->codec->width = avio_rl32(pb);

        st->codec->height = avio_rl32(pb);

        /* not available for asf */

        avio_rl16(pb); /* panes */

        st->codec->bits_per_coded_sample = avio_rl16(pb); /* depth */

        tag1 = avio_rl32(pb);

        avio_skip(pb, 20);

        //                av_log(s, AV_LOG_DEBUG, "size:%d tsize:%d sizeX:%d\n", size, total_size, sizeX);

        if (sizeX > 40) {

            st->codec->extradata_size = sizeX - 40;

            st->codec->extradata = av_mallocz(st->codec->extradata_size + FF_INPUT_BUFFER_PADDING_SIZE);

            avio_read(pb, st->codec->extradata, st->codec->extradata_size);

        }



        /* Extract palette from extradata if bpp <= 8 */

        /* This code assumes that extradata contains only palette */

        /* This is true for all paletted codecs implemented in ffmpeg */

        if (st->codec->extradata_size && (st->codec->bits_per_coded_sample <= 8)) {

            int av_unused i;

            st->codec->palctrl = av_mallocz(sizeof(AVPaletteControl));

#if HAVE_BIGENDIAN

            for (i = 0; i < FFMIN(st->codec->extradata_size, AVPALETTE_SIZE)/4; i++)

                st->codec->palctrl->palette[i] = av_bswap32(((uint32_t*)st->codec->extradata)[i]);

#else

            memcpy(st->codec->palctrl->palette, st->codec->extradata,

                    FFMIN(st->codec->extradata_size, AVPALETTE_SIZE));

#endif

            st->codec->palctrl->palette_changed = 1;

        }



        st->codec->codec_tag = tag1;

        st->codec->codec_id = ff_codec_get_id(ff_codec_bmp_tags, tag1);

        if(tag1 == MKTAG('D', 'V', 'R', ' ')){

            st->need_parsing = AVSTREAM_PARSE_FULL;

            // issue658 containse wrong w/h and MS even puts a fake seq header with wrong w/h in extradata while a correct one is in te stream. maximum lameness

            st->codec->width  =

                st->codec->height = 0;

            av_freep(&st->codec->extradata);

            st->codec->extradata_size=0;

        }

        if(st->codec->codec_id == CODEC_ID_H264)

            st->need_parsing = AVSTREAM_PARSE_FULL_ONCE;

    }

    pos2 = avio_tell(pb);

    avio_skip(pb, size - (pos2 - pos1 + 24));



    return 0;

}

static int kmvc_decode_intra_8x8(KmvcContext * ctx, const uint8_t * src, int src_size, int w, int h)

{

    BitBuf bb;

    int res, val;

    int i, j;

    int bx, by;

    int l0x, l1x, l0y, l1y;

    int mx, my;

    const uint8_t *src_end = src + src_size;



    kmvc_init_getbits(bb, src);



    for (by = 0; by < h; by += 8)

        for (bx = 0; bx < w; bx += 8) {

            kmvc_getbit(bb, src, src_end, res);

            if (!res) {         // fill whole 8x8 block

                if (src >= src_end) {

                    av_log(ctx->avctx, AV_LOG_ERROR, "Data overrun\n");

                    return AVERROR_INVALIDDATA;

                }

                val = *src++;

                for (i = 0; i < 64; i++)

                    BLK(ctx->cur, bx + (i & 0x7), by + (i >> 3)) = val;

            } else {            // handle four 4x4 subblocks

                for (i = 0; i < 4; i++) {

                    l0x = bx + (i & 1) * 4;

                    l0y = by + (i & 2) * 2;

                    kmvc_getbit(bb, src, src_end, res);

                    if (!res) {

                        kmvc_getbit(bb, src, src_end, res);

                        if (!res) {     // fill whole 4x4 block

                            if (src >= src_end) {

                                av_log(ctx->avctx, AV_LOG_ERROR, "Data overrun\n");

                                return AVERROR_INVALIDDATA;

                            }

                            val = *src++;

                            for (j = 0; j < 16; j++)

                                BLK(ctx->cur, l0x + (j & 3), l0y + (j >> 2)) = val;

                        } else {        // copy block from already decoded place

                            if (src >= src_end) {

                                av_log(ctx->avctx, AV_LOG_ERROR, "Data overrun\n");

                                return AVERROR_INVALIDDATA;

                            }

                            val = *src++;

                            mx = val & 0xF;

                            my = val >> 4;

                            for (j = 0; j < 16; j++)

                                BLK(ctx->cur, l0x + (j & 3), l0y + (j >> 2)) =

                                    BLK(ctx->cur, l0x + (j & 3) - mx, l0y + (j >> 2) - my);

                        }

                    } else {    // descend to 2x2 sub-sub-blocks

                        for (j = 0; j < 4; j++) {

                            l1x = l0x + (j & 1) * 2;

                            l1y = l0y + (j & 2);

                            kmvc_getbit(bb, src, src_end, res);

                            if (!res) {

                                kmvc_getbit(bb, src, src_end, res);

                                if (!res) {     // fill whole 2x2 block

                                    if (src >= src_end) {

                                        av_log(ctx->avctx, AV_LOG_ERROR, "Data overrun\n");

                                        return AVERROR_INVALIDDATA;

                                    }

                                    val = *src++;

                                    BLK(ctx->cur, l1x, l1y) = val;

                                    BLK(ctx->cur, l1x + 1, l1y) = val;

                                    BLK(ctx->cur, l1x, l1y + 1) = val;

                                    BLK(ctx->cur, l1x + 1, l1y + 1) = val;

                                } else {        // copy block from already decoded place

                                    if (src >= src_end) {

                                        av_log(ctx->avctx, AV_LOG_ERROR, "Data overrun\n");

                                        return AVERROR_INVALIDDATA;

                                    }

                                    val = *src++;

                                    mx = val & 0xF;

                                    my = val >> 4;

                                    BLK(ctx->cur, l1x, l1y) = BLK(ctx->cur, l1x - mx, l1y - my);

                                    BLK(ctx->cur, l1x + 1, l1y) =

                                        BLK(ctx->cur, l1x + 1 - mx, l1y - my);

                                    BLK(ctx->cur, l1x, l1y + 1) =

                                        BLK(ctx->cur, l1x - mx, l1y + 1 - my);

                                    BLK(ctx->cur, l1x + 1, l1y + 1) =

                                        BLK(ctx->cur, l1x + 1 - mx, l1y + 1 - my);

                                }

                            } else {    // read values for block

                                BLK(ctx->cur, l1x, l1y) = *src++;

                                BLK(ctx->cur, l1x + 1, l1y) = *src++;

                                BLK(ctx->cur, l1x, l1y + 1) = *src++;

                                BLK(ctx->cur, l1x + 1, l1y + 1) = *src++;

                            }

                        }

                    }

                }

            }

        }



    return 0;

}

static int ff_asf_parse_packet(AVFormatContext *s, ByteIOContext *pb, AVPacket *pkt)

{

    ASFContext *asf = s->priv_data;

    ASFStream *asf_st = 0;

    for (;;) {

        if(url_feof(pb))

            return AVERROR_EOF;

        if (asf->packet_size_left < FRAME_HEADER_SIZE

            || asf->packet_segments < 1) {

            //asf->packet_size_left <= asf->packet_padsize) {

            int ret = asf->packet_size_left + asf->packet_padsize;

            //printf("PacketLeftSize:%d  Pad:%d Pos:%"PRId64"\n", asf->packet_size_left, asf->packet_padsize, url_ftell(pb));

            assert(ret>=0);

            /* fail safe */

            url_fskip(pb, ret);



            asf->packet_pos= url_ftell(pb);

            if (asf->data_object_size != (uint64_t)-1 &&

                (asf->packet_pos - asf->data_object_offset >= asf->data_object_size))

                return AVERROR_EOF; /* Do not exceed the size of the data object */

            return 1;

        }

        if (asf->packet_time_start == 0) {

            if(asf_read_frame_header(s, pb) < 0){

                asf->packet_segments= 0;

                continue;

            }

            if (asf->stream_index < 0

                || s->streams[asf->stream_index]->discard >= AVDISCARD_ALL

                || (!asf->packet_key_frame && s->streams[asf->stream_index]->discard >= AVDISCARD_NONKEY)

                ) {

                asf->packet_time_start = 0;

                /* unhandled packet (should not happen) */

                url_fskip(pb, asf->packet_frag_size);

                asf->packet_size_left -= asf->packet_frag_size;

                if(asf->stream_index < 0)

                    av_log(s, AV_LOG_ERROR, "ff asf skip %d (unknown stream)\n", asf->packet_frag_size);

                continue;

            }

            asf->asf_st = s->streams[asf->stream_index]->priv_data;

        }

        asf_st = asf->asf_st;



        if (asf->packet_replic_size == 1) {

            // frag_offset is here used as the beginning timestamp

            asf->packet_frag_timestamp = asf->packet_time_start;

            asf->packet_time_start += asf->packet_time_delta;

            asf->packet_obj_size = asf->packet_frag_size = get_byte(pb);

            asf->packet_size_left--;

            asf->packet_multi_size--;

            if (asf->packet_multi_size < asf->packet_obj_size)

            {

                asf->packet_time_start = 0;

                url_fskip(pb, asf->packet_multi_size);

                asf->packet_size_left -= asf->packet_multi_size;

                continue;

            }

            asf->packet_multi_size -= asf->packet_obj_size;

            //printf("COMPRESS size  %d  %d  %d   ms:%d\n", asf->packet_obj_size, asf->packet_frag_timestamp, asf->packet_size_left, asf->packet_multi_size);

        }

        if(   /*asf->packet_frag_size == asf->packet_obj_size*/

              asf_st->frag_offset + asf->packet_frag_size <= asf_st->pkt.size

           && asf_st->frag_offset + asf->packet_frag_size > asf->packet_obj_size){

            av_log(s, AV_LOG_INFO, "ignoring invalid packet_obj_size (%d %d %d %d)\n",

                asf_st->frag_offset, asf->packet_frag_size,

                asf->packet_obj_size, asf_st->pkt.size);

            asf->packet_obj_size= asf_st->pkt.size;

        }



        if (   asf_st->pkt.size != asf->packet_obj_size

            || asf_st->frag_offset + asf->packet_frag_size > asf_st->pkt.size) { //FIXME is this condition sufficient?

            if(asf_st->pkt.data){

                av_log(s, AV_LOG_INFO, "freeing incomplete packet size %d, new %d\n", asf_st->pkt.size, asf->packet_obj_size);

                asf_st->frag_offset = 0;

                av_free_packet(&asf_st->pkt);

            }

            /* new packet */

            av_new_packet(&asf_st->pkt, asf->packet_obj_size);

            asf_st->seq = asf->packet_seq;

            asf_st->pkt.dts = asf->packet_frag_timestamp;

            asf_st->pkt.stream_index = asf->stream_index;

            asf_st->pkt.pos =

            asf_st->packet_pos= asf->packet_pos;

//printf("new packet: stream:%d key:%d packet_key:%d audio:%d size:%d\n",

//asf->stream_index, asf->packet_key_frame, asf_st->pkt.flags & AV_PKT_FLAG_KEY,

//s->streams[asf->stream_index]->codec->codec_type == AVMEDIA_TYPE_AUDIO, asf->packet_obj_size);

            if (s->streams[asf->stream_index]->codec->codec_type == AVMEDIA_TYPE_AUDIO)

                asf->packet_key_frame = 1;

            if (asf->packet_key_frame)

                asf_st->pkt.flags |= AV_PKT_FLAG_KEY;

        }



        /* read data */

        //printf("READ PACKET s:%d  os:%d  o:%d,%d  l:%d   DATA:%p\n",

        //       s->packet_size, asf_st->pkt.size, asf->packet_frag_offset,

        //       asf_st->frag_offset, asf->packet_frag_size, asf_st->pkt.data);

        asf->packet_size_left -= asf->packet_frag_size;

        if (asf->packet_size_left < 0)

            continue;



        if(   asf->packet_frag_offset >= asf_st->pkt.size

           || asf->packet_frag_size > asf_st->pkt.size - asf->packet_frag_offset){

            av_log(s, AV_LOG_ERROR, "packet fragment position invalid %u,%u not in %u\n",

                asf->packet_frag_offset, asf->packet_frag_size, asf_st->pkt.size);

            continue;

        }



        get_buffer(pb, asf_st->pkt.data + asf->packet_frag_offset,

                   asf->packet_frag_size);

        if (s->key && s->keylen == 20)

            ff_asfcrypt_dec(s->key, asf_st->pkt.data + asf->packet_frag_offset,

                            asf->packet_frag_size);

        asf_st->frag_offset += asf->packet_frag_size;

        /* test if whole packet is read */

        if (asf_st->frag_offset == asf_st->pkt.size) {

            //workaround for macroshit radio DVR-MS files

            if(   s->streams[asf->stream_index]->codec->codec_id == CODEC_ID_MPEG2VIDEO

               && asf_st->pkt.size > 100){

                int i;

                for(i=0; i<asf_st->pkt.size && !asf_st->pkt.data[i]; i++);

                if(i == asf_st->pkt.size){

                    av_log(s, AV_LOG_DEBUG, "discarding ms fart\n");

                    asf_st->frag_offset = 0;

                    av_free_packet(&asf_st->pkt);

                    continue;

                }

            }



            /* return packet */

            if (asf_st->ds_span > 1) {

              if(asf_st->pkt.size != asf_st->ds_packet_size * asf_st->ds_span){

                    av_log(s, AV_LOG_ERROR, "pkt.size != ds_packet_size * ds_span (%d %d %d)\n", asf_st->pkt.size, asf_st->ds_packet_size, asf_st->ds_span);

              }else{

                /* packet descrambling */

                uint8_t *newdata = av_malloc(asf_st->pkt.size + FF_INPUT_BUFFER_PADDING_SIZE);

                if (newdata) {

                    int offset = 0;

                    memset(newdata + asf_st->pkt.size, 0, FF_INPUT_BUFFER_PADDING_SIZE);

                    while (offset < asf_st->pkt.size) {

                        int off = offset / asf_st->ds_chunk_size;

                        int row = off / asf_st->ds_span;

                        int col = off % asf_st->ds_span;

                        int idx = row + col * asf_st->ds_packet_size / asf_st->ds_chunk_size;

                        //printf("off:%d  row:%d  col:%d  idx:%d\n", off, row, col, idx);



                        assert(offset + asf_st->ds_chunk_size <= asf_st->pkt.size);

                        assert(idx+1 <= asf_st->pkt.size / asf_st->ds_chunk_size);

                        memcpy(newdata + offset,

                               asf_st->pkt.data + idx * asf_st->ds_chunk_size,

                               asf_st->ds_chunk_size);

                        offset += asf_st->ds_chunk_size;

                    }

                    av_free(asf_st->pkt.data);

                    asf_st->pkt.data = newdata;

                }

              }

            }

            asf_st->frag_offset = 0;

            *pkt= asf_st->pkt;

            //printf("packet %d %d\n", asf_st->pkt.size, asf->packet_frag_size);

            asf_st->pkt.size = 0;

            asf_st->pkt.data = 0;

            break; // packet completed

        }

    }

    return 0;

}

static int filter_samples(AVFilterLink *inlink, AVFilterBufferRef *buf)

{

    AVFilterContext  *ctx = inlink->dst;

    ASyncContext       *s = ctx->priv;

    AVFilterLink *outlink = ctx->outputs[0];

    int nb_channels = av_get_channel_layout_nb_channels(buf->audio->channel_layout);

    int64_t pts = (buf->pts == AV_NOPTS_VALUE) ? buf->pts :

                  av_rescale_q(buf->pts, inlink->time_base, outlink->time_base);

    int out_size, ret;

    int64_t delta;



    /* buffer data until we get the first timestamp */

    if (s->pts == AV_NOPTS_VALUE) {

        if (pts != AV_NOPTS_VALUE) {

            s->pts = pts - get_delay(s);

        }

        return write_to_fifo(s, buf);

    }



    /* now wait for the next timestamp */

    if (pts == AV_NOPTS_VALUE) {

        return write_to_fifo(s, buf);

    }



    /* when we have two timestamps, compute how many samples would we have

     * to add/remove to get proper sync between data and timestamps */

    delta    = pts - s->pts - get_delay(s);

    out_size = avresample_available(s->avr);



    if (labs(delta) > s->min_delta) {

        av_log(ctx, AV_LOG_VERBOSE, "Discontinuity - %"PRId64" samples.\n", delta);

        out_size += delta;

    } else {

        if (s->resample) {

            int comp = av_clip(delta, -s->max_comp, s->max_comp);

            av_log(ctx, AV_LOG_VERBOSE, "Compensating %d samples per second.\n", comp);

            avresample_set_compensation(s->avr, delta, inlink->sample_rate);

        }

        delta = 0;

    }



    if (out_size > 0) {

        AVFilterBufferRef *buf_out = ff_get_audio_buffer(outlink, AV_PERM_WRITE,

                                                         out_size);

        if (!buf_out) {

            ret = AVERROR(ENOMEM);

            goto fail;

        }



        avresample_read(s->avr, (void**)buf_out->extended_data, out_size);

        buf_out->pts = s->pts;



        if (delta > 0) {

            av_samples_set_silence(buf_out->extended_data, out_size - delta,

                                   delta, nb_channels, buf->format);

        }

        ret = ff_filter_samples(outlink, buf_out);

        if (ret < 0)

            goto fail;

        s->got_output = 1;

    } else {

        av_log(ctx, AV_LOG_WARNING, "Non-monotonous timestamps, dropping "

               "whole buffer.\n");

    }



    /* drain any remaining buffered data */

    avresample_read(s->avr, NULL, avresample_available(s->avr));



    s->pts = pts - avresample_get_delay(s->avr);

    ret = avresample_convert(s->avr, NULL, 0, 0, (void**)buf->extended_data,

                             buf->linesize[0], buf->audio->nb_samples);



fail:

    avfilter_unref_buffer(buf);



    return ret;

}

static int init_output_stream_streamcopy(OutputStream *ost)

{

    OutputFile *of = output_files[ost->file_index];

    InputStream *ist = get_input_stream(ost);

    AVCodecParameters *par_dst = ost->st->codecpar;

    AVCodecParameters *par_src = ost->ref_par;

    AVRational sar;

    int i, ret;

    uint32_t codec_tag = par_dst->codec_tag;



    av_assert0(ist && !ost->filter);



    avcodec_parameters_to_context(ost->enc_ctx, ist->st->codecpar);

    ret = av_opt_set_dict(ost->enc_ctx, &ost->encoder_opts);

    if (ret < 0) {

        av_log(NULL, AV_LOG_FATAL,

               "Error setting up codec context options.\n");

        return ret;

    }

    avcodec_parameters_from_context(par_src, ost->enc_ctx);



    if (!codec_tag) {

        unsigned int codec_tag_tmp;

        if (!of->ctx->oformat->codec_tag ||

            av_codec_get_id (of->ctx->oformat->codec_tag, par_src->codec_tag) == par_src->codec_id ||

            !av_codec_get_tag2(of->ctx->oformat->codec_tag, par_src->codec_id, &codec_tag_tmp))

            codec_tag = par_src->codec_tag;

    }



    ret = avcodec_parameters_copy(par_dst, par_src);

    if (ret < 0)

        return ret;



    par_dst->codec_tag = codec_tag;



    if (!ost->frame_rate.num)

        ost->frame_rate = ist->framerate;

    ost->st->avg_frame_rate = ost->frame_rate;



    ret = avformat_transfer_internal_stream_timing_info(of->ctx->oformat, ost->st, ist->st, copy_tb);

    if (ret < 0)

        return ret;



    // copy timebase while removing common factors

    ost->st->time_base = av_add_q(av_stream_get_codec_timebase(ost->st), (AVRational){0, 1});



    // copy disposition

    ost->st->disposition = ist->st->disposition;



    if (ist->st->nb_side_data) {

        ost->st->side_data = av_realloc_array(NULL, ist->st->nb_side_data,

                                              sizeof(*ist->st->side_data));

        if (!ost->st->side_data)

            return AVERROR(ENOMEM);



        ost->st->nb_side_data = 0;

        for (i = 0; i < ist->st->nb_side_data; i++) {

            const AVPacketSideData *sd_src = &ist->st->side_data[i];

            AVPacketSideData *sd_dst = &ost->st->side_data[ost->st->nb_side_data];



            if (ost->rotate_overridden && sd_src->type == AV_PKT_DATA_DISPLAYMATRIX)

                continue;



            sd_dst->data = av_malloc(sd_src->size);

            if (!sd_dst->data)

                return AVERROR(ENOMEM);

            memcpy(sd_dst->data, sd_src->data, sd_src->size);

            sd_dst->size = sd_src->size;

            sd_dst->type = sd_src->type;

            ost->st->nb_side_data++;

        }

    }



    ost->parser = av_parser_init(par_dst->codec_id);

    ost->parser_avctx = avcodec_alloc_context3(NULL);

    if (!ost->parser_avctx)

        return AVERROR(ENOMEM);



    switch (par_dst->codec_type) {

    case AVMEDIA_TYPE_AUDIO:

        if (audio_volume != 256) {

            av_log(NULL, AV_LOG_FATAL, "-acodec copy and -vol are incompatible (frames are not decoded)\n");

            exit_program(1);

        }

        if((par_dst->block_align == 1 || par_dst->block_align == 1152 || par_dst->block_align == 576) && par_dst->codec_id == AV_CODEC_ID_MP3)

            par_dst->block_align= 0;

        if(par_dst->codec_id == AV_CODEC_ID_AC3)

            par_dst->block_align= 0;

        break;

    case AVMEDIA_TYPE_VIDEO:

        if (ost->frame_aspect_ratio.num) { // overridden by the -aspect cli option

            sar =

                av_mul_q(ost->frame_aspect_ratio,

                         (AVRational){ par_dst->height, par_dst->width });

            av_log(NULL, AV_LOG_WARNING, "Overriding aspect ratio "

                   "with stream copy may produce invalid files\n");

            }

        else if (ist->st->sample_aspect_ratio.num)

            sar = ist->st->sample_aspect_ratio;

        else

            sar = par_src->sample_aspect_ratio;

        ost->st->sample_aspect_ratio = par_dst->sample_aspect_ratio = sar;

        ost->st->avg_frame_rate = ist->st->avg_frame_rate;

        ost->st->r_frame_rate = ist->st->r_frame_rate;

        break;

    }



    return 0;

}

yuv2rgb_full_1_c_template(SwsContext *c, const int16_t *buf0,

                     const int16_t *ubuf[2], const int16_t *vbuf[2],

                     const int16_t *abuf0, uint8_t *dest, int dstW,

                     int uvalpha, int y, enum AVPixelFormat target,

                     int hasAlpha)

{

    const int16_t *ubuf0 = ubuf[0], *vbuf0 = vbuf[0];

    int i;

    int step = (target == AV_PIX_FMT_RGB24 || target == AV_PIX_FMT_BGR24) ? 3 : 4;

    int err[4] = {0};



    if(   target == AV_PIX_FMT_BGR4_BYTE || target == AV_PIX_FMT_RGB4_BYTE

       || target == AV_PIX_FMT_BGR8      || target == AV_PIX_FMT_RGB8)

        step = 1;



    if (uvalpha < 2048) {

        for (i = 0; i < dstW; i++) {

            int Y = buf0[i] << 2;

            int U = (ubuf0[i] - (128<<7)) << 2;

            int V = (vbuf0[i] - (128<<7)) << 2;

            int A;



            if (hasAlpha) {

                A = (abuf0[i] + 64) >> 7;

                if (A & 0x100)

                    A = av_clip_uint8(A);

            }



            yuv2rgb_write_full(c, dest, i, Y, A, U, V, y, target, hasAlpha, err);

            dest += step;

        }

    } else {

        const int16_t *ubuf1 = ubuf[1], *vbuf1 = vbuf[1];

        for (i = 0; i < dstW; i++) {

            int Y = buf0[i] << 2;

            int U = (ubuf0[i] + ubuf1[i] - (128<<8)) << 1;

            int V = (vbuf0[i] + vbuf1[i] - (128<<8)) << 1;

            int A;



            if (hasAlpha) {

                A = (abuf0[i] + 64) >> 7;

                if (A & 0x100)

                    A = av_clip_uint8(A);

            }



            yuv2rgb_write_full(c, dest, i, Y, A, U, V, y, target, hasAlpha, err);

            dest += step;

        }

    }



    c->dither_error[0][i] = err[0];

    c->dither_error[1][i] = err[1];

    c->dither_error[2][i] = err[2];

}

static void parse_ptl(HEVCContext *s, PTL *ptl, int max_num_sub_layers)

{

    int i;

    HEVCLocalContext *lc = s->HEVClc;

    GetBitContext *gb = &lc->gb;

    decode_profile_tier_level(s, &ptl->general_ptl);

    ptl->general_ptl.level_idc = get_bits(gb, 8);



    for (i = 0; i < max_num_sub_layers - 1; i++) {

        ptl->sub_layer_profile_present_flag[i] = get_bits1(gb);

        ptl->sub_layer_level_present_flag[i]   = get_bits1(gb);

    }

    if (max_num_sub_layers - 1> 0)

        for (i = max_num_sub_layers - 1; i < 8; i++)

            skip_bits(gb, 2); // reserved_zero_2bits[i]

    for (i = 0; i < max_num_sub_layers - 1; i++) {

        if (ptl->sub_layer_profile_present_flag[i])

            decode_profile_tier_level(s, &ptl->sub_layer_ptl[i]);

        if (ptl->sub_layer_level_present_flag[i])

            ptl->sub_layer_ptl[i].level_idc = get_bits(gb, 8);

    }

}

void av_blowfish_crypt(AVBlowfish *ctx, uint8_t *dst, const uint8_t *src,

                       int count, uint8_t *iv, int decrypt)

{

    uint32_t v0, v1;

    int i;



    while (count > 0) {

        if (decrypt) {

            v0 = AV_RB32(src);

            v1 = AV_RB32(src + 4);



            av_blowfish_crypt_ecb(ctx, &v0, &v1, decrypt);



            AV_WB32(dst, v0);

            AV_WB32(dst + 4, v1);



            if (iv) {

                for (i = 0; i < 8; i++)

                    dst[i] = dst[i] ^ iv[i];

                memcpy(iv, src, 8);

            }

        } else {

            if (iv) {

                for (i = 0; i < 8; i++)

                    dst[i] = src[i] ^ iv[i];

                v0 = AV_RB32(dst);

                v1 = AV_RB32(dst + 4);

            } else {

                v0 = AV_RB32(src);

                v1 = AV_RB32(src + 4);

            }



            av_blowfish_crypt_ecb(ctx, &v0, &v1, decrypt);



            AV_WB32(dst, v0);

            AV_WB32(dst + 4, v1);



            if (iv)

                memcpy(iv, dst, 8);

        }



        src   += 8;

        dst   += 8;

        count -= 8;

    }

}

void ff_put_h264_qpel16_mc22_msa(uint8_t *dst, const uint8_t *src,

                                 ptrdiff_t stride)

{

    avc_luma_mid_16w_msa(src - (2 * stride) - 2, stride, dst, stride, 16);

