int ff_dirac_parse_sequence_header(AVCodecContext *avctx, GetBitContext *gb,

                                   dirac_source_params *source)

{

    unsigned version_major;

    unsigned video_format, picture_coding_mode;



    version_major  = svq3_get_ue_golomb(gb);

    svq3_get_ue_golomb(gb); /* version_minor */

    avctx->profile = svq3_get_ue_golomb(gb);

    avctx->level   = svq3_get_ue_golomb(gb);

    video_format   = svq3_get_ue_golomb(gb);



    if (version_major < 2)

        av_log(avctx, AV_LOG_WARNING, "Stream is old and may not work\n");

    else if (version_major > 2)

        av_log(avctx, AV_LOG_WARNING, "Stream may have unhandled features\n");



    if (video_format > 20)

        return -1;



    // Fill in defaults for the source parameters.

    *source = dirac_source_parameters_defaults[video_format];



    // Override the defaults.

    if (parse_source_parameters(avctx, gb, source))

        return -1;



    if (av_image_check_size(source->width, source->height, 0, avctx))

        return -1;



    avcodec_set_dimensions(avctx, source->width, source->height);



    // currently only used to signal field coding

    picture_coding_mode = svq3_get_ue_golomb(gb);

    if (picture_coding_mode != 0) {

        av_log(avctx, AV_LOG_ERROR, "Unsupported picture coding mode %d",

               picture_coding_mode);

        return -1;

    }

    return 0;

}

static int mov_read_moov(MOVContext *c, ByteIOContext *pb, MOV_atom_t atom)

{

    int err;



    err = mov_read_default(c, pb, atom);

    /* we parsed the 'moov' atom, we can terminate the parsing as soon as we find the 'mdat' */

    /* so we don't parse the whole file if over a network */

    c->found_moov=1;

    if(c->found_mdat)

        return 1; /* found both, just go */

    return 0; /* now go for mdat */

}

static int xvid_ff_2pass_create(xvid_plg_create_t * param,

                                void ** handle) {

    struct xvid_ff_pass1 *x = (struct xvid_ff_pass1 *)param->param;

    char *log = x->context->twopassbuffer;



    /* Do a quick bounds check */

    if( log == NULL )

        return XVID_ERR_FAIL;



    /* We use snprintf() */

    /* This is because we can safely prevent a buffer overflow */

    log[0] = 0;

    snprintf(log, BUFFER_REMAINING(log),

        "# avconv 2-pass log file, using xvid codec\n");

    snprintf(BUFFER_CAT(log), BUFFER_REMAINING(log),

        "# Do not modify. libxvidcore version: %d.%d.%d\n\n",

        XVID_VERSION_MAJOR(XVID_VERSION),

        XVID_VERSION_MINOR(XVID_VERSION),

        XVID_VERSION_PATCH(XVID_VERSION));



    *handle = x->context;

    return 0;

}

int ff_mjpeg_find_marker(MJpegDecodeContext *s,

                         const uint8_t **buf_ptr, const uint8_t *buf_end,

                         const uint8_t **unescaped_buf_ptr,

                         int *unescaped_buf_size)

{

    int start_code;

    start_code = find_marker(buf_ptr, buf_end);



    av_fast_padded_malloc(&s->buffer, &s->buffer_size, buf_end - *buf_ptr);

    if (!s->buffer)

        return AVERROR(ENOMEM);



    /* unescape buffer of SOS, use special treatment for JPEG-LS */

    if (start_code == SOS && !s->ls) {

        const uint8_t *src = *buf_ptr;

        uint8_t *dst = s->buffer;



        while (src < buf_end) {

            uint8_t x = *(src++);



            *(dst++) = x;

            if (s->avctx->codec_id != AV_CODEC_ID_THP) {

                if (x == 0xff) {

                    while (src < buf_end && x == 0xff)

                        x = *(src++);



                    if (x >= 0xd0 && x <= 0xd7)

                        *(dst++) = x;

                    else if (x)

                        break;

                }

            }

        }

        *unescaped_buf_ptr  = s->buffer;

        *unescaped_buf_size = dst - s->buffer;

        memset(s->buffer + *unescaped_buf_size, 0,

               FF_INPUT_BUFFER_PADDING_SIZE);



        av_log(s->avctx, AV_LOG_DEBUG, "escaping removed %td bytes\n",

               (buf_end - *buf_ptr) - (dst - s->buffer));

    } else if (start_code == SOS && s->ls) {

        const uint8_t *src = *buf_ptr;

        uint8_t *dst  = s->buffer;

        int bit_count = 0;

        int t = 0, b = 0;

        PutBitContext pb;



        s->cur_scan++;



        /* find marker */

        while (src + t < buf_end) {

            uint8_t x = src[t++];

            if (x == 0xff) {

                while ((src + t < buf_end) && x == 0xff)

                    x = src[t++];

                if (x & 0x80) {

                    t -= 2;

                    break;

                }

            }

        }

        bit_count = t * 8;

        init_put_bits(&pb, dst, t);



        /* unescape bitstream */

        while (b < t) {

            uint8_t x = src[b++];

            put_bits(&pb, 8, x);

            if (x == 0xFF) {

                x = src[b++];

                put_bits(&pb, 7, x);

                bit_count--;

            }

        }

        flush_put_bits(&pb);



        *unescaped_buf_ptr  = dst;

        *unescaped_buf_size = (bit_count + 7) >> 3;

        memset(s->buffer + *unescaped_buf_size, 0,

               FF_INPUT_BUFFER_PADDING_SIZE);

    } else {

        *unescaped_buf_ptr  = *buf_ptr;

        *unescaped_buf_size = buf_end - *buf_ptr;

    }



    return start_code;

}

static int yuv4_write_header(AVFormatContext *s)

{

    int *first_pkt = s->priv_data;



    if (s->nb_streams != 1)

        return AVERROR(EIO);



    if (s->streams[0]->codecpar->codec_id != AV_CODEC_ID_WRAPPED_AVFRAME) {

        av_log(s, AV_LOG_ERROR, "ERROR: Codec not supported.\n");

        return AVERROR_INVALIDDATA;

    }



    switch (s->streams[0]->codecpar->format) {

    case AV_PIX_FMT_YUV411P:

        av_log(s, AV_LOG_WARNING, "Warning: generating rarely used 4:1:1 YUV "

               "stream, some mjpegtools might not work.\n");

        break;

    case AV_PIX_FMT_GRAY8:

    case AV_PIX_FMT_GRAY16:

    case AV_PIX_FMT_YUV420P:

    case AV_PIX_FMT_YUV422P:

    case AV_PIX_FMT_YUV444P:

        break;

    case AV_PIX_FMT_YUV420P9:

    case AV_PIX_FMT_YUV422P9:

    case AV_PIX_FMT_YUV444P9:

    case AV_PIX_FMT_YUV420P10:

    case AV_PIX_FMT_YUV422P10:

    case AV_PIX_FMT_YUV444P10:

    case AV_PIX_FMT_YUV420P12:

    case AV_PIX_FMT_YUV422P12:

    case AV_PIX_FMT_YUV444P12:

    case AV_PIX_FMT_YUV420P14:

    case AV_PIX_FMT_YUV422P14:

    case AV_PIX_FMT_YUV444P14:

    case AV_PIX_FMT_YUV420P16:

    case AV_PIX_FMT_YUV422P16:

    case AV_PIX_FMT_YUV444P16:

        if (s->strict_std_compliance >= FF_COMPLIANCE_NORMAL) {

            av_log(s, AV_LOG_ERROR, "'%s' is not an official yuv4mpegpipe pixel format. "

                   "Use '-strict -1' to encode to this pixel format.\n",

                   av_get_pix_fmt_name(s->streams[0]->codecpar->format));

            return AVERROR(EINVAL);

        }

        av_log(s, AV_LOG_WARNING, "Warning: generating non standard YUV stream. "

               "Mjpegtools will not work.\n");

        break;

    default:

        av_log(s, AV_LOG_ERROR, "ERROR: yuv4mpeg can only handle "

               "yuv444p, yuv422p, yuv420p, yuv411p and gray8 pixel formats. "

               "And using 'strict -1' also yuv444p9, yuv422p9, yuv420p9, "

               "yuv444p10, yuv422p10, yuv420p10, "

               "yuv444p12, yuv422p12, yuv420p12, "

               "yuv444p14, yuv422p14, yuv420p14, "

               "yuv444p16, yuv422p16, yuv420p16 "

               "and gray16 pixel formats. "

               "Use -pix_fmt to select one.\n");

        return AVERROR(EIO);

    }



    *first_pkt = 1;

    return 0;

}

int rtp_set_remote_url(URLContext *h, const char *uri)

{

    RTPContext *s = h->priv_data;

    char hostname[256];

    int port;



    char buf[1024];

    char path[1024];



    url_split(NULL, 0, hostname, sizeof(hostname), &port, 

              path, sizeof(path), uri);



    snprintf(buf, sizeof(buf), "udp://%s:%d%s", hostname, port, path);

    udp_set_remote_url(s->rtp_hd, buf);



    snprintf(buf, sizeof(buf), "udp://%s:%d%s", hostname, port + 1, path);

    udp_set_remote_url(s->rtcp_hd, buf);

    return 0;

}

int vp78_decode_mb_row_sliced(AVCodecContext *avctx, void *tdata, int jobnr,

                              int threadnr, int is_vp7)

{

    VP8Context *s = avctx->priv_data;

    VP8ThreadData *td = &s->thread_data[jobnr];

    VP8ThreadData *next_td = NULL, *prev_td = NULL;

    VP8Frame *curframe = s->curframe;

    int mb_y, num_jobs = s->num_jobs;

    int ret;



    td->thread_nr = threadnr;

    for (mb_y = jobnr; mb_y < s->mb_height; mb_y += num_jobs) {

        if (mb_y >= s->mb_height)

            break;

        td->thread_mb_pos = mb_y << 16;

        ret = s->decode_mb_row_no_filter(avctx, tdata, jobnr, threadnr);

        if (ret < 0)

            return ret;

        if (s->deblock_filter)

            s->filter_mb_row(avctx, tdata, jobnr, threadnr);

        update_pos(td, mb_y, INT_MAX & 0xFFFF);



        s->mv_min.y -= 64;

        s->mv_max.y -= 64;



        if (avctx->active_thread_type == FF_THREAD_FRAME)

            ff_thread_report_progress(&curframe->tf, mb_y, 0);

    }



    return 0;

}

