static int vp9_handle_packet(AVFormatContext *ctx, PayloadContext *rtp_vp9_ctx,

                             AVStream *st, AVPacket *pkt, uint32_t *timestamp,

                             const uint8_t *buf, int len, uint16_t seq,

                             int flags)

{

    int has_pic_id, has_layer_idc, has_ref_idc, has_ss_data, has_su_data;

    av_unused int pic_id = 0, non_key_frame = 0;

    av_unused int layer_temporal = -1, layer_spatial = -1, layer_quality = -1;

    int ref_fields = 0, has_ref_field_ext_pic_id = 0;

    int first_fragment, last_fragment;

    int rtp_m;

    int res = 0;



    /* drop data of previous packets in case of non-continuous (lossy) packet stream */

    if (rtp_vp9_ctx->buf && rtp_vp9_ctx->timestamp != *timestamp)

        ffio_free_dyn_buf(&rtp_vp9_ctx->buf);



    /* sanity check for size of input packet: 1 byte payload at least */

    if (len < RTP_VP9_DESC_REQUIRED_SIZE + 1) {

        av_log(ctx, AV_LOG_ERROR, "Too short RTP/VP9 packet, got %d bytes\n", len);

        return AVERROR_INVALIDDATA;

    }



    /*

     *     decode the required VP9 payload descriptor according to section 4.2 of the spec.:

     *

     *      0 1 2 3 4 5 6 7

     *     +-+-+-+-+-+-+-+-+

     *     |I|L|F|B|E|V|U|-| (REQUIRED)

     *     +-+-+-+-+-+-+-+-+

     *

     *     I: PictureID present

     *     L: Layer indices present

     *     F: Reference indices present

     *     B: Start of VP9 frame

     *     E: End of picture

     *     V: Scalability Structure (SS) present

     *     U: Scalability Structure Update (SU) present

     */

    has_pic_id     = !!(buf[0] & 0x80);

    has_layer_idc  = !!(buf[0] & 0x40);

    has_ref_idc    = !!(buf[0] & 0x20);

    first_fragment = !!(buf[0] & 0x10);

    last_fragment  = !!(buf[0] & 0x08);

    has_ss_data    = !!(buf[0] & 0x04);

    has_su_data    = !!(buf[0] & 0x02);



    rtp_m = !!(flags & RTP_FLAG_MARKER);



    /* sanity check for markers: B should always be equal to the RTP M marker */

    if (last_fragment != rtp_m) {

        av_log(ctx, AV_LOG_ERROR, "Invalid combination of B and M marker (%d != %d)\n", last_fragment, rtp_m);

        return AVERROR_INVALIDDATA;

    }



    /* pass the extensions field */

    buf += RTP_VP9_DESC_REQUIRED_SIZE;

    len -= RTP_VP9_DESC_REQUIRED_SIZE;



    /*

     *         decode the 1-byte/2-byte picture ID:

     *

     *          0 1 2 3 4 5 6 7

     *         +-+-+-+-+-+-+-+-+

     *   I:    |M|PICTURE ID   | (RECOMMENDED)

     *         +-+-+-+-+-+-+-+-+

     *   M:    | EXTENDED PID  | (RECOMMENDED)

     *         +-+-+-+-+-+-+-+-+

     *

     *   M: The most significant bit of the first octet is an extension flag.

     *   PictureID:  8 or 16 bits including the M bit.

     */

    if (has_pic_id) {

        if (len < 1) {

            av_log(ctx, AV_LOG_ERROR, "Too short RTP/VP9 packet\n");

            return AVERROR_INVALIDDATA;

        }



        /* check for 1-byte or 2-byte picture index */

        if (buf[0] & 0x80) {

            if (len < 2) {

                av_log(ctx, AV_LOG_ERROR, "Too short RTP/VP9 packet\n");

                return AVERROR_INVALIDDATA;

            }

            pic_id = AV_RB16(buf) & 0x7fff;

            buf += 2;

            len -= 2;

        } else {

            pic_id = buf[0] & 0x7f;

            buf++;

            len--;

        }

    }



    /*

     *         decode layer indices

     *

     *          0 1 2 3 4 5 6 7

     *         +-+-+-+-+-+-+-+-+

     *   L:    | T | S | Q | R | (CONDITIONALLY RECOMMENDED)

     *         +-+-+-+-+-+-+-+-+

     *

     *   T, S and Q are 2-bit indices for temporal, spatial, and quality layers.

     *   If "F" is set in the initial octet, R is 2 bits representing the number

     *   of reference fields this frame refers to.

     */

    if (has_layer_idc) {

        if (len < 1) {

            av_log(ctx, AV_LOG_ERROR, "Too short RTP/VP9 packet\n");

            return AVERROR_INVALIDDATA;

        }

        layer_temporal = buf[0] & 0xC0;

        layer_spatial  = buf[0] & 0x30;

        layer_quality  = buf[0] & 0x0C;

        if (has_ref_idc) {

            ref_fields = buf[0] & 0x03;

            if (ref_fields)

                non_key_frame = 1;

        }

        buf++;

        len--;

    }



    /*

     *         decode the reference fields

     *

     *          0 1 2 3 4 5 6 7

     *         +-+-+-+-+-+-+-+-+              -\

     *   F:    | PID |X| RS| RQ| (OPTIONAL)    .

     *         +-+-+-+-+-+-+-+-+               . - R times

     *   X:    | EXTENDED PID  | (OPTIONAL)    .

     *         +-+-+-+-+-+-+-+-+              -/

     *

     *   PID:  The relative Picture ID referred to by this frame.

     *   RS and RQ:  The spatial and quality layer IDs.

     *   X: 1 if this layer index has an extended relative Picture ID.

     */

    if (has_ref_idc) {

        while (ref_fields) {

            if (len < 1) {

                av_log(ctx, AV_LOG_ERROR, "Too short RTP/VP9 packet\n");

                return AVERROR_INVALIDDATA;

            }



            has_ref_field_ext_pic_id = buf[0] & 0x10;



            /* pass ref. field */

            if (has_ref_field_ext_pic_id) {

                if (len < 2) {

                    av_log(ctx, AV_LOG_ERROR, "Too short RTP/VP9 packet\n");

                    return AVERROR_INVALIDDATA;

                }



                /* ignore ref. data */



                buf += 2;

                len -= 2;

            } else {



                /* ignore ref. data */



                buf++;

                len--;

            }

            ref_fields--;

        }

    }



    /*

     *         decode the scalability structure (SS)

     *

     *          0 1 2 3 4 5 6 7

     *         +-+-+-+-+-+-+-+-+

     *   V:    | PATTERN LENGTH|

     *         +-+-+-+-+-+-+-+-+                           -\

     *         | T | S | Q | R | (OPTIONAL)                 .

     *         +-+-+-+-+-+-+-+-+              -\            .

     *         | PID |X| RS| RQ| (OPTIONAL)    .            . - PAT. LEN. times

     *         +-+-+-+-+-+-+-+-+               . - R times  .

     *   X:    | EXTENDED PID  | (OPTIONAL)    .            .

     *         +-+-+-+-+-+-+-+-+              -/           -/

     *

     *   PID:  The relative Picture ID referred to by this frame.

     *   RS and RQ:  The spatial and quality layer IDs.

     *   X: 1 if this layer index has an extended relative Picture ID.

     */

    if (has_ss_data) {

        avpriv_report_missing_feature(ctx, "VP9 scalability structure data");

        return AVERROR(ENOSYS);

    }



    /*

     * decode the scalability update structure (SU)

     *

     *  spec. is tbd

     */

    if (has_su_data) {

        avpriv_report_missing_feature(ctx, "VP9 scalability update structure data");

        return AVERROR(ENOSYS);

    }



    /*

     * decode the VP9 payload header

     *

     *  spec. is tbd

     */

    //XXX: implement when specified



    /* sanity check: 1 byte payload as minimum */

    if (len < 1) {

        av_log(ctx, AV_LOG_ERROR, "Too short RTP/VP9 packet\n");

        return AVERROR_INVALIDDATA;

    }



    /* start frame buffering with new dynamic buffer */

    if (!rtp_vp9_ctx->buf) {

        /* sanity check: a new frame should have started */

        if (first_fragment) {

            res = avio_open_dyn_buf(&rtp_vp9_ctx->buf);

            if (res < 0)

                return res;

            /* update the timestamp in the frame packet with the one from the RTP packet */

            rtp_vp9_ctx->timestamp = *timestamp;

        } else {

            /* frame not started yet, need more packets */

            return AVERROR(EAGAIN);

        }

    }



    /* write the fragment to the dyn. buffer */

    avio_write(rtp_vp9_ctx->buf, buf, len);



    /* do we need more fragments? */

    if (!last_fragment)

        return AVERROR(EAGAIN);



    /* close frame buffering and create resulting A/V packet */

    res = ff_rtp_finalize_packet(pkt, &rtp_vp9_ctx->buf, st->index);

    if (res < 0)

        return res;



    return 0;

}

static int ir2_decode_plane_inter(Ir2Context *ctx, int width, int height, uint8_t *dst,

                                  int pitch, const uint8_t *table)

{

    int j;

    int out = 0;

    int c;

    int t;



    if (width & 1)




    for (j = 0; j < height; j++) {

        out = 0;



        while (out < width) {

            c = ir2_get_code(&ctx->gb);

            if (c >= 0x80) { /* we have a skip */

                c   -= 0x7F;

                out += c * 2;

            } else { /* add two deltas from table */

                t        = dst[out] + (((table[c * 2] - 128)*3) >> 2);

                t        = av_clip_uint8(t);

                dst[out] = t;

                out++;

                t        = dst[out] + (((table[(c * 2) + 1] - 128)*3) >> 2);

                t        = av_clip_uint8(t);

                dst[out] = t;

                out++;

            }

        }

        dst += pitch;

    }

    return 0;

}

static int initFilter(int16_t **outFilter, int16_t **filterPos, int *outFilterSize, int xInc,

                      int srcW, int dstW, int filterAlign, int one, int flags, int cpu_flags,

                      SwsVector *srcFilter, SwsVector *dstFilter, double param[2])

{

    int i;

    int filterSize;

    int filter2Size;

    int minFilterSize;

    int64_t *filter=NULL;

    int64_t *filter2=NULL;

    const int64_t fone= 1LL<<54;

    int ret= -1;



    emms_c(); //FIXME this should not be required but it IS (even for non-MMX versions)



    // NOTE: the +3 is for the MMX(+1)/SSE(+3) scaler which reads over the end

    FF_ALLOC_OR_GOTO(NULL, *filterPos, (dstW+3)*sizeof(int16_t), fail);



    if (FFABS(xInc - 0x10000) <10) { // unscaled

        int i;

        filterSize= 1;

        FF_ALLOCZ_OR_GOTO(NULL, filter, dstW*sizeof(*filter)*filterSize, fail);



        for (i=0; i<dstW; i++) {

            filter[i*filterSize]= fone;

            (*filterPos)[i]=i;

        }



    } else if (flags&SWS_POINT) { // lame looking point sampling mode

        int i;

        int xDstInSrc;

        filterSize= 1;

        FF_ALLOC_OR_GOTO(NULL, filter, dstW*sizeof(*filter)*filterSize, fail);



        xDstInSrc= xInc/2 - 0x8000;

        for (i=0; i<dstW; i++) {

            int xx= (xDstInSrc - ((filterSize-1)<<15) + (1<<15))>>16;



            (*filterPos)[i]= xx;

            filter[i]= fone;

            xDstInSrc+= xInc;

        }

    } else if ((xInc <= (1<<16) && (flags&SWS_AREA)) || (flags&SWS_FAST_BILINEAR)) { // bilinear upscale

        int i;

        int xDstInSrc;

        filterSize= 2;

        FF_ALLOC_OR_GOTO(NULL, filter, dstW*sizeof(*filter)*filterSize, fail);



        xDstInSrc= xInc/2 - 0x8000;

        for (i=0; i<dstW; i++) {

            int xx= (xDstInSrc - ((filterSize-1)<<15) + (1<<15))>>16;

            int j;



            (*filterPos)[i]= xx;

            //bilinear upscale / linear interpolate / area averaging

            for (j=0; j<filterSize; j++) {

                int64_t coeff= fone - FFABS((xx<<16) - xDstInSrc)*(fone>>16);

                if (coeff<0) coeff=0;

                filter[i*filterSize + j]= coeff;

                xx++;

            }

            xDstInSrc+= xInc;

        }

    } else {

        int xDstInSrc;

        int sizeFactor;



        if      (flags&SWS_BICUBIC)      sizeFactor=  4;

        else if (flags&SWS_X)            sizeFactor=  8;

        else if (flags&SWS_AREA)         sizeFactor=  1; //downscale only, for upscale it is bilinear

        else if (flags&SWS_GAUSS)        sizeFactor=  8;   // infinite ;)

        else if (flags&SWS_LANCZOS)      sizeFactor= param[0] != SWS_PARAM_DEFAULT ? ceil(2*param[0]) : 6;

        else if (flags&SWS_SINC)         sizeFactor= 20; // infinite ;)

        else if (flags&SWS_SPLINE)       sizeFactor= 20;  // infinite ;)

        else if (flags&SWS_BILINEAR)     sizeFactor=  2;

        else {

            sizeFactor= 0; //GCC warning killer

            assert(0);

        }



        if (xInc <= 1<<16)      filterSize= 1 + sizeFactor; // upscale

        else                    filterSize= 1 + (sizeFactor*srcW + dstW - 1)/ dstW;



        if (filterSize > srcW-2) filterSize=srcW-2;



        FF_ALLOC_OR_GOTO(NULL, filter, dstW*sizeof(*filter)*filterSize, fail);



        xDstInSrc= xInc - 0x10000;

        for (i=0; i<dstW; i++) {

            int xx= (xDstInSrc - ((filterSize-2)<<16)) / (1<<17);

            int j;

            (*filterPos)[i]= xx;

            for (j=0; j<filterSize; j++) {

                int64_t d= ((int64_t)FFABS((xx<<17) - xDstInSrc))<<13;

                double floatd;

                int64_t coeff;



                if (xInc > 1<<16)

                    d= d*dstW/srcW;

                floatd= d * (1.0/(1<<30));



                if (flags & SWS_BICUBIC) {

                    int64_t B= (param[0] != SWS_PARAM_DEFAULT ? param[0] :   0) * (1<<24);

                    int64_t C= (param[1] != SWS_PARAM_DEFAULT ? param[1] : 0.6) * (1<<24);



                    if (d >= 1LL<<31) {

                        coeff = 0.0;

                    } else {

                        int64_t dd  = (d  * d) >> 30;

                        int64_t ddd = (dd * d) >> 30;



                        if (d < 1LL<<30)

                            coeff = (12*(1<<24)-9*B-6*C)*ddd + (-18*(1<<24)+12*B+6*C)*dd + (6*(1<<24)-2*B)*(1<<30);

                        else

                            coeff = (-B-6*C)*ddd + (6*B+30*C)*dd + (-12*B-48*C)*d + (8*B+24*C)*(1<<30);

                    }

                    coeff *= fone>>(30+24);

                }

/*                else if (flags & SWS_X) {

                    double p= param ? param*0.01 : 0.3;

                    coeff = d ? sin(d*M_PI)/(d*M_PI) : 1.0;

                    coeff*= pow(2.0, - p*d*d);

                }*/

                else if (flags & SWS_X) {

                    double A= param[0] != SWS_PARAM_DEFAULT ? param[0] : 1.0;

                    double c;



                    if (floatd<1.0)

                        c = cos(floatd*M_PI);

                    else

                        c=-1.0;

                    if (c<0.0)      c= -pow(-c, A);

                    else            c=  pow( c, A);

                    coeff= (c*0.5 + 0.5)*fone;

                } else if (flags & SWS_AREA) {

                    int64_t d2= d - (1<<29);

                    if      (d2*xInc < -(1LL<<(29+16))) coeff= 1.0 * (1LL<<(30+16));

                    else if (d2*xInc <  (1LL<<(29+16))) coeff= -d2*xInc + (1LL<<(29+16));

                    else coeff=0.0;

                    coeff *= fone>>(30+16);

                } else if (flags & SWS_GAUSS) {

                    double p= param[0] != SWS_PARAM_DEFAULT ? param[0] : 3.0;

                    coeff = (pow(2.0, - p*floatd*floatd))*fone;

                } else if (flags & SWS_SINC) {

                    coeff = (d ? sin(floatd*M_PI)/(floatd*M_PI) : 1.0)*fone;

                } else if (flags & SWS_LANCZOS) {

                    double p= param[0] != SWS_PARAM_DEFAULT ? param[0] : 3.0;

                    coeff = (d ? sin(floatd*M_PI)*sin(floatd*M_PI/p)/(floatd*floatd*M_PI*M_PI/p) : 1.0)*fone;

                    if (floatd>p) coeff=0;

                } else if (flags & SWS_BILINEAR) {

                    coeff= (1<<30) - d;

                    if (coeff<0) coeff=0;

                    coeff *= fone >> 30;

                } else if (flags & SWS_SPLINE) {

                    double p=-2.196152422706632;

                    coeff = getSplineCoeff(1.0, 0.0, p, -p-1.0, floatd) * fone;

                } else {

                    coeff= 0.0; //GCC warning killer

                    assert(0);

                }



                filter[i*filterSize + j]= coeff;

                xx++;

            }

            xDstInSrc+= 2*xInc;

        }

    }



    /* apply src & dst Filter to filter -> filter2

       av_free(filter);

    */

    assert(filterSize>0);

    filter2Size= filterSize;

    if (srcFilter) filter2Size+= srcFilter->length - 1;

    if (dstFilter) filter2Size+= dstFilter->length - 1;

    assert(filter2Size>0);

    FF_ALLOCZ_OR_GOTO(NULL, filter2, filter2Size*dstW*sizeof(*filter2), fail);



    for (i=0; i<dstW; i++) {

        int j, k;



        if(srcFilter) {

            for (k=0; k<srcFilter->length; k++) {

                for (j=0; j<filterSize; j++)

                    filter2[i*filter2Size + k + j] += srcFilter->coeff[k]*filter[i*filterSize + j];

            }

        } else {

            for (j=0; j<filterSize; j++)

                filter2[i*filter2Size + j]= filter[i*filterSize + j];

        }

        //FIXME dstFilter



        (*filterPos)[i]+= (filterSize-1)/2 - (filter2Size-1)/2;

    }

    av_freep(&filter);



    /* try to reduce the filter-size (step1 find size and shift left) */

    // Assume it is near normalized (*0.5 or *2.0 is OK but * 0.001 is not).

    minFilterSize= 0;

    for (i=dstW-1; i>=0; i--) {

        int min= filter2Size;

        int j;

        int64_t cutOff=0.0;



        /* get rid of near zero elements on the left by shifting left */

        for (j=0; j<filter2Size; j++) {

            int k;

            cutOff += FFABS(filter2[i*filter2Size]);



            if (cutOff > SWS_MAX_REDUCE_CUTOFF*fone) break;



            /* preserve monotonicity because the core can't handle the filter otherwise */

            if (i<dstW-1 && (*filterPos)[i] >= (*filterPos)[i+1]) break;



            // move filter coefficients left

            for (k=1; k<filter2Size; k++)

                filter2[i*filter2Size + k - 1]= filter2[i*filter2Size + k];

            filter2[i*filter2Size + k - 1]= 0;

            (*filterPos)[i]++;

        }



        cutOff=0;

        /* count near zeros on the right */

        for (j=filter2Size-1; j>0; j--) {

            cutOff += FFABS(filter2[i*filter2Size + j]);



            if (cutOff > SWS_MAX_REDUCE_CUTOFF*fone) break;

            min--;

        }



        if (min>minFilterSize) minFilterSize= min;

    }



    if (HAVE_ALTIVEC && cpu_flags & AV_CPU_FLAG_ALTIVEC) {

        // we can handle the special case 4,

        // so we don't want to go to the full 8

        if (minFilterSize < 5)

            filterAlign = 4;



        // We really don't want to waste our time

        // doing useless computation, so fall back on

        // the scalar C code for very small filters.

        // Vectorizing is worth it only if you have a

        // decent-sized vector.

        if (minFilterSize < 3)

            filterAlign = 1;

    }



    if (HAVE_MMX && cpu_flags & AV_CPU_FLAG_MMX) {

        // special case for unscaled vertical filtering

        if (minFilterSize == 1 && filterAlign == 2)

            filterAlign= 1;

    }



    assert(minFilterSize > 0);

    filterSize= (minFilterSize +(filterAlign-1)) & (~(filterAlign-1));

    assert(filterSize > 0);

    filter= av_malloc(filterSize*dstW*sizeof(*filter));

    if (filterSize >= MAX_FILTER_SIZE*16/((flags&SWS_ACCURATE_RND) ? APCK_SIZE : 16) || !filter)

        goto fail;

    *outFilterSize= filterSize;



    if (flags&SWS_PRINT_INFO)

        av_log(NULL, AV_LOG_VERBOSE, "SwScaler: reducing / aligning filtersize %d -> %d\n", filter2Size, filterSize);

    /* try to reduce the filter-size (step2 reduce it) */

    for (i=0; i<dstW; i++) {

        int j;



        for (j=0; j<filterSize; j++) {

            if (j>=filter2Size) filter[i*filterSize + j]= 0;

            else               filter[i*filterSize + j]= filter2[i*filter2Size + j];

            if((flags & SWS_BITEXACT) && j>=minFilterSize)

                filter[i*filterSize + j]= 0;

        }

    }



    //FIXME try to align filterPos if possible



    //fix borders

    for (i=0; i<dstW; i++) {

        int j;

        if ((*filterPos)[i] < 0) {

            // move filter coefficients left to compensate for filterPos

            for (j=1; j<filterSize; j++) {

                int left= FFMAX(j + (*filterPos)[i], 0);

                filter[i*filterSize + left] += filter[i*filterSize + j];

                filter[i*filterSize + j]=0;

            }

            (*filterPos)[i]= 0;

        }



        if ((*filterPos)[i] + filterSize > srcW) {

            int shift= (*filterPos)[i] + filterSize - srcW;

            // move filter coefficients right to compensate for filterPos

            for (j=filterSize-2; j>=0; j--) {

                int right= FFMIN(j + shift, filterSize-1);

                filter[i*filterSize +right] += filter[i*filterSize +j];

                filter[i*filterSize +j]=0;

            }

            (*filterPos)[i]= srcW - filterSize;

        }

    }



    // Note the +1 is for the MMX scaler which reads over the end

    /* align at 16 for AltiVec (needed by hScale_altivec_real) */

    FF_ALLOCZ_OR_GOTO(NULL, *outFilter, *outFilterSize*(dstW+3)*sizeof(int16_t), fail);



    /* normalize & store in outFilter */

    for (i=0; i<dstW; i++) {

        int j;

        int64_t error=0;

        int64_t sum=0;



        for (j=0; j<filterSize; j++) {

            sum+= filter[i*filterSize + j];

        }

        sum= (sum + one/2)/ one;

        for (j=0; j<*outFilterSize; j++) {

            int64_t v= filter[i*filterSize + j] + error;

            int intV= ROUNDED_DIV(v, sum);

            (*outFilter)[i*(*outFilterSize) + j]= intV;

            error= v - intV*sum;

        }

    }



    (*filterPos)[dstW+0] =

    (*filterPos)[dstW+1] =

    (*filterPos)[dstW+2] = (*filterPos)[dstW-1]; // the MMX/SSE scaler will read over the end

    for (i=0; i<*outFilterSize; i++) {

        int k= (dstW - 1) * (*outFilterSize) + i;

        (*outFilter)[k + 1 * (*outFilterSize)] =

        (*outFilter)[k + 2 * (*outFilterSize)] =

        (*outFilter)[k + 3 * (*outFilterSize)] = (*outFilter)[k];

    }



    ret=0;

fail:

    av_free(filter);

    av_free(filter2);

    return ret;

}

int update_dimensions(VP8Context *s, int width, int height, int is_vp7)

{

    AVCodecContext *avctx = s->avctx;

    int i, ret;



    if (width  != s->avctx->width ||

        height != s->avctx->height) {

        vp8_decode_flush_impl(s->avctx, 1);



        ret = ff_set_dimensions(s->avctx, width, height);

        if (ret < 0)

            return ret;

    }



    s->mb_width  = (s->avctx->coded_width  + 15) / 16;

    s->mb_height = (s->avctx->coded_height + 15) / 16;



    s->mb_layout = is_vp7 || avctx->active_thread_type == FF_THREAD_SLICE &&

                   FFMIN(s->num_coeff_partitions, avctx->thread_count) > 1;

    if (!s->mb_layout) { // Frame threading and one thread

        s->macroblocks_base       = av_mallocz((s->mb_width + s->mb_height * 2 + 1) *

                                               sizeof(*s->macroblocks));

        s->intra4x4_pred_mode_top = av_mallocz(s->mb_width * 4);

    } else // Sliced threading

        s->macroblocks_base = av_mallocz((s->mb_width + 2) * (s->mb_height + 2) *

                                         sizeof(*s->macroblocks));

    s->top_nnz     = av_mallocz(s->mb_width * sizeof(*s->top_nnz));

    s->top_border  = av_mallocz((s->mb_width + 1) * sizeof(*s->top_border));

    s->thread_data = av_mallocz(MAX_THREADS * sizeof(VP8ThreadData));



    for (i = 0; i < MAX_THREADS; i++) {

        s->thread_data[i].filter_strength =

            av_mallocz(s->mb_width * sizeof(*s->thread_data[0].filter_strength));

#if HAVE_THREADS

        pthread_mutex_init(&s->thread_data[i].lock, NULL);

        pthread_cond_init(&s->thread_data[i].cond, NULL);

#endif

    }



    if (!s->macroblocks_base || !s->top_nnz || !s->top_border ||

        (!s->intra4x4_pred_mode_top && !s->mb_layout))

        return AVERROR(ENOMEM);



    s->macroblocks = s->macroblocks_base + 1;



    return 0;

}

static int decode_main_header(NUTContext *nut){

    AVFormatContext *s= nut->avf;

    ByteIOContext *bc = &s->pb;

    uint64_t tmp;

    int i, j;



    get_packetheader(nut, bc, 8, 1);



    tmp = get_v(bc);

    if (tmp != 1){

	av_log(s, AV_LOG_ERROR, "bad version (%Ld)\n", tmp);

        return -1;

    }



    nut->stream_count = get_v(bc);

    get_v(bc); //checksum threshold



    for(i=0; i<256;){

        int tmp_flags = get_v(bc);

        int tmp_stream= get_v(bc);

        int tmp_mul   = get_v(bc);

        int tmp_size  = get_v(bc);

        int count     = get_v(bc);



        if(count == 0 || i+count > 256){

            av_log(s, AV_LOG_ERROR, "illegal count %d at %d\n", count, i);

            return -1;

        }



        if((tmp_flags & FLAG_FRAME_TYPE) && tmp_flags != 1){

            if(tmp_flags & FLAG_PRED_KEY_FRAME){

                av_log(s, AV_LOG_ERROR, "keyframe prediction in non 0 frame type\n");

                return -1;

            }

            if(!(tmp_flags & FLAG_PTS) || !(tmp_flags & FLAG_FULL_PTS) ){

                av_log(s, AV_LOG_ERROR, "no full pts in non 0 frame type\n");

                return -1;

            }

        }



        for(j=0; j<count; j++,i++){

            if(tmp_stream > nut->stream_count + 1){

                av_log(s, AV_LOG_ERROR, "illegal stream number\n");

                return -1;

            }



            nut->frame_code[i].flags           = tmp_flags ;

            nut->frame_code[i].stream_id_plus1 = tmp_stream;

            nut->frame_code[i].size_mul        = tmp_mul   ;

            nut->frame_code[i].size_lsb        = tmp_size  ;

            if(++tmp_size >= tmp_mul){

                tmp_size=0;

                tmp_stream++;

            }

        }

    }

    if(nut->frame_code['N'].flags != 1){

        av_log(s, AV_LOG_ERROR, "illegal frame_code table\n");

        return -1;

    }



    if(check_checksum(bc)){

        av_log(s, AV_LOG_ERROR, "Main header checksum missmatch\n");

        return -1;

    }



    return 0;

}

void av_dynarray_add(void *tab_ptr, int *nb_ptr, void *elem)

{

    /* see similar ffmpeg.c:grow_array() */

    int nb, nb_alloc;

    intptr_t *tab;



    nb = *nb_ptr;

    tab = *(intptr_t**)tab_ptr;

    if ((nb & (nb - 1)) == 0) {

        if (nb == 0)

            nb_alloc = 1;

        else

            nb_alloc = nb * 2;

        tab = av_realloc(tab, nb_alloc * sizeof(intptr_t));

        *(intptr_t**)tab_ptr = tab;

    }

    tab[nb++] = (intptr_t)elem;

    *nb_ptr = nb;

}

static void write_long(unsigned char *p,uint32_t v)

{

	p[0] = v>>24;

	p[1] = v>>16;

	p[2] = v>>8;

	p[3] = v;

}

static void filter_edges_16bit(void *dst1, void *prev1, void *cur1, void *next1,

                               int w, int prefs, int mrefs, int parity, int mode)

{

    uint16_t *dst  = dst1;

    uint16_t *prev = prev1;

    uint16_t *cur  = cur1;

    uint16_t *next = next1;

    int x;

    uint16_t *prev2 = parity ? prev : cur ;

    uint16_t *next2 = parity ? cur  : next;

    mrefs /= 2;

    prefs /= 2;



    FILTER(0, 3, 0)



    dst   = (uint16_t*)dst1  + w - 3;

    prev  = (uint16_t*)prev1 + w - 3;

    cur   = (uint16_t*)cur1  + w - 3;

    next  = (uint16_t*)next1 + w - 3;

    prev2 = (uint16_t*)(parity ? prev : cur);

    next2 = (uint16_t*)(parity ? cur  : next);



    FILTER(w - 3, w, 0)

}

static int avi_load_index(AVFormatContext *s)

{

    AVIContext *avi = s->priv_data;

    ByteIOContext *pb = s->pb;

    uint32_t tag, size;

    int64_t pos= url_ftell(pb);



    url_fseek(pb, avi->movi_end, SEEK_SET);

#ifdef DEBUG_SEEK

    printf("movi_end=0x%"PRIx64"\n", avi->movi_end);

#endif

    for(;;) {

        if (url_feof(pb))

            break;

        tag = get_le32(pb);

        size = get_le32(pb);

#ifdef DEBUG_SEEK

        printf("tag=%c%c%c%c size=0x%x\n",

               tag & 0xff,

               (tag >> 8) & 0xff,

               (tag >> 16) & 0xff,

               (tag >> 24) & 0xff,

               size);

#endif

        switch(tag) {

        case MKTAG('i', 'd', 'x', '1'):

            if (avi_read_idx1(s, size) < 0)

                goto skip;

            else

                goto the_end;

            break;

        default:

        skip:

            size += (size & 1);

            url_fskip(pb, size);

            break;

        }

    }

 the_end:

    url_fseek(pb, pos, SEEK_SET);

    return 0;

}

static char *get_content_url(xmlNodePtr *baseurl_nodes,

                             int n_baseurl_nodes,

                             char *rep_id_val,

                             char *rep_bandwidth_val,

                             char *val)

{

    int i;

    char *text;

    char *url = NULL;

    char tmp_str[MAX_URL_SIZE];

    char tmp_str_2[MAX_URL_SIZE];



    memset(tmp_str, 0, sizeof(tmp_str));



    for (i = 0; i < n_baseurl_nodes; ++i) {

        if (baseurl_nodes[i] &&

            baseurl_nodes[i]->children &&

            baseurl_nodes[i]->children->type == XML_TEXT_NODE) {

            text = xmlNodeGetContent(baseurl_nodes[i]->children);

            if (text) {

                memset(tmp_str, 0, sizeof(tmp_str));

                memset(tmp_str_2, 0, sizeof(tmp_str_2));

                ff_make_absolute_url(tmp_str_2, MAX_URL_SIZE, tmp_str, text);

                av_strlcpy(tmp_str, tmp_str_2, sizeof(tmp_str));

                xmlFree(text);

            }

        }

    }



    if (val)

        av_strlcat(tmp_str, (const char*)val, sizeof(tmp_str));



    if (rep_id_val) {

        url = av_strireplace(tmp_str, "$RepresentationID$", (const char*)rep_id_val);

        if (!url) {

            return NULL;

        }

        av_strlcpy(tmp_str, url, sizeof(tmp_str));

        av_free(url);

    }

    if (rep_bandwidth_val && tmp_str[0] != '\0') {

        url = av_strireplace(tmp_str, "$Bandwidth$", (const char*)rep_bandwidth_val);

        if (!url) {

            return NULL;

        }

    }

    return url;

}

av_cold void ff_idctdsp_init(IDCTDSPContext *c, AVCodecContext *avctx)

{

    const unsigned high_bit_depth = avctx->bits_per_raw_sample > 8;



    if (avctx->lowres==1) {

        c->idct_put  = ff_jref_idct4_put;

        c->idct_add  = ff_jref_idct4_add;

        c->idct      = ff_j_rev_dct4;

        c->perm_type = FF_IDCT_PERM_NONE;

    } else if (avctx->lowres==2) {

        c->idct_put  = ff_jref_idct2_put;

        c->idct_add  = ff_jref_idct2_add;

        c->idct      = ff_j_rev_dct2;

        c->perm_type = FF_IDCT_PERM_NONE;

    } else if (avctx->lowres==3) {

        c->idct_put  = ff_jref_idct1_put;

        c->idct_add  = ff_jref_idct1_add;

        c->idct      = ff_j_rev_dct1;

        c->perm_type = FF_IDCT_PERM_NONE;

    } else {

        if (avctx->bits_per_raw_sample == 10 || avctx->bits_per_raw_sample == 9) {

            c->idct_put              = ff_simple_idct_put_10;

            c->idct_add              = ff_simple_idct_add_10;

            c->idct                  = ff_simple_idct_10;

            c->perm_type             = FF_IDCT_PERM_NONE;

        } else if (avctx->bits_per_raw_sample == 12) {

            c->idct_put              = ff_simple_idct_put_12;

            c->idct_add              = ff_simple_idct_add_12;

            c->idct                  = ff_simple_idct_12;

            c->perm_type             = FF_IDCT_PERM_NONE;

        } else {

            if (avctx->idct_algo == FF_IDCT_INT) {

                c->idct_put  = ff_jref_idct_put;

                c->idct_add  = ff_jref_idct_add;

                c->idct      = ff_j_rev_dct;

                c->perm_type = FF_IDCT_PERM_LIBMPEG2;

#if CONFIG_FAANIDCT

            } else if (avctx->idct_algo == FF_IDCT_FAAN) {

                c->idct_put  = ff_faanidct_put;

                c->idct_add  = ff_faanidct_add;

                c->idct      = ff_faanidct;

                c->perm_type = FF_IDCT_PERM_NONE;

#endif /* CONFIG_FAANIDCT */

            } else { // accurate/default

                c->idct_put  = ff_simple_idct_put_8;

                c->idct_add  = ff_simple_idct_add_8;

                c->idct      = ff_simple_idct_8;

                c->perm_type = FF_IDCT_PERM_NONE;

            }

        }

    }



    c->put_pixels_clamped        = put_pixels_clamped_c;

    c->put_signed_pixels_clamped = put_signed_pixels_clamped_c;

    c->add_pixels_clamped        = add_pixels_clamped_c;



    if (CONFIG_MPEG4_DECODER && avctx->idct_algo == FF_IDCT_XVID)

        ff_xvid_idct_init(c, avctx);



    if (ARCH_AARCH64)

        ff_idctdsp_init_aarch64(c, avctx, high_bit_depth);

    if (ARCH_ALPHA)

        ff_idctdsp_init_alpha(c, avctx, high_bit_depth);

    if (ARCH_ARM)

        ff_idctdsp_init_arm(c, avctx, high_bit_depth);

    if (ARCH_PPC)

        ff_idctdsp_init_ppc(c, avctx, high_bit_depth);

    if (ARCH_X86)

        ff_idctdsp_init_x86(c, avctx, high_bit_depth);

    if (ARCH_MIPS)

        ff_idctdsp_init_mips(c, avctx, high_bit_depth);



    ff_put_pixels_clamped = c->put_pixels_clamped;

    ff_add_pixels_clamped = c->add_pixels_clamped;



    ff_init_scantable_permutation(c->idct_permutation,

                                  c->perm_type);

}

static int get_cod(J2kDecoderContext *s, J2kCodingStyle *c, uint8_t *properties)

{

    J2kCodingStyle tmp;

    int compno;



    if (s->buf_end - s->buf < 5)

        return AVERROR(EINVAL);



    tmp.log2_prec_width  =

    tmp.log2_prec_height = 15;



    tmp.csty = bytestream_get_byte(&s->buf);



    if (bytestream_get_byte(&s->buf)){ // progression level

        av_log(s->avctx, AV_LOG_ERROR, "only LRCP progression supported\n");

        return -1;

    }



    tmp.nlayers = bytestream_get_be16(&s->buf);

        tmp.mct = bytestream_get_byte(&s->buf); // multiple component transformation



    get_cox(s, &tmp);

    for (compno = 0; compno < s->ncomponents; compno++){

        if (!(properties[compno] & HAD_COC))

            memcpy(c + compno, &tmp, sizeof(J2kCodingStyle));

    }

    return 0;

}

static void vc1_mc_1mv(VC1Context *v, int dir)

{

    MpegEncContext *s = &v->s;

    DSPContext *dsp   = &v->s.dsp;

    H264ChromaContext *h264chroma = &v->h264chroma;

    uint8_t *srcY, *srcU, *srcV;

    int dxy, mx, my, uvmx, uvmy, src_x, src_y, uvsrc_x, uvsrc_y;

    int off, off_uv;

    int v_edge_pos = s->v_edge_pos >> v->field_mode;



    if ((!v->field_mode ||

         (v->ref_field_type[dir] == 1 && v->cur_field_type == 1)) &&

        !v->s.last_picture.f.data[0])

        return;



    mx = s->mv[dir][0][0];

    my = s->mv[dir][0][1];



    // store motion vectors for further use in B frames

    if (s->pict_type == AV_PICTURE_TYPE_P) {

        s->current_picture.f.motion_val[1][s->block_index[0] + v->blocks_off][0] = mx;

        s->current_picture.f.motion_val[1][s->block_index[0] + v->blocks_off][1] = my;

    }



    uvmx = (mx + ((mx & 3) == 3)) >> 1;

    uvmy = (my + ((my & 3) == 3)) >> 1;

    v->luma_mv[s->mb_x][0] = uvmx;

    v->luma_mv[s->mb_x][1] = uvmy;



    if (v->field_mode &&

        v->cur_field_type != v->ref_field_type[dir]) {

        my   = my   - 2 + 4 * v->cur_field_type;

        uvmy = uvmy - 2 + 4 * v->cur_field_type;

    }



    // fastuvmc shall be ignored for interlaced frame picture

    if (v->fastuvmc && (v->fcm != ILACE_FRAME)) {

        uvmx = uvmx + ((uvmx < 0) ? (uvmx & 1) : -(uvmx & 1));

        uvmy = uvmy + ((uvmy < 0) ? (uvmy & 1) : -(uvmy & 1));

    }

    if (v->field_mode) { // interlaced field picture

        if (!dir) {

            if ((v->cur_field_type != v->ref_field_type[dir]) && v->second_field) {

                srcY = s->current_picture.f.data[0];

                srcU = s->current_picture.f.data[1];

                srcV = s->current_picture.f.data[2];

            } else {

                srcY = s->last_picture.f.data[0];

                srcU = s->last_picture.f.data[1];

                srcV = s->last_picture.f.data[2];

            }

        } else {

            srcY = s->next_picture.f.data[0];

            srcU = s->next_picture.f.data[1];

            srcV = s->next_picture.f.data[2];

        }

    } else {

        if (!dir) {

            srcY = s->last_picture.f.data[0];

            srcU = s->last_picture.f.data[1];

            srcV = s->last_picture.f.data[2];

        } else {

            srcY = s->next_picture.f.data[0];

            srcU = s->next_picture.f.data[1];

            srcV = s->next_picture.f.data[2];

        }

    }



    if(!srcY)

        return;



    src_x   = s->mb_x * 16 + (mx   >> 2);

    src_y   = s->mb_y * 16 + (my   >> 2);

    uvsrc_x = s->mb_x *  8 + (uvmx >> 2);

    uvsrc_y = s->mb_y *  8 + (uvmy >> 2);



    if (v->profile != PROFILE_ADVANCED) {

        src_x   = av_clip(  src_x, -16, s->mb_width  * 16);

        src_y   = av_clip(  src_y, -16, s->mb_height * 16);

        uvsrc_x = av_clip(uvsrc_x,  -8, s->mb_width  *  8);

        uvsrc_y = av_clip(uvsrc_y,  -8, s->mb_height *  8);

    } else {

        src_x   = av_clip(  src_x, -17, s->avctx->coded_width);

        src_y   = av_clip(  src_y, -18, s->avctx->coded_height + 1);

        uvsrc_x = av_clip(uvsrc_x,  -8, s->avctx->coded_width  >> 1);

        uvsrc_y = av_clip(uvsrc_y,  -8, s->avctx->coded_height >> 1);

    }



    srcY += src_y   * s->linesize   + src_x;

    srcU += uvsrc_y * s->uvlinesize + uvsrc_x;

    srcV += uvsrc_y * s->uvlinesize + uvsrc_x;



    if (v->field_mode && v->ref_field_type[dir]) {

        srcY += s->current_picture_ptr->f.linesize[0];

        srcU += s->current_picture_ptr->f.linesize[1];

        srcV += s->current_picture_ptr->f.linesize[2];

    }



    /* for grayscale we should not try to read from unknown area */

    if (s->flags & CODEC_FLAG_GRAY) {

        srcU = s->edge_emu_buffer + 18 * s->linesize;

        srcV = s->edge_emu_buffer + 18 * s->linesize;

    }



    if (v->rangeredfrm || (v->mv_mode == MV_PMODE_INTENSITY_COMP)

        || s->h_edge_pos < 22 || v_edge_pos < 22

        || (unsigned)(src_x - s->mspel) > s->h_edge_pos - (mx&3) - 16 - s->mspel * 3

        || (unsigned)(src_y - 1)        > v_edge_pos    - (my&3) - 16 - 3) {

        uint8_t *uvbuf = s->edge_emu_buffer + 19 * s->linesize;



        srcY -= s->mspel * (1 + s->linesize);

        s->vdsp.emulated_edge_mc(s->edge_emu_buffer, srcY, s->linesize,

                                 17 + s->mspel * 2, 17 + s->mspel * 2,

                                 src_x - s->mspel, src_y - s->mspel,

                                 s->h_edge_pos, v_edge_pos);

        srcY = s->edge_emu_buffer;

        s->vdsp.emulated_edge_mc(uvbuf     , srcU, s->uvlinesize, 8 + 1, 8 + 1,

                                 uvsrc_x, uvsrc_y, s->h_edge_pos >> 1, v_edge_pos >> 1);

        s->vdsp.emulated_edge_mc(uvbuf + 16, srcV, s->uvlinesize, 8 + 1, 8 + 1,

                                 uvsrc_x, uvsrc_y, s->h_edge_pos >> 1, v_edge_pos >> 1);

        srcU = uvbuf;

        srcV = uvbuf + 16;

        /* if we deal with range reduction we need to scale source blocks */

        if (v->rangeredfrm) {

            int i, j;

            uint8_t *src, *src2;



            src = srcY;

            for (j = 0; j < 17 + s->mspel * 2; j++) {

                for (i = 0; i < 17 + s->mspel * 2; i++)

                    src[i] = ((src[i] - 128) >> 1) + 128;

                src += s->linesize;

            }

            src  = srcU;

            src2 = srcV;

            for (j = 0; j < 9; j++) {

                for (i = 0; i < 9; i++) {

                    src[i]  = ((src[i]  - 128) >> 1) + 128;

                    src2[i] = ((src2[i] - 128) >> 1) + 128;

                }

                src  += s->uvlinesize;

                src2 += s->uvlinesize;

            }

        }

        /* if we deal with intensity compensation we need to scale source blocks */

        if (v->mv_mode == MV_PMODE_INTENSITY_COMP) {

            int i, j;

            uint8_t *src, *src2;



            src = srcY;

            for (j = 0; j < 17 + s->mspel * 2; j++) {

                for (i = 0; i < 17 + s->mspel * 2; i++)

                    src[i] = v->luty[src[i]];

                src += s->linesize;

            }

            src  = srcU;

            src2 = srcV;

            for (j = 0; j < 9; j++) {

                for (i = 0; i < 9; i++) {

                    src[i]  = v->lutuv[src[i]];

                    src2[i] = v->lutuv[src2[i]];

                }

                src  += s->uvlinesize;

                src2 += s->uvlinesize;

            }

        }

        srcY += s->mspel * (1 + s->linesize);

    }



    if (v->field_mode && v->second_field) {

        off    = s->current_picture_ptr->f.linesize[0];

        off_uv = s->current_picture_ptr->f.linesize[1];

    } else {

        off    = 0;

        off_uv = 0;

    }

    if (s->mspel) {

        dxy = ((my & 3) << 2) | (mx & 3);

        v->vc1dsp.put_vc1_mspel_pixels_tab[dxy](s->dest[0] + off    , srcY    , s->linesize, v->rnd);

        v->vc1dsp.put_vc1_mspel_pixels_tab[dxy](s->dest[0] + off + 8, srcY + 8, s->linesize, v->rnd);

        srcY += s->linesize * 8;

        v->vc1dsp.put_vc1_mspel_pixels_tab[dxy](s->dest[0] + off + 8 * s->linesize    , srcY    , s->linesize, v->rnd);

        v->vc1dsp.put_vc1_mspel_pixels_tab[dxy](s->dest[0] + off + 8 * s->linesize + 8, srcY + 8, s->linesize, v->rnd);

    } else { // hpel mc - always used for luma

        dxy = (my & 2) | ((mx & 2) >> 1);

        if (!v->rnd)

            dsp->put_pixels_tab[0][dxy](s->dest[0] + off, srcY, s->linesize, 16);

        else

            dsp->put_no_rnd_pixels_tab[0][dxy](s->dest[0] + off, srcY, s->linesize, 16);

    }



    if (s->flags & CODEC_FLAG_GRAY) return;

    /* Chroma MC always uses qpel bilinear */

    uvmx = (uvmx & 3) << 1;

    uvmy = (uvmy & 3) << 1;

    if (!v->rnd) {

        h264chroma->put_h264_chroma_pixels_tab[0](s->dest[1] + off_uv, srcU, s->uvlinesize, 8, uvmx, uvmy);

        h264chroma->put_h264_chroma_pixels_tab[0](s->dest[2] + off_uv, srcV, s->uvlinesize, 8, uvmx, uvmy);

    } else {

        v->vc1dsp.put_no_rnd_vc1_chroma_pixels_tab[0](s->dest[1] + off_uv, srcU, s->uvlinesize, 8, uvmx, uvmy);

        v->vc1dsp.put_no_rnd_vc1_chroma_pixels_tab[0](s->dest[2] + off_uv, srcV, s->uvlinesize, 8, uvmx, uvmy);

    }

}

static void decode_mb(MadContext *t, int inter)

{

    MpegEncContext *s = &t->s;

    int mv_map = 0;

    int mv_x, mv_y;

    int j;



    if (inter) {

        int v = decode210(&s->gb);

        if (v < 2) {

            mv_map = v ? get_bits(&s->gb, 6) : 63;

            mv_x = decode_motion(&s->gb);

            mv_y = decode_motion(&s->gb);

        } else {

            mv_map = 0;

        }

    }



    for (j=0; j<6; j++) {

        if (mv_map & (1<<j)) {  // mv_x and mv_y are guarded by mv_map

            int add = 2*decode_motion(&s->gb);

            if (t->last_frame.data[0])

                comp_block(t, s->mb_x, s->mb_y, j, mv_x, mv_y, add);

        } else {

            s->dsp.clear_block(t->block);

            decode_block_intra(t, t->block);

            idct_put(t, t->block, s->mb_x, s->mb_y, j);

        }

    }

}

static void envelope_instant16(WaveformContext *s, AVFrame *out, int plane, int component)

{

    const int dst_linesize = out->linesize[component] / 2;

    const int bg = s->bg_color[component] * (s->size / 256);

    const int limit = s->size - 1;

    const int is_chroma = (component == 1 || component == 2);

    const int shift_w = (is_chroma ? s->desc->log2_chroma_w : 0);

    const int shift_h = (is_chroma ? s->desc->log2_chroma_h : 0);

    const int dst_h = FF_CEIL_RSHIFT(out->height, shift_h);

    const int dst_w = FF_CEIL_RSHIFT(out->width, shift_w);

    const int start = s->estart[plane];

    const int end = s->eend[plane];

    uint16_t *dst;

    int x, y;



    if (s->mode) {

        for (x = 0; x < dst_w; x++) {

            for (y = start; y < end; y++) {

                dst = (uint16_t *)out->data[component] + y * dst_linesize + x;

                if (dst[0] != bg) {

                    dst[0] = limit;

                    break;

                }

            }

            for (y = end - 1; y >= start; y--) {

                dst = (uint16_t *)out->data[component] + y * dst_linesize + x;

                if (dst[0] != bg) {

                    dst[0] = limit;

                    break;

                }

            }

        }

    } else {

        for (y = 0; y < dst_h; y++) {

            dst = (uint16_t *)out->data[component] + y * dst_linesize;

            for (x = start; x < end; x++) {

                if (dst[x] != bg) {

                    dst[x] = limit;

                    break;

                }

            }

            for (x = end - 1; x >= start; x--) {

                if (dst[x] != bg) {

                    dst[x] = limit;

                    break;

                }

            }

        }

    }

}

static int advanced_decode_picture_header(VC9Context *v)

{

    static const int type_table[4] = { P_TYPE, B_TYPE, I_TYPE, BI_TYPE };

    int type, i, ret;



    if (v->interlace)

    {

        v->fcm = get_bits(&v->gb, 1);

        if (v->fcm) v->fcm = 2+get_bits(&v->gb, 1);

    }



    type = get_prefix(&v->gb, 0, 4);

    if (type > 4 || type < 0) return FRAME_SKIPED;

    v->pict_type = type_table[type];

    av_log(v->avctx, AV_LOG_INFO, "AP Frame Type: %i\n", v->pict_type);



    if (v->tfcntrflag) v->tfcntr = get_bits(&v->gb, 8);

    if (v->broadcast)

    {

        if (!v->interlace) v->rptfrm = get_bits(&v->gb, 2);

        else

        {

            v->tff = get_bits(&v->gb, 1);

            v->rff = get_bits(&v->gb, 1);

        }

    }



    if (v->panscanflag)

    {

#if 0

        for (i=0; i<v->numpanscanwin; i++)

        {

            v->topleftx[i] = get_bits(&v->gb, 16);

            v->toplefty[i] = get_bits(&v->gb, 16);

            v->bottomrightx[i] = get_bits(&v->gb, 16);

            v->bottomrighty[i] = get_bits(&v->gb, 16);

        }

#else

        skip_bits(&v->gb, 16*4*v->numpanscanwin);

#endif

    }

    v->rndctrl = get_bits(&v->gb, 1);

    v->uvsamp = get_bits(&v->gb, 1);

    if (v->finterpflag == 1) v->interpfrm = get_bits(&v->gb, 1);



    switch(v->pict_type)

    {

    case I_TYPE: if (decode_i_picture_header(v) < 0) return -1;

    case P_TYPE: if (decode_p_picture_header(v) < 0) return -1;

    case BI_TYPE:

    case B_TYPE: if (decode_b_picture_header(v) < 0) return FRAME_SKIPED;

    default: break;

    }



    /* AC/DC Syntax */

    v->transacfrm = get_bits(&v->gb, 1);

    if (v->transacfrm) v->transacfrm += get_bits(&v->gb, 1);

    if (v->pict_type == I_TYPE || v->pict_type == BI_TYPE)

    {

        v->transacfrm2 = get_bits(&v->gb, 1);

        if (v->transacfrm2) v->transacfrm2 += get_bits(&v->gb, 1);

    }

    v->transacdctab = get_bits(&v->gb, 1);

    if (v->pict_type == I_TYPE) vop_dquant_decoding(v);



    return 0;

}

static void dss_sp_unpack_coeffs(DssSpContext *p, const uint8_t *src)

{

    GetBitContext gb;

    DssSpFrame *fparam = &p->fparam;

    int i;

    int subframe_idx;

    uint32_t combined_pitch;

    uint32_t tmp;

    uint32_t pitch_lag;



    for (i = 0; i < DSS_SP_FRAME_SIZE; i += 2) {

        p->bits[i]     = src[i + 1];

        p->bits[i + 1] = src[i];

    }



    init_get_bits(&gb, p->bits, DSS_SP_FRAME_SIZE * 8);



    for (i = 0; i < 2; i++)

        fparam->filter_idx[i] = get_bits(&gb, 5);

    for (; i < 8; i++)

        fparam->filter_idx[i] = get_bits(&gb, 4);

    for (; i < 14; i++)

        fparam->filter_idx[i] = get_bits(&gb, 3);



    for (subframe_idx = 0; subframe_idx < 4; subframe_idx++) {

        fparam->sf_adaptive_gain[subframe_idx] = get_bits(&gb, 5);



        fparam->sf[subframe_idx].combined_pulse_pos = get_bits_long(&gb, 31);



        fparam->sf[subframe_idx].gain = get_bits(&gb, 6);



        for (i = 0; i < 7; i++)

            fparam->sf[subframe_idx].pulse_val[i] = get_bits(&gb, 3);

    }



    for (subframe_idx = 0; subframe_idx < 4; subframe_idx++) {

        unsigned int C72_binomials[PULSE_MAX] = {

            72, 2556, 59640, 1028790, 13991544, 156238908, 1473109704,

            3379081753

        };

        unsigned int combined_pulse_pos =

            fparam->sf[subframe_idx].combined_pulse_pos;

        int index = 6;



        if (combined_pulse_pos < C72_binomials[PULSE_MAX - 1]) {

            if (p->pulse_dec_mode) {

                int pulse, pulse_idx;

                pulse              = PULSE_MAX - 1;

                pulse_idx          = 71;

                combined_pulse_pos =

                    fparam->sf[subframe_idx].combined_pulse_pos;



                /* this part seems to be close to g723.1 gen_fcb_excitation()

                 * RATE_6300 */



                /* TODO: what is 7? size of subframe? */

                for (i = 0; i < 7; i++) {

                    for (;

                         combined_pulse_pos <

                         dss_sp_combinatorial_table[pulse][pulse_idx];

                         --pulse_idx)

                        ;

                    combined_pulse_pos -=

                        dss_sp_combinatorial_table[pulse][pulse_idx];

                    pulse--;

                    fparam->sf[subframe_idx].pulse_pos[i] = pulse_idx;

                }

            }

        } else {

            p->pulse_dec_mode = 0;



            /* why do we need this? */

            fparam->sf[subframe_idx].pulse_pos[6] = 0;



            for (i = 71; i >= 0; i--) {

                if (C72_binomials[index] <= combined_pulse_pos) {

                    combined_pulse_pos -= C72_binomials[index];



                    fparam->sf[subframe_idx].pulse_pos[6 - index] = i;



                    if (!index)

                        break;

                    --index;

                }

                --C72_binomials[0];

                if (index) {

                    int a;

                    for (a = 0; a < index; a++)

                        C72_binomials[a + 1] -= C72_binomials[a];

                }

            }

        }

    }



    combined_pitch = get_bits(&gb, 24);



    fparam->pitch_lag[0] = (combined_pitch % 151) + 36;



    combined_pitch /= 151;



    for (i = 1; i < SUBFRAMES; i++) {

        fparam->pitch_lag[i] = combined_pitch % 48;

        combined_pitch      /= 48;

    }



    pitch_lag = fparam->pitch_lag[0];

    for (i = 1; i < SUBFRAMES; i++) {

        if (pitch_lag > 162) {

            fparam->pitch_lag[i] += 162 - 23;

        } else {

            tmp = pitch_lag - 23;

            if (tmp < 36)

                tmp = 36;

            fparam->pitch_lag[i] += tmp;

        }

        pitch_lag = fparam->pitch_lag[i];

    }

}

int av_packet_copy_props(AVPacket *dst, const AVPacket *src)

{

    int i;



    dst->pts                  = src->pts;

    dst->dts                  = src->dts;

    dst->pos                  = src->pos;

    dst->duration             = src->duration;

    dst->convergence_duration = src->convergence_duration;

    dst->flags                = src->flags;

    dst->stream_index         = src->stream_index;

    dst->side_data_elems      = src->side_data_elems;



    for (i = 0; i < src->side_data_elems; i++) {

         enum AVPacketSideDataType type = src->side_data[i].type;

         int size          = src->side_data[i].size;

         uint8_t *src_data = src->side_data[i].data;

         uint8_t *dst_data = av_packet_new_side_data(dst, type, size);



        if (!dst_data) {

            av_packet_free_side_data(dst);

            return AVERROR(ENOMEM);

        }

        memcpy(dst_data, src_data, size);

    }



    return 0;

}

static inline int get_len(LZOContext *c, int x, int mask)

{

    int cnt = x & mask;

    if (!cnt) {

        while (!(x = get_byte(c)))

            cnt += 255;

        cnt += mask + x;

    }

    return cnt;

}

static int dx2_decode_slice_444(GetBitContext *gb, AVFrame *frame,

                                int line, int left,

                                uint8_t lru[3][8])

{

    int x, y;



    int width   = frame->width;



    int ystride = frame->linesize[0];

    int ustride = frame->linesize[1];

    int vstride = frame->linesize[2];



    uint8_t *Y  = frame->data[0] + ystride * line;

    uint8_t *U  = frame->data[1] + ustride * line;

    uint8_t *V  = frame->data[2] + vstride * line;



    for (y = 0; y < left && get_bits_left(gb) > 16; y++) {

        for (x = 0; x < width; x++) {

            Y[x] = decode_sym(gb, lru[0]);

            U[x] = decode_sym(gb, lru[1]) ^ 0x80;

            V[x] = decode_sym(gb, lru[2]) ^ 0x80;

        }



        Y += ystride;

        U += ustride;

        V += vstride;

    }



    return y;

}

static void new_audio_stream(AVFormatContext *oc, int file_idx)

{

    AVStream *st;

    AVOutputStream *ost;

    AVCodec *codec= NULL;

    AVCodecContext *audio_enc;

    enum CodecID codec_id;



    st = av_new_stream(oc, oc->nb_streams < nb_streamid_map ? streamid_map[oc->nb_streams] : 0);

    if (!st) {

        fprintf(stderr, "Could not alloc stream\n");

        ffmpeg_exit(1);

    }

    ost = new_output_stream(oc, file_idx);



    output_codecs = grow_array(output_codecs, sizeof(*output_codecs), &nb_output_codecs, nb_output_codecs + 1);

    if(!audio_stream_copy){

        if (audio_codec_name) {

            codec_id = find_codec_or_die(audio_codec_name, AVMEDIA_TYPE_AUDIO, 1,

                                         avcodec_opts[AVMEDIA_TYPE_AUDIO]->strict_std_compliance);

            codec = avcodec_find_encoder_by_name(audio_codec_name);

            output_codecs[nb_output_codecs-1] = codec;

        } else {

            codec_id = av_guess_codec(oc->oformat, NULL, oc->filename, NULL, AVMEDIA_TYPE_AUDIO);

            codec = avcodec_find_encoder(codec_id);

        }

    }



    avcodec_get_context_defaults3(st->codec, codec);



    ost->bitstream_filters = audio_bitstream_filters;

    audio_bitstream_filters= NULL;



    avcodec_thread_init(st->codec, thread_count);



    audio_enc = st->codec;

    audio_enc->codec_type = AVMEDIA_TYPE_AUDIO;



    if(audio_codec_tag)

        audio_enc->codec_tag= audio_codec_tag;



    if (oc->oformat->flags & AVFMT_GLOBALHEADER) {

        audio_enc->flags |= CODEC_FLAG_GLOBAL_HEADER;

        avcodec_opts[AVMEDIA_TYPE_AUDIO]->flags|= CODEC_FLAG_GLOBAL_HEADER;

    }

    if (audio_stream_copy) {

        st->stream_copy = 1;

        audio_enc->channels = audio_channels;

        audio_enc->sample_rate = audio_sample_rate;

    } else {

        audio_enc->codec_id = codec_id;

        set_context_opts(audio_enc, avcodec_opts[AVMEDIA_TYPE_AUDIO], AV_OPT_FLAG_AUDIO_PARAM | AV_OPT_FLAG_ENCODING_PARAM, codec);



        if (audio_qscale > QSCALE_NONE) {

            audio_enc->flags |= CODEC_FLAG_QSCALE;

            audio_enc->global_quality = st->quality = FF_QP2LAMBDA * audio_qscale;

        }

        audio_enc->channels = audio_channels;

        audio_enc->sample_fmt = audio_sample_fmt;

        audio_enc->sample_rate = audio_sample_rate;

        audio_enc->channel_layout = channel_layout;

        if (av_get_channel_layout_nb_channels(channel_layout) != audio_channels)

            audio_enc->channel_layout = 0;

        choose_sample_fmt(st, codec);

        choose_sample_rate(st, codec);

    }

    audio_enc->time_base= (AVRational){1, audio_sample_rate};

    if (audio_language) {

        av_metadata_set2(&st->metadata, "language", audio_language, 0);

        av_freep(&audio_language);

    }



    /* reset some key parameters */

    audio_disable = 0;

    av_freep(&audio_codec_name);

    audio_stream_copy = 0;

}

static int smacker_decode_tree(GetBitContext *gb, HuffContext *hc, uint32_t prefix, int length)

{

    if(length > 32) {

        av_log(NULL, AV_LOG_ERROR, "length too long\n");

        return AVERROR_INVALIDDATA;

    }

    if(!get_bits1(gb)){ //Leaf

        if(hc->current >= 256){

            av_log(NULL, AV_LOG_ERROR, "Tree size exceeded!\n");

            return AVERROR_INVALIDDATA;

        }

        if(length){

            hc->bits[hc->current] = prefix;

            hc->lengths[hc->current] = length;

        } else {

            hc->bits[hc->current] = 0;

            hc->lengths[hc->current] = 0;

        }

        hc->values[hc->current] = get_bits(gb, 8);

        hc->current++;

        if(hc->maxlength < length)

            hc->maxlength = length;

        return 0;

    } else { //Node

        int r;

        length++;

        r = smacker_decode_tree(gb, hc, prefix, length);

        if(r)

            return r;

        return smacker_decode_tree(gb, hc, prefix | (1 << (length - 1)), length);

    }

}

static int64_t run_opencl_bench(AVOpenCLExternalEnv *ext_opencl_env)

{

    int i, arg = 0, width = 1920, height = 1088;

    int64_t start, ret = 0;

    cl_int status;

    size_t kernel_len;

    char *inbuf;

    int *mask;

    int buf_size = width * height * sizeof(char);

    int mask_size = sizeof(uint32_t) * 128;



    cl_mem cl_mask, cl_inbuf, cl_outbuf;

    cl_kernel kernel = NULL;

    cl_program program = NULL;

    size_t local_work_size_2d[2] = {16, 16};

    size_t global_work_size_2d[2] = {(size_t)width, (size_t)height};



    if (!(inbuf = av_malloc(buf_size)) || !(mask = av_malloc(mask_size))) {

        av_log(NULL, AV_LOG_ERROR, "Out of memory\n");

        ret = AVERROR(ENOMEM);

        goto end;

    }

    fill_rand_int((int*)inbuf, buf_size/4);

    fill_rand_int(mask, mask_size/4);



    CREATEBUF(cl_mask, CL_MEM_READ_ONLY, mask_size);

    CREATEBUF(cl_inbuf, CL_MEM_READ_ONLY, buf_size);

    CREATEBUF(cl_outbuf, CL_MEM_READ_WRITE, buf_size);



    kernel_len = strlen(ocl_bench_source);

    program = clCreateProgramWithSource(ext_opencl_env->context, 1, &ocl_bench_source,

                                        &kernel_len, &status);

    if (status != CL_SUCCESS || !program) {

        av_log(NULL, AV_LOG_ERROR, "OpenCL unable to create benchmark program\n");

        ret = AVERROR_EXTERNAL;

        goto end;

    }

    status = clBuildProgram(program, 1, &(ext_opencl_env->device_id), NULL, NULL, NULL);

    if (status != CL_SUCCESS) {

        av_log(NULL, AV_LOG_ERROR, "OpenCL unable to build benchmark program\n");

        ret = AVERROR_EXTERNAL;

        goto end;

    }

    kernel = clCreateKernel(program, "unsharp_bench", &status);

    if (status != CL_SUCCESS) {

        av_log(NULL, AV_LOG_ERROR, "OpenCL unable to create benchmark kernel\n");

        ret = AVERROR_EXTERNAL;

        goto end;

    }



    OCLCHECK(clEnqueueWriteBuffer, ext_opencl_env->command_queue, cl_inbuf, CL_TRUE, 0,

             buf_size, inbuf, 0, NULL, NULL);

    OCLCHECK(clEnqueueWriteBuffer, ext_opencl_env->command_queue, cl_mask, CL_TRUE, 0,

             mask_size, mask, 0, NULL, NULL);

    OCLCHECK(clSetKernelArg, kernel, arg++, sizeof(cl_mem), &cl_inbuf);

    OCLCHECK(clSetKernelArg, kernel, arg++, sizeof(cl_mem), &cl_outbuf);

    OCLCHECK(clSetKernelArg, kernel, arg++, sizeof(cl_mem), &cl_mask);

    OCLCHECK(clSetKernelArg, kernel, arg++, sizeof(cl_int), &width);

    OCLCHECK(clSetKernelArg, kernel, arg++, sizeof(cl_int), &height);



    start = av_gettime_relative();

    for (i = 0; i < OPENCL_NB_ITER; i++)

        OCLCHECK(clEnqueueNDRangeKernel, ext_opencl_env->command_queue, kernel, 2, NULL,

                 global_work_size_2d, local_work_size_2d, 0, NULL, NULL);

    clFinish(ext_opencl_env->command_queue);

    ret = (av_gettime_relative() - start)/OPENCL_NB_ITER;

end:

    if (kernel)

        clReleaseKernel(kernel);

    if (program)

        clReleaseProgram(program);

    if (cl_inbuf)

        clReleaseMemObject(cl_inbuf);

    if (cl_outbuf)

        clReleaseMemObject(cl_outbuf);

    if (cl_mask)

        clReleaseMemObject(cl_mask);

    av_free(inbuf);

    av_free(mask);

    return ret;

}

static int parse_strk(AVFormatContext *s,

                      FourxmDemuxContext *fourxm, uint8_t *buf, int size,

                      int left)

{

    AVStream *st;

    int track;

    /* check that there is enough data */

    if (size != strk_SIZE || left < size + 8)

        return AVERROR_INVALIDDATA;



    track = AV_RL32(buf + 8);

    if ((unsigned)track >= UINT_MAX / sizeof(AudioTrack) - 1) {

        av_log(s, AV_LOG_ERROR, "current_track too large\n");

        return AVERROR_INVALIDDATA;

    }



    if (track + 1 > fourxm->track_count) {

        if (av_reallocp_array(&fourxm->tracks, track + 1, sizeof(AudioTrack)))

            return AVERROR(ENOMEM);

        memset(&fourxm->tracks[fourxm->track_count], 0,

               sizeof(AudioTrack) * (track + 1 - fourxm->track_count));

        fourxm->track_count = track + 1;

    }

    fourxm->tracks[track].adpcm       = AV_RL32(buf + 12);

    fourxm->tracks[track].channels    = AV_RL32(buf + 36);

    fourxm->tracks[track].sample_rate = AV_RL32(buf + 40);

    fourxm->tracks[track].bits        = AV_RL32(buf + 44);

    fourxm->tracks[track].audio_pts   = 0;



    if (fourxm->tracks[track].channels    <= 0 ||

        fourxm->tracks[track].sample_rate <= 0 ||

        fourxm->tracks[track].bits        <= 0) {

        av_log(s, AV_LOG_ERROR, "audio header invalid\n");

        return AVERROR_INVALIDDATA;

    }

    if (!fourxm->tracks[track].adpcm && fourxm->tracks[track].bits<8) {

        av_log(s, AV_LOG_ERROR, "bits unspecified for non ADPCM\n");

        return AVERROR_INVALIDDATA;

    }



    if (fourxm->tracks[track].sample_rate > INT64_MAX / fourxm->tracks[track].bits / fourxm->tracks[track].channels) {

        av_log(s, AV_LOG_ERROR, "Overflow during bit rate calculation %d * %d * %d\n",

               fourxm->tracks[track].sample_rate, fourxm->tracks[track].bits, fourxm->tracks[track].channels);

        return AVERROR_INVALIDDATA;

    }



    /* allocate a new AVStream */

    st = avformat_new_stream(s, NULL);

    if (!st)

        return AVERROR(ENOMEM);



    st->id = track;

    avpriv_set_pts_info(st, 60, 1, fourxm->tracks[track].sample_rate);



    fourxm->tracks[track].stream_index = st->index;



    st->codecpar->codec_type            = AVMEDIA_TYPE_AUDIO;

    st->codecpar->codec_tag             = 0;

    st->codecpar->channels              = fourxm->tracks[track].channels;

    st->codecpar->sample_rate           = fourxm->tracks[track].sample_rate;

    st->codecpar->bits_per_coded_sample = fourxm->tracks[track].bits;

    st->codecpar->bit_rate              = (int64_t)st->codecpar->channels *

                                          st->codecpar->sample_rate *

                                          st->codecpar->bits_per_coded_sample;

    st->codecpar->block_align           = st->codecpar->channels *

                                          st->codecpar->bits_per_coded_sample;



    if (fourxm->tracks[track].adpcm){

        st->codecpar->codec_id = AV_CODEC_ID_ADPCM_4XM;

    } else if (st->codecpar->bits_per_coded_sample == 8) {

        st->codecpar->codec_id = AV_CODEC_ID_PCM_U8;

    } else

        st->codecpar->codec_id = AV_CODEC_ID_PCM_S16LE;



    return 0;

}

void yuv2rgb_altivec_init_tables (SwsContext *c, const int inv_table[4],int brightness,int contrast, int saturation)

{

  union {

  	signed short tmp[8] __attribute__ ((aligned(16)));

	vector signed short vec;

	} buf;



  buf.tmp[0] =  ( (0xffffLL) * contrast>>8 )>>9;			//cy

  buf.tmp[1] =  -256*brightness;					//oy

  buf.tmp[2] =  (inv_table[0]>>3) *(contrast>>16)*(saturation>>16);	//crv

  buf.tmp[3] =  (inv_table[1]>>3) *(contrast>>16)*(saturation>>16);	//cbu

  buf.tmp[4] = -((inv_table[2]>>1)*(contrast>>16)*(saturation>>16));	//cgu

  buf.tmp[5] = -((inv_table[3]>>1)*(contrast>>16)*(saturation>>16));	//cgv





  c->CSHIFT = (vector unsigned short)vec_splat_u16(2);

  c->CY  = vec_splat ((vector signed short)buf.vec, 0);

  c->OY  = vec_splat ((vector signed short)buf.vec, 1);

  c->CRV  = vec_splat ((vector signed short)buf.vec, 2);

  c->CBU  = vec_splat ((vector signed short)buf.vec, 3);

  c->CGU  = vec_splat ((vector signed short)buf.vec, 4);

  c->CGV  = vec_splat ((vector signed short)buf.vec, 5);

