static int udp_open(URLContext *h, const char *uri, int flags)

{

    char hostname[1024], localaddr[1024] = "";

    int port, udp_fd = -1, tmp, bind_ret = -1;

    UDPContext *s = h->priv_data;

    int is_output;

    const char *p;

    char buf[256];

    struct sockaddr_storage my_addr;

    int len;

    int reuse_specified = 0;



    h->is_streamed = 1;

    h->max_packet_size = 1472;



    is_output = !(flags & AVIO_FLAG_READ);



    s->ttl = 16;

    s->buffer_size = is_output ? UDP_TX_BUF_SIZE : UDP_MAX_PKT_SIZE;



    s->circular_buffer_size = 7*188*4096;



    p = strchr(uri, '?');

    if (p) {

        if (av_find_info_tag(buf, sizeof(buf), "reuse", p)) {

            char *endptr = NULL;

            s->reuse_socket = strtol(buf, &endptr, 10);

            /* assume if no digits were found it is a request to enable it */

            if (buf == endptr)

                s->reuse_socket = 1;

            reuse_specified = 1;

        }

        if (av_find_info_tag(buf, sizeof(buf), "overrun_nonfatal", p)) {

            char *endptr = NULL;

            s->overrun_nonfatal = strtol(buf, &endptr, 10);

            /* assume if no digits were found it is a request to enable it */

            if (buf == endptr)

                s->overrun_nonfatal = 1;

        }

        if (av_find_info_tag(buf, sizeof(buf), "ttl", p)) {

            s->ttl = strtol(buf, NULL, 10);

        }

        if (av_find_info_tag(buf, sizeof(buf), "localport", p)) {

            s->local_port = strtol(buf, NULL, 10);

        }

        if (av_find_info_tag(buf, sizeof(buf), "pkt_size", p)) {

            h->max_packet_size = strtol(buf, NULL, 10);

        }

        if (av_find_info_tag(buf, sizeof(buf), "buffer_size", p)) {

            s->buffer_size = strtol(buf, NULL, 10);

        }

        if (av_find_info_tag(buf, sizeof(buf), "connect", p)) {

            s->is_connected = strtol(buf, NULL, 10);

        }

        if (av_find_info_tag(buf, sizeof(buf), "fifo_size", p)) {

            s->circular_buffer_size = strtol(buf, NULL, 10)*188;

        }

        if (av_find_info_tag(buf, sizeof(buf), "localaddr", p)) {

            av_strlcpy(localaddr, buf, sizeof(localaddr));

        }

    }



    /* fill the dest addr */

    av_url_split(NULL, 0, NULL, 0, hostname, sizeof(hostname), &port, NULL, 0, uri);



    /* XXX: fix av_url_split */

    if (hostname[0] == '\0' || hostname[0] == '?') {

        /* only accepts null hostname if input */

        if (!(flags & AVIO_FLAG_READ))

            goto fail;

    } else {

        if (ff_udp_set_remote_url(h, uri) < 0)

            goto fail;

    }



    if ((s->is_multicast || !s->local_port) && (h->flags & AVIO_FLAG_READ))

        s->local_port = port;

    udp_fd = udp_socket_create(s, &my_addr, &len, localaddr);

    if (udp_fd < 0)

        goto fail;



    /* Follow the requested reuse option, unless it's multicast in which

     * case enable reuse unless explicitly disabled.

     */

    if (s->reuse_socket || (s->is_multicast && !reuse_specified)) {

        s->reuse_socket = 1;

        if (setsockopt (udp_fd, SOL_SOCKET, SO_REUSEADDR, &(s->reuse_socket), sizeof(s->reuse_socket)) != 0)

            goto fail;

    }



    /* If multicast, try binding the multicast address first, to avoid

     * receiving UDP packets from other sources aimed at the same UDP

     * port. This fails on windows. This makes sending to the same address

     * using sendto() fail, so only do it if we're opened in read-only mode. */

    if (s->is_multicast && !(h->flags & AVIO_FLAG_WRITE)) {

        bind_ret = bind(udp_fd,(struct sockaddr *)&s->dest_addr, len);

    }

    /* bind to the local address if not multicast or if the multicast

     * bind failed */

    /* the bind is needed to give a port to the socket now */

    if (bind_ret < 0 && bind(udp_fd,(struct sockaddr *)&my_addr, len) < 0) {

        av_log(h, AV_LOG_ERROR, "bind failed: %s\n", strerror(errno));

        goto fail;

    }



    len = sizeof(my_addr);

    getsockname(udp_fd, (struct sockaddr *)&my_addr, &len);

    s->local_port = udp_port(&my_addr, len);



    if (s->is_multicast) {

        if (h->flags & AVIO_FLAG_WRITE) {

            /* output */

            if (udp_set_multicast_ttl(udp_fd, s->ttl, (struct sockaddr *)&s->dest_addr) < 0)

                goto fail;

        }

        if (h->flags & AVIO_FLAG_READ) {

            /* input */

            if (udp_join_multicast_group(udp_fd, (struct sockaddr *)&s->dest_addr) < 0)

                goto fail;

        }

    }



    if (is_output) {

        /* limit the tx buf size to limit latency */

        tmp = s->buffer_size;

        if (setsockopt(udp_fd, SOL_SOCKET, SO_SNDBUF, &tmp, sizeof(tmp)) < 0) {

            av_log(h, AV_LOG_ERROR, "setsockopt(SO_SNDBUF): %s\n", strerror(errno));

            goto fail;

        }

    } else {

        /* set udp recv buffer size to the largest possible udp packet size to

         * avoid losing data on OSes that set this too low by default. */

        tmp = s->buffer_size;

        if (setsockopt(udp_fd, SOL_SOCKET, SO_RCVBUF, &tmp, sizeof(tmp)) < 0) {

            av_log(h, AV_LOG_WARNING, "setsockopt(SO_RECVBUF): %s\n", strerror(errno));

        }

        /* make the socket non-blocking */

        ff_socket_nonblock(udp_fd, 1);

    }

    if (s->is_connected) {

        if (connect(udp_fd, (struct sockaddr *) &s->dest_addr, s->dest_addr_len)) {

            av_log(h, AV_LOG_ERROR, "connect: %s\n", strerror(errno));

            goto fail;

        }

    }



    s->udp_fd = udp_fd;



#if HAVE_PTHREADS

    if (!is_output && s->circular_buffer_size) {

        int ret;



        /* start the task going */

        s->fifo = av_fifo_alloc(s->circular_buffer_size);

        ret = pthread_mutex_init(&s->mutex, NULL);

        if (ret != 0) {

            av_log(h, AV_LOG_ERROR, "pthread_mutex_init failed : %s\n", strerror(ret));

            goto fail;

        }

        ret = pthread_cond_init(&s->cond, NULL);

        if (ret != 0) {

            av_log(h, AV_LOG_ERROR, "pthread_cond_init failed : %s\n", strerror(ret));

            goto cond_fail;

        }

        ret = pthread_create(&s->circular_buffer_thread, NULL, circular_buffer_task, h);

        if (ret != 0) {

            av_log(h, AV_LOG_ERROR, "pthread_create failed : %s\n", strerror(ret));

            goto thread_fail;

        }

        s->thread_started = 1;

    }

#endif



    return 0;

#if HAVE_PTHREADS

 thread_fail:

    pthread_cond_destroy(&s->cond);

 cond_fail:

    pthread_mutex_destroy(&s->mutex);

#endif

 fail:

    if (udp_fd >= 0)

        closesocket(udp_fd);

    av_fifo_free(s->fifo);

    return AVERROR(EIO);

}

static int txd_decode_frame(AVCodecContext *avctx, void *data, int *data_size,

                            AVPacket *avpkt) {

    const uint8_t *buf = avpkt->data;

    TXDContext * const s = avctx->priv_data;

    AVFrame *picture = data;

    AVFrame * const p = &s->picture;

    unsigned int version, w, h, d3d_format, depth, stride, mipmap_count, flags;

    unsigned int y, v;

    uint8_t *ptr;

    const uint8_t *cur = buf;

    const uint32_t *palette = (const uint32_t *)(cur + 88);

    uint32_t *pal;



    version         = AV_RL32(cur);

    d3d_format      = AV_RL32(cur+76);

    w               = AV_RL16(cur+80);

    h               = AV_RL16(cur+82);

    depth           = AV_RL8 (cur+84);

    mipmap_count    = AV_RL8 (cur+85);

    flags           = AV_RL8 (cur+87);

    cur            += 92;



    if (version < 8 || version > 9) {

        av_log(avctx, AV_LOG_ERROR, "texture data version %i is unsupported\n",

                                                                    version);

        return -1;

    }



    if (depth == 8) {

        avctx->pix_fmt = PIX_FMT_PAL8;

        cur += 1024;

    } else if (depth == 16 || depth == 32)

        avctx->pix_fmt = PIX_FMT_RGB32;

    else {

        av_log(avctx, AV_LOG_ERROR, "depth of %i is unsupported\n", depth);

        return -1;

    }



    if (p->data[0])

        avctx->release_buffer(avctx, p);



    if (av_image_check_size(w, h, 0, avctx))

        return -1;

    if (w != avctx->width || h != avctx->height)

        avcodec_set_dimensions(avctx, w, h);

    if (avctx->get_buffer(avctx, p) < 0) {

        av_log(avctx, AV_LOG_ERROR, "get_buffer() failed\n");

        return -1;

    }



    p->pict_type = AV_PICTURE_TYPE_I;



    ptr    = p->data[0];

    stride = p->linesize[0];



    if (depth == 8) {

        pal = (uint32_t *) p->data[1];

        for (y=0; y<256; y++) {

            v = AV_RB32(palette+y);

            pal[y] = (v>>8) + (v<<24);

        }

        for (y=0; y<h; y++) {

            memcpy(ptr, cur, w);

            ptr += stride;

            cur += w;

        }

    } else if (depth == 16) {

        switch (d3d_format) {

        case 0:

            if (!(flags & 1))

                goto unsupported;

        case FF_S3TC_DXT1:

            ff_decode_dxt1(cur, ptr, w, h, stride);

            break;

        case FF_S3TC_DXT3:

            ff_decode_dxt3(cur, ptr, w, h, stride);

            break;

        default:

            goto unsupported;

        }

    } else if (depth == 32) {

        switch (d3d_format) {

        case 0x15:

        case 0x16:

            for (y=0; y<h; y++) {

                memcpy(ptr, cur, w*4);

                ptr += stride;

                cur += w*4;

            }

            break;

        default:

            goto unsupported;

        }

    }



    for (; mipmap_count > 1; mipmap_count--)

        cur += AV_RL32(cur) + 4;



    *picture   = s->picture;

    *data_size = sizeof(AVPicture);



    return cur - buf;



unsupported:

    av_log(avctx, AV_LOG_ERROR, "unsupported d3d format (%08x)\n", d3d_format);

    return -1;

}

static int start_frame(AVFilterLink *inlink, AVFilterBufferRef *picref)

{

    AVFilterContext *ctx  = inlink->dst;

    TileContext *tile    = ctx->priv;

    AVFilterLink *outlink = ctx->outputs[0];



    if (tile->current)

        return 0;

    outlink->out_buf = ff_get_video_buffer(outlink, AV_PERM_WRITE,

                                                 outlink->w, outlink->h);

    avfilter_copy_buffer_ref_props(outlink->out_buf, picref);

    outlink->out_buf->video->w = outlink->w;

    outlink->out_buf->video->h = outlink->h;



    /* fill surface once for margin/padding */

    if (tile->margin || tile->padding)

        ff_fill_rectangle(&tile->draw, &tile->blank,

                          outlink->out_buf->data, outlink->out_buf->linesize,

                          0, 0, outlink->w, outlink->h);

    return 0;

}

static int v4l2_read_header(AVFormatContext *ctx)

{

    struct video_data *s = ctx->priv_data;

    AVStream *st;

    int res = 0;

    uint32_t desired_format;

    enum AVCodecID codec_id = AV_CODEC_ID_NONE;

    enum AVPixelFormat pix_fmt = AV_PIX_FMT_NONE;

    struct v4l2_input input = { 0 };



    st = avformat_new_stream(ctx, NULL);

    if (!st)

        return AVERROR(ENOMEM);



#if CONFIG_LIBV4L2

    /* silence libv4l2 logging. if fopen() fails v4l2_log_file will be NULL

       and errors will get sent to stderr */

    if (s->use_libv4l2)

        v4l2_log_file = fopen("/dev/null", "w");

#endif



    s->fd = device_open(ctx);

    if (s->fd < 0)

        return s->fd;



    if (s->channel != -1) {

        /* set video input */

        av_log(ctx, AV_LOG_DEBUG, "Selecting input_channel: %d\n", s->channel);

        if (v4l2_ioctl(s->fd, VIDIOC_S_INPUT, &s->channel) < 0) {

            res = AVERROR(errno);

            av_log(ctx, AV_LOG_ERROR, "ioctl(VIDIOC_S_INPUT): %s\n", av_err2str(res));

            goto fail;

        }

    } else {

        /* get current video input */

        if (v4l2_ioctl(s->fd, VIDIOC_G_INPUT, &s->channel) < 0) {

            res = AVERROR(errno);

            av_log(ctx, AV_LOG_ERROR, "ioctl(VIDIOC_G_INPUT): %s\n", av_err2str(res));

            goto fail;

        }

    }



    /* enum input */

    input.index = s->channel;

    if (v4l2_ioctl(s->fd, VIDIOC_ENUMINPUT, &input) < 0) {

        res = AVERROR(errno);

        av_log(ctx, AV_LOG_ERROR, "ioctl(VIDIOC_ENUMINPUT): %s\n", av_err2str(res));

        goto fail;

    }

    s->std_id = input.std;

    av_log(ctx, AV_LOG_DEBUG, "Current input_channel: %d, input_name: %s, input_std: %"PRIx64"\n",

           s->channel, input.name, (uint64_t)input.std);



    if (s->list_format) {

        list_formats(ctx, s->list_format);

        res = AVERROR_EXIT;

        goto fail;

    }



    if (s->list_standard) {

        list_standards(ctx);

        res = AVERROR_EXIT;

        goto fail;

    }



    avpriv_set_pts_info(st, 64, 1, 1000000); /* 64 bits pts in us */



    if ((res = v4l2_set_parameters(ctx)) < 0)

        goto fail;



    if (s->pixel_format) {

        AVCodec *codec = avcodec_find_decoder_by_name(s->pixel_format);



        if (codec)

            ctx->video_codec_id = codec->id;



        pix_fmt = av_get_pix_fmt(s->pixel_format);



        if (pix_fmt == AV_PIX_FMT_NONE && !codec) {

            av_log(ctx, AV_LOG_ERROR, "No such input format: %s.\n",

                   s->pixel_format);



            res = AVERROR(EINVAL);

            goto fail;

        }

    }



    if (!s->width && !s->height) {

        struct v4l2_format fmt = { .type = V4L2_BUF_TYPE_VIDEO_CAPTURE };



        av_log(ctx, AV_LOG_VERBOSE,

               "Querying the device for the current frame size\n");

        if (v4l2_ioctl(s->fd, VIDIOC_G_FMT, &fmt) < 0) {

            res = AVERROR(errno);

            av_log(ctx, AV_LOG_ERROR, "ioctl(VIDIOC_G_FMT): %s\n", av_err2str(res));

            goto fail;

        }



        s->width  = fmt.fmt.pix.width;

        s->height = fmt.fmt.pix.height;

        av_log(ctx, AV_LOG_VERBOSE,

               "Setting frame size to %dx%d\n", s->width, s->height);

    }



    res = device_try_init(ctx, pix_fmt, &s->width, &s->height, &desired_format, &codec_id);

    if (res < 0)

        goto fail;



    /* If no pixel_format was specified, the codec_id was not known up

     * until now. Set video_codec_id in the context, as codec_id will

     * not be available outside this function

     */

    if (codec_id != AV_CODEC_ID_NONE && ctx->video_codec_id == AV_CODEC_ID_NONE)

        ctx->video_codec_id = codec_id;



    if ((res = av_image_check_size(s->width, s->height, 0, ctx)) < 0)

        goto fail;



    s->frame_format = desired_format;



    st->codec->pix_fmt = avpriv_fmt_v4l2ff(desired_format, codec_id);

    s->frame_size =

        avpicture_get_size(st->codec->pix_fmt, s->width, s->height);



    if ((res = mmap_init(ctx)) ||

        (res = mmap_start(ctx)) < 0)

            goto fail;



    s->top_field_first = first_field(s);



    st->codec->codec_type = AVMEDIA_TYPE_VIDEO;

    st->codec->codec_id = codec_id;

    if (codec_id == AV_CODEC_ID_RAWVIDEO)

        st->codec->codec_tag =

            avcodec_pix_fmt_to_codec_tag(st->codec->pix_fmt);

    else if (codec_id == AV_CODEC_ID_H264) {

        st->need_parsing = AVSTREAM_PARSE_HEADERS;

    }

    if (desired_format == V4L2_PIX_FMT_YVU420)

        st->codec->codec_tag = MKTAG('Y', 'V', '1', '2');

    else if (desired_format == V4L2_PIX_FMT_YVU410)

        st->codec->codec_tag = MKTAG('Y', 'V', 'U', '9');

    st->codec->width = s->width;

    st->codec->height = s->height;

    if (st->avg_frame_rate.den)

        st->codec->bit_rate = s->frame_size * av_q2d(st->avg_frame_rate) * 8;



    return 0;



fail:

    v4l2_close(s->fd);

    return res;

}

static int output_frame(H264Context *h, AVFrame *dst, Picture *srcp)

{

    AVFrame *src = &srcp->f;

    int i;

    int ret = av_frame_ref(dst, src);

    if (ret < 0)

        return ret;



    av_dict_set(&dst->metadata, "stereo_mode", ff_h264_sei_stereo_mode(h), 0);



    if (!srcp->crop)

        return 0;



    for (i = 0; i < 3; i++) {

        int hshift = (i > 0) ? h->chroma_x_shift : 0;

        int vshift = (i > 0) ? h->chroma_y_shift : 0;

        int off    = ((srcp->crop_left >> hshift) << h->pixel_shift) +

                      (srcp->crop_top  >> vshift) * dst->linesize[i];

        dst->data[i] += off;

    }

    return 0;

}

static int flac_write_header(struct AVFormatContext *s)

{

    int ret;

    AVCodecContext *codec = s->streams[0]->codec;

    FlacMuxerContext *c   = s->priv_data;



    if (!c->write_header)

        return 0;



    ret = ff_flac_write_header(s->pb, codec, 0);

    if (ret)

        return ret;



    ret = flac_write_block_comment(s->pb, &s->metadata, 0,

                                   codec->flags & CODEC_FLAG_BITEXACT);

    if (ret)

        return ret;



    /* The command line flac encoder defaults to placing a seekpoint

     * every 10s.  So one might add padding to allow that later

     * but there seems to be no simple way to get the duration here.

     * So let's try the flac default of 8192 bytes */

    flac_write_block_padding(s->pb, 8192, 1);



    return ret;

}

int ff_qsv_enc_init(AVCodecContext *avctx, QSVEncContext *q)

{

    int opaque_alloc = 0;

    int ret;



    q->param.IOPattern  = MFX_IOPATTERN_IN_SYSTEM_MEMORY;

    q->param.AsyncDepth = q->async_depth;



    q->async_fifo = av_fifo_alloc((1 + q->async_depth) *

                                  (sizeof(AVPacket) + sizeof(mfxSyncPoint) + sizeof(mfxBitstream*)));

    if (!q->async_fifo)

        return AVERROR(ENOMEM);



    if (avctx->hwaccel_context) {

        AVQSVContext *qsv = avctx->hwaccel_context;



        q->session         = qsv->session;

        q->param.IOPattern = qsv->iopattern;



        opaque_alloc = qsv->opaque_alloc;

    }



    if (!q->session) {

        ret = ff_qsv_init_internal_session(avctx, &q->internal_session,

                                           q->load_plugins);

        if (ret < 0)

            return ret;



        q->session = q->internal_session;

    }



    ret = init_video_param(avctx, q);

    if (ret < 0)

        return ret;



    ret = MFXVideoENCODE_QueryIOSurf(q->session, &q->param, &q->req);

    if (ret < 0) {

        av_log(avctx, AV_LOG_ERROR, "Error querying the encoding parameters\n");

        return ff_qsv_error(ret);

    }



    if (opaque_alloc) {

        ret = qsv_init_opaque_alloc(avctx, q);

        if (ret < 0)

            return ret;

    }



    if (avctx->hwaccel_context) {

        AVQSVContext *qsv = avctx->hwaccel_context;

        int i, j;



        q->extparam = av_mallocz_array(qsv->nb_ext_buffers + q->nb_extparam_internal,

                                       sizeof(*q->extparam));

        if (!q->extparam)

            return AVERROR(ENOMEM);



        q->param.ExtParam = q->extparam;

        for (i = 0; i < qsv->nb_ext_buffers; i++)

            q->param.ExtParam[i] = qsv->ext_buffers[i];

        q->param.NumExtParam = qsv->nb_ext_buffers;



        for (i = 0; i < q->nb_extparam_internal; i++) {

            for (j = 0; j < qsv->nb_ext_buffers; j++) {

                if (qsv->ext_buffers[j]->BufferId == q->extparam_internal[i]->BufferId)

                    break;

            }

            if (j < qsv->nb_ext_buffers)

                continue;



            q->param.ExtParam[q->param.NumExtParam++] = q->extparam_internal[i];

        }

    } else {

        q->param.ExtParam    = q->extparam_internal;

        q->param.NumExtParam = q->nb_extparam_internal;

    }



    ret = MFXVideoENCODE_Init(q->session, &q->param);

    if (ret < 0) {

        av_log(avctx, AV_LOG_ERROR, "Error initializing the encoder\n");

        return ff_qsv_error(ret);

    }



    ret = qsv_retrieve_enc_params(avctx, q);

    if (ret < 0) {

        av_log(avctx, AV_LOG_ERROR, "Error retrieving encoding parameters.\n");

        return ret;

    }



    q->avctx = avctx;



    return 0;

}

static int vorbis_parse_setup_hdr_floors(vorbis_context *vc) {

    GetBitContext *gb=&vc->gb;

    uint_fast16_t i,j,k;



    vc->floor_count=get_bits(gb, 6)+1;



    vc->floors=av_mallocz(vc->floor_count * sizeof(vorbis_floor));



    for (i=0;i<vc->floor_count;++i) {

        vorbis_floor *floor_setup=&vc->floors[i];



        floor_setup->floor_type=get_bits(gb, 16);



        AV_DEBUG(" %d. floor type %d \n", i, floor_setup->floor_type);



        if (floor_setup->floor_type==1) {

            uint_fast8_t maximum_class=0;

            uint_fast8_t rangebits;

            uint_fast16_t floor1_values=2;



            floor_setup->decode=vorbis_floor1_decode;



            floor_setup->data.t1.partitions=get_bits(gb, 5);



            AV_DEBUG(" %d.floor: %d partitions \n", i, floor_setup->data.t1.partitions);



            for(j=0;j<floor_setup->data.t1.partitions;++j) {

                floor_setup->data.t1.partition_class[j]=get_bits(gb, 4);

                if (floor_setup->data.t1.partition_class[j]>maximum_class) maximum_class=floor_setup->data.t1.partition_class[j];



                AV_DEBUG(" %d. floor %d partition class %d \n", i, j, floor_setup->data.t1.partition_class[j]);



            }



            AV_DEBUG(" maximum class %d \n", maximum_class);



            floor_setup->data.t1.maximum_class=maximum_class;



            for(j=0;j<=maximum_class;++j) {

                floor_setup->data.t1.class_dimensions[j]=get_bits(gb, 3)+1;

                floor_setup->data.t1.class_subclasses[j]=get_bits(gb, 2);



                AV_DEBUG(" %d floor %d class dim: %d subclasses %d \n", i, j, floor_setup->data.t1.class_dimensions[j], floor_setup->data.t1.class_subclasses[j]);



                if (floor_setup->data.t1.class_subclasses[j]) {

                    floor_setup->data.t1.class_masterbook[j]=get_bits(gb, 8);



                    AV_DEBUG("   masterbook: %d \n", floor_setup->data.t1.class_masterbook[j]);

                }



                for(k=0;k<(1<<floor_setup->data.t1.class_subclasses[j]);++k) {

                    floor_setup->data.t1.subclass_books[j][k]=(int16_t)get_bits(gb, 8)-1;



                    AV_DEBUG("    book %d. : %d \n", k, floor_setup->data.t1.subclass_books[j][k]);

                }

            }



            floor_setup->data.t1.multiplier=get_bits(gb, 2)+1;

            floor_setup->data.t1.x_list_dim=2;



            for(j=0;j<floor_setup->data.t1.partitions;++j) {

                floor_setup->data.t1.x_list_dim+=floor_setup->data.t1.class_dimensions[floor_setup->data.t1.partition_class[j]];

            }



            floor_setup->data.t1.list=av_mallocz(floor_setup->data.t1.x_list_dim * sizeof(vorbis_floor1_entry));





            rangebits=get_bits(gb, 4);

            floor_setup->data.t1.list[0].x = 0;

            floor_setup->data.t1.list[1].x = (1<<rangebits);



            for(j=0;j<floor_setup->data.t1.partitions;++j) {

                for(k=0;k<floor_setup->data.t1.class_dimensions[floor_setup->data.t1.partition_class[j]];++k,++floor1_values) {

                    floor_setup->data.t1.list[floor1_values].x=get_bits(gb, rangebits);



                    AV_DEBUG(" %d. floor1 Y coord. %d \n", floor1_values, floor_setup->data.t1.list[floor1_values].x);

                }

            }



// Precalculate order of x coordinates - needed for decode

            ff_vorbis_ready_floor1_list(floor_setup->data.t1.list, floor_setup->data.t1.x_list_dim);

        }

        else if(floor_setup->floor_type==0) {

            uint_fast8_t max_codebook_dim=0;



            floor_setup->decode=vorbis_floor0_decode;



            floor_setup->data.t0.order=get_bits(gb, 8);

            floor_setup->data.t0.rate=get_bits(gb, 16);

            floor_setup->data.t0.bark_map_size=get_bits(gb, 16);

            floor_setup->data.t0.amplitude_bits=get_bits(gb, 6);

            /* zero would result in a div by zero later *

             * 2^0 - 1 == 0                             */

            if (floor_setup->data.t0.amplitude_bits == 0) {

              av_log(vc->avccontext, AV_LOG_ERROR,

                     "Floor 0 amplitude bits is 0.\n");

              return 1;

            }

            floor_setup->data.t0.amplitude_offset=get_bits(gb, 8);

            floor_setup->data.t0.num_books=get_bits(gb, 4)+1;



            /* allocate mem for booklist */

            floor_setup->data.t0.book_list=

                av_malloc(floor_setup->data.t0.num_books);

            if(!floor_setup->data.t0.book_list) { return 1; }

            /* read book indexes */

            {

                int idx;

                uint_fast8_t book_idx;

                for (idx=0;idx<floor_setup->data.t0.num_books;++idx) {

                    book_idx=get_bits(gb, 8);

                    if (book_idx>=vc->codebook_count)

                        return 1;

                    floor_setup->data.t0.book_list[idx]=book_idx;

                    if (vc->codebooks[book_idx].dimensions > max_codebook_dim)

                        max_codebook_dim=vc->codebooks[book_idx].dimensions;

                }

            }



            create_map( vc, i );



            /* allocate mem for lsp coefficients */

            {

                /* codebook dim is for padding if codebook dim doesn't *

                 * divide order+1 then we need to read more data       */

                floor_setup->data.t0.lsp=

                    av_malloc((floor_setup->data.t0.order+1 + max_codebook_dim)

                              * sizeof(float));

                if(!floor_setup->data.t0.lsp) { return 1; }

            }



#ifdef V_DEBUG /* debug output parsed headers */

            AV_DEBUG("floor0 order: %u\n", floor_setup->data.t0.order);

            AV_DEBUG("floor0 rate: %u\n", floor_setup->data.t0.rate);

            AV_DEBUG("floor0 bark map size: %u\n",

              floor_setup->data.t0.bark_map_size);

            AV_DEBUG("floor0 amplitude bits: %u\n",

              floor_setup->data.t0.amplitude_bits);

            AV_DEBUG("floor0 amplitude offset: %u\n",

              floor_setup->data.t0.amplitude_offset);

            AV_DEBUG("floor0 number of books: %u\n",

              floor_setup->data.t0.num_books);

            AV_DEBUG("floor0 book list pointer: %p\n",

              floor_setup->data.t0.book_list);

            {

              int idx;

              for (idx=0;idx<floor_setup->data.t0.num_books;++idx) {

                AV_DEBUG( "  Book %d: %u\n",

                  idx+1,

                  floor_setup->data.t0.book_list[idx] );

              }

            }

#endif

        }

        else {

            av_log(vc->avccontext, AV_LOG_ERROR, "Invalid floor type!\n");

            return 1;

        }

    }

    return 0;

}

static int encode_block(WMACodecContext *s, float (*src_coefs)[BLOCK_MAX_SIZE], int total_gain){

    int v, bsize, ch, coef_nb_bits, parse_exponents;

    float mdct_norm;

    int nb_coefs[MAX_CHANNELS];

    static const int fixed_exp[25]={20,20,20,20,20,20,20,20,20,20,20,20,20,20,20,20,20,20,20,20,20,20,20,20,20};



    //FIXME remove duplication relative to decoder

    if (s->use_variable_block_len) {

        assert(0); //FIXME not implemented

    }else{

        /* fixed block len */

        s->next_block_len_bits = s->frame_len_bits;

        s->prev_block_len_bits = s->frame_len_bits;

        s->block_len_bits = s->frame_len_bits;

    }



    s->block_len = 1 << s->block_len_bits;

//     assert((s->block_pos + s->block_len) <= s->frame_len);

    bsize = s->frame_len_bits - s->block_len_bits;



    //FIXME factor

    v = s->coefs_end[bsize] - s->coefs_start;

    for(ch = 0; ch < s->nb_channels; ch++)

        nb_coefs[ch] = v;

    {

        int n4 = s->block_len / 2;

        mdct_norm = 1.0 / (float)n4;

        if (s->version == 1) {

            mdct_norm *= sqrt(n4);

        }

    }



    if (s->nb_channels == 2) {

        put_bits(&s->pb, 1, !!s->ms_stereo);

    }



    for(ch = 0; ch < s->nb_channels; ch++) {

        s->channel_coded[ch] = 1; //FIXME only set channel_coded when needed, instead of always

        if (s->channel_coded[ch]) {

            init_exp(s, ch, fixed_exp);

        }

    }



    for(ch = 0; ch < s->nb_channels; ch++) {

        if (s->channel_coded[ch]) {

            WMACoef *coefs1;

            float *coefs, *exponents, mult;

            int i, n;



            coefs1 = s->coefs1[ch];

            exponents = s->exponents[ch];

            mult = pow(10, total_gain * 0.05) / s->max_exponent[ch];

            mult *= mdct_norm;

            coefs = src_coefs[ch];

            if (s->use_noise_coding && 0) {

                assert(0); //FIXME not implemented

            } else {

                coefs += s->coefs_start;

                n = nb_coefs[ch];

                for(i = 0;i < n; i++){

                    double t= *coefs++ / (exponents[i] * mult);

                    if(t<-32768 || t>32767)

                        return -1;



                    coefs1[i] = lrint(t);

                }

            }

        }

    }



    v = 0;

    for(ch = 0; ch < s->nb_channels; ch++) {

        int a = s->channel_coded[ch];

        put_bits(&s->pb, 1, a);

        v |= a;

    }



    if (!v)

        return 1;



    for(v= total_gain-1; v>=127; v-= 127)

        put_bits(&s->pb, 7, 127);

    put_bits(&s->pb, 7, v);



    coef_nb_bits= ff_wma_total_gain_to_bits(total_gain);



    if (s->use_noise_coding) {

        for(ch = 0; ch < s->nb_channels; ch++) {

            if (s->channel_coded[ch]) {

                int i, n;

                n = s->exponent_high_sizes[bsize];

                for(i=0;i<n;i++) {

                    put_bits(&s->pb, 1, s->high_band_coded[ch][i]= 0);

                    if (0)

                        nb_coefs[ch] -= s->exponent_high_bands[bsize][i];

                }

            }

        }

    }



    parse_exponents = 1;

    if (s->block_len_bits != s->frame_len_bits) {

        put_bits(&s->pb, 1, parse_exponents);

    }



    if (parse_exponents) {

        for(ch = 0; ch < s->nb_channels; ch++) {

            if (s->channel_coded[ch]) {

                if (s->use_exp_vlc) {

                    encode_exp_vlc(s, ch, fixed_exp);

                } else {

                    assert(0); //FIXME not implemented

//                    encode_exp_lsp(s, ch);

                }

            }

        }

    } else {

        assert(0); //FIXME not implemented

    }



    for(ch = 0; ch < s->nb_channels; ch++) {

        if (s->channel_coded[ch]) {

            int run, tindex;

            WMACoef *ptr, *eptr;

            tindex = (ch == 1 && s->ms_stereo);

            ptr = &s->coefs1[ch][0];

            eptr = ptr + nb_coefs[ch];



            run=0;

            for(;ptr < eptr; ptr++){

                if(*ptr){

                    int level= *ptr;

                    int abs_level= FFABS(level);

                    int code= 0;

                    if(abs_level <= s->coef_vlcs[tindex]->max_level){

                        if(run < s->coef_vlcs[tindex]->levels[abs_level-1])

                            code= run + s->int_table[tindex][abs_level-1];

                    }



                    assert(code < s->coef_vlcs[tindex]->n);

                    put_bits(&s->pb, s->coef_vlcs[tindex]->huffbits[code], s->coef_vlcs[tindex]->huffcodes[code]);



                    if(code == 0){

                        if(1<<coef_nb_bits <= abs_level)

                            return -1;





                        //Workaround minor rounding differences for the regression tests, FIXME we should find and replace the problematic float by fixpoint for reg tests

                        if(abs_level == 0x71B && (s->avctx->flags & CODEC_FLAG_BITEXACT)) abs_level=0x71A;



                        put_bits(&s->pb, coef_nb_bits, abs_level);

                        put_bits(&s->pb, s->frame_len_bits, run);

                    }

                    put_bits(&s->pb, 1, level < 0); //FIXME the sign is fliped somewhere

                    run=0;

                }else{

                    run++;

                }

            }

            if(run)

                put_bits(&s->pb, s->coef_vlcs[tindex]->huffbits[1], s->coef_vlcs[tindex]->huffcodes[1]);

        }

        if (s->version == 1 && s->nb_channels >= 2) {

            avpriv_align_put_bits(&s->pb);

        }

    }

    return 0;

}

int ff_amf_get_field_value(const uint8_t *data, const uint8_t *data_end,

                           const uint8_t *name, uint8_t *dst, int dst_size)

{

    int namelen = strlen(name);

    int len;



    while (*data != AMF_DATA_TYPE_OBJECT && data < data_end) {

        len = ff_amf_tag_size(data, data_end);

        if (len < 0)

            len = data_end - data;

        data += len;

    }

    if (data_end - data < 3)

        return -1;

    data++;

    for (;;) {

        int size = bytestream_get_be16(&data);

        if (!size)

            break;

        if (size < 0 || size >= data_end - data)

            return -1;

        data += size;

        if (size == namelen && !memcmp(data-size, name, namelen)) {

            switch (*data++) {

            case AMF_DATA_TYPE_NUMBER:

                snprintf(dst, dst_size, "%g", av_int2double(AV_RB64(data)));

                break;

            case AMF_DATA_TYPE_BOOL:

                snprintf(dst, dst_size, "%s", *data ? "true" : "false");

                break;

            case AMF_DATA_TYPE_STRING:

                len = bytestream_get_be16(&data);

                av_strlcpy(dst, data, FFMIN(len+1, dst_size));

                break;

            default:

                return -1;

            }

            return 0;

        }

        len = ff_amf_tag_size(data, data_end);

        if (len < 0 || len >= data_end - data)

            return -1;

        data += len;

    }

    return -1;

}

int ff_intel_h263_decode_picture_header(MpegEncContext *s)

{

    int format;



    /* picture header */

    if (get_bits_long(&s->gb, 22) != 0x20) {

        av_log(s->avctx, AV_LOG_ERROR, "Bad picture start code\n");

        return -1;

    }

    s->picture_number = get_bits(&s->gb, 8); /* picture timestamp */



    if (get_bits1(&s->gb) != 1) {

        av_log(s->avctx, AV_LOG_ERROR, "Bad marker\n");

        return -1;      /* marker */

    }

    if (get_bits1(&s->gb) != 0) {

        av_log(s->avctx, AV_LOG_ERROR, "Bad H263 id\n");

        return -1;      /* h263 id */

    }

    skip_bits1(&s->gb);         /* split screen off */

    skip_bits1(&s->gb);         /* camera  off */

    skip_bits1(&s->gb);         /* freeze picture release off */



    format = get_bits(&s->gb, 3);

    if (format == 0 || format == 6) {

        av_log(s->avctx, AV_LOG_ERROR, "Intel H263 free format not supported\n");

        return -1;

    }

    s->h263_plus = 0;



    s->pict_type = AV_PICTURE_TYPE_I + get_bits1(&s->gb);



    s->unrestricted_mv = get_bits1(&s->gb);

    s->h263_long_vectors = s->unrestricted_mv;



    if (get_bits1(&s->gb) != 0) {

        av_log(s->avctx, AV_LOG_ERROR, "SAC not supported\n");

        return -1;      /* SAC: off */

    }

    s->obmc= get_bits1(&s->gb);

    s->pb_frame = get_bits1(&s->gb);



    if (format < 6) {

        s->width = ff_h263_format[format][0];

        s->height = ff_h263_format[format][1];

        s->avctx->sample_aspect_ratio.num = 12;

        s->avctx->sample_aspect_ratio.den = 11;

    } else {

        format = get_bits(&s->gb, 3);

        if(format == 0 || format == 7){

            av_log(s->avctx, AV_LOG_ERROR, "Wrong Intel H263 format\n");

            return -1;

        }

        if(get_bits(&s->gb, 2))

            av_log(s->avctx, AV_LOG_ERROR, "Bad value for reserved field\n");

        s->loop_filter = get_bits1(&s->gb);

        if(get_bits1(&s->gb))

            av_log(s->avctx, AV_LOG_ERROR, "Bad value for reserved field\n");

        if(get_bits1(&s->gb))

            s->pb_frame = 2;

        if(get_bits(&s->gb, 5))

            av_log(s->avctx, AV_LOG_ERROR, "Bad value for reserved field\n");

        if(get_bits(&s->gb, 5) != 1)

            av_log(s->avctx, AV_LOG_ERROR, "Invalid marker\n");

    }

    if(format == 6){

        int ar = get_bits(&s->gb, 4);

        skip_bits(&s->gb, 9); // display width

        skip_bits1(&s->gb);

        skip_bits(&s->gb, 9); // display height

        if(ar == 15){

            s->avctx->sample_aspect_ratio.num = get_bits(&s->gb, 8); // aspect ratio - width

            s->avctx->sample_aspect_ratio.den = get_bits(&s->gb, 8); // aspect ratio - height

        } else {

            s->avctx->sample_aspect_ratio = ff_h263_pixel_aspect[ar];

        }

        if (s->avctx->sample_aspect_ratio.num == 0)

            av_log(s->avctx, AV_LOG_ERROR, "Invalid aspect ratio.\n");

    }



    s->chroma_qscale= s->qscale = get_bits(&s->gb, 5);

    skip_bits1(&s->gb); /* Continuous Presence Multipoint mode: off */



    if(s->pb_frame){

        skip_bits(&s->gb, 3); //temporal reference for B-frame

        skip_bits(&s->gb, 2); //dbquant

    }



    /* PEI */

    while (get_bits1(&s->gb) != 0) {

        skip_bits(&s->gb, 8);

    }

    s->f_code = 1;



    s->y_dc_scale_table=

    s->c_dc_scale_table= ff_mpeg1_dc_scale_table;



    ff_h263_show_pict_info(s);



    return 0;

}

static int mov_read_stsz(MOVContext *c, AVIOContext *pb, MOVAtom atom)

{

    AVStream *st;

    MOVStreamContext *sc;

    unsigned int i, entries, sample_size, field_size, num_bytes;

    GetBitContext gb;

    unsigned char* buf;



    if (c->fc->nb_streams < 1)

        return 0;

    st = c->fc->streams[c->fc->nb_streams-1];

    sc = st->priv_data;



    avio_r8(pb); /* version */

    avio_rb24(pb); /* flags */



    if (atom.type == MKTAG('s','t','s','z')) {

        sample_size = avio_rb32(pb);

        if (!sc->sample_size) /* do not overwrite value computed in stsd */

            sc->sample_size = sample_size;

        field_size = 32;

    } else {

        sample_size = 0;

        avio_rb24(pb); /* reserved */

        field_size = avio_r8(pb);

    }

    entries = avio_rb32(pb);



    av_dlog(c->fc, "sample_size = %d sample_count = %d\n", sc->sample_size, entries);



    sc->sample_count = entries;

    if (sample_size)

        return 0;



    if (field_size != 4 && field_size != 8 && field_size != 16 && field_size != 32) {

        av_log(c->fc, AV_LOG_ERROR, "Invalid sample field size %d\n", field_size);

        return AVERROR_INVALIDDATA;

    }



    if (!entries)

        return 0;

    if (entries >= UINT_MAX / sizeof(int) || entries >= (UINT_MAX - 4) / field_size)

        return AVERROR_INVALIDDATA;

    sc->sample_sizes = av_malloc(entries * sizeof(int));

    if (!sc->sample_sizes)

        return AVERROR(ENOMEM);



    num_bytes = (entries*field_size+4)>>3;



    buf = av_malloc(num_bytes+FF_INPUT_BUFFER_PADDING_SIZE);

    if (!buf) {

        av_freep(&sc->sample_sizes);

        return AVERROR(ENOMEM);

    }



    if (avio_read(pb, buf, num_bytes) < num_bytes) {

        av_freep(&sc->sample_sizes);

        av_free(buf);

        return AVERROR_INVALIDDATA;

    }



    init_get_bits(&gb, buf, 8*num_bytes);



    for (i = 0; i < entries; i++) {

        sc->sample_sizes[i] = get_bits_long(&gb, field_size);

        sc->data_size += sc->sample_sizes[i];

    }



    av_free(buf);

    return 0;

}

static int configure_input_video_filter(FilterGraph *fg, InputFilter *ifilter,

                                        AVFilterInOut *in)

{

    AVFilterContext *last_filter;

    const AVFilter *buffer_filt = avfilter_get_by_name("buffer");

    InputStream *ist = ifilter->ist;

    InputFile     *f = input_files[ist->file_index];

    AVRational tb = ist->framerate.num ? av_inv_q(ist->framerate) :

                                         ist->st->time_base;

    AVRational sar;

    char args[255], name[255];

    int ret, pad_idx = 0;



    sar = ist->st->sample_aspect_ratio.num ?

          ist->st->sample_aspect_ratio :

          ist->st->codec->sample_aspect_ratio;

    snprintf(args, sizeof(args), "%d:%d:%d:%d:%d:%d:%d", ist->st->codec->width,

             ist->st->codec->height, ist->st->codec->pix_fmt,

             tb.num, tb.den, sar.num, sar.den);

    snprintf(name, sizeof(name), "graph %d input from stream %d:%d", fg->index,

             ist->file_index, ist->st->index);



    if ((ret = avfilter_graph_create_filter(&ifilter->filter, buffer_filt, name,

                                            args, NULL, fg->graph)) < 0)

        return ret;

    last_filter = ifilter->filter;



    if (ist->framerate.num) {

        AVFilterContext *setpts;



        snprintf(name, sizeof(name), "force CFR for input from stream %d:%d",

                 ist->file_index, ist->st->index);

        if ((ret = avfilter_graph_create_filter(&setpts,

                                                avfilter_get_by_name("setpts"),

                                                name, "N", NULL,

                                                fg->graph)) < 0)

            return ret;



        if ((ret = avfilter_link(last_filter, 0, setpts, 0)) < 0)

            return ret;



        last_filter = setpts;

    }



    snprintf(name, sizeof(name), "trim for input stream %d:%d",

             ist->file_index, ist->st->index);

    ret = insert_trim(((f->start_time == AV_NOPTS_VALUE) || !f->accurate_seek) ?

                      AV_NOPTS_VALUE : 0, INT64_MAX, &last_filter, &pad_idx, name);

    if (ret < 0)

        return ret;



    if ((ret = avfilter_link(last_filter, 0, in->filter_ctx, in->pad_idx)) < 0)

        return ret;

    return 0;

}

