    if (IS_KLV_KEY(uid, mxf_crypto_source_container_ul))

        avio_read(pb, cryptocontext->source_container_ul, 16);

    return 0;

}

void ff_eac3_decode_transform_coeffs_aht_ch(AC3DecodeContext *s, int ch)

{

    int bin, blk, gs;

    int end_bap, gaq_mode;

    GetBitContext *gbc = &s->gbc;

    int gaq_gain[AC3_MAX_COEFS];



    gaq_mode = get_bits(gbc, 2);

    end_bap = (gaq_mode < 2) ? 12 : 17;



    /* if GAQ gain is used, decode gain codes for bins with hebap between

       8 and end_bap */

    gs = 0;

    if (gaq_mode == EAC3_GAQ_12 || gaq_mode == EAC3_GAQ_14) {

        /* read 1-bit GAQ gain codes */

        for (bin = s->start_freq[ch]; bin < s->end_freq[ch]; bin++) {

            if (s->bap[ch][bin] > 7 && s->bap[ch][bin] < end_bap)

                gaq_gain[gs++] = get_bits1(gbc) << (gaq_mode-1);

        }

    } else if (gaq_mode == EAC3_GAQ_124) {

        /* read 1.67-bit GAQ gain codes (3 codes in 5 bits) */

        int gc = 2;

        for (bin = s->start_freq[ch]; bin < s->end_freq[ch]; bin++) {

            if (s->bap[ch][bin] > 7 && s->bap[ch][bin] < 17) {

                if (gc++ == 2) {

                    int group_code = get_bits(gbc, 5);

                    if (group_code > 26) {

                        av_log(s->avctx, AV_LOG_WARNING, "GAQ gain group code out-of-range\n");

                        group_code = 26;

                    }

                    gaq_gain[gs++] = ff_ac3_ungroup_3_in_5_bits_tab[group_code][0];

                    gaq_gain[gs++] = ff_ac3_ungroup_3_in_5_bits_tab[group_code][1];

                    gaq_gain[gs++] = ff_ac3_ungroup_3_in_5_bits_tab[group_code][2];

                    gc = 0;

                }

            }

        }

    }



    gs=0;

    for (bin = s->start_freq[ch]; bin < s->end_freq[ch]; bin++) {

        int hebap = s->bap[ch][bin];

        int bits = ff_eac3_bits_vs_hebap[hebap];

        if (!hebap) {

            /* zero-mantissa dithering */

            for (blk = 0; blk < 6; blk++) {

                s->pre_mantissa[ch][bin][blk] = (av_lfg_get(&s->dith_state) & 0x7FFFFF) - 0x400000;

            }

        } else if (hebap < 8) {

            /* Vector Quantization */

            int v = get_bits(gbc, bits);

            for (blk = 0; blk < 6; blk++) {

                s->pre_mantissa[ch][bin][blk] = ff_eac3_mantissa_vq[hebap][v][blk] << 8;

            }

        } else {

            /* Gain Adaptive Quantization */

            int gbits, log_gain;

            if (gaq_mode != EAC3_GAQ_NO && hebap < end_bap) {

                log_gain = gaq_gain[gs++];

            } else {

                log_gain = 0;

            }

            gbits = bits - log_gain;



            for (blk = 0; blk < 6; blk++) {

                int mant = get_sbits(gbc, gbits);

                if (log_gain && mant == -(1 << (gbits-1))) {

                    /* large mantissa */

                    int b;

                    int mbits = bits - (2 - log_gain);

                    mant = get_sbits(gbc, mbits);

                    mant <<= (23 - (mbits - 1));

                    /* remap mantissa value to correct for asymmetric quantization */

                    if (mant >= 0)

                        b = 1 << (23 - log_gain);

                    else

                        b = ff_eac3_gaq_remap_2_4_b[hebap-8][log_gain-1] << 8;

                    mant += ((ff_eac3_gaq_remap_2_4_a[hebap-8][log_gain-1] * (int64_t)mant) >> 15) + b;

                } else {

                    /* small mantissa, no GAQ, or Gk=1 */

                    mant <<= 24 - bits;

                    if (!log_gain) {

                        /* remap mantissa value for no GAQ or Gk=1 */

                        mant += (ff_eac3_gaq_remap_1[hebap-8] * (int64_t)mant) >> 15;

                    }

                }

                s->pre_mantissa[ch][bin][blk] = mant;

            }

        }

        idct6(s->pre_mantissa[ch][bin]);

    }

}

int avpicture_layout(const AVPicture* src, enum AVPixelFormat pix_fmt,

                     int width, int height,

                     unsigned char *dest, int dest_size)

{

    int i, j, nb_planes = 0, linesizes[4];

    const AVPixFmtDescriptor *desc = av_pix_fmt_desc_get(pix_fmt);

    int size = avpicture_get_size(pix_fmt, width, height);



    if (size > dest_size || size < 0)

        return AVERROR(EINVAL);



    for (i = 0; i < desc->nb_components; i++)

        nb_planes = FFMAX(desc->comp[i].plane, nb_planes);



    nb_planes++;



    av_image_fill_linesizes(linesizes, pix_fmt, width);

    for (i = 0; i < nb_planes; i++) {

        int h, shift = (i == 1 || i == 2) ? desc->log2_chroma_h : 0;

        const unsigned char *s = src->data[i];

        h = (height + (1 << shift) - 1) >> shift;



        for (j = 0; j < h; j++) {

            memcpy(dest, s, linesizes[i]);

            dest += linesizes[i];

            s += src->linesize[i];

        }

    }



    if (desc->flags & AV_PIX_FMT_FLAG_PAL)

        memcpy((unsigned char *)(((size_t)dest + 3) & ~3),

               src->data[1], 256 * 4);



    return size;

}

static int pipe_open(URLContext *h, const char *filename, int flags)

{

    int fd;



    if (flags & URL_WRONLY) {

        fd = 1;

    } else {

        fd = 0;

    }

#if defined(__MINGW32__) || defined(CONFIG_OS2) || defined(__CYGWIN__)

    setmode(fd, O_BINARY);

#endif

    h->priv_data = (void *)(size_t)fd;

    h->is_streamed = 1;

    return 0;

}

static int decode_video(InputStream *ist, AVPacket *pkt, int *got_output)

{

    AVFrame *decoded_frame, *f;

    void *buffer_to_free = NULL;

    int i, ret = 0, err = 0, resample_changed;

    int64_t best_effort_timestamp;

    AVRational *frame_sample_aspect;



    if (!ist->decoded_frame && !(ist->decoded_frame = av_frame_alloc()))

        return AVERROR(ENOMEM);

    if (!ist->filter_frame && !(ist->filter_frame = av_frame_alloc()))

        return AVERROR(ENOMEM);

    decoded_frame = ist->decoded_frame;

    pkt->dts  = av_rescale_q(ist->dts, AV_TIME_BASE_Q, ist->st->time_base);



    update_benchmark(NULL);

    ret = avcodec_decode_video2(ist->st->codec,

                                decoded_frame, got_output, pkt);

    update_benchmark("decode_video %d.%d", ist->file_index, ist->st->index);

    if (!*got_output || ret < 0) {

        if (!pkt->size) {

            for (i = 0; i < ist->nb_filters; i++)

#if 1

                av_buffersrc_add_ref(ist->filters[i]->filter, NULL, 0);

#else

                av_buffersrc_add_frame(ist->filters[i]->filter, NULL);

#endif

        }

        return ret;

    }



    if(ist->top_field_first>=0)

        decoded_frame->top_field_first = ist->top_field_first;



    best_effort_timestamp= av_frame_get_best_effort_timestamp(decoded_frame);

    if(best_effort_timestamp != AV_NOPTS_VALUE)

        ist->next_pts = ist->pts = av_rescale_q(decoded_frame->pts = best_effort_timestamp, ist->st->time_base, AV_TIME_BASE_Q);



    if (debug_ts) {

        av_log(NULL, AV_LOG_INFO, "decoder -> ist_index:%d type:video "

                "frame_pts:%s frame_pts_time:%s best_effort_ts:%"PRId64" best_effort_ts_time:%s keyframe:%d frame_type:%d \n",

                ist->st->index, av_ts2str(decoded_frame->pts),

                av_ts2timestr(decoded_frame->pts, &ist->st->time_base),

                best_effort_timestamp,

                av_ts2timestr(best_effort_timestamp, &ist->st->time_base),

                decoded_frame->key_frame, decoded_frame->pict_type);

    }



    pkt->size = 0;

#if FF_API_DEINTERLACE

    pre_process_video_frame(ist, (AVPicture *)decoded_frame, &buffer_to_free);

#endif



    rate_emu_sleep(ist);



    if (ist->st->sample_aspect_ratio.num)

        decoded_frame->sample_aspect_ratio = ist->st->sample_aspect_ratio;



    resample_changed = ist->resample_width   != decoded_frame->width  ||

                       ist->resample_height  != decoded_frame->height ||

                       ist->resample_pix_fmt != decoded_frame->format;

    if (resample_changed) {

        av_log(NULL, AV_LOG_INFO,

               "Input stream #%d:%d frame changed from size:%dx%d fmt:%s to size:%dx%d fmt:%s\n",

               ist->file_index, ist->st->index,

               ist->resample_width,  ist->resample_height,  av_get_pix_fmt_name(ist->resample_pix_fmt),

               decoded_frame->width, decoded_frame->height, av_get_pix_fmt_name(decoded_frame->format));



        ist->resample_width   = decoded_frame->width;

        ist->resample_height  = decoded_frame->height;

        ist->resample_pix_fmt = decoded_frame->format;



        for (i = 0; i < nb_filtergraphs; i++) {

            if (ist_in_filtergraph(filtergraphs[i], ist) && ist->reinit_filters &&

                configure_filtergraph(filtergraphs[i]) < 0) {

                av_log(NULL, AV_LOG_FATAL, "Error reinitializing filters!\n");

                exit(1);

            }

        }

    }



    frame_sample_aspect= av_opt_ptr(avcodec_get_frame_class(), decoded_frame, "sample_aspect_ratio");

    for (i = 0; i < ist->nb_filters; i++) {

        if (!frame_sample_aspect->num)

            *frame_sample_aspect = ist->st->sample_aspect_ratio;



        if (i < ist->nb_filters - 1) {

            f = ist->filter_frame;

            err = av_frame_ref(f, decoded_frame);

            if (err < 0)

                break;

        } else

            f = decoded_frame;

        if(av_buffersrc_add_frame_flags(ist->filters[i]->filter, f,

                                        AV_BUFFERSRC_FLAG_PUSH)<0) {

            av_log(NULL, AV_LOG_FATAL, "Failed to inject frame into filter network\n");

            exit(1);

        }



    }



    av_frame_unref(ist->filter_frame);

    av_frame_unref(decoded_frame);

    av_free(buffer_to_free);

    return err < 0 ? err : ret;

}

static void audio_encode_example(const char *filename)

{

    AVCodec *codec;

    AVCodecContext *c= NULL;

    AVFrame *frame;

    AVPacket pkt;

    int i, j, k, ret, got_output;

    int buffer_size;

    FILE *f;

    uint16_t *samples;

    float t, tincr;



    printf("Encode audio file %s\n", filename);



    /* find the MP2 encoder */

    codec = avcodec_find_encoder(AV_CODEC_ID_MP2);

    if (!codec) {

        fprintf(stderr, "Codec not found\n");

        exit(1);

    }



    c = avcodec_alloc_context3(codec);

    if (!c) {

        fprintf(stderr, "Could not allocate audio codec context\n");

        exit(1);

    }



    /* put sample parameters */

    c->bit_rate = 64000;



    /* check that the encoder supports s16 pcm input */

    c->sample_fmt = AV_SAMPLE_FMT_S16;

    if (!check_sample_fmt(codec, c->sample_fmt)) {

        fprintf(stderr, "Encoder does not support sample format %s",

                av_get_sample_fmt_name(c->sample_fmt));

        exit(1);

    }



    /* select other audio parameters supported by the encoder */

    c->sample_rate    = select_sample_rate(codec);

    c->channel_layout = select_channel_layout(codec);

    c->channels       = av_get_channel_layout_nb_channels(c->channel_layout);



    /* open it */

    if (avcodec_open2(c, codec, NULL) < 0) {

        fprintf(stderr, "Could not open codec\n");

        exit(1);

    }



    f = fopen(filename, "wb");

    if (!f) {

        fprintf(stderr, "Could not open %s\n", filename);

        exit(1);

    }



    /* frame containing input raw audio */

    frame = av_frame_alloc();

    if (!frame) {

        fprintf(stderr, "Could not allocate audio frame\n");

        exit(1);

    }



    frame->nb_samples     = c->frame_size;

    frame->format         = c->sample_fmt;

    frame->channel_layout = c->channel_layout;



    /* the codec gives us the frame size, in samples,

     * we calculate the size of the samples buffer in bytes */

    buffer_size = av_samples_get_buffer_size(NULL, c->channels, c->frame_size,

                                             c->sample_fmt, 0);

    if (!buffer_size) {

        fprintf(stderr, "Could not get sample buffer size\n");

        exit(1);

    }

    samples = av_malloc(buffer_size);

    if (!samples) {

        fprintf(stderr, "Could not allocate %d bytes for samples buffer\n",

                buffer_size);

        exit(1);

    }

    /* setup the data pointers in the AVFrame */

    ret = avcodec_fill_audio_frame(frame, c->channels, c->sample_fmt,

                                   (const uint8_t*)samples, buffer_size, 0);

    if (ret < 0) {

        fprintf(stderr, "Could not setup audio frame\n");

        exit(1);

    }



    /* encode a single tone sound */

    t = 0;

    tincr = 2 * M_PI * 440.0 / c->sample_rate;

    for(i=0;i<200;i++) {

        av_init_packet(&pkt);

        pkt.data = NULL; // packet data will be allocated by the encoder

        pkt.size = 0;



        for (j = 0; j < c->frame_size; j++) {

            samples[2*j] = (int)(sin(t) * 10000);



            for (k = 1; k < c->channels; k++)

                samples[2*j + k] = samples[2*j];

            t += tincr;

        }

        /* encode the samples */

        ret = avcodec_encode_audio2(c, &pkt, frame, &got_output);

        if (ret < 0) {

            fprintf(stderr, "Error encoding audio frame\n");

            exit(1);

        }

        if (got_output) {

            fwrite(pkt.data, 1, pkt.size, f);

            av_free_packet(&pkt);

        }

    }



    /* get the delayed frames */

    for (got_output = 1; got_output; i++) {

        ret = avcodec_encode_audio2(c, &pkt, NULL, &got_output);

        if (ret < 0) {

            fprintf(stderr, "Error encoding frame\n");

            exit(1);

        }



        if (got_output) {

            fwrite(pkt.data, 1, pkt.size, f);

            av_free_packet(&pkt);

        }

    }

    fclose(f);



    av_freep(&samples);

    av_frame_free(&frame);

    avcodec_close(c);

    av_free(c);

}

static void avconv_cleanup(int ret)

{

    int i, j;



    for (i = 0; i < nb_filtergraphs; i++) {

        FilterGraph *fg = filtergraphs[i];

        avfilter_graph_free(&fg->graph);

        for (j = 0; j < fg->nb_inputs; j++) {

            while (av_fifo_size(fg->inputs[j]->frame_queue)) {

                AVFrame *frame;

                av_fifo_generic_read(fg->inputs[j]->frame_queue, &frame,

                                     sizeof(frame), NULL);

                av_frame_free(&frame);

            }

            av_fifo_free(fg->inputs[j]->frame_queue);

            av_buffer_unref(&fg->inputs[j]->hw_frames_ctx);

            av_freep(&fg->inputs[j]->name);

            av_freep(&fg->inputs[j]);

        }

        av_freep(&fg->inputs);

        for (j = 0; j < fg->nb_outputs; j++) {

            av_freep(&fg->outputs[j]->name);

            av_freep(&fg->outputs[j]->formats);

            av_freep(&fg->outputs[j]->channel_layouts);

            av_freep(&fg->outputs[j]->sample_rates);

            av_freep(&fg->outputs[j]);

        }

        av_freep(&fg->outputs);

        av_freep(&fg->graph_desc);



        av_freep(&filtergraphs[i]);

    }

    av_freep(&filtergraphs);



    /* close files */

    for (i = 0; i < nb_output_files; i++) {

        OutputFile *of = output_files[i];

        AVFormatContext *s = of->ctx;

        if (s && s->oformat && !(s->oformat->flags & AVFMT_NOFILE) && s->pb)

            avio_close(s->pb);

        avformat_free_context(s);

        av_dict_free(&of->opts);



        av_freep(&output_files[i]);

    }

    for (i = 0; i < nb_output_streams; i++) {

        OutputStream *ost = output_streams[i];



        for (j = 0; j < ost->nb_bitstream_filters; j++)

            av_bsf_free(&ost->bsf_ctx[j]);

        av_freep(&ost->bsf_ctx);

        av_freep(&ost->bitstream_filters);



        av_frame_free(&ost->filtered_frame);



        av_parser_close(ost->parser);

        avcodec_free_context(&ost->parser_avctx);



        av_freep(&ost->forced_keyframes);

        av_freep(&ost->avfilter);

        av_freep(&ost->logfile_prefix);



        avcodec_free_context(&ost->enc_ctx);



        while (av_fifo_size(ost->muxing_queue)) {

            AVPacket pkt;

            av_fifo_generic_read(ost->muxing_queue, &pkt, sizeof(pkt), NULL);

            av_packet_unref(&pkt);

        }

        av_fifo_free(ost->muxing_queue);



        av_freep(&output_streams[i]);

    }

    for (i = 0; i < nb_input_files; i++) {

        avformat_close_input(&input_files[i]->ctx);

        av_freep(&input_files[i]);

    }

    for (i = 0; i < nb_input_streams; i++) {

        InputStream *ist = input_streams[i];



        av_frame_free(&ist->decoded_frame);

        av_frame_free(&ist->filter_frame);

        av_dict_free(&ist->decoder_opts);

        av_freep(&ist->filters);

        av_freep(&ist->hwaccel_device);



        avcodec_free_context(&ist->dec_ctx);



        av_freep(&input_streams[i]);

    }



    if (vstats_file)

        fclose(vstats_file);

    av_free(vstats_filename);



    av_freep(&input_streams);

    av_freep(&input_files);

    av_freep(&output_streams);

    av_freep(&output_files);



    uninit_opts();



    avformat_network_deinit();



    if (received_sigterm) {

        av_log(NULL, AV_LOG_INFO, "Received signal %d: terminating.\n",

               (int) received_sigterm);

        exit (255);

    }

}

static void dump_stream_format(AVFormatContext *ic, int i, int index, int is_output)

{

    char buf[256];

    int flags = (is_output ? ic->oformat->flags : ic->iformat->flags);

    AVStream *st = ic->streams[i];

    int g = ff_gcd(st->time_base.num, st->time_base.den);

    avcodec_string(buf, sizeof(buf), st->codec, is_output);

    av_log(NULL, AV_LOG_INFO, "    Stream #%d.%d", index, i);

    /* the pid is an important information, so we display it */

    /* XXX: add a generic system */

    if (flags & AVFMT_SHOW_IDS)

        av_log(NULL, AV_LOG_INFO, "[0x%x]", st->id);

    if (strlen(st->language) > 0)

        av_log(NULL, AV_LOG_INFO, "(%s)", st->language);

    av_log(NULL, AV_LOG_DEBUG, ", %d/%d", st->time_base.num/g, st->time_base.den/g);

    av_log(NULL, AV_LOG_INFO, ": %s", buf);

    if(st->codec->codec_type == CODEC_TYPE_VIDEO){

        if(st->r_frame_rate.den && st->r_frame_rate.num)

            av_log(NULL, AV_LOG_INFO, ", %5.2f fps(r)", av_q2d(st->r_frame_rate));

/*      else if(st->time_base.den && st->time_base.num)

            av_log(NULL, AV_LOG_INFO, ", %5.2f fps(m)", 1/av_q2d(st->time_base));*/

        else

            av_log(NULL, AV_LOG_INFO, ", %5.2f fps(c)", 1/av_q2d(st->codec->time_base));

    }

    av_log(NULL, AV_LOG_INFO, "\n");

}

static inline void rv34_decode_block(DCTELEM *dst, GetBitContext *gb, RV34VLC *rvlc, int fc, int sc, int q_dc, int q_ac1, int q_ac2)

{

    int code, pattern;



    code = get_vlc2(gb, rvlc->first_pattern[fc].table, 9, 2);



    pattern = code & 0x7;



    code >>= 3;

    decode_subblock3(dst, code, 0, gb, &rvlc->coefficient, q_dc, q_ac1, q_ac2);



    if(pattern & 4){

        code = get_vlc2(gb, rvlc->second_pattern[sc].table, 9, 2);

        decode_subblock(dst + 2, code, 0, gb, &rvlc->coefficient, q_ac2);

    }

    if(pattern & 2){ // Looks like coefficients 1 and 2 are swapped for this block

        code = get_vlc2(gb, rvlc->second_pattern[sc].table, 9, 2);

        decode_subblock(dst + 8*2, code, 1, gb, &rvlc->coefficient, q_ac2);

    }

    if(pattern & 1){

        code = get_vlc2(gb, rvlc->third_pattern[sc].table, 9, 2);

        decode_subblock(dst + 8*2+2, code, 0, gb, &rvlc->coefficient, q_ac2);

    }



}

AVFrameSideData *av_frame_new_side_data(AVFrame *frame,

                                        enum AVFrameSideDataType type,

                                        int size)

{

    AVFrameSideData *ret, **tmp;



    if (frame->nb_side_data > INT_MAX / sizeof(*frame->side_data) - 1)

        return NULL;



    tmp = av_realloc(frame->side_data,

                     (frame->nb_side_data + 1) * sizeof(*frame->side_data));

    if (!tmp)

        return NULL;

    frame->side_data = tmp;



    ret = av_mallocz(sizeof(*ret));

    if (!ret)

        return NULL;



    if (size > 0) {

        ret->buf = av_buffer_alloc(size);

        if (!ret->buf) {

            av_freep(&ret);

            return NULL;

        }



        ret->data = ret->buf->data;

        ret->size = size;

    }

    ret->type = type;



    frame->side_data[frame->nb_side_data++] = ret;



    return ret;

}

void ff_configure_buffers_for_index(AVFormatContext *s, int64_t time_tolerance)

{

    int ist1, ist2;

    int64_t pos_delta = 0;

    //We could use URLProtocol flags here but as many user applications do not use URLProtocols this would be unreliable

    const char *proto = avio_find_protocol_name(s->filename);



    if (!(strcmp(proto, "file") && strcmp(proto, "pipe") && strcmp(proto, "cache")))

        return;



    for (ist1 = 0; ist1 < s->nb_streams; ist1++) {

        AVStream *st1 = s->streams[ist1];

        for (ist2 = 0; ist2 < s->nb_streams; ist2++) {

            AVStream *st2 = s->streams[ist2];

            int i1, i2;



            if (ist1 == ist2)

                continue;



            for (i1 = i2 = 0; i1 < st1->nb_index_entries; i1++) {

                AVIndexEntry *e1 = &st1->index_entries[i1];

                int64_t e1_pts = av_rescale_q(e1->timestamp, st1->time_base, AV_TIME_BASE_Q);



                for (; i2 < st2->nb_index_entries; i2++) {

                    AVIndexEntry *e2 = &st2->index_entries[i2];

                    int64_t e2_pts = av_rescale_q(e2->timestamp, st2->time_base, AV_TIME_BASE_Q);

                    if (e2_pts - e1_pts < time_tolerance)

                        continue;

                    pos_delta = FFMAX(pos_delta, e1->pos - e2->pos);

                    break;

                }

            }

        }

    }



    pos_delta *= 2;

    /* XXX This could be adjusted depending on protocol*/

    if (s->pb->buffer_size < pos_delta && pos_delta < (1<<24)) {

        av_log(s, AV_LOG_VERBOSE, "Reconfiguring buffers to size %"PRId64"\n", pos_delta);

        ffio_set_buf_size(s->pb, pos_delta);

        s->pb->short_seek_threshold = FFMAX(s->pb->short_seek_threshold, pos_delta/2);

    }

}

int attribute_align_arg avcodec_decode_audio4(AVCodecContext *avctx,

                                              AVFrame *frame,

                                              int *got_frame_ptr,

                                              const AVPacket *avpkt)

{

    AVCodecInternal *avci = avctx->internal;

    int planar, channels;

    int ret = 0;



    *got_frame_ptr = 0;



    if (!avpkt->data && avpkt->size) {

        av_log(avctx, AV_LOG_ERROR, "invalid packet: NULL data, size != 0\n");


    }



    if (avctx->codec->type != AVMEDIA_TYPE_AUDIO) {

        av_log(avctx, AV_LOG_ERROR, "Invalid media type for audio\n");


    }



    avcodec_get_frame_defaults(frame);



    if (!avctx->refcounted_frames)

        av_frame_unref(&avci->to_free);



    if ((avctx->codec->capabilities & CODEC_CAP_DELAY) || avpkt->size || (avctx->active_thread_type & FF_THREAD_FRAME)) {

        uint8_t *side;

        int side_size;

        // copy to ensure we do not change avpkt

        AVPacket tmp = *avpkt;

        int did_split = av_packet_split_side_data(&tmp);

        apply_param_change(avctx, &tmp);



        avctx->pkt = &tmp;

        if (HAVE_THREADS && avctx->active_thread_type & FF_THREAD_FRAME)

            ret = ff_thread_decode_frame(avctx, frame, got_frame_ptr, &tmp);

        else {

            ret = avctx->codec->decode(avctx, frame, got_frame_ptr, &tmp);

            frame->pkt_dts = avpkt->dts;

        }

        if (ret >= 0 && *got_frame_ptr) {

            add_metadata_from_side_data(avctx, frame);

            avctx->frame_number++;

            av_frame_set_best_effort_timestamp(frame,

                                               guess_correct_pts(avctx,

                                                                 frame->pkt_pts,

                                                                 frame->pkt_dts));

            if (frame->format == AV_SAMPLE_FMT_NONE)

                frame->format = avctx->sample_fmt;

            if (!frame->channel_layout)

                frame->channel_layout = avctx->channel_layout;

            if (!av_frame_get_channels(frame))

                av_frame_set_channels(frame, avctx->channels);

            if (!frame->sample_rate)

                frame->sample_rate = avctx->sample_rate;

        }



        side= av_packet_get_side_data(avctx->pkt, AV_PKT_DATA_SKIP_SAMPLES, &side_size);

        if(side && side_size>=10) {

            avctx->internal->skip_samples = AV_RL32(side);

            av_log(avctx, AV_LOG_DEBUG, "skip %d samples due to side data\n",

                   avctx->internal->skip_samples);

        }

        if (avctx->internal->skip_samples && *got_frame_ptr) {

            if(frame->nb_samples <= avctx->internal->skip_samples){

                *got_frame_ptr = 0;

                avctx->internal->skip_samples -= frame->nb_samples;

                av_log(avctx, AV_LOG_DEBUG, "skip whole frame, skip left: %d\n",

                       avctx->internal->skip_samples);

            } else {

                av_samples_copy(frame->extended_data, frame->extended_data, 0, avctx->internal->skip_samples,

                                frame->nb_samples - avctx->internal->skip_samples, avctx->channels, frame->format);

                if(avctx->pkt_timebase.num && avctx->sample_rate) {

                    int64_t diff_ts = av_rescale_q(avctx->internal->skip_samples,

                                                   (AVRational){1, avctx->sample_rate},

                                                   avctx->pkt_timebase);

                    if(frame->pkt_pts!=AV_NOPTS_VALUE)

                        frame->pkt_pts += diff_ts;

                    if(frame->pkt_dts!=AV_NOPTS_VALUE)

                        frame->pkt_dts += diff_ts;

                    if (av_frame_get_pkt_duration(frame) >= diff_ts)

                        av_frame_set_pkt_duration(frame, av_frame_get_pkt_duration(frame) - diff_ts);

                } else {

                    av_log(avctx, AV_LOG_WARNING, "Could not update timestamps for skipped samples.\n");

                }

                av_log(avctx, AV_LOG_DEBUG, "skip %d/%d samples\n",

                       avctx->internal->skip_samples, frame->nb_samples);

                frame->nb_samples -= avctx->internal->skip_samples;

                avctx->internal->skip_samples = 0;

            }

        }



        avctx->pkt = NULL;

        if (did_split) {

            ff_packet_free_side_data(&tmp);

            if(ret == tmp.size)

                ret = avpkt->size;

        }



        if (ret >= 0 && *got_frame_ptr) {

            if (!avctx->refcounted_frames) {

                avci->to_free = *frame;

                avci->to_free.extended_data = avci->to_free.data;

                memset(frame->buf, 0, sizeof(frame->buf));

                frame->extended_buf    = NULL;

                frame->nb_extended_buf = 0;

            }

        } else if (frame->data[0])

            av_frame_unref(frame);

    }



    /* many decoders assign whole AVFrames, thus overwriting extended_data;

     * make sure it's set correctly; assume decoders that actually use

     * extended_data are doing it correctly */

    if (*got_frame_ptr) {

        planar   = av_sample_fmt_is_planar(frame->format);

        channels = av_frame_get_channels(frame);

        if (!(planar && channels > AV_NUM_DATA_POINTERS))

            frame->extended_data = frame->data;

    } else {

        frame->extended_data = NULL;

    }



    return ret;

}

static void vp56_decode_mb(VP56Context *s, int row, int col, int is_alpha)

{

    AVFrame *frame_current, *frame_ref;

    VP56mb mb_type;

    VP56Frame ref_frame;

    int b, ab, b_max, plane, off;



    if (s->frames[VP56_FRAME_CURRENT]->key_frame)

        mb_type = VP56_MB_INTRA;

    else

        mb_type = vp56_decode_mv(s, row, col);

    ref_frame = ff_vp56_reference_frame[mb_type];



    s->parse_coeff(s);



    vp56_add_predictors_dc(s, ref_frame);



    frame_current = s->frames[VP56_FRAME_CURRENT];

    frame_ref = s->frames[ref_frame];

    if (mb_type != VP56_MB_INTRA && !frame_ref->data[0])

        return;



    ab = 6*is_alpha;

    b_max = 6 - 2*is_alpha;



    switch (mb_type) {

        case VP56_MB_INTRA:

            for (b=0; b<b_max; b++) {

                plane = ff_vp56_b2p[b+ab];

                s->vp3dsp.idct_put(frame_current->data[plane] + s->block_offset[b],

                                s->stride[plane], s->block_coeff[b]);

            }

            break;



        case VP56_MB_INTER_NOVEC_PF:

        case VP56_MB_INTER_NOVEC_GF:

            for (b=0; b<b_max; b++) {

                plane = ff_vp56_b2p[b+ab];

                off = s->block_offset[b];

                s->hdsp.put_pixels_tab[1][0](frame_current->data[plane] + off,

                                             frame_ref->data[plane] + off,

                                             s->stride[plane], 8);

                s->vp3dsp.idct_add(frame_current->data[plane] + off,

                                s->stride[plane], s->block_coeff[b]);

            }

            break;



        case VP56_MB_INTER_DELTA_PF:

        case VP56_MB_INTER_V1_PF:

        case VP56_MB_INTER_V2_PF:

        case VP56_MB_INTER_DELTA_GF:

        case VP56_MB_INTER_4V:

        case VP56_MB_INTER_V1_GF:

        case VP56_MB_INTER_V2_GF:

            for (b=0; b<b_max; b++) {

                int x_off = b==1 || b==3 ? 8 : 0;

                int y_off = b==2 || b==3 ? 8 : 0;

                plane = ff_vp56_b2p[b+ab];

                vp56_mc(s, b, plane, frame_ref->data[plane], s->stride[plane],

                        16*col+x_off, 16*row+y_off);

                s->vp3dsp.idct_add(frame_current->data[plane] + s->block_offset[b],

                                s->stride[plane], s->block_coeff[b]);

            }

            break;

    }



    if (is_alpha) {

        s->block_coeff[4][0] = 0;

        s->block_coeff[5][0] = 0;

    }

}

void av_force_cpu_flags(int arg){

    if (   (arg & ( AV_CPU_FLAG_3DNOW    |

                    AV_CPU_FLAG_3DNOWEXT |

                    AV_CPU_FLAG_MMXEXT   |

                    AV_CPU_FLAG_SSE      |

                    AV_CPU_FLAG_SSE2     |

                    AV_CPU_FLAG_SSE2SLOW |

                    AV_CPU_FLAG_SSE3     |

                    AV_CPU_FLAG_SSE3SLOW |

                    AV_CPU_FLAG_SSSE3    |

                    AV_CPU_FLAG_SSE4     |

                    AV_CPU_FLAG_SSE42    |

                    AV_CPU_FLAG_AVX      |

                    AV_CPU_FLAG_AVXSLOW  |

                    AV_CPU_FLAG_XOP      |

                    AV_CPU_FLAG_FMA3     |

                    AV_CPU_FLAG_FMA4     |

                    AV_CPU_FLAG_AVX2     ))

        && !(arg & AV_CPU_FLAG_MMX)) {

        av_log(NULL, AV_LOG_WARNING, "MMX implied by specified flags\n");

        arg |= AV_CPU_FLAG_MMX;

    }



    flags   = arg;

    checked = arg != -1;

}

static int select_frame(AVFilterContext *ctx, AVFilterBufferRef *picref)

{

    SelectContext *select = ctx->priv;

    AVFilterLink *inlink = ctx->inputs[0];

    double res;



    if (isnan(select->var_values[VAR_START_PTS]))

        select->var_values[VAR_START_PTS] = TS2D(picref->pts);

    if (isnan(select->var_values[VAR_START_T]))

        select->var_values[VAR_START_T] = TS2D(picref->pts) * av_q2d(inlink->time_base);



    select->var_values[VAR_PTS] = TS2D(picref->pts);

    select->var_values[VAR_T  ] = picref->pts * av_q2d(inlink->time_base);

    select->var_values[VAR_POS] = picref->pos == -1 ? NAN : picref->pos;

    select->var_values[VAR_PREV_PTS] = TS2D(picref ->pts);



    select->var_values[VAR_INTERLACE_TYPE] =

        !picref->video->interlaced     ? INTERLACE_TYPE_P :

        picref->video->top_field_first ? INTERLACE_TYPE_T : INTERLACE_TYPE_B;

    select->var_values[VAR_PICT_TYPE] = picref->video->pict_type;



    res = av_expr_eval(select->expr, select->var_values, NULL);

    av_log(inlink->dst, AV_LOG_DEBUG,

           "n:%d pts:%d t:%f pos:%d interlace_type:%c key:%d pict_type:%c "

           "-> select:%f\n",

           (int)select->var_values[VAR_N],

           (int)select->var_values[VAR_PTS],

           select->var_values[VAR_T],

           (int)select->var_values[VAR_POS],

           select->var_values[VAR_INTERLACE_TYPE] == INTERLACE_TYPE_P ? 'P' :

           select->var_values[VAR_INTERLACE_TYPE] == INTERLACE_TYPE_T ? 'T' :

           select->var_values[VAR_INTERLACE_TYPE] == INTERLACE_TYPE_B ? 'B' : '?',

           (int)select->var_values[VAR_KEY],

           av_get_picture_type_char(select->var_values[VAR_PICT_TYPE]),

           res);



    select->var_values[VAR_N] += 1.0;



    if (res) {

        select->var_values[VAR_PREV_SELECTED_N]   = select->var_values[VAR_N];

        select->var_values[VAR_PREV_SELECTED_PTS] = select->var_values[VAR_PTS];

        select->var_values[VAR_PREV_SELECTED_T]   = select->var_values[VAR_T];

        select->var_values[VAR_SELECTED_N] += 1.0;

    }

    return res;

}

static int mov_write_identification(AVIOContext *pb, AVFormatContext *s)

{

    MOVMuxContext *mov = s->priv_data;

    int i;



    mov_write_ftyp_tag(pb,s);

    if (mov->mode == MODE_PSP) {

        int video_streams_nb = 0, audio_streams_nb = 0, other_streams_nb = 0;

        for (i = 0; i < s->nb_streams; i++) {

            AVStream *st = s->streams[i];

            if (st->codecpar->codec_type == AVMEDIA_TYPE_VIDEO)

                video_streams_nb++;

            else if (st->codecpar->codec_type == AVMEDIA_TYPE_AUDIO)

                audio_streams_nb++;

            else

                other_streams_nb++;

            }



        if (video_streams_nb != 1 || audio_streams_nb != 1 || other_streams_nb) {

            av_log(s, AV_LOG_ERROR, "PSP mode need one video and one audio stream\n");

            return AVERROR(EINVAL);

        }

        mov_write_uuidprof_tag(pb, s);

    }

    return 0;

}

static int motion_inter_block (bit_buffer_t *bitbuf,

			       uint8_t *current, uint8_t *previous, int pitch,

			       svq1_pmv_t *motion, int x, int y) {

  uint8_t    *src;

  uint8_t    *dst;

  svq1_pmv_t  mv;

  svq1_pmv_t *pmv[3];

  int	      result;



  /* predict and decode motion vector */

  pmv[0] = &motion[0];

  pmv[1] = &motion[(x / 8) + 2];

  pmv[2] = &motion[(x / 8) + 4];



  if (y == 0) {

    pmv[1] = pmv[0];

    pmv[2] = pmv[0];

  }



  result = decode_motion_vector (bitbuf, &mv, pmv);



  if (result != 0)

    return result;



  motion[0].x		= mv.x;

  motion[0].y		= mv.y;

  motion[(x / 8) + 2].x	= mv.x;

  motion[(x / 8) + 2].y	= mv.y;

  motion[(x / 8) + 3].x	= mv.x;

  motion[(x / 8) + 3].y	= mv.y;



  src = &previous[(x + (mv.x >> 1)) + (y + (mv.y >> 1))*pitch];

  dst = current;



  put_pixels_tab[((mv.y & 1) << 1) | (mv.x & 1)](dst,src,pitch,16);

  put_pixels_tab[((mv.y & 1) << 1) | (mv.x & 1)](dst+8,src+8,pitch,16);



  return 0;

}

static int swf_write_video(AVFormatContext *s, 

                           AVCodecContext *enc, const uint8_t *buf, int size)

{

    ByteIOContext *pb = &s->pb;

    static int tag_id = 0;



    if (enc->frame_number > 1) {

        /* remove the shape */

        put_swf_tag(s, TAG_REMOVEOBJECT);

        put_le16(pb, SHAPE_ID); /* shape ID */

        put_le16(pb, 1); /* depth */

        put_swf_end_tag(s);



        /* free the bitmap */

        put_swf_tag(s, TAG_FREECHARACTER);

        put_le16(pb, BITMAP_ID);

        put_swf_end_tag(s);

    }



    put_swf_tag(s, TAG_JPEG2 | TAG_LONG);



    put_le16(pb, tag_id); /* ID of the image */



    /* a dummy jpeg header seems to be required */

    put_byte(pb, 0xff); 

    put_byte(pb, 0xd8);

    put_byte(pb, 0xff);

    put_byte(pb, 0xd9);

    /* write the jpeg image */

    put_buffer(pb, buf, size);



    put_swf_end_tag(s);



    /* draw the shape */



    put_swf_tag(s, TAG_PLACEOBJECT);

    put_le16(pb, SHAPE_ID); /* shape ID */

    put_le16(pb, 1); /* depth */

    put_swf_matrix(pb, 1 << FRAC_BITS, 0, 0, 1 << FRAC_BITS, 0, 0);

    put_swf_end_tag(s);



    /* output the frame */

    put_swf_tag(s, TAG_SHOWFRAME);

    put_swf_end_tag(s);



    put_flush_packet(&s->pb);

    return 0;

}

static int mov_skip_multiple_stsd(MOVContext *c, AVIOContext *pb,

                                  int codec_tag, int format,

                                  int size)

{

    int video_codec_id = ff_codec_get_id(ff_codec_movvideo_tags, format);



    if (codec_tag &&

         (codec_tag != format &&

          (c->fc->video_codec_id ? video_codec_id != c->fc->video_codec_id

                                 : codec_tag != MKTAG('j','p','e','g')))) {

        /* Multiple fourcc, we skip JPEG. This is not correct, we should

         * export it as a separate AVStream but this needs a few changes

         * in the MOV demuxer, patch welcome. */



        av_log(c->fc, AV_LOG_WARNING, "multiple fourcc not supported\n");

        avio_skip(pb, size);

        return 1;

    }

    if ( codec_tag == AV_RL32("avc1") ||

         codec_tag == AV_RL32("hvc1") ||

         codec_tag == AV_RL32("hev1")

    )

        av_log(c->fc, AV_LOG_WARNING, "Concatenated H.264 or H.265 might not play correctly.\n");



    return 0;

}

void ff_slice_thread_free(AVCodecContext *avctx)

{

    SliceThreadContext *c = avctx->internal->thread_ctx;

    int i;



    pthread_mutex_lock(&c->current_job_lock);

    c->done = 1;

    pthread_cond_broadcast(&c->current_job_cond);

    for (i = 0; i < c->thread_count; i++)

        pthread_cond_broadcast(&c->progress_cond[i]);

    pthread_mutex_unlock(&c->current_job_lock);



    for (i=0; i<avctx->thread_count; i++)

         pthread_join(c->workers[i], NULL);



    for (i = 0; i < c->thread_count; i++) {

        pthread_mutex_destroy(&c->progress_mutex[i]);

        pthread_cond_destroy(&c->progress_cond[i]);

    }



    pthread_mutex_destroy(&c->current_job_lock);

    pthread_cond_destroy(&c->current_job_cond);

    pthread_cond_destroy(&c->last_job_cond);



    av_freep(&c->entries);

    av_freep(&c->progress_mutex);

    av_freep(&c->progress_cond);



    av_freep(&c->workers);

    av_freep(&avctx->internal->thread_ctx);

}

RTPDemuxContext *rtp_parse_open(AVFormatContext *s1, AVStream *st, URLContext *rtpc, int payload_type, RTPPayloadData *rtp_payload_data)

{

    RTPDemuxContext *s;



    s = av_mallocz(sizeof(RTPDemuxContext));

    if (!s)

        return NULL;

    s->payload_type = payload_type;

    s->last_rtcp_ntp_time = AV_NOPTS_VALUE;

    s->first_rtcp_ntp_time = AV_NOPTS_VALUE;

    s->ic = s1;

    s->st = st;

    s->rtp_payload_data = rtp_payload_data;

    rtp_init_statistics(&s->statistics, 0); // do we know the initial sequence from sdp?

    if (!strcmp(ff_rtp_enc_name(payload_type), "MP2T")) {

        s->ts = ff_mpegts_parse_open(s->ic);

        if (s->ts == NULL) {

            av_free(s);

            return NULL;

        }

    } else {

        av_set_pts_info(st, 32, 1, 90000);

        switch(st->codec->codec_id) {

        case CODEC_ID_MPEG1VIDEO:

        case CODEC_ID_MPEG2VIDEO:

        case CODEC_ID_MP2:

        case CODEC_ID_MP3:

        case CODEC_ID_MPEG4:

        case CODEC_ID_H263:

        case CODEC_ID_H264:

            st->need_parsing = AVSTREAM_PARSE_FULL;

            break;

        default:

            if (st->codec->codec_type == CODEC_TYPE_AUDIO) {

                av_set_pts_info(st, 32, 1, st->codec->sample_rate);

            }

            break;

        }

    }

    // needed to send back RTCP RR in RTSP sessions

    s->rtp_ctx = rtpc;

    gethostname(s->hostname, sizeof(s->hostname));

    return s;

}

static int http_send_data(HTTPContext *c, long cur_time)

{

    int len, ret;



    while (c->buffer_ptr >= c->buffer_end) {

        ret = http_prepare_data(c, cur_time);

        if (ret < 0)

            return -1;

        else if (ret == 0) {

            continue;

        } else {

            /* state change requested */

            return 0;

        }

    }



    if (c->buffer_end > c->buffer_ptr) {

        len = write(c->fd, c->buffer_ptr, c->buffer_end - c->buffer_ptr);

        if (len < 0) {

            if (errno != EAGAIN && errno != EINTR) {

                /* error : close connection */

                return -1;

            }

        } else {

            c->buffer_ptr += len;

            c->data_count += len;

            if (c->stream)

                c->stream->bytes_served += len;

        }

    }

    return 0;

}

