static int mov_read_ddts(MOVContext *c, AVIOContext *pb, MOVAtom atom)

{

    const uint32_t ddts_size = 20;

    AVStream *st = NULL;

    uint8_t *buf = NULL;

    uint32_t frame_duration_code = 0;

    uint32_t channel_layout_code = 0;

    GetBitContext gb;



    buf = av_malloc(ddts_size + AV_INPUT_BUFFER_PADDING_SIZE);

    if (!buf) {

        return AVERROR(ENOMEM);

    }

    if (avio_read(pb, buf, ddts_size) < ddts_size) {


        return AVERROR_INVALIDDATA;

    }



    init_get_bits(&gb, buf, 8*ddts_size);



    if (c->fc->nb_streams < 1) {


        return 0;

    }

    st = c->fc->streams[c->fc->nb_streams-1];



    st->codecpar->sample_rate = get_bits_long(&gb, 32);

    if (st->codecpar->sample_rate <= 0) {

        av_log(c->fc, AV_LOG_ERROR, "Invalid sample rate %d\n", st->codecpar->sample_rate);


        return AVERROR_INVALIDDATA;

    }

    skip_bits_long(&gb, 32); /* max bitrate */

    st->codecpar->bit_rate = get_bits_long(&gb, 32);

    st->codecpar->bits_per_coded_sample = get_bits(&gb, 8);

    frame_duration_code = get_bits(&gb, 2);

    skip_bits(&gb, 30); /* various fields */

    channel_layout_code = get_bits(&gb, 16);



    st->codecpar->frame_size =

            (frame_duration_code == 0) ? 512 :

            (frame_duration_code == 1) ? 1024 :

            (frame_duration_code == 2) ? 2048 :

            (frame_duration_code == 3) ? 4096 : 0;



    if (channel_layout_code > 0xff) {

        av_log(c->fc, AV_LOG_WARNING, "Unsupported DTS audio channel layout");

    }

    st->codecpar->channel_layout =

            ((channel_layout_code & 0x1) ? AV_CH_FRONT_CENTER : 0) |

            ((channel_layout_code & 0x2) ? AV_CH_FRONT_LEFT : 0) |

            ((channel_layout_code & 0x2) ? AV_CH_FRONT_RIGHT : 0) |

            ((channel_layout_code & 0x4) ? AV_CH_SIDE_LEFT : 0) |

            ((channel_layout_code & 0x4) ? AV_CH_SIDE_RIGHT : 0) |

            ((channel_layout_code & 0x8) ? AV_CH_LOW_FREQUENCY : 0);



    st->codecpar->channels = av_get_channel_layout_nb_channels(st->codecpar->channel_layout);




    return 0;

}

static int mkv_write_tags(AVFormatContext *s)

{

    ebml_master tags = {0};

    int i, ret;



    ff_metadata_conv_ctx(s, ff_mkv_metadata_conv, NULL);



    if (av_dict_get(s->metadata, "", NULL, AV_DICT_IGNORE_SUFFIX)) {

        ret = mkv_write_tag(s, s->metadata, 0, 0, &tags);

        if (ret < 0) return ret;

    }



    for (i = 0; i < s->nb_streams; i++) {

        AVStream *st = s->streams[i];



        if (!av_dict_get(st->metadata, "", 0, AV_DICT_IGNORE_SUFFIX))

            continue;



        ret = mkv_write_tag(s, st->metadata, MATROSKA_ID_TAGTARGETS_TRACKUID, i + 1, &tags);

        if (ret < 0) return ret;

    }



    for (i = 0; i < s->nb_chapters; i++) {

        AVChapter *ch = s->chapters[i];



        if (!av_dict_get(ch->metadata, "", NULL, AV_DICT_IGNORE_SUFFIX))

            continue;



        ret = mkv_write_tag(s, ch->metadata, MATROSKA_ID_TAGTARGETS_CHAPTERUID, ch->id, &tags);

        if (ret < 0) return ret;

    }



    if (tags.pos)

        end_ebml_master(s->pb, tags);

    return 0;

}

static av_always_inline void mc_chroma_dir(VP9Context *s, vp9_mc_func(*mc)[2],

                                           uint8_t *dst_u, uint8_t *dst_v,

                                           ptrdiff_t dst_stride,

                                           const uint8_t *ref_u,

                                           ptrdiff_t src_stride_u,

                                           const uint8_t *ref_v,

                                           ptrdiff_t src_stride_v,

                                           ThreadFrame *ref_frame,

                                           ptrdiff_t y, ptrdiff_t x,

                                           const VP56mv *mv,

                                           int bw, int bh, int w, int h)

{

    int mx = mv->x, my = mv->y;

    int th;



    y     += my >> 4;

    x     += mx >> 4;

    ref_u += y * src_stride_u + x;

    ref_v += y * src_stride_v + x;

    mx    &= 15;

    my    &= 15;



    // we use +7 because the last 7 pixels of each sbrow can be changed in

    // the longest loopfilter of the next sbrow

    th = (y + bh + 4 * !!my + 7) >> 5;

    ff_thread_await_progress(ref_frame, FFMAX(th, 0), 0);



    // FIXME bilinear filter only needs 0/1 pixels, not 3/4

    if (x < !!mx * 3 || y < !!my * 3 ||

        x + !!mx * 4 > w - bw || y + !!my * 4 > h - bh) {

        s->vdsp.emulated_edge_mc(s->edge_emu_buffer,

                                 ref_u - !!my * 3 * src_stride_u - !!mx * 3,

                                 80,

                                 src_stride_u,

                                 bw + !!mx * 7, bh + !!my * 7,

                                 x - !!mx * 3, y - !!my * 3, w, h);

        ref_u = s->edge_emu_buffer + !!my * 3 * 80 + !!mx * 3;

        mc[!!mx][!!my](dst_u, dst_stride, ref_u, 80, bh, mx, my);



        s->vdsp.emulated_edge_mc(s->edge_emu_buffer,

                                 ref_v - !!my * 3 * src_stride_v - !!mx * 3,

                                 80,

                                 src_stride_v,

                                 bw + !!mx * 7, bh + !!my * 7,

                                 x - !!mx * 3, y - !!my * 3, w, h);

        ref_v = s->edge_emu_buffer + !!my * 3 * 80 + !!mx * 3;

        mc[!!mx][!!my](dst_v, dst_stride, ref_v, 80, bh, mx, my);

    } else {

        mc[!!mx][!!my](dst_u, dst_stride, ref_u, src_stride_u, bh, mx, my);

        mc[!!mx][!!my](dst_v, dst_stride, ref_v, src_stride_v, bh, mx, my);

    }

}

void ff_thread_report_progress(ThreadFrame *f, int n, int field)

{

    PerThreadContext *p;

    atomic_int *progress = f->progress ? (atomic_int*)f->progress->data : NULL;



    if (!progress ||

        atomic_load_explicit(&progress[field], memory_order_relaxed) >= n)

        return;



    p = f->owner[field]->internal->thread_ctx;



    if (f->owner[field]->debug&FF_DEBUG_THREADS)

        av_log(f->owner[field], AV_LOG_DEBUG,

               "%p finished %d field %d\n", progress, n, field);



    pthread_mutex_lock(&p->progress_mutex);



    atomic_store_explicit(&progress[field], n, memory_order_release);



    pthread_cond_broadcast(&p->progress_cond);

    pthread_mutex_unlock(&p->progress_mutex);

}

static inline int64_t bs_get_v(const uint8_t **bs)

{

    int64_t v = 0;

    int br = 0;

    int c;



    do {

        c = **bs; (*bs)++;

        v <<= 7;

        v |= c & 0x7F;

        br++;

        if (br > 10)

            return -1;

    } while (c & 0x80);



    return v - br;

}

static int vp6_parse_header(VP56Context *s, const uint8_t *buf, int buf_size)

{

    VP56RangeCoder *c = &s->c;

    int parse_filter_info = 0;

    int coeff_offset = 0;

    int vrt_shift = 0;

    int sub_version;

    int rows, cols;

    int res = 0;

    int ret;

    int separated_coeff = buf[0] & 1;



    s->frames[VP56_FRAME_CURRENT]->key_frame = !(buf[0] & 0x80);

    ff_vp56_init_dequant(s, (buf[0] >> 1) & 0x3F);



    if (s->frames[VP56_FRAME_CURRENT]->key_frame) {

        sub_version = buf[1] >> 3;

        if (sub_version > 8)

            return AVERROR_INVALIDDATA;

        s->filter_header = buf[1] & 0x06;

        if (buf[1] & 1) {

            avpriv_report_missing_feature(s->avctx, "Interlacing");

            return AVERROR_PATCHWELCOME;

        }

        if (separated_coeff || !s->filter_header) {

            coeff_offset = AV_RB16(buf+2) - 2;

            buf += 2;

            buf_size -= 2;

        }



        rows = buf[2];  /* number of stored macroblock rows */

        cols = buf[3];  /* number of stored macroblock cols */

        /* buf[4] is number of displayed macroblock rows */

        /* buf[5] is number of displayed macroblock cols */

        if (!rows || !cols) {

            av_log(s->avctx, AV_LOG_ERROR, "Invalid size %dx%d\n", cols << 4, rows << 4);

            return AVERROR_INVALIDDATA;

        }



        if (!s->macroblocks || /* first frame */

            16*cols != s->avctx->coded_width ||

            16*rows != s->avctx->coded_height) {

            if (s->avctx->extradata_size == 0 &&

                FFALIGN(s->avctx->width,  16) == 16 * cols &&

                FFALIGN(s->avctx->height, 16) == 16 * rows) {

                // We assume this is properly signalled container cropping,

                // in an F4V file. Just set the coded_width/height, don't

                // touch the cropped ones.

                s->avctx->coded_width  = 16 * cols;

                s->avctx->coded_height = 16 * rows;

            } else {

                ret = ff_set_dimensions(s->avctx, 16 * cols, 16 * rows);

                if (ret < 0)

                    return ret;



                if (s->avctx->extradata_size == 1) {

                    s->avctx->width  -= s->avctx->extradata[0] >> 4;

                    s->avctx->height -= s->avctx->extradata[0] & 0x0F;

                }

            }

            res = VP56_SIZE_CHANGE;

        }



        ret = ff_vp56_init_range_decoder(c, buf+6, buf_size-6);

        if (ret < 0)

            return ret;

        vp56_rac_gets(c, 2);



        parse_filter_info = s->filter_header;

        if (sub_version < 8)

            vrt_shift = 5;

        s->sub_version = sub_version;

        s->golden_frame = 0;

    } else {

        if (!s->sub_version || !s->avctx->coded_width || !s->avctx->coded_height)

            return AVERROR_INVALIDDATA;



        if (separated_coeff || !s->filter_header) {

            coeff_offset = AV_RB16(buf+1) - 2;

            buf += 2;

            buf_size -= 2;

        }

        ret = ff_vp56_init_range_decoder(c, buf+1, buf_size-1);

        if (ret < 0)

            return ret;



        s->golden_frame = vp56_rac_get(c);

        if (s->filter_header) {

            s->deblock_filtering = vp56_rac_get(c);

            if (s->deblock_filtering)

                vp56_rac_get(c);

            if (s->sub_version > 7)

                parse_filter_info = vp56_rac_get(c);

        }

    }



    if (parse_filter_info) {

        if (vp56_rac_get(c)) {

            s->filter_mode = 2;

            s->sample_variance_threshold = vp56_rac_gets(c, 5) << vrt_shift;

            s->max_vector_length = 2 << vp56_rac_gets(c, 3);

        } else if (vp56_rac_get(c)) {

            s->filter_mode = 1;

        } else {

            s->filter_mode = 0;

        }

        if (s->sub_version > 7)

            s->filter_selection = vp56_rac_gets(c, 4);

        else

            s->filter_selection = 16;

    }



    s->use_huffman = vp56_rac_get(c);



    s->parse_coeff = vp6_parse_coeff;

    if (coeff_offset) {

        buf      += coeff_offset;

        buf_size -= coeff_offset;

        if (buf_size < 0) {

            if (s->frames[VP56_FRAME_CURRENT]->key_frame)

                ff_set_dimensions(s->avctx, 0, 0);

            return AVERROR_INVALIDDATA;

        }

        if (s->use_huffman) {

            s->parse_coeff = vp6_parse_coeff_huffman;

            init_get_bits(&s->gb, buf, buf_size<<3);

        } else {

            ret = ff_vp56_init_range_decoder(&s->cc, buf, buf_size);

            if (ret < 0)

                return ret;

            s->ccp = &s->cc;

        }

    } else {

        s->ccp = &s->c;

    }



    return res;

}

static void find_best_state(uint8_t best_state[256][256],

                            const uint8_t one_state[256])

{

    int i, j, k, m;

    double l2tab[256];



    for (i = 1; i < 256; i++)

        l2tab[i] = log2(i / 256.0);



    for (i = 0; i < 256; i++) {

        double best_len[256];

        double p = i / 256.0;



        for (j = 0; j < 256; j++)

            best_len[j] = 1 << 30;



        for (j = FFMAX(i - 10, 1); j < FFMIN(i + 11, 256); j++) {

            double occ[256] = { 0 };

            double len      = 0;

            occ[j] = 1.0;

            for (k = 0; k < 256; k++) {

                double newocc[256] = { 0 };

                for (m = 1; m < 256; m++)

                    if (occ[m]) {

                        len -= occ[m] *     (p  * l2tab[m] +

                                        (1 - p) * l2tab[256 - m]);

                    }

                if (len < best_len[k]) {

                    best_len[k]      = len;

                    best_state[i][k] = j;

                }

                for (m = 0; m < 256; m++)

                    if (occ[m]) {

                        newocc[one_state[m]]             += occ[m] * p;

                        newocc[256 - one_state[256 - m]] += occ[m] * (1 - p);

                    }

                memcpy(occ, newocc, sizeof(occ));

            }

        }

    }

}

static inline int parse_nal_units(AVCodecParserContext *s, const uint8_t *buf,
                           int buf_size, AVCodecContext *avctx)
{
    HEVCParserContext *ctx = s->priv_data;
    HEVCContext       *h   = &ctx->h;
    GetBitContext      *gb;
    SliceHeader        *sh = &h->sh;
    HEVCParamSets *ps = &h->ps;
    H2645Packet   *pkt = &ctx->pkt;
    const uint8_t *buf_end = buf + buf_size;
    int state = -1, i;
    H2645NAL *nal;
    int is_global = buf == avctx->extradata;
    if (!h->HEVClc)
        h->HEVClc = av_mallocz(sizeof(HEVCLocalContext));
    if (!h->HEVClc)
        return AVERROR(ENOMEM);
    gb = &h->HEVClc->gb;
    /* set some sane default values */
    s->pict_type         = AV_PICTURE_TYPE_I;
    s->key_frame         = 0;
    s->picture_structure = AV_PICTURE_STRUCTURE_UNKNOWN;
    h->avctx = avctx;
    if (!buf_size)
        return 0;
    if (pkt->nals_allocated < 1) {
        H2645NAL *tmp = av_realloc_array(pkt->nals, 1, sizeof(*tmp));
        if (!tmp)
            return AVERROR(ENOMEM);
        pkt->nals = tmp;
        memset(pkt->nals, 0, sizeof(*tmp));
        pkt->nals_allocated = 1;
    }
    nal = &pkt->nals[0];
    for (;;) {
        int src_length, consumed;
        int ret;
        buf = avpriv_find_start_code(buf, buf_end, &state);
        if (--buf + 2 >= buf_end)
            break;
        src_length = buf_end - buf;
        h->nal_unit_type = (*buf >> 1) & 0x3f;
        h->temporal_id   = (*(buf + 1) & 0x07) - 1;
        if (h->nal_unit_type <= NAL_CRA_NUT) {
            // Do not walk the whole buffer just to decode slice segment header
            if (src_length > 20)
                src_length = 20;
        }
        consumed = ff_h2645_extract_rbsp(buf, src_length, nal);
        if (consumed < 0)
            return consumed;
        ret = init_get_bits8(gb, nal->data + 2, nal->size);
        if (ret < 0)
            return ret;
        switch (h->nal_unit_type) {
        case NAL_VPS:
            ff_hevc_decode_nal_vps(gb, avctx, ps);
            break;
        case NAL_SPS:
            ff_hevc_decode_nal_sps(gb, avctx, ps, 1);
            break;
        case NAL_PPS:
            ff_hevc_decode_nal_pps(gb, avctx, ps);
            break;
        case NAL_SEI_PREFIX:
        case NAL_SEI_SUFFIX:
            ff_hevc_decode_nal_sei(h);
            break;
        case NAL_TRAIL_N:
        case NAL_TRAIL_R:
        case NAL_TSA_N:
        case NAL_TSA_R:
        case NAL_STSA_N:
        case NAL_STSA_R:
        case NAL_RADL_N:
        case NAL_RADL_R:
        case NAL_RASL_N:
        case NAL_RASL_R:
        case NAL_BLA_W_LP:
        case NAL_BLA_W_RADL:
        case NAL_BLA_N_LP:
        case NAL_IDR_W_RADL:
        case NAL_IDR_N_LP:
        case NAL_CRA_NUT:
            if (is_global) {
                av_log(avctx, AV_LOG_ERROR, "Invalid NAL unit: %d\n", h->nal_unit_type);
                return AVERROR_INVALIDDATA;
            }
            sh->first_slice_in_pic_flag = get_bits1(gb);
            s->picture_structure = h->picture_struct;
            s->field_order = h->picture_struct;
            if (IS_IRAP(h)) {
                s->key_frame = 1;
                sh->no_output_of_prior_pics_flag = get_bits1(gb);
            }
            sh->pps_id = get_ue_golomb(gb);
            if (sh->pps_id >= MAX_PPS_COUNT || !ps->pps_list[sh->pps_id]) {
                av_log(avctx, AV_LOG_ERROR, "PPS id out of range: %d\n", sh->pps_id);
                return AVERROR_INVALIDDATA;
            }
            ps->pps = (HEVCPPS*)ps->pps_list[sh->pps_id]->data;
            if (ps->pps->sps_id >= MAX_SPS_COUNT || !ps->sps_list[ps->pps->sps_id]) {
                av_log(avctx, AV_LOG_ERROR, "SPS id out of range: %d\n", ps->pps->sps_id);
                return AVERROR_INVALIDDATA;
            }
            if (ps->sps != (HEVCSPS*)ps->sps_list[ps->pps->sps_id]->data) {
                ps->sps = (HEVCSPS*)ps->sps_list[ps->pps->sps_id]->data;
                ps->vps = (HEVCVPS*)ps->vps_list[ps->sps->vps_id]->data;
            }
            if (!sh->first_slice_in_pic_flag) {
                int slice_address_length;
                if (ps->pps->dependent_slice_segments_enabled_flag)
                    sh->dependent_slice_segment_flag = get_bits1(gb);
                else
                    sh->dependent_slice_segment_flag = 0;
                slice_address_length = av_ceil_log2_c(ps->sps->ctb_width *
                                                      ps->sps->ctb_height);
                sh->slice_segment_addr = get_bitsz(gb, slice_address_length);
                if (sh->slice_segment_addr >= ps->sps->ctb_width * ps->sps->ctb_height) {
                    av_log(avctx, AV_LOG_ERROR, "Invalid slice segment address: %u.\n",
                           sh->slice_segment_addr);
                    return AVERROR_INVALIDDATA;
                }
            } else
                sh->dependent_slice_segment_flag = 0;
            if (sh->dependent_slice_segment_flag)
                break;
            for (i = 0; i < ps->pps->num_extra_slice_header_bits; i++)
                skip_bits(gb, 1); // slice_reserved_undetermined_flag[]
            sh->slice_type = get_ue_golomb(gb);
            if (!(sh->slice_type == I_SLICE || sh->slice_type == P_SLICE ||
                  sh->slice_type == B_SLICE)) {
                av_log(avctx, AV_LOG_ERROR, "Unknown slice type: %d.\n",
                       sh->slice_type);
                return AVERROR_INVALIDDATA;
            }
            s->pict_type = sh->slice_type == B_SLICE ? AV_PICTURE_TYPE_B :
                           sh->slice_type == P_SLICE ? AV_PICTURE_TYPE_P :
                                                       AV_PICTURE_TYPE_I;
            if (ps->pps->output_flag_present_flag)
                sh->pic_output_flag = get_bits1(gb);
            if (ps->sps->separate_colour_plane_flag)
                sh->colour_plane_id = get_bits(gb, 2);
            if (!IS_IDR(h)) {
                sh->pic_order_cnt_lsb = get_bits(gb, ps->sps->log2_max_poc_lsb);
                s->output_picture_number = h->poc = ff_hevc_compute_poc(h, sh->pic_order_cnt_lsb);
            } else
                s->output_picture_number = h->poc = 0;
            if (h->temporal_id == 0 &&
                h->nal_unit_type != NAL_TRAIL_N &&
                h->nal_unit_type != NAL_TSA_N &&
                h->nal_unit_type != NAL_STSA_N &&
                h->nal_unit_type != NAL_RADL_N &&
                h->nal_unit_type != NAL_RASL_N &&
                h->nal_unit_type != NAL_RADL_R &&
                h->nal_unit_type != NAL_RASL_R)
                h->pocTid0 = h->poc;
            return 0; /* no need to evaluate the rest */
        }
        buf += consumed;
    }
    /* didn't find a picture! */
    if (!is_global)
        av_log(h->avctx, AV_LOG_ERROR, "missing picture in access unit\n");
    return -1;
}

static float ssim_end4(int sum0[5][4], int sum1[5][4], int width)

{

    float ssim = 0.0;

    int i;



    for (i = 0; i < width; i++)

        ssim += ssim_end1(sum0[i][0] + sum0[i + 1][0] + sum1[i][0] + sum1[i + 1][0],

                          sum0[i][1] + sum0[i + 1][1] + sum1[i][1] + sum1[i + 1][1],

                          sum0[i][2] + sum0[i + 1][2] + sum1[i][2] + sum1[i + 1][2],

                          sum0[i][3] + sum0[i + 1][3] + sum1[i][3] + sum1[i + 1][3]);

    return ssim;

}

static void avc_loopfilter_luma_intra_edge_hor_msa(uint8_t *data,

                                                   uint8_t alpha_in,

                                                   uint8_t beta_in,

                                                   uint32_t img_width)

{

    v16u8 p2_asub_p0, q2_asub_q0, p0_asub_q0;

    v16u8 alpha, beta;

    v16u8 is_less_than, is_less_than_beta, negate_is_less_than_beta;

    v16u8 p2, p1, p0, q0, q1, q2;

    v16u8 p3_org, p2_org, p1_org, p0_org, q0_org, q1_org, q2_org, q3_org;

    v8i16 p1_org_r, p0_org_r, q0_org_r, q1_org_r;

    v8i16 p1_org_l, p0_org_l, q0_org_l, q1_org_l;

    v8i16 p2_r = { 0 };

    v8i16 p1_r = { 0 };

    v8i16 p0_r = { 0 };

    v8i16 q0_r = { 0 };

    v8i16 q1_r = { 0 };

    v8i16 q2_r = { 0 };

    v8i16 p2_l = { 0 };

    v8i16 p1_l = { 0 };

    v8i16 p0_l = { 0 };

    v8i16 q0_l = { 0 };

    v8i16 q1_l = { 0 };

    v8i16 q2_l = { 0 };

    v16u8 tmp_flag;

    v16i8 zero = { 0 };



    alpha = (v16u8) __msa_fill_b(alpha_in);

    beta = (v16u8) __msa_fill_b(beta_in);



    p1_org = LOAD_UB(data - (img_width << 1));

    p0_org = LOAD_UB(data - img_width);

    q0_org = LOAD_UB(data);

    q1_org = LOAD_UB(data + img_width);



    {

        v16u8 p1_asub_p0, q1_asub_q0, is_less_than_alpha;



        p0_asub_q0 = __msa_asub_u_b(p0_org, q0_org);

        p1_asub_p0 = __msa_asub_u_b(p1_org, p0_org);

        q1_asub_q0 = __msa_asub_u_b(q1_org, q0_org);



        is_less_than_alpha = (p0_asub_q0 < alpha);

        is_less_than_beta = (p1_asub_p0 < beta);

        is_less_than = is_less_than_beta & is_less_than_alpha;

        is_less_than_beta = (q1_asub_q0 < beta);

        is_less_than = is_less_than_beta & is_less_than;

    }



    if (!__msa_test_bz_v(is_less_than)) {

        q2_org = LOAD_UB(data + (2 * img_width));

        p3_org = LOAD_UB(data - (img_width << 2));

        p2_org = LOAD_UB(data - (3 * img_width));



        p1_org_r = (v8i16) __msa_ilvr_b(zero, (v16i8) p1_org);

        p0_org_r = (v8i16) __msa_ilvr_b(zero, (v16i8) p0_org);

        q0_org_r = (v8i16) __msa_ilvr_b(zero, (v16i8) q0_org);



        p1_org_l = (v8i16) __msa_ilvl_b(zero, (v16i8) p1_org);

        p0_org_l = (v8i16) __msa_ilvl_b(zero, (v16i8) p0_org);

        q0_org_l = (v8i16) __msa_ilvl_b(zero, (v16i8) q0_org);



        tmp_flag = alpha >> 2;

        tmp_flag = tmp_flag + 2;

        tmp_flag = (p0_asub_q0 < tmp_flag);



        p2_asub_p0 = __msa_asub_u_b(p2_org, p0_org);

        is_less_than_beta = (p2_asub_p0 < beta);

        is_less_than_beta = is_less_than_beta & tmp_flag;



        negate_is_less_than_beta = __msa_xori_b(is_less_than_beta, 0xff);

        is_less_than_beta = is_less_than_beta & is_less_than;

        negate_is_less_than_beta = negate_is_less_than_beta & is_less_than;



        {

            v8u16 is_less_than_beta_l, is_less_than_beta_r;



            q1_org_r = (v8i16) __msa_ilvr_b(zero, (v16i8) q1_org);



            is_less_than_beta_r =

                (v8u16) __msa_sldi_b((v16i8) is_less_than_beta, zero, 8);

            if (!__msa_test_bz_v((v16u8) is_less_than_beta_r)) {

                v8i16 p3_org_r;



                p3_org_r = (v8i16) __msa_ilvr_b(zero, (v16i8) p3_org);

                p2_r = (v8i16) __msa_ilvr_b(zero, (v16i8) p2_org);



                AVC_LOOP_FILTER_P0P1P2_OR_Q0Q1Q2(p3_org_r, p0_org_r,

                                                 q0_org_r, p1_org_r,

                                                 p2_r, q1_org_r,

                                                 p0_r, p1_r, p2_r);

            }



            q1_org_l = (v8i16) __msa_ilvl_b(zero, (v16i8) q1_org);



            is_less_than_beta_l =

                (v8u16) __msa_sldi_b(zero, (v16i8) is_less_than_beta, 8);



            if (!__msa_test_bz_v((v16u8) is_less_than_beta_l)) {

                v8i16 p3_org_l;



                p3_org_l = (v8i16) __msa_ilvl_b(zero, (v16i8) p3_org);

                p2_l = (v8i16) __msa_ilvl_b(zero, (v16i8) p2_org);



                AVC_LOOP_FILTER_P0P1P2_OR_Q0Q1Q2(p3_org_l, p0_org_l,

                                                 q0_org_l, p1_org_l,

                                                 p2_l, q1_org_l,

                                                 p0_l, p1_l, p2_l);

            }

        }



        /* combine and store */

        if (!__msa_test_bz_v(is_less_than_beta)) {

            p0 = (v16u8) __msa_pckev_b((v16i8) p0_l, (v16i8) p0_r);

            p1 = (v16u8) __msa_pckev_b((v16i8) p1_l, (v16i8) p1_r);

            p2 = (v16u8) __msa_pckev_b((v16i8) p2_l, (v16i8) p2_r);



            p0_org = __msa_bmnz_v(p0_org, p0, is_less_than_beta);

            p1_org = __msa_bmnz_v(p1_org, p1, is_less_than_beta);

            p2_org = __msa_bmnz_v(p2_org, p2, is_less_than_beta);



            STORE_UB(p1_org, data - (2 * img_width));

            STORE_UB(p2_org, data - (3 * img_width));

        }



        {

            v8u16 negate_is_less_than_beta_r, negate_is_less_than_beta_l;



            negate_is_less_than_beta_r =

                (v8u16) __msa_sldi_b((v16i8) negate_is_less_than_beta, zero, 8);

            if (!__msa_test_bz_v((v16u8) negate_is_less_than_beta_r)) {

                AVC_LOOP_FILTER_P0_OR_Q0(p0_org_r, q1_org_r, p1_org_r, p0_r);

            }



            negate_is_less_than_beta_l =

                (v8u16) __msa_sldi_b(zero, (v16i8) negate_is_less_than_beta, 8);

            if (!__msa_test_bz_v((v16u8) negate_is_less_than_beta_l)) {

                AVC_LOOP_FILTER_P0_OR_Q0(p0_org_l, q1_org_l, p1_org_l, p0_l);

            }

        }



        /* combine */

        if (!__msa_test_bz_v(negate_is_less_than_beta)) {

            p0 = (v16u8) __msa_pckev_b((v16i8) p0_l, (v16i8) p0_r);

            p0_org = __msa_bmnz_v(p0_org, p0, negate_is_less_than_beta);

        }



        STORE_UB(p0_org, data - img_width);



        /* if (tmpFlag && (unsigned)ABS(q2-q0) < thresholds->beta_in) */



        q3_org = LOAD_UB(data + (3 * img_width));



        q2_asub_q0 = __msa_asub_u_b(q2_org, q0_org);

        is_less_than_beta = (q2_asub_q0 < beta);

        is_less_than_beta = is_less_than_beta & tmp_flag;

        negate_is_less_than_beta = __msa_xori_b(is_less_than_beta, 0xff);

        is_less_than_beta = is_less_than_beta & is_less_than;

        negate_is_less_than_beta = negate_is_less_than_beta & is_less_than;



        {

            v8u16 is_less_than_beta_l, is_less_than_beta_r;



            is_less_than_beta_r =

                (v8u16) __msa_sldi_b((v16i8) is_less_than_beta, zero, 8);

            if (!__msa_test_bz_v((v16u8) is_less_than_beta_r)) {

                v8i16 q3_org_r;



                q3_org_r = (v8i16) __msa_ilvr_b(zero, (v16i8) q3_org);

                q2_r = (v8i16) __msa_ilvr_b(zero, (v16i8) q2_org);



                AVC_LOOP_FILTER_P0P1P2_OR_Q0Q1Q2(q3_org_r, q0_org_r,

                                                 p0_org_r, q1_org_r,

                                                 q2_r, p1_org_r,

                                                 q0_r, q1_r, q2_r);

            }



            is_less_than_beta_l =

                (v8u16) __msa_sldi_b(zero, (v16i8) is_less_than_beta, 8);

            if (!__msa_test_bz_v((v16u8) is_less_than_beta_l)) {

                v8i16 q3_org_l;



                q3_org_l = (v8i16) __msa_ilvl_b(zero, (v16i8) q3_org);

                q2_l = (v8i16) __msa_ilvl_b(zero, (v16i8) q2_org);



                AVC_LOOP_FILTER_P0P1P2_OR_Q0Q1Q2(q3_org_l, q0_org_l,

                                                 p0_org_l, q1_org_l,

                                                 q2_l, p1_org_l,

                                                 q0_l, q1_l, q2_l);

            }

        }



        /* combine and store */

        if (!__msa_test_bz_v(is_less_than_beta)) {

            q0 = (v16u8) __msa_pckev_b((v16i8) q0_l, (v16i8) q0_r);

            q1 = (v16u8) __msa_pckev_b((v16i8) q1_l, (v16i8) q1_r);

            q2 = (v16u8) __msa_pckev_b((v16i8) q2_l, (v16i8) q2_r);



            q0_org = __msa_bmnz_v(q0_org, q0, is_less_than_beta);

            q1_org = __msa_bmnz_v(q1_org, q1, is_less_than_beta);

            q2_org = __msa_bmnz_v(q2_org, q2, is_less_than_beta);



            STORE_UB(q1_org, data + img_width);

            STORE_UB(q2_org, data + 2 * img_width);

        }



        {

            v8u16 negate_is_less_than_beta_r, negate_is_less_than_beta_l;



            negate_is_less_than_beta_r =

                (v8u16) __msa_sldi_b((v16i8) negate_is_less_than_beta, zero, 8);

            if (!__msa_test_bz_v((v16u8) negate_is_less_than_beta_r)) {

                AVC_LOOP_FILTER_P0_OR_Q0(q0_org_r, p1_org_r, q1_org_r, q0_r);

            }



            negate_is_less_than_beta_l =

                (v8u16) __msa_sldi_b(zero, (v16i8) negate_is_less_than_beta, 8);

            if (!__msa_test_bz_v((v16u8) negate_is_less_than_beta_l)) {

                AVC_LOOP_FILTER_P0_OR_Q0(q0_org_l, p1_org_l, q1_org_l, q0_l);

            }

        }



        /* combine */

        if (!__msa_test_bz_v(negate_is_less_than_beta)) {

            q0 = (v16u8) __msa_pckev_b((v16i8) q0_l, (v16i8) q0_r);

            q0_org = __msa_bmnz_v(q0_org, q0, negate_is_less_than_beta);

        }



        STORE_UB(q0_org, data);

    }

}

static enum AVPixelFormat get_pixel_format(H264Context *h, int force_callback)

{

#define HWACCEL_MAX (CONFIG_H264_DXVA2_HWACCEL + \

                     CONFIG_H264_D3D11VA_HWACCEL + \

                     CONFIG_H264_VAAPI_HWACCEL + \

                     (CONFIG_H264_VDA_HWACCEL * 2) + \

                     CONFIG_H264_VIDEOTOOLBOX_HWACCEL + \

                     CONFIG_H264_VDPAU_HWACCEL)

    enum AVPixelFormat pix_fmts[HWACCEL_MAX + 2], *fmt = pix_fmts;

    const enum AVPixelFormat *choices = pix_fmts;

    int i;



    switch (h->ps.sps->bit_depth_luma) {

    case 9:

        if (CHROMA444(h)) {

            if (h->avctx->colorspace == AVCOL_SPC_RGB) {

                *fmt++ = AV_PIX_FMT_GBRP9;

            } else

                *fmt++ = AV_PIX_FMT_YUV444P9;

        } else if (CHROMA422(h))

            *fmt++ = AV_PIX_FMT_YUV422P9;

        else

            *fmt++ = AV_PIX_FMT_YUV420P9;

        break;

    case 10:

        if (CHROMA444(h)) {

            if (h->avctx->colorspace == AVCOL_SPC_RGB) {

                *fmt++ = AV_PIX_FMT_GBRP10;

            } else

                *fmt++ = AV_PIX_FMT_YUV444P10;

        } else if (CHROMA422(h))

            *fmt++ = AV_PIX_FMT_YUV422P10;

        else

            *fmt++ = AV_PIX_FMT_YUV420P10;

        break;

    case 12:

        if (CHROMA444(h)) {

            if (h->avctx->colorspace == AVCOL_SPC_RGB) {

                *fmt++ = AV_PIX_FMT_GBRP12;

            } else

                *fmt++ = AV_PIX_FMT_YUV444P12;

        } else if (CHROMA422(h))

            *fmt++ = AV_PIX_FMT_YUV422P12;

        else

            *fmt++ = AV_PIX_FMT_YUV420P12;

        break;

    case 14:

        if (CHROMA444(h)) {

            if (h->avctx->colorspace == AVCOL_SPC_RGB) {

                *fmt++ = AV_PIX_FMT_GBRP14;

            } else

                *fmt++ = AV_PIX_FMT_YUV444P14;

        } else if (CHROMA422(h))

            *fmt++ = AV_PIX_FMT_YUV422P14;

        else

            *fmt++ = AV_PIX_FMT_YUV420P14;

        break;

    case 8:

#if CONFIG_H264_VDPAU_HWACCEL

        *fmt++ = AV_PIX_FMT_VDPAU;

#endif

        if (CHROMA444(h)) {

            if (h->avctx->colorspace == AVCOL_SPC_RGB)

                *fmt++ = AV_PIX_FMT_GBRP;

            else if (h->avctx->color_range == AVCOL_RANGE_JPEG)

                *fmt++ = AV_PIX_FMT_YUVJ444P;

            else

                *fmt++ = AV_PIX_FMT_YUV444P;

        } else if (CHROMA422(h)) {

            if (h->avctx->color_range == AVCOL_RANGE_JPEG)

                *fmt++ = AV_PIX_FMT_YUVJ422P;

            else

                *fmt++ = AV_PIX_FMT_YUV422P;

        } else {

#if CONFIG_H264_DXVA2_HWACCEL

            *fmt++ = AV_PIX_FMT_DXVA2_VLD;

#endif

#if CONFIG_H264_D3D11VA_HWACCEL

            *fmt++ = AV_PIX_FMT_D3D11VA_VLD;

#endif

#if CONFIG_H264_VAAPI_HWACCEL

            *fmt++ = AV_PIX_FMT_VAAPI;

#endif

#if CONFIG_H264_VDA_HWACCEL

            *fmt++ = AV_PIX_FMT_VDA_VLD;

            *fmt++ = AV_PIX_FMT_VDA;

#endif

#if CONFIG_H264_VIDEOTOOLBOX_HWACCEL

            *fmt++ = AV_PIX_FMT_VIDEOTOOLBOX;

#endif

            if (h->avctx->codec->pix_fmts)

                choices = h->avctx->codec->pix_fmts;

            else if (h->avctx->color_range == AVCOL_RANGE_JPEG)

                *fmt++ = AV_PIX_FMT_YUVJ420P;

            else

                *fmt++ = AV_PIX_FMT_YUV420P;

        }

        break;

    default:

        av_log(h->avctx, AV_LOG_ERROR,

               "Unsupported bit depth %d\n", h->ps.sps->bit_depth_luma);

        return AVERROR_INVALIDDATA;

    }



    *fmt = AV_PIX_FMT_NONE;



    for (i=0; choices[i] != AV_PIX_FMT_NONE; i++)

        if (choices[i] == h->avctx->pix_fmt && !force_callback)

            return choices[i];

    return ff_thread_get_format(h->avctx, choices);

}

static int smka_decode_frame(AVCodecContext *avctx, void *data,

                             int *got_frame_ptr, AVPacket *avpkt)

{

    SmackerAudioContext *s = avctx->priv_data;

    const uint8_t *buf = avpkt->data;

    int buf_size = avpkt->size;

    GetBitContext gb;

    HuffContext h[4] = { { 0 } };

    VLC vlc[4]       = { { 0 } };

    int16_t *samples;

    uint8_t *samples8;

    int val;

    int i, res, ret;

    int unp_size;

    int bits, stereo;

    int pred[2] = {0, 0};



    if (buf_size <= 4) {

        av_log(avctx, AV_LOG_ERROR, "packet is too small\n");

        return AVERROR(EINVAL);

    }



    unp_size = AV_RL32(buf);



    if (unp_size > (1U<<24)) {

        av_log(avctx, AV_LOG_ERROR, "packet is too big\n");

        return AVERROR_INVALIDDATA;

    }



    init_get_bits(&gb, buf + 4, (buf_size - 4) * 8);



    if(!get_bits1(&gb)){

        av_log(avctx, AV_LOG_INFO, "Sound: no data\n");

        *got_frame_ptr = 0;

        return 1;

    }

    stereo = get_bits1(&gb);

    bits = get_bits1(&gb);

    if (stereo ^ (avctx->channels != 1)) {

        av_log(avctx, AV_LOG_ERROR, "channels mismatch\n");

        return AVERROR(EINVAL);

    }

    if (bits && avctx->sample_fmt == AV_SAMPLE_FMT_U8) {

        av_log(avctx, AV_LOG_ERROR, "sample format mismatch\n");

        return AVERROR(EINVAL);

    }



    /* get output buffer */

    s->frame.nb_samples = unp_size / (avctx->channels * (bits + 1));

    if ((ret = avctx->get_buffer(avctx, &s->frame)) < 0) {

        av_log(avctx, AV_LOG_ERROR, "get_buffer() failed\n");

        return ret;

    }

    samples  = (int16_t *)s->frame.data[0];

    samples8 =            s->frame.data[0];



    // Initialize

    for(i = 0; i < (1 << (bits + stereo)); i++) {

        h[i].length = 256;

        h[i].maxlength = 0;

        h[i].current = 0;

        h[i].bits = av_mallocz(256 * 4);

        h[i].lengths = av_mallocz(256 * sizeof(int));

        h[i].values = av_mallocz(256 * sizeof(int));

        skip_bits1(&gb);

        smacker_decode_tree(&gb, &h[i], 0, 0);

        skip_bits1(&gb);

        if(h[i].current > 1) {

            res = init_vlc(&vlc[i], SMKTREE_BITS, h[i].length,

                    h[i].lengths, sizeof(int), sizeof(int),

                    h[i].bits, sizeof(uint32_t), sizeof(uint32_t), INIT_VLC_LE);

            if(res < 0) {

                av_log(avctx, AV_LOG_ERROR, "Cannot build VLC table\n");

                return AVERROR_INVALIDDATA;

            }

        }

    }

    if(bits) { //decode 16-bit data

        for(i = stereo; i >= 0; i--)

            pred[i] = sign_extend(av_bswap16(get_bits(&gb, 16)), 16);

        for(i = 0; i <= stereo; i++)

            *samples++ = pred[i];

        for(; i < unp_size / 2; i++) {

            if(get_bits_left(&gb)<0)

                return AVERROR_INVALIDDATA;

            if(i & stereo) {

                if(vlc[2].table)

                    res = get_vlc2(&gb, vlc[2].table, SMKTREE_BITS, 3);

                else

                    res = 0;

                if (res < 0) {

                    av_log(avctx, AV_LOG_ERROR, "invalid vlc\n");

                    return AVERROR_INVALIDDATA;

                }

                val  = h[2].values[res];

                if(vlc[3].table)

                    res = get_vlc2(&gb, vlc[3].table, SMKTREE_BITS, 3);

                else

                    res = 0;

                if (res < 0) {

                    av_log(avctx, AV_LOG_ERROR, "invalid vlc\n");

                    return AVERROR_INVALIDDATA;

                }

                val |= h[3].values[res] << 8;

                pred[1] += sign_extend(val, 16);

                *samples++ = av_clip_int16(pred[1]);

            } else {

                if(vlc[0].table)

                    res = get_vlc2(&gb, vlc[0].table, SMKTREE_BITS, 3);

                else

                    res = 0;

                if (res < 0) {

                    av_log(avctx, AV_LOG_ERROR, "invalid vlc\n");

                    return AVERROR_INVALIDDATA;

                }

                val  = h[0].values[res];

                if(vlc[1].table)

                    res = get_vlc2(&gb, vlc[1].table, SMKTREE_BITS, 3);

                else

                    res = 0;

                if (res < 0) {

                    av_log(avctx, AV_LOG_ERROR, "invalid vlc\n");

                    return AVERROR_INVALIDDATA;

                }

                val |= h[1].values[res] << 8;

                pred[0] += sign_extend(val, 16);

                *samples++ = av_clip_int16(pred[0]);

            }

        }

    } else { //8-bit data

        for(i = stereo; i >= 0; i--)

            pred[i] = get_bits(&gb, 8);

        for(i = 0; i <= stereo; i++)

            *samples8++ = pred[i];

        for(; i < unp_size; i++) {

            if(get_bits_left(&gb)<0)

                return AVERROR_INVALIDDATA;

            if(i & stereo){

                if(vlc[1].table)

                    res = get_vlc2(&gb, vlc[1].table, SMKTREE_BITS, 3);

                else

                    res = 0;

                if (res < 0) {

                    av_log(avctx, AV_LOG_ERROR, "invalid vlc\n");

                    return AVERROR_INVALIDDATA;

                }

                pred[1] += sign_extend(h[1].values[res], 8);

                *samples8++ = av_clip_uint8(pred[1]);

            } else {

                if(vlc[0].table)

                    res = get_vlc2(&gb, vlc[0].table, SMKTREE_BITS, 3);

                else

                    res = 0;

                if (res < 0) {

                    av_log(avctx, AV_LOG_ERROR, "invalid vlc\n");

                    return AVERROR_INVALIDDATA;

                }

                pred[0] += sign_extend(h[0].values[res], 8);

                *samples8++ = av_clip_uint8(pred[0]);

            }

        }

    }



    for(i = 0; i < 4; i++) {

        if(vlc[i].table)

            ff_free_vlc(&vlc[i]);

        av_free(h[i].bits);

        av_free(h[i].lengths);

        av_free(h[i].values);

    }



    *got_frame_ptr   = 1;

    *(AVFrame *)data = s->frame;



    return buf_size;

}

static int device_init(AVFormatContext *ctx, int *width, int *height,

                       uint32_t pix_fmt)

{

    struct video_data *s = ctx->priv_data;

    int fd = s->fd;

    struct v4l2_format fmt;

    struct v4l2_pix_format *pix = &fmt.fmt.pix;



    int res;



    memset(&fmt, 0, sizeof(struct v4l2_format));



    fmt.type = V4L2_BUF_TYPE_VIDEO_CAPTURE;

    pix->width = *width;

    pix->height = *height;

    pix->pixelformat = pix_fmt;

    pix->field = V4L2_FIELD_ANY;



    res = ioctl(fd, VIDIOC_S_FMT, &fmt);



    if ((*width != fmt.fmt.pix.width) || (*height != fmt.fmt.pix.height)) {

        av_log(ctx, AV_LOG_INFO,

               "The V4L2 driver changed the video from %dx%d to %dx%d\n",

               *width, *height, fmt.fmt.pix.width, fmt.fmt.pix.height);

        *width = fmt.fmt.pix.width;

        *height = fmt.fmt.pix.height;

    }



    if (pix_fmt != fmt.fmt.pix.pixelformat) {

        av_log(ctx, AV_LOG_DEBUG,

               "The V4L2 driver changed the pixel format "

               "from 0x%08X to 0x%08X\n",

               pix_fmt, fmt.fmt.pix.pixelformat);

        res = -1;

    }



    if (fmt.fmt.pix.field == V4L2_FIELD_INTERLACED) {

        av_log(ctx, AV_LOG_DEBUG, "The V4L2 driver using the interlaced mode");

        s->interlaced = 1;

    }



    return res;

}

static int encode_packets(Jpeg2000EncoderContext *s, Jpeg2000Tile *tile, int tileno)

{

    int compno, reslevelno, ret;

    Jpeg2000CodingStyle *codsty = &s->codsty;

    Jpeg2000QuantStyle  *qntsty = &s->qntsty;



    av_log(s->avctx, AV_LOG_DEBUG, "tier2\n");

    // lay-rlevel-comp-pos progression

    for (reslevelno = 0; reslevelno < codsty->nreslevels; reslevelno++){

        for (compno = 0; compno < s->ncomponents; compno++){

            int precno;

            Jpeg2000ResLevel *reslevel = s->tile[tileno].comp[compno].reslevel + reslevelno;

            for (precno = 0; precno < reslevel->num_precincts_x * reslevel->num_precincts_y; precno++){

                if (ret = encode_packet(s, reslevel, precno, qntsty->expn + (reslevelno ? 3*reslevelno-2 : 0),

                              qntsty->nguardbits))

                    return ret;

            }

        }

    }

    av_log(s->avctx, AV_LOG_DEBUG, "after tier2\n");

    return 0;

}

static void chomp3(ChannelData *ctx, int16_t *output, uint8_t val,

                   const uint16_t tab1[],

                   const int16_t *tab2, int tab2_stride,

                   uint32_t numChannels)

{

    int16_t current;



    current = tab2[((ctx->index & 0x7f0) >> 4)*tab2_stride + val];



    current = mace_broken_clip_int16(current + ctx->lev);



    ctx->lev = current - (current >> 3);

    *output = QT_8S_2_16S(current);

    if (( ctx->index += tab1[val]-(ctx->index >> 5) ) < 0)

        ctx->index = 0;

}

static void srt_to_ass(AVCodecContext *avctx, AVBPrint *dst,

                       const char *in, int x1, int y1, int x2, int y2)

{

    if (x1 >= 0 && y1 >= 0) {

        /* XXX: here we rescale coordinate assuming they are in DVD resolution

         * (720x480) since we don't have anything better */



        if (x2 >= 0 && y2 >= 0 && (x2 != x1 || y2 != y1) && x2 >= x1 && y2 >= y1) {

            /* text rectangle defined, write the text at the center of the rectangle */

            const int cx = x1 + (x2 - x1)/2;

            const int cy = y1 + (y2 - y1)/2;

            const int scaled_x = cx * ASS_DEFAULT_PLAYRESX / 720;

            const int scaled_y = cy * ASS_DEFAULT_PLAYRESY / 480;

            av_bprintf(dst, "{\\an5}{\\pos(%d,%d)}", scaled_x, scaled_y);

        } else {

            /* only the top left corner, assume the text starts in that corner */

            const int scaled_x = x1 * ASS_DEFAULT_PLAYRESX / 720;

            const int scaled_y = y1 * ASS_DEFAULT_PLAYRESY / 480;

            av_bprintf(dst, "{\\an1}{\\pos(%d,%d)}", scaled_x, scaled_y);

        }

    }



    ff_htmlmarkup_to_ass(avctx, dst, in);

}

int ff_twinvq_decode_frame(AVCodecContext *avctx, void *data,

                           int *got_frame_ptr, AVPacket *avpkt)

{

    AVFrame *frame     = data;

    const uint8_t *buf = avpkt->data;

    int buf_size       = avpkt->size;

    TwinVQContext *tctx = avctx->priv_data;

    const TwinVQModeTab *mtab = tctx->mtab;

    float **out = NULL;

    int ret;



    /* get output buffer */

    if (tctx->discarded_packets >= 2) {

        frame->nb_samples = mtab->size;

        if ((ret = ff_get_buffer(avctx, frame, 0)) < 0) {

            av_log(avctx, AV_LOG_ERROR, "get_buffer() failed\n");

            return ret;

        }

        out = (float **)frame->extended_data;

    }



    if ((ret = tctx->read_bitstream(avctx, tctx, buf, buf_size)) < 0)

        return ret;



    read_and_decode_spectrum(tctx, tctx->spectrum, tctx->bits.ftype);



    imdct_output(tctx, tctx->bits.ftype, tctx->bits.window_type, out);



    FFSWAP(float *, tctx->curr_frame, tctx->prev_frame);



    if (tctx->discarded_packets < 2) {

        tctx->discarded_packets++;

        *got_frame_ptr = 0;

        return buf_size;

    }



    *got_frame_ptr = 1;



    return buf_size;

}

static int split_field_ref_list(Picture *dest, int dest_len,

                                Picture *src,  int src_len,

                                int parity,    int long_i){



    int i = split_field_half_ref_list(dest, dest_len, src, long_i, parity);

    dest += i;

    dest_len -= i;



    i += split_field_half_ref_list(dest, dest_len, src + long_i,

                                   src_len - long_i, parity);

    return i;

}

static int fourxm_read_packet(AVFormatContext *s,

                              AVPacket *pkt)

{

    FourxmDemuxContext *fourxm = s->priv_data;

    ByteIOContext *pb = s->pb;

    unsigned int fourcc_tag;

    unsigned int size, out_size;

    int ret = 0;

    unsigned int track_number;

    int packet_read = 0;

    unsigned char header[8];

    int audio_frame_count;



    while (!packet_read) {



        if ((ret = get_buffer(s->pb, header, 8)) < 0)

            return ret;

        fourcc_tag = AV_RL32(&header[0]);

        size = AV_RL32(&header[4]);

        if (url_feof(pb))

            return AVERROR(EIO);

        switch (fourcc_tag) {



        case LIST_TAG:

            /* this is a good time to bump the video pts */

            fourxm->video_pts ++;



            /* skip the LIST-* tag and move on to the next fourcc */

            get_le32(pb);

            break;



        case ifrm_TAG:

        case pfrm_TAG:

        case cfrm_TAG:

        case ifr2_TAG:

        case pfr2_TAG:

        case cfr2_TAG:

            /* allocate 8 more bytes than 'size' to account for fourcc

             * and size */

            if (size + 8 < size || av_new_packet(pkt, size + 8))

                return AVERROR(EIO);

            pkt->stream_index = fourxm->video_stream_index;

            pkt->pts = fourxm->video_pts;

            pkt->pos = url_ftell(s->pb);

            memcpy(pkt->data, header, 8);

            ret = get_buffer(s->pb, &pkt->data[8], size);



            if (ret < 0){

                av_free_packet(pkt);

            }else

                packet_read = 1;

            break;



        case snd__TAG:

            track_number = get_le32(pb);

            out_size= get_le32(pb);

            size-=8;



            if (track_number < fourxm->track_count) {

                ret= av_get_packet(s->pb, pkt, size);

                if(ret<0)

                    return AVERROR(EIO);

                pkt->stream_index =

                    fourxm->tracks[track_number].stream_index;

                pkt->pts = fourxm->tracks[track_number].audio_pts;

                packet_read = 1;



                /* pts accounting */

                audio_frame_count = size;

                if (fourxm->tracks[track_number].adpcm)

                    audio_frame_count -=

                        2 * (fourxm->tracks[track_number].channels);

                audio_frame_count /=

                      fourxm->tracks[track_number].channels;

                if (fourxm->tracks[track_number].adpcm){

                    audio_frame_count *= 2;

                }else

                    audio_frame_count /=

                    (fourxm->tracks[track_number].bits / 8);

                fourxm->tracks[track_number].audio_pts += audio_frame_count;



            } else {

                url_fseek(pb, size, SEEK_CUR);

            }

            break;



        default:

            url_fseek(pb, size, SEEK_CUR);

            break;

        }

    }

    return ret;

}

SwsFunc ff_yuv2rgb_init_mmx(SwsContext *c)

{

    int cpu_flags = av_get_cpu_flags();



    if (c->srcFormat != PIX_FMT_YUV420P &&

        c->srcFormat != PIX_FMT_YUVA420P)

        return NULL;



#if HAVE_MMX2

    if (cpu_flags & AV_CPU_FLAG_MMX2) {

        switch (c->dstFormat) {

        case PIX_FMT_RGB24:  return yuv420_rgb24_MMX2;

        case PIX_FMT_BGR24:  return yuv420_bgr24_MMX2;

        }

    }

#endif



    if (cpu_flags & AV_CPU_FLAG_MMX) {

        switch (c->dstFormat) {

            case PIX_FMT_RGB32:

                if (c->srcFormat == PIX_FMT_YUVA420P) {

#if HAVE_7REGS && CONFIG_SWSCALE_ALPHA

                    return yuva420_rgb32_MMX;

#endif

                    break;

                } else return yuv420_rgb32_MMX;

            case PIX_FMT_BGR32:

                if (c->srcFormat == PIX_FMT_YUVA420P) {

#if HAVE_7REGS && CONFIG_SWSCALE_ALPHA

                    return yuva420_bgr32_MMX;

#endif

                    break;

                } else return yuv420_bgr32_MMX;

            case PIX_FMT_RGB24:  return yuv420_rgb24_MMX;

            case PIX_FMT_BGR24:  return yuv420_bgr24_MMX;

            case PIX_FMT_RGB565: return yuv420_rgb16_MMX;

            case PIX_FMT_RGB555: return yuv420_rgb15_MMX;

        }

    }



    return NULL;

}

static av_always_inline av_flatten void FUNCC(h264_loop_filter_luma)(uint8_t *p_pix, int xstride, int ystride, int inner_iters, int alpha, int beta, int8_t *tc0)

{

    pixel *pix = (pixel*)p_pix;

    int i, d;

    xstride >>= sizeof(pixel)-1;

    ystride >>= sizeof(pixel)-1;

    alpha <<= BIT_DEPTH - 8;

    beta  <<= BIT_DEPTH - 8;

    for( i = 0; i < 4; i++ ) {

        const int tc_orig = tc0[i] << (BIT_DEPTH - 8);

        if( tc_orig < 0 ) {

            pix += inner_iters*ystride;

            continue;

        }

        for( d = 0; d < inner_iters; d++ ) {

            const int p0 = pix[-1*xstride];

            const int p1 = pix[-2*xstride];

            const int p2 = pix[-3*xstride];

            const int q0 = pix[0];

            const int q1 = pix[1*xstride];

            const int q2 = pix[2*xstride];



            if( FFABS( p0 - q0 ) < alpha &&

                FFABS( p1 - p0 ) < beta &&

                FFABS( q1 - q0 ) < beta ) {



                int tc = tc_orig;

                int i_delta;



                if( FFABS( p2 - p0 ) < beta ) {

                    if(tc_orig)

                    pix[-2*xstride] = p1 + av_clip( (( p2 + ( ( p0 + q0 + 1 ) >> 1 ) ) >> 1) - p1, -tc_orig, tc_orig );

                    tc++;

                }

                if( FFABS( q2 - q0 ) < beta ) {

                    if(tc_orig)

                    pix[   xstride] = q1 + av_clip( (( q2 + ( ( p0 + q0 + 1 ) >> 1 ) ) >> 1) - q1, -tc_orig, tc_orig );

                    tc++;

                }



                i_delta = av_clip( (((q0 - p0 ) << 2) + (p1 - q1) + 4) >> 3, -tc, tc );

                pix[-xstride] = av_clip_pixel( p0 + i_delta );    /* p0' */

                pix[0]        = av_clip_pixel( q0 - i_delta );    /* q0' */

            }

            pix += ystride;

        }

    }

}

static int start_frame(AVFilterLink *inlink, AVFilterBufferRef *picref)

{

    AVFilterContext *ctx = inlink->dst;

    TInterlaceContext *tinterlace = ctx->priv;



    avfilter_unref_buffer(tinterlace->cur);

    tinterlace->cur  = tinterlace->next;

    tinterlace->next = picref;


    return 0;

}

static void write_odml_master(AVFormatContext *s, int stream_index)

{

    AVIOContext *pb = s->pb;

    AVStream *st = s->streams[stream_index];

    AVCodecContext *enc = st->codec;

    AVIStream *avist = st->priv_data;

    unsigned char tag[5];

    int j;



    /* Starting to lay out AVI OpenDML master index.

        * We want to make it JUNK entry for now, since we'd

        * like to get away without making AVI an OpenDML one

        * for compatibility reasons. */

    avist->indexes.entry      = avist->indexes.ents_allocated = 0;

    avist->indexes.indx_start = ff_start_tag(pb, "JUNK");

    avio_wl16(pb, 4);   /* wLongsPerEntry */

    avio_w8(pb, 0);     /* bIndexSubType (0 == frame index) */

    avio_w8(pb, 0);     /* bIndexType (0 == AVI_INDEX_OF_INDEXES) */

    avio_wl32(pb, 0);   /* nEntriesInUse (will fill out later on) */

    ffio_wfourcc(pb, avi_stream2fourcc(tag, stream_index, enc->codec_type));

                        /* dwChunkId */

    avio_wl64(pb, 0);   /* dwReserved[3] */

    avio_wl32(pb, 0);   /* Must be 0.    */

    for (j = 0; j < AVI_MASTER_INDEX_SIZE * 2; j++)

        avio_wl64(pb, 0);

    ff_end_tag(pb, avist->indexes.indx_start);

}

static void cook_imlt(COOKContext *q, float* inbuffer, float* outbuffer)

{

    int i;



    q->mdct_ctx.fft.imdct_calc(&q->mdct_ctx, outbuffer, inbuffer, q->mdct_tmp);



    for(i = 0; i < q->samples_per_channel; i++){

        float tmp = outbuffer[i];



        outbuffer[i] = q->mlt_window[i] * outbuffer[q->samples_per_channel + i];

        outbuffer[q->samples_per_channel + i] = q->mlt_window[q->samples_per_channel - 1 - i] * -tmp;

    }

}

static int mp3_write_trailer(struct AVFormatContext *s)

{

    uint8_t buf[ID3v1_TAG_SIZE];

    MP3Context *mp3 = s->priv_data;



    /* write the id3v1 tag */

    if (id3v1_create_tag(s, buf) > 0) {

        avio_write(s->pb, buf, ID3v1_TAG_SIZE);

    }



    /* write number of frames */

    if (mp3 && mp3->nb_frames_offset) {

        avio_seek(s->pb, mp3->nb_frames_offset, SEEK_SET);

        avio_wb32(s->pb, s->streams[0]->nb_frames);

        avio_seek(s->pb, 0, SEEK_END);

    }



    avio_flush(s->pb);



    return 0;

}

static int vp3_decode_frame(AVCodecContext *avctx,

                            void *data, int *got_frame,

                            AVPacket *avpkt)

{

    const uint8_t *buf = avpkt->data;

    int buf_size = avpkt->size;

    Vp3DecodeContext *s = avctx->priv_data;

    GetBitContext gb;

    int i;

    int ret;



    init_get_bits(&gb, buf, buf_size * 8);



#if CONFIG_THEORA_DECODER

    if (s->theora && get_bits1(&gb))

    {

        int type = get_bits(&gb, 7);

        skip_bits_long(&gb, 6*8); /* "theora" */



        if (type == 0) {

            if (s->avctx->active_thread_type&FF_THREAD_FRAME) {

                av_log(avctx, AV_LOG_ERROR, "midstream reconfiguration with multithreading is unsupported, try -threads 1\n");

                return AVERROR_PATCHWELCOME;

            }

            vp3_decode_end(avctx);

            ret = theora_decode_header(avctx, &gb);



            if (ret < 0) {

                vp3_decode_end(avctx);

            } else

                ret = vp3_decode_init(avctx);

            return ret;

        } else if (type == 2) {

            ret = theora_decode_tables(avctx, &gb);

            if (ret < 0) {

                vp3_decode_end(avctx);

            } else

                ret = vp3_decode_init(avctx);

            return ret;

        }



        av_log(avctx, AV_LOG_ERROR, "Header packet passed to frame decoder, skipping\n");

        return -1;

    }

#endif



    s->keyframe = !get_bits1(&gb);

    if (!s->all_fragments) {

        av_log(avctx, AV_LOG_ERROR, "Data packet without prior valid headers\n");

        return -1;

    }

    if (!s->theora)

        skip_bits(&gb, 1);

    for (i = 0; i < 3; i++)

        s->last_qps[i] = s->qps[i];



    s->nqps=0;

    do{

        s->qps[s->nqps++]= get_bits(&gb, 6);

    } while(s->theora >= 0x030200 && s->nqps<3 && get_bits1(&gb));

    for (i = s->nqps; i < 3; i++)

        s->qps[i] = -1;



    if (s->avctx->debug & FF_DEBUG_PICT_INFO)

        av_log(s->avctx, AV_LOG_INFO, " VP3 %sframe #%d: Q index = %d\n",

            s->keyframe?"key":"", avctx->frame_number+1, s->qps[0]);



    s->skip_loop_filter = !s->filter_limit_values[s->qps[0]] ||

        avctx->skip_loop_filter >= (s->keyframe ? AVDISCARD_ALL : AVDISCARD_NONKEY);



    if (s->qps[0] != s->last_qps[0])

        init_loop_filter(s);



    for (i = 0; i < s->nqps; i++)

        // reinit all dequantizers if the first one changed, because

        // the DC of the first quantizer must be used for all matrices

        if (s->qps[i] != s->last_qps[i] || s->qps[0] != s->last_qps[0])

            init_dequantizer(s, i);



    if (avctx->skip_frame >= AVDISCARD_NONKEY && !s->keyframe)

        return buf_size;



    s->current_frame.reference = 3;

    s->current_frame.pict_type = s->keyframe ? AV_PICTURE_TYPE_I : AV_PICTURE_TYPE_P;

    s->current_frame.key_frame = s->keyframe;

    if (ff_thread_get_buffer(avctx, &s->current_frame) < 0) {

        av_log(s->avctx, AV_LOG_ERROR, "get_buffer() failed\n");

        goto error;

    }



    if (!s->edge_emu_buffer)

        s->edge_emu_buffer = av_malloc(9*FFABS(s->current_frame.linesize[0]));



    if (s->keyframe) {

        if (!s->theora)

        {

            skip_bits(&gb, 4); /* width code */

            skip_bits(&gb, 4); /* height code */

            if (s->version)

            {

                s->version = get_bits(&gb, 5);

                if (avctx->frame_number == 0)

                    av_log(s->avctx, AV_LOG_DEBUG, "VP version: %d\n", s->version);

            }

        }

        if (s->version || s->theora)

        {

                if (get_bits1(&gb))

                    av_log(s->avctx, AV_LOG_ERROR, "Warning, unsupported keyframe coding type?!\n");

            skip_bits(&gb, 2); /* reserved? */

        }

    } else {

        if (!s->golden_frame.data[0]) {

            av_log(s->avctx, AV_LOG_WARNING, "vp3: first frame not a keyframe\n");



            s->golden_frame.reference = 3;

            s->golden_frame.pict_type = AV_PICTURE_TYPE_I;

            if (ff_thread_get_buffer(avctx, &s->golden_frame) < 0) {

                av_log(s->avctx, AV_LOG_ERROR, "get_buffer() failed\n");

                goto error;

            }

            s->last_frame = s->golden_frame;

            s->last_frame.type = FF_BUFFER_TYPE_COPY;

            ff_thread_report_progress(&s->last_frame, INT_MAX, 0);

        }

    }



    memset(s->all_fragments, 0, s->fragment_count * sizeof(Vp3Fragment));

    ff_thread_finish_setup(avctx);



    if (unpack_superblocks(s, &gb)){

        av_log(s->avctx, AV_LOG_ERROR, "error in unpack_superblocks\n");

        goto error;

    }

    if (unpack_modes(s, &gb)){

        av_log(s->avctx, AV_LOG_ERROR, "error in unpack_modes\n");

        goto error;

    }

    if (unpack_vectors(s, &gb)){

        av_log(s->avctx, AV_LOG_ERROR, "error in unpack_vectors\n");

        goto error;

    }

    if (unpack_block_qpis(s, &gb)){

        av_log(s->avctx, AV_LOG_ERROR, "error in unpack_block_qpis\n");

        goto error;

    }

    if (unpack_dct_coeffs(s, &gb)){

        av_log(s->avctx, AV_LOG_ERROR, "error in unpack_dct_coeffs\n");

        goto error;

    }



    for (i = 0; i < 3; i++) {

        int height = s->height >> (i && s->chroma_y_shift);

        if (s->flipped_image)

            s->data_offset[i] = 0;

        else

            s->data_offset[i] = (height-1) * s->current_frame.linesize[i];

    }



    s->last_slice_end = 0;

    for (i = 0; i < s->c_superblock_height; i++)

        render_slice(s, i);



    // filter the last row

    for (i = 0; i < 3; i++) {

        int row = (s->height >> (3+(i && s->chroma_y_shift))) - 1;

        apply_loop_filter(s, i, row, row+1);

    }

    vp3_draw_horiz_band(s, s->avctx->height);



    *got_frame = 1;

    *(AVFrame*)data= s->current_frame;



    if (!HAVE_THREADS || !(s->avctx->active_thread_type&FF_THREAD_FRAME))

        update_frames(avctx);



    return buf_size;



error:

    ff_thread_report_progress(&s->current_frame, INT_MAX, 0);



    if (!HAVE_THREADS || !(s->avctx->active_thread_type&FF_THREAD_FRAME))

        avctx->release_buffer(avctx, &s->current_frame);



    return -1;

}

static void SET_TYPE(resample_one)(ResampleContext *c,

                                   void *dst0, int dst_index, const void *src0,

                                   int src_size, int index, int frac)

{

    FELEM *dst = dst0;

    const FELEM *src = src0;

    int i;

    int sample_index = index >> c->phase_shift;

    FELEM2 val = 0;

    FELEM *filter = ((FELEM *)c->filter_bank) +

                    c->filter_length * (index & c->phase_mask);



    if (sample_index < 0) {

        for (i = 0; i < c->filter_length; i++)

            val += src[FFABS(sample_index + i) % src_size] *

                   (FELEM2)filter[i];

    } else if (c->linear) {

        FELEM2 v2 = 0;

        for (i = 0; i < c->filter_length; i++) {

            val += src[abs(sample_index + i)] * (FELEM2)filter[i];

            v2  += src[abs(sample_index + i)] * (FELEM2)filter[i + c->filter_length];

        }

        val += (v2 - val) * (FELEML)frac / c->src_incr;

    } else {

        for (i = 0; i < c->filter_length; i++)

            val += src[sample_index + i] * (FELEM2)filter[i];

    }



    OUT(dst[dst_index], val);

}

static int thp_probe(AVProbeData *p)

{

    /* check file header */

    if (p->buf_size < 4)

        return 0;



    if (AV_RL32(p->buf) == MKTAG('T', 'H', 'P', '\0'))

        return AVPROBE_SCORE_MAX;

    else

        return 0;

}

static int update_thread_context(AVCodecContext *dst, const AVCodecContext *src)

{

    PNGDecContext *psrc = src->priv_data;

    PNGDecContext *pdst = dst->priv_data;

    int ret;



    if (dst == src)

        return 0;



    ff_thread_release_buffer(dst, &pdst->picture);

    if (psrc->picture.f->data[0] &&

        (ret = ff_thread_ref_frame(&pdst->picture, &psrc->picture)) < 0)

        return ret;

    if (CONFIG_APNG_DECODER && dst->codec_id == AV_CODEC_ID_APNG) {

        pdst->width             = psrc->width;

        pdst->height            = psrc->height;

        pdst->bit_depth         = psrc->bit_depth;

        pdst->color_type        = psrc->color_type;

        pdst->compression_type  = psrc->compression_type;

        pdst->interlace_type    = psrc->interlace_type;

        pdst->filter_type       = psrc->filter_type;

        pdst->cur_w = psrc->cur_w;

        pdst->cur_h = psrc->cur_h;

        pdst->x_offset = psrc->x_offset;

        pdst->y_offset = psrc->y_offset;

        pdst->has_trns = psrc->has_trns;

        memcpy(pdst->transparent_color_be, psrc->transparent_color_be, sizeof(pdst->transparent_color_be));



        pdst->dispose_op = psrc->dispose_op;



        memcpy(pdst->palette, psrc->palette, sizeof(pdst->palette));



        pdst->state |= psrc->state & (PNG_IHDR | PNG_PLTE);



        ff_thread_release_buffer(dst, &pdst->last_picture);

        if (psrc->last_picture.f->data[0] &&

            (ret = ff_thread_ref_frame(&pdst->last_picture, &psrc->last_picture)) < 0)

            return ret;



        ff_thread_release_buffer(dst, &pdst->previous_picture);

        if (psrc->previous_picture.f->data[0] &&

            (ret = ff_thread_ref_frame(&pdst->previous_picture, &psrc->previous_picture)) < 0)

            return ret;

    }



    return 0;

}

static int read_seek(AVFormatContext *s, int stream_index, int64_t timestamp, int flags)

{

    AVStream *st = s->streams[stream_index];

    avio_seek(s->pb, FFMAX(timestamp, 0) * st->codec->width * st->codec->height * 4, SEEK_SET);

    return 0;

}

static int transcode_init(void)

{

    int ret = 0, i, j, k;

    AVFormatContext *oc;

    OutputStream *ost;

    InputStream *ist;

    char error[1024] = {0};

    int want_sdp = 1;



    for (i = 0; i < nb_filtergraphs; i++) {

        FilterGraph *fg = filtergraphs[i];

        for (j = 0; j < fg->nb_outputs; j++) {

            OutputFilter *ofilter = fg->outputs[j];

            if (!ofilter->ost || ofilter->ost->source_index >= 0)

                continue;

            if (fg->nb_inputs != 1)

                continue;

            for (k = nb_input_streams-1; k >= 0 ; k--)

                if (fg->inputs[0]->ist == input_streams[k])

                    break;

            ofilter->ost->source_index = k;

        }

    }



    /* init framerate emulation */

    for (i = 0; i < nb_input_files; i++) {

        InputFile *ifile = input_files[i];

        if (ifile->rate_emu)

            for (j = 0; j < ifile->nb_streams; j++)

                input_streams[j + ifile->ist_index]->start = av_gettime_relative();

    }



    /* output stream init */

    for (i = 0; i < nb_output_files; i++) {

        oc = output_files[i]->ctx;

        if (!oc->nb_streams && !(oc->oformat->flags & AVFMT_NOSTREAMS)) {

            av_dump_format(oc, i, oc->filename, 1);

            av_log(NULL, AV_LOG_ERROR, "Output file #%d does not contain any stream\n", i);

            return AVERROR(EINVAL);

        }

    }



    /* init complex filtergraphs */

    for (i = 0; i < nb_filtergraphs; i++)

        if ((ret = avfilter_graph_config(filtergraphs[i]->graph, NULL)) < 0)

            return ret;



    /* for each output stream, we compute the right encoding parameters */

    for (i = 0; i < nb_output_streams; i++) {

        AVCodecContext *enc_ctx;

        AVCodecContext *dec_ctx = NULL;

        ost = output_streams[i];

        oc  = output_files[ost->file_index]->ctx;

        ist = get_input_stream(ost);



        if (ost->attachment_filename)

            continue;



        enc_ctx = ost->stream_copy ? ost->st->codec : ost->enc_ctx;



        if (ist) {

            dec_ctx = ist->dec_ctx;



            ost->st->disposition          = ist->st->disposition;

            enc_ctx->bits_per_raw_sample    = dec_ctx->bits_per_raw_sample;

            enc_ctx->chroma_sample_location = dec_ctx->chroma_sample_location;

        } else {

            for (j=0; j<oc->nb_streams; j++) {

                AVStream *st = oc->streams[j];

                if (st != ost->st && st->codec->codec_type == enc_ctx->codec_type)

                    break;

            }

            if (j == oc->nb_streams)

                if (enc_ctx->codec_type == AVMEDIA_TYPE_AUDIO || enc_ctx->codec_type == AVMEDIA_TYPE_VIDEO)

                    ost->st->disposition = AV_DISPOSITION_DEFAULT;

        }



        if (ost->stream_copy) {

            AVRational sar;

            uint64_t extra_size;



            av_assert0(ist && !ost->filter);



            extra_size = (uint64_t)dec_ctx->extradata_size + FF_INPUT_BUFFER_PADDING_SIZE;



            if (extra_size > INT_MAX) {

                return AVERROR(EINVAL);

            }



            /* if stream_copy is selected, no need to decode or encode */

            enc_ctx->codec_id   = dec_ctx->codec_id;

            enc_ctx->codec_type = dec_ctx->codec_type;



            if (!enc_ctx->codec_tag) {

                unsigned int codec_tag;

                if (!oc->oformat->codec_tag ||

                     av_codec_get_id (oc->oformat->codec_tag, dec_ctx->codec_tag) == enc_ctx->codec_id ||

                     !av_codec_get_tag2(oc->oformat->codec_tag, dec_ctx->codec_id, &codec_tag))

                    enc_ctx->codec_tag = dec_ctx->codec_tag;

            }



            enc_ctx->bit_rate       = dec_ctx->bit_rate;

            enc_ctx->rc_max_rate    = dec_ctx->rc_max_rate;

            enc_ctx->rc_buffer_size = dec_ctx->rc_buffer_size;

            enc_ctx->field_order    = dec_ctx->field_order;

            if (dec_ctx->extradata_size) {

                enc_ctx->extradata      = av_mallocz(extra_size);

                if (!enc_ctx->extradata) {

                    return AVERROR(ENOMEM);

                }

                memcpy(enc_ctx->extradata, dec_ctx->extradata, dec_ctx->extradata_size);

            }

            enc_ctx->extradata_size= dec_ctx->extradata_size;

            enc_ctx->bits_per_coded_sample  = dec_ctx->bits_per_coded_sample;



            enc_ctx->time_base = ist->st->time_base;

            /*

             * Avi is a special case here because it supports variable fps but

             * having the fps and timebase differe significantly adds quite some

             * overhead

             */

            if(!strcmp(oc->oformat->name, "avi")) {

                if ( copy_tb<0 && av_q2d(ist->st->r_frame_rate) >= av_q2d(ist->st->avg_frame_rate)

                               && 0.5/av_q2d(ist->st->r_frame_rate) > av_q2d(ist->st->time_base)

                               && 0.5/av_q2d(ist->st->r_frame_rate) > av_q2d(dec_ctx->time_base)

                               && av_q2d(ist->st->time_base) < 1.0/500 && av_q2d(dec_ctx->time_base) < 1.0/500

                     || copy_tb==2){

                    enc_ctx->time_base.num = ist->st->r_frame_rate.den;

                    enc_ctx->time_base.den = 2*ist->st->r_frame_rate.num;

                    enc_ctx->ticks_per_frame = 2;

                } else if (   copy_tb<0 && av_q2d(dec_ctx->time_base)*dec_ctx->ticks_per_frame > 2*av_q2d(ist->st->time_base)

                                 && av_q2d(ist->st->time_base) < 1.0/500

                    || copy_tb==0){

                    enc_ctx->time_base = dec_ctx->time_base;

                    enc_ctx->time_base.num *= dec_ctx->ticks_per_frame;

                    enc_ctx->time_base.den *= 2;

                    enc_ctx->ticks_per_frame = 2;

                }

            } else if(!(oc->oformat->flags & AVFMT_VARIABLE_FPS)

                      && strcmp(oc->oformat->name, "mov") && strcmp(oc->oformat->name, "mp4") && strcmp(oc->oformat->name, "3gp")

                      && strcmp(oc->oformat->name, "3g2") && strcmp(oc->oformat->name, "psp") && strcmp(oc->oformat->name, "ipod")

                      && strcmp(oc->oformat->name, "f4v")

            ) {

                if(   copy_tb<0 && dec_ctx->time_base.den

                                && av_q2d(dec_ctx->time_base)*dec_ctx->ticks_per_frame > av_q2d(ist->st->time_base)

                                && av_q2d(ist->st->time_base) < 1.0/500

                   || copy_tb==0){

                    enc_ctx->time_base = dec_ctx->time_base;

                    enc_ctx->time_base.num *= dec_ctx->ticks_per_frame;

                }

            }

            if (   enc_ctx->codec_tag == AV_RL32("tmcd")

                && dec_ctx->time_base.num < dec_ctx->time_base.den

                && dec_ctx->time_base.num > 0

                && 121LL*dec_ctx->time_base.num > dec_ctx->time_base.den) {

                enc_ctx->time_base = dec_ctx->time_base;

            }



            if (ist && !ost->frame_rate.num)

                ost->frame_rate = ist->framerate;

            if(ost->frame_rate.num)

                enc_ctx->time_base = av_inv_q(ost->frame_rate);



            av_reduce(&enc_ctx->time_base.num, &enc_ctx->time_base.den,

                        enc_ctx->time_base.num, enc_ctx->time_base.den, INT_MAX);



            if (ist->st->nb_side_data) {

                ost->st->side_data = av_realloc_array(NULL, ist->st->nb_side_data,

                                                      sizeof(*ist->st->side_data));

                if (!ost->st->side_data)

                    return AVERROR(ENOMEM);



                for (j = 0; j < ist->st->nb_side_data; j++) {

                    const AVPacketSideData *sd_src = &ist->st->side_data[j];

                    AVPacketSideData *sd_dst = &ost->st->side_data[j];



                    sd_dst->data = av_malloc(sd_src->size);

                    if (!sd_dst->data)

                        return AVERROR(ENOMEM);

                    memcpy(sd_dst->data, sd_src->data, sd_src->size);

                    sd_dst->size = sd_src->size;

                    sd_dst->type = sd_src->type;

                    ost->st->nb_side_data++;

                }

            }



            ost->parser = av_parser_init(enc_ctx->codec_id);



            switch (enc_ctx->codec_type) {

            case AVMEDIA_TYPE_AUDIO:

                if (audio_volume != 256) {

                    av_log(NULL, AV_LOG_FATAL, "-acodec copy and -vol are incompatible (frames are not decoded)\n");

                    exit_program(1);

                }

                enc_ctx->channel_layout     = dec_ctx->channel_layout;

                enc_ctx->sample_rate        = dec_ctx->sample_rate;

                enc_ctx->channels           = dec_ctx->channels;

                enc_ctx->frame_size         = dec_ctx->frame_size;

                enc_ctx->audio_service_type = dec_ctx->audio_service_type;

                enc_ctx->block_align        = dec_ctx->block_align;

                enc_ctx->initial_padding    = dec_ctx->delay;

#if FF_API_AUDIOENC_DELAY

                enc_ctx->delay              = dec_ctx->delay;

#endif

                if((enc_ctx->block_align == 1 || enc_ctx->block_align == 1152 || enc_ctx->block_align == 576) && enc_ctx->codec_id == AV_CODEC_ID_MP3)

                    enc_ctx->block_align= 0;

                if(enc_ctx->codec_id == AV_CODEC_ID_AC3)

                    enc_ctx->block_align= 0;

                break;

            case AVMEDIA_TYPE_VIDEO:

                enc_ctx->pix_fmt            = dec_ctx->pix_fmt;

                enc_ctx->width              = dec_ctx->width;

                enc_ctx->height             = dec_ctx->height;

                enc_ctx->has_b_frames       = dec_ctx->has_b_frames;

                if (ost->frame_aspect_ratio.num) { // overridden by the -aspect cli option

                    sar =

                        av_mul_q(ost->frame_aspect_ratio,

                                 (AVRational){ enc_ctx->height, enc_ctx->width });

                    av_log(NULL, AV_LOG_WARNING, "Overriding aspect ratio "

                           "with stream copy may produce invalid files\n");

                }

                else if (ist->st->sample_aspect_ratio.num)

                    sar = ist->st->sample_aspect_ratio;

                else

                    sar = dec_ctx->sample_aspect_ratio;

                ost->st->sample_aspect_ratio = enc_ctx->sample_aspect_ratio = sar;

                ost->st->avg_frame_rate = ist->st->avg_frame_rate;

                ost->st->r_frame_rate = ist->st->r_frame_rate;

                break;

            case AVMEDIA_TYPE_SUBTITLE:

                enc_ctx->width  = dec_ctx->width;

                enc_ctx->height = dec_ctx->height;

                break;

            case AVMEDIA_TYPE_DATA:

            case AVMEDIA_TYPE_ATTACHMENT:

                break;

            default:

                abort();

            }

        } else {

            if (!ost->enc)

                ost->enc = avcodec_find_encoder(enc_ctx->codec_id);

            if (!ost->enc) {

                /* should only happen when a default codec is not present. */

                snprintf(error, sizeof(error), "Encoder (codec %s) not found for output stream #%d:%d",

                         avcodec_get_name(ost->st->codec->codec_id), ost->file_index, ost->index);

                ret = AVERROR(EINVAL);

                goto dump_format;

            }



            if (ist)

                ist->decoding_needed |= DECODING_FOR_OST;

            ost->encoding_needed = 1;



            set_encoder_id(output_files[ost->file_index], ost);



            if (!ost->filter &&

                (enc_ctx->codec_type == AVMEDIA_TYPE_VIDEO ||

                 enc_ctx->codec_type == AVMEDIA_TYPE_AUDIO)) {

                    FilterGraph *fg;

                    fg = init_simple_filtergraph(ist, ost);

                    if (configure_filtergraph(fg)) {

                        av_log(NULL, AV_LOG_FATAL, "Error opening filters!\n");

                        exit_program(1);

                    }

            }



            if (enc_ctx->codec_type == AVMEDIA_TYPE_VIDEO) {

                if (ost->filter && !ost->frame_rate.num)

                    ost->frame_rate = av_buffersink_get_frame_rate(ost->filter->filter);

                if (ist && !ost->frame_rate.num)

                    ost->frame_rate = ist->framerate;

                if (ist && !ost->frame_rate.num)

                    ost->frame_rate = ist->st->r_frame_rate;

                if (ist && !ost->frame_rate.num) {

                    ost->frame_rate = (AVRational){25, 1};

                    av_log(NULL, AV_LOG_WARNING,

                           "No information "

                           "about the input framerate is available. Falling "

                           "back to a default value of 25fps for output stream #%d:%d. Use the -r option "

                           "if you want a different framerate.\n",

                           ost->file_index, ost->index);

                }

//                    ost->frame_rate = ist->st->avg_frame_rate.num ? ist->st->avg_frame_rate : (AVRational){25, 1};

                if (ost->enc && ost->enc->supported_framerates && !ost->force_fps) {

                    int idx = av_find_nearest_q_idx(ost->frame_rate, ost->enc->supported_framerates);

                    ost->frame_rate = ost->enc->supported_framerates[idx];

                }

                // reduce frame rate for mpeg4 to be within the spec limits

                if (enc_ctx->codec_id == AV_CODEC_ID_MPEG4) {

                    av_reduce(&ost->frame_rate.num, &ost->frame_rate.den,

                              ost->frame_rate.num, ost->frame_rate.den, 65535);

                }

            }



            switch (enc_ctx->codec_type) {

            case AVMEDIA_TYPE_AUDIO:

                enc_ctx->sample_fmt     = ost->filter->filter->inputs[0]->format;

                enc_ctx->sample_rate    = ost->filter->filter->inputs[0]->sample_rate;

                enc_ctx->channel_layout = ost->filter->filter->inputs[0]->channel_layout;

                enc_ctx->channels       = avfilter_link_get_channels(ost->filter->filter->inputs[0]);

                enc_ctx->time_base      = (AVRational){ 1, enc_ctx->sample_rate };

                break;

            case AVMEDIA_TYPE_VIDEO:

                enc_ctx->time_base = av_inv_q(ost->frame_rate);

                if (ost->filter && !(enc_ctx->time_base.num && enc_ctx->time_base.den))

                    enc_ctx->time_base = ost->filter->filter->inputs[0]->time_base;

                if (   av_q2d(enc_ctx->time_base) < 0.001 && video_sync_method != VSYNC_PASSTHROUGH

                   && (video_sync_method == VSYNC_CFR || video_sync_method == VSYNC_VSCFR || (video_sync_method == VSYNC_AUTO && !(oc->oformat->flags & AVFMT_VARIABLE_FPS)))){

                    av_log(oc, AV_LOG_WARNING, "Frame rate very high for a muxer not efficiently supporting it.\n"

                                               "Please consider specifying a lower framerate, a different muxer or -vsync 2\n");

                }

                for (j = 0; j < ost->forced_kf_count; j++)

                    ost->forced_kf_pts[j] = av_rescale_q(ost->forced_kf_pts[j],

                                                         AV_TIME_BASE_Q,

                                                         enc_ctx->time_base);



                enc_ctx->width  = ost->filter->filter->inputs[0]->w;

                enc_ctx->height = ost->filter->filter->inputs[0]->h;

                enc_ctx->sample_aspect_ratio = ost->st->sample_aspect_ratio =

                    ost->frame_aspect_ratio.num ? // overridden by the -aspect cli option

                    av_mul_q(ost->frame_aspect_ratio, (AVRational){ enc_ctx->height, enc_ctx->width }) :

                    ost->filter->filter->inputs[0]->sample_aspect_ratio;

                if (!strncmp(ost->enc->name, "libx264", 7) &&

                    enc_ctx->pix_fmt == AV_PIX_FMT_NONE &&

                    ost->filter->filter->inputs[0]->format != AV_PIX_FMT_YUV420P)

                    av_log(NULL, AV_LOG_WARNING,

                           "No pixel format specified, %s for H.264 encoding chosen.\n"

                           "Use -pix_fmt yuv420p for compatibility with outdated media players.\n",

                           av_get_pix_fmt_name(ost->filter->filter->inputs[0]->format));

                if (!strncmp(ost->enc->name, "mpeg2video", 10) &&

                    enc_ctx->pix_fmt == AV_PIX_FMT_NONE &&

                    ost->filter->filter->inputs[0]->format != AV_PIX_FMT_YUV420P)

                    av_log(NULL, AV_LOG_WARNING,

                           "No pixel format specified, %s for MPEG-2 encoding chosen.\n"

                           "Use -pix_fmt yuv420p for compatibility with outdated media players.\n",

                           av_get_pix_fmt_name(ost->filter->filter->inputs[0]->format));

                enc_ctx->pix_fmt = ost->filter->filter->inputs[0]->format;



                ost->st->avg_frame_rate = ost->frame_rate;



                if (!dec_ctx ||

                    enc_ctx->width   != dec_ctx->width  ||

                    enc_ctx->height  != dec_ctx->height ||

                    enc_ctx->pix_fmt != dec_ctx->pix_fmt) {

                    enc_ctx->bits_per_raw_sample = frame_bits_per_raw_sample;

                }



                if (ost->forced_keyframes) {

                    if (!strncmp(ost->forced_keyframes, "expr:", 5)) {

                        ret = av_expr_parse(&ost->forced_keyframes_pexpr, ost->forced_keyframes+5,

                                            forced_keyframes_const_names, NULL, NULL, NULL, NULL, 0, NULL);

                        if (ret < 0) {

                            av_log(NULL, AV_LOG_ERROR,

                                   "Invalid force_key_frames expression '%s'\n", ost->forced_keyframes+5);

                            return ret;

                        }

                        ost->forced_keyframes_expr_const_values[FKF_N] = 0;

                        ost->forced_keyframes_expr_const_values[FKF_N_FORCED] = 0;

                        ost->forced_keyframes_expr_const_values[FKF_PREV_FORCED_N] = NAN;

                        ost->forced_keyframes_expr_const_values[FKF_PREV_FORCED_T] = NAN;

                    } else {

                        parse_forced_key_frames(ost->forced_keyframes, ost, ost->enc_ctx);

                    }

                }

                break;

            case AVMEDIA_TYPE_SUBTITLE:

                enc_ctx->time_base = (AVRational){1, 1000};

                if (!enc_ctx->width) {

                    enc_ctx->width     = input_streams[ost->source_index]->st->codec->width;

                    enc_ctx->height    = input_streams[ost->source_index]->st->codec->height;

                }

                break;

            case AVMEDIA_TYPE_DATA:

                break;

            default:

                abort();

                break;

            }

            /* two pass mode */

            if (enc_ctx->flags & (CODEC_FLAG_PASS1 | CODEC_FLAG_PASS2)) {

                char logfilename[1024];

                FILE *f;



                snprintf(logfilename, sizeof(logfilename), "%s-%d.log",

                         ost->logfile_prefix ? ost->logfile_prefix :

                                               DEFAULT_PASS_LOGFILENAME_PREFIX,

                         i);

                if (!strcmp(ost->enc->name, "libx264")) {

                    av_dict_set(&ost->encoder_opts, "stats", logfilename, AV_DICT_DONT_OVERWRITE);

                } else {

                    if (enc_ctx->flags & CODEC_FLAG_PASS2) {

                        char  *logbuffer;

                        size_t logbuffer_size;

                        if (cmdutils_read_file(logfilename, &logbuffer, &logbuffer_size) < 0) {

                            av_log(NULL, AV_LOG_FATAL, "Error reading log file '%s' for pass-2 encoding\n",

                                   logfilename);

                            exit_program(1);

                        }

                        enc_ctx->stats_in = logbuffer;

                    }

                    if (enc_ctx->flags & CODEC_FLAG_PASS1) {

                        f = av_fopen_utf8(logfilename, "wb");

                        if (!f) {

                            av_log(NULL, AV_LOG_FATAL, "Cannot write log file '%s' for pass-1 encoding: %s\n",

                                logfilename, strerror(errno));

                            exit_program(1);

                        }

                        ost->logfile = f;

                    }

                }

            }

        }



        if (ost->disposition) {

            static const AVOption opts[] = {

                { "disposition"         , NULL, 0, AV_OPT_TYPE_FLAGS, { .i64 = 0 }, INT64_MIN, INT64_MAX, .unit = "flags" },

                { "default"             , NULL, 0, AV_OPT_TYPE_CONST, { .i64 = AV_DISPOSITION_DEFAULT           },    .unit = "flags" },

                { "dub"                 , NULL, 0, AV_OPT_TYPE_CONST, { .i64 = AV_DISPOSITION_DUB               },    .unit = "flags" },

                { "original"            , NULL, 0, AV_OPT_TYPE_CONST, { .i64 = AV_DISPOSITION_ORIGINAL          },    .unit = "flags" },

                { "comment"             , NULL, 0, AV_OPT_TYPE_CONST, { .i64 = AV_DISPOSITION_COMMENT           },    .unit = "flags" },

                { "lyrics"              , NULL, 0, AV_OPT_TYPE_CONST, { .i64 = AV_DISPOSITION_LYRICS            },    .unit = "flags" },

                { "karaoke"             , NULL, 0, AV_OPT_TYPE_CONST, { .i64 = AV_DISPOSITION_KARAOKE           },    .unit = "flags" },

                { "forced"              , NULL, 0, AV_OPT_TYPE_CONST, { .i64 = AV_DISPOSITION_FORCED            },    .unit = "flags" },

                { "hearing_impaired"    , NULL, 0, AV_OPT_TYPE_CONST, { .i64 = AV_DISPOSITION_HEARING_IMPAIRED  },    .unit = "flags" },

                { "visual_impaired"     , NULL, 0, AV_OPT_TYPE_CONST, { .i64 = AV_DISPOSITION_VISUAL_IMPAIRED   },    .unit = "flags" },

                { "clean_effects"       , NULL, 0, AV_OPT_TYPE_CONST, { .i64 = AV_DISPOSITION_CLEAN_EFFECTS     },    .unit = "flags" },

                { "captions"            , NULL, 0, AV_OPT_TYPE_CONST, { .i64 = AV_DISPOSITION_CAPTIONS          },    .unit = "flags" },

                { "descriptions"        , NULL, 0, AV_OPT_TYPE_CONST, { .i64 = AV_DISPOSITION_DESCRIPTIONS      },    .unit = "flags" },

                { "metadata"            , NULL, 0, AV_OPT_TYPE_CONST, { .i64 = AV_DISPOSITION_METADATA          },    .unit = "flags" },

                { NULL },

            };

            static const AVClass class = {

                .class_name = "",

                .item_name  = av_default_item_name,

                .option     = opts,

                .version    = LIBAVUTIL_VERSION_INT,

            };

            const AVClass *pclass = &class;



            ret = av_opt_eval_flags(&pclass, &opts[0], ost->disposition, &ost->st->disposition);

            if (ret < 0)

                goto dump_format;

        }

    }



    /* open each encoder */

    for (i = 0; i < nb_output_streams; i++) {

        ost = output_streams[i];

        if (ost->encoding_needed) {

            AVCodec      *codec = ost->enc;

            AVCodecContext *dec = NULL;



            if ((ist = get_input_stream(ost)))

                dec = ist->dec_ctx;

            if (dec && dec->subtitle_header) {

                /* ASS code assumes this buffer is null terminated so add extra byte. */

                ost->enc_ctx->subtitle_header = av_mallocz(dec->subtitle_header_size + 1);

                if (!ost->enc_ctx->subtitle_header) {

                    ret = AVERROR(ENOMEM);

                    goto dump_format;

                }

                memcpy(ost->enc_ctx->subtitle_header, dec->subtitle_header, dec->subtitle_header_size);

                ost->enc_ctx->subtitle_header_size = dec->subtitle_header_size;

            }

            if (!av_dict_get(ost->encoder_opts, "threads", NULL, 0))

                av_dict_set(&ost->encoder_opts, "threads", "auto", 0);

            av_dict_set(&ost->encoder_opts, "side_data_only_packets", "1", 0);



            if ((ret = avcodec_open2(ost->enc_ctx, codec, &ost->encoder_opts)) < 0) {

                if (ret == AVERROR_EXPERIMENTAL)

                    abort_codec_experimental(codec, 1);

                snprintf(error, sizeof(error), "Error while opening encoder for output stream #%d:%d - maybe incorrect parameters such as bit_rate, rate, width or height",

                        ost->file_index, ost->index);

                goto dump_format;

            }

            if (ost->enc->type == AVMEDIA_TYPE_AUDIO &&

                !(ost->enc->capabilities & CODEC_CAP_VARIABLE_FRAME_SIZE))

                av_buffersink_set_frame_size(ost->filter->filter,

                                             ost->enc_ctx->frame_size);

            assert_avoptions(ost->encoder_opts);

            if (ost->enc_ctx->bit_rate && ost->enc_ctx->bit_rate < 1000)

                av_log(NULL, AV_LOG_WARNING, "The bitrate parameter is set too low."

                                             " It takes bits/s as argument, not kbits/s\n");



            ret = avcodec_copy_context(ost->st->codec, ost->enc_ctx);

            if (ret < 0) {

                av_log(NULL, AV_LOG_FATAL,

                       "Error initializing the output stream codec context.\n");

                exit_program(1);

            }



            // copy timebase while removing common factors

            ost->st->time_base = av_add_q(ost->enc_ctx->time_base, (AVRational){0, 1});

            ost->st->codec->codec= ost->enc_ctx->codec;

        } else {

            ret = av_opt_set_dict(ost->enc_ctx, &ost->encoder_opts);

            if (ret < 0) {

                av_log(NULL, AV_LOG_FATAL,

                    "Error setting up codec context options.\n");

                return ret;

            }

            // copy timebase while removing common factors

            ost->st->time_base = av_add_q(ost->st->codec->time_base, (AVRational){0, 1});

        }

    }



    /* init input streams */

    for (i = 0; i < nb_input_streams; i++)

        if ((ret = init_input_stream(i, error, sizeof(error))) < 0) {

            for (i = 0; i < nb_output_streams; i++) {

                ost = output_streams[i];

                avcodec_close(ost->enc_ctx);

            }

            goto dump_format;

        }



    /* discard unused programs */

    for (i = 0; i < nb_input_files; i++) {

        InputFile *ifile = input_files[i];

        for (j = 0; j < ifile->ctx->nb_programs; j++) {

            AVProgram *p = ifile->ctx->programs[j];

            int discard  = AVDISCARD_ALL;



            for (k = 0; k < p->nb_stream_indexes; k++)

                if (!input_streams[ifile->ist_index + p->stream_index[k]]->discard) {

                    discard = AVDISCARD_DEFAULT;

                    break;

                }

            p->discard = discard;

        }

    }



    /* open files and write file headers */

    for (i = 0; i < nb_output_files; i++) {

        oc = output_files[i]->ctx;

        oc->interrupt_callback = int_cb;

        if ((ret = avformat_write_header(oc, &output_files[i]->opts)) < 0) {

            snprintf(error, sizeof(error),

                     "Could not write header for output file #%d "

                     "(incorrect codec parameters ?): %s",

                     i, av_err2str(ret));

            ret = AVERROR(EINVAL);

            goto dump_format;

        }

//         assert_avoptions(output_files[i]->opts);

        if (strcmp(oc->oformat->name, "rtp")) {

            want_sdp = 0;

        }

    }



 dump_format:

    /* dump the file output parameters - cannot be done before in case

       of stream copy */

    for (i = 0; i < nb_output_files; i++) {

        av_dump_format(output_files[i]->ctx, i, output_files[i]->ctx->filename, 1);

    }



    /* dump the stream mapping */

    av_log(NULL, AV_LOG_INFO, "Stream mapping:\n");

    for (i = 0; i < nb_input_streams; i++) {

        ist = input_streams[i];



        for (j = 0; j < ist->nb_filters; j++) {

            if (ist->filters[j]->graph->graph_desc) {

                av_log(NULL, AV_LOG_INFO, "  Stream #%d:%d (%s) -> %s",

                       ist->file_index, ist->st->index, ist->dec ? ist->dec->name : "?",

                       ist->filters[j]->name);

                if (nb_filtergraphs > 1)

                    av_log(NULL, AV_LOG_INFO, " (graph %d)", ist->filters[j]->graph->index);

                av_log(NULL, AV_LOG_INFO, "\n");

            }

        }

    }



    for (i = 0; i < nb_output_streams; i++) {

        ost = output_streams[i];



        if (ost->attachment_filename) {

            /* an attached file */

            av_log(NULL, AV_LOG_INFO, "  File %s -> Stream #%d:%d\n",

                   ost->attachment_filename, ost->file_index, ost->index);

            continue;

        }



        if (ost->filter && ost->filter->graph->graph_desc) {

            /* output from a complex graph */

            av_log(NULL, AV_LOG_INFO, "  %s", ost->filter->name);

            if (nb_filtergraphs > 1)

                av_log(NULL, AV_LOG_INFO, " (graph %d)", ost->filter->graph->index);



            av_log(NULL, AV_LOG_INFO, " -> Stream #%d:%d (%s)\n", ost->file_index,

                   ost->index, ost->enc ? ost->enc->name : "?");

            continue;

        }



        av_log(NULL, AV_LOG_INFO, "  Stream #%d:%d -> #%d:%d",

               input_streams[ost->source_index]->file_index,

               input_streams[ost->source_index]->st->index,

               ost->file_index,

               ost->index);

        if (ost->sync_ist != input_streams[ost->source_index])

            av_log(NULL, AV_LOG_INFO, " [sync #%d:%d]",

                   ost->sync_ist->file_index,

                   ost->sync_ist->st->index);

        if (ost->stream_copy)

            av_log(NULL, AV_LOG_INFO, " (copy)");

        else {

            const AVCodec *in_codec    = input_streams[ost->source_index]->dec;

            const AVCodec *out_codec   = ost->enc;

            const char *decoder_name   = "?";

            const char *in_codec_name  = "?";

            const char *encoder_name   = "?";

            const char *out_codec_name = "?";

            const AVCodecDescriptor *desc;



            if (in_codec) {

                decoder_name  = in_codec->name;

                desc = avcodec_descriptor_get(in_codec->id);

                if (desc)

                    in_codec_name = desc->name;

                if (!strcmp(decoder_name, in_codec_name))

                    decoder_name = "native";

            }



            if (out_codec) {

                encoder_name   = out_codec->name;

                desc = avcodec_descriptor_get(out_codec->id);

                if (desc)

                    out_codec_name = desc->name;

                if (!strcmp(encoder_name, out_codec_name))

                    encoder_name = "native";

            }



            av_log(NULL, AV_LOG_INFO, " (%s (%s) -> %s (%s))",

                   in_codec_name, decoder_name,

                   out_codec_name, encoder_name);

        }

        av_log(NULL, AV_LOG_INFO, "\n");

    }



    if (ret) {

        av_log(NULL, AV_LOG_ERROR, "%s\n", error);

        return ret;

    }



    if (sdp_filename || want_sdp) {

        print_sdp();

    }



    transcode_init_done = 1;



    return 0;

}

static int mp3_read_packet(AVFormatContext *s, AVPacket *pkt)

{

    int ret;



    ret = av_get_packet(s->pb, pkt, MP3_PACKET_SIZE);



    pkt->stream_index = 0;

    if (ret <= 0) {

        return AVERROR(EIO);

    }



    if (ret > ID3v1_TAG_SIZE &&

        memcmp(&pkt->data[ret - ID3v1_TAG_SIZE], "TAG", 3) == 0)

        ret -= ID3v1_TAG_SIZE;



    /* note: we need to modify the packet size here to handle the last

       packet */

    pkt->size = ret;

    return ret;

}

static void ff_h264_idct_add_mmx(uint8_t *dst, int16_t *block, int stride)

{

    /* Load dct coeffs */

    __asm__ volatile(

        "movq   (%0), %%mm0 \n\t"

        "movq  8(%0), %%mm1 \n\t"

        "movq 16(%0), %%mm2 \n\t"

        "movq 24(%0), %%mm3 \n\t"

    :: "r"(block) );



    __asm__ volatile(

        /* mm1=s02+s13  mm2=s02-s13  mm4=d02+d13  mm0=d02-d13 */

        IDCT4_1D( %%mm2, %%mm1, %%mm0, %%mm3, %%mm4 )



        "movq      %0,    %%mm6 \n\t"

        /* in: 1,4,0,2  out: 1,2,3,0 */

        TRANSPOSE4( %%mm3, %%mm1, %%mm0, %%mm2, %%mm4 )



        "paddw     %%mm6, %%mm3 \n\t"



        /* mm2=s02+s13  mm3=s02-s13  mm4=d02+d13  mm1=d02-d13 */

        IDCT4_1D( %%mm4, %%mm2, %%mm3, %%mm0, %%mm1 )



        "pxor %%mm7, %%mm7    \n\t"

    :: "m"(ff_pw_32));



    __asm__ volatile(

    STORE_DIFF_4P( %%mm0, %%mm1, %%mm7)

        "add %1, %0             \n\t"

    STORE_DIFF_4P( %%mm2, %%mm1, %%mm7)

        "add %1, %0             \n\t"

    STORE_DIFF_4P( %%mm3, %%mm1, %%mm7)

        "add %1, %0             \n\t"

    STORE_DIFF_4P( %%mm4, %%mm1, %%mm7)

        : "+r"(dst)

        : "r" ((x86_reg)stride)

    );

}

