static enum AVPixelFormat get_format(HEVCContext *s, const HEVCSPS *sps)

{

    #define HWACCEL_MAX (CONFIG_HEVC_DXVA2_HWACCEL + CONFIG_HEVC_D3D11VA_HWACCEL + CONFIG_HEVC_VAAPI_HWACCEL + CONFIG_HEVC_VDPAU_HWACCEL)

    enum AVPixelFormat pix_fmts[HWACCEL_MAX + 2], *fmt = pix_fmts;



    switch (sps->pix_fmt) {

    case AV_PIX_FMT_YUV420P:

    case AV_PIX_FMT_YUVJ420P:

#if CONFIG_HEVC_DXVA2_HWACCEL

        *fmt++ = AV_PIX_FMT_DXVA2_VLD;

#endif

#if CONFIG_HEVC_D3D11VA_HWACCEL

        *fmt++ = AV_PIX_FMT_D3D11VA_VLD;

#endif

#if CONFIG_HEVC_VAAPI_HWACCEL

        *fmt++ = AV_PIX_FMT_VAAPI;

#endif

#if CONFIG_HEVC_VDPAU_HWACCEL

        *fmt++ = AV_PIX_FMT_VDPAU;

#endif

        break;

    case AV_PIX_FMT_YUV420P10:

#if CONFIG_HEVC_DXVA2_HWACCEL

        *fmt++ = AV_PIX_FMT_DXVA2_VLD;

#endif

#if CONFIG_HEVC_D3D11VA_HWACCEL

        *fmt++ = AV_PIX_FMT_D3D11VA_VLD;

#endif

#if CONFIG_HEVC_VAAPI_HWACCEL

        *fmt++ = AV_PIX_FMT_VAAPI;

#endif

        break;

    }



    *fmt++ = sps->pix_fmt;

    *fmt = AV_PIX_FMT_NONE;



    return ff_thread_get_format(s->avctx, pix_fmts);

}

av_cold void ff_fft_init_x86(FFTContext *s)

{

    int cpu_flags = av_get_cpu_flags();



#if ARCH_X86_32

    if (EXTERNAL_AMD3DNOW(cpu_flags)) {

        /* 3DNow! for K6-2/3 */

        s->imdct_calc = ff_imdct_calc_3dnow;

        s->imdct_half = ff_imdct_half_3dnow;

        s->fft_calc   = ff_fft_calc_3dnow;

    }

    if (EXTERNAL_AMD3DNOWEXT(cpu_flags)) {

        /* 3DNowEx for K7 */

        s->imdct_calc = ff_imdct_calc_3dnowext;

        s->imdct_half = ff_imdct_half_3dnowext;

        s->fft_calc   = ff_fft_calc_3dnowext;

    }

#endif

    if (EXTERNAL_SSE(cpu_flags)) {

        /* SSE for P3/P4/K8 */

        s->imdct_calc  = ff_imdct_calc_sse;

        s->imdct_half  = ff_imdct_half_sse;

        s->fft_permute = ff_fft_permute_sse;

        s->fft_calc    = ff_fft_calc_sse;

        s->fft_permutation = FF_FFT_PERM_SWAP_LSBS;

    }

    if (EXTERNAL_AVX(cpu_flags) && s->nbits >= 5) {

        /* AVX for SB */

        s->imdct_half      = ff_imdct_half_avx;

        s->fft_calc        = ff_fft_calc_avx;

        s->fft_permutation = FF_FFT_PERM_AVX;

    }

}

static void print_samplesref(AVFilterBufferRef *samplesref)

{

    const AVFilterBufferRefAudioProps *props = samplesref->audio;

    const int n = props->nb_samples * av_get_channel_layout_nb_channels(props->channel_layout);

    const uint16_t *p     = (uint16_t*)samplesref->data[0];

    const uint16_t *p_end = p + n;



    while (p < p_end) {

        fputc(*p    & 0xff, stdout);

        fputc(*p>>8 & 0xff, stdout);

        p++;

    }

    fflush(stdout);

}

static int h261_decode_gob_header(H261Context *h){

    unsigned int val;

    MpegEncContext * const s = &h->s;



    /* Check for GOB Start Code */

    val = show_bits(&s->gb, 15);

    if(val)

        return -1;



    /* We have a GBSC */

    skip_bits(&s->gb, 16);



    h->gob_number = get_bits(&s->gb, 4); /* GN */

    s->qscale = get_bits(&s->gb, 5); /* GQUANT */



    /* GEI */

    while (get_bits1(&s->gb) != 0) {

        skip_bits(&s->gb, 8);

    }



    if(s->qscale==0)

        return -1;



    // For the first transmitted macroblock in a GOB, MBA is the absolute address. For

    // subsequent macroblocks, MBA is the difference between the absolute addresses of

    // the macroblock and the last transmitted macroblock.

    h->current_mba = 0;

    h->mba_diff = 0;



    return 0;

}

static int read_rle_sgi(uint8_t *out_buf, SgiState *s)

{

    uint8_t *dest_row;

    unsigned int len = s->height * s->depth * 4;

    GetByteContext g_table = s->g;

    unsigned int y, z;

    unsigned int start_offset;



    /* size of  RLE offset and length tables */

    if (len * 2  > bytestream2_get_bytes_left(&s->g)) {

        return AVERROR_INVALIDDATA;

    }



    for (z = 0; z < s->depth; z++) {

        dest_row = out_buf;

        for (y = 0; y < s->height; y++) {

            dest_row -= s->linesize;

            start_offset = bytestream2_get_be32(&g_table);

            bytestream2_seek(&s->g, start_offset, SEEK_SET);

            if (expand_rle_row(s, dest_row + z, dest_row + FFABS(s->linesize),

                               s->depth) != s->width) {

                return AVERROR_INVALIDDATA;

            }

        }

    }

    return 0;

}

static inline void RENAME(uyvyToY)(uint8_t *dst, const uint8_t *src, long width, uint32_t *unused)

{

#if COMPILE_TEMPLATE_MMX

    __asm__ volatile(

        "mov                  %0, %%"REG_a"         \n\t"

        "1:                                         \n\t"

        "movq  (%1, %%"REG_a",2), %%mm0             \n\t"

        "movq 8(%1, %%"REG_a",2), %%mm1             \n\t"

        "psrlw                $8, %%mm0             \n\t"

        "psrlw                $8, %%mm1             \n\t"

        "packuswb          %%mm1, %%mm0             \n\t"

        "movq              %%mm0, (%2, %%"REG_a")   \n\t"

        "add                  $8, %%"REG_a"         \n\t"

        " js                  1b                    \n\t"

        : : "g" ((x86_reg)-width), "r" (src+width*2), "r" (dst+width)

        : "%"REG_a

    );

#else

    int i;

    for (i=0; i<width; i++)

        dst[i]= src[2*i+1];

#endif

}

