static int encode_block(SVQ1Context *s, uint8_t *src, uint8_t *ref, uint8_t *decoded, int stride, int level, int threshold, int lambda, int intra){

    int count, y, x, i, j, split, best_mean, best_score, best_count;

    int best_vector[6];

    int block_sum[7]= {0, 0, 0, 0, 0, 0};

    int w= 2<<((level+2)>>1);

    int h= 2<<((level+1)>>1);

    int size=w*h;

    int16_t block[7][256];

    const int8_t *codebook_sum, *codebook;

    const uint16_t (*mean_vlc)[2];

    const uint8_t (*multistage_vlc)[2];



    best_score=0;

    //FIXME optimize, this doenst need to be done multiple times

    if(intra){

        codebook_sum= svq1_intra_codebook_sum[level];

        codebook= ff_svq1_intra_codebooks[level];

        mean_vlc= ff_svq1_intra_mean_vlc;

        multistage_vlc= ff_svq1_intra_multistage_vlc[level];

        for(y=0; y<h; y++){

            for(x=0; x<w; x++){

                int v= src[x + y*stride];

                block[0][x + w*y]= v;

                best_score += v*v;

                block_sum[0] += v;

            }

        }

    }else{

        codebook_sum= svq1_inter_codebook_sum[level];

        codebook= ff_svq1_inter_codebooks[level];

        mean_vlc= ff_svq1_inter_mean_vlc + 256;

        multistage_vlc= ff_svq1_inter_multistage_vlc[level];

        for(y=0; y<h; y++){

            for(x=0; x<w; x++){

                int v= src[x + y*stride] - ref[x + y*stride];

                block[0][x + w*y]= v;

                best_score += v*v;

                block_sum[0] += v;

            }

        }

    }



    best_count=0;

    best_score -= ((block_sum[0]*block_sum[0])>>(level+3));

    best_mean= (block_sum[0] + (size>>1)) >> (level+3);



    if(level<4){

        for(count=1; count<7; count++){

            int best_vector_score= INT_MAX;

            int best_vector_sum=-999, best_vector_mean=-999;

            const int stage= count-1;

            const int8_t *vector;



            for(i=0; i<16; i++){

                int sum= codebook_sum[stage*16 + i];

                int sqr, diff, score;



                vector = codebook + stage*size*16 + i*size;

                sqr = s->dsp.ssd_int8_vs_int16(vector, block[stage], size);

                diff= block_sum[stage] - sum;

                score= sqr - ((diff*(int64_t)diff)>>(level+3)); //FIXME 64bit slooow

                if(score < best_vector_score){

                    int mean= (diff + (size>>1)) >> (level+3);

                    assert(mean >-300 && mean<300);

                    mean= av_clip(mean, intra?0:-256, 255);

                    best_vector_score= score;

                    best_vector[stage]= i;

                    best_vector_sum= sum;

                    best_vector_mean= mean;

                }

            }

            assert(best_vector_mean != -999);

            vector= codebook + stage*size*16 + best_vector[stage]*size;

            for(j=0; j<size; j++){

                block[stage+1][j] = block[stage][j] - vector[j];

            }

            block_sum[stage+1]= block_sum[stage] - best_vector_sum;

            best_vector_score +=

                lambda*(+ 1 + 4*count

                        + multistage_vlc[1+count][1]

                        + mean_vlc[best_vector_mean][1]);



            if(best_vector_score < best_score){

                best_score= best_vector_score;

                best_count= count;

                best_mean= best_vector_mean;

            }

        }

    }



    split=0;

    if(best_score > threshold && level){

        int score=0;

        int offset= (level&1) ? stride*h/2 : w/2;

        PutBitContext backup[6];



        for(i=level-1; i>=0; i--){

            backup[i]= s->reorder_pb[i];

        }

        score += encode_block(s, src         , ref         , decoded         , stride, level-1, threshold>>1, lambda, intra);

        score += encode_block(s, src + offset, ref + offset, decoded + offset, stride, level-1, threshold>>1, lambda, intra);

        score += lambda;



        if(score < best_score){

            best_score= score;

            split=1;

        }else{

            for(i=level-1; i>=0; i--){

                s->reorder_pb[i]= backup[i];

            }

        }

    }

    if (level > 0)

        put_bits(&s->reorder_pb[level], 1, split);



    if(!split){

        assert((best_mean >= 0 && best_mean<256) || !intra);

        assert(best_mean >= -256 && best_mean<256);

        assert(best_count >=0 && best_count<7);

        assert(level<4 || best_count==0);



        /* output the encoding */

        put_bits(&s->reorder_pb[level],

            multistage_vlc[1 + best_count][1],

            multistage_vlc[1 + best_count][0]);

        put_bits(&s->reorder_pb[level], mean_vlc[best_mean][1],

            mean_vlc[best_mean][0]);



        for (i = 0; i < best_count; i++){

            assert(best_vector[i]>=0 && best_vector[i]<16);

            put_bits(&s->reorder_pb[level], 4, best_vector[i]);

        }



        for(y=0; y<h; y++){

            for(x=0; x<w; x++){

                decoded[x + y*stride]= src[x + y*stride] - block[best_count][x + w*y] + best_mean;

            }

        }

    }



    return best_score;

}

static void horizontal_filter(unsigned char *first_pixel, int stride,

    int *bounding_values)

{

    unsigned char *end;

    int filter_value;



    for (end= first_pixel + 8*stride; first_pixel < end; first_pixel += stride) {

        filter_value =

            (first_pixel[-2] - first_pixel[ 1])

         +3*(first_pixel[ 0] - first_pixel[-1]);

        filter_value = bounding_values[(filter_value + 4) >> 3];

        first_pixel[-1] = clip_uint8(first_pixel[-1] + filter_value);

        first_pixel[ 0] = clip_uint8(first_pixel[ 0] - filter_value);

    }

}

static void synthfilt_build_sb_samples(QDM2Context *q, GetBitContext *gb,

                                       int length, int sb_min, int sb_max)

{

    int sb, j, k, n, ch, run, channels;

    int joined_stereo, zero_encoding, chs;

    int type34_first;

    float type34_div = 0;

    float type34_predictor;

    float samples[10], sign_bits[16];



    if (length == 0) {

        // If no data use noise

        for (sb=sb_min; sb < sb_max; sb++)

            build_sb_samples_from_noise (q, sb);



        return;

    }



    for (sb = sb_min; sb < sb_max; sb++) {

        FIX_NOISE_IDX(q->noise_idx);



        channels = q->nb_channels;



        if (q->nb_channels <= 1 || sb < 12)

            joined_stereo = 0;

        else if (sb >= 24)

            joined_stereo = 1;

        else

            joined_stereo = (get_bits_left(gb) >= 1) ? get_bits1 (gb) : 0;



        if (joined_stereo) {

            if (get_bits_left(gb) >= 16)

                for (j = 0; j < 16; j++)

                    sign_bits[j] = get_bits1 (gb);



            for (j = 0; j < 64; j++)

                if (q->coding_method[1][sb][j] > q->coding_method[0][sb][j])

                    q->coding_method[0][sb][j] = q->coding_method[1][sb][j];



            fix_coding_method_array(sb, q->nb_channels, q->coding_method);

            channels = 1;

        }



        for (ch = 0; ch < channels; ch++) {

            zero_encoding = (get_bits_left(gb) >= 1) ? get_bits1(gb) : 0;

            type34_predictor = 0.0;

            type34_first = 1;



            for (j = 0; j < 128; ) {

                switch (q->coding_method[ch][sb][j / 2]) {

                    case 8:

                        if (get_bits_left(gb) >= 10) {

                            if (zero_encoding) {

                                for (k = 0; k < 5; k++) {

                                    if ((j + 2 * k) >= 128)

                                        break;

                                    samples[2 * k] = get_bits1(gb) ? dequant_1bit[joined_stereo][2 * get_bits1(gb)] : 0;

                                }

                            } else {

                                n = get_bits(gb, 8);

                                for (k = 0; k < 5; k++)

                                    samples[2 * k] = dequant_1bit[joined_stereo][random_dequant_index[n][k]];

                            }

                            for (k = 0; k < 5; k++)

                                samples[2 * k + 1] = SB_DITHERING_NOISE(sb,q->noise_idx);

                        } else {

                            for (k = 0; k < 10; k++)

                                samples[k] = SB_DITHERING_NOISE(sb,q->noise_idx);

                        }

                        run = 10;

                        break;



                    case 10:

                        if (get_bits_left(gb) >= 1) {

                            float f = 0.81;



                            if (get_bits1(gb))

                                f = -f;

                            f -= noise_samples[((sb + 1) * (j +5 * ch + 1)) & 127] * 9.0 / 40.0;

                            samples[0] = f;

                        } else {

                            samples[0] = SB_DITHERING_NOISE(sb,q->noise_idx);

                        }

                        run = 1;

                        break;



                    case 16:

                        if (get_bits_left(gb) >= 10) {

                            if (zero_encoding) {

                                for (k = 0; k < 5; k++) {

                                    if ((j + k) >= 128)

                                        break;

                                    samples[k] = (get_bits1(gb) == 0) ? 0 : dequant_1bit[joined_stereo][2 * get_bits1(gb)];

                                }

                            } else {

                                n = get_bits (gb, 8);

                                for (k = 0; k < 5; k++)

                                    samples[k] = dequant_1bit[joined_stereo][random_dequant_index[n][k]];

                            }

                        } else {

                            for (k = 0; k < 5; k++)

                                samples[k] = SB_DITHERING_NOISE(sb,q->noise_idx);

                        }

                        run = 5;

                        break;



                    case 24:

                        if (get_bits_left(gb) >= 7) {

                            n = get_bits(gb, 7);

                            for (k = 0; k < 3; k++)

                                samples[k] = (random_dequant_type24[n][k] - 2.0) * 0.5;

                        } else {

                            for (k = 0; k < 3; k++)

                                samples[k] = SB_DITHERING_NOISE(sb,q->noise_idx);

                        }

                        run = 3;

                        break;



                    case 30:

                        if (get_bits_left(gb) >= 4) {

                            unsigned index = qdm2_get_vlc(gb, &vlc_tab_type30, 0, 1);

                            if (index < FF_ARRAY_ELEMS(type30_dequant)) {

                                samples[0] = type30_dequant[index];

                            } else

                                samples[0] = SB_DITHERING_NOISE(sb,q->noise_idx);

                        } else

                            samples[0] = SB_DITHERING_NOISE(sb,q->noise_idx);



                        run = 1;

                        break;



                    case 34:

                        if (get_bits_left(gb) >= 7) {

                            if (type34_first) {

                                type34_div = (float)(1 << get_bits(gb, 2));

                                samples[0] = ((float)get_bits(gb, 5) - 16.0) / 15.0;

                                type34_predictor = samples[0];

                                type34_first = 0;

                            } else {

                                unsigned index = qdm2_get_vlc(gb, &vlc_tab_type34, 0, 1);

                                if (index < FF_ARRAY_ELEMS(type34_delta)) {

                                    samples[0] = type34_delta[index] / type34_div + type34_predictor;

                                    type34_predictor = samples[0];

                                } else

                                    samples[0] = SB_DITHERING_NOISE(sb,q->noise_idx);

                            }

                        } else {

                            samples[0] = SB_DITHERING_NOISE(sb,q->noise_idx);

                        }

                        run = 1;

                        break;



                    default:

                        samples[0] = SB_DITHERING_NOISE(sb,q->noise_idx);

                        run = 1;

                        break;

                }



                if (joined_stereo) {

                    float tmp[10][MPA_MAX_CHANNELS];



                    for (k = 0; k < run; k++) {

                        tmp[k][0] = samples[k];

                        tmp[k][1] = (sign_bits[(j + k) / 8]) ? -samples[k] : samples[k];

                    }

                    for (chs = 0; chs < q->nb_channels; chs++)

                        for (k = 0; k < run; k++)

                            if ((j + k) < 128)

                                q->sb_samples[chs][j + k][sb] = q->tone_level[chs][sb][((j + k)/2)] * tmp[k][chs];

                } else {

                    for (k = 0; k < run; k++)

                        if ((j + k) < 128)

                            q->sb_samples[ch][j + k][sb] = q->tone_level[ch][sb][(j + k)/2] * samples[k];

                }



                j += run;

            } // j loop

        } // channel loop

    } // subband loop

}

static int latm_write_packet(AVFormatContext *s, AVPacket *pkt)

{

    LATMContext *ctx = s->priv_data;

    AVIOContext *pb = s->pb;

    PutBitContext bs;

    int i, len;

    uint8_t loas_header[] = "\x56\xe0\x00";



    if (s->streams[0]->codecpar->codec_id == AV_CODEC_ID_AAC_LATM)

        return ff_raw_write_packet(s, pkt);



    if (!s->streams[0]->codecpar->extradata) {

        if(pkt->size > 2 && pkt->data[0] == 0x56 && (pkt->data[1] >> 4) == 0xe &&

            (AV_RB16(pkt->data + 1) & 0x1FFF) + 3 == pkt->size)

            return ff_raw_write_packet(s, pkt);

        else

            return AVERROR_INVALIDDATA;

    }



    if (pkt->size > 0x1fff)

        goto too_large;



    init_put_bits(&bs, ctx->buffer, pkt->size+1024+MAX_EXTRADATA_SIZE);



    latm_write_frame_header(s, &bs);



    /* PayloadLengthInfo() */

    for (i = 0; i <= pkt->size-255; i+=255)

        put_bits(&bs, 8, 255);



    put_bits(&bs, 8, pkt->size-i);



    /* The LATM payload is written unaligned */



    /* PayloadMux() */

    if (pkt->size && (pkt->data[0] & 0xe1) == 0x81) {

        // Convert byte-aligned DSE to non-aligned.

        // Due to the input format encoding we know that

        // it is naturally byte-aligned in the input stream,

        // so there are no padding bits to account for.

        // To avoid having to add padding bits and rearrange

        // the whole stream we just remove the byte-align flag.

        // This allows us to remux our FATE AAC samples into latm

        // files that are still playable with minimal effort.

        put_bits(&bs, 8, pkt->data[0] & 0xfe);

        avpriv_copy_bits(&bs, pkt->data + 1, 8*pkt->size - 8);

    } else

        avpriv_copy_bits(&bs, pkt->data, 8*pkt->size);



    avpriv_align_put_bits(&bs);

    flush_put_bits(&bs);



    len = put_bits_count(&bs) >> 3;



    if (len > 0x1fff)

        goto too_large;



    loas_header[1] |= (len >> 8) & 0x1f;

    loas_header[2] |= len & 0xff;



    avio_write(pb, loas_header, 3);

    avio_write(pb, ctx->buffer, len);



    return 0;



too_large:

    av_log(s, AV_LOG_ERROR, "LATM packet size larger than maximum size 0x1fff\n");

    return AVERROR_INVALIDDATA;

}

static void end_ebml_master_crc32(AVIOContext *pb, AVIOContext **dyn_cp, MatroskaMuxContext *mkv,

                                  ebml_master master)

{

    uint8_t *buf, crc[4];

    int size;



    if (pb->seekable) {

        size = avio_close_dyn_buf(*dyn_cp, &buf);

        if (mkv->write_crc && mkv->mode != MODE_WEBM) {

            AV_WL32(crc, av_crc(av_crc_get_table(AV_CRC_32_IEEE_LE), UINT32_MAX, buf, size) ^ UINT32_MAX);

            put_ebml_binary(pb, EBML_ID_CRC32, crc, sizeof(crc));

        }

        avio_write(pb, buf, size);

        end_ebml_master(pb, master);

    } else {

        end_ebml_master(*dyn_cp, master);

        size = avio_close_dyn_buf(*dyn_cp, &buf);

        avio_write(pb, buf, size);

    }

    av_free(buf);

    *dyn_cp = NULL;

}

void ff_h264_direct_ref_list_init(const H264Context *const h, H264SliceContext *sl)

{

    H264Ref *const ref1 = &sl->ref_list[1][0];

    H264Picture *const cur = h->cur_pic_ptr;

    int list, j, field;

    int sidx     = (h->picture_structure & 1) ^ 1;

    int ref1sidx = (ref1->reference      & 1) ^ 1;



    for (list = 0; list < sl->list_count; list++) {

        cur->ref_count[sidx][list] = sl->ref_count[list];

        for (j = 0; j < sl->ref_count[list]; j++)

            cur->ref_poc[sidx][list][j] = 4 * sl->ref_list[list][j].parent->frame_num +

                                          (sl->ref_list[list][j].reference & 3);

    }



    if (h->picture_structure == PICT_FRAME) {

        memcpy(cur->ref_count[1], cur->ref_count[0], sizeof(cur->ref_count[0]));

        memcpy(cur->ref_poc[1],   cur->ref_poc[0],   sizeof(cur->ref_poc[0]));

    }



    cur->mbaff = FRAME_MBAFF(h);



    sl->col_fieldoff = 0;



    if (sl->list_count != 2 || !sl->ref_count[1])

        return;



    if (h->picture_structure == PICT_FRAME) {

        int cur_poc  = h->cur_pic_ptr->poc;

        int *col_poc = sl->ref_list[1][0].parent->field_poc;

        if (col_poc[0] == INT_MAX && col_poc[1] == INT_MAX) {

            av_log(h->avctx, AV_LOG_ERROR, "co located POCs unavailable\n");

            sl->col_parity = 1;

        } else

        sl->col_parity = (FFABS(col_poc[0] - cur_poc) >=

                          FFABS(col_poc[1] - cur_poc));

        ref1sidx =

        sidx     = sl->col_parity;

    // FL -> FL & differ parity

    } else if (!(h->picture_structure & sl->ref_list[1][0].reference) &&

               !sl->ref_list[1][0].parent->mbaff) {

        sl->col_fieldoff = 2 * sl->ref_list[1][0].reference - 3;

    }



    if (sl->slice_type_nos != AV_PICTURE_TYPE_B || sl->direct_spatial_mv_pred)

        return;



    for (list = 0; list < 2; list++) {

        fill_colmap(h, sl, sl->map_col_to_list0, list, sidx, ref1sidx, 0);

        if (FRAME_MBAFF(h))

            for (field = 0; field < 2; field++)

                fill_colmap(h, sl, sl->map_col_to_list0_field[field], list, field,

                            field, 1);

    }

}

static av_cold int xvid_encode_init(AVCodecContext *avctx)

{

    int xerr, i;

    int xvid_flags = avctx->flags;

    struct xvid_context *x = avctx->priv_data;

    uint16_t *intra, *inter;

    int fd;



    xvid_plugin_single_t single         = { 0 };

    struct xvid_ff_pass1 rc2pass1       = { 0 };

    xvid_plugin_2pass2_t rc2pass2       = { 0 };

    xvid_plugin_lumimasking_t masking_l = { 0 }; /* For lumi masking */

    xvid_plugin_lumimasking_t masking_v = { 0 }; /* For variance AQ */

    xvid_plugin_ssim_t ssim             = { 0 };

    xvid_gbl_init_t xvid_gbl_init       = { 0 };

    xvid_enc_create_t xvid_enc_create   = { 0 };

    xvid_enc_plugin_t plugins[7];



    /* Bring in VOP flags from avconv command-line */

    x->vop_flags = XVID_VOP_HALFPEL; /* Bare minimum quality */

    if (xvid_flags & CODEC_FLAG_4MV)

        x->vop_flags |= XVID_VOP_INTER4V; /* Level 3 */

    if (avctx->trellis)

        x->vop_flags |= XVID_VOP_TRELLISQUANT; /* Level 5 */

    if (xvid_flags & CODEC_FLAG_AC_PRED)

        x->vop_flags |= XVID_VOP_HQACPRED; /* Level 6 */

    if (xvid_flags & CODEC_FLAG_GRAY)

        x->vop_flags |= XVID_VOP_GREYSCALE;



    /* Decide which ME quality setting to use */

    x->me_flags = 0;

    switch (avctx->me_method) {

    case ME_FULL:   /* Quality 6 */

        x->me_flags |= XVID_ME_EXTSEARCH16 |

                       XVID_ME_EXTSEARCH8;



    case ME_EPZS:   /* Quality 4 */

        x->me_flags |= XVID_ME_ADVANCEDDIAMOND8 |

                       XVID_ME_HALFPELREFINE8   |

                       XVID_ME_CHROMA_PVOP      |

                       XVID_ME_CHROMA_BVOP;



    case ME_LOG:    /* Quality 2 */

    case ME_PHODS:

    case ME_X1:

        x->me_flags |= XVID_ME_ADVANCEDDIAMOND16 |

                       XVID_ME_HALFPELREFINE16;



    case ME_ZERO:   /* Quality 0 */

    default:

        break;

    }



    /* Decide how we should decide blocks */

    switch (avctx->mb_decision) {

    case 2:

        x->vop_flags |=  XVID_VOP_MODEDECISION_RD;

        x->me_flags  |=  XVID_ME_HALFPELREFINE8_RD    |

                         XVID_ME_QUARTERPELREFINE8_RD |

                         XVID_ME_EXTSEARCH_RD         |

                         XVID_ME_CHECKPREDICTION_RD;

    case 1:

        if (!(x->vop_flags & XVID_VOP_MODEDECISION_RD))

            x->vop_flags |= XVID_VOP_FAST_MODEDECISION_RD;

        x->me_flags |= XVID_ME_HALFPELREFINE16_RD |

                       XVID_ME_QUARTERPELREFINE16_RD;

    default:

        break;

    }



    /* Bring in VOL flags from avconv command-line */

#if FF_API_GMC

    if (avctx->flags & CODEC_FLAG_GMC)

        x->gmc = 1;

#endif



    x->vol_flags = 0;

    if (x->gmc) {

        x->vol_flags |= XVID_VOL_GMC;

        x->me_flags  |= XVID_ME_GME_REFINE;

    }

    if (xvid_flags & CODEC_FLAG_QPEL) {

        x->vol_flags |= XVID_VOL_QUARTERPEL;

        x->me_flags  |= XVID_ME_QUARTERPELREFINE16;

        if (x->vop_flags & XVID_VOP_INTER4V)

            x->me_flags |= XVID_ME_QUARTERPELREFINE8;

    }



    xvid_gbl_init.version   = XVID_VERSION;

    xvid_gbl_init.debug     = 0;

    xvid_gbl_init.cpu_flags = 0;



    /* Initialize */

    xvid_global(NULL, XVID_GBL_INIT, &xvid_gbl_init, NULL);



    /* Create the encoder reference */

    xvid_enc_create.version = XVID_VERSION;



    /* Store the desired frame size */

    xvid_enc_create.width  =

    x->xsize               = avctx->width;

    xvid_enc_create.height =

    x->ysize               = avctx->height;



    /* Xvid can determine the proper profile to use */

    /* xvid_enc_create.profile = XVID_PROFILE_S_L3; */



    /* We don't use zones */

    xvid_enc_create.zones     = NULL;

    xvid_enc_create.num_zones = 0;



    xvid_enc_create.num_threads = avctx->thread_count;



    xvid_enc_create.plugins     = plugins;

    xvid_enc_create.num_plugins = 0;



    /* Initialize Buffers */

    x->twopassbuffer     = NULL;

    x->old_twopassbuffer = NULL;

    x->twopassfile       = NULL;



    if (xvid_flags & CODEC_FLAG_PASS1) {

        rc2pass1.version     = XVID_VERSION;

        rc2pass1.context     = x;

        x->twopassbuffer     = av_malloc(BUFFER_SIZE);

        x->old_twopassbuffer = av_malloc(BUFFER_SIZE);

        if (!x->twopassbuffer || !x->old_twopassbuffer) {

            av_log(avctx, AV_LOG_ERROR,

                   "Xvid: Cannot allocate 2-pass log buffers\n");

            return AVERROR(ENOMEM);

        }

        x->twopassbuffer[0]     =

        x->old_twopassbuffer[0] = 0;



        plugins[xvid_enc_create.num_plugins].func  = xvid_ff_2pass;

        plugins[xvid_enc_create.num_plugins].param = &rc2pass1;

        xvid_enc_create.num_plugins++;

    } else if (xvid_flags & CODEC_FLAG_PASS2) {

        rc2pass2.version = XVID_VERSION;

        rc2pass2.bitrate = avctx->bit_rate;



        fd = ff_tempfile("xvidff.", &x->twopassfile);

        if (fd < 0) {

            av_log(avctx, AV_LOG_ERROR, "Xvid: Cannot write 2-pass pipe\n");

            return fd;

        }



        if (!avctx->stats_in) {

            av_log(avctx, AV_LOG_ERROR,

                   "Xvid: No 2-pass information loaded for second pass\n");

            return AVERROR_INVALIDDATA;

        }



        if (strlen(avctx->stats_in) >

            write(fd, avctx->stats_in, strlen(avctx->stats_in))) {

            close(fd);

            av_log(avctx, AV_LOG_ERROR, "Xvid: Cannot write to 2-pass pipe\n");

            return AVERROR(EIO);

        }



        close(fd);

        rc2pass2.filename                          = x->twopassfile;

        plugins[xvid_enc_create.num_plugins].func  = xvid_plugin_2pass2;

        plugins[xvid_enc_create.num_plugins].param = &rc2pass2;

        xvid_enc_create.num_plugins++;

    } else if (!(xvid_flags & CODEC_FLAG_QSCALE)) {

        /* Single Pass Bitrate Control! */

        single.version = XVID_VERSION;

        single.bitrate = avctx->bit_rate;



        plugins[xvid_enc_create.num_plugins].func  = xvid_plugin_single;

        plugins[xvid_enc_create.num_plugins].param = &single;

        xvid_enc_create.num_plugins++;

    }



    if (avctx->lumi_masking != 0.0)

        x->lumi_aq = 1;



    if (x->lumi_aq && x->variance_aq) {

        x->variance_aq = 0;

        av_log(avctx, AV_LOG_WARNING,

               "variance_aq is ignored when lumi_aq is set.\n");

    }



    /* Luminance Masking */

    if (x->lumi_aq) {

        masking_l.method                          = 0;

        plugins[xvid_enc_create.num_plugins].func = xvid_plugin_lumimasking;



        /* The old behavior is that when avctx->lumi_masking is specified,

         * plugins[...].param = NULL. Trying to keep the old behavior here. */

        plugins[xvid_enc_create.num_plugins].param =

            avctx->lumi_masking ? NULL : &masking_l;

        xvid_enc_create.num_plugins++;

    }



    /* Variance AQ */

    if (x->variance_aq) {

        masking_v.method                           = 1;

        plugins[xvid_enc_create.num_plugins].func  = xvid_plugin_lumimasking;

        plugins[xvid_enc_create.num_plugins].param = &masking_v;

        xvid_enc_create.num_plugins++;

    }



    /* SSIM */

    if (x->ssim) {

        plugins[xvid_enc_create.num_plugins].func  = xvid_plugin_ssim;

        ssim.b_printstat                           = x->ssim == 2;

        ssim.acc                                   = x->ssim_acc;

        ssim.cpu_flags                             = xvid_gbl_init.cpu_flags;

        ssim.b_visualize                           = 0;

        plugins[xvid_enc_create.num_plugins].param = &ssim;

        xvid_enc_create.num_plugins++;

    }



    /* Frame Rate and Key Frames */

    xvid_correct_framerate(avctx);

    xvid_enc_create.fincr = avctx->time_base.num;

    xvid_enc_create.fbase = avctx->time_base.den;

    if (avctx->gop_size > 0)

        xvid_enc_create.max_key_interval = avctx->gop_size;

    else

        xvid_enc_create.max_key_interval = 240; /* Xvid's best default */



    /* Quants */

    if (xvid_flags & CODEC_FLAG_QSCALE)

        x->qscale = 1;

    else

        x->qscale = 0;



    xvid_enc_create.min_quant[0] = avctx->qmin;

    xvid_enc_create.min_quant[1] = avctx->qmin;

    xvid_enc_create.min_quant[2] = avctx->qmin;

    xvid_enc_create.max_quant[0] = avctx->qmax;

    xvid_enc_create.max_quant[1] = avctx->qmax;

    xvid_enc_create.max_quant[2] = avctx->qmax;



    /* Quant Matrices */

    x->intra_matrix =

    x->inter_matrix = NULL;

    if (avctx->mpeg_quant)

        x->vol_flags |= XVID_VOL_MPEGQUANT;

    if ((avctx->intra_matrix || avctx->inter_matrix)) {

        x->vol_flags |= XVID_VOL_MPEGQUANT;



        if (avctx->intra_matrix) {

            intra           = avctx->intra_matrix;

            x->intra_matrix = av_malloc(sizeof(unsigned char) * 64);

            if (!x->intra_matrix)

                return AVERROR(ENOMEM);

        } else

            intra = NULL;

        if (avctx->inter_matrix) {

            inter           = avctx->inter_matrix;

            x->inter_matrix = av_malloc(sizeof(unsigned char) * 64);

            if (!x->inter_matrix)

                return AVERROR(ENOMEM);

        } else

            inter = NULL;



        for (i = 0; i < 64; i++) {

            if (intra)

                x->intra_matrix[i] = (unsigned char) intra[i];

            if (inter)

                x->inter_matrix[i] = (unsigned char) inter[i];

        }

    }



    /* Misc Settings */

    xvid_enc_create.frame_drop_ratio = 0;

    xvid_enc_create.global           = 0;

    if (xvid_flags & CODEC_FLAG_CLOSED_GOP)

        xvid_enc_create.global |= XVID_GLOBAL_CLOSED_GOP;



    /* Determines which codec mode we are operating in */

    avctx->extradata      = NULL;

    avctx->extradata_size = 0;

    if (xvid_flags & CODEC_FLAG_GLOBAL_HEADER) {

        /* In this case, we are claiming to be MPEG4 */

        x->quicktime_format = 1;

        avctx->codec_id     = AV_CODEC_ID_MPEG4;

    } else {

        /* We are claiming to be Xvid */

        x->quicktime_format = 0;

        if (!avctx->codec_tag)

            avctx->codec_tag = AV_RL32("xvid");

    }



    /* Bframes */

    xvid_enc_create.max_bframes   = avctx->max_b_frames;

    xvid_enc_create.bquant_offset = 100 * avctx->b_quant_offset;

    xvid_enc_create.bquant_ratio  = 100 * avctx->b_quant_factor;

    if (avctx->max_b_frames > 0 && !x->quicktime_format)

        xvid_enc_create.global |= XVID_GLOBAL_PACKED;



    /* Create encoder context */

    xerr = xvid_encore(NULL, XVID_ENC_CREATE, &xvid_enc_create, NULL);

    if (xerr) {

        av_log(avctx, AV_LOG_ERROR, "Xvid: Could not create encoder reference\n");

        return -1;

    }



    x->encoder_handle  = xvid_enc_create.handle;

    avctx->coded_frame = av_frame_alloc();

    if (!avctx->coded_frame)

        return AVERROR(ENOMEM);



    return 0;

}

static void do_audio_out(AVFormatContext *s,

                         AVOutputStream *ost,

                         AVInputStream *ist,

                         unsigned char *buf, int size)

{

    uint8_t *buftmp;

    static uint8_t *audio_buf = NULL;

    static uint8_t *audio_out = NULL;

    const int audio_out_size= 4*MAX_AUDIO_PACKET_SIZE;



    int size_out, frame_bytes, ret;

    AVCodecContext *enc= ost->st->codec;

    AVCodecContext *dec= ist->st->codec;



    /* SC: dynamic allocation of buffers */

    if (!audio_buf)

        audio_buf = av_malloc(2*MAX_AUDIO_PACKET_SIZE);

    if (!audio_out)

        audio_out = av_malloc(audio_out_size);

    if (!audio_buf || !audio_out)

        return;               /* Should signal an error ! */



    if (enc->channels != dec->channels)

        ost->audio_resample = 1;



    if (ost->audio_resample && !ost->resample) {

        ost->resample = audio_resample_init(enc->channels,    dec->channels,

                                            enc->sample_rate, dec->sample_rate);

        if (!ost->resample) {

            fprintf(stderr, "Can not resample %d channels @ %d Hz to %d channels @ %d Hz\n",

                    dec->channels, dec->sample_rate,

                    enc->channels, enc->sample_rate);

            av_exit(1);

        }

    }



    if(audio_sync_method){

        double delta = get_sync_ipts(ost) * enc->sample_rate - ost->sync_opts

                - av_fifo_size(&ost->fifo)/(ost->st->codec->channels * 2);

        double idelta= delta*ist->st->codec->sample_rate / enc->sample_rate;

        int byte_delta= ((int)idelta)*2*ist->st->codec->channels;



        //FIXME resample delay

        if(fabs(delta) > 50){

            if(ist->is_start || fabs(delta) > audio_drift_threshold*enc->sample_rate){

                if(byte_delta < 0){

                    byte_delta= FFMAX(byte_delta, -size);

                    size += byte_delta;

                    buf  -= byte_delta;

                    if(verbose > 2)

                        fprintf(stderr, "discarding %d audio samples\n", (int)-delta);

                    if(!size)

                        return;

                    ist->is_start=0;

                }else{

                    static uint8_t *input_tmp= NULL;

                    input_tmp= av_realloc(input_tmp, byte_delta + size);



                    if(byte_delta + size <= MAX_AUDIO_PACKET_SIZE)

                        ist->is_start=0;

                    else

                        byte_delta= MAX_AUDIO_PACKET_SIZE - size;



                    memset(input_tmp, 0, byte_delta);

                    memcpy(input_tmp + byte_delta, buf, size);

                    buf= input_tmp;

                    size += byte_delta;

                    if(verbose > 2)

                        fprintf(stderr, "adding %d audio samples of silence\n", (int)delta);

                }

            }else if(audio_sync_method>1){

                int comp= av_clip(delta, -audio_sync_method, audio_sync_method);

                assert(ost->audio_resample);

                if(verbose > 2)

                    fprintf(stderr, "compensating audio timestamp drift:%f compensation:%d in:%d\n", delta, comp, enc->sample_rate);

//                fprintf(stderr, "drift:%f len:%d opts:%"PRId64" ipts:%"PRId64" fifo:%d\n", delta, -1, ost->sync_opts, (int64_t)(get_sync_ipts(ost) * enc->sample_rate), av_fifo_size(&ost->fifo)/(ost->st->codec->channels * 2));

                av_resample_compensate(*(struct AVResampleContext**)ost->resample, comp, enc->sample_rate);

            }

        }

    }else

        ost->sync_opts= lrintf(get_sync_ipts(ost) * enc->sample_rate)

                        - av_fifo_size(&ost->fifo)/(ost->st->codec->channels * 2); //FIXME wrong



    if (ost->audio_resample) {

        buftmp = audio_buf;

        size_out = audio_resample(ost->resample,

                                  (short *)buftmp, (short *)buf,

                                  size / (ist->st->codec->channels * 2));

        size_out = size_out * enc->channels * 2;

    } else {

        buftmp = buf;

        size_out = size;

    }



    /* now encode as many frames as possible */

    if (enc->frame_size > 1) {

        /* output resampled raw samples */

        av_fifo_realloc(&ost->fifo, av_fifo_size(&ost->fifo) + size_out + 1);

        av_fifo_write(&ost->fifo, buftmp, size_out);



        frame_bytes = enc->frame_size * 2 * enc->channels;



        while (av_fifo_read(&ost->fifo, audio_buf, frame_bytes) == 0) {

            AVPacket pkt;

            av_init_packet(&pkt);



            //FIXME pass ost->sync_opts as AVFrame.pts in avcodec_encode_audio()



            ret = avcodec_encode_audio(enc, audio_out, audio_out_size,

                                       (short *)audio_buf);

            audio_size += ret;

            pkt.stream_index= ost->index;

            pkt.data= audio_out;

            pkt.size= ret;

            if(enc->coded_frame && enc->coded_frame->pts != AV_NOPTS_VALUE)

                pkt.pts= av_rescale_q(enc->coded_frame->pts, enc->time_base, ost->st->time_base);

            pkt.flags |= PKT_FLAG_KEY;

            write_frame(s, &pkt, ost->st->codec, bitstream_filters[ost->file_index][pkt.stream_index]);



            ost->sync_opts += enc->frame_size;

        }

    } else {

        AVPacket pkt;

        av_init_packet(&pkt);



        ost->sync_opts += size_out / (2 * enc->channels);



        /* output a pcm frame */

        /* XXX: change encoding codec API to avoid this ? */

        switch(enc->codec->id) {

        case CODEC_ID_PCM_S32LE:

        case CODEC_ID_PCM_S32BE:

        case CODEC_ID_PCM_U32LE:

        case CODEC_ID_PCM_U32BE:

            size_out = size_out << 1;

            break;

        case CODEC_ID_PCM_S24LE:

        case CODEC_ID_PCM_S24BE:

        case CODEC_ID_PCM_U24LE:

        case CODEC_ID_PCM_U24BE:

        case CODEC_ID_PCM_S24DAUD:

            size_out = size_out / 2 * 3;

            break;

        case CODEC_ID_PCM_S16LE:

        case CODEC_ID_PCM_S16BE:

        case CODEC_ID_PCM_U16LE:

        case CODEC_ID_PCM_U16BE:

            break;

        default:

            size_out = size_out >> 1;

            break;

        }

        //FIXME pass ost->sync_opts as AVFrame.pts in avcodec_encode_audio()

        ret = avcodec_encode_audio(enc, audio_out, size_out,

                                   (short *)buftmp);

        audio_size += ret;

        pkt.stream_index= ost->index;

        pkt.data= audio_out;

        pkt.size= ret;

        if(enc->coded_frame && enc->coded_frame->pts != AV_NOPTS_VALUE)

            pkt.pts= av_rescale_q(enc->coded_frame->pts, enc->time_base, ost->st->time_base);

        pkt.flags |= PKT_FLAG_KEY;

        write_frame(s, &pkt, ost->st->codec, bitstream_filters[ost->file_index][pkt.stream_index]);

    }

}

static int mace3_decode_frame(AVCodecContext *avctx,

                              void *data, int *data_size,

                              const uint8_t *buf, int buf_size)

{

    int16_t *samples = data;

    MACEContext *ctx = avctx->priv_data;

    int i, j, k;



    for(i = 0; i < avctx->channels; i++) {

        int16_t *output = samples + i;



        for (j=0; j < buf_size / 2 / avctx->channels; j++)

            for (k=0; k < 2; k++) {

                uint8_t pkt = buf[i*2 + j*2*avctx->channels + k];

                chomp3(&ctx->chd[i], output, pkt       &7, MACEtab1, MACEtab2,

                       8, avctx->channels);

                output += avctx->channels;

                chomp3(&ctx->chd[i], output,(pkt >> 3) &3, MACEtab3, MACEtab4,

                       4, avctx->channels);

                output += avctx->channels;

                chomp3(&ctx->chd[i], output, pkt >> 5    , MACEtab1, MACEtab2,

                       8, avctx->channels);

                output += avctx->channels;

            }

    }



    *data_size = 2 * 3 * buf_size;



    return buf_size;

}

static int nut_read_header(AVFormatContext *s, AVFormatParameters *ap)

{

    NUTContext *nut = s->priv_data;

    ByteIOContext *bc = &s->pb;

    int64_t pos;

    int inited_stream_count;



    nut->avf= s;



    /* main header */

    pos=0;

    for(;;){

        pos= find_startcode(bc, MAIN_STARTCODE, pos)+1;

        if (pos<0){

            av_log(s, AV_LOG_ERROR, "no main startcode found\n");

            return -1;

        }

        if(decode_main_header(nut) >= 0)

            break;

    }





    s->bit_rate = 0;



    nut->stream = av_malloc(sizeof(StreamContext)*nut->stream_count);



    /* stream headers */

    pos=0;

    for(inited_stream_count=0; inited_stream_count < nut->stream_count;){

        pos= find_startcode(bc, STREAM_STARTCODE, pos)+1;

        if (pos<0){

            av_log(s, AV_LOG_ERROR, "not all stream headers found\n");

            return -1;

        }

        if(decode_stream_header(nut) >= 0)

            inited_stream_count++;

    }



    /* info headers */

    pos=0;

    for(;;){

        uint64_t startcode= find_any_startcode(bc, pos);

        pos= url_ftell(bc);



        if(startcode==0){

            av_log(s, AV_LOG_ERROR, "EOF before video frames\n");

            return -1;

        }else if(startcode == KEYFRAME_STARTCODE){

            nut->next_startcode= startcode;

            break;

        }else if(startcode != INFO_STARTCODE){

            continue;

        }



        decode_info_header(nut);

    }



    return 0;

}

int av_interleaved_write_frame(AVFormatContext *s, AVPacket *pkt)

{

    int ret, flush = 0;



    ret = check_packet(s, pkt);

    if (ret < 0)

        goto fail;



    if (pkt) {

        AVStream *st = s->streams[pkt->stream_index];



        //FIXME/XXX/HACK drop zero sized packets

        if (st->codec->codec_type == AVMEDIA_TYPE_AUDIO && pkt->size == 0) {

            ret = 0;

            goto fail;

        }



        av_dlog(s, "av_interleaved_write_frame size:%d dts:%" PRId64 " pts:%" PRId64 "\n",

                pkt->size, pkt->dts, pkt->pts);

        if ((ret = compute_pkt_fields2(s, st, pkt)) < 0 && !(s->oformat->flags & AVFMT_NOTIMESTAMPS))

            goto fail;



        if (pkt->dts == AV_NOPTS_VALUE && !(s->oformat->flags & AVFMT_NOTIMESTAMPS)) {

            ret = AVERROR(EINVAL);

            goto fail;

        }

    } else {

        av_dlog(s, "av_interleaved_write_frame FLUSH\n");

        flush = 1;

    }



    for (;; ) {

        AVPacket opkt;

        int ret = interleave_packet(s, &opkt, pkt, flush);

        if (pkt) {

            memset(pkt, 0, sizeof(*pkt));

            av_init_packet(pkt);

            pkt = NULL;

        }

        if (ret <= 0) //FIXME cleanup needed for ret<0 ?

            return ret;



        ret = write_packet(s, &opkt);

        if (ret >= 0)

            s->streams[opkt.stream_index]->nb_frames++;



        av_free_packet(&opkt);



        if (ret < 0)

            return ret;

    }

fail:

    av_packet_unref(pkt);

    return ret;

}

static av_noinline void FUNC(hl_decode_mb_444)(H264Context *h, H264SliceContext *sl)

{

    const int mb_x    = h->mb_x;

    const int mb_y    = h->mb_y;

    const int mb_xy   = h->mb_xy;

    const int mb_type = h->cur_pic.mb_type[mb_xy];

    uint8_t *dest[3];

    int linesize;

    int i, j, p;

    int *block_offset = &h->block_offset[0];

    const int transform_bypass = !SIMPLE && (sl->qscale == 0 && h->sps.transform_bypass);

    const int plane_count      = (SIMPLE || !CONFIG_GRAY || !(h->flags & CODEC_FLAG_GRAY)) ? 3 : 1;



    for (p = 0; p < plane_count; p++) {

        dest[p] = h->cur_pic.f.data[p] +

                  ((mb_x << PIXEL_SHIFT) + mb_y * h->linesize) * 16;

        h->vdsp.prefetch(dest[p] + (h->mb_x & 3) * 4 * h->linesize + (64 << PIXEL_SHIFT),

                         h->linesize, 4);

    }



    h->list_counts[mb_xy] = sl->list_count;



    if (!SIMPLE && MB_FIELD(h)) {

        linesize     = sl->mb_linesize = sl->mb_uvlinesize = h->linesize * 2;

        block_offset = &h->block_offset[48];

        if (mb_y & 1) // FIXME move out of this function?

            for (p = 0; p < 3; p++)

                dest[p] -= h->linesize * 15;

        if (FRAME_MBAFF(h)) {

            int list;

            for (list = 0; list < sl->list_count; list++) {

                if (!USES_LIST(mb_type, list))

                    continue;

                if (IS_16X16(mb_type)) {

                    int8_t *ref = &sl->ref_cache[list][scan8[0]];

                    fill_rectangle(ref, 4, 4, 8, (16 + *ref) ^ (h->mb_y & 1), 1);

                } else {

                    for (i = 0; i < 16; i += 4) {

                        int ref = sl->ref_cache[list][scan8[i]];

                        if (ref >= 0)

                            fill_rectangle(&sl->ref_cache[list][scan8[i]], 2, 2,

                                           8, (16 + ref) ^ (h->mb_y & 1), 1);

                    }

                }

            }

        }

    } else {

        linesize = sl->mb_linesize = sl->mb_uvlinesize = h->linesize;

    }



    if (!SIMPLE && IS_INTRA_PCM(mb_type)) {

        if (PIXEL_SHIFT) {

            const int bit_depth = h->sps.bit_depth_luma;

            GetBitContext gb;

            init_get_bits(&gb, sl->intra_pcm_ptr, 768 * bit_depth);



            for (p = 0; p < plane_count; p++)

                for (i = 0; i < 16; i++) {

                    uint16_t *tmp = (uint16_t *)(dest[p] + i * linesize);

                    for (j = 0; j < 16; j++)

                        tmp[j] = get_bits(&gb, bit_depth);

                }

        } else {

            for (p = 0; p < plane_count; p++)

                for (i = 0; i < 16; i++)

                    memcpy(dest[p] + i * linesize,

                           sl->intra_pcm_ptr + p * 256 + i * 16, 16);

        }

    } else {

        if (IS_INTRA(mb_type)) {

            if (h->deblocking_filter)

                xchg_mb_border(h, sl, dest[0], dest[1], dest[2], linesize,

                               linesize, 1, 1, SIMPLE, PIXEL_SHIFT);



            for (p = 0; p < plane_count; p++)

                hl_decode_mb_predict_luma(h, sl, mb_type, 1, SIMPLE,

                                          transform_bypass, PIXEL_SHIFT,

                                          block_offset, linesize, dest[p], p);



            if (h->deblocking_filter)

                xchg_mb_border(h, sl, dest[0], dest[1], dest[2], linesize,

                               linesize, 0, 1, SIMPLE, PIXEL_SHIFT);

        } else {

            FUNC(hl_motion_444)(h, sl, dest[0], dest[1], dest[2],

                      h->qpel_put, h->h264chroma.put_h264_chroma_pixels_tab,

                      h->qpel_avg, h->h264chroma.avg_h264_chroma_pixels_tab,

                      h->h264dsp.weight_h264_pixels_tab,

                      h->h264dsp.biweight_h264_pixels_tab);

        }



        for (p = 0; p < plane_count; p++)

            hl_decode_mb_idct_luma(h, sl, mb_type, 1, SIMPLE, transform_bypass,

                                   PIXEL_SHIFT, block_offset, linesize,

                                   dest[p], p);

    }

}

static int synthfilt_build_sb_samples(QDM2Context *q, GetBitContext *gb,

                                       int length, int sb_min, int sb_max)

{

    int sb, j, k, n, ch, run, channels;

    int joined_stereo, zero_encoding;

    int type34_first;

    float type34_div = 0;

    float type34_predictor;

    float samples[10];

    int sign_bits[16];



    if (length == 0) {

        // If no data use noise

        for (sb=sb_min; sb < sb_max; sb++)

            build_sb_samples_from_noise (q, sb);



        return 0;

    }



    for (sb = sb_min; sb < sb_max; sb++) {

        channels = q->nb_channels;



        if (q->nb_channels <= 1 || sb < 12)

            joined_stereo = 0;

        else if (sb >= 24)

            joined_stereo = 1;

        else

            joined_stereo = (get_bits_left(gb) >= 1) ? get_bits1 (gb) : 0;



        if (joined_stereo) {

            if (get_bits_left(gb) >= 16)

                for (j = 0; j < 16; j++)

                    sign_bits[j] = get_bits1 (gb);



            for (j = 0; j < 64; j++)

                if (q->coding_method[1][sb][j] > q->coding_method[0][sb][j])

                    q->coding_method[0][sb][j] = q->coding_method[1][sb][j];



            if (fix_coding_method_array(sb, q->nb_channels,

                                            q->coding_method)) {

                av_log(NULL, AV_LOG_ERROR, "coding method invalid\n");

                build_sb_samples_from_noise(q, sb);

                continue;

            }

            channels = 1;

        }



        for (ch = 0; ch < channels; ch++) {

            FIX_NOISE_IDX(q->noise_idx);

            zero_encoding = (get_bits_left(gb) >= 1) ? get_bits1(gb) : 0;

            type34_predictor = 0.0;

            type34_first = 1;



            for (j = 0; j < 128; ) {

                switch (q->coding_method[ch][sb][j / 2]) {

                    case 8:

                        if (get_bits_left(gb) >= 10) {

                            if (zero_encoding) {

                                for (k = 0; k < 5; k++) {

                                    if ((j + 2 * k) >= 128)

                                        break;

                                    samples[2 * k] = get_bits1(gb) ? dequant_1bit[joined_stereo][2 * get_bits1(gb)] : 0;

                                }

                            } else {

                                n = get_bits(gb, 8);

                                if (n >= 243) {

                                    av_log(NULL, AV_LOG_ERROR, "Invalid 8bit codeword\n");

                                    return AVERROR_INVALIDDATA;

                                }



                                for (k = 0; k < 5; k++)

                                    samples[2 * k] = dequant_1bit[joined_stereo][random_dequant_index[n][k]];

                            }

                            for (k = 0; k < 5; k++)

                                samples[2 * k + 1] = SB_DITHERING_NOISE(sb,q->noise_idx);

                        } else {

                            for (k = 0; k < 10; k++)

                                samples[k] = SB_DITHERING_NOISE(sb,q->noise_idx);

                        }

                        run = 10;

                        break;



                    case 10:

                        if (get_bits_left(gb) >= 1) {

                            float f = 0.81;



                            if (get_bits1(gb))

                                f = -f;

                            f -= noise_samples[((sb + 1) * (j +5 * ch + 1)) & 127] * 9.0 / 40.0;

                            samples[0] = f;

                        } else {

                            samples[0] = SB_DITHERING_NOISE(sb,q->noise_idx);

                        }

                        run = 1;

                        break;



                    case 16:

                        if (get_bits_left(gb) >= 10) {

                            if (zero_encoding) {

                                for (k = 0; k < 5; k++) {

                                    if ((j + k) >= 128)

                                        break;

                                    samples[k] = (get_bits1(gb) == 0) ? 0 : dequant_1bit[joined_stereo][2 * get_bits1(gb)];

                                }

                            } else {

                                n = get_bits (gb, 8);

                                if (n >= 243) {

                                    av_log(NULL, AV_LOG_ERROR, "Invalid 8bit codeword\n");

                                    return AVERROR_INVALIDDATA;

                                }



                                for (k = 0; k < 5; k++)

                                    samples[k] = dequant_1bit[joined_stereo][random_dequant_index[n][k]];

                            }

                        } else {

                            for (k = 0; k < 5; k++)

                                samples[k] = SB_DITHERING_NOISE(sb,q->noise_idx);

                        }

                        run = 5;

                        break;



                    case 24:

                        if (get_bits_left(gb) >= 7) {

                            n = get_bits(gb, 7);

                            if (n >= 125) {

                                av_log(NULL, AV_LOG_ERROR, "Invalid 7bit codeword\n");

                                return AVERROR_INVALIDDATA;

                            }



                            for (k = 0; k < 3; k++)

                                samples[k] = (random_dequant_type24[n][k] - 2.0) * 0.5;

                        } else {

                            for (k = 0; k < 3; k++)

                                samples[k] = SB_DITHERING_NOISE(sb,q->noise_idx);

                        }

                        run = 3;

                        break;



                    case 30:

                        if (get_bits_left(gb) >= 4) {

                            unsigned index = qdm2_get_vlc(gb, &vlc_tab_type30, 0, 1);

                            if (index >= FF_ARRAY_ELEMS(type30_dequant)) {

                                av_log(NULL, AV_LOG_ERROR, "index %d out of type30_dequant array\n", index);

                                return AVERROR_INVALIDDATA;

                            }

                            samples[0] = type30_dequant[index];

                        } else

                            samples[0] = SB_DITHERING_NOISE(sb,q->noise_idx);



                        run = 1;

                        break;



                    case 34:

                        if (get_bits_left(gb) >= 7) {

                            if (type34_first) {

                                type34_div = (float)(1 << get_bits(gb, 2));

                                samples[0] = ((float)get_bits(gb, 5) - 16.0) / 15.0;

                                type34_predictor = samples[0];

                                type34_first = 0;

                            } else {

                                unsigned index = qdm2_get_vlc(gb, &vlc_tab_type34, 0, 1);

                                if (index >= FF_ARRAY_ELEMS(type34_delta)) {

                                    av_log(NULL, AV_LOG_ERROR, "index %d out of type34_delta array\n", index);

                                    return AVERROR_INVALIDDATA;

                                }

                                samples[0] = type34_delta[index] / type34_div + type34_predictor;

                                type34_predictor = samples[0];

                            }

                        } else {

                            samples[0] = SB_DITHERING_NOISE(sb,q->noise_idx);

                        }

                        run = 1;

                        break;



                    default:

                        samples[0] = SB_DITHERING_NOISE(sb,q->noise_idx);

                        run = 1;

                        break;

                }



                if (joined_stereo) {

                    for (k = 0; k < run && j + k < 128; k++) {

                        q->sb_samples[0][j + k][sb] =

                            q->tone_level[0][sb][(j + k) / 2] * samples[k];

                        if (q->nb_channels == 2) {

                            if (sign_bits[(j + k) / 8])

                                q->sb_samples[1][j + k][sb] =

                                    q->tone_level[1][sb][(j + k) / 2] * -samples[k];

                            else

                                q->sb_samples[1][j + k][sb] =

                                    q->tone_level[1][sb][(j + k) / 2] * samples[k];

                        }

                    }

                } else {

                    for (k = 0; k < run; k++)

                        if ((j + k) < 128)

                            q->sb_samples[ch][j + k][sb] = q->tone_level[ch][sb][(j + k)/2] * samples[k];

                }



                j += run;

            } // j loop

        } // channel loop

    } // subband loop

    return 0;

}

static int ogg_new_stream(AVFormatContext *s, uint32_t serial, int new_avstream)

{



    struct ogg *ogg = s->priv_data;

    int idx = ogg->nstreams++;

    AVStream *st;

    struct ogg_stream *os;



    ogg->streams = av_realloc (ogg->streams,

                               ogg->nstreams * sizeof (*ogg->streams));

    memset (ogg->streams + idx, 0, sizeof (*ogg->streams));

    os = ogg->streams + idx;

    os->serial = serial;

    os->bufsize = DECODER_BUFFER_SIZE;

    os->buf = av_malloc(os->bufsize);

    os->header = -1;



    if (new_avstream) {

        st = avformat_new_stream(s, NULL);

        if (!st)

            return AVERROR(ENOMEM);



        st->id = idx;

        avpriv_set_pts_info(st, 64, 1, 1000000);

    }



    return idx;

}

static void adx_decode_stereo(short *out,const unsigned char *in,PREV *prev)

{

	short tmp[32*2];

	int i;



	adx_decode(tmp   ,in   ,prev);

	adx_decode(tmp+32,in+18,prev+1);

	for(i=0;i<32;i++) {

		out[i*2]   = tmp[i];

		out[i*2+1] = tmp[i+32];

	}

}

int add_av_stream(FFStream *feed,

                  AVStream *st)

{

    AVStream *fst;

    AVCodecContext *av, *av1;

    int i;



    av = &st->codec;

    for(i=0;i<feed->nb_streams;i++) {

        st = feed->streams[i];

        av1 = &st->codec;

        if (av1->codec_id == av->codec_id &&

            av1->codec_type == av->codec_type &&

            av1->bit_rate == av->bit_rate) {



            switch(av->codec_type) {

            case CODEC_TYPE_AUDIO:

                if (av1->channels == av->channels &&

                    av1->sample_rate == av->sample_rate)

                    goto found;

                break;

            case CODEC_TYPE_VIDEO:

                if (av1->width == av->width &&

                    av1->height == av->height &&

                    av1->frame_rate == av->frame_rate &&

                    av1->gop_size == av->gop_size)

                    goto found;

                break;

            default:

                abort();

            }

        }

    }



    fst = av_mallocz(sizeof(AVStream));

    if (!fst)

        return -1;

    fst->priv_data = av_mallocz(sizeof(FeedData));

    memcpy(&fst->codec, av, sizeof(AVCodecContext));

    feed->streams[feed->nb_streams++] = fst;

    return feed->nb_streams - 1;

 found:

    return i;

}

