static void skip_data_stream_element(GetBitContext *gb)

{

    int byte_align = get_bits1(gb);

    int count = get_bits(gb, 8);

    if (count == 255)

        count += get_bits(gb, 8);

    if (byte_align)

        align_get_bits(gb);

    skip_bits_long(gb, 8 * count);

}

static void celt_pvq_search(float *X, int *y, int K, int N)

{

    int i;

    float res = 0.0f, y_norm = 0.0f, xy_norm = 0.0f;



    for (i = 0; i < N; i++)

        res += FFABS(X[i]);



    res = K/res;



    for (i = 0; i < N; i++) {

        y[i] = lrintf(res*X[i]);

        y_norm  += y[i]*y[i];

        xy_norm += y[i]*X[i];

        K -= FFABS(y[i]);

    }



    while (K) {

        int max_idx = 0, phase = FFSIGN(K);

        float max_den = 1.0f, max_num = 0.0f;

        y_norm += 1.0f;



        for (i = 0; i < N; i++) {

            float xy_new = xy_norm + 1*phase*FFABS(X[i]);

            float y_new  = y_norm  + 2*phase*FFABS(y[i]);

            xy_new = xy_new * xy_new;

            /* FIXME: the y[i] check makes the search slightly worse at Ks below 5 */

            if (y[i] && (max_den*xy_new) > (y_new*max_num)) {

                max_den = y_new;

                max_num = xy_new;

                max_idx = i;

            }

        }



        K -= phase;



        phase *= FFSIGN(X[max_idx]);

        xy_norm += 1*phase*X[max_idx];

        y_norm  += 2*phase*y[max_idx];

        y[max_idx] += phase;

    }

}

static int rtsp_read_seek(AVFormatContext *s, int stream_index,

                          int64_t timestamp, int flags)

{

    RTSPState *rt = s->priv_data;



    rt->seek_timestamp = av_rescale_q(timestamp, s->streams[stream_index]->time_base, AV_TIME_BASE_Q);

    switch(rt->state) {

    default:

    case RTSP_STATE_IDLE:

        break;

    case RTSP_STATE_PLAYING:

        if (rtsp_read_pause(s) != 0)

            return -1;

        rt->state = RTSP_STATE_SEEKING;

        if (rtsp_read_play(s) != 0)

            return -1;

        break;

    case RTSP_STATE_PAUSED:

        rt->state = RTSP_STATE_IDLE;

        break;

    }

    return 0;

}

static int load_input_picture(MpegEncContext *s, AVFrame *pic_arg){

    AVFrame *pic=NULL;

    int64_t pts;

    int i;

    const int encoding_delay= s->max_b_frames;

    int direct=1;



    if(pic_arg){

        pts= pic_arg->pts;

        pic_arg->display_picture_number= s->input_picture_number++;



        if(pts != AV_NOPTS_VALUE){

            if(s->user_specified_pts != AV_NOPTS_VALUE){

                int64_t time= pts;

                int64_t last= s->user_specified_pts;



                if(time <= last){

                    av_log(s->avctx, AV_LOG_ERROR, "Error, Invalid timestamp=%"PRId64", last=%"PRId64"\n", pts, s->user_specified_pts);

                    return -1;

                }

            }

            s->user_specified_pts= pts;

        }else{

            if(s->user_specified_pts != AV_NOPTS_VALUE){

                s->user_specified_pts=

                pts= s->user_specified_pts + 1;

                av_log(s->avctx, AV_LOG_INFO, "Warning: AVFrame.pts=? trying to guess (%"PRId64")\n", pts);

            }else{

                pts= pic_arg->display_picture_number;

            }

        }

    }



  if(pic_arg){

    if(encoding_delay && !(s->flags&CODEC_FLAG_INPUT_PRESERVED)) direct=0;

    if(pic_arg->linesize[0] != s->linesize) direct=0;

    if(pic_arg->linesize[1] != s->uvlinesize) direct=0;

    if(pic_arg->linesize[2] != s->uvlinesize) direct=0;



//    av_log(AV_LOG_DEBUG, "%d %d %d %d\n",pic_arg->linesize[0], pic_arg->linesize[1], s->linesize, s->uvlinesize);



    if(direct){

        i= ff_find_unused_picture(s, 1);



        pic= (AVFrame*)&s->picture[i];

        pic->reference= 3;



        for(i=0; i<4; i++){

            pic->data[i]= pic_arg->data[i];

            pic->linesize[i]= pic_arg->linesize[i];

        }

        ff_alloc_picture(s, (Picture*)pic, 1);

    }else{

        i= ff_find_unused_picture(s, 0);



        pic= (AVFrame*)&s->picture[i];

        pic->reference= 3;



        ff_alloc_picture(s, (Picture*)pic, 0);



        if(   pic->data[0] + INPLACE_OFFSET == pic_arg->data[0]

           && pic->data[1] + INPLACE_OFFSET == pic_arg->data[1]

           && pic->data[2] + INPLACE_OFFSET == pic_arg->data[2]){

       // empty

        }else{

            int h_chroma_shift, v_chroma_shift;

            avcodec_get_chroma_sub_sample(s->avctx->pix_fmt, &h_chroma_shift, &v_chroma_shift);



            for(i=0; i<3; i++){

                int src_stride= pic_arg->linesize[i];

                int dst_stride= i ? s->uvlinesize : s->linesize;

                int h_shift= i ? h_chroma_shift : 0;

                int v_shift= i ? v_chroma_shift : 0;

                int w= s->width >>h_shift;

                int h= s->height>>v_shift;

                uint8_t *src= pic_arg->data[i];

                uint8_t *dst= pic->data[i];



                if(!s->avctx->rc_buffer_size)

                    dst +=INPLACE_OFFSET;



                if(src_stride==dst_stride)

                    memcpy(dst, src, src_stride*h);

                else{

                    while(h--){

                        memcpy(dst, src, w);

                        dst += dst_stride;

                        src += src_stride;

                    }

                }

            }

        }

    }

    copy_picture_attributes(s, pic, pic_arg);

    pic->pts= pts; //we set this here to avoid modifiying pic_arg

  }



    /* shift buffer entries */

    for(i=1; i<MAX_PICTURE_COUNT /*s->encoding_delay+1*/; i++)

        s->input_picture[i-1]= s->input_picture[i];



    s->input_picture[encoding_delay]= (Picture*)pic;



    return 0;

}

static inline void MPV_motion_lowres(MpegEncContext *s,

                              uint8_t *dest_y, uint8_t *dest_cb, uint8_t *dest_cr,

                              int dir, uint8_t **ref_picture,

                              h264_chroma_mc_func *pix_op)

{

    int mx, my;

    int mb_x, mb_y, i;

    const int lowres= s->avctx->lowres;

    const int block_s= 8>>lowres;



    mb_x = s->mb_x;

    mb_y = s->mb_y;



    switch(s->mv_type) {

    case MV_TYPE_16X16:

        mpeg_motion_lowres(s, dest_y, dest_cb, dest_cr,

                    0, 0, 0,

                    ref_picture, pix_op,

                    s->mv[dir][0][0], s->mv[dir][0][1], 2*block_s);

        break;

    case MV_TYPE_8X8:

        mx = 0;

        my = 0;

            for(i=0;i<4;i++) {

                hpel_motion_lowres(s, dest_y + ((i & 1) + (i >> 1) * s->linesize)*block_s,

                            ref_picture[0], 0, 0,

                            (2*mb_x + (i & 1))*block_s, (2*mb_y + (i >>1))*block_s,

                            s->width, s->height, s->linesize,

                            s->h_edge_pos >> lowres, s->v_edge_pos >> lowres,

                            block_s, block_s, pix_op,

                            s->mv[dir][i][0], s->mv[dir][i][1]);



                mx += s->mv[dir][i][0];

                my += s->mv[dir][i][1];

            }



        if(!(s->flags&CODEC_FLAG_GRAY))

            chroma_4mv_motion_lowres(s, dest_cb, dest_cr, ref_picture, pix_op, mx, my);

        break;

    case MV_TYPE_FIELD:

        if (s->picture_structure == PICT_FRAME) {

            /* top field */

            mpeg_motion_lowres(s, dest_y, dest_cb, dest_cr,

                        1, 0, s->field_select[dir][0],

                        ref_picture, pix_op,

                        s->mv[dir][0][0], s->mv[dir][0][1], block_s);

            /* bottom field */

            mpeg_motion_lowres(s, dest_y, dest_cb, dest_cr,

                        1, 1, s->field_select[dir][1],

                        ref_picture, pix_op,

                        s->mv[dir][1][0], s->mv[dir][1][1], block_s);

        } else {

            if(s->picture_structure != s->field_select[dir][0] + 1 && s->pict_type != B_TYPE && !s->first_field){

                ref_picture= s->current_picture_ptr->data;

            }



            mpeg_motion_lowres(s, dest_y, dest_cb, dest_cr,

                        0, 0, s->field_select[dir][0],

                        ref_picture, pix_op,

                        s->mv[dir][0][0], s->mv[dir][0][1], 2*block_s);

        }

        break;

    case MV_TYPE_16X8:

        for(i=0; i<2; i++){

            uint8_t ** ref2picture;



            if(s->picture_structure == s->field_select[dir][i] + 1 || s->pict_type == B_TYPE || s->first_field){

                ref2picture= ref_picture;

            }else{

                ref2picture= s->current_picture_ptr->data;

            }



            mpeg_motion_lowres(s, dest_y, dest_cb, dest_cr,

                        0, 0, s->field_select[dir][i],

                        ref2picture, pix_op,

                        s->mv[dir][i][0], s->mv[dir][i][1] + 2*block_s*i, block_s);



            dest_y += 2*block_s*s->linesize;

            dest_cb+= (2*block_s>>s->chroma_y_shift)*s->uvlinesize;

            dest_cr+= (2*block_s>>s->chroma_y_shift)*s->uvlinesize;

        }

        break;

    case MV_TYPE_DMV:

        if(s->picture_structure == PICT_FRAME){

            for(i=0; i<2; i++){

                int j;

                for(j=0; j<2; j++){

                    mpeg_motion_lowres(s, dest_y, dest_cb, dest_cr,

                                1, j, j^i,

                                ref_picture, pix_op,

                                s->mv[dir][2*i + j][0], s->mv[dir][2*i + j][1], block_s);

                }

                pix_op = s->dsp.avg_h264_chroma_pixels_tab;

            }

        }else{

            for(i=0; i<2; i++){

                mpeg_motion_lowres(s, dest_y, dest_cb, dest_cr,

                            0, 0, s->picture_structure != i+1,

                            ref_picture, pix_op,

                            s->mv[dir][2*i][0],s->mv[dir][2*i][1],2*block_s);



                // after put we make avg of the same block

                pix_op = s->dsp.avg_h264_chroma_pixels_tab;



                //opposite parity is always in the same frame if this is second field

                if(!s->first_field){

                    ref_picture = s->current_picture_ptr->data;

                }

            }

        }

    break;

    default: assert(0);

    }

}

static int jpeg2000_decode_packets(Jpeg2000DecoderContext *s, Jpeg2000Tile *tile)

{

    int ret, i;

    int tp_index = 0;



    s->bit_index = 8;

    if (tile->poc.nb_poc) {

        for (i=0; i<tile->poc.nb_poc; i++) {

            Jpeg2000POCEntry *e = &tile->poc.poc[i];

            ret = jpeg2000_decode_packets_po_iteration(s, tile,

                e->RSpoc, e->CSpoc,

                e->LYEpoc, e->REpoc, e->CEpoc,

                e->Ppoc, &tp_index

                );

            if (ret < 0)

                return ret;

        }

    } else {

        ret = jpeg2000_decode_packets_po_iteration(s, tile,

            0, 0,

            tile->codsty[0].nlayers,

            33,

            s->ncomponents,

            tile->codsty[0].prog_order,

            &tp_index

        );

    }

    /* EOC marker reached */

    bytestream2_skip(&s->g, 2);



    return ret;

}

static int pix_sum_altivec(uint8_t *pix, int line_size)

{

    int i, s;

    const vector unsigned int zero =

        (const vector unsigned int) vec_splat_u32(0);

    vector unsigned int sad = (vector unsigned int) vec_splat_u32(0);

    vector signed int sumdiffs;



    for (i = 0; i < 16; i++) {

        /* Read the potentially unaligned 16 pixels into t1. */

        //vector unsigned char pixl = vec_ld(0,  pix);

        //vector unsigned char pixr = vec_ld(15, pix);

        //vector unsigned char t1   = vec_perm(pixl, pixr, perm);

        vector unsigned char t1   = vec_vsx_ld(0,  pix);



        /* Add each 4 pixel group together and put 4 results into sad. */

        sad = vec_sum4s(t1, sad);



        pix += line_size;

    }



    /* Sum up the four partial sums, and put the result into s. */

    sumdiffs = vec_sums((vector signed int) sad, (vector signed int) zero);

    sumdiffs = vec_splat(sumdiffs, 3);

    vec_vsx_st(sumdiffs, 0, &s);

    return s;

}

static inline void mix_3f_1r_to_dolby(AC3DecodeContext *ctx)

{

    int i;

    float (*output)[256] = ctx->audio_block.block_output;



    for (i = 0; i < 256; i++) {

        output[1][i] += (output[2][i] - output[4][i]);

        output[2][i] += (output[3][i] + output[4][i]);

    }

    memset(output[3], 0, sizeof(output[3]));

    memset(output[4], 0, sizeof(output[4]));

}

static int has_codec_parameters(AVCodecContext *enc)

{

    int val;

    switch(enc->codec_type) {

    case CODEC_TYPE_AUDIO:

        val = enc->sample_rate;

        break;

    case CODEC_TYPE_VIDEO:

        val = enc->width && enc->pix_fmt != PIX_FMT_NONE;

        break;

    default:

        val = 1;

        break;

    }

    return (val != 0);

}

static int test_vector_fmul_scalar(AVFloatDSPContext *fdsp, AVFloatDSPContext *cdsp,

                                   const float *v1, float scale)

{

    LOCAL_ALIGNED(32, float, cdst, [LEN]);

    LOCAL_ALIGNED(32, float, odst, [LEN]);

    int ret;



    cdsp->vector_fmul_scalar(cdst, v1, scale, LEN);

    fdsp->vector_fmul_scalar(odst, v1, scale, LEN);



    if (ret = compare_floats(cdst, odst, LEN, FLT_EPSILON))

