double parse_number_or_die(const char *context, const char *numstr, int type,

                           double min, double max)

{

    char *tail;

    const char *error;

    double d = av_strtod(numstr, &tail);

    if (*tail)

        error = "Expected number for %s but found: %s\n";

    else if (d < min || d > max)

        error = "The value for %s was %s which is not within %f - %f\n";

    else if (type == OPT_INT64 && (int64_t)d != d)

        error = "Expected int64 for %s but found %s\n";

    else if (type == OPT_INT && (int)d != d)

        error = "Expected int for %s but found %s\n";

    else

        return d;

    av_log(NULL, AV_LOG_FATAL, error, context, numstr, min, max);

    exit(1);

    return 0;

}

static void init_fps(int bf, int audio_preroll, int fps)

{

    AVStream *st;

    ctx = avformat_alloc_context();

    if (!ctx)

        exit(1);

    ctx->oformat = av_guess_format(format, NULL, NULL);

    if (!ctx->oformat)

        exit(1);

    ctx->pb = avio_alloc_context(iobuf, sizeof(iobuf), AVIO_FLAG_WRITE, NULL, NULL, io_write, NULL);

    if (!ctx->pb)

        exit(1);

    ctx->flags |= AVFMT_FLAG_BITEXACT;



    st = avformat_new_stream(ctx, NULL);

    if (!st)

        exit(1);

    st->codec->codec_type = AVMEDIA_TYPE_VIDEO;

    st->codec->codec_id = AV_CODEC_ID_H264;

    st->codec->width = 640;

    st->codec->height = 480;

    st->time_base.num = 1;

    st->time_base.den = 30;

    st->codec->extradata_size = sizeof(h264_extradata);

    st->codec->extradata = av_mallocz(st->codec->extradata_size + AV_INPUT_BUFFER_PADDING_SIZE);

    if (!st->codec->extradata)

        exit(1);

    memcpy(st->codec->extradata, h264_extradata, sizeof(h264_extradata));

    st->codec->flags |= AV_CODEC_FLAG_GLOBAL_HEADER;

    video_st = st;



    st = avformat_new_stream(ctx, NULL);

    if (!st)

        exit(1);

    st->codec->codec_type = AVMEDIA_TYPE_AUDIO;

    st->codec->codec_id = AV_CODEC_ID_AAC;

    st->codec->sample_rate = 44100;

    st->codec->channels = 2;

    st->time_base.num = 1;

    st->time_base.den = 44100;

    st->codec->extradata_size = sizeof(aac_extradata);

    st->codec->extradata = av_mallocz(st->codec->extradata_size + AV_INPUT_BUFFER_PADDING_SIZE);

    if (!st->codec->extradata)

        exit(1);

    memcpy(st->codec->extradata, aac_extradata, sizeof(aac_extradata));

    st->codec->flags |= AV_CODEC_FLAG_GLOBAL_HEADER;

    audio_st = st;



    if (avformat_write_header(ctx, &opts) < 0)

        exit(1);

    av_dict_free(&opts);



    frames = 0;

    gop_size = 30;

    duration = video_st->time_base.den / fps;

    audio_duration = 1024 * audio_st->time_base.den / audio_st->codec->sample_rate;

    if (audio_preroll)

        audio_preroll = 2048 * audio_st->time_base.den / audio_st->codec->sample_rate;



    bframes = bf;

    video_dts = bframes ? -duration : 0;

    audio_dts = -audio_preroll;

}

static int matroska_parse_laces(MatroskaDemuxContext *matroska, uint8_t **buf,

                                int* buf_size, int type,

                                uint32_t **lace_buf, int *laces)

{

    int res = 0, n, size = *buf_size;

    uint8_t *data = *buf;

    uint32_t *lace_size;



    if (!type) {

        *laces = 1;

        *lace_buf = av_mallocz(sizeof(int));

        if (!*lace_buf)

            return AVERROR(ENOMEM);



        *lace_buf[0] = size;

        return 0;

    }



    av_assert0(size > 0);

    *laces = *data + 1;

    data += 1;

    size -= 1;

    lace_size = av_mallocz(*laces * sizeof(int));

    if (!lace_size)

        return AVERROR(ENOMEM);



    switch (type) {

    case 0x1: /* Xiph lacing */ {

        uint8_t temp;

        uint32_t total = 0;

        for (n = 0; res == 0 && n < *laces - 1; n++) {

            while (1) {

                if (size == 0) {

                    res = AVERROR_INVALIDDATA;

                    break;

                }

                temp = *data;

                lace_size[n] += temp;

                data += 1;

                size -= 1;

                if (temp != 0xff)

                    break;

            }

            total += lace_size[n];

        }

        if (size <= total) {

            res = AVERROR_INVALIDDATA;

            break;

        }



        lace_size[n] = size - total;

        break;

    }



    case 0x2: /* fixed-size lacing */

        if (size % (*laces)) {

            res = AVERROR_INVALIDDATA;

            break;

        }

        for (n = 0; n < *laces; n++)

            lace_size[n] = size / *laces;

        break;



    case 0x3: /* EBML lacing */ {

        uint64_t num;

        uint64_t total;

        n = matroska_ebmlnum_uint(matroska, data, size, &num);

        if (n < 0) {

            av_log(matroska->ctx, AV_LOG_INFO,

                   "EBML block data error\n");

            res = n;

            break;

        }

        data += n;

        size -= n;

        total = lace_size[0] = num;

        for (n = 1; res == 0 && n < *laces - 1; n++) {

            int64_t snum;

            int r;

            r = matroska_ebmlnum_sint(matroska, data, size, &snum);

            if (r < 0) {

                av_log(matroska->ctx, AV_LOG_INFO,

                       "EBML block data error\n");

                res = r;

                break;

            }

            data += r;

            size -= r;

            lace_size[n] = lace_size[n - 1] + snum;

            total += lace_size[n];

        }

        if (size <= total) {

            res = AVERROR_INVALIDDATA;

            break;

        }

        lace_size[*laces - 1] = size - total;

        break;

    }

    }



    *buf      = data;

    *lace_buf = lace_size;

    *buf_size = size;



    return res;

}

static av_cold int ape_decode_init(AVCodecContext * avctx)

{

    APEContext *s = avctx->priv_data;

    int i;



    if (avctx->extradata_size != 6) {

        av_log(avctx, AV_LOG_ERROR, "Incorrect extradata\n");

        return -1;

    }

    if (avctx->bits_per_coded_sample != 16) {

        av_log(avctx, AV_LOG_ERROR, "Only 16-bit samples are supported\n");

        return -1;

    }

    if (avctx->channels > 2) {

        av_log(avctx, AV_LOG_ERROR, "Only mono and stereo is supported\n");

        return -1;

    }

    s->avctx             = avctx;

    s->channels          = avctx->channels;

    s->fileversion       = AV_RL16(avctx->extradata);

    s->compression_level = AV_RL16(avctx->extradata + 2);

    s->flags             = AV_RL16(avctx->extradata + 4);



    av_log(avctx, AV_LOG_DEBUG, "Compression Level: %d - Flags: %d\n", s->compression_level, s->flags);

    if (s->compression_level % 1000 || s->compression_level > COMPRESSION_LEVEL_INSANE) {

        av_log(avctx, AV_LOG_ERROR, "Incorrect compression level %d\n", s->compression_level);

        return -1;

    }

    s->fset = s->compression_level / 1000 - 1;

    for (i = 0; i < APE_FILTER_LEVELS; i++) {

        if (!ape_filter_orders[s->fset][i])

            break;

        s->filterbuf[i] = av_malloc((ape_filter_orders[s->fset][i] * 3 + HISTORY_SIZE) * 4);

    }



    dsputil_init(&s->dsp, avctx);

    avctx->sample_fmt = AV_SAMPLE_FMT_S16;

    avctx->channel_layout = (avctx->channels==2) ? AV_CH_LAYOUT_STEREO : AV_CH_LAYOUT_MONO;

    return 0;

}

static void hScale16To19_c(SwsContext *c, int16_t *_dst, int dstW, const uint8_t *_src,

                           const int16_t *filter,

                           const int16_t *filterPos, int filterSize)

{

    int i;

    int32_t *dst = (int32_t *) _dst;

    const uint16_t *src = (const uint16_t *) _src;

    int bits = av_pix_fmt_descriptors[c->srcFormat].comp[0].depth_minus1;

    int sh = bits - 4;



    for (i = 0; i < dstW; i++) {

        int j;

        int srcPos = filterPos[i];

        int val = 0;



        for (j = 0; j < filterSize; j++) {

            val += src[srcPos + j] * filter[filterSize * i + j];

        }

        // filter=14 bit, input=16 bit, output=30 bit, >> 11 makes 19 bit

        dst[i] = FFMIN(val >> sh, (1 << 19) - 1);

    }

}

static void test_butterflies_float(const float *src0, const float *src1)

{

    LOCAL_ALIGNED_16(float,  cdst,  [LEN]);

    LOCAL_ALIGNED_16(float,  odst,  [LEN]);

    LOCAL_ALIGNED_16(float,  cdst1, [LEN]);

    LOCAL_ALIGNED_16(float,  odst1, [LEN]);

    int i;



    declare_func(void, float *av_restrict src0, float *av_restrict src1,

    int len);



    memcpy(cdst,  src0, LEN * sizeof(*src0));

    memcpy(cdst1, src1, LEN * sizeof(*src1));

    memcpy(odst,  src0, LEN * sizeof(*src0));

