    memcpy(odst1, src1, LEN * sizeof(*src1));

    bench_new(odst, odst1, LEN);

}

static int wav_read_packet(AVFormatContext *s, AVPacket *pkt)

{

    int ret, size;

    int64_t left;

    AVStream *st;

    WAVDemuxContext *wav = s->priv_data;



    if (CONFIG_SPDIF_DEMUXER && wav->spdif == 0 &&

        s->streams[0]->codec->codec_tag == 1) {

        enum AVCodecID codec;

        ret = ff_spdif_probe(s->pb->buffer, s->pb->buf_end - s->pb->buffer,

                             &codec);

        if (ret > AVPROBE_SCORE_EXTENSION) {

            s->streams[0]->codec->codec_id = codec;

            wav->spdif = 1;

        } else {

            wav->spdif = -1;

        }

    }

    if (CONFIG_SPDIF_DEMUXER && wav->spdif == 1)

        return ff_spdif_read_packet(s, pkt);



    if (wav->smv_data_ofs > 0) {

        int64_t audio_dts, video_dts;

smv_retry:

        audio_dts = s->streams[0]->cur_dts;

        video_dts = s->streams[1]->cur_dts;



        if (audio_dts != AV_NOPTS_VALUE && video_dts != AV_NOPTS_VALUE) {

            /*We always return a video frame first to get the pixel format first*/

            wav->smv_last_stream = wav->smv_given_first ?

                av_compare_ts(video_dts, s->streams[1]->time_base,

                              audio_dts, s->streams[0]->time_base) > 0 : 0;

            wav->smv_given_first = 1;

        }

        wav->smv_last_stream = !wav->smv_last_stream;

        wav->smv_last_stream |= wav->audio_eof;

        wav->smv_last_stream &= !wav->smv_eof;

        if (wav->smv_last_stream) {

            uint64_t old_pos = avio_tell(s->pb);

            uint64_t new_pos = wav->smv_data_ofs +

                wav->smv_block * wav->smv_block_size;

            if (avio_seek(s->pb, new_pos, SEEK_SET) < 0) {

                ret = AVERROR_EOF;

                goto smv_out;

            }

            size = avio_rl24(s->pb);

            ret  = av_get_packet(s->pb, pkt, size);

            if (ret < 0)

                goto smv_out;

            pkt->pos -= 3;

            pkt->pts = wav->smv_block * wav->smv_frames_per_jpeg + wav->smv_cur_pt;

            wav->smv_cur_pt++;

            if (wav->smv_frames_per_jpeg > 0)

                wav->smv_cur_pt %= wav->smv_frames_per_jpeg;

            if (!wav->smv_cur_pt)

                wav->smv_block++;



            pkt->stream_index = 1;

smv_out:

            avio_seek(s->pb, old_pos, SEEK_SET);

            if (ret == AVERROR_EOF) {

                wav->smv_eof = 1;

                goto smv_retry;

            }

            return ret;

        }

    }



    st = s->streams[0];



    left = wav->data_end - avio_tell(s->pb);

    if (wav->ignore_length)

        left = INT_MAX;

    if (left <= 0) {

        if (CONFIG_W64_DEMUXER && wav->w64)

            left = find_guid(s->pb, ff_w64_guid_data) - 24;

        else

            left = find_tag(s->pb, MKTAG('d', 'a', 't', 'a'));

        if (left < 0) {

            wav->audio_eof = 1;

            if (wav->smv_data_ofs > 0 && !wav->smv_eof)

                goto smv_retry;

            return AVERROR_EOF;

        }

        wav->data_end = avio_tell(s->pb) + left;

    }



    size = MAX_SIZE;

    if (st->codec->block_align > 1) {

        if (size < st->codec->block_align)

            size = st->codec->block_align;

        size = (size / st->codec->block_align) * st->codec->block_align;

    }

    size = FFMIN(size, left);

    ret  = av_get_packet(s->pb, pkt, size);

    if (ret < 0)

        return ret;

    pkt->stream_index = 0;



    return ret;

}

int ff_new_chapter(AVFormatContext *s, int id, int64_t start, int64_t end, const char *title)

{

    AVChapter *chapter = NULL;

    int i;



    for(i=0; i<s->num_chapters; i++)

        if(s->chapters[i]->id == id)

            chapter = s->chapters[i];



    if(!chapter){

        chapter= av_mallocz(sizeof(AVChapter));

        if(!chapter)

            return AVERROR(ENOMEM);

        dynarray_add(&s->chapters, &s->num_chapters, chapter);

    }

    if(chapter->title)

        av_free(chapter->title);

    if (title)

        chapter->title = av_strdup(title);

    chapter->id    = id;

    chapter->start = start;

    chapter->end = end;



    return 0;

}

static int flic_decode_frame_8BPP(AVCodecContext *avctx,

                                  void *data, int *got_frame,

                                  const uint8_t *buf, int buf_size)

{

    FlicDecodeContext *s = avctx->priv_data;



    GetByteContext g2;

    int pixel_ptr;

    int palette_ptr;

    unsigned char palette_idx1;

    unsigned char palette_idx2;



    unsigned int frame_size;

    int num_chunks;



    unsigned int chunk_size;

    int chunk_type;



    int i, j, ret;



    int color_packets;

    int color_changes;

    int color_shift;

    unsigned char r, g, b;



    int lines;

    int compressed_lines;

    int starting_line;

    signed short line_packets;

    int y_ptr;

    int byte_run;

    int pixel_skip;

    int pixel_countdown;

    unsigned char *pixels;

    unsigned int pixel_limit;



    bytestream2_init(&g2, buf, buf_size);



    if ((ret = ff_reget_buffer(avctx, &s->frame)) < 0)

        return ret;



    pixels = s->frame.data[0];

    pixel_limit = s->avctx->height * s->frame.linesize[0];

    if (buf_size < 16 || buf_size > INT_MAX - (3 * 256 + FF_INPUT_BUFFER_PADDING_SIZE))

        return AVERROR_INVALIDDATA;

    frame_size = bytestream2_get_le32(&g2);

    if (frame_size > buf_size)

        frame_size = buf_size;

    bytestream2_skip(&g2, 2); /* skip the magic number */

    num_chunks = bytestream2_get_le16(&g2);

    bytestream2_skip(&g2, 8);  /* skip padding */



    frame_size -= 16;



    /* iterate through the chunks */

    while ((frame_size >= 6) && (num_chunks > 0)) {

        int stream_ptr_after_chunk;

        chunk_size = bytestream2_get_le32(&g2);

        if (chunk_size > frame_size) {

            av_log(avctx, AV_LOG_WARNING,

                   "Invalid chunk_size = %u > frame_size = %u\n", chunk_size, frame_size);

            chunk_size = frame_size;

        }

        stream_ptr_after_chunk = bytestream2_tell(&g2) - 4 + chunk_size;



        chunk_type = bytestream2_get_le16(&g2);



        switch (chunk_type) {

        case FLI_256_COLOR:

        case FLI_COLOR:

            /* check special case: If this file is from the Magic Carpet

             * game and uses 6-bit colors even though it reports 256-color

             * chunks in a 0xAF12-type file (fli_type is set to 0xAF13 during

             * initialization) */

            if ((chunk_type == FLI_256_COLOR) && (s->fli_type != FLC_MAGIC_CARPET_SYNTHETIC_TYPE_CODE))

                color_shift = 0;

            else

                color_shift = 2;

            /* set up the palette */

            color_packets = bytestream2_get_le16(&g2);

            palette_ptr = 0;

            for (i = 0; i < color_packets; i++) {

                /* first byte is how many colors to skip */

                palette_ptr += bytestream2_get_byte(&g2);



                /* next byte indicates how many entries to change */

                color_changes = bytestream2_get_byte(&g2);



                /* if there are 0 color changes, there are actually 256 */

                if (color_changes == 0)

                    color_changes = 256;



                if (bytestream2_tell(&g2) + color_changes * 3 > stream_ptr_after_chunk)

                    break;



                for (j = 0; j < color_changes; j++) {

                    unsigned int entry;



                    /* wrap around, for good measure */

                    if ((unsigned)palette_ptr >= 256)

                        palette_ptr = 0;



                    r = bytestream2_get_byte(&g2) << color_shift;

                    g = bytestream2_get_byte(&g2) << color_shift;

                    b = bytestream2_get_byte(&g2) << color_shift;

                    entry = 0xFFU << 24 | r << 16 | g << 8 | b;

                    if (color_shift == 2)

                        entry |= entry >> 6 & 0x30303;

                    if (s->palette[palette_ptr] != entry)

                        s->new_palette = 1;

                    s->palette[palette_ptr++] = entry;

                }

            }

            break;



        case FLI_DELTA:

            y_ptr = 0;

            compressed_lines = bytestream2_get_le16(&g2);

            while (compressed_lines > 0) {

                if (bytestream2_tell(&g2) + 2 > stream_ptr_after_chunk)

                    break;

                line_packets = bytestream2_get_le16(&g2);

                if ((line_packets & 0xC000) == 0xC000) {

                    // line skip opcode

                    line_packets = -line_packets;

                    y_ptr += line_packets * s->frame.linesize[0];

                } else if ((line_packets & 0xC000) == 0x4000) {

                    av_log(avctx, AV_LOG_ERROR, "Undefined opcode (%x) in DELTA_FLI\n", line_packets);

                } else if ((line_packets & 0xC000) == 0x8000) {

                    // "last byte" opcode

                    pixel_ptr= y_ptr + s->frame.linesize[0] - 1;

                    CHECK_PIXEL_PTR(0);

                    pixels[pixel_ptr] = line_packets & 0xff;

                } else {

                    compressed_lines--;

                    pixel_ptr = y_ptr;

                    CHECK_PIXEL_PTR(0);

                    pixel_countdown = s->avctx->width;

                    for (i = 0; i < line_packets; i++) {

                        if (bytestream2_tell(&g2) + 2 > stream_ptr_after_chunk)

                            break;

                        /* account for the skip bytes */

                        pixel_skip = bytestream2_get_byte(&g2);

                        pixel_ptr += pixel_skip;

                        pixel_countdown -= pixel_skip;

                        byte_run = sign_extend(bytestream2_get_byte(&g2), 8);

                        if (byte_run < 0) {

                            byte_run = -byte_run;

                            palette_idx1 = bytestream2_get_byte(&g2);

                            palette_idx2 = bytestream2_get_byte(&g2);

                            CHECK_PIXEL_PTR(byte_run * 2);

                            for (j = 0; j < byte_run; j++, pixel_countdown -= 2) {

                                pixels[pixel_ptr++] = palette_idx1;

                                pixels[pixel_ptr++] = palette_idx2;

                            }

                        } else {

                            CHECK_PIXEL_PTR(byte_run * 2);

                            if (bytestream2_tell(&g2) + byte_run * 2 > stream_ptr_after_chunk)

                                break;

                            for (j = 0; j < byte_run * 2; j++, pixel_countdown--) {

                                pixels[pixel_ptr++] = bytestream2_get_byte(&g2);

                            }

                        }

                    }



                    y_ptr += s->frame.linesize[0];

                }

            }

            break;



        case FLI_LC:

            /* line compressed */

            starting_line = bytestream2_get_le16(&g2);

            y_ptr = 0;

            y_ptr += starting_line * s->frame.linesize[0];



            compressed_lines = bytestream2_get_le16(&g2);

            while (compressed_lines > 0) {

                pixel_ptr = y_ptr;

                CHECK_PIXEL_PTR(0);

                pixel_countdown = s->avctx->width;

                if (bytestream2_tell(&g2) + 1 > stream_ptr_after_chunk)

                    break;

                line_packets = bytestream2_get_byte(&g2);

                if (line_packets > 0) {

                    for (i = 0; i < line_packets; i++) {

                        /* account for the skip bytes */

                        if (bytestream2_tell(&g2) + 1 > stream_ptr_after_chunk)

                            break;

                        pixel_skip = bytestream2_get_byte(&g2);

                        pixel_ptr += pixel_skip;

                        pixel_countdown -= pixel_skip;

                        byte_run = sign_extend(bytestream2_get_byte(&g2),8);

                        if (byte_run > 0) {

                            CHECK_PIXEL_PTR(byte_run);

                            if (bytestream2_tell(&g2) + byte_run > stream_ptr_after_chunk)

                                break;

                            for (j = 0; j < byte_run; j++, pixel_countdown--) {

                                pixels[pixel_ptr++] = bytestream2_get_byte(&g2);

                            }

                        } else if (byte_run < 0) {

                            byte_run = -byte_run;

                            palette_idx1 = bytestream2_get_byte(&g2);

                            CHECK_PIXEL_PTR(byte_run);

                            for (j = 0; j < byte_run; j++, pixel_countdown--) {

                                pixels[pixel_ptr++] = palette_idx1;

                            }

                        }

                    }

                }



                y_ptr += s->frame.linesize[0];

                compressed_lines--;

            }

            break;



        case FLI_BLACK:

            /* set the whole frame to color 0 (which is usually black) */

            memset(pixels, 0,

                s->frame.linesize[0] * s->avctx->height);

            break;



        case FLI_BRUN:

            /* Byte run compression: This chunk type only occurs in the first

             * FLI frame and it will update the entire frame. */

            y_ptr = 0;

            for (lines = 0; lines < s->avctx->height; lines++) {

                pixel_ptr = y_ptr;

                /* disregard the line packets; instead, iterate through all

                 * pixels on a row */

                 bytestream2_skip(&g2, 1);

                pixel_countdown = s->avctx->width;

                while (pixel_countdown > 0) {

                    if (bytestream2_tell(&g2) + 1 > stream_ptr_after_chunk)

                        break;

                    byte_run = sign_extend(bytestream2_get_byte(&g2), 8);

                    if (!byte_run) {

                        av_log(avctx, AV_LOG_ERROR, "Invalid byte run value.\n");

                        return AVERROR_INVALIDDATA;

                    }



                    if (byte_run > 0) {

                        palette_idx1 = bytestream2_get_byte(&g2);

                        CHECK_PIXEL_PTR(byte_run);

                        for (j = 0; j < byte_run; j++) {

                            pixels[pixel_ptr++] = palette_idx1;

                            pixel_countdown--;

                            if (pixel_countdown < 0)

                                av_log(avctx, AV_LOG_ERROR, "pixel_countdown < 0 (%d) at line %d\n",

                                       pixel_countdown, lines);

                        }

                    } else {  /* copy bytes if byte_run < 0 */

                        byte_run = -byte_run;

                        CHECK_PIXEL_PTR(byte_run);

                        if (bytestream2_tell(&g2) + byte_run > stream_ptr_after_chunk)

                            break;

                        for (j = 0; j < byte_run; j++) {

                            pixels[pixel_ptr++] = bytestream2_get_byte(&g2);

                            pixel_countdown--;

                            if (pixel_countdown < 0)

                                av_log(avctx, AV_LOG_ERROR, "pixel_countdown < 0 (%d) at line %d\n",

                                       pixel_countdown, lines);

                        }

                    }

                }



                y_ptr += s->frame.linesize[0];

            }

            break;



        case FLI_COPY:

            /* copy the chunk (uncompressed frame) */

            if (chunk_size - 6 != s->avctx->width * s->avctx->height) {

                av_log(avctx, AV_LOG_ERROR, "In chunk FLI_COPY : source data (%d bytes) " \

                       "has incorrect size, skipping chunk\n", chunk_size - 6);

                bytestream2_skip(&g2, chunk_size - 6);

            } else {

                for (y_ptr = 0; y_ptr < s->frame.linesize[0] * s->avctx->height;

                     y_ptr += s->frame.linesize[0]) {

                    bytestream2_get_buffer(&g2, &pixels[y_ptr],

                                           s->avctx->width);

                }

            }

            break;



        case FLI_MINI:

            /* some sort of a thumbnail? disregard this chunk... */

            break;



        default:

            av_log(avctx, AV_LOG_ERROR, "Unrecognized chunk type: %d\n", chunk_type);

            break;

        }



        if (stream_ptr_after_chunk - bytestream2_tell(&g2) > 0)

            bytestream2_skip(&g2, stream_ptr_after_chunk - bytestream2_tell(&g2));



        frame_size -= chunk_size;

        num_chunks--;

    }



    /* by the end of the chunk, the stream ptr should equal the frame

     * size (minus 1 or 2, possibly); if it doesn't, issue a warning */

    if (bytestream2_get_bytes_left(&g2) > 2)

        av_log(avctx, AV_LOG_ERROR, "Processed FLI chunk where chunk size = %d " \

               "and final chunk ptr = %d\n", buf_size,

               buf_size - bytestream2_get_bytes_left(&g2));



    /* make the palette available on the way out */

    memcpy(s->frame.data[1], s->palette, AVPALETTE_SIZE);

    if (s->new_palette) {

        s->frame.palette_has_changed = 1;

        s->new_palette = 0;

    }



    if ((ret = av_frame_ref(data, &s->frame)) < 0)

        return ret;



    *got_frame = 1;



    return buf_size;

}

static void mpeg_decode_sequence_extension(Mpeg1Context *s1)

{

    MpegEncContext *s = &s1->mpeg_enc_ctx;

    int horiz_size_ext, vert_size_ext;

    int bit_rate_ext;



    skip_bits(&s->gb, 1); /* profile and level esc*/

    s->avctx->profile       = get_bits(&s->gb, 3);

    s->avctx->level         = get_bits(&s->gb, 4);

    s->progressive_sequence = get_bits1(&s->gb);   /* progressive_sequence */

    s->chroma_format        = get_bits(&s->gb, 2); /* chroma_format 1=420, 2=422, 3=444 */



    if (!s->chroma_format) {

        s->chroma_format = 1;

        av_log(s->avctx, AV_LOG_WARNING, "Chroma format invalid\n");

    }



    horiz_size_ext          = get_bits(&s->gb, 2);

    vert_size_ext           = get_bits(&s->gb, 2);

    s->width  |= (horiz_size_ext << 12);

    s->height |= (vert_size_ext  << 12);

    bit_rate_ext = get_bits(&s->gb, 12);  /* XXX: handle it */

    s->bit_rate += (bit_rate_ext << 18) * 400;

    check_marker(&s->gb, "after bit rate extension");

    s->avctx->rc_buffer_size += get_bits(&s->gb, 8) * 1024 * 16 << 10;



    s->low_delay = get_bits1(&s->gb);

    if (s->avctx->flags & AV_CODEC_FLAG_LOW_DELAY)

        s->low_delay = 1;



    s1->frame_rate_ext.num = get_bits(&s->gb, 2) + 1;

    s1->frame_rate_ext.den = get_bits(&s->gb, 5) + 1;



    ff_dlog(s->avctx, "sequence extension\n");

    s->codec_id = s->avctx->codec_id = AV_CODEC_ID_MPEG2VIDEO;



    if (s->avctx->debug & FF_DEBUG_PICT_INFO)

        av_log(s->avctx, AV_LOG_DEBUG,

               "profile: %d, level: %d ps: %d cf:%d vbv buffer: %d, bitrate:%"PRId64"\n",

               s->avctx->profile, s->avctx->level, s->progressive_sequence, s->chroma_format,

               s->avctx->rc_buffer_size, s->bit_rate);

}

static void get_pixels_altivec(int16_t *restrict block, const uint8_t *pixels, int line_size)

{

    int i;

    vector unsigned char perm = vec_lvsl(0, pixels);

    vector unsigned char bytes;

    const vector unsigned char zero = (const vector unsigned char)vec_splat_u8(0);

    vector signed short shorts;



    for (i = 0; i < 8; i++) {

        // Read potentially unaligned pixels.

        // We're reading 16 pixels, and actually only want 8,

        // but we simply ignore the extras.

        vector unsigned char pixl = vec_ld( 0, pixels);

        vector unsigned char pixr = vec_ld(15, pixels);

        bytes = vec_perm(pixl, pixr, perm);



        // convert the bytes into shorts

        shorts = (vector signed short)vec_mergeh(zero, bytes);



        // save the data to the block, we assume the block is 16-byte aligned

        vec_st(shorts, i*16, (vector signed short*)block);



        pixels += line_size;

    }

}

static int sap_write_close(AVFormatContext *s)

{

    struct SAPState *sap = s->priv_data;

    int i;



    for (i = 0; i < s->nb_streams; i++) {

        AVFormatContext *rtpctx = s->streams[i]->priv_data;

        if (!rtpctx)

            continue;

        av_write_trailer(rtpctx);

        url_fclose(rtpctx->pb);

        av_metadata_free(&rtpctx->streams[0]->metadata);

        av_metadata_free(&rtpctx->metadata);


        av_free(rtpctx->streams[0]);

        av_free(rtpctx);

        s->streams[i]->priv_data = NULL;

    }



    if (sap->last_time && sap->ann && sap->ann_fd) {

        sap->ann[0] |= 4; /* Session deletion*/

        url_write(sap->ann_fd, sap->ann, sap->ann_size);

    }



    av_freep(&sap->ann);

    if (sap->ann_fd)

        url_close(sap->ann_fd);

    ff_network_close();

    return 0;

}

static int get_cod(Jpeg2000DecoderContext *s, Jpeg2000CodingStyle *c,

                   uint8_t *properties)

{

    Jpeg2000CodingStyle tmp;

    int compno;



    if (s->buf_end - s->buf < 5)

        return AVERROR_INVALIDDATA;



    tmp.log2_prec_width  =

    tmp.log2_prec_height = 15;



    tmp.csty = bytestream_get_byte(&s->buf);



    // get progression order

    tmp.prog_order = bytestream_get_byte(&s->buf);



    tmp.nlayers = bytestream_get_be16(&s->buf);

    tmp.mct     = bytestream_get_byte(&s->buf); // multiple component transformation



    get_cox(s, &tmp);

    for (compno = 0; compno < s->ncomponents; compno++)

        if (!(properties[compno] & HAD_COC))

            memcpy(c + compno, &tmp, sizeof(tmp));

    return 0;

}

static inline int RENAME(yuv420_rgb32)(SwsContext *c, uint8_t* src[], int srcStride[], int srcSliceY,

             int srcSliceH, uint8_t* dst[], int dstStride[]){

    int y, h_size;



    if(c->srcFormat == PIX_FMT_YUV422P){

	srcStride[1] *= 2;

	srcStride[2] *= 2;

    }



    h_size= (c->dstW+7)&~7;

    if(h_size*4 > FFABS(dstStride[0])) h_size-=8;



    __asm__ __volatile__ ("pxor %mm4, %mm4;" /* zero mm4 */ );



    for (y= 0; y<srcSliceH; y++ ) {

	uint8_t *_image = dst[0] + (y+srcSliceY)*dstStride[0];

	uint8_t *_py = src[0] + y*srcStride[0];

	uint8_t *_pu = src[1] + (y>>1)*srcStride[1];

	uint8_t *_pv = src[2] + (y>>1)*srcStride[2];

	long index= -h_size/2;



	    /* this mmx assembly code deals with SINGLE scan line at a time, it convert 8

	       pixels in each iteration */

	    __asm__ __volatile__ (

	/* load data for start of next scan line */

		     "movd (%2, %0), %%mm0;" /* Load 4 Cb 00 00 00 00 u3 u2 u1 u0 */

		     "movd (%3, %0), %%mm1;" /* Load 4 Cr 00 00 00 00 v3 v2 v1 v0 */

		     "movq (%5, %0, 2), %%mm6;" /* Load 8  Y Y7 Y6 Y5 Y4 Y3 Y2 Y1 Y0 */

//		    ".balign 16			\n\t"

		    "1:				\n\t"

YUV2RGB

		     /* convert RGB plane to RGB packed format,

			mm0 -> B, mm1 -> R, mm2 -> G, mm3 -> 0,

			mm4 -> GB, mm5 -> AR pixel 4-7,

			mm6 -> GB, mm7 -> AR pixel 0-3 */

		     "pxor %%mm3, %%mm3;" /* zero mm3 */



		     "movq %%mm0, %%mm6;" /* B7 B6 B5 B4 B3 B2 B1 B0 */

		     "movq %%mm1, %%mm7;" /* R7 R6 R5 R4 R3 R2 R1 R0 */



		     "movq %%mm0, %%mm4;" /* B7 B6 B5 B4 B3 B2 B1 B0 */

		     "movq %%mm1, %%mm5;" /* R7 R6 R5 R4 R3 R2 R1 R0 */



		     "punpcklbw %%mm2, %%mm6;" /* G3 B3 G2 B2 G1 B1 G0 B0 */

		     "punpcklbw %%mm3, %%mm7;" /* 00 R3 00 R2 00 R1 00 R0 */



		     "punpcklwd %%mm7, %%mm6;" /* 00 R1 B1 G1 00 R0 B0 G0 */

		     MOVNTQ " %%mm6, (%1);" /* Store ARGB1 ARGB0 */



		     "movq %%mm0, %%mm6;" /* B7 B6 B5 B4 B3 B2 B1 B0 */

		     "punpcklbw %%mm2, %%mm6;" /* G3 B3 G2 B2 G1 B1 G0 B0 */



		     "punpckhwd %%mm7, %%mm6;" /* 00 R3 G3 B3 00 R2 B3 G2 */

		     MOVNTQ " %%mm6, 8 (%1);" /* Store ARGB3 ARGB2 */



		     "punpckhbw %%mm2, %%mm4;" /* G7 B7 G6 B6 G5 B5 G4 B4 */

		     "punpckhbw %%mm3, %%mm5;" /* 00 R7 00 R6 00 R5 00 R4 */



		     "punpcklwd %%mm5, %%mm4;" /* 00 R5 B5 G5 00 R4 B4 G4 */

		     MOVNTQ " %%mm4, 16 (%1);" /* Store ARGB5 ARGB4 */



		     "movq %%mm0, %%mm4;" /* B7 B6 B5 B4 B3 B2 B1 B0 */

		     "punpckhbw %%mm2, %%mm4;" /* G7 B7 G6 B6 G5 B5 G4 B4 */



		     "punpckhwd %%mm5, %%mm4;" /* 00 R7 G7 B7 00 R6 B6 G6 */

		     MOVNTQ " %%mm4, 24 (%1);" /* Store ARGB7 ARGB6 */



		     "movd 4 (%2, %0), %%mm0;" /* Load 4 Cb 00 00 00 00 u3 u2 u1 u0 */

		     "movd 4 (%3, %0), %%mm1;" /* Load 4 Cr 00 00 00 00 v3 v2 v1 v0 */



		     "pxor %%mm4, %%mm4;" /* zero mm4 */

		     "movq 8 (%5, %0, 2), %%mm6;" /* Load 8 Y Y7 Y6 Y5 Y4 Y3 Y2 Y1 Y0 */



		     "add $32, %1			\n\t"

		     "add $4, %0			\n\t"

		     " js 1b				\n\t"



		     : "+r" (index), "+r" (_image)

		     : "r" (_pu - index), "r" (_pv - index), "r"(&c->redDither), "r" (_py - 2*index)

		     );

    }



    __asm__ __volatile__ (EMMS);

    return srcSliceH;

}

static int latm_decode_audio_specific_config(struct LATMContext *latmctx,

                                             GetBitContext *gb, int asclen)

{

    AACContext *ac        = &latmctx->aac_ctx;

    AVCodecContext *avctx = ac->avctx;

    MPEG4AudioConfig m4ac = {0};

    int config_start_bit  = get_bits_count(gb);

    int sync_extension    = 0;

    int bits_consumed, esize;



    if (asclen) {

        sync_extension = 1;

        asclen         = FFMIN(asclen, get_bits_left(gb));

    } else

        asclen         = get_bits_left(gb);



    if (config_start_bit % 8) {

        av_log_missing_feature(latmctx->aac_ctx.avctx, "audio specific "

                               "config not byte aligned.\n", 1);


    }



    bits_consumed = decode_audio_specific_config(NULL, avctx, &m4ac,

                                         gb->buffer + (config_start_bit / 8),

                                         asclen, sync_extension);



    if (bits_consumed < 0)




    if (ac->m4ac.sample_rate != m4ac.sample_rate ||

        ac->m4ac.chan_config != m4ac.chan_config) {



        av_log(avctx, AV_LOG_INFO, "audio config changed\n");

        latmctx->initialized = 0;



        esize = (bits_consumed+7) / 8;



        if (avctx->extradata_size < esize) {

            av_free(avctx->extradata);

            avctx->extradata = av_malloc(esize + FF_INPUT_BUFFER_PADDING_SIZE);

            if (!avctx->extradata)

                return AVERROR(ENOMEM);

        }



        avctx->extradata_size = esize;

        memcpy(avctx->extradata, gb->buffer + (config_start_bit/8), esize);

        memset(avctx->extradata+esize, 0, FF_INPUT_BUFFER_PADDING_SIZE);

    }

    skip_bits_long(gb, bits_consumed);



    return bits_consumed;

}

