static inline int bidir_refine(MpegEncContext * s, int mb_x, int mb_y)

{

    MotionEstContext * const c= &s->me;

    const int mot_stride = s->mb_stride;

    const int xy = mb_y *mot_stride + mb_x;

    int fbmin;

    int pred_fx= s->b_bidir_forw_mv_table[xy-1][0];

    int pred_fy= s->b_bidir_forw_mv_table[xy-1][1];

    int pred_bx= s->b_bidir_back_mv_table[xy-1][0];

    int pred_by= s->b_bidir_back_mv_table[xy-1][1];

    int motion_fx= s->b_bidir_forw_mv_table[xy][0]= s->b_forw_mv_table[xy][0];

    int motion_fy= s->b_bidir_forw_mv_table[xy][1]= s->b_forw_mv_table[xy][1];

    int motion_bx= s->b_bidir_back_mv_table[xy][0]= s->b_back_mv_table[xy][0];

    int motion_by= s->b_bidir_back_mv_table[xy][1]= s->b_back_mv_table[xy][1];

    const int flags= c->sub_flags;

    const int qpel= flags&FLAG_QPEL;

    const int shift= 1+qpel;

    const int xmin= c->xmin<<shift;

    const int ymin= c->ymin<<shift;

    const int xmax= c->xmax<<shift;

    const int ymax= c->ymax<<shift;

    uint8_t map[8][8][8][8];



    memset(map,0,sizeof(map));

#define BIDIR_MAP(fx,fy,bx,by) \

    map[(motion_fx+fx)&7][(motion_fy+fy)&7][(motion_bx+bx)&7][(motion_by+by)&7]

    BIDIR_MAP(0,0,0,0) = 1;



    fbmin= check_bidir_mv(s, motion_fx, motion_fy,

                          motion_bx, motion_by,

                          pred_fx, pred_fy,

                          pred_bx, pred_by,

                          0, 16);



    if(s->avctx->bidir_refine){

        int score, end;

#define CHECK_BIDIR(fx,fy,bx,by)\

    if( !BIDIR_MAP(fx,fy,bx,by)\

       &&(fx<=0 || motion_fx+fx<=xmax) && (fy<=0 || motion_fy+fy<=ymax) && (bx<=0 || motion_bx+bx<=xmax) && (by<=0 || motion_by+by<=ymax)\

       &&(fx>=0 || motion_fx+fx>=xmin) && (fy>=0 || motion_fy+fy>=ymin) && (bx>=0 || motion_bx+bx>=xmin) && (by>=0 || motion_by+by>=ymin)){\

        BIDIR_MAP(fx,fy,bx,by) = 1;\

        score= check_bidir_mv(s, motion_fx+fx, motion_fy+fy, motion_bx+bx, motion_by+by, pred_fx, pred_fy, pred_bx, pred_by, 0, 16);\

        if(score < fbmin){\

            fbmin= score;\

            motion_fx+=fx;\

            motion_fy+=fy;\

            motion_bx+=bx;\

            motion_by+=by;\

            end=0;\

        }\

    }

#define CHECK_BIDIR2(a,b,c,d)\

CHECK_BIDIR(a,b,c,d)\

CHECK_BIDIR(-a,-b,-c,-d)



#define CHECK_BIDIRR(a,b,c,d)\

CHECK_BIDIR2(a,b,c,d)\

CHECK_BIDIR2(b,c,d,a)\

CHECK_BIDIR2(c,d,a,b)\

CHECK_BIDIR2(d,a,b,c)



        do{

            end=1;



            CHECK_BIDIRR( 0, 0, 0, 1)

            if(s->avctx->bidir_refine > 1){

                CHECK_BIDIRR( 0, 0, 1, 1)

                CHECK_BIDIR2( 0, 1, 0, 1)

                CHECK_BIDIR2( 1, 0, 1, 0)

                CHECK_BIDIRR( 0, 0,-1, 1)

                CHECK_BIDIR2( 0,-1, 0, 1)

                CHECK_BIDIR2(-1, 0, 1, 0)

                if(s->avctx->bidir_refine > 2){

                    CHECK_BIDIRR( 0, 1, 1, 1)

                    CHECK_BIDIRR( 0,-1, 1, 1)

                    CHECK_BIDIRR( 0, 1,-1, 1)

                    CHECK_BIDIRR( 0, 1, 1,-1)

                    if(s->avctx->bidir_refine > 3){

                        CHECK_BIDIR2( 1, 1, 1, 1)

                        CHECK_BIDIRR( 1, 1, 1,-1)

                        CHECK_BIDIR2( 1, 1,-1,-1)

                        CHECK_BIDIR2( 1,-1,-1, 1)

                        CHECK_BIDIR2( 1,-1, 1,-1)

                    }

                }

            }

        }while(!end);

    }



    s->b_bidir_forw_mv_table[xy][0]= motion_fx;

    s->b_bidir_forw_mv_table[xy][1]= motion_fy;

    s->b_bidir_back_mv_table[xy][0]= motion_bx;

    s->b_bidir_back_mv_table[xy][1]= motion_by;



    return fbmin;

}

int ff_h264_execute_decode_slices(H264Context *h, unsigned context_count)

{

    AVCodecContext *const avctx = h->avctx;

    H264Context *hx;

    int i;



    if (h->mb_y >= h->mb_height) {

        av_log(h->avctx, AV_LOG_ERROR,

               "Input contains more MB rows than the frame height.\n");

        return AVERROR_INVALIDDATA;

    }



    if (h->avctx->hwaccel)

        return 0;

    if (context_count == 1) {

        return decode_slice(avctx, &h);

    } else {

        for (i = 1; i < context_count; i++) {

            hx                 = h->thread_context[i];

            hx->er.error_count = 0;

        }



        avctx->execute(avctx, decode_slice, h->thread_context,

                       NULL, context_count, sizeof(void *));



        /* pull back stuff from slices to master context */

        hx                   = h->thread_context[context_count - 1];

        h->mb_x              = hx->mb_x;

        h->mb_y              = hx->mb_y;

        h->droppable         = hx->droppable;

        h->picture_structure = hx->picture_structure;

        for (i = 1; i < context_count; i++)

            h->er.error_count += h->thread_context[i]->er.error_count;

    }



    return 0;

}

static int open_next_file(AVFormatContext *avf)

{

    ConcatContext *cat = avf->priv_data;

    unsigned fileno = cat->cur_file - cat->files;



    if (cat->cur_file->duration == AV_NOPTS_VALUE)

        cat->cur_file->duration = cat->avf->duration - (cat->cur_file->file_inpoint - cat->cur_file->file_start_time);



    if (++fileno >= cat->nb_files) {

        cat->eof = 1;

        return AVERROR_EOF;

    }

    return open_file(avf, fileno);

}

int ff_h263_decode_frame(AVCodecContext *avctx, 

                             void *data, int *data_size,

                             UINT8 *buf, int buf_size)

{

    MpegEncContext *s = avctx->priv_data;

    int ret,i;

    AVFrame *pict = data; 

    float new_aspect;



#ifdef PRINT_FRAME_TIME

uint64_t time= rdtsc();

#endif

#ifdef DEBUG

    printf("*****frame %d size=%d\n", avctx->frame_number, buf_size);

    printf("bytes=%x %x %x %x\n", buf[0], buf[1], buf[2], buf[3]);

#endif

    s->flags= avctx->flags;



    *data_size = 0;



   /* no supplementary picture */

    if (buf_size == 0) {

        return 0;

    }



    if(s->flags&CODEC_FLAG_TRUNCATED){

        int next;

        ParseContext *pc= &s->parse_context;



        pc->last_index= pc->index;



        if(s->codec_id==CODEC_ID_MPEG4){

            next= mpeg4_find_frame_end(s, buf, buf_size);

        }else{

            fprintf(stderr, "this codec doesnt support truncated bitstreams\n");

            return -1;

        }

        if(next==-1){

            if(buf_size + FF_INPUT_BUFFER_PADDING_SIZE + pc->index > pc->buffer_size){

                pc->buffer_size= buf_size + pc->index + 10*1024;

                pc->buffer= realloc(pc->buffer, pc->buffer_size);

            }



            memcpy(&pc->buffer[pc->index], buf, buf_size);

            pc->index += buf_size;

            return buf_size;

        }



        if(pc->index){

            if(next + FF_INPUT_BUFFER_PADDING_SIZE + pc->index > pc->buffer_size){

                pc->buffer_size= next + pc->index + 10*1024;

                pc->buffer= realloc(pc->buffer, pc->buffer_size);

            }



            memcpy(&pc->buffer[pc->index], buf, next + FF_INPUT_BUFFER_PADDING_SIZE );

            pc->index = 0;

            buf= pc->buffer;

            buf_size= pc->last_index + next;

        }

    }



retry:



    if(s->bitstream_buffer_size && buf_size<20){ //divx 5.01+ frame reorder

        init_get_bits(&s->gb, s->bitstream_buffer, s->bitstream_buffer_size);

    }else

        init_get_bits(&s->gb, buf, buf_size);

    s->bitstream_buffer_size=0;



    if (!s->context_initialized) {

        if (MPV_common_init(s) < 0) //we need the idct permutaton for reading a custom matrix

            return -1;

    }



    /* let's go :-) */

    if (s->msmpeg4_version==5) {

        ret= ff_wmv2_decode_picture_header(s);

    } else if (s->msmpeg4_version) {

        ret = msmpeg4_decode_picture_header(s);

    } else if (s->h263_pred) {

        if(s->avctx->extradata_size && s->picture_number==0){

            GetBitContext gb;



            init_get_bits(&gb, s->avctx->extradata, s->avctx->extradata_size);

            ret = ff_mpeg4_decode_picture_header(s, &gb);

        }

        ret = ff_mpeg4_decode_picture_header(s, &s->gb);



        if(s->flags& CODEC_FLAG_LOW_DELAY)

            s->low_delay=1;

    } else if (s->h263_intel) {

        ret = intel_h263_decode_picture_header(s);

    } else {

        ret = h263_decode_picture_header(s);

    }

    avctx->has_b_frames= !s->low_delay;



    if(s->workaround_bugs&FF_BUG_AUTODETECT){

        if(s->padding_bug_score > -2 && !s->data_partitioning)

            s->workaround_bugs |=  FF_BUG_NO_PADDING;

        else

            s->workaround_bugs &= ~FF_BUG_NO_PADDING;



        if(s->avctx->fourcc == ff_get_fourcc("XVIX")) 

            s->workaround_bugs|= FF_BUG_XVID_ILACE;

#if 0

        if(s->avctx->fourcc == ff_get_fourcc("MP4S")) 

            s->workaround_bugs|= FF_BUG_AC_VLC;



        if(s->avctx->fourcc == ff_get_fourcc("M4S2")) 

            s->workaround_bugs|= FF_BUG_AC_VLC;

#endif

        if(s->avctx->fourcc == ff_get_fourcc("UMP4")){

            s->workaround_bugs|= FF_BUG_UMP4;

            s->workaround_bugs|= FF_BUG_AC_VLC;

        }



        if(s->divx_version){

            s->workaround_bugs|= FF_BUG_QPEL_CHROMA;

        }



        if(s->avctx->fourcc == ff_get_fourcc("XVID") && s->xvid_build==0)

            s->workaround_bugs|= FF_BUG_QPEL_CHROMA;



        if(s->avctx->fourcc == ff_get_fourcc("XVID") && s->xvid_build==0)

            s->padding_bug_score= 256*256*256*64;



        if(s->xvid_build && s->xvid_build<=3)

            s->padding_bug_score= 256*256*256*64;



        if(s->xvid_build && s->xvid_build<=1)

