static int parse_ifo_palette(DVDSubContext *ctx, char *p)

{

    FILE *ifo;

    char ifostr[12];

    uint32_t sp_pgci, pgci, off_pgc, pgc;

    uint8_t r, g, b, yuv[65], *buf;

    int i, y, cb, cr, r_add, g_add, b_add;

    int ret = 0;

    const uint8_t *cm = ff_crop_tab + MAX_NEG_CROP;



    ctx->has_palette = 0;

    if ((ifo = fopen(p, "r")) == NULL) {

        av_log(ctx, AV_LOG_WARNING, "Unable to open IFO file \"%s\": %s\n", p, strerror(errno));

        return AVERROR_EOF;

    }

    if (fread(ifostr, 12, 1, ifo) != 1 || memcmp(ifostr, "DVDVIDEO-VTS", 12)) {

        av_log(ctx, AV_LOG_WARNING, "\"%s\" is not a proper IFO file\n", p);

        ret = AVERROR_INVALIDDATA;

        goto end;

    }

    fseek(ifo, 0xCC, SEEK_SET);

    if (fread(&sp_pgci, 4, 1, ifo) == 1) {

        pgci = av_be2ne32(sp_pgci) * 2048;

        fseek(ifo, pgci + 0x0C, SEEK_SET);

        if (fread(&off_pgc, 4, 1, ifo) == 1) {

            pgc = pgci + av_be2ne32(off_pgc);

            fseek(ifo, pgc + 0xA4, SEEK_SET);

            if (fread(yuv, 64, 1, ifo) == 1) {

                buf = yuv;

                for(i=0; i<16; i++) {

                    y  = *++buf;

                    cr = *++buf;

                    cb = *++buf;

                    YUV_TO_RGB1_CCIR(cb, cr);

                    YUV_TO_RGB2_CCIR(r, g, b, y);

                    ctx->palette[i] = (r << 16) + (g << 8) + b;

                    buf++;

                }

                ctx->has_palette = 1;

            }

        }

    }

    if (ctx->has_palette == 0) {

        av_log(ctx, AV_LOG_WARNING, "Failed to read palette from IFO file \"%s\"\n", p);

        ret = AVERROR_INVALIDDATA;

    }

end:

    fclose(ifo);

    return ret;

}

static void lsp2polyf(const double *lsp, double *f, int lp_half_order)

{

    int i, j;



    f[0] = 1.0;

    f[1] = -2 * lsp[0];

    lsp -= 2;

    for(i=2; i<=lp_half_order; i++)

    {

        double val = -2 * lsp[2*i];

        f[i] = val * f[i-1] + 2*f[i-2];

        for(j=i-1; j>1; j--)

            f[j] += f[j-1] * val + f[j-2];

        f[1] += val;

    }

}

static void do_audio_out(AVFormatContext *s,

                         AVOutputStream *ost,

                         AVInputStream *ist,

                         unsigned char *buf, int size)

{

    uint8_t *buftmp;

    int64_t audio_out_size, audio_buf_size;

    int64_t allocated_for_size= size;



    int size_out, frame_bytes, ret;

    AVCodecContext *enc= ost->st->codec;

    AVCodecContext *dec= ist->st->codec;

    int osize= av_get_bits_per_sample_format(enc->sample_fmt)/8;

    int isize= av_get_bits_per_sample_format(dec->sample_fmt)/8;

    const int coded_bps = av_get_bits_per_sample(enc->codec->id);



need_realloc:

    audio_buf_size= (allocated_for_size + isize*dec->channels - 1) / (isize*dec->channels);

    audio_buf_size= (audio_buf_size*enc->sample_rate + dec->sample_rate) / dec->sample_rate;

    audio_buf_size= audio_buf_size*2 + 10000; //safety factors for the deprecated resampling API

    audio_buf_size= FFMAX(audio_buf_size, enc->frame_size);

    audio_buf_size*= osize*enc->channels;



    audio_out_size= FFMAX(audio_buf_size, enc->frame_size * osize * enc->channels);

    if(coded_bps > 8*osize)

        audio_out_size= audio_out_size * coded_bps / (8*osize);

    audio_out_size += FF_MIN_BUFFER_SIZE;



    if(audio_out_size > INT_MAX || audio_buf_size > INT_MAX){

        fprintf(stderr, "Buffer sizes too large\n");

        ffmpeg_exit(1);

    }



    av_fast_malloc(&audio_buf, &allocated_audio_buf_size, audio_buf_size);

    av_fast_malloc(&audio_out, &allocated_audio_out_size, audio_out_size);

    if (!audio_buf || !audio_out){

        fprintf(stderr, "Out of memory in do_audio_out\n");

        ffmpeg_exit(1);

    }



    if (enc->channels != dec->channels)

        ost->audio_resample = 1;



    if (ost->audio_resample && !ost->resample) {

        if (dec->sample_fmt != SAMPLE_FMT_S16)

            fprintf(stderr, "Warning, using s16 intermediate sample format for resampling\n");

        ost->resample = av_audio_resample_init(enc->channels,    dec->channels,

                                               enc->sample_rate, dec->sample_rate,

                                               enc->sample_fmt,  dec->sample_fmt,

                                               16, 10, 0, 0.8);

        if (!ost->resample) {

            fprintf(stderr, "Can not resample %d channels @ %d Hz to %d channels @ %d Hz\n",

                    dec->channels, dec->sample_rate,

                    enc->channels, enc->sample_rate);

            ffmpeg_exit(1);

        }

    }



#define MAKE_SFMT_PAIR(a,b) ((a)+SAMPLE_FMT_NB*(b))

    if (!ost->audio_resample && dec->sample_fmt!=enc->sample_fmt &&

        MAKE_SFMT_PAIR(enc->sample_fmt,dec->sample_fmt)!=ost->reformat_pair) {

        if (ost->reformat_ctx)

            av_audio_convert_free(ost->reformat_ctx);

        ost->reformat_ctx = av_audio_convert_alloc(enc->sample_fmt, 1,

                                                   dec->sample_fmt, 1, NULL, 0);

        if (!ost->reformat_ctx) {

            fprintf(stderr, "Cannot convert %s sample format to %s sample format\n",

                avcodec_get_sample_fmt_name(dec->sample_fmt),

                avcodec_get_sample_fmt_name(enc->sample_fmt));

            ffmpeg_exit(1);

        }

        ost->reformat_pair=MAKE_SFMT_PAIR(enc->sample_fmt,dec->sample_fmt);

    }



    if(audio_sync_method){

        double delta = get_sync_ipts(ost) * enc->sample_rate - ost->sync_opts

                - av_fifo_size(ost->fifo)/(enc->channels * 2);

        double idelta= delta*dec->sample_rate / enc->sample_rate;

        int byte_delta= ((int)idelta)*2*dec->channels;



        //FIXME resample delay

        if(fabs(delta) > 50){

            if(ist->is_start || fabs(delta) > audio_drift_threshold*enc->sample_rate){

                if(byte_delta < 0){

                    byte_delta= FFMAX(byte_delta, -size);

                    size += byte_delta;

                    buf  -= byte_delta;

                    if(verbose > 2)

                        fprintf(stderr, "discarding %d audio samples\n", (int)-delta);

                    if(!size)

                        return;

                    ist->is_start=0;

                }else{

                    static uint8_t *input_tmp= NULL;

                    input_tmp= av_realloc(input_tmp, byte_delta + size);



                    if(byte_delta > allocated_for_size - size){

                        allocated_for_size= byte_delta + (int64_t)size;

                        goto need_realloc;

                    }

                    ist->is_start=0;



                    memset(input_tmp, 0, byte_delta);

                    memcpy(input_tmp + byte_delta, buf, size);

                    buf= input_tmp;

                    size += byte_delta;

                    if(verbose > 2)

                        fprintf(stderr, "adding %d audio samples of silence\n", (int)delta);

                }

            }else if(audio_sync_method>1){

                int comp= av_clip(delta, -audio_sync_method, audio_sync_method);

                assert(ost->audio_resample);

                if(verbose > 2)

                    fprintf(stderr, "compensating audio timestamp drift:%f compensation:%d in:%d\n", delta, comp, enc->sample_rate);

//                fprintf(stderr, "drift:%f len:%d opts:%"PRId64" ipts:%"PRId64" fifo:%d\n", delta, -1, ost->sync_opts, (int64_t)(get_sync_ipts(ost) * enc->sample_rate), av_fifo_size(ost->fifo)/(ost->st->codec->channels * 2));

                av_resample_compensate(*(struct AVResampleContext**)ost->resample, comp, enc->sample_rate);

            }

        }

    }else

        ost->sync_opts= lrintf(get_sync_ipts(ost) * enc->sample_rate)

                        - av_fifo_size(ost->fifo)/(enc->channels * 2); //FIXME wrong



    if (ost->audio_resample) {

        buftmp = audio_buf;

        size_out = audio_resample(ost->resample,

                                  (short *)buftmp, (short *)buf,

                                  size / (dec->channels * isize));

        size_out = size_out * enc->channels * osize;

    } else {

        buftmp = buf;

        size_out = size;

    }



    if (!ost->audio_resample && dec->sample_fmt!=enc->sample_fmt) {

        const void *ibuf[6]= {buftmp};

        void *obuf[6]= {audio_buf};

        int istride[6]= {isize};

        int ostride[6]= {osize};

        int len= size_out/istride[0];

        if (av_audio_convert(ost->reformat_ctx, obuf, ostride, ibuf, istride, len)<0) {

            printf("av_audio_convert() failed\n");

            if (exit_on_error)

                ffmpeg_exit(1);

            return;

        }

        buftmp = audio_buf;

        size_out = len*osize;

    }



    /* now encode as many frames as possible */

    if (enc->frame_size > 1) {

        /* output resampled raw samples */

        if (av_fifo_realloc2(ost->fifo, av_fifo_size(ost->fifo) + size_out) < 0) {

            fprintf(stderr, "av_fifo_realloc2() failed\n");

            ffmpeg_exit(1);

        }

        av_fifo_generic_write(ost->fifo, buftmp, size_out, NULL);



        frame_bytes = enc->frame_size * osize * enc->channels;



        while (av_fifo_size(ost->fifo) >= frame_bytes) {

            AVPacket pkt;

            av_init_packet(&pkt);



            av_fifo_generic_read(ost->fifo, audio_buf, frame_bytes, NULL);



            //FIXME pass ost->sync_opts as AVFrame.pts in avcodec_encode_audio()



            ret = avcodec_encode_audio(enc, audio_out, audio_out_size,

                                       (short *)audio_buf);

            if (ret < 0) {

                fprintf(stderr, "Audio encoding failed\n");

                ffmpeg_exit(1);

            }

            audio_size += ret;

            pkt.stream_index= ost->index;

            pkt.data= audio_out;

            pkt.size= ret;

            if(enc->coded_frame && enc->coded_frame->pts != AV_NOPTS_VALUE)

                pkt.pts= av_rescale_q(enc->coded_frame->pts, enc->time_base, ost->st->time_base);

            pkt.flags |= AV_PKT_FLAG_KEY;

            write_frame(s, &pkt, enc, bitstream_filters[ost->file_index][pkt.stream_index]);



            ost->sync_opts += enc->frame_size;

        }

    } else {

        AVPacket pkt;

        av_init_packet(&pkt);



        ost->sync_opts += size_out / (osize * enc->channels);



        /* output a pcm frame */

        /* determine the size of the coded buffer */

        size_out /= osize;

        if (coded_bps)

            size_out = size_out*coded_bps/8;



        if(size_out > audio_out_size){

            fprintf(stderr, "Internal error, buffer size too small\n");

            ffmpeg_exit(1);

        }



        //FIXME pass ost->sync_opts as AVFrame.pts in avcodec_encode_audio()

        ret = avcodec_encode_audio(enc, audio_out, size_out,

                                   (short *)buftmp);

        if (ret < 0) {

            fprintf(stderr, "Audio encoding failed\n");

            ffmpeg_exit(1);

        }

        audio_size += ret;

        pkt.stream_index= ost->index;

        pkt.data= audio_out;

        pkt.size= ret;

        if(enc->coded_frame && enc->coded_frame->pts != AV_NOPTS_VALUE)

            pkt.pts= av_rescale_q(enc->coded_frame->pts, enc->time_base, ost->st->time_base);

        pkt.flags |= AV_PKT_FLAG_KEY;

        write_frame(s, &pkt, enc, bitstream_filters[ost->file_index][pkt.stream_index]);

    }

}

static int rv20_decode_picture_header(MpegEncContext *s)

{

    int seq, mb_pos, i;



    if(s->avctx->sub_id == 0x30202002 || s->avctx->sub_id == 0x30203002){

        if (get_bits(&s->gb, 3)){

            av_log(s->avctx, AV_LOG_ERROR, "unknown triplet set\n");

            return -1;

        } 

    }   



    i= get_bits(&s->gb, 2);

    switch(i){

    case 0: s->pict_type= I_TYPE; break;

    case 1: s->pict_type= I_TYPE; break; //hmm ...

    case 2: s->pict_type= P_TYPE; break;

    case 3: s->pict_type= B_TYPE; break;

    default: 

        av_log(s->avctx, AV_LOG_ERROR, "unknown frame type\n");

        return -1;

    }



    if (get_bits(&s->gb, 1)){

        av_log(s->avctx, AV_LOG_ERROR, "unknown bit set\n");

        return -1;

    }



    s->qscale = get_bits(&s->gb, 5);

    if(s->qscale==0){

        av_log(s->avctx, AV_LOG_ERROR, "error, qscale:0\n");

        return -1;

    }

    if(s->avctx->sub_id == 0x30203002){

        if (get_bits(&s->gb, 1)){

            av_log(s->avctx, AV_LOG_ERROR, "unknown bit2 set\n");

            return -1;

        }

    }



    if(s->avctx->has_b_frames){

        if (get_bits(&s->gb, 1)){

            av_log(s->avctx, AV_LOG_ERROR, "unknown bit3 set\n");

            return -1;

        }

        seq= get_bits(&s->gb, 15);

    }else

        seq= get_bits(&s->gb, 8)*128;

//printf("%d\n", seq);

    seq |= s->time &~0x7FFF;

    if(seq - s->time >  0x4000) seq -= 0x8000;

    if(seq - s->time < -0x4000) seq += 0x8000;

    if(seq != s->time){  

        if(s->pict_type!=B_TYPE){

            s->time= seq;

            s->pp_time= s->time - s->last_non_b_time;

            s->last_non_b_time= s->time;

        }else{

            s->time= seq;

            s->pb_time= s->pp_time - (s->last_non_b_time - s->time);

            if(s->pp_time <=s->pb_time || s->pp_time <= s->pp_time - s->pb_time || s->pp_time<=0){

                printf("messed up order, seeking?, skiping current b frame\n");

                return FRAME_SKIPED;

            }

        }

    }

//    printf("%d %d %d %d %d\n", seq, (int)s->time, (int)s->last_non_b_time, s->pp_time, s->pb_time);



    mb_pos= ff_h263_decode_mba(s);

    s->no_rounding= get_bits1(&s->gb);



    s->f_code = 1;

    s->unrestricted_mv = 1;

    s->h263_aic= s->pict_type == I_TYPE;

//    s->alt_inter_vlc=1;

//    s->obmc=1;

//    s->umvplus=1;

    s->modified_quant=1;

    s->loop_filter=1;



    if(s->avctx->debug & FF_DEBUG_PICT_INFO){

            av_log(s->avctx, AV_LOG_INFO, "num:%5d x:%2d y:%2d type:%d qscale:%2d rnd:%d\n", 

                   seq, s->mb_x, s->mb_y, s->pict_type, s->qscale, s->no_rounding);

    }



    assert(s->pict_type != B_TYPE || !s->low_delay);



    return s->mb_width*s->mb_height - mb_pos;

}

static av_cold int concat_open(URLContext *h, const char *uri, int flags)

{

    char *node_uri = NULL;

    int err = 0;

    int64_t size;

    size_t  len, i;

    URLContext *uc;

    struct concat_data  *data = h->priv_data;

    struct concat_nodes *nodes;



    av_strstart(uri, "concat:", &uri);



    for (i = 0, len = 1; uri[i]; i++)

        if (uri[i] == *AV_CAT_SEPARATOR)

            /* integer overflow */

            if (++len == UINT_MAX / sizeof(*nodes)) {

                av_freep(&h->priv_data);

                return AVERROR(ENAMETOOLONG);

            }



    if (!(nodes = av_malloc(sizeof(*nodes) * len))) {

        return AVERROR(ENOMEM);

    } else

        data->nodes = nodes;



    /* handle input */

    if (!*uri)

        err = AVERROR(ENOENT);

    for (i = 0; *uri; i++) {

        /* parsing uri */

        len = strcspn(uri, AV_CAT_SEPARATOR);

        if ((err = av_reallocp(&node_uri, len + 1)) < 0)

            break;

        av_strlcpy(node_uri, uri, len+1);

        uri += len + strspn(uri+len, AV_CAT_SEPARATOR);



        /* creating URLContext */

        if ((err = ffurl_open(&uc, node_uri, flags,

                              &h->interrupt_callback, NULL)) < 0)

            break;



        /* creating size */

        if ((size = ffurl_size(uc)) < 0) {

            ffurl_close(uc);

            err = AVERROR(ENOSYS);

            break;

        }



        /* assembling */

        nodes[i].uc   = uc;

        nodes[i].size = size;

    }

    av_free(node_uri);

    data->length = i;



    if (err < 0)

        concat_close(h);

    else if ((err = av_reallocp(&nodes, data->length * sizeof(*nodes))) < 0)

        concat_close(h);

    else

        data->nodes = nodes;

    return err;

}

static int encode_frame(AVCodecContext *avctx, AVPacket *avpkt,
                        const AVFrame *frame, int *got_packet_ptr)
{
    DCAEncContext *c = avctx->priv_data;
    const int32_t *samples;
    int ret, i;
    if ((ret = ff_alloc_packet2(avctx, avpkt, c->frame_size , 0)) < 0)
        return ret;
    samples = (const int32_t *)frame->data[0];
    subband_transform(c, samples);
    if (c->lfe_channel)
        lfe_downsample(c, samples);
    calc_masking(c, samples);
    find_peaks(c);
    assign_bits(c);
    calc_scales(c);
    quantize_all(c);
    shift_history(c, samples);
    init_put_bits(&c->pb, avpkt->data, avpkt->size);
    put_frame_header(c);
    put_primary_audio_header(c);
    for (i = 0; i < SUBFRAMES; i++)
        put_subframe(c, i);
    flush_put_bits(&c->pb);
    avpkt->pts      = frame->pts;
    avpkt->duration = ff_samples_to_time_base(avctx, frame->nb_samples);
    avpkt->size     = c->frame_size + 1;
    *got_packet_ptr = 1;
    return 0;
}

void ff_subblock_synthesis(RA144Context *ractx, const int16_t *lpc_coefs,

                           int cba_idx, int cb1_idx, int cb2_idx,

                           int gval, int gain)

{

    int16_t *block;

    int m[3];



    if (cba_idx) {

        cba_idx += BLOCKSIZE/2 - 1;

        ff_copy_and_dup(ractx->buffer_a, ractx->adapt_cb, cba_idx);

        m[0] = (ff_irms(&ractx->adsp, ractx->buffer_a) * gval) >> 12;

    } else {

        m[0] = 0;

    }

    m[1] = (ff_cb1_base[cb1_idx] * gval) >> 8;

    m[2] = (ff_cb2_base[cb2_idx] * gval) >> 8;

    memmove(ractx->adapt_cb, ractx->adapt_cb + BLOCKSIZE,

            (BUFFERSIZE - BLOCKSIZE) * sizeof(*ractx->adapt_cb));



    block = ractx->adapt_cb + BUFFERSIZE - BLOCKSIZE;



    add_wav(block, gain, cba_idx, m, cba_idx? ractx->buffer_a: NULL,

            ff_cb1_vects[cb1_idx], ff_cb2_vects[cb2_idx]);



    memcpy(ractx->curr_sblock, ractx->curr_sblock + BLOCKSIZE,

           LPC_ORDER*sizeof(*ractx->curr_sblock));



    if (ff_celp_lp_synthesis_filter(ractx->curr_sblock + LPC_ORDER, lpc_coefs,

                                    block, BLOCKSIZE, LPC_ORDER, 1, 0, 0xfff))

        memset(ractx->curr_sblock, 0, (LPC_ORDER+BLOCKSIZE)*sizeof(*ractx->curr_sblock));

}

static void close_file(OutputStream *os)

{

    int64_t pos = avio_tell(os->out);

    avio_seek(os->out, 0, SEEK_SET);

    avio_wb32(os->out, pos);

    avio_flush(os->out);

    avio_close(os->out);

    os->out = NULL;

}

static int g726_encode_frame(AVCodecContext *avctx, AVPacket *avpkt,

                             const AVFrame *frame, int *got_packet_ptr)

{

    G726Context *c = avctx->priv_data;

    const int16_t *samples = (const int16_t *)frame->data[0];

    PutBitContext pb;

    int i, ret, out_size;



    out_size = (frame->nb_samples * c->code_size + 7) / 8;

    if ((ret = ff_alloc_packet2(avctx, avpkt, out_size)))

        return ret;

    init_put_bits(&pb, avpkt->data, avpkt->size);



    for (i = 0; i < frame->nb_samples; i++)

        put_bits(&pb, c->code_size, g726_encode(c, *samples++));



    flush_put_bits(&pb);



    avpkt->size = out_size;

    *got_packet_ptr = 1;

    return 0;

}

static void read_apic(AVFormatContext *s, AVIOContext *pb, int taglen, char *tag, ID3v2ExtraMeta **extra_meta)

{

    int enc, pic_type;

    char             mimetype[64];

    const CodecMime     *mime = ff_id3v2_mime_tags;

    enum AVCodecID           id = AV_CODEC_ID_NONE;

    ID3v2ExtraMetaAPIC  *apic = NULL;

    ID3v2ExtraMeta *new_extra = NULL;

    int64_t               end = avio_tell(pb) + taglen;



    if (taglen <= 4)

        goto fail;



    new_extra = av_mallocz(sizeof(*new_extra));

    apic      = av_mallocz(sizeof(*apic));

    if (!new_extra || !apic)

        goto fail;



    enc = avio_r8(pb);

    taglen--;



    /* mimetype */

    taglen -= avio_get_str(pb, taglen, mimetype, sizeof(mimetype));

    while (mime->id != AV_CODEC_ID_NONE) {

        if (!av_strncasecmp(mime->str, mimetype, sizeof(mimetype))) {

            id = mime->id;

            break;

        }

        mime++;

    }

    if (id == AV_CODEC_ID_NONE) {

        av_log(s, AV_LOG_WARNING, "Unknown attached picture mimetype: %s, skipping.\n", mimetype);

        goto fail;

    }

    apic->id = id;



    /* picture type */

    pic_type = avio_r8(pb);

    taglen--;

    if (pic_type < 0 || pic_type >= FF_ARRAY_ELEMS(ff_id3v2_picture_types)) {

        av_log(s, AV_LOG_WARNING, "Unknown attached picture type %d.\n", pic_type);

        pic_type = 0;

    }

    apic->type = ff_id3v2_picture_types[pic_type];



    /* description and picture data */

    if (decode_str(s, pb, enc, &apic->description, &taglen) < 0) {

        av_log(s, AV_LOG_ERROR, "Error decoding attached picture description.\n");

        goto fail;

    }



    apic->buf = av_buffer_alloc(taglen);

    if (!apic->buf || !taglen || avio_read(pb, apic->buf->data, taglen) != taglen)

        goto fail;



    new_extra->tag    = "APIC";

    new_extra->data   = apic;

    new_extra->next   = *extra_meta;

    *extra_meta       = new_extra;



    return;



fail:

    if (apic)

        free_apic(apic);

    av_freep(&new_extra);

    avio_seek(pb, end, SEEK_SET);

}

