        avpriv_request_sample(ctx->avctx, "unknown subcodec %d", codec);
        return AVERROR_PATCHWELCOME;

static int tgq_decode_mb(TgqContext *s, AVFrame *frame, int mb_y, int mb_x)

{

    int mode;

    int i;

    int8_t dc[6];



    mode = bytestream2_get_byte(&s->gb);

    if (mode > 12) {

        GetBitContext gb;

        init_get_bits8(&gb, s->gb.buffer, FFMIN(bytestream2_get_bytes_left(&s->gb), mode));

        for (i = 0; i < 6; i++)

            tgq_decode_block(s, s->block[i], &gb);

        tgq_idct_put_mb(s, s->block, frame, mb_x, mb_y);

        bytestream2_skip(&s->gb, mode);

    } else {

        if (mode == 3) {

            memset(dc, bytestream2_get_byte(&s->gb), 4);

            dc[4] = bytestream2_get_byte(&s->gb);

            dc[5] = bytestream2_get_byte(&s->gb);

        } else if (mode == 6) {

            bytestream2_get_buffer(&s->gb, dc, 6);

        } else if (mode == 12) {

            for (i = 0; i < 6; i++) {

                dc[i] = bytestream2_get_byte(&s->gb);

                bytestream2_skip(&s->gb, 1);

            }

        } else {

            av_log(s->avctx, AV_LOG_ERROR, "unsupported mb mode %i\n", mode);

            return -1;

        }

        tgq_idct_put_mb_dconly(s, frame, mb_x, mb_y, dc);

    }

    return 0;

}

static void stream_component_close(VideoState *is, int stream_index)

{

    AVFormatContext *ic = is->ic;

    AVCodecContext *avctx;



    if (stream_index < 0 || stream_index >= ic->nb_streams)

        return;

    avctx = ic->streams[stream_index]->codec;



    switch(avctx->codec_type) {

    case AVMEDIA_TYPE_AUDIO:

        packet_queue_abort(&is->audioq);



        SDL_CloseAudio();



        packet_queue_end(&is->audioq);

        av_free_packet(&is->audio_pkt);

        if (is->reformat_ctx)

            av_audio_convert_free(is->reformat_ctx);

        is->reformat_ctx = NULL;



        if (is->rdft) {

            av_rdft_end(is->rdft);

            av_freep(&is->rdft_data);



        }

        break;

    case AVMEDIA_TYPE_VIDEO:

        packet_queue_abort(&is->videoq);



        /* note: we also signal this mutex to make sure we deblock the

           video thread in all cases */

        SDL_LockMutex(is->pictq_mutex);

        SDL_CondSignal(is->pictq_cond);

        SDL_UnlockMutex(is->pictq_mutex);



        SDL_WaitThread(is->video_tid, NULL);



        packet_queue_end(&is->videoq);

        break;

    case AVMEDIA_TYPE_SUBTITLE:

        packet_queue_abort(&is->subtitleq);



        /* note: we also signal this mutex to make sure we deblock the

           video thread in all cases */

        SDL_LockMutex(is->subpq_mutex);

        is->subtitle_stream_changed = 1;



        SDL_CondSignal(is->subpq_cond);

        SDL_UnlockMutex(is->subpq_mutex);



        SDL_WaitThread(is->subtitle_tid, NULL);



        packet_queue_end(&is->subtitleq);

        break;

    default:

        break;

    }



    ic->streams[stream_index]->discard = AVDISCARD_ALL;

    avcodec_close(avctx);

    switch(avctx->codec_type) {

    case AVMEDIA_TYPE_AUDIO:

        is->audio_st = NULL;

        is->audio_stream = -1;

        break;

    case AVMEDIA_TYPE_VIDEO:

        is->video_st = NULL;

        is->video_stream = -1;

        break;

    case AVMEDIA_TYPE_SUBTITLE:

        is->subtitle_st = NULL;

        is->subtitle_stream = -1;

        break;

    default:

        break;

    }

}

static inline void idct4col_put(uint8_t *dest, int line_size, const int16_t *col)

{

    int c0, c1, c2, c3, a0, a1, a2, a3;



    a0 = col[8*0];

    a1 = col[8*2];

    a2 = col[8*4];

    a3 = col[8*6];

    c0 = ((a0 + a2) << (CN_SHIFT - 1)) + (1 << (C_SHIFT - 1));

    c2 = ((a0 - a2) << (CN_SHIFT - 1)) + (1 << (C_SHIFT - 1));

    c1 = a1 * C1 + a3 * C2;

    c3 = a1 * C2 - a3 * C1;

    dest[0] = av_clip_uint8((c0 + c1) >> C_SHIFT);

    dest += line_size;

    dest[0] = av_clip_uint8((c2 + c3) >> C_SHIFT);

    dest += line_size;

    dest[0] = av_clip_uint8((c2 - c3) >> C_SHIFT);

    dest += line_size;

    dest[0] = av_clip_uint8((c0 - c1) >> C_SHIFT);

}

void fifo_realloc(FifoBuffer *f, int new_size){

    int old_size= f->end - f->buffer;



    if(old_size < new_size){

        uint8_t *old= f->buffer;



        f->buffer= av_realloc(f->buffer, new_size);



        f->rptr += f->buffer - old;

        f->wptr += f->buffer - old;



        if(f->wptr < f->rptr){

            memmove(f->rptr + new_size - old_size, f->rptr, f->buffer + old_size - f->rptr);

            f->rptr += new_size - old_size;

        }

        f->end= f->buffer + new_size;

    }

}

FFAMediaCodec* ff_AMediaCodec_createDecoderByType(const char *mime)

{

    JNIEnv *env = NULL;

    FFAMediaCodec *codec = NULL;

    jstring mime_type = NULL;



    codec = av_mallocz(sizeof(FFAMediaCodec));

    if (!codec) {

        return NULL;

    }

    codec->class = &amediacodec_class;



    env = ff_jni_get_env(codec);

    if (!env) {

        av_freep(&codec);

        return NULL;

    }



    if (ff_jni_init_jfields(env, &codec->jfields, jni_amediacodec_mapping, 1, codec) < 0) {

        goto fail;

    }



    mime_type = ff_jni_utf_chars_to_jstring(env, mime, codec);

    if (!mime_type) {

        goto fail;

    }



    codec->object = (*env)->CallStaticObjectMethod(env, codec->jfields.mediacodec_class, codec->jfields.create_decoder_by_type_id, mime_type);

    if (ff_jni_exception_check(env, 1, codec) < 0) {

        goto fail;

    }



    codec->object = (*env)->NewGlobalRef(env, codec->object);

    if (!codec->object) {

        goto fail;

    }



    if (codec_init_static_fields(codec) < 0) {

        goto fail;

    }



    if (codec->jfields.get_input_buffer_id && codec->jfields.get_output_buffer_id) {

        codec->has_get_i_o_buffer = 1;

    }



    return codec;

fail:

    ff_jni_reset_jfields(env, &codec->jfields, jni_amediacodec_mapping, 1, codec);



    if (mime_type) {

        (*env)->DeleteLocalRef(env, mime_type);

    }



    av_freep(&codec);



    return NULL;

}

static void vc1_interp_mc(VC1Context *v)

{

    MpegEncContext *s = &v->s;

    H264ChromaContext *h264chroma = &v->h264chroma;

    uint8_t *srcY, *srcU, *srcV;

    int dxy, mx, my, uvmx, uvmy, src_x, src_y, uvsrc_x, uvsrc_y;

    int off, off_uv;

    int v_edge_pos = s->v_edge_pos >> v->field_mode;

    int use_ic = v->next_use_ic;



    if (!v->field_mode && !v->s.next_picture.f.data[0])

        return;



    mx   = s->mv[1][0][0];

    my   = s->mv[1][0][1];

    uvmx = (mx + ((mx & 3) == 3)) >> 1;

    uvmy = (my + ((my & 3) == 3)) >> 1;

    if (v->field_mode) {

        if (v->cur_field_type != v->ref_field_type[1])

            my   = my   - 2 + 4 * v->cur_field_type;

            uvmy = uvmy - 2 + 4 * v->cur_field_type;

    }

    if (v->fastuvmc) {

        uvmx = uvmx + ((uvmx < 0) ? -(uvmx & 1) : (uvmx & 1));

        uvmy = uvmy + ((uvmy < 0) ? -(uvmy & 1) : (uvmy & 1));

    }

    srcY = s->next_picture.f.data[0];

    srcU = s->next_picture.f.data[1];

    srcV = s->next_picture.f.data[2];



    src_x   = s->mb_x * 16 + (mx   >> 2);

    src_y   = s->mb_y * 16 + (my   >> 2);

    uvsrc_x = s->mb_x *  8 + (uvmx >> 2);

    uvsrc_y = s->mb_y *  8 + (uvmy >> 2);



    if (v->profile != PROFILE_ADVANCED) {

        src_x   = av_clip(  src_x, -16, s->mb_width  * 16);

        src_y   = av_clip(  src_y, -16, s->mb_height * 16);

        uvsrc_x = av_clip(uvsrc_x,  -8, s->mb_width  *  8);

        uvsrc_y = av_clip(uvsrc_y,  -8, s->mb_height *  8);

    } else {

        src_x   = av_clip(  src_x, -17, s->avctx->coded_width);

        src_y   = av_clip(  src_y, -18, s->avctx->coded_height + 1);

        uvsrc_x = av_clip(uvsrc_x,  -8, s->avctx->coded_width  >> 1);

        uvsrc_y = av_clip(uvsrc_y,  -8, s->avctx->coded_height >> 1);

    }



    srcY += src_y   * s->linesize   + src_x;

    srcU += uvsrc_y * s->uvlinesize + uvsrc_x;

    srcV += uvsrc_y * s->uvlinesize + uvsrc_x;



    if (v->field_mode && v->ref_field_type[1]) {

        srcY += s->current_picture_ptr->f.linesize[0];

        srcU += s->current_picture_ptr->f.linesize[1];

        srcV += s->current_picture_ptr->f.linesize[2];

    }



    /* for grayscale we should not try to read from unknown area */

    if (s->flags & CODEC_FLAG_GRAY) {

        srcU = s->edge_emu_buffer + 18 * s->linesize;

        srcV = s->edge_emu_buffer + 18 * s->linesize;

    }



    if (v->rangeredfrm || s->h_edge_pos < 22 || v_edge_pos < 22 || use_ic

        || (unsigned)(src_x - 1) > s->h_edge_pos - (mx & 3) - 16 - 3

        || (unsigned)(src_y - 1) > v_edge_pos    - (my & 3) - 16 - 3) {

        uint8_t *uvbuf = s->edge_emu_buffer + 19 * s->linesize;



        srcY -= s->mspel * (1 + s->linesize);

        s->vdsp.emulated_edge_mc(s->edge_emu_buffer, srcY,

                                 s->linesize, s->linesize,

                                 17 + s->mspel * 2, 17 + s->mspel * 2,

                                 src_x - s->mspel, src_y - s->mspel,

                                 s->h_edge_pos, v_edge_pos);

        srcY = s->edge_emu_buffer;

        s->vdsp.emulated_edge_mc(uvbuf, srcU,

                                 s->uvlinesize, s->uvlinesize,

                                 8 + 1, 8 + 1,

                                 uvsrc_x, uvsrc_y, s->h_edge_pos >> 1, v_edge_pos >> 1);

        s->vdsp.emulated_edge_mc(uvbuf + 16, srcV,

                                 s->uvlinesize, s->uvlinesize,

                                 8 + 1, 8 + 1,

                                 uvsrc_x, uvsrc_y, s->h_edge_pos >> 1, v_edge_pos >> 1);

        srcU = uvbuf;

        srcV = uvbuf + 16;

        /* if we deal with range reduction we need to scale source blocks */

        if (v->rangeredfrm) {

            int i, j;

            uint8_t *src, *src2;



            src = srcY;

            for (j = 0; j < 17 + s->mspel * 2; j++) {

                for (i = 0; i < 17 + s->mspel * 2; i++)

                    src[i] = ((src[i] - 128) >> 1) + 128;

                src += s->linesize;

            }

            src = srcU;

            src2 = srcV;

            for (j = 0; j < 9; j++) {

                for (i = 0; i < 9; i++) {

                    src[i]  = ((src[i]  - 128) >> 1) + 128;

                    src2[i] = ((src2[i] - 128) >> 1) + 128;

                }

                src  += s->uvlinesize;

                src2 += s->uvlinesize;

            }

        }



        if (use_ic) {

            uint8_t (*luty )[256] = v->next_luty;

            uint8_t (*lutuv)[256] = v->next_lutuv;

            int i, j;

            uint8_t *src, *src2;



            src = srcY;

            for (j = 0; j < 17 + s->mspel * 2; j++) {

                int f = v->field_mode ? v->ref_field_type[1] : ((j+src_y - s->mspel) & 1);

                for (i = 0; i < 17 + s->mspel * 2; i++)

                    src[i] = luty[f][src[i]];

                src += s->linesize;

            }

            src  = srcU;

            src2 = srcV;

            for (j = 0; j < 9; j++) {

                int f = v->field_mode ? v->ref_field_type[1] : ((j+uvsrc_y) & 1);

                for (i = 0; i < 9; i++) {

                    src[i]  = lutuv[f][src[i]];

                    src2[i] = lutuv[f][src2[i]];

                }

                src  += s->uvlinesize;

                src2 += s->uvlinesize;

            }

        }

        srcY += s->mspel * (1 + s->linesize);

    }



    off    = 0;

    off_uv = 0;



    if (s->mspel) {

        dxy = ((my & 3) << 2) | (mx & 3);

        v->vc1dsp.avg_vc1_mspel_pixels_tab[dxy](s->dest[0] + off    , srcY    , s->linesize, v->rnd);

        v->vc1dsp.avg_vc1_mspel_pixels_tab[dxy](s->dest[0] + off + 8, srcY + 8, s->linesize, v->rnd);

        srcY += s->linesize * 8;

        v->vc1dsp.avg_vc1_mspel_pixels_tab[dxy](s->dest[0] + off + 8 * s->linesize    , srcY    , s->linesize, v->rnd);

        v->vc1dsp.avg_vc1_mspel_pixels_tab[dxy](s->dest[0] + off + 8 * s->linesize + 8, srcY + 8, s->linesize, v->rnd);

    } else { // hpel mc

        dxy = (my & 2) | ((mx & 2) >> 1);



        if (!v->rnd)

            s->hdsp.avg_pixels_tab[0][dxy](s->dest[0] + off, srcY, s->linesize, 16);

        else

            s->hdsp.avg_no_rnd_pixels_tab[dxy](s->dest[0] + off, srcY, s->linesize, 16);

    }



    if (s->flags & CODEC_FLAG_GRAY) return;

    /* Chroma MC always uses qpel blilinear */

    uvmx = (uvmx & 3) << 1;

    uvmy = (uvmy & 3) << 1;

    if (!v->rnd) {

        h264chroma->avg_h264_chroma_pixels_tab[0](s->dest[1] + off_uv, srcU, s->uvlinesize, 8, uvmx, uvmy);

        h264chroma->avg_h264_chroma_pixels_tab[0](s->dest[2] + off_uv, srcV, s->uvlinesize, 8, uvmx, uvmy);

    } else {

        v->vc1dsp.avg_no_rnd_vc1_chroma_pixels_tab[0](s->dest[1] + off_uv, srcU, s->uvlinesize, 8, uvmx, uvmy);

        v->vc1dsp.avg_no_rnd_vc1_chroma_pixels_tab[0](s->dest[2] + off_uv, srcV, s->uvlinesize, 8, uvmx, uvmy);

    }

}

static int dnxhd_decode_header(DNXHDContext *ctx, const uint8_t *buf, int buf_size, int first_field)

{

    static const uint8_t header_prefix[] = { 0x00, 0x00, 0x02, 0x80, 0x01 };

    int i, cid;



    if (buf_size < 0x280)

        return -1;



    if (memcmp(buf, header_prefix, 5)) {

        av_log(ctx->avctx, AV_LOG_ERROR, "error in header\n");

        return -1;

    }

    if (buf[5] & 2) { /* interlaced */

        ctx->cur_field = buf[5] & 1;

        ctx->picture.interlaced_frame = 1;

        ctx->picture.top_field_first = first_field ^ ctx->cur_field;

        av_log(ctx->avctx, AV_LOG_DEBUG, "interlaced %d, cur field %d\n", buf[5] & 3, ctx->cur_field);

    }



    ctx->height = AV_RB16(buf + 0x18);

    ctx->width  = AV_RB16(buf + 0x1a);



    av_dlog(ctx->avctx, "width %d, height %d\n", ctx->width, ctx->height);



    if (buf[0x21] & 0x40) {

        ctx->avctx->pix_fmt = AV_PIX_FMT_YUV422P10;

        ctx->avctx->bits_per_raw_sample = 10;

        if (ctx->bit_depth != 10) {

            ff_dsputil_init(&ctx->dsp, ctx->avctx);

            ctx->bit_depth = 10;

            ctx->decode_dct_block = dnxhd_decode_dct_block_10;

        }

    } else {

        ctx->avctx->pix_fmt = AV_PIX_FMT_YUV422P;

        ctx->avctx->bits_per_raw_sample = 8;

        if (ctx->bit_depth != 8) {

            ff_dsputil_init(&ctx->dsp, ctx->avctx);

            ctx->bit_depth = 8;

            ctx->decode_dct_block = dnxhd_decode_dct_block_8;

        }

    }



    cid = AV_RB32(buf + 0x28);

    av_dlog(ctx->avctx, "compression id %d\n", cid);



    if (dnxhd_init_vlc(ctx, cid) < 0)

        return -1;



    if (buf_size < ctx->cid_table->coding_unit_size) {

        av_log(ctx->avctx, AV_LOG_ERROR, "incorrect frame size\n");

        return -1;

    }



    ctx->mb_width = ctx->width>>4;

    ctx->mb_height = buf[0x16d];



    av_dlog(ctx->avctx, "mb width %d, mb height %d\n", ctx->mb_width, ctx->mb_height);



    if ((ctx->height+15)>>4 == ctx->mb_height && ctx->picture.interlaced_frame)

        ctx->height <<= 1;



    if (ctx->mb_height > 68 ||

        (ctx->mb_height<<ctx->picture.interlaced_frame) > (ctx->height+15)>>4) {

        av_log(ctx->avctx, AV_LOG_ERROR, "mb height too big: %d\n", ctx->mb_height);

        return -1;

    }



    for (i = 0; i < ctx->mb_height; i++) {

        ctx->mb_scan_index[i] = AV_RB32(buf + 0x170 + (i<<2));

        av_dlog(ctx->avctx, "mb scan index %d\n", ctx->mb_scan_index[i]);

        if (buf_size < ctx->mb_scan_index[i] + 0x280) {

            av_log(ctx->avctx, AV_LOG_ERROR, "invalid mb scan index\n");

            return -1;

        }

    }



    return 0;

}

static int ogg_write_trailer(AVFormatContext *s)

{

    int i;



    /* flush current page */

    for (i = 0; i < s->nb_streams; i++)

        ogg_buffer_page(s, s->streams[i]->priv_data);



    ogg_write_pages(s, 1);



    for (i = 0; i < s->nb_streams; i++) {

        AVStream *st = s->streams[i];

        OGGStreamContext *oggstream = st->priv_data;

        if (st->codec->codec_id == CODEC_ID_FLAC ||

            st->codec->codec_id == CODEC_ID_SPEEX) {

            av_free(oggstream->header[0]);


        }



        av_freep(&st->priv_data);

    }

    return 0;

}

static int avi_sync(AVFormatContext *s, int exit_early)

{

    AVIContext *avi = s->priv_data;

    AVIOContext *pb = s->pb;

    int n;

    unsigned int d[8];

    unsigned int size;

    int64_t i, sync;



start_sync:

    memset(d, -1, sizeof(d));

    for (i = sync = avio_tell(pb); !avio_feof(pb); i++) {

        int j;



        for (j = 0; j < 7; j++)

            d[j] = d[j + 1];

        d[7] = avio_r8(pb);



        size = d[4] + (d[5] << 8) + (d[6] << 16) + (d[7] << 24);



        n = get_stream_idx(d + 2);

        ff_tlog(s, "%X %X %X %X %X %X %X %X %"PRId64" %u %d\n",

                d[0], d[1], d[2], d[3], d[4], d[5], d[6], d[7], i, size, n);

        if (i*(avi->io_fsize>0) + (uint64_t)size > avi->fsize || d[0] > 127)

            continue;



        // parse ix##

        if ((d[0] == 'i' && d[1] == 'x' && n < s->nb_streams) ||

            // parse JUNK

            (d[0] == 'J' && d[1] == 'U' && d[2] == 'N' && d[3] == 'K') ||

            (d[0] == 'i' && d[1] == 'd' && d[2] == 'x' && d[3] == '1') ||

            (d[0] == 'i' && d[1] == 'n' && d[2] == 'd' && d[3] == 'x')) {

            avio_skip(pb, size);

            goto start_sync;

        }



        // parse stray LIST

        if (d[0] == 'L' && d[1] == 'I' && d[2] == 'S' && d[3] == 'T') {

            avio_skip(pb, 4);

            goto start_sync;

        }



        n = get_stream_idx(d);



        if (!((i - avi->last_pkt_pos) & 1) &&

            get_stream_idx(d + 1) < s->nb_streams)

            continue;



        // detect ##ix chunk and skip

        if (d[2] == 'i' && d[3] == 'x' && n < s->nb_streams) {

            avio_skip(pb, size);

            goto start_sync;

        }



        if (avi->dv_demux && n != 0)

            continue;



        // parse ##dc/##wb

        if (n < s->nb_streams) {

            AVStream *st;

            AVIStream *ast;

            st  = s->streams[n];

            ast = st->priv_data;



            if (!ast) {

                av_log(s, AV_LOG_WARNING, "Skipping foreign stream %d packet\n", n);

                continue;

            }



            if (s->nb_streams >= 2) {

                AVStream *st1   = s->streams[1];

                AVIStream *ast1 = st1->priv_data;

                // workaround for broken small-file-bug402.avi

                if (   d[2] == 'w' && d[3] == 'b'

                   && n == 0

                   && st ->codecpar->codec_type == AVMEDIA_TYPE_VIDEO

                   && st1->codecpar->codec_type == AVMEDIA_TYPE_AUDIO

                   && ast->prefix == 'd'*256+'c'

                   && (d[2]*256+d[3] == ast1->prefix || !ast1->prefix_count)

                  ) {

                    n   = 1;

                    st  = st1;

                    ast = ast1;

                    av_log(s, AV_LOG_WARNING,

                           "Invalid stream + prefix combination, assuming audio.\n");

                }

            }



            if (!avi->dv_demux &&

                ((st->discard >= AVDISCARD_DEFAULT && size == 0) /* ||

                 // FIXME: needs a little reordering

                 (st->discard >= AVDISCARD_NONKEY &&

                 !(pkt->flags & AV_PKT_FLAG_KEY)) */

                || st->discard >= AVDISCARD_ALL)) {

                if (!exit_early) {

                    ast->frame_offset += get_duration(ast, size);

                    avio_skip(pb, size);

                    goto start_sync;

                }

            }



            if (d[2] == 'p' && d[3] == 'c' && size <= 4 * 256 + 4) {

                int k    = avio_r8(pb);

                int last = (k + avio_r8(pb) - 1) & 0xFF;



                avio_rl16(pb); // flags



                // b + (g << 8) + (r << 16);

                for (; k <= last; k++)

                    ast->pal[k] = 0xFFU<<24 | avio_rb32(pb)>>8;



                ast->has_pal = 1;

                goto start_sync;

            } else if (((ast->prefix_count < 5 || sync + 9 > i) &&

                        d[2] < 128 && d[3] < 128) ||

                       d[2] * 256 + d[3] == ast->prefix /* ||

                       (d[2] == 'd' && d[3] == 'c') ||

                       (d[2] == 'w' && d[3] == 'b') */) {

                if (exit_early)

                    return 0;

                if (d[2] * 256 + d[3] == ast->prefix)

                    ast->prefix_count++;

                else {

                    ast->prefix       = d[2] * 256 + d[3];

                    ast->prefix_count = 0;

                }



                avi->stream_index = n;

                ast->packet_size  = size + 8;

                ast->remaining    = size;



                if (size) {

                    uint64_t pos = avio_tell(pb) - 8;

                    if (!st->index_entries || !st->nb_index_entries ||

                        st->index_entries[st->nb_index_entries - 1].pos < pos) {

                        av_add_index_entry(st, pos, ast->frame_offset, size,

                                           0, AVINDEX_KEYFRAME);

                    }

                }

                return 0;

            }

        }

    }



    if (pb->error)

        return pb->error;

    return AVERROR_EOF;

}

static int roq_probe(AVProbeData *p)

{

    if (p->buf_size < 6)

        return 0;



    if ((AV_RL16(&p->buf[0]) != RoQ_MAGIC_NUMBER) ||

        (AV_RL32(&p->buf[2]) != 0xFFFFFFFF))

        return 0;



    return AVPROBE_SCORE_MAX;

}

inline static void RENAME(hcscale)(SwsContext *c, uint16_t *dst, long dstWidth, const uint8_t *src1, const uint8_t *src2,

                                   int srcW, int xInc, const int16_t *hChrFilter,

                                   const int16_t *hChrFilterPos, int hChrFilterSize,

                                   uint8_t *formatConvBuffer,

                                   uint32_t *pal)

{



    src1 += c->chrSrcOffset;

    src2 += c->chrSrcOffset;



    if (c->chrToYV12) {

        c->chrToYV12(formatConvBuffer, formatConvBuffer+VOFW, src1, src2, srcW, pal);

        src1= formatConvBuffer;

        src2= formatConvBuffer+VOFW;

    }



    if (c->hScale16) {

        c->hScale16(dst     , dstWidth, (uint16_t*)src1, srcW, xInc, hChrFilter, hChrFilterPos, hChrFilterSize, av_pix_fmt_descriptors[c->srcFormat].comp[0].depth_minus1);

        c->hScale16(dst+VOFW, dstWidth, (uint16_t*)src2, srcW, xInc, hChrFilter, hChrFilterPos, hChrFilterSize, av_pix_fmt_descriptors[c->srcFormat].comp[0].depth_minus1);

    } else if (!c->hcscale_fast) {

        c->hScale(dst     , dstWidth, src1, srcW, xInc, hChrFilter, hChrFilterPos, hChrFilterSize);

        c->hScale(dst+VOFW, dstWidth, src2, srcW, xInc, hChrFilter, hChrFilterPos, hChrFilterSize);

    } else { // fast bilinear upscale / crap downscale

        c->hcscale_fast(c, dst, dstWidth, src1, src2, srcW, xInc);

    }



    if (c->chrConvertRange)

        c->chrConvertRange(dst, dstWidth);

}

void ff_af_queue_remove(AudioFrameQueue *afq, int nb_samples, int64_t *pts,

                        int *duration)

{

    int64_t out_pts = AV_NOPTS_VALUE;

    int removed_samples = 0;

    int i;



    if (afq->frame_count || afq->frame_alloc) {

        if (afq->frames->pts != AV_NOPTS_VALUE)

            out_pts = afq->frames->pts;

    }

    if(!afq->frame_count)

        av_log(afq->avctx, AV_LOG_WARNING, "Trying to remove %d samples, but que empty\n", nb_samples);

    if (pts)

        *pts = ff_samples_to_time_base(afq->avctx, out_pts);



    for(i=0; nb_samples && i<afq->frame_count; i++){

        int n= FFMIN(afq->frames[i].duration, nb_samples);

        afq->frames[i].duration -= n;

        nb_samples              -= n;

        removed_samples         += n;

        if(afq->frames[i].pts != AV_NOPTS_VALUE)

            afq->frames[i].pts      += n;

    }

    i -= i && afq->frames[i-1].duration;

    memmove(afq->frames, afq->frames + i, sizeof(*afq->frames) * (afq->frame_count - i));

    afq->frame_count -= i;



    if(nb_samples){

        av_assert0(!afq->frame_count);

        if(afq->frames[0].pts != AV_NOPTS_VALUE)

            afq->frames[0].pts += nb_samples;

        av_log(afq->avctx, AV_LOG_DEBUG, "Trying to remove %d more samples than are in the que\n", nb_samples);

    }

    if (duration)

        *duration = ff_samples_to_time_base(afq->avctx, removed_samples);

}

static int bmp_decode_frame(AVCodecContext *avctx,

                            void *data, int *got_frame,

                            AVPacket *avpkt)

{

    const uint8_t *buf = avpkt->data;

    int buf_size       = avpkt->size;

    AVFrame *p         = data;

    unsigned int fsize, hsize;

    int width, height;

    unsigned int depth;

    BiCompression comp;

    unsigned int ihsize;

    int i, j, n, linesize, ret;

    uint32_t rgb[3] = {0};

    uint32_t alpha = 0;

    uint8_t *ptr;

    int dsize;

    const uint8_t *buf0 = buf;

    GetByteContext gb;



    if (buf_size < 14) {

        av_log(avctx, AV_LOG_ERROR, "buf size too small (%d)\n", buf_size);

        return AVERROR_INVALIDDATA;

    }



    if (bytestream_get_byte(&buf) != 'B' ||

        bytestream_get_byte(&buf) != 'M') {

        av_log(avctx, AV_LOG_ERROR, "bad magic number\n");

        return AVERROR_INVALIDDATA;

    }



    fsize = bytestream_get_le32(&buf);

    if (buf_size < fsize) {

        av_log(avctx, AV_LOG_ERROR, "not enough data (%d < %u), trying to decode anyway\n",

               buf_size, fsize);

        fsize = buf_size;

    }



    buf += 2; /* reserved1 */

    buf += 2; /* reserved2 */



    hsize  = bytestream_get_le32(&buf); /* header size */

    ihsize = bytestream_get_le32(&buf); /* more header size */

    if (ihsize + 14LL > hsize) {

        av_log(avctx, AV_LOG_ERROR, "invalid header size %u\n", hsize);

        return AVERROR_INVALIDDATA;

    }



    /* sometimes file size is set to some headers size, set a real size in that case */

    if (fsize == 14 || fsize == ihsize + 14)

        fsize = buf_size - 2;



    if (fsize <= hsize) {

        av_log(avctx, AV_LOG_ERROR,

               "Declared file size is less than header size (%u < %u)\n",

               fsize, hsize);

        return AVERROR_INVALIDDATA;

    }



    switch (ihsize) {

    case  40: // windib

    case  56: // windib v3

    case  64: // OS/2 v2

    case 108: // windib v4

    case 124: // windib v5

        width  = bytestream_get_le32(&buf);

        height = bytestream_get_le32(&buf);

        break;

    case  12: // OS/2 v1

        width  = bytestream_get_le16(&buf);

        height = bytestream_get_le16(&buf);

        break;

    default:

        avpriv_report_missing_feature(avctx, "Information header size %u",

                                      ihsize);

        return AVERROR_PATCHWELCOME;

    }



    /* planes */

    if (bytestream_get_le16(&buf) != 1) {

        av_log(avctx, AV_LOG_ERROR, "invalid BMP header\n");

        return AVERROR_INVALIDDATA;

    }



    depth = bytestream_get_le16(&buf);



    if (ihsize >= 40)

        comp = bytestream_get_le32(&buf);

    else

        comp = BMP_RGB;



    if (comp != BMP_RGB && comp != BMP_BITFIELDS && comp != BMP_RLE4 &&

        comp != BMP_RLE8) {

        av_log(avctx, AV_LOG_ERROR, "BMP coding %d not supported\n", comp);

        return AVERROR_INVALIDDATA;

    }



    if (comp == BMP_BITFIELDS) {

        buf += 20;

        rgb[0] = bytestream_get_le32(&buf);

        rgb[1] = bytestream_get_le32(&buf);

        rgb[2] = bytestream_get_le32(&buf);

        if (ihsize > 40)

        alpha = bytestream_get_le32(&buf);

    }



    avctx->width  = width;

    avctx->height = height > 0 ? height : -(unsigned)height;



    avctx->pix_fmt = AV_PIX_FMT_NONE;



    switch (depth) {

    case 32:

        if (comp == BMP_BITFIELDS) {

            if (rgb[0] == 0xFF000000 && rgb[1] == 0x00FF0000 && rgb[2] == 0x0000FF00)

                avctx->pix_fmt = alpha ? AV_PIX_FMT_ABGR : AV_PIX_FMT_0BGR;

            else if (rgb[0] == 0x00FF0000 && rgb[1] == 0x0000FF00 && rgb[2] == 0x000000FF)

                avctx->pix_fmt = alpha ? AV_PIX_FMT_BGRA : AV_PIX_FMT_BGR0;

            else if (rgb[0] == 0x0000FF00 && rgb[1] == 0x00FF0000 && rgb[2] == 0xFF000000)

                avctx->pix_fmt = alpha ? AV_PIX_FMT_ARGB : AV_PIX_FMT_0RGB;

            else if (rgb[0] == 0x000000FF && rgb[1] == 0x0000FF00 && rgb[2] == 0x00FF0000)

                avctx->pix_fmt = alpha ? AV_PIX_FMT_RGBA : AV_PIX_FMT_RGB0;

            else {

                av_log(avctx, AV_LOG_ERROR, "Unknown bitfields "

                       "%0"PRIX32" %0"PRIX32" %0"PRIX32"\n", rgb[0], rgb[1], rgb[2]);

                return AVERROR(EINVAL);

            }

        } else {

            avctx->pix_fmt = AV_PIX_FMT_BGRA;

        }

        break;

    case 24:

        avctx->pix_fmt = AV_PIX_FMT_BGR24;

        break;

    case 16:

        if (comp == BMP_RGB)

            avctx->pix_fmt = AV_PIX_FMT_RGB555;

        else if (comp == BMP_BITFIELDS) {

            if (rgb[0] == 0xF800 && rgb[1] == 0x07E0 && rgb[2] == 0x001F)

               avctx->pix_fmt = AV_PIX_FMT_RGB565;

            else if (rgb[0] == 0x7C00 && rgb[1] == 0x03E0 && rgb[2] == 0x001F)

               avctx->pix_fmt = AV_PIX_FMT_RGB555;

            else if (rgb[0] == 0x0F00 && rgb[1] == 0x00F0 && rgb[2] == 0x000F)

               avctx->pix_fmt = AV_PIX_FMT_RGB444;

            else {

               av_log(avctx, AV_LOG_ERROR,

                      "Unknown bitfields %0"PRIX32" %0"PRIX32" %0"PRIX32"\n",

                      rgb[0], rgb[1], rgb[2]);

               return AVERROR(EINVAL);

            }

        }

        break;

    case 8:

        if (hsize - ihsize - 14 > 0)

            avctx->pix_fmt = AV_PIX_FMT_PAL8;

        else

            avctx->pix_fmt = AV_PIX_FMT_GRAY8;

        break;

    case 1:

    case 4:

        if (hsize - ihsize - 14 > 0) {

            avctx->pix_fmt = AV_PIX_FMT_PAL8;

        } else {

            av_log(avctx, AV_LOG_ERROR, "Unknown palette for %u-colour BMP\n",

                   1 << depth);

            return AVERROR_INVALIDDATA;

        }

        break;

    default:

        av_log(avctx, AV_LOG_ERROR, "depth %u not supported\n", depth);

        return AVERROR_INVALIDDATA;

    }



    if (avctx->pix_fmt == AV_PIX_FMT_NONE) {

        av_log(avctx, AV_LOG_ERROR, "unsupported pixel format\n");

        return AVERROR_INVALIDDATA;

    }



    if ((ret = ff_get_buffer(avctx, p, 0)) < 0)

        return ret;

    p->pict_type = AV_PICTURE_TYPE_I;

    p->key_frame = 1;



    buf   = buf0 + hsize;

    dsize = buf_size - hsize;



    /* Line size in file multiple of 4 */

    n = ((avctx->width * depth + 31) / 8) & ~3;



    if (n * avctx->height > dsize && comp != BMP_RLE4 && comp != BMP_RLE8) {

        n = (avctx->width * depth + 7) / 8;

        if (n * avctx->height > dsize) {

            av_log(avctx, AV_LOG_ERROR, "not enough data (%d < %d)\n",

                   dsize, n * avctx->height);

            return AVERROR_INVALIDDATA;

        }

        av_log(avctx, AV_LOG_ERROR, "data size too small, assuming missing line alignment\n");

    }



    // RLE may skip decoding some picture areas, so blank picture before decoding

    if (comp == BMP_RLE4 || comp == BMP_RLE8)

        memset(p->data[0], 0, avctx->height * p->linesize[0]);



    if (height > 0) {

        ptr      = p->data[0] + (avctx->height - 1) * p->linesize[0];

        linesize = -p->linesize[0];

    } else {

        ptr      = p->data[0];

        linesize = p->linesize[0];

    }



    if (avctx->pix_fmt == AV_PIX_FMT_PAL8) {

        int colors = 1 << depth;



        memset(p->data[1], 0, 1024);



        if (ihsize >= 36) {

            int t;

            buf = buf0 + 46;

            t   = bytestream_get_le32(&buf);

            if (t < 0 || t > (1 << depth)) {

                av_log(avctx, AV_LOG_ERROR,

                       "Incorrect number of colors - %X for bitdepth %u\n",

                       t, depth);

            } else if (t) {

                colors = t;

            }

        } else {

            colors = FFMIN(256, (hsize-ihsize-14) / 3);

        }

        buf = buf0 + 14 + ihsize; //palette location

        // OS/2 bitmap, 3 bytes per palette entry

        if ((hsize-ihsize-14) < (colors << 2)) {

            if ((hsize-ihsize-14) < colors * 3) {

                av_log(avctx, AV_LOG_ERROR, "palette doesn't fit in packet\n");

                return AVERROR_INVALIDDATA;

            }

            for (i = 0; i < colors; i++)

                ((uint32_t*)p->data[1])[i] = (0xFFU<<24) | bytestream_get_le24(&buf);

        } else {

            for (i = 0; i < colors; i++)

                ((uint32_t*)p->data[1])[i] = 0xFFU << 24 | bytestream_get_le32(&buf);

        }

        buf = buf0 + hsize;

    }

    if (comp == BMP_RLE4 || comp == BMP_RLE8) {

        if (comp == BMP_RLE8 && height < 0) {

            p->data[0]    +=  p->linesize[0] * (avctx->height - 1);

            p->linesize[0] = -p->linesize[0];

        }

        bytestream2_init(&gb, buf, dsize);

        ff_msrle_decode(avctx, p, depth, &gb);

        if (height < 0) {

            p->data[0]    +=  p->linesize[0] * (avctx->height - 1);

            p->linesize[0] = -p->linesize[0];

        }

    } else {

        switch (depth) {

        case 1:

            for (i = 0; i < avctx->height; i++) {

                int j;

                for (j = 0; j < n; j++) {

                    ptr[j*8+0] =  buf[j] >> 7;

                    ptr[j*8+1] = (buf[j] >> 6) & 1;

                    ptr[j*8+2] = (buf[j] >> 5) & 1;

                    ptr[j*8+3] = (buf[j] >> 4) & 1;

                    ptr[j*8+4] = (buf[j] >> 3) & 1;

                    ptr[j*8+5] = (buf[j] >> 2) & 1;

                    ptr[j*8+6] = (buf[j] >> 1) & 1;

                    ptr[j*8+7] =  buf[j]       & 1;

                }

                buf += n;

                ptr += linesize;

            }

            break;

        case 8:

        case 24:

        case 32:

            for (i = 0; i < avctx->height; i++) {

                memcpy(ptr, buf, n);

                buf += n;

                ptr += linesize;

            }

            break;

        case 4:

            for (i = 0; i < avctx->height; i++) {

                int j;

                for (j = 0; j < n; j++) {

                    ptr[j*2+0] = (buf[j] >> 4) & 0xF;

                    ptr[j*2+1] = buf[j] & 0xF;

                }

                buf += n;

                ptr += linesize;

            }

            break;

        case 16:

            for (i = 0; i < avctx->height; i++) {

                const uint16_t *src = (const uint16_t *) buf;

                uint16_t *dst       = (uint16_t *) ptr;



                for (j = 0; j < avctx->width; j++)

                    *dst++ = av_le2ne16(*src++);



                buf += n;

                ptr += linesize;

            }

            break;

        default:

            av_log(avctx, AV_LOG_ERROR, "BMP decoder is broken\n");

            return AVERROR_INVALIDDATA;

        }

    }

    if (avctx->pix_fmt == AV_PIX_FMT_BGRA) {

        for (i = 0; i < avctx->height; i++) {

            int j;

            uint8_t *ptr = p->data[0] + p->linesize[0]*i + 3;

            for (j = 0; j < avctx->width; j++) {

                if (ptr[4*j])

                    break;

            }

            if (j < avctx->width)

                break;

        }

        if (i == avctx->height)

            avctx->pix_fmt = p->format = AV_PIX_FMT_BGR0;

    }



    *got_frame = 1;



    return buf_size;

}

static int shorten_decode_frame(AVCodecContext *avctx,

        void *data, int *data_size,

        AVPacket *avpkt)

{

    const uint8_t *buf = avpkt->data;

    int buf_size = avpkt->size;

    ShortenContext *s = avctx->priv_data;

    int i, input_buf_size = 0;

    int16_t *samples = data;

    if(s->max_framesize == 0){

        s->max_framesize= 1024; // should hopefully be enough for the first header

        s->bitstream= av_fast_realloc(s->bitstream, &s->allocated_bitstream_size, s->max_framesize);

    }



    if(1 && s->max_framesize){//FIXME truncated

        buf_size= FFMIN(buf_size, s->max_framesize - s->bitstream_size);

        input_buf_size= buf_size;



        if(s->bitstream_index + s->bitstream_size + buf_size > s->allocated_bitstream_size){

            //                printf("memmove\n");

            memmove(s->bitstream, &s->bitstream[s->bitstream_index], s->bitstream_size);

            s->bitstream_index=0;

        }

        memcpy(&s->bitstream[s->bitstream_index + s->bitstream_size], buf, buf_size);

        buf= &s->bitstream[s->bitstream_index];

        buf_size += s->bitstream_size;

        s->bitstream_size= buf_size;



        if(buf_size < s->max_framesize){

            *data_size = 0;

            return input_buf_size;

        }

    }

    init_get_bits(&s->gb, buf, buf_size*8);

    skip_bits(&s->gb, s->bitindex);

    if (!s->blocksize)

    {

        int ret;

        if ((ret = read_header(s)) < 0)

            return ret;

        *data_size = 0;

    }

    else

    {

        int cmd;

        int len;

        cmd = get_ur_golomb_shorten(&s->gb, FNSIZE);



        if (cmd > FN_VERBATIM) {

            av_log(avctx, AV_LOG_ERROR, "unknown shorten function %d\n", cmd);

            if (s->bitstream_size > 0) {

                s->bitstream_index++;

                s->bitstream_size--;

            }

            return -1;

        }



        if (!is_audio_command[cmd]) {

            /* process non-audio command */

            switch (cmd) {

                case FN_VERBATIM:

                    len = get_ur_golomb_shorten(&s->gb, VERBATIM_CKSIZE_SIZE);

                    while (len--) {

                        get_ur_golomb_shorten(&s->gb, VERBATIM_BYTE_SIZE);

                    }

                    break;

                case FN_BITSHIFT:

                    s->bitshift = get_ur_golomb_shorten(&s->gb, BITSHIFTSIZE);

                    break;

                case FN_BLOCKSIZE: {

                    int blocksize = get_uint(s, av_log2(s->blocksize));

                    if (blocksize > s->blocksize) {

                        av_log(avctx, AV_LOG_ERROR, "Increasing block size is not supported\n");

                        return AVERROR_PATCHWELCOME;

                    }

                    s->blocksize = blocksize;

                    break;

                }

                case FN_QUIT:

                    break;

            }

            *data_size = 0;

        } else {

            /* process audio command */

            int ret;

            int residual_size = 0;

            int channel = s->cur_chan;

            int32_t coffset;

            if (cmd != FN_ZERO) {

                residual_size = get_ur_golomb_shorten(&s->gb, ENERGYSIZE);

                /* this is a hack as version 0 differed in defintion of get_sr_golomb_shorten */

                if (s->version == 0)

                    residual_size--;

            }



            if (s->nmean == 0)

                coffset = s->offset[channel][0];

            else {

                int32_t sum = (s->version < 2) ? 0 : s->nmean / 2;

                for (i=0; i<s->nmean; i++)

                    sum += s->offset[channel][i];

                coffset = sum / s->nmean;

                if (s->version >= 2)

                    coffset >>= FFMIN(1, s->bitshift);

            }

            switch (cmd) {

                case FN_ZERO:

                    for (i=0; i<s->blocksize; i++)

                        s->decoded[channel][i] = 0;

                    break;

                case FN_DIFF0:

                    for (i=0; i<s->blocksize; i++)

                        s->decoded[channel][i] = get_sr_golomb_shorten(&s->gb, residual_size) + coffset;

                    break;

                case FN_DIFF1:

                    for (i=0; i<s->blocksize; i++)

                        s->decoded[channel][i] = get_sr_golomb_shorten(&s->gb, residual_size) + s->decoded[channel][i - 1];

                    break;

                case FN_DIFF2:

                    for (i=0; i<s->blocksize; i++)

                        s->decoded[channel][i] = get_sr_golomb_shorten(&s->gb, residual_size) + 2*s->decoded[channel][i-1]

                                                                                              -   s->decoded[channel][i-2];

                    break;

                case FN_DIFF3:

                    for (i=0; i<s->blocksize; i++)

                        s->decoded[channel][i] = get_sr_golomb_shorten(&s->gb, residual_size) + 3*s->decoded[channel][i-1]

                                                                                              - 3*s->decoded[channel][i-2]

                                                                                              +   s->decoded[channel][i-3];

                    break;

                case FN_QLPC:

                    if ((ret = decode_subframe_lpc(s, channel, residual_size, coffset)) < 0)

                        return ret;

                    break;

            }

            if (s->nmean > 0) {

                int32_t sum = (s->version < 2) ? 0 : s->blocksize / 2;

                for (i=0; i<s->blocksize; i++)

                    sum += s->decoded[channel][i];



                for (i=1; i<s->nmean; i++)

                    s->offset[channel][i-1] = s->offset[channel][i];



                if (s->version < 2)

                    s->offset[channel][s->nmean - 1] = sum / s->blocksize;

                else

                    s->offset[channel][s->nmean - 1] = (sum / s->blocksize) << s->bitshift;

            }

            for (i=-s->nwrap; i<0; i++)

                s->decoded[channel][i] = s->decoded[channel][i + s->blocksize];



            fix_bitshift(s, s->decoded[channel]);



            s->cur_chan++;

            if (s->cur_chan == s->channels) {

                samples = interleave_buffer(samples, s->channels, s->blocksize, s->decoded);

                s->cur_chan = 0;

                *data_size = (int8_t *)samples - (int8_t *)data;

            } else {

                *data_size = 0;

            }

        }

    }



    //    s->last_blocksize = s->blocksize;

    s->bitindex = get_bits_count(&s->gb) - 8*((get_bits_count(&s->gb))/8);

    i= (get_bits_count(&s->gb))/8;

    if (i > buf_size) {

        av_log(s->avctx, AV_LOG_ERROR, "overread: %d\n", i - buf_size);

        s->bitstream_size=0;

        s->bitstream_index=0;

        return -1;

    }

    if (s->bitstream_size) {

        s->bitstream_index += i;

        s->bitstream_size  -= i;

        return input_buf_size;

    } else

        return i;

}

static int mm_decode_pal(MmContext *s)

{

    int i;



    bytestream2_skip(&s->gb, 4);

    for (i = 0; i < 128; i++) {

        s->palette[i] = 0xFF << 24 | bytestream2_get_be24(&s->gb);

        s->palette[i+128] = s->palette[i]<<2;

    }



    return 0;

}

static void FUNCC(pred16x16_horizontal_add)(uint8_t *pix,

                                            const int *block_offset,

                                            const int16_t *block,

                                            ptrdiff_t stride)

{

