static void sbr_gain_calc(AACContext *ac, SpectralBandReplication *sbr,

                          SBRData *ch_data, const int e_a[2])

{

    int e, k, m;

    // max gain limits : -3dB, 0dB, 3dB, inf dB (limiter off)

    static const SoftFloat limgain[4] = { { 760155524,  0 }, { 0x20000000,  1 },

                                            { 758351638,  1 }, { 625000000, 34 } };



    for (e = 0; e < ch_data->bs_num_env; e++) {

        int delta = !((e == e_a[1]) || (e == e_a[0]));

        for (k = 0; k < sbr->n_lim; k++) {

            SoftFloat gain_boost, gain_max;

            SoftFloat sum[2] = { FLOAT_0, FLOAT_0 };

            for (m = sbr->f_tablelim[k] - sbr->kx[1]; m < sbr->f_tablelim[k + 1] - sbr->kx[1]; m++) {

                const SoftFloat temp = av_div_sf(sbr->e_origmapped[e][m],

                                            av_add_sf(FLOAT_1, sbr->q_mapped[e][m]));

                sbr->q_m[e][m] = av_sqrt_sf(av_mul_sf(temp, sbr->q_mapped[e][m]));

                sbr->s_m[e][m] = av_sqrt_sf(av_mul_sf(temp, av_int2sf(ch_data->s_indexmapped[e + 1][m], 0)));

                if (!sbr->s_mapped[e][m]) {

                    if (delta) {

                      sbr->gain[e][m] = av_sqrt_sf(av_div_sf(sbr->e_origmapped[e][m],

                                            av_mul_sf(av_add_sf(FLOAT_1, sbr->e_curr[e][m]),

                                            av_add_sf(FLOAT_1, sbr->q_mapped[e][m]))));

                    } else {

                      sbr->gain[e][m] = av_sqrt_sf(av_div_sf(sbr->e_origmapped[e][m],

                                            av_add_sf(FLOAT_1, sbr->e_curr[e][m])));

                    }

                } else {

                    sbr->gain[e][m] = av_sqrt_sf(

                                        av_div_sf(

                                            av_mul_sf(sbr->e_origmapped[e][m], sbr->q_mapped[e][m]),

                                            av_mul_sf(

                                                av_add_sf(FLOAT_1, sbr->e_curr[e][m]),

                                                av_add_sf(FLOAT_1, sbr->q_mapped[e][m]))));

                }

            }

            for (m = sbr->f_tablelim[k] - sbr->kx[1]; m < sbr->f_tablelim[k + 1] - sbr->kx[1]; m++) {

                sum[0] = av_add_sf(sum[0], sbr->e_origmapped[e][m]);

                sum[1] = av_add_sf(sum[1], sbr->e_curr[e][m]);

            }

            gain_max = av_mul_sf(limgain[sbr->bs_limiter_gains],

                            av_sqrt_sf(

                                av_div_sf(

                                    av_add_sf(FLOAT_EPSILON, sum[0]),

                                    av_add_sf(FLOAT_EPSILON, sum[1]))));

            if (av_gt_sf(gain_max, FLOAT_100000))

              gain_max = FLOAT_100000;

            for (m = sbr->f_tablelim[k] - sbr->kx[1]; m < sbr->f_tablelim[k + 1] - sbr->kx[1]; m++) {

                SoftFloat q_m_max = av_div_sf(

                                        av_mul_sf(sbr->q_m[e][m], gain_max),

                                        sbr->gain[e][m]);

                if (av_gt_sf(sbr->q_m[e][m], q_m_max))

                  sbr->q_m[e][m] = q_m_max;

                if (av_gt_sf(sbr->gain[e][m], gain_max))

                  sbr->gain[e][m] = gain_max;

            }

            sum[0] = sum[1] = FLOAT_0;

            for (m = sbr->f_tablelim[k] - sbr->kx[1]; m < sbr->f_tablelim[k + 1] - sbr->kx[1]; m++) {

                sum[0] = av_add_sf(sum[0], sbr->e_origmapped[e][m]);

                sum[1] = av_add_sf(sum[1],

                            av_mul_sf(

                                av_mul_sf(sbr->e_curr[e][m],

                                          sbr->gain[e][m]),

                                sbr->gain[e][m]));

                sum[1] = av_add_sf(sum[1],

                            av_mul_sf(sbr->s_m[e][m], sbr->s_m[e][m]));

                if (delta && !sbr->s_m[e][m].mant)

                  sum[1] = av_add_sf(sum[1],

                                av_mul_sf(sbr->q_m[e][m], sbr->q_m[e][m]));

            }

            gain_boost = av_sqrt_sf(

                            av_div_sf(

                                av_add_sf(FLOAT_EPSILON, sum[0]),

                                av_add_sf(FLOAT_EPSILON, sum[1])));

            if (av_gt_sf(gain_boost, FLOAT_1584893192))

              gain_boost = FLOAT_1584893192;



            for (m = sbr->f_tablelim[k] - sbr->kx[1]; m < sbr->f_tablelim[k + 1] - sbr->kx[1]; m++) {

                sbr->gain[e][m] = av_mul_sf(sbr->gain[e][m], gain_boost);

                sbr->q_m[e][m]  = av_mul_sf(sbr->q_m[e][m], gain_boost);

                sbr->s_m[e][m]  = av_mul_sf(sbr->s_m[e][m], gain_boost);

            }

        }

    }

}

x11grab_read_packet(AVFormatContext *s1, AVPacket *pkt)

{

    struct x11_grab *s = s1->priv_data;

    Display *dpy = s->dpy;

    XImage *image = s->image;

    int x_off = s->x_off;

    int y_off = s->y_off;



    int64_t curtime, delay;

    struct timespec ts;



    /* Calculate the time of the next frame */

    s->time_frame += INT64_C(1000000);



    /* wait based on the frame rate */

    for(;;) {

        curtime = av_gettime();

        delay = s->time_frame * av_q2d(s->time_base) - curtime;

        if (delay <= 0) {

            if (delay < INT64_C(-1000000) * av_q2d(s->time_base)) {

                s->time_frame += INT64_C(1000000);

            }

            break;

        }

        ts.tv_sec = delay / 1000000;

        ts.tv_nsec = (delay % 1000000) * 1000;

        nanosleep(&ts, NULL);

    }



    av_init_packet(pkt);

    pkt->data = image->data;

    pkt->size = s->frame_size;

    pkt->pts = curtime;



    if(s->use_shm) {

        if (!XShmGetImage(dpy, RootWindow(dpy, DefaultScreen(dpy)), image, x_off, y_off, AllPlanes)) {

            av_log (s1, AV_LOG_INFO, "XShmGetImage() failed\n");

        }

    } else {

        if (!xget_zpixmap(dpy, RootWindow(dpy, DefaultScreen(dpy)), image, x_off, y_off)) {

            av_log (s1, AV_LOG_INFO, "XGetZPixmap() failed\n");

        }

    }



    if(!s->nomouse){

        paint_mouse_pointer(image, s);

    }



    return s->frame_size;

}

static int svq3_decode_slice_header(H264Context *h)

{

    MpegEncContext *const s = (MpegEncContext *) h;

    const int mb_xy = h->mb_xy;

    int i, header;



    header = get_bits(&s->gb, 8);



    if (((header & 0x9F) != 1 && (header & 0x9F) != 2) || (header & 0x60) == 0) {

        /* TODO: what? */

        av_log(h->s.avctx, AV_LOG_ERROR, "unsupported slice header (%02X)\n", header);

        return -1;

    } else {

        int length = (header >> 5) & 3;



        h->next_slice_index = get_bits_count(&s->gb) + 8*show_bits(&s->gb, 8*length) + 8*length;



        if (h->next_slice_index > s->gb.size_in_bits) {

            av_log(h->s.avctx, AV_LOG_ERROR, "slice after bitstream end\n");

            return -1;

    }



        s->gb.size_in_bits = h->next_slice_index - 8*(length - 1);

        skip_bits(&s->gb, 8);



        if (h->svq3_watermark_key) {

            uint32_t header = AV_RL32(&s->gb.buffer[(get_bits_count(&s->gb)>>3)+1]);

            AV_WL32(&s->gb.buffer[(get_bits_count(&s->gb)>>3)+1], header ^ h->svq3_watermark_key);

        }

        if (length > 0) {

            memcpy((uint8_t *) &s->gb.buffer[get_bits_count(&s->gb) >> 3],

                   &s->gb.buffer[s->gb.size_in_bits >> 3], (length - 1));

        }

        skip_bits_long(&s->gb, 0);

    }



    if ((i = svq3_get_ue_golomb(&s->gb)) == INVALID_VLC || i >= 3){

        av_log(h->s.avctx, AV_LOG_ERROR, "illegal slice type %d \n", i);

        return -1;

    }



    h->slice_type = golomb_to_pict_type[i];



    if ((header & 0x9F) == 2) {

        i = (s->mb_num < 64) ? 6 : (1 + av_log2 (s->mb_num - 1));

        s->mb_skip_run = get_bits(&s->gb, i) - (s->mb_x + (s->mb_y * s->mb_width));

    } else {

        skip_bits1(&s->gb);

        s->mb_skip_run = 0;

    }



    h->slice_num = get_bits(&s->gb, 8);

    s->qscale = get_bits(&s->gb, 5);

    s->adaptive_quant = get_bits1(&s->gb);



    /* unknown fields */

    skip_bits1(&s->gb);



    if (h->unknown_svq3_flag) {

        skip_bits1(&s->gb);

    }



    skip_bits1(&s->gb);

    skip_bits(&s->gb, 2);



    while (get_bits1(&s->gb)) {

        skip_bits(&s->gb, 8);

    }



    /* reset intra predictors and invalidate motion vector references */

    if (s->mb_x > 0) {

        memset(h->intra4x4_pred_mode+8*h->mb2br_xy[mb_xy - 1      ]+3, -1, 4*sizeof(int8_t));

        memset(h->intra4x4_pred_mode+8*h->mb2br_xy[mb_xy - s->mb_x]  , -1, 8*sizeof(int8_t)*s->mb_x);

    }

    if (s->mb_y > 0) {

        memset(h->intra4x4_pred_mode+8*h->mb2br_xy[mb_xy - s->mb_stride], -1, 8*sizeof(int8_t)*(s->mb_width - s->mb_x));



        if (s->mb_x > 0) {

            h->intra4x4_pred_mode[8*h->mb2br_xy[mb_xy - s->mb_stride - 1]+3] = -1;

        }

    }



    return 0;

}

static int tta_read_header(AVFormatContext *s)

{

    TTAContext *c = s->priv_data;

    AVStream *st;

    int i, channels, bps, samplerate;

    uint64_t framepos, start_offset;

    uint32_t datalen;



    if (!av_dict_get(s->metadata, "", NULL, AV_DICT_IGNORE_SUFFIX))

        ff_id3v1_read(s);



    start_offset = avio_tell(s->pb);

    if (avio_rl32(s->pb) != AV_RL32("TTA1"))

        return -1; // not tta file



    avio_skip(s->pb, 2); // FIXME: flags

    channels = avio_rl16(s->pb);

    bps = avio_rl16(s->pb);

    samplerate = avio_rl32(s->pb);

    if(samplerate <= 0 || samplerate > 1000000){

        av_log(s, AV_LOG_ERROR, "nonsense samplerate\n");

        return -1;

    }



    datalen = avio_rl32(s->pb);

    if (!datalen) {

        av_log(s, AV_LOG_ERROR, "invalid datalen\n");

        return AVERROR_INVALIDDATA;

    }



    avio_skip(s->pb, 4); // header crc



    c->frame_size      = samplerate * 256 / 245;

    c->last_frame_size = datalen % c->frame_size;

    if (!c->last_frame_size)

        c->last_frame_size = c->frame_size;

    c->totalframes = datalen / c->frame_size + (c->last_frame_size < c->frame_size);

    c->currentframe = 0;



    if(c->totalframes >= UINT_MAX/sizeof(uint32_t) || c->totalframes <= 0){

        av_log(s, AV_LOG_ERROR, "totalframes %d invalid\n", c->totalframes);

        return -1;

    }



    st = avformat_new_stream(s, NULL);

    if (!st)

        return AVERROR(ENOMEM);



    avpriv_set_pts_info(st, 64, 1, samplerate);

    st->start_time = 0;

    st->duration = datalen;



    framepos = avio_tell(s->pb) + 4*c->totalframes + 4;



    for (i = 0; i < c->totalframes; i++) {

        uint32_t size = avio_rl32(s->pb);

        av_add_index_entry(st, framepos, i * c->frame_size, size, 0,

                           AVINDEX_KEYFRAME);

        framepos += size;

    }

    avio_skip(s->pb, 4); // seektable crc



    st->codec->codec_type = AVMEDIA_TYPE_AUDIO;

    st->codec->codec_id = AV_CODEC_ID_TTA;

    st->codec->channels = channels;

    st->codec->sample_rate = samplerate;

    st->codec->bits_per_coded_sample = bps;



    st->codec->extradata_size = avio_tell(s->pb) - start_offset;

    if(st->codec->extradata_size+FF_INPUT_BUFFER_PADDING_SIZE <= (unsigned)st->codec->extradata_size){

        //this check is redundant as avio_read should fail

        av_log(s, AV_LOG_ERROR, "extradata_size too large\n");

        return -1;

    }

    st->codec->extradata = av_mallocz(st->codec->extradata_size+FF_INPUT_BUFFER_PADDING_SIZE);

    if (!st->codec->extradata) {

        st->codec->extradata_size = 0;

        return AVERROR(ENOMEM);

    }

    avio_seek(s->pb, start_offset, SEEK_SET);

    avio_read(s->pb, st->codec->extradata, st->codec->extradata_size);



    return 0;

}

static void sub2video_update(InputStream *ist, AVSubtitle *sub)

{

    int w = ist->sub2video.w, h = ist->sub2video.h;

    AVFrame *frame = ist->sub2video.frame;

    int8_t *dst;

    int     dst_linesize;

    int num_rects, i;

    int64_t pts, end_pts;



    if (!frame)

        return;

    if (sub) {

        pts       = av_rescale_q(sub->pts + sub->start_display_time * 1000,

                                 AV_TIME_BASE_Q, ist->st->time_base);

        end_pts   = av_rescale_q(sub->pts + sub->end_display_time   * 1000,

                                 AV_TIME_BASE_Q, ist->st->time_base);

        num_rects = sub->num_rects;

    } else {

        pts       = ist->sub2video.end_pts;

        end_pts   = INT64_MAX;

        num_rects = 0;

    }

    if (sub2video_get_blank_frame(ist) < 0) {

        av_log(ist->dec_ctx, AV_LOG_ERROR,

               "Impossible to get a blank canvas.\n");

        return;

    }

    dst          = frame->data    [0];

    dst_linesize = frame->linesize[0];

    for (i = 0; i < num_rects; i++)

        sub2video_copy_rect(dst, dst_linesize, w, h, sub->rects[i]);

    sub2video_push_ref(ist, pts);

    ist->sub2video.end_pts = end_pts;

}

static av_cold int flic_decode_init(AVCodecContext *avctx)

{

    FlicDecodeContext *s = avctx->priv_data;

    unsigned char *fli_header = (unsigned char *)avctx->extradata;

    int depth;



    if (avctx->extradata_size != 12 &&

        avctx->extradata_size != 128) {

        av_log(avctx, AV_LOG_ERROR, "Expected extradata of 12 or 128 bytes\n");

        return AVERROR_INVALIDDATA;

    }



    s->avctx = avctx;



    s->fli_type = AV_RL16(&fli_header[4]); /* Might be overridden if a Magic Carpet FLC */



    depth = 0;

    if (s->avctx->extradata_size == 12) {

        /* special case for magic carpet FLIs */

        s->fli_type = FLC_MAGIC_CARPET_SYNTHETIC_TYPE_CODE;

        depth = 8;

    } else {

        depth = AV_RL16(&fli_header[12]);

    }



    if (depth == 0) {

        depth = 8; /* Some FLC generators set depth to zero, when they mean 8Bpp. Fix up here */

    }



    if ((s->fli_type == FLC_FLX_TYPE_CODE) && (depth == 16)) {

        depth = 15; /* Original Autodesk FLX's say the depth is 16Bpp when it is really 15Bpp */

    }



    switch (depth) {

        case 8  : avctx->pix_fmt = AV_PIX_FMT_PAL8; break;

        case 15 : avctx->pix_fmt = AV_PIX_FMT_RGB555; break;

        case 16 : avctx->pix_fmt = AV_PIX_FMT_RGB565; break;

        case 24 : avctx->pix_fmt = AV_PIX_FMT_BGR24; /* Supposedly BGR, but havent any files to test with */

                  av_log(avctx, AV_LOG_ERROR, "24Bpp FLC/FLX is unsupported due to no test files.\n");

                  return AVERROR_PATCHWELCOME;

        default :

                  av_log(avctx, AV_LOG_ERROR, "Unknown FLC/FLX depth of %d Bpp is unsupported.\n",depth);

                  return AVERROR_INVALIDDATA;

    }



    s->frame.data[0] = NULL;

    s->new_palette = 0;



    return 0;

}

void ff_sbr_apply(AACContext *ac, SpectralBandReplication *sbr, int id_aac,

                  float* L, float* R)

{

    int downsampled = ac->m4ac.ext_sample_rate < sbr->sample_rate;

    int ch;

    int nch = (id_aac == TYPE_CPE) ? 2 : 1;



    if (sbr->start) {

        sbr_dequant(sbr, id_aac);

    }

    for (ch = 0; ch < nch; ch++) {

        /* decode channel */

        sbr_qmf_analysis(&ac->dsp, &sbr->mdct_ana, ch ? R : L, sbr->data[ch].analysis_filterbank_samples,

                         (float*)sbr->qmf_filter_scratch,

                         sbr->data[ch].W);

        sbr_lf_gen(ac, sbr, sbr->X_low, sbr->data[ch].W);

        if (sbr->start) {

            sbr_hf_inverse_filter(sbr->alpha0, sbr->alpha1, sbr->X_low, sbr->k[0]);

            sbr_chirp(sbr, &sbr->data[ch]);

            sbr_hf_gen(ac, sbr, sbr->X_high, sbr->X_low, sbr->alpha0, sbr->alpha1,

                       sbr->data[ch].bw_array, sbr->data[ch].t_env,

                       sbr->data[ch].bs_num_env);



            // hf_adj

            sbr_mapping(ac, sbr, &sbr->data[ch], sbr->data[ch].e_a);

            sbr_env_estimate(sbr->e_curr, sbr->X_high, sbr, &sbr->data[ch]);

            sbr_gain_calc(ac, sbr, &sbr->data[ch], sbr->data[ch].e_a);

            sbr_hf_assemble(sbr->data[ch].Y, sbr->X_high, sbr, &sbr->data[ch],

                            sbr->data[ch].e_a);

        }



        /* synthesis */

        sbr_x_gen(sbr, sbr->X[ch], sbr->X_low, sbr->data[ch].Y, ch);

    }



    if (ac->m4ac.ps == 1) {

        if (sbr->ps.start) {

            ff_ps_apply(ac->avctx, &sbr->ps, sbr->X[0], sbr->X[1], sbr->kx[1] + sbr->m[1]);

        } else {

            memcpy(sbr->X[1], sbr->X[0], sizeof(sbr->X[0]));

        }

        nch = 2;

    }



    sbr_qmf_synthesis(&ac->dsp, &sbr->mdct, L, sbr->X[0], sbr->qmf_filter_scratch,

                      sbr->data[0].synthesis_filterbank_samples,

                      &sbr->data[0].synthesis_filterbank_samples_offset,

                      downsampled);

    if (nch == 2)

        sbr_qmf_synthesis(&ac->dsp, &sbr->mdct, R, sbr->X[1], sbr->qmf_filter_scratch,

                          sbr->data[1].synthesis_filterbank_samples,

                          &sbr->data[1].synthesis_filterbank_samples_offset,

                          downsampled);

}

static void tile_codeblocks(Jpeg2000DecoderContext *s, Jpeg2000Tile *tile)

{

    Jpeg2000T1Context t1;



    int compno, reslevelno, bandno;



    /* Loop on tile components */



    for (compno = 0; compno < s->ncomponents; compno++) {

        Jpeg2000Component *comp     = tile->comp + compno;

        Jpeg2000CodingStyle *codsty = tile->codsty + compno;

        /* Loop on resolution levels */

        for (reslevelno = 0; reslevelno < codsty->nreslevels2decode; reslevelno++) {

            Jpeg2000ResLevel *rlevel = comp->reslevel + reslevelno;

            /* Loop on bands */

            for (bandno = 0; bandno < rlevel->nbands; bandno++) {

                uint16_t nb_precincts, precno;

                Jpeg2000Band *band = rlevel->band + bandno;

                int cblkno = 0, bandpos;

                bandpos = bandno + (reslevelno > 0);



                if (band->coord[0][0] == band->coord[0][1] ||

                    band->coord[1][0] == band->coord[1][1])

                    continue;



                nb_precincts = rlevel->num_precincts_x * rlevel->num_precincts_y;

                /* Loop on precincts */

                for (precno = 0; precno < nb_precincts; precno++) {

                    Jpeg2000Prec *prec = band->prec + precno;



                    /* Loop on codeblocks */

                    for (cblkno = 0; cblkno < prec->nb_codeblocks_width * prec->nb_codeblocks_height; cblkno++) {

                        int x, y;

                        Jpeg2000Cblk *cblk = prec->cblk + cblkno;

                        decode_cblk(s, codsty, &t1, cblk,

                                    cblk->coord[0][1] - cblk->coord[0][0],

                                    cblk->coord[1][1] - cblk->coord[1][0],

                                    bandpos);



                        x = cblk->coord[0][0];

                        y = cblk->coord[1][0];



                        if (codsty->transform == FF_DWT97)

                            dequantization_float(x, y, cblk, comp, &t1, band);

                        else

                            dequantization_int(x, y, cblk, comp, &t1, band);

                   } /* end cblk */

                } /*end prec */

            } /* end band */

        } /* end reslevel */



        /* inverse DWT */

        ff_dwt_decode(&comp->dwt, codsty->transform == FF_DWT97 ? (void*)comp->f_data : (void*)comp->i_data);

    } /*end comp */

}

static inline void downmix_3f_2r_to_dolby(float *samples)

{

    int i;



    for (i = 0; i < 256; i++) {

        samples[i] += (samples[i + 256] - samples[i + 768]);

        samples[i + 256] = (samples[i + 512] + samples[i + 1024]);

        samples[i + 512] = samples[i + 768] = samples[i + 1024] = 0;

    }

}

int rtsp_next_attr_and_value(const char **p, char *attr, int attr_size, char *value, int value_size)

{

    skip_spaces(p);

    if(**p) {

        get_word_sep(attr, attr_size, "=", p);

        if (**p == '=')

            (*p)++;

        get_word_sep(value, value_size, ";", p);

        if (**p == ';')

            (*p)++;

        return 1;

    }

    return 0;

}

int av_opencl_init(AVDictionary *options, AVOpenCLExternalEnv *ext_opencl_env)

{

    int ret = 0;

    AVDictionaryEntry *opt_build_entry;

    AVDictionaryEntry *opt_platform_entry;

    AVDictionaryEntry *opt_device_entry;

    LOCK_OPENCL

    if (!gpu_env.init_count) {

        opt_platform_entry = av_dict_get(options, "platform_idx", NULL, 0);

        opt_device_entry   = av_dict_get(options, "device_idx", NULL, 0);

        /*initialize devices, context, command_queue*/

        gpu_env.usr_spec_dev_info.platform_idx = -1;

        gpu_env.usr_spec_dev_info.dev_idx = -1;

        if (opt_platform_entry) {

            gpu_env.usr_spec_dev_info.platform_idx = strtol(opt_platform_entry->value, NULL, 10);

        }

        if (opt_device_entry) {

            gpu_env.usr_spec_dev_info.dev_idx = strtol(opt_device_entry->value, NULL, 10);

        }

        ret = init_opencl_env(&gpu_env, ext_opencl_env);

        if (ret < 0)

            goto end;

    }

    /*initialize program, kernel_name, kernel_count*/

    opt_build_entry = av_dict_get(options, "build_options", NULL, 0);

    if (opt_build_entry)

        ret = compile_kernel_file(&gpu_env, opt_build_entry->value);

    else

        ret = compile_kernel_file(&gpu_env, NULL);

    if (ret < 0)

        goto end;

    av_assert1(gpu_env.kernel_code_count > 0);

    gpu_env.init_count++;



end:

    UNLOCK_OPENCL

    return ret;

}

static CodeBook unpack_codebook(GetBitContext* gb, unsigned depth,

                                 unsigned size)

{

    unsigned i, j;

    CodeBook cb = { 0 };



    if (!can_safely_read(gb, (uint64_t)size * 34))

        return cb;



    if (size >= INT_MAX / sizeof(MacroBlock))

        return cb;

    cb.blocks = av_malloc(size ? size * sizeof(MacroBlock) : 1);

    if (!cb.blocks)

        return cb;



    cb.depth = depth;

    cb.size = size;

    for (i = 0; i < size; i++) {

        unsigned mask_bits = get_bits(gb, 4);

        unsigned color0 = get_bits(gb, 15);

        unsigned color1 = get_bits(gb, 15);



        for (j = 0; j < 4; j++) {

            if (mask_bits & (1 << j))

                cb.blocks[i].pixels[j] = color1;

            else

                cb.blocks[i].pixels[j] = color0;

        }

    }

    return cb;

}

static void hybrid4_8_12_cx(float (*in)[2], float (*out)[32][2], const float (*filter)[7][2], int N, int len)

{

    int i, j, ssb;



    for (i = 0; i < len; i++, in++) {

        for (ssb = 0; ssb < N; ssb++) {

            float sum_re = filter[ssb][6][0] * in[6][0], sum_im = filter[ssb][6][0] * in[6][1];

            for (j = 0; j < 6; j++) {

                float in0_re = in[j][0];

                float in0_im = in[j][1];

                float in1_re = in[12-j][0];

                float in1_im = in[12-j][1];

                sum_re += filter[ssb][j][0] * (in0_re + in1_re) - filter[ssb][j][1] * (in0_im - in1_im);

                sum_im += filter[ssb][j][0] * (in0_im + in1_im) + filter[ssb][j][1] * (in0_re - in1_re);

            }

            out[ssb][i][0] = sum_re;

            out[ssb][i][1] = sum_im;

        }

    }

}

