static int h263_decode_gob_header(MpegEncContext *s)

{

    unsigned int val, gob_number;

    int left;



    /* Check for GOB Start Code */

    val = show_bits(&s->gb, 16);

    if(val)

        return -1;



        /* We have a GBSC probably with GSTUFF */

    skip_bits(&s->gb, 16); /* Drop the zeros */

    left= get_bits_left(&s->gb);


    //MN: we must check the bits left or we might end in an infinite loop (or segfault)

    for(;left>13; left--){

        if(get_bits1(&s->gb)) break; /* Seek the '1' bit */

    }

    if(left<=13)

        return -1;



    if(s->h263_slice_structured){

        if(check_marker(s->avctx, &s->gb, "before MBA")==0)

            return -1;



        ff_h263_decode_mba(s);



        if(s->mb_num > 1583)

            if(check_marker(s->avctx, &s->gb, "after MBA")==0)

                return -1;



        s->qscale = get_bits(&s->gb, 5); /* SQUANT */

        if(check_marker(s->avctx, &s->gb, "after SQUANT")==0)

            return -1;

        skip_bits(&s->gb, 2); /* GFID */

    }else{

        gob_number = get_bits(&s->gb, 5); /* GN */

        s->mb_x= 0;

        s->mb_y= s->gob_index* gob_number;

        skip_bits(&s->gb, 2); /* GFID */

        s->qscale = get_bits(&s->gb, 5); /* GQUANT */

    }



    if(s->mb_y >= s->mb_height)

        return -1;



    if(s->qscale==0)

        return -1;



    return 0;

}

static int mov_read_wide(MOVContext *c, ByteIOContext *pb, MOV_atom_t atom)

{

    int err;

    uint32_t type;



#ifdef DEBUG

    print_atom("wide", atom);

    debug_indent++;

#endif

    if (atom.size < 8)

        return 0; /* continue */

    if (get_be32(pb) != 0) { /* 0 sized mdat atom... use the 'wide' atom size */

        url_fskip(pb, atom.size - 4);

        return 0;

    }

    atom.type = get_le32(pb);

    atom.offset += 8;

    atom.size -= 8;

    if (type != MKTAG('m', 'd', 'a', 't')) {

        url_fskip(pb, atom.size);

        return 0;

    }

    err = mov_read_mdat(c, pb, atom);

#ifdef DEBUG

    debug_indent--;

#endif

    return err;

}

static int copy_cell(Indeo3DecodeContext *ctx, Plane *plane, Cell *cell)

{

    int     h, w, mv_x, mv_y, offset, offset_dst;

    uint8_t *src, *dst;



    /* setup output and reference pointers */

    offset_dst  = (cell->ypos << 2) * plane->pitch + (cell->xpos << 2);

    dst         = plane->pixels[ctx->buf_sel] + offset_dst;

    mv_y        = cell->mv_ptr[0];

    mv_x        = cell->mv_ptr[1];



    /* -1 because there is an extra line on top for prediction */

    if ((cell->ypos << 2) + mv_y < -1 || (cell->xpos << 2) + mv_x < 0 ||

        ((cell->ypos + cell->height) << 2) + mv_y >= plane->height    ||

        ((cell->xpos + cell->width)  << 2) + mv_x >= plane->width) {

        av_log(ctx->avctx, AV_LOG_ERROR,

               "Motion vectors point out of the frame.\n");

        return AVERROR_INVALIDDATA;

    }



    offset      = offset_dst + mv_y * plane->pitch + mv_x;

    src         = plane->pixels[ctx->buf_sel ^ 1] + offset;



    h = cell->height << 2;



    for (w = cell->width; w > 0;) {

        /* copy using 16xH blocks */

        if (!((cell->xpos << 2) & 15) && w >= 4) {

            for (; w >= 4; src += 16, dst += 16, w -= 4)

                ctx->hdsp.put_no_rnd_pixels_tab[0][0](dst, src, plane->pitch, h);

        }



        /* copy using 8xH blocks */

        if (!((cell->xpos << 2) & 7) && w >= 2) {

            ctx->hdsp.put_no_rnd_pixels_tab[1][0](dst, src, plane->pitch, h);

            w -= 2;

            src += 8;

            dst += 8;

        }



        if (w >= 1) {

            ctx->hdsp.put_no_rnd_pixels_tab[2][0](dst, src, plane->pitch, h);

            w--;

            src += 4;

            dst += 4;

        }

    }



    return 0;

}

