static int asf_write_trailer(AVFormatContext *s)

{

    ASFContext *asf = s->priv_data;

    int64_t file_size, data_size;



    /* flush the current packet */

    if (asf->pb.buf_ptr > asf->pb.buffer)

        flush_packet(s);



    /* write index */

    data_size = avio_tell(s->pb);

    if ((!asf->is_streamed) && (asf->nb_index_count != 0))

        asf_write_index(s, asf->index_ptr, asf->maximum_packet, asf->nb_index_count);

    avio_flush(s->pb);



    if (asf->is_streamed || !s->pb->seekable) {

        put_chunk(s, 0x4524, 0, 0); /* end of stream */

    } else {

        /* rewrite an updated header */

        file_size = avio_tell(s->pb);

        avio_seek(s->pb, 0, SEEK_SET);

        asf_write_header1(s, file_size, data_size - asf->data_offset);

    }



    av_free(asf->index_ptr);

    return 0;

}

static void dvbsub_parse_display_definition_segment(AVCodecContext *avctx,

                                                    const uint8_t *buf,

                                                    int buf_size)

{

    DVBSubContext *ctx = avctx->priv_data;

    DVBSubDisplayDefinition *display_def = ctx->display_definition;

    int dds_version, info_byte;



    if (buf_size < 5)

        return;



    info_byte   = bytestream_get_byte(&buf);

    dds_version = info_byte >> 4;

    if (display_def && display_def->version == dds_version)

        return; // already have this display definition version



    if (!display_def) {

        display_def             = av_mallocz(sizeof(*display_def));

        ctx->display_definition = display_def;

    }

    if (!display_def)

        return;



    display_def->version = dds_version;

    display_def->x       = 0;

    display_def->y       = 0;

    display_def->width   = bytestream_get_be16(&buf) + 1;

    display_def->height  = bytestream_get_be16(&buf) + 1;



    if (buf_size < 13)

        return;



    if (info_byte & 1<<3) { // display_window_flag

        display_def->x = bytestream_get_be16(&buf);

        display_def->y = bytestream_get_be16(&buf);

        display_def->width  = bytestream_get_be16(&buf) - display_def->x + 1;

        display_def->height = bytestream_get_be16(&buf) - display_def->y + 1;

    }

}

static int synchronize_audio(VideoState *is, int nb_samples)

{

    int wanted_nb_samples = nb_samples;



    /* if not master, then we try to remove or add samples to correct the clock */

    if (get_master_sync_type(is) != AV_SYNC_AUDIO_MASTER) {

        double diff, avg_diff;

        int min_nb_samples, max_nb_samples;



        diff = get_audio_clock(is) - get_master_clock(is);



        if (fabs(diff) < AV_NOSYNC_THRESHOLD) {

            is->audio_diff_cum = diff + is->audio_diff_avg_coef * is->audio_diff_cum;

            if (is->audio_diff_avg_count < AUDIO_DIFF_AVG_NB) {

                /* not enough measures to have a correct estimate */

                is->audio_diff_avg_count++;

            } else {

                /* estimate the A-V difference */

                avg_diff = is->audio_diff_cum * (1.0 - is->audio_diff_avg_coef);



                if (fabs(avg_diff) >= is->audio_diff_threshold) {

                    wanted_nb_samples = nb_samples + (int)(diff * is->audio_src.freq);

                    min_nb_samples = ((nb_samples * (100 - SAMPLE_CORRECTION_PERCENT_MAX) / 100));

                    max_nb_samples = ((nb_samples * (100 + SAMPLE_CORRECTION_PERCENT_MAX) / 100));

                    wanted_nb_samples = FFMIN(FFMAX(wanted_nb_samples, min_nb_samples), max_nb_samples);

                }

                av_dlog(NULL, "diff=%f adiff=%f sample_diff=%d apts=%0.3f %f\n",

                        diff, avg_diff, wanted_nb_samples - nb_samples,

                        is->audio_clock, is->audio_diff_threshold);

            }

        } else {

            /* too big difference : may be initial PTS errors, so

               reset A-V filter */

            is->audio_diff_avg_count = 0;

            is->audio_diff_cum       = 0;

        }

    }



    return wanted_nb_samples;

}

int ff_alloc_packet(AVPacket *avpkt, int size)

{

    if (size > INT_MAX - FF_INPUT_BUFFER_PADDING_SIZE)

        return AVERROR(EINVAL);



    if (avpkt->data) {

        void *destruct = avpkt->destruct;



        if (avpkt->size < size)

            return AVERROR(EINVAL);



        av_init_packet(avpkt);

        avpkt->destruct = destruct;

        avpkt->size = size;

        return 0;

    } else {

        return av_new_packet(avpkt, size);

    }

}

static int ast_write_trailer(AVFormatContext *s)

{

    AVIOContext *pb = s->pb;

    ASTMuxContext *ast = s->priv_data;

    AVCodecContext *enc = s->streams[0]->codec;

    int64_t file_size = avio_tell(pb);

    int64_t samples = (file_size - 64 - (32 * enc->frame_number)) / enc->block_align; /* PCM_S16BE_PLANAR */



    av_log(s, AV_LOG_DEBUG, "total samples: %"PRId64"\n", samples);



    if (s->pb->seekable) {

        /* Number of samples */

        avio_seek(pb, ast->samples, SEEK_SET);

        avio_wb32(pb, samples);



        /* Loopstart if provided */

        if (ast->loopstart > 0) {

        if (ast->loopstart >= samples) {

            av_log(s, AV_LOG_WARNING, "Loopstart value is out of range and will be ignored\n");

            ast->loopstart = -1;

            avio_skip(pb, 4);

        } else

        avio_wb32(pb, ast->loopstart);

        } else

            avio_skip(pb, 4);



        /* Loopend if provided. Otherwise number of samples again */

        if (ast->loopend && ast->loopstart >= 0) {

            if (ast->loopend > samples) {

                av_log(s, AV_LOG_WARNING, "Loopend value is out of range and will be ignored\n");

                ast->loopend = samples;

            }

            avio_wb32(pb, ast->loopend);

        } else {

            avio_wb32(pb, samples);

        }



        /* Size of first block */

        avio_wb32(pb, ast->fbs);



        /* File size minus header */

        avio_seek(pb, ast->size, SEEK_SET);

        avio_wb32(pb, file_size - 64);



        /* Loop flag */

        if (ast->loopstart >= 0) {

            avio_skip(pb, 6);

            avio_wb16(pb, 0xFFFF);

        }



        avio_seek(pb, file_size, SEEK_SET);

        avio_flush(pb);

    }

    return 0;

}

int ff_h264_field_end(H264Context *h, H264SliceContext *sl, int in_setup)

{

    AVCodecContext *const avctx = h->avctx;

    int err = 0;

    h->mb_y = 0;



    if (!in_setup && !h->droppable)

        ff_thread_report_progress(&h->cur_pic_ptr->tf, INT_MAX,

                                  h->picture_structure == PICT_BOTTOM_FIELD);



    if (in_setup || !(avctx->active_thread_type & FF_THREAD_FRAME)) {

        if (!h->droppable) {

            err = ff_h264_execute_ref_pic_marking(h, h->mmco, h->mmco_index);

            h->prev_poc_msb = h->poc_msb;

            h->prev_poc_lsb = h->poc_lsb;

        }

        h->prev_frame_num_offset = h->frame_num_offset;

        h->prev_frame_num        = h->frame_num;

    }



    if (avctx->hwaccel) {

        if (avctx->hwaccel->end_frame(avctx) < 0)

            av_log(avctx, AV_LOG_ERROR,

                   "hardware accelerator failed to decode picture\n");

    }



#if CONFIG_ERROR_RESILIENCE

    /*

     * FIXME: Error handling code does not seem to support interlaced

     * when slices span multiple rows

     * The ff_er_add_slice calls don't work right for bottom

     * fields; they cause massive erroneous error concealing

     * Error marking covers both fields (top and bottom).

     * This causes a mismatched s->error_count

     * and a bad error table. Further, the error count goes to

     * INT_MAX when called for bottom field, because mb_y is

     * past end by one (callers fault) and resync_mb_y != 0

     * causes problems for the first MB line, too.

     */

    if (!FIELD_PICTURE(h) && h->enable_er) {

        h264_set_erpic(&sl->er.cur_pic, h->cur_pic_ptr);

        h264_set_erpic(&sl->er.last_pic,

                       sl->ref_count[0] ? sl->ref_list[0][0].parent : NULL);

        h264_set_erpic(&sl->er.next_pic,

                       sl->ref_count[1] ? sl->ref_list[1][0].parent : NULL);

        ff_er_frame_end(&sl->er);

    }

#endif /* CONFIG_ERROR_RESILIENCE */



    emms_c();



    h->current_slice = 0;



    return err;

}

static int audio_read_packet(AVFormatContext *s1, AVPacket *pkt)

{

    AlsaData *s  = s1->priv_data;

    AVStream *st = s1->streams[0];

    int res;

    snd_htimestamp_t timestamp;

    snd_pcm_uframes_t ts_delay;



    if (av_new_packet(pkt, s->period_size) < 0) {

        return AVERROR(EIO);

    }



    while ((res = snd_pcm_readi(s->h, pkt->data, pkt->size / s->frame_size)) < 0) {

        if (res == -EAGAIN) {

            av_free_packet(pkt);



            return AVERROR(EAGAIN);

        }

        if (ff_alsa_xrun_recover(s1, res) < 0) {

            av_log(s1, AV_LOG_ERROR, "ALSA read error: %s\n",

                   snd_strerror(res));

            av_free_packet(pkt);



            return AVERROR(EIO);

        }

    }



    snd_pcm_htimestamp(s->h, &ts_delay, &timestamp);

    ts_delay += res;

    pkt->pts = timestamp.tv_sec * 1000000LL

               + (timestamp.tv_nsec * st->codec->sample_rate

                  - ts_delay * 1000000000LL + st->codec->sample_rate * 500LL)

               / (st->codec->sample_rate * 1000LL);



    pkt->size = res * s->frame_size;



    return 0;

}

static void RENAME(uyvytoyuv422)(uint8_t *ydst, uint8_t *udst, uint8_t *vdst, const uint8_t *src,

                                      long width, long height,

                                      long lumStride, long chromStride, long srcStride)

{

    long y;

    const long chromWidth= -((-width)>>1);



    for (y=0; y<height; y++) {

        RENAME(extract_even)(src+1, ydst, width);

        RENAME(extract_even2)(src, udst, vdst, chromWidth);



        src += srcStride;

        ydst+= lumStride;

        udst+= chromStride;

        vdst+= chromStride;

    }

#if COMPILE_TEMPLATE_MMX

    __asm__(

            EMMS"       \n\t"

            SFENCE"     \n\t"

            ::: "memory"

        );

#endif

}

static int mpc8_decode_init(AVCodecContext * avctx)

{

    int i;

