                 &mpc8_q7_codes[i], 1, 1, INIT_VLC_USE_STATIC);

        init_vlc(&quant_vlc[3][i], MPC8_Q8_BITS, MPC8_Q8_SIZE,

                 &mpc8_q8_bits[i],  1, 1,

                 &mpc8_q8_codes[i], 1, 1, INIT_VLC_USE_STATIC);

    }

    vlc_inited = 1;

