        * of lost slices, MBAFF or threading. */

        if (FIELD_PICTURE(h)) {

            for(i = (h->picture_structure == PICT_BOTTOM_FIELD); i<h->mb_height; i++)

                memset(h->slice_table + i*h->mb_stride, -1, (h->mb_stride - (i+1==h->mb_height)) * sizeof(*h->slice_table));

        } else {

            memset(h->slice_table, -1,

                (h->mb_height * h->mb_stride - 1) * sizeof(*h->slice_table));

        }

        h0->last_slice_type = -1;

    }

    if (h != h0 && (ret = clone_slice(h, h0)) < 0)

        return ret;



    /* can't be in alloc_tables because linesize isn't known there.

     * FIXME: redo bipred weight to not require extra buffer? */

    for (i = 0; i < h->slice_context_count; i++)

        if (h->thread_context[i]) {

            ret = alloc_scratch_buffers(h->thread_context[i], h->linesize);

            if (ret < 0)

                return ret;

        }



    h->cur_pic_ptr->frame_num = h->frame_num; // FIXME frame_num cleanup



    av_assert1(h->mb_num == h->mb_width * h->mb_height);

    if (first_mb_in_slice << FIELD_OR_MBAFF_PICTURE(h) >= h->mb_num ||

        first_mb_in_slice >= h->mb_num) {

        av_log(h->avctx, AV_LOG_ERROR, "first_mb_in_slice overflow\n");

        return AVERROR_INVALIDDATA;

    }

    h->resync_mb_x = h->mb_x =  first_mb_in_slice % h->mb_width;

    h->resync_mb_y = h->mb_y = (first_mb_in_slice / h->mb_width) <<

                               FIELD_OR_MBAFF_PICTURE(h);

    if (h->picture_structure == PICT_BOTTOM_FIELD)

        h->resync_mb_y = h->mb_y = h->mb_y + 1;

    av_assert1(h->mb_y < h->mb_height);



    if (h->picture_structure == PICT_FRAME) {

        h->curr_pic_num = h->frame_num;

        h->max_pic_num  = 1 << h->sps.log2_max_frame_num;

    } else {

        h->curr_pic_num = 2 * h->frame_num + 1;

        h->max_pic_num  = 1 << (h->sps.log2_max_frame_num + 1);

    }



    if (h->nal_unit_type == NAL_IDR_SLICE)

        get_ue_golomb(&h->gb); /* idr_pic_id */



    if (h->sps.poc_type == 0) {

        h->poc_lsb = get_bits(&h->gb, h->sps.log2_max_poc_lsb);



        if (h->pps.pic_order_present == 1 && h->picture_structure == PICT_FRAME)

            h->delta_poc_bottom = get_se_golomb(&h->gb);

    }



    if (h->sps.poc_type == 1 && !h->sps.delta_pic_order_always_zero_flag) {

        h->delta_poc[0] = get_se_golomb(&h->gb);



        if (h->pps.pic_order_present == 1 && h->picture_structure == PICT_FRAME)

            h->delta_poc[1] = get_se_golomb(&h->gb);

    }



    ff_init_poc(h, h->cur_pic_ptr->field_poc, &h->cur_pic_ptr->poc);



    if (h->pps.redundant_pic_cnt_present)

        h->redundant_pic_count = get_ue_golomb(&h->gb);



    ret = ff_set_ref_count(h);

    if (ret < 0)

        return ret;



    if (slice_type != AV_PICTURE_TYPE_I &&

        (h0->current_slice == 0 ||

         slice_type != h0->last_slice_type ||

         memcmp(h0->last_ref_count, h0->ref_count, sizeof(h0->ref_count)))) {



        ff_h264_fill_default_ref_list(h);

    }



    if (h->slice_type_nos != AV_PICTURE_TYPE_I) {

       ret = ff_h264_decode_ref_pic_list_reordering(h);

       if (ret < 0) {

           h->ref_count[1] = h->ref_count[0] = 0;

           return ret;

       }

    }



    if ((h->pps.weighted_pred && h->slice_type_nos == AV_PICTURE_TYPE_P) ||

        (h->pps.weighted_bipred_idc == 1 &&

         h->slice_type_nos == AV_PICTURE_TYPE_B))

        ff_pred_weight_table(h);

    else if (h->pps.weighted_bipred_idc == 2 &&

             h->slice_type_nos == AV_PICTURE_TYPE_B) {

        implicit_weight_table(h, -1);

    } else {

        h->use_weight = 0;

        for (i = 0; i < 2; i++) {

            h->luma_weight_flag[i]   = 0;

            h->chroma_weight_flag[i] = 0;

        }

    }



    // If frame-mt is enabled, only update mmco tables for the first slice

    // in a field. Subsequent slices can temporarily clobber h->mmco_index

    // or h->mmco, which will cause ref list mix-ups and decoding errors

    // further down the line. This may break decoding if the first slice is

    // corrupt, thus we only do this if frame-mt is enabled.

    if (h->nal_ref_idc) {

        ret = ff_h264_decode_ref_pic_marking(h0, &h->gb,

                                             !(h->avctx->active_thread_type & FF_THREAD_FRAME) ||

                                             h0->current_slice == 0);

        if (ret < 0 && (h->avctx->err_recognition & AV_EF_EXPLODE))

            return AVERROR_INVALIDDATA;

    }



    if (FRAME_MBAFF(h)) {

        ff_h264_fill_mbaff_ref_list(h);



        if (h->pps.weighted_bipred_idc == 2 && h->slice_type_nos == AV_PICTURE_TYPE_B) {

            implicit_weight_table(h, 0);

            implicit_weight_table(h, 1);

        }

    }



    if (h->slice_type_nos == AV_PICTURE_TYPE_B && !h->direct_spatial_mv_pred)

        ff_h264_direct_dist_scale_factor(h);

    ff_h264_direct_ref_list_init(h);



    if (h->slice_type_nos != AV_PICTURE_TYPE_I && h->pps.cabac) {

        tmp = get_ue_golomb_31(&h->gb);

        if (tmp > 2) {

            av_log(h->avctx, AV_LOG_ERROR, "cabac_init_idc %u overflow\n", tmp);

            return AVERROR_INVALIDDATA;

        }

        h->cabac_init_idc = tmp;

    }



    h->last_qscale_diff = 0;

    tmp = h->pps.init_qp + get_se_golomb(&h->gb);

    if (tmp > 51 + 6 * (h->sps.bit_depth_luma - 8)) {

        av_log(h->avctx, AV_LOG_ERROR, "QP %u out of range\n", tmp);

        return AVERROR_INVALIDDATA;

    }

    h->qscale       = tmp;

    h->chroma_qp[0] = get_chroma_qp(h, 0, h->qscale);

    h->chroma_qp[1] = get_chroma_qp(h, 1, h->qscale);

    // FIXME qscale / qp ... stuff

    if (h->slice_type == AV_PICTURE_TYPE_SP)

        get_bits1(&h->gb); /* sp_for_switch_flag */

    if (h->slice_type == AV_PICTURE_TYPE_SP ||

        h->slice_type == AV_PICTURE_TYPE_SI)

        get_se_golomb(&h->gb); /* slice_qs_delta */



    h->deblocking_filter     = 1;

    h->slice_alpha_c0_offset = 0;

    h->slice_beta_offset     = 0;

    if (h->pps.deblocking_filter_parameters_present) {

        tmp = get_ue_golomb_31(&h->gb);

        if (tmp > 2) {

            av_log(h->avctx, AV_LOG_ERROR,

                   "deblocking_filter_idc %u out of range\n", tmp);

            return AVERROR_INVALIDDATA;

        }

        h->deblocking_filter = tmp;

        if (h->deblocking_filter < 2)

            h->deblocking_filter ^= 1;  // 1<->0



        if (h->deblocking_filter) {

            h->slice_alpha_c0_offset = get_se_golomb(&h->gb) * 2;

            h->slice_beta_offset     = get_se_golomb(&h->gb) * 2;

            if (h->slice_alpha_c0_offset >  12 ||

                h->slice_alpha_c0_offset < -12 ||

                h->slice_beta_offset >  12     ||

                h->slice_beta_offset < -12) {

                av_log(h->avctx, AV_LOG_ERROR,

                       "deblocking filter parameters %d %d out of range\n",

                       h->slice_alpha_c0_offset, h->slice_beta_offset);

                return AVERROR_INVALIDDATA;

            }

        }

    }



    if (h->avctx->skip_loop_filter >= AVDISCARD_ALL ||

        (h->avctx->skip_loop_filter >= AVDISCARD_NONKEY &&

         h->nal_unit_type != NAL_IDR_SLICE) ||

        (h->avctx->skip_loop_filter >= AVDISCARD_NONINTRA &&

         h->slice_type_nos != AV_PICTURE_TYPE_I) ||

        (h->avctx->skip_loop_filter >= AVDISCARD_BIDIR  &&

         h->slice_type_nos == AV_PICTURE_TYPE_B) ||

        (h->avctx->skip_loop_filter >= AVDISCARD_NONREF &&

         h->nal_ref_idc == 0))

        h->deblocking_filter = 0;



    if (h->deblocking_filter == 1 && h0->max_contexts > 1) {

        if (h->avctx->flags2 & CODEC_FLAG2_FAST) {

            /* Cheat slightly for speed:

             * Do not bother to deblock across slices. */

            h->deblocking_filter = 2;

        } else {

            h0->max_contexts = 1;

            if (!h0->single_decode_warning) {

                av_log(h->avctx, AV_LOG_INFO,

                       "Cannot parallelize deblocking type 1, decoding such frames in sequential order\n");

                h0->single_decode_warning = 1;

            }

            if (h != h0) {

                av_log(h->avctx, AV_LOG_ERROR,

                       "Deblocking switched inside frame.\n");

                return SLICE_SINGLETHREAD;

            }

        }

    }

    h->qp_thresh = 15 -

                   FFMIN(h->slice_alpha_c0_offset, h->slice_beta_offset) -

                   FFMAX3(0,

                          h->pps.chroma_qp_index_offset[0],

                          h->pps.chroma_qp_index_offset[1]) +

                   6 * (h->sps.bit_depth_luma - 8);



    h0->last_slice_type = slice_type;

    memcpy(h0->last_ref_count, h0->ref_count, sizeof(h0->last_ref_count));

    h->slice_num        = ++h0->current_slice;



    if (h->slice_num)

        h0->slice_row[(h->slice_num-1)&(MAX_SLICES-1)]= h->resync_mb_y;

    if (   h0->slice_row[h->slice_num&(MAX_SLICES-1)] + 3 >= h->resync_mb_y

        && h0->slice_row[h->slice_num&(MAX_SLICES-1)] <= h->resync_mb_y

        && h->slice_num >= MAX_SLICES) {

        //in case of ASO this check needs to be updated depending on how we decide to assign slice numbers in this case

        av_log(h->avctx, AV_LOG_WARNING, "Possibly too many slices (%d >= %d), increase MAX_SLICES and recompile if there are artifacts\n", h->slice_num, MAX_SLICES);

    }



    for (j = 0; j < 2; j++) {

        int id_list[16];

        int *ref2frm = h->ref2frm[h->slice_num & (MAX_SLICES - 1)][j];

        for (i = 0; i < 16; i++) {

            id_list[i] = 60;

            if (j < h->list_count && i < h->ref_count[j] &&

                h->ref_list[j][i].f.buf[0]) {

                int k;

                AVBuffer *buf = h->ref_list[j][i].f.buf[0]->buffer;

                for (k = 0; k < h->short_ref_count; k++)

                    if (h->short_ref[k]->f.buf[0]->buffer == buf) {

                        id_list[i] = k;

                        break;

                    }

                for (k = 0; k < h->long_ref_count; k++)

                    if (h->long_ref[k] && h->long_ref[k]->f.buf[0]->buffer == buf) {

                        id_list[i] = h->short_ref_count + k;

                        break;

                    }

            }

        }



        ref2frm[0] =

        ref2frm[1] = -1;

        for (i = 0; i < 16; i++)

            ref2frm[i + 2] = 4 * id_list[i] + (h->ref_list[j][i].reference & 3);

        ref2frm[18 + 0] =

        ref2frm[18 + 1] = -1;

        for (i = 16; i < 48; i++)

            ref2frm[i + 4] = 4 * id_list[(i - 16) >> 1] +

                             (h->ref_list[j][i].reference & 3);

    }



    if (h->ref_count[0]) ff_h264_set_erpic(&h->er.last_pic, &h->ref_list[0][0]);

    if (h->ref_count[1]) ff_h264_set_erpic(&h->er.next_pic, &h->ref_list[1][0]);



    h->er.ref_count = h->ref_count[0];

    h0->au_pps_id = pps_id;

    h->sps.new =

    h0->sps_buffers[h->pps.sps_id]->new = 0;

    h->current_sps_id = h->pps.sps_id;



    if (h->avctx->debug & FF_DEBUG_PICT_INFO) {

        av_log(h->avctx, AV_LOG_DEBUG,

               "slice:%d %s mb:%d %c%s%s pps:%u frame:%d poc:%d/%d ref:%d/%d qp:%d loop:%d:%d:%d weight:%d%s %s\n",

               h->slice_num,

               (h->picture_structure == PICT_FRAME ? "F" : h->picture_structure == PICT_TOP_FIELD ? "T" : "B"),

               first_mb_in_slice,

               av_get_picture_type_char(h->slice_type),

               h->slice_type_fixed ? " fix" : "",

               h->nal_unit_type == NAL_IDR_SLICE ? " IDR" : "",

               pps_id, h->frame_num,

               h->cur_pic_ptr->field_poc[0],

               h->cur_pic_ptr->field_poc[1],

               h->ref_count[0], h->ref_count[1],

               h->qscale,

               h->deblocking_filter,

               h->slice_alpha_c0_offset, h->slice_beta_offset,

               h->use_weight,

               h->use_weight == 1 && h->use_weight_chroma ? "c" : "",

               h->slice_type == AV_PICTURE_TYPE_B ? (h->direct_spatial_mv_pred ? "SPAT" : "TEMP") : "");

    }



    return 0;

}

int ff_init_filters(SwsContext * c)

{

    int i;

    int index;

    int num_ydesc;

    int num_cdesc;

    int num_vdesc = isPlanarYUV(c->dstFormat) && !isGray(c->dstFormat) ? 2 : 1;

    int need_lum_conv = c->lumToYV12 || c->readLumPlanar || c->alpToYV12 || c->readAlpPlanar;

    int need_chr_conv = c->chrToYV12 || c->readChrPlanar;

    int srcIdx, dstIdx;

    int dst_stride = FFALIGN(c->dstW * sizeof(int16_t) + 66, 16);



    uint32_t * pal = usePal(c->srcFormat) ? c->pal_yuv : (uint32_t*)c->input_rgb2yuv_table;

    int res = 0;



    if (c->dstBpc == 16)

        dst_stride <<= 1;



    num_ydesc = need_lum_conv ? 2 : 1;

    num_cdesc = need_chr_conv ? 2 : 1;



    c->numSlice = FFMAX(num_ydesc, num_cdesc) + 2;

    c->numDesc = num_ydesc + num_cdesc + num_vdesc;

    c->descIndex[0] = num_ydesc;

    c->descIndex[1] = num_ydesc + num_cdesc;







    c->desc = av_mallocz_array(sizeof(SwsFilterDescriptor), c->numDesc);

    if (!c->desc)

        return AVERROR(ENOMEM);

    c->slice = av_mallocz_array(sizeof(SwsSlice), c->numSlice);





    res = alloc_slice(&c->slice[0], c->srcFormat, c->srcH, c->chrSrcH, c->chrSrcHSubSample, c->chrSrcVSubSample, 0);

    if (res < 0) goto cleanup;

    for (i = 1; i < c->numSlice-2; ++i) {

        res = alloc_slice(&c->slice[i], c->srcFormat, c->vLumFilterSize + MAX_LINES_AHEAD, c->vChrFilterSize + MAX_LINES_AHEAD, c->chrSrcHSubSample, c->chrSrcVSubSample, 0);

        if (res < 0) goto cleanup;

        res = alloc_lines(&c->slice[i], FFALIGN(c->srcW*2+78, 16), c->srcW);

        if (res < 0) goto cleanup;

    }

    // horizontal scaler output

    res = alloc_slice(&c->slice[i], c->srcFormat, c->vLumFilterSize + MAX_LINES_AHEAD, c->vChrFilterSize + MAX_LINES_AHEAD, c->chrDstHSubSample, c->chrDstVSubSample, 1);

    if (res < 0) goto cleanup;

    res = alloc_lines(&c->slice[i], dst_stride, c->dstW);

    if (res < 0) goto cleanup;



    fill_ones(&c->slice[i], dst_stride>>1, c->dstBpc == 16);



    // vertical scaler output

    ++i;

    res = alloc_slice(&c->slice[i], c->dstFormat, c->dstH, c->chrDstH, c->chrDstHSubSample, c->chrDstVSubSample, 0);

    if (res < 0) goto cleanup;



    index = 0;

    srcIdx = 0;

    dstIdx = 1;



    if (need_lum_conv) {

        ff_init_desc_fmt_convert(&c->desc[index], &c->slice[srcIdx], &c->slice[dstIdx], pal);

        c->desc[index].alpha = c->alpPixBuf != 0;

        ++index;

        srcIdx = dstIdx;

    }





    dstIdx = FFMAX(num_ydesc, num_cdesc);

    ff_init_desc_hscale(&c->desc[index], &c->slice[index], &c->slice[dstIdx], c->hLumFilter, c->hLumFilterPos, c->hLumFilterSize, c->lumXInc);

    c->desc[index].alpha = c->alpPixBuf != 0;





    ++index;

    {

        srcIdx = 0;

        dstIdx = 1;

        if (need_chr_conv) {

            ff_init_desc_cfmt_convert(&c->desc[index], &c->slice[srcIdx], &c->slice[dstIdx], pal);

            ++index;

            srcIdx = dstIdx;

        }



        dstIdx = FFMAX(num_ydesc, num_cdesc);

        if (c->needs_hcscale)

            ff_init_desc_chscale(&c->desc[index], &c->slice[srcIdx], &c->slice[dstIdx], c->hChrFilter, c->hChrFilterPos, c->hChrFilterSize, c->chrXInc);

        else

            ff_init_desc_no_chr(&c->desc[index], &c->slice[srcIdx], &c->slice[dstIdx]);

    }



    ++index;

    {

        srcIdx = c->numSlice - 2;

        dstIdx = c->numSlice - 1;

        ff_init_vscale(c, c->desc + index, c->slice + srcIdx, c->slice + dstIdx);

    }



    return 0;



cleanup:

    ff_free_filters(c);

    return res;

}

static int64_t cache_seek(URLContext *h, int64_t pos, int whence)

{

    Context *c= h->priv_data;



    if (whence == AVSEEK_SIZE) {

        pos= ffurl_seek(c->inner, pos, whence);

        if(pos <= 0){

            pos= ffurl_seek(c->inner, -1, SEEK_END);

            ffurl_seek(c->inner, c->end, SEEK_SET);

            if(pos <= 0)

                return c->end;

        }

        return pos;

    }



    pos= lseek(c->fd, pos, whence);

    if(pos<0){

        return pos;

    }else if(pos <= c->end){

        c->pos= pos;

        return pos;

    }else{

        lseek(c->fd, c->pos, SEEK_SET);

        return AVERROR(EPIPE);

    }

}

static int sonic_encode_frame(AVCodecContext *avctx, AVPacket *avpkt,

                              const AVFrame *frame, int *got_packet_ptr)

{

    SonicContext *s = avctx->priv_data;

    RangeCoder c;

    int i, j, ch, quant = 0, x = 0;

    int ret;

    const short *samples = (const int16_t*)frame->data[0];

    uint8_t state[32];



    if ((ret = ff_alloc_packet2(avctx, avpkt, s->frame_size * 5 + 1000)) < 0)

        return ret;



    ff_init_range_encoder(&c, avpkt->data, avpkt->size);

    ff_build_rac_states(&c, 0.05*(1LL<<32), 256-8);

    memset(state, 128, sizeof(state));



    // short -> internal

    for (i = 0; i < s->frame_size; i++)

        s->int_samples[i] = samples[i];



    if (!s->lossless)

        for (i = 0; i < s->frame_size; i++)

            s->int_samples[i] = s->int_samples[i] << SAMPLE_SHIFT;



    switch(s->decorrelation)

    {

        case MID_SIDE:

            for (i = 0; i < s->frame_size; i += s->channels)

            {

                s->int_samples[i] += s->int_samples[i+1];

                s->int_samples[i+1] -= shift(s->int_samples[i], 1);

            }

            break;

        case LEFT_SIDE:

            for (i = 0; i < s->frame_size; i += s->channels)

                s->int_samples[i+1] -= s->int_samples[i];

            break;

        case RIGHT_SIDE:

            for (i = 0; i < s->frame_size; i += s->channels)

                s->int_samples[i] -= s->int_samples[i+1];

            break;

    }



    memset(s->window, 0, 4* s->window_size);



    for (i = 0; i < s->tail_size; i++)

        s->window[x++] = s->tail[i];



    for (i = 0; i < s->frame_size; i++)

        s->window[x++] = s->int_samples[i];



    for (i = 0; i < s->tail_size; i++)

        s->window[x++] = 0;



    for (i = 0; i < s->tail_size; i++)

        s->tail[i] = s->int_samples[s->frame_size - s->tail_size + i];



    // generate taps

    modified_levinson_durbin(s->window, s->window_size,

                s->predictor_k, s->num_taps, s->channels, s->tap_quant);

    if ((ret = intlist_write(&c, state, s->predictor_k, s->num_taps, 0)) < 0)

        return ret;



    for (ch = 0; ch < s->channels; ch++)

    {

        x = s->tail_size+ch;

        for (i = 0; i < s->block_align; i++)

        {

            int sum = 0;

            for (j = 0; j < s->downsampling; j++, x += s->channels)

                sum += s->window[x];

            s->coded_samples[ch][i] = sum;

        }

    }



    // simple rate control code

    if (!s->lossless)

    {

        double energy1 = 0.0, energy2 = 0.0;

        for (ch = 0; ch < s->channels; ch++)

        {

            for (i = 0; i < s->block_align; i++)

            {

                double sample = s->coded_samples[ch][i];

                energy2 += sample*sample;

                energy1 += fabs(sample);

            }

        }



        energy2 = sqrt(energy2/(s->channels*s->block_align));

        energy1 = M_SQRT2*energy1/(s->channels*s->block_align);



        // increase bitrate when samples are like a gaussian distribution

        // reduce bitrate when samples are like a two-tailed exponential distribution



        if (energy2 > energy1)

            energy2 += (energy2-energy1)*RATE_VARIATION;



        quant = (int)(BASE_QUANT*s->quantization*energy2/SAMPLE_FACTOR);

//        av_log(avctx, AV_LOG_DEBUG, "quant: %d energy: %f / %f\n", quant, energy1, energy2);



        quant = av_clip(quant, 1, 65534);



        put_symbol(&c, state, quant, 0, NULL, NULL);



        quant *= SAMPLE_FACTOR;

    }



    // write out coded samples

    for (ch = 0; ch < s->channels; ch++)

    {

        if (!s->lossless)

            for (i = 0; i < s->block_align; i++)

                s->coded_samples[ch][i] = ROUNDED_DIV(s->coded_samples[ch][i], quant);



        if ((ret = intlist_write(&c, state, s->coded_samples[ch], s->block_align, 1)) < 0)

            return ret;

    }



//    av_log(avctx, AV_LOG_DEBUG, "used bytes: %d\n", (put_bits_count(&pb)+7)/8);



    avpkt->size = ff_rac_terminate(&c);

    *got_packet_ptr = 1;

    return 0;



}

static int read_huffman_tables(HYuvContext *s, uint8_t *src, int length){

    GetBitContext gb;

    int i;



    init_get_bits(&gb, src, length*8);



    for(i=0; i<3; i++){

        read_len_table(s->len[i], &gb);



        if(generate_bits_table(s->bits[i], s->len[i])<0){

            return -1;

        }

#if 0

for(j=0; j<256; j++){

printf("%6X, %2d,  %3d\n", s->bits[i][j], s->len[i][j], j);

}

#endif

        free_vlc(&s->vlc[i]);

        init_vlc(&s->vlc[i], VLC_BITS, 256, s->len[i], 1, 1, s->bits[i], 4, 4, 0);

    }



    generate_joint_tables(s);



    return (get_bits_count(&gb)+7)/8;

}

int ff_hevc_cu_qp_delta_abs(HEVCContext *s)

{

    int prefix_val = 0;

    int suffix_val = 0;

    int inc = 0;



    while (prefix_val < 5 && GET_CABAC(elem_offset[CU_QP_DELTA] + inc)) {

        prefix_val++;

        inc = 1;

    }

    if (prefix_val >= 5) {

        int k = 0;

        while (k < CABAC_MAX_BIN && get_cabac_bypass(&s->HEVClc->cc)) {

            suffix_val += 1 << k;

            k++;

        }

        if (k == CABAC_MAX_BIN)

            av_log(s->avctx, AV_LOG_ERROR, "CABAC_MAX_BIN : %d\n", k);



        while (k--)

            suffix_val += get_cabac_bypass(&s->HEVClc->cc) << k;

    }

    return prefix_val + suffix_val;

}

