{

#if HAVE_TERMIOS_H

    if(!run_as_daemon){

    struct termios tty;



    tcgetattr (0, &tty);

    oldtty = tty;

    atexit(term_exit);



    tty.c_iflag &= ~(IGNBRK|BRKINT|PARMRK|ISTRIP

                          |INLCR|IGNCR|ICRNL|IXON);

