static void png_filter_row(PNGDSPContext *dsp, uint8_t *dst, int filter_type,

                           uint8_t *src, uint8_t *last, int size, int bpp)

{

    int i, p, r, g, b, a;



    switch (filter_type) {

    case PNG_FILTER_VALUE_NONE:

        memcpy(dst, src, size);

        break;

    case PNG_FILTER_VALUE_SUB:

        for (i = 0; i < bpp; i++)

            dst[i] = src[i];

        if (bpp == 4) {

            p = *(int *)dst;

            for (; i < size; i += bpp) {

                unsigned s = *(int *)(src + i);

                p = ((s & 0x7f7f7f7f) + (p & 0x7f7f7f7f)) ^ ((s ^ p) & 0x80808080);

                *(int *)(dst + i) = p;

            }

        } else {

#define OP_SUB(x, s, l) ((x) + (s))

            UNROLL_FILTER(OP_SUB);

        }

        break;

    case PNG_FILTER_VALUE_UP:

        dsp->add_bytes_l2(dst, src, last, size);

        break;

    case PNG_FILTER_VALUE_AVG:

        for (i = 0; i < bpp; i++) {

            p      = (last[i] >> 1);

            dst[i] = p + src[i];

        }

#define OP_AVG(x, s, l) (((((x) + (l)) >> 1) + (s)) & 0xff)

        UNROLL_FILTER(OP_AVG);

        break;

    case PNG_FILTER_VALUE_PAETH:

        for (i = 0; i < bpp; i++) {

            p      = last[i];

            dst[i] = p + src[i];

        }

        if (bpp > 2 && size > 4) {

            /* would write off the end of the array if we let it process

             * the last pixel with bpp=3 */

            int w = bpp == 4 ? size : size - 3;

            dsp->add_paeth_prediction(dst + i, src + i, last + i, w - i, bpp);

            i = w;

        }

        ff_add_png_paeth_prediction(dst + i, src + i, last + i, size - i, bpp);

        break;

    }

}

av_cold int ff_mpv_common_init(MpegEncContext *s)

{

    int i;

    int nb_slices = (HAVE_THREADS &&

                     s->avctx->active_thread_type & FF_THREAD_SLICE) ?

                    s->avctx->thread_count : 1;



    if (s->encoding && s->avctx->slices)

        nb_slices = s->avctx->slices;



    if (s->codec_id == AV_CODEC_ID_MPEG2VIDEO && !s->progressive_sequence)

        s->mb_height = (s->height + 31) / 32 * 2;

    else

        s->mb_height = (s->height + 15) / 16;



    if (s->avctx->pix_fmt == AV_PIX_FMT_NONE) {

        av_log(s->avctx, AV_LOG_ERROR,

               "decoding to AV_PIX_FMT_NONE is not supported.\n");

        return -1;

    }



    if (nb_slices > MAX_THREADS || (nb_slices > s->mb_height && s->mb_height)) {

        int max_slices;

        if (s->mb_height)

            max_slices = FFMIN(MAX_THREADS, s->mb_height);

        else

            max_slices = MAX_THREADS;

        av_log(s->avctx, AV_LOG_WARNING, "too many threads/slices (%d),"

               " reducing to %d\n", nb_slices, max_slices);

        nb_slices = max_slices;

    }



    if ((s->width || s->height) &&

        av_image_check_size(s->width, s->height, 0, s->avctx))

        return -1;



    dct_init(s);



    /* set chroma shifts */

    avcodec_get_chroma_sub_sample(s->avctx->pix_fmt,

                                  &s->chroma_x_shift,

                                  &s->chroma_y_shift);





    FF_ALLOCZ_OR_GOTO(s->avctx, s->picture,

                      MAX_PICTURE_COUNT * sizeof(Picture), fail);

    for (i = 0; i < MAX_PICTURE_COUNT; i++) {

        s->picture[i].f = av_frame_alloc();

        if (!s->picture[i].f)

            goto fail;

    }

    memset(&s->next_picture, 0, sizeof(s->next_picture));

    memset(&s->last_picture, 0, sizeof(s->last_picture));

    memset(&s->current_picture, 0, sizeof(s->current_picture));

    memset(&s->new_picture, 0, sizeof(s->new_picture));

    s->next_picture.f = av_frame_alloc();

    if (!s->next_picture.f)

        goto fail;

    s->last_picture.f = av_frame_alloc();

    if (!s->last_picture.f)

        goto fail;

    s->current_picture.f = av_frame_alloc();

    if (!s->current_picture.f)

        goto fail;

    s->new_picture.f = av_frame_alloc();

    if (!s->new_picture.f)

        goto fail;



        if (init_context_frame(s))

            goto fail;



        s->parse_context.state = -1;



        s->context_initialized = 1;

        memset(s->thread_context, 0, sizeof(s->thread_context));

        s->thread_context[0]   = s;



//     if (s->width && s->height) {

        if (nb_slices > 1) {

            for (i = 0; i < nb_slices; i++) {

                if (i) {

                    s->thread_context[i] = av_memdup(s, sizeof(MpegEncContext));

                    if (!s->thread_context[i])

                        goto fail;

                }

                if (init_duplicate_context(s->thread_context[i]) < 0)

                    goto fail;

                    s->thread_context[i]->start_mb_y =

                        (s->mb_height * (i) + nb_slices / 2) / nb_slices;

                    s->thread_context[i]->end_mb_y   =

                        (s->mb_height * (i + 1) + nb_slices / 2) / nb_slices;

            }

        } else {

            if (init_duplicate_context(s) < 0)

                goto fail;

            s->start_mb_y = 0;

            s->end_mb_y   = s->mb_height;

        }

        s->slice_context_count = nb_slices;

//     }



    return 0;

 fail:

    ff_mpv_common_end(s);

    return -1;

}

int ff_socket(int af, int type, int proto)

{

    int fd;



#ifdef SOCK_CLOEXEC

    fd = socket(af, type | SOCK_CLOEXEC, proto);

    if (fd == -1 && errno == EINVAL)

#endif

    {

        fd = socket(af, type, proto);

#if HAVE_FCNTL

        if (fd != -1)

            fcntl(fd, F_SETFD, FD_CLOEXEC);

#endif

    }

    return fd;

}

static int nuv_header(AVFormatContext *s)

{

    NUVContext *ctx = s->priv_data;

    AVIOContext *pb = s->pb;

    char id_string[12];

    double aspect, fps;

    int is_mythtv, width, height, v_packs, a_packs;

    AVStream *vst = NULL, *ast = NULL;



    avio_read(pb, id_string, 12);

    is_mythtv = !memcmp(id_string, "MythTVVideo", 12);

    avio_skip(pb, 5);       // version string

    avio_skip(pb, 3);       // padding

    width  = avio_rl32(pb);

    height = avio_rl32(pb);

    avio_rl32(pb);          // unused, "desiredwidth"

    avio_rl32(pb);          // unused, "desiredheight"

    avio_r8(pb);            // 'P' == progressive, 'I' == interlaced

    avio_skip(pb, 3);       // padding

    aspect = av_int2double(avio_rl64(pb));

    if (aspect > 0.9999 && aspect < 1.0001)

        aspect = 4.0 / 3.0;

    fps = av_int2double(avio_rl64(pb));



    // number of packets per stream type, -1 means unknown, e.g. streaming

    v_packs = avio_rl32(pb);

    a_packs = avio_rl32(pb);

    avio_rl32(pb); // text



    avio_rl32(pb); // keyframe distance (?)



    if (v_packs) {

        vst = avformat_new_stream(s, NULL);

        if (!vst)

            return AVERROR(ENOMEM);

        ctx->v_id = vst->index;



        vst->codec->codec_type            = AVMEDIA_TYPE_VIDEO;

        vst->codec->codec_id              = AV_CODEC_ID_NUV;

        vst->codec->width                 = width;

        vst->codec->height                = height;

        vst->codec->bits_per_coded_sample = 10;

        vst->sample_aspect_ratio          = av_d2q(aspect * height / width,

                                                   10000);

#if FF_API_R_FRAME_RATE

        vst->r_frame_rate =

#endif

        vst->avg_frame_rate = av_d2q(fps, 60000);

        avpriv_set_pts_info(vst, 32, 1, 1000);

    } else

        ctx->v_id = -1;



    if (a_packs) {

        ast = avformat_new_stream(s, NULL);

        if (!ast)

            return AVERROR(ENOMEM);

        ctx->a_id = ast->index;



        ast->codec->codec_type            = AVMEDIA_TYPE_AUDIO;

        ast->codec->codec_id              = AV_CODEC_ID_PCM_S16LE;

        ast->codec->channels              = 2;

        ast->codec->channel_layout        = AV_CH_LAYOUT_STEREO;

        ast->codec->sample_rate           = 44100;

        ast->codec->bit_rate              = 2 * 2 * 44100 * 8;

        ast->codec->block_align           = 2 * 2;

        ast->codec->bits_per_coded_sample = 16;

        avpriv_set_pts_info(ast, 32, 1, 1000);

    } else

        ctx->a_id = -1;



    get_codec_data(pb, vst, ast, is_mythtv);

    ctx->rtjpg_video = vst && vst->codec->codec_id == AV_CODEC_ID_NUV;



    return 0;

}

static int dfa_probe(AVProbeData *p)
{
    if (p->buf_size < 4 || AV_RL32(p->buf) != MKTAG('D', 'F', 'I', 'A'))
        return 0;
    return AVPROBE_SCORE_MAX;
}

static int decode_mb(H264Context *h){

    MpegEncContext * const s = &h->s;

    const int mb_xy= s->mb_x + s->mb_y*s->mb_stride;

    int mb_type, partition_count, cbp;



    s->dsp.clear_blocks(h->mb); //FIXME avoid if allready clear (move after skip handlong?    



    tprintf("pic:%d mb:%d/%d\n", h->frame_num, s->mb_x, s->mb_y);

    cbp = 0; /* avoid warning. FIXME: find a solution without slowing

                down the code */

    if(h->slice_type != I_TYPE && h->slice_type != SI_TYPE){

        if(s->mb_skip_run==-1)

            s->mb_skip_run= get_ue_golomb(&s->gb);



        if (s->mb_skip_run--) {

            int mx, my;

            /* skip mb */

//FIXME b frame

            mb_type= MB_TYPE_16x16|MB_TYPE_P0L0|MB_TYPE_P1L0;



            memset(h->non_zero_count[mb_xy], 0, 16+4+4);

            memset(h->non_zero_count_cache + 8, 0, 8*5); //FIXME ugly, remove pfui



            if(h->sps.mb_aff && s->mb_skip_run==0 && (s->mb_y&1)==0){

                h->mb_field_decoding_flag= get_bits1(&s->gb);

            }



            if(h->mb_field_decoding_flag)

                mb_type|= MB_TYPE_INTERLACED;



            fill_caches(h, mb_type); //FIXME check what is needed and what not ...

            pred_pskip_motion(h, &mx, &my);

            fill_rectangle(&h->ref_cache[0][scan8[0]], 4, 4, 8, 0, 1);

            fill_rectangle(  h->mv_cache[0][scan8[0]], 4, 4, 8, pack16to32(mx,my), 4);

            write_back_motion(h, mb_type);



            s->current_picture.mb_type[mb_xy]= mb_type; //FIXME SKIP type

            s->current_picture.qscale_table[mb_xy]= s->qscale;

            h->slice_table[ mb_xy ]= h->slice_num;



            h->prev_mb_skiped= 1;

            return 0;

        }

    }

    if(h->sps.mb_aff /* && !field pic FIXME needed? */){

        if((s->mb_y&1)==0)

            h->mb_field_decoding_flag = get_bits1(&s->gb);

    }else

        h->mb_field_decoding_flag=0; //FIXME som ed note ?!



    h->prev_mb_skiped= 0;



    mb_type= get_ue_golomb(&s->gb);

    if(h->slice_type == B_TYPE){

        if(mb_type < 23){

            partition_count= b_mb_type_info[mb_type].partition_count;

            mb_type=         b_mb_type_info[mb_type].type;

        }else{

            mb_type -= 23;

            goto decode_intra_mb;

        }

    }else if(h->slice_type == P_TYPE /*|| h->slice_type == SP_TYPE */){

        if(mb_type < 5){

            partition_count= p_mb_type_info[mb_type].partition_count;

            mb_type=         p_mb_type_info[mb_type].type;

        }else{

            mb_type -= 5;

            goto decode_intra_mb;

        }

    }else{

       assert(h->slice_type == I_TYPE);

decode_intra_mb:

        if(mb_type > 25){

            av_log(h->s.avctx, AV_LOG_ERROR, "mb_type %d in %c slice to large at %d %d\n", mb_type, av_get_pict_type_char(h->slice_type), s->mb_x, s->mb_y);

            return -1;

        }

        partition_count=0;

        cbp= i_mb_type_info[mb_type].cbp;

        h->intra16x16_pred_mode= i_mb_type_info[mb_type].pred_mode;

        mb_type= i_mb_type_info[mb_type].type;

    }



    if(h->mb_field_decoding_flag)

        mb_type |= MB_TYPE_INTERLACED;



    s->current_picture.mb_type[mb_xy]= mb_type;

    h->slice_table[ mb_xy ]= h->slice_num;



    if(IS_INTRA_PCM(mb_type)){

        const uint8_t *ptr;

        int x, y;



        // we assume these blocks are very rare so we dont optimize it

        align_get_bits(&s->gb);



        ptr= s->gb.buffer + get_bits_count(&s->gb);



        for(y=0; y<16; y++){

            const int index= 4*(y&3) + 64*(y>>2);

            for(x=0; x<16; x++){

                h->mb[index + (x&3) + 16*(x>>2)]= *(ptr++);

            }

        }

        for(y=0; y<8; y++){

            const int index= 256 + 4*(y&3) + 32*(y>>2);

            for(x=0; x<8; x++){

                h->mb[index + (x&3) + 16*(x>>2)]= *(ptr++);

            }

        }

        for(y=0; y<8; y++){

            const int index= 256 + 64 + 4*(y&3) + 32*(y>>2);

            for(x=0; x<8; x++){

                h->mb[index + (x&3) + 16*(x>>2)]= *(ptr++);

            }

        }



        skip_bits(&s->gb, 384); //FIXME check /fix the bitstream readers



        memset(h->non_zero_count[mb_xy], 16, 16+4+4);

        s->current_picture.qscale_table[mb_xy]= s->qscale;



        return 0;

    }



    fill_caches(h, mb_type);



    //mb_pred

    if(IS_INTRA(mb_type)){

//            init_top_left_availability(h);

            if(IS_INTRA4x4(mb_type)){

                int i;



//                fill_intra4x4_pred_table(h);

                for(i=0; i<16; i++){

                    const int mode_coded= !get_bits1(&s->gb);

                    const int predicted_mode=  pred_intra_mode(h, i);

                    int mode;



                    if(mode_coded){

                        const int rem_mode= get_bits(&s->gb, 3);

                        if(rem_mode<predicted_mode)

                            mode= rem_mode;

                        else

                            mode= rem_mode + 1;

                    }else{

                        mode= predicted_mode;

                    }



                    h->intra4x4_pred_mode_cache[ scan8[i] ] = mode;

                }

                write_back_intra_pred_mode(h);

                if( check_intra4x4_pred_mode(h) < 0)

                    return -1;

            }else{

                h->intra16x16_pred_mode= check_intra_pred_mode(h, h->intra16x16_pred_mode);

                if(h->intra16x16_pred_mode < 0)

                    return -1;

            }

            h->chroma_pred_mode= get_ue_golomb(&s->gb);



            h->chroma_pred_mode= check_intra_pred_mode(h, h->chroma_pred_mode);

            if(h->chroma_pred_mode < 0)

                return -1;

    }else if(partition_count==4){

        int i, j, sub_partition_count[4], list, ref[2][4];



        if(h->slice_type == B_TYPE){

            for(i=0; i<4; i++){

                h->sub_mb_type[i]= get_ue_golomb(&s->gb);

                if(h->sub_mb_type[i] >=13){

                    av_log(h->s.avctx, AV_LOG_ERROR, "B sub_mb_type %d out of range at %d %d\n", h->sub_mb_type[i], s->mb_x, s->mb_y);

                    return -1;

                }

                sub_partition_count[i]= b_sub_mb_type_info[ h->sub_mb_type[i] ].partition_count;

                h->sub_mb_type[i]=      b_sub_mb_type_info[ h->sub_mb_type[i] ].type;

            }

        }else{

            assert(h->slice_type == P_TYPE || h->slice_type == SP_TYPE); //FIXME SP correct ?

            for(i=0; i<4; i++){

                h->sub_mb_type[i]= get_ue_golomb(&s->gb);

                if(h->sub_mb_type[i] >=4){

                    av_log(h->s.avctx, AV_LOG_ERROR, "P sub_mb_type %d out of range at %d %d\n", h->sub_mb_type[i], s->mb_x, s->mb_y);

                    return -1;

                }

                sub_partition_count[i]= p_sub_mb_type_info[ h->sub_mb_type[i] ].partition_count;

                h->sub_mb_type[i]=      p_sub_mb_type_info[ h->sub_mb_type[i] ].type;

            }

        }



        for(list=0; list<2; list++){

            const int ref_count= IS_REF0(mb_type) ? 1 : h->ref_count[list];

            if(ref_count == 0) continue;

            for(i=0; i<4; i++){

                if(IS_DIR(h->sub_mb_type[i], 0, list) && !IS_DIRECT(h->sub_mb_type[i])){

                    ref[list][i] = get_te0_golomb(&s->gb, ref_count); //FIXME init to 0 before and skip?

                }else{

                 //FIXME

                    ref[list][i] = -1;

                }

            }

        }



        for(list=0; list<2; list++){

            const int ref_count= IS_REF0(mb_type) ? 1 : h->ref_count[list];

            if(ref_count == 0) continue;



            for(i=0; i<4; i++){

                h->ref_cache[list][ scan8[4*i]   ]=h->ref_cache[list][ scan8[4*i]+1 ]=

                h->ref_cache[list][ scan8[4*i]+8 ]=h->ref_cache[list][ scan8[4*i]+9 ]= ref[list][i];



                if(IS_DIR(h->sub_mb_type[i], 0, list) && !IS_DIRECT(h->sub_mb_type[i])){

                    const int sub_mb_type= h->sub_mb_type[i];

                    const int block_width= (sub_mb_type & (MB_TYPE_16x16|MB_TYPE_16x8)) ? 2 : 1;

                    for(j=0; j<sub_partition_count[i]; j++){

                        int mx, my;

                        const int index= 4*i + block_width*j;

                        int16_t (* mv_cache)[2]= &h->mv_cache[list][ scan8[index] ];

                        pred_motion(h, index, block_width, list, h->ref_cache[list][ scan8[index] ], &mx, &my);

                        mx += get_se_golomb(&s->gb);

                        my += get_se_golomb(&s->gb);

                        tprintf("final mv:%d %d\n", mx, my);



                        if(IS_SUB_8X8(sub_mb_type)){

                            mv_cache[ 0 ][0]= mv_cache[ 1 ][0]= 

                            mv_cache[ 8 ][0]= mv_cache[ 9 ][0]= mx;

                            mv_cache[ 0 ][1]= mv_cache[ 1 ][1]= 

                            mv_cache[ 8 ][1]= mv_cache[ 9 ][1]= my;

                        }else if(IS_SUB_8X4(sub_mb_type)){

                            mv_cache[ 0 ][0]= mv_cache[ 1 ][0]= mx;

                            mv_cache[ 0 ][1]= mv_cache[ 1 ][1]= my;

                        }else if(IS_SUB_4X8(sub_mb_type)){

                            mv_cache[ 0 ][0]= mv_cache[ 8 ][0]= mx;

                            mv_cache[ 0 ][1]= mv_cache[ 8 ][1]= my;

                        }else{

                            assert(IS_SUB_4X4(sub_mb_type));

                            mv_cache[ 0 ][0]= mx;

                            mv_cache[ 0 ][1]= my;

                        }

                    }

                }else{

                    uint32_t *p= (uint32_t *)&h->mv_cache[list][ scan8[4*i] ][0];

                    p[0] = p[1]=

                    p[8] = p[9]= 0;

                }

            }

        }

    }else if(!IS_DIRECT(mb_type)){

        int list, mx, my, i;

         //FIXME we should set ref_idx_l? to 0 if we use that later ...

        if(IS_16X16(mb_type)){

            for(list=0; list<2; list++){

                if(h->ref_count[0]>0){

                    if(IS_DIR(mb_type, 0, list)){

                        const int val= get_te0_golomb(&s->gb, h->ref_count[list]);

                        fill_rectangle(&h->ref_cache[list][ scan8[0] ], 4, 4, 8, val, 1);

                    }

                }

            }

            for(list=0; list<2; list++){

                if(IS_DIR(mb_type, 0, list)){

                    pred_motion(h, 0, 4, list, h->ref_cache[list][ scan8[0] ], &mx, &my);

                    mx += get_se_golomb(&s->gb);

                    my += get_se_golomb(&s->gb);

                    tprintf("final mv:%d %d\n", mx, my);



                    fill_rectangle(h->mv_cache[list][ scan8[0] ], 4, 4, 8, pack16to32(mx,my), 4);

                }

            }

        }

        else if(IS_16X8(mb_type)){

            for(list=0; list<2; list++){

                if(h->ref_count[list]>0){

                    for(i=0; i<2; i++){

                        if(IS_DIR(mb_type, i, list)){

                            const int val= get_te0_golomb(&s->gb, h->ref_count[list]);

                            fill_rectangle(&h->ref_cache[list][ scan8[0] + 16*i ], 4, 2, 8, val, 1);

                        }

                    }

                }

            }

            for(list=0; list<2; list++){

                for(i=0; i<2; i++){

                    if(IS_DIR(mb_type, i, list)){

                        pred_16x8_motion(h, 8*i, list, h->ref_cache[list][scan8[0] + 16*i], &mx, &my);

                        mx += get_se_golomb(&s->gb);

                        my += get_se_golomb(&s->gb);

                        tprintf("final mv:%d %d\n", mx, my);



                        fill_rectangle(h->mv_cache[list][ scan8[0] + 16*i ], 4, 2, 8, pack16to32(mx,my), 4);

                    }

                }

            }

        }else{

            assert(IS_8X16(mb_type));

            for(list=0; list<2; list++){

                if(h->ref_count[list]>0){

                    for(i=0; i<2; i++){

                        if(IS_DIR(mb_type, i, list)){ //FIXME optimize

                            const int val= get_te0_golomb(&s->gb, h->ref_count[list]);

                            fill_rectangle(&h->ref_cache[list][ scan8[0] + 2*i ], 2, 4, 8, val, 1);

                        }

                    }

                }

            }

            for(list=0; list<2; list++){

                for(i=0; i<2; i++){

                    if(IS_DIR(mb_type, i, list)){

                        pred_8x16_motion(h, i*4, list, h->ref_cache[list][ scan8[0] + 2*i ], &mx, &my);

                        mx += get_se_golomb(&s->gb);

                        my += get_se_golomb(&s->gb);

                        tprintf("final mv:%d %d\n", mx, my);



                        fill_rectangle(h->mv_cache[list][ scan8[0] + 2*i ], 2, 4, 8, pack16to32(mx,my), 4);

                    }

                }

            }

        }

    }



    if(IS_INTER(mb_type))

        write_back_motion(h, mb_type);



    if(!IS_INTRA16x16(mb_type)){

        cbp= get_ue_golomb(&s->gb);

        if(cbp > 47){

            av_log(h->s.avctx, AV_LOG_ERROR, "cbp too large (%d) at %d %d\n", cbp, s->mb_x, s->mb_y);

            return -1;

        }



        if(IS_INTRA4x4(mb_type))

            cbp= golomb_to_intra4x4_cbp[cbp];

        else

            cbp= golomb_to_inter_cbp[cbp];

    }



    if(cbp || IS_INTRA16x16(mb_type)){

        int i8x8, i4x4, chroma_idx;

        int chroma_qp, dquant;

        GetBitContext *gb= IS_INTRA(mb_type) ? h->intra_gb_ptr : h->inter_gb_ptr;

        const uint8_t *scan, *dc_scan;



//        fill_non_zero_count_cache(h);



        if(IS_INTERLACED(mb_type)){

            scan= field_scan;

            dc_scan= luma_dc_field_scan;

        }else{

            scan= zigzag_scan;

            dc_scan= luma_dc_zigzag_scan;

        }



        dquant= get_se_golomb(&s->gb);



        if( dquant > 25 || dquant < -26 ){

            av_log(h->s.avctx, AV_LOG_ERROR, "dquant out of range (%d) at %d %d\n", dquant, s->mb_x, s->mb_y);

            return -1;

        }



        s->qscale += dquant;

        if(((unsigned)s->qscale) > 51){

            if(s->qscale<0) s->qscale+= 52;

            else            s->qscale-= 52;

        }



        h->chroma_qp= chroma_qp= get_chroma_qp(h, s->qscale);

        if(IS_INTRA16x16(mb_type)){

            if( decode_residual(h, h->intra_gb_ptr, h->mb, LUMA_DC_BLOCK_INDEX, dc_scan, s->qscale, 16) < 0){

                return -1; //FIXME continue if partotioned and other retirn -1 too

            }



            assert((cbp&15) == 0 || (cbp&15) == 15);



            if(cbp&15){

                for(i8x8=0; i8x8<4; i8x8++){

                    for(i4x4=0; i4x4<4; i4x4++){

                        const int index= i4x4 + 4*i8x8;

                        if( decode_residual(h, h->intra_gb_ptr, h->mb + 16*index, index, scan + 1, s->qscale, 15) < 0 ){

                            return -1;

                        }

                    }

                }

            }else{

                fill_rectangle(&h->non_zero_count_cache[scan8[0]], 4, 4, 8, 0, 1);

            }

        }else{

            for(i8x8=0; i8x8<4; i8x8++){

                if(cbp & (1<<i8x8)){

                    for(i4x4=0; i4x4<4; i4x4++){

                        const int index= i4x4 + 4*i8x8;



                        if( decode_residual(h, gb, h->mb + 16*index, index, scan, s->qscale, 16) <0 ){

                            return -1;

                        }

                    }

                }else{

                    uint8_t * const nnz= &h->non_zero_count_cache[ scan8[4*i8x8] ];

                    nnz[0] = nnz[1] = nnz[8] = nnz[9] = 0;

                }

            }

        }



        if(cbp&0x30){

            for(chroma_idx=0; chroma_idx<2; chroma_idx++)

                if( decode_residual(h, gb, h->mb + 256 + 16*4*chroma_idx, CHROMA_DC_BLOCK_INDEX, chroma_dc_scan, chroma_qp, 4) < 0){

                    return -1;

                }

        }



        if(cbp&0x20){

            for(chroma_idx=0; chroma_idx<2; chroma_idx++){

                for(i4x4=0; i4x4<4; i4x4++){

                    const int index= 16 + 4*chroma_idx + i4x4;

                    if( decode_residual(h, gb, h->mb + 16*index, index, scan + 1, chroma_qp, 15) < 0){

                        return -1;

                    }

                }

            }

        }else{

            uint8_t * const nnz= &h->non_zero_count_cache[0];

            nnz[ scan8[16]+0 ] = nnz[ scan8[16]+1 ] =nnz[ scan8[16]+8 ] =nnz[ scan8[16]+9 ] =

            nnz[ scan8[20]+0 ] = nnz[ scan8[20]+1 ] =nnz[ scan8[20]+8 ] =nnz[ scan8[20]+9 ] = 0;

        }

    }else{

        memset(&h->non_zero_count_cache[8], 0, 8*5);

    }

    s->current_picture.qscale_table[mb_xy]= s->qscale;

    write_back_non_zero_count(h);



    return 0;

}

static void decode_vui(GetBitContext *gb, AVCodecContext *avctx,

                       int apply_defdispwin, HEVCSPS *sps)

{

    VUI *vui          = &sps->vui;

    int sar_present;



    av_log(avctx, AV_LOG_DEBUG, "Decoding VUI\n");



    sar_present = get_bits1(gb);

    if (sar_present) {

        uint8_t sar_idx = get_bits(gb, 8);

        if (sar_idx < FF_ARRAY_ELEMS(vui_sar))

            vui->sar = vui_sar[sar_idx];

        else if (sar_idx == 255) {

            vui->sar.num = get_bits(gb, 16);

            vui->sar.den = get_bits(gb, 16);

        } else

            av_log(avctx, AV_LOG_WARNING,

                   "Unknown SAR index: %u.\n", sar_idx);

    }



    vui->overscan_info_present_flag = get_bits1(gb);

    if (vui->overscan_info_present_flag)

        vui->overscan_appropriate_flag = get_bits1(gb);



    vui->video_signal_type_present_flag = get_bits1(gb);

    if (vui->video_signal_type_present_flag) {

        vui->video_format                    = get_bits(gb, 3);

        vui->video_full_range_flag           = get_bits1(gb);

        vui->colour_description_present_flag = get_bits1(gb);

        if (vui->video_full_range_flag && sps->pix_fmt == AV_PIX_FMT_YUV420P)

            sps->pix_fmt = AV_PIX_FMT_YUVJ420P;

        if (vui->colour_description_present_flag) {

            vui->colour_primaries        = get_bits(gb, 8);

            vui->transfer_characteristic = get_bits(gb, 8);

            vui->matrix_coeffs           = get_bits(gb, 8);



            // Set invalid values to "unspecified"

            if (vui->colour_primaries >= AVCOL_PRI_NB)

                vui->colour_primaries = AVCOL_PRI_UNSPECIFIED;

            if (vui->transfer_characteristic >= AVCOL_TRC_NB)

                vui->transfer_characteristic = AVCOL_TRC_UNSPECIFIED;

            if (vui->matrix_coeffs >= AVCOL_SPC_NB)

                vui->matrix_coeffs = AVCOL_SPC_UNSPECIFIED;

        }

    }



    vui->chroma_loc_info_present_flag = get_bits1(gb);

    if (vui->chroma_loc_info_present_flag) {

        vui->chroma_sample_loc_type_top_field    = get_ue_golomb_long(gb);

        vui->chroma_sample_loc_type_bottom_field = get_ue_golomb_long(gb);

    }



    vui->neutra_chroma_indication_flag = get_bits1(gb);

    vui->field_seq_flag                = get_bits1(gb);

