int ff_amf_tag_size(const uint8_t *data, const uint8_t *data_end)

{

    const uint8_t *base = data;



    if (data >= data_end)

        return -1;

    switch (*data++) {

    case AMF_DATA_TYPE_NUMBER:      return 9;

    case AMF_DATA_TYPE_BOOL:        return 2;

    case AMF_DATA_TYPE_STRING:      return 3 + AV_RB16(data);

    case AMF_DATA_TYPE_LONG_STRING: return 5 + AV_RB32(data);

    case AMF_DATA_TYPE_NULL:        return 1;

    case AMF_DATA_TYPE_ARRAY:

        data += 4;

    case AMF_DATA_TYPE_OBJECT:

        for (;;) {

            int size = bytestream_get_be16(&data);

            int t;

            if (!size) {

                data++;

                break;

            }

            if (data + size >= data_end || data + size < data)

                return -1;

            data += size;

            t = ff_amf_tag_size(data, data_end);

            if (t < 0 || data + t >= data_end)

                return -1;

            data += t;

        }

        return data - base;

    case AMF_DATA_TYPE_OBJECT_END:  return 1;

    default:                        return -1;

    }

}

static int v4l2_read_header(AVFormatContext *s1, AVFormatParameters *ap)

{

    struct video_data *s = s1->priv_data;

    AVStream *st;

    int width, height;

    int res, frame_rate, frame_rate_base;

    uint32_t desired_format, capabilities;



    if (ap->width <= 0 || ap->height <= 0 || ap->time_base.den <= 0) {

        av_log(s1, AV_LOG_ERROR, "Missing/Wrong width, height or framerate\n");



        return -1;

    }



    width = ap->width;

    height = ap->height;

    frame_rate = ap->time_base.den;

    frame_rate_base = ap->time_base.num;



    if((unsigned)width > 32767 || (unsigned)height > 32767) {

        av_log(s1, AV_LOG_ERROR, "Wrong size %dx%d\n", width, height);



        return -1;

    }



    st = av_new_stream(s1, 0);

    if (!st) {

        return AVERROR(ENOMEM);

    }

    av_set_pts_info(st, 64, 1, 1000000); /* 64 bits pts in us */



    s->width = width;

    s->height = height;

    s->frame_rate      = frame_rate;

    s->frame_rate_base = frame_rate_base;



    capabilities = 0;

    s->fd = device_open(s1, &capabilities);

    if (s->fd < 0) {

        av_free(st);



        return AVERROR(EIO);

    }

    av_log(s1, AV_LOG_INFO, "[%d]Capabilities: %x\n", s->fd, capabilities);



    desired_format = fmt_ff2v4l(ap->pix_fmt);

    if (desired_format == 0 || (device_init(s1, &width, &height, desired_format) < 0)) {

        int i, done;



        done = 0; i = 0;

        while (!done) {

            desired_format = fmt_conversion_table[i].v4l2_fmt;

            if (device_init(s1, &width, &height, desired_format) < 0) {

                desired_format = 0;

                i++;

            } else {

               done = 1;

            }

            if (i == sizeof(fmt_conversion_table) / sizeof(struct fmt_map)) {

               done = 1;

            }

        }

    }

    if (desired_format == 0) {

        av_log(s1, AV_LOG_ERROR, "Cannot find a proper format.\n");

        close(s->fd);

        av_free(st);



        return AVERROR(EIO);

    }

    s->frame_format = desired_format;



    if( v4l2_set_parameters( s1, ap ) < 0 )

        return AVERROR(EIO);



    st->codec->pix_fmt = fmt_v4l2ff(desired_format);

    s->frame_size = avpicture_get_size(st->codec->pix_fmt, width, height);

    if (capabilities & V4L2_CAP_STREAMING) {

        s->io_method = io_mmap;

        res = mmap_init(s1);

        if (res == 0) {

            res = mmap_start(s1);

        }

    } else {

        s->io_method = io_read;

        res = read_init(s1);

    }

    if (res < 0) {

        close(s->fd);

        av_free(st);



        return AVERROR(EIO);

    }

    s->top_field_first = first_field(s->fd);



    st->codec->codec_type = CODEC_TYPE_VIDEO;

    st->codec->codec_id = CODEC_ID_RAWVIDEO;

    st->codec->width = width;

    st->codec->height = height;

    st->codec->time_base.den = frame_rate;

    st->codec->time_base.num = frame_rate_base;

    st->codec->bit_rate = s->frame_size * 1/av_q2d(st->codec->time_base) * 8;



    return 0;

}

static unsigned decode_skip_count(GetBitContext* gb)

{

    unsigned value;

    // This function reads a maximum of 23 bits,

    // which is within the padding space

    if (!can_safely_read(gb, 1))

        return -1;

    value = get_bits1(gb);

    if (!value)

        return value;



    value += get_bits(gb, 3);

    if (value != (1 + ((1 << 3) - 1)))

        return value;



    value += get_bits(gb, 7);

    if (value != (1 + ((1 << 3) - 1)) + ((1 << 7) - 1))

        return value;



    return value + get_bits(gb, 12);

}

static int check_init_output_file(OutputFile *of, int file_index)

{

    int ret, i;



    for (i = 0; i < of->ctx->nb_streams; i++) {

        OutputStream *ost = output_streams[of->ost_index + i];

        if (!ost->initialized)

            return 0;

    }



    of->ctx->interrupt_callback = int_cb;



    ret = avformat_write_header(of->ctx, &of->opts);

    if (ret < 0) {

        av_log(NULL, AV_LOG_ERROR,

               "Could not write header for output file #%d "

               "(incorrect codec parameters ?): %s\n",

               file_index, av_err2str(ret));

        return ret;

    }

    //assert_avoptions(of->opts);

    of->header_written = 1;



    av_dump_format(of->ctx, file_index, of->ctx->filename, 1);



    if (sdp_filename || want_sdp)

        print_sdp();



    /* flush the muxing queues */

    for (i = 0; i < of->ctx->nb_streams; i++) {

        OutputStream *ost = output_streams[of->ost_index + i];



        /* try to improve muxing time_base (only possible if nothing has been written yet) */

        if (!av_fifo_size(ost->muxing_queue))

            ost->mux_timebase = ost->st->time_base;



        while (av_fifo_size(ost->muxing_queue)) {

            AVPacket pkt;

            av_fifo_generic_read(ost->muxing_queue, &pkt, sizeof(pkt), NULL);

            write_packet(of, &pkt, ost);

        }

    }



    return 0;

}

static int read_uncompressed_sgi(unsigned char* out_buf, SgiState *s)

{

    int x, y, z;

    unsigned int offset = s->height * s->width * s->bytes_per_channel;

    GetByteContext gp[4];

    uint8_t *out_end;



    /* Test buffer size. */

    if (offset * s->depth > bytestream2_get_bytes_left(&s->g))

        return AVERROR_INVALIDDATA;



    /* Create a reader for each plane */

    for (z = 0; z < s->depth; z++) {

        gp[z] = s->g;

        bytestream2_skip(&gp[z], z * offset);

    }



    for (y = s->height - 1; y >= 0; y--) {

        out_end = out_buf + (y * s->linesize);

        if (s->bytes_per_channel == 1) {

            for (x = s->width; x > 0; x--) {

                bytestream2_get_bufferu(&gp[z], out_end, s->depth);

                out_end += s->depth;

            }

        } else {

            uint16_t *out16 = (uint16_t *)out_end;

            for (x = s->width; x > 0; x--)

                for (z = 0; z < s->depth; z++)

                    *out16++ = bytestream2_get_ne16u(&gp[z]);

        }

    }

    return 0;

}

static int decode_fctl_chunk(AVFormatContext *s, APNGDemuxContext *ctx, AVPacket *pkt)

{

    uint32_t sequence_number, width, height, x_offset, y_offset;

    uint16_t delay_num, delay_den;

    uint8_t dispose_op, blend_op;



    sequence_number = avio_rb32(s->pb);

    width           = avio_rb32(s->pb);

    height          = avio_rb32(s->pb);

    x_offset        = avio_rb32(s->pb);

    y_offset        = avio_rb32(s->pb);

    delay_num       = avio_rb16(s->pb);

    delay_den       = avio_rb16(s->pb);

    dispose_op      = avio_r8(s->pb);

    blend_op        = avio_r8(s->pb);

    avio_skip(s->pb, 4); /* crc */



    /* default is hundredths of seconds */

    if (!delay_den)

        delay_den = 100;

    if (!delay_num || delay_den / delay_num > ctx->max_fps) {

        delay_num = 1;

        delay_den = ctx->default_fps;

    }

    ctx->pkt_duration = av_rescale_q(delay_num,

                                     (AVRational){ 1, delay_den },

                                     s->streams[0]->time_base);



    av_log(s, AV_LOG_DEBUG, "%s: "

            "sequence_number: %"PRId32", "

            "width: %"PRIu32", "

            "height: %"PRIu32", "

            "x_offset: %"PRIu32", "

            "y_offset: %"PRIu32", "

            "delay_num: %"PRIu16", "

            "delay_den: %"PRIu16", "

            "dispose_op: %d, "

            "blend_op: %d\n",

            __FUNCTION__,

            sequence_number,

            width,

            height,

            x_offset,

            y_offset,

            delay_num,

            delay_den,

            dispose_op,

            blend_op);



    if (width != s->streams[0]->codecpar->width ||

        height != s->streams[0]->codecpar->height ||

        x_offset != 0 ||

        y_offset != 0) {

        if (sequence_number == 0 ||

            x_offset >= s->streams[0]->codecpar->width ||

            width > s->streams[0]->codecpar->width - x_offset ||

            y_offset >= s->streams[0]->codecpar->height ||

            height > s->streams[0]->codecpar->height - y_offset)

            return AVERROR_INVALIDDATA;

        ctx->is_key_frame = 0;

    } else {

        if (sequence_number == 0 && dispose_op == APNG_DISPOSE_OP_PREVIOUS)

            dispose_op = APNG_DISPOSE_OP_BACKGROUND;

        ctx->is_key_frame = dispose_op == APNG_DISPOSE_OP_BACKGROUND ||

                            blend_op   == APNG_BLEND_OP_SOURCE;

    }



    return 0;

}

static int ape_tag_read_field(AVFormatContext *s)

{

    AVIOContext *pb = s->pb;

    uint8_t key[1024], *value;

    uint32_t size, flags;

    int i, c;



    size = avio_rl32(pb);  /* field size */

    flags = avio_rl32(pb); /* field flags */

    for (i = 0; i < sizeof(key) - 1; i++) {

        c = avio_r8(pb);

        if (c < 0x20 || c > 0x7E)

            break;

        else

            key[i] = c;

    }

    key[i] = 0;

    if (c != 0) {

        av_log(s, AV_LOG_WARNING, "Invalid APE tag key '%s'.\n", key);

        return -1;

    }

    if (size > INT32_MAX - FF_INPUT_BUFFER_PADDING_SIZE) {

        av_log(s, AV_LOG_ERROR, "APE tag size too large.\n");

        return AVERROR_INVALIDDATA;

    }

    if (flags & APE_TAG_FLAG_IS_BINARY) {

        uint8_t filename[1024];

        enum AVCodecID id;

        AVStream *st = avformat_new_stream(s, NULL);

        if (!st)

            return AVERROR(ENOMEM);



        size -= avio_get_str(pb, size, filename, sizeof(filename));

        if (size <= 0) {

            av_log(s, AV_LOG_WARNING, "Skipping binary tag '%s'.\n", key);

            return 0;

        }



        av_dict_set(&st->metadata, key, filename, 0);



        if ((id = ff_guess_image2_codec(filename)) != AV_CODEC_ID_NONE) {

            AVPacket pkt;

            int ret;



            ret = av_get_packet(s->pb, &pkt, size);

            if (ret < 0) {

                av_log(s, AV_LOG_ERROR, "Error reading cover art.\n");

                return ret;

            }



            st->disposition      |= AV_DISPOSITION_ATTACHED_PIC;

            st->codec->codec_type = AVMEDIA_TYPE_VIDEO;

            st->codec->codec_id   = id;



            st->attached_pic              = pkt;

            st->attached_pic.stream_index = st->index;

            st->attached_pic.flags       |= AV_PKT_FLAG_KEY;

        } else {

            if (ff_get_extradata(st->codec, s->pb, size) < 0)

                return AVERROR(ENOMEM);

            st->codec->codec_type = AVMEDIA_TYPE_ATTACHMENT;

        }

    } else {

        value = av_malloc(size+1);

        if (!value)

            return AVERROR(ENOMEM);

        c = avio_read(pb, value, size);

        if (c < 0) {

            av_free(value);

            return c;

        }

        value[c] = 0;

        av_dict_set(&s->metadata, key, value, AV_DICT_DONT_STRDUP_VAL);

    }

    return 0;

}

