static void new_subtitle_stream(AVFormatContext *oc)

{

    AVStream *st;

    AVCodec *codec=NULL;

    AVCodecContext *subtitle_enc;



    st = av_new_stream(oc, oc->nb_streams < nb_streamid_map ? streamid_map[oc->nb_streams] : 0);

    if (!st) {

        fprintf(stderr, "Could not alloc stream\n");

        ffmpeg_exit(1);

    }

    subtitle_enc = st->codec;

    output_codecs = grow_array(output_codecs, sizeof(*output_codecs), &nb_output_codecs, nb_output_codecs + 1);

    if(!subtitle_stream_copy){

        subtitle_enc->codec_id = find_codec_or_die(subtitle_codec_name, AVMEDIA_TYPE_SUBTITLE, 1,

                                                   avcodec_opts[AVMEDIA_TYPE_SUBTITLE]->strict_std_compliance);

        codec= output_codecs[nb_output_codecs-1] = avcodec_find_encoder_by_name(subtitle_codec_name);

    }

    avcodec_get_context_defaults3(st->codec, codec);



    bitstream_filters[nb_output_files] =

        grow_array(bitstream_filters[nb_output_files],

                   sizeof(*bitstream_filters[nb_output_files]),

                   &nb_bitstream_filters[nb_output_files], oc->nb_streams);

    bitstream_filters[nb_output_files][oc->nb_streams - 1]= subtitle_bitstream_filters;

    subtitle_bitstream_filters= NULL;



    subtitle_enc->codec_type = AVMEDIA_TYPE_SUBTITLE;



    if(subtitle_codec_tag)

        subtitle_enc->codec_tag= subtitle_codec_tag;



    if (subtitle_stream_copy) {

        st->stream_copy = 1;

    } else {

        set_context_opts(avcodec_opts[AVMEDIA_TYPE_SUBTITLE], subtitle_enc, AV_OPT_FLAG_SUBTITLE_PARAM | AV_OPT_FLAG_ENCODING_PARAM, codec);

    }



    if (subtitle_language) {

        av_metadata_set2(&st->metadata, "language", subtitle_language, 0);

        av_freep(&subtitle_language);

    }



    subtitle_disable = 0;

    av_freep(&subtitle_codec_name);

    subtitle_stream_copy = 0;

}

static inline void silk_stabilize_lsf(int16_t nlsf[16], int order, const uint16_t min_delta[17])

{

    int pass, i;

    for (pass = 0; pass < 20; pass++) {

        int k, min_diff = 0;

        for (i = 0; i < order+1; i++) {

            int low  = i != 0     ? nlsf[i-1] : 0;

            int high = i != order ? nlsf[i]   : 32768;

            int diff = (high - low) - (min_delta[i]);



            if (diff < min_diff) {

                min_diff = diff;

                k = i;



                if (pass == 20)

                    break;

            }

        }

        if (min_diff == 0) /* no issues; stabilized */

            return;



        /* wiggle one or two LSFs */

        if (k == 0) {

            /* repel away from lower bound */

            nlsf[0] = min_delta[0];

        } else if (k == order) {

            /* repel away from higher bound */

            nlsf[order-1] = 32768 - min_delta[order];

        } else {

            /* repel away from current position */

            int min_center = 0, max_center = 32768, center_val;



            /* lower extent */

            for (i = 0; i < k; i++)

                min_center += min_delta[i];

            min_center += min_delta[k] >> 1;



            /* upper extent */

            for (i = order; i > k; i--)

                max_center -= min_delta[i];

            max_center -= min_delta[k] >> 1;



            /* move apart */

            center_val = nlsf[k - 1] + nlsf[k];

            center_val = (center_val >> 1) + (center_val & 1); // rounded divide by 2

            center_val = FFMIN(max_center, FFMAX(min_center, center_val));



            nlsf[k - 1] = center_val - (min_delta[k] >> 1);

            nlsf[k]     = nlsf[k - 1] + min_delta[k];

        }

    }



    /* resort to the fall-back method, the standard method for LSF stabilization */



    /* sort; as the LSFs should be nearly sorted, use insertion sort */

    for (i = 1; i < order; i++) {

        int j, value = nlsf[i];

        for (j = i - 1; j >= 0 && nlsf[j] > value; j--)

            nlsf[j + 1] = nlsf[j];

        nlsf[j + 1] = value;

    }



    /* push forwards to increase distance */

    if (nlsf[0] < min_delta[0])

        nlsf[0] = min_delta[0];

    for (i = 1; i < order; i++)

        if (nlsf[i] < nlsf[i - 1] + min_delta[i])

            nlsf[i] = nlsf[i - 1] + min_delta[i];



    /* push backwards to increase distance */

    if (nlsf[order-1] > 32768 - min_delta[order])

        nlsf[order-1] = 32768 - min_delta[order];

    for (i = order-2; i >= 0; i--)

        if (nlsf[i] > nlsf[i + 1] - min_delta[i+1])

            nlsf[i] = nlsf[i + 1] - min_delta[i+1];



    return;

}

static int decode_channel_sound_unit(ATRAC3Context *q, GetBitContext *gb,

                                     ChannelUnit *snd, float *output,

                                     int channel_num, int coding_mode)

{

    int band, ret, num_subbands, last_tonal, num_bands;

    GainBlock *gain1 = &snd->gain_block[    snd->gc_blk_switch];

    GainBlock *gain2 = &snd->gain_block[1 - snd->gc_blk_switch];



    if (coding_mode == JOINT_STEREO && channel_num == 1) {

        if (get_bits(gb, 2) != 3) {

            av_log(NULL,AV_LOG_ERROR,"JS mono Sound Unit id != 3.\n");

            return AVERROR_INVALIDDATA;

        }

    } else {

        if (get_bits(gb, 6) != 0x28) {

            av_log(NULL,AV_LOG_ERROR,"Sound Unit id != 0x28.\n");

            return AVERROR_INVALIDDATA;

        }

    }



    /* number of coded QMF bands */

    snd->bands_coded = get_bits(gb, 2);



    ret = decode_gain_control(gb, gain2, snd->bands_coded);

    if (ret)

        return ret;



    snd->num_components = decode_tonal_components(gb, snd->components,

                                                  snd->bands_coded);

    if (snd->num_components < 0)

        return snd->num_components;



    num_subbands = decode_spectrum(gb, snd->spectrum);



    /* Merge the decoded spectrum and tonal components. */

    last_tonal = add_tonal_components(snd->spectrum, snd->num_components,

                                      snd->components);





    /* calculate number of used MLT/QMF bands according to the amount of coded

       spectral lines */

    num_bands = (subband_tab[num_subbands] - 1) >> 8;

    if (last_tonal >= 0)

        num_bands = FFMAX((last_tonal + 256) >> 8, num_bands);





    /* Reconstruct time domain samples. */

    for (band = 0; band < 4; band++) {

        /* Perform the IMDCT step without overlapping. */

        if (band <= num_bands)

            imlt(q, &snd->spectrum[band * 256], snd->imdct_buf, band & 1);

        else

            memset(snd->imdct_buf, 0, 512 * sizeof(*snd->imdct_buf));



        /* gain compensation and overlapping */

        ff_atrac_gain_compensation(&q->gainc_ctx, snd->imdct_buf,

                                   &snd->prev_frame[band * 256],

                                   &gain1->g_block[band], &gain2->g_block[band],

                                   256, &output[band * 256]);

    }



    /* Swap the gain control buffers for the next frame. */

    snd->gc_blk_switch ^= 1;



    return 0;

}

static void RENAME(extract_odd2)(const uint8_t *src, uint8_t *dst0, uint8_t *dst1, x86_reg count)

{

    dst0+=   count;

    dst1+=   count;

    src += 4*count;

    count= - count;

#if COMPILE_TEMPLATE_MMX

    if(count <= -8) {

        count += 7;

        __asm__ volatile(

            "pcmpeqw       %%mm7, %%mm7        \n\t"

            "psrlw            $8, %%mm7        \n\t"

            "1:                                \n\t"

            "movq -28(%1, %0, 4), %%mm0        \n\t"

            "movq -20(%1, %0, 4), %%mm1        \n\t"

            "movq -12(%1, %0, 4), %%mm2        \n\t"

            "movq  -4(%1, %0, 4), %%mm3        \n\t"

            "psrlw            $8, %%mm0        \n\t"

            "psrlw            $8, %%mm1        \n\t"

            "psrlw            $8, %%mm2        \n\t"

            "psrlw            $8, %%mm3        \n\t"

            "packuswb      %%mm1, %%mm0        \n\t"

            "packuswb      %%mm3, %%mm2        \n\t"

            "movq          %%mm0, %%mm1        \n\t"

            "movq          %%mm2, %%mm3        \n\t"

            "psrlw            $8, %%mm0        \n\t"

            "psrlw            $8, %%mm2        \n\t"

            "pand          %%mm7, %%mm1        \n\t"

            "pand          %%mm7, %%mm3        \n\t"

            "packuswb      %%mm2, %%mm0        \n\t"

            "packuswb      %%mm3, %%mm1        \n\t"

            MOVNTQ"        %%mm0,- 7(%3, %0)   \n\t"

            MOVNTQ"        %%mm1,- 7(%2, %0)   \n\t"

            "add              $8, %0           \n\t"

            " js 1b                            \n\t"

            : "+r"(count)

            : "r"(src), "r"(dst0), "r"(dst1)

        );

        count -= 7;

    }

#endif

    src++;

    while(count<0) {

        dst0[count]= src[4*count+0];

        dst1[count]= src[4*count+2];

        count++;

    }

}

static int decode_frame(AVCodecContext *avctx,

                             void *data, int *data_size,

                             AVPacket *avpkt)

{

    const uint8_t *buf = avpkt->data;

    int buf_size = avpkt->size;

    H264Context *h = avctx->priv_data;

    MpegEncContext *s = &h->s;

    AVFrame *pict = data;

    int buf_index;



    s->flags= avctx->flags;

    s->flags2= avctx->flags2;



   /* end of stream, output what is still in the buffers */

    if (buf_size == 0) {

        Picture *out;

        int i, out_idx;



//FIXME factorize this with the output code below

        out = h->delayed_pic[0];

        out_idx = 0;

        for(i=1; h->delayed_pic[i] && (h->delayed_pic[i]->poc && !h->delayed_pic[i]->key_frame); i++)

            if(h->delayed_pic[i]->poc < out->poc){

                out = h->delayed_pic[i];

                out_idx = i;

            }



        for(i=out_idx; h->delayed_pic[i]; i++)

            h->delayed_pic[i] = h->delayed_pic[i+1];



        if(out){

            *data_size = sizeof(AVFrame);

            *pict= *(AVFrame*)out;

        }



        return 0;

    }



    if(h->is_avc && !h->got_avcC) {

        int i, cnt, nalsize;

        unsigned char *p = avctx->extradata;

        if(avctx->extradata_size < 7) {

            av_log(avctx, AV_LOG_ERROR, "avcC too short\n");

            return -1;

        }

        if(*p != 1) {

            av_log(avctx, AV_LOG_ERROR, "Unknown avcC version %d\n", *p);

            return -1;

        }

        /* sps and pps in the avcC always have length coded with 2 bytes,

           so put a fake nal_length_size = 2 while parsing them */

        h->nal_length_size = 2;

        // Decode sps from avcC

        cnt = *(p+5) & 0x1f; // Number of sps

        p += 6;

        for (i = 0; i < cnt; i++) {

            nalsize = AV_RB16(p) + 2;

            if(decode_nal_units(h, p, nalsize) < 0) {

                av_log(avctx, AV_LOG_ERROR, "Decoding sps %d from avcC failed\n", i);

                return -1;

            }

            p += nalsize;

        }

        // Decode pps from avcC

        cnt = *(p++); // Number of pps

        for (i = 0; i < cnt; i++) {

            nalsize = AV_RB16(p) + 2;

            if(decode_nal_units(h, p, nalsize)  != nalsize) {

                av_log(avctx, AV_LOG_ERROR, "Decoding pps %d from avcC failed\n", i);

                return -1;

            }

            p += nalsize;

        }

        // Now store right nal length size, that will be use to parse all other nals

        h->nal_length_size = ((*(((char*)(avctx->extradata))+4))&0x03)+1;

        // Do not reparse avcC

        h->got_avcC = 1;

    }



    if(!h->got_avcC && !h->is_avc && s->avctx->extradata_size){

        if(decode_nal_units(h, s->avctx->extradata, s->avctx->extradata_size) < 0)

            return -1;

        h->got_avcC = 1;

    }



    buf_index=decode_nal_units(h, buf, buf_size);

    if(buf_index < 0)

        return -1;



    if(!(s->flags2 & CODEC_FLAG2_CHUNKS) && !s->current_picture_ptr){

        if (avctx->skip_frame >= AVDISCARD_NONREF || s->hurry_up) return 0;

        av_log(avctx, AV_LOG_ERROR, "no frame!\n");

        return -1;

    }



    if(!(s->flags2 & CODEC_FLAG2_CHUNKS) || (s->mb_y >= s->mb_height && s->mb_height)){

        Picture *out = s->current_picture_ptr;

        Picture *cur = s->current_picture_ptr;

        int i, pics, cross_idr, out_of_order, out_idx;



        field_end(h);



        if (cur->field_poc[0]==INT_MAX || cur->field_poc[1]==INT_MAX) {

            /* Wait for second field. */

            *data_size = 0;



        } else {

            cur->repeat_pict = 0;



            /* Signal interlacing information externally. */

            /* Prioritize picture timing SEI information over used decoding process if it exists. */

            if (h->sei_ct_type)

                cur->interlaced_frame = (h->sei_ct_type & (1<<1)) != 0;

            else

                cur->interlaced_frame = FIELD_OR_MBAFF_PICTURE;



            if(h->sps.pic_struct_present_flag){

                switch (h->sei_pic_struct)

                {

                case SEI_PIC_STRUCT_TOP_BOTTOM_TOP:

                case SEI_PIC_STRUCT_BOTTOM_TOP_BOTTOM:

                    // Signal the possibility of telecined film externally (pic_struct 5,6)

                    // From these hints, let the applications decide if they apply deinterlacing.

                    cur->repeat_pict = 1;

                    break;

                case SEI_PIC_STRUCT_FRAME_DOUBLING:

                    // Force progressive here, as doubling interlaced frame is a bad idea.

                    cur->interlaced_frame = 0;

                    cur->repeat_pict = 2;

                    break;

                case SEI_PIC_STRUCT_FRAME_TRIPLING:

                    cur->interlaced_frame = 0;

                    cur->repeat_pict = 4;

                    break;

                }

            }else{

                /* Derive interlacing flag from used decoding process. */

                cur->interlaced_frame = FIELD_OR_MBAFF_PICTURE;

            }



            if (cur->field_poc[0] != cur->field_poc[1]){

                /* Derive top_field_first from field pocs. */

                cur->top_field_first = cur->field_poc[0] < cur->field_poc[1];

            }else{

                if(cur->interlaced_frame || h->sps.pic_struct_present_flag){

                    /* Use picture timing SEI information. Even if it is a information of a past frame, better than nothing. */

                    if(h->sei_pic_struct == SEI_PIC_STRUCT_TOP_BOTTOM

                      || h->sei_pic_struct == SEI_PIC_STRUCT_TOP_BOTTOM_TOP)

                        cur->top_field_first = 1;

                    else

                        cur->top_field_first = 0;

                }else{

                    /* Most likely progressive */

                    cur->top_field_first = 0;

                }

            }



        //FIXME do something with unavailable reference frames



            /* Sort B-frames into display order */



            if(h->sps.bitstream_restriction_flag

               && s->avctx->has_b_frames < h->sps.num_reorder_frames){

                s->avctx->has_b_frames = h->sps.num_reorder_frames;

                s->low_delay = 0;

            }



            if(   s->avctx->strict_std_compliance >= FF_COMPLIANCE_STRICT

               && !h->sps.bitstream_restriction_flag){

                s->avctx->has_b_frames= MAX_DELAYED_PIC_COUNT;

                s->low_delay= 0;

            }



            pics = 0;

            while(h->delayed_pic[pics]) pics++;



            assert(pics <= MAX_DELAYED_PIC_COUNT);



            h->delayed_pic[pics++] = cur;

            if(cur->reference == 0)

                cur->reference = DELAYED_PIC_REF;



            out = h->delayed_pic[0];

            out_idx = 0;

            for(i=1; h->delayed_pic[i] && (h->delayed_pic[i]->poc && !h->delayed_pic[i]->key_frame); i++)

                if(h->delayed_pic[i]->poc < out->poc){

                    out = h->delayed_pic[i];

                    out_idx = i;

                }

            cross_idr = !h->delayed_pic[0]->poc || !!h->delayed_pic[i] || h->delayed_pic[0]->key_frame;



            out_of_order = !cross_idr && out->poc < h->outputed_poc;



            if(h->sps.bitstream_restriction_flag && s->avctx->has_b_frames >= h->sps.num_reorder_frames)

                { }

            else if((out_of_order && pics-1 == s->avctx->has_b_frames && s->avctx->has_b_frames < MAX_DELAYED_PIC_COUNT)

               || (s->low_delay &&

                ((!cross_idr && out->poc > h->outputed_poc + 2)

                 || cur->pict_type == FF_B_TYPE)))

            {

                s->low_delay = 0;

                s->avctx->has_b_frames++;

            }



            if(out_of_order || pics > s->avctx->has_b_frames){

                out->reference &= ~DELAYED_PIC_REF;

                for(i=out_idx; h->delayed_pic[i]; i++)

                    h->delayed_pic[i] = h->delayed_pic[i+1];

            }

            if(!out_of_order && pics > s->avctx->has_b_frames){

                *data_size = sizeof(AVFrame);



                h->outputed_poc = out->poc;

                *pict= *(AVFrame*)out;

            }else{

                av_log(avctx, AV_LOG_DEBUG, "no picture\n");

            }

        }

    }



    assert(pict->data[0] || !*data_size);

    ff_print_debug_info(s, pict);

//printf("out %d\n", (int)pict->data[0]);

#if 0 //?



    /* Return the Picture timestamp as the frame number */

    /* we subtract 1 because it is added on utils.c     */

    avctx->frame_number = s->picture_number - 1;

#endif

    return get_consumed_bytes(s, buf_index, buf_size);

}

static int tscc2_decode_mb(TSCC2Context *c, int *q, int vlc_set,

                           uint8_t *dst, int stride, int plane)

{

    GetBitContext *gb = &c->gb;

    int prev_dc, dc, nc, ac, bpos, val;

    int i, j, k, l;



    if (get_bits1(gb)) {

        if (get_bits1(gb)) {

            val = get_bits(gb, 8);

            for (i = 0; i < 8; i++, dst += stride)

                memset(dst, val, 16);

        } else {

            if (get_bits_left(gb) < 16 * 8 * 8)

                return AVERROR_INVALIDDATA;

            for (i = 0; i < 8; i++) {

                for (j = 0; j < 16; j++)

                    dst[j] = get_bits(gb, 8);

                dst += stride;

            }

        }

        return 0;

    }



    prev_dc = 0;

    for (j = 0; j < 2; j++) {

        for (k = 0; k < 4; k++) {

            if (!(j | k)) {

                dc = get_bits(gb, 8);

            } else {

                dc = get_vlc2(gb, c->dc_vlc.table, 9, 2);

                if (dc == -1)

                    return AVERROR_INVALIDDATA;

                if (dc == 0x100)

                    dc = get_bits(gb, 8);

            }

            dc          = (dc + prev_dc) & 0xFF;

            prev_dc     = dc;

            c->block[0] = dc;



            nc = get_vlc2(gb, c->nc_vlc[vlc_set].table, 9, 1);

            if (nc == -1)

                return AVERROR_INVALIDDATA;



            bpos = 1;

            memset(c->block + 1, 0, 15 * sizeof(*c->block));

            for (l = 0; l < nc; l++) {

                ac = get_vlc2(gb, c->ac_vlc[vlc_set].table, 9, 2);

                if (ac == -1)

                    return AVERROR_INVALIDDATA;

                if (ac == 0x1000)

                    ac = get_bits(gb, 12);

                bpos += ac & 0xF;

                if (bpos >= 64)

                    return AVERROR_INVALIDDATA;

                val = sign_extend(ac >> 4, 8);

                c->block[tscc2_zigzag[bpos++]] = val;

            }

            tscc2_idct4_put(c->block, q, dst + k * 4, stride);

        }

        dst += 4 * stride;

    }

    return 0;

}

static void subband_transform(DCAEncContext *c, const int32_t *input)

{

    int ch, subs, i, k, j;



    for (ch = 0; ch < c->fullband_channels; ch++) {

        /* History is copied because it is also needed for PSY */

        int32_t hist[512];

        int hist_start = 0;

        const int chi = c->channel_order_tab[ch];



        for (i = 0; i < 512; i++)

            hist[i] = c->history[i][ch];



        for (subs = 0; subs < SUBBAND_SAMPLES; subs++) {

            int32_t accum[64];

            int32_t resp;

            int band;



            /* Calculate the convolutions at once */

            for (i = 0; i < 64; i++)

                accum[i] = 0;



            for (k = 0, i = hist_start, j = 0;

                    i < 512; k = (k + 1) & 63, i++, j++)

                accum[k] += mul32(hist[i], c->band_interpolation[j]);

            for (i = 0; i < hist_start; k = (k + 1) & 63, i++, j++)

                accum[k] += mul32(hist[i], c->band_interpolation[j]);



            for (k = 16; k < 32; k++)

                accum[k] = accum[k] - accum[31 - k];

            for (k = 32; k < 48; k++)

                accum[k] = accum[k] + accum[95 - k];



            for (band = 0; band < 32; band++) {

                resp = 0;

                for (i = 16; i < 48; i++) {

                    int s = (2 * band + 1) * (2 * (i + 16) + 1);

                    resp += mul32(accum[i], cos_t(s << 3)) >> 3;

                }



                c->subband[subs][band][ch] = ((band + 1) & 2) ? -resp : resp;

            }



            /* Copy in 32 new samples from input */

            for (i = 0; i < 32; i++)

                hist[i + hist_start] = input[(subs * 32 + i) * c->channels + chi];

            hist_start = (hist_start + 32) & 511;

        }

    }

}

static void pcx_palette(const uint8_t **src, uint32_t *dst, unsigned int pallen) {

    unsigned int i;



    for (i=0; i<pallen; i++)

        *dst++ = 0xFF000000 | bytestream_get_be24(src);

    if (pallen < 256)

        memset(dst, 0, (256 - pallen) * sizeof(*dst));

}

static int mxf_read_sequence(MXFSequence *sequence, ByteIOContext *pb, int tag)

{

    switch(tag) {

    case 0x0202:

        sequence->duration = get_be64(pb);

        break;

    case 0x0201:

        get_buffer(pb, sequence->data_definition_ul, 16);

        break;

    case 0x1001:

        sequence->structural_components_count = get_be32(pb);

        if (sequence->structural_components_count >= UINT_MAX / sizeof(UID))

            return -1;

        sequence->structural_components_refs = av_malloc(sequence->structural_components_count * sizeof(UID));

        if (!sequence->structural_components_refs)

            return -1;

        url_fskip(pb, 4); /* useless size of objects, always 16 according to specs */

        get_buffer(pb, (uint8_t *)sequence->structural_components_refs, sequence->structural_components_count * sizeof(UID));

        break;

    }

    return 0;

}

