static int pic_arrays_init(HEVCContext *s, const HEVCSPS *sps)

{

    int log2_min_cb_size = sps->log2_min_cb_size;

    int width            = sps->width;

    int height           = sps->height;

    int pic_size_in_ctb  = ((width  >> log2_min_cb_size) + 1) *

                           ((height >> log2_min_cb_size) + 1);

    int ctb_count        = sps->ctb_width * sps->ctb_height;

    int min_pu_size      = sps->min_pu_width * sps->min_pu_height;



    s->bs_width  = (width  >> 2) + 1;

    s->bs_height = (height >> 2) + 1;



    s->sao           = av_mallocz_array(ctb_count, sizeof(*s->sao));

    s->deblock       = av_mallocz_array(ctb_count, sizeof(*s->deblock));

    if (!s->sao || !s->deblock)

        goto fail;



    s->skip_flag    = av_malloc(sps->min_cb_height * sps->min_cb_width);

    s->tab_ct_depth = av_malloc_array(sps->min_cb_height, sps->min_cb_width);

    if (!s->skip_flag || !s->tab_ct_depth)

        goto fail;



    s->cbf_luma = av_malloc_array(sps->min_tb_width, sps->min_tb_height);

    s->tab_ipm  = av_mallocz(min_pu_size);

    s->is_pcm   = av_malloc((sps->min_pu_width + 1) * (sps->min_pu_height + 1));

    if (!s->tab_ipm || !s->cbf_luma || !s->is_pcm)

        goto fail;



    s->filter_slice_edges = av_malloc(ctb_count);

    s->tab_slice_address  = av_malloc_array(pic_size_in_ctb,

                                      sizeof(*s->tab_slice_address));

    s->qp_y_tab           = av_malloc_array(pic_size_in_ctb,

                                      sizeof(*s->qp_y_tab));

    if (!s->qp_y_tab || !s->filter_slice_edges || !s->tab_slice_address)

        goto fail;



    s->horizontal_bs = av_mallocz_array(s->bs_width, s->bs_height);

    s->vertical_bs   = av_mallocz_array(s->bs_width, s->bs_height);

    if (!s->horizontal_bs || !s->vertical_bs)

        goto fail;



    s->tab_mvf_pool = av_buffer_pool_init(min_pu_size * sizeof(MvField),

                                          av_buffer_allocz);

    s->rpl_tab_pool = av_buffer_pool_init(ctb_count * sizeof(RefPicListTab),

                                          av_buffer_allocz);

    if (!s->tab_mvf_pool || !s->rpl_tab_pool)

        goto fail;



    return 0;



fail:

    pic_arrays_free(s);

    return AVERROR(ENOMEM);

}

static int decode_dc_progressive(MJpegDecodeContext *s, int16_t *block,

                                 int component, int dc_index,

                                 int16_t *quant_matrix, int Al)

{

    int val;

    s->bdsp.clear_block(block);

    val = mjpeg_decode_dc(s, dc_index);

    if (val == 0xfffff) {

        av_log(s->avctx, AV_LOG_ERROR, "error dc\n");

        return AVERROR_INVALIDDATA;

    }

    val = (val * (quant_matrix[0] << Al)) + s->last_dc[component];

    s->last_dc[component] = val;

    block[0] = val;

    return 0;

}

static int config_input(AVFilterLink *inlink)
{
    HQDN3DContext *s = inlink->dst->priv;
    const AVPixFmtDescriptor *desc = av_pix_fmt_desc_get(inlink->format);
    int i;
    s->hsub  = desc->log2_chroma_w;
    s->vsub  = desc->log2_chroma_h;
    s->depth = desc->comp[0].depth_minus1+1;
    s->line = av_malloc(inlink->w * sizeof(*s->line));
    if (!s->line)
        return AVERROR(ENOMEM);
    for (i = 0; i < 4; i++) {
        s->coefs[i] = precalc_coefs(s->strength[i], s->depth);
        if (!s->coefs[i])
            return AVERROR(ENOMEM);
    }
    if (ARCH_X86)
        ff_hqdn3d_init_x86(s);
    return 0;
}

static int64_t mkv_write_cues(AVIOContext *pb, mkv_cues *cues, mkv_track *tracks, int num_tracks)

{

    ebml_master cues_element;

    int64_t currentpos;

    int i, j;



    currentpos = avio_tell(pb);

    cues_element = start_ebml_master(pb, MATROSKA_ID_CUES, 0);



    for (i = 0; i < cues->num_entries; i++) {

        ebml_master cuepoint, track_positions;

        mkv_cuepoint *entry = &cues->entries[i];

        uint64_t pts = entry->pts;



        cuepoint = start_ebml_master(pb, MATROSKA_ID_POINTENTRY, MAX_CUEPOINT_SIZE(num_tracks));

        put_ebml_uint(pb, MATROSKA_ID_CUETIME, pts);



        // put all the entries from different tracks that have the exact same

        // timestamp into the same CuePoint

        for (j = 0; j < num_tracks; j++)

            tracks[j].has_cue = 0;

        for (j = 0; j < cues->num_entries - i && entry[j].pts == pts; j++) {

            if (tracks[entry[j].tracknum].has_cue)

                continue;

            tracks[entry[j].tracknum].has_cue = 1;

            track_positions = start_ebml_master(pb, MATROSKA_ID_CUETRACKPOSITION, MAX_CUETRACKPOS_SIZE);

            put_ebml_uint(pb, MATROSKA_ID_CUETRACK          , entry[j].tracknum   );

            put_ebml_uint(pb, MATROSKA_ID_CUECLUSTERPOSITION, entry[j].cluster_pos);

            end_ebml_master(pb, track_positions);

        }

        i += j - 1;

        end_ebml_master(pb, cuepoint);

    }

    end_ebml_master(pb, cues_element);



    return currentpos;

}

static void decode_plane(FFV1Context *s, uint8_t *src,

                         int w, int h, int stride, int plane_index,

                         int pixel_stride)

{

    int x, y;

    int16_t *sample[2];

    sample[0] = s->sample_buffer + 3;

    sample[1] = s->sample_buffer + w + 6 + 3;



    s->run_index = 0;



    memset(s->sample_buffer, 0, 2 * (w + 6) * sizeof(*s->sample_buffer));



    for (y = 0; y < h; y++) {

        int16_t *temp = sample[0]; // FIXME: try a normal buffer



        sample[0] = sample[1];

        sample[1] = temp;



        sample[1][-1] = sample[0][0];

        sample[0][w]  = sample[0][w - 1];



// { START_TIMER

        if (s->avctx->bits_per_raw_sample <= 8) {

            decode_line(s, w, sample, plane_index, 8);

            for (x = 0; x < w; x++)

                src[x*pixel_stride + stride * y] = sample[1][x];

        } else {

            decode_line(s, w, sample, plane_index, s->avctx->bits_per_raw_sample);

            if (s->packed_at_lsb) {

                for (x = 0; x < w; x++) {

                    ((uint16_t*)(src + stride*y))[x*pixel_stride] = sample[1][x];

                }

            } else {

                for (x = 0; x < w; x++) {

                    ((uint16_t*)(src + stride*y))[x*pixel_stride] = sample[1][x] << (16 - s->avctx->bits_per_raw_sample) | ((uint16_t **)sample)[1][x] >> (2 * s->avctx->bits_per_raw_sample - 16);

                }

            }

        }

// STOP_TIMER("decode-line") }

    }

}

static int wav_read_header(AVFormatContext *s,

                           AVFormatParameters *ap)

{

    int size;

    unsigned int tag;

    ByteIOContext *pb = s->pb;

    AVStream *st;

    WAVContext *wav = s->priv_data;



    /* check RIFF header */

    tag = get_le32(pb);



    if (tag != MKTAG('R', 'I', 'F', 'F'))

        return -1;

    get_le32(pb); /* file size */

    tag = get_le32(pb);

    if (tag != MKTAG('W', 'A', 'V', 'E'))

        return -1;



    /* parse fmt header */

    size = find_tag(pb, MKTAG('f', 'm', 't', ' '));

    if (size < 0)

        return -1;

    st = av_new_stream(s, 0);

    if (!st)

        return AVERROR(ENOMEM);



    get_wav_header(pb, st->codec, size);

    st->need_parsing = AVSTREAM_PARSE_FULL;



    av_set_pts_info(st, 64, 1, st->codec->sample_rate);



    size = find_tag(pb, MKTAG('d', 'a', 't', 'a'));

    if (size < 0)

        return -1;

    wav->data_end= url_ftell(pb) + size;

    return 0;

}

int attribute_align_arg avcodec_decode_video2(AVCodecContext *avctx, AVFrame *picture,

                                              int *got_picture_ptr,

                                              AVPacket *avpkt)

{

    AVCodecInternal *avci = avctx->internal;

    int ret;



    *got_picture_ptr = 0;

    if ((avctx->coded_width || avctx->coded_height) && av_image_check_size(avctx->coded_width, avctx->coded_height, 0, avctx))

        return -1;



    avctx->internal->pkt = avpkt;

    ret = apply_param_change(avctx, avpkt);

    if (ret < 0) {

        av_log(avctx, AV_LOG_ERROR, "Error applying parameter changes.\n");

        if (avctx->err_recognition & AV_EF_EXPLODE)

            return ret;

    }



    avcodec_get_frame_defaults(picture);



    if (!avctx->refcounted_frames)

        av_frame_unref(&avci->to_free);



    if ((avctx->codec->capabilities & CODEC_CAP_DELAY) || avpkt->size || (avctx->active_thread_type & FF_THREAD_FRAME)) {

        if (HAVE_THREADS && avctx->active_thread_type & FF_THREAD_FRAME)

            ret = ff_thread_decode_frame(avctx, picture, got_picture_ptr,

                                         avpkt);

        else {

            ret = avctx->codec->decode(avctx, picture, got_picture_ptr,

                                       avpkt);

            picture->pkt_dts = avpkt->dts;

            /* get_buffer is supposed to set frame parameters */

            if (!(avctx->codec->capabilities & CODEC_CAP_DR1)) {

                picture->sample_aspect_ratio = avctx->sample_aspect_ratio;

                picture->width               = avctx->width;

                picture->height              = avctx->height;

                picture->format              = avctx->pix_fmt;

            }

        }



        emms_c(); //needed to avoid an emms_c() call before every return;



        if (ret < 0 && picture->buf[0])

            av_frame_unref(picture);



        if (*got_picture_ptr) {

            if (!avctx->refcounted_frames) {

                avci->to_free = *picture;

                avci->to_free.extended_data = avci->to_free.data;

                memset(picture->buf, 0, sizeof(picture->buf));

            }



            avctx->frame_number++;

        }

    } else

        ret = 0;



    return ret;

}

int av_new_packet(AVPacket *pkt, int size)

{

    uint8_t *data;

    if((unsigned)size > (unsigned)size + FF_INPUT_BUFFER_PADDING_SIZE)

        return AVERROR(ENOMEM);

    data = av_malloc(size + FF_INPUT_BUFFER_PADDING_SIZE);

    if (!data)

        return AVERROR(ENOMEM);

    memset(data + size, 0, FF_INPUT_BUFFER_PADDING_SIZE);



    av_init_packet(pkt);

    pkt->data = data;

    pkt->size = size;

    pkt->destruct = av_destruct_packet;

    return 0;

}

static int decode_slice(H264Context *h){

    MpegEncContext * const s = &h->s;

    const int part_mask= s->partitioned_frame ? (AC_END|AC_ERROR) : 0x7F;



    s->mb_skip_run= -1;



    if( h->pps.cabac ) {

        int i;



        /* realign */

        align_get_bits( &s->gb );



        /* init cabac */

        ff_init_cabac_states( &h->cabac, ff_h264_lps_range, ff_h264_mps_state, ff_h264_lps_state, 64 );

        ff_init_cabac_decoder( &h->cabac,

                               s->gb.buffer + get_bits_count(&s->gb)/8,

                               ( s->gb.size_in_bits - get_bits_count(&s->gb) + 7)/8);

        /* calculate pre-state */

        for( i= 0; i < 460; i++ ) {

            int pre;

            if( h->slice_type == I_TYPE )

                pre = clip( ((cabac_context_init_I[i][0] * s->qscale) >>4 ) + cabac_context_init_I[i][1], 1, 126 );

            else

                pre = clip( ((cabac_context_init_PB[h->cabac_init_idc][i][0] * s->qscale) >>4 ) + cabac_context_init_PB[h->cabac_init_idc][i][1], 1, 126 );



            if( pre <= 63 )

                h->cabac_state[i] = 2 * ( 63 - pre ) + 0;

            else

                h->cabac_state[i] = 2 * ( pre - 64 ) + 1;

        }



        for(;;){

            int ret = decode_mb_cabac(h);

            int eos;



            if(ret>=0) hl_decode_mb(h);



            /* XXX: useless as decode_mb_cabac it doesn't support that ... */

            if( ret >= 0 && h->mb_aff_frame ) { //FIXME optimal? or let mb_decode decode 16x32 ?

                s->mb_y++;



                if(ret>=0) ret = decode_mb_cabac(h);



                hl_decode_mb(h);

                s->mb_y--;

            }

            eos = get_cabac_terminate( &h->cabac );



            if( ret < 0 || h->cabac.bytestream > h->cabac.bytestream_end + 1) {

                av_log(h->s.avctx, AV_LOG_ERROR, "error while decoding MB %d %d\n", s->mb_x, s->mb_y);

                ff_er_add_slice(s, s->resync_mb_x, s->resync_mb_y, s->mb_x, s->mb_y, (AC_ERROR|DC_ERROR|MV_ERROR)&part_mask);

                return -1;

            }



            if( ++s->mb_x >= s->mb_width ) {

                s->mb_x = 0;

                ff_draw_horiz_band(s, 16*s->mb_y, 16);

                ++s->mb_y;

                if(h->mb_aff_frame) {

                    ++s->mb_y;

                }

            }



            if( eos || s->mb_y >= s->mb_height ) {

                tprintf("slice end %d %d\n", get_bits_count(&s->gb), s->gb.size_in_bits);

                ff_er_add_slice(s, s->resync_mb_x, s->resync_mb_y, s->mb_x-1, s->mb_y, (AC_END|DC_END|MV_END)&part_mask);

                return 0;

            }

        }



    } else {

        for(;;){

            int ret = decode_mb_cavlc(h);



            if(ret>=0) hl_decode_mb(h);



            if(ret>=0 && h->mb_aff_frame){ //FIXME optimal? or let mb_decode decode 16x32 ?

                s->mb_y++;

                ret = decode_mb_cavlc(h);



                if(ret>=0) hl_decode_mb(h);

                s->mb_y--;

            }



            if(ret<0){

                av_log(h->s.avctx, AV_LOG_ERROR, "error while decoding MB %d %d\n", s->mb_x, s->mb_y);

                ff_er_add_slice(s, s->resync_mb_x, s->resync_mb_y, s->mb_x, s->mb_y, (AC_ERROR|DC_ERROR|MV_ERROR)&part_mask);



                return -1;

            }



            if(++s->mb_x >= s->mb_width){

                s->mb_x=0;

                ff_draw_horiz_band(s, 16*s->mb_y, 16);

                ++s->mb_y;

                if(h->mb_aff_frame) {

                    ++s->mb_y;

                }

                if(s->mb_y >= s->mb_height){

                    tprintf("slice end %d %d\n", get_bits_count(&s->gb), s->gb.size_in_bits);



                    if(get_bits_count(&s->gb) == s->gb.size_in_bits ) {

                        ff_er_add_slice(s, s->resync_mb_x, s->resync_mb_y, s->mb_x-1, s->mb_y, (AC_END|DC_END|MV_END)&part_mask);



