                        return -1;

                    }

                }

            }



            if(get_bits_count(&s->gb) >= s->gb.size_in_bits && s->mb_skip_run<=0){

                tprintf("slice end %d %d\n", get_bits_count(&s->gb), s->gb.size_in_bits);

