static int color_distance(uint32_t a, uint32_t b)

{

    int r = 0, d, i;



    for (i = 0; i < 32; i += 8) {

        d = ((a >> i) & 0xFF) - ((b >> i) & 0xFF);

        r += d * d;

    }

    return r;

}

static void sbr_qmf_deint_bfly_c(INTFLOAT *v, const INTFLOAT *src0, const INTFLOAT *src1)

{

    int i;

    for (i = 0; i < 64; i++) {

        v[      i] = AAC_SRA_R((src0[i] - src1[63 - i]), 5);

        v[127 - i] = AAC_SRA_R((src0[i] + src1[63 - i]), 5);

    }

}

static void gif_copy_img_rect(const uint32_t *src, uint32_t *dst,

                              int linesize, int l, int t, int w, int h)

{

    const int y_start = t * linesize;

    const uint32_t *src_px, *src_pr,

                   *src_py = src + y_start,

                   *dst_py = dst + y_start;

    const uint32_t *src_pb = src_py + (t + h) * linesize;

    uint32_t *dst_px;



    for (; src_py < src_pb; src_py += linesize, dst_py += linesize) {

        src_px = src_py + l;

        dst_px = (uint32_t *)dst_py + l;

        src_pr = src_px + w;



        for (; src_px < src_pr; src_px++, dst_px++)

            *dst_px = *src_px;

    }

}

static int expand_rle_row(SgiState *s, uint8_t *out_buf,

                          uint8_t *out_end, int pixelstride)

{

    unsigned char pixel, count;

    unsigned char *orig = out_buf;



    while (1) {

        if (bytestream2_get_bytes_left(&s->g) < 1)

            return AVERROR_INVALIDDATA;

        pixel = bytestream2_get_byteu(&s->g);

        if (!(count = (pixel & 0x7f))) {

            return (out_buf - orig) / pixelstride;

        }



        /* Check for buffer overflow. */

        if(out_buf + pixelstride * count >= out_end) return -1;



        if (pixel & 0x80) {

            while (count--) {

                *out_buf = bytestream2_get_byte(&s->g);

                out_buf += pixelstride;

            }

        } else {

            pixel = bytestream2_get_byte(&s->g);



            while (count--) {

                *out_buf = pixel;

                out_buf += pixelstride;

            }

        }

    }

}

static void new_connection(int server_fd, int is_rtsp)

{

    struct sockaddr_in from_addr;

    int fd, len;

    HTTPContext *c = NULL;



    len = sizeof(from_addr);

    fd = accept(server_fd, (struct sockaddr *)&from_addr, 

                &len);

    if (fd < 0)

        return;

    fcntl(fd, F_SETFL, O_NONBLOCK);



    /* XXX: should output a warning page when coming

       close to the connection limit */

    if (nb_connections >= nb_max_connections)

        goto fail;



    /* add a new connection */

    c = av_mallocz(sizeof(HTTPContext));

    if (!c)

        goto fail;



    c->next = first_http_ctx;

    first_http_ctx = c;

    c->fd = fd;

    c->poll_entry = NULL;

    c->from_addr = from_addr;

    c->buffer_size = IOBUFFER_INIT_SIZE;

    c->buffer = av_malloc(c->buffer_size);

    if (!c->buffer)

        goto fail;

    nb_connections++;



    start_wait_request(c, is_rtsp);



    return;



 fail:

    if (c) {

        av_free(c->buffer);

        av_free(c);

    }

    close(fd);

}

static void apply_independent_coupling_fixed(AACContext *ac,

                                       SingleChannelElement *target,

                                       ChannelElement *cce, int index)

{

    int i, c, shift, round, tmp;

    const int gain = cce->coup.gain[index][0];

    const int *src = cce->ch[0].ret;

    int *dest = target->ret;

    const int len = 1024 << (ac->oc[1].m4ac.sbr == 1);



    c = cce_scale_fixed[gain & 7];

    shift = (gain-1024) >> 3;

    if (shift < 0) {

        shift = -shift;

        round = 1 << (shift - 1);



        for (i = 0; i < len; i++) {

            tmp = (int)(((int64_t)src[i] * c + (int64_t)0x1000000000) >> 37);

            dest[i] += (tmp + round) >> shift;

        }

    }

    else {

      for (i = 0; i < len; i++) {

          tmp = (int)(((int64_t)src[i] * c + (int64_t)0x1000000000) >> 37);

          dest[i] += tmp << shift;

      }

    }

}

static int mov_read_tkhd(MOVContext *c, AVIOContext *pb, MOVAtom atom)

{

    int i;

    int width;

    int height;

    int display_matrix[3][3];

    AVStream *st;

    MOVStreamContext *sc;

    int version;

    int flags;



    if (c->fc->nb_streams < 1)

        return 0;

    st = c->fc->streams[c->fc->nb_streams-1];

    sc = st->priv_data;



    version = avio_r8(pb);

    flags = avio_rb24(pb);

    st->disposition |= (flags & MOV_TKHD_FLAG_ENABLED) ? AV_DISPOSITION_DEFAULT : 0;



    if (version == 1) {

        avio_rb64(pb);

        avio_rb64(pb);

    } else {

        avio_rb32(pb); /* creation time */

        avio_rb32(pb); /* modification time */

    }

    st->id = (int)avio_rb32(pb); /* track id (NOT 0 !)*/

    avio_rb32(pb); /* reserved */



    /* highlevel (considering edits) duration in movie timebase */

    (version == 1) ? avio_rb64(pb) : avio_rb32(pb);

    avio_rb32(pb); /* reserved */

    avio_rb32(pb); /* reserved */



    avio_rb16(pb); /* layer */

    avio_rb16(pb); /* alternate group */

    avio_rb16(pb); /* volume */

    avio_rb16(pb); /* reserved */



    //read in the display matrix (outlined in ISO 14496-12, Section 6.2.2)

    // they're kept in fixed point format through all calculations

    // save u,v,z to store the whole matrix in the AV_PKT_DATA_DISPLAYMATRIX

    // side data, but the scale factor is not needed to calculate aspect ratio

    for (i = 0; i < 3; i++) {

        display_matrix[i][0] = avio_rb32(pb);   // 16.16 fixed point

        display_matrix[i][1] = avio_rb32(pb);   // 16.16 fixed point

        display_matrix[i][2] = avio_rb32(pb);   //  2.30 fixed point

    }



    width = avio_rb32(pb);       // 16.16 fixed point track width

    height = avio_rb32(pb);      // 16.16 fixed point track height

    sc->width = width >> 16;

    sc->height = height >> 16;



    // save the matrix and add rotate metadata when it is not the default

    // identity

    if (display_matrix[0][0] != (1 << 16) ||

        display_matrix[1][1] != (1 << 16) ||

        display_matrix[2][2] != (1 << 30) ||

        display_matrix[0][1] || display_matrix[0][2] ||

        display_matrix[1][0] || display_matrix[1][2] ||

        display_matrix[2][0] || display_matrix[2][1]) {

        int i, j;

        double rotate;



        av_freep(&sc->display_matrix);

        sc->display_matrix = av_malloc(sizeof(int32_t) * 9);

        if (!sc->display_matrix)

            return AVERROR(ENOMEM);



        for (i = 0; i < 3; i++)

            for (j = 0; j < 3; j++)

                sc->display_matrix[i * 3 + j] = display_matrix[j][i];



        rotate = av_display_rotation_get(sc->display_matrix);

        if (!isnan(rotate)) {

            char rotate_buf[64];

            rotate = -rotate;

            if (rotate < 0) // for backward compatibility

                rotate += 360;

            snprintf(rotate_buf, sizeof(rotate_buf), "%g", rotate);

            av_dict_set(&st->metadata, "rotate", rotate_buf, 0);

        }

    }



    // transform the display width/height according to the matrix

    // to keep the same scale, use [width height 1<<16]

    if (width && height && sc->display_matrix) {

        double disp_transform[2];



#define SQR(a) ((a)*(double)(a))

        for (i = 0; i < 2; i++)

            disp_transform[i] = sqrt(SQR(display_matrix[i][0]) + SQR(display_matrix[i][1]));



        if (disp_transform[0] > 0 && disp_transform[1] > 0 &&

            fabs((disp_transform[0] / disp_transform[1]) - 1.0) > 0.01)

            st->sample_aspect_ratio = av_d2q(

                disp_transform[0] / disp_transform[1],

                INT_MAX);

    }

    return 0;

}

int ff_mjpeg_find_marker(MJpegDecodeContext *s,

                         const uint8_t **buf_ptr, const uint8_t *buf_end,

                         const uint8_t **unescaped_buf_ptr,

                         int *unescaped_buf_size)

{

    int start_code;

    start_code = find_marker(buf_ptr, buf_end);



    av_fast_padded_malloc(&s->buffer, &s->buffer_size, buf_end - *buf_ptr);

    if (!s->buffer)

        return AVERROR(ENOMEM);



    /* unescape buffer of SOS, use special treatment for JPEG-LS */

    if (start_code == SOS && !s->ls) {

        const uint8_t *src = *buf_ptr;

        uint8_t *dst = s->buffer;



        while (src < buf_end) {

            uint8_t x = *(src++);



            *(dst++) = x;

            if (s->avctx->codec_id != AV_CODEC_ID_THP) {

                if (x == 0xff) {

                    while (src < buf_end && x == 0xff)

                        x = *(src++);



                    if (x >= 0xd0 && x <= 0xd7)

                        *(dst++) = x;

                    else if (x)

                        break;

                }

            }

        }

        *unescaped_buf_ptr  = s->buffer;

        *unescaped_buf_size = dst - s->buffer;

        memset(s->buffer + *unescaped_buf_size, 0,

               AV_INPUT_BUFFER_PADDING_SIZE);



        av_log(s->avctx, AV_LOG_DEBUG, "escaping removed %"PTRDIFF_SPECIFIER" bytes\n",

               (buf_end - *buf_ptr) - (dst - s->buffer));

    } else if (start_code == SOS && s->ls) {

        const uint8_t *src = *buf_ptr;

        uint8_t *dst  = s->buffer;

        int bit_count = 0;

        int t = 0, b = 0;

        PutBitContext pb;



        /* find marker */

        while (src + t < buf_end) {

            uint8_t x = src[t++];

            if (x == 0xff) {

                while ((src + t < buf_end) && x == 0xff)

                    x = src[t++];

                if (x & 0x80) {

                    t -= FFMIN(2, t);

                    break;

                }

            }

        }

        bit_count = t * 8;

        init_put_bits(&pb, dst, t);



        /* unescape bitstream */

        while (b < t) {

            uint8_t x = src[b++];

            put_bits(&pb, 8, x);

            if (x == 0xFF) {

                x = src[b++];

                if (x & 0x80) {

                    av_log(s->avctx, AV_LOG_WARNING, "Invalid escape sequence\n");

                    x &= 0x7f;

                }

                put_bits(&pb, 7, x);

                bit_count--;

            }

        }

        flush_put_bits(&pb);



        *unescaped_buf_ptr  = dst;

        *unescaped_buf_size = (bit_count + 7) >> 3;

        memset(s->buffer + *unescaped_buf_size, 0,

               AV_INPUT_BUFFER_PADDING_SIZE);

    } else {

        *unescaped_buf_ptr  = *buf_ptr;

        *unescaped_buf_size = buf_end - *buf_ptr;

    }



    return start_code;

}

static int parse_picture_segment(AVCodecContext *avctx,

                                  const uint8_t *buf, int buf_size)

{

    PGSSubContext *ctx = avctx->priv_data;



    uint8_t sequence_desc;

    unsigned int rle_bitmap_len, width, height;

    uint16_t picture_id;



    if (buf_size <= 4)

        return -1;

    buf_size -= 4;



    picture_id = bytestream_get_be16(&buf);



    /* skip 1 unknown byte: Version Number */

    buf++;



    /* Read the Sequence Description to determine if start of RLE data or appended to previous RLE */

    sequence_desc = bytestream_get_byte(&buf);



    if (!(sequence_desc & 0x80)) {

        /* Additional RLE data */

        if (buf_size > ctx->pictures[picture_id].rle_remaining_len)

            return -1;



        memcpy(ctx->pictures[picture_id].rle + ctx->pictures[picture_id].rle_data_len, buf, buf_size);

        ctx->pictures[picture_id].rle_data_len += buf_size;

        ctx->pictures[picture_id].rle_remaining_len -= buf_size;



        return 0;

    }



    if (buf_size <= 7)

        return -1;

    buf_size -= 7;



    /* Decode rle bitmap length, stored size includes width/height data */

    rle_bitmap_len = bytestream_get_be24(&buf) - 2*2;



    /* Get bitmap dimensions from data */

    width  = bytestream_get_be16(&buf);

    height = bytestream_get_be16(&buf);



    /* Make sure the bitmap is not too large */

    if (avctx->width < width || avctx->height < height) {

        av_log(avctx, AV_LOG_ERROR, "Bitmap dimensions larger than video.\n");

        return -1;

    }



    if (buf_size > rle_bitmap_len) {

        av_log(avctx, AV_LOG_ERROR, "too much RLE data\n");

        return AVERROR_INVALIDDATA;

    }



    ctx->pictures[picture_id].w = width;

    ctx->pictures[picture_id].h = height;



    av_fast_malloc(&ctx->pictures[picture_id].rle, &ctx->pictures[picture_id].rle_buffer_size, rle_bitmap_len);



    if (!ctx->pictures[picture_id].rle)

        return -1;



    memcpy(ctx->pictures[picture_id].rle, buf, buf_size);

    ctx->pictures[picture_id].rle_data_len      = buf_size;

    ctx->pictures[picture_id].rle_remaining_len = rle_bitmap_len - buf_size;



    return 0;

}

static int64_t get_pts(const char *buf, int *duration)

{

    int i, hour, min, sec, hsec;

    int he, me, se, mse;



    for (i=0; i<2; i++) {

        int64_t start, end;

        if (sscanf(buf, "%d:%2d:%2d%*1[,.]%3d --> %d:%2d:%2d%*1[,.]%3d",

                   &hour, &min, &sec, &hsec, &he, &me, &se, &mse) == 8) {

            min += 60*hour;

            sec += 60*min;

            start = sec*1000+hsec;

            me += 60*he;

            se += 60*me;

            end = se*1000+mse;

            *duration = end - start;

            return start;

        }

        buf += strcspn(buf, "\n") + 1;

    }

    return AV_NOPTS_VALUE;

}

int av_parse_color(uint8_t *rgba_color, const char *color_string, void *log_ctx)

{

    if (!strcasecmp(color_string, "random") || !strcasecmp(color_string, "bikeshed")) {

        int rgba = av_get_random_seed();

        rgba_color[0] = rgba >> 24;

        rgba_color[1] = rgba >> 16;

        rgba_color[2] = rgba >> 8;

        rgba_color[3] = rgba;

    } else

    if (!strncmp(color_string, "0x", 2)) {

        char *tail;

        int len = strlen(color_string);

        unsigned int rgba = strtoul(color_string, &tail, 16);



        if (*tail || (len != 8 && len != 10)) {

            av_log(log_ctx, AV_LOG_ERROR, "Invalid 0xRRGGBB[AA] color string: '%s'\n", color_string);

            return AVERROR(EINVAL);

        }

        if (len == 10) {

            rgba_color[3] = rgba;

            rgba >>= 8;

        }

        rgba_color[0] = rgba >> 16;

        rgba_color[1] = rgba >> 8;

        rgba_color[2] = rgba;

    } else {

        const ColorEntry *entry = bsearch(color_string,

                                          color_table,

                                          FF_ARRAY_ELEMS(color_table),

                                          sizeof(ColorEntry),

                                          color_table_compare);

        if (!entry) {

            av_log(log_ctx, AV_LOG_ERROR, "Cannot find color '%s'\n", color_string);

            return AVERROR(EINVAL);

        }

        memcpy(rgba_color, entry->rgba_color, 4);

    }



    return 0;

}

av_cold int ff_mjpeg_encode_init(MpegEncContext *s)

{

    MJpegContext *m;



    av_assert0(s->slice_context_count == 1);



    if (s->width > 65500 || s->height > 65500) {

        av_log(s, AV_LOG_ERROR, "JPEG does not support resolutions above 65500x65500\n");

        return AVERROR(EINVAL);

    }



    m = av_malloc(sizeof(MJpegContext));

    if (!m)

        return AVERROR(ENOMEM);



    s->min_qcoeff=-1023;

    s->max_qcoeff= 1023;



    // Build default Huffman tables.

    // These may be overwritten later with more optimal Huffman tables, but

    // they are needed at least right now for some processes like trellis.

    ff_mjpeg_build_huffman_codes(m->huff_size_dc_luminance,

                                 m->huff_code_dc_luminance,

                                 avpriv_mjpeg_bits_dc_luminance,

                                 avpriv_mjpeg_val_dc);

    ff_mjpeg_build_huffman_codes(m->huff_size_dc_chrominance,

                                 m->huff_code_dc_chrominance,

                                 avpriv_mjpeg_bits_dc_chrominance,

                                 avpriv_mjpeg_val_dc);

    ff_mjpeg_build_huffman_codes(m->huff_size_ac_luminance,

                                 m->huff_code_ac_luminance,

                                 avpriv_mjpeg_bits_ac_luminance,

                                 avpriv_mjpeg_val_ac_luminance);

    ff_mjpeg_build_huffman_codes(m->huff_size_ac_chrominance,

                                 m->huff_code_ac_chrominance,

                                 avpriv_mjpeg_bits_ac_chrominance,

                                 avpriv_mjpeg_val_ac_chrominance);



    ff_init_uni_ac_vlc(m->huff_size_ac_luminance,   m->uni_ac_vlc_len);

    ff_init_uni_ac_vlc(m->huff_size_ac_chrominance, m->uni_chroma_ac_vlc_len);

    s->intra_ac_vlc_length      =

    s->intra_ac_vlc_last_length = m->uni_ac_vlc_len;

    s->intra_chroma_ac_vlc_length      =

    s->intra_chroma_ac_vlc_last_length = m->uni_chroma_ac_vlc_len;



    // Buffers start out empty.

    m->huff_ncode = 0;

    s->mjpeg_ctx = m;



    return alloc_huffman(s);

}

void fft_calc_altivec(FFTContext *s, FFTComplex *z)

{

POWERPC_TBL_DECLARE(altivec_fft_num, s->nbits >= 6);

#ifdef ALTIVEC_USE_REFERENCE_C_CODE

    int ln = s->nbits;

    int	j, np, np2;

    int	nblocks, nloops;

    register FFTComplex *p, *q;

    FFTComplex *exptab = s->exptab;

    int l;

    FFTSample tmp_re, tmp_im;



POWERPC_TBL_START_COUNT(altivec_fft_num, s->nbits >= 6);



    np = 1 << ln;



    /* pass 0 */



    p=&z[0];

    j=(np >> 1);

    do {

        BF(p[0].re, p[0].im, p[1].re, p[1].im, 

           p[0].re, p[0].im, p[1].re, p[1].im);

        p+=2;

    } while (--j != 0);



    /* pass 1 */





    p=&z[0];

    j=np >> 2;

    if (s->inverse) {

        do {

            BF(p[0].re, p[0].im, p[2].re, p[2].im, 

               p[0].re, p[0].im, p[2].re, p[2].im);

            BF(p[1].re, p[1].im, p[3].re, p[3].im, 

               p[1].re, p[1].im, -p[3].im, p[3].re);

            p+=4;

        } while (--j != 0);

    } else {

        do {

            BF(p[0].re, p[0].im, p[2].re, p[2].im, 

               p[0].re, p[0].im, p[2].re, p[2].im);

            BF(p[1].re, p[1].im, p[3].re, p[3].im, 

               p[1].re, p[1].im, p[3].im, -p[3].re);

            p+=4;

        } while (--j != 0);

    }

    /* pass 2 .. ln-1 */



    nblocks = np >> 3;

    nloops = 1 << 2;

    np2 = np >> 1;

    do {

        p = z;

        q = z + nloops;

        for (j = 0; j < nblocks; ++j) {

            BF(p->re, p->im, q->re, q->im,

               p->re, p->im, q->re, q->im);



            p++;

            q++;

            for(l = nblocks; l < np2; l += nblocks) {

                CMUL(tmp_re, tmp_im, exptab[l].re, exptab[l].im, q->re, q->im);

                BF(p->re, p->im, q->re, q->im,

                   p->re, p->im, tmp_re, tmp_im);

                p++;

                q++;

            }



            p += nloops;

            q += nloops;

        }

        nblocks = nblocks >> 1;

        nloops = nloops << 1;

    } while (nblocks != 0);



POWERPC_TBL_STOP_COUNT(altivec_fft_num, s->nbits >= 6);



#else /* ALTIVEC_USE_REFERENCE_C_CODE */

#ifdef CONFIG_DARWIN

    register const vector float vczero = (const vector float)(0.);

#else

    register const vector float vczero = (const vector float){0.,0.,0.,0.};

#endif



    int ln = s->nbits;

    int	j, np, np2;

    int	nblocks, nloops;

    register FFTComplex *p, *q;

    FFTComplex *cptr, *cptr1;

    int k;



POWERPC_TBL_START_COUNT(altivec_fft_num, s->nbits >= 6);



    np = 1 << ln;



    {

        vector float *r, a, b, a1, c1, c2;



        r = (vector float *)&z[0];



        c1 = vcii(p,p,n,n);



        if (s->inverse)

            {

                c2 = vcii(p,p,n,p);

            }

        else

            {

                c2 = vcii(p,p,p,n);

            }



        j = (np >> 2);

        do {

            a = vec_ld(0, r);

            a1 = vec_ld(sizeof(vector float), r);



            b = vec_perm(a,a,vcprmle(1,0,3,2));

            a = vec_madd(a,c1,b);

            /* do the pass 0 butterfly */



            b = vec_perm(a1,a1,vcprmle(1,0,3,2));

            b = vec_madd(a1,c1,b);

            /* do the pass 0 butterfly */



            /* multiply third by -i */

            b = vec_perm(b,b,vcprmle(2,3,1,0));



            /* do the pass 1 butterfly */

            vec_st(vec_madd(b,c2,a), 0, r);

            vec_st(vec_nmsub(b,c2,a), sizeof(vector float), r);



            r += 2;

        } while (--j != 0);

    }

    /* pass 2 .. ln-1 */



    nblocks = np >> 3;

    nloops = 1 << 2;

    np2 = np >> 1;



    cptr1 = s->exptab1;

    do {

        p = z;

        q = z + nloops;

        j = nblocks;

        do {

            cptr = cptr1;

            k = nloops >> 1;

            do {

                vector float a,b,c,t1;



                a = vec_ld(0, (float*)p);

                b = vec_ld(0, (float*)q);



                /* complex mul */

                c = vec_ld(0, (float*)cptr);

                /*  cre*re cim*re */

                t1 = vec_madd(c, vec_perm(b,b,vcprmle(2,2,0,0)),vczero);

                c = vec_ld(sizeof(vector float), (float*)cptr);

                /*  -cim*im cre*im */

                b = vec_madd(c, vec_perm(b,b,vcprmle(3,3,1,1)),t1);



                /* butterfly */

                vec_st(vec_add(a,b), 0, (float*)p);

                vec_st(vec_sub(a,b), 0, (float*)q);



                p += 2;

                q += 2;

                cptr += 4;

            } while (--k);



            p += nloops;

            q += nloops;

        } while (--j);

        cptr1 += nloops * 2;

        nblocks = nblocks >> 1;

        nloops = nloops << 1;

    } while (nblocks != 0);



POWERPC_TBL_STOP_COUNT(altivec_fft_num, s->nbits >= 6);



#endif /* ALTIVEC_USE_REFERENCE_C_CODE */

}

static void RENAME(lumRangeToJpeg)(int16_t *dst, int width)

{

    int i;

    for (i = 0; i < width; i++)

        dst[i] = (FFMIN(dst[i],30189)*19077 - 39057361)>>14;

}

