static int amr_wb_encode_frame(AVCodecContext *avctx, AVPacket *avpkt,

                               const AVFrame *frame, int *got_packet_ptr)

{

    AMRWBContext *s = avctx->priv_data;

    const int16_t *samples = (const int16_t *)frame->data[0];

    int size, ret;



    if ((ret = ff_alloc_packet2(avctx, avpkt, MAX_PACKET_SIZE)))

        return ret;



    if (s->last_bitrate != avctx->bit_rate) {

        s->mode         = get_wb_bitrate_mode(avctx->bit_rate, avctx);

        s->last_bitrate = avctx->bit_rate;

    }

    size = E_IF_encode(s->state, s->mode, samples, avpkt->data, s->allow_dtx);

    if (size <= 0 || size > MAX_PACKET_SIZE) {

        av_log(avctx, AV_LOG_ERROR, "Error encoding frame\n");

        return AVERROR(EINVAL);

    }



    if (frame->pts != AV_NOPTS_VALUE)

        avpkt->pts = frame->pts - ff_samples_to_time_base(avctx, avctx->delay);



    avpkt->size = size;

    *got_packet_ptr = 1;

    return 0;

}

static int decode_2(SANMVideoContext *ctx)

{

    int cx, cy, ret;



    for (cy = 0; cy != ctx->aligned_height; cy += 8) {

        for (cx = 0; cx != ctx->aligned_width; cx += 8) {

            if (ret = codec2subblock(ctx, cx, cy, 8))

                return ret;

        }

    }



    return 0;

}

static int ffv1_encode_frame(AVCodecContext *avctx, AVPacket *pkt,

                        const AVFrame *pict, int *got_packet)

{

    FFV1Context *f      = avctx->priv_data;

    RangeCoder *const c = &f->slice_context[0]->c;

    int used_count      = 0;

    uint8_t keystate    = 128;

    uint8_t *buf_p;

    int i, ret;



    f->frame = pict;



    if ((ret = ff_alloc_packet(pkt, avctx->width * avctx->height *

                             ((8 * 2 + 1 + 1) * 4) / 8 +

                             AV_INPUT_BUFFER_MIN_SIZE)) < 0) {

        av_log(avctx, AV_LOG_ERROR, "Error getting output packet.\n");

        return ret;

    }



    ff_init_range_encoder(c, pkt->data, pkt->size);

    ff_build_rac_states(c, 0.05 * (1LL << 32), 256 - 8);



    if (avctx->gop_size == 0 || f->picture_number % avctx->gop_size == 0) {

        put_rac(c, &keystate, 1);

        f->key_frame = 1;

        f->gob_count++;

        write_header(f);

    } else {

        put_rac(c, &keystate, 0);

        f->key_frame = 0;

    }



    if (f->ac > 1) {

        int i;

        for (i = 1; i < 256; i++) {

            c->one_state[i]        = f->state_transition[i];

            c->zero_state[256 - i] = 256 - c->one_state[i];

        }

    }



    for (i = 1; i < f->slice_count; i++) {

        FFV1Context *fs = f->slice_context[i];

        uint8_t *start  = pkt->data +

                          (pkt->size - used_count) * (int64_t)i / f->slice_count;

        int len = pkt->size / f->slice_count;

        ff_init_range_encoder(&fs->c, start, len);

    }

    avctx->execute(avctx, encode_slice, &f->slice_context[0], NULL,

                   f->slice_count, sizeof(void *));



    buf_p = pkt->data;

    for (i = 0; i < f->slice_count; i++) {

        FFV1Context *fs = f->slice_context[i];

        int bytes;



        if (fs->ac) {

            uint8_t state = 129;

            put_rac(&fs->c, &state, 0);

            bytes = ff_rac_terminate(&fs->c);

        } else {

            flush_put_bits(&fs->pb); // FIXME: nicer padding

            bytes = fs->ac_byte_count + (put_bits_count(&fs->pb) + 7) / 8;

        }

        if (i > 0 || f->version > 2) {

            av_assert0(bytes < pkt->size / f->slice_count);

            memmove(buf_p, fs->c.bytestream_start, bytes);

            av_assert0(bytes < (1 << 24));

            AV_WB24(buf_p + bytes, bytes);

            bytes += 3;

        }

        if (f->ec) {

            unsigned v;

            buf_p[bytes++] = 0;

            v = av_crc(av_crc_get_table(AV_CRC_32_IEEE), 0, buf_p, bytes);

            AV_WL32(buf_p + bytes, v);

            bytes += 4;

        }

        buf_p += bytes;

    }



    if ((avctx->flags & AV_CODEC_FLAG_PASS1) && (f->picture_number & 31) == 0) {

        int j, k, m;

        char *p   = avctx->stats_out;

        char *end = p + STATS_OUT_SIZE;



        memset(f->rc_stat, 0, sizeof(f->rc_stat));

        for (i = 0; i < f->quant_table_count; i++)

            memset(f->rc_stat2[i], 0, f->context_count[i] * sizeof(*f->rc_stat2[i]));



        for (j = 0; j < f->slice_count; j++) {

            FFV1Context *fs = f->slice_context[j];

            for (i = 0; i < 256; i++) {

                f->rc_stat[i][0] += fs->rc_stat[i][0];

                f->rc_stat[i][1] += fs->rc_stat[i][1];

            }

            for (i = 0; i < f->quant_table_count; i++) {

                for (k = 0; k < f->context_count[i]; k++)

                    for (m = 0; m < 32; m++) {

                        f->rc_stat2[i][k][m][0] += fs->rc_stat2[i][k][m][0];

                        f->rc_stat2[i][k][m][1] += fs->rc_stat2[i][k][m][1];

                    }

            }

        }



        for (j = 0; j < 256; j++) {

            snprintf(p, end - p, "%" PRIu64 " %" PRIu64 " ",

                     f->rc_stat[j][0], f->rc_stat[j][1]);

            p += strlen(p);

        }

        snprintf(p, end - p, "\n");



        for (i = 0; i < f->quant_table_count; i++) {

            for (j = 0; j < f->context_count[i]; j++)

                for (m = 0; m < 32; m++) {

                    snprintf(p, end - p, "%" PRIu64 " %" PRIu64 " ",

                             f->rc_stat2[i][j][m][0], f->rc_stat2[i][j][m][1]);

                    p += strlen(p);

                }

        }

        snprintf(p, end - p, "%d\n", f->gob_count);

    } else if (avctx->flags & AV_CODEC_FLAG_PASS1)

        avctx->stats_out[0] = '\0';



#if FF_API_CODED_FRAME

FF_DISABLE_DEPRECATION_WARNINGS

    avctx->coded_frame->key_frame = f->key_frame;

FF_ENABLE_DEPRECATION_WARNINGS

#endif



    f->picture_number++;

    pkt->size   = buf_p - pkt->data;

    pkt->flags |= AV_PKT_FLAG_KEY * f->key_frame;

    *got_packet = 1;



    return 0;

}

static int mov_write_packet(AVFormatContext *s, int stream_index,

                            const uint8_t *buf, int size, int64_t pts)

{

    MOVContext *mov = s->priv_data;

    ByteIOContext *pb = &s->pb;

    AVCodecContext *enc = &s->streams[stream_index]->codec;

    MOVTrack* trk = &mov->tracks[stream_index];

    int cl, id;

    unsigned int samplesInChunk = 0;



    if (url_is_streamed(&s->pb)) return 0; /* Can't handle that */

    if (!size) return 0; /* Discard 0 sized packets */



    if (enc->codec_type == CODEC_TYPE_VIDEO ) {

        samplesInChunk = 1;

    }

    else if (enc->codec_type == CODEC_TYPE_AUDIO ) {

        if( enc->codec_id == CODEC_ID_AMR_NB) {

            /* We must find out how many AMR blocks there are in one packet */

            static uint16_t packed_size[16] =

                {13, 14, 16, 18, 20, 21, 27, 32, 6, 0, 0, 0, 0, 0, 0, 0};

            int len = 0;



            while (len < size && samplesInChunk < 100) {

                len += packed_size[(buf[len] >> 3) & 0x0F];

                samplesInChunk++;

            }

        }

        else if(enc->codec_id == CODEC_ID_PCM_ALAW) {

            samplesInChunk = size/enc->channels;

        }

        else {

            samplesInChunk = 1;

        }

    }



    if ((enc->codec_id == CODEC_ID_MPEG4 || enc->codec_id == CODEC_ID_AAC)

        && trk->vosLen == 0) {

        assert(enc->extradata_size);



        trk->vosLen = enc->extradata_size;

        trk->vosData = av_malloc(trk->vosLen);

        memcpy(trk->vosData, enc->extradata, trk->vosLen);

    }



    cl = trk->entry / MOV_INDEX_CLUSTER_SIZE;

    id = trk->entry % MOV_INDEX_CLUSTER_SIZE;



    if (trk->ents_allocated <= trk->entry) {

        trk->cluster = av_realloc(trk->cluster, (cl+1)*sizeof(void*)); 

        if (!trk->cluster)

            return -1;

        trk->cluster[cl] = av_malloc(MOV_INDEX_CLUSTER_SIZE*sizeof(MOVIentry));

        if (!trk->cluster[cl])

            return -1;

        trk->ents_allocated += MOV_INDEX_CLUSTER_SIZE;

    }

    if (mov->mdat_written == 0) {

        mov_write_mdat_tag(pb, mov);

        mov->mdat_written = 1;

        mov->time = Timestamp();

    }



    trk->cluster[cl][id].pos = url_ftell(pb) - mov->movi_list;

    trk->cluster[cl][id].samplesInChunk = samplesInChunk;

    trk->cluster[cl][id].size = size;

    trk->cluster[cl][id].entries = samplesInChunk;

    if(enc->codec_type == CODEC_TYPE_VIDEO) {

        trk->cluster[cl][id].key_frame = enc->coded_frame->key_frame;

        if(enc->coded_frame->pict_type == FF_I_TYPE)

            trk->hasKeyframes = 1;

    }

    trk->enc = enc;

    trk->entry++;

    trk->sampleCount += samplesInChunk;

    trk->mdat_size += size;



    put_buffer(pb, buf, size);



    put_flush_packet(pb);

    return 0;

}

int ff_get_line(AVIOContext *s, char *buf, int maxlen)

{

    int i = 0;

    char c;



    do {

        c = avio_r8(s);

        if (c && i < maxlen-1)

            buf[i++] = c;

    } while (c != '\n' && c != '\r' && c);

    if (c == '\r' && avio_r8(s) != '\n')

        avio_skip(s, -1);



    buf[i] = 0;

    return i;

}

int ff_h264_decode_ref_pic_list_reordering(H264Context *h)

{

    int list, index, pic_structure, i;



    print_short_term(h);

    print_long_term(h);



    for (list = 0; list < h->list_count; list++) {

        for (i = 0; i < h->ref_count[list]; i++)

            COPY_PICTURE(&h->ref_list[list][i], &h->default_ref_list[list][i]);



        if (get_bits1(&h->gb)) {

            int pred = h->curr_pic_num;



            for (index = 0; ; index++) {

                unsigned int reordering_of_pic_nums_idc = get_ue_golomb_31(&h->gb);

                unsigned int pic_id;

                int i;

                Picture *ref = NULL;



                if (reordering_of_pic_nums_idc == 3)

                    break;



                if (index >= h->ref_count[list]) {

                    av_log(h->avctx, AV_LOG_ERROR, "reference count overflow\n");

                    return -1;

                }



                if (reordering_of_pic_nums_idc < 3) {

                    if (reordering_of_pic_nums_idc < 2) {

                        const unsigned int abs_diff_pic_num = get_ue_golomb(&h->gb) + 1;

                        int frame_num;



                        if (abs_diff_pic_num > h->max_pic_num) {

                            av_log(h->avctx, AV_LOG_ERROR, "abs_diff_pic_num overflow\n");

                            return -1;

                        }



                        if (reordering_of_pic_nums_idc == 0)

                            pred -= abs_diff_pic_num;

                        else

                            pred += abs_diff_pic_num;

                        pred &= h->max_pic_num - 1;



                        frame_num = pic_num_extract(h, pred, &pic_structure);



                        for (i = h->short_ref_count - 1; i >= 0; i--) {

                            ref = h->short_ref[i];

                            assert(ref->reference);

                            assert(!ref->long_ref);

                            if (ref->frame_num == frame_num &&

                                (ref->reference & pic_structure))

                                break;

                        }

                        if (i >= 0)

                            ref->pic_id = pred;

                    } else {

                        int long_idx;

                        pic_id = get_ue_golomb(&h->gb); //long_term_pic_idx



                        long_idx = pic_num_extract(h, pic_id, &pic_structure);



                        if (long_idx > 31) {

                            av_log(h->avctx, AV_LOG_ERROR, "long_term_pic_idx overflow\n");

                            return -1;

                        }

                        ref = h->long_ref[long_idx];

                        assert(!(ref && !ref->reference));

                        if (ref && (ref->reference & pic_structure)) {

                            ref->pic_id = pic_id;

                            assert(ref->long_ref);

                            i = 0;

                        } else {

                            i = -1;

                        }

                    }



                    if (i < 0) {

                        av_log(h->avctx, AV_LOG_ERROR, "reference picture missing during reorder\n");

                        memset(&h->ref_list[list][index], 0, sizeof(Picture)); //FIXME

                    } else {

                        for (i = index; i + 1 < h->ref_count[list]; i++) {

                            if (ref->long_ref == h->ref_list[list][i].long_ref &&

                                ref->pic_id   == h->ref_list[list][i].pic_id)

                                break;

                        }

                        for (; i > index; i--) {

                            COPY_PICTURE(&h->ref_list[list][i], &h->ref_list[list][i - 1]);

                        }

                        COPY_PICTURE(&h->ref_list[list][index], ref);

                        if (FIELD_PICTURE(h)) {

                            pic_as_field(&h->ref_list[list][index], pic_structure);

                        }

                    }

                } else {

                    av_log(h->avctx, AV_LOG_ERROR, "illegal reordering_of_pic_nums_idc\n");

                    return -1;

                }

            }

        }

    }

    for (list = 0; list < h->list_count; list++) {

        for (index = 0; index < h->ref_count[list]; index++) {

            if (!h->ref_list[list][index].f.data[0]) {

                av_log(h->avctx, AV_LOG_ERROR, "Missing reference picture\n");

                if (h->default_ref_list[list][0].f.data[0])

                    COPY_PICTURE(&h->ref_list[list][index], &h->default_ref_list[list][0]);

                else

                    return -1;

            }

        }

    }



    return 0;

}

static enum AVHWDeviceType hw_device_match_type_by_hwaccel(enum HWAccelID hwaccel_id)

{

    int i;

    if (hwaccel_id == HWACCEL_NONE)

        return AV_HWDEVICE_TYPE_NONE;

    for (i = 0; hwaccels[i].name; i++) {

        if (hwaccels[i].id == hwaccel_id)

            return hwaccels[i].device_type;

    }

    return AV_HWDEVICE_TYPE_NONE;

}

int swr_convert(struct SwrContext *s, uint8_t *out_arg[SWR_CH_MAX], int out_count,

                                const uint8_t *in_arg [SWR_CH_MAX], int  in_count){

    AudioData * in= &s->in;

    AudioData *out= &s->out;



    if(s->drop_output > 0){

        int ret;

        uint8_t *tmp_arg[SWR_CH_MAX];

        if((ret=swri_realloc_audio(&s->drop_temp, s->drop_output))<0)

            return ret;



        reversefill_audiodata(&s->drop_temp, tmp_arg);

        s->drop_output *= -1; //FIXME find a less hackish solution

        ret = swr_convert(s, tmp_arg, -s->drop_output, in_arg, in_count); //FIXME optimize but this is as good as never called so maybe it doesnt matter

        s->drop_output *= -1;

        if(ret>0)

            s->drop_output -= ret;



        if(s->drop_output || !out_arg)

            return 0;

        in_count = 0;

    }



    if(!in_arg){

        if(s->resample){

            if (!s->flushed)

                s->resampler->flush(s);

            s->resample_in_constraint = 0;

            s->flushed = 1;

        }else if(!s->in_buffer_count){

            return 0;

        }

    }else

        fill_audiodata(in ,  (void*)in_arg);



    fill_audiodata(out, out_arg);



    if(s->resample){

        int ret = swr_convert_internal(s, out, out_count, in, in_count);

        if(ret>0 && !s->drop_output)

            s->outpts += ret * (int64_t)s->in_sample_rate;

        return ret;

    }else{

        AudioData tmp= *in;

        int ret2=0;

        int ret, size;

        size = FFMIN(out_count, s->in_buffer_count);

        if(size){

            buf_set(&tmp, &s->in_buffer, s->in_buffer_index);

            ret= swr_convert_internal(s, out, size, &tmp, size);

            if(ret<0)

                return ret;

            ret2= ret;

            s->in_buffer_count -= ret;

            s->in_buffer_index += ret;

            buf_set(out, out, ret);

            out_count -= ret;

            if(!s->in_buffer_count)

                s->in_buffer_index = 0;

        }



        if(in_count){

            size= s->in_buffer_index + s->in_buffer_count + in_count - out_count;



            if(in_count > out_count) { //FIXME move after swr_convert_internal

                if(   size > s->in_buffer.count

                && s->in_buffer_count + in_count - out_count <= s->in_buffer_index){

                    buf_set(&tmp, &s->in_buffer, s->in_buffer_index);

                    copy(&s->in_buffer, &tmp, s->in_buffer_count);

                    s->in_buffer_index=0;

                }else

                    if((ret=swri_realloc_audio(&s->in_buffer, size)) < 0)

                        return ret;

            }



            if(out_count){

                size = FFMIN(in_count, out_count);

                ret= swr_convert_internal(s, out, size, in, size);

                if(ret<0)

                    return ret;

                buf_set(in, in, ret);

                in_count -= ret;

                ret2 += ret;

            }

            if(in_count){

                buf_set(&tmp, &s->in_buffer, s->in_buffer_index + s->in_buffer_count);

                copy(&tmp, in, in_count);

                s->in_buffer_count += in_count;

            }

        }

        if(ret2>0 && !s->drop_output)

            s->outpts += ret2 * (int64_t)s->in_sample_rate;

        return ret2;

    }

}

av_cold int ff_mjpeg_decode_init(AVCodecContext *avctx)

{

    MJpegDecodeContext *s = avctx->priv_data;

    int ret;



    if (!s->picture_ptr) {

        s->picture = av_frame_alloc();

        if (!s->picture)

            return AVERROR(ENOMEM);

        s->picture_ptr = s->picture;

    }



    s->avctx = avctx;

    ff_blockdsp_init(&s->bdsp, avctx);

    ff_hpeldsp_init(&s->hdsp, avctx->flags);

    ff_idctdsp_init(&s->idsp, avctx);

    ff_init_scantable(s->idsp.idct_permutation, &s->scantable,

                      ff_zigzag_direct);

    s->buffer_size   = 0;

    s->buffer        = NULL;

    s->start_code    = -1;

    s->first_picture = 1;

    s->org_height    = avctx->coded_height;

    avctx->chroma_sample_location = AVCHROMA_LOC_CENTER;

    avctx->colorspace = AVCOL_SPC_BT470BG;



    if ((ret = build_basic_mjpeg_vlc(s)) < 0)

        return ret;



    if (s->extern_huff) {

        av_log(avctx, AV_LOG_INFO, "mjpeg: using external huffman table\n");

        if ((ret = init_get_bits(&s->gb, avctx->extradata, avctx->extradata_size * 8)) < 0)

            return ret;

        if ((ret = ff_mjpeg_decode_dht(s))) {

            av_log(avctx, AV_LOG_ERROR,

                   "mjpeg: error using external huffman table\n");

            return ret;

        }

    }

    if (avctx->field_order == AV_FIELD_BB) { /* quicktime icefloe 019 */

        s->interlace_polarity = 1;           /* bottom field first */

        av_log(avctx, AV_LOG_DEBUG, "mjpeg bottom field first\n");

    }

    if (avctx->codec->id == AV_CODEC_ID_AMV)

        s->flipped = 1;



    return 0;

}

static int seg_write_trailer(struct AVFormatContext *s)

{

    SegmentContext *seg = s->priv_data;

    AVFormatContext *oc = seg->avf;

    int ret = 0;



    if (!oc)

        goto fail;



    if (!seg->write_header_trailer) {

        if ((ret = segment_end(oc, 0)) < 0)

            goto fail;

        open_null_ctx(&oc->pb);

        ret = av_write_trailer(oc);

        close_null_ctx(oc->pb);

    } else {

        ret = segment_end(oc, 1);

    }



    if (ret < 0)

        goto fail;



    if (seg->list && seg->list_type == LIST_HLS) {

        if ((ret = segment_hls_window(s, 1) < 0))

            goto fail;

    }



fail:

    avio_close(seg->pb);

    avformat_free_context(oc);

    return ret;

}

int ff_tempfile(const char *prefix, char **filename) {

    int fd=-1;

#if !HAVE_MKSTEMP

    *filename = tempnam(".", prefix);

#else

    size_t len = strlen(prefix) + 12; /* room for "/tmp/" and "XXXXXX\0" */

    *filename = av_malloc(len);

#endif

    /* -----common section-----*/

    if (*filename == NULL) {

        av_log(NULL, AV_LOG_ERROR, "ff_tempfile: Cannot allocate file name\n");

        return -1;

    }

#if !HAVE_MKSTEMP

    fd = avpriv_open(*filename, O_RDWR | O_BINARY | O_CREAT, 0444);

#else

    snprintf(*filename, len, "/tmp/%sXXXXXX", prefix);

    fd = mkstemp(*filename);

    if (fd < 0) {

        snprintf(*filename, len, "./%sXXXXXX", prefix);

        fd = mkstemp(*filename);

    }

#endif

    /* -----common section-----*/

    if (fd < 0) {

        av_log(NULL, AV_LOG_ERROR, "ff_tempfile: Cannot open temporary file %s\n", *filename);

        return -1;

    }

    return fd; /* success */

}

