    return push_frame(outlink);

int ff_j2k_dwt_init(DWTContext *s, uint16_t border[2][2], int decomp_levels, int type)

{

    int i, j, lev = decomp_levels, maxlen,

        b[2][2];



    if (decomp_levels >= FF_DWT_MAX_DECLVLS)

        return AVERROR_INVALIDDATA;

    s->ndeclevels = decomp_levels;

    s->type = type;



    for (i = 0; i < 2; i++)

        for(j = 0; j < 2; j++)

            b[i][j] = border[i][j];



    maxlen = FFMAX(b[0][1] - b[0][0],

                   b[1][1] - b[1][0]);



    while(--lev >= 0){

        for (i = 0; i < 2; i++){

            s->linelen[lev][i] = b[i][1] - b[i][0];

            s->mod[lev][i] = b[i][0] & 1;

            for (j = 0; j < 2; j++)

                b[i][j] = (b[i][j] + 1) >> 1;

        }

    }

    if (type == FF_DWT97)

        s->linebuf = av_malloc((maxlen + 12) * sizeof(float));

    else if (type == FF_DWT53)

        s->linebuf = av_malloc((maxlen + 6) * sizeof(int));

    else

        return -1;



    if (!s->linebuf)

        return AVERROR(ENOMEM);



    return 0;

}

static int read_block_types(AVCodecContext *avctx, GetBitContext *gb, Bundle *b)

{

    int t, v;

    int last = 0;

    const uint8_t *dec_end;



    CHECK_READ_VAL(gb, b, t);

    dec_end = b->cur_dec + t;

    if (dec_end > b->data_end) {

        av_log(avctx, AV_LOG_ERROR, "Too many block type values\n");

        return -1;

    }

    if (get_bits1(gb)) {

        v = get_bits(gb, 4);

        memset(b->cur_dec, v, t);

        b->cur_dec += t;

    } else {

        do {

            v = GET_HUFF(gb, b->tree);

            if (v < 12) {

                last = v;

                *b->cur_dec++ = v;

            } else {

                int run = bink_rlelens[v - 12];



                memset(b->cur_dec, last, run);

                b->cur_dec += run;

            }

        } while (b->cur_dec < dec_end);

    }

    return 0;

}

static int y41p_decode_frame(AVCodecContext *avctx, void *data,

                             int *got_frame, AVPacket *avpkt)

{

    AVFrame *pic = data;

    uint8_t *src = avpkt->data;

    uint8_t *y, *u, *v;

    int i, j, ret;



    if (avpkt->size < 3LL * avctx->height * avctx->width / 2) {

        av_log(avctx, AV_LOG_ERROR, "Insufficient input data.\n");

        return AVERROR(EINVAL);

    }



    if ((ret = ff_get_buffer(avctx, pic, 0)) < 0)

        return ret;



    pic->key_frame = 1;

    pic->pict_type = AV_PICTURE_TYPE_I;



    for (i = avctx->height - 1; i >= 0 ; i--) {

        y = &pic->data[0][i * pic->linesize[0]];

        u = &pic->data[1][i * pic->linesize[1]];

        v = &pic->data[2][i * pic->linesize[2]];

        for (j = 0; j < avctx->width; j += 8) {

            *(u++) = *src++;

            *(y++) = *src++;

            *(v++) = *src++;

            *(y++) = *src++;



            *(u++) = *src++;

            *(y++) = *src++;

            *(v++) = *src++;

            *(y++) = *src++;



            *(y++) = *src++;

            *(y++) = *src++;

            *(y++) = *src++;

            *(y++) = *src++;

        }

    }



    *got_frame = 1;



    return avpkt->size;

}

int ff_MPV_common_frame_size_change(MpegEncContext *s)

{

    int i, err = 0;



    if (s->slice_context_count > 1) {

        for (i = 0; i < s->slice_context_count; i++) {

            free_duplicate_context(s->thread_context[i]);

        }

        for (i = 1; i < s->slice_context_count; i++) {

            av_freep(&s->thread_context[i]);

        }

    } else

        free_duplicate_context(s);



    if ((err = free_context_frame(s)) < 0)

        return err;



    if (s->picture)

        for (i = 0; i < MAX_PICTURE_COUNT; i++) {

                s->picture[i].needs_realloc = 1;

        }



    s->last_picture_ptr         =

    s->next_picture_ptr         =

    s->current_picture_ptr      = NULL;



    // init

    if (s->codec_id == AV_CODEC_ID_MPEG2VIDEO && !s->progressive_sequence)

        s->mb_height = (s->height + 31) / 32 * 2;

    else

        s->mb_height = (s->height + 15) / 16;



    if ((s->width || s->height) &&

        av_image_check_size(s->width, s->height, 0, s->avctx))

        return AVERROR_INVALIDDATA;



    if ((err = init_context_frame(s)))

        goto fail;



    s->thread_context[0]   = s;



    if (s->width && s->height) {

        int nb_slices = s->slice_context_count;

        if (nb_slices > 1) {

            for (i = 1; i < nb_slices; i++) {

                s->thread_context[i] = av_malloc(sizeof(MpegEncContext));

                memcpy(s->thread_context[i], s, sizeof(MpegEncContext));

            }



            for (i = 0; i < nb_slices; i++) {

                if (init_duplicate_context(s->thread_context[i]) < 0)

                    goto fail;

                    s->thread_context[i]->start_mb_y =

                        (s->mb_height * (i) + nb_slices / 2) / nb_slices;

                    s->thread_context[i]->end_mb_y   =

                        (s->mb_height * (i + 1) + nb_slices / 2) / nb_slices;

            }

        } else {

            if (init_duplicate_context(s) < 0)

                goto fail;

            s->start_mb_y = 0;

            s->end_mb_y   = s->mb_height;

        }

        s->slice_context_count = nb_slices;

    }



    return 0;

 fail:

    ff_MPV_common_end(s);

    return err;

}

static int mjpeg_decode_scan_progressive_ac(MJpegDecodeContext *s, int ss,

                                            int se, int Ah, int Al)

{

    int mb_x, mb_y;

    int EOBRUN = 0;

    int c = s->comp_index[0];

    uint8_t *data = s->picture_ptr->data[c];

    int linesize  = s->linesize[c];

    int last_scan = 0;

    int16_t *quant_matrix = s->quant_matrixes[s->quant_sindex[0]];

    int bytes_per_pixel = 1 + (s->bits > 8);



    av_assert0(ss>=0 && Ah>=0 && Al>=0);

    if (se < ss || se > 63) {

        av_log(s->avctx, AV_LOG_ERROR, "SS/SE %d/%d is invalid\n", ss, se);

        return AVERROR_INVALIDDATA;

    }



    if (!Al) {

        s->coefs_finished[c] |= (2LL << se) - (1LL << ss);

        last_scan = !~s->coefs_finished[c];

    }



    if (s->interlaced && s->bottom_field)

        data += linesize >> 1;



    s->restart_count = 0;



    for (mb_y = 0; mb_y < s->mb_height; mb_y++) {

        uint8_t *ptr     = data + (mb_y * linesize * 8 >> s->avctx->lowres);

        int block_idx    = mb_y * s->block_stride[c];

        int16_t (*block)[64] = &s->blocks[c][block_idx];

        uint8_t *last_nnz    = &s->last_nnz[c][block_idx];

        for (mb_x = 0; mb_x < s->mb_width; mb_x++, block++, last_nnz++) {

                int ret;

                if (s->restart_interval && !s->restart_count)

                    s->restart_count = s->restart_interval;



                if (Ah)

                    ret = decode_block_refinement(s, *block, last_nnz, s->ac_index[0],

                                                  quant_matrix, ss, se, Al, &EOBRUN);

                else

                    ret = decode_block_progressive(s, *block, last_nnz, s->ac_index[0],

                                                   quant_matrix, ss, se, Al, &EOBRUN);

                if (ret < 0) {

                    av_log(s->avctx, AV_LOG_ERROR,

                           "error y=%d x=%d\n", mb_y, mb_x);

                    return AVERROR_INVALIDDATA;

                }



            if (last_scan) {

                    s->dsp.idct_put(ptr, linesize, *block);

                    if (s->bits & 7)

                        shift_output(s, ptr, linesize);

                    ptr += bytes_per_pixel*8 >> s->avctx->lowres;

            }

            if (handle_rstn(s, 0))

                EOBRUN = 0;

        }

    }

    return 0;

}

