static void init_custom_qm(VC2EncContext *s)

{

    int level, orientation;



    if (s->quant_matrix == VC2_QM_DEF) {

        for (level = 0; level < s->wavelet_depth; level++) {

            for (orientation = 0; orientation < 4; orientation++) {

                if (level <= 3)

                    s->quant[level][orientation] = ff_dirac_default_qmat[s->wavelet_idx][level][orientation];

                else

                    s->quant[level][orientation] = vc2_qm_col_tab[level][orientation];

            }

        }

    } else if (s->quant_matrix == VC2_QM_COL) {

        for (level = 0; level < s->wavelet_depth; level++) {

            for (orientation = 0; orientation < 4; orientation++) {

                s->quant[level][orientation] = vc2_qm_col_tab[level][orientation];

            }

        }

    } else {

        for (level = 0; level < s->wavelet_depth; level++) {

            for (orientation = 0; orientation < 4; orientation++) {

                s->quant[level][orientation] = vc2_qm_flat_tab[level][orientation];

            }

        }

    }

}

static void vc1_decode_b_mb_intfi(VC1Context *v)

{

    MpegEncContext *s = &v->s;

    GetBitContext *gb = &s->gb;

    int i, j;

    int mb_pos = s->mb_x + s->mb_y * s->mb_stride;

    int cbp = 0; /* cbp decoding stuff */

    int mqdiff, mquant; /* MB quantization */

    int ttmb = v->ttfrm; /* MB Transform type */

    int mb_has_coeffs = 0; /* last_flag */

    int val; /* temp value */

    int first_block = 1;

    int dst_idx, off;

    int fwd;

    int dmv_x[2], dmv_y[2], pred_flag[2];

    int bmvtype = BMV_TYPE_BACKWARD;

    int idx_mbmode;

    int av_uninit(interpmvp);



    mquant      = v->pq; /* Lossy initialization */

    s->mb_intra = 0;



    idx_mbmode = get_vlc2(gb, v->mbmode_vlc->table, VC1_IF_MBMODE_VLC_BITS, 2);

    if (idx_mbmode <= 1) { // intra MB

        s->mb_intra = v->is_intra[s->mb_x] = 1;

        s->current_picture.motion_val[1][s->block_index[0]][0] = 0;

        s->current_picture.motion_val[1][s->block_index[0]][1] = 0;

        s->current_picture.mb_type[mb_pos + v->mb_off]         = MB_TYPE_INTRA;

        GET_MQUANT();

        s->current_picture.qscale_table[mb_pos] = mquant;

        /* Set DC scale - y and c use the same (not sure if necessary here) */

        s->y_dc_scale = s->y_dc_scale_table[mquant];

        s->c_dc_scale = s->c_dc_scale_table[mquant];

        v->s.ac_pred  = v->acpred_plane[mb_pos] = get_bits1(gb);

        mb_has_coeffs = idx_mbmode & 1;

        if (mb_has_coeffs)

            cbp = 1 + get_vlc2(&v->s.gb, v->cbpcy_vlc->table, VC1_ICBPCY_VLC_BITS, 2);

        dst_idx = 0;

        for (i = 0; i < 6; i++) {

            s->dc_val[0][s->block_index[i]] = 0;

            dst_idx += i >> 2;

            val = ((cbp >> (5 - i)) & 1);

            v->mb_type[0][s->block_index[i]] = s->mb_intra;

            v->a_avail                       = v->c_avail = 0;

            if (i == 2 || i == 3 || !s->first_slice_line)

                v->a_avail = v->mb_type[0][s->block_index[i] - s->block_wrap[i]];

            if (i == 1 || i == 3 || s->mb_x)

                v->c_avail = v->mb_type[0][s->block_index[i] - 1];



            vc1_decode_intra_block(v, s->block[i], i, val, mquant,

                                   (i & 4) ? v->codingset2 : v->codingset);

            if ((i>3) && (s->flags & CODEC_FLAG_GRAY))

                continue;

            v->vc1dsp.vc1_inv_trans_8x8(s->block[i]);

            if (v->rangeredfrm)

                for (j = 0; j < 64; j++)

                    s->block[i][j] <<= 1;

            off  = (i & 4) ? 0 : ((i & 1) * 8 + (i & 2) * 4 * s->linesize);

            s->dsp.put_signed_pixels_clamped(s->block[i], s->dest[dst_idx] + off, (i & 4) ? s->uvlinesize : s->linesize);

            // TODO: yet to perform loop filter

        }

    } else {

        s->mb_intra = v->is_intra[s->mb_x] = 0;

        s->current_picture.mb_type[mb_pos + v->mb_off] = MB_TYPE_16x16;

        for (i = 0; i < 6; i++) v->mb_type[0][s->block_index[i]] = 0;

        if (v->fmb_is_raw)

            fwd = v->forward_mb_plane[mb_pos] = get_bits1(gb);

        else

            fwd = v->forward_mb_plane[mb_pos];

        if (idx_mbmode <= 5) { // 1-MV

            dmv_x[0]     = dmv_x[1] = dmv_y[0] = dmv_y[1] = 0;

            pred_flag[0] = pred_flag[1] = 0;

            if (fwd)

                bmvtype = BMV_TYPE_FORWARD;

            else {

                bmvtype = decode012(gb);

                switch (bmvtype) {

                case 0:

                    bmvtype = BMV_TYPE_BACKWARD;

                    break;

                case 1:

                    bmvtype = BMV_TYPE_DIRECT;

                    break;

                case 2:

                    bmvtype   = BMV_TYPE_INTERPOLATED;

                    interpmvp = get_bits1(gb);

                }

            }

            v->bmvtype = bmvtype;

            if (bmvtype != BMV_TYPE_DIRECT && idx_mbmode & 1) {

                get_mvdata_interlaced(v, &dmv_x[bmvtype == BMV_TYPE_BACKWARD], &dmv_y[bmvtype == BMV_TYPE_BACKWARD], &pred_flag[bmvtype == BMV_TYPE_BACKWARD]);

            }

            if (bmvtype == BMV_TYPE_INTERPOLATED && interpmvp) {

                get_mvdata_interlaced(v, &dmv_x[1], &dmv_y[1], &pred_flag[1]);

            }

            if (bmvtype == BMV_TYPE_DIRECT) {

                dmv_x[0] = dmv_y[0] = pred_flag[0] = 0;

                dmv_x[1] = dmv_y[1] = pred_flag[0] = 0;

            }

            vc1_pred_b_mv_intfi(v, 0, dmv_x, dmv_y, 1, pred_flag);

            vc1_b_mc(v, dmv_x, dmv_y, (bmvtype == BMV_TYPE_DIRECT), bmvtype);

            mb_has_coeffs = !(idx_mbmode & 2);

        } else { // 4-MV

            if (fwd)

                bmvtype = BMV_TYPE_FORWARD;

            v->bmvtype  = bmvtype;

            v->fourmvbp = get_vlc2(gb, v->fourmvbp_vlc->table, VC1_4MV_BLOCK_PATTERN_VLC_BITS, 1);

            for (i = 0; i < 6; i++) {

                if (i < 4) {

                    dmv_x[0] = dmv_y[0] = pred_flag[0] = 0;

                    dmv_x[1] = dmv_y[1] = pred_flag[1] = 0;

                    val = ((v->fourmvbp >> (3 - i)) & 1);

                    if (val) {

                        get_mvdata_interlaced(v, &dmv_x[bmvtype == BMV_TYPE_BACKWARD],

                                                 &dmv_y[bmvtype == BMV_TYPE_BACKWARD],

                                             &pred_flag[bmvtype == BMV_TYPE_BACKWARD]);

                    }

                    vc1_pred_b_mv_intfi(v, i, dmv_x, dmv_y, 0, pred_flag);

                    vc1_mc_4mv_luma(v, i, bmvtype == BMV_TYPE_BACKWARD, 0);

                } else if (i == 4)

                    vc1_mc_4mv_chroma(v, bmvtype == BMV_TYPE_BACKWARD);

            }

            mb_has_coeffs = idx_mbmode & 1;

        }

        if (mb_has_coeffs)

            cbp = 1 + get_vlc2(&v->s.gb, v->cbpcy_vlc->table, VC1_CBPCY_P_VLC_BITS, 2);

        if (cbp) {

            GET_MQUANT();

        }

        s->current_picture.qscale_table[mb_pos] = mquant;

        if (!v->ttmbf && cbp) {

            ttmb = get_vlc2(gb, ff_vc1_ttmb_vlc[v->tt_index].table, VC1_TTMB_VLC_BITS, 2);

        }

        dst_idx = 0;

        for (i = 0; i < 6; i++) {

            s->dc_val[0][s->block_index[i]] = 0;

            dst_idx += i >> 2;

            val = ((cbp >> (5 - i)) & 1);

            off = (i & 4) ? 0 : (i & 1) * 8 + (i & 2) * 4 * s->linesize;

            if (val) {

                vc1_decode_p_block(v, s->block[i], i, mquant, ttmb,

                                   first_block, s->dest[dst_idx] + off,

                                   (i & 4) ? s->uvlinesize : s->linesize,

                                   (i & 4) && (s->flags & CODEC_FLAG_GRAY), NULL);

                if (!v->ttmbf && ttmb < 8)

                    ttmb = -1;

                first_block = 0;

            }

        }

    }

}

static int libspeex_decode_frame(AVCodecContext *avctx, void *data,

                                 int *got_frame_ptr, AVPacket *avpkt)

{

    uint8_t *buf = avpkt->data;

    int buf_size = avpkt->size;

    LibSpeexContext *s = avctx->priv_data;

    int16_t *output;

    int ret, consumed = 0;



    /* get output buffer */

    s->frame.nb_samples = s->frame_size;

    if ((ret = ff_get_buffer(avctx, &s->frame)) < 0) {

        av_log(avctx, AV_LOG_ERROR, "get_buffer() failed\n");

        return ret;

    }

    output = (int16_t *)s->frame.data[0];



    /* if there is not enough data left for the smallest possible frame or the

       next 5 bits are a terminator code, reset the libspeex buffer using the

       current packet, otherwise ignore the current packet and keep decoding

       frames from the libspeex buffer. */

    if (speex_bits_remaining(&s->bits) < 5 ||

        speex_bits_peek_unsigned(&s->bits, 5) == 0x1F) {

        /* check for flush packet */

        if (!buf || !buf_size) {

            *got_frame_ptr = 0;

            return buf_size;

        }

        /* set new buffer */

        speex_bits_read_from(&s->bits, buf, buf_size);

        consumed = buf_size;

    }



    /* decode a single frame */

    ret = speex_decode_int(s->dec_state, &s->bits, output);

    if (ret <= -2) {

        av_log(avctx, AV_LOG_ERROR, "Error decoding Speex frame.\n");

        return AVERROR_INVALIDDATA;

    }

    if (avctx->channels == 2)

        speex_decode_stereo_int(output, s->frame_size, &s->stereo);



    *got_frame_ptr   = 1;

    *(AVFrame *)data = s->frame;



    return consumed;

}

static int doTest(uint8_t *ref[4], int refStride[4], int w, int h,

                  enum PixelFormat srcFormat, enum PixelFormat dstFormat,

                  int srcW, int srcH, int dstW, int dstH, int flags)

{

    uint8_t *src[4] = {0};

    uint8_t *dst[4] = {0};

    uint8_t *out[4] = {0};

    int srcStride[4], dstStride[4];

    int i;

    uint64_t ssdY, ssdU=0, ssdV=0, ssdA=0;

    struct SwsContext *srcContext = NULL, *dstContext = NULL,

                      *outContext = NULL;

    int res;



    res = 0;

    for (i=0; i<4; i++) {

        // avoid stride % bpp != 0

        if (srcFormat==PIX_FMT_RGB24 || srcFormat==PIX_FMT_BGR24)

            srcStride[i]= srcW*3;

        else if (srcFormat==PIX_FMT_RGB48BE || srcFormat==PIX_FMT_RGB48LE)

            srcStride[i]= srcW*6;

        else

            srcStride[i]= srcW*4;



        if (dstFormat==PIX_FMT_RGB24 || dstFormat==PIX_FMT_BGR24)

            dstStride[i]= dstW*3;

        else if (dstFormat==PIX_FMT_RGB48BE || dstFormat==PIX_FMT_RGB48LE)

            dstStride[i]= dstW*6;

        else

            dstStride[i]= dstW*4;



        /* Image buffers passed into libswscale can be allocated any way you

         * prefer, as long as they're aligned enough for the architecture, and

         * they're freed appropriately (such as using av_free for buffers

         * allocated with av_malloc). */

        /* An extra 16 bytes is being allocated because some scalers may write

         * out of bounds. */

        src[i]= av_mallocz(srcStride[i]*srcH+16);

        dst[i]= av_mallocz(dstStride[i]*dstH+16);

        out[i]= av_mallocz(refStride[i]*h);

        if (!src[i] || !dst[i] || !out[i]) {

            perror("Malloc");

            res = -1;



            goto end;

        }

    }



    srcContext= sws_getContext(w, h, PIX_FMT_YUVA420P, srcW, srcH, srcFormat, flags, NULL, NULL, NULL);

    if (!srcContext) {

        fprintf(stderr, "Failed to get %s ---> %s\n",

                av_pix_fmt_descriptors[PIX_FMT_YUVA420P].name,

                av_pix_fmt_descriptors[srcFormat].name);

        res = -1;



        goto end;

    }

    dstContext= sws_getContext(srcW, srcH, srcFormat, dstW, dstH, dstFormat, flags, NULL, NULL, NULL);

    if (!dstContext) {

        fprintf(stderr, "Failed to get %s ---> %s\n",

                av_pix_fmt_descriptors[srcFormat].name,

                av_pix_fmt_descriptors[dstFormat].name);

        res = -1;



        goto end;

    }

    outContext= sws_getContext(dstW, dstH, dstFormat, w, h, PIX_FMT_YUVA420P, flags, NULL, NULL, NULL);

    if (!outContext) {

        fprintf(stderr, "Failed to get %s ---> %s\n",

                av_pix_fmt_descriptors[dstFormat].name,

                av_pix_fmt_descriptors[PIX_FMT_YUVA420P].name);

        res = -1;



        goto end;

    }

//    printf("test %X %X %X -> %X %X %X\n", (int)ref[0], (int)ref[1], (int)ref[2],

//        (int)src[0], (int)src[1], (int)src[2]);



    sws_scale(srcContext, ref, refStride, 0, h   , src, srcStride);

    sws_scale(dstContext, src, srcStride, 0, srcH, dst, dstStride);

    sws_scale(outContext, dst, dstStride, 0, dstH, out, refStride);



    ssdY= getSSD(ref[0], out[0], refStride[0], refStride[0], w, h);

    if (hasChroma(srcFormat) && hasChroma(dstFormat)) {

        //FIXME check that output is really gray

        ssdU= getSSD(ref[1], out[1], refStride[1], refStride[1], (w+1)>>1, (h+1)>>1);

        ssdV= getSSD(ref[2], out[2], refStride[2], refStride[2], (w+1)>>1, (h+1)>>1);

    }

    if (isALPHA(srcFormat) && isALPHA(dstFormat))

        ssdA= getSSD(ref[3], out[3], refStride[3], refStride[3], w, h);



    ssdY/= w*h;

    ssdU/= w*h/4;

    ssdV/= w*h/4;

    ssdA/= w*h;



    printf(" %s %dx%d -> %s %4dx%4d flags=%2d SSD=%5"PRId64",%5"PRId64",%5"PRId64",%5"PRId64"\n",

           av_pix_fmt_descriptors[srcFormat].name, srcW, srcH,

           av_pix_fmt_descriptors[dstFormat].name, dstW, dstH,

           flags, ssdY, ssdU, ssdV, ssdA);

    fflush(stdout);



end:



    sws_freeContext(srcContext);

    sws_freeContext(dstContext);

    sws_freeContext(outContext);



    for (i=0; i<4; i++) {

        av_free(src[i]);

        av_free(dst[i]);

        av_free(out[i]);

    }



    return res;

}

