            {

                *(samples++) = s->decoded[0][i];

                *(samples++) = s->decoded[0][i] - s->decoded[1][i];

            }

            break;

        case RIGHT_SIDE:

            assert(s->channels == 2);

            for (i = 0; i < s->blocksize; i++)

            {

                *(samples++) = s->decoded[0][i] + s->decoded[1][i];

                *(samples++) = s->decoded[1][i];

            }

            break;

        case MID_SIDE:

            assert(s->channels == 2);

            for (i = 0; i < s->blocksize; i++)

            {

                int mid, side;

                mid = s->decoded[0][i];

                side = s->decoded[1][i];



                mid <<= 1;

                if (side & 1)

                    mid++;

                *(samples++) = (mid + side) >> 1;

                *(samples++) = (mid - side) >> 1;

            }

            break;

    }

#endif



    *data_size = (int8_t *)samples - (int8_t *)data;

    av_log(s->avctx, AV_LOG_DEBUG, "data size: %d\n", *data_size);



//    s->last_blocksize = s->blocksize;

end:

    i= (get_bits_count(&s->gb)+7)/8;;

    if(i > buf_size){

        av_log(s->avctx, AV_LOG_ERROR, "overread: %d\n", i - buf_size);

        return -1;

    }



    if(s->bitstream_size){

        s->bitstream_index += i;

        s->bitstream_size  -= i;

        return input_buf_size;

    }else 

        return i;

}

int64_t avcodec_guess_channel_layout(int nb_channels, enum CodecID codec_id, const char *fmt_name)

{

    switch(nb_channels) {

    case 1: return AV_CH_LAYOUT_MONO;

    case 2: return AV_CH_LAYOUT_STEREO;

    case 3: return AV_CH_LAYOUT_SURROUND;

    case 4: return AV_CH_LAYOUT_QUAD;

    case 5: return AV_CH_LAYOUT_5POINT0;

    case 6: return AV_CH_LAYOUT_5POINT1;

    case 8: return AV_CH_LAYOUT_7POINT1;

    default: return 0;

    }

}

static inline void downmix_2f_1r_to_dolby(float *samples)

{

    int i;



    for (i = 0; i < 256; i++) {

        samples[i] -= samples[i + 512];

        samples[i + 256] += samples[i + 512];

        samples[i + 512] = 0;

    }

}

