static int add_file(AVFormatContext *avf, char *filename, ConcatFile **rfile,

                    unsigned *nb_files_alloc)

{

    ConcatContext *cat = avf->priv_data;

    ConcatFile *file;

    char *url;

    size_t url_len;



    url_len = strlen(avf->filename) + strlen(filename) + 16;

    if (!(url = av_malloc(url_len)))

        return AVERROR(ENOMEM);

    ff_make_absolute_url(url, url_len, avf->filename, filename);

    av_free(filename);



    if (cat->nb_files >= *nb_files_alloc) {

        unsigned n = FFMAX(*nb_files_alloc * 2, 16);

        ConcatFile *new_files;

        if (n <= cat->nb_files || n > SIZE_MAX / sizeof(*cat->files) ||

            !(new_files = av_realloc(cat->files, n * sizeof(*cat->files))))

            return AVERROR(ENOMEM);

        cat->files = new_files;

        *nb_files_alloc = n;

    }



    file = &cat->files[cat->nb_files++];

    memset(file, 0, sizeof(*file));

    *rfile = file;



    file->url        = url;

    file->start_time = AV_NOPTS_VALUE;

    file->duration   = AV_NOPTS_VALUE;



    return 0;

}

static double compute_target_time(double frame_current_pts, VideoState *is)

{

    double delay, sync_threshold, diff;



    /* compute nominal delay */

    delay = frame_current_pts - is->frame_last_pts;

    if (delay <= 0 || delay >= 10.0) {

        /* if incorrect delay, use previous one */

        delay = is->frame_last_delay;

    } else {

        is->frame_last_delay = delay;

    }

    is->frame_last_pts = frame_current_pts;



    /* update delay to follow master synchronisation source */

    if (((is->av_sync_type == AV_SYNC_AUDIO_MASTER && is->audio_st) ||

         is->av_sync_type == AV_SYNC_EXTERNAL_CLOCK)) {

        /* if video is slave, we try to correct big delays by

           duplicating or deleting a frame */

        diff = get_video_clock(is) - get_master_clock(is);



        /* skip or repeat frame. We take into account the

           delay to compute the threshold. I still don't know

           if it is the best guess */

        sync_threshold = FFMAX(AV_SYNC_THRESHOLD, delay);

        if (fabs(diff) < AV_NOSYNC_THRESHOLD) {

            if (diff <= -sync_threshold)

                delay = 0;

            else if (diff >= sync_threshold)

                delay = 2 * delay;

        }

    }

    is->frame_timer += delay;



    av_log(NULL, AV_LOG_TRACE, "video: delay=%0.3f pts=%0.3f A-V=%f\n",

            delay, frame_current_pts, -diff);



    return is->frame_timer;

}

static int tee_write_header(AVFormatContext *avf)

{

    TeeContext *tee = avf->priv_data;

    unsigned nb_slaves = 0, i;

    const char *filename = avf->filename;

    char *slaves[MAX_SLAVES];

    int ret;



    while (*filename) {

        if (nb_slaves == MAX_SLAVES) {

            av_log(avf, AV_LOG_ERROR, "Maximum %d slave muxers reached.\n",

                   MAX_SLAVES);

            ret = AVERROR_PATCHWELCOME;

            goto fail;

        }

        if (!(slaves[nb_slaves++] = av_get_token(&filename, slave_delim))) {

            ret = AVERROR(ENOMEM);

            goto fail;

        }

        if (strspn(filename, slave_delim))

            filename++;

    }



    for (i = 0; i < nb_slaves; i++) {

        if ((ret = open_slave(avf, slaves[i], &tee->slaves[i])) < 0)

            goto fail;

        log_slave(&tee->slaves[i], avf, AV_LOG_VERBOSE);

        av_freep(&slaves[i]);

    }



    tee->nb_slaves = nb_slaves;



    for (i = 0; i < avf->nb_streams; i++) {

        int j, mapped = 0;

        for (j = 0; j < tee->nb_slaves; j++)

            mapped += tee->slaves[j].stream_map[i] >= 0;

        if (!mapped)

            av_log(avf, AV_LOG_WARNING, "Input stream #%d is not mapped "

                   "to any slave.\n", i);

    }

    return 0;



fail:

    for (i = 0; i < nb_slaves; i++)

        av_freep(&slaves[i]);

    close_slaves(avf);

    return ret;

}

void ffserver_parse_acl_row(FFServerStream *stream, FFServerStream* feed,
                            FFServerIPAddressACL *ext_acl,
                            const char *p, const char *filename, int line_num)
{
    char arg[1024];
    FFServerIPAddressACL acl;
    FFServerIPAddressACL *nacl;
    FFServerIPAddressACL **naclp;
    ffserver_get_arg(arg, sizeof(arg), &p);
    if (av_strcasecmp(arg, "allow") == 0)
        acl.action = IP_ALLOW;
    else if (av_strcasecmp(arg, "deny") == 0)
        acl.action = IP_DENY;
    else {
        fprintf(stderr, "%s:%d: ACL action '%s' should be ALLOW or DENY.\n",
                filename, line_num, arg);
    ffserver_get_arg(arg, sizeof(arg), &p);
    if (resolve_host(&acl.first, arg)) {
        fprintf(stderr,
                "%s:%d: ACL refers to invalid host or IP address '%s'\n",
                filename, line_num, arg);
    acl.last = acl.first;
    ffserver_get_arg(arg, sizeof(arg), &p);
    if (arg[0]) {
        if (resolve_host(&acl.last, arg)) {
            fprintf(stderr,
                    "%s:%d: ACL refers to invalid host or IP address '%s'\n",
                    filename, line_num, arg);
    nacl = av_mallocz(sizeof(*nacl));
    naclp = 0;
    acl.next = 0;
    *nacl = acl;
    if (stream)
        naclp = &stream->acl;
    else if (feed)
        naclp = &feed->acl;
    else if (ext_acl)
        naclp = &ext_acl;
    else
        fprintf(stderr, "%s:%d: ACL found not in <Stream> or <Feed>\n",
                filename, line_num);
    if (naclp) {
        while (*naclp)
            naclp = &(*naclp)->next;
        *naclp = nacl;
    } else
        av_free(nacl);
bail:
  return;

static void decode_422_bitstream(HYuvContext *s, int count)

{

    int i;



    count /= 2;



    if (count >= (get_bits_left(&s->gb)) / (31 * 4)) {

        for (i = 0; i < count && get_bits_left(&s->gb) > 0; i++) {

            READ_2PIX(s->temp[0][2 * i    ], s->temp[1][i], 1);

            READ_2PIX(s->temp[0][2 * i + 1], s->temp[2][i], 2);

        }




    } else {

        for (i = 0; i < count; i++) {

            READ_2PIX(s->temp[0][2 * i    ], s->temp[1][i], 1);

            READ_2PIX(s->temp[0][2 * i + 1], s->temp[2][i], 2);

        }

    }

}

static int dv_extract_audio(uint8_t* frame, uint8_t* ppcm[4],
                            const DVprofile *sys)
{
    int size, chan, i, j, d, of, smpls, freq, quant, half_ch;
    uint16_t lc, rc;
    const uint8_t* as_pack;
    uint8_t *pcm, ipcm;
    as_pack = dv_extract_pack(frame, dv_audio_source);
    if (!as_pack)    /* No audio ? */
        return 0;
    smpls =  as_pack[1] & 0x3f;       /* samples in this frame - min. samples */
    freq  = (as_pack[4] >> 3) & 0x07; /* 0 - 48kHz, 1 - 44,1kHz, 2 - 32kHz */
    quant =  as_pack[4] & 0x07;       /* 0 - 16bit linear, 1 - 12bit nonlinear */
    if (quant > 1)
        return -1; /* unsupported quantization */
    if (freq >= FF_ARRAY_ELEMS(dv_audio_frequency))
    size = (sys->audio_min_samples[freq] + smpls) * 4; /* 2ch, 2bytes */
    half_ch = sys->difseg_size / 2;
    /* We work with 720p frames split in half, thus even frames have
     * channels 0,1 and odd 2,3. */
    ipcm = (sys->height == 720 && !(frame[1] & 0x0C)) ? 2 : 0;
    /* for each DIF channel */
    for (chan = 0; chan < sys->n_difchan; chan++) {
        av_assert0(ipcm<4);
        pcm = ppcm[ipcm++];
        if (!pcm)
            break;
        /* for each DIF segment */
        for (i = 0; i < sys->difseg_size; i++) {
            frame += 6 * 80; /* skip DIF segment header */
            if (quant == 1 && i == half_ch) {
                /* next stereo channel (12bit mode only) */
                av_assert0(ipcm<4);
                pcm = ppcm[ipcm++];
                if (!pcm)
                    break;
            /* for each AV sequence */
            for (j = 0; j < 9; j++) {
                for (d = 8; d < 80; d += 2) {
                    if (quant == 0) {  /* 16bit quantization */
                        of = sys->audio_shuffle[i][j] + (d - 8) / 2 * sys->audio_stride;
                        if (of*2 >= size)
                            continue;
                        pcm[of*2]   = frame[d+1]; // FIXME: maybe we have to admit
                        pcm[of*2+1] = frame[d];   //        that DV is a big-endian PCM
                        if (pcm[of*2+1] == 0x80 && pcm[of*2] == 0x00)
                            pcm[of*2+1] = 0;
                    } else {           /* 12bit quantization */
                        lc = ((uint16_t)frame[d]   << 4) |
                             ((uint16_t)frame[d+2] >> 4);
                        rc = ((uint16_t)frame[d+1] << 4) |
                             ((uint16_t)frame[d+2] & 0x0f);
                        lc = (lc == 0x800 ? 0 : dv_audio_12to16(lc));
                        rc = (rc == 0x800 ? 0 : dv_audio_12to16(rc));
                        of = sys->audio_shuffle[i%half_ch][j] + (d - 8) / 3 * sys->audio_stride;
                        if (of*2 >= size)
                            continue;
                        pcm[of*2]   = lc & 0xff; // FIXME: maybe we have to admit
                        pcm[of*2+1] = lc >> 8;   //        that DV is a big-endian PCM
                        of = sys->audio_shuffle[i%half_ch+half_ch][j] +
                            (d - 8) / 3 * sys->audio_stride;
                        pcm[of*2]   = rc & 0xff; // FIXME: maybe we have to admit
                        pcm[of*2+1] = rc >> 8;   //        that DV is a big-endian PCM
                        ++d;
                frame += 16 * 80; /* 15 Video DIFs + 1 Audio DIF */
    return size;

void ff_mpeg4_encode_picture_header(MpegEncContext *s, int picture_number)

{

    int time_incr;

    int time_div, time_mod;



    if (s->pict_type == AV_PICTURE_TYPE_I) {

        if (!(s->avctx->flags & AV_CODEC_FLAG_GLOBAL_HEADER)) {

            if (s->strict_std_compliance < FF_COMPLIANCE_VERY_STRICT)  // HACK, the reference sw is buggy

                mpeg4_encode_visual_object_header(s);

            if (s->strict_std_compliance < FF_COMPLIANCE_VERY_STRICT || picture_number == 0)  // HACK, the reference sw is buggy

                mpeg4_encode_vol_header(s, 0, 0);

        }

        if (!(s->workaround_bugs & FF_BUG_MS))

            mpeg4_encode_gop_header(s);

    }



    s->partitioned_frame = s->data_partitioning && s->pict_type != AV_PICTURE_TYPE_B;



    put_bits(&s->pb, 16, 0);                /* vop header */

    put_bits(&s->pb, 16, VOP_STARTCODE);    /* vop header */

    put_bits(&s->pb, 2, s->pict_type - 1);  /* pict type: I = 0 , P = 1 */



    time_div  = FFUDIV(s->time, s->avctx->time_base.den);

    time_mod  = FFUMOD(s->time, s->avctx->time_base.den);

    time_incr = time_div - s->last_time_base;

    av_assert0(time_incr >= 0);

    while (time_incr--)

        put_bits(&s->pb, 1, 1);



    put_bits(&s->pb, 1, 0);



    put_bits(&s->pb, 1, 1);                             /* marker */

    put_bits(&s->pb, s->time_increment_bits, time_mod); /* time increment */

    put_bits(&s->pb, 1, 1);                             /* marker */

    put_bits(&s->pb, 1, 1);                             /* vop coded */

    if (s->pict_type == AV_PICTURE_TYPE_P) {

        put_bits(&s->pb, 1, s->no_rounding);    /* rounding type */

    }

    put_bits(&s->pb, 3, 0);     /* intra dc VLC threshold */

    if (!s->progressive_sequence) {

        put_bits(&s->pb, 1, s->current_picture_ptr->f->top_field_first);

        put_bits(&s->pb, 1, s->alternate_scan);

    }

    // FIXME sprite stuff



    put_bits(&s->pb, 5, s->qscale);



    if (s->pict_type != AV_PICTURE_TYPE_I)

        put_bits(&s->pb, 3, s->f_code);  /* fcode_for */

    if (s->pict_type == AV_PICTURE_TYPE_B)

        put_bits(&s->pb, 3, s->b_code);  /* fcode_back */

}

static int hls_slice_data_wpp(HEVCContext *s, const HEVCNAL *nal)

{

    const uint8_t *data = nal->data;

    int length          = nal->size;

    HEVCLocalContext *lc = s->HEVClc;

    int *ret = av_malloc_array(s->sh.num_entry_point_offsets + 1, sizeof(int));

    int *arg = av_malloc_array(s->sh.num_entry_point_offsets + 1, sizeof(int));

    int64_t offset;

    int startheader, cmpt = 0;

    int i, j, res = 0;



    if (!ret || !arg) {

        av_free(ret);

        av_free(arg);

        return AVERROR(ENOMEM);

    }



    if (s->sh.slice_ctb_addr_rs + s->sh.num_entry_point_offsets * s->ps.sps->ctb_width >= s->ps.sps->ctb_width * s->ps.sps->ctb_height) {

        av_log(s->avctx, AV_LOG_ERROR, "WPP ctb addresses are wrong (%d %d %d %d)\n",

            s->sh.slice_ctb_addr_rs, s->sh.num_entry_point_offsets,

            s->ps.sps->ctb_width, s->ps.sps->ctb_height

        );

        res = AVERROR_INVALIDDATA;

        goto error;

    }



    ff_alloc_entries(s->avctx, s->sh.num_entry_point_offsets + 1);



    if (!s->sList[1]) {

        for (i = 1; i < s->threads_number; i++) {

            s->sList[i] = av_malloc(sizeof(HEVCContext));

            memcpy(s->sList[i], s, sizeof(HEVCContext));

            s->HEVClcList[i] = av_mallocz(sizeof(HEVCLocalContext));

            s->sList[i]->HEVClc = s->HEVClcList[i];

        }

    }



    offset = (lc->gb.index >> 3);



    for (j = 0, cmpt = 0, startheader = offset + s->sh.entry_point_offset[0]; j < nal->skipped_bytes; j++) {

        if (nal->skipped_bytes_pos[j] >= offset && nal->skipped_bytes_pos[j] < startheader) {

            startheader--;

            cmpt++;

        }

    }



    for (i = 1; i < s->sh.num_entry_point_offsets; i++) {

        offset += (s->sh.entry_point_offset[i - 1] - cmpt);

        for (j = 0, cmpt = 0, startheader = offset

             + s->sh.entry_point_offset[i]; j < nal->skipped_bytes; j++) {

            if (nal->skipped_bytes_pos[j] >= offset && nal->skipped_bytes_pos[j] < startheader) {

                startheader--;

                cmpt++;

            }

        }

        s->sh.size[i - 1] = s->sh.entry_point_offset[i] - cmpt;

        s->sh.offset[i - 1] = offset;



    }

    if (s->sh.num_entry_point_offsets != 0) {

        offset += s->sh.entry_point_offset[s->sh.num_entry_point_offsets - 1] - cmpt;

        if (length < offset) {

            av_log(s->avctx, AV_LOG_ERROR, "entry_point_offset table is corrupted\n");

            res = AVERROR_INVALIDDATA;

            goto error;

        }

        s->sh.size[s->sh.num_entry_point_offsets - 1] = length - offset;

        s->sh.offset[s->sh.num_entry_point_offsets - 1] = offset;



    }

    s->data = data;



    for (i = 1; i < s->threads_number; i++) {

        s->sList[i]->HEVClc->first_qp_group = 1;

        s->sList[i]->HEVClc->qp_y = s->sList[0]->HEVClc->qp_y;

        memcpy(s->sList[i], s, sizeof(HEVCContext));

        s->sList[i]->HEVClc = s->HEVClcList[i];

    }



    avpriv_atomic_int_set(&s->wpp_err, 0);

    ff_reset_entries(s->avctx);



    for (i = 0; i <= s->sh.num_entry_point_offsets; i++) {

        arg[i] = i;

        ret[i] = 0;

    }



    if (s->ps.pps->entropy_coding_sync_enabled_flag)

        s->avctx->execute2(s->avctx, hls_decode_entry_wpp, arg, ret, s->sh.num_entry_point_offsets + 1);



    for (i = 0; i <= s->sh.num_entry_point_offsets; i++)

        res += ret[i];

error:

    av_free(ret);

    av_free(arg);

    return res;

}

int av_interleave_packet_per_dts(AVFormatContext *s, AVPacket *out, AVPacket *pkt, int flush){

    AVPacketList *pktl, **next_point, *this_pktl;

    int stream_count=0;

    int streams[MAX_STREAMS];



    if(pkt){

        AVStream *st= s->streams[ pkt->stream_index];



//        assert(pkt->destruct != av_destruct_packet); //FIXME



        this_pktl = av_mallocz(sizeof(AVPacketList));

        this_pktl->pkt= *pkt;

        if(pkt->destruct == av_destruct_packet)

            pkt->destruct= NULL; // not shared -> must keep original from being freed

        else

            av_dup_packet(&this_pktl->pkt);  //shared -> must dup



        next_point = &s->packet_buffer;

        while(*next_point){

            AVStream *st2= s->streams[ (*next_point)->pkt.stream_index];

            int64_t left=  st2->time_base.num * (int64_t)st ->time_base.den;

            int64_t right= st ->time_base.num * (int64_t)st2->time_base.den;

            if((*next_point)->pkt.dts * left > pkt->dts * right) //FIXME this can overflow

                break;

            next_point= &(*next_point)->next;

        }

        this_pktl->next= *next_point;

        *next_point= this_pktl;

    }



    memset(streams, 0, sizeof(streams));

    pktl= s->packet_buffer;

    while(pktl){

//av_log(s, AV_LOG_DEBUG, "show st:%d dts:%"PRId64"\n", pktl->pkt.stream_index, pktl->pkt.dts);

        if(streams[ pktl->pkt.stream_index ] == 0)

            stream_count++;

        streams[ pktl->pkt.stream_index ]++;

        pktl= pktl->next;

    }



    if(s->nb_streams == stream_count || (flush && stream_count)){

        pktl= s->packet_buffer;

        *out= pktl->pkt;



        s->packet_buffer= pktl->next;

        av_freep(&pktl);

        return 1;

    }else{

        av_init_packet(out);

        return 0;

    }

}

static int mov_write_stts_tag(AVIOContext *pb, MOVTrack *track)

{

    MOVStts *stts_entries;

    uint32_t entries = -1;

    uint32_t atom_size;

    int i;



    if (track->enc->codec_type == AVMEDIA_TYPE_AUDIO && !track->audio_vbr) {

        stts_entries = av_malloc(sizeof(*stts_entries)); /* one entry */

        if (!stts_entries)

            return AVERROR(ENOMEM);

        stts_entries[0].count = track->sample_count;

        stts_entries[0].duration = 1;

        entries = 1;

    } else {

        stts_entries = track->entry ?

                       av_malloc_array(track->entry, sizeof(*stts_entries)) : /* worst case */

                       NULL;

        if (!stts_entries)

            return AVERROR(ENOMEM);

        for (i = 0; i < track->entry; i++) {

            int duration = get_cluster_duration(track, i);

            if (i && duration == stts_entries[entries].duration) {

                stts_entries[entries].count++; /* compress */

            } else {

                entries++;

                stts_entries[entries].duration = duration;

                stts_entries[entries].count = 1;

            }

        }

        entries++; /* last one */

    }

    atom_size = 16 + (entries * 8);

    avio_wb32(pb, atom_size); /* size */

    ffio_wfourcc(pb, "stts");

    avio_wb32(pb, 0); /* version & flags */

    avio_wb32(pb, entries); /* entry count */

    for (i = 0; i < entries; i++) {

        avio_wb32(pb, stts_entries[i].count);

        avio_wb32(pb, stts_entries[i].duration);

    }

    av_free(stts_entries);

    return atom_size;

}

static int v410_encode_frame(AVCodecContext *avctx, uint8_t *buf,

                             int buf_size, void *data)

{

    AVFrame *pic = data;

    uint8_t *dst = buf;

    uint16_t *y, *u, *v;

    uint32_t val;

    int i, j;

    int output_size = 0;



    if (buf_size < avctx->width * avctx->height * 3) {

        av_log(avctx, AV_LOG_ERROR, "Out buffer is too small.\n");

        return AVERROR(ENOMEM);

    }



    avctx->coded_frame->reference = 0;

    avctx->coded_frame->key_frame = 1;

    avctx->coded_frame->pict_type = FF_I_TYPE;



    y = (uint16_t *)pic->data[0];

    u = (uint16_t *)pic->data[1];

    v = (uint16_t *)pic->data[2];



    for (i = 0; i < avctx->height; i++) {

        for (j = 0; j < avctx->width; j++) {

            val  = u[j] << 2;

            val |= y[j] << 12;

            val |= v[j] << 22;

            AV_WL32(dst, val);

            dst += 4;

            output_size += 4;

        }

        y += pic->linesize[0] >> 1;

        u += pic->linesize[1] >> 1;

        v += pic->linesize[2] >> 1;

    }



    return output_size;

}

static int compand_nodelay(AVFilterContext *ctx, AVFrame *frame)

{

    CompandContext *s    = ctx->priv;

    AVFilterLink *inlink = ctx->inputs[0];

    const int channels = inlink->channels;

    const int nb_samples = frame->nb_samples;

    AVFrame *out_frame;

    int chan, i;



    if (av_frame_is_writable(frame)) {

        out_frame = frame;

    } else {

        out_frame = ff_get_audio_buffer(inlink, nb_samples);

        if (!out_frame) {

            av_frame_free(&frame);

            return AVERROR(ENOMEM);

        }

        av_frame_copy_props(out_frame, frame);

    }



    for (chan = 0; chan < channels; chan++) {

        const double *src = (double *)frame->extended_data[chan];

        double *dst = (double *)out_frame->extended_data[chan];

        ChanParam *cp = &s->channels[chan];



        for (i = 0; i < nb_samples; i++) {

            update_volume(cp, fabs(src[i]));



            dst[i] = av_clipd(src[i] * get_volume(s, cp->volume), -1, 1);

        }

    }



    if (frame != out_frame)

        av_frame_free(&frame);



    return ff_filter_frame(ctx->outputs[0], out_frame);

}

static int get_sot(Jpeg2000DecoderContext *s, int n)

{

    Jpeg2000TilePart *tp;

    uint16_t Isot;

    uint32_t Psot;

    uint8_t TPsot;



    if (bytestream2_get_bytes_left(&s->g) < 8)

        return AVERROR_INVALIDDATA;



    s->curtileno = 0;

    Isot = bytestream2_get_be16u(&s->g);        // Isot

    if (Isot >= s->numXtiles * s->numYtiles)

        return AVERROR_INVALIDDATA;



    s->curtileno = Isot;

    Psot  = bytestream2_get_be32u(&s->g);       // Psot

    TPsot = bytestream2_get_byteu(&s->g);       // TPsot



    /* Read TNSot but not used */

    bytestream2_get_byteu(&s->g);               // TNsot



    if (!Psot)

        Psot = bytestream2_get_bytes_left(&s->g) + n + 2;



    if (Psot > bytestream2_get_bytes_left(&s->g) + n + 2) {

        av_log(s->avctx, AV_LOG_ERROR, "Psot %"PRIu32" too big\n", Psot);

        return AVERROR_INVALIDDATA;

    }



    if (TPsot >= FF_ARRAY_ELEMS(s->tile[Isot].tile_part)) {

        avpriv_request_sample(s->avctx, "Support for %"PRIu8" components", TPsot);

        return AVERROR_PATCHWELCOME;

    }



    s->tile[Isot].tp_idx = TPsot;

    tp             = s->tile[Isot].tile_part + TPsot;

    tp->tile_index = Isot;

    tp->tp_end     = s->g.buffer + Psot - n - 2;



    if (!TPsot) {

        Jpeg2000Tile *tile = s->tile + s->curtileno;



        /* copy defaults */

        memcpy(tile->codsty, s->codsty, s->ncomponents * sizeof(Jpeg2000CodingStyle));

        memcpy(tile->qntsty, s->qntsty, s->ncomponents * sizeof(Jpeg2000QuantStyle));

    }



    return 0;

}

int MPV_encode_picture(AVCodecContext *avctx,

                       unsigned char *buf, int buf_size, void *data)

{

    MpegEncContext *s = avctx->priv_data;

    AVFrame *pic_arg = data;

    int i, stuffing_count;



    for(i=0; i<avctx->thread_count; i++){

        int start_y= s->thread_context[i]->start_mb_y;

        int   end_y= s->thread_context[i]->  end_mb_y;

        int h= s->mb_height;

        uint8_t *start= buf + (size_t)(((int64_t) buf_size)*start_y/h);

        uint8_t *end  = buf + (size_t)(((int64_t) buf_size)*  end_y/h);



        init_put_bits(&s->thread_context[i]->pb, start, end - start);

    }



    s->picture_in_gop_number++;



    if(load_input_picture(s, pic_arg) < 0)

        return -1;



    select_input_picture(s);



    /* output? */

    if(s->new_picture.data[0]){

        s->pict_type= s->new_picture.pict_type;

//emms_c();

//printf("qs:%f %f %d\n", s->new_picture.quality, s->current_picture.quality, s->qscale);

        MPV_frame_start(s, avctx);

vbv_retry:

        if (encode_picture(s, s->picture_number) < 0)

            return -1;



        avctx->real_pict_num  = s->picture_number;

        avctx->header_bits = s->header_bits;

        avctx->mv_bits     = s->mv_bits;

        avctx->misc_bits   = s->misc_bits;

        avctx->i_tex_bits  = s->i_tex_bits;

        avctx->p_tex_bits  = s->p_tex_bits;

        avctx->i_count     = s->i_count;

        avctx->p_count     = s->mb_num - s->i_count - s->skip_count; //FIXME f/b_count in avctx

        avctx->skip_count  = s->skip_count;



        MPV_frame_end(s);



        if (s->out_format == FMT_MJPEG)

            mjpeg_picture_trailer(s);



        if(avctx->rc_buffer_size){

            RateControlContext *rcc= &s->rc_context;

            int max_size= rcc->buffer_index/3;



            if(put_bits_count(&s->pb) > max_size && s->qscale < s->avctx->qmax){

                s->next_lambda= s->lambda*(s->qscale+1) / s->qscale;

                s->mb_skipped = 0;        //done in MPV_frame_start()

                if(s->pict_type==P_TYPE){ //done in encode_picture() so we must undo it

                    if(s->flipflop_rounding || s->codec_id == CODEC_ID_H263P || s->codec_id == CODEC_ID_MPEG4)

                        s->no_rounding ^= 1;

                }

//                av_log(NULL, AV_LOG_ERROR, "R:%d ", s->next_lambda);

                for(i=0; i<avctx->thread_count; i++){

                    PutBitContext *pb= &s->thread_context[i]->pb;

                    init_put_bits(pb, pb->buf, pb->buf_end - pb->buf);

                }

                goto vbv_retry;

            }



            assert(s->avctx->rc_max_rate);

        }



        if(s->flags&CODEC_FLAG_PASS1)

            ff_write_pass1_stats(s);



        for(i=0; i<4; i++){

            s->current_picture_ptr->error[i]= s->current_picture.error[i];

            avctx->error[i] += s->current_picture_ptr->error[i];

        }



        if(s->flags&CODEC_FLAG_PASS1)

            assert(avctx->header_bits + avctx->mv_bits + avctx->misc_bits + avctx->i_tex_bits + avctx->p_tex_bits == put_bits_count(&s->pb));

        flush_put_bits(&s->pb);

        s->frame_bits  = put_bits_count(&s->pb);



        stuffing_count= ff_vbv_update(s, s->frame_bits);

        if(stuffing_count){

            if(s->pb.buf_end - s->pb.buf - (put_bits_count(&s->pb)>>3) < stuffing_count + 50){

                av_log(s->avctx, AV_LOG_ERROR, "stuffing too large\n");

                return -1;

            }



            switch(s->codec_id){

            case CODEC_ID_MPEG1VIDEO:

            case CODEC_ID_MPEG2VIDEO:

                while(stuffing_count--){

                    put_bits(&s->pb, 8, 0);

                }

            break;

            case CODEC_ID_MPEG4:

                put_bits(&s->pb, 16, 0);

                put_bits(&s->pb, 16, 0x1C3);

                stuffing_count -= 4;

                while(stuffing_count--){

                    put_bits(&s->pb, 8, 0xFF);

                }

            break;

            default:

                av_log(s->avctx, AV_LOG_ERROR, "vbv buffer overflow\n");

            }

            flush_put_bits(&s->pb);

            s->frame_bits  = put_bits_count(&s->pb);

        }



        /* update mpeg1/2 vbv_delay for CBR */

        if(s->avctx->rc_max_rate && s->avctx->rc_min_rate == s->avctx->rc_max_rate && s->out_format == FMT_MPEG1

           && 90000LL * (avctx->rc_buffer_size-1) <= s->avctx->rc_max_rate*0xFFFFLL){

            int vbv_delay;



            assert(s->repeat_first_field==0);



            vbv_delay= lrintf(90000 * s->rc_context.buffer_index / s->avctx->rc_max_rate);

            assert(vbv_delay < 0xFFFF);



            s->vbv_delay_ptr[0] &= 0xF8;

            s->vbv_delay_ptr[0] |= vbv_delay>>13;

            s->vbv_delay_ptr[1]  = vbv_delay>>5;

            s->vbv_delay_ptr[2] &= 0x07;

            s->vbv_delay_ptr[2] |= vbv_delay<<3;

        }

        s->total_bits += s->frame_bits;

        avctx->frame_bits  = s->frame_bits;

    }else{

        assert((pbBufPtr(&s->pb) == s->pb.buf));

        s->frame_bits=0;

    }

    assert((s->frame_bits&7)==0);



    return s->frame_bits/8;

}

static void RENAME(yuv2bgr24_1)(SwsContext *c, const uint16_t *buf0,

                                const uint16_t *ubuf0, const uint16_t *ubuf1,

                                const uint16_t *vbuf0, const uint16_t *vbuf1,

                                const uint16_t *abuf0, uint8_t *dest,

                                int dstW, int uvalpha, enum PixelFormat dstFormat,

                                int flags, int y)

{

    const uint16_t *buf1= buf0; //FIXME needed for RGB1/BGR1



    if (uvalpha < 2048) { // note this is not correct (shifts chrominance by 0.5 pixels) but it is a bit faster

        __asm__ volatile(

            "mov %%"REG_b", "ESP_OFFSET"(%5)        \n\t"

            "mov        %4, %%"REG_b"               \n\t"

            "push %%"REG_BP"                        \n\t"

            YSCALEYUV2RGB1(%%REGBP, %5)

            "pxor    %%mm7, %%mm7                   \n\t"

            WRITEBGR24(%%REGb, 8280(%5), %%REGBP)

            "pop %%"REG_BP"                         \n\t"

            "mov "ESP_OFFSET"(%5), %%"REG_b"        \n\t"

            :: "c" (buf0), "d" (buf1), "S" (ubuf0), "D" (ubuf1), "m" (dest),

               "a" (&c->redDither)

        );

    } else {

        __asm__ volatile(

