    /* DCT & quantize */

    if (s->h263_pred && s->msmpeg4_version!=2) {

        h263_dc_scale(s);

    } else if (s->h263_aic) {

        s->y_dc_scale = 2*s->qscale;

        s->c_dc_scale = 2*s->qscale;

    } else {

        /* default quantization values */

        s->y_dc_scale = 8;

        s->c_dc_scale = 8;

    }

    if(s->out_format==FMT_MJPEG){

        for(i=0;i<6;i++) {

            int overflow;

            s->block_last_index[i] = dct_quantize(s, s->block[i], i, 8, &overflow);

            if (overflow) clip_coeffs(s, s->block[i], s->block_last_index[i]);

        }

    }else{

        for(i=0;i<6;i++) {

            int overflow;

            s->block_last_index[i] = dct_quantize(s, s->block[i], i, s->qscale, &overflow);

            // FIXME we could decide to change to quantizer instead of clipping

            // JS: I don't think that would be a good idea it could lower quality instead

            //     of improve it. Just INTRADC clipping deserves changes in quantizer

            if (overflow) clip_coeffs(s, s->block[i], s->block_last_index[i]);

        }

    }



    /* huffman encode */

    switch(s->out_format) {

    case FMT_MPEG1:

        mpeg1_encode_mb(s, s->block, motion_x, motion_y);

        break;

    case FMT_H263:

        if (s->h263_msmpeg4)

            msmpeg4_encode_mb(s, s->block, motion_x, motion_y);

        else if(s->h263_pred)

            mpeg4_encode_mb(s, s->block, motion_x, motion_y);

        else

            h263_encode_mb(s, s->block, motion_x, motion_y);

        break;

    case FMT_MJPEG:

        mjpeg_encode_mb(s, s->block);

        break;

    }

}

static int decode_subframe_fixed(FLACContext *s, int channel, int pred_order)

{

    const int blocksize = s->blocksize;

    int32_t *decoded = s->decoded[channel];

    int a, b, c, d, i;



    /* warm up samples */

    for (i = 0; i < pred_order; i++) {

        decoded[i] = get_sbits(&s->gb, s->curr_bps);

    }



    if (decode_residuals(s, channel, pred_order) < 0)

        return -1;



    if (pred_order > 0)

        a = decoded[pred_order-1];

    if (pred_order > 1)

        b = a - decoded[pred_order-2];

    if (pred_order > 2)

        c = b - decoded[pred_order-2] + decoded[pred_order-3];

    if (pred_order > 3)

        d = c - decoded[pred_order-2] + 2*decoded[pred_order-3] - decoded[pred_order-4];



    switch (pred_order) {

    case 0:

        break;

    case 1:

        for (i = pred_order; i < blocksize; i++)

            decoded[i] = a += decoded[i];

        break;

    case 2:

        for (i = pred_order; i < blocksize; i++)

            decoded[i] = a += b += decoded[i];

        break;

    case 3:

        for (i = pred_order; i < blocksize; i++)

            decoded[i] = a += b += c += decoded[i];

        break;

    case 4:

        for (i = pred_order; i < blocksize; i++)

            decoded[i] = a += b += c += d += decoded[i];

        break;

    default:

        av_log(s->avctx, AV_LOG_ERROR, "illegal pred order %d\n", pred_order);

        return -1;

    }



    return 0;

}

static int bitplane_decoding(uint8_t* data, int *raw_flag, VC1Context *v)

{

    GetBitContext *gb = &v->s.gb;



    int imode, x, y, code, offset;

    uint8_t invert, *planep = data;

    int width, height, stride;



    width  = v->s.mb_width;

    height = v->s.mb_height >> v->field_mode;

    stride = v->s.mb_stride;

    invert = get_bits1(gb);

    imode = get_vlc2(gb, ff_vc1_imode_vlc.table, VC1_IMODE_VLC_BITS, 1);



    *raw_flag = 0;

    switch (imode) {

    case IMODE_RAW:

        //Data is actually read in the MB layer (same for all tests == "raw")

        *raw_flag = 1; //invert ignored

        return invert;

    case IMODE_DIFF2:

    case IMODE_NORM2:

        if ((height * width) & 1) {

            *planep++ = get_bits1(gb);

            offset    = 1;

        }

        else

            offset = 0;

        // decode bitplane as one long line

        for (y = offset; y < height * width; y += 2) {

            code = get_vlc2(gb, ff_vc1_norm2_vlc.table, VC1_NORM2_VLC_BITS, 1);

            *planep++ = code & 1;

            offset++;

            if (offset == width) {

                offset  = 0;

                planep += stride - width;

            }

            *planep++ = code >> 1;

            offset++;

            if (offset == width) {

                offset  = 0;

                planep += stride - width;

            }

        }

        break;

    case IMODE_DIFF6:

    case IMODE_NORM6:

        if (!(height % 3) && (width % 3)) { // use 2x3 decoding

            for (y = 0; y < height; y += 3) {

                for (x = width & 1; x < width; x += 2) {

                    code = get_vlc2(gb, ff_vc1_norm6_vlc.table, VC1_NORM6_VLC_BITS, 2);

                    if (code < 0) {

                        av_log(v->s.avctx, AV_LOG_DEBUG, "invalid NORM-6 VLC\n");

                        return -1;

                    }

                    planep[x + 0]              = (code >> 0) & 1;

                    planep[x + 1]              = (code >> 1) & 1;

                    planep[x + 0 + stride]     = (code >> 2) & 1;

                    planep[x + 1 + stride]     = (code >> 3) & 1;

                    planep[x + 0 + stride * 2] = (code >> 4) & 1;

                    planep[x + 1 + stride * 2] = (code >> 5) & 1;

                }

                planep += stride * 3;

            }

            if (width & 1)

                decode_colskip(data, 1, height, stride, &v->s.gb);

        } else { // 3x2

            planep += (height & 1) * stride;

            for (y = height & 1; y < height; y += 2) {

                for (x = width % 3; x < width; x += 3) {

                    code = get_vlc2(gb, ff_vc1_norm6_vlc.table, VC1_NORM6_VLC_BITS, 2);

                    if (code < 0) {

                        av_log(v->s.avctx, AV_LOG_DEBUG, "invalid NORM-6 VLC\n");

                        return -1;

                    }

                    planep[x + 0]          = (code >> 0) & 1;

                    planep[x + 1]          = (code >> 1) & 1;

                    planep[x + 2]          = (code >> 2) & 1;

                    planep[x + 0 + stride] = (code >> 3) & 1;

                    planep[x + 1 + stride] = (code >> 4) & 1;

                    planep[x + 2 + stride] = (code >> 5) & 1;

                }

                planep += stride * 2;

            }

            x = width % 3;

            if (x)

                decode_colskip(data,             x, height, stride, &v->s.gb);

            if (height & 1)

                decode_rowskip(data + x, width - x,      1, stride, &v->s.gb);

        }

        break;

    case IMODE_ROWSKIP:

        decode_rowskip(data, width, height, stride, &v->s.gb);

        break;

    case IMODE_COLSKIP:

        decode_colskip(data, width, height, stride, &v->s.gb);

        break;

    default:

        break;

    }



    /* Applying diff operator */

    if (imode == IMODE_DIFF2 || imode == IMODE_DIFF6) {

        planep = data;

        planep[0] ^= invert;

        for (x = 1; x < width; x++)

            planep[x] ^= planep[x-1];

        for (y = 1; y < height; y++) {

            planep += stride;

            planep[0] ^= planep[-stride];

            for (x = 1; x < width; x++) {

                if (planep[x-1] != planep[x-stride]) planep[x] ^= invert;

                else                                 planep[x] ^= planep[x-1];

            }

        }

    } else if (invert) {

        planep = data;

        for (x = 0; x < stride * height; x++)

            planep[x] = !planep[x]; //FIXME stride

    }

    return (imode << 1) + invert;

}

