    av_opt_set_int(s, "osf", out_sample_fmt,  0);

    av_opt_set_int(s, "osr", out_sample_rate, 0);

    av_opt_set_int(s, "icl", in_ch_layout,    0);

    av_opt_set_int(s, "isf", in_sample_fmt,   0);

