static int init_tiles(Jpeg2000EncoderContext *s)

{

    int tileno, tilex, tiley, compno;

    Jpeg2000CodingStyle *codsty = &s->codsty;

    Jpeg2000QuantStyle  *qntsty = &s->qntsty;



    s->numXtiles = ff_jpeg2000_ceildiv(s->width, s->tile_width);

    s->numYtiles = ff_jpeg2000_ceildiv(s->height, s->tile_height);



    s->tile = av_malloc_array(s->numXtiles, s->numYtiles * sizeof(Jpeg2000Tile));

    if (!s->tile)

        return AVERROR(ENOMEM);

    for (tileno = 0, tiley = 0; tiley < s->numYtiles; tiley++)

        for (tilex = 0; tilex < s->numXtiles; tilex++, tileno++){

            Jpeg2000Tile *tile = s->tile + tileno;



            tile->comp = av_mallocz_array(s->ncomponents, sizeof(Jpeg2000Component));

            if (!tile->comp)

                return AVERROR(ENOMEM);

            for (compno = 0; compno < s->ncomponents; compno++){

                Jpeg2000Component *comp = tile->comp + compno;

                int ret, i, j;



                comp->coord[0][0] = comp->coord_o[0][0] = tilex * s->tile_width;

                comp->coord[0][1] = comp->coord_o[0][1] = FFMIN((tilex+1)*s->tile_width, s->width);

                comp->coord[1][0] = comp->coord_o[1][0] = tiley * s->tile_height;

                comp->coord[1][1] = comp->coord_o[1][1] = FFMIN((tiley+1)*s->tile_height, s->height);

                if (compno > 0)

                    for (i = 0; i < 2; i++)

                        for (j = 0; j < 2; j++)

                            comp->coord[i][j] = comp->coord_o[i][j] = ff_jpeg2000_ceildivpow2(comp->coord[i][j], s->chroma_shift[i]);



                if (ret = ff_jpeg2000_init_component(comp,

                                                codsty,

                                                qntsty,

                                                s->cbps[compno],

                                                compno?1<<s->chroma_shift[0]:1,

                                                compno?1<<s->chroma_shift[1]:1,

                                                s->avctx

                                               ))

                    return ret;

            }

        }

    return 0;

}

int avformat_find_stream_info(AVFormatContext *ic, AVDictionary **options)

{

    int i, count, ret = 0, j;

    int64_t read_size;

    AVStream *st;

    AVPacket pkt1, *pkt;

    int64_t old_offset = avio_tell(ic->pb);

    int orig_nb_streams = ic->nb_streams;        // new streams might appear, no options for those

    int flush_codecs = ic->probesize > 0;



    if(ic->pb)

        av_log(ic, AV_LOG_DEBUG, "File position before avformat_find_stream_info() is %"PRId64"\n", avio_tell(ic->pb));



    for(i=0;i<ic->nb_streams;i++) {

        const AVCodec *codec;

        AVDictionary *thread_opt = NULL;

        st = ic->streams[i];



        if (st->codec->codec_type == AVMEDIA_TYPE_VIDEO ||

            st->codec->codec_type == AVMEDIA_TYPE_SUBTITLE) {

/*            if(!st->time_base.num)

                st->time_base= */

            if(!st->codec->time_base.num)

                st->codec->time_base= st->time_base;

        }

        //only for the split stuff

        if (!st->parser && !(ic->flags & AVFMT_FLAG_NOPARSE)) {

            st->parser = av_parser_init(st->codec->codec_id);

            if(st->parser){

                if(st->need_parsing == AVSTREAM_PARSE_HEADERS){

                    st->parser->flags |= PARSER_FLAG_COMPLETE_FRAMES;

                } else if(st->need_parsing == AVSTREAM_PARSE_FULL_RAW) {

                    st->parser->flags |= PARSER_FLAG_USE_CODEC_TS;

                }

            } else if (st->need_parsing) {

                av_log(ic, AV_LOG_VERBOSE, "parser not found for codec "

                       "%s, packets or times may be invalid.\n",

                       avcodec_get_name(st->codec->codec_id));

            }

        }

        codec = st->codec->codec ? st->codec->codec :

                                   avcodec_find_decoder(st->codec->codec_id);



        /* force thread count to 1 since the h264 decoder will not extract SPS

         *  and PPS to extradata during multi-threaded decoding */

        av_dict_set(options ? &options[i] : &thread_opt, "threads", "1", 0);



        /* Ensure that subtitle_header is properly set. */

        if (st->codec->codec_type == AVMEDIA_TYPE_SUBTITLE

            && codec && !st->codec->codec)

            avcodec_open2(st->codec, codec, options ? &options[i]

                              : &thread_opt);



        //try to just open decoders, in case this is enough to get parameters

        if (!has_codec_parameters(st, NULL) && st->request_probe <= 0) {

            if (codec && !st->codec->codec)

                avcodec_open2(st->codec, codec, options ? &options[i]

                              : &thread_opt);

        }

        if (!options)

            av_dict_free(&thread_opt);

    }



    for (i=0; i<ic->nb_streams; i++) {

#if FF_API_R_FRAME_RATE

        ic->streams[i]->info->last_dts = AV_NOPTS_VALUE;

#endif

        ic->streams[i]->info->fps_first_dts = AV_NOPTS_VALUE;

        ic->streams[i]->info->fps_last_dts  = AV_NOPTS_VALUE;

    }



    count = 0;

    read_size = 0;

    for(;;) {

        if (ff_check_interrupt(&ic->interrupt_callback)){

            ret= AVERROR_EXIT;

            av_log(ic, AV_LOG_DEBUG, "interrupted\n");

            break;

        }



        /* check if one codec still needs to be handled */

        for(i=0;i<ic->nb_streams;i++) {

            int fps_analyze_framecount = 20;



            st = ic->streams[i];

            if (!has_codec_parameters(st, NULL))

                break;

            /* if the timebase is coarse (like the usual millisecond precision

               of mkv), we need to analyze more frames to reliably arrive at

               the correct fps */

            if (av_q2d(st->time_base) > 0.0005)

                fps_analyze_framecount *= 2;

            if (ic->fps_probe_size >= 0)

                fps_analyze_framecount = ic->fps_probe_size;

            if (st->disposition & AV_DISPOSITION_ATTACHED_PIC)

                fps_analyze_framecount = 0;

            /* variable fps and no guess at the real fps */

            if(   tb_unreliable(st->codec) && !(st->r_frame_rate.num && st->avg_frame_rate.num)

               && st->info->duration_count < fps_analyze_framecount

               && st->codec->codec_type == AVMEDIA_TYPE_VIDEO)

                break;

            if(st->parser && st->parser->parser->split && !st->codec->extradata)

                break;

            if (st->first_dts == AV_NOPTS_VALUE &&

                (st->codec->codec_type == AVMEDIA_TYPE_VIDEO ||

                 st->codec->codec_type == AVMEDIA_TYPE_AUDIO))

                break;

        }

        if (i == ic->nb_streams) {

            /* NOTE: if the format has no header, then we need to read

               some packets to get most of the streams, so we cannot

               stop here */

            if (!(ic->ctx_flags & AVFMTCTX_NOHEADER)) {

                /* if we found the info for all the codecs, we can stop */

                ret = count;

                av_log(ic, AV_LOG_DEBUG, "All info found\n");

                flush_codecs = 0;

                break;

            }

        }

        /* we did not get all the codec info, but we read too much data */

        if (read_size >= ic->probesize) {

            ret = count;

            av_log(ic, AV_LOG_DEBUG, "Probe buffer size limit of %d bytes reached\n", ic->probesize);

            for (i = 0; i < ic->nb_streams; i++)

                if (!ic->streams[i]->r_frame_rate.num &&

                    ic->streams[i]->info->duration_count <= 1)

                    av_log(ic, AV_LOG_WARNING,

                           "Stream #%d: not enough frames to estimate rate; "

                           "consider increasing probesize\n", i);

            break;

        }



        /* NOTE: a new stream can be added there if no header in file

           (AVFMTCTX_NOHEADER) */

        ret = read_frame_internal(ic, &pkt1);

        if (ret == AVERROR(EAGAIN))

            continue;



        if (ret < 0) {

            /* EOF or error*/

            break;

        }



        if (ic->flags & AVFMT_FLAG_NOBUFFER) {

            pkt = &pkt1;

        } else {

            pkt = add_to_pktbuf(&ic->packet_buffer, &pkt1,

                                &ic->packet_buffer_end);

            if ((ret = av_dup_packet(pkt)) < 0)

                goto find_stream_info_err;

        }



        read_size += pkt->size;



        st = ic->streams[pkt->stream_index];

        if (pkt->dts != AV_NOPTS_VALUE && st->codec_info_nb_frames > 1) {

            /* check for non-increasing dts */

            if (st->info->fps_last_dts != AV_NOPTS_VALUE &&

                st->info->fps_last_dts >= pkt->dts) {

                av_log(ic, AV_LOG_DEBUG, "Non-increasing DTS in stream %d: "

                       "packet %d with DTS %"PRId64", packet %d with DTS "

                       "%"PRId64"\n", st->index, st->info->fps_last_dts_idx,

                       st->info->fps_last_dts, st->codec_info_nb_frames, pkt->dts);

                st->info->fps_first_dts = st->info->fps_last_dts = AV_NOPTS_VALUE;

            }

            /* check for a discontinuity in dts - if the difference in dts

             * is more than 1000 times the average packet duration in the sequence,

             * we treat it as a discontinuity */

            if (st->info->fps_last_dts != AV_NOPTS_VALUE &&

                st->info->fps_last_dts_idx > st->info->fps_first_dts_idx &&

                (pkt->dts - st->info->fps_last_dts) / 1000 >

                (st->info->fps_last_dts - st->info->fps_first_dts) / (st->info->fps_last_dts_idx - st->info->fps_first_dts_idx)) {

                av_log(ic, AV_LOG_WARNING, "DTS discontinuity in stream %d: "

                       "packet %d with DTS %"PRId64", packet %d with DTS "

                       "%"PRId64"\n", st->index, st->info->fps_last_dts_idx,

                       st->info->fps_last_dts, st->codec_info_nb_frames, pkt->dts);

                st->info->fps_first_dts = st->info->fps_last_dts = AV_NOPTS_VALUE;

            }



            /* update stored dts values */

            if (st->info->fps_first_dts == AV_NOPTS_VALUE) {

                st->info->fps_first_dts     = pkt->dts;

                st->info->fps_first_dts_idx = st->codec_info_nb_frames;

            }

            st->info->fps_last_dts = pkt->dts;

            st->info->fps_last_dts_idx = st->codec_info_nb_frames;

        }

        if (st->codec_info_nb_frames>1) {

            int64_t t=0;

            if (st->time_base.den > 0)

                t = av_rescale_q(st->info->codec_info_duration, st->time_base, AV_TIME_BASE_Q);

            if (st->avg_frame_rate.num > 0)

                t = FFMAX(t, av_rescale_q(st->codec_info_nb_frames, av_inv_q(st->avg_frame_rate), AV_TIME_BASE_Q));



            if (   t==0

                && st->codec_info_nb_frames>15

                && st->codec->codec_type == AVMEDIA_TYPE_VIDEO

                && (   !strcmp(ic->iformat->name, "mpeg") // this breaks some flvs thus use only for mpegps/ts for now (for ts we have a sample that needs it)

                    || !strcmp(ic->iformat->name, "mpegts"))

                && st->info->fps_first_dts != AV_NOPTS_VALUE

                && st->info->fps_last_dts  != AV_NOPTS_VALUE)

                t = FFMAX(t, av_rescale_q(st->info->fps_last_dts - st->info->fps_first_dts, st->time_base, AV_TIME_BASE_Q));



            if (t >= ic->max_analyze_duration) {

                av_log(ic, AV_LOG_VERBOSE, "max_analyze_duration %d reached at %"PRId64" microseconds\n", ic->max_analyze_duration, t);

                break;

            }

            if (pkt->duration) {

                st->info->codec_info_duration        += pkt->duration;

                st->info->codec_info_duration_fields += st->parser && st->codec->ticks_per_frame==2 ? st->parser->repeat_pict + 1 : 2;

            }

        }

#if FF_API_R_FRAME_RATE

        {

            int64_t last = st->info->last_dts;



            if(   pkt->dts != AV_NOPTS_VALUE && last != AV_NOPTS_VALUE && pkt->dts > last

               && pkt->dts - (uint64_t)last < INT64_MAX){

                double dts= (is_relative(pkt->dts) ?  pkt->dts - RELATIVE_TS_BASE : pkt->dts) * av_q2d(st->time_base);

                int64_t duration= pkt->dts - last;



                if (!st->info->duration_error)

                    st->info->duration_error = av_mallocz(sizeof(st->info->duration_error[0])*2);



//                 if(st->codec->codec_type == AVMEDIA_TYPE_VIDEO)

//                     av_log(NULL, AV_LOG_ERROR, "%f\n", dts);

                for (i=0; i<MAX_STD_TIMEBASES; i++) {

                    int framerate= get_std_framerate(i);

                    double sdts= dts*framerate/(1001*12);

                    for(j=0; j<2; j++){

                        int64_t ticks= llrint(sdts+j*0.5);

                        double error= sdts - ticks + j*0.5;

                        st->info->duration_error[j][0][i] += error;

                        st->info->duration_error[j][1][i] += error*error;

                    }

                }

                st->info->duration_count++;

                // ignore the first 4 values, they might have some random jitter

                if (st->info->duration_count > 3 && is_relative(pkt->dts) == is_relative(last))

                    st->info->duration_gcd = av_gcd(st->info->duration_gcd, duration);

            }

            if (pkt->dts != AV_NOPTS_VALUE)

                st->info->last_dts = pkt->dts;

        }

#endif

        if(st->parser && st->parser->parser->split && !st->codec->extradata){

            int i= st->parser->parser->split(st->codec, pkt->data, pkt->size);

            if (i > 0 && i < FF_MAX_EXTRADATA_SIZE) {

                st->codec->extradata_size= i;

                st->codec->extradata= av_malloc(st->codec->extradata_size + FF_INPUT_BUFFER_PADDING_SIZE);

                if (!st->codec->extradata)

                    return AVERROR(ENOMEM);

                memcpy(st->codec->extradata, pkt->data, st->codec->extradata_size);

                memset(st->codec->extradata + i, 0, FF_INPUT_BUFFER_PADDING_SIZE);

            }

        }



        /* if still no information, we try to open the codec and to

           decompress the frame. We try to avoid that in most cases as

           it takes longer and uses more memory. For MPEG-4, we need to

           decompress for QuickTime.



           If CODEC_CAP_CHANNEL_CONF is set this will force decoding of at

           least one frame of codec data, this makes sure the codec initializes

           the channel configuration and does not only trust the values from the container.

        */

        try_decode_frame(st, pkt, (options && i < orig_nb_streams ) ? &options[i] : NULL);



        st->codec_info_nb_frames++;

        count++;

    }



    if (flush_codecs) {

        AVPacket empty_pkt = { 0 };

        int err = 0;

        av_init_packet(&empty_pkt);



        for(i=0;i<ic->nb_streams;i++) {



            st = ic->streams[i];



            /* flush the decoders */

            if (st->info->found_decoder == 1) {

                do {

                    err = try_decode_frame(st, &empty_pkt,

                                            (options && i < orig_nb_streams) ?

                                            &options[i] : NULL);

                } while (err > 0 && !has_codec_parameters(st, NULL));



                if (err < 0) {

                    av_log(ic, AV_LOG_INFO,

                        "decoding for stream %d failed\n", st->index);

                }

            }

        }

    }



    // close codecs which were opened in try_decode_frame()

    for(i=0;i<ic->nb_streams;i++) {

        st = ic->streams[i];

        avcodec_close(st->codec);

    }

    for(i=0;i<ic->nb_streams;i++) {

        st = ic->streams[i];

        if (st->codec->codec_type == AVMEDIA_TYPE_VIDEO) {

            if(st->codec->codec_id == AV_CODEC_ID_RAWVIDEO && !st->codec->codec_tag && !st->codec->bits_per_coded_sample){

                uint32_t tag= avcodec_pix_fmt_to_codec_tag(st->codec->pix_fmt);

                if (avpriv_find_pix_fmt(ff_raw_pix_fmt_tags, tag) == st->codec->pix_fmt)

                    st->codec->codec_tag= tag;

            }



            /* estimate average framerate if not set by demuxer */

            if (st->info->codec_info_duration_fields && !st->avg_frame_rate.num && st->info->codec_info_duration) {

                int      best_fps = 0;

                double best_error = 0.01;



                av_reduce(&st->avg_frame_rate.num, &st->avg_frame_rate.den,

                          st->info->codec_info_duration_fields*(int64_t)st->time_base.den,

                          st->info->codec_info_duration*2*(int64_t)st->time_base.num, 60000);



                /* round guessed framerate to a "standard" framerate if it's

                 * within 1% of the original estimate*/

                for (j = 1; j < MAX_STD_TIMEBASES; j++) {

                    AVRational std_fps = { get_std_framerate(j), 12*1001 };

                    double error = fabs(av_q2d(st->avg_frame_rate) / av_q2d(std_fps) - 1);



                    if (error < best_error) {

                        best_error = error;

                        best_fps   = std_fps.num;

                    }

                }

                if (best_fps) {

                    av_reduce(&st->avg_frame_rate.num, &st->avg_frame_rate.den,

                              best_fps, 12*1001, INT_MAX);

                }

            }

            // the check for tb_unreliable() is not completely correct, since this is not about handling

            // a unreliable/inexact time base, but a time base that is finer than necessary, as e.g.

            // ipmovie.c produces.

            if (tb_unreliable(st->codec) && st->info->duration_count > 15 && st->info->duration_gcd > FFMAX(1, st->time_base.den/(500LL*st->time_base.num)) && !st->r_frame_rate.num)

                av_reduce(&st->r_frame_rate.num, &st->r_frame_rate.den, st->time_base.den, st->time_base.num * st->info->duration_gcd, INT_MAX);

            if (st->info->duration_count>1 && !st->r_frame_rate.num

                && tb_unreliable(st->codec)) {

                int num = 0;

                double best_error= 0.01;



                for (j=0; j<MAX_STD_TIMEBASES; j++) {

                    int k;



                    if(st->info->codec_info_duration && st->info->codec_info_duration*av_q2d(st->time_base) < (1001*12.0)/get_std_framerate(j))

                        continue;

                    if(!st->info->codec_info_duration && 1.0 < (1001*12.0)/get_std_framerate(j))

                        continue;

                    for(k=0; k<2; k++){

                        int n= st->info->duration_count;

                        double a= st->info->duration_error[k][0][j] / n;

                        double error= st->info->duration_error[k][1][j]/n - a*a;



                        if(error < best_error && best_error> 0.000000001){

                            best_error= error;

                            num = get_std_framerate(j);

                        }

                        if(error < 0.02)

                            av_log(NULL, AV_LOG_DEBUG, "rfps: %f %f\n", get_std_framerate(j) / 12.0/1001, error);

                    }

                }

                // do not increase frame rate by more than 1 % in order to match a standard rate.

                if (num && (!st->r_frame_rate.num || (double)num/(12*1001) < 1.01 * av_q2d(st->r_frame_rate)))

                    av_reduce(&st->r_frame_rate.num, &st->r_frame_rate.den, num, 12*1001, INT_MAX);

            }



            if (!st->r_frame_rate.num){

                if(    st->codec->time_base.den * (int64_t)st->time_base.num

                    <= st->codec->time_base.num * st->codec->ticks_per_frame * (int64_t)st->time_base.den){

                    st->r_frame_rate.num = st->codec->time_base.den;

                    st->r_frame_rate.den = st->codec->time_base.num * st->codec->ticks_per_frame;

                }else{

                    st->r_frame_rate.num = st->time_base.den;

                    st->r_frame_rate.den = st->time_base.num;

                }

            }

        }else if(st->codec->codec_type == AVMEDIA_TYPE_AUDIO) {

            if(!st->codec->bits_per_coded_sample)

                st->codec->bits_per_coded_sample= av_get_bits_per_sample(st->codec->codec_id);

            // set stream disposition based on audio service type

            switch (st->codec->audio_service_type) {

            case AV_AUDIO_SERVICE_TYPE_EFFECTS:

                st->disposition = AV_DISPOSITION_CLEAN_EFFECTS;    break;

            case AV_AUDIO_SERVICE_TYPE_VISUALLY_IMPAIRED:

                st->disposition = AV_DISPOSITION_VISUAL_IMPAIRED;  break;

            case AV_AUDIO_SERVICE_TYPE_HEARING_IMPAIRED:

                st->disposition = AV_DISPOSITION_HEARING_IMPAIRED; break;

            case AV_AUDIO_SERVICE_TYPE_COMMENTARY:

                st->disposition = AV_DISPOSITION_COMMENT;          break;

            case AV_AUDIO_SERVICE_TYPE_KARAOKE:

                st->disposition = AV_DISPOSITION_KARAOKE;          break;

            }

        }

    }



    if(ic->probesize)

    estimate_timings(ic, old_offset);



    if (ret >= 0 && ic->nb_streams)

        ret = -1; /* we could not have all the codec parameters before EOF */

    for(i=0;i<ic->nb_streams;i++) {

        const char *errmsg;

        st = ic->streams[i];

        if (!has_codec_parameters(st, &errmsg)) {

            char buf[256];

            avcodec_string(buf, sizeof(buf), st->codec, 0);

            av_log(ic, AV_LOG_WARNING,

                   "Could not find codec parameters for stream %d (%s): %s\n"

                   "Consider increasing the value for the 'analyzeduration' and 'probesize' options\n",

                   i, buf, errmsg);

        } else {

            ret = 0;

        }

    }



    compute_chapters_end(ic);



 find_stream_info_err:

    for (i=0; i < ic->nb_streams; i++) {

        st = ic->streams[i];

        if (ic->streams[i]->codec && ic->streams[i]->codec->codec_type != AVMEDIA_TYPE_AUDIO)

            ic->streams[i]->codec->thread_count = 0;

        if (st->info)

            av_freep(&st->info->duration_error);

        av_freep(&ic->streams[i]->info);

    }

    if(ic->pb)

        av_log(ic, AV_LOG_DEBUG, "File position after avformat_find_stream_info() is %"PRId64"\n", avio_tell(ic->pb));

    return ret;

}

static int advanced_decode_picture_secondary_header(VC9Context *v)

{

    GetBitContext *gb = &v->s.gb;

    int index, status = 0;



    switch(v->s.pict_type)

    {

    case P_TYPE: status = decode_p_picture_secondary_header(v); break;

    case B_TYPE: status = decode_b_picture_secondary_header(v); break;

    case BI_TYPE:

    case I_TYPE: status = decode_i_picture_secondary_header(v); break; 

    }

    if (status<0) return FRAME_SKIPED;



    /* AC Syntax */

    v->ac_table_level = decode012(gb);

    if (v->s.pict_type == I_TYPE || v->s.pict_type == BI_TYPE)

    {

        v->ac2_table_level = decode012(gb);

    }

    /* DC Syntax */

    index = decode012(gb);

    v->luma_dc_vlc = &ff_msmp4_dc_luma_vlc[index];

    v->chroma_dc_vlc = &ff_msmp4_dc_chroma_vlc[index];



    return 0;

}

static inline void range_dec_normalize(APEContext *ctx)

{

    while (ctx->rc.range <= BOTTOM_VALUE) {

        ctx->rc.buffer <<= 8;

        if(ctx->ptr < ctx->data_end)

            ctx->rc.buffer += *ctx->ptr;

        ctx->ptr++;

        ctx->rc.low    = (ctx->rc.low << 8)    | ((ctx->rc.buffer >> 1) & 0xFF);

        ctx->rc.range  <<= 8;

    }

}

static int theora_header(AVFormatContext *s, int idx)
{
    struct ogg *ogg       = s->priv_data;
    struct ogg_stream *os = ogg->streams + idx;
    AVStream *st          = s->streams[idx];
    TheoraParams *thp     = os->private;
    int cds               = st->codec->extradata_size + os->psize + 2;
    int err;
    uint8_t *cdp;
    if (!(os->buf[os->pstart] & 0x80))
        return 0;
    if (!thp) {
        thp = av_mallocz(sizeof(*thp));
        if (!thp)
            return AVERROR(ENOMEM);
        os->private = thp;
    }
    switch (os->buf[os->pstart]) {
    case 0x80: {
        GetBitContext gb;
        AVRational timebase;
        init_get_bits(&gb, os->buf + os->pstart, os->psize * 8);
        /* 0x80"theora" */
        skip_bits_long(&gb, 7 * 8);
        thp->version = get_bits_long(&gb, 24);
        if (thp->version < 0x030100) {
            av_log(s, AV_LOG_ERROR,
                   "Too old or unsupported Theora (%x)\n", thp->version);
            return AVERROR(ENOSYS);
        }
        st->codec->width  = get_bits(&gb, 16) << 4;
        st->codec->height = get_bits(&gb, 16) << 4;
        if (thp->version >= 0x030400)
            skip_bits(&gb, 100);
        if (thp->version >= 0x030200) {
            int width  = get_bits_long(&gb, 24);
            int height = get_bits_long(&gb, 24);
            if (width  <= st->codec->width  && width  > st->codec->width  - 16 &&
                height <= st->codec->height && height > st->codec->height - 16) {
                st->codec->width  = width;
                st->codec->height = height;
            }
            skip_bits(&gb, 16);
        }
        timebase.den = get_bits_long(&gb, 32);
        timebase.num = get_bits_long(&gb, 32);
        if (!(timebase.num > 0 && timebase.den > 0)) {
            av_log(s, AV_LOG_WARNING, "Invalid time base in theora stream, assuming 25 FPS\n");
            timebase.num = 1;
            timebase.den = 25;
        }
        avpriv_set_pts_info(st, 64, timebase.num, timebase.den);
        st->sample_aspect_ratio.num = get_bits_long(&gb, 24);
        st->sample_aspect_ratio.den = get_bits_long(&gb, 24);
        if (thp->version >= 0x030200)
            skip_bits_long(&gb, 38);
        if (thp->version >= 0x304000)
            skip_bits(&gb, 2);
        thp->gpshift = get_bits(&gb, 5);
        thp->gpmask  = (1 << thp->gpshift) - 1;
        st->codec->codec_type = AVMEDIA_TYPE_VIDEO;
        st->codec->codec_id   = AV_CODEC_ID_THEORA;
        st->need_parsing      = AVSTREAM_PARSE_HEADERS;
    }
    break;
    case 0x81:
        ff_vorbis_comment(s, &st->metadata, os->buf + os->pstart + 7, os->psize - 7);
    case 0x82:
        if (!thp->version)
            return AVERROR_INVALIDDATA;
        break;
    default:
        av_log(s, AV_LOG_ERROR, "Unknown header type %X\n", os->buf[os->pstart]);
        return AVERROR_INVALIDDATA;
    }
    if ((err = av_reallocp(&st->codec->extradata,
                           cds + FF_INPUT_BUFFER_PADDING_SIZE)) < 0) {
        st->codec->extradata_size = 0;
        return err;
    }
    cdp    = st->codec->extradata + st->codec->extradata_size;
    *cdp++ = os->psize >> 8;
    *cdp++ = os->psize & 0xff;
    memcpy(cdp, os->buf + os->pstart, os->psize);
    st->codec->extradata_size = cds;
    return 1;
}

static int buffer_needs_copy(PadContext *s, AVFrame *frame, AVBufferRef *buf)

{

    int planes[4] = { -1, -1, -1, -1}, *p = planes;

    int i, j;



    /* get all planes in this buffer */

    for (i = 0; i < FF_ARRAY_ELEMS(planes) && frame->data[i]; i++) {

        if (av_frame_get_plane_buffer(frame, i) == buf)

            *p++ = i;

    }



    /* for each plane in this buffer, check that it can be padded without

     * going over buffer bounds or other planes */

    for (i = 0; i < FF_ARRAY_ELEMS(planes) && planes[i] >= 0; i++) {

        int hsub = (planes[i] == 1 || planes[i] == 2) ? s->hsub : 0;

        int vsub = (planes[i] == 1 || planes[i] == 2) ? s->vsub : 0;



        uint8_t *start = frame->data[planes[i]];

        uint8_t *end   = start + (frame->height >> hsub) *

                                 frame->linesize[planes[i]];



        /* amount of free space needed before the start and after the end

         * of the plane */

        ptrdiff_t req_start = (s->x >> hsub) * s->line_step[planes[i]] +

                              (s->y >> vsub) * frame->linesize[planes[i]];

        ptrdiff_t req_end   = ((s->w - s->x - frame->width) >> hsub) *

                              s->line_step[planes[i]] +

                              (s->y >> vsub) * frame->linesize[planes[i]];



        if (frame->linesize[planes[i]] < (s->w >> hsub) * s->line_step[planes[i]])

            return 1;

        if (start - buf->data < req_start ||

            (buf->data + buf->size) - end < req_end)

            return 1;



#define SIGN(x) ((x) > 0 ? 1 : -1)

        for (j = 0; j < FF_ARRAY_ELEMS(planes) & planes[j] >= 0; j++) {

            int hsub1 = (planes[j] == 1 || planes[j] == 2) ? s->hsub : 0;

            uint8_t *start1 = frame->data[planes[j]];

            uint8_t *end1   = start1 + (frame->height >> hsub1) *

                                       frame->linesize[planes[j]];

            if (i == j)

                continue;



            if (SIGN(start - end1) != SIGN(start - end1 - req_start) ||

                SIGN(end - start1) != SIGN(end - start1 + req_end))

                return 1;

        }

    }



    return 0;

}

static void initMMX2HScaler(int dstW, int xInc, uint8_t *funnyCode)

{

	uint8_t *fragment;

	int imm8OfPShufW1;

	int imm8OfPShufW2;

	int fragmentLength;



	int xpos, i;



	// create an optimized horizontal scaling routine



	//code fragment



	asm volatile(

		"jmp 9f				\n\t"

	// Begin

		"0:				\n\t"

		"movq (%%esi), %%mm0		\n\t" //FIXME Alignment

		"movq %%mm0, %%mm1		\n\t"

		"psrlq $8, %%mm0		\n\t"

		"punpcklbw %%mm7, %%mm1	\n\t"

		"movq %%mm2, %%mm3		\n\t"

		"punpcklbw %%mm7, %%mm0	\n\t"

		"addw %%bx, %%cx		\n\t" //2*xalpha += (4*lumXInc)&0xFFFF

		"pshufw $0xFF, %%mm1, %%mm1	\n\t"

		"1:				\n\t"

		"adcl %%edx, %%esi		\n\t" //xx+= (4*lumXInc)>>16 + carry

		"pshufw $0xFF, %%mm0, %%mm0	\n\t"

		"2:				\n\t"

		"psrlw $9, %%mm3		\n\t"

		"psubw %%mm1, %%mm0		\n\t"

		"pmullw %%mm3, %%mm0		\n\t"

		"paddw %%mm6, %%mm2		\n\t" // 2*alpha += xpos&0xFFFF

		"psllw $7, %%mm1		\n\t"

		"paddw %%mm1, %%mm0		\n\t"



		"movq %%mm0, (%%edi, %%eax)	\n\t"



		"addl $8, %%eax			\n\t"

	// End

		"9:				\n\t"

//		"int $3\n\t"

		"leal 0b, %0			\n\t"

		"leal 1b, %1			\n\t"

		"leal 2b, %2			\n\t"

		"decl %1			\n\t"

		"decl %2			\n\t"

		"subl %0, %1			\n\t"

		"subl %0, %2			\n\t"

		"leal 9b, %3			\n\t"

		"subl %0, %3			\n\t"

		:"=r" (fragment), "=r" (imm8OfPShufW1), "=r" (imm8OfPShufW2),

		"=r" (fragmentLength)

	);



	xpos= 0; //lumXInc/2 - 0x8000; // difference between pixel centers



	for(i=0; i<dstW/8; i++)

	{

		int xx=xpos>>16;



		if((i&3) == 0)

		{

			int a=0;

			int b=((xpos+xInc)>>16) - xx;

			int c=((xpos+xInc*2)>>16) - xx;

			int d=((xpos+xInc*3)>>16) - xx;



			memcpy(funnyCode + fragmentLength*i/4, fragment, fragmentLength);



			funnyCode[fragmentLength*i/4 + imm8OfPShufW1]=

			funnyCode[fragmentLength*i/4 + imm8OfPShufW2]=

				a | (b<<2) | (c<<4) | (d<<6);



			// if we dont need to read 8 bytes than dont :), reduces the chance of

			// crossing a cache line

			if(d<3) funnyCode[fragmentLength*i/4 + 1]= 0x6E;



			funnyCode[fragmentLength*(i+4)/4]= RET;

		}

		xpos+=xInc;

	}

}

static int encode_picture_ls(AVCodecContext *avctx, AVPacket *pkt,

                             const AVFrame *pict, int *got_packet)

{

    const AVFrame *const p = pict;

    const int near         = avctx->prediction_method;

    PutBitContext pb, pb2;

    GetBitContext gb;

    uint8_t *buf2, *zero, *cur, *last;

    JLSState *state;

    int i, size, ret;

    int comps;



    if (avctx->pix_fmt == AV_PIX_FMT_GRAY8 ||

        avctx->pix_fmt == AV_PIX_FMT_GRAY16)

        comps = 1;

    else

        comps = 3;



    if ((ret = ff_alloc_packet(pkt, avctx->width * avctx->height * comps * 4 +

                               FF_MIN_BUFFER_SIZE)) < 0) {

        av_log(avctx, AV_LOG_ERROR, "Error getting output packet.\n");

        return ret;

    }



    buf2 = av_malloc(pkt->size);



    init_put_bits(&pb, pkt->data, pkt->size);

    init_put_bits(&pb2, buf2, pkt->size);



    /* write our own JPEG header, can't use mjpeg_picture_header */

    put_marker(&pb, SOI);

    put_marker(&pb, SOF48);

    put_bits(&pb, 16, 8 + comps * 3); // header size depends on components

    put_bits(&pb, 8, (avctx->pix_fmt == AV_PIX_FMT_GRAY16) ? 16 : 8);  // bpp

    put_bits(&pb, 16, avctx->height);

    put_bits(&pb, 16, avctx->width);

    put_bits(&pb, 8, comps);          // components

    for (i = 1; i <= comps; i++) {

        put_bits(&pb, 8, i);     // component ID

        put_bits(&pb, 8, 0x11);  // subsampling: none

        put_bits(&pb, 8, 0);     // Tiq, used by JPEG-LS ext

    }



    put_marker(&pb, SOS);

    put_bits(&pb, 16, 6 + comps * 2);

    put_bits(&pb, 8, comps);

    for (i = 1; i <= comps; i++) {

        put_bits(&pb, 8, i);   // component ID

        put_bits(&pb, 8, 0);   // mapping index: none

    }

    put_bits(&pb, 8, near);

    put_bits(&pb, 8, (comps > 1) ? 1 : 0);  // interleaving: 0 - plane, 1 - line

    put_bits(&pb, 8, 0);  // point transform: none



    state = av_mallocz(sizeof(JLSState));

    /* initialize JPEG-LS state from JPEG parameters */

    state->near = near;

    state->bpp  = (avctx->pix_fmt == AV_PIX_FMT_GRAY16) ? 16 : 8;

    ff_jpegls_reset_coding_parameters(state, 0);

    ff_jpegls_init_state(state);



    ls_store_lse(state, &pb);



    zero = av_mallocz(p->linesize[0]);

    last = zero;

    cur  = p->data[0];

    if (avctx->pix_fmt == AV_PIX_FMT_GRAY8) {

        int t = 0;



        for (i = 0; i < avctx->height; i++) {

            ls_encode_line(state, &pb2, last, cur, t, avctx->width, 1, 0, 8);

            t    = last[0];

            last = cur;

            cur += p->linesize[0];

        }

    } else if (avctx->pix_fmt == AV_PIX_FMT_GRAY16) {

        int t = 0;



        for (i = 0; i < avctx->height; i++) {

            ls_encode_line(state, &pb2, last, cur, t, avctx->width, 1, 0, 16);

            t    = *((uint16_t *)last);

            last = cur;

            cur += p->linesize[0];

        }

    } else if (avctx->pix_fmt == AV_PIX_FMT_RGB24) {

        int j, width;

        int Rc[3] = { 0, 0, 0 };



        width = avctx->width * 3;

        for (i = 0; i < avctx->height; i++) {

            for (j = 0; j < 3; j++) {

                ls_encode_line(state, &pb2, last + j, cur + j, Rc[j],

                               width, 3, j, 8);

                Rc[j] = last[j];

            }

            last = cur;

            cur += p->linesize[0];

        }

    } else if (avctx->pix_fmt == AV_PIX_FMT_BGR24) {

        int j, width;

        int Rc[3] = { 0, 0, 0 };



        width = avctx->width * 3;

        for (i = 0; i < avctx->height; i++) {

            for (j = 2; j >= 0; j--) {

                ls_encode_line(state, &pb2, last + j, cur + j, Rc[j],

                               width, 3, j, 8);

                Rc[j] = last[j];

            }

            last = cur;

            cur += p->linesize[0];

        }

    }



    av_free(zero);

    av_free(state);



    /* the specification says that after doing 0xff escaping unused bits in

     * the last byte must be set to 0, so just append 7 "optional" zero-bits

     * to avoid special-casing. */

    put_bits(&pb2, 7, 0);

    size = put_bits_count(&pb2);

    flush_put_bits(&pb2);

    /* do escape coding */

    init_get_bits(&gb, buf2, size);

    size -= 7;

    while (get_bits_count(&gb) < size) {

        int v;

        v = get_bits(&gb, 8);

        put_bits(&pb, 8, v);

        if (v == 0xFF) {

            v = get_bits(&gb, 7);

            put_bits(&pb, 8, v);

        }

    }

    avpriv_align_put_bits(&pb);

    av_free(buf2);



    /* End of image */

    put_marker(&pb, EOI);

    flush_put_bits(&pb);



    emms_c();



    pkt->size   = put_bits_count(&pb) >> 3;

    pkt->flags |= AV_PKT_FLAG_KEY;

    *got_packet = 1;

    return 0;

}

static int bmp_decode_frame(AVCodecContext *avctx,

                            void *data, int *data_size,

                            AVPacket *avpkt)

{

    const uint8_t *buf = avpkt->data;

    int buf_size = avpkt->size;

    BMPContext *s = avctx->priv_data;

    AVFrame *picture = data;

    AVFrame *p = &s->picture;

    unsigned int fsize, hsize;

    int width, height;

    unsigned int depth;

    BiCompression comp;

    unsigned int ihsize;

    int i, j, n, linesize;

    uint32_t rgb[3];

    uint32_t alpha = 0;

    uint8_t *ptr;

    int dsize;

    const uint8_t *buf0 = buf;

    GetByteContext gb;



    if(buf_size < 14){

        av_log(avctx, AV_LOG_ERROR, "buf size too small (%d)\n", buf_size);

        return -1;

    }



    if(bytestream_get_byte(&buf) != 'B' ||

       bytestream_get_byte(&buf) != 'M') {

        av_log(avctx, AV_LOG_ERROR, "bad magic number\n");

        return -1;

    }



    fsize = bytestream_get_le32(&buf);

    if(buf_size < fsize){

        av_log(avctx, AV_LOG_ERROR, "not enough data (%d < %d), trying to decode anyway\n",

               buf_size, fsize);

        fsize = buf_size;

    }



    buf += 2; /* reserved1 */

    buf += 2; /* reserved2 */



    hsize = bytestream_get_le32(&buf); /* header size */

    ihsize = bytestream_get_le32(&buf);       /* more header size */

    if(ihsize + 14 > hsize){

        av_log(avctx, AV_LOG_ERROR, "invalid header size %d\n", hsize);

        return -1;

    }



    /* sometimes file size is set to some headers size, set a real size in that case */

    if(fsize == 14 || fsize == ihsize + 14)

        fsize = buf_size - 2;



    if(fsize <= hsize){

        av_log(avctx, AV_LOG_ERROR, "declared file size is less than header size (%d < %d)\n",

               fsize, hsize);

        return -1;

    }



    switch(ihsize){

    case  40: // windib

    case  56: // windib v3

    case  64: // OS/2 v2

    case 108: // windib v4

    case 124: // windib v5

        width = bytestream_get_le32(&buf);

        height = bytestream_get_le32(&buf);

        break;

    case  12: // OS/2 v1

        width  = bytestream_get_le16(&buf);

        height = bytestream_get_le16(&buf);

        break;

    default:

        av_log(avctx, AV_LOG_ERROR, "unsupported BMP file, patch welcome\n");

        return -1;

    }



    if(bytestream_get_le16(&buf) != 1){ /* planes */

        av_log(avctx, AV_LOG_ERROR, "invalid BMP header\n");

        return -1;

    }



    depth = bytestream_get_le16(&buf);



    if (ihsize >= 40)

        comp = bytestream_get_le32(&buf);

    else

        comp = BMP_RGB;



    if(comp != BMP_RGB && comp != BMP_BITFIELDS && comp != BMP_RLE4 && comp != BMP_RLE8){

        av_log(avctx, AV_LOG_ERROR, "BMP coding %d not supported\n", comp);

        return -1;

    }



    if(comp == BMP_BITFIELDS){

        buf += 20;

        rgb[0] = bytestream_get_le32(&buf);

        rgb[1] = bytestream_get_le32(&buf);

        rgb[2] = bytestream_get_le32(&buf);

        alpha = bytestream_get_le32(&buf);

    }



    avctx->width = width;

    avctx->height = height > 0? height: -height;



    avctx->pix_fmt = AV_PIX_FMT_NONE;



    switch(depth){

    case 32:

        if(comp == BMP_BITFIELDS){

            if (rgb[0] == 0xFF000000 && rgb[1] == 0x00FF0000 && rgb[2] == 0x0000FF00)

                avctx->pix_fmt = alpha ? AV_PIX_FMT_ABGR : AV_PIX_FMT_0BGR;

            else if (rgb[0] == 0x00FF0000 && rgb[1] == 0x0000FF00 && rgb[2] == 0x000000FF)

                avctx->pix_fmt = alpha ? AV_PIX_FMT_BGRA : AV_PIX_FMT_BGR0;

            else if (rgb[0] == 0x0000FF00 && rgb[1] == 0x00FF0000 && rgb[2] == 0xFF000000)

                avctx->pix_fmt = alpha ? AV_PIX_FMT_ARGB : AV_PIX_FMT_0RGB;

            else if (rgb[0] == 0x000000FF && rgb[1] == 0x0000FF00 && rgb[2] == 0x00FF0000)

                avctx->pix_fmt = alpha ? AV_PIX_FMT_RGBA : AV_PIX_FMT_RGB0;

            else {

                av_log(avctx, AV_LOG_ERROR, "Unknown bitfields %0X %0X %0X\n", rgb[0], rgb[1], rgb[2]);

                return AVERROR(EINVAL);

            }

        } else {

            avctx->pix_fmt = AV_PIX_FMT_BGRA;

        }

        break;

    case 24:

        avctx->pix_fmt = AV_PIX_FMT_BGR24;

        break;

    case 16:

        if(comp == BMP_RGB)

            avctx->pix_fmt = AV_PIX_FMT_RGB555;

        else if (comp == BMP_BITFIELDS) {

            if (rgb[0] == 0xF800 && rgb[1] == 0x07E0 && rgb[2] == 0x001F)

               avctx->pix_fmt = AV_PIX_FMT_RGB565;

            else if (rgb[0] == 0x7C00 && rgb[1] == 0x03E0 && rgb[2] == 0x001F)

               avctx->pix_fmt = AV_PIX_FMT_RGB555;

            else if (rgb[0] == 0x0F00 && rgb[1] == 0x00F0 && rgb[2] == 0x000F)

               avctx->pix_fmt = AV_PIX_FMT_RGB444;

            else {

               av_log(avctx, AV_LOG_ERROR, "Unknown bitfields %0X %0X %0X\n", rgb[0], rgb[1], rgb[2]);

               return AVERROR(EINVAL);

            }

        }

        break;

    case 8:

        if(hsize - ihsize - 14 > 0)

            avctx->pix_fmt = AV_PIX_FMT_PAL8;

        else

            avctx->pix_fmt = AV_PIX_FMT_GRAY8;

        break;

    case 1:

    case 4:

        if(hsize - ihsize - 14 > 0){

            avctx->pix_fmt = AV_PIX_FMT_PAL8;

        }else{

            av_log(avctx, AV_LOG_ERROR, "Unknown palette for %d-colour BMP\n", 1<<depth);

            return -1;

        }

        break;

    default:

        av_log(avctx, AV_LOG_ERROR, "depth %d not supported\n", depth);

        return -1;

    }



    if(avctx->pix_fmt == AV_PIX_FMT_NONE){

        av_log(avctx, AV_LOG_ERROR, "unsupported pixel format\n");

        return -1;

    }



    if(p->data[0])

        avctx->release_buffer(avctx, p);



    p->reference = 0;

    if(avctx->get_buffer(avctx, p) < 0){

        av_log(avctx, AV_LOG_ERROR, "get_buffer() failed\n");

        return -1;

    }

    p->pict_type = AV_PICTURE_TYPE_I;

    p->key_frame = 1;



    buf = buf0 + hsize;

    dsize = buf_size - hsize;



    /* Line size in file multiple of 4 */

    n = ((avctx->width * depth + 31) / 8) & ~3;



    if(n * avctx->height > dsize && comp != BMP_RLE4 && comp != BMP_RLE8){

        av_log(avctx, AV_LOG_ERROR, "not enough data (%d < %d)\n",

               dsize, n * avctx->height);

        return -1;

    }



    // RLE may skip decoding some picture areas, so blank picture before decoding

    if(comp == BMP_RLE4 || comp == BMP_RLE8)

        memset(p->data[0], 0, avctx->height * p->linesize[0]);



    if(height > 0){

        ptr = p->data[0] + (avctx->height - 1) * p->linesize[0];

        linesize = -p->linesize[0];

    } else {

        ptr = p->data[0];

        linesize = p->linesize[0];

    }



    if(avctx->pix_fmt == AV_PIX_FMT_PAL8){

        int colors = 1 << depth;



        memset(p->data[1], 0, 1024);



        if(ihsize >= 36){

            int t;

            buf = buf0 + 46;

            t = bytestream_get_le32(&buf);

            if(t < 0 || t > (1 << depth)){

                av_log(avctx, AV_LOG_ERROR, "Incorrect number of colors - %X for bitdepth %d\n", t, depth);

            }else if(t){

                colors = t;

            }

        }

        buf = buf0 + 14 + ihsize; //palette location

        if((hsize-ihsize-14) < (colors << 2)){ // OS/2 bitmap, 3 bytes per palette entry

            for(i = 0; i < colors; i++)

                ((uint32_t*)p->data[1])[i] = (0xff<<24) | bytestream_get_le24(&buf);

        }else{

            for(i = 0; i < colors; i++)

                ((uint32_t*)p->data[1])[i] = 0xFFU << 24 | bytestream_get_le32(&buf);

        }

        buf = buf0 + hsize;

    }

    if(comp == BMP_RLE4 || comp == BMP_RLE8){

        if(height < 0){

            p->data[0] += p->linesize[0] * (avctx->height - 1);

            p->linesize[0] = -p->linesize[0];

        }

        bytestream2_init(&gb, buf, dsize);

        ff_msrle_decode(avctx, (AVPicture*)p, depth, &gb);

        if(height < 0){

            p->data[0] += p->linesize[0] * (avctx->height - 1);

            p->linesize[0] = -p->linesize[0];

        }

    }else{

        switch(depth){

        case 1:

            for (i = 0; i < avctx->height; i++) {

                int j;

                for (j = 0; j < n; j++) {

                    ptr[j*8+0] =  buf[j] >> 7;

                    ptr[j*8+1] = (buf[j] >> 6) & 1;

                    ptr[j*8+2] = (buf[j] >> 5) & 1;

                    ptr[j*8+3] = (buf[j] >> 4) & 1;

                    ptr[j*8+4] = (buf[j] >> 3) & 1;

                    ptr[j*8+5] = (buf[j] >> 2) & 1;

                    ptr[j*8+6] = (buf[j] >> 1) & 1;

                    ptr[j*8+7] =  buf[j]       & 1;

                }

                buf += n;

                ptr += linesize;

            }

            break;

        case 8:

        case 24:

        case 32:

            for(i = 0; i < avctx->height; i++){

                memcpy(ptr, buf, n);

                buf += n;

                ptr += linesize;

            }

            break;

        case 4:

            for(i = 0; i < avctx->height; i++){

                int j;

                for(j = 0; j < n; j++){

                    ptr[j*2+0] = (buf[j] >> 4) & 0xF;

                    ptr[j*2+1] = buf[j] & 0xF;

                }

                buf += n;

                ptr += linesize;

            }

            break;

        case 16:

            for(i = 0; i < avctx->height; i++){

                const uint16_t *src = (const uint16_t *) buf;

                uint16_t *dst = (uint16_t *) ptr;



                for(j = 0; j < avctx->width; j++)

                    *dst++ = av_le2ne16(*src++);



                buf += n;

                ptr += linesize;

            }

            break;

        default:

            av_log(avctx, AV_LOG_ERROR, "BMP decoder is broken\n");

            return -1;

        }

    }



    *picture = s->picture;

    *data_size = sizeof(AVPicture);



    return buf_size;

}

static int v4l2_set_parameters(AVFormatContext *s1)

{

    struct video_data *s = s1->priv_data;

    struct v4l2_standard standard = { 0 };

    struct v4l2_streamparm streamparm = { 0 };

    struct v4l2_fract *tpf = &streamparm.parm.capture.timeperframe;

    AVRational framerate_q = { 0 };

    int i, ret;



    streamparm.type = V4L2_BUF_TYPE_VIDEO_CAPTURE;



    if (s->framerate &&

        (ret = av_parse_video_rate(&framerate_q, s->framerate)) < 0) {

        av_log(s1, AV_LOG_ERROR, "Could not parse framerate '%s'.\n",

               s->framerate);

        return ret;

    }



    if (s->standard) {

        av_log(s1, AV_LOG_DEBUG, "The V4L2 driver set standard: %s\n",

               s->standard);

        /* set tv standard */

        for(i=0;;i++) {

            standard.index = i;

            ret = v4l2_ioctl(s->fd, VIDIOC_ENUMSTD, &standard);

            if (ret < 0 || !av_strcasecmp(standard.name, s->standard))

                break;

        }

        if (ret < 0) {

            av_log(s1, AV_LOG_ERROR, "Unknown standard '%s'\n", s->standard);

            return ret;

        }



        av_log(s1, AV_LOG_DEBUG,

               "The V4L2 driver set standard: %s, id: %"PRIu64"\n",

               s->standard, (uint64_t)standard.id);

        if (v4l2_ioctl(s->fd, VIDIOC_S_STD, &standard.id) < 0) {

            av_log(s1, AV_LOG_ERROR,

                   "The V4L2 driver ioctl set standard(%s) failed\n",

                   s->standard);

            return AVERROR(EIO);

        }

    }



    if (framerate_q.num && framerate_q.den) {

        av_log(s1, AV_LOG_DEBUG, "Setting time per frame to %d/%d\n",

               framerate_q.den, framerate_q.num);

        tpf->numerator   = framerate_q.den;

        tpf->denominator = framerate_q.num;



        if (v4l2_ioctl(s->fd, VIDIOC_S_PARM, &streamparm) != 0) {

            av_log(s1, AV_LOG_ERROR,

                   "ioctl set time per frame(%d/%d) failed\n",

                   framerate_q.den, framerate_q.num);

            return AVERROR(EIO);

        }



        if (framerate_q.num != tpf->denominator ||

            framerate_q.den != tpf->numerator) {

            av_log(s1, AV_LOG_INFO,

                   "The driver changed the time per frame from "

                   "%d/%d to %d/%d\n",

                   framerate_q.den, framerate_q.num,

                   tpf->numerator, tpf->denominator);

        }

    } else {

        if (v4l2_ioctl(s->fd, VIDIOC_G_PARM, &streamparm) != 0) {

            av_log(s1, AV_LOG_ERROR, "ioctl(VIDIOC_G_PARM): %s\n",

                   strerror(errno));

            return AVERROR(errno);

        }

    }

    s1->streams[0]->avg_frame_rate.num = tpf->denominator;

    s1->streams[0]->avg_frame_rate.den = tpf->numerator;



    return 0;

}

void ff_mpc_dequantize_and_synth(MPCContext * c, int maxband, void *data, int channels)

{

    int i, j, ch;

    Band *bands = c->bands;

    int off;

    float mul;



    /* dequantize */

    memset(c->sb_samples, 0, sizeof(c->sb_samples));

    off = 0;

    for(i = 0; i <= maxband; i++, off += SAMPLES_PER_BAND){

        for(ch = 0; ch < 2; ch++){

            if(bands[i].res[ch]){

                j = 0;

                mul = mpc_CC[bands[i].res[ch]] * mpc_SCF[bands[i].scf_idx[ch][0] & 0xFF];

                for(; j < 12; j++)

                    c->sb_samples[ch][j][i] = mul * c->Q[ch][j + off];

                mul = mpc_CC[bands[i].res[ch]] * mpc_SCF[bands[i].scf_idx[ch][1] & 0xFF];

                for(; j < 24; j++)

                    c->sb_samples[ch][j][i] = mul * c->Q[ch][j + off];

                mul = mpc_CC[bands[i].res[ch]] * mpc_SCF[bands[i].scf_idx[ch][2] & 0xFF];

                for(; j < 36; j++)

                    c->sb_samples[ch][j][i] = mul * c->Q[ch][j + off];

            }

        }

        if(bands[i].msf){

            int t1, t2;

            for(j = 0; j < SAMPLES_PER_BAND; j++){

                t1 = c->sb_samples[0][j][i];

                t2 = c->sb_samples[1][j][i];

                c->sb_samples[0][j][i] = t1 + t2;

                c->sb_samples[1][j][i] = t1 - t2;

            }

        }

    }



    mpc_synth(c, data, channels);

}

static int decode_slice_luma(AVCodecContext *avctx, SliceContext *slice,

                             uint16_t *dst, int dst_stride,

                             const uint8_t *buf, unsigned buf_size,

                             const int16_t *qmat)

{

    ProresContext *ctx = avctx->priv_data;

    LOCAL_ALIGNED_16(int16_t, blocks, [8*4*64]);

    int16_t *block;

    GetBitContext gb;

    int i, blocks_per_slice = slice->mb_count<<2;

    int ret;



    for (i = 0; i < blocks_per_slice; i++)

        ctx->bdsp.clear_block(blocks+(i<<6));



    init_get_bits(&gb, buf, buf_size << 3);



    decode_dc_coeffs(&gb, blocks, blocks_per_slice);

    if ((ret = decode_ac_coeffs(avctx, &gb, blocks, blocks_per_slice)) < 0)

        return ret;



    block = blocks;

    for (i = 0; i < slice->mb_count; i++) {

        ctx->prodsp.idct_put(dst, dst_stride, block+(0<<6), qmat);

        ctx->prodsp.idct_put(dst             +8, dst_stride, block+(1<<6), qmat);

        ctx->prodsp.idct_put(dst+4*dst_stride  , dst_stride, block+(2<<6), qmat);

        ctx->prodsp.idct_put(dst+4*dst_stride+8, dst_stride, block+(3<<6), qmat);

        block += 4*64;

        dst += 16;

    }

    return 0;

}

static int read_uncompressed_sgi(const SGIInfo *si, 

        AVPicture *pict, ByteIOContext *f)

{

    int x, y, z, chan_offset, ret = 0;

    uint8_t *dest_row, *tmp_row = NULL;



    tmp_row = av_malloc(si->xsize);



    /* skip header */ 

    url_fseek(f, SGI_HEADER_SIZE, SEEK_SET);



    pict->linesize[0] = si->xsize;



    for (z = 0; z < si->zsize; z++) {



#ifndef WORDS_BIGENDIAN

        /* rgba -> bgra for rgba32 on little endian cpus */

        if (si->zsize == 4 && z != 3) 

            chan_offset = 2 - z;

        else

#endif

            chan_offset = z;



        for (y = si->ysize - 1; y >= 0; y--) {

            dest_row = pict->data[0] + (y * si->xsize * si->zsize);



            if (!get_buffer(f, tmp_row, si->xsize)) {

                ret = -1;

                goto cleanup;

            }

            for (x = 0; x < si->xsize; x++) {

                dest_row[chan_offset] = tmp_row[x]; 

                dest_row += si->zsize;

            }

        }

    }



cleanup:

    av_free(tmp_row);

    return ret;

}

int av_dict_set(AVDictionary **pm, const char *key, const char *value,

                int flags)

{

    AVDictionary *m = *pm;

    AVDictionaryEntry *tag = av_dict_get(m, key, NULL, flags);

    char *oldval = NULL, *copy_key = NULL, *copy_value = NULL;



    if (flags & AV_DICT_DONT_STRDUP_KEY)

        copy_key = (void *)key;

    else

        copy_key = av_strdup(key);

    if (flags & AV_DICT_DONT_STRDUP_VAL)

        copy_value = (void *)value;

    else if (copy_key)

        copy_value = av_strdup(value);

    if (!m)

        m = *pm = av_mallocz(sizeof(*m));

    if (!m || (key && !copy_key) || (value && !copy_value))

        goto err_out;



    if (tag) {

        if (flags & AV_DICT_DONT_OVERWRITE) {

            av_free(copy_key);

            av_free(copy_value);

            return 0;

        }

        if (flags & AV_DICT_APPEND)

            oldval = tag->value;

        else

            av_free(tag->value);

        av_free(tag->key);

        *tag = m->elems[--m->count];

    } else {

        AVDictionaryEntry *tmp = av_realloc(m->elems,

                                            (m->count + 1) * sizeof(*m->elems));

        if (!tmp)

            goto err_out;

        m->elems = tmp;

    }

    if (copy_value) {

        m->elems[m->count].key = copy_key;

        m->elems[m->count].value = copy_value;

        if (oldval && flags & AV_DICT_APPEND) {

            size_t len = strlen(oldval) + strlen(copy_value) + 1;

            char *newval = av_mallocz(len);

            if (!newval)

                goto err_out;

            av_strlcat(newval, oldval, len);

            av_freep(&oldval);

            av_strlcat(newval, copy_value, len);

            m->elems[m->count].value = newval;

            av_freep(&copy_value);

        }

        m->count++;

    } else {

        av_freep(&copy_key);

    }

    if (!m->count) {

        av_freep(&m->elems);

        av_freep(pm);

    }



    return 0;



err_out:

    if (m && !m->count) {

        av_freep(&m->elems);

        av_freep(pm);

    }

    av_free(copy_key);

    av_free(copy_value);

    return AVERROR(ENOMEM);

}

static av_cold int dfa_decode_init(AVCodecContext *avctx)
{
    DfaContext *s = avctx->priv_data;
    avctx->pix_fmt = PIX_FMT_PAL8;
    s->frame_buf = av_mallocz(avctx->width * avctx->height + AV_LZO_OUTPUT_PADDING);
    if (!s->frame_buf)
        return AVERROR(ENOMEM);
    return 0;
}

static void free_stream(AVStream **pst)

{

    AVStream *st = *pst;

    int i;



    if (!st)

        return;



    for (i = 0; i < st->nb_side_data; i++)

        av_freep(&st->side_data[i].data);

    av_freep(&st->side_data);



    if (st->parser)

        av_parser_close(st->parser);



    if (st->attached_pic.data)

        av_packet_unref(&st->attached_pic);



    if (st->internal) {

        avcodec_free_context(&st->internal->avctx);

        for (i = 0; i < st->internal->nb_bsfcs; i++) {

            av_bsf_free(&st->internal->bsfcs[i]);

            av_freep(&st->internal->bsfcs);

        }

        av_bsf_free(&st->internal->extract_extradata.bsf);

        av_packet_free(&st->internal->extract_extradata.pkt);

    }

    av_freep(&st->internal);



    av_dict_free(&st->metadata);

    avcodec_parameters_free(&st->codecpar);

    av_freep(&st->probe_data.buf);

    av_freep(&st->index_entries);

#if FF_API_LAVF_AVCTX

FF_DISABLE_DEPRECATION_WARNINGS

    av_freep(&st->codec->extradata);

    av_freep(&st->codec->subtitle_header);

    av_freep(&st->codec);

FF_ENABLE_DEPRECATION_WARNINGS

#endif

    av_freep(&st->priv_data);

    if (st->info)

        av_freep(&st->info->duration_error);

    av_freep(&st->info);

    av_freep(&st->recommended_encoder_configuration);

    av_freep(&st->priv_pts);



    av_freep(pst);

}

static void FUNCC(pred16x16_horizontal)(uint8_t *_src, int stride){

    int i;

    pixel *src = (pixel*)_src;

    stride /= sizeof(pixel);



    for(i=0; i<16; i++){

        ((pixel4*)(src+i*stride))[0] =

        ((pixel4*)(src+i*stride))[1] =

        ((pixel4*)(src+i*stride))[2] =

        ((pixel4*)(src+i*stride))[3] = PIXEL_SPLAT_X4(src[-1+i*stride]);

    }

}

static int filter_frame(AVFilterLink *inlink, AVFrame *insamples)

{

    AVFilterContext *ctx = inlink->dst;

    AVFilterLink *outlink = ctx->outputs[0];

    ShowCQTContext *s = ctx->priv;

    int remaining, step, ret, x, i, j, m;

    float *audio_data;

    AVFrame *out = NULL;



    if (!insamples) {

        while (s->remaining_fill < s->fft_len / 2) {

            memset(&s->fft_data[s->fft_len - s->remaining_fill], 0, sizeof(*s->fft_data) * s->remaining_fill);

            ret = plot_cqt(ctx, &out);

            if (ret < 0)

                return ret;



            step = s->step + (s->step_frac.num + s->remaining_frac) / s->step_frac.den;

            s->remaining_frac = (s->step_frac.num + s->remaining_frac) % s->step_frac.den;

            for (x = 0; x < (s->fft_len-step); x++)

                s->fft_data[x] = s->fft_data[x+step];

            s->remaining_fill += step;



            if (out)

                return ff_filter_frame(outlink, out);

        }

        return AVERROR_EOF;

    }



    remaining = insamples->nb_samples;

    audio_data = (float*) insamples->data[0];



    while (remaining) {

        i = insamples->nb_samples - remaining;

        j = s->fft_len - s->remaining_fill;

        if (remaining >= s->remaining_fill) {

            for (m = 0; m < s->remaining_fill; m++) {

                s->fft_data[j+m].re = audio_data[2*(i+m)];

                s->fft_data[j+m].im = audio_data[2*(i+m)+1];

            }

            ret = plot_cqt(ctx, &out);

            if (ret < 0) {

                av_frame_free(&insamples);

                return ret;

            }

            remaining -= s->remaining_fill;

            if (out) {

                int64_t pts = av_rescale_q(insamples->pts, inlink->time_base, av_make_q(1, inlink->sample_rate));

                pts += insamples->nb_samples - remaining - s->fft_len/2;

                pts = av_rescale_q(pts, av_make_q(1, inlink->sample_rate), outlink->time_base);

                if (FFABS(pts - out->pts) > PTS_TOLERANCE) {

                    av_log(ctx, AV_LOG_DEBUG, "changing pts from %"PRId64" (%.3f) to %"PRId64" (%.3f).\n",

                           out->pts, out->pts * av_q2d(outlink->time_base),

                           pts, pts * av_q2d(outlink->time_base));

                    out->pts = pts;

                    s->next_pts = pts + PTS_STEP;

                }

                ret = ff_filter_frame(outlink, out);

                if (ret < 0) {

                    av_frame_free(&insamples);

                    return ret;

                }

                out = NULL;

            }

            step = s->step + (s->step_frac.num + s->remaining_frac) / s->step_frac.den;

            s->remaining_frac = (s->step_frac.num + s->remaining_frac) % s->step_frac.den;

            for (m = 0; m < s->fft_len-step; m++)

                s->fft_data[m] = s->fft_data[m+step];

            s->remaining_fill = step;

        } else {

            for (m = 0; m < remaining; m++) {

                s->fft_data[j+m].re = audio_data[2*(i+m)];

                s->fft_data[j+m].im = audio_data[2*(i+m)+1];

            }

            s->remaining_fill -= remaining;

            remaining = 0;

        }

    }

    av_frame_free(&insamples);

    return 0;

}

static int get_dimension(GetBitContext *gb, const int *dim)

{

    int t   = get_bits(gb, 3);

    int val = dim[t];

    if(val < 0)

        val = dim[get_bits1(gb) - val];

    if(!val){

        do{



            t = get_bits(gb, 8);

            val += t << 2;

        }while(t == 0xFF);

    }

    return val;

}

