static int matroska_parse_block(MatroskaDemuxContext *matroska, uint8_t *data,
                                int size, int64_t pos, uint64_t cluster_time,
                                uint64_t duration, int is_keyframe,
                                int64_t cluster_pos)
{
    uint64_t timecode = AV_NOPTS_VALUE;
    MatroskaTrack *track;
    int res = 0;
    AVStream *st;
    AVPacket *pkt;
    int16_t block_time;
    uint32_t *lace_size = NULL;
    int n, flags, laces = 0;
    uint64_t num;
    if ((n = matroska_ebmlnum_uint(matroska, data, size, &num)) < 0) {
        av_log(matroska->ctx, AV_LOG_ERROR, "EBML block data error\n");
        return res;
    data += n;
    size -= n;
    track = matroska_find_track_by_num(matroska, num);
    if (size <= 3 || !track || !track->stream) {
        av_log(matroska->ctx, AV_LOG_INFO,
               "Invalid stream %"PRIu64" or size %u\n", num, size);
        return res;
    st = track->stream;
    if (st->discard >= AVDISCARD_ALL)
        return res;
    if (duration == AV_NOPTS_VALUE)
        duration = track->default_duration / matroska->time_scale;
    block_time = AV_RB16(data);
    data += 2;
    flags = *data++;
    size -= 3;
    if (is_keyframe == -1)
        is_keyframe = flags & 0x80 ? PKT_FLAG_KEY : 0;
    if (cluster_time != (uint64_t)-1
        && (block_time >= 0 || cluster_time >= -block_time)) {
        timecode = cluster_time + block_time;
        if (track->type == MATROSKA_TRACK_TYPE_SUBTITLE
            && timecode < track->end_timecode)
            is_keyframe = 0;  /* overlapping subtitles are not key frame */
        if (is_keyframe)
            av_add_index_entry(st, cluster_pos, timecode, 0,0,AVINDEX_KEYFRAME);
        track->end_timecode = FFMAX(track->end_timecode, timecode+duration);
    if (matroska->skip_to_keyframe && track->type != MATROSKA_TRACK_TYPE_SUBTITLE) {
        if (!is_keyframe || timecode < matroska->skip_to_timecode)
            return res;
        matroska->skip_to_keyframe = 0;
    switch ((flags & 0x06) >> 1) {
        case 0x0: /* no lacing */
            laces = 1;
            lace_size = av_mallocz(sizeof(int));
            lace_size[0] = size;
        case 0x1: /* Xiph lacing */
        case 0x2: /* fixed-size lacing */
        case 0x3: /* EBML lacing */
            assert(size>0); // size <=3 is checked before size-=3 above
            laces = (*data) + 1;
            data += 1;
            size -= 1;
            lace_size = av_mallocz(laces * sizeof(int));
            switch ((flags & 0x06) >> 1) {
                case 0x1: /* Xiph lacing */ {
                    uint8_t temp;
                    uint32_t total = 0;
                    for (n = 0; res == 0 && n < laces - 1; n++) {
                        while (1) {
                            if (size == 0) {
                                res = -1;
                            temp = *data;
                            lace_size[n] += temp;
                            data += 1;
                            size -= 1;
                            if (temp != 0xff)
                        total += lace_size[n];
                    lace_size[n] = size - total;
                case 0x2: /* fixed-size lacing */
                    for (n = 0; n < laces; n++)
                        lace_size[n] = size / laces;
                case 0x3: /* EBML lacing */ {
                    uint32_t total;
                    n = matroska_ebmlnum_uint(matroska, data, size, &num);
                    if (n < 0) {
                        av_log(matroska->ctx, AV_LOG_INFO,
                               "EBML block data error\n");
                    data += n;
                    size -= n;
                    total = lace_size[0] = num;
                    for (n = 1; res == 0 && n < laces - 1; n++) {
                        int64_t snum;
                        int r;
                        r = matroska_ebmlnum_sint(matroska, data, size, &snum);
                        if (r < 0) {
                            av_log(matroska->ctx, AV_LOG_INFO,
                                   "EBML block data error\n");
                        data += r;
                        size -= r;
                        lace_size[n] = lace_size[n - 1] + snum;
                        total += lace_size[n];
                    lace_size[n] = size - total;
    if (res == 0) {
        for (n = 0; n < laces; n++) {
            if ((st->codec->codec_id == CODEC_ID_RA_288 ||
                 st->codec->codec_id == CODEC_ID_COOK ||
                 st->codec->codec_id == CODEC_ID_ATRAC3) &&
                 st->codec->block_align && track->audio.sub_packet_size) {
                int a = st->codec->block_align;
                int sps = track->audio.sub_packet_size;
                int cfs = track->audio.coded_framesize;
                int h = track->audio.sub_packet_h;
                int y = track->audio.sub_packet_cnt;
                int w = track->audio.frame_size;
                int x;
                if (!track->audio.pkt_cnt) {
                    if (st->codec->codec_id == CODEC_ID_RA_288)
                        for (x=0; x<h/2; x++)
                            memcpy(track->audio.buf+x*2*w+y*cfs,
                                   data+x*cfs, cfs);
                    else
                        for (x=0; x<w/sps; x++)
                            memcpy(track->audio.buf+sps*(h*x+((h+1)/2)*(y&1)+(y>>1)), data+x*sps, sps);
                    if (++track->audio.sub_packet_cnt >= h) {
                        track->audio.sub_packet_cnt = 0;
                        track->audio.pkt_cnt = h*w / a;
                while (track->audio.pkt_cnt) {
                    pkt = av_mallocz(sizeof(AVPacket));
                    av_new_packet(pkt, a);
                    memcpy(pkt->data, track->audio.buf
                           + a * (h*w / a - track->audio.pkt_cnt--), a);
                    pkt->pos = pos;
                    pkt->stream_index = st->index;
                    dynarray_add(&matroska->packets,&matroska->num_packets,pkt);
            } else {
                MatroskaTrackEncoding *encodings = track->encodings.elem;
                int offset = 0, pkt_size = lace_size[n];
                uint8_t *pkt_data = data;
                if (encodings && encodings->scope & 1) {
                    offset = matroska_decode_buffer(&pkt_data,&pkt_size, track);
                    if (offset < 0)
                        continue;
                pkt = av_mallocz(sizeof(AVPacket));
                /* XXX: prevent data copy... */
                if (av_new_packet(pkt, pkt_size+offset) < 0) {
                    av_free(pkt);
                    res = AVERROR(ENOMEM);
                if (offset)
                    memcpy (pkt->data, encodings->compression.settings.data, offset);
                memcpy (pkt->data+offset, pkt_data, pkt_size);
                if (pkt_data != data)
                    av_free(pkt_data);
                if (n == 0)
                    pkt->flags = is_keyframe;
                pkt->stream_index = st->index;
                if (track->ms_compat)
                    pkt->dts = timecode;
                else
                    pkt->pts = timecode;
                pkt->pos = pos;
                if (st->codec->codec_id == CODEC_ID_TEXT)
                    pkt->convergence_duration = duration;
                else if (track->type != MATROSKA_TRACK_TYPE_SUBTITLE)
                    pkt->duration = duration;
                if (st->codec->codec_id == CODEC_ID_SSA)
                    matroska_fix_ass_packet(matroska, pkt, duration);
                if (matroska->prev_pkt &&
                    timecode != AV_NOPTS_VALUE &&
                    matroska->prev_pkt->pts == timecode &&
                    matroska->prev_pkt->stream_index == st->index)
                    matroska_merge_packets(matroska->prev_pkt, pkt);
                else {
                    dynarray_add(&matroska->packets,&matroska->num_packets,pkt);
                    matroska->prev_pkt = pkt;
            if (timecode != AV_NOPTS_VALUE)
                timecode = duration ? timecode + duration : AV_NOPTS_VALUE;
            data += lace_size[n];
            size -= lace_size[n];
    av_free(lace_size);
    return res;

void ff_mpeg_set_erpic(ERPicture *dst, Picture *src)

{

    int i;




    if (!src)

        return;



    dst->f = &src->f;

    dst->tf = &src->tf;



    for (i = 0; i < 2; i++) {

        dst->motion_val[i] = src->motion_val[i];

        dst->ref_index[i] = src->ref_index[i];

    }



    dst->mb_type = src->mb_type;

    dst->field_picture = src->field_picture;

}

static void synthfilt_build_sb_samples (QDM2Context *q, GetBitContext *gb, int length, int sb_min, int sb_max)

{

    int sb, j, k, n, ch, run, channels;

    int joined_stereo, zero_encoding, chs;

    int type34_first;

    float type34_div = 0;

    float type34_predictor;

    float samples[10], sign_bits[16];



    if (length == 0) {

        // If no data use noise

        for (sb=sb_min; sb < sb_max; sb++)

            build_sb_samples_from_noise (q, sb);



        return;

    }



    for (sb = sb_min; sb < sb_max; sb++) {

        FIX_NOISE_IDX(q->noise_idx);



        channels = q->nb_channels;



        if (q->nb_channels <= 1 || sb < 12)

            joined_stereo = 0;

        else if (sb >= 24)

            joined_stereo = 1;

        else

            joined_stereo = (get_bits_left(gb) >= 1) ? get_bits1 (gb) : 0;



        if (joined_stereo) {

            if (get_bits_left(gb) >= 16)

                for (j = 0; j < 16; j++)

                    sign_bits[j] = get_bits1 (gb);



            for (j = 0; j < 64; j++)

                if (q->coding_method[1][sb][j] > q->coding_method[0][sb][j])

                    q->coding_method[0][sb][j] = q->coding_method[1][sb][j];



            fix_coding_method_array(sb, q->nb_channels, q->coding_method);

            channels = 1;

        }



        for (ch = 0; ch < channels; ch++) {

            zero_encoding = (get_bits_left(gb) >= 1) ? get_bits1(gb) : 0;

            type34_predictor = 0.0;

            type34_first = 1;



            for (j = 0; j < 128; ) {

                switch (q->coding_method[ch][sb][j / 2]) {

                    case 8:

                        if (get_bits_left(gb) >= 10) {

                            if (zero_encoding) {

                                for (k = 0; k < 5; k++) {

                                    if ((j + 2 * k) >= 128)

                                        break;

                                    samples[2 * k] = get_bits1(gb) ? dequant_1bit[joined_stereo][2 * get_bits1(gb)] : 0;

                                }

                            } else {

                                n = get_bits(gb, 8);

                                for (k = 0; k < 5; k++)

                                    samples[2 * k] = dequant_1bit[joined_stereo][random_dequant_index[n][k]];

                            }

                            for (k = 0; k < 5; k++)

                                samples[2 * k + 1] = SB_DITHERING_NOISE(sb,q->noise_idx);

                        } else {

                            for (k = 0; k < 10; k++)

                                samples[k] = SB_DITHERING_NOISE(sb,q->noise_idx);

                        }

                        run = 10;

                        break;



                    case 10:

                        if (get_bits_left(gb) >= 1) {

                            float f = 0.81;



                            if (get_bits1(gb))

                                f = -f;

                            f -= noise_samples[((sb + 1) * (j +5 * ch + 1)) & 127] * 9.0 / 40.0;

                            samples[0] = f;

                        } else {

                            samples[0] = SB_DITHERING_NOISE(sb,q->noise_idx);

                        }

                        run = 1;

                        break;



                    case 16:

                        if (get_bits_left(gb) >= 10) {

                            if (zero_encoding) {

                                for (k = 0; k < 5; k++) {

                                    if ((j + k) >= 128)

                                        break;

                                    samples[k] = (get_bits1(gb) == 0) ? 0 : dequant_1bit[joined_stereo][2 * get_bits1(gb)];

                                }

                            } else {

                                n = get_bits (gb, 8);

                                for (k = 0; k < 5; k++)

                                    samples[k] = dequant_1bit[joined_stereo][random_dequant_index[n][k]];

                            }

                        } else {

                            for (k = 0; k < 5; k++)

                                samples[k] = SB_DITHERING_NOISE(sb,q->noise_idx);

                        }

                        run = 5;

                        break;



                    case 24:

                        if (get_bits_left(gb) >= 7) {

                            n = get_bits(gb, 7);

                            for (k = 0; k < 3; k++)

                                samples[k] = (random_dequant_type24[n][k] - 2.0) * 0.5;

                        } else {

                            for (k = 0; k < 3; k++)

                                samples[k] = SB_DITHERING_NOISE(sb,q->noise_idx);

                        }

                        run = 3;

                        break;



                    case 30:

                        if (get_bits_left(gb) >= 4)

                            samples[0] = type30_dequant[qdm2_get_vlc(gb, &vlc_tab_type30, 0, 1)];

                        else

                            samples[0] = SB_DITHERING_NOISE(sb,q->noise_idx);



                        run = 1;

                        break;



                    case 34:

                        if (get_bits_left(gb) >= 7) {

                            if (type34_first) {

                                type34_div = (float)(1 << get_bits(gb, 2));

                                samples[0] = ((float)get_bits(gb, 5) - 16.0) / 15.0;

                                type34_predictor = samples[0];

                                type34_first = 0;

                            } else {

                                samples[0] = type34_delta[qdm2_get_vlc(gb, &vlc_tab_type34, 0, 1)] / type34_div + type34_predictor;

                                type34_predictor = samples[0];

                            }

                        } else {

                            samples[0] = SB_DITHERING_NOISE(sb,q->noise_idx);

                        }

                        run = 1;

                        break;



                    default:

                        samples[0] = SB_DITHERING_NOISE(sb,q->noise_idx);

                        run = 1;

                        break;

                }



                if (joined_stereo) {

                    float tmp[10][MPA_MAX_CHANNELS];



                    for (k = 0; k < run; k++) {

                        tmp[k][0] = samples[k];

                        tmp[k][1] = (sign_bits[(j + k) / 8]) ? -samples[k] : samples[k];

                    }

                    for (chs = 0; chs < q->nb_channels; chs++)

                        for (k = 0; k < run; k++)

                            if ((j + k) < 128)

                                q->sb_samples[chs][j + k][sb] = q->tone_level[chs][sb][((j + k)/2)] * tmp[k][chs];

                } else {

                    for (k = 0; k < run; k++)

                        if ((j + k) < 128)

                            q->sb_samples[ch][j + k][sb] = q->tone_level[ch][sb][(j + k)/2] * samples[k];

                }



                j += run;

            } // j loop

        } // channel loop

    } // subband loop

}

static int svq3_decode_slice_header(AVCodecContext *avctx)

{

    SVQ3Context *svq3 = avctx->priv_data;

    H264Context *h = &svq3->h;

    MpegEncContext *s = &h->s;

    const int mb_xy = h->mb_xy;

    int i, header;



    header = get_bits(&s->gb, 8);



    if (((header & 0x9F) != 1 && (header & 0x9F) != 2) || (header & 0x60) == 0) {

        /* TODO: what? */

        av_log(avctx, AV_LOG_ERROR, "unsupported slice header (%02X)\n", header);

        return -1;

    } else {

        int length = (header >> 5) & 3;



        svq3->next_slice_index = get_bits_count(&s->gb) + 8*show_bits(&s->gb, 8*length) + 8*length;



        if (svq3->next_slice_index > s->gb.size_in_bits) {

            av_log(avctx, AV_LOG_ERROR, "slice after bitstream end\n");

            return -1;

    }



        s->gb.size_in_bits = svq3->next_slice_index - 8*(length - 1);

        skip_bits(&s->gb, 8);



        if (svq3->watermark_key) {

            uint32_t header = AV_RL32(&s->gb.buffer[(get_bits_count(&s->gb)>>3)+1]);

            AV_WL32(&s->gb.buffer[(get_bits_count(&s->gb)>>3)+1], header ^ svq3->watermark_key);

        }

        if (length > 0) {

            memcpy((uint8_t *) &s->gb.buffer[get_bits_count(&s->gb) >> 3],

                   &s->gb.buffer[s->gb.size_in_bits >> 3], (length - 1));

        }

        skip_bits_long(&s->gb, 0);

    }



    if ((i = svq3_get_ue_golomb(&s->gb)) == INVALID_VLC || i >= 3){

        av_log(h->s.avctx, AV_LOG_ERROR, "illegal slice type %d \n", i);

        return -1;

    }



    h->slice_type = golomb_to_pict_type[i];



    if ((header & 0x9F) == 2) {

        i = (s->mb_num < 64) ? 6 : (1 + av_log2 (s->mb_num - 1));

        s->mb_skip_run = get_bits(&s->gb, i) - (s->mb_x + (s->mb_y * s->mb_width));

    } else {

        skip_bits1(&s->gb);

        s->mb_skip_run = 0;

    }



    h->slice_num = get_bits(&s->gb, 8);

    s->qscale = get_bits(&s->gb, 5);

    s->adaptive_quant = get_bits1(&s->gb);



    /* unknown fields */

    skip_bits1(&s->gb);



    if (svq3->unknown_flag) {

        skip_bits1(&s->gb);

    }



    skip_bits1(&s->gb);

    skip_bits(&s->gb, 2);



    while (get_bits1(&s->gb)) {

        skip_bits(&s->gb, 8);

    }



    /* reset intra predictors and invalidate motion vector references */

    if (s->mb_x > 0) {

        memset(h->intra4x4_pred_mode+h->mb2br_xy[mb_xy - 1      ]+3, -1, 4*sizeof(int8_t));

        memset(h->intra4x4_pred_mode+h->mb2br_xy[mb_xy - s->mb_x]  , -1, 8*sizeof(int8_t)*s->mb_x);

    }

    if (s->mb_y > 0) {

        memset(h->intra4x4_pred_mode+h->mb2br_xy[mb_xy - s->mb_stride], -1, 8*sizeof(int8_t)*(s->mb_width - s->mb_x));



        if (s->mb_x > 0) {

            h->intra4x4_pred_mode[h->mb2br_xy[mb_xy - s->mb_stride - 1]+3] = -1;

        }

    }



    return 0;

}

void avfilter_default_start_frame(AVFilterLink *link, AVFilterPicRef *picref)

{

    AVFilterLink *out = NULL;



    if(link->dst->output_count)

        out = link->dst->outputs[0];



    if(out) {

        out->outpic      = avfilter_get_video_buffer(out, AV_PERM_WRITE, link->w, link->h);

        out->outpic->pts = picref->pts;

        avfilter_start_frame(out, avfilter_ref_pic(out->outpic, ~0));

    }

}

static void choose_sample_fmt(AVStream *st, AVCodec *codec)

{

    if (codec && codec->sample_fmts) {

        const enum AVSampleFormat *p = codec->sample_fmts;

        for (; *p != -1; p++) {

            if (*p == st->codec->sample_fmt)

                break;

        }

        if (*p == -1) {

            av_log(NULL, AV_LOG_WARNING,

                   "Incompatible sample format '%s' for codec '%s', auto-selecting format '%s'\n",

                   av_get_sample_fmt_name(st->codec->sample_fmt),

                   codec->name,

                   av_get_sample_fmt_name(codec->sample_fmts[0]));

            st->codec->sample_fmt = codec->sample_fmts[0];

        }

    }

}

static int decode_wdlt(GetByteContext *gb, uint8_t *frame, int width, int height)

{

    const uint8_t *frame_end   = frame + width * height;

    uint8_t *line_ptr;

    int count, i, v, lines, segments;



    lines = bytestream2_get_le16(gb);

    if (lines > height)

        return -1;



    while (lines--) {

        if (bytestream2_get_bytes_left(gb) < 2)

            return -1;

        segments = bytestream2_get_le16u(gb);

        while ((segments & 0xC000) == 0xC000) {

            unsigned delta = -((int16_t)segments * width);

            if (frame_end - frame <= delta)

                return -1;

            frame    += delta;

            segments = bytestream2_get_le16(gb);

        }

        if (segments & 0x8000) {

            frame[width - 1] = segments & 0xFF;

            segments = bytestream2_get_le16(gb);

        }

        line_ptr = frame;

        frame += width;

        while (segments--) {

            if (frame - line_ptr <= bytestream2_peek_byte(gb))

                return -1;

            line_ptr += bytestream2_get_byte(gb);

            count = (int8_t)bytestream2_get_byte(gb);

            if (count >= 0) {

                if (frame - line_ptr < count * 2)

                    return -1;

                if (bytestream2_get_buffer(gb, line_ptr, count * 2) != count * 2)

                    return -1;

                line_ptr += count * 2;

            } else {

                count = -count;

                if (frame - line_ptr < count * 2)

                    return -1;

                v = bytestream2_get_le16(gb);

                for (i = 0; i < count; i++)

                    bytestream_put_le16(&line_ptr, v);

            }

        }

    }



    return 0;

}

static inline void decode_hrd_parameters(H264Context *h, SPS *sps){

    MpegEncContext * const s = &h->s;

    int cpb_count, i;

    cpb_count = get_ue_golomb(&s->gb) + 1;

    get_bits(&s->gb, 4); /* bit_rate_scale */

    get_bits(&s->gb, 4); /* cpb_size_scale */

    for(i=0; i<cpb_count; i++){

        get_ue_golomb(&s->gb); /* bit_rate_value_minus1 */

        get_ue_golomb(&s->gb); /* cpb_size_value_minus1 */

        get_bits1(&s->gb);     /* cbr_flag */

    }

    get_bits(&s->gb, 5); /* initial_cpb_removal_delay_length_minus1 */

    sps->cpb_removal_delay_length = get_bits(&s->gb, 5) + 1;

    sps->dpb_output_delay_length = get_bits(&s->gb, 5) + 1;

    sps->time_offset_length = get_bits(&s->gb, 5);

}

static void reanalyze(MpegTSContext *ts) {

    AVIOContext *pb = ts->stream->pb;

    int64_t pos = avio_tell(pb);

    if(pos < 0)

        return;

    pos += ts->raw_packet_size - ts->pos47_full;

    if (pos == TS_PACKET_SIZE) {

        ts->size_stat[0] ++;

    } else if (pos == TS_DVHS_PACKET_SIZE) {

        ts->size_stat[1] ++;

    } else if (pos == TS_FEC_PACKET_SIZE) {

        ts->size_stat[2] ++;

    }



    ts->size_stat_count ++;

    if(ts->size_stat_count > SIZE_STAT_THRESHOLD) {

        int newsize = 0;

        if (ts->size_stat[0] > SIZE_STAT_THRESHOLD) {

            newsize = TS_PACKET_SIZE;

        } else if (ts->size_stat[1] > SIZE_STAT_THRESHOLD) {

            newsize = TS_DVHS_PACKET_SIZE;

        } else if (ts->size_stat[2] > SIZE_STAT_THRESHOLD) {

            newsize = TS_FEC_PACKET_SIZE;

        }

        if (newsize) {

            av_log(ts->stream, AV_LOG_WARNING, "changing packet size to %d\n", newsize);

            ts->raw_packet_size = newsize;

        }

        ts->size_stat_count = 0;

        memset(ts->size_stat, 0, sizeof(ts->size_stat));

    }

}

int ff_hevc_decode_nal_vps(HEVCContext *s)

{

    int i,j;

    GetBitContext *gb = &s->HEVClc.gb;

    int vps_id = 0;

    HEVCVPS *vps;

    AVBufferRef *vps_buf = av_buffer_allocz(sizeof(*vps));



    if (!vps_buf)

      return AVERROR(ENOMEM);

    vps = (HEVCVPS*)vps_buf->data;



    av_log(s->avctx, AV_LOG_DEBUG, "Decoding VPS\n");



    vps_id = get_bits(gb, 4);

    if (vps_id >= MAX_VPS_COUNT) {

        av_log(s->avctx, AV_LOG_ERROR, "VPS id out of range: %d\n", vps_id);

        goto err;

    }



    if (get_bits(gb, 2) != 3) { // vps_reserved_three_2bits

        av_log(s->avctx, AV_LOG_ERROR, "vps_reserved_three_2bits is not three\n");

        goto err;

    }



    vps->vps_max_layers               = get_bits(gb, 6) + 1;

    vps->vps_max_sub_layers           = get_bits(gb, 3) + 1;

    vps->vps_temporal_id_nesting_flag = get_bits1(gb);



    if (get_bits(gb, 16) != 0xffff) { // vps_reserved_ffff_16bits

        av_log(s->avctx, AV_LOG_ERROR, "vps_reserved_ffff_16bits is not 0xffff\n");

        goto err;

    }



    if (vps->vps_max_sub_layers > MAX_SUB_LAYERS) {

        av_log(s->avctx, AV_LOG_ERROR, "vps_max_sub_layers out of range: %d\n",

               vps->vps_max_sub_layers);

        goto err;

    }



    if (decode_profile_tier_level(&s->HEVClc, &vps->ptl, vps->vps_max_sub_layers) < 0) {

        av_log(s->avctx, AV_LOG_ERROR, "Error decoding profile tier level.\n");

        goto err;

    }

    vps->vps_sub_layer_ordering_info_present_flag = get_bits1(gb);



    i = vps->vps_sub_layer_ordering_info_present_flag ? 0 : vps->vps_max_sub_layers - 1;

    for (; i < vps->vps_max_sub_layers; i++) {

        vps->vps_max_dec_pic_buffering[i] = get_ue_golomb_long(gb) + 1;

        vps->vps_num_reorder_pics[i]      = get_ue_golomb_long(gb);

        vps->vps_max_latency_increase[i]  = get_ue_golomb_long(gb) - 1;



        if (vps->vps_max_dec_pic_buffering[i] > MAX_DPB_SIZE) {

            av_log(s->avctx, AV_LOG_ERROR, "vps_max_dec_pic_buffering_minus1 out of range: %d\n",

                   vps->vps_max_dec_pic_buffering[i] - 1);

            goto err;

        }

        if (vps->vps_num_reorder_pics[i] > vps->vps_max_dec_pic_buffering[i] - 1) {

            av_log(s->avctx, AV_LOG_ERROR, "vps_max_num_reorder_pics out of range: %d\n",

                   vps->vps_num_reorder_pics[i]);

            goto err;

        }

    }



    vps->vps_max_layer_id   = get_bits(gb, 6);

    vps->vps_num_layer_sets = get_ue_golomb_long(gb) + 1;

    for (i = 1; i < vps->vps_num_layer_sets; i++)

        for (j = 0; j <= vps->vps_max_layer_id; j++)

            skip_bits(gb, 1);  // layer_id_included_flag[i][j]



    vps->vps_timing_info_present_flag = get_bits1(gb);

    if (vps->vps_timing_info_present_flag) {

        vps->vps_num_units_in_tick               = get_bits_long(gb, 32);

        vps->vps_time_scale                      = get_bits_long(gb, 32);

        vps->vps_poc_proportional_to_timing_flag = get_bits1(gb);

        if (vps->vps_poc_proportional_to_timing_flag)

            vps->vps_num_ticks_poc_diff_one = get_ue_golomb_long(gb) + 1;

        vps->vps_num_hrd_parameters = get_ue_golomb_long(gb);

        for (i = 0; i < vps->vps_num_hrd_parameters; i++) {

            int common_inf_present = 1;



            get_ue_golomb_long(gb); // hrd_layer_set_idx

            if (i)

                common_inf_present = get_bits1(gb);

            decode_hrd(s, common_inf_present, vps->vps_max_sub_layers);

        }

    }

    get_bits1(gb); /* vps_extension_flag */



    av_buffer_unref(&s->vps_list[vps_id]);

    s->vps_list[vps_id] = vps_buf;

    return 0;



err:

    av_buffer_unref(&vps_buf);

    return AVERROR_INVALIDDATA;

}

static int decode_frame(AVCodecContext * avctx, void *data, int *data_size, AVPacket *avpkt)

{

    const uint8_t *buf = avpkt->data;

    int buf_size = avpkt->size;

    KmvcContext *const ctx = avctx->priv_data;

    uint8_t *out, *src;

    int i;

    int header;

    int blocksize;

    const uint8_t *pal = av_packet_get_side_data(avpkt, AV_PKT_DATA_PALETTE, NULL);



    if (ctx->pic.data[0])

        avctx->release_buffer(avctx, &ctx->pic);



    ctx->pic.reference = 1;

    ctx->pic.buffer_hints = FF_BUFFER_HINTS_VALID;

    if (avctx->get_buffer(avctx, &ctx->pic) < 0) {

        av_log(avctx, AV_LOG_ERROR, "get_buffer() failed\n");

        return -1;

    }



    header = *buf++;



    /* blocksize 127 is really palette change event */

    if (buf[0] == 127) {

        buf += 3;

        for (i = 0; i < 127; i++) {

            ctx->pal[i + (header & 0x81)] = AV_RB24(buf);

            buf += 4;

        }

        buf -= 127 * 4 + 3;

    }



    if (header & KMVC_KEYFRAME) {

        ctx->pic.key_frame = 1;

        ctx->pic.pict_type = AV_PICTURE_TYPE_I;

    } else {

        ctx->pic.key_frame = 0;

        ctx->pic.pict_type = AV_PICTURE_TYPE_P;

    }



    if (header & KMVC_PALETTE) {

        ctx->pic.palette_has_changed = 1;

        // palette starts from index 1 and has 127 entries

        for (i = 1; i <= ctx->palsize; i++) {

            ctx->pal[i] = bytestream_get_be24(&buf);

        }

    }



    if (pal) {

        ctx->pic.palette_has_changed = 1;

        memcpy(ctx->pal, pal, AVPALETTE_SIZE);

    }



    if (ctx->setpal) {

        ctx->setpal = 0;

        ctx->pic.palette_has_changed = 1;

    }



    /* make the palette available on the way out */

    memcpy(ctx->pic.data[1], ctx->pal, 1024);



    blocksize = *buf++;



    if (blocksize != 8 && blocksize != 127) {

        av_log(avctx, AV_LOG_ERROR, "Block size = %i\n", blocksize);

        return -1;

    }

    memset(ctx->cur, 0, 320 * 200);

    switch (header & KMVC_METHOD) {

    case 0:

    case 1: // used in palette changed event

        memcpy(ctx->cur, ctx->prev, 320 * 200);

        break;

    case 3:

        kmvc_decode_intra_8x8(ctx, buf, buf_size, avctx->width, avctx->height);

        break;

    case 4:

        kmvc_decode_inter_8x8(ctx, buf, buf_size, avctx->width, avctx->height);

        break;

    default:

        av_log(avctx, AV_LOG_ERROR, "Unknown compression method %i\n", header & KMVC_METHOD);

        return -1;

    }



    out = ctx->pic.data[0];

    src = ctx->cur;

    for (i = 0; i < avctx->height; i++) {

        memcpy(out, src, avctx->width);

        src += 320;

        out += ctx->pic.linesize[0];

    }



    /* flip buffers */

    if (ctx->cur == ctx->frm0) {

        ctx->cur = ctx->frm1;

        ctx->prev = ctx->frm0;

    } else {

        ctx->cur = ctx->frm0;

        ctx->prev = ctx->frm1;

    }



    *data_size = sizeof(AVFrame);

    *(AVFrame *) data = ctx->pic;



    /* always report that the buffer was completely consumed */

    return buf_size;

}

static int read_header(FFV1Context *f)

{

    uint8_t state[CONTEXT_SIZE];

    int i, j, context_count = -1; //-1 to avoid warning

    RangeCoder *const c = &f->slice_context[0]->c;



    memset(state, 128, sizeof(state));



    if (f->version < 2) {

        int chroma_planes, chroma_h_shift, chroma_v_shift, transparency, colorspace, bits_per_raw_sample;

        unsigned v= get_symbol(c, state, 0);

        if (v >= 2) {

            av_log(f->avctx, AV_LOG_ERROR, "invalid version %d in ver01 header\n", v);

            return AVERROR_INVALIDDATA;

        }

        f->version = v;

        f->ac      = f->avctx->coder_type = get_symbol(c, state, 0);

        if (f->ac > 1) {

            for (i = 1; i < 256; i++)

                f->state_transition[i] = get_symbol(c, state, 1) + c->one_state[i];

        }



        colorspace     = get_symbol(c, state, 0); //YUV cs type

        bits_per_raw_sample = f->version > 0 ? get_symbol(c, state, 0) : f->avctx->bits_per_raw_sample;

        chroma_planes  = get_rac(c, state);

        chroma_h_shift = get_symbol(c, state, 0);

        chroma_v_shift = get_symbol(c, state, 0);

        transparency   = get_rac(c, state);



        if (f->plane_count) {

            if (   colorspace    != f->colorspace

                || bits_per_raw_sample != f->avctx->bits_per_raw_sample

                || chroma_planes != f->chroma_planes

                || chroma_h_shift!= f->chroma_h_shift

                || chroma_v_shift!= f->chroma_v_shift

                || transparency  != f->transparency) {

                av_log(f->avctx, AV_LOG_ERROR, "Invalid change of global parameters\n");

                return AVERROR_INVALIDDATA;

            }

        }



        f->colorspace     = colorspace;

        f->avctx->bits_per_raw_sample = bits_per_raw_sample;

        f->chroma_planes  = chroma_planes;

        f->chroma_h_shift = chroma_h_shift;

        f->chroma_v_shift = chroma_v_shift;

        f->transparency   = transparency;



        f->plane_count    = 2 + f->transparency;

    }



    if (f->colorspace == 0) {

        if (!f->transparency && !f->chroma_planes) {

            if (f->avctx->bits_per_raw_sample <= 8)

                f->avctx->pix_fmt = AV_PIX_FMT_GRAY8;

            else

                f->avctx->pix_fmt = AV_PIX_FMT_GRAY16;

        } else if (f->avctx->bits_per_raw_sample<=8 && !f->transparency) {

            switch(16 * f->chroma_h_shift + f->chroma_v_shift) {

            case 0x00: f->avctx->pix_fmt = AV_PIX_FMT_YUV444P; break;

            case 0x01: f->avctx->pix_fmt = AV_PIX_FMT_YUV440P; break;

            case 0x10: f->avctx->pix_fmt = AV_PIX_FMT_YUV422P; break;

            case 0x11: f->avctx->pix_fmt = AV_PIX_FMT_YUV420P; break;

            case 0x20: f->avctx->pix_fmt = AV_PIX_FMT_YUV411P; break;

            case 0x22: f->avctx->pix_fmt = AV_PIX_FMT_YUV410P; break;

            default:

                av_log(f->avctx, AV_LOG_ERROR, "format not supported\n");

                return AVERROR(ENOSYS);

            }

        } else if (f->avctx->bits_per_raw_sample <= 8 && f->transparency) {

            switch(16*f->chroma_h_shift + f->chroma_v_shift) {

            case 0x00: f->avctx->pix_fmt = AV_PIX_FMT_YUVA444P; break;

            case 0x10: f->avctx->pix_fmt = AV_PIX_FMT_YUVA422P; break;

            case 0x11: f->avctx->pix_fmt = AV_PIX_FMT_YUVA420P; break;

            default:

                av_log(f->avctx, AV_LOG_ERROR, "format not supported\n");

                return AVERROR(ENOSYS);

            }

        } else if (f->avctx->bits_per_raw_sample == 9) {

            f->packed_at_lsb = 1;

            switch(16 * f->chroma_h_shift + f->chroma_v_shift) {

            case 0x00: f->avctx->pix_fmt = AV_PIX_FMT_YUV444P9; break;

            case 0x10: f->avctx->pix_fmt = AV_PIX_FMT_YUV422P9; break;

            case 0x11: f->avctx->pix_fmt = AV_PIX_FMT_YUV420P9; break;

            default:

                av_log(f->avctx, AV_LOG_ERROR, "format not supported\n");

                return AVERROR(ENOSYS);

            }

        } else if (f->avctx->bits_per_raw_sample == 10) {

            f->packed_at_lsb = 1;

            switch(16 * f->chroma_h_shift + f->chroma_v_shift) {

            case 0x00: f->avctx->pix_fmt = AV_PIX_FMT_YUV444P10; break;

            case 0x10: f->avctx->pix_fmt = AV_PIX_FMT_YUV422P10; break;

            case 0x11: f->avctx->pix_fmt = AV_PIX_FMT_YUV420P10; break;

            default:

                av_log(f->avctx, AV_LOG_ERROR, "format not supported\n");

                return AVERROR(ENOSYS);

            }

        } else {

            switch(16 * f->chroma_h_shift + f->chroma_v_shift) {

            case 0x00: f->avctx->pix_fmt = AV_PIX_FMT_YUV444P16; break;

            case 0x10: f->avctx->pix_fmt = AV_PIX_FMT_YUV422P16; break;

            case 0x11: f->avctx->pix_fmt = AV_PIX_FMT_YUV420P16; break;

            default:

                av_log(f->avctx, AV_LOG_ERROR, "format not supported\n");

                return AVERROR(ENOSYS);

            }

        }

    } else if (f->colorspace == 1) {

        if (f->chroma_h_shift || f->chroma_v_shift) {

            av_log(f->avctx, AV_LOG_ERROR,

                   "chroma subsampling not supported in this colorspace\n");

            return AVERROR(ENOSYS);

        }

        if (     f->avctx->bits_per_raw_sample ==  9)

            f->avctx->pix_fmt = AV_PIX_FMT_GBRP9;

        else if (f->avctx->bits_per_raw_sample == 10)

            f->avctx->pix_fmt = AV_PIX_FMT_GBRP10;

        else if (f->avctx->bits_per_raw_sample == 12)

            f->avctx->pix_fmt = AV_PIX_FMT_GBRP12;

        else if (f->avctx->bits_per_raw_sample == 14)

            f->avctx->pix_fmt = AV_PIX_FMT_GBRP14;

        else

        if (f->transparency) f->avctx->pix_fmt = AV_PIX_FMT_RGB32;

        else                 f->avctx->pix_fmt = AV_PIX_FMT_0RGB32;

    } else {

        av_log(f->avctx, AV_LOG_ERROR, "colorspace not supported\n");

        return AVERROR(ENOSYS);

    }



    av_dlog(f->avctx, "%d %d %d\n",

            f->chroma_h_shift, f->chroma_v_shift, f->avctx->pix_fmt);

    if (f->version < 2) {

        context_count = read_quant_tables(c, f->quant_table);

        if (context_count < 0) {

            av_log(f->avctx, AV_LOG_ERROR, "read_quant_table error\n");

            return AVERROR_INVALIDDATA;

        }

    } else if (f->version < 3) {

        f->slice_count = get_symbol(c, state, 0);

    } else {

        const uint8_t *p = c->bytestream_end;

        for (f->slice_count = 0;

             f->slice_count < MAX_SLICES && 3 < p - c->bytestream_start;

             f->slice_count++) {

            int trailer = 3 + 5*!!f->ec;

            int size = AV_RB24(p-trailer);

            if (size + trailer > p - c->bytestream_start)

                break;

            p -= size + trailer;

        }

    }

    if (f->slice_count > (unsigned)MAX_SLICES || f->slice_count <= 0) {

        av_log(f->avctx, AV_LOG_ERROR, "slice count %d is invalid\n", f->slice_count);

        return AVERROR_INVALIDDATA;

    }



    for (j = 0; j < f->slice_count; j++) {

        FFV1Context *fs = f->slice_context[j];

        fs->ac            = f->ac;

        fs->packed_at_lsb = f->packed_at_lsb;



        fs->slice_damaged = 0;



        if (f->version == 2) {

            fs->slice_x      =  get_symbol(c, state, 0)      * f->width ;

            fs->slice_y      =  get_symbol(c, state, 0)      * f->height;

            fs->slice_width  = (get_symbol(c, state, 0) + 1) * f->width  + fs->slice_x;

            fs->slice_height = (get_symbol(c, state, 0) + 1) * f->height + fs->slice_y;



            fs->slice_x     /= f->num_h_slices;

            fs->slice_y     /= f->num_v_slices;

            fs->slice_width  = fs->slice_width  / f->num_h_slices - fs->slice_x;

            fs->slice_height = fs->slice_height / f->num_v_slices - fs->slice_y;

            if ((unsigned)fs->slice_width  > f->width ||

                (unsigned)fs->slice_height > f->height)

                return AVERROR_INVALIDDATA;

            if (   (unsigned)fs->slice_x + (uint64_t)fs->slice_width  > f->width

                || (unsigned)fs->slice_y + (uint64_t)fs->slice_height > f->height)

                return AVERROR_INVALIDDATA;

        }



        for (i = 0; i < f->plane_count; i++) {

            PlaneContext *const p = &fs->plane[i];



            if (f->version == 2) {

                int idx = get_symbol(c, state, 0);

                if (idx > (unsigned)f->quant_table_count) {

                    av_log(f->avctx, AV_LOG_ERROR,

                           "quant_table_index out of range\n");

                    return AVERROR_INVALIDDATA;

                }

                p->quant_table_index = idx;

                memcpy(p->quant_table, f->quant_tables[idx],

                       sizeof(p->quant_table));

                context_count = f->context_count[idx];

            } else {

                memcpy(p->quant_table, f->quant_table, sizeof(p->quant_table));

            }



            if (f->version <= 2) {

                av_assert0(context_count >= 0);

                if (p->context_count < context_count) {

                    av_freep(&p->state);

                    av_freep(&p->vlc_state);

                }

                p->context_count = context_count;

            }

        }

    }

    return 0;

}

static int config_props(AVFilterLink *outlink)

{

    AVFilterContext *ctx = outlink->src;

    AVFilterLink *inlink = outlink->src->inputs[0];

    ScaleContext *scale = ctx->priv;

    int64_t w, h;

    double var_values[VARS_NB], res;

    char *expr;

    int ret;



    var_values[VAR_PI]    = M_PI;

    var_values[VAR_PHI]   = M_PHI;

    var_values[VAR_E]     = M_E;

    var_values[VAR_IN_W]  = var_values[VAR_IW] = inlink->w;

    var_values[VAR_IN_H]  = var_values[VAR_IH] = inlink->h;

    var_values[VAR_OUT_W] = var_values[VAR_OW] = NAN;

    var_values[VAR_OUT_H] = var_values[VAR_OH] = NAN;

    var_values[VAR_DAR]   = var_values[VAR_A]  = (float) inlink->w / inlink->h;

    var_values[VAR_SAR]   = inlink->sample_aspect_ratio.num ?

        (float) inlink->sample_aspect_ratio.num / inlink->sample_aspect_ratio.den : 1;

    var_values[VAR_HSUB]  = 1<<av_pix_fmt_descriptors[inlink->format].log2_chroma_w;

    var_values[VAR_VSUB]  = 1<<av_pix_fmt_descriptors[inlink->format].log2_chroma_h;



    /* evaluate width and height */

    av_expr_parse_and_eval(&res, (expr = scale->w_expr),

                           var_names, var_values,

                           NULL, NULL, NULL, NULL, NULL, 0, ctx);

    scale->w = var_values[VAR_OUT_W] = var_values[VAR_OW] = res;

    if ((ret = av_expr_parse_and_eval(&res, (expr = scale->h_expr),

                                      var_names, var_values,

                                      NULL, NULL, NULL, NULL, NULL, 0, ctx)) < 0)

        goto fail;

    scale->h = var_values[VAR_OUT_H] = var_values[VAR_OH] = res;

    /* evaluate again the width, as it may depend on the output height */

    if ((ret = av_expr_parse_and_eval(&res, (expr = scale->w_expr),

                                      var_names, var_values,

                                      NULL, NULL, NULL, NULL, NULL, 0, ctx)) < 0)

        goto fail;

    scale->w = res;



    w = scale->w;

    h = scale->h;



    /* sanity check params */

    if (w <  -1 || h <  -1) {

        av_log(ctx, AV_LOG_ERROR, "Size values less than -1 are not acceptable.\n");

        return AVERROR(EINVAL);

    }

    if (w == -1 && h == -1)

        scale->w = scale->h = 0;



    if (!(w = scale->w))

        w = inlink->w;

    if (!(h = scale->h))

        h = inlink->h;

    if (w == -1)

        w = av_rescale(h, inlink->w, inlink->h);

    if (h == -1)

        h = av_rescale(w, inlink->h, inlink->w);



    if (w > INT_MAX || h > INT_MAX ||

        (h * inlink->w) > INT_MAX  ||

        (w * inlink->h) > INT_MAX)

        av_log(ctx, AV_LOG_ERROR, "Rescaled value for width or height is too big.\n");



    outlink->w = w;

    outlink->h = h;



    /* TODO: make algorithm configurable */

    av_log(ctx, AV_LOG_INFO, "w:%d h:%d fmt:%s -> w:%d h:%d fmt:%s flags:0x%0x\n",

           inlink ->w, inlink ->h, av_pix_fmt_descriptors[ inlink->format].name,

           outlink->w, outlink->h, av_pix_fmt_descriptors[outlink->format].name,

           scale->flags);



    scale->input_is_pal = av_pix_fmt_descriptors[inlink->format].flags & PIX_FMT_PAL;



    if (scale->sws)

        sws_freeContext(scale->sws);

    scale->sws = sws_getContext(inlink ->w, inlink ->h, inlink ->format,

                                outlink->w, outlink->h, outlink->format,

                                scale->flags, NULL, NULL, NULL);

    if (!scale->sws)

        return AVERROR(EINVAL);





    if (inlink->sample_aspect_ratio.num)

        outlink->sample_aspect_ratio = av_mul_q((AVRational){outlink->h*inlink->w,

                                                             outlink->w*inlink->h},

                                                inlink->sample_aspect_ratio);

    else

        outlink->sample_aspect_ratio = inlink->sample_aspect_ratio;



    return 0;



fail:

    av_log(NULL, AV_LOG_ERROR,

           "Error when evaluating the expression '%s'\n", expr);

    return ret;

}

static int set_sps(HEVCContext *s, const HEVCSPS *sps)

{

    #define HWACCEL_MAX (CONFIG_HEVC_DXVA2_HWACCEL + CONFIG_HEVC_D3D11VA_HWACCEL)

    enum AVPixelFormat pix_fmts[HWACCEL_MAX + 2], *fmt = pix_fmts;

    int ret;



    export_stream_params(s->avctx, &s->ps, sps);



    pic_arrays_free(s);

    ret = pic_arrays_init(s, sps);

    if (ret < 0)

        goto fail;



    if (sps->pix_fmt == AV_PIX_FMT_YUV420P || sps->pix_fmt == AV_PIX_FMT_YUVJ420P) {

#if CONFIG_HEVC_DXVA2_HWACCEL

        *fmt++ = AV_PIX_FMT_DXVA2_VLD;

#endif

#if CONFIG_HEVC_D3D11VA_HWACCEL

        *fmt++ = AV_PIX_FMT_D3D11VA_VLD;

#endif

    }



    *fmt++ = sps->pix_fmt;

    *fmt = AV_PIX_FMT_NONE;



    ret = ff_get_format(s->avctx, pix_fmts);

    if (ret < 0)

        goto fail;

    s->avctx->pix_fmt = ret;



    ff_hevc_pred_init(&s->hpc,     sps->bit_depth);

    ff_hevc_dsp_init (&s->hevcdsp, sps->bit_depth);

    ff_videodsp_init (&s->vdsp,    sps->bit_depth);



    if (sps->sao_enabled && !s->avctx->hwaccel) {

        av_frame_unref(s->tmp_frame);

        ret = ff_get_buffer(s->avctx, s->tmp_frame, AV_GET_BUFFER_FLAG_REF);

        if (ret < 0)

            goto fail;

        s->frame = s->tmp_frame;

    }



    s->ps.sps = sps;

    s->ps.vps = (HEVCVPS*) s->ps.vps_list[s->ps.sps->vps_id]->data;



    return 0;



fail:

    pic_arrays_free(s);

    s->ps.sps = NULL;

    return ret;

}

static int svq1_encode_frame(AVCodecContext *avctx, unsigned char *buf, 

    int buf_size, void *data)

{

    SVQ1Context * const s = avctx->priv_data;

    AVFrame *pict = data;

    AVFrame * const p= (AVFrame*)&s->picture;

    AVFrame temp;

    int i;



    if(avctx->pix_fmt != PIX_FMT_YUV410P){

        av_log(avctx, AV_LOG_ERROR, "unsupported pixel format\n");

        return -1;

    }



    if(!s->current_picture.data[0]){

        avctx->get_buffer(avctx, &s->current_picture);

        avctx->get_buffer(avctx, &s->last_picture);

    }



    temp= s->current_picture;

    s->current_picture= s->last_picture;

    s->last_picture= temp;



    init_put_bits(&s->pb, buf, buf_size);



    *p = *pict;

    p->pict_type = avctx->frame_number % avctx->gop_size ? P_TYPE : I_TYPE;

    p->key_frame = p->pict_type == I_TYPE;



    svq1_write_header(s, p->pict_type);

    for(i=0; i<3; i++){

        svq1_encode_plane(s, i,

            s->picture.data[i], s->last_picture.data[i], s->current_picture.data[i],

            s->frame_width / (i?4:1), s->frame_height / (i?4:1), 

            s->picture.linesize[i], s->current_picture.linesize[i]);

    }



//    align_put_bits(&s->pb);

    while(put_bits_count(&s->pb) & 31)

        put_bits(&s->pb, 1, 0);



    flush_put_bits(&s->pb);



    return (put_bits_count(&s->pb) / 8);

}

