static void pmt_cb(MpegTSFilter *filter, const uint8_t *section, int section_len)

{

    MpegTSContext *ts = filter->u.section_filter.opaque;

    MpegTSSectionFilter *tssf = &filter->u.section_filter;

    SectionHeader h1, *h = &h1;

    PESContext *pes;

    AVStream *st;

    const uint8_t *p, *p_end, *desc_list_end;

    int program_info_length, pcr_pid, pid, stream_type;

    int desc_list_len;

    uint32_t prog_reg_desc = 0; /* registration descriptor */



    int mp4_descr_count = 0;

    Mp4Descr mp4_descr[MAX_MP4_DESCR_COUNT] = { { 0 } };

    int i;



    av_log(ts->stream, AV_LOG_TRACE, "PMT: len %i\n", section_len);

    hex_dump_debug(ts->stream, section, section_len);



    p_end = section + section_len - 4;

    p = section;

    if (parse_section_header(h, &p, p_end) < 0)

        return;

    if (h->version == tssf->last_ver)

        return;

    tssf->last_ver = h->version;



    av_log(ts->stream, AV_LOG_TRACE, "sid=0x%x sec_num=%d/%d version=%d\n",

            h->id, h->sec_num, h->last_sec_num, h->version);



    if (h->tid != PMT_TID)

        return;

    if (!ts->scan_all_pmts && ts->skip_changes)

        return;



    if (!ts->skip_clear)

        clear_program(ts, h->id);



    pcr_pid = get16(&p, p_end);

    if (pcr_pid < 0)

        return;

    pcr_pid &= 0x1fff;

    add_pid_to_pmt(ts, h->id, pcr_pid);

    set_pcr_pid(ts->stream, h->id, pcr_pid);



    av_log(ts->stream, AV_LOG_TRACE, "pcr_pid=0x%x\n", pcr_pid);



    program_info_length = get16(&p, p_end);

    if (program_info_length < 0)

        return;

    program_info_length &= 0xfff;

    while (program_info_length >= 2) {

        uint8_t tag, len;

        tag = get8(&p, p_end);

        len = get8(&p, p_end);



        av_log(ts->stream, AV_LOG_TRACE, "program tag: 0x%02x len=%d\n", tag, len);



        if (len > program_info_length - 2)

            // something else is broken, exit the program_descriptors_loop

            break;

        program_info_length -= len + 2;

        if (tag == 0x1d) { // IOD descriptor

            get8(&p, p_end); // scope

            get8(&p, p_end); // label

            len -= 2;

            mp4_read_iods(ts->stream, p, len, mp4_descr + mp4_descr_count,

                          &mp4_descr_count, MAX_MP4_DESCR_COUNT);

        } else if (tag == 0x05 && len >= 4) { // registration descriptor

            prog_reg_desc = bytestream_get_le32(&p);

            len -= 4;

        }

        p += len;

    }

    p += program_info_length;

    if (p >= p_end)

        goto out;



    // stop parsing after pmt, we found header

    if (!ts->stream->nb_streams)

        ts->stop_parse = 2;



    set_pmt_found(ts, h->id);





    for (;;) {

        st = 0;

        pes = NULL;

        stream_type = get8(&p, p_end);

        if (stream_type < 0)

            break;

        pid = get16(&p, p_end);

        if (pid < 0)

            goto out;

        pid &= 0x1fff;

        if (pid == ts->current_pid)

            goto out;



        /* now create stream */

        if (ts->pids[pid] && ts->pids[pid]->type == MPEGTS_PES) {

            pes = ts->pids[pid]->u.pes_filter.opaque;

            if (!pes->st) {

                pes->st     = avformat_new_stream(pes->stream, NULL);

                if (!pes->st)

                    goto out;

                pes->st->id = pes->pid;

            }

            st = pes->st;

        } else if (stream_type != 0x13) {

            if (ts->pids[pid])

                mpegts_close_filter(ts, ts->pids[pid]); // wrongly added sdt filter probably

            pes = add_pes_stream(ts, pid, pcr_pid);

            if (pes) {

                st = avformat_new_stream(pes->stream, NULL);

                if (!st)

                    goto out;

                st->id = pes->pid;

            }

        } else {

            int idx = ff_find_stream_index(ts->stream, pid);

            if (idx >= 0) {

                st = ts->stream->streams[idx];

            } else {

                st = avformat_new_stream(ts->stream, NULL);

                if (!st)

                    goto out;

                st->id = pid;

                st->codec->codec_type = AVMEDIA_TYPE_DATA;

            }

        }



        if (!st)

            goto out;



        if (pes && !pes->stream_type)

            mpegts_set_stream_info(st, pes, stream_type, prog_reg_desc);



        add_pid_to_pmt(ts, h->id, pid);



        ff_program_add_stream_index(ts->stream, h->id, st->index);



        desc_list_len = get16(&p, p_end);

        if (desc_list_len < 0)

            goto out;

        desc_list_len &= 0xfff;

        desc_list_end  = p + desc_list_len;

        if (desc_list_end > p_end)

            goto out;

        for (;;) {

            if (ff_parse_mpeg2_descriptor(ts->stream, st, stream_type, &p,

                                          desc_list_end, mp4_descr,

                                          mp4_descr_count, pid, ts) < 0)

                break;



            if (pes && prog_reg_desc == AV_RL32("HDMV") &&

                stream_type == 0x83 && pes->sub_st) {

                ff_program_add_stream_index(ts->stream, h->id,

                                            pes->sub_st->index);

                pes->sub_st->codec->codec_tag = st->codec->codec_tag;

            }

        }

        p = desc_list_end;

    }



    if (!ts->pids[pcr_pid])

        mpegts_open_pcr_filter(ts, pcr_pid);



out:

    for (i = 0; i < mp4_descr_count; i++)

        av_free(mp4_descr[i].dec_config_descr);

}

static int rm_read_packet(AVFormatContext *s, AVPacket *pkt)

{

    RMDemuxContext *rm = s->priv_data;

    AVStream *st;

    int i, len, res, seq = 1;

    int64_t timestamp, pos;

    int flags;



    for (;;) {

        if (rm->audio_pkt_cnt) {

            // If there are queued audio packet return them first

            st = s->streams[rm->audio_stream_num];

            ff_rm_retrieve_cache(s, s->pb, st, st->priv_data, pkt);

            flags = 0;

        } else {

            if (rm->old_format) {

                RMStream *ast;



                st = s->streams[0];

                ast = st->priv_data;

                timestamp = AV_NOPTS_VALUE;

                len = !ast->audio_framesize ? RAW_PACKET_SIZE :

                    ast->coded_framesize * ast->sub_packet_h / 2;

                flags = (seq++ == 1) ? 2 : 0;

                pos = avio_tell(s->pb);

            } else {

                len=sync(s, &timestamp, &flags, &i, &pos);

                if (len > 0)

                    st = s->streams[i];

            }



            if(len<0 || s->pb->eof_reached)

                return AVERROR(EIO);



            res = ff_rm_parse_packet (s, s->pb, st, st->priv_data, len, pkt,

                                      &seq, flags, timestamp);

            if((flags&2) && (seq&0x7F) == 1)

                av_add_index_entry(st, pos, timestamp, 0, 0, AVINDEX_KEYFRAME);

            if (res)

                continue;

        }



        if(  (st->discard >= AVDISCARD_NONKEY && !(flags&2))

           || st->discard >= AVDISCARD_ALL){

            av_free_packet(pkt);

        } else

            break;

    }



    return 0;

}

static int decode_group3_2d_line(AVCodecContext *avctx, GetBitContext *gb,

                                 int width, int *runs, const int *runend, const int *ref)

{

    int mode = 0, offs = 0, run = 0, saved_run = 0, t;

    int run_off = *ref++;

    int *run_start = runs;



    runend--; // for the last written 0



    while(offs < width){

        int cmode = get_vlc2(gb, ccitt_group3_2d_vlc.table, 9, 1);

        if(cmode == -1){

            av_log(avctx, AV_LOG_ERROR, "Incorrect mode VLC\n");

            return -1;

        }

        //sync line pointers

        if(runs != run_start)while(run_off <= offs){

            run_off += *ref++;

            run_off += *ref++;

        }

        if(!cmode){//pass mode

            run_off += *ref++;

            run = run_off - offs;

            run_off += *ref++;

            offs += run;

            if(offs > width){

                av_log(avctx, AV_LOG_ERROR, "Run went out of bounds\n");

                return -1;

            }

            saved_run += run;

        }else if(cmode == 1){//horizontal mode

            int k;

            for(k = 0; k < 2; k++){

                run = 0;

                for(;;){

                    t = get_vlc2(gb, ccitt_vlc[mode].table, 9, 2);

                    if(t == -1){

                        av_log(avctx, AV_LOG_ERROR, "Incorrect code\n");

                        return -1;

                    }

                    run += t;

                    if(t < 64)

                        break;

                }

                *runs++ = run + saved_run;

                if(runs >= runend){

                    av_log(avctx, AV_LOG_ERROR, "Run overrun\n");

                    return -1;

                }

                saved_run = 0;

                offs += run;

                if(offs > width){

                    av_log(avctx, AV_LOG_ERROR, "Run went out of bounds\n");

                    return -1;

                }

                mode = !mode;

            }

        }else if(cmode == 9 || cmode == 10){

            av_log(avctx, AV_LOG_ERROR, "Special modes are not supported (yet)\n");

            return -1;

        }else{//vertical mode

            run = run_off - offs + (cmode - 5);

            if(cmode >= 5)

                run_off += *ref++;

            else

                run_off -= *--ref;

            offs += run;

            if(offs > width){

                av_log(avctx, AV_LOG_ERROR, "Run went out of bounds\n");

                return -1;

            }

            *runs++ = run + saved_run;

            if(runs >= runend){

                av_log(avctx, AV_LOG_ERROR, "Run overrun\n");

                return -1;

            }

            saved_run = 0;

            mode = !mode;

        }

    }

    *runs++ = saved_run;

    *runs++ = 0;

    return 0;

}

static int analyze(const uint8_t *buf, int size, int packet_size, int *index,

                   int probe)

{

    int stat[TS_MAX_PACKET_SIZE];

    int stat_all = 0;

    int i;

    int best_score = 0;



    memset(stat, 0, packet_size * sizeof(*stat));



    for (i = 0; i < size - 3; i++) {

        if (buf[i] == 0x47 &&

            (!probe || (!(buf[i + 1] & 0x80) && buf[i + 3] != 0x47))) {

            int x = i % packet_size;

            stat[x]++;

            stat_all++;

            if (stat[x] > best_score) {

                best_score = stat[x];

                if (index)

                    *index = x;

            }

        }

    }



    return best_score - FFMAX(stat_all - 10*best_score, 0)/10;

}

void uninit_opts(void)

{

    int i;

    for (i = 0; i < AVMEDIA_TYPE_NB; i++)

        av_freep(&avcodec_opts[i]);

    av_freep(&avformat_opts->key);

    av_freep(&avformat_opts);

#if CONFIG_SWSCALE

    av_freep(&sws_opts);

#endif

    for (i = 0; i < opt_name_count; i++) {

        //opt_values are only stored for codec-specific options in which case

        //both the name and value are dup'd

        if (opt_values[i]) {

            av_freep(&opt_names[i]);

            av_freep(&opt_values[i]);

        }

    }

    av_freep(&opt_names);

    av_freep(&opt_values);

}

static int ftp_send_command(FTPContext *s, const char *command,

                            const int response_codes[], char **response)

{

    int err;



    /* Flush control connection input to get rid of non relevant responses if any */

    if ((err = ftp_flush_control_input(s)) < 0)

        return err;



    /* send command in blocking mode */

    s->conn_control_block_flag = 0;

    if ((err = ffurl_write(s->conn_control, command, strlen(command))) < 0)

        return err;

    if (!err)

        return -1;



    /* return status */

    if (response_codes) {

        return ftp_status(s, response, response_codes);

    }

    return 0;

}

static int libvorbis_encode_frame(AVCodecContext *avctx, AVPacket *avpkt,

                                  const AVFrame *frame, int *got_packet_ptr)

{

    LibvorbisContext *s = avctx->priv_data;

    ogg_packet op;

    int ret, duration;



    /* send samples to libvorbis */

    if (frame) {

        const int samples = frame->nb_samples;

        float **buffer;

        int c, channels = s->vi.channels;



        buffer = vorbis_analysis_buffer(&s->vd, samples);

        for (c = 0; c < channels; c++) {

            int co = (channels > 8) ? c :

                     ff_vorbis_encoding_channel_layout_offsets[channels - 1][c];

            memcpy(buffer[c], frame->extended_data[co],

                   samples * sizeof(*buffer[c]));

        }

        if ((ret = vorbis_analysis_wrote(&s->vd, samples)) < 0) {

            av_log(avctx, AV_LOG_ERROR, "error in vorbis_analysis_wrote()\n");

            return vorbis_error_to_averror(ret);

        }

        if ((ret = ff_af_queue_add(&s->afq, frame)) < 0)

            return ret;

    } else {

        if (!s->eof)

            if ((ret = vorbis_analysis_wrote(&s->vd, 0)) < 0) {

                av_log(avctx, AV_LOG_ERROR, "error in vorbis_analysis_wrote()\n");

                return vorbis_error_to_averror(ret);

            }

        s->eof = 1;

    }



    /* retrieve available packets from libvorbis */

    while ((ret = vorbis_analysis_blockout(&s->vd, &s->vb)) == 1) {

        if ((ret = vorbis_analysis(&s->vb, NULL)) < 0)

            break;

        if ((ret = vorbis_bitrate_addblock(&s->vb)) < 0)

            break;



        /* add any available packets to the output packet buffer */

        while ((ret = vorbis_bitrate_flushpacket(&s->vd, &op)) == 1) {

            if (av_fifo_space(s->pkt_fifo) < sizeof(ogg_packet) + op.bytes) {

                av_log(avctx, AV_LOG_ERROR, "packet buffer is too small");

                return AVERROR_BUG;

            }

            av_fifo_generic_write(s->pkt_fifo, &op, sizeof(ogg_packet), NULL);

            av_fifo_generic_write(s->pkt_fifo, op.packet, op.bytes, NULL);

        }

        if (ret < 0) {

            av_log(avctx, AV_LOG_ERROR, "error getting available packets\n");

            break;

        }

    }

    if (ret < 0) {

        av_log(avctx, AV_LOG_ERROR, "error getting available packets\n");

        return vorbis_error_to_averror(ret);

    }



    /* check for available packets */

    if (av_fifo_size(s->pkt_fifo) < sizeof(ogg_packet))

        return 0;



    av_fifo_generic_read(s->pkt_fifo, &op, sizeof(ogg_packet), NULL);



    if ((ret = ff_alloc_packet(avpkt, op.bytes))) {

        av_log(avctx, AV_LOG_ERROR, "Error getting output packet\n");

        return ret;

    }

    av_fifo_generic_read(s->pkt_fifo, avpkt->data, op.bytes, NULL);



    avpkt->pts = ff_samples_to_time_base(avctx, op.granulepos);



    duration = avpriv_vorbis_parse_frame(&s->vp, avpkt->data, avpkt->size);

    if (duration > 0) {

        /* we do not know encoder delay until we get the first packet from

         * libvorbis, so we have to update the AudioFrameQueue counts */

        if (!avctx->delay) {

            avctx->delay              = duration;

            s->afq.remaining_delay   += duration;

            s->afq.remaining_samples += duration;

        }

        ff_af_queue_remove(&s->afq, duration, &avpkt->pts, &avpkt->duration);

    }



    *got_packet_ptr = 1;

    return 0;

}

static int get_aac_sample_rates(AVFormatContext *s, AVCodecParameters *par,

                                int *sample_rate, int *output_sample_rate)

{

    MPEG4AudioConfig mp4ac;



    if (avpriv_mpeg4audio_get_config(&mp4ac, par->extradata,

                                     par->extradata_size * 8, 1) < 0) {

        av_log(s, AV_LOG_ERROR,

               "Error parsing AAC extradata, unable to determine samplerate.\n");

        return AVERROR(EINVAL);

    }



    *sample_rate        = mp4ac.sample_rate;

    *output_sample_rate = mp4ac.ext_sample_rate;

    return 0;

}

static int amr_wb_decode_frame(AVCodecContext *avctx, void *data,

                               int *data_size, AVPacket *avpkt)

{

    const uint8_t *buf = avpkt->data;

    int buf_size       = avpkt->size;

    AMRWBContext *s    = avctx->priv_data;

    int mode;

    int packet_size;

    static const uint8_t block_size[16] = {18, 24, 33, 37, 41, 47, 51, 59, 61, 6, 6, 0, 0, 0, 1, 1};



    mode        = (buf[0] >> 3) & 0x000F;

    packet_size = block_size[mode];



    if (packet_size > buf_size) {

        av_log(avctx, AV_LOG_ERROR, "amr frame too short (%u, should be %u)\n",

               buf_size, packet_size + 1);

        return AVERROR_INVALIDDATA;

    }



    D_IF_decode(s->state, buf, data, _good_frame);

    *data_size = 320 * 2;

    return packet_size;

}

static int qdm2_decode_frame(AVCodecContext *avctx,

            void *data, int *data_size,

            uint8_t *buf, int buf_size)

{

    QDM2Context *s = avctx->priv_data;



    if((buf == NULL) || (buf_size < s->checksum_size))

        return 0;



    *data_size = s->channels * s->frame_size * sizeof(int16_t);



    av_log(avctx, AV_LOG_DEBUG, "decode(%d): %p[%d] -> %p[%d]\n",

       buf_size, buf, s->checksum_size, data, *data_size);



    qdm2_decode(s, buf, data);



    // reading only when next superblock found

    if (s->sub_packet == 0) {

        return s->checksum_size;

    }



    return 0;

}

static int parse_packet_header(WMAVoiceContext *s)

{

    GetBitContext *gb = &s->gb;

    unsigned int res;



    if (get_bits_left(gb) < 11)

        return 1;

    skip_bits(gb, 4);          // packet sequence number

    s->has_residual_lsps = get_bits1(gb);

    do {

        res = get_bits(gb, 6); // number of superframes per packet

                               // (minus first one if there is spillover)

        if (get_bits_left(gb) < 6 * (res == 0x3F) + s->spillover_bitsize)

            return 1;

    } while (res == 0x3F);

    s->spillover_nbits   = get_bits(gb, s->spillover_bitsize);



    return 0;

}

static void decode_422_bitstream(HYuvContext *s, int count)

{

    int i;



    count /= 2;



    if (count >= (get_bits_left(&s->gb)) / (31 * 4)) {

        for (i = 0; i < count && get_bits_left(&s->gb) > 0; i++) {

            READ_2PIX(s->temp[0][2 * i    ], s->temp[1][i], 1);

            READ_2PIX(s->temp[0][2 * i + 1], s->temp[2][i], 2);

        }

        for (; i < count; i++)

            s->temp[0][2 * i    ] = s->temp[1][i] =

            s->temp[0][2 * i + 1] = s->temp[2][i] = 128;

    } else {

        for (i = 0; i < count; i++) {

            READ_2PIX(s->temp[0][2 * i    ], s->temp[1][i], 1);

            READ_2PIX(s->temp[0][2 * i + 1], s->temp[2][i], 2);

        }

    }

}

static void flush_packet(AVFormatContext *ctx, int stream_index, int last_pkt)

{

    MpegMuxContext *s = ctx->priv_data;

    StreamInfo *stream = ctx->streams[stream_index]->priv_data;

    uint8_t *buf_ptr;

    int size, payload_size, startcode, id, len, stuffing_size, i, header_len;

    int64_t timestamp;

    uint8_t buffer[128];

    int last = last_pkt ? 4 : 0;



    id = stream->id;

    timestamp = stream->start_pts;



#if 0

    printf("packet ID=%2x PTS=%0.3f\n", 

           id, timestamp / 90000.0);

#endif



    buf_ptr = buffer;

    if (((s->packet_number % s->pack_header_freq) == 0)) {

        /* output pack and systems header if needed */

        size = put_pack_header(ctx, buf_ptr, timestamp);

        buf_ptr += size;

        if ((s->packet_number % s->system_header_freq) == 0) {

            size = put_system_header(ctx, buf_ptr);

            buf_ptr += size;

        }

    }

    size = buf_ptr - buffer;

    put_buffer(&ctx->pb, buffer, size);



    /* packet header */

    if (s->is_mpeg2) {

        header_len = 8;

    } else {

        header_len = 5;

    }

    payload_size = s->packet_size - (size + 6 + header_len + last);

    if (id < 0xc0) {

        startcode = PRIVATE_STREAM_1;

        payload_size -= 4;

    } else {

        startcode = 0x100 + id;

    }

    stuffing_size = payload_size - stream->buffer_ptr;

    if (stuffing_size < 0)

        stuffing_size = 0;



    put_be32(&ctx->pb, startcode);



    put_be16(&ctx->pb, payload_size + header_len);

    /* stuffing */

    for(i=0;i<stuffing_size;i++)

        put_byte(&ctx->pb, 0xff);



    if (s->is_mpeg2) {

        put_byte(&ctx->pb, 0x80); /* mpeg2 id */

        put_byte(&ctx->pb, 0x80); /* flags */

        put_byte(&ctx->pb, 0x05); /* header len (only pts is included) */

    }

    put_byte(&ctx->pb, 

             (0x02 << 4) | 

             (((timestamp >> 30) & 0x07) << 1) | 

             1);

    put_be16(&ctx->pb, (uint16_t)((((timestamp >> 15) & 0x7fff) << 1) | 1));

    put_be16(&ctx->pb, (uint16_t)((((timestamp) & 0x7fff) << 1) | 1));



    if (startcode == PRIVATE_STREAM_1) {

        put_byte(&ctx->pb, id);

        if (id >= 0x80 && id <= 0xbf) {

            /* XXX: need to check AC3 spec */

            put_byte(&ctx->pb, 1);

            put_byte(&ctx->pb, 0);

            put_byte(&ctx->pb, 2);

        }

    }



    if (last_pkt) {

        put_be32(&ctx->pb, ISO_11172_END_CODE);

    }

    /* output data */

    put_buffer(&ctx->pb, stream->buffer, payload_size - stuffing_size);

    put_flush_packet(&ctx->pb);



    /* preserve remaining data */

    len = stream->buffer_ptr - payload_size;

    if (len < 0) 

        len = 0;

    memmove(stream->buffer, stream->buffer + stream->buffer_ptr - len, len);

    stream->buffer_ptr = len;



    s->packet_number++;

    stream->packet_number++;

    stream->start_pts = -1;

}

static int audio_decode_frame(VideoState *is, uint8_t *audio_buf, double *pts_ptr)

{

    AVPacket *pkt = &is->audio_pkt;

    int n, len1, data_size;

    double pts;



    for(;;) {

        /* NOTE: the audio packet can contain several frames */

        while (is->audio_pkt_size > 0) {

            len1 = avcodec_decode_audio(&is->audio_st->codec, 

                                        (int16_t *)audio_buf, &data_size, 

                                        is->audio_pkt_data, is->audio_pkt_size);

            if (len1 < 0) {

                /* if error, we skip the frame */

                is->audio_pkt_size = 0;

                break;

            }



            is->audio_pkt_data += len1;

            is->audio_pkt_size -= len1;

            if (data_size <= 0)

                continue;

            /* if no pts, then compute it */

            pts = is->audio_clock;

            *pts_ptr = pts;

            n = 2 * is->audio_st->codec.channels;

printf("%f %d %d %d\n", is->audio_clock, is->audio_st->codec.channels, data_size, is->audio_st->codec.sample_rate);

            is->audio_clock += (double)data_size / 

                (double)(n * is->audio_st->codec.sample_rate);

#if defined(DEBUG_SYNC)

            {

                static double last_clock;

                printf("audio: delay=%0.3f clock=%0.3f pts=%0.3f\n",

                       is->audio_clock - last_clock,

                       is->audio_clock, pts);

                last_clock = is->audio_clock;

            }

#endif

            return data_size;

        }



        /* free the current packet */

        if (pkt->data)

            av_free_packet(pkt);



        if (is->paused || is->audioq.abort_request) {

            return -1;

        }



        /* read next packet */

        if (packet_queue_get(&is->audioq, pkt, 1) < 0)

            return -1;

        is->audio_pkt_data = pkt->data;

        is->audio_pkt_size = pkt->size;



        /* if update the audio clock with the pts */

        if (pkt->pts != AV_NOPTS_VALUE) {

            is->audio_clock = (double)pkt->pts / AV_TIME_BASE;

        }

    }

}

static int rtp_write_header(AVFormatContext *s1)

{

    RTPDemuxContext *s = s1->priv_data;

    int payload_type, max_packet_size, n;

    AVStream *st;



    if (s1->nb_streams != 1)

        return -1;

    st = s1->streams[0];



    payload_type = rtp_get_payload_type(st->codec);

    if (payload_type < 0)

        payload_type = RTP_PT_PRIVATE; /* private payload type */

    s->payload_type = payload_type;



    s->base_timestamp = random();

    s->timestamp = s->base_timestamp;

    s->ssrc = random();

    s->first_packet = 1;



    max_packet_size = url_fget_max_packet_size(&s1->pb);

    if (max_packet_size <= 12)

        return AVERROR_IO;

    s->max_payload_size = max_packet_size - 12;



    switch(st->codec->codec_id) {

    case CODEC_ID_MP2:

    case CODEC_ID_MP3:

        s->buf_ptr = s->buf + 4;

        s->cur_timestamp = 0;

        break;

    case CODEC_ID_MPEG1VIDEO:

        s->cur_timestamp = 0;

        break;

    case CODEC_ID_MPEG2TS:

        n = s->max_payload_size / TS_PACKET_SIZE;

        if (n < 1)

            n = 1;

        s->max_payload_size = n * TS_PACKET_SIZE;

        s->buf_ptr = s->buf;

        break;

    default:

        s->buf_ptr = s->buf;

        break;

    }



    return 0;

}

int ff_v4l2_context_dequeue_packet(V4L2Context* ctx, AVPacket* pkt)

{

    V4L2Buffer* avbuf = NULL;



    /* if we are draining, we are no longer inputing data, therefore enable a

     * timeout so we can dequeue and flag the last valid buffer.

     *

     * blocks until:

     *  1. encoded packet available

     *  2. an input buffer ready to be dequeued

     */

    avbuf = v4l2_dequeue_v4l2buf(ctx, ctx_to_m2mctx(ctx)->draining ? 200 : -1);

    if (!avbuf) {

        if (ctx->done)

            return AVERROR_EOF;



        return AVERROR(EAGAIN);

    }



    return ff_v4l2_buffer_buf_to_avpkt(pkt, avbuf);

}

static void find_best_tables(MpegEncContext * s)

{

    int i;

    int best       =-1, best_size       =9999999;

    int chroma_best=-1, best_chroma_size=9999999;



    for(i=0; i<3; i++){

        int level;

        int chroma_size=0;

        int size=0;



        if(i>0){// ;)

            size++;

            chroma_size++;

        }

        for(level=0; level<=MAX_LEVEL; level++){

            int run;

            for(run=0; run<=MAX_RUN; run++){

                int last;

                const int last_size= size + chroma_size;

                for(last=0; last<2; last++){

                    int inter_count       = s->ac_stats[0][0][level][run][last] + s->ac_stats[0][1][level][run][last];

                    int intra_luma_count  = s->ac_stats[1][0][level][run][last];

                    int intra_chroma_count= s->ac_stats[1][1][level][run][last];



                    if(s->pict_type==AV_PICTURE_TYPE_I){

                        size       += intra_luma_count  *rl_length[i  ][level][run][last];

                        chroma_size+= intra_chroma_count*rl_length[i+3][level][run][last];

                    }else{

                        size+=        intra_luma_count  *rl_length[i  ][level][run][last]

                                     +intra_chroma_count*rl_length[i+3][level][run][last]

                                     +inter_count       *rl_length[i+3][level][run][last];

                    }

                }

                if(last_size == size+chroma_size) break;

            }

        }

        if(size<best_size){

            best_size= size;

            best= i;

        }

        if(chroma_size<best_chroma_size){

            best_chroma_size= chroma_size;

            chroma_best= i;

        }

    }



//    printf("type:%d, best:%d, qp:%d, var:%d, mcvar:%d, size:%d //\n",

//           s->pict_type, best, s->qscale, s->mb_var_sum, s->mc_mb_var_sum, best_size);



    if(s->pict_type==AV_PICTURE_TYPE_P) chroma_best= best;



    memset(s->ac_stats, 0, sizeof(int)*(MAX_LEVEL+1)*(MAX_RUN+1)*2*2*2);



    s->rl_table_index       =        best;

    s->rl_chroma_table_index= chroma_best;



    if(s->pict_type != s->last_non_b_pict_type){

        s->rl_table_index= 2;

        if(s->pict_type==AV_PICTURE_TYPE_I)

            s->rl_chroma_table_index= 1;

        else

            s->rl_chroma_table_index= 2;

    }



}

matroska_parse_cluster (MatroskaDemuxContext *matroska)

{

    int res = 0;

    uint32_t id;

    uint64_t cluster_time = 0;

    uint8_t *data;

    int64_t pos;

    int size;



    av_log(matroska->ctx, AV_LOG_DEBUG,

           "parsing cluster at %"PRId64"\n", url_ftell(&matroska->ctx->pb));



    while (res == 0) {

        if (!(id = ebml_peek_id(matroska, &matroska->level_up))) {

            res = AVERROR_IO;

            break;

        } else if (matroska->level_up) {

            matroska->level_up--;

            break;

        }



        switch (id) {

            /* cluster timecode */

            case MATROSKA_ID_CLUSTERTIMECODE: {

                uint64_t num;

                if ((res = ebml_read_uint(matroska, &id, &num)) < 0)

                    break;

                cluster_time = num;

                break;

            }



                /* a group of blocks inside a cluster */

            case MATROSKA_ID_BLOCKGROUP:

                if ((res = ebml_read_master(matroska, &id)) < 0)

                    break;

                res = matroska_parse_blockgroup(matroska, cluster_time);

                break;



            case MATROSKA_ID_SIMPLEBLOCK:

                pos = url_ftell(&matroska->ctx->pb);

                res = ebml_read_binary(matroska, &id, &data, &size);

                if (res == 0)

                    res = matroska_parse_block(matroska, data, size, pos,

                                               cluster_time, -1, NULL, NULL);

                break;



            default:

                av_log(matroska->ctx, AV_LOG_INFO,

                       "Unknown entry 0x%x in cluster data\n", id);

                /* fall-through */



            case EBML_ID_VOID:

                res = ebml_read_skip(matroska);

                break;

        }



        if (matroska->level_up) {

            matroska->level_up--;

            break;

        }

    }



    return res;

}

static int http_proxy_open(URLContext *h, const char *uri, int flags)

{

    HTTPContext *s = h->priv_data;

    char hostname[1024], hoststr[1024];

    char auth[1024], pathbuf[1024], *path;

    char line[1024], lower_url[100];

    int port, ret = 0;

    HTTPAuthType cur_auth_type;

    char *authstr;



    h->is_streamed = 1;



    av_url_split(NULL, 0, auth, sizeof(auth), hostname, sizeof(hostname), &port,

                 pathbuf, sizeof(pathbuf), uri);

    ff_url_join(hoststr, sizeof(hoststr), NULL, NULL, hostname, port, NULL);

    path = pathbuf;

    if (*path == '/')

        path++;



    ff_url_join(lower_url, sizeof(lower_url), "tcp", NULL, hostname, port,

                NULL);

redo:

    ret = ffurl_open(&s->hd, lower_url, AVIO_FLAG_READ_WRITE,

                     &h->interrupt_callback, NULL);

    if (ret < 0)

        return ret;



    authstr = ff_http_auth_create_response(&s->proxy_auth_state, auth,

                                           path, "CONNECT");

    snprintf(s->buffer, sizeof(s->buffer),

             "CONNECT %s HTTP/1.1\r\n"

             "Host: %s\r\n"

             "Connection: close\r\n"

             "%s%s"

             "\r\n",

             path,

             hoststr,

             authstr ? "Proxy-" : "", authstr ? authstr : "");

    av_freep(&authstr);



    if ((ret = ffurl_write(s->hd, s->buffer, strlen(s->buffer))) < 0)

        goto fail;



    s->buf_ptr = s->buffer;

    s->buf_end = s->buffer;

    s->line_count = 0;

    s->filesize = -1;

    cur_auth_type = s->proxy_auth_state.auth_type;



    for (;;) {

        int new_loc;

        // Note: This uses buffering, potentially reading more than the

        // HTTP header. If tunneling a protocol where the server starts

        // the conversation, we might buffer part of that here, too.

        // Reading that requires using the proper ffurl_read() function

        // on this URLContext, not using the fd directly (as the tls

        // protocol does). This shouldn't be an issue for tls though,

        // since the client starts the conversation there, so there

        // is no extra data that we might buffer up here.

        if (http_get_line(s, line, sizeof(line)) < 0) {

            ret = AVERROR(EIO);

            goto fail;

        }



        av_dlog(h, "header='%s'\n", line);



        ret = process_line(h, line, s->line_count, &new_loc);

        if (ret < 0)

            goto fail;

        if (ret == 0)

            break;

        s->line_count++;

    }

    if (s->http_code == 407 && cur_auth_type == HTTP_AUTH_NONE &&

        s->proxy_auth_state.auth_type != HTTP_AUTH_NONE) {

        ffurl_close(s->hd);

        s->hd = NULL;

        goto redo;

    }



    if (s->http_code < 400)

        return 0;

    ret = AVERROR(EIO);



fail:

    http_proxy_close(h);

    return ret;

}

