static int vc1_decode_frame(AVCodecContext *avctx,

                            void *data, int *data_size,

                            const uint8_t *buf, int buf_size)

{

    VC1Context *v = avctx->priv_data;

    MpegEncContext *s = &v->s;

    AVFrame *pict = data;

    uint8_t *buf2 = NULL;



    /* no supplementary picture */

    if (buf_size == 0) {

        /* special case for last picture */

        if (s->low_delay==0 && s->next_picture_ptr) {

            *pict= *(AVFrame*)s->next_picture_ptr;

            s->next_picture_ptr= NULL;



            *data_size = sizeof(AVFrame);

        }



        return 0;

    }



    /* We need to set current_picture_ptr before reading the header,

     * otherwise we cannot store anything in there. */

    if(s->current_picture_ptr==NULL || s->current_picture_ptr->data[0]){

        int i= ff_find_unused_picture(s, 0);

        s->current_picture_ptr= &s->picture[i];

    }



    //for advanced profile we may need to parse and unescape data

    if (avctx->codec_id == CODEC_ID_VC1) {

        int buf_size2 = 0;

        buf2 = av_mallocz(buf_size + FF_INPUT_BUFFER_PADDING_SIZE);



        if(IS_MARKER(AV_RB32(buf))){ /* frame starts with marker and needs to be parsed */

            const uint8_t *start, *end, *next;

            int size;



            next = buf;

            for(start = buf, end = buf + buf_size; next < end; start = next){

                next = find_next_marker(start + 4, end);

                size = next - start - 4;

                if(size <= 0) continue;

                switch(AV_RB32(start)){

                case VC1_CODE_FRAME:

                    buf_size2 = vc1_unescape_buffer(start + 4, size, buf2);

                    break;

                case VC1_CODE_ENTRYPOINT: /* it should be before frame data */

                    buf_size2 = vc1_unescape_buffer(start + 4, size, buf2);

                    init_get_bits(&s->gb, buf2, buf_size2*8);

                    decode_entry_point(avctx, &s->gb);

                    break;

                case VC1_CODE_SLICE:

                    av_log(avctx, AV_LOG_ERROR, "Sliced decoding is not implemented (yet)\n");


                    return -1;

                }

            }

        }else if(v->interlace && ((buf[0] & 0xC0) == 0xC0)){ /* WVC1 interlaced stores both fields divided by marker */

            const uint8_t *divider;



            divider = find_next_marker(buf, buf + buf_size);

            if((divider == (buf + buf_size)) || AV_RB32(divider) != VC1_CODE_FIELD){

                av_log(avctx, AV_LOG_ERROR, "Error in WVC1 interlaced frame\n");


                return -1;

            }



            buf_size2 = vc1_unescape_buffer(buf, divider - buf, buf2);

            // TODO

            av_free(buf2);return -1;

        }else{

            buf_size2 = vc1_unescape_buffer(buf, buf_size, buf2);

        }

        init_get_bits(&s->gb, buf2, buf_size2*8);

    } else

        init_get_bits(&s->gb, buf, buf_size*8);

    // do parse frame header

    if(v->profile < PROFILE_ADVANCED) {

        if(vc1_parse_frame_header(v, &s->gb) == -1) {


            return -1;

        }

    } else {

        if(vc1_parse_frame_header_adv(v, &s->gb) == -1) {


            return -1;

        }

    }



    if(s->pict_type != FF_I_TYPE && !v->res_rtm_flag){


        return -1;

    }



    // for hurry_up==5

    s->current_picture.pict_type= s->pict_type;

    s->current_picture.key_frame= s->pict_type == FF_I_TYPE;



    /* skip B-frames if we don't have reference frames */

    if(s->last_picture_ptr==NULL && (s->pict_type==FF_B_TYPE || s->dropable)){


        return -1;//buf_size;

    }

    /* skip b frames if we are in a hurry */

    if(avctx->hurry_up && s->pict_type==FF_B_TYPE) return -1;//buf_size;

    if(   (avctx->skip_frame >= AVDISCARD_NONREF && s->pict_type==FF_B_TYPE)

       || (avctx->skip_frame >= AVDISCARD_NONKEY && s->pict_type!=FF_I_TYPE)

       ||  avctx->skip_frame >= AVDISCARD_ALL) {


        return buf_size;

    }

    /* skip everything if we are in a hurry>=5 */

    if(avctx->hurry_up>=5) {


        return -1;//buf_size;

    }



    if(s->next_p_frame_damaged){

        if(s->pict_type==FF_B_TYPE)

            return buf_size;

        else

            s->next_p_frame_damaged=0;

    }



    if(MPV_frame_start(s, avctx) < 0) {


        return -1;

    }



    s->me.qpel_put= s->dsp.put_qpel_pixels_tab;

    s->me.qpel_avg= s->dsp.avg_qpel_pixels_tab;



    ff_er_frame_start(s);



    v->bits = buf_size * 8;

    vc1_decode_blocks(v);

//av_log(s->avctx, AV_LOG_INFO, "Consumed %i/%i bits\n", get_bits_count(&s->gb), buf_size*8);

//  if(get_bits_count(&s->gb) > buf_size * 8)

//      return -1;

    ff_er_frame_end(s);



    MPV_frame_end(s);



assert(s->current_picture.pict_type == s->current_picture_ptr->pict_type);

assert(s->current_picture.pict_type == s->pict_type);

    if (s->pict_type == FF_B_TYPE || s->low_delay) {

        *pict= *(AVFrame*)s->current_picture_ptr;

    } else if (s->last_picture_ptr != NULL) {

        *pict= *(AVFrame*)s->last_picture_ptr;

    }



    if(s->last_picture_ptr || s->low_delay){

        *data_size = sizeof(AVFrame);

        ff_print_debug_info(s, pict);

    }



    /* Return the Picture timestamp as the frame number */

    /* we subtract 1 because it is added on utils.c     */

    avctx->frame_number = s->picture_number - 1;




    return buf_size;

}

static inline int decode_mb(MDECContext *a, DCTELEM block[6][64]){

    int i;

    const int block_index[6]= {5,4,0,1,2,3};



    a->dsp.clear_blocks(block[0]);



    for(i=0; i<6; i++){

        if( mdec_decode_block_intra(a, block[ block_index[i] ], block_index[i]) < 0)

            return -1;

    }

    return 0;

}

static int decompress_i(AVCodecContext *avctx, uint32_t *dst, int linesize)

{

    SCPRContext *s = avctx->priv_data;

    GetByteContext *gb = &s->gb;

    int cx = 0, cx1 = 0, k = 0, clr = 0;

    int run, r, g, b, off, y = 0, x = 0, z, ret;

    unsigned backstep = linesize - avctx->width;

    const int cxshift = s->cxshift;

    unsigned lx, ly, ptype;



    reinit_tables(s);

    bytestream2_skip(gb, 2);

    init_rangecoder(&s->rc, gb);



    while (k < avctx->width + 1) {

        ret = decode_unit(s, &s->pixel_model[0][cx + cx1], 400, &r);

        if (ret < 0)

            return ret;



        cx1 = (cx << 6) & 0xFC0;

        cx = r >> cxshift;

        ret = decode_unit(s, &s->pixel_model[1][cx + cx1], 400, &g);

        if (ret < 0)

            return ret;



        cx1 = (cx << 6) & 0xFC0;

        cx = g >> cxshift;

        ret = decode_unit(s, &s->pixel_model[2][cx + cx1], 400, &b);

        if (ret < 0)

            return ret;



        cx1 = (cx << 6) & 0xFC0;

        cx = b >> cxshift;



        ret = decode_value(s, s->run_model[0], 256, 400, &run);

        if (ret < 0)

            return ret;



        clr = (b << 16) + (g << 8) + r;

        k += run;

        while (run-- > 0) {

            if (y >= avctx->height)

                return AVERROR_INVALIDDATA;



            dst[y * linesize + x] = clr;

            lx = x;

            ly = y;

            x++;

            if (x >= avctx->width) {

                x = 0;

                y++;

            }

        }

    }

    off = -linesize - 1;

    ptype = 0;



    while (x < avctx->width && y < avctx->height) {

        ret = decode_value(s, s->op_model[ptype], 6, 1000, &ptype);

        if (ret < 0)

            return ret;

        if (ptype == 0) {

            ret = decode_unit(s, &s->pixel_model[0][cx + cx1], 400, &r);

            if (ret < 0)

                return ret;



            cx1 = (cx << 6) & 0xFC0;

            cx = r >> cxshift;

            ret = decode_unit(s, &s->pixel_model[1][cx + cx1], 400, &g);

            if (ret < 0)

                return ret;



            cx1 = (cx << 6) & 0xFC0;

            cx = g >> cxshift;

            ret = decode_unit(s, &s->pixel_model[2][cx + cx1], 400, &b);

            if (ret < 0)

                return ret;



            clr = (b << 16) + (g << 8) + r;

        }

        if (ptype > 5)

            return AVERROR_INVALIDDATA;

        ret = decode_value(s, s->run_model[ptype], 256, 400, &run);

        if (ret < 0)

            return ret;



        switch (ptype) {

        case 0:

            while (run-- > 0) {

                if (y >= avctx->height)

                    return AVERROR_INVALIDDATA;



                dst[y * linesize + x] = clr;

                lx = x;

                ly = y;

                x++;

                if (x >= avctx->width) {

                    x = 0;

                    y++;

                }

            }

            break;

        case 1:

            while (run-- > 0) {

                if (y >= avctx->height)

                    return AVERROR_INVALIDDATA;



                dst[y * linesize + x] = dst[ly * linesize + lx];

                lx = x;

                ly = y;

                x++;

                if (x >= avctx->width) {

                    x = 0;

                    y++;

                }

            }

            clr = dst[ly * linesize + lx];

            break;

        case 2:

            while (run-- > 0) {

                if (y < 1 || y >= avctx->height)

                    return AVERROR_INVALIDDATA;



                clr = dst[y * linesize + x + off + 1];

                dst[y * linesize + x] = clr;

                lx = x;

                ly = y;

                x++;

                if (x >= avctx->width) {

                    x = 0;

                    y++;

                }

            }

            break;

        case 4:

            while (run-- > 0) {

                uint8_t *odst = (uint8_t *)dst;



                if (y < 1 || y >= avctx->height ||

                    (y == 1 && x == 0))

                    return AVERROR_INVALIDDATA;



                if (x == 0) {

                    z = backstep;

                } else {

                    z = 0;

                }



                r = odst[(ly * linesize + lx) * 4] +

                    odst[((y * linesize + x) + off - z) * 4 + 4] -

                    odst[((y * linesize + x) + off - z) * 4];

                g = odst[(ly * linesize + lx) * 4 + 1] +

                    odst[((y * linesize + x) + off - z) * 4 + 5] -

                    odst[((y * linesize + x) + off - z) * 4 + 1];

                b = odst[(ly * linesize + lx) * 4 + 2] +

                    odst[((y * linesize + x) + off - z) * 4 + 6] -

                    odst[((y * linesize + x) + off - z) * 4 + 2];

                clr = ((b & 0xFF) << 16) + ((g & 0xFF) << 8) + (r & 0xFF);

                dst[y * linesize + x] = clr;

                lx = x;

                ly = y;

                x++;

                if (x >= avctx->width) {

                    x = 0;

                    y++;

                }

            }

            break;

        case 5:

            while (run-- > 0) {

                if (y < 1 || y >= avctx->height ||

                    (y == 1 && x == 0))

                    return AVERROR_INVALIDDATA;



                if (x == 0) {

                    z = backstep;

                } else {

                    z = 0;

                }



                clr = dst[y * linesize + x + off - z];

                dst[y * linesize + x] = clr;

                lx = x;

                ly = y;

                x++;

                if (x >= avctx->width) {

                    x = 0;

                    y++;

                }

            }

            break;

        }



        if (avctx->bits_per_coded_sample == 16) {

            cx1 = (clr & 0x3F00) >> 2;

            cx = (clr & 0xFFFFFF) >> 16;

        } else {

            cx1 = (clr & 0xFC00) >> 4;

            cx = (clr & 0xFFFFFF) >> 18;

        }

    }



    return 0;

}

static int scale_vector(int16_t *vector, int length)

{

    int bits, max = 0;

    int64_t scale;

    int i;





    for (i = 0; i < length; i++)

        max = FFMAX(max, FFABS(vector[i]));



    max   = FFMIN(max, 0x7FFF);

    bits  = normalize_bits(max, 15);

    scale = (bits == 15) ? 0x7FFF : (1 << bits);



    for (i = 0; i < length; i++)

        vector[i] = av_clipl_int32(vector[i] * scale << 1) >> 4;



    return bits - 3;

}

static int fileTest(uint8_t *ref[4], int refStride[4], int w, int h, FILE *fp,

                    enum AVPixelFormat srcFormat_in,

                    enum AVPixelFormat dstFormat_in)

{

    char buf[256];



    while (fgets(buf, sizeof(buf), fp)) {

        struct Results r;

        enum AVPixelFormat srcFormat;

        char srcStr[12];

        int srcW, srcH;

        enum AVPixelFormat dstFormat;

        char dstStr[12];

        int dstW, dstH;

        int flags;

        int ret;



        ret = sscanf(buf,

                     " %12s %dx%d -> %12s %dx%d flags=%d CRC=%x"

                     " SSD=%"SCNu64 ", %"SCNu64 ", %"SCNu64 ", %"SCNu64 "\n",

                     srcStr, &srcW, &srcH, dstStr, &dstW, &dstH,

                     &flags, &r.crc, &r.ssdY, &r.ssdU, &r.ssdV, &r.ssdA);

        if (ret != 12) {

            srcStr[0] = dstStr[0] = 0;

            ret       = sscanf(buf, "%12s -> %12s\n", srcStr, dstStr);

        }



        srcFormat = av_get_pix_fmt(srcStr);

        dstFormat = av_get_pix_fmt(dstStr);



        if (srcFormat == AV_PIX_FMT_NONE || dstFormat == AV_PIX_FMT_NONE ||

            srcW > 8192U || srcH > 8192U || dstW > 8192U || dstH > 8192U) {

            fprintf(stderr, "malformed input file\n");

            return -1;

        }

        if ((srcFormat_in != AV_PIX_FMT_NONE && srcFormat_in != srcFormat) ||

            (dstFormat_in != AV_PIX_FMT_NONE && dstFormat_in != dstFormat))

            continue;

        if (ret != 12) {

            printf("%s", buf);

            continue;

        }



        doTest(ref, refStride, w, h,

               srcFormat, dstFormat,

               srcW, srcH, dstW, dstH, flags,

               &r);

    }



    return 0;

}

static int lut2_config_output(AVFilterLink *outlink)

{

    AVFilterContext *ctx = outlink->src;

    LUT2Context *s = ctx->priv;

    AVFilterLink *srcx = ctx->inputs[0];

    AVFilterLink *srcy = ctx->inputs[1];

    FFFrameSyncIn *in;

    int ret;



    if (srcx->format != srcy->format) {

        av_log(ctx, AV_LOG_ERROR, "inputs must be of same pixel format\n");

        return AVERROR(EINVAL);

    }

    if (srcx->w                       != srcy->w ||

        srcx->h                       != srcy->h ||

        srcx->sample_aspect_ratio.num != srcy->sample_aspect_ratio.num ||

        srcx->sample_aspect_ratio.den != srcy->sample_aspect_ratio.den) {

        av_log(ctx, AV_LOG_ERROR, "First input link %s parameters "

               "(size %dx%d, SAR %d:%d) do not match the corresponding "

               "second input link %s parameters (%dx%d, SAR %d:%d)\n",

               ctx->input_pads[0].name, srcx->w, srcx->h,

               srcx->sample_aspect_ratio.num,

               srcx->sample_aspect_ratio.den,

               ctx->input_pads[1].name,

               srcy->w, srcy->h,

               srcy->sample_aspect_ratio.num,

               srcy->sample_aspect_ratio.den);

        return AVERROR(EINVAL);

    }



    outlink->w = srcx->w;

    outlink->h = srcx->h;

    outlink->time_base = srcx->time_base;

    outlink->sample_aspect_ratio = srcx->sample_aspect_ratio;

    outlink->frame_rate = srcx->frame_rate;



    if ((ret = ff_framesync2_init(&s->fs, ctx, 2)) < 0)

        return ret;



    in = s->fs.in;

    in[0].time_base = srcx->time_base;

    in[1].time_base = srcy->time_base;

    in[0].sync   = 1;

    in[0].before = EXT_STOP;

    in[0].after  = EXT_INFINITY;

    in[1].sync   = 1;

    in[1].before = EXT_STOP;

    in[1].after  = EXT_INFINITY;

    s->fs.opaque   = s;

    s->fs.on_event = process_frame;



    if ((ret = config_output(outlink)) < 0)

        return ret;



    return ff_framesync2_configure(&s->fs);

}

static inline void unpack_coeffs(SnowContext *s, SubBand *b, SubBand * parent, int orientation){

    const int w= b->width;

    const int h= b->height;

    int x,y;



    if(1){

        int run;

        x_and_coeff *xc= b->x_coeff;

        x_and_coeff *prev_xc= NULL;

        x_and_coeff *prev2_xc= xc;

        x_and_coeff *parent_xc= parent ? parent->x_coeff : NULL;

        x_and_coeff *prev_parent_xc= parent_xc;



        run= get_symbol2(&s->c, b->state[1], 3);

        for(y=0; y<h; y++){

            int v=0;

            int lt=0, t=0, rt=0;



            if(y && prev_xc->x == 0){

                rt= prev_xc->coeff;

            }

            for(x=0; x<w; x++){

                int p=0;

                const int l= v;



                lt= t; t= rt;



                if(y){

                    if(prev_xc->x <= x)

                        prev_xc++;

                    if(prev_xc->x == x + 1)

                        rt= prev_xc->coeff;

                    else

                        rt=0;

                }

                if(parent_xc){

                    if(x>>1 > parent_xc->x){

                        parent_xc++;

                    }

                    if(x>>1 == parent_xc->x){

                        p= parent_xc->coeff;

                    }

                }

                if(/*ll|*/l|lt|t|rt|p){

                    int context= av_log2(/*ABS(ll) + */3*(l>>1) + (lt>>1) + (t&~1) + (rt>>1) + (p>>1));



                    v=get_rac(&s->c, &b->state[0][context]);

                    if(v){

                        v= 2*(get_symbol2(&s->c, b->state[context + 2], context-4) + 1);

                        v+=get_rac(&s->c, &b->state[0][16 + 1 + 3 + quant3bA[l&0xFF] + 3*quant3bA[t&0xFF]]);



                        xc->x=x;

                        (xc++)->coeff= v;

                    }

                }else{

                    if(!run){

                        run= get_symbol2(&s->c, b->state[1], 3);

                        v= 2*(get_symbol2(&s->c, b->state[0 + 2], 0-4) + 1);

                        v+=get_rac(&s->c, &b->state[0][16 + 1 + 3]);



                        xc->x=x;

                        (xc++)->coeff= v;

                    }else{

                        int max_run;

                        run--;

                        v=0;



                        if(y) max_run= FFMIN(run, prev_xc->x - x - 2);

                        else  max_run= FFMIN(run, w-x-1);

                        if(parent_xc)

                            max_run= FFMIN(max_run, 2*parent_xc->x - x - 1);

                        x+= max_run;

                        run-= max_run;

                    }

                }

            }

            (xc++)->x= w+1; //end marker

            prev_xc= prev2_xc;

            prev2_xc= xc;



            if(parent_xc){

                if(y&1){

                    while(parent_xc->x != parent->width+1)

                        parent_xc++;

                    parent_xc++;

                    prev_parent_xc= parent_xc;

                }else{

                    parent_xc= prev_parent_xc;

                }

            }

        }



        (xc++)->x= w+1; //end marker

    }

}

static int decode_frame(AVCodecContext *avctx, void *data, int *got_frame,

                        AVPacket *avpkt)

{

    const uint8_t *buf = avpkt->data;

    int buf_size       = avpkt->size;

    VmncContext * const c = avctx->priv_data;

    GetByteContext *gb = &c->gb;

    uint8_t *outptr;

    int dx, dy, w, h, depth, enc, chunks, res, size_left, ret;



    if ((ret = ff_reget_buffer(avctx, c->pic)) < 0) {

        av_log(avctx, AV_LOG_ERROR, "reget_buffer() failed\n");

        return ret;

    }



    bytestream2_init(gb, buf, buf_size);



    c->pic->key_frame = 0;

    c->pic->pict_type = AV_PICTURE_TYPE_P;



    // restore screen after cursor

    if (c->screendta) {

        int i;

        w = c->cur_w;

        if (c->width < c->cur_x + w)

            w = c->width - c->cur_x;

        h = c->cur_h;

        if (c->height < c->cur_y + h)

            h = c->height - c->cur_y;

        dx = c->cur_x;

        if (dx < 0) {

            w += dx;

            dx = 0;

        }

        dy = c->cur_y;

        if (dy < 0) {

            h += dy;

            dy = 0;

        }

        if ((w > 0) && (h > 0)) {

            outptr = c->pic->data[0] + dx * c->bpp2 + dy * c->pic->linesize[0];

            for (i = 0; i < h; i++) {

                memcpy(outptr, c->screendta + i * c->cur_w * c->bpp2,

                       w * c->bpp2);

                outptr += c->pic->linesize[0];

            }

        }

    }

    bytestream2_skip(gb, 2);

    chunks = bytestream2_get_be16(gb);

    while (chunks--) {

        dx  = bytestream2_get_be16(gb);

        dy  = bytestream2_get_be16(gb);

        w   = bytestream2_get_be16(gb);

        h   = bytestream2_get_be16(gb);

        enc = bytestream2_get_be32(gb);

        outptr = c->pic->data[0] + dx * c->bpp2 + dy * c->pic->linesize[0];

        size_left = bytestream2_get_bytes_left(gb);

        switch (enc) {

        case MAGIC_WMVd: // cursor

            if (size_left < 2 + w * h * c->bpp2 * 2) {

                av_log(avctx, AV_LOG_ERROR,

                       "Premature end of data! (need %i got %i)\n",

                       2 + w * h * c->bpp2 * 2, size_left);

                return AVERROR_INVALIDDATA;

            }

            bytestream2_skip(gb, 2);

            c->cur_w  = w;

            c->cur_h  = h;

            c->cur_hx = dx;

            c->cur_hy = dy;

            if ((c->cur_hx > c->cur_w) || (c->cur_hy > c->cur_h)) {

                av_log(avctx, AV_LOG_ERROR,

                       "Cursor hot spot is not in image: "

                       "%ix%i of %ix%i cursor size\n",

                       c->cur_hx, c->cur_hy, c->cur_w, c->cur_h);

                c->cur_hx = c->cur_hy = 0;

            }

            if (c->cur_w * c->cur_h >= INT_MAX / c->bpp2) {

                reset_buffers(c);

                return AVERROR(EINVAL);

            } else {

                int screen_size = c->cur_w * c->cur_h * c->bpp2;

                if ((ret = av_reallocp(&c->curbits, screen_size)) < 0 ||

                    (ret = av_reallocp(&c->curmask, screen_size)) < 0 ||

                    (ret = av_reallocp(&c->screendta, screen_size)) < 0) {

                    reset_buffers(c);

                    return ret;

                }

            }

            load_cursor(c);

            break;

        case MAGIC_WMVe: // unknown

            bytestream2_skip(gb, 2);

            break;

        case MAGIC_WMVf: // update cursor position

            c->cur_x = dx - c->cur_hx;

            c->cur_y = dy - c->cur_hy;

            break;

        case MAGIC_WMVg: // unknown

            bytestream2_skip(gb, 10);

            break;

        case MAGIC_WMVh: // unknown

            bytestream2_skip(gb, 4);

            break;

        case MAGIC_WMVi: // ServerInitialization struct

            c->pic->key_frame = 1;

            c->pic->pict_type = AV_PICTURE_TYPE_I;

            depth = bytestream2_get_byte(gb);

            if (depth != c->bpp) {

                av_log(avctx, AV_LOG_INFO,

                       "Depth mismatch. Container %i bpp, "

                       "Frame data: %i bpp\n",

                       c->bpp, depth);

            }

            bytestream2_skip(gb, 1);

            c->bigendian = bytestream2_get_byte(gb);

            if (c->bigendian & (~1)) {

                av_log(avctx, AV_LOG_INFO,

                       "Invalid header: bigendian flag = %i\n", c->bigendian);

                return AVERROR_INVALIDDATA;

            }

            //skip the rest of pixel format data

            bytestream2_skip(gb, 13);

            break;

        case MAGIC_WMVj: // unknown

            bytestream2_skip(gb, 2);

            break;

        case 0x00000000: // raw rectangle data

            if ((dx + w > c->width) || (dy + h > c->height)) {

                av_log(avctx, AV_LOG_ERROR,

                       "Incorrect frame size: %ix%i+%ix%i of %ix%i\n",

                       w, h, dx, dy, c->width, c->height);

                return AVERROR_INVALIDDATA;

            }

            if (size_left < w * h * c->bpp2) {

                av_log(avctx, AV_LOG_ERROR,

                       "Premature end of data! (need %i got %i)\n",

                       w * h * c->bpp2, size_left);

                return AVERROR_INVALIDDATA;

            }

            paint_raw(outptr, w, h, gb, c->bpp2, c->bigendian,

                      c->pic->linesize[0]);

            break;

        case 0x00000005: // HexTile encoded rectangle

            if ((dx + w > c->width) || (dy + h > c->height)) {

                av_log(avctx, AV_LOG_ERROR,

                       "Incorrect frame size: %ix%i+%ix%i of %ix%i\n",

                       w, h, dx, dy, c->width, c->height);

                return AVERROR_INVALIDDATA;

            }

            res = decode_hextile(c, outptr, gb, w, h, c->pic->linesize[0]);

            if (res < 0)

                return res;

            break;

        default:

            av_log(avctx, AV_LOG_ERROR, "Unsupported block type 0x%08X\n", enc);

            chunks = 0; // leave chunks decoding loop

        }

    }

    if (c->screendta) {

        int i;

        // save screen data before painting cursor

        w = c->cur_w;

        if (c->width < c->cur_x + w)

            w = c->width - c->cur_x;

        h = c->cur_h;

        if (c->height < c->cur_y + h)

            h = c->height - c->cur_y;

        dx = c->cur_x;

        if (dx < 0) {

            w += dx;

            dx = 0;

        }

        dy = c->cur_y;

        if (dy < 0) {

            h += dy;

            dy = 0;

        }

        if ((w > 0) && (h > 0)) {

            outptr = c->pic->data[0] + dx * c->bpp2 + dy * c->pic->linesize[0];

            for (i = 0; i < h; i++) {

                memcpy(c->screendta + i * c->cur_w * c->bpp2, outptr,

                       w * c->bpp2);

                outptr += c->pic->linesize[0];

            }

            outptr = c->pic->data[0];

            put_cursor(outptr, c->pic->linesize[0], c, c->cur_x, c->cur_y);

        }

    }

    *got_frame = 1;

    if ((ret = av_frame_ref(data, c->pic)) < 0)

        return ret;



    /* always report that the buffer was completely consumed */

    return buf_size;

}

void ff_fft_calc_sse(FFTContext *s, FFTComplex *z)

{

    int ln = s->nbits;

    long i, j;

    long nblocks, nloops;

    FFTComplex *p, *cptr;



    asm volatile(

        "movaps %0, %%xmm4 \n\t"

        "movaps %1, %%xmm5 \n\t"

        ::"m"(*p1p1m1m1),

          "m"(*(s->inverse ? p1p1m1p1 : p1p1p1m1))

    );



    i = 8 << ln;

    asm volatile(

        "1: \n\t"

        "sub $32, %0 \n\t"

        /* do the pass 0 butterfly */

        "movaps   (%0,%1), %%xmm0 \n\t"

        "movaps    %%xmm0, %%xmm1 \n\t"

        "shufps     $0x4E, %%xmm0, %%xmm0 \n\t"

        "xorps     %%xmm4, %%xmm1 \n\t"

        "addps     %%xmm1, %%xmm0 \n\t"

        "movaps 16(%0,%1), %%xmm2 \n\t"

        "movaps    %%xmm2, %%xmm3 \n\t"

        "shufps     $0x4E, %%xmm2, %%xmm2 \n\t"

        "xorps     %%xmm4, %%xmm3 \n\t"

        "addps     %%xmm3, %%xmm2 \n\t"

        /* multiply third by -i */

        /* by toggling the sign bit */

        "shufps     $0xB4, %%xmm2, %%xmm2 \n\t"

        "xorps     %%xmm5, %%xmm2 \n\t"

        /* do the pass 1 butterfly */

        "movaps    %%xmm0, %%xmm1 \n\t"

        "addps     %%xmm2, %%xmm0 \n\t"

        "subps     %%xmm2, %%xmm1 \n\t"

        "movaps    %%xmm0,   (%0,%1) \n\t"

        "movaps    %%xmm1, 16(%0,%1) \n\t"

        "jg 1b \n\t"

        :"+r"(i)

        :"r"(z)

    );

    /* pass 2 .. ln-1 */



    nblocks = 1 << (ln-3);

    nloops = 1 << 2;

    cptr = s->exptab1;

    do {

        p = z;

        j = nblocks;

        do {

            i = nloops*8;

            asm volatile(

                "1: \n\t"

                "sub $16, %0 \n\t"

                "movaps    (%2,%0), %%xmm1 \n\t"

                "movaps    (%1,%0), %%xmm0 \n\t"

                "movaps     %%xmm1, %%xmm2 \n\t"

                "shufps      $0xA0, %%xmm1, %%xmm1 \n\t"

                "shufps      $0xF5, %%xmm2, %%xmm2 \n\t"

                "mulps   (%3,%0,2), %%xmm1 \n\t" //  cre*re cim*re

                "mulps 16(%3,%0,2), %%xmm2 \n\t" // -cim*im cre*im

                "addps      %%xmm2, %%xmm1 \n\t"

                "movaps     %%xmm0, %%xmm3 \n\t"

                "addps      %%xmm1, %%xmm0 \n\t"

                "subps      %%xmm1, %%xmm3 \n\t"

                "movaps     %%xmm0, (%1,%0) \n\t"

                "movaps     %%xmm3, (%2,%0) \n\t"

                "jg 1b \n\t"

                :"+r"(i)

                :"r"(p), "r"(p + nloops), "r"(cptr)

            );

            p += nloops*2;

        } while (--j);

        cptr += nloops*2;

        nblocks >>= 1;

        nloops <<= 1;

    } while (nblocks != 0);

}

