static void floor_encode(vorbis_enc_context *venc, vorbis_enc_floor *fc,

                         PutBitContext *pb, uint16_t *posts,

                         float *floor, int samples)

{

    int range = 255 / fc->multiplier + 1;

    int coded[MAX_FLOOR_VALUES]; // first 2 values are unused

    int i, counter;



    put_bits(pb, 1, 1); // non zero

    put_bits(pb, ilog(range - 1), posts[0]);

    put_bits(pb, ilog(range - 1), posts[1]);

    coded[0] = coded[1] = 1;



    for (i = 2; i < fc->values; i++) {

        int predicted = render_point(fc->list[fc->list[i].low].x,

                                     posts[fc->list[i].low],

                                     fc->list[fc->list[i].high].x,

                                     posts[fc->list[i].high],

                                     fc->list[i].x);

        int highroom = range - predicted;

        int lowroom = predicted;

        int room = FFMIN(highroom, lowroom);

        if (predicted == posts[i]) {

            coded[i] = 0; // must be used later as flag!

            continue;

        } else {

            if (!coded[fc->list[i].low ])

                coded[fc->list[i].low ] = -1;

            if (!coded[fc->list[i].high])

                coded[fc->list[i].high] = -1;

        }

        if (posts[i] > predicted) {

            if (posts[i] - predicted > room)

                coded[i] = posts[i] - predicted + lowroom;

            else

                coded[i] = (posts[i] - predicted) << 1;

        } else {

            if (predicted - posts[i] > room)

                coded[i] = predicted - posts[i] + highroom - 1;

            else

                coded[i] = ((predicted - posts[i]) << 1) - 1;

        }

    }



    counter = 2;

    for (i = 0; i < fc->partitions; i++) {

        vorbis_enc_floor_class * c = &fc->classes[fc->partition_to_class[i]];

        int k, cval = 0, csub = 1<<c->subclass;

        if (c->subclass) {

            vorbis_enc_codebook * book = &venc->codebooks[c->masterbook];

            int cshift = 0;

            for (k = 0; k < c->dim; k++) {

                int l;

                for (l = 0; l < csub; l++) {

                    int maxval = 1;

                    if (c->books[l] != -1)

                        maxval = venc->codebooks[c->books[l]].nentries;

                    // coded could be -1, but this still works, cause that is 0

                    if (coded[counter + k] < maxval)

                        break;

                }

                assert(l != csub);

                cval   |= l << cshift;

                cshift += c->subclass;

            }

            put_codeword(pb, book, cval);

        }

        for (k = 0; k < c->dim; k++) {

            int book  = c->books[cval & (csub-1)];

            int entry = coded[counter++];

            cval >>= c->subclass;

            if (book == -1)

                continue;

            if (entry == -1)

                entry = 0;

            put_codeword(pb, &venc->codebooks[book], entry);

        }

    }



    ff_vorbis_floor1_render_list(fc->list, fc->values, posts, coded,

                                 fc->multiplier, floor, samples);

}

static void guess_mv(MpegEncContext *s){

    uint8_t fixed[s->mb_stride * s->mb_height];

#define MV_FROZEN    3

#define MV_CHANGED   2

#define MV_UNCHANGED 1

    const int mb_stride = s->mb_stride;

    const int mb_width = s->mb_width;

    const int mb_height= s->mb_height;

    int i, depth, num_avail;

    int mb_x, mb_y, mot_step, mot_stride;



    set_mv_strides(s, &mot_step, &mot_stride);



    num_avail=0;

    for(i=0; i<s->mb_num; i++){

        const int mb_xy= s->mb_index2xy[ i ];

        int f=0;

        int error= s->error_status_table[mb_xy];



        if(IS_INTRA(s->current_picture.mb_type[mb_xy])) f=MV_FROZEN; //intra //FIXME check

        if(!(error&MV_ERROR)) f=MV_FROZEN;           //inter with undamaged MV



        fixed[mb_xy]= f;

        if(f==MV_FROZEN)

            num_avail++;

    }



    if((!(s->avctx->error_concealment&FF_EC_GUESS_MVS)) || num_avail <= mb_width/2){

        for(mb_y=0; mb_y<s->mb_height; mb_y++){

            for(mb_x=0; mb_x<s->mb_width; mb_x++){

                const int mb_xy= mb_x + mb_y*s->mb_stride;



                if(IS_INTRA(s->current_picture.mb_type[mb_xy]))  continue;

                if(!(s->error_status_table[mb_xy]&MV_ERROR)) continue;



                s->mv_dir = s->last_picture.data[0] ? MV_DIR_FORWARD : MV_DIR_BACKWARD;

                s->mb_intra=0;

                s->mv_type = MV_TYPE_16X16;

                s->mb_skipped=0;



                s->dsp.clear_blocks(s->block[0]);



                s->mb_x= mb_x;

                s->mb_y= mb_y;

                s->mv[0][0][0]= 0;

                s->mv[0][0][1]= 0;

                decode_mb(s, 0);

            }

        }

        return;

    }



    for(depth=0;; depth++){

        int changed, pass, none_left;



        none_left=1;

        changed=1;

        for(pass=0; (changed || pass<2) && pass<10; pass++){

            int mb_x, mb_y;

int score_sum=0;



            changed=0;

            for(mb_y=0; mb_y<s->mb_height; mb_y++){

                for(mb_x=0; mb_x<s->mb_width; mb_x++){

                    const int mb_xy= mb_x + mb_y*s->mb_stride;

                    int mv_predictor[8][2]={{0}};

                    int ref[8]={0};

                    int pred_count=0;

                    int j;

                    int best_score=256*256*256*64;

                    int best_pred=0;

                    const int mot_index= (mb_x + mb_y*mot_stride) * mot_step;

                    int prev_x, prev_y, prev_ref;



                    if((mb_x^mb_y^pass)&1) continue;



                    if(fixed[mb_xy]==MV_FROZEN) continue;

                    assert(!IS_INTRA(s->current_picture.mb_type[mb_xy]));

                    assert(s->last_picture_ptr && s->last_picture_ptr->data[0]);



                    j=0;

                    if(mb_x>0           && fixed[mb_xy-1        ]==MV_FROZEN) j=1;

                    if(mb_x+1<mb_width  && fixed[mb_xy+1        ]==MV_FROZEN) j=1;

                    if(mb_y>0           && fixed[mb_xy-mb_stride]==MV_FROZEN) j=1;

                    if(mb_y+1<mb_height && fixed[mb_xy+mb_stride]==MV_FROZEN) j=1;

                    if(j==0) continue;



                    j=0;

                    if(mb_x>0           && fixed[mb_xy-1        ]==MV_CHANGED) j=1;

                    if(mb_x+1<mb_width  && fixed[mb_xy+1        ]==MV_CHANGED) j=1;

                    if(mb_y>0           && fixed[mb_xy-mb_stride]==MV_CHANGED) j=1;

                    if(mb_y+1<mb_height && fixed[mb_xy+mb_stride]==MV_CHANGED) j=1;

                    if(j==0 && pass>1) continue;



                    none_left=0;



                    if(mb_x>0 && fixed[mb_xy-1]){

                        mv_predictor[pred_count][0]= s->current_picture.motion_val[0][mot_index - mot_step][0];

                        mv_predictor[pred_count][1]= s->current_picture.motion_val[0][mot_index - mot_step][1];

                        ref         [pred_count]   = s->current_picture.ref_index[0][4*(mb_xy-1)];

                        pred_count++;

                    }

                    if(mb_x+1<mb_width && fixed[mb_xy+1]){

                        mv_predictor[pred_count][0]= s->current_picture.motion_val[0][mot_index + mot_step][0];

                        mv_predictor[pred_count][1]= s->current_picture.motion_val[0][mot_index + mot_step][1];

                        ref         [pred_count]   = s->current_picture.ref_index[0][4*(mb_xy+1)];

                        pred_count++;

                    }

                    if(mb_y>0 && fixed[mb_xy-mb_stride]){

                        mv_predictor[pred_count][0]= s->current_picture.motion_val[0][mot_index - mot_stride*mot_step][0];

                        mv_predictor[pred_count][1]= s->current_picture.motion_val[0][mot_index - mot_stride*mot_step][1];

                        ref         [pred_count]   = s->current_picture.ref_index[0][4*(mb_xy-s->mb_stride)];

                        pred_count++;

                    }

                    if(mb_y+1<mb_height && fixed[mb_xy+mb_stride]){

                        mv_predictor[pred_count][0]= s->current_picture.motion_val[0][mot_index + mot_stride*mot_step][0];

                        mv_predictor[pred_count][1]= s->current_picture.motion_val[0][mot_index + mot_stride*mot_step][1];

                        ref         [pred_count]   = s->current_picture.ref_index[0][4*(mb_xy+s->mb_stride)];

                        pred_count++;

                    }

                    if(pred_count==0) continue;



                    if(pred_count>1){

                        int sum_x=0, sum_y=0, sum_r=0;

                        int max_x, max_y, min_x, min_y, max_r, min_r;



                        for(j=0; j<pred_count; j++){

                            sum_x+= mv_predictor[j][0];

                            sum_y+= mv_predictor[j][1];

                            sum_r+= ref[j];

                            if(j && ref[j] != ref[j-1])

                                goto skip_mean_and_median;

                        }



                        /* mean */

                        mv_predictor[pred_count][0] = sum_x/j;

                        mv_predictor[pred_count][1] = sum_y/j;

                        ref         [pred_count]    = sum_r/j;



                        /* median */

                        if(pred_count>=3){

                            min_y= min_x= min_r= 99999;

                            max_y= max_x= max_r=-99999;

                        }else{

                            min_x=min_y=max_x=max_y=min_r=max_r=0;

                        }

                        for(j=0; j<pred_count; j++){

                            max_x= FFMAX(max_x, mv_predictor[j][0]);

                            max_y= FFMAX(max_y, mv_predictor[j][1]);

                            max_r= FFMAX(max_r, ref[j]);

                            min_x= FFMIN(min_x, mv_predictor[j][0]);

                            min_y= FFMIN(min_y, mv_predictor[j][1]);

                            min_r= FFMIN(min_r, ref[j]);

                        }

                        mv_predictor[pred_count+1][0] = sum_x - max_x - min_x;

                        mv_predictor[pred_count+1][1] = sum_y - max_y - min_y;

                        ref         [pred_count+1]    = sum_r - max_r - min_r;



                        if(pred_count==4){

                            mv_predictor[pred_count+1][0] /= 2;

                            mv_predictor[pred_count+1][1] /= 2;

                            ref         [pred_count+1]    /= 2;

                        }

                        pred_count+=2;

                    }

skip_mean_and_median:



                    /* zero MV */

                    pred_count++;



                    if (!fixed[mb_xy]) {

                        if (s->avctx->codec_id == CODEC_ID_H264) {

                            // FIXME

                        } else {

                            ff_thread_await_progress((AVFrame *) s->last_picture_ptr,

                                                     mb_y, 0);

                        }

                        if (!s->last_picture.motion_val[0] ||

                            !s->last_picture.ref_index[0])

                            goto skip_last_mv;

                        prev_x = s->last_picture.motion_val[0][mot_index][0];

                        prev_y = s->last_picture.motion_val[0][mot_index][1];

                        prev_ref = s->last_picture.ref_index[0][4*mb_xy];

                    } else {

                        prev_x = s->current_picture.motion_val[0][mot_index][0];

                        prev_y = s->current_picture.motion_val[0][mot_index][1];

                        prev_ref = s->current_picture.ref_index[0][4*mb_xy];

                    }



                    /* last MV */

                    mv_predictor[pred_count][0]= prev_x;

                    mv_predictor[pred_count][1]= prev_y;

                    ref         [pred_count]   = prev_ref;

                    pred_count++;




                    s->mv_dir = MV_DIR_FORWARD;

                    s->mb_intra=0;

                    s->mv_type = MV_TYPE_16X16;

                    s->mb_skipped=0;



                    s->dsp.clear_blocks(s->block[0]);



                    s->mb_x= mb_x;

                    s->mb_y= mb_y;



                    for(j=0; j<pred_count; j++){

                        int score=0;

                        uint8_t *src= s->current_picture.data[0] + mb_x*16 + mb_y*16*s->linesize;



                        s->current_picture.motion_val[0][mot_index][0]= s->mv[0][0][0]= mv_predictor[j][0];

                        s->current_picture.motion_val[0][mot_index][1]= s->mv[0][0][1]= mv_predictor[j][1];



                        if(ref[j]<0) //predictor intra or otherwise not available

                            continue;



                        decode_mb(s, ref[j]);



                        if(mb_x>0 && fixed[mb_xy-1]){

                            int k;

                            for(k=0; k<16; k++)

                                score += FFABS(src[k*s->linesize-1 ]-src[k*s->linesize   ]);

                        }

                        if(mb_x+1<mb_width && fixed[mb_xy+1]){

                            int k;

                            for(k=0; k<16; k++)

                                score += FFABS(src[k*s->linesize+15]-src[k*s->linesize+16]);

                        }

                        if(mb_y>0 && fixed[mb_xy-mb_stride]){

                            int k;

                            for(k=0; k<16; k++)

                                score += FFABS(src[k-s->linesize   ]-src[k               ]);

                        }

                        if(mb_y+1<mb_height && fixed[mb_xy+mb_stride]){

                            int k;

                            for(k=0; k<16; k++)

                                score += FFABS(src[k+s->linesize*15]-src[k+s->linesize*16]);

                        }



                        if(score <= best_score){ // <= will favor the last MV

                            best_score= score;

                            best_pred= j;

                        }

                    }

score_sum+= best_score;

                    s->mv[0][0][0]= mv_predictor[best_pred][0];

                    s->mv[0][0][1]= mv_predictor[best_pred][1];



                    for(i=0; i<mot_step; i++)

                        for(j=0; j<mot_step; j++){

                            s->current_picture.motion_val[0][mot_index+i+j*mot_stride][0]= s->mv[0][0][0];

                            s->current_picture.motion_val[0][mot_index+i+j*mot_stride][1]= s->mv[0][0][1];

                        }



                    decode_mb(s, ref[best_pred]);





                    if(s->mv[0][0][0] != prev_x || s->mv[0][0][1] != prev_y){

                        fixed[mb_xy]=MV_CHANGED;

                        changed++;

                    }else

                        fixed[mb_xy]=MV_UNCHANGED;

                }

            }



//            printf(".%d/%d", changed, score_sum); fflush(stdout);

        }



        if(none_left)

            return;



        for(i=0; i<s->mb_num; i++){

            int mb_xy= s->mb_index2xy[i];

            if(fixed[mb_xy])

                fixed[mb_xy]=MV_FROZEN;

        }

//        printf(":"); fflush(stdout);

    }

}

static int read_var_block_data(ALSDecContext *ctx, ALSBlockData *bd)

{

    ALSSpecificConfig *sconf = &ctx->sconf;

    AVCodecContext *avctx    = ctx->avctx;

    GetBitContext *gb        = &ctx->gb;

    unsigned int k;

    unsigned int s[8];

    unsigned int sx[8];

    unsigned int sub_blocks, log2_sub_blocks, sb_length;

    unsigned int start      = 0;

    unsigned int opt_order;

    int          sb;

    int32_t      *quant_cof = bd->quant_cof;

    int32_t      *current_res;





    // ensure variable block decoding by reusing this field

    *bd->const_block = 0;



    *bd->opt_order  = 1;

    bd->js_blocks   = get_bits1(gb);



    opt_order       = *bd->opt_order;



    // determine the number of subblocks for entropy decoding

    if (!sconf->bgmc && !sconf->sb_part) {

        log2_sub_blocks = 0;

    } else {

        if (sconf->bgmc && sconf->sb_part)

            log2_sub_blocks = get_bits(gb, 2);

        else

            log2_sub_blocks = 2 * get_bits1(gb);




    sub_blocks = 1 << log2_sub_blocks;



    // do not continue in case of a damaged stream since

    // block_length must be evenly divisible by sub_blocks

    if (bd->block_length & (sub_blocks - 1)) {

        av_log(avctx, AV_LOG_WARNING,

               "Block length is not evenly divisible by the number of subblocks.\n");





    sb_length = bd->block_length >> log2_sub_blocks;



    if (sconf->bgmc) {

        s[0] = get_bits(gb, 8 + (sconf->resolution > 1));


            s[k] = s[k - 1] + decode_rice(gb, 2);



        for (k = 0; k < sub_blocks; k++) {

            sx[k]   = s[k] & 0x0F;

            s [k] >>= 4;


    } else {

        s[0] = get_bits(gb, 4 + (sconf->resolution > 1));


            s[k] = s[k - 1] + decode_rice(gb, 0);









    if (get_bits1(gb))

        *bd->shift_lsbs = get_bits(gb, 4) + 1;



    *bd->store_prev_samples = (bd->js_blocks && bd->raw_other) || *bd->shift_lsbs;





    if (!sconf->rlslms) {

        if (sconf->adapt_order) {

            int opt_order_length = av_ceil_log2(av_clip((bd->block_length >> 3) - 1,

                                                2, sconf->max_order + 1));

            *bd->opt_order       = get_bits(gb, opt_order_length);

            if (*bd->opt_order > sconf->max_order) {

                *bd->opt_order = sconf->max_order;

                av_log(avctx, AV_LOG_ERROR, "Predictor order too large!\n");



        } else {

            *bd->opt_order = sconf->max_order;




        opt_order = *bd->opt_order;



        if (opt_order) {

            int add_base;



            if (sconf->coef_table == 3) {

                add_base = 0x7F;



                // read coefficient 0

                quant_cof[0] = 32 * parcor_scaled_values[get_bits(gb, 7)];



                // read coefficient 1

                if (opt_order > 1)

                    quant_cof[1] = -32 * parcor_scaled_values[get_bits(gb, 7)];



                // read coefficients 2 to opt_order

                for (k = 2; k < opt_order; k++)

                    quant_cof[k] = get_bits(gb, 7);

            } else {

                int k_max;

                add_base = 1;



                // read coefficient 0 to 19

                k_max = FFMIN(opt_order, 20);

                for (k = 0; k < k_max; k++) {

                    int rice_param = parcor_rice_table[sconf->coef_table][k][1];

                    int offset     = parcor_rice_table[sconf->coef_table][k][0];

                    quant_cof[k] = decode_rice(gb, rice_param) + offset;

                    if (quant_cof[k] < -64 || quant_cof[k] > 63) {

                        av_log(avctx, AV_LOG_ERROR, "Quantization coefficient %d is out of range!\n", quant_cof[k]);

                        return AVERROR_INVALIDDATA;





                // read coefficients 20 to 126

                k_max = FFMIN(opt_order, 127);

                for (; k < k_max; k++)

                    quant_cof[k] = decode_rice(gb, 2) + (k & 1);



                // read coefficients 127 to opt_order

                for (; k < opt_order; k++)

                    quant_cof[k] = decode_rice(gb, 1);



                quant_cof[0] = 32 * parcor_scaled_values[quant_cof[0] + 64];



                if (opt_order > 1)

                    quant_cof[1] = -32 * parcor_scaled_values[quant_cof[1] + 64];




            for (k = 2; k < opt_order; k++)

                quant_cof[k] = (quant_cof[k] << 14) + (add_base << 13);





    // read LTP gain and lag values

    if (sconf->long_term_prediction) {

        *bd->use_ltp = get_bits1(gb);



        if (*bd->use_ltp) {

            int r, c;



            bd->ltp_gain[0]   = decode_rice(gb, 1) << 3;

            bd->ltp_gain[1]   = decode_rice(gb, 2) << 3;



            r                 = get_unary(gb, 0, 3);

            c                 = get_bits(gb, 2);

            bd->ltp_gain[2]   = ltp_gain_values[r][c];



            bd->ltp_gain[3]   = decode_rice(gb, 2) << 3;

            bd->ltp_gain[4]   = decode_rice(gb, 1) << 3;



            *bd->ltp_lag      = get_bits(gb, ctx->ltp_lag_length);

            *bd->ltp_lag     += FFMAX(4, opt_order + 1);





    // read first value and residuals in case of a random access block

    if (bd->ra_block) {

        if (opt_order)

            bd->raw_samples[0] = decode_rice(gb, avctx->bits_per_raw_sample - 4);

        if (opt_order > 1)

            bd->raw_samples[1] = decode_rice(gb, FFMIN(s[0] + 3, ctx->s_max));

        if (opt_order > 2)

            bd->raw_samples[2] = decode_rice(gb, FFMIN(s[0] + 1, ctx->s_max));



        start = FFMIN(opt_order, 3);




    // read all residuals

    if (sconf->bgmc) {

        int          delta[8];

        unsigned int k    [8];

        unsigned int b = av_clip((av_ceil_log2(bd->block_length) - 3) >> 1, 0, 5);

        unsigned int i = start;



        // read most significant bits

        unsigned int high;

        unsigned int low;

        unsigned int value;



        ff_bgmc_decode_init(gb, &high, &low, &value);



        current_res = bd->raw_samples + start;



        for (sb = 0; sb < sub_blocks; sb++, i = 0) {

            k    [sb] = s[sb] > b ? s[sb] - b : 0;

            delta[sb] = 5 - s[sb] + k[sb];



            ff_bgmc_decode(gb, sb_length, current_res,

                        delta[sb], sx[sb], &high, &low, &value, ctx->bgmc_lut, ctx->bgmc_lut_status);



            current_res += sb_length;




        ff_bgmc_decode_end(gb);





        // read least significant bits and tails

        i = start;

        current_res = bd->raw_samples + start;



        for (sb = 0; sb < sub_blocks; sb++, i = 0) {

            unsigned int cur_tail_code = tail_code[sx[sb]][delta[sb]];

            unsigned int cur_k         = k[sb];

            unsigned int cur_s         = s[sb];



            for (; i < sb_length; i++) {

                int32_t res = *current_res;



                if (res == cur_tail_code) {

                    unsigned int max_msb =   (2 + (sx[sb] > 2) + (sx[sb] > 10))

                                          << (5 - delta[sb]);



                    res = decode_rice(gb, cur_s);



                    if (res >= 0) {

                        res += (max_msb    ) << cur_k;

                    } else {

                        res -= (max_msb - 1) << cur_k;


                } else {

                    if (res > cur_tail_code)

                        res--;



                    if (res & 1)

                        res = -res;



                    res >>= 1;



                    if (cur_k) {

                        res <<= cur_k;

                        res  |= get_bits_long(gb, cur_k);





                *current_res++ = res;



    } else {

        current_res = bd->raw_samples + start;



        for (sb = 0; sb < sub_blocks; sb++, start = 0)

            for (; start < sb_length; start++)

                *current_res++ = decode_rice(gb, s[sb]);




    if (!sconf->mc_coding || ctx->js_switch)

        align_get_bits(gb);



    return 0;

static int write_abst(AVFormatContext *s, OutputStream *os, int final)

{

    HDSContext *c = s->priv_data;

    AVIOContext *out;

    char filename[1024], temp_filename[1024];

    int i, ret;

    int64_t asrt_pos, afrt_pos;

    int start = 0, fragments;

    int index = s->streams[os->first_stream]->id;

    int64_t cur_media_time = 0;

    if (c->window_size)

        start = FFMAX(os->nb_fragments - c->window_size, 0);

    fragments = os->nb_fragments - start;

    if (final)

        cur_media_time = os->last_ts;

    else if (os->nb_fragments)

        cur_media_time = os->fragments[os->nb_fragments - 1]->start_time;



    snprintf(filename, sizeof(filename),

             "%s/stream%d.abst", s->filename, index);

    snprintf(temp_filename, sizeof(temp_filename),

             "%s/stream%d.abst.tmp", s->filename, index);

    ret = avio_open2(&out, temp_filename, AVIO_FLAG_WRITE,

                     &s->interrupt_callback, NULL);

    if (ret < 0) {

        av_log(s, AV_LOG_ERROR, "Unable to open %s for writing\n", temp_filename);

        return ret;

    }

    avio_wb32(out, 0); // abst size

    avio_wl32(out, MKTAG('a','b','s','t'));

    avio_wb32(out, 0); // version + flags

    avio_wb32(out, os->fragment_index - 1); // BootstrapinfoVersion

    avio_w8(out, final ? 0 : 0x20); // profile, live, update

    avio_wb32(out, 1000); // timescale

    avio_wb64(out, cur_media_time);

    avio_wb64(out, 0); // SmpteTimeCodeOffset

    avio_w8(out, 0); // MovieIdentifer (null string)

    avio_w8(out, 0); // ServerEntryCount

    avio_w8(out, 0); // QualityEntryCount

    avio_w8(out, 0); // DrmData (null string)

    avio_w8(out, 0); // MetaData (null string)

    avio_w8(out, 1); // SegmentRunTableCount

    asrt_pos = avio_tell(out);

    avio_wb32(out, 0); // asrt size

    avio_wl32(out, MKTAG('a','s','r','t'));

    avio_wb32(out, 0); // version + flags

    avio_w8(out, 0); // QualityEntryCount

    avio_wb32(out, 1); // SegmentRunEntryCount

    avio_wb32(out, 1); // FirstSegment

    avio_wb32(out, final ? (os->fragment_index - 1) : 0xffffffff); // FragmentsPerSegment

    update_size(out, asrt_pos);

    avio_w8(out, 1); // FragmentRunTableCount

    afrt_pos = avio_tell(out);

    avio_wb32(out, 0); // afrt size

    avio_wl32(out, MKTAG('a','f','r','t'));

    avio_wb32(out, 0); // version + flags

    avio_wb32(out, 1000); // timescale

    avio_w8(out, 0); // QualityEntryCount

    avio_wb32(out, fragments); // FragmentRunEntryCount

    for (i = start; i < os->nb_fragments; i++) {

        avio_wb32(out, os->fragments[i]->n);

        avio_wb64(out, os->fragments[i]->start_time);

        avio_wb32(out, os->fragments[i]->duration);

    }

    update_size(out, afrt_pos);

    update_size(out, 0);

    avio_close(out);

    return ff_rename(temp_filename, filename);

}

static inline void RENAME(bgr24ToUV)(uint8_t *dstU, uint8_t *dstV, const uint8_t *src1, const uint8_t *src2, long width, uint32_t *unused)

{

#if COMPILE_TEMPLATE_MMX

    RENAME(bgr24ToUV_mmx)(dstU, dstV, src1, width, PIX_FMT_BGR24);

#else

    int i;

    for (i=0; i<width; i++) {

        int b= src1[3*i + 0];

        int g= src1[3*i + 1];

        int r= src1[3*i + 2];



        dstU[i]= (RU*r + GU*g + BU*b + (257<<(RGB2YUV_SHIFT-1)))>>RGB2YUV_SHIFT;

        dstV[i]= (RV*r + GV*g + BV*b + (257<<(RGB2YUV_SHIFT-1)))>>RGB2YUV_SHIFT;

    }

#endif /* COMPILE_TEMPLATE_MMX */

    assert(src1 == src2);

}

int qsv_init(AVCodecContext *s)

{

    InputStream *ist = s->opaque;

    QSVContext  *qsv = ist->hwaccel_ctx;

    AVQSVContext *hwctx_dec;

    int ret;



    if (!qsv) {

        av_log(NULL, AV_LOG_ERROR, "QSV transcoding is not initialized. "

               "-hwaccel qsv should only be used for one-to-one QSV transcoding "

               "with no filters.\n");

        return AVERROR_BUG;

    }



    ret = init_opaque_surf(qsv);

    if (ret < 0)

        return ret;



    hwctx_dec = av_qsv_alloc_context();

    if (!hwctx_dec)

        return AVERROR(ENOMEM);



    hwctx_dec->session        = qsv->session;

    hwctx_dec->iopattern      = MFX_IOPATTERN_OUT_OPAQUE_MEMORY;

    hwctx_dec->ext_buffers    = qsv->ext_buffers;

    hwctx_dec->nb_ext_buffers = FF_ARRAY_ELEMS(qsv->ext_buffers);



    av_freep(&s->hwaccel_context);

    s->hwaccel_context = hwctx_dec;



    ist->hwaccel_get_buffer = qsv_get_buffer;

    ist->hwaccel_uninit     = qsv_uninit;



    return 0;

}

static void float_to_int16_sse(int16_t *dst, const float *src, long len){

    int i;

    for(i=0; i<len; i+=4) {

        asm volatile(

            "cvtps2pi    %1, %%mm0 \n\t"

            "cvtps2pi    %2, %%mm1 \n\t"

            "packssdw %%mm1, %%mm0 \n\t"

            "movq     %%mm0, %0    \n\t"

            :"=m"(dst[i])

            :"m"(src[i]), "m"(src[i+2])

        );

    }

    asm volatile("emms");

}

static inline void RENAME(rgb32tobgr15)(const uint8_t *src, uint8_t *dst, long src_size)

{

    const uint8_t *s = src;

    const uint8_t *end;

#if COMPILE_TEMPLATE_MMX

    const uint8_t *mm_end;

#endif

    uint16_t *d = (uint16_t *)dst;

    end = s + src_size;

#if COMPILE_TEMPLATE_MMX

    __asm__ volatile(PREFETCH"    %0"::"m"(*src):"memory");

    __asm__ volatile(

        "movq          %0, %%mm7    \n\t"

        "movq          %1, %%mm6    \n\t"

        ::"m"(red_15mask),"m"(green_15mask));

    mm_end = end - 15;

    while (s < mm_end) {

        __asm__ volatile(

            PREFETCH"    32%1           \n\t"

            "movd          %1, %%mm0    \n\t"

            "movd         4%1, %%mm3    \n\t"

            "punpckldq    8%1, %%mm0    \n\t"

            "punpckldq   12%1, %%mm3    \n\t"

            "movq       %%mm0, %%mm1    \n\t"

            "movq       %%mm0, %%mm2    \n\t"

            "movq       %%mm3, %%mm4    \n\t"

            "movq       %%mm3, %%mm5    \n\t"

            "psllq         $7, %%mm0    \n\t"

            "psllq         $7, %%mm3    \n\t"

            "pand       %%mm7, %%mm0    \n\t"

            "pand       %%mm7, %%mm3    \n\t"

            "psrlq         $6, %%mm1    \n\t"

            "psrlq         $6, %%mm4    \n\t"

            "pand       %%mm6, %%mm1    \n\t"

            "pand       %%mm6, %%mm4    \n\t"

            "psrlq        $19, %%mm2    \n\t"

            "psrlq        $19, %%mm5    \n\t"

            "pand          %2, %%mm2    \n\t"

            "pand          %2, %%mm5    \n\t"

            "por        %%mm1, %%mm0    \n\t"

            "por        %%mm4, %%mm3    \n\t"

            "por        %%mm2, %%mm0    \n\t"

            "por        %%mm5, %%mm3    \n\t"

            "psllq        $16, %%mm3    \n\t"

            "por        %%mm3, %%mm0    \n\t"

            MOVNTQ"     %%mm0, %0       \n\t"

            :"=m"(*d):"m"(*s),"m"(blue_15mask):"memory");

        d += 4;

        s += 16;

    }

    __asm__ volatile(SFENCE:::"memory");

    __asm__ volatile(EMMS:::"memory");

#endif

    while (s < end) {

        register int rgb = *(const uint32_t*)s; s += 4;

        *d++ = ((rgb&0xF8)<<7) + ((rgb&0xF800)>>6) + ((rgb&0xF80000)>>19);

    }

}

static void flush_encoders(void)

{

    int i, ret;



    for (i = 0; i < nb_output_streams; i++) {

        OutputStream   *ost = output_streams[i];

        AVCodecContext *enc = ost->enc_ctx;

        AVFormatContext *os = output_files[ost->file_index]->ctx;

        int stop_encoding = 0;



        if (!ost->encoding_needed)

            continue;



        if (enc->codec_type == AVMEDIA_TYPE_AUDIO && enc->frame_size <= 1)

            continue;



        if (enc->codec_type != AVMEDIA_TYPE_VIDEO && enc->codec_type != AVMEDIA_TYPE_AUDIO)

            continue;



        avcodec_send_frame(enc, NULL);



        for (;;) {

            const char *desc = NULL;



            switch (enc->codec_type) {

            case AVMEDIA_TYPE_AUDIO:

                desc   = "Audio";

                break;

            case AVMEDIA_TYPE_VIDEO:

                desc   = "Video";

                break;

            default:

                av_assert0(0);

            }



            if (1) {

                AVPacket pkt;

                av_init_packet(&pkt);

                pkt.data = NULL;

                pkt.size = 0;



                ret = avcodec_receive_packet(enc, &pkt);

                if (ret < 0 && ret != AVERROR_EOF) {

                    av_log(NULL, AV_LOG_FATAL, "%s encoding failed\n", desc);

                    exit_program(1);

                }

                if (ost->logfile && enc->stats_out) {

                    fprintf(ost->logfile, "%s", enc->stats_out);

                }

                if (ret == AVERROR_EOF) {

                    stop_encoding = 1;

                    break;

                }

                av_packet_rescale_ts(&pkt, enc->time_base, ost->st->time_base);

                output_packet(os, &pkt, ost);

            }



            if (stop_encoding)

                break;

        }

    }

}

AVFormatContext *ff_rtp_chain_mux_open(AVFormatContext *s, AVStream *st,

                                       URLContext *handle, int packet_size)

{

    AVFormatContext *rtpctx;

    int ret;

    AVOutputFormat *rtp_format = av_guess_format("rtp", NULL, NULL);



    if (!rtp_format)

        return NULL;



    /* Allocate an AVFormatContext for each output stream */

    rtpctx = avformat_alloc_context();

    if (!rtpctx)

        return NULL;



    rtpctx->oformat = rtp_format;

    if (!av_new_stream(rtpctx, 0)) {

        av_free(rtpctx);

        return NULL;

    }

    /* Copy the max delay setting; the rtp muxer reads this. */

    rtpctx->max_delay = s->max_delay;

    /* Copy other stream parameters. */

    rtpctx->streams[0]->sample_aspect_ratio = st->sample_aspect_ratio;



    /* Set the synchronized start time. */

    rtpctx->start_time_realtime = s->start_time_realtime;



    avcodec_copy_context(rtpctx->streams[0]->codec, st->codec);



    if (handle) {

        url_fdopen(&rtpctx->pb, handle);

    } else

        url_open_dyn_packet_buf(&rtpctx->pb, packet_size);

    ret = av_write_header(rtpctx);



    if (ret) {

        if (handle) {

            avio_close(rtpctx->pb);

        } else {

            uint8_t *ptr;

            avio_close_dyn_buf(rtpctx->pb, &ptr);

            av_free(ptr);

        }

        avformat_free_context(rtpctx);

        return NULL;

    }



    return rtpctx;

}

