int avio_close_dyn_buf(AVIOContext *s, uint8_t **pbuffer)

{

    DynBuffer *d;

    int size;

    static const char padbuf[AV_INPUT_BUFFER_PADDING_SIZE] = {0};

    int padding = 0;



    if (!s) {

        *pbuffer = NULL;

        return 0;

    }



    /* don't attempt to pad fixed-size packet buffers */

    if (!s->max_packet_size) {

        avio_write(s, padbuf, sizeof(padbuf));

        padding = AV_INPUT_BUFFER_PADDING_SIZE;

    }



    avio_flush(s);



    d = s->opaque;

    *pbuffer = d->buffer;

    size = d->size;

    av_free(d);

    av_free(s);

    return size - padding;

}

static void get_slice_data(ProresContext *ctx, const uint16_t *src,

                           int linesize, int x, int y, int w, int h,

                           DCTELEM *blocks, uint16_t *emu_buf,

                           int mbs_per_slice, int blocks_per_mb, int is_chroma)

{

    const uint16_t *esrc;

    const int mb_width = 4 * blocks_per_mb;

    int elinesize;

    int i, j, k;



    for (i = 0; i < mbs_per_slice; i++, src += mb_width) {

        if (x >= w) {

            memset(blocks, 0, 64 * (mbs_per_slice - i) * blocks_per_mb

                              * sizeof(*blocks));

            return;

        }

        if (x + mb_width <= w && y + 16 <= h) {

            esrc      = src;

            elinesize = linesize;

        } else {

            int bw, bh, pix;



            esrc      = emu_buf;

            elinesize = 16 * sizeof(*emu_buf);



            bw = FFMIN(w - x, mb_width);

            bh = FFMIN(h - y, 16);



            for (j = 0; j < bh; j++) {

                memcpy(emu_buf + j * 16,

                       (const uint8_t*)src + j * linesize,

                       bw * sizeof(*src));

                pix = emu_buf[j * 16 + bw - 1];

                for (k = bw; k < mb_width; k++)

                    emu_buf[j * 16 + k] = pix;

            }

            for (; j < 16; j++)

                memcpy(emu_buf + j * 16,

                       emu_buf + (bh - 1) * 16,

                       mb_width * sizeof(*emu_buf));

        }

        if (!is_chroma) {

            ctx->dsp.fdct(esrc, elinesize, blocks);

            blocks += 64;

            if (blocks_per_mb > 2) {

                ctx->dsp.fdct(src + 8, linesize, blocks);

                blocks += 64;

            }

            ctx->dsp.fdct(src + linesize * 4, linesize, blocks);

            blocks += 64;

            if (blocks_per_mb > 2) {

                ctx->dsp.fdct(src + linesize * 4 + 8, linesize, blocks);

                blocks += 64;

            }

        } else {

            ctx->dsp.fdct(esrc, elinesize, blocks);

            blocks += 64;

            ctx->dsp.fdct(src + linesize * 4, linesize, blocks);

            blocks += 64;

            if (blocks_per_mb > 2) {

                ctx->dsp.fdct(src + 8, linesize, blocks);

                blocks += 64;

                ctx->dsp.fdct(src + linesize * 4 + 8, linesize, blocks);

                blocks += 64;

            }

        }



        x += mb_width;

    }

}

static av_cold int vaapi_encode_h265_init_internal(AVCodecContext *avctx)

{

    static const VAConfigAttrib default_config_attributes[] = {

        { .type  = VAConfigAttribRTFormat,

          .value = VA_RT_FORMAT_YUV420 },

        { .type  = VAConfigAttribEncPackedHeaders,

          .value = (VA_ENC_PACKED_HEADER_SEQUENCE |

                    VA_ENC_PACKED_HEADER_SLICE) },

    };



    VAAPIEncodeContext      *ctx = avctx->priv_data;

    VAAPIEncodeH265Context *priv = ctx->priv_data;

    int i, err;



    switch (avctx->profile) {

    case FF_PROFILE_HEVC_MAIN:

    case FF_PROFILE_UNKNOWN:

        ctx->va_profile = VAProfileHEVCMain;

        break;

    case FF_PROFILE_HEVC_MAIN_10:

        av_log(avctx, AV_LOG_ERROR, "H.265 main 10-bit profile "

               "is not supported.\n");

        return AVERROR_PATCHWELCOME;

    default:

        av_log(avctx, AV_LOG_ERROR, "Unknown H.265 profile %d.\n",

               avctx->profile);

        return AVERROR(EINVAL);

    }

    ctx->va_entrypoint = VAEntrypointEncSlice;



    ctx->input_width    = avctx->width;

    ctx->input_height   = avctx->height;

    ctx->aligned_width  = FFALIGN(ctx->input_width,  16);

    ctx->aligned_height = FFALIGN(ctx->input_height, 16);

    priv->ctu_width     = FFALIGN(ctx->aligned_width,  32) / 32;

    priv->ctu_height    = FFALIGN(ctx->aligned_height, 32) / 32;



    av_log(avctx, AV_LOG_VERBOSE, "Input %ux%u -> Aligned %ux%u -> CTU %ux%u.\n",

           ctx->input_width, ctx->input_height, ctx->aligned_width,

           ctx->aligned_height, priv->ctu_width, priv->ctu_height);



    for (i = 0; i < FF_ARRAY_ELEMS(default_config_attributes); i++) {

        ctx->config_attributes[ctx->nb_config_attributes++] =

            default_config_attributes[i];

    }



    if (avctx->bit_rate > 0) {

        ctx->va_rc_mode = VA_RC_CBR;

        err = vaapi_encode_h265_init_constant_bitrate(avctx);

    } else {

        ctx->va_rc_mode = VA_RC_CQP;

        err = vaapi_encode_h265_init_fixed_qp(avctx);

    }

    if (err < 0)

        return err;



    ctx->config_attributes[ctx->nb_config_attributes++] = (VAConfigAttrib) {

        .type  = VAConfigAttribRateControl,

        .value = ctx->va_rc_mode,

    };



    ctx->nb_recon_frames = 20;



    return 0;

}

static int decode_motion_vector (bit_buffer_t *bitbuf, svq1_pmv_t *mv, svq1_pmv_t **pmv) {

  uint32_t    bit_cache;

  vlc_code_t *vlc;

  int	      diff, sign;

  int	      i;



  for (i=0; i < 2; i++) {



    /* get motion code */

    bit_cache = get_bit_cache (bitbuf);



    if (!(bit_cache & 0xFFE00000))

      return -1;	/* invalid vlc code */



    if (bit_cache & 0x80000000) {

      diff = 0;



      /* flush bit */

      skip_bits(bitbuf,1);



    } else {

      if (bit_cache >= 0x06000000) {

        vlc = &motion_table_0[(bit_cache >> (32 - 7)) - 3];

      } else {

        vlc = &motion_table_1[(bit_cache >> (32 - 12)) - 2];

      }



      /* decode motion vector differential */

      sign = (int) (bit_cache << (vlc->length - 1)) >> 31;

      diff = (vlc->value ^ sign) - sign;



      /* flush bits */

      skip_bits(bitbuf,vlc->length);

    }



    /* add median of motion vector predictors and clip result */

    if (i == 1)

      mv->y = ((diff + MEDIAN(pmv[0]->y, pmv[1]->y, pmv[2]->y)) << 26) >> 26;

    else

      mv->x = ((diff + MEDIAN(pmv[0]->x, pmv[1]->x, pmv[2]->x)) << 26) >> 26;

  }



  return 0;

}

long check_dcbzl_effect(void)

{

  register char *fakedata = (char*)av_malloc(1024);

  register char *fakedata_middle;

  register long zero = 0;

  register long i = 0;

  long count = 0;



  if (!fakedata)

  {

    return 0L;

  }



  fakedata_middle = (fakedata + 512);



  memset(fakedata, 0xFF, 1024);



  /* below the constraint "b" seems to mean "Address base register"

     in gcc-3.3 / RS/6000 speaks. seems to avoid using r0, so.... */

  asm volatile("dcbzl %0, %1" : : "b" (fakedata_middle), "r" (zero));



  for (i = 0; i < 1024 ; i ++)

  {

    if (fakedata[i] == (char)0)

      count++;

  }



  av_free(fakedata);



  return count;

}

static inline void comp_block(MadContext *t, int mb_x, int mb_y,

                              int j, int mv_x, int mv_y, int add)

{

    MpegEncContext *s = &t->s;

    if (j < 4) {

        comp(t->frame.data[0] + (mb_y*16 + ((j&2)<<2))*t->frame.linesize[0] + mb_x*16 + ((j&1)<<3),

             t->frame.linesize[0],

             t->last_frame.data[0] + (mb_y*16 + ((j&2)<<2) + mv_y)*t->last_frame.linesize[0] + mb_x*16 + ((j&1)<<3) + mv_x,

             t->last_frame.linesize[0], add);

    } else if (!(s->avctx->flags & CODEC_FLAG_GRAY)) {

        int index = j - 3;

        comp(t->frame.data[index] + (mb_y*8)*t->frame.linesize[index] + mb_x * 8,

             t->frame.linesize[index],

             t->last_frame.data[index] + (mb_y * 8 + (mv_y/2))*t->last_frame.linesize[index] + mb_x * 8 + (mv_x/2),

             t->last_frame.linesize[index], add);

    }

}

static int mov_open_dref(AVIOContext **pb, char *src, MOVDref *ref,

                         AVIOInterruptCB *int_cb)

{

    /* try relative path, we do not try the absolute because it can leak information about our

       system to an attacker */

    if (ref->nlvl_to > 0 && ref->nlvl_from > 0) {

        char filename[1024];

        char *src_path;

        int i, l;



        /* find a source dir */

        src_path = strrchr(src, '/');

        if (src_path)

            src_path++;

        else

            src_path = src;



        /* find a next level down to target */

        for (i = 0, l = strlen(ref->path) - 1; l >= 0; l--)

            if (ref->path[l] == '/') {

                if (i == ref->nlvl_to - 1)

                    break;

                else

                    i++;

            }



        /* compose filename if next level down to target was found */

        if (i == ref->nlvl_to - 1 && src_path - src  < sizeof(filename)) {

            memcpy(filename, src, src_path - src);

            filename[src_path - src] = 0;



            for (i = 1; i < ref->nlvl_from; i++)

                av_strlcat(filename, "../", 1024);



            av_strlcat(filename, ref->path + l + 1, 1024);



            if (!avio_open2(pb, filename, AVIO_FLAG_READ, int_cb, NULL))

                return 0;

        }

    }



    return AVERROR(ENOENT);

}

pp_context_t *pp_get_context(int width, int height, int cpuCaps){

	PPContext *c= memalign(32, sizeof(PPContext));

	int i;

	int stride= (width+15)&(~15); //assumed / will realloc if needed



	memset(c, 0, sizeof(PPContext));

	c->cpuCaps= cpuCaps;

	if(cpuCaps&PP_FORMAT){

		c->hChromaSubSample= cpuCaps&0x3;

		c->vChromaSubSample= (cpuCaps>>4)&0x3;

	}else{

		c->hChromaSubSample= 1;

		c->vChromaSubSample= 1;

	}



	reallocBuffers(c, width, height, stride);



	c->frameNum=-1;



	return c;

}

static int rv10_decode_frame(AVCodecContext *avctx,

                             void *data, int *got_frame,

                             AVPacket *avpkt)

{

    const uint8_t *buf = avpkt->data;

    int buf_size = avpkt->size;

    MpegEncContext *s = avctx->priv_data;

    int i;

    AVFrame *pict = data;

    int slice_count;

    const uint8_t *slices_hdr = NULL;



    av_dlog(avctx, "*****frame %d size=%d\n", avctx->frame_number, buf_size);



    /* no supplementary picture */

    if (buf_size == 0) {

        return 0;

    }



    if(!avctx->slice_count){

        slice_count = (*buf++) + 1;

        buf_size--;

        slices_hdr = buf + 4;

        buf += 8 * slice_count;

        buf_size -= 8 * slice_count;

        if (buf_size <= 0)

            return AVERROR_INVALIDDATA;

    }else

        slice_count = avctx->slice_count;



    for(i=0; i<slice_count; i++){

        unsigned offset = get_slice_offset(avctx, slices_hdr, i);

        int size, size2;



        if (offset >= buf_size)

            return AVERROR_INVALIDDATA;



        if(i+1 == slice_count)

            size= buf_size - offset;

        else

            size= get_slice_offset(avctx, slices_hdr, i+1) - offset;



        if(i+2 >= slice_count)

            size2= buf_size - offset;

        else

            size2= get_slice_offset(avctx, slices_hdr, i+2) - offset;



        if (size <= 0 || size2 <= 0 ||

            offset + FFMAX(size, size2) > buf_size)

            return AVERROR_INVALIDDATA;



        if(rv10_decode_packet(avctx, buf+offset, size, size2) > 8*size)

            i++;

    }



    if(s->current_picture_ptr != NULL && s->mb_y>=s->mb_height){

        ff_er_frame_end(s);

        ff_MPV_frame_end(s);



        if (s->pict_type == AV_PICTURE_TYPE_B || s->low_delay) {

            *pict = s->current_picture_ptr->f;

        } else if (s->last_picture_ptr != NULL) {

            *pict = s->last_picture_ptr->f;

        }



        if(s->last_picture_ptr || s->low_delay){

            *got_frame = 1;

            ff_print_debug_info(s, pict);

        }

        s->current_picture_ptr= NULL; // so we can detect if frame_end was not called (find some nicer solution...)

    }



    return avpkt->size;

}

static int xvid_ff_2pass_after(struct xvid_context *ref,

                                xvid_plg_data_t *param) {

    char *log = ref->twopassbuffer;

    const char *frame_types = " ipbs";

    char frame_type;



    /* Quick bounds check */

    if( log == NULL )

        return XVID_ERR_FAIL;



    /* Convert the type given to us into a character */

    if( param->type < 5 && param->type > 0 ) {

        frame_type = frame_types[param->type];

    } else {

        return XVID_ERR_FAIL;

    }



    snprintf(BUFFER_CAT(log), BUFFER_REMAINING(log),

        "%c %d %d %d %d %d %d\n",

        frame_type, param->stats.quant, param->stats.kblks, param->stats.mblks,

        param->stats.ublks, param->stats.length, param->stats.hlength);



    return 0;

}

int ff_vdpau_common_end_frame(AVCodecContext *avctx, AVFrame *frame,

                              struct vdpau_picture_context *pic_ctx)

{

    VDPAUContext *vdctx = avctx->internal->hwaccel_priv_data;

    AVVDPAUContext *hwctx = avctx->hwaccel_context;

    VdpVideoSurface surf = ff_vdpau_get_surface_id(frame);

    VdpStatus status;

    int val;



    val = ff_vdpau_common_reinit(avctx);

    if (val < 0)

        return val;



#if FF_API_BUFS_VDPAU

FF_DISABLE_DEPRECATION_WARNINGS

    hwctx->info = pic_ctx->info;

    hwctx->bitstream_buffers = pic_ctx->bitstream_buffers;

    hwctx->bitstream_buffers_used = pic_ctx->bitstream_buffers_used;

    hwctx->bitstream_buffers_allocated = pic_ctx->bitstream_buffers_allocated;

FF_ENABLE_DEPRECATION_WARNINGS

#endif



    if (!hwctx->render) {

        status = hwctx->render2(avctx, frame, (void *)&pic_ctx->info,

                                pic_ctx->bitstream_buffers_used, pic_ctx->bitstream_buffers);

    } else

    status = vdctx->render(vdctx->decoder, surf, (void *)&pic_ctx->info,

                           pic_ctx->bitstream_buffers_used,

                           pic_ctx->bitstream_buffers);



    av_freep(&pic_ctx->bitstream_buffers);



#if FF_API_BUFS_VDPAU

FF_DISABLE_DEPRECATION_WARNINGS

    hwctx->bitstream_buffers = NULL;

    hwctx->bitstream_buffers_used = 0;

    hwctx->bitstream_buffers_allocated = 0;

FF_ENABLE_DEPRECATION_WARNINGS

#endif



    return vdpau_error(status);

}

static CheckasmFunc *get_func(const char *name, int length)

{

    CheckasmFunc *f, **f_ptr = &state.funcs;



    /* Search the tree for a matching node */

    while ((f = *f_ptr)) {

        int cmp = cmp_func_names(name, f->name);

        if (!cmp)

            return f;



        f_ptr = &f->child[(cmp > 0)];

    }



    /* Allocate and insert a new node into the tree */

    f = *f_ptr = checkasm_malloc(sizeof(CheckasmFunc) + length);

    memcpy(f->name, name, length+1);



    return f;

}

static void unref_picture(H264Context *h, Picture *pic)

{

    int off = offsetof(Picture, tf) + sizeof(pic->tf);

    int i;



    if (!pic->f.data[0])

        return;



    ff_thread_release_buffer(h->avctx, &pic->tf);

    av_buffer_unref(&pic->hwaccel_priv_buf);



    av_buffer_unref(&pic->qscale_table_buf);

    av_buffer_unref(&pic->mb_type_buf);

    for (i = 0; i < 2; i++) {

        av_buffer_unref(&pic->motion_val_buf[i]);

        av_buffer_unref(&pic->ref_index_buf[i]);

    }



    memset((uint8_t*)pic + off, 0, sizeof(*pic) - off);

}

void ff_free_parser_state(AVFormatContext *s, AVParserState *state)

{

    int i;

    AVParserStreamState *ss;



    if (!state)

        return;



    for (i = 0; i < state->nb_streams; i++) {

        ss = &state->stream_states[i];

        if (ss->parser)

            av_parser_close(ss->parser);

        av_free_packet(&ss->cur_pkt);

    }



    free_packet_list(state->packet_buffer);

    free_packet_list(state->raw_packet_buffer);



    av_free(state->stream_states);

    av_free(state);

}

