static int decode_residuals(FLACContext *s, int channel, int pred_order)

{

    int i, tmp, partition, method_type, rice_order;

    int sample = 0, samples;



    method_type = get_bits(&s->gb, 2);

    if (method_type > 1) {

        av_log(s->avctx, AV_LOG_ERROR, "illegal residual coding method %d\n",

               method_type);

        return -1;

    }



    rice_order = get_bits(&s->gb, 4);



    samples= s->blocksize >> rice_order;

    if (pred_order > samples) {

        av_log(s->avctx, AV_LOG_ERROR, "invalid predictor order: %i > %i\n",

               pred_order, samples);

        return -1;

    }



    sample=

    i= pred_order;

    for (partition = 0; partition < (1 << rice_order); partition++) {

        tmp = get_bits(&s->gb, method_type == 0 ? 4 : 5);

        if (tmp == (method_type == 0 ? 15 : 31)) {

            tmp = get_bits(&s->gb, 5);

            for (; i < samples; i++, sample++)

                s->decoded[channel][sample] = get_sbits_long(&s->gb, tmp);

        } else {

            for (; i < samples; i++, sample++) {

                s->decoded[channel][sample] = get_sr_golomb_flac(&s->gb, tmp, INT_MAX, 0);

            }

        }

        i= 0;

    }



    return 0;

}

static int print_device_sinks(AVOutputFormat *fmt, AVDictionary *opts)

{

    int ret, i;

    AVFormatContext *dev = NULL;

    AVDeviceInfoList *device_list = NULL;

    AVDictionary *tmp_opts = NULL;



    if (!fmt || !fmt->priv_class  || !AV_IS_OUTPUT_DEVICE(fmt->priv_class->category))

        return AVERROR(EINVAL);



    printf("Audo-detected sinks for %s:\n", fmt->name);

    if (!fmt->get_device_list) {

        ret = AVERROR(ENOSYS);

        printf("Cannot list sinks. Not implemented.\n");

        goto fail;

    }



    if ((ret = avformat_alloc_output_context2(&dev, fmt, NULL, NULL)) < 0) {

        printf("Cannot open device: %s.\n", fmt->name);

        goto fail;

    }

    av_dict_copy(&tmp_opts, opts, 0);

    av_opt_set_dict2(dev, &tmp_opts, AV_OPT_SEARCH_CHILDREN);



    if ((ret = avdevice_list_devices(dev, &device_list)) < 0) {

        printf("Cannot list sinks.\n");

        goto fail;

    }



    for (i = 0; i < device_list->nb_devices; i++) {

        printf("%s %s [%s]\n", device_list->default_device == i ? "*" : " ",

               device_list->devices[i]->device_name, device_list->devices[i]->device_description);

    }



  fail:

    av_dict_free(&tmp_opts);

    avdevice_free_list_devices(&device_list);

    avformat_free_context(dev);

    return ret;

}

static int bmp_decode_frame(AVCodecContext *avctx,

                            void *data, int *data_size,

                            uint8_t *buf, int buf_size)

{

    BMPContext *s = avctx->priv_data;

    AVFrame *picture = data;

    AVFrame *p = &s->picture;

    unsigned int fsize, hsize;

    int width, height;

    unsigned int depth;

    BiCompression comp;

    unsigned int ihsize;

    int i, j, n, linesize;

    uint32_t rgb[3];

    uint8_t *ptr;

    int dsize;

    uint8_t *buf0 = buf;



    if(buf_size < 14){

        av_log(avctx, AV_LOG_ERROR, "buf size too small (%d)\n", buf_size);

        return -1;

    }



    if(bytestream_get_byte(&buf) != 'B' ||

       bytestream_get_byte(&buf) != 'M') {

        av_log(avctx, AV_LOG_ERROR, "bad magic number\n");

        return -1;

    }



    fsize = bytestream_get_le32(&buf);

    if(buf_size < fsize){

        av_log(avctx, AV_LOG_ERROR, "not enough data (%d < %d)\n",

               buf_size, fsize);

        return -1;

    }



    buf += 2; /* reserved1 */

    buf += 2; /* reserved2 */



    hsize = bytestream_get_le32(&buf); /* header size */

    if(fsize <= hsize){

        av_log(avctx, AV_LOG_ERROR, "not enough data (%d < %d)\n",

               fsize, hsize);

        return -1;

    }



    ihsize = bytestream_get_le32(&buf);       /* more header size */

    if(ihsize + 14 > hsize){

        av_log(avctx, AV_LOG_ERROR, "invalid header size %d\n", hsize);

        return -1;

    }



    width = bytestream_get_le32(&buf);

    height = bytestream_get_le32(&buf);



    if(bytestream_get_le16(&buf) != 1){ /* planes */

        av_log(avctx, AV_LOG_ERROR, "invalid BMP header\n");

        return -1;

    }



    depth = bytestream_get_le16(&buf);



    if(ihsize > 16)

        comp = bytestream_get_le32(&buf);

    else

        comp = BMP_RGB;



    if(comp != BMP_RGB && comp != BMP_BITFIELDS){

        av_log(avctx, AV_LOG_ERROR, "BMP coding %d not supported\n", comp);

        return -1;

    }



    if(comp == BMP_BITFIELDS){

        buf += 20;

        rgb[0] = bytestream_get_le32(&buf);

        rgb[1] = bytestream_get_le32(&buf);

        rgb[2] = bytestream_get_le32(&buf);

    }



    avctx->codec_id = CODEC_ID_BMP;

    avctx->width = width;

    avctx->height = height > 0? height: -height;



    avctx->pix_fmt = PIX_FMT_NONE;



    switch(depth){

    case 32:

        if(comp == BMP_BITFIELDS){

            rgb[0] = (rgb[0] >> 15) & 3;

            rgb[1] = (rgb[1] >> 15) & 3;

            rgb[2] = (rgb[2] >> 15) & 3;



            if(rgb[0] + rgb[1] + rgb[2] != 3 ||

               rgb[0] == rgb[1] || rgb[0] == rgb[2] || rgb[1] == rgb[2]){

                break;

            }

        } else {

            rgb[0] = 2;

            rgb[1] = 1;

            rgb[2] = 0;

        }



        avctx->pix_fmt = PIX_FMT_BGR24;

        break;

    case 24:

        avctx->pix_fmt = PIX_FMT_BGR24;

        break;

    case 16:

        if(comp == BMP_RGB)

            avctx->pix_fmt = PIX_FMT_RGB555;

        break;

    default:

        av_log(avctx, AV_LOG_ERROR, "depth %d not supported\n", depth);

        return -1;

    }



    if(avctx->pix_fmt == PIX_FMT_NONE){

        av_log(avctx, AV_LOG_ERROR, "unsupported pixel format\n");

        return -1;

    }



    if(p->data[0])

        avctx->release_buffer(avctx, p);



    p->reference = 0;

    if(avctx->get_buffer(avctx, p) < 0){

        av_log(avctx, AV_LOG_ERROR, "get_buffer() failed\n");

        return -1;

    }

    p->pict_type = FF_I_TYPE;

    p->key_frame = 1;



    buf = buf0 + hsize;

    dsize = buf_size - hsize;



    /* Line size in file multiple of 4 */

    n = (avctx->width * (depth / 8) + 3) & ~3;



    if(n * avctx->height > dsize){

        av_log(avctx, AV_LOG_ERROR, "not enough data (%d < %d)\n",

               dsize, n * avctx->height);

        return -1;

    }



    if(height > 0){

        ptr = p->data[0] + (avctx->height - 1) * p->linesize[0];

        linesize = -p->linesize[0];

    } else {

        ptr = p->data[0];

        linesize = p->linesize[0];

    }



    switch(depth){

    case 24:

        for(i = 0; i < avctx->height; i++){

            memcpy(ptr, buf, n);

            buf += n;

            ptr += linesize;

        }

        break;

    case 16:

        for(i = 0; i < avctx->height; i++){

            uint16_t *src = (uint16_t *) buf;

            uint16_t *dst = (uint16_t *) ptr;



            for(j = 0; j < avctx->width; j++)

                *dst++ = le2me_16(*src++);



            buf += n;

            ptr += linesize;

        }

        break;

    case 32:

        for(i = 0; i < avctx->height; i++){

            uint8_t *src = buf;

            uint8_t *dst = ptr;



            for(j = 0; j < avctx->width; j++){

                dst[0] = src[rgb[2]];

                dst[1] = src[rgb[1]];

                dst[2] = src[rgb[0]];

                dst += 3;

                src += 4;

            }



            buf += n;

            ptr += linesize;

        }

        break;

    default:

        av_log(avctx, AV_LOG_ERROR, "BMP decoder is broken\n");

        return -1;

    }



    *picture = s->picture;

    *data_size = sizeof(AVPicture);



    return buf_size;

}

static void add_pixels_clamped4_c(const DCTELEM *block, uint8_t *restrict pixels,

                          int line_size)

{

    int i;

    uint8_t *cm = ff_cropTbl + MAX_NEG_CROP;



    /* read the pixels */

    for(i=0;i<4;i++) {

        pixels[0] = cm[pixels[0] + block[0]];

        pixels[1] = cm[pixels[1] + block[1]];

        pixels[2] = cm[pixels[2] + block[2]];

        pixels[3] = cm[pixels[3] + block[3]];

        pixels += line_size;

        block += 8;

    }

}

static void msmpeg4_encode_dc(MpegEncContext * s, int level, int n, int *dir_ptr)

{

    int sign, code;

    int pred, extquant;

    int extrabits = 0;



    int16_t *dc_val;

    pred = ff_msmpeg4_pred_dc(s, n, &dc_val, dir_ptr);



    /* update predictor */

    if (n < 4) {

        *dc_val = level * s->y_dc_scale;

    } else {

        *dc_val = level * s->c_dc_scale;

    }



    /* do the prediction */

    level -= pred;



    if(s->msmpeg4_version<=2){

        if (n < 4) {

            put_bits(&s->pb,

                     ff_v2_dc_lum_table[level + 256][1],

                     ff_v2_dc_lum_table[level + 256][0]);

        }else{

            put_bits(&s->pb,

                     ff_v2_dc_chroma_table[level + 256][1],

                     ff_v2_dc_chroma_table[level + 256][0]);

        }

    }else{

        sign = 0;

        if (level < 0) {

            level = -level;

            sign = 1;

        }

        code = level;

        if (code > DC_MAX)

            code = DC_MAX;

        else if( s->msmpeg4_version>=6 ) {

            if( s->qscale == 1 ) {

                extquant = (level + 3) & 0x3;

                code  = ((level+3)>>2);

            } else if( s->qscale == 2 ) {

                extquant = (level + 1) & 0x1;

                code  = ((level+1)>>1);

            }

        }



        if (s->dc_table_index == 0) {

            if (n < 4) {

                put_bits(&s->pb, ff_table0_dc_lum[code][1], ff_table0_dc_lum[code][0]);

            } else {

                put_bits(&s->pb, ff_table0_dc_chroma[code][1], ff_table0_dc_chroma[code][0]);

            }

        } else {

            if (n < 4) {

                put_bits(&s->pb, ff_table1_dc_lum[code][1], ff_table1_dc_lum[code][0]);

            } else {

                put_bits(&s->pb, ff_table1_dc_chroma[code][1], ff_table1_dc_chroma[code][0]);

            }

        }



        if(s->msmpeg4_version>=6 && s->qscale<=2)

            extrabits = 3 - s->qscale;



        if (code == DC_MAX)

            put_bits(&s->pb, 8 + extrabits, level);

        else if(extrabits > 0)//== VC1 && s->qscale<=2

            put_bits(&s->pb, extrabits, extquant);



        if (level != 0) {

            put_bits(&s->pb, 1, sign);

        }

    }

}

matroska_read_header (AVFormatContext    *s,

                      AVFormatParameters *ap)

{

    MatroskaDemuxContext *matroska = s->priv_data;

    char *doctype;

    int version, last_level, res = 0;

    uint32_t id;



    matroska->ctx = s;



    /* First read the EBML header. */

    doctype = NULL;

    if ((res = ebml_read_header(matroska, &doctype, &version)) < 0)

        return res;

    if ((doctype == NULL) || strcmp(doctype, "matroska")) {

        av_log(matroska->ctx, AV_LOG_ERROR,

               "Wrong EBML doctype ('%s' != 'matroska').\n",

               doctype ? doctype : "(none)");

        if (doctype)

            av_free(doctype);

        return AVERROR_NOFMT;

    }

    av_free(doctype);

    if (version > 2) {

        av_log(matroska->ctx, AV_LOG_ERROR,

               "Matroska demuxer version 2 too old for file version %d\n",

               version);

        return AVERROR_NOFMT;

    }



    /* The next thing is a segment. */

    while (1) {

        if (!(id = ebml_peek_id(matroska, &last_level)))

            return AVERROR(EIO);

        if (id == MATROSKA_ID_SEGMENT)

            break;



        /* oi! */

        av_log(matroska->ctx, AV_LOG_INFO,

               "Expected a Segment ID (0x%x), but received 0x%x!\n",

               MATROSKA_ID_SEGMENT, id);

        if ((res = ebml_read_skip(matroska)) < 0)

            return res;

    }



    /* We now have a Matroska segment.

     * Seeks are from the beginning of the segment,

     * after the segment ID/length. */

    if ((res = ebml_read_master(matroska, &id)) < 0)

        return res;

    matroska->segment_start = url_ftell(s->pb);



    matroska->time_scale = 1000000;

    /* we've found our segment, start reading the different contents in here */

    while (res == 0) {

        if (!(id = ebml_peek_id(matroska, &matroska->level_up))) {

            res = AVERROR(EIO);

            break;

        } else if (matroska->level_up) {

            matroska->level_up--;

            break;

        }



        switch (id) {

            /* stream info */

            case MATROSKA_ID_INFO: {

                if ((res = ebml_read_master(matroska, &id)) < 0)

                    break;

                res = matroska_parse_info(matroska);

                break;

            }



            /* track info headers */

            case MATROSKA_ID_TRACKS: {

                if ((res = ebml_read_master(matroska, &id)) < 0)

                    break;

                res = matroska_parse_tracks(matroska);

                break;

            }



            /* stream index */

            case MATROSKA_ID_CUES: {

                if (!matroska->index_parsed) {

                    if ((res = ebml_read_master(matroska, &id)) < 0)

                        break;

                    res = matroska_parse_index(matroska);

                } else

                    res = ebml_read_skip(matroska);

                break;

            }



            /* metadata */

            case MATROSKA_ID_TAGS: {

                if (!matroska->metadata_parsed) {

                    if ((res = ebml_read_master(matroska, &id)) < 0)

                        break;

                    res = matroska_parse_metadata(matroska);

                } else

                    res = ebml_read_skip(matroska);

                break;

            }



            /* file index (if seekable, seek to Cues/Tags to parse it) */

            case MATROSKA_ID_SEEKHEAD: {

                if ((res = ebml_read_master(matroska, &id)) < 0)

                    break;

                res = matroska_parse_seekhead(matroska);

                break;

            }



            case MATROSKA_ID_ATTACHMENTS: {

                if ((res = ebml_read_master(matroska, &id)) < 0)

                    break;

                res = matroska_parse_attachments(s);

                break;

            }



            case MATROSKA_ID_CLUSTER: {

                /* Do not read the master - this will be done in the next

                 * call to matroska_read_packet. */

                res = 1;

                break;

            }



            default:

                av_log(matroska->ctx, AV_LOG_INFO,

                       "Unknown matroska file header ID 0x%x\n", id);

            /* fall-through */



            case EBML_ID_VOID:

                res = ebml_read_skip(matroska);

                break;

        }



        if (matroska->level_up) {

            matroska->level_up--;

            break;

        }

    }



    /* Have we found a cluster? */

    if (ebml_peek_id(matroska, NULL) == MATROSKA_ID_CLUSTER) {

        int i, j;

        MatroskaTrack *track;

        AVStream *st;



        for (i = 0; i < matroska->num_tracks; i++) {

            enum CodecID codec_id = CODEC_ID_NONE;

            uint8_t *extradata = NULL;

            int extradata_size = 0;

            int extradata_offset = 0;

            track = matroska->tracks[i];

            track->stream_index = -1;



            /* Apply some sanity checks. */

            if (track->codec_id == NULL)

                continue;



            for(j=0; ff_mkv_codec_tags[j].id != CODEC_ID_NONE; j++){

                if(!strncmp(ff_mkv_codec_tags[j].str, track->codec_id,

                            strlen(ff_mkv_codec_tags[j].str))){

                    codec_id= ff_mkv_codec_tags[j].id;

                    break;

                }

            }



            /* Set the FourCC from the CodecID. */

            /* This is the MS compatibility mode which stores a

             * BITMAPINFOHEADER in the CodecPrivate. */

            if (!strcmp(track->codec_id,

                        MATROSKA_CODEC_ID_VIDEO_VFW_FOURCC) &&

                (track->codec_priv_size >= 40) &&

                (track->codec_priv != NULL)) {

                MatroskaVideoTrack *vtrack = (MatroskaVideoTrack *) track;



                /* Offset of biCompression. Stored in LE. */

                vtrack->fourcc = AV_RL32(track->codec_priv + 16);

                codec_id = codec_get_id(codec_bmp_tags, vtrack->fourcc);



            }



            /* This is the MS compatibility mode which stores a

             * WAVEFORMATEX in the CodecPrivate. */

            else if (!strcmp(track->codec_id,

                             MATROSKA_CODEC_ID_AUDIO_ACM) &&

                (track->codec_priv_size >= 18) &&

                (track->codec_priv != NULL)) {

                uint16_t tag;



                /* Offset of wFormatTag. Stored in LE. */

                tag = AV_RL16(track->codec_priv);

                codec_id = codec_get_id(codec_wav_tags, tag);



            }



            else if (codec_id == CODEC_ID_AAC && !track->codec_priv_size) {

                MatroskaAudioTrack *audiotrack = (MatroskaAudioTrack *) track;

                int profile = matroska_aac_profile(track->codec_id);

                int sri = matroska_aac_sri(audiotrack->internal_samplerate);

                extradata = av_malloc(5);

                if (extradata == NULL)

                    return AVERROR(ENOMEM);

                extradata[0] = (profile << 3) | ((sri&0x0E) >> 1);

                extradata[1] = ((sri&0x01) << 7) | (audiotrack->channels<<3);

                if (strstr(track->codec_id, "SBR")) {

                    sri = matroska_aac_sri(audiotrack->samplerate);

                    extradata[2] = 0x56;

                    extradata[3] = 0xE5;

                    extradata[4] = 0x80 | (sri<<3);

                    extradata_size = 5;

                } else {

                    extradata_size = 2;

                }

            }



            else if (codec_id == CODEC_ID_TTA) {

                MatroskaAudioTrack *audiotrack = (MatroskaAudioTrack *) track;

                ByteIOContext b;

                extradata_size = 30;

                extradata = av_mallocz(extradata_size);

                if (extradata == NULL)

                    return AVERROR(ENOMEM);

                init_put_byte(&b, extradata, extradata_size, 1,

                              NULL, NULL, NULL, NULL);

                put_buffer(&b, "TTA1", 4);

                put_le16(&b, 1);

                put_le16(&b, audiotrack->channels);

                put_le16(&b, audiotrack->bitdepth);

                put_le32(&b, audiotrack->samplerate);

                put_le32(&b, matroska->ctx->duration * audiotrack->samplerate);

            }



            else if (codec_id == CODEC_ID_RV10 || codec_id == CODEC_ID_RV20 ||

                     codec_id == CODEC_ID_RV30 || codec_id == CODEC_ID_RV40) {

                extradata_offset = 26;

                track->codec_priv_size -= extradata_offset;

            }



            else if (codec_id == CODEC_ID_RA_144) {

                MatroskaAudioTrack *audiotrack = (MatroskaAudioTrack *)track;

                audiotrack->samplerate = 8000;

                audiotrack->channels = 1;

            }



            else if (codec_id == CODEC_ID_RA_288 ||

                     codec_id == CODEC_ID_COOK ||

                     codec_id == CODEC_ID_ATRAC3) {

                MatroskaAudioTrack *audiotrack = (MatroskaAudioTrack *)track;

                ByteIOContext b;



                init_put_byte(&b, track->codec_priv, track->codec_priv_size, 0,

                              NULL, NULL, NULL, NULL);

                url_fskip(&b, 24);

                audiotrack->coded_framesize = get_be32(&b);

                url_fskip(&b, 12);

                audiotrack->sub_packet_h    = get_be16(&b);

                audiotrack->frame_size      = get_be16(&b);

                audiotrack->sub_packet_size = get_be16(&b);

                audiotrack->buf = av_malloc(audiotrack->frame_size * audiotrack->sub_packet_h);

                if (codec_id == CODEC_ID_RA_288) {

                    audiotrack->block_align = audiotrack->coded_framesize;

                    track->codec_priv_size = 0;

                } else {

                    audiotrack->block_align = audiotrack->sub_packet_size;

                    extradata_offset = 78;

                    track->codec_priv_size -= extradata_offset;

                }

            }



            if (codec_id == CODEC_ID_NONE) {

                av_log(matroska->ctx, AV_LOG_INFO,

                       "Unknown/unsupported CodecID %s.\n",

                       track->codec_id);

            }



            track->stream_index = matroska->num_streams;



            matroska->num_streams++;

            st = av_new_stream(s, track->stream_index);

            if (st == NULL)

                return AVERROR(ENOMEM);

            av_set_pts_info(st, 64, matroska->time_scale, 1000*1000*1000); /* 64 bit pts in ns */



            st->codec->codec_id = codec_id;

            st->start_time = 0;

            if (strcmp(track->language, "und"))

                strcpy(st->language, track->language);



            if (track->flags & MATROSKA_TRACK_DEFAULT)

                st->disposition |= AV_DISPOSITION_DEFAULT;



            if (track->default_duration)

                av_reduce(&st->codec->time_base.num, &st->codec->time_base.den,

                          track->default_duration, 1000000000, 30000);



            if(extradata){

                st->codec->extradata = extradata;

                st->codec->extradata_size = extradata_size;

            } else if(track->codec_priv && track->codec_priv_size > 0){

                st->codec->extradata = av_malloc(track->codec_priv_size);

                if(st->codec->extradata == NULL)

                    return AVERROR(ENOMEM);

                st->codec->extradata_size = track->codec_priv_size;

                memcpy(st->codec->extradata,track->codec_priv+extradata_offset,

                       track->codec_priv_size);

            }



            if (track->type == MATROSKA_TRACK_TYPE_VIDEO) {

                MatroskaVideoTrack *videotrack = (MatroskaVideoTrack *)track;



                st->codec->codec_type = CODEC_TYPE_VIDEO;

                st->codec->codec_tag = videotrack->fourcc;

                st->codec->width = videotrack->pixel_width;

                st->codec->height = videotrack->pixel_height;

                if (videotrack->display_width == 0)

                    videotrack->display_width= videotrack->pixel_width;

                if (videotrack->display_height == 0)

                    videotrack->display_height= videotrack->pixel_height;

                av_reduce(&st->codec->sample_aspect_ratio.num,

                          &st->codec->sample_aspect_ratio.den,

                          st->codec->height * videotrack->display_width,

                          st->codec-> width * videotrack->display_height,

                          255);

                st->need_parsing = AVSTREAM_PARSE_HEADERS;

            } else if (track->type == MATROSKA_TRACK_TYPE_AUDIO) {

                MatroskaAudioTrack *audiotrack = (MatroskaAudioTrack *)track;



                st->codec->codec_type = CODEC_TYPE_AUDIO;

                st->codec->sample_rate = audiotrack->samplerate;

                st->codec->channels = audiotrack->channels;

                st->codec->block_align = audiotrack->block_align;

            } else if (track->type == MATROSKA_TRACK_TYPE_SUBTITLE) {

                st->codec->codec_type = CODEC_TYPE_SUBTITLE;

            }



            /* What do we do with private data? E.g. for Vorbis. */

        }

        res = 0;

    }



    if (matroska->index_parsed) {

        int i, track, stream;

        for (i=0; i<matroska->num_indexes; i++) {

            MatroskaDemuxIndex *idx = &matroska->index[i];

            track = matroska_find_track_by_num(matroska, idx->track);

            stream = matroska->tracks[track]->stream_index;

            if (stream >= 0)

                av_add_index_entry(matroska->ctx->streams[stream],

                                   idx->pos, idx->time/matroska->time_scale,

                                   0, 0, AVINDEX_KEYFRAME);

        }

    }



    return res;

}

