static int mpeg1_decode_picture(AVCodecContext *avctx, 

                                UINT8 *buf, int buf_size)

{

    Mpeg1Context *s1 = avctx->priv_data;

    MpegEncContext *s = &s1->mpeg_enc_ctx;

    int ref, f_code;



    init_get_bits(&s->gb, buf, buf_size);



    ref = get_bits(&s->gb, 10); /* temporal ref */

    s->pict_type = get_bits(&s->gb, 3);

    dprintf("pict_type=%d number=%d\n", s->pict_type, s->picture_number);



    skip_bits(&s->gb, 16);

    if (s->pict_type == P_TYPE || s->pict_type == B_TYPE) {

        s->full_pel[0] = get_bits1(&s->gb);

        f_code = get_bits(&s->gb, 3);

        if (f_code == 0)

            return -1;

        s->mpeg_f_code[0][0] = f_code;

        s->mpeg_f_code[0][1] = f_code;

    }

    if (s->pict_type == B_TYPE) {

        s->full_pel[1] = get_bits1(&s->gb);

        f_code = get_bits(&s->gb, 3);

        if (f_code == 0)

            return -1;

        s->mpeg_f_code[1][0] = f_code;

        s->mpeg_f_code[1][1] = f_code;

    }

    s->current_picture.pict_type= s->pict_type;

    s->current_picture.key_frame= s->pict_type == I_TYPE;



    s->y_dc_scale = 8;

    s->c_dc_scale = 8;

    s->first_slice = 1;

    return 0;

}

static int mpeg1_find_frame_end(MpegEncContext *s, uint8_t *buf, int buf_size){

    ParseContext *pc= &s->parse_context;

    int i;

    uint32_t state;



    state= pc->state;



    i=0;

    if(!pc->frame_start_found){

        for(i=0; i<buf_size; i++){

            state= (state<<8) | buf[i];

            if(state >= SLICE_MIN_START_CODE && state <= SLICE_MAX_START_CODE){

                i++;

                pc->frame_start_found=1;

                break;

            }

        }

    }



    if(pc->frame_start_found){

        for(; i<buf_size; i++){

            state= (state<<8) | buf[i];

            if((state&0xFFFFFF00) == 0x100){

                if(state < SLICE_MIN_START_CODE || state > SLICE_MAX_START_CODE){

                    pc->frame_start_found=0;

                    pc->state=-1; 

                    return i-3;

                }

            }

        }

    }        

    pc->state= state;

    return -1;

}

static int mov_read_mvhd(MOVContext *c, AVIOContext *pb, MOVAtom atom)

{

    int i;

    int64_t creation_time;

    int version = avio_r8(pb); /* version */

    avio_rb24(pb); /* flags */



    if (version == 1) {

        creation_time = avio_rb64(pb);

        avio_rb64(pb);

    } else {

        creation_time = avio_rb32(pb);

        avio_rb32(pb); /* modification time */

    }

    mov_metadata_creation_time(&c->fc->metadata, creation_time);

    c->time_scale = avio_rb32(pb); /* time scale */

    if (c->time_scale <= 0) {

        av_log(c->fc, AV_LOG_ERROR, "Invalid mvhd time scale %d\n", c->time_scale);

        return AVERROR_INVALIDDATA;

    }

    av_log(c->fc, AV_LOG_TRACE, "time scale = %i\n", c->time_scale);



    c->duration = (version == 1) ? avio_rb64(pb) : avio_rb32(pb); /* duration */

    // set the AVCodecContext duration because the duration of individual tracks

    // may be inaccurate

    if (c->time_scale > 0 && !c->trex_data)

        c->fc->duration = av_rescale(c->duration, AV_TIME_BASE, c->time_scale);

    avio_rb32(pb); /* preferred scale */



    avio_rb16(pb); /* preferred volume */



    avio_skip(pb, 10); /* reserved */



    /* movie display matrix, store it in main context and use it later on */

    for (i = 0; i < 3; i++) {

        c->movie_display_matrix[i][0] = avio_rb32(pb); // 16.16 fixed point

        c->movie_display_matrix[i][1] = avio_rb32(pb); // 16.16 fixed point

        c->movie_display_matrix[i][2] = avio_rb32(pb); //  2.30 fixed point

    }



    avio_rb32(pb); /* preview time */

    avio_rb32(pb); /* preview duration */

    avio_rb32(pb); /* poster time */

    avio_rb32(pb); /* selection time */

    avio_rb32(pb); /* selection duration */

    avio_rb32(pb); /* current time */

    avio_rb32(pb); /* next track ID */



    return 0;

}

static int decode_packet(Jpeg2000DecoderContext *s, Jpeg2000CodingStyle *codsty, Jpeg2000ResLevel *rlevel, int precno,

                         int layno, uint8_t *expn, int numgbits)

{

    int bandno, cblkny, cblknx, cblkno, ret;



    if (!(ret = get_bits(s, 1))){

        j2k_flush(s);

        return 0;

    } else if (ret < 0)

        return ret;



    for (bandno = 0; bandno < rlevel->nbands; bandno++){

        Jpeg2000Band *band = rlevel->band + bandno;

        Jpeg2000Prec *prec = band->prec + precno;

        int pos = 0;



        if (band->coord[0][0] == band->coord[0][1]

        ||  band->coord[1][0] == band->coord[1][1])

            continue;



        for (cblkny = prec->yi0; cblkny < prec->yi1; cblkny++)

            for(cblknx = prec->xi0, cblkno = cblkny * band->cblknx + cblknx; cblknx < prec->xi1; cblknx++, cblkno++, pos++){

                Jpeg2000Cblk *cblk = band->cblk + cblkno;

                int incl, newpasses, llen;



                if (cblk->npasses)

                    incl = get_bits(s, 1);

                else

                    incl = tag_tree_decode(s, prec->cblkincl + pos, layno+1) == layno;

                if (!incl)

                    continue;

                else if (incl < 0)

                    return incl;



                if (!cblk->npasses)

                    cblk->nonzerobits = expn[bandno] + numgbits - 1 - tag_tree_decode(s, prec->zerobits + pos, 100);

                if ((newpasses = getnpasses(s)) < 0)

                    return newpasses;

                if ((llen = getlblockinc(s)) < 0)

                    return llen;

                cblk->lblock += llen;

                if ((ret = get_bits(s, av_log2(newpasses) + cblk->lblock)) < 0)

                    return ret;

                cblk->lengthinc = ret;

                cblk->npasses += newpasses;

            }

    }

    j2k_flush(s);



    if (codsty->csty & JPEG2000_CSTY_EPH) {

        if (bytestream2_peek_be16(&s->g) == JPEG2000_EPH) {

            bytestream2_skip(&s->g, 2);

        } else {

            av_log(s->avctx, AV_LOG_ERROR, "EPH marker not found.\n");

        }

    }



    for (bandno = 0; bandno < rlevel->nbands; bandno++){

        Jpeg2000Band *band = rlevel->band + bandno;

        int yi, cblknw = band->prec[precno].xi1 - band->prec[precno].xi0;

        for (yi = band->prec[precno].yi0; yi < band->prec[precno].yi1; yi++){

            int xi;

            for (xi = band->prec[precno].xi0; xi < band->prec[precno].xi1; xi++){

                Jpeg2000Cblk *cblk = band->cblk + yi * cblknw + xi;

                if (bytestream2_get_bytes_left(&s->g) < cblk->lengthinc)

                    return AVERROR(EINVAL);

                bytestream2_get_bufferu(&s->g, cblk->data, cblk->lengthinc);

                cblk->length += cblk->lengthinc;

                cblk->lengthinc = 0;

            }

        }

    }

    return 0;

}

static void avc_luma_vt_and_aver_dst_8x8_msa(const uint8_t *src,

                                             int32_t src_stride,

                                             uint8_t *dst, int32_t dst_stride)

{

    int32_t loop_cnt;

    int16_t filt_const0 = 0xfb01;

    int16_t filt_const1 = 0x1414;

    int16_t filt_const2 = 0x1fb;

    v16u8 dst0, dst1, dst2, dst3;

    v16i8 src0, src1, src2, src3, src4, src7, src8, src9, src10;

    v16i8 src10_r, src32_r, src76_r, src98_r;

    v16i8 src21_r, src43_r, src87_r, src109_r;

    v8i16 out0, out1, out2, out3;

    v16i8 filt0, filt1, filt2;



    filt0 = (v16i8) __msa_fill_h(filt_const0);

    filt1 = (v16i8) __msa_fill_h(filt_const1);

    filt2 = (v16i8) __msa_fill_h(filt_const2);



    LD_SB5(src, src_stride, src0, src1, src2, src3, src4);

    src += (5 * src_stride);



    XORI_B5_128_SB(src0, src1, src2, src3, src4);

    ILVR_B4_SB(src1, src0, src2, src1, src3, src2, src4, src3,

               src10_r, src21_r, src32_r, src43_r);



    for (loop_cnt = 2; loop_cnt--;) {

        LD_SB4(src, src_stride, src7, src8, src9, src10);

        src += (4 * src_stride);



        XORI_B4_128_SB(src7, src8, src9, src10);

        ILVR_B4_SB(src7, src4, src8, src7, src9, src8, src10, src9,

                   src76_r, src87_r, src98_r, src109_r);

        out0 = DPADD_SH3_SH(src10_r, src32_r, src76_r, filt0, filt1, filt2);

        out1 = DPADD_SH3_SH(src21_r, src43_r, src87_r, filt0, filt1, filt2);

        out2 = DPADD_SH3_SH(src32_r, src76_r, src98_r, filt0, filt1, filt2);

        out3 = DPADD_SH3_SH(src43_r, src87_r, src109_r, filt0, filt1, filt2);

        SRARI_H4_SH(out0, out1, out2, out3, 5);

        SAT_SH4_SH(out0, out1, out2, out3, 7);

        LD_UB4(dst, dst_stride, dst0, dst1, dst2, dst3);

        ILVR_D2_UB(dst1, dst0, dst3, dst2, dst0, dst1);

        CONVERT_UB_AVG_ST8x4_UB(out0, out1, out2, out3, dst0, dst1,

                                dst, dst_stride);

        dst += (4 * dst_stride);



        src10_r = src76_r;

        src32_r = src98_r;

        src21_r = src87_r;

        src43_r = src109_r;

        src4 = src10;

    }

}

int main (int argc, char **argv)

{

    int ret = 0, got_frame;



    if (argc != 4 && argc != 5) {

        fprintf(stderr, "usage: %s [-refcount=<old|new_norefcount|new_refcount>] "

                "input_file video_output_file audio_output_file\n"

                "API example program to show how to read frames from an input file.\n"

                "This program reads frames from a file, decodes them, and writes decoded\n"

                "video frames to a rawvideo file named video_output_file, and decoded\n"

                "audio frames to a rawaudio file named audio_output_file.\n\n"

                "If the -refcount option is specified, the program use the\n"

                "reference counting frame system which allows keeping a copy of\n"

                "the data for longer than one decode call. If unset, it's using\n"

                "the classic old method.\n"

                "\n", argv[0]);

        exit(1);

    }

    if (argc == 5) {

        const char *mode = argv[1] + strlen("-refcount=");

        if      (!strcmp(mode, "old"))            api_mode = API_MODE_OLD;

        else if (!strcmp(mode, "new_norefcount")) api_mode = API_MODE_NEW_API_NO_REF_COUNT;

        else if (!strcmp(mode, "new_refcount"))   api_mode = API_MODE_NEW_API_REF_COUNT;

        else {

            fprintf(stderr, "unknow mode '%s'\n", mode);

            exit(1);

        }

        argv++;

    }

    src_filename = argv[1];

    video_dst_filename = argv[2];

    audio_dst_filename = argv[3];



    /* register all formats and codecs */

    av_register_all();



    /* open input file, and allocate format context */

    if (avformat_open_input(&fmt_ctx, src_filename, NULL, NULL) < 0) {

        fprintf(stderr, "Could not open source file %s\n", src_filename);

        exit(1);

    }



    /* retrieve stream information */

    if (avformat_find_stream_info(fmt_ctx, NULL) < 0) {

        fprintf(stderr, "Could not find stream information\n");

        exit(1);

    }



    if (open_codec_context(&video_stream_idx, fmt_ctx, AVMEDIA_TYPE_VIDEO) >= 0) {

        video_stream = fmt_ctx->streams[video_stream_idx];

        video_dec_ctx = video_stream->codec;



        video_dst_file = fopen(video_dst_filename, "wb");

        if (!video_dst_file) {

            fprintf(stderr, "Could not open destination file %s\n", video_dst_filename);

            ret = 1;

            goto end;

        }



        /* allocate image where the decoded image will be put */

        ret = av_image_alloc(video_dst_data, video_dst_linesize,

                             video_dec_ctx->width, video_dec_ctx->height,

                             video_dec_ctx->pix_fmt, 1);

        if (ret < 0) {

            fprintf(stderr, "Could not allocate raw video buffer\n");

            goto end;

        }

        video_dst_bufsize = ret;

    }



    if (open_codec_context(&audio_stream_idx, fmt_ctx, AVMEDIA_TYPE_AUDIO) >= 0) {

        audio_stream = fmt_ctx->streams[audio_stream_idx];

        audio_dec_ctx = audio_stream->codec;

        audio_dst_file = fopen(audio_dst_filename, "wb");

        if (!audio_dst_file) {

            fprintf(stderr, "Could not open destination file %s\n", video_dst_filename);

            ret = 1;

            goto end;

        }

    }



    /* dump input information to stderr */

    av_dump_format(fmt_ctx, 0, src_filename, 0);



    if (!audio_stream && !video_stream) {

        fprintf(stderr, "Could not find audio or video stream in the input, aborting\n");

        ret = 1;

        goto end;

    }



    /* When using the new API, you need to use the libavutil/frame.h API, while

     * the classic frame management is available in libavcodec */

    if (api_mode == API_MODE_OLD)

        frame = avcodec_alloc_frame();

    else

        frame = av_frame_alloc();

    if (!frame) {

        fprintf(stderr, "Could not allocate frame\n");

        ret = AVERROR(ENOMEM);

        goto end;

    }



    /* initialize packet, set data to NULL, let the demuxer fill it */

    av_init_packet(&pkt);

    pkt.data = NULL;

    pkt.size = 0;



    if (video_stream)

        printf("Demuxing video from file '%s' into '%s'\n", src_filename, video_dst_filename);

    if (audio_stream)

        printf("Demuxing audio from file '%s' into '%s'\n", src_filename, audio_dst_filename);



    /* read frames from the file */

    while (av_read_frame(fmt_ctx, &pkt) >= 0) {

        AVPacket orig_pkt = pkt;

        do {

            ret = decode_packet(&got_frame, 0);

            if (ret < 0)

                break;

            pkt.data += ret;

            pkt.size -= ret;

        } while (pkt.size > 0);

        av_free_packet(&orig_pkt);

    }



    /* flush cached frames */

    pkt.data = NULL;

    pkt.size = 0;

    do {

        decode_packet(&got_frame, 1);

    } while (got_frame);



    printf("Demuxing succeeded.\n");



    if (video_stream) {

        printf("Play the output video file with the command:\n"

               "ffplay -f rawvideo -pix_fmt %s -video_size %dx%d %s\n",

               av_get_pix_fmt_name(video_dec_ctx->pix_fmt), video_dec_ctx->width, video_dec_ctx->height,

               video_dst_filename);

    }



    if (audio_stream) {

        enum AVSampleFormat sfmt = audio_dec_ctx->sample_fmt;

        int n_channels = audio_dec_ctx->channels;

        const char *fmt;



        if (av_sample_fmt_is_planar(sfmt)) {

            const char *packed = av_get_sample_fmt_name(sfmt);

            printf("Warning: the sample format the decoder produced is planar "

                   "(%s). This example will output the first channel only.\n",

                   packed ? packed : "?");

            sfmt = av_get_packed_sample_fmt(sfmt);

            n_channels = 1;

        }



        if ((ret = get_format_from_sample_fmt(&fmt, sfmt)) < 0)

            goto end;



        printf("Play the output audio file with the command:\n"

               "ffplay -f %s -ac %d -ar %d %s\n",

               fmt, n_channels, audio_dec_ctx->sample_rate,

               audio_dst_filename);

    }



end:

    if (video_dec_ctx)

        avcodec_close(video_dec_ctx);

    if (audio_dec_ctx)

        avcodec_close(audio_dec_ctx);

    avformat_close_input(&fmt_ctx);

    if (video_dst_file)

        fclose(video_dst_file);

    if (audio_dst_file)

        fclose(audio_dst_file);

    if (api_mode == API_MODE_OLD)

        avcodec_free_frame(&frame);

    else

        av_frame_free(&frame);

    av_free(video_dst_data[0]);



    return ret < 0;

}

void ff_celp_lp_synthesis_filterf(float *out,

                                  const float* filter_coeffs,

                                  const float* in,

                                  int buffer_length,

                                  int filter_length)

{

    int i,n;



    // Avoids a +1 in the inner loop.

    filter_length++;



    for (n = 0; n < buffer_length; n++) {

        out[n] = in[n];

        for (i = 1; i < filter_length; i++)

            out[n] -= filter_coeffs[i-1] * out[n-i];

    }

}

static int read_seek(AVFormatContext *s, int stream_index, int64_t timestamp, int flags)

{

    BinkDemuxContext *bink = s->priv_data;

    AVStream *vst = s->streams[0];



    if (!s->pb->seekable)

        return -1;



    /* seek to the first frame */

    if (avio_seek(s->pb, vst->index_entries[0].pos, SEEK_SET) < 0)

        return -1;



    bink->video_pts = 0;

    memset(bink->audio_pts, 0, sizeof(bink->audio_pts));

    bink->current_track = -1;

    return 0;

}

static int dvvideo_decode_frame(AVCodecContext *avctx, 

                                 void *data, int *data_size,

                                 UINT8 *buf, int buf_size)

{

    DVVideoDecodeContext *s = avctx->priv_data;

    int sct, dsf, apt, ds, nb_dif_segs, vs, width, height, i, packet_size;

    unsigned size;

    UINT8 *buf_ptr;

    const UINT16 *mb_pos_ptr;

    AVPicture *picture;



    /* parse id */

    init_get_bits(&s->gb, buf, buf_size);

    sct = get_bits(&s->gb, 3);

    if (sct != 0)

        return -1;

    skip_bits(&s->gb, 5);

    get_bits(&s->gb, 4); /* dsn (sequence number */

    get_bits(&s->gb, 1); /* fsc (channel number) */

    skip_bits(&s->gb, 3);

    get_bits(&s->gb, 8); /* dbn (diff block number 0-134) */



    dsf = get_bits(&s->gb, 1); /* 0 = NTSC 1 = PAL */

    if (get_bits(&s->gb, 1) != 0)

        return -1;

    skip_bits(&s->gb, 11);

    apt = get_bits(&s->gb, 3); /* apt */



    get_bits(&s->gb, 1); /* tf1 */

    skip_bits(&s->gb, 4);

    get_bits(&s->gb, 3); /* ap1 */



    get_bits(&s->gb, 1); /* tf2 */

    skip_bits(&s->gb, 4);

    get_bits(&s->gb, 3); /* ap2 */



    get_bits(&s->gb, 1); /* tf3 */

    skip_bits(&s->gb, 4);

    get_bits(&s->gb, 3); /* ap3 */



    /* init size */

    width = 720;

    if (dsf) {

        avctx->frame_rate = 25 * FRAME_RATE_BASE;

        packet_size = PAL_FRAME_SIZE;

        height = 576;

        nb_dif_segs = 12;

    } else {

        avctx->frame_rate = 30 * FRAME_RATE_BASE;

        packet_size = NTSC_FRAME_SIZE;

        height = 480;

        nb_dif_segs = 10;

    }

    /* NOTE: we only accept several full frames */

    if (buf_size < packet_size)

        return -1;



    /* XXX: is it correct to assume that 420 is always used in PAL

       mode ? */

    s->sampling_411 = !dsf;

    if (s->sampling_411) {

        mb_pos_ptr = dv_place_411;

        avctx->pix_fmt = PIX_FMT_YUV411P;

    } else {

        mb_pos_ptr = dv_place_420;

        avctx->pix_fmt = PIX_FMT_YUV420P;

    }



    avctx->width = width;

    avctx->height = height;



    if (avctx->flags & CODEC_FLAG_DR1 && avctx->get_buffer_callback)

    {

	s->width = -1;

	avctx->dr_buffer[0] = avctx->dr_buffer[1] = avctx->dr_buffer[2] = 0;

	if(avctx->get_buffer_callback(avctx, width, height, I_TYPE) < 0){

	    fprintf(stderr, "get_buffer() failed\n");

	    return -1;

	}

    }



    /* (re)alloc picture if needed */

    if (s->width != width || s->height != height) {

	if (!(avctx->flags & CODEC_FLAG_DR1))

	    for(i=0;i<3;i++) {

		if (avctx->dr_buffer[i] != s->current_picture[i])

		    av_freep(&s->current_picture[i]);

		avctx->dr_buffer[i] = 0;

	    }



        for(i=0;i<3;i++) {

	    if (avctx->dr_buffer[i]) {

		s->current_picture[i] = avctx->dr_buffer[i];

		s->linesize[i] = (i == 0) ? avctx->dr_stride : avctx->dr_uvstride;

	    } else {

		size = width * height;

		s->linesize[i] = width;

		if (i >= 1) {

		    size >>= 2;

		    s->linesize[i] >>= s->sampling_411 ? 2 : 1;

		}

		s->current_picture[i] = av_malloc(size);

	    }

            if (!s->current_picture[i])

                return -1;

        }

        s->width = width;

        s->height = height;

    }



    /* for each DIF segment */

    buf_ptr = buf;

    for (ds = 0; ds < nb_dif_segs; ds++) {

        buf_ptr += 6 * 80; /* skip DIF segment header */



        for(vs = 0; vs < 27; vs++) {

            if ((vs % 3) == 0) {

                /* skip audio block */

                buf_ptr += 80;

            }

            dv_decode_video_segment(s, buf_ptr, mb_pos_ptr);

            buf_ptr += 5 * 80;

            mb_pos_ptr += 5;

        }

    }



    emms_c();



    /* return image */

    *data_size = sizeof(AVPicture);

    picture = data;

    for(i=0;i<3;i++) {

        picture->data[i] = s->current_picture[i];

        picture->linesize[i] = s->linesize[i];

    }

    return packet_size;

}

static int audio_read_header(AVFormatContext *s1, AVFormatParameters *ap)

{

    AudioData *s = s1->priv_data;

    AVStream *st;

    int ret;



    if (!ap || ap->sample_rate <= 0 || ap->channels <= 0)

        return -1;



    st = av_new_stream(s1, 0);

    if (!st) {

        return -ENOMEM;

    }

    s->sample_rate = ap->sample_rate;

    s->channels = ap->channels;



    ret = audio_open(s, 0, ap->device);

    if (ret < 0) {

        av_free(st);

        return AVERROR_IO;

    }



    /* take real parameters */

    st->codec->codec_type = CODEC_TYPE_AUDIO;

    st->codec->codec_id = s->codec_id;

    st->codec->sample_rate = s->sample_rate;

    st->codec->channels = s->channels;



    av_set_pts_info(st, 64, 1, 1000000);  /* 64 bits pts in us */

    return 0;

}

char *ff_get_ref_perms_string(char *buf, size_t buf_size, int perms)

{

    snprintf(buf, buf_size, "%s%s%s%s%s",

             perms & AV_PERM_READ      ? "r" : "",

             perms & AV_PERM_WRITE     ? "w" : "",

             perms & AV_PERM_PRESERVE  ? "p" : "",

             perms & AV_PERM_REUSE     ? "u" : "",

             perms & AV_PERM_REUSE2    ? "U" : "");

    return buf;

}

static void gif_copy_img_rect(const uint32_t *src, uint32_t *dst,

                              int linesize, int l, int t, int w, int h)

{

    const int y_start = t * linesize;

    const uint32_t *src_px, *src_pr,

                   *src_py = src + y_start,

                   *dst_py = dst + y_start;

    const uint32_t *src_pb = src_py + t * linesize;

    uint32_t *dst_px;



    for (; src_py < src_pb; src_py += linesize, dst_py += linesize) {

        src_px = src_py + l;

        dst_px = (uint32_t *)dst_py + l;

        src_pr = src_px + w;



        for (; src_px < src_pr; src_px++, dst_px++)

            *dst_px = *src_px;

    }

}

static int alac_encode_frame(AVCodecContext *avctx, AVPacket *avpkt,

                             const AVFrame *frame, int *got_packet_ptr)

{

    AlacEncodeContext *s = avctx->priv_data;

    int out_bytes, max_frame_size, ret;



    s->frame_size = frame->nb_samples;



    if (frame->nb_samples < DEFAULT_FRAME_SIZE)

        max_frame_size = get_max_frame_size(s->frame_size, avctx->channels,

                                            avctx->bits_per_raw_sample);

    else

        max_frame_size = s->max_coded_frame_size;



    if ((ret = ff_alloc_packet2(avctx, avpkt, 2 * max_frame_size)))

        return ret;



    /* use verbatim mode for compression_level 0 */

    if (s->compression_level) {

        s->verbatim   = 0;

        s->extra_bits = avctx->bits_per_raw_sample - 16;

    } else {

        s->verbatim   = 1;

        s->extra_bits = 0;

    }



    out_bytes = write_frame(s, avpkt, frame->extended_data);



    if (out_bytes > max_frame_size) {

        /* frame too large. use verbatim mode */

        s->verbatim = 1;

        s->extra_bits = 0;

        out_bytes = write_frame(s, avpkt, frame->extended_data);

    }



    avpkt->size = out_bytes;

    *got_packet_ptr = 1;

    return 0;

}

static int xan_decode_frame_type1(AVCodecContext *avctx)

{

    XanContext *s = avctx->priv_data;

    uint8_t *ybuf, *src = s->scratch_buffer;

    int cur, last;

    int i, j;

    int ret;



    if ((ret = xan_decode_chroma(avctx, bytestream2_get_le32(&s->gb))) != 0)

        return ret;



    bytestream2_seek(&s->gb, 16, SEEK_SET);

    ret = xan_unpack_luma(s, src,

                          s->buffer_size >> 1);

    if (ret) {

        av_log(avctx, AV_LOG_ERROR, "Luma decoding failed\n");

        return ret;

    }



    ybuf = s->y_buffer;

    for (i = 0; i < avctx->height; i++) {

        last = (ybuf[0] + (*src++ << 1)) & 0x3F;

        ybuf[0] = last;

        for (j = 1; j < avctx->width - 1; j += 2) {

            cur = (ybuf[j + 1] + (*src++ << 1)) & 0x3F;

            ybuf[j]   = (last + cur) >> 1;

            ybuf[j+1] = cur;

            last = cur;

        }

        ybuf[j] = last;

        ybuf += avctx->width;

    }



    src = s->y_buffer;

    ybuf = s->pic.data[0];

    for (j = 0; j < avctx->height; j++) {

        for (i = 0; i < avctx->width; i++)

            ybuf[i] = (src[i] << 2) | (src[i] >> 3);

        src  += avctx->width;

        ybuf += s->pic.linesize[0];

    }



    return 0;

}

static int aac_sync(uint64_t state, AACAC3ParseContext *hdr_info,

        int *need_next_header, int *new_frame_start)

{

    GetBitContext bits;

    int size, rdb, ch, sr;

    union {

        uint64_t u64;

        uint8_t  u8[8];

    } tmp;



    tmp.u64 = be2me_64(state);

    init_get_bits(&bits, tmp.u8+8-AAC_HEADER_SIZE, AAC_HEADER_SIZE * 8);



    if(get_bits(&bits, 12) != 0xfff)

        return 0;



    skip_bits1(&bits);          /* id */

    skip_bits(&bits, 2);        /* layer */

    skip_bits1(&bits);          /* protection_absent */

    skip_bits(&bits, 2);        /* profile_objecttype */

    sr = get_bits(&bits, 4);    /* sample_frequency_index */

    if(!ff_mpeg4audio_sample_rates[sr])

        return 0;

    skip_bits1(&bits);          /* private_bit */

    ch = get_bits(&bits, 3);    /* channel_configuration */

    if(!ff_mpeg4audio_channels[ch])

        return 0;

    skip_bits1(&bits);          /* original/copy */

    skip_bits1(&bits);          /* home */



    /* adts_variable_header */

    skip_bits1(&bits);          /* copyright_identification_bit */

    skip_bits1(&bits);          /* copyright_identification_start */

    size = get_bits(&bits, 13); /* aac_frame_length */

    if(size < AAC_HEADER_SIZE)

        return 0;



    skip_bits(&bits, 11);       /* adts_buffer_fullness */

    rdb = get_bits(&bits, 2);   /* number_of_raw_data_blocks_in_frame */



    hdr_info->channels = ff_mpeg4audio_channels[ch];

    hdr_info->sample_rate = ff_mpeg4audio_sample_rates[sr];

    hdr_info->samples = (rdb + 1) * 1024;

    hdr_info->bit_rate = size * 8 * hdr_info->sample_rate / hdr_info->samples;



    *need_next_header = 0;

    *new_frame_start  = 1;

    return size;

}

void decode_mb_mode(VP8Context *s, VP8Macroblock *mb, int mb_x, int mb_y,

                    uint8_t *segment, uint8_t *ref, int layout, int is_vp7)

{

    VP56RangeCoder *c = &s->c;

    static const char *vp7_feature_name[] = { "q-index",

                                              "lf-delta",

                                              "partial-golden-update",

                                              "blit-pitch" };

    if (is_vp7) {

        int i;

        *segment = 0;

        for (i = 0; i < 4; i++) {

            if (s->feature_enabled[i]) {

                if (vp56_rac_get_prob_branchy(c, s->feature_present_prob[i])) {

                      int index = vp8_rac_get_tree(c, vp7_feature_index_tree,

                                                   s->feature_index_prob[i]);

                      av_log(s->avctx, AV_LOG_WARNING,

                             "Feature %s present in macroblock (value 0x%x)\n",

                             vp7_feature_name[i], s->feature_value[i][index]);

                }

           }

        }

    } else if (s->segmentation.update_map) {

        int bit  = vp56_rac_get_prob(c, s->prob->segmentid[0]);

        *segment = vp56_rac_get_prob(c, s->prob->segmentid[1+bit]) + 2*bit;

    } else if (s->segmentation.enabled)

        *segment = ref ? *ref : *segment;

    mb->segment = *segment;



    mb->skip = s->mbskip_enabled ? vp56_rac_get_prob(c, s->prob->mbskip) : 0;



    if (s->keyframe) {

        mb->mode = vp8_rac_get_tree(c, vp8_pred16x16_tree_intra,

                                    vp8_pred16x16_prob_intra);



        if (mb->mode == MODE_I4x4) {

            decode_intra4x4_modes(s, c, mb, mb_x, 1, layout);

        } else {

            const uint32_t modes = (is_vp7 ? vp7_pred4x4_mode

                                           : vp8_pred4x4_mode)[mb->mode] * 0x01010101u;

            if (s->mb_layout)

                AV_WN32A(mb->intra4x4_pred_mode_top, modes);

            else

                AV_WN32A(s->intra4x4_pred_mode_top + 4 * mb_x, modes);

            AV_WN32A(s->intra4x4_pred_mode_left, modes);

        }



        mb->chroma_pred_mode = vp8_rac_get_tree(c, vp8_pred8x8c_tree,

                                                vp8_pred8x8c_prob_intra);

        mb->ref_frame        = VP56_FRAME_CURRENT;

    } else if (vp56_rac_get_prob_branchy(c, s->prob->intra)) {

        // inter MB, 16.2

        if (vp56_rac_get_prob_branchy(c, s->prob->last))

            mb->ref_frame =

                (!is_vp7 && vp56_rac_get_prob(c, s->prob->golden)) ? VP56_FRAME_GOLDEN2 /* altref */

                                                                   : VP56_FRAME_GOLDEN;

        else

            mb->ref_frame = VP56_FRAME_PREVIOUS;

        s->ref_count[mb->ref_frame - 1]++;



        // motion vectors, 16.3

        if (is_vp7)

            vp7_decode_mvs(s, mb, mb_x, mb_y, layout);

        else

            vp8_decode_mvs(s, mb, mb_x, mb_y, layout);

    } else {

        // intra MB, 16.1

        mb->mode = vp8_rac_get_tree(c, vp8_pred16x16_tree_inter, s->prob->pred16x16);



        if (mb->mode == MODE_I4x4)

            decode_intra4x4_modes(s, c, mb, mb_x, 0, layout);



        mb->chroma_pred_mode = vp8_rac_get_tree(c, vp8_pred8x8c_tree,

                                                s->prob->pred8x8c);

        mb->ref_frame        = VP56_FRAME_CURRENT;

        mb->partitioning     = VP8_SPLITMVMODE_NONE;

        AV_ZERO32(&mb->bmv[0]);

    }

}

