static int get_cox(J2kDecoderContext *s, J2kCodingStyle *c)

{

    if (s->buf_end - s->buf < 5)

        return AVERROR(EINVAL);

          c->nreslevels = bytestream_get_byte(&s->buf) + 1; // num of resolution levels - 1

     c->log2_cblk_width = bytestream_get_byte(&s->buf) + 2; // cblk width

    c->log2_cblk_height = bytestream_get_byte(&s->buf) + 2; // cblk height



    c->cblk_style = bytestream_get_byte(&s->buf);

    if (c->cblk_style != 0){ // cblk style

        av_log(s->avctx, AV_LOG_WARNING, "extra cblk styles %X\n", c->cblk_style);

    }

    c->transform = bytestream_get_byte(&s->buf); // transformation

    if (c->csty & J2K_CSTY_PREC) {

        int i;

        for (i = 0; i < c->nreslevels; i++)

            bytestream_get_byte(&s->buf);

    }

    return 0;

}

static int flic_decode_frame_8BPP(AVCodecContext *avctx,

                                  void *data, int *got_frame,

                                  const uint8_t *buf, int buf_size)

{

    FlicDecodeContext *s = avctx->priv_data;



    GetByteContext g2;

    int pixel_ptr;

    int palette_ptr;

    unsigned char palette_idx1;

    unsigned char palette_idx2;



    unsigned int frame_size;

    int num_chunks;



    unsigned int chunk_size;

    int chunk_type;



    int i, j, ret;



    int color_packets;

    int color_changes;

    int color_shift;

    unsigned char r, g, b;



    int lines;

    int compressed_lines;

    int starting_line;

    signed short line_packets;

    int y_ptr;

    int byte_run;

    int pixel_skip;

    int pixel_countdown;

    unsigned char *pixels;

    unsigned int pixel_limit;



    bytestream2_init(&g2, buf, buf_size);



    if ((ret = ff_reget_buffer(avctx, s->frame)) < 0)

        return ret;



    pixels = s->frame->data[0];

    pixel_limit = s->avctx->height * s->frame->linesize[0];

    if (buf_size < 16 || buf_size > INT_MAX - (3 * 256 + AV_INPUT_BUFFER_PADDING_SIZE))


    frame_size = bytestream2_get_le32(&g2);

    if (frame_size > buf_size)

        frame_size = buf_size;

    bytestream2_skip(&g2, 2); /* skip the magic number */

    num_chunks = bytestream2_get_le16(&g2);

    bytestream2_skip(&g2, 8);  /* skip padding */



    if (frame_size < 16)




    frame_size -= 16;



    /* iterate through the chunks */

    while ((frame_size >= 6) && (num_chunks > 0) &&

            bytestream2_get_bytes_left(&g2) >= 4) {

        int stream_ptr_after_chunk;

        chunk_size = bytestream2_get_le32(&g2);

        if (chunk_size > frame_size) {

            av_log(avctx, AV_LOG_WARNING,

                   "Invalid chunk_size = %u > frame_size = %u\n", chunk_size, frame_size);

            chunk_size = frame_size;

        }

        stream_ptr_after_chunk = bytestream2_tell(&g2) - 4 + chunk_size;



        chunk_type = bytestream2_get_le16(&g2);



        switch (chunk_type) {

        case FLI_256_COLOR:

        case FLI_COLOR:

            /* check special case: If this file is from the Magic Carpet

             * game and uses 6-bit colors even though it reports 256-color

             * chunks in a 0xAF12-type file (fli_type is set to 0xAF13 during

             * initialization) */

            if ((chunk_type == FLI_256_COLOR) && (s->fli_type != FLC_MAGIC_CARPET_SYNTHETIC_TYPE_CODE))

                color_shift = 0;

            else

                color_shift = 2;

            /* set up the palette */

            color_packets = bytestream2_get_le16(&g2);

            palette_ptr = 0;

            for (i = 0; i < color_packets; i++) {

                /* first byte is how many colors to skip */

                palette_ptr += bytestream2_get_byte(&g2);



                /* next byte indicates how many entries to change */

                color_changes = bytestream2_get_byte(&g2);



                /* if there are 0 color changes, there are actually 256 */

                if (color_changes == 0)

                    color_changes = 256;



                if (bytestream2_tell(&g2) + color_changes * 3 > stream_ptr_after_chunk)

                    break;



                for (j = 0; j < color_changes; j++) {

                    unsigned int entry;



                    /* wrap around, for good measure */

                    if ((unsigned)palette_ptr >= 256)

                        palette_ptr = 0;



                    r = bytestream2_get_byte(&g2) << color_shift;

                    g = bytestream2_get_byte(&g2) << color_shift;

                    b = bytestream2_get_byte(&g2) << color_shift;

                    entry = 0xFFU << 24 | r << 16 | g << 8 | b;

                    if (color_shift == 2)

                        entry |= entry >> 6 & 0x30303;

                    if (s->palette[palette_ptr] != entry)

                        s->new_palette = 1;

                    s->palette[palette_ptr++] = entry;

                }

            }

            break;



        case FLI_DELTA:

            y_ptr = 0;

            compressed_lines = bytestream2_get_le16(&g2);

            while (compressed_lines > 0) {

                if (bytestream2_tell(&g2) + 2 > stream_ptr_after_chunk)

                    break;

                if (y_ptr > pixel_limit)


                line_packets = bytestream2_get_le16(&g2);

                if ((line_packets & 0xC000) == 0xC000) {

                    // line skip opcode

                    line_packets = -line_packets;

                    if (line_packets > s->avctx->height)


                    y_ptr += line_packets * s->frame->linesize[0];

                } else if ((line_packets & 0xC000) == 0x4000) {

                    av_log(avctx, AV_LOG_ERROR, "Undefined opcode (%x) in DELTA_FLI\n", line_packets);

                } else if ((line_packets & 0xC000) == 0x8000) {

                    // "last byte" opcode

                    pixel_ptr= y_ptr + s->frame->linesize[0] - 1;

                    CHECK_PIXEL_PTR(0);

                    pixels[pixel_ptr] = line_packets & 0xff;

                } else {

                    compressed_lines--;

                    pixel_ptr = y_ptr;

                    CHECK_PIXEL_PTR(0);

                    pixel_countdown = s->avctx->width;

                    for (i = 0; i < line_packets; i++) {

                        if (bytestream2_tell(&g2) + 2 > stream_ptr_after_chunk)

                            break;

                        /* account for the skip bytes */

                        pixel_skip = bytestream2_get_byte(&g2);

                        pixel_ptr += pixel_skip;

                        pixel_countdown -= pixel_skip;

                        byte_run = sign_extend(bytestream2_get_byte(&g2), 8);

                        if (byte_run < 0) {

                            byte_run = -byte_run;

                            palette_idx1 = bytestream2_get_byte(&g2);

                            palette_idx2 = bytestream2_get_byte(&g2);

                            CHECK_PIXEL_PTR(byte_run * 2);

                            for (j = 0; j < byte_run; j++, pixel_countdown -= 2) {

                                pixels[pixel_ptr++] = palette_idx1;

                                pixels[pixel_ptr++] = palette_idx2;

                            }

                        } else {

                            CHECK_PIXEL_PTR(byte_run * 2);

                            if (bytestream2_tell(&g2) + byte_run * 2 > stream_ptr_after_chunk)

                                break;

                            for (j = 0; j < byte_run * 2; j++, pixel_countdown--) {

                                pixels[pixel_ptr++] = bytestream2_get_byte(&g2);

                            }

                        }

                    }



                    y_ptr += s->frame->linesize[0];

                }

            }

            break;



        case FLI_LC:

            /* line compressed */

            starting_line = bytestream2_get_le16(&g2);



            y_ptr = 0;

            y_ptr += starting_line * s->frame->linesize[0];



            compressed_lines = bytestream2_get_le16(&g2);

            while (compressed_lines > 0) {

                pixel_ptr = y_ptr;

                CHECK_PIXEL_PTR(0);

                pixel_countdown = s->avctx->width;

                if (bytestream2_tell(&g2) + 1 > stream_ptr_after_chunk)

                    break;

                line_packets = bytestream2_get_byte(&g2);

                if (line_packets > 0) {

                    for (i = 0; i < line_packets; i++) {

                        /* account for the skip bytes */

                        if (bytestream2_tell(&g2) + 1 > stream_ptr_after_chunk)

                            break;

                        pixel_skip = bytestream2_get_byte(&g2);

                        pixel_ptr += pixel_skip;

                        pixel_countdown -= pixel_skip;

                        byte_run = sign_extend(bytestream2_get_byte(&g2),8);

                        if (byte_run > 0) {

                            CHECK_PIXEL_PTR(byte_run);

                            if (bytestream2_tell(&g2) + byte_run > stream_ptr_after_chunk)

                                break;

                            for (j = 0; j < byte_run; j++, pixel_countdown--) {

                                pixels[pixel_ptr++] = bytestream2_get_byte(&g2);

                            }

                        } else if (byte_run < 0) {

                            byte_run = -byte_run;

                            palette_idx1 = bytestream2_get_byte(&g2);

                            CHECK_PIXEL_PTR(byte_run);

                            for (j = 0; j < byte_run; j++, pixel_countdown--) {

                                pixels[pixel_ptr++] = palette_idx1;

                            }

                        }

                    }

                }



                y_ptr += s->frame->linesize[0];

                compressed_lines--;

            }

            break;



        case FLI_BLACK:

            /* set the whole frame to color 0 (which is usually black) */

            memset(pixels, 0,

                s->frame->linesize[0] * s->avctx->height);

            break;



        case FLI_BRUN:

            /* Byte run compression: This chunk type only occurs in the first

             * FLI frame and it will update the entire frame. */

            y_ptr = 0;

            for (lines = 0; lines < s->avctx->height; lines++) {

                pixel_ptr = y_ptr;

                /* disregard the line packets; instead, iterate through all

                 * pixels on a row */

                 bytestream2_skip(&g2, 1);

                pixel_countdown = s->avctx->width;

                while (pixel_countdown > 0) {

                    if (bytestream2_tell(&g2) + 1 > stream_ptr_after_chunk)

                        break;

                    byte_run = sign_extend(bytestream2_get_byte(&g2), 8);

                    if (!byte_run) {

                        av_log(avctx, AV_LOG_ERROR, "Invalid byte run value.\n");


                    }



                    if (byte_run > 0) {

                        palette_idx1 = bytestream2_get_byte(&g2);

                        CHECK_PIXEL_PTR(byte_run);

                        for (j = 0; j < byte_run; j++) {

                            pixels[pixel_ptr++] = palette_idx1;

                            pixel_countdown--;

                            if (pixel_countdown < 0)

                                av_log(avctx, AV_LOG_ERROR, "pixel_countdown < 0 (%d) at line %d\n",

                                       pixel_countdown, lines);

                        }

                    } else {  /* copy bytes if byte_run < 0 */

                        byte_run = -byte_run;

                        CHECK_PIXEL_PTR(byte_run);

                        if (bytestream2_tell(&g2) + byte_run > stream_ptr_after_chunk)

                            break;

                        for (j = 0; j < byte_run; j++) {

                            pixels[pixel_ptr++] = bytestream2_get_byte(&g2);

                            pixel_countdown--;

                            if (pixel_countdown < 0)

                                av_log(avctx, AV_LOG_ERROR, "pixel_countdown < 0 (%d) at line %d\n",

                                       pixel_countdown, lines);

                        }

                    }

                }



                y_ptr += s->frame->linesize[0];

            }

            break;



        case FLI_COPY:

            /* copy the chunk (uncompressed frame) */

            if (chunk_size - 6 != FFALIGN(s->avctx->width, 4) * s->avctx->height) {

                av_log(avctx, AV_LOG_ERROR, "In chunk FLI_COPY : source data (%d bytes) " \

                       "has incorrect size, skipping chunk\n", chunk_size - 6);

                bytestream2_skip(&g2, chunk_size - 6);

            } else {

                for (y_ptr = 0; y_ptr < s->frame->linesize[0] * s->avctx->height;

                     y_ptr += s->frame->linesize[0]) {

                    bytestream2_get_buffer(&g2, &pixels[y_ptr],

                                           s->avctx->width);

                    if (s->avctx->width & 3)

                        bytestream2_skip(&g2, 4 - (s->avctx->width & 3));

                }

            }

            break;



        case FLI_MINI:

            /* some sort of a thumbnail? disregard this chunk... */

            break;



        default:

            av_log(avctx, AV_LOG_ERROR, "Unrecognized chunk type: %d\n", chunk_type);

            break;

        }



        if (stream_ptr_after_chunk - bytestream2_tell(&g2) >= 0) {

            bytestream2_skip(&g2, stream_ptr_after_chunk - bytestream2_tell(&g2));

        } else {

            av_log(avctx, AV_LOG_ERROR, "Chunk overread\n");

            break;

        }



        frame_size -= chunk_size;

        num_chunks--;

    }



    /* by the end of the chunk, the stream ptr should equal the frame

     * size (minus 1 or 2, possibly); if it doesn't, issue a warning */

    if (bytestream2_get_bytes_left(&g2) > 2)

        av_log(avctx, AV_LOG_ERROR, "Processed FLI chunk where chunk size = %d " \

               "and final chunk ptr = %d\n", buf_size,

               buf_size - bytestream2_get_bytes_left(&g2));



    /* make the palette available on the way out */

    memcpy(s->frame->data[1], s->palette, AVPALETTE_SIZE);

    if (s->new_palette) {

        s->frame->palette_has_changed = 1;

        s->new_palette = 0;

    }



    if ((ret = av_frame_ref(data, s->frame)) < 0)

        return ret;



    *got_frame = 1;



    return buf_size;

}

static void write_streaminfo(FlacEncodeContext *s, uint8_t *header)

{

    PutBitContext pb;



    memset(header, 0, FLAC_STREAMINFO_SIZE);

    init_put_bits(&pb, header, FLAC_STREAMINFO_SIZE);



    /* streaminfo metadata block */

    put_bits(&pb, 16, s->avctx->frame_size);

    put_bits(&pb, 16, s->avctx->frame_size);

    put_bits(&pb, 24, 0);

    put_bits(&pb, 24, s->max_framesize);

    put_bits(&pb, 20, s->samplerate);

    put_bits(&pb, 3, s->channels-1);

    put_bits(&pb, 5, 15);       /* bits per sample - 1 */

    /* write 36-bit sample count in 2 put_bits() calls */

    put_bits(&pb, 24, (s->sample_count & 0xFFFFFF000LL) >> 12);

    put_bits(&pb, 12,  s->sample_count & 0x000000FFFLL);

    flush_put_bits(&pb);

    /* MD5 signature = 0 */

}

static void dequantize_slice_buffered(SnowContext *s, slice_buffer * sb, SubBand *b, IDWTELEM *src, int stride, int start_y, int end_y){

    const int w= b->width;

    const int qlog= av_clip(s->qlog + b->qlog, 0, QROOT*16);

    const int qmul= ff_qexp[qlog&(QROOT-1)]<<(qlog>>QSHIFT);

    const int qadd= (s->qbias*qmul)>>QBIAS_SHIFT;

    int x,y;



    if(s->qlog == LOSSLESS_QLOG) return;



    for(y=start_y; y<end_y; y++){

//        DWTELEM * line = slice_buffer_get_line_from_address(sb, src + (y * stride));

        IDWTELEM * line = slice_buffer_get_line(sb, (y * b->stride_line) + b->buf_y_offset) + b->buf_x_offset;

        for(x=0; x<w; x++){

            int i= line[x];

            if(i<0){

                line[x]= -((-i*qmul + qadd)>>(QEXPSHIFT)); //FIXME try different bias

            }else if(i>0){

                line[x]=  (( i*qmul + qadd)>>(QEXPSHIFT));

            }

        }

    }

}

static int wav_write_header(AVFormatContext *s)

{

    WAVContext *wav = s->priv_data;

    AVIOContext *pb = s->pb;

    int64_t fmt, fact;



    ffio_wfourcc(pb, "RIFF");

    avio_wl32(pb, 0); /* file length */

    ffio_wfourcc(pb, "WAVE");



    /* format header */

    fmt = ff_start_tag(pb, "fmt ");

    if (ff_put_wav_header(pb, s->streams[0]->codec) < 0) {

        av_log(s, AV_LOG_ERROR, "%s codec not supported in WAVE format\n",

               s->streams[0]->codec->codec ? s->streams[0]->codec->codec->name : "NONE");

        av_free(wav);

        return -1;

    }

    ff_end_tag(pb, fmt);



    if (s->streams[0]->codec->codec_tag != 0x01 /* hence for all other than PCM */

        && s->pb->seekable) {

        fact = ff_start_tag(pb, "fact");

        avio_wl32(pb, 0);

        ff_end_tag(pb, fact);

    }



    av_set_pts_info(s->streams[0], 64, 1, s->streams[0]->codec->sample_rate);

    wav->maxpts = wav->last_duration = 0;

    wav->minpts = INT64_MAX;



    /* data header */

    wav->data = ff_start_tag(pb, "data");



    avio_flush(pb);



    return 0;

}

void ff_llviddsp_init_x86(LLVidDSPContext *c)

{

    int cpu_flags = av_get_cpu_flags();



#if HAVE_INLINE_ASM && HAVE_7REGS && ARCH_X86_32

    if (cpu_flags & AV_CPU_FLAG_CMOV)

        c->add_median_pred = add_median_pred_cmov;

#endif



    if (ARCH_X86_32 && EXTERNAL_MMX(cpu_flags)) {

        c->add_bytes = ff_add_bytes_mmx;

    }



    if (ARCH_X86_32 && EXTERNAL_MMXEXT(cpu_flags)) {

        /* slower than cmov version on AMD */

        if (!(cpu_flags & AV_CPU_FLAG_3DNOW))

            c->add_median_pred = ff_add_median_pred_mmxext;

    }



    if (EXTERNAL_SSE2(cpu_flags)) {

        c->add_bytes       = ff_add_bytes_sse2;

        c->add_median_pred = ff_add_median_pred_sse2;

    }



    if (EXTERNAL_SSSE3(cpu_flags)) {

        c->add_left_pred = ff_add_left_pred_ssse3;

        c->add_left_pred_int16 = ff_add_left_pred_int16_ssse3;

        c->add_gradient_pred   = ff_add_gradient_pred_ssse3;

    }



    if (EXTERNAL_SSSE3_FAST(cpu_flags)) {

        c->add_left_pred = ff_add_left_pred_unaligned_ssse3;

    }



    if (EXTERNAL_SSE4(cpu_flags)) {

        c->add_left_pred_int16 = ff_add_left_pred_int16_sse4;

    }

    if (EXTERNAL_AVX2_FAST(cpu_flags)) {

        c->add_bytes       = ff_add_bytes_avx2;

        c->add_left_pred   = ff_add_left_pred_unaligned_avx2;

        c->add_gradient_pred = ff_add_gradient_pred_avx2;

    }

}

static av_cold int libgsm_init(AVCodecContext *avctx) {

    if (avctx->channels > 1) {

        av_log(avctx, AV_LOG_ERROR, "Mono required for GSM, got %d channels\n",

               avctx->channels);

        return -1;

    }



    if(avctx->codec->decode){

        if(!avctx->channels)

            avctx->channels= 1;



        if(!avctx->sample_rate)

            avctx->sample_rate= 8000;



        avctx->sample_fmt = AV_SAMPLE_FMT_S16;

    }else{

        if (avctx->sample_rate != 8000) {

            av_log(avctx, AV_LOG_ERROR, "Sample rate 8000Hz required for GSM, got %dHz\n",

                avctx->sample_rate);

            if(avctx->strict_std_compliance > FF_COMPLIANCE_UNOFFICIAL)

                return -1;

        }

        if (avctx->bit_rate != 13000 /* Official */ &&

            avctx->bit_rate != 13200 /* Very common */ &&

            avctx->bit_rate != 0 /* Unknown; a.o. mov does not set bitrate when decoding */ ) {

            av_log(avctx, AV_LOG_ERROR, "Bitrate 13000bps required for GSM, got %dbps\n",

                avctx->bit_rate);

            if(avctx->strict_std_compliance > FF_COMPLIANCE_UNOFFICIAL)

                return -1;

        }

    }



    avctx->priv_data = gsm_create();



    switch(avctx->codec_id) {

    case CODEC_ID_GSM:

        avctx->frame_size = GSM_FRAME_SIZE;

        avctx->block_align = GSM_BLOCK_SIZE;

        break;

    case CODEC_ID_GSM_MS: {

        int one = 1;

        gsm_option(avctx->priv_data, GSM_OPT_WAV49, &one);

        avctx->frame_size = 2*GSM_FRAME_SIZE;

        avctx->block_align = GSM_MS_BLOCK_SIZE;

        }

    }



    avctx->coded_frame= avcodec_alloc_frame();

    avctx->coded_frame->key_frame= 1;



    return 0;

}

static int h261_decode_frame(AVCodecContext *avctx,

                             void *data, int *data_size,

                             uint8_t *buf, int buf_size)

{

    H261Context *h= avctx->priv_data;

    MpegEncContext *s = &h->s;

    int ret;

    AVFrame *pict = data;



#ifdef DEBUG

    printf("*****frame %d size=%d\n", avctx->frame_number, buf_size);

    printf("bytes=%x %x %x %x\n", buf[0], buf[1], buf[2], buf[3]);

#endif

    s->flags= avctx->flags;

    s->flags2= avctx->flags2;



    /* no supplementary picture */

    if (buf_size == 0) {

        return 0;

    }



    h->gob_start_code_skipped=0;



retry:



    init_get_bits(&s->gb, buf, buf_size*8);



    if(!s->context_initialized){

        if (MPV_common_init(s) < 0) //we need the idct permutaton for reading a custom matrix

            return -1;

    }



    //we need to set current_picture_ptr before reading the header, otherwise we cant store anyting im there

    if(s->current_picture_ptr==NULL || s->current_picture_ptr->data[0]){

        int i= ff_find_unused_picture(s, 0);

        s->current_picture_ptr= &s->picture[i];

    }



    ret = h261_decode_picture_header(h);



    /* skip if the header was thrashed */

    if (ret < 0){

        av_log(s->avctx, AV_LOG_ERROR, "header damaged\n");

        return -1;

    }



    if (s->width != avctx->coded_width || s->height != avctx->coded_height){

        ParseContext pc= s->parse_context; //FIXME move these demuxng hack to avformat

        s->parse_context.buffer=0;

        MPV_common_end(s);

        s->parse_context= pc;

    }

    if (!s->context_initialized) {

        avcodec_set_dimensions(avctx, s->width, s->height);



        goto retry;

    }



    // for hurry_up==5

    s->current_picture.pict_type= s->pict_type;

    s->current_picture.key_frame= s->pict_type == I_TYPE;



    /* skip everything if we are in a hurry>=5 */

    if(avctx->hurry_up>=5) return get_consumed_bytes(s, buf_size);



    if(MPV_frame_start(s, avctx) < 0)

        return -1;



    ff_er_frame_start(s);



    /* decode each macroblock */

    s->mb_x=0;

    s->mb_y=0;



    while(h->gob_number < (s->mb_height==18 ? 12 : 5)){

        if(ff_h261_resync(h)<0)

            break;

        h261_decode_gob(h);

    }

    MPV_frame_end(s);



assert(s->current_picture.pict_type == s->current_picture_ptr->pict_type);

assert(s->current_picture.pict_type == s->pict_type);

    *pict= *(AVFrame*)s->current_picture_ptr;

    ff_print_debug_info(s, pict);



    /* Return the Picture timestamp as the frame number */

    /* we substract 1 because it is added on utils.c    */

    avctx->frame_number = s->picture_number - 1;



    *data_size = sizeof(AVFrame);



    return get_consumed_bytes(s, buf_size);

}

static int mov_read_uuid(MOVContext *c, AVIOContext *pb, MOVAtom atom)

{

    AVStream *st;

    MOVStreamContext *sc;

    int64_t ret;

    uint8_t uuid[16];

    static const uint8_t uuid_isml_manifest[] = {

        0xa5, 0xd4, 0x0b, 0x30, 0xe8, 0x14, 0x11, 0xdd,

        0xba, 0x2f, 0x08, 0x00, 0x20, 0x0c, 0x9a, 0x66

    };

    static const uint8_t uuid_xmp[] = {

        0xbe, 0x7a, 0xcf, 0xcb, 0x97, 0xa9, 0x42, 0xe8,

        0x9c, 0x71, 0x99, 0x94, 0x91, 0xe3, 0xaf, 0xac

    };

    static const uint8_t uuid_spherical[] = {

        0xff, 0xcc, 0x82, 0x63, 0xf8, 0x55, 0x4a, 0x93,

        0x88, 0x14, 0x58, 0x7a, 0x02, 0x52, 0x1f, 0xdd,

    };



    if (atom.size < sizeof(uuid) || atom.size == INT64_MAX)

        return AVERROR_INVALIDDATA;



    if (c->fc->nb_streams < 1)

        return 0;

    st = c->fc->streams[c->fc->nb_streams - 1];

    sc = st->priv_data;



    ret = avio_read(pb, uuid, sizeof(uuid));

    if (ret < 0) {

        return ret;

    } else if (ret != sizeof(uuid)) {

        return AVERROR_INVALIDDATA;

    }

    if (!memcmp(uuid, uuid_isml_manifest, sizeof(uuid))) {

        uint8_t *buffer, *ptr;

        char *endptr;

        size_t len = atom.size - sizeof(uuid);



        if (len < 4) {

            return AVERROR_INVALIDDATA;

        }

        ret = avio_skip(pb, 4); // zeroes

        len -= 4;



        buffer = av_mallocz(len + 1);

        if (!buffer) {

            return AVERROR(ENOMEM);

        }

        ret = avio_read(pb, buffer, len);

        if (ret < 0) {

            av_free(buffer);

            return ret;

        } else if (ret != len) {

            av_free(buffer);

            return AVERROR_INVALIDDATA;

        }



        ptr = buffer;

        while ((ptr = av_stristr(ptr, "systemBitrate=\""))) {

            ptr += sizeof("systemBitrate=\"") - 1;

            c->bitrates_count++;

            c->bitrates = av_realloc_f(c->bitrates, c->bitrates_count, sizeof(*c->bitrates));

            if (!c->bitrates) {

                c->bitrates_count = 0;

                av_free(buffer);

                return AVERROR(ENOMEM);

            }

            errno = 0;

            ret = strtol(ptr, &endptr, 10);

            if (ret < 0 || errno || *endptr != '"') {

                c->bitrates[c->bitrates_count - 1] = 0;

            } else {

                c->bitrates[c->bitrates_count - 1] = ret;

            }

        }



        av_free(buffer);

    } else if (!memcmp(uuid, uuid_xmp, sizeof(uuid))) {

        uint8_t *buffer;

        size_t len = atom.size - sizeof(uuid);

        if (c->export_xmp) {

            buffer = av_mallocz(len + 1);

            if (!buffer) {

                return AVERROR(ENOMEM);

            }

            ret = avio_read(pb, buffer, len);

            if (ret < 0) {

                av_free(buffer);

                return ret;

            } else if (ret != len) {

                av_free(buffer);

                return AVERROR_INVALIDDATA;

            }

            buffer[len] = '\0';

            av_dict_set(&c->fc->metadata, "xmp", buffer, 0);

            av_free(buffer);

        } else {

            // skip all uuid atom, which makes it fast for long uuid-xmp file

            ret = avio_skip(pb, len);

            if (ret < 0)

                return ret;

        }

    } else if (!memcmp(uuid, uuid_spherical, sizeof(uuid))) {

        size_t len = atom.size - sizeof(uuid);

        ret = mov_parse_uuid_spherical(sc, pb, len);

        if (ret < 0)

            return ret;

        if (!sc->spherical)

            av_log(c->fc, AV_LOG_WARNING, "Invalid spherical metadata found\n");    }



    return 0;

}

