int get_frame_filename(char *buf, int buf_size,

                       const char *path, int number)

{

    const char *p;

    char *q, buf1[20];

    int nd, len, c, percentd_found;



    q = buf;

    p = path;

    percentd_found = 0;

    for(;;) {

        c = *p++;

        if (c == '\0')

            break;

        if (c == '%') {

            do {

                nd = 0;

                while (isdigit(*p)) {

                    nd = nd * 10 + *p++ - '0';

                }

                c = *p++;

                if (c == '*' && nd > 0) {

                    // The nd field is actually the modulus

                    number = number % nd;

                    c = *p++;

                    nd = 0;

                }

            } while (isdigit(c));



            switch(c) {

            case '%':

                goto addchar;

            case 'd':

                if (percentd_found)

                    goto fail;

                percentd_found = 1;

                snprintf(buf1, sizeof(buf1), "%0*d", nd, number);

                len = strlen(buf1);

                if ((q - buf + len) > buf_size - 1)

                    goto fail;

                memcpy(q, buf1, len);

                q += len;

                break;

            default:

                goto fail;

            }

        } else {

        addchar:

            if ((q - buf) < buf_size - 1)

                *q++ = c;

        }

    }

    if (!percentd_found)

        goto fail;

    *q = '\0';

    return 0;

 fail:

    *q = '\0';

    return -1;

}

static int ivi_decode_blocks(GetBitContext *gb, IVIBandDesc *band, IVITile *tile,

                             AVCodecContext *avctx)

{

    int         mbn, blk, num_blocks, num_coeffs, blk_size, scan_pos, run, val,

                pos, is_intra, mc_type = 0, mv_x, mv_y, col_mask;

    uint8_t     col_flags[8];

    int32_t     prev_dc, trvec[64];

    uint32_t    cbp, sym, lo, hi, quant, buf_offs, q;

    IVIMbInfo   *mb;

    RVMapDesc   *rvmap = band->rv_map;

    void (*mc_with_delta_func)(int16_t *buf, const int16_t *ref_buf, uint32_t pitch, int mc_type);

    void (*mc_no_delta_func)  (int16_t *buf, const int16_t *ref_buf, uint32_t pitch, int mc_type);

    const uint16_t  *base_tab;

    const uint8_t   *scale_tab;



    prev_dc = 0; /* init intra prediction for the DC coefficient */



    blk_size   = band->blk_size;

    col_mask   = blk_size - 1; /* column mask for tracking non-zero coeffs */

    num_blocks = (band->mb_size != blk_size) ? 4 : 1; /* number of blocks per mb */

    num_coeffs = blk_size * blk_size;

    if (blk_size == 8) {

        mc_with_delta_func = ff_ivi_mc_8x8_delta;

        mc_no_delta_func   = ff_ivi_mc_8x8_no_delta;

    } else {

        mc_with_delta_func = ff_ivi_mc_4x4_delta;

        mc_no_delta_func   = ff_ivi_mc_4x4_no_delta;

    }



    for (mbn = 0, mb = tile->mbs; mbn < tile->num_MBs; mb++, mbn++) {

        is_intra = !mb->type;

        cbp      = mb->cbp;

        buf_offs = mb->buf_offs;



        quant = av_clip(band->glob_quant + mb->q_delta, 0, 23);



        base_tab  = is_intra ? band->intra_base  : band->inter_base;

        scale_tab = is_intra ? band->intra_scale : band->inter_scale;

        if (scale_tab)

            quant = scale_tab[quant];



        if (!is_intra) {

            mv_x = mb->mv_x;

            mv_y = mb->mv_y;

            if (band->is_halfpel) {

                mc_type = ((mv_y & 1) << 1) | (mv_x & 1);

                mv_x >>= 1;

                mv_y >>= 1; /* convert halfpel vectors into fullpel ones */

            }

            if (mb->type) {

                int dmv_x, dmv_y, cx, cy;



                dmv_x = mb->mv_x >> band->is_halfpel;

                dmv_y = mb->mv_y >> band->is_halfpel;

                cx    = mb->mv_x &  band->is_halfpel;

                cy    = mb->mv_y &  band->is_halfpel;



                if (   mb->xpos + dmv_x < 0

                    || mb->xpos + dmv_x + band->mb_size + cx > band->pitch

                    || mb->ypos + dmv_y < 0

                    || mb->ypos + dmv_y + band->mb_size + cy > band->aheight) {

                    return AVERROR_INVALIDDATA;

                }

            }

        }



        for (blk = 0; blk < num_blocks; blk++) {

            /* adjust block position in the buffer according to its number */

            if (blk & 1) {

                buf_offs += blk_size;

            } else if (blk == 2) {

                buf_offs -= blk_size;

                buf_offs += blk_size * band->pitch;

            }



            if (cbp & 1) { /* block coded ? */

                if (!band->scan) {

                    av_log(avctx, AV_LOG_ERROR, "Scan pattern is not set.\n");

                    return AVERROR_INVALIDDATA;

                }



                scan_pos = -1;

                memset(trvec, 0, num_coeffs*sizeof(trvec[0])); /* zero transform vector */

                memset(col_flags, 0, sizeof(col_flags));      /* zero column flags */



                while (scan_pos <= num_coeffs) {

                    sym = get_vlc2(gb, band->blk_vlc.tab->table, IVI_VLC_BITS, 1);

                    if (sym == rvmap->eob_sym)

                        break; /* End of block */



                    if (sym == rvmap->esc_sym) { /* Escape - run/val explicitly coded using 3 vlc codes */

                        run = get_vlc2(gb, band->blk_vlc.tab->table, IVI_VLC_BITS, 1) + 1;

                        lo  = get_vlc2(gb, band->blk_vlc.tab->table, IVI_VLC_BITS, 1);

                        hi  = get_vlc2(gb, band->blk_vlc.tab->table, IVI_VLC_BITS, 1);

                        val = IVI_TOSIGNED((hi << 6) | lo); /* merge them and convert into signed val */

                    } else {

                        if (sym >= 256U) {

                            av_log(avctx, AV_LOG_ERROR, "Invalid sym encountered: %d.\n", sym);

                            return -1;

                        }

                        run = rvmap->runtab[sym];

                        val = rvmap->valtab[sym];

                    }



                    /* de-zigzag and dequantize */

                    scan_pos += run;

                    if (scan_pos >= (unsigned)num_coeffs)

                        break;

                    pos = band->scan[scan_pos];



                    if (!val)

                        av_dlog(avctx, "Val = 0 encountered!\n");



                    q = (base_tab[pos] * quant) >> 9;

                    if (q > 1)

                        val = val * q + FFSIGN(val) * (((q ^ 1) - 1) >> 1);

                    trvec[pos] = val;

                    col_flags[pos & col_mask] |= !!val; /* track columns containing non-zero coeffs */

                }// while



                if (scan_pos >= num_coeffs && sym != rvmap->eob_sym)

                    return -1; /* corrupt block data */



                /* undoing DC coeff prediction for intra-blocks */

                if (is_intra && band->is_2d_trans) {

                    prev_dc      += trvec[0];

                    trvec[0]      = prev_dc;

                    col_flags[0] |= !!prev_dc;

                }

                if(band->transform_size > band->blk_size){

                    av_log(NULL, AV_LOG_ERROR, "Too large transform\n");

                    return AVERROR_INVALIDDATA;

                }

                /* apply inverse transform */

                band->inv_transform(trvec, band->buf + buf_offs,

                                    band->pitch, col_flags);



                /* apply motion compensation */

                if (!is_intra)

                    mc_with_delta_func(band->buf + buf_offs,

                                       band->ref_buf + buf_offs + mv_y * band->pitch + mv_x,

                                       band->pitch, mc_type);

            } else {

                /* block not coded */

                /* for intra blocks apply the dc slant transform */

                /* for inter - perform the motion compensation without delta */

                if (is_intra) {

                    band->dc_transform(&prev_dc, band->buf + buf_offs,

                                       band->pitch, blk_size);

                } else

                    mc_no_delta_func(band->buf + buf_offs,

                                     band->ref_buf + buf_offs + mv_y * band->pitch + mv_x,

                                     band->pitch, mc_type);

            }



            cbp >>= 1;

        }// for blk

    }// for mbn



    align_get_bits(gb);



    return 0;

}

static int epzs_motion_search(MpegEncContext * s,

                             int *mx_ptr, int *my_ptr,

                             int P[5][2], int pred_x, int pred_y,

                             int xmin, int ymin, int xmax, int ymax)

{

    int best[2]={0, 0};

    int d, dmin; 

    UINT8 *new_pic, *old_pic;

    const int pic_stride= s->linesize;

    const int pic_xy= (s->mb_y*pic_stride + s->mb_x)*16;

    UINT16 *mv_penalty= s->mv_penalty[s->f_code] + MAX_MV; // f_code of the prev frame

    int quant= s->qscale; // qscale of the prev frame

    const int shift= 1+s->quarter_sample;



    new_pic = s->new_picture[0] + pic_xy;

    old_pic = s->last_picture[0] + pic_xy;

//printf("%d %d %d %d\n", xmin, ymin, xmax, ymax);



    dmin = pix_abs16x16(new_pic, old_pic, pic_stride, 16);

    if(dmin<Z_THRESHOLD){

        *mx_ptr= 0;

        *my_ptr= 0;

//printf("Z");

        return dmin;

    }



    /* first line */

    if ((s->mb_y == 0 || s->first_slice_line || s->first_gob_line)) {

        CHECK_MV(P[1][0]>>shift, P[1][1]>>shift)

    }else{

        CHECK_MV(P[4][0]>>shift, P[4][1]>>shift)

        if(dmin<Z_THRESHOLD){

            *mx_ptr= P[4][0]>>shift;

            *my_ptr= P[4][1]>>shift;

//printf("M\n");

            return dmin;

        }

        CHECK_MV(P[1][0]>>shift, P[1][1]>>shift)

        CHECK_MV(P[2][0]>>shift, P[2][1]>>shift)

        CHECK_MV(P[3][0]>>shift, P[3][1]>>shift)

    }

    CHECK_MV(P[0][0]>>shift, P[0][1]>>shift)



    dmin= small_diamond_search(s, best, dmin, new_pic, old_pic, pic_stride, 

                               pred_x, pred_y, mv_penalty, quant, xmin, ymin, xmax, ymax, shift);

    *mx_ptr= best[0];

    *my_ptr= best[1];    



//    printf("%d %d %d \n", best[0], best[1], dmin);



    return dmin;

}

void ff_snow_horizontal_compose97i_sse2(DWTELEM *b, int width){

    const int w2= (width+1)>>1;

    // SSE2 code runs faster with pointers aligned on a 32-byte boundary.

    DWTELEM temp_buf[(width>>1) + 4];

    DWTELEM * const temp = temp_buf + 4 - (((int)temp_buf & 0xF) >> 2);

    const int w_l= (width>>1);

    const int w_r= w2 - 1;

    int i;



    { // Lift 0

        DWTELEM * const ref = b + w2 - 1;

        DWTELEM b_0 = b[0]; //By allowing the first entry in b[0] to be calculated twice

        // (the first time erroneously), we allow the SSE2 code to run an extra pass.

        // The savings in code and time are well worth having to store this value and

        // calculate b[0] correctly afterwards.



        i = 0;

        asm volatile(

            "pcmpeqd   %%xmm7, %%xmm7         \n\t"

            "pslld        $31, %%xmm7         \n\t"

            "psrld        $29, %%xmm7         \n\t"

        ::);

        for(; i<w_l-7; i+=8){

            asm volatile(

                "movdqu   (%1), %%xmm1        \n\t"

                "movdqu 16(%1), %%xmm5        \n\t"

                "movdqu  4(%1), %%xmm2        \n\t"

                "movdqu 20(%1), %%xmm6        \n\t"

                "paddd  %%xmm1, %%xmm2        \n\t"

                "paddd  %%xmm5, %%xmm6        \n\t"

                "movdqa %%xmm2, %%xmm0        \n\t"

                "movdqa %%xmm6, %%xmm4        \n\t"

                "paddd  %%xmm2, %%xmm2        \n\t"

                "paddd  %%xmm6, %%xmm6        \n\t"

                "paddd  %%xmm0, %%xmm2        \n\t"

                "paddd  %%xmm4, %%xmm6        \n\t"

                "paddd  %%xmm7, %%xmm2        \n\t"

                "paddd  %%xmm7, %%xmm6        \n\t"

                "psrad      $3, %%xmm2        \n\t"

                "psrad      $3, %%xmm6        \n\t"

                "movdqa   (%0), %%xmm0        \n\t"

                "movdqa 16(%0), %%xmm4        \n\t"

                "psubd  %%xmm2, %%xmm0        \n\t"

                "psubd  %%xmm6, %%xmm4        \n\t"

                "movdqa %%xmm0, (%0)          \n\t"

                "movdqa %%xmm4, 16(%0)        \n\t"

                :: "r"(&b[i]), "r"(&ref[i])

                : "memory"

            );

        }

        snow_horizontal_compose_lift_lead_out(i, b, b, ref, width, w_l, 0, W_DM, W_DO, W_DS);

        b[0] = b_0 - ((W_DM * 2 * ref[1]+W_DO)>>W_DS);

    }



    { // Lift 1

        DWTELEM * const dst = b+w2;



        i = 0;

        for(; (((long)&dst[i]) & 0xF) && i<w_r; i++){

            dst[i] = dst[i] - (b[i] + b[i + 1]);

        }

        for(; i<w_r-7; i+=8){

            asm volatile(

                "movdqu   (%1), %%xmm1        \n\t"

                "movdqu 16(%1), %%xmm5        \n\t"

                "movdqu  4(%1), %%xmm2        \n\t"

                "movdqu 20(%1), %%xmm6        \n\t"

                "paddd  %%xmm1, %%xmm2        \n\t"

                "paddd  %%xmm5, %%xmm6        \n\t"

                "movdqa   (%0), %%xmm0        \n\t"

                "movdqa 16(%0), %%xmm4        \n\t"

                "psubd  %%xmm2, %%xmm0        \n\t"

                "psubd  %%xmm6, %%xmm4        \n\t"

                "movdqa %%xmm0, (%0)          \n\t"

                "movdqa %%xmm4, 16(%0)        \n\t"

                :: "r"(&dst[i]), "r"(&b[i])

                : "memory"

            );

        }

        snow_horizontal_compose_lift_lead_out(i, dst, dst, b, width, w_r, 1, W_CM, W_CO, W_CS);

    }



    { // Lift 2

        DWTELEM * const ref = b+w2 - 1;

        DWTELEM b_0 = b[0];



        i = 0;

        asm volatile(

            "pslld          $1, %%xmm7        \n\t"

        ::);

        for(; i<w_l-7; i+=8){

            asm volatile(

                "movdqu   (%1), %%xmm1        \n\t"

                "movdqu 16(%1), %%xmm5        \n\t"

                "movdqu  4(%1), %%xmm0        \n\t"

                "movdqu 20(%1), %%xmm4        \n\t" //FIXME try aligned reads and shifts

                "paddd  %%xmm1, %%xmm0        \n\t"

                "paddd  %%xmm5, %%xmm4        \n\t"

                "paddd  %%xmm7, %%xmm0        \n\t"

                "paddd  %%xmm7, %%xmm4        \n\t"

                "movdqa   (%0), %%xmm1        \n\t"

                "movdqa 16(%0), %%xmm5        \n\t"

                "psrad      $2, %%xmm0        \n\t"

                "psrad      $2, %%xmm4        \n\t"

                "paddd  %%xmm1, %%xmm0        \n\t"

                "paddd  %%xmm5, %%xmm4        \n\t"

                "psrad      $2, %%xmm0        \n\t"

                "psrad      $2, %%xmm4        \n\t"

                "paddd  %%xmm1, %%xmm0        \n\t"

                "paddd  %%xmm5, %%xmm4        \n\t"

                "movdqa %%xmm0, (%0)          \n\t"

                "movdqa %%xmm4, 16(%0)        \n\t"

                :: "r"(&b[i]), "r"(&ref[i])

                : "memory"

            );

        }

        snow_horizontal_compose_liftS_lead_out(i, b, b, ref, width, w_l);

        b[0] = b_0 + ((2 * ref[1] + W_BO-1 + 4 * b_0) >> W_BS);

    }



    { // Lift 3

        DWTELEM * const src = b+w2;



        i = 0;

        for(; (((long)&temp[i]) & 0xF) && i<w_r; i++){

            temp[i] = src[i] - ((-W_AM*(b[i] + b[i+1]))>>W_AS);

        }

        for(; i<w_r-7; i+=8){

            asm volatile(

                "movdqu  4(%1), %%xmm2        \n\t"

                "movdqu 20(%1), %%xmm6        \n\t"

                "paddd    (%1), %%xmm2        \n\t"

                "paddd  16(%1), %%xmm6        \n\t"

                "movdqu   (%0), %%xmm0        \n\t"

                "movdqu 16(%0), %%xmm4        \n\t"

                "paddd  %%xmm2, %%xmm0        \n\t"

                "paddd  %%xmm6, %%xmm4        \n\t"

                "psrad      $1, %%xmm2        \n\t"

                "psrad      $1, %%xmm6        \n\t"

                "paddd  %%xmm0, %%xmm2        \n\t"

                "paddd  %%xmm4, %%xmm6        \n\t"

                "movdqa %%xmm2, (%2)          \n\t"

                "movdqa %%xmm6, 16(%2)        \n\t"

                :: "r"(&src[i]), "r"(&b[i]), "r"(&temp[i])

                 : "memory"

               );

        }

        snow_horizontal_compose_lift_lead_out(i, temp, src, b, width, w_r, 1, -W_AM, W_AO+1, W_AS);

    }



    {

        snow_interleave_line_header(&i, width, b, temp);



        for (; (i & 0x1E) != 0x1E; i-=2){

            b[i+1] = temp[i>>1];

            b[i] = b[i>>1];

        }

        for (i-=30; i>=0; i-=32){

            asm volatile(

                "movdqa      (%1), %%xmm0       \n\t"

                "movdqa    16(%1), %%xmm2       \n\t"

                "movdqa    32(%1), %%xmm4       \n\t"

                "movdqa    48(%1), %%xmm6       \n\t"

                "movdqa      (%1), %%xmm1       \n\t"

                "movdqa    16(%1), %%xmm3       \n\t"

                "movdqa    32(%1), %%xmm5       \n\t"

                "movdqa    48(%1), %%xmm7       \n\t"

                "punpckldq   (%2), %%xmm0       \n\t"

                "punpckldq 16(%2), %%xmm2       \n\t"

                "punpckldq 32(%2), %%xmm4       \n\t"

                "punpckldq 48(%2), %%xmm6       \n\t"

                "movdqa    %%xmm0, (%0)         \n\t"

                "movdqa    %%xmm2, 32(%0)       \n\t"

                "movdqa    %%xmm4, 64(%0)       \n\t"

                "movdqa    %%xmm6, 96(%0)       \n\t"

                "punpckhdq   (%2), %%xmm1       \n\t"

                "punpckhdq 16(%2), %%xmm3       \n\t"

                "punpckhdq 32(%2), %%xmm5       \n\t"

                "punpckhdq 48(%2), %%xmm7       \n\t"

                "movdqa    %%xmm1, 16(%0)       \n\t"

                "movdqa    %%xmm3, 48(%0)       \n\t"

                "movdqa    %%xmm5, 80(%0)       \n\t"

                "movdqa    %%xmm7, 112(%0)      \n\t"

                :: "r"(&(b)[i]), "r"(&(b)[i>>1]), "r"(&(temp)[i>>1])

                 : "memory"

               );

        }

    }

}

static void decode(Real288_internal *glob, float gain, int cb_coef)

{

    unsigned int x, y;

    float f;

    double sum, sumsum;

    float *p1, *p2;

    float buffer[5];



    for (x=36; x--; glob->sb[x+5] = glob->sb[x]);



    for (x=5; x--;) {

        p1 = glob->sb+x;

        p2 = glob->pr1;

        for (sum=0, y=36; y--; sum -= (*(++p1))*(*(p2++)));



        glob->sb[x] = sum;

    }



    /* convert log and do rms */

    for (sum=32, x=10; x--; sum -= glob->pr2[x] * glob->lhist[x]);



    if (sum < 0)

        sum = 0;

    else if (sum > 60)

        sum = 60;



    sumsum = exp(sum * 0.1151292546497) * gain;    /* pow(10.0,sum/20)*f */



    for (sum=0, x=5; x--;) {

        buffer[x] = codetable[cb_coef][x] * sumsum;

        sum += buffer[x] * buffer[x];

    }



    if ((sum /= 5) < 1)

        sum = 1;



    /* shift and store */

    for (x=10; --x; glob->lhist[x] = glob->lhist[x-1]);



    *glob->lhist = glob->history[glob->phase] = 10 * log10(sum) - 32;



    for (x=1; x < 5; x++)

        for (y=x; y--; buffer[x] -= glob->pr1[x-y-1] * buffer[y]);



    /* output */

    for (x=0; x < 5; x++) {

        f = glob->sb[4-x] + buffer[x];



        if (f > 4095)

            f = 4095;

        else if (f < -4095)

            f = -4095;



        glob->output[glob->phasep+x] = glob->sb[4-x] = f;

    }

}

