int avcodec_close(AVCodecContext *avctx)

{

    entangled_thread_counter++;

    if(entangled_thread_counter != 1){

        av_log(avctx, AV_LOG_ERROR, "insufficient thread locking around avcodec_open/close()\n");

        entangled_thread_counter--;

        return -1;

    }



    if (ENABLE_THREADS && avctx->thread_opaque)

        avcodec_thread_free(avctx);

    if (avctx->codec->close)

        avctx->codec->close(avctx);

    avcodec_default_free_buffers(avctx);

    av_freep(&avctx->priv_data);


    avctx->codec = NULL;

    entangled_thread_counter--;

    return 0;

}

void av_dump_format(AVFormatContext *ic, int index,

                    const char *url, int is_output)

{

    int i;

    uint8_t *printed = ic->nb_streams ? av_mallocz(ic->nb_streams) : NULL;

    if (ic->nb_streams && !printed)

        return;



    av_log(NULL, AV_LOG_INFO, "%s #%d, %s, %s '%s':\n",

           is_output ? "Output" : "Input",

           index,

           is_output ? ic->oformat->name : ic->iformat->name,

           is_output ? "to" : "from", url);

    dump_metadata(NULL, ic->metadata, "  ");



    if (!is_output) {

        av_log(NULL, AV_LOG_INFO, "  Duration: ");

        if (ic->duration != AV_NOPTS_VALUE) {

            int hours, mins, secs, us;

            int64_t duration = ic->duration + (ic->duration <= INT64_MAX - 5000 ? 5000 : 0);

            secs  = duration / AV_TIME_BASE;

            us    = duration % AV_TIME_BASE;

            mins  = secs / 60;

            secs %= 60;

            hours = mins / 60;

            mins %= 60;

            av_log(NULL, AV_LOG_INFO, "%02d:%02d:%02d.%02d", hours, mins, secs,

                   (100 * us) / AV_TIME_BASE);

        } else {

            av_log(NULL, AV_LOG_INFO, "N/A");

        }

        if (ic->start_time != AV_NOPTS_VALUE) {

            int secs, us;

            av_log(NULL, AV_LOG_INFO, ", start: ");

            secs = ic->start_time / AV_TIME_BASE;

            us   = llabs(ic->start_time % AV_TIME_BASE);

            av_log(NULL, AV_LOG_INFO, "%d.%06d",

                   secs, (int) av_rescale(us, 1000000, AV_TIME_BASE));

        }

        av_log(NULL, AV_LOG_INFO, ", bitrate: ");

        if (ic->bit_rate)

            av_log(NULL, AV_LOG_INFO, "%"PRId64" kb/s", (int64_t)ic->bit_rate / 1000);

        else

            av_log(NULL, AV_LOG_INFO, "N/A");

        av_log(NULL, AV_LOG_INFO, "\n");

    }



    for (i = 0; i < ic->nb_chapters; i++) {

        AVChapter *ch = ic->chapters[i];

        av_log(NULL, AV_LOG_INFO, "    Chapter #%d:%d: ", index, i);

        av_log(NULL, AV_LOG_INFO,

               "start %f, ", ch->start * av_q2d(ch->time_base));

        av_log(NULL, AV_LOG_INFO,

               "end %f\n", ch->end * av_q2d(ch->time_base));



        dump_metadata(NULL, ch->metadata, "    ");

    }



    if (ic->nb_programs) {

        int j, k, total = 0;

        for (j = 0; j < ic->nb_programs; j++) {

            AVDictionaryEntry *name = av_dict_get(ic->programs[j]->metadata,

                                                  "name", NULL, 0);

            av_log(NULL, AV_LOG_INFO, "  Program %d %s\n", ic->programs[j]->id,

                   name ? name->value : "");

            dump_metadata(NULL, ic->programs[j]->metadata, "    ");

            for (k = 0; k < ic->programs[j]->nb_stream_indexes; k++) {

                dump_stream_format(ic, ic->programs[j]->stream_index[k],

                                   index, is_output);

                printed[ic->programs[j]->stream_index[k]] = 1;

            }

            total += ic->programs[j]->nb_stream_indexes;

        }

        if (total < ic->nb_streams)

            av_log(NULL, AV_LOG_INFO, "  No Program\n");

    }



    for (i = 0; i < ic->nb_streams; i++)

        if (!printed[i])

            dump_stream_format(ic, i, index, is_output);



    av_free(printed);

}

static void vp8_idct_add_c(uint8_t *dst, DCTELEM block[16], ptrdiff_t stride)

{

    int i, t0, t1, t2, t3;

    uint8_t *cm = ff_cropTbl + MAX_NEG_CROP;

    DCTELEM tmp[16];



    for (i = 0; i < 4; i++) {

        t0 = block[0*4+i] + block[2*4+i];

        t1 = block[0*4+i] - block[2*4+i];

        t2 = MUL_35468(block[1*4+i]) - MUL_20091(block[3*4+i]);

        t3 = MUL_20091(block[1*4+i]) + MUL_35468(block[3*4+i]);

        block[0*4+i] = 0;

        block[1*4+i] = 0;

        block[2*4+i] = 0;

        block[3*4+i] = 0;



        tmp[i*4+0] = t0 + t3;

        tmp[i*4+1] = t1 + t2;

        tmp[i*4+2] = t1 - t2;

        tmp[i*4+3] = t0 - t3;

    }



    for (i = 0; i < 4; i++) {

        t0 = tmp[0*4+i] + tmp[2*4+i];

        t1 = tmp[0*4+i] - tmp[2*4+i];

        t2 = MUL_35468(tmp[1*4+i]) - MUL_20091(tmp[3*4+i]);

        t3 = MUL_20091(tmp[1*4+i]) + MUL_35468(tmp[3*4+i]);



        dst[0] = cm[dst[0] + ((t0 + t3 + 4) >> 3)];

        dst[1] = cm[dst[1] + ((t1 + t2 + 4) >> 3)];

        dst[2] = cm[dst[2] + ((t1 - t2 + 4) >> 3)];

        dst[3] = cm[dst[3] + ((t0 - t3 + 4) >> 3)];

        dst += stride;

    }

}

static int decode_hextile(VmncContext *c, uint8_t *dst, const uint8_t *src,

                          int ssize, int w, int h, int stride)

{

    int i, j, k;

    int bg = 0, fg = 0, rects, color, flags, xy, wh;

    const int bpp = c->bpp2;

    uint8_t *dst2;

    int bw = 16, bh = 16;

    const uint8_t *ssrc = src;



    for (j = 0; j < h; j += 16) {

        dst2 = dst;

        bw   = 16;

        if (j + 16 > h)

            bh = h - j;

        for (i = 0; i < w; i += 16, dst2 += 16 * bpp) {

            if (src - ssrc >= ssize) {

                av_log(c->avctx, AV_LOG_ERROR, "Premature end of data!\n");

                return -1;

            }

            if (i + 16 > w)

                bw = w - i;

            flags = *src++;

            if (flags & HT_RAW) {

                if (src - ssrc > ssize - bw * bh * bpp) {

                    av_log(c->avctx, AV_LOG_ERROR, "Premature end of data!\n");

                    return -1;

                }

                paint_raw(dst2, bw, bh, src, bpp, c->bigendian, stride);

                src += bw * bh * bpp;

            } else {

                if (flags & HT_BKG) {

                    bg = vmnc_get_pixel(src, bpp, c->bigendian);

                    src += bpp;

                }

                if (flags & HT_FG) {

                    fg = vmnc_get_pixel(src, bpp, c->bigendian);

                    src += bpp;

                }

                rects = 0;

                if (flags & HT_SUB)

                    rects = *src++;

                color = !!(flags & HT_CLR);



                paint_rect(dst2, 0, 0, bw, bh, bg, bpp, stride);



                if (src - ssrc > ssize - rects * (color * bpp + 2)) {

                    av_log(c->avctx, AV_LOG_ERROR, "Premature end of data!\n");

                    return -1;

                }

                for (k = 0; k < rects; k++) {

                    if (color) {

                        fg = vmnc_get_pixel(src, bpp, c->bigendian);

                        src += bpp;

                    }

                    xy = *src++;

                    wh = *src++;

                    paint_rect(dst2, xy >> 4, xy & 0xF, (wh >> 4) + 1,

                               (wh & 0xF) + 1, fg, bpp, stride);

                }

            }

        }

        dst += stride * 16;

    }

    return src - ssrc;

}

int ff_pre_estimate_p_frame_motion(MpegEncContext * s,

                                    int mb_x, int mb_y)

{

    MotionEstContext * const c= &s->me;

    int mx, my, dmin;

    int P[10][2];

    const int shift= 1+s->quarter_sample;

    const int xy= mb_x + mb_y*s->mb_stride;

    init_ref(c, s->new_picture.f.data, s->last_picture.f.data, NULL, 16*mb_x, 16*mb_y, 0);



    assert(s->quarter_sample==0 || s->quarter_sample==1);



    c->pre_penalty_factor    = get_penalty_factor(s->lambda, s->lambda2, c->avctx->me_pre_cmp);

    c->current_mv_penalty= c->mv_penalty[s->f_code] + MAX_MV;



    get_limits(s, 16*mb_x, 16*mb_y);

    c->skip=0;



    P_LEFT[0]       = s->p_mv_table[xy + 1][0];

    P_LEFT[1]       = s->p_mv_table[xy + 1][1];



    if(P_LEFT[0]       < (c->xmin<<shift)) P_LEFT[0]       = (c->xmin<<shift);



    /* special case for first line */

    if (s->first_slice_line) {

        c->pred_x= P_LEFT[0];

        c->pred_y= P_LEFT[1];

        P_TOP[0]= P_TOPRIGHT[0]= P_MEDIAN[0]=

        P_TOP[1]= P_TOPRIGHT[1]= P_MEDIAN[1]= 0; //FIXME

    } else {

        P_TOP[0]      = s->p_mv_table[xy + s->mb_stride    ][0];

        P_TOP[1]      = s->p_mv_table[xy + s->mb_stride    ][1];

        P_TOPRIGHT[0] = s->p_mv_table[xy + s->mb_stride - 1][0];

        P_TOPRIGHT[1] = s->p_mv_table[xy + s->mb_stride - 1][1];

        if(P_TOP[1]      < (c->ymin<<shift)) P_TOP[1]     = (c->ymin<<shift);

        if(P_TOPRIGHT[0] > (c->xmax<<shift)) P_TOPRIGHT[0]= (c->xmax<<shift);

        if(P_TOPRIGHT[1] < (c->ymin<<shift)) P_TOPRIGHT[1]= (c->ymin<<shift);



        P_MEDIAN[0]= mid_pred(P_LEFT[0], P_TOP[0], P_TOPRIGHT[0]);

        P_MEDIAN[1]= mid_pred(P_LEFT[1], P_TOP[1], P_TOPRIGHT[1]);



        c->pred_x = P_MEDIAN[0];

        c->pred_y = P_MEDIAN[1];

    }



    dmin = ff_epzs_motion_search(s, &mx, &my, P, 0, 0, s->p_mv_table, (1<<16)>>shift, 0, 16);



    s->p_mv_table[xy][0] = mx<<shift;

    s->p_mv_table[xy][1] = my<<shift;



    return dmin;

}

