int attribute_align_arg avcodec_decode_audio4(AVCodecContext *avctx,

                                              AVFrame *frame,

                                              int *got_frame_ptr,

                                              AVPacket *avpkt)

{

    AVCodecInternal *avci = avctx->internal;

    int planar, channels;

    int ret = 0;



    *got_frame_ptr = 0;



    avctx->pkt = avpkt;



    if (!avpkt->data && avpkt->size) {

        av_log(avctx, AV_LOG_ERROR, "invalid packet: NULL data, size != 0\n");

        return AVERROR(EINVAL);

    }



    apply_param_change(avctx, avpkt);



    avcodec_get_frame_defaults(frame);



    if (!avctx->refcounted_frames)

        av_frame_unref(&avci->to_free);



    if ((avctx->codec->capabilities & CODEC_CAP_DELAY) || avpkt->size) {

        ret = avctx->codec->decode(avctx, frame, got_frame_ptr, avpkt);

        if (ret >= 0 && *got_frame_ptr) {

            avctx->frame_number++;

            frame->pkt_dts = avpkt->dts;

            if (frame->format == AV_SAMPLE_FMT_NONE)

                frame->format = avctx->sample_fmt;



            if (!avctx->refcounted_frames) {

                avci->to_free = *frame;

                avci->to_free.extended_data = avci->to_free.data;

                memset(frame->buf, 0, sizeof(frame->buf));

                frame->extended_buf    = NULL;

                frame->nb_extended_buf = 0;

            }

        }



        if (ret < 0 && frame->data[0])

            av_frame_unref(frame);

    }



    /* many decoders assign whole AVFrames, thus overwriting extended_data;

     * make sure it's set correctly; assume decoders that actually use

     * extended_data are doing it correctly */

    planar   = av_sample_fmt_is_planar(frame->format);

    channels = av_get_channel_layout_nb_channels(frame->channel_layout);

    if (!(planar && channels > AV_NUM_DATA_POINTERS))

        frame->extended_data = frame->data;



    return ret;

}

static void extrapolate_isf(float isf[LP_ORDER_16k])

{

    float diff_isf[LP_ORDER - 2], diff_mean;

    float *diff_hi = diff_isf - LP_ORDER + 1; // diff array for extrapolated indexes

    float corr_lag[3];

    float est, scale;

    int i, i_max_corr;



    isf[LP_ORDER_16k - 1] = isf[LP_ORDER - 1];



    /* Calculate the difference vector */

    for (i = 0; i < LP_ORDER - 2; i++)

        diff_isf[i] = isf[i + 1] - isf[i];



    diff_mean = 0.0;

    for (i = 2; i < LP_ORDER - 2; i++)

        diff_mean += diff_isf[i] * (1.0f / (LP_ORDER - 4));



    /* Find which is the maximum autocorrelation */

    i_max_corr = 0;

    for (i = 0; i < 3; i++) {

        corr_lag[i] = auto_correlation(diff_isf, diff_mean, i + 2);



        if (corr_lag[i] > corr_lag[i_max_corr])

            i_max_corr = i;

    }

    i_max_corr++;



    for (i = LP_ORDER - 1; i < LP_ORDER_16k - 1; i++)

        isf[i] = isf[i - 1] + isf[i - 1 - i_max_corr]

                            - isf[i - 2 - i_max_corr];



    /* Calculate an estimate for ISF(18) and scale ISF based on the error */

    est   = 7965 + (isf[2] - isf[3] - isf[4]) / 6.0;

    scale = 0.5 * (FFMIN(est, 7600) - isf[LP_ORDER - 2]) /

            (isf[LP_ORDER_16k - 2] - isf[LP_ORDER - 2]);



    for (i = LP_ORDER - 1; i < LP_ORDER_16k - 1; i++)

        diff_hi[i] = scale * (isf[i] - isf[i - 1]);



    /* Stability insurance */

    for (i = LP_ORDER; i < LP_ORDER_16k - 1; i++)

        if (diff_hi[i] + diff_hi[i - 1] < 5.0) {

            if (diff_hi[i] > diff_hi[i - 1]) {

                diff_hi[i - 1] = 5.0 - diff_hi[i];

            } else

                diff_hi[i] = 5.0 - diff_hi[i - 1];

        }



    for (i = LP_ORDER - 1; i < LP_ORDER_16k - 1; i++)

        isf[i] = isf[i - 1] + diff_hi[i] * (1.0f / (1 << 15));



    /* Scale the ISF vector for 16000 Hz */

    for (i = 0; i < LP_ORDER_16k - 1; i++)

        isf[i] *= 0.8;

}

static void do_video_out(AVFormatContext *s,

                         OutputStream *ost,

                         AVFrame *next_picture,

                         double sync_ipts)

{

    int ret, format_video_sync;

    AVPacket pkt;

    AVCodecContext *enc = ost->enc_ctx;

    AVCodecContext *mux_enc = ost->st->codec;

    int nb_frames, nb0_frames, i;

    double delta, delta0;

    double duration = 0;

    int frame_size = 0;

    InputStream *ist = NULL;

    AVFilterContext *filter = ost->filter->filter;



    if (ost->source_index >= 0)

        ist = input_streams[ost->source_index];



    if (filter->inputs[0]->frame_rate.num > 0 &&

        filter->inputs[0]->frame_rate.den > 0)

        duration = 1/(av_q2d(filter->inputs[0]->frame_rate) * av_q2d(enc->time_base));



    if(ist && ist->st->start_time != AV_NOPTS_VALUE && ist->st->first_dts != AV_NOPTS_VALUE && ost->frame_rate.num)

        duration = FFMIN(duration, 1/(av_q2d(ost->frame_rate) * av_q2d(enc->time_base)));



    if (!ost->filters_script &&

        !ost->filters &&

        next_picture &&

        ist &&

        lrintf(av_frame_get_pkt_duration(next_picture) * av_q2d(ist->st->time_base) / av_q2d(enc->time_base)) > 0) {

        duration = lrintf(av_frame_get_pkt_duration(next_picture) * av_q2d(ist->st->time_base) / av_q2d(enc->time_base));

    }



    if (!next_picture) {

        //end, flushing

        nb0_frames = nb_frames = mid_pred(ost->last_nb0_frames[0],

                                          ost->last_nb0_frames[1],

                                          ost->last_nb0_frames[2]);

    } else {

        delta0 = sync_ipts - ost->sync_opts;

        delta  = delta0 + duration;



        /* by default, we output a single frame */

        nb0_frames = 0;

        nb_frames = 1;



        format_video_sync = video_sync_method;

        if (format_video_sync == VSYNC_AUTO) {

            if(!strcmp(s->oformat->name, "avi")) {

                format_video_sync = VSYNC_VFR;

            } else

                format_video_sync = (s->oformat->flags & AVFMT_VARIABLE_FPS) ? ((s->oformat->flags & AVFMT_NOTIMESTAMPS) ? VSYNC_PASSTHROUGH : VSYNC_VFR) : VSYNC_CFR;

            if (   ist

                && format_video_sync == VSYNC_CFR

                && input_files[ist->file_index]->ctx->nb_streams == 1

                && input_files[ist->file_index]->input_ts_offset == 0) {

                format_video_sync = VSYNC_VSCFR;

            }

            if (format_video_sync == VSYNC_CFR && copy_ts) {

                format_video_sync = VSYNC_VSCFR;

            }

        }



        if (delta0 < 0 &&

            delta > 0 &&

            format_video_sync != VSYNC_PASSTHROUGH &&

            format_video_sync != VSYNC_DROP) {

            double cor = FFMIN(-delta0, duration);

            if (delta0 < -0.6) {

                av_log(NULL, AV_LOG_WARNING, "Past duration %f too large\n", -delta0);

            } else

                av_log(NULL, AV_LOG_DEBUG, "Cliping frame in rate conversion by %f\n", -delta0);

            sync_ipts += cor;

            duration -= cor;

            delta0 += cor;

        }



        switch (format_video_sync) {

        case VSYNC_VSCFR:

            if (ost->frame_number == 0 && delta - duration >= 0.5) {

                av_log(NULL, AV_LOG_DEBUG, "Not duplicating %d initial frames\n", (int)lrintf(delta - duration));

                delta = duration;

                delta0 = 0;

                ost->sync_opts = lrint(sync_ipts);

            }

        case VSYNC_CFR:

            // FIXME set to 0.5 after we fix some dts/pts bugs like in avidec.c

            if (frame_drop_threshold && delta < frame_drop_threshold && ost->frame_number) {

                nb_frames = 0;

            } else if (delta < -1.1)

                nb_frames = 0;

            else if (delta > 1.1) {

                nb_frames = lrintf(delta);

                if (delta0 > 1.1)

                    nb0_frames = lrintf(delta0 - 0.6);

            }

            break;

        case VSYNC_VFR:

            if (delta <= -0.6)

                nb_frames = 0;

            else if (delta > 0.6)

                ost->sync_opts = lrint(sync_ipts);

            break;

        case VSYNC_DROP:

        case VSYNC_PASSTHROUGH:

            ost->sync_opts = lrint(sync_ipts);

            break;

        default:

            av_assert0(0);

        }

    }



    nb_frames = FFMIN(nb_frames, ost->max_frames - ost->frame_number);

    nb0_frames = FFMIN(nb0_frames, nb_frames);



    memmove(ost->last_nb0_frames + 1,

            ost->last_nb0_frames,

            sizeof(ost->last_nb0_frames[0]) * (FF_ARRAY_ELEMS(ost->last_nb0_frames) - 1));

    ost->last_nb0_frames[0] = nb0_frames;



    if (nb0_frames == 0 && ost->last_droped) {

        nb_frames_drop++;

        av_log(NULL, AV_LOG_VERBOSE,

               "*** dropping frame %d from stream %d at ts %"PRId64"\n",

               ost->frame_number, ost->st->index, ost->last_frame->pts);

    }

    if (nb_frames > (nb0_frames && ost->last_droped) + (nb_frames > nb0_frames)) {

        if (nb_frames > dts_error_threshold * 30) {

            av_log(NULL, AV_LOG_ERROR, "%d frame duplication too large, skipping\n", nb_frames - 1);

            nb_frames_drop++;

            return;

        }

        nb_frames_dup += nb_frames - (nb0_frames && ost->last_droped) - (nb_frames > nb0_frames);

        av_log(NULL, AV_LOG_VERBOSE, "*** %d dup!\n", nb_frames - 1);

    }

    ost->last_droped = nb_frames == nb0_frames && next_picture;



  /* duplicates frame if needed */

  for (i = 0; i < nb_frames; i++) {

    AVFrame *in_picture;

    av_init_packet(&pkt);

    pkt.data = NULL;

    pkt.size = 0;



    if (i < nb0_frames && ost->last_frame) {

        in_picture = ost->last_frame;

    } else

        in_picture = next_picture;



    if (!in_picture)

        return;



    in_picture->pts = ost->sync_opts;



#if 1

    if (!check_recording_time(ost))

#else

    if (ost->frame_number >= ost->max_frames)

#endif

        return;



    if (s->oformat->flags & AVFMT_RAWPICTURE &&

        enc->codec->id == AV_CODEC_ID_RAWVIDEO) {

        /* raw pictures are written as AVPicture structure to

           avoid any copies. We support temporarily the older

           method. */

        if (in_picture->interlaced_frame)

            mux_enc->field_order = in_picture->top_field_first ? AV_FIELD_TB:AV_FIELD_BT;

        else

            mux_enc->field_order = AV_FIELD_PROGRESSIVE;

        pkt.data   = (uint8_t *)in_picture;

        pkt.size   =  sizeof(AVPicture);

        pkt.pts    = av_rescale_q(in_picture->pts, enc->time_base, ost->st->time_base);

        pkt.flags |= AV_PKT_FLAG_KEY;



        write_frame(s, &pkt, ost);

    } else {

        int got_packet, forced_keyframe = 0;

        double pts_time;



        if (enc->flags & (AV_CODEC_FLAG_INTERLACED_DCT | AV_CODEC_FLAG_INTERLACED_ME) &&

            ost->top_field_first >= 0)

            in_picture->top_field_first = !!ost->top_field_first;



        if (in_picture->interlaced_frame) {

            if (enc->codec->id == AV_CODEC_ID_MJPEG)

                mux_enc->field_order = in_picture->top_field_first ? AV_FIELD_TT:AV_FIELD_BB;

            else

                mux_enc->field_order = in_picture->top_field_first ? AV_FIELD_TB:AV_FIELD_BT;

        } else

            mux_enc->field_order = AV_FIELD_PROGRESSIVE;



        in_picture->quality = enc->global_quality;

        in_picture->pict_type = 0;



        pts_time = in_picture->pts != AV_NOPTS_VALUE ?

            in_picture->pts * av_q2d(enc->time_base) : NAN;

        if (ost->forced_kf_index < ost->forced_kf_count &&

            in_picture->pts >= ost->forced_kf_pts[ost->forced_kf_index]) {

            ost->forced_kf_index++;

            forced_keyframe = 1;

        } else if (ost->forced_keyframes_pexpr) {

            double res;

            ost->forced_keyframes_expr_const_values[FKF_T] = pts_time;

            res = av_expr_eval(ost->forced_keyframes_pexpr,

                               ost->forced_keyframes_expr_const_values, NULL);

            ff_dlog(NULL, "force_key_frame: n:%f n_forced:%f prev_forced_n:%f t:%f prev_forced_t:%f -> res:%f\n",

                    ost->forced_keyframes_expr_const_values[FKF_N],

                    ost->forced_keyframes_expr_const_values[FKF_N_FORCED],

                    ost->forced_keyframes_expr_const_values[FKF_PREV_FORCED_N],

                    ost->forced_keyframes_expr_const_values[FKF_T],

                    ost->forced_keyframes_expr_const_values[FKF_PREV_FORCED_T],

                    res);

            if (res) {

                forced_keyframe = 1;

                ost->forced_keyframes_expr_const_values[FKF_PREV_FORCED_N] =

                    ost->forced_keyframes_expr_const_values[FKF_N];

                ost->forced_keyframes_expr_const_values[FKF_PREV_FORCED_T] =

                    ost->forced_keyframes_expr_const_values[FKF_T];

                ost->forced_keyframes_expr_const_values[FKF_N_FORCED] += 1;

            }



            ost->forced_keyframes_expr_const_values[FKF_N] += 1;

        } else if (   ost->forced_keyframes

                   && !strncmp(ost->forced_keyframes, "source", 6)

                   && in_picture->key_frame==1) {

            forced_keyframe = 1;

        }



        if (forced_keyframe) {

            in_picture->pict_type = AV_PICTURE_TYPE_I;

            av_log(NULL, AV_LOG_DEBUG, "Forced keyframe at time %f\n", pts_time);

        }



        update_benchmark(NULL);

        if (debug_ts) {

            av_log(NULL, AV_LOG_INFO, "encoder <- type:video "

                   "frame_pts:%s frame_pts_time:%s time_base:%d/%d\n",

                   av_ts2str(in_picture->pts), av_ts2timestr(in_picture->pts, &enc->time_base),

                   enc->time_base.num, enc->time_base.den);

        }



        ost->frames_encoded++;



        ret = avcodec_encode_video2(enc, &pkt, in_picture, &got_packet);

        update_benchmark("encode_video %d.%d", ost->file_index, ost->index);

        if (ret < 0) {

            av_log(NULL, AV_LOG_FATAL, "Video encoding failed\n");

            exit_program(1);

        }



        if (got_packet) {

            if (debug_ts) {

                av_log(NULL, AV_LOG_INFO, "encoder -> type:video "

                       "pkt_pts:%s pkt_pts_time:%s pkt_dts:%s pkt_dts_time:%s\n",

                       av_ts2str(pkt.pts), av_ts2timestr(pkt.pts, &enc->time_base),

                       av_ts2str(pkt.dts), av_ts2timestr(pkt.dts, &enc->time_base));

            }



            if (pkt.pts == AV_NOPTS_VALUE && !(enc->codec->capabilities & AV_CODEC_CAP_DELAY))

                pkt.pts = ost->sync_opts;



            av_packet_rescale_ts(&pkt, enc->time_base, ost->st->time_base);



            if (debug_ts) {

                av_log(NULL, AV_LOG_INFO, "encoder -> type:video "

                    "pkt_pts:%s pkt_pts_time:%s pkt_dts:%s pkt_dts_time:%s\n",

                    av_ts2str(pkt.pts), av_ts2timestr(pkt.pts, &ost->st->time_base),

                    av_ts2str(pkt.dts), av_ts2timestr(pkt.dts, &ost->st->time_base));

            }



            frame_size = pkt.size;

            write_frame(s, &pkt, ost);



            /* if two pass, output log */

            if (ost->logfile && enc->stats_out) {

                fprintf(ost->logfile, "%s", enc->stats_out);

            }

        }

    }

    ost->sync_opts++;

    /*

     * For video, number of frames in == number of packets out.

     * But there may be reordering, so we can't throw away frames on encoder

     * flush, we need to limit them here, before they go into encoder.

     */

    ost->frame_number++;



    if (vstats_filename && frame_size)

        do_video_stats(ost, frame_size);

  }



    if (!ost->last_frame)

        ost->last_frame = av_frame_alloc();

    av_frame_unref(ost->last_frame);

    if (next_picture && ost->last_frame)

        av_frame_ref(ost->last_frame, next_picture);

    else

        av_frame_free(&ost->last_frame);

}

static int vqa_decode_frame(AVCodecContext *avctx,

                            void *data, int *data_size,

                            AVPacket *avpkt)

{

    const uint8_t *buf = avpkt->data;

    int buf_size = avpkt->size;

    VqaContext *s = avctx->priv_data;



    s->buf = buf;

    s->size = buf_size;



    if (s->frame.data[0])

        avctx->release_buffer(avctx, &s->frame);



    if (avctx->get_buffer(avctx, &s->frame)) {

        av_log(s->avctx, AV_LOG_ERROR, "  VQA Video: get_buffer() failed\n");

        return -1;

    }



    vqa_decode_chunk(s);



    /* make the palette available on the way out */

    memcpy(s->frame.data[1], s->palette, PALETTE_COUNT * 4);

    s->frame.palette_has_changed = 1;



    *data_size = sizeof(AVFrame);

    *(AVFrame*)data = s->frame;



    /* report that the buffer was completely consumed */

    return buf_size;

}

static void search_for_quantizers_faac(AVCodecContext *avctx, AACEncContext *s,

                                       SingleChannelElement *sce,

                                       const float lambda)

{

    int start = 0, i, w, w2, g;

    float uplim[128], maxq[128];

    int minq, maxsf;

    float distfact = ((sce->ics.num_windows > 1) ? 85.80 : 147.84) / lambda;

    int last = 0, lastband = 0, curband = 0;

    float avg_energy = 0.0;

    if (sce->ics.num_windows == 1) {

        start = 0;

        for (i = 0; i < 1024; i++) {

            if (i - start >= sce->ics.swb_sizes[curband]) {

                start += sce->ics.swb_sizes[curband];

                curband++;

            }

            if (sce->coeffs[i]) {

                avg_energy += sce->coeffs[i] * sce->coeffs[i];

                last = i;

                lastband = curband;

            }

        }

    } else {

        for (w = 0; w < 8; w++) {

            const float *coeffs = sce->coeffs + w*128;

            curband = start = 0;

            for (i = 0; i < 128; i++) {

                if (i - start >= sce->ics.swb_sizes[curband]) {

                    start += sce->ics.swb_sizes[curband];

                    curband++;

                }

                if (coeffs[i]) {

                    avg_energy += coeffs[i] * coeffs[i];

                    last = FFMAX(last, i);

                    lastband = FFMAX(lastband, curband);

                }

            }

        }

    }

    last++;

    avg_energy /= last;

    if (avg_energy == 0.0f) {

        for (i = 0; i < FF_ARRAY_ELEMS(sce->sf_idx); i++)

            sce->sf_idx[i] = SCALE_ONE_POS;

        return;

    }

    for (w = 0; w < sce->ics.num_windows; w += sce->ics.group_len[w]) {

        start = w*128;

        for (g = 0; g < sce->ics.num_swb; g++) {

            float *coefs   = sce->coeffs + start;

            const int size = sce->ics.swb_sizes[g];

            int start2 = start, end2 = start + size, peakpos = start;

            float maxval = -1, thr = 0.0f, t;

            maxq[w*16+g] = 0.0f;

            if (g > lastband) {

                maxq[w*16+g] = 0.0f;

                start += size;

                for (w2 = 0; w2 < sce->ics.group_len[w]; w2++)

                    memset(coefs + w2*128, 0, sizeof(coefs[0])*size);

                continue;

            }

            for (w2 = 0; w2 < sce->ics.group_len[w]; w2++) {

                for (i = 0; i < size; i++) {

                    float t = coefs[w2*128+i]*coefs[w2*128+i];

                    maxq[w*16+g] = FFMAX(maxq[w*16+g], fabsf(coefs[w2*128 + i]));

                    thr += t;

                    if (sce->ics.num_windows == 1 && maxval < t) {

                        maxval  = t;

                        peakpos = start+i;

                    }

                }

            }

            if (sce->ics.num_windows == 1) {

                start2 = FFMAX(peakpos - 2, start2);

                end2   = FFMIN(peakpos + 3, end2);

            } else {

                start2 -= start;

                end2   -= start;

            }

            start += size;

            thr = pow(thr / (avg_energy * (end2 - start2)), 0.3 + 0.1*(lastband - g) / lastband);

            t   = 1.0 - (1.0 * start2 / last);

            uplim[w*16+g] = distfact / (1.4 * thr + t*t*t + 0.075);

        }

    }

    memset(sce->sf_idx, 0, sizeof(sce->sf_idx));

    abs_pow34_v(s->scoefs, sce->coeffs, 1024);

    for (w = 0; w < sce->ics.num_windows; w += sce->ics.group_len[w]) {

        start = w*128;

        for (g = 0;  g < sce->ics.num_swb; g++) {

            const float *coefs  = sce->coeffs + start;

            const float *scaled = s->scoefs   + start;

            const int size      = sce->ics.swb_sizes[g];

            int scf, prev_scf, step;

            int min_scf = -1, max_scf = 256;

            float curdiff;

            if (maxq[w*16+g] < 21.544) {

                sce->zeroes[w*16+g] = 1;

                start += size;

                continue;

            }

            sce->zeroes[w*16+g] = 0;

            scf  = prev_scf = av_clip(SCALE_ONE_POS - SCALE_DIV_512 - log2f(1/maxq[w*16+g])*16/3, 60, 218);

            for (;;) {

                float dist = 0.0f;

                int quant_max;



                for (w2 = 0; w2 < sce->ics.group_len[w]; w2++) {

                    int b;

                    dist += quantize_band_cost(s, coefs + w2*128,

                                               scaled + w2*128,

                                               sce->ics.swb_sizes[g],

                                               scf,

                                               ESC_BT,

                                               lambda,

                                               INFINITY,

                                               &b,

                                               0);

                    dist -= b;

                }

                dist *= 1.0f / 512.0f / lambda;

                quant_max = quant(maxq[w*16+g], ff_aac_pow2sf_tab[POW_SF2_ZERO - scf + SCALE_ONE_POS - SCALE_DIV_512], ROUND_STANDARD);

                if (quant_max >= 8191) { // too much, return to the previous quantizer

                    sce->sf_idx[w*16+g] = prev_scf;

                    break;

                }

                prev_scf = scf;

                curdiff = fabsf(dist - uplim[w*16+g]);

                if (curdiff <= 1.0f)

                    step = 0;

                else

                    step = log2f(curdiff);

                if (dist > uplim[w*16+g])

                    step = -step;

                scf += step;

                scf = av_clip_uint8(scf);

                step = scf - prev_scf;

                if (FFABS(step) <= 1 || (step > 0 && scf >= max_scf) || (step < 0 && scf <= min_scf)) {

                    sce->sf_idx[w*16+g] = av_clip(scf, min_scf, max_scf);

                    break;

                }

                if (step > 0)

                    min_scf = prev_scf;

                else

                    max_scf = prev_scf;

            }

            start += size;

        }

    }

    minq = sce->sf_idx[0] ? sce->sf_idx[0] : INT_MAX;

    for (i = 1; i < 128; i++) {

        if (!sce->sf_idx[i])

            sce->sf_idx[i] = sce->sf_idx[i-1];

        else

            minq = FFMIN(minq, sce->sf_idx[i]);

    }

    if (minq == INT_MAX)

        minq = 0;

    minq = FFMIN(minq, SCALE_MAX_POS);

    maxsf = FFMIN(minq + SCALE_MAX_DIFF, SCALE_MAX_POS);

    for (i = 126; i >= 0; i--) {

        if (!sce->sf_idx[i])

            sce->sf_idx[i] = sce->sf_idx[i+1];

        sce->sf_idx[i] = av_clip(sce->sf_idx[i], minq, maxsf);

    }

}

static av_cold int jpg_init(AVCodecContext *avctx, JPGContext *c)

{

    int ret;



    ret = build_vlc(&c->dc_vlc[0], avpriv_mjpeg_bits_dc_luminance,

                    avpriv_mjpeg_val_dc, 12, 0);

    if (ret)

        return ret;

    ret = build_vlc(&c->dc_vlc[1], avpriv_mjpeg_bits_dc_chrominance,

                    avpriv_mjpeg_val_dc, 12, 0);

    if (ret)

        return ret;

    ret = build_vlc(&c->ac_vlc[0], avpriv_mjpeg_bits_ac_luminance,

                    avpriv_mjpeg_val_ac_luminance, 251, 1);

    if (ret)

        return ret;

    ret = build_vlc(&c->ac_vlc[1], avpriv_mjpeg_bits_ac_chrominance,

                    avpriv_mjpeg_val_ac_chrominance, 251, 1);

    if (ret)

        return ret;



    ff_blockdsp_init(&c->bdsp, avctx);

    ff_idctdsp_init(&c->idsp, avctx);

    ff_init_scantable(c->idsp.idct_permutation, &c->scantable,

                      ff_zigzag_direct);



    return 0;

}

static int ffm_read_header(AVFormatContext *s, AVFormatParameters *ap)

{

    FFMContext *ffm = s->priv_data;

    AVStream *st;

    ByteIOContext *pb = s->pb;

    AVCodecContext *codec;

    int i, nb_streams;

    uint32_t tag;



    /* header */

    tag = get_le32(pb);

    if (tag != MKTAG('F', 'F', 'M', '1'))

        goto fail;

    ffm->packet_size = get_be32(pb);

    if (ffm->packet_size != FFM_PACKET_SIZE)

        goto fail;

    ffm->write_index = get_be64(pb);

    /* get also filesize */

    if (!url_is_streamed(pb)) {

        ffm->file_size = url_fsize(pb);

        if (ffm->write_index)

            adjust_write_index(s);

    } else {

        ffm->file_size = (UINT64_C(1) << 63) - 1;

    }



    nb_streams = get_be32(pb);

    get_be32(pb); /* total bitrate */

    /* read each stream */

    for(i=0;i<nb_streams;i++) {

        char rc_eq_buf[128];



        st = av_new_stream(s, 0);

        if (!st)

            goto fail;



        av_set_pts_info(st, 64, 1, 1000000);



        codec = st->codec;

        /* generic info */

        codec->codec_id = get_be32(pb);

        codec->codec_type = get_byte(pb); /* codec_type */

        codec->bit_rate = get_be32(pb);

        st->quality = get_be32(pb);

        codec->flags = get_be32(pb);

        codec->flags2 = get_be32(pb);

        codec->debug = get_be32(pb);

        /* specific info */

        switch(codec->codec_type) {

        case CODEC_TYPE_VIDEO:

            codec->time_base.num = get_be32(pb);

            codec->time_base.den = get_be32(pb);

            codec->width = get_be16(pb);

            codec->height = get_be16(pb);

            codec->gop_size = get_be16(pb);

            codec->pix_fmt = get_be32(pb);

            codec->qmin = get_byte(pb);

            codec->qmax = get_byte(pb);

            codec->max_qdiff = get_byte(pb);

            codec->qcompress = get_be16(pb) / 10000.0;

            codec->qblur = get_be16(pb) / 10000.0;

            codec->bit_rate_tolerance = get_be32(pb);

            codec->rc_eq = av_strdup(get_strz(pb, rc_eq_buf, sizeof(rc_eq_buf)));

            codec->rc_max_rate = get_be32(pb);

            codec->rc_min_rate = get_be32(pb);

            codec->rc_buffer_size = get_be32(pb);

            codec->i_quant_factor = av_int2dbl(get_be64(pb));

            codec->b_quant_factor = av_int2dbl(get_be64(pb));

            codec->i_quant_offset = av_int2dbl(get_be64(pb));

            codec->b_quant_offset = av_int2dbl(get_be64(pb));

            codec->dct_algo = get_be32(pb);

            codec->strict_std_compliance = get_be32(pb);

            codec->max_b_frames = get_be32(pb);

            codec->luma_elim_threshold = get_be32(pb);

            codec->chroma_elim_threshold = get_be32(pb);

            codec->mpeg_quant = get_be32(pb);

            codec->intra_dc_precision = get_be32(pb);

            codec->me_method = get_be32(pb);

            codec->mb_decision = get_be32(pb);

            codec->nsse_weight = get_be32(pb);

            codec->frame_skip_cmp = get_be32(pb);

            codec->rc_buffer_aggressivity = av_int2dbl(get_be64(pb));

            codec->codec_tag = get_be32(pb);

            codec->thread_count = get_byte(pb);

            codec->coder_type = get_be32(pb);

            codec->me_cmp = get_be32(pb);

            codec->partitions = get_be32(pb);

            codec->me_subpel_quality = get_be32(pb);

            codec->me_range = get_be32(pb);

            codec->keyint_min = get_be32(pb);

            codec->scenechange_threshold = get_be32(pb);

            codec->b_frame_strategy = get_be32(pb);

            codec->qcompress = av_int2dbl(get_be64(pb));

            codec->qblur = av_int2dbl(get_be64(pb));

            codec->max_qdiff = get_be32(pb);

            codec->refs = get_be32(pb);

            codec->directpred = get_be32(pb);

            break;

        case CODEC_TYPE_AUDIO:

            codec->sample_rate = get_be32(pb);

            codec->channels = get_le16(pb);

            codec->frame_size = get_le16(pb);

            codec->sample_fmt = get_le16(pb);

            break;

        default:

            goto fail;

        }

        if (codec->flags & CODEC_FLAG_GLOBAL_HEADER) {

            codec->extradata_size = get_be32(pb);

            codec->extradata = av_malloc(codec->extradata_size);

            if (!codec->extradata)

                return AVERROR(ENOMEM);

            get_buffer(pb, codec->extradata, codec->extradata_size);

        }

    }



    /* get until end of block reached */

    while ((url_ftell(pb) % ffm->packet_size) != 0)

        get_byte(pb);



    /* init packet demux */

    ffm->packet_ptr = ffm->packet;

    ffm->packet_end = ffm->packet;

    ffm->frame_offset = 0;

    ffm->dts = 0;

    ffm->read_state = READ_HEADER;

    ffm->first_packet = 1;

    return 0;

 fail:

    for(i=0;i<s->nb_streams;i++) {

        st = s->streams[i];

        if (st) {

            av_free(st);

        }

    }

    return -1;

}

static av_cold int msvideo1_decode_init(AVCodecContext *avctx)

{

    Msvideo1Context *s = avctx->priv_data;



    s->avctx = avctx;



    /* figure out the colorspace based on the presence of a palette */

    if (s->avctx->bits_per_coded_sample == 8) {

        s->mode_8bit = 1;

        avctx->pix_fmt = AV_PIX_FMT_PAL8;

    } else {

        s->mode_8bit = 0;

        avctx->pix_fmt = AV_PIX_FMT_RGB555;

    }



    s->frame.data[0] = NULL;



    return 0;

}

static void avc_luma_hv_qrt_16w_msa(const uint8_t *src_x, const uint8_t *src_y,

                                    int32_t src_stride, uint8_t *dst,

                                    int32_t dst_stride, int32_t height)

{

    uint32_t multiple8_cnt;



    for (multiple8_cnt = 2; multiple8_cnt--;) {

        avc_luma_hv_qrt_8w_msa(src_x, src_y, src_stride, dst, dst_stride,

                               height);



        src_x += 8;

        src_y += 8;

        dst += 8;

    }

}

static av_always_inline void hl_decode_mb_idct_luma(H264Context *h, int mb_type,

                                                    int is_h264, int simple,

                                                    int transform_bypass,

                                                    int pixel_shift,

                                                    int *block_offset,

                                                    int linesize,

                                                    uint8_t *dest_y, int p)

{

    void (*idct_add)(uint8_t *dst, int16_t *block, int stride);

    int i;

    block_offset += 16 * p;

    if (!IS_INTRA4x4(mb_type)) {

        if (is_h264) {

            if (IS_INTRA16x16(mb_type)) {

                if (transform_bypass) {

                    if (h->sps.profile_idc == 244 &&

                        (h->intra16x16_pred_mode == VERT_PRED8x8 ||

                         h->intra16x16_pred_mode == HOR_PRED8x8)) {

                        h->hpc.pred16x16_add[h->intra16x16_pred_mode](dest_y, block_offset,

                                                                      h->mb + (p * 256 << pixel_shift),

                                                                      linesize);

                    } else {

                        for (i = 0; i < 16; i++)

                            if (h->non_zero_count_cache[scan8[i + p * 16]] ||

                                dctcoef_get(h->mb, pixel_shift, i * 16 + p * 256))

                                h->h264dsp.h264_add_pixels4(dest_y + block_offset[i],

                                                            h->mb + (i * 16 + p * 256 << pixel_shift),

                                                            linesize);

                    }

                } else {

                    h->h264dsp.h264_idct_add16intra(dest_y, block_offset,

                                                    h->mb + (p * 256 << pixel_shift),

                                                    linesize,

                                                    h->non_zero_count_cache + p * 5 * 8);

                }

            } else if (h->cbp & 15) {

                if (transform_bypass) {

                    const int di = IS_8x8DCT(mb_type) ? 4 : 1;

                    idct_add = IS_8x8DCT(mb_type) ? h->h264dsp.h264_add_pixels8

                                                  : h->h264dsp.h264_add_pixels4;

                    for (i = 0; i < 16; i += di)

                        if (h->non_zero_count_cache[scan8[i + p * 16]])

                            idct_add(dest_y + block_offset[i],

                                     h->mb + (i * 16 + p * 256 << pixel_shift),

                                     linesize);

                } else {

                    if (IS_8x8DCT(mb_type))

                        h->h264dsp.h264_idct8_add4(dest_y, block_offset,

                                                   h->mb + (p * 256 << pixel_shift),

                                                   linesize,

                                                   h->non_zero_count_cache + p * 5 * 8);

                    else

                        h->h264dsp.h264_idct_add16(dest_y, block_offset,

                                                   h->mb + (p * 256 << pixel_shift),

                                                   linesize,

                                                   h->non_zero_count_cache + p * 5 * 8);

                }

            }

        } else if (CONFIG_SVQ3_DECODER) {

            for (i = 0; i < 16; i++)

                if (h->non_zero_count_cache[scan8[i + p * 16]] || h->mb[i * 16 + p * 256]) {

                    // FIXME benchmark weird rule, & below

                    uint8_t *const ptr = dest_y + block_offset[i];

                    ff_svq3_add_idct_c(ptr, h->mb + i * 16 + p * 256, linesize,

                                       h->qscale, IS_INTRA(mb_type) ? 1 : 0);

                }

        }

    }

}

static int wc3_read_header(AVFormatContext *s,

                           AVFormatParameters *ap)

{

    Wc3DemuxContext *wc3 = s->priv_data;

    ByteIOContext *pb = s->pb;

    unsigned int fourcc_tag;

    unsigned int size;

    AVStream *st;

    int ret = 0;

    int current_palette = 0;

    char *buffer;

    int i;



    /* default context members */

    wc3->width = WC3_DEFAULT_WIDTH;

    wc3->height = WC3_DEFAULT_HEIGHT;

    wc3->palettes = NULL;

    wc3->palette_count = 0;

    wc3->pts = 0;

    wc3->video_stream_index = wc3->audio_stream_index = 0;



    /* skip the first 3 32-bit numbers */

    url_fseek(pb, 12, SEEK_CUR);



    /* traverse through the chunks and load the header information before

     * the first BRCH tag */

    fourcc_tag = get_le32(pb);

    size = (get_be32(pb) + 1) & (~1);



    do {

        switch (fourcc_tag) {



        case SOND_TAG:

        case INDX_TAG:

            /* SOND unknown, INDX unnecessary; ignore both */

            url_fseek(pb, size, SEEK_CUR);

            break;



        case PC__TAG:

            /* need the number of palettes */

            url_fseek(pb, 8, SEEK_CUR);

            wc3->palette_count = get_le32(pb);

            if((unsigned)wc3->palette_count >= UINT_MAX / PALETTE_SIZE){

                wc3->palette_count= 0;

                return -1;

            }

            wc3->palettes = av_malloc(wc3->palette_count * PALETTE_SIZE);

            break;



        case BNAM_TAG:

            /* load up the name */

            buffer = av_malloc(size+1);

            if (!buffer)

                return AVERROR(ENOMEM);

            if ((ret = get_buffer(pb, buffer, size)) != size)

                return AVERROR(EIO);

            buffer[size] = 0;

            av_metadata_set2(&s->metadata, "title", buffer,

                                   AV_METADATA_DONT_STRDUP_VAL);

            break;



        case SIZE_TAG:

            /* video resolution override */

            wc3->width  = get_le32(pb);

            wc3->height = get_le32(pb);

            break;



        case PALT_TAG:

            /* one of several palettes */

            if ((unsigned)current_palette >= wc3->palette_count)

                return AVERROR_INVALIDDATA;

            if ((ret = get_buffer(pb,

                &wc3->palettes[current_palette * PALETTE_SIZE],

                PALETTE_SIZE)) != PALETTE_SIZE)

                return AVERROR(EIO);



            /* transform the current palette in place */

            for (i = current_palette * PALETTE_SIZE;

                 i < (current_palette + 1) * PALETTE_SIZE; i++) {

                wc3->palettes[i] = wc3_pal_lookup[wc3->palettes[i]];

            }

            current_palette++;

            break;



        default:

            av_log(s, AV_LOG_ERROR, "  unrecognized WC3 chunk: %c%c%c%c (0x%02X%02X%02X%02X)\n",

                (uint8_t)fourcc_tag, (uint8_t)(fourcc_tag >> 8), (uint8_t)(fourcc_tag >> 16), (uint8_t)(fourcc_tag >> 24),

                (uint8_t)fourcc_tag, (uint8_t)(fourcc_tag >> 8), (uint8_t)(fourcc_tag >> 16), (uint8_t)(fourcc_tag >> 24));

            return AVERROR_INVALIDDATA;

            break;

        }



        fourcc_tag = get_le32(pb);

        /* chunk sizes are 16-bit aligned */

        size = (get_be32(pb) + 1) & (~1);

        if (url_feof(pb))

            return AVERROR(EIO);



    } while (fourcc_tag != BRCH_TAG);



    /* initialize the decoder streams */

    st = av_new_stream(s, 0);

    if (!st)

        return AVERROR(ENOMEM);

    av_set_pts_info(st, 33, 1, WC3_FRAME_FPS);

    wc3->video_stream_index = st->index;

    st->codec->codec_type = AVMEDIA_TYPE_VIDEO;

    st->codec->codec_id = CODEC_ID_XAN_WC3;

    st->codec->codec_tag = 0;  /* no fourcc */

    st->codec->width = wc3->width;

    st->codec->height = wc3->height;



    /* palette considerations */

    st->codec->palctrl = &wc3->palette_control;



    st = av_new_stream(s, 0);

    if (!st)

        return AVERROR(ENOMEM);

    av_set_pts_info(st, 33, 1, WC3_FRAME_FPS);

    wc3->audio_stream_index = st->index;

    st->codec->codec_type = AVMEDIA_TYPE_AUDIO;

    st->codec->codec_id = CODEC_ID_PCM_S16LE;

    st->codec->codec_tag = 1;

    st->codec->channels = WC3_AUDIO_CHANNELS;

    st->codec->bits_per_coded_sample = WC3_AUDIO_BITS;

    st->codec->sample_rate = WC3_SAMPLE_RATE;

    st->codec->bit_rate = st->codec->channels * st->codec->sample_rate *

        st->codec->bits_per_coded_sample;

    st->codec->block_align = WC3_AUDIO_BITS * WC3_AUDIO_CHANNELS;



    return 0;

}

static int decode_packet(AVCodecContext *avctx, void *data, int *got_frame_ptr,
                         AVPacket* avpkt)
{
    WmallDecodeCtx *s = avctx->priv_data;
    GetBitContext* gb  = &s->pgb;
    const uint8_t* buf = avpkt->data;
    int buf_size       = avpkt->size;
    int num_bits_prev_frame, packet_sequence_number, spliced_packet;
    s->frame->nb_samples = 0;
    if (!buf_size && s->num_saved_bits > get_bits_count(&s->gb)) {
        s->packet_done = 0;
        if (!decode_frame(s))
            s->num_saved_bits = 0;
    } else if (s->packet_done || s->packet_loss) {
        s->packet_done = 0;
        if (!buf_size)
            return 0;
        s->next_packet_start = buf_size - FFMIN(avctx->block_align, buf_size);
        buf_size             = FFMIN(avctx->block_align, buf_size);
        s->buf_bit_size      = buf_size << 3;
        /* parse packet header */
        init_get_bits(gb, buf, s->buf_bit_size);
        packet_sequence_number = get_bits(gb, 4);
        skip_bits(gb, 1);   // Skip seekable_frame_in_packet, currently unused
        spliced_packet = get_bits1(gb);
        if (spliced_packet)
            avpriv_request_sample(avctx, "Bitstream splicing");
        /* get number of bits that need to be added to the previous frame */
        num_bits_prev_frame = get_bits(gb, s->log2_frame_size);
        /* check for packet loss */
        if (!s->packet_loss &&
            ((s->packet_sequence_number + 1) & 0xF) != packet_sequence_number) {
            av_log(avctx, AV_LOG_ERROR,
                   "Packet loss detected! seq %"PRIx8" vs %x\n",
                   s->packet_sequence_number, packet_sequence_number);
        s->packet_sequence_number = packet_sequence_number;
        if (num_bits_prev_frame > 0) {
            int remaining_packet_bits = s->buf_bit_size - get_bits_count(gb);
            if (num_bits_prev_frame >= remaining_packet_bits) {
                num_bits_prev_frame = remaining_packet_bits;
                s->packet_done = 1;
            /* Append the previous frame data to the remaining data from the
             * previous packet to create a full frame. */
            save_bits(s, gb, num_bits_prev_frame, 1);
            /* decode the cross packet frame if it is valid */
            if (num_bits_prev_frame < remaining_packet_bits && !s->packet_loss)
                decode_frame(s);
        } else if (s->num_saved_bits - s->frame_offset) {
            ff_dlog(avctx, "ignoring %x previously saved bits\n",
                    s->num_saved_bits - s->frame_offset);
        if (s->packet_loss) {
            /* Reset number of saved bits so that the decoder does not start
             * to decode incomplete frames in the s->len_prefix == 0 case. */
            s->num_saved_bits = 0;
            s->packet_loss    = 0;
            init_put_bits(&s->pb, s->frame_data, s->max_frame_size);
    } else {
        int frame_size;
        s->buf_bit_size = (avpkt->size - s->next_packet_start) << 3;
        init_get_bits(gb, avpkt->data, s->buf_bit_size);
        skip_bits(gb, s->packet_offset);
        if (s->len_prefix && remaining_bits(s, gb) > s->log2_frame_size &&
            (frame_size = show_bits(gb, s->log2_frame_size)) &&
            frame_size <= remaining_bits(s, gb)) {
            save_bits(s, gb, frame_size, 0);
            s->packet_done = !decode_frame(s);
        } else if (!s->len_prefix
                   && s->num_saved_bits > get_bits_count(&s->gb)) {
            /* when the frames do not have a length prefix, we don't know the
             * compressed length of the individual frames however, we know what
             * part of a new packet belongs to the previous frame therefore we
             * save the incoming packet first, then we append the "previous
             * frame" data from the next packet so that we get a buffer that
             * only contains full frames */
            s->packet_done = !decode_frame(s);
        } else {
            s->packet_done = 1;
    if (s->packet_done && !s->packet_loss &&
        remaining_bits(s, gb) > 0) {
        /* save the rest of the data so that it can be decoded
         * with the next packet */
        save_bits(s, gb, remaining_bits(s, gb), 0);
    *got_frame_ptr   = s->frame->nb_samples > 0;
    av_frame_move_ref(data, s->frame);
    s->packet_offset = get_bits_count(gb) & 7;
    return (s->packet_loss) ? AVERROR_INVALIDDATA : buf_size ? get_bits_count(gb) >> 3 : 0;

static int avi_read_packet(AVFormatContext *s, AVPacket *pkt)
{
    AVIContext *avi = s->priv_data;
    ByteIOContext *pb = s->pb;
    int n, d[8], size;
    offset_t i, sync;
    void* dstr;
    if (ENABLE_DV_DEMUXER && avi->dv_demux) {
        size = dv_get_packet(avi->dv_demux, pkt);
        if (size >= 0)
            return size;
    }
    if(avi->non_interleaved){
        int best_stream_index = 0;
        AVStream *best_st= NULL;
        AVIStream *best_ast;
        int64_t best_ts= INT64_MAX;
        int i;
        for(i=0; i<s->nb_streams; i++){
            AVStream *st = s->streams[i];
            AVIStream *ast = st->priv_data;
            int64_t ts= ast->frame_offset;
            if(ast->sample_size)
                ts /= ast->sample_size;
            ts= av_rescale(ts, AV_TIME_BASE * (int64_t)st->time_base.num, st->time_base.den);
//            av_log(NULL, AV_LOG_DEBUG, "%"PRId64" %d/%d %"PRId64"\n", ts, st->time_base.num, st->time_base.den, ast->frame_offset);
            if(ts < best_ts && st->nb_index_entries){
                best_ts= ts;
                best_st= st;
                best_stream_index= i;
            }
        }
        best_ast = best_st->priv_data;
        best_ts= av_rescale(best_ts, best_st->time_base.den, AV_TIME_BASE * (int64_t)best_st->time_base.num); //FIXME a little ugly
        if(best_ast->remaining)
            i= av_index_search_timestamp(best_st, best_ts, AVSEEK_FLAG_ANY | AVSEEK_FLAG_BACKWARD);
        else
            i= av_index_search_timestamp(best_st, best_ts, AVSEEK_FLAG_ANY);
//        av_log(NULL, AV_LOG_DEBUG, "%d\n", i);
        if(i>=0){
            int64_t pos= best_st->index_entries[i].pos;
            pos += best_ast->packet_size - best_ast->remaining;
            url_fseek(s->pb, pos + 8, SEEK_SET);
//        av_log(NULL, AV_LOG_DEBUG, "pos=%"PRId64"\n", pos);
            assert(best_ast->remaining <= best_ast->packet_size);
            avi->stream_index= best_stream_index;
            if(!best_ast->remaining)
                best_ast->packet_size=
                best_ast->remaining= best_st->index_entries[i].size;
        }
    }
resync:
    if(avi->stream_index >= 0){
        AVStream *st= s->streams[ avi->stream_index ];
        AVIStream *ast= st->priv_data;
        int size;
        if(ast->sample_size <= 1) // minorityreport.AVI block_align=1024 sample_size=1 IMA-ADPCM
            size= INT_MAX;
        else if(ast->sample_size < 32)
            size= 64*ast->sample_size;
        else
            size= ast->sample_size;
        if(size > ast->remaining)
            size= ast->remaining;
        av_get_packet(pb, pkt, size);
        if(ast->has_pal && pkt->data && pkt->size<(unsigned)INT_MAX/2){
            ast->has_pal=0;
            pkt->size += 4*256;
            pkt->data = av_realloc(pkt->data, pkt->size + FF_INPUT_BUFFER_PADDING_SIZE);
            if(pkt->data)
                memcpy(pkt->data + pkt->size - 4*256, ast->pal, 4*256);
        }
        if (ENABLE_DV_DEMUXER && avi->dv_demux) {
            dstr = pkt->destruct;
            size = dv_produce_packet(avi->dv_demux, pkt,
                                    pkt->data, pkt->size);
            pkt->destruct = dstr;
            pkt->flags |= PKT_FLAG_KEY;
        } else {
            /* XXX: how to handle B frames in avi ? */
            pkt->dts = ast->frame_offset;
//                pkt->dts += ast->start;
            if(ast->sample_size)
                pkt->dts /= ast->sample_size;
//av_log(NULL, AV_LOG_DEBUG, "dts:%"PRId64" offset:%"PRId64" %d/%d smpl_siz:%d base:%d st:%d size:%d\n", pkt->dts, ast->frame_offset, ast->scale, ast->rate, ast->sample_size, AV_TIME_BASE, avi->stream_index, size);
            pkt->stream_index = avi->stream_index;
            if (st->codec->codec_type == CODEC_TYPE_VIDEO) {
                AVIndexEntry *e;
                int index;
                assert(st->index_entries);
                index= av_index_search_timestamp(st, pkt->dts, 0);
                e= &st->index_entries[index];
                if(index >= 0 && e->timestamp == ast->frame_offset){
                    if (e->flags & AVINDEX_KEYFRAME)
                        pkt->flags |= PKT_FLAG_KEY;
                }
            } else {
                pkt->flags |= PKT_FLAG_KEY;
            }
            if(ast->sample_size)
                ast->frame_offset += pkt->size;
            else
                ast->frame_offset++;
        }
        ast->remaining -= size;
        if(!ast->remaining){
            avi->stream_index= -1;
            ast->packet_size= 0;
        }
        return size;
    }
    memset(d, -1, sizeof(int)*8);
    for(i=sync=url_ftell(pb); !url_feof(pb); i++) {
        int j;
        for(j=0; j<7; j++)
            d[j]= d[j+1];
        d[7]= get_byte(pb);
        size= d[4] + (d[5]<<8) + (d[6]<<16) + (d[7]<<24);
        if(    d[2] >= '0' && d[2] <= '9'
            && d[3] >= '0' && d[3] <= '9'){
            n= (d[2] - '0') * 10 + (d[3] - '0');
        }else{
            n= 100; //invalid stream id
        }
//av_log(NULL, AV_LOG_DEBUG, "%X %X %X %X %X %X %X %X %"PRId64" %d %d\n", d[0], d[1], d[2], d[3], d[4], d[5], d[6], d[7], i, size, n);
        if(i + size > avi->fsize || d[0]<0)
            continue;
        //parse ix##
        if(  (d[0] == 'i' && d[1] == 'x' && n < s->nb_streams)
        //parse JUNK
           ||(d[0] == 'J' && d[1] == 'U' && d[2] == 'N' && d[3] == 'K')
           ||(d[0] == 'i' && d[1] == 'd' && d[2] == 'x' && d[3] == '1')){
            url_fskip(pb, size);
//av_log(NULL, AV_LOG_DEBUG, "SKIP\n");
            goto resync;
        }
        if(    d[0] >= '0' && d[0] <= '9'
            && d[1] >= '0' && d[1] <= '9'){
            n= (d[0] - '0') * 10 + (d[1] - '0');
        }else{
            n= 100; //invalid stream id
        }
        //parse ##dc/##wb
        if(n < s->nb_streams){
            AVStream *st;
            AVIStream *ast;
            st = s->streams[n];
            ast = st->priv_data;
            if(s->nb_streams>=2){
                AVStream *st1  = s->streams[1];
                AVIStream *ast1= st1->priv_data;
                //workaround for broken small-file-bug402.avi
                if(   d[2] == 'w' && d[3] == 'b'
                   && n==0
                   && st ->codec->codec_type == CODEC_TYPE_VIDEO
                   && st1->codec->codec_type == CODEC_TYPE_AUDIO
                   && ast->prefix == 'd'*256+'c'
                   && (d[2]*256+d[3] == ast1->prefix || !ast1->prefix_count)
                  ){
                    n=1;
                    st = st1;
                    ast = ast1;
                    av_log(s, AV_LOG_WARNING, "Invalid stream+prefix combination, assuming audio\n");
                }
            }
            if(   (st->discard >= AVDISCARD_DEFAULT && size==0)
               /*|| (st->discard >= AVDISCARD_NONKEY && !(pkt->flags & PKT_FLAG_KEY))*/ //FIXME needs a little reordering
               || st->discard >= AVDISCARD_ALL){
                if(ast->sample_size) ast->frame_offset += pkt->size;
                else                 ast->frame_offset++;
                url_fskip(pb, size);
                goto resync;
            }
            if (d[2] == 'p' && d[3] == 'c' && size<=4*256+4) {
                int k = get_byte(pb);
                int last = (k + get_byte(pb) - 1) & 0xFF;
                get_le16(pb); //flags
                for (; k <= last; k++)
                    ast->pal[k] = get_be32(pb)>>8;// b + (g << 8) + (r << 16);
                ast->has_pal= 1;
                goto resync;
            } else if(   ((ast->prefix_count<5 || sync+9 > i) && d[2]<128 && d[3]<128) ||
                         d[2]*256+d[3] == ast->prefix /*||
                         (d[2] == 'd' && d[3] == 'c') ||
                         (d[2] == 'w' && d[3] == 'b')*/) {
//av_log(NULL, AV_LOG_DEBUG, "OK\n");
                if(d[2]*256+d[3] == ast->prefix)
                    ast->prefix_count++;
                else{
                    ast->prefix= d[2]*256+d[3];
                    ast->prefix_count= 0;
                }
                avi->stream_index= n;
                ast->packet_size= size + 8;
                ast->remaining= size;
                {
                    uint64_t pos= url_ftell(pb) - 8;
                    if(!st->index_entries || !st->nb_index_entries || st->index_entries[st->nb_index_entries - 1].pos < pos){
                        av_add_index_entry(st, pos, ast->frame_offset / FFMAX(1, ast->sample_size), size, 0, AVINDEX_KEYFRAME);
                    }
                }
                goto resync;
            }
        }
    }
}

int decode_luma_residual(const H264Context *h, H264SliceContext *sl,

                         GetBitContext *gb, const uint8_t *scan,

                         const uint8_t *scan8x8, int pixel_shift,

                         int mb_type, int cbp, int p)

{

    int i4x4, i8x8;

    int qscale = p == 0 ? sl->qscale : sl->chroma_qp[p - 1];

    if(IS_INTRA16x16(mb_type)){

        AV_ZERO128(sl->mb_luma_dc[p]+0);

        AV_ZERO128(sl->mb_luma_dc[p]+8);

        AV_ZERO128(sl->mb_luma_dc[p]+16);

        AV_ZERO128(sl->mb_luma_dc[p]+24);

        if (decode_residual(h, sl, gb, sl->mb_luma_dc[p], LUMA_DC_BLOCK_INDEX + p, scan, NULL, 16) < 0) {

            return -1; //FIXME continue if partitioned and other return -1 too

        }



        assert((cbp&15) == 0 || (cbp&15) == 15);



        if(cbp&15){

            for(i8x8=0; i8x8<4; i8x8++){

                for(i4x4=0; i4x4<4; i4x4++){

                    const int index= i4x4 + 4*i8x8 + p*16;

                    if( decode_residual(h, sl, gb, sl->mb + (16*index << pixel_shift),

                        index, scan + 1, h->dequant4_coeff[p][qscale], 15) < 0 ){

                        return -1;

                    }

                }

            }

            return 0xf;

        }else{

            fill_rectangle(&sl->non_zero_count_cache[scan8[p*16]], 4, 4, 8, 0, 1);

            return 0;

        }

    }else{

        int cqm = (IS_INTRA( mb_type ) ? 0:3)+p;

        /* For CAVLC 4:4:4, we need to keep track of the luma 8x8 CBP for deblocking nnz purposes. */

        int new_cbp = 0;

        for(i8x8=0; i8x8<4; i8x8++){

            if(cbp & (1<<i8x8)){

                if(IS_8x8DCT(mb_type)){

                    int16_t *buf = &sl->mb[64*i8x8+256*p << pixel_shift];

                    uint8_t *nnz;

                    for(i4x4=0; i4x4<4; i4x4++){

                        const int index= i4x4 + 4*i8x8 + p*16;

                        if( decode_residual(h, sl, gb, buf, index, scan8x8+16*i4x4,

                                            h->dequant8_coeff[cqm][qscale], 16) < 0 )

                            return -1;

                    }

                    nnz = &sl->non_zero_count_cache[scan8[4 * i8x8 + p * 16]];

                    nnz[0] += nnz[1] + nnz[8] + nnz[9];

                    new_cbp |= !!nnz[0] << i8x8;

                }else{

                    for(i4x4=0; i4x4<4; i4x4++){

                        const int index= i4x4 + 4*i8x8 + p*16;

                        if( decode_residual(h, sl, gb, sl->mb + (16*index << pixel_shift), index,

                                            scan, h->dequant4_coeff[cqm][qscale], 16) < 0 ){

                            return -1;

                        }

                        new_cbp |= sl->non_zero_count_cache[scan8[index]] << i8x8;

                    }

                }

            }else{

                uint8_t * const nnz = &sl->non_zero_count_cache[scan8[4 * i8x8 + p * 16]];

                nnz[0] = nnz[1] = nnz[8] = nnz[9] = 0;

            }

        }

        return new_cbp;

    }

}

static int get_codec_data(AVIOContext *pb, AVStream *vst,

                          AVStream *ast, int myth)

{

    nuv_frametype frametype;



    if (!vst && !myth)

        return 1; // no codec data needed

    while (!avio_feof(pb)) {

        int size, subtype;



        frametype = avio_r8(pb);

        switch (frametype) {

        case NUV_EXTRADATA:

            subtype = avio_r8(pb);

            avio_skip(pb, 6);

            size = PKTSIZE(avio_rl32(pb));

            if (vst && subtype == 'R') {

                if (vst->codecpar->extradata) {

                    av_freep(&vst->codecpar->extradata);

                    vst->codecpar->extradata_size = 0;

                }

                if (ff_get_extradata(NULL, vst->codecpar, pb, size) < 0)

                    return AVERROR(ENOMEM);

                size = 0;

                if (!myth)

                    return 0;

            }

            break;

        case NUV_MYTHEXT:

            avio_skip(pb, 7);

            size = PKTSIZE(avio_rl32(pb));

            if (size != 128 * 4)

                break;

            avio_rl32(pb); // version

            if (vst) {

                vst->codecpar->codec_tag = avio_rl32(pb);

                vst->codecpar->codec_id =

                    ff_codec_get_id(ff_codec_bmp_tags, vst->codecpar->codec_tag);

                if (vst->codecpar->codec_tag == MKTAG('R', 'J', 'P', 'G'))

                    vst->codecpar->codec_id = AV_CODEC_ID_NUV;

            } else

                avio_skip(pb, 4);



            if (ast) {

                int id;



                ast->codecpar->codec_tag             = avio_rl32(pb);

                ast->codecpar->sample_rate           = avio_rl32(pb);

                ast->codecpar->bits_per_coded_sample = avio_rl32(pb);

                ast->codecpar->channels              = avio_rl32(pb);

                ast->codecpar->channel_layout        = 0;



                id = ff_wav_codec_get_id(ast->codecpar->codec_tag,

                                         ast->codecpar->bits_per_coded_sample);

                if (id == AV_CODEC_ID_NONE) {

                    id = ff_codec_get_id(nuv_audio_tags, ast->codecpar->codec_tag);

                    if (id == AV_CODEC_ID_PCM_S16LE)

                        id = ff_get_pcm_codec_id(ast->codecpar->bits_per_coded_sample,

                                                 0, 0, ~1);

                }

                ast->codecpar->codec_id = id;



                ast->need_parsing = AVSTREAM_PARSE_FULL;

            } else

                avio_skip(pb, 4 * 4);



            size -= 6 * 4;

            avio_skip(pb, size);

            return 0;

        case NUV_SEEKP:

            size = 11;

            break;

        default:

            avio_skip(pb, 7);

            size = PKTSIZE(avio_rl32(pb));

            break;

        }

        avio_skip(pb, size);

    }



    return 0;

}

static void h264_h_loop_filter_luma_c(uint8_t *pix, int stride, int alpha, int beta, int8_t *tc0)

{

    h264_loop_filter_luma_c(pix, 1, stride, alpha, beta, tc0);

}

static int avi_read_header(AVFormatContext *s)

{

    AVIContext *avi = s->priv_data;

    AVIOContext *pb = s->pb;

    unsigned int tag, tag1, handler;

    int codec_type, stream_index, frame_period;

    unsigned int size;

    int i;

    AVStream *st;

    AVIStream *ast      = NULL;

    int avih_width      = 0, avih_height = 0;

    int amv_file_format = 0;

    uint64_t list_end   = 0;

    int ret;



    avi->stream_index = -1;



    ret = get_riff(s, pb);

    if (ret < 0)

        return ret;



    avi->fsize = avio_size(pb);

    if (avi->fsize <= 0)

        avi->fsize = avi->riff_end == 8 ? INT64_MAX : avi->riff_end;



    /* first list tag */

    stream_index = -1;

    codec_type   = -1;

    frame_period = 0;

    for (;;) {

        if (pb->eof_reached)

            goto fail;

        tag  = avio_rl32(pb);

        size = avio_rl32(pb);



        print_tag("tag", tag, size);



        switch (tag) {

        case MKTAG('L', 'I', 'S', 'T'):

            list_end = avio_tell(pb) + size;

            /* Ignored, except at start of video packets. */

            tag1 = avio_rl32(pb);



            print_tag("list", tag1, 0);



            if (tag1 == MKTAG('m', 'o', 'v', 'i')) {

                avi->movi_list = avio_tell(pb) - 4;

                if (size)

                    avi->movi_end = avi->movi_list + size + (size & 1);

                else

                    avi->movi_end = avio_size(pb);

                av_dlog(NULL, "movi end=%"PRIx64"\n", avi->movi_end);

                goto end_of_header;

            } else if (tag1 == MKTAG('I', 'N', 'F', 'O'))

                ff_read_riff_info(s, size - 4);

            else if (tag1 == MKTAG('n', 'c', 'd', 't'))

                avi_read_nikon(s, list_end);



            break;

        case MKTAG('I', 'D', 'I', 'T'):

        {

            unsigned char date[64] = { 0 };

            size += (size & 1);

            size -= avio_read(pb, date, FFMIN(size, sizeof(date) - 1));

            avio_skip(pb, size);

            avi_metadata_creation_time(&s->metadata, date);

            break;

        }

        case MKTAG('d', 'm', 'l', 'h'):

            avi->is_odml = 1;

            avio_skip(pb, size + (size & 1));

            break;

        case MKTAG('a', 'm', 'v', 'h'):

            amv_file_format = 1;

        case MKTAG('a', 'v', 'i', 'h'):

            /* AVI header */

            /* using frame_period is bad idea */

            frame_period = avio_rl32(pb);

            avio_skip(pb, 4);

            avio_rl32(pb);

            avi->non_interleaved |= avio_rl32(pb) & AVIF_MUSTUSEINDEX;



            avio_skip(pb, 2 * 4);

            avio_rl32(pb);

            avio_rl32(pb);

            avih_width  = avio_rl32(pb);

            avih_height = avio_rl32(pb);



            avio_skip(pb, size - 10 * 4);

            break;

        case MKTAG('s', 't', 'r', 'h'):

            /* stream header */



            tag1    = avio_rl32(pb);

            handler = avio_rl32(pb); /* codec tag */



            if (tag1 == MKTAG('p', 'a', 'd', 's')) {

                avio_skip(pb, size - 8);

                break;

            } else {

                stream_index++;

                st = avformat_new_stream(s, NULL);

                if (!st)

                    goto fail;



                st->id = stream_index;

                ast    = av_mallocz(sizeof(AVIStream));

                if (!ast)

                    goto fail;

                st->priv_data = ast;

            }

            if (amv_file_format)

                tag1 = stream_index ? MKTAG('a', 'u', 'd', 's')

                                    : MKTAG('v', 'i', 'd', 's');



            print_tag("strh", tag1, -1);



            if (tag1 == MKTAG('i', 'a', 'v', 's') ||

                tag1 == MKTAG('i', 'v', 'a', 's')) {

                int64_t dv_dur;



                /* After some consideration -- I don't think we

                 * have to support anything but DV in type1 AVIs. */

                if (s->nb_streams != 1)

                    goto fail;



                if (handler != MKTAG('d', 'v', 's', 'd') &&

                    handler != MKTAG('d', 'v', 'h', 'd') &&

                    handler != MKTAG('d', 'v', 's', 'l'))

                    goto fail;



                ast = s->streams[0]->priv_data;

                av_freep(&s->streams[0]->codec->extradata);

                av_freep(&s->streams[0]->codec);

                av_freep(&s->streams[0]->info);

                av_freep(&s->streams[0]);

                s->nb_streams = 0;

                if (CONFIG_DV_DEMUXER) {

                    avi->dv_demux = avpriv_dv_init_demux(s);

                    if (!avi->dv_demux)

                        goto fail;

                } else

                    goto fail;

                s->streams[0]->priv_data = ast;

                avio_skip(pb, 3 * 4);

                ast->scale = avio_rl32(pb);

                ast->rate  = avio_rl32(pb);

                avio_skip(pb, 4);  /* start time */



                dv_dur = avio_rl32(pb);

                if (ast->scale > 0 && ast->rate > 0 && dv_dur > 0) {

                    dv_dur     *= AV_TIME_BASE;

                    s->duration = av_rescale(dv_dur, ast->scale, ast->rate);

                }

                /* else, leave duration alone; timing estimation in utils.c

                 * will make a guess based on bitrate. */



                stream_index = s->nb_streams - 1;

                avio_skip(pb, size - 9 * 4);

                break;

            }



            assert(stream_index < s->nb_streams);

            st->codec->stream_codec_tag = handler;



            avio_rl32(pb); /* flags */

            avio_rl16(pb); /* priority */

            avio_rl16(pb); /* language */

            avio_rl32(pb); /* initial frame */

            ast->scale = avio_rl32(pb);

            ast->rate  = avio_rl32(pb);

            if (!(ast->scale && ast->rate)) {

                av_log(s, AV_LOG_WARNING,

                       "scale/rate is %"PRIu32"/%"PRIu32" which is invalid. "

                       "(This file has been generated by broken software.)\n",

                       ast->scale,

                       ast->rate);

                if (frame_period) {

                    ast->rate  = 1000000;

                    ast->scale = frame_period;

                } else {

                    ast->rate  = 25;

                    ast->scale = 1;

                }

            }

            avpriv_set_pts_info(st, 64, ast->scale, ast->rate);



            ast->cum_len  = avio_rl32(pb); /* start */

            st->nb_frames = avio_rl32(pb);



            st->start_time = 0;

            avio_rl32(pb); /* buffer size */

            avio_rl32(pb); /* quality */

            ast->sample_size = avio_rl32(pb); /* sample ssize */

            ast->cum_len    *= FFMAX(1, ast->sample_size);

            av_dlog(s, "%"PRIu32" %"PRIu32" %d\n",

                    ast->rate, ast->scale, ast->sample_size);



            switch (tag1) {

            case MKTAG('v', 'i', 'd', 's'):

                codec_type = AVMEDIA_TYPE_VIDEO;



                ast->sample_size = 0;

                break;

            case MKTAG('a', 'u', 'd', 's'):

                codec_type = AVMEDIA_TYPE_AUDIO;

                break;

            case MKTAG('t', 'x', 't', 's'):

                codec_type = AVMEDIA_TYPE_SUBTITLE;

                break;

            case MKTAG('d', 'a', 't', 's'):

                codec_type = AVMEDIA_TYPE_DATA;

                break;

            default:

                av_log(s, AV_LOG_ERROR, "unknown stream type %X\n", tag1);

                goto fail;

            }

            if (ast->sample_size == 0)

                st->duration = st->nb_frames;

            ast->frame_offset = ast->cum_len;

            avio_skip(pb, size - 12 * 4);

            break;

        case MKTAG('s', 't', 'r', 'f'):

            /* stream header */

            if (stream_index >= (unsigned)s->nb_streams || avi->dv_demux) {

                avio_skip(pb, size);

            } else {

                uint64_t cur_pos = avio_tell(pb);

                if (cur_pos < list_end)

                    size = FFMIN(size, list_end - cur_pos);

                st = s->streams[stream_index];

                switch (codec_type) {

                case AVMEDIA_TYPE_VIDEO:

                    if (amv_file_format) {

                        st->codec->width      = avih_width;

                        st->codec->height     = avih_height;

                        st->codec->codec_type = AVMEDIA_TYPE_VIDEO;

                        st->codec->codec_id   = AV_CODEC_ID_AMV;

                        avio_skip(pb, size);

                        break;

                    }

                    tag1 = ff_get_bmp_header(pb, st);



                    if (tag1 == MKTAG('D', 'X', 'S', 'B') ||

                        tag1 == MKTAG('D', 'X', 'S', 'A')) {

                        st->codec->codec_type = AVMEDIA_TYPE_SUBTITLE;

                        st->codec->codec_tag  = tag1;

                        st->codec->codec_id   = AV_CODEC_ID_XSUB;

                        break;

                    }



                    if (size > 10 * 4 && size < (1 << 30)) {

                        st->codec->extradata_size = size - 10 * 4;

                        st->codec->extradata      = av_malloc(st->codec->extradata_size +

                                                              FF_INPUT_BUFFER_PADDING_SIZE);

                        if (!st->codec->extradata) {

                            st->codec->extradata_size = 0;

                            return AVERROR(ENOMEM);

                        }

                        avio_read(pb,

                                  st->codec->extradata,

                                  st->codec->extradata_size);

                    }



                    // FIXME: check if the encoder really did this correctly

                    if (st->codec->extradata_size & 1)

                        avio_r8(pb);



                    /* Extract palette from extradata if bpp <= 8.

                     * This code assumes that extradata contains only palette.

                     * This is true for all paletted codecs implemented in

                     * Libav. */

                    if (st->codec->extradata_size &&

                        (st->codec->bits_per_coded_sample <= 8)) {

                        int pal_size = (1 << st->codec->bits_per_coded_sample) << 2;

                        const uint8_t *pal_src;



                        pal_size = FFMIN(pal_size, st->codec->extradata_size);

                        pal_src  = st->codec->extradata +

                                   st->codec->extradata_size - pal_size;

#if HAVE_BIGENDIAN

                        for (i = 0; i < pal_size / 4; i++)

                            ast->pal[i] = av_bswap32(((uint32_t *)pal_src)[i]);

#else

                        memcpy(ast->pal, pal_src, pal_size);

#endif

                        ast->has_pal = 1;

                    }



                    print_tag("video", tag1, 0);



                    st->codec->codec_type = AVMEDIA_TYPE_VIDEO;

                    st->codec->codec_tag  = tag1;

                    st->codec->codec_id   = ff_codec_get_id(ff_codec_bmp_tags,

                                                            tag1);

                    /* This is needed to get the pict type which is necessary

                     * for generating correct pts. */

                    st->need_parsing = AVSTREAM_PARSE_HEADERS;

                    // Support "Resolution 1:1" for Avid AVI Codec

                    if (tag1 == MKTAG('A', 'V', 'R', 'n') &&

                        st->codec->extradata_size >= 31   &&

                        !memcmp(&st->codec->extradata[28], "1:1", 3))

                        st->codec->codec_id = AV_CODEC_ID_RAWVIDEO;



                    if (st->codec->codec_tag == 0 && st->codec->height > 0 &&

                        st->codec->extradata_size < 1U << 30) {

                        st->codec->extradata_size += 9;

                        if ((ret = av_reallocp(&st->codec->extradata,

                                               st->codec->extradata_size +

                                               FF_INPUT_BUFFER_PADDING_SIZE)) < 0) {

                            st->codec->extradata_size = 0;

                            return ret;

                        } else

                            memcpy(st->codec->extradata + st->codec->extradata_size - 9,

                                   "BottomUp", 9);

                    }

                    st->codec->height = FFABS(st->codec->height);



//                    avio_skip(pb, size - 5 * 4);

                    break;

                case AVMEDIA_TYPE_AUDIO:

                    ret = ff_get_wav_header(pb, st->codec, size);

                    if (ret < 0)

                        return ret;

                    ast->dshow_block_align = st->codec->block_align;

                    if (ast->sample_size && st->codec->block_align &&

                        ast->sample_size != st->codec->block_align) {

                        av_log(s,

                               AV_LOG_WARNING,

                               "sample size (%d) != block align (%d)\n",

                               ast->sample_size,

                               st->codec->block_align);

                        ast->sample_size = st->codec->block_align;

                    }

                    /* 2-aligned

                     * (fix for Stargate SG-1 - 3x18 - Shades of Grey.avi) */

                    if (size & 1)

                        avio_skip(pb, 1);

                    /* Force parsing as several audio frames can be in

                     * one packet and timestamps refer to packet start. */

                    st->need_parsing = AVSTREAM_PARSE_TIMESTAMPS;

                    /* ADTS header is in extradata, AAC without header must be

                     * stored as exact frames. Parser not needed and it will

                     * fail. */

                    if (st->codec->codec_id == AV_CODEC_ID_AAC &&

                        st->codec->extradata_size)

                        st->need_parsing = AVSTREAM_PARSE_NONE;

                    /* AVI files with Xan DPCM audio (wrongly) declare PCM

                     * audio in the header but have Axan as stream_code_tag. */

                    if (st->codec->stream_codec_tag == AV_RL32("Axan")) {

                        st->codec->codec_id  = AV_CODEC_ID_XAN_DPCM;

                        st->codec->codec_tag = 0;

                    }

                    if (amv_file_format) {

                        st->codec->codec_id    = AV_CODEC_ID_ADPCM_IMA_AMV;

                        ast->dshow_block_align = 0;

                    }

                    break;

                case AVMEDIA_TYPE_SUBTITLE:

                    st->codec->codec_type = AVMEDIA_TYPE_SUBTITLE;

                    st->codec->codec_id   = AV_CODEC_ID_PROBE;

                    break;

                default:

                    st->codec->codec_type = AVMEDIA_TYPE_DATA;

                    st->codec->codec_id   = AV_CODEC_ID_NONE;

                    st->codec->codec_tag  = 0;

                    avio_skip(pb, size);

                    break;

                }

            }

            break;

        case MKTAG('i', 'n', 'd', 'x'):

            i = avio_tell(pb);

            if (pb->seekable && !(s->flags & AVFMT_FLAG_IGNIDX) &&

                read_braindead_odml_indx(s, 0) < 0 &&

                (s->error_recognition & AV_EF_EXPLODE))

                goto fail;

            avio_seek(pb, i + size, SEEK_SET);

            break;

        case MKTAG('v', 'p', 'r', 'p'):

            if (stream_index < (unsigned)s->nb_streams && size > 9 * 4) {

                AVRational active, active_aspect;



                st = s->streams[stream_index];

                avio_rl32(pb);

                avio_rl32(pb);

                avio_rl32(pb);

                avio_rl32(pb);

                avio_rl32(pb);



                active_aspect.den = avio_rl16(pb);

                active_aspect.num = avio_rl16(pb);

                active.num        = avio_rl32(pb);

                active.den        = avio_rl32(pb);

                avio_rl32(pb); // nbFieldsPerFrame



                if (active_aspect.num && active_aspect.den &&

                    active.num && active.den) {

                    st->sample_aspect_ratio = av_div_q(active_aspect, active);

                    av_dlog(s, "vprp %d/%d %d/%d\n",

                            active_aspect.num, active_aspect.den,

                            active.num, active.den);

                }

                size -= 9 * 4;

            }

            avio_skip(pb, size);

            break;

        case MKTAG('s', 't', 'r', 'n'):

            if (s->nb_streams) {

                ret = avi_read_tag(s, s->streams[s->nb_streams - 1], tag, size);

                if (ret < 0)

                    return ret;

                break;

            }

        default:

            if (size > 1000000) {

                av_log(s, AV_LOG_ERROR,

                       "Something went wrong during header parsing, "

                       "I will ignore it and try to continue anyway.\n");

                if (s->error_recognition & AV_EF_EXPLODE)

                    goto fail;

                avi->movi_list = avio_tell(pb) - 4;

                avi->movi_end  = avio_size(pb);

                goto end_of_header;

            }

            /* skip tag */

            size += (size & 1);

            avio_skip(pb, size);

            break;

        }

    }



end_of_header:

    /* check stream number */

    if (stream_index != s->nb_streams - 1) {



fail:

        return AVERROR_INVALIDDATA;

    }



    if (!avi->index_loaded && pb->seekable)

        avi_load_index(s);

    avi->index_loaded     = 1;

    avi->non_interleaved |= guess_ni_flag(s);

    for (i = 0; i < s->nb_streams; i++) {

        AVStream *st = s->streams[i];

        if (st->nb_index_entries)

            break;

    }

    if (i == s->nb_streams && avi->non_interleaved) {

        av_log(s, AV_LOG_WARNING,

               "Non-interleaved AVI without index, switching to interleaved\n");

        avi->non_interleaved = 0;

    }



    if (avi->non_interleaved) {

        av_log(s, AV_LOG_INFO, "non-interleaved AVI\n");

        clean_index(s);

    }



    ff_metadata_conv_ctx(s, NULL, avi_metadata_conv);

    ff_metadata_conv_ctx(s, NULL, ff_riff_info_conv);



    return 0;

}

static av_cold int g726_decode_init(AVCodecContext *avctx)

{

    G726Context* c = avctx->priv_data;



    if (avctx->sample_rate <= 0) {

        av_log(avctx, AV_LOG_ERROR, "Samplerate is invalid\n");

        return -1;

    }



    if(avctx->channels != 1){

        av_log(avctx, AV_LOG_ERROR, "Only mono is supported\n");

        return -1;

    }



    c->code_size = avctx->bits_per_coded_sample;

    if (c->code_size < 2 || c->code_size > 5) {

        av_log(avctx, AV_LOG_ERROR, "Invalid number of bits %d\n", c->code_size);

        return AVERROR(EINVAL);

    }

    g726_reset(c, c->code_size - 2);



    avctx->sample_fmt = AV_SAMPLE_FMT_S16;



    return 0;

}

static int mov_read_colr(MOVContext *c, AVIOContext *pb, MOVAtom atom)

{

    AVStream *st;

    char color_parameter_type[5] = { 0 };

    int color_primaries, color_trc, color_matrix;



    if (c->fc->nb_streams < 1)

        return 0;

    st = c->fc->streams[c->fc->nb_streams - 1];



    avio_read(pb, color_parameter_type, 4);

    if (strncmp(color_parameter_type, "nclx", 4) &&

        strncmp(color_parameter_type, "nclc", 4)) {

        av_log(c->fc, AV_LOG_WARNING, "unsupported color_parameter_type %s\n",

               color_parameter_type);

        return 0;

    }



    color_primaries = avio_rb16(pb);

    color_trc = avio_rb16(pb);

    color_matrix = avio_rb16(pb);



    av_dlog(c->fc, "%s: pri %d trc %d matrix %d",

            color_parameter_type, color_primaries, color_trc, color_matrix);



    if (c->isom) {

        uint8_t color_range = avio_r8(pb) >> 7;

        av_dlog(c->fc, " full %"PRIu8"", color_range);

        if (color_range)

            st->codec->color_range = AVCOL_RANGE_JPEG;

        else

            st->codec->color_range = AVCOL_RANGE_MPEG;

        /* 14496-12 references JPEG XR specs (rather than the more complete

         * 23001-8) so some adjusting is required */

        if (color_primaries >= AVCOL_PRI_FILM)

            color_primaries = AVCOL_PRI_UNSPECIFIED;

        if ((color_trc >= AVCOL_TRC_LINEAR &&

             color_trc <= AVCOL_TRC_LOG_SQRT) ||

            color_trc >= AVCOL_TRC_BT2020_10)

            color_trc = AVCOL_TRC_UNSPECIFIED;

        if (color_matrix >= AVCOL_SPC_BT2020_NCL)

            color_matrix = AVCOL_SPC_UNSPECIFIED;

        st->codec->color_primaries = color_primaries;

        st->codec->color_trc = color_trc;

        st->codec->colorspace = color_matrix;

    } else {

        /* color primaries, Table 4-4 */

        switch (color_primaries) {

        case 1: st->codec->color_primaries = AVCOL_PRI_BT709; break;

        case 5: st->codec->color_primaries = AVCOL_PRI_SMPTE170M; break;

        case 6: st->codec->color_primaries = AVCOL_PRI_SMPTE240M; break;

        }

        /* color transfer, Table 4-5 */

        switch (color_trc) {

        case 1: st->codec->color_trc = AVCOL_TRC_BT709; break;

        case 7: st->codec->color_trc = AVCOL_TRC_SMPTE240M; break;

        }

        /* color matrix, Table 4-6 */

        switch (color_matrix) {

        case 1: st->codec->colorspace = AVCOL_SPC_BT709; break;

        case 6: st->codec->colorspace = AVCOL_SPC_BT470BG; break;

        case 7: st->codec->colorspace = AVCOL_SPC_SMPTE240M; break;

        }

    }

    av_dlog(c->fc, "\n");



    return 0;

}

static inline void downmix_3f_1r_to_stereo(float *samples)

{

    int i;



    for (i = 0; i < 256; i++) {

        samples[i] += (samples[i + 256] + samples[i + 768]);

        samples[i + 256] += (samples[i + 512] + samples[i + 768]);

        samples[i + 512] = samples[i + 768] = 0;

    }

}

static int lmlm4_read_packet(AVFormatContext *s, AVPacket *pkt) {

    AVIOContext *pb = s->pb;

    int ret;

    unsigned int frame_type, packet_size, padding, frame_size;



    avio_rb16(pb);                       /* channel number */

    frame_type  = avio_rb16(pb);

    packet_size = avio_rb32(pb);

    padding     = -packet_size & 511;

    frame_size  = packet_size - 8;



    if (frame_type > LMLM4_MPEG1L2 || frame_type == LMLM4_INVALID) {

        av_log(s, AV_LOG_ERROR, "invalid or unsupported frame_type\n");

        return AVERROR(EIO);

    }

    if (packet_size > LMLM4_MAX_PACKET_SIZE) {

        av_log(s, AV_LOG_ERROR, "packet size exceeds maximum\n");

        return AVERROR(EIO);

    }



    if ((ret = av_get_packet(pb, pkt, frame_size)) <= 0)

        return AVERROR(EIO);



    avio_skip(pb, padding);



    switch (frame_type) {

        case LMLM4_I_FRAME:

            pkt->flags = AV_PKT_FLAG_KEY;

        case LMLM4_P_FRAME:

        case LMLM4_B_FRAME:

            pkt->stream_index = 0;

            break;

        case LMLM4_MPEG1L2:

            pkt->stream_index = 1;

            break;

    }



    return ret;

}

static int decode_frame(AVCodecContext *avctx, void *data, int *got_frame, AVPacket *pkt)

{

    BinkContext * const c = avctx->priv_data;

    GetBitContext gb;

    int plane, plane_idx, ret;

    int bits_count = pkt->size << 3;



    if (c->version > 'b') {

        if(c->pic->data[0])

            avctx->release_buffer(avctx, c->pic);



        if ((ret = ff_get_buffer(avctx, c->pic)) < 0) {

            av_log(avctx, AV_LOG_ERROR, "get_buffer() failed\n");

            return ret;

        }

    } else {

        if ((ret = avctx->reget_buffer(avctx, c->pic)) < 0) {

            av_log(avctx, AV_LOG_ERROR, "reget_buffer() failed\n");

            return ret;

        }

    }



    init_get_bits(&gb, pkt->data, bits_count);

    if (c->has_alpha) {

        if (c->version >= 'i')

            skip_bits_long(&gb, 32);

        if ((ret = bink_decode_plane(c, &gb, 3, 0)) < 0)

            return ret;

    }

    if (c->version >= 'i')

        skip_bits_long(&gb, 32);



    for (plane = 0; plane < 3; plane++) {

        plane_idx = (!plane || !c->swap_planes) ? plane : (plane ^ 3);



        if (c->version > 'b') {

            if ((ret = bink_decode_plane(c, &gb, plane_idx, !!plane)) < 0)

                return ret;

        } else {

            if ((ret = binkb_decode_plane(c, &gb, plane_idx, !pkt->pts, !!plane)) < 0)

                return ret;

        }

        if (get_bits_count(&gb) >= bits_count)

            break;

    }

    emms_c();



    *got_frame = 1;

    *(AVFrame*)data = *c->pic;



    if (c->version > 'b')

        FFSWAP(AVFrame*, c->pic, c->last);



    /* always report that the buffer was completely consumed */

    return pkt->size;

}

static int packed_16bpc_bswap(SwsContext *c, const uint8_t *src[],

                              int srcStride[], int srcSliceY, int srcSliceH,

                              uint8_t *dst[], int dstStride[])

{

    int i, j, p;



    for (p = 0; p < 4; p++) {

        int srcstr = srcStride[p] >> 1;

        int dststr = dstStride[p] >> 1;

        uint16_t       *dstPtr =       (uint16_t *) dst[p];

        const uint16_t *srcPtr = (const uint16_t *) src[p];

        int min_stride         = FFMIN(srcstr, dststr);

        if(!dstPtr || !srcPtr)

            continue;

        for (i = 0; i < (srcSliceH >> c->chrDstVSubSample); i++) {

            for (j = 0; j < min_stride; j++) {

                dstPtr[j] = av_bswap16(srcPtr[j]);

            }

            srcPtr += srcstr;

            dstPtr += dststr;

        }

    }



    return srcSliceH;

}

static void video_refresh(void *opaque)

{

    VideoState *is = opaque;

    VideoPicture *vp;

    double time;



    SubPicture *sp, *sp2;



    if (!is->paused && get_master_sync_type(is) == AV_SYNC_EXTERNAL_CLOCK && is->realtime)

        check_external_clock_speed(is);



    if (!display_disable && is->show_mode != SHOW_MODE_VIDEO && is->audio_st)

        video_display(is);



    if (is->video_st) {

        if (is->force_refresh)

            pictq_prev_picture(is);

retry:

        if (is->pictq_size == 0) {

            SDL_LockMutex(is->pictq_mutex);

            if (is->frame_last_dropped_pts != AV_NOPTS_VALUE && is->frame_last_dropped_pts > is->frame_last_pts) {

                update_video_pts(is, is->frame_last_dropped_pts, is->frame_last_dropped_pos, 0);

                is->frame_last_dropped_pts = AV_NOPTS_VALUE;

            }

            SDL_UnlockMutex(is->pictq_mutex);

            // nothing to do, no picture to display in the queue

        } else {

            double last_duration, duration, delay;

            /* dequeue the picture */

            vp = &is->pictq[is->pictq_rindex];



            if (vp->serial != is->videoq.serial) {

                pictq_next_picture(is);

                goto retry;

            }



            if (is->paused)

                goto display;



            /* compute nominal last_duration */

            last_duration = vp->pts - is->frame_last_pts;

            if (last_duration > 0 && last_duration < is->max_frame_duration) {

                /* if duration of the last frame was sane, update last_duration in video state */

                is->frame_last_duration = last_duration;

            }

            delay = compute_target_delay(is->frame_last_duration, is);



            time= av_gettime()/1000000.0;

            if (time < is->frame_timer + delay)

                return;



            if (delay > 0)

                is->frame_timer += delay * FFMAX(1, floor((time-is->frame_timer) / delay));



            SDL_LockMutex(is->pictq_mutex);

            update_video_pts(is, vp->pts, vp->pos, vp->serial);

            SDL_UnlockMutex(is->pictq_mutex);



            if (is->pictq_size > 1) {

                VideoPicture *nextvp = &is->pictq[(is->pictq_rindex + 1) % VIDEO_PICTURE_QUEUE_SIZE];

                duration = nextvp->pts - vp->pts;

                if(!is->step && (framedrop>0 || (framedrop && get_master_sync_type(is) != AV_SYNC_VIDEO_MASTER)) && time > is->frame_timer + duration){

                    is->frame_drops_late++;

                    pictq_next_picture(is);

                    goto retry;

                }

            }



            if (is->subtitle_st) {

                if (is->subtitle_stream_changed) {

                    SDL_LockMutex(is->subpq_mutex);



                    while (is->subpq_size) {

                        free_subpicture(&is->subpq[is->subpq_rindex]);



                        /* update queue size and signal for next picture */

                        if (++is->subpq_rindex == SUBPICTURE_QUEUE_SIZE)

                            is->subpq_rindex = 0;



                        is->subpq_size--;

                    }

                    is->subtitle_stream_changed = 0;



                    SDL_CondSignal(is->subpq_cond);

                    SDL_UnlockMutex(is->subpq_mutex);

                } else {

                    if (is->subpq_size > 0) {

                        sp = &is->subpq[is->subpq_rindex];



                        if (is->subpq_size > 1)

                            sp2 = &is->subpq[(is->subpq_rindex + 1) % SUBPICTURE_QUEUE_SIZE];

                        else

                            sp2 = NULL;



                        if ((is->video_current_pts > (sp->pts + ((float) sp->sub.end_display_time / 1000)))

                                || (sp2 && is->video_current_pts > (sp2->pts + ((float) sp2->sub.start_display_time / 1000))))

                        {

                            free_subpicture(sp);



                            /* update queue size and signal for next picture */

                            if (++is->subpq_rindex == SUBPICTURE_QUEUE_SIZE)

                                is->subpq_rindex = 0;



                            SDL_LockMutex(is->subpq_mutex);

                            is->subpq_size--;

                            SDL_CondSignal(is->subpq_cond);

                            SDL_UnlockMutex(is->subpq_mutex);

                        }

                    }

                }

            }



display:

            /* display picture */

            if (!display_disable && is->show_mode == SHOW_MODE_VIDEO)

                video_display(is);



            pictq_next_picture(is);



            if (is->step && !is->paused)

                stream_toggle_pause(is);

        }

    }

    is->force_refresh = 0;

    if (show_status) {

        static int64_t last_time;

        int64_t cur_time;

        int aqsize, vqsize, sqsize;

        double av_diff;



        cur_time = av_gettime();

        if (!last_time || (cur_time - last_time) >= 30000) {

            aqsize = 0;

            vqsize = 0;

            sqsize = 0;

            if (is->audio_st)

                aqsize = is->audioq.size;

            if (is->video_st)

                vqsize = is->videoq.size;

            if (is->subtitle_st)

                sqsize = is->subtitleq.size;

            av_diff = 0;

            if (is->audio_st && is->video_st)

                av_diff = get_audio_clock(is) - get_video_clock(is);

            printf("%7.2f A-V:%7.3f fd=%4d aq=%5dKB vq=%5dKB sq=%5dB f=%"PRId64"/%"PRId64"   \r",

                   get_master_clock(is),

                   av_diff,

                   is->frame_drops_early + is->frame_drops_late,

                   aqsize / 1024,

                   vqsize / 1024,

                   sqsize,

                   is->video_st ? is->video_st->codec->pts_correction_num_faulty_dts : 0,

                   is->video_st ? is->video_st->codec->pts_correction_num_faulty_pts : 0);

            fflush(stdout);

            last_time = cur_time;

        }

    }

}

static int alloc_buffer(FrameBuffer **pool, AVCodecContext *s, FrameBuffer **pbuf)

{

    const AVPixFmtDescriptor *desc = av_pix_fmt_desc_get(s->pix_fmt);

    FrameBuffer *buf;

    int i, ret;

    int pixel_size;

    int h_chroma_shift, v_chroma_shift;

    int edge = 32; // XXX should be avcodec_get_edge_width(), but that fails on svq1

    int w = s->width, h = s->height;



    if (!desc)

        return AVERROR(EINVAL);

    pixel_size = desc->comp[0].step_minus1 + 1;



    buf = av_mallocz(sizeof(*buf));

    if (!buf)

        return AVERROR(ENOMEM);



    if (!(s->flags & CODEC_FLAG_EMU_EDGE)) {

        w += 2*edge;

        h += 2*edge;

    }



    avcodec_align_dimensions(s, &w, &h);

    if ((ret = av_image_alloc(buf->base, buf->linesize, w, h,

                              s->pix_fmt, 32)) < 0) {

        av_freep(&buf);

        return ret;

    }

    /* XXX this shouldn't be needed, but some tests break without this line

     * those decoders are buggy and need to be fixed.

     * the following tests fail:

     */

    memset(buf->base[0], 128, ret);



    av_pix_fmt_get_chroma_sub_sample(s->pix_fmt,

                                     &h_chroma_shift, &v_chroma_shift);



    for (i = 0; i < FF_ARRAY_ELEMS(buf->data); i++) {

        const int h_shift = i==0 ? 0 : h_chroma_shift;

        const int v_shift = i==0 ? 0 : v_chroma_shift;

        if (s->flags & CODEC_FLAG_EMU_EDGE)

            buf->data[i] = buf->base[i];

        else if (buf->base[i])

            buf->data[i] = buf->base[i] +

                           FFALIGN((buf->linesize[i]*edge >> v_shift) +

                                   (pixel_size*edge >> h_shift), 32);

    }

    buf->w       = s->width;

    buf->h       = s->height;

    buf->pix_fmt = s->pix_fmt;

    buf->pool    = pool;



    *pbuf = buf;

    return 0;

}

