int ff_rate_control_init(MpegEncContext *s)

{

    RateControlContext *rcc= &s->rc_context;

    int i;

    const char *error = NULL;

    static const char * const const_names[]={

        "PI",

        "E",

        "iTex",

        "pTex",

        "tex",

        "mv",

        "fCode",

        "iCount",

        "mcVar",

        "var",

        "isI",

        "isP",

        "isB",

        "avgQP",

        "qComp",

/*        "lastIQP",

        "lastPQP",

        "lastBQP",

        "nextNonBQP",*/

        "avgIITex",

        "avgPITex",

        "avgPPTex",

        "avgBPTex",

        "avgTex",

        NULL

    };

    static double (*func1[])(void *, double)={

        (void *)bits2qp,

        (void *)qp2bits,

        NULL

    };

    static const char * const func1_names[]={

        "bits2qp",

        "qp2bits",

        NULL

    };

    emms_c();



    rcc->rc_eq_eval = ff_parse(s->avctx->rc_eq, const_names, func1, func1_names, NULL, NULL, &error);

    if (!rcc->rc_eq_eval) {

        av_log(s->avctx, AV_LOG_ERROR, "Error parsing rc_eq \"%s\": %s\n", s->avctx->rc_eq, error? error : "");

        return -1;

    }



    for(i=0; i<5; i++){

        rcc->pred[i].coeff= FF_QP2LAMBDA * 7.0;

        rcc->pred[i].count= 1.0;



        rcc->pred[i].decay= 0.4;

        rcc->i_cplx_sum [i]=

        rcc->p_cplx_sum [i]=

        rcc->mv_bits_sum[i]=

        rcc->qscale_sum [i]=

        rcc->frame_count[i]= 1; // 1 is better because of 1/0 and such

        rcc->last_qscale_for[i]=FF_QP2LAMBDA * 5;

    }

    rcc->buffer_index= s->avctx->rc_initial_buffer_occupancy;



    if(s->flags&CODEC_FLAG_PASS2){

        int i;

        char *p;



        /* find number of pics */

        p= s->avctx->stats_in;

        for(i=-1; p; i++){

            p= strchr(p+1, ';');

        }

        i+= s->max_b_frames;

        if(i<=0 || i>=INT_MAX / sizeof(RateControlEntry))

            return -1;

        rcc->entry = av_mallocz(i*sizeof(RateControlEntry));

        rcc->num_entries= i;



        /* init all to skipped p frames (with b frames we might have a not encoded frame at the end FIXME) */

        for(i=0; i<rcc->num_entries; i++){

            RateControlEntry *rce= &rcc->entry[i];

            rce->pict_type= rce->new_pict_type=FF_P_TYPE;

            rce->qscale= rce->new_qscale=FF_QP2LAMBDA * 2;

            rce->misc_bits= s->mb_num + 10;

            rce->mb_var_sum= s->mb_num*100;

        }



        /* read stats */

        p= s->avctx->stats_in;

        for(i=0; i<rcc->num_entries - s->max_b_frames; i++){

            RateControlEntry *rce;

            int picture_number;

            int e;

            char *next;



            next= strchr(p, ';');

            if(next){

                (*next)=0; //sscanf in unbelievably slow on looong strings //FIXME copy / do not write

                next++;

            }

            e= sscanf(p, " in:%d ", &picture_number);



            assert(picture_number >= 0);

            assert(picture_number < rcc->num_entries);

            rce= &rcc->entry[picture_number];



            e+=sscanf(p, " in:%*d out:%*d type:%d q:%f itex:%d ptex:%d mv:%d misc:%d fcode:%d bcode:%d mc-var:%d var:%d icount:%d skipcount:%d hbits:%d",

                   &rce->pict_type, &rce->qscale, &rce->i_tex_bits, &rce->p_tex_bits, &rce->mv_bits, &rce->misc_bits,

                   &rce->f_code, &rce->b_code, &rce->mc_mb_var_sum, &rce->mb_var_sum, &rce->i_count, &rce->skip_count, &rce->header_bits);

            if(e!=14){

                av_log(s->avctx, AV_LOG_ERROR, "statistics are damaged at line %d, parser out=%d\n", i, e);

                return -1;

            }



            p= next;

        }



        if(init_pass2(s) < 0) return -1;



        //FIXME maybe move to end

        if((s->flags&CODEC_FLAG_PASS2) && s->avctx->rc_strategy == FF_RC_STRATEGY_XVID) {

#ifdef CONFIG_LIBXVID

            return ff_xvid_rate_control_init(s);

#else

            av_log(s->avctx, AV_LOG_ERROR, "Xvid ratecontrol requires libavcodec compiled with Xvid support.\n");

            return -1;

#endif

        }

    }



    if(!(s->flags&CODEC_FLAG_PASS2)){



        rcc->short_term_qsum=0.001;

        rcc->short_term_qcount=0.001;



        rcc->pass1_rc_eq_output_sum= 0.001;

        rcc->pass1_wanted_bits=0.001;



        if(s->avctx->qblur > 1.0){

            av_log(s->avctx, AV_LOG_ERROR, "qblur too large\n");

            return -1;

        }

        /* init stuff with the user specified complexity */

        if(s->avctx->rc_initial_cplx){

            for(i=0; i<60*30; i++){

                double bits= s->avctx->rc_initial_cplx * (i/10000.0 + 1.0)*s->mb_num;

                RateControlEntry rce;

                double q;



                if     (i%((s->gop_size+3)/4)==0) rce.pict_type= FF_I_TYPE;

                else if(i%(s->max_b_frames+1))    rce.pict_type= FF_B_TYPE;

                else                              rce.pict_type= FF_P_TYPE;



                rce.new_pict_type= rce.pict_type;

                rce.mc_mb_var_sum= bits*s->mb_num/100000;

                rce.mb_var_sum   = s->mb_num;

                rce.qscale   = FF_QP2LAMBDA * 2;

                rce.f_code   = 2;

                rce.b_code   = 1;

                rce.misc_bits= 1;



                if(s->pict_type== FF_I_TYPE){

                    rce.i_count   = s->mb_num;

                    rce.i_tex_bits= bits;

                    rce.p_tex_bits= 0;

                    rce.mv_bits= 0;

                }else{

                    rce.i_count   = 0; //FIXME we do know this approx

                    rce.i_tex_bits= 0;

                    rce.p_tex_bits= bits*0.9;

                    rce.mv_bits= bits*0.1;

                }

                rcc->i_cplx_sum [rce.pict_type] += rce.i_tex_bits*rce.qscale;

                rcc->p_cplx_sum [rce.pict_type] += rce.p_tex_bits*rce.qscale;

                rcc->mv_bits_sum[rce.pict_type] += rce.mv_bits;

                rcc->frame_count[rce.pict_type] ++;



                bits= rce.i_tex_bits + rce.p_tex_bits;



                q= get_qscale(s, &rce, rcc->pass1_wanted_bits/rcc->pass1_rc_eq_output_sum, i);

                rcc->pass1_wanted_bits+= s->bit_rate/(1/av_q2d(s->avctx->time_base)); //FIXME misbehaves a little for variable fps

            }

        }



    }



    return 0;

}

static int iec61883_read_header(AVFormatContext *context)

{

    struct iec61883_data *dv = context->priv_data;

    struct raw1394_portinfo pinf[16];

    rom1394_directory rom_dir;

    char *endptr;

    int inport;

    int nb_ports;

    int port = -1;

    int response;

    int i, j = 0;

    uint64_t guid = 0;



    dv->input_port = -1;

    dv->output_port = -1;

    dv->channel = -1;



    dv->raw1394 = raw1394_new_handle();



    if (!dv->raw1394) {

        av_log(context, AV_LOG_ERROR, "Failed to open IEEE1394 interface.\n");

        return AVERROR(EIO);

    }



    if ((nb_ports = raw1394_get_port_info(dv->raw1394, pinf, 16)) < 0) {

        av_log(context, AV_LOG_ERROR, "Failed to get number of IEEE1394 ports.\n");

        goto fail;

    }



    inport = strtol(context->filename, &endptr, 10);

    if (endptr != context->filename && *endptr == '\0') {

        av_log(context, AV_LOG_INFO, "Selecting IEEE1394 port: %d\n", inport);

        j = inport;

        nb_ports = inport + 1;

    } else if (strcmp(context->filename, "auto")) {

        av_log(context, AV_LOG_ERROR, "Invalid input \"%s\", you should specify "

               "\"auto\" for auto-detection, or the port number.\n", context->filename);

        goto fail;

    }



    if (dv->device_guid) {

        if (sscanf(dv->device_guid, "%llx", (long long unsigned int *)&guid) != 1) {

            av_log(context, AV_LOG_INFO, "Invalid dvguid parameter: %s\n",

                   dv->device_guid);

            goto fail;

        }

    }



    for (; j < nb_ports && port==-1; ++j) {

        raw1394_destroy_handle(dv->raw1394);



        if (!(dv->raw1394 = raw1394_new_handle_on_port(j))) {

            av_log(context, AV_LOG_ERROR, "Failed setting IEEE1394 port.\n");

            goto fail;

        }



        for (i=0; i<raw1394_get_nodecount(dv->raw1394); ++i) {



            /* Select device explicitly by GUID */



            if (guid > 1) {

                if (guid == rom1394_get_guid(dv->raw1394, i)) {

                    dv->node = i;

                    port = j;

                    break;

                }

            } else {



                /* Select first AV/C tape recorder player node */



                if (rom1394_get_directory(dv->raw1394, i, &rom_dir) < 0)

                    continue;

                if (((rom1394_get_node_type(&rom_dir) == ROM1394_NODE_TYPE_AVC) &&

                     avc1394_check_subunit_type(dv->raw1394, i, AVC1394_SUBUNIT_TYPE_VCR)) ||

                    (rom_dir.unit_spec_id == MOTDCT_SPEC_ID)) {

                    rom1394_free_directory(&rom_dir);

                    dv->node = i;

                    port = j;

                    break;

                }

                rom1394_free_directory(&rom_dir);

            }

        }

    }



    if (port == -1) {

        av_log(context, AV_LOG_ERROR, "No AV/C devices found.\n");

        goto fail;

    }



    /* Provide bus sanity for multiple connections */



    iec61883_cmp_normalize_output(dv->raw1394, 0xffc0 | dv->node);



    /* Find out if device is DV or HDV */



    if (dv->type == IEC61883_AUTO) {

        response = avc1394_transaction(dv->raw1394, dv->node,

                                       AVC1394_CTYPE_STATUS |

                                       AVC1394_SUBUNIT_TYPE_TAPE_RECORDER |

                                       AVC1394_SUBUNIT_ID_0 |

                                       AVC1394_VCR_COMMAND_OUTPUT_SIGNAL_MODE |

                                       0xFF, 2);

        response = AVC1394_GET_OPERAND0(response);

        dv->type = (response == 0x10 || response == 0x90 || response == 0x1A || response == 0x9A) ?

            IEC61883_HDV : IEC61883_DV;

    }



    /* Connect to device, and do initialization */



    dv->channel = iec61883_cmp_connect(dv->raw1394, dv->node, &dv->output_port,

                                       raw1394_get_local_id(dv->raw1394),

                                       &dv->input_port, &dv->bandwidth);



    if (dv->channel < 0)

        dv->channel = 63;



    if (!dv->max_packets)

        dv->max_packets = 100;



    if (CONFIG_MPEGTS_DEMUXER && dv->type == IEC61883_HDV) {



        /* Init HDV receive */



        avformat_new_stream(context, NULL);



        dv->mpeg_demux = avpriv_mpegts_parse_open(context);

        if (!dv->mpeg_demux)

            goto fail;



        dv->parse_queue = iec61883_parse_queue_hdv;



        dv->iec61883_mpeg2 = iec61883_mpeg2_recv_init(dv->raw1394,

                                                      (iec61883_mpeg2_recv_t)iec61883_callback,

                                                      dv);



        dv->max_packets *= 766;

    } else {



        /* Init DV receive */



        dv->dv_demux = avpriv_dv_init_demux(context);

        if (!dv->dv_demux)

            goto fail;



        dv->parse_queue = iec61883_parse_queue_dv;



        dv->iec61883_dv = iec61883_dv_fb_init(dv->raw1394, iec61883_callback, dv);

    }



    dv->raw1394_poll.fd = raw1394_get_fd(dv->raw1394);

    dv->raw1394_poll.events = POLLIN | POLLERR | POLLHUP | POLLPRI;



    /* Actually start receiving */



    if (dv->type == IEC61883_HDV)

        iec61883_mpeg2_recv_start(dv->iec61883_mpeg2, dv->channel);

    else

        iec61883_dv_fb_start(dv->iec61883_dv, dv->channel);



#if THREADS

    dv->thread_loop = 1;

    pthread_mutex_init(&dv->mutex, NULL);

    pthread_cond_init(&dv->cond, NULL);

    pthread_create(&dv->receive_task_thread, NULL, iec61883_receive_task, dv);

#endif



    return 0;



fail:

    raw1394_destroy_handle(dv->raw1394);

    return AVERROR(EIO);

}

static int idcin_decode_frame(AVCodecContext *avctx,

                              void *data, int *data_size,

                              AVPacket *avpkt)

{

    const uint8_t *buf = avpkt->data;

    int buf_size = avpkt->size;

    IdcinContext *s = avctx->priv_data;

    const uint8_t *pal = av_packet_get_side_data(avpkt, AV_PKT_DATA_PALETTE, NULL);



    s->buf = buf;

    s->size = buf_size;



    if (s->frame.data[0])

        avctx->release_buffer(avctx, &s->frame);



    if (avctx->get_buffer(avctx, &s->frame)) {

        av_log(avctx, AV_LOG_ERROR, "get_buffer() failed\n");

        return -1;

    }



    idcin_decode_vlcs(s);



    if (pal) {

        s->frame.palette_has_changed = 1;

        memcpy(s->pal, pal, AVPALETTE_SIZE);

    }

    /* make the palette available on the way out */

    memcpy(s->frame.data[1], s->pal, AVPALETTE_SIZE);



    *data_size = sizeof(AVFrame);

    *(AVFrame*)data = s->frame;



    /* report that the buffer was completely consumed */

    return buf_size;

}

static void exit_program(void)

{

    int i, j;



    for (i = 0; i < nb_filtergraphs; i++) {

        avfilter_graph_free(&filtergraphs[i]->graph);

        for (j = 0; j < filtergraphs[i]->nb_inputs; j++) {

            av_freep(&filtergraphs[i]->inputs[j]->name);

            av_freep(&filtergraphs[i]->inputs[j]);

        }

        av_freep(&filtergraphs[i]->inputs);

        for (j = 0; j < filtergraphs[i]->nb_outputs; j++) {

            av_freep(&filtergraphs[i]->outputs[j]->name);

            av_freep(&filtergraphs[i]->outputs[j]);

        }

        av_freep(&filtergraphs[i]->outputs);

        av_freep(&filtergraphs[i]->graph_desc);

        av_freep(&filtergraphs[i]);

    }

    av_freep(&filtergraphs);



    /* close files */

    for (i = 0; i < nb_output_files; i++) {

        AVFormatContext *s = output_files[i]->ctx;

        if (s && s->oformat && !(s->oformat->flags & AVFMT_NOFILE) && s->pb)

            avio_close(s->pb);

        avformat_free_context(s);

        av_dict_free(&output_files[i]->opts);

        av_freep(&output_files[i]);

    }

    for (i = 0; i < nb_output_streams; i++) {

        AVBitStreamFilterContext *bsfc = output_streams[i]->bitstream_filters;

        while (bsfc) {

            AVBitStreamFilterContext *next = bsfc->next;

            av_bitstream_filter_close(bsfc);

            bsfc = next;

        }

        output_streams[i]->bitstream_filters = NULL;

        avcodec_free_frame(&output_streams[i]->filtered_frame);



        av_freep(&output_streams[i]->forced_keyframes);

        av_freep(&output_streams[i]->avfilter);

        av_freep(&output_streams[i]->logfile_prefix);

        av_freep(&output_streams[i]);

    }

    for (i = 0; i < nb_input_files; i++) {

        avformat_close_input(&input_files[i]->ctx);

        av_freep(&input_files[i]);

    }

    for (i = 0; i < nb_input_streams; i++) {

        av_frame_free(&input_streams[i]->decoded_frame);

        av_frame_free(&input_streams[i]->filter_frame);

        av_dict_free(&input_streams[i]->opts);

        av_freep(&input_streams[i]->filters);

        av_freep(&input_streams[i]);

    }



    if (vstats_file)

        fclose(vstats_file);

    av_free(vstats_filename);



    av_freep(&input_streams);

    av_freep(&input_files);

    av_freep(&output_streams);

    av_freep(&output_files);



    uninit_opts();



    avformat_network_deinit();



    if (received_sigterm) {

        av_log(NULL, AV_LOG_INFO, "Received signal %d: terminating.\n",

               (int) received_sigterm);

        exit (255);

    }

}

static int rpl_read_header(AVFormatContext *s)

{

    AVIOContext *pb = s->pb;

    RPLContext *rpl = s->priv_data;

    AVStream *vst = NULL, *ast = NULL;

    int total_audio_size;

    int error = 0;



    uint32_t i;



    int32_t audio_format, chunk_catalog_offset, number_of_chunks;

    AVRational fps;



    char line[RPL_LINE_LENGTH];



    // The header for RPL/ARMovie files is 21 lines of text

    // containing the various header fields.  The fields are always

    // in the same order, and other text besides the first

    // number usually isn't important.

    // (The spec says that there exists some significance

    // for the text in a few cases; samples needed.)

    error |= read_line(pb, line, sizeof(line));      // ARMovie

    error |= read_line(pb, line, sizeof(line));      // movie name

    av_dict_set(&s->metadata, "title"    , line, 0);

    error |= read_line(pb, line, sizeof(line));      // date/copyright

    av_dict_set(&s->metadata, "copyright", line, 0);

    error |= read_line(pb, line, sizeof(line));      // author and other

    av_dict_set(&s->metadata, "author"   , line, 0);



    // video headers

    vst = avformat_new_stream(s, NULL);

    if (!vst)

        return AVERROR(ENOMEM);

    vst->codec->codec_type      = AVMEDIA_TYPE_VIDEO;

    vst->codec->codec_tag       = read_line_and_int(pb, &error);  // video format

    vst->codec->width           = read_line_and_int(pb, &error);  // video width

    vst->codec->height          = read_line_and_int(pb, &error);  // video height

    vst->codec->bits_per_coded_sample = read_line_and_int(pb, &error);  // video bits per sample

    error |= read_line(pb, line, sizeof(line));                   // video frames per second

    fps = read_fps(line, &error);

    avpriv_set_pts_info(vst, 32, fps.den, fps.num);



    // Figure out the video codec

    switch (vst->codec->codec_tag) {

#if 0

        case 122:

            vst->codec->codec_id = AV_CODEC_ID_ESCAPE122;

            break;

#endif

        case 124:

            vst->codec->codec_id = AV_CODEC_ID_ESCAPE124;

            // The header is wrong here, at least sometimes

            vst->codec->bits_per_coded_sample = 16;

            break;

        case 130:

            vst->codec->codec_id = AV_CODEC_ID_ESCAPE130;

            break;

        default:

            avpriv_report_missing_feature(s, "Video format %i",

                                          vst->codec->codec_tag);

            vst->codec->codec_id = AV_CODEC_ID_NONE;

    }



    // Audio headers



    // ARMovie supports multiple audio tracks; I don't have any

    // samples, though. This code will ignore additional tracks.

    audio_format = read_line_and_int(pb, &error);  // audio format ID

    if (audio_format) {

        ast = avformat_new_stream(s, NULL);

        if (!ast)

            return AVERROR(ENOMEM);

        ast->codec->codec_type      = AVMEDIA_TYPE_AUDIO;

        ast->codec->codec_tag       = audio_format;

        ast->codec->sample_rate     = read_line_and_int(pb, &error);  // audio bitrate

        ast->codec->channels        = read_line_and_int(pb, &error);  // number of audio channels

        ast->codec->bits_per_coded_sample = read_line_and_int(pb, &error);  // audio bits per sample

        // At least one sample uses 0 for ADPCM, which is really 4 bits

        // per sample.

        if (ast->codec->bits_per_coded_sample == 0)

            ast->codec->bits_per_coded_sample = 4;



        ast->codec->bit_rate = ast->codec->sample_rate *

                               ast->codec->bits_per_coded_sample *

                               ast->codec->channels;



        ast->codec->codec_id = AV_CODEC_ID_NONE;

        switch (audio_format) {

            case 1:

                if (ast->codec->bits_per_coded_sample == 16) {

                    // 16-bit audio is always signed

                    ast->codec->codec_id = AV_CODEC_ID_PCM_S16LE;

                    break;

                }

                // There are some other formats listed as legal per the spec;

                // samples needed.

                break;

            case 101:

                if (ast->codec->bits_per_coded_sample == 8) {

                    // The samples with this kind of audio that I have

                    // are all unsigned.

                    ast->codec->codec_id = AV_CODEC_ID_PCM_U8;

                    break;

                } else if (ast->codec->bits_per_coded_sample == 4) {

                    ast->codec->codec_id = AV_CODEC_ID_ADPCM_IMA_EA_SEAD;

                    break;

                }

                break;

        }

        if (ast->codec->codec_id == AV_CODEC_ID_NONE)

            avpriv_request_sample(s, "Audio format %i", audio_format);

        avpriv_set_pts_info(ast, 32, 1, ast->codec->bit_rate);

    } else {

        for (i = 0; i < 3; i++)

            error |= read_line(pb, line, sizeof(line));

    }



    rpl->frames_per_chunk = read_line_and_int(pb, &error);  // video frames per chunk

    if (rpl->frames_per_chunk > 1 && vst->codec->codec_tag != 124)

        av_log(s, AV_LOG_WARNING,

               "Don't know how to split frames for video format %i. "

               "Video stream will be broken!\n", vst->codec->codec_tag);



    number_of_chunks = read_line_and_int(pb, &error);  // number of chunks in the file

    // The number in the header is actually the index of the last chunk.

    number_of_chunks++;



    error |= read_line(pb, line, sizeof(line));  // "even" chunk size in bytes

    error |= read_line(pb, line, sizeof(line));  // "odd" chunk size in bytes

    chunk_catalog_offset =                       // offset of the "chunk catalog"

        read_line_and_int(pb, &error);           //   (file index)

    error |= read_line(pb, line, sizeof(line));  // offset to "helpful" sprite

    error |= read_line(pb, line, sizeof(line));  // size of "helpful" sprite

    error |= read_line(pb, line, sizeof(line));  // offset to key frame list



    // Read the index

    avio_seek(pb, chunk_catalog_offset, SEEK_SET);

    total_audio_size = 0;

    for (i = 0; !error && i < number_of_chunks; i++) {

        int64_t offset, video_size, audio_size;

        error |= read_line(pb, line, sizeof(line));

        if (3 != sscanf(line, "%"SCNd64" , %"SCNd64" ; %"SCNd64,

                        &offset, &video_size, &audio_size))

            error = -1;

        av_add_index_entry(vst, offset, i * rpl->frames_per_chunk,

                           video_size, rpl->frames_per_chunk, 0);

        if (ast)

            av_add_index_entry(ast, offset + video_size, total_audio_size,

                               audio_size, audio_size * 8, 0);

        total_audio_size += audio_size * 8;

    }



    if (error) return AVERROR(EIO);



    return 0;

}

