    } else {

        s->vsample[0] = 2;

        s->vsample[1] = 2 >> chroma_v_shift;

        s->vsample[2] = 2 >> chroma_v_shift;

        s->hsample[0] = 2;

        s->hsample[1] = 2 >> chroma_h_shift;

        s->hsample[2] = 2 >> chroma_h_shift;

    }



    ff_mjpeg_build_huffman_codes(s->huff_size_dc_luminance,

                                 s->huff_code_dc_luminance,

