                                 s->huff_code_dc_chrominance,

                                 avpriv_mjpeg_bits_dc_chrominance,

                                 avpriv_mjpeg_val_dc);



    return 0;

}

static void encode_frame(MpegAudioContext *s,

                         unsigned char bit_alloc[MPA_MAX_CHANNELS][SBLIMIT],

                         int padding)

{

    int i, j, k, l, bit_alloc_bits, b, ch;

    unsigned char *sf;

    int q[3];

    PutBitContext *p = &s->pb;



    /* header */



    put_bits(p, 12, 0xfff);

    put_bits(p, 1, 1 - s->lsf); /* 1 = mpeg1 ID, 0 = mpeg2 lsf ID */

    put_bits(p, 2, 4-2);  /* layer 2 */

    put_bits(p, 1, 1); /* no error protection */

    put_bits(p, 4, s->bitrate_index);

    put_bits(p, 2, s->freq_index);

    put_bits(p, 1, s->do_padding); /* use padding */

    put_bits(p, 1, 0);             /* private_bit */

    put_bits(p, 2, s->nb_channels == 2 ? MPA_STEREO : MPA_MONO);

    put_bits(p, 2, 0); /* mode_ext */

    put_bits(p, 1, 0); /* no copyright */

    put_bits(p, 1, 1); /* original */

    put_bits(p, 2, 0); /* no emphasis */



    /* bit allocation */

    j = 0;

    for(i=0;i<s->sblimit;i++) {

        bit_alloc_bits = s->alloc_table[j];

        for(ch=0;ch<s->nb_channels;ch++) {

            put_bits(p, bit_alloc_bits, bit_alloc[ch][i]);

        }

        j += 1 << bit_alloc_bits;

    }



    /* scale codes */

    for(i=0;i<s->sblimit;i++) {

        for(ch=0;ch<s->nb_channels;ch++) {

            if (bit_alloc[ch][i])

                put_bits(p, 2, s->scale_code[ch][i]);

        }

    }



    /* scale factors */

    for(i=0;i<s->sblimit;i++) {

        for(ch=0;ch<s->nb_channels;ch++) {

            if (bit_alloc[ch][i]) {

                sf = &s->scale_factors[ch][i][0];

                switch(s->scale_code[ch][i]) {

                case 0:

                    put_bits(p, 6, sf[0]);

                    put_bits(p, 6, sf[1]);

                    put_bits(p, 6, sf[2]);

                    break;

                case 3:

                case 1:

                    put_bits(p, 6, sf[0]);

                    put_bits(p, 6, sf[2]);

                    break;

                case 2:

                    put_bits(p, 6, sf[0]);

                    break;

                }

            }

        }

    }



    /* quantization & write sub band samples */



    for(k=0;k<3;k++) {

        for(l=0;l<12;l+=3) {

            j = 0;

            for(i=0;i<s->sblimit;i++) {

                bit_alloc_bits = s->alloc_table[j];

                for(ch=0;ch<s->nb_channels;ch++) {

                    b = bit_alloc[ch][i];

                    if (b) {

                        int qindex, steps, m, sample, bits;

                        /* we encode 3 sub band samples of the same sub band at a time */

                        qindex = s->alloc_table[j+b];

                        steps = ff_mpa_quant_steps[qindex];

                        for(m=0;m<3;m++) {

                            sample = s->sb_samples[ch][k][l + m][i];

                            /* divide by scale factor */

#if USE_FLOATS

                            {

                                float a;

                                a = (float)sample * s->scale_factor_inv_table[s->scale_factors[ch][i][k]];

                                q[m] = (int)((a + 1.0) * steps * 0.5);

                            }

#else

                            {

                                int q1, e, shift, mult;

                                e = s->scale_factors[ch][i][k];

                                shift = s->scale_factor_shift[e];

                                mult = s->scale_factor_mult[e];



                                /* normalize to P bits */

                                if (shift < 0)

                                    q1 = sample << (-shift);

                                else

                                    q1 = sample >> shift;

                                q1 = (q1 * mult) >> P;

                                q1 += 1 << P;

                                if (q1 < 0)

                                    q1 = 0;

                                q[m] = (unsigned)(q1 * steps) >> (P + 1);

                            }

#endif

                            if (q[m] >= steps)

                                q[m] = steps - 1;

                            av_assert2(q[m] >= 0 && q[m] < steps);

                        }

                        bits = ff_mpa_quant_bits[qindex];

                        if (bits < 0) {

                            /* group the 3 values to save bits */

                            put_bits(p, -bits,

                                     q[0] + steps * (q[1] + steps * q[2]));

                        } else {

                            put_bits(p, bits, q[0]);

                            put_bits(p, bits, q[1]);

                            put_bits(p, bits, q[2]);

                        }

                    }

                }

                /* next subband in alloc table */

                j += 1 << bit_alloc_bits;

            }

        }

    }



    /* padding */

    for(i=0;i<padding;i++)

        put_bits(p, 1, 0);



    /* flush */

    flush_put_bits(p);

}

static int quantize_coefs(double *coef, int *idx, float *lpc, int order)

{

    int i;

    uint8_t u_coef;

    const float *quant_arr = tns_tmp2_map[TNS_Q_BITS == 4];

    const double iqfac_p = ((1 << (TNS_Q_BITS-1)) - 0.5)/(M_PI/2.0);

    const double iqfac_m = ((1 << (TNS_Q_BITS-1)) + 0.5)/(M_PI/2.0);

    for (i = 0; i < order; i++) {

        idx[i] = ceilf(asin(coef[i])*((coef[i] >= 0) ? iqfac_p : iqfac_m));

        u_coef = (idx[i])&(~(~0<<TNS_Q_BITS));

        lpc[i] = quant_arr[u_coef];

    }

    return order;

}

int avfilter_graph_add_filter(AVFilterGraph *graph, AVFilterContext *filter)

{

    graph->filters = av_realloc(graph->filters,

                                sizeof(AVFilterContext*) * ++graph->filter_count);



    if (!graph->filters)

        return AVERROR(ENOMEM);



    graph->filters[graph->filter_count - 1] = filter;



    return 0;

}

av_cold int ff_rate_control_init(MpegEncContext *s)

{

    RateControlContext *rcc = &s->rc_context;

    int i, res;

    static const char * const const_names[] = {

        "PI",

        "E",

        "iTex",

        "pTex",

        "tex",

        "mv",

        "fCode",

        "iCount",

        "mcVar",

        "var",

        "isI",

        "isP",

        "isB",

        "avgQP",

        "qComp",

#if 0

        "lastIQP",

        "lastPQP",

        "lastBQP",

        "nextNonBQP",

#endif

        "avgIITex",

        "avgPITex",

        "avgPPTex",

        "avgBPTex",

        "avgTex",

        NULL

    };

    static double (* const func1[])(void *, double) = {

        (void *)bits2qp,

        (void *)qp2bits,

        NULL

    };

    static const char * const func1_names[] = {

        "bits2qp",

        "qp2bits",

        NULL

    };

    emms_c();



    if (!s->avctx->rc_max_available_vbv_use && s->avctx->rc_buffer_size) {

        if (s->avctx->rc_max_rate) {

            s->avctx->rc_max_available_vbv_use = av_clipf(s->avctx->rc_max_rate/(s->avctx->rc_buffer_size*get_fps(s->avctx)), 1.0/3, 1.0);

        } else

            s->avctx->rc_max_available_vbv_use = 1.0;

    }



    res = av_expr_parse(&rcc->rc_eq_eval,

                        s->rc_eq ? s->rc_eq : "tex^qComp",

                        const_names, func1_names, func1,

                        NULL, NULL, 0, s->avctx);

    if (res < 0) {

        av_log(s->avctx, AV_LOG_ERROR, "Error parsing rc_eq \"%s\"\n", s->rc_eq);

        return res;

    }



    for (i = 0; i < 5; i++) {

        rcc->pred[i].coeff = FF_QP2LAMBDA * 7.0;

        rcc->pred[i].count = 1.0;

        rcc->pred[i].decay = 0.4;



        rcc->i_cplx_sum [i] =

        rcc->p_cplx_sum [i] =

        rcc->mv_bits_sum[i] =

        rcc->qscale_sum [i] =

        rcc->frame_count[i] = 1; // 1 is better because of 1/0 and such



        rcc->last_qscale_for[i] = FF_QP2LAMBDA * 5;

    }

    rcc->buffer_index = s->avctx->rc_initial_buffer_occupancy;

    if (!rcc->buffer_index)

        rcc->buffer_index = s->avctx->rc_buffer_size * 3 / 4;



    if (s->flags & CODEC_FLAG_PASS2) {

        int i;

        char *p;



        /* find number of pics */

        p = s->avctx->stats_in;

        for (i = -1; p; i++)

            p = strchr(p + 1, ';');

        i += s->max_b_frames;

        if (i <= 0 || i >= INT_MAX / sizeof(RateControlEntry))

            return -1;

        rcc->entry       = av_mallocz(i * sizeof(RateControlEntry));



        rcc->num_entries = i;



        /* init all to skipped p frames

         * (with b frames we might have a not encoded frame at the end FIXME) */

        for (i = 0; i < rcc->num_entries; i++) {

            RateControlEntry *rce = &rcc->entry[i];



            rce->pict_type  = rce->new_pict_type = AV_PICTURE_TYPE_P;

            rce->qscale     = rce->new_qscale    = FF_QP2LAMBDA * 2;

            rce->misc_bits  = s->mb_num + 10;

            rce->mb_var_sum = s->mb_num * 100;

        }



        /* read stats */

        p = s->avctx->stats_in;

        for (i = 0; i < rcc->num_entries - s->max_b_frames; i++) {

            RateControlEntry *rce;

            int picture_number;

            int e;

            char *next;



            next = strchr(p, ';');

            if (next) {

                (*next) = 0; // sscanf in unbelievably slow on looong strings // FIXME copy / do not write

                next++;

            }

            e = sscanf(p, " in:%d ", &picture_number);



            assert(picture_number >= 0);

            assert(picture_number < rcc->num_entries);

            rce = &rcc->entry[picture_number];



            e += sscanf(p, " in:%*d out:%*d type:%d q:%f itex:%d ptex:%d mv:%d misc:%d fcode:%d bcode:%d mc-var:%"SCNd64" var:%"SCNd64" icount:%d skipcount:%d hbits:%d",

                        &rce->pict_type, &rce->qscale, &rce->i_tex_bits, &rce->p_tex_bits,

                        &rce->mv_bits, &rce->misc_bits,

                        &rce->f_code, &rce->b_code,

                        &rce->mc_mb_var_sum, &rce->mb_var_sum,

                        &rce->i_count, &rce->skip_count, &rce->header_bits);

            if (e != 14) {

                av_log(s->avctx, AV_LOG_ERROR,

                       "statistics are damaged at line %d, parser out=%d\n",

                       i, e);

                return -1;

            }



            p = next;

        }



        if (init_pass2(s) < 0)

            return -1;



        // FIXME maybe move to end

        if ((s->flags & CODEC_FLAG_PASS2) && s->avctx->rc_strategy == FF_RC_STRATEGY_XVID) {

#if CONFIG_LIBXVID

            return ff_xvid_rate_control_init(s);

#else

            av_log(s->avctx, AV_LOG_ERROR,

                   "Xvid ratecontrol requires libavcodec compiled with Xvid support.\n");

            return -1;

#endif

        }

    }



    if (!(s->flags & CODEC_FLAG_PASS2)) {

        rcc->short_term_qsum   = 0.001;

        rcc->short_term_qcount = 0.001;



        rcc->pass1_rc_eq_output_sum = 0.001;

        rcc->pass1_wanted_bits      = 0.001;



        if (s->avctx->qblur > 1.0) {

            av_log(s->avctx, AV_LOG_ERROR, "qblur too large\n");

            return -1;

        }

        /* init stuff with the user specified complexity */

        if (s->rc_initial_cplx) {

            for (i = 0; i < 60 * 30; i++) {

                double bits = s->rc_initial_cplx * (i / 10000.0 + 1.0) * s->mb_num;

                RateControlEntry rce;



                if (i % ((s->gop_size + 3) / 4) == 0)

                    rce.pict_type = AV_PICTURE_TYPE_I;

                else if (i % (s->max_b_frames + 1))

                    rce.pict_type = AV_PICTURE_TYPE_B;

                else

                    rce.pict_type = AV_PICTURE_TYPE_P;



                rce.new_pict_type = rce.pict_type;

                rce.mc_mb_var_sum = bits * s->mb_num / 100000;

                rce.mb_var_sum    = s->mb_num;



                rce.qscale    = FF_QP2LAMBDA * 2;

                rce.f_code    = 2;

                rce.b_code    = 1;

                rce.misc_bits = 1;



                if (s->pict_type == AV_PICTURE_TYPE_I) {

                    rce.i_count    = s->mb_num;

                    rce.i_tex_bits = bits;

                    rce.p_tex_bits = 0;

                    rce.mv_bits    = 0;

                } else {

                    rce.i_count    = 0; // FIXME we do know this approx

                    rce.i_tex_bits = 0;

                    rce.p_tex_bits = bits * 0.9;

                    rce.mv_bits    = bits * 0.1;

                }

                rcc->i_cplx_sum[rce.pict_type]  += rce.i_tex_bits * rce.qscale;

                rcc->p_cplx_sum[rce.pict_type]  += rce.p_tex_bits * rce.qscale;

                rcc->mv_bits_sum[rce.pict_type] += rce.mv_bits;

                rcc->frame_count[rce.pict_type]++;



                get_qscale(s, &rce, rcc->pass1_wanted_bits / rcc->pass1_rc_eq_output_sum, i);



                // FIXME misbehaves a little for variable fps

                rcc->pass1_wanted_bits += s->bit_rate / get_fps(s->avctx);

            }

        }

    }



    return 0;

}

int main (int argc, char **argv)

{

    int ret = 0, got_frame;



    if (argc != 4) {

        fprintf(stderr, "usage: %s input_file video_output_file audio_output_file\n"

                "API example program to show how to read frames from an input file.\n"

                "This program reads frames from a file, decodes them, and writes decoded\n"

                "video frames to a rawvideo file named video_output_file, and decoded\n"

                "audio frames to a rawaudio file named audio_output_file.\n"

                "\n", argv[0]);

        exit(1);

    }

    src_filename = argv[1];

    video_dst_filename = argv[2];

    audio_dst_filename = argv[3];



    /* register all formats and codecs */

    av_register_all();



    /* open input file, and allocate format context */

    if (avformat_open_input(&fmt_ctx, src_filename, NULL, NULL) < 0) {

        fprintf(stderr, "Could not open source file %s\n", src_filename);

        exit(1);

    }



    /* retrieve stream information */

    if (avformat_find_stream_info(fmt_ctx, NULL) < 0) {

        fprintf(stderr, "Could not find stream information\n");

        exit(1);

    }



    if (open_codec_context(&video_stream_idx, fmt_ctx, AVMEDIA_TYPE_VIDEO) >= 0) {

        video_stream = fmt_ctx->streams[video_stream_idx];

        video_dec_ctx = video_stream->codec;



        video_dst_file = fopen(video_dst_filename, "wb");

        if (!video_dst_file) {

            fprintf(stderr, "Could not open destination file %s\n", video_dst_filename);

            ret = 1;

            goto end;

        }



        /* allocate image where the decoded image will be put */

        ret = av_image_alloc(video_dst_data, video_dst_linesize,

                             video_dec_ctx->width, video_dec_ctx->height,

                             video_dec_ctx->pix_fmt, 1);

        if (ret < 0) {

            fprintf(stderr, "Could not allocate raw video buffer\n");

            goto end;

        }

        video_dst_bufsize = ret;

    }



    if (open_codec_context(&audio_stream_idx, fmt_ctx, AVMEDIA_TYPE_AUDIO) >= 0) {

        int nb_planes;



        audio_stream = fmt_ctx->streams[audio_stream_idx];

        audio_dec_ctx = audio_stream->codec;

        audio_dst_file = fopen(audio_dst_filename, "wb");

        if (!audio_dst_file) {

            fprintf(stderr, "Could not open destination file %s\n", video_dst_filename);

            ret = 1;

            goto end;

        }



        nb_planes = av_sample_fmt_is_planar(audio_dec_ctx->sample_fmt) ?

            audio_dec_ctx->channels : 1;

        audio_dst_data = av_mallocz(sizeof(uint8_t *) * nb_planes);

        if (!audio_dst_data) {

            fprintf(stderr, "Could not allocate audio data buffers\n");

            ret = AVERROR(ENOMEM);

            goto end;

        }

    }



    /* dump input information to stderr */

    av_dump_format(fmt_ctx, 0, src_filename, 0);



    if (!audio_stream && !video_stream) {

        fprintf(stderr, "Could not find audio or video stream in the input, aborting\n");

        ret = 1;

        goto end;

    }



    frame = avcodec_alloc_frame();

    if (!frame) {

        fprintf(stderr, "Could not allocate frame\n");

        ret = AVERROR(ENOMEM);

        goto end;

    }



    /* initialize packet, set data to NULL, let the demuxer fill it */

    av_init_packet(&pkt);

    pkt.data = NULL;

    pkt.size = 0;



    if (video_stream)

        printf("Demuxing video from file '%s' into '%s'\n", src_filename, video_dst_filename);

    if (audio_stream)

        printf("Demuxing audio from file '%s' into '%s'\n", src_filename, audio_dst_filename);



    /* read frames from the file */

    while (av_read_frame(fmt_ctx, &pkt) >= 0)

        decode_packet(&got_frame, 0);



    /* flush cached frames */

    pkt.data = NULL;

    pkt.size = 0;

    do {

        decode_packet(&got_frame, 1);

    } while (got_frame);



    printf("Demuxing succeeded.\n");



    if (video_stream) {

        printf("Play the output video file with the command:\n"

               "ffplay -f rawvideo -pix_fmt %s -video_size %dx%d %s\n",

               av_get_pix_fmt_name(video_dec_ctx->pix_fmt), video_dec_ctx->width, video_dec_ctx->height,

               video_dst_filename);

    }



    if (audio_stream) {

        const char *fmt;



        if ((ret = get_format_from_sample_fmt(&fmt, audio_dec_ctx->sample_fmt)) < 0)

            goto end;

        printf("Play the output audio file with the command:\n"

               "ffplay -f %s -ac %d -ar %d %s\n",

               fmt, audio_dec_ctx->channels, audio_dec_ctx->sample_rate,

               audio_dst_filename);

    }



end:

    if (video_dec_ctx)

        avcodec_close(video_dec_ctx);

    if (audio_dec_ctx)

        avcodec_close(audio_dec_ctx);

    avformat_close_input(&fmt_ctx);

    if (video_dst_file)

        fclose(video_dst_file);

    if (audio_dst_file)

        fclose(audio_dst_file);

    av_free(frame);

    av_free(video_dst_data[0]);

    av_free(audio_dst_data);



    return ret < 0;

}

