static int h264_export_frame_props(H264Context *h)

{

    const SPS *sps = h->ps.sps;

    H264Picture *cur = h->cur_pic_ptr;



    cur->f->interlaced_frame = 0;

    cur->f->repeat_pict      = 0;



    /* Signal interlacing information externally. */

    /* Prioritize picture timing SEI information over used

     * decoding process if it exists. */



    if (sps->pic_struct_present_flag) {

        H264SEIPictureTiming *pt = &h->sei.picture_timing;

        switch (pt->pic_struct) {

        case SEI_PIC_STRUCT_FRAME:

            break;

        case SEI_PIC_STRUCT_TOP_FIELD:

        case SEI_PIC_STRUCT_BOTTOM_FIELD:

            cur->f->interlaced_frame = 1;

            break;

        case SEI_PIC_STRUCT_TOP_BOTTOM:

        case SEI_PIC_STRUCT_BOTTOM_TOP:

            if (FIELD_OR_MBAFF_PICTURE(h))

                cur->f->interlaced_frame = 1;

            else

                // try to flag soft telecine progressive

                cur->f->interlaced_frame = h->prev_interlaced_frame;

            break;

        case SEI_PIC_STRUCT_TOP_BOTTOM_TOP:

        case SEI_PIC_STRUCT_BOTTOM_TOP_BOTTOM:

            /* Signal the possibility of telecined film externally

             * (pic_struct 5,6). From these hints, let the applications

             * decide if they apply deinterlacing. */

            cur->f->repeat_pict = 1;

            break;

        case SEI_PIC_STRUCT_FRAME_DOUBLING:

            cur->f->repeat_pict = 2;

            break;

        case SEI_PIC_STRUCT_FRAME_TRIPLING:

            cur->f->repeat_pict = 4;

            break;

        }



        if ((pt->ct_type & 3) &&

            pt->pic_struct <= SEI_PIC_STRUCT_BOTTOM_TOP)

            cur->f->interlaced_frame = (pt->ct_type & (1 << 1)) != 0;

    } else {

        /* Derive interlacing flag from used decoding process. */

        cur->f->interlaced_frame = FIELD_OR_MBAFF_PICTURE(h);

    }

    h->prev_interlaced_frame = cur->f->interlaced_frame;



    if (cur->field_poc[0] != cur->field_poc[1]) {

        /* Derive top_field_first from field pocs. */

        cur->f->top_field_first = cur->field_poc[0] < cur->field_poc[1];

    } else {

        if (cur->f->interlaced_frame || sps->pic_struct_present_flag) {

            /* Use picture timing SEI information. Even if it is a

             * information of a past frame, better than nothing. */

            if (h->sei.picture_timing.pic_struct == SEI_PIC_STRUCT_TOP_BOTTOM ||

                h->sei.picture_timing.pic_struct == SEI_PIC_STRUCT_TOP_BOTTOM_TOP)

                cur->f->top_field_first = 1;

            else

                cur->f->top_field_first = 0;

        } else {

            /* Most likely progressive */

            cur->f->top_field_first = 0;

        }

    }



    if (h->sei.frame_packing.present &&

        h->sei.frame_packing.arrangement_type >= 0 &&

        h->sei.frame_packing.arrangement_type <= 6 &&

        h->sei.frame_packing.content_interpretation_type > 0 &&

        h->sei.frame_packing.content_interpretation_type < 3) {

        H264SEIFramePacking *fp = &h->sei.frame_packing;

        AVStereo3D *stereo = av_stereo3d_create_side_data(cur->f);

        if (!stereo)

            return AVERROR(ENOMEM);



        switch (fp->arrangement_type) {

        case 0:

            stereo->type = AV_STEREO3D_CHECKERBOARD;

            break;

        case 1:

            stereo->type = AV_STEREO3D_COLUMNS;

            break;

        case 2:

            stereo->type = AV_STEREO3D_LINES;

            break;

        case 3:

            if (fp->quincunx_subsampling)

                stereo->type = AV_STEREO3D_SIDEBYSIDE_QUINCUNX;

            else

                stereo->type = AV_STEREO3D_SIDEBYSIDE;

            break;

        case 4:

            stereo->type = AV_STEREO3D_TOPBOTTOM;

            break;

        case 5:

            stereo->type = AV_STEREO3D_FRAMESEQUENCE;

            break;

        case 6:

            stereo->type = AV_STEREO3D_2D;

            break;

        }



        if (fp->content_interpretation_type == 2)

            stereo->flags = AV_STEREO3D_FLAG_INVERT;

    }



    if (h->sei.display_orientation.present &&

        (h->sei.display_orientation.anticlockwise_rotation ||

         h->sei.display_orientation.hflip ||

         h->sei.display_orientation.vflip)) {

        H264SEIDisplayOrientation *o = &h->sei.display_orientation;

        double angle = o->anticlockwise_rotation * 360 / (double) (1 << 16);

        AVFrameSideData *rotation = av_frame_new_side_data(cur->f,

                                                           AV_FRAME_DATA_DISPLAYMATRIX,

                                                           sizeof(int32_t) * 9);

        if (!rotation)

            return AVERROR(ENOMEM);



        av_display_rotation_set((int32_t *)rotation->data, angle);

        av_display_matrix_flip((int32_t *)rotation->data,

                               o->hflip, o->vflip);

    }



    if (h->sei.afd.present) {

        AVFrameSideData *sd = av_frame_new_side_data(cur->f, AV_FRAME_DATA_AFD,

                                                     sizeof(uint8_t));

        if (!sd)

            return AVERROR(ENOMEM);



        *sd->data = h->sei.afd.active_format_description;

        h->sei.afd.present = 0;

    }



    if (h->sei.a53_caption.a53_caption) {

        H264SEIA53Caption *a53 = &h->sei.a53_caption;

        AVFrameSideData *sd = av_frame_new_side_data(cur->f,

                                                     AV_FRAME_DATA_A53_CC,

                                                     a53->a53_caption_size);

        if (!sd)

            return AVERROR(ENOMEM);



        memcpy(sd->data, a53->a53_caption, a53->a53_caption_size);

        av_freep(&a53->a53_caption);

        a53->a53_caption_size = 0;

    }



    return 0;

}

static int caca_write_header(AVFormatContext *s)

{

    CACAContext *c = s->priv_data;

    AVStream *st = s->streams[0];

    AVCodecContext *encctx = st->codec;

    int ret, bpp;



    c->ctx = s;

    if (c->list_drivers) {

        list_drivers(c);

        return AVERROR_EXIT;

    }

    if (c->list_dither) {

        if (!strcmp(c->list_dither, "colors")) {

            list_dither_color(c);

        } else if (!strcmp(c->list_dither, "charsets")) {

            list_dither_charset(c);

        } else if (!strcmp(c->list_dither, "algorithms")) {

            list_dither_algorithm(c);

        } else if (!strcmp(c->list_dither, "antialiases")) {

            list_dither_antialias(c);

        } else {

            av_log(s, AV_LOG_ERROR,

                   "Invalid argument '%s', for 'list_dither' option\n"

                   "Argument must be one of 'algorithms, 'antialiases', 'charsets', 'colors'\n",

                   c->list_dither);

            return AVERROR(EINVAL);

        }

        return AVERROR_EXIT;

    }



    if (   s->nb_streams > 1

        || encctx->codec_type != AVMEDIA_TYPE_VIDEO

        || encctx->codec_id   != CODEC_ID_RAWVIDEO) {

        av_log(s, AV_LOG_ERROR, "Only supports one rawvideo stream\n");

        return AVERROR(EINVAL);

    }



    if (encctx->pix_fmt != PIX_FMT_RGB24) {

        av_log(s, AV_LOG_ERROR,

               "Unsupported pixel format '%s', choose rgb24\n",

               av_get_pix_fmt_name(encctx->pix_fmt));

        return AVERROR(EINVAL);

    }



    c->canvas = caca_create_canvas(c->window_width, c->window_height);

    if (!c->canvas) {

        av_log(s, AV_LOG_ERROR, "Failed to create canvas\n");

        return AVERROR(errno);

    }



    c->display = caca_create_display_with_driver(c->canvas, c->driver);

    if (!c->display) {

        av_log(s, AV_LOG_ERROR, "Failed to create display\n");

        list_drivers(c);

        caca_free_canvas(c->canvas);

        return AVERROR(errno);

    }



    if (!c->window_width || !c->window_height) {

        c->window_width  = caca_get_canvas_width(c->canvas);

        c->window_height = caca_get_canvas_height(c->canvas);

    }



    bpp = av_get_bits_per_pixel(&av_pix_fmt_descriptors[encctx->pix_fmt]);

    c->dither = caca_create_dither(bpp, encctx->width, encctx->height,

                                   bpp / 8 * encctx->width,

                                   0x0000ff, 0x00ff00, 0xff0000, 0);

    if (!c->dither) {

        av_log(s, AV_LOG_ERROR, "Failed to create dither\n");

        ret =  AVERROR(errno);

        goto fail;

    }



#define CHECK_DITHER_OPT(opt)                                           \

    if (caca_set_dither_##opt(c->dither, c->opt) < 0)  {                \

        ret = AVERROR(errno);                                           \

        av_log(s, AV_LOG_ERROR, "Failed to set value '%s' for option '%s'\n", \

               c->opt, #opt);                                           \

        goto fail;                                                      \

    }

    CHECK_DITHER_OPT(algorithm);

    CHECK_DITHER_OPT(antialias);

    CHECK_DITHER_OPT(charset);

    CHECK_DITHER_OPT(color);



    if (!c->window_title)

        c->window_title = av_strdup(s->filename);

    caca_set_display_title(c->display, c->window_title);

    caca_set_display_time(c->display, av_rescale_q(1, st->codec->time_base, AV_TIME_BASE_Q));



    return 0;



fail:

    caca_write_trailer(s);

    return ret;

}

static int mxf_read_index_entry_array(AVIOContext *pb, MXFIndexTableSegment *segment)

{

    int i, length;



    segment->nb_index_entries = avio_rb32(pb);



    length = avio_rb32(pb);





    if (!(segment->temporal_offset_entries=av_calloc(segment->nb_index_entries, sizeof(*segment->temporal_offset_entries))) ||

        !(segment->flag_entries          = av_calloc(segment->nb_index_entries, sizeof(*segment->flag_entries))) ||

        !(segment->stream_offset_entries = av_calloc(segment->nb_index_entries, sizeof(*segment->stream_offset_entries)))) {

        av_freep(&segment->temporal_offset_entries);

        av_freep(&segment->flag_entries);

        return AVERROR(ENOMEM);

    }



    for (i = 0; i < segment->nb_index_entries; i++) {

        if(avio_feof(pb))


        segment->temporal_offset_entries[i] = avio_r8(pb);

        avio_r8(pb);                                        /* KeyFrameOffset */

        segment->flag_entries[i] = avio_r8(pb);

        segment->stream_offset_entries[i] = avio_rb64(pb);

        avio_skip(pb, length - 11);

    }

    return 0;

}

static int vp7_decode_frame_header(VP8Context *s, const uint8_t *buf, int buf_size)

{

    VP56RangeCoder *c = &s->c;

    int part1_size, hscale, vscale, i, j, ret;

    int width  = s->avctx->width;

    int height = s->avctx->height;



    s->profile = (buf[0] >> 1) & 7;

    if (s->profile > 1) {

        avpriv_request_sample(s->avctx, "Unknown profile %d", s->profile);

        return AVERROR_INVALIDDATA;

    }



    s->keyframe  = !(buf[0] & 1);

    s->invisible = 0;

    part1_size   = AV_RL24(buf) >> 4;



    buf      += 4 - s->profile;

    buf_size -= 4 - s->profile;



    memcpy(s->put_pixels_tab, s->vp8dsp.put_vp8_epel_pixels_tab, sizeof(s->put_pixels_tab));



    ff_vp56_init_range_decoder(c, buf, part1_size);

    buf      += part1_size;

    buf_size -= part1_size;



    /* A. Dimension information (keyframes only) */

    if (s->keyframe) {

        width  = vp8_rac_get_uint(c, 12);

        height = vp8_rac_get_uint(c, 12);

        hscale = vp8_rac_get_uint(c, 2);

        vscale = vp8_rac_get_uint(c, 2);

        if (hscale || vscale)

            avpriv_request_sample(s->avctx, "Upscaling");



        s->update_golden = s->update_altref = VP56_FRAME_CURRENT;

        vp78_reset_probability_tables(s);

        memcpy(s->prob->pred16x16, vp8_pred16x16_prob_inter,

               sizeof(s->prob->pred16x16));

        memcpy(s->prob->pred8x8c, vp8_pred8x8c_prob_inter,

               sizeof(s->prob->pred8x8c));

        for (i = 0; i < 2; i++)

            memcpy(s->prob->mvc[i], vp7_mv_default_prob[i],

                   sizeof(vp7_mv_default_prob[i]));

        memset(&s->segmentation, 0, sizeof(s->segmentation));

        memset(&s->lf_delta, 0, sizeof(s->lf_delta));

        memcpy(s->prob[0].scan, zigzag_scan, sizeof(s->prob[0].scan));

    }



    if (s->keyframe || s->profile > 0)

        memset(s->inter_dc_pred, 0 , sizeof(s->inter_dc_pred));



    /* B. Decoding information for all four macroblock-level features */

    for (i = 0; i < 4; i++) {

        s->feature_enabled[i] = vp8_rac_get(c);

        if (s->feature_enabled[i]) {

             s->feature_present_prob[i] = vp8_rac_get_uint(c, 8);



             for (j = 0; j < 3; j++)

                 s->feature_index_prob[i][j] =

                     vp8_rac_get(c) ? vp8_rac_get_uint(c, 8) : 255;



             if (vp7_feature_value_size[i])

                 for (j = 0; j < 4; j++)

                     s->feature_value[i][j] =

                         vp8_rac_get(c) ? vp8_rac_get_uint(c, vp7_feature_value_size[s->profile][i]) : 0;

        }

    }



    s->segmentation.enabled    = 0;

    s->segmentation.update_map = 0;

    s->lf_delta.enabled        = 0;



    s->num_coeff_partitions = 1;

    ff_vp56_init_range_decoder(&s->coeff_partition[0], buf, buf_size);



    if (!s->macroblocks_base || /* first frame */

        width != s->avctx->width || height != s->avctx->height ||

        (width + 15) / 16 != s->mb_width || (height + 15) / 16 != s->mb_height) {

        if ((ret = vp7_update_dimensions(s, width, height)) < 0)

            return ret;

    }



    /* C. Dequantization indices */

    vp7_get_quants(s);



    /* D. Golden frame update flag (a Flag) for interframes only */

    if (!s->keyframe) {

        s->update_golden = vp8_rac_get(c) ? VP56_FRAME_CURRENT : VP56_FRAME_NONE;

        s->sign_bias[VP56_FRAME_GOLDEN] = 0;

    }



    s->update_last          = 1;

    s->update_probabilities = 1;

    s->fade_present         = 1;



    if (s->profile > 0) {

        s->update_probabilities = vp8_rac_get(c);

        if (!s->update_probabilities)

            s->prob[1] = s->prob[0];



        if (!s->keyframe)

            s->fade_present = vp8_rac_get(c);

    }



    /* E. Fading information for previous frame */

    if (s->fade_present && vp8_rac_get(c)) {

        if ((ret = vp7_fade_frame(s ,c)) < 0)

            return ret;

    }



    /* F. Loop filter type */

    if (!s->profile)

        s->filter.simple = vp8_rac_get(c);



    /* G. DCT coefficient ordering specification */

    if (vp8_rac_get(c))

        for (i = 1; i < 16; i++)

            s->prob[0].scan[i] = zigzag_scan[vp8_rac_get_uint(c, 4)];



    /* H. Loop filter levels  */

    if (s->profile > 0)

        s->filter.simple = vp8_rac_get(c);

    s->filter.level     = vp8_rac_get_uint(c, 6);

    s->filter.sharpness = vp8_rac_get_uint(c, 3);



    /* I. DCT coefficient probability update; 13.3 Token Probability Updates */

    vp78_update_probability_tables(s);



    s->mbskip_enabled = 0;



    /* J. The remaining frame header data occurs ONLY FOR INTERFRAMES */

    if (!s->keyframe) {

        s->prob->intra  = vp8_rac_get_uint(c, 8);

        s->prob->last   = vp8_rac_get_uint(c, 8);

        vp78_update_pred16x16_pred8x8_mvc_probabilities(s, VP7_MVC_SIZE);

    }



    return 0;

}

static inline void mc_dir_part(H264Context *h, Picture *pic, int n, int square, int chroma_height, int delta, int list,

                           uint8_t *dest_y, uint8_t *dest_cb, uint8_t *dest_cr,

                           int src_x_offset, int src_y_offset,

                           qpel_mc_func *qpix_op, h264_chroma_mc_func chroma_op){

    MpegEncContext * const s = &h->s;

    const int mx= h->mv_cache[list][ scan8[n] ][0] + src_x_offset*8;

    const int my= h->mv_cache[list][ scan8[n] ][1] + src_y_offset*8;

    const int luma_xy= (mx&3) + ((my&3)<<2);

    uint8_t * src_y = pic->data[0] + (mx>>2) + (my>>2)*s->linesize;

    uint8_t * src_cb= pic->data[1] + (mx>>3) + (my>>3)*s->uvlinesize;

    uint8_t * src_cr= pic->data[2] + (mx>>3) + (my>>3)*s->uvlinesize;

    int extra_width= (s->flags&CODEC_FLAG_EMU_EDGE) ? 0 : 16; //FIXME increase edge?, IMHO not worth it

    int extra_height= extra_width;

    int emu=0;

    const int full_mx= mx>>2;

    const int full_my= my>>2;

    const int pic_width  = 16*s->mb_width;

    const int pic_height = 16*s->mb_height;



    assert(pic->data[0]);



    if(mx&7) extra_width -= 3;

    if(my&7) extra_height -= 3;



    if(   full_mx < 0-extra_width

       || full_my < 0-extra_height

       || full_mx + 16/*FIXME*/ > pic_width + extra_width

       || full_my + 16/*FIXME*/ > pic_height + extra_height){

        ff_emulated_edge_mc(s->edge_emu_buffer, src_y - 2 - 2*s->linesize, s->linesize, 16+5, 16+5/*FIXME*/, full_mx-2, full_my-2, pic_width, pic_height);

            src_y= s->edge_emu_buffer + 2 + 2*s->linesize;

        emu=1;

    }



    qpix_op[luma_xy](dest_y, src_y, s->linesize); //FIXME try variable height perhaps?

    if(!square){

        qpix_op[luma_xy](dest_y + delta, src_y + delta, s->linesize);

    }



    if(s->flags&CODEC_FLAG_GRAY) return;



    if(emu){

        ff_emulated_edge_mc(s->edge_emu_buffer, src_cb, s->uvlinesize, 9, 9/*FIXME*/, (mx>>3), (my>>3), pic_width>>1, pic_height>>1);

            src_cb= s->edge_emu_buffer;

    }

    chroma_op(dest_cb, src_cb, s->uvlinesize, chroma_height, mx&7, my&7);



    if(emu){

        ff_emulated_edge_mc(s->edge_emu_buffer, src_cr, s->uvlinesize, 9, 9/*FIXME*/, (mx>>3), (my>>3), pic_width>>1, pic_height>>1);

            src_cr= s->edge_emu_buffer;

    }

    chroma_op(dest_cr, src_cr, s->uvlinesize, chroma_height, mx&7, my&7);

}

static int encode_frame(AVCodecContext *avctx, uint8_t *buf,

                        int buf_size, void *data)

{

    AVFrame *pic = data;

    int i, j;

    int aligned_width = FFALIGN(avctx->width, 64);

    uint8_t *src_line;

    uint8_t *dst = buf;



    if (buf_size < 4 * aligned_width * avctx->height) {

        av_log(avctx, AV_LOG_ERROR, "output buffer too small\n");

        return AVERROR(ENOMEM);

    }



    avctx->coded_frame->reference = 0;

    avctx->coded_frame->key_frame = 1;

    avctx->coded_frame->pict_type = AV_PICTURE_TYPE_I;

    src_line = pic->data[0];



    for (i = 0; i < avctx->height; i++) {

        uint16_t *src = (uint16_t *)src_line;

        for (j = 0; j < avctx->width; j++) {

            uint32_t pixel;

            uint16_t r = *src++ >> 6;

            uint16_t g = *src++ >> 6;

            uint16_t b = *src++ >> 4;

            if (avctx->codec_id == CODEC_ID_R210)

                pixel = (r << 20) | (g << 10) | b >> 2;

            else

                pixel = (r << 22) | (g << 12) | b;

            if (avctx->codec_id == CODEC_ID_AVRP)

                bytestream_put_le32(&dst, pixel);

            else

                bytestream_put_be32(&dst, pixel);

        }

        dst += (aligned_width - avctx->width) * 4;

        src_line += pic->linesize[0];

    }



    return 4 * aligned_width * avctx->height;

}

static int nut_read_packet(AVFormatContext *s, AVPacket *pkt)

{

    NUTContext *nut = s->priv_data;

    StreamContext *stream;

    ByteIOContext *bc = &s->pb;

    int size, frame_code, flags, size_mul, size_lsb, stream_id;

    int key_frame = 0;

    int frame_type= 0;

    int64_t pts = 0;

    const int64_t frame_start= url_ftell(bc);



    if (url_feof(bc))

	return -1;



    frame_code = get_byte(bc);

    if(frame_code == 'N'){

        uint64_t tmp= frame_code;

	tmp<<=8 ; tmp |= get_byte(bc);

	tmp<<=16; tmp |= get_be16(bc);

	tmp<<=32; tmp |= get_be32(bc);

	if (tmp == KEYFRAME_STARTCODE)

	{

	    frame_code = get_byte(bc);

            frame_type = 2;

	}

	else

	    av_log(s, AV_LOG_ERROR, "error in zero bit / startcode %LX\n", tmp);

    }

    flags= nut->frame_code[frame_code].flags;

    size_mul= nut->frame_code[frame_code].size_mul;

    size_lsb= nut->frame_code[frame_code].size_lsb;

    stream_id= nut->frame_code[frame_code].stream_id_plus1 - 1;



    if(flags & FLAG_FRAME_TYPE){

        reset(s);

        if(frame_type==2){

            get_packetheader(nut, bc, 8+1, 0);

        }else{

            get_packetheader(nut, bc, 1, 0);

            frame_type= 1;

        }

    }



    if(stream_id==-1)

        stream_id= get_v(bc);

    if(stream_id >= s->nb_streams){

        av_log(s, AV_LOG_ERROR, "illegal stream_id\n");

        return -1;

    }

    stream= &nut->stream[stream_id];



    if(flags & FLAG_PRED_KEY_FRAME){

        if(flags & FLAG_KEY_FRAME)

            key_frame= !stream->last_key_frame;

        else

            key_frame= stream->last_key_frame;

    }else{

        key_frame= !!(flags & FLAG_KEY_FRAME);

    }



    if(flags & FLAG_PTS){

        if(flags & FLAG_FULL_PTS){

            pts= get_v(bc);

        }else{

            int64_t mask = (1<<stream->msb_timestamp_shift)-1;

            int64_t delta= stream->last_pts - mask/2;

            pts= ((get_v(bc) - delta)&mask) + delta;

        }

    }else{

        pts= stream->last_pts + stream->lru_pts_delta[(flags&12)>>2];

    }



    if(size_mul <= size_lsb){

        size= stream->lru_size[size_lsb - size_mul];

    }else{

        if(flags & FLAG_DATA_SIZE)

            size= size_mul*get_v(bc) + size_lsb;

        else

            size= size_lsb;

    }



//av_log(s, AV_LOG_DEBUG, "fs:%lld fc:%d ft:%d kf:%d pts:%lld\n", frame_start, frame_code, frame_type, key_frame, pts);



    av_new_packet(pkt, size);

    get_buffer(bc, pkt->data, size);

    pkt->stream_index = stream_id;

    if (key_frame)

	pkt->flags |= PKT_FLAG_KEY;

    pkt->pts = pts * AV_TIME_BASE * stream->rate_den / stream->rate_num;



    update(nut, stream_id, frame_start, frame_type, frame_code, key_frame, size, pts);



    return 0;

}

int avio_check(const char *url, int flags)

{

    URLContext *h;

    int ret = ffurl_alloc(&h, url, flags, NULL);

    if (ret)

        return ret;



    if (h->prot->url_check) {

        ret = h->prot->url_check(h, flags);

    } else {

        ret = ffurl_connect(h, NULL);

        if (ret >= 0)

            ret = flags;

    }



    ffurl_close(h);

    return ret;

}

static int mov_read_trak(MOVContext *c, ByteIOContext *pb, MOVAtom atom)

{

    AVStream *st;

    MOVStreamContext *sc;

    int ret;



    st = av_new_stream(c->fc, c->fc->nb_streams);

    if (!st) return AVERROR(ENOMEM);

    sc = av_mallocz(sizeof(MOVStreamContext));

    if (!sc) return AVERROR(ENOMEM);



    st->priv_data = sc;

    st->codec->codec_type = CODEC_TYPE_DATA;

    sc->ffindex = st->index;



    if ((ret = mov_read_default(c, pb, atom)) < 0)

        return ret;



    /* sanity checks */

    if(sc->chunk_count && (!sc->stts_count || !sc->stsc_count ||

                           (!sc->sample_size && !sc->sample_count))){

        av_log(c->fc, AV_LOG_ERROR, "stream %d, missing mandatory atoms, broken header\n",

               st->index);

        sc->sample_count = 0; //ignore track

        return 0;

    }

    if(!sc->time_rate)

        sc->time_rate=1;

    if(!sc->time_scale)

        sc->time_scale= c->time_scale;

    av_set_pts_info(st, 64, sc->time_rate, sc->time_scale);



    if (st->codec->codec_type == CODEC_TYPE_AUDIO &&

        !st->codec->frame_size && sc->stts_count == 1) {

        st->codec->frame_size = av_rescale(sc->stts_data[0].duration,

                                           st->codec->sample_rate, sc->time_scale);

        dprintf(c->fc, "frame size %d\n", st->codec->frame_size);

    }



    if(st->duration != AV_NOPTS_VALUE){

        assert(st->duration % sc->time_rate == 0);

        st->duration /= sc->time_rate;

    }



    mov_build_index(c, st);



    if (sc->dref_id-1 < sc->drefs_count && sc->drefs[sc->dref_id-1].path) {

        if (url_fopen(&sc->pb, sc->drefs[sc->dref_id-1].path, URL_RDONLY) < 0)

            av_log(c->fc, AV_LOG_ERROR, "stream %d, error opening file %s: %s\n",

                   st->index, sc->drefs[sc->dref_id-1].path, strerror(errno));

    } else

        sc->pb = c->fc->pb;



    switch (st->codec->codec_id) {

#if CONFIG_H261_DECODER

    case CODEC_ID_H261:

#endif

#if CONFIG_H263_DECODER

    case CODEC_ID_H263:

#endif

#if CONFIG_MPEG4_DECODER

    case CODEC_ID_MPEG4:

#endif

        st->codec->width= 0; /* let decoder init width/height */

        st->codec->height= 0;

        break;

    }



    /* Do not need those anymore. */

    av_freep(&sc->chunk_offsets);

    av_freep(&sc->stsc_data);

    av_freep(&sc->sample_sizes);

    av_freep(&sc->keyframes);

    av_freep(&sc->stts_data);



    return 0;

}

