        break;

    }

    case AV_CODEC_ID_ADPCM_EA_MAXIS_XA:

    {

        int coeff[2][2], shift[2];



        for(channel = 0; channel < avctx->channels; channel++) {

            int byte = bytestream2_get_byteu(&gb);

            for (i=0; i<2; i++)

                coeff[channel][i] = ea_adpcm_table[(byte >> 4) + 4*i];

