static inline void RENAME(rgb24tobgr15)(const uint8_t *src, uint8_t *dst, long src_size)

{

    const uint8_t *s = src;

    const uint8_t *end;

#if COMPILE_TEMPLATE_MMX

    const uint8_t *mm_end;

#endif

    uint16_t *d = (uint16_t *)dst;

    end = s + src_size;

#if COMPILE_TEMPLATE_MMX

    __asm__ volatile(PREFETCH"    %0"::"m"(*src):"memory");

    __asm__ volatile(

        "movq          %0, %%mm7    \n\t"

        "movq          %1, %%mm6    \n\t"

        ::"m"(red_15mask),"m"(green_15mask));

    mm_end = end - 11;

    while (s < mm_end) {

        __asm__ volatile(

            PREFETCH"    32%1           \n\t"

            "movd          %1, %%mm0    \n\t"

            "movd         3%1, %%mm3    \n\t"

            "punpckldq    6%1, %%mm0    \n\t"

            "punpckldq    9%1, %%mm3    \n\t"

            "movq       %%mm0, %%mm1    \n\t"

            "movq       %%mm0, %%mm2    \n\t"

            "movq       %%mm3, %%mm4    \n\t"

            "movq       %%mm3, %%mm5    \n\t"

            "psrlq         $3, %%mm0    \n\t"

            "psrlq         $3, %%mm3    \n\t"

            "pand          %2, %%mm0    \n\t"

            "pand          %2, %%mm3    \n\t"

            "psrlq         $6, %%mm1    \n\t"

            "psrlq         $6, %%mm4    \n\t"

            "pand       %%mm6, %%mm1    \n\t"

            "pand       %%mm6, %%mm4    \n\t"

            "psrlq         $9, %%mm2    \n\t"

            "psrlq         $9, %%mm5    \n\t"

            "pand       %%mm7, %%mm2    \n\t"

            "pand       %%mm7, %%mm5    \n\t"

            "por        %%mm1, %%mm0    \n\t"

            "por        %%mm4, %%mm3    \n\t"

            "por        %%mm2, %%mm0    \n\t"

            "por        %%mm5, %%mm3    \n\t"

            "psllq        $16, %%mm3    \n\t"

            "por        %%mm3, %%mm0    \n\t"

            MOVNTQ"     %%mm0, %0       \n\t"

            :"=m"(*d):"m"(*s),"m"(blue_15mask):"memory");

        d += 4;

        s += 12;

    }

    __asm__ volatile(SFENCE:::"memory");

    __asm__ volatile(EMMS:::"memory");

#endif

    while (s < end) {

        const int b = *s++;

        const int g = *s++;

        const int r = *s++;

        *d++ = (b>>3) | ((g&0xF8)<<2) | ((r&0xF8)<<7);

    }

}

static double compute_target_delay(double delay, VideoState *is)

{

    double sync_threshold, diff;



    /* update delay to follow master synchronisation source */

    if (get_master_sync_type(is) != AV_SYNC_VIDEO_MASTER) {

        /* if video is slave, we try to correct big delays by

           duplicating or deleting a frame */

        diff = get_video_clock(is) - get_master_clock(is);



        /* skip or repeat frame. We take into account the

           delay to compute the threshold. I still don't know

           if it is the best guess */

        sync_threshold = FFMAX(AV_SYNC_THRESHOLD, delay);

        if (fabs(diff) < AV_NOSYNC_THRESHOLD) {

            if (diff <= -sync_threshold)

                delay = 0;

            else if (diff >= sync_threshold)

                delay = 2 * delay;

        }

    }



    av_dlog(NULL, "video: delay=%0.3f A-V=%f\n",

            delay, -diff);



    return delay;

}

static OutputStream *new_output_stream(OptionsContext *o, AVFormatContext *oc, enum AVMediaType type)

{

    OutputStream *ost;

    AVStream *st = avformat_new_stream(oc, NULL);

    int idx      = oc->nb_streams - 1, ret = 0;

    int64_t max_frames = INT64_MAX;

    char *bsf = NULL, *next, *codec_tag = NULL;

    AVBitStreamFilterContext *bsfc, *bsfc_prev = NULL;

    double qscale = -1;

    char *buf = NULL, *arg = NULL, *preset = NULL;

    AVIOContext *s = NULL;



    if (!st) {

        av_log(NULL, AV_LOG_FATAL, "Could not alloc stream.\n");

        exit_program(1);

    }



    if (oc->nb_streams - 1 < o->nb_streamid_map)

        st->id = o->streamid_map[oc->nb_streams - 1];



    output_streams = grow_array(output_streams, sizeof(*output_streams), &nb_output_streams,

                                nb_output_streams + 1);

    ost = &output_streams[nb_output_streams - 1];

    ost->file_index = nb_output_files;

    ost->index = idx;

    ost->st    = st;

    st->codec->codec_type = type;

    ost->enc = choose_codec(o, oc, st, type);

    if (ost->enc) {

        ost->opts  = filter_codec_opts(codec_opts, ost->enc->id, oc, st);

    }



    avcodec_get_context_defaults3(st->codec, ost->enc);

    st->codec->codec_type = type; // XXX hack, avcodec_get_context_defaults2() sets type to unknown for stream copy



    MATCH_PER_STREAM_OPT(presets, str, preset, oc, st);

    if (preset && (!(ret = get_preset_file_2(preset, ost->enc->name, &s)))) {

        do  {

            buf = get_line(s);

            if (!buf[0] || buf[0] == '#') {

                av_free(buf);

                continue;

            }

            if (!(arg = strchr(buf, '='))) {

                av_log(NULL, AV_LOG_FATAL, "Invalid line found in the preset file.\n");

                exit_program(1);

            }

            *arg++ = 0;

            av_dict_set(&ost->opts, buf, arg, AV_DICT_DONT_OVERWRITE);

            av_free(buf);

        } while (!s->eof_reached);

        avio_close(s);

    }

    if (ret) {

        av_log(NULL, AV_LOG_FATAL,

               "Preset %s specified for stream %d:%d, but could not be opened.\n",

               preset, ost->file_index, ost->index);

        exit_program(1);

    }



    MATCH_PER_STREAM_OPT(max_frames, i64, max_frames, oc, st);

    ost->max_frames = max_frames;



    MATCH_PER_STREAM_OPT(bitstream_filters, str, bsf, oc, st);

    while (bsf) {

        if (next = strchr(bsf, ','))

            *next++ = 0;

        if (!(bsfc = av_bitstream_filter_init(bsf))) {

            av_log(NULL, AV_LOG_FATAL, "Unknown bitstream filter %s\n", bsf);

            exit_program(1);

        }

        if (bsfc_prev)

            bsfc_prev->next = bsfc;

        else

            ost->bitstream_filters = bsfc;



        bsfc_prev = bsfc;

        bsf       = next;

    }



    MATCH_PER_STREAM_OPT(codec_tags, str, codec_tag, oc, st);

    if (codec_tag) {

        uint32_t tag = strtol(codec_tag, &next, 0);

        if (*next)

            tag = AV_RL32(codec_tag);

        st->codec->codec_tag = tag;

    }



    MATCH_PER_STREAM_OPT(qscale, dbl, qscale, oc, st);

    if (qscale >= 0 || same_quant) {

        st->codec->flags |= CODEC_FLAG_QSCALE;

        st->codec->global_quality = FF_QP2LAMBDA * qscale;

    }



    if (oc->oformat->flags & AVFMT_GLOBALHEADER)

        st->codec->flags |= CODEC_FLAG_GLOBAL_HEADER;



    av_opt_get_int(sws_opts, "sws_flags", 0, &ost->sws_flags);

    return ost;

}

int av_picture_pad(AVPicture *dst, const AVPicture *src, int height, int width,

                   enum PixelFormat pix_fmt, int padtop, int padbottom, int padleft, int padright,

            int *color)

{

    uint8_t *optr;

    int y_shift;

    int x_shift;

    int yheight;

    int i, y;



    if (pix_fmt < 0 || pix_fmt >= PIX_FMT_NB ||

        !is_yuv_planar(&pix_fmt_info[pix_fmt])) return -1;



    for (i = 0; i < 3; i++) {

        x_shift = i ? av_pix_fmt_descriptors[pix_fmt].log2_chroma_w : 0;

        y_shift = i ? av_pix_fmt_descriptors[pix_fmt].log2_chroma_h : 0;



        if (padtop || padleft) {

            memset(dst->data[i], color[i],

                dst->linesize[i] * (padtop >> y_shift) + (padleft >> x_shift));

        }



        if (padleft || padright) {

            optr = dst->data[i] + dst->linesize[i] * (padtop >> y_shift) +

                (dst->linesize[i] - (padright >> x_shift));

            yheight = (height - 1 - (padtop + padbottom)) >> y_shift;

            for (y = 0; y < yheight; y++) {

                memset(optr, color[i], (padleft + padright) >> x_shift);

                optr += dst->linesize[i];

            }

        }



        if (src) { /* first line */

            uint8_t *iptr = src->data[i];

            optr = dst->data[i] + dst->linesize[i] * (padtop >> y_shift) +

                    (padleft >> x_shift);

            memcpy(optr, iptr, (width - padleft - padright) >> x_shift);

            iptr += src->linesize[i];

            optr = dst->data[i] + dst->linesize[i] * (padtop >> y_shift) +

                (dst->linesize[i] - (padright >> x_shift));

            yheight = (height - 1 - (padtop + padbottom)) >> y_shift;

            for (y = 0; y < yheight; y++) {

                memset(optr, color[i], (padleft + padright) >> x_shift);

                memcpy(optr + ((padleft + padright) >> x_shift), iptr,

                       (width - padleft - padright) >> x_shift);

                iptr += src->linesize[i];

                optr += dst->linesize[i];

            }

        }



        if (padbottom || padright) {

            optr = dst->data[i] + dst->linesize[i] *

                ((height - padbottom) >> y_shift) - (padright >> x_shift);

            memset(optr, color[i],dst->linesize[i] *

                (padbottom >> y_shift) + (padright >> x_shift));

        }

    }

    return 0;

}

static int prepare_input_packet(AVFormatContext *s, AVPacket *pkt)

{

    int ret;



    ret = check_packet(s, pkt);

    if (ret < 0)

        return ret;



#if !FF_API_COMPUTE_PKT_FIELDS2

    /* sanitize the timestamps */

    if (!(s->oformat->flags & AVFMT_NOTIMESTAMPS)) {

        AVStream *st = s->streams[pkt->stream_index];



        /* when there is no reordering (so dts is equal to pts), but

         * only one of them is set, set the other as well */

        if (!st->internal->reorder) {

            if (pkt->pts == AV_NOPTS_VALUE && pkt->dts != AV_NOPTS_VALUE)

                pkt->pts = pkt->dts;

            if (pkt->dts == AV_NOPTS_VALUE && pkt->pts != AV_NOPTS_VALUE)

                pkt->dts = pkt->pts;

        }



        /* check that the timestamps are set */

        if (pkt->pts == AV_NOPTS_VALUE || pkt->dts == AV_NOPTS_VALUE) {

            av_log(s, AV_LOG_ERROR,

                   "Timestamps are unset in a packet for stream %d\n", st->index);

            return AVERROR(EINVAL);

        }



        /* check that the dts are increasing (or at least non-decreasing,

         * if the format allows it */

        if (st->cur_dts != AV_NOPTS_VALUE &&

            ((!(s->oformat->flags & AVFMT_TS_NONSTRICT) && st->cur_dts >= pkt->dts) ||

             st->cur_dts > pkt->dts)) {

            av_log(s, AV_LOG_ERROR,

                   "Application provided invalid, non monotonically increasing "

                   "dts to muxer in stream %d: %" PRId64 " >= %" PRId64 "\n",

                   st->index, st->cur_dts, pkt->dts);

            return AVERROR(EINVAL);

        }



        if (pkt->pts < pkt->dts) {

            av_log(s, AV_LOG_ERROR, "pts %" PRId64 " < dts %" PRId64 " in stream %d\n",

                   pkt->pts, pkt->dts, st->index);

            return AVERROR(EINVAL);

        }

    }

#endif



    return 0;

}

static void rtsp_send_cmd(AVFormatContext *s, 

                          const char *cmd, RTSPHeader *reply, 

                          unsigned char **content_ptr)

{

    RTSPState *rt = s->priv_data;

    char buf[4096], buf1[1024], *q;

    unsigned char ch;

    const char *p;

    int content_length, line_count;

    unsigned char *content = NULL;



    memset(reply, 0, sizeof(RTSPHeader));



    rt->seq++;

    pstrcpy(buf, sizeof(buf), cmd);

    snprintf(buf1, sizeof(buf1), "CSeq: %d\r\n", rt->seq);

    pstrcat(buf, sizeof(buf), buf1);

    if (rt->session_id[0] != '\0' && !strstr(cmd, "\nIf-Match:")) {

        snprintf(buf1, sizeof(buf1), "Session: %s\r\n", rt->session_id);

        pstrcat(buf, sizeof(buf), buf1);

    }

    pstrcat(buf, sizeof(buf), "\r\n");

#ifdef DEBUG

    printf("Sending:\n%s--\n", buf);

#endif

    url_write(rt->rtsp_hd, buf, strlen(buf));



    /* parse reply (XXX: use buffers) */

    line_count = 0;

    rt->last_reply[0] = '\0';

    for(;;) {

        q = buf;

        for(;;) {

            if (url_read(rt->rtsp_hd, &ch, 1) == 0)

                break;

            if (ch == '\n')

                break;

            if (ch != '\r') {

                if ((q - buf) < sizeof(buf) - 1)

                    *q++ = ch;

            }

        }

        *q = '\0';

#ifdef DEBUG

        printf("line='%s'\n", buf);

#endif

        /* test if last line */

        if (buf[0] == '\0')

            break;

        p = buf;

        if (line_count == 0) {

            /* get reply code */

            get_word(buf1, sizeof(buf1), &p);

            get_word(buf1, sizeof(buf1), &p);

            reply->status_code = atoi(buf1);

        } else {

            rtsp_parse_line(reply, p);

            pstrcat(rt->last_reply, sizeof(rt->last_reply), p);

            pstrcat(rt->last_reply, sizeof(rt->last_reply), "\n");

        }

        line_count++;

    }



    if (rt->session_id[0] == '\0' && reply->session_id[0] != '\0')

        pstrcpy(rt->session_id, sizeof(rt->session_id), reply->session_id);



    content_length = reply->content_length;

    if (content_length > 0) {

        /* leave some room for a trailing '\0' (useful for simple parsing) */

        content = av_malloc(content_length + 1);

        url_read(rt->rtsp_hd, content, content_length);

        content[content_length] = '\0';

    }

    if (content_ptr)

        *content_ptr = content;

}

static void gmc1_motion(MpegEncContext *s,

                        uint8_t *dest_y, uint8_t *dest_cb, uint8_t *dest_cr,

                        uint8_t **ref_picture)

{

    uint8_t *ptr;

    int offset, src_x, src_y, linesize, uvlinesize;

    int motion_x, motion_y;

    int emu=0;



    motion_x= s->sprite_offset[0][0];

    motion_y= s->sprite_offset[0][1];

    src_x = s->mb_x * 16 + (motion_x >> (s->sprite_warping_accuracy+1));

    src_y = s->mb_y * 16 + (motion_y >> (s->sprite_warping_accuracy+1));

    motion_x<<=(3-s->sprite_warping_accuracy);

    motion_y<<=(3-s->sprite_warping_accuracy);

    src_x = av_clip(src_x, -16, s->width);

    if (src_x == s->width)

        motion_x =0;

    src_y = av_clip(src_y, -16, s->height);

    if (src_y == s->height)

        motion_y =0;



    linesize = s->linesize;

    uvlinesize = s->uvlinesize;



    ptr = ref_picture[0] + (src_y * linesize) + src_x;



    if(s->flags&CODEC_FLAG_EMU_EDGE){

        if(   (unsigned)src_x >= FFMAX(s->h_edge_pos - 17, 0)

           || (unsigned)src_y >= FFMAX(s->v_edge_pos - 17, 0)){

            s->vdsp.emulated_edge_mc(s->edge_emu_buffer, ptr, linesize, 17, 17, src_x, src_y, s->h_edge_pos, s->v_edge_pos);

            ptr= s->edge_emu_buffer;

        }

    }



    if((motion_x|motion_y)&7){

        s->dsp.gmc1(dest_y  , ptr  , linesize, 16, motion_x&15, motion_y&15, 128 - s->no_rounding);

        s->dsp.gmc1(dest_y+8, ptr+8, linesize, 16, motion_x&15, motion_y&15, 128 - s->no_rounding);

    }else{

        int dxy;



        dxy= ((motion_x>>3)&1) | ((motion_y>>2)&2);

        if (s->no_rounding){

            s->hdsp.put_no_rnd_pixels_tab[0][dxy](dest_y, ptr, linesize, 16);

        }else{

            s->hdsp.put_pixels_tab       [0][dxy](dest_y, ptr, linesize, 16);

        }

    }



    if(CONFIG_GRAY && s->flags&CODEC_FLAG_GRAY) return;



    motion_x= s->sprite_offset[1][0];

    motion_y= s->sprite_offset[1][1];

    src_x = s->mb_x * 8 + (motion_x >> (s->sprite_warping_accuracy+1));

    src_y = s->mb_y * 8 + (motion_y >> (s->sprite_warping_accuracy+1));

    motion_x<<=(3-s->sprite_warping_accuracy);

    motion_y<<=(3-s->sprite_warping_accuracy);

    src_x = av_clip(src_x, -8, s->width>>1);

    if (src_x == s->width>>1)

        motion_x =0;

    src_y = av_clip(src_y, -8, s->height>>1);

    if (src_y == s->height>>1)

        motion_y =0;



    offset = (src_y * uvlinesize) + src_x;

    ptr = ref_picture[1] + offset;

    if(s->flags&CODEC_FLAG_EMU_EDGE){

        if(   (unsigned)src_x >= FFMAX((s->h_edge_pos>>1) - 9, 0)

           || (unsigned)src_y >= FFMAX((s->v_edge_pos>>1) - 9, 0)){

            s->vdsp.emulated_edge_mc(s->edge_emu_buffer, ptr, uvlinesize, 9, 9, src_x, src_y, s->h_edge_pos>>1, s->v_edge_pos>>1);

            ptr= s->edge_emu_buffer;

            emu=1;

        }

    }

    s->dsp.gmc1(dest_cb, ptr, uvlinesize, 8, motion_x&15, motion_y&15, 128 - s->no_rounding);



    ptr = ref_picture[2] + offset;

    if(emu){

        s->vdsp.emulated_edge_mc(s->edge_emu_buffer, ptr, uvlinesize, 9, 9, src_x, src_y, s->h_edge_pos>>1, s->v_edge_pos>>1);

        ptr= s->edge_emu_buffer;

    }

    s->dsp.gmc1(dest_cr, ptr, uvlinesize, 8, motion_x&15, motion_y&15, 128 - s->no_rounding);



    return;

}

static int thread_get_buffer_internal(AVCodecContext *avctx, ThreadFrame *f, int flags)

{

    PerThreadContext *p = avctx->internal->thread_ctx;

    int err;



    f->owner = avctx;



    ff_init_buffer_info(avctx, f->f);



    if (!(avctx->active_thread_type & FF_THREAD_FRAME))

        return ff_get_buffer(avctx, f->f, flags);



    if (atomic_load(&p->state) != STATE_SETTING_UP &&

        (avctx->codec->update_thread_context || !THREAD_SAFE_CALLBACKS(avctx))) {

        av_log(avctx, AV_LOG_ERROR, "get_buffer() cannot be called after ff_thread_finish_setup()\n");

        return -1;

    }



    if (avctx->internal->allocate_progress) {

        atomic_int *progress;

        f->progress = av_buffer_alloc(2 * sizeof(*progress));

        if (!f->progress) {

            return AVERROR(ENOMEM);

        }

        progress = (atomic_int*)f->progress->data;



        atomic_init(&progress[0], -1);

        atomic_init(&progress[1], -1);

    }



    pthread_mutex_lock(&p->parent->buffer_mutex);

    if (avctx->thread_safe_callbacks ||

        avctx->get_buffer2 == avcodec_default_get_buffer2) {

        err = ff_get_buffer(avctx, f->f, flags);

    } else {

        pthread_mutex_lock(&p->progress_mutex);

        p->requested_frame = f->f;

        p->requested_flags = flags;

        atomic_store_explicit(&p->state, STATE_GET_BUFFER, memory_order_release);

        pthread_cond_broadcast(&p->progress_cond);



        while (atomic_load(&p->state) != STATE_SETTING_UP)

            pthread_cond_wait(&p->progress_cond, &p->progress_mutex);



        err = p->result;



        pthread_mutex_unlock(&p->progress_mutex);



    }

    if (!THREAD_SAFE_CALLBACKS(avctx) && !avctx->codec->update_thread_context)

        ff_thread_finish_setup(avctx);

    if (err)

        av_buffer_unref(&f->progress);



    pthread_mutex_unlock(&p->parent->buffer_mutex);



    return err;

}

