static int encode_superframe(AVCodecContext *avctx, AVPacket *avpkt,

                             const AVFrame *frame, int *got_packet_ptr)

{

    WMACodecContext *s = avctx->priv_data;

    int i, total_gain, ret, error;



    s->block_len_bits= s->frame_len_bits; //required by non variable block len

    s->block_len = 1 << s->block_len_bits;



    apply_window_and_mdct(avctx, frame);



    if (s->ms_stereo) {

        float a, b;

        int i;



        for(i = 0; i < s->block_len; i++) {

            a = s->coefs[0][i]*0.5;

            b = s->coefs[1][i]*0.5;

            s->coefs[0][i] = a + b;

            s->coefs[1][i] = a - b;





    if ((ret = ff_alloc_packet2(avctx, avpkt, 2 * MAX_CODED_SUPERFRAME_SIZE)) < 0)

        return ret;



    total_gain= 128;

    for(i=64; i; i>>=1){

        error = encode_frame(s, s->coefs, avpkt->data, avpkt->size,

                                 total_gain - i);

        if(error<=0)

            total_gain-= i;




    while(total_gain <= 128 && error > 0)

        error = encode_frame(s, s->coefs, avpkt->data, avpkt->size, total_gain++);






    av_assert0((put_bits_count(&s->pb) & 7) == 0);

    i= avctx->block_align - (put_bits_count(&s->pb)+7)/8;

    av_assert0(i>=0);

    while(i--)

        put_bits(&s->pb, 8, 'N');



    flush_put_bits(&s->pb);

    av_assert0(put_bits_ptr(&s->pb) - s->pb.buf == avctx->block_align);



    if (frame->pts != AV_NOPTS_VALUE)

        avpkt->pts = frame->pts - ff_samples_to_time_base(avctx, avctx->delay);



    avpkt->size = avctx->block_align;

    *got_packet_ptr = 1;

    return 0;

static int ftp_passive_mode(FTPContext *s)

{

    char *res = NULL, *start, *end;

    int i;

    const char *command = "PASV\r\n";

    const int pasv_codes[] = {227, 501, 0}; /* 501 is incorrect code */



    if (ftp_send_command(s, command, pasv_codes, &res) != 227 || !res)

        goto fail;



    start = NULL;

    for (i = 0; i < strlen(res); ++i) {

        if (res[i] == '(') {

            start = res + i + 1;

        } else if (res[i] == ')') {

            end = res + i;

            break;

        }

    }

    if (!start || !end)

        goto fail;



    *end  = '\0';

    /* skip ip */

    if (!av_strtok(start, ",", &end)) goto fail;

    if (!av_strtok(end, ",", &end)) goto fail;

    if (!av_strtok(end, ",", &end)) goto fail;

    if (!av_strtok(end, ",", &end)) goto fail;



    /* parse port number */

    start = av_strtok(end, ",", &end);

    if (!start) goto fail;

    s->server_data_port = atoi(start) * 256;

    start = av_strtok(end, ",", &end);

    if (!start) goto fail;

    s->server_data_port += atoi(start);

    av_dlog(s, "Server data port: %d\n", s->server_data_port);



    av_free(res);

    return 0;



  fail:

    av_free(res);

    s->server_data_port = -1;

    return AVERROR(EIO);

}

static int wavpack_decode_block(AVCodecContext *avctx, int block_no,

                                void *data, int *data_size,

                                const uint8_t *buf, int buf_size)

{

    WavpackContext *wc = avctx->priv_data;

    WavpackFrameContext *s;

    void *samples = data;

    int samplecount;

    int got_terms = 0, got_weights = 0, got_samples = 0, got_entropy = 0, got_bs = 0, got_float = 0;

    int got_hybrid = 0;

    const uint8_t* orig_buf = buf;

    const uint8_t* buf_end = buf + buf_size;

    int i, j, id, size, ssize, weights, t;

    int bpp, chan, chmask;



    if (buf_size == 0){

        *data_size = 0;

        return 0;

    }



    if(block_no >= wc->fdec_num && wv_alloc_frame_context(wc) < 0){

        av_log(avctx, AV_LOG_ERROR, "Error creating frame decode context\n");

        return -1;

    }



    s = wc->fdec[block_no];

    if(!s){

        av_log(avctx, AV_LOG_ERROR, "Context for block %d is not present\n", block_no);

        return -1;

    }



    if(!s->samples_left){

        memset(s->decorr, 0, MAX_TERMS * sizeof(Decorr));

        memset(s->ch, 0, sizeof(s->ch));

        s->extra_bits = 0;

        s->and = s->or = s->shift = 0;

        s->got_extra_bits = 0;

    }



    if(!wc->mkv_mode){

        s->samples = AV_RL32(buf); buf += 4;

        if(!s->samples){

            *data_size = 0;

            return 0;

        }

    }else{

        s->samples = wc->samples;

    }

    s->frame_flags = AV_RL32(buf); buf += 4;

    if(s->frame_flags&0x80){

        bpp = sizeof(float);

        avctx->sample_fmt = AV_SAMPLE_FMT_FLT;

    } else if((s->frame_flags&0x03) <= 1){

        bpp = 2;

        avctx->sample_fmt = AV_SAMPLE_FMT_S16;

    } else {

        bpp = 4;

        avctx->sample_fmt = AV_SAMPLE_FMT_S32;

    }

    samples = (uint8_t*)samples + bpp * wc->ch_offset;



    s->stereo = !(s->frame_flags & WV_MONO);

    s->stereo_in = (s->frame_flags & WV_FALSE_STEREO) ? 0 : s->stereo;

    s->joint = s->frame_flags & WV_JOINT_STEREO;

    s->hybrid = s->frame_flags & WV_HYBRID_MODE;

    s->hybrid_bitrate = s->frame_flags & WV_HYBRID_BITRATE;

    s->post_shift = 8 * (bpp-1-(s->frame_flags&0x03)) + ((s->frame_flags >> 13) & 0x1f);

    s->CRC = AV_RL32(buf); buf += 4;

    if(wc->mkv_mode)

        buf += 4; //skip block size;



    wc->ch_offset += 1 + s->stereo;



    s->max_samples = *data_size / (bpp * avctx->channels);

    s->max_samples = FFMIN(s->max_samples, s->samples);

    if(s->samples_left > 0){

        s->max_samples = FFMIN(s->max_samples, s->samples_left);

        buf = buf_end;

    }



    // parse metadata blocks

    while(buf < buf_end){

        id = *buf++;

        size = *buf++;

        if(id & WP_IDF_LONG) {

            size |= (*buf++) << 8;

            size |= (*buf++) << 16;

        }

        size <<= 1; // size is specified in words

        ssize = size;

        if(id & WP_IDF_ODD) size--;

        if(size < 0){

            av_log(avctx, AV_LOG_ERROR, "Got incorrect block %02X with size %i\n", id, size);

            break;

        }

        if(buf + ssize > buf_end){

            av_log(avctx, AV_LOG_ERROR, "Block size %i is out of bounds\n", size);

            break;

        }

        if(id & WP_IDF_IGNORE){

            buf += ssize;

            continue;

        }

        switch(id & WP_IDF_MASK){

        case WP_ID_DECTERMS:

            s->terms = size;

            if(s->terms > MAX_TERMS){

                av_log(avctx, AV_LOG_ERROR, "Too many decorrelation terms\n");

                buf += ssize;

                continue;

            }

            for(i = 0; i < s->terms; i++) {

                s->decorr[s->terms - i - 1].value = (*buf & 0x1F) - 5;

                s->decorr[s->terms - i - 1].delta = *buf >> 5;

                buf++;

            }

            got_terms = 1;

            break;

        case WP_ID_DECWEIGHTS:

            if(!got_terms){

                av_log(avctx, AV_LOG_ERROR, "No decorrelation terms met\n");

                continue;

            }

            weights = size >> s->stereo_in;

            if(weights > MAX_TERMS || weights > s->terms){

                av_log(avctx, AV_LOG_ERROR, "Too many decorrelation weights\n");

                buf += ssize;

                continue;

            }

            for(i = 0; i < weights; i++) {

                t = (int8_t)(*buf++);

                s->decorr[s->terms - i - 1].weightA = t << 3;

                if(s->decorr[s->terms - i - 1].weightA > 0)

                    s->decorr[s->terms - i - 1].weightA += (s->decorr[s->terms - i - 1].weightA + 64) >> 7;

                if(s->stereo_in){

                    t = (int8_t)(*buf++);

                    s->decorr[s->terms - i - 1].weightB = t << 3;

                    if(s->decorr[s->terms - i - 1].weightB > 0)

                        s->decorr[s->terms - i - 1].weightB += (s->decorr[s->terms - i - 1].weightB + 64) >> 7;

                }

            }

            got_weights = 1;

            break;

        case WP_ID_DECSAMPLES:

            if(!got_terms){

                av_log(avctx, AV_LOG_ERROR, "No decorrelation terms met\n");

                continue;

            }

            t = 0;

            for(i = s->terms - 1; (i >= 0) && (t < size); i--) {

                if(s->decorr[i].value > 8){

                    s->decorr[i].samplesA[0] = wp_exp2(AV_RL16(buf)); buf += 2;

                    s->decorr[i].samplesA[1] = wp_exp2(AV_RL16(buf)); buf += 2;

                    if(s->stereo_in){

                        s->decorr[i].samplesB[0] = wp_exp2(AV_RL16(buf)); buf += 2;

                        s->decorr[i].samplesB[1] = wp_exp2(AV_RL16(buf)); buf += 2;

                        t += 4;

                    }

                    t += 4;

                }else if(s->decorr[i].value < 0){

                    s->decorr[i].samplesA[0] = wp_exp2(AV_RL16(buf)); buf += 2;

                    s->decorr[i].samplesB[0] = wp_exp2(AV_RL16(buf)); buf += 2;

                    t += 4;

                }else{

                    for(j = 0; j < s->decorr[i].value; j++){

                        s->decorr[i].samplesA[j] = wp_exp2(AV_RL16(buf)); buf += 2;

                        if(s->stereo_in){

                            s->decorr[i].samplesB[j] = wp_exp2(AV_RL16(buf)); buf += 2;

                        }

                    }

                    t += s->decorr[i].value * 2 * (s->stereo_in + 1);

                }

            }

            got_samples = 1;

            break;

        case WP_ID_ENTROPY:

            if(size != 6 * (s->stereo_in + 1)){

                av_log(avctx, AV_LOG_ERROR, "Entropy vars size should be %i, got %i", 6 * (s->stereo_in + 1), size);

                buf += ssize;

                continue;

            }

            for(j = 0; j <= s->stereo_in; j++){

                for(i = 0; i < 3; i++){

                    s->ch[j].median[i] = wp_exp2(AV_RL16(buf));

                    buf += 2;

                }

            }

            got_entropy = 1;

            break;

        case WP_ID_HYBRID:

            if(s->hybrid_bitrate){

                for(i = 0; i <= s->stereo_in; i++){

                    s->ch[i].slow_level = wp_exp2(AV_RL16(buf));

                    buf += 2;

                    size -= 2;

                }

            }

            for(i = 0; i < (s->stereo_in + 1); i++){

                s->ch[i].bitrate_acc = AV_RL16(buf) << 16;

                buf += 2;

                size -= 2;

            }

            if(size > 0){

                for(i = 0; i < (s->stereo_in + 1); i++){

                    s->ch[i].bitrate_delta = wp_exp2((int16_t)AV_RL16(buf));

                    buf += 2;

                }

            }else{

                for(i = 0; i < (s->stereo_in + 1); i++)

                    s->ch[i].bitrate_delta = 0;

            }

            got_hybrid = 1;

            break;

        case WP_ID_INT32INFO:

            if(size != 4){

                av_log(avctx, AV_LOG_ERROR, "Invalid INT32INFO, size = %i, sent_bits = %i\n", size, *buf);

                buf += ssize;

                continue;

            }

            if(buf[0])

                s->extra_bits = buf[0];

            else if(buf[1])

                s->shift = buf[1];

            else if(buf[2]){

                s->and = s->or = 1;

                s->shift = buf[2];

            }else if(buf[3]){

                s->and = 1;

                s->shift = buf[3];

            }

            buf += 4;

            break;

        case WP_ID_FLOATINFO:

            if(size != 4){

                av_log(avctx, AV_LOG_ERROR, "Invalid FLOATINFO, size = %i\n", size);

                buf += ssize;

                continue;

            }

            s->float_flag = buf[0];

            s->float_shift = buf[1];

            s->float_max_exp = buf[2];

            buf += 4;

            got_float = 1;

            break;

        case WP_ID_DATA:

            s->sc.offset = buf - orig_buf;

            s->sc.size   = size * 8;

            init_get_bits(&s->gb, buf, size * 8);

            s->data_size = size * 8;

            buf += size;

            got_bs = 1;

            break;

        case WP_ID_EXTRABITS:

            if(size <= 4){

                av_log(avctx, AV_LOG_ERROR, "Invalid EXTRABITS, size = %i\n", size);

                buf += size;

                continue;

            }

            s->extra_sc.offset = buf - orig_buf;

            s->extra_sc.size   = size * 8;

            init_get_bits(&s->gb_extra_bits, buf, size * 8);

            s->crc_extra_bits = get_bits_long(&s->gb_extra_bits, 32);

            buf += size;

            s->got_extra_bits = 1;

            break;

        case WP_ID_CHANINFO:

            if(size <= 1){

                av_log(avctx, AV_LOG_ERROR, "Insufficient channel information\n");

                return -1;

            }

            chan = *buf++;

            switch(size - 2){

            case 0:

                chmask = *buf;

                break;

            case 1:

                chmask = AV_RL16(buf);

                break;

            case 2:

                chmask = AV_RL24(buf);

                break;

            case 3:

                chmask = AV_RL32(buf);

                break;

            case 5:

                chan |= (buf[1] & 0xF) << 8;

                chmask = AV_RL24(buf + 2);

                break;

            default:

                av_log(avctx, AV_LOG_ERROR, "Invalid channel info size %d\n", size);

                chan = avctx->channels;

                chmask = avctx->channel_layout;

            }

            if(chan != avctx->channels){

                av_log(avctx, AV_LOG_ERROR, "Block reports total %d channels, decoder believes it's %d channels\n",

                       chan, avctx->channels);

                return -1;

            }

            if(!avctx->channel_layout)

                avctx->channel_layout = chmask;

            buf += size - 1;

            break;

        default:

            buf += size;

        }

        if(id & WP_IDF_ODD) buf++;

    }

    if(!s->samples_left){

        if(!got_terms){

            av_log(avctx, AV_LOG_ERROR, "No block with decorrelation terms\n");

            return -1;

        }

        if(!got_weights){

            av_log(avctx, AV_LOG_ERROR, "No block with decorrelation weights\n");

            return -1;

        }

        if(!got_samples){

            av_log(avctx, AV_LOG_ERROR, "No block with decorrelation samples\n");

            return -1;

        }

        if(!got_entropy){

            av_log(avctx, AV_LOG_ERROR, "No block with entropy info\n");

            return -1;

        }

        if(s->hybrid && !got_hybrid){

            av_log(avctx, AV_LOG_ERROR, "Hybrid config not found\n");

            return -1;

        }

        if(!got_bs){

            av_log(avctx, AV_LOG_ERROR, "Packed samples not found\n");

            return -1;

        }

        if(!got_float && avctx->sample_fmt == AV_SAMPLE_FMT_FLT){

            av_log(avctx, AV_LOG_ERROR, "Float information not found\n");

            return -1;

        }

        if(s->got_extra_bits && avctx->sample_fmt != AV_SAMPLE_FMT_FLT){

            const int size = get_bits_left(&s->gb_extra_bits);

            const int wanted = s->samples * s->extra_bits << s->stereo_in;

            if(size < wanted){

                av_log(avctx, AV_LOG_ERROR, "Too small EXTRABITS\n");

                s->got_extra_bits = 0;

            }

        }

        s->samples_left = s->samples;

    }else{

        init_get_bits(&s->gb, orig_buf + s->sc.offset, s->sc.size);

        skip_bits_long(&s->gb, s->sc.bits_used);

        if(s->got_extra_bits){

            init_get_bits(&s->gb_extra_bits, orig_buf + s->extra_sc.offset,

                          s->extra_sc.size);

            skip_bits_long(&s->gb_extra_bits, s->extra_sc.bits_used);

        }

    }



    if(s->stereo_in){

        if(avctx->sample_fmt == AV_SAMPLE_FMT_S16)

            samplecount = wv_unpack_stereo(s, &s->gb, samples, AV_SAMPLE_FMT_S16);

        else if(avctx->sample_fmt == AV_SAMPLE_FMT_S32)

            samplecount = wv_unpack_stereo(s, &s->gb, samples, AV_SAMPLE_FMT_S32);

        else

            samplecount = wv_unpack_stereo(s, &s->gb, samples, AV_SAMPLE_FMT_FLT);

        samplecount >>= 1;

    }else{

        const int channel_stride = avctx->channels;



        if(avctx->sample_fmt == AV_SAMPLE_FMT_S16)

            samplecount = wv_unpack_mono(s, &s->gb, samples, AV_SAMPLE_FMT_S16);

        else if(avctx->sample_fmt == AV_SAMPLE_FMT_S32)

            samplecount = wv_unpack_mono(s, &s->gb, samples, AV_SAMPLE_FMT_S32);

        else

            samplecount = wv_unpack_mono(s, &s->gb, samples, AV_SAMPLE_FMT_FLT);



        if(s->stereo && avctx->sample_fmt == AV_SAMPLE_FMT_S16){

            int16_t *dst = (int16_t*)samples + 1;

            int16_t *src = (int16_t*)samples;

            int cnt = samplecount;

            while(cnt--){

                *dst = *src;

                src += channel_stride;

                dst += channel_stride;

            }

        }else if(s->stereo && avctx->sample_fmt == AV_SAMPLE_FMT_S32){

            int32_t *dst = (int32_t*)samples + 1;

            int32_t *src = (int32_t*)samples;

            int cnt = samplecount;

            while(cnt--){

                *dst = *src;

                src += channel_stride;

                dst += channel_stride;

            }

        }else if(s->stereo){

            float *dst = (float*)samples + 1;

            float *src = (float*)samples;

            int cnt = samplecount;

            while(cnt--){

                *dst = *src;

                src += channel_stride;

                dst += channel_stride;

            }

        }

    }



    wc->samples_left = s->samples_left;



    return samplecount * bpp;

}

static int swf_read_header(AVFormatContext *s, AVFormatParameters *ap)

{

    ByteIOContext *pb = &s->pb;

    int nbits, len, frame_rate, tag, v;

    AVStream *st;



    if ((get_be32(pb) & 0xffffff00) != MKBETAG('F', 'W', 'S', 0))

        return -EIO;

    get_le32(pb);

    /* skip rectangle size */

    nbits = get_byte(pb) >> 3;

    len = (4 * nbits - 3 + 7) / 8;

    url_fskip(pb, len);

    frame_rate = get_le16(pb);

    get_le16(pb); /* frame count */



    for(;;) {

        tag = get_swf_tag(pb, &len);

        if (tag < 0) {

            fprintf(stderr, "No streaming found in SWF\n");

            return -EIO;

        }

        if (tag == TAG_STREAMHEAD) {

            /* streaming found */

            get_byte(pb);

            v = get_byte(pb);

            get_le16(pb);

            if (len!=4)

                url_fskip(pb,len-4);

            /* if mp3 streaming found, OK */

            if ((v & 0x20) != 0) {

                st = av_new_stream(s, 0);

                if (!st)

                    return -ENOMEM;



                if (v & 0x01)

                    st->codec.channels = 2;

                else

                    st->codec.channels = 1;



                switch((v>> 2) & 0x03) {

                case 1:

                    st->codec.sample_rate = 11025;

                    break;

                case 2:

                    st->codec.sample_rate = 22050;

                    break;

                case 3:

                    st->codec.sample_rate = 44100;

                    break;

                default:

                    av_free(st);

                    return -EIO;

                }

                st->codec.codec_type = CODEC_TYPE_AUDIO;

                st->codec.codec_id = CODEC_ID_MP2;

                break;

            }

        } else {

            url_fskip(pb, len);

        }

    }



    return 0;

}

static int crystalhd_receive_frame(AVCodecContext *avctx, AVFrame *frame)

{

    BC_STATUS bc_ret;

    BC_DTS_STATUS decoder_status = { 0, };

    CopyRet rec_ret;

    CHDContext *priv   = avctx->priv_data;

    HANDLE dev         = priv->dev;

    int got_frame = 0;



    av_log(avctx, AV_LOG_VERBOSE, "CrystalHD: receive_frame\n");



    bc_ret = DtsGetDriverStatus(dev, &decoder_status);

    if (bc_ret != BC_STS_SUCCESS) {

        av_log(avctx, AV_LOG_ERROR, "CrystalHD: GetDriverStatus failed\n");

        return -1;

    }



    if (decoder_status.ReadyListCount == 0) {

        av_log(avctx, AV_LOG_INFO, "CrystalHD: Insufficient frames ready. Returning\n");

        return AVERROR(EAGAIN);

    }



    rec_ret = receive_frame(avctx, frame, &got_frame);

    if (rec_ret == RET_ERROR) {

        return -1;

    } else if (got_frame == 0) {

        return AVERROR(EAGAIN);

    } else {

        return 0;

    }

}

av_cold int ff_opus_parse_extradata(AVCodecContext *avctx,

                                    OpusContext *s)

{

    static const uint8_t default_channel_map[2] = { 0, 1 };



    int (*channel_reorder)(int, int) = channel_reorder_unknown;



    const uint8_t *extradata, *channel_map;

    int extradata_size;

    int version, channels, map_type, streams, stereo_streams, i, j;

    uint64_t layout;



    if (!avctx->extradata) {

        if (avctx->channels > 2) {

            av_log(avctx, AV_LOG_ERROR,

                   "Multichannel configuration without extradata.\n");

            return AVERROR(EINVAL);

        }

        extradata      = opus_default_extradata;

        extradata_size = sizeof(opus_default_extradata);

    } else {

        extradata = avctx->extradata;

        extradata_size = avctx->extradata_size;

    }



    if (extradata_size < 19) {

        av_log(avctx, AV_LOG_ERROR, "Invalid extradata size: %d\n",

               extradata_size);

        return AVERROR_INVALIDDATA;

    }



    version = extradata[8];

    if (version > 15) {

        avpriv_request_sample(avctx, "Extradata version %d", version);

        return AVERROR_PATCHWELCOME;

    }



    avctx->delay = AV_RL16(extradata + 10);



    channels = avctx->extradata ? extradata[9] : (avctx->channels == 1) ? 1 : 2;

    if (!channels) {

        av_log(avctx, AV_LOG_ERROR, "Zero channel count specified in the extradata\n");

        return AVERROR_INVALIDDATA;

    }



    s->gain_i = AV_RL16(extradata + 16);

    if (s->gain_i)

        s->gain = ff_exp10(s->gain_i / (20.0 * 256));



    map_type = extradata[18];

    if (!map_type) {

        if (channels > 2) {

            av_log(avctx, AV_LOG_ERROR,

                   "Channel mapping 0 is only specified for up to 2 channels\n");

            return AVERROR_INVALIDDATA;

        }

        layout         = (channels == 1) ? AV_CH_LAYOUT_MONO : AV_CH_LAYOUT_STEREO;

        streams        = 1;

        stereo_streams = channels - 1;

        channel_map    = default_channel_map;

    } else if (map_type == 1 || map_type == 2 || map_type == 255) {

        if (extradata_size < 21 + channels) {

            av_log(avctx, AV_LOG_ERROR, "Invalid extradata size: %d\n",

                   extradata_size);

            return AVERROR_INVALIDDATA;

        }



        streams        = extradata[19];

        stereo_streams = extradata[20];

        if (!streams || stereo_streams > streams ||

            streams + stereo_streams > 255) {

            av_log(avctx, AV_LOG_ERROR,

                   "Invalid stream/stereo stream count: %d/%d\n", streams, stereo_streams);

            return AVERROR_INVALIDDATA;

        }



        if (map_type == 1) {

            if (channels > 8) {

                av_log(avctx, AV_LOG_ERROR,

                       "Channel mapping 1 is only specified for up to 8 channels\n");

                return AVERROR_INVALIDDATA;

            }

            layout = ff_vorbis_channel_layouts[channels - 1];

            channel_reorder = channel_reorder_vorbis;

        } else if (map_type == 2) {

            int ambisonic_order = ff_sqrt(channels) - 1;

            if (channels != (ambisonic_order + 1) * (ambisonic_order + 1)) {

                av_log(avctx, AV_LOG_ERROR,

                       "Channel mapping 2 is only specified for channel counts"

                       " which can be written as (n + 1)^2 for nonnegative integer n\n");

                return AVERROR_INVALIDDATA;

            }

            layout = 0;

        } else

            layout = 0;



        channel_map = extradata + 21;

    } else {

        avpriv_request_sample(avctx, "Mapping type %d", map_type);

        return AVERROR_PATCHWELCOME;

    }



    s->channel_maps = av_mallocz_array(channels, sizeof(*s->channel_maps));

    if (!s->channel_maps)

        return AVERROR(ENOMEM);



    for (i = 0; i < channels; i++) {

        ChannelMap *map = &s->channel_maps[i];

        uint8_t     idx = channel_map[channel_reorder(channels, i)];



        if (idx == 255) {

            map->silence = 1;

            continue;

        } else if (idx >= streams + stereo_streams) {

            av_log(avctx, AV_LOG_ERROR,

                   "Invalid channel map for output channel %d: %d\n", i, idx);


            return AVERROR_INVALIDDATA;

        }



        /* check that we did not see this index yet */

        map->copy = 0;

        for (j = 0; j < i; j++)

            if (channel_map[channel_reorder(channels, j)] == idx) {

                map->copy     = 1;

                map->copy_idx = j;

                break;

            }



        if (idx < 2 * stereo_streams) {

            map->stream_idx  = idx / 2;

            map->channel_idx = idx & 1;

        } else {

            map->stream_idx  = idx - stereo_streams;

            map->channel_idx = 0;

        }

    }



    avctx->channels       = channels;

    avctx->channel_layout = layout;

    s->nb_streams         = streams;

    s->nb_stereo_streams  = stereo_streams;



    return 0;

}

static int do_packet_auto_bsf(AVFormatContext *s, AVPacket *pkt) {

    AVStream *st = s->streams[pkt->stream_index];

    int i, ret;



    if (!(s->flags & AVFMT_FLAG_AUTO_BSF))

        return 1;



    if (s->oformat->check_bitstream) {

        if (!st->internal->bitstream_checked) {

            if ((ret = s->oformat->check_bitstream(s, pkt)) < 0)

                return ret;

            else if (ret == 1)

                st->internal->bitstream_checked = 1;

        }

    }



#if FF_API_LAVF_MERGE_SD

FF_DISABLE_DEPRECATION_WARNINGS

    if (st->internal->nb_bsfcs) {

        ret = av_packet_split_side_data(pkt);

        if (ret < 0)

            av_log(s, AV_LOG_WARNING, "Failed to split side data before bitstream filter\n");

    }

FF_ENABLE_DEPRECATION_WARNINGS

#endif



    for (i = 0; i < st->internal->nb_bsfcs; i++) {

        AVBSFContext *ctx = st->internal->bsfcs[i];

        if (i > 0) {

            AVBSFContext* prev_ctx = st->internal->bsfcs[i - 1];

            if (prev_ctx->par_out->extradata_size != ctx->par_in->extradata_size) {

                if ((ret = avcodec_parameters_copy(ctx->par_in, prev_ctx->par_out)) < 0)

                    return ret;

            }

        }

        // TODO: when any bitstream filter requires flushing at EOF, we'll need to

        // flush each stream's BSF chain on write_trailer.

        if ((ret = av_bsf_send_packet(ctx, pkt)) < 0) {

            av_log(ctx, AV_LOG_ERROR,

                    "Failed to send packet to filter %s for stream %d\n",

                    ctx->filter->name, pkt->stream_index);

            return ret;

        }

        // TODO: when any automatically-added bitstream filter is generating multiple

        // output packets for a single input one, we'll need to call this in a loop

        // and write each output packet.

        if ((ret = av_bsf_receive_packet(ctx, pkt)) < 0) {

            if (ret == AVERROR(EAGAIN) || ret == AVERROR_EOF)

                return 0;

            av_log(ctx, AV_LOG_ERROR,

                    "Failed to send packet to filter %s for stream %d\n",

                    ctx->filter->name, pkt->stream_index);

            return ret;

        }

        if (i == st->internal->nb_bsfcs - 1) {

            if (ctx->par_out->extradata_size != st->codecpar->extradata_size) {

                if ((ret = avcodec_parameters_copy(st->codecpar, ctx->par_out)) < 0)

                    return ret;

            }

        }

    }

    return 1;

}

AVFilterContext *ff_filter_alloc(const AVFilter *filter, const char *inst_name)

{

    AVFilterContext *ret;



    if (!filter)

        return NULL;



    ret = av_mallocz(sizeof(AVFilterContext));

    if (!ret)

        return NULL;



    ret->av_class = &avfilter_class;

    ret->filter   = filter;

    ret->name     = inst_name ? av_strdup(inst_name) : NULL;

    if (filter->priv_size) {

        ret->priv     = av_mallocz(filter->priv_size);

        if (!ret->priv)

            goto err;

    }



    if (filter->priv_class) {

        *(const AVClass**)ret->priv = filter->priv_class;

        av_opt_set_defaults(ret->priv);

    }



    ret->nb_inputs = pad_count(filter->inputs);

    if (ret->nb_inputs ) {

        ret->input_pads   = av_malloc(sizeof(AVFilterPad) * ret->nb_inputs);

        if (!ret->input_pads)

            goto err;

        memcpy(ret->input_pads, filter->inputs, sizeof(AVFilterPad) * ret->nb_inputs);

        ret->inputs       = av_mallocz(sizeof(AVFilterLink*) * ret->nb_inputs);

        if (!ret->inputs)

            goto err;

    }



    ret->nb_outputs = pad_count(filter->outputs);

    if (ret->nb_outputs) {

        ret->output_pads  = av_malloc(sizeof(AVFilterPad) * ret->nb_outputs);

        if (!ret->output_pads)

            goto err;

        memcpy(ret->output_pads, filter->outputs, sizeof(AVFilterPad) * ret->nb_outputs);

        ret->outputs      = av_mallocz(sizeof(AVFilterLink*) * ret->nb_outputs);

        if (!ret->outputs)

            goto err;

    }

#if FF_API_FOO_COUNT

    ret->output_count = ret->nb_outputs;

    ret->input_count  = ret->nb_inputs;

#endif



    return ret;



err:

    av_freep(&ret->inputs);

    av_freep(&ret->input_pads);

    ret->nb_inputs = 0;

    av_freep(&ret->outputs);

    av_freep(&ret->output_pads);

    ret->nb_outputs = 0;

    av_freep(&ret->priv);

    av_free(ret);

    return NULL;

}

static int dv_decode_video_segment(AVCodecContext *avctx, void *arg)

{

    DVVideoContext *s = avctx->priv_data;

    DVwork_chunk *work_chunk = arg;

    int quant, dc, dct_mode, class1, j;

    int mb_index, mb_x, mb_y, last_index;

    int y_stride, linesize;

    DCTELEM *block, *block1;

    int c_offset;

    uint8_t *y_ptr;

    const uint8_t *buf_ptr;

    PutBitContext pb, vs_pb;

    GetBitContext gb;

    BlockInfo mb_data[5 * DV_MAX_BPM], *mb, *mb1;

    LOCAL_ALIGNED_16(DCTELEM, sblock, [5*DV_MAX_BPM], [64]);

    LOCAL_ALIGNED_16(uint8_t, mb_bit_buffer, [  80 + FF_INPUT_BUFFER_PADDING_SIZE]); /* allow some slack */

    LOCAL_ALIGNED_16(uint8_t, vs_bit_buffer, [5*80 + FF_INPUT_BUFFER_PADDING_SIZE]); /* allow some slack */

    const int log2_blocksize = 3;

    int is_field_mode[5];



    assert((((int)mb_bit_buffer) & 7) == 0);

    assert((((int)vs_bit_buffer) & 7) == 0);



    memset(sblock, 0, 5*DV_MAX_BPM*sizeof(*sblock));



    /* pass 1: read DC and AC coefficients in blocks */

    buf_ptr = &s->buf[work_chunk->buf_offset*80];

    block1  = &sblock[0][0];

    mb1     = mb_data;

    init_put_bits(&vs_pb, vs_bit_buffer, 5 * 80);

    for (mb_index = 0; mb_index < 5; mb_index++, mb1 += s->sys->bpm, block1 += s->sys->bpm * 64) {

        /* skip header */

        quant = buf_ptr[3] & 0x0f;

        buf_ptr += 4;

        init_put_bits(&pb, mb_bit_buffer, 80);

        mb    = mb1;

        block = block1;

        is_field_mode[mb_index] = 0;

        for (j = 0; j < s->sys->bpm; j++) {

            last_index = s->sys->block_sizes[j];

            init_get_bits(&gb, buf_ptr, last_index);



            /* get the DC */

            dc       = get_sbits(&gb, 9);

            dct_mode = get_bits1(&gb);

            class1   = get_bits(&gb, 2);

            if (DV_PROFILE_IS_HD(s->sys)) {

                mb->idct_put     = s->idct_put[0];

                mb->scan_table   = s->dv_zigzag[0];

                mb->factor_table = &s->sys->idct_factor[(j >= 4)*4*16*64 + class1*16*64 + quant*64];

                is_field_mode[mb_index] |= !j && dct_mode;

            } else {

                mb->idct_put     = s->idct_put[dct_mode && log2_blocksize == 3];

                mb->scan_table   = s->dv_zigzag[dct_mode];

                mb->factor_table = &s->sys->idct_factor[(class1 == 3)*2*22*64 + dct_mode*22*64 +

                                                        (quant + ff_dv_quant_offset[class1])*64];

            }

            dc = dc << 2;

            /* convert to unsigned because 128 is not added in the

               standard IDCT */

            dc += 1024;

            block[0] = dc;

            buf_ptr += last_index >> 3;

            mb->pos               = 0;

            mb->partial_bit_count = 0;



            av_dlog(avctx, "MB block: %d, %d ", mb_index, j);

            dv_decode_ac(&gb, mb, block);



            /* write the remaining bits in a new buffer only if the

               block is finished */

            if (mb->pos >= 64)

                bit_copy(&pb, &gb);



            block += 64;

            mb++;

        }



        /* pass 2: we can do it just after */

        av_dlog(avctx, "***pass 2 size=%d MB#=%d\n", put_bits_count(&pb), mb_index);

        block = block1;

        mb    = mb1;

        init_get_bits(&gb, mb_bit_buffer, put_bits_count(&pb));

        put_bits32(&pb, 0); // padding must be zeroed

        flush_put_bits(&pb);

        for (j = 0; j < s->sys->bpm; j++, block += 64, mb++) {

            if (mb->pos < 64 && get_bits_left(&gb) > 0) {

                dv_decode_ac(&gb, mb, block);

                /* if still not finished, no need to parse other blocks */

                if (mb->pos < 64)

                    break;

            }

        }

        /* all blocks are finished, so the extra bytes can be used at

           the video segment level */

        if (j >= s->sys->bpm)

            bit_copy(&vs_pb, &gb);

    }



    /* we need a pass over the whole video segment */

    av_dlog(avctx, "***pass 3 size=%d\n", put_bits_count(&vs_pb));

    block = &sblock[0][0];

    mb    = mb_data;

    init_get_bits(&gb, vs_bit_buffer, put_bits_count(&vs_pb));

    put_bits32(&vs_pb, 0); // padding must be zeroed

    flush_put_bits(&vs_pb);

    for (mb_index = 0; mb_index < 5; mb_index++) {

        for (j = 0; j < s->sys->bpm; j++) {

            if (mb->pos < 64) {

                av_dlog(avctx, "start %d:%d\n", mb_index, j);

                dv_decode_ac(&gb, mb, block);

            }

            if (mb->pos >= 64 && mb->pos < 127)

                av_log(avctx, AV_LOG_ERROR, "AC EOB marker is absent pos=%d\n", mb->pos);

            block += 64;

            mb++;

        }

    }



    /* compute idct and place blocks */

    block = &sblock[0][0];

    mb    = mb_data;

    for (mb_index = 0; mb_index < 5; mb_index++) {

        dv_calculate_mb_xy(s, work_chunk, mb_index, &mb_x, &mb_y);



        /* idct_put'ting luminance */

        if ((s->sys->pix_fmt == PIX_FMT_YUV420P) ||

            (s->sys->pix_fmt == PIX_FMT_YUV411P && mb_x >= (704 / 8)) ||

            (s->sys->height >= 720 && mb_y != 134)) {

            y_stride = (s->picture.linesize[0] << ((!is_field_mode[mb_index]) * log2_blocksize));

        } else {

            y_stride = (2 << log2_blocksize);

        }

        y_ptr = s->picture.data[0] + ((mb_y * s->picture.linesize[0] + mb_x) << log2_blocksize);

        linesize = s->picture.linesize[0] << is_field_mode[mb_index];

        mb[0]    .idct_put(y_ptr                                   , linesize, block + 0*64);

        if (s->sys->video_stype == 4) { /* SD 422 */

            mb[2].idct_put(y_ptr + (1 << log2_blocksize)           , linesize, block + 2*64);

        } else {

            mb[1].idct_put(y_ptr + (1 << log2_blocksize)           , linesize, block + 1*64);

            mb[2].idct_put(y_ptr                         + y_stride, linesize, block + 2*64);

            mb[3].idct_put(y_ptr + (1 << log2_blocksize) + y_stride, linesize, block + 3*64);

        }

        mb += 4;

        block += 4*64;



        /* idct_put'ting chrominance */

        c_offset = (((mb_y >>  (s->sys->pix_fmt == PIX_FMT_YUV420P)) * s->picture.linesize[1] +

                     (mb_x >> ((s->sys->pix_fmt == PIX_FMT_YUV411P) ? 2 : 1))) << log2_blocksize);

        for (j = 2; j; j--) {

            uint8_t *c_ptr = s->picture.data[j] + c_offset;

            if (s->sys->pix_fmt == PIX_FMT_YUV411P && mb_x >= (704 / 8)) {

                  uint64_t aligned_pixels[64/8];

                  uint8_t *pixels = (uint8_t*)aligned_pixels;

                  uint8_t *c_ptr1, *ptr1;

                  int x, y;

                  mb->idct_put(pixels, 8, block);

                  for (y = 0; y < (1 << log2_blocksize); y++, c_ptr += s->picture.linesize[j], pixels += 8) {

                      ptr1   = pixels + (1 << (log2_blocksize - 1));

                      c_ptr1 = c_ptr + (s->picture.linesize[j] << log2_blocksize);

                      for (x = 0; x < (1 << (log2_blocksize - 1)); x++) {

                          c_ptr[x]  = pixels[x];

                          c_ptr1[x] = ptr1[x];

                      }

                  }

                  block += 64; mb++;

            } else {

                  y_stride = (mb_y == 134) ? (1 << log2_blocksize) :

                                             s->picture.linesize[j] << ((!is_field_mode[mb_index]) * log2_blocksize);

                  linesize = s->picture.linesize[j] << is_field_mode[mb_index];

                  (mb++)->    idct_put(c_ptr           , linesize, block); block += 64;

                  if (s->sys->bpm == 8) {

                      (mb++)->idct_put(c_ptr + y_stride, linesize, block); block += 64;

                  }

            }

        }

    }

    return 0;

}

static void compute_default_clut(AVSubtitleRect *rect, int w, int h)

{

    uint8_t list[256] = {0};

    uint8_t list_inv[256];

    int counttab[256] = {0};

    int count, i, x, y;



#define V(x,y) rect->data[0][(x) + (y)*rect->linesize[0]]

    for (y = 0; y<h; y++) {

        for (x = 0; x<w; x++) {

            int v = V(x,y) + 1;

            int vl = x     ? V(x-1,y) + 1 : 0;

            int vr = x+1<w ? V(x+1,y) + 1 : 0;

            int vt = y     ? V(x,y-1) + 1 : 0;

            int vb = y+1<h ? V(x,y+1) + 1 : 0;

            counttab[v-1] += !!((v!=vl) + (v!=vr) + (v!=vt) + (v!=vb));

        }

    }

#define L(x,y) list[ rect->data[0][(x) + (y)*rect->linesize[0]] ]



    for (i = 0; i<256; i++) {

        int scoretab[256] = {0};

        int bestscore = 0;

        int bestv = 0;

        for (y = 0; y<h; y++) {

            for (x = 0; x<w; x++) {

                int v = rect->data[0][x + y*rect->linesize[0]];

                int l_m = list[v];

                int l_l = x     ? L(x-1, y) : 1;

                int l_r = x+1<w ? L(x+1, y) : 1;

                int l_t = y     ? L(x, y-1) : 1;

                int l_b = y+1<h ? L(x, y+1) : 1;

                int score;

                if (l_m)

                    continue;

                scoretab[v] += l_l + l_r + l_t + l_b;

                score = 1024LL*scoretab[v] / counttab[v];

                if (score > bestscore) {

                    bestscore = score;

                    bestv = v;

                }

            }

        }

        if (!bestscore)

            break;

        list    [ bestv ] = 1;

        list_inv[     i ] = bestv;

    }



    count = FFMAX(i - 1, 1);

    for (i--; i>=0; i--) {

        int v = i*255/count;

        AV_WN32(rect->data[1] + 4*list_inv[i], RGBA(v/2,v,v/2,v));

    }

}

static int seqvideo_decode(SeqVideoContext *seq, const unsigned char *data, int data_size)

{

    const unsigned char *data_end = data + data_size;

    GetBitContext gb;

    int flags, i, j, x, y, op;

    unsigned char c[3];

    unsigned char *dst;

    uint32_t *palette;



    flags = *data++;



    if (flags & 1) {

        palette = (uint32_t *)seq->frame.data[1];

        if (data_end - data < 256 * 3)

            return AVERROR_INVALIDDATA;

        for (i = 0; i < 256; i++) {

            for (j = 0; j < 3; j++, data++)

                c[j] = (*data << 2) | (*data >> 4);

            palette[i] = AV_RB24(c);

        }

        seq->frame.palette_has_changed = 1;

    }



    if (flags & 2) {

        if (data_end - data < 128)

            return AVERROR_INVALIDDATA;

        init_get_bits(&gb, data, 128 * 8); data += 128;

        for (y = 0; y < 128; y += 8)

            for (x = 0; x < 256; x += 8) {

                dst = &seq->frame.data[0][y * seq->frame.linesize[0] + x];

                op = get_bits(&gb, 2);

                switch (op) {

                case 1:

                    data = seq_decode_op1(seq, data, data_end, dst);

                    break;

                case 2:

                    data = seq_decode_op2(seq, data, data_end, dst);

                    break;

                case 3:

                    data = seq_decode_op3(seq, data, data_end, dst);

                    break;

                }

                if (!data)

                    return AVERROR_INVALIDDATA;

            }

    }

    return 0;

}

static void decode_block(BinkAudioContext *s, short *out, int use_dct)

{

    int ch, i, j, k;

    float q, quant[25];

    int width, coeff;

    GetBitContext *gb = &s->gb;



    if (use_dct)

        skip_bits(gb, 2);



    for (ch = 0; ch < s->channels; ch++) {

        FFTSample *coeffs = s->coeffs_ptr[ch];

        q = 0.0f;

        coeffs[0] = get_float(gb) * s->root;

        coeffs[1] = get_float(gb) * s->root;



        for (i = 0; i < s->num_bands; i++) {

            /* constant is result of 0.066399999/log10(M_E) */

            int value = get_bits(gb, 8);

            quant[i] = expf(FFMIN(value, 95) * 0.15289164787221953823f) * s->root;

        }



        // find band (k)

        for (k = 0; s->bands[k] < 1; k++) {

            q = quant[k];

        }



        // parse coefficients

        i = 2;

        while (i < s->frame_len) {

            if (get_bits1(gb)) {

                j = i + rle_length_tab[get_bits(gb, 4)] * 8;

            } else {

                j = i + 8;

            }



            j = FFMIN(j, s->frame_len);



            width = get_bits(gb, 4);

            if (width == 0) {

                memset(coeffs + i, 0, (j - i) * sizeof(*coeffs));

                i = j;

                while (s->bands[k] < i)

                    q = quant[k++];

            } else {

                while (i < j) {

                    if (s->bands[k] == i)

                        q = quant[k++];

                    coeff = get_bits(gb, width);

                    if (coeff) {

                        if (get_bits1(gb))

                            coeffs[i] = -q * coeff;

                        else

                            coeffs[i] =  q * coeff;

                    } else {

                        coeffs[i] = 0.0f;

                    }

                    i++;

                }

            }

        }



        if (CONFIG_BINKAUDIO_DCT_DECODER && use_dct) {

            coeffs[0] /= 0.5;

            ff_dct_calc (&s->trans.dct,  coeffs);

            s->dsp.vector_fmul_scalar(coeffs, coeffs, s->frame_len / 2, s->frame_len);

        }

        else if (CONFIG_BINKAUDIO_RDFT_DECODER)

            ff_rdft_calc(&s->trans.rdft, coeffs);

    }



    s->fmt_conv.float_to_int16_interleave(out, (const float **)s->coeffs_ptr,

                                          s->frame_len, s->channels);



    if (!s->first) {

        int count = s->overlap_len * s->channels;

        int shift = av_log2(count);

        for (i = 0; i < count; i++) {

            out[i] = (s->previous[i] * (count - i) + out[i] * i) >> shift;

        }

    }



    memcpy(s->previous, out + s->block_size,

           s->overlap_len * s->channels * sizeof(*out));



    s->first = 0;

}

static int img_read_packet(AVFormatContext *s1, AVPacket *pkt)

{

    VideoData *s = s1->priv_data;

    char filename[1024];

    int ret;

    ByteIOContext f1, *f;



    if (!s->is_pipe) {

        if (get_frame_filename(filename, sizeof(filename),

                               s->path, s->img_number) < 0)

            return -EIO;

        f = &f1;

        if (url_fopen(f, filename, URL_RDONLY) < 0)

            return -EIO;

    } else {

        f = &s1->pb;

        if (url_feof(f))

            return -EIO;

    }



    av_new_packet(pkt, s->img_size);

    pkt->stream_index = 0;



    s->ptr = pkt->data;

    ret = av_read_image(f, filename, s->img_fmt, read_packet_alloc_cb, s);

    if (!s->is_pipe) {

        url_fclose(f);

    }



    if (ret < 0) {

        av_free_packet(pkt);

        return -EIO; /* signal EOF */

    } else {

        pkt->pts = av_rescale((int64_t)s->img_number * s1->streams[0]->codec.frame_rate_base, s1->pts_den, s1->streams[0]->codec.frame_rate) / s1->pts_num;

        s->img_number++;

        return 0;

    }

}

static void store_slice_c(uint8_t *dst, const uint16_t *src,

                          int dst_linesize, int src_linesize,

                          int width, int height, int log2_scale,

                          const uint8_t dither[8][8])

{

    int y, x;



#define STORE(pos) do {                                                     \

    temp = ((src[x + y*src_linesize + pos] << log2_scale) + d[pos]) >> 6;   \

    if (temp & 0x100)                                                       \

        temp = ~(temp >> 31);                                               \

    dst[x + y*dst_linesize + pos] = temp;                                   \

} while (0)



    for (y = 0; y < height; y++) {

        const uint8_t *d = dither[y];

        for (x = 0; x < width; x += 8) {

            int temp;

            STORE(0);

            STORE(1);

            STORE(2);

            STORE(3);

            STORE(4);

            STORE(5);

            STORE(6);

            STORE(7);

        }

    }

}

static int cbs_mpeg2_read_unit(CodedBitstreamContext *ctx,

                               CodedBitstreamUnit *unit)

{

    BitstreamContext bc;

    int err;



    err = bitstream_init(&bc, unit->data, 8 * unit->data_size);

    if (err < 0)

        return err;



    if (MPEG2_START_IS_SLICE(unit->type)) {

        MPEG2RawSlice *slice;

        int pos, len;



        slice = av_mallocz(sizeof(*slice));

        if (!slice)

            return AVERROR(ENOMEM);

        err = cbs_mpeg2_read_slice_header(ctx, &bc, &slice->header);

        if (err < 0) {

            av_free(slice);

            return err;

        }



        pos = bitstream_tell(&bc);

        len = unit->data_size;



        slice->data_size = len - pos / 8;

        slice->data = av_malloc(slice->data_size);

        if (!slice->data) {

            av_free(slice);

            return AVERROR(ENOMEM);

        }



        memcpy(slice->data,

               unit->data + pos / 8, slice->data_size);

        slice->data_bit_start = pos % 8;



        unit->content = slice;



    } else {

        switch (unit->type) {

#define START(start_code, type, func) \

        case start_code: \

            { \

                type *header; \

                header = av_mallocz(sizeof(*header)); \

                if (!header) \

                    return AVERROR(ENOMEM); \

                err = cbs_mpeg2_read_ ## func(ctx, &bc, header); \

                if (err < 0) { \

                    av_free(header); \

                    return err; \

                } \

                unit->content = header; \

            } \

            break;

            START(0x00, MPEG2RawPictureHeader,  picture_header);

            START(0xb2, MPEG2RawUserData,       user_data);

            START(0xb3, MPEG2RawSequenceHeader, sequence_header);

            START(0xb5, MPEG2RawExtensionData,  extension_data);

            START(0xb8, MPEG2RawGroupOfPicturesHeader, group_of_pictures_header);

#undef START

        default:

            av_log(ctx->log_ctx, AV_LOG_ERROR, "Unknown start code %02x.\n",

                   unit->type);

            return AVERROR_INVALIDDATA;

        }

    }



    return 0;

}

static int scan_for_extensions(AVCodecContext *avctx)

{

    DCAContext *s = avctx->priv_data;

    int core_ss_end, ret;



    core_ss_end = FFMIN(s->frame_size, s->dca_buffer_size) * 8;



    /* only scan for extensions if ext_descr was unknown or indicated a

     * supported XCh extension */

    if (s->core_ext_mask < 0 || s->core_ext_mask & DCA_EXT_XCH) {

        /* if ext_descr was unknown, clear s->core_ext_mask so that the

         * extensions scan can fill it up */

        s->core_ext_mask = FFMAX(s->core_ext_mask, 0);



        /* extensions start at 32-bit boundaries into bitstream */

        skip_bits_long(&s->gb, (-get_bits_count(&s->gb)) & 31);



        while (core_ss_end - get_bits_count(&s->gb) >= 32) {

            uint32_t bits = get_bits_long(&s->gb, 32);

            int i;



            switch (bits) {

            case DCA_SYNCWORD_XCH: {

                int ext_amode, xch_fsize;



                s->xch_base_channel = s->prim_channels;



                /* validate sync word using XCHFSIZE field */

                xch_fsize = show_bits(&s->gb, 10);

                if ((s->frame_size != (get_bits_count(&s->gb) >> 3) - 4 + xch_fsize) &&

                    (s->frame_size != (get_bits_count(&s->gb) >> 3) - 4 + xch_fsize + 1))

                    continue;



                /* skip length-to-end-of-frame field for the moment */

                skip_bits(&s->gb, 10);



                s->core_ext_mask |= DCA_EXT_XCH;



                /* extension amode(number of channels in extension) should be 1 */

                /* AFAIK XCh is not used for more channels */

                if ((ext_amode = get_bits(&s->gb, 4)) != 1) {

                    av_log(avctx, AV_LOG_ERROR,

                           "XCh extension amode %d not supported!\n",

                           ext_amode);

                    continue;

                }



                /* much like core primary audio coding header */

                dca_parse_audio_coding_header(s, s->xch_base_channel);



                for (i = 0; i < (s->sample_blocks / 8); i++)

                    if ((ret = dca_decode_block(s, s->xch_base_channel, i))) {

                        av_log(avctx, AV_LOG_ERROR, "error decoding XCh extension\n");

                        continue;

                    }



                s->xch_present = 1;

                break;

            }

            case DCA_SYNCWORD_XXCH:

                /* XXCh: extended channels */

                /* usually found either in core or HD part in DTS-HD HRA streams,

                 * but not in DTS-ES which contains XCh extensions instead */

                s->core_ext_mask |= DCA_EXT_XXCH;

                break;



            case 0x1d95f262: {

                int fsize96 = show_bits(&s->gb, 12) + 1;

                if (s->frame_size != (get_bits_count(&s->gb) >> 3) - 4 + fsize96)

                    continue;



                av_log(avctx, AV_LOG_DEBUG, "X96 extension found at %d bits\n",

                       get_bits_count(&s->gb));

                skip_bits(&s->gb, 12);

                av_log(avctx, AV_LOG_DEBUG, "FSIZE96 = %d bytes\n", fsize96);

                av_log(avctx, AV_LOG_DEBUG, "REVNO = %d\n", get_bits(&s->gb, 4));



                s->core_ext_mask |= DCA_EXT_X96;

                break;

            }

            }



            skip_bits_long(&s->gb, (-get_bits_count(&s->gb)) & 31);

        }

    } else {

        /* no supported extensions, skip the rest of the core substream */

        skip_bits_long(&s->gb, core_ss_end - get_bits_count(&s->gb));

    }



    if (s->core_ext_mask & DCA_EXT_X96)

        s->profile = FF_PROFILE_DTS_96_24;

    else if (s->core_ext_mask & (DCA_EXT_XCH | DCA_EXT_XXCH))

        s->profile = FF_PROFILE_DTS_ES;



    /* check for ExSS (HD part) */

    if (s->dca_buffer_size - s->frame_size > 32 &&

        get_bits_long(&s->gb, 32) == DCA_SYNCWORD_SUBSTREAM)

        ff_dca_exss_parse_header(s);



    return ret;

}

static av_unused FFPsyWindowInfo psy_3gpp_window(FFPsyContext *ctx,

                                                 const int16_t *audio,

                                                 const int16_t *la,

                                                 int channel, int prev_type)

{

    int i, j;

    int br               = ctx->avctx->bit_rate / ctx->avctx->channels;

    int attack_ratio     = br <= 16000 ? 18 : 10;

    AacPsyContext *pctx = (AacPsyContext*) ctx->model_priv_data;

    AacPsyChannel *pch  = &pctx->ch[channel];

    uint8_t grouping     = 0;

    int next_type        = pch->next_window_seq;

    FFPsyWindowInfo wi  = { { 0 } };



    if (la) {

        float s[8], v;

        int switch_to_eight = 0;

        float sum = 0.0, sum2 = 0.0;

        int attack_n = 0;

        int stay_short = 0;

        for (i = 0; i < 8; i++) {

            for (j = 0; j < 128; j++) {

                v = iir_filter(la[i*128+j], pch->iir_state);

                sum += v*v;

            }

            s[i]  = sum;

            sum2 += sum;

        }

        for (i = 0; i < 8; i++) {

            if (s[i] > pch->win_energy * attack_ratio) {

                attack_n        = i + 1;

                switch_to_eight = 1;

                break;

            }

        }

        pch->win_energy = pch->win_energy*7/8 + sum2/64;



        wi.window_type[1] = prev_type;

        switch (prev_type) {

        case ONLY_LONG_SEQUENCE:

            wi.window_type[0] = switch_to_eight ? LONG_START_SEQUENCE : ONLY_LONG_SEQUENCE;

            next_type = switch_to_eight ? EIGHT_SHORT_SEQUENCE : ONLY_LONG_SEQUENCE;

            break;

        case LONG_START_SEQUENCE:

            wi.window_type[0] = EIGHT_SHORT_SEQUENCE;

            grouping = pch->next_grouping;

            next_type = switch_to_eight ? EIGHT_SHORT_SEQUENCE : LONG_STOP_SEQUENCE;

            break;

        case LONG_STOP_SEQUENCE:

            wi.window_type[0] = switch_to_eight ? LONG_START_SEQUENCE : ONLY_LONG_SEQUENCE;

            next_type = switch_to_eight ? EIGHT_SHORT_SEQUENCE : ONLY_LONG_SEQUENCE;

            break;

        case EIGHT_SHORT_SEQUENCE:

            stay_short = next_type == EIGHT_SHORT_SEQUENCE || switch_to_eight;

            wi.window_type[0] = stay_short ? EIGHT_SHORT_SEQUENCE : LONG_STOP_SEQUENCE;

            grouping = next_type == EIGHT_SHORT_SEQUENCE ? pch->next_grouping : 0;

            next_type = switch_to_eight ? EIGHT_SHORT_SEQUENCE : LONG_STOP_SEQUENCE;

            break;

        }



        pch->next_grouping = window_grouping[attack_n];

        pch->next_window_seq = next_type;

    } else {

        for (i = 0; i < 3; i++)

            wi.window_type[i] = prev_type;

        grouping = (prev_type == EIGHT_SHORT_SEQUENCE) ? window_grouping[0] : 0;

    }



    wi.window_shape   = 1;

    if (wi.window_type[0] != EIGHT_SHORT_SEQUENCE) {

        wi.num_windows = 1;

        wi.grouping[0] = 1;

    } else {

        int lastgrp = 0;

        wi.num_windows = 8;

        for (i = 0; i < 8; i++) {

            if (!((grouping >> i) & 1))

                lastgrp = i;

            wi.grouping[lastgrp]++;

        }

    }



    return wi;

}

static int rac_get_model_sym(RangeCoder *c, Model *m)

{

    int prob, prob2, helper, val;

    int end, end2;



    prob       = 0;

    prob2      = c->range;

    c->range >>= MODEL_SCALE;

    val        = 0;

    end        = m->num_syms >> 1;

    end2       = m->num_syms;

    do {

        helper = m->freqs[end] * c->range;

        if (helper <= c->low) {

            val   = end;

            prob  = helper;

        } else {

            end2  = end;

            prob2 = helper;

        }

        end = (end2 + val) >> 1;

    } while (end != val);

    c->low  -= prob;

    c->range = prob2 - prob;

    if (c->range < RAC_BOTTOM)

        rac_normalise(c);



    model_update(m, val);



    return val;

}

static int dvbsub_display_end_segment(AVCodecContext *avctx, const uint8_t *buf,

                                        int buf_size, AVSubtitle *sub)

{

    DVBSubContext *ctx = avctx->priv_data;

    DVBSubDisplayDefinition *display_def = ctx->display_definition;



    DVBSubRegion *region;

    DVBSubRegionDisplay *display;

    AVSubtitleRect *rect;

    DVBSubCLUT *clut;

    uint32_t *clut_table;

    int i;

    int offset_x=0, offset_y=0;



    sub->end_display_time = ctx->time_out * 1000;



    if (display_def) {

        offset_x = display_def->x;

        offset_y = display_def->y;

    }



    sub->num_rects = ctx->display_list_size;



    if (sub->num_rects > 0){

        sub->rects = av_mallocz(sizeof(*sub->rects) * sub->num_rects);

        for(i=0; i<sub->num_rects; i++)

            sub->rects[i] = av_mallocz(sizeof(*sub->rects[i]));



    i = 0;



    for (display = ctx->display_list; display; display = display->next) {

        region = get_region(ctx, display->region_id);



        if (!region)

            continue;



        if (!region->dirty)

            continue;



        rect = sub->rects[i];

        rect->x = display->x_pos + offset_x;

        rect->y = display->y_pos + offset_y;

        rect->w = region->width;

        rect->h = region->height;

        rect->nb_colors = (1 << region->depth);

        rect->type      = SUBTITLE_BITMAP;

        rect->pict.linesize[0] = region->width;



        clut = get_clut(ctx, region->clut);



        if (!clut)

            clut = &default_clut;



        switch (region->depth) {

        case 2:

            clut_table = clut->clut4;

            break;

        case 8:

            clut_table = clut->clut256;

            break;

        case 4:

        default:

            clut_table = clut->clut16;

            break;

        }



        rect->pict.data[1] = av_mallocz(AVPALETTE_SIZE);

        memcpy(rect->pict.data[1], clut_table, (1 << region->depth) * sizeof(uint32_t));



        rect->pict.data[0] = av_malloc(region->buf_size);

        memcpy(rect->pict.data[0], region->pbuf, region->buf_size);



        i++;

    }



    sub->num_rects = i;

    }

#ifdef DEBUG

    save_display_set(ctx);

#endif



    return 1;

}

static av_always_inline void hl_decode_mb_internal(H264Context *h, int simple){

    MpegEncContext * const s = &h->s;

    const int mb_x= s->mb_x;

    const int mb_y= s->mb_y;

    const int mb_xy= mb_x + mb_y*s->mb_stride;

    const int mb_type= s->current_picture.mb_type[mb_xy];

    uint8_t  *dest_y, *dest_cb, *dest_cr;

    int linesize, uvlinesize /*dct_offset*/;

    int i;

    int *block_offset = &h->block_offset[0];

    const unsigned int bottom = mb_y & 1;

    const int transform_bypass = (s->qscale == 0 && h->sps.transform_bypass), is_h264 = (simple || s->codec_id == CODEC_ID_H264);

    void (*idct_add)(uint8_t *dst, DCTELEM *block, int stride);

    void (*idct_dc_add)(uint8_t *dst, DCTELEM *block, int stride);



    dest_y  = s->current_picture.data[0] + (mb_y * 16* s->linesize  ) + mb_x * 16;

    dest_cb = s->current_picture.data[1] + (mb_y * 8 * s->uvlinesize) + mb_x * 8;

    dest_cr = s->current_picture.data[2] + (mb_y * 8 * s->uvlinesize) + mb_x * 8;



    s->dsp.prefetch(dest_y + (s->mb_x&3)*4*s->linesize + 64, s->linesize, 4);

    s->dsp.prefetch(dest_cb + (s->mb_x&7)*s->uvlinesize + 64, dest_cr - dest_cb, 2);



    if (!simple && MB_FIELD) {

        linesize   = h->mb_linesize   = s->linesize * 2;

        uvlinesize = h->mb_uvlinesize = s->uvlinesize * 2;

        block_offset = &h->block_offset[24];

        if(mb_y&1){ //FIXME move out of this func?

            dest_y -= s->linesize*15;

            dest_cb-= s->uvlinesize*7;

            dest_cr-= s->uvlinesize*7;

        }

        if(FRAME_MBAFF) {

            int list;

            for(list=0; list<h->list_count; list++){

                if(!USES_LIST(mb_type, list))

                    continue;

                if(IS_16X16(mb_type)){

                    int8_t *ref = &h->ref_cache[list][scan8[0]];

                    fill_rectangle(ref, 4, 4, 8, 16+*ref^(s->mb_y&1), 1);

                }else{

                    for(i=0; i<16; i+=4){

                        //FIXME can refs be smaller than 8x8 when !direct_8x8_inference ?

                        int ref = h->ref_cache[list][scan8[i]];

                        if(ref >= 0)

                            fill_rectangle(&h->ref_cache[list][scan8[i]], 2, 2, 8, 16+ref^(s->mb_y&1), 1);

                    }

                }

            }

        }

    } else {

        linesize   = h->mb_linesize   = s->linesize;

        uvlinesize = h->mb_uvlinesize = s->uvlinesize;

//        dct_offset = s->linesize * 16;

    }



    if(transform_bypass){

        idct_dc_add =

        idct_add = IS_8x8DCT(mb_type) ? s->dsp.add_pixels8 : s->dsp.add_pixels4;

    }else if(IS_8x8DCT(mb_type)){

        idct_dc_add = s->dsp.h264_idct8_dc_add;

        idct_add = s->dsp.h264_idct8_add;

    }else{

        idct_dc_add = s->dsp.h264_idct_dc_add;

        idct_add = s->dsp.h264_idct_add;

    }



    if(!simple && FRAME_MBAFF && h->deblocking_filter && IS_INTRA(mb_type)

       && (!bottom || !IS_INTRA(s->current_picture.mb_type[mb_xy-s->mb_stride]))){

        int mbt_y = mb_y&~1;

        uint8_t *top_y  = s->current_picture.data[0] + (mbt_y * 16* s->linesize  ) + mb_x * 16;

        uint8_t *top_cb = s->current_picture.data[1] + (mbt_y * 8 * s->uvlinesize) + mb_x * 8;

        uint8_t *top_cr = s->current_picture.data[2] + (mbt_y * 8 * s->uvlinesize) + mb_x * 8;

        xchg_pair_border(h, top_y, top_cb, top_cr, s->linesize, s->uvlinesize, 1);

    }



    if (!simple && IS_INTRA_PCM(mb_type)) {

        unsigned int x, y;



        // The pixels are stored in h->mb array in the same order as levels,

        // copy them in output in the correct order.

        for(i=0; i<16; i++) {

            for (y=0; y<4; y++) {

                for (x=0; x<4; x++) {

                    *(dest_y + block_offset[i] + y*linesize + x) = h->mb[i*16+y*4+x];

                }

            }

        }

        for(i=16; i<16+4; i++) {

            for (y=0; y<4; y++) {

                for (x=0; x<4; x++) {

                    *(dest_cb + block_offset[i] + y*uvlinesize + x) = h->mb[i*16+y*4+x];

                }

            }

        }

        for(i=20; i<20+4; i++) {

            for (y=0; y<4; y++) {

                for (x=0; x<4; x++) {

                    *(dest_cr + block_offset[i] + y*uvlinesize + x) = h->mb[i*16+y*4+x];

                }

            }

        }

    } else {

        if(IS_INTRA(mb_type)){

            if(h->deblocking_filter && (simple || !FRAME_MBAFF))

                xchg_mb_border(h, dest_y, dest_cb, dest_cr, linesize, uvlinesize, 1, simple);



            if(simple || !(s->flags&CODEC_FLAG_GRAY)){

                h->pred8x8[ h->chroma_pred_mode ](dest_cb, uvlinesize);

                h->pred8x8[ h->chroma_pred_mode ](dest_cr, uvlinesize);

            }



            if(IS_INTRA4x4(mb_type)){

                if(simple || !s->encoding){

                    if(IS_8x8DCT(mb_type)){

                        for(i=0; i<16; i+=4){

                            uint8_t * const ptr= dest_y + block_offset[i];

                            const int dir= h->intra4x4_pred_mode_cache[ scan8[i] ];

                            const int nnz = h->non_zero_count_cache[ scan8[i] ];

                            h->pred8x8l[ dir ](ptr, (h->topleft_samples_available<<i)&0x8000,

                                                   (h->topright_samples_available<<i)&0x4000, linesize);

                            if(nnz){

                                if(nnz == 1 && h->mb[i*16])

                                    idct_dc_add(ptr, h->mb + i*16, linesize);

                                else

                                    idct_add(ptr, h->mb + i*16, linesize);

                            }

                        }

                    }else

                    for(i=0; i<16; i++){

                        uint8_t * const ptr= dest_y + block_offset[i];

                        uint8_t *topright;

                        const int dir= h->intra4x4_pred_mode_cache[ scan8[i] ];

                        int nnz, tr;



                        if(dir == DIAG_DOWN_LEFT_PRED || dir == VERT_LEFT_PRED){

                            const int topright_avail= (h->topright_samples_available<<i)&0x8000;

                            assert(mb_y || linesize <= block_offset[i]);

                            if(!topright_avail){

                                tr= ptr[3 - linesize]*0x01010101;

                                topright= (uint8_t*) &tr;

                            }else

                                topright= ptr + 4 - linesize;

                        }else

                            topright= NULL;



                        h->pred4x4[ dir ](ptr, topright, linesize);

                        nnz = h->non_zero_count_cache[ scan8[i] ];

                        if(nnz){

                            if(is_h264){

                                if(nnz == 1 && h->mb[i*16])

                                    idct_dc_add(ptr, h->mb + i*16, linesize);

                                else

                                    idct_add(ptr, h->mb + i*16, linesize);

                            }else

                                svq3_add_idct_c(ptr, h->mb + i*16, linesize, s->qscale, 0);

                        }

                    }

                }

            }else{

                h->pred16x16[ h->intra16x16_pred_mode ](dest_y , linesize);

                if(is_h264){

                    if(!transform_bypass)

                        h264_luma_dc_dequant_idct_c(h->mb, s->qscale, h->dequant4_coeff[IS_INTRA(mb_type) ? 0:3][s->qscale][0]);

                }else

                    svq3_luma_dc_dequant_idct_c(h->mb, s->qscale);

            }

            if(h->deblocking_filter && (simple || !FRAME_MBAFF))

                xchg_mb_border(h, dest_y, dest_cb, dest_cr, linesize, uvlinesize, 0, simple);

        }else if(is_h264){

            hl_motion(h, dest_y, dest_cb, dest_cr,

                      s->me.qpel_put, s->dsp.put_h264_chroma_pixels_tab,

                      s->me.qpel_avg, s->dsp.avg_h264_chroma_pixels_tab,

                      s->dsp.weight_h264_pixels_tab, s->dsp.biweight_h264_pixels_tab);

        }





        if(!IS_INTRA4x4(mb_type)){

            if(is_h264){

                if(IS_INTRA16x16(mb_type)){

                    for(i=0; i<16; i++){

                        if(h->non_zero_count_cache[ scan8[i] ])

                            idct_add(dest_y + block_offset[i], h->mb + i*16, linesize);

                        else if(h->mb[i*16])

                            idct_dc_add(dest_y + block_offset[i], h->mb + i*16, linesize);

                    }

                }else{

                    const int di = IS_8x8DCT(mb_type) ? 4 : 1;

                    for(i=0; i<16; i+=di){

                        int nnz = h->non_zero_count_cache[ scan8[i] ];

                        if(nnz){

                            if(nnz==1 && h->mb[i*16])

                                idct_dc_add(dest_y + block_offset[i], h->mb + i*16, linesize);

                            else

                                idct_add(dest_y + block_offset[i], h->mb + i*16, linesize);

                        }

                    }

                }

            }else{

                for(i=0; i<16; i++){

                    if(h->non_zero_count_cache[ scan8[i] ] || h->mb[i*16]){ //FIXME benchmark weird rule, & below

                        uint8_t * const ptr= dest_y + block_offset[i];

                        svq3_add_idct_c(ptr, h->mb + i*16, linesize, s->qscale, IS_INTRA(mb_type) ? 1 : 0);

                    }

                }

            }

        }



        if(simple || !(s->flags&CODEC_FLAG_GRAY)){

            uint8_t *dest[2] = {dest_cb, dest_cr};

            if(transform_bypass){

                idct_add = idct_dc_add = s->dsp.add_pixels4;

            }else{

                idct_add = s->dsp.h264_idct_add;

                idct_dc_add = s->dsp.h264_idct_dc_add;

                chroma_dc_dequant_idct_c(h->mb + 16*16, h->chroma_qp, h->dequant4_coeff[IS_INTRA(mb_type) ? 1:4][h->chroma_qp][0]);

                chroma_dc_dequant_idct_c(h->mb + 16*16+4*16, h->chroma_qp, h->dequant4_coeff[IS_INTRA(mb_type) ? 2:5][h->chroma_qp][0]);

            }

            if(is_h264){

                for(i=16; i<16+8; i++){

                    if(h->non_zero_count_cache[ scan8[i] ])

                        idct_add(dest[(i&4)>>2] + block_offset[i], h->mb + i*16, uvlinesize);

                    else if(h->mb[i*16])

                        idct_dc_add(dest[(i&4)>>2] + block_offset[i], h->mb + i*16, uvlinesize);

                }

            }else{

                for(i=16; i<16+8; i++){

                    if(h->non_zero_count_cache[ scan8[i] ] || h->mb[i*16]){

                        uint8_t * const ptr= dest[(i&4)>>2] + block_offset[i];

                        svq3_add_idct_c(ptr, h->mb + i*16, uvlinesize, chroma_qp[s->qscale + 12] - 12, 2);

                    }

                }

            }

        }

    }

    if(h->deblocking_filter) {

        if (!simple && FRAME_MBAFF) {

            //FIXME try deblocking one mb at a time?

            // the reduction in load/storing mvs and such might outweigh the extra backup/xchg_border

            const int mb_y = s->mb_y - 1;

            uint8_t  *pair_dest_y, *pair_dest_cb, *pair_dest_cr;

            const int mb_xy= mb_x + mb_y*s->mb_stride;

            const int mb_type_top   = s->current_picture.mb_type[mb_xy];

            const int mb_type_bottom= s->current_picture.mb_type[mb_xy+s->mb_stride];

            if (!bottom) return;

            pair_dest_y  = s->current_picture.data[0] + (mb_y * 16* s->linesize  ) + mb_x * 16;

            pair_dest_cb = s->current_picture.data[1] + (mb_y * 8 * s->uvlinesize) + mb_x * 8;

            pair_dest_cr = s->current_picture.data[2] + (mb_y * 8 * s->uvlinesize) + mb_x * 8;



            if(IS_INTRA(mb_type_top | mb_type_bottom))

                xchg_pair_border(h, pair_dest_y, pair_dest_cb, pair_dest_cr, s->linesize, s->uvlinesize, 0);



            backup_pair_border(h, pair_dest_y, pair_dest_cb, pair_dest_cr, s->linesize, s->uvlinesize);

            // deblock a pair

            // top

            s->mb_y--;

            tprintf(h->s.avctx, "call mbaff filter_mb mb_x:%d mb_y:%d pair_dest_y = %p, dest_y = %p\n", mb_x, mb_y, pair_dest_y, dest_y);

            fill_caches(h, mb_type_top, 1); //FIXME don't fill stuff which isn't used by filter_mb

            h->chroma_qp = get_chroma_qp(h, s->current_picture.qscale_table[mb_xy]);

            filter_mb(h, mb_x, mb_y, pair_dest_y, pair_dest_cb, pair_dest_cr, linesize, uvlinesize);

            // bottom

            s->mb_y++;

            tprintf(h->s.avctx, "call mbaff filter_mb\n");

            fill_caches(h, mb_type_bottom, 1); //FIXME don't fill stuff which isn't used by filter_mb

            h->chroma_qp = get_chroma_qp(h, s->current_picture.qscale_table[mb_xy+s->mb_stride]);

            filter_mb(h, mb_x, mb_y+1, dest_y, dest_cb, dest_cr, linesize, uvlinesize);

        } else {

            tprintf(h->s.avctx, "call filter_mb\n");

            backup_mb_border(h, dest_y, dest_cb, dest_cr, linesize, uvlinesize, simple);

            fill_caches(h, mb_type, 1); //FIXME don't fill stuff which isn't used by filter_mb

            filter_mb_fast(h, mb_x, mb_y, dest_y, dest_cb, dest_cr, linesize, uvlinesize);

        }

    }

}

static int read_len_table(uint8_t *dst, GetBitContext *gb){

    int i, val, repeat;



    for(i=0; i<256;){

        repeat= get_bits(gb, 3);

        val   = get_bits(gb, 5);

        if(repeat==0)

            repeat= get_bits(gb, 8);

//printf("%d %d\n", val, repeat);

        if(i+repeat > 256) {

            av_log(NULL, AV_LOG_ERROR, "Error reading huffman table\n");

            return -1;

        }

        while (repeat--)

            dst[i++] = val;

    }

    return 0;

}

void ff_ivi_inverse_haar_4x4(const int32_t *in, int16_t *out, ptrdiff_t pitch,

                             const uint8_t *flags)

{

    int     i, shift, sp1, sp2;

    const int32_t *src;

    int32_t *dst;

    int     tmp[16];

    int     t0, t1, t2, t3, t4;



    /* apply the InvHaar4 to all columns */

#define COMPENSATE(x) (x)

    src = in;

    dst = tmp;

    for (i = 0; i < 4; i++) {

        if (flags[i]) {

            /* pre-scaling */

            shift = !(i & 2);

            sp1 = src[0] << shift;

            sp2 = src[4] << shift;

            INV_HAAR4(   sp1,    sp2, src[8], src[12],

                      dst[0], dst[4], dst[8], dst[12],

                      t0, t1, t2, t3, t4);

        } else

            dst[0] = dst[4] = dst[8] = dst[12] = 0;



        src++;

        dst++;

    }

#undef  COMPENSATE



    /* apply the InvHaar8 to all rows */

#define COMPENSATE(x) (x)

    src = tmp;

    for (i = 0; i < 4; i++) {

        if (!src[0] && !src[1] && !src[2] && !src[3]) {

            memset(out, 0, 4 * sizeof(out[0]));

        } else {

            INV_HAAR4(src[0], src[1], src[2], src[3],

                      out[0], out[1], out[2], out[3],

                      t0, t1, t2, t3, t4);

        }

        src += 4;

        out += pitch;

    }

#undef  COMPENSATE

}

static int submit_packet(PerThreadContext *p, AVPacket *avpkt)

{

    FrameThreadContext *fctx = p->parent;

    PerThreadContext *prev_thread = fctx->prev_thread;

    const AVCodec *codec = p->avctx->codec;



    if (!avpkt->size && !(codec->capabilities & AV_CODEC_CAP_DELAY))

        return 0;



    pthread_mutex_lock(&p->mutex);



    release_delayed_buffers(p);



    if (prev_thread) {

        int err;

        if (prev_thread->state == STATE_SETTING_UP) {

            pthread_mutex_lock(&prev_thread->progress_mutex);

            while (prev_thread->state == STATE_SETTING_UP)

                pthread_cond_wait(&prev_thread->progress_cond, &prev_thread->progress_mutex);

            pthread_mutex_unlock(&prev_thread->progress_mutex);

        }



        err = update_context_from_thread(p->avctx, prev_thread->avctx, 0);

        if (err) {

            pthread_mutex_unlock(&p->mutex);

            return err;

        }

    }



    av_packet_unref(&p->avpkt);

    av_packet_ref(&p->avpkt, avpkt);



    p->state = STATE_SETTING_UP;

    pthread_cond_signal(&p->input_cond);

    pthread_mutex_unlock(&p->mutex);



    /*

     * If the client doesn't have a thread-safe get_buffer(),

     * then decoding threads call back to the main thread,

     * and it calls back to the client here.

     */



    if (!p->avctx->thread_safe_callbacks && (

         p->avctx->get_format != avcodec_default_get_format ||

         p->avctx->get_buffer2 != avcodec_default_get_buffer2)) {

        while (p->state != STATE_SETUP_FINISHED && p->state != STATE_INPUT_READY) {

            int call_done = 1;

            pthread_mutex_lock(&p->progress_mutex);

            while (p->state == STATE_SETTING_UP)

                pthread_cond_wait(&p->progress_cond, &p->progress_mutex);



            switch (p->state) {

            case STATE_GET_BUFFER:

                p->result = ff_get_buffer(p->avctx, p->requested_frame, p->requested_flags);

                break;

            case STATE_GET_FORMAT:

                p->result_format = ff_get_format(p->avctx, p->available_formats);

                break;

            default:

                call_done = 0;

                break;

            }

            if (call_done) {

                p->state  = STATE_SETTING_UP;

                pthread_cond_signal(&p->progress_cond);

            }

            pthread_mutex_unlock(&p->progress_mutex);

        }

    }



    fctx->prev_thread = p;

    fctx->next_decoding++;



    return 0;

}

static int ty_read_packet(AVFormatContext *s, AVPacket *pkt)

{

    TYDemuxContext *ty = s->priv_data;

    AVIOContext *pb = s->pb;

    TyRecHdr *rec;

    int64_t rec_size = 0;

    int ret = 0;



    if (avio_feof(pb))

        return AVERROR_EOF;



    while (ret <= 0) {

        if (ty->first_chunk || ty->cur_rec >= ty->num_recs) {

            if (get_chunk(s) < 0 || ty->num_recs == 0)

                return AVERROR_EOF;

        }



        rec = &ty->rec_hdrs[ty->cur_rec];

        rec_size = rec->rec_size;

        ty->cur_rec++;



        if (rec_size <= 0)

            continue;



        if (ty->cur_chunk_pos + rec->rec_size > CHUNK_SIZE)

            return AVERROR_INVALIDDATA;



        if (avio_feof(pb))

            return AVERROR_EOF;



        switch (rec->rec_type) {

        case VIDEO_ID:

            ret = demux_video(s, rec, pkt);

            break;

        case AUDIO_ID:

            ret = demux_audio(s, rec, pkt);

            break;

        default:

            ff_dlog(s, "Invalid record type 0x%02x\n", rec->rec_type);

        case 0x01:

        case 0x02:

        case 0x03: /* TiVo data services */

        case 0x05: /* unknown, but seen regularly */

            ty->cur_chunk_pos += rec->rec_size;

            break;

        }

    }



    return 0;

}

static int lag_decode_frame(AVCodecContext *avctx,

                            void *data, int *data_size, AVPacket *avpkt)

{

    const uint8_t *buf = avpkt->data;

    int buf_size = avpkt->size;

    LagarithContext *l = avctx->priv_data;

    AVFrame *const p = &l->picture;

    uint8_t frametype = 0;

    uint32_t offset_gu = 0, offset_bv = 0, offset_ry = 9;

    int offs[4];

    uint8_t *srcs[4], *dst;

    int i, j, planes = 3;



    AVFrame *picture = data;



    if (p->data[0])

        avctx->release_buffer(avctx, p);



    p->reference = 0;

    p->key_frame = 1;



    frametype = buf[0];



    offset_gu = AV_RL32(buf + 1);

    offset_bv = AV_RL32(buf + 5);



    switch (frametype) {

    case FRAME_SOLID_RGBA:

        avctx->pix_fmt = PIX_FMT_RGB32;



        if (avctx->get_buffer(avctx, p) < 0) {

            av_log(avctx, AV_LOG_ERROR, "get_buffer() failed\n");

            return -1;

        }



        dst = p->data[0];

        for (j = 0; j < avctx->height; j++) {

            for (i = 0; i < avctx->width; i++)

                AV_WN32(dst + i * 4, offset_gu);

            dst += p->linesize[0];

        }

        break;

    case FRAME_ARITH_RGBA:

        avctx->pix_fmt = PIX_FMT_RGB32;

        planes = 4;

        offset_ry += 4;

        offs[3] = AV_RL32(buf + 9);

    case FRAME_ARITH_RGB24:

        if (frametype == FRAME_ARITH_RGB24)

            avctx->pix_fmt = PIX_FMT_RGB24;



        if (avctx->get_buffer(avctx, p) < 0) {

            av_log(avctx, AV_LOG_ERROR, "get_buffer() failed\n");

            return -1;

        }



        offs[0] = offset_bv;

        offs[1] = offset_gu;

        offs[2] = offset_ry;



        if (!l->rgb_planes) {

            l->rgb_stride = FFALIGN(avctx->width, 16);

            l->rgb_planes = av_malloc(l->rgb_stride * avctx->height * planes + 16);

            if (!l->rgb_planes) {

                av_log(avctx, AV_LOG_ERROR, "cannot allocate temporary buffer\n");

                return AVERROR(ENOMEM);

            }

        }

        for (i = 0; i < planes; i++)

            srcs[i] = l->rgb_planes + (i + 1) * l->rgb_stride * avctx->height - l->rgb_stride;

        for (i = 0; i < planes; i++)

            lag_decode_arith_plane(l, srcs[i],

                                   avctx->width, avctx->height,

                                   -l->rgb_stride, buf + offs[i],

                                   buf_size);

        dst = p->data[0];

        for (i = 0; i < planes; i++)

            srcs[i] = l->rgb_planes + i * l->rgb_stride * avctx->height;

        for (j = 0; j < avctx->height; j++) {

            for (i = 0; i < avctx->width; i++) {

                uint8_t r, g, b, a;

                r = srcs[0][i];

                g = srcs[1][i];

                b = srcs[2][i];

                r += g;

                b += g;

                if (frametype == FRAME_ARITH_RGBA) {

                    a = srcs[3][i];

                    AV_WN32(dst + i * 4, MKBETAG(a, r, g, b));

                } else {

                    dst[i * 3 + 0] = r;

                    dst[i * 3 + 1] = g;

                    dst[i * 3 + 2] = b;

                }

            }

            dst += p->linesize[0];

            for (i = 0; i < planes; i++)

                srcs[i] += l->rgb_stride;

        }

        break;

    case FRAME_ARITH_YV12:

        avctx->pix_fmt = PIX_FMT_YUV420P;



        if (avctx->get_buffer(avctx, p) < 0) {

            av_log(avctx, AV_LOG_ERROR, "get_buffer() failed\n");

            return -1;

        }



        lag_decode_arith_plane(l, p->data[0], avctx->width, avctx->height,

                               p->linesize[0], buf + offset_ry,

                               buf_size);

        lag_decode_arith_plane(l, p->data[2], avctx->width / 2,

                               avctx->height / 2, p->linesize[2],

                               buf + offset_gu, buf_size);

        lag_decode_arith_plane(l, p->data[1], avctx->width / 2,

                               avctx->height / 2, p->linesize[1],

                               buf + offset_bv, buf_size);

        break;

    default:

        av_log(avctx, AV_LOG_ERROR,

               "Unsupported Lagarith frame type: %#x\n", frametype);

        return -1;

    }



    *picture = *p;

    *data_size = sizeof(AVFrame);



    return buf_size;

}

static inline int check_for_slice(AVSContext *h) {

    GetBitContext *gb = &h->s.gb;

    int align;



    if(h->mbx)

        return 0;

    align = (-get_bits_count(gb)) & 7;

    /* check for stuffing byte */

    if(!align && (show_bits(gb,8) == 0x80))

        get_bits(gb,8);

    if((show_bits_long(gb,24+align) & 0xFFFFFF) == 0x000001) {

        skip_bits_long(gb,24+align);

        h->stc = get_bits(gb,8);

        decode_slice_header(h,gb);

        return 1;

    }

    return 0;

}

static int decode_display_orientation(H264Context *h)

{

    h->sei_display_orientation_present = !get_bits1(&h->gb);



    if (h->sei_display_orientation_present) {

        h->sei_hflip = get_bits1(&h->gb);     // hor_flip

        h->sei_vflip = get_bits1(&h->gb);     // ver_flip



        h->sei_anticlockwise_rotation = get_bits(&h->gb, 16);

        get_ue_golomb(&h->gb);  // display_orientation_repetition_period

        skip_bits1(&h->gb);     // display_orientation_extension_flag

    }



    return 0;

}

static int init_image(TiffContext *s)

{

    int i, ret;

    uint32_t *pal;



    switch (s->bpp * 10 + s->bppcount) {

    case 11:

        if (!s->palette_is_set) {

            s->avctx->pix_fmt = AV_PIX_FMT_MONOBLACK;

            break;

        }

    case 21:

    case 41:

    case 81:

        s->avctx->pix_fmt = AV_PIX_FMT_PAL8;

        break;

    case 243:

        s->avctx->pix_fmt = AV_PIX_FMT_RGB24;

        break;

    case 161:

        s->avctx->pix_fmt = s->le ? AV_PIX_FMT_GRAY16LE : AV_PIX_FMT_GRAY16BE;

        break;

    case 162:

        s->avctx->pix_fmt = AV_PIX_FMT_GRAY8A;

        break;

    case 324:

        s->avctx->pix_fmt = AV_PIX_FMT_RGBA;

        break;

    case 483:

        s->avctx->pix_fmt = s->le ? AV_PIX_FMT_RGB48LE : AV_PIX_FMT_RGB48BE;

        break;

    case 644:

        s->avctx->pix_fmt = s->le ? AV_PIX_FMT_RGBA64LE : AV_PIX_FMT_RGBA64BE;

        break;

    default:

        av_log(s->avctx, AV_LOG_ERROR,

               "This format is not supported (bpp=%d, bppcount=%d)\n",

               s->bpp, s->bppcount);

        return AVERROR_INVALIDDATA;

    }

    if (s->width != s->avctx->width || s->height != s->avctx->height) {

        if ((ret = av_image_check_size(s->width, s->height, 0, s->avctx)) < 0)

            return ret;

        avcodec_set_dimensions(s->avctx, s->width, s->height);

    }

    if (s->picture.data[0])

        s->avctx->release_buffer(s->avctx, &s->picture);

    if ((ret = s->avctx->get_buffer(s->avctx, &s->picture)) < 0) {

        av_log(s->avctx, AV_LOG_ERROR, "get_buffer() failed\n");

        return ret;

    }

    if (s->avctx->pix_fmt == AV_PIX_FMT_PAL8) {

        if (s->palette_is_set) {

            memcpy(s->picture.data[1], s->palette, sizeof(s->palette));

        } else {

            /* make default grayscale pal */

            pal = (uint32_t *) s->picture.data[1];

            for (i = 0; i < 1<<s->bpp; i++)

                pal[i] = 0xFF << 24 | i * 255 / ((1<<s->bpp) - 1) * 0x010101;

        }

    }

    return 0;

}

static int h261_decode_gob_header(H261Context *h)

{

    unsigned int val;

    MpegEncContext *const s = &h->s;



    if (!h->gob_start_code_skipped) {

        /* Check for GOB Start Code */

        val = show_bits(&s->gb, 15);

        if (val)

            return -1;



        /* We have a GBSC */

        skip_bits(&s->gb, 16);

    }



    h->gob_start_code_skipped = 0;



    h->gob_number = get_bits(&s->gb, 4); /* GN */

    s->qscale     = get_bits(&s->gb, 5); /* GQUANT */



    /* Check if gob_number is valid */

    if (s->mb_height == 18) { // CIF

        if ((h->gob_number <= 0) || (h->gob_number > 12))

            return -1;

    } else { // QCIF

        if ((h->gob_number != 1) && (h->gob_number != 3) &&

            (h->gob_number != 5))

            return -1;

    }



    /* GEI */

    while (get_bits1(&s->gb) != 0)

        skip_bits(&s->gb, 8);



    if (s->qscale == 0) {

        av_log(s->avctx, AV_LOG_ERROR, "qscale has forbidden 0 value\n");

        if (s->avctx->err_recognition & (AV_EF_BITSTREAM | AV_EF_COMPLIANT))

            return -1;

    }



    /* For the first transmitted macroblock in a GOB, MBA is the absolute

     * address. For subsequent macroblocks, MBA is the difference between

     * the absolute addresses of the macroblock and the last transmitted

     * macroblock. */

    h->current_mba = 0;

    h->mba_diff    = 0;



    return 0;

}

static int has_decode_delay_been_guessed(AVStream *st)

{

    return st->codec->codec_id != CODEC_ID_H264 ||

        st->codec_info_nb_frames >= 6 + st->codec->has_b_frames;

}

static int64_t scene_sad8(FrameRateContext *s, uint8_t *p1, int p1_linesize, uint8_t* p2, int p2_linesize, int height)

{

    int64_t sad;

    int x, y;

    for (sad = y = 0; y < height; y += 8) {

        for (x = 0; x < p1_linesize; x += 8) {

            sad += s->sad(p1 + y * p1_linesize + x,

                          p1_linesize,

                          p2 + y * p2_linesize + x,

                          p2_linesize);

        }

    }

    emms_c();

    return sad;

}

static inline void FUNC(idctRowCondDC)(DCTELEM *row)

{

    int a0, a1, a2, a3, b0, b1, b2, b3;



#if HAVE_FAST_64BIT

#define ROW0_MASK (0xffffLL << 48 * HAVE_BIGENDIAN)

    if (((((uint64_t *)row)[0] & ~ROW0_MASK) | ((uint64_t *)row)[1]) == 0) {

        uint64_t temp = (row[0] << DC_SHIFT) & 0xffff;

        temp += temp << 16;

        temp += temp << 32;

        ((uint64_t *)row)[0] = temp;

        ((uint64_t *)row)[1] = temp;

        return;

    }

#else

    if (!(((uint32_t*)row)[1] |

          ((uint32_t*)row)[2] |

          ((uint32_t*)row)[3] |

          row[1])) {

        uint32_t temp = (row[0] << DC_SHIFT) & 0xffff;

        temp += temp << 16;

        ((uint32_t*)row)[0]=((uint32_t*)row)[1] =

            ((uint32_t*)row)[2]=((uint32_t*)row)[3] = temp;

        return;

    }

#endif



    a0 = (W4 * row[0]) + (1 << (ROW_SHIFT - 1));

    a1 = a0;

    a2 = a0;

    a3 = a0;



    a0 += W2 * row[2];

    a1 += W6 * row[2];

    a2 -= W6 * row[2];

    a3 -= W2 * row[2];



    b0 = MUL(W1, row[1]);

    MAC(b0, W3, row[3]);

    b1 = MUL(W3, row[1]);

    MAC(b1, -W7, row[3]);

    b2 = MUL(W5, row[1]);

    MAC(b2, -W1, row[3]);

    b3 = MUL(W7, row[1]);

    MAC(b3, -W5, row[3]);



    if (AV_RN64A(row + 4)) {

        a0 +=   W4*row[4] + W6*row[6];

        a1 += - W4*row[4] - W2*row[6];

        a2 += - W4*row[4] + W2*row[6];

        a3 +=   W4*row[4] - W6*row[6];



        MAC(b0,  W5, row[5]);

        MAC(b0,  W7, row[7]);



        MAC(b1, -W1, row[5]);

        MAC(b1, -W5, row[7]);



        MAC(b2,  W7, row[5]);

        MAC(b2,  W3, row[7]);



        MAC(b3,  W3, row[5]);

        MAC(b3, -W1, row[7]);

    }



    row[0] = (a0 + b0) >> ROW_SHIFT;

    row[7] = (a0 - b0) >> ROW_SHIFT;

    row[1] = (a1 + b1) >> ROW_SHIFT;

    row[6] = (a1 - b1) >> ROW_SHIFT;

    row[2] = (a2 + b2) >> ROW_SHIFT;

    row[5] = (a2 - b2) >> ROW_SHIFT;

    row[3] = (a3 + b3) >> ROW_SHIFT;

    row[4] = (a3 - b3) >> ROW_SHIFT;

}

static int get_slice_offset(AVCodecContext *avctx, const uint8_t *buf, int n)

{

    if(avctx->slice_count) return avctx->slice_offset[n];

    else                   return AV_RL32(buf + n*8 - 4) == 1 ? AV_RL32(buf + n*8) :  AV_RB32(buf + n*8);

}

static int tls_read(URLContext *h, uint8_t *buf, int size)

{

    TLSContext *c = h->priv_data;

    size_t processed = 0;

    int ret = SSLRead(c->ssl_context, buf, size, &processed);

    ret = map_ssl_error(ret, processed);

    if (ret > 0)

        return ret;

    if (ret == 0)

        return AVERROR_EOF;

    return print_tls_error(h, ret);

}

int ff_wma_run_level_decode(AVCodecContext* avctx, GetBitContext* gb,

                            VLC *vlc,

                            const uint16_t *level_table, const uint16_t *run_table,

                            int version, WMACoef *ptr, int offset,

                            int num_coefs, int block_len, int frame_len_bits,

                            int coef_nb_bits)

{

    int code, run, level, sign;

    WMACoef* eptr = ptr + num_coefs;

    ptr += offset;

    for(;;) {

        code = get_vlc2(gb, vlc->table, VLCBITS, VLCMAX);

        if (code < 0)

            return -1;

        if (code == 1) {

            /* EOB */

            break;

        } else if (code == 0) {

            /* escape */

            if (!version) {

                level = get_bits(gb, coef_nb_bits);

                /* NOTE: this is rather suboptimal. reading

                   block_len_bits would be better */

                run = get_bits(gb, frame_len_bits);

            } else {

                level = ff_wma_get_large_val(gb);

                /** escape decode */

                if (get_bits1(gb)) {

                    if (get_bits1(gb)) {

                        if (get_bits1(gb)) {

                            av_log(avctx,AV_LOG_ERROR,

                                "broken escape sequence\n");

                            return -1;

                        } else

                            run = get_bits(gb, frame_len_bits) + 4;

                    } else

                        run = get_bits(gb, 2) + 1;

                } else

                     run = 0;

            }

        } else {

            /* normal code */

            run = run_table[code];

            level = level_table[code];

        }

        sign = get_bits1(gb);

        if (!sign)

             level = -level;

        ptr += run;

        if (ptr >= eptr)

        {

            av_log(NULL, AV_LOG_ERROR, "overflow in spectral RLE, ignoring\n");

            break;

        }

        *ptr++ = level;

        /* NOTE: EOB can be omitted */

        if (ptr >= eptr)

            break;

    }

    return 0;

}

static void blend_frames_c(BLEND_FUNC_PARAMS)

{

    int line, pixel;

    for (line = 0; line < height; line++) {

        for (pixel = 0; pixel < width; pixel++) {

            // integer version of (src1 * factor1) + (src2 * factor2) + 0.5

            // 0.5 is for rounding

            // 128 is the integer representation of 0.5 << 8

            dst[pixel] = ((src1[pixel] * factor1) + (src2[pixel] * factor2) + 128) >> 8;

        }

        src1 += src1_linesize;

        src2 += src2_linesize;

        dst  += dst_linesize;

    }

}

static void ff_jref_idct1_add(uint8_t *dest, int line_size, DCTELEM *block)

{

    uint8_t *cm = ff_cropTbl + MAX_NEG_CROP;



    dest[0] = cm[dest[0] + ((block[0] + 4)>>3)];

}

static void hScale_altivec_real(SwsContext *c, int16_t *dst, int dstW,

                                const uint8_t *src, const int16_t *filter,

                                const int16_t *filterPos, int filterSize)

{

    register int i;

    DECLARE_ALIGNED(16, int, tempo)[4];



    if (filterSize % 4) {

        for (i = 0; i < dstW; i++) {

            register int j;

            register int srcPos = filterPos[i];

            register int val    = 0;

            for (j = 0; j < filterSize; j++)

                val += ((int)src[srcPos + j]) * filter[filterSize * i + j];

            dst[i] = FFMIN(val >> 7, (1 << 15) - 1);

        }

    } else

        switch (filterSize) {

        case 4:

            for (i = 0; i < dstW; i++) {

                register int srcPos = filterPos[i];



                vector unsigned char src_v0 = vec_ld(srcPos, src);

                vector unsigned char src_v1, src_vF;

                vector signed short src_v, filter_v;

                vector signed int val_vEven, val_s;

                if ((((uintptr_t)src + srcPos) % 16) > 12) {

                    src_v1 = vec_ld(srcPos + 16, src);

                }

                src_vF = vec_perm(src_v0, src_v1, vec_lvsl(srcPos, src));



                src_v = // vec_unpackh sign-extends...

                        (vector signed short)(vec_mergeh((vector unsigned char)vzero, src_vF));

                // now put our elements in the even slots

                src_v = vec_mergeh(src_v, (vector signed short)vzero);



                filter_v = vec_ld(i << 3, filter);

                // The 3 above is 2 (filterSize == 4) + 1 (sizeof(short) == 2).



                // The neat trick: We only care for half the elements,

                // high or low depending on (i<<3)%16 (it's 0 or 8 here),

                // and we're going to use vec_mule, so we choose

                // carefully how to "unpack" the elements into the even slots.

                if ((i << 3) % 16)

                    filter_v = vec_mergel(filter_v, (vector signed short)vzero);

                else

                    filter_v = vec_mergeh(filter_v, (vector signed short)vzero);



                val_vEven = vec_mule(src_v, filter_v);

                val_s     = vec_sums(val_vEven, vzero);

                vec_st(val_s, 0, tempo);

                dst[i] = FFMIN(tempo[3] >> 7, (1 << 15) - 1);

            }

        break;



        case 8:

            for (i = 0; i < dstW; i++) {

                register int srcPos = filterPos[i];



                vector unsigned char src_v0 = vec_ld(srcPos, src);

                vector unsigned char src_v1, src_vF;

                vector signed short src_v, filter_v;

                vector signed int val_v, val_s;

                if ((((uintptr_t)src + srcPos) % 16) > 8) {

                    src_v1 = vec_ld(srcPos + 16, src);

                }

                src_vF = vec_perm(src_v0, src_v1, vec_lvsl(srcPos, src));



                src_v = // vec_unpackh sign-extends...

                        (vector signed short)(vec_mergeh((vector unsigned char)vzero, src_vF));

                filter_v = vec_ld(i << 4, filter);

                // the 4 above is 3 (filterSize == 8) + 1 (sizeof(short) == 2)



                val_v = vec_msums(src_v, filter_v, (vector signed int)vzero);

                val_s = vec_sums(val_v, vzero);

                vec_st(val_s, 0, tempo);

                dst[i] = FFMIN(tempo[3] >> 7, (1 << 15) - 1);

            }

        break;



        case 16:

            for (i = 0; i < dstW; i++) {

                register int srcPos = filterPos[i];



                vector unsigned char src_v0 = vec_ld(srcPos, src);

                vector unsigned char src_v1 = vec_ld(srcPos + 16, src);

                vector unsigned char src_vF = vec_perm(src_v0, src_v1, vec_lvsl(srcPos, src));



                vector signed short src_vA = // vec_unpackh sign-extends...

                                             (vector signed short)(vec_mergeh((vector unsigned char)vzero, src_vF));

                vector signed short src_vB = // vec_unpackh sign-extends...

                                             (vector signed short)(vec_mergel((vector unsigned char)vzero, src_vF));



                vector signed short filter_v0 = vec_ld(i << 5, filter);

                vector signed short filter_v1 = vec_ld((i << 5) + 16, filter);

                // the 5 above are 4 (filterSize == 16) + 1 (sizeof(short) == 2)



                vector signed int val_acc = vec_msums(src_vA, filter_v0, (vector signed int)vzero);

                vector signed int val_v   = vec_msums(src_vB, filter_v1, val_acc);



                vector signed int val_s = vec_sums(val_v, vzero);



                vec_st(val_s, 0, tempo);

                dst[i] = FFMIN(tempo[3] >> 7, (1 << 15) - 1);

            }

        break;



        default:

            for (i = 0; i < dstW; i++) {

                register int j;

                register int srcPos = filterPos[i];



                vector signed int val_s, val_v = (vector signed int)vzero;

                vector signed short filter_v0R = vec_ld(i * 2 * filterSize, filter);

                vector unsigned char permF     = vec_lvsl((i * 2 * filterSize), filter);



                vector unsigned char src_v0 = vec_ld(srcPos, src);

                vector unsigned char permS  = vec_lvsl(srcPos, src);



                for (j = 0; j < filterSize - 15; j += 16) {

                    vector unsigned char src_v1 = vec_ld(srcPos + j + 16, src);

                    vector unsigned char src_vF = vec_perm(src_v0, src_v1, permS);



                    vector signed short src_vA = // vec_unpackh sign-extends...

                                                 (vector signed short)(vec_mergeh((vector unsigned char)vzero, src_vF));

                    vector signed short src_vB = // vec_unpackh sign-extends...

                                                 (vector signed short)(vec_mergel((vector unsigned char)vzero, src_vF));



                    vector signed short filter_v1R = vec_ld((i * 2 * filterSize) + (j * 2) + 16, filter);

                    vector signed short filter_v2R = vec_ld((i * 2 * filterSize) + (j * 2) + 32, filter);

                    vector signed short filter_v0  = vec_perm(filter_v0R, filter_v1R, permF);

                    vector signed short filter_v1  = vec_perm(filter_v1R, filter_v2R, permF);



                    vector signed int val_acc = vec_msums(src_vA, filter_v0, val_v);

                    val_v = vec_msums(src_vB, filter_v1, val_acc);



                    filter_v0R = filter_v2R;

                    src_v0     = src_v1;

                }



                if (j < filterSize - 7) {

                    // loading src_v0 is useless, it's already done above

                    // vector unsigned char src_v0 = vec_ld(srcPos + j, src);

                    vector unsigned char src_v1, src_vF;

                    vector signed short src_v, filter_v1R, filter_v;

                    if ((((uintptr_t)src + srcPos) % 16) > 8) {

                        src_v1 = vec_ld(srcPos + j + 16, src);

                    }

                    src_vF = vec_perm(src_v0, src_v1, permS);



                    src_v = // vec_unpackh sign-extends...

                            (vector signed short)(vec_mergeh((vector unsigned char)vzero, src_vF));

                    // loading filter_v0R is useless, it's already done above

                    // vector signed short filter_v0R = vec_ld((i * 2 * filterSize) + j, filter);

                    filter_v1R = vec_ld((i * 2 * filterSize) + (j * 2) + 16, filter);

                    filter_v   = vec_perm(filter_v0R, filter_v1R, permF);



                    val_v = vec_msums(src_v, filter_v, val_v);

                }



                val_s = vec_sums(val_v, vzero);



                vec_st(val_s, 0, tempo);

                dst[i] = FFMIN(tempo[3] >> 7, (1 << 15) - 1);

            }

        }

}

static int dfa_decode_frame(AVCodecContext *avctx,

                            void *data, int *data_size,

                            AVPacket *avpkt)

{

    DfaContext *s = avctx->priv_data;

    const uint8_t *buf = avpkt->data;

    const uint8_t *buf_end = avpkt->data + avpkt->size;

    const uint8_t *tmp_buf;

    uint32_t chunk_type, chunk_size;

    uint8_t *dst;

    int ret;

    int i, pal_elems;



    if (s->pic.data[0])

        avctx->release_buffer(avctx, &s->pic);



    if ((ret = avctx->get_buffer(avctx, &s->pic))) {

        av_log(avctx, AV_LOG_ERROR, "get_buffer() failed\n");

        return ret;

    }



    while (buf < buf_end) {

        chunk_size = AV_RL32(buf + 4);

        chunk_type = AV_RL32(buf + 8);

        buf += 12;

        if (buf_end - buf < chunk_size) {

            av_log(avctx, AV_LOG_ERROR, "Chunk size is too big (%d bytes)\n", chunk_size);

            return -1;

        }

        if (!chunk_type)

            break;

        if (chunk_type == 1) {

            pal_elems = FFMIN(chunk_size / 3, 256);

            tmp_buf = buf;

            for (i = 0; i < pal_elems; i++) {

                s->pal[i] = bytestream_get_be24(&tmp_buf) << 2;

                s->pal[i] |= (s->pal[i] >> 6) & 0x333;

            }

            s->pic.palette_has_changed = 1;

        } else if (chunk_type <= 9) {

            if (decoder[chunk_type - 2](s->frame_buf, avctx->width, avctx->height,

                                        buf, buf + chunk_size)) {

                av_log(avctx, AV_LOG_ERROR, "Error decoding %s chunk\n",

                       chunk_name[chunk_type - 2]);

                return -1;

            }

        } else {

            av_log(avctx, AV_LOG_WARNING, "Ignoring unknown chunk type %d\n",

                   chunk_type);

        }

        buf += chunk_size;

    }



    buf = s->frame_buf;

    dst = s->pic.data[0];

    for (i = 0; i < avctx->height; i++) {

        memcpy(dst, buf, avctx->width);

        dst += s->pic.linesize[0];

        buf += avctx->width;

    }

    memcpy(s->pic.data[1], s->pal, sizeof(s->pal));



    *data_size = sizeof(AVFrame);

    *(AVFrame*)data = s->pic;



    return avpkt->size;

}

static int init_file(AVFormatContext *s, OutputStream *os, int64_t start_ts)

{

    int ret, i;

    ret = avio_open2(&os->out, os->temp_filename, AVIO_FLAG_WRITE,

                     &s->interrupt_callback, NULL);

    if (ret < 0)

        return ret;

    avio_wb32(os->out, 0);

    avio_wl32(os->out, MKTAG('m','d','a','t'));

    for (i = 0; i < os->nb_extra_packets; i++) {

        AV_WB24(os->extra_packets[i] + 4, start_ts);

        os->extra_packets[i][7] = (start_ts >> 24) & 0x7f;

        avio_write(os->out, os->extra_packets[i], os->extra_packet_sizes[i]);

    }

    return 0;

}

static inline void log_input_change(void *ctx, AVFilterLink *link, AVFilterBufferRef *ref)

{

    char old_layout_str[16], new_layout_str[16];

    av_get_channel_layout_string(old_layout_str, sizeof(old_layout_str),

                                 -1, link->channel_layout);

    av_get_channel_layout_string(new_layout_str, sizeof(new_layout_str),

                                 -1, ref->audio->channel_layout);

    av_log(ctx, AV_LOG_INFO,

           "Audio input format changed: "

           "%s:%s:%"PRId64" -> %s:%s:%u, normalizing\n",

           av_get_sample_fmt_name(link->format),

           old_layout_str, link->sample_rate,

           av_get_sample_fmt_name(ref->format),

           new_layout_str, ref->audio->sample_rate);

}

static int decode_mime_header(AMRWBContext *ctx, const uint8_t *buf)

{

    /* Decode frame header (1st octet) */

    ctx->fr_cur_mode  = buf[0] >> 3 & 0x0F;

    ctx->fr_quality   = (buf[0] & 0x4) != 0x4;



    return 1;

}

static void init_entropy_decoder(APEContext *ctx)

{

    /* Read the CRC */

    ctx->CRC = bytestream_get_be32(&ctx->ptr);



    /* Read the frame flags if they exist */

    ctx->frameflags = 0;

    if ((ctx->fileversion > 3820) && (ctx->CRC & 0x80000000)) {

        ctx->CRC &= ~0x80000000;



        ctx->frameflags = bytestream_get_be32(&ctx->ptr);

    }



    /* Keep a count of the blocks decoded in this frame */

    ctx->blocksdecoded = 0;



    /* Initialize the rice structs */

    ctx->riceX.k = 10;

    ctx->riceX.ksum = (1 << ctx->riceX.k) * 16;

    ctx->riceY.k = 10;

    ctx->riceY.ksum = (1 << ctx->riceY.k) * 16;



    /* The first 8 bits of input are ignored. */

    ctx->ptr++;



    range_start_decoding(ctx);

}

static void get_sub_picture(CinepakEncContext *s, int x, int y, AVPicture *in, AVPicture *out)

{

    out->data[0] = in->data[0] + x + y * in->linesize[0];

    out->linesize[0] = in->linesize[0];



    if(s->pix_fmt == AV_PIX_FMT_YUV420P) {

        out->data[1] = in->data[1] + (x >> 1) + (y >> 1) * in->linesize[1];

        out->linesize[1] = in->linesize[1];



        out->data[2] = in->data[2] + (x >> 1) + (y >> 1) * in->linesize[2];

        out->linesize[2] = in->linesize[2];

    }

}

