static int tcp_open(URLContext *h, const char *uri, int flags)

{

    struct sockaddr_in dest_addr;

    int port, fd = -1;

    TCPContext *s = NULL;

    fd_set wfds;

    int fd_max, ret;

    struct timeval tv;

    socklen_t optlen;

    char hostname[1024],proto[1024],path[1024],tmp[1024],*q;



    if(!ff_network_init())

        return AVERROR(EIO);



    url_split(proto, sizeof(proto), NULL, 0, hostname, sizeof(hostname),

        &port, path, sizeof(path), uri);

    if (strcmp(proto,"tcp") || port <= 0 || port >= 65536)

        return AVERROR(EINVAL);

    if ((q = strchr(hostname,'@'))) { strcpy(tmp,q+1); strcpy(hostname,tmp); }



    dest_addr.sin_family = AF_INET;

    dest_addr.sin_port = htons(port);

    if (resolve_host(&dest_addr.sin_addr, hostname) < 0)

        return AVERROR(EIO);



    fd = socket(AF_INET, SOCK_STREAM, 0);

    if (fd < 0)

        return AVERROR(EIO);

    ff_socket_nonblock(fd, 1);



 redo:

    ret = connect(fd, (struct sockaddr *)&dest_addr,

                  sizeof(dest_addr));

    if (ret < 0) {

        if (ff_neterrno() == FF_NETERROR(EINTR))

            goto redo;

        if (ff_neterrno() != FF_NETERROR(EINPROGRESS) &&

            ff_neterrno() != FF_NETERROR(EAGAIN))

            goto fail;



        /* wait until we are connected or until abort */

        for(;;) {

            if (url_interrupt_cb()) {

                ret = AVERROR(EINTR);

                goto fail1;

            }

            fd_max = fd;

            FD_ZERO(&wfds);

            FD_SET(fd, &wfds);

            tv.tv_sec = 0;

            tv.tv_usec = 100 * 1000;

            ret = select(fd_max + 1, NULL, &wfds, NULL, &tv);

            if (ret > 0 && FD_ISSET(fd, &wfds))

                break;

        }



        /* test error */

        optlen = sizeof(ret);

        getsockopt (fd, SOL_SOCKET, SO_ERROR, &ret, &optlen);

        if (ret != 0)

            goto fail;

    }

    s = av_malloc(sizeof(TCPContext));

    if (!s)

        return AVERROR(ENOMEM);

    h->priv_data = s;

    h->is_streamed = 1;

    s->fd = fd;

    return 0;



 fail:

    ret = AVERROR(EIO);

 fail1:

    if (fd >= 0)

        closesocket(fd);

    return ret;

}

static av_always_inline int even(uint64_t layout)

{

    return (!layout || (layout & (layout - 1)));

}

static int64_t mkv_write_seekhead(AVIOContext *pb, mkv_seekhead *seekhead)

{

    ebml_master metaseek, seekentry;

    int64_t currentpos;

    int i;



    currentpos = avio_tell(pb);



    if (seekhead->reserved_size > 0)

        if (avio_seek(pb, seekhead->filepos, SEEK_SET) < 0)

            return -1;



    metaseek = start_ebml_master(pb, MATROSKA_ID_SEEKHEAD, seekhead->reserved_size);

    for (i = 0; i < seekhead->num_entries; i++) {

        mkv_seekhead_entry *entry = &seekhead->entries[i];



        seekentry = start_ebml_master(pb, MATROSKA_ID_SEEKENTRY, MAX_SEEKENTRY_SIZE);



        put_ebml_id(pb, MATROSKA_ID_SEEKID);

        put_ebml_num(pb, ebml_id_size(entry->elementid), 0);

        put_ebml_id(pb, entry->elementid);



        put_ebml_uint(pb, MATROSKA_ID_SEEKPOSITION, entry->segmentpos);

        end_ebml_master(pb, seekentry);

    }

    end_ebml_master(pb, metaseek);



    if (seekhead->reserved_size > 0) {

        uint64_t remaining = seekhead->filepos + seekhead->reserved_size - avio_tell(pb);

        put_ebml_void(pb, remaining);

        avio_seek(pb, currentpos, SEEK_SET);



        currentpos = seekhead->filepos;

    }

    av_free(seekhead->entries);

    av_free(seekhead);



    return currentpos;

}

static int wavpack_decode_frame(AVCodecContext *avctx,

                            void *data, int *data_size,

                            AVPacket *avpkt)

{

    WavpackContext *s = avctx->priv_data;

    const uint8_t *buf = avpkt->data;

    int buf_size = avpkt->size;

    int frame_size;

    int samplecount = 0;



    s->block = 0;

    s->samples_left = 0;

    s->ch_offset = 0;



    if(s->mkv_mode){

        s->samples = AV_RL32(buf); buf += 4;

    }

    while(buf_size > 0){

        if(!s->multichannel){

            frame_size = buf_size;

        }else{

            if(!s->mkv_mode){

                frame_size = AV_RL32(buf) - 12; buf += 4; buf_size -= 4;

            }else{

                if(buf_size < 12) //MKV files can have zero flags after last block

                    break;

                frame_size = AV_RL32(buf + 8) + 12;

            }

        }

        if(frame_size < 0 || frame_size > buf_size){

            av_log(avctx, AV_LOG_ERROR, "Block %d has invalid size (size %d vs. %d bytes left)\n",

                   s->block, frame_size, buf_size);

            return -1;

        }

        if((samplecount = wavpack_decode_block(avctx, s->block, data,

                                               data_size, buf, frame_size)) < 0)

            return -1;

        s->block++;

        buf += frame_size; buf_size -= frame_size;

    }

    *data_size = samplecount * avctx->channels;



    return s->samples_left > 0 ? 0 : avpkt->size;

}

static int get_bits(J2kDecoderContext *s, int n)

{

    int res = 0;

    if (s->buf_end - s->buf < ((n - s->bit_index) >> 8))

        return AVERROR(EINVAL);

    while (--n >= 0){

        res <<= 1;

        if (s->bit_index == 0){

            s->bit_index = 7 + (*s->buf != 0xff);

            s->buf++;

        }

        s->bit_index--;

        res |= (*s->buf >> s->bit_index) & 1;

    }

    return res;

}

static int get_cookies(HTTPContext *s, char **cookies, const char *path,

                       const char *domain)

{

    // cookie strings will look like Set-Cookie header field values.  Multiple

    // Set-Cookie fields will result in multiple values delimited by a newline

    int ret = 0;

    char *next, *cookie, *set_cookies = av_strdup(s->cookies), *cset_cookies = set_cookies;



    if (!set_cookies) return AVERROR(EINVAL);



    *cookies = NULL;

    while ((cookie = av_strtok(set_cookies, "\n", &next))) {

        int domain_offset = 0;

        char *param, *next_param, *cdomain = NULL, *cpath = NULL, *cvalue = NULL;

        set_cookies = NULL;



        while ((param = av_strtok(cookie, "; ", &next_param))) {

            cookie = NULL;

            if        (!av_strncasecmp("path=",   param, 5)) {


                cpath = av_strdup(&param[5]);

            } else if (!av_strncasecmp("domain=", param, 7)) {


                cdomain = av_strdup(&param[7]);

            } else if (!av_strncasecmp("secure",  param, 6) ||

                       !av_strncasecmp("comment", param, 7) ||

                       !av_strncasecmp("max-age", param, 7) ||

                       !av_strncasecmp("version", param, 7)) {

                // ignore Comment, Max-Age, Secure and Version

            } else {

                av_free(cvalue);

                cvalue = av_strdup(param);

            }

        }



        // ensure all of the necessary values are valid

        if (!cdomain || !cpath || !cvalue) {

            av_log(s, AV_LOG_WARNING,

                   "Invalid cookie found, no value, path or domain specified\n");

            goto done_cookie;

        }



        // check if the request path matches the cookie path

        if (av_strncasecmp(path, cpath, strlen(cpath)))

            goto done_cookie;



        // the domain should be at least the size of our cookie domain

        domain_offset = strlen(domain) - strlen(cdomain);

        if (domain_offset < 0)

            goto done_cookie;



        // match the cookie domain

        if (av_strcasecmp(&domain[domain_offset], cdomain))

            goto done_cookie;



        // cookie parameters match, so copy the value

        if (!*cookies) {

            if (!(*cookies = av_strdup(cvalue))) {

                ret = AVERROR(ENOMEM);

                goto done_cookie;

            }

        } else {

            char *tmp = *cookies;

            size_t str_size = strlen(cvalue) + strlen(*cookies) + 3;

            if (!(*cookies = av_malloc(str_size))) {

                ret = AVERROR(ENOMEM);

                goto done_cookie;

            }

            snprintf(*cookies, str_size, "%s; %s", tmp, cvalue);

            av_free(tmp);

        }



        done_cookie:



        av_free(cvalue);

        if (ret < 0) {

            if (*cookies) av_freep(cookies);

            av_free(cset_cookies);

            return ret;

        }

    }



    av_free(cset_cookies);



    return 0;

}

static inline void xan_wc3_copy_pixel_run(XanContext *s,

    int x, int y, int pixel_count, int motion_x, int motion_y)

{

    int stride;

    int line_inc;

    int curframe_index, prevframe_index;

    int curframe_x, prevframe_x;

    int width = s->avctx->width;

    unsigned char *palette_plane, *prev_palette_plane;



    palette_plane = s->current_frame.data[0];

    prev_palette_plane = s->last_frame.data[0];



    stride = s->current_frame.linesize[0];

    line_inc = stride - width;

    curframe_index = y * stride + x;

    curframe_x = x;

    prevframe_index = (y + motion_y) * stride + x + motion_x;

    prevframe_x = x + motion_x;

    while(pixel_count && (curframe_index < s->frame_size)) {

        int count = FFMIN3(pixel_count, width - curframe_x, width - prevframe_x);



        memcpy(palette_plane + curframe_index, prev_palette_plane + prevframe_index, count);

        pixel_count     -= count;

        curframe_index  += count;

        prevframe_index += count;

        curframe_x      += count;

        prevframe_x     += count;



        if (curframe_x >= width) {

            curframe_index += line_inc;

            curframe_x = 0;

        }



        if (prevframe_x >= width) {

            prevframe_index += line_inc;

            prevframe_x = 0;

        }

    }

}

static inline int get_block(GetBitContext *gb, DCTELEM *block, const uint8_t *scan,
                            const uint32_t *quant) {
    int coeff, i, n;
    int8_t ac;
    uint8_t dc = get_bits(gb, 8);
    // block not coded
    if (dc == 255)
    // number of non-zero coefficients
    coeff = get_bits(gb, 6);
    // normally we would only need to clear the (63 - coeff) last values,
    // but since we do not know where they are we just clear the whole block
    memset(block, 0, 64 * sizeof(DCTELEM));
    // 2 bits per coefficient
    while (coeff) {
        ac = get_sbits(gb, 2);
        if (ac == -2)
            break; // continue with more bits
        PUT_COEFF(ac);
    }
    // 4 bits per coefficient
    ALIGN(4);
    if (get_bits_count(gb) + (coeff << 2) >= gb->size_in_bits)
    while (coeff) {
        ac = get_sbits(gb, 4);
        if (ac == -8)
            break; // continue with more bits
        PUT_COEFF(ac);
    }
    // 8 bits per coefficient
    ALIGN(8);
    if (get_bits_count(gb) + (coeff << 3) >= gb->size_in_bits)
    while (coeff) {
        ac = get_sbits(gb, 8);
        PUT_COEFF(ac);
    }
    PUT_COEFF(dc);
    return 1;
}

static int can_merge_formats(AVFilterFormats *a_arg,

                             AVFilterFormats *b_arg,

                             enum AVMediaType type,

                             int is_sample_rate)

{

    AVFilterFormats *a, *b, *ret;

    if (a == b)

        return 1;

    a = clone_filter_formats(a_arg);

    b = clone_filter_formats(b_arg);

    if (is_sample_rate) {

        ret = ff_merge_samplerates(a, b);

    } else {

        ret = ff_merge_formats(a, b, type);

    }

    if (ret) {

        av_freep(&ret->formats);

        av_freep(&ret);

        return 1;

    } else {

        av_freep(&a->formats);

        av_freep(&b->formats);

        av_freep(&a);

        av_freep(&b);

        return 0;

    }

}

static int mxf_write_partition(AVFormatContext *s, int bodysid,

                                int indexsid,

                                const uint8_t *key, int write_metadata)

{

    MXFContext *mxf = s->priv_data;

    AVIOContext *pb = s->pb;

    int64_t header_byte_count_offset;

    unsigned index_byte_count = 0;

    uint64_t partition_offset = avio_tell(pb);

    int err;



    if (!mxf->edit_unit_byte_count && mxf->edit_units_count)

        index_byte_count = 85 + 12+(s->nb_streams+1)*6 +

            12+mxf->edit_units_count*(11+mxf->slice_count*4);

    else if (mxf->edit_unit_byte_count && indexsid)

        index_byte_count = 80;



    if (index_byte_count) {

        // add encoded ber length

        index_byte_count += 16 + klv_ber_length(index_byte_count);

        index_byte_count += klv_fill_size(index_byte_count);

    }



    if (!memcmp(key, body_partition_key, 16)) {

        if ((err = av_reallocp_array(&mxf->body_partition_offset, mxf->body_partitions_count + 1,

                                     sizeof(*mxf->body_partition_offset))) < 0) {

            mxf->body_partitions_count = 0;

            return err;

        }

        mxf->body_partition_offset[mxf->body_partitions_count++] = partition_offset;

    }



    // write klv

    avio_write(pb, key, 16);

    klv_encode_ber_length(pb, 88 + 16 * mxf->essence_container_count);



    // write partition value

    avio_wb16(pb, 1); // majorVersion

    avio_wb16(pb, 2); // minorVersion

    avio_wb32(pb, KAG_SIZE); // KAGSize



    avio_wb64(pb, partition_offset); // ThisPartition



    if (!memcmp(key, body_partition_key, 16) && mxf->body_partitions_count > 1)

        avio_wb64(pb, mxf->body_partition_offset[mxf->body_partitions_count-2]); // PreviousPartition

    else if (!memcmp(key, footer_partition_key, 16) && mxf->body_partitions_count)

        avio_wb64(pb, mxf->body_partition_offset[mxf->body_partitions_count-1]); // PreviousPartition

    else

        avio_wb64(pb, 0);



    avio_wb64(pb, mxf->footer_partition_offset); // footerPartition



    // set offset

    header_byte_count_offset = avio_tell(pb);

    avio_wb64(pb, 0); // headerByteCount, update later



    // indexTable

    avio_wb64(pb, index_byte_count); // indexByteCount

    avio_wb32(pb, index_byte_count ? indexsid : 0); // indexSID



    // BodyOffset

    if (bodysid && mxf->edit_units_count && mxf->body_partitions_count) {

        avio_wb64(pb, mxf->body_offset);

    } else

        avio_wb64(pb, 0);



    avio_wb32(pb, bodysid); // bodySID



    // operational pattern

    avio_write(pb, op1a_ul, 16);



    // essence container

    mxf_write_essence_container_refs(s);



    if (write_metadata) {

        // mark the start of the headermetadata and calculate metadata size

        int64_t pos, start;

        unsigned header_byte_count;



        mxf_write_klv_fill(s);

        start = avio_tell(s->pb);

        mxf_write_primer_pack(s);

        mxf_write_header_metadata_sets(s);

        pos = avio_tell(s->pb);

        header_byte_count = pos - start + klv_fill_size(pos);



        // update header_byte_count

        avio_seek(pb, header_byte_count_offset, SEEK_SET);

        avio_wb64(pb, header_byte_count);

        avio_seek(pb, pos, SEEK_SET);

    }



    avio_flush(pb);



    return 0;

}

static uint8_t get_sot(J2kDecoderContext *s)

{

    if (s->buf_end - s->buf < 4)

        return AVERROR(EINVAL);



    s->curtileno = bytestream_get_be16(&s->buf); ///< Isot

    if((unsigned)s->curtileno >= s->numXtiles * s->numYtiles){

        s->curtileno=0;

        return AVERROR(EINVAL);

    }



    s->buf += 4; ///< Psot (ignored)



    if (!bytestream_get_byte(&s->buf)){ ///< TPsot

        J2kTile *tile = s->tile + s->curtileno;



        /* copy defaults */

        memcpy(tile->codsty, s->codsty, s->ncomponents * sizeof(J2kCodingStyle));

        memcpy(tile->qntsty, s->qntsty, s->ncomponents * sizeof(J2kQuantStyle));

    }

    bytestream_get_byte(&s->buf); ///< TNsot



    return 0;

}

static void select_input_picture(MpegEncContext *s){

    int i;



    for(i=1; i<MAX_PICTURE_COUNT; i++)

        s->reordered_input_picture[i-1]= s->reordered_input_picture[i];

    s->reordered_input_picture[MAX_PICTURE_COUNT-1]= NULL;



    /* set next picture type & ordering */

    if(s->reordered_input_picture[0]==NULL && s->input_picture[0]){

        if(/*s->picture_in_gop_number >= s->gop_size ||*/ s->next_picture_ptr==NULL || s->intra_only){

            s->reordered_input_picture[0]= s->input_picture[0];

            s->reordered_input_picture[0]->pict_type= I_TYPE;

            s->reordered_input_picture[0]->coded_picture_number= s->coded_picture_number++;

        }else{

            int b_frames;



            if(s->avctx->frame_skip_threshold || s->avctx->frame_skip_factor){

                if(s->picture_in_gop_number < s->gop_size && skip_check(s, s->input_picture[0], s->next_picture_ptr)){

                //FIXME check that te gop check above is +-1 correct

//av_log(NULL, AV_LOG_DEBUG, "skip %p %Ld\n", s->input_picture[0]->data[0], s->input_picture[0]->pts);



                    if(s->input_picture[0]->type == FF_BUFFER_TYPE_SHARED){

                        for(i=0; i<4; i++)

                            s->input_picture[0]->data[i]= NULL;

                        s->input_picture[0]->type= 0;

                    }else{

                        assert(   s->input_picture[0]->type==FF_BUFFER_TYPE_USER

                               || s->input_picture[0]->type==FF_BUFFER_TYPE_INTERNAL);



                        s->avctx->release_buffer(s->avctx, (AVFrame*)s->input_picture[0]);

                    }



                    emms_c();

                    ff_vbv_update(s, 0);



                    goto no_output_pic;

                }

            }



            if(s->flags&CODEC_FLAG_PASS2){

                for(i=0; i<s->max_b_frames+1; i++){

                    int pict_num= s->input_picture[0]->display_picture_number + i;



                    if(pict_num >= s->rc_context.num_entries)

                        break;

                    if(!s->input_picture[i]){

                        s->rc_context.entry[pict_num-1].new_pict_type = P_TYPE;

                        break;

                    }



                    s->input_picture[i]->pict_type=

                        s->rc_context.entry[pict_num].new_pict_type;

                }

            }



            if(s->avctx->b_frame_strategy==0){

                b_frames= s->max_b_frames;

                while(b_frames && !s->input_picture[b_frames]) b_frames--;

            }else if(s->avctx->b_frame_strategy==1){

                for(i=1; i<s->max_b_frames+1; i++){

                    if(s->input_picture[i] && s->input_picture[i]->b_frame_score==0){

                        s->input_picture[i]->b_frame_score=

                            get_intra_count(s, s->input_picture[i  ]->data[0],

                                               s->input_picture[i-1]->data[0], s->linesize) + 1;

                    }

                }

                for(i=0; i<s->max_b_frames+1; i++){

                    if(s->input_picture[i]==NULL || s->input_picture[i]->b_frame_score - 1 > s->mb_num/s->avctx->b_sensitivity) break;

                }



                b_frames= FFMAX(0, i-1);



                /* reset scores */

                for(i=0; i<b_frames+1; i++){

                    s->input_picture[i]->b_frame_score=0;

                }

            }else if(s->avctx->b_frame_strategy==2){

                b_frames= estimate_best_b_count(s);

            }else{

                av_log(s->avctx, AV_LOG_ERROR, "illegal b frame strategy\n");

                b_frames=0;

            }



            emms_c();

//static int b_count=0;

//b_count+= b_frames;

//av_log(s->avctx, AV_LOG_DEBUG, "b_frames: %d\n", b_count);



            for(i= b_frames - 1; i>=0; i--){

                int type= s->input_picture[i]->pict_type;

                if(type && type != B_TYPE)

                    b_frames= i;

            }

            if(s->input_picture[b_frames]->pict_type == B_TYPE && b_frames == s->max_b_frames){

                av_log(s->avctx, AV_LOG_ERROR, "warning, too many b frames in a row\n");

            }



            if(s->picture_in_gop_number + b_frames >= s->gop_size){

              if((s->flags2 & CODEC_FLAG2_STRICT_GOP) && s->gop_size > s->picture_in_gop_number){

                    b_frames= s->gop_size - s->picture_in_gop_number - 1;

              }else{

                if(s->flags & CODEC_FLAG_CLOSED_GOP)

                    b_frames=0;

                s->input_picture[b_frames]->pict_type= I_TYPE;

              }

            }



            if(   (s->flags & CODEC_FLAG_CLOSED_GOP)

               && b_frames

               && s->input_picture[b_frames]->pict_type== I_TYPE)

                b_frames--;



            s->reordered_input_picture[0]= s->input_picture[b_frames];

            if(s->reordered_input_picture[0]->pict_type != I_TYPE)

                s->reordered_input_picture[0]->pict_type= P_TYPE;

            s->reordered_input_picture[0]->coded_picture_number= s->coded_picture_number++;

            for(i=0; i<b_frames; i++){

                s->reordered_input_picture[i+1]= s->input_picture[i];

                s->reordered_input_picture[i+1]->pict_type= B_TYPE;

                s->reordered_input_picture[i+1]->coded_picture_number= s->coded_picture_number++;

            }

        }

    }

no_output_pic:

    if(s->reordered_input_picture[0]){

        s->reordered_input_picture[0]->reference= s->reordered_input_picture[0]->pict_type!=B_TYPE ? 3 : 0;



        copy_picture(&s->new_picture, s->reordered_input_picture[0]);



        if(s->reordered_input_picture[0]->type == FF_BUFFER_TYPE_SHARED){

            // input is a shared pix, so we can't modifiy it -> alloc a new one & ensure that the shared one is reuseable



            int i= ff_find_unused_picture(s, 0);

            Picture *pic= &s->picture[i];



            /* mark us unused / free shared pic */

            for(i=0; i<4; i++)

                s->reordered_input_picture[0]->data[i]= NULL;

            s->reordered_input_picture[0]->type= 0;



            pic->reference              = s->reordered_input_picture[0]->reference;



            alloc_picture(s, pic, 0);



            copy_picture_attributes(s, (AVFrame*)pic, (AVFrame*)s->reordered_input_picture[0]);



            s->current_picture_ptr= pic;

        }else{

            // input is not a shared pix -> reuse buffer for current_pix



            assert(   s->reordered_input_picture[0]->type==FF_BUFFER_TYPE_USER

                   || s->reordered_input_picture[0]->type==FF_BUFFER_TYPE_INTERNAL);



            s->current_picture_ptr= s->reordered_input_picture[0];

            for(i=0; i<4; i++){

                s->new_picture.data[i]+= INPLACE_OFFSET;

            }

        }

        copy_picture(&s->current_picture, s->current_picture_ptr);



        s->picture_number= s->new_picture.display_picture_number;

//printf("dpn:%d\n", s->picture_number);

    }else{

       memset(&s->new_picture, 0, sizeof(Picture));

    }

}

