av_cold void ff_mpadsp_init_x86(MPADSPContext *s)

{

    int cpu_flags = av_get_cpu_flags();



    int i, j;

    for (j = 0; j < 4; j++) {

        for (i = 0; i < 40; i ++) {

            mdct_win_sse[0][j][4*i    ] = ff_mdct_win_float[j    ][i];

            mdct_win_sse[0][j][4*i + 1] = ff_mdct_win_float[j + 4][i];

            mdct_win_sse[0][j][4*i + 2] = ff_mdct_win_float[j    ][i];

            mdct_win_sse[0][j][4*i + 3] = ff_mdct_win_float[j + 4][i];

            mdct_win_sse[1][j][4*i    ] = ff_mdct_win_float[0    ][i];

            mdct_win_sse[1][j][4*i + 1] = ff_mdct_win_float[4    ][i];

            mdct_win_sse[1][j][4*i + 2] = ff_mdct_win_float[j    ][i];

            mdct_win_sse[1][j][4*i + 3] = ff_mdct_win_float[j + 4][i];

        }

    }



#if HAVE_6REGS && HAVE_SSE_INLINE

    if (INLINE_SSE(cpu_flags)) {

        s->apply_window_float = apply_window_mp3;

    }

#endif /* HAVE_SSE_INLINE */



#if HAVE_YASM

#if HAVE_SSE

#if ARCH_X86_32

    if (EXTERNAL_SSE(cpu_flags)) {

        s->imdct36_blocks_float = imdct36_blocks_sse;

    }

#endif

    if (EXTERNAL_SSE2(cpu_flags)) {

        s->imdct36_blocks_float = imdct36_blocks_sse2;

    }

    if (EXTERNAL_SSE3(cpu_flags)) {

        s->imdct36_blocks_float = imdct36_blocks_sse3;

    }

    if (EXTERNAL_SSSE3(cpu_flags)) {

        s->imdct36_blocks_float = imdct36_blocks_ssse3;

    }

#endif

#if HAVE_AVX_EXTERNAL

    if (EXTERNAL_AVX(cpu_flags)) {

        s->imdct36_blocks_float = imdct36_blocks_avx;

    }

#endif

#endif /* HAVE_YASM */

}

static void dirac_unpack_block_motion_data(DiracContext *s)

{

    GetBitContext *gb = &s->gb;

    uint8_t *sbsplit = s->sbsplit;

    int i, x, y, q, p;

    DiracArith arith[8];



    align_get_bits(gb);



    /* [DIRAC_STD] 11.2.4 and 12.2.1 Number of blocks and superblocks */

    s->sbwidth  = DIVRNDUP(s->source.width,  4*s->plane[0].xbsep);

    s->sbheight = DIVRNDUP(s->source.height, 4*s->plane[0].ybsep);

    s->blwidth  = 4 * s->sbwidth;

    s->blheight = 4 * s->sbheight;



    /* [DIRAC_STD] 12.3.1 Superblock splitting modes. superblock_split_modes()

       decode superblock split modes */

    ff_dirac_init_arith_decoder(arith, gb, svq3_get_ue_golomb(gb));     /* svq3_get_ue_golomb(gb) is the length */

    for (y = 0; y < s->sbheight; y++) {

        for (x = 0; x < s->sbwidth; x++) {

            int split  = dirac_get_arith_uint(arith, CTX_SB_F1, CTX_SB_DATA);

            sbsplit[x] = (split + pred_sbsplit(sbsplit+x, s->sbwidth, x, y)) % 3;

        }

        sbsplit += s->sbwidth;

    }



    /* setup arith decoding */

    ff_dirac_init_arith_decoder(arith, gb, svq3_get_ue_golomb(gb));

    for (i = 0; i < s->num_refs; i++) {

        ff_dirac_init_arith_decoder(arith + 4 + 2 * i, gb, svq3_get_ue_golomb(gb));

        ff_dirac_init_arith_decoder(arith + 5 + 2 * i, gb, svq3_get_ue_golomb(gb));

    }

    for (i = 0; i < 3; i++)

        ff_dirac_init_arith_decoder(arith+1+i, gb, svq3_get_ue_golomb(gb));



    for (y = 0; y < s->sbheight; y++)

        for (x = 0; x < s->sbwidth; x++) {

            int blkcnt = 1 << s->sbsplit[y * s->sbwidth + x];

            int step   = 4 >> s->sbsplit[y * s->sbwidth + x];



            for (q = 0; q < blkcnt; q++)

                for (p = 0; p < blkcnt; p++) {

                    int bx = 4 * x + p*step;

                    int by = 4 * y + q*step;

                    DiracBlock *block = &s->blmotion[by*s->blwidth + bx];

                    decode_block_params(s, arith, block, s->blwidth, bx, by);

                    propagate_block_data(block, s->blwidth, step);

                }

        }

}

static void add_bytes_c(uint8_t *dst, uint8_t *src, int w){

    long i;

    for(i=0; i<=w-sizeof(long); i+=sizeof(long)){

        long a = *(long*)(src+i);

        long b = *(long*)(dst+i);

        *(long*)(dst+i) = ((a&pb_7f) + (b&pb_7f)) ^ ((a^b)&pb_80);

    }

    for(; i<w; i++)

        dst[i+0] += src[i+0];

}

static int parse_audio(DBEContext *s, int start, int end, int seg_id)

{

    int ch, ret, key = parse_key(s);



    for (ch = start; ch < end; ch++) {

        if (!s->ch_size[ch]) {

            s->channels[seg_id][ch].nb_groups = 0;

            continue;

        }

        if ((ret = convert_input(s, s->ch_size[ch], key)) < 0)

            return ret;

        if ((ret = parse_channel(s, ch, seg_id)) < 0) {

            if (s->avctx->err_recognition & AV_EF_EXPLODE)

                return ret;

            s->channels[seg_id][ch].nb_groups = 0;

        }

        skip_input(s, s->ch_size[ch]);

    }



    skip_input(s, 1);

    return 0;

}

static void av_noinline filter_mb_edgecv( uint8_t *pix, int stride, int16_t bS[4], unsigned int qp, H264Context *h ) {

    const unsigned int index_a = 52 + qp + h->slice_alpha_c0_offset;

    const int alpha = alpha_table[index_a];

    const int beta  = (beta_table+52)[qp + h->slice_beta_offset];

    if (alpha ==0 || beta == 0) return;



    if( bS[0] < 4 ) {

        int8_t tc[4];

        tc[0] = tc0_table[index_a][bS[0]]+1;

        tc[1] = tc0_table[index_a][bS[1]]+1;

        tc[2] = tc0_table[index_a][bS[2]]+1;

        tc[3] = tc0_table[index_a][bS[3]]+1;

        h->s.dsp.h264_h_loop_filter_chroma(pix, stride, alpha, beta, tc);

    } else {

        h->s.dsp.h264_h_loop_filter_chroma_intra(pix, stride, alpha, beta);

    }

}

static void vp5_parse_coeff(VP56Context *s)

{

    VP56RangeCoder *c = &s->c;

    VP56Model *model = s->modelp;

    uint8_t *permute = s->idct_scantable;

    uint8_t *model1, *model2;

    int coeff, sign, coeff_idx;

    int b, i, cg, idx, ctx, ctx_last;

    int pt = 0;    /* plane type (0 for Y, 1 for U or V) */



    for (b=0; b<6; b++) {

        int ct = 1;    /* code type */



        if (b > 3) pt = 1;



        ctx = 6*s->coeff_ctx[ff_vp56_b6to4[b]][0]

              + s->above_blocks[s->above_block_idx[b]].not_null_dc;

        model1 = model->coeff_dccv[pt];

        model2 = model->coeff_dcct[pt][ctx];



        coeff_idx = 0;

        for (;;) {

            if (vp56_rac_get_prob_branchy(c, model2[0])) {

                if (vp56_rac_get_prob_branchy(c, model2[2])) {

                    if (vp56_rac_get_prob_branchy(c, model2[3])) {

                        s->coeff_ctx[ff_vp56_b6to4[b]][coeff_idx] = 4;

                        idx = vp56_rac_get_tree(c, ff_vp56_pc_tree, model1);

                        sign = vp56_rac_get(c);

                        coeff = ff_vp56_coeff_bias[idx+5];

                        for (i=ff_vp56_coeff_bit_length[idx]; i>=0; i--)

                            coeff += vp56_rac_get_prob(c, ff_vp56_coeff_parse_table[idx][i]) << i;

                    } else {

                        if (vp56_rac_get_prob_branchy(c, model2[4])) {

                            coeff = 3 + vp56_rac_get_prob(c, model1[5]);

                            s->coeff_ctx[ff_vp56_b6to4[b]][coeff_idx] = 3;

                        } else {

                            coeff = 2;

                            s->coeff_ctx[ff_vp56_b6to4[b]][coeff_idx] = 2;

                        }

                        sign = vp56_rac_get(c);

                    }

                    ct = 2;

                } else {

                    ct = 1;

                    s->coeff_ctx[ff_vp56_b6to4[b]][coeff_idx] = 1;

                    sign = vp56_rac_get(c);

                    coeff = 1;

                }

                coeff = (coeff ^ -sign) + sign;

                if (coeff_idx)

                    coeff *= s->dequant_ac;

                s->block_coeff[b][permute[coeff_idx]] = coeff;

            } else {

                if (ct && !vp56_rac_get_prob_branchy(c, model2[1]))

                    break;

                ct = 0;

                s->coeff_ctx[ff_vp56_b6to4[b]][coeff_idx] = 0;

            }

            coeff_idx++;

            if (coeff_idx >= 64)

                break;



            cg = vp5_coeff_groups[coeff_idx];

            ctx = s->coeff_ctx[ff_vp56_b6to4[b]][coeff_idx];

            model1 = model->coeff_ract[pt][ct][cg];

            model2 = cg > 2 ? model1 : model->coeff_acct[pt][ct][cg][ctx];

        }



        ctx_last = FFMIN(s->coeff_ctx_last[ff_vp56_b6to4[b]], 24);

        s->coeff_ctx_last[ff_vp56_b6to4[b]] = coeff_idx;

        if (coeff_idx < ctx_last)

            for (i=coeff_idx; i<=ctx_last; i++)

                s->coeff_ctx[ff_vp56_b6to4[b]][i] = 5;

        s->above_blocks[s->above_block_idx[b]].not_null_dc = s->coeff_ctx[ff_vp56_b6to4[b]][0];

    }

}

