static inline void RENAME(yuy2toyv12)(const uint8_t *src, uint8_t *ydst, uint8_t *udst, uint8_t *vdst,

	long width, long height,

	long lumStride, long chromStride, long srcStride)

{

	long y;

	const long chromWidth= width>>1;

	for(y=0; y<height; y+=2)

	{

#ifdef HAVE_MMX

		asm volatile(

			"xor %%"REG_a", %%"REG_a"	\n\t"

			"pcmpeqw %%mm7, %%mm7		\n\t"

			"psrlw $8, %%mm7		\n\t" // FF,00,FF,00...

			ASMALIGN16

			"1:				\n\t"

			PREFETCH" 64(%0, %%"REG_a", 4)	\n\t"

			"movq (%0, %%"REG_a", 4), %%mm0	\n\t" // YUYV YUYV(0)

			"movq 8(%0, %%"REG_a", 4), %%mm1\n\t" // YUYV YUYV(4)

			"movq %%mm0, %%mm2		\n\t" // YUYV YUYV(0)

			"movq %%mm1, %%mm3		\n\t" // YUYV YUYV(4)

			"psrlw $8, %%mm0		\n\t" // U0V0 U0V0(0)

			"psrlw $8, %%mm1		\n\t" // U0V0 U0V0(4)

			"pand %%mm7, %%mm2		\n\t" // Y0Y0 Y0Y0(0)

			"pand %%mm7, %%mm3		\n\t" // Y0Y0 Y0Y0(4)

			"packuswb %%mm1, %%mm0		\n\t" // UVUV UVUV(0)

			"packuswb %%mm3, %%mm2		\n\t" // YYYY YYYY(0)



			MOVNTQ" %%mm2, (%1, %%"REG_a", 2)\n\t"



			"movq 16(%0, %%"REG_a", 4), %%mm1\n\t" // YUYV YUYV(8)

			"movq 24(%0, %%"REG_a", 4), %%mm2\n\t" // YUYV YUYV(12)

			"movq %%mm1, %%mm3		\n\t" // YUYV YUYV(8)

			"movq %%mm2, %%mm4		\n\t" // YUYV YUYV(12)

			"psrlw $8, %%mm1		\n\t" // U0V0 U0V0(8)

			"psrlw $8, %%mm2		\n\t" // U0V0 U0V0(12)

			"pand %%mm7, %%mm3		\n\t" // Y0Y0 Y0Y0(8)

			"pand %%mm7, %%mm4		\n\t" // Y0Y0 Y0Y0(12)

			"packuswb %%mm2, %%mm1		\n\t" // UVUV UVUV(8)

			"packuswb %%mm4, %%mm3		\n\t" // YYYY YYYY(8)



			MOVNTQ" %%mm3, 8(%1, %%"REG_a", 2)\n\t"



			"movq %%mm0, %%mm2		\n\t" // UVUV UVUV(0)

			"movq %%mm1, %%mm3		\n\t" // UVUV UVUV(8)

			"psrlw $8, %%mm0		\n\t" // V0V0 V0V0(0)

			"psrlw $8, %%mm1		\n\t" // V0V0 V0V0(8)

			"pand %%mm7, %%mm2		\n\t" // U0U0 U0U0(0)

			"pand %%mm7, %%mm3		\n\t" // U0U0 U0U0(8)

			"packuswb %%mm1, %%mm0		\n\t" // VVVV VVVV(0)

			"packuswb %%mm3, %%mm2		\n\t" // UUUU UUUU(0)



			MOVNTQ" %%mm0, (%3, %%"REG_a")	\n\t"

			MOVNTQ" %%mm2, (%2, %%"REG_a")	\n\t"



			"add $8, %%"REG_a"		\n\t"

			"cmp %4, %%"REG_a"		\n\t"

			" jb 1b				\n\t"

			::"r"(src), "r"(ydst), "r"(udst), "r"(vdst), "g" (chromWidth)

			: "memory", "%"REG_a

		);



		ydst += lumStride;

		src  += srcStride;



		asm volatile(

			"xor %%"REG_a", %%"REG_a"	\n\t"

			ASMALIGN16

			"1:				\n\t"

			PREFETCH" 64(%0, %%"REG_a", 4)	\n\t"

			"movq (%0, %%"REG_a", 4), %%mm0	\n\t" // YUYV YUYV(0)

			"movq 8(%0, %%"REG_a", 4), %%mm1\n\t" // YUYV YUYV(4)

			"movq 16(%0, %%"REG_a", 4), %%mm2\n\t" // YUYV YUYV(8)

			"movq 24(%0, %%"REG_a", 4), %%mm3\n\t" // YUYV YUYV(12)

			"pand %%mm7, %%mm0		\n\t" // Y0Y0 Y0Y0(0)

			"pand %%mm7, %%mm1		\n\t" // Y0Y0 Y0Y0(4)

			"pand %%mm7, %%mm2		\n\t" // Y0Y0 Y0Y0(8)

			"pand %%mm7, %%mm3		\n\t" // Y0Y0 Y0Y0(12)

			"packuswb %%mm1, %%mm0		\n\t" // YYYY YYYY(0)

			"packuswb %%mm3, %%mm2		\n\t" // YYYY YYYY(8)



			MOVNTQ" %%mm0, (%1, %%"REG_a", 2)\n\t"

			MOVNTQ" %%mm2, 8(%1, %%"REG_a", 2)\n\t"



			"add $8, %%"REG_a"		\n\t"

			"cmp %4, %%"REG_a"		\n\t"

			" jb 1b				\n\t"



			::"r"(src), "r"(ydst), "r"(udst), "r"(vdst), "g" (chromWidth)

			: "memory", "%"REG_a

		);

#else

		long i;

		for(i=0; i<chromWidth; i++)

		{

			ydst[2*i+0] 	= src[4*i+0];

			udst[i] 	= src[4*i+1];

			ydst[2*i+1] 	= src[4*i+2];

			vdst[i] 	= src[4*i+3];

		}

		ydst += lumStride;

		src  += srcStride;



		for(i=0; i<chromWidth; i++)

		{

			ydst[2*i+0] 	= src[4*i+0];

			ydst[2*i+1] 	= src[4*i+2];

		}

#endif

		udst += chromStride;

		vdst += chromStride;

		ydst += lumStride;

		src  += srcStride;

	}

#ifdef HAVE_MMX

asm volatile(   EMMS" \n\t"

        	SFENCE" \n\t"

        	:::"memory");

#endif

}

static int qtrle_decode_init(AVCodecContext *avctx)

{

    QtrleContext *s = avctx->priv_data;



    s->avctx = avctx;

    switch (avctx->bits_per_sample) {

    case 1:

    case 2:

    case 4:

    case 8:

    case 33:

    case 34:

    case 36:

    case 40:

        avctx->pix_fmt = PIX_FMT_PAL8;

        break;



    case 16:

        avctx->pix_fmt = PIX_FMT_RGB555;

        break;



    case 24:

        avctx->pix_fmt = PIX_FMT_RGB24;

        break;



    case 32:

        avctx->pix_fmt = PIX_FMT_RGB32;

        break;



    default:

        av_log (avctx, AV_LOG_ERROR, "Unsupported colorspace: %d bits/sample?\n",

            avctx->bits_per_sample);

        break;

    }

    dsputil_init(&s->dsp, avctx);



    s->frame.data[0] = NULL;



    return 0;

}

void vp8_mc_part(VP8Context *s, uint8_t *dst[3],

                 AVFrame *ref_frame, int x_off, int y_off,

                 int bx_off, int by_off,

                 int block_w, int block_h,

                 int width, int height, VP56mv *mv)

{

    VP56mv uvmv = *mv;



    /* Y */

    vp8_mc(s, 1, dst[0] + by_off * s->linesize + bx_off,

           ref_frame->data[0], mv, x_off + bx_off, y_off + by_off,

           block_w, block_h, width, height, s->linesize,

           s->put_pixels_tab[block_w == 8]);



    /* U/V */

    if (s->profile == 3) {

        uvmv.x &= ~7;

        uvmv.y &= ~7;

    }

    x_off   >>= 1; y_off   >>= 1;

    bx_off  >>= 1; by_off  >>= 1;

    width   >>= 1; height  >>= 1;

    block_w >>= 1; block_h >>= 1;

    vp8_mc(s, 0, dst[1] + by_off * s->uvlinesize + bx_off,

           ref_frame->data[1], &uvmv, x_off + bx_off, y_off + by_off,

           block_w, block_h, width, height, s->uvlinesize,

           s->put_pixels_tab[1 + (block_w == 4)]);

    vp8_mc(s, 0, dst[2] + by_off * s->uvlinesize + bx_off,

           ref_frame->data[2], &uvmv, x_off + bx_off, y_off + by_off,

           block_w, block_h, width, height, s->uvlinesize,

           s->put_pixels_tab[1 + (block_w == 4)]);

}

static int decode_p_frame(FourXContext *f, const uint8_t *buf, int length){

    int x, y;

    const int width= f->avctx->width;

    const int height= f->avctx->height;

    uint16_t *src= (uint16_t*)f->last_picture.data[0];

    uint16_t *dst= (uint16_t*)f->current_picture.data[0];

    const int stride= f->current_picture.linesize[0]>>1;

    unsigned int bitstream_size, bytestream_size, wordstream_size, extra;



    if(f->version>1){

        extra=20;

        bitstream_size= AV_RL32(buf+8);

        wordstream_size= AV_RL32(buf+12);

        bytestream_size= AV_RL32(buf+16);

    }else{

        extra=0;

        bitstream_size = AV_RL16(buf-4);

        wordstream_size= AV_RL16(buf-2);

        bytestream_size= FFMAX(length - bitstream_size - wordstream_size, 0);

    }



    if(bitstream_size+ bytestream_size+ wordstream_size + extra != length

       || bitstream_size  > (1<<26)

       || bytestream_size > (1<<26)

       || wordstream_size > (1<<26)

       ){

        av_log(f->avctx, AV_LOG_ERROR, "lengths %d %d %d %d\n", bitstream_size, bytestream_size, wordstream_size,

        bitstream_size+ bytestream_size+ wordstream_size - length);

        return -1;

    }



    av_fast_malloc(&f->bitstream_buffer, &f->bitstream_buffer_size, bitstream_size + FF_INPUT_BUFFER_PADDING_SIZE);

    if (!f->bitstream_buffer)

        return AVERROR(ENOMEM);

    f->dsp.bswap_buf(f->bitstream_buffer, (const uint32_t*)(buf + extra), bitstream_size/4);

    memset((uint8_t*)f->bitstream_buffer + bitstream_size, 0, FF_INPUT_BUFFER_PADDING_SIZE);

    init_get_bits(&f->gb, f->bitstream_buffer, 8*bitstream_size);



    f->wordstream= (const uint16_t*)(buf + extra + bitstream_size);

    f->bytestream= buf + extra + bitstream_size + wordstream_size;



    init_mv(f);



    for(y=0; y<height; y+=8){

        for(x=0; x<width; x+=8){

            decode_p_block(f, dst + x, src + x, 3, 3, stride);

        }

        src += 8*stride;

        dst += 8*stride;

    }



    if(   bitstream_size != (get_bits_count(&f->gb)+31)/32*4

       || (((const char*)f->wordstream - (const char*)buf + 2)&~2) != extra + bitstream_size + wordstream_size

       || (((const char*)f->bytestream - (const char*)buf + 3)&~3) != extra + bitstream_size + wordstream_size + bytestream_size)

        av_log(f->avctx, AV_LOG_ERROR, " %d %td %td bytes left\n",

            bitstream_size - (get_bits_count(&f->gb)+31)/32*4,

            -(((const char*)f->bytestream - (const char*)buf + 3)&~3) + (extra + bitstream_size + wordstream_size + bytestream_size),

            -(((const char*)f->wordstream - (const char*)buf + 2)&~2) + (extra + bitstream_size + wordstream_size)

        );



    return 0;

}

static inline int halfpel_motion_search(MpegEncContext * s,

				  int *mx_ptr, int *my_ptr, int dmin,

				  int xmin, int ymin, int xmax, int ymax,

                                  int pred_x, int pred_y, uint8_t *ref_picture)

{

    UINT16 *mv_penalty= s->mv_penalty[s->f_code] + MAX_MV; // f_code of the prev frame

    const int quant= s->qscale;

    int pen_x, pen_y;

    int mx, my, mx1, my1, d, xx, yy, dminh;

    UINT8 *pix, *ptr;



    mx = *mx_ptr;

    my = *my_ptr;

    ptr = ref_picture + (my * s->linesize) + mx;



    xx = 16 * s->mb_x;

    yy = 16 * s->mb_y;

    pix =  s->new_picture[0] + (yy * s->linesize) + xx;



    dminh = dmin;



    if (mx > xmin && mx < xmax && 

        my > ymin && my < ymax) {



        mx= mx1= 2*(mx - xx);

        my= my1= 2*(my - yy);

        if(dmin < Z_THRESHOLD && mx==0 && my==0){

            *mx_ptr = 0;

            *my_ptr = 0;

            return dmin;

        }



        pen_x= pred_x + mx;

        pen_y= pred_y + my;



        ptr-= s->linesize;

        CHECK_HALF_MV(xy2, -1, -1)

        CHECK_HALF_MV(y2 ,  0, -1)

        CHECK_HALF_MV(xy2, +1, -1)



        ptr+= s->linesize;

        CHECK_HALF_MV(x2 , -1,  0)

        CHECK_HALF_MV(x2 , +1,  0)

        CHECK_HALF_MV(xy2, -1, +1)

        CHECK_HALF_MV(y2 ,  0, +1)

        CHECK_HALF_MV(xy2, +1, +1)



    }else{

        mx= 2*(mx - xx);

        my= 2*(my - yy);

    }



    *mx_ptr = mx;

    *my_ptr = my;

    return dminh;

}

