static void synthfilt_build_sb_samples (QDM2Context *q, GetBitContext *gb, int length, int sb_min, int sb_max)

{

    int sb, j, k, n, ch, run, channels;

    int joined_stereo, zero_encoding, chs;

    int type34_first;

    float type34_div = 0;

    float type34_predictor;

    float samples[10], sign_bits[16];



    if (length == 0) {

        // If no data use noise

        for (sb=sb_min; sb < sb_max; sb++)

            build_sb_samples_from_noise (q, sb);



        return;

    }



    for (sb = sb_min; sb < sb_max; sb++) {

        FIX_NOISE_IDX(q->noise_idx);



        channels = q->nb_channels;



        if (q->nb_channels <= 1 || sb < 12)

            joined_stereo = 0;

        else if (sb >= 24)

            joined_stereo = 1;

        else

            joined_stereo = (BITS_LEFT(length,gb) >= 1) ? get_bits1 (gb) : 0;



        if (joined_stereo) {

            if (BITS_LEFT(length,gb) >= 16)

                for (j = 0; j < 16; j++)

                    sign_bits[j] = get_bits1 (gb);



            for (j = 0; j < 64; j++)

                if (q->coding_method[1][sb][j] > q->coding_method[0][sb][j])

                    q->coding_method[0][sb][j] = q->coding_method[1][sb][j];



            fix_coding_method_array(sb, q->nb_channels, q->coding_method);

            channels = 1;

        }



        for (ch = 0; ch < channels; ch++) {

            zero_encoding = (BITS_LEFT(length,gb) >= 1) ? get_bits1(gb) : 0;

            type34_predictor = 0.0;

            type34_first = 1;



            for (j = 0; j < 128; ) {

                switch (q->coding_method[ch][sb][j / 2]) {

                    case 8:

                        if (BITS_LEFT(length,gb) >= 10) {

                            if (zero_encoding) {

                                for (k = 0; k < 5; k++) {

                                    if ((j + 2 * k) >= 128)

                                        break;

                                    samples[2 * k] = get_bits1(gb) ? dequant_1bit[joined_stereo][2 * get_bits1(gb)] : 0;

                                }

                            } else {

                                n = get_bits(gb, 8);

                                for (k = 0; k < 5; k++)

                                    samples[2 * k] = dequant_1bit[joined_stereo][random_dequant_index[n][k]];

                            }

                            for (k = 0; k < 5; k++)

                                samples[2 * k + 1] = SB_DITHERING_NOISE(sb,q->noise_idx);

                        } else {

                            for (k = 0; k < 10; k++)

                                samples[k] = SB_DITHERING_NOISE(sb,q->noise_idx);

                        }

                        run = 10;

                        break;



                    case 10:

                        if (BITS_LEFT(length,gb) >= 1) {

                            float f = 0.81;



                            if (get_bits1(gb))

                                f = -f;

                            f -= noise_samples[((sb + 1) * (j +5 * ch + 1)) & 127] * 9.0 / 40.0;

                            samples[0] = f;

                        } else {

                            samples[0] = SB_DITHERING_NOISE(sb,q->noise_idx);

                        }

                        run = 1;

                        break;



                    case 16:

                        if (BITS_LEFT(length,gb) >= 10) {

                            if (zero_encoding) {

                                for (k = 0; k < 5; k++) {

                                    if ((j + k) >= 128)

                                        break;

                                    samples[k] = (get_bits1(gb) == 0) ? 0 : dequant_1bit[joined_stereo][2 * get_bits1(gb)];

                                }

                            } else {

                                n = get_bits (gb, 8);

                                for (k = 0; k < 5; k++)

                                    samples[k] = dequant_1bit[joined_stereo][random_dequant_index[n][k]];

                            }

                        } else {

                            for (k = 0; k < 5; k++)

                                samples[k] = SB_DITHERING_NOISE(sb,q->noise_idx);

                        }

                        run = 5;

                        break;



                    case 24:

                        if (BITS_LEFT(length,gb) >= 7) {

                            n = get_bits(gb, 7);

                            for (k = 0; k < 3; k++)

                                samples[k] = (random_dequant_type24[n][k] - 2.0) * 0.5;

                        } else {

                            for (k = 0; k < 3; k++)

                                samples[k] = SB_DITHERING_NOISE(sb,q->noise_idx);

                        }

                        run = 3;

                        break;



                    case 30:

                        if (BITS_LEFT(length,gb) >= 4)

                            samples[0] = type30_dequant[qdm2_get_vlc(gb, &vlc_tab_type30, 0, 1)];

                        else

                            samples[0] = SB_DITHERING_NOISE(sb,q->noise_idx);



                        run = 1;

                        break;



                    case 34:

                        if (BITS_LEFT(length,gb) >= 7) {

                            if (type34_first) {

                                type34_div = (float)(1 << get_bits(gb, 2));

                                samples[0] = ((float)get_bits(gb, 5) - 16.0) / 15.0;

                                type34_predictor = samples[0];

                                type34_first = 0;

                            } else {

                                samples[0] = type34_delta[qdm2_get_vlc(gb, &vlc_tab_type34, 0, 1)] / type34_div + type34_predictor;

                                type34_predictor = samples[0];

                            }

                        } else {

                            samples[0] = SB_DITHERING_NOISE(sb,q->noise_idx);

                        }

                        run = 1;

                        break;



                    default:

                        samples[0] = SB_DITHERING_NOISE(sb,q->noise_idx);

                        run = 1;

                        break;

                }



                if (joined_stereo) {

                    float tmp[10][MPA_MAX_CHANNELS];



                    for (k = 0; k < run; k++) {

                        tmp[k][0] = samples[k];

                        tmp[k][1] = (sign_bits[(j + k) / 8]) ? -samples[k] : samples[k];

                    }

                    for (chs = 0; chs < q->nb_channels; chs++)

                        for (k = 0; k < run; k++)

                            if ((j + k) < 128)

                                q->sb_samples[chs][j + k][sb] = q->tone_level[chs][sb][((j + k)/2)] * tmp[k][chs];

                } else {

                    for (k = 0; k < run; k++)

                        if ((j + k) < 128)

                            q->sb_samples[ch][j + k][sb] = q->tone_level[ch][sb][(j + k)/2] * samples[k];

                }



                j += run;

            } // j loop

        } // channel loop

    } // subband loop

}

static void opt_target(const char *arg)

{

    enum { PAL, NTSC, FILM, UNKNOWN } norm = UNKNOWN;

    static const char *const frame_rates[] = {"25", "30000/1001", "24000/1001"};



    if(!strncmp(arg, "pal-", 4)) {

        norm = PAL;

        arg += 4;

    } else if(!strncmp(arg, "ntsc-", 5)) {

        norm = NTSC;

        arg += 5;

    } else if(!strncmp(arg, "film-", 5)) {

        norm = FILM;

        arg += 5;

    } else {

        int fr;

        /* Calculate FR via float to avoid int overflow */

        fr = (int)(frame_rate.num * 1000.0 / frame_rate.den);

        if(fr == 25000) {

            norm = PAL;

        } else if((fr == 29970) || (fr == 23976)) {

            norm = NTSC;

        } else {

            /* Try to determine PAL/NTSC by peeking in the input files */

            if(nb_input_files) {

                int i, j;

                for(j = 0; j < nb_input_files; j++) {

                    for(i = 0; i < input_files[j]->nb_streams; i++) {

                        AVCodecContext *c = input_files[j]->streams[i]->codec;

                        if(c->codec_type != AVMEDIA_TYPE_VIDEO)

                            continue;

                        fr = c->time_base.den * 1000 / c->time_base.num;

                        if(fr == 25000) {

                            norm = PAL;

                            break;

                        } else if((fr == 29970) || (fr == 23976)) {

                            norm = NTSC;

                            break;

                        }

                    }

                    if(norm != UNKNOWN)

                        break;

                }

            }

        }

        if(verbose && norm != UNKNOWN)

            fprintf(stderr, "Assuming %s for target.\n", norm == PAL ? "PAL" : "NTSC");

    }



    if(norm == UNKNOWN) {

        fprintf(stderr, "Could not determine norm (PAL/NTSC/NTSC-Film) for target.\n");

        fprintf(stderr, "Please prefix target with \"pal-\", \"ntsc-\" or \"film-\",\n");

        fprintf(stderr, "or set a framerate with \"-r xxx\".\n");

        ffmpeg_exit(1);

    }



    if(!strcmp(arg, "vcd")) {



        opt_video_codec("mpeg1video");

        opt_audio_codec("mp2");

        opt_format("vcd");



        opt_frame_size(norm == PAL ? "352x288" : "352x240");

        opt_frame_rate(NULL, frame_rates[norm]);

        opt_default("g", norm == PAL ? "15" : "18");



        opt_default("b", "1150000");

        opt_default("maxrate", "1150000");

        opt_default("minrate", "1150000");

        opt_default("bufsize", "327680"); // 40*1024*8;



        opt_default("ab", "224000");

        audio_sample_rate = 44100;

        audio_channels = 2;



        opt_default("packetsize", "2324");

        opt_default("muxrate", "1411200"); // 2352 * 75 * 8;



        /* We have to offset the PTS, so that it is consistent with the SCR.

           SCR starts at 36000, but the first two packs contain only padding

           and the first pack from the other stream, respectively, may also have

           been written before.

           So the real data starts at SCR 36000+3*1200. */

        mux_preload= (36000+3*1200) / 90000.0; //0.44

    } else if(!strcmp(arg, "svcd")) {



        opt_video_codec("mpeg2video");

        opt_audio_codec("mp2");

        opt_format("svcd");



        opt_frame_size(norm == PAL ? "480x576" : "480x480");

        opt_frame_rate(NULL, frame_rates[norm]);

        opt_default("g", norm == PAL ? "15" : "18");



        opt_default("b", "2040000");

        opt_default("maxrate", "2516000");

        opt_default("minrate", "0"); //1145000;

        opt_default("bufsize", "1835008"); //224*1024*8;

        opt_default("flags", "+scan_offset");





        opt_default("ab", "224000");

        audio_sample_rate = 44100;



        opt_default("packetsize", "2324");



    } else if(!strcmp(arg, "dvd")) {



        opt_video_codec("mpeg2video");

        opt_audio_codec("ac3");

        opt_format("dvd");



        opt_frame_size(norm == PAL ? "720x576" : "720x480");

        opt_frame_rate(NULL, frame_rates[norm]);

        opt_default("g", norm == PAL ? "15" : "18");



        opt_default("b", "6000000");

        opt_default("maxrate", "9000000");

        opt_default("minrate", "0"); //1500000;

        opt_default("bufsize", "1835008"); //224*1024*8;



        opt_default("packetsize", "2048");  // from www.mpucoder.com: DVD sectors contain 2048 bytes of data, this is also the size of one pack.

        opt_default("muxrate", "10080000"); // from mplex project: data_rate = 1260000. mux_rate = data_rate * 8



        opt_default("ab", "448000");

        audio_sample_rate = 48000;



    } else if(!strncmp(arg, "dv", 2)) {



        opt_format("dv");



        opt_frame_size(norm == PAL ? "720x576" : "720x480");

        opt_frame_pix_fmt(!strncmp(arg, "dv50", 4) ? "yuv422p" :

                          (norm == PAL ? "yuv420p" : "yuv411p"));

        opt_frame_rate(NULL, frame_rates[norm]);



        audio_sample_rate = 48000;

        audio_channels = 2;



    } else {

        fprintf(stderr, "Unknown target: %s\n", arg);

        ffmpeg_exit(1);

    }

}

static int decode_init(AVCodecContext *avctx)

{

    LclContext * const c = (LclContext *)avctx->priv_data;

    int basesize = avctx->width * avctx->height;

    int zret; // Zlib return code



    c->avctx = avctx;

    avctx->has_b_frames = 0;



    c->pic.data[0] = NULL;



#ifdef CONFIG_ZLIB

    // Needed if zlib unused or init aborted before inflateInit

    memset(&(c->zstream), 0, sizeof(z_stream)); 

#endif



    if (avctx->extradata_size < 8) {

        av_log(avctx, AV_LOG_ERROR, "Extradata size too small.\n");

        return 1;

    }



    /* Check codec type */ 

    if (((avctx->codec_id == CODEC_ID_MSZH)  && (*((char *)avctx->extradata + 7) != CODEC_MSZH)) ||

        ((avctx->codec_id == CODEC_ID_ZLIB)  && (*((char *)avctx->extradata + 7) != CODEC_ZLIB))) {

        av_log(avctx, AV_LOG_ERROR, "Codec id and codec type mismatch. This should not happen.\n");

    }



    /* Detect image type */

    switch (c->imgtype = *((char *)avctx->extradata + 4)) {

        case IMGTYPE_YUV111:

            c->decomp_size = basesize * 3;

            av_log(avctx, AV_LOG_INFO, "Image type is YUV 1:1:1.\n");

            break;

        case IMGTYPE_YUV422:

            c->decomp_size = basesize * 2;

            av_log(avctx, AV_LOG_INFO, "Image type is YUV 4:2:2.\n");

            break;

        case IMGTYPE_RGB24:

            c->decomp_size = basesize * 3;

            av_log(avctx, AV_LOG_INFO, "Image type is RGB 24.\n");

            break;

        case IMGTYPE_YUV411:

            c->decomp_size = basesize / 2 * 3;

            av_log(avctx, AV_LOG_INFO, "Image type is YUV 4:1:1.\n");

            break;

        case IMGTYPE_YUV211:

            c->decomp_size = basesize * 2;

            av_log(avctx, AV_LOG_INFO, "Image type is YUV 2:1:1.\n");

            break;

        case IMGTYPE_YUV420:

            c->decomp_size = basesize / 2 * 3;

            av_log(avctx, AV_LOG_INFO, "Image type is YUV 4:2:0.\n");

            break;

        default:

            av_log(avctx, AV_LOG_ERROR, "Unsupported image format %d.\n", c->imgtype);

            return 1;

    }



    /* Detect compression method */

    c->compression = *((char *)avctx->extradata + 5);

    switch (avctx->codec_id) {

        case CODEC_ID_MSZH:

            switch (c->compression) {

                case COMP_MSZH:

                    av_log(avctx, AV_LOG_INFO, "Compression enabled.\n");

                    break;

                case COMP_MSZH_NOCOMP:

                    c->decomp_size = 0;

                    av_log(avctx, AV_LOG_INFO, "No compression.\n");

                    break;

                default:

                    av_log(avctx, AV_LOG_ERROR, "Unsupported compression format for MSZH (%d).\n", c->compression);

                    return 1;

            }

            break;

        case CODEC_ID_ZLIB:

#ifdef CONFIG_ZLIB

            switch (c->compression) {

                case COMP_ZLIB_HISPEED:

                    av_log(avctx, AV_LOG_INFO, "High speed compression.\n");

                    break;

                case COMP_ZLIB_HICOMP:

                    av_log(avctx, AV_LOG_INFO, "High compression.\n");

                    break;

                case COMP_ZLIB_NORMAL:

                    av_log(avctx, AV_LOG_INFO, "Normal compression.\n");

                    break;

                default:

                    if ((c->compression < Z_NO_COMPRESSION) || (c->compression > Z_BEST_COMPRESSION)) {

                	    av_log(avctx, AV_LOG_ERROR, "Unusupported compression level for ZLIB: (%d).\n", c->compression);

                        return 1;

                    }

                    av_log(avctx, AV_LOG_INFO, "Compression level for ZLIB: (%d).\n", c->compression);

            }

#else

            av_log(avctx, AV_LOG_ERROR, "Zlib support not compiled.\n");

            return 1;

#endif

            break;

        default:

            av_log(avctx, AV_LOG_ERROR, "BUG! Unknown codec in compression switch.\n");

            return 1;

    }



    /* Allocate decompression buffer */

    /* 4*8 max overflow space for mszh decomp algorithm */

    if (c->decomp_size) {

        if ((c->decomp_buf = av_malloc(c->decomp_size+4*8)) == NULL) {

            av_log(avctx, AV_LOG_ERROR, "Can't allocate decompression buffer.\n");

            return 1;

        }

    }



    /* Detect flags */ 

    c->flags = *((char *)avctx->extradata + 6);

    if (c->flags & FLAG_MULTITHREAD)

        av_log(avctx, AV_LOG_INFO, "Multithread encoder flag set.\n");

    if (c->flags & FLAG_NULLFRAME)

        av_log(avctx, AV_LOG_INFO, "Nullframe insertion flag set.\n");

    if ((avctx->codec_id == CODEC_ID_ZLIB) && (c->flags & FLAG_PNGFILTER))

        av_log(avctx, AV_LOG_INFO, "PNG filter flag set.\n");

    if (c->flags & FLAGMASK_UNUSED)

        av_log(avctx, AV_LOG_ERROR, "Unknown flag set (%d).\n", c->flags);



    /* If needed init zlib */

    if (avctx->codec_id == CODEC_ID_ZLIB) {

#ifdef CONFIG_ZLIB

        c->zstream.zalloc = Z_NULL;

        c->zstream.zfree = Z_NULL;

        c->zstream.opaque = Z_NULL;

        zret = inflateInit(&(c->zstream));

        if (zret != Z_OK) {

            av_log(avctx, AV_LOG_ERROR, "Inflate init error: %d\n", zret);

            return 1;

        }

#else

    av_log(avctx, AV_LOG_ERROR, "Zlib support not compiled.\n");

    return 1;

#endif

    }



    avctx->pix_fmt = PIX_FMT_BGR24;



    return 0;

}

static void use_high_update_speed(WmallDecodeCtx *s, int ich)

{

    int ilms, recent, icoef;

    s->update_speed[ich] = 16;

    for (ilms = s->cdlms_ttl[ich]; ilms >= 0; ilms--) {

        recent = s->cdlms[ich][ilms].recent;

        if (s->bV3RTM) {

            for (icoef = 0; icoef < s->cdlms[ich][ilms].order; icoef++)

                s->cdlms[ich][ilms].lms_updates[icoef + recent] *= 2;

        } else {

            for (icoef = 0; icoef < s->cdlms[ich][ilms].order; icoef++)

                s->cdlms[ich][ilms].lms_updates[icoef] *= 2;

        }

    }

}

void ff_estimate_b_frame_motion(MpegEncContext * s,

                             int mb_x, int mb_y)

{

    MotionEstContext * const c= &s->me;

    const int penalty_factor= c->mb_penalty_factor;

    int fmin, bmin, dmin, fbmin, bimin, fimin;

    int type=0;

    const int xy = mb_y*s->mb_stride + mb_x;

    init_ref(c, s->new_picture.f->data, s->last_picture.f->data,

             s->next_picture.f->data, 16 * mb_x, 16 * mb_y, 2);



    get_limits(s, 16*mb_x, 16*mb_y);



    c->skip=0;



    if (s->codec_id == AV_CODEC_ID_MPEG4 && s->next_picture.mbskip_table[xy]) {

        int score= direct_search(s, mb_x, mb_y); //FIXME just check 0,0



        score= ((unsigned)(score*score + 128*256))>>16;

        c->mc_mb_var_sum_temp += score;

        s->current_picture.mc_mb_var[mb_y*s->mb_stride + mb_x] = score; //FIXME use SSE

        s->mb_type[mb_y*s->mb_stride + mb_x]= CANDIDATE_MB_TYPE_DIRECT0;



        return;

    }



    if (s->codec_id == AV_CODEC_ID_MPEG4)

        dmin= direct_search(s, mb_x, mb_y);

    else

        dmin= INT_MAX;

//FIXME penalty stuff for non mpeg4

    c->skip=0;

    fmin = estimate_motion_b(s, mb_x, mb_y, s->b_forw_mv_table, 0, s->f_code) +

           3 * penalty_factor;



    c->skip=0;

    bmin = estimate_motion_b(s, mb_x, mb_y, s->b_back_mv_table, 2, s->b_code) +

           2 * penalty_factor;

    ff_dlog(s, " %d %d ", s->b_forw_mv_table[xy][0], s->b_forw_mv_table[xy][1]);



    c->skip=0;

    fbmin= bidir_refine(s, mb_x, mb_y) + penalty_factor;

    ff_dlog(s, "%d %d %d %d\n", dmin, fmin, bmin, fbmin);



    if (s->avctx->flags & AV_CODEC_FLAG_INTERLACED_ME) {

//FIXME mb type penalty

        c->skip=0;

        c->current_mv_penalty= c->mv_penalty[s->f_code] + MAX_MV;

        fimin= interlaced_search(s, 0,

                                 s->b_field_mv_table[0], s->b_field_select_table[0],

                                 s->b_forw_mv_table[xy][0], s->b_forw_mv_table[xy][1], 0);

        c->current_mv_penalty= c->mv_penalty[s->b_code] + MAX_MV;

        bimin= interlaced_search(s, 2,

                                 s->b_field_mv_table[1], s->b_field_select_table[1],

                                 s->b_back_mv_table[xy][0], s->b_back_mv_table[xy][1], 0);

    }else

        fimin= bimin= INT_MAX;



    {

        int score= fmin;

        type = CANDIDATE_MB_TYPE_FORWARD;



        if (dmin <= score){

            score = dmin;

            type = CANDIDATE_MB_TYPE_DIRECT;

        }

        if(bmin<score){

            score=bmin;

            type= CANDIDATE_MB_TYPE_BACKWARD;

        }

        if(fbmin<score){

            score=fbmin;

            type= CANDIDATE_MB_TYPE_BIDIR;

        }

        if(fimin<score){

            score=fimin;

            type= CANDIDATE_MB_TYPE_FORWARD_I;

        }

        if(bimin<score){

            score=bimin;

            type= CANDIDATE_MB_TYPE_BACKWARD_I;

        }



        score= ((unsigned)(score*score + 128*256))>>16;

        c->mc_mb_var_sum_temp += score;

        s->current_picture.mc_mb_var[mb_y*s->mb_stride + mb_x] = score; //FIXME use SSE

    }



    if(c->avctx->mb_decision > FF_MB_DECISION_SIMPLE){

        type= CANDIDATE_MB_TYPE_FORWARD | CANDIDATE_MB_TYPE_BACKWARD | CANDIDATE_MB_TYPE_BIDIR | CANDIDATE_MB_TYPE_DIRECT;

        if(fimin < INT_MAX)

            type |= CANDIDATE_MB_TYPE_FORWARD_I;

        if(bimin < INT_MAX)

            type |= CANDIDATE_MB_TYPE_BACKWARD_I;

        if(fimin < INT_MAX && bimin < INT_MAX){

            type |= CANDIDATE_MB_TYPE_BIDIR_I;

        }

         //FIXME something smarter

        if(dmin>256*256*16) type&= ~CANDIDATE_MB_TYPE_DIRECT; //do not try direct mode if it is invalid for this MB

        if (s->codec_id == AV_CODEC_ID_MPEG4 && type&CANDIDATE_MB_TYPE_DIRECT &&

            s->mpv_flags & FF_MPV_FLAG_MV0 && *(uint32_t*)s->b_direct_mv_table[xy])

            type |= CANDIDATE_MB_TYPE_DIRECT0;

    }



    s->mb_type[mb_y*s->mb_stride + mb_x]= type;

}

static inline int mpeg4_decode_dc(MpegEncContext * s, int n, int *dir_ptr)

{

    int level, pred, code;

    uint16_t *dc_val;



    if (n < 4) 

        code = get_vlc2(&s->gb, dc_lum.table, DC_VLC_BITS, 1);

    else 

        code = get_vlc2(&s->gb, dc_chrom.table, DC_VLC_BITS, 1);

    if (code < 0 || code > 9 /* && s->nbit<9 */){

        fprintf(stderr, "illegal dc vlc\n");

        return -1;

    }

    if (code == 0) {

        level = 0;

    } else {

        level = get_xbits(&s->gb, code);

        if (code > 8){

            if(get_bits1(&s->gb)==0){ /* marker */

                if(s->error_resilience>=2){

                    fprintf(stderr, "dc marker bit missing\n");

                    return -1;

                }

            }

        }

    }

    pred = ff_mpeg4_pred_dc(s, n, &dc_val, dir_ptr);

    level += pred;

    if (level < 0){

        if(s->error_resilience>=3){

            fprintf(stderr, "dc<0 at %dx%d\n", s->mb_x, s->mb_y);

            return -1;

        }

        level = 0;

    }

    if (n < 4) {

        *dc_val = level * s->y_dc_scale;

    } else {

        *dc_val = level * s->c_dc_scale;

    }

    if(s->error_resilience>=3){

        if(*dc_val > 2048 + s->y_dc_scale + s->c_dc_scale){

            fprintf(stderr, "dc overflow at %dx%d\n", s->mb_x, s->mb_y);

            return -1;

        }

    }

    return level;

}

static void check_pred8x8(H264PredContext *h, uint8_t *buf0, uint8_t *buf1,

                          int codec, int chroma_format, int bit_depth)

{

