}

static void RENAME(yuv2bgr24_2)(SwsContext *c, const uint16_t *buf0,

                                const uint16_t *buf1, const uint16_t *ubuf0,

                                const uint16_t *ubuf1, const uint16_t *vbuf0,

                                const uint16_t *vbuf1, const uint16_t *abuf0,

                                const uint16_t *abuf1, uint8_t *dest,

                                int dstW, int yalpha, int uvalpha, int y)

{

    //Note 8280 == DSTW_OFFSET but the preprocessor can't handle that there :(

    __asm__ volatile(

        "mov %%"REG_b", "ESP_OFFSET"(%5)        \n\t"

        "mov        %4, %%"REG_b"               \n\t"

        "push %%"REG_BP"                        \n\t"

        YSCALEYUV2RGB(%%REGBP, %5)

        "pxor    %%mm7, %%mm7                   \n\t"

        WRITEBGR24(%%REGb, 8280(%5), %%REGBP)

        "pop %%"REG_BP"                         \n\t"

        "mov "ESP_OFFSET"(%5), %%"REG_b"        \n\t"

        :: "c" (buf0), "d" (buf1), "S" (ubuf0), "D" (ubuf1), "m" (dest),

           "a" (&c->redDither)

    );

}

static void filter_mb( H264Context *h, int mb_x, int mb_y, uint8_t *img_y, uint8_t *img_cb, uint8_t *img_cr) {

    MpegEncContext * const s = &h->s;

    const int mb_xy= mb_x + mb_y*s->mb_stride;

    int linesize, uvlinesize;

    int dir;



    /* FIXME Implement deblocking filter for field MB */

    if( h->sps.mb_aff ) {

        return;

    }

    linesize = s->linesize;

    uvlinesize = s->uvlinesize;



    /* dir : 0 -> vertical edge, 1 -> horizontal edge */

    for( dir = 0; dir < 2; dir++ )

    {

        int edge;

        const int mbm_xy = dir == 0 ? mb_xy -1 : mb_xy - s->mb_stride;

        int start = h->slice_table[mbm_xy] == 255 ? 1 : 0;



        if (h->deblocking_filter==2 && h->slice_table[mbm_xy] != h->slice_table[mb_xy])

            start = 1;



        /* Calculate bS */

        for( edge = start; edge < 4; edge++ ) {

            /* mbn_xy: neighbour macroblock (how that works for field ?) */

            int mbn_xy = edge > 0 ? mb_xy : mbm_xy;

            int bS[4];

            int qp;



            if( IS_INTRA( s->current_picture.mb_type[mb_xy] ) ||

                IS_INTRA( s->current_picture.mb_type[mbn_xy] ) ) {

                bS[0] = bS[1] = bS[2] = bS[3] = ( edge == 0 ? 4 : 3 );

            } else {

                int i;

                for( i = 0; i < 4; i++ ) {

                    int x = dir == 0 ? edge : i;

                    int y = dir == 0 ? i    : edge;

                    int b_idx= 8 + 4 + x + 8*y;

                    int bn_idx= b_idx - (dir ? 8:1);



                    if( h->non_zero_count_cache[b_idx] != 0 ||

                        h->non_zero_count_cache[bn_idx] != 0 ) {

                        bS[i] = 2;

                    }

                    else if( h->slice_type == P_TYPE ) {

                        if( h->ref_cache[0][b_idx] != h->ref_cache[0][bn_idx] ||

                            ABS( h->mv_cache[0][b_idx][0] - h->mv_cache[0][bn_idx][0] ) >= 4 ||

                            ABS( h->mv_cache[0][b_idx][1] - h->mv_cache[0][bn_idx][1] ) >= 4 )

                            bS[i] = 1;

                        else

                            bS[i] = 0;

                    } else {

                        /* FIXME Add support for B frame */

                        return;

                    }

                }



                if(bS[0]+bS[1]+bS[2]+bS[3] == 0)

                    continue;

            }



            /* Filter edge */

            // Do not use s->qscale as luma quantiser because it has not the same

            // value in IPCM macroblocks.

            qp = ( s->current_picture.qscale_table[mb_xy] + s->current_picture.qscale_table[mbn_xy] + 1 ) >> 1;

            //tprintf("filter mb:%d/%d dir:%d edge:%d, QPy:%d, QPc:%d, QPcn:%d\n", mb_x, mb_y, dir, edge, qp, h->chroma_qp, s->current_picture.qscale_table[mbn_xy]);

            if( dir == 0 ) {

                filter_mb_edgev( h, &img_y[4*edge], linesize, bS, qp );

                if( (edge&1) == 0 ) {

                    int chroma_qp = ( h->chroma_qp +

                                      get_chroma_qp( h, s->current_picture.qscale_table[mbn_xy] ) + 1 ) >> 1;

                    filter_mb_edgecv( h, &img_cb[2*edge], uvlinesize, bS, chroma_qp );

                    filter_mb_edgecv( h, &img_cr[2*edge], uvlinesize, bS, chroma_qp );

                }

            } else {

                filter_mb_edgeh( h, &img_y[4*edge*linesize], linesize, bS, qp );

                if( (edge&1) == 0 ) {

                    int chroma_qp = ( h->chroma_qp +

                                      get_chroma_qp( h, s->current_picture.qscale_table[mbn_xy] ) + 1 ) >> 1;

                    filter_mb_edgech( h, &img_cb[2*edge*uvlinesize], uvlinesize, bS, chroma_qp );

                    filter_mb_edgech( h, &img_cr[2*edge*uvlinesize], uvlinesize, bS, chroma_qp );

                }

            }

        }

    }

}

int ff_qsv_encode(AVCodecContext *avctx, QSVEncContext *q,

                  AVPacket *pkt, const AVFrame *frame, int *got_packet)

{

    int ret;



    ret = encode_frame(avctx, q, frame);

    if (ret < 0)

        return ret;



    if (!av_fifo_space(q->async_fifo) ||

        (!frame && av_fifo_size(q->async_fifo))) {

        AVPacket new_pkt;

        mfxBitstream *bs;

        mfxSyncPoint sync;



        av_fifo_generic_read(q->async_fifo, &new_pkt, sizeof(new_pkt), NULL);

        av_fifo_generic_read(q->async_fifo, &sync,    sizeof(sync),    NULL);

        av_fifo_generic_read(q->async_fifo, &bs,      sizeof(bs),      NULL);



        do {

            ret = MFXVideoCORE_SyncOperation(q->session, sync, 1000);

        } while (ret == MFX_WRN_IN_EXECUTION);



        new_pkt.dts  = av_rescale_q(bs->DecodeTimeStamp, (AVRational){1, 90000}, avctx->time_base);

        new_pkt.pts  = av_rescale_q(bs->TimeStamp,       (AVRational){1, 90000}, avctx->time_base);

        new_pkt.size = bs->DataLength;



        if (bs->FrameType & MFX_FRAMETYPE_IDR ||

            bs->FrameType & MFX_FRAMETYPE_xIDR)

            new_pkt.flags |= AV_PKT_FLAG_KEY;



#if FF_API_CODED_FRAME

FF_DISABLE_DEPRECATION_WARNINGS

        if (bs->FrameType & MFX_FRAMETYPE_I || bs->FrameType & MFX_FRAMETYPE_xI)

            avctx->coded_frame->pict_type = AV_PICTURE_TYPE_I;

        else if (bs->FrameType & MFX_FRAMETYPE_P || bs->FrameType & MFX_FRAMETYPE_xP)

            avctx->coded_frame->pict_type = AV_PICTURE_TYPE_P;

        else if (bs->FrameType & MFX_FRAMETYPE_B || bs->FrameType & MFX_FRAMETYPE_xB)

            avctx->coded_frame->pict_type = AV_PICTURE_TYPE_B;

FF_ENABLE_DEPRECATION_WARNINGS

#endif



        av_freep(&bs);



        if (pkt->data) {

            if (pkt->size < new_pkt.size) {

                av_log(avctx, AV_LOG_ERROR, "Submitted buffer not large enough: %d < %d\n",

                       pkt->size, new_pkt.size);

                av_packet_unref(&new_pkt);

                return AVERROR(EINVAL);

            }



            memcpy(pkt->data, new_pkt.data, new_pkt.size);

            pkt->size = new_pkt.size;



            ret = av_packet_copy_props(pkt, &new_pkt);

            av_packet_unref(&new_pkt);

            if (ret < 0)

                return ret;

        } else

            *pkt = new_pkt;



        *got_packet = 1;

    }



    return 0;

}

static int test_vector_dmul_scalar(AVFloatDSPContext *fdsp, AVFloatDSPContext *cdsp,

                                   const double *v1, double scale)

{

    LOCAL_ALIGNED(32, double, cdst, [LEN]);

    LOCAL_ALIGNED(32, double, odst, [LEN]);

    int ret;



    cdsp->vector_dmul_scalar(cdst, v1, scale, LEN);

    fdsp->vector_dmul_scalar(odst, v1, scale, LEN);



    if (ret = compare_doubles(cdst, odst, LEN, DBL_EPSILON))

        av_log(NULL, AV_LOG_ERROR, "vector_dmul_scalar failed\n");



    return ret;

}

static int mpegps_read_pes_header(AVFormatContext *s,

                                  int64_t *ppos, int *pstart_code,

                                  int64_t *ppts, int64_t *pdts)

{

    MpegDemuxContext *m = s->priv_data;

    int len, size, startcode, c, flags, header_len;

    int64_t pts, dts, last_pos;



    last_pos = -1;

 redo:

        /* next start code (should be immediately after) */

        m->header_state = 0xff;

        size = MAX_SYNC_SIZE;

        startcode = find_next_start_code(&s->pb, &size, &m->header_state);

    //printf("startcode=%x pos=0x%"PRIx64"\n", startcode, url_ftell(&s->pb));

    if (startcode < 0)

        return AVERROR_IO;

    if (startcode == PACK_START_CODE)

        goto redo;

    if (startcode == SYSTEM_HEADER_START_CODE)

        goto redo;

    if (startcode == PADDING_STREAM ||

        startcode == PRIVATE_STREAM_2) {

        /* skip them */

        len = get_be16(&s->pb);

        url_fskip(&s->pb, len);

        goto redo;

    }

    if (startcode == PROGRAM_STREAM_MAP) {

        mpegps_psm_parse(m, &s->pb);

        goto redo;

    }



    /* find matching stream */

    if (!((startcode >= 0x1c0 && startcode <= 0x1df) ||

          (startcode >= 0x1e0 && startcode <= 0x1ef) ||

          (startcode == 0x1bd)))

        goto redo;

    if (ppos) {

        *ppos = url_ftell(&s->pb) - 4;

    }

    len = get_be16(&s->pb);

    pts = AV_NOPTS_VALUE;

    dts = AV_NOPTS_VALUE;

    /* stuffing */

    for(;;) {

        if (len < 1)

            goto redo;

        c = get_byte(&s->pb);

        len--;

        /* XXX: for mpeg1, should test only bit 7 */

        if (c != 0xff)

            break;

    }

    if ((c & 0xc0) == 0x40) {

        /* buffer scale & size */

        if (len < 2)

            goto redo;

        get_byte(&s->pb);

        c = get_byte(&s->pb);

        len -= 2;

    }

    if ((c & 0xf0) == 0x20) {

        if (len < 4)

            goto redo;

        dts = pts = get_pts(&s->pb, c);

        len -= 4;

    } else if ((c & 0xf0) == 0x30) {

        if (len < 9)

            goto redo;

        pts = get_pts(&s->pb, c);

        dts = get_pts(&s->pb, -1);

        len -= 9;

    } else if ((c & 0xc0) == 0x80) {

        /* mpeg 2 PES */

#if 0 /* some streams have this field set for no apparent reason */

        if ((c & 0x30) != 0) {

            /* Encrypted multiplex not handled */

            goto redo;

        }

#endif

        flags = get_byte(&s->pb);

        header_len = get_byte(&s->pb);

        len -= 2;

        if (header_len > len)

            goto redo;

        if ((flags & 0xc0) == 0x80) {

            dts = pts = get_pts(&s->pb, -1);

            if (header_len < 5)

                goto redo;

            header_len -= 5;

            len -= 5;

        } if ((flags & 0xc0) == 0xc0) {

            pts = get_pts(&s->pb, -1);

            dts = get_pts(&s->pb, -1);

            if (header_len < 10)

                goto redo;

            header_len -= 10;

            len -= 10;

        }

        len -= header_len;

        while (header_len > 0) {

            get_byte(&s->pb);

            header_len--;

        }

    }

    else if( c!= 0xf )

        goto redo;



    if (startcode == PRIVATE_STREAM_1 && !m->psm_es_type[startcode & 0xff]) {

        if (len < 1)

            goto redo;

        startcode = get_byte(&s->pb);

        len--;

        if (startcode >= 0x80 && startcode <= 0xbf) {

            /* audio: skip header */

            if (len < 3)

                goto redo;

            get_byte(&s->pb);

            get_byte(&s->pb);

            get_byte(&s->pb);

            len -= 3;

        }

    }

    if(dts != AV_NOPTS_VALUE && ppos){

        int i;

        for(i=0; i<s->nb_streams; i++){

            if(startcode == s->streams[i]->id) {

                av_add_index_entry(s->streams[i], *ppos, dts, 0, 0, AVINDEX_KEYFRAME /* FIXME keyframe? */);

            }

        }

    }



    *pstart_code = startcode;

    *ppts = pts;

    *pdts = dts;

    return len;

}

static void decode_sigpass(Jpeg2000T1Context *t1, int width, int height,

                           int bpno, int bandno,

                           int vert_causal_ctx_csty_symbol)

{

    int mask = 3 << (bpno - 1), y0, x, y;



    for (y0 = 0; y0 < height; y0 += 4)

        for (x = 0; x < width; x++)

            for (y = y0; y < height && y < y0 + 4; y++) {

                int flags_mask = -1;

                if (vert_causal_ctx_csty_symbol && y == y0 + 3)

                    flags_mask &= ~(JPEG2000_T1_SIG_S | JPEG2000_T1_SIG_SW | JPEG2000_T1_SIG_SE | JPEG2000_T1_SGN_S);

                if ((t1->flags[y+1][x+1] & JPEG2000_T1_SIG_NB & flags_mask)

                && !(t1->flags[y+1][x+1] & (JPEG2000_T1_SIG | JPEG2000_T1_VIS))) {

                    if (ff_mqc_decode(&t1->mqc, t1->mqc.cx_states + ff_jpeg2000_getsigctxno(t1->flags[y+1][x+1] & flags_mask, bandno))) {

                        int xorbit, ctxno = ff_jpeg2000_getsgnctxno(t1->flags[y+1][x+1] & flags_mask, &xorbit);

                        if (t1->mqc.raw)

                             t1->data[y][x] = ff_mqc_decode(&t1->mqc, t1->mqc.cx_states + ctxno) ? -mask : mask;

                        else

                             t1->data[y][x] = (ff_mqc_decode(&t1->mqc, t1->mqc.cx_states + ctxno) ^ xorbit) ?

                                               -mask : mask;



                        ff_jpeg2000_set_significance(t1, x, y,

                                                     t1->data[y][x] < 0);

                    }

                    t1->flags[y + 1][x + 1] |= JPEG2000_T1_VIS;

                }

            }

}

static AVPacket *add_to_pktbuf(AVPacketList **packet_buffer, AVPacket *pkt,

                               AVPacketList **plast_pktl)

{

    AVPacketList *pktl = av_mallocz(sizeof(AVPacketList));

    if (!pktl)

        return NULL;



    if (*packet_buffer)

        (*plast_pktl)->next = pktl;

    else

        *packet_buffer = pktl;



    /* Add the packet in the buffered packet list. */

    *plast_pktl = pktl;

    pktl->pkt   = *pkt;

    return &pktl->pkt;

}

static av_always_inline void h264_filter_mb_fast_internal(const H264Context *h,

                                                          H264SliceContext *sl,

                                                          int mb_x, int mb_y,

                                                          uint8_t *img_y,

                                                          uint8_t *img_cb,

                                                          uint8_t *img_cr,

                                                          unsigned int linesize,

                                                          unsigned int uvlinesize,

                                                          int pixel_shift)

{

    int chroma = !(CONFIG_GRAY && (h->flags & AV_CODEC_FLAG_GRAY));

    int chroma444 = CHROMA444(h);

    int chroma422 = CHROMA422(h);



    int mb_xy = sl->mb_xy;

    int left_type = sl->left_type[LTOP];

    int top_type  = sl->top_type;



    int qp_bd_offset = 6 * (h->sps.bit_depth_luma - 8);

    int a = 52 + sl->slice_alpha_c0_offset - qp_bd_offset;

    int b = 52 + sl->slice_beta_offset - qp_bd_offset;



    int mb_type = h->cur_pic.mb_type[mb_xy];

    int qp      = h->cur_pic.qscale_table[mb_xy];

    int qp0     = h->cur_pic.qscale_table[mb_xy - 1];

    int qp1     = h->cur_pic.qscale_table[sl->top_mb_xy];

    int qpc = get_chroma_qp( h, 0, qp );

    int qpc0 = get_chroma_qp( h, 0, qp0 );

    int qpc1 = get_chroma_qp( h, 0, qp1 );

    qp0 = (qp + qp0 + 1) >> 1;

    qp1 = (qp + qp1 + 1) >> 1;

    qpc0 = (qpc + qpc0 + 1) >> 1;

    qpc1 = (qpc + qpc1 + 1) >> 1;



    if( IS_INTRA(mb_type) ) {

        static const int16_t bS4[4] = {4,4,4,4};

        static const int16_t bS3[4] = {3,3,3,3};

        const int16_t *bSH = FIELD_PICTURE(h) ? bS3 : bS4;

        if(left_type)

            filter_mb_edgev( &img_y[4*0<<pixel_shift], linesize, bS4, qp0, a, b, h, 1);

        if( IS_8x8DCT(mb_type) ) {

            filter_mb_edgev( &img_y[4*2<<pixel_shift], linesize, bS3, qp, a, b, h, 0);

            if(top_type){

                filter_mb_edgeh( &img_y[4*0*linesize], linesize, bSH, qp1, a, b, h, 1);

            }

            filter_mb_edgeh( &img_y[4*2*linesize], linesize, bS3, qp, a, b, h, 0);

        } else {

            filter_mb_edgev( &img_y[4*1<<pixel_shift], linesize, bS3, qp, a, b, h, 0);

            filter_mb_edgev( &img_y[4*2<<pixel_shift], linesize, bS3, qp, a, b, h, 0);

            filter_mb_edgev( &img_y[4*3<<pixel_shift], linesize, bS3, qp, a, b, h, 0);

            if(top_type){

                filter_mb_edgeh( &img_y[4*0*linesize], linesize, bSH, qp1, a, b, h, 1);

            }

            filter_mb_edgeh( &img_y[4*1*linesize], linesize, bS3, qp, a, b, h, 0);

            filter_mb_edgeh( &img_y[4*2*linesize], linesize, bS3, qp, a, b, h, 0);

            filter_mb_edgeh( &img_y[4*3*linesize], linesize, bS3, qp, a, b, h, 0);

        }

        if(chroma){

            if(chroma444){

                if(left_type){

                    filter_mb_edgev( &img_cb[4*0<<pixel_shift], linesize, bS4, qpc0, a, b, h, 1);

                    filter_mb_edgev( &img_cr[4*0<<pixel_shift], linesize, bS4, qpc0, a, b, h, 1);

                }

                if( IS_8x8DCT(mb_type) ) {

                    filter_mb_edgev( &img_cb[4*2<<pixel_shift], linesize, bS3, qpc, a, b, h, 0);

                    filter_mb_edgev( &img_cr[4*2<<pixel_shift], linesize, bS3, qpc, a, b, h, 0);

                    if(top_type){

                        filter_mb_edgeh( &img_cb[4*0*linesize], linesize, bSH, qpc1, a, b, h, 1 );

                        filter_mb_edgeh( &img_cr[4*0*linesize], linesize, bSH, qpc1, a, b, h, 1 );

                    }

                    filter_mb_edgeh( &img_cb[4*2*linesize], linesize, bS3, qpc, a, b, h, 0);

                    filter_mb_edgeh( &img_cr[4*2*linesize], linesize, bS3, qpc, a, b, h, 0);

                } else {

                    filter_mb_edgev( &img_cb[4*1<<pixel_shift], linesize, bS3, qpc, a, b, h, 0);

                    filter_mb_edgev( &img_cr[4*1<<pixel_shift], linesize, bS3, qpc, a, b, h, 0);

                    filter_mb_edgev( &img_cb[4*2<<pixel_shift], linesize, bS3, qpc, a, b, h, 0);

                    filter_mb_edgev( &img_cr[4*2<<pixel_shift], linesize, bS3, qpc, a, b, h, 0);

                    filter_mb_edgev( &img_cb[4*3<<pixel_shift], linesize, bS3, qpc, a, b, h, 0);

                    filter_mb_edgev( &img_cr[4*3<<pixel_shift], linesize, bS3, qpc, a, b, h, 0);

                    if(top_type){

                        filter_mb_edgeh( &img_cb[4*0*linesize], linesize, bSH, qpc1, a, b, h, 1);

                        filter_mb_edgeh( &img_cr[4*0*linesize], linesize, bSH, qpc1, a, b, h, 1);

                    }

                    filter_mb_edgeh( &img_cb[4*1*linesize], linesize, bS3, qpc, a, b, h, 0);

                    filter_mb_edgeh( &img_cr[4*1*linesize], linesize, bS3, qpc, a, b, h, 0);

                    filter_mb_edgeh( &img_cb[4*2*linesize], linesize, bS3, qpc, a, b, h, 0);

                    filter_mb_edgeh( &img_cr[4*2*linesize], linesize, bS3, qpc, a, b, h, 0);

                    filter_mb_edgeh( &img_cb[4*3*linesize], linesize, bS3, qpc, a, b, h, 0);

                    filter_mb_edgeh( &img_cr[4*3*linesize], linesize, bS3, qpc, a, b, h, 0);

                }

            }else if(chroma422){

                if(left_type){

                    filter_mb_edgecv(&img_cb[2*0<<pixel_shift], uvlinesize, bS4, qpc0, a, b, h, 1);

                    filter_mb_edgecv(&img_cr[2*0<<pixel_shift], uvlinesize, bS4, qpc0, a, b, h, 1);

                }

                filter_mb_edgecv(&img_cb[2*2<<pixel_shift], uvlinesize, bS3, qpc, a, b, h, 0);

                filter_mb_edgecv(&img_cr[2*2<<pixel_shift], uvlinesize, bS3, qpc, a, b, h, 0);

                if(top_type){

                    filter_mb_edgech(&img_cb[4*0*uvlinesize], uvlinesize, bSH, qpc1, a, b, h, 1);

                    filter_mb_edgech(&img_cr[4*0*uvlinesize], uvlinesize, bSH, qpc1, a, b, h, 1);

                }

                filter_mb_edgech(&img_cb[4*1*uvlinesize], uvlinesize, bS3, qpc, a, b, h, 0);

                filter_mb_edgech(&img_cr[4*1*uvlinesize], uvlinesize, bS3, qpc, a, b, h, 0);

                filter_mb_edgech(&img_cb[4*2*uvlinesize], uvlinesize, bS3, qpc, a, b, h, 0);

                filter_mb_edgech(&img_cr[4*2*uvlinesize], uvlinesize, bS3, qpc, a, b, h, 0);

                filter_mb_edgech(&img_cb[4*3*uvlinesize], uvlinesize, bS3, qpc, a, b, h, 0);

                filter_mb_edgech(&img_cr[4*3*uvlinesize], uvlinesize, bS3, qpc, a, b, h, 0);

            }else{

                if(left_type){

                    filter_mb_edgecv( &img_cb[2*0<<pixel_shift], uvlinesize, bS4, qpc0, a, b, h, 1);

                    filter_mb_edgecv( &img_cr[2*0<<pixel_shift], uvlinesize, bS4, qpc0, a, b, h, 1);

                }

                filter_mb_edgecv( &img_cb[2*2<<pixel_shift], uvlinesize, bS3, qpc, a, b, h, 0);

                filter_mb_edgecv( &img_cr[2*2<<pixel_shift], uvlinesize, bS3, qpc, a, b, h, 0);

                if(top_type){

                    filter_mb_edgech( &img_cb[2*0*uvlinesize], uvlinesize, bSH, qpc1, a, b, h, 1);

                    filter_mb_edgech( &img_cr[2*0*uvlinesize], uvlinesize, bSH, qpc1, a, b, h, 1);

                }

                filter_mb_edgech( &img_cb[2*2*uvlinesize], uvlinesize, bS3, qpc, a, b, h, 0);

                filter_mb_edgech( &img_cr[2*2*uvlinesize], uvlinesize, bS3, qpc, a, b, h, 0);

            }

        }

        return;

    } else {

        LOCAL_ALIGNED_8(int16_t, bS, [2], [4][4]);

        int edges;

        if( IS_8x8DCT(mb_type) && (sl->cbp&7) == 7 && !chroma444 ) {

            edges = 4;

            AV_WN64A(bS[0][0], 0x0002000200020002ULL);

            AV_WN64A(bS[0][2], 0x0002000200020002ULL);

            AV_WN64A(bS[1][0], 0x0002000200020002ULL);

            AV_WN64A(bS[1][2], 0x0002000200020002ULL);

        } else {

            int mask_edge1 = (3*(((5*mb_type)>>5)&1)) | (mb_type>>4); //(mb_type & (MB_TYPE_16x16 | MB_TYPE_8x16)) ? 3 : (mb_type & MB_TYPE_16x8) ? 1 : 0;

            int mask_edge0 = 3*((mask_edge1>>1) & ((5*left_type)>>5)&1); // (mb_type & (MB_TYPE_16x16 | MB_TYPE_8x16)) && (h->left_type[LTOP] & (MB_TYPE_16x16 | MB_TYPE_8x16)) ? 3 : 0;

            int step =  1+(mb_type>>24); //IS_8x8DCT(mb_type) ? 2 : 1;

            edges = 4 - 3*((mb_type>>3) & !(sl->cbp & 15)); //(mb_type & MB_TYPE_16x16) && !(h->cbp & 15) ? 1 : 4;

            h->h264dsp.h264_loop_filter_strength(bS, sl->non_zero_count_cache, sl->ref_cache, sl->mv_cache,

                                                 sl->list_count==2, edges, step, mask_edge0, mask_edge1, FIELD_PICTURE(h));

        }

        if( IS_INTRA(left_type) )

            AV_WN64A(bS[0][0], 0x0004000400040004ULL);

        if( IS_INTRA(top_type) )

            AV_WN64A(bS[1][0], FIELD_PICTURE(h) ? 0x0003000300030003ULL : 0x0004000400040004ULL);



#define FILTER(hv,dir,edge,intra)\

        if(AV_RN64A(bS[dir][edge])) {                                   \

            filter_mb_edge##hv( &img_y[4*edge*(dir?linesize:1<<pixel_shift)], linesize, bS[dir][edge], edge ? qp : qp##dir, a, b, h, intra );\

            if(chroma){\

                if(chroma444){\

                    filter_mb_edge##hv( &img_cb[4*edge*(dir?linesize:1<<pixel_shift)], linesize, bS[dir][edge], edge ? qpc : qpc##dir, a, b, h, intra );\

                    filter_mb_edge##hv( &img_cr[4*edge*(dir?linesize:1<<pixel_shift)], linesize, bS[dir][edge], edge ? qpc : qpc##dir, a, b, h, intra );\

                } else if(!(edge&1)) {\

                    filter_mb_edgec##hv( &img_cb[2*edge*(dir?uvlinesize:1<<pixel_shift)], uvlinesize, bS[dir][edge], edge ? qpc : qpc##dir, a, b, h, intra );\

                    filter_mb_edgec##hv( &img_cr[2*edge*(dir?uvlinesize:1<<pixel_shift)], uvlinesize, bS[dir][edge], edge ? qpc : qpc##dir, a, b, h, intra );\

                }\

            }\

        }

        if(left_type)

            FILTER(v,0,0,1);

        if( edges == 1 ) {

            if(top_type)

                FILTER(h,1,0,1);

        } else if( IS_8x8DCT(mb_type) ) {

            FILTER(v,0,2,0);

            if(top_type)

                FILTER(h,1,0,1);

            FILTER(h,1,2,0);

        } else {

            FILTER(v,0,1,0);

            FILTER(v,0,2,0);

            FILTER(v,0,3,0);

            if(top_type)

                FILTER(h,1,0,1);

            FILTER(h,1,1,0);

            FILTER(h,1,2,0);

            FILTER(h,1,3,0);

        }

#undef FILTER

    }

}

static int asf_read_frame_header(AVFormatContext *s, AVIOContext *pb){

    ASFContext *asf = s->priv_data;

    ASFStream *asfst;

    int rsize = 1;

    int num = avio_r8(pb);

    int i;

    int64_t ts0, ts1 av_unused;



    asf->packet_segments--;

    asf->packet_key_frame = num >> 7;

    asf->stream_index = asf->asfid2avid[num & 0x7f];

    asfst = &asf->streams[num & 0x7f];

    // sequence should be ignored!

    DO_2BITS(asf->packet_property >> 4, asf->packet_seq, 0);

    DO_2BITS(asf->packet_property >> 2, asf->packet_frag_offset, 0);

    DO_2BITS(asf->packet_property, asf->packet_replic_size, 0);

    av_dlog(asf, "key:%d stream:%d seq:%d offset:%d replic_size:%d\n",

            asf->packet_key_frame, asf->stream_index, asf->packet_seq,

            asf->packet_frag_offset, asf->packet_replic_size);

    if (rsize+asf->packet_replic_size > asf->packet_size_left) {

        av_log(s, AV_LOG_ERROR, "packet_replic_size %d is invalid\n", asf->packet_replic_size);

        return AVERROR_INVALIDDATA;

    }

    if (asf->packet_replic_size >= 8) {

        int64_t end = avio_tell(pb) + asf->packet_replic_size;

        AVRational aspect;

        asf->packet_obj_size = avio_rl32(pb);

        if(asf->packet_obj_size >= (1<<24) || asf->packet_obj_size <= 0){

            av_log(s, AV_LOG_ERROR, "packet_obj_size invalid\n");

            return AVERROR_INVALIDDATA;

        }

        asf->packet_frag_timestamp = avio_rl32(pb); // timestamp



        for (i=0; i<asfst->payload_ext_ct; i++) {

            ASFPayload *p = &asfst->payload[i];

            int size = p->size;

            int64_t payend;

            if(size == 0xFFFF)

                size = avio_rl16(pb);

            payend = avio_tell(pb) + size;

            if (payend > end) {

                av_log(s, AV_LOG_ERROR, "too long payload\n");

                break;

            }

            switch(p->type) {

            case 0x50:

//              duration = avio_rl16(pb);

                break;

            case 0x54:

                aspect.num = avio_r8(pb);

                aspect.den = avio_r8(pb);

                if (aspect.num > 0 && aspect.den > 0) {

                    s->streams[asf->stream_index]->sample_aspect_ratio = aspect;

                }

                break;

            case 0x2A:

                avio_skip(pb, 8);

                ts0= avio_rl64(pb);

                ts1= avio_rl64(pb);

                if(ts0!= -1) asf->packet_frag_timestamp= ts0/10000;

                else         asf->packet_frag_timestamp= AV_NOPTS_VALUE;

                break;

            case 0x5B:

            case 0xB7:

            case 0xCC:

            case 0xC0:

            case 0xA0:

                //unknown

                break;

            }

            avio_seek(pb, payend, SEEK_SET);

        }



        avio_seek(pb, end, SEEK_SET);

        rsize += asf->packet_replic_size; // FIXME - check validity

    } else if (asf->packet_replic_size==1){

        // multipacket - frag_offset is beginning timestamp

        asf->packet_time_start = asf->packet_frag_offset;

        asf->packet_frag_offset = 0;

        asf->packet_frag_timestamp = asf->packet_timestamp;



        asf->packet_time_delta = avio_r8(pb);

        rsize++;

    }else if(asf->packet_replic_size!=0){

        av_log(s, AV_LOG_ERROR, "unexpected packet_replic_size of %d\n", asf->packet_replic_size);

        return AVERROR_INVALIDDATA;

    }

    if (asf->packet_flags & 0x01) {

        DO_2BITS(asf->packet_segsizetype >> 6, asf->packet_frag_size, 0); // 0 is illegal

        if (rsize > asf->packet_size_left) {

            av_log(s, AV_LOG_ERROR, "packet_replic_size is invalid\n");

            return AVERROR_INVALIDDATA;

        } else if(asf->packet_frag_size > asf->packet_size_left - rsize){

            if (asf->packet_frag_size > asf->packet_size_left - rsize + asf->packet_padsize) {

                av_log(s, AV_LOG_ERROR, "packet_frag_size is invalid (%d-%d)\n", asf->packet_size_left, rsize);

                return AVERROR_INVALIDDATA;

            } else {

                int diff = asf->packet_frag_size - (asf->packet_size_left - rsize);

                asf->packet_size_left += diff;

                asf->packet_padsize   -= diff;

            }

        }

    } else {

        asf->packet_frag_size = asf->packet_size_left - rsize;

    }

    if (asf->packet_replic_size == 1) {

        asf->packet_multi_size = asf->packet_frag_size;

        if (asf->packet_multi_size > asf->packet_size_left)

            return AVERROR_INVALIDDATA;

    }

    asf->packet_size_left -= rsize;



    return 0;

}

