static int ff_asf_parse_packet(AVFormatContext *s, AVIOContext *pb, AVPacket *pkt)

{

    ASFContext *asf = s->priv_data;

    ASFStream *asf_st = 0;

    for (;;) {

        int ret;

        if(pb->eof_reached)

            return AVERROR_EOF;

        if (asf->packet_size_left < FRAME_HEADER_SIZE

            || asf->packet_segments < 1) {

            //asf->packet_size_left <= asf->packet_padsize) {

            int ret = asf->packet_size_left + asf->packet_padsize;

            //printf("PacketLeftSize:%d  Pad:%d Pos:%"PRId64"\n", asf->packet_size_left, asf->packet_padsize, avio_tell(pb));

            assert(ret>=0);

            /* fail safe */

            avio_skip(pb, ret);



            asf->packet_pos= avio_tell(pb);

            if (asf->data_object_size != (uint64_t)-1 &&

                (asf->packet_pos - asf->data_object_offset >= asf->data_object_size))

                return AVERROR_EOF; /* Do not exceed the size of the data object */

            return 1;

        }

        if (asf->packet_time_start == 0) {

            if(asf_read_frame_header(s, pb) < 0){

                asf->packet_segments= 0;

                continue;

            }

            if (asf->stream_index < 0

                || s->streams[asf->stream_index]->discard >= AVDISCARD_ALL

                || (!asf->packet_key_frame && s->streams[asf->stream_index]->discard >= AVDISCARD_NONKEY)

                ) {

                asf->packet_time_start = 0;

                /* unhandled packet (should not happen) */

                avio_skip(pb, asf->packet_frag_size);

                asf->packet_size_left -= asf->packet_frag_size;

                if(asf->stream_index < 0)

                    av_log(s, AV_LOG_ERROR, "ff asf skip %d (unknown stream)\n", asf->packet_frag_size);

                continue;

            }

            asf->asf_st = s->streams[asf->stream_index]->priv_data;

        }

        asf_st = asf->asf_st;



        if (asf->packet_replic_size == 1) {

            // frag_offset is here used as the beginning timestamp

            asf->packet_frag_timestamp = asf->packet_time_start;

            asf->packet_time_start += asf->packet_time_delta;

            asf->packet_obj_size = asf->packet_frag_size = avio_r8(pb);

            asf->packet_size_left--;

            asf->packet_multi_size--;

            if (asf->packet_multi_size < asf->packet_obj_size)

            {

                asf->packet_time_start = 0;

                avio_skip(pb, asf->packet_multi_size);

                asf->packet_size_left -= asf->packet_multi_size;

                continue;

            }

            asf->packet_multi_size -= asf->packet_obj_size;

            //printf("COMPRESS size  %d  %d  %d   ms:%d\n", asf->packet_obj_size, asf->packet_frag_timestamp, asf->packet_size_left, asf->packet_multi_size);

        }

        if(   /*asf->packet_frag_size == asf->packet_obj_size*/

              asf_st->frag_offset + asf->packet_frag_size <= asf_st->pkt.size

           && asf_st->frag_offset + asf->packet_frag_size > asf->packet_obj_size){

            av_log(s, AV_LOG_INFO, "ignoring invalid packet_obj_size (%d %d %d %d)\n",

                asf_st->frag_offset, asf->packet_frag_size,

                asf->packet_obj_size, asf_st->pkt.size);

            asf->packet_obj_size= asf_st->pkt.size;

        }



        if (   asf_st->pkt.size != asf->packet_obj_size

            || asf_st->frag_offset + asf->packet_frag_size > asf_st->pkt.size) { //FIXME is this condition sufficient?

            if(asf_st->pkt.data){

                av_log(s, AV_LOG_INFO, "freeing incomplete packet size %d, new %d\n", asf_st->pkt.size, asf->packet_obj_size);

                asf_st->frag_offset = 0;

                av_free_packet(&asf_st->pkt);

            }

            /* new packet */

            av_new_packet(&asf_st->pkt, asf->packet_obj_size);

            asf_st->seq = asf->packet_seq;

            asf_st->pkt.dts = asf->packet_frag_timestamp - asf->hdr.preroll;

            asf_st->pkt.stream_index = asf->stream_index;

            asf_st->pkt.pos =

            asf_st->packet_pos= asf->packet_pos;

            if (asf_st->pkt.data && asf_st->palette_changed) {

                uint8_t *pal;

                pal = av_packet_new_side_data(&asf_st->pkt, AV_PKT_DATA_PALETTE,

                                              AVPALETTE_SIZE);

                if (!pal) {

                    av_log(s, AV_LOG_ERROR, "Cannot append palette to packet\n");

                } else {

                    memcpy(pal, asf_st->palette, AVPALETTE_SIZE);

                    asf_st->palette_changed = 0;

                }

            }

//printf("new packet: stream:%d key:%d packet_key:%d audio:%d size:%d\n",

//asf->stream_index, asf->packet_key_frame, asf_st->pkt.flags & AV_PKT_FLAG_KEY,

//s->streams[asf->stream_index]->codec->codec_type == AVMEDIA_TYPE_AUDIO, asf->packet_obj_size);

            if (s->streams[asf->stream_index]->codec->codec_type == AVMEDIA_TYPE_AUDIO)

                asf->packet_key_frame = 1;

            if (asf->packet_key_frame)

                asf_st->pkt.flags |= AV_PKT_FLAG_KEY;

        }



        /* read data */

        //printf("READ PACKET s:%d  os:%d  o:%d,%d  l:%d   DATA:%p\n",

        //       s->packet_size, asf_st->pkt.size, asf->packet_frag_offset,

        //       asf_st->frag_offset, asf->packet_frag_size, asf_st->pkt.data);

        asf->packet_size_left -= asf->packet_frag_size;

        if (asf->packet_size_left < 0)

            continue;



        if(   asf->packet_frag_offset >= asf_st->pkt.size

           || asf->packet_frag_size > asf_st->pkt.size - asf->packet_frag_offset){

            av_log(s, AV_LOG_ERROR, "packet fragment position invalid %u,%u not in %u\n",

                asf->packet_frag_offset, asf->packet_frag_size, asf_st->pkt.size);

            continue;

        }



        ret = avio_read(pb, asf_st->pkt.data + asf->packet_frag_offset,

                         asf->packet_frag_size);

        if (ret != asf->packet_frag_size) {

            if (ret < 0 || asf->packet_frag_offset + ret == 0)

                return ret < 0 ? ret : AVERROR_EOF;

            if (asf_st->ds_span > 1) {

                // scrambling, we can either drop it completely or fill the remainder

                // TODO: should we fill the whole packet instead of just the current

                // fragment?

                memset(asf_st->pkt.data + asf->packet_frag_offset + ret, 0,

                       asf->packet_frag_size - ret);

                ret = asf->packet_frag_size;

            } else

                // no scrambling, so we can return partial packets

                av_shrink_packet(&asf_st->pkt, asf->packet_frag_offset + ret);

        }

        if (s->key && s->keylen == 20)

            ff_asfcrypt_dec(s->key, asf_st->pkt.data + asf->packet_frag_offset,

                            ret);

        asf_st->frag_offset += ret;

        /* test if whole packet is read */

        if (asf_st->frag_offset == asf_st->pkt.size) {

            //workaround for macroshit radio DVR-MS files

            if(   s->streams[asf->stream_index]->codec->codec_id == CODEC_ID_MPEG2VIDEO

               && asf_st->pkt.size > 100){

                int i;

                for(i=0; i<asf_st->pkt.size && !asf_st->pkt.data[i]; i++);

                if(i == asf_st->pkt.size){

                    av_log(s, AV_LOG_DEBUG, "discarding ms fart\n");

                    asf_st->frag_offset = 0;

                    av_free_packet(&asf_st->pkt);

                    continue;

                }

            }



            /* return packet */

            if (asf_st->ds_span > 1) {

              if(asf_st->pkt.size != asf_st->ds_packet_size * asf_st->ds_span){

                    av_log(s, AV_LOG_ERROR, "pkt.size != ds_packet_size * ds_span (%d %d %d)\n", asf_st->pkt.size, asf_st->ds_packet_size, asf_st->ds_span);

              }else{

                /* packet descrambling */

                uint8_t *newdata = av_malloc(asf_st->pkt.size + FF_INPUT_BUFFER_PADDING_SIZE);

                if (newdata) {

                    int offset = 0;

                    memset(newdata + asf_st->pkt.size, 0, FF_INPUT_BUFFER_PADDING_SIZE);

                    while (offset < asf_st->pkt.size) {

                        int off = offset / asf_st->ds_chunk_size;

                        int row = off / asf_st->ds_span;

                        int col = off % asf_st->ds_span;

                        int idx = row + col * asf_st->ds_packet_size / asf_st->ds_chunk_size;

                        //printf("off:%d  row:%d  col:%d  idx:%d\n", off, row, col, idx);



                        assert(offset + asf_st->ds_chunk_size <= asf_st->pkt.size);

                        assert(idx+1 <= asf_st->pkt.size / asf_st->ds_chunk_size);

                        memcpy(newdata + offset,

                               asf_st->pkt.data + idx * asf_st->ds_chunk_size,

                               asf_st->ds_chunk_size);

                        offset += asf_st->ds_chunk_size;

                    }

                    av_free(asf_st->pkt.data);

                    asf_st->pkt.data = newdata;

                }

              }

            }

            asf_st->frag_offset = 0;

            *pkt= asf_st->pkt;

            //printf("packet %d %d\n", asf_st->pkt.size, asf->packet_frag_size);

            asf_st->pkt.size = 0;

            asf_st->pkt.data = 0;



            break; // packet completed

        }

    }

    return 0;

}

static int h264_slice_header_init(H264Context *h, int reinit)

{

    MpegEncContext *const s  = &h->s;

    int i, ret;



    if(   FFALIGN(s->avctx->width , 16                                 ) == s->width

        && FFALIGN(s->avctx->height, 16*(2 - h->sps.frame_mbs_only_flag)) == s->height

        && !h->sps.crop_right && !h->sps.crop_bottom

        && (s->avctx->width != s->width || s->avctx->height && s->height)

    ) {

        av_log(h->s.avctx, AV_LOG_DEBUG, "Using externally provided dimensions\n");

        s->avctx->coded_width  = s->width;

        s->avctx->coded_height = s->height;

    } else{

        avcodec_set_dimensions(s->avctx, s->width, s->height);

        s->avctx->width  -= (2>>CHROMA444)*FFMIN(h->sps.crop_right, (8<<CHROMA444)-1);

        s->avctx->height -= (1<<s->chroma_y_shift)*FFMIN(h->sps.crop_bottom, (16>>s->chroma_y_shift)-1) * (2 - h->sps.frame_mbs_only_flag);

    }



    s->avctx->sample_aspect_ratio = h->sps.sar;

    av_assert0(s->avctx->sample_aspect_ratio.den);



    if (h->sps.timing_info_present_flag) {

        int64_t den = h->sps.time_scale;

        if (h->x264_build < 44U)

            den *= 2;

        av_reduce(&s->avctx->time_base.num, &s->avctx->time_base.den,

                  h->sps.num_units_in_tick, den, 1 << 30);

    }



    s->avctx->hwaccel = ff_find_hwaccel(s->avctx->codec->id, s->avctx->pix_fmt);



    if (reinit) {

        free_tables(h, 0);

        if ((ret = ff_MPV_common_frame_size_change(s)) < 0) {

            av_log(h->s.avctx, AV_LOG_ERROR, "ff_MPV_common_frame_size_change() failed.\n");

            return ret;

        }

    } else {

        if ((ret = ff_MPV_common_init(s) < 0)) {

            av_log(h->s.avctx, AV_LOG_ERROR, "ff_MPV_common_init() failed.\n");

            return ret;

        }

    }

    s->first_field = 0;

    h->prev_interlaced_frame = 1;



    init_scan_tables(h);

    if (ff_h264_alloc_tables(h) < 0) {

        av_log(h->s.avctx, AV_LOG_ERROR,

               "Could not allocate memory for h264\n");

        return AVERROR(ENOMEM);

    }



    if (!HAVE_THREADS || !(s->avctx->active_thread_type & FF_THREAD_SLICE)) {

        if (context_init(h) < 0) {

            av_log(h->s.avctx, AV_LOG_ERROR, "context_init() failed.\n");

            return -1;

        }

    } else {

        for (i = 1; i < s->slice_context_count; i++) {

            H264Context *c;

            c = h->thread_context[i] = av_malloc(sizeof(H264Context));

            memcpy(c, h->s.thread_context[i], sizeof(MpegEncContext));

            memset(&c->s + 1, 0, sizeof(H264Context) - sizeof(MpegEncContext));

            c->h264dsp     = h->h264dsp;

            c->sps         = h->sps;

            c->pps         = h->pps;

            c->pixel_shift = h->pixel_shift;

            c->cur_chroma_format_idc = h->cur_chroma_format_idc;

            init_scan_tables(c);

            clone_tables(c, h, i);

        }



        for (i = 0; i < s->slice_context_count; i++)

            if (context_init(h->thread_context[i]) < 0) {

                av_log(h->s.avctx, AV_LOG_ERROR, "context_init() failed.\n");

                return -1;

            }

    }



    return 0;

}

static inline void RENAME(hyscale)(uint16_t *dst, long dstWidth, uint8_t *src, int srcW, int xInc,

				   int flags, int canMMX2BeUsed, int16_t *hLumFilter,

				   int16_t *hLumFilterPos, int hLumFilterSize, void *funnyYCode,

				   int srcFormat, uint8_t *formatConvBuffer, int16_t *mmx2Filter,

				   int32_t *mmx2FilterPos, uint8_t *pal)

{

    if(srcFormat==PIX_FMT_YUYV422 || srcFormat==PIX_FMT_GRAY16BE)

    {

	RENAME(yuy2ToY)(formatConvBuffer, src, srcW);

	src= formatConvBuffer;

    }

    else if(srcFormat==PIX_FMT_UYVY422 || srcFormat==PIX_FMT_GRAY16LE)

    {

	RENAME(uyvyToY)(formatConvBuffer, src, srcW);

	src= formatConvBuffer;

    }

    else if(srcFormat==PIX_FMT_RGB32)

    {

	RENAME(bgr32ToY)(formatConvBuffer, src, srcW);

	src= formatConvBuffer;

    }

    else if(srcFormat==PIX_FMT_BGR24)

    {

	RENAME(bgr24ToY)(formatConvBuffer, src, srcW);

	src= formatConvBuffer;

    }

    else if(srcFormat==PIX_FMT_BGR565)

    {

	RENAME(bgr16ToY)(formatConvBuffer, src, srcW);

	src= formatConvBuffer;

    }

    else if(srcFormat==PIX_FMT_BGR555)

    {

	RENAME(bgr15ToY)(formatConvBuffer, src, srcW);

	src= formatConvBuffer;

    }

    else if(srcFormat==PIX_FMT_BGR32)

    {

	RENAME(rgb32ToY)(formatConvBuffer, src, srcW);

	src= formatConvBuffer;

    }

    else if(srcFormat==PIX_FMT_RGB24)

    {

	RENAME(rgb24ToY)(formatConvBuffer, src, srcW);

	src= formatConvBuffer;

    }

    else if(srcFormat==PIX_FMT_RGB565)

    {

	RENAME(rgb16ToY)(formatConvBuffer, src, srcW);

	src= formatConvBuffer;

    }

    else if(srcFormat==PIX_FMT_RGB555)

    {

	RENAME(rgb15ToY)(formatConvBuffer, src, srcW);

	src= formatConvBuffer;

    }

    else if(srcFormat==PIX_FMT_RGB8 || srcFormat==PIX_FMT_BGR8 || srcFormat==PIX_FMT_PAL8 || srcFormat==PIX_FMT_BGR4_BYTE  || srcFormat==PIX_FMT_RGB4_BYTE)

    {

	RENAME(palToY)(formatConvBuffer, src, srcW, pal);

	src= formatConvBuffer;

    }



#ifdef HAVE_MMX

	// use the new MMX scaler if the mmx2 can't be used (its faster than the x86asm one)

    if(!(flags&SWS_FAST_BILINEAR) || (!canMMX2BeUsed))

#else

    if(!(flags&SWS_FAST_BILINEAR))

#endif

    {

    	RENAME(hScale)(dst, dstWidth, src, srcW, xInc, hLumFilter, hLumFilterPos, hLumFilterSize);

    }

    else // Fast Bilinear upscale / crap downscale

    {

#if defined(ARCH_X86)

#ifdef HAVE_MMX2

	int i;

#if defined(PIC)

	uint64_t ebxsave __attribute__((aligned(8)));

#endif

	if(canMMX2BeUsed)

	{

		asm volatile(

#if defined(PIC)

			"mov %%"REG_b", %5    \n\t"

#endif

			"pxor %%mm7, %%mm7		\n\t"

			"mov %0, %%"REG_c"		\n\t"

			"mov %1, %%"REG_D"		\n\t"

			"mov %2, %%"REG_d"		\n\t"

			"mov %3, %%"REG_b"		\n\t"

			"xor %%"REG_a", %%"REG_a"	\n\t" // i

			PREFETCH" (%%"REG_c")		\n\t"

			PREFETCH" 32(%%"REG_c")		\n\t"

			PREFETCH" 64(%%"REG_c")		\n\t"



#ifdef ARCH_X86_64



#define FUNNY_Y_CODE \

			"movl (%%"REG_b"), %%esi	\n\t"\

			"call *%4			\n\t"\

			"movl (%%"REG_b", %%"REG_a"), %%esi\n\t"\

			"add %%"REG_S", %%"REG_c"	\n\t"\

			"add %%"REG_a", %%"REG_D"	\n\t"\

			"xor %%"REG_a", %%"REG_a"	\n\t"\



#else



#define FUNNY_Y_CODE \

			"movl (%%"REG_b"), %%esi	\n\t"\

			"call *%4			\n\t"\

			"addl (%%"REG_b", %%"REG_a"), %%"REG_c"\n\t"\

			"add %%"REG_a", %%"REG_D"	\n\t"\

			"xor %%"REG_a", %%"REG_a"	\n\t"\



#endif



FUNNY_Y_CODE

FUNNY_Y_CODE

FUNNY_Y_CODE

FUNNY_Y_CODE

FUNNY_Y_CODE

FUNNY_Y_CODE

FUNNY_Y_CODE

FUNNY_Y_CODE



#if defined(PIC)

			"mov %5, %%"REG_b"    \n\t"

#endif

			:: "m" (src), "m" (dst), "m" (mmx2Filter), "m" (mmx2FilterPos),

			"m" (funnyYCode)

#if defined(PIC)

			,"m" (ebxsave)

#endif

			: "%"REG_a, "%"REG_c, "%"REG_d, "%"REG_S, "%"REG_D

#if !defined(PIC)

			,"%"REG_b

#endif

		);

		for(i=dstWidth-1; (i*xInc)>>16 >=srcW-1; i--) dst[i] = src[srcW-1]*128;

	}

	else

	{

#endif

	long xInc_shr16 = xInc >> 16;

	uint16_t xInc_mask = xInc & 0xffff;

	//NO MMX just normal asm ...

	asm volatile(

		"xor %%"REG_a", %%"REG_a"	\n\t" // i

		"xor %%"REG_d", %%"REG_d"	\n\t" // xx

		"xorl %%ecx, %%ecx		\n\t" // 2*xalpha

		ASMALIGN(4)

		"1:				\n\t"

		"movzbl  (%0, %%"REG_d"), %%edi	\n\t" //src[xx]

		"movzbl 1(%0, %%"REG_d"), %%esi	\n\t" //src[xx+1]

		"subl %%edi, %%esi		\n\t" //src[xx+1] - src[xx]

		"imull %%ecx, %%esi		\n\t" //(src[xx+1] - src[xx])*2*xalpha

		"shll $16, %%edi		\n\t"

		"addl %%edi, %%esi		\n\t" //src[xx+1]*2*xalpha + src[xx]*(1-2*xalpha)

		"mov %1, %%"REG_D"		\n\t"

		"shrl $9, %%esi			\n\t"

		"movw %%si, (%%"REG_D", %%"REG_a", 2)\n\t"

		"addw %4, %%cx			\n\t" //2*xalpha += xInc&0xFF

		"adc %3, %%"REG_d"		\n\t" //xx+= xInc>>8 + carry



		"movzbl (%0, %%"REG_d"), %%edi	\n\t" //src[xx]

		"movzbl 1(%0, %%"REG_d"), %%esi	\n\t" //src[xx+1]

		"subl %%edi, %%esi		\n\t" //src[xx+1] - src[xx]

		"imull %%ecx, %%esi		\n\t" //(src[xx+1] - src[xx])*2*xalpha

		"shll $16, %%edi		\n\t"

		"addl %%edi, %%esi		\n\t" //src[xx+1]*2*xalpha + src[xx]*(1-2*xalpha)

		"mov %1, %%"REG_D"		\n\t"

		"shrl $9, %%esi			\n\t"

		"movw %%si, 2(%%"REG_D", %%"REG_a", 2)\n\t"

		"addw %4, %%cx			\n\t" //2*xalpha += xInc&0xFF

		"adc %3, %%"REG_d"		\n\t" //xx+= xInc>>8 + carry





		"add $2, %%"REG_a"		\n\t"

		"cmp %2, %%"REG_a"		\n\t"

		" jb 1b				\n\t"





		:: "r" (src), "m" (dst), "m" (dstWidth), "m" (xInc_shr16), "m" (xInc_mask)

		: "%"REG_a, "%"REG_d, "%ecx", "%"REG_D, "%esi"

		);

#ifdef HAVE_MMX2

	} //if MMX2 can't be used

#endif

#else

	int i;

	unsigned int xpos=0;

	for(i=0;i<dstWidth;i++)

	{

		register unsigned int xx=xpos>>16;

		register unsigned int xalpha=(xpos&0xFFFF)>>9;

		dst[i]= (src[xx]<<7) + (src[xx+1] - src[xx])*xalpha;

		xpos+=xInc;

	}

#endif

    }

}

static int rtmp_write(URLContext *s, const uint8_t *buf, int size)
{
    RTMPContext *rt = s->priv_data;
    int size_temp = size;
    int pktsize, pkttype;
    uint32_t ts;
    const uint8_t *buf_temp = buf;
    uint8_t c;
    int ret;
    do {
        if (rt->skip_bytes) {
            int skip = FFMIN(rt->skip_bytes, size_temp);
            buf_temp       += skip;
            size_temp      -= skip;
            rt->skip_bytes -= skip;
            continue;
        if (rt->flv_header_bytes < 11) {
            const uint8_t *header = rt->flv_header;
            int copy = FFMIN(11 - rt->flv_header_bytes, size_temp);
            bytestream_get_buffer(&buf_temp, rt->flv_header + rt->flv_header_bytes, copy);
            rt->flv_header_bytes += copy;
            size_temp            -= copy;
            if (rt->flv_header_bytes < 11)
                break;
            pkttype = bytestream_get_byte(&header);
            pktsize = bytestream_get_be24(&header);
            ts = bytestream_get_be24(&header);
            ts |= bytestream_get_byte(&header) << 24;
            bytestream_get_be24(&header);
            rt->flv_size = pktsize;
            //force 12bytes header
            if (((pkttype == RTMP_PT_VIDEO || pkttype == RTMP_PT_AUDIO) && ts == 0) ||
                pkttype == RTMP_PT_NOTIFY) {
                if (pkttype == RTMP_PT_NOTIFY)
                    pktsize += 16;
                rt->prev_pkt[1][RTMP_SOURCE_CHANNEL].channel_id = 0;
            //this can be a big packet, it's better to send it right here
            if ((ret = ff_rtmp_packet_create(&rt->out_pkt, RTMP_SOURCE_CHANNEL,
                                             pkttype, ts, pktsize)) < 0)
            rt->out_pkt.extra = rt->main_channel_id;
            rt->flv_data = rt->out_pkt.data;
            if (pkttype == RTMP_PT_NOTIFY)
                ff_amf_write_string(&rt->flv_data, "@setDataFrame");
        if (rt->flv_size - rt->flv_off > size_temp) {
            bytestream_get_buffer(&buf_temp, rt->flv_data + rt->flv_off, size_temp);
            rt->flv_off += size_temp;
            size_temp = 0;
        } else {
            bytestream_get_buffer(&buf_temp, rt->flv_data + rt->flv_off, rt->flv_size - rt->flv_off);
            size_temp   -= rt->flv_size - rt->flv_off;
            rt->flv_off += rt->flv_size - rt->flv_off;
        if (rt->flv_off == rt->flv_size) {
            rt->skip_bytes = 4;
            if ((ret = ff_rtmp_packet_write(rt->stream, &rt->out_pkt,
                                            rt->chunk_size, rt->prev_pkt[1])) < 0)
            ff_rtmp_packet_destroy(&rt->out_pkt);
            rt->flv_size = 0;
            rt->flv_off = 0;
            rt->flv_header_bytes = 0;
    } while (buf_temp - buf < size);

void ff_thread_flush(AVCodecContext *avctx)

{

    FrameThreadContext *fctx = avctx->thread_opaque;



    if (!avctx->thread_opaque) return;



    park_frame_worker_threads(fctx, avctx->thread_count);



    if (fctx->prev_thread)

        update_context_from_thread(fctx->threads->avctx, fctx->prev_thread->avctx, 0);



    fctx->next_decoding = fctx->next_finished = 0;

    fctx->delaying = 1;

    fctx->prev_thread = NULL;

}

void ff_j2k_cleanup(Jpeg2000Component *comp, Jpeg2000CodingStyle *codsty)

{

    int reslevelno, bandno, precno;

    for (reslevelno = 0; reslevelno < codsty->nreslevels; reslevelno++) {

        Jpeg2000ResLevel *reslevel = comp->reslevel + reslevelno;



        for (bandno = 0; bandno < reslevel->nbands; bandno++) {

            Jpeg2000Band *band = reslevel->band + bandno;

            for (precno = 0; precno < reslevel->num_precincts_x * reslevel->num_precincts_y; precno++) {

                Jpeg2000Prec *prec = band->prec + precno;

                av_freep(&prec->zerobits);

                av_freep(&prec->cblkincl);

                av_freep(&prec->cblk);

            }



            av_freep(&band->prec);

        }

        av_freep(&reslevel->band);

    }



    ff_dwt_destroy(&comp->dwt);

    av_freep(&comp->reslevel);

    av_freep(&comp->data);

}

static int decode_picture_header(AVCodecContext *avctx, const uint8_t *buf, const int buf_size)

{

    ProresContext *ctx = avctx->priv_data;

    int i, hdr_size, slice_count;

    unsigned pic_data_size;

    int log2_slice_mb_width, log2_slice_mb_height;

    int slice_mb_count, mb_x, mb_y;

    const uint8_t *data_ptr, *index_ptr;



    hdr_size = buf[0] >> 3;

    if (hdr_size < 8 || hdr_size > buf_size) {

        av_log(avctx, AV_LOG_ERROR, "error, wrong picture header size\n");

        return -1;

    }



    pic_data_size = AV_RB32(buf + 1);

    if (pic_data_size > buf_size) {

        av_log(avctx, AV_LOG_ERROR, "error, wrong picture data size\n");

        return -1;

    }



    log2_slice_mb_width  = buf[7] >> 4;

    log2_slice_mb_height = buf[7] & 0xF;

    if (log2_slice_mb_width > 3 || log2_slice_mb_height) {

        av_log(avctx, AV_LOG_ERROR, "unsupported slice resolution: %dx%d\n",

               1 << log2_slice_mb_width, 1 << log2_slice_mb_height);

        return -1;

    }



    ctx->mb_width  = (avctx->width  + 15) >> 4;

    ctx->mb_height = (avctx->height + 15) >> 4;



    slice_count = AV_RB16(buf + 5);



    if (ctx->slice_count != slice_count || !ctx->slices) {

        av_freep(&ctx->slices);

        ctx->slices = av_mallocz(slice_count * sizeof(*ctx->slices));

        if (!ctx->slices)

            return AVERROR(ENOMEM);

        ctx->slice_count = slice_count;

    }



    if (!slice_count)

        return AVERROR(EINVAL);



    if (hdr_size + slice_count*2 > buf_size) {

        av_log(avctx, AV_LOG_ERROR, "error, wrong slice count\n");

        return -1;

    }



    // parse slice information

    index_ptr = buf + hdr_size;

    data_ptr  = index_ptr + slice_count*2;



    slice_mb_count = 1 << log2_slice_mb_width;

    mb_x = 0;

    mb_y = 0;



    for (i = 0; i < slice_count; i++) {

        SliceContext *slice = &ctx->slices[i];



        slice->data = data_ptr;

        data_ptr += AV_RB16(index_ptr + i*2);



        while (ctx->mb_width - mb_x < slice_mb_count)

            slice_mb_count >>= 1;



        slice->mb_x = mb_x;

        slice->mb_y = mb_y;

        slice->mb_count = slice_mb_count;

        slice->data_size = data_ptr - slice->data;



        if (slice->data_size < 6) {

            av_log(avctx, AV_LOG_ERROR, "error, wrong slice data size\n");

            return -1;

        }



        mb_x += slice_mb_count;

        if (mb_x == ctx->mb_width) {

            slice_mb_count = 1 << log2_slice_mb_width;

            mb_x = 0;

            mb_y++;

        }

        if (data_ptr > buf + buf_size) {

            av_log(avctx, AV_LOG_ERROR, "error, slice out of bounds\n");

            return -1;

        }

    }



    return pic_data_size;

}

int avpriv_dca_parse_core_frame_header(GetBitContext *gb, DCACoreFrameHeader *h)

{

    if (get_bits_long(gb, 32) != DCA_SYNCWORD_CORE_BE)

        return DCA_PARSE_ERROR_SYNC_WORD;



    h->normal_frame = get_bits1(gb);

    h->deficit_samples = get_bits(gb, 5) + 1;

    if (h->deficit_samples != DCA_PCMBLOCK_SAMPLES)

        return DCA_PARSE_ERROR_DEFICIT_SAMPLES;



    h->crc_present = get_bits1(gb);

    h->npcmblocks = get_bits(gb, 7) + 1;

    if (h->npcmblocks & (DCA_SUBBAND_SAMPLES - 1))

        return DCA_PARSE_ERROR_PCM_BLOCKS;



    h->frame_size = get_bits(gb, 14) + 1;

    if (h->frame_size < 96)

        return DCA_PARSE_ERROR_FRAME_SIZE;



    h->audio_mode = get_bits(gb, 6);

    if (h->audio_mode >= DCA_AMODE_COUNT)

        return DCA_PARSE_ERROR_AMODE;



    h->sr_code = get_bits(gb, 4);

    if (!avpriv_dca_sample_rates[h->sr_code])

        return DCA_PARSE_ERROR_SAMPLE_RATE;



    h->br_code = get_bits(gb, 5);

    if (get_bits1(gb))

        return DCA_PARSE_ERROR_RESERVED_BIT;



    h->drc_present = get_bits1(gb);

    h->ts_present = get_bits1(gb);

    h->aux_present = get_bits1(gb);

    h->hdcd_master = get_bits1(gb);

    h->ext_audio_type = get_bits(gb, 3);

    h->ext_audio_present = get_bits1(gb);

    h->sync_ssf = get_bits1(gb);

    h->lfe_present = get_bits(gb, 2);

    if (h->lfe_present == DCA_LFE_FLAG_INVALID)

        return DCA_PARSE_ERROR_LFE_FLAG;



    h->predictor_history = get_bits1(gb);

    if (h->crc_present)

        skip_bits(gb, 16);

    h->filter_perfect = get_bits1(gb);

    h->encoder_rev = get_bits(gb, 4);

    h->copy_hist = get_bits(gb, 2);

    h->pcmr_code = get_bits(gb, 3);

    if (!ff_dca_bits_per_sample[h->pcmr_code])

        return DCA_PARSE_ERROR_PCM_RES;



    h->sumdiff_front = get_bits1(gb);

    h->sumdiff_surround = get_bits1(gb);

    h->dn_code = get_bits(gb, 4);

    return 0;

}

static void FUNCC(pred8x8l_horizontal_add)(uint8_t *_pix, const int16_t *_block,

                                           ptrdiff_t stride)

{

    int i;

    pixel *pix = (pixel*)_pix;

    const dctcoef *block = (const dctcoef*)_block;

    stride >>= sizeof(pixel)-1;

    for(i=0; i<8; i++){

        pixel v = pix[-1];

        pix[0]= v += block[0];

        pix[1]= v += block[1];

        pix[2]= v += block[2];

        pix[3]= v += block[3];

        pix[4]= v += block[4];

        pix[5]= v += block[5];

        pix[6]= v += block[6];

        pix[7]= v +  block[7];

        pix+= stride;

        block+= 8;

    }

}

static int vtenc_create_encoder(AVCodecContext   *avctx,

                                CMVideoCodecType codec_type,

                                CFStringRef      profile_level,

                                CFNumberRef      gamma_level,

                                CFDictionaryRef  enc_info,

                                CFDictionaryRef  pixel_buffer_info,

                                VTCompressionSessionRef *session)

{

    VTEncContext *vtctx = avctx->priv_data;

    SInt32       bit_rate = avctx->bit_rate;

    CFNumberRef  bit_rate_num;



    int status = VTCompressionSessionCreate(kCFAllocatorDefault,

                                            avctx->width,

                                            avctx->height,

                                            codec_type,

                                            enc_info,

                                            pixel_buffer_info,

                                            kCFAllocatorDefault,

                                            vtenc_output_callback,

                                            avctx,

                                            session);



    if (status || !vtctx->session) {

        av_log(avctx, AV_LOG_ERROR, "Error: cannot create compression session: %d\n", status);



#if !TARGET_OS_IPHONE

        if (!vtctx->allow_sw) {

            av_log(avctx, AV_LOG_ERROR, "Try -allow_sw 1. The hardware encoder may be busy, or not supported.\n");

        }

#endif



        return AVERROR_EXTERNAL;

    }



    bit_rate_num = CFNumberCreate(kCFAllocatorDefault,

                                  kCFNumberSInt32Type,

                                  &bit_rate);

    if (!bit_rate_num) return AVERROR(ENOMEM);



    status = VTSessionSetProperty(vtctx->session,

                                  kVTCompressionPropertyKey_AverageBitRate,

                                  bit_rate_num);

    CFRelease(bit_rate_num);



    if (status) {

        av_log(avctx, AV_LOG_ERROR, "Error setting bitrate property: %d\n", status);

        return AVERROR_EXTERNAL;

    }



    if (profile_level) {

        status = VTSessionSetProperty(vtctx->session,

                                      kVTCompressionPropertyKey_ProfileLevel,

                                      profile_level);

        if (status) {

            av_log(avctx, AV_LOG_ERROR, "Error setting profile/level property: %d\n", status);

            return AVERROR_EXTERNAL;

        }

    }



    if (avctx->gop_size > 0) {

        CFNumberRef interval = CFNumberCreate(kCFAllocatorDefault,

                                              kCFNumberIntType,

                                              &avctx->gop_size);

        if (!interval) {

            return AVERROR(ENOMEM);

        }



        status = VTSessionSetProperty(vtctx->session,

                                      kVTCompressionPropertyKey_MaxKeyFrameInterval,

                                      interval);

        CFRelease(interval);



        if (status) {

            av_log(avctx, AV_LOG_ERROR, "Error setting 'max key-frame interval' property: %d\n", status);

            return AVERROR_EXTERNAL;

        }

    }



    if (vtctx->frames_before) {

        status = VTSessionSetProperty(vtctx->session,

                                      kVTCompressionPropertyKey_MoreFramesBeforeStart,

                                      kCFBooleanTrue);



        if (status == kVTPropertyNotSupportedErr) {

            av_log(avctx, AV_LOG_WARNING, "frames_before property is not supported on this device. Ignoring.\n");

        } else if (status) {

            av_log(avctx, AV_LOG_ERROR, "Error setting frames_before property: %d\n", status);

        }

    }



    if (vtctx->frames_after) {

        status = VTSessionSetProperty(vtctx->session,

                                      kVTCompressionPropertyKey_MoreFramesAfterEnd,

                                      kCFBooleanTrue);



        if (status == kVTPropertyNotSupportedErr) {

            av_log(avctx, AV_LOG_WARNING, "frames_after property is not supported on this device. Ignoring.\n");

        } else if (status) {

            av_log(avctx, AV_LOG_ERROR, "Error setting frames_after property: %d\n", status);

        }

    }



    if (avctx->sample_aspect_ratio.num != 0) {

        CFNumberRef num;

        CFNumberRef den;

        CFMutableDictionaryRef par;

        AVRational *avpar = &avctx->sample_aspect_ratio;



        av_reduce(&avpar->num, &avpar->den,

                   avpar->num,  avpar->den,

                  0xFFFFFFFF);



        num = CFNumberCreate(kCFAllocatorDefault,

                             kCFNumberIntType,

                             &avpar->num);



        den = CFNumberCreate(kCFAllocatorDefault,

                             kCFNumberIntType,

                             &avpar->den);







        par = CFDictionaryCreateMutable(kCFAllocatorDefault,

                                        2,

                                        &kCFCopyStringDictionaryKeyCallBacks,

                                        &kCFTypeDictionaryValueCallBacks);



        if (!par || !num || !den) {

            if (par) CFRelease(par);

            if (num) CFRelease(num);

            if (den) CFRelease(den);



            return AVERROR(ENOMEM);

        }



        CFDictionarySetValue(

            par,

            kCMFormatDescriptionKey_PixelAspectRatioHorizontalSpacing,

            num);



        CFDictionarySetValue(

            par,

            kCMFormatDescriptionKey_PixelAspectRatioVerticalSpacing,

            den);



        status = VTSessionSetProperty(vtctx->session,

                                      kVTCompressionPropertyKey_PixelAspectRatio,

                                      par);



        CFRelease(par);

        CFRelease(num);

        CFRelease(den);



        if (status) {

            av_log(avctx,

                   AV_LOG_ERROR,

                   "Error setting pixel aspect ratio to %d:%d: %d.\n",

                   avctx->sample_aspect_ratio.num,

                   avctx->sample_aspect_ratio.den,

                   status);



            return AVERROR_EXTERNAL;

        }

    }





    if (vtctx->transfer_function) {

        status = VTSessionSetProperty(vtctx->session,

                                      kVTCompressionPropertyKey_TransferFunction,

                                      vtctx->transfer_function);



        if (status) {

            av_log(avctx, AV_LOG_WARNING, "Could not set transfer function: %d\n", status);

        }

    }





    if (vtctx->ycbcr_matrix) {

        status = VTSessionSetProperty(vtctx->session,

                                      kVTCompressionPropertyKey_YCbCrMatrix,

                                      vtctx->ycbcr_matrix);



        if (status) {

            av_log(avctx, AV_LOG_WARNING, "Could not set ycbcr matrix: %d\n", status);

        }

    }





    if (vtctx->color_primaries) {

        status = VTSessionSetProperty(vtctx->session,

                                      kVTCompressionPropertyKey_ColorPrimaries,

                                      vtctx->color_primaries);



        if (status) {

            av_log(avctx, AV_LOG_WARNING, "Could not set color primaries: %d\n", status);

        }

    }



    if (gamma_level) {

        status = VTSessionSetProperty(vtctx->session,

                                      kCVImageBufferGammaLevelKey,

                                      gamma_level);



        if (status) {

            av_log(avctx, AV_LOG_WARNING, "Could not set gamma level: %d\n", status);

        }

    }



    if (!vtctx->has_b_frames) {

        status = VTSessionSetProperty(vtctx->session,

                                      kVTCompressionPropertyKey_AllowFrameReordering,

                                      kCFBooleanFalse);



        if (status) {

            av_log(avctx, AV_LOG_ERROR, "Error setting 'allow frame reordering' property: %d\n", status);

            return AVERROR_EXTERNAL;

        }

    }



    if (vtctx->entropy != VT_ENTROPY_NOT_SET) {

        CFStringRef entropy = vtctx->entropy == VT_CABAC ?

                                kVTH264EntropyMode_CABAC:

                                kVTH264EntropyMode_CAVLC;



        status = VTSessionSetProperty(vtctx->session,

                                      kVTCompressionPropertyKey_H264EntropyMode,

                                      entropy);



        if (status) {

            av_log(avctx, AV_LOG_ERROR, "Error setting entropy property: %d\n", status);

            return AVERROR_EXTERNAL;

        }

    }



    if (vtctx->realtime) {

        status = VTSessionSetProperty(vtctx->session,

                                      kVTCompressionPropertyKey_RealTime,

                                      kCFBooleanTrue);



        if (status) {

            av_log(avctx, AV_LOG_ERROR, "Error setting realtime property: %d\n", status);

        }

    }



    status = VTCompressionSessionPrepareToEncodeFrames(vtctx->session);

    if (status) {

        av_log(avctx, AV_LOG_ERROR, "Error: cannot prepare encoder: %d\n", status);

        return AVERROR_EXTERNAL;

    }



    return 0;

}

static av_cold int libspeex_decode_init(AVCodecContext *avctx)

{

    LibSpeexContext *s = avctx->priv_data;

    const SpeexMode *mode;



    // defaults in the case of a missing header

    if (avctx->sample_rate <= 8000)

        mode = &speex_nb_mode;

    else if (avctx->sample_rate <= 16000)

        mode = &speex_wb_mode;

    else

        mode = &speex_uwb_mode;



    if (avctx->extradata_size >= 80)

        s->header = speex_packet_to_header(avctx->extradata, avctx->extradata_size);



    avctx->sample_fmt = AV_SAMPLE_FMT_S16;

    if (s->header) {

        avctx->sample_rate = s->header->rate;

        avctx->channels    = s->header->nb_channels;

        s->frame_size      = s->header->frame_size;



        mode = speex_lib_get_mode(s->header->mode);

        if (!mode) {

            av_log(avctx, AV_LOG_ERROR, "Unknown Speex mode %d", s->header->mode);

            return AVERROR_INVALIDDATA;

        }

    } else

        av_log(avctx, AV_LOG_INFO, "Missing Speex header, assuming defaults.\n");



    if (avctx->channels > 2) {

        av_log(avctx, AV_LOG_ERROR, "Only stereo and mono are supported.\n");

        return AVERROR(EINVAL);

    }



    speex_bits_init(&s->bits);

    s->dec_state = speex_decoder_init(mode);

    if (!s->dec_state) {

        av_log(avctx, AV_LOG_ERROR, "Error initializing libspeex decoder.\n");

        return -1;

    }



    if (!s->header) {

        speex_decoder_ctl(s->dec_state, SPEEX_GET_FRAME_SIZE, &s->frame_size);

    }



    if (avctx->channels == 2) {

        SpeexCallback callback;

        callback.callback_id = SPEEX_INBAND_STEREO;

        callback.func = speex_std_stereo_request_handler;

        callback.data = &s->stereo;

        s->stereo = (SpeexStereoState)SPEEX_STEREO_STATE_INIT;

        speex_decoder_ctl(s->dec_state, SPEEX_SET_HANDLER, &callback);

    }



    avcodec_get_frame_defaults(&s->frame);

    avctx->coded_frame = &s->frame;



    return 0;

}

static int mpegts_set_stream_info(AVStream *st, PESContext *pes,

                                  uint32_t stream_type, uint32_t prog_reg_desc)

{

    int old_codec_type= st->codec->codec_type;

    int old_codec_id  = st->codec->codec_id;



    if (old_codec_id != AV_CODEC_ID_NONE && avcodec_is_open(st->codec)) {

        av_log(pes->stream, AV_LOG_DEBUG, "cannot set stream info, codec is open\n");

        return 0;

    }



    avpriv_set_pts_info(st, 33, 1, 90000);

    st->priv_data = pes;

    st->codec->codec_type = AVMEDIA_TYPE_DATA;

    st->codec->codec_id   = AV_CODEC_ID_NONE;

    st->need_parsing = AVSTREAM_PARSE_FULL;

    pes->st = st;

    pes->stream_type = stream_type;



    av_log(pes->stream, AV_LOG_DEBUG,

           "stream=%d stream_type=%x pid=%x prog_reg_desc=%.4s\n",

           st->index, pes->stream_type, pes->pid, (char*)&prog_reg_desc);



    st->codec->codec_tag = pes->stream_type;



    mpegts_find_stream_type(st, pes->stream_type, ISO_types);

    if ((prog_reg_desc == AV_RL32("HDMV") ||

         prog_reg_desc == AV_RL32("HDPR")) &&

        st->codec->codec_id == AV_CODEC_ID_NONE) {

        mpegts_find_stream_type(st, pes->stream_type, HDMV_types);

        if (pes->stream_type == 0x83) {

            // HDMV TrueHD streams also contain an AC3 coded version of the

            // audio track - add a second stream for this

            AVStream *sub_st;

            // priv_data cannot be shared between streams

            PESContext *sub_pes = av_malloc(sizeof(*sub_pes));

            if (!sub_pes)

                return AVERROR(ENOMEM);

            memcpy(sub_pes, pes, sizeof(*sub_pes));



            sub_st = avformat_new_stream(pes->stream, NULL);

            if (!sub_st) {

                av_free(sub_pes);

                return AVERROR(ENOMEM);

            }



            sub_st->id = pes->pid;

            avpriv_set_pts_info(sub_st, 33, 1, 90000);

            sub_st->priv_data = sub_pes;

            sub_st->codec->codec_type = AVMEDIA_TYPE_AUDIO;

            sub_st->codec->codec_id   = AV_CODEC_ID_AC3;

            sub_st->need_parsing = AVSTREAM_PARSE_FULL;

            sub_pes->sub_st = pes->sub_st = sub_st;

        }

    }

    if (st->codec->codec_id == AV_CODEC_ID_NONE)

        mpegts_find_stream_type(st, pes->stream_type, MISC_types);

    if (st->codec->codec_id == AV_CODEC_ID_NONE){

        st->codec->codec_id  = old_codec_id;

        st->codec->codec_type= old_codec_type;

    }



    return 0;

}

