            sd_dst->size = sd_dst->buf->size;



        av_dict_copy(&sd_dst->metadata, sd_src->metadata, 0);




#if FF_API_FRAME_QP

FF_DISABLE_DEPRECATION_WARNINGS

    dst->qscale_table = NULL;

    dst->qstride      = 0;

