int qsv_transcode_init(OutputStream *ost)

{

    InputStream *ist;

    const enum AVPixelFormat *pix_fmt;



    AVDictionaryEntry *e;

    const AVOption *opt;

    int flags = 0;



    int err, i;



    QSVContext *qsv = NULL;

    AVQSVContext *hwctx = NULL;

    mfxIMPL impl;

    mfxVersion ver = { { 3, 1 } };



    /* check if the encoder supports QSV */

    if (!ost->enc->pix_fmts)

        return 0;

    for (pix_fmt = ost->enc->pix_fmts; *pix_fmt != AV_PIX_FMT_NONE; pix_fmt++)

        if (*pix_fmt == AV_PIX_FMT_QSV)

            break;

    if (*pix_fmt == AV_PIX_FMT_NONE)

        return 0;



    if (strcmp(ost->avfilter, "null") || ost->source_index < 0)

        return 0;



    /* check if the decoder supports QSV and the output only goes to this stream */

    ist = input_streams[ost->source_index];

    if (ist->hwaccel_id != HWACCEL_QSV || !ist->dec || !ist->dec->pix_fmts)

        return 0;

    for (pix_fmt = ist->dec->pix_fmts; *pix_fmt != AV_PIX_FMT_NONE; pix_fmt++)

        if (*pix_fmt == AV_PIX_FMT_QSV)

            break;

    if (*pix_fmt == AV_PIX_FMT_NONE)

        return 0;



    for (i = 0; i < nb_output_streams; i++)

        if (output_streams[i] != ost &&

            output_streams[i]->source_index == ost->source_index)

            return 0;



    av_log(NULL, AV_LOG_VERBOSE, "Setting up QSV transcoding\n");



    qsv   = av_mallocz(sizeof(*qsv));

    hwctx = av_qsv_alloc_context();

    if (!qsv || !hwctx)

        goto fail;



    impl = choose_implementation(ist);



    err = MFXInit(impl, &ver, &qsv->session);

    if (err != MFX_ERR_NONE) {

        av_log(NULL, AV_LOG_ERROR, "Error initializing an MFX session: %d\n", err);

        goto fail;

    }



    e = av_dict_get(ost->encoder_opts, "flags", NULL, 0);

    opt = av_opt_find(ost->enc_ctx, "flags", NULL, 0, 0);

    if (e && opt)

        av_opt_eval_flags(ost->enc_ctx, opt, e->value, &flags);



    qsv->ost = ost;



    hwctx->session                = qsv->session;

    hwctx->iopattern              = MFX_IOPATTERN_IN_OPAQUE_MEMORY;

    hwctx->opaque_alloc           = 1;

    hwctx->nb_opaque_surfaces     = 16;



    ost->hwaccel_ctx              = qsv;

    ost->enc_ctx->hwaccel_context = hwctx;

    ost->enc_ctx->pix_fmt         = AV_PIX_FMT_QSV;



    ist->hwaccel_ctx              = qsv;

    ist->dec_ctx->pix_fmt         = AV_PIX_FMT_QSV;

    ist->resample_pix_fmt         = AV_PIX_FMT_QSV;



    return 0;



fail:

    av_freep(&hwctx);

    av_freep(&qsv);

    return AVERROR_UNKNOWN;

}

static int mov_write_ftyp_tag(AVIOContext *pb, AVFormatContext *s)

{

    MOVMuxContext *mov = s->priv_data;

    int64_t pos = avio_tell(pb);

    int has_h264 = 0, has_video = 0;

    int minor = 0x200;

    int i;



    for (i = 0; i < s->nb_streams; i++) {

        AVStream *st = s->streams[i];

        if (st->codec->codec_type == AVMEDIA_TYPE_VIDEO)

            has_video = 1;

        if (st->codec->codec_id == AV_CODEC_ID_H264)

            has_h264 = 1;

    }



    avio_wb32(pb, 0); /* size */

    ffio_wfourcc(pb, "ftyp");



    if (mov->mode == MODE_3GP) {

        ffio_wfourcc(pb, has_h264 ? "3gp6"  : "3gp4");

        minor =     has_h264 ?   0x100 :   0x200;

    } else if (mov->mode & MODE_3G2) {

        ffio_wfourcc(pb, has_h264 ? "3g2b"  : "3g2a");

        minor =     has_h264 ? 0x20000 : 0x10000;

    } else if (mov->mode == MODE_PSP)

        ffio_wfourcc(pb, "MSNV");

    else if (mov->mode == MODE_MP4)

        ffio_wfourcc(pb, "isom");

    else if (mov->mode == MODE_IPOD)

        ffio_wfourcc(pb, has_video ? "M4V ":"M4A ");

    else if (mov->mode == MODE_ISM)

        ffio_wfourcc(pb, "isml");

    else if (mov->mode == MODE_F4V)

        ffio_wfourcc(pb, "f4v ");

    else

        ffio_wfourcc(pb, "qt  ");



    avio_wb32(pb, minor);



    if (mov->mode == MODE_MOV)

        ffio_wfourcc(pb, "qt  ");

    else if (mov->mode == MODE_ISM) {

        ffio_wfourcc(pb, "piff");

        ffio_wfourcc(pb, "iso2");

    } else {

        ffio_wfourcc(pb, "isom");

        ffio_wfourcc(pb, "iso2");

        if (has_h264)

            ffio_wfourcc(pb, "avc1");

    }



    if (mov->mode == MODE_3GP)

        ffio_wfourcc(pb, has_h264 ? "3gp6":"3gp4");

    else if (mov->mode & MODE_3G2)

        ffio_wfourcc(pb, has_h264 ? "3g2b":"3g2a");

    else if (mov->mode == MODE_PSP)

        ffio_wfourcc(pb, "MSNV");

    else if (mov->mode == MODE_MP4)

        ffio_wfourcc(pb, "mp41");

    return update_size(pb, pos);

}

static av_cold int bktr_init(const char *video_device, int width, int height,

    int format, int *video_fd, int *tuner_fd, int idev, double frequency)

{

    struct meteor_geomet geo;

    int h_max;

    long ioctl_frequency;

    char *arg;

    int c;

    struct sigaction act = { 0 }, old;



    if (idev < 0 || idev > 4)

    {

        arg = getenv ("BKTR_DEV");

        if (arg)

            idev = atoi (arg);

        if (idev < 0 || idev > 4)

            idev = 1;

    }



    if (format < 1 || format > 6)

    {

        arg = getenv ("BKTR_FORMAT");

        if (arg)

            format = atoi (arg);

        if (format < 1 || format > 6)

            format = VIDEO_FORMAT;

    }



    if (frequency <= 0)

    {

        arg = getenv ("BKTR_FREQUENCY");

        if (arg)

            frequency = atof (arg);

        if (frequency <= 0)

            frequency = 0.0;

    }



    sigemptyset(&act.sa_mask);

    act.sa_handler = catchsignal;

    sigaction(SIGUSR1, &act, &old);



    *tuner_fd = open("/dev/tuner0", O_RDONLY);

    if (*tuner_fd < 0)

        av_log(NULL, AV_LOG_ERROR, "Warning. Tuner not opened, continuing: %s\n", strerror(errno));



    *video_fd = open(video_device, O_RDONLY);

    if (*video_fd < 0) {

        av_log(NULL, AV_LOG_ERROR, "%s: %s\n", video_device, strerror(errno));

        return -1;

    }



    geo.rows = height;

    geo.columns = width;

    geo.frames = 1;

    geo.oformat = METEOR_GEO_YUV_422 | METEOR_GEO_YUV_12;



    switch (format) {

    case PAL:   h_max = PAL_HEIGHT;   c = BT848_IFORM_F_PALBDGHI; break;

    case PALN:  h_max = PAL_HEIGHT;   c = BT848_IFORM_F_PALN;     break;

    case PALM:  h_max = PAL_HEIGHT;   c = BT848_IFORM_F_PALM;     break;

    case SECAM: h_max = SECAM_HEIGHT; c = BT848_IFORM_F_SECAM;    break;

    case NTSC:  h_max = NTSC_HEIGHT;  c = BT848_IFORM_F_NTSCM;    break;

    case NTSCJ: h_max = NTSC_HEIGHT;  c = BT848_IFORM_F_NTSCJ;    break;

    default:    h_max = PAL_HEIGHT;   c = BT848_IFORM_F_PALBDGHI; break;

    }



    if (height <= h_max / 2)

        geo.oformat |= METEOR_GEO_EVEN_ONLY;



    if (ioctl(*video_fd, METEORSETGEO, &geo) < 0) {

        av_log(NULL, AV_LOG_ERROR, "METEORSETGEO: %s\n", strerror(errno));

        return -1;

    }



    if (ioctl(*video_fd, BT848SFMT, &c) < 0) {

        av_log(NULL, AV_LOG_ERROR, "BT848SFMT: %s\n", strerror(errno));

        return -1;

    }



    c = bktr_dev[idev];

    if (ioctl(*video_fd, METEORSINPUT, &c) < 0) {

        av_log(NULL, AV_LOG_ERROR, "METEORSINPUT: %s\n", strerror(errno));

        return -1;

    }



    video_buf_size = width * height * 12 / 8;



    video_buf = (uint8_t *)mmap((caddr_t)0, video_buf_size,

        PROT_READ, MAP_SHARED, *video_fd, (off_t)0);

    if (video_buf == MAP_FAILED) {

        av_log(NULL, AV_LOG_ERROR, "mmap: %s\n", strerror(errno));

        return -1;

    }



    if (frequency != 0.0) {

        ioctl_frequency  = (unsigned long)(frequency*16);

        if (ioctl(*tuner_fd, TVTUNER_SETFREQ, &ioctl_frequency) < 0)

            av_log(NULL, AV_LOG_ERROR, "TVTUNER_SETFREQ: %s\n", strerror(errno));

    }



    c = AUDIO_UNMUTE;

    if (ioctl(*tuner_fd, BT848_SAUDIO, &c) < 0)

        av_log(NULL, AV_LOG_ERROR, "TVTUNER_SAUDIO: %s\n", strerror(errno));



    c = METEOR_CAP_CONTINOUS;

    ioctl(*video_fd, METEORCAPTUR, &c);



    c = SIGUSR1;

    ioctl(*video_fd, METEORSSIGNAL, &c);



    return 0;

}

static inline int wv_unpack_stereo(WavpackFrameContext *s, GetBitContext *gb,
                                   void *dst_l, void *dst_r, const int type)
{
    int i, j, count = 0;
    int last, t;
    int A, B, L, L2, R, R2;
    int pos                 = s->pos;
    uint32_t crc            = s->sc.crc;
    uint32_t crc_extra_bits = s->extra_sc.crc;
    int16_t *dst16_l        = dst_l;
    int16_t *dst16_r        = dst_r;
    int32_t *dst32_l        = dst_l;
    int32_t *dst32_r        = dst_r;
    float *dstfl_l          = dst_l;
    float *dstfl_r          = dst_r;
    s->one = s->zero = s->zeroes = 0;
    do {
        L = wv_get_value(s, gb, 0, &last);
        if (last)
            break;
        R = wv_get_value(s, gb, 1, &last);
        if (last)
            break;
        for (i = 0; i < s->terms; i++) {
            t = s->decorr[i].value;
            if (t > 0) {
                if (t > 8) {
                    if (t & 1) {
                        A = 2 * s->decorr[i].samplesA[0] - s->decorr[i].samplesA[1];
                        B = 2 * s->decorr[i].samplesB[0] - s->decorr[i].samplesB[1];
                    } else {
                        A = (3 * s->decorr[i].samplesA[0] - s->decorr[i].samplesA[1]) >> 1;
                        B = (3 * s->decorr[i].samplesB[0] - s->decorr[i].samplesB[1]) >> 1;
                    s->decorr[i].samplesA[1] = s->decorr[i].samplesA[0];
                    s->decorr[i].samplesB[1] = s->decorr[i].samplesB[0];
                    j                        = 0;
                } else {
                    A = s->decorr[i].samplesA[pos];
                    B = s->decorr[i].samplesB[pos];
                    j = (pos + t) & 7;
                if (type != AV_SAMPLE_FMT_S16P) {
                    L2 = L + ((s->decorr[i].weightA * (int64_t)A + 512) >> 10);
                    R2 = R + ((s->decorr[i].weightB * (int64_t)B + 512) >> 10);
                } else {
                    L2 = L + ((s->decorr[i].weightA * A + 512) >> 10);
                    R2 = R + ((s->decorr[i].weightB * B + 512) >> 10);
                if (A && L)
                    s->decorr[i].weightA -= ((((L ^ A) >> 30) & 2) - 1) * s->decorr[i].delta;
                if (B && R)
                    s->decorr[i].weightB -= ((((R ^ B) >> 30) & 2) - 1) * s->decorr[i].delta;
                s->decorr[i].samplesA[j] = L = L2;
                s->decorr[i].samplesB[j] = R = R2;
            } else if (t == -1) {
                if (type != AV_SAMPLE_FMT_S16P)
                    L2 = L + ((s->decorr[i].weightA * (int64_t)s->decorr[i].samplesA[0] + 512) >> 10);
                else
                    L2 = L + ((s->decorr[i].weightA * s->decorr[i].samplesA[0] + 512) >> 10);
                UPDATE_WEIGHT_CLIP(s->decorr[i].weightA, s->decorr[i].delta, s->decorr[i].samplesA[0], L);
                L = L2;
                if (type != AV_SAMPLE_FMT_S16P)
                    R2 = R + ((s->decorr[i].weightB * (int64_t)L2 + 512) >> 10);
                else
                    R2 = R + ((s->decorr[i].weightB * L2 + 512) >> 10);
                UPDATE_WEIGHT_CLIP(s->decorr[i].weightB, s->decorr[i].delta, L2, R);
                R                        = R2;
                s->decorr[i].samplesA[0] = R;
            } else {
                if (type != AV_SAMPLE_FMT_S16P)
                    R2 = R + ((s->decorr[i].weightB * (int64_t)s->decorr[i].samplesB[0] + 512) >> 10);
                else
                    R2 = R + ((s->decorr[i].weightB * s->decorr[i].samplesB[0] + 512) >> 10);
                UPDATE_WEIGHT_CLIP(s->decorr[i].weightB, s->decorr[i].delta, s->decorr[i].samplesB[0], R);
                R = R2;
                if (t == -3) {
                    R2                       = s->decorr[i].samplesA[0];
                    s->decorr[i].samplesA[0] = R;
                if (type != AV_SAMPLE_FMT_S16P)
                    L2 = L + ((s->decorr[i].weightA * (int64_t)R2 + 512) >> 10);
                else
                    L2 = L + ((s->decorr[i].weightA * R2 + 512) >> 10);
                UPDATE_WEIGHT_CLIP(s->decorr[i].weightA, s->decorr[i].delta, R2, L);
                L                        = L2;
                s->decorr[i].samplesB[0] = L;
        pos = (pos + 1) & 7;
        if (s->joint)
            L += (R -= (L >> 1));
        crc = (crc * 3 + L) * 3 + R;
        if (type == AV_SAMPLE_FMT_FLTP) {
            *dstfl_l++ = wv_get_value_float(s, &crc_extra_bits, L);
            *dstfl_r++ = wv_get_value_float(s, &crc_extra_bits, R);
        } else if (type == AV_SAMPLE_FMT_S32P) {
            *dst32_l++ = wv_get_value_integer(s, &crc_extra_bits, L);
            *dst32_r++ = wv_get_value_integer(s, &crc_extra_bits, R);
        } else {
            *dst16_l++ = wv_get_value_integer(s, &crc_extra_bits, L);
            *dst16_r++ = wv_get_value_integer(s, &crc_extra_bits, R);
        count++;
    } while (!last && count < s->samples);
    wv_reset_saved_context(s);
    if ((s->avctx->err_recognition & AV_EF_CRCCHECK) &&
        wv_check_crc(s, crc, crc_extra_bits))
        return AVERROR_INVALIDDATA;
    return 0;

void ff_jpeg2000_cleanup(Jpeg2000Component *comp, Jpeg2000CodingStyle *codsty)

{

    int reslevelno, bandno, precno;

    for (reslevelno = 0;

         comp->reslevel && reslevelno < codsty->nreslevels;

         reslevelno++) {

        Jpeg2000ResLevel *reslevel;



        if (!comp->reslevel)

            continue;



        reslevel = comp->reslevel + reslevelno;

        for (bandno = 0; bandno < reslevel->nbands; bandno++) {

            Jpeg2000Band *band;



            if (!reslevel->band)

                continue;



            band = reslevel->band + bandno;

            for (precno = 0; precno < reslevel->num_precincts_x * reslevel->num_precincts_y; precno++) {

                if (band->prec) {

                    Jpeg2000Prec *prec = band->prec + precno;

                    av_freep(&prec->zerobits);

                    av_freep(&prec->cblkincl);

                    av_freep(&prec->cblk);

                }

            }



            av_freep(&band->prec);

        }

        av_freep(&reslevel->band);

    }



    ff_dwt_destroy(&comp->dwt);

    av_freep(&comp->reslevel);

    av_freep(&comp->i_data);

    av_freep(&comp->f_data);

}

static int smacker_decode_header_tree(SmackVContext *smk, BitstreamContext *bc,

                                      int **recodes, int *last, int size)

{

    int res;

    HuffContext huff;

    HuffContext tmp1, tmp2;

    VLC vlc[2] = { { 0 } };

    int escapes[3];

    DBCtx ctx;

    int err = 0;



    if(size >= UINT_MAX>>4){ // (((size + 3) >> 2) + 3) << 2 must not overflow

        av_log(smk->avctx, AV_LOG_ERROR, "size too large\n");

        return AVERROR_INVALIDDATA;

    }



    tmp1.length = 256;

    tmp1.maxlength = 0;

    tmp1.current = 0;

    tmp1.bits = av_mallocz(256 * 4);

    tmp1.lengths = av_mallocz(256 * sizeof(int));

    tmp1.values = av_mallocz(256 * sizeof(int));



    tmp2.length = 256;

    tmp2.maxlength = 0;

    tmp2.current = 0;

    tmp2.bits = av_mallocz(256 * 4);

    tmp2.lengths = av_mallocz(256 * sizeof(int));

    tmp2.values = av_mallocz(256 * sizeof(int));

    if (!tmp1.bits || !tmp1.lengths || !tmp1.values ||

        !tmp2.bits || !tmp2.lengths || !tmp2.values) {

        err = AVERROR(ENOMEM);

        goto error;

    }



    if (bitstream_read_bit(bc)) {

        smacker_decode_tree(bc, &tmp1, 0, 0);

        bitstream_skip(bc, 1);

        res = init_vlc(&vlc[0], SMKTREE_BITS, tmp1.length,

                    tmp1.lengths, sizeof(int), sizeof(int),

                    tmp1.bits, sizeof(uint32_t), sizeof(uint32_t), INIT_VLC_LE);

        if(res < 0) {

            av_log(smk->avctx, AV_LOG_ERROR, "Cannot build VLC table\n");

            err = res;

            goto error;

        }

    } else {

        av_log(smk->avctx, AV_LOG_ERROR, "Skipping low bytes tree\n");

    }

    if (bitstream_read_bit(bc)) {

        smacker_decode_tree(bc, &tmp2, 0, 0);

        bitstream_skip(bc, 1);

        res = init_vlc(&vlc[1], SMKTREE_BITS, tmp2.length,

                    tmp2.lengths, sizeof(int), sizeof(int),

                    tmp2.bits, sizeof(uint32_t), sizeof(uint32_t), INIT_VLC_LE);

        if(res < 0) {

            av_log(smk->avctx, AV_LOG_ERROR, "Cannot build VLC table\n");

            err = res;

            goto error;

        }

    } else {

        av_log(smk->avctx, AV_LOG_ERROR, "Skipping high bytes tree\n");

    }



    escapes[0]  = bitstream_read(bc, 8);

    escapes[0] |= bitstream_read(bc, 8) << 8;

    escapes[1]  = bitstream_read(bc, 8);

    escapes[1] |= bitstream_read(bc, 8) << 8;

    escapes[2]  = bitstream_read(bc, 8);

    escapes[2] |= bitstream_read(bc, 8) << 8;



    last[0] = last[1] = last[2] = -1;



    ctx.escapes[0] = escapes[0];

    ctx.escapes[1] = escapes[1];

    ctx.escapes[2] = escapes[2];

    ctx.v1 = &vlc[0];

    ctx.v2 = &vlc[1];

    ctx.recode1 = tmp1.values;

    ctx.recode2 = tmp2.values;

    ctx.last = last;



    huff.length = ((size + 3) >> 2) + 4;

    huff.maxlength = 0;

    huff.current = 0;

    huff.values = av_mallocz(huff.length * sizeof(int));

    if (!huff.values) {

        err = AVERROR(ENOMEM);

        goto error;

    }



    if ((res = smacker_decode_bigtree(bc, &huff, &ctx)) < 0)

        err = res;

    bitstream_skip(bc, 1);

    if(ctx.last[0] == -1) ctx.last[0] = huff.current++;

    if(ctx.last[1] == -1) ctx.last[1] = huff.current++;

    if(ctx.last[2] == -1) ctx.last[2] = huff.current++;

    if (ctx.last[0] >= huff.length ||

        ctx.last[1] >= huff.length ||

        ctx.last[2] >= huff.length) {

        av_log(smk->avctx, AV_LOG_ERROR, "Huffman codes out of range\n");

        err = AVERROR_INVALIDDATA;

    }



    *recodes = huff.values;



error:

    if(vlc[0].table)

        ff_free_vlc(&vlc[0]);

    if(vlc[1].table)

        ff_free_vlc(&vlc[1]);

    av_free(tmp1.bits);

    av_free(tmp1.lengths);

    av_free(tmp1.values);

    av_free(tmp2.bits);

    av_free(tmp2.lengths);

    av_free(tmp2.values);



    return err;

}

static inline void RENAME(yuv2rgb565_1)(SwsContext *c, const uint16_t *buf0,

                                        const uint16_t *ubuf0, const uint16_t *ubuf1,

                                        const uint16_t *vbuf0, const uint16_t *vbuf1,

                                        const uint16_t *abuf0, uint8_t *dest,

                                        int dstW, int uvalpha, enum PixelFormat dstFormat,

                                        int flags, int y)

{

    x86_reg uv_off = c->uv_off << 1;

    const uint16_t *buf1= buf0; //FIXME needed for RGB1/BGR1



    if (uvalpha < 2048) { // note this is not correct (shifts chrominance by 0.5 pixels) but it is a bit faster

        __asm__ volatile(

            "mov %%"REG_b", "ESP_OFFSET"(%5)        \n\t"

            "mov        %4, %%"REG_b"               \n\t"

            "push %%"REG_BP"                        \n\t"

            YSCALEYUV2RGB1(%%REGBP, %5, %6)

            "pxor    %%mm7, %%mm7                   \n\t"

            /* mm2=B, %%mm4=G, %%mm5=R, %%mm7=0 */

#ifdef DITHER1XBPP

            "paddusb "BLUE_DITHER"(%5), %%mm2      \n\t"

            "paddusb "GREEN_DITHER"(%5), %%mm4      \n\t"

            "paddusb "RED_DITHER"(%5), %%mm5      \n\t"

#endif

            WRITERGB16(%%REGb, 8280(%5), %%REGBP)

            "pop %%"REG_BP"                         \n\t"

            "mov "ESP_OFFSET"(%5), %%"REG_b"        \n\t"

            :: "c" (buf0), "d" (buf1), "S" (ubuf0), "D" (ubuf1), "m" (dest),

               "a" (&c->redDither), "m"(uv_off)

        );

    } else {

        __asm__ volatile(

            "mov %%"REG_b", "ESP_OFFSET"(%5)        \n\t"

            "mov        %4, %%"REG_b"               \n\t"

            "push %%"REG_BP"                        \n\t"

            YSCALEYUV2RGB1b(%%REGBP, %5, %6)

            "pxor    %%mm7, %%mm7                   \n\t"

            /* mm2=B, %%mm4=G, %%mm5=R, %%mm7=0 */

#ifdef DITHER1XBPP

            "paddusb "BLUE_DITHER"(%5), %%mm2      \n\t"

            "paddusb "GREEN_DITHER"(%5), %%mm4      \n\t"

            "paddusb "RED_DITHER"(%5), %%mm5      \n\t"

#endif

            WRITERGB16(%%REGb, 8280(%5), %%REGBP)

            "pop %%"REG_BP"                         \n\t"

            "mov "ESP_OFFSET"(%5), %%"REG_b"        \n\t"

            :: "c" (buf0), "d" (buf1), "S" (ubuf0), "D" (ubuf1), "m" (dest),

               "a" (&c->redDither), "m"(uv_off)

        );

    }

}

int RENAME(swri_resample)(ResampleContext *c, DELEM *dst, const DELEM *src, int *consumed, int src_size, int dst_size, int update_ctx){

    int dst_index, i;

    int index= c->index;

    int frac= c->frac;

    int dst_incr_frac= c->dst_incr % c->src_incr;

    int dst_incr=      c->dst_incr / c->src_incr;

    int compensation_distance= c->compensation_distance;



    av_assert1(c->filter_shift == FILTER_SHIFT);

    av_assert1(c->felem_size == sizeof(FELEM));



    if(compensation_distance == 0 && c->filter_length == 1 && c->phase_shift==0){

        int64_t index2= (1LL<<32)*c->frac/c->src_incr + (1LL<<32)*index;

        int64_t incr= (1LL<<32) * c->dst_incr / c->src_incr;

        int new_size = (src_size * (int64_t)c->src_incr - frac + c->dst_incr - 1) / c->dst_incr;



        dst_size= FFMIN(dst_size, new_size);



        for(dst_index=0; dst_index < dst_size; dst_index++){

            dst[dst_index] = src[index2>>32];

            index2 += incr;

        }

        index += dst_index * dst_incr;

        index += (frac + dst_index * (int64_t)dst_incr_frac) / c->src_incr;

        frac   = (frac + dst_index * (int64_t)dst_incr_frac) % c->src_incr;

        av_assert2(index >= 0);

        *consumed= index;

        index = 0;

    } else if (compensation_distance == 0 && index >= 0) {

        int64_t end_index = (1 + src_size - c->filter_length) << c->phase_shift;

        int64_t delta_frac = (end_index - index) * c->src_incr - c->frac;

        int delta_n = (delta_frac + c->dst_incr - 1) / c->dst_incr;

        int n = FFMIN(dst_size, delta_n);

        int sample_index;



        if (!c->linear) {

            sample_index = index >> c->phase_shift;

            index &= c->phase_mask;

            for (dst_index = 0; dst_index < n; dst_index++) {

                FELEM *filter = ((FELEM *) c->filter_bank) + c->filter_alloc * index;



#ifdef COMMON_CORE

                COMMON_CORE

#else

                FELEM2 val=0;

                for (i = 0; i < c->filter_length; i++) {

                    val += src[sample_index + i] * (FELEM2)filter[i];

                }

                OUT(dst[dst_index], val);

#endif



                frac += dst_incr_frac;

                index += dst_incr;

                if (frac >= c->src_incr) {

                    frac -= c->src_incr;

                    index++;

                }

                sample_index += index >> c->phase_shift;

                index &= c->phase_mask;

            }

        } else {

            sample_index = index >> c->phase_shift;

            index &= c->phase_mask;

            for (dst_index = 0; dst_index < n; dst_index++) {

                FELEM *filter = ((FELEM *) c->filter_bank) + c->filter_alloc * index;

                FELEM2 val=0, v2 = 0;



#ifdef LINEAR_CORE

                LINEAR_CORE

#else

                for (i = 0; i < c->filter_length; i++) {

                    val += src[sample_index + i] * (FELEM2)filter[i];

                    v2  += src[sample_index + i] * (FELEM2)filter[i + c->filter_alloc];

                }

#endif

                val += (v2 - val) * (FELEML) frac / c->src_incr;

                OUT(dst[dst_index], val);



                frac += dst_incr_frac;

                index += dst_incr;

                if (frac >= c->src_incr) {

                    frac -= c->src_incr;

                    index++;

                }

                sample_index += index >> c->phase_shift;

                index &= c->phase_mask;

            }

        }



        *consumed = sample_index;

    } else {

        int sample_index = 0;

        for(dst_index=0; dst_index < dst_size; dst_index++){

            FELEM *filter;

            FELEM2 val=0;



            sample_index += index >> c->phase_shift;

            index &= c->phase_mask;

            filter = ((FELEM*)c->filter_bank) + c->filter_alloc*index;



            if(sample_index + c->filter_length > src_size || -sample_index >= src_size){

                break;

            }else if(sample_index < 0){

                for(i=0; i<c->filter_length; i++)

                    val += src[FFABS(sample_index + i)] * (FELEM2)filter[i];

                OUT(dst[dst_index], val);

            }else if(c->linear){

                FELEM2 v2=0;

#ifdef LINEAR_CORE

                LINEAR_CORE

#else

                for(i=0; i<c->filter_length; i++){

                    val += src[sample_index + i] * (FELEM2)filter[i];

                    v2  += src[sample_index + i] * (FELEM2)filter[i + c->filter_alloc];

                }

#endif

                val+=(v2-val)*(FELEML)frac / c->src_incr;

                OUT(dst[dst_index], val);

            }else{

#ifdef COMMON_CORE

                COMMON_CORE

#else

                for(i=0; i<c->filter_length; i++){

                    val += src[sample_index + i] * (FELEM2)filter[i];

                }

                OUT(dst[dst_index], val);

#endif

            }



            frac += dst_incr_frac;

            index += dst_incr;

            if(frac >= c->src_incr){

                frac -= c->src_incr;

                index++;

            }



            if(dst_index + 1 == compensation_distance){

                compensation_distance= 0;

                dst_incr_frac= c->ideal_dst_incr % c->src_incr;

                dst_incr=      c->ideal_dst_incr / c->src_incr;

            }

        }

        *consumed= FFMAX(sample_index, 0);

        index += FFMIN(sample_index, 0) << c->phase_shift;



        if(compensation_distance){

            compensation_distance -= dst_index;

            av_assert1(compensation_distance > 0);

        }

    }



    if(update_ctx){

        c->frac= frac;

        c->index= index;

        c->dst_incr= dst_incr_frac + c->src_incr*dst_incr;

        c->compensation_distance= compensation_distance;

    }



    return dst_index;

}

static int dca_subframe_footer(DCAContext *s, int base_channel)

{

    int in, out, aux_data_count, aux_data_end, reserved;

    uint32_t nsyncaux;



    /*

     * Unpack optional information

     */



    /* presumably optional information only appears in the core? */

    if (!base_channel) {

        if (s->timestamp)

            skip_bits_long(&s->gb, 32);



        if (s->aux_data) {

            aux_data_count = get_bits(&s->gb, 6);



            // align (32-bit)

            skip_bits_long(&s->gb, (-get_bits_count(&s->gb)) & 31);



            aux_data_end = 8 * aux_data_count + get_bits_count(&s->gb);



            if ((nsyncaux = get_bits_long(&s->gb, 32)) != DCA_NSYNCAUX) {

                av_log(s->avctx, AV_LOG_ERROR, "nSYNCAUX mismatch %#"PRIx32"\n",

                       nsyncaux);

                return AVERROR_INVALIDDATA;

            }



            if (get_bits1(&s->gb)) { // bAUXTimeStampFlag

                avpriv_request_sample(s->avctx,

                                      "Auxiliary Decode Time Stamp Flag");

                // align (4-bit)

                skip_bits(&s->gb, (-get_bits_count(&s->gb)) & 4);

                // 44 bits: nMSByte (8), nMarker (4), nLSByte (28), nMarker (4)

                skip_bits_long(&s->gb, 44);

            }



            if ((s->core_downmix = get_bits1(&s->gb))) {

                int am = get_bits(&s->gb, 3);

                switch (am) {

                case 0:

                    s->core_downmix_amode = DCA_MONO;

                    break;

                case 1:

                    s->core_downmix_amode = DCA_STEREO;

                    break;

                case 2:

                    s->core_downmix_amode = DCA_STEREO_TOTAL;

                    break;

                case 3:

                    s->core_downmix_amode = DCA_3F;

                    break;

                case 4:

                    s->core_downmix_amode = DCA_2F1R;

                    break;

                case 5:

                    s->core_downmix_amode = DCA_2F2R;

                    break;

                case 6:

                    s->core_downmix_amode = DCA_3F1R;

                    break;

                default:

                    av_log(s->avctx, AV_LOG_ERROR,

                           "Invalid mode %d for embedded downmix coefficients\n",

                           am);

                    return AVERROR_INVALIDDATA;

                }

                for (out = 0; out < ff_dca_channels[s->core_downmix_amode]; out++) {

                    for (in = 0; in < s->audio_header.prim_channels + !!s->lfe; in++) {

                        uint16_t tmp = get_bits(&s->gb, 9);

                        if ((tmp & 0xFF) > 241) {

                            av_log(s->avctx, AV_LOG_ERROR,

                                   "Invalid downmix coefficient code %"PRIu16"\n",

                                   tmp);

                            return AVERROR_INVALIDDATA;

                        }

                        s->core_downmix_codes[in][out] = tmp;

                    }

                }

            }



            align_get_bits(&s->gb); // byte align

            skip_bits(&s->gb, 16);  // nAUXCRC16



            // additional data (reserved, cf. ETSI TS 102 114 V1.4.1)

            if ((reserved = (aux_data_end - get_bits_count(&s->gb))) < 0) {

                av_log(s->avctx, AV_LOG_ERROR,

                       "Overread auxiliary data by %d bits\n", -reserved);

                return AVERROR_INVALIDDATA;

            } else if (reserved) {

                avpriv_request_sample(s->avctx,

                                      "Core auxiliary data reserved content");

                skip_bits_long(&s->gb, reserved);

            }

        }



        if (s->crc_present && s->dynrange)

            get_bits(&s->gb, 16);

    }



    return 0;

}

static void pred_temp_direct_motion(const H264Context *const h, H264SliceContext *sl,

                                    int *mb_type)

{

    int b8_stride = 2;

    int b4_stride = h->b_stride;

    int mb_xy = sl->mb_xy, mb_y = sl->mb_y;

    int mb_type_col[2];

    const int16_t (*l1mv0)[2], (*l1mv1)[2];

    const int8_t *l1ref0, *l1ref1;

    const int is_b8x8 = IS_8X8(*mb_type);

    unsigned int sub_mb_type;

    int i8, i4;



    assert(sl->ref_list[1][0].reference & 3);



    await_reference_mb_row(h, sl->ref_list[1][0].parent,

                           sl->mb_y + !!IS_INTERLACED(*mb_type));



    if (IS_INTERLACED(sl->ref_list[1][0].parent->mb_type[mb_xy])) { // AFL/AFR/FR/FL -> AFL/FL

        if (!IS_INTERLACED(*mb_type)) {                    //     AFR/FR    -> AFL/FL

            mb_y  = (sl->mb_y & ~1) + sl->col_parity;

            mb_xy = sl->mb_x +

                    ((sl->mb_y & ~1) + sl->col_parity) * h->mb_stride;

            b8_stride = 0;

        } else {

            mb_y  += sl->col_fieldoff;

            mb_xy += h->mb_stride * sl->col_fieldoff; // non-zero for FL -> FL & differ parity

        }

        goto single_col;

    } else {                                        // AFL/AFR/FR/FL -> AFR/FR

        if (IS_INTERLACED(*mb_type)) {              // AFL       /FL -> AFR/FR

            mb_y           = sl->mb_y & ~1;

            mb_xy          = sl->mb_x + (sl->mb_y & ~1) * h->mb_stride;

            mb_type_col[0] = sl->ref_list[1][0].parent->mb_type[mb_xy];

            mb_type_col[1] = sl->ref_list[1][0].parent->mb_type[mb_xy + h->mb_stride];

            b8_stride      = 2 + 4 * h->mb_stride;

            b4_stride     *= 6;

            if (IS_INTERLACED(mb_type_col[0]) !=

                IS_INTERLACED(mb_type_col[1])) {

                mb_type_col[0] &= ~MB_TYPE_INTERLACED;

                mb_type_col[1] &= ~MB_TYPE_INTERLACED;

            }



            sub_mb_type = MB_TYPE_16x16 | MB_TYPE_P0L0 | MB_TYPE_P0L1 |

                          MB_TYPE_DIRECT2;                  /* B_SUB_8x8 */



            if ((mb_type_col[0] & MB_TYPE_16x16_OR_INTRA) &&

                (mb_type_col[1] & MB_TYPE_16x16_OR_INTRA) &&

                !is_b8x8) {

                *mb_type |= MB_TYPE_16x8 | MB_TYPE_L0L1 |

                            MB_TYPE_DIRECT2;                /* B_16x8 */

            } else {

                *mb_type |= MB_TYPE_8x8 | MB_TYPE_L0L1;

            }

        } else {                                    //     AFR/FR    -> AFR/FR

single_col:

            mb_type_col[0]     =

                mb_type_col[1] = sl->ref_list[1][0].parent->mb_type[mb_xy];



            sub_mb_type = MB_TYPE_16x16 | MB_TYPE_P0L0 | MB_TYPE_P0L1 |

                          MB_TYPE_DIRECT2;                  /* B_SUB_8x8 */

            if (!is_b8x8 && (mb_type_col[0] & MB_TYPE_16x16_OR_INTRA)) {

                *mb_type |= MB_TYPE_16x16 | MB_TYPE_P0L0 | MB_TYPE_P0L1 |

                            MB_TYPE_DIRECT2;                /* B_16x16 */

            } else if (!is_b8x8 &&

                       (mb_type_col[0] & (MB_TYPE_16x8 | MB_TYPE_8x16))) {

                *mb_type |= MB_TYPE_L0L1 | MB_TYPE_DIRECT2 |

                            (mb_type_col[0] & (MB_TYPE_16x8 | MB_TYPE_8x16));

            } else {

                if (!h->ps.sps->direct_8x8_inference_flag) {

                    /* FIXME: save sub mb types from previous frames (or derive

                     * from MVs) so we know exactly what block size to use */

                    sub_mb_type = MB_TYPE_8x8 | MB_TYPE_P0L0 | MB_TYPE_P0L1 |

                                  MB_TYPE_DIRECT2;          /* B_SUB_4x4 */

                }

                *mb_type |= MB_TYPE_8x8 | MB_TYPE_L0L1;

            }

        }

    }



    await_reference_mb_row(h, sl->ref_list[1][0].parent, mb_y);



    l1mv0  = &sl->ref_list[1][0].parent->motion_val[0][h->mb2b_xy[mb_xy]];

    l1mv1  = &sl->ref_list[1][0].parent->motion_val[1][h->mb2b_xy[mb_xy]];

    l1ref0 = &sl->ref_list[1][0].parent->ref_index[0][4 * mb_xy];

    l1ref1 = &sl->ref_list[1][0].parent->ref_index[1][4 * mb_xy];

    if (!b8_stride) {

        if (sl->mb_y & 1) {

            l1ref0 += 2;

            l1ref1 += 2;

            l1mv0  += 2 * b4_stride;

            l1mv1  += 2 * b4_stride;

        }

    }



    {

        const int *map_col_to_list0[2] = { sl->map_col_to_list0[0],

                                           sl->map_col_to_list0[1] };

        const int *dist_scale_factor = sl->dist_scale_factor;

        int ref_offset;



        if (FRAME_MBAFF(h) && IS_INTERLACED(*mb_type)) {

            map_col_to_list0[0] = sl->map_col_to_list0_field[sl->mb_y & 1][0];

            map_col_to_list0[1] = sl->map_col_to_list0_field[sl->mb_y & 1][1];

            dist_scale_factor   = sl->dist_scale_factor_field[sl->mb_y & 1];

        }

        ref_offset = (sl->ref_list[1][0].parent->mbaff << 4) & (mb_type_col[0] >> 3);



        if (IS_INTERLACED(*mb_type) != IS_INTERLACED(mb_type_col[0])) {

            int y_shift = 2 * !IS_INTERLACED(*mb_type);

            assert(h->ps.sps->direct_8x8_inference_flag);



            for (i8 = 0; i8 < 4; i8++) {

                const int x8 = i8 & 1;

                const int y8 = i8 >> 1;

                int ref0, scale;

                const int16_t (*l1mv)[2] = l1mv0;



                if (is_b8x8 && !IS_DIRECT(sl->sub_mb_type[i8]))

                    continue;

                sl->sub_mb_type[i8] = sub_mb_type;



                fill_rectangle(&sl->ref_cache[1][scan8[i8 * 4]], 2, 2, 8, 0, 1);

                if (IS_INTRA(mb_type_col[y8])) {

                    fill_rectangle(&sl->ref_cache[0][scan8[i8 * 4]], 2, 2, 8, 0, 1);

                    fill_rectangle(&sl->mv_cache[0][scan8[i8 * 4]], 2, 2, 8, 0, 4);

                    fill_rectangle(&sl->mv_cache[1][scan8[i8 * 4]], 2, 2, 8, 0, 4);

                    continue;

                }



                ref0 = l1ref0[x8 + y8 * b8_stride];

                if (ref0 >= 0)

                    ref0 = map_col_to_list0[0][ref0 + ref_offset];

                else {

                    ref0 = map_col_to_list0[1][l1ref1[x8 + y8 * b8_stride] +

                                               ref_offset];

                    l1mv = l1mv1;

                }

                scale = dist_scale_factor[ref0];

                fill_rectangle(&sl->ref_cache[0][scan8[i8 * 4]], 2, 2, 8,

                               ref0, 1);



                {

                    const int16_t *mv_col = l1mv[x8 * 3 + y8 * b4_stride];

                    int my_col            = (mv_col[1] << y_shift) / 2;

                    int mx                = (scale * mv_col[0] + 128) >> 8;

                    int my                = (scale * my_col    + 128) >> 8;

                    fill_rectangle(&sl->mv_cache[0][scan8[i8 * 4]], 2, 2, 8,

                                   pack16to32(mx, my), 4);

                    fill_rectangle(&sl->mv_cache[1][scan8[i8 * 4]], 2, 2, 8,

                                   pack16to32(mx - mv_col[0], my - my_col), 4);

                }

            }

            return;

        }



        /* one-to-one mv scaling */



        if (IS_16X16(*mb_type)) {

            int ref, mv0, mv1;



            fill_rectangle(&sl->ref_cache[1][scan8[0]], 4, 4, 8, 0, 1);

            if (IS_INTRA(mb_type_col[0])) {

                ref = mv0 = mv1 = 0;

            } else {

                const int ref0 = l1ref0[0] >= 0 ? map_col_to_list0[0][l1ref0[0] + ref_offset]

                                                : map_col_to_list0[1][l1ref1[0] + ref_offset];

                const int scale = dist_scale_factor[ref0];

                const int16_t *mv_col = l1ref0[0] >= 0 ? l1mv0[0] : l1mv1[0];

                int mv_l0[2];

                mv_l0[0] = (scale * mv_col[0] + 128) >> 8;

                mv_l0[1] = (scale * mv_col[1] + 128) >> 8;

                ref      = ref0;

                mv0      = pack16to32(mv_l0[0], mv_l0[1]);

                mv1      = pack16to32(mv_l0[0] - mv_col[0], mv_l0[1] - mv_col[1]);

            }

            fill_rectangle(&sl->ref_cache[0][scan8[0]], 4, 4, 8, ref, 1);

            fill_rectangle(&sl->mv_cache[0][scan8[0]], 4, 4, 8, mv0, 4);

            fill_rectangle(&sl->mv_cache[1][scan8[0]], 4, 4, 8, mv1, 4);

        } else {

            for (i8 = 0; i8 < 4; i8++) {

                const int x8 = i8 & 1;

                const int y8 = i8 >> 1;

                int ref0, scale;

                const int16_t (*l1mv)[2] = l1mv0;



                if (is_b8x8 && !IS_DIRECT(sl->sub_mb_type[i8]))

                    continue;

                sl->sub_mb_type[i8] = sub_mb_type;

                fill_rectangle(&sl->ref_cache[1][scan8[i8 * 4]], 2, 2, 8, 0, 1);

                if (IS_INTRA(mb_type_col[0])) {

                    fill_rectangle(&sl->ref_cache[0][scan8[i8 * 4]], 2, 2, 8, 0, 1);

                    fill_rectangle(&sl->mv_cache[0][scan8[i8 * 4]], 2, 2, 8, 0, 4);

                    fill_rectangle(&sl->mv_cache[1][scan8[i8 * 4]], 2, 2, 8, 0, 4);

                    continue;

                }



                assert(b8_stride == 2);

                ref0 = l1ref0[i8];

                if (ref0 >= 0)

                    ref0 = map_col_to_list0[0][ref0 + ref_offset];

                else {

                    ref0 = map_col_to_list0[1][l1ref1[i8] + ref_offset];

                    l1mv = l1mv1;

                }

                scale = dist_scale_factor[ref0];



                fill_rectangle(&sl->ref_cache[0][scan8[i8 * 4]], 2, 2, 8,

                               ref0, 1);

                if (IS_SUB_8X8(sub_mb_type)) {

                    const int16_t *mv_col = l1mv[x8 * 3 + y8 * 3 * b4_stride];

                    int mx                = (scale * mv_col[0] + 128) >> 8;

                    int my                = (scale * mv_col[1] + 128) >> 8;

                    fill_rectangle(&sl->mv_cache[0][scan8[i8 * 4]], 2, 2, 8,

                                   pack16to32(mx, my), 4);

                    fill_rectangle(&sl->mv_cache[1][scan8[i8 * 4]], 2, 2, 8,

                                   pack16to32(mx - mv_col[0], my - mv_col[1]), 4);

                } else {

                    for (i4 = 0; i4 < 4; i4++) {

                        const int16_t *mv_col = l1mv[x8 * 2 + (i4 & 1) +

                                                     (y8 * 2 + (i4 >> 1)) * b4_stride];

                        int16_t *mv_l0 = sl->mv_cache[0][scan8[i8 * 4 + i4]];

                        mv_l0[0] = (scale * mv_col[0] + 128) >> 8;

                        mv_l0[1] = (scale * mv_col[1] + 128) >> 8;

                        AV_WN32A(sl->mv_cache[1][scan8[i8 * 4 + i4]],

                                 pack16to32(mv_l0[0] - mv_col[0],

                                            mv_l0[1] - mv_col[1]));

                    }

                }

            }

        }

    }

}

static void ff_mpeg4_init_direct_mv(MpegEncContext *s){

    //FIXME table is stored in MpegEncContext for thread-safety,

    // but a static array would be faster

    static const int tab_size = sizeof(s->direct_scale_mv[0])/sizeof(int16_t);

    static const int tab_bias = (tab_size/2);

    int i;

    for(i=0; i<tab_size; i++){

        s->direct_scale_mv[0][i] = (i-tab_bias)*s->pb_time/s->pp_time;

        s->direct_scale_mv[1][i] = (i-tab_bias)*(s->pb_time-s->pp_time)/s->pp_time;

    }

}

static void video_image_display(VideoState *is)

{

    Frame *vp;

    Frame *sp;

    AVPicture pict;

    SDL_Rect rect;

    int i;



    vp = frame_queue_peek(&is->pictq);

    if (vp->bmp) {

        if (is->subtitle_st) {

            if (frame_queue_nb_remaining(&is->subpq) > 0) {

                sp = frame_queue_peek(&is->subpq);



                if (vp->pts >= sp->pts + ((float) sp->sub.start_display_time / 1000)) {

                    SDL_LockYUVOverlay (vp->bmp);



                    pict.data[0] = vp->bmp->pixels[0];

                    pict.data[1] = vp->bmp->pixels[2];

                    pict.data[2] = vp->bmp->pixels[1];



                    pict.linesize[0] = vp->bmp->pitches[0];

                    pict.linesize[1] = vp->bmp->pitches[2];

                    pict.linesize[2] = vp->bmp->pitches[1];



                    for (i = 0; i < sp->sub.num_rects; i++)

                        blend_subrect(&pict, sp->sub.rects[i],

                                      vp->bmp->w, vp->bmp->h);



                    SDL_UnlockYUVOverlay (vp->bmp);

                }

            }

        }



        calculate_display_rect(&rect, is->xleft, is->ytop, is->width, is->height, vp->width, vp->height, vp->sar);



        SDL_DisplayYUVOverlay(vp->bmp, &rect);



        if (rect.x != is->last_display_rect.x || rect.y != is->last_display_rect.y || rect.w != is->last_display_rect.w || rect.h != is->last_display_rect.h || is->force_refresh) {

            int bgcolor = SDL_MapRGB(screen->format, 0x00, 0x00, 0x00);

            fill_border(is->xleft, is->ytop, is->width, is->height, rect.x, rect.y, rect.w, rect.h, bgcolor, 1);

            is->last_display_rect = rect;

        }

    }

}

static int pad_count(const AVFilterPad *pads)

{

    int count;



    if (!pads)

        return 0;



    for(count = 0; pads->name; count ++) pads ++;

    return count;

}

rtsp_read_reply (AVFormatContext *s, RTSPMessageHeader *reply,

                 unsigned char **content_ptr, int return_on_interleaved_data)

{

    RTSPState *rt = s->priv_data;

    char buf[4096], buf1[1024], *q;

    unsigned char ch;

    const char *p;

    int ret, content_length, line_count = 0;

    unsigned char *content = NULL;



    memset(reply, 0, sizeof(*reply));



    /* parse reply (XXX: use buffers) */

    rt->last_reply[0] = '\0';

    for(;;) {

        q = buf;

        for(;;) {

            ret = url_read_complete(rt->rtsp_hd, &ch, 1);

#ifdef DEBUG_RTP_TCP

            dprintf(s, "ret=%d c=%02x [%c]\n", ret, ch, ch);

#endif

            if (ret != 1)

                return -1;

            if (ch == '\n')

                break;

            if (ch == '$') {

                /* XXX: only parse it if first char on line ? */

                if (return_on_interleaved_data) {

                    return 1;

                } else

                rtsp_skip_packet(s);

            } else if (ch != '\r') {

                if ((q - buf) < sizeof(buf) - 1)

                    *q++ = ch;

            }

        }

        *q = '\0';



        dprintf(s, "line='%s'\n", buf);



        /* test if last line */

        if (buf[0] == '\0')

            break;

        p = buf;

        if (line_count == 0) {

            /* get reply code */

            get_word(buf1, sizeof(buf1), &p);

            get_word(buf1, sizeof(buf1), &p);

            reply->status_code = atoi(buf1);

        } else {

            rtsp_parse_line(reply, p);

            av_strlcat(rt->last_reply, p,    sizeof(rt->last_reply));

            av_strlcat(rt->last_reply, "\n", sizeof(rt->last_reply));

        }

        line_count++;

    }



    if (rt->session_id[0] == '\0' && reply->session_id[0] != '\0')

        av_strlcpy(rt->session_id, reply->session_id, sizeof(rt->session_id));



    content_length = reply->content_length;

    if (content_length > 0) {

        /* leave some room for a trailing '\0' (useful for simple parsing) */

        content = av_malloc(content_length + 1);

        (void)url_read_complete(rt->rtsp_hd, content, content_length);

        content[content_length] = '\0';

    }

    if (content_ptr)

        *content_ptr = content;

    else

        av_free(content);



    /* EOS */

    if (reply->notice == 2101 /* End-of-Stream Reached */      ||

        reply->notice == 2104 /* Start-of-Stream Reached */    ||

        reply->notice == 2306 /* Continuous Feed Terminated */)

        rt->state = RTSP_STATE_IDLE;

    else if (reply->notice >= 4400 && reply->notice < 5500)

        return AVERROR(EIO); /* data or server error */

    else if (reply->notice == 2401 /* Ticket Expired */ ||

             (reply->notice >= 5500 && reply->notice < 5600) /* end of term */ )

        return AVERROR(EPERM);



    return 0;

}

int av_fifo_generic_write(AVFifoBuffer *f, void *src, int size, int (*func)(void*, void*, int))

{

    int total = size;

    do {

        int len = FFMIN(f->end - f->wptr, size);

        if (func) {

            if (func(src, f->wptr, len) <= 0)

                break;

        } else {

            memcpy(f->wptr, src, len);

            src = (uint8_t*)src + len;

        }

// Write memory barrier needed for SMP here in theory

        f->wptr += len;

        if (f->wptr >= f->end)

            f->wptr = f->buffer;

        f->wndx += len;

        size -= len;

    } while (size > 0);

    return total - size;

}

int av_image_get_linesize(enum AVPixelFormat pix_fmt, int width, int plane)

{

    const AVPixFmtDescriptor *desc = av_pix_fmt_desc_get(pix_fmt);

    int max_step     [4];       /* max pixel step for each plane */

    int max_step_comp[4];       /* the component for each plane which has the max pixel step */



    if ((unsigned)pix_fmt >= AV_PIX_FMT_NB || desc->flags & AV_PIX_FMT_FLAG_HWACCEL)

        return AVERROR(EINVAL);



    av_image_fill_max_pixsteps(max_step, max_step_comp, desc);

    return image_get_linesize(width, plane, max_step[plane], max_step_comp[plane], desc);

}

static int encode_slice(AVCodecContext *c, void *arg)

{

    FFV1Context *fs  = *(void **)arg;

    FFV1Context *f   = fs->avctx->priv_data;

    int width        = fs->slice_width;

    int height       = fs->slice_height;

    int x            = fs->slice_x;

    int y            = fs->slice_y;

    const AVFrame *const p = f->frame;

    const int ps     = (av_pix_fmt_desc_get(c->pix_fmt)->flags & AV_PIX_FMT_FLAG_PLANAR)

                       ? (f->bits_per_raw_sample > 8) + 1

                       : 4;



    if (f->key_frame)

        ffv1_clear_slice_state(f, fs);

    if (f->version > 2) {

        encode_slice_header(f, fs);

    }

    if (!fs->ac) {

        if (f->version > 2)

            put_rac(&fs->c, (uint8_t[]) { 129 }, 0);

        fs->ac_byte_count = f->version > 2 || (!x && !y) ? ff_rac_terminate( &fs->c) : 0;

        init_put_bits(&fs->pb, fs->c.bytestream_start + fs->ac_byte_count,

                      fs->c.bytestream_end - fs->c.bytestream_start - fs->ac_byte_count);

    }



    if (f->colorspace == 0) {

        const int chroma_width  = -((-width) >> f->chroma_h_shift);

        const int chroma_height = -((-height) >> f->chroma_v_shift);

        const int cx            = x >> f->chroma_h_shift;

        const int cy            = y >> f->chroma_v_shift;



        encode_plane(fs, p->data[0] + ps * x + y * p->linesize[0],

                     width, height, p->linesize[0], 0);



        if (f->chroma_planes) {

            encode_plane(fs, p->data[1] + ps * cx + cy * p->linesize[1],

                         chroma_width, chroma_height, p->linesize[1], 1);

            encode_plane(fs, p->data[2] + ps * cx + cy * p->linesize[2],

                         chroma_width, chroma_height, p->linesize[2], 1);

        }

        if (fs->transparency)

            encode_plane(fs, p->data[3] + ps * x + y * p->linesize[3], width,

                         height, p->linesize[3], 2);

    } else {

        const uint8_t *planes[3] = { p->data[0] + ps * x + y * p->linesize[0],

                                     p->data[1] + ps * x + y * p->linesize[1],

                                     p->data[2] + ps * x + y * p->linesize[2] };

        encode_rgb_frame(fs, planes, width, height, p->linesize);

    }

    emms_c();



    return 0;

}

static inline int coupling_strategy(AC3DecodeContext *s, int blk,

                                    uint8_t *bit_alloc_stages)

{

    GetBitContext *bc = &s->gbc;

    int fbw_channels = s->fbw_channels;

    int channel_mode = s->channel_mode;

    int ch;



    memset(bit_alloc_stages, 3, AC3_MAX_CHANNELS);

    if (!s->eac3)

        s->cpl_in_use[blk] = get_bits1(bc);

    if (s->cpl_in_use[blk]) {

        /* coupling in use */

        int cpl_start_subband, cpl_end_subband;



        if (channel_mode < AC3_CHMODE_STEREO) {

            av_log(s->avctx, AV_LOG_ERROR, "coupling not allowed in mono or dual-mono\n");

            return AVERROR_INVALIDDATA;

        }



        /* check for enhanced coupling */

        if (s->eac3 && get_bits1(bc)) {

            /* TODO: parse enhanced coupling strategy info */

            avpriv_request_sample(s->avctx, "Enhanced coupling");

            return AVERROR_PATCHWELCOME;

        }



        /* determine which channels are coupled */

        if (s->eac3 && s->channel_mode == AC3_CHMODE_STEREO) {

            s->channel_in_cpl[1] = 1;

            s->channel_in_cpl[2] = 1;

        } else {

            for (ch = 1; ch <= fbw_channels; ch++)

                s->channel_in_cpl[ch] = get_bits1(bc);

        }



        /* phase flags in use */

        if (channel_mode == AC3_CHMODE_STEREO)

            s->phase_flags_in_use = get_bits1(bc);



        /* coupling frequency range */

        cpl_start_subband = get_bits(bc, 4);

        cpl_end_subband = s->spx_in_use ? (s->spx_src_start_freq - 37) / 12 :

                                          get_bits(bc, 4) + 3;

        if (cpl_start_subband >= cpl_end_subband) {

            av_log(s->avctx, AV_LOG_ERROR, "invalid coupling range (%d >= %d)\n",

                   cpl_start_subband, cpl_end_subband);

            return AVERROR_INVALIDDATA;

        }

        s->start_freq[CPL_CH] = cpl_start_subband * 12 + 37;

        s->end_freq[CPL_CH]   = cpl_end_subband   * 12 + 37;



        decode_band_structure(bc, blk, s->eac3, 0, cpl_start_subband,

                              cpl_end_subband,

                              ff_eac3_default_cpl_band_struct,

                              &s->num_cpl_bands, s->cpl_band_sizes);

    } else {

        /* coupling not in use */

        for (ch = 1; ch <= fbw_channels; ch++) {

            s->channel_in_cpl[ch] = 0;

            s->first_cpl_coords[ch] = 1;

        }

        s->first_cpl_leak = s->eac3;

        s->phase_flags_in_use = 0;

    }



    return 0;

}

static int tiff_decode_tag(TiffContext *s, const uint8_t *start, const uint8_t *buf, const uint8_t *end_buf)

{

    int tag, type, count, off, value = 0;

    int i, j;

    uint32_t *pal;

    const uint8_t *rp, *gp, *bp;



    tag = tget_short(&buf, s->le);

    type = tget_short(&buf, s->le);

    count = tget_long(&buf, s->le);

    off = tget_long(&buf, s->le);



    if(count == 1){

        switch(type){

        case TIFF_BYTE:

        case TIFF_SHORT:

            buf -= 4;

            value = tget(&buf, type, s->le);

            buf = NULL;

            break;

        case TIFF_LONG:

            value = off;

            buf = NULL;

            break;

        case TIFF_STRING:

            if(count <= 4){

                buf -= 4;

                break;

            }

        default:

            value = -1;

            buf = start + off;

        }

    }else if(type_sizes[type] * count <= 4){

        buf -= 4;

    }else{

        buf = start + off;

    }



    if(buf && (buf < start || buf > end_buf)){

        av_log(s->avctx, AV_LOG_ERROR, "Tag referencing position outside the image\n");

        return -1;

    }



    switch(tag){

    case TIFF_WIDTH:

        s->width = value;

        break;

    case TIFF_HEIGHT:

        s->height = value;

        break;

    case TIFF_BPP:

        if(count == 1) s->bpp = value;

        else{

            switch(type){

            case TIFF_BYTE:

                s->bpp = (off & 0xFF) + ((off >> 8) & 0xFF) + ((off >> 16) & 0xFF) + ((off >> 24) & 0xFF);

                break;

            case TIFF_SHORT:

            case TIFF_LONG:

                s->bpp = 0;

                for(i = 0; i < count; i++) s->bpp += tget(&buf, type, s->le);

                break;

            default:

                s->bpp = -1;

            }

        }

        switch(s->bpp){

        case 1:

            s->avctx->pix_fmt = PIX_FMT_MONOBLACK;

            break;

        case 8:

            s->avctx->pix_fmt = PIX_FMT_PAL8;

            break;

        case 24:

            s->avctx->pix_fmt = PIX_FMT_RGB24;

            break;

        case 16:

            if(count == 1){

                s->avctx->pix_fmt = PIX_FMT_GRAY16BE;

            }else{

                av_log(s->avctx, AV_LOG_ERROR, "This format is not supported (bpp=%i)\n", s->bpp);

                return -1;

            }

            break;

        case 32:

            if(count == 4){

                s->avctx->pix_fmt = PIX_FMT_RGBA;

            }else{

                av_log(s->avctx, AV_LOG_ERROR, "This format is not supported (bpp=%d, %d components)\n", s->bpp, count);

                return -1;

            }

            break;

        default:

            av_log(s->avctx, AV_LOG_ERROR, "This format is not supported (bpp=%d, %d components)\n", s->bpp, count);

            return -1;

        }

        if(s->width != s->avctx->width || s->height != s->avctx->height){

            if(avcodec_check_dimensions(s->avctx, s->width, s->height))

                return -1;

            avcodec_set_dimensions(s->avctx, s->width, s->height);

        }

        if(s->picture.data[0])

            s->avctx->release_buffer(s->avctx, &s->picture);

        if(s->avctx->get_buffer(s->avctx, &s->picture) < 0){

            av_log(s->avctx, AV_LOG_ERROR, "get_buffer() failed\n");

            return -1;

        }

        if(s->bpp == 8){

            /* make default grayscale pal */

            pal = (uint32_t *) s->picture.data[1];

            for(i = 0; i < 256; i++)

                pal[i] = i * 0x010101;

        }

        break;

    case TIFF_COMPR:

        s->compr = value;

        s->predictor = 0;

        switch(s->compr){

        case TIFF_RAW:

        case TIFF_PACKBITS:

        case TIFF_LZW:

        case TIFF_CCITT_RLE:

            break;

        case TIFF_G3:

        case TIFF_G4:

            s->fax_opts = 0;

            break;

        case TIFF_DEFLATE:

        case TIFF_ADOBE_DEFLATE:

#if CONFIG_ZLIB

            break;

#else

            av_log(s->avctx, AV_LOG_ERROR, "Deflate: ZLib not compiled in\n");

            return -1;

#endif

        case TIFF_JPEG:

        case TIFF_NEWJPEG:

            av_log(s->avctx, AV_LOG_ERROR, "JPEG compression is not supported\n");

            return -1;

        default:

            av_log(s->avctx, AV_LOG_ERROR, "Unknown compression method %i\n", s->compr);

            return -1;

        }

        break;

    case TIFF_ROWSPERSTRIP:

        if(type == TIFF_LONG && value == -1)

            value = s->avctx->height;

        if(value < 1){

            av_log(s->avctx, AV_LOG_ERROR, "Incorrect value of rows per strip\n");

            return -1;

        }

        s->rps = value;

        break;

    case TIFF_STRIP_OFFS:

        if(count == 1){

            s->stripdata = NULL;

            s->stripoff = value;

        }else

            s->stripdata = start + off;

        s->strips = count;

        if(s->strips == 1) s->rps = s->height;

        s->sot = type;

        if(s->stripdata > end_buf){

            av_log(s->avctx, AV_LOG_ERROR, "Tag referencing position outside the image\n");

            return -1;

        }

        break;

    case TIFF_STRIP_SIZE:

        if(count == 1){

            s->stripsizes = NULL;

            s->stripsize = value;

            s->strips = 1;

        }else{

            s->stripsizes = start + off;

        }

        s->strips = count;

        s->sstype = type;

        if(s->stripsizes > end_buf){

            av_log(s->avctx, AV_LOG_ERROR, "Tag referencing position outside the image\n");

            return -1;

        }

        break;

    case TIFF_PREDICTOR:

        s->predictor = value;

        break;

    case TIFF_INVERT:

        switch(value){

        case 0:

            s->invert = 1;

            break;

        case 1:

            s->invert = 0;

            break;

        case 2:

        case 3:

            break;

        default:

            av_log(s->avctx, AV_LOG_ERROR, "Color mode %d is not supported\n", value);

            return -1;

        }

        break;

    case TIFF_PAL:

        if(s->avctx->pix_fmt != PIX_FMT_PAL8){

            av_log(s->avctx, AV_LOG_ERROR, "Palette met but this is not palettized format\n");

            return -1;

        }

        pal = (uint32_t *) s->picture.data[1];

        off = type_sizes[type];

        rp = buf;

        gp = buf + count / 3 * off;

        bp = buf + count / 3 * off * 2;

        off = (type_sizes[type] - 1) << 3;

        for(i = 0; i < count / 3; i++){

            j = (tget(&rp, type, s->le) >> off) << 16;

            j |= (tget(&gp, type, s->le) >> off) << 8;

            j |= tget(&bp, type, s->le) >> off;

            pal[i] = j;

        }

        break;

    case TIFF_PLANAR:

        if(value == 2){

            av_log(s->avctx, AV_LOG_ERROR, "Planar format is not supported\n");

            return -1;

        }

        break;

    case TIFF_T4OPTIONS:

    case TIFF_T6OPTIONS:

        s->fax_opts = value;

        break;

    }

    return 0;

}

int attribute_align_arg avcodec_encode_audio(AVCodecContext *avctx,

                                             uint8_t *buf, int buf_size,

                                             const short *samples)

{

    AVPacket pkt;

    AVFrame *frame;

    int ret, samples_size, got_packet;



    av_init_packet(&pkt);

    pkt.data = buf;

    pkt.size = buf_size;



    if (samples) {

        frame = av_frame_alloc();





        if (avctx->frame_size) {

            frame->nb_samples = avctx->frame_size;

        } else {

            /* if frame_size is not set, the number of samples must be

             * calculated from the buffer size */

            int64_t nb_samples;

            if (!av_get_bits_per_sample(avctx->codec_id)) {

                av_log(avctx, AV_LOG_ERROR, "avcodec_encode_audio() does not "

                                            "support this codec\n");

                av_frame_free(&frame);

                return AVERROR(EINVAL);

            }

            nb_samples = (int64_t)buf_size * 8 /

                         (av_get_bits_per_sample(avctx->codec_id) *

                          avctx->channels);

            if (nb_samples >= INT_MAX) {

                av_frame_free(&frame);

                return AVERROR(EINVAL);

            }

            frame->nb_samples = nb_samples;

        }



        /* it is assumed that the samples buffer is large enough based on the

         * relevant parameters */

        samples_size = av_samples_get_buffer_size(NULL, avctx->channels,

                                                  frame->nb_samples,

                                                  avctx->sample_fmt, 1);

        if ((ret = avcodec_fill_audio_frame(frame, avctx->channels,

                                            avctx->sample_fmt,

                                            (const uint8_t *)samples,

                                            samples_size, 1)) < 0) {

            av_frame_free(&frame);

            return ret;

        }



        /* fabricate frame pts from sample count.

         * this is needed because the avcodec_encode_audio() API does not have

         * a way for the user to provide pts */

        if (avctx->sample_rate && avctx->time_base.num)

            frame->pts = ff_samples_to_time_base(avctx,

                                                 avctx->internal->sample_count);

        else

            frame->pts = AV_NOPTS_VALUE;

        avctx->internal->sample_count += frame->nb_samples;

    } else {

        frame = NULL;

    }



    got_packet = 0;

    ret = avcodec_encode_audio2(avctx, &pkt, frame, &got_packet);

    if (!ret && got_packet && avctx->coded_frame) {

        avctx->coded_frame->pts       = pkt.pts;

        avctx->coded_frame->key_frame = !!(pkt.flags & AV_PKT_FLAG_KEY);

    }

    /* free any side data since we cannot return it */

    av_packet_free_side_data(&pkt);



    if (frame && frame->extended_data != frame->data)

        av_freep(&frame->extended_data);



    av_frame_free(&frame);

    return ret ? ret : pkt.size;

}

static inline void RENAME(rgb32tobgr15)(const uint8_t *src, uint8_t *dst, int src_size)

{

    const uint8_t *s = src;

    const uint8_t *end;

    const uint8_t *mm_end;

    uint16_t *d = (uint16_t *)dst;

    end = s + src_size;

    __asm__ volatile(PREFETCH"    %0"::"m"(*src):"memory");

    __asm__ volatile(

        "movq          %0, %%mm7    \n\t"

        "movq          %1, %%mm6    \n\t"

        ::"m"(red_15mask),"m"(green_15mask));

    mm_end = end - 15;

    while (s < mm_end) {

        __asm__ volatile(

            PREFETCH"    32%1           \n\t"

            "movd          %1, %%mm0    \n\t"

            "movd         4%1, %%mm3    \n\t"

            "punpckldq    8%1, %%mm0    \n\t"

            "punpckldq   12%1, %%mm3    \n\t"

            "movq       %%mm0, %%mm1    \n\t"

            "movq       %%mm0, %%mm2    \n\t"

            "movq       %%mm3, %%mm4    \n\t"

            "movq       %%mm3, %%mm5    \n\t"

            "psllq         $7, %%mm0    \n\t"

            "psllq         $7, %%mm3    \n\t"

            "pand       %%mm7, %%mm0    \n\t"

            "pand       %%mm7, %%mm3    \n\t"

            "psrlq         $6, %%mm1    \n\t"

            "psrlq         $6, %%mm4    \n\t"

            "pand       %%mm6, %%mm1    \n\t"

            "pand       %%mm6, %%mm4    \n\t"

            "psrlq        $19, %%mm2    \n\t"

            "psrlq        $19, %%mm5    \n\t"

            "pand          %2, %%mm2    \n\t"

            "pand          %2, %%mm5    \n\t"

            "por        %%mm1, %%mm0    \n\t"

            "por        %%mm4, %%mm3    \n\t"

            "por        %%mm2, %%mm0    \n\t"

            "por        %%mm5, %%mm3    \n\t"

            "psllq        $16, %%mm3    \n\t"

            "por        %%mm3, %%mm0    \n\t"

            MOVNTQ"     %%mm0, %0       \n\t"

            :"=m"(*d):"m"(*s),"m"(blue_15mask):"memory");

        d += 4;

        s += 16;

    }

    __asm__ volatile(SFENCE:::"memory");

    __asm__ volatile(EMMS:::"memory");

    while (s < end) {

        register int rgb = *(const uint32_t*)s; s += 4;

        *d++ = ((rgb&0xF8)<<7) + ((rgb&0xF800)>>6) + ((rgb&0xF80000)>>19);

    }

}

static int mov_read_custom(MOVContext *c, AVIOContext *pb, MOVAtom atom)

{

    int64_t end = avio_tell(pb) + atom.size;

    uint8_t *key = NULL, *val = NULL, *mean = NULL;

    int i;

    AVStream *st;

    MOVStreamContext *sc;



    if (c->fc->nb_streams < 1)

        return 0;

    st = c->fc->streams[c->fc->nb_streams-1];

    sc = st->priv_data;



    for (i = 0; i < 3; i++) {

        uint8_t **p;

        uint32_t len, tag;

        int ret;



        if (end - avio_tell(pb) <= 12)

            break;



        len = avio_rb32(pb);

        tag = avio_rl32(pb);

        avio_skip(pb, 4); // flags



        if (len < 12 || len - 12 > end - avio_tell(pb))

            break;

        len -= 12;



        if (tag == MKTAG('m', 'e', 'a', 'n'))

            p = &mean;

        else if (tag == MKTAG('n', 'a', 'm', 'e'))

            p = &key;

        else if (tag == MKTAG('d', 'a', 't', 'a') && len > 4) {

            avio_skip(pb, 4);

            len -= 4;

            p = &val;

        } else

            break;



        *p = av_malloc(len + 1);

        if (!*p)

            break;

        ret = ffio_read_size(pb, *p, len);

        if (ret < 0) {

            av_freep(p);

            return ret;

        }

        (*p)[len] = 0;

    }



    if (mean && key && val) {

        if (strcmp(key, "iTunSMPB") == 0) {

            int priming, remainder, samples;

            if(sscanf(val, "%*X %X %X %X", &priming, &remainder, &samples) == 3){

                if(priming>0 && priming<16384)

                    sc->start_pad = priming;

            }

        }

        if (strcmp(key, "cdec") != 0) {

            av_dict_set(&c->fc->metadata, key, val,

                        AV_DICT_DONT_STRDUP_KEY | AV_DICT_DONT_STRDUP_VAL);

            key = val = NULL;

        }

    } else {

        av_log(c->fc, AV_LOG_VERBOSE,

               "Unhandled or malformed custom metadata of size %"PRId64"\n", atom.size);

    }



    avio_seek(pb, end, SEEK_SET);

    av_freep(&key);

    av_freep(&val);

    av_freep(&mean);

    return 0;

}

static AVBufferRef *dxva2_pool_alloc(void *opaque, int size)

{

    AVHWFramesContext      *ctx = (AVHWFramesContext*)opaque;

    DXVA2FramesContext       *s = ctx->internal->priv;

    AVDXVA2FramesContext *hwctx = ctx->hwctx;



    if (s->nb_surfaces_used < hwctx->nb_surfaces) {

        s->nb_surfaces_used++;

        return av_buffer_create((uint8_t*)s->surfaces_internal[s->nb_surfaces_used - 1],

                                sizeof(*hwctx->surfaces), NULL, 0, 0);

    }



    return NULL;

}

void put_string(PutBitContext * pbc, char *s)

{

    while(*s){

        put_bits(pbc, 8, *s);

        s++;

    }

    put_bits(pbc, 8, 0);

}

static void mp_decode_frame_helper(MotionPixelsContext *mp, GetBitContext *gb)
{
    YuvPixel p;
    int y, y0;
    for (y = 0; y < mp->avctx->height; ++y) {
        if (mp->changes_map[y * mp->avctx->width] != 0) {
            memset(mp->gradient_scale, 1, sizeof(mp->gradient_scale));
            p = mp_get_yuv_from_rgb(mp, 0, y);
        } else {
            p.y += mp_gradient(mp, 0, mp_get_vlc(mp, gb));
            p.y = av_clip(p.y, 0, 31);
            if ((y & 3) == 0) {
                p.v += mp_gradient(mp, 1, mp_get_vlc(mp, gb));
                p.v = av_clip(p.v, -32, 31);
                p.u += mp_gradient(mp, 2, mp_get_vlc(mp, gb));
                p.u = av_clip(p.u, -32, 31);
            }
            mp->vpt[y] = p;
            mp_set_rgb_from_yuv(mp, 0, y, &p);
        }
    }
    for (y0 = 0; y0 < 2; ++y0)
        for (y = y0; y < mp->avctx->height; y += 2)
            mp_decode_line(mp, gb, y);
}

static int find_start_code(const uint8_t **pbuf_ptr, const uint8_t *buf_end)

{

    const uint8_t *buf_ptr= *pbuf_ptr;



    buf_ptr++; //gurantees that -1 is within the array

    buf_end -= 2; // gurantees that +2 is within the array



    while (buf_ptr < buf_end) {

        if(*buf_ptr==0){

            while(buf_ptr < buf_end && buf_ptr[1]==0)

                buf_ptr++;



            if(buf_ptr[-1] == 0 && buf_ptr[1] == 1){

                *pbuf_ptr = buf_ptr+3;

                return buf_ptr[2] + 0x100;

            }

        }

        buf_ptr += 2;

    }

    buf_end += 2; //undo the hack above



    *pbuf_ptr = buf_end;

    return -1;

}

av_cold int ff_nvenc_encode_init(AVCodecContext *avctx)

{

    int ret;



    if ((ret = nvenc_load_libraries(avctx)) < 0)

        return ret;



    if ((ret = nvenc_setup_device(avctx)) < 0)

        return ret;



    if ((ret = nvenc_setup_encoder(avctx)) < 0)

        return ret;



    if ((ret = nvenc_setup_surfaces(avctx)) < 0)

        return ret;



    if (avctx->flags & CODEC_FLAG_GLOBAL_HEADER) {

        if ((ret = nvenc_setup_extradata(avctx)) < 0)

            return ret;

    }



    avctx->coded_frame = av_frame_alloc();

    if (!avctx->coded_frame)

        return AVERROR(ENOMEM);



    return 0;

}

int avcodec_decode_audio2(AVCodecContext *avctx, int16_t *samples,

                         int *frame_size_ptr,

                         uint8_t *buf, int buf_size)

{

    int ret;



    //FIXME remove the check below _after_ ensuring that all audio check that the available space is enough

    if(*frame_size_ptr < AVCODEC_MAX_AUDIO_FRAME_SIZE){

        av_log(avctx, AV_LOG_ERROR, "buffer smaller than AVCODEC_MAX_AUDIO_FRAME_SIZE\n");

        return -1;

    }

    if(*frame_size_ptr < FF_MIN_BUFFER_SIZE ||

       *frame_size_ptr < avctx->channels * avctx->frame_size * sizeof(int16_t) ||

       *frame_size_ptr < buf_size){

        av_log(avctx, AV_LOG_ERROR, "buffer %d too small\n", *frame_size_ptr);

        return -1;

    }

    if((avctx->codec->capabilities & CODEC_CAP_DELAY) || buf_size){

        ret = avctx->codec->decode(avctx, samples, frame_size_ptr,

                                buf, buf_size);

        avctx->frame_number++;

    }else{

        ret= 0;

        *frame_size_ptr=0;

    }

    return ret;

}

static int64_t ffm_read_write_index(int fd)

{

    uint8_t buf[8];



    lseek(fd, 8, SEEK_SET);

    if (read(fd, buf, 8) != 8)

        return AVERROR(EIO);

    return AV_RB64(buf);

}

static inline void dv_decode_video_segment(DVVideoContext *s, 

                                           uint8_t *buf_ptr1, 

                                           const uint16_t *mb_pos_ptr)

{

    int quant, dc, dct_mode, class1, j;

    int mb_index, mb_x, mb_y, v, last_index;

    DCTELEM *block, *block1;

    int c_offset;

    uint8_t *y_ptr;

    void (*idct_put)(uint8_t *dest, int line_size, DCTELEM *block);

    uint8_t *buf_ptr;

    PutBitContext pb, vs_pb;

    GetBitContext gb;

    BlockInfo mb_data[5 * 6], *mb, *mb1;

    DCTELEM sblock[5*6][64] __align8;

    uint8_t mb_bit_buffer[80 + 4]; /* allow some slack */

    uint8_t vs_bit_buffer[5 * 80 + 4]; /* allow some slack */



    memset(sblock, 0, sizeof(sblock));



    /* pass 1 : read DC and AC coefficients in blocks */

    buf_ptr = buf_ptr1;

    block1 = &sblock[0][0];

    mb1 = mb_data;

    init_put_bits(&vs_pb, vs_bit_buffer, 5 * 80);

    for(mb_index = 0; mb_index < 5; mb_index++, mb1 += 6, block1 += 6 * 64) {

        /* skip header */

        quant = buf_ptr[3] & 0x0f;

        buf_ptr += 4;

        init_put_bits(&pb, mb_bit_buffer, 80);

        mb = mb1;

        block = block1;

        for(j = 0;j < 6; j++) {

            last_index = block_sizes[j];

	    init_get_bits(&gb, buf_ptr, last_index);



            /* get the dc */

            dc = get_sbits(&gb, 9);

            dct_mode = get_bits1(&gb);

            mb->dct_mode = dct_mode;

            mb->scan_table = s->dv_zigzag[dct_mode];

            class1 = get_bits(&gb, 2);

            mb->shift_table = s->dv_idct_shift[class1 == 3][dct_mode]

                [quant + dv_quant_offset[class1]];

            dc = dc << 2;

            /* convert to unsigned because 128 is not added in the

               standard IDCT */

            dc += 1024;

            block[0] = dc;

            buf_ptr += last_index >> 3;

            mb->pos = 0;

            mb->partial_bit_count = 0;



#ifdef VLC_DEBUG

            printf("MB block: %d, %d ", mb_index, j);

#endif

            dv_decode_ac(&gb, mb, block);



            /* write the remaining bits  in a new buffer only if the

               block is finished */

            if (mb->pos >= 64)

                bit_copy(&pb, &gb);



            block += 64;

            mb++;

        }



        /* pass 2 : we can do it just after */

#ifdef VLC_DEBUG

        printf("***pass 2 size=%d MB#=%d\n", put_bits_count(&pb), mb_index);

#endif

        block = block1;

        mb = mb1;

        init_get_bits(&gb, mb_bit_buffer, put_bits_count(&pb));

	flush_put_bits(&pb);

        for(j = 0;j < 6; j++, block += 64, mb++) {

            if (mb->pos < 64 && get_bits_left(&gb) > 0) {

                dv_decode_ac(&gb, mb, block);

                /* if still not finished, no need to parse other blocks */

                if (mb->pos < 64)

                    break;

            }

        }

        /* all blocks are finished, so the extra bytes can be used at

           the video segment level */

        if (j >= 6)

	    bit_copy(&vs_pb, &gb);

    }



    /* we need a pass other the whole video segment */

#ifdef VLC_DEBUG

    printf("***pass 3 size=%d\n", put_bits_count(&vs_pb));

#endif

    block = &sblock[0][0];

    mb = mb_data;

    init_get_bits(&gb, vs_bit_buffer, put_bits_count(&vs_pb));

    flush_put_bits(&vs_pb);

    for(mb_index = 0; mb_index < 5; mb_index++) {

        for(j = 0;j < 6; j++) {

            if (mb->pos < 64) {

#ifdef VLC_DEBUG

                printf("start %d:%d\n", mb_index, j);

#endif

                dv_decode_ac(&gb, mb, block);

            }

	    if (mb->pos >= 64 && mb->pos < 127)

		av_log(NULL, AV_LOG_ERROR, "AC EOB marker is absent pos=%d\n", mb->pos);

            block += 64;

            mb++;

        }

    }



    /* compute idct and place blocks */

    block = &sblock[0][0];

    mb = mb_data;

    for(mb_index = 0; mb_index < 5; mb_index++) {

        v = *mb_pos_ptr++;

        mb_x = v & 0xff;

        mb_y = v >> 8;

        y_ptr = s->picture.data[0] + (mb_y * s->picture.linesize[0] * 8) + (mb_x * 8);

        if (s->sys->pix_fmt == PIX_FMT_YUV411P)

            c_offset = (mb_y * s->picture.linesize[1] * 8) + ((mb_x >> 2) * 8);

        else

            c_offset = ((mb_y >> 1) * s->picture.linesize[1] * 8) + ((mb_x >> 1) * 8);

        for(j = 0;j < 6; j++) {

            idct_put = s->idct_put[mb->dct_mode];

            if (j < 4) {

                if (s->sys->pix_fmt == PIX_FMT_YUV411P && mb_x < (704 / 8)) {

                    /* NOTE: at end of line, the macroblock is handled as 420 */

                    idct_put(y_ptr + (j * 8), s->picture.linesize[0], block);

                } else {

                    idct_put(y_ptr + ((j & 1) * 8) + ((j >> 1) * 8 * s->picture.linesize[0]),

                             s->picture.linesize[0], block);

                }

            } else {

                if (s->sys->pix_fmt == PIX_FMT_YUV411P && mb_x >= (704 / 8)) {

                    uint64_t aligned_pixels[64/8];

                    uint8_t *pixels= (uint8_t*)aligned_pixels;

		    uint8_t *c_ptr, *c_ptr1, *ptr;

                    int y, linesize;

                    /* NOTE: at end of line, the macroblock is handled as 420 */

                    idct_put(pixels, 8, block);

                    linesize = s->picture.linesize[6 - j];

                    c_ptr = s->picture.data[6 - j] + c_offset;

                    ptr = pixels;

                    for(y = 0;y < 8; y++) {

                        /* convert to 411P */

                        c_ptr1 = c_ptr + 8*linesize;

                        c_ptr[0]= ptr[0]; c_ptr1[0]= ptr[4];

                        c_ptr[1]= ptr[1]; c_ptr1[1]= ptr[5];

                        c_ptr[2]= ptr[2]; c_ptr1[2]= ptr[6];

                        c_ptr[3]= ptr[3]; c_ptr1[3]= ptr[7];

                        c_ptr += linesize;

                        ptr += 8;

                    }

                } else {

                    /* don't ask me why they inverted Cb and Cr ! */

                    idct_put(s->picture.data[6 - j] + c_offset, 

                             s->picture.linesize[6 - j], block);

                }

            }

            block += 64;

            mb++;

        }

    }

}

static inline int decode_bytes(const uint8_t* inbuffer, uint8_t* out, int bytes){

    int i, off;

    uint32_t c;

    const uint32_t* buf;

    uint32_t* obuf = (uint32_t*) out;

    /* FIXME: 64 bit platforms would be able to do 64 bits at a time.

     * I'm too lazy though, should be something like

     * for(i=0 ; i<bitamount/64 ; i++)

     *     (int64_t)out[i] = 0x37c511f237c511f2^av_be2ne64(int64_t)in[i]);

     * Buffer alignment needs to be checked. */



    off = (intptr_t)inbuffer & 3;

    buf = (const uint32_t*) (inbuffer - off);

    c = av_be2ne32((0x37c511f2 >> (off*8)) | (0x37c511f2 << (32-(off*8))));

    bytes += 3 + off;

    for (i = 0; i < bytes/4; i++)

        obuf[i] = c ^ buf[i];



    return off;

}

ogg_get_length (AVFormatContext * s)

{

    ogg_t *ogg = s->priv_data;

    int idx = -1, i;

    offset_t size, end;



    if(s->pb.is_streamed)

        return 0;



// already set

    if (s->duration != AV_NOPTS_VALUE)

        return 0;



    size = url_fsize(&s->pb);

    if(size < 0)

        return 0;

    end = size > MAX_PAGE_SIZE? size - MAX_PAGE_SIZE: size;



    ogg_save (s);

    url_fseek (&s->pb, end, SEEK_SET);



    while (!ogg_read_page (s, &i)){

        if (ogg->streams[i].granule != -1 && ogg->streams[i].granule != 0)

            idx = i;

    }



    if (idx != -1){

        s->streams[idx]->duration =

            ogg_gptopts (s, idx, ogg->streams[idx].granule);

    }



    ogg->size = size;

    ogg_restore (s, 0);

    ogg_save (s);

    while (!ogg_read_page (s, &i)) {

        if (i == idx && ogg->streams[i].granule != -1 && ogg->streams[i].granule != 0)

            break;

    }

    if (i == idx) {

        s->streams[idx]->start_time = ogg_gptopts (s, idx, ogg->streams[idx].granule);

        s->streams[idx]->duration -= s->streams[idx]->start_time;

    }

    ogg_restore (s, 0);



    return 0;

}

static int rm_write_header(AVFormatContext *s)
{
    RMMuxContext *rm = s->priv_data;
    StreamInfo *stream;
    int n;
    AVCodecContext *codec;
    for(n=0;n<s->nb_streams;n++) {
        s->streams[n]->id = n;
        codec = s->streams[n]->codec;
        stream = &rm->streams[n];
        memset(stream, 0, sizeof(StreamInfo));
        stream->num = n;
        stream->bit_rate = codec->bit_rate;
        stream->enc = codec;
        switch(codec->codec_type) {
        case AVMEDIA_TYPE_AUDIO:
            rm->audio_stream = stream;
            stream->frame_rate = (float)codec->sample_rate / (float)codec->frame_size;
            /* XXX: dummy values */
            stream->packet_max_size = 1024;
            stream->nb_packets = 0;
            stream->total_frames = stream->nb_packets;
            break;
        case AVMEDIA_TYPE_VIDEO:
            rm->video_stream = stream;
            stream->frame_rate = (float)codec->time_base.den / (float)codec->time_base.num;
            /* XXX: dummy values */
            stream->packet_max_size = 4096;
            stream->nb_packets = 0;
            stream->total_frames = stream->nb_packets;
            break;
        default:
            return -1;
    if (rv10_write_header(s, 0, 0))
        return AVERROR_INVALIDDATA;
    avio_flush(s->pb);
    return 0;

static inline void mix_stereo_to_mono(AC3DecodeContext *ctx)

{

    int i;

    float (*output)[256] = ctx->audio_block.block_output;



    for (i = 0; i < 256; i++)

        output[1][i] += output[2][i];

    memset(output[2], 0, sizeof(output[2]));

}

static int msmpeg4_decode_dc(MpegEncContext * s, int n, int *dir_ptr)

{

    int level, pred;



    if(s->msmpeg4_version<=2){

        if (n < 4) {

            level = get_vlc2(&s->gb, v2_dc_lum_vlc.table, DC_VLC_BITS, 3);

        } else {

            level = get_vlc2(&s->gb, v2_dc_chroma_vlc.table, DC_VLC_BITS, 3);

        }

        if (level < 0)

            return -1;

        level-=256;

    }else{  //FIXME optimize use unified tables & index

        if (n < 4) {

            level = get_vlc2(&s->gb, ff_msmp4_dc_luma_vlc[s->dc_table_index].table, DC_VLC_BITS, 3);

        } else {

            level = get_vlc2(&s->gb, ff_msmp4_dc_chroma_vlc[s->dc_table_index].table, DC_VLC_BITS, 3);

        }

        if (level < 0){

            av_log(s->avctx, AV_LOG_ERROR, "illegal dc vlc\n");

            return -1;

        }



        if (level == DC_MAX) {

            level = get_bits(&s->gb, 8);

            if (get_bits1(&s->gb))

                level = -level;

        } else if (level != 0) {

            if (get_bits1(&s->gb))

                level = -level;

        }

    }



    if(s->msmpeg4_version==1){

        int32_t *dc_val;

        pred = msmpeg4v1_pred_dc(s, n, &dc_val);

        level += pred;



        /* update predictor */

        *dc_val= level;

    }else{

        int16_t *dc_val;

        pred   = ff_msmpeg4_pred_dc(s, n, &dc_val, dir_ptr);

        level += pred;



        /* update predictor */

        if (n < 4) {

            *dc_val = level * s->y_dc_scale;

        } else {

            *dc_val = level * s->c_dc_scale;

        }

    }



    return level;

}

