static inline int GetCode(GifState * s)

{

    int c, sizbuf;

    uint8_t *ptr;



    while (s->bbits < s->cursize) {

        ptr = s->pbuf;

        if (ptr >= s->ebuf) {

            if (!s->eob_reached) {

                sizbuf = get_byte(s->f);

                s->ebuf = s->buf + sizbuf;

                s->pbuf = s->buf;

                if (sizbuf > 0) {

                    get_buffer(s->f, s->buf, sizbuf);

                } else {

                    s->eob_reached = 1;

                }

            }

            ptr = s->pbuf;

        }

        s->bbuf |= ptr[0] << s->bbits;

        ptr++;

        s->pbuf = ptr;

        s->bbits += 8;

    }

    c = s->bbuf & s->curmask;

    s->bbuf >>= s->cursize;

    s->bbits -= s->cursize;

    return c;

}

static void filter(SPPContext *p, uint8_t *dst, uint8_t *src,

                   int dst_linesize, int src_linesize, int width, int height,

                   const uint8_t *qp_table, int qp_stride, int is_luma, int sample_bytes)

{

    int x, y, i;

    const int count = 1 << p->log2_count;

    const int linesize = is_luma ? p->temp_linesize : FFALIGN(width+16, 16);

    DECLARE_ALIGNED(16, uint64_t, block_align)[32];

    int16_t *block  = (int16_t *)block_align;

    int16_t *block2 = (int16_t *)(block_align + 16);

    uint16_t *psrc16 = (uint16_t*)p->src;



    for (y = 0; y < height; y++) {

        int index = 8 + 8*linesize + y*linesize;

        memcpy(p->src + index*sample_bytes, src + y*src_linesize, width*sample_bytes);

        if (sample_bytes == 1) {

            for (x = 0; x < 8; x++) {

                p->src[index         - x - 1] = p->src[index +         x    ];

                p->src[index + width + x    ] = p->src[index + width - x - 1];

            }

        } else {

            for (x = 0; x < 8; x++) {

                psrc16[index         - x - 1] = psrc16[index +         x    ];

                psrc16[index + width + x    ] = psrc16[index + width - x - 1];

            }

        }

    }

    for (y = 0; y < 8; y++) {

        memcpy(p->src + (       7-y)*linesize * sample_bytes, p->src + (       y+8)*linesize * sample_bytes, linesize * sample_bytes);

        memcpy(p->src + (height+8+y)*linesize * sample_bytes, p->src + (height-y+7)*linesize * sample_bytes, linesize * sample_bytes);

    }



    for (y = 0; y < height + 8; y += 8) {

        memset(p->temp + (8 + y) * linesize, 0, 8 * linesize * sizeof(*p->temp));

        for (x = 0; x < width + 8; x += 8) {

            int qp;



            if (p->qp) {

                qp = p->qp;

            } else{

                const int qps = 3 + is_luma;

                qp = qp_table[(FFMIN(x, width - 1) >> qps) + (FFMIN(y, height - 1) >> qps) * qp_stride];

                qp = FFMAX(1, norm_qscale(qp, p->qscale_type));

            }

            for (i = 0; i < count; i++) {

                const int x1 = x + offset[i + count - 1][0];

                const int y1 = y + offset[i + count - 1][1];

                const int index = x1 + y1*linesize;

                p->dct->get_pixels(block, p->src + sample_bytes*index, sample_bytes*linesize);

                p->dct->fdct(block);

                p->requantize(block2, block, qp, p->dct->idct_permutation);

                p->dct->idct(block2);

                add_block(p->temp + index, linesize, block2);

            }

        }

        if (y) {

            if (sample_bytes == 1) {

                p->store_slice(dst + (y - 8) * dst_linesize, p->temp + 8 + y*linesize,

                               dst_linesize, linesize, width,

                               FFMIN(8, height + 8 - y), MAX_LEVEL - p->log2_count,

                               ldither);

            } else {

                store_slice16_c((uint16_t*)(dst + (y - 8) * dst_linesize), p->temp + 8 + y*linesize,

                                dst_linesize/2, linesize, width,

                                FFMIN(8, height + 8 - y), MAX_LEVEL - p->log2_count,

                                ldither);

            }

        }

    }

}

static int vp8_alloc_frame(VP8Context *s, AVFrame *f)

{

    int ret;

    if ((ret = ff_thread_get_buffer(s->avctx, f)) < 0)

        return ret;

    if (!s->maps_are_invalid && s->num_maps_to_be_freed) {

        f->ref_index[0] = s->segmentation_maps[--s->num_maps_to_be_freed];

    } else if (!(f->ref_index[0] = av_mallocz(s->mb_width * s->mb_height))) {

        ff_thread_release_buffer(s->avctx, f);

        return AVERROR(ENOMEM);

    }

    return 0;

}

static int64_t read_ts(const char *s)

{

    int hh, mm, ss, ms;

    if (sscanf(s, "%u:%u:%u.%u", &hh, &mm, &ss, &ms) == 4) return (hh*3600 + mm*60 + ss) * 1000 + ms;

    if (sscanf(s,    "%u:%u.%u",      &mm, &ss, &ms) == 3) return (          mm*60 + ss) * 1000 + ms;

    return AV_NOPTS_VALUE;

}

static int allocate_buffers(ShortenContext *s)

{

    int i, chan, err;



    for (chan = 0; chan < s->channels; chan++) {

        if (FFMAX(1, s->nmean) >= UINT_MAX / sizeof(int32_t)) {

            av_log(s->avctx, AV_LOG_ERROR, "nmean too large\n");

            return AVERROR_INVALIDDATA;

        }

        if (s->blocksize + s->nwrap >= UINT_MAX / sizeof(int32_t) ||

            s->blocksize + s->nwrap <= (unsigned)s->nwrap) {

            av_log(s->avctx, AV_LOG_ERROR,

                   "s->blocksize + s->nwrap too large\n");

            return AVERROR_INVALIDDATA;

        }



        if ((err = av_reallocp_array(&s->offset[chan],

                               sizeof(int32_t),

                               FFMAX(1, s->nmean))) < 0)

            return err;



        if ((err = av_reallocp_array(&s->decoded_base[chan], (s->blocksize + s->nwrap),

                               sizeof(s->decoded_base[0][0]))) < 0)

            return err;

        for (i = 0; i < s->nwrap; i++)

            s->decoded_base[chan][i] = 0;

        s->decoded[chan] = s->decoded_base[chan] + s->nwrap;

    }



    if ((err = av_reallocp_array(&s->coeffs, s->nwrap, sizeof(*s->coeffs))) < 0)

        return err;



    return 0;

}

static av_always_inline int rv40_loop_filter_strength(uint8_t *src,

                                                      int step, int stride,

                                                      int beta, int beta2,

                                                      int edge,

                                                      int *p1, int *q1)

{

    int sum_p1p0 = 0, sum_q1q0 = 0, sum_p1p2 = 0, sum_q1q2 = 0;

    int strong0 = 0, strong1 = 0;

    uint8_t *ptr;

    int i;



    for (i = 0, ptr = src; i < 4; i++, ptr += stride) {

        sum_p1p0 += ptr[-2*step] - ptr[-1*step];

        sum_q1q0 += ptr[ 1*step] - ptr[ 0*step];

    }



    *p1 = FFABS(sum_p1p0) < (beta << 2);

    *q1 = FFABS(sum_q1q0) < (beta << 2);



    if(!*p1 && !*q1)

        return 0;



    if (!edge)

        return 0;



    for (i = 0, ptr = src; i < 4; i++, ptr += stride) {

        sum_p1p2 += ptr[-2*step] - ptr[-3*step];

        sum_q1q2 += ptr[ 1*step] - ptr[ 2*step];

    }



    strong0 = *p1 && (FFABS(sum_p1p2) < beta2);

    strong1 = *q1 && (FFABS(sum_q1q2) < beta2);



    return strong0 && strong1;

}

static void encode_window_bands_info(AACEncContext *s, SingleChannelElement *sce,

                                     int win, int group_len, const float lambda)

{

    BandCodingPath path[120][CB_TOT_ALL];

    int w, swb, cb, start, size;

    int i, j;

    const int max_sfb  = sce->ics.max_sfb;

    const int run_bits = sce->ics.num_windows == 1 ? 5 : 3;

    const int run_esc  = (1 << run_bits) - 1;

    int idx, ppos, count;

    int stackrun[120], stackcb[120], stack_len;

    float next_minrd = INFINITY;

    int next_mincb = 0;



    abs_pow34_v(s->scoefs, sce->coeffs, 1024);

    start = win*128;

    for (cb = 0; cb < CB_TOT_ALL; cb++) {

        path[0][cb].cost     = 0.0f;

        path[0][cb].prev_idx = -1;

        path[0][cb].run      = 0;

    }

    for (swb = 0; swb < max_sfb; swb++) {

        size = sce->ics.swb_sizes[swb];

        if (sce->zeroes[win*16 + swb]) {

            for (cb = 0; cb < CB_TOT_ALL; cb++) {

                path[swb+1][cb].prev_idx = cb;

                path[swb+1][cb].cost     = path[swb][cb].cost;

                path[swb+1][cb].run      = path[swb][cb].run + 1;

            }

        } else {

            float minrd = next_minrd;

            int mincb = next_mincb;

            next_minrd = INFINITY;

            next_mincb = 0;

            for (cb = 0; cb < CB_TOT_ALL; cb++) {

                float cost_stay_here, cost_get_here;

                float rd = 0.0f;

                if (cb >= 12 && sce->band_type[win*16+swb] < aac_cb_out_map[cb] ||

                    cb  < aac_cb_in_map[sce->band_type[win*16+swb]] && sce->band_type[win*16+swb] > aac_cb_out_map[cb]) {

                    path[swb+1][cb].prev_idx = -1;

                    path[swb+1][cb].cost     = INFINITY;

                    path[swb+1][cb].run      = path[swb][cb].run + 1;

                    continue;

                }

                for (w = 0; w < group_len; w++) {

                    FFPsyBand *band = &s->psy.ch[s->cur_channel].psy_bands[(win+w)*16+swb];

                    rd += quantize_band_cost(s, sce->coeffs + start + w*128,

                                             s->scoefs + start + w*128, size,

                                             sce->sf_idx[(win+w)*16+swb], aac_cb_out_map[cb],

                                             lambda / band->threshold, INFINITY, NULL, 0);

                }

                cost_stay_here = path[swb][cb].cost + rd;

                cost_get_here  = minrd              + rd + run_bits + 4;

                if (   run_value_bits[sce->ics.num_windows == 8][path[swb][cb].run]

                    != run_value_bits[sce->ics.num_windows == 8][path[swb][cb].run+1])

                    cost_stay_here += run_bits;

                if (cost_get_here < cost_stay_here) {

                    path[swb+1][cb].prev_idx = mincb;

                    path[swb+1][cb].cost     = cost_get_here;

                    path[swb+1][cb].run      = 1;

                } else {

                    path[swb+1][cb].prev_idx = cb;

                    path[swb+1][cb].cost     = cost_stay_here;

                    path[swb+1][cb].run      = path[swb][cb].run + 1;

                }

                if (path[swb+1][cb].cost < next_minrd) {

                    next_minrd = path[swb+1][cb].cost;

                    next_mincb = cb;

                }

            }

        }

        start += sce->ics.swb_sizes[swb];

    }



    //convert resulting path from backward-linked list

    stack_len = 0;

    idx       = 0;

    for (cb = 1; cb < CB_TOT_ALL; cb++)

        if (path[max_sfb][cb].cost < path[max_sfb][idx].cost)

            idx = cb;

    ppos = max_sfb;

    while (ppos > 0) {

        av_assert1(idx >= 0);

        cb = idx;

        stackrun[stack_len] = path[ppos][cb].run;

        stackcb [stack_len] = cb;

        idx = path[ppos-path[ppos][cb].run+1][cb].prev_idx;

        ppos -= path[ppos][cb].run;

        stack_len++;

    }

    //perform actual band info encoding

    start = 0;

    for (i = stack_len - 1; i >= 0; i--) {

        cb = aac_cb_out_map[stackcb[i]];

        put_bits(&s->pb, 4, cb);

        count = stackrun[i];

        memset(sce->zeroes + win*16 + start, !cb, count);

        //XXX: memset when band_type is also uint8_t

        for (j = 0; j < count; j++) {

            sce->band_type[win*16 + start] = cb;

            start++;

        }

        while (count >= run_esc) {

            put_bits(&s->pb, run_bits, run_esc);

            count -= run_esc;

        }

        put_bits(&s->pb, run_bits, count);

    }

}

callback(void *priv_data, int index, uint8_t *buf, int buf_size, int64_t time)

{

    AVFormatContext *s = priv_data;

    struct dshow_ctx *ctx = s->priv_data;

    AVPacketList **ppktl, *pktl_next;



//    dump_videohdr(s, vdhdr);



    WaitForSingleObject(ctx->mutex, INFINITE);



    if(shall_we_drop(s, index))

        goto fail;



    pktl_next = av_mallocz(sizeof(AVPacketList));

    if(!pktl_next)

        goto fail;



    if(av_new_packet(&pktl_next->pkt, buf_size) < 0) {

        av_free(pktl_next);

        goto fail;

    }



    pktl_next->pkt.stream_index = index;

    pktl_next->pkt.pts = time;

    memcpy(pktl_next->pkt.data, buf, buf_size);



    for(ppktl = &ctx->pktl ; *ppktl ; ppktl = &(*ppktl)->next);

    *ppktl = pktl_next;

    ctx->curbufsize[index] += buf_size;



    SetEvent(ctx->event[1]);

    ReleaseMutex(ctx->mutex);



    return;

fail:

    ReleaseMutex(ctx->mutex);

    return;

}

static int xan_decode_frame_type0(AVCodecContext *avctx, AVPacket *avpkt)

{

    const uint8_t *buf = avpkt->data;

    XanContext *s = avctx->priv_data;

    uint8_t *ybuf, *prev_buf, *src = s->scratch_buffer;

    unsigned  chroma_off, corr_off;

    int cur, last, size;

    int i, j;

    int ret;



    corr_off   = AV_RL32(buf + 8);

    chroma_off = AV_RL32(buf + 4);



    if ((ret = xan_decode_chroma(avctx, avpkt)) != 0)

        return ret;



    size = avpkt->size - 4;

    if (corr_off >= avpkt->size) {

        av_log(avctx, AV_LOG_WARNING, "Ignoring invalid correction block position\n");

        corr_off = 0;

    }

    if (corr_off)

        size = corr_off;

    if (chroma_off)

        size = FFMIN(size, chroma_off);

    ret = xan_unpack_luma(buf + 12, size, src, s->buffer_size >> 1);

    if (ret) {

        av_log(avctx, AV_LOG_ERROR, "Luma decoding failed\n");

        return ret;

    }



    ybuf = s->y_buffer;

    last = *src++;

    ybuf[0] = last << 1;

    for (j = 1; j < avctx->width - 1; j += 2) {

        cur = (last + *src++) & 0x1F;

        ybuf[j]   = last + cur;

        ybuf[j+1] = cur << 1;

        last = cur;

    }

    ybuf[j]  = last << 1;

    prev_buf = ybuf;

    ybuf += avctx->width;



    for (i = 1; i < avctx->height; i++) {

        last = ((prev_buf[0] >> 1) + *src++) & 0x1F;

        ybuf[0] = last << 1;

        for (j = 1; j < avctx->width - 1; j += 2) {

            cur = ((prev_buf[j + 1] >> 1) + *src++) & 0x1F;

            ybuf[j]   = last + cur;

            ybuf[j+1] = cur << 1;

            last = cur;

        }

        ybuf[j] = last << 1;

        prev_buf = ybuf;

        ybuf += avctx->width;

    }



    if (corr_off) {

        int corr_end, dec_size;



        corr_end = avpkt->size;

        if (chroma_off > corr_off)

            corr_end = chroma_off;

        dec_size = xan_unpack(s->scratch_buffer, s->buffer_size,

                              avpkt->data + 8 + corr_off,

                              corr_end - corr_off);

        if (dec_size < 0)

            dec_size = 0;

        for (i = 0; i < dec_size; i++)

            s->y_buffer[i*2+1] = (s->y_buffer[i*2+1] + (s->scratch_buffer[i] << 1)) & 0x3F;

    }



    src  = s->y_buffer;

    ybuf = s->pic.data[0];

    for (j = 0; j < avctx->height; j++) {

        for (i = 0; i < avctx->width; i++)

            ybuf[i] = (src[i] << 2) | (src[i] >> 3);

        src  += avctx->width;

        ybuf += s->pic.linesize[0];

    }



    return 0;

}

paint_mouse_pointer(XImage *image, struct x11grab *s)

{

    int x_off = s->x_off;

    int y_off = s->y_off;

    int width = s->width;

    int height = s->height;

    Display *dpy = s->dpy;

    XFixesCursorImage *xcim;

    int x, y;

    int line, column;

    int to_line, to_column;

    int pixstride = image->bits_per_pixel >> 3;

    /* Warning: in its insanity, xlib provides unsigned image data through a

     * char* pointer, so we have to make it uint8_t to make things not break.

     * Anyone who performs further investigation of the xlib API likely risks

     * permanent brain damage. */

    uint8_t *pix = image->data;

    Cursor c;

    Window w;

    XSetWindowAttributes attr;



    /* Code doesn't currently support 16-bit or PAL8 */

    if (image->bits_per_pixel != 24 && image->bits_per_pixel != 32)

        return;



    c = XCreateFontCursor(dpy, XC_left_ptr);

    w = DefaultRootWindow(dpy);

    attr.cursor = c;

    XChangeWindowAttributes(dpy, w, CWCursor, &attr);



    xcim = XFixesGetCursorImage(dpy);



    x = xcim->x - xcim->xhot;

    y = xcim->y - xcim->yhot;



    to_line = FFMIN((y + xcim->height), (height + y_off));

    to_column = FFMIN((x + xcim->width), (width + x_off));



    for (line = FFMAX(y, y_off); line < to_line; line++) {

        for (column = FFMAX(x, x_off); column < to_column; column++) {

            int  xcim_addr = (line - y) * xcim->width + column - x;

            int image_addr = ((line - y_off) * width + column - x_off) * pixstride;

            int r = (uint8_t)(xcim->pixels[xcim_addr] >>  0);

            int g = (uint8_t)(xcim->pixels[xcim_addr] >>  8);

            int b = (uint8_t)(xcim->pixels[xcim_addr] >> 16);

            int a = (uint8_t)(xcim->pixels[xcim_addr] >> 24);



            if (a == 255) {

                pix[image_addr+0] = r;

                pix[image_addr+1] = g;

                pix[image_addr+2] = b;

            } else if (a) {

                /* pixel values from XFixesGetCursorImage come premultiplied by alpha */

                pix[image_addr+0] = r + (pix[image_addr+0]*(255-a) + 255/2) / 255;

                pix[image_addr+1] = g + (pix[image_addr+1]*(255-a) + 255/2) / 255;

                pix[image_addr+2] = b + (pix[image_addr+2]*(255-a) + 255/2) / 255;

            }

        }

    }



    XFree(xcim);

    xcim = NULL;

}

int ff_mediacodec_dec_close(AVCodecContext *avctx, MediaCodecDecContext *s)
{
    if (s->codec) {
        ff_AMediaCodec_delete(s->codec);
        s->codec = NULL;
    }
    if (s->format) {
        ff_AMediaFormat_delete(s->format);
        s->format = NULL;
    }
    return 0;
}

static int fic_decode_frame(AVCodecContext *avctx, void *data,

                            int *got_frame, AVPacket *avpkt)

{

    FICContext *ctx = avctx->priv_data;

    uint8_t *src = avpkt->data;

    int ret;

    int slice, nslices;

    int msize;

    int tsize;

    int cur_x, cur_y;

    int skip_cursor = ctx->skip_cursor;

    uint8_t *sdata;



    if ((ret = ff_reget_buffer(avctx, ctx->frame)) < 0)

        return ret;



    /* Header + at least one slice (4) */

    if (avpkt->size < FIC_HEADER_SIZE + 4) {

        av_log(avctx, AV_LOG_ERROR, "Frame data is too small.\n");

        return AVERROR_INVALIDDATA;

    }



    /* Check for header. */

    if (memcmp(src, fic_header, 7))

        av_log(avctx, AV_LOG_WARNING, "Invalid FIC Header.\n");



    /* Is it a skip frame? */

    if (src[17]) {

        if (!ctx->final_frame) {

            av_log(avctx, AV_LOG_WARNING, "Initial frame is skipped\n");

            return AVERROR_INVALIDDATA;

        }

        goto skip;

    }



    nslices = src[13];

    if (!nslices) {

        av_log(avctx, AV_LOG_ERROR, "Zero slices found.\n");

        return AVERROR_INVALIDDATA;

    }



    /* High or Low Quality Matrix? */

    ctx->qmat = src[23] ? fic_qmat_hq : fic_qmat_lq;



    /* Skip cursor data. */

    tsize = AV_RB24(src + 24);

    if (tsize > avpkt->size - FIC_HEADER_SIZE) {

        av_log(avctx, AV_LOG_ERROR,

               "Packet is too small to contain cursor (%d vs %d bytes).\n",

               tsize, avpkt->size - FIC_HEADER_SIZE);

        return AVERROR_INVALIDDATA;

    }



    if (!tsize || !AV_RL16(src + 37) || !AV_RL16(src + 39))

        skip_cursor = 1;



    if (!skip_cursor && tsize < 32) {

        av_log(avctx, AV_LOG_WARNING,

               "Cursor data too small. Skipping cursor.\n");

        skip_cursor = 1;

    }



    /* Cursor position. */

    cur_x = AV_RL16(src + 33);

    cur_y = AV_RL16(src + 35);

    if (!skip_cursor && (cur_x > avctx->width || cur_y > avctx->height)) {

        av_log(avctx, AV_LOG_DEBUG,

               "Invalid cursor position: (%d,%d). Skipping cursor.\n",

               cur_x, cur_y);

        skip_cursor = 1;

    }



    if (!skip_cursor && (AV_RL16(src + 37) != 32 || AV_RL16(src + 39) != 32)) {

        av_log(avctx, AV_LOG_WARNING,

               "Invalid cursor size. Skipping cursor.\n");

        skip_cursor = 1;

    }



    /* Slice height for all but the last slice. */

    ctx->slice_h = 16 * (ctx->aligned_height >> 4) / nslices;

    if (ctx->slice_h % 16)

        ctx->slice_h = FFALIGN(ctx->slice_h - 16, 16);



    /* First slice offset and remaining data. */

    sdata = src + tsize + FIC_HEADER_SIZE + 4 * nslices;

    msize = avpkt->size - nslices * 4 - tsize - FIC_HEADER_SIZE;



    if (msize <= 0) {

        av_log(avctx, AV_LOG_ERROR, "Not enough frame data to decode.\n");

        return AVERROR_INVALIDDATA;

    }



    /*

     * Set the frametype to I initially. It will be set to P if the frame

     * has any dependencies (skip blocks). There will be a race condition

     * inside the slice decode function to set these, but we do not care.

     * since they will only ever be set to 0/P.

     */

    ctx->frame->key_frame = 1;

    ctx->frame->pict_type = AV_PICTURE_TYPE_I;



    /* Allocate slice data. */

    av_fast_malloc(&ctx->slice_data, &ctx->slice_data_size,

                   nslices * sizeof(ctx->slice_data[0]));

    if (!ctx->slice_data_size) {

        av_log(avctx, AV_LOG_ERROR, "Could not allocate slice data.\n");

        return AVERROR(ENOMEM);

    }

    memset(ctx->slice_data, 0, nslices * sizeof(ctx->slice_data[0]));



    for (slice = 0; slice < nslices; slice++) {

        unsigned slice_off = AV_RB32(src + tsize + FIC_HEADER_SIZE + slice * 4);

        unsigned slice_size;

        int y_off   = ctx->slice_h * slice;

        int slice_h = ctx->slice_h;



        /*

         * Either read the slice size, or consume all data left.

         * Also, special case the last slight height.

         */

        if (slice == nslices - 1) {

            slice_size   = msize;

            slice_h      = FFALIGN(avctx->height - ctx->slice_h * (nslices - 1), 16);

        } else {

            slice_size = AV_RB32(src + tsize + FIC_HEADER_SIZE + slice * 4 + 4);

        }



        if (slice_size < slice_off || slice_size > msize)

            continue;



        slice_size -= slice_off;



        ctx->slice_data[slice].src      = sdata + slice_off;

        ctx->slice_data[slice].src_size = slice_size;

        ctx->slice_data[slice].slice_h  = slice_h;

        ctx->slice_data[slice].y_off    = y_off;

    }



    if ((ret = avctx->execute(avctx, fic_decode_slice, ctx->slice_data,

                              NULL, nslices, sizeof(ctx->slice_data[0]))) < 0)

        return ret;



    av_frame_free(&ctx->final_frame);

    ctx->final_frame = av_frame_clone(ctx->frame);

    if (!ctx->final_frame) {

        av_log(avctx, AV_LOG_ERROR, "Could not clone frame buffer.\n");

        return AVERROR(ENOMEM);

    }



    /* Make sure we use a user-supplied buffer. */

    if ((ret = ff_reget_buffer(avctx, ctx->final_frame)) < 0) {

        av_log(avctx, AV_LOG_ERROR, "Could not make frame writable.\n");

        return ret;

    }



    /* Draw cursor. */

    if (!skip_cursor) {

        memcpy(ctx->cursor_buf, src + 59, 32 * 32 * 4);

        fic_draw_cursor(avctx, cur_x, cur_y);

    }



skip:

    *got_frame = 1;

    if ((ret = av_frame_ref(data, ctx->final_frame)) < 0)

        return ret;



    return avpkt->size;

}

static int append_to_cached_buf(AVCodecContext *avctx,

                                const uint8_t *buf, int buf_size)

{

    DVDSubContext *ctx = avctx->priv_data;



    if (ctx->buf_size > 0xffff - buf_size) {

        av_log(avctx, AV_LOG_WARNING, "Attempt to reconstruct "

               "too large SPU packets aborted.\n");

        av_freep(&ctx->buf);

        return AVERROR_INVALIDDATA;

    }

    ctx->buf = av_realloc(ctx->buf, ctx->buf_size + buf_size);

    if (!ctx->buf)

        return AVERROR(ENOMEM);

    memcpy(ctx->buf + ctx->buf_size, buf, buf_size);

    ctx->buf_size += buf_size;

    return 0;

}

av_cold void ff_dcadsp_init_x86(DCADSPContext *s)

{

    int cpu_flags = av_get_cpu_flags();



    if (EXTERNAL_SSE(cpu_flags)) {

#if ARCH_X86_32

        s->int8x8_fmul_int32 = ff_int8x8_fmul_int32_sse;

#endif

        s->lfe_fir[0]        = ff_dca_lfe_fir0_sse;

        s->lfe_fir[1]        = ff_dca_lfe_fir1_sse;

    }



    if (EXTERNAL_SSE2(cpu_flags)) {

        s->int8x8_fmul_int32 = ff_int8x8_fmul_int32_sse2;

    }



    if (EXTERNAL_SSE4(cpu_flags)) {

        s->int8x8_fmul_int32 = ff_int8x8_fmul_int32_sse4;

    }

}

static int rm_write_packet(AVFormatContext *s, AVPacket *pkt)

{

    if (s->streams[pkt->stream_index]->codec.codec_type == 

        CODEC_TYPE_AUDIO)

        return rm_write_audio(s, pkt->data, pkt->size);

    else

        return rm_write_video(s, pkt->data, pkt->size);

}

static int sctp_write(URLContext *h, const uint8_t *buf, int size)

{

    SCTPContext *s = h->priv_data;

    int ret;



    if (!(h->flags & AVIO_FLAG_NONBLOCK)) {

        ret = sctp_wait_fd(s->fd, 1);

        if (ret < 0)

            return ret;

    }



    if (s->max_streams) {

        /*StreamId is introduced as a 2byte code into the stream*/

        struct sctp_sndrcvinfo info = { 0 };

        info.sinfo_stream           = AV_RB16(buf);

        if (info.sinfo_stream > s->max_streams)

            abort();

        ret = ff_sctp_send(s->fd, buf + 2, size - 2, &info, MSG_EOR);

    } else

        ret = send(s->fd, buf, size, 0);



    return ret < 0 ? ff_neterrno() : ret;

}

