    return 0;

}

static inline void cvtyuvtoRGB (SwsContext *c,

			   vector signed short Y, vector signed short U, vector signed short V,

			   vector signed short *R, vector signed short *G, vector signed short *B)

{

  vector signed   short vx,ux,uvx;



  Y = vec_mradds (Y, c->CY, c->OY);



  U = vec_sub (U,(vector signed short)(128));

  V = vec_sub (V,(vector signed short)(128));



  //   ux  = (CBU*(u<<c->CSHIFT)+0x4000)>>15;

  ux = vec_sl (U, c->CSHIFT);

  *B = vec_mradds (ux, c->CBU, Y);



  // vx  = (CRV*(v<<c->CSHIFT)+0x4000)>>15;

  vx = vec_sl (V, c->CSHIFT);

  *R = vec_mradds (vx, c->CRV, Y);



  // uvx = ((CGU*u) + (CGV*v))>>15;

  uvx = vec_mradds (U, c->CGU, Y);

  *G = vec_mradds (V, c->CGV, uvx);

}

static void vaapi_encode_h264_write_sei(PutBitContext *pbc,

                                        VAAPIEncodeContext *ctx,

                                        VAAPIEncodePicture *pic)

{

    VAAPIEncodeH264Context *priv = ctx->priv_data;

    PutBitContext payload_bits;

    char payload[256];

    int payload_type, payload_size, i;

    void (*write_payload)(PutBitContext *pbc,

                          VAAPIEncodeContext *ctx,

                          VAAPIEncodePicture *pic) = NULL;



    vaapi_encode_h264_write_nal_header(pbc, NAL_SEI, 0);



    for (payload_type = 0; payload_type < 64; payload_type++) {

        switch (payload_type) {

        case SEI_TYPE_BUFFERING_PERIOD:

            if (!priv->send_timing_sei ||

                pic->type != PICTURE_TYPE_IDR)

                continue;

            write_payload = &vaapi_encode_h264_write_buffering_period;

            break;

        case SEI_TYPE_PIC_TIMING:

            if (!priv->send_timing_sei)

                continue;

            write_payload = &vaapi_encode_h264_write_pic_timing;

            break;

        case SEI_TYPE_USER_DATA_UNREGISTERED:

            if (pic->encode_order != 0)

                continue;

            write_payload = &vaapi_encode_h264_write_identifier;

            break;

        default:

            continue;

        }



        init_put_bits(&payload_bits, payload, sizeof(payload));

        write_payload(&payload_bits, ctx, pic);

        if (put_bits_count(&payload_bits) & 7) {

            write_u(&payload_bits, 1, 1, bit_equal_to_one);

            while (put_bits_count(&payload_bits) & 7)

                write_u(&payload_bits, 1, 0, bit_equal_to_zero);

        }

        payload_size = put_bits_count(&payload_bits) / 8;

        flush_put_bits(&payload_bits);



        u(8, payload_type, last_payload_type_byte);

        u(8, payload_size, last_payload_size_byte);

        for (i = 0; i < payload_size; i++)

            u(8, payload[i] & 0xff, sei_payload);

    }



    vaapi_encode_h264_write_trailing_rbsp(pbc);

}

static int parse_metadata(DBEContext *s)

{

    int i, ret, key = parse_key(s), mtd_size;



    if ((ret = convert_input(s, 1, key)) < 0)

        return ret;



    skip_bits(&s->gb, 4);

    mtd_size = get_bits(&s->gb, 10);

    if (!mtd_size) {

        av_log(s->avctx, AV_LOG_ERROR, "Invalid metadata size\n");

        return AVERROR_INVALIDDATA;

    }



    if ((ret = convert_input(s, mtd_size, key)) < 0)

        return ret;



    skip_bits(&s->gb, 14);

    s->prog_conf = get_bits(&s->gb, 6);

    if (s->prog_conf > MAX_PROG_CONF) {

        av_log(s->avctx, AV_LOG_ERROR, "Invalid program configuration\n");

        return AVERROR_INVALIDDATA;

    }



    s->nb_channels = nb_channels_tab[s->prog_conf];

    s->nb_programs = nb_programs_tab[s->prog_conf];



    s->fr_code      = get_bits(&s->gb, 4);

    s->fr_code_orig = get_bits(&s->gb, 4);

    if (!sample_rate_tab[s->fr_code] ||

        !sample_rate_tab[s->fr_code_orig]) {

        av_log(s->avctx, AV_LOG_ERROR, "Invalid frame rate code\n");

        return AVERROR_INVALIDDATA;

    }



    skip_bits_long(&s->gb, 88);

    for (i = 0; i < s->nb_channels; i++)

        s->ch_size[i] = get_bits(&s->gb, 10);

    s->mtd_ext_size = get_bits(&s->gb, 8);

    s->meter_size   = get_bits(&s->gb, 8);



    skip_bits_long(&s->gb, 10 * s->nb_programs);

    for (i = 0; i < s->nb_channels; i++) {

        s->rev_id[i]     = get_bits(&s->gb,  4);

        skip_bits1(&s->gb);

        s->begin_gain[i] = get_bits(&s->gb, 10);

        s->end_gain[i]   = get_bits(&s->gb, 10);

    }



    if (get_bits_left(&s->gb) < 0) {

        av_log(s->avctx, AV_LOG_ERROR, "Read past end of metadata\n");

        return AVERROR_INVALIDDATA;

    }



    skip_input(s, mtd_size + 1);

    return 0;

}

static void vp8_release_frame(VP8Context *s, AVFrame *f, int is_close)

{

    if (!is_close) {

        if (f->ref_index[0]) {

            assert(s->num_maps_to_be_freed < FF_ARRAY_ELEMS(s->segmentation_maps));

            s->segmentation_maps[s->num_maps_to_be_freed++] = f->ref_index[0];

            f->ref_index[0] = NULL;

        }

    } else {

        av_freep(&f->ref_index[0]);

    }

    ff_thread_release_buffer(s->avctx, f);

}

static int smacker_probe(AVProbeData *p)

{

    if(p->buf[0] == 'S' && p->buf[1] == 'M' && p->buf[2] == 'K'

        && (p->buf[3] == '2' || p->buf[3] == '4'))

        return AVPROBE_SCORE_MAX;

    else

        return 0;

}

static av_noinline void FUNC(hl_decode_mb)(H264Context *h, H264SliceContext *sl)

{

    const int mb_x    = h->mb_x;

    const int mb_y    = h->mb_y;

    const int mb_xy   = h->mb_xy;

    const int mb_type = h->cur_pic.mb_type[mb_xy];

    uint8_t *dest_y, *dest_cb, *dest_cr;

    int linesize, uvlinesize /*dct_offset*/;

    int i, j;

    int *block_offset = &h->block_offset[0];

    const int transform_bypass = !SIMPLE && (sl->qscale == 0 && h->sps.transform_bypass);

    /* is_h264 should always be true if SVQ3 is disabled. */

    const int is_h264 = !CONFIG_SVQ3_DECODER || SIMPLE || h->avctx->codec_id == AV_CODEC_ID_H264;

    void (*idct_add)(uint8_t *dst, int16_t *block, int stride);

    const int block_h   = 16 >> h->chroma_y_shift;

    const int chroma422 = CHROMA422(h);



    dest_y  = h->cur_pic.f.data[0] + ((mb_x << PIXEL_SHIFT)     + mb_y * h->linesize)  * 16;

    dest_cb = h->cur_pic.f.data[1] +  (mb_x << PIXEL_SHIFT) * 8 + mb_y * h->uvlinesize * block_h;

    dest_cr = h->cur_pic.f.data[2] +  (mb_x << PIXEL_SHIFT) * 8 + mb_y * h->uvlinesize * block_h;



    h->vdsp.prefetch(dest_y  + (h->mb_x & 3) * 4 * h->linesize   + (64 << PIXEL_SHIFT), h->linesize,       4);

    h->vdsp.prefetch(dest_cb + (h->mb_x & 7)     * h->uvlinesize + (64 << PIXEL_SHIFT), dest_cr - dest_cb, 2);



    h->list_counts[mb_xy] = sl->list_count;



    if (!SIMPLE && MB_FIELD(h)) {

        linesize     = sl->mb_linesize = h->linesize * 2;

        uvlinesize   = sl->mb_uvlinesize = h->uvlinesize * 2;

        block_offset = &h->block_offset[48];

        if (mb_y & 1) { // FIXME move out of this function?

            dest_y  -= h->linesize * 15;

            dest_cb -= h->uvlinesize * (block_h - 1);

            dest_cr -= h->uvlinesize * (block_h - 1);

        }

        if (FRAME_MBAFF(h)) {

            int list;

            for (list = 0; list < sl->list_count; list++) {

                if (!USES_LIST(mb_type, list))

                    continue;

                if (IS_16X16(mb_type)) {

                    int8_t *ref = &sl->ref_cache[list][scan8[0]];

                    fill_rectangle(ref, 4, 4, 8, (16 + *ref) ^ (h->mb_y & 1), 1);

                } else {

                    for (i = 0; i < 16; i += 4) {

                        int ref = sl->ref_cache[list][scan8[i]];

                        if (ref >= 0)

                            fill_rectangle(&sl->ref_cache[list][scan8[i]], 2, 2,

                                           8, (16 + ref) ^ (h->mb_y & 1), 1);

                    }

                }

            }

        }

    } else {

        linesize   = sl->mb_linesize   = h->linesize;

        uvlinesize = sl->mb_uvlinesize = h->uvlinesize;

        // dct_offset = s->linesize * 16;

    }



    if (!SIMPLE && IS_INTRA_PCM(mb_type)) {

        if (PIXEL_SHIFT) {

            const int bit_depth = h->sps.bit_depth_luma;

            int j;

            GetBitContext gb;

            init_get_bits(&gb, sl->intra_pcm_ptr,

                          ff_h264_mb_sizes[h->sps.chroma_format_idc] * bit_depth);



            for (i = 0; i < 16; i++) {

                uint16_t *tmp_y = (uint16_t *)(dest_y + i * linesize);

                for (j = 0; j < 16; j++)

                    tmp_y[j] = get_bits(&gb, bit_depth);

            }

            if (SIMPLE || !CONFIG_GRAY || !(h->flags & CODEC_FLAG_GRAY)) {

                if (!h->sps.chroma_format_idc) {

                    for (i = 0; i < block_h; i++) {

                        uint16_t *tmp_cb = (uint16_t *)(dest_cb + i * uvlinesize);

                        for (j = 0; j < 8; j++)

                            tmp_cb[j] = 1 << (bit_depth - 1);

                    }

                    for (i = 0; i < block_h; i++) {

                        uint16_t *tmp_cr = (uint16_t *)(dest_cr + i * uvlinesize);

                        for (j = 0; j < 8; j++)

                            tmp_cr[j] = 1 << (bit_depth - 1);

                    }

                } else {

                    for (i = 0; i < block_h; i++) {

                        uint16_t *tmp_cb = (uint16_t *)(dest_cb + i * uvlinesize);

                        for (j = 0; j < 8; j++)

                            tmp_cb[j] = get_bits(&gb, bit_depth);

                    }

                    for (i = 0; i < block_h; i++) {

                        uint16_t *tmp_cr = (uint16_t *)(dest_cr + i * uvlinesize);

                        for (j = 0; j < 8; j++)

                            tmp_cr[j] = get_bits(&gb, bit_depth);

                    }

                }

            }

        } else {

            for (i = 0; i < 16; i++)

                memcpy(dest_y + i * linesize, sl->intra_pcm_ptr + i * 16, 16);

            if (SIMPLE || !CONFIG_GRAY || !(h->flags & CODEC_FLAG_GRAY)) {

                if (!h->sps.chroma_format_idc) {

                    for (i = 0; i < block_h; i++) {

                        memset(dest_cb + i * uvlinesize, 128, 8);

                        memset(dest_cr + i * uvlinesize, 128, 8);

                    }

                } else {

                    const uint8_t *src_cb = sl->intra_pcm_ptr + 256;

                    const uint8_t *src_cr = sl->intra_pcm_ptr + 256 + block_h * 8;

                    for (i = 0; i < block_h; i++) {

                        memcpy(dest_cb + i * uvlinesize, src_cb + i * 8, 8);

                        memcpy(dest_cr + i * uvlinesize, src_cr + i * 8, 8);

                    }

                }

            }

        }

    } else {

        if (IS_INTRA(mb_type)) {

            if (h->deblocking_filter)

                xchg_mb_border(h, sl, dest_y, dest_cb, dest_cr, linesize,

                               uvlinesize, 1, 0, SIMPLE, PIXEL_SHIFT);



            if (SIMPLE || !CONFIG_GRAY || !(h->flags & CODEC_FLAG_GRAY)) {

                h->hpc.pred8x8[sl->chroma_pred_mode](dest_cb, uvlinesize);

                h->hpc.pred8x8[sl->chroma_pred_mode](dest_cr, uvlinesize);

            }



            hl_decode_mb_predict_luma(h, sl, mb_type, is_h264, SIMPLE,

                                      transform_bypass, PIXEL_SHIFT,

                                      block_offset, linesize, dest_y, 0);



            if (h->deblocking_filter)

                xchg_mb_border(h, sl, dest_y, dest_cb, dest_cr, linesize,

                               uvlinesize, 0, 0, SIMPLE, PIXEL_SHIFT);

        } else if (is_h264) {

            if (chroma422) {

                FUNC(hl_motion_422)(h, sl, dest_y, dest_cb, dest_cr,

                              h->qpel_put, h->h264chroma.put_h264_chroma_pixels_tab,

                              h->qpel_avg, h->h264chroma.avg_h264_chroma_pixels_tab,

                              h->h264dsp.weight_h264_pixels_tab,

                              h->h264dsp.biweight_h264_pixels_tab);

            } else {

                FUNC(hl_motion_420)(h, sl, dest_y, dest_cb, dest_cr,

                              h->qpel_put, h->h264chroma.put_h264_chroma_pixels_tab,

                              h->qpel_avg, h->h264chroma.avg_h264_chroma_pixels_tab,

                              h->h264dsp.weight_h264_pixels_tab,

                              h->h264dsp.biweight_h264_pixels_tab);

            }

        }



        hl_decode_mb_idct_luma(h, sl, mb_type, is_h264, SIMPLE, transform_bypass,

                               PIXEL_SHIFT, block_offset, linesize, dest_y, 0);



        if ((SIMPLE || !CONFIG_GRAY || !(h->flags & CODEC_FLAG_GRAY)) &&

            (sl->cbp & 0x30)) {

            uint8_t *dest[2] = { dest_cb, dest_cr };

            if (transform_bypass) {

                if (IS_INTRA(mb_type) && h->sps.profile_idc == 244 &&

                    (sl->chroma_pred_mode == VERT_PRED8x8 ||

                     sl->chroma_pred_mode == HOR_PRED8x8)) {

                    h->hpc.pred8x8_add[sl->chroma_pred_mode](dest[0],

                                                            block_offset + 16,

                                                            sl->mb + (16 * 16 * 1 << PIXEL_SHIFT),

                                                            uvlinesize);

                    h->hpc.pred8x8_add[sl->chroma_pred_mode](dest[1],

                                                            block_offset + 32,

                                                            sl->mb + (16 * 16 * 2 << PIXEL_SHIFT),

                                                            uvlinesize);

                } else {

                    idct_add = h->h264dsp.h264_add_pixels4_clear;

                    for (j = 1; j < 3; j++) {

                        for (i = j * 16; i < j * 16 + 4; i++)

                            if (sl->non_zero_count_cache[scan8[i]] ||

                                dctcoef_get(sl->mb, PIXEL_SHIFT, i * 16))

                                idct_add(dest[j - 1] + block_offset[i],

                                         sl->mb + (i * 16 << PIXEL_SHIFT),

                                         uvlinesize);

                        if (chroma422) {

                            for (i = j * 16 + 4; i < j * 16 + 8; i++)

                                if (sl->non_zero_count_cache[scan8[i + 4]] ||

                                    dctcoef_get(sl->mb, PIXEL_SHIFT, i * 16))

                                    idct_add(dest[j - 1] + block_offset[i + 4],

                                             sl->mb + (i * 16 << PIXEL_SHIFT),

                                             uvlinesize);

                        }

                    }

                }

            } else {

                if (is_h264) {

                    int qp[2];

                    if (chroma422) {

                        qp[0] = sl->chroma_qp[0] + 3;

                        qp[1] = sl->chroma_qp[1] + 3;

                    } else {

                        qp[0] = sl->chroma_qp[0];

                        qp[1] = sl->chroma_qp[1];

                    }

                    if (sl->non_zero_count_cache[scan8[CHROMA_DC_BLOCK_INDEX + 0]])

                        h->h264dsp.h264_chroma_dc_dequant_idct(sl->mb + (16 * 16 * 1 << PIXEL_SHIFT),

                                                               h->dequant4_coeff[IS_INTRA(mb_type) ? 1 : 4][qp[0]][0]);

                    if (sl->non_zero_count_cache[scan8[CHROMA_DC_BLOCK_INDEX + 1]])

                        h->h264dsp.h264_chroma_dc_dequant_idct(sl->mb + (16 * 16 * 2 << PIXEL_SHIFT),

                                                               h->dequant4_coeff[IS_INTRA(mb_type) ? 2 : 5][qp[1]][0]);

                    h->h264dsp.h264_idct_add8(dest, block_offset,

                                              sl->mb, uvlinesize,

                                              sl->non_zero_count_cache);

                } else if (CONFIG_SVQ3_DECODER) {

                    h->h264dsp.h264_chroma_dc_dequant_idct(sl->mb + 16 * 16 * 1,

                                                           h->dequant4_coeff[IS_INTRA(mb_type) ? 1 : 4][sl->chroma_qp[0]][0]);

                    h->h264dsp.h264_chroma_dc_dequant_idct(sl->mb + 16 * 16 * 2,

                                                           h->dequant4_coeff[IS_INTRA(mb_type) ? 2 : 5][sl->chroma_qp[1]][0]);

                    for (j = 1; j < 3; j++) {

                        for (i = j * 16; i < j * 16 + 4; i++)

                            if (sl->non_zero_count_cache[scan8[i]] || sl->mb[i * 16]) {

                                uint8_t *const ptr = dest[j - 1] + block_offset[i];

                                ff_svq3_add_idct_c(ptr, sl->mb + i * 16,

                                                   uvlinesize,

                                                   ff_h264_chroma_qp[0][sl->qscale + 12] - 12, 2);

                            }

                    }

                }

            }

        }

    }

}

static int hds_write_header(AVFormatContext *s)

{

    HDSContext *c = s->priv_data;

    int ret = 0, i;

    AVOutputFormat *oformat;



    mkdir(s->filename, 0777);



    oformat = av_guess_format("flv", NULL, NULL);

    if (!oformat) {

        ret = AVERROR_MUXER_NOT_FOUND;

        goto fail;

    }



    c->streams = av_mallocz(sizeof(*c->streams) * s->nb_streams);

    if (!c->streams) {

        ret = AVERROR(ENOMEM);

        goto fail;

    }



    for (i = 0; i < s->nb_streams; i++) {

        OutputStream *os = &c->streams[c->nb_streams];

        AVFormatContext *ctx;

        AVStream *st = s->streams[i];



        if (!st->codec->bit_rate) {

            av_log(s, AV_LOG_ERROR, "No bit rate set for stream %d\n", i);

            ret = AVERROR(EINVAL);

            goto fail;

        }

        if (st->codec->codec_type == AVMEDIA_TYPE_VIDEO) {

            if (os->has_video) {

                c->nb_streams++;

                os++;

            }

            os->has_video = 1;

        } else if (st->codec->codec_type == AVMEDIA_TYPE_AUDIO) {

            if (os->has_audio) {

                c->nb_streams++;

                os++;

            }

            os->has_audio = 1;

        } else {

            av_log(s, AV_LOG_ERROR, "Unsupported stream type in stream %d\n", i);

            ret = AVERROR(EINVAL);

            goto fail;

        }

        os->bitrate += s->streams[i]->codec->bit_rate;



        if (!os->ctx) {

            os->first_stream = i;

            ctx = avformat_alloc_context();

            if (!ctx) {

                ret = AVERROR(ENOMEM);

                goto fail;

            }

            os->ctx = ctx;

            ctx->oformat = oformat;

            ctx->interrupt_callback = s->interrupt_callback;



            ctx->pb = avio_alloc_context(os->iobuf, sizeof(os->iobuf),

                                         AVIO_FLAG_WRITE, os,

                                         NULL, hds_write, NULL);

            if (!ctx->pb) {

                ret = AVERROR(ENOMEM);

                goto fail;

            }

        } else {

            ctx = os->ctx;

        }

        s->streams[i]->id = c->nb_streams;



        if (!(st = avformat_new_stream(ctx, NULL))) {

            ret = AVERROR(ENOMEM);

            goto fail;

        }

        avcodec_copy_context(st->codec, s->streams[i]->codec);

        st->sample_aspect_ratio = s->streams[i]->sample_aspect_ratio;

    }

    if (c->streams[c->nb_streams].ctx)

        c->nb_streams++;



    for (i = 0; i < c->nb_streams; i++) {

        OutputStream *os = &c->streams[i];

        int j;

        if ((ret = avformat_write_header(os->ctx, NULL)) < 0) {

             goto fail;

        }

        os->ctx_inited = 1;

        avio_flush(os->ctx->pb);

        for (j = 0; j < os->ctx->nb_streams; j++)

            s->streams[os->first_stream + j]->time_base = os->ctx->streams[j]->time_base;



        snprintf(os->temp_filename, sizeof(os->temp_filename),

                 "%s/stream%d_temp", s->filename, i);

        ret = init_file(s, os, 0);

        if (ret < 0)

            goto fail;



        if (!os->has_video && c->min_frag_duration <= 0) {

            av_log(s, AV_LOG_WARNING,

                   "No video stream in output stream %d and no min frag duration set\n", i);

            ret = AVERROR(EINVAL);

        }

        os->fragment_index = 1;

        write_abst(s, os, 0);

    }

    ret = write_manifest(s, 0);



fail:

    if (ret)

        hds_free(s);

    return ret;

}

static inline int round_sample(int64_t *sum)

{

    int sum1;

    sum1 = (int)((*sum) >> OUT_SHIFT);

    *sum &= (1<<OUT_SHIFT)-1;

    return av_clip(sum1, OUT_MIN, OUT_MAX);

}

static void render_slice(Vp3DecodeContext *s, int slice)

{

    int x, y;

    int m, n;

    int i;  /* indicates current fragment */

    int16_t *dequantizer;

    DCTELEM __align16 block[64];

    unsigned char *output_plane;

    unsigned char *last_plane;

    unsigned char *golden_plane;

    int stride;

    int motion_x = 0xdeadbeef, motion_y = 0xdeadbeef;

    int upper_motion_limit, lower_motion_limit;

    int motion_halfpel_index;

    uint8_t *motion_source;

    int plane;

    int plane_width;

    int plane_height;

    int slice_height;

    int current_macroblock_entry = slice * s->macroblock_width * 6;



    if (slice >= s->macroblock_height)

        return;



    for (plane = 0; plane < 3; plane++) {



        /* set up plane-specific parameters */

        if (plane == 0) {

            output_plane = s->current_frame.data[0];

            last_plane = s->last_frame.data[0];

            golden_plane = s->golden_frame.data[0];

            stride = s->current_frame.linesize[0];

            if (!s->flipped_image) stride = -stride;

            upper_motion_limit = 7 * s->current_frame.linesize[0];

            lower_motion_limit = s->height * s->current_frame.linesize[0] + s->width - 8;

            y = slice * FRAGMENT_PIXELS * 2;

            plane_width = s->width;

            plane_height = s->height;

            slice_height = y + FRAGMENT_PIXELS * 2;

            i = s->macroblock_fragments[current_macroblock_entry + 0];

        } else if (plane == 1) {

            output_plane = s->current_frame.data[1];

            last_plane = s->last_frame.data[1];

            golden_plane = s->golden_frame.data[1];

            stride = s->current_frame.linesize[1];

            if (!s->flipped_image) stride = -stride;

            upper_motion_limit = 7 * s->current_frame.linesize[1];

            lower_motion_limit = (s->height / 2) * s->current_frame.linesize[1] + (s->width / 2) - 8;

            y = slice * FRAGMENT_PIXELS;

            plane_width = s->width / 2;

            plane_height = s->height / 2;

            slice_height = y + FRAGMENT_PIXELS;

            i = s->macroblock_fragments[current_macroblock_entry + 4];

        } else {

            output_plane = s->current_frame.data[2];

            last_plane = s->last_frame.data[2];

            golden_plane = s->golden_frame.data[2];

            stride = s->current_frame.linesize[2];

            if (!s->flipped_image) stride = -stride;

            upper_motion_limit = 7 * s->current_frame.linesize[2];

            lower_motion_limit = (s->height / 2) * s->current_frame.linesize[2] + (s->width / 2) - 8;

            y = slice * FRAGMENT_PIXELS;

            plane_width = s->width / 2;

            plane_height = s->height / 2;

            slice_height = y + FRAGMENT_PIXELS;

            i = s->macroblock_fragments[current_macroblock_entry + 5];

        }



        if(ABS(stride) > 2048)

            return; //various tables are fixed size



        /* for each fragment row in the slice (both of them)... */

        for (; y < slice_height; y += 8) {



            /* for each fragment in a row... */

            for (x = 0; x < plane_width; x += 8, i++) {



                if ((i < 0) || (i >= s->fragment_count)) {

                    av_log(s->avctx, AV_LOG_ERROR, "  vp3:render_slice(): bad fragment number (%d)\n", i);

                    return;

                }



                /* transform if this block was coded */

                if ((s->all_fragments[i].coding_method != MODE_COPY) &&

                    !((s->avctx->flags & CODEC_FLAG_GRAY) && plane)) {



                    if ((s->all_fragments[i].coding_method == MODE_USING_GOLDEN) ||

                        (s->all_fragments[i].coding_method == MODE_GOLDEN_MV))

                        motion_source= golden_plane;

                    else 

                        motion_source= last_plane;



                    motion_source += s->all_fragments[i].first_pixel;

                    motion_halfpel_index = 0;



                    /* sort out the motion vector if this fragment is coded

                     * using a motion vector method */

                    if ((s->all_fragments[i].coding_method > MODE_INTRA) &&

                        (s->all_fragments[i].coding_method != MODE_USING_GOLDEN)) {

                        int src_x, src_y;

                        motion_x = s->all_fragments[i].motion_x;

                        motion_y = s->all_fragments[i].motion_y;

                        if(plane){

                            motion_x= (motion_x>>1) | (motion_x&1);

                            motion_y= (motion_y>>1) | (motion_y&1);

                        }



                        src_x= (motion_x>>1) + x;

                        src_y= (motion_y>>1) + y;

                        if ((motion_x == 127) || (motion_y == 127))

                            av_log(s->avctx, AV_LOG_ERROR, " help! got invalid motion vector! (%X, %X)\n", motion_x, motion_y);



                        motion_halfpel_index = motion_x & 0x01;

                        motion_source += (motion_x >> 1);



                        motion_halfpel_index |= (motion_y & 0x01) << 1;

                        motion_source += ((motion_y >> 1) * stride);



                        if(src_x<0 || src_y<0 || src_x + 9 >= plane_width || src_y + 9 >= plane_height){

                            uint8_t *temp= s->edge_emu_buffer;

                            if(stride<0) temp -= 9*stride;

                            else temp += 9*stride;



                            ff_emulated_edge_mc(temp, motion_source, stride, 9, 9, src_x, src_y, plane_width, plane_height);

                            motion_source= temp;

                        }

                    }





                    /* first, take care of copying a block from either the

                     * previous or the golden frame */

                    if (s->all_fragments[i].coding_method != MODE_INTRA) {

                        /* Note, it is possible to implement all MC cases with 

                           put_no_rnd_pixels_l2 which would look more like the 

                           VP3 source but this would be slower as 

                           put_no_rnd_pixels_tab is better optimzed */

                        if(motion_halfpel_index != 3){

                            s->dsp.put_no_rnd_pixels_tab[1][motion_halfpel_index](

                                output_plane + s->all_fragments[i].first_pixel,

                                motion_source, stride, 8);

                        }else{

                            int d= (motion_x ^ motion_y)>>31; // d is 0 if motion_x and _y have the same sign, else -1

                            s->dsp.put_no_rnd_pixels_l2[1](

                                output_plane + s->all_fragments[i].first_pixel,

                                motion_source - d, 

                                motion_source + stride + 1 + d, 

                                stride, 8);

                        }

                        dequantizer = s->inter_dequant;

                    }else{

                        if (plane == 0)

                            dequantizer = s->intra_y_dequant;

                        else

                            dequantizer = s->intra_c_dequant;

                    }



                    /* dequantize the DCT coefficients */

                    debug_idct("fragment %d, coding mode %d, DC = %d, dequant = %d:\n", 

                        i, s->all_fragments[i].coding_method, 

                        DC_COEFF(i), dequantizer[0]);



                    if(s->avctx->idct_algo==FF_IDCT_VP3){

                        Coeff *coeff= s->coeffs + i;

                        memset(block, 0, sizeof(block));

                        while(coeff->next){

                            block[coeff->index]= coeff->coeff * dequantizer[coeff->index];

                            coeff= coeff->next;

                        }

                    }else{

                        Coeff *coeff= s->coeffs + i;

                        memset(block, 0, sizeof(block));

                        while(coeff->next){

                            block[coeff->index]= (coeff->coeff * dequantizer[coeff->index] + 2)>>2;

                            coeff= coeff->next;

                        }

                    }



                    /* invert DCT and place (or add) in final output */



                    if (s->all_fragments[i].coding_method == MODE_INTRA) {

                        if(s->avctx->idct_algo!=FF_IDCT_VP3)

                            block[0] += 128<<3;

                        s->dsp.idct_put(

                            output_plane + s->all_fragments[i].first_pixel,

                            stride,

                            block);

                    } else {

                        s->dsp.idct_add(

                            output_plane + s->all_fragments[i].first_pixel,

                            stride,

                            block);

                    }



                    debug_idct("block after idct_%s():\n",

                        (s->all_fragments[i].coding_method == MODE_INTRA)?

                        "put" : "add");

                    for (m = 0; m < 8; m++) {

                        for (n = 0; n < 8; n++) {

                            debug_idct(" %3d", *(output_plane + 

                                s->all_fragments[i].first_pixel + (m * stride + n)));

                        }

                        debug_idct("\n");

                    }

                    debug_idct("\n");



                } else {



                    /* copy directly from the previous frame */

                    s->dsp.put_pixels_tab[1][0](

                        output_plane + s->all_fragments[i].first_pixel,

                        last_plane + s->all_fragments[i].first_pixel,

                        stride, 8);



                }

            }

        }

    }



    /* future loop filter logic goes here... */

    /* algorithm: 

     *   if (slice != 0) 

     *     run filter on 1st row of Y slice

     *     run filter on U slice

     *     run filter on V slice

     *   run filter on 2nd row of Y slice

     */



     /* this looks like a good place for slice dispatch... */

     /* algorithm:

      *   if (slice > 0)

      *     dispatch (slice - 1);

      *   if (slice == s->macroblock_height - 1)

      *     dispatch (slice);  // handle last slice

      */



    emms_c();

}

static void bastardized_rice_decompress(ALACContext *alac,

                                 int32_t *output_buffer,

                                 int output_size,

                                 int readsamplesize, /* arg_10 */

                                 int rice_initialhistory, /* arg424->b */

                                 int rice_kmodifier, /* arg424->d */

                                 int rice_historymult, /* arg424->c */

                                 int rice_kmodifier_mask /* arg424->e */

        )

{

    int output_count;

    unsigned int history = rice_initialhistory;

    int sign_modifier = 0;



    for (output_count = 0; output_count < output_size; output_count++) {

        int32_t x;

        int32_t x_modified;

        int32_t final_val;



        /* read x - number of 1s before 0 represent the rice */

        x = get_unary_0_9(&alac->gb);



        if (x > 8) { /* RICE THRESHOLD */

            /* use alternative encoding */

            x = get_bits(&alac->gb, readsamplesize);

        } else {

            /* standard rice encoding */

            int extrabits;

            int k; /* size of extra bits */



            /* read k, that is bits as is */

            k = 31 - count_leading_zeros((history >> 9) + 3);



            if (k >= rice_kmodifier)

                k = rice_kmodifier;



            if (k != 1) {

                extrabits = show_bits(&alac->gb, k);



                /* multiply x by 2^k - 1, as part of their strange algorithm */

                x = (x << k) - x;



                if (extrabits > 1) {

                    x += extrabits - 1;

                    skip_bits(&alac->gb, k);

                } else

                    skip_bits(&alac->gb, k - 1);

            }

        }



        x_modified = sign_modifier + x;

        final_val = (x_modified + 1) / 2;

        if (x_modified & 1) final_val *= -1;



        output_buffer[output_count] = final_val;



        sign_modifier = 0;



        /* now update the history */

        history += x_modified * rice_historymult

                   - ((history * rice_historymult) >> 9);



        if (x_modified > 0xffff)

            history = 0xffff;



        /* special case: there may be compressed blocks of 0 */

        if ((history < 128) && (output_count+1 < output_size)) {

            int block_size;



            sign_modifier = 1;



            x = get_unary_0_9(&alac->gb);



            if (x > 8) {

                block_size = get_bits(&alac->gb, 16);

            } else {

                int k;

                int extrabits;



                k = count_leading_zeros(history) + ((history + 16) >> 6 /* / 64 */) - 24;



                extrabits = show_bits(&alac->gb, k);



                block_size = (((1 << k) - 1) & rice_kmodifier_mask) * x

                           + extrabits - 1;



                if (extrabits < 2) {

                    x = 1 - extrabits;

                    block_size += x;

                    skip_bits(&alac->gb, k - 1);

                } else {

                    skip_bits(&alac->gb, k);

                }

            }



            if (block_size > 0) {

                memset(&output_buffer[output_count+1], 0, block_size * 4);

                output_count += block_size;

            }



            if (block_size > 0xffff)

                sign_modifier = 0;



            history = 0;

        }

    }

}

static av_cold int vc2_encode_frame(AVCodecContext *avctx, AVPacket *avpkt,

                                      const AVFrame *frame, int *got_packet_ptr)

{

    int ret;

    int max_frame_bytes, sig_size = 256;

    VC2EncContext *s = avctx->priv_data;

    const char aux_data[] = LIBAVCODEC_IDENT;

    const int aux_data_size = sizeof(aux_data);

    const int header_size = 100 + aux_data_size;

    int64_t r_bitrate = avctx->bit_rate >> (s->interlaced);



    s->avctx = avctx;

    s->size_scaler = 1;

    s->prefix_bytes = 0;

    s->last_parse_code = 0;

    s->next_parse_offset = 0;



    /* Rate control */

    max_frame_bytes = (av_rescale(r_bitrate, s->avctx->time_base.num,

                                  s->avctx->time_base.den) >> 3) - header_size;



    /* Find an appropriate size scaler */

    while (sig_size > 255) {

        s->slice_max_bytes = FFALIGN(av_rescale(max_frame_bytes, 1,

                                     s->num_x*s->num_y), s->size_scaler);

        s->slice_max_bytes += 4 + s->prefix_bytes;

        sig_size = s->slice_max_bytes/s->size_scaler; /* Signalled slize size */

        s->size_scaler <<= 1;

    }



    s->slice_min_bytes = s->slice_max_bytes - s->slice_max_bytes*(s->tolerance/100.0f);



    ret = ff_alloc_packet2(avctx, avpkt, max_frame_bytes*3, 0);

    if (ret < 0) {

        av_log(avctx, AV_LOG_ERROR, "Error getting output packet.\n");

        return ret;

    } else {

        init_put_bits(&s->pb, avpkt->data, avpkt->size);

    }



    encode_frame(s, frame, aux_data, s->interlaced);

    if (s->interlaced)

        encode_frame(s, frame, NULL, 2);



    flush_put_bits(&s->pb);

    avpkt->size = put_bits_count(&s->pb) >> 3;



    *got_packet_ptr = 1;



    return 0;

}

