static av_always_inline void encode_mb_internal(MpegEncContext *s,

                                                int motion_x, int motion_y,

                                                int mb_block_height,

                                                int mb_block_count)

{

    int16_t weight[8][64];

    int16_t orig[8][64];

    const int mb_x = s->mb_x;

    const int mb_y = s->mb_y;

    int i;

    int skip_dct[8];

    int dct_offset = s->linesize * 8; // default for progressive frames

    uint8_t *ptr_y, *ptr_cb, *ptr_cr;

    ptrdiff_t wrap_y, wrap_c;



    for (i = 0; i < mb_block_count; i++)

        skip_dct[i] = s->skipdct;



    if (s->adaptive_quant) {

        const int last_qp = s->qscale;

        const int mb_xy = mb_x + mb_y * s->mb_stride;



        s->lambda = s->lambda_table[mb_xy];

        update_qscale(s);



        if (!(s->mpv_flags & FF_MPV_FLAG_QP_RD)) {

            s->qscale = s->current_picture_ptr->qscale_table[mb_xy];

            s->dquant = s->qscale - last_qp;



            if (s->out_format == FMT_H263) {

                s->dquant = av_clip(s->dquant, -2, 2);



                if (s->codec_id == AV_CODEC_ID_MPEG4) {

                    if (!s->mb_intra) {

                        if (s->pict_type == AV_PICTURE_TYPE_B) {

                            if (s->dquant & 1 || s->mv_dir & MV_DIRECT)

                                s->dquant = 0;

                        }

                        if (s->mv_type == MV_TYPE_8X8)

                            s->dquant = 0;

                    }

                }

            }

        }

        ff_set_qscale(s, last_qp + s->dquant);

    } else if (s->mpv_flags & FF_MPV_FLAG_QP_RD)

        ff_set_qscale(s, s->qscale + s->dquant);



    wrap_y = s->linesize;

    wrap_c = s->uvlinesize;

    ptr_y  = s->new_picture.f.data[0] +

             (mb_y * 16 * wrap_y)              + mb_x * 16;

    ptr_cb = s->new_picture.f.data[1] +

             (mb_y * mb_block_height * wrap_c) + mb_x * 8;

    ptr_cr = s->new_picture.f.data[2] +

             (mb_y * mb_block_height * wrap_c) + mb_x * 8;



    if (mb_x * 16 + 16 > s->width || mb_y * 16 + 16 > s->height) {

        uint8_t *ebuf = s->edge_emu_buffer + 32;

        s->vdsp.emulated_edge_mc(ebuf, ptr_y,

                                 wrap_y, wrap_y,

                                 16, 16, mb_x * 16, mb_y * 16,

                                 s->width, s->height);

        ptr_y = ebuf;

        s->vdsp.emulated_edge_mc(ebuf + 18 * wrap_y, ptr_cb,

                                 wrap_c, wrap_c,

                                 8, mb_block_height, mb_x * 8, mb_y * 8,

                                 s->width >> 1, s->height >> 1);

        ptr_cb = ebuf + 18 * wrap_y;

        s->vdsp.emulated_edge_mc(ebuf + 18 * wrap_y + 8, ptr_cr,

                                 wrap_c, wrap_c,

                                 8, mb_block_height, mb_x * 8, mb_y * 8,

                                 s->width >> 1, s->height >> 1);

        ptr_cr = ebuf + 18 * wrap_y + 8;

    }



    if (s->mb_intra) {

        if (s->flags & CODEC_FLAG_INTERLACED_DCT) {

            int progressive_score, interlaced_score;



            s->interlaced_dct = 0;

            progressive_score = s->dsp.ildct_cmp[4](s, ptr_y,

                                                    NULL, wrap_y, 8) +

                                s->dsp.ildct_cmp[4](s, ptr_y + wrap_y * 8,

                                                    NULL, wrap_y, 8) - 400;



            if (progressive_score > 0) {

                interlaced_score = s->dsp.ildct_cmp[4](s, ptr_y,

                                                       NULL, wrap_y * 2, 8) +

                                   s->dsp.ildct_cmp[4](s, ptr_y + wrap_y,

                                                       NULL, wrap_y * 2, 8);

                if (progressive_score > interlaced_score) {

                    s->interlaced_dct = 1;



                    dct_offset = wrap_y;

                    wrap_y <<= 1;

                    if (s->chroma_format == CHROMA_422)

                        wrap_c <<= 1;

                }

            }

        }



        s->dsp.get_pixels(s->block[0], ptr_y                  , wrap_y);

        s->dsp.get_pixels(s->block[1], ptr_y              + 8 , wrap_y);

        s->dsp.get_pixels(s->block[2], ptr_y + dct_offset     , wrap_y);

        s->dsp.get_pixels(s->block[3], ptr_y + dct_offset + 8 , wrap_y);



        if (s->flags & CODEC_FLAG_GRAY) {

            skip_dct[4] = 1;

            skip_dct[5] = 1;

        } else {

            s->dsp.get_pixels(s->block[4], ptr_cb, wrap_c);

            s->dsp.get_pixels(s->block[5], ptr_cr, wrap_c);

            if (!s->chroma_y_shift) { /* 422 */

                s->dsp.get_pixels(s->block[6],

                                  ptr_cb + (dct_offset >> 1), wrap_c);

                s->dsp.get_pixels(s->block[7],

                                  ptr_cr + (dct_offset >> 1), wrap_c);

            }

        }

    } else {

        op_pixels_func (*op_pix)[4];

        qpel_mc_func (*op_qpix)[16];

        uint8_t *dest_y, *dest_cb, *dest_cr;



        dest_y  = s->dest[0];

        dest_cb = s->dest[1];

        dest_cr = s->dest[2];



        if ((!s->no_rounding) || s->pict_type == AV_PICTURE_TYPE_B) {

            op_pix  = s->hdsp.put_pixels_tab;

            op_qpix = s->dsp.put_qpel_pixels_tab;

        } else {

            op_pix  = s->hdsp.put_no_rnd_pixels_tab;

            op_qpix = s->dsp.put_no_rnd_qpel_pixels_tab;

        }



        if (s->mv_dir & MV_DIR_FORWARD) {

            ff_MPV_motion(s, dest_y, dest_cb, dest_cr, 0,

                          s->last_picture.f.data,

                          op_pix, op_qpix);

            op_pix  = s->hdsp.avg_pixels_tab;

            op_qpix = s->dsp.avg_qpel_pixels_tab;

        }

        if (s->mv_dir & MV_DIR_BACKWARD) {

            ff_MPV_motion(s, dest_y, dest_cb, dest_cr, 1,

                          s->next_picture.f.data,

                          op_pix, op_qpix);

        }



        if (s->flags & CODEC_FLAG_INTERLACED_DCT) {

            int progressive_score, interlaced_score;



            s->interlaced_dct = 0;

            progressive_score = s->dsp.ildct_cmp[0](s, dest_y,

                                                    ptr_y,              wrap_y,

                                                    8) +

                                s->dsp.ildct_cmp[0](s, dest_y + wrap_y * 8,

                                                    ptr_y + wrap_y * 8, wrap_y,

                                                    8) - 400;



            if (s->avctx->ildct_cmp == FF_CMP_VSSE)

                progressive_score -= 400;



            if (progressive_score > 0) {

                interlaced_score = s->dsp.ildct_cmp[0](s, dest_y,

                                                       ptr_y,

                                                       wrap_y * 2, 8) +

                                   s->dsp.ildct_cmp[0](s, dest_y + wrap_y,

                                                       ptr_y + wrap_y,

                                                       wrap_y * 2, 8);



                if (progressive_score > interlaced_score) {

                    s->interlaced_dct = 1;



                    dct_offset = wrap_y;

                    wrap_y <<= 1;

                    if (s->chroma_format == CHROMA_422)

                        wrap_c <<= 1;

                }

            }

        }



        s->dsp.diff_pixels(s->block[0], ptr_y, dest_y, wrap_y);

        s->dsp.diff_pixels(s->block[1], ptr_y + 8, dest_y + 8, wrap_y);

        s->dsp.diff_pixels(s->block[2], ptr_y + dct_offset,

                           dest_y + dct_offset, wrap_y);

        s->dsp.diff_pixels(s->block[3], ptr_y + dct_offset + 8,

                           dest_y + dct_offset + 8, wrap_y);



        if (s->flags & CODEC_FLAG_GRAY) {

            skip_dct[4] = 1;

            skip_dct[5] = 1;

        } else {

            s->dsp.diff_pixels(s->block[4], ptr_cb, dest_cb, wrap_c);

            s->dsp.diff_pixels(s->block[5], ptr_cr, dest_cr, wrap_c);

            if (!s->chroma_y_shift) { /* 422 */

                s->dsp.diff_pixels(s->block[6], ptr_cb + (dct_offset >> 1),

                                   dest_cb + (dct_offset >> 1), wrap_c);

                s->dsp.diff_pixels(s->block[7], ptr_cr + (dct_offset >> 1),

                                   dest_cr + (dct_offset >> 1), wrap_c);

            }

        }

        /* pre quantization */

        if (s->current_picture.mc_mb_var[s->mb_stride * mb_y + mb_x] <

                2 * s->qscale * s->qscale) {

            // FIXME optimize

            if (s->dsp.sad[1](NULL, ptr_y , dest_y,

                              wrap_y, 8) < 20 * s->qscale)

                skip_dct[0] = 1;

            if (s->dsp.sad[1](NULL, ptr_y + 8,

                              dest_y + 8, wrap_y, 8) < 20 * s->qscale)

                skip_dct[1] = 1;

            if (s->dsp.sad[1](NULL, ptr_y + dct_offset,

                              dest_y + dct_offset, wrap_y, 8) < 20 * s->qscale)

                skip_dct[2] = 1;

            if (s->dsp.sad[1](NULL, ptr_y + dct_offset + 8,

                              dest_y + dct_offset + 8,

                              wrap_y, 8) < 20 * s->qscale)

                skip_dct[3] = 1;

            if (s->dsp.sad[1](NULL, ptr_cb, dest_cb,

                              wrap_c, 8) < 20 * s->qscale)

                skip_dct[4] = 1;

            if (s->dsp.sad[1](NULL, ptr_cr, dest_cr,

                              wrap_c, 8) < 20 * s->qscale)

                skip_dct[5] = 1;

            if (!s->chroma_y_shift) { /* 422 */

                if (s->dsp.sad[1](NULL, ptr_cb + (dct_offset >> 1),

                                  dest_cb + (dct_offset >> 1),

                                  wrap_c, 8) < 20 * s->qscale)

                    skip_dct[6] = 1;

                if (s->dsp.sad[1](NULL, ptr_cr + (dct_offset >> 1),

                                  dest_cr + (dct_offset >> 1),

                                  wrap_c, 8) < 20 * s->qscale)

                    skip_dct[7] = 1;

            }

        }

    }



    if (s->quantizer_noise_shaping) {

        if (!skip_dct[0])

            get_visual_weight(weight[0], ptr_y                 , wrap_y);

        if (!skip_dct[1])

            get_visual_weight(weight[1], ptr_y              + 8, wrap_y);

        if (!skip_dct[2])

            get_visual_weight(weight[2], ptr_y + dct_offset    , wrap_y);

        if (!skip_dct[3])

            get_visual_weight(weight[3], ptr_y + dct_offset + 8, wrap_y);

        if (!skip_dct[4])

            get_visual_weight(weight[4], ptr_cb                , wrap_c);

        if (!skip_dct[5])

            get_visual_weight(weight[5], ptr_cr                , wrap_c);

        if (!s->chroma_y_shift) { /* 422 */

            if (!skip_dct[6])

                get_visual_weight(weight[6], ptr_cb + (dct_offset >> 1),

                                  wrap_c);

            if (!skip_dct[7])

                get_visual_weight(weight[7], ptr_cr + (dct_offset >> 1),

                                  wrap_c);

        }

        memcpy(orig[0], s->block[0], sizeof(int16_t) * 64 * mb_block_count);

    }



    /* DCT & quantize */

    assert(s->out_format != FMT_MJPEG || s->qscale == 8);

    {

        for (i = 0; i < mb_block_count; i++) {

            if (!skip_dct[i]) {

                int overflow;

                s->block_last_index[i] = s->dct_quantize(s, s->block[i], i, s->qscale, &overflow);

                // FIXME we could decide to change to quantizer instead of

                // clipping

                // JS: I don't think that would be a good idea it could lower

                //     quality instead of improve it. Just INTRADC clipping

                //     deserves changes in quantizer

                if (overflow)

                    clip_coeffs(s, s->block[i], s->block_last_index[i]);

            } else

                s->block_last_index[i] = -1;

        }

        if (s->quantizer_noise_shaping) {

            for (i = 0; i < mb_block_count; i++) {

                if (!skip_dct[i]) {

                    s->block_last_index[i] =

                        dct_quantize_refine(s, s->block[i], weight[i],

                                            orig[i], i, s->qscale);

                }

            }

        }



        if (s->luma_elim_threshold && !s->mb_intra)

            for (i = 0; i < 4; i++)

                dct_single_coeff_elimination(s, i, s->luma_elim_threshold);

        if (s->chroma_elim_threshold && !s->mb_intra)

            for (i = 4; i < mb_block_count; i++)

                dct_single_coeff_elimination(s, i, s->chroma_elim_threshold);



        if (s->mpv_flags & FF_MPV_FLAG_CBP_RD) {

            for (i = 0; i < mb_block_count; i++) {

                if (s->block_last_index[i] == -1)

                    s->coded_score[i] = INT_MAX / 256;

            }

        }

    }



    if ((s->flags & CODEC_FLAG_GRAY) && s->mb_intra) {

        s->block_last_index[4] =

        s->block_last_index[5] = 0;

        s->block[4][0] =

        s->block[5][0] = (1024 + s->c_dc_scale / 2) / s->c_dc_scale;

    }



    // non c quantize code returns incorrect block_last_index FIXME

    if (s->alternate_scan && s->dct_quantize != ff_dct_quantize_c) {

        for (i = 0; i < mb_block_count; i++) {

            int j;

            if (s->block_last_index[i] > 0) {

                for (j = 63; j > 0; j--) {

                    if (s->block[i][s->intra_scantable.permutated[j]])

                        break;

                }

                s->block_last_index[i] = j;

            }

        }

    }



    /* huffman encode */

    switch(s->codec_id){ //FIXME funct ptr could be slightly faster

    case AV_CODEC_ID_MPEG1VIDEO:

    case AV_CODEC_ID_MPEG2VIDEO:

        if (CONFIG_MPEG1VIDEO_ENCODER || CONFIG_MPEG2VIDEO_ENCODER)

            ff_mpeg1_encode_mb(s, s->block, motion_x, motion_y);

        break;

    case AV_CODEC_ID_MPEG4:

        if (CONFIG_MPEG4_ENCODER)

            ff_mpeg4_encode_mb(s, s->block, motion_x, motion_y);

        break;

    case AV_CODEC_ID_MSMPEG4V2:

    case AV_CODEC_ID_MSMPEG4V3:

    case AV_CODEC_ID_WMV1:

        if (CONFIG_MSMPEG4_ENCODER)

            ff_msmpeg4_encode_mb(s, s->block, motion_x, motion_y);

        break;

    case AV_CODEC_ID_WMV2:

        if (CONFIG_WMV2_ENCODER)

            ff_wmv2_encode_mb(s, s->block, motion_x, motion_y);

        break;

    case AV_CODEC_ID_H261:

        if (CONFIG_H261_ENCODER)

            ff_h261_encode_mb(s, s->block, motion_x, motion_y);

        break;

    case AV_CODEC_ID_H263:

    case AV_CODEC_ID_H263P:

    case AV_CODEC_ID_FLV1:

    case AV_CODEC_ID_RV10:

    case AV_CODEC_ID_RV20:

        if (CONFIG_H263_ENCODER)

            ff_h263_encode_mb(s, s->block, motion_x, motion_y);

        break;

    case AV_CODEC_ID_MJPEG:

        if (CONFIG_MJPEG_ENCODER)

            ff_mjpeg_encode_mb(s, s->block);

        break;

    default:

        assert(0);

    }

}

void av_close_input_file(AVFormatContext *s)

{

    int i;



    if (s->iformat->read_close)

        s->iformat->read_close(s);

    for(i=0;i<s->nb_streams;i++) {

        av_free(s->streams[i]);

    }

    if (s->packet_buffer) {

        AVPacketList *p, *p1;

        p = s->packet_buffer;

        while (p != NULL) {

            p1 = p->next;

            av_free_packet(&p->pkt);

            av_free(p);

            p = p1;

        }

        s->packet_buffer = NULL;

    }

    if (!(s->iformat->flags & AVFMT_NOFILE)) {

        url_fclose(&s->pb);

    }

    av_free(s->priv_data);

    av_free(s);

}

static inline void RENAME(rgb32to24)(const uint8_t *src,uint8_t *dst,long src_size)

{

  uint8_t *dest = dst;

  const uint8_t *s = src;

  const uint8_t *end;

#ifdef HAVE_MMX

  const uint8_t *mm_end;

#endif

  end = s + src_size;

#ifdef HAVE_MMX

  __asm __volatile(PREFETCH"	%0"::"m"(*s):"memory");

  mm_end = end - 31;

  while(s < mm_end)

  {

    __asm __volatile(

	PREFETCH"	32%1\n\t"

	"movq	%1, %%mm0\n\t"

	"movq	8%1, %%mm1\n\t"

	"movq	16%1, %%mm4\n\t"

	"movq	24%1, %%mm5\n\t"

	"movq	%%mm0, %%mm2\n\t"

	"movq	%%mm1, %%mm3\n\t"

	"movq	%%mm4, %%mm6\n\t"

	"movq	%%mm5, %%mm7\n\t"

	"psrlq	$8, %%mm2\n\t"

	"psrlq	$8, %%mm3\n\t"

	"psrlq	$8, %%mm6\n\t"

	"psrlq	$8, %%mm7\n\t"

	"pand	%2, %%mm0\n\t"

	"pand	%2, %%mm1\n\t"

	"pand	%2, %%mm4\n\t"

	"pand	%2, %%mm5\n\t"

	"pand	%3, %%mm2\n\t"

	"pand	%3, %%mm3\n\t"

	"pand	%3, %%mm6\n\t"

	"pand	%3, %%mm7\n\t"

	"por	%%mm2, %%mm0\n\t"

	"por	%%mm3, %%mm1\n\t"

	"por	%%mm6, %%mm4\n\t"

	"por	%%mm7, %%mm5\n\t"



	"movq	%%mm1, %%mm2\n\t"

	"movq	%%mm4, %%mm3\n\t"

	"psllq	$48, %%mm2\n\t"

	"psllq	$32, %%mm3\n\t"

	"pand	%4, %%mm2\n\t"

	"pand	%5, %%mm3\n\t"

	"por	%%mm2, %%mm0\n\t"

	"psrlq	$16, %%mm1\n\t"

	"psrlq	$32, %%mm4\n\t"

	"psllq	$16, %%mm5\n\t"

	"por	%%mm3, %%mm1\n\t"

	"pand	%6, %%mm5\n\t"

	"por	%%mm5, %%mm4\n\t"



	MOVNTQ"	%%mm0, %0\n\t"

	MOVNTQ"	%%mm1, 8%0\n\t"

	MOVNTQ"	%%mm4, 16%0"

	:"=m"(*dest)

	:"m"(*s),"m"(mask24l),

	 "m"(mask24h),"m"(mask24hh),"m"(mask24hhh),"m"(mask24hhhh)

	:"memory");

    dest += 24;

    s += 32;

  }

  __asm __volatile(SFENCE:::"memory");

  __asm __volatile(EMMS:::"memory");

#endif

  while(s < end)

  {

#ifdef WORDS_BIGENDIAN

    /* RGB32 (= A,B,G,R) -> RGB24 (= R,G,B) */

    s++;

    dest[2] = *s++;

    dest[1] = *s++;

    dest[0] = *s++;

    dest += 3;

#else

    *dest++ = *s++;

    *dest++ = *s++;

    *dest++ = *s++;

    s++;

#endif

  }

}

static int vqf_read_seek(AVFormatContext *s,

                         int stream_index, int64_t timestamp, int flags)

{

    VqfContext *c = s->priv_data;

    AVStream *st;

    int ret;

    int64_t pos;



    st = s->streams[stream_index];

    pos = av_rescale_rnd(timestamp * st->codec->bit_rate,

                         st->time_base.num,

                         st->time_base.den * (int64_t)c->frame_bit_len,

                         (flags & AVSEEK_FLAG_BACKWARD) ?

                                                   AV_ROUND_DOWN : AV_ROUND_UP);

    pos *= c->frame_bit_len;



    st->cur_dts = av_rescale(pos, st->time_base.den,

                             st->codec->bit_rate * (int64_t)st->time_base.num);



    if ((ret = avio_seek(s->pb, ((pos-7) >> 3) + s->internal->data_offset, SEEK_SET)) < 0)

        return ret;



    c->remaining_bits = -7 - ((pos-7)&7);

    return 0;

}

static void copy_context_reset(AVCodecContext *avctx)
{
    av_opt_free(avctx);
    av_freep(&avctx->rc_override);
    av_freep(&avctx->intra_matrix);
    av_freep(&avctx->inter_matrix);
    av_freep(&avctx->extradata);
    av_freep(&avctx->subtitle_header);
    av_buffer_unref(&avctx->hw_frames_ctx);
    avctx->subtitle_header_size = 0;
    avctx->extradata_size = 0;
}

int ff_audio_mix_init(AVAudioResampleContext *avr)

{

    int ret;



    if (avr->internal_sample_fmt != AV_SAMPLE_FMT_S16P &&

        avr->internal_sample_fmt != AV_SAMPLE_FMT_FLTP) {

        av_log(avr, AV_LOG_ERROR, "Unsupported internal format for "

               "mixing: %s\n",

               av_get_sample_fmt_name(avr->internal_sample_fmt));

        return AVERROR(EINVAL);

    }



    /* build matrix if the user did not already set one */

    if (!avr->am->matrix) {

        int i, j;

        char in_layout_name[128];

        char out_layout_name[128];

        double *matrix_dbl = av_mallocz(avr->out_channels * avr->in_channels *

                                        sizeof(*matrix_dbl));

        if (!matrix_dbl)

            return AVERROR(ENOMEM);



        ret = avresample_build_matrix(avr->in_channel_layout,

                                      avr->out_channel_layout,

                                      avr->center_mix_level,

                                      avr->surround_mix_level,

                                      avr->lfe_mix_level, 1, matrix_dbl,

                                      avr->in_channels,

                                      avr->matrix_encoding);

        if (ret < 0) {

            av_free(matrix_dbl);

            return ret;

        }



        av_get_channel_layout_string(in_layout_name, sizeof(in_layout_name),

                                     avr->in_channels, avr->in_channel_layout);

        av_get_channel_layout_string(out_layout_name, sizeof(out_layout_name),

                                     avr->out_channels, avr->out_channel_layout);

        av_log(avr, AV_LOG_DEBUG, "audio_mix: %s to %s\n",

               in_layout_name, out_layout_name);

        for (i = 0; i < avr->out_channels; i++) {

            for (j = 0; j < avr->in_channels; j++) {

                av_log(avr, AV_LOG_DEBUG, "  %0.3f ",

                       matrix_dbl[i * avr->in_channels + j]);

            }

            av_log(avr, AV_LOG_DEBUG, "\n");

        }



        ret = avresample_set_matrix(avr, matrix_dbl, avr->in_channels);

        if (ret < 0) {

            av_free(matrix_dbl);

            return ret;

        }

        av_free(matrix_dbl);

    }



    avr->am->fmt          = avr->internal_sample_fmt;

    avr->am->coeff_type   = avr->mix_coeff_type;

    avr->am->in_layout    = avr->in_channel_layout;

    avr->am->out_layout   = avr->out_channel_layout;

    avr->am->in_channels  = avr->in_channels;

    avr->am->out_channels = avr->out_channels;



    ret = mix_function_init(avr->am);

    if (ret < 0)

        return ret;



    return 0;

}

static inline void RENAME(rgb16ToY)(uint8_t *dst, uint8_t *src, int width)

{

	int i;

	for(i=0; i<width; i++)

	{

		int d= ((uint16_t*)src)[i];

		int r= d&0x1F;

		int g= (d>>5)&0x3F;

		int b= (d>>11)&0x1F;



		dst[i]= ((2*RY*r + GY*g + 2*BY*b)>>(RGB2YUV_SHIFT-2)) + 16;

	}

}

void palette8tobgr16(const uint8_t *src, uint8_t *dst, unsigned num_pixels, const uint8_t *palette)

{

	unsigned i;

	for(i=0; i<num_pixels; i++)

		((uint16_t *)dst)[i] = bswap_16(((uint16_t *)palette)[ src[i] ]);

}

static int vda_h264_decode_slice(AVCodecContext *avctx,

                                 const uint8_t *buffer,

                                 uint32_t size)

{

    VDAContext *vda                     = avctx->internal->hwaccel_priv_data;

    struct vda_context *vda_ctx         = avctx->hwaccel_context;

    void *tmp;



    if (!vda_ctx->decoder)

        return -1;



    tmp = av_fast_realloc(vda->bitstream,

                          &vda->allocated_size,

                          vda->bitstream_size + size + 4);

    if (!tmp)

        return AVERROR(ENOMEM);



    vda->bitstream = tmp;



    AV_WB32(vda->bitstream + vda->bitstream_size, size);

    memcpy(vda->bitstream + vda->bitstream_size + 4, buffer, size);



    vda->bitstream_size += size + 4;



    return 0;

}

static void print_tag(const char *str, unsigned int tag, int size)

{

    dprintf(NULL, "%s: tag=%c%c%c%c size=0x%x\n",

           str, tag & 0xff,

           (tag >> 8) & 0xff,

           (tag >> 16) & 0xff,

           (tag >> 24) & 0xff,

           size);

}

static void h264_loop_filter_strength_mmx2( int16_t bS[2][4][4], uint8_t nnz[40], int8_t ref[2][40], int16_t mv[2][40][2],

                                            int bidir, int edges, int step, int mask_mv0, int mask_mv1, int field ) {

    __asm__ volatile(

        "movq %0, %%mm7 \n"

        "movq %1, %%mm6 \n"

        ::"m"(ff_pb_1), "m"(ff_pb_3)

    );

    if(field)

        __asm__ volatile(

            "movq %0, %%mm6 \n"

            ::"m"(ff_pb_3_1)

        );

    __asm__ volatile(

        "movq  %%mm6, %%mm5 \n"

        "paddb %%mm5, %%mm5 \n"

    :);



    // could do a special case for dir==0 && edges==1, but it only reduces the

    // average filter time by 1.2%

    step  <<= 3;

    edges <<= 3;

    h264_loop_filter_strength_iteration_mmx2(bS, nnz, ref, mv, bidir, edges, step, mask_mv1, 1, -8,  0);

    h264_loop_filter_strength_iteration_mmx2(bS, nnz, ref, mv, bidir,    32,    8, mask_mv0, 0, -1, -1);



    __asm__ volatile(

        "movq   (%0), %%mm0 \n\t"

        "movq  8(%0), %%mm1 \n\t"

        "movq 16(%0), %%mm2 \n\t"

        "movq 24(%0), %%mm3 \n\t"

        TRANSPOSE4(%%mm0, %%mm1, %%mm2, %%mm3, %%mm4)

        "movq %%mm0,   (%0) \n\t"

        "movq %%mm3,  8(%0) \n\t"

        "movq %%mm4, 16(%0) \n\t"

        "movq %%mm2, 24(%0) \n\t"

        ::"r"(bS[0])

        :"memory"

    );

}

int avfilter_copy_frame_props(AVFilterBufferRef *dst, const AVFrame *src)

{

    dst->pts    = src->pts;

    dst->pos    = av_frame_get_pkt_pos(src);

    dst->format = src->format;



    switch (dst->type) {

    case AVMEDIA_TYPE_VIDEO:

        dst->video->w                   = src->width;

        dst->video->h                   = src->height;

        dst->video->sample_aspect_ratio = src->sample_aspect_ratio;

        dst->video->interlaced          = src->interlaced_frame;

        dst->video->top_field_first     = src->top_field_first;

        dst->video->key_frame           = src->key_frame;

        dst->video->pict_type           = src->pict_type;

        av_freep(&dst->video->qp_table);

        dst->video->qp_table_linesize = 0;

        if (src->qscale_table) {

            int qsize = src->qstride ? src->qstride * ((src->height+15)/16) : (src->width+15)/16;

            dst->video->qp_table        = av_malloc(qsize);

            if(!dst->video->qp_table)

                return AVERROR(ENOMEM);

            dst->video->qp_table_linesize       = src->qstride;


            memcpy(dst->video->qp_table, src->qscale_table, qsize);

        }

        break;

    case AVMEDIA_TYPE_AUDIO:

        dst->audio->sample_rate         = src->sample_rate;

        dst->audio->channel_layout      = src->channel_layout;

        break;

    default:

        return AVERROR(EINVAL);

    }



    return 0;

}

int ff_probe_input_buffer(ByteIOContext **pb, AVInputFormat **fmt,

                          const char *filename, void *logctx,

                          unsigned int offset, unsigned int max_probe_size)

{

    AVProbeData pd = { filename ? filename : "", NULL, -offset };

    unsigned char *buf = NULL;

    int probe_size;



    if (!max_probe_size) {

        max_probe_size = PROBE_BUF_MAX;

    } else if (max_probe_size > PROBE_BUF_MAX) {

        max_probe_size = PROBE_BUF_MAX;

    } else if (max_probe_size < PROBE_BUF_MIN) {

        return AVERROR(EINVAL);

    }



    if (offset >= max_probe_size) {

        return AVERROR(EINVAL);

    }



    for(probe_size= PROBE_BUF_MIN; probe_size<=max_probe_size && !*fmt; probe_size<<=1){

        int ret, score = probe_size < max_probe_size ? AVPROBE_SCORE_MAX/4 : 0;

        int buf_offset = (probe_size == PROBE_BUF_MIN) ? 0 : probe_size>>1;



        if (probe_size < offset) {

            continue;

        }



        /* read probe data */

        buf = av_realloc(buf, probe_size + AVPROBE_PADDING_SIZE);

        if ((ret = get_buffer(*pb, buf + buf_offset, probe_size - buf_offset)) < 0) {

            av_free(buf);

            return ret;

        }

        pd.buf_size += ret;

        pd.buf = &buf[offset];



        memset(pd.buf + pd.buf_size, 0, AVPROBE_PADDING_SIZE);



        /* guess file format */

        *fmt = av_probe_input_format2(&pd, 1, &score);

        if(*fmt){

            if(score <= AVPROBE_SCORE_MAX/4){ //this can only be true in the last iteration

                av_log(logctx, AV_LOG_WARNING, "Format detected only with low score of %d, misdetection possible!\n", score);

            }else

                av_log(logctx, AV_LOG_DEBUG, "Probed with size=%d and score=%d\n", probe_size, score);

        }

    }



    av_free(buf);

    if (url_fseek(*pb, 0, SEEK_SET) < 0) {

        url_fclose(*pb);

        if (url_fopen(pb, filename, URL_RDONLY) < 0)

            return AVERROR(EIO);

    }



    return 0;

}

static void vp8_filter_mb_row(AVCodecContext *avctx, void *tdata,

                              int jobnr, int threadnr)

{

    VP8Context *s = avctx->priv_data;

    VP8ThreadData *td = &s->thread_data[threadnr];

    int mb_x, mb_y = td->thread_mb_pos >> 16, num_jobs = s->num_jobs;

    AVFrame *curframe = s->curframe->tf.f;

    VP8Macroblock *mb;

    VP8ThreadData *prev_td, *next_td;

    uint8_t *dst[3] = {

        curframe->data[0] + 16 * mb_y * s->linesize,

        curframe->data[1] +  8 * mb_y * s->uvlinesize,

        curframe->data[2] +  8 * mb_y * s->uvlinesize

    };



    if (s->mb_layout == 1)

        mb = s->macroblocks_base + ((s->mb_width + 1) * (mb_y + 1) + 1);

    else

        mb = s->macroblocks + (s->mb_height - mb_y - 1) * 2;



    if (mb_y == 0)

        prev_td = td;

    else

        prev_td = &s->thread_data[(jobnr + num_jobs - 1) % num_jobs];

    if (mb_y == s->mb_height - 1)

        next_td = td;

    else

        next_td = &s->thread_data[(jobnr + 1) % num_jobs];



    for (mb_x = 0; mb_x < s->mb_width; mb_x++, mb++) {

        VP8FilterStrength *f = &td->filter_strength[mb_x];

        if (prev_td != td)

            check_thread_pos(td, prev_td,

                             (mb_x + 1) + (s->mb_width + 3), mb_y - 1);

        if (next_td != td)

            if (next_td != &s->thread_data[0])

                check_thread_pos(td, next_td, mb_x + 1, mb_y + 1);



        if (num_jobs == 1) {

            if (s->filter.simple)

                backup_mb_border(s->top_border[mb_x + 1], dst[0],

                                 NULL, NULL, s->linesize, 0, 1);

            else

                backup_mb_border(s->top_border[mb_x + 1], dst[0],

                                 dst[1], dst[2], s->linesize, s->uvlinesize, 0);

        }



        if (s->filter.simple)

            filter_mb_simple(s, dst[0], f, mb_x, mb_y);

        else

            filter_mb(s, dst, f, mb_x, mb_y);

        dst[0] += 16;

        dst[1] += 8;

        dst[2] += 8;



        update_pos(td, mb_y, (s->mb_width + 3) + mb_x);

    }

}

static int cllc_decode_frame(AVCodecContext *avctx, void *data,

                             int *got_picture_ptr, AVPacket *avpkt)

{

    CLLCContext *ctx = avctx->priv_data;

    AVFrame *pic = data;

    uint8_t *src = avpkt->data;

    uint32_t info_tag, info_offset;

    int data_size;

    GetBitContext gb;

    int coding_type, ret;



    /* Skip the INFO header if present */

    info_offset = 0;

    info_tag    = AV_RL32(src);

    if (info_tag == MKTAG('I', 'N', 'F', 'O')) {

        info_offset = AV_RL32(src + 4);

        if (info_offset > UINT32_MAX - 8 || info_offset + 8 > avpkt->size) {

            av_log(avctx, AV_LOG_ERROR,

                   "Invalid INFO header offset: 0x%08"PRIX32" is too large.\n",

                   info_offset);

            return AVERROR_INVALIDDATA;

        }



        info_offset += 8;

        src         += info_offset;



        av_log(avctx, AV_LOG_DEBUG, "Skipping INFO chunk.\n");

    }



    data_size = (avpkt->size - info_offset) & ~1;



    /* Make sure our bswap16'd buffer is big enough */

    av_fast_padded_malloc(&ctx->swapped_buf,

                          &ctx->swapped_buf_size, data_size);

    if (!ctx->swapped_buf) {

        av_log(avctx, AV_LOG_ERROR, "Could not allocate swapped buffer.\n");

        return AVERROR(ENOMEM);

    }



    /* bswap16 the buffer since CLLC's bitreader works in 16-bit words */

    ctx->bdsp.bswap16_buf((uint16_t *) ctx->swapped_buf, (uint16_t *) src,

                          data_size / 2);



    init_get_bits(&gb, ctx->swapped_buf, data_size * 8);



    /*

     * Read in coding type. The types are as follows:

     *

     * 0 - YUY2

     * 1 - BGR24 (Triples)

     * 2 - BGR24 (Quads)

     * 3 - BGRA

     */

    coding_type = (AV_RL32(src) >> 8) & 0xFF;

    av_log(avctx, AV_LOG_DEBUG, "Frame coding type: %d\n", coding_type);



    switch (coding_type) {

    case 0:

        avctx->pix_fmt             = AV_PIX_FMT_YUV422P;

        avctx->bits_per_raw_sample = 8;



        ret = ff_get_buffer(avctx, pic, 0);

        if (ret < 0) {

            av_log(avctx, AV_LOG_ERROR, "Could not allocate buffer.\n");

            return ret;

        }



        ret = decode_yuv_frame(ctx, &gb, pic);

        if (ret < 0)

            return ret;



        break;

    case 1:

    case 2:

        avctx->pix_fmt             = AV_PIX_FMT_RGB24;

        avctx->bits_per_raw_sample = 8;



        ret = ff_get_buffer(avctx, pic, 0);

        if (ret < 0) {

            av_log(avctx, AV_LOG_ERROR, "Could not allocate buffer.\n");

            return ret;

        }



        ret = decode_rgb24_frame(ctx, &gb, pic);

        if (ret < 0)

            return ret;



        break;

    case 3:

        avctx->pix_fmt             = AV_PIX_FMT_ARGB;

        avctx->bits_per_raw_sample = 8;



        ret = ff_get_buffer(avctx, pic, 0);

        if (ret < 0) {

            av_log(avctx, AV_LOG_ERROR, "Could not allocate buffer.\n");

            return ret;

        }



        ret = decode_argb_frame(ctx, &gb, pic);

        if (ret < 0)

            return ret;



        break;

    default:

        av_log(avctx, AV_LOG_ERROR, "Unknown coding type: %d.\n", coding_type);

        return AVERROR_INVALIDDATA;

    }



    pic->key_frame = 1;

    pic->pict_type = AV_PICTURE_TYPE_I;



    *got_picture_ptr = 1;



    return avpkt->size;

}

