int ff_alloc_packet2(AVCodecContext *avctx, AVPacket *avpkt, int size)

{

    if (size < 0 || avpkt->size < 0 || size > INT_MAX - FF_INPUT_BUFFER_PADDING_SIZE) {

        av_log(avctx, AV_LOG_ERROR, "Size %d invalid\n", size);

        return AVERROR(EINVAL);

    }



    if (avctx) {

        av_assert0(!avpkt->data || avpkt->data != avctx->internal->byte_buffer);

        if (!avpkt->data || avpkt->size < size) {

            av_fast_padded_malloc(&avctx->internal->byte_buffer, &avctx->internal->byte_buffer_size, size);

            avpkt->data = avctx->internal->byte_buffer;

            avpkt->size = avctx->internal->byte_buffer_size;

            avpkt->destruct = NULL;

        }

    }



    if (avpkt->data) {

        AVBufferRef *buf = avpkt->buf;

#if FF_API_DESTRUCT_PACKET

        void *destruct = avpkt->destruct;

#endif



        if (avpkt->size < size) {

            av_log(avctx, AV_LOG_ERROR, "User packet is too small (%d < %d)\n", avpkt->size, size);

            return AVERROR(EINVAL);

        }



        av_init_packet(avpkt);

#if FF_API_DESTRUCT_PACKET

        avpkt->destruct = destruct;

#endif

        avpkt->buf      = buf;

        avpkt->size     = size;

        return 0;

    } else {

        int ret = av_new_packet(avpkt, size);

        if (ret < 0)

            av_log(avctx, AV_LOG_ERROR, "Failed to allocate packet of size %d\n", size);

        return ret;

    }

}

static int sort_stt(FFV1Context *s, uint8_t stt[256])

{

    int i, i2, changed, print = 0;



    do {

        changed = 0;

        for (i = 12; i < 244; i++) {

            for (i2 = i + 1; i2 < 245 && i2 < i + 4; i2++) {



#define COST(old, new)                                      \

    s->rc_stat[old][0] * -log2((256 - (new)) / 256.0) +     \

    s->rc_stat[old][1] * -log2((new)         / 256.0)



#define COST2(old, new)                         \

    COST(old, new) + COST(256 - (old), 256 - (new))



                double size0 = COST2(i,  i) + COST2(i2, i2);

                double sizeX = COST2(i, i2) + COST2(i2, i);

                if (sizeX < size0 && i != 128 && i2 != 128) {

                    int j;

                    FFSWAP(int, stt[i], stt[i2]);

                    FFSWAP(int, s->rc_stat[i][0], s->rc_stat[i2][0]);

                    FFSWAP(int, s->rc_stat[i][1], s->rc_stat[i2][1]);

                    if (i != 256 - i2) {

                        FFSWAP(int, stt[256 - i], stt[256 - i2]);

                        FFSWAP(int, s->rc_stat[256 - i][0], s->rc_stat[256 - i2][0]);

                        FFSWAP(int, s->rc_stat[256 - i][1], s->rc_stat[256 - i2][1]);

                    }

                    for (j = 1; j < 256; j++) {

                        if (stt[j] == i)

                            stt[j] = i2;

                        else if (stt[j] == i2)

                            stt[j] = i;

                        if (i != 256 - i2) {

                            if (stt[256 - j] == 256 - i)

                                stt[256 - j] = 256 - i2;

                            else if (stt[256 - j] == 256 - i2)

                                stt[256 - j] = 256 - i;

                        }

                    }

                    print = changed = 1;

                }

            }

        }

    } while (changed);

    return print;

}

static void dvbsub_parse_object_segment(AVCodecContext *avctx,

                                        const uint8_t *buf, int buf_size)

{

    DVBSubContext *ctx = avctx->priv_data;



    const uint8_t *buf_end = buf + buf_size;

    const uint8_t *block;

    int object_id;

    DVBSubObject *object;

    DVBSubObjectDisplay *display;

    int top_field_len, bottom_field_len;



    int coding_method, non_modifying_color;



    object_id = AV_RB16(buf);

    buf += 2;



    object = get_object(ctx, object_id);



    if (!object)

        return;



    coding_method = ((*buf) >> 2) & 3;

    non_modifying_color = ((*buf++) >> 1) & 1;



    if (coding_method == 0) {

        top_field_len = AV_RB16(buf);

        buf += 2;

        bottom_field_len = AV_RB16(buf);

        buf += 2;



        if (buf + top_field_len + bottom_field_len > buf_end) {

            av_log(avctx, AV_LOG_ERROR, "Field data size too large\n");

            return;

        }



        for (display = object->display_list; display; display = display->object_list_next) {

            block = buf;



            dvbsub_parse_pixel_data_block(avctx, display, block, top_field_len, 0,

                                            non_modifying_color);



            if (bottom_field_len > 0)

                block = buf + top_field_len;

            else

                bottom_field_len = top_field_len;



            dvbsub_parse_pixel_data_block(avctx, display, block, bottom_field_len, 1,

                                            non_modifying_color);

        }



/*  } else if (coding_method == 1) {*/



    } else {

        av_log(avctx, AV_LOG_ERROR, "Unknown object coding %d\n", coding_method);

    }



}

static int svq1_encode_frame(AVCodecContext *avctx, AVPacket *pkt,

                             const AVFrame *pict, int *got_packet)

{

    SVQ1EncContext *const s = avctx->priv_data;

    AVFrame *const p        = avctx->coded_frame;

    int i, ret;



    if (!pkt->data &&

        (ret = av_new_packet(pkt, s->y_block_width * s->y_block_height *

                             MAX_MB_BYTES * 3 + FF_MIN_BUFFER_SIZE)) < 0) {

        av_log(avctx, AV_LOG_ERROR, "Error getting output packet.\n");

        return ret;

    }



    if (avctx->pix_fmt != AV_PIX_FMT_YUV410P) {

        av_log(avctx, AV_LOG_ERROR, "unsupported pixel format\n");

        return -1;

    }



    if (!s->current_picture->data[0]) {

        ret = ff_get_buffer(avctx, s->current_picture, 0);

        if (ret < 0)

            return ret;

    }

    if (!s->last_picture->data[0]) {

        ret = ff_get_buffer(avctx, s->last_picture, 0);

        if (ret < 0)

            return ret;

    }

    if (!s->scratchbuf) {

        s->scratchbuf = av_malloc(s->current_picture->linesize[0] * 16 * 2);

        if (!s->scratchbuf)

            return AVERROR(ENOMEM);

    }



    FFSWAP(AVFrame*, s->current_picture, s->last_picture);



    init_put_bits(&s->pb, pkt->data, pkt->size);



    p->pict_type = avctx->gop_size && avctx->frame_number % avctx->gop_size ?

                   AV_PICTURE_TYPE_P : AV_PICTURE_TYPE_I;

    p->key_frame = p->pict_type == AV_PICTURE_TYPE_I;

    p->quality   = pict->quality;



    svq1_write_header(s, p->pict_type);

    for (i = 0; i < 3; i++)

        if (svq1_encode_plane(s, i,

                              pict->data[i],

                              s->last_picture->data[i],

                              s->current_picture->data[i],

                              s->frame_width  / (i ? 4 : 1),

                              s->frame_height / (i ? 4 : 1),

                              pict->linesize[i],

                              s->current_picture->linesize[i]) < 0)

            return -1;



    // avpriv_align_put_bits(&s->pb);

    while (put_bits_count(&s->pb) & 31)

        put_bits(&s->pb, 1, 0);



    flush_put_bits(&s->pb);



    pkt->size = put_bits_count(&s->pb) / 8;

    if (p->pict_type == AV_PICTURE_TYPE_I)

        pkt->flags |= AV_PKT_FLAG_KEY;

    *got_packet = 1;



    return 0;

}

static int decode_frame(AVCodecContext *avctx, 

                        void *data, int *data_size,

                        uint8_t *buf, int buf_size)

{

    MDECContext * const a = avctx->priv_data;

    AVFrame *picture = data;

    AVFrame * const p= (AVFrame*)&a->picture;

    int i;



    /* special case for last picture */

    if (buf_size == 0) {

        return 0;

    }



    if(p->data[0])

        avctx->release_buffer(avctx, p);



    p->reference= 0;

    if(avctx->get_buffer(avctx, p) < 0){

        av_log(avctx, AV_LOG_ERROR, "get_buffer() failed\n");

        return -1;

    }

    p->pict_type= I_TYPE;

    p->key_frame= 1;

    a->last_dc[0]=

    a->last_dc[1]=

    a->last_dc[2]= 0;



    a->bitstream_buffer= av_fast_realloc(a->bitstream_buffer, &a->bitstream_buffer_size, buf_size + FF_INPUT_BUFFER_PADDING_SIZE);

    for(i=0; i<buf_size; i+=2){

        a->bitstream_buffer[i]  = buf[i+1];

        a->bitstream_buffer[i+1]= buf[i  ];

    }

    init_get_bits(&a->gb, a->bitstream_buffer, buf_size*8);



    /* skip over 4 preamble bytes in stream (typically 0xXX 0xXX 0x00 0x38) */

    skip_bits(&a->gb, 32);



    a->qscale=  get_bits(&a->gb, 16);

    a->version= get_bits(&a->gb, 16);



//    printf("qscale:%d (0x%X), version:%d (0x%X)\n", a->qscale, a->qscale, a->version, a->version);



    for(a->mb_x=0; a->mb_x<a->mb_width; a->mb_x++){

        for(a->mb_y=0; a->mb_y<a->mb_height; a->mb_y++){

            if( decode_mb(a, a->block) <0)

                return -1;



            idct_put(a, a->mb_x, a->mb_y);

        }

    }



//    p->quality= (32 + a->inv_qscale/2)/a->inv_qscale;

//    memset(p->qscale_table, p->quality, p->qstride*a->mb_height);



    *picture= *(AVFrame*)&a->picture;

    *data_size = sizeof(AVPicture);



    emms_c();



    return (get_bits_count(&a->gb)+31)/32*4;

}

