static int ape_read_header(AVFormatContext * s, AVFormatParameters * ap)

{

    AVIOContext *pb = s->pb;

    APEContext *ape = s->priv_data;

    AVStream *st;

    uint32_t tag;

    int i;

    int total_blocks;

    int64_t pts;



    /* TODO: Skip any leading junk such as id3v2 tags */

    ape->junklength = 0;



    tag = avio_rl32(pb);

    if (tag != MKTAG('M', 'A', 'C', ' '))

        return -1;



    ape->fileversion = avio_rl16(pb);



    if (ape->fileversion < APE_MIN_VERSION || ape->fileversion > APE_MAX_VERSION) {

        av_log(s, AV_LOG_ERROR, "Unsupported file version - %d.%02d\n", ape->fileversion / 1000, (ape->fileversion % 1000) / 10);

        return -1;




    if (ape->fileversion >= 3980) {

        ape->padding1             = avio_rl16(pb);

        ape->descriptorlength     = avio_rl32(pb);

        ape->headerlength         = avio_rl32(pb);

        ape->seektablelength      = avio_rl32(pb);

        ape->wavheaderlength      = avio_rl32(pb);

        ape->audiodatalength      = avio_rl32(pb);

        ape->audiodatalength_high = avio_rl32(pb);

        ape->wavtaillength        = avio_rl32(pb);

        avio_read(pb, ape->md5, 16);



        /* Skip any unknown bytes at the end of the descriptor.

           This is for future compatibility */

        if (ape->descriptorlength > 52)

            avio_seek(pb, ape->descriptorlength - 52, SEEK_CUR);



        /* Read header data */

        ape->compressiontype      = avio_rl16(pb);

        ape->formatflags          = avio_rl16(pb);

        ape->blocksperframe       = avio_rl32(pb);

        ape->finalframeblocks     = avio_rl32(pb);

        ape->totalframes          = avio_rl32(pb);

        ape->bps                  = avio_rl16(pb);

        ape->channels             = avio_rl16(pb);

        ape->samplerate           = avio_rl32(pb);

    } else {

        ape->descriptorlength = 0;

        ape->headerlength = 32;



        ape->compressiontype      = avio_rl16(pb);

        ape->formatflags          = avio_rl16(pb);

        ape->channels             = avio_rl16(pb);

        ape->samplerate           = avio_rl32(pb);

        ape->wavheaderlength      = avio_rl32(pb);

        ape->wavtaillength        = avio_rl32(pb);

        ape->totalframes          = avio_rl32(pb);

        ape->finalframeblocks     = avio_rl32(pb);



        if (ape->formatflags & MAC_FORMAT_FLAG_HAS_PEAK_LEVEL) {

            avio_seek(pb, 4, SEEK_CUR); /* Skip the peak level */

            ape->headerlength += 4;




        if (ape->formatflags & MAC_FORMAT_FLAG_HAS_SEEK_ELEMENTS) {

            ape->seektablelength = avio_rl32(pb);

            ape->headerlength += 4;

            ape->seektablelength *= sizeof(int32_t);

        } else

            ape->seektablelength = ape->totalframes * sizeof(int32_t);



        if (ape->formatflags & MAC_FORMAT_FLAG_8_BIT)

            ape->bps = 8;

        else if (ape->formatflags & MAC_FORMAT_FLAG_24_BIT)

            ape->bps = 24;

        else

            ape->bps = 16;



        if (ape->fileversion >= 3950)

            ape->blocksperframe = 73728 * 4;

        else if (ape->fileversion >= 3900 || (ape->fileversion >= 3800  && ape->compressiontype >= 4000))

            ape->blocksperframe = 73728;

        else

            ape->blocksperframe = 9216;



        /* Skip any stored wav header */

        if (!(ape->formatflags & MAC_FORMAT_FLAG_CREATE_WAV_HEADER))

            avio_seek(pb, ape->wavheaderlength, SEEK_CUR);








    if(ape->totalframes > UINT_MAX / sizeof(APEFrame)){

        av_log(s, AV_LOG_ERROR, "Too many frames: %d\n", ape->totalframes);

        return -1;


    ape->frames       = av_malloc(ape->totalframes * sizeof(APEFrame));

    if(!ape->frames)

        return AVERROR(ENOMEM);

    ape->firstframe   = ape->junklength + ape->descriptorlength + ape->headerlength + ape->seektablelength + ape->wavheaderlength;

    ape->currentframe = 0;





    ape->totalsamples = ape->finalframeblocks;

    if (ape->totalframes > 1)

        ape->totalsamples += ape->blocksperframe * (ape->totalframes - 1);



    if (ape->seektablelength > 0) {

        ape->seektable = av_malloc(ape->seektablelength);

        for (i = 0; i < ape->seektablelength / sizeof(uint32_t); i++)

            ape->seektable[i] = avio_rl32(pb);




    ape->frames[0].pos     = ape->firstframe;

    ape->frames[0].nblocks = ape->blocksperframe;

    ape->frames[0].skip    = 0;

    for (i = 1; i < ape->totalframes; i++) {

        ape->frames[i].pos      = ape->seektable[i]; //ape->frames[i-1].pos + ape->blocksperframe;

        ape->frames[i].nblocks  = ape->blocksperframe;

        ape->frames[i - 1].size = ape->frames[i].pos - ape->frames[i - 1].pos;

        ape->frames[i].skip     = (ape->frames[i].pos - ape->frames[0].pos) & 3;


    ape->frames[ape->totalframes - 1].size    = ape->finalframeblocks * 4;

    ape->frames[ape->totalframes - 1].nblocks = ape->finalframeblocks;



    for (i = 0; i < ape->totalframes; i++) {

        if(ape->frames[i].skip){

            ape->frames[i].pos  -= ape->frames[i].skip;

            ape->frames[i].size += ape->frames[i].skip;


        ape->frames[i].size = (ape->frames[i].size + 3) & ~3;






    ape_dumpinfo(s, ape);



    /* try to read APE tags */

    if (!url_is_streamed(pb)) {

        ff_ape_parse_tag(s);

        avio_seek(pb, 0, SEEK_SET);




    av_log(s, AV_LOG_DEBUG, "Decoding file - v%d.%02d, compression level %d\n", ape->fileversion / 1000, (ape->fileversion % 1000) / 10, ape->compressiontype);



    /* now we are ready: build format streams */

    st = av_new_stream(s, 0);

    if (!st)

        return -1;



    total_blocks = (ape->totalframes == 0) ? 0 : ((ape->totalframes - 1) * ape->blocksperframe) + ape->finalframeblocks;



    st->codec->codec_type      = AVMEDIA_TYPE_AUDIO;

    st->codec->codec_id        = CODEC_ID_APE;

    st->codec->codec_tag       = MKTAG('A', 'P', 'E', ' ');

    st->codec->channels        = ape->channels;

    st->codec->sample_rate     = ape->samplerate;

    st->codec->bits_per_coded_sample = ape->bps;

    st->codec->frame_size      = MAC_SUBFRAME_SIZE;



    st->nb_frames = ape->totalframes;

    st->start_time = 0;

    st->duration  = total_blocks / MAC_SUBFRAME_SIZE;

    av_set_pts_info(st, 64, MAC_SUBFRAME_SIZE, ape->samplerate);



    st->codec->extradata = av_malloc(APE_EXTRADATA_SIZE);

    st->codec->extradata_size = APE_EXTRADATA_SIZE;

    AV_WL16(st->codec->extradata + 0, ape->fileversion);

    AV_WL16(st->codec->extradata + 2, ape->compressiontype);

    AV_WL16(st->codec->extradata + 4, ape->formatflags);



    pts = 0;

    for (i = 0; i < ape->totalframes; i++) {

        ape->frames[i].pts = pts;

        av_add_index_entry(st, ape->frames[i].pos, ape->frames[i].pts, 0, 0, AVINDEX_KEYFRAME);

        pts += ape->blocksperframe / MAC_SUBFRAME_SIZE;




    return 0;

static const struct URLProtocol *url_find_protocol(const char *filename)

{

    const URLProtocol **protocols;

    char proto_str[128], proto_nested[128], *ptr;

    size_t proto_len = strspn(filename, URL_SCHEME_CHARS);

    int i;



    if (filename[proto_len] != ':' &&

        (strncmp(filename, "subfile,", 8) || !strchr(filename + proto_len + 1, ':')) ||

        is_dos_path(filename))

        strcpy(proto_str, "file");

    else

        av_strlcpy(proto_str, filename,

                   FFMIN(proto_len + 1, sizeof(proto_str)));



    if ((ptr = strchr(proto_str, ',')))

        *ptr = '\0';

    av_strlcpy(proto_nested, proto_str, sizeof(proto_nested));

    if ((ptr = strchr(proto_nested, '+')))

        *ptr = '\0';



    protocols = ffurl_get_protocols(NULL, NULL);



    for (i = 0; protocols[i]; i++) {

            const URLProtocol *up = protocols[i];

        if (!strcmp(proto_str, up->name)) {

            av_freep(&protocols);

            return up;

        }

        if (up->flags & URL_PROTOCOL_FLAG_NESTED_SCHEME &&

            !strcmp(proto_nested, up->name)) {

            av_freep(&protocols);

            return up;

        }

    }

    av_freep(&protocols);




}

static void postprocess_chroma(AVFrame *frame, int w, int h, int depth)

{

    uint16_t *dstu = (uint16_t *)frame->data[1];

    uint16_t *dstv = (uint16_t *)frame->data[2];

    int16_t *srcu  = (int16_t *)frame->data[1];

    int16_t *srcv  = (int16_t *)frame->data[2];

    ptrdiff_t strideu = frame->linesize[1] / 2;

    ptrdiff_t stridev = frame->linesize[2] / 2;

    const int add = 1 << (depth - 1);

    const int shift = 16 - depth;

    int i, j;



    for (j = 0; j < h; j++) {

        for (i = 0; i < w; i++) {

            dstu[i] = (add + srcu[i]) << shift;

            dstv[i] = (add + srcv[i]) << shift;

        }

        dstu += strideu;

        dstv += stridev;

        srcu += strideu;

        srcv += stridev;

    }

}

static void id3v2_parse(AVFormatContext *s, int len, uint8_t version,

                        uint8_t flags, ID3v2ExtraMeta **extra_meta)

{

    int isv34, tlen, unsync;

    char tag[5];

    int64_t next, end = avio_tell(s->pb) + len;

    int taghdrlen;

    const char *reason = NULL;

    AVIOContext pb;

    AVIOContext *pbx;

    unsigned char *buffer = NULL;

    int buffer_size       = 0;

    const ID3v2EMFunc *extra_func;



    switch (version) {

    case 2:

        if (flags & 0x40) {

            reason = "compression";

            goto error;

        }

        isv34     = 0;

        taghdrlen = 6;

        break;



    case 3:

    case 4:

        isv34     = 1;

        taghdrlen = 10;

        break;



    default:

        reason = "version";

        goto error;

    }



    unsync = flags & 0x80;



    if (isv34 && flags & 0x40) { /* Extended header present, just skip over it */

        int extlen = get_size(s->pb, 4);

        if (version == 4)

            /* In v2.4 the length includes the length field we just read. */

            extlen -= 4;



        if (extlen < 0) {

            reason = "invalid extended header length";

            goto error;

        }

        avio_skip(s->pb, extlen);

    }



    while (len >= taghdrlen) {

        unsigned int tflags = 0;

        int tunsync         = 0;



        if (isv34) {

            avio_read(s->pb, tag, 4);

            tag[4] = 0;

            if (version == 3) {

                tlen = avio_rb32(s->pb);

            } else

                tlen = get_size(s->pb, 4);

            tflags  = avio_rb16(s->pb);

            tunsync = tflags & ID3v2_FLAG_UNSYNCH;

        } else {

            avio_read(s->pb, tag, 3);

            tag[3] = 0;

            tlen   = avio_rb24(s->pb);

        }

        if (tlen < 0 || tlen > len - taghdrlen) {

            av_log(s, AV_LOG_WARNING,

                   "Invalid size in frame %s, skipping the rest of tag.\n",

                   tag);

            break;

        }

        len -= taghdrlen + tlen;

        next = avio_tell(s->pb) + tlen;



        if (!tlen) {

            if (tag[0])

                av_log(s, AV_LOG_DEBUG, "Invalid empty frame %s, skipping.\n",

                       tag);

            continue;

        }



        if (tflags & ID3v2_FLAG_DATALEN) {

            avio_rb32(s->pb);

            tlen -= 4;

        }



        if (tflags & (ID3v2_FLAG_ENCRYPTION | ID3v2_FLAG_COMPRESSION)) {

            av_log(s, AV_LOG_WARNING,

                   "Skipping encrypted/compressed ID3v2 frame %s.\n", tag);

            avio_skip(s->pb, tlen);

        /* check for text tag or supported special meta tag */

        } else if (tag[0] == 'T' ||

                   (extra_meta &&

                    (extra_func = get_extra_meta_func(tag, isv34)))) {

            if (unsync || tunsync) {

                int64_t end = avio_tell(s->pb) + tlen;

                uint8_t *b;

                av_fast_malloc(&buffer, &buffer_size, tlen);

                if (!buffer) {

                    av_log(s, AV_LOG_ERROR, "Failed to alloc %d bytes\n", tlen);

                    goto seek;

                }

                b = buffer;

                while (avio_tell(s->pb) < end) {

                    *b++ = avio_r8(s->pb);

                    if (*(b - 1) == 0xff && avio_tell(s->pb) < end - 1) {

                        uint8_t val = avio_r8(s->pb);

                        *b++ = val ? val : avio_r8(s->pb);

                    }

                }

                ffio_init_context(&pb, buffer, b - buffer, 0, NULL, NULL, NULL,

                                  NULL);

                tlen = b - buffer;

                pbx  = &pb; // read from sync buffer

            } else {

                pbx = s->pb; // read straight from input

            }

            if (tag[0] == 'T')

                /* parse text tag */

                read_ttag(s, pbx, tlen, tag);

            else

                /* parse special meta tag */

                extra_func->read(s, pbx, tlen, tag, extra_meta);

        } else if (!tag[0]) {

            if (tag[1])

                av_log(s, AV_LOG_WARNING, "invalid frame id, assuming padding");

            avio_skip(s->pb, tlen);

            break;

        }

        /* Skip to end of tag */

seek:

        avio_seek(s->pb, next, SEEK_SET);

    }



    /* Footer preset, always 10 bytes, skip over it */

    if (version == 4 && flags & 0x10)

        end += 10;



error:

    if (reason)

        av_log(s, AV_LOG_INFO, "ID3v2.%d tag skipped, cannot handle %s\n",

               version, reason);

    avio_seek(s->pb, end, SEEK_SET);

    av_free(buffer);

    return;

}

static av_always_inline int encode_line(FFV1Context *s, int w,

                                        int16_t *sample[3],

                                        int plane_index, int bits)

{

    PlaneContext *const p = &s->plane[plane_index];

    RangeCoder *const c   = &s->c;

    int x;

    int run_index = s->run_index;

    int run_count = 0;

    int run_mode  = 0;



    if (s->ac) {

        if (c->bytestream_end - c->bytestream < w * 20) {

            av_log(s->avctx, AV_LOG_ERROR, "encoded frame too large\n");

            return AVERROR_INVALIDDATA;

        }

    } else {

        if (s->pb.buf_end - s->pb.buf - (put_bits_count(&s->pb) >> 3) < w * 4) {

            av_log(s->avctx, AV_LOG_ERROR, "encoded frame too large\n");

            return AVERROR_INVALIDDATA;

        }

    }



    for (x = 0; x < w; x++) {

        int diff, context;



        context = get_context(p, sample[0] + x, sample[1] + x, sample[2] + x);

        diff    = sample[0][x] - predict(sample[0] + x, sample[1] + x);



        if (context < 0) {

            context = -context;

            diff    = -diff;

        }



        diff = fold(diff, bits);



        if (s->ac) {

            if (s->flags & CODEC_FLAG_PASS1) {

                put_symbol_inline(c, p->state[context], diff, 1, s->rc_stat,

                                  s->rc_stat2[p->quant_table_index][context]);

            } else {

                put_symbol_inline(c, p->state[context], diff, 1, NULL, NULL);

            }

        } else {

            if (context == 0)

                run_mode = 1;



            if (run_mode) {

                if (diff) {

                    while (run_count >= 1 << ff_log2_run[run_index]) {

                        run_count -= 1 << ff_log2_run[run_index];

                        run_index++;

                        put_bits(&s->pb, 1, 1);

                    }



                    put_bits(&s->pb, 1 + ff_log2_run[run_index], run_count);

                    if (run_index)

                        run_index--;

                    run_count = 0;

                    run_mode  = 0;

                    if (diff > 0)

                        diff--;

                } else {

                    run_count++;

                }

            }



            av_dlog(s->avctx, "count:%d index:%d, mode:%d, x:%d pos:%d\n",

                    run_count, run_index, run_mode, x,

                    (int)put_bits_count(&s->pb));



            if (run_mode == 0)

                put_vlc_symbol(&s->pb, &p->vlc_state[context], diff, bits);

        }

    }

    if (run_mode) {

        while (run_count >= 1 << ff_log2_run[run_index]) {

            run_count -= 1 << ff_log2_run[run_index];

            run_index++;

            put_bits(&s->pb, 1, 1);

        }



        if (run_count)

            put_bits(&s->pb, 1, 1);

    }

    s->run_index = run_index;



    return 0;

}

static int mpeg4_decode_header(AVCodecParserContext *s1, AVCodecContext *avctx,

                               const uint8_t *buf, int buf_size)

{

    struct Mp4vParseContext *pc = s1->priv_data;

    Mpeg4DecContext *dec_ctx = &pc->dec_ctx;

    MpegEncContext *s = &dec_ctx->m;

    GetBitContext gb1, *gb = &gb1;

    int ret;



    s->avctx               = avctx;

    s->current_picture_ptr = &s->current_picture;



    if (avctx->extradata_size && pc->first_picture) {

        init_get_bits(gb, avctx->extradata, avctx->extradata_size * 8);

        ret = ff_mpeg4_decode_picture_header(dec_ctx, gb);



    }



    init_get_bits(gb, buf, 8 * buf_size);

    ret = ff_mpeg4_decode_picture_header(dec_ctx, gb);

    if (s->width && (!avctx->width || !avctx->height ||

                     !avctx->coded_width || !avctx->coded_height)) {

        ret = ff_set_dimensions(avctx, s->width, s->height);


            return ret;

    }

    if((s1->flags & PARSER_FLAG_USE_CODEC_TS) && s->avctx->time_base.den>0 && ret>=0){

        av_assert1(s1->pts == AV_NOPTS_VALUE);

        av_assert1(s1->dts == AV_NOPTS_VALUE);



        s1->pts = av_rescale_q(s->time, (AVRational){1, s->avctx->time_base.den}, (AVRational){1, 1200000});

    }



    s1->pict_type     = s->pict_type;

    pc->first_picture = 0;

    return ret;

}

static inline void RENAME(yuvPlanartouyvy)(const uint8_t *ysrc, const uint8_t *usrc, const uint8_t *vsrc, uint8_t *dst,

	long width, long height,

	long lumStride, long chromStride, long dstStride, long vertLumPerChroma)

{

	long y;

	const long chromWidth= width>>1;

	for(y=0; y<height; y++)

	{

#ifdef HAVE_MMX

//FIXME handle 2 lines a once (fewer prefetch, reuse some chrom, but very likely limited by mem anyway)

		asm volatile(

			"xor %%"REG_a", %%"REG_a"	\n\t"

			ASMALIGN(4)

			"1:				\n\t"

			PREFETCH" 32(%1, %%"REG_a", 2)	\n\t"

			PREFETCH" 32(%2, %%"REG_a")	\n\t"

			PREFETCH" 32(%3, %%"REG_a")	\n\t"

			"movq (%2, %%"REG_a"), %%mm0	\n\t" // U(0)

			"movq %%mm0, %%mm2		\n\t" // U(0)

			"movq (%3, %%"REG_a"), %%mm1	\n\t" // V(0)

			"punpcklbw %%mm1, %%mm0		\n\t" // UVUV UVUV(0)

			"punpckhbw %%mm1, %%mm2		\n\t" // UVUV UVUV(8)



			"movq (%1, %%"REG_a",2), %%mm3	\n\t" // Y(0)

			"movq 8(%1, %%"REG_a",2), %%mm5	\n\t" // Y(8)

			"movq %%mm0, %%mm4		\n\t" // Y(0)

			"movq %%mm2, %%mm6		\n\t" // Y(8)

			"punpcklbw %%mm3, %%mm0		\n\t" // YUYV YUYV(0)

			"punpckhbw %%mm3, %%mm4		\n\t" // YUYV YUYV(4)

			"punpcklbw %%mm5, %%mm2		\n\t" // YUYV YUYV(8)

			"punpckhbw %%mm5, %%mm6		\n\t" // YUYV YUYV(12)



			MOVNTQ" %%mm0, (%0, %%"REG_a", 4)\n\t"

			MOVNTQ" %%mm4, 8(%0, %%"REG_a", 4)\n\t"

			MOVNTQ" %%mm2, 16(%0, %%"REG_a", 4)\n\t"

			MOVNTQ" %%mm6, 24(%0, %%"REG_a", 4)\n\t"



			"add $8, %%"REG_a"		\n\t"

			"cmp %4, %%"REG_a"		\n\t"

			" jb 1b				\n\t"

			::"r"(dst), "r"(ysrc), "r"(usrc), "r"(vsrc), "g" (chromWidth)

			: "%"REG_a

		);

#else

//FIXME adapt the alpha asm code from yv12->yuy2



#if __WORDSIZE >= 64

		int i;

		uint64_t *ldst = (uint64_t *) dst;

		const uint8_t *yc = ysrc, *uc = usrc, *vc = vsrc;

		for(i = 0; i < chromWidth; i += 2){

			uint64_t k, l;

			k = uc[0] + (yc[0] << 8) +

			    (vc[0] << 16) + (yc[1] << 24);

			l = uc[1] + (yc[2] << 8) +

			    (vc[1] << 16) + (yc[3] << 24);

			*ldst++ = k + (l << 32);

			yc += 4;

			uc += 2;

			vc += 2;

		}



#else

		int i, *idst = (int32_t *) dst;

		const uint8_t *yc = ysrc, *uc = usrc, *vc = vsrc;

		for(i = 0; i < chromWidth; i++){

#ifdef WORDS_BIGENDIAN

			*idst++ = (uc[0] << 24)+ (yc[0] << 16) +

			    (vc[0] << 8) + (yc[1] << 0);

#else

			*idst++ = uc[0] + (yc[0] << 8) +

			    (vc[0] << 16) + (yc[1] << 24);

#endif

			yc += 2;

			uc++;

			vc++;

		}

#endif

#endif

		if((y&(vertLumPerChroma-1))==(vertLumPerChroma-1) )

		{

			usrc += chromStride;

			vsrc += chromStride;

		}

		ysrc += lumStride;

		dst += dstStride;

	}

#ifdef HAVE_MMX

asm(    EMMS" \n\t"

        SFENCE" \n\t"

        :::"memory");

#endif

}

callback(void *priv_data, int index, uint8_t *buf, int buf_size, int64_t time)

{

    AVFormatContext *s = priv_data;

    struct dshow_ctx *ctx = s->priv_data;

    AVPacketList **ppktl, *pktl_next;



//    dump_videohdr(s, vdhdr);



    WaitForSingleObject(ctx->mutex, INFINITE);



    if(shall_we_drop(s))

        goto fail;



    pktl_next = av_mallocz(sizeof(AVPacketList));

    if(!pktl_next)

        goto fail;



    if(av_new_packet(&pktl_next->pkt, buf_size) < 0) {

        av_free(pktl_next);

        goto fail;

    }



    pktl_next->pkt.stream_index = index;

    pktl_next->pkt.pts = time;

    memcpy(pktl_next->pkt.data, buf, buf_size);



    for(ppktl = &ctx->pktl ; *ppktl ; ppktl = &(*ppktl)->next);

    *ppktl = pktl_next;



    ctx->curbufsize += buf_size;



    SetEvent(ctx->event);

    ReleaseMutex(ctx->mutex);



    return;

fail:

    ReleaseMutex(ctx->mutex);

    return;

}

static inline void RENAME(yvu9_to_yuy2)(const uint8_t *src1, const uint8_t *src2, const uint8_t *src3,

			uint8_t *dst,

			unsigned width, unsigned height,

			int srcStride1, int srcStride2,

			int srcStride3, int dstStride)

{

    unsigned long y,x,w,h;

    w=width/2; h=height;

    for(y=0;y<h;y++){

	const uint8_t* yp=src1+srcStride1*y;

	const uint8_t* up=src2+srcStride2*(y>>2);

	const uint8_t* vp=src3+srcStride3*(y>>2);

	uint8_t* d=dst+dstStride*y;

	x=0;

#ifdef HAVE_MMX

	for(;x<w-7;x+=8)

	{

	    asm volatile(

		PREFETCH" 32(%1, %0)\n\t"

		PREFETCH" 32(%2, %0)\n\t"

		PREFETCH" 32(%3, %0)\n\t"

		"movq	(%1, %0, 4), %%mm0\n\t"       /* Y0Y1Y2Y3Y4Y5Y6Y7 */

		"movq	(%2, %0), %%mm1\n\t"       /* U0U1U2U3U4U5U6U7 */

		"movq	(%3, %0), %%mm2\n\t"	     /* V0V1V2V3V4V5V6V7 */

		"movq	%%mm0, %%mm3\n\t"    /* Y0Y1Y2Y3Y4Y5Y6Y7 */

		"movq	%%mm1, %%mm4\n\t"    /* U0U1U2U3U4U5U6U7 */

		"movq	%%mm2, %%mm5\n\t"    /* V0V1V2V3V4V5V6V7 */

		"punpcklbw %%mm1, %%mm1\n\t" /* U0U0 U1U1 U2U2 U3U3 */

		"punpcklbw %%mm2, %%mm2\n\t" /* V0V0 V1V1 V2V2 V3V3 */

		"punpckhbw %%mm4, %%mm4\n\t" /* U4U4 U5U5 U6U6 U7U7 */

		"punpckhbw %%mm5, %%mm5\n\t" /* V4V4 V5V5 V6V6 V7V7 */



		"movq	%%mm1, %%mm6\n\t"

		"punpcklbw %%mm2, %%mm1\n\t" /* U0V0 U0V0 U1V1 U1V1*/

		"punpcklbw %%mm1, %%mm0\n\t" /* Y0U0 Y1V0 Y2U0 Y3V0*/

		"punpckhbw %%mm1, %%mm3\n\t" /* Y4U1 Y5V1 Y6U1 Y7V1*/

		MOVNTQ"	%%mm0, (%4, %0, 8)\n\t"

		MOVNTQ"	%%mm3, 8(%4, %0, 8)\n\t"



		"punpckhbw %%mm2, %%mm6\n\t" /* U2V2 U2V2 U3V3 U3V3*/

		"movq	8(%1, %0, 4), %%mm0\n\t"

		"movq	%%mm0, %%mm3\n\t"

		"punpcklbw %%mm6, %%mm0\n\t" /* Y U2 Y V2 Y U2 Y V2*/

		"punpckhbw %%mm6, %%mm3\n\t" /* Y U3 Y V3 Y U3 Y V3*/

		MOVNTQ"	%%mm0, 16(%4, %0, 8)\n\t"

		MOVNTQ"	%%mm3, 24(%4, %0, 8)\n\t"



		"movq	%%mm4, %%mm6\n\t"

		"movq	16(%1, %0, 4), %%mm0\n\t"

		"movq	%%mm0, %%mm3\n\t"

		"punpcklbw %%mm5, %%mm4\n\t"

		"punpcklbw %%mm4, %%mm0\n\t" /* Y U4 Y V4 Y U4 Y V4*/

		"punpckhbw %%mm4, %%mm3\n\t" /* Y U5 Y V5 Y U5 Y V5*/

		MOVNTQ"	%%mm0, 32(%4, %0, 8)\n\t"

		MOVNTQ"	%%mm3, 40(%4, %0, 8)\n\t"



		"punpckhbw %%mm5, %%mm6\n\t"

		"movq	24(%1, %0, 4), %%mm0\n\t"

		"movq	%%mm0, %%mm3\n\t"

		"punpcklbw %%mm6, %%mm0\n\t" /* Y U6 Y V6 Y U6 Y V6*/

		"punpckhbw %%mm6, %%mm3\n\t" /* Y U7 Y V7 Y U7 Y V7*/

		MOVNTQ"	%%mm0, 48(%4, %0, 8)\n\t"

		MOVNTQ"	%%mm3, 56(%4, %0, 8)\n\t"



		: "+r" (x)

                : "r"(yp), "r" (up), "r"(vp), "r"(d)

		:"memory");

	}

#endif

	for(; x<w; x++)

	{

	    const int x2= x<<2;

	    d[8*x+0]=yp[x2];

	    d[8*x+1]=up[x];

	    d[8*x+2]=yp[x2+1];

	    d[8*x+3]=vp[x];

	    d[8*x+4]=yp[x2+2];

	    d[8*x+5]=up[x];

	    d[8*x+6]=yp[x2+3];

	    d[8*x+7]=vp[x];

	}

    }

#ifdef HAVE_MMX

	asm(

		EMMS" \n\t"

		SFENCE" \n\t"

		::: "memory"

		);

#endif

}

static void *av_mallocz_static(unsigned int size)

{

    void *ptr = av_mallocz(size);



    if(ptr){

        array_static =av_fast_realloc(array_static, &allocated_static, sizeof(void*)*(last_static+1));

        if(!array_static)

            return NULL;

        array_static[last_static++] = ptr;

    }



    return ptr;

}

static int mxf_read_primer_pack(MXFContext *mxf)

{

    ByteIOContext *pb = mxf->fc->pb;

    int item_num = get_be32(pb);

    int item_len = get_be32(pb);



    if (item_len != 18) {

        av_log(mxf->fc, AV_LOG_ERROR, "unsupported primer pack item length\n");

        return -1;

    }

    if (item_num > UINT_MAX / item_len)

        return -1;

    mxf->local_tags_count = item_num;

    mxf->local_tags = av_malloc(item_num*item_len);

    if (!mxf->local_tags)

        return -1;

    get_buffer(pb, mxf->local_tags, item_num*item_len);

    return 0;

}

static int convert_bitstream(const uint8_t *src, int src_size, uint8_t *dst, int max_size)

{

    switch (AV_RB32(src)) {

    case DCA_SYNCWORD_CORE_BE:

    case DCA_SYNCWORD_SUBSTREAM:

        memcpy(dst, src, src_size);

        return src_size;

    case DCA_SYNCWORD_CORE_LE:

    case DCA_SYNCWORD_CORE_14B_BE:

    case DCA_SYNCWORD_CORE_14B_LE:

        return avpriv_dca_convert_bitstream(src, src_size, dst, max_size);

    default:

        return AVERROR_INVALIDDATA;

    }

}

int ff_scale_image(uint8_t *dst_data[4], int dst_linesize[4],

                   int dst_w, int dst_h, enum AVPixelFormat dst_pix_fmt,

                   uint8_t * const src_data[4], int src_linesize[4],

                   int src_w, int src_h, enum AVPixelFormat src_pix_fmt,

                   void *log_ctx)

{

    int ret;

    struct SwsContext *sws_ctx = sws_getContext(src_w, src_h, src_pix_fmt,

                                                dst_w, dst_h, dst_pix_fmt,

                                                SWS_BILINEAR, NULL, NULL, NULL);

    if (!sws_ctx) {

        av_log(log_ctx, AV_LOG_ERROR,

               "Impossible to create scale context for the conversion "

               "fmt:%s s:%dx%d -> fmt:%s s:%dx%d\n",

               av_get_pix_fmt_name(src_pix_fmt), src_w, src_h,

               av_get_pix_fmt_name(dst_pix_fmt), dst_w, dst_h);

        ret = AVERROR(EINVAL);

        goto end;

    }



    if ((ret = av_image_alloc(dst_data, dst_linesize, dst_w, dst_h, dst_pix_fmt, 16)) < 0)

        goto end;

    ret = 0;

    sws_scale(sws_ctx, (const uint8_t * const*)src_data, src_linesize, 0, src_h, dst_data, dst_linesize);



end:

    sws_freeContext(sws_ctx);

    return ret;

}

static int ftp_read(URLContext *h, unsigned char *buf, int size)

{

    FTPContext *s = h->priv_data;

    int read, err, retry_done = 0;



    av_dlog(h, "ftp protocol read %d bytes\n", size);

  retry:

    if (s->state == DISCONNECTED) {

        /* optimization */

        if (s->position >= s->filesize)

            return 0;

        if ((err = ftp_connect_data_connection(h)) < 0)

            return err;

    }

    if (s->state == READY) {

        if (s->position >= s->filesize)

            return 0;

        if ((err = ftp_retrieve(s)) < 0)

            return err;

    }

    if (s->conn_data && s->state == DOWNLOADING) {

        read = ffurl_read(s->conn_data, buf, size);

        if (read >= 0) {

            s->position += read;

            if (s->position >= s->filesize) {

                /* server will terminate, but keep current position to avoid madness */

                /* save position to restart from it */

                int64_t pos = s->position;

                if (ftp_abort(h) < 0) {

                    s->position = pos;

                    return AVERROR(EIO);

                }

                s->position = pos;

            }

        }

        if (read <= 0 && s->position < s->filesize && !h->is_streamed) {

            /* Server closed connection. Probably due to inactivity */

            int64_t pos = s->position;

            av_log(h, AV_LOG_INFO, "Reconnect to FTP server.\n");

            if ((err = ftp_abort(h)) < 0)

                return err;

            if ((err = ftp_seek(h, pos, SEEK_SET)) < 0) {

                av_log(h, AV_LOG_ERROR, "Position cannot be restored.\n");

                return err;

            }

            if (!retry_done) {

                retry_done = 1;

                goto retry;

            }

        }

        return read;

    }



    av_log(h, AV_LOG_DEBUG, "FTP read failed\n");

    return AVERROR(EIO);

}

static void do_video_out(AVFormatContext *s,

                         OutputStream *ost,

                         AVFrame *in_picture,

                         float quality)

{

    int ret, format_video_sync;

    AVPacket pkt;

    AVCodecContext *enc = ost->st->codec;

    int nb_frames;

    double sync_ipts, delta;

    double duration = 0;

    int frame_size = 0;

    InputStream *ist = NULL;



    if (ost->source_index >= 0)

        ist = input_streams[ost->source_index];



    if(ist && ist->st->start_time != AV_NOPTS_VALUE && ist->st->first_dts != AV_NOPTS_VALUE && ost->frame_rate.num)

        duration = 1/(av_q2d(ost->frame_rate) * av_q2d(enc->time_base));



    sync_ipts = in_picture->pts;

    delta = sync_ipts - ost->sync_opts + duration;



    /* by default, we output a single frame */

    nb_frames = 1;



    format_video_sync = video_sync_method;

    if (format_video_sync == VSYNC_AUTO)

        format_video_sync = (s->oformat->flags & AVFMT_VARIABLE_FPS) ? ((s->oformat->flags & AVFMT_NOTIMESTAMPS) ? VSYNC_PASSTHROUGH : VSYNC_VFR) : 1;



    switch (format_video_sync) {

    case VSYNC_CFR:

        // FIXME set to 0.5 after we fix some dts/pts bugs like in avidec.c

        if (delta < -1.1)

            nb_frames = 0;

        else if (delta > 1.1)

            nb_frames = lrintf(delta);

        break;

    case VSYNC_VFR:

        if (delta <= -0.6)

            nb_frames = 0;

        else if (delta > 0.6)

            ost->sync_opts = lrint(sync_ipts);

        break;

    case VSYNC_DROP:

    case VSYNC_PASSTHROUGH:

        ost->sync_opts = lrint(sync_ipts);

        break;

    default:

        av_assert0(0);




    nb_frames = FFMIN(nb_frames, ost->max_frames - ost->frame_number);

    if (nb_frames == 0) {


        av_log(NULL, AV_LOG_VERBOSE, "*** drop!\n");


    } else if (nb_frames > 1) {






        nb_frames_dup += nb_frames - 1;

        av_log(NULL, AV_LOG_VERBOSE, "*** %d dup!\n", nb_frames - 1);






duplicate_frame:

    av_init_packet(&pkt);

    pkt.data = NULL;

    pkt.size = 0;



    in_picture->pts = ost->sync_opts;



    if (s->oformat->flags & AVFMT_RAWPICTURE &&

        enc->codec->id == CODEC_ID_RAWVIDEO) {

        /* raw pictures are written as AVPicture structure to

           avoid any copies. We support temporarily the older

           method. */

        enc->coded_frame->interlaced_frame = in_picture->interlaced_frame;

        enc->coded_frame->top_field_first  = in_picture->top_field_first;

        pkt.data   = (uint8_t *)in_picture;

        pkt.size   =  sizeof(AVPicture);

        pkt.pts    = av_rescale_q(in_picture->pts, enc->time_base, ost->st->time_base);

        pkt.flags |= AV_PKT_FLAG_KEY;



        write_frame(s, &pkt, ost);

        video_size += pkt.size;

    } else {

        int got_packet;

        AVFrame big_picture;



        big_picture = *in_picture;

        /* better than nothing: use input picture interlaced

           settings */

        big_picture.interlaced_frame = in_picture->interlaced_frame;

        if (ost->st->codec->flags & (CODEC_FLAG_INTERLACED_DCT|CODEC_FLAG_INTERLACED_ME)) {

            if (ost->top_field_first == -1)

                big_picture.top_field_first = in_picture->top_field_first;

            else

                big_picture.top_field_first = !!ost->top_field_first;




        /* handles same_quant here. This is not correct because it may

           not be a global option */

        big_picture.quality = quality;

        if (!enc->me_threshold)

            big_picture.pict_type = 0;

        if (ost->forced_kf_index < ost->forced_kf_count &&

            big_picture.pts >= ost->forced_kf_pts[ost->forced_kf_index]) {

