static av_cold int read_specific_config(ALSDecContext *ctx)

{

    GetBitContext gb;

    uint64_t ht_size;

    int i, config_offset;

    MPEG4AudioConfig m4ac;

    ALSSpecificConfig *sconf = &ctx->sconf;

    AVCodecContext *avctx    = ctx->avctx;

    uint32_t als_id, header_size, trailer_size;



    init_get_bits(&gb, avctx->extradata, avctx->extradata_size * 8);



    config_offset = avpriv_mpeg4audio_get_config(&m4ac, avctx->extradata,

                                                 avctx->extradata_size * 8, 1);



    if (config_offset < 0)

        return -1;



    skip_bits_long(&gb, config_offset);



    if (get_bits_left(&gb) < (30 << 3))

        return -1;



    // read the fixed items

    als_id                      = get_bits_long(&gb, 32);

    avctx->sample_rate          = m4ac.sample_rate;

    skip_bits_long(&gb, 32); // sample rate already known

    sconf->samples              = get_bits_long(&gb, 32);

    avctx->channels             = m4ac.channels;

    skip_bits(&gb, 16);      // number of channels already known

    skip_bits(&gb, 3);       // skip file_type

    sconf->resolution           = get_bits(&gb, 3);

    sconf->floating             = get_bits1(&gb);

    sconf->msb_first            = get_bits1(&gb);

    sconf->frame_length         = get_bits(&gb, 16) + 1;

    sconf->ra_distance          = get_bits(&gb, 8);

    sconf->ra_flag              = get_bits(&gb, 2);

    sconf->adapt_order          = get_bits1(&gb);

    sconf->coef_table           = get_bits(&gb, 2);

    sconf->long_term_prediction = get_bits1(&gb);

    sconf->max_order            = get_bits(&gb, 10);

    sconf->block_switching      = get_bits(&gb, 2);

    sconf->bgmc                 = get_bits1(&gb);

    sconf->sb_part              = get_bits1(&gb);

    sconf->joint_stereo         = get_bits1(&gb);

    sconf->mc_coding            = get_bits1(&gb);

    sconf->chan_config          = get_bits1(&gb);

    sconf->chan_sort            = get_bits1(&gb);

    sconf->crc_enabled          = get_bits1(&gb);

    sconf->rlslms               = get_bits1(&gb);

    skip_bits(&gb, 5);       // skip 5 reserved bits

    skip_bits1(&gb);         // skip aux_data_enabled





    // check for ALSSpecificConfig struct

    if (als_id != MKBETAG('A','L','S','\0'))

        return -1;



    ctx->cur_frame_length = sconf->frame_length;



    // read channel config

    if (sconf->chan_config)

        sconf->chan_config_info = get_bits(&gb, 16);

    // TODO: use this to set avctx->channel_layout





    // read channel sorting

    if (sconf->chan_sort && avctx->channels > 1) {

        int chan_pos_bits = av_ceil_log2(avctx->channels);

        int bits_needed  = avctx->channels * chan_pos_bits + 7;

        if (get_bits_left(&gb) < bits_needed)

            return -1;



        if (!(sconf->chan_pos = av_malloc(avctx->channels * sizeof(*sconf->chan_pos))))

            return AVERROR(ENOMEM);



        ctx->cs_switch = 1;



        for (i = 0; i < avctx->channels; i++) {

            int idx;



            idx = get_bits(&gb, chan_pos_bits);

            if (idx >= avctx->channels) {

                av_log(avctx, AV_LOG_WARNING, "Invalid channel reordering.\n");

                ctx->cs_switch = 0;

                break;

            }

            sconf->chan_pos[idx] = i;

        }



        align_get_bits(&gb);

    }





    // read fixed header and trailer sizes,

    // if size = 0xFFFFFFFF then there is no data field!

    if (get_bits_left(&gb) < 64)

        return -1;



    header_size  = get_bits_long(&gb, 32);

    trailer_size = get_bits_long(&gb, 32);

    if (header_size  == 0xFFFFFFFF)

        header_size  = 0;

    if (trailer_size == 0xFFFFFFFF)

        trailer_size = 0;



    ht_size = ((int64_t)(header_size) + (int64_t)(trailer_size)) << 3;





    // skip the header and trailer data

    if (get_bits_left(&gb) < ht_size)

        return -1;



    if (ht_size > INT32_MAX)

        return -1;



    skip_bits_long(&gb, ht_size);





    // initialize CRC calculation

    if (sconf->crc_enabled) {

        if (get_bits_left(&gb) < 32)

            return -1;



        if (avctx->err_recognition & (AV_EF_CRCCHECK|AV_EF_CAREFUL)) {

            ctx->crc_table = av_crc_get_table(AV_CRC_32_IEEE_LE);

            ctx->crc       = 0xFFFFFFFF;

            ctx->crc_org   = ~get_bits_long(&gb, 32);

        } else

            skip_bits_long(&gb, 32);

    }





    // no need to read the rest of ALSSpecificConfig (ra_unit_size & aux data)



    dprint_specific_config(ctx);



    return 0;

}

static int v4l2_receive_frame(AVCodecContext *avctx, AVFrame *frame)

{

    V4L2m2mContext *s = avctx->priv_data;

    V4L2Context *const capture = &s->capture;

    V4L2Context *const output = &s->output;

    AVPacket avpkt = {0};

    int ret;



    ret = ff_decode_get_packet(avctx, &avpkt);

    if (ret < 0 && ret != AVERROR_EOF)

        return ret;



    if (s->draining)

        goto dequeue;



    ret = ff_v4l2_context_enqueue_packet(output, &avpkt);

    if (ret < 0) {

        if (ret != AVERROR(ENOMEM))

           return ret;

        /* no input buffers available, continue dequeing */

    }



    if (avpkt.size) {

        ret = v4l2_try_start(avctx);

        if (ret)

            return 0;

    }



dequeue:

    return ff_v4l2_context_dequeue_frame(capture, frame);

}

static int jpeg2000_decode_tile(Jpeg2000DecoderContext *s, Jpeg2000Tile *tile,

                                AVFrame *picture)

{

    int compno, reslevelno, bandno;

    int x, y;



    uint8_t *line;

    Jpeg2000T1Context t1;

    /* Loop on tile components */



    for (compno = 0; compno < s->ncomponents; compno++) {

        Jpeg2000Component *comp     = tile->comp + compno;

        Jpeg2000CodingStyle *codsty = tile->codsty + compno;

        /* Loop on resolution levels */

        for (reslevelno = 0; reslevelno < codsty->nreslevels2decode; reslevelno++) {

            Jpeg2000ResLevel *rlevel = comp->reslevel + reslevelno;

            /* Loop on bands */

            for (bandno = 0; bandno < rlevel->nbands; bandno++) {

                uint16_t nb_precincts, precno;

                Jpeg2000Band *band = rlevel->band + bandno;

                int cblkno = 0, bandpos;

                bandpos = bandno + (reslevelno > 0);



                if (band->coord[0][0] == band->coord[0][1] ||

                    band->coord[1][0] == band->coord[1][1])

                    continue;



                nb_precincts = rlevel->num_precincts_x * rlevel->num_precincts_y;

                /* Loop on precincts */

                for (precno = 0; precno < nb_precincts; precno++) {

                    Jpeg2000Prec *prec = band->prec + precno;



                    /* Loop on codeblocks */

                    for (cblkno = 0; cblkno < prec->nb_codeblocks_width * prec->nb_codeblocks_height; cblkno++) {

                        int x, y;

                        Jpeg2000Cblk *cblk = prec->cblk + cblkno;

                        decode_cblk(s, codsty, &t1, cblk,

                                    cblk->coord[0][1] - cblk->coord[0][0],

                                    cblk->coord[1][1] - cblk->coord[1][0],

                                    bandpos);



                        x = cblk->coord[0][0];

                        y = cblk->coord[1][0];



                        if (codsty->transform == FF_DWT97)

                            dequantization_float(x, y, cblk, comp, &t1, band);

                        else

                            dequantization_int(x, y, cblk, comp, &t1, band);

                   } /* end cblk */

                } /*end prec */

            } /* end band */

        } /* end reslevel */



        /* inverse DWT */

        ff_dwt_decode(&comp->dwt, codsty->transform == FF_DWT97 ? (void*)comp->f_data : (void*)comp->i_data);

    } /*end comp */



    /* inverse MCT transformation */

    if (tile->codsty[0].mct)

        mct_decode(s, tile);



    if (s->precision <= 8) {

        for (compno = 0; compno < s->ncomponents; compno++) {

            Jpeg2000Component *comp = tile->comp + compno;

            float *datap = comp->f_data;

            int32_t *i_datap = comp->i_data;

            int cbps = s->cbps[compno];

            int w = tile->comp[compno].coord[0][1] - s->image_offset_x;



            y    = tile->comp[compno].coord[1][0] - s->image_offset_y;

            line = picture->data[0] + y * picture->linesize[0];

            for (; y < tile->comp[compno].coord[1][1] - s->image_offset_y; y += s->cdy[compno]) {

                uint8_t *dst;



                x   = tile->comp[compno].coord[0][0] - s->image_offset_x;

                dst = line + x * s->ncomponents + compno;



                if (tile->codsty->transform == FF_DWT97) {

                    for (; x < w; x += s->cdx[compno]) {

                        int val = lrintf(*datap) + (1 << (cbps - 1));

                        /* DC level shift and clip see ISO 15444-1:2002 G.1.2 */

                        val = av_clip(val, 0, (1 << cbps) - 1);

                        *dst = val << (8 - cbps);

                        datap++;

                        dst += s->ncomponents;

                    }

                } else {

                    for (; x < w; x += s->cdx[compno]) {

                        int val = *i_datap + (1 << (cbps - 1));

                        /* DC level shift and clip see ISO 15444-1:2002 G.1.2 */

                        val = av_clip(val, 0, (1 << cbps) - 1);

                        *dst = val << (8 - cbps);

                        i_datap++;

                        dst += s->ncomponents;

                    }

                }

                line += picture->linesize[0];

            }

        }

    } else {

        for (compno = 0; compno < s->ncomponents; compno++) {

            Jpeg2000Component *comp = tile->comp + compno;

            float *datap = comp->f_data;

            int32_t *i_datap = comp->i_data;

            uint16_t *linel;

            int cbps = s->cbps[compno];

            int w = tile->comp[compno].coord[0][1] - s->image_offset_x;



            y     = tile->comp[compno].coord[1][0] - s->image_offset_y;

            linel = (uint16_t *)picture->data[0] + y * (picture->linesize[0] >> 1);

            for (; y < tile->comp[compno].coord[1][1] - s->image_offset_y; y += s->cdy[compno]) {

                uint16_t *dst;

                x   = tile->comp[compno].coord[0][0] - s->image_offset_x;

                dst = linel + (x * s->ncomponents + compno);

                if (tile->codsty->transform == FF_DWT97) {

                    for (; x < w; x += s-> cdx[compno]) {

                        int  val = lrintf(*datap) + (1 << (cbps - 1));

                        /* DC level shift and clip see ISO 15444-1:2002 G.1.2 */

                        val = av_clip(val, 0, (1 << cbps) - 1);

                        /* align 12 bit values in little-endian mode */

                        *dst = val << (16 - cbps);

                        datap++;

                        dst += s->ncomponents;

                    }

                } else {

                    for (; x < w; x += s-> cdx[compno]) {

                        int val = *i_datap + (1 << (cbps - 1));

                        /* DC level shift and clip see ISO 15444-1:2002 G.1.2 */

                        val = av_clip(val, 0, (1 << cbps) - 1);

                        /* align 12 bit values in little-endian mode */

                        *dst = val << (16 - cbps);

                        i_datap++;

                        dst += s->ncomponents;

                    }

                }

                linel += picture->linesize[0] >> 1;

            }

        }

    }



    return 0;

}

static int rtmp_open(URLContext *s, const char *uri, int flags)

{

    RTMPContext *rt = s->priv_data;

    char proto[8], hostname[256], path[1024], auth[100], *fname;

    char *old_app, *qmark, fname_buffer[1024];

    uint8_t buf[2048];

    int port;

    AVDictionary *opts = NULL;

    int ret;



    if (rt->listen_timeout > 0)

        rt->listen = 1;



    rt->is_input = !(flags & AVIO_FLAG_WRITE);



    av_url_split(proto, sizeof(proto), auth, sizeof(auth),

                 hostname, sizeof(hostname), &port,

                 path, sizeof(path), s->filename);



    if (strchr(path, ' ')) {

        av_log(s, AV_LOG_WARNING,

               "Detected librtmp style URL parameters, these aren't supported "

               "by the libavformat internal RTMP handler currently enabled. "

               "See the documentation for the correct way to pass parameters.\n");

    }



    if (auth[0]) {

        char *ptr = strchr(auth, ':');

        if (ptr) {

            *ptr = '\0';

            av_strlcpy(rt->username, auth, sizeof(rt->username));

            av_strlcpy(rt->password, ptr + 1, sizeof(rt->password));

        }

    }



    if (rt->listen && strcmp(proto, "rtmp")) {

        av_log(s, AV_LOG_ERROR, "rtmp_listen not available for %s\n",

               proto);

        return AVERROR(EINVAL);

    }

    if (!strcmp(proto, "rtmpt") || !strcmp(proto, "rtmpts")) {

        if (!strcmp(proto, "rtmpts"))

            av_dict_set(&opts, "ffrtmphttp_tls", "1", 1);



        /* open the http tunneling connection */

        ff_url_join(buf, sizeof(buf), "ffrtmphttp", NULL, hostname, port, NULL);

    } else if (!strcmp(proto, "rtmps")) {

        /* open the tls connection */

        if (port < 0)

            port = RTMPS_DEFAULT_PORT;

        ff_url_join(buf, sizeof(buf), "tls", NULL, hostname, port, NULL);

    } else if (!strcmp(proto, "rtmpe") || (!strcmp(proto, "rtmpte"))) {

        if (!strcmp(proto, "rtmpte"))

            av_dict_set(&opts, "ffrtmpcrypt_tunneling", "1", 1);



        /* open the encrypted connection */

        ff_url_join(buf, sizeof(buf), "ffrtmpcrypt", NULL, hostname, port, NULL);

        rt->encrypted = 1;

    } else {

        /* open the tcp connection */

        if (port < 0)

            port = RTMP_DEFAULT_PORT;

        if (rt->listen)

            ff_url_join(buf, sizeof(buf), "tcp", NULL, hostname, port,

                        "?listen&listen_timeout=%d",

                        rt->listen_timeout * 1000);

        else

            ff_url_join(buf, sizeof(buf), "tcp", NULL, hostname, port, NULL);

    }



reconnect:

    if ((ret = ffurl_open(&rt->stream, buf, AVIO_FLAG_READ_WRITE,

                          &s->interrupt_callback, &opts)) < 0) {

        av_log(s , AV_LOG_ERROR, "Cannot open connection %s\n", buf);

        goto fail;

    }



    if (rt->swfverify) {

        if ((ret = rtmp_calc_swfhash(s)) < 0)

            goto fail;

    }



    rt->state = STATE_START;

    if (!rt->listen && (ret = rtmp_handshake(s, rt)) < 0)

        goto fail;

    if (rt->listen && (ret = rtmp_server_handshake(s, rt)) < 0)

        goto fail;



    rt->out_chunk_size = 128;

    rt->in_chunk_size  = 128; // Probably overwritten later

    rt->state = STATE_HANDSHAKED;



    // Keep the application name when it has been defined by the user.

    old_app = rt->app;



    rt->app = av_malloc(APP_MAX_LENGTH);

    if (!rt->app) {

        ret = AVERROR(ENOMEM);

        goto fail;

    }



    //extract "app" part from path

    qmark = strchr(path, '?');

    if (qmark && strstr(qmark, "slist=")) {

        char* amp;

        // After slist we have the playpath, before the params, the app

        av_strlcpy(rt->app, path + 1, FFMIN(qmark - path, APP_MAX_LENGTH));

        fname = strstr(path, "slist=") + 6;

        // Strip any further query parameters from fname

        amp = strchr(fname, '&');

        if (amp) {

            av_strlcpy(fname_buffer, fname, FFMIN(amp - fname + 1,

                                                  sizeof(fname_buffer)));

            fname = fname_buffer;

        }

    } else if (!strncmp(path, "/ondemand/", 10)) {

        fname = path + 10;

        memcpy(rt->app, "ondemand", 9);

    } else {

        char *next = *path ? path + 1 : path;

        char *p = strchr(next, '/');

        if (!p) {

            fname = next;

            rt->app[0] = '\0';

        } else {

            // make sure we do not mismatch a playpath for an application instance

            char *c = strchr(p + 1, ':');

            fname = strchr(p + 1, '/');

            if (!fname || (c && c < fname)) {

                fname = p + 1;

                av_strlcpy(rt->app, path + 1, FFMIN(p - path, APP_MAX_LENGTH));

            } else {

                fname++;

                av_strlcpy(rt->app, path + 1, FFMIN(fname - path - 1, APP_MAX_LENGTH));

            }

        }

    }



    if (old_app) {

        // The name of application has been defined by the user, override it.

        if (strlen(old_app) >= APP_MAX_LENGTH) {

            ret = AVERROR(EINVAL);

            goto fail;

        }

        av_free(rt->app);

        rt->app = old_app;

    }



    if (!rt->playpath) {

        int len = strlen(fname);



        rt->playpath = av_malloc(PLAYPATH_MAX_LENGTH);

        if (!rt->playpath) {

            ret = AVERROR(ENOMEM);

            goto fail;

        }



        if (!strchr(fname, ':') && len >= 4 &&

            (!strcmp(fname + len - 4, ".f4v") ||

             !strcmp(fname + len - 4, ".mp4"))) {

            memcpy(rt->playpath, "mp4:", 5);

        } else {

            if (len >= 4 && !strcmp(fname + len - 4, ".flv"))

                fname[len - 4] = '\0';

            rt->playpath[0] = 0;

        }

        av_strlcat(rt->playpath, fname, PLAYPATH_MAX_LENGTH);

    }



    if (!rt->tcurl) {

        rt->tcurl = av_malloc(TCURL_MAX_LENGTH);

        if (!rt->tcurl) {

            ret = AVERROR(ENOMEM);

            goto fail;

        }

        ff_url_join(rt->tcurl, TCURL_MAX_LENGTH, proto, NULL, hostname,

                    port, "/%s", rt->app);

    }



    if (!rt->flashver) {

        rt->flashver = av_malloc(FLASHVER_MAX_LENGTH);

        if (!rt->flashver) {

            ret = AVERROR(ENOMEM);

            goto fail;

        }

        if (rt->is_input) {

            snprintf(rt->flashver, FLASHVER_MAX_LENGTH, "%s %d,%d,%d,%d",

                    RTMP_CLIENT_PLATFORM, RTMP_CLIENT_VER1, RTMP_CLIENT_VER2,

                    RTMP_CLIENT_VER3, RTMP_CLIENT_VER4);

        } else {

            snprintf(rt->flashver, FLASHVER_MAX_LENGTH,

                    "FMLE/3.0 (compatible; %s)", LIBAVFORMAT_IDENT);

        }

    }



    rt->client_report_size = 1048576;

    rt->bytes_read = 0;

    rt->has_audio = 0;

    rt->has_video = 0;

    rt->received_metadata = 0;

    rt->last_bytes_read = 0;

    rt->server_bw = 2500000;



    av_log(s, AV_LOG_DEBUG, "Proto = %s, path = %s, app = %s, fname = %s\n",

           proto, path, rt->app, rt->playpath);

    if (!rt->listen) {

        if ((ret = gen_connect(s, rt)) < 0)

            goto fail;

    } else {

        if ((ret = read_connect(s, s->priv_data)) < 0)

            goto fail;

    }



    do {

        ret = get_packet(s, 1);

    } while (ret == AVERROR(EAGAIN));

    if (ret < 0)

        goto fail;



    if (rt->do_reconnect) {

        int i;

        ffurl_close(rt->stream);

        rt->stream       = NULL;

        rt->do_reconnect = 0;

        rt->nb_invokes   = 0;

        for (i = 0; i < 2; i++)

            memset(rt->prev_pkt[i], 0,

                   sizeof(**rt->prev_pkt) * rt->nb_prev_pkt[i]);

        free_tracked_methods(rt);

        goto reconnect;

    }



    if (rt->is_input) {

        int err;

        // generate FLV header for demuxer

        rt->flv_size = 13;

        if ((err = av_reallocp(&rt->flv_data, rt->flv_size)) < 0)

            return err;

        rt->flv_off  = 0;

        memcpy(rt->flv_data, "FLV\1\0\0\0\0\011\0\0\0\0", rt->flv_size);



        // Read packets until we reach the first A/V packet or read metadata.

        // If there was a metadata package in front of the A/V packets, we can

        // build the FLV header from this. If we do not receive any metadata,

        // the FLV decoder will allocate the needed streams when their first

        // audio or video packet arrives.

        while (!rt->has_audio && !rt->has_video && !rt->received_metadata) {

            if ((ret = get_packet(s, 0)) < 0)

               return ret;

        }



        // Either after we have read the metadata or (if there is none) the

        // first packet of an A/V stream, we have a better knowledge about the

        // streams, so set the FLV header accordingly.

        if (rt->has_audio) {

            rt->flv_data[4] |= FLV_HEADER_FLAG_HASAUDIO;

        }

        if (rt->has_video) {

            rt->flv_data[4] |= FLV_HEADER_FLAG_HASVIDEO;

        }

    } else {

        rt->flv_size = 0;

        rt->flv_data = NULL;

        rt->flv_off  = 0;

        rt->skip_bytes = 13;

    }



    s->max_packet_size = rt->stream->max_packet_size;

    s->is_streamed     = 1;

    return 0;



fail:

    av_dict_free(&opts);

    rtmp_close(s);

    return ret;

}

static int read_random(uint32_t *dst, const char *file)

{

    int fd = open(file, O_RDONLY);

    int err = -1;



    if (fd == -1)

        return -1;

#if HAVE_FCNTL && defined(O_NONBLOCK)

    if (fcntl(fd, F_SETFL, fcntl(fd, F_GETFL) | O_NONBLOCK) != -1)

#endif

        err = read(fd, dst, sizeof(*dst));

    close(fd);



    return err;

}

static int draw_slice(AVFilterLink *link, int y, int h, int slice_dir)

{

    SliceContext *slice = link->dst->priv;

    int y2, ret = 0;



    if (slice_dir == 1) {

        for (y2 = y; y2 + slice->h <= y + h; y2 += slice->h) {

            ret = ff_draw_slice(link->dst->outputs[0], y2, slice->h, slice_dir);

            if (ret < 0)

                return ret;

        }



        if (y2 < y + h)

            return ff_draw_slice(link->dst->outputs[0], y2, y + h - y2, slice_dir);

    } else if (slice_dir == -1) {

        for (y2 = y + h; y2 - slice->h >= y; y2 -= slice->h) {

            ret = ff_draw_slice(link->dst->outputs[0], y2 - slice->h, slice->h, slice_dir);

            if (ret < 0)

                return ret;

        }



        if (y2 > y)

            return ff_draw_slice(link->dst->outputs[0], y, y2 - y, slice_dir);

    }

    return 0;

}

static int read_key(void)

{

#if HAVE_TERMIOS_H

    int n = 1;

    unsigned char ch;

    struct timeval tv;

    fd_set rfds;



    FD_ZERO(&rfds);

    FD_SET(0, &rfds);

    tv.tv_sec = 0;

    tv.tv_usec = 0;

    n = select(1, &rfds, NULL, NULL, &tv);

    if (n > 0) {

        n = read(0, &ch, 1);

        if (n == 1)

            return ch;



        return n;

    }

#elif HAVE_CONIO_H

    if(kbhit())

        return(getch());

#endif

    return -1;

}

int main(int argc, char *argv[])

{

    int fd_in, fd_out, comp_len, uncomp_len, i, last_out;

    char buf_in[1024], buf_out[65536];

    z_stream zstream;

    struct stat statbuf;



    if (argc < 3) {

        printf("Usage: %s <infile.swf> <outfile.swf>\n", argv[0]);

        return 1;

    }



    fd_in = open(argv[1], O_RDONLY);

    if (fd_in < 0) {

        perror("Error opening input file");

        return 1;

    }



    fd_out = open(argv[2], O_WRONLY | O_CREAT, 00644);

    if (fd_out < 0) {

        perror("Error opening output file");

        close(fd_in);

        return 1;

    }



    if (read(fd_in, &buf_in, 8) != 8) {

        printf("Header error\n");

        close(fd_in);

        close(fd_out);

        return 1;

    }



    if (buf_in[0] != 'C' || buf_in[1] != 'W' || buf_in[2] != 'S') {

        printf("Not a compressed flash file\n");

        return 1;

    }



    fstat(fd_in, &statbuf);

    comp_len   = statbuf.st_size;

    uncomp_len = buf_in[4] | (buf_in[5] << 8) | (buf_in[6] << 16) | (buf_in[7] << 24);



    printf("Compressed size: %d Uncompressed size: %d\n",

           comp_len - 4, uncomp_len - 4);



    // write out modified header

    buf_in[0] = 'F';

    if (write(fd_out, &buf_in, 8) < 8) {

        perror("Error writing output file");

        return 1;

    }



    zstream.zalloc = NULL;

    zstream.zfree  = NULL;

    zstream.opaque = NULL;

    if (inflateInit(&zstream) != Z_OK) {

        fprintf(stderr, "inflateInit failed\n");

        return 1;

    }



    for (i = 0; i < comp_len - 8;) {

        int ret, len = read(fd_in, &buf_in, 1024);



        dbgprintf("read %d bytes\n", len);



        last_out = zstream.total_out;



        zstream.next_in   = &buf_in[0];

        zstream.avail_in  = len;

        zstream.next_out  = &buf_out[0];

        zstream.avail_out = 65536;



        ret = inflate(&zstream, Z_SYNC_FLUSH);

        if (ret != Z_STREAM_END && ret != Z_OK) {

            printf("Error while decompressing: %d\n", ret);

            inflateEnd(&zstream);

            return 1;

        }



        dbgprintf("a_in: %d t_in: %lu a_out: %d t_out: %lu -- %lu out\n",

                  zstream.avail_in, zstream.total_in, zstream.avail_out,

                  zstream.total_out, zstream.total_out - last_out);



        if (write(fd_out, &buf_out, zstream.total_out - last_out) <

            zstream.total_out - last_out) {

            perror("Error writing output file");

            return 1;

        }



        i += len;



        if (ret == Z_STREAM_END || ret == Z_BUF_ERROR)

            break;

    }



    if (zstream.total_out != uncomp_len - 8) {

        printf("Size mismatch (%lu != %d), updating header...\n",

               zstream.total_out, uncomp_len - 8);



        buf_in[0] =  (zstream.total_out + 8)        & 0xff;

        buf_in[1] = ((zstream.total_out + 8) >>  8) & 0xff;

        buf_in[2] = ((zstream.total_out + 8) >> 16) & 0xff;

        buf_in[3] = ((zstream.total_out + 8) >> 24) & 0xff;



        if (   lseek(fd_out, 4, SEEK_SET) < 0

            || write(fd_out, &buf_in, 4) < 4) {

            perror("Error writing output file");

            return 1;

        }

    }



    inflateEnd(&zstream);

    close(fd_in);

    close(fd_out);

    return 0;

}

static av_cold int encode_end(AVCodecContext *avctx)

{

    LclEncContext *c = avctx->priv_data;



    av_freep(&avctx->extradata);

    deflateEnd(&c->zstream);



    av_frame_free(&avctx->coded_frame);



    return 0;

}

static int decode_nal_units(H264Context *h, uint8_t *buf, int buf_size){

    MpegEncContext * const s = &h->s;

    AVCodecContext * const avctx= s->avctx;

    int buf_index=0;

#if 0

    int i;

    for(i=0; i<32; i++){

        printf("%X ", buf[i]);

    }

#endif

    for(;;){

        int consumed;

        int dst_length;

        int bit_length;

        uint8_t *ptr;



        // start code prefix search

        for(; buf_index + 3 < buf_size; buf_index++){

            // this should allways succeed in the first iteration

            if(buf[buf_index] == 0 && buf[buf_index+1] == 0 && buf[buf_index+2] == 1)

                break;

        }



        if(buf_index+3 >= buf_size) break;



        buf_index+=3;



        ptr= decode_nal(h, buf + buf_index, &dst_length, &consumed, buf_size - buf_index);

        if(ptr[dst_length - 1] == 0) dst_length--;

        bit_length= 8*dst_length - decode_rbsp_trailing(ptr + dst_length - 1);



        if(s->avctx->debug&FF_DEBUG_STARTCODE){

            av_log(h->s.avctx, AV_LOG_DEBUG, "NAL %d at %d length %d\n", h->nal_unit_type, buf_index, dst_length);

        }



        buf_index += consumed;



        if(h->nal_ref_idc < s->hurry_up)

            continue;



        switch(h->nal_unit_type){

        case NAL_IDR_SLICE:

            idr(h); //FIXME ensure we dont loose some frames if there is reordering

        case NAL_SLICE:

            init_get_bits(&s->gb, ptr, bit_length);

            h->intra_gb_ptr=

            h->inter_gb_ptr= &s->gb;

            s->data_partitioning = 0;



            if(decode_slice_header(h) < 0) return -1;

            if(h->redundant_pic_count==0)

                decode_slice(h);

            break;

        case NAL_DPA:

            init_get_bits(&s->gb, ptr, bit_length);

            h->intra_gb_ptr=

            h->inter_gb_ptr= NULL;

            s->data_partitioning = 1;



            if(decode_slice_header(h) < 0) return -1;

            break;

        case NAL_DPB:

            init_get_bits(&h->intra_gb, ptr, bit_length);

            h->intra_gb_ptr= &h->intra_gb;

            break;

        case NAL_DPC:

            init_get_bits(&h->inter_gb, ptr, bit_length);

            h->inter_gb_ptr= &h->inter_gb;



            if(h->redundant_pic_count==0 && h->intra_gb_ptr && s->data_partitioning)

                decode_slice(h);

            break;

        case NAL_SEI:

            break;

        case NAL_SPS:

            init_get_bits(&s->gb, ptr, bit_length);

            decode_seq_parameter_set(h);



            if(s->flags& CODEC_FLAG_LOW_DELAY)

                s->low_delay=1;



            avctx->has_b_frames= !s->low_delay;

            break;

        case NAL_PPS:

            init_get_bits(&s->gb, ptr, bit_length);



            decode_picture_parameter_set(h);



            break;

        case NAL_PICTURE_DELIMITER:

            break;

        case NAL_FILTER_DATA:

            break;

        }        



        //FIXME move after where irt is set

        s->current_picture.pict_type= s->pict_type;

        s->current_picture.key_frame= s->pict_type == I_TYPE;

    }



    if(!s->current_picture_ptr) return buf_index; //no frame



    h->prev_frame_num_offset= h->frame_num_offset;

    h->prev_frame_num= h->frame_num;

    if(s->current_picture_ptr->reference){

        h->prev_poc_msb= h->poc_msb;

        h->prev_poc_lsb= h->poc_lsb;

    }

    if(s->current_picture_ptr->reference)

        execute_ref_pic_marking(h, h->mmco, h->mmco_index);

    else

        assert(h->mmco_index==0);



    ff_er_frame_end(s);



    if( h->disable_deblocking_filter_idc != 1 ) {

        filter_frame( h );

    }



    MPV_frame_end(s);



    return buf_index;

}

static int rd_frame(CinepakEncContext *s, const AVFrame *frame, int isakeyframe, unsigned char *buf, int buf_size)

{

    int num_strips, strip, i, y, nexty, size, temp_size, best_size;

    AVPicture last_pict, pict, scratch_pict;

    int64_t best_score = 0, score, score_temp;

#ifdef CINEPAK_REPORT_SERR

    int64_t best_serr = 0, serr, serr_temp;

#endif



    int best_nstrips;



    if(s->pix_fmt == AV_PIX_FMT_RGB24) {

        int x;

// build a copy of the given frame in the correct colorspace

        for(y = 0; y < s->h; y += 2) {

            for(x = 0; x < s->w; x += 2) {

                uint8_t *ir[2]; int32_t r, g, b, rr, gg, bb;

                ir[0] = ((AVPicture*)frame)->data[0] + x*3 + y*((AVPicture*)frame)->linesize[0];

                ir[1] = ir[0] + ((AVPicture*)frame)->linesize[0];

                get_sub_picture(s, x, y, (AVPicture*)s->input_frame, &scratch_pict);

                r = g = b = 0;

                for(i=0; i<4; ++i) {

                    int i1, i2;

                    i1 = (i&1); i2 = (i>=2);

                    rr = ir[i2][i1*3+0];

                    gg = ir[i2][i1*3+1];

                    bb = ir[i2][i1*3+2];

                    r += rr; g += gg; b += bb;

// using fixed point arithmetic for portable repeatability, scaling by 2^23

// "Y"

//                    rr = 0.2857*rr + 0.5714*gg + 0.1429*bb;

                    rr = (2396625*rr + 4793251*gg + 1198732*bb) >> 23;

                    if(      rr <   0) rr =   0;

                    else if (rr > 255) rr = 255;

                    scratch_pict.data[0][i1 + i2*scratch_pict.linesize[0]] = rr;

                }

// let us scale down as late as possible

//                r /= 4; g /= 4; b /= 4;

// "U"

//                rr = -0.1429*r - 0.2857*g + 0.4286*b;

                rr = (-299683*r - 599156*g + 898839*b) >> 23;

                if(      rr < -128) rr = -128;

                else if (rr >  127) rr =  127;

                scratch_pict.data[1][0] = rr + 128; // quantize needs unsigned

// "V"

//                rr = 0.3571*r - 0.2857*g - 0.0714*b;

                rr = (748893*r - 599156*g - 149737*b) >> 23;

                if(      rr < -128) rr = -128;

                else if (rr >  127) rr =  127;

                scratch_pict.data[2][0] = rr + 128; // quantize needs unsigned

            }

        }

    }



    //would be nice but quite certainly incompatible with vintage players:

    // support encoding zero strips (meaning skip the whole frame)

    for(num_strips = s->min_strips; num_strips <= s->max_strips && num_strips <= s->h / MB_SIZE; num_strips++) {

        score = 0;

        size = 0;

#ifdef CINEPAK_REPORT_SERR

        serr = 0;

#endif



        for(y = 0, strip = 1; y < s->h; strip++, y = nexty) {

            int strip_height;



            nexty = strip * s->h / num_strips; // <= s->h

            //make nexty the next multiple of 4 if not already there

            if(nexty & 3)

                nexty += 4 - (nexty & 3);



            strip_height = nexty - y;

            if(strip_height <= 0) { // can this ever happen?

                av_log(s->avctx, AV_LOG_INFO, "skipping zero height strip %i of %i\n", strip, num_strips);

                continue;

            }



            if(s->pix_fmt == AV_PIX_FMT_RGB24)

                get_sub_picture(s, 0, y, (AVPicture*)s->input_frame,    &pict);

            else

                get_sub_picture(s, 0, y, (AVPicture*)frame,              &pict);

            get_sub_picture(s, 0, y, (AVPicture*)s->last_frame,    &last_pict);

            get_sub_picture(s, 0, y, (AVPicture*)s->scratch_frame, &scratch_pict);



            if((temp_size = rd_strip(s, y, strip_height, isakeyframe, &last_pict, &pict, &scratch_pict, s->frame_buf + size + CVID_HEADER_SIZE, &score_temp

#ifdef CINEPAK_REPORT_SERR

, &serr_temp

#endif

)) < 0)

                return temp_size;



            score += score_temp;

#ifdef CINEPAK_REPORT_SERR

            serr += serr_temp;

#endif

            size += temp_size;

            //av_log(s->avctx, AV_LOG_INFO, "strip %d, isakeyframe=%d", strip, isakeyframe);

            //av_log(s->avctx, AV_LOG_INFO, "\n");

        }



        if(best_score == 0 || score < best_score) {

            best_score = score;

#ifdef CINEPAK_REPORT_SERR

            best_serr = serr;

#endif

            best_size = size + write_cvid_header(s, s->frame_buf, num_strips, size, isakeyframe);

            //av_log(s->avctx, AV_LOG_INFO, "best number of strips so far: %2i, %12lli, %i B\n", num_strips, (long long int)score, best_size);

#ifdef CINEPAK_REPORT_SERR

            av_log(s->avctx, AV_LOG_INFO, "best number of strips so far: %2i, %12lli, %i B\n", num_strips, (long long int)serr, best_size);

#endif



            FFSWAP(AVFrame *, s->best_frame, s->scratch_frame);

            memcpy(buf, s->frame_buf, best_size);

            best_nstrips = num_strips;

        }

// avoid trying too many strip numbers without a real reason

// (this makes the processing of the very first frame faster)

        if(num_strips - best_nstrips > 4)

            break;

    }



// let the number of strips slowly adapt to the changes in the contents,

// compared to full bruteforcing every time this will occasionally lead

// to some r/d performance loss but makes encoding up to several times faster

    if(!s->strip_number_delta_range) {

        if(best_nstrips == s->max_strips) { // let us try to step up

            s->max_strips = best_nstrips + 1;

            if(s->max_strips >= s->max_max_strips)

                s->max_strips = s->max_max_strips;

        } else { // try to step down

            s->max_strips = best_nstrips;

        }

        s->min_strips = s->max_strips - 1;

        if(s->min_strips < s->min_min_strips)

            s->min_strips = s->min_min_strips;

    } else {

        s->max_strips = best_nstrips + s->strip_number_delta_range;

        if(s->max_strips >= s->max_max_strips)

            s->max_strips = s->max_max_strips;

        s->min_strips = best_nstrips - s->strip_number_delta_range;

        if(s->min_strips < s->min_min_strips)

            s->min_strips = s->min_min_strips;

    }



    return best_size;

}

