static int update_frame_pool(AVCodecContext *avctx, AVFrame *frame)

{

    FramePool *pool = avctx->internal->pool;

    int i, ret;



    switch (avctx->codec_type) {

    case AVMEDIA_TYPE_VIDEO: {

        uint8_t *data[4];

        int linesize[4];

        int size[4] = { 0 };

        int w = frame->width;

        int h = frame->height;

        int tmpsize, unaligned;



        if (pool->format == frame->format &&

            pool->width == frame->width && pool->height == frame->height)

            return 0;



        avcodec_align_dimensions2(avctx, &w, &h, pool->stride_align);



        do {

            // NOTE: do not align linesizes individually, this breaks e.g. assumptions

            // that linesize[0] == 2*linesize[1] in the MPEG-encoder for 4:2:2

            av_image_fill_linesizes(linesize, avctx->pix_fmt, w);

            // increase alignment of w for next try (rhs gives the lowest bit set in w)

            w += w & ~(w - 1);



            unaligned = 0;

            for (i = 0; i < 4; i++)

                unaligned |= linesize[i] % pool->stride_align[i];

        } while (unaligned);



        tmpsize = av_image_fill_pointers(data, avctx->pix_fmt, h,

                                         NULL, linesize);

        if (tmpsize < 0)

            return -1;



        for (i = 0; i < 3 && data[i + 1]; i++)

            size[i] = data[i + 1] - data[i];

        size[i] = tmpsize - (data[i] - data[0]);



        for (i = 0; i < 4; i++) {

            av_buffer_pool_uninit(&pool->pools[i]);

            pool->linesize[i] = linesize[i];

            if (size[i]) {

                pool->pools[i] = av_buffer_pool_init(size[i] + 16 + STRIDE_ALIGN - 1,

                                                     CONFIG_MEMORY_POISONING ?

                                                        NULL :

                                                        av_buffer_allocz);

                if (!pool->pools[i]) {

                    ret = AVERROR(ENOMEM);

                    goto fail;

                }

            }

        }

        pool->format = frame->format;

        pool->width  = frame->width;

        pool->height = frame->height;



        break;

        }

    case AVMEDIA_TYPE_AUDIO: {

        int ch     = av_frame_get_channels(frame); //av_get_channel_layout_nb_channels(frame->channel_layout);

        int planar = av_sample_fmt_is_planar(frame->format);

        int planes = planar ? ch : 1;



        if (pool->format == frame->format && pool->planes == planes &&

            pool->channels == ch && frame->nb_samples == pool->samples)

            return 0;



        av_buffer_pool_uninit(&pool->pools[0]);

        ret = av_samples_get_buffer_size(&pool->linesize[0], ch,

                                         frame->nb_samples, frame->format, 0);

        if (ret < 0)

            goto fail;



        pool->pools[0] = av_buffer_pool_init(pool->linesize[0], NULL);

        if (!pool->pools[0]) {

            ret = AVERROR(ENOMEM);

            goto fail;

        }



        pool->format     = frame->format;

        pool->planes     = planes;

        pool->channels   = ch;

        pool->samples = frame->nb_samples;

        break;

        }

    default: av_assert0(0);

    }

    return 0;

fail:

    for (i = 0; i < 4; i++)

        av_buffer_pool_uninit(&pool->pools[i]);

    pool->format = -1;

    pool->planes = pool->channels = pool->samples = 0;

    pool->width  = pool->height = 0;

    return ret;

}

static void filter_mb(VP8Context *s, uint8_t *dst[3], VP8Macroblock *mb, int mb_x, int mb_y)

{

    int filter_level, inner_limit, hev_thresh, mbedge_lim, bedge_lim;



    filter_level_for_mb(s, mb, &filter_level, &inner_limit, &hev_thresh);

    if (!filter_level)

        return;



    mbedge_lim = 2*(filter_level+2) + inner_limit;

     bedge_lim = 2* filter_level    + inner_limit;



    if (mb_x) {

        s->vp8dsp.vp8_h_loop_filter16(dst[0], s->linesize,   mbedge_lim, inner_limit, hev_thresh);

        s->vp8dsp.vp8_h_loop_filter8 (dst[1], s->uvlinesize, mbedge_lim, inner_limit, hev_thresh);

        s->vp8dsp.vp8_h_loop_filter8 (dst[2], s->uvlinesize, mbedge_lim, inner_limit, hev_thresh);

    }



    if (!mb->skip || mb->mode == MODE_I4x4 || mb->mode == VP8_MVMODE_SPLIT) {

        s->vp8dsp.vp8_h_loop_filter16_inner(dst[0]+ 4, s->linesize,   bedge_lim, inner_limit, hev_thresh);

        s->vp8dsp.vp8_h_loop_filter16_inner(dst[0]+ 8, s->linesize,   bedge_lim, inner_limit, hev_thresh);

        s->vp8dsp.vp8_h_loop_filter16_inner(dst[0]+12, s->linesize,   bedge_lim, inner_limit, hev_thresh);

        s->vp8dsp.vp8_h_loop_filter8_inner (dst[1]+ 4, s->uvlinesize, bedge_lim, inner_limit, hev_thresh);

        s->vp8dsp.vp8_h_loop_filter8_inner (dst[2]+ 4, s->uvlinesize, bedge_lim, inner_limit, hev_thresh);

    }



    if (mb_y) {

        s->vp8dsp.vp8_v_loop_filter16(dst[0], s->linesize,   mbedge_lim, inner_limit, hev_thresh);

        s->vp8dsp.vp8_v_loop_filter8 (dst[1], s->uvlinesize, mbedge_lim, inner_limit, hev_thresh);

        s->vp8dsp.vp8_v_loop_filter8 (dst[2], s->uvlinesize, mbedge_lim, inner_limit, hev_thresh);

    }



    if (!mb->skip || mb->mode == MODE_I4x4 || mb->mode == VP8_MVMODE_SPLIT) {

        s->vp8dsp.vp8_v_loop_filter16_inner(dst[0]+ 4*s->linesize,   s->linesize,   bedge_lim, inner_limit, hev_thresh);

        s->vp8dsp.vp8_v_loop_filter16_inner(dst[0]+ 8*s->linesize,   s->linesize,   bedge_lim, inner_limit, hev_thresh);

        s->vp8dsp.vp8_v_loop_filter16_inner(dst[0]+12*s->linesize,   s->linesize,   bedge_lim, inner_limit, hev_thresh);

        s->vp8dsp.vp8_v_loop_filter8_inner (dst[1]+ 4*s->uvlinesize, s->uvlinesize, bedge_lim, inner_limit, hev_thresh);

        s->vp8dsp.vp8_v_loop_filter8_inner (dst[2]+ 4*s->uvlinesize, s->uvlinesize, bedge_lim, inner_limit, hev_thresh);

    }

}

static int yuv4_read_header(AVFormatContext *s)

{

    char header[MAX_YUV4_HEADER + 10];  // Include headroom for

                                        // the longest option

    char *tokstart, *tokend, *header_end;

    int i;

    AVIOContext *pb = s->pb;

    int width = -1, height  = -1, raten   = 0,

        rated =  0, aspectn =  0, aspectd = 0;

    enum AVPixelFormat pix_fmt = AV_PIX_FMT_NONE, alt_pix_fmt = AV_PIX_FMT_NONE;

    enum AVChromaLocation chroma_sample_location = AVCHROMA_LOC_UNSPECIFIED;

    AVStream *st;

    enum AVFieldOrder field_order;



    for (i = 0; i < MAX_YUV4_HEADER; i++) {

        header[i] = avio_r8(pb);

        if (header[i] == '\n') {

            header[i + 1] = 0x20;  // Add a space after last option.

                                   // Makes parsing "444" vs "444alpha" easier.

            header[i + 2] = 0;

            break;

        }

    }

    if (i == MAX_YUV4_HEADER)

        return -1;

    if (strncmp(header, Y4M_MAGIC, strlen(Y4M_MAGIC)))

        return -1;



    header_end = &header[i + 1]; // Include space

    for (tokstart = &header[strlen(Y4M_MAGIC) + 1];

         tokstart < header_end; tokstart++) {

        if (*tokstart == 0x20)

            continue;

        switch (*tokstart++) {

        case 'W': // Width. Required.

            width    = strtol(tokstart, &tokend, 10);

            tokstart = tokend;

            break;

        case 'H': // Height. Required.

            height   = strtol(tokstart, &tokend, 10);

            tokstart = tokend;

            break;

        case 'C': // Color space

            if (strncmp("420jpeg", tokstart, 7) == 0) {

                pix_fmt = AV_PIX_FMT_YUV420P;

                chroma_sample_location = AVCHROMA_LOC_CENTER;

            } else if (strncmp("420mpeg2", tokstart, 8) == 0) {

                pix_fmt = AV_PIX_FMT_YUV420P;

                chroma_sample_location = AVCHROMA_LOC_LEFT;

            } else if (strncmp("420paldv", tokstart, 8) == 0) {

                pix_fmt = AV_PIX_FMT_YUV420P;

                chroma_sample_location = AVCHROMA_LOC_TOPLEFT;

            } else if (strncmp("420p16", tokstart, 6) == 0) {

                pix_fmt = AV_PIX_FMT_YUV420P16;

            } else if (strncmp("422p16", tokstart, 6) == 0) {

                pix_fmt = AV_PIX_FMT_YUV422P16;

            } else if (strncmp("444p16", tokstart, 6) == 0) {

                pix_fmt = AV_PIX_FMT_YUV444P16;

            } else if (strncmp("420p14", tokstart, 6) == 0) {

                pix_fmt = AV_PIX_FMT_YUV420P14;

            } else if (strncmp("422p14", tokstart, 6) == 0) {

                pix_fmt = AV_PIX_FMT_YUV422P14;

            } else if (strncmp("444p14", tokstart, 6) == 0) {

                pix_fmt = AV_PIX_FMT_YUV444P14;

            } else if (strncmp("420p12", tokstart, 6) == 0) {

                pix_fmt = AV_PIX_FMT_YUV420P12;

            } else if (strncmp("422p12", tokstart, 6) == 0) {

                pix_fmt = AV_PIX_FMT_YUV422P12;

            } else if (strncmp("444p12", tokstart, 6) == 0) {

                pix_fmt = AV_PIX_FMT_YUV444P12;

            } else if (strncmp("420p10", tokstart, 6) == 0) {

                pix_fmt = AV_PIX_FMT_YUV420P10;

            } else if (strncmp("422p10", tokstart, 6) == 0) {

                pix_fmt = AV_PIX_FMT_YUV422P10;

            } else if (strncmp("444p10", tokstart, 6) == 0) {

                pix_fmt = AV_PIX_FMT_YUV444P10;

            } else if (strncmp("420p9", tokstart, 5) == 0) {

                pix_fmt = AV_PIX_FMT_YUV420P9;

            } else if (strncmp("422p9", tokstart, 5) == 0) {

                pix_fmt = AV_PIX_FMT_YUV422P9;

            } else if (strncmp("444p9", tokstart, 5) == 0) {

                pix_fmt = AV_PIX_FMT_YUV444P9;

            } else if (strncmp("420", tokstart, 3) == 0) {

                pix_fmt = AV_PIX_FMT_YUV420P;

                chroma_sample_location = AVCHROMA_LOC_CENTER;

            } else if (strncmp("411", tokstart, 3) == 0) {

                pix_fmt = AV_PIX_FMT_YUV411P;

            } else if (strncmp("422", tokstart, 3) == 0) {

                pix_fmt = AV_PIX_FMT_YUV422P;

            } else if (strncmp("444alpha", tokstart, 8) == 0 ) {

                av_log(s, AV_LOG_ERROR, "Cannot handle 4:4:4:4 "

                       "YUV4MPEG stream.\n");

                return -1;

            } else if (strncmp("444", tokstart, 3) == 0) {

                pix_fmt = AV_PIX_FMT_YUV444P;

            } else if (strncmp("mono16", tokstart, 6) == 0) {

                pix_fmt = AV_PIX_FMT_GRAY16;

            } else if (strncmp("mono", tokstart, 4) == 0) {

                pix_fmt = AV_PIX_FMT_GRAY8;

            } else {

                av_log(s, AV_LOG_ERROR, "YUV4MPEG stream contains an unknown "

                       "pixel format.\n");

                return -1;

            }

            while (tokstart < header_end && *tokstart != 0x20)

                tokstart++;

            break;

        case 'I': // Interlace type

            switch (*tokstart++){

            case '?':

                field_order = AV_FIELD_UNKNOWN;

                break;

            case 'p':

                field_order = AV_FIELD_PROGRESSIVE;

                break;

            case 't':

                field_order = AV_FIELD_TT;

                break;

            case 'b':

                field_order = AV_FIELD_BB;

                break;

            case 'm':

                av_log(s, AV_LOG_ERROR, "YUV4MPEG stream contains mixed "

                       "interlaced and non-interlaced frames.\n");

            default:

                av_log(s, AV_LOG_ERROR, "YUV4MPEG has invalid header.\n");

                return AVERROR(EINVAL);

            }

            break;

        case 'F': // Frame rate

            sscanf(tokstart, "%d:%d", &raten, &rated); // 0:0 if unknown

            while (tokstart < header_end && *tokstart != 0x20)

                tokstart++;

            break;

        case 'A': // Pixel aspect

            sscanf(tokstart, "%d:%d", &aspectn, &aspectd); // 0:0 if unknown

            while (tokstart < header_end && *tokstart != 0x20)

                tokstart++;

            break;

        case 'X': // Vendor extensions

            if (strncmp("YSCSS=", tokstart, 6) == 0) {

                // Older nonstandard pixel format representation

                tokstart += 6;

                if (strncmp("420JPEG", tokstart, 7) == 0)

                    alt_pix_fmt = AV_PIX_FMT_YUV420P;

                else if (strncmp("420MPEG2", tokstart, 8) == 0)

                    alt_pix_fmt = AV_PIX_FMT_YUV420P;

                else if (strncmp("420PALDV", tokstart, 8) == 0)

                    alt_pix_fmt = AV_PIX_FMT_YUV420P;

                else if (strncmp("420P9", tokstart, 5) == 0)

                    alt_pix_fmt = AV_PIX_FMT_YUV420P9;

                else if (strncmp("422P9", tokstart, 5) == 0)

                    alt_pix_fmt = AV_PIX_FMT_YUV422P9;

                else if (strncmp("444P9", tokstart, 5) == 0)

                    alt_pix_fmt = AV_PIX_FMT_YUV444P9;

                else if (strncmp("420P10", tokstart, 6) == 0)

                    alt_pix_fmt = AV_PIX_FMT_YUV420P10;

                else if (strncmp("422P10", tokstart, 6) == 0)

                    alt_pix_fmt = AV_PIX_FMT_YUV422P10;

                else if (strncmp("444P10", tokstart, 6) == 0)

                    alt_pix_fmt = AV_PIX_FMT_YUV444P10;

                else if (strncmp("420P12", tokstart, 6) == 0)

                    alt_pix_fmt = AV_PIX_FMT_YUV420P12;

                else if (strncmp("422P12", tokstart, 6) == 0)

                    alt_pix_fmt = AV_PIX_FMT_YUV422P12;

                else if (strncmp("444P12", tokstart, 6) == 0)

                    alt_pix_fmt = AV_PIX_FMT_YUV444P12;

                else if (strncmp("420P14", tokstart, 6) == 0)

                    alt_pix_fmt = AV_PIX_FMT_YUV420P14;

                else if (strncmp("422P14", tokstart, 6) == 0)

                    alt_pix_fmt = AV_PIX_FMT_YUV422P14;

                else if (strncmp("444P14", tokstart, 6) == 0)

                    alt_pix_fmt = AV_PIX_FMT_YUV444P14;

                else if (strncmp("420P16", tokstart, 6) == 0)

                    alt_pix_fmt = AV_PIX_FMT_YUV420P16;

                else if (strncmp("422P16", tokstart, 6) == 0)

                    alt_pix_fmt = AV_PIX_FMT_YUV422P16;

                else if (strncmp("444P16", tokstart, 6) == 0)

                    alt_pix_fmt = AV_PIX_FMT_YUV444P16;

                else if (strncmp("411", tokstart, 3) == 0)

                    alt_pix_fmt = AV_PIX_FMT_YUV411P;

                else if (strncmp("422", tokstart, 3) == 0)

                    alt_pix_fmt = AV_PIX_FMT_YUV422P;

                else if (strncmp("444", tokstart, 3) == 0)

                    alt_pix_fmt = AV_PIX_FMT_YUV444P;

            }

            while (tokstart < header_end && *tokstart != 0x20)

                tokstart++;

            break;

        }

    }



    if (width == -1 || height == -1) {

        av_log(s, AV_LOG_ERROR, "YUV4MPEG has invalid header.\n");

        return -1;

    }



    if (pix_fmt == AV_PIX_FMT_NONE) {

        if (alt_pix_fmt == AV_PIX_FMT_NONE)

            pix_fmt = AV_PIX_FMT_YUV420P;

        else

            pix_fmt = alt_pix_fmt;

    }



    if (raten <= 0 || rated <= 0) {

        // Frame rate unknown

        raten = 25;

        rated = 1;

    }



    if (aspectn == 0 && aspectd == 0) {

        // Pixel aspect unknown

        aspectd = 1;

    }



    st = avformat_new_stream(s, NULL);

    if (!st)

        return AVERROR(ENOMEM);

    st->codec->width  = width;

    st->codec->height = height;

    av_reduce(&raten, &rated, raten, rated, (1UL << 31) - 1);

    avpriv_set_pts_info(st, 64, rated, raten);

    st->avg_frame_rate                = av_inv_q(st->time_base);

    st->codec->pix_fmt                = pix_fmt;

    st->codec->codec_type             = AVMEDIA_TYPE_VIDEO;

    st->codec->codec_id               = AV_CODEC_ID_RAWVIDEO;

    st->sample_aspect_ratio           = (AVRational){ aspectn, aspectd };

    st->codec->chroma_sample_location = chroma_sample_location;

    st->codec->field_order            = field_order;



    return 0;

}

