static int adaptive_cb_search(const int16_t *adapt_cb, float *work,

                              const float *coefs, float *data)

{

    int i, best_vect;

    float score, gain, best_score, best_gain;

    float exc[BLOCKSIZE];



    gain = best_score = 0;

    for (i = BLOCKSIZE / 2; i <= BUFFERSIZE; i++) {

        create_adapt_vect(exc, adapt_cb, i);

        get_match_score(work, coefs, exc, NULL, NULL, data, &score, &gain);

        if (score > best_score) {

            best_score = score;

            best_vect = i;

            best_gain = gain;

        }

    }

    if (!best_score)

        return 0;



    /**

     * Re-calculate the filtered vector from the vector with maximum match score

     * and remove its contribution from input data.

     */

    create_adapt_vect(exc, adapt_cb, best_vect);

    ff_celp_lp_synthesis_filterf(work, coefs, exc, BLOCKSIZE, LPC_ORDER);

    for (i = 0; i < BLOCKSIZE; i++)

        data[i] -= best_gain * work[i];

    return best_vect - BLOCKSIZE / 2 + 1;

}

static int transcode(void)

{

    int ret, i;

    AVFormatContext *is, *os;

    OutputStream *ost;

    InputStream *ist;

    uint8_t *no_packet;

    int no_packet_count = 0;

    int64_t timer_start;



    if (!(no_packet = av_mallocz(nb_input_files)))

        exit_program(1);



    ret = transcode_init();

    if (ret < 0)

        goto fail;



    av_log(NULL, AV_LOG_INFO, "Press ctrl-c to stop encoding\n");

    term_init();



    timer_start = av_gettime();



    for (; received_sigterm == 0;) {

        int file_index, ist_index, past_recording_time = 1;

        AVPacket pkt;

        int64_t ipts_min;



        ipts_min = INT64_MAX;



        /* check if there's any stream where output is still needed */

        for (i = 0; i < nb_output_streams; i++) {

            OutputFile *of;

            ost = output_streams[i];

            of  = output_files[ost->file_index];

            os  = output_files[ost->file_index]->ctx;

            if (ost->is_past_recording_time ||

                (os->pb && avio_tell(os->pb) >= of->limit_filesize))

                continue;

            if (ost->frame_number > ost->max_frames) {

                int j;

                for (j = 0; j < of->ctx->nb_streams; j++)

                    output_streams[of->ost_index + j]->is_past_recording_time = 1;

                continue;

            }

            past_recording_time = 0;

        }

        if (past_recording_time)

            break;



        /* select the stream that we must read now by looking at the

           smallest output pts */

        file_index = -1;

        for (i = 0; i < nb_input_streams; i++) {

            int64_t ipts;

            ist = input_streams[i];

            ipts = ist->last_dts;

            if (ist->discard || no_packet[ist->file_index])

                continue;

            if (!input_files[ist->file_index]->eof_reached) {

                if (ipts < ipts_min) {

                    ipts_min = ipts;

                    file_index = ist->file_index;

                }

            }

        }

        /* if none, if is finished */

        if (file_index < 0) {

            if (no_packet_count) {

                no_packet_count = 0;

                memset(no_packet, 0, nb_input_files);

                usleep(10000);

                continue;

            }

            break;

        }



        /* read a frame from it and output it in the fifo */

        is  = input_files[file_index]->ctx;

        ret = av_read_frame(is, &pkt);

        if (ret == AVERROR(EAGAIN)) {

            no_packet[file_index] = 1;

            no_packet_count++;

            continue;

        }

        if (ret < 0) {

            input_files[file_index]->eof_reached = 1;



            for (i = 0; i < input_files[file_index]->nb_streams; i++) {

                ist = input_streams[input_files[file_index]->ist_index + i];

                if (ist->decoding_needed)

                    output_packet(ist, NULL);

            }



            if (opt_shortest)

                break;

            else

                continue;

        }



        no_packet_count = 0;

        memset(no_packet, 0, nb_input_files);



        if (do_pkt_dump) {

            av_pkt_dump_log2(NULL, AV_LOG_DEBUG, &pkt, do_hex_dump,

                             is->streams[pkt.stream_index]);

        }

        /* the following test is needed in case new streams appear

           dynamically in stream : we ignore them */

        if (pkt.stream_index >= input_files[file_index]->nb_streams)

            goto discard_packet;

        ist_index = input_files[file_index]->ist_index + pkt.stream_index;

        ist = input_streams[ist_index];

        if (ist->discard)

            goto discard_packet;



        if (pkt.dts != AV_NOPTS_VALUE)

            pkt.dts += av_rescale_q(input_files[ist->file_index]->ts_offset, AV_TIME_BASE_Q, ist->st->time_base);

        if (pkt.pts != AV_NOPTS_VALUE)

            pkt.pts += av_rescale_q(input_files[ist->file_index]->ts_offset, AV_TIME_BASE_Q, ist->st->time_base);



        if (pkt.pts != AV_NOPTS_VALUE)

            pkt.pts *= ist->ts_scale;

        if (pkt.dts != AV_NOPTS_VALUE)

            pkt.dts *= ist->ts_scale;



        //fprintf(stderr, "next:%"PRId64" dts:%"PRId64" off:%"PRId64" %d\n",

        //        ist->next_dts,

        //        pkt.dts, input_files[ist->file_index].ts_offset,

        //        ist->st->codec->codec_type);

        if (pkt.dts != AV_NOPTS_VALUE && ist->next_dts != AV_NOPTS_VALUE

            && (is->iformat->flags & AVFMT_TS_DISCONT)) {

            int64_t pkt_dts = av_rescale_q(pkt.dts, ist->st->time_base, AV_TIME_BASE_Q);

            int64_t delta   = pkt_dts - ist->next_dts;

            if ((FFABS(delta) > 1LL * dts_delta_threshold * AV_TIME_BASE || pkt_dts + 1 < ist->last_dts) && !copy_ts) {

                input_files[ist->file_index]->ts_offset -= delta;

                av_log(NULL, AV_LOG_DEBUG,

                       "timestamp discontinuity %"PRId64", new offset= %"PRId64"\n",

                       delta, input_files[ist->file_index]->ts_offset);

                pkt.dts-= av_rescale_q(delta, AV_TIME_BASE_Q, ist->st->time_base);

                if (pkt.pts != AV_NOPTS_VALUE)

                    pkt.pts-= av_rescale_q(delta, AV_TIME_BASE_Q, ist->st->time_base);

            }

        }



        // fprintf(stderr,"read #%d.%d size=%d\n", ist->file_index, ist->st->index, pkt.size);

        if (output_packet(ist, &pkt) < 0 || poll_filters() < 0) {

            av_log(NULL, AV_LOG_ERROR, "Error while decoding stream #%d:%d\n",

                   ist->file_index, ist->st->index);

            if (exit_on_error)

                exit_program(1);

            av_free_packet(&pkt);

            continue;

        }



    discard_packet:

        av_free_packet(&pkt);



        /* dump report by using the output first video and audio streams */

        print_report(0, timer_start);

    }



    /* at the end of stream, we must flush the decoder buffers */

    for (i = 0; i < nb_input_streams; i++) {

        ist = input_streams[i];

        if (!input_files[ist->file_index]->eof_reached && ist->decoding_needed) {

            output_packet(ist, NULL);

        }

    }

    poll_filters();

    flush_encoders();



    term_exit();



    /* write the trailer if needed and close file */

    for (i = 0; i < nb_output_files; i++) {

        os = output_files[i]->ctx;

        av_write_trailer(os);

    }



    /* dump report by using the first video and audio streams */

    print_report(1, timer_start);



    /* close each encoder */

    for (i = 0; i < nb_output_streams; i++) {

        ost = output_streams[i];

        if (ost->encoding_needed) {

            av_freep(&ost->st->codec->stats_in);

            avcodec_close(ost->st->codec);

        }

    }



    /* close each decoder */

    for (i = 0; i < nb_input_streams; i++) {

        ist = input_streams[i];

        if (ist->decoding_needed) {

            avcodec_close(ist->st->codec);

        }

    }



    /* finished ! */

    ret = 0;



 fail:

    av_freep(&no_packet);



    if (output_streams) {

        for (i = 0; i < nb_output_streams; i++) {

            ost = output_streams[i];

            if (ost) {

                if (ost->stream_copy)

                    av_freep(&ost->st->codec->extradata);

                if (ost->logfile) {

                    fclose(ost->logfile);

                    ost->logfile = NULL;

                }

                av_fifo_free(ost->fifo); /* works even if fifo is not

                                             initialized but set to zero */

                av_freep(&ost->st->codec->subtitle_header);

                av_free(ost->forced_kf_pts);

                if (ost->avr)

                    avresample_free(&ost->avr);

                av_dict_free(&ost->opts);

            }

        }

    }

    return ret;

}

static inline void doVertLowPass_altivec(uint8_t *src, int stride, PPContext *c) {

    /*

    this code makes no assumption on src or stride.

    One could remove the recomputation of the perm

    vector by assuming (stride % 16) == 0, unfortunately

    this is not always true. Quite a lot of load/stores

    can be removed by assuming proper alignment of

    src & stride :-(

    */

    uint8_t *src2 = src;

    const vector signed int zero = vec_splat_s32(0);

    const int properStride = (stride % 16);

    const int srcAlign = ((unsigned long)src2 % 16);

    DECLARE_ALIGNED(16, short, qp[8]) = {c->QP};

    vector signed short vqp = vec_ld(0, qp);

    vector signed short vb0, vb1, vb2, vb3, vb4, vb5, vb6, vb7, vb8, vb9;

    vector unsigned char vbA0, vbA1, vbA2, vbA3, vbA4, vbA5, vbA6, vbA7, vbA8, vbA9;

    vector unsigned char vbB0, vbB1, vbB2, vbB3, vbB4, vbB5, vbB6, vbB7, vbB8, vbB9;

    vector unsigned char vbT0, vbT1, vbT2, vbT3, vbT4, vbT5, vbT6, vbT7, vbT8, vbT9;

    vector unsigned char perml0, perml1, perml2, perml3, perml4,

                         perml5, perml6, perml7, perml8, perml9;

    register int j0 = 0,

                 j1 = stride,

                 j2 = 2 * stride,

                 j3 = 3 * stride,

                 j4 = 4 * stride,

                 j5 = 5 * stride,

                 j6 = 6 * stride,

                 j7 = 7 * stride,

                 j8 = 8 * stride,

                 j9 = 9 * stride;



    vqp = vec_splat(vqp, 0);



    src2 += stride*3;



#define LOAD_LINE(i)                                                    \

    perml##i = vec_lvsl(i * stride, src2);                              \

    vbA##i = vec_ld(i * stride, src2);                                  \

    vbB##i = vec_ld(i * stride + 16, src2);                             \

    vbT##i = vec_perm(vbA##i, vbB##i, perml##i);                        \

    vb##i =                                                             \

        (vector signed short)vec_mergeh((vector unsigned char)zero,     \

                                        (vector unsigned char)vbT##i)



#define LOAD_LINE_ALIGNED(i)                                            \

    vbT##i = vec_ld(j##i, src2);                                        \

    vb##i =                                                             \

        (vector signed short)vec_mergeh((vector signed char)zero,       \

                                        (vector signed char)vbT##i)



      /* Special-casing the aligned case is worthwhile, as all calls from

       * the (transposed) horizontable deblocks will be aligned, in addition

       * to the naturally aligned vertical deblocks. */

    if (properStride && srcAlign) {

          LOAD_LINE_ALIGNED(0);

          LOAD_LINE_ALIGNED(1);

          LOAD_LINE_ALIGNED(2);

          LOAD_LINE_ALIGNED(3);

          LOAD_LINE_ALIGNED(4);

          LOAD_LINE_ALIGNED(5);

          LOAD_LINE_ALIGNED(6);

          LOAD_LINE_ALIGNED(7);

          LOAD_LINE_ALIGNED(8);

          LOAD_LINE_ALIGNED(9);

    } else {

          LOAD_LINE(0);

          LOAD_LINE(1);

          LOAD_LINE(2);

          LOAD_LINE(3);

          LOAD_LINE(4);

          LOAD_LINE(5);

          LOAD_LINE(6);

          LOAD_LINE(7);

          LOAD_LINE(8);

          LOAD_LINE(9);

    }

#undef LOAD_LINE

#undef LOAD_LINE_ALIGNED

    {

        const vector unsigned short v_2 = vec_splat_u16(2);

        const vector unsigned short v_4 = vec_splat_u16(4);



        const vector signed short v_diff01 = vec_sub(vb0, vb1);

        const vector unsigned short v_cmp01 =

            (const vector unsigned short) vec_cmplt(vec_abs(v_diff01), vqp);

        const vector signed short v_first = vec_sel(vb1, vb0, v_cmp01);

        const vector signed short v_diff89 = vec_sub(vb8, vb9);

        const vector unsigned short v_cmp89 =

            (const vector unsigned short) vec_cmplt(vec_abs(v_diff89), vqp);

        const vector signed short v_last = vec_sel(vb8, vb9, v_cmp89);



        const vector signed short temp01 = vec_mladd(v_first, (vector signed short)v_4, vb1);

        const vector signed short temp02 = vec_add(vb2, vb3);

        const vector signed short temp03 = vec_add(temp01, (vector signed short)v_4);

        const vector signed short v_sumsB0 = vec_add(temp02, temp03);



        const vector signed short temp11 = vec_sub(v_sumsB0, v_first);

        const vector signed short v_sumsB1 = vec_add(temp11, vb4);



        const vector signed short temp21 = vec_sub(v_sumsB1, v_first);

        const vector signed short v_sumsB2 = vec_add(temp21, vb5);



        const vector signed short temp31 = vec_sub(v_sumsB2, v_first);

        const vector signed short v_sumsB3 = vec_add(temp31, vb6);



        const vector signed short temp41 = vec_sub(v_sumsB3, v_first);

        const vector signed short v_sumsB4 = vec_add(temp41, vb7);



        const vector signed short temp51 = vec_sub(v_sumsB4, vb1);

        const vector signed short v_sumsB5 = vec_add(temp51, vb8);



        const vector signed short temp61 = vec_sub(v_sumsB5, vb2);

        const vector signed short v_sumsB6 = vec_add(temp61, v_last);



        const vector signed short temp71 = vec_sub(v_sumsB6, vb3);

        const vector signed short v_sumsB7 = vec_add(temp71, v_last);



        const vector signed short temp81 = vec_sub(v_sumsB7, vb4);

        const vector signed short v_sumsB8 = vec_add(temp81, v_last);



        const vector signed short temp91 = vec_sub(v_sumsB8, vb5);

        const vector signed short v_sumsB9 = vec_add(temp91, v_last);



    #define COMPUTE_VR(i, j, k)                                             \

        const vector signed short temps1##i =                               \

            vec_add(v_sumsB##i, v_sumsB##k);                                \

        const vector signed short temps2##i =                               \

            vec_mladd(vb##j, (vector signed short)v_2, temps1##i);          \

        const vector signed short  vr##j = vec_sra(temps2##i, v_4)



        COMPUTE_VR(0, 1, 2);

        COMPUTE_VR(1, 2, 3);

        COMPUTE_VR(2, 3, 4);

        COMPUTE_VR(3, 4, 5);

        COMPUTE_VR(4, 5, 6);

        COMPUTE_VR(5, 6, 7);

        COMPUTE_VR(6, 7, 8);

        COMPUTE_VR(7, 8, 9);



        const vector signed char neg1 = vec_splat_s8(-1);

        const vector unsigned char permHH = (const vector unsigned char){0x00, 0x01, 0x02, 0x03, 0x04, 0x05, 0x06, 0x07,

                                                                         0x18, 0x19, 0x1A, 0x1B, 0x1C, 0x1D, 0x1E, 0x1F};



#define PACK_AND_STORE(i)                                       \

{   const vector unsigned char perms##i =                       \

        vec_lvsr(i * stride, src2);                             \

    const vector unsigned char vf##i =                          \

        vec_packsu(vr##i, (vector signed short)zero);           \

    const vector unsigned char vg##i =                          \

        vec_perm(vf##i, vbT##i, permHH);                        \

    const vector unsigned char mask##i =                        \

        vec_perm((vector unsigned char)zero, (vector unsigned char)neg1, perms##i); \

    const vector unsigned char vg2##i =                         \

        vec_perm(vg##i, vg##i, perms##i);                       \

    const vector unsigned char svA##i =                         \

        vec_sel(vbA##i, vg2##i, mask##i);                       \

    const vector unsigned char svB##i =                         \

        vec_sel(vg2##i, vbB##i, mask##i);                       \

    vec_st(svA##i, i * stride, src2);                           \

    vec_st(svB##i, i * stride + 16, src2);}



#define PACK_AND_STORE_ALIGNED(i)                               \

{   const vector unsigned char vf##i =                          \

        vec_packsu(vr##i, (vector signed short)zero);           \

    const vector unsigned char vg##i =                          \

        vec_perm(vf##i, vbT##i, permHH);                        \

    vec_st(vg##i, i * stride, src2);}



        /* Special-casing the aligned case is worthwhile, as all calls from

         * the (transposed) horizontable deblocks will be aligned, in addition

         * to the naturally aligned vertical deblocks. */

        if (properStride && srcAlign) {

            PACK_AND_STORE_ALIGNED(1)

            PACK_AND_STORE_ALIGNED(2)

            PACK_AND_STORE_ALIGNED(3)

            PACK_AND_STORE_ALIGNED(4)

            PACK_AND_STORE_ALIGNED(5)

            PACK_AND_STORE_ALIGNED(6)

            PACK_AND_STORE_ALIGNED(7)

            PACK_AND_STORE_ALIGNED(8)

        } else {

            PACK_AND_STORE(1)

            PACK_AND_STORE(2)

            PACK_AND_STORE(3)

            PACK_AND_STORE(4)

            PACK_AND_STORE(5)

            PACK_AND_STORE(6)

            PACK_AND_STORE(7)

            PACK_AND_STORE(8)

        }

    #undef PACK_AND_STORE

    #undef PACK_AND_STORE_ALIGNED

    }

}

static void decode_hrd(HEVCContext *s, int common_inf_present,

                       int max_sublayers)

{

    GetBitContext *gb = &s->HEVClc.gb;

    int nal_params_present = 0, vcl_params_present = 0;

    int subpic_params_present = 0;

    int i;



    if (common_inf_present) {

        nal_params_present = get_bits1(gb);

        vcl_params_present = get_bits1(gb);



        if (nal_params_present || vcl_params_present) {

            subpic_params_present = get_bits1(gb);



            if (subpic_params_present) {

                skip_bits(gb, 8); // tick_divisor_minus2

                skip_bits(gb, 5); // du_cpb_removal_delay_increment_length_minus1

                skip_bits(gb, 1); // sub_pic_cpb_params_in_pic_timing_sei_flag

                skip_bits(gb, 5); // dpb_output_delay_du_length_minus1

            }



            skip_bits(gb, 4); // bit_rate_scale

            skip_bits(gb, 4); // cpb_size_scale



            if (subpic_params_present)

                skip_bits(gb, 4);  // cpb_size_du_scale



            skip_bits(gb, 5); // initial_cpb_removal_delay_length_minus1

            skip_bits(gb, 5); // au_cpb_removal_delay_length_minus1

            skip_bits(gb, 5); // dpb_output_delay_length_minus1

        }

    }



    for (i = 0; i < max_sublayers; i++) {

        int low_delay = 0;

        int nb_cpb = 1;

        int fixed_rate = get_bits1(gb);



        if (!fixed_rate)

            fixed_rate = get_bits1(gb);



        if (fixed_rate)

            get_ue_golomb_long(gb);  // elemental_duration_in_tc_minus1

        else

            low_delay = get_bits1(gb);



        if (!low_delay)

            nb_cpb = get_ue_golomb_long(gb) + 1;



        if (nal_params_present)

            decode_sublayer_hrd(s, nb_cpb, subpic_params_present);

        if (vcl_params_present)

            decode_sublayer_hrd(s, nb_cpb, subpic_params_present);

    }

}

