static int flv_set_video_codec(AVFormatContext *s, AVStream *vstream, int flv_codecid) {

    FLVContext *flv = s->priv_data;

    AVCodecContext *vcodec = vstream->codec;

    switch(flv_codecid) {

        case FLV_CODECID_H263  : vcodec->codec_id = CODEC_ID_FLV1   ; break;

        case FLV_CODECID_SCREEN: vcodec->codec_id = CODEC_ID_FLASHSV; break;

        case FLV_CODECID_VP6A  :

            if (!flv->alpha_stream) {

                AVCodecContext *alpha_codec;

                flv->alpha_stream = av_new_stream(s, 2);

                if (flv->alpha_stream) {

                    av_set_pts_info(flv->alpha_stream, 24, 1, 1000);

                    alpha_codec = flv->alpha_stream->codec;

                    alpha_codec->codec_type = CODEC_TYPE_VIDEO;

                    alpha_codec->codec_id = CODEC_ID_VP6F;

                    alpha_codec->extradata_size = 1;

                    alpha_codec->extradata = av_malloc(1);

                }

            }

        case FLV_CODECID_VP6   : vcodec->codec_id = CODEC_ID_VP6F   ;

            if(vcodec->extradata_size != 1) {

                vcodec->extradata_size = 1;

                vcodec->extradata = av_malloc(1);

            }

            vcodec->extradata[0] = get_byte(&s->pb);

            if (flv->alpha_stream)

                flv->alpha_stream->codec->extradata[0] = vcodec->extradata[0];

            return 1; // 1 byte body size adjustment for flv_read_packet()

        default:

            av_log(s, AV_LOG_INFO, "Unsupported video codec (%x)\n", flv_codecid);

            vcodec->codec_tag = flv_codecid;

    }



    return 0;

}

static int sub2video_prepare(InputStream *ist, InputFilter *ifilter)

{

    AVFormatContext *avf = input_files[ist->file_index]->ctx;

    int i, w, h;



    /* Compute the size of the canvas for the subtitles stream.

       If the subtitles codecpar has set a size, use it. Otherwise use the

       maximum dimensions of the video streams in the same file. */

    w = ifilter->width;

    h = ifilter->height;

    if (!(w && h)) {

        for (i = 0; i < avf->nb_streams; i++) {

            if (avf->streams[i]->codecpar->codec_type == AVMEDIA_TYPE_VIDEO) {

                w = FFMAX(w, avf->streams[i]->codecpar->width);

                h = FFMAX(h, avf->streams[i]->codecpar->height);

            }

        }

        if (!(w && h)) {

            w = FFMAX(w, 720);

            h = FFMAX(h, 576);

        }

        av_log(avf, AV_LOG_INFO, "sub2video: using %dx%d canvas\n", w, h);

    }

    ist->sub2video.w = ist->resample_width  = w;

    ist->sub2video.h = ist->resample_height = h;



    /* rectangles are AV_PIX_FMT_PAL8, but we have no guarantee that the

       palettes for all rectangles are identical or compatible */

    ist->resample_pix_fmt = ifilter->format = AV_PIX_FMT_RGB32;



    ist->sub2video.frame = av_frame_alloc();

    if (!ist->sub2video.frame)

        return AVERROR(ENOMEM);

    ist->sub2video.last_pts = INT64_MIN;

    return 0;

}

static int parse_inputs(const char **buf, AVFilterInOut **curr_inputs,

                        AVFilterInOut **open_outputs, AVClass *log_ctx)

{

    int pad = 0;



    while (**buf == '[') {

        char *name = parse_link_name(buf, log_ctx);

        AVFilterInOut *match;



        if (!name)

            return -1;



        /* First check if the label is not in the open_outputs list */

        match = extract_inout(name, open_outputs);



        if (match) {

            av_free(name);

        } else {

            /* Not in the list, so add it as an input */

            match = av_mallocz(sizeof(AVFilterInOut));

            match->name    = name;

            match->pad_idx = pad;

        }



        insert_inout(curr_inputs, match);



        *buf += strspn(*buf, WHITESPACES);

        pad++;

    }



    return pad;

}

static int dnxhd_mb_var_thread(AVCodecContext *avctx, void *arg, int jobnr, int threadnr)

{

    DNXHDEncContext *ctx = avctx->priv_data;

    int mb_y = jobnr, mb_x;

    ctx = ctx->thread[threadnr];

    if (ctx->cid_table->bit_depth == 8) {

        uint8_t *pix = ctx->thread[0]->src[0] + ((mb_y<<4) * ctx->m.linesize);

        for (mb_x = 0; mb_x < ctx->m.mb_width; ++mb_x, pix += 16) {

            unsigned mb  = mb_y * ctx->m.mb_width + mb_x;

            int sum = ctx->m.dsp.pix_sum(pix, ctx->m.linesize);

            int varc = (ctx->m.dsp.pix_norm1(pix, ctx->m.linesize) - (((unsigned)(sum*sum))>>8)+128)>>8;

            ctx->mb_cmp[mb].value = varc;

            ctx->mb_cmp[mb].mb = mb;

        }

    } else { // 10-bit

        int const linesize = ctx->m.linesize >> 1;

        for (mb_x = 0; mb_x < ctx->m.mb_width; ++mb_x) {

            uint16_t *pix = (uint16_t*)ctx->thread[0]->src[0] + ((mb_y << 4) * linesize) + (mb_x << 4);

            unsigned mb  = mb_y * ctx->m.mb_width + mb_x;

            int sum = 0;

            int sqsum = 0;

            int mean, sqmean;

            int i, j;

            // Macroblocks are 16x16 pixels, unlike DCT blocks which are 8x8.

            for (i = 0; i < 16; ++i) {

                for (j = 0; j < 16; ++j) {

                    // Turn 16-bit pixels into 10-bit ones.

                    int const sample = (unsigned)pix[j] >> 6;

                    sum += sample;

                    sqsum += sample * sample;

                    // 2^10 * 2^10 * 16 * 16 = 2^28, which is less than INT_MAX

                }

                pix += linesize;

            }

            mean = sum >> 8; // 16*16 == 2^8

            sqmean = sqsum >> 8;

            ctx->mb_cmp[mb].value = sqmean - mean * mean;

            ctx->mb_cmp[mb].mb = mb;

        }

    }

    return 0;

}

static int writer_open(WriterContext **wctx, const Writer *writer, const char *args,

                       const struct section *sections, int nb_sections)

{

    int i, ret = 0;



    if (!(*wctx = av_malloc(sizeof(WriterContext)))) {

        ret = AVERROR(ENOMEM);

        goto fail;

    }



    if (!((*wctx)->priv = av_mallocz(writer->priv_size))) {

        ret = AVERROR(ENOMEM);

        goto fail;

    }



    (*wctx)->class = &writer_class;

    (*wctx)->writer = writer;

    (*wctx)->level = -1;

    (*wctx)->sections = sections;

    (*wctx)->nb_sections = nb_sections;



    if (writer->priv_class) {

        void *priv_ctx = (*wctx)->priv;

        *((const AVClass **)priv_ctx) = writer->priv_class;

        av_opt_set_defaults(priv_ctx);



        if (args &&

            (ret = av_set_options_string(priv_ctx, args, "=", ":")) < 0)

            goto fail;

    }



    for (i = 0; i < SECTION_MAX_NB_LEVELS; i++)

        av_bprint_init(&(*wctx)->section_pbuf[i], 1, AV_BPRINT_SIZE_UNLIMITED);



    if ((*wctx)->writer->init)

        ret = (*wctx)->writer->init(*wctx);

    if (ret < 0)

        goto fail;



    return 0;



fail:

    writer_close(wctx);

    return ret;

}

static void test_vector_dmul_scalar(const double *src0, const double *src1)

{

    LOCAL_ALIGNED_32(double, cdst, [LEN]);

    LOCAL_ALIGNED_32(double, odst, [LEN]);

    int i;



    declare_func(void, double *dst, const double *src, double mul, int len);



    call_ref(cdst, src0, src1[0], LEN);

    call_new(odst, src0, src1[0], LEN);

    for (i = 0; i < LEN; i++) {

        if (!double_near_abs_eps(cdst[i], odst[i], DBL_EPSILON)) {

            fprintf(stderr, "%d: %- .12f - %- .12f = % .12g\n", i,

                    cdst[i], odst[i], cdst[i] - odst[i]);

            fail();

            break;

        }

    }

    bench_new(odst, src0, src1[0], LEN);

}

