				YSCALEYUV2RGBX

				"leal (%%eax, %%eax, 2), %%ebx	\n\t" //FIXME optimize

				"addl %4, %%ebx			\n\t"

				WRITEBGR24



			:: "m" (-lumFilterSize), "m" (-chrFilterSize),

			   "m" (lumMmxFilter+lumFilterSize*4), "m" (chrMmxFilter+chrFilterSize*4),

			   "r" (dest), "m" (dstW),

			   "m" (lumSrc+lumFilterSize), "m" (chrSrc+chrFilterSize)

			: "%eax", "%ebx", "%ecx", "%edx", "%esi"

