static inline int parse_nal_units(AVCodecParserContext *s, const uint8_t *buf,

                           int buf_size, AVCodecContext *avctx)

{

    HEVCParserContext *ctx = s->priv_data;

    HEVCContext       *h   = &ctx->h;

    GetBitContext      *gb;

    SliceHeader        *sh = &h->sh;

    HEVCParamSets *ps = &h->ps;

    HEVCPacket   *pkt = &ctx->pkt;

    const uint8_t *buf_end = buf + buf_size;

    int state = -1, i;

    HEVCNAL *nal;

    int is_global = buf == avctx->extradata;



    if (!h->HEVClc)

        h->HEVClc = av_mallocz(sizeof(HEVCLocalContext));

    if (!h->HEVClc)

        return AVERROR(ENOMEM);



    gb = &h->HEVClc->gb;



    /* set some sane default values */

    s->pict_type         = AV_PICTURE_TYPE_I;

    s->key_frame         = 0;

    s->picture_structure = AV_PICTURE_STRUCTURE_UNKNOWN;



    h->avctx = avctx;



    if (!buf_size)

        return 0;



    if (pkt->nals_allocated < 1) {

        HEVCNAL *tmp = av_realloc_array(pkt->nals, 1, sizeof(*tmp));

        if (!tmp)

            return AVERROR(ENOMEM);

        pkt->nals = tmp;

        memset(pkt->nals, 0, sizeof(*tmp));

        pkt->nals_allocated = 1;

    }



    nal = &pkt->nals[0];



    for (;;) {

        int src_length, consumed;

        buf = avpriv_find_start_code(buf, buf_end, &state);

        if (--buf + 2 >= buf_end)

            break;

        src_length = buf_end - buf;



        h->nal_unit_type = (*buf >> 1) & 0x3f;

        h->temporal_id   = (*(buf + 1) & 0x07) - 1;

        if (h->nal_unit_type <= NAL_CRA_NUT) {

            // Do not walk the whole buffer just to decode slice segment header

            if (src_length > 20)

                src_length = 20;

        }



        consumed = ff_hevc_extract_rbsp(NULL, buf, src_length, nal);

        if (consumed < 0)

            return consumed;



        init_get_bits8(gb, nal->data + 2, nal->size);

        switch (h->nal_unit_type) {

        case NAL_VPS:

            ff_hevc_decode_nal_vps(gb, avctx, ps);

            break;

        case NAL_SPS:

            ff_hevc_decode_nal_sps(gb, avctx, ps, 1);

            break;

        case NAL_PPS:

            ff_hevc_decode_nal_pps(gb, avctx, ps);

            break;

        case NAL_SEI_PREFIX:

        case NAL_SEI_SUFFIX:

            ff_hevc_decode_nal_sei(h);

            break;

        case NAL_TRAIL_N:

        case NAL_TRAIL_R:

        case NAL_TSA_N:

        case NAL_TSA_R:

        case NAL_STSA_N:

        case NAL_STSA_R:

        case NAL_RADL_N:

        case NAL_RADL_R:

        case NAL_RASL_N:

        case NAL_RASL_R:

        case NAL_BLA_W_LP:

        case NAL_BLA_W_RADL:

        case NAL_BLA_N_LP:

        case NAL_IDR_W_RADL:

        case NAL_IDR_N_LP:

        case NAL_CRA_NUT:



            if (is_global) {

                av_log(avctx, AV_LOG_ERROR, "Invalid NAL unit: %d\n", h->nal_unit_type);

                return AVERROR_INVALIDDATA;

            }



            sh->first_slice_in_pic_flag = get_bits1(gb);

            s->picture_structure = h->picture_struct;

            s->field_order = h->picture_struct;



            if (IS_IRAP(h)) {

                s->key_frame = 1;

                sh->no_output_of_prior_pics_flag = get_bits1(gb);

            }



            sh->pps_id = get_ue_golomb(gb);

            if (sh->pps_id >= MAX_PPS_COUNT || !ps->pps_list[sh->pps_id]) {

                av_log(avctx, AV_LOG_ERROR, "PPS id out of range: %d\n", sh->pps_id);

                return AVERROR_INVALIDDATA;

            }

            ps->pps = (HEVCPPS*)ps->pps_list[sh->pps_id]->data;



            if (ps->pps->sps_id >= MAX_SPS_COUNT || !ps->sps_list[ps->pps->sps_id]) {

                av_log(avctx, AV_LOG_ERROR, "SPS id out of range: %d\n", ps->pps->sps_id);

                return AVERROR_INVALIDDATA;

            }

            if (ps->sps != (HEVCSPS*)ps->sps_list[ps->pps->sps_id]->data) {

                ps->sps = (HEVCSPS*)ps->sps_list[ps->pps->sps_id]->data;

                ps->vps = (HEVCVPS*)ps->vps_list[ps->sps->vps_id]->data;

            }



            if (!sh->first_slice_in_pic_flag) {

                int slice_address_length;



                if (ps->pps->dependent_slice_segments_enabled_flag)

                    sh->dependent_slice_segment_flag = get_bits1(gb);

                else

                    sh->dependent_slice_segment_flag = 0;



                slice_address_length = av_ceil_log2_c(ps->sps->ctb_width *

                                                      ps->sps->ctb_height);

                sh->slice_segment_addr = slice_address_length ? get_bits(gb, slice_address_length) : 0;

                if (sh->slice_segment_addr >= ps->sps->ctb_width * ps->sps->ctb_height) {

                    av_log(avctx, AV_LOG_ERROR, "Invalid slice segment address: %u.\n",

                           sh->slice_segment_addr);

                    return AVERROR_INVALIDDATA;

                }

            } else

                sh->dependent_slice_segment_flag = 0;



            if (sh->dependent_slice_segment_flag)

                break;



            for (i = 0; i < ps->pps->num_extra_slice_header_bits; i++)

                skip_bits(gb, 1); // slice_reserved_undetermined_flag[]



            sh->slice_type = get_ue_golomb(gb);

            if (!(sh->slice_type == I_SLICE || sh->slice_type == P_SLICE ||

                  sh->slice_type == B_SLICE)) {

                av_log(avctx, AV_LOG_ERROR, "Unknown slice type: %d.\n",

                       sh->slice_type);

                return AVERROR_INVALIDDATA;

            }

            s->pict_type = sh->slice_type == B_SLICE ? AV_PICTURE_TYPE_B :

                           sh->slice_type == P_SLICE ? AV_PICTURE_TYPE_P :

                                                       AV_PICTURE_TYPE_I;



            if (ps->pps->output_flag_present_flag)

                sh->pic_output_flag = get_bits1(gb);



            if (ps->sps->separate_colour_plane_flag)

                sh->colour_plane_id = get_bits(gb, 2);



            if (!IS_IDR(h)) {

                sh->pic_order_cnt_lsb = get_bits(gb, ps->sps->log2_max_poc_lsb);

                s->output_picture_number = h->poc = ff_hevc_compute_poc(h, sh->pic_order_cnt_lsb);

            } else

                s->output_picture_number = h->poc = 0;



            if (h->temporal_id == 0 &&

                h->nal_unit_type != NAL_TRAIL_N &&

                h->nal_unit_type != NAL_TSA_N &&

                h->nal_unit_type != NAL_STSA_N &&

                h->nal_unit_type != NAL_RADL_N &&

                h->nal_unit_type != NAL_RASL_N &&

                h->nal_unit_type != NAL_RADL_R &&

                h->nal_unit_type != NAL_RASL_R)

                h->pocTid0 = h->poc;



            return 0; /* no need to evaluate the rest */

        }

        buf += consumed;

    }

    /* didn't find a picture! */

    if (!is_global)

        av_log(h->avctx, AV_LOG_ERROR, "missing picture in access unit\n");

    return -1;

}

static void decode_colskip(uint8_t* plane, int width, int height, int stride, VC9Context *v){

    int x, y;

    GetBitContext *gb = &v->s.gb;



    for (x=0; x<width; x++){

        if (!get_bits(gb, 1)) //colskip

            for (y=0; y<height; y++)

                plane[y*stride] = 0;

        else

            for (y=0; y<height; y++)

                plane[y*stride] = get_bits(gb, 1);

        plane ++;

    }

}

static void vc1_h_overlap_c(uint8_t* src, int stride)

{

    int i;

    int a, b, c, d;

    int d1, d2;

    int rnd = 1;

    for(i = 0; i < 8; i++) {

        a = src[-2];

        b = src[-1];

        c = src[0];

        d = src[1];

        d1 = (a - d + 3 + rnd) >> 3;

        d2 = (a - d + b - c + 4 - rnd) >> 3;



        src[-2] = a - d1;

        src[-1] = b - d2;

        src[0] = c + d2;

        src[1] = d + d1;

        src += stride;

        rnd = !rnd;

    }

}

int ff_msmpeg4_decode_block(MpegEncContext * s, int16_t * block,

                              int n, int coded, const uint8_t *scan_table)

{

    int level, i, last, run, run_diff;

    int av_uninit(dc_pred_dir);

    RLTable *rl;

    RL_VLC_ELEM *rl_vlc;

    int qmul, qadd;



    if (s->mb_intra) {

        qmul=1;

        qadd=0;



        /* DC coef */

        level = msmpeg4_decode_dc(s, n, &dc_pred_dir);



        if (level < 0){

            av_log(s->avctx, AV_LOG_ERROR, "dc overflow- block: %d qscale: %d//\n", n, s->qscale);

            if(s->inter_intra_pred) level=0;

            else                    return -1;

        }

        if (n < 4) {

            rl = &ff_rl_table[s->rl_table_index];

            if(level > 256*s->y_dc_scale){

                av_log(s->avctx, AV_LOG_ERROR, "dc overflow+ L qscale: %d//\n", s->qscale);

                if(!s->inter_intra_pred) return -1;

            }

        } else {

            rl = &ff_rl_table[3 + s->rl_chroma_table_index];

            if(level > 256*s->c_dc_scale){

                av_log(s->avctx, AV_LOG_ERROR, "dc overflow+ C qscale: %d//\n", s->qscale);

                if(!s->inter_intra_pred) return -1;

            }

        }

        block[0] = level;



        run_diff = s->msmpeg4_version >= 4;

        i = 0;

        if (!coded) {

            goto not_coded;

        }

        if (s->ac_pred) {

            if (dc_pred_dir == 0)

                scan_table = s->intra_v_scantable.permutated; /* left */

            else

                scan_table = s->intra_h_scantable.permutated; /* top */

        } else {

            scan_table = s->intra_scantable.permutated;

        }

        rl_vlc= rl->rl_vlc[0];

    } else {

        qmul = s->qscale << 1;

        qadd = (s->qscale - 1) | 1;

        i = -1;

        rl = &ff_rl_table[3 + s->rl_table_index];



        if(s->msmpeg4_version==2)

            run_diff = 0;

        else

            run_diff = 1;



        if (!coded) {

            s->block_last_index[n] = i;

            return 0;

        }

        if(!scan_table)

            scan_table = s->inter_scantable.permutated;

        rl_vlc= rl->rl_vlc[s->qscale];

    }

  {

    OPEN_READER(re, &s->gb);

    for(;;) {

        UPDATE_CACHE(re, &s->gb);

        GET_RL_VLC(level, run, re, &s->gb, rl_vlc, TEX_VLC_BITS, 2, 0);

        if (level==0) {

            int cache;

            cache= GET_CACHE(re, &s->gb);

            /* escape */

            if (s->msmpeg4_version==1 || (cache&0x80000000)==0) {

                if (s->msmpeg4_version==1 || (cache&0x40000000)==0) {

                    /* third escape */

                    if(s->msmpeg4_version!=1) LAST_SKIP_BITS(re, &s->gb, 2);

                    UPDATE_CACHE(re, &s->gb);

                    if(s->msmpeg4_version<=3){

                        last=  SHOW_UBITS(re, &s->gb, 1); SKIP_CACHE(re, &s->gb, 1);

                        run=   SHOW_UBITS(re, &s->gb, 6); SKIP_CACHE(re, &s->gb, 6);

                        level= SHOW_SBITS(re, &s->gb, 8);

                        SKIP_COUNTER(re, &s->gb, 1+6+8);

                    }else{

                        int sign;

                        last=  SHOW_UBITS(re, &s->gb, 1); SKIP_BITS(re, &s->gb, 1);

                        if(!s->esc3_level_length){

                            int ll;

                            av_dlog(s->avctx, "ESC-3 %X at %d %d\n",

                                    show_bits(&s->gb, 24), s->mb_x, s->mb_y);

                            if(s->qscale<8){

                                ll= SHOW_UBITS(re, &s->gb, 3); SKIP_BITS(re, &s->gb, 3);

                                if(ll==0){

                                    ll= 8+SHOW_UBITS(re, &s->gb, 1); SKIP_BITS(re, &s->gb, 1);

                                }

                            }else{

                                ll=2;

                                while(ll<8 && SHOW_UBITS(re, &s->gb, 1)==0){

                                    ll++;

                                    SKIP_BITS(re, &s->gb, 1);

                                }

                                if(ll<8) SKIP_BITS(re, &s->gb, 1);

                            }



                            s->esc3_level_length= ll;

                            s->esc3_run_length= SHOW_UBITS(re, &s->gb, 2) + 3; SKIP_BITS(re, &s->gb, 2);

                            UPDATE_CACHE(re, &s->gb);

                        }

                        run=   SHOW_UBITS(re, &s->gb, s->esc3_run_length);

                        SKIP_BITS(re, &s->gb, s->esc3_run_length);



                        sign=  SHOW_UBITS(re, &s->gb, 1);

                        SKIP_BITS(re, &s->gb, 1);



                        level= SHOW_UBITS(re, &s->gb, s->esc3_level_length);

                        SKIP_BITS(re, &s->gb, s->esc3_level_length);

                        if(sign) level= -level;

                    }



#if 0 // waste of time / this will detect very few errors

                    {

                        const int abs_level= FFABS(level);

                        const int run1= run - rl->max_run[last][abs_level] - run_diff;

                        if(abs_level<=MAX_LEVEL && run<=MAX_RUN){

                            if(abs_level <= rl->max_level[last][run]){

                                av_log(s->avctx, AV_LOG_ERROR, "illegal 3. esc, vlc encoding possible\n");

                                return DECODING_AC_LOST;

                            }

                            if(abs_level <= rl->max_level[last][run]*2){

                                av_log(s->avctx, AV_LOG_ERROR, "illegal 3. esc, esc 1 encoding possible\n");

                                return DECODING_AC_LOST;

                            }

                            if(run1>=0 && abs_level <= rl->max_level[last][run1]){

                                av_log(s->avctx, AV_LOG_ERROR, "illegal 3. esc, esc 2 encoding possible\n");

                                return DECODING_AC_LOST;

                            }

                        }

                    }

#endif

                    //level = level * qmul + (level>0) * qadd - (level<=0) * qadd ;

                    if (level>0) level= level * qmul + qadd;

                    else         level= level * qmul - qadd;

#if 0 // waste of time too :(

                    if(level>2048 || level<-2048){

                        av_log(s->avctx, AV_LOG_ERROR, "|level| overflow in 3. esc\n");

                        return DECODING_AC_LOST;

                    }

#endif

                    i+= run + 1;

                    if(last) i+=192;

#ifdef ERROR_DETAILS

                if(run==66)

                    av_log(s->avctx, AV_LOG_ERROR, "illegal vlc code in ESC3 level=%d\n", level);

                else if((i>62 && i<192) || i>192+63)

                    av_log(s->avctx, AV_LOG_ERROR, "run overflow in ESC3 i=%d run=%d level=%d\n", i, run, level);

#endif

                } else {

                    /* second escape */

                    SKIP_BITS(re, &s->gb, 2);

                    GET_RL_VLC(level, run, re, &s->gb, rl_vlc, TEX_VLC_BITS, 2, 1);

                    i+= run + rl->max_run[run>>7][level/qmul] + run_diff; //FIXME opt indexing

                    level = (level ^ SHOW_SBITS(re, &s->gb, 1)) - SHOW_SBITS(re, &s->gb, 1);

                    LAST_SKIP_BITS(re, &s->gb, 1);

#ifdef ERROR_DETAILS

                if(run==66)

                    av_log(s->avctx, AV_LOG_ERROR, "illegal vlc code in ESC2 level=%d\n", level);

                else if((i>62 && i<192) || i>192+63)

                    av_log(s->avctx, AV_LOG_ERROR, "run overflow in ESC2 i=%d run=%d level=%d\n", i, run, level);

#endif

                }

            } else {

                /* first escape */

                SKIP_BITS(re, &s->gb, 1);

                GET_RL_VLC(level, run, re, &s->gb, rl_vlc, TEX_VLC_BITS, 2, 1);

                i+= run;

                level = level + rl->max_level[run>>7][(run-1)&63] * qmul;//FIXME opt indexing

                level = (level ^ SHOW_SBITS(re, &s->gb, 1)) - SHOW_SBITS(re, &s->gb, 1);

                LAST_SKIP_BITS(re, &s->gb, 1);

#ifdef ERROR_DETAILS

                if(run==66)

                    av_log(s->avctx, AV_LOG_ERROR, "illegal vlc code in ESC1 level=%d\n", level);

                else if((i>62 && i<192) || i>192+63)

                    av_log(s->avctx, AV_LOG_ERROR, "run overflow in ESC1 i=%d run=%d level=%d\n", i, run, level);

#endif

            }

        } else {

            i+= run;

            level = (level ^ SHOW_SBITS(re, &s->gb, 1)) - SHOW_SBITS(re, &s->gb, 1);

            LAST_SKIP_BITS(re, &s->gb, 1);

#ifdef ERROR_DETAILS

                if(run==66)

                    av_log(s->avctx, AV_LOG_ERROR, "illegal vlc code level=%d\n", level);

                else if((i>62 && i<192) || i>192+63)

                    av_log(s->avctx, AV_LOG_ERROR, "run overflow i=%d run=%d level=%d\n", i, run, level);

#endif

        }

        if (i > 62){

            i-= 192;

            if(i&(~63)){

                const int left= get_bits_left(&s->gb);

                if(((i+192 == 64 && level/qmul==-1) || !(s->err_recognition&(AV_EF_BITSTREAM|AV_EF_COMPLIANT))) && left>=0){

                    av_log(s->avctx, AV_LOG_ERROR, "ignoring overflow at %d %d\n", s->mb_x, s->mb_y);

                    i = 63;

                    break;

                }else{

                    av_log(s->avctx, AV_LOG_ERROR, "ac-tex damaged at %d %d\n", s->mb_x, s->mb_y);

                    return -1;

                }

            }



            block[scan_table[i]] = level;

            break;

        }



        block[scan_table[i]] = level;

    }

    CLOSE_READER(re, &s->gb);

  }

 not_coded:

    if (s->mb_intra) {

        ff_mpeg4_pred_ac(s, block, n, dc_pred_dir);

        if (s->ac_pred) {

            i = 63; /* XXX: not optimal */

        }

    }

    if(s->msmpeg4_version>=4 && i>0) i=63; //FIXME/XXX optimize

    s->block_last_index[n] = i;



    return 0;

}

static int svq1_decode_frame(AVCodecContext *avctx, void *data,

                             int *got_frame, AVPacket *avpkt)

{

    const uint8_t *buf = avpkt->data;

    int buf_size       = avpkt->size;

    SVQ1Context     *s = avctx->priv_data;

    AVFrame       *cur = data;

    uint8_t *current;

    int result, i, x, y, width, height;

    svq1_pmv *pmv;



    /* initialize bit buffer */

    init_get_bits(&s->gb, buf, buf_size * 8);



    /* decode frame header */

    s->frame_code = get_bits(&s->gb, 22);



    if ((s->frame_code & ~0x70) || !(s->frame_code & 0x60))

        return AVERROR_INVALIDDATA;



    /* swap some header bytes (why?) */

    if (s->frame_code != 0x20) {

        uint32_t *src = (uint32_t *)(buf + 4);



        for (i = 0; i < 4; i++)

            src[i] = ((src[i] << 16) | (src[i] >> 16)) ^ src[7 - i];

    }



    result = svq1_decode_frame_header(avctx, cur);



    if (result != 0) {

        av_dlog(avctx, "Error in svq1_decode_frame_header %i\n", result);

        return result;

    }



    result = ff_set_dimensions(avctx, s->width, s->height);

    if (result < 0)

        return result;



    if ((avctx->skip_frame >= AVDISCARD_NONREF && s->nonref) ||

        (avctx->skip_frame >= AVDISCARD_NONKEY &&

         cur->pict_type != AV_PICTURE_TYPE_I) ||

        avctx->skip_frame >= AVDISCARD_ALL)

        return buf_size;



    result = ff_get_buffer(avctx, cur, s->nonref ? 0 : AV_GET_BUFFER_FLAG_REF);

    if (result < 0)

        return result;



    pmv = av_malloc((FFALIGN(s->width, 16) / 8 + 3) * sizeof(*pmv));

    if (!pmv)

        return AVERROR(ENOMEM);



    /* decode y, u and v components */

    for (i = 0; i < 3; i++) {

        int linesize = cur->linesize[i];

        if (i == 0) {

            width    = FFALIGN(s->width,  16);

            height   = FFALIGN(s->height, 16);

        } else {

            if (avctx->flags & CODEC_FLAG_GRAY)

                break;

            width    = FFALIGN(s->width  / 4, 16);

            height   = FFALIGN(s->height / 4, 16);

        }



        current = cur->data[i];



        if (cur->pict_type == AV_PICTURE_TYPE_I) {

            /* keyframe */

            for (y = 0; y < height; y += 16) {

                for (x = 0; x < width; x += 16) {

                    result = svq1_decode_block_intra(&s->gb, &current[x],

                                                     linesize);

                    if (result != 0) {

                        av_log(avctx, AV_LOG_INFO,

                               "Error in svq1_decode_block %i (keyframe)\n",

                               result);

                        goto err;

                    }

                }

                current += 16 * linesize;

            }

        } else {

            /* delta frame */

            uint8_t *previous = s->prev->data[i];

            if (!previous ||

                s->prev->width != s->width || s->prev->height != s->height) {

                av_log(avctx, AV_LOG_ERROR, "Missing reference frame.\n");

                result = AVERROR_INVALIDDATA;

                goto err;

            }



            memset(pmv, 0, ((width / 8) + 3) * sizeof(svq1_pmv));



            for (y = 0; y < height; y += 16) {

                for (x = 0; x < width; x += 16) {

                    result = svq1_decode_delta_block(avctx, &s->hdsp,

                                                     &s->gb, &current[x],

                                                     previous, linesize,

                                                     pmv, x, y, width, height);

                    if (result != 0) {

                        av_dlog(avctx,

                                "Error in svq1_decode_delta_block %i\n",

                                result);

                        goto err;

                    }

                }



                pmv[0].x     =

                    pmv[0].y = 0;



                current += 16 * linesize;

            }

        }

    }



    if (!s->nonref) {

        av_frame_unref(s->prev);

        result = av_frame_ref(s->prev, cur);

        if (result < 0)

            goto err;

    }



    *got_frame = 1;

    result     = buf_size;



err:

    av_free(pmv);

    return result;

}

static av_cold int targa_encode_close(AVCodecContext *avctx)

{

    av_frame_free(&avctx->coded_frame);

    return 0;

}

static void backward_filter(RA288Context *ractx)

{

    float temp1[37]; // RTMP in the spec

    float temp2[11]; // GPTPMP in the spec



    do_hybrid_window(36, 40, 35, ractx->sp_block, temp1, ractx->sp_hist,

                     ractx->sp_rec, syn_window);



    if (!eval_lpc_coeffs(temp1, ractx->sp_lpc, 36))

        colmult(ractx->sp_lpc, ractx->sp_lpc, syn_bw_tab, 36);



    do_hybrid_window(10, 8, 20, ractx->gain_block, temp2, ractx->gain_hist,

                     ractx->gain_rec, gain_window);



    if (!eval_lpc_coeffs(temp2, ractx->gain_lpc, 10))

        colmult(ractx->gain_lpc, ractx->gain_lpc, gain_bw_tab, 10);

}

static void avc_loopfilter_luma_intra_edge_ver_msa(uint8_t *data,

                                                   uint8_t alpha_in,

                                                   uint8_t beta_in,

                                                   uint32_t img_width)

{

    uint8_t *src;

    v16u8 alpha, beta, p0_asub_q0;

    v16u8 is_less_than_alpha, is_less_than;

    v16u8 is_less_than_beta, negate_is_less_than_beta;

    v8i16 p2_r = { 0 };

    v8i16 p1_r = { 0 };

    v8i16 p0_r = { 0 };

    v8i16 q0_r = { 0 };

    v8i16 q1_r = { 0 };

    v8i16 q2_r = { 0 };

    v8i16 p2_l = { 0 };

    v8i16 p1_l = { 0 };

    v8i16 p0_l = { 0 };

    v8i16 q0_l = { 0 };

    v8i16 q1_l = { 0 };

    v8i16 q2_l = { 0 };

    v16u8 p3_org, p2_org, p1_org, p0_org, q0_org, q1_org, q2_org, q3_org;

    v8i16 p1_org_r, p0_org_r, q0_org_r, q1_org_r;

    v8i16 p1_org_l, p0_org_l, q0_org_l, q1_org_l;

    v16i8 zero = { 0 };

    v16u8 tmp_flag;



    src = data - 4;



    {

        v16u8 row0, row1, row2, row3, row4, row5, row6, row7;

        v16u8 row8, row9, row10, row11, row12, row13, row14, row15;



        LOAD_8VECS_UB(src, img_width,

                      row0, row1, row2, row3, row4, row5, row6, row7);

        LOAD_8VECS_UB(src + (8 * img_width), img_width,

                      row8, row9, row10, row11, row12, row13, row14, row15);



        TRANSPOSE16x8_B_UB(row0, row1, row2, row3, row4, row5, row6, row7,

                           row8, row9, row10, row11, row12, row13, row14, row15,

                           p3_org, p2_org, p1_org, p0_org,

                           q0_org, q1_org, q2_org, q3_org);

    }



    p1_org_r = (v8i16) __msa_ilvr_b(zero, (v16i8) p1_org);

    p0_org_r = (v8i16) __msa_ilvr_b(zero, (v16i8) p0_org);

    q0_org_r = (v8i16) __msa_ilvr_b(zero, (v16i8) q0_org);

    q1_org_r = (v8i16) __msa_ilvr_b(zero, (v16i8) q1_org);



    p1_org_l = (v8i16) __msa_ilvl_b(zero, (v16i8) p1_org);

    p0_org_l = (v8i16) __msa_ilvl_b(zero, (v16i8) p0_org);

    q0_org_l = (v8i16) __msa_ilvl_b(zero, (v16i8) q0_org);

    q1_org_l = (v8i16) __msa_ilvl_b(zero, (v16i8) q1_org);



    /*  if ( ((unsigned)ABS(p0-q0) < thresholds->alpha_in) &&

       ((unsigned)ABS(p1-p0) < thresholds->beta_in)  &&

       ((unsigned)ABS(q1-q0) < thresholds->beta_in) )   */

    {

        v16u8 p1_asub_p0, q1_asub_q0;



        p0_asub_q0 = __msa_asub_u_b(p0_org, q0_org);

        p1_asub_p0 = __msa_asub_u_b(p1_org, p0_org);

        q1_asub_q0 = __msa_asub_u_b(q1_org, q0_org);



        alpha = (v16u8) __msa_fill_b(alpha_in);

        beta = (v16u8) __msa_fill_b(beta_in);



        is_less_than_alpha = (p0_asub_q0 < alpha);

        is_less_than_beta = (p1_asub_p0 < beta);

        is_less_than = is_less_than_beta & is_less_than_alpha;

        is_less_than_beta = (q1_asub_q0 < beta);

        is_less_than = is_less_than_beta & is_less_than;

    }



    if (!__msa_test_bz_v(is_less_than)) {

        tmp_flag = alpha >> 2;

        tmp_flag = tmp_flag + 2;

        tmp_flag = (p0_asub_q0 < tmp_flag);



        {

            v16u8 p2_asub_p0;



            p2_asub_p0 = __msa_asub_u_b(p2_org, p0_org);

            is_less_than_beta = (p2_asub_p0 < beta);

        }



        is_less_than_beta = tmp_flag & is_less_than_beta;



        negate_is_less_than_beta = __msa_xori_b(is_less_than_beta, 0xff);

        is_less_than_beta = is_less_than_beta & is_less_than;

        negate_is_less_than_beta = negate_is_less_than_beta & is_less_than;



        /* right */

        {

            v16u8 is_less_than_beta_r;



            is_less_than_beta_r =

                (v16u8) __msa_sldi_b((v16i8) is_less_than_beta, zero, 8);

            if (!__msa_test_bz_v(is_less_than_beta_r)) {

                v8i16 p3_org_r;



                p3_org_r = (v8i16) __msa_ilvr_b(zero, (v16i8) p3_org);

                p2_r = (v8i16) __msa_ilvr_b(zero, (v16i8) p2_org);



                AVC_LOOP_FILTER_P0P1P2_OR_Q0Q1Q2(p3_org_r, p0_org_r,

                                                 q0_org_r, p1_org_r,

                                                 p2_r, q1_org_r,

                                                 p0_r, p1_r, p2_r);

            }

        }

        /* left */

        {

            v16u8 is_less_than_beta_l;



            is_less_than_beta_l =

                (v16u8) __msa_sldi_b(zero, (v16i8) is_less_than_beta, 8);

            if (!__msa_test_bz_v(is_less_than_beta_l)) {

                v8i16 p3_org_l;



                p3_org_l = (v8i16) __msa_ilvl_b(zero, (v16i8) p3_org);

                p2_l = (v8i16) __msa_ilvl_b(zero, (v16i8) p2_org);



                AVC_LOOP_FILTER_P0P1P2_OR_Q0Q1Q2(p3_org_l, p0_org_l,

                                                 q0_org_l, p1_org_l,

                                                 p2_l, q1_org_l,

                                                 p0_l, p1_l, p2_l);

            }

        }



        /* combine and store */

        if (!__msa_test_bz_v(is_less_than_beta)) {

            v16u8 p0, p2, p1;



            p0 = (v16u8) __msa_pckev_b((v16i8) p0_l, (v16i8) p0_r);

            p1 = (v16u8) __msa_pckev_b((v16i8) p1_l, (v16i8) p1_r);

            p2 = (v16u8) __msa_pckev_b((v16i8) p2_l, (v16i8) p2_r);



            p0_org = __msa_bmnz_v(p0_org, p0, is_less_than_beta);

            p1_org = __msa_bmnz_v(p1_org, p1, is_less_than_beta);

            p2_org = __msa_bmnz_v(p2_org, p2, is_less_than_beta);

        }



        /* right */

        {

            v16u8 negate_is_less_than_beta_r;



            negate_is_less_than_beta_r =

                (v16u8) __msa_sldi_b((v16i8) negate_is_less_than_beta, zero, 8);



            if (!__msa_test_bz_v(negate_is_less_than_beta_r)) {

                AVC_LOOP_FILTER_P0_OR_Q0(p0_org_r, q1_org_r, p1_org_r, p0_r);

            }

        }



        /* left */

        {

            v16u8 negate_is_less_than_beta_l;



            negate_is_less_than_beta_l =

                (v16u8) __msa_sldi_b(zero, (v16i8) negate_is_less_than_beta, 8);

            if (!__msa_test_bz_v(negate_is_less_than_beta_l)) {

                AVC_LOOP_FILTER_P0_OR_Q0(p0_org_l, q1_org_l, p1_org_l, p0_l);

            }

        }



        if (!__msa_test_bz_v(negate_is_less_than_beta)) {

            v16u8 p0;



            p0 = (v16u8) __msa_pckev_b((v16i8) p0_l, (v16i8) p0_r);

            p0_org = __msa_bmnz_v(p0_org, p0, negate_is_less_than_beta);

        }



        {

            v16u8 q2_asub_q0;



            q2_asub_q0 = __msa_asub_u_b(q2_org, q0_org);

            is_less_than_beta = (q2_asub_q0 < beta);

        }



        is_less_than_beta = is_less_than_beta & tmp_flag;

        negate_is_less_than_beta = __msa_xori_b(is_less_than_beta, 0xff);



        is_less_than_beta = is_less_than_beta & is_less_than;

        negate_is_less_than_beta = negate_is_less_than_beta & is_less_than;



        /* right */

        {

            v16u8 is_less_than_beta_r;



            is_less_than_beta_r =

                (v16u8) __msa_sldi_b((v16i8) is_less_than_beta, zero, 8);

            if (!__msa_test_bz_v(is_less_than_beta_r)) {

                v8i16 q3_org_r;



                q3_org_r = (v8i16) __msa_ilvr_b(zero, (v16i8) q3_org);

                q2_r = (v8i16) __msa_ilvr_b(zero, (v16i8) q2_org);



                AVC_LOOP_FILTER_P0P1P2_OR_Q0Q1Q2(q3_org_r, q0_org_r,

                                                 p0_org_r, q1_org_r,

                                                 q2_r, p1_org_r,

                                                 q0_r, q1_r, q2_r);

            }

        }



        /* left */

        {

            v16u8 is_less_than_beta_l;



            is_less_than_beta_l =

                (v16u8) __msa_sldi_b(zero, (v16i8) is_less_than_beta, 8);

            if (!__msa_test_bz_v(is_less_than_beta_l)) {

                v8i16 q3_org_l;



                q3_org_l = (v8i16) __msa_ilvl_b(zero, (v16i8) q3_org);

                q2_l = (v8i16) __msa_ilvl_b(zero, (v16i8) q2_org);



                AVC_LOOP_FILTER_P0P1P2_OR_Q0Q1Q2(q3_org_l, q0_org_l,

                                                 p0_org_l, q1_org_l,

                                                 q2_l, p1_org_l,

                                                 q0_l, q1_l, q2_l);

            }

        }



        /* combine and store */

        if (!__msa_test_bz_v(is_less_than_beta)) {

            v16u8 q0, q1, q2;



            q0 = (v16u8) __msa_pckev_b((v16i8) q0_l, (v16i8) q0_r);

            q1 = (v16u8) __msa_pckev_b((v16i8) q1_l, (v16i8) q1_r);

            q2 = (v16u8) __msa_pckev_b((v16i8) q2_l, (v16i8) q2_r);



            q0_org = __msa_bmnz_v(q0_org, q0, is_less_than_beta);

            q1_org = __msa_bmnz_v(q1_org, q1, is_less_than_beta);

            q2_org = __msa_bmnz_v(q2_org, q2, is_less_than_beta);

        }



        /* right */

        {

            v16u8 negate_is_less_than_beta_r;



            negate_is_less_than_beta_r =

                (v16u8) __msa_sldi_b((v16i8) negate_is_less_than_beta, zero, 8);

            if (!__msa_test_bz_v(negate_is_less_than_beta_r)) {

                AVC_LOOP_FILTER_P0_OR_Q0(q0_org_r, p1_org_r, q1_org_r, q0_r);

            }

        }

        /* left */

        {

            v16u8 negate_is_less_than_beta_l;



            negate_is_less_than_beta_l =

                (v16u8) __msa_sldi_b(zero, (v16i8) negate_is_less_than_beta, 8);

            if (!__msa_test_bz_v(negate_is_less_than_beta_l)) {

                AVC_LOOP_FILTER_P0_OR_Q0(q0_org_l, p1_org_l, q1_org_l, q0_l);

            }

        }



        if (!__msa_test_bz_v(negate_is_less_than_beta)) {

            v16u8 q0;



            q0 = (v16u8) __msa_pckev_b((v16i8) q0_l, (v16i8) q0_r);

            q0_org = __msa_bmnz_v(q0_org, q0, negate_is_less_than_beta);

        }

    }



    {

        v16u8 tmp0, tmp1, tmp2, tmp3, tmp4, tmp5, tmp6, tmp7;

        uint32_t out0, out2;

        uint16_t out1, out3;



        tmp0 = (v16u8) __msa_ilvr_b((v16i8) p1_org, (v16i8) p2_org);

        tmp1 = (v16u8) __msa_ilvr_b((v16i8) q0_org, (v16i8) p0_org);

        tmp2 = (v16u8) __msa_ilvr_b((v16i8) q2_org, (v16i8) q1_org);

        tmp3 = (v16u8) __msa_ilvr_h((v8i16) tmp1, (v8i16) tmp0);

        tmp4 = (v16u8) __msa_ilvl_h((v8i16) tmp1, (v8i16) tmp0);



        tmp0 = (v16u8) __msa_ilvl_b((v16i8) p1_org, (v16i8) p2_org);

        tmp1 = (v16u8) __msa_ilvl_b((v16i8) q0_org, (v16i8) p0_org);

        tmp5 = (v16u8) __msa_ilvl_b((v16i8) q2_org, (v16i8) q1_org);

        tmp6 = (v16u8) __msa_ilvr_h((v8i16) tmp1, (v8i16) tmp0);

        tmp7 = (v16u8) __msa_ilvl_h((v8i16) tmp1, (v8i16) tmp0);



        src = data - 3;



        out0 = __msa_copy_u_w((v4i32) tmp3, 0);

        out1 = __msa_copy_u_h((v8i16) tmp2, 0);

        out2 = __msa_copy_u_w((v4i32) tmp3, 1);

        out3 = __msa_copy_u_h((v8i16) tmp2, 1);



        STORE_WORD(src, out0);

        STORE_HWORD((src + 4), out1);

        src += img_width;

        STORE_WORD(src, out2);

        STORE_HWORD((src + 4), out3);



        out0 = __msa_copy_u_w((v4i32) tmp3, 2);

        out1 = __msa_copy_u_h((v8i16) tmp2, 2);

        out2 = __msa_copy_u_w((v4i32) tmp3, 3);

        out3 = __msa_copy_u_h((v8i16) tmp2, 3);



        src += img_width;

        STORE_WORD(src, out0);

        STORE_HWORD((src + 4), out1);

        src += img_width;

        STORE_WORD(src, out2);

        STORE_HWORD((src + 4), out3);



        out0 = __msa_copy_u_w((v4i32) tmp4, 0);

        out1 = __msa_copy_u_h((v8i16) tmp2, 4);

        out2 = __msa_copy_u_w((v4i32) tmp4, 1);

        out3 = __msa_copy_u_h((v8i16) tmp2, 5);



        src += img_width;

        STORE_WORD(src, out0);

        STORE_HWORD((src + 4), out1);

        src += img_width;

        STORE_WORD(src, out2);

        STORE_HWORD((src + 4), out3);



        out0 = __msa_copy_u_w((v4i32) tmp4, 2);

        out1 = __msa_copy_u_h((v8i16) tmp2, 6);

        out2 = __msa_copy_u_w((v4i32) tmp4, 3);

        out3 = __msa_copy_u_h((v8i16) tmp2, 7);



        src += img_width;

        STORE_WORD(src, out0);

        STORE_HWORD((src + 4), out1);

        src += img_width;

        STORE_WORD(src, out2);

        STORE_HWORD((src + 4), out3);



        out0 = __msa_copy_u_w((v4i32) tmp6, 0);

        out1 = __msa_copy_u_h((v8i16) tmp5, 0);

        out2 = __msa_copy_u_w((v4i32) tmp6, 1);

        out3 = __msa_copy_u_h((v8i16) tmp5, 1);



        src += img_width;

        STORE_WORD(src, out0);

        STORE_HWORD((src + 4), out1);

        src += img_width;

        STORE_WORD(src, out2);

        STORE_HWORD((src + 4), out3);



        out0 = __msa_copy_u_w((v4i32) tmp6, 2);

        out1 = __msa_copy_u_h((v8i16) tmp5, 2);

        out2 = __msa_copy_u_w((v4i32) tmp6, 3);

        out3 = __msa_copy_u_h((v8i16) tmp5, 3);



        src += img_width;

        STORE_WORD(src, out0);

        STORE_HWORD((src + 4), out1);

        src += img_width;

        STORE_WORD(src, out2);

        STORE_HWORD((src + 4), out3);



        out0 = __msa_copy_u_w((v4i32) tmp7, 0);

        out1 = __msa_copy_u_h((v8i16) tmp5, 4);

        out2 = __msa_copy_u_w((v4i32) tmp7, 1);

        out3 = __msa_copy_u_h((v8i16) tmp5, 5);



        src += img_width;

        STORE_WORD(src, out0);

        STORE_HWORD((src + 4), out1);

        src += img_width;

        STORE_WORD(src, out2);

        STORE_HWORD((src + 4), out3);



        out0 = __msa_copy_u_w((v4i32) tmp7, 2);

        out1 = __msa_copy_u_h((v8i16) tmp5, 6);

        out2 = __msa_copy_u_w((v4i32) tmp7, 3);

        out3 = __msa_copy_u_h((v8i16) tmp5, 7);



        src += img_width;

        STORE_WORD(src, out0);

        STORE_HWORD((src + 4), out1);

        src += img_width;

        STORE_WORD(src, out2);

        STORE_HWORD((src + 4), out3);

    }

}

static int dshow_read_packet(AVFormatContext *s, AVPacket *pkt)

{

    struct dshow_ctx *ctx = s->priv_data;

    AVPacketList *pktl = NULL;



    while (!pktl) {

        WaitForSingleObject(ctx->mutex, INFINITE);

        pktl = ctx->pktl;

        if (pktl) {

            *pkt = pktl->pkt;

            ctx->pktl = ctx->pktl->next;

            av_free(pktl);

            ctx->curbufsize -= pkt->size;

        }

        ResetEvent(ctx->event);

        ReleaseMutex(ctx->mutex);

        if (!pktl) {

            if (s->flags & AVFMT_FLAG_NONBLOCK) {

                return AVERROR(EAGAIN);

            } else {

                WaitForSingleObject(ctx->event, INFINITE);

            }

        }

    }



    return pkt->size;

}

static void blend_image(AVFilterContext *ctx,

                        AVFilterBufferRef *dst, AVFilterBufferRef *src,

                        int x, int y)

{

    OverlayContext *over = ctx->priv;

    int i, j, k;

    int width   = src->video->w;

    int height  = src->video->h;



    if (over->main_is_packed_rgb) {

        uint8_t *dp = dst->data[0] + x * over->main_pix_step[0] +

                      y * dst->linesize[0];

        uint8_t *sp = src->data[0];

        uint8_t alpha;          ///< the amount of overlay to blend on to main

        const int dr = over->main_rgba_map[R];

        const int dg = over->main_rgba_map[G];

        const int db = over->main_rgba_map[B];

        const int da = over->main_rgba_map[A];

        const int dstep = over->main_pix_step[0];

        const int sr = over->overlay_rgba_map[R];

        const int sg = over->overlay_rgba_map[G];

        const int sb = over->overlay_rgba_map[B];

        const int sa = over->overlay_rgba_map[A];

        const int sstep = over->overlay_pix_step[0];

        const int main_has_alpha = over->main_has_alpha;

        for (i = 0; i < height; i++) {

            uint8_t *d = dp, *s = sp;

            for (j = 0; j < width; j++) {

                alpha = s[sa];



                // if the main channel has an alpha channel, alpha has to be calculated

                // to create an un-premultiplied (straight) alpha value

                if (main_has_alpha && alpha != 0 && alpha != 255) {

                    uint8_t alpha_d = d[da];

                    alpha = UNPREMULTIPLY_ALPHA(alpha, alpha_d);

                }



                switch (alpha) {

                case 0:

                    break;

                case 255:

                    d[dr] = s[sr];

                    d[dg] = s[sg];

                    d[db] = s[sb];

                    break;

                default:

                    // main_value = main_value * (1 - alpha) + overlay_value * alpha

                    // since alpha is in the range 0-255, the result must divided by 255

                    d[dr] = FAST_DIV255(d[dr] * (255 - alpha) + s[sr] * alpha);

                    d[dg] = FAST_DIV255(d[dg] * (255 - alpha) + s[sg] * alpha);

                    d[db] = FAST_DIV255(d[db] * (255 - alpha) + s[sb] * alpha);

                }

                if (main_has_alpha) {

                    switch (alpha) {

                    case 0:

                        break;

                    case 255:

                        d[da] = s[sa];

                        break;

                    default:

                        // apply alpha compositing: main_alpha += (1-main_alpha) * overlay_alpha

                        d[da] += FAST_DIV255((255 - d[da]) * s[sa]);

                    }

                }

                d += dstep;

                s += sstep;

            }

            dp += dst->linesize[0];

            sp += src->linesize[0];

        }

    } else {

        const int main_has_alpha = over->main_has_alpha;

        if (main_has_alpha) {

            uint8_t *da = dst->data[3] + x * over->main_pix_step[3] +

                          y * dst->linesize[3];

            uint8_t *sa = src->data[3];

            uint8_t alpha;          ///< the amount of overlay to blend on to main

            for (i = 0; i < height; i++) {

                uint8_t *d = da, *s = sa;

                for (j = 0; j < width; j++) {

                    alpha = *s;

                    if (alpha != 0 && alpha != 255) {

                        uint8_t alpha_d = *d;

                        alpha = UNPREMULTIPLY_ALPHA(alpha, alpha_d);

                    }

                    switch (alpha) {

                    case 0:

                        break;

                    case 255:

                        *d = *s;

                        break;

                    default:

                        // apply alpha compositing: main_alpha += (1-main_alpha) * overlay_alpha

                        *d += FAST_DIV255((255 - *d) * *s);

                    }

                    d += 1;

                    s += 1;

                }

                da += dst->linesize[3];

                sa += src->linesize[3];

            }

        }

        for (i = 0; i < 3; i++) {

            int hsub = i ? over->hsub : 0;

            int vsub = i ? over->vsub : 0;

            uint8_t *dp = dst->data[i] + (x >> hsub) +

                (y >> vsub) * dst->linesize[i];

            uint8_t *sp = src->data[i];

            uint8_t *ap = src->data[3];

            int wp = FFALIGN(width, 1<<hsub) >> hsub;

            int hp = FFALIGN(height, 1<<vsub) >> vsub;

            for (j = 0; j < hp; j++) {

                uint8_t *d = dp, *s = sp, *a = ap;

                for (k = 0; k < wp; k++) {

                    // average alpha for color components, improve quality

                    int alpha_v, alpha_h, alpha;

                    if (hsub && vsub && j+1 < hp && k+1 < wp) {

                        alpha = (a[0] + a[src->linesize[3]] +

                                 a[1] + a[src->linesize[3]+1]) >> 2;

                    } else if (hsub || vsub) {

                        alpha_h = hsub && k+1 < wp ?

                            (a[0] + a[1]) >> 1 : a[0];

                        alpha_v = vsub && j+1 < hp ?

                            (a[0] + a[src->linesize[3]]) >> 1 : a[0];

                        alpha = (alpha_v + alpha_h) >> 1;

                    } else

                        alpha = a[0];

                    // if the main channel has an alpha channel, alpha has to be calculated

                    // to create an un-premultiplied (straight) alpha value

                    if (main_has_alpha && alpha != 0 && alpha != 255) {

                        // average alpha for color components, improve quality

                        uint8_t alpha_d;

                        if (hsub && vsub && j+1 < hp && k+1 < wp) {

                            alpha_d = (d[0] + d[src->linesize[3]] +

                                       d[1] + d[src->linesize[3]+1]) >> 2;

                        } else if (hsub || vsub) {

                            alpha_h = hsub && k+1 < wp ?

                                (d[0] + d[1]) >> 1 : d[0];

                            alpha_v = vsub && j+1 < hp ?

                                (d[0] + d[src->linesize[3]]) >> 1 : d[0];

                            alpha_d = (alpha_v + alpha_h) >> 1;

                        } else

                            alpha_d = d[0];

                        alpha = UNPREMULTIPLY_ALPHA(alpha, alpha_d);

                    }

                    *d = FAST_DIV255(*d * (255 - alpha) + *s * alpha);

                    s++;

                    d++;

                    a += 1 << hsub;

                }

                dp += dst->linesize[i];

                sp += src->linesize[i];

                ap += (1 << vsub) * src->linesize[3];

            }

        }

    }

}

static void draw_mandelbrot(AVFilterContext *ctx, uint32_t *color, int linesize, int64_t pts)

{

    MBContext *mb = ctx->priv;

    int x,y,i, in_cidx=0, next_cidx=0, tmp_cidx;

    double scale= mb->start_scale*pow(mb->end_scale/mb->start_scale, pts/mb->end_pts);

    int use_zyklus=0;

    fill_from_cache(ctx, NULL, &in_cidx, NULL, mb->start_y+scale*(-mb->h/2-0.5), scale);

    for(y=0; y<mb->h; y++){

        const double ci=mb->start_y+scale*(y-mb->h/2);

        memset(color+linesize*y, 0, sizeof(*color)*mb->w);

        fill_from_cache(ctx, color+linesize*y, &in_cidx, &next_cidx, ci, scale);

        tmp_cidx= in_cidx;

        fill_from_cache(ctx, color+linesize*y, &tmp_cidx, NULL, ci + scale/2, scale);



        for(x=0; x<mb->w; x++){

            const double cr=mb->start_x+scale*(x-mb->w/2);

            double zr=cr;

            double zi=ci;

            uint32_t c=0;

            double dv= mb->dither / (double)(1LL<<32);

            mb->dither= mb->dither*1664525+1013904223;



            if(color[x + y*linesize] & 0xFF000000)

                continue;



            use_zyklus= (x==0 || mb->inner!=BLACK ||color[x-1 + y*linesize] == 0xFF000000);



#define Z_Z2_C(outr,outi,inr,ini)\

            outr= inr*inr - ini*ini + cr;\

            outi= 2*inr*ini + ci;



#define Z_Z2_C_ZYKLUS(outr,outi,inr,ini, Z)\

            Z_Z2_C(outr,outi,inr,ini)\

            if(use_zyklus){\

                if(Z && mb->zyklus[i>>1][0]==outr && mb->zyklus[i>>1][1]==outi)\

                    break;\

                mb->zyklus[i][0]= outr;\

                mb->zyklus[i][1]= outi;\

            }





            for(i=0; i<mb->maxiter-8; i++){

                double t;

                Z_Z2_C_ZYKLUS(t, zi, zr, zi, 0)

                i++;

                Z_Z2_C_ZYKLUS(zr, zi, t, zi, 1)

                i++;

                Z_Z2_C_ZYKLUS(t, zi, zr, zi, 0)

                i++;

                Z_Z2_C_ZYKLUS(zr, zi, t, zi, 1)

                i++;

                Z_Z2_C_ZYKLUS(t, zi, zr, zi, 0)

                i++;

                Z_Z2_C_ZYKLUS(zr, zi, t, zi, 1)

                i++;

                Z_Z2_C_ZYKLUS(t, zi, zr, zi, 0)

                i++;

                Z_Z2_C_ZYKLUS(zr, zi, t, zi, 1)

                if(zr*zr + zi*zi > mb->bailout){

                    i-= FFMIN(7, i);

                    for(; i<mb->maxiter; i++){

                        zr= mb->zyklus[i][0];

                        zi= mb->zyklus[i][1];

                        if(zr*zr + zi*zi > mb->bailout){

                            switch(mb->outer){

                            case            ITERATION_COUNT: zr = i; break;

                            case NORMALIZED_ITERATION_COUNT: zr= i + log2(log(mb->bailout) / log(zr*zr + zi*zi)); break;

                            }

                            c= lrintf((sin(zr)+1)*127) + lrintf((sin(zr/1.234)+1)*127)*256*256 + lrintf((sin(zr/100)+1)*127)*256;

                            break;

                        }

                    }

                    break;

                }

            }

            if(!c){

                if(mb->inner==PERIOD){

                int j;

                for(j=i-1; j; j--)

                    if(SQR(mb->zyklus[j][0]-zr) + SQR(mb->zyklus[j][1]-zi) < 0.0000000000000001)

                        break;

                if(j){

                    c= i-j;

                    c= ((c<<5)&0xE0) + ((c<<16)&0xE000) + ((c<<27)&0xE00000);

                }

                }else if(mb->inner==CONVTIME){

                    c= floor(i*255.0/mb->maxiter+dv)*0x010101;

                } else if(mb->inner==MINCOL){

                    int j;

                    double closest=9999;

                    int closest_index=0;

                    for(j=i-1; j>=0; j--)

                        if(SQR(mb->zyklus[j][0]) + SQR(mb->zyklus[j][1]) < closest){

                            closest= SQR(mb->zyklus[j][0]) + SQR(mb->zyklus[j][1]);

                            closest_index= j;

                        }

                    closest = sqrt(closest);

                    c= lrintf((mb->zyklus[closest_index][0]/closest+1)*127+dv) + lrintf((mb->zyklus[closest_index][1]/closest+1)*127+dv)*256;

                }

            }

            c |= 0xFF000000;

            color[x + y*linesize]= c;

            if(next_cidx < mb->cache_allocated){

                mb->next_cache[next_cidx  ].p[0]= cr;

                mb->next_cache[next_cidx  ].p[1]= ci;

                mb->next_cache[next_cidx++].val = c;

            }

        }

        fill_from_cache(ctx, NULL, &in_cidx, &next_cidx, ci + scale/2, scale);

    }

    FFSWAP(void*, mb->next_cache, mb->point_cache);

    mb->cache_used = next_cidx;

    if(mb->cache_used == mb->cache_allocated)

        av_log(0, AV_LOG_INFO, "Mandelbrot cache is too small!\n");

}

static void opt_mb_qmax(const char *arg)

{

    video_mb_qmax = atoi(arg);

    if (video_mb_qmax < 0 ||

        video_mb_qmax > 31) {

        fprintf(stderr, "qmax must be >= 1 and <= 31\n");

        exit(1);

    }

}

static int read_access_unit(AVCodecContext *avctx, void* data, int *data_size,

                            AVPacket *avpkt)

{

    const uint8_t *buf = avpkt->data;

    int buf_size = avpkt->size;

    MLPDecodeContext *m = avctx->priv_data;

    GetBitContext gb;

    unsigned int length, substr;

    unsigned int substream_start;

    unsigned int header_size = 4;

    unsigned int substr_header_size = 0;

    uint8_t substream_parity_present[MAX_SUBSTREAMS];

    uint16_t substream_data_len[MAX_SUBSTREAMS];

    uint8_t parity_bits;



    if (buf_size < 4)

        return 0;



    length = (AV_RB16(buf) & 0xfff) * 2;



    if (length > buf_size)

        return -1;



    init_get_bits(&gb, (buf + 4), (length - 4) * 8);



    m->is_major_sync_unit = 0;

    if (show_bits_long(&gb, 31) == (0xf8726fba >> 1)) {

        if (read_major_sync(m, &gb) < 0)

            goto error;

        m->is_major_sync_unit = 1;

        header_size += 28;

    }



    if (!m->params_valid) {

        av_log(m->avctx, AV_LOG_WARNING,

               "Stream parameters not seen; skipping frame.\n");

        *data_size = 0;

        return length;

    }



    substream_start = 0;



    for (substr = 0; substr < m->num_substreams; substr++) {

        int extraword_present, checkdata_present, end, nonrestart_substr;



        extraword_present = get_bits1(&gb);

        nonrestart_substr = get_bits1(&gb);

        checkdata_present = get_bits1(&gb);

        skip_bits1(&gb);



        end = get_bits(&gb, 12) * 2;



        substr_header_size += 2;



        if (extraword_present) {

            if (m->avctx->codec_id == CODEC_ID_MLP) {

                av_log(m->avctx, AV_LOG_ERROR, "There must be no extraword for MLP.\n");

                goto error;

            }

            skip_bits(&gb, 16);

            substr_header_size += 2;

        }



        if (!(nonrestart_substr ^ m->is_major_sync_unit)) {

            av_log(m->avctx, AV_LOG_ERROR, "Invalid nonrestart_substr.\n");

            goto error;

        }



        if (end + header_size + substr_header_size > length) {

            av_log(m->avctx, AV_LOG_ERROR,

                   "Indicated length of substream %d data goes off end of "

                   "packet.\n", substr);

            end = length - header_size - substr_header_size;

        }



        if (end < substream_start) {

            av_log(avctx, AV_LOG_ERROR,

                   "Indicated end offset of substream %d data "

                   "is smaller than calculated start offset.\n",

                   substr);

            goto error;

        }



        if (substr > m->max_decoded_substream)

            continue;



        substream_parity_present[substr] = checkdata_present;

        substream_data_len[substr] = end - substream_start;

        substream_start = end;

    }



    parity_bits  = ff_mlp_calculate_parity(buf, 4);

    parity_bits ^= ff_mlp_calculate_parity(buf + header_size, substr_header_size);



    if ((((parity_bits >> 4) ^ parity_bits) & 0xF) != 0xF) {

        av_log(avctx, AV_LOG_ERROR, "Parity check failed.\n");

        goto error;

    }



    buf += header_size + substr_header_size;



    for (substr = 0; substr <= m->max_decoded_substream; substr++) {

        SubStream *s = &m->substream[substr];

        init_get_bits(&gb, buf, substream_data_len[substr] * 8);



        m->matrix_changed = 0;

        memset(m->filter_changed, 0, sizeof(m->filter_changed));



        s->blockpos = 0;

        do {

            unsigned int ch;



            if (get_bits1(&gb)) {

                if (get_bits1(&gb)) {

                    /* A restart header should be present. */

                    if (read_restart_header(m, &gb, buf, substr) < 0)

                        goto next_substr;

                    s->restart_seen = 1;

                }



                if (!s->restart_seen) {

                    goto next_substr;

                }



                if (read_decoding_params(m, &gb, substr) < 0)

                    goto next_substr;

            }



            if (m->matrix_changed > 1) {

                av_log(m->avctx, AV_LOG_ERROR, "Matrices may change only once per access unit.\n");

                goto next_substr;

            }

            for (ch = 0; ch < s->max_channel; ch++)

                if (m->filter_changed[ch][FIR] > 1 ||

                    m->filter_changed[ch][IIR] > 1) {

                    av_log(m->avctx, AV_LOG_ERROR, "Filters may change only once per access unit.\n");

                    goto next_substr;

                }



            if (!s->restart_seen) {

                goto next_substr;

            }



            if (read_block_data(m, &gb, substr) < 0)

                return -1;



            if (get_bits_count(&gb) >= substream_data_len[substr] * 8)

                goto substream_length_mismatch;



        } while (!get_bits1(&gb));



        skip_bits(&gb, (-get_bits_count(&gb)) & 15);

        if (substream_data_len[substr] * 8 - get_bits_count(&gb) >= 32) {

            int shorten_by;



            if (get_bits(&gb, 16) != 0xD234)

                return -1;



            shorten_by = get_bits(&gb, 16);

            if      (m->avctx->codec_id == CODEC_ID_TRUEHD && shorten_by  & 0x2000)

                s->blockpos -= FFMIN(shorten_by & 0x1FFF, s->blockpos);

            else if (m->avctx->codec_id == CODEC_ID_MLP    && shorten_by != 0xD234)

                return -1;



            if (substr == m->max_decoded_substream)

                av_log(m->avctx, AV_LOG_INFO, "End of stream indicated.\n");

        }

        if (substream_parity_present[substr]) {

            uint8_t parity, checksum;



            if (substream_data_len[substr] * 8 - get_bits_count(&gb) != 16)

                goto substream_length_mismatch;



            parity   = ff_mlp_calculate_parity(buf, substream_data_len[substr] - 2);

            checksum = ff_mlp_checksum8       (buf, substream_data_len[substr] - 2);



            if ((get_bits(&gb, 8) ^ parity) != 0xa9    )

                av_log(m->avctx, AV_LOG_ERROR, "Substream %d parity check failed.\n", substr);

            if ( get_bits(&gb, 8)           != checksum)

                av_log(m->avctx, AV_LOG_ERROR, "Substream %d checksum failed.\n"    , substr);

        }

        if (substream_data_len[substr] * 8 != get_bits_count(&gb)) {

            goto substream_length_mismatch;

        }



next_substr:

        if (!s->restart_seen) {

            av_log(m->avctx, AV_LOG_ERROR,

                   "No restart header present in substream %d.\n", substr);

        }



        buf += substream_data_len[substr];

    }



    rematrix_channels(m, m->max_decoded_substream);



    if (output_data(m, m->max_decoded_substream, data, data_size) < 0)

        return -1;



    return length;



substream_length_mismatch:

    av_log(m->avctx, AV_LOG_ERROR, "substream %d length mismatch\n", substr);

    return -1;



error:

    m->params_valid = 0;

    return -1;

}

static av_noinline void emulated_edge_mc_mmxext(uint8_t *buf, const uint8_t *src,

                                                ptrdiff_t buf_stride,

                                                ptrdiff_t src_stride,

                                                int block_w, int block_h,

                                                int src_x, int src_y, int w, int h)

{

    emulated_edge_mc(buf, src, buf_stride, src_stride, block_w, block_h,

                     src_x, src_y, w, h, vfixtbl_mmx, &ff_emu_edge_vvar_mmx,

                     hfixtbl_mmxext, &ff_emu_edge_hvar_mmxext);

}

static int epzs_motion_search(MpegEncContext * s,

                             int *mx_ptr, int *my_ptr,

                             int P[5][2], int pred_x, int pred_y,

                             int xmin, int ymin, int xmax, int ymax, uint8_t * ref_picture)

{

    int best[2]={0, 0};

    int d, dmin; 

    UINT8 *new_pic, *old_pic;

    const int pic_stride= s->linesize;

    const int pic_xy= (s->mb_y*pic_stride + s->mb_x)*16;

    UINT16 *mv_penalty= s->mv_penalty[s->f_code] + MAX_MV; // f_code of the prev frame

    int quant= s->qscale; // qscale of the prev frame

    const int shift= 1+s->quarter_sample;



    new_pic = s->new_picture[0] + pic_xy;

    old_pic = ref_picture + pic_xy;



    dmin = pix_abs16x16(new_pic, old_pic, pic_stride);

    if(dmin<Z_THRESHOLD){

        *mx_ptr= 0;

        *my_ptr= 0;

//printf("Z");

        return dmin;

    }



    /* first line */

    if ((s->mb_y == 0 || s->first_slice_line || s->first_gob_line)) {

        CHECK_MV(P[1][0]>>shift, P[1][1]>>shift)

    }else{

        CHECK_MV(P[4][0]>>shift, P[4][1]>>shift)

        if(dmin<Z_THRESHOLD){

            *mx_ptr= P[4][0]>>shift;

            *my_ptr= P[4][1]>>shift;

//printf("M\n");

            return dmin;

        }

        CHECK_MV(P[1][0]>>shift, P[1][1]>>shift)

        CHECK_MV(P[2][0]>>shift, P[2][1]>>shift)

        CHECK_MV(P[3][0]>>shift, P[3][1]>>shift)

    }

    CHECK_MV(P[0][0]>>shift, P[0][1]>>shift)



//check(best[0],best[1],0, b0)

    if(s->me_method==ME_EPZS)

        dmin= small_diamond_search(s, best, dmin, new_pic, old_pic, pic_stride, 

                                   pred_x, pred_y, mv_penalty, quant, xmin, ymin, xmax, ymax, shift);

    else

        dmin=         snake_search(s, best, dmin, new_pic, old_pic, pic_stride, 

                                   pred_x, pred_y, mv_penalty, quant, xmin, ymin, xmax, ymax, shift);

//check(best[0],best[1],0, b1)

    *mx_ptr= best[0];

    *my_ptr= best[1];    



//    printf("%d %d %d \n", best[0], best[1], dmin);

    return dmin;

}

int ff_qsv_encode(AVCodecContext *avctx, QSVEncContext *q,

                  AVPacket *pkt, const AVFrame *frame, int *got_packet)

{

    mfxBitstream bs = { { { 0 } } };



    mfxFrameSurface1 *surf = NULL;

    mfxSyncPoint sync      = NULL;

    int ret;



    if (frame) {

        ret = submit_frame(q, frame, &surf);

        if (ret < 0) {

            av_log(avctx, AV_LOG_ERROR, "Error submitting the frame for encoding.\n");

            return ret;

        }

    }



    ret = ff_alloc_packet(pkt, q->packet_size);

    if (ret < 0) {

        av_log(avctx, AV_LOG_ERROR, "Error allocating the output packet\n");

        return ret;

    }

    bs.Data      = pkt->data;

    bs.MaxLength = pkt->size;



    do {

        ret = MFXVideoENCODE_EncodeFrameAsync(q->session, NULL, surf, &bs, &sync);

        if (ret == MFX_WRN_DEVICE_BUSY)

            av_usleep(1);

    } while (ret > 0);



    if (ret < 0)

        return (ret == MFX_ERR_MORE_DATA) ? 0 : ff_qsv_error(ret);



    if (ret == MFX_WRN_INCOMPATIBLE_VIDEO_PARAM && frame->interlaced_frame)

        print_interlace_msg(avctx, q);



    if (sync) {

        MFXVideoCORE_SyncOperation(q->session, sync, 60000);



        if (bs.FrameType & MFX_FRAMETYPE_I || bs.FrameType & MFX_FRAMETYPE_xI)

            avctx->coded_frame->pict_type = AV_PICTURE_TYPE_I;

        else if (bs.FrameType & MFX_FRAMETYPE_P || bs.FrameType & MFX_FRAMETYPE_xP)

            avctx->coded_frame->pict_type = AV_PICTURE_TYPE_P;

        else if (bs.FrameType & MFX_FRAMETYPE_B || bs.FrameType & MFX_FRAMETYPE_xB)

            avctx->coded_frame->pict_type = AV_PICTURE_TYPE_B;



        pkt->dts  = av_rescale_q(bs.DecodeTimeStamp, (AVRational){1, 90000}, avctx->time_base);

        pkt->pts  = av_rescale_q(bs.TimeStamp,       (AVRational){1, 90000}, avctx->time_base);

        pkt->size = bs.DataLength;



        if (bs.FrameType & MFX_FRAMETYPE_IDR ||

            bs.FrameType & MFX_FRAMETYPE_xIDR)

            pkt->flags |= AV_PKT_FLAG_KEY;



        *got_packet = 1;

    }



    return 0;

}

static av_cold int xvid_encode_close(AVCodecContext *avctx) {

    struct xvid_context *x = avctx->priv_data;



    xvid_encore(x->encoder_handle, XVID_ENC_DESTROY, NULL, NULL);



    if( avctx->extradata != NULL )

        av_free(avctx->extradata);

    if( x->twopassbuffer != NULL ) {

        av_free(x->twopassbuffer);

        av_free(x->old_twopassbuffer);

    }

    if( x->twopassfile != NULL )

        av_free(x->twopassfile);

    if( x->intra_matrix != NULL )

        av_free(x->intra_matrix);

    if( x->inter_matrix != NULL )

        av_free(x->inter_matrix);



    return 0;

}

int attribute_align_arg avcodec_open2(AVCodecContext *avctx, const AVCodec *codec, AVDictionary **options)

{

    int ret = 0;

    AVDictionary *tmp = NULL;



    if (avcodec_is_open(avctx))

        return 0;



    if ((!codec && !avctx->codec)) {

        av_log(avctx, AV_LOG_ERROR, "No codec provided to avcodec_open2()\n");

        return AVERROR(EINVAL);

    }

    if ((codec && avctx->codec && codec != avctx->codec)) {

        av_log(avctx, AV_LOG_ERROR, "This AVCodecContext was allocated for %s, "

                                    "but %s passed to avcodec_open2()\n", avctx->codec->name, codec->name);

        return AVERROR(EINVAL);

    }

    if (!codec)

        codec = avctx->codec;



    if (avctx->extradata_size < 0 || avctx->extradata_size >= FF_MAX_EXTRADATA_SIZE)

        return AVERROR(EINVAL);



    if (options)

        av_dict_copy(&tmp, *options, 0);



    ret = ff_lock_avcodec(avctx);

    if (ret < 0)

        return ret;



    avctx->internal = av_mallocz(sizeof(AVCodecInternal));

    if (!avctx->internal) {

        ret = AVERROR(ENOMEM);

        goto end;

    }



    avctx->internal->pool = av_mallocz(sizeof(*avctx->internal->pool));

    if (!avctx->internal->pool) {

        ret = AVERROR(ENOMEM);

        goto free_and_end;

    }



    if (codec->priv_data_size > 0) {

        if (!avctx->priv_data) {

            avctx->priv_data = av_mallocz(codec->priv_data_size);

            if (!avctx->priv_data) {

                ret = AVERROR(ENOMEM);

                goto end;

            }

            if (codec->priv_class) {

                *(const AVClass **)avctx->priv_data = codec->priv_class;

                av_opt_set_defaults(avctx->priv_data);

            }

        }

        if (codec->priv_class && (ret = av_opt_set_dict(avctx->priv_data, &tmp)) < 0)

            goto free_and_end;

    } else {

        avctx->priv_data = NULL;

    }

    if ((ret = av_opt_set_dict(avctx, &tmp)) < 0)

        goto free_and_end;



    //We only call avcodec_set_dimensions() for non h264 codecs so as not to overwrite previously setup dimensions

    if (!( avctx->coded_width && avctx->coded_height && avctx->width && avctx->height && avctx->codec_id == AV_CODEC_ID_H264)){



    if (avctx->coded_width && avctx->coded_height)

        avcodec_set_dimensions(avctx, avctx->coded_width, avctx->coded_height);

    else if (avctx->width && avctx->height)

        avcodec_set_dimensions(avctx, avctx->width, avctx->height);

    }



    if ((avctx->coded_width || avctx->coded_height || avctx->width || avctx->height)

        && (  av_image_check_size(avctx->coded_width, avctx->coded_height, 0, avctx) < 0

           || av_image_check_size(avctx->width,       avctx->height,       0, avctx) < 0)) {

        av_log(avctx, AV_LOG_WARNING, "Ignoring invalid width/height values\n");

        avcodec_set_dimensions(avctx, 0, 0);

    }



    /* if the decoder init function was already called previously,

     * free the already allocated subtitle_header before overwriting it */

    if (av_codec_is_decoder(codec))

        av_freep(&avctx->subtitle_header);



    if (avctx->channels > FF_SANE_NB_CHANNELS) {

        ret = AVERROR(EINVAL);

        goto free_and_end;

    }



    avctx->codec = codec;

    if ((avctx->codec_type == AVMEDIA_TYPE_UNKNOWN || avctx->codec_type == codec->type) &&

        avctx->codec_id == AV_CODEC_ID_NONE) {

        avctx->codec_type = codec->type;

        avctx->codec_id   = codec->id;

    }

    if (avctx->codec_id != codec->id || (avctx->codec_type != codec->type

                                         && avctx->codec_type != AVMEDIA_TYPE_ATTACHMENT)) {

        av_log(avctx, AV_LOG_ERROR, "Codec type or id mismatches\n");

        ret = AVERROR(EINVAL);

        goto free_and_end;

    }

    avctx->frame_number = 0;

    avctx->codec_descriptor = avcodec_descriptor_get(avctx->codec_id);



    if (avctx->codec->capabilities & CODEC_CAP_EXPERIMENTAL &&

        avctx->strict_std_compliance > FF_COMPLIANCE_EXPERIMENTAL) {

        const char *codec_string = av_codec_is_encoder(codec) ? "encoder" : "decoder";

        AVCodec *codec2;

        av_log(NULL, AV_LOG_ERROR,

               "The %s '%s' is experimental but experimental codecs are not enabled, "

               "add '-strict %d' if you want to use it.\n",

               codec_string, codec->name, FF_COMPLIANCE_EXPERIMENTAL);

        codec2 = av_codec_is_encoder(codec) ? avcodec_find_encoder(codec->id) : avcodec_find_decoder(codec->id);

        if (!(codec2->capabilities & CODEC_CAP_EXPERIMENTAL))

            av_log(NULL, AV_LOG_ERROR, "Alternatively use the non experimental %s '%s'.\n",

                codec_string, codec2->name);

        ret = AVERROR_EXPERIMENTAL;

        goto free_and_end;

    }



    if (avctx->codec_type == AVMEDIA_TYPE_AUDIO &&

        (!avctx->time_base.num || !avctx->time_base.den)) {

        avctx->time_base.num = 1;

        avctx->time_base.den = avctx->sample_rate;

    }



    if (!HAVE_THREADS)

        av_log(avctx, AV_LOG_WARNING, "Warning: not compiled with thread support, using thread emulation\n");



    if (HAVE_THREADS) {

        ff_unlock_avcodec(); //we will instanciate a few encoders thus kick the counter to prevent false detection of a problem

        ret = ff_frame_thread_encoder_init(avctx, options ? *options : NULL);

        ff_lock_avcodec(avctx);

        if (ret < 0)

            goto free_and_end;

    }



    if (HAVE_THREADS && !avctx->thread_opaque

        && !(avctx->internal->frame_thread_encoder && (avctx->active_thread_type&FF_THREAD_FRAME))) {

        ret = ff_thread_init(avctx);

        if (ret < 0) {

            goto free_and_end;

        }

    }

    if (!HAVE_THREADS && !(codec->capabilities & CODEC_CAP_AUTO_THREADS))

        avctx->thread_count = 1;



    if (avctx->codec->max_lowres < avctx->lowres || avctx->lowres < 0) {

        av_log(avctx, AV_LOG_ERROR, "The maximum value for lowres supported by the decoder is %d\n",

               avctx->codec->max_lowres);

        ret = AVERROR(EINVAL);

        goto free_and_end;

    }



    if (av_codec_is_encoder(avctx->codec)) {

        int i;

        if (avctx->codec->sample_fmts) {

            for (i = 0; avctx->codec->sample_fmts[i] != AV_SAMPLE_FMT_NONE; i++) {

                if (avctx->sample_fmt == avctx->codec->sample_fmts[i])

                    break;

                if (avctx->channels == 1 &&

                    av_get_planar_sample_fmt(avctx->sample_fmt) ==

                    av_get_planar_sample_fmt(avctx->codec->sample_fmts[i])) {

                    avctx->sample_fmt = avctx->codec->sample_fmts[i];

                    break;

                }

            }

            if (avctx->codec->sample_fmts[i] == AV_SAMPLE_FMT_NONE) {

                char buf[128];

                snprintf(buf, sizeof(buf), "%d", avctx->sample_fmt);

                av_log(avctx, AV_LOG_ERROR, "Specified sample format %s is invalid or not supported\n",

                       (char *)av_x_if_null(av_get_sample_fmt_name(avctx->sample_fmt), buf));

                ret = AVERROR(EINVAL);

                goto free_and_end;

            }

        }

        if (avctx->codec->pix_fmts) {

            for (i = 0; avctx->codec->pix_fmts[i] != AV_PIX_FMT_NONE; i++)

                if (avctx->pix_fmt == avctx->codec->pix_fmts[i])

                    break;

            if (avctx->codec->pix_fmts[i] == AV_PIX_FMT_NONE

                && !((avctx->codec_id == AV_CODEC_ID_MJPEG || avctx->codec_id == AV_CODEC_ID_LJPEG)

                     && avctx->strict_std_compliance <= FF_COMPLIANCE_UNOFFICIAL)) {

                char buf[128];

                snprintf(buf, sizeof(buf), "%d", avctx->pix_fmt);

                av_log(avctx, AV_LOG_ERROR, "Specified pixel format %s is invalid or not supported\n",

                       (char *)av_x_if_null(av_get_pix_fmt_name(avctx->pix_fmt), buf));

                ret = AVERROR(EINVAL);

                goto free_and_end;

            }

        }

        if (avctx->codec->supported_samplerates) {

            for (i = 0; avctx->codec->supported_samplerates[i] != 0; i++)

                if (avctx->sample_rate == avctx->codec->supported_samplerates[i])

                    break;

            if (avctx->codec->supported_samplerates[i] == 0) {

                av_log(avctx, AV_LOG_ERROR, "Specified sample rate %d is not supported\n",

                       avctx->sample_rate);

                ret = AVERROR(EINVAL);

                goto free_and_end;

            }

        }

        if (avctx->codec->channel_layouts) {

            if (!avctx->channel_layout) {

                av_log(avctx, AV_LOG_WARNING, "Channel layout not specified\n");

            } else {

                for (i = 0; avctx->codec->channel_layouts[i] != 0; i++)

                    if (avctx->channel_layout == avctx->codec->channel_layouts[i])

                        break;

                if (avctx->codec->channel_layouts[i] == 0) {

                    char buf[512];

                    av_get_channel_layout_string(buf, sizeof(buf), -1, avctx->channel_layout);

                    av_log(avctx, AV_LOG_ERROR, "Specified channel layout '%s' is not supported\n", buf);

                    ret = AVERROR(EINVAL);

                    goto free_and_end;

                }

            }

        }

        if (avctx->channel_layout && avctx->channels) {

            int channels = av_get_channel_layout_nb_channels(avctx->channel_layout);

            if (channels != avctx->channels) {

                char buf[512];

                av_get_channel_layout_string(buf, sizeof(buf), -1, avctx->channel_layout);

                av_log(avctx, AV_LOG_ERROR,

                       "Channel layout '%s' with %d channels does not match number of specified channels %d\n",

                       buf, channels, avctx->channels);

                ret = AVERROR(EINVAL);

                goto free_and_end;

            }

        } else if (avctx->channel_layout) {

            avctx->channels = av_get_channel_layout_nb_channels(avctx->channel_layout);

        }

        if(avctx->codec_type == AVMEDIA_TYPE_VIDEO &&

           avctx->codec_id != AV_CODEC_ID_PNG // For mplayer

        ) {

            if (avctx->width <= 0 || avctx->height <= 0) {

                av_log(avctx, AV_LOG_ERROR, "dimensions not set\n");

                ret = AVERROR(EINVAL);

                goto free_and_end;

            }

        }

        if (   (avctx->codec_type == AVMEDIA_TYPE_VIDEO || avctx->codec_type == AVMEDIA_TYPE_AUDIO)

            && avctx->bit_rate>0 && avctx->bit_rate<1000) {

            av_log(avctx, AV_LOG_WARNING, "Bitrate %d is extremely low, maybe you mean %dk\n", avctx->bit_rate, avctx->bit_rate);

        }



        if (!avctx->rc_initial_buffer_occupancy)

            avctx->rc_initial_buffer_occupancy = avctx->rc_buffer_size * 3 / 4;

    }



    avctx->pts_correction_num_faulty_pts =

    avctx->pts_correction_num_faulty_dts = 0;

    avctx->pts_correction_last_pts =

    avctx->pts_correction_last_dts = INT64_MIN;



    if (   avctx->codec->init && (!(avctx->active_thread_type&FF_THREAD_FRAME)

        || avctx->internal->frame_thread_encoder)) {

        ret = avctx->codec->init(avctx);

        if (ret < 0) {

            goto free_and_end;

        }

    }



    ret=0;



    if (av_codec_is_decoder(avctx->codec)) {

        if (!avctx->bit_rate)

            avctx->bit_rate = get_bit_rate(avctx);

        /* validate channel layout from the decoder */

        if (avctx->channel_layout) {

            int channels = av_get_channel_layout_nb_channels(avctx->channel_layout);

            if (!avctx->channels)

                avctx->channels = channels;

            else if (channels != avctx->channels) {

                char buf[512];

                av_get_channel_layout_string(buf, sizeof(buf), -1, avctx->channel_layout);

                av_log(avctx, AV_LOG_WARNING,

                       "Channel layout '%s' with %d channels does not match specified number of channels %d: "

                       "ignoring specified channel layout\n",

                       buf, channels, avctx->channels);

                avctx->channel_layout = 0;

            }

        }

        if (avctx->channels && avctx->channels < 0 ||

            avctx->channels > FF_SANE_NB_CHANNELS) {

            ret = AVERROR(EINVAL);

            goto free_and_end;

        }

        if (avctx->sub_charenc) {

            if (avctx->codec_type != AVMEDIA_TYPE_SUBTITLE) {

                av_log(avctx, AV_LOG_ERROR, "Character encoding is only "

                       "supported with subtitles codecs\n");

                ret = AVERROR(EINVAL);

                goto free_and_end;

            } else if (avctx->codec_descriptor->props & AV_CODEC_PROP_BITMAP_SUB) {

                av_log(avctx, AV_LOG_WARNING, "Codec '%s' is bitmap-based, "

                       "subtitles character encoding will be ignored\n",

                       avctx->codec_descriptor->name);

                avctx->sub_charenc_mode = FF_SUB_CHARENC_MODE_DO_NOTHING;

            } else {

                /* input character encoding is set for a text based subtitle

                 * codec at this point */

                if (avctx->sub_charenc_mode == FF_SUB_CHARENC_MODE_AUTOMATIC)

                    avctx->sub_charenc_mode = FF_SUB_CHARENC_MODE_PRE_DECODER;



                if (avctx->sub_charenc_mode == FF_SUB_CHARENC_MODE_PRE_DECODER) {

#if CONFIG_ICONV

                    iconv_t cd = iconv_open("UTF-8", avctx->sub_charenc);

                    if (cd == (iconv_t)-1) {

                        av_log(avctx, AV_LOG_ERROR, "Unable to open iconv context "

                               "with input character encoding \"%s\"\n", avctx->sub_charenc);

                        ret = AVERROR(errno);

                        goto free_and_end;

                    }

                    iconv_close(cd);

#else

                    av_log(avctx, AV_LOG_ERROR, "Character encoding subtitles "

                           "conversion needs a libavcodec built with iconv support "

                           "for this codec\n");

                    ret = AVERROR(ENOSYS);

                    goto free_and_end;

#endif

                }

            }

        }

    }

end:

    ff_unlock_avcodec();

    if (options) {

        av_dict_free(options);

        *options = tmp;

    }



    return ret;

free_and_end:

    av_dict_free(&tmp);

    av_freep(&avctx->priv_data);

    if (avctx->internal)

        av_freep(&avctx->internal->pool);

    av_freep(&avctx->internal);

    avctx->codec = NULL;

    goto end;

}

unsigned long av_adler32_update(unsigned long adler, const uint8_t * buf,

                                unsigned int len)

{

    unsigned long s1 = adler & 0xffff;

    unsigned long s2 = adler >> 16;



    while (len > 0) {

#if CONFIG_SMALL

        while (len > 4  && s2 < (1U << 31)) {

            DO4(buf);

            len -= 4;

        }

#else

        while (len > 16 && s2 < (1U << 31)) {

            DO16(buf);

            len -= 16;

        }

#endif

        DO1(buf); len--;

        s1 %= BASE;

        s2 %= BASE;

    }

    return (s2 << 16) | s1;

}

static int mpc_read_seek(AVFormatContext *s, int stream_index, int64_t timestamp, int flags)

{

    AVStream *st = s->streams[stream_index];

    MPCContext *c = s->priv_data;

    AVPacket pkt1, *pkt = &pkt1;

    int ret;

    int index = av_index_search_timestamp(st, timestamp - DELAY_FRAMES, flags);

    uint32_t lastframe;



    /* if found, seek there */

    if (index >= 0){

        c->curframe = st->index_entries[index].pos;

        return 0;

    }

    /* if timestamp is out of bounds, return error */

    if(timestamp < 0 || timestamp >= c->fcount)

        return -1;

    timestamp -= DELAY_FRAMES;

    /* seek to the furthest known position and read packets until

       we reach desired position */

    lastframe = c->curframe;

    if(c->frames_noted) c->curframe = c->frames_noted - 1;

    while(c->curframe < timestamp){

        ret = av_read_frame(s, pkt);

        if (ret < 0){

            c->curframe = lastframe;

            return ret;

        }

        av_free_packet(pkt);

    }

    return 0;

}

av_cold void ff_gradfun_init_x86(GradFunContext *gf)

{

    int cpu_flags = av_get_cpu_flags();



    if (HAVE_MMX2 && cpu_flags & AV_CPU_FLAG_MMX2)

        gf->filter_line = gradfun_filter_line_mmx2;

    if (HAVE_SSSE3 && cpu_flags & AV_CPU_FLAG_SSSE3)

        gf->filter_line = gradfun_filter_line_ssse3;

    if (HAVE_SSE && cpu_flags & AV_CPU_FLAG_SSE2)

        gf->blur_line = gradfun_blur_line_sse2;

}

int ff_listen_bind(int fd, const struct sockaddr *addr,

                   socklen_t addrlen, int timeout)

{

    int ret;

    int reuse = 1;

    struct pollfd lp = { fd, POLLIN, 0 };

    setsockopt(fd, SOL_SOCKET, SO_REUSEADDR, &reuse, sizeof(reuse));

    ret = bind(fd, addr, addrlen);

    if (ret)

        return ff_neterrno();



    ret = listen(fd, 1);

    if (ret)

        return ff_neterrno();



    ret = poll(&lp, 1, timeout >= 0 ? timeout : -1);

    if (ret <= 0)

        return AVERROR(ETIMEDOUT);



    ret = accept(fd, NULL, NULL);

    if (ret < 0)

        return ff_neterrno();



    closesocket(fd);



    ff_socket_nonblock(ret, 1);

    return ret;

}

static int hls_read_header(AVFormatContext *s)

{

    void *u = (s->flags & AVFMT_FLAG_CUSTOM_IO) ? NULL : s->pb;

    HLSContext *c = s->priv_data;

    int ret = 0, i;

    int highest_cur_seq_no = 0;



    c->ctx                = s;

    c->interrupt_callback = &s->interrupt_callback;

    c->strict_std_compliance = s->strict_std_compliance;



    c->first_packet = 1;

    c->first_timestamp = AV_NOPTS_VALUE;

    c->cur_timestamp = AV_NOPTS_VALUE;



    if (u) {

        // get the previous user agent & set back to null if string size is zero

        update_options(&c->user_agent, "user-agent", u);



        // get the previous cookies & set back to null if string size is zero

        update_options(&c->cookies, "cookies", u);



        // get the previous headers & set back to null if string size is zero

        update_options(&c->headers, "headers", u);



        // get the previous http proxt & set back to null if string size is zero

        update_options(&c->http_proxy, "http_proxy", u);

    }



    if ((ret = parse_playlist(c, s->filename, NULL, s->pb)) < 0)

        goto fail;



    if ((ret = save_avio_options(s)) < 0)

        goto fail;



    /* Some HLS servers don't like being sent the range header */

    av_dict_set(&c->avio_opts, "seekable", "0", 0);



    if (c->n_variants == 0) {

        av_log(NULL, AV_LOG_WARNING, "Empty playlist\n");

        ret = AVERROR_EOF;

        goto fail;

    }

    /* If the playlist only contained playlists (Master Playlist),

     * parse each individual playlist. */

    if (c->n_playlists > 1 || c->playlists[0]->n_segments == 0) {

        for (i = 0; i < c->n_playlists; i++) {

            struct playlist *pls = c->playlists[i];

            if ((ret = parse_playlist(c, pls->url, pls, NULL)) < 0)

                goto fail;

        }

    }



    if (c->variants[0]->playlists[0]->n_segments == 0) {

        av_log(NULL, AV_LOG_WARNING, "Empty playlist\n");

        ret = AVERROR_EOF;

        goto fail;

    }



    /* If this isn't a live stream, calculate the total duration of the

     * stream. */

    if (c->variants[0]->playlists[0]->finished) {

        int64_t duration = 0;

        for (i = 0; i < c->variants[0]->playlists[0]->n_segments; i++)

            duration += c->variants[0]->playlists[0]->segments[i]->duration;

        s->duration = duration;

    }



    /* Associate renditions with variants */

    for (i = 0; i < c->n_variants; i++) {

        struct variant *var = c->variants[i];



        if (var->audio_group[0])

            add_renditions_to_variant(c, var, AVMEDIA_TYPE_AUDIO, var->audio_group);

        if (var->video_group[0])

            add_renditions_to_variant(c, var, AVMEDIA_TYPE_VIDEO, var->video_group);

        if (var->subtitles_group[0])

            add_renditions_to_variant(c, var, AVMEDIA_TYPE_SUBTITLE, var->subtitles_group);

    }



    /* Create a program for each variant */

    for (i = 0; i < c->n_variants; i++) {

        struct variant *v = c->variants[i];

        AVProgram *program;



        program = av_new_program(s, i);

        if (!program)

            goto fail;

        av_dict_set_int(&program->metadata, "variant_bitrate", v->bandwidth, 0);

    }



    /* Select the starting segments */

    for (i = 0; i < c->n_playlists; i++) {

        struct playlist *pls = c->playlists[i];



        if (pls->n_segments == 0)

            continue;



        pls->cur_seq_no = select_cur_seq_no(c, pls);

        highest_cur_seq_no = FFMAX(highest_cur_seq_no, pls->cur_seq_no);

    }



    /* Open the demuxer for each playlist */

    for (i = 0; i < c->n_playlists; i++) {

        struct playlist *pls = c->playlists[i];

        AVInputFormat *in_fmt = NULL;



        if (!(pls->ctx = avformat_alloc_context())) {

            ret = AVERROR(ENOMEM);

            goto fail;

        }



        if (pls->n_segments == 0)

            continue;



        pls->index  = i;

        pls->needed = 1;

        pls->parent = s;



        /*

         * If this is a live stream and this playlist looks like it is one segment

         * behind, try to sync it up so that every substream starts at the same

         * time position (so e.g. avformat_find_stream_info() will see packets from

         * all active streams within the first few seconds). This is not very generic,

         * though, as the sequence numbers are technically independent.

         */

        if (!pls->finished && pls->cur_seq_no == highest_cur_seq_no - 1 &&

            highest_cur_seq_no < pls->start_seq_no + pls->n_segments) {

            pls->cur_seq_no = highest_cur_seq_no;

        }



        pls->read_buffer = av_malloc(INITIAL_BUFFER_SIZE);

        if (!pls->read_buffer){

            ret = AVERROR(ENOMEM);

            avformat_free_context(pls->ctx);

            pls->ctx = NULL;

            goto fail;

        }

        ffio_init_context(&pls->pb, pls->read_buffer, INITIAL_BUFFER_SIZE, 0, pls,

                          read_data, NULL, NULL);

        pls->pb.seekable = 0;

        ret = av_probe_input_buffer(&pls->pb, &in_fmt, pls->segments[0]->url,

                                    NULL, 0, 0);

        if (ret < 0) {

            /* Free the ctx - it isn't initialized properly at this point,

             * so avformat_close_input shouldn't be called. If

             * avformat_open_input fails below, it frees and zeros the

             * context, so it doesn't need any special treatment like this. */

            av_log(s, AV_LOG_ERROR, "Error when loading first segment '%s'\n", pls->segments[0]->url);

            avformat_free_context(pls->ctx);

            pls->ctx = NULL;

            goto fail;

        }

        pls->ctx->pb       = &pls->pb;

        pls->ctx->io_open  = nested_io_open;



        if ((ret = ff_copy_whiteblacklists(pls->ctx, s)) < 0)

            goto fail;



        ret = avformat_open_input(&pls->ctx, pls->segments[0]->url, in_fmt, NULL);

        if (ret < 0)

            goto fail;



        if (pls->id3_deferred_extra && pls->ctx->nb_streams == 1) {

            ff_id3v2_parse_apic(pls->ctx, &pls->id3_deferred_extra);

            avformat_queue_attached_pictures(pls->ctx);

            ff_id3v2_free_extra_meta(&pls->id3_deferred_extra);

            pls->id3_deferred_extra = NULL;

        }



        pls->ctx->ctx_flags &= ~AVFMTCTX_NOHEADER;

        ret = avformat_find_stream_info(pls->ctx, NULL);

        if (ret < 0)

            goto fail;



        if (pls->is_id3_timestamped == -1)

            av_log(s, AV_LOG_WARNING, "No expected HTTP requests have been made\n");



        /* Create new AVStreams for each stream in this playlist */

        ret = update_streams_from_subdemuxer(s, pls);

        if (ret < 0)

            goto fail;



        add_metadata_from_renditions(s, pls, AVMEDIA_TYPE_AUDIO);

        add_metadata_from_renditions(s, pls, AVMEDIA_TYPE_VIDEO);

        add_metadata_from_renditions(s, pls, AVMEDIA_TYPE_SUBTITLE);

    }



    return 0;

fail:

    free_playlist_list(c);

    free_variant_list(c);

    free_rendition_list(c);

    return ret;

}

static av_cold int init_subtitles(AVFilterContext *ctx, const char *args)

{

    int ret, sid;

    AVFormatContext *fmt = NULL;

    AVCodecContext *dec_ctx = NULL;

    AVCodec *dec = NULL;

    AVStream *st;

    AVPacket pkt;

    AssContext *ass = ctx->priv;



    /* Init libass */

    ret = init(ctx, args, &subtitles_class);

    if (ret < 0)

        return ret;

    ass->track = ass_new_track(ass->library);

    if (!ass->track) {

        av_log(ctx, AV_LOG_ERROR, "Could not create a libass track\n");

        return AVERROR(EINVAL);

    }



    /* Open subtitles file */

    ret = avformat_open_input(&fmt, ass->filename, NULL, NULL);

    if (ret < 0) {

        av_log(ctx, AV_LOG_ERROR, "Unable to open %s\n", ass->filename);

        goto end;

    }

    ret = avformat_find_stream_info(fmt, NULL);

    if (ret < 0)

        goto end;



    /* Locate subtitles stream */

    ret = av_find_best_stream(fmt, AVMEDIA_TYPE_SUBTITLE, -1, -1, NULL, 0);

    if (ret < 0) {

        av_log(ctx, AV_LOG_ERROR, "Unable to locate subtitle stream in %s\n",

               ass->filename);

        goto end;

    }

    sid = ret;

    st = fmt->streams[sid];



    /* Open decoder */

    dec_ctx = st->codec;

    dec = avcodec_find_decoder(dec_ctx->codec_id);

    if (!dec) {

        av_log(ctx, AV_LOG_ERROR, "Failed to find subtitle codec %s\n",

               avcodec_get_name(dec_ctx->codec_id));

        return AVERROR(EINVAL);

    }

    ret = avcodec_open2(dec_ctx, dec, NULL);

    if (ret < 0)

        goto end;



    /* Decode subtitles and push them into the renderer (libass) */

    if (dec_ctx->subtitle_header)

        ass_process_codec_private(ass->track,

                                  dec_ctx->subtitle_header,

                                  dec_ctx->subtitle_header_size);

    av_init_packet(&pkt);

    pkt.data = NULL;

    pkt.size = 0;

    while (av_read_frame(fmt, &pkt) >= 0) {

        int i, got_subtitle;

        AVSubtitle sub;



        if (pkt.stream_index == sid) {

            ret = avcodec_decode_subtitle2(dec_ctx, &sub, &got_subtitle, &pkt);

            if (ret < 0 || !got_subtitle)

                break;

            for (i = 0; i < sub.num_rects; i++) {

                char *ass_line = sub.rects[i]->ass;

                if (!ass_line)

                    break;

                ass_process_data(ass->track, ass_line, strlen(ass_line));

            }

        }

        av_free_packet(&pkt);

        avsubtitle_free(&sub);

    }



end:

    if (fmt)

        avformat_close_input(&fmt);

    if (dec_ctx)

        avcodec_close(dec_ctx);

    return ret;

}

static void rv30_loop_filter(RV34DecContext *r, int row)

{

    MpegEncContext *s = &r->s;

    int mb_pos, mb_x;

    int i, j, k;

    uint8_t *Y, *C;

    int loc_lim, cur_lim, left_lim = 0, top_lim = 0;



    mb_pos = row * s->mb_stride;

    for(mb_x = 0; mb_x < s->mb_width; mb_x++, mb_pos++){

        int mbtype = s->current_picture_ptr->mb_type[mb_pos];

        if(IS_INTRA(mbtype) || IS_SEPARATE_DC(mbtype))

            r->deblock_coefs[mb_pos] = 0xFFFF;

        if(IS_INTRA(mbtype))

            r->cbp_chroma[mb_pos] = 0xFF;

    }



    /* all vertical edges are filtered first

     * and horizontal edges are filtered on the next iteration

     */

    mb_pos = row * s->mb_stride;

    for(mb_x = 0; mb_x < s->mb_width; mb_x++, mb_pos++){

        cur_lim = rv30_loop_filt_lim[s->current_picture_ptr->qscale_table[mb_pos]];

        if(mb_x)

            left_lim = rv30_loop_filt_lim[s->current_picture_ptr->qscale_table[mb_pos - 1]];

        for(j = 0; j < 16; j += 4){

            Y = s->current_picture_ptr->f.data[0] + mb_x*16 + (row*16 + j) * s->linesize + 4 * !mb_x;

            for(i = !mb_x; i < 4; i++, Y += 4){

                int ij = i + j;

                loc_lim = 0;

                if(r->deblock_coefs[mb_pos] & (1 << ij))

                    loc_lim = cur_lim;

                else if(!i && r->deblock_coefs[mb_pos - 1] & (1 << (ij + 3)))

                    loc_lim = left_lim;

                else if( i && r->deblock_coefs[mb_pos]     & (1 << (ij - 1)))

                    loc_lim = cur_lim;

                if(loc_lim)

                    rv30_weak_loop_filter(Y, 1, s->linesize, loc_lim);

            }

        }

        for(k = 0; k < 2; k++){

            int cur_cbp, left_cbp = 0;

            cur_cbp = (r->cbp_chroma[mb_pos] >> (k*4)) & 0xF;

            if(mb_x)

                left_cbp = (r->cbp_chroma[mb_pos - 1] >> (k*4)) & 0xF;

            for(j = 0; j < 8; j += 4){

                C = s->current_picture_ptr->f.data[k + 1] + mb_x*8 + (row*8 + j) * s->uvlinesize + 4 * !mb_x;

                for(i = !mb_x; i < 2; i++, C += 4){

                    int ij = i + (j >> 1);

                    loc_lim = 0;

                    if (cur_cbp & (1 << ij))

                        loc_lim = cur_lim;

                    else if(!i && left_cbp & (1 << (ij + 1)))

                        loc_lim = left_lim;

                    else if( i && cur_cbp  & (1 << (ij - 1)))

                        loc_lim = cur_lim;

                    if(loc_lim)

                        rv30_weak_loop_filter(C, 1, s->uvlinesize, loc_lim);

                }

            }

        }

    }

    mb_pos = row * s->mb_stride;

    for(mb_x = 0; mb_x < s->mb_width; mb_x++, mb_pos++){

        cur_lim = rv30_loop_filt_lim[s->current_picture_ptr->qscale_table[mb_pos]];

        if(row)

            top_lim = rv30_loop_filt_lim[s->current_picture_ptr->qscale_table[mb_pos - s->mb_stride]];

        for(j = 4*!row; j < 16; j += 4){

            Y = s->current_picture_ptr->f.data[0] + mb_x*16 + (row*16 + j) * s->linesize;

            for(i = 0; i < 4; i++, Y += 4){

                int ij = i + j;

                loc_lim = 0;

                if(r->deblock_coefs[mb_pos] & (1 << ij))

                    loc_lim = cur_lim;

                else if(!j && r->deblock_coefs[mb_pos - s->mb_stride] & (1 << (ij + 12)))

                    loc_lim = top_lim;

                else if( j && r->deblock_coefs[mb_pos]                & (1 << (ij - 4)))

                    loc_lim = cur_lim;

                if(loc_lim)

                    rv30_weak_loop_filter(Y, s->linesize, 1, loc_lim);

            }

        }

        for(k = 0; k < 2; k++){

            int cur_cbp, top_cbp = 0;

            cur_cbp = (r->cbp_chroma[mb_pos] >> (k*4)) & 0xF;

            if(row)

                top_cbp = (r->cbp_chroma[mb_pos - s->mb_stride] >> (k*4)) & 0xF;

            for(j = 4*!row; j < 8; j += 4){

                C = s->current_picture_ptr->f.data[k+1] + mb_x*8 + (row*8 + j) * s->uvlinesize;

                for(i = 0; i < 2; i++, C += 4){

                    int ij = i + (j >> 1);

                    loc_lim = 0;

                    if (r->cbp_chroma[mb_pos] & (1 << ij))

                        loc_lim = cur_lim;

                    else if(!j && top_cbp & (1 << (ij + 2)))

                        loc_lim = top_lim;

                    else if( j && cur_cbp & (1 << (ij - 2)))

                        loc_lim = cur_lim;

                    if(loc_lim)

                        rv30_weak_loop_filter(C, s->uvlinesize, 1, loc_lim);

                }

            }

        }

    }

}

static void alac_linear_predictor(AlacEncodeContext *s, int ch)

{

    int i;

    LPCContext lpc = s->lpc[ch];



    if(lpc.lpc_order == 31) {

        s->predictor_buf[0] = s->sample_buf[ch][0];



        for(i=1; i<s->avctx->frame_size; i++)

            s->predictor_buf[i] = s->sample_buf[ch][i] - s->sample_buf[ch][i-1];



        return;

    }



    // generalised linear predictor



    if(lpc.lpc_order > 0) {

        int32_t *samples  = s->sample_buf[ch];

        int32_t *residual = s->predictor_buf;



        // generate warm-up samples

        residual[0] = samples[0];

        for(i=1;i<=lpc.lpc_order;i++)

            residual[i] = samples[i] - samples[i-1];



        // perform lpc on remaining samples

        for(i = lpc.lpc_order + 1; i < s->avctx->frame_size; i++) {

            int sum = 1 << (lpc.lpc_quant - 1), res_val, j;



            for (j = 0; j < lpc.lpc_order; j++) {

                sum += (samples[lpc.lpc_order-j] - samples[0]) *

                        lpc.lpc_coeff[j];

            }



            sum >>= lpc.lpc_quant;

            sum += samples[0];

            residual[i] = samples[lpc.lpc_order+1] - sum;

            res_val = residual[i];



            if(res_val) {

                int index = lpc.lpc_order - 1;

                int neg = (res_val < 0);



                while(index >= 0 && (neg ? (res_val < 0):(res_val > 0))) {

                    int val = samples[0] - samples[lpc.lpc_order - index];

                    int sign = (val ? FFSIGN(val) : 0);



                    if(neg)

                        sign*=-1;



                    lpc.lpc_coeff[index] -= sign;

                    val *= sign;

                    res_val -= ((val >> lpc.lpc_quant) *

                            (lpc.lpc_order - index));

                    index--;

                }

            }

            samples++;

        }

    }

}

static int parse_psfile(AVFilterContext *ctx, const char *fname)

{

    CurvesContext *curves = ctx->priv;

    uint8_t *buf;

    size_t size;

    int i, ret, av_unused(version), nb_curves;

    AVBPrint ptstr;

    static const int comp_ids[] = {3, 0, 1, 2};



    av_bprint_init(&ptstr, 0, AV_BPRINT_SIZE_AUTOMATIC);



    ret = av_file_map(fname, &buf, &size, 0, NULL);

    if (ret < 0)

        return ret;



#define READ16(dst) do {                \

    if (size < 2)                       \

        return AVERROR_INVALIDDATA;     \

    dst = AV_RB16(buf);                 \

    buf  += 2;                          \

    size -= 2;                          \

} while (0)



    READ16(version);

    READ16(nb_curves);

    for (i = 0; i < FFMIN(nb_curves, FF_ARRAY_ELEMS(comp_ids)); i++) {

        int nb_points, n;

        av_bprint_clear(&ptstr);

        READ16(nb_points);

        for (n = 0; n < nb_points; n++) {

            int y, x;

            READ16(y);

            READ16(x);

            av_bprintf(&ptstr, "%f/%f ", x / 255., y / 255.);

        }

        if (*ptstr.str) {

            char **pts = &curves->comp_points_str[comp_ids[i]];

            if (!*pts) {

                *pts = av_strdup(ptstr.str);

                av_log(ctx, AV_LOG_DEBUG, "curves %d (intid=%d) [%d points]: [%s]\n",

                       i, comp_ids[i], nb_points, *pts);

                if (!*pts) {

                    ret = AVERROR(ENOMEM);

                    goto end;

                }

            }

        }

    }

end:

    av_bprint_finalize(&ptstr, NULL);

    av_file_unmap(buf, size);

    return ret;

}

static int svq3_decode_slice_header(AVCodecContext *avctx)

{

    SVQ3Context *svq3 = avctx->priv_data;

    H264Context *h    = &svq3->h;

    MpegEncContext *s = &h->s;

    const int mb_xy   = h->mb_xy;

    int i, header;



    header = get_bits(&s->gb, 8);



    if (((header & 0x9F) != 1 && (header & 0x9F) != 2) || (header & 0x60) == 0) {

        /* TODO: what? */

        av_log(avctx, AV_LOG_ERROR, "unsupported slice header (%02X)\n", header);

        return -1;

    } else {

        int length = header >> 5 & 3;



        svq3->next_slice_index = get_bits_count(&s->gb) +

                                 8 * show_bits(&s->gb, 8 * length) +

                                 8 * length;



        if (svq3->next_slice_index > s->gb.size_in_bits) {

            av_log(avctx, AV_LOG_ERROR, "slice after bitstream end\n");

            return -1;

        }



        s->gb.size_in_bits = svq3->next_slice_index - 8 * (length - 1);

        skip_bits(&s->gb, 8);



        if (svq3->watermark_key) {

            uint32_t header = AV_RL32(&s->gb.buffer[(get_bits_count(&s->gb) >> 3) + 1]);

            AV_WL32(&s->gb.buffer[(get_bits_count(&s->gb) >> 3) + 1],

                    header ^ svq3->watermark_key);

        }

        if (length > 0) {

            memcpy((uint8_t *) &s->gb.buffer[get_bits_count(&s->gb) >> 3],

                   &s->gb.buffer[s->gb.size_in_bits >> 3], length - 1);

        }

        skip_bits_long(&s->gb, 0);

    }



    if ((i = svq3_get_ue_golomb(&s->gb)) == INVALID_VLC || i >= 3) {

        av_log(h->s.avctx, AV_LOG_ERROR, "illegal slice type %d \n", i);

        return -1;

    }



    h->slice_type = golomb_to_pict_type[i];



    if ((header & 0x9F) == 2) {

        i              = (s->mb_num < 64) ? 6 : (1 + av_log2(s->mb_num - 1));

        s->mb_skip_run = get_bits(&s->gb, i) -

                         (s->mb_y * s->mb_width + s->mb_x);

    } else {

        skip_bits1(&s->gb);

        s->mb_skip_run = 0;

    }



    h->slice_num      = get_bits(&s->gb, 8);

    s->qscale         = get_bits(&s->gb, 5);

    s->adaptive_quant = get_bits1(&s->gb);



    /* unknown fields */

    skip_bits1(&s->gb);



    if (svq3->unknown_flag)

        skip_bits1(&s->gb);



    skip_bits1(&s->gb);

    skip_bits(&s->gb, 2);



    while (get_bits1(&s->gb))

        skip_bits(&s->gb, 8);



    /* reset intra predictors and invalidate motion vector references */

    if (s->mb_x > 0) {

        memset(h->intra4x4_pred_mode + h->mb2br_xy[mb_xy - 1] + 3,

               -1, 4 * sizeof(int8_t));

        memset(h->intra4x4_pred_mode + h->mb2br_xy[mb_xy - s->mb_x],

               -1, 8 * sizeof(int8_t) * s->mb_x);

    }

    if (s->mb_y > 0) {

        memset(h->intra4x4_pred_mode + h->mb2br_xy[mb_xy - s->mb_stride],

               -1, 8 * sizeof(int8_t) * (s->mb_width - s->mb_x));



        if (s->mb_x > 0)

            h->intra4x4_pred_mode[h->mb2br_xy[mb_xy - s->mb_stride - 1] + 3] = -1;

    }



    return 0;

}

int av_probe_input_buffer(AVIOContext *pb, AVInputFormat **fmt,

                          const char *filename, void *logctx,

                          unsigned int offset, unsigned int max_probe_size)

{

    AVProbeData pd = { filename ? filename : "", NULL, -offset };

    unsigned char *buf = NULL;

    int ret = 0, probe_size;



    if (!max_probe_size) {

        max_probe_size = PROBE_BUF_MAX;

    } else if (max_probe_size > PROBE_BUF_MAX) {

        max_probe_size = PROBE_BUF_MAX;

    } else if (max_probe_size < PROBE_BUF_MIN) {

        return AVERROR(EINVAL);

    }



    if (offset >= max_probe_size) {

        return AVERROR(EINVAL);

    }



    for(probe_size= PROBE_BUF_MIN; probe_size<=max_probe_size && !*fmt;

        probe_size = FFMIN(probe_size<<1, FFMAX(max_probe_size, probe_size+1))) {

        int score = probe_size < max_probe_size ? AVPROBE_SCORE_RETRY : 0;

        int buf_offset = (probe_size == PROBE_BUF_MIN) ? 0 : probe_size>>1;

        void *buftmp;



        if (probe_size < offset) {

            continue;

        }



        /* read probe data */

        buftmp = av_realloc(buf, probe_size + AVPROBE_PADDING_SIZE);

        if(!buftmp){

            av_free(buf);

            return AVERROR(ENOMEM);

        }

        buf=buftmp;

        if ((ret = avio_read(pb, buf + buf_offset, probe_size - buf_offset)) < 0) {

            /* fail if error was not end of file, otherwise, lower score */

            if (ret != AVERROR_EOF) {

                av_free(buf);

                return ret;

            }

            score = 0;

            ret = 0;            /* error was end of file, nothing read */

        }

        pd.buf_size += ret;

        pd.buf = &buf[offset];



        memset(pd.buf + pd.buf_size, 0, AVPROBE_PADDING_SIZE);



        /* guess file format */

        *fmt = av_probe_input_format2(&pd, 1, &score);

        if(*fmt){

            if(score <= AVPROBE_SCORE_RETRY){ //this can only be true in the last iteration

                av_log(logctx, AV_LOG_WARNING, "Format %s detected only with low score of %d, misdetection possible!\n", (*fmt)->name, score);

            }else

                av_log(logctx, AV_LOG_DEBUG, "Format %s probed with size=%d and score=%d\n", (*fmt)->name, probe_size, score);

        }

    }



    if (!*fmt) {

        av_free(buf);

        return AVERROR_INVALIDDATA;

    }



    /* rewind. reuse probe buffer to avoid seeking */

    if ((ret = ffio_rewind_with_probe_data(pb, buf, pd.buf_size)) < 0)

        av_free(buf);



    return ret;

}

static int mov_read_stsz(MOVContext *c, AVIOContext *pb, MOVAtom atom)

{

    AVStream *st;

    MOVStreamContext *sc;

    unsigned int i, entries, sample_size, field_size, num_bytes;

    GetBitContext gb;

    unsigned char* buf;



    if (c->fc->nb_streams < 1)

        return 0;

    st = c->fc->streams[c->fc->nb_streams-1];

    sc = st->priv_data;



    avio_r8(pb); /* version */

    avio_rb24(pb); /* flags */



    if (atom.type == MKTAG('s','t','s','z')) {

        sample_size = avio_rb32(pb);

        if (!sc->sample_size) /* do not overwrite value computed in stsd */

            sc->sample_size = sample_size;

        field_size = 32;

    } else {

        sample_size = 0;

        avio_rb24(pb); /* reserved */

        field_size = avio_r8(pb);

    }

    entries = avio_rb32(pb);



    av_log(c->fc, AV_LOG_TRACE, "sample_size = %d sample_count = %d\n", sc->sample_size, entries);



    sc->sample_count = entries;

    if (sample_size)

        return 0;



    if (field_size != 4 && field_size != 8 && field_size != 16 && field_size != 32) {

        av_log(c->fc, AV_LOG_ERROR, "Invalid sample field size %d\n", field_size);

        return AVERROR_INVALIDDATA;

    }



    if (!entries)

        return 0;

    if (entries >= UINT_MAX / sizeof(int) || entries >= (UINT_MAX - 4) / field_size)

        return AVERROR_INVALIDDATA;

    sc->sample_sizes = av_malloc(entries * sizeof(int));

    if (!sc->sample_sizes)

        return AVERROR(ENOMEM);



    num_bytes = (entries*field_size+4)>>3;



    buf = av_malloc(num_bytes+FF_INPUT_BUFFER_PADDING_SIZE);

    if (!buf) {

        av_freep(&sc->sample_sizes);

        return AVERROR(ENOMEM);

    }



    if (avio_read(pb, buf, num_bytes) < num_bytes) {

        av_freep(&sc->sample_sizes);

        av_free(buf);

        return AVERROR_INVALIDDATA;

    }



    init_get_bits(&gb, buf, 8*num_bytes);



    for (i = 0; i < entries && !pb->eof_reached; i++) {

        sc->sample_sizes[i] = get_bits_long(&gb, field_size);

        sc->data_size += sc->sample_sizes[i];

    }



    sc->sample_count = i;



    av_free(buf);



    if (pb->eof_reached)

        return AVERROR_EOF;



    return 0;

}

static inline void writer_print_string(WriterContext *wctx,

                                       const char *key, const char *val, int opt)

{

    const struct section *section = wctx->section[wctx->level];



    if (opt && !(wctx->writer->flags & WRITER_FLAG_DISPLAY_OPTIONAL_FIELDS))

        return;



    if (section->show_all_entries || av_dict_get(section->entries_to_show, key, NULL, 0)) {

        wctx->writer->print_string(wctx, key, val);

        wctx->nb_item[wctx->level]++;

    }

}

static int verify_expr(AVExpr *e)

{

    if (!e) return 0;

    switch (e->type) {

        case e_value:

        case e_const: return 1;

        case e_func0:

        case e_func1:

        case e_squish:

        case e_ld:

        case e_gauss:

        case e_isnan:

        case e_floor:

        case e_ceil:

        case e_trunc:

        case e_sqrt:

        case e_not:

        case e_random:

            return verify_expr(e->param[0]) && !e->param[2];

        case e_taylor:

            return verify_expr(e->param[0]) && verify_expr(e->param[1])

                   && (!e->param[2] || verify_expr(e->param[2]));

        default: return verify_expr(e->param[0]) && verify_expr(e->param[1]) && !e->param[2];

    }

}

