static void deinterlace_bottom_field_inplace(uint8_t *src1, int src_wrap,

                                             int width, int height)

{

    uint8_t *src_m1, *src_0, *src_p1, *src_p2;

    int y;

    uint8_t *buf;

    buf = av_malloc(width);



    src_m1 = src1;

    memcpy(buf,src_m1,width);

    src_0=&src_m1[src_wrap];

    src_p1=&src_0[src_wrap];

    src_p2=&src_p1[src_wrap];

    for(y=0;y<(height-2);y+=2) {

        deinterlace_line_inplace(buf,src_m1,src_0,src_p1,src_p2,width);

        src_m1 = src_p1;

        src_0 = src_p2;

        src_p1 += 2*src_wrap;

        src_p2 += 2*src_wrap;

    }

    /* do last line */

    deinterlace_line_inplace(buf,src_m1,src_0,src_0,src_0,width);

    av_free(buf);

}

void ff_h264_filter_mb_fast( H264Context *h, int mb_x, int mb_y, uint8_t *img_y, uint8_t *img_cb, uint8_t *img_cr, unsigned int linesize, unsigned int uvlinesize) {

    MpegEncContext * const s = &h->s;

    int mb_xy;

    int mb_type, left_type, top_type;

    int qp, qp0, qp1, qpc, qpc0, qpc1, qp_thresh;

    int chroma = !(CONFIG_GRAY && (s->flags&CODEC_FLAG_GRAY));

    int chroma444 = CHROMA444;



    mb_xy = h->mb_xy;



    if(!h->h264dsp.h264_loop_filter_strength || h->pps.chroma_qp_diff) {

        ff_h264_filter_mb(h, mb_x, mb_y, img_y, img_cb, img_cr, linesize, uvlinesize);

        return;

    }

    assert(!FRAME_MBAFF);

    left_type= h->left_type[LTOP];

    top_type= h->top_type;



    mb_type = s->current_picture.mb_type[mb_xy];

    qp = s->current_picture.qscale_table[mb_xy];

    qp0 = s->current_picture.qscale_table[mb_xy-1];

    qp1 = s->current_picture.qscale_table[h->top_mb_xy];

    qpc = get_chroma_qp( h, 0, qp );

    qpc0 = get_chroma_qp( h, 0, qp0 );

    qpc1 = get_chroma_qp( h, 0, qp1 );

    qp0 = (qp + qp0 + 1) >> 1;

    qp1 = (qp + qp1 + 1) >> 1;

    qpc0 = (qpc + qpc0 + 1) >> 1;

    qpc1 = (qpc + qpc1 + 1) >> 1;

    qp_thresh = 15+52 - h->slice_alpha_c0_offset;

    if(qp <= qp_thresh && qp0 <= qp_thresh && qp1 <= qp_thresh &&

       qpc <= qp_thresh && qpc0 <= qp_thresh && qpc1 <= qp_thresh)

        return;



    if( IS_INTRA(mb_type) ) {

        int16_t bS4[4] = {4,4,4,4};

        int16_t bS3[4] = {3,3,3,3};

        int16_t *bSH = FIELD_PICTURE ? bS3 : bS4;

        if(left_type)

            filter_mb_edgev( &img_y[4*0], linesize, bS4, qp0, h);

        if( IS_8x8DCT(mb_type) ) {

            filter_mb_edgev( &img_y[4*2], linesize, bS3, qp, h);

            if(top_type){

                filter_mb_edgeh( &img_y[4*0*linesize], linesize, bSH, qp1, h);

            }

            filter_mb_edgeh( &img_y[4*2*linesize], linesize, bS3, qp, h);

        } else {

            filter_mb_edgev( &img_y[4*1], linesize, bS3, qp, h);

            filter_mb_edgev( &img_y[4*2], linesize, bS3, qp, h);

            filter_mb_edgev( &img_y[4*3], linesize, bS3, qp, h);

            if(top_type){

                filter_mb_edgeh( &img_y[4*0*linesize], linesize, bSH, qp1, h);

            }

            filter_mb_edgeh( &img_y[4*1*linesize], linesize, bS3, qp, h);

            filter_mb_edgeh( &img_y[4*2*linesize], linesize, bS3, qp, h);

            filter_mb_edgeh( &img_y[4*3*linesize], linesize, bS3, qp, h);

        }

        if(chroma){

            if(chroma444){

                if(left_type){

                    filter_mb_edgev( &img_cb[4*0], linesize, bS4, qpc0, h);

                    filter_mb_edgev( &img_cr[4*0], linesize, bS4, qpc0, h);

                }

                if( IS_8x8DCT(mb_type) ) {

                    filter_mb_edgev( &img_cb[4*2], linesize, bS3, qpc, h);

                    filter_mb_edgev( &img_cr[4*2], linesize, bS3, qpc, h);

                    if(top_type){

                        filter_mb_edgeh( &img_cb[4*0*linesize], linesize, bSH, qpc1, h);

                        filter_mb_edgeh( &img_cr[4*0*linesize], linesize, bSH, qpc1, h);

                    }

                    filter_mb_edgeh( &img_cb[4*2*linesize], linesize, bS3, qpc, h);

                    filter_mb_edgeh( &img_cr[4*2*linesize], linesize, bS3, qpc, h);

                } else {

                    filter_mb_edgev( &img_cb[4*1], linesize, bS3, qpc, h);

                    filter_mb_edgev( &img_cr[4*1], linesize, bS3, qpc, h);

                    filter_mb_edgev( &img_cb[4*2], linesize, bS3, qpc, h);

                    filter_mb_edgev( &img_cr[4*2], linesize, bS3, qpc, h);

                    filter_mb_edgev( &img_cb[4*3], linesize, bS3, qpc, h);

                    filter_mb_edgev( &img_cr[4*3], linesize, bS3, qpc, h);

                    if(top_type){

                        filter_mb_edgeh( &img_cb[4*0*linesize], linesize, bSH, qpc1, h);

                        filter_mb_edgeh( &img_cr[4*0*linesize], linesize, bSH, qpc1, h);

                    }

                    filter_mb_edgeh( &img_cb[4*1*linesize], linesize, bS3, qpc, h);

                    filter_mb_edgeh( &img_cr[4*1*linesize], linesize, bS3, qpc, h);

                    filter_mb_edgeh( &img_cb[4*2*linesize], linesize, bS3, qpc, h);

                    filter_mb_edgeh( &img_cr[4*2*linesize], linesize, bS3, qpc, h);

                    filter_mb_edgeh( &img_cb[4*3*linesize], linesize, bS3, qpc, h);

                    filter_mb_edgeh( &img_cr[4*3*linesize], linesize, bS3, qpc, h);

                }

            }else{

                if(left_type){

                    filter_mb_edgecv( &img_cb[2*0], uvlinesize, bS4, qpc0, h);

                    filter_mb_edgecv( &img_cr[2*0], uvlinesize, bS4, qpc0, h);

                }

                filter_mb_edgecv( &img_cb[2*2], uvlinesize, bS3, qpc, h);

                filter_mb_edgecv( &img_cr[2*2], uvlinesize, bS3, qpc, h);

                if(top_type){

                    filter_mb_edgech( &img_cb[2*0*uvlinesize], uvlinesize, bSH, qpc1, h);

                    filter_mb_edgech( &img_cr[2*0*uvlinesize], uvlinesize, bSH, qpc1, h);

                }

                filter_mb_edgech( &img_cb[2*2*uvlinesize], uvlinesize, bS3, qpc, h);

                filter_mb_edgech( &img_cr[2*2*uvlinesize], uvlinesize, bS3, qpc, h);

            }

        }

        return;

    } else {

        LOCAL_ALIGNED_8(int16_t, bS, [2], [4][4]);

        int edges;

        if( IS_8x8DCT(mb_type) && (h->cbp&7) == 7 ) {

            edges = 4;

            AV_WN64A(bS[0][0], 0x0002000200020002ULL);

            AV_WN64A(bS[0][2], 0x0002000200020002ULL);

            AV_WN64A(bS[1][0], 0x0002000200020002ULL);

            AV_WN64A(bS[1][2], 0x0002000200020002ULL);

        } else {

            int mask_edge1 = (3*(((5*mb_type)>>5)&1)) | (mb_type>>4); //(mb_type & (MB_TYPE_16x16 | MB_TYPE_8x16)) ? 3 : (mb_type & MB_TYPE_16x8) ? 1 : 0;

            int mask_edge0 = 3*((mask_edge1>>1) & ((5*left_type)>>5)&1); // (mb_type & (MB_TYPE_16x16 | MB_TYPE_8x16)) && (h->left_type[LTOP] & (MB_TYPE_16x16 | MB_TYPE_8x16)) ? 3 : 0;

            int step =  1+(mb_type>>24); //IS_8x8DCT(mb_type) ? 2 : 1;

            edges = 4 - 3*((mb_type>>3) & !(h->cbp & 15)); //(mb_type & MB_TYPE_16x16) && !(h->cbp & 15) ? 1 : 4;

            h->h264dsp.h264_loop_filter_strength( bS, h->non_zero_count_cache, h->ref_cache, h->mv_cache,

                                              h->list_count==2, edges, step, mask_edge0, mask_edge1, FIELD_PICTURE);

        }

        if( IS_INTRA(left_type) )

            AV_WN64A(bS[0][0], 0x0004000400040004ULL);

        if( IS_INTRA(top_type) )

            AV_WN64A(bS[1][0], FIELD_PICTURE ? 0x0003000300030003ULL : 0x0004000400040004ULL);



#define FILTER(hv,dir,edge)\

        if(AV_RN64A(bS[dir][edge])) {                                   \

            filter_mb_edge##hv( &img_y[4*edge*(dir?linesize:1)], linesize, bS[dir][edge], edge ? qp : qp##dir, h );\

            if(chroma){\

                if(chroma444){\

                    filter_mb_edge##hv( &img_cb[4*edge*(dir?linesize:1)], linesize, bS[dir][edge], edge ? qpc : qpc##dir, h );\

                    filter_mb_edge##hv( &img_cr[4*edge*(dir?linesize:1)], linesize, bS[dir][edge], edge ? qpc : qpc##dir, h );\

                } else if(!(edge&1)) {\

                    filter_mb_edgec##hv( &img_cb[2*edge*(dir?uvlinesize:1)], uvlinesize, bS[dir][edge], edge ? qpc : qpc##dir, h );\

                    filter_mb_edgec##hv( &img_cr[2*edge*(dir?uvlinesize:1)], uvlinesize, bS[dir][edge], edge ? qpc : qpc##dir, h );\

                }\

            }\

        }

        if(left_type)

            FILTER(v,0,0);

        if( edges == 1 ) {

            if(top_type)

                FILTER(h,1,0);

        } else if( IS_8x8DCT(mb_type) ) {

            FILTER(v,0,2);

            if(top_type)

                FILTER(h,1,0);

            FILTER(h,1,2);

        } else {

            FILTER(v,0,1);

            FILTER(v,0,2);

            FILTER(v,0,3);

            if(top_type)

                FILTER(h,1,0);

            FILTER(h,1,1);

            FILTER(h,1,2);

            FILTER(h,1,3);

        }

#undef FILTER

    }

}

static inline void downmix_2f_1r_to_mono(float *samples)

{

    int i;



    for (i = 0; i < 256; i++) {

        samples[i] += (samples[i + 256] + samples[i + 512]);

        samples[i + 256] = samples[i + 512] = 0;

    }

}

static void do_bit_allocation1(AC3DecodeContext *ctx, int chnl)

{

    ac3_audio_block *ab = &ctx->audio_block;

    int sdecay, fdecay, sgain, dbknee, floor;

    int lowcomp = 0, fgain = 0, snroffset = 0, fastleak = 0, slowleak = 0;

    int psd[256], bndpsd[50], excite[50], mask[50], delta;

    int start = 0, end = 0, bin = 0, i = 0, j = 0, k = 0, lastbin = 0, bndstrt = 0;

    int bndend = 0, begin = 0, deltnseg = 0, band = 0, seg = 0, address = 0;

    int fscod = ctx->sync_info.fscod;

    uint8_t *exps, *deltoffst = 0, *deltlen = 0, *deltba = 0;

    uint8_t *baps;

    int do_delta = 0;



    /* initialization */

    sdecay = sdecaytab[ab->sdcycod];

    fdecay = fdecaytab[ab->fdcycod];

    sgain = sgaintab[ab->sgaincod];

    dbknee = dbkneetab[ab->dbpbcod];

    floor = floortab[ab->floorcod];



    if (chnl == 5) {

        start = ab->cplstrtmant;

        end = ab->cplendmant;

        fgain = fgaintab[ab->cplfgaincod];

        snroffset = (((ab->csnroffst - 15) << 4) + ab->cplfsnroffst) << 2;

        fastleak = (ab->cplfleak << 8) + 768;

        slowleak = (ab->cplsleak << 8) + 768;

        exps = ab->dcplexps;

        baps = ab->cplbap;

        if (ab->cpldeltbae == AC3_DBASTR_NEW || ab->cpldeltbae == AC3_DBASTR_REUSE) {

            do_delta = 1;

            deltnseg = ab->cpldeltnseg;

            deltoffst = ab->cpldeltoffst;

            deltlen = ab->cpldeltlen;

            deltba = ab->cpldeltba;

        }

    }

    else if (chnl == 6) {

        start = 0;

        end = 7;

        lowcomp = 0;

        fastleak = 0;

        slowleak = 0;

        fgain = fgaintab[ab->lfefgaincod];

        snroffset = (((ab->csnroffst - 15) << 4) + ab->lfefsnroffst) << 2;

        exps = ab->dlfeexps;

        baps = ab->lfebap;

    }

    else {

        start = 0;

        end = ab->endmant[chnl];

        lowcomp = 0;

        fastleak = 0;

        slowleak = 0;

        fgain = fgaintab[ab->fgaincod[chnl]];

        snroffset = (((ab->csnroffst - 15) << 4) + ab->fsnroffst[chnl]) << 2;

        exps = ab->dexps[chnl];

        baps = ab->bap[chnl];

        if (ab->deltbae[chnl] == AC3_DBASTR_NEW || ab->deltbae[chnl] == AC3_DBASTR_REUSE) {

            do_delta = 1;

            deltnseg = ab->deltnseg[chnl];

            deltoffst = ab->deltoffst[chnl];

            deltlen = ab->deltlen[chnl];

            deltba = ab->deltba[chnl];

        }

    }



    for (bin = start; bin < end; bin++) /* exponent mapping into psd */

        psd[bin] = (3072 - ((int)(exps[bin]) << 7));



    /* psd integration */

    j = start;

    k = masktab[start];

    do {

        lastbin = FFMIN(bndtab[k] + bndsz[k], end);

        bndpsd[k] = psd[j];

        j++;

        for (i = j; i < lastbin; i++) {

            bndpsd[k] = logadd(bndpsd[k], psd[j]);

            j++;

        }

        k++;

    } while (end > lastbin);



    /* compute the excite function */

    bndstrt = masktab[start];

    bndend = masktab[end - 1] + 1;

    if (bndstrt == 0) {

        lowcomp = calc_lowcomp(lowcomp, bndpsd[0], bndpsd[1], 0);

        excite[0] = bndpsd[0] - fgain - lowcomp;

        lowcomp = calc_lowcomp(lowcomp, bndpsd[1], bndpsd[2], 1);

        excite[1] = bndpsd[1] - fgain - lowcomp;

        begin = 7;

        for (bin = 2; bin < 7; bin++) {

            if (bndend != 7 || bin != 6)

                lowcomp = calc_lowcomp(lowcomp, bndpsd[bin], bndpsd[bin + 1], bin);

            fastleak = bndpsd[bin] - fgain;

            slowleak = bndpsd[bin] - sgain;

            excite[bin] = fastleak - lowcomp;

            if (bndend != 7 || bin != 6)

                if (bndpsd[bin] <= bndpsd[bin + 1]) {

                    begin = bin + 1;

                    break;

                }

        }

        for (bin = begin; bin < FFMIN(bndend, 22); bin++) {

            if (bndend != 7 || bin != 6)

                lowcomp = calc_lowcomp(lowcomp, bndpsd[bin], bndpsd[bin + 1], bin);

            fastleak -= fdecay;

            fastleak = FFMAX(fastleak, bndpsd[bin] - fgain);

            slowleak -= sdecay;

            slowleak = FFMAX(slowleak, bndpsd[bin] - sgain);

            excite[bin] = FFMAX(fastleak - lowcomp, slowleak);

        }

        begin = 22;

    }

    else {

        begin = bndstrt;

    }

    for (bin = begin; bin < bndend; bin++) {

        fastleak -= fdecay;

        fastleak = FFMAX(fastleak, bndpsd[bin] - fgain);

        slowleak -= sdecay;

        slowleak = FFMAX(slowleak, bndpsd[bin] - sgain);

        excite[bin] = FFMAX(fastleak, slowleak);

    }



    /* compute the masking curve */

    for (bin = bndstrt; bin < bndend; bin++) {

        if (bndpsd[bin] < dbknee)

            excite[bin] += ((dbknee - bndpsd[bin]) >> 2);

        mask[bin] = FFMAX(excite[bin], hth[bin][fscod]);

    }



    /* apply the delta bit allocation */

    if (do_delta) {

        band = 0;

        for (seg = 0; seg < deltnseg + 1; seg++) {

            band += (int)(deltoffst[seg]);

            if ((int)(deltba[seg]) >= 4)

                delta = ((int)(deltba[seg]) - 3) << 7;

            else

                delta = ((int)(deltba[seg]) - 4) << 7;

            for (k = 0; k < (int)(deltlen[seg]); k++) {

                mask[band] += delta;

                band++;

            }

        }

    }



    /*compute the bit allocation */

    i = start;

    j = masktab[start];

    do {

        lastbin = FFMIN(bndtab[j] + bndsz[j], end);

        mask[j] -= snroffset;

        mask[j] -= floor;

        if (mask[j] < 0)

            mask[j] = 0;

        mask[j] &= 0x1fe0;

        mask[j] += floor;

        for (k = i; k < lastbin; k++) {

            address = (psd[i] - mask[j]) >> 5;

            address = FFMIN(63, FFMAX(0, address));

            baps[i] = baptab[address];

            i++;

        }

        j++;

    } while (end > lastbin);

}

static int add_shorts_metadata(int count, const char *name,

                               const char *sep, TiffContext *s)

{

    char *ap;

    int i;

    int16_t *sp;



    if (bytestream2_get_bytes_left(&s->gb) < count * sizeof(int16_t))

        return -1;



    sp = av_malloc(count * sizeof(int16_t));

    if (!sp)

        return AVERROR(ENOMEM);



    for (i = 0; i < count; i++)

        sp[i] = tget_short(&s->gb, s->le);

    ap = shorts2str(sp, count, sep);

    av_freep(&sp);

    if (!ap)

        return AVERROR(ENOMEM);

    av_dict_set(&s->picture.metadata, name, ap, AV_DICT_DONT_STRDUP_VAL);

    return 0;

}

int av_open_input_file(AVFormatContext **ic_ptr, const char *filename,

                       AVInputFormat *fmt,

                       int buf_size,

                       AVFormatParameters *ap)

{

    int err;

    AVProbeData probe_data, *pd = &probe_data;

    ByteIOContext *pb = NULL;

    void *logctx= ap && ap->prealloced_context ? *ic_ptr : NULL;



    pd->filename = "";

    if (filename)

        pd->filename = filename;

    pd->buf = NULL;

    pd->buf_size = 0;



    if (!fmt) {

        /* guess format if no file can be opened */

        fmt = av_probe_input_format(pd, 0);

    }



    /* Do not open file if the format does not need it. XXX: specific

       hack needed to handle RTSP/TCP */

    if (!fmt || !(fmt->flags & AVFMT_NOFILE)) {

        /* if no file needed do not try to open one */

        if ((err=url_fopen(&pb, filename, URL_RDONLY)) < 0) {

            goto fail;

        }

        if (buf_size > 0) {

            url_setbufsize(pb, buf_size);

        }

        if ((err = ff_probe_input_buffer(&pb, &fmt, filename, logctx, 0, 0)) < 0) {

            goto fail;

        }

    }



    /* if still no format found, error */

    if (!fmt) {

        err = AVERROR_NOFMT;

        goto fail;

    }



    /* check filename in case an image number is expected */

    if (fmt->flags & AVFMT_NEEDNUMBER) {

        if (!av_filename_number_test(filename)) {

            err = AVERROR_NUMEXPECTED;

            goto fail;

        }

    }

    err = av_open_input_stream(ic_ptr, pb, filename, fmt, ap);

    if (err)

        goto fail;

    return 0;

 fail:

    av_freep(&pd->buf);

    if (pb)

        url_fclose(pb);

    if (ap && ap->prealloced_context)

        av_free(*ic_ptr);

    *ic_ptr = NULL;

    return err;



}

static int amr_probe(AVProbeData *p)

{

