        return AVPROBE_SCORE_MAX;

    else

        return 0;

}

static rwpipe *rwpipe_open( int argc, char *argv[] )

{

    rwpipe *this = av_mallocz( sizeof( rwpipe ) );



    if ( this != NULL )

    {

        int input[ 2 ];

        int output[ 2 ];



        pipe( input );

        pipe( output );



        this->pid = fork();



        if ( this->pid == 0 )

        {

#define COMMAND_SIZE 10240

            char *command = av_mallocz( COMMAND_SIZE );

            int i;



            strcpy( command, "" );

            for ( i = 0; i < argc; i ++ )

            {

                av_strlcat( command, argv[ i ], COMMAND_SIZE );

                av_strlcat( command, " ", COMMAND_SIZE );

            }



            dup2( output[ 0 ], STDIN_FILENO );

            dup2( input[ 1 ], STDOUT_FILENO );



            close( input[ 0 ] );

            close( input[ 1 ] );

            close( output[ 0 ] );

            close( output[ 1 ] );



            execl("/bin/sh", "sh", "-c", command, (char*)NULL );

            _exit( 255 );

        }

        else

        {

            close( input[ 1 ] );

            close( output[ 0 ] );



            this->reader = fdopen( input[ 0 ], "r" );

            this->writer = fdopen( output[ 1 ], "w" );

        }

    }



    return this;

}

static int validate_codec_tag(AVFormatContext *s, AVStream *st)

{

    const AVCodecTag *avctag;

    int n;

    enum AVCodecID id = AV_CODEC_ID_NONE;

    unsigned int tag  = 0;



    /**

     * Check that tag + id is in the table

     * If neither is in the table -> OK

     * If tag is in the table with another id -> FAIL

     * If id is in the table with another tag -> FAIL unless strict < normal

     */

    for (n = 0; s->oformat->codec_tag[n]; n++) {

        avctag = s->oformat->codec_tag[n];

        while (avctag->id != AV_CODEC_ID_NONE) {

            if (avpriv_toupper4(avctag->tag) == avpriv_toupper4(st->codec->codec_tag)) {

                id = avctag->id;

                if (id == st->codec->codec_id)

                    return 1;

            }

            if (avctag->id == st->codec->codec_id)

                tag = avctag->tag;

            avctag++;

        }

    }

    if (id != AV_CODEC_ID_NONE)

        return 0;

    if (tag && (st->codec->strict_std_compliance >= FF_COMPLIANCE_NORMAL))

        return 0;

    return 1;

}

