static void end_frame(AVFilterLink *inlink)

{

    TransContext *trans = inlink->dst->priv;

    AVFilterBufferRef *inpic  = inlink->cur_buf;

    AVFilterBufferRef *outpic = inlink->dst->outputs[0]->out_buf;

    AVFilterLink *outlink = inlink->dst->outputs[0];

    int plane;



    for (plane = 0; outpic->data[plane]; plane++) {

        int hsub = plane == 1 || plane == 2 ? trans->hsub : 0;

        int vsub = plane == 1 || plane == 2 ? trans->vsub : 0;

        int pixstep = trans->pixsteps[plane];

        int inh  = inpic->video->h>>vsub;

        int outw = outpic->video->w>>hsub;

        int outh = outpic->video->h>>vsub;

        uint8_t *out, *in;

        int outlinesize, inlinesize;

        int x, y;



        out = outpic->data[plane]; outlinesize = outpic->linesize[plane];

        in  = inpic ->data[plane]; inlinesize  = inpic ->linesize[plane];



        if (trans->dir&1) {

            in +=  inpic->linesize[plane] * (inh-1);

            inlinesize *= -1;

        }



        if (trans->dir&2) {

            out += outpic->linesize[plane] * (outh-1);

            outlinesize *= -1;

        }



        for (y = 0; y < outh; y++) {

            switch (pixstep) {

            case 1:

                for (x = 0; x < outw; x++)

                    out[x] = in[x*inlinesize + y];

                break;

            case 2:

                for (x = 0; x < outw; x++)

                    *((uint16_t *)(out + 2*x)) = *((uint16_t *)(in + x*inlinesize + y*2));

                break;

            case 3:

                for (x = 0; x < outw; x++) {

                    int32_t v = AV_RB24(in + x*inlinesize + y*3);

                    AV_WB24(out + 3*x, v);

                }

                break;

            case 4:

                for (x = 0; x < outw; x++)

                    *((uint32_t *)(out + 4*x)) = *((uint32_t *)(in + x*inlinesize + y*4));

                break;

            }

            out += outlinesize;

        }

    }



    avfilter_unref_buffer(inpic);

    ff_draw_slice(outlink, 0, outpic->video->h, 1);

    ff_end_frame(outlink);

    avfilter_unref_buffer(outpic);

}

static void unpack_alpha(GetBitContext *gb, uint16_t *dst, int num_coeffs,

                         const int num_bits)

{

    const int mask = (1 << num_bits) - 1;

    int i, idx, val, alpha_val;



    idx       = 0;

    alpha_val = mask;

    do {

        do {

            if (get_bits1(gb))

                val = get_bits(gb, num_bits);

            else {

                int sign;

                val  = get_bits(gb, num_bits == 16 ? 7 : 4);

                sign = val & 1;

                val  = (val + 2) >> 1;

                if (sign)

                    val = -val;

            }

            alpha_val = (alpha_val + val) & mask;

            if (num_bits == 16)

                dst[idx++] = alpha_val >> 6;

            else

                dst[idx++] = (alpha_val << 2) | (alpha_val >> 6);

            if (idx == num_coeffs - 1)

                break;

        } while (get_bits1(gb));

        val = get_bits(gb, 4);

        if (!val)

            val = get_bits(gb, 11);

        if (idx + val > num_coeffs)

            val = num_coeffs - idx;

        if (num_bits == 16)

            for (i = 0; i < val; i++)

                dst[idx++] = alpha_val >> 6;

        else

            for (i = 0; i < val; i++)

                dst[idx++] = (alpha_val << 2) | (alpha_val >> 6);

    } while (idx < num_coeffs);

}

static void mdct512(AC3MDCTContext *mdct, int32_t *out, int16_t *in)

{

    int i, re, im, n, n2, n4;

    int16_t *rot = mdct->rot_tmp;

    IComplex *x  = mdct->cplx_tmp;



    n  = 1 << mdct->nbits;

    n2 = n >> 1;

    n4 = n >> 2;



    /* shift to simplify computations */

    for (i = 0; i <n4; i++)

        rot[i] = -in[i + 3*n4];

    memcpy(&rot[n4], &in[0], 3*n4*sizeof(*in));



    /* pre rotation */

    for (i = 0; i < n4; i++) {

        re =  ((int)rot[   2*i] - (int)rot[ n-1-2*i]) >> 1;

        im = -((int)rot[n2+2*i] - (int)rot[n2-1-2*i]) >> 1;

        CMUL(x[i].re, x[i].im, re, im, -mdct->xcos1[i], mdct->xsin1[i]);

    }



    fft(mdct, x, mdct->nbits - 2);



    /* post rotation */

    for (i = 0; i < n4; i++) {

        re = x[i].re;

        im = x[i].im;

        CMUL(out[n2-1-2*i], out[2*i], re, im, mdct->xsin1[i], mdct->xcos1[i]);

    }

}

