int ff_init_buffer_info(AVCodecContext *avctx, AVFrame *frame)

{

    if (avctx->internal->pkt) {

        frame->pkt_pts = avctx->internal->pkt->pts;

        av_frame_set_pkt_pos     (frame, avctx->internal->pkt->pos);

        av_frame_set_pkt_duration(frame, avctx->internal->pkt->duration);

        av_frame_set_pkt_size    (frame, avctx->internal->pkt->size);

    } else {

        frame->pkt_pts = AV_NOPTS_VALUE;

        av_frame_set_pkt_pos     (frame, -1);

        av_frame_set_pkt_duration(frame, 0);

        av_frame_set_pkt_size    (frame, -1);

    }

    frame->reordered_opaque = avctx->reordered_opaque;



    switch (avctx->codec->type) {

    case AVMEDIA_TYPE_VIDEO:

        if (frame->format < 0)

            frame->format              = avctx->pix_fmt;

        if (!frame->sample_aspect_ratio.num)

            frame->sample_aspect_ratio = avctx->sample_aspect_ratio;

        if (av_frame_get_colorspace(frame) == AVCOL_SPC_UNSPECIFIED)

            av_frame_set_colorspace(frame, avctx->colorspace);

        if (av_frame_get_color_range(frame) == AVCOL_RANGE_UNSPECIFIED)

            av_frame_set_color_range(frame, avctx->color_range);

        break;

    case AVMEDIA_TYPE_AUDIO:

        if (!frame->sample_rate)

            frame->sample_rate    = avctx->sample_rate;

        if (frame->format < 0)

            frame->format         = avctx->sample_fmt;

        if (!frame->channel_layout) {

            if (avctx->channel_layout) {

                 if (av_get_channel_layout_nb_channels(avctx->channel_layout) !=

                     avctx->channels) {

                     av_log(avctx, AV_LOG_ERROR, "Inconsistent channel "

                            "configuration.\n");

                     return AVERROR(EINVAL);

                 }



                frame->channel_layout = avctx->channel_layout;

            } else {

                if (avctx->channels > FF_SANE_NB_CHANNELS) {

                    av_log(avctx, AV_LOG_ERROR, "Too many channels: %d.\n",

                           avctx->channels);

                    return AVERROR(ENOSYS);

                }

            }

        }

        av_frame_set_channels(frame, avctx->channels);

        break;

    }

    return 0;

}

AVFilterContext *avfilter_open(AVFilter *filter, char *inst_name)

{

    AVFilterContext *ret = av_malloc(sizeof(AVFilterContext));



    ret->av_class = av_mallocz(sizeof(AVClass));

    ret->av_class->item_name = filter_name;

    ret->filter   = filter;

    ret->name     = inst_name ? av_strdup(inst_name) : NULL;

    ret->priv     = av_mallocz(filter->priv_size);



    ret->input_count  = pad_count(filter->inputs);

    ret->input_pads   = av_malloc(sizeof(AVFilterPad) * ret->input_count);

    memcpy(ret->input_pads, filter->inputs, sizeof(AVFilterPad)*ret->input_count);

    ret->inputs       = av_mallocz(sizeof(AVFilterLink*) * ret->input_count);



    ret->output_count = pad_count(filter->outputs);

    ret->output_pads  = av_malloc(sizeof(AVFilterPad) * ret->output_count);

    memcpy(ret->output_pads, filter->outputs, sizeof(AVFilterPad)*ret->output_count);

    ret->outputs      = av_mallocz(sizeof(AVFilterLink*) * ret->output_count);



    return ret;

}

static void fic_draw_cursor(AVCodecContext *avctx, int cur_x, int cur_y)

{

    FICContext *ctx = avctx->priv_data;

    uint8_t *ptr    = ctx->cursor_buf;

    uint8_t *dstptr[3];

    uint8_t planes[4][1024];

    uint8_t chroma[3][256];

    int i, j, p;



    /* Convert to YUVA444. */

    for (i = 0; i < 1024; i++) {

        planes[0][i] = av_clip_uint8((( 25 * ptr[0] + 129 * ptr[1] +  66 * ptr[2]) / 255) + 16);

        planes[1][i] = av_clip_uint8(((-38 * ptr[0] + 112 * ptr[1] + -74 * ptr[2]) / 255) + 128);

        planes[2][i] = av_clip_uint8(((-18 * ptr[0] + 112 * ptr[1] + -94 * ptr[2]) / 255) + 128);

        planes[3][i] = ptr[3];



        ptr += 4;

    }



    /* Subsample chroma. */

    for (i = 0; i < 32; i += 2)

        for (j = 0; j < 32; j += 2)

            for (p = 0; p < 3; p++)

                chroma[p][16 * (i / 2) + j / 2] = (planes[p + 1][32 *  i      + j    ] +

                                                   planes[p + 1][32 *  i      + j + 1] +

                                                   planes[p + 1][32 * (i + 1) + j    ] +

                                                   planes[p + 1][32 * (i + 1) + j + 1]) / 4;



    /* Seek to x/y pos of cursor. */

    for (i = 0; i < 3; i++)

        dstptr[i] = ctx->final_frame->data[i]                        +

                    (ctx->final_frame->linesize[i] * (cur_y >> !!i)) +

                    (cur_x >> !!i) + !!i;



    /* Copy. */

    for (i = 0; i < FFMIN(32, avctx->height - cur_y) - 1; i += 2) {

        int lsize = FFMIN(32, avctx->width - cur_x);

        int csize = lsize / 2;



        fic_alpha_blend(dstptr[0],

                        planes[0] + i * 32, lsize, planes[3] + i * 32);

        fic_alpha_blend(dstptr[0] + ctx->final_frame->linesize[0],

                        planes[0] + (i + 1) * 32, lsize, planes[3] + (i + 1) * 32);

        fic_alpha_blend(dstptr[1],

                        chroma[0] + (i / 2) * 16, csize, chroma[2] + (i / 2) * 16);

        fic_alpha_blend(dstptr[2],

                        chroma[1] + (i / 2) * 16, csize, chroma[2] + (i / 2) * 16);



        dstptr[0] += ctx->final_frame->linesize[0] * 2;

        dstptr[1] += ctx->final_frame->linesize[1];

        dstptr[2] += ctx->final_frame->linesize[2];

    }

}

static int decode_ref_pic_list_reordering(H264Context *h){

    MpegEncContext * const s = &h->s;

    int list, index;



    print_short_term(h);

    print_long_term(h);

    if(h->slice_type==I_TYPE || h->slice_type==SI_TYPE) return 0; //FIXME move before func



    for(list=0; list<2; list++){

        memcpy(h->ref_list[list], h->default_ref_list[list], sizeof(Picture)*h->ref_count[list]);



        if(get_bits1(&s->gb)){

            int pred= h->curr_pic_num;



            for(index=0; ; index++){

                int reordering_of_pic_nums_idc= get_ue_golomb(&s->gb);

                int pic_id;

                int i;

                Picture *ref = NULL;



                if(reordering_of_pic_nums_idc==3)

                    break;



                if(index >= h->ref_count[list]){

                    av_log(h->s.avctx, AV_LOG_ERROR, "reference count overflow\n");

                    return -1;

                }



                if(reordering_of_pic_nums_idc<3){

                    if(reordering_of_pic_nums_idc<2){

                        const int abs_diff_pic_num= get_ue_golomb(&s->gb) + 1;



                        if(abs_diff_pic_num >= h->max_pic_num){

                            av_log(h->s.avctx, AV_LOG_ERROR, "abs_diff_pic_num overflow\n");

                            return -1;

                        }



                        if(reordering_of_pic_nums_idc == 0) pred-= abs_diff_pic_num;

                        else                                pred+= abs_diff_pic_num;

                        pred &= h->max_pic_num - 1;



                        for(i= h->short_ref_count-1; i>=0; i--){

                            ref = h->short_ref[i];

                            assert(ref->reference == 3);

                            assert(!ref->long_ref);

                            if(ref->data[0] != NULL && ref->frame_num == pred && ref->long_ref == 0) // ignore non existing pictures by testing data[0] pointer

                                break;

                        }

                        if(i>=0)

                            ref->pic_id= ref->frame_num;

                    }else{

                        pic_id= get_ue_golomb(&s->gb); //long_term_pic_idx

                        ref = h->long_ref[pic_id];

                        if(ref){

                            ref->pic_id= pic_id;

                            assert(ref->reference == 3);

                            assert(ref->long_ref);

                            i=0;

                        }else{

                            i=-1;

                        }

                    }



                    if (i < 0) {

                        av_log(h->s.avctx, AV_LOG_ERROR, "reference picture missing during reorder\n");

                        memset(&h->ref_list[list][index], 0, sizeof(Picture)); //FIXME

                    } else {

                        for(i=index; i+1<h->ref_count[list]; i++){

                            if(ref->long_ref == h->ref_list[list][i].long_ref && ref->pic_id == h->ref_list[list][i].pic_id)

                                break;

                        }

                        for(; i > index; i--){

                            h->ref_list[list][i]= h->ref_list[list][i-1];

                        }

                        h->ref_list[list][index]= *ref;

                    }

                }else{

                    av_log(h->s.avctx, AV_LOG_ERROR, "illegal reordering_of_pic_nums_idc\n");

                    return -1;

                }

            }

        }



        if(h->slice_type!=B_TYPE) break;

    }

    for(list=0; list<2; list++){

        for(index= 0; index < h->ref_count[list]; index++){

            if(!h->ref_list[list][index].data[0])

                h->ref_list[list][index]= s->current_picture;

        }

        if(h->slice_type!=B_TYPE) break;

    }



    if(h->slice_type==B_TYPE && !h->direct_spatial_mv_pred)

        direct_dist_scale_factor(h);

    direct_ref_list_init(h);

    return 0;

}

void FUNCC(ff_h264_idct8_dc_add)(uint8_t *_dst, DCTELEM *block, int stride){

    int i, j;

    int dc = (((dctcoef*)block)[0] + 32) >> 6;

    INIT_CLIP

    pixel *dst = (pixel*)_dst;

    stride /= sizeof(pixel);

    for( j = 0; j < 8; j++ )

    {

        for( i = 0; i < 8; i++ )

            dst[i] = CLIP( dst[i] + dc );

        dst += stride;

    }

}

static int svq3_decode_frame(AVCodecContext *avctx, void *data,

                             int *got_frame, AVPacket *avpkt)

{

    const uint8_t *buf = avpkt->data;

    SVQ3Context *svq3  = avctx->priv_data;

    H264Context *h     = &svq3->h;

    MpegEncContext *s  = &h->s;

    int buf_size       = avpkt->size;

    int m, mb_type;



    /* special case for last picture */

    if (buf_size == 0) {

        if (s->next_picture_ptr && !s->low_delay) {

            *(AVFrame *) data   = s->next_picture.f;

            s->next_picture_ptr = NULL;

            *got_frame          = 1;

        }

        return 0;

    }



    init_get_bits(&s->gb, buf, 8 * buf_size);



    s->mb_x = s->mb_y = h->mb_xy = 0;



    if (svq3_decode_slice_header(avctx))

        return -1;



    s->pict_type      = h->slice_type;

    s->picture_number = h->slice_num;



    if (avctx->debug & FF_DEBUG_PICT_INFO)

        av_log(h->s.avctx, AV_LOG_DEBUG,

               "%c hpel:%d, tpel:%d aqp:%d qp:%d, slice_num:%02X\n",

               av_get_picture_type_char(s->pict_type),

               svq3->halfpel_flag, svq3->thirdpel_flag,

               s->adaptive_quant, s->qscale, h->slice_num);



    /* for skipping the frame */

    s->current_picture.f.pict_type = s->pict_type;

    s->current_picture.f.key_frame = (s->pict_type == AV_PICTURE_TYPE_I);



    /* Skip B-frames if we do not have reference frames. */

    if (s->last_picture_ptr == NULL && s->pict_type == AV_PICTURE_TYPE_B)

        return 0;

    if (avctx->skip_frame >= AVDISCARD_NONREF && s->pict_type == AV_PICTURE_TYPE_B ||

        avctx->skip_frame >= AVDISCARD_NONKEY && s->pict_type != AV_PICTURE_TYPE_I ||

        avctx->skip_frame >= AVDISCARD_ALL)

        return 0;



    if (s->next_p_frame_damaged) {

        if (s->pict_type == AV_PICTURE_TYPE_B)

            return 0;

        else

            s->next_p_frame_damaged = 0;

    }



    if (ff_h264_frame_start(h) < 0)

        return -1;



    if (s->pict_type == AV_PICTURE_TYPE_B) {

        h->frame_num_offset = h->slice_num - h->prev_frame_num;



        if (h->frame_num_offset < 0)

            h->frame_num_offset += 256;

        if (h->frame_num_offset == 0 ||

            h->frame_num_offset >= h->prev_frame_num_offset) {

            av_log(h->s.avctx, AV_LOG_ERROR, "error in B-frame picture id\n");

            return -1;

        }

    } else {

        h->prev_frame_num        = h->frame_num;

        h->frame_num             = h->slice_num;

        h->prev_frame_num_offset = h->frame_num - h->prev_frame_num;



        if (h->prev_frame_num_offset < 0)

            h->prev_frame_num_offset += 256;

    }



    for (m = 0; m < 2; m++) {

        int i;

        for (i = 0; i < 4; i++) {

            int j;

            for (j = -1; j < 4; j++)

                h->ref_cache[m][scan8[0] + 8 * i + j] = 1;

            if (i < 3)

                h->ref_cache[m][scan8[0] + 8 * i + j] = PART_NOT_AVAILABLE;

        }

    }



    for (s->mb_y = 0; s->mb_y < s->mb_height; s->mb_y++) {

        for (s->mb_x = 0; s->mb_x < s->mb_width; s->mb_x++) {

            h->mb_xy = s->mb_x + s->mb_y * s->mb_stride;



            if ((get_bits_count(&s->gb) + 7) >= s->gb.size_in_bits &&

                ((get_bits_count(&s->gb) & 7) == 0 ||

                 show_bits(&s->gb, -get_bits_count(&s->gb) & 7) == 0)) {

                skip_bits(&s->gb, svq3->next_slice_index - get_bits_count(&s->gb));

                s->gb.size_in_bits = 8 * buf_size;



                if (svq3_decode_slice_header(avctx))

                    return -1;



                /* TODO: support s->mb_skip_run */

            }



            mb_type = svq3_get_ue_golomb(&s->gb);



            if (s->pict_type == AV_PICTURE_TYPE_I)

                mb_type += 8;

            else if (s->pict_type == AV_PICTURE_TYPE_B && mb_type >= 4)

                mb_type += 4;

            if ((unsigned)mb_type > 33 || svq3_decode_mb(svq3, mb_type)) {

                av_log(h->s.avctx, AV_LOG_ERROR,

                       "error while decoding MB %d %d\n", s->mb_x, s->mb_y);

                return -1;

            }



            if (mb_type != 0)

                ff_h264_hl_decode_mb(h);



            if (s->pict_type != AV_PICTURE_TYPE_B && !s->low_delay)

                s->current_picture.f.mb_type[s->mb_x + s->mb_y * s->mb_stride] =

                    (s->pict_type == AV_PICTURE_TYPE_P && mb_type < 8) ? (mb_type - 1) : -1;

        }



        ff_draw_horiz_band(s, 16 * s->mb_y, 16);

    }



    ff_MPV_frame_end(s);



    if (s->pict_type == AV_PICTURE_TYPE_B || s->low_delay)

        *(AVFrame *)data = s->current_picture.f;

    else

        *(AVFrame *)data = s->last_picture.f;



    /* Do not output the last pic after seeking. */

    if (s->last_picture_ptr || s->low_delay)

        *got_frame = 1;



    return buf_size;

}

static void mpeg4_decode_sprite_trajectory(MpegEncContext * s, GetBitContext *gb)

{

    int i;

    int a= 2<<s->sprite_warping_accuracy;

    int rho= 3-s->sprite_warping_accuracy;

    int r=16/a;

    const int vop_ref[4][2]= {{0,0}, {s->width,0}, {0, s->height}, {s->width, s->height}}; // only true for rectangle shapes

    int d[4][2]={{0,0}, {0,0}, {0,0}, {0,0}};

    int sprite_ref[4][2];

    int virtual_ref[2][2];

    int w2, h2, w3, h3;

    int alpha=0, beta=0;

    int w= s->width;

    int h= s->height;

    int min_ab;



    for(i=0; i<s->num_sprite_warping_points; i++){

        int length;

        int x=0, y=0;



        length= get_vlc2(gb, sprite_trajectory.table, SPRITE_TRAJ_VLC_BITS, 3);

        if(length){

            x= get_xbits(gb, length);

        }

        if(!(s->divx_version==500 && s->divx_build==413)) skip_bits1(gb); /* marker bit */



        length= get_vlc2(gb, sprite_trajectory.table, SPRITE_TRAJ_VLC_BITS, 3);

        if(length){

            y=get_xbits(gb, length);

        }

        skip_bits1(gb); /* marker bit */

        s->sprite_traj[i][0]= d[i][0]= x;

        s->sprite_traj[i][1]= d[i][1]= y;

    }

    for(; i<4; i++)

        s->sprite_traj[i][0]= s->sprite_traj[i][1]= 0;



    while((1<<alpha)<w) alpha++;

    while((1<<beta )<h) beta++; // there seems to be a typo in the mpeg4 std for the definition of w' and h'

    w2= 1<<alpha;

    h2= 1<<beta;



// Note, the 4th point isn't used for GMC

    if(s->divx_version==500 && s->divx_build==413){

        sprite_ref[0][0]= a*vop_ref[0][0] + d[0][0];

        sprite_ref[0][1]= a*vop_ref[0][1] + d[0][1];

        sprite_ref[1][0]= a*vop_ref[1][0] + d[0][0] + d[1][0];

        sprite_ref[1][1]= a*vop_ref[1][1] + d[0][1] + d[1][1];

        sprite_ref[2][0]= a*vop_ref[2][0] + d[0][0] + d[2][0];

        sprite_ref[2][1]= a*vop_ref[2][1] + d[0][1] + d[2][1];

    } else {

        sprite_ref[0][0]= (a>>1)*(2*vop_ref[0][0] + d[0][0]);

        sprite_ref[0][1]= (a>>1)*(2*vop_ref[0][1] + d[0][1]);

        sprite_ref[1][0]= (a>>1)*(2*vop_ref[1][0] + d[0][0] + d[1][0]);

        sprite_ref[1][1]= (a>>1)*(2*vop_ref[1][1] + d[0][1] + d[1][1]);

        sprite_ref[2][0]= (a>>1)*(2*vop_ref[2][0] + d[0][0] + d[2][0]);

        sprite_ref[2][1]= (a>>1)*(2*vop_ref[2][1] + d[0][1] + d[2][1]);

    }

/*    sprite_ref[3][0]= (a>>1)*(2*vop_ref[3][0] + d[0][0] + d[1][0] + d[2][0] + d[3][0]);

    sprite_ref[3][1]= (a>>1)*(2*vop_ref[3][1] + d[0][1] + d[1][1] + d[2][1] + d[3][1]); */



// this is mostly identical to the mpeg4 std (and is totally unreadable because of that ...)

// perhaps it should be reordered to be more readable ...

// the idea behind this virtual_ref mess is to be able to use shifts later per pixel instead of divides

// so the distance between points is converted from w&h based to w2&h2 based which are of the 2^x form

    virtual_ref[0][0]= 16*(vop_ref[0][0] + w2)

        + ROUNDED_DIV(((w - w2)*(r*sprite_ref[0][0] - 16*vop_ref[0][0]) + w2*(r*sprite_ref[1][0] - 16*vop_ref[1][0])),w);

    virtual_ref[0][1]= 16*vop_ref[0][1]

        + ROUNDED_DIV(((w - w2)*(r*sprite_ref[0][1] - 16*vop_ref[0][1]) + w2*(r*sprite_ref[1][1] - 16*vop_ref[1][1])),w);

    virtual_ref[1][0]= 16*vop_ref[0][0]

        + ROUNDED_DIV(((h - h2)*(r*sprite_ref[0][0] - 16*vop_ref[0][0]) + h2*(r*sprite_ref[2][0] - 16*vop_ref[2][0])),h);

    virtual_ref[1][1]= 16*(vop_ref[0][1] + h2)

        + ROUNDED_DIV(((h - h2)*(r*sprite_ref[0][1] - 16*vop_ref[0][1]) + h2*(r*sprite_ref[2][1] - 16*vop_ref[2][1])),h);



    switch(s->num_sprite_warping_points)

    {

        case 0:

            s->sprite_offset[0][0]= 0;

            s->sprite_offset[0][1]= 0;

            s->sprite_offset[1][0]= 0;

            s->sprite_offset[1][1]= 0;

            s->sprite_delta[0][0]= a;

            s->sprite_delta[0][1]= 0;

            s->sprite_delta[1][0]= 0;

            s->sprite_delta[1][1]= a;

            s->sprite_shift[0]= 0;

            s->sprite_shift[1]= 0;

            break;

        case 1: //GMC only

            s->sprite_offset[0][0]= sprite_ref[0][0] - a*vop_ref[0][0];

            s->sprite_offset[0][1]= sprite_ref[0][1] - a*vop_ref[0][1];

            s->sprite_offset[1][0]= ((sprite_ref[0][0]>>1)|(sprite_ref[0][0]&1)) - a*(vop_ref[0][0]/2);

            s->sprite_offset[1][1]= ((sprite_ref[0][1]>>1)|(sprite_ref[0][1]&1)) - a*(vop_ref[0][1]/2);

            s->sprite_delta[0][0]= a;

            s->sprite_delta[0][1]= 0;

            s->sprite_delta[1][0]= 0;

            s->sprite_delta[1][1]= a;

            s->sprite_shift[0]= 0;

            s->sprite_shift[1]= 0;

            break;

        case 2:

            s->sprite_offset[0][0]= (sprite_ref[0][0]<<(alpha+rho))

                                                  + (-r*sprite_ref[0][0] + virtual_ref[0][0])*(-vop_ref[0][0])

                                                  + ( r*sprite_ref[0][1] - virtual_ref[0][1])*(-vop_ref[0][1])

                                                  + (1<<(alpha+rho-1));

            s->sprite_offset[0][1]= (sprite_ref[0][1]<<(alpha+rho))

                                                  + (-r*sprite_ref[0][1] + virtual_ref[0][1])*(-vop_ref[0][0])

                                                  + (-r*sprite_ref[0][0] + virtual_ref[0][0])*(-vop_ref[0][1])

                                                  + (1<<(alpha+rho-1));

            s->sprite_offset[1][0]= ( (-r*sprite_ref[0][0] + virtual_ref[0][0])*(-2*vop_ref[0][0] + 1)

                                     +( r*sprite_ref[0][1] - virtual_ref[0][1])*(-2*vop_ref[0][1] + 1)

                                     +2*w2*r*sprite_ref[0][0]

                                     - 16*w2

                                     + (1<<(alpha+rho+1)));

            s->sprite_offset[1][1]= ( (-r*sprite_ref[0][1] + virtual_ref[0][1])*(-2*vop_ref[0][0] + 1)

                                     +(-r*sprite_ref[0][0] + virtual_ref[0][0])*(-2*vop_ref[0][1] + 1)

                                     +2*w2*r*sprite_ref[0][1]

                                     - 16*w2

                                     + (1<<(alpha+rho+1)));

            s->sprite_delta[0][0]=   (-r*sprite_ref[0][0] + virtual_ref[0][0]);

            s->sprite_delta[0][1]=   (+r*sprite_ref[0][1] - virtual_ref[0][1]);

            s->sprite_delta[1][0]=   (-r*sprite_ref[0][1] + virtual_ref[0][1]);

            s->sprite_delta[1][1]=   (-r*sprite_ref[0][0] + virtual_ref[0][0]);



            s->sprite_shift[0]= alpha+rho;

            s->sprite_shift[1]= alpha+rho+2;

            break;

        case 3:

            min_ab= FFMIN(alpha, beta);

            w3= w2>>min_ab;

            h3= h2>>min_ab;

            s->sprite_offset[0][0]=  (sprite_ref[0][0]<<(alpha+beta+rho-min_ab))

                                   + (-r*sprite_ref[0][0] + virtual_ref[0][0])*h3*(-vop_ref[0][0])

                                   + (-r*sprite_ref[0][0] + virtual_ref[1][0])*w3*(-vop_ref[0][1])

                                   + (1<<(alpha+beta+rho-min_ab-1));

            s->sprite_offset[0][1]=  (sprite_ref[0][1]<<(alpha+beta+rho-min_ab))

                                   + (-r*sprite_ref[0][1] + virtual_ref[0][1])*h3*(-vop_ref[0][0])

                                   + (-r*sprite_ref[0][1] + virtual_ref[1][1])*w3*(-vop_ref[0][1])

                                   + (1<<(alpha+beta+rho-min_ab-1));

            s->sprite_offset[1][0]=  (-r*sprite_ref[0][0] + virtual_ref[0][0])*h3*(-2*vop_ref[0][0] + 1)

                                   + (-r*sprite_ref[0][0] + virtual_ref[1][0])*w3*(-2*vop_ref[0][1] + 1)

                                   + 2*w2*h3*r*sprite_ref[0][0]

                                   - 16*w2*h3

                                   + (1<<(alpha+beta+rho-min_ab+1));

            s->sprite_offset[1][1]=  (-r*sprite_ref[0][1] + virtual_ref[0][1])*h3*(-2*vop_ref[0][0] + 1)

                                   + (-r*sprite_ref[0][1] + virtual_ref[1][1])*w3*(-2*vop_ref[0][1] + 1)

                                   + 2*w2*h3*r*sprite_ref[0][1]

                                   - 16*w2*h3

                                   + (1<<(alpha+beta+rho-min_ab+1));

            s->sprite_delta[0][0]=   (-r*sprite_ref[0][0] + virtual_ref[0][0])*h3;

            s->sprite_delta[0][1]=   (-r*sprite_ref[0][0] + virtual_ref[1][0])*w3;

            s->sprite_delta[1][0]=   (-r*sprite_ref[0][1] + virtual_ref[0][1])*h3;

            s->sprite_delta[1][1]=   (-r*sprite_ref[0][1] + virtual_ref[1][1])*w3;



            s->sprite_shift[0]= alpha + beta + rho - min_ab;

            s->sprite_shift[1]= alpha + beta + rho - min_ab + 2;

            break;

    }

    /* try to simplify the situation */

    if(   s->sprite_delta[0][0] == a<<s->sprite_shift[0]

       && s->sprite_delta[0][1] == 0

       && s->sprite_delta[1][0] == 0

       && s->sprite_delta[1][1] == a<<s->sprite_shift[0])

    {

        s->sprite_offset[0][0]>>=s->sprite_shift[0];

        s->sprite_offset[0][1]>>=s->sprite_shift[0];

        s->sprite_offset[1][0]>>=s->sprite_shift[1];

        s->sprite_offset[1][1]>>=s->sprite_shift[1];

        s->sprite_delta[0][0]= a;

        s->sprite_delta[0][1]= 0;

        s->sprite_delta[1][0]= 0;

        s->sprite_delta[1][1]= a;

        s->sprite_shift[0]= 0;

        s->sprite_shift[1]= 0;

        s->real_sprite_warping_points=1;

    }

    else{

        int shift_y= 16 - s->sprite_shift[0];

        int shift_c= 16 - s->sprite_shift[1];

        for(i=0; i<2; i++){

            s->sprite_offset[0][i]<<= shift_y;

            s->sprite_offset[1][i]<<= shift_c;

            s->sprite_delta[0][i]<<= shift_y;

            s->sprite_delta[1][i]<<= shift_y;

            s->sprite_shift[i]= 16;

        }

        s->real_sprite_warping_points= s->num_sprite_warping_points;

    }

}

static int parse(AVCodecParserContext *ctx,

                 AVCodecContext *avctx,

                 const uint8_t **out_data, int *out_size,

                 const uint8_t *data, int size)

{

    VP9ParseContext *s = ctx->priv_data;

    int full_size = size;

    int marker;



    if (size <= 0) {

        *out_size = 0;

        *out_data = data;



        return 0;

    }



    if (s->n_frames > 0) {

        *out_data = data;

        *out_size = s->size[--s->n_frames];

        parse_frame(ctx, *out_data, *out_size);



        return s->n_frames > 0 ? *out_size : size /* i.e. include idx tail */;

    }



    marker = data[size - 1];

    if ((marker & 0xe0) == 0xc0) {

        int nbytes = 1 + ((marker >> 3) & 0x3);

        int n_frames = 1 + (marker & 0x7), idx_sz = 2 + n_frames * nbytes;



        if (size >= idx_sz && data[size - idx_sz] == marker) {

            const uint8_t *idx = data + size + 1 - idx_sz;

            int first = 1;



            switch (nbytes) {

#define case_n(a, rd) \

            case a: \

                while (n_frames--) { \

                    unsigned sz = rd; \

                    idx += a; \

                    if (sz > size) { \

                        s->n_frames = 0; \

                        *out_size = size; \

                        *out_data = data; \

                        av_log(avctx, AV_LOG_ERROR, \

                               "Superframe packet size too big: %u > %d\n", \

                               sz, size); \

                        return full_size; \

                    } \

                    if (first) { \

                        first = 0; \

                        *out_data = data; \

                        *out_size = sz; \

                        s->n_frames = n_frames; \

                    } else { \

                        s->size[n_frames] = sz; \

                    } \

                    data += sz; \

                    size -= sz; \

                } \

                parse_frame(ctx, *out_data, *out_size); \

                return *out_size



                case_n(1, *idx);

                case_n(2, AV_RL16(idx));

                case_n(3, AV_RL24(idx));

                case_n(4, AV_RL32(idx));

            }

        }

    }



    *out_data = data;

    *out_size = size;

    parse_frame(ctx, data, size);



    return size;

}

static int mjpeg_decode_app(MJpegDecodeContext *s)

{

    int len, id, i;



    len = get_bits(&s->gb, 16);

    if (len < 6)

        return AVERROR_INVALIDDATA;

    if (8 * len > get_bits_left(&s->gb))

        return AVERROR_INVALIDDATA;



    id   = get_bits_long(&s->gb, 32);

    len -= 6;



    if (s->avctx->debug & FF_DEBUG_STARTCODE) {

        char id_str[32];

        av_get_codec_tag_string(id_str, sizeof(id_str), av_bswap32(id));

        av_log(s->avctx, AV_LOG_DEBUG, "APPx (%s / %8X) len=%d\n", id_str, id, len);

    }



    /* Buggy AVID, it puts EOI only at every 10th frame. */

    /* Also, this fourcc is used by non-avid files too, it holds some

       information, but it's always present in AVID-created files. */

    if (id == AV_RB32("AVI1")) {

        /* structure:

            4bytes      AVI1

            1bytes      polarity

            1bytes      always zero

            4bytes      field_size

            4bytes      field_size_less_padding

        */

            s->buggy_avid = 1;

        i = get_bits(&s->gb, 8); len--;

        av_log(s->avctx, AV_LOG_DEBUG, "polarity %d\n", i);

#if 0

        skip_bits(&s->gb, 8);

        skip_bits(&s->gb, 32);

        skip_bits(&s->gb, 32);

        len -= 10;

#endif


    }



//    len -= 2;



    if (id == AV_RB32("JFIF")) {

        int t_w, t_h, v1, v2;



        skip_bits(&s->gb, 8); /* the trailing zero-byte */

        v1 = get_bits(&s->gb, 8);

        v2 = get_bits(&s->gb, 8);

        skip_bits(&s->gb, 8);



        s->avctx->sample_aspect_ratio.num = get_bits(&s->gb, 16);

        s->avctx->sample_aspect_ratio.den = get_bits(&s->gb, 16);

        if (   s->avctx->sample_aspect_ratio.num <= 0

            || s->avctx->sample_aspect_ratio.den <= 0) {

            s->avctx->sample_aspect_ratio.num = 0;

            s->avctx->sample_aspect_ratio.den = 1;

        }



        if (s->avctx->debug & FF_DEBUG_PICT_INFO)

            av_log(s->avctx, AV_LOG_INFO,

                   "mjpeg: JFIF header found (version: %x.%x) SAR=%d/%d\n",

                   v1, v2,

                   s->avctx->sample_aspect_ratio.num,

                   s->avctx->sample_aspect_ratio.den);



        len -= 8;

        if (len >= 2) {

            t_w = get_bits(&s->gb, 8);

            t_h = get_bits(&s->gb, 8);

            if (t_w && t_h) {

                /* skip thumbnail */

                if (len -10 - (t_w * t_h * 3) > 0)

                    len -= t_w * t_h * 3;

            }

            len -= 2;

        }


    }



    if (   id == AV_RB32("Adob")

        && len >= 7

        && show_bits(&s->gb, 8) == 'e'

        && show_bits_long(&s->gb, 32) != AV_RB32("e_CM")) {

        skip_bits(&s->gb,  8); /* 'e' */

        skip_bits(&s->gb, 16); /* version */

        skip_bits(&s->gb, 16); /* flags0 */

        skip_bits(&s->gb, 16); /* flags1 */

        s->adobe_transform = get_bits(&s->gb,  8);

        if (s->avctx->debug & FF_DEBUG_PICT_INFO)

            av_log(s->avctx, AV_LOG_INFO, "mjpeg: Adobe header found, transform=%d\n", s->adobe_transform);

        len -= 7;


    }



    if (id == AV_RB32("LJIF")) {

        int rgb = s->rgb;

        int pegasus_rct = s->pegasus_rct;

        if (s->avctx->debug & FF_DEBUG_PICT_INFO)

            av_log(s->avctx, AV_LOG_INFO,

                   "Pegasus lossless jpeg header found\n");

        skip_bits(&s->gb, 16); /* version ? */

        skip_bits(&s->gb, 16); /* unknown always 0? */

        skip_bits(&s->gb, 16); /* unknown always 0? */

        skip_bits(&s->gb, 16); /* unknown always 0? */

        switch (i=get_bits(&s->gb, 8)) {

        case 1:

            rgb         = 1;

            pegasus_rct = 0;

            break;

        case 2:

            rgb         = 1;

            pegasus_rct = 1;

            break;

        default:

            av_log(s->avctx, AV_LOG_ERROR, "unknown colorspace %d\n", i);

        }



        len -= 9;

        if (s->got_picture)

            if (rgb != s->rgb || pegasus_rct != s->pegasus_rct) {

                av_log(s->avctx, AV_LOG_WARNING, "Mismatching LJIF tag\n");


            }



        s->rgb = rgb;

        s->pegasus_rct = pegasus_rct;




    }

    if (id == AV_RL32("colr") && len > 0) {

        s->colr = get_bits(&s->gb, 8);

        if (s->avctx->debug & FF_DEBUG_PICT_INFO)

            av_log(s->avctx, AV_LOG_INFO, "COLR %d\n", s->colr);

        len --;


    }

    if (id == AV_RL32("xfrm") && len > 0) {

        s->xfrm = get_bits(&s->gb, 8);

        if (s->avctx->debug & FF_DEBUG_PICT_INFO)

            av_log(s->avctx, AV_LOG_INFO, "XFRM %d\n", s->xfrm);

        len --;


    }



    /* JPS extension by VRex */

    if (s->start_code == APP3 && id == AV_RB32("_JPS") && len >= 10) {

        int flags, layout, type;

        if (s->avctx->debug & FF_DEBUG_PICT_INFO)

            av_log(s->avctx, AV_LOG_INFO, "_JPSJPS_\n");



        skip_bits(&s->gb, 32); len -= 4;  /* JPS_ */

        skip_bits(&s->gb, 16); len -= 2;  /* block length */

        skip_bits(&s->gb, 8);             /* reserved */

        flags  = get_bits(&s->gb, 8);

        layout = get_bits(&s->gb, 8);

        type   = get_bits(&s->gb, 8);

        len -= 4;



        s->stereo3d = av_stereo3d_alloc();

        if (!s->stereo3d) {


        }

        if (type == 0) {

            s->stereo3d->type = AV_STEREO3D_2D;

        } else if (type == 1) {

            switch (layout) {

            case 0x01:

                s->stereo3d->type = AV_STEREO3D_LINES;

                break;

            case 0x02:

                s->stereo3d->type = AV_STEREO3D_SIDEBYSIDE;

                break;

            case 0x03:

                s->stereo3d->type = AV_STEREO3D_TOPBOTTOM;

                break;

            }

            if (!(flags & 0x04)) {

                s->stereo3d->flags = AV_STEREO3D_FLAG_INVERT;

            }

        }


    }



    /* EXIF metadata */

    if (s->start_code == APP1 && id == AV_RB32("Exif") && len >= 2) {

        GetByteContext gbytes;

        int ret, le, ifd_offset, bytes_read;

        const uint8_t *aligned;



        skip_bits(&s->gb, 16); // skip padding

        len -= 2;



        // init byte wise reading

        aligned = align_get_bits(&s->gb);

        bytestream2_init(&gbytes, aligned, len);



        // read TIFF header

        ret = ff_tdecode_header(&gbytes, &le, &ifd_offset);

        if (ret) {

            av_log(s->avctx, AV_LOG_ERROR, "mjpeg: invalid TIFF header in EXIF data\n");

        } else {

            bytestream2_seek(&gbytes, ifd_offset, SEEK_SET);



            // read 0th IFD and store the metadata

            // (return values > 0 indicate the presence of subimage metadata)

            ret = avpriv_exif_decode_ifd(s->avctx, &gbytes, le, 0, &s->exif_metadata);

            if (ret < 0) {

                av_log(s->avctx, AV_LOG_ERROR, "mjpeg: error decoding EXIF data\n");

            }

        }



        bytes_read = bytestream2_tell(&gbytes);

        skip_bits(&s->gb, bytes_read << 3);

        len -= bytes_read;




    }



    /* Apple MJPEG-A */

    if ((s->start_code == APP1) && (len > (0x28 - 8))) {

        id   = get_bits_long(&s->gb, 32);

        len -= 4;

        /* Apple MJPEG-A */

        if (id == AV_RB32("mjpg")) {

#if 0

            skip_bits(&s->gb, 32); /* field size */

            skip_bits(&s->gb, 32); /* pad field size */

            skip_bits(&s->gb, 32); /* next off */

            skip_bits(&s->gb, 32); /* quant off */

            skip_bits(&s->gb, 32); /* huff off */

            skip_bits(&s->gb, 32); /* image off */

            skip_bits(&s->gb, 32); /* scan off */

            skip_bits(&s->gb, 32); /* data off */

#endif

            if (s->avctx->debug & FF_DEBUG_PICT_INFO)

                av_log(s->avctx, AV_LOG_INFO, "mjpeg: Apple MJPEG-A header found\n");

        }

    }



out:

    /* slow but needed for extreme adobe jpegs */

    if (len < 0)

        av_log(s->avctx, AV_LOG_ERROR,

               "mjpeg: error, decode_app parser read over the end\n");

    while (--len > 0)

        skip_bits(&s->gb, 8);



    return 0;

}

static int do_decode(AVCodecContext *avctx, AVPacket *pkt)

{

    int got_frame;

    int ret;



    av_assert0(!avctx->internal->buffer_frame->buf[0]);



    if (!pkt)

        pkt = avctx->internal->buffer_pkt;



    // This is the lesser evil. The field is for compatibility with legacy users

    // of the legacy API, and users using the new API should not be forced to

    // even know about this field.

    avctx->refcounted_frames = 1;



    // Some codecs (at least wma lossless) will crash when feeding drain packets

    // after EOF was signaled.

    if (avctx->internal->draining_done)

        return AVERROR_EOF;



    if (avctx->codec_type == AVMEDIA_TYPE_VIDEO) {

        ret = avcodec_decode_video2(avctx, avctx->internal->buffer_frame,

                                    &got_frame, pkt);

        if (ret >= 0 && !(avctx->flags & AV_CODEC_FLAG_TRUNCATED))

            ret = pkt->size;

    } else if (avctx->codec_type == AVMEDIA_TYPE_AUDIO) {

        ret = avcodec_decode_audio4(avctx, avctx->internal->buffer_frame,

                                    &got_frame, pkt);

    } else {

        ret = AVERROR(EINVAL);

    }



    if (ret == AVERROR(EAGAIN))

        ret = pkt->size;



    if (avctx->internal->draining && !got_frame)

        avctx->internal->draining_done = 1;



    if (ret < 0)

        return ret;



    if (ret >= pkt->size) {

        av_packet_unref(avctx->internal->buffer_pkt);

    } else {

        int consumed = ret;



        if (pkt != avctx->internal->buffer_pkt) {

            av_packet_unref(avctx->internal->buffer_pkt);

            if ((ret = av_packet_ref(avctx->internal->buffer_pkt, pkt)) < 0)

                return ret;

        }



        avctx->internal->buffer_pkt->data += consumed;

        avctx->internal->buffer_pkt->size -= consumed;

        avctx->internal->buffer_pkt->pts   = AV_NOPTS_VALUE;

        avctx->internal->buffer_pkt->dts   = AV_NOPTS_VALUE;

    }



    if (got_frame)

        av_assert0(avctx->internal->buffer_frame->buf[0]);



    return 0;

}

