    static int done = 0;



    if(!done){

        done = 1;

        init_vlc(&h261_mba_vlc, H261_MBA_VLC_BITS, 35,

                 h261_mba_bits, 1, 1,

                 h261_mba_code, 1, 1);

        init_vlc(&h261_mtype_vlc, H261_MTYPE_VLC_BITS, 10,

                 h261_mtype_bits, 1, 1,

                 h261_mtype_code, 1, 1);

        init_vlc(&h261_mv_vlc, H261_MV_VLC_BITS, 17,

                 &h261_mv_tab[0][1], 2, 1,

