        init_vlc(&h261_cbp_vlc, H261_CBP_VLC_BITS, 63,

                 &h261_cbp_tab[0][1], 2, 1,

                 &h261_cbp_tab[0][0], 2, 1);

        init_rl(&h261_rl_tcoeff);

        init_vlc_rl(&h261_rl_tcoeff);

    }

}

static int xan_wc3_decode_frame(XanContext *s) {



    int width = s->avctx->width;

    int height = s->avctx->height;

    int total_pixels = width * height;

    unsigned char opcode;

    unsigned char flag = 0;

    int size = 0;

    int motion_x, motion_y;

    int x, y;



    unsigned char *opcode_buffer = s->buffer1;

    unsigned char *opcode_buffer_end = s->buffer1 + s->buffer1_size;

    int opcode_buffer_size = s->buffer1_size;

    const unsigned char *imagedata_buffer = s->buffer2;



    /* pointers to segments inside the compressed chunk */

    const unsigned char *huffman_segment;

    const unsigned char *size_segment;

    const unsigned char *vector_segment;

    const unsigned char *imagedata_segment;

    int huffman_offset, size_offset, vector_offset, imagedata_offset, imagedata_size;



    if (s->size < 8)

        return AVERROR_INVALIDDATA;



    huffman_offset    = AV_RL16(&s->buf[0]);

    size_offset       = AV_RL16(&s->buf[2]);

    vector_offset     = AV_RL16(&s->buf[4]);

    imagedata_offset  = AV_RL16(&s->buf[6]);



    if (huffman_offset   >= s->size ||

        size_offset      >= s->size ||

        vector_offset    >= s->size ||

        imagedata_offset >= s->size)

        return AVERROR_INVALIDDATA;



    huffman_segment   = s->buf + huffman_offset;

    size_segment      = s->buf + size_offset;

    vector_segment    = s->buf + vector_offset;

    imagedata_segment = s->buf + imagedata_offset;



    if (xan_huffman_decode(opcode_buffer, opcode_buffer_size,

                           huffman_segment, s->size - huffman_offset) < 0)

        return AVERROR_INVALIDDATA;



    if (imagedata_segment[0] == 2) {

        xan_unpack(s->buffer2, &imagedata_segment[1], s->buffer2_size);

        imagedata_size = s->buffer2_size;

    } else {

        imagedata_size = s->size - imagedata_offset - 1;

        imagedata_buffer = &imagedata_segment[1];

    }



    /* use the decoded data segments to build the frame */

    x = y = 0;

    while (total_pixels && opcode_buffer < opcode_buffer_end) {



        opcode = *opcode_buffer++;

        size = 0;



        switch (opcode) {



        case 0:

            flag ^= 1;

            continue;



        case 1:

        case 2:

        case 3:

        case 4:

        case 5:

        case 6:

        case 7:

        case 8:

            size = opcode;

            break;



        case 12:

        case 13:

        case 14:

        case 15:

        case 16:

        case 17:

        case 18:

            size += (opcode - 10);

            break;



        case 9:

        case 19:

            size = *size_segment++;

            break;



        case 10:

        case 20:

            size = AV_RB16(&size_segment[0]);

            size_segment += 2;

            break;



        case 11:

        case 21:

            size = AV_RB24(size_segment);

            size_segment += 3;

            break;

        }

        if (size > total_pixels)

            break;



        if (opcode < 12) {

            flag ^= 1;

            if (flag) {

                /* run of (size) pixels is unchanged from last frame */

                xan_wc3_copy_pixel_run(s, x, y, size, 0, 0);

            } else {

                /* output a run of pixels from imagedata_buffer */

                if (imagedata_size < size)

                    break;

                xan_wc3_output_pixel_run(s, imagedata_buffer, x, y, size);

                imagedata_buffer += size;

                imagedata_size -= size;

            }

        } else {

            /* run-based motion compensation from last frame */

            motion_x = sign_extend(*vector_segment >> 4,  4);

            motion_y = sign_extend(*vector_segment & 0xF, 4);

            vector_segment++;



            /* copy a run of pixels from the previous frame */

            xan_wc3_copy_pixel_run(s, x, y, size, motion_x, motion_y);



            flag = 0;

        }



        /* coordinate accounting */

        total_pixels -= size;

        y += (x + size) / width;

        x  = (x + size) % width;

    }

    return 0;

}

static int vp9_raw_reorder_make_output(AVBSFContext *bsf,

                                   AVPacket *out,

                                   VP9RawReorderFrame *last_frame)

{

    VP9RawReorderContext *ctx = bsf->priv_data;

    VP9RawReorderFrame *next_output = last_frame,

                      *next_display = last_frame, *frame;

    int s, err;



    for (s = 0; s < FRAME_SLOTS; s++) {

        frame = ctx->slot[s];

        if (!frame)

            continue;

        if (frame->needs_output && (!next_output ||

            frame->sequence < next_output->sequence))

            next_output = frame;

        if (frame->needs_display && (!next_display ||

            frame->pts < next_display->pts))

            next_display = frame;

    }



    if (!next_output && !next_display)

        return AVERROR_EOF;



    if (!next_display || (next_output &&

        next_output->sequence < next_display->sequence))

        frame = next_output;

    else

        frame = next_display;



    if (frame->needs_output && frame->needs_display &&

        next_output == next_display) {

        av_log(bsf, AV_LOG_DEBUG, "Output and display frame "

               "%"PRId64" (%"PRId64") in order.\n",

               frame->sequence, frame->pts);



        av_packet_move_ref(out, frame->packet);



        frame->needs_output = frame->needs_display = 0;

    } else if (frame->needs_output) {

        if (frame->needs_display) {

            av_log(bsf, AV_LOG_DEBUG, "Output frame %"PRId64" "

                   "(%"PRId64") for later display.\n",

                   frame->sequence, frame->pts);

        } else {

            av_log(bsf, AV_LOG_DEBUG, "Output unshown frame "

                   "%"PRId64" (%"PRId64") to keep order.\n",

                   frame->sequence, frame->pts);

        }



        av_packet_move_ref(out, frame->packet);

        out->pts = out->dts;



        frame->needs_output = 0;

    } else {

        PutBitContext pb;



        av_assert0(!frame->needs_output && frame->needs_display);



        if (frame->slots == 0) {

            av_log(bsf, AV_LOG_ERROR, "Attempting to display frame "

                   "which is no longer available?\n");

            frame->needs_display = 0;

            return AVERROR_INVALIDDATA;

        }



        s = ff_ctz(frame->slots);

        av_assert0(s < FRAME_SLOTS);



        av_log(bsf, AV_LOG_DEBUG, "Display frame %"PRId64" "

               "(%"PRId64") from slot %d.\n",

               frame->sequence, frame->pts, s);



        frame->packet = av_packet_alloc();

        if (!frame->packet)

            return AVERROR(ENOMEM);



        err = av_new_packet(out, 2);

        if (err < 0)

            return err;



        init_put_bits(&pb, out->data, 2);



        // frame_marker

        put_bits(&pb, 2, 2);

        // profile_low_bit

        put_bits(&pb, 1, frame->profile & 1);

        // profile_high_bit

        put_bits(&pb, 1, (frame->profile >> 1) & 1);

        if (frame->profile == 3) {

            // reserved_zero

            put_bits(&pb, 1, 0);

        }

        // show_existing_frame

        put_bits(&pb, 1, 1);

        // frame_to_show_map_idx

        put_bits(&pb, 3, s);



        while (put_bits_count(&pb) < 16)

            put_bits(&pb, 1, 0);



        flush_put_bits(&pb);

        out->pts = out->dts = frame->pts;



        frame->needs_display = 0;

    }



    return 0;

}

static void decode_band_structure(GetBitContext *gbc, int blk, int eac3,

                                  int ecpl, int start_subband, int end_subband,

                                  const uint8_t *default_band_struct,

                                  int *num_bands, uint8_t *band_sizes)

{

    int subbnd, bnd, n_subbands, n_bands=0;

    uint8_t bnd_sz[22];

    uint8_t coded_band_struct[22];

    const uint8_t *band_struct;



    n_subbands = end_subband - start_subband;



    /* decode band structure from bitstream or use default */

    if (!eac3 || get_bits1(gbc)) {

        for (subbnd = 0; subbnd < n_subbands - 1; subbnd++) {

            coded_band_struct[subbnd] = get_bits1(gbc);

        }

        band_struct = coded_band_struct;

    } else if (!blk) {

        band_struct = &default_band_struct[start_subband+1];

    } else {

        /* no change in band structure */

        return;

    }



    /* calculate number of bands and band sizes based on band structure.

       note that the first 4 subbands in enhanced coupling span only 6 bins

       instead of 12. */

    if (num_bands || band_sizes ) {

        n_bands = n_subbands;

        bnd_sz[0] = ecpl ? 6 : 12;

        for (bnd = 0, subbnd = 1; subbnd < n_subbands; subbnd++) {

            int subbnd_size = (ecpl && subbnd < 4) ? 6 : 12;

            if (band_struct[subbnd - 1]) {

                n_bands--;

                bnd_sz[bnd] += subbnd_size;

            } else {

                bnd_sz[++bnd] = subbnd_size;

            }

        }

    }



    /* set optional output params */

    if (num_bands)

        *num_bands = n_bands;

    if (band_sizes)

        memcpy(band_sizes, bnd_sz, n_bands);

}

static int decode_block_progressive(MJpegDecodeContext *s, int16_t *block,

                                    uint8_t *last_nnz, int ac_index,

                                    uint16_t *quant_matrix,

                                    int ss, int se, int Al, int *EOBRUN)

{

    int code, i, j, level, val, run;



    if (*EOBRUN) {

        (*EOBRUN)--;

        return 0;

    }



    {

        OPEN_READER(re, &s->gb);

        for (i = ss; ; i++) {

            UPDATE_CACHE(re, &s->gb);

            GET_VLC(code, re, &s->gb, s->vlcs[2][ac_index].table, 9, 2);



            run = ((unsigned) code) >> 4;

            code &= 0xF;

            if (code) {

                i += run;

                if (code > MIN_CACHE_BITS - 16)

                    UPDATE_CACHE(re, &s->gb);



                {

                    int cache = GET_CACHE(re, &s->gb);

                    int sign  = (~cache) >> 31;

                    level     = (NEG_USR32(sign ^ cache,code) ^ sign) - sign;

                }



                LAST_SKIP_BITS(re, &s->gb, code);



                if (i >= se) {

                    if (i == se) {

                        j = s->scantable.permutated[se];

                        block[j] = level * (quant_matrix[se] << Al);

                        break;

                    }

                    av_log(s->avctx, AV_LOG_ERROR, "error count: %d\n", i);

                    return AVERROR_INVALIDDATA;

                }

                j = s->scantable.permutated[i];

                block[j] = level * (quant_matrix[i] << Al);

            } else {

                if (run == 0xF) {// ZRL - skip 15 coefficients

                    i += 15;

                    if (i >= se) {

                        av_log(s->avctx, AV_LOG_ERROR, "ZRL overflow: %d\n", i);

                        return AVERROR_INVALIDDATA;

                    }

                } else {

                    val = (1 << run);

                    if (run) {

                        UPDATE_CACHE(re, &s->gb);

                        val += NEG_USR32(GET_CACHE(re, &s->gb), run);

                        LAST_SKIP_BITS(re, &s->gb, run);

                    }

                    *EOBRUN = val - 1;

                    break;

                }

            }

        }

        CLOSE_READER(re, &s->gb);

    }



    if (i > *last_nnz)

        *last_nnz = i;



    return 0;

}

static int asf_read_header(AVFormatContext *s)

{

    ASFContext *asf = s->priv_data;

    ff_asf_guid g;

    AVIOContext *pb = s->pb;

    int i;

    int64_t gsize;



    ff_get_guid(pb, &g);

    if (ff_guidcmp(&g, &ff_asf_header))

        return AVERROR_INVALIDDATA;

    avio_rl64(pb);

    avio_rl32(pb);

    avio_r8(pb);

    avio_r8(pb);

    memset(&asf->asfid2avid, -1, sizeof(asf->asfid2avid));



    for (i = 0; i<128; i++)

        asf->streams[i].stream_language_index = 128; // invalid stream index means no language info



    for (;;) {

        uint64_t gpos = avio_tell(pb);

        ff_get_guid(pb, &g);

        gsize = avio_rl64(pb);

        print_guid(&g);

        if (!ff_guidcmp(&g, &ff_asf_data_header)) {

            asf->data_object_offset = avio_tell(pb);

            /* If not streaming, gsize is not unlimited (how?),

             * and there is enough space in the file.. */

            if (!(asf->hdr.flags & 0x01) && gsize >= 100)

                asf->data_object_size = gsize - 24;

            else

                asf->data_object_size = (uint64_t)-1;

            break;

        }

        if (gsize < 24)

            return AVERROR_INVALIDDATA;

        if (!ff_guidcmp(&g, &ff_asf_file_header)) {

            int ret = asf_read_file_properties(s, gsize);

            if (ret < 0)

                return ret;

        } else if (!ff_guidcmp(&g, &ff_asf_stream_header)) {

            int ret = asf_read_stream_properties(s, gsize);

            if (ret < 0)

                return ret;

        } else if (!ff_guidcmp(&g, &ff_asf_comment_header)) {

            asf_read_content_desc(s, gsize);

        } else if (!ff_guidcmp(&g, &ff_asf_language_guid)) {

            asf_read_language_list(s, gsize);

        } else if (!ff_guidcmp(&g, &ff_asf_extended_content_header)) {

            asf_read_ext_content_desc(s, gsize);

        } else if (!ff_guidcmp(&g, &ff_asf_metadata_header)) {

            asf_read_metadata(s, gsize);

        } else if (!ff_guidcmp(&g, &ff_asf_metadata_library_header)) {

            asf_read_metadata(s, gsize);

        } else if (!ff_guidcmp(&g, &ff_asf_ext_stream_header)) {

            asf_read_ext_stream_properties(s, gsize);



            // there could be a optional stream properties object to follow

            // if so the next iteration will pick it up

            continue;

        } else if (!ff_guidcmp(&g, &ff_asf_head1_guid)) {

            ff_get_guid(pb, &g);

            avio_skip(pb, 6);

            continue;

        } else if (!ff_guidcmp(&g, &ff_asf_marker_header)) {

            asf_read_marker(s, gsize);

        } else if (avio_feof(pb)) {

            return AVERROR_EOF;

        } else {

            if (!s->keylen) {

                if (!ff_guidcmp(&g, &ff_asf_content_encryption)) {

                    unsigned int len;

                    int ret;

                    AVPacket pkt;

                    av_log(s, AV_LOG_WARNING,

                           "DRM protected stream detected, decoding will likely fail!\n");

                    len= avio_rl32(pb);

                    av_log(s, AV_LOG_DEBUG, "Secret data:\n");



                    if ((ret = av_get_packet(pb, &pkt, len)) < 0)

                        return ret;

                    av_hex_dump_log(s, AV_LOG_DEBUG, pkt.data, pkt.size);

                    av_free_packet(&pkt);

                    len= avio_rl32(pb);

                    get_tag(s, "ASF_Protection_Type", -1, len, 32);

                    len= avio_rl32(pb);

                    get_tag(s, "ASF_Key_ID", -1, len, 32);

                    len= avio_rl32(pb);

                    get_tag(s, "ASF_License_URL", -1, len, 32);

                } else if (!ff_guidcmp(&g, &ff_asf_ext_content_encryption)) {

                    av_log(s, AV_LOG_WARNING,

                           "Ext DRM protected stream detected, decoding will likely fail!\n");

                    av_dict_set(&s->metadata, "encryption", "ASF Extended Content Encryption", 0);

                } else if (!ff_guidcmp(&g, &ff_asf_digital_signature)) {

                    av_log(s, AV_LOG_INFO, "Digital signature detected!\n");

                }

            }

        }

        if (avio_tell(pb) != gpos + gsize)

            av_log(s, AV_LOG_DEBUG,

                   "gpos mismatch our pos=%"PRIu64", end=%"PRId64"\n",

                   avio_tell(pb) - gpos, gsize);

        avio_seek(pb, gpos + gsize, SEEK_SET);

    }

    ff_get_guid(pb, &g);

    avio_rl64(pb);

    avio_r8(pb);

    avio_r8(pb);

    if (avio_feof(pb))

        return AVERROR_EOF;

    asf->data_offset      = avio_tell(pb);

    asf->packet_size_left = 0;



    for (i = 0; i < 128; i++) {

        int stream_num = asf->asfid2avid[i];

        if (stream_num >= 0) {

            AVStream *st = s->streams[stream_num];

            if (!st->codec->bit_rate)

                st->codec->bit_rate = asf->stream_bitrates[i];

            if (asf->dar[i].num > 0 && asf->dar[i].den > 0) {

                av_reduce(&st->sample_aspect_ratio.num,

                          &st->sample_aspect_ratio.den,

                          asf->dar[i].num, asf->dar[i].den, INT_MAX);

            } else if ((asf->dar[0].num > 0) && (asf->dar[0].den > 0) &&

                       // Use ASF container value if the stream doesn't set AR.

                       (st->codec->codec_type == AVMEDIA_TYPE_VIDEO))

                av_reduce(&st->sample_aspect_ratio.num,

                          &st->sample_aspect_ratio.den,

                          asf->dar[0].num, asf->dar[0].den, INT_MAX);



            av_log(s, AV_LOG_TRACE, "i=%d, st->codec->codec_type:%d, asf->dar %d:%d sar=%d:%d\n",

                    i, st->codec->codec_type, asf->dar[i].num, asf->dar[i].den,

                    st->sample_aspect_ratio.num, st->sample_aspect_ratio.den);



            // copy and convert language codes to the frontend

            if (asf->streams[i].stream_language_index < 128) {

                const char *rfc1766 = asf->stream_languages[asf->streams[i].stream_language_index];

                if (rfc1766 && strlen(rfc1766) > 1) {

                    const char primary_tag[3] = { rfc1766[0], rfc1766[1], '\0' }; // ignore country code if any

                    const char *iso6392       = av_convert_lang_to(primary_tag,

                                                                   AV_LANG_ISO639_2_BIBL);

                    if (iso6392)

                        av_dict_set(&st->metadata, "language", iso6392, 0);

                }

            }

        }

    }



    ff_metadata_conv(&s->metadata, NULL, ff_asf_metadata_conv);



    return 0;

}

int ff_interleave_packet_per_dts(AVFormatContext *s, AVPacket *out,

                                 AVPacket *pkt, int flush)

{

    AVPacketList *pktl;

    int stream_count = 0;

    int i;



    if (pkt) {

        ff_interleave_add_packet(s, pkt, interleave_compare_dts);

    }



    if (s->max_interleave_delta > 0 && s->packet_buffer && !flush) {

        AVPacket *top_pkt = &s->packet_buffer->pkt;

        int64_t delta_dts = INT64_MIN;

        int64_t top_dts = av_rescale_q(top_pkt->dts,

                                       s->streams[top_pkt->stream_index]->time_base,

                                       AV_TIME_BASE_Q);



        for (i = 0; i < s->nb_streams; i++) {

            int64_t last_dts;

            const AVPacketList *last = s->streams[i]->last_in_packet_buffer;



            if (!last)

                continue;



            last_dts = av_rescale_q(last->pkt.dts,

                                    s->streams[i]->time_base,

                                    AV_TIME_BASE_Q);

            delta_dts = FFMAX(delta_dts, last_dts - top_dts);

            stream_count++;

        }



        if (delta_dts > s->max_interleave_delta) {

            av_log(s, AV_LOG_DEBUG,

                   "Delay between the first packet and last packet in the "

                   "muxing queue is %"PRId64" > %"PRId64": forcing output\n",

                   delta_dts, s->max_interleave_delta);

            flush = 1;

        }

    } else {

        for (i = 0; i < s->nb_streams; i++)

            stream_count += !!s->streams[i]->last_in_packet_buffer;

    }





    if (stream_count && (s->internal->nb_interleaved_streams == stream_count || flush)) {

        pktl = s->packet_buffer;

        *out = pktl->pkt;



        s->packet_buffer = pktl->next;

        if (!s->packet_buffer)

            s->packet_buffer_end = NULL;



        if (s->streams[out->stream_index]->last_in_packet_buffer == pktl)

            s->streams[out->stream_index]->last_in_packet_buffer = NULL;

        av_freep(&pktl);

        return 1;

    } else {

        av_init_packet(out);

        return 0;

    }

}

static int svq3_decode_mb(SVQ3Context *s, unsigned int mb_type)

{

    H264Context *h = &s->h;

    int i, j, k, m, dir, mode;

    int cbp = 0;

    uint32_t vlc;

    int8_t *top, *left;

    const int mb_xy         = h->mb_xy;

    const int b_xy          = 4 * h->mb_x + 4 * h->mb_y * h->b_stride;



    h->top_samples_available      = (h->mb_y == 0) ? 0x33FF : 0xFFFF;

    h->left_samples_available     = (h->mb_x == 0) ? 0x5F5F : 0xFFFF;

    h->topright_samples_available = 0xFFFF;



    if (mb_type == 0) {           /* SKIP */

        if (h->pict_type == AV_PICTURE_TYPE_P ||

            s->next_pic->mb_type[mb_xy] == -1) {

            svq3_mc_dir_part(s, 16 * h->mb_x, 16 * h->mb_y, 16, 16,

                             0, 0, 0, 0, 0, 0);



            if (h->pict_type == AV_PICTURE_TYPE_B)

                svq3_mc_dir_part(s, 16 * h->mb_x, 16 * h->mb_y, 16, 16,

                                 0, 0, 0, 0, 1, 1);



            mb_type = MB_TYPE_SKIP;

        } else {

            mb_type = FFMIN(s->next_pic->mb_type[mb_xy], 6);

            if (svq3_mc_dir(s, mb_type, PREDICT_MODE, 0, 0) < 0)

                return -1;

            if (svq3_mc_dir(s, mb_type, PREDICT_MODE, 1, 1) < 0)

                return -1;



            mb_type = MB_TYPE_16x16;

        }

    } else if (mb_type < 8) {     /* INTER */

        if (s->thirdpel_flag && s->halfpel_flag == !get_bits1(&h->gb))

            mode = THIRDPEL_MODE;

        else if (s->halfpel_flag &&

                 s->thirdpel_flag == !get_bits1(&h->gb))

            mode = HALFPEL_MODE;

        else

            mode = FULLPEL_MODE;



        /* fill caches */

        /* note ref_cache should contain here:

         *  ????????

         *  ???11111

         *  N??11111

         *  N??11111

         *  N??11111

         */



        for (m = 0; m < 2; m++) {

            if (h->mb_x > 0 && h->intra4x4_pred_mode[h->mb2br_xy[mb_xy - 1] + 6] != -1) {

                for (i = 0; i < 4; i++)

                    AV_COPY32(h->mv_cache[m][scan8[0] - 1 + i * 8],

                              h->cur_pic.motion_val[m][b_xy - 1 + i * h->b_stride]);

            } else {

                for (i = 0; i < 4; i++)

                    AV_ZERO32(h->mv_cache[m][scan8[0] - 1 + i * 8]);

            }

            if (h->mb_y > 0) {

                memcpy(h->mv_cache[m][scan8[0] - 1 * 8],

                       h->cur_pic.motion_val[m][b_xy - h->b_stride],

                       4 * 2 * sizeof(int16_t));

                memset(&h->ref_cache[m][scan8[0] - 1 * 8],

                       (h->intra4x4_pred_mode[h->mb2br_xy[mb_xy - h->mb_stride]] == -1) ? PART_NOT_AVAILABLE : 1, 4);



                if (h->mb_x < h->mb_width - 1) {

                    AV_COPY32(h->mv_cache[m][scan8[0] + 4 - 1 * 8],

                              h->cur_pic.motion_val[m][b_xy - h->b_stride + 4]);

                    h->ref_cache[m][scan8[0] + 4 - 1 * 8] =

                        (h->intra4x4_pred_mode[h->mb2br_xy[mb_xy - h->mb_stride + 1] + 6] == -1 ||

                         h->intra4x4_pred_mode[h->mb2br_xy[mb_xy - h->mb_stride]] == -1) ? PART_NOT_AVAILABLE : 1;

                } else

                    h->ref_cache[m][scan8[0] + 4 - 1 * 8] = PART_NOT_AVAILABLE;

                if (h->mb_x > 0) {

                    AV_COPY32(h->mv_cache[m][scan8[0] - 1 - 1 * 8],

                              h->cur_pic.motion_val[m][b_xy - h->b_stride - 1]);

                    h->ref_cache[m][scan8[0] - 1 - 1 * 8] =

                        (h->intra4x4_pred_mode[h->mb2br_xy[mb_xy - h->mb_stride - 1] + 3] == -1) ? PART_NOT_AVAILABLE : 1;

                } else

                    h->ref_cache[m][scan8[0] - 1 - 1 * 8] = PART_NOT_AVAILABLE;

            } else

                memset(&h->ref_cache[m][scan8[0] - 1 * 8 - 1],

                       PART_NOT_AVAILABLE, 8);



            if (h->pict_type != AV_PICTURE_TYPE_B)

                break;

        }



        /* decode motion vector(s) and form prediction(s) */

        if (h->pict_type == AV_PICTURE_TYPE_P) {

            if (svq3_mc_dir(s, mb_type - 1, mode, 0, 0) < 0)

                return -1;

        } else {        /* AV_PICTURE_TYPE_B */

            if (mb_type != 2) {

                if (svq3_mc_dir(s, 0, mode, 0, 0) < 0)

                    return -1;

            } else {

                for (i = 0; i < 4; i++)

                    memset(h->cur_pic.motion_val[0][b_xy + i * h->b_stride],

                           0, 4 * 2 * sizeof(int16_t));

            }

            if (mb_type != 1) {

                if (svq3_mc_dir(s, 0, mode, 1, mb_type == 3) < 0)

                    return -1;

            } else {

                for (i = 0; i < 4; i++)

                    memset(h->cur_pic.motion_val[1][b_xy + i * h->b_stride],

                           0, 4 * 2 * sizeof(int16_t));

            }

        }



        mb_type = MB_TYPE_16x16;

    } else if (mb_type == 8 || mb_type == 33) {   /* INTRA4x4 */

        memset(h->intra4x4_pred_mode_cache, -1, 8 * 5 * sizeof(int8_t));



        if (mb_type == 8) {

            if (h->mb_x > 0) {

                for (i = 0; i < 4; i++)

                    h->intra4x4_pred_mode_cache[scan8[0] - 1 + i * 8] = h->intra4x4_pred_mode[h->mb2br_xy[mb_xy - 1] + 6 - i];

                if (h->intra4x4_pred_mode_cache[scan8[0] - 1] == -1)

                    h->left_samples_available = 0x5F5F;

            }

            if (h->mb_y > 0) {

                h->intra4x4_pred_mode_cache[4 + 8 * 0] = h->intra4x4_pred_mode[h->mb2br_xy[mb_xy - h->mb_stride] + 0];

                h->intra4x4_pred_mode_cache[5 + 8 * 0] = h->intra4x4_pred_mode[h->mb2br_xy[mb_xy - h->mb_stride] + 1];

                h->intra4x4_pred_mode_cache[6 + 8 * 0] = h->intra4x4_pred_mode[h->mb2br_xy[mb_xy - h->mb_stride] + 2];

                h->intra4x4_pred_mode_cache[7 + 8 * 0] = h->intra4x4_pred_mode[h->mb2br_xy[mb_xy - h->mb_stride] + 3];



                if (h->intra4x4_pred_mode_cache[4 + 8 * 0] == -1)

                    h->top_samples_available = 0x33FF;

            }



            /* decode prediction codes for luma blocks */

            for (i = 0; i < 16; i += 2) {

                vlc = svq3_get_ue_golomb(&h->gb);



                if (vlc >= 25U) {

                    av_log(h->avctx, AV_LOG_ERROR, "luma prediction:%d\n", vlc);

                    return -1;

                }



                left = &h->intra4x4_pred_mode_cache[scan8[i] - 1];

                top  = &h->intra4x4_pred_mode_cache[scan8[i] - 8];



                left[1] = svq3_pred_1[top[0] + 1][left[0] + 1][svq3_pred_0[vlc][0]];

                left[2] = svq3_pred_1[top[1] + 1][left[1] + 1][svq3_pred_0[vlc][1]];



                if (left[1] == -1 || left[2] == -1) {

                    av_log(h->avctx, AV_LOG_ERROR, "weird prediction\n");

                    return -1;

                }

            }

        } else {    /* mb_type == 33, DC_128_PRED block type */

            for (i = 0; i < 4; i++)

                memset(&h->intra4x4_pred_mode_cache[scan8[0] + 8 * i], DC_PRED, 4);

        }



        write_back_intra_pred_mode(h);



        if (mb_type == 8) {

            ff_h264_check_intra4x4_pred_mode(h);



            h->top_samples_available  = (h->mb_y == 0) ? 0x33FF : 0xFFFF;

            h->left_samples_available = (h->mb_x == 0) ? 0x5F5F : 0xFFFF;

        } else {

            for (i = 0; i < 4; i++)

                memset(&h->intra4x4_pred_mode_cache[scan8[0] + 8 * i], DC_128_PRED, 4);



            h->top_samples_available  = 0x33FF;

            h->left_samples_available = 0x5F5F;

        }



        mb_type = MB_TYPE_INTRA4x4;

    } else {                      /* INTRA16x16 */

        dir = i_mb_type_info[mb_type - 8].pred_mode;

        dir = (dir >> 1) ^ 3 * (dir & 1) ^ 1;



        if ((h->intra16x16_pred_mode = ff_h264_check_intra_pred_mode(h, dir, 0)) == -1) {

            av_log(h->avctx, AV_LOG_ERROR, "check_intra_pred_mode = -1\n");

            return -1;

        }



        cbp     = i_mb_type_info[mb_type - 8].cbp;

        mb_type = MB_TYPE_INTRA16x16;

    }



    if (!IS_INTER(mb_type) && h->pict_type != AV_PICTURE_TYPE_I) {

        for (i = 0; i < 4; i++)

            memset(h->cur_pic.motion_val[0][b_xy + i * h->b_stride],

                   0, 4 * 2 * sizeof(int16_t));

        if (h->pict_type == AV_PICTURE_TYPE_B) {

            for (i = 0; i < 4; i++)

                memset(h->cur_pic.motion_val[1][b_xy + i * h->b_stride],

                       0, 4 * 2 * sizeof(int16_t));

        }

    }

    if (!IS_INTRA4x4(mb_type)) {

        memset(h->intra4x4_pred_mode + h->mb2br_xy[mb_xy], DC_PRED, 8);

    }

    if (!IS_SKIP(mb_type) || h->pict_type == AV_PICTURE_TYPE_B) {

        memset(h->non_zero_count_cache + 8, 0, 14 * 8 * sizeof(uint8_t));

    }



    if (!IS_INTRA16x16(mb_type) &&

        (!IS_SKIP(mb_type) || h->pict_type == AV_PICTURE_TYPE_B)) {

        if ((vlc = svq3_get_ue_golomb(&h->gb)) >= 48U){

            av_log(h->avctx, AV_LOG_ERROR, "cbp_vlc=%d\n", vlc);

            return -1;

        }



        cbp = IS_INTRA(mb_type) ? golomb_to_intra4x4_cbp[vlc]

                                : golomb_to_inter_cbp[vlc];

    }

    if (IS_INTRA16x16(mb_type) ||

        (h->pict_type != AV_PICTURE_TYPE_I && s->adaptive_quant && cbp)) {

        h->qscale += svq3_get_se_golomb(&h->gb);



        if (h->qscale > 31u) {

            av_log(h->avctx, AV_LOG_ERROR, "qscale:%d\n", h->qscale);

            return -1;

        }

    }

    if (IS_INTRA16x16(mb_type)) {

        AV_ZERO128(h->mb_luma_dc[0] + 0);

        AV_ZERO128(h->mb_luma_dc[0] + 8);

        if (svq3_decode_block(&h->gb, h->mb_luma_dc[0], 0, 1)) {

            av_log(h->avctx, AV_LOG_ERROR,

                   "error while decoding intra luma dc\n");

            return -1;

        }

    }



    if (cbp) {

        const int index = IS_INTRA16x16(mb_type) ? 1 : 0;

        const int type  = ((h->qscale < 24 && IS_INTRA4x4(mb_type)) ? 2 : 1);



        for (i = 0; i < 4; i++)

            if ((cbp & (1 << i))) {

                for (j = 0; j < 4; j++) {

                    k = index ? (1 * (j & 1) + 2 * (i & 1) +

                                 2 * (j & 2) + 4 * (i & 2))

                              : (4 * i + j);

                    h->non_zero_count_cache[scan8[k]] = 1;



                    if (svq3_decode_block(&h->gb, &h->mb[16 * k], index, type)) {

                        av_log(h->avctx, AV_LOG_ERROR,

                               "error while decoding block\n");

                        return -1;

                    }

                }

            }



        if ((cbp & 0x30)) {

            for (i = 1; i < 3; ++i)

                if (svq3_decode_block(&h->gb, &h->mb[16 * 16 * i], 0, 3)) {

                    av_log(h->avctx, AV_LOG_ERROR,

                           "error while decoding chroma dc block\n");

                    return -1;

                }



            if ((cbp & 0x20)) {

                for (i = 1; i < 3; i++) {

                    for (j = 0; j < 4; j++) {

                        k                                 = 16 * i + j;

                        h->non_zero_count_cache[scan8[k]] = 1;



                        if (svq3_decode_block(&h->gb, &h->mb[16 * k], 1, 1)) {

                            av_log(h->avctx, AV_LOG_ERROR,

                                   "error while decoding chroma ac block\n");

                            return -1;

                        }

                    }

                }

            }

        }

    }



    h->cbp                              = cbp;

    h->cur_pic.mb_type[mb_xy] = mb_type;



    if (IS_INTRA(mb_type))

        h->chroma_pred_mode = ff_h264_check_intra_pred_mode(h, DC_PRED8x8, 1);



    return 0;

}

static void loop_filter(H264Context *h, H264SliceContext *sl, int start_x, int end_x)

{

    uint8_t *dest_y, *dest_cb, *dest_cr;

    int linesize, uvlinesize, mb_x, mb_y;

    const int end_mb_y       = h->mb_y + FRAME_MBAFF(h);

    const int old_slice_type = sl->slice_type;

    const int pixel_shift    = h->pixel_shift;

    const int block_h        = 16 >> h->chroma_y_shift;



    if (h->deblocking_filter) {

        for (mb_x = start_x; mb_x < end_x; mb_x++)

            for (mb_y = end_mb_y - FRAME_MBAFF(h); mb_y <= end_mb_y; mb_y++) {

                int mb_xy, mb_type;

                mb_xy         = h->mb_xy = mb_x + mb_y * h->mb_stride;

                sl->slice_num = h->slice_table[mb_xy];

                mb_type       = h->cur_pic.mb_type[mb_xy];

                sl->list_count = h->list_counts[mb_xy];



                if (FRAME_MBAFF(h))

                    h->mb_mbaff               =

                    h->mb_field_decoding_flag = !!IS_INTERLACED(mb_type);



                h->mb_x = mb_x;

                h->mb_y = mb_y;

                dest_y  = h->cur_pic.f.data[0] +

                          ((mb_x << pixel_shift) + mb_y * h->linesize) * 16;

                dest_cb = h->cur_pic.f.data[1] +

                          (mb_x << pixel_shift) * (8 << CHROMA444(h)) +

                          mb_y * h->uvlinesize * block_h;

                dest_cr = h->cur_pic.f.data[2] +

                          (mb_x << pixel_shift) * (8 << CHROMA444(h)) +

                          mb_y * h->uvlinesize * block_h;

                // FIXME simplify above



                if (MB_FIELD(h)) {

                    linesize   = sl->mb_linesize   = h->linesize   * 2;

                    uvlinesize = sl->mb_uvlinesize = h->uvlinesize * 2;

                    if (mb_y & 1) { // FIXME move out of this function?

                        dest_y  -= h->linesize   * 15;

                        dest_cb -= h->uvlinesize * (block_h - 1);

                        dest_cr -= h->uvlinesize * (block_h - 1);

                    }

                } else {

                    linesize   = sl->mb_linesize   = h->linesize;

                    uvlinesize = sl->mb_uvlinesize = h->uvlinesize;

                }

                backup_mb_border(h, dest_y, dest_cb, dest_cr, linesize,

                                 uvlinesize, 0);

                if (fill_filter_caches(h, sl, mb_type))

                    continue;

                sl->chroma_qp[0] = get_chroma_qp(h, 0, h->cur_pic.qscale_table[mb_xy]);

                sl->chroma_qp[1] = get_chroma_qp(h, 1, h->cur_pic.qscale_table[mb_xy]);



                if (FRAME_MBAFF(h)) {

                    ff_h264_filter_mb(h, sl, mb_x, mb_y, dest_y, dest_cb, dest_cr,

                                      linesize, uvlinesize);

                } else {

                    ff_h264_filter_mb_fast(h, sl, mb_x, mb_y, dest_y, dest_cb,

                                           dest_cr, linesize, uvlinesize);

                }

            }

    }

    sl->slice_type  = old_slice_type;

    h->mb_x         = end_x;

    h->mb_y         = end_mb_y - FRAME_MBAFF(h);

    sl->chroma_qp[0] = get_chroma_qp(h, 0, sl->qscale);

    sl->chroma_qp[1] = get_chroma_qp(h, 1, sl->qscale);

}

static int detect_stream_specific(AVFormatContext *avf, int idx)

{

    ConcatContext *cat = avf->priv_data;

    AVStream *st = cat->avf->streams[idx];

    ConcatStream *cs = &cat->cur_file->streams[idx];

    AVBitStreamFilterContext *bsf;

    int ret;



    if (cat->auto_convert && st->codecpar->codec_id == AV_CODEC_ID_H264 &&

        (st->codecpar->extradata_size < 4 || AV_RB32(st->codecpar->extradata) != 1)) {

        av_log(cat->avf, AV_LOG_INFO,

               "Auto-inserting h264_mp4toannexb bitstream filter\n");

        if (!(bsf = av_bitstream_filter_init("h264_mp4toannexb"))) {

            av_log(avf, AV_LOG_ERROR, "h264_mp4toannexb bitstream filter "

                   "required for H.264 streams\n");

            return AVERROR_BSF_NOT_FOUND;

        }

        cs->bsf = bsf;



        cs->avctx = avcodec_alloc_context3(NULL);

        if (!cs->avctx)

            return AVERROR(ENOMEM);



        /* This really should be part of the bsf work.

           Note: input bitstream filtering will not work with bsf that

           create extradata from the first packet. */

        av_freep(&st->codecpar->extradata);

        st->codecpar->extradata_size = 0;



        ret = avcodec_parameters_to_context(cs->avctx, st->codecpar);

        if (ret < 0) {

            avcodec_free_context(&cs->avctx);

            return ret;

        }



    }

    return 0;

}

static int rm_read_audio_stream_info(AVFormatContext *s, ByteIOContext *pb,

                                     AVStream *st, int read_all)

{

    RMDemuxContext *rm = s->priv_data;

    char buf[256];

    uint32_t version;

    int i;



    /* ra type header */

    version = get_be32(pb); /* version */

    if (((version >> 16) & 0xff) == 3) {

        int64_t startpos = url_ftell(pb);

        /* very old version */

        for(i = 0; i < 14; i++)

            get_byte(pb);

        get_str8(pb, s->title, sizeof(s->title));

        get_str8(pb, s->author, sizeof(s->author));

        get_str8(pb, s->copyright, sizeof(s->copyright));

        get_str8(pb, s->comment, sizeof(s->comment));

        if ((startpos + (version & 0xffff)) >= url_ftell(pb) + 2) {

            // fourcc (should always be "lpcJ")

            get_byte(pb);

            get_str8(pb, buf, sizeof(buf));

        }

        // Skip extra header crap (this should never happen)

        if ((startpos + (version & 0xffff)) > url_ftell(pb))

            url_fskip(pb, (version & 0xffff) + startpos - url_ftell(pb));

        st->codec->sample_rate = 8000;

        st->codec->channels = 1;

        st->codec->codec_type = CODEC_TYPE_AUDIO;

        st->codec->codec_id = CODEC_ID_RA_144;

    } else {

        int flavor, sub_packet_h, coded_framesize, sub_packet_size;

        /* old version (4) */

        get_be32(pb); /* .ra4 */

        get_be32(pb); /* data size */

        get_be16(pb); /* version2 */

        get_be32(pb); /* header size */

        flavor= get_be16(pb); /* add codec info / flavor */

        rm->coded_framesize = coded_framesize = get_be32(pb); /* coded frame size */

        get_be32(pb); /* ??? */

        get_be32(pb); /* ??? */

        get_be32(pb); /* ??? */

        rm->sub_packet_h = sub_packet_h = get_be16(pb); /* 1 */

        st->codec->block_align= get_be16(pb); /* frame size */

        rm->sub_packet_size = sub_packet_size = get_be16(pb); /* sub packet size */

        get_be16(pb); /* ??? */

        if (((version >> 16) & 0xff) == 5) {

            get_be16(pb); get_be16(pb); get_be16(pb);

        }

        st->codec->sample_rate = get_be16(pb);

        get_be32(pb);

        st->codec->channels = get_be16(pb);

        if (((version >> 16) & 0xff) == 5) {

            get_be32(pb);

            buf[0] = get_byte(pb);

            buf[1] = get_byte(pb);

            buf[2] = get_byte(pb);

            buf[3] = get_byte(pb);

            buf[4] = 0;

        } else {

            get_str8(pb, buf, sizeof(buf)); /* desc */

            get_str8(pb, buf, sizeof(buf)); /* desc */

        }

        st->codec->codec_type = CODEC_TYPE_AUDIO;

        if (!strcmp(buf, "dnet")) {

            st->codec->codec_id = CODEC_ID_AC3;

            st->need_parsing = AVSTREAM_PARSE_FULL;

        } else if (!strcmp(buf, "28_8")) {

            st->codec->codec_id = CODEC_ID_RA_288;

            st->codec->extradata_size= 0;

            rm->audio_framesize = st->codec->block_align;

            st->codec->block_align = coded_framesize;



            if(rm->audio_framesize >= UINT_MAX / sub_packet_h){

                av_log(s, AV_LOG_ERROR, "rm->audio_framesize * sub_packet_h too large\n");

                return -1;

            }



            rm->audiobuf = av_malloc(rm->audio_framesize * sub_packet_h);

        } else if ((!strcmp(buf, "cook")) || (!strcmp(buf, "atrc")) || (!strcmp(buf, "sipr"))) {

            int codecdata_length, i;

            get_be16(pb); get_byte(pb);

            if (((version >> 16) & 0xff) == 5)

                get_byte(pb);

            codecdata_length = get_be32(pb);

            if(codecdata_length + FF_INPUT_BUFFER_PADDING_SIZE <= (unsigned)codecdata_length){

                av_log(s, AV_LOG_ERROR, "codecdata_length too large\n");

                return -1;

            }



            if(sub_packet_size <= 0){

                av_log(s, AV_LOG_ERROR, "sub_packet_size is invalid\n");

                return -1;

            }



            if (!strcmp(buf, "cook")) st->codec->codec_id = CODEC_ID_COOK;

            else if (!strcmp(buf, "sipr")) st->codec->codec_id = CODEC_ID_SIPR;

            else st->codec->codec_id = CODEC_ID_ATRAC3;

            st->codec->extradata_size= codecdata_length;

            st->codec->extradata= av_mallocz(st->codec->extradata_size + FF_INPUT_BUFFER_PADDING_SIZE);

            for(i = 0; i < codecdata_length; i++)

                ((uint8_t*)st->codec->extradata)[i] = get_byte(pb);

            rm->audio_framesize = st->codec->block_align;

            st->codec->block_align = rm->sub_packet_size;



            if(rm->audio_framesize >= UINT_MAX / sub_packet_h){

                av_log(s, AV_LOG_ERROR, "rm->audio_framesize * sub_packet_h too large\n");

                return -1;

            }



            rm->audiobuf = av_malloc(rm->audio_framesize * sub_packet_h);

        } else if (!strcmp(buf, "raac") || !strcmp(buf, "racp")) {

            int codecdata_length, i;

            get_be16(pb); get_byte(pb);

            if (((version >> 16) & 0xff) == 5)

                get_byte(pb);

            st->codec->codec_id = CODEC_ID_AAC;

            codecdata_length = get_be32(pb);

            if(codecdata_length + FF_INPUT_BUFFER_PADDING_SIZE <= (unsigned)codecdata_length){

                av_log(s, AV_LOG_ERROR, "codecdata_length too large\n");

                return -1;

            }

            if (codecdata_length >= 1) {

                st->codec->extradata_size = codecdata_length - 1;

                st->codec->extradata = av_mallocz(st->codec->extradata_size + FF_INPUT_BUFFER_PADDING_SIZE);

                get_byte(pb);

                for(i = 0; i < st->codec->extradata_size; i++)

                    ((uint8_t*)st->codec->extradata)[i] = get_byte(pb);

            }

        } else {

            st->codec->codec_id = CODEC_ID_NONE;

            av_strlcpy(st->codec->codec_name, buf, sizeof(st->codec->codec_name));

        }

        if (read_all) {

            get_byte(pb);

            get_byte(pb);

            get_byte(pb);



            get_str8(pb, s->title, sizeof(s->title));

            get_str8(pb, s->author, sizeof(s->author));

            get_str8(pb, s->copyright, sizeof(s->copyright));

            get_str8(pb, s->comment, sizeof(s->comment));

        }

    }

    return 0;

}

void ff_rv10_encode_picture_header(MpegEncContext *s, int picture_number)

{

    int full_frame= 0;



    avpriv_align_put_bits(&s->pb);



    put_bits(&s->pb, 1, 1);     /* marker */



    put_bits(&s->pb, 1, (s->pict_type == AV_PICTURE_TYPE_P));



    put_bits(&s->pb, 1, 0);     /* not PB frame */



    put_bits(&s->pb, 5, s->qscale);



    if (s->pict_type == AV_PICTURE_TYPE_I) {

        /* specific MPEG like DC coding not used */

    }

    /* if multiple packets per frame are sent, the position at which

       to display the macroblocks is coded here */

    if(!full_frame){

        put_bits(&s->pb, 6, 0); /* mb_x */

        put_bits(&s->pb, 6, 0); /* mb_y */

        put_bits(&s->pb, 12, s->mb_width * s->mb_height);

    }



    put_bits(&s->pb, 3, 0);     /* ignored */

}

static inline int wnv1_get_code(WNV1Context *w, int base_value)

{

    int v = get_vlc2(&w->gb, code_vlc.table, CODE_VLC_BITS, 1);



    if (v == 15)

        return ff_reverse[get_bits(&w->gb, 8 - w->shift)];

    else

        return base_value + ((v - 7) << w->shift);

}

int av_image_get_linesize(enum PixelFormat pix_fmt, int width, int plane)

{

    const AVPixFmtDescriptor *desc = &av_pix_fmt_descriptors[pix_fmt];

    int max_step     [4];       /* max pixel step for each plane */

    int max_step_comp[4];       /* the component for each plane which has the max pixel step */

    int s;



    if (desc->flags & PIX_FMT_BITSTREAM)

        return (width * (desc->comp[0].step_minus1+1) + 7) >> 3;



    av_image_fill_max_pixsteps(max_step, max_step_comp, desc);

    s = (max_step_comp[plane] == 1 || max_step_comp[plane] == 2) ? desc->log2_chroma_w : 0;

    return max_step[plane] * (((width + (1 << s) - 1)) >> s);

}

rdt_parse_packet (AVFormatContext *ctx, PayloadContext *rdt, AVStream *st,

                  AVPacket *pkt, uint32_t *timestamp,

                  const uint8_t *buf, int len, uint16_t rtp_seq, int flags)

{

    int seq = 1, res;

    AVIOContext pb;



    if (!rdt->rmctx)

        return AVERROR(EINVAL);



    if (rdt->audio_pkt_cnt == 0) {

        int pos;



        ffio_init_context(&pb, buf, len, 0, NULL, NULL, NULL, NULL);

        flags = (flags & RTP_FLAG_KEY) ? 2 : 0;

        res = ff_rm_parse_packet (rdt->rmctx, &pb, st, rdt->rmst[st->index], len, pkt,

                                  &seq, flags, *timestamp);

        pos = avio_tell(&pb);

        if (res < 0)

            return res;

        if (res > 0) {

            if (st->codec->codec_id == AV_CODEC_ID_AAC) {

                memcpy (rdt->buffer, buf + pos, len - pos);

                rdt->rmctx->pb = avio_alloc_context (rdt->buffer, len - pos, 0,

                                                    NULL, NULL, NULL, NULL);

            }

            goto get_cache;

        }

    } else {

get_cache:

        rdt->audio_pkt_cnt =

            ff_rm_retrieve_cache (rdt->rmctx, rdt->rmctx->pb,

                                  st, rdt->rmst[st->index], pkt);

        if (rdt->audio_pkt_cnt == 0 &&

            st->codec->codec_id == AV_CODEC_ID_AAC)

            av_freep(&rdt->rmctx->pb);

    }

    pkt->stream_index = st->index;

    pkt->pts = *timestamp;



    return rdt->audio_pkt_cnt > 0;

}

ff_rm_retrieve_cache (AVFormatContext *s, AVIOContext *pb,

                      AVStream *st, RMStream *ast, AVPacket *pkt)

{

    RMDemuxContext *rm = s->priv_data;



    assert (rm->audio_pkt_cnt > 0);



    if (ast->deint_id == DEINT_ID_VBRF ||

        ast->deint_id == DEINT_ID_VBRS)

        av_get_packet(pb, pkt, ast->sub_packet_lengths[ast->sub_packet_cnt - rm->audio_pkt_cnt]);

    else {

        av_new_packet(pkt, st->codec->block_align);

        memcpy(pkt->data, ast->pkt.data + st->codec->block_align * //FIXME avoid this

               (ast->sub_packet_h * ast->audio_framesize / st->codec->block_align - rm->audio_pkt_cnt),

               st->codec->block_align);

    }

    rm->audio_pkt_cnt--;

    if ((pkt->pts = ast->audiotimestamp) != AV_NOPTS_VALUE) {

        ast->audiotimestamp = AV_NOPTS_VALUE;

        pkt->flags = AV_PKT_FLAG_KEY;

    } else

        pkt->flags = 0;

    pkt->stream_index = st->index;



    return rm->audio_pkt_cnt;

}

int av_bsf_send_packet(AVBSFContext *ctx, AVPacket *pkt)

{

    if (!pkt) {

        ctx->internal->eof = 1;

        return 0;

    }



    if (ctx->internal->eof) {

        av_log(ctx, AV_LOG_ERROR, "A non-NULL packet sent after an EOF.\n");

        return AVERROR(EINVAL);

    }



    if (ctx->internal->buffer_pkt->data ||

        ctx->internal->buffer_pkt->side_data_elems)

        return AVERROR(EAGAIN);



    av_packet_move_ref(ctx->internal->buffer_pkt, pkt);



    return 0;

}

static int refresh_thread(void *opaque)

{

    VideoState *is= opaque;

    while (!is->abort_request) {

        SDL_Event event;

        event.type = FF_REFRESH_EVENT;

        event.user.data1 = opaque;

        if (!is->refresh && (!is->paused || is->force_refresh)) {

            is->refresh = 1;

            SDL_PushEvent(&event);

        }

        //FIXME ideally we should wait the correct time but SDLs event passing is so slow it would be silly

        av_usleep(is->audio_st && is->show_mode != SHOW_MODE_VIDEO ? rdftspeed*1000 : 5000);

    }

    return 0;

}

void ff_hpeldsp_init_x86(HpelDSPContext *c, int flags)

{

    int cpu_flags = av_get_cpu_flags();



    if (INLINE_MMX(cpu_flags))

        hpeldsp_init_mmx(c, flags, cpu_flags);



    if (EXTERNAL_MMXEXT(cpu_flags))

        hpeldsp_init_mmxext(c, flags, cpu_flags);



    if (EXTERNAL_AMD3DNOW(cpu_flags))

        hpeldsp_init_3dnow(c, flags, cpu_flags);



    if (EXTERNAL_SSE2(cpu_flags))

        hpeldsp_init_sse2(c, flags, cpu_flags);

}

int av_opt_get(void *obj, const char *name, int search_flags, uint8_t **out_val)

{

    void *dst, *target_obj;

    const AVOption *o = av_opt_find2(obj, name, NULL, 0, search_flags, &target_obj);

    uint8_t *bin, buf[128];

    int len, i, ret;



    if (!o || !target_obj)

        return AVERROR_OPTION_NOT_FOUND;



    dst = (uint8_t*)target_obj + o->offset;



    buf[0] = 0;

    switch (o->type) {

    case AV_OPT_TYPE_FLAGS:     ret = snprintf(buf, sizeof(buf), "0x%08X",  *(int    *)dst);break;

    case AV_OPT_TYPE_INT:       ret = snprintf(buf, sizeof(buf), "%d" ,     *(int    *)dst);break;

    case AV_OPT_TYPE_INT64:     ret = snprintf(buf, sizeof(buf), "%"PRId64, *(int64_t*)dst);break;

    case AV_OPT_TYPE_FLOAT:     ret = snprintf(buf, sizeof(buf), "%f" ,     *(float  *)dst);break;

    case AV_OPT_TYPE_DOUBLE:    ret = snprintf(buf, sizeof(buf), "%f" ,     *(double *)dst);break;

    case AV_OPT_TYPE_RATIONAL:  ret = snprintf(buf, sizeof(buf), "%d/%d",   ((AVRational*)dst)->num, ((AVRational*)dst)->den);break;

    case AV_OPT_TYPE_STRING:

        if (*(uint8_t**)dst)

            *out_val = av_strdup(*(uint8_t**)dst);

        else

            *out_val = av_strdup("");

        return 0;

    case AV_OPT_TYPE_BINARY:

        len = *(int*)(((uint8_t *)dst) + sizeof(uint8_t *));

        if ((uint64_t)len*2 + 1 > INT_MAX)

            return AVERROR(EINVAL);

        if (!(*out_val = av_malloc(len*2 + 1)))

            return AVERROR(ENOMEM);

        bin = *(uint8_t**)dst;

        for (i = 0; i < len; i++)

            snprintf(*out_val + i*2, 3, "%02X", bin[i]);

        return 0;

    default:

        return AVERROR(EINVAL);

    }



    if (ret >= sizeof(buf))

        return AVERROR(EINVAL);

    *out_val = av_strdup(buf);

    return 0;

}

