static inline int RENAME(yuv420_rgb32)(SwsContext *c, uint8_t* src[], int srcStride[], int srcSliceY,

             int srcSliceH, uint8_t* dst[], int dstStride[]){

    int y, h_size;



    if(c->srcFormat == PIX_FMT_YUV422P){

	srcStride[1] *= 2;

	srcStride[2] *= 2;

    }



    h_size= (c->dstW+7)&~7;

    if(h_size*4 > dstStride[0]) h_size-=8;



    __asm__ __volatile__ ("pxor %mm4, %mm4;" /* zero mm4 */ );



    for (y= 0; y<srcSliceH; y++ ) {

	uint8_t *_image = dst[0] + (y+srcSliceY)*dstStride[0];

	uint8_t *_py = src[0] + y*srcStride[0];

	uint8_t *_pu = src[1] + (y>>1)*srcStride[1];

	uint8_t *_pv = src[2] + (y>>1)*srcStride[2];

	long index= -h_size/2;



	    /* this mmx assembly code deals with SINGLE scan line at a time, it convert 8

	       pixels in each iteration */

	    __asm__ __volatile__ (

	/* load data for start of next scan line */

		     "movd (%2, %0), %%mm0;" /* Load 4 Cb 00 00 00 00 u3 u2 u1 u0 */

		     "movd (%3, %0), %%mm1;" /* Load 4 Cr 00 00 00 00 v3 v2 v1 v0 */

		     "movq (%5, %0, 2), %%mm6;" /* Load 8  Y Y7 Y6 Y5 Y4 Y3 Y2 Y1 Y0 */

//		    ".balign 16			\n\t"

		    "1:				\n\t"

YUV2RGB

		     /* convert RGB plane to RGB packed format,

			mm0 -> B, mm1 -> R, mm2 -> G, mm3 -> 0,

			mm4 -> GB, mm5 -> AR pixel 4-7,

			mm6 -> GB, mm7 -> AR pixel 0-3 */

		     "pxor %%mm3, %%mm3;" /* zero mm3 */



		     "movq %%mm0, %%mm6;" /* B7 B6 B5 B4 B3 B2 B1 B0 */

		     "movq %%mm1, %%mm7;" /* R7 R6 R5 R4 R3 R2 R1 R0 */



		     "movq %%mm0, %%mm4;" /* B7 B6 B5 B4 B3 B2 B1 B0 */

		     "movq %%mm1, %%mm5;" /* R7 R6 R5 R4 R3 R2 R1 R0 */



		     "punpcklbw %%mm2, %%mm6;" /* G3 B3 G2 B2 G1 B1 G0 B0 */

		     "punpcklbw %%mm3, %%mm7;" /* 00 R3 00 R2 00 R1 00 R0 */



		     "punpcklwd %%mm7, %%mm6;" /* 00 R1 B1 G1 00 R0 B0 G0 */

		     MOVNTQ " %%mm6, (%1);" /* Store ARGB1 ARGB0 */



		     "movq %%mm0, %%mm6;" /* B7 B6 B5 B4 B3 B2 B1 B0 */

		     "punpcklbw %%mm2, %%mm6;" /* G3 B3 G2 B2 G1 B1 G0 B0 */



		     "punpckhwd %%mm7, %%mm6;" /* 00 R3 G3 B3 00 R2 B3 G2 */

		     MOVNTQ " %%mm6, 8 (%1);" /* Store ARGB3 ARGB2 */



		     "punpckhbw %%mm2, %%mm4;" /* G7 B7 G6 B6 G5 B5 G4 B4 */

		     "punpckhbw %%mm3, %%mm5;" /* 00 R7 00 R6 00 R5 00 R4 */



		     "punpcklwd %%mm5, %%mm4;" /* 00 R5 B5 G5 00 R4 B4 G4 */

		     MOVNTQ " %%mm4, 16 (%1);" /* Store ARGB5 ARGB4 */



		     "movq %%mm0, %%mm4;" /* B7 B6 B5 B4 B3 B2 B1 B0 */

		     "punpckhbw %%mm2, %%mm4;" /* G7 B7 G6 B6 G5 B5 G4 B4 */



		     "punpckhwd %%mm5, %%mm4;" /* 00 R7 G7 B7 00 R6 B6 G6 */

		     MOVNTQ " %%mm4, 24 (%1);" /* Store ARGB7 ARGB6 */



		     "movd 4 (%2, %0), %%mm0;" /* Load 4 Cb 00 00 00 00 u3 u2 u1 u0 */

		     "movd 4 (%3, %0), %%mm1;" /* Load 4 Cr 00 00 00 00 v3 v2 v1 v0 */



		     "pxor %%mm4, %%mm4;" /* zero mm4 */

		     "movq 8 (%5, %0, 2), %%mm6;" /* Load 8 Y Y7 Y6 Y5 Y4 Y3 Y2 Y1 Y0 */



		     "add $32, %1			\n\t"

		     "add $4, %0			\n\t"

		     " js 1b				\n\t"



		     : "+r" (index), "+r" (_image)

		     : "r" (_pu - index), "r" (_pv - index), "r"(&c->redDither), "r" (_py - 2*index)

		     );

    }



    __asm__ __volatile__ (EMMS);

    return srcSliceH;

}

static int oggvorbis_decode_init(AVCodecContext *avccontext) {

    OggVorbisDecContext *context = avccontext->priv_data ;

    uint8_t *p= avccontext->extradata;

    int i, hsizes[3];

    unsigned char *headers[3], *extradata = avccontext->extradata;



    vorbis_info_init(&context->vi) ;

    vorbis_comment_init(&context->vc) ;



    if(! avccontext->extradata_size || ! p) {

        av_log(avccontext, AV_LOG_ERROR, "vorbis extradata absent\n");

        return -1;

    }



    if(p[0] == 0 && p[1] == 30) {

        for(i = 0; i < 3; i++){

            hsizes[i] = bytestream_get_be16((const uint8_t **)&p);

            headers[i] = p;

            p += hsizes[i];

        }

    } else if(*p == 2) {

        unsigned int offset = 1;

        p++;

        for(i=0; i<2; i++) {

            hsizes[i] = 0;

            while((*p == 0xFF) && (offset < avccontext->extradata_size)) {

                hsizes[i] += 0xFF;

                offset++;

                p++;

            }

            if(offset >= avccontext->extradata_size - 1) {

                av_log(avccontext, AV_LOG_ERROR,

                       "vorbis header sizes damaged\n");

                return -1;

            }

            hsizes[i] += *p;

            offset++;

            p++;

        }

        hsizes[2] = avccontext->extradata_size - hsizes[0]-hsizes[1]-offset;

#if 0

        av_log(avccontext, AV_LOG_DEBUG,

               "vorbis header sizes: %d, %d, %d, / extradata_len is %d \n",

               hsizes[0], hsizes[1], hsizes[2], avccontext->extradata_size);

#endif

        headers[0] = extradata + offset;

        headers[1] = extradata + offset + hsizes[0];

        headers[2] = extradata + offset + hsizes[0] + hsizes[1];

    } else {

        av_log(avccontext, AV_LOG_ERROR,

               "vorbis initial header len is wrong: %d\n", *p);

        return -1;

    }



    for(i=0; i<3; i++){

        context->op.b_o_s= i==0;

        context->op.bytes = hsizes[i];

        context->op.packet = headers[i];

        if(vorbis_synthesis_headerin(&context->vi, &context->vc, &context->op)<0){

            av_log(avccontext, AV_LOG_ERROR, "%d. vorbis header damaged\n", i+1);

            return -1;

        }

    }



    avccontext->channels = context->vi.channels;

    avccontext->sample_rate = context->vi.rate;

    avccontext->sample_fmt = AV_SAMPLE_FMT_S16;

    avccontext->time_base= (AVRational){1, avccontext->sample_rate};



    vorbis_synthesis_init(&context->vd, &context->vi);

    vorbis_block_init(&context->vd, &context->vb);



    return 0 ;

}

yuv2rgb48_2_c_template(SwsContext *c, const int32_t *buf[2],

                       const int32_t *ubuf[2], const int32_t *vbuf[2],

                       const int32_t *abuf[2], uint16_t *dest, int dstW,

                       int yalpha, int uvalpha, int y,

                       enum AVPixelFormat target)

{

    const int32_t *buf0  = buf[0],  *buf1  = buf[1],

                  *ubuf0 = ubuf[0], *ubuf1 = ubuf[1],

                  *vbuf0 = vbuf[0], *vbuf1 = vbuf[1];

    int  yalpha1 = 4096 - yalpha;

    int uvalpha1 = 4096 - uvalpha;

    int i;



    for (i = 0; i < ((dstW + 1) >> 1); i++) {

        int Y1 = (buf0[i * 2]     * yalpha1  + buf1[i * 2]     * yalpha) >> 14;

        int Y2 = (buf0[i * 2 + 1] * yalpha1  + buf1[i * 2 + 1] * yalpha) >> 14;

        int U  = (ubuf0[i]        * uvalpha1 + ubuf1[i]        * uvalpha + (-128 << 23)) >> 14;

        int V  = (vbuf0[i]        * uvalpha1 + vbuf1[i]        * uvalpha + (-128 << 23)) >> 14;

        int R, G, B;



        Y1 -= c->yuv2rgb_y_offset;

        Y2 -= c->yuv2rgb_y_offset;

        Y1 *= c->yuv2rgb_y_coeff;

        Y2 *= c->yuv2rgb_y_coeff;

        Y1 += 1 << 13;

        Y2 += 1 << 13;



        R = V * c->yuv2rgb_v2r_coeff;

        G = V * c->yuv2rgb_v2g_coeff + U * c->yuv2rgb_u2g_coeff;

        B =                            U * c->yuv2rgb_u2b_coeff;



        output_pixel(&dest[0], av_clip_uintp2(R_B + Y1, 30) >> 14);

        output_pixel(&dest[1], av_clip_uintp2(  G + Y1, 30) >> 14);

        output_pixel(&dest[2], av_clip_uintp2(B_R + Y1, 30) >> 14);

        output_pixel(&dest[3], av_clip_uintp2(R_B + Y2, 30) >> 14);

        output_pixel(&dest[4], av_clip_uintp2(  G + Y2, 30) >> 14);

        output_pixel(&dest[5], av_clip_uintp2(B_R + Y2, 30) >> 14);

        dest += 6;

    }

}

static void filter_mb( H264Context *h, int mb_x, int mb_y, uint8_t *img_y, uint8_t *img_cb, uint8_t *img_cr, unsigned int linesize, unsigned int uvlinesize) {

    MpegEncContext * const s = &h->s;

    const int mb_xy= mb_x + mb_y*s->mb_stride;

    const int mb_type = s->current_picture.mb_type[mb_xy];

    const int mvy_limit = IS_INTERLACED(mb_type) ? 2 : 4;

    int first_vertical_edge_done = 0;

    int dir;



    //for sufficiently low qp, filtering wouldn't do anything

    //this is a conservative estimate: could also check beta_offset and more accurate chroma_qp

    if(!FRAME_MBAFF){

        int qp_thresh = 15 - h->slice_alpha_c0_offset - FFMAX3(0, h->pps.chroma_qp_index_offset[0], h->pps.chroma_qp_index_offset[1]);

        int qp = s->current_picture.qscale_table[mb_xy];

        if(qp <= qp_thresh

           && (mb_x == 0 || ((qp + s->current_picture.qscale_table[mb_xy-1] + 1)>>1) <= qp_thresh)

           && (mb_y == 0 || ((qp + s->current_picture.qscale_table[h->top_mb_xy] + 1)>>1) <= qp_thresh)){

            return;

        }

    }



    if (FRAME_MBAFF

            // left mb is in picture

            && h->slice_table[mb_xy-1] != 255

            // and current and left pair do not have the same interlaced type

            && (IS_INTERLACED(mb_type) != IS_INTERLACED(s->current_picture.mb_type[mb_xy-1]))

            // and left mb is in the same slice if deblocking_filter == 2

            && (h->deblocking_filter!=2 || h->slice_table[mb_xy-1] == h->slice_table[mb_xy])) {

        /* First vertical edge is different in MBAFF frames

         * There are 8 different bS to compute and 2 different Qp

         */

        const int pair_xy = mb_x + (mb_y&~1)*s->mb_stride;

        const int left_mb_xy[2] = { pair_xy-1, pair_xy-1+s->mb_stride };

        int16_t bS[8];

        int qp[2];

        int bqp[2];

        int rqp[2];

        int mb_qp, mbn0_qp, mbn1_qp;

        int i;

        first_vertical_edge_done = 1;



        if( IS_INTRA(mb_type) )

            bS[0] = bS[1] = bS[2] = bS[3] = bS[4] = bS[5] = bS[6] = bS[7] = 4;

        else {

            for( i = 0; i < 8; i++ ) {

                int mbn_xy = MB_FIELD ? left_mb_xy[i>>2] : left_mb_xy[i&1];



                if( IS_INTRA( s->current_picture.mb_type[mbn_xy] ) )

                    bS[i] = 4;

                else if( h->non_zero_count_cache[12+8*(i>>1)] != 0 ||

                         /* FIXME: with 8x8dct + cavlc, should check cbp instead of nnz */

                         h->non_zero_count[mbn_xy][MB_FIELD ? i&3 : (i>>2)+(mb_y&1)*2] )

                    bS[i] = 2;

                else

                    bS[i] = 1;

            }

        }



        mb_qp = s->current_picture.qscale_table[mb_xy];

        mbn0_qp = s->current_picture.qscale_table[left_mb_xy[0]];

        mbn1_qp = s->current_picture.qscale_table[left_mb_xy[1]];

        qp[0] = ( mb_qp + mbn0_qp + 1 ) >> 1;

        bqp[0] = ( get_chroma_qp( h, 0, mb_qp ) +

                   get_chroma_qp( h, 0, mbn0_qp ) + 1 ) >> 1;

        rqp[0] = ( get_chroma_qp( h, 1, mb_qp ) +

                   get_chroma_qp( h, 1, mbn0_qp ) + 1 ) >> 1;

        qp[1] = ( mb_qp + mbn1_qp + 1 ) >> 1;

        bqp[1] = ( get_chroma_qp( h, 0, mb_qp ) +

                   get_chroma_qp( h, 0, mbn1_qp ) + 1 ) >> 1;

        rqp[1] = ( get_chroma_qp( h, 1, mb_qp ) +

                   get_chroma_qp( h, 1, mbn1_qp ) + 1 ) >> 1;



        /* Filter edge */

        tprintf(s->avctx, "filter mb:%d/%d MBAFF, QPy:%d/%d, QPb:%d/%d QPr:%d/%d ls:%d uvls:%d", mb_x, mb_y, qp[0], qp[1], bqp[0], bqp[1], rqp[0], rqp[1], linesize, uvlinesize);

        { int i; for (i = 0; i < 8; i++) tprintf(s->avctx, " bS[%d]:%d", i, bS[i]); tprintf(s->avctx, "\n"); }

        filter_mb_mbaff_edgev ( h, &img_y [0], linesize,   bS, qp );

        filter_mb_mbaff_edgecv( h, &img_cb[0], uvlinesize, bS, bqp );

        filter_mb_mbaff_edgecv( h, &img_cr[0], uvlinesize, bS, rqp );

    }

    /* dir : 0 -> vertical edge, 1 -> horizontal edge */

    for( dir = 0; dir < 2; dir++ )

    {

        int edge;

        const int mbm_xy = dir == 0 ? mb_xy -1 : h->top_mb_xy;

        const int mbm_type = s->current_picture.mb_type[mbm_xy];

        int start = h->slice_table[mbm_xy] == 255 ? 1 : 0;



        const int edges = (mb_type & (MB_TYPE_16x16|MB_TYPE_SKIP))

                                  == (MB_TYPE_16x16|MB_TYPE_SKIP) ? 1 : 4;

        // how often to recheck mv-based bS when iterating between edges

        const int mask_edge = (mb_type & (MB_TYPE_16x16 | (MB_TYPE_16x8 << dir))) ? 3 :

                              (mb_type & (MB_TYPE_8x16 >> dir)) ? 1 : 0;

        // how often to recheck mv-based bS when iterating along each edge

        const int mask_par0 = mb_type & (MB_TYPE_16x16 | (MB_TYPE_8x16 >> dir));



        if (first_vertical_edge_done) {

            start = 1;

            first_vertical_edge_done = 0;

        }



        if (h->deblocking_filter==2 && h->slice_table[mbm_xy] != h->slice_table[mb_xy])

            start = 1;



        if (FRAME_MBAFF && (dir == 1) && ((mb_y&1) == 0) && start == 0

            && !IS_INTERLACED(mb_type)

            && IS_INTERLACED(mbm_type)

            ) {

            // This is a special case in the norm where the filtering must

            // be done twice (one each of the field) even if we are in a

            // frame macroblock.

            //

            static const int nnz_idx[4] = {4,5,6,3};

            unsigned int tmp_linesize   = 2 *   linesize;

            unsigned int tmp_uvlinesize = 2 * uvlinesize;

            int mbn_xy = mb_xy - 2 * s->mb_stride;

            int qp;

            int i, j;

            int16_t bS[4];



            for(j=0; j<2; j++, mbn_xy += s->mb_stride){

                if( IS_INTRA(mb_type) ||

                    IS_INTRA(s->current_picture.mb_type[mbn_xy]) ) {

                    bS[0] = bS[1] = bS[2] = bS[3] = 3;

                } else {

                    const uint8_t *mbn_nnz = h->non_zero_count[mbn_xy];

                    for( i = 0; i < 4; i++ ) {

                        if( h->non_zero_count_cache[scan8[0]+i] != 0 ||

                            mbn_nnz[nnz_idx[i]] != 0 )

                            bS[i] = 2;

                        else

                            bS[i] = 1;

                    }

                }

                // Do not use s->qscale as luma quantizer because it has not the same

                // value in IPCM macroblocks.

                qp = ( s->current_picture.qscale_table[mb_xy] + s->current_picture.qscale_table[mbn_xy] + 1 ) >> 1;

                tprintf(s->avctx, "filter mb:%d/%d dir:%d edge:%d, QPy:%d ls:%d uvls:%d", mb_x, mb_y, dir, edge, qp, tmp_linesize, tmp_uvlinesize);

                { int i; for (i = 0; i < 4; i++) tprintf(s->avctx, " bS[%d]:%d", i, bS[i]); tprintf(s->avctx, "\n"); }

                filter_mb_edgeh( h, &img_y[j*linesize], tmp_linesize, bS, qp );

                filter_mb_edgech( h, &img_cb[j*uvlinesize], tmp_uvlinesize, bS,

                                  ( h->chroma_qp[0] + get_chroma_qp( h, 0, s->current_picture.qscale_table[mbn_xy] ) + 1 ) >> 1);

                filter_mb_edgech( h, &img_cr[j*uvlinesize], tmp_uvlinesize, bS,

                                  ( h->chroma_qp[1] + get_chroma_qp( h, 1, s->current_picture.qscale_table[mbn_xy] ) + 1 ) >> 1);

            }



            start = 1;

        }



        /* Calculate bS */

        for( edge = start; edge < edges; edge++ ) {

            /* mbn_xy: neighbor macroblock */

            const int mbn_xy = edge > 0 ? mb_xy : mbm_xy;

            const int mbn_type = s->current_picture.mb_type[mbn_xy];

            int16_t bS[4];

            int qp;



            if( (edge&1) && IS_8x8DCT(mb_type) )

                continue;



            if( IS_INTRA(mb_type) ||

                IS_INTRA(mbn_type) ) {

                int value;

                if (edge == 0) {

                    if (   (!IS_INTERLACED(mb_type) && !IS_INTERLACED(mbm_type))

                        || ((FRAME_MBAFF || (s->picture_structure != PICT_FRAME)) && (dir == 0))

                    ) {

                        value = 4;

                    } else {

                        value = 3;

                    }

                } else {

                    value = 3;

                }

                bS[0] = bS[1] = bS[2] = bS[3] = value;

            } else {

                int i, l;

                int mv_done;



                if( edge & mask_edge ) {

                    bS[0] = bS[1] = bS[2] = bS[3] = 0;

                    mv_done = 1;

                }

                else if( FRAME_MBAFF && IS_INTERLACED(mb_type ^ mbn_type)) {

                    bS[0] = bS[1] = bS[2] = bS[3] = 1;

                    mv_done = 1;

                }

                else if( mask_par0 && (edge || (mbn_type & (MB_TYPE_16x16 | (MB_TYPE_8x16 >> dir)))) ) {

                    int b_idx= 8 + 4 + edge * (dir ? 8:1);

                    int bn_idx= b_idx - (dir ? 8:1);

                    int v = 0;

                    int xn= h->slice_type_nos == FF_B_TYPE && h->ref2frm[0][h->ref_cache[0][b_idx]+2] != h->ref2frm[0][h->ref_cache[0][bn_idx]+2];



                    for( l = 0; !v && l < 1 + (h->slice_type_nos == FF_B_TYPE); l++ ) {

                        int ln= l^xn;

                        v |= h->ref2frm[l][h->ref_cache[l][b_idx]+2] != h->ref2frm[ln][h->ref_cache[ln][bn_idx]+2] ||

                             FFABS( h->mv_cache[l][b_idx][0] - h->mv_cache[ln][bn_idx][0] ) >= 4 ||

                             FFABS( h->mv_cache[l][b_idx][1] - h->mv_cache[ln][bn_idx][1] ) >= mvy_limit;

                    }

                    bS[0] = bS[1] = bS[2] = bS[3] = v;

                    mv_done = 1;

                }

                else

                    mv_done = 0;



                for( i = 0; i < 4; i++ ) {

                    int x = dir == 0 ? edge : i;

                    int y = dir == 0 ? i    : edge;

                    int b_idx= 8 + 4 + x + 8*y;

                    int bn_idx= b_idx - (dir ? 8:1);



                    if( h->non_zero_count_cache[b_idx] != 0 ||

                        h->non_zero_count_cache[bn_idx] != 0 ) {

                        bS[i] = 2;

                    }

                    else if(!mv_done)

                    {

                        int xn= h->slice_type_nos == FF_B_TYPE && h->ref2frm[0][h->ref_cache[0][b_idx]+2] != h->ref2frm[0][h->ref_cache[0][bn_idx]+2];

                        bS[i] = 0;

                        for( l = 0; l < 1 + (h->slice_type_nos == FF_B_TYPE); l++ ) {

                            int ln= l^xn;

                            if( h->ref2frm[l][h->ref_cache[l][b_idx]+2] != h->ref2frm[ln][h->ref_cache[ln][bn_idx]+2] ||

                                FFABS( h->mv_cache[l][b_idx][0] - h->mv_cache[ln][bn_idx][0] ) >= 4 ||

                                FFABS( h->mv_cache[l][b_idx][1] - h->mv_cache[ln][bn_idx][1] ) >= mvy_limit ) {

                                bS[i] = 1;

                                break;

                            }

                        }

                    }

                }



                if(bS[0]+bS[1]+bS[2]+bS[3] == 0)

                    continue;

            }



            /* Filter edge */

            // Do not use s->qscale as luma quantizer because it has not the same

            // value in IPCM macroblocks.

            qp = ( s->current_picture.qscale_table[mb_xy] + s->current_picture.qscale_table[mbn_xy] + 1 ) >> 1;

            //tprintf(s->avctx, "filter mb:%d/%d dir:%d edge:%d, QPy:%d, QPc:%d, QPcn:%d\n", mb_x, mb_y, dir, edge, qp, h->chroma_qp, s->current_picture.qscale_table[mbn_xy]);

            tprintf(s->avctx, "filter mb:%d/%d dir:%d edge:%d, QPy:%d ls:%d uvls:%d", mb_x, mb_y, dir, edge, qp, linesize, uvlinesize);

            { int i; for (i = 0; i < 4; i++) tprintf(s->avctx, " bS[%d]:%d", i, bS[i]); tprintf(s->avctx, "\n"); }

            if( dir == 0 ) {

                filter_mb_edgev( h, &img_y[4*edge], linesize, bS, qp );

                if( (edge&1) == 0 ) {

                    filter_mb_edgecv( h, &img_cb[2*edge], uvlinesize, bS,

                                      ( h->chroma_qp[0] + get_chroma_qp( h, 0, s->current_picture.qscale_table[mbn_xy] ) + 1 ) >> 1);

                    filter_mb_edgecv( h, &img_cr[2*edge], uvlinesize, bS,

                                      ( h->chroma_qp[1] + get_chroma_qp( h, 1, s->current_picture.qscale_table[mbn_xy] ) + 1 ) >> 1);

                }

            } else {

                filter_mb_edgeh( h, &img_y[4*edge*linesize], linesize, bS, qp );

                if( (edge&1) == 0 ) {

                    filter_mb_edgech( h, &img_cb[2*edge*uvlinesize], uvlinesize, bS,

                                      ( h->chroma_qp[0] + get_chroma_qp( h, 0, s->current_picture.qscale_table[mbn_xy] ) + 1 ) >> 1);

                    filter_mb_edgech( h, &img_cr[2*edge*uvlinesize], uvlinesize, bS,

                                      ( h->chroma_qp[1] + get_chroma_qp( h, 1, s->current_picture.qscale_table[mbn_xy] ) + 1 ) >> 1);

                }

            }

        }

    }

}

static int twolame_encode_frame(AVCodecContext *avctx, AVPacket *avpkt,

                                const AVFrame *frame, int *got_packet_ptr)

{

    TWOLAMEContext *s = avctx->priv_data;

    int ret;



    if ((ret = ff_alloc_packet(avpkt, MPA_MAX_CODED_FRAME_SIZE)) < 0)

        return ret;



    if (frame) {

        switch (avctx->sample_fmt) {

        case AV_SAMPLE_FMT_FLT:

            ret = twolame_encode_buffer_float32_interleaved(s->glopts,

                                                            (const float *)frame->data[0],

                                                            frame->nb_samples,

                                                            avpkt->data,

                                                            avpkt->size);

            break;

        case AV_SAMPLE_FMT_FLTP:

            ret = twolame_encode_buffer_float32(s->glopts,

                                                (const float *)frame->data[0],

                                                (const float *)frame->data[1],

                                                frame->nb_samples,

                                                avpkt->data, avpkt->size);

            break;

        case AV_SAMPLE_FMT_S16:

            ret = twolame_encode_buffer_interleaved(s->glopts,

                                                    (const short int *)frame->data[0],

                                                    frame->nb_samples,

                                                    avpkt->data, avpkt->size);

            break;

        case AV_SAMPLE_FMT_S16P:

            ret = twolame_encode_buffer(s->glopts,

                                        (const short int *)frame->data[0],

                                        (const short int *)frame->data[1],

                                        frame->nb_samples,

                                        avpkt->data, avpkt->size);

            break;

        default:

            av_log(avctx, AV_LOG_ERROR,

                   "Unsupported sample format %d.\n", avctx->sample_fmt);

            return AVERROR_BUG;

        }

    } else {

        ret = twolame_encode_flush(s->glopts, avpkt->data, avpkt->size);

    }



    if (!ret)     // no bytes written

        return 0;

    if (ret < 0)  // twolame error

        return AVERROR_UNKNOWN;



    avpkt->duration = ff_samples_to_time_base(avctx, frame->nb_samples);

    if (frame) {

        if (frame->pts != AV_NOPTS_VALUE)

            avpkt->pts = frame->pts - ff_samples_to_time_base(avctx, avctx->delay);

    } else {

        avpkt->pts = s->next_pts;

    }

    // this is for setting pts for flushed packet(s).

    if (avpkt->pts != AV_NOPTS_VALUE)

        s->next_pts = avpkt->pts + avpkt->duration;



    av_shrink_packet(avpkt, ret);

    *got_packet_ptr = 1;

    return 0;

}

av_cold void ff_vc1dsp_init_x86(VC1DSPContext *dsp)

{

    int cpu_flags = av_get_cpu_flags();



    if (INLINE_MMX(cpu_flags))

        ff_vc1dsp_init_mmx(dsp);



    if (INLINE_MMXEXT(cpu_flags))

        ff_vc1dsp_init_mmxext(dsp);



#define ASSIGN_LF(EXT) \

        dsp->vc1_v_loop_filter4  = ff_vc1_v_loop_filter4_ ## EXT; \

        dsp->vc1_h_loop_filter4  = ff_vc1_h_loop_filter4_ ## EXT; \

        dsp->vc1_v_loop_filter8  = ff_vc1_v_loop_filter8_ ## EXT; \

        dsp->vc1_h_loop_filter8  = ff_vc1_h_loop_filter8_ ## EXT; \

        dsp->vc1_v_loop_filter16 = vc1_v_loop_filter16_ ## EXT; \

        dsp->vc1_h_loop_filter16 = vc1_h_loop_filter16_ ## EXT



#if HAVE_YASM

    if (cpu_flags & AV_CPU_FLAG_MMX) {

        dsp->put_no_rnd_vc1_chroma_pixels_tab[0] = ff_put_vc1_chroma_mc8_nornd_mmx;

    }



    if (cpu_flags & AV_CPU_FLAG_MMXEXT) {

        ASSIGN_LF(mmxext);

        dsp->avg_no_rnd_vc1_chroma_pixels_tab[0] = ff_avg_vc1_chroma_mc8_nornd_mmxext;



        dsp->avg_vc1_mspel_pixels_tab[0]         = avg_vc1_mspel_mc00_mmxext;

    } else if (cpu_flags & AV_CPU_FLAG_3DNOW) {

        dsp->avg_no_rnd_vc1_chroma_pixels_tab[0] = ff_avg_vc1_chroma_mc8_nornd_3dnow;

    }



    if (cpu_flags & AV_CPU_FLAG_SSE2) {

        dsp->vc1_v_loop_filter8  = ff_vc1_v_loop_filter8_sse2;

        dsp->vc1_h_loop_filter8  = ff_vc1_h_loop_filter8_sse2;

        dsp->vc1_v_loop_filter16 = vc1_v_loop_filter16_sse2;

        dsp->vc1_h_loop_filter16 = vc1_h_loop_filter16_sse2;

    }

    if (cpu_flags & AV_CPU_FLAG_SSSE3) {

        ASSIGN_LF(ssse3);

        dsp->put_no_rnd_vc1_chroma_pixels_tab[0] = ff_put_vc1_chroma_mc8_nornd_ssse3;

        dsp->avg_no_rnd_vc1_chroma_pixels_tab[0] = ff_avg_vc1_chroma_mc8_nornd_ssse3;

    }

    if (cpu_flags & AV_CPU_FLAG_SSE4) {

        dsp->vc1_h_loop_filter8  = ff_vc1_h_loop_filter8_sse4;

        dsp->vc1_h_loop_filter16 = vc1_h_loop_filter16_sse4;

    }

#endif /* HAVE_YASM */

}

static int resample(ResampleContext *c, void *dst, const void *src,

                    int *consumed, int src_size, int dst_size, int update_ctx,

                    int nearest_neighbour)

{

    int dst_index;

    int index         = c->index;

    int frac          = c->frac;

    int dst_incr_frac = c->dst_incr % c->src_incr;

    int dst_incr      = c->dst_incr / c->src_incr;

    int compensation_distance = c->compensation_distance;



    if (!dst != !src)

        return AVERROR(EINVAL);



    if (nearest_neighbour) {

        int64_t index2 = ((int64_t)index) << 32;

        int64_t incr   = (1LL << 32) * c->dst_incr / c->src_incr;

        dst_size       = FFMIN(dst_size,

                               (src_size-1-index) * (int64_t)c->src_incr /

                               c->dst_incr);



        if (dst) {

            for(dst_index = 0; dst_index < dst_size; dst_index++) {

                c->resample_nearest(dst, dst_index, src, index2 >> 32);

                index2 += incr;

            }

        } else {

            dst_index = dst_size;

        }

        index += dst_index * dst_incr;

        index += (frac + dst_index * (int64_t)dst_incr_frac) / c->src_incr;

        frac   = (frac + dst_index * (int64_t)dst_incr_frac) % c->src_incr;

    } else {

        for (dst_index = 0; dst_index < dst_size; dst_index++) {

            int sample_index = index >> c->phase_shift;



            if (sample_index + c->filter_length > src_size ||

                -sample_index >= src_size)

                break;



            if (dst)

                c->resample_one(c, dst, dst_index, src, src_size, index, frac);



            frac  += dst_incr_frac;

            index += dst_incr;

            if (frac >= c->src_incr) {

                frac -= c->src_incr;

                index++;

            }

            if (dst_index + 1 == compensation_distance) {

                compensation_distance = 0;

                dst_incr_frac = c->ideal_dst_incr % c->src_incr;

                dst_incr      = c->ideal_dst_incr / c->src_incr;

            }

        }

    }

    if (consumed)

        *consumed = FFMAX(index, 0) >> c->phase_shift;



    if (update_ctx) {

        if (index >= 0)

            index &= c->phase_mask;



        if (compensation_distance) {

            compensation_distance -= dst_index;

            if (compensation_distance <= 0)

                return AVERROR_BUG;

        }

        c->frac     = frac;

        c->index    = index;

        c->dst_incr = dst_incr_frac + c->src_incr*dst_incr;

        c->compensation_distance = compensation_distance;

    }



    return dst_index;

}

static av_always_inline int dnxhd_decode_dct_block(const DNXHDContext *ctx,

                                                   RowContext *row,

                                                   int n,

                                                   int index_bits,

                                                   int level_bias,

                                                   int level_shift,

                                                   int dc_shift)

{

    int i, j, index1, index2, len, flags;

    int level, component, sign;

    const int *scale;

    const uint8_t *weight_matrix;

    const uint8_t *ac_info = ctx->cid_table->ac_info;

    int16_t *block = row->blocks[n];

    const int eob_index     = ctx->cid_table->eob_index;

    int ret = 0;

    OPEN_READER(bs, &row->gb);



    ctx->bdsp.clear_block(block);



    if (!ctx->is_444) {

        if (n & 2) {

            component     = 1 + (n & 1);

            scale = row->chroma_scale;

            weight_matrix = ctx->cid_table->chroma_weight;

        } else {

            component     = 0;

            scale = row->luma_scale;

            weight_matrix = ctx->cid_table->luma_weight;

        }

    } else {

        component = (n >> 1) % 3;

        if (component) {

            scale = row->chroma_scale;

            weight_matrix = ctx->cid_table->chroma_weight;

        } else {

            scale = row->luma_scale;

            weight_matrix = ctx->cid_table->luma_weight;

        }

    }



    UPDATE_CACHE(bs, &row->gb);

    GET_VLC(len, bs, &row->gb, ctx->dc_vlc.table, DNXHD_DC_VLC_BITS, 1);

    if (len) {

        level = GET_CACHE(bs, &row->gb);

        LAST_SKIP_BITS(bs, &row->gb, len);

        sign  = ~level >> 31;

        level = (NEG_USR32(sign ^ level, len) ^ sign) - sign;

        row->last_dc[component] += level << dc_shift;

    }

    block[0] = row->last_dc[component];



    i = 0;



    UPDATE_CACHE(bs, &row->gb);

    GET_VLC(index1, bs, &row->gb, ctx->ac_vlc.table,

            DNXHD_VLC_BITS, 2);



    while (index1 != eob_index) {

        level = ac_info[2*index1+0];

        flags = ac_info[2*index1+1];



        sign = SHOW_SBITS(bs, &row->gb, 1);

        SKIP_BITS(bs, &row->gb, 1);



        if (flags & 1) {

            level += SHOW_UBITS(bs, &row->gb, index_bits) << 7;

            SKIP_BITS(bs, &row->gb, index_bits);

        }



        if (flags & 2) {

            UPDATE_CACHE(bs, &row->gb);

            GET_VLC(index2, bs, &row->gb, ctx->run_vlc.table,

                    DNXHD_VLC_BITS, 2);

            i += ctx->cid_table->run[index2];

        }



        if (++i > 63) {

            av_log(ctx->avctx, AV_LOG_ERROR, "ac tex damaged %d, %d\n", n, i);

            ret = -1;

            break;

        }



        j     = ctx->scantable.permutated[i];

        level *= scale[i];

        level += scale[i] >> 1;

        if (level_bias < 32 || weight_matrix[i] != level_bias)

            level += level_bias; // 1<<(level_shift-1)

        level >>= level_shift;



        block[j] = (level ^ sign) - sign;



        UPDATE_CACHE(bs, &row->gb);

        GET_VLC(index1, bs, &row->gb, ctx->ac_vlc.table,

                DNXHD_VLC_BITS, 2);

    }



    CLOSE_READER(bs, &row->gb);

    return ret;

}

static enum AVPixelFormat webp_get_format(AVCodecContext *avctx,

                                          const enum AVPixelFormat *formats)

{

    WebPContext *s = avctx->priv_data;

    if (s->has_alpha)

        return AV_PIX_FMT_YUVA420P;

    else

        return AV_PIX_FMT_YUV420P;

}

static void coded_frame_add(void *list, struct FrameListData *cx_frame)

{

    struct FrameListData **p = list;



    while (*p != NULL)

        p = &(*p)->next;

    *p = cx_frame;

    cx_frame->next = NULL;

}

void swri_resample_dsp_x86_init(ResampleContext *c)

{

    int av_unused mm_flags = av_get_cpu_flags();



    switch(c->format){

    case AV_SAMPLE_FMT_S16P:

        if (ARCH_X86_32 && HAVE_MMXEXT_EXTERNAL && mm_flags & AV_CPU_FLAG_MMX2) {

            c->dsp.resample = c->linear ? ff_resample_linear_int16_mmxext

                                        : ff_resample_common_int16_mmxext;

        }

        if (HAVE_SSE2_EXTERNAL && mm_flags & AV_CPU_FLAG_SSE2) {

            c->dsp.resample = c->linear ? ff_resample_linear_int16_sse2

                                        : ff_resample_common_int16_sse2;

        }

        if (HAVE_XOP_EXTERNAL && mm_flags & AV_CPU_FLAG_XOP) {

            c->dsp.resample = c->linear ? ff_resample_linear_int16_xop

                                        : ff_resample_common_int16_xop;

        }

        break;

    case AV_SAMPLE_FMT_FLTP:

        if (HAVE_SSE_EXTERNAL && mm_flags & AV_CPU_FLAG_SSE) {

            c->dsp.resample = c->linear ? ff_resample_linear_float_sse

                                        : ff_resample_common_float_sse;

        }

        if (HAVE_AVX_EXTERNAL && mm_flags & AV_CPU_FLAG_AVX) {

            c->dsp.resample = c->linear ? ff_resample_linear_float_avx

                                        : ff_resample_common_float_avx;

        }

        if (HAVE_FMA3_EXTERNAL && mm_flags & AV_CPU_FLAG_FMA3) {

            c->dsp.resample = c->linear ? ff_resample_linear_float_fma3

                                        : ff_resample_common_float_fma3;

        }

        if (HAVE_FMA4_EXTERNAL && mm_flags & AV_CPU_FLAG_FMA4) {

            c->dsp.resample = c->linear ? ff_resample_linear_float_fma4

                                        : ff_resample_common_float_fma4;

        }

        break;

    case AV_SAMPLE_FMT_DBLP:

        if (HAVE_SSE2_EXTERNAL && mm_flags & AV_CPU_FLAG_SSE2) {

            c->dsp.resample = c->linear ? ff_resample_linear_double_sse2

                                        : ff_resample_common_double_sse2;

        }

        break;

    }

}

static inline int coef_test_compression(int coef)

{

    int tmp = coef >> 2;

    int res = ff_ctz(tmp);

    if (res > 1)

        return 1;       /* ...00 ->  compressable    */

    else if (res == 1)

        return 0;       /* ...10 ->  uncompressable  */

    else if (ff_ctz(tmp >> 1) > 0)

        return 0;       /* ...0 1 -> uncompressable  */

    else

        return 1;       /* ...1 1 -> compressable    */

}

void ff_get_unscaled_swscale(SwsContext *c)

{

    const enum PixelFormat srcFormat = c->srcFormat;

    const enum PixelFormat dstFormat = c->dstFormat;

    const int flags = c->flags;

    const int dstH = c->dstH;

    int needsDither;



    needsDither= isAnyRGB(dstFormat)

        &&  c->dstFormatBpp < 24

        && (c->dstFormatBpp < c->srcFormatBpp || (!isAnyRGB(srcFormat)));



    /* yv12_to_nv12 */

    if ((srcFormat == PIX_FMT_YUV420P || srcFormat == PIX_FMT_YUVA420P) && (dstFormat == PIX_FMT_NV12 || dstFormat == PIX_FMT_NV21)) {

        c->swScale= planarToNv12Wrapper;

    }

    /* yuv2bgr */

    if ((srcFormat==PIX_FMT_YUV420P || srcFormat==PIX_FMT_YUV422P || srcFormat==PIX_FMT_YUVA420P) && isAnyRGB(dstFormat)

        && !(flags & SWS_ACCURATE_RND) && !(dstH&1)) {

        c->swScale= ff_yuv2rgb_get_func_ptr(c);

    }



    if (srcFormat==PIX_FMT_YUV410P && (dstFormat==PIX_FMT_YUV420P || dstFormat==PIX_FMT_YUVA420P) && !(flags & SWS_BITEXACT)) {

        c->swScale= yvu9ToYv12Wrapper;

    }



    /* bgr24toYV12 */

    if (srcFormat==PIX_FMT_BGR24 && (dstFormat==PIX_FMT_YUV420P || dstFormat==PIX_FMT_YUVA420P) && !(flags & SWS_ACCURATE_RND))

        c->swScale= bgr24ToYv12Wrapper;



    /* RGB/BGR -> RGB/BGR (no dither needed forms) */

    if (   isAnyRGB(srcFormat)

        && isAnyRGB(dstFormat)

        && srcFormat != PIX_FMT_BGR8      && dstFormat != PIX_FMT_BGR8

        && srcFormat != PIX_FMT_RGB8      && dstFormat != PIX_FMT_RGB8

        && srcFormat != PIX_FMT_BGR4      && dstFormat != PIX_FMT_BGR4

        && srcFormat != PIX_FMT_RGB4      && dstFormat != PIX_FMT_RGB4

        && srcFormat != PIX_FMT_BGR4_BYTE && dstFormat != PIX_FMT_BGR4_BYTE

        && srcFormat != PIX_FMT_RGB4_BYTE && dstFormat != PIX_FMT_RGB4_BYTE

        && srcFormat != PIX_FMT_MONOBLACK && dstFormat != PIX_FMT_MONOBLACK

        && srcFormat != PIX_FMT_MONOWHITE && dstFormat != PIX_FMT_MONOWHITE

        && srcFormat != PIX_FMT_RGB48LE   && dstFormat != PIX_FMT_RGB48LE

        && srcFormat != PIX_FMT_RGB48BE   && dstFormat != PIX_FMT_RGB48BE

        && srcFormat != PIX_FMT_BGR48LE   && dstFormat != PIX_FMT_BGR48LE

        && srcFormat != PIX_FMT_BGR48BE   && dstFormat != PIX_FMT_BGR48BE

        && (!needsDither || (c->flags&(SWS_FAST_BILINEAR|SWS_POINT))))

        c->swScale= rgbToRgbWrapper;



#define isByteRGB(f) (\

        f == PIX_FMT_RGB32   ||\

        f == PIX_FMT_RGB32_1 ||\

        f == PIX_FMT_RGB24   ||\

        f == PIX_FMT_BGR32   ||\

        f == PIX_FMT_BGR32_1 ||\

        f == PIX_FMT_BGR24)



    if (isAnyRGB(srcFormat) && isPlanar(srcFormat) && isByteRGB(dstFormat))

        c->swScale= planarRgbToRgbWrapper;



    if ((usePal(srcFormat) && (

        dstFormat == PIX_FMT_RGB32   ||

        dstFormat == PIX_FMT_RGB32_1 ||

        dstFormat == PIX_FMT_RGB24   ||

        dstFormat == PIX_FMT_BGR32   ||

        dstFormat == PIX_FMT_BGR32_1 ||

        dstFormat == PIX_FMT_BGR24)))

        c->swScale= palToRgbWrapper;



    if (srcFormat == PIX_FMT_YUV422P) {

        if (dstFormat == PIX_FMT_YUYV422)

            c->swScale= yuv422pToYuy2Wrapper;

        else if (dstFormat == PIX_FMT_UYVY422)

            c->swScale= yuv422pToUyvyWrapper;

    }



    /* LQ converters if -sws 0 or -sws 4*/

    if (c->flags&(SWS_FAST_BILINEAR|SWS_POINT)) {

        /* yv12_to_yuy2 */

        if (srcFormat == PIX_FMT_YUV420P || srcFormat == PIX_FMT_YUVA420P) {

            if (dstFormat == PIX_FMT_YUYV422)

                c->swScale= planarToYuy2Wrapper;

            else if (dstFormat == PIX_FMT_UYVY422)

                c->swScale= planarToUyvyWrapper;

        }

    }

    if(srcFormat == PIX_FMT_YUYV422 && (dstFormat == PIX_FMT_YUV420P || dstFormat == PIX_FMT_YUVA420P))

        c->swScale= yuyvToYuv420Wrapper;

    if(srcFormat == PIX_FMT_UYVY422 && (dstFormat == PIX_FMT_YUV420P || dstFormat == PIX_FMT_YUVA420P))

        c->swScale= uyvyToYuv420Wrapper;

    if(srcFormat == PIX_FMT_YUYV422 && dstFormat == PIX_FMT_YUV422P)

        c->swScale= yuyvToYuv422Wrapper;

    if(srcFormat == PIX_FMT_UYVY422 && dstFormat == PIX_FMT_YUV422P)

        c->swScale= uyvyToYuv422Wrapper;



    /* simple copy */

    if (  srcFormat == dstFormat

        || (srcFormat == PIX_FMT_YUVA420P && dstFormat == PIX_FMT_YUV420P)

        || (srcFormat == PIX_FMT_YUV420P && dstFormat == PIX_FMT_YUVA420P)

        || (isPlanarYUV(srcFormat) && isGray(dstFormat))

        || (isPlanarYUV(dstFormat) && isGray(srcFormat))

        || (isGray(dstFormat) && isGray(srcFormat))

        || (isPlanarYUV(srcFormat) && isPlanarYUV(dstFormat)

            && c->chrDstHSubSample == c->chrSrcHSubSample

            && c->chrDstVSubSample == c->chrSrcVSubSample

            && dstFormat != PIX_FMT_NV12 && dstFormat != PIX_FMT_NV21

            && srcFormat != PIX_FMT_NV12 && srcFormat != PIX_FMT_NV21))

    {

        if (isPacked(c->srcFormat))

            c->swScale= packedCopyWrapper;

        else /* Planar YUV or gray */

            c->swScale= planarCopyWrapper;

    }



    if (ARCH_BFIN)

        ff_bfin_get_unscaled_swscale(c);

    if (HAVE_ALTIVEC)

        ff_swscale_get_unscaled_altivec(c);

}

static inline int decode_seq_parameter_set(H264Context *h){

    MpegEncContext * const s = &h->s;

    int profile_idc, level_idc;

    unsigned int sps_id, tmp, mb_width, mb_height;

    int i;

    SPS *sps;



    profile_idc= get_bits(&s->gb, 8);

    get_bits1(&s->gb);   //constraint_set0_flag

    get_bits1(&s->gb);   //constraint_set1_flag

    get_bits1(&s->gb);   //constraint_set2_flag

    get_bits1(&s->gb);   //constraint_set3_flag

    get_bits(&s->gb, 4); // reserved

    level_idc= get_bits(&s->gb, 8);

    sps_id= get_ue_golomb(&s->gb);



    sps = alloc_parameter_set(h, (void **)h->sps_buffers, sps_id, MAX_SPS_COUNT, sizeof(SPS), "sps");

    if(sps == NULL)

        return -1;



    sps->profile_idc= profile_idc;

    sps->level_idc= level_idc;



    memset(sps->scaling_matrix4, 16, sizeof(sps->scaling_matrix4));

    memset(sps->scaling_matrix8, 16, sizeof(sps->scaling_matrix8));

    sps->scaling_matrix_present = 0;



    if(sps->profile_idc >= 100){ //high profile

        sps->chroma_format_idc= get_ue_golomb(&s->gb);

        if(sps->chroma_format_idc == 3)

            get_bits1(&s->gb);  //residual_color_transform_flag

        get_ue_golomb(&s->gb);  //bit_depth_luma_minus8

        get_ue_golomb(&s->gb);  //bit_depth_chroma_minus8

        sps->transform_bypass = get_bits1(&s->gb);

        decode_scaling_matrices(h, sps, NULL, 1, sps->scaling_matrix4, sps->scaling_matrix8);

    }else{

        sps->chroma_format_idc= 1;

    }



    sps->log2_max_frame_num= get_ue_golomb(&s->gb) + 4;

    sps->poc_type= get_ue_golomb(&s->gb);



    if(sps->poc_type == 0){ //FIXME #define

        sps->log2_max_poc_lsb= get_ue_golomb(&s->gb) + 4;

    } else if(sps->poc_type == 1){//FIXME #define

        sps->delta_pic_order_always_zero_flag= get_bits1(&s->gb);

        sps->offset_for_non_ref_pic= get_se_golomb(&s->gb);

        sps->offset_for_top_to_bottom_field= get_se_golomb(&s->gb);

        tmp= get_ue_golomb(&s->gb);



        if(tmp >= sizeof(sps->offset_for_ref_frame) / sizeof(sps->offset_for_ref_frame[0])){

            av_log(h->s.avctx, AV_LOG_ERROR, "poc_cycle_length overflow %u\n", tmp);

            return -1;

        }

        sps->poc_cycle_length= tmp;



        for(i=0; i<sps->poc_cycle_length; i++)

            sps->offset_for_ref_frame[i]= get_se_golomb(&s->gb);

    }else if(sps->poc_type != 2){

        av_log(h->s.avctx, AV_LOG_ERROR, "illegal POC type %d\n", sps->poc_type);

        return -1;

    }



    tmp= get_ue_golomb(&s->gb);

    if(tmp > MAX_PICTURE_COUNT-2 || tmp >= 32){

        av_log(h->s.avctx, AV_LOG_ERROR, "too many reference frames\n");

        return -1;

    }

    sps->ref_frame_count= tmp;

    sps->gaps_in_frame_num_allowed_flag= get_bits1(&s->gb);

    mb_width= get_ue_golomb(&s->gb) + 1;

    mb_height= get_ue_golomb(&s->gb) + 1;

    if(mb_width >= INT_MAX/16 || mb_height >= INT_MAX/16 ||

       avcodec_check_dimensions(NULL, 16*mb_width, 16*mb_height)){

        av_log(h->s.avctx, AV_LOG_ERROR, "mb_width/height overflow\n");

        return -1;

    }

    sps->mb_width = mb_width;

    sps->mb_height= mb_height;



    sps->frame_mbs_only_flag= get_bits1(&s->gb);

    if(!sps->frame_mbs_only_flag)

        sps->mb_aff= get_bits1(&s->gb);

    else

        sps->mb_aff= 0;



    sps->direct_8x8_inference_flag= get_bits1(&s->gb);



#ifndef ALLOW_INTERLACE

    if(sps->mb_aff)

        av_log(h->s.avctx, AV_LOG_ERROR, "MBAFF support not included; enable it at compile-time.\n");

#endif

    if(!sps->direct_8x8_inference_flag && sps->mb_aff)

        av_log(h->s.avctx, AV_LOG_ERROR, "MBAFF + !direct_8x8_inference is not implemented\n");



    sps->crop= get_bits1(&s->gb);

    if(sps->crop){

        sps->crop_left  = get_ue_golomb(&s->gb);

        sps->crop_right = get_ue_golomb(&s->gb);

        sps->crop_top   = get_ue_golomb(&s->gb);

        sps->crop_bottom= get_ue_golomb(&s->gb);

        if(sps->crop_left || sps->crop_top){

            av_log(h->s.avctx, AV_LOG_ERROR, "insane cropping not completely supported, this could look slightly wrong ...\n");

        }

        if(sps->crop_right >= 8 || sps->crop_bottom >= (8>> !sps->frame_mbs_only_flag)){

            av_log(h->s.avctx, AV_LOG_ERROR, "brainfart cropping not supported, this could look slightly wrong ...\n");

        }

    }else{

        sps->crop_left  =

        sps->crop_right =

        sps->crop_top   =

        sps->crop_bottom= 0;

    }



    sps->vui_parameters_present_flag= get_bits1(&s->gb);

    if( sps->vui_parameters_present_flag )

        decode_vui_parameters(h, sps);



    if(s->avctx->debug&FF_DEBUG_PICT_INFO){

        av_log(h->s.avctx, AV_LOG_DEBUG, "sps:%u profile:%d/%d poc:%d ref:%d %dx%d %s %s crop:%d/%d/%d/%d %s %s\n",

               sps_id, sps->profile_idc, sps->level_idc,

               sps->poc_type,

               sps->ref_frame_count,

               sps->mb_width, sps->mb_height,

               sps->frame_mbs_only_flag ? "FRM" : (sps->mb_aff ? "MB-AFF" : "PIC-AFF"),

               sps->direct_8x8_inference_flag ? "8B8" : "",

               sps->crop_left, sps->crop_right,

               sps->crop_top, sps->crop_bottom,

               sps->vui_parameters_present_flag ? "VUI" : "",

               ((const char*[]){"Gray","420","422","444"})[sps->chroma_format_idc]

               );

    }

    return 0;

}

static enum AVPixelFormat dshow_pixfmt(DWORD biCompression, WORD biBitCount)

{

    switch(biCompression) {

    case BI_BITFIELDS:

    case BI_RGB:

        switch(biBitCount) { /* 1-8 are untested */

            case 1:

                return AV_PIX_FMT_MONOWHITE;

            case 4:

                return AV_PIX_FMT_RGB4;

            case 8:

                return AV_PIX_FMT_RGB8;

            case 16:

                return AV_PIX_FMT_RGB555;

            case 24:

                return AV_PIX_FMT_BGR24;

            case 32:

                return AV_PIX_FMT_0RGB32;

        }

    }

    return avpriv_find_pix_fmt(ff_raw_pix_fmt_tags, biCompression); // all others

}

static void decode_scaling_list(H264Context *h, uint8_t *factors, int size,

                                const uint8_t *jvt_list,

                                const uint8_t *fallback_list)

{

    int i, last = 8, next = 8;

    const uint8_t *scan = size == 16 ? ff_zigzag_scan : ff_zigzag_direct;

    if (!get_bits1(&h->gb)) /* matrix not written, we use the predicted one */

        memcpy(factors, fallback_list, size * sizeof(uint8_t));

    else

        for (i = 0; i < size; i++) {

            if (next)

                next = (last + get_se_golomb(&h->gb)) & 0xff;

            if (!i && !next) { /* matrix not written, we use the preset one */

                memcpy(factors, jvt_list, size * sizeof(uint8_t));

                break;

            }

            last = factors[scan[i]] = next ? next : last;

        }

}

