static int init(AVFilterContext *ctx)

{

    EvalContext *eval = ctx->priv;

    char *args1 = av_strdup(eval->exprs);

    char *expr, *buf;

    int ret, i;



    if (!args1) {

        av_log(ctx, AV_LOG_ERROR, "Channels expressions list is empty\n");

        ret = eval->exprs ? AVERROR(ENOMEM) : AVERROR(EINVAL);

        goto end;

    }



    /* parse expressions */

    buf = args1;

    i = 0;

    while (i < FF_ARRAY_ELEMS(eval->expr) && (expr = av_strtok(buf, "|", &buf))) {

        ret = av_expr_parse(&eval->expr[i], expr, var_names,

                            NULL, NULL, NULL, NULL, 0, ctx);

        if (ret < 0)

            goto end;

        i++;

    }

    eval->nb_channels = i;



    if (eval->chlayout_str) {

        int n;

        ret = ff_parse_channel_layout(&eval->chlayout, eval->chlayout_str, ctx);

        if (ret < 0)

            goto end;



        n = av_get_channel_layout_nb_channels(eval->chlayout);

        if (n != eval->nb_channels) {

            av_log(ctx, AV_LOG_ERROR,

                   "Mismatch between the specified number of channels '%d' "

                   "and the number of channels '%d' in the specified channel layout '%s'\n",

                   eval->nb_channels, n, eval->chlayout_str);

            ret = AVERROR(EINVAL);

            goto end;

        }

    } else {

        /* guess channel layout from nb expressions/channels */

        eval->chlayout = av_get_default_channel_layout(eval->nb_channels);

        if (!eval->chlayout) {

            av_log(ctx, AV_LOG_ERROR, "Invalid number of channels '%d' provided\n",

                   eval->nb_channels);

            ret = AVERROR(EINVAL);

            goto end;

        }

    }



    if ((ret = ff_parse_sample_rate(&eval->sample_rate, eval->sample_rate_str, ctx)))

        goto end;

    eval->n = 0;



end:

    av_free(args1);

    return ret;

}

int ff_h264_pred_weight_table(GetBitContext *gb, const SPS *sps,

                              const int *ref_count, int slice_type_nos,

                              H264PredWeightTable *pwt, void *logctx)

{

    int list, i, j;

    int luma_def, chroma_def;



    pwt->use_weight             = 0;

    pwt->use_weight_chroma      = 0;

    pwt->luma_log2_weight_denom = get_ue_golomb(gb);

    if (sps->chroma_format_idc)

        pwt->chroma_log2_weight_denom = get_ue_golomb(gb);



    if (pwt->luma_log2_weight_denom > 7U) {

        av_log(logctx, AV_LOG_ERROR, "luma_log2_weight_denom %d is out of range\n", pwt->luma_log2_weight_denom);

        pwt->luma_log2_weight_denom = 0;

    }

    if (pwt->chroma_log2_weight_denom > 7U) {

        av_log(logctx, AV_LOG_ERROR, "chroma_log2_weight_denom %d is out of range\n", pwt->chroma_log2_weight_denom);

        pwt->chroma_log2_weight_denom = 0;

    }



    luma_def   = 1 << pwt->luma_log2_weight_denom;

    chroma_def = 1 << pwt->chroma_log2_weight_denom;



    for (list = 0; list < 2; list++) {

        pwt->luma_weight_flag[list]   = 0;

        pwt->chroma_weight_flag[list] = 0;

        for (i = 0; i < ref_count[list]; i++) {

            int luma_weight_flag, chroma_weight_flag;



            luma_weight_flag = get_bits1(gb);

            if (luma_weight_flag) {

                pwt->luma_weight[i][list][0] = get_se_golomb(gb);

                pwt->luma_weight[i][list][1] = get_se_golomb(gb);




                if (pwt->luma_weight[i][list][0] != luma_def ||

                    pwt->luma_weight[i][list][1] != 0) {

                    pwt->use_weight             = 1;

                    pwt->luma_weight_flag[list] = 1;

                }

            } else {

                pwt->luma_weight[i][list][0] = luma_def;

                pwt->luma_weight[i][list][1] = 0;

            }



            if (sps->chroma_format_idc) {

                chroma_weight_flag = get_bits1(gb);

                if (chroma_weight_flag) {

                    int j;

                    for (j = 0; j < 2; j++) {

                        pwt->chroma_weight[i][list][j][0] = get_se_golomb(gb);

                        pwt->chroma_weight[i][list][j][1] = get_se_golomb(gb);

                        if ((int8_t)pwt->chroma_weight[i][list][j][0] != pwt->chroma_weight[i][list][j][0] ||

                            (int8_t)pwt->chroma_weight[i][list][j][1] != pwt->chroma_weight[i][list][j][1])


                        if (pwt->chroma_weight[i][list][j][0] != chroma_def ||

                            pwt->chroma_weight[i][list][j][1] != 0) {

                            pwt->use_weight_chroma        = 1;

                            pwt->chroma_weight_flag[list] = 1;

                        }

                    }

                } else {

                    int j;

                    for (j = 0; j < 2; j++) {

                        pwt->chroma_weight[i][list][j][0] = chroma_def;

                        pwt->chroma_weight[i][list][j][1] = 0;

                    }

                }

            }



            // for MBAFF

            pwt->luma_weight[16 + 2 * i][list][0] = pwt->luma_weight[16 + 2 * i + 1][list][0] = pwt->luma_weight[i][list][0];

            pwt->luma_weight[16 + 2 * i][list][1] = pwt->luma_weight[16 + 2 * i + 1][list][1] = pwt->luma_weight[i][list][1];

            for (j = 0; j < 2; j++) {

                pwt->chroma_weight[16 + 2 * i][list][j][0] = pwt->chroma_weight[16 + 2 * i + 1][list][j][0] = pwt->chroma_weight[i][list][j][0];

                pwt->chroma_weight[16 + 2 * i][list][j][1] = pwt->chroma_weight[16 + 2 * i + 1][list][j][1] = pwt->chroma_weight[i][list][j][1];

            }

        }

        if (slice_type_nos != AV_PICTURE_TYPE_B)

            break;

    }

    pwt->use_weight = pwt->use_weight || pwt->use_weight_chroma;

    return 0;

out_range_weight:

    avpriv_request_sample(logctx, "Out of range weight\n");

    return AVERROR_INVALIDDATA;

}

static int cin_read_packet(AVFormatContext *s, AVPacket *pkt)

{

    CinDemuxContext *cin = s->priv_data;

    ByteIOContext *pb = s->pb;

    CinFrameHeader *hdr = &cin->frame_header;

    int rc, palette_type, pkt_size;



    if (cin->audio_buffer_size == 0) {

        rc = cin_read_frame_header(cin, pb);

        if (rc)

            return rc;



        if ((int16_t)hdr->pal_colors_count < 0) {

            hdr->pal_colors_count = -(int16_t)hdr->pal_colors_count;

            palette_type = 1;

        } else {

            palette_type = 0;

        }



        /* palette and video packet */

        pkt_size = (palette_type + 3) * hdr->pal_colors_count + hdr->video_frame_size;



        if (av_new_packet(pkt, 4 + pkt_size))

            return AVERROR(ENOMEM);



        pkt->stream_index = cin->video_stream_index;

        pkt->pts = cin->video_stream_pts++;



        pkt->data[0] = palette_type;

        pkt->data[1] = hdr->pal_colors_count & 0xFF;

        pkt->data[2] = hdr->pal_colors_count >> 8;

        pkt->data[3] = hdr->video_frame_type;



        if (get_buffer(pb, &pkt->data[4], pkt_size) != pkt_size)

            return AVERROR(EIO);



        /* sound buffer will be processed on next read_packet() call */

        cin->audio_buffer_size = hdr->audio_frame_size;

        return 0;

    }



    /* audio packet */

    if (av_new_packet(pkt, cin->audio_buffer_size))

        return AVERROR(ENOMEM);



    pkt->stream_index = cin->audio_stream_index;

    pkt->pts = cin->audio_stream_pts;

    cin->audio_stream_pts += cin->audio_buffer_size * 2 / cin->file_header.audio_frame_size;



    if (get_buffer(pb, pkt->data, cin->audio_buffer_size) != cin->audio_buffer_size)

        return AVERROR(EIO);



    cin->audio_buffer_size = 0;

    return 0;

}

static int v4l2_receive_packet(AVCodecContext *avctx, AVPacket *avpkt)

{

    V4L2m2mContext *s = avctx->priv_data;

    V4L2Context *const capture = &s->capture;

    V4L2Context *const output = &s->output;

    int ret;



    if (s->draining)

        goto dequeue;



    if (!output->streamon) {

        ret = ff_v4l2_context_set_status(output, VIDIOC_STREAMON);

        if (ret) {

            av_log(avctx, AV_LOG_ERROR, "VIDIOC_STREAMOFF failed on output context\n");

            return ret;

        }

    }



    if (!capture->streamon) {

        ret = ff_v4l2_context_set_status(capture, VIDIOC_STREAMON);

        if (ret) {

            av_log(avctx, AV_LOG_ERROR, "VIDIOC_STREAMON failed on capture context\n");

            return ret;

        }

    }



dequeue:

    return ff_v4l2_context_dequeue_packet(capture, avpkt);

}

static int mov_rewrite_dvd_sub_extradata(AVStream *st)

{

    char pal_s[256];

    char buf[256];

    int pal_s_pos = 0;

    uint8_t *src = st->codec->extradata;

    int i;



    if (st->codec->extradata_size != 64)

        return 0;



    for (i = 0; i < 16; i++) {

        uint32_t yuv = AV_RB32(src + i * 4);

        uint32_t rgba = yuv_to_rgba(yuv);



        snprintf(pal_s + pal_s_pos, sizeof(pal_s) - pal_s_pos, "%06x%s", rgba,

                 i != 15 ? ", " : "");

        pal_s_pos = strlen(pal_s);

        if (pal_s_pos >= sizeof(pal_s))

            return 0;

    }



    snprintf(buf, sizeof(buf), "size: %dx%d\npalette: %s\n",

             st->codec->width, st->codec->height, pal_s);



    av_freep(&st->codec->extradata);

    st->codec->extradata_size = 0;

    st->codec->extradata = av_mallocz(strlen(buf) + FF_INPUT_BUFFER_PADDING_SIZE);

    if (!st->codec->extradata)

        return AVERROR(ENOMEM);

    st->codec->extradata_size = strlen(buf);

    memcpy(st->codec->extradata, buf, st->codec->extradata_size);



    return 0;

}

static void do_streamcopy(InputStream *ist, OutputStream *ost, const AVPacket *pkt)

{

    OutputFile *of = output_files[ost->file_index];

    int64_t ost_tb_start_time = av_rescale_q(of->start_time, AV_TIME_BASE_Q, ost->st->time_base);

    AVPacket opkt;



    av_init_packet(&opkt);



    if ((!ost->frame_number && !(pkt->flags & AV_PKT_FLAG_KEY)) &&

        !ost->copy_initial_nonkeyframes)

        return;



    if (of->recording_time != INT64_MAX &&

        ist->last_dts >= of->recording_time + of->start_time) {

        ost->is_past_recording_time = 1;

        return;

    }



    /* force the input stream PTS */

    if (ost->st->codec->codec_type == AVMEDIA_TYPE_AUDIO)

        audio_size += pkt->size;

    else if (ost->st->codec->codec_type == AVMEDIA_TYPE_VIDEO) {

        video_size += pkt->size;

        ost->sync_opts++;

    }



    if (pkt->pts != AV_NOPTS_VALUE)

        opkt.pts = av_rescale_q(pkt->pts, ist->st->time_base, ost->st->time_base) - ost_tb_start_time;

    else

        opkt.pts = AV_NOPTS_VALUE;



    if (pkt->dts == AV_NOPTS_VALUE)

        opkt.dts = av_rescale_q(ist->last_dts, AV_TIME_BASE_Q, ost->st->time_base);

    else

        opkt.dts = av_rescale_q(pkt->dts, ist->st->time_base, ost->st->time_base);

    opkt.dts -= ost_tb_start_time;



    opkt.duration = av_rescale_q(pkt->duration, ist->st->time_base, ost->st->time_base);

    opkt.flags    = pkt->flags;



    // FIXME remove the following 2 lines they shall be replaced by the bitstream filters

    if (  ost->st->codec->codec_id != AV_CODEC_ID_H264

       && ost->st->codec->codec_id != AV_CODEC_ID_MPEG1VIDEO

       && ost->st->codec->codec_id != AV_CODEC_ID_MPEG2VIDEO

       && ost->st->codec->codec_id != AV_CODEC_ID_VC1

       ) {

        if (av_parser_change(ist->st->parser, ost->st->codec, &opkt.data, &opkt.size, pkt->data, pkt->size, pkt->flags & AV_PKT_FLAG_KEY))

            opkt.destruct = av_destruct_packet;

    } else {

        opkt.data = pkt->data;

        opkt.size = pkt->size;

    }



    write_frame(of->ctx, &opkt, ost);

    ost->st->codec->frame_number++;

    av_free_packet(&opkt);

}

static int au_read_packet(AVFormatContext *s,

                          AVPacket *pkt)

{

    int ret;



    ret= av_get_packet(s->pb, pkt, BLOCK_SIZE *

                       s->streams[0]->codec->channels *

                       av_get_bits_per_sample(s->streams[0]->codec->codec_id) >> 3);

    if (ret < 0)

        return ret;

    pkt->flags &= ~AV_PKT_FLAG_CORRUPT;

    pkt->stream_index = 0;

    return 0;

}

int av_find_stream_info(AVFormatContext *ic)

{

    int i, count, ret, read_size, j;

    AVStream *st;

    AVPacket pkt1, *pkt;

    int64_t old_offset = url_ftell(ic->pb);

    struct {

        int64_t last_dts;

        int64_t duration_gcd;

        int duration_count;

        double duration_error[MAX_STD_TIMEBASES];

        int64_t codec_info_duration;

    } info[MAX_STREAMS] = {{0}};



    for(i=0;i<ic->nb_streams;i++) {

        st = ic->streams[i];

        if (st->codec->codec_id == CODEC_ID_AAC) {

            st->codec->sample_rate = 0;

            st->codec->frame_size = 0;

            st->codec->channels = 0;

        }

        if(st->codec->codec_type == AVMEDIA_TYPE_VIDEO){

/*            if(!st->time_base.num)

                st->time_base= */

            if(!st->codec->time_base.num)

                st->codec->time_base= st->time_base;

        }

        //only for the split stuff

        if (!st->parser && !(ic->flags & AVFMT_FLAG_NOPARSE)) {

            st->parser = av_parser_init(st->codec->codec_id);

            if(st->need_parsing == AVSTREAM_PARSE_HEADERS && st->parser){

                st->parser->flags |= PARSER_FLAG_COMPLETE_FRAMES;

            }

        }

        assert(!st->codec->codec);

        //try to just open decoders, in case this is enough to get parameters

        if(!has_codec_parameters(st->codec)){

            AVCodec *codec = avcodec_find_decoder(st->codec->codec_id);

            if (codec)

                avcodec_open(st->codec, codec);

        }

    }



    for(i=0;i<MAX_STREAMS;i++){

        info[i].last_dts= AV_NOPTS_VALUE;

    }



    count = 0;

    read_size = 0;

    for(;;) {

        if(url_interrupt_cb()){

            ret= AVERROR(EINTR);

            av_log(ic, AV_LOG_DEBUG, "interrupted\n");

            break;

        }



        /* check if one codec still needs to be handled */

        for(i=0;i<ic->nb_streams;i++) {

            st = ic->streams[i];

            if (!has_codec_parameters(st->codec))

                break;

            /* variable fps and no guess at the real fps */

            if(   tb_unreliable(st->codec) && !(st->r_frame_rate.num && st->avg_frame_rate.num)

               && info[i].duration_count<20 && st->codec->codec_type == AVMEDIA_TYPE_VIDEO)

                break;

            if(st->parser && st->parser->parser->split && !st->codec->extradata)

                break;

            if(st->first_dts == AV_NOPTS_VALUE)

                break;

        }

        if (i == ic->nb_streams) {

            /* NOTE: if the format has no header, then we need to read

               some packets to get most of the streams, so we cannot

               stop here */

            if (!(ic->ctx_flags & AVFMTCTX_NOHEADER)) {

                /* if we found the info for all the codecs, we can stop */

                ret = count;

                av_log(ic, AV_LOG_DEBUG, "All info found\n");

                break;

            }

        }

        /* we did not get all the codec info, but we read too much data */

        if (read_size >= ic->probesize) {

            ret = count;

            av_log(ic, AV_LOG_DEBUG, "Probe buffer size limit %d reached\n", ic->probesize);

            break;

        }



        /* NOTE: a new stream can be added there if no header in file

           (AVFMTCTX_NOHEADER) */

        ret = av_read_frame_internal(ic, &pkt1);

        if(ret == AVERROR(EAGAIN))

            continue;

        if (ret < 0) {

            /* EOF or error */

            ret = -1; /* we could not have all the codec parameters before EOF */

            for(i=0;i<ic->nb_streams;i++) {

                st = ic->streams[i];

                if (!has_codec_parameters(st->codec)){

                    char buf[256];

                    avcodec_string(buf, sizeof(buf), st->codec, 0);

                    av_log(ic, AV_LOG_WARNING, "Could not find codec parameters (%s)\n", buf);

                } else {

                    ret = 0;

                }

            }

            break;

        }



        pkt= add_to_pktbuf(&ic->packet_buffer, &pkt1, &ic->packet_buffer_end);

        if(av_dup_packet(pkt) < 0) {

            return AVERROR(ENOMEM);

        }



        read_size += pkt->size;



        st = ic->streams[pkt->stream_index];

        if(st->codec_info_nb_frames>1) {

            if (st->time_base.den > 0 && av_rescale_q(info[st->index].codec_info_duration, st->time_base, AV_TIME_BASE_Q) >= ic->max_analyze_duration){

                av_log(ic, AV_LOG_WARNING, "max_analyze_duration reached\n");

                break;

            }

            info[st->index].codec_info_duration += pkt->duration;

        }

        {

            int index= pkt->stream_index;

            int64_t last= info[index].last_dts;

            int64_t duration= pkt->dts - last;



            if(pkt->dts != AV_NOPTS_VALUE && last != AV_NOPTS_VALUE && duration>0){

                double dur= duration * av_q2d(st->time_base);



//                if(st->codec->codec_type == AVMEDIA_TYPE_VIDEO)

//                    av_log(NULL, AV_LOG_ERROR, "%f\n", dur);

                if(info[index].duration_count < 2)

                    memset(info[index].duration_error, 0, sizeof(info[index].duration_error));

                for(i=1; i<MAX_STD_TIMEBASES; i++){

                    int framerate= get_std_framerate(i);

                    int ticks= lrintf(dur*framerate/(1001*12));

                    double error= dur - ticks*1001*12/(double)framerate;

                    info[index].duration_error[i] += error*error;

                }

                info[index].duration_count++;

                // ignore the first 4 values, they might have some random jitter

                if (info[index].duration_count > 3)

                    info[index].duration_gcd = av_gcd(info[index].duration_gcd, duration);

            }

            if(last == AV_NOPTS_VALUE || info[index].duration_count <= 1)

                info[pkt->stream_index].last_dts = pkt->dts;

        }

        if(st->parser && st->parser->parser->split && !st->codec->extradata){

            int i= st->parser->parser->split(st->codec, pkt->data, pkt->size);

            if(i){

                st->codec->extradata_size= i;

                st->codec->extradata= av_malloc(st->codec->extradata_size + FF_INPUT_BUFFER_PADDING_SIZE);

                memcpy(st->codec->extradata, pkt->data, st->codec->extradata_size);

                memset(st->codec->extradata + i, 0, FF_INPUT_BUFFER_PADDING_SIZE);

            }

        }



        /* if still no information, we try to open the codec and to

           decompress the frame. We try to avoid that in most cases as

           it takes longer and uses more memory. For MPEG-4, we need to

           decompress for QuickTime. */

        if (!has_codec_parameters(st->codec) || !has_decode_delay_been_guessed(st))

            try_decode_frame(st, pkt);



        st->codec_info_nb_frames++;

        count++;

    }



    // close codecs which were opened in try_decode_frame()

    for(i=0;i<ic->nb_streams;i++) {

        st = ic->streams[i];

        if(st->codec->codec)

            avcodec_close(st->codec);

    }

    for(i=0;i<ic->nb_streams;i++) {

        st = ic->streams[i];

        if(st->codec_info_nb_frames>2 && !st->avg_frame_rate.num && info[i].codec_info_duration)

            av_reduce(&st->avg_frame_rate.num, &st->avg_frame_rate.den,

                     (st->codec_info_nb_frames-2)*(int64_t)st->time_base.den,

                      info[i].codec_info_duration*(int64_t)st->time_base.num, 60000);

        if (st->codec->codec_type == AVMEDIA_TYPE_VIDEO) {

            if(st->codec->codec_id == CODEC_ID_RAWVIDEO && !st->codec->codec_tag && !st->codec->bits_per_coded_sample)

                st->codec->codec_tag= avcodec_pix_fmt_to_codec_tag(st->codec->pix_fmt);



            // the check for tb_unreliable() is not completely correct, since this is not about handling

            // a unreliable/inexact time base, but a time base that is finer than necessary, as e.g.

            // ipmovie.c produces.

            if (tb_unreliable(st->codec) && info[i].duration_count > 15 && info[i].duration_gcd > 1 && !st->r_frame_rate.num)

                av_reduce(&st->r_frame_rate.num, &st->r_frame_rate.den, st->time_base.den, st->time_base.num * info[i].duration_gcd, INT_MAX);

            if(info[i].duration_count && !st->r_frame_rate.num

               && tb_unreliable(st->codec) /*&&

               //FIXME we should not special-case MPEG-2, but this needs testing with non-MPEG-2 ...

               st->time_base.num*duration_sum[i]/info[i].duration_count*101LL > st->time_base.den*/){

                int num = 0;

                double best_error= 2*av_q2d(st->time_base);

                best_error= best_error*best_error*info[i].duration_count*1000*12*30;



                for(j=1; j<MAX_STD_TIMEBASES; j++){

                    double error= info[i].duration_error[j] * get_std_framerate(j);

//                    if(st->codec->codec_type == AVMEDIA_TYPE_VIDEO)

//                        av_log(NULL, AV_LOG_ERROR, "%f %f\n", get_std_framerate(j) / 12.0/1001, error);

                    if(error < best_error){

                        best_error= error;

                        num = get_std_framerate(j);

                    }

                }

                // do not increase frame rate by more than 1 % in order to match a standard rate.

                if (num && (!st->r_frame_rate.num || (double)num/(12*1001) < 1.01 * av_q2d(st->r_frame_rate)))

                    av_reduce(&st->r_frame_rate.num, &st->r_frame_rate.den, num, 12*1001, INT_MAX);

            }



            if (!st->r_frame_rate.num){

                if(    st->codec->time_base.den * (int64_t)st->time_base.num

                    <= st->codec->time_base.num * st->codec->ticks_per_frame * (int64_t)st->time_base.den){

                    st->r_frame_rate.num = st->codec->time_base.den;

                    st->r_frame_rate.den = st->codec->time_base.num * st->codec->ticks_per_frame;

                }else{

                    st->r_frame_rate.num = st->time_base.den;

                    st->r_frame_rate.den = st->time_base.num;

                }

            }

        }else if(st->codec->codec_type == AVMEDIA_TYPE_AUDIO) {

            if(!st->codec->bits_per_coded_sample)

                st->codec->bits_per_coded_sample= av_get_bits_per_sample(st->codec->codec_id);

        }

    }



    av_estimate_timings(ic, old_offset);



    compute_chapters_end(ic);



#if 0

    /* correct DTS for B-frame streams with no timestamps */

    for(i=0;i<ic->nb_streams;i++) {

        st = ic->streams[i];

        if (st->codec->codec_type == AVMEDIA_TYPE_VIDEO) {

            if(b-frames){

                ppktl = &ic->packet_buffer;

                while(ppkt1){

                    if(ppkt1->stream_index != i)

                        continue;

                    if(ppkt1->pkt->dts < 0)

                        break;

                    if(ppkt1->pkt->pts != AV_NOPTS_VALUE)

                        break;

                    ppkt1->pkt->dts -= delta;

                    ppkt1= ppkt1->next;

                }

                if(ppkt1)

                    continue;

                st->cur_dts -= delta;

            }

        }

    }

#endif



    return ret;

}

static int r3d_read_reda(AVFormatContext *s, AVPacket *pkt, Atom *atom)

{

    AVStream *st = s->streams[1];

    int av_unused tmp, tmp2;

    int samples, size;

    uint64_t pos = avio_tell(s->pb);

    unsigned dts;

    int ret;



    dts = avio_rb32(s->pb);



    st->codec->sample_rate = avio_rb32(s->pb);

    if (st->codec->sample_rate <= 0) {

        av_log(s, AV_LOG_ERROR, "Bad sample rate\n");

        return AVERROR_INVALIDDATA;

    }



    samples = avio_rb32(s->pb);



    tmp = avio_rb32(s->pb);

    av_dlog(s, "packet num %d\n", tmp);



    tmp = avio_rb16(s->pb); // unknown

    av_dlog(s, "unknown %d\n", tmp);



    tmp  = avio_r8(s->pb); // major version

    tmp2 = avio_r8(s->pb); // minor version

    av_dlog(s, "version %d.%d\n", tmp, tmp2);



    tmp = avio_rb32(s->pb); // unknown

    av_dlog(s, "unknown %d\n", tmp);



    size = atom->size - 8 - (avio_tell(s->pb) - pos);

    if (size < 0)

        return -1;

    ret = av_get_packet(s->pb, pkt, size);

    if (ret < 0) {

        av_log(s, AV_LOG_ERROR, "error reading audio packet\n");

        return ret;

    }



    pkt->stream_index = 1;

    pkt->dts = dts;

    pkt->duration = av_rescale(samples, st->time_base.den, st->codec->sample_rate);

    av_dlog(s, "pkt dts %"PRId64" duration %d samples %d sample rate %d\n",

            pkt->dts, pkt->duration, samples, st->codec->sample_rate);



    return 0;

}

void rgb16tobgr32(const uint8_t *src, uint8_t *dst, long src_size)

{

	const uint16_t *end;

	uint8_t *d = (uint8_t *)dst;

	const uint16_t *s = (uint16_t *)src;

	end = s + src_size/2;

	while(s < end)

	{

		register uint16_t bgr;

		bgr = *s++;

		#ifdef WORDS_BIGENDIAN

			*d++ = 0;

			*d++ = (bgr&0x1F)<<3;

			*d++ = (bgr&0x7E0)>>3;

			*d++ = (bgr&0xF800)>>8;

		#else

			*d++ = (bgr&0xF800)>>8;

			*d++ = (bgr&0x7E0)>>3;

			*d++ = (bgr&0x1F)<<3;

			*d++ = 0;

		#endif

	}

}

static void ir2_decode_plane_inter(Ir2Context *ctx, int width, int height, uint8_t *dst, int stride,

                             const uint8_t *table)

{

    int j;

    int out = 0;

    int c;

    int t;



    for (j = 0; j < height; j++){

        out = 0;

        while (out < width){

            c = ir2_get_code(&ctx->gb);

            if(c > 0x80) { /* we have a skip */

                c -= 0x80;

                out += c * 2;

            } else { /* add two deltas from table */

                t = dst[out] + (table[c * 2] - 128);

                CLAMP_TO_BYTE(t);

                dst[out] = t;

                out++;

                t = dst[out] + (table[(c * 2) + 1] - 128);

                CLAMP_TO_BYTE(t);

                dst[out] = t;

                out++;

            }

        }

        dst += stride;

    }

}

static int get_video_frame(VideoState *is, AVFrame *frame, int64_t *pts, AVPacket *pkt, int *serial)

{

    int got_picture;



    if (packet_queue_get(&is->videoq, pkt, 1, serial) < 0)

        return -1;



    if (pkt->data == flush_pkt.data) {

        avcodec_flush_buffers(is->video_st->codec);



        SDL_LockMutex(is->pictq_mutex);

        // Make sure there are no long delay timers (ideally we should just flush the queue but that's harder)

        while (is->pictq_size && !is->videoq.abort_request) {

            SDL_CondWait(is->pictq_cond, is->pictq_mutex);

        }

        is->video_current_pos = -1;

        is->frame_last_pts = AV_NOPTS_VALUE;

        is->frame_last_duration = 0;

        is->frame_timer = (double)av_gettime() / 1000000.0;

        is->frame_last_dropped_pts = AV_NOPTS_VALUE;

        SDL_UnlockMutex(is->pictq_mutex);

        return 0;

    }



    if(avcodec_decode_video2(is->video_st->codec, frame, &got_picture, pkt) < 0)

        return 0;



    if (got_picture) {

        int ret = 1;



        if (decoder_reorder_pts == -1) {

            *pts = av_frame_get_best_effort_timestamp(frame);

        } else if (decoder_reorder_pts) {

            *pts = frame->pkt_pts;

        } else {

            *pts = frame->pkt_dts;

        }



        if (*pts == AV_NOPTS_VALUE) {

            *pts = 0;

        }



        if (framedrop>0 || (framedrop && get_master_sync_type(is) != AV_SYNC_VIDEO_MASTER)) {

            SDL_LockMutex(is->pictq_mutex);

            if (is->frame_last_pts != AV_NOPTS_VALUE && *pts) {

                double clockdiff = get_video_clock(is) - get_master_clock(is);

                double dpts = av_q2d(is->video_st->time_base) * *pts;

                double ptsdiff = dpts - is->frame_last_pts;

                if (!isnan(clockdiff) && fabs(clockdiff) < AV_NOSYNC_THRESHOLD &&

                     ptsdiff > 0 && ptsdiff < AV_NOSYNC_THRESHOLD &&

                     clockdiff + ptsdiff - is->frame_last_filter_delay < 0) {

                    is->frame_last_dropped_pos = pkt->pos;

                    is->frame_last_dropped_pts = dpts;

                    is->frame_drops_early++;


                    ret = 0;

                }

            }

            SDL_UnlockMutex(is->pictq_mutex);

        }



        return ret;

    }

    return 0;

}

int ff_audio_rechunk_interleave(AVFormatContext *s, AVPacket *out, AVPacket *pkt, int flush,

                        int (*get_packet)(AVFormatContext *, AVPacket *, AVPacket *, int),

                        int (*compare_ts)(AVFormatContext *, AVPacket *, AVPacket *))

{

    int i;



    if (pkt) {

        AVStream *st = s->streams[pkt->stream_index];

        AudioInterleaveContext *aic = st->priv_data;

        if (st->codec->codec_type == AVMEDIA_TYPE_AUDIO) {

            unsigned new_size = av_fifo_size(aic->fifo) + pkt->size;

            if (new_size > aic->fifo_size) {

                if (av_fifo_realloc2(aic->fifo, new_size) < 0)

                    return -1;

                aic->fifo_size = new_size;

            }

            av_fifo_generic_write(aic->fifo, pkt->data, pkt->size, NULL);

        } else {

            // rewrite pts and dts to be decoded time line position

            pkt->pts = pkt->dts = aic->dts;

            aic->dts += pkt->duration;

            ff_interleave_add_packet(s, pkt, compare_ts);

        }

        pkt = NULL;

    }



    for (i = 0; i < s->nb_streams; i++) {

        AVStream *st = s->streams[i];

        if (st->codec->codec_type == AVMEDIA_TYPE_AUDIO) {

            AVPacket new_pkt;

            while (ff_interleave_new_audio_packet(s, &new_pkt, i, flush))

                ff_interleave_add_packet(s, &new_pkt, compare_ts);

        }

    }



    return get_packet(s, out, pkt, flush);

}

static int aac_decode_frame_int(AVCodecContext *avctx, void *data,

                                int *got_frame_ptr, GetBitContext *gb)

{

    AACContext *ac = avctx->priv_data;

    ChannelElement *che = NULL, *che_prev = NULL;

    enum RawDataBlockType elem_type, elem_type_prev = TYPE_END;

    int err, elem_id;

    int samples = 0, multiplier, audio_found = 0, pce_found = 0;



    if (show_bits(gb, 12) == 0xfff) {

        if (parse_adts_frame_header(ac, gb) < 0) {

            av_log(avctx, AV_LOG_ERROR, "Error decoding AAC frame header.\n");

            err = -1;

            goto fail;

        }

        if (ac->oc[1].m4ac.sampling_index > 12) {

            av_log(ac->avctx, AV_LOG_ERROR, "invalid sampling rate index %d\n", ac->oc[1].m4ac.sampling_index);

            err = -1;

            goto fail;

        }

    }



    ac->tags_mapped = 0;

    // parse

    while ((elem_type = get_bits(gb, 3)) != TYPE_END) {

        elem_id = get_bits(gb, 4);



        if (elem_type < TYPE_DSE) {

            if (!(che=get_che(ac, elem_type, elem_id))) {

                av_log(ac->avctx, AV_LOG_ERROR, "channel element %d.%d is not allocated\n",

                       elem_type, elem_id);

                err = -1;

                goto fail;

            }

            samples = 1024;

        }



        switch (elem_type) {



        case TYPE_SCE:

            err = decode_ics(ac, &che->ch[0], gb, 0, 0);

            audio_found = 1;

            break;



        case TYPE_CPE:

            err = decode_cpe(ac, gb, che);

            audio_found = 1;

            break;



        case TYPE_CCE:

            err = decode_cce(ac, gb, che);

            break;



        case TYPE_LFE:

            err = decode_ics(ac, &che->ch[0], gb, 0, 0);

            audio_found = 1;

            break;



        case TYPE_DSE:

            err = skip_data_stream_element(ac, gb);

            break;



        case TYPE_PCE: {

            uint8_t layout_map[MAX_ELEM_ID*4][3];

            int tags;

            push_output_configuration(ac);

            tags = decode_pce(avctx, &ac->oc[1].m4ac, layout_map, gb);

            if (tags < 0) {

                err = tags;

                break;

            }

            if (pce_found) {

                av_log(avctx, AV_LOG_ERROR,

                       "Not evaluating a further program_config_element as this construct is dubious at best.\n");

                pop_output_configuration(ac);

            } else {

                err = output_configure(ac, layout_map, tags, 0, OC_TRIAL_PCE);

                if (!err)

                    ac->oc[1].m4ac.chan_config = 0;

                pce_found = 1;

            }

            break;

        }



        case TYPE_FIL:

            if (elem_id == 15)

                elem_id += get_bits(gb, 8) - 1;

            if (get_bits_left(gb) < 8 * elem_id) {

                    av_log(avctx, AV_LOG_ERROR, overread_err);

                    err = -1;

                    goto fail;

            }

            while (elem_id > 0)

                elem_id -= decode_extension_payload(ac, gb, elem_id, che_prev, elem_type_prev);

            err = 0; /* FIXME */

            break;



        default:

            err = -1; /* should not happen, but keeps compiler happy */

            break;

        }



        che_prev       = che;

        elem_type_prev = elem_type;



        if (err)

            goto fail;



        if (get_bits_left(gb) < 3) {

            av_log(avctx, AV_LOG_ERROR, overread_err);

            err = -1;

            goto fail;

        }

    }



    spectral_to_sample(ac);



    multiplier = (ac->oc[1].m4ac.sbr == 1) ? ac->oc[1].m4ac.ext_sample_rate > ac->oc[1].m4ac.sample_rate : 0;

    samples <<= multiplier;



    if (samples) {

        /* get output buffer */

        ac->frame.nb_samples = samples;

        if ((err = avctx->get_buffer(avctx, &ac->frame)) < 0) {

            av_log(avctx, AV_LOG_ERROR, "get_buffer() failed\n");

            err = -1;

            goto fail;

        }



        if (avctx->sample_fmt == AV_SAMPLE_FMT_FLT)

            ac->fmt_conv.float_interleave((float *)ac->frame.data[0],

                                          (const float **)ac->output_data,

                                          samples, avctx->channels);

        else

            ac->fmt_conv.float_to_int16_interleave((int16_t *)ac->frame.data[0],

                                                   (const float **)ac->output_data,

                                                   samples, avctx->channels);



        *(AVFrame *)data = ac->frame;

    }

    *got_frame_ptr = !!samples;



    if (ac->oc[1].status && audio_found) {

        avctx->sample_rate = ac->oc[1].m4ac.sample_rate << multiplier;

        avctx->frame_size = samples;

        ac->oc[1].status = OC_LOCKED;

    }



    return 0;

fail:

    pop_output_configuration(ac);

    return err;

}

static int fill_default_ref_list(H264Context *h){

    MpegEncContext * const s = &h->s;

    int i;

    int smallest_poc_greater_than_current = -1;

    Picture sorted_short_ref[32];



    if(h->slice_type==B_TYPE){

        int out_i;

        int limit= -1;



        /* sort frame according to poc in B slice */

        for(out_i=0; out_i<h->short_ref_count; out_i++){

            int best_i=-1;

            int best_poc=INT_MAX;



            for(i=0; i<h->short_ref_count; i++){

                const int poc= h->short_ref[i]->poc;

                if(poc > limit && poc < best_poc){

                    best_poc= poc;

                    best_i= i;

                }

            }



            assert(best_i != -1);



            limit= best_poc;

            sorted_short_ref[out_i]= *h->short_ref[best_i];

            tprintf("sorted poc: %d->%d poc:%d fn:%d\n", best_i, out_i, sorted_short_ref[out_i].poc, sorted_short_ref[out_i].frame_num);

            if (-1 == smallest_poc_greater_than_current) {

                if (h->short_ref[best_i]->poc >= s->current_picture_ptr->poc) {

                    smallest_poc_greater_than_current = out_i;

                }

            }

        }

    }



    if(s->picture_structure == PICT_FRAME){

        if(h->slice_type==B_TYPE){

            int list;

            tprintf("current poc: %d, smallest_poc_greater_than_current: %d\n", s->current_picture_ptr->poc, smallest_poc_greater_than_current);



            // find the largest poc

            for(list=0; list<2; list++){

                int index = 0;

                int j= -99;

                int step= list ? -1 : 1;



                for(i=0; i<h->short_ref_count && index < h->ref_count[list]; i++, j+=step) {

                    while(j<0 || j>= h->short_ref_count){

                        if(j != -99 && step == (list ? -1 : 1))

                            return -1;

                        step = -step;

                        j= smallest_poc_greater_than_current + (step>>1);

                    }

                    if(sorted_short_ref[j].reference != 3) continue;

                    h->default_ref_list[list][index  ]= sorted_short_ref[j];

                    h->default_ref_list[list][index++].pic_id= sorted_short_ref[j].frame_num;

                }



                for(i = 0; i < 16 && index < h->ref_count[ list ]; i++){

                    if(h->long_ref[i] == NULL) continue;

                    if(h->long_ref[i]->reference != 3) continue;



                    h->default_ref_list[ list ][index  ]= *h->long_ref[i];

                    h->default_ref_list[ list ][index++].pic_id= i;;

                }



                if(list && (smallest_poc_greater_than_current<=0 || smallest_poc_greater_than_current>=h->short_ref_count) && (1 < index)){

                    // swap the two first elements of L1 when

                    // L0 and L1 are identical

                    Picture temp= h->default_ref_list[1][0];

                    h->default_ref_list[1][0] = h->default_ref_list[1][1];

                    h->default_ref_list[1][1] = temp;

                }



                if(index < h->ref_count[ list ])

                    memset(&h->default_ref_list[list][index], 0, sizeof(Picture)*(h->ref_count[ list ] - index));

            }

        }else{

            int index=0;

            for(i=0; i<h->short_ref_count; i++){

                if(h->short_ref[i]->reference != 3) continue; //FIXME refernce field shit

                h->default_ref_list[0][index  ]= *h->short_ref[i];

                h->default_ref_list[0][index++].pic_id= h->short_ref[i]->frame_num;

            }

            for(i = 0; i < 16; i++){

                if(h->long_ref[i] == NULL) continue;

                if(h->long_ref[i]->reference != 3) continue;

                h->default_ref_list[0][index  ]= *h->long_ref[i];

                h->default_ref_list[0][index++].pic_id= i;;

            }

            if(index < h->ref_count[0])

                memset(&h->default_ref_list[0][index], 0, sizeof(Picture)*(h->ref_count[0] - index));

        }

    }else{ //FIELD

        if(h->slice_type==B_TYPE){

        }else{

            //FIXME second field balh

        }

    }

#ifdef TRACE

    for (i=0; i<h->ref_count[0]; i++) {

        tprintf("List0: %s fn:%d 0x%p\n", (h->default_ref_list[0][i].long_ref ? "LT" : "ST"), h->default_ref_list[0][i].pic_id, h->default_ref_list[0][i].data[0]);

    }

    if(h->slice_type==B_TYPE){

        for (i=0; i<h->ref_count[1]; i++) {

            tprintf("List1: %s fn:%d 0x%p\n", (h->default_ref_list[1][i].long_ref ? "LT" : "ST"), h->default_ref_list[1][i].pic_id, h->default_ref_list[0][i].data[0]);

        }

    }

#endif

    return 0;

}

static av_cold int read_specific_config(ALSDecContext *ctx)

{

    GetBitContext gb;

    uint64_t ht_size;

    int i, config_offset;

    MPEG4AudioConfig m4ac;

    ALSSpecificConfig *sconf = &ctx->sconf;

    AVCodecContext *avctx    = ctx->avctx;

    uint32_t als_id, header_size, trailer_size;



    init_get_bits(&gb, avctx->extradata, avctx->extradata_size * 8);



    config_offset = avpriv_mpeg4audio_get_config(&m4ac, avctx->extradata,

                                                 avctx->extradata_size * 8, 1);



    if (config_offset < 0)

        return -1;



    skip_bits_long(&gb, config_offset);



    if (get_bits_left(&gb) < (30 << 3))

        return -1;



    // read the fixed items

    als_id                      = get_bits_long(&gb, 32);

    avctx->sample_rate          = m4ac.sample_rate;

    skip_bits_long(&gb, 32); // sample rate already known

    sconf->samples              = get_bits_long(&gb, 32);

    avctx->channels             = m4ac.channels;

    skip_bits(&gb, 16);      // number of channels already knwon

    skip_bits(&gb, 3);       // skip file_type

    sconf->resolution           = get_bits(&gb, 3);

    sconf->floating             = get_bits1(&gb);

    sconf->msb_first            = get_bits1(&gb);

    sconf->frame_length         = get_bits(&gb, 16) + 1;

    sconf->ra_distance          = get_bits(&gb, 8);

    sconf->ra_flag              = get_bits(&gb, 2);

    sconf->adapt_order          = get_bits1(&gb);

    sconf->coef_table           = get_bits(&gb, 2);

    sconf->long_term_prediction = get_bits1(&gb);

    sconf->max_order            = get_bits(&gb, 10);

    sconf->block_switching      = get_bits(&gb, 2);

    sconf->bgmc                 = get_bits1(&gb);

    sconf->sb_part              = get_bits1(&gb);

    sconf->joint_stereo         = get_bits1(&gb);

    sconf->mc_coding            = get_bits1(&gb);

    sconf->chan_config          = get_bits1(&gb);

    sconf->chan_sort            = get_bits1(&gb);

    sconf->crc_enabled          = get_bits1(&gb);

    sconf->rlslms               = get_bits1(&gb);

    skip_bits(&gb, 5);       // skip 5 reserved bits

    skip_bits1(&gb);         // skip aux_data_enabled





    // check for ALSSpecificConfig struct

    if (als_id != MKBETAG('A','L','S','\0'))

        return -1;



    ctx->cur_frame_length = sconf->frame_length;



    // read channel config

    if (sconf->chan_config)

        sconf->chan_config_info = get_bits(&gb, 16);

    // TODO: use this to set avctx->channel_layout





    // read channel sorting

    if (sconf->chan_sort && avctx->channels > 1) {

        int chan_pos_bits = av_ceil_log2(avctx->channels);

        int bits_needed  = avctx->channels * chan_pos_bits + 7;

        if (get_bits_left(&gb) < bits_needed)

            return -1;



        if (!(sconf->chan_pos = av_malloc(avctx->channels * sizeof(*sconf->chan_pos))))

            return AVERROR(ENOMEM);



        for (i = 0; i < avctx->channels; i++) {

            sconf->chan_pos[i] = get_bits(&gb, chan_pos_bits);

            if (sconf->chan_pos[i] >= avctx->channels) {

                av_log(avctx, AV_LOG_WARNING, "Invalid original channel position.\n");

                sconf->chan_sort = 0;

                break;

            }

        }



        align_get_bits(&gb);

    } else {

        sconf->chan_sort = 0;

    }





    // read fixed header and trailer sizes,

    // if size = 0xFFFFFFFF then there is no data field!

    if (get_bits_left(&gb) < 64)

        return -1;



    header_size  = get_bits_long(&gb, 32);

    trailer_size = get_bits_long(&gb, 32);

    if (header_size  == 0xFFFFFFFF)

        header_size  = 0;

    if (trailer_size == 0xFFFFFFFF)

        trailer_size = 0;



    ht_size = ((int64_t)(header_size) + (int64_t)(trailer_size)) << 3;





    // skip the header and trailer data

    if (get_bits_left(&gb) < ht_size)

        return -1;



    if (ht_size > INT32_MAX)

        return -1;



    skip_bits_long(&gb, ht_size);





    // initialize CRC calculation

    if (sconf->crc_enabled) {

        if (get_bits_left(&gb) < 32)

            return -1;



        if (avctx->err_recognition & (AV_EF_CRCCHECK|AV_EF_CAREFUL)) {

            ctx->crc_table = av_crc_get_table(AV_CRC_32_IEEE_LE);

            ctx->crc       = 0xFFFFFFFF;

            ctx->crc_org   = ~get_bits_long(&gb, 32);

        } else

            skip_bits_long(&gb, 32);

    }





    // no need to read the rest of ALSSpecificConfig (ra_unit_size & aux data)



    dprint_specific_config(ctx);



    return 0;

}

static int dv_read_timecode(AVFormatContext *s) {

    int ret;

    char timecode[AV_TIMECODE_STR_SIZE];

    int64_t pos = avio_tell(s->pb);



    // Read 3 DIF blocks: Header block and 2 Subcode blocks.

    int partial_frame_size = 3 * 80;

    uint8_t *partial_frame = av_mallocz(sizeof(*partial_frame) *

                                        partial_frame_size);



    RawDVContext *c = s->priv_data;

    ret = avio_read(s->pb, partial_frame, partial_frame_size);

    if (ret < 0)

        goto finish;



    if (ret < partial_frame_size) {

        ret = -1;

        goto finish;

    }



    ret = dv_extract_timecode(c->dv_demux, partial_frame, timecode);

    if (ret)

        av_dict_set(&s->metadata, "timecode", timecode, 0);

    else if (ret < 0)

        av_log(s, AV_LOG_ERROR, "Detected timecode is invalid\n");



finish:

    av_free(partial_frame);

    avio_seek(s->pb, pos, SEEK_SET);

    return ret;

}

int ff_hls_write_file_entry(AVIOContext *out, int insert_discont,

                             int byterange_mode,

                             double duration, int round_duration,

                             int64_t size, int64_t pos, //Used only if HLS_SINGLE_FILE flag is set

                             char *baseurl, //Ignored if NULL

                             char *filename, double *prog_date_time) {

    if (!out || !filename)

        return AVERROR(EINVAL);



    if (insert_discont) {

        avio_printf(out, "#EXT-X-DISCONTINUITY\n");

    }

    if (round_duration)

        avio_printf(out, "#EXTINF:%ld,\n",  lrint(duration));

    else

        avio_printf(out, "#EXTINF:%f,\n", duration);

    if (byterange_mode)

        avio_printf(out, "#EXT-X-BYTERANGE:%"PRId64"@%"PRId64"\n", size, pos);



    if (prog_date_time) {

        time_t tt, wrongsecs;

        int milli;

        struct tm *tm, tmpbuf;

        char buf0[128], buf1[128];

        tt = (int64_t)*prog_date_time;

        milli = av_clip(lrint(1000*(*prog_date_time - tt)), 0, 999);

        tm = localtime_r(&tt, &tmpbuf);

        strftime(buf0, sizeof(buf0), "%Y-%m-%dT%H:%M:%S", tm);

        if (!strftime(buf1, sizeof(buf1), "%z", tm) || buf1[1]<'0' ||buf1[1]>'2') {

            int tz_min, dst = tm->tm_isdst;

            tm = gmtime_r(&tt, &tmpbuf);

            tm->tm_isdst = dst;

            wrongsecs = mktime(tm);

            tz_min = (FFABS(wrongsecs - tt) + 30) / 60;

            snprintf(buf1, sizeof(buf1),

                     "%c%02d%02d",

                     wrongsecs <= tt ? '+' : '-',

                     tz_min / 60,

                     tz_min % 60);

        }

        avio_printf(out, "#EXT-X-PROGRAM-DATE-TIME:%s.%03d%s\n", buf0, milli, buf1);

        *prog_date_time += duration;

    }

    if (baseurl)

        avio_printf(out, "%s", baseurl);

    avio_printf(out, "%s\n", filename);



    return 0;

}

static int svag_read_header(AVFormatContext *s)

{

    unsigned size, align;

    AVStream *st;



    avio_skip(s->pb, 4);



    st = avformat_new_stream(s, NULL);

    if (!st)

        return AVERROR(ENOMEM);



    size                   = avio_rl32(s->pb);

    st->codec->codec_type  = AVMEDIA_TYPE_AUDIO;

    st->codec->codec_id    = AV_CODEC_ID_ADPCM_PSX;

    st->codec->sample_rate = avio_rl32(s->pb);

    if (st->codec->sample_rate <= 0)

        return AVERROR_INVALIDDATA;

    st->codec->channels    = avio_rl32(s->pb);

    if (st->codec->channels <= 0)

        return AVERROR_INVALIDDATA;

    st->duration           = size / (16 * st->codec->channels) * 28;

    align                  = avio_rl32(s->pb);

    if (align <= 0 || align > INT_MAX / st->codec->channels)

        return AVERROR_INVALIDDATA;

    st->codec->block_align = align * st->codec->channels;

    avio_skip(s->pb, 0x800 - avio_tell(s->pb));

    avpriv_set_pts_info(st, 64, 1, st->codec->sample_rate);



    return 0;

}

int ff_mpeg_update_thread_context(AVCodecContext *dst,
                                  const AVCodecContext *src)
{
    int i;
    MpegEncContext *s = dst->priv_data, *s1 = src->priv_data;
    if (dst == src || !s1->context_initialized)
        return 0;
    // FIXME can parameters change on I-frames?
    // in that case dst may need a reinit
    if (!s->context_initialized) {
        memcpy(s, s1, sizeof(MpegEncContext));
        s->avctx                 = dst;
        s->picture_range_start  += MAX_PICTURE_COUNT;
        s->picture_range_end    += MAX_PICTURE_COUNT;
        s->bitstream_buffer      = NULL;
        s->bitstream_buffer_size = s->allocated_bitstream_buffer_size = 0;
        ff_MPV_common_init(s);
    }
    if (s->height != s1->height || s->width != s1->width || s->context_reinit) {
        int err;
        s->context_reinit = 0;
        s->height = s1->height;
        s->width  = s1->width;
        if ((err = ff_MPV_common_frame_size_change(s)) < 0)
            return err;
    }
    s->avctx->coded_height  = s1->avctx->coded_height;
    s->avctx->coded_width   = s1->avctx->coded_width;
    s->avctx->width         = s1->avctx->width;
    s->avctx->height        = s1->avctx->height;
    s->coded_picture_number = s1->coded_picture_number;
    s->picture_number       = s1->picture_number;
    s->input_picture_number = s1->input_picture_number;
    memcpy(s->picture, s1->picture, s1->picture_count * sizeof(Picture));
    memcpy(&s->last_picture, &s1->last_picture,
           (char *) &s1->last_picture_ptr - (char *) &s1->last_picture);
    s->last_picture_ptr    = REBASE_PICTURE(s1->last_picture_ptr,    s, s1);
    s->current_picture_ptr = REBASE_PICTURE(s1->current_picture_ptr, s, s1);
    s->next_picture_ptr    = REBASE_PICTURE(s1->next_picture_ptr,    s, s1);
    // Error/bug resilience
    s->next_p_frame_damaged = s1->next_p_frame_damaged;
    s->workaround_bugs      = s1->workaround_bugs;
    // MPEG4 timing info
    memcpy(&s->time_increment_bits, &s1->time_increment_bits,
           (char *) &s1->shape - (char *) &s1->time_increment_bits);
    // B-frame info
    s->max_b_frames = s1->max_b_frames;
    s->low_delay    = s1->low_delay;
    s->dropable     = s1->dropable;
    // DivX handling (doesn't work)
    s->divx_packed  = s1->divx_packed;
    if (s1->bitstream_buffer) {
        if (s1->bitstream_buffer_size +
            FF_INPUT_BUFFER_PADDING_SIZE > s->allocated_bitstream_buffer_size)
            av_fast_malloc(&s->bitstream_buffer,
                           &s->allocated_bitstream_buffer_size,
                           s1->allocated_bitstream_buffer_size);
            s->bitstream_buffer_size = s1->bitstream_buffer_size;
        memcpy(s->bitstream_buffer, s1->bitstream_buffer,
               s1->bitstream_buffer_size);
        memset(s->bitstream_buffer + s->bitstream_buffer_size, 0,
               FF_INPUT_BUFFER_PADDING_SIZE);
    }
    // MPEG2/interlacing info
    memcpy(&s->progressive_sequence, &s1->progressive_sequence,
           (char *) &s1->rtp_mode - (char *) &s1->progressive_sequence);
    if (!s1->first_field) {
        s->last_pict_type = s1->pict_type;
        if (s1->current_picture_ptr)
            s->last_lambda_for[s1->pict_type] = s1->current_picture_ptr->f.quality;
        if (s1->pict_type != AV_PICTURE_TYPE_B) {
            s->last_non_b_pict_type = s1->pict_type;
        }
    }
    return 0;
}

static void encode_rgb_frame(FFV1Context *s, uint8_t *src[3], int w, int h, int stride[3]){

    int x, y, p, i;

    const int ring_size= s->avctx->context_model ? 3 : 2;

    int16_t *sample[4][3];

    int lbd=  s->avctx->bits_per_raw_sample <= 8;

    int bits= s->avctx->bits_per_raw_sample > 0 ? s->avctx->bits_per_raw_sample : 8;

    int offset= 1 << bits;

    s->run_index=0;



    memset(s->sample_buffer, 0, ring_size*4*(w+6)*sizeof(*s->sample_buffer));



    for(y=0; y<h; y++){

        for(i=0; i<ring_size; i++)

            for(p=0; p<4; p++)

                sample[p][i]= s->sample_buffer + p*ring_size*(w+6) + ((h+i-y)%ring_size)*(w+6) + 3;



        for(x=0; x<w; x++){

            int b,g,r,a;

            if(lbd){

                unsigned v= *((uint32_t*)(src[0] + x*4 + stride[0]*y));

                b= v&0xFF;

                g= (v>>8)&0xFF;

                r= (v>>16)&0xFF;

                a=  v>>24;

            }else{

                b= *((uint16_t*)(src[0] + x*2 + stride[0]*y));

                g= *((uint16_t*)(src[1] + x*2 + stride[1]*y));

                r= *((uint16_t*)(src[2] + x*2 + stride[2]*y));

            }



            b -= g;

            r -= g;

            g += (b + r)>>2;

            b += offset;

            r += offset;



//            assert(g>=0 && b>=0 && r>=0);

//            assert(g<256 && b<512 && r<512);

            sample[0][0][x]= g;

            sample[1][0][x]= b;

            sample[2][0][x]= r;

            sample[3][0][x]= a;

        }

        for(p=0; p<3 + s->transparency; p++){

            sample[p][0][-1]= sample[p][1][0  ];

            sample[p][1][ w]= sample[p][1][w-1];

            if (lbd)

                encode_line(s, w, sample[p], (p+1)/2, 9);

            else

                encode_line(s, w, sample[p], (p+1)/2, bits+1);

        }

    }

}

static int decode_init(AVCodecContext * avctx)

{

    MPADecodeContext *s = avctx->priv_data;

    static int init=0;

    int i, j, k;



#if defined(USE_HIGHPRECISION) && defined(CONFIG_AUDIO_NONSHORT)

    avctx->sample_fmt= SAMPLE_FMT_S32;

#else

    avctx->sample_fmt= SAMPLE_FMT_S16;

#endif    



    if(avctx->antialias_algo != FF_AA_FLOAT)

        s->compute_antialias= compute_antialias_integer;

    else

        s->compute_antialias= compute_antialias_float;



    if (!init && !avctx->parse_only) {

        /* scale factors table for layer 1/2 */

        for(i=0;i<64;i++) {

            int shift, mod;

            /* 1.0 (i = 3) is normalized to 2 ^ FRAC_BITS */

            shift = (i / 3);

            mod = i % 3;

            scale_factor_modshift[i] = mod | (shift << 2);

        }



        /* scale factor multiply for layer 1 */

        for(i=0;i<15;i++) {

            int n, norm;

            n = i + 2;

            norm = ((int64_t_C(1) << n) * FRAC_ONE) / ((1 << n) - 1);

            scale_factor_mult[i][0] = MULL(FIXR(1.0 * 2.0), norm);

            scale_factor_mult[i][1] = MULL(FIXR(0.7937005259 * 2.0), norm);

            scale_factor_mult[i][2] = MULL(FIXR(0.6299605249 * 2.0), norm);

            dprintf("%d: norm=%x s=%x %x %x\n",

                    i, norm, 

                    scale_factor_mult[i][0],

                    scale_factor_mult[i][1],

                    scale_factor_mult[i][2]);

        }



	ff_mpa_synth_init(window);



        /* huffman decode tables */

        huff_code_table[0] = NULL;

        for(i=1;i<16;i++) {

            const HuffTable *h = &mpa_huff_tables[i];

	    int xsize, x, y;

            unsigned int n;

            uint8_t *code_table;



            xsize = h->xsize;

            n = xsize * xsize;

            /* XXX: fail test */

            init_vlc(&huff_vlc[i], 8, n, 

                     h->bits, 1, 1, h->codes, 2, 2, 1);



            code_table = av_mallocz(n);

            j = 0;

            for(x=0;x<xsize;x++) {

                for(y=0;y<xsize;y++)

                    code_table[j++] = (x << 4) | y;

            }

            huff_code_table[i] = code_table;

        }

        for(i=0;i<2;i++) {

            init_vlc(&huff_quad_vlc[i], i == 0 ? 7 : 4, 16, 

                     mpa_quad_bits[i], 1, 1, mpa_quad_codes[i], 1, 1, 1);

        }



        for(i=0;i<9;i++) {

            k = 0;

            for(j=0;j<22;j++) {

                band_index_long[i][j] = k;

                k += band_size_long[i][j];

            }

            band_index_long[i][22] = k;

        }



	/* compute n ^ (4/3) and store it in mantissa/exp format */

	table_4_3_exp= av_mallocz_static(TABLE_4_3_SIZE * sizeof(table_4_3_exp[0]));

        if(!table_4_3_exp)

	    return -1;

	table_4_3_value= av_mallocz_static(TABLE_4_3_SIZE * sizeof(table_4_3_value[0]));

        if(!table_4_3_value)

            return -1;



        int_pow_init();

        for(i=1;i<TABLE_4_3_SIZE;i++) {

            double f, fm;

            int e, m;

            f = pow((double)(i/4), 4.0 / 3.0) * pow(2, (i&3)*0.25);

            fm = frexp(f, &e);

            m = FIXHR(fm*0.5);

            e+= FRAC_BITS - 31;



            /* normalized to FRAC_BITS */

            table_4_3_value[i] = m;

//            av_log(NULL, AV_LOG_DEBUG, "%d %d %f\n", i, m, pow((double)i, 4.0 / 3.0));

            table_4_3_exp[i] = -e;

        }



        for(i=0;i<7;i++) {

            float f;

            int v;

            if (i != 6) {

                f = tan((double)i * M_PI / 12.0);

                v = FIXR(f / (1.0 + f));

            } else {

                v = FIXR(1.0);

            }

            is_table[0][i] = v;

            is_table[1][6 - i] = v;

        }

        /* invalid values */

        for(i=7;i<16;i++)

            is_table[0][i] = is_table[1][i] = 0.0;



        for(i=0;i<16;i++) {

            double f;

            int e, k;



            for(j=0;j<2;j++) {

                e = -(j + 1) * ((i + 1) >> 1);

                f = pow(2.0, e / 4.0);

                k = i & 1;

                is_table_lsf[j][k ^ 1][i] = FIXR(f);

                is_table_lsf[j][k][i] = FIXR(1.0);

                dprintf("is_table_lsf %d %d: %x %x\n", 

                        i, j, is_table_lsf[j][0][i], is_table_lsf[j][1][i]);

            }

        }



        for(i=0;i<8;i++) {

            float ci, cs, ca;

            ci = ci_table[i];

            cs = 1.0 / sqrt(1.0 + ci * ci);

            ca = cs * ci;

            csa_table[i][0] = FIXHR(cs/4);

            csa_table[i][1] = FIXHR(ca/4);

            csa_table[i][2] = FIXHR(ca/4) + FIXHR(cs/4);

            csa_table[i][3] = FIXHR(ca/4) - FIXHR(cs/4); 

            csa_table_float[i][0] = cs;

            csa_table_float[i][1] = ca;

            csa_table_float[i][2] = ca + cs;

            csa_table_float[i][3] = ca - cs; 

//            printf("%d %d %d %d\n", FIX(cs), FIX(cs-1), FIX(ca), FIX(cs)-FIX(ca));

//            av_log(NULL, AV_LOG_DEBUG,"%f %f %f %f\n", cs, ca, ca+cs, ca-cs);

        }



        /* compute mdct windows */

        for(i=0;i<36;i++) {

            for(j=0; j<4; j++){

                double d;



                if(j==2 && i%3 != 1)

                    continue;



                d= sin(M_PI * (i + 0.5) / 36.0);

                if(j==1){

                    if     (i>=30) d= 0;

                    else if(i>=24) d= sin(M_PI * (i - 18 + 0.5) / 12.0);

                    else if(i>=18) d= 1;

                }else if(j==3){

                    if     (i<  6) d= 0;

                    else if(i< 12) d= sin(M_PI * (i -  6 + 0.5) / 12.0);

                    else if(i< 18) d= 1;

                }

                //merge last stage of imdct into the window coefficients

                d*= 0.5 / cos(M_PI*(2*i + 19)/72);



                if(j==2)

                    mdct_win[j][i/3] = FIXHR((d / (1<<5)));

                else

                    mdct_win[j][i  ] = FIXHR((d / (1<<5)));

//                av_log(NULL, AV_LOG_DEBUG, "%2d %d %f\n", i,j,d / (1<<5));

            }

        }



        /* NOTE: we do frequency inversion adter the MDCT by changing

           the sign of the right window coefs */

        for(j=0;j<4;j++) {

            for(i=0;i<36;i+=2) {

                mdct_win[j + 4][i] = mdct_win[j][i];

                mdct_win[j + 4][i + 1] = -mdct_win[j][i + 1];

            }

        }



#if defined(DEBUG)

        for(j=0;j<8;j++) {

            printf("win%d=\n", j);

            for(i=0;i<36;i++)

                printf("%f, ", (double)mdct_win[j][i] / FRAC_ONE);

            printf("\n");

        }

#endif

        init = 1;

    }



    s->inbuf_index = 0;

    s->inbuf = &s->inbuf1[s->inbuf_index][BACKSTEP_SIZE];

    s->inbuf_ptr = s->inbuf;

#ifdef DEBUG

    s->frame_count = 0;

#endif

    if (avctx->codec_id == CODEC_ID_MP3ADU)

        s->adu_mode = 1;

    return 0;

}

