    av_free(x4->sei);



    if (x4->enc)

        x264_encoder_close(x4->enc);



    av_frame_free(&avctx->coded_frame);



    return 0;

}

static int aiff_read_header(AVFormatContext *s,

                            AVFormatParameters *ap)

{

    int size, filesize;

    offset_t offset = 0;

    uint32_t tag;

    unsigned version = AIFF_C_VERSION1;

    ByteIOContext *pb = s->pb;

    AVStream * st = s->streams[0];



    /* check FORM header */

    filesize = get_tag(pb, &tag);

    if (filesize < 0 || tag != MKTAG('F', 'O', 'R', 'M'))

        return AVERROR_INVALIDDATA;



    /* AIFF data type */

    tag = get_le32(pb);

    if (tag == MKTAG('A', 'I', 'F', 'F'))       /* Got an AIFF file */

        version = AIFF;

    else if (tag != MKTAG('A', 'I', 'F', 'C'))  /* An AIFF-C file then */

        return AVERROR_INVALIDDATA;



    filesize -= 4;



    st = av_new_stream(s, 0);

    if (!st)

        return AVERROR(ENOMEM);



    while (filesize > 0) {

        /* parse different chunks */

        size = get_tag(pb, &tag);

        if (size < 0)

            return size;



        filesize -= size + 8;



        switch (tag) {

        case MKTAG('C', 'O', 'M', 'M'):     /* Common chunk */

            /* Then for the complete header info */

            st->nb_frames = get_aiff_header (pb, st->codec, size, version);

            if (st->nb_frames < 0)

                return st->nb_frames;

            if (offset > 0) // COMM is after SSND

                goto got_sound;

            break;

        case MKTAG('F', 'V', 'E', 'R'):     /* Version chunk */

            version = get_be32(pb);

            break;

        case MKTAG('N', 'A', 'M', 'E'):     /* Sample name chunk */

            get_meta (pb, s->title, sizeof(s->title), size);

            break;

        case MKTAG('A', 'U', 'T', 'H'):     /* Author chunk */

            get_meta (pb, s->author, sizeof(s->author), size);

            break;

        case MKTAG('(', 'c', ')', ' '):     /* Copyright chunk */

            get_meta (pb, s->copyright, sizeof(s->copyright), size);

            break;

        case MKTAG('A', 'N', 'N', 'O'):     /* Annotation chunk */

            get_meta (pb, s->comment, sizeof(s->comment), size);

            break;

        case MKTAG('S', 'S', 'N', 'D'):     /* Sampled sound chunk */

            offset = get_be32(pb);      /* Offset of sound data */

            get_be32(pb);               /* BlockSize... don't care */

            offset += url_ftell(pb);    /* Compute absolute data offset */

            if (st->codec->codec_id)    /* Assume COMM already parsed */

                goto got_sound;

            if (url_is_streamed(pb)) {

                av_log(s, AV_LOG_ERROR, "file is not seekable\n");


            }

            url_fskip(pb, size - 8);

            break;

        case MKTAG('w', 'a', 'v', 'e'):



            st->codec->extradata = av_mallocz(size + FF_INPUT_BUFFER_PADDING_SIZE);

            if (!st->codec->extradata)

                return AVERROR(ENOMEM);

            st->codec->extradata_size = size;

            get_buffer(pb, st->codec->extradata, size);

            break;

        default: /* Jump */

            if (size & 1)   /* Always even aligned */

                size++;

            url_fskip (pb, size);

        }

    }



    /* End of loop and didn't get sound */

    return AVERROR_INVALIDDATA;



got_sound:

    /* Now positioned, get the sound data start and end */

    if (st->nb_frames)

        s->file_size = st->nb_frames * st->codec->block_align;



    av_set_pts_info(st, 64, 1, st->codec->sample_rate);

    st->start_time = 0;

    st->duration = st->codec->frame_size ?

        st->nb_frames * st->codec->frame_size : st->nb_frames;



    /* Position the stream at the first block */

    url_fseek(pb, offset, SEEK_SET);



    return 0;

}

static int start_frame_overlay(AVFilterLink *inlink, AVFilterBufferRef *inpicref)

{

    AVFilterContext *ctx = inlink->dst;

    OverlayContext *over = ctx->priv;



    inlink->cur_buf  = NULL;


    over->overpicref = inpicref;

    over->overpicref->pts = av_rescale_q(inpicref->pts, ctx->inputs[OVERLAY]->time_base,

                                         ctx->outputs[0]->time_base);

    return 0;

}

static av_cold int X264_init(AVCodecContext *avctx)

{

    X264Context *x4 = avctx->priv_data;

    int sw,sh;



    if (avctx->global_quality > 0)

        av_log(avctx, AV_LOG_WARNING, "-qscale is ignored, -crf is recommended.\n");



    x264_param_default(&x4->params);



    x4->params.b_deblocking_filter         = avctx->flags & CODEC_FLAG_LOOP_FILTER;



    if (x4->preset || x4->tune)

        if (x264_param_default_preset(&x4->params, x4->preset, x4->tune) < 0) {

            int i;

            av_log(avctx, AV_LOG_ERROR, "Error setting preset/tune %s/%s.\n", x4->preset, x4->tune);

            av_log(avctx, AV_LOG_INFO, "Possible presets:");

            for (i = 0; x264_preset_names[i]; i++)

                av_log(avctx, AV_LOG_INFO, " %s", x264_preset_names[i]);

            av_log(avctx, AV_LOG_INFO, "\n");

            av_log(avctx, AV_LOG_INFO, "Possible tunes:");

            for (i = 0; x264_tune_names[i]; i++)

                av_log(avctx, AV_LOG_INFO, " %s", x264_tune_names[i]);

            av_log(avctx, AV_LOG_INFO, "\n");

            return AVERROR(EINVAL);

        }



    if (avctx->level > 0)

        x4->params.i_level_idc = avctx->level;



    x4->params.pf_log               = X264_log;

    x4->params.p_log_private        = avctx;

    x4->params.i_log_level          = X264_LOG_DEBUG;

    x4->params.i_csp                = convert_pix_fmt(avctx->pix_fmt);



    OPT_STR("weightp", x4->wpredp);



    if (avctx->bit_rate) {

        x4->params.rc.i_bitrate   = avctx->bit_rate / 1000;

        x4->params.rc.i_rc_method = X264_RC_ABR;

    }

    x4->params.rc.i_vbv_buffer_size = avctx->rc_buffer_size / 1000;

    x4->params.rc.i_vbv_max_bitrate = avctx->rc_max_rate    / 1000;

    x4->params.rc.b_stat_write      = avctx->flags & CODEC_FLAG_PASS1;

    if (avctx->flags & CODEC_FLAG_PASS2) {

        x4->params.rc.b_stat_read = 1;

    } else {

        if (x4->crf >= 0) {

            x4->params.rc.i_rc_method   = X264_RC_CRF;

            x4->params.rc.f_rf_constant = x4->crf;

        } else if (x4->cqp >= 0) {

            x4->params.rc.i_rc_method   = X264_RC_CQP;

            x4->params.rc.i_qp_constant = x4->cqp;

        }



        if (x4->crf_max >= 0)

            x4->params.rc.f_rf_constant_max = x4->crf_max;

    }



    if (avctx->rc_buffer_size && avctx->rc_initial_buffer_occupancy > 0 &&

        (avctx->rc_initial_buffer_occupancy <= avctx->rc_buffer_size)) {

        x4->params.rc.f_vbv_buffer_init =

            (float)avctx->rc_initial_buffer_occupancy / avctx->rc_buffer_size;

    }



    OPT_STR("level", x4->level);



    if (avctx->i_quant_factor > 0)

        x4->params.rc.f_ip_factor         = 1 / fabs(avctx->i_quant_factor);

    if (avctx->b_quant_factor > 0)

        x4->params.rc.f_pb_factor         = avctx->b_quant_factor;

    if (avctx->chromaoffset)

        x4->params.analyse.i_chroma_qp_offset = avctx->chromaoffset;



    if (avctx->me_method == ME_EPZS)

        x4->params.analyse.i_me_method = X264_ME_DIA;

    else if (avctx->me_method == ME_HEX)

        x4->params.analyse.i_me_method = X264_ME_HEX;

    else if (avctx->me_method == ME_UMH)

        x4->params.analyse.i_me_method = X264_ME_UMH;

    else if (avctx->me_method == ME_FULL)

        x4->params.analyse.i_me_method = X264_ME_ESA;

    else if (avctx->me_method == ME_TESA)

        x4->params.analyse.i_me_method = X264_ME_TESA;



    if (avctx->gop_size >= 0)

        x4->params.i_keyint_max         = avctx->gop_size;

    if (avctx->max_b_frames >= 0)

        x4->params.i_bframe             = avctx->max_b_frames;

    if (avctx->scenechange_threshold >= 0)

        x4->params.i_scenecut_threshold = avctx->scenechange_threshold;

    if (avctx->qmin >= 0)

        x4->params.rc.i_qp_min          = avctx->qmin;

    if (avctx->qmax >= 0)

        x4->params.rc.i_qp_max          = avctx->qmax;

    if (avctx->max_qdiff >= 0)

        x4->params.rc.i_qp_step         = avctx->max_qdiff;

    if (avctx->qblur >= 0)

        x4->params.rc.f_qblur           = avctx->qblur;     /* temporally blur quants */

    if (avctx->qcompress >= 0)

        x4->params.rc.f_qcompress       = avctx->qcompress; /* 0.0 => cbr, 1.0 => constant qp */

    if (avctx->refs >= 0)

        x4->params.i_frame_reference    = avctx->refs;

    else if (x4->level) {

        int i;

        int mbn = FF_CEIL_RSHIFT(avctx->width, 4) * FF_CEIL_RSHIFT(avctx->height, 4);

        int level_id = -1;

        char *tail;

        int scale = X264_BUILD < 129 ? 384 : 1;



        if (!strcmp(x4->level, "1b")) {

            level_id = 9;

        } else if (strlen(x4->level) <= 3){

            level_id = av_strtod(x4->level, &tail) * 10 + 0.5;

            if (*tail)

                level_id = -1;

        }

        if (level_id <= 0)

            av_log(avctx, AV_LOG_WARNING, "Failed to parse level\n");



        for (i = 0; i<x264_levels[i].level_idc; i++)

            if (x264_levels[i].level_idc == level_id)

                x4->params.i_frame_reference = av_clip(x264_levels[i].dpb / mbn / scale, 1, x4->params.i_frame_reference);

    }



    if (avctx->trellis >= 0)

        x4->params.analyse.i_trellis    = avctx->trellis;

    if (avctx->me_range >= 0)

        x4->params.analyse.i_me_range   = avctx->me_range;

    if (avctx->noise_reduction >= 0)

        x4->params.analyse.i_noise_reduction = avctx->noise_reduction;

    if (avctx->me_subpel_quality >= 0)

        x4->params.analyse.i_subpel_refine   = avctx->me_subpel_quality;

    if (avctx->b_frame_strategy >= 0)

        x4->params.i_bframe_adaptive = avctx->b_frame_strategy;

    if (avctx->keyint_min >= 0)

        x4->params.i_keyint_min = avctx->keyint_min;

    if (avctx->coder_type >= 0)

        x4->params.b_cabac = avctx->coder_type == FF_CODER_TYPE_AC;

    if (avctx->me_cmp >= 0)

        x4->params.analyse.b_chroma_me = avctx->me_cmp & FF_CMP_CHROMA;



    if (x4->aq_mode >= 0)

        x4->params.rc.i_aq_mode = x4->aq_mode;

    if (x4->aq_strength >= 0)

        x4->params.rc.f_aq_strength = x4->aq_strength;

    PARSE_X264_OPT("psy-rd", psy_rd);

    PARSE_X264_OPT("deblock", deblock);

    PARSE_X264_OPT("partitions", partitions);

    PARSE_X264_OPT("stats", stats);

    if (x4->psy >= 0)

        x4->params.analyse.b_psy  = x4->psy;

    if (x4->rc_lookahead >= 0)

        x4->params.rc.i_lookahead = x4->rc_lookahead;

    if (x4->weightp >= 0)

        x4->params.analyse.i_weighted_pred = x4->weightp;

    if (x4->weightb >= 0)

        x4->params.analyse.b_weighted_bipred = x4->weightb;

    if (x4->cplxblur >= 0)

        x4->params.rc.f_complexity_blur = x4->cplxblur;



    if (x4->ssim >= 0)

        x4->params.analyse.b_ssim = x4->ssim;

    if (x4->intra_refresh >= 0)

        x4->params.b_intra_refresh = x4->intra_refresh;

    if (x4->bluray_compat >= 0) {

        x4->params.b_bluray_compat = x4->bluray_compat;

        x4->params.b_vfr_input = 0;

    }

    if (x4->avcintra_class >= 0)

#if X264_BUILD >= 142

        x4->params.i_avcintra_class = x4->avcintra_class;

#else

        av_log(avctx, AV_LOG_ERROR,

               "x264 too old for AVC Intra, at least version 142 needed\n");

#endif

    if (x4->b_bias != INT_MIN)

        x4->params.i_bframe_bias              = x4->b_bias;

    if (x4->b_pyramid >= 0)

        x4->params.i_bframe_pyramid = x4->b_pyramid;

    if (x4->mixed_refs >= 0)

        x4->params.analyse.b_mixed_references = x4->mixed_refs;

    if (x4->dct8x8 >= 0)

        x4->params.analyse.b_transform_8x8    = x4->dct8x8;

    if (x4->fast_pskip >= 0)

        x4->params.analyse.b_fast_pskip       = x4->fast_pskip;

    if (x4->aud >= 0)

        x4->params.b_aud                      = x4->aud;

    if (x4->mbtree >= 0)

        x4->params.rc.b_mb_tree               = x4->mbtree;

    if (x4->direct_pred >= 0)

        x4->params.analyse.i_direct_mv_pred   = x4->direct_pred;



    if (x4->slice_max_size >= 0)

        x4->params.i_slice_max_size =  x4->slice_max_size;

    else {

        /*

         * Allow x264 to be instructed through AVCodecContext about the maximum

         * size of the RTP payload. For example, this enables the production of

         * payload suitable for the H.264 RTP packetization-mode 0 i.e. single

         * NAL unit per RTP packet.

         */

        if (avctx->rtp_payload_size)

            x4->params.i_slice_max_size = avctx->rtp_payload_size;

    }



    if (x4->fastfirstpass)

        x264_param_apply_fastfirstpass(&x4->params);



    /* Allow specifying the x264 profile through AVCodecContext. */

    if (!x4->profile)

        switch (avctx->profile) {

        case FF_PROFILE_H264_BASELINE:

            x4->profile = av_strdup("baseline");

            break;

        case FF_PROFILE_H264_HIGH:

            x4->profile = av_strdup("high");

            break;

        case FF_PROFILE_H264_HIGH_10:

            x4->profile = av_strdup("high10");

            break;

        case FF_PROFILE_H264_HIGH_422:

            x4->profile = av_strdup("high422");

            break;

        case FF_PROFILE_H264_HIGH_444:

            x4->profile = av_strdup("high444");

            break;

        case FF_PROFILE_H264_MAIN:

            x4->profile = av_strdup("main");

            break;

        default:

            break;

        }



    if (x4->nal_hrd >= 0)

        x4->params.i_nal_hrd = x4->nal_hrd;



    if (x4->profile)

        if (x264_param_apply_profile(&x4->params, x4->profile) < 0) {

            int i;

            av_log(avctx, AV_LOG_ERROR, "Error setting profile %s.\n", x4->profile);

            av_log(avctx, AV_LOG_INFO, "Possible profiles:");

            for (i = 0; x264_profile_names[i]; i++)

                av_log(avctx, AV_LOG_INFO, " %s", x264_profile_names[i]);

            av_log(avctx, AV_LOG_INFO, "\n");

            return AVERROR(EINVAL);

        }



    x4->params.i_width          = avctx->width;

    x4->params.i_height         = avctx->height;

    av_reduce(&sw, &sh, avctx->sample_aspect_ratio.num, avctx->sample_aspect_ratio.den, 4096);

    x4->params.vui.i_sar_width  = sw;

    x4->params.vui.i_sar_height = sh;

    x4->params.i_timebase_den = avctx->time_base.den;

    x4->params.i_timebase_num = avctx->time_base.num;

    x4->params.i_fps_num = avctx->time_base.den;

    x4->params.i_fps_den = avctx->time_base.num * avctx->ticks_per_frame;



    x4->params.analyse.b_psnr = avctx->flags & CODEC_FLAG_PSNR;



    x4->params.i_threads      = avctx->thread_count;

    if (avctx->thread_type)

        x4->params.b_sliced_threads = avctx->thread_type == FF_THREAD_SLICE;



    x4->params.b_interlaced   = avctx->flags & CODEC_FLAG_INTERLACED_DCT;



    x4->params.b_open_gop     = !(avctx->flags & CODEC_FLAG_CLOSED_GOP);



    x4->params.i_slice_count  = avctx->slices;



    x4->params.vui.b_fullrange = avctx->pix_fmt == AV_PIX_FMT_YUVJ420P ||

                                 avctx->pix_fmt == AV_PIX_FMT_YUVJ422P ||

                                 avctx->pix_fmt == AV_PIX_FMT_YUVJ444P ||

                                 avctx->color_range == AVCOL_RANGE_JPEG;



    if (avctx->colorspace != AVCOL_SPC_UNSPECIFIED)

        x4->params.vui.i_colmatrix = avctx->colorspace;

    if (avctx->color_primaries != AVCOL_PRI_UNSPECIFIED)

        x4->params.vui.i_colorprim = avctx->color_primaries;

    if (avctx->color_trc != AVCOL_TRC_UNSPECIFIED)

        x4->params.vui.i_transfer  = avctx->color_trc;



    if (avctx->flags & CODEC_FLAG_GLOBAL_HEADER)

        x4->params.b_repeat_headers = 0;



    if(x4->x264opts){

        const char *p= x4->x264opts;

        while(p){

            char param[256]={0}, val[256]={0};

            if(sscanf(p, "%255[^:=]=%255[^:]", param, val) == 1){

                OPT_STR(param, "1");

            }else

                OPT_STR(param, val);

            p= strchr(p, ':');

            p+=!!p;

        }

    }



    if (x4->x264_params) {

        AVDictionary *dict    = NULL;

        AVDictionaryEntry *en = NULL;



        if (!av_dict_parse_string(&dict, x4->x264_params, "=", ":", 0)) {

            while ((en = av_dict_get(dict, "", en, AV_DICT_IGNORE_SUFFIX))) {

                if (x264_param_parse(&x4->params, en->key, en->value) < 0)

                    av_log(avctx, AV_LOG_WARNING,

                           "Error parsing option '%s = %s'.\n",

                            en->key, en->value);

            }



            av_dict_free(&dict);

        }

    }



    // update AVCodecContext with x264 parameters

    avctx->has_b_frames = x4->params.i_bframe ?

        x4->params.i_bframe_pyramid ? 2 : 1 : 0;

    if (avctx->max_b_frames < 0)

        avctx->max_b_frames = 0;



    avctx->bit_rate = x4->params.rc.i_bitrate*1000;



    x4->enc = x264_encoder_open(&x4->params);

    if (!x4->enc)

        return -1;



    avctx->coded_frame = av_frame_alloc();

    if (!avctx->coded_frame)

        return AVERROR(ENOMEM);



    if (avctx->flags & CODEC_FLAG_GLOBAL_HEADER) {

        x264_nal_t *nal;

        uint8_t *p;

        int nnal, s, i;



        s = x264_encoder_headers(x4->enc, &nal, &nnal);

        avctx->extradata = p = av_malloc(s);





        for (i = 0; i < nnal; i++) {

            /* Don't put the SEI in extradata. */

            if (nal[i].i_type == NAL_SEI) {

                av_log(avctx, AV_LOG_INFO, "%s\n", nal[i].p_payload+25);

                x4->sei_size = nal[i].i_payload;

                x4->sei      = av_malloc(x4->sei_size);

                if (!x4->sei)


                memcpy(x4->sei, nal[i].p_payload, nal[i].i_payload);

                continue;

            }

            memcpy(p, nal[i].p_payload, nal[i].i_payload);

            p += nal[i].i_payload;

        }

        avctx->extradata_size = p - avctx->extradata;

    }



    return 0;

nomem:

    X264_close(avctx);

    return AVERROR(ENOMEM);

}

static float quantize_and_encode_band_cost(struct AACEncContext *s,

                                PutBitContext *pb, const float *in,

                                const float *scaled, int size, int scale_idx,

                                int cb, const float lambda, const float uplim,

                                int *bits)

{

    const float IQ = ff_aac_pow2sf_tab[200 + scale_idx - SCALE_ONE_POS + SCALE_DIV_512];

    const float  Q = ff_aac_pow2sf_tab[200 - scale_idx + SCALE_ONE_POS - SCALE_DIV_512];

    const float CLIPPED_ESCAPE = 165140.0f*IQ;

    int i, j, k;

    float cost = 0;

    const int dim = cb < FIRST_PAIR_BT ? 4 : 2;

    int resbits = 0;

#ifndef USE_REALLY_FULL_SEARCH

    const float  Q34 = sqrtf(Q * sqrtf(Q));

    const int range  = aac_cb_range[cb];

    const int maxval = aac_cb_maxval[cb];

    int offs[4];

#endif /* USE_REALLY_FULL_SEARCH */



    if (!cb) {

        for (i = 0; i < size; i++)

            cost += in[i]*in[i];

        if (bits)

            *bits = 0;

        return cost * lambda;

    }

#ifndef USE_REALLY_FULL_SEARCH

    offs[0] = 1;

    for (i = 1; i < dim; i++)

        offs[i] = offs[i-1]*range;

    if (!scaled) {

        abs_pow34_v(s->scoefs, in, size);

        scaled = s->scoefs;

    }

    quantize_bands(s->qcoefs, in, scaled, size, Q34, !IS_CODEBOOK_UNSIGNED(cb), maxval);

#endif /* USE_REALLY_FULL_SEARCH */

    for (i = 0; i < size; i += dim) {

        float mincost;

        int minidx  = 0;

        int minbits = 0;

        const float *vec;

#ifndef USE_REALLY_FULL_SEARCH

        int (*quants)[2] = &s->qcoefs[i];

        mincost = 0.0f;

        for (j = 0; j < dim; j++)

            mincost += in[i+j]*in[i+j];

        minidx = IS_CODEBOOK_UNSIGNED(cb) ? 0 : 40;

        minbits = ff_aac_spectral_bits[cb-1][minidx];

        mincost = mincost * lambda + minbits;

        for (j = 0; j < (1<<dim); j++) {

            float rd = 0.0f;

            int curbits;

            int curidx = IS_CODEBOOK_UNSIGNED(cb) ? 0 : 40;

            int same   = 0;

            for (k = 0; k < dim; k++) {

                if ((j & (1 << k)) && quants[k][0] == quants[k][1]) {

                    same = 1;

                    break;

                }

            }

            if (same)

                continue;

            for (k = 0; k < dim; k++)

                curidx += quants[k][!!(j & (1 << k))] * offs[dim - 1 - k];

            curbits =  ff_aac_spectral_bits[cb-1][curidx];

            vec     = &ff_aac_codebook_vectors[cb-1][curidx*dim];

#else

        mincost = INFINITY;

        vec = ff_aac_codebook_vectors[cb-1];

        for (j = 0; j < ff_aac_spectral_sizes[cb-1]; j++, vec += dim) {

            float rd = 0.0f;

            int curbits = ff_aac_spectral_bits[cb-1][j];

            int curidx = j;

#endif /* USE_REALLY_FULL_SEARCH */

            if (IS_CODEBOOK_UNSIGNED(cb)) {

                for (k = 0; k < dim; k++) {

                    float t = fabsf(in[i+k]);

                    float di;

                    if (vec[k] == 64.0f) { //FIXME: slow

                        //do not code with escape sequence small values

                        if (t < 39.0f*IQ) {

                            rd = INFINITY;

                            break;

                        }

                        if (t >= CLIPPED_ESCAPE) {

                            di = t - CLIPPED_ESCAPE;

                            curbits += 21;

                        } else {

                            int c = av_clip(quant(t, Q), 0, 8191);

                            di = t - c*cbrtf(c)*IQ;

                            curbits += av_log2(c)*2 - 4 + 1;

                        }

                    } else {

                        di = t - vec[k]*IQ;

                    }

                    if (vec[k] != 0.0f)

                        curbits++;

                    rd += di*di;

                }

            } else {

                for (k = 0; k < dim; k++) {

                    float di = in[i+k] - vec[k]*IQ;

                    rd += di*di;

                }

            }

            rd = rd * lambda + curbits;

            if (rd < mincost) {

                mincost = rd;

                minidx  = curidx;

                minbits = curbits;

            }

        }

        cost    += mincost;

        resbits += minbits;

        if (cost >= uplim)

            return uplim;

        if (pb) {

        put_bits(pb, ff_aac_spectral_bits[cb-1][minidx], ff_aac_spectral_codes[cb-1][minidx]);

        if (IS_CODEBOOK_UNSIGNED(cb))

            for (j = 0; j < dim; j++)

                if (ff_aac_codebook_vectors[cb-1][minidx*dim+j] != 0.0f)

                    put_bits(pb, 1, in[i+j] < 0.0f);

        if (cb == ESC_BT) {

            for (j = 0; j < 2; j++) {

                if (ff_aac_codebook_vectors[cb-1][minidx*2+j] == 64.0f) {

                    int coef = av_clip(quant(fabsf(in[i+j]), Q), 0, 8191);

                    int len = av_log2(coef);



                    put_bits(pb, len - 4 + 1, (1 << (len - 4 + 1)) - 2);

                    put_bits(pb, len, coef & ((1 << len) - 1));

                }

            }

        }

        }

    }



    if (bits)

        *bits = resbits;

    return cost;

}

int ff_h264_execute_decode_slices(H264Context *h, unsigned context_count)

{

    AVCodecContext *const avctx = h->avctx;

    H264SliceContext *sl;

    int i;



    av_assert0(context_count && h->slice_ctx[context_count - 1].mb_y < h->mb_height);



    if (h->avctx->hwaccel ||

        h->avctx->codec->capabilities & CODEC_CAP_HWACCEL_VDPAU)

        return 0;

    if (context_count == 1) {

        int ret = decode_slice(avctx, &h->slice_ctx[0]);

        h->mb_y = h->slice_ctx[0].mb_y;

        return ret;

    } else {

        av_assert0(context_count > 0);

        for (i = 1; i < context_count; i++) {

            sl                 = &h->slice_ctx[i];

            if (CONFIG_ERROR_RESILIENCE) {

                sl->er.error_count = 0;

            }

        }



        avctx->execute(avctx, decode_slice, h->slice_ctx,

                       NULL, context_count, sizeof(h->slice_ctx[0]));



        /* pull back stuff from slices to master context */

        sl                   = &h->slice_ctx[context_count - 1];

        h->mb_y              = sl->mb_y;

        if (CONFIG_ERROR_RESILIENCE) {

            for (i = 1; i < context_count; i++)

                h->slice_ctx[0].er.error_count += h->slice_ctx[i].er.error_count;

        }

    }



    return 0;

}

static int lag_decode_frame(AVCodecContext *avctx,

                            void *data, int *data_size, AVPacket *avpkt)

{

    const uint8_t *buf = avpkt->data;

    int buf_size = avpkt->size;

    LagarithContext *l = avctx->priv_data;

    AVFrame *const p = &l->picture;

    uint8_t frametype = 0;

    uint32_t offset_gu = 0, offset_bv = 0, offset_ry = 9;

    uint32_t offs[4];

    uint8_t *srcs[4], *dst;

    int i, j, planes = 3;



    AVFrame *picture = data;



    if (p->data[0])

        avctx->release_buffer(avctx, p);



    p->reference = 0;

    p->key_frame = 1;



    frametype = buf[0];



    offset_gu = AV_RL32(buf + 1);

    offset_bv = AV_RL32(buf + 5);



    switch (frametype) {

    case FRAME_SOLID_RGBA:

        avctx->pix_fmt = PIX_FMT_RGB32;



        if (avctx->get_buffer(avctx, p) < 0) {

            av_log(avctx, AV_LOG_ERROR, "get_buffer() failed\n");

            return -1;

        }



        dst = p->data[0];

        for (j = 0; j < avctx->height; j++) {

            for (i = 0; i < avctx->width; i++)

                AV_WN32(dst + i * 4, offset_gu);

            dst += p->linesize[0];

        }

        break;

    case FRAME_ARITH_RGBA:

        avctx->pix_fmt = PIX_FMT_RGB32;

        planes = 4;

        offset_ry += 4;

        offs[3] = AV_RL32(buf + 9);

    case FRAME_ARITH_RGB24:

    case FRAME_U_RGB24:

        if (frametype == FRAME_ARITH_RGB24 || frametype == FRAME_U_RGB24)

            avctx->pix_fmt = PIX_FMT_RGB24;



        if (avctx->get_buffer(avctx, p) < 0) {

            av_log(avctx, AV_LOG_ERROR, "get_buffer() failed\n");

            return -1;

        }



        offs[0] = offset_bv;

        offs[1] = offset_gu;

        offs[2] = offset_ry;



        if (!l->rgb_planes) {

            l->rgb_stride = FFALIGN(avctx->width, 16);

            l->rgb_planes = av_malloc(l->rgb_stride * avctx->height * planes);

            if (!l->rgb_planes) {

                av_log(avctx, AV_LOG_ERROR, "cannot allocate temporary buffer\n");

                return AVERROR(ENOMEM);

            }

        }

        for (i = 0; i < planes; i++)

            srcs[i] = l->rgb_planes + (i + 1) * l->rgb_stride * avctx->height - l->rgb_stride;

        if (offset_ry >= buf_size ||

            offset_gu >= buf_size ||

            offset_bv >= buf_size ||

            (planes == 4 && offs[3] >= buf_size)) {

            av_log(avctx, AV_LOG_ERROR,

                    "Invalid frame offsets\n");

            return AVERROR_INVALIDDATA;

        }

        for (i = 0; i < planes; i++)

            lag_decode_arith_plane(l, srcs[i],

                                   avctx->width, avctx->height,

                                   -l->rgb_stride, buf + offs[i],

                                   buf_size - offs[i]);

        dst = p->data[0];

        for (i = 0; i < planes; i++)

            srcs[i] = l->rgb_planes + i * l->rgb_stride * avctx->height;

        for (j = 0; j < avctx->height; j++) {

            for (i = 0; i < avctx->width; i++) {

                uint8_t r, g, b, a;

                r = srcs[0][i];

                g = srcs[1][i];

                b = srcs[2][i];

                r += g;

                b += g;

                if (frametype == FRAME_ARITH_RGBA) {

                    a = srcs[3][i];

                    AV_WN32(dst + i * 4, MKBETAG(a, r, g, b));

                } else {

                    dst[i * 3 + 0] = r;

                    dst[i * 3 + 1] = g;

                    dst[i * 3 + 2] = b;

                }

            }

            dst += p->linesize[0];

            for (i = 0; i < planes; i++)

                srcs[i] += l->rgb_stride;

        }

        break;

    case FRAME_ARITH_YUY2:

        avctx->pix_fmt = PIX_FMT_YUV422P;



        if (avctx->get_buffer(avctx, p) < 0) {

            av_log(avctx, AV_LOG_ERROR, "get_buffer() failed\n");

            return -1;

        }



        if (offset_ry >= buf_size ||

            offset_gu >= buf_size ||

            offset_bv >= buf_size) {

            av_log(avctx, AV_LOG_ERROR,

                   "Invalid frame offsets\n");

            return AVERROR_INVALIDDATA;

        }



        lag_decode_arith_plane(l, p->data[0], avctx->width, avctx->height,

                               p->linesize[0], buf + offset_ry,

                               buf_size - offset_ry);

        lag_decode_arith_plane(l, p->data[2], avctx->width / 2,

                               avctx->height, p->linesize[2],

                               buf + offset_gu, buf_size - offset_gu);

        lag_decode_arith_plane(l, p->data[1], avctx->width / 2,

                               avctx->height, p->linesize[1],

                               buf + offset_bv, buf_size - offset_bv);

        break;

    case FRAME_ARITH_YV12:

        avctx->pix_fmt = PIX_FMT_YUV420P;



        if (avctx->get_buffer(avctx, p) < 0) {

            av_log(avctx, AV_LOG_ERROR, "get_buffer() failed\n");

            return -1;

        }



        if (offset_ry >= buf_size ||

            offset_gu >= buf_size ||

            offset_bv >= buf_size) {

            av_log(avctx, AV_LOG_ERROR,

                   "Invalid frame offsets\n");

            return AVERROR_INVALIDDATA;

        }



        lag_decode_arith_plane(l, p->data[0], avctx->width, avctx->height,

                               p->linesize[0], buf + offset_ry,

                               buf_size - offset_ry);

        lag_decode_arith_plane(l, p->data[2], avctx->width / 2,

                               avctx->height / 2, p->linesize[2],

                               buf + offset_gu, buf_size - offset_gu);

        lag_decode_arith_plane(l, p->data[1], avctx->width / 2,

                               avctx->height / 2, p->linesize[1],

                               buf + offset_bv, buf_size - offset_bv);

        break;

    default:

        av_log(avctx, AV_LOG_ERROR,

               "Unsupported Lagarith frame type: %#x\n", frametype);

        return -1;

    }



    *picture = *p;

    *data_size = sizeof(AVFrame);



    return buf_size;

}

static int filter_packet(void *log_ctx, AVPacket *pkt,

                         AVFormatContext *fmt_ctx, AVBitStreamFilterContext *bsf_ctx)

{

    AVCodecContext *enc_ctx = fmt_ctx->streams[pkt->stream_index]->codec;

    int ret;



    while (bsf_ctx) {

        AVPacket new_pkt = *pkt;

        ret = av_bitstream_filter_filter(bsf_ctx, enc_ctx, NULL,

                                             &new_pkt.data, &new_pkt.size,

                                             pkt->data, pkt->size,

                                             pkt->flags & AV_PKT_FLAG_KEY);

        if (ret == 0 && new_pkt.data != pkt->data && new_pkt.destruct) {

            if ((ret = av_copy_packet(&new_pkt, pkt)) < 0)

                break;

            ret = 1;

        }



        if (ret > 0) {

            av_free_packet(pkt);

            new_pkt.buf = av_buffer_create(new_pkt.data, new_pkt.size,

                                           av_buffer_default_free, NULL, 0);

            if (!new_pkt.buf)

                break;

        }

        *pkt = new_pkt;



        bsf_ctx = bsf_ctx->next;

    }



    if (ret < 0) {

        av_log(log_ctx, AV_LOG_ERROR,

               "Failed to filter bitstream with filter %s for stream %d in file '%s' with codec %s\n",

               bsf_ctx->filter->name, pkt->stream_index, fmt_ctx->filename,

               avcodec_get_name(enc_ctx->codec_id));

    }



    return ret;

}

static int srt_encode_frame(AVCodecContext *avctx,

                            unsigned char *buf, int bufsize, const AVSubtitle *sub)

{

    SRTContext *s = avctx->priv_data;

    ASSDialog *dialog;

    int i, len, num;



    s->ptr = s->buffer;

    s->end = s->ptr + sizeof(s->buffer);



    for (i=0; i<sub->num_rects; i++) {



        if (sub->rects[i]->type != SUBTITLE_ASS) {

            av_log(avctx, AV_LOG_ERROR, "Only SUBTITLE_ASS type supported.\n");

            return AVERROR(ENOSYS);

        }



        dialog = ff_ass_split_dialog(s->ass_ctx, sub->rects[i]->ass, 0, &num);

        for (; dialog && num--; dialog++) {

            if (avctx->codec->id == CODEC_ID_SRT) {

                int sh, sm, ss, sc = 10 * dialog->start;

                int eh, em, es, ec = 10 * dialog->end;

                sh = sc/3600000;  sc -= 3600000*sh;

                sm = sc/  60000;  sc -=   60000*sm;

                ss = sc/   1000;  sc -=    1000*ss;

                eh = ec/3600000;  ec -= 3600000*eh;

                em = ec/  60000;  ec -=   60000*em;

                es = ec/   1000;  ec -=    1000*es;

                srt_print(s,"%d\r\n%02d:%02d:%02d,%03d --> %02d:%02d:%02d,%03d\r\n",

                          ++s->count, sh, sm, ss, sc, eh, em, es, ec);

            }

            s->alignment_applied = 0;

            s->dialog_start = s->ptr - 2;

            srt_style_apply(s, dialog->style);

            ff_ass_split_override_codes(&srt_callbacks, s, dialog->text);

        }

    }



    if (s->ptr == s->buffer)

        return 0;



    len = av_strlcpy(buf, s->buffer, bufsize);



    if (len > bufsize-1) {

        av_log(avctx, AV_LOG_ERROR, "Buffer too small for ASS event.\n");

        return -1;

    }



    return len;

}

void  pp_postprocess(const uint8_t * src[3], const int srcStride[3],

                     uint8_t * dst[3], const int dstStride[3],

                     int width, int height,

                     const QP_STORE_T *QP_store,  int QPStride,

                     pp_mode *vm,  void *vc, int pict_type)

{

    int mbWidth = (width+15)>>4;

    int mbHeight= (height+15)>>4;

    PPMode *mode = vm;

    PPContext *c = vc;

    int minStride= FFMAX(FFABS(srcStride[0]), FFABS(dstStride[0]));

    int absQPStride = FFABS(QPStride);



    // c->stride and c->QPStride are always positive

    if(c->stride < minStride || c->qpStride < absQPStride)

        reallocBuffers(c, width, height,

                       FFMAX(minStride, c->stride),

                       FFMAX(c->qpStride, absQPStride));



    if(!QP_store || (mode->lumMode & FORCE_QUANT)){

        int i;

        QP_store= c->forcedQPTable;

        absQPStride = QPStride = 0;

        if(mode->lumMode & FORCE_QUANT)

            for(i=0; i<mbWidth; i++) c->forcedQPTable[i]= mode->forcedQuant;

        else

            for(i=0; i<mbWidth; i++) c->forcedQPTable[i]= 1;

    }



    if(pict_type & PP_PICT_TYPE_QP2){

        int i;

        const int count= FFMAX(mbHeight * absQPStride, mbWidth);

        for(i=0; i<(count>>2); i++){

            ((uint32_t*)c->stdQPTable)[i] = (((const uint32_t*)QP_store)[i]>>1) & 0x7F7F7F7F;

        }

        for(i<<=2; i<count; i++){

            c->stdQPTable[i] = QP_store[i]>>1;

        }

        QP_store= c->stdQPTable;

        QPStride= absQPStride;

    }



    if(0){

        int x,y;

        for(y=0; y<mbHeight; y++){

            for(x=0; x<mbWidth; x++){

                av_log(c, AV_LOG_INFO, "%2d ", QP_store[x + y*QPStride]);

            }

            av_log(c, AV_LOG_INFO, "\n");

        }

        av_log(c, AV_LOG_INFO, "\n");

    }



    if((pict_type&7)!=3){

        if (QPStride >= 0){

            int i;

            const int count= FFMAX(mbHeight * QPStride, mbWidth);

            for(i=0; i<(count>>2); i++){

                ((uint32_t*)c->nonBQPTable)[i] = ((const uint32_t*)QP_store)[i] & 0x3F3F3F3F;

            }

            for(i<<=2; i<count; i++){

                c->nonBQPTable[i] = QP_store[i] & 0x3F;

            }

        } else {

            int i,j;

            for(i=0; i<mbHeight; i++) {

                for(j=0; j<absQPStride; j++) {

                    c->nonBQPTable[i*absQPStride+j] = QP_store[i*QPStride+j] & 0x3F;

                }

            }

        }

    }



    av_log(c, AV_LOG_DEBUG, "using npp filters 0x%X/0x%X\n",

           mode->lumMode, mode->chromMode);



    postProcess(src[0], srcStride[0], dst[0], dstStride[0],

                width, height, QP_store, QPStride, 0, mode, c);



    if (!(src[1] && src[2] && dst[1] && dst[2]))

        return;



    width  = (width )>>c->hChromaSubSample;

    height = (height)>>c->vChromaSubSample;



    if(mode->chromMode){

        postProcess(src[1], srcStride[1], dst[1], dstStride[1],

                    width, height, QP_store, QPStride, 1, mode, c);

        postProcess(src[2], srcStride[2], dst[2], dstStride[2],

                    width, height, QP_store, QPStride, 2, mode, c);

    }

    else if(srcStride[1] == dstStride[1] && srcStride[2] == dstStride[2]){

        linecpy(dst[1], src[1], height, srcStride[1]);

        linecpy(dst[2], src[2], height, srcStride[2]);

    }else{

        int y;

        for(y=0; y<height; y++){

            memcpy(&(dst[1][y*dstStride[1]]), &(src[1][y*srcStride[1]]), width);

            memcpy(&(dst[2][y*dstStride[2]]), &(src[2][y*srcStride[2]]), width);

        }

    }

}

