static av_always_inline int setup_classifs(vorbis_context *vc,

                                           vorbis_residue *vr,

                                           uint8_t *do_not_decode,

                                           unsigned ch_used,

                                           int partition_count)

{

    int p, j, i;

    unsigned c_p_c         = vc->codebooks[vr->classbook].dimensions;

    unsigned inverse_class = ff_inverse[vr->classifications];

    unsigned temp, temp2;

    for (p = 0, j = 0; j < ch_used; ++j) {

        if (!do_not_decode[j]) {

            temp = get_vlc2(&vc->gb, vc->codebooks[vr->classbook].vlc.table,

                                     vc->codebooks[vr->classbook].nb_bits, 3);



            av_dlog(NULL, "Classword: %u\n", temp);



            if ((int)temp < 0)

                return temp;



            av_assert0(vr->classifications > 1); //needed for inverse[]



            if (temp <= 65536) {

                for (i = partition_count + c_p_c - 1; i >= partition_count; i--) {

                    temp2 = (((uint64_t)temp) * inverse_class) >> 32;



                    if (i < vr->ptns_to_read)

                        vr->classifs[p + i] = temp - temp2 * vr->classifications;

                    temp = temp2;

                }

            } else {

                for (i = partition_count + c_p_c - 1; i >= partition_count; i--) {

                    temp2 = temp / vr->classifications;



                    if (i < vr->ptns_to_read)

                        vr->classifs[p + i] = temp - temp2 * vr->classifications;

                    temp = temp2;

                }

            }

        }

        p += vr->ptns_to_read;

    }

    return 0;

}

static int xan_unpack(uint8_t *dest, const int dest_len,

                      const uint8_t *src, const int src_len)

{

    uint8_t opcode;

    int size;

    uint8_t *orig_dest = dest;

    const uint8_t *src_end = src + src_len;

    const uint8_t *dest_end = dest + dest_len;



    while (dest < dest_end) {

        opcode = *src++;



        if (opcode < 0xe0) {

            int size2, back;

            if ((opcode & 0x80) == 0) {

                size  = opcode & 3;

                back  = ((opcode & 0x60) << 3) + *src++ + 1;

                size2 = ((opcode & 0x1c) >> 2) + 3;

            } else if ((opcode & 0x40) == 0) {

                size  = *src >> 6;

                back  = (bytestream_get_be16(&src) & 0x3fff) + 1;

                size2 = (opcode & 0x3f) + 4;

            } else {

                size  = opcode & 3;

                back  = ((opcode & 0x10) << 12) + bytestream_get_be16(&src) + 1;

                size2 = ((opcode & 0x0c) <<  6) + *src++ + 5;

                if (size + size2 > dest_end - dest)

                    break;

            }

            if (src + size > src_end || dest + size + size2 > dest_end ||

                dest - orig_dest + size < back)

                return -1;

            bytestream_get_buffer(&src, dest, size);

            dest += size;

            av_memcpy_backptr(dest, back, size2);

            dest += size2;

        } else {

            int finish = opcode >= 0xfc;



            size = finish ? opcode & 3 : ((opcode & 0x1f) << 2) + 4;

            if (src + size > src_end || dest + size > dest_end)

                return -1;

            bytestream_get_buffer(&src, dest, size);

            dest += size;

            if (finish)

                break;

        }

    }

    return dest - orig_dest;

}

static int mov_write_tkhd_tag(ByteIOContext *pb, MOVTrack* track)

{

    int64_t maxTrackLenTemp;

    put_be32(pb, 0x5c); /* size (always 0x5c) */

    put_tag(pb, "tkhd");

    put_be32(pb, 0xf); /* version & flags (track enabled) */

    put_be32(pb, track->time); /* creation time */

    put_be32(pb, track->time); /* modification time */

    put_be32(pb, track->trackID); /* track-id */

    put_be32(pb, 0); /* reserved */

    maxTrackLenTemp = ((int64_t)globalTimescale*(int64_t)track->trackDuration)/(int64_t)track->timescale;

    put_be32(pb, (long)maxTrackLenTemp); /* duration */



    put_be32(pb, 0); /* reserved */

    put_be32(pb, 0); /* reserved */

    put_be32(pb, 0x0); /* reserved (Layer & Alternate group) */

    /* Volume, only for audio */

    if(track->enc->codec_type == CODEC_TYPE_AUDIO)

        put_be16(pb, 0x0100);

    else

        put_be16(pb, 0);

    put_be16(pb, 0); /* reserved */



    /* Matrix structure */

    put_be32(pb, 0x00010000); /* reserved */

    put_be32(pb, 0x0); /* reserved */

    put_be32(pb, 0x0); /* reserved */

    put_be32(pb, 0x0); /* reserved */

    put_be32(pb, 0x00010000); /* reserved */

    put_be32(pb, 0x0); /* reserved */

    put_be32(pb, 0x0); /* reserved */

    put_be32(pb, 0x0); /* reserved */

    put_be32(pb, 0x40000000); /* reserved */



    /* Track width and height, for visual only */

    if(track->enc->codec_type == CODEC_TYPE_VIDEO) {

        put_be32(pb, track->enc->width*0x10000);

        put_be32(pb, track->enc->height*0x10000);

    }

    else {

        put_be32(pb, 0);

        put_be32(pb, 0);

    }

    return 0x5c;

}

