static int query_formats(AVFilterGraph *graph, AVClass *log_ctx)

{

    int i, j, ret;

    int scaler_count = 0, resampler_count = 0;

    int count_queried = 0;        /* successful calls to query_formats() */

    int count_merged = 0;         /* successful merge of formats lists */

    int count_already_merged = 0; /* lists already merged */

    int count_delayed = 0;        /* lists that need to be merged later */



    for (i = 0; i < graph->nb_filters; i++) {

        AVFilterContext *f = graph->filters[i];

        if (formats_declared(f))

            continue;

        if (f->filter->query_formats)

            ret = filter_query_formats(f);

        else

            ret = ff_default_query_formats(f);

        if (ret < 0 && ret != AVERROR(EAGAIN))

            return ret;

        /* note: EAGAIN could indicate a partial success, not counted yet */

        count_queried += ret >= 0;

    }



    /* go through and merge as many format lists as possible */

    for (i = 0; i < graph->nb_filters; i++) {

        AVFilterContext *filter = graph->filters[i];



        for (j = 0; j < filter->nb_inputs; j++) {

            AVFilterLink *link = filter->inputs[j];

            int convert_needed = 0;



            if (!link)

                continue;



            if (link->in_formats != link->out_formats

                && link->in_formats && link->out_formats)

                if (!can_merge_formats(link->in_formats, link->out_formats,

                                      link->type, 0))

                    convert_needed = 1;

            if (link->type == AVMEDIA_TYPE_AUDIO) {

                if (link->in_samplerates != link->out_samplerates

                    && link->in_samplerates && link->out_samplerates)

                    if (!can_merge_formats(link->in_samplerates,

                                           link->out_samplerates,

                                           0, 1))

                        convert_needed = 1;

            }



#define MERGE_DISPATCH(field, statement)                                     \

            if (!(link->in_ ## field && link->out_ ## field)) {              \

                count_delayed++;                                             \

            } else if (link->in_ ## field == link->out_ ## field) {          \

                count_already_merged++;                                      \

            } else if (!convert_needed) {                                    \

                count_merged++;                                              \

                statement                                                    \

            }



            if (link->type == AVMEDIA_TYPE_AUDIO) {

                MERGE_DISPATCH(channel_layouts,

                    if (!ff_merge_channel_layouts(link->in_channel_layouts,

                                                  link->out_channel_layouts))

                        convert_needed = 1;

                )

                MERGE_DISPATCH(samplerates,

                    if (!ff_merge_samplerates(link->in_samplerates,

                                              link->out_samplerates))

                        convert_needed = 1;

                )

            }

            MERGE_DISPATCH(formats,

                if (!ff_merge_formats(link->in_formats, link->out_formats,

                                      link->type))

                    convert_needed = 1;

            )

#undef MERGE_DISPATCH



            if (convert_needed) {

                AVFilterContext *convert;

                AVFilter *filter;

                AVFilterLink *inlink, *outlink;

                char scale_args[256];

                char inst_name[30];



                /* couldn't merge format lists. auto-insert conversion filter */

                switch (link->type) {

                case AVMEDIA_TYPE_VIDEO:

                    if (!(filter = avfilter_get_by_name("scale"))) {

                        av_log(log_ctx, AV_LOG_ERROR, "'scale' filter "

                               "not present, cannot convert pixel formats.\n");

                        return AVERROR(EINVAL);

                    }



                    snprintf(inst_name, sizeof(inst_name), "auto-inserted scaler %d",

                             scaler_count++);



                    if ((ret = avfilter_graph_create_filter(&convert, filter,

                                                            inst_name, graph->scale_sws_opts, NULL,

                                                            graph)) < 0)

                        return ret;

                    break;

                case AVMEDIA_TYPE_AUDIO:

                    if (!(filter = avfilter_get_by_name("aresample"))) {

                        av_log(log_ctx, AV_LOG_ERROR, "'aresample' filter "

                               "not present, cannot convert audio formats.\n");

                        return AVERROR(EINVAL);

                    }



                    snprintf(inst_name, sizeof(inst_name), "auto-inserted resampler %d",

                             resampler_count++);

                    scale_args[0] = '\0';

                    if (graph->aresample_swr_opts)

                        snprintf(scale_args, sizeof(scale_args), "%s",

                                 graph->aresample_swr_opts);

                    if ((ret = avfilter_graph_create_filter(&convert, filter,

                                                            inst_name, graph->aresample_swr_opts,

                                                            NULL, graph)) < 0)

                        return ret;

                    break;

                default:

                    return AVERROR(EINVAL);

                }



                if ((ret = avfilter_insert_filter(link, convert, 0, 0)) < 0)

                    return ret;



                filter_query_formats(convert);

                inlink  = convert->inputs[0];

                outlink = convert->outputs[0];

                av_assert0( inlink-> in_formats->refcount > 0);

                av_assert0( inlink->out_formats->refcount > 0);

                av_assert0(outlink-> in_formats->refcount > 0);

                av_assert0(outlink->out_formats->refcount > 0);

                if (outlink->type == AVMEDIA_TYPE_AUDIO) {

                    av_assert0( inlink-> in_samplerates->refcount > 0);

                    av_assert0( inlink->out_samplerates->refcount > 0);

                    av_assert0(outlink-> in_samplerates->refcount > 0);

                    av_assert0(outlink->out_samplerates->refcount > 0);

                    av_assert0( inlink-> in_channel_layouts->refcount > 0);

                    av_assert0( inlink->out_channel_layouts->refcount > 0);

                    av_assert0(outlink-> in_channel_layouts->refcount > 0);

                    av_assert0(outlink->out_channel_layouts->refcount > 0);

                }

                if (!ff_merge_formats( inlink->in_formats,  inlink->out_formats,  inlink->type) ||

                    !ff_merge_formats(outlink->in_formats, outlink->out_formats, outlink->type))

                    ret = AVERROR(ENOSYS);

                if (inlink->type == AVMEDIA_TYPE_AUDIO &&

                    (!ff_merge_samplerates(inlink->in_samplerates,

                                           inlink->out_samplerates) ||

                     !ff_merge_channel_layouts(inlink->in_channel_layouts,

                                               inlink->out_channel_layouts)))

                    ret = AVERROR(ENOSYS);

                if (outlink->type == AVMEDIA_TYPE_AUDIO &&

                    (!ff_merge_samplerates(outlink->in_samplerates,

                                           outlink->out_samplerates) ||

                     !ff_merge_channel_layouts(outlink->in_channel_layouts,

                                               outlink->out_channel_layouts)))

                    ret = AVERROR(ENOSYS);



                if (ret < 0) {

                    av_log(log_ctx, AV_LOG_ERROR,

                           "Impossible to convert between the formats supported by the filter "

                           "'%s' and the filter '%s'\n", link->src->name, link->dst->name);

                    return ret;

                }

            }

        }

    }



    av_log(graph, AV_LOG_DEBUG, "query_formats: "

           "%d queried, %d merged, %d already done, %d delayed\n",

           count_queried, count_merged, count_already_merged, count_delayed);

    if (count_delayed) {

        AVBPrint bp;



        /* if count_queried > 0, one filter at least did set its formats,

           that will give additional information to its neighbour;

           if count_merged > 0, one pair of formats lists at least was merged,

           that will give additional information to all connected filters;

           in both cases, progress was made and a new round must be done */

        if (count_queried || count_merged)

            return AVERROR(EAGAIN);

        av_bprint_init(&bp, 0, AV_BPRINT_SIZE_AUTOMATIC);

        for (i = 0; i < graph->nb_filters; i++)

            if (!formats_declared(graph->filters[i]))

                av_bprintf(&bp, "%s%s", bp.len ? ", " : "",

                          graph->filters[i]->name);

        av_log(graph, AV_LOG_ERROR,

               "The following filters could not choose their formats: %s\n"

               "Consider inserting the (a)format filter near their input or "

               "output.\n", bp.str);

        return AVERROR(EIO);

    }

    return 0;

}

void mpeg1_encode_init(MpegEncContext *s)

{

    static int done=0;

    if(!done){

        int f_code;

        int mv;



        done=1;

        for(f_code=1; f_code<=MAX_FCODE; f_code++){

            for(mv=-MAX_MV; mv<=MAX_MV; mv++){

                int len;



                if(mv==0) len= mbMotionVectorTable[0][1];

                else{

                    int val, bit_size, range, code;



                    bit_size = s->f_code - 1;

                    range = 1 << bit_size;



                    val=mv;

                    if (val < 0) 

                        val = -val;

                    val--;

                    code = (val >> bit_size) + 1;

                    if(code<17){

                        len= mbMotionVectorTable[code][1] + 1 + bit_size;

                    }else{

                        len= mbMotionVectorTable[16][1] + 2 + bit_size;

                    }

                }



                mv_penalty[f_code][mv+MAX_MV]= len;

            }

        }





        for(f_code=MAX_FCODE; f_code>0; f_code--){

            for(mv=-(8<<f_code); mv<(8<<f_code); mv++){

                fcode_tab[mv+MAX_MV]= f_code;

            }

        }

    }

    s->mv_penalty= mv_penalty;



    s->fcode_tab= fcode_tab;

}

static int cook_decode_close(AVCodecContext *avctx)

{

    int i;

    COOKContext *q = avctx->priv_data;

    av_log(NULL,AV_LOG_DEBUG, "Deallocating memory.\n");



    /* Free allocated memory buffers. */

    av_free(q->mlt_window);

    av_free(q->mlt_precos);

    av_free(q->mlt_presin);

    av_free(q->mlt_postcos);

    av_free(q->frame_reorder_index);

    av_free(q->frame_reorder_buffer);

    av_free(q->decoded_bytes_buffer);



    /* Free the transform. */

    ff_fft_end(&q->fft_ctx);



    /* Free the VLC tables. */

    for (i=0 ; i<13 ; i++) {

        free_vlc(&q->envelope_quant_index[i]);

    }

    for (i=0 ; i<7 ; i++) {

        free_vlc(&q->sqvh[i]);

    }

    if(q->nb_channels==2 && q->joint_stereo==1 ){

        free_vlc(&q->ccpl);

    }



    av_log(NULL,AV_LOG_DEBUG,"Memory deallocated.\n");



    return 0;

}

static int compute_pkt_fields2(AVFormatContext *s, AVStream *st, AVPacket *pkt){

    int delay = FFMAX(st->codec->has_b_frames, !!st->codec->max_b_frames);

    int num, den, frame_size, i;



    av_dlog(s, "compute_pkt_fields2: pts:%"PRId64" dts:%"PRId64" cur_dts:%"PRId64" b:%d size:%d st:%d\n",

            pkt->pts, pkt->dts, st->cur_dts, delay, pkt->size, pkt->stream_index);



/*    if(pkt->pts == AV_NOPTS_VALUE && pkt->dts == AV_NOPTS_VALUE)

        return AVERROR(EINVAL);*/



    /* duration field */

    if (pkt->duration == 0) {

        compute_frame_duration(&num, &den, st, NULL, pkt);

        if (den && num) {

            pkt->duration = av_rescale(1, num * (int64_t)st->time_base.den * st->codec->ticks_per_frame, den * (int64_t)st->time_base.num);

        }

    }



    if(pkt->pts == AV_NOPTS_VALUE && pkt->dts != AV_NOPTS_VALUE && delay==0)

        pkt->pts= pkt->dts;



    //XXX/FIXME this is a temporary hack until all encoders output pts

    if((pkt->pts == 0 || pkt->pts == AV_NOPTS_VALUE) && pkt->dts == AV_NOPTS_VALUE && !delay){

        pkt->dts=

//        pkt->pts= st->cur_dts;

        pkt->pts= st->pts.val;

    }



    //calculate dts from pts

    if(pkt->pts != AV_NOPTS_VALUE && pkt->dts == AV_NOPTS_VALUE && delay <= MAX_REORDER_DELAY){

        st->pts_buffer[0]= pkt->pts;

        for(i=1; i<delay+1 && st->pts_buffer[i] == AV_NOPTS_VALUE; i++)

            st->pts_buffer[i]= pkt->pts + (i-delay-1) * pkt->duration;

        for(i=0; i<delay && st->pts_buffer[i] > st->pts_buffer[i+1]; i++)

            FFSWAP(int64_t, st->pts_buffer[i], st->pts_buffer[i+1]);



        pkt->dts= st->pts_buffer[0];

    }



    if(st->cur_dts && st->cur_dts != AV_NOPTS_VALUE && ((!(s->oformat->flags & AVFMT_TS_NONSTRICT) && st->cur_dts >= pkt->dts) || st->cur_dts > pkt->dts)){

        av_log(s, AV_LOG_ERROR,

               "Application provided invalid, non monotonically increasing dts to muxer in stream %d: %"PRId64" >= %"PRId64"\n",

               st->index, st->cur_dts, pkt->dts);

        return AVERROR(EINVAL);

    }

    if(pkt->dts != AV_NOPTS_VALUE && pkt->pts != AV_NOPTS_VALUE && pkt->pts < pkt->dts){

        av_log(s, AV_LOG_ERROR, "pts < dts in stream %d\n", st->index);

        return AVERROR(EINVAL);

    }



//    av_log(s, AV_LOG_DEBUG, "av_write_frame: pts2:%"PRId64" dts2:%"PRId64"\n", pkt->pts, pkt->dts);

    st->cur_dts= pkt->dts;

    st->pts.val= pkt->dts;



    /* update pts */

    switch (st->codec->codec_type) {

    case AVMEDIA_TYPE_AUDIO:

        frame_size = get_audio_frame_size(st->codec, pkt->size);



        /* HACK/FIXME, we skip the initial 0 size packets as they are most

           likely equal to the encoder delay, but it would be better if we

           had the real timestamps from the encoder */

        if (frame_size >= 0 && (pkt->size || st->pts.num!=st->pts.den>>1 || st->pts.val)) {

            frac_add(&st->pts, (int64_t)st->time_base.den * frame_size);

        }

        break;

    case AVMEDIA_TYPE_VIDEO:

        frac_add(&st->pts, (int64_t)st->time_base.den * st->codec->time_base.num);

        break;

    default:

        break;

    }

    return 0;

}

int ff_h264_check_intra_pred_mode(H264Context *h, int mode){

    MpegEncContext * const s = &h->s;

    static const int8_t top [7]= {LEFT_DC_PRED8x8, 1,-1,-1};

    static const int8_t left[7]= { TOP_DC_PRED8x8,-1, 2,-1,DC_128_PRED8x8};



    if(mode > 6U) {

        av_log(h->s.avctx, AV_LOG_ERROR, "out of range intra chroma pred mode at %d %d\n", s->mb_x, s->mb_y);

        return -1;

    }



    if(!(h->top_samples_available&0x8000)){

        mode= top[ mode ];

        if(mode<0){

            av_log(h->s.avctx, AV_LOG_ERROR, "top block unavailable for requested intra mode at %d %d\n", s->mb_x, s->mb_y);

            return -1;

        }

    }



    if((h->left_samples_available&0x8080) != 0x8080){

        mode= left[ mode ];

        if(h->left_samples_available&0x8080){ //mad cow disease mode, aka MBAFF + constrained_intra_pred

            mode= ALZHEIMER_DC_L0T_PRED8x8 + (!(h->left_samples_available&0x8000)) + 2*(mode == DC_128_PRED8x8);

        }

        if(mode<0){

            av_log(h->s.avctx, AV_LOG_ERROR, "left block unavailable for requested intra mode at %d %d\n", s->mb_x, s->mb_y);

            return -1;

        }

    }



    return mode;

}

static inline void chroma_4mv_motion_lowres(MpegEncContext *s,

                                            uint8_t *dest_cb, uint8_t *dest_cr,

                                            uint8_t **ref_picture,

                                            h264_chroma_mc_func * pix_op,

                                            int mx, int my)

{

    const int lowres     = s->avctx->lowres;

    const int op_index   = FFMIN(lowres, 2);

    const int block_s    = 8 >> lowres;

    const int s_mask     = (2 << lowres) - 1;

    const int h_edge_pos = s->h_edge_pos >> lowres + 1;

    const int v_edge_pos = s->v_edge_pos >> lowres + 1;

    int emu = 0, src_x, src_y, offset, sx, sy;

    uint8_t *ptr;



    if (s->quarter_sample) {

        mx /= 2;

        my /= 2;

    }



    /* In case of 8X8, we construct a single chroma motion vector

       with a special rounding */

    mx = ff_h263_round_chroma(mx);

    my = ff_h263_round_chroma(my);



    sx = mx & s_mask;

    sy = my & s_mask;

    src_x = s->mb_x * block_s + (mx >> lowres + 1);

    src_y = s->mb_y * block_s + (my >> lowres + 1);



    offset = src_y * s->uvlinesize + src_x;

    ptr = ref_picture[1] + offset;

    if (s->flags & CODEC_FLAG_EMU_EDGE) {

        if ((unsigned) src_x > h_edge_pos - (!!sx) - block_s ||

            (unsigned) src_y > v_edge_pos - (!!sy) - block_s) {

            s->dsp.emulated_edge_mc(s->edge_emu_buffer, ptr, s->uvlinesize,

                                    9, 9, src_x, src_y, h_edge_pos, v_edge_pos);

            ptr = s->edge_emu_buffer;

            emu = 1;

        }

    }

    sx = (sx << 2) >> lowres;

    sy = (sy << 2) >> lowres;

    pix_op[op_index](dest_cb, ptr, s->uvlinesize, block_s, sx, sy);



    ptr = ref_picture[2] + offset;

    if (emu) {

        s->dsp.emulated_edge_mc(s->edge_emu_buffer, ptr, s->uvlinesize, 9, 9,

                                src_x, src_y, h_edge_pos, v_edge_pos);

        ptr = s->edge_emu_buffer;

    }

    pix_op[op_index](dest_cr, ptr, s->uvlinesize, block_s, sx, sy);

}

static int mov_read_trun(MOVContext *c, AVIOContext *pb, MOVAtom atom)

{

    MOVFragment *frag = &c->fragment;

    AVStream *st = NULL;

    MOVStreamContext *sc;

    MOVStts *ctts_data;

    uint64_t offset;

    int64_t dts;

    int data_offset = 0;

    unsigned entries, first_sample_flags = frag->flags;

    int flags, distance, i;



    for (i = 0; i < c->fc->nb_streams; i++) {

        if (c->fc->streams[i]->id == frag->track_id) {

            st = c->fc->streams[i];

            break;

        }

    }

    if (!st) {

        av_log(c->fc, AV_LOG_ERROR, "could not find corresponding track id %u\n", frag->track_id);

        return AVERROR_INVALIDDATA;

    }

    sc = st->priv_data;

    if (sc->pseudo_stream_id+1 != frag->stsd_id && sc->pseudo_stream_id != -1)

        return 0;

    avio_r8(pb); /* version */

    flags = avio_rb24(pb);

    entries = avio_rb32(pb);

    av_log(c->fc, AV_LOG_TRACE, "flags 0x%x entries %u\n", flags, entries);



    /* Always assume the presence of composition time offsets.

     * Without this assumption, for instance, we cannot deal with a track in fragmented movies that meet the following.

     *  1) in the initial movie, there are no samples.

     *  2) in the first movie fragment, there is only one sample without composition time offset.

     *  3) in the subsequent movie fragments, there are samples with composition time offset. */

    if (!sc->ctts_count && sc->sample_count)

    {

        /* Complement ctts table if moov atom doesn't have ctts atom. */

        ctts_data = av_fast_realloc(NULL, &sc->ctts_allocated_size, sizeof(*sc->ctts_data) * sc->sample_count);

        if (!ctts_data)

            return AVERROR(ENOMEM);

        /* Don't use a count greater than 1 here since it will leave a gap in

         * the ctts index which the code below relies on being sequential. */

        sc->ctts_data = ctts_data;

        for (i = 0; i < sc->sample_count; i++) {

            sc->ctts_data[sc->ctts_count].count = 1;

            sc->ctts_data[sc->ctts_count].duration = 0;

            sc->ctts_count++;

        }

    }

    if ((uint64_t)entries+sc->ctts_count >= UINT_MAX/sizeof(*sc->ctts_data))

        return AVERROR_INVALIDDATA;

    if (flags & MOV_TRUN_DATA_OFFSET)        data_offset        = avio_rb32(pb);

    if (flags & MOV_TRUN_FIRST_SAMPLE_FLAGS) first_sample_flags = avio_rb32(pb);

    dts    = sc->track_end - sc->time_offset;

    offset = frag->base_data_offset + data_offset;

    distance = 0;

    av_log(c->fc, AV_LOG_TRACE, "first sample flags 0x%x\n", first_sample_flags);

    for (i = 0; i < entries && !pb->eof_reached; i++) {

        unsigned sample_size = frag->size;

        int sample_flags = i ? frag->flags : first_sample_flags;

        unsigned sample_duration = frag->duration;

        unsigned ctts_duration = 0;

        int keyframe = 0;

        int ctts_index = 0;

        int old_nb_index_entries = st->nb_index_entries;



        if (flags & MOV_TRUN_SAMPLE_DURATION) sample_duration = avio_rb32(pb);

        if (flags & MOV_TRUN_SAMPLE_SIZE)     sample_size     = avio_rb32(pb);

        if (flags & MOV_TRUN_SAMPLE_FLAGS)    sample_flags    = avio_rb32(pb);

        if (flags & MOV_TRUN_SAMPLE_CTS)      ctts_duration   = avio_rb32(pb);



        mov_update_dts_shift(sc, ctts_duration);

        if (frag->time != AV_NOPTS_VALUE) {

            if (c->use_mfra_for == FF_MOV_FLAG_MFRA_PTS) {

                int64_t pts = frag->time;

                av_log(c->fc, AV_LOG_DEBUG, "found frag time %"PRId64

                        " sc->dts_shift %d ctts.duration %d"

                        " sc->time_offset %"PRId64" flags & MOV_TRUN_SAMPLE_CTS %d\n", pts,

                        sc->dts_shift, ctts_duration,

                        sc->time_offset, flags & MOV_TRUN_SAMPLE_CTS);

                dts = pts - sc->dts_shift;

                if (flags & MOV_TRUN_SAMPLE_CTS) {

                    dts -= ctts_duration;

                } else {

                    dts -= sc->time_offset;

                }

                av_log(c->fc, AV_LOG_DEBUG, "calculated into dts %"PRId64"\n", dts);

            } else {

                dts = frag->time - sc->time_offset;

                av_log(c->fc, AV_LOG_DEBUG, "found frag time %"PRId64

                        ", using it for dts\n", dts);

            }

            frag->time = AV_NOPTS_VALUE;

        }



        if (st->codecpar->codec_type == AVMEDIA_TYPE_AUDIO)

            keyframe = 1;

        else

            keyframe =

                !(sample_flags & (MOV_FRAG_SAMPLE_FLAG_IS_NON_SYNC |

                                  MOV_FRAG_SAMPLE_FLAG_DEPENDS_YES));

        if (keyframe)

            distance = 0;

        ctts_index = av_add_index_entry(st, offset, dts, sample_size, distance,

                                        keyframe ? AVINDEX_KEYFRAME : 0);

        if (ctts_index >= 0 && old_nb_index_entries < st->nb_index_entries) {

            unsigned int size_needed = st->nb_index_entries * sizeof(*sc->ctts_data);

            unsigned int request_size = size_needed > sc->ctts_allocated_size ?

                FFMAX(size_needed, 2 * sc->ctts_allocated_size) : size_needed;

            ctts_data = av_fast_realloc(sc->ctts_data, &sc->ctts_allocated_size, request_size);

            if (!ctts_data) {

                av_freep(&sc->ctts_data);

                return AVERROR(ENOMEM);

            }



            sc->ctts_data = ctts_data;

            if (ctts_index != old_nb_index_entries) {

                memmove(sc->ctts_data + ctts_index + 1, sc->ctts_data + ctts_index,

                        sizeof(*sc->ctts_data) * (sc->ctts_count - ctts_index));

                if (ctts_index <= sc->current_sample) {

                    // if we inserted a new item before the current sample, move the

                    // counter ahead so it is still pointing to the same sample.

                    sc->current_sample++;

                }

            }



            sc->ctts_data[ctts_index].count = 1;

            sc->ctts_data[ctts_index].duration = ctts_duration;

            sc->ctts_count++;

        } else {

            av_log(c->fc, AV_LOG_ERROR, "Failed to add index entry\n");

        }



        av_log(c->fc, AV_LOG_TRACE, "AVIndex stream %d, sample %d, offset %"PRIx64", dts %"PRId64", "

                "size %u, distance %d, keyframe %d\n", st->index, ctts_index,

                offset, dts, sample_size, distance, keyframe);

        distance++;

        dts += sample_duration;

        offset += sample_size;

        sc->data_size += sample_size;

        sc->duration_for_fps += sample_duration;

        sc->nb_frames_for_fps ++;

    }



    if (pb->eof_reached)

        return AVERROR_EOF;



    frag->implicit_offset = offset;



    sc->track_end = dts + sc->time_offset;

    if (st->duration < sc->track_end)

        st->duration = sc->track_end;



    return 0;

}

