static void FUNC(transquant_bypass32x32)(uint8_t *_dst, int16_t *coeffs,

                                         ptrdiff_t stride)

{

    int x, y;

    pixel *dst = (pixel *)_dst;



    stride /= sizeof(pixel);



    for (y = 0; y < 32; y++) {

        for (x = 0; x < 32; x++) {

            dst[x] += *coeffs;

            coeffs++;

        }

        dst += stride;

    }

}

static int g2m_decode_frame(AVCodecContext *avctx, void *data,

                            int *got_picture_ptr, AVPacket *avpkt)

{

    const uint8_t *buf = avpkt->data;

    int buf_size = avpkt->size;

    G2MContext *c = avctx->priv_data;

    AVFrame *pic = data;

    GetByteContext bc, tbc;

    int magic;

    int got_header = 0;

    uint32_t chunk_size, cur_size;

    int chunk_type;

    int i;

    int ret;



    if (buf_size < 12) {

        av_log(avctx, AV_LOG_ERROR,

               "Frame should have at least 12 bytes, got %d instead\n",

               buf_size);

        return AVERROR_INVALIDDATA;

    }



    bytestream2_init(&bc, buf, buf_size);



    magic = bytestream2_get_be32(&bc);

    if ((magic & ~0xF) != MKBETAG('G', '2', 'M', '0') ||

        (magic & 0xF) < 2 || (magic & 0xF) > 4) {

        av_log(avctx, AV_LOG_ERROR, "Wrong magic %08X\n", magic);

        return AVERROR_INVALIDDATA;

    }



    if ((magic & 0xF) != 4) {

        av_log(avctx, AV_LOG_ERROR, "G2M2 and G2M3 are not yet supported\n");

        return AVERROR(ENOSYS);

    }



    while (bytestream2_get_bytes_left(&bc) > 5) {

        chunk_size = bytestream2_get_le32(&bc) - 1;

        chunk_type = bytestream2_get_byte(&bc);

        if (chunk_size > bytestream2_get_bytes_left(&bc)) {

            av_log(avctx, AV_LOG_ERROR, "Invalid chunk size %d type %02X\n",

                   chunk_size, chunk_type);

            break;

        }

        switch (chunk_type) {

        case FRAME_INFO:

            c->got_header = 0;

            if (chunk_size < 21) {

                av_log(avctx, AV_LOG_ERROR, "Invalid frame info size %d\n",

                       chunk_size);

                break;

            }

            c->width  = bytestream2_get_be32(&bc);

            c->height = bytestream2_get_be32(&bc);

            if (c->width  < 16 || c->width  > avctx->width ||

                c->height < 16 || c->height > avctx->height) {

                av_log(avctx, AV_LOG_ERROR,

                       "Invalid frame dimensions %dx%d\n",

                       c->width, c->height);

                c->width = c->height = 0;

                bytestream2_skip(&bc, bytestream2_get_bytes_left(&bc));

            }

            if (c->width != avctx->width || c->height != avctx->height)

                avcodec_set_dimensions(avctx, c->width, c->height);

            c->compression = bytestream2_get_be32(&bc);

            if (c->compression != 2 && c->compression != 3) {

                av_log(avctx, AV_LOG_ERROR,

                       "Unknown compression method %d\n",

                       c->compression);

                return AVERROR_PATCHWELCOME;

            }

            c->tile_width  = bytestream2_get_be32(&bc);

            c->tile_height = bytestream2_get_be32(&bc);

            if (!c->tile_width || !c->tile_height) {

                av_log(avctx, AV_LOG_ERROR,

                       "Invalid tile dimensions %dx%d\n",

                       c->tile_width, c->tile_height);

                return AVERROR_INVALIDDATA;

            }

            c->tiles_x = (c->width  + c->tile_width  - 1) / c->tile_width;

            c->tiles_y = (c->height + c->tile_height - 1) / c->tile_height;

            c->bpp = bytestream2_get_byte(&bc);

            chunk_size -= 21;

            bytestream2_skip(&bc, chunk_size);

            if (g2m_init_buffers(c))

                return AVERROR(ENOMEM);

            got_header = 1;

            break;

        case TILE_DATA:

            if (!c->tiles_x || !c->tiles_y) {

                av_log(avctx, AV_LOG_WARNING,

                       "No frame header - skipping tile\n");

                bytestream2_skip(&bc, bytestream2_get_bytes_left(&bc));

                break;

            }

            if (chunk_size < 2) {

                av_log(avctx, AV_LOG_ERROR, "Invalid tile data size %d\n",

                       chunk_size);

                break;

            }

            c->tile_x = bytestream2_get_byte(&bc);

            c->tile_y = bytestream2_get_byte(&bc);

            if (c->tile_x >= c->tiles_x || c->tile_y >= c->tiles_y) {

                av_log(avctx, AV_LOG_ERROR,

                       "Invalid tile pos %d,%d (in %dx%d grid)\n",

                       c->tile_x, c->tile_y, c->tiles_x, c->tiles_y);

                break;

            }

            chunk_size -= 2;

            ret = 0;

            switch (c->compression) {

            case COMPR_EPIC_J_B:

                av_log(avctx, AV_LOG_ERROR,

                       "ePIC j-b compression is not implemented yet\n");

                return AVERROR(ENOSYS);

            case COMPR_KEMPF_J_B:

                ret = kempf_decode_tile(c, c->tile_x, c->tile_y,

                                        buf + bytestream2_tell(&bc),

                                        chunk_size);

                break;

            }

            if (ret && c->framebuf)

                av_log(avctx, AV_LOG_ERROR, "Error decoding tile %d,%d\n",

                       c->tile_x, c->tile_y);

            bytestream2_skip(&bc, chunk_size);

            break;

        case CURSOR_POS:

            if (chunk_size < 5) {

                av_log(avctx, AV_LOG_ERROR, "Invalid cursor pos size %d\n",

                       chunk_size);

                break;

            }

            c->cursor_x = bytestream2_get_be16(&bc);

            c->cursor_y = bytestream2_get_be16(&bc);

            bytestream2_skip(&bc, chunk_size - 4);

            break;

        case CURSOR_SHAPE:

            if (chunk_size < 8) {

                av_log(avctx, AV_LOG_ERROR, "Invalid cursor data size %d\n",

                       chunk_size);

                break;

            }

            bytestream2_init(&tbc, buf + bytestream2_tell(&bc),

                             chunk_size - 4);

            cur_size        = bytestream2_get_be32(&tbc);

            c->cursor_w     = bytestream2_get_byte(&tbc);

            c->cursor_h     = bytestream2_get_byte(&tbc);

            c->cursor_hot_x = bytestream2_get_byte(&tbc);

            c->cursor_hot_y = bytestream2_get_byte(&tbc);

            c->cursor_fmt   = bytestream2_get_byte(&tbc);

            if (cur_size >= chunk_size ||

                c->cursor_w * c->cursor_h / 4 > cur_size) {

                av_log(avctx, AV_LOG_ERROR, "Invalid cursor data size %d\n",

                       chunk_size);

                break;

            }

            g2m_load_cursor(c, &tbc);

            bytestream2_skip(&bc, chunk_size);

            break;

        case CHUNK_CC:

        case CHUNK_CD:

            bytestream2_skip(&bc, chunk_size);

            break;

        default:

            av_log(avctx, AV_LOG_WARNING, "Skipping chunk type %02X\n",

                   chunk_type);

            bytestream2_skip(&bc, chunk_size);

        }

    }

    if (got_header)

        c->got_header = 1;



    if (c->width && c->height && c->framebuf) {

        if ((ret = ff_get_buffer(avctx, pic, 0)) < 0) {

            av_log(avctx, AV_LOG_ERROR, "get_buffer() failed\n");

            return ret;

        }



        pic->key_frame = got_header;

        pic->pict_type = got_header ? AV_PICTURE_TYPE_I : AV_PICTURE_TYPE_P;



        for (i = 0; i < avctx->height; i++)

            memcpy(pic->data[0] + i * pic->linesize[0],

                   c->framebuf  + i * c->framebuf_stride,

                   c->width * 3);

        g2m_paint_cursor(c, pic->data[0], pic->linesize[0]);



        *got_picture_ptr = 1;

    }



    return buf_size;

}

static inline void chroma_4mv_motion_lowres(MpegEncContext *s,

                                            uint8_t *dest_cb, uint8_t *dest_cr,

                                            uint8_t **ref_picture,

                                            h264_chroma_mc_func * pix_op,

                                            int mx, int my)

{

    const int lowres     = s->avctx->lowres;

    const int op_index   = FFMIN(lowres, 2);

    const int block_s    = 8 >> lowres;

    const int s_mask     = (2 << lowres) - 1;

    const int h_edge_pos = s->h_edge_pos >> lowres + 1;

    const int v_edge_pos = s->v_edge_pos >> lowres + 1;

    int emu = 0, src_x, src_y, offset, sx, sy;

    uint8_t *ptr;



    if (s->quarter_sample) {

        mx /= 2;

        my /= 2;

    }



    /* In case of 8X8, we construct a single chroma motion vector

       with a special rounding */

    mx = ff_h263_round_chroma(mx);

    my = ff_h263_round_chroma(my);



    sx = mx & s_mask;

    sy = my & s_mask;

    src_x = s->mb_x * block_s + (mx >> lowres + 1);

    src_y = s->mb_y * block_s + (my >> lowres + 1);



    offset = src_y * s->uvlinesize + src_x;

    ptr = ref_picture[1] + offset;

    if (s->flags & CODEC_FLAG_EMU_EDGE) {

        if ((unsigned) src_x > FFMAX(h_edge_pos - (!!sx) - block_s, 0) ||

            (unsigned) src_y > FFMAX(v_edge_pos - (!!sy) - block_s, 0)) {

            s->vdsp.emulated_edge_mc(s->edge_emu_buffer, ptr, s->uvlinesize,

                                    9, 9, src_x, src_y, h_edge_pos, v_edge_pos);

            ptr = s->edge_emu_buffer;

            emu = 1;

        }

    }

    sx = (sx << 2) >> lowres;

    sy = (sy << 2) >> lowres;

    pix_op[op_index](dest_cb, ptr, s->uvlinesize, block_s, sx, sy);



    ptr = ref_picture[2] + offset;

    if (emu) {

        s->vdsp.emulated_edge_mc(s->edge_emu_buffer, ptr, s->uvlinesize, 9, 9,

                                src_x, src_y, h_edge_pos, v_edge_pos);

        ptr = s->edge_emu_buffer;

    }

    pix_op[op_index](dest_cr, ptr, s->uvlinesize, block_s, sx, sy);

}

int av_buffersrc_buffer(AVFilterContext *ctx, AVFilterBufferRef *buf)

{

    BufferSourceContext *s = ctx->priv;

    AVFrame *frame = NULL;

    AVBufferRef *dummy_buf = NULL;

    int ret = 0, planes, i;



    if (!buf) {

        s->eof = 1;

        return 0;

    } else if (s->eof)

        return AVERROR(EINVAL);



    frame = av_frame_alloc();

    if (!frame)

        return AVERROR(ENOMEM);



    dummy_buf = av_buffer_create(NULL, 0, compat_free_buffer, buf, 0);

    if (!dummy_buf) {

        ret = AVERROR(ENOMEM);

        goto fail;

    }



    if ((ret = avfilter_copy_buf_props(frame, buf)) < 0)

        goto fail;



#define WRAP_PLANE(ref_out, data, data_size)                            \

do {                                                                    \

    AVBufferRef *dummy_ref = av_buffer_ref(dummy_buf);                  \

    if (!dummy_ref) {                                                   \

        ret = AVERROR(ENOMEM);                                          \

        goto fail;                                                      \

    }                                                                   \

    ref_out = av_buffer_create(data, data_size, compat_unref_buffer,    \

                               dummy_ref, 0);                           \

    if (!ref_out) {                                                     \


        av_frame_unref(frame);                                          \

        ret = AVERROR(ENOMEM);                                          \

        goto fail;                                                      \

    }                                                                   \

} while (0)



    if (ctx->outputs[0]->type  == AVMEDIA_TYPE_VIDEO) {

        const AVPixFmtDescriptor *desc = av_pix_fmt_desc_get(frame->format);



        planes = av_pix_fmt_count_planes(frame->format);

        if (!desc || planes <= 0) {

            ret = AVERROR(EINVAL);

            goto fail;

        }



        for (i = 0; i < planes; i++) {

            int v_shift    = (i == 1 || i == 2) ? desc->log2_chroma_h : 0;

            int plane_size = (frame->height >> v_shift) * frame->linesize[i];



            WRAP_PLANE(frame->buf[i], frame->data[i], plane_size);

        }

    } else {

        int planar = av_sample_fmt_is_planar(frame->format);

        int channels = av_get_channel_layout_nb_channels(frame->channel_layout);



        planes = planar ? channels : 1;



        if (planes > FF_ARRAY_ELEMS(frame->buf)) {

            frame->nb_extended_buf = planes - FF_ARRAY_ELEMS(frame->buf);

            frame->extended_buf = av_mallocz(sizeof(*frame->extended_buf) *

                                             frame->nb_extended_buf);

            if (!frame->extended_buf) {

                ret = AVERROR(ENOMEM);

                goto fail;

            }

        }



        for (i = 0; i < FFMIN(planes, FF_ARRAY_ELEMS(frame->buf)); i++)

            WRAP_PLANE(frame->buf[i], frame->extended_data[i], frame->linesize[0]);



        for (i = 0; i < planes - FF_ARRAY_ELEMS(frame->buf); i++)

            WRAP_PLANE(frame->extended_buf[i],

                       frame->extended_data[i + FF_ARRAY_ELEMS(frame->buf)],

                       frame->linesize[0]);

    }



    ret = av_buffersrc_add_frame(ctx, frame);



fail:

    av_buffer_unref(&dummy_buf);

    av_frame_free(&frame);



    return ret;

}

int ff_h264_decode_seq_parameter_set(H264Context *h){

    MpegEncContext * const s = &h->s;

    int profile_idc, level_idc, constraint_set_flags = 0;

    unsigned int sps_id;

    int i, log2_max_frame_num_minus4;

    SPS *sps;



    profile_idc= get_bits(&s->gb, 8);

    constraint_set_flags |= get_bits1(&s->gb) << 0;   //constraint_set0_flag

    constraint_set_flags |= get_bits1(&s->gb) << 1;   //constraint_set1_flag

    constraint_set_flags |= get_bits1(&s->gb) << 2;   //constraint_set2_flag

    constraint_set_flags |= get_bits1(&s->gb) << 3;   //constraint_set3_flag

    get_bits(&s->gb, 4); // reserved

    level_idc= get_bits(&s->gb, 8);

    sps_id= get_ue_golomb_31(&s->gb);



    if(sps_id >= MAX_SPS_COUNT) {

        av_log(h->s.avctx, AV_LOG_ERROR, "sps_id (%d) out of range\n", sps_id);

        return -1;

    }

    sps= av_mallocz(sizeof(SPS));

    if(sps == NULL)

        return -1;



    sps->time_offset_length = 24;

    sps->profile_idc= profile_idc;

    sps->constraint_set_flags = constraint_set_flags;

    sps->level_idc= level_idc;



    memset(sps->scaling_matrix4, 16, sizeof(sps->scaling_matrix4));

    memset(sps->scaling_matrix8, 16, sizeof(sps->scaling_matrix8));

    sps->scaling_matrix_present = 0;



    if(sps->profile_idc >= 100){ //high profile

        sps->chroma_format_idc= get_ue_golomb_31(&s->gb);

        if(sps->chroma_format_idc > 3) {

            av_log(h->s.avctx, AV_LOG_ERROR, "chroma_format_idc (%u) out of range\n", sps->chroma_format_idc);

            goto fail;

        } else if(sps->chroma_format_idc == 3) {

            sps->residual_color_transform_flag = get_bits1(&s->gb);

        }

        sps->bit_depth_luma   = get_ue_golomb(&s->gb) + 8;

        sps->bit_depth_chroma = get_ue_golomb(&s->gb) + 8;

        sps->transform_bypass = get_bits1(&s->gb);

        decode_scaling_matrices(h, sps, NULL, 1, sps->scaling_matrix4, sps->scaling_matrix8);

    }else{

        sps->chroma_format_idc= 1;

        sps->bit_depth_luma   = 8;

        sps->bit_depth_chroma = 8;

    }



    log2_max_frame_num_minus4 = get_ue_golomb(&s->gb);

    if (log2_max_frame_num_minus4 < MIN_LOG2_MAX_FRAME_NUM - 4 ||

        log2_max_frame_num_minus4 > MAX_LOG2_MAX_FRAME_NUM - 4) {

        av_log(h->s.avctx, AV_LOG_ERROR,

               "log2_max_frame_num_minus4 out of range (0-12): %d\n",

               log2_max_frame_num_minus4);

        return AVERROR_INVALIDDATA;

    }

    sps->log2_max_frame_num = log2_max_frame_num_minus4 + 4;



    sps->poc_type= get_ue_golomb_31(&s->gb);



    if(sps->poc_type == 0){ //FIXME #define

        sps->log2_max_poc_lsb= get_ue_golomb(&s->gb) + 4;

    } else if(sps->poc_type == 1){//FIXME #define

        sps->delta_pic_order_always_zero_flag= get_bits1(&s->gb);

        sps->offset_for_non_ref_pic= get_se_golomb(&s->gb);

        sps->offset_for_top_to_bottom_field= get_se_golomb(&s->gb);

        sps->poc_cycle_length                = get_ue_golomb(&s->gb);



        if((unsigned)sps->poc_cycle_length >= FF_ARRAY_ELEMS(sps->offset_for_ref_frame)){

            av_log(h->s.avctx, AV_LOG_ERROR, "poc_cycle_length overflow %u\n", sps->poc_cycle_length);

            goto fail;

        }



        for(i=0; i<sps->poc_cycle_length; i++)

            sps->offset_for_ref_frame[i]= get_se_golomb(&s->gb);

    }else if(sps->poc_type != 2){

        av_log(h->s.avctx, AV_LOG_ERROR, "illegal POC type %d\n", sps->poc_type);

        goto fail;

    }



    sps->ref_frame_count= get_ue_golomb_31(&s->gb);

    if(sps->ref_frame_count > MAX_PICTURE_COUNT-2 || sps->ref_frame_count >= 32U){

        av_log(h->s.avctx, AV_LOG_ERROR, "too many reference frames\n");

        goto fail;

    }

    sps->gaps_in_frame_num_allowed_flag= get_bits1(&s->gb);

    sps->mb_width = get_ue_golomb(&s->gb) + 1;

    sps->mb_height= get_ue_golomb(&s->gb) + 1;

    if((unsigned)sps->mb_width >= INT_MAX/16 || (unsigned)sps->mb_height >= INT_MAX/16 ||

       av_image_check_size(16*sps->mb_width, 16*sps->mb_height, 0, h->s.avctx)){

        av_log(h->s.avctx, AV_LOG_ERROR, "mb_width/height overflow\n");

        goto fail;

    }



    sps->frame_mbs_only_flag= get_bits1(&s->gb);

    if(!sps->frame_mbs_only_flag)

        sps->mb_aff= get_bits1(&s->gb);

    else

        sps->mb_aff= 0;



    sps->direct_8x8_inference_flag= get_bits1(&s->gb);

    if(!sps->frame_mbs_only_flag && !sps->direct_8x8_inference_flag){

        av_log(h->s.avctx, AV_LOG_ERROR, "This stream was generated by a broken encoder, invalid 8x8 inference\n");

        goto fail;

    }



#ifndef ALLOW_INTERLACE

    if(sps->mb_aff)

        av_log(h->s.avctx, AV_LOG_ERROR, "MBAFF support not included; enable it at compile-time.\n");

#endif

    sps->crop= get_bits1(&s->gb);

    if(sps->crop){

        int crop_vertical_limit   = sps->chroma_format_idc  & 2 ? 16 : 8;

        int crop_horizontal_limit = sps->chroma_format_idc == 3 ? 16 : 8;

        sps->crop_left  = get_ue_golomb(&s->gb);

        sps->crop_right = get_ue_golomb(&s->gb);

        sps->crop_top   = get_ue_golomb(&s->gb);

        sps->crop_bottom= get_ue_golomb(&s->gb);

        if(sps->crop_left || sps->crop_top){

            av_log(h->s.avctx, AV_LOG_ERROR, "insane cropping not completely supported, this could look slightly wrong ...\n");

        }

        if(sps->crop_right >= crop_horizontal_limit || sps->crop_bottom >= crop_vertical_limit){

            av_log(h->s.avctx, AV_LOG_ERROR, "brainfart cropping not supported, this could look slightly wrong ...\n");

        }

    }else{

        sps->crop_left  =

        sps->crop_right =

        sps->crop_top   =

        sps->crop_bottom= 0;

    }



    sps->vui_parameters_present_flag= get_bits1(&s->gb);

    if( sps->vui_parameters_present_flag )

        if (decode_vui_parameters(h, sps) < 0)

            goto fail;



    if(!sps->sar.den)

        sps->sar.den= 1;



    if(s->avctx->debug&FF_DEBUG_PICT_INFO){

        static const char csp[4][5] = { "Gray", "420", "422", "444" };

        av_log(h->s.avctx, AV_LOG_DEBUG, "sps:%u profile:%d/%d poc:%d ref:%d %dx%d %s %s crop:%d/%d/%d/%d %s %s %d/%d\n",

               sps_id, sps->profile_idc, sps->level_idc,

               sps->poc_type,

               sps->ref_frame_count,

               sps->mb_width, sps->mb_height,

               sps->frame_mbs_only_flag ? "FRM" : (sps->mb_aff ? "MB-AFF" : "PIC-AFF"),

               sps->direct_8x8_inference_flag ? "8B8" : "",

               sps->crop_left, sps->crop_right,

               sps->crop_top, sps->crop_bottom,

               sps->vui_parameters_present_flag ? "VUI" : "",

               csp[sps->chroma_format_idc],

               sps->timing_info_present_flag ? sps->num_units_in_tick : 0,

               sps->timing_info_present_flag ? sps->time_scale : 0

               );

    }



    av_free(h->sps_buffers[sps_id]);

    h->sps_buffers[sps_id]= sps;

    h->sps = *sps;

    return 0;

fail:

    av_free(sps);

    return -1;

}

static inline int op(uint8_t **dst, const uint8_t *dst_end,

                     const uint8_t **buf, const uint8_t *buf_end,

                     int pixel, int count,

                     int *x, int width, int linesize)

{

    int remaining = width - *x;

    while(count > 0) {

        int striplen = FFMIN(count, remaining);

        if (buf) {

            striplen = FFMIN(striplen, buf_end - *buf);

            if (*buf >= buf_end)

                goto exhausted;

            memcpy(*dst, *buf, striplen);

            *buf += striplen;

        } else if (pixel >= 0)

            memset(*dst, pixel, striplen);

        *dst      += striplen;

        remaining -= striplen;

        count     -= striplen;

        if (remaining <= 0) {

            *dst      += linesize - width;

            remaining  = width;

        }

        if (linesize > 0) {

            if (*dst >= dst_end) goto exhausted;

        } else {

            if (*dst <= dst_end) goto exhausted;

        }

    }

    *x = width - remaining;

    return 0;



exhausted:

    *x = width - remaining;

    return 1;

}

static void ra144_encode_subblock(RA144Context *ractx,

                                  const int16_t *sblock_data,

                                  const int16_t *lpc_coefs, unsigned int rms,

                                  PutBitContext *pb)

{

    float data[BLOCKSIZE] = { 0 }, work[LPC_ORDER + BLOCKSIZE];

    float coefs[LPC_ORDER];

    float zero[BLOCKSIZE], cba[BLOCKSIZE], cb1[BLOCKSIZE], cb2[BLOCKSIZE];

    int16_t cba_vect[BLOCKSIZE];

    int cba_idx, cb1_idx, cb2_idx, gain;

    int i, n;

    unsigned m[3];

    float g[3];

    float error, best_error;



    for (i = 0; i < LPC_ORDER; i++) {

        work[i] = ractx->curr_sblock[BLOCKSIZE + i];

        coefs[i] = lpc_coefs[i] * (1/4096.0);

    }



    /**

     * Calculate the zero-input response of the LPC filter and subtract it from

     * input data.

     */

    ff_celp_lp_synthesis_filterf(work + LPC_ORDER, coefs, data, BLOCKSIZE,

                                 LPC_ORDER);

    for (i = 0; i < BLOCKSIZE; i++) {

        zero[i] = work[LPC_ORDER + i];

        data[i] = sblock_data[i] - zero[i];

    }



    /**

     * Codebook search is performed without taking into account the contribution

     * of the previous subblock, since it has been just subtracted from input

     * data.

     */

    memset(work, 0, LPC_ORDER * sizeof(*work));



    cba_idx = adaptive_cb_search(ractx->adapt_cb, work + LPC_ORDER, coefs,

                                 data);

    if (cba_idx) {

        /**

         * The filtered vector from the adaptive codebook can be retrieved from

         * work, see implementation of adaptive_cb_search().

         */

        memcpy(cba, work + LPC_ORDER, sizeof(cba));



        ff_copy_and_dup(cba_vect, ractx->adapt_cb, cba_idx + BLOCKSIZE / 2 - 1);

        m[0] = (ff_irms(cba_vect) * rms) >> 12;

    }

    fixed_cb_search(work + LPC_ORDER, coefs, data, cba_idx, &cb1_idx, &cb2_idx);

    for (i = 0; i < BLOCKSIZE; i++) {

        cb1[i] = ff_cb1_vects[cb1_idx][i];

        cb2[i] = ff_cb2_vects[cb2_idx][i];

    }

    ff_celp_lp_synthesis_filterf(work + LPC_ORDER, coefs, cb1, BLOCKSIZE,

                                 LPC_ORDER);

    memcpy(cb1, work + LPC_ORDER, sizeof(cb1));

    m[1] = (ff_cb1_base[cb1_idx] * rms) >> 8;

    ff_celp_lp_synthesis_filterf(work + LPC_ORDER, coefs, cb2, BLOCKSIZE,

                                 LPC_ORDER);

    memcpy(cb2, work + LPC_ORDER, sizeof(cb2));

    m[2] = (ff_cb2_base[cb2_idx] * rms) >> 8;

    best_error = FLT_MAX;

    gain = 0;

    for (n = 0; n < 256; n++) {

        g[1] = ((ff_gain_val_tab[n][1] * m[1]) >> ff_gain_exp_tab[n]) *

               (1/4096.0);

        g[2] = ((ff_gain_val_tab[n][2] * m[2]) >> ff_gain_exp_tab[n]) *

               (1/4096.0);

        error = 0;

        if (cba_idx) {

            g[0] = ((ff_gain_val_tab[n][0] * m[0]) >> ff_gain_exp_tab[n]) *

                   (1/4096.0);

            for (i = 0; i < BLOCKSIZE; i++) {

                data[i] = zero[i] + g[0] * cba[i] + g[1] * cb1[i] +

                          g[2] * cb2[i];

                error += (data[i] - sblock_data[i]) *

                         (data[i] - sblock_data[i]);

            }

        } else {

            for (i = 0; i < BLOCKSIZE; i++) {

                data[i] = zero[i] + g[1] * cb1[i] + g[2] * cb2[i];

                error += (data[i] - sblock_data[i]) *

                         (data[i] - sblock_data[i]);

            }

        }

        if (error < best_error) {

            best_error = error;

            gain = n;

        }

    }

    put_bits(pb, 7, cba_idx);

    put_bits(pb, 8, gain);

    put_bits(pb, 7, cb1_idx);

    put_bits(pb, 7, cb2_idx);

    ff_subblock_synthesis(ractx, lpc_coefs, cba_idx, cb1_idx, cb2_idx, rms,

                          gain);

}

build_qp_table(PPS *pps, int index)

{

    int i;

    for(i = 0; i < 255; i++)

        pps->chroma_qp_table[i & 0xff] = chroma_qp[av_clip(i + index, 0, 51)];

