#endif



    if ((ret = rv34_decoder_alloc(r)) < 0)

        return ret;



    if(!intra_vlcs[0].cbppattern[0].bits)

        rv34_init_tables();



    avctx->internal->allocate_progress = 1;



    return 0;

}

static int flic_decode_frame_24BPP(AVCodecContext *avctx,

                                   void *data, int *got_frame,

                                   const uint8_t *buf, int buf_size)

{

    FlicDecodeContext *s = avctx->priv_data;



    GetByteContext g2;

    int pixel_ptr;

    unsigned char palette_idx1;



    unsigned int frame_size;

    int num_chunks;



    unsigned int chunk_size;

    int chunk_type;



    int i, j, ret;



    int lines;

    int compressed_lines;

    signed short line_packets;

    int y_ptr;

    int byte_run;

    int pixel_skip;

    int pixel_countdown;

    unsigned char *pixels;

    int pixel;

    unsigned int pixel_limit;



    bytestream2_init(&g2, buf, buf_size);



    if ((ret = ff_reget_buffer(avctx, s->frame)) < 0)

        return ret;



    pixels = s->frame->data[0];

    pixel_limit = s->avctx->height * s->frame->linesize[0];



    frame_size = bytestream2_get_le32(&g2);

    bytestream2_skip(&g2, 2);  /* skip the magic number */

    num_chunks = bytestream2_get_le16(&g2);

    bytestream2_skip(&g2, 8);  /* skip padding */

    if (frame_size > buf_size)

        frame_size = buf_size;



    if (frame_size < 16)


    frame_size -= 16;



    /* iterate through the chunks */

    while ((frame_size > 0) && (num_chunks > 0) &&

            bytestream2_get_bytes_left(&g2) >= 4) {

        int stream_ptr_after_chunk;

        chunk_size = bytestream2_get_le32(&g2);

        if (chunk_size > frame_size) {

            av_log(avctx, AV_LOG_WARNING,

                   "Invalid chunk_size = %u > frame_size = %u\n", chunk_size, frame_size);

            chunk_size = frame_size;

        }

        stream_ptr_after_chunk = bytestream2_tell(&g2) - 4 + chunk_size;



        chunk_type = bytestream2_get_le16(&g2);





        switch (chunk_type) {

        case FLI_256_COLOR:

        case FLI_COLOR:

            /* For some reason, it seems that non-palettized flics do

             * include one of these chunks in their first frame.

             * Why I do not know, it seems rather extraneous. */

            ff_dlog(avctx,

                    "Unexpected Palette chunk %d in non-palettized FLC\n",

                    chunk_type);

            bytestream2_skip(&g2, chunk_size - 6);

            break;



        case FLI_DELTA:

        case FLI_DTA_LC:

            y_ptr = 0;

            compressed_lines = bytestream2_get_le16(&g2);

            while (compressed_lines > 0) {

                if (bytestream2_tell(&g2) + 2 > stream_ptr_after_chunk)

                    break;



                line_packets = bytestream2_get_le16(&g2);

                if (line_packets < 0) {

                    line_packets = -line_packets;



                    y_ptr += line_packets * s->frame->linesize[0];

                } else {

                    compressed_lines--;

                    pixel_ptr = y_ptr;

                    CHECK_PIXEL_PTR(0);

                    pixel_countdown = s->avctx->width;

                    for (i = 0; i < line_packets; i++) {

                        /* account for the skip bytes */

                        if (bytestream2_tell(&g2) + 2 > stream_ptr_after_chunk)

                            break;

                        pixel_skip = bytestream2_get_byte(&g2);

                        pixel_ptr += (pixel_skip*3); /* Pixel is 3 bytes wide */

                        pixel_countdown -= pixel_skip;

                        byte_run = sign_extend(bytestream2_get_byte(&g2), 8);

                        if (byte_run < 0) {

                            byte_run = -byte_run;

                            pixel    = bytestream2_get_le24(&g2);

                            CHECK_PIXEL_PTR(3 * byte_run);

                            for (j = 0; j < byte_run; j++, pixel_countdown -= 1) {

                                AV_WL24(&pixels[pixel_ptr], pixel);

                                pixel_ptr += 3;

                            }

                        } else {

                            if (bytestream2_tell(&g2) + 2*byte_run > stream_ptr_after_chunk)

                                break;

                            CHECK_PIXEL_PTR(2 * byte_run);

                            for (j = 0; j < byte_run; j++, pixel_countdown--) {

                                pixel = bytestream2_get_le24(&g2);

                                AV_WL24(&pixels[pixel_ptr], pixel);

                                pixel_ptr += 3;

                            }

                        }

                    }



                    y_ptr += s->frame->linesize[0];

                }

            }

            break;



        case FLI_LC:

            av_log(avctx, AV_LOG_ERROR, "Unexpected FLI_LC chunk in non-palettized FLC\n");

            bytestream2_skip(&g2, chunk_size - 6);

            break;



        case FLI_BLACK:

            /* set the whole frame to 0x00 which is black for 24 bit mode. */

            memset(pixels, 0x00,

                   s->frame->linesize[0] * s->avctx->height);

            break;



        case FLI_BRUN:

            y_ptr = 0;

            for (lines = 0; lines < s->avctx->height; lines++) {

                pixel_ptr = y_ptr;

                /* disregard the line packets; instead, iterate through all

                 * pixels on a row */

                bytestream2_skip(&g2, 1);

                pixel_countdown = (s->avctx->width * 3);



                while (pixel_countdown > 0) {

                    if (bytestream2_tell(&g2) + 1 > stream_ptr_after_chunk)

                        break;

                    byte_run = sign_extend(bytestream2_get_byte(&g2), 8);

                    if (byte_run > 0) {

                        palette_idx1 = bytestream2_get_byte(&g2);

                        CHECK_PIXEL_PTR(byte_run);

                        for (j = 0; j < byte_run; j++) {

                            pixels[pixel_ptr++] = palette_idx1;

                            pixel_countdown--;

                            if (pixel_countdown < 0)

                                av_log(avctx, AV_LOG_ERROR, "pixel_countdown < 0 (%d) (linea%d)\n",

                                       pixel_countdown, lines);

                        }

                    } else {  /* copy bytes if byte_run < 0 */

                        byte_run = -byte_run;

                        if (bytestream2_tell(&g2) + byte_run > stream_ptr_after_chunk)

                            break;

                        CHECK_PIXEL_PTR(byte_run);

                        for (j = 0; j < byte_run; j++) {

                            palette_idx1 = bytestream2_get_byte(&g2);

                            pixels[pixel_ptr++] = palette_idx1;

                            pixel_countdown--;

                            if (pixel_countdown < 0)

                                av_log(avctx, AV_LOG_ERROR, "pixel_countdown < 0 (%d) at line %d\n",

                                       pixel_countdown, lines);

                        }

                    }

                }



                y_ptr += s->frame->linesize[0];

            }

            break;



        case FLI_DTA_BRUN:

            y_ptr = 0;

            for (lines = 0; lines < s->avctx->height; lines++) {

                pixel_ptr = y_ptr;

                /* disregard the line packets; instead, iterate through all

                 * pixels on a row */

                bytestream2_skip(&g2, 1);

                pixel_countdown = s->avctx->width; /* Width is in pixels, not bytes */



                while (pixel_countdown > 0) {

                    if (bytestream2_tell(&g2) + 1 > stream_ptr_after_chunk)

                        break;

                    byte_run = sign_extend(bytestream2_get_byte(&g2), 8);

                    if (byte_run > 0) {

                        pixel = bytestream2_get_le24(&g2);

                        CHECK_PIXEL_PTR(3 * byte_run);

                        for (j = 0; j < byte_run; j++) {

                            AV_WL24(pixels + pixel_ptr, pixel);

                            pixel_ptr += 3;

                            pixel_countdown--;

                            if (pixel_countdown < 0)

                                av_log(avctx, AV_LOG_ERROR, "pixel_countdown < 0 (%d)\n",

                                       pixel_countdown);

                        }

                    } else {  /* copy pixels if byte_run < 0 */

                        byte_run = -byte_run;

                        if (bytestream2_tell(&g2) + 3 * byte_run > stream_ptr_after_chunk)

                            break;

                        CHECK_PIXEL_PTR(3 * byte_run);

                        for (j = 0; j < byte_run; j++) {

                            pixel = bytestream2_get_le24(&g2);

                            AV_WL24(pixels + pixel_ptr, pixel);

                            pixel_ptr  += 3;

                            pixel_countdown--;

                            if (pixel_countdown < 0)

                                av_log(avctx, AV_LOG_ERROR, "pixel_countdown < 0 (%d)\n",

                                       pixel_countdown);

                        }

                    }

                }



                y_ptr += s->frame->linesize[0];

            }

            break;



        case FLI_COPY:

        case FLI_DTA_COPY:

            /* copy the chunk (uncompressed frame) */

            if (chunk_size - 6 > (unsigned int)(FFALIGN(s->avctx->width, 2) * s->avctx->height)*3) {

                av_log(avctx, AV_LOG_ERROR, "In chunk FLI_COPY : source data (%d bytes) " \

                       "bigger than image, skipping chunk\n", chunk_size - 6);

                bytestream2_skip(&g2, chunk_size - 6);

            } else {

                for (y_ptr = 0; y_ptr < s->frame->linesize[0] * s->avctx->height;

                     y_ptr += s->frame->linesize[0]) {



                    pixel_countdown = s->avctx->width;

                    pixel_ptr = 0;

                    while (pixel_countdown > 0) {

                        pixel = bytestream2_get_le24(&g2);

                        AV_WL24(&pixels[y_ptr + pixel_ptr], pixel);

                        pixel_ptr += 3;

                        pixel_countdown--;

                    }

                    if (s->avctx->width & 1)

                        bytestream2_skip(&g2, 3);

                }

            }

            break;



        case FLI_MINI:

            /* some sort of a thumbnail? disregard this chunk... */

            bytestream2_skip(&g2, chunk_size - 6);

            break;



        default:

            av_log(avctx, AV_LOG_ERROR, "Unrecognized chunk type: %d\n", chunk_type);

            break;

        }



        if (stream_ptr_after_chunk - bytestream2_tell(&g2) >= 0) {

            bytestream2_skip(&g2, stream_ptr_after_chunk - bytestream2_tell(&g2));

        } else {

            av_log(avctx, AV_LOG_ERROR, "Chunk overread\n");

            break;

        }



        frame_size -= chunk_size;

        num_chunks--;

    }



    /* by the end of the chunk, the stream ptr should equal the frame

     * size (minus 1, possibly); if it doesn't, issue a warning */

    if ((bytestream2_get_bytes_left(&g2) != 0) && (bytestream2_get_bytes_left(&g2) != 1))

        av_log(avctx, AV_LOG_ERROR, "Processed FLI chunk where chunk size = %d " \

               "and final chunk ptr = %d\n", buf_size, bytestream2_tell(&g2));



    if ((ret = av_frame_ref(data, s->frame)) < 0)

        return ret;



    *got_frame = 1;



    return buf_size;

}

static int h264_mp4toannexb_filter(AVBitStreamFilterContext *bsfc,

                                   AVCodecContext *avctx, const char *args,

                                   uint8_t  **poutbuf, int *poutbuf_size,

                                   const uint8_t *buf, int      buf_size,

                                   int keyframe) {

    H264BSFContext *ctx = bsfc->priv_data;

    uint8_t unit_type;

    int32_t nal_size;

    uint32_t cumul_size = 0;

    const uint8_t *buf_end = buf + buf_size;



    /* nothing to filter */

    if (!avctx->extradata || avctx->extradata_size < 6) {

        *poutbuf = (uint8_t*) buf;

        *poutbuf_size = buf_size;

        return 0;

    }



    /* retrieve sps and pps NAL units from extradata */

    if (!ctx->extradata_parsed) {

        uint16_t unit_size;

        uint64_t total_size = 0;

        uint8_t *out = NULL, unit_nb, sps_done = 0;

        const uint8_t *extradata = avctx->extradata+4;

        static const uint8_t nalu_header[4] = {0, 0, 0, 1};



        /* retrieve length coded size */

        ctx->length_size = (*extradata++ & 0x3) + 1;

        if (ctx->length_size == 3)

            return AVERROR(EINVAL);



        /* retrieve sps and pps unit(s) */

        unit_nb = *extradata++ & 0x1f; /* number of sps unit(s) */

        if (!unit_nb) {

            unit_nb = *extradata++; /* number of pps unit(s) */

            sps_done++;

        }

        while (unit_nb--) {

            void *tmp;



            unit_size = AV_RB16(extradata);

            total_size += unit_size+4;

            if (total_size > INT_MAX - FF_INPUT_BUFFER_PADDING_SIZE ||

                extradata+2+unit_size > avctx->extradata+avctx->extradata_size) {

                av_free(out);

                return AVERROR(EINVAL);

            }

            tmp = av_realloc(out, total_size + FF_INPUT_BUFFER_PADDING_SIZE);

            if (!tmp) {

                av_free(out);

                return AVERROR(ENOMEM);

            }

            out = tmp;

            memcpy(out+total_size-unit_size-4, nalu_header, 4);

            memcpy(out+total_size-unit_size,   extradata+2, unit_size);

            extradata += 2+unit_size;



            if (!unit_nb && !sps_done++)

                unit_nb = *extradata++; /* number of pps unit(s) */

        }



        memset(out + total_size, 0, FF_INPUT_BUFFER_PADDING_SIZE);

        av_free(avctx->extradata);

        avctx->extradata      = out;

        avctx->extradata_size = total_size;

        ctx->first_idr        = 1;

        ctx->extradata_parsed = 1;

    }



    *poutbuf_size = 0;

    *poutbuf = NULL;

    do {

        if (buf + ctx->length_size > buf_end)

            goto fail;



        if (ctx->length_size == 1) {

            nal_size = buf[0];

        } else if (ctx->length_size == 2) {

            nal_size = AV_RB16(buf);

        } else

            nal_size = AV_RB32(buf);



        buf += ctx->length_size;

        unit_type = *buf & 0x1f;



        if (buf + nal_size > buf_end || nal_size < 0)

            goto fail;



        /* prepend only to the first type 5 NAL unit of an IDR picture */

        if (ctx->first_idr && unit_type == 5) {

            if (alloc_and_copy(poutbuf, poutbuf_size,

                               avctx->extradata, avctx->extradata_size,

                               buf, nal_size) < 0)

                goto fail;

            ctx->first_idr = 0;

        } else {

            if (alloc_and_copy(poutbuf, poutbuf_size,

                               NULL, 0,

                               buf, nal_size) < 0)

                goto fail;

            if (!ctx->first_idr && unit_type == 1)

                ctx->first_idr = 1;

        }



        buf += nal_size;

        cumul_size += nal_size + ctx->length_size;

    } while (cumul_size < buf_size);



    return 1;



fail:

    av_freep(poutbuf);

    *poutbuf_size = 0;

    return AVERROR(EINVAL);

}

static int fill_filter_caches(H264Context *h, int mb_type){

    MpegEncContext * const s = &h->s;

    const int mb_xy= h->mb_xy;

    int top_xy, left_xy[2];

    int top_type, left_type[2];



    top_xy     = mb_xy  - (s->mb_stride << MB_FIELD);



    //FIXME deblocking could skip the intra and nnz parts.



    /* Wow, what a mess, why didn't they simplify the interlacing & intra

     * stuff, I can't imagine that these complex rules are worth it. */



    left_xy[1] = left_xy[0] = mb_xy-1;

    if(FRAME_MBAFF){

        const int left_mb_field_flag     = IS_INTERLACED(s->current_picture.mb_type[mb_xy-1]);

        const int curr_mb_field_flag     = IS_INTERLACED(mb_type);

        if(s->mb_y&1){

            if (left_mb_field_flag != curr_mb_field_flag) {

                left_xy[0] -= s->mb_stride;

            }

        }else{

            if(curr_mb_field_flag){

                top_xy      += s->mb_stride & (((s->current_picture.mb_type[top_xy    ]>>7)&1)-1);

            }

            if (left_mb_field_flag != curr_mb_field_flag) {

                left_xy[1] += s->mb_stride;

            }

        }

    }



    h->top_mb_xy = top_xy;

    h->left_mb_xy[0] = left_xy[0];

    h->left_mb_xy[1] = left_xy[1];

    {

        //for sufficiently low qp, filtering wouldn't do anything

        //this is a conservative estimate: could also check beta_offset and more accurate chroma_qp

        int qp_thresh = h->qp_thresh; //FIXME strictly we should store qp_thresh for each mb of a slice

        int qp = s->current_picture.qscale_table[mb_xy];

        if(qp <= qp_thresh

           && (left_xy[0]<0 || ((qp + s->current_picture.qscale_table[left_xy[0]] + 1)>>1) <= qp_thresh)

           && (top_xy   < 0 || ((qp + s->current_picture.qscale_table[top_xy    ] + 1)>>1) <= qp_thresh)){

            if(!FRAME_MBAFF)

                return 1;

            if(   (left_xy[0]< 0            || ((qp + s->current_picture.qscale_table[left_xy[1]             ] + 1)>>1) <= qp_thresh)

               && (top_xy    < s->mb_stride || ((qp + s->current_picture.qscale_table[top_xy    -s->mb_stride] + 1)>>1) <= qp_thresh))

                return 1;

        }

    }



    top_type     = s->current_picture.mb_type[top_xy]    ;

    left_type[0] = s->current_picture.mb_type[left_xy[0]];

    left_type[1] = s->current_picture.mb_type[left_xy[1]];

    if(h->deblocking_filter == 2){

        if(h->slice_table[top_xy     ] != h->slice_num) top_type= 0;

        if(h->slice_table[left_xy[0] ] != h->slice_num) left_type[0]= left_type[1]= 0;

    }else{

        if(h->slice_table[top_xy     ] == 0xFFFF) top_type= 0;

        if(h->slice_table[left_xy[0] ] == 0xFFFF) left_type[0]= left_type[1] =0;

    }

    h->top_type    = top_type    ;

    h->left_type[0]= left_type[0];

    h->left_type[1]= left_type[1];



    if(IS_INTRA(mb_type))

        return 0;



    AV_COPY32(&h->non_zero_count_cache[4+8* 1], &h->non_zero_count[mb_xy][ 0]);

    AV_COPY32(&h->non_zero_count_cache[4+8* 2], &h->non_zero_count[mb_xy][ 4]);

    AV_COPY32(&h->non_zero_count_cache[4+8* 3], &h->non_zero_count[mb_xy][ 8]);

    AV_COPY32(&h->non_zero_count_cache[4+8* 4], &h->non_zero_count[mb_xy][12]);



    h->cbp= h->cbp_table[mb_xy];



    {

        int list;

        for(list=0; list<h->list_count; list++){

            int8_t *ref;

            int y, b_stride;

            int16_t (*mv_dst)[2];

            int16_t (*mv_src)[2];



            if(!USES_LIST(mb_type, list)){

                fill_rectangle(  h->mv_cache[list][scan8[0]], 4, 4, 8, pack16to32(0,0), 4);

                AV_WN32A(&h->ref_cache[list][scan8[ 0]], ((LIST_NOT_USED)&0xFF)*0x01010101u);

                AV_WN32A(&h->ref_cache[list][scan8[ 2]], ((LIST_NOT_USED)&0xFF)*0x01010101u);

                AV_WN32A(&h->ref_cache[list][scan8[ 8]], ((LIST_NOT_USED)&0xFF)*0x01010101u);

                AV_WN32A(&h->ref_cache[list][scan8[10]], ((LIST_NOT_USED)&0xFF)*0x01010101u);

                continue;

            }



            ref = &s->current_picture.ref_index[list][4*mb_xy];

            {

                int (*ref2frm)[64] = h->ref2frm[ h->slice_num&(MAX_SLICES-1) ][0] + (MB_MBAFF ? 20 : 2);

                AV_WN32A(&h->ref_cache[list][scan8[ 0]], (pack16to32(ref2frm[list][ref[0]],ref2frm[list][ref[1]])&0x00FF00FF)*0x0101);

                AV_WN32A(&h->ref_cache[list][scan8[ 2]], (pack16to32(ref2frm[list][ref[0]],ref2frm[list][ref[1]])&0x00FF00FF)*0x0101);

                ref += 2;

                AV_WN32A(&h->ref_cache[list][scan8[ 8]], (pack16to32(ref2frm[list][ref[0]],ref2frm[list][ref[1]])&0x00FF00FF)*0x0101);

                AV_WN32A(&h->ref_cache[list][scan8[10]], (pack16to32(ref2frm[list][ref[0]],ref2frm[list][ref[1]])&0x00FF00FF)*0x0101);

            }



            b_stride = h->b_stride;

            mv_dst   = &h->mv_cache[list][scan8[0]];

            mv_src   = &s->current_picture.motion_val[list][4*s->mb_x + 4*s->mb_y*b_stride];

            for(y=0; y<4; y++){

                AV_COPY128(mv_dst + 8*y, mv_src + y*b_stride);

            }



        }

    }





/*

0 . T T. T T T T

1 L . .L . . . .

2 L . .L . . . .

3 . T TL . . . .

4 L . .L . . . .

5 L . .. . . . .

*/

//FIXME constraint_intra_pred & partitioning & nnz (let us hope this is just a typo in the spec)

    if(top_type){

        AV_COPY32(&h->non_zero_count_cache[4+8*0], &h->non_zero_count[top_xy][3*4]);

    }



    if(left_type[0]){

        h->non_zero_count_cache[3+8*1]= h->non_zero_count[left_xy[0]][3+0*4];

        h->non_zero_count_cache[3+8*2]= h->non_zero_count[left_xy[0]][3+1*4];

        h->non_zero_count_cache[3+8*3]= h->non_zero_count[left_xy[0]][3+2*4];

        h->non_zero_count_cache[3+8*4]= h->non_zero_count[left_xy[0]][3+3*4];

    }



    // CAVLC 8x8dct requires NNZ values for residual decoding that differ from what the loop filter needs

    if(!CABAC && h->pps.transform_8x8_mode){

        if(IS_8x8DCT(top_type)){

            h->non_zero_count_cache[4+8*0]=

            h->non_zero_count_cache[5+8*0]= (h->cbp_table[top_xy] & 0x4000) >> 12;

            h->non_zero_count_cache[6+8*0]=

            h->non_zero_count_cache[7+8*0]= (h->cbp_table[top_xy] & 0x8000) >> 12;

        }

        if(IS_8x8DCT(left_type[0])){

            h->non_zero_count_cache[3+8*1]=

            h->non_zero_count_cache[3+8*2]= (h->cbp_table[left_xy[0]]&0x2000) >> 12; //FIXME check MBAFF

        }

        if(IS_8x8DCT(left_type[1])){

            h->non_zero_count_cache[3+8*3]=

            h->non_zero_count_cache[3+8*4]= (h->cbp_table[left_xy[1]]&0x8000) >> 12; //FIXME check MBAFF

        }



        if(IS_8x8DCT(mb_type)){

            h->non_zero_count_cache[scan8[0   ]]= h->non_zero_count_cache[scan8[1   ]]=

            h->non_zero_count_cache[scan8[2   ]]= h->non_zero_count_cache[scan8[3   ]]= (h->cbp & 0x1000) >> 12;



            h->non_zero_count_cache[scan8[0+ 4]]= h->non_zero_count_cache[scan8[1+ 4]]=

            h->non_zero_count_cache[scan8[2+ 4]]= h->non_zero_count_cache[scan8[3+ 4]]= (h->cbp & 0x2000) >> 12;



            h->non_zero_count_cache[scan8[0+ 8]]= h->non_zero_count_cache[scan8[1+ 8]]=

            h->non_zero_count_cache[scan8[2+ 8]]= h->non_zero_count_cache[scan8[3+ 8]]= (h->cbp & 0x4000) >> 12;



            h->non_zero_count_cache[scan8[0+12]]= h->non_zero_count_cache[scan8[1+12]]=

            h->non_zero_count_cache[scan8[2+12]]= h->non_zero_count_cache[scan8[3+12]]= (h->cbp & 0x8000) >> 12;

        }

    }



    if(IS_INTER(mb_type) || IS_DIRECT(mb_type)){

        int list;

        for(list=0; list<h->list_count; list++){

            if(USES_LIST(top_type, list)){

                const int b_xy= h->mb2b_xy[top_xy] + 3*h->b_stride;

                const int b8_xy= 4*top_xy + 2;

                int (*ref2frm)[64] = h->ref2frm[ h->slice_table[top_xy]&(MAX_SLICES-1) ][0] + (MB_MBAFF ? 20 : 2);

                AV_COPY128(h->mv_cache[list][scan8[0] + 0 - 1*8], s->current_picture.motion_val[list][b_xy + 0]);

                h->ref_cache[list][scan8[0] + 0 - 1*8]=

                h->ref_cache[list][scan8[0] + 1 - 1*8]= ref2frm[list][s->current_picture.ref_index[list][b8_xy + 0]];

                h->ref_cache[list][scan8[0] + 2 - 1*8]=

                h->ref_cache[list][scan8[0] + 3 - 1*8]= ref2frm[list][s->current_picture.ref_index[list][b8_xy + 1]];

            }else{

                AV_ZERO128(h->mv_cache[list][scan8[0] + 0 - 1*8]);

                AV_WN32A(&h->ref_cache[list][scan8[0] + 0 - 1*8], ((LIST_NOT_USED)&0xFF)*0x01010101u);

            }



            if(!IS_INTERLACED(mb_type^left_type[0])){

                if(USES_LIST(left_type[0], list)){

                    const int b_xy= h->mb2b_xy[left_xy[0]] + 3;

                    const int b8_xy= 4*left_xy[0] + 1;

                    int (*ref2frm)[64] = h->ref2frm[ h->slice_table[left_xy[0]]&(MAX_SLICES-1) ][0] + (MB_MBAFF ? 20 : 2);

                    AV_COPY32(h->mv_cache[list][scan8[0] - 1 + 0 ], s->current_picture.motion_val[list][b_xy + h->b_stride*0]);

                    AV_COPY32(h->mv_cache[list][scan8[0] - 1 + 8 ], s->current_picture.motion_val[list][b_xy + h->b_stride*1]);

                    AV_COPY32(h->mv_cache[list][scan8[0] - 1 +16 ], s->current_picture.motion_val[list][b_xy + h->b_stride*2]);

                    AV_COPY32(h->mv_cache[list][scan8[0] - 1 +24 ], s->current_picture.motion_val[list][b_xy + h->b_stride*3]);

                    h->ref_cache[list][scan8[0] - 1 + 0 ]=

                    h->ref_cache[list][scan8[0] - 1 + 8 ]= ref2frm[list][s->current_picture.ref_index[list][b8_xy + 2*0]];

                    h->ref_cache[list][scan8[0] - 1 +16 ]=

                    h->ref_cache[list][scan8[0] - 1 +24 ]= ref2frm[list][s->current_picture.ref_index[list][b8_xy + 2*1]];

                }else{

                    AV_ZERO32(h->mv_cache [list][scan8[0] - 1 + 0 ]);

                    AV_ZERO32(h->mv_cache [list][scan8[0] - 1 + 8 ]);

                    AV_ZERO32(h->mv_cache [list][scan8[0] - 1 +16 ]);

                    AV_ZERO32(h->mv_cache [list][scan8[0] - 1 +24 ]);

                    h->ref_cache[list][scan8[0] - 1 + 0  ]=

                    h->ref_cache[list][scan8[0] - 1 + 8  ]=

                    h->ref_cache[list][scan8[0] - 1 + 16 ]=

                    h->ref_cache[list][scan8[0] - 1 + 24 ]= LIST_NOT_USED;

                }

            }

        }

    }



    return 0;

}

static int ff_estimate_motion_b(MpegEncContext * s,

                       int mb_x, int mb_y, int16_t (*mv_table)[2], Picture *picture, int f_code)

{

    int mx, my, range, dmin;

    int xmin, ymin, xmax, ymax;

    int rel_xmin, rel_ymin, rel_xmax, rel_ymax;

    int pred_x=0, pred_y=0;

    int P[10][2];

    const int shift= 1+s->quarter_sample;

    const int mot_stride = s->mb_width + 2;

    const int mot_xy = (mb_y + 1)*mot_stride + mb_x + 1;

    uint8_t * const ref_picture= picture->data[0];

    uint16_t * const mv_penalty= s->me.mv_penalty[f_code] + MAX_MV;

    int mv_scale;



    s->me.penalty_factor    = get_penalty_factor(s, s->avctx->me_cmp);

    s->me.sub_penalty_factor= get_penalty_factor(s, s->avctx->me_sub_cmp);

    s->me.mb_penalty_factor = get_penalty_factor(s, s->avctx->mb_cmp);



    get_limits(s, &range, &xmin, &ymin, &xmax, &ymax, f_code);

    rel_xmin= xmin - mb_x*16;

    rel_xmax= xmax - mb_x*16;

    rel_ymin= ymin - mb_y*16;

    rel_ymax= ymax - mb_y*16;



    switch(s->me_method) {

    case ME_ZERO:

    default:

	no_motion_search(s, &mx, &my);

        dmin = 0;

        mx-= mb_x*16;

        my-= mb_y*16;

        break;

    case ME_FULL:

	dmin = full_motion_search(s, &mx, &my, range, xmin, ymin, xmax, ymax, ref_picture);

        mx-= mb_x*16;

        my-= mb_y*16;

        break;

    case ME_LOG:

	dmin = log_motion_search(s, &mx, &my, range / 2, xmin, ymin, xmax, ymax, ref_picture);

        mx-= mb_x*16;

        my-= mb_y*16;

        break;

    case ME_PHODS:

	dmin = phods_motion_search(s, &mx, &my, range / 2, xmin, ymin, xmax, ymax, ref_picture);

        mx-= mb_x*16;

        my-= mb_y*16;

        break;

    case ME_X1:

    case ME_EPZS:

       {

            P_LEFT[0]        = mv_table[mot_xy - 1][0];

            P_LEFT[1]        = mv_table[mot_xy - 1][1];



            if(P_LEFT[0]       > (rel_xmax<<shift)) P_LEFT[0]       = (rel_xmax<<shift);



            /* special case for first line */

            if (mb_y) {

                P_TOP[0] = mv_table[mot_xy - mot_stride             ][0];

                P_TOP[1] = mv_table[mot_xy - mot_stride             ][1];

                P_TOPRIGHT[0] = mv_table[mot_xy - mot_stride + 1         ][0];

                P_TOPRIGHT[1] = mv_table[mot_xy - mot_stride + 1         ][1];

                if(P_TOP[1] > (rel_ymax<<shift)) P_TOP[1]= (rel_ymax<<shift);

                if(P_TOPRIGHT[0] < (rel_xmin<<shift)) P_TOPRIGHT[0]= (rel_xmin<<shift);

                if(P_TOPRIGHT[1] > (rel_ymax<<shift)) P_TOPRIGHT[1]= (rel_ymax<<shift);



                P_MEDIAN[0]= mid_pred(P_LEFT[0], P_TOP[0], P_TOPRIGHT[0]);

                P_MEDIAN[1]= mid_pred(P_LEFT[1], P_TOP[1], P_TOPRIGHT[1]);

            }

            pred_x= P_LEFT[0];

            pred_y= P_LEFT[1];

        }



        if(mv_table == s->b_forw_mv_table){

            mv_scale= (s->pb_time<<16) / (s->pp_time<<shift);

        }else{

            mv_scale= ((s->pb_time - s->pp_time)<<16) / (s->pp_time<<shift);

        }



        dmin = s->me.motion_search[0](s, 0, &mx, &my, P, pred_x, pred_y, rel_xmin, rel_ymin, rel_xmax, rel_ymax, 

                                      picture, s->p_mv_table, mv_scale, mv_penalty);



        break;

    }



    dmin= s->me.sub_motion_search(s, &mx, &my, dmin, rel_xmin, rel_ymin, rel_xmax, rel_ymax,

				   pred_x, pred_y, picture, 0, 0, mv_penalty);



    if(s->avctx->me_sub_cmp != s->avctx->mb_cmp && !s->me.skip)

        dmin= s->me.get_mb_score(s, mx, my, pred_x, pred_y, picture, mv_penalty);



//printf("%d %d %d %d//", s->mb_x, s->mb_y, mx, my);

//    s->mb_type[mb_y*s->mb_width + mb_x]= mb_type;

    mv_table[mot_xy][0]= mx;

    mv_table[mot_xy][1]= my;



    return dmin;

}

static inline int get_scale(GetBitContext *gb, int level, int value)

{

    if (level < 5) {

        /* huffman encoded */

        value += get_bitalloc(gb, &dca_scalefactor, level);

    } else if (level < 8)

        value = get_bits(gb, level + 1);

    return value;

}

static av_cold int alac_decode_init(AVCodecContext * avctx)

{

    int ret;

    int req_packed;

    ALACContext *alac = avctx->priv_data;

    alac->avctx = avctx;



    /* initialize from the extradata */

    if (alac->avctx->extradata_size != ALAC_EXTRADATA_SIZE) {

        av_log(avctx, AV_LOG_ERROR, "expected %d extradata bytes\n",

            ALAC_EXTRADATA_SIZE);

        return -1;

    }

    if (alac_set_info(alac)) {

        av_log(avctx, AV_LOG_ERROR, "set_info failed\n");

        return -1;

    }



    req_packed = LIBAVCODEC_VERSION_MAJOR < 55 && !av_sample_fmt_is_planar(avctx->request_sample_fmt);

    switch (alac->sample_size) {

    case 16: avctx->sample_fmt = req_packed ? AV_SAMPLE_FMT_S16 : AV_SAMPLE_FMT_S16P;

             break;

    case 24:

    case 32: avctx->sample_fmt = req_packed ? AV_SAMPLE_FMT_S32 : AV_SAMPLE_FMT_S32P;

             break;

    default: av_log_ask_for_sample(avctx, "Sample depth %d is not supported.\n",

                                   alac->sample_size);

             return AVERROR_PATCHWELCOME;

    }

    avctx->bits_per_raw_sample = alac->sample_size;



    if (alac->channels < 1) {

        av_log(avctx, AV_LOG_WARNING, "Invalid channel count\n");

        alac->channels = avctx->channels;

    } else {

        if (alac->channels > MAX_CHANNELS)

            alac->channels = avctx->channels;

        else

            avctx->channels = alac->channels;

    }

    if (avctx->channels > MAX_CHANNELS) {

        av_log(avctx, AV_LOG_ERROR, "Unsupported channel count: %d\n",

               avctx->channels);

        return AVERROR_PATCHWELCOME;

    }

    avctx->channel_layout = alac_channel_layouts[alac->channels - 1];



    if ((ret = allocate_buffers(alac)) < 0) {

        av_log(avctx, AV_LOG_ERROR, "Error allocating buffers\n");

        return ret;

    }



    avcodec_get_frame_defaults(&alac->frame);

    avctx->coded_frame = &alac->frame;



    return 0;

}

static void qtrle_decode_8bpp(QtrleContext *s)

{

    int stream_ptr;

    int header;

    int start_line;

    int lines_to_change;

    signed char rle_code;

    int row_ptr, pixel_ptr;

    int row_inc = s->frame.linesize[0];

    unsigned char pi1, pi2, pi3, pi4;  /* 4 palette indices */

    unsigned char *rgb = s->frame.data[0];

    int pixel_limit = s->frame.linesize[0] * s->avctx->height;



    /* check if this frame is even supposed to change */

    if (s->size < 8)

        return;



    /* start after the chunk size */

    stream_ptr = 4;



    /* fetch the header */

    CHECK_STREAM_PTR(2);

    header = BE_16(&s->buf[stream_ptr]);

    stream_ptr += 2;



    /* if a header is present, fetch additional decoding parameters */

    if (header & 0x0008) {

        CHECK_STREAM_PTR(8);

        start_line = BE_16(&s->buf[stream_ptr]);

        stream_ptr += 4;

        lines_to_change = BE_16(&s->buf[stream_ptr]);

        stream_ptr += 4;

    } else {

        start_line = 0;

        lines_to_change = s->avctx->height;

    }



    row_ptr = row_inc * start_line;

    while (lines_to_change--) {

        CHECK_STREAM_PTR(2);

        pixel_ptr = row_ptr + (4 * (s->buf[stream_ptr++] - 1));



        while ((rle_code = (signed char)s->buf[stream_ptr++]) != -1) {

            if (rle_code == 0) {

                /* there's another skip code in the stream */

                CHECK_STREAM_PTR(1);

                pixel_ptr += (4 * (s->buf[stream_ptr++] - 1));

            } else if (rle_code < 0) {

                /* decode the run length code */

                rle_code = -rle_code;

                /* get the next 4 bytes from the stream, treat them as palette

                 * indices, and output them rle_code times */

                CHECK_STREAM_PTR(4);

                pi1 = s->buf[stream_ptr++];

                pi2 = s->buf[stream_ptr++];

                pi3 = s->buf[stream_ptr++];

                pi4 = s->buf[stream_ptr++];



                CHECK_PIXEL_PTR(rle_code * 4);



                while (rle_code--) {

                    rgb[pixel_ptr++] = pi1;

                    rgb[pixel_ptr++] = pi2;

                    rgb[pixel_ptr++] = pi3;

                    rgb[pixel_ptr++] = pi4;

                }

            } else {

                /* copy the same pixel directly to output 4 times */

                rle_code *= 4;

                CHECK_STREAM_PTR(rle_code);

                CHECK_PIXEL_PTR(rle_code);



                while (rle_code--) {

                    rgb[pixel_ptr++] = s->buf[stream_ptr++];

                }

            }

        }

        row_ptr += row_inc;

    }

}

static int mxf_read_source_package(MXFPackage *package, ByteIOContext *pb, int tag)

{

    switch(tag) {

    case 0x4403:

        package->tracks_count = get_be32(pb);

        if (package->tracks_count >= UINT_MAX / sizeof(UID))

            return -1;

        package->tracks_refs = av_malloc(package->tracks_count * sizeof(UID));

        if (!package->tracks_refs)

            return -1;

        url_fskip(pb, 4); /* useless size of objects, always 16 according to specs */

        get_buffer(pb, (uint8_t *)package->tracks_refs, package->tracks_count * sizeof(UID));

        break;

    case 0x4401:

        /* UMID, only get last 16 bytes */

        url_fskip(pb, 16);

        get_buffer(pb, package->package_uid, 16);

        break;

    case 0x4701:

        get_buffer(pb, package->descriptor_ref, 16);

        break;

    }

    return 0;

}

static int decode_packet(AVCodecContext *avctx, void *data,
                         int *got_frame_ptr, AVPacket* avpkt)
{
    WMAProDecodeCtx *s = avctx->priv_data;
    GetBitContext* gb  = &s->pgb;
    const uint8_t* buf = avpkt->data;
    int buf_size       = avpkt->size;
    int num_bits_prev_frame;
    int packet_sequence_number;
    *got_frame_ptr = 0;
    if (s->skip_packets > 0) {
        s->skip_packets--;
        return FFMIN(avpkt->size, avctx->block_align);
    if (s->packet_done || s->packet_loss) {
        s->packet_done = 0;
        /** sanity check for the buffer length */
        if (avctx->codec_id == AV_CODEC_ID_WMAPRO && buf_size < avctx->block_align) {
            av_log(avctx, AV_LOG_ERROR, "Input packet too small (%d < %d)\n",
                   buf_size, avctx->block_align);
            return AVERROR_INVALIDDATA;
        if (avctx->codec_id == AV_CODEC_ID_WMAPRO) {
            s->next_packet_start = buf_size - avctx->block_align;
            buf_size = avctx->block_align;
        } else {
            s->next_packet_start = buf_size - FFMIN(buf_size, avctx->block_align);
            buf_size = FFMIN(buf_size, avctx->block_align);
        s->buf_bit_size = buf_size << 3;
        /** parse packet header */
        init_get_bits(gb, buf, s->buf_bit_size);
        if (avctx->codec_id != AV_CODEC_ID_XMA2) {
            packet_sequence_number = get_bits(gb, 4);
            skip_bits(gb, 2);
        } else {
            s->num_frames = get_bits(gb, 6);
            packet_sequence_number = 0;
        /** get number of bits that need to be added to the previous frame */
        num_bits_prev_frame = get_bits(gb, s->log2_frame_size);
        if (avctx->codec_id != AV_CODEC_ID_WMAPRO) {
            skip_bits(gb, 3);
            s->skip_packets = get_bits(gb, 8);
        ff_dlog(avctx, "packet[%d]: nbpf %x\n", avctx->frame_number,
                num_bits_prev_frame);
        /** check for packet loss */
        if (avctx->codec_id != AV_CODEC_ID_XMA2 && !s->packet_loss &&
            ((s->packet_sequence_number + 1) & 0xF) != packet_sequence_number) {
            av_log(avctx, AV_LOG_ERROR,
                   "Packet loss detected! seq %"PRIx8" vs %x\n",
                   s->packet_sequence_number, packet_sequence_number);
        s->packet_sequence_number = packet_sequence_number;
        if (num_bits_prev_frame > 0) {
            int remaining_packet_bits = s->buf_bit_size - get_bits_count(gb);
            if (num_bits_prev_frame >= remaining_packet_bits) {
                num_bits_prev_frame = remaining_packet_bits;
                s->packet_done = 1;
            /** append the previous frame data to the remaining data from the
                previous packet to create a full frame */
            save_bits(s, gb, num_bits_prev_frame, 1);
            ff_dlog(avctx, "accumulated %x bits of frame data\n",
                    s->num_saved_bits - s->frame_offset);
            /** decode the cross packet frame if it is valid */
            if (!s->packet_loss)
                decode_frame(s, data, got_frame_ptr);
        } else if (s->num_saved_bits - s->frame_offset) {
            ff_dlog(avctx, "ignoring %x previously saved bits\n",
                    s->num_saved_bits - s->frame_offset);
        if (s->packet_loss) {
            /** reset number of saved bits so that the decoder
                does not start to decode incomplete frames in the
                s->len_prefix == 0 case */
            s->num_saved_bits = 0;
            s->packet_loss = 0;
    } else {
        int frame_size;
        s->buf_bit_size = (avpkt->size - s->next_packet_start) << 3;
        init_get_bits(gb, avpkt->data, s->buf_bit_size);
        skip_bits(gb, s->packet_offset);
        if (s->len_prefix && remaining_bits(s, gb) > s->log2_frame_size &&
            (frame_size = show_bits(gb, s->log2_frame_size)) &&
            frame_size <= remaining_bits(s, gb)) {
            save_bits(s, gb, frame_size, 0);
            if (!s->packet_loss)
                s->packet_done = !decode_frame(s, data, got_frame_ptr);
        } else if (!s->len_prefix
                   && s->num_saved_bits > get_bits_count(&s->gb)) {
            /** when the frames do not have a length prefix, we don't know
                the compressed length of the individual frames
                however, we know what part of a new packet belongs to the
                previous frame
                therefore we save the incoming packet first, then we append
                the "previous frame" data from the next packet so that
                we get a buffer that only contains full frames */
            s->packet_done = !decode_frame(s, data, got_frame_ptr);
        } else
            s->packet_done = 1;
    if (s->packet_done && !s->packet_loss &&
        remaining_bits(s, gb) > 0) {
        /** save the rest of the data so that it can be decoded
            with the next packet */
        save_bits(s, gb, remaining_bits(s, gb), 0);
    s->packet_offset = get_bits_count(gb) & 7;
    if (s->packet_loss)
        return AVERROR_INVALIDDATA;
    return get_bits_count(gb) >> 3;

int ff_pca(PCA *pca, double *eigenvector, double *eigenvalue){

    int i, j, k, pass;

    const int n= pca->n;

    double z[n];



    memset(eigenvector, 0, sizeof(double)*n*n);



    for(j=0; j<n; j++){

        pca->mean[j] /= pca->count;

        eigenvector[j + j*n] = 1.0;

        for(i=0; i<=j; i++){

            pca->covariance[j + i*n] /= pca->count;

            pca->covariance[j + i*n] -= pca->mean[i] * pca->mean[j];

            pca->covariance[i + j*n] = pca->covariance[j + i*n];

        }

        eigenvalue[j]= pca->covariance[j + j*n];

        z[j]= 0;

    }



    for(pass=0; pass < 50; pass++){

        double sum=0;



        for(i=0; i<n; i++)

            for(j=i+1; j<n; j++)

                sum += fabs(pca->covariance[j + i*n]);



        if(sum == 0){

            for(i=0; i<n; i++){

                double maxvalue= -1;

                for(j=i; j<n; j++){

                    if(eigenvalue[j] > maxvalue){

                        maxvalue= eigenvalue[j];

                        k= j;

                    }

                }

                eigenvalue[k]= eigenvalue[i];

                eigenvalue[i]= maxvalue;

                for(j=0; j<n; j++){

                    double tmp= eigenvector[k + j*n];

                    eigenvector[k + j*n]= eigenvector[i + j*n];

                    eigenvector[i + j*n]= tmp;

                }

            }

            return pass;

        }



        for(i=0; i<n; i++){

            for(j=i+1; j<n; j++){

                double covar= pca->covariance[j + i*n];

                double t,c,s,tau,theta, h;



                if(pass < 3 && fabs(covar) < sum / (5*n*n)) //FIXME why pass < 3

                    continue;

                if(fabs(covar) == 0.0) //FIXME shouldnt be needed

                    continue;

                if(pass >=3 && fabs((eigenvalue[j]+z[j])/covar) > (1LL<<32) && fabs((eigenvalue[i]+z[i])/covar) > (1LL<<32)){

                    pca->covariance[j + i*n]=0.0;

                    continue;

                }



                h= (eigenvalue[j]+z[j]) - (eigenvalue[i]+z[i]);

                theta=0.5*h/covar;

                t=1.0/(fabs(theta)+sqrt(1.0+theta*theta));

                if(theta < 0.0) t = -t;



                c=1.0/sqrt(1+t*t);

                s=t*c;

                tau=s/(1.0+c);

                z[i] -= t*covar;

                z[j] += t*covar;



#define ROTATE(a,i,j,k,l) {\

    double g=a[j + i*n];\

    double h=a[l + k*n];\

    a[j + i*n]=g-s*(h+g*tau);\

    a[l + k*n]=h+s*(g-h*tau); }

                for(k=0; k<n; k++) {

                    if(k!=i && k!=j){

                        ROTATE(pca->covariance,FFMIN(k,i),FFMAX(k,i),FFMIN(k,j),FFMAX(k,j))

                    }

                    ROTATE(eigenvector,k,i,k,j)

                }

                pca->covariance[j + i*n]=0.0;

            }

        }

        for (i=0; i<n; i++) {

            eigenvalue[i] += z[i];

            z[i]=0.0;

        }

    }



    return -1;

}

static int svq1_decode_frame(AVCodecContext *avctx, void *data,

                             int *data_size, AVPacket *avpkt)

{

    const uint8_t *buf = avpkt->data;

    int buf_size       = avpkt->size;

    MpegEncContext *s  = avctx->priv_data;

    uint8_t *current, *previous;

    int result, i, x, y, width, height;

    AVFrame *pict = data;

    svq1_pmv *pmv;



    /* initialize bit buffer */

    init_get_bits(&s->gb, buf, buf_size * 8);



    /* decode frame header */

    s->f_code = get_bits(&s->gb, 22);



    if ((s->f_code & ~0x70) || !(s->f_code & 0x60))

        return AVERROR_INVALIDDATA;



    /* swap some header bytes (why?) */

    if (s->f_code != 0x20) {

        uint32_t *src = (uint32_t *)(buf + 4);



        if (buf_size < 36)

            return AVERROR_INVALIDDATA;



        for (i = 0; i < 4; i++)

            src[i] = ((src[i] << 16) | (src[i] >> 16)) ^ src[7 - i];

    }



    result = svq1_decode_frame_header(&s->gb, s);

    if (result) {

        av_dlog(s->avctx, "Error in svq1_decode_frame_header %i\n", result);

        return result;

    }

    avcodec_set_dimensions(avctx, s->width, s->height);



    /* FIXME: This avoids some confusion for "B frames" without 2 references.

     * This should be removed after libavcodec can handle more flexible

     * picture types & ordering */

    if (s->pict_type == AV_PICTURE_TYPE_B && s->last_picture_ptr == NULL)

        return buf_size;



    if ((avctx->skip_frame >= AVDISCARD_NONREF &&

         s->pict_type == AV_PICTURE_TYPE_B)    ||

        (avctx->skip_frame >= AVDISCARD_NONKEY &&

         s->pict_type != AV_PICTURE_TYPE_I)    ||

        avctx->skip_frame >= AVDISCARD_ALL)

        return buf_size;



    if ((result = ff_MPV_frame_start(s, avctx)) < 0)

        return result;



    pmv = av_malloc((FFALIGN(s->width, 16) / 8 + 3) * sizeof(*pmv));

    if (!pmv)

        return AVERROR(ENOMEM);



    /* decode y, u and v components */

    for (i = 0; i < 3; i++) {

        int linesize;

        if (i == 0) {

            width    = FFALIGN(s->width,  16);

            height   = FFALIGN(s->height, 16);

            linesize = s->linesize;

        } else {

            if (s->flags & CODEC_FLAG_GRAY)

                break;

            width    = FFALIGN(s->width  / 4, 16);

            height   = FFALIGN(s->height / 4, 16);

            linesize = s->uvlinesize;

        }



        current = s->current_picture.f.data[i];



        if (s->pict_type == AV_PICTURE_TYPE_B)

            previous = s->next_picture.f.data[i];

        else

            previous = s->last_picture.f.data[i];



        if (s->pict_type == AV_PICTURE_TYPE_I) {

            /* keyframe */

            for (y = 0; y < height; y += 16) {

                for (x = 0; x < width; x += 16) {

                    result = svq1_decode_block_intra(&s->gb, &current[x],

                                                     linesize);

                    if (result) {

                        av_log(s->avctx, AV_LOG_ERROR,

                               "Error in svq1_decode_block %i (keyframe)\n",

                               result);

                        goto err;

                    }

                }

                current += 16 * linesize;

            }

        } else {

            /* delta frame */

            memset(pmv, 0, ((width / 8) + 3) * sizeof(svq1_pmv));



            for (y = 0; y < height; y += 16) {

                for (x = 0; x < width; x += 16) {

                    result = svq1_decode_delta_block(s, &s->gb, &current[x],

                                                     previous, linesize,

                                                     pmv, x, y);

                    if (result) {

                        av_dlog(s->avctx,

                                "Error in svq1_decode_delta_block %i\n",

                                result);

                        goto err;

                    }

                }



                pmv[0].x     =

                    pmv[0].y = 0;



                current += 16 * linesize;

            }

        }

    }



    *pict = s->current_picture.f;




    ff_MPV_frame_end(s);



    *data_size = sizeof(AVFrame);

    result     = buf_size;



err:

    av_free(pmv);

    return result;

}

static av_cold void movie_uninit(AVFilterContext *ctx)

{

    MovieContext *movie = ctx->priv;

    int i;



    for (i = 0; i < ctx->nb_outputs; i++) {

        av_freep(&ctx->output_pads[i].name);

        if (movie->st[i].st)

            avcodec_close(movie->st[i].st->codec);

    }

    av_freep(&movie->st);

    av_freep(&movie->out_index);

    av_frame_free(&movie->frame);

    if (movie->format_ctx)

        avformat_close_input(&movie->format_ctx);

}

static void chroma(WaveformContext *s, AVFrame *in, AVFrame *out,

                   int component, int intensity, int offset, int column)

{

    const int plane = s->desc->comp[component].plane;

    const int mirror = s->mirror;

    const int c0_linesize = in->linesize[(plane + 1) % s->ncomp];

    const int c1_linesize = in->linesize[(plane + 2) % s->ncomp];

    const int dst_linesize = out->linesize[plane];

    const int max = 255 - intensity;

    const int src_h = in->height;

    const int src_w = in->width;

    int x, y;



    if (column) {

        const int dst_signed_linesize = dst_linesize * (mirror == 1 ? -1 : 1);



        for (x = 0; x < src_w; x++) {

            const uint8_t *c0_data = in->data[(plane + 1) % s->ncomp];

            const uint8_t *c1_data = in->data[(plane + 2) % s->ncomp];

            uint8_t *dst_data = out->data[plane] + offset * dst_linesize;

            uint8_t * const dst_bottom_line = dst_data + dst_linesize * (s->size - 1);

            uint8_t * const dst_line = (mirror ? dst_bottom_line : dst_data);

            uint8_t *dst = dst_line;



            for (y = 0; y < src_h; y++) {

                const int sum = FFABS(c0_data[x] - 128) + FFABS(c1_data[x] - 128);

                uint8_t *target;

                int p;



                for (p = 256 - sum; p < 256 + sum; p++) {

                    target = dst + x + dst_signed_linesize * p;

                    update(target, max, 1);

                }



                c0_data += c0_linesize;

                c1_data += c1_linesize;

                dst_data += dst_linesize;

            }

        }

    } else {

        const uint8_t *c0_data = in->data[(plane + 1) % s->ncomp];

        const uint8_t *c1_data = in->data[(plane + 2) % s->ncomp];

        uint8_t *dst_data = out->data[plane] + offset;



        if (mirror)

            dst_data += s->size - 1;

        for (y = 0; y < src_h; y++) {

            for (x = 0; x < src_w; x++) {

                const int sum = FFABS(c0_data[x] - 128) + FFABS(c1_data[x] - 128);

                uint8_t *target;

                int p;



                for (p = 256 - sum; p < 256 + sum; p++) {

                    if (mirror)

                        target = dst_data - p;

                    else

                        target = dst_data + p;



                    update(target, max, 1);

                }

            }



            c0_data += c0_linesize;

            c1_data += c1_linesize;

            dst_data += dst_linesize;

        }

    }



    envelope(s, out, plane, (plane + 0) % s->ncomp);

}

int put_wav_header(ByteIOContext *pb, AVCodecContext *enc)

{

    int bps, blkalign, bytespersec;

    int hdrsize = 18;



    if(!enc->codec_tag || enc->codec_tag > 0xffff)

       enc->codec_tag = codec_get_tag(codec_wav_tags, enc->codec_id);

    if(!enc->codec_tag)

        return -1;



    put_le16(pb, enc->codec_tag);

    put_le16(pb, enc->channels);

    put_le32(pb, enc->sample_rate);

    if (enc->codec_id == CODEC_ID_PCM_U8 ||

        enc->codec_id == CODEC_ID_PCM_ALAW ||

        enc->codec_id == CODEC_ID_PCM_MULAW) {

        bps = 8;

    } else if (enc->codec_id == CODEC_ID_MP2 || enc->codec_id == CODEC_ID_MP3) {

        bps = 0;

    } else if (enc->codec_id == CODEC_ID_ADPCM_IMA_WAV || enc->codec_id == CODEC_ID_ADPCM_MS || enc->codec_id == CODEC_ID_ADPCM_G726 || enc->codec_id == CODEC_ID_ADPCM_YAMAHA) { //

        bps = 4;

    } else if (enc->codec_id == CODEC_ID_PCM_S24LE) {

        bps = 24;

    } else if (enc->codec_id == CODEC_ID_PCM_S32LE) {

        bps = 32;

    } else {

        bps = 16;

    }



    if (enc->codec_id == CODEC_ID_MP2 || enc->codec_id == CODEC_ID_MP3) {

        blkalign = enc->frame_size; //this is wrong, but seems many demuxers dont work if this is set correctly

        //blkalign = 144 * enc->bit_rate/enc->sample_rate;

    } else if (enc->codec_id == CODEC_ID_ADPCM_G726) { //

        blkalign = 1;

    } else if (enc->block_align != 0) { /* specified by the codec */

        blkalign = enc->block_align;

    } else

        blkalign = enc->channels*bps >> 3;

    if (enc->codec_id == CODEC_ID_PCM_U8 ||

        enc->codec_id == CODEC_ID_PCM_S24LE ||

        enc->codec_id == CODEC_ID_PCM_S32LE ||

        enc->codec_id == CODEC_ID_PCM_S16LE) {

        bytespersec = enc->sample_rate * blkalign;

    } else {

        bytespersec = enc->bit_rate / 8;

    }

    put_le32(pb, bytespersec); /* bytes per second */

    put_le16(pb, blkalign); /* block align */

    put_le16(pb, bps); /* bits per sample */

    if (enc->codec_id == CODEC_ID_MP3) {

        put_le16(pb, 12); /* wav_extra_size */

        hdrsize += 12;

        put_le16(pb, 1); /* wID */

        put_le32(pb, 2); /* fdwFlags */

        put_le16(pb, 1152); /* nBlockSize */

        put_le16(pb, 1); /* nFramesPerBlock */

        put_le16(pb, 1393); /* nCodecDelay */

    } else if (enc->codec_id == CODEC_ID_MP2) {

        put_le16(pb, 22); /* wav_extra_size */

        hdrsize += 22;

        put_le16(pb, 2);  /* fwHeadLayer */

        put_le32(pb, enc->bit_rate); /* dwHeadBitrate */

        put_le16(pb, enc->channels == 2 ? 1 : 8); /* fwHeadMode */

        put_le16(pb, 0);  /* fwHeadModeExt */

        put_le16(pb, 1);  /* wHeadEmphasis */

        put_le16(pb, 16); /* fwHeadFlags */

        put_le32(pb, 0);  /* dwPTSLow */

        put_le32(pb, 0);  /* dwPTSHigh */

    } else if (enc->codec_id == CODEC_ID_ADPCM_IMA_WAV) {

        put_le16(pb, 2); /* wav_extra_size */

        hdrsize += 2;

        put_le16(pb, ((enc->block_align - 4 * enc->channels) / (4 * enc->channels)) * 8 + 1); /* wSamplesPerBlock */

    } else if(enc->extradata_size){

        put_le16(pb, enc->extradata_size);

        put_buffer(pb, enc->extradata, enc->extradata_size);

        hdrsize += enc->extradata_size;

        if(hdrsize&1){

            hdrsize++;

            put_byte(pb, 0);

        }

    } else {

        hdrsize -= 2;

    }



    return hdrsize;

}

static inline int get_egolomb(GetBitContext *gb)

{

    int v = 4;



    while (get_bits1(gb)) v++;



    return (1 << v) + get_bits(gb, v);

}

static int read_access_unit(AVCodecContext *avctx, void* data, int *data_size,

                            const uint8_t *buf, int buf_size)

{

    MLPDecodeContext *m = avctx->priv_data;

    GetBitContext gb;

    unsigned int length, substr;

    unsigned int substream_start;

    unsigned int header_size = 4;

    unsigned int substr_header_size = 0;

    uint8_t substream_parity_present[MAX_SUBSTREAMS];

    uint16_t substream_data_len[MAX_SUBSTREAMS];

    uint8_t parity_bits;



    if (buf_size < 4)

        return 0;



    length = (AV_RB16(buf) & 0xfff) * 2;



    if (length > buf_size)

        return -1;



    init_get_bits(&gb, (buf + 4), (length - 4) * 8);



    if (show_bits_long(&gb, 31) == (0xf8726fba >> 1)) {

        if (read_major_sync(m, &gb) < 0)

            goto error;

        header_size += 28;

    }



    if (!m->params_valid) {

        av_log(m->avctx, AV_LOG_WARNING,

               "Stream parameters not seen; skipping frame.\n");

        *data_size = 0;

        return length;

    }



    substream_start = 0;



    for (substr = 0; substr < m->num_substreams; substr++) {

        int extraword_present, checkdata_present, end;



        extraword_present = get_bits1(&gb);

        skip_bits1(&gb);

        checkdata_present = get_bits1(&gb);

        skip_bits1(&gb);



        end = get_bits(&gb, 12) * 2;



        substr_header_size += 2;



        if (extraword_present) {

            skip_bits(&gb, 16);

            substr_header_size += 2;

        }



        if (end + header_size + substr_header_size > length) {

            av_log(m->avctx, AV_LOG_ERROR,

                   "Indicated length of substream %d data goes off end of "

                   "packet.\n", substr);

            end = length - header_size - substr_header_size;

        }



        if (end < substream_start) {

            av_log(avctx, AV_LOG_ERROR,

                   "Indicated end offset of substream %d data "

                   "is smaller than calculated start offset.\n",

                   substr);

            goto error;

        }



        if (substr > m->max_decoded_substream)

            continue;



        substream_parity_present[substr] = checkdata_present;

        substream_data_len[substr] = end - substream_start;

        substream_start = end;

    }



    parity_bits  = ff_mlp_calculate_parity(buf, 4);

    parity_bits ^= ff_mlp_calculate_parity(buf + header_size, substr_header_size);



    if ((((parity_bits >> 4) ^ parity_bits) & 0xF) != 0xF) {

        av_log(avctx, AV_LOG_ERROR, "Parity check failed.\n");

        goto error;

    }



    buf += header_size + substr_header_size;



    for (substr = 0; substr <= m->max_decoded_substream; substr++) {

        SubStream *s = &m->substream[substr];

        init_get_bits(&gb, buf, substream_data_len[substr] * 8);



        s->blockpos = 0;

        do {

            if (get_bits1(&gb)) {

                if (get_bits1(&gb)) {

                    /* A restart header should be present. */

                    if (read_restart_header(m, &gb, buf, substr) < 0)

                        goto next_substr;

                    s->restart_seen = 1;

                }



                if (!s->restart_seen) {

                    goto next_substr;

                }



                if (read_decoding_params(m, &gb, substr) < 0)

                    goto next_substr;

            }



            if (!s->restart_seen) {

                goto next_substr;

            }



            if (read_block_data(m, &gb, substr) < 0)

                return -1;



            if (get_bits_count(&gb) >= substream_data_len[substr] * 8)

                goto substream_length_mismatch;



        } while (!get_bits1(&gb));



        skip_bits(&gb, (-get_bits_count(&gb)) & 15);

        if (substream_data_len[substr] * 8 - get_bits_count(&gb) >= 32) {

            int shorten_by;



            if (get_bits(&gb, 16) != 0xD234)

                return -1;



            shorten_by = get_bits(&gb, 16);

            if      (m->avctx->codec_id == CODEC_ID_TRUEHD && shorten_by  & 0x2000)

                s->blockpos -= FFMIN(shorten_by & 0x1FFF, s->blockpos);

            else if (m->avctx->codec_id == CODEC_ID_MLP    && shorten_by != 0xD234)

                return -1;



            if (substr == m->max_decoded_substream)

                av_log(m->avctx, AV_LOG_INFO, "End of stream indicated.\n");

        }

        if (substream_parity_present[substr]) {

            uint8_t parity, checksum;



            if (substream_data_len[substr] * 8 - get_bits_count(&gb) != 16)

                goto substream_length_mismatch;



            parity   = ff_mlp_calculate_parity(buf, substream_data_len[substr] - 2);

            checksum = ff_mlp_checksum8       (buf, substream_data_len[substr] - 2);



            if ((get_bits(&gb, 8) ^ parity) != 0xa9    )

                av_log(m->avctx, AV_LOG_ERROR, "Substream %d parity check failed.\n", substr);

            if ( get_bits(&gb, 8)           != checksum)

                av_log(m->avctx, AV_LOG_ERROR, "Substream %d checksum failed.\n"    , substr);

        }

        if (substream_data_len[substr] * 8 != get_bits_count(&gb)) {

            goto substream_length_mismatch;

        }



next_substr:

        if (!s->restart_seen) {

            av_log(m->avctx, AV_LOG_ERROR,

                   "No restart header present in substream %d.\n", substr);

        }



        buf += substream_data_len[substr];

    }



    rematrix_channels(m, m->max_decoded_substream);



    if (output_data(m, m->max_decoded_substream, data, data_size) < 0)

        return -1;



    return length;



substream_length_mismatch:

    av_log(m->avctx, AV_LOG_ERROR, "substream %d length mismatch\n", substr);

    return -1;



error:

    m->params_valid = 0;

    return -1;

}

int ff_get_buffer(AVCodecContext *avctx, AVFrame *frame, int flags)

{

    int ret;



    switch (avctx->codec_type) {

    case AVMEDIA_TYPE_VIDEO:

        if (!frame->width)

            frame->width               = avctx->width;

        if (!frame->height)

            frame->height              = avctx->height;

        if (frame->format < 0)

            frame->format              = avctx->pix_fmt;

        if (!frame->sample_aspect_ratio.num)

            frame->sample_aspect_ratio = avctx->sample_aspect_ratio;



        if ((ret = av_image_check_size(avctx->width, avctx->height, 0, avctx)) < 0)

            return ret;

        break;

    case AVMEDIA_TYPE_AUDIO:

        if (!frame->sample_rate)

            frame->sample_rate    = avctx->sample_rate;

        if (frame->format < 0)

            frame->format         = avctx->sample_fmt;

        if (!frame->channel_layout)

            frame->channel_layout = avctx->channel_layout;

        break;

    default: return AVERROR(EINVAL);

    }



    frame->pkt_pts = avctx->pkt ? avctx->pkt->pts : AV_NOPTS_VALUE;

    frame->reordered_opaque = avctx->reordered_opaque;



#if FF_API_GET_BUFFER

    /*

     * Wrap an old get_buffer()-allocated buffer in an bunch of AVBuffers.

     * We wrap each plane in its own AVBuffer. Each of those has a reference to

     * a dummy AVBuffer as its private data, unreffing it on free.

     * When all the planes are freed, the dummy buffer's free callback calls

     * release_buffer().

     */

    if (avctx->get_buffer) {

        CompatReleaseBufPriv *priv = NULL;

        AVBufferRef *dummy_buf = NULL;

        int planes, i, ret;



        if (flags & AV_GET_BUFFER_FLAG_REF)

            frame->reference    = 1;



        ret = avctx->get_buffer(avctx, frame);

        if (ret < 0)

            return ret;



        /* return if the buffers are already set up

         * this would happen e.g. when a custom get_buffer() calls

         * avcodec_default_get_buffer

         */

        if (frame->buf[0])

            return 0;



        priv = av_mallocz(sizeof(*priv));

        if (!priv) {

            ret = AVERROR(ENOMEM);

            goto fail;

        }

        priv->avctx = *avctx;

        priv->frame = *frame;



        dummy_buf = av_buffer_create(NULL, 0, compat_free_buffer, priv, 0);

        if (!dummy_buf) {

            ret = AVERROR(ENOMEM);

            goto fail;

        }



#define WRAP_PLANE(ref_out, data, data_size)                            \

do {                                                                    \

    AVBufferRef *dummy_ref = av_buffer_ref(dummy_buf);                  \

    if (!dummy_ref) {                                                   \

        ret = AVERROR(ENOMEM);                                          \

        goto fail;                                                      \

    }                                                                   \

    ref_out = av_buffer_create(data, data_size, compat_release_buffer,  \

                               dummy_ref, 0);                           \

    if (!ref_out) {                                                     \

        av_frame_unref(frame);                                          \

        ret = AVERROR(ENOMEM);                                          \

        goto fail;                                                      \

    }                                                                   \

} while (0)



        if (avctx->codec_type == AVMEDIA_TYPE_VIDEO) {

            const AVPixFmtDescriptor *desc = av_pix_fmt_desc_get(frame->format);



            if (!desc) {

                ret = AVERROR(EINVAL);

                goto fail;

            }

            planes = (desc->flags & PIX_FMT_PLANAR) ? desc->nb_components : 1;



            for (i = 0; i < planes; i++) {

                int h_shift    = (i == 1 || i == 2) ? desc->log2_chroma_h : 0;

                int plane_size = (frame->width >> h_shift) * frame->linesize[i];



                WRAP_PLANE(frame->buf[i], frame->data[i], plane_size);

            }

        } else {

            int planar = av_sample_fmt_is_planar(frame->format);

            planes = planar ? avctx->channels : 1;



            if (planes > FF_ARRAY_ELEMS(frame->buf)) {

                frame->nb_extended_buf = planes - FF_ARRAY_ELEMS(frame->buf);

                frame->extended_buf = av_malloc(sizeof(*frame->extended_buf) *

                                                frame->nb_extended_buf);

                if (!frame->extended_buf) {

                    ret = AVERROR(ENOMEM);

                    goto fail;

                }

            }



            for (i = 0; i < FFMIN(planes, FF_ARRAY_ELEMS(frame->buf)); i++)

                WRAP_PLANE(frame->buf[i], frame->extended_data[i], frame->linesize[0]);



            for (i = 0; i < planes - FF_ARRAY_ELEMS(frame->buf); i++)

                WRAP_PLANE(frame->extended_buf[i],

                           frame->extended_data[i + FF_ARRAY_ELEMS(frame->buf)],

                           frame->linesize[0]);

        }



        av_buffer_unref(&dummy_buf);



        return 0;



fail:

        avctx->release_buffer(avctx, frame);

        av_freep(&priv);

        av_buffer_unref(&dummy_buf);

        return ret;

    }

#endif



    return avctx->get_buffer2(avctx, frame, flags);

}

static av_cold void common_init(H264Context *h){

    MpegEncContext * const s = &h->s;



