        }

    }

    if(FRAME_MBAFF){

        if( (s->mb_y&1) == 0 )

            h->mb_mbaff = h->mb_field_decoding_flag = get_bits1(&s->gb);

    }



    h->prev_mb_skipped= 0;



    mb_type= get_ue_golomb(&s->gb);

    if(h->slice_type_nos == FF_B_TYPE){

        if(mb_type < 23){

            partition_count= b_mb_type_info[mb_type].partition_count;

            mb_type=         b_mb_type_info[mb_type].type;

        }else{

            mb_type -= 23;

            goto decode_intra_mb;

        }

    }else if(h->slice_type_nos == FF_P_TYPE){

        if(mb_type < 5){

            partition_count= p_mb_type_info[mb_type].partition_count;

            mb_type=         p_mb_type_info[mb_type].type;

        }else{

            mb_type -= 5;

            goto decode_intra_mb;

        }

    }else{

       assert(h->slice_type_nos == FF_I_TYPE);

        if(h->slice_type == FF_SI_TYPE && mb_type)

            mb_type--;

decode_intra_mb:

        if(mb_type > 25){

            av_log(h->s.avctx, AV_LOG_ERROR, "mb_type %d in %c slice too large at %d %d\n", mb_type, av_get_pict_type_char(h->slice_type), s->mb_x, s->mb_y);

            return -1;

        }

        partition_count=0;

        cbp= i_mb_type_info[mb_type].cbp;

        h->intra16x16_pred_mode= i_mb_type_info[mb_type].pred_mode;

        mb_type= i_mb_type_info[mb_type].type;

    }



    if(MB_FIELD)

        mb_type |= MB_TYPE_INTERLACED;



    h->slice_table[ mb_xy ]= h->slice_num;



    if(IS_INTRA_PCM(mb_type)){

        unsigned int x;



        // We assume these blocks are very rare so we do not optimize it.

        align_get_bits(&s->gb);



        // The pixels are stored in the same order as levels in h->mb array.

        for(x=0; x < (CHROMA ? 384 : 256); x++){

            ((uint8_t*)h->mb)[x]= get_bits(&s->gb, 8);

        }



        // In deblocking, the quantizer is 0

        s->current_picture.qscale_table[mb_xy]= 0;

        // All coeffs are present

        memset(h->non_zero_count[mb_xy], 16, 16);



        s->current_picture.mb_type[mb_xy]= mb_type;

        return 0;

    }



    if(MB_MBAFF){

        h->ref_count[0] <<= 1;

        h->ref_count[1] <<= 1;

    }



    fill_caches(h, mb_type, 0);



    //mb_pred

    if(IS_INTRA(mb_type)){

        int pred_mode;

//            init_top_left_availability(h);

        if(IS_INTRA4x4(mb_type)){

            int i;

            int di = 1;

            if(dct8x8_allowed && get_bits1(&s->gb)){

                mb_type |= MB_TYPE_8x8DCT;

                di = 4;

            }



//                fill_intra4x4_pred_table(h);

            for(i=0; i<16; i+=di){

                int mode= pred_intra_mode(h, i);



                if(!get_bits1(&s->gb)){

                    const int rem_mode= get_bits(&s->gb, 3);

                    mode = rem_mode + (rem_mode >= mode);

                }



                if(di==4)

                    fill_rectangle( &h->intra4x4_pred_mode_cache[ scan8[i] ], 2, 2, 8, mode, 1 );

                else

                    h->intra4x4_pred_mode_cache[ scan8[i] ] = mode;

            }

            ff_h264_write_back_intra_pred_mode(h);

            if( ff_h264_check_intra4x4_pred_mode(h) < 0)

                return -1;

        }else{

            h->intra16x16_pred_mode= ff_h264_check_intra_pred_mode(h, h->intra16x16_pred_mode);

            if(h->intra16x16_pred_mode < 0)

                return -1;

        }

        if(CHROMA){

            pred_mode= ff_h264_check_intra_pred_mode(h, get_ue_golomb_31(&s->gb));

            if(pred_mode < 0)

                return -1;

            h->chroma_pred_mode= pred_mode;

        }

    }else if(partition_count==4){

        int i, j, sub_partition_count[4], list, ref[2][4];



        if(h->slice_type_nos == FF_B_TYPE){

            for(i=0; i<4; i++){

                h->sub_mb_type[i]= get_ue_golomb_31(&s->gb);

                if(h->sub_mb_type[i] >=13){

                    av_log(h->s.avctx, AV_LOG_ERROR, "B sub_mb_type %u out of range at %d %d\n", h->sub_mb_type[i], s->mb_x, s->mb_y);

                    return -1;

                }

                sub_partition_count[i]= b_sub_mb_type_info[ h->sub_mb_type[i] ].partition_count;

                h->sub_mb_type[i]=      b_sub_mb_type_info[ h->sub_mb_type[i] ].type;

            }

            if(   IS_DIRECT(h->sub_mb_type[0]) || IS_DIRECT(h->sub_mb_type[1])

               || IS_DIRECT(h->sub_mb_type[2]) || IS_DIRECT(h->sub_mb_type[3])) {

                ff_h264_pred_direct_motion(h, &mb_type);

                h->ref_cache[0][scan8[4]] =

                h->ref_cache[1][scan8[4]] =

                h->ref_cache[0][scan8[12]] =

                h->ref_cache[1][scan8[12]] = PART_NOT_AVAILABLE;

            }

        }else{

            assert(h->slice_type_nos == FF_P_TYPE); //FIXME SP correct ?

            for(i=0; i<4; i++){

                h->sub_mb_type[i]= get_ue_golomb_31(&s->gb);

                if(h->sub_mb_type[i] >=4){

                    av_log(h->s.avctx, AV_LOG_ERROR, "P sub_mb_type %u out of range at %d %d\n", h->sub_mb_type[i], s->mb_x, s->mb_y);

                    return -1;

                }

                sub_partition_count[i]= p_sub_mb_type_info[ h->sub_mb_type[i] ].partition_count;

                h->sub_mb_type[i]=      p_sub_mb_type_info[ h->sub_mb_type[i] ].type;

            }

        }



        for(list=0; list<h->list_count; list++){

            int ref_count= IS_REF0(mb_type) ? 1 : h->ref_count[list];

            for(i=0; i<4; i++){

                if(IS_DIRECT(h->sub_mb_type[i])) continue;

                if(IS_DIR(h->sub_mb_type[i], 0, list)){

                    unsigned int tmp;

                    if(ref_count == 1){

                        tmp= 0;

                    }else if(ref_count == 2){

                        tmp= get_bits1(&s->gb)^1;

                    }else{

                        tmp= get_ue_golomb_31(&s->gb);

                        if(tmp>=ref_count){

                            av_log(h->s.avctx, AV_LOG_ERROR, "ref %u overflow\n", tmp);

                            return -1;

                        }

                    }

                    ref[list][i]= tmp;

                }else{

                 //FIXME

                    ref[list][i] = -1;

                }

            }

        }



        if(dct8x8_allowed)

            dct8x8_allowed = get_dct8x8_allowed(h);



        for(list=0; list<h->list_count; list++){

            for(i=0; i<4; i++){

                if(IS_DIRECT(h->sub_mb_type[i])) {

                    h->ref_cache[list][ scan8[4*i] ] = h->ref_cache[list][ scan8[4*i]+1 ];

                    continue;

                }

                h->ref_cache[list][ scan8[4*i]   ]=h->ref_cache[list][ scan8[4*i]+1 ]=

                h->ref_cache[list][ scan8[4*i]+8 ]=h->ref_cache[list][ scan8[4*i]+9 ]= ref[list][i];



                if(IS_DIR(h->sub_mb_type[i], 0, list)){

                    const int sub_mb_type= h->sub_mb_type[i];

                    const int block_width= (sub_mb_type & (MB_TYPE_16x16|MB_TYPE_16x8)) ? 2 : 1;

                    for(j=0; j<sub_partition_count[i]; j++){

                        int mx, my;

                        const int index= 4*i + block_width*j;

                        int16_t (* mv_cache)[2]= &h->mv_cache[list][ scan8[index] ];

                        pred_motion(h, index, block_width, list, h->ref_cache[list][ scan8[index] ], &mx, &my);

                        mx += get_se_golomb(&s->gb);

                        my += get_se_golomb(&s->gb);

                        tprintf(s->avctx, "final mv:%d %d\n", mx, my);



                        if(IS_SUB_8X8(sub_mb_type)){

                            mv_cache[ 1 ][0]=

                            mv_cache[ 8 ][0]= mv_cache[ 9 ][0]= mx;

                            mv_cache[ 1 ][1]=

                            mv_cache[ 8 ][1]= mv_cache[ 9 ][1]= my;

                        }else if(IS_SUB_8X4(sub_mb_type)){

                            mv_cache[ 1 ][0]= mx;

                            mv_cache[ 1 ][1]= my;

                        }else if(IS_SUB_4X8(sub_mb_type)){

                            mv_cache[ 8 ][0]= mx;

                            mv_cache[ 8 ][1]= my;

                        }

                        mv_cache[ 0 ][0]= mx;

                        mv_cache[ 0 ][1]= my;

                    }

                }else{

                    uint32_t *p= (uint32_t *)&h->mv_cache[list][ scan8[4*i] ][0];

                    p[0] = p[1]=

                    p[8] = p[9]= 0;

                }

            }

        }

    }else if(IS_DIRECT(mb_type)){

        ff_h264_pred_direct_motion(h, &mb_type);

        dct8x8_allowed &= h->sps.direct_8x8_inference_flag;

    }else{

        int list, mx, my, i;

         //FIXME we should set ref_idx_l? to 0 if we use that later ...

        if(IS_16X16(mb_type)){

            for(list=0; list<h->list_count; list++){

                    unsigned int val;

                    if(IS_DIR(mb_type, 0, list)){

                        if(h->ref_count[list]==1){

                            val= 0;

                        }else if(h->ref_count[list]==2){

                            val= get_bits1(&s->gb)^1;

                        }else{

                            val= get_ue_golomb_31(&s->gb);

                            if(val >= h->ref_count[list]){

                                av_log(h->s.avctx, AV_LOG_ERROR, "ref %u overflow\n", val);

                                return -1;

                            }

                        }

                    }else

                        val= LIST_NOT_USED&0xFF;

                    fill_rectangle(&h->ref_cache[list][ scan8[0] ], 4, 4, 8, val, 1);

            }

            for(list=0; list<h->list_count; list++){

                unsigned int val;

                if(IS_DIR(mb_type, 0, list)){

                    pred_motion(h, 0, 4, list, h->ref_cache[list][ scan8[0] ], &mx, &my);

                    mx += get_se_golomb(&s->gb);

                    my += get_se_golomb(&s->gb);

                    tprintf(s->avctx, "final mv:%d %d\n", mx, my);



                    val= pack16to32(mx,my);

                }else

                    val=0;

                fill_rectangle(h->mv_cache[list][ scan8[0] ], 4, 4, 8, val, 4);

            }

        }

        else if(IS_16X8(mb_type)){

            for(list=0; list<h->list_count; list++){

                    for(i=0; i<2; i++){

                        unsigned int val;

                        if(IS_DIR(mb_type, i, list)){

                            if(h->ref_count[list] == 1){

                                val= 0;

                            }else if(h->ref_count[list] == 2){

                                val= get_bits1(&s->gb)^1;

                            }else{

                                val= get_ue_golomb_31(&s->gb);

                                if(val >= h->ref_count[list]){

                                    av_log(h->s.avctx, AV_LOG_ERROR, "ref %u overflow\n", val);

                                    return -1;

                                }

                            }

                        }else

                            val= LIST_NOT_USED&0xFF;

                        fill_rectangle(&h->ref_cache[list][ scan8[0] + 16*i ], 4, 2, 8, val, 1);

                    }

            }

            for(list=0; list<h->list_count; list++){

                for(i=0; i<2; i++){

                    unsigned int val;

                    if(IS_DIR(mb_type, i, list)){

                        pred_16x8_motion(h, 8*i, list, h->ref_cache[list][scan8[0] + 16*i], &mx, &my);

                        mx += get_se_golomb(&s->gb);

                        my += get_se_golomb(&s->gb);

                        tprintf(s->avctx, "final mv:%d %d\n", mx, my);



                        val= pack16to32(mx,my);

                    }else

                        val=0;

                    fill_rectangle(h->mv_cache[list][ scan8[0] + 16*i ], 4, 2, 8, val, 4);

                }

            }

        }else{

            assert(IS_8X16(mb_type));

            for(list=0; list<h->list_count; list++){

                    for(i=0; i<2; i++){

                        unsigned int val;

                        if(IS_DIR(mb_type, i, list)){ //FIXME optimize

                            if(h->ref_count[list]==1){

                                val= 0;

                            }else if(h->ref_count[list]==2){

                                val= get_bits1(&s->gb)^1;

                            }else{

                                val= get_ue_golomb_31(&s->gb);

                                if(val >= h->ref_count[list]){

                                    av_log(h->s.avctx, AV_LOG_ERROR, "ref %u overflow\n", val);

                                    return -1;

                                }

                            }

                        }else

                            val= LIST_NOT_USED&0xFF;

                        fill_rectangle(&h->ref_cache[list][ scan8[0] + 2*i ], 2, 4, 8, val, 1);

                    }

            }

            for(list=0; list<h->list_count; list++){

                for(i=0; i<2; i++){

                    unsigned int val;

                    if(IS_DIR(mb_type, i, list)){

                        pred_8x16_motion(h, i*4, list, h->ref_cache[list][ scan8[0] + 2*i ], &mx, &my);

                        mx += get_se_golomb(&s->gb);

                        my += get_se_golomb(&s->gb);

                        tprintf(s->avctx, "final mv:%d %d\n", mx, my);



                        val= pack16to32(mx,my);

                    }else

                        val=0;

                    fill_rectangle(h->mv_cache[list][ scan8[0] + 2*i ], 2, 4, 8, val, 4);

                }

            }

        }

    }



    if(IS_INTER(mb_type))

        write_back_motion(h, mb_type);



    if(!IS_INTRA16x16(mb_type)){

        cbp= get_ue_golomb(&s->gb);

        if(cbp > 47){

            av_log(h->s.avctx, AV_LOG_ERROR, "cbp too large (%u) at %d %d\n", cbp, s->mb_x, s->mb_y);

            return -1;

        }



        if(CHROMA){

            if(IS_INTRA4x4(mb_type)) cbp= golomb_to_intra4x4_cbp[cbp];

            else                     cbp= golomb_to_inter_cbp   [cbp];

        }else{

            if(IS_INTRA4x4(mb_type)) cbp= golomb_to_intra4x4_cbp_gray[cbp];

            else                     cbp= golomb_to_inter_cbp_gray[cbp];

        }

    }

    h->cbp = cbp;



    if(dct8x8_allowed && (cbp&15) && !IS_INTRA(mb_type)){

        if(get_bits1(&s->gb)){

            mb_type |= MB_TYPE_8x8DCT;

            h->cbp_table[mb_xy]= cbp;

        }

    }

    s->current_picture.mb_type[mb_xy]= mb_type;



    if(cbp || IS_INTRA16x16(mb_type)){

        int i8x8, i4x4, chroma_idx;

        int dquant;

        GetBitContext *gb= IS_INTRA(mb_type) ? h->intra_gb_ptr : h->inter_gb_ptr;

        const uint8_t *scan, *scan8x8, *dc_scan;



//        fill_non_zero_count_cache(h);



        if(IS_INTERLACED(mb_type)){

            scan8x8= s->qscale ? h->field_scan8x8_cavlc : h->field_scan8x8_cavlc_q0;

            scan= s->qscale ? h->field_scan : h->field_scan_q0;

            dc_scan= luma_dc_field_scan;

        }else{

            scan8x8= s->qscale ? h->zigzag_scan8x8_cavlc : h->zigzag_scan8x8_cavlc_q0;

            scan= s->qscale ? h->zigzag_scan : h->zigzag_scan_q0;

            dc_scan= luma_dc_zigzag_scan;

        }



        dquant= get_se_golomb(&s->gb);



        if( dquant > 25 || dquant < -26 ){

            av_log(h->s.avctx, AV_LOG_ERROR, "dquant out of range (%d) at %d %d\n", dquant, s->mb_x, s->mb_y);

            return -1;

        }



        s->qscale += dquant;

        if(((unsigned)s->qscale) > 51){

            if(s->qscale<0) s->qscale+= 52;

            else            s->qscale-= 52;

        }



        h->chroma_qp[0]= get_chroma_qp(h, 0, s->qscale);

        h->chroma_qp[1]= get_chroma_qp(h, 1, s->qscale);

        if(IS_INTRA16x16(mb_type)){

            if( decode_residual(h, h->intra_gb_ptr, h->mb, LUMA_DC_BLOCK_INDEX, dc_scan, h->dequant4_coeff[0][s->qscale], 16) < 0){

                return -1; //FIXME continue if partitioned and other return -1 too

            }



            assert((cbp&15) == 0 || (cbp&15) == 15);



            if(cbp&15){

                for(i8x8=0; i8x8<4; i8x8++){

                    for(i4x4=0; i4x4<4; i4x4++){

                        const int index= i4x4 + 4*i8x8;

                        if( decode_residual(h, h->intra_gb_ptr, h->mb + 16*index, index, scan + 1, h->dequant4_coeff[0][s->qscale], 15) < 0 ){

                            return -1;

                        }

                    }

                }

            }else{

                fill_rectangle(&h->non_zero_count_cache[scan8[0]], 4, 4, 8, 0, 1);

            }

        }else{

            for(i8x8=0; i8x8<4; i8x8++){

                if(cbp & (1<<i8x8)){

                    if(IS_8x8DCT(mb_type)){

                        DCTELEM *buf = &h->mb[64*i8x8];

                        uint8_t *nnz;

                        for(i4x4=0; i4x4<4; i4x4++){

                            if( decode_residual(h, gb, buf, i4x4+4*i8x8, scan8x8+16*i4x4,

                                                h->dequant8_coeff[IS_INTRA( mb_type ) ? 0:1][s->qscale], 16) <0 )

                                return -1;

                        }

                        nnz= &h->non_zero_count_cache[ scan8[4*i8x8] ];

                        nnz[0] += nnz[1] + nnz[8] + nnz[9];

                    }else{

                        for(i4x4=0; i4x4<4; i4x4++){

                            const int index= i4x4 + 4*i8x8;



                            if( decode_residual(h, gb, h->mb + 16*index, index, scan, h->dequant4_coeff[IS_INTRA( mb_type ) ? 0:3][s->qscale], 16) <0 ){

                                return -1;

                            }

                        }

                    }

                }else{

                    uint8_t * const nnz= &h->non_zero_count_cache[ scan8[4*i8x8] ];

                    nnz[0] = nnz[1] = nnz[8] = nnz[9] = 0;

                }

            }

        }



        if(cbp&0x30){

            for(chroma_idx=0; chroma_idx<2; chroma_idx++)

                if( decode_residual(h, gb, h->mb + 256 + 16*4*chroma_idx, CHROMA_DC_BLOCK_INDEX, chroma_dc_scan, NULL, 4) < 0){

                    return -1;

                }

        }



        if(cbp&0x20){

            for(chroma_idx=0; chroma_idx<2; chroma_idx++){

                const uint32_t *qmul = h->dequant4_coeff[chroma_idx+1+(IS_INTRA( mb_type ) ? 0:3)][h->chroma_qp[chroma_idx]];

                for(i4x4=0; i4x4<4; i4x4++){

                    const int index= 16 + 4*chroma_idx + i4x4;

                    if( decode_residual(h, gb, h->mb + 16*index, index, scan + 1, qmul, 15) < 0){

                        return -1;

                    }

                }

            }

        }else{

            uint8_t * const nnz= &h->non_zero_count_cache[0];

            nnz[ scan8[16]+0 ] = nnz[ scan8[16]+1 ] =nnz[ scan8[16]+8 ] =nnz[ scan8[16]+9 ] =

            nnz[ scan8[20]+0 ] = nnz[ scan8[20]+1 ] =nnz[ scan8[20]+8 ] =nnz[ scan8[20]+9 ] = 0;

        }

    }else{

        uint8_t * const nnz= &h->non_zero_count_cache[0];

        fill_rectangle(&nnz[scan8[0]], 4, 4, 8, 0, 1);

        nnz[ scan8[16]+0 ] = nnz[ scan8[16]+1 ] =nnz[ scan8[16]+8 ] =nnz[ scan8[16]+9 ] =

        nnz[ scan8[20]+0 ] = nnz[ scan8[20]+1 ] =nnz[ scan8[20]+8 ] =nnz[ scan8[20]+9 ] = 0;

    }

    s->current_picture.qscale_table[mb_xy]= s->qscale;

    write_back_non_zero_count(h);



    if(MB_MBAFF){

        h->ref_count[0] >>= 1;

        h->ref_count[1] >>= 1;

    }



    return 0;

}

int av_opt_set(void *obj, const char *name, const char *val, int search_flags)

{

    int ret = 0;

    void *dst, *target_obj;

    const AVOption *o = av_opt_find2(obj, name, NULL, 0, search_flags, &target_obj);

    if (!o || !target_obj)

        return AVERROR_OPTION_NOT_FOUND;

    if (!val && (o->type != AV_OPT_TYPE_STRING &&

                 o->type != AV_OPT_TYPE_PIXEL_FMT && o->type != AV_OPT_TYPE_SAMPLE_FMT &&

                 o->type != AV_OPT_TYPE_IMAGE_SIZE && o->type != AV_OPT_TYPE_VIDEO_RATE &&

                 o->type != AV_OPT_TYPE_DURATION && o->type != AV_OPT_TYPE_COLOR &&

                 o->type != AV_OPT_TYPE_CHANNEL_LAYOUT && o->type != AV_OPT_TYPE_BOOL))

        return AVERROR(EINVAL);



    if (o->flags & AV_OPT_FLAG_READONLY)

        return AVERROR(EINVAL);



    dst = ((uint8_t *)target_obj) + o->offset;

    switch (o->type) {

    case AV_OPT_TYPE_BOOL:

        return set_string_bool(obj, o, val, dst);

    case AV_OPT_TYPE_STRING:

        return set_string(obj, o, val, dst);

    case AV_OPT_TYPE_BINARY:

        return set_string_binary(obj, o, val, dst);

    case AV_OPT_TYPE_FLAGS:

    case AV_OPT_TYPE_INT:

    case AV_OPT_TYPE_INT64:

    case AV_OPT_TYPE_FLOAT:

    case AV_OPT_TYPE_DOUBLE:

    case AV_OPT_TYPE_RATIONAL:

        return set_string_number(obj, target_obj, o, val, dst);

    case AV_OPT_TYPE_IMAGE_SIZE:

        return set_string_image_size(obj, o, val, dst);

    case AV_OPT_TYPE_VIDEO_RATE:

        return set_string_video_rate(obj, o, val, dst);

    case AV_OPT_TYPE_PIXEL_FMT:

        return set_string_pixel_fmt(obj, o, val, dst);

    case AV_OPT_TYPE_SAMPLE_FMT:

        return set_string_sample_fmt(obj, o, val, dst);

    case AV_OPT_TYPE_DURATION:

        if (!val) {

            *(int64_t *)dst = 0;

            return 0;

        } else {

            if ((ret = av_parse_time(dst, val, 1)) < 0)

                av_log(obj, AV_LOG_ERROR, "Unable to parse option value \"%s\" as duration\n", val);

            return ret;

        }

        break;

    case AV_OPT_TYPE_COLOR:

        return set_string_color(obj, o, val, dst);

    case AV_OPT_TYPE_CHANNEL_LAYOUT:

        if (!val || !strcmp(val, "none")) {

            *(int64_t *)dst = 0;

        } else {

            int64_t cl = av_get_channel_layout(val);

            if (!cl) {

                av_log(obj, AV_LOG_ERROR, "Unable to parse option value \"%s\" as channel layout\n", val);

                ret = AVERROR(EINVAL);

            }

            *(int64_t *)dst = cl;

            return ret;

        }

        break;

    }



    av_log(obj, AV_LOG_ERROR, "Invalid option type.\n");

    return AVERROR(EINVAL);

}

static int64_t dv_frame_offset(AVFormatContext *s, DVDemuxContext *c,

                               int64_t timestamp, int flags)

{

    // FIXME: sys may be wrong if last dv_read_packet() failed (buffer is junk)

    const AVDVProfile *sys = av_dv_codec_profile2(c->vst->codec->width, c->vst->codec->height,

                                                 c->vst->codec->pix_fmt, c->vst->codec->time_base);

    int64_t offset;

    int64_t size       = avio_size(s->pb) - s->internal->data_offset;

    int64_t max_offset = ((size - 1) / sys->frame_size) * sys->frame_size;



    offset = sys->frame_size * timestamp;



    if (size >= 0 && offset > max_offset)

        offset = max_offset;

    else if (offset < 0)

        offset = 0;



    return offset + s->internal->data_offset;

}

static int ogg_read_page(AVFormatContext *s, int *sid)

{

    AVIOContext *bc = s->pb;

    struct ogg *ogg = s->priv_data;

    struct ogg_stream *os;

    int ret, i = 0;

    int flags, nsegs;

    uint64_t gp;

    uint32_t serial;

    int size, idx;

    uint8_t sync[4];

    int sp = 0;



    ret = avio_read(bc, sync, 4);

    if (ret < 4)

        return ret < 0 ? ret : AVERROR_EOF;



    do {

        int c;



        if (sync[sp & 3] == 'O' &&

            sync[(sp + 1) & 3] == 'g' &&

            sync[(sp + 2) & 3] == 'g' && sync[(sp + 3) & 3] == 'S')

            break;



        if(!i && bc->seekable && ogg->page_pos > 0) {

            memset(sync, 0, 4);

            avio_seek(bc, ogg->page_pos+4, SEEK_SET);

            ogg->page_pos = -1;

        }



        c = avio_r8(bc);



        if (avio_feof(bc))

            return AVERROR_EOF;



        sync[sp++ & 3] = c;

    } while (i++ < MAX_PAGE_SIZE);



    if (i >= MAX_PAGE_SIZE) {

        av_log(s, AV_LOG_INFO, "cannot find sync word\n");

        return AVERROR_INVALIDDATA;

    }



    if (avio_r8(bc) != 0) {      /* version */

        av_log (s, AV_LOG_ERROR, "ogg page, unsupported version\n");

        return AVERROR_INVALIDDATA;

    }



    flags  = avio_r8(bc);

    gp     = avio_rl64(bc);

    serial = avio_rl32(bc);

    avio_skip(bc, 8); /* seq, crc */

    nsegs  = avio_r8(bc);



    idx = ogg_find_stream(ogg, serial);

    if (idx < 0) {

        if (data_packets_seen(ogg))

            idx = ogg_replace_stream(s, serial, nsegs);

        else

            idx = ogg_new_stream(s, serial);



        if (idx < 0) {

            av_log(s, AV_LOG_ERROR, "failed to create or replace stream\n");

            return idx;

        }

    }



    os = ogg->streams + idx;

    ogg->page_pos =

    os->page_pos = avio_tell(bc) - 27;



    if (os->psize > 0)

        ogg_new_buf(ogg, idx);



    ret = avio_read(bc, os->segments, nsegs);

    if (ret < nsegs)

        return ret < 0 ? ret : AVERROR_EOF;



    os->nsegs = nsegs;

    os->segp  = 0;



    size = 0;

    for (i = 0; i < nsegs; i++)

        size += os->segments[i];



    if (!(flags & OGG_FLAG_BOS))

        os->got_data = 1;



    if (flags & OGG_FLAG_CONT || os->incomplete) {

        if (!os->psize) {

            // If this is the very first segment we started

            // playback in the middle of a continuation packet.

            // Discard it since we missed the start of it.

            while (os->segp < os->nsegs) {

                int seg = os->segments[os->segp++];

                os->pstart += seg;

                if (seg < 255)

                    break;

            }

            os->sync_pos = os->page_pos;

        }

    } else {

        os->psize    = 0;

        os->sync_pos = os->page_pos;

    }



    if (os->bufsize - os->bufpos < size) {

        uint8_t *nb = av_malloc((os->bufsize *= 2) + FF_INPUT_BUFFER_PADDING_SIZE);

        if (!nb)

            return AVERROR(ENOMEM);

        memcpy(nb, os->buf, os->bufpos);

        av_free(os->buf);

        os->buf = nb;

    }



    ret = avio_read(bc, os->buf + os->bufpos, size);

    if (ret < size)

        return ret < 0 ? ret : AVERROR_EOF;



    os->bufpos += size;

    os->granule = gp;

    os->flags   = flags;



    memset(os->buf + os->bufpos, 0, FF_INPUT_BUFFER_PADDING_SIZE);

    if (sid)

        *sid = idx;



    return 0;

}

static inline void RENAME(uyvyToUV)(uint8_t *dstU, uint8_t *dstV, uint8_t *src1, uint8_t *src2, long width)

{

#ifdef HAVE_MMX

	asm volatile(

		"movq "MANGLE(bm01010101)", %%mm4\n\t"

		"mov %0, %%"REG_a"		\n\t"

		"1:				\n\t"

		"movq (%1, %%"REG_a",4), %%mm0	\n\t"

		"movq 8(%1, %%"REG_a",4), %%mm1	\n\t"

		"pand %%mm4, %%mm0		\n\t"

		"pand %%mm4, %%mm1		\n\t"

		"packuswb %%mm1, %%mm0		\n\t"

		"movq %%mm0, %%mm1		\n\t"

		"psrlw $8, %%mm0		\n\t"

		"pand %%mm4, %%mm1		\n\t"

		"packuswb %%mm0, %%mm0		\n\t"

		"packuswb %%mm1, %%mm1		\n\t"

		"movd %%mm0, (%3, %%"REG_a")	\n\t"

		"movd %%mm1, (%2, %%"REG_a")	\n\t"

		"add $4, %%"REG_a"		\n\t"

		" js 1b				\n\t"

		: : "g" (-width), "r" (src1+width*4), "r" (dstU+width), "r" (dstV+width)

		: "%"REG_a

	);

#else

	int i;

	for(i=0; i<width; i++)

	{

		dstU[i]= src1[4*i + 0];

		dstV[i]= src1[4*i + 2];

	}

#endif

        assert(src1 == src2);

}

static void FUNC(intra_pred)(HEVCContext *s, int x0, int y0, int log2_size, int c_idx)

{

#define PU(x) \

    ((x) >> s->sps->log2_min_pu_size)

#define MVF(x, y) \

    (s->ref->tab_mvf[(x) + (y) * pic_width_in_min_pu])

#define MVF_PU(x, y) \

    MVF(PU(x0 + ((x) << hshift)), PU(y0 + ((y) << vshift)))

#define IS_INTRA(x, y) \

    MVF_PU(x, y).is_intra

#define MIN_TB_ADDR_ZS(x, y) \

    s->pps->min_tb_addr_zs[(y) * s->sps->min_tb_width + (x)]

#define EXTEND_LEFT(ptr, start, length) \

        for (i = (start); i > (start) - (length); i--) \

            ptr[i - 1] = ptr[i]

#define EXTEND_RIGHT(ptr, start, length) \

        for (i = (start); i < (start) + (length); i++) \

            ptr[i] = ptr[i - 1]

#define EXTEND_UP(ptr, start, length)   EXTEND_LEFT(ptr, start, length)

#define EXTEND_DOWN(ptr, start, length) EXTEND_RIGHT(ptr, start, length)

#define EXTEND_LEFT_CIP(ptr, start, length) \

        for (i = (start); i > (start) - (length); i--) \

            if (!IS_INTRA(i - 1, -1)) \

                ptr[i - 1] = ptr[i]

#define EXTEND_RIGHT_CIP(ptr, start, length) \

        for (i = (start); i < (start) + (length); i++) \

            if (!IS_INTRA(i, -1)) \

                ptr[i] = ptr[i - 1]

#define EXTEND_UP_CIP(ptr, start, length) \

        for (i = (start); i > (start) - (length); i--) \

            if (!IS_INTRA(-1, i - 1)) \

                ptr[i - 1] = ptr[i]

#define EXTEND_UP_CIP_0(ptr, start, length) \

        for (i = (start); i > (start) - (length); i--) \

            ptr[i - 1] = ptr[i]

#define EXTEND_DOWN_CIP(ptr, start, length) \

        for (i = (start); i < (start) + (length); i++) \

            if (!IS_INTRA(-1, i)) \

                ptr[i] = ptr[i - 1]

    HEVCLocalContext *lc = s->HEVClc;

    int i;

    int hshift = s->sps->hshift[c_idx];

    int vshift = s->sps->vshift[c_idx];

    int size = (1 << log2_size);

    int size_in_luma = size << hshift;

    int size_in_tbs = size_in_luma >> s->sps->log2_min_transform_block_size;

    int x = x0 >> hshift;

    int y = y0 >> vshift;

    int x_tb = x0 >> s->sps->log2_min_transform_block_size;

    int y_tb = y0 >> s->sps->log2_min_transform_block_size;

    int cur_tb_addr = MIN_TB_ADDR_ZS(x_tb, y_tb);



    ptrdiff_t stride = s->frame->linesize[c_idx] / sizeof(pixel);

    pixel *src = (pixel*)s->frame->data[c_idx] + x + y * stride;



    int pic_width_in_min_pu = PU(s->sps->width);



    enum IntraPredMode mode = c_idx ? lc->pu.intra_pred_mode_c :

                              lc->tu.cur_intra_pred_mode;



    pixel left_array[2 * MAX_TB_SIZE + 1];

    pixel filtered_left_array[2 * MAX_TB_SIZE + 1];

    pixel top_array[2 * MAX_TB_SIZE + 1];

    pixel filtered_top_array[2 * MAX_TB_SIZE + 1];



    pixel *left          = left_array + 1;

    pixel *top           = top_array + 1;

    pixel *filtered_left = filtered_left_array + 1;

    pixel *filtered_top  = filtered_top_array + 1;



    int cand_bottom_left = lc->na.cand_bottom_left && cur_tb_addr > MIN_TB_ADDR_ZS(x_tb - 1, y_tb + size_in_tbs);

    int cand_left        = lc->na.cand_left;

    int cand_up_left     = lc->na.cand_up_left;

    int cand_up          = lc->na.cand_up;

    int cand_up_right    = lc->na.cand_up_right && cur_tb_addr > MIN_TB_ADDR_ZS(x_tb + size_in_tbs, y_tb - 1);



    int bottom_left_size = (FFMIN(y0 + 2 * size_in_luma, s->sps->height) -

                            (y0 + size_in_luma)) >> vshift;

    int top_right_size   = (FFMIN(x0 + 2 * size_in_luma, s->sps->width) -

                            (x0 + size_in_luma)) >> hshift;



    if (s->pps->constrained_intra_pred_flag == 1) {

        int size_in_luma_pu = PU(size_in_luma);

        int on_pu_edge_x = !(x0 & ((1 << s->sps->log2_min_pu_size) - 1));

        int on_pu_edge_y = !(y0 & ((1 << s->sps->log2_min_pu_size) - 1));

        if(!size_in_luma_pu)

            size_in_luma_pu++;

        if (cand_bottom_left == 1 && on_pu_edge_x) {

            int x_left_pu   = PU(x0 - 1);

            int y_bottom_pu = PU(y0 + size_in_luma);

            cand_bottom_left = 0;

            for(i = 0; i < size_in_luma_pu; i++)

                cand_bottom_left |= MVF(x_left_pu, y_bottom_pu + i).is_intra;

        }

        if (cand_left == 1 && on_pu_edge_x) {

            int x_left_pu   = PU(x0 - 1);

            int y_left_pu   = PU(y0);

            cand_left = 0;

            for(i = 0; i < size_in_luma_pu; i++)

                cand_left |= MVF(x_left_pu, y_left_pu + i).is_intra;

        }

        if (cand_up_left == 1) {

            int x_left_pu   = PU(x0 - 1);

            int y_top_pu    = PU(y0 - 1);

            cand_up_left = MVF(x_left_pu, y_top_pu).is_intra;

        }

        if (cand_up == 1 && on_pu_edge_y) {

            int x_top_pu    = PU(x0);

            int y_top_pu    = PU(y0 - 1);

            cand_up = 0;

            for(i = 0; i < size_in_luma_pu; i++)

                cand_up |= MVF(x_top_pu + i, y_top_pu).is_intra;

        }

        if (cand_up_right == 1 && on_pu_edge_y) {

            int y_top_pu    = PU(y0 - 1);

            int x_right_pu  = PU(x0 + size_in_luma);

            cand_up_right = 0;

            for(i = 0; i < size_in_luma_pu; i++)

                cand_up_right |= MVF(x_right_pu + i, y_top_pu).is_intra;

        }

        for (i = 0; i < 2 * MAX_TB_SIZE; i++) {

            left[i] = 128;

            top[i]  = 128;

        }

    }

    if (cand_bottom_left) {

        for (i = size + bottom_left_size; i < (size << 1); i++)

            if (IS_INTRA(-1, size + bottom_left_size - 1) || !s->pps->constrained_intra_pred_flag)

                left[i] = POS(-1, size + bottom_left_size - 1);

        for (i = size + bottom_left_size - 1; i >= size; i--)

            if (IS_INTRA(-1, i) || !s->pps->constrained_intra_pred_flag)

                left[i] = POS(-1, i);

    }

    if (cand_left)

        for (i = size - 1; i >= 0; i--)

            if (IS_INTRA(-1, i) || !s->pps->constrained_intra_pred_flag)

                left[i] = POS(-1, i);

    if (cand_up_left)

        if (IS_INTRA(-1, -1) || !s->pps->constrained_intra_pred_flag) {

            left[-1] = POS(-1, -1);

            top[-1]  = left[-1];

        }

    if (cand_up)

        for (i = size - 1; i >= 0; i--)

            if (IS_INTRA(i, -1) || !s->pps->constrained_intra_pred_flag)

                top[i] = POS(i, -1);

    if (cand_up_right) {

        for (i = size + top_right_size; i < (size << 1); i++)

            if (IS_INTRA(size + top_right_size - 1, -1) || !s->pps->constrained_intra_pred_flag)

                top[i] = POS(size + top_right_size - 1, -1);

        for (i = size + top_right_size - 1; i >= size; i--)

            if (IS_INTRA(i, -1) || !s->pps->constrained_intra_pred_flag)

                top[i] = POS(i, -1);

    }



    if (s->pps->constrained_intra_pred_flag == 1) {

        if (cand_bottom_left || cand_left || cand_up_left || cand_up || cand_up_right) {

            int size_max_x = x0 + ((2 * size) << hshift) < s->sps->width ?

                                    2 * size : (s->sps->width - x0) >> hshift;

            int size_max_y = y0 + ((2 * size) << vshift) < s->sps->height ?

                                    2 * size : (s->sps->height - y0) >> vshift;

            int j = size + (cand_bottom_left? bottom_left_size: 0) -1;

            if (!cand_up_right) {

                size_max_x = x0 + ((size) << hshift) < s->sps->width ?

                                                    size : (s->sps->width - x0) >> hshift;

            }

            if (!cand_bottom_left) {

                size_max_y = y0 + (( size) << vshift) < s->sps->height ?

                                                     size : (s->sps->height - y0) >> vshift;

            }

            if (cand_bottom_left || cand_left || cand_up_left) {

                while (j>-1 && !IS_INTRA(-1, j)) j--;

                if (!IS_INTRA(-1, j)) {

                    j = 0;

                    while(j < size_max_x && !IS_INTRA(j, -1)) j++;

                    EXTEND_LEFT_CIP(top, j, j+1);

                    left[-1] = top[-1];

                    j = 0;

                }

            } else {

                j = 0;

                while (j < size_max_x && !IS_INTRA(j, -1)) j++;

                if (j > 0)

                    if (x0 > 0) {

                        EXTEND_LEFT_CIP(top, j, j+1);

                    } else {

                        EXTEND_LEFT_CIP(top, j, j);

                        top[-1] = top[0];

                    }

                left[-1] = top[-1];

                j = 0;

            }

            if (cand_bottom_left || cand_left) {

                EXTEND_DOWN_CIP(left, j, size_max_y-j);

            }

            if (!cand_left) {

                EXTEND_DOWN(left, 0, size);

            }

            if (!cand_bottom_left) {

                EXTEND_DOWN(left, size, size);

            }

            if (x0 != 0 && y0 != 0) {

                EXTEND_UP_CIP(left, size_max_y - 1, size_max_y);

            } else if( x0 == 0) {

                EXTEND_UP_CIP_0(left, size_max_y - 1, size_max_y);

            } else{

                EXTEND_UP_CIP(left, size_max_y - 1, size_max_y-1);

            }

            top[-1] = left[-1];

            if (y0 != 0) {

                EXTEND_RIGHT_CIP(top, 0, size_max_x);

            }

        }

    }

    // Infer the unavailable samples

    if (!cand_bottom_left) {

        if (cand_left) {

            EXTEND_DOWN(left, size, size);

        } else if (cand_up_left) {

            EXTEND_DOWN(left, 0, 2 * size);

            cand_left = 1;

        } else if (cand_up) {

            left[-1] = top[0];

            EXTEND_DOWN(left, 0, 2 * size);

            cand_up_left = 1;

            cand_left = 1;

        } else if (cand_up_right) {

            EXTEND_LEFT(top, size, size);

            left[-1] = top[0];

            EXTEND_DOWN(left ,0 , 2 * size);

            cand_up = 1;

            cand_up_left = 1;

            cand_left = 1;

        } else { // No samples available

            top[0] = left[-1] = (1 << (BIT_DEPTH - 1));

            EXTEND_RIGHT(top, 1, 2 * size - 1);

            EXTEND_DOWN(left, 0, 2 * size);

        }

    }



    if (!cand_left) {

        EXTEND_UP(left, size, size);

    }

    if (!cand_up_left) {

        left[-1] = left[0];

    }

    if (!cand_up) {

        top[0] = left[-1];

        EXTEND_RIGHT(top, 1, size-1);

    }

    if (!cand_up_right) {

        EXTEND_RIGHT(top, size, size);

    }



    top[-1] = left[-1];



#undef EXTEND_LEFT_CIP

#undef EXTEND_RIGHT_CIP

#undef EXTEND_UP_CIP

#undef EXTEND_DOWN_CIP

#undef IS_INTRA

#undef MVF_PU

#undef MVF

#undef PU

#undef EXTEND_LEFT

#undef EXTEND_RIGHT

#undef EXTEND_UP

#undef EXTEND_DOWN

#undef MIN_TB_ADDR_ZS



    // Filtering process

    if (c_idx == 0 && mode != INTRA_DC && size != 4) {

        int intra_hor_ver_dist_thresh[] = { 7, 1, 0 };

        int min_dist_vert_hor           = FFMIN(FFABS((int)mode - 26),

                                                FFABS((int)mode - 10));

        if (min_dist_vert_hor > intra_hor_ver_dist_thresh[log2_size - 3]) {

            int threshold = 1 << (BIT_DEPTH - 5);

            if (s->sps->sps_strong_intra_smoothing_enable_flag &&

                log2_size == 5 &&

                FFABS(top[-1] + top[63] - 2 * top[31]) < threshold &&

                FFABS(left[-1] + left[63] - 2 * left[31]) < threshold) {

                // We can't just overwrite values in top because it could be

                // a pointer into src

                filtered_top[-1] = top[-1];

                filtered_top[63] = top[63];

                for (i = 0; i < 63; i++)

                    filtered_top[i] = ((64 - (i + 1)) * top[-1] +

                                             (i + 1)  * top[63] + 32) >> 6;

                for (i = 0; i < 63; i++)

                    left[i] = ((64 - (i + 1)) * left[-1] +

                                     (i + 1)  * left[63] + 32) >> 6;

                top = filtered_top;

            } else {

                filtered_left[2 * size - 1] = left[2 * size - 1];

                filtered_top[2 * size - 1]  = top[2 * size - 1];

                for (i = 2 * size - 2; i >= 0; i--)

                    filtered_left[i] = (left[i + 1] + 2 * left[i] +

                                        left[i - 1] + 2) >> 2;

                filtered_top[-1] =

                filtered_left[-1] = (left[0] + 2 * left[-1] +

                                     top[0]  + 2) >> 2;

                for (i = 2 * size - 2; i >= 0; i--)

                    filtered_top[i] = (top[i + 1] + 2 * top[i] +

                                       top[i - 1] + 2) >> 2;

                left = filtered_left;

                top  = filtered_top;

            }

        }

    }



    switch (mode) {

    case INTRA_PLANAR:

        s->hpc.pred_planar[log2_size - 2]((uint8_t*)src, (uint8_t*)top,

                                          (uint8_t*)left, stride);

        break;

    case INTRA_DC:

        s->hpc.pred_dc((uint8_t*)src, (uint8_t*)top,

                       (uint8_t*)left, stride, log2_size, c_idx);

        break;

    default:

        s->hpc.pred_angular[log2_size - 2]((uint8_t*)src, (uint8_t*)top,

                                           (uint8_t*)left, stride, c_idx, mode);

        break;

    }

}

static inline void vc1_pred_b_mv(VC1Context *v, int dmv_x[2], int dmv_y[2],
                                 int direct, int mvtype)
{
    MpegEncContext *s = &v->s;
    int xy, wrap, off = 0;
    int16_t *A, *B, *C;
    int px, py;
    int sum;
    int r_x, r_y;
    const uint8_t *is_intra = v->mb_type[0];
    r_x = v->range_x;
    r_y = v->range_y;
    /* scale MV difference to be quad-pel */
    dmv_x[0] <<= 1 - s->quarter_sample;
    dmv_y[0] <<= 1 - s->quarter_sample;
    dmv_x[1] <<= 1 - s->quarter_sample;
    dmv_y[1] <<= 1 - s->quarter_sample;
    wrap = s->b8_stride;
    xy = s->block_index[0];
    if (s->mb_intra) {
        s->current_picture.motion_val[0][xy + v->blocks_off][0] =
        s->current_picture.motion_val[0][xy + v->blocks_off][1] =
        s->current_picture.motion_val[1][xy + v->blocks_off][0] =
        s->current_picture.motion_val[1][xy + v->blocks_off][1] = 0;
        return;
    }
    if (!v->field_mode) {
        s->mv[0][0][0] = scale_mv(s->next_picture.motion_val[1][xy][0], v->bfraction, 0, s->quarter_sample);
        s->mv[0][0][1] = scale_mv(s->next_picture.motion_val[1][xy][1], v->bfraction, 0, s->quarter_sample);
        s->mv[1][0][0] = scale_mv(s->next_picture.motion_val[1][xy][0], v->bfraction, 1, s->quarter_sample);
        s->mv[1][0][1] = scale_mv(s->next_picture.motion_val[1][xy][1], v->bfraction, 1, s->quarter_sample);
        /* Pullback predicted motion vectors as specified in 8.4.5.4 */
        s->mv[0][0][0] = av_clip(s->mv[0][0][0], -60 - (s->mb_x << 6), (s->mb_width  << 6) - 4 - (s->mb_x << 6));
        s->mv[0][0][1] = av_clip(s->mv[0][0][1], -60 - (s->mb_y << 6), (s->mb_height << 6) - 4 - (s->mb_y << 6));
        s->mv[1][0][0] = av_clip(s->mv[1][0][0], -60 - (s->mb_x << 6), (s->mb_width  << 6) - 4 - (s->mb_x << 6));
        s->mv[1][0][1] = av_clip(s->mv[1][0][1], -60 - (s->mb_y << 6), (s->mb_height << 6) - 4 - (s->mb_y << 6));
    }
    if (direct) {
        s->current_picture.motion_val[0][xy + v->blocks_off][0] = s->mv[0][0][0];
        s->current_picture.motion_val[0][xy + v->blocks_off][1] = s->mv[0][0][1];
        s->current_picture.motion_val[1][xy + v->blocks_off][0] = s->mv[1][0][0];
        s->current_picture.motion_val[1][xy + v->blocks_off][1] = s->mv[1][0][1];
        return;
    }
    if ((mvtype == BMV_TYPE_FORWARD) || (mvtype == BMV_TYPE_INTERPOLATED)) {
        C   = s->current_picture.motion_val[0][xy - 2];
        A   = s->current_picture.motion_val[0][xy - wrap * 2];
        off = (s->mb_x == (s->mb_width - 1)) ? -2 : 2;
        B   = s->current_picture.motion_val[0][xy - wrap * 2 + off];
        if (!s->mb_x) C[0] = C[1] = 0;
        if (!s->first_slice_line) { // predictor A is not out of bounds
            if (s->mb_width == 1) {
                px = A[0];
                py = A[1];
            } else {
                px = mid_pred(A[0], B[0], C[0]);
                py = mid_pred(A[1], B[1], C[1]);
            }
        } else if (s->mb_x) { // predictor C is not out of bounds
            px = C[0];
            py = C[1];
        } else {
            px = py = 0;
        }
        /* Pullback MV as specified in 8.3.5.3.4 */
        {
            int qx, qy, X, Y;
            if (v->profile < PROFILE_ADVANCED) {
                qx = (s->mb_x << 5);
                qy = (s->mb_y << 5);
                X  = (s->mb_width  << 5) - 4;
                Y  = (s->mb_height << 5) - 4;
                if (qx + px < -28) px = -28 - qx;
                if (qy + py < -28) py = -28 - qy;
                if (qx + px > X) px = X - qx;
                if (qy + py > Y) py = Y - qy;
            } else {
                qx = (s->mb_x << 6);
                qy = (s->mb_y << 6);
                X  = (s->mb_width  << 6) - 4;
                Y  = (s->mb_height << 6) - 4;
                if (qx + px < -60) px = -60 - qx;
                if (qy + py < -60) py = -60 - qy;
                if (qx + px > X) px = X - qx;
                if (qy + py > Y) py = Y - qy;
            }
        }
        /* Calculate hybrid prediction as specified in 8.3.5.3.5 */
        if (0 && !s->first_slice_line && s->mb_x) {
            if (is_intra[xy - wrap])
                sum = FFABS(px) + FFABS(py);
            else
                sum = FFABS(px - A[0]) + FFABS(py - A[1]);
            if (sum > 32) {
                if (get_bits1(&s->gb)) {
                    px = A[0];
                    py = A[1];
                } else {
                    px = C[0];
                    py = C[1];
                }
            } else {
                if (is_intra[xy - 2])
                    sum = FFABS(px) + FFABS(py);
                else
                    sum = FFABS(px - C[0]) + FFABS(py - C[1]);
                if (sum > 32) {
                    if (get_bits1(&s->gb)) {
                        px = A[0];
                        py = A[1];
                    } else {
                        px = C[0];
                        py = C[1];
                    }
                }
            }
        }
        /* store MV using signed modulus of MV range defined in 4.11 */
        s->mv[0][0][0] = ((px + dmv_x[0] + r_x) & ((r_x << 1) - 1)) - r_x;
        s->mv[0][0][1] = ((py + dmv_y[0] + r_y) & ((r_y << 1) - 1)) - r_y;
    }
    if ((mvtype == BMV_TYPE_BACKWARD) || (mvtype == BMV_TYPE_INTERPOLATED)) {
        C   = s->current_picture.motion_val[1][xy - 2];
        A   = s->current_picture.motion_val[1][xy - wrap * 2];
        off = (s->mb_x == (s->mb_width - 1)) ? -2 : 2;
        B   = s->current_picture.motion_val[1][xy - wrap * 2 + off];
        if (!s->mb_x)
            C[0] = C[1] = 0;
        if (!s->first_slice_line) { // predictor A is not out of bounds
            if (s->mb_width == 1) {
                px = A[0];
                py = A[1];
            } else {
                px = mid_pred(A[0], B[0], C[0]);
                py = mid_pred(A[1], B[1], C[1]);
            }
        } else if (s->mb_x) { // predictor C is not out of bounds
            px = C[0];
            py = C[1];
        } else {
            px = py = 0;
        }
        /* Pullback MV as specified in 8.3.5.3.4 */
        {
            int qx, qy, X, Y;
            if (v->profile < PROFILE_ADVANCED) {
                qx = (s->mb_x << 5);
                qy = (s->mb_y << 5);
                X  = (s->mb_width  << 5) - 4;
                Y  = (s->mb_height << 5) - 4;
                if (qx + px < -28) px = -28 - qx;
                if (qy + py < -28) py = -28 - qy;
                if (qx + px > X) px = X - qx;
                if (qy + py > Y) py = Y - qy;
            } else {
                qx = (s->mb_x << 6);
                qy = (s->mb_y << 6);
                X  = (s->mb_width  << 6) - 4;
                Y  = (s->mb_height << 6) - 4;
                if (qx + px < -60) px = -60 - qx;
                if (qy + py < -60) py = -60 - qy;
                if (qx + px > X) px = X - qx;
                if (qy + py > Y) py = Y - qy;
            }
        }
        /* Calculate hybrid prediction as specified in 8.3.5.3.5 */
        if (0 && !s->first_slice_line && s->mb_x) {
            if (is_intra[xy - wrap])
                sum = FFABS(px) + FFABS(py);
            else
                sum = FFABS(px - A[0]) + FFABS(py - A[1]);
            if (sum > 32) {
                if (get_bits1(&s->gb)) {
                    px = A[0];
                    py = A[1];
                } else {
                    px = C[0];
                    py = C[1];
                }
            } else {
                if (is_intra[xy - 2])
                    sum = FFABS(px) + FFABS(py);
                else
                    sum = FFABS(px - C[0]) + FFABS(py - C[1]);
                if (sum > 32) {
                    if (get_bits1(&s->gb)) {
                        px = A[0];
                        py = A[1];
                    } else {
                        px = C[0];
                        py = C[1];
                    }
                }
            }
        }
        /* store MV using signed modulus of MV range defined in 4.11 */
        s->mv[1][0][0] = ((px + dmv_x[1] + r_x) & ((r_x << 1) - 1)) - r_x;
        s->mv[1][0][1] = ((py + dmv_y[1] + r_y) & ((r_y << 1) - 1)) - r_y;
    }
    s->current_picture.motion_val[0][xy][0] = s->mv[0][0][0];
    s->current_picture.motion_val[0][xy][1] = s->mv[0][0][1];
    s->current_picture.motion_val[1][xy][0] = s->mv[1][0][0];
    s->current_picture.motion_val[1][xy][1] = s->mv[1][0][1];
}

static int read_rle_sgi(const SGIInfo *sgi_info, 

        AVPicture *pict, ByteIOContext *f)

{

    uint8_t *dest_row, *rle_data = NULL;

    unsigned long *start_table, *length_table;

    int y, z, xsize, ysize, zsize, tablen; 

    long start_offset, run_length;

    int ret = 0;



    xsize = sgi_info->xsize;

    ysize = sgi_info->ysize;

    zsize = sgi_info->zsize;



    rle_data = av_malloc(xsize);



    /* skip header */ 

    url_fseek(f, SGI_HEADER_SIZE, SEEK_SET);



    /* size of rle offset and length tables */

    tablen = ysize * zsize * sizeof(long);



    start_table = (unsigned long *)av_malloc(tablen);

    length_table = (unsigned long *)av_malloc(tablen);



    if (!get_buffer(f, (uint8_t *)start_table, tablen)) {

        ret = -1;

        goto fail;

    }



    if (!get_buffer(f, (uint8_t *)length_table, tablen)) {

        ret = -1;

        goto fail;

    }



    for (z = 0; z < zsize; z++) {

        for (y = 0; y < ysize; y++) {

            dest_row = pict->data[0] + (ysize - 1 - y) * (xsize * zsize);



            start_offset = BE_32(&start_table[y + z * ysize]);

            run_length = BE_32(&length_table[y + z * ysize]);



            /* don't seek if already in the correct spot */

            if (url_ftell(f) != start_offset) {

                url_fseek(f, start_offset, SEEK_SET);

            }



            get_buffer(f, rle_data, run_length);



            expand_rle_row(dest_row, rle_data, z, zsize);

        }

    }



fail:

    av_free(start_table);

    av_free(length_table);

    av_free(rle_data);



    return ret;

}

static int pcm_decode_frame(AVCodecContext *avctx,

                            void *data, int *data_size,

                            const uint8_t *buf, int buf_size)

{

    PCMDecode *s = avctx->priv_data;

    int sample_size, c, n;

    short *samples;

    const uint8_t *src, *src2[MAX_CHANNELS];

    uint8_t *dstu8;

    int16_t *dst_int16_t;

    int32_t *dst_int32_t;

    int64_t *dst_int64_t;

    uint16_t *dst_uint16_t;

    uint32_t *dst_uint32_t;



    samples = data;

    src = buf;



    if (avctx->sample_fmt!=avctx->codec->sample_fmts[0]) {

        av_log(avctx, AV_LOG_ERROR, "invalid sample_fmt\n");

        return -1;

    }



    if(avctx->channels <= 0 || avctx->channels > MAX_CHANNELS){

        av_log(avctx, AV_LOG_ERROR, "PCM channels out of bounds\n");

        return -1;

    }



    sample_size = av_get_bits_per_sample(avctx->codec_id)/8;



    n = avctx->channels * sample_size;

    /* av_get_bits_per_sample returns 0 for CODEC_ID_PCM_DVD */

    if (CODEC_ID_PCM_DVD == avctx->codec_id)

        /* 2 samples are interleaved per block in PCM_DVD */

        n = 2 * avctx->channels * avctx->bits_per_sample/8;



    if(n && buf_size % n){

        av_log(avctx, AV_LOG_ERROR, "invalid PCM packet\n");

        return -1;

    }



    buf_size= FFMIN(buf_size, *data_size/2);

    *data_size=0;



    n = buf_size/sample_size;



    switch(avctx->codec->id) {

    case CODEC_ID_PCM_U32LE:

        DECODE(uint32_t, le32, src, samples, n, 0, 0x80000000)

        break;

    case CODEC_ID_PCM_U32BE:

        DECODE(uint32_t, be32, src, samples, n, 0, 0x80000000)

        break;

    case CODEC_ID_PCM_S24LE:

        DECODE(int32_t, le24, src, samples, n, 8, 0)

        break;

    case CODEC_ID_PCM_S24BE:

        DECODE(int32_t, be24, src, samples, n, 8, 0)

        break;

    case CODEC_ID_PCM_U24LE:

        DECODE(uint32_t, le24, src, samples, n, 8, 0x800000)

        break;

    case CODEC_ID_PCM_U24BE:

        DECODE(uint32_t, be24, src, samples, n, 8, 0x800000)

        break;

    case CODEC_ID_PCM_S24DAUD:

        for(;n>0;n--) {

          uint32_t v = bytestream_get_be24(&src);

          v >>= 4; // sync flags are here

          *samples++ = ff_reverse[(v >> 8) & 0xff] +

                       (ff_reverse[v & 0xff] << 8);

        }

        break;

    case CODEC_ID_PCM_S16LE_PLANAR:

        n /= avctx->channels;

        for(c=0;c<avctx->channels;c++)

            src2[c] = &src[c*n*2];

        for(;n>0;n--)

            for(c=0;c<avctx->channels;c++)

                *samples++ = bytestream_get_le16(&src2[c]);

        src = src2[avctx->channels-1];

        break;

    case CODEC_ID_PCM_U16LE:

        DECODE(uint16_t, le16, src, samples, n, 0, 0x8000)

        break;

    case CODEC_ID_PCM_U16BE:

        DECODE(uint16_t, be16, src, samples, n, 0, 0x8000)

        break;

    case CODEC_ID_PCM_S8:

        dstu8= (uint8_t*)samples;

        for(;n>0;n--) {

            *dstu8++ = *src++ + 128;

        }

        samples= (short*)dstu8;

        break;

#if WORDS_BIGENDIAN

    case CODEC_ID_PCM_F64LE:

        DECODE(int64_t, le64, src, samples, n, 0, 0)

        break;

    case CODEC_ID_PCM_S32LE:

    case CODEC_ID_PCM_F32LE:

        DECODE(int32_t, le32, src, samples, n, 0, 0)

        break;

    case CODEC_ID_PCM_S16LE:

        DECODE(int16_t, le16, src, samples, n, 0, 0)

        break;

    case CODEC_ID_PCM_F64BE:

    case CODEC_ID_PCM_F32BE:

    case CODEC_ID_PCM_S32BE:

    case CODEC_ID_PCM_S16BE:

#else

    case CODEC_ID_PCM_F64BE:

        DECODE(int64_t, be64, src, samples, n, 0, 0)

        break;

    case CODEC_ID_PCM_F32BE:

    case CODEC_ID_PCM_S32BE:

        DECODE(int32_t, be32, src, samples, n, 0, 0)

        break;

    case CODEC_ID_PCM_S16BE:

        DECODE(int16_t, be16, src, samples, n, 0, 0)

        break;

    case CODEC_ID_PCM_F64LE:

    case CODEC_ID_PCM_F32LE:

    case CODEC_ID_PCM_S32LE:

    case CODEC_ID_PCM_S16LE:

#endif /* WORDS_BIGENDIAN */

    case CODEC_ID_PCM_U8:

        memcpy(samples, src, n*sample_size);

        src += n*sample_size;

        samples = (short*)((uint8_t*)data + n*sample_size);

        break;

    case CODEC_ID_PCM_ZORK:

        for(;n>0;n--) {

            int x= *src++;

            if(x&128) x-= 128;

            else      x = -x;

            *samples++ = x << 8;

        }

        break;

    case CODEC_ID_PCM_ALAW:

    case CODEC_ID_PCM_MULAW:

        for(;n>0;n--) {

            *samples++ = s->table[*src++];

        }

        break;

    case CODEC_ID_PCM_DVD:

        if(avctx->bits_per_sample != 20 && avctx->bits_per_sample != 24) {

            av_log(avctx, AV_LOG_ERROR, "PCM DVD unsupported sample depth\n");

            return -1;

        } else {

            int jump = avctx->channels * (avctx->bits_per_sample-16) / 4;

            n = buf_size / (avctx->channels * 2 * avctx->bits_per_sample / 8);

            while (n--) {

                for (c=0; c < 2*avctx->channels; c++)

                    *samples++ = bytestream_get_be16(&src);

                src += jump;

            }

        }

        break;

    default:

        return -1;

    }

    *data_size = (uint8_t *)samples - (uint8_t *)data;

    return src - buf;

}

static int vp5_parse_coeff(VP56Context *s)

{

    VP56RangeCoder *c = &s->c;

    VP56Model *model = s->modelp;

    uint8_t *permute = s->idct_scantable;

    uint8_t *model1, *model2;

    int coeff, sign, coeff_idx;

    int b, i, cg, idx, ctx, ctx_last;

    int pt = 0;    /* plane type (0 for Y, 1 for U or V) */



    if (c->end >= c->buffer && c->bits >= 0) {

        av_log(s->avctx, AV_LOG_ERROR, "End of AC stream reached in vp5_parse_coeff\n");

        return AVERROR_INVALIDDATA;

    }



    for (b=0; b<6; b++) {

        int ct = 1;    /* code type */



        if (b > 3) pt = 1;



        ctx = 6*s->coeff_ctx[ff_vp56_b6to4[b]][0]

              + s->above_blocks[s->above_block_idx[b]].not_null_dc;

        model1 = model->coeff_dccv[pt];

        model2 = model->coeff_dcct[pt][ctx];



        coeff_idx = 0;

        for (;;) {

            if (vp56_rac_get_prob_branchy(c, model2[0])) {

                if (vp56_rac_get_prob_branchy(c, model2[2])) {

                    if (vp56_rac_get_prob_branchy(c, model2[3])) {

                        s->coeff_ctx[ff_vp56_b6to4[b]][coeff_idx] = 4;

                        idx = vp56_rac_get_tree(c, ff_vp56_pc_tree, model1);

                        sign = vp56_rac_get(c);

                        coeff = ff_vp56_coeff_bias[idx+5];

                        for (i=ff_vp56_coeff_bit_length[idx]; i>=0; i--)

                            coeff += vp56_rac_get_prob(c, ff_vp56_coeff_parse_table[idx][i]) << i;

                    } else {

                        if (vp56_rac_get_prob_branchy(c, model2[4])) {

                            coeff = 3 + vp56_rac_get_prob(c, model1[5]);

                            s->coeff_ctx[ff_vp56_b6to4[b]][coeff_idx] = 3;

                        } else {

                            coeff = 2;

                            s->coeff_ctx[ff_vp56_b6to4[b]][coeff_idx] = 2;

                        }

                        sign = vp56_rac_get(c);

                    }

                    ct = 2;

                } else {

                    ct = 1;

                    s->coeff_ctx[ff_vp56_b6to4[b]][coeff_idx] = 1;

                    sign = vp56_rac_get(c);

                    coeff = 1;

                }

                coeff = (coeff ^ -sign) + sign;

                if (coeff_idx)

                    coeff *= s->dequant_ac;

                s->block_coeff[b][permute[coeff_idx]] = coeff;

            } else {

                if (ct && !vp56_rac_get_prob_branchy(c, model2[1]))

                    break;

                ct = 0;

                s->coeff_ctx[ff_vp56_b6to4[b]][coeff_idx] = 0;

            }

            coeff_idx++;

            if (coeff_idx >= 64)

                break;



            cg = vp5_coeff_groups[coeff_idx];

            ctx = s->coeff_ctx[ff_vp56_b6to4[b]][coeff_idx];

            model1 = model->coeff_ract[pt][ct][cg];

            model2 = cg > 2 ? model1 : model->coeff_acct[pt][ct][cg][ctx];

        }



        ctx_last = FFMIN(s->coeff_ctx_last[ff_vp56_b6to4[b]], 24);

        s->coeff_ctx_last[ff_vp56_b6to4[b]] = coeff_idx;

        if (coeff_idx < ctx_last)

            for (i=coeff_idx; i<=ctx_last; i++)

                s->coeff_ctx[ff_vp56_b6to4[b]][i] = 5;

        s->above_blocks[s->above_block_idx[b]].not_null_dc = s->coeff_ctx[ff_vp56_b6to4[b]][0];

    }

    return 0;

}

static int init_filters(const char *filters_descr)

{

    char args[512];

    int ret;

    AVFilter *abuffersrc  = avfilter_get_by_name("abuffer");

    AVFilter *abuffersink = avfilter_get_by_name("abuffersink");

    AVFilterInOut *outputs = avfilter_inout_alloc();

    AVFilterInOut *inputs  = avfilter_inout_alloc();

    const enum AVSampleFormat sample_fmts[] = { AV_SAMPLE_FMT_S16, -1 };

    const int packing_fmts[]                = { AVFILTER_PACKED, -1 };

    const int64_t *chlayouts                = avfilter_all_channel_layouts;

    AVABufferSinkParams *abuffersink_params;

    const AVFilterLink *outlink;



    filter_graph = avfilter_graph_alloc();



    /* buffer audio source: the decoded frames from the decoder will be inserted here. */

    if (!dec_ctx->channel_layout)

        dec_ctx->channel_layout = av_get_default_channel_layout(dec_ctx->channels);

    snprintf(args, sizeof(args), "%d:%d:0x%"PRIx64":packed",

             dec_ctx->sample_rate, dec_ctx->sample_fmt, dec_ctx->channel_layout);

    ret = avfilter_graph_create_filter(&buffersrc_ctx, abuffersrc, "in",

                                       args, NULL, filter_graph);

    if (ret < 0) {

        av_log(NULL, AV_LOG_ERROR, "Cannot create audio buffer source\n");

        return ret;

    }



    /* buffer audio sink: to terminate the filter chain. */

    abuffersink_params = av_abuffersink_params_alloc();

    abuffersink_params->sample_fmts     = sample_fmts;

    abuffersink_params->channel_layouts = chlayouts;

    abuffersink_params->packing_fmts    = packing_fmts;

    ret = avfilter_graph_create_filter(&buffersink_ctx, abuffersink, "out",

                                       NULL, abuffersink_params, filter_graph);


    if (ret < 0) {

        av_log(NULL, AV_LOG_ERROR, "Cannot create audio buffer sink\n");

        return ret;

    }



    /* Endpoints for the filter graph. */

    outputs->name       = av_strdup("in");

    outputs->filter_ctx = buffersrc_ctx;

    outputs->pad_idx    = 0;

    outputs->next       = NULL;



    inputs->name       = av_strdup("out");

    inputs->filter_ctx = buffersink_ctx;

    inputs->pad_idx    = 0;

    inputs->next       = NULL;



    if ((ret = avfilter_graph_parse(filter_graph, filter_descr,

                                    &inputs, &outputs, NULL)) < 0)

        return ret;



    if ((ret = avfilter_graph_config(filter_graph, NULL)) < 0)

        return ret;



    /* Print summary of the sink buffer

     * Note: args buffer is reused to store channel layout string */

    outlink = buffersink_ctx->inputs[0];

    av_get_channel_layout_string(args, sizeof(args), -1, outlink->channel_layout);

    av_log(NULL, AV_LOG_INFO, "Output: srate:%dHz fmt:%s chlayout:%s\n",

           (int)outlink->sample_rate,

           (char *)av_x_if_null(av_get_sample_fmt_name(outlink->format), "?"),

           args);



    return 0;

}

static int smacker_decode_tree(GetBitContext *gb, HuffContext *hc, uint32_t prefix, int length)

{





    if(!get_bits1(gb)){ //Leaf

        if(hc->current >= 256){

            av_log(NULL, AV_LOG_ERROR, "Tree size exceeded!\n");



        if(length){

            hc->bits[hc->current] = prefix;

            hc->lengths[hc->current] = length;

        } else {

            hc->bits[hc->current] = 0;

            hc->lengths[hc->current] = 0;


        hc->values[hc->current] = get_bits(gb, 8);

        hc->current++;

        if(hc->maxlength < length)

            hc->maxlength = length;

        return 0;

    } else { //Node

        int r;

        length++;

        r = smacker_decode_tree(gb, hc, prefix, length);

        if(r)

            return r;

        return smacker_decode_tree(gb, hc, prefix | (1 << (length - 1)), length);

static void init_2d_vlc_rl(RLTable *rl)

{

    int i;



    init_vlc(&rl->vlc, TEX_VLC_BITS, rl->n + 2, 

             &rl->table_vlc[0][1], 4, 2,

             &rl->table_vlc[0][0], 4, 2);





    rl->rl_vlc[0]= av_malloc(rl->vlc.table_size*sizeof(RL_VLC_ELEM));

    for(i=0; i<rl->vlc.table_size; i++){

        int code= rl->vlc.table[i][0];

        int len = rl->vlc.table[i][1];

        int level, run;



        if(len==0){ // illegal code

            run= 65;

            level= MAX_LEVEL;

        }else if(len<0){ //more bits needed

            run= 0;

            level= code;

        }else{

            if(code==rl->n){ //esc

                run= 65;

                level= 0;

            }else if(code==rl->n+1){ //eob

                run= 0;

                level= 127;

            }else{

                run=   rl->table_run  [code] + 1;

                level= rl->table_level[code];

            }

        }

        rl->rl_vlc[0][i].len= len;

        rl->rl_vlc[0][i].level= level;

        rl->rl_vlc[0][i].run= run;

    }

}

static int mlp_parse(AVCodecParserContext *s,

                     AVCodecContext *avctx,

                     const uint8_t **poutbuf, int *poutbuf_size,

                     const uint8_t *buf, int buf_size)

{

    MLPParseContext *mp = s->priv_data;

    int sync_present;

    uint8_t parity_bits;

    int next;

    int i, p = 0;



    *poutbuf_size = 0;

    if (buf_size == 0)

        return 0;



    if (!mp->in_sync) {

        // Not in sync - find a major sync header



        for (i = 0; i < buf_size; i++) {

            mp->pc.state = (mp->pc.state << 8) | buf[i];

            if ((mp->pc.state & 0xfffffffe) == 0xf8726fba &&

                // ignore if we do not have the data for the start of header

                mp->pc.index + i >= 7) {

                mp->in_sync = 1;

                mp->bytes_left = 0;

                break;

            }

        }



        if (!mp->in_sync) {

            if (ff_combine_frame(&mp->pc, END_NOT_FOUND, &buf, &buf_size) != -1)

                av_log(avctx, AV_LOG_WARNING, "ff_combine_frame failed\n");

            return buf_size;

        }



        ff_combine_frame(&mp->pc, i - 7, &buf, &buf_size);



        return i - 7;

    }



    if (mp->bytes_left == 0) {

        // Find length of this packet



        /* Copy overread bytes from last frame into buffer. */

        for(; mp->pc.overread>0; mp->pc.overread--) {

            mp->pc.buffer[mp->pc.index++]= mp->pc.buffer[mp->pc.overread_index++];

        }



        if (mp->pc.index + buf_size < 2) {

            if (ff_combine_frame(&mp->pc, END_NOT_FOUND, &buf, &buf_size) != -1)

                av_log(avctx, AV_LOG_WARNING, "ff_combine_frame failed\n");

            return buf_size;

        }



        mp->bytes_left = ((mp->pc.index > 0 ? mp->pc.buffer[0] : buf[0]) << 8)

                       |  (mp->pc.index > 1 ? mp->pc.buffer[1] : buf[1-mp->pc.index]);

        mp->bytes_left = (mp->bytes_left & 0xfff) * 2;

        if (mp->bytes_left <= 0) { // prevent infinite loop

            goto lost_sync;

        }

        mp->bytes_left -= mp->pc.index;

    }



    next = (mp->bytes_left > buf_size) ? END_NOT_FOUND : mp->bytes_left;



    if (ff_combine_frame(&mp->pc, next, &buf, &buf_size) < 0) {

        mp->bytes_left -= buf_size;

        return buf_size;

    }



    mp->bytes_left = 0;



    sync_present = (AV_RB32(buf + 4) & 0xfffffffe) == 0xf8726fba;



    if (!sync_present) {

        /* The first nibble of a frame is a parity check of the 4-byte

         * access unit header and all the 2- or 4-byte substream headers. */

        // Only check when this isn't a sync frame - syncs have a checksum.



        parity_bits = 0;

        for (i = -1; i < mp->num_substreams; i++) {

            parity_bits ^= buf[p++];

            parity_bits ^= buf[p++];



            if (i < 0 || buf[p-2] & 0x80) {

                parity_bits ^= buf[p++];

                parity_bits ^= buf[p++];

            }

        }



        if ((((parity_bits >> 4) ^ parity_bits) & 0xF) != 0xF) {

            av_log(avctx, AV_LOG_INFO, "mlpparse: Parity check failed.\n");

            goto lost_sync;

        }

    } else {

        GetBitContext gb;

        MLPHeaderInfo mh;



        init_get_bits(&gb, buf + 4, (buf_size - 4) << 3);

        if (ff_mlp_read_major_sync(avctx, &mh, &gb) < 0)

            goto lost_sync;



        avctx->bits_per_raw_sample = mh.group1_bits;

        if (avctx->bits_per_raw_sample > 16)

            avctx->sample_fmt = AV_SAMPLE_FMT_S32;

        else

            avctx->sample_fmt = AV_SAMPLE_FMT_S16;

        avctx->sample_rate = mh.group1_samplerate;

        s->duration = mh.access_unit_size;



        if(!avctx->channels || !avctx->channel_layout) {

        if (mh.stream_type == 0xbb) {

            /* MLP stream */

#if FF_API_REQUEST_CHANNELS

FF_DISABLE_DEPRECATION_WARNINGS

            if (avctx->request_channels > 0 && avctx->request_channels <= 2 &&

                mh.num_substreams > 1) {

                avctx->channels       = 2;

                avctx->channel_layout = AV_CH_LAYOUT_STEREO;

FF_ENABLE_DEPRECATION_WARNINGS

            } else

#endif

            if (avctx->request_channel_layout &&

                (avctx->request_channel_layout & AV_CH_LAYOUT_STEREO) ==

                avctx->request_channel_layout &&

                mh.num_substreams > 1) {

                avctx->channels       = 2;

                avctx->channel_layout = AV_CH_LAYOUT_STEREO;

            } else {

                avctx->channels       = mh.channels_mlp;

                avctx->channel_layout = mh.channel_layout_mlp;

            }

        } else { /* mh.stream_type == 0xba */

            /* TrueHD stream */

#if FF_API_REQUEST_CHANNELS

FF_DISABLE_DEPRECATION_WARNINGS

            if (avctx->request_channels > 0 && avctx->request_channels <= 2 &&

                mh.num_substreams > 1) {

                avctx->channels       = 2;

                avctx->channel_layout = AV_CH_LAYOUT_STEREO;

            } else if (avctx->request_channels > 0 &&

                       avctx->request_channels <= mh.channels_thd_stream1) {

                avctx->channels       = mh.channels_thd_stream1;

                avctx->channel_layout = mh.channel_layout_thd_stream1;

FF_ENABLE_DEPRECATION_WARNINGS

            } else

#endif

                if (avctx->request_channel_layout &&

                    (avctx->request_channel_layout & AV_CH_LAYOUT_STEREO) ==

                    avctx->request_channel_layout &&

                    mh.num_substreams > 1) {

                avctx->channels       = 2;

                avctx->channel_layout = AV_CH_LAYOUT_STEREO;

            } else if (!mh.channels_thd_stream2 ||

                       (avctx->request_channel_layout &&

                        (avctx->request_channel_layout & mh.channel_layout_thd_stream1) ==

                        avctx->request_channel_layout)) {

                avctx->channels       = mh.channels_thd_stream1;

                avctx->channel_layout = mh.channel_layout_thd_stream1;

            } else {

                avctx->channels       = mh.channels_thd_stream2;

                avctx->channel_layout = mh.channel_layout_thd_stream2;

            }

        }

        }



        if (!mh.is_vbr) /* Stream is CBR */

            avctx->bit_rate = mh.peak_bitrate;



        mp->num_substreams = mh.num_substreams;

    }



    *poutbuf = buf;

    *poutbuf_size = buf_size;



    return next;



lost_sync:

    mp->in_sync = 0;

    return 1;

}

static void draw_rectangle(unsigned val, uint8_t *dst, int dst_linesize, unsigned segment_width,

                           unsigned x, unsigned y, unsigned w, unsigned h)

{

    int i;

    int step = 3;



    dst += segment_width * (step * x + y * dst_linesize);

    w *= segment_width * step;

    h *= segment_width;

    for (i = 0; i < h; i++) {

        memset(dst, val, w);

        dst += dst_linesize;

    }

}

