}

static int flv_write_trailer(AVFormatContext *s)

{

    int64_t file_size;



    AVIOContext *pb = s->pb;

    FLVContext *flv = s->priv_data;

    int i;



    /* Add EOS tag */

    for (i = 0; i < s->nb_streams; i++) {

        AVCodecContext *enc = s->streams[i]->codec;

        if (enc->codec_type == AVMEDIA_TYPE_VIDEO &&

                enc->codec_id == CODEC_ID_H264) {

            put_avc_eos_tag(pb, flv->last_video_ts);

        }

    }



    file_size = avio_tell(pb);



    /* update informations */

    avio_seek(pb, flv->duration_offset, SEEK_SET);

    put_amf_double(pb, flv->duration / (double)1000);

    avio_seek(pb, flv->filesize_offset, SEEK_SET);

    put_amf_double(pb, file_size);



    avio_seek(pb, file_size, SEEK_SET);

    return 0;

}

static av_always_inline void mc_chroma_unscaled(VP9Context *s, vp9_mc_func (*mc)[2],

                                                uint8_t *dst_u, uint8_t *dst_v,

                                                ptrdiff_t dst_stride,

                                                const uint8_t *ref_u, ptrdiff_t src_stride_u,

                                                const uint8_t *ref_v, ptrdiff_t src_stride_v,

                                                ThreadFrame *ref_frame,

                                                ptrdiff_t y, ptrdiff_t x, const VP56mv *mv,

                                                int bw, int bh, int w, int h, int bytesperpixel)

{

    int mx = mv->x * (1 << !s->ss_h), my = mv->y * (1 << !s->ss_v), th;



    y += my >> 4;

    x += mx >> 4;

    ref_u += y * src_stride_u + x * bytesperpixel;

    ref_v += y * src_stride_v + x * bytesperpixel;

    mx &= 15;

    my &= 15;

    // FIXME bilinear filter only needs 0/1 pixels, not 3/4

    // we use +7 because the last 7 pixels of each sbrow can be changed in

    // the longest loopfilter of the next sbrow

    th = (y + bh + 4 * !!my + 7) >> (6 - s->ss_v);

    ff_thread_await_progress(ref_frame, FFMAX(th, 0), 0);

    if (x < !!mx * 3 || y < !!my * 3 ||

        x + !!mx * 4 > w - bw || y + !!my * 4 > h - bh) {

        s->vdsp.emulated_edge_mc(s->edge_emu_buffer,

                                 ref_u - !!my * 3 * src_stride_u - !!mx * 3 * bytesperpixel,

                                 160, src_stride_u,

                                 bw + !!mx * 7, bh + !!my * 7,

                                 x - !!mx * 3, y - !!my * 3, w, h);

        ref_u = s->edge_emu_buffer + !!my * 3 * 160 + !!mx * 3 * bytesperpixel;

        mc[!!mx][!!my](dst_u, dst_stride, ref_u, 160, bh, mx, my);



        s->vdsp.emulated_edge_mc(s->edge_emu_buffer,

                                 ref_v - !!my * 3 * src_stride_v - !!mx * 3 * bytesperpixel,

                                 160, src_stride_v,

                                 bw + !!mx * 7, bh + !!my * 7,

                                 x - !!mx * 3, y - !!my * 3, w, h);

        ref_v = s->edge_emu_buffer + !!my * 3 * 160 + !!mx * 3 * bytesperpixel;

        mc[!!mx][!!my](dst_v, dst_stride, ref_v, 160, bh, mx, my);

    } else {

        mc[!!mx][!!my](dst_u, dst_stride, ref_u, src_stride_u, bh, mx, my);

        mc[!!mx][!!my](dst_v, dst_stride, ref_v, src_stride_v, bh, mx, my);

    }

}

static int dv_read_header(AVFormatContext *s,

                          AVFormatParameters *ap)

{

    unsigned state;

    RawDVContext *c = s->priv_data;



    c->dv_demux = dv_init_demux(s);

    if (!c->dv_demux)

        return -1;



    state = get_be32(s->pb);

    while ((state & 0xffffff7f) != 0x1f07003f) {

        if (url_feof(s->pb)) {

            av_log(s, AV_LOG_ERROR, "Cannot find DV header.\n");

            return -1;

        }

        state = (state << 8) | get_byte(s->pb);

    }

    AV_WB32(c->buf, state);



    if (get_buffer(s->pb, c->buf + 4, DV_PROFILE_BYTES - 4) <= 0 ||

        url_fseek(s->pb, -DV_PROFILE_BYTES, SEEK_CUR) < 0)

        return AVERROR(EIO);



    c->dv_demux->sys = dv_frame_profile(c->buf);

    if (!c->dv_demux->sys) {

        av_log(s, AV_LOG_ERROR, "Can't determine profile of DV input stream.\n");

        return -1;

    }



    s->bit_rate = av_rescale_q(c->dv_demux->sys->frame_size, (AVRational){8,1},

                               c->dv_demux->sys->time_base);



    return 0;

}

int ff_mjpeg_decode_frame(AVCodecContext *avctx,

                              void *data, int *data_size,

                              AVPacket *avpkt)

{

    const uint8_t *buf = avpkt->data;

    int buf_size = avpkt->size;

    MJpegDecodeContext *s = avctx->priv_data;

    const uint8_t *buf_end, *buf_ptr;

    int start_code;

    AVFrame *picture = data;



    s->got_picture = 0; // picture from previous image can not be reused

    buf_ptr = buf;

    buf_end = buf + buf_size;

    while (buf_ptr < buf_end) {

        /* find start next marker */

        start_code = find_marker(&buf_ptr, buf_end);

        {

            /* EOF */

            if (start_code < 0) {

                goto the_end;

            } else {

                av_log(avctx, AV_LOG_DEBUG, "marker=%x avail_size_in_buf=%td\n", start_code, buf_end - buf_ptr);



                if ((buf_end - buf_ptr) > s->buffer_size)

                {

                    av_free(s->buffer);

                    s->buffer_size = buf_end-buf_ptr;

                    s->buffer = av_malloc(s->buffer_size + FF_INPUT_BUFFER_PADDING_SIZE);

                    av_log(avctx, AV_LOG_DEBUG, "buffer too small, expanding to %d bytes\n",

                        s->buffer_size);




                /* unescape buffer of SOS, use special treatment for JPEG-LS */

                if (start_code == SOS && !s->ls)

                {

                    const uint8_t *src = buf_ptr;

                    uint8_t *dst = s->buffer;



                    while (src<buf_end)

                    {

                        uint8_t x = *(src++);



                        *(dst++) = x;

                        if (avctx->codec_id != CODEC_ID_THP)

                        {

                            if (x == 0xff) {

                                while (src < buf_end && x == 0xff)

                                    x = *(src++);



                                if (x >= 0xd0 && x <= 0xd7)

                                    *(dst++) = x;

                                else if (x)





                    init_get_bits(&s->gb, s->buffer, (dst - s->buffer)*8);



                    av_log(avctx, AV_LOG_DEBUG, "escaping removed %td bytes\n",

                           (buf_end - buf_ptr) - (dst - s->buffer));


                else if(start_code == SOS && s->ls){

                    const uint8_t *src = buf_ptr;

                    uint8_t *dst = s->buffer;

                    int bit_count = 0;

                    int t = 0, b = 0;

                    PutBitContext pb;



                    s->cur_scan++;



                    /* find marker */

                    while (src + t < buf_end){

                        uint8_t x = src[t++];

                        if (x == 0xff){

                            while((src + t < buf_end) && x == 0xff)

                                x = src[t++];

                            if (x & 0x80) {

                                t -= 2;





                    bit_count = t * 8;



                    init_put_bits(&pb, dst, t);



                    /* unescape bitstream */

                    while(b < t){

                        uint8_t x = src[b++];

                        put_bits(&pb, 8, x);

                        if(x == 0xFF){

                            x = src[b++];

                            put_bits(&pb, 7, x);

                            bit_count--;



                    flush_put_bits(&pb);



                    init_get_bits(&s->gb, dst, bit_count);


                else

                    init_get_bits(&s->gb, buf_ptr, (buf_end - buf_ptr)*8);



                s->start_code = start_code;

                if(s->avctx->debug & FF_DEBUG_STARTCODE){

                    av_log(avctx, AV_LOG_DEBUG, "startcode: %X\n", start_code);




                /* process markers */

                if (start_code >= 0xd0 && start_code <= 0xd7) {

                    av_log(avctx, AV_LOG_DEBUG, "restart marker: %d\n", start_code&0x0f);

                    /* APP fields */

                } else if (start_code >= APP0 && start_code <= APP15) {

                    mjpeg_decode_app(s);

                    /* Comment */

                } else if (start_code == COM){

                    mjpeg_decode_com(s);




                switch(start_code) {

                case SOI:

                    s->restart_interval = 0;



                    s->restart_count = 0;

                    /* nothing to do on SOI */


                case DQT:

                    ff_mjpeg_decode_dqt(s);


                case DHT:

                    if(ff_mjpeg_decode_dht(s) < 0){

                        av_log(avctx, AV_LOG_ERROR, "huffman table decode error\n");

                        return -1;



                case SOF0:

                    s->lossless=0;

                    s->ls=0;

                    s->progressive=0;

                    if (ff_mjpeg_decode_sof(s) < 0)

                        return -1;


                case SOF2:

                    s->lossless=0;

                    s->ls=0;

                    s->progressive=1;

                    if (ff_mjpeg_decode_sof(s) < 0)

                        return -1;


                case SOF3:

                    s->lossless=1;

                    s->ls=0;

                    s->progressive=0;

                    if (ff_mjpeg_decode_sof(s) < 0)

                        return -1;


                case SOF48:

                    s->lossless=1;

                    s->ls=1;

                    s->progressive=0;

                    if (ff_mjpeg_decode_sof(s) < 0)

                        return -1;


                case LSE:

                    if (!CONFIG_JPEGLS_DECODER || ff_jpegls_decode_lse(s) < 0)

                        return -1;


                case EOI:

                    s->cur_scan = 0;

                    if ((s->buggy_avid && !s->interlaced) || s->restart_interval)


eoi_parser:


                        av_log(avctx, AV_LOG_WARNING, "Found EOI before any SOF, ignoring\n");



                    {

                        if (s->interlaced) {

                            s->bottom_field ^= 1;

                            /* if not bottom field, do not output image yet */

                            if (s->bottom_field == !s->interlace_polarity)

                                goto not_the_end;


                        *picture = s->picture;

                        *data_size = sizeof(AVFrame);



                        if(!s->lossless){

                            picture->quality= FFMAX3(s->qscale[0], s->qscale[1], s->qscale[2]);

                            picture->qstride= 0;

                            picture->qscale_table= s->qscale_table;

                            memset(picture->qscale_table, picture->quality, (s->width+15)/16);

                            if(avctx->debug & FF_DEBUG_QP)

                                av_log(avctx, AV_LOG_DEBUG, "QP: %d\n", picture->quality);

                            picture->quality*= FF_QP2LAMBDA;




                        goto the_end;



                case SOS:





                    ff_mjpeg_decode_sos(s);

                    /* buggy avid puts EOI every 10-20th frame */

                    /* if restart period is over process EOI */

                    if ((s->buggy_avid && !s->interlaced) || s->restart_interval)

                        goto eoi_parser;


                case DRI:

                    mjpeg_decode_dri(s);


                case SOF1:

                case SOF5:

                case SOF6:

                case SOF7:

                case SOF9:

                case SOF10:

                case SOF11:

                case SOF13:

                case SOF14:

                case SOF15:

                case JPG:

                    av_log(avctx, AV_LOG_ERROR, "mjpeg: unsupported coding type (%x)\n", start_code);


//                default:

//                    printf("mjpeg: unsupported marker (%x)\n", start_code);

//                    break;




not_the_end:

                /* eof process start code */

                buf_ptr += (get_bits_count(&s->gb)+7)/8;

                av_log(avctx, AV_LOG_DEBUG, "marker parser used %d bytes (%d bits)\n",

                       (get_bits_count(&s->gb)+7)/8, get_bits_count(&s->gb));




the_end:

    av_log(avctx, AV_LOG_DEBUG, "mjpeg decode frame unused %td bytes\n", buf_end - buf_ptr);

//    return buf_end - buf_ptr;

    return buf_ptr - buf;

void av_read_image_line(uint16_t *dst, const uint8_t *data[4], const int linesize[4],

                        const AVPixFmtDescriptor *desc, int x, int y, int c, int w, int read_pal_component)

{

    AVComponentDescriptor comp= desc->comp[c];

    int plane= comp.plane;

    int depth= comp.depth_minus1+1;

    int mask = (1<<depth)-1;

    int shift= comp.shift;

    int step = comp.step_minus1+1;

    int flags= desc->flags;



    if (flags & PIX_FMT_BITSTREAM){

        int skip = x*step + comp.offset_plus1-1;

        const uint8_t *p = data[plane] + y*linesize[plane] + (skip>>3);

        int shift = 8 - depth - (skip&7);



        while(w--){

            int val = (*p >> shift) & mask;

            if(read_pal_component)

                val= data[1][4*val + c];

            shift -= step;

            p -= shift>>3;

            shift &= 7;

            *dst++= val;

        }

    } else {

        const uint8_t *p = data[plane]+ y*linesize[plane] + x*step + comp.offset_plus1-1;



        while(w--){

            int val = flags & PIX_FMT_BE ? AV_RB16(p) : AV_RL16(p);

            val = (val>>shift) & mask;

            if(read_pal_component)

                val= data[1][4*val + c];

            p+= step;

            *dst++= val;

        }

    }

}

int attribute_align_arg av_buffersink_get_frame_flags(AVFilterContext *ctx, AVFrame *frame, int flags)

{

    BufferSinkContext *buf = ctx->priv;

    AVFilterLink *inlink = ctx->inputs[0];

    int ret;

    AVFrame *cur_frame;



    /* no picref available, fetch it from the filterchain */

    if (!av_fifo_size(buf->fifo)) {

        if (inlink->closed)

            return AVERROR_EOF;

        if (flags & AV_BUFFERSINK_FLAG_NO_REQUEST)

            return AVERROR(EAGAIN);

        if ((ret = ff_request_frame(inlink)) < 0)

            return ret;

    }



    if (!av_fifo_size(buf->fifo))

        return AVERROR(EINVAL);



    if (flags & AV_BUFFERSINK_FLAG_PEEK) {

        cur_frame = *((AVFrame **)av_fifo_peek2(buf->fifo, 0));

        if ((ret = av_frame_ref(frame, cur_frame)) < 0)

            return ret;

    } else {

        av_fifo_generic_read(buf->fifo, &cur_frame, sizeof(cur_frame), NULL);

        av_frame_move_ref(frame, cur_frame);

        av_frame_free(&cur_frame);

    }



    return 0;

}

static float wv_get_value_float(WavpackFrameContext *s, uint32_t *crc, int S)

{

    union {

        float    f;

        uint32_t u;

    } value;



    int sign;

    int exp = s->float_max_exp;



    if (s->got_extra_bits) {

        const int max_bits  = 1 + 23 + 8 + 1;

        const int left_bits = get_bits_left(&s->gb_extra_bits);



        if (left_bits + 8 * FF_INPUT_BUFFER_PADDING_SIZE < max_bits)

            return 0.0;

    }



    if (S) {

        S <<= s->float_shift;

        sign = S < 0;

        if (sign)

            S = -S;

        if (S >= 0x1000000) {

            if (s->got_extra_bits && get_bits1(&s->gb_extra_bits))

                S = get_bits(&s->gb_extra_bits, 23);

            else

                S = 0;

            exp = 255;

        } else if (exp) {

            int shift = 23 - av_log2(S);

            exp = s->float_max_exp;

            if (exp <= shift)

                shift = --exp;

            exp -= shift;



            if (shift) {

                S <<= shift;

                if ((s->float_flag & WV_FLT_SHIFT_ONES) ||

                    (s->got_extra_bits && (s->float_flag & WV_FLT_SHIFT_SAME) &&

                     get_bits1(&s->gb_extra_bits))) {

                    S |= (1 << shift) - 1;

                } else if (s->got_extra_bits &&

                           (s->float_flag & WV_FLT_SHIFT_SENT)) {

                    S |= get_bits(&s->gb_extra_bits, shift);

                }

            }

        } else {

            exp = s->float_max_exp;

        }

        S &= 0x7fffff;

    } else {

        sign = 0;

        exp = 0;

        if (s->got_extra_bits && (s->float_flag & WV_FLT_ZERO_SENT)) {

            if (get_bits1(&s->gb_extra_bits)) {

                S = get_bits(&s->gb_extra_bits, 23);

                if (s->float_max_exp >= 25)

                    exp = get_bits(&s->gb_extra_bits, 8);

                sign = get_bits1(&s->gb_extra_bits);

            } else {

                if (s->float_flag & WV_FLT_ZERO_SIGN)

                    sign = get_bits1(&s->gb_extra_bits);

            }

        }

    }



    *crc = *crc * 27 + S * 9 + exp * 3 + sign;



    value.u = (sign << 31) | (exp << 23) | S;

    return value.f;

}

