    uint8_t *dst[4] = {0};

    uint8_t *out[4] = {0};

    int srcStride[4], dstStride[4];

    int i;

    uint64_t ssdY, ssdU, ssdV, ssdA=0;

    struct SwsContext *srcContext = NULL, *dstContext = NULL,

                      *outContext = NULL;

