    avctx->priv_data = NULL;

    return 0;

}

static int mov_open_dref(ByteIOContext **pb, char *src, MOVDref *ref)

{

    /* try absolute path */

    if (!url_fopen(pb, ref->path, URL_RDONLY))

        return 0;



    /* try relative path */

    if (ref->nlvl_to > 0 && ref->nlvl_from > 0) {

        char filename[1024];

        char *src_path;

        int i, l;



        /* find a source dir */

        src_path = strrchr(src, '/');

        if (src_path)

            src_path++;

        else

            src_path = src;



        /* find a next level down to target */

        for (i = 0, l = strlen(ref->path) - 1; l >= 0; l--)

            if (ref->path[l] == '/') {

                if (i == ref->nlvl_to - 1)

                    break;

                else

                    i++;

            }



        /* compose filename if next level down to target was found */

        if (i == ref->nlvl_to - 1) {

            memcpy(filename, src, src_path - src);

            filename[src_path - src] = 0;



            for (i = 1; i < ref->nlvl_from; i++)

                av_strlcat(filename, "../", 1024);



            av_strlcat(filename, ref->path + l + 1, 1024);



            if (!url_fopen(pb, filename, URL_RDONLY))

                return 0;

        }

    }



    return AVERROR(ENOENT);

};

int ff_get_buffer(AVCodecContext *avctx, AVFrame *frame, int flags)

{

    int ret;



    switch (avctx->codec_type) {

    case AVMEDIA_TYPE_VIDEO:

        if (!frame->width)

            frame->width               = avctx->width;

        if (!frame->height)

            frame->height              = avctx->height;

        if (frame->format < 0)

            frame->format              = avctx->pix_fmt;

        if (!frame->sample_aspect_ratio.num)

            frame->sample_aspect_ratio = avctx->sample_aspect_ratio;



        if ((ret = av_image_check_size(avctx->width, avctx->height, 0, avctx)) < 0)

            return ret;

        break;

    case AVMEDIA_TYPE_AUDIO:

        if (!frame->sample_rate)

            frame->sample_rate    = avctx->sample_rate;

        if (frame->format < 0)

            frame->format         = avctx->sample_fmt;

        if (!frame->channel_layout) {

            if (avctx->channel_layout) {

                 if (av_get_channel_layout_nb_channels(avctx->channel_layout) !=

                     avctx->channels) {

                     av_log(avctx, AV_LOG_ERROR, "Inconsistent channel "

                            "configuration.\n");

                     return AVERROR(EINVAL);

                 }



                frame->channel_layout = avctx->channel_layout;

            } else {

                if (avctx->channels > FF_SANE_NB_CHANNELS) {

                    av_log(avctx, AV_LOG_ERROR, "Too many channels: %d.\n",

                           avctx->channels);

                    return AVERROR(ENOSYS);

                }



                frame->channel_layout = av_get_default_channel_layout(avctx->channels);

                if (!frame->channel_layout)

                    frame->channel_layout = (1ULL << avctx->channels) - 1;

            }

        }

        break;

    default: return AVERROR(EINVAL);

    }



    frame->pkt_pts = avctx->pkt ? avctx->pkt->pts : AV_NOPTS_VALUE;

    frame->reordered_opaque = avctx->reordered_opaque;



#if FF_API_GET_BUFFER

    /*

     * Wrap an old get_buffer()-allocated buffer in an bunch of AVBuffers.

     * We wrap each plane in its own AVBuffer. Each of those has a reference to

     * a dummy AVBuffer as its private data, unreffing it on free.

     * When all the planes are freed, the dummy buffer's free callback calls

     * release_buffer().

     */

    if (avctx->get_buffer) {

        CompatReleaseBufPriv *priv = NULL;

        AVBufferRef *dummy_buf = NULL;

        int planes, i, ret;



        if (flags & AV_GET_BUFFER_FLAG_REF)

            frame->reference    = 1;



        ret = avctx->get_buffer(avctx, frame);

        if (ret < 0)

            return ret;



        /* return if the buffers are already set up

         * this would happen e.g. when a custom get_buffer() calls

         * avcodec_default_get_buffer

         */

        if (frame->buf[0])

            return 0;



        priv = av_mallocz(sizeof(*priv));

        if (!priv) {

            ret = AVERROR(ENOMEM);

            goto fail;

        }

        priv->avctx = *avctx;

        priv->frame = *frame;



        dummy_buf = av_buffer_create(NULL, 0, compat_free_buffer, priv, 0);

        if (!dummy_buf) {

            ret = AVERROR(ENOMEM);

            goto fail;

        }



#define WRAP_PLANE(ref_out, data, data_size)                            \

do {                                                                    \

    AVBufferRef *dummy_ref = av_buffer_ref(dummy_buf);                  \

    if (!dummy_ref) {                                                   \

        ret = AVERROR(ENOMEM);                                          \

        goto fail;                                                      \

    }                                                                   \

    ref_out = av_buffer_create(data, data_size, compat_release_buffer,  \

                               dummy_ref, 0);                           \

    if (!ref_out) {                                                     \

        av_frame_unref(frame);                                          \

        ret = AVERROR(ENOMEM);                                          \

        goto fail;                                                      \

    }                                                                   \

} while (0)



        if (avctx->codec_type == AVMEDIA_TYPE_VIDEO) {

            const AVPixFmtDescriptor *desc = av_pix_fmt_desc_get(frame->format);



            if (!desc) {

                ret = AVERROR(EINVAL);

                goto fail;

            }

            planes = (desc->flags & PIX_FMT_PLANAR) ? desc->nb_components : 1;



            for (i = 0; i < planes; i++) {

                int h_shift    = (i == 1 || i == 2) ? desc->log2_chroma_h : 0;

                int plane_size = (frame->width >> h_shift) * frame->linesize[i];



                WRAP_PLANE(frame->buf[i], frame->data[i], plane_size);

            }

        } else {

            int planar = av_sample_fmt_is_planar(frame->format);

            planes = planar ? avctx->channels : 1;



            if (planes > FF_ARRAY_ELEMS(frame->buf)) {

                frame->nb_extended_buf = planes - FF_ARRAY_ELEMS(frame->buf);

                frame->extended_buf = av_malloc(sizeof(*frame->extended_buf) *

                                                frame->nb_extended_buf);

                if (!frame->extended_buf) {

                    ret = AVERROR(ENOMEM);

                    goto fail;

                }

            }



            for (i = 0; i < FFMIN(planes, FF_ARRAY_ELEMS(frame->buf)); i++)

                WRAP_PLANE(frame->buf[i], frame->extended_data[i], frame->linesize[0]);



            for (i = 0; i < planes - FF_ARRAY_ELEMS(frame->buf); i++)

                WRAP_PLANE(frame->extended_buf[i],

                           frame->extended_data[i + FF_ARRAY_ELEMS(frame->buf)],

                           frame->linesize[0]);

        }



        av_buffer_unref(&dummy_buf);



        return 0;



fail:

        avctx->release_buffer(avctx, frame);

        av_freep(&priv);

        av_buffer_unref(&dummy_buf);

        return ret;

    }

#endif



    return avctx->get_buffer2(avctx, frame, flags);

}

static int vorbis_parse_setup_hdr_codebooks(vorbis_context *vc) {

    uint_fast16_t cb;

    uint8_t *tmp_vlc_bits;

    uint32_t *tmp_vlc_codes;

    GetBitContext *gb=&vc->gb;



    vc->codebook_count=get_bits(gb,8)+1;



    AV_DEBUG(" Codebooks: %d \n", vc->codebook_count);



    vc->codebooks=(vorbis_codebook *)av_mallocz(vc->codebook_count * sizeof(vorbis_codebook));

    tmp_vlc_bits=(uint8_t *)av_mallocz(V_MAX_VLCS * sizeof(uint8_t));

    tmp_vlc_codes=(uint32_t *)av_mallocz(V_MAX_VLCS * sizeof(uint32_t));



    for(cb=0;cb<vc->codebook_count;++cb) {

        vorbis_codebook *codebook_setup=&vc->codebooks[cb];

        uint_fast8_t ordered;

        uint_fast32_t t, used_entries=0;

        uint_fast32_t entries;



        AV_DEBUG(" %d. Codebook \n", cb);



        if (get_bits(gb, 24)!=0x564342) {

            av_log(vc->avccontext, AV_LOG_ERROR, " %"PRIdFAST16". Codebook setup data corrupt. \n", cb);

            goto error;

        }



        codebook_setup->dimensions=get_bits(gb, 16);

        if (codebook_setup->dimensions>16) {

            av_log(vc->avccontext, AV_LOG_ERROR, " %"PRIdFAST16". Codebook's dimension is too large (%d). \n", cb, codebook_setup->dimensions);

            goto error;

        }

        entries=get_bits(gb, 24);

        if (entries>V_MAX_VLCS) {

            av_log(vc->avccontext, AV_LOG_ERROR, " %"PRIdFAST16". Codebook has too many entries (%"PRIdFAST32"). \n", cb, entries);

            goto error;

        }



        ordered=get_bits1(gb);



        AV_DEBUG(" codebook_dimensions %d, codebook_entries %d \n", codebook_setup->dimensions, entries);



        if (!ordered) {

            uint_fast16_t ce;

            uint_fast8_t flag;

            uint_fast8_t sparse=get_bits1(gb);



            AV_DEBUG(" not ordered \n");



            if (sparse) {

                AV_DEBUG(" sparse \n");



                used_entries=0;

                for(ce=0;ce<entries;++ce) {

                    flag=get_bits1(gb);

                    if (flag) {

                        tmp_vlc_bits[ce]=get_bits(gb, 5)+1;

                        ++used_entries;

                    }

                    else tmp_vlc_bits[ce]=0;

                }

            } else {

                AV_DEBUG(" not sparse \n");



                used_entries=entries;

                for(ce=0;ce<entries;++ce) {

                    tmp_vlc_bits[ce]=get_bits(gb, 5)+1;

                }

            }

        } else {

            uint_fast16_t current_entry=0;

            uint_fast8_t current_length=get_bits(gb, 5)+1;



            AV_DEBUG(" ordered, current length: %d \n", current_length);  //FIXME



            used_entries=entries;

            for(;current_entry<used_entries;++current_length) {

                uint_fast16_t i, number;



                AV_DEBUG(" number bits: %d ", ilog(entries - current_entry));



                number=get_bits(gb, ilog(entries - current_entry));



                AV_DEBUG(" number: %d \n", number);



                for(i=current_entry;i<number+current_entry;++i) {

                    if (i<used_entries) tmp_vlc_bits[i]=current_length;

                }



                current_entry+=number;

            }

            if (current_entry>used_entries) {

                av_log(vc->avccontext, AV_LOG_ERROR, " More codelengths than codes in codebook. \n");

                goto error;

            }

        }



        codebook_setup->lookup_type=get_bits(gb, 4);



        AV_DEBUG(" lookup type: %d : %s \n", codebook_setup->lookup_type, codebook_setup->lookup_type ? "vq" : "no lookup" );



// If the codebook is used for (inverse) VQ, calculate codevectors.



        if (codebook_setup->lookup_type==1) {

            uint_fast16_t i, j, k;

            uint_fast16_t codebook_lookup_values=ff_vorbis_nth_root(entries, codebook_setup->dimensions);

            uint_fast16_t codebook_multiplicands[codebook_lookup_values];



            float codebook_minimum_value=vorbisfloat2float(get_bits_long(gb, 32));

            float codebook_delta_value=vorbisfloat2float(get_bits_long(gb, 32));

            uint_fast8_t codebook_value_bits=get_bits(gb, 4)+1;

            uint_fast8_t codebook_sequence_p=get_bits1(gb);



            AV_DEBUG(" We expect %d numbers for building the codevectors. \n", codebook_lookup_values);

            AV_DEBUG("  delta %f minmum %f \n", codebook_delta_value, codebook_minimum_value);



            for(i=0;i<codebook_lookup_values;++i) {

                codebook_multiplicands[i]=get_bits(gb, codebook_value_bits);



                AV_DEBUG(" multiplicands*delta+minmum : %e \n", (float)codebook_multiplicands[i]*codebook_delta_value+codebook_minimum_value);

                AV_DEBUG(" multiplicand %d \n", codebook_multiplicands[i]);

            }



// Weed out unused vlcs and build codevector vector

            codebook_setup->codevectors=(float *)av_mallocz(used_entries*codebook_setup->dimensions * sizeof(float));

            for(j=0, i=0;i<entries;++i) {

                uint_fast8_t dim=codebook_setup->dimensions;



                if (tmp_vlc_bits[i]) {

                    float last=0.0;

                    uint_fast32_t lookup_offset=i;



#ifdef V_DEBUG

                    av_log(vc->avccontext, AV_LOG_INFO, "Lookup offset %d ,", i);

#endif



                    for(k=0;k<dim;++k) {

                        uint_fast32_t multiplicand_offset = lookup_offset % codebook_lookup_values;

                        codebook_setup->codevectors[j*dim+k]=codebook_multiplicands[multiplicand_offset]*codebook_delta_value+codebook_minimum_value+last;

                        if (codebook_sequence_p) {

                            last=codebook_setup->codevectors[j*dim+k];

                        }

                        lookup_offset/=codebook_lookup_values;

                    }

                    tmp_vlc_bits[j]=tmp_vlc_bits[i];



#ifdef V_DEBUG

                    av_log(vc->avccontext, AV_LOG_INFO, "real lookup offset %d, vector: ", j);

                    for(k=0;k<dim;++k) {

                        av_log(vc->avccontext, AV_LOG_INFO, " %f ", codebook_setup->codevectors[j*dim+k]);

                    }

                    av_log(vc->avccontext, AV_LOG_INFO, "\n");

#endif



                    ++j;

                }

            }

            if (j!=used_entries) {

                av_log(vc->avccontext, AV_LOG_ERROR, "Bug in codevector vector building code. \n");

                goto error;

            }

            entries=used_entries;

        }

        else if (codebook_setup->lookup_type>=2) {

            av_log(vc->avccontext, AV_LOG_ERROR, "Codebook lookup type not supported. \n");

            goto error;

        }



// Initialize VLC table

        if (ff_vorbis_len2vlc(tmp_vlc_bits, tmp_vlc_codes, entries)) {

            av_log(vc->avccontext, AV_LOG_ERROR, " Invalid code lengths while generating vlcs. \n");

            goto error;

        }

        codebook_setup->maxdepth=0;

        for(t=0;t<entries;++t)

            if (tmp_vlc_bits[t]>=codebook_setup->maxdepth) codebook_setup->maxdepth=tmp_vlc_bits[t];



        if(codebook_setup->maxdepth > 3*V_NB_BITS) codebook_setup->nb_bits=V_NB_BITS2;

        else                                       codebook_setup->nb_bits=V_NB_BITS;



        codebook_setup->maxdepth=(codebook_setup->maxdepth+codebook_setup->nb_bits-1)/codebook_setup->nb_bits;



        if (init_vlc(&codebook_setup->vlc, codebook_setup->nb_bits, entries, tmp_vlc_bits, sizeof(*tmp_vlc_bits), sizeof(*tmp_vlc_bits), tmp_vlc_codes, sizeof(*tmp_vlc_codes), sizeof(*tmp_vlc_codes), INIT_VLC_LE)) {

            av_log(vc->avccontext, AV_LOG_ERROR, " Error generating vlc tables. \n");

            goto error;

        }

    }



    av_free(tmp_vlc_bits);

    av_free(tmp_vlc_codes);

    return 0;



// Error:

error:

    av_free(tmp_vlc_bits);

    av_free(tmp_vlc_codes);

    return 1;

}

static int load_input_picture(MpegEncContext *s, const AVFrame *pic_arg)

{

    Picture *pic = NULL;

    int64_t pts;

    int i, display_picture_number = 0, ret;

    int encoding_delay = s->max_b_frames ? s->max_b_frames

                                         : (s->low_delay ? 0 : 1);

    int flush_offset = 1;

    int direct = 1;



    if (pic_arg) {

        pts = pic_arg->pts;

        display_picture_number = s->input_picture_number++;



        if (pts != AV_NOPTS_VALUE) {

            if (s->user_specified_pts != AV_NOPTS_VALUE) {

                int64_t last = s->user_specified_pts;



                if (pts <= last) {

                    av_log(s->avctx, AV_LOG_ERROR,

                           "Invalid pts (%"PRId64") <= last (%"PRId64")\n",

                           pts, last);

                    return AVERROR(EINVAL);

                }



                if (!s->low_delay && display_picture_number == 1)

                    s->dts_delta = pts - last;

            }

            s->user_specified_pts = pts;

        } else {

            if (s->user_specified_pts != AV_NOPTS_VALUE) {

                s->user_specified_pts =

                pts = s->user_specified_pts + 1;

                av_log(s->avctx, AV_LOG_INFO,

                       "Warning: AVFrame.pts=? trying to guess (%"PRId64")\n",

                       pts);

            } else {

                pts = display_picture_number;

            }

        }



        if (!pic_arg->buf[0] ||

            pic_arg->linesize[0] != s->linesize ||

            pic_arg->linesize[1] != s->uvlinesize ||

            pic_arg->linesize[2] != s->uvlinesize)

            direct = 0;

        if ((s->width & 15) || (s->height & 15))

            direct = 0;

        if (((intptr_t)(pic_arg->data[0])) & (STRIDE_ALIGN-1))

            direct = 0;

        if (s->linesize & (STRIDE_ALIGN-1))

            direct = 0;



        ff_dlog(s->avctx, "%d %d %"PTRDIFF_SPECIFIER" %"PTRDIFF_SPECIFIER"\n", pic_arg->linesize[0],

                pic_arg->linesize[1], s->linesize, s->uvlinesize);



        i = ff_find_unused_picture(s->avctx, s->picture, direct);

        if (i < 0)

            return i;



        pic = &s->picture[i];

        pic->reference = 3;



        if (direct) {

            if ((ret = av_frame_ref(pic->f, pic_arg)) < 0)

                return ret;

        }

        ret = alloc_picture(s, pic, direct);

        if (ret < 0)

            return ret;



        if (!direct) {

            if (pic->f->data[0] + INPLACE_OFFSET == pic_arg->data[0] &&

                pic->f->data[1] + INPLACE_OFFSET == pic_arg->data[1] &&

                pic->f->data[2] + INPLACE_OFFSET == pic_arg->data[2]) {

                // empty

            } else {

                int h_chroma_shift, v_chroma_shift;

                av_pix_fmt_get_chroma_sub_sample(s->avctx->pix_fmt,

                                                 &h_chroma_shift,

                                                 &v_chroma_shift);



                for (i = 0; i < 3; i++) {

                    int src_stride = pic_arg->linesize[i];

                    int dst_stride = i ? s->uvlinesize : s->linesize;

                    int h_shift = i ? h_chroma_shift : 0;

                    int v_shift = i ? v_chroma_shift : 0;

                    int w = s->width  >> h_shift;

                    int h = s->height >> v_shift;

                    uint8_t *src = pic_arg->data[i];

                    uint8_t *dst = pic->f->data[i];

                    int vpad = 16;



                    if (   s->codec_id == AV_CODEC_ID_MPEG2VIDEO

                        && !s->progressive_sequence

                        && FFALIGN(s->height, 32) - s->height > 16)

                        vpad = 32;



                    if (!s->avctx->rc_buffer_size)

                        dst += INPLACE_OFFSET;



                    if (src_stride == dst_stride)

                        memcpy(dst, src, src_stride * h);

                    else {

                        int h2 = h;

                        uint8_t *dst2 = dst;

                        while (h2--) {

                            memcpy(dst2, src, w);

                            dst2 += dst_stride;

                            src += src_stride;

                        }

                    }

                    if ((s->width & 15) || (s->height & (vpad-1))) {

                        s->mpvencdsp.draw_edges(dst, dst_stride,

                                                w, h,

                                                16 >> h_shift,

                                                vpad >> v_shift,

                                                EDGE_BOTTOM);

                    }

                }


            }

        }

        ret = av_frame_copy_props(pic->f, pic_arg);

        if (ret < 0)

            return ret;



        pic->f->display_picture_number = display_picture_number;

        pic->f->pts = pts; // we set this here to avoid modifying pic_arg

    } else {

        /* Flushing: When we have not received enough input frames,

         * ensure s->input_picture[0] contains the first picture */

        for (flush_offset = 0; flush_offset < encoding_delay + 1; flush_offset++)

            if (s->input_picture[flush_offset])

                break;



        if (flush_offset <= 1)

            flush_offset = 1;

        else

            encoding_delay = encoding_delay - flush_offset + 1;

    }



    /* shift buffer entries */

    for (i = flush_offset; i < MAX_PICTURE_COUNT /*s->encoding_delay + 1*/; i++)

        s->input_picture[i - flush_offset] = s->input_picture[i];



    s->input_picture[encoding_delay] = (Picture*) pic;



    return 0;

}

static int fourxm_read_header(AVFormatContext *s)

{

    AVIOContext *pb = s->pb;

    unsigned int fourcc_tag;

    unsigned int size;

    int header_size;

    FourxmDemuxContext *fourxm = s->priv_data;

    unsigned char *header;

    int i, ret;

    AVStream *st;



    fourxm->track_count = 0;

    fourxm->tracks = NULL;

    fourxm->fps = 1.0;



    /* skip the first 3 32-bit numbers */

    avio_skip(pb, 12);



    /* check for LIST-HEAD */

    GET_LIST_HEADER();

    header_size = size - 4;

    if (fourcc_tag != HEAD_TAG || header_size < 0)

        return AVERROR_INVALIDDATA;



    /* allocate space for the header and load the whole thing */

    header = av_malloc(header_size);

    if (!header)

        return AVERROR(ENOMEM);

    if (avio_read(pb, header, header_size) != header_size){

        av_free(header);

        return AVERROR(EIO);




    /* take the lazy approach and search for any and all vtrk and strk chunks */

    for (i = 0; i < header_size - 8; i++) {

        fourcc_tag = AV_RL32(&header[i]);

        size = AV_RL32(&header[i + 4]);

        if (size > header_size - i - 8 && (fourcc_tag == vtrk_TAG || fourcc_tag == strk_TAG)) {

            av_log(s, AV_LOG_ERROR, "chunk larger than array %d>%d\n", size, header_size - i - 8);

            return AVERROR_INVALIDDATA;




        if (fourcc_tag == std__TAG) {

            fourxm->fps = av_int2float(AV_RL32(&header[i + 12]));

        } else if (fourcc_tag == vtrk_TAG) {

            /* check that there is enough data */

            if (size != vtrk_SIZE) {

                ret= AVERROR_INVALIDDATA;



            fourxm->width  = AV_RL32(&header[i + 36]);

            fourxm->height = AV_RL32(&header[i + 40]);



            /* allocate a new AVStream */

            st = avformat_new_stream(s, NULL);

            if (!st){

                ret= AVERROR(ENOMEM);



            avpriv_set_pts_info(st, 60, 1, fourxm->fps);



            fourxm->video_stream_index = st->index;



            st->codec->codec_type = AVMEDIA_TYPE_VIDEO;

            st->codec->codec_id = CODEC_ID_4XM;

            st->codec->extradata_size = 4;

            st->codec->extradata = av_malloc(4);

            AV_WL32(st->codec->extradata, AV_RL32(&header[i + 16]));

            st->codec->width  = fourxm->width;

            st->codec->height = fourxm->height;



            i += 8 + size;

        } else if (fourcc_tag == strk_TAG) {

            int current_track;

            /* check that there is enough data */

            if (size != strk_SIZE) {

                ret= AVERROR_INVALIDDATA;



            current_track = AV_RL32(&header[i + 8]);

            if((unsigned)current_track >= UINT_MAX / sizeof(AudioTrack) - 1){

                av_log(s, AV_LOG_ERROR, "current_track too large\n");




            if (current_track + 1 > fourxm->track_count) {

                fourxm->tracks = av_realloc_f(fourxm->tracks,

                                              sizeof(AudioTrack),

                                              current_track + 1);

                if (!fourxm->tracks) {

                    ret = AVERROR(ENOMEM);



                memset(&fourxm->tracks[fourxm->track_count], 0,

                       sizeof(AudioTrack) * (current_track + 1 - fourxm->track_count));

                fourxm->track_count = current_track + 1;


            fourxm->tracks[current_track].adpcm       = AV_RL32(&header[i + 12]);

            fourxm->tracks[current_track].channels    = AV_RL32(&header[i + 36]);

            fourxm->tracks[current_track].sample_rate = AV_RL32(&header[i + 40]);

            fourxm->tracks[current_track].bits        = AV_RL32(&header[i + 44]);

            fourxm->tracks[current_track].audio_pts   = 0;

            if(   fourxm->tracks[current_track].channels    <= 0

               || fourxm->tracks[current_track].sample_rate <= 0

               || fourxm->tracks[current_track].bits        <  0){

                av_log(s, AV_LOG_ERROR, "audio header invalid\n");









            i += 8 + size;



            /* allocate a new AVStream */

            st = avformat_new_stream(s, NULL);

            if (!st){

                ret= AVERROR(ENOMEM);





            st->id = current_track;

            avpriv_set_pts_info(st, 60, 1, fourxm->tracks[current_track].sample_rate);



            fourxm->tracks[current_track].stream_index = st->index;



            st->codec->codec_type = AVMEDIA_TYPE_AUDIO;

            st->codec->codec_tag = 0;

            st->codec->channels              = fourxm->tracks[current_track].channels;

            st->codec->sample_rate           = fourxm->tracks[current_track].sample_rate;

            st->codec->bits_per_coded_sample = fourxm->tracks[current_track].bits;

            st->codec->bit_rate              = st->codec->channels * st->codec->sample_rate *

                st->codec->bits_per_coded_sample;

            st->codec->block_align = st->codec->channels * st->codec->bits_per_coded_sample;

            if (fourxm->tracks[current_track].adpcm){

                st->codec->codec_id = CODEC_ID_ADPCM_4XM;

            }else if (st->codec->bits_per_coded_sample == 8){

                st->codec->codec_id = CODEC_ID_PCM_U8;

            }else

                st->codec->codec_id = CODEC_ID_PCM_S16LE;





    /* skip over the LIST-MOVI chunk (which is where the stream should be */

    GET_LIST_HEADER();

    if (fourcc_tag != MOVI_TAG){

        ret= AVERROR_INVALIDDATA;





    av_free(header);

    /* initialize context members */

    fourxm->video_pts = -1;  /* first frame will push to 0 */



    return 0;

fail:

    av_freep(&fourxm->tracks);

    av_free(header);

    return ret;

static int encode_frame(AVCodecContext *avctx, AVPacket *pkt,

                        const AVFrame *pict, int *got_packet)

{

    TiffEncoderContext *s = avctx->priv_data;

    const AVFrame *const p = pict;

    int i;

    uint8_t *ptr;

    uint8_t *offset;

    uint32_t strips;

    uint32_t *strip_sizes   = NULL;

    uint32_t *strip_offsets = NULL;

    int bytes_per_row;

    uint32_t res[2]    = { 72, 1 };     // image resolution (72/1)

    uint16_t bpp_tab[] = { 8, 8, 8, 8 };

    int ret = 0;

    int is_yuv = 0;

    uint8_t *yuv_line = NULL;

    int shift_h, shift_v;

    int packet_size;

    const AVPixFmtDescriptor *pfd;



    s->avctx = avctx;



    s->width          = avctx->width;

    s->height         = avctx->height;

    s->subsampling[0] = 1;

    s->subsampling[1] = 1;



    switch (avctx->pix_fmt) {

    case AV_PIX_FMT_RGB48LE:

    case AV_PIX_FMT_GRAY16LE:

    case AV_PIX_FMT_RGBA:

    case AV_PIX_FMT_RGB24:

    case AV_PIX_FMT_GRAY8:

    case AV_PIX_FMT_PAL8:

        pfd    = av_pix_fmt_desc_get(avctx->pix_fmt);

        s->bpp = av_get_bits_per_pixel(pfd);

        if (pfd->flags & AV_PIX_FMT_FLAG_PAL)

            s->photometric_interpretation = TIFF_PHOTOMETRIC_PALETTE;

        else if (pfd->flags & AV_PIX_FMT_FLAG_RGB)

            s->photometric_interpretation = TIFF_PHOTOMETRIC_RGB;

        else

            s->photometric_interpretation = TIFF_PHOTOMETRIC_BLACK_IS_ZERO;

        s->bpp_tab_size = pfd->nb_components;

        for (i = 0; i < s->bpp_tab_size; i++)

            bpp_tab[i] = s->bpp / s->bpp_tab_size;

        break;

    case AV_PIX_FMT_MONOBLACK:

        s->bpp                        = 1;

        s->photometric_interpretation = TIFF_PHOTOMETRIC_BLACK_IS_ZERO;

        s->bpp_tab_size               = 0;

        break;

    case AV_PIX_FMT_MONOWHITE:

        s->bpp                        = 1;

        s->photometric_interpretation = TIFF_PHOTOMETRIC_WHITE_IS_ZERO;

        s->bpp_tab_size               = 0;

        break;

    case AV_PIX_FMT_YUV420P:

    case AV_PIX_FMT_YUV422P:

    case AV_PIX_FMT_YUV444P:

    case AV_PIX_FMT_YUV410P:

    case AV_PIX_FMT_YUV411P:

        av_pix_fmt_get_chroma_sub_sample(avctx->pix_fmt, &shift_h, &shift_v);

        s->photometric_interpretation = TIFF_PHOTOMETRIC_YCBCR;

        s->bpp                        = 8 + (16 >> (shift_h + shift_v));

        s->subsampling[0]             = 1 << shift_h;

        s->subsampling[1]             = 1 << shift_v;

        s->bpp_tab_size               = 3;

        is_yuv                        = 1;

        break;

    default:

        av_log(s->avctx, AV_LOG_ERROR,

               "This colors format is not supported\n");

        return -1;

    }



    if (s->compr == TIFF_DEFLATE       ||

        s->compr == TIFF_ADOBE_DEFLATE ||

        s->compr == TIFF_LZW)

        // best choice for DEFLATE

        s->rps = s->height;

    else

        // suggest size of strip

        s->rps = FFMAX(8192 / (((s->width * s->bpp) >> 3) + 1), 1);

    // round rps up

    s->rps = ((s->rps - 1) / s->subsampling[1] + 1) * s->subsampling[1];



    strips = (s->height - 1) / s->rps + 1;



    packet_size = avctx->height * ((avctx->width * s->bpp + 7) >> 3) * 2 +

