static int sls_flag_use_localtime_filename(AVFormatContext *oc, HLSContext *c, VariantStream *vs)

{

    if (c->flags & HLS_SECOND_LEVEL_SEGMENT_INDEX) {

        char * filename = av_strdup(oc->filename);  // %%d will be %d after strftime

        if (!filename)

            return AVERROR(ENOMEM);

        if (replace_int_data_in_filename(oc->filename, sizeof(oc->filename),

#if FF_API_HLS_WRAP

            filename, 'd', c->wrap ? vs->sequence % c->wrap : vs->sequence) < 1) {

#else

            filename, 'd', vs->sequence) < 1) {

#endif

            av_log(c, AV_LOG_ERROR, "Invalid second level segment filename template '%s', "

                    "you can try to remove second_level_segment_index flag\n",

                   filename);

            av_free(filename);

            return AVERROR(EINVAL);

        }

        av_free(filename);

    }

    if (c->flags & (HLS_SECOND_LEVEL_SEGMENT_SIZE | HLS_SECOND_LEVEL_SEGMENT_DURATION)) {

        av_strlcpy(vs->current_segment_final_filename_fmt, oc->filename,

                   sizeof(vs->current_segment_final_filename_fmt));

        if (c->flags & HLS_SECOND_LEVEL_SEGMENT_SIZE) {

            char * filename = av_strdup(oc->filename);  // %%s will be %s after strftime

            if (!filename)

                return AVERROR(ENOMEM);

            if (replace_int_data_in_filename(oc->filename, sizeof(oc->filename), filename, 's', 0) < 1) {

                av_log(c, AV_LOG_ERROR, "Invalid second level segment filename template '%s', "

                        "you can try to remove second_level_segment_size flag\n",

                       filename);

                av_free(filename);

                return AVERROR(EINVAL);

            }

            av_free(filename);

        }

        if (c->flags & HLS_SECOND_LEVEL_SEGMENT_DURATION) {

            char * filename = av_strdup(oc->filename);  // %%t will be %t after strftime

            if (!filename)

                return AVERROR(ENOMEM);

            if (replace_int_data_in_filename(oc->filename, sizeof(oc->filename), filename, 't', 0) < 1) {

                av_log(c, AV_LOG_ERROR, "Invalid second level segment filename template '%s', "

                        "you can try to remove second_level_segment_time flag\n",

                       filename);

                av_free(filename);

                return AVERROR(EINVAL);

            }

            av_free(filename);

        }

    }

    return 0;

}

static int decode_init(AVCodecContext *avctx)

{

    HYuvContext *s = avctx->priv_data;

    int width, height;



    s->avctx= avctx;

    s->flags= avctx->flags;



    dsputil_init(&s->dsp, avctx);

    memset(s->vlc, 0, 3*sizeof(VLC));



    width= s->width= avctx->width;

    height= s->height= avctx->height;

    avctx->coded_frame= &s->picture;



s->bgr32=1;

    assert(width && height);

//if(avctx->extradata)

//  printf("extradata:%X, extradata_size:%d\n", *(uint32_t*)avctx->extradata, avctx->extradata_size);

    if(avctx->extradata_size){

        if((avctx->bits_per_sample&7) && avctx->bits_per_sample != 12)

            s->version=1; // do such files exist at all?

        else

            s->version=2;

    }else

        s->version=0;



    if(s->version==2){

        int method;



        method= ((uint8_t*)avctx->extradata)[0];

        s->decorrelate= method&64 ? 1 : 0;

        s->predictor= method&63;

        s->bitstream_bpp= ((uint8_t*)avctx->extradata)[1];

        if(s->bitstream_bpp==0) 

            s->bitstream_bpp= avctx->bits_per_sample&~7;

        s->context= ((uint8_t*)avctx->extradata)[2] & 0x40 ? 1 : 0;



        if(read_huffman_tables(s, ((uint8_t*)avctx->extradata)+4, avctx->extradata_size) < 0)

            return -1;

    }else{

        switch(avctx->bits_per_sample&7){

        case 1:

            s->predictor= LEFT;

            s->decorrelate= 0;

            break;

        case 2:

            s->predictor= LEFT;

            s->decorrelate= 1;

            break;

        case 3:

            s->predictor= PLANE;

            s->decorrelate= avctx->bits_per_sample >= 24;

            break;

        case 4:

            s->predictor= MEDIAN;

            s->decorrelate= 0;

            break;

        default:

            s->predictor= LEFT; //OLD

            s->decorrelate= 0;

            break;

        }

        s->bitstream_bpp= avctx->bits_per_sample & ~7;

        s->context= 0;



        if(read_old_huffman_tables(s) < 0)

            return -1;

    }



    if(((uint8_t*)avctx->extradata)[2] & 0x20)

	s->interlaced= ((uint8_t*)avctx->extradata)[2] & 0x10 ? 1 : 0;

    else

	s->interlaced= height > 288;



    switch(s->bitstream_bpp){

    case 12:

        avctx->pix_fmt = PIX_FMT_YUV420P;

        break;

    case 16:

        if(s->yuy2){

            avctx->pix_fmt = PIX_FMT_YUV422;

        }else{

            avctx->pix_fmt = PIX_FMT_YUV422P;

        }

        break;

    case 24:

    case 32:

        if(s->bgr32){

            avctx->pix_fmt = PIX_FMT_RGBA32;

        }else{

            avctx->pix_fmt = PIX_FMT_BGR24;

        }

        break;

    default:

        assert(0);

    }



//    av_log(NULL, AV_LOG_DEBUG, "pred:%d bpp:%d hbpp:%d il:%d\n", s->predictor, s->bitstream_bpp, avctx->bits_per_sample, s->interlaced);



    return 0;

}

static void vc1_decode_b_mb(VC1Context *v)

{

    MpegEncContext *s = &v->s;

    GetBitContext *gb = &s->gb;

    int i, j;

    int mb_pos = s->mb_x + s->mb_y * s->mb_stride;

    int cbp = 0; /* cbp decoding stuff */

    int mqdiff, mquant; /* MB quantization */

    int ttmb = v->ttfrm; /* MB Transform type */

    int mb_has_coeffs = 0; /* last_flag */

    int index, index1; /* LUT indexes */

    int val, sign; /* temp values */

    int first_block = 1;

    int dst_idx, off;

    int skipped, direct;

    int dmv_x[2], dmv_y[2];

    int bmvtype = BMV_TYPE_BACKWARD;



    mquant = v->pq; /* Loosy initialization */

    s->mb_intra = 0;



    if (v->dmb_is_raw)

        direct = get_bits1(gb);

    else

        direct = v->direct_mb_plane[mb_pos];

    if (v->skip_is_raw)

        skipped = get_bits1(gb);

    else

        skipped = v->s.mbskip_table[mb_pos];



    dmv_x[0] = dmv_x[1] = dmv_y[0] = dmv_y[1] = 0;

    for(i = 0; i < 6; i++) {

        v->mb_type[0][s->block_index[i]] = 0;

        s->dc_val[0][s->block_index[i]] = 0;

    }

    s->current_picture.qscale_table[mb_pos] = 0;



    if (!direct) {

        if (!skipped) {

            GET_MVDATA(dmv_x[0], dmv_y[0]);

            dmv_x[1] = dmv_x[0];

            dmv_y[1] = dmv_y[0];

        }

        if(skipped || !s->mb_intra) {

            bmvtype = decode012(gb);

            switch(bmvtype) {

            case 0:

                bmvtype = (v->bfraction >= (B_FRACTION_DEN/2)) ? BMV_TYPE_BACKWARD : BMV_TYPE_FORWARD;

                break;

            case 1:

                bmvtype = (v->bfraction >= (B_FRACTION_DEN/2)) ? BMV_TYPE_FORWARD : BMV_TYPE_BACKWARD;

                break;

            case 2:

                bmvtype = BMV_TYPE_INTERPOLATED;

                dmv_x[0] = dmv_y[0] = 0;

            }

        }

    }

    for(i = 0; i < 6; i++)

        v->mb_type[0][s->block_index[i]] = s->mb_intra;



    if (skipped) {

        if(direct) bmvtype = BMV_TYPE_INTERPOLATED;

        vc1_pred_b_mv(v, dmv_x, dmv_y, direct, bmvtype);

        vc1_b_mc(v, dmv_x, dmv_y, direct, bmvtype);

        return;

    }

    if (direct) {

        cbp = get_vlc2(&v->s.gb, v->cbpcy_vlc->table, VC1_CBPCY_P_VLC_BITS, 2);

        GET_MQUANT();

        s->mb_intra = 0;

        s->current_picture.qscale_table[mb_pos] = mquant;

        if(!v->ttmbf)

            ttmb = get_vlc2(gb, ff_vc1_ttmb_vlc[v->tt_index].table, VC1_TTMB_VLC_BITS, 2);

        dmv_x[0] = dmv_y[0] = dmv_x[1] = dmv_y[1] = 0;

        vc1_pred_b_mv(v, dmv_x, dmv_y, direct, bmvtype);

        vc1_b_mc(v, dmv_x, dmv_y, direct, bmvtype);

    } else {

        if(!mb_has_coeffs && !s->mb_intra) {

            /* no coded blocks - effectively skipped */

            vc1_pred_b_mv(v, dmv_x, dmv_y, direct, bmvtype);

            vc1_b_mc(v, dmv_x, dmv_y, direct, bmvtype);

            return;

        }

        if(s->mb_intra && !mb_has_coeffs) {

            GET_MQUANT();

            s->current_picture.qscale_table[mb_pos] = mquant;

            s->ac_pred = get_bits1(gb);

            cbp = 0;

            vc1_pred_b_mv(v, dmv_x, dmv_y, direct, bmvtype);

        } else {

            if(bmvtype == BMV_TYPE_INTERPOLATED) {

                GET_MVDATA(dmv_x[0], dmv_y[0]);

                if(!mb_has_coeffs) {

                    /* interpolated skipped block */

                    vc1_pred_b_mv(v, dmv_x, dmv_y, direct, bmvtype);

                    vc1_b_mc(v, dmv_x, dmv_y, direct, bmvtype);

                    return;

                }

            }

            vc1_pred_b_mv(v, dmv_x, dmv_y, direct, bmvtype);

            if(!s->mb_intra) {

                vc1_b_mc(v, dmv_x, dmv_y, direct, bmvtype);

            }

            if(s->mb_intra)

                s->ac_pred = get_bits1(gb);

            cbp = get_vlc2(&v->s.gb, v->cbpcy_vlc->table, VC1_CBPCY_P_VLC_BITS, 2);

            GET_MQUANT();

            s->current_picture.qscale_table[mb_pos] = mquant;

            if(!v->ttmbf && !s->mb_intra && mb_has_coeffs)

                ttmb = get_vlc2(gb, ff_vc1_ttmb_vlc[v->tt_index].table, VC1_TTMB_VLC_BITS, 2);

        }

    }

    dst_idx = 0;

    for (i=0; i<6; i++)

    {

        s->dc_val[0][s->block_index[i]] = 0;

        dst_idx += i >> 2;

        val = ((cbp >> (5 - i)) & 1);

        off = (i & 4) ? 0 : ((i & 1) * 8 + (i & 2) * 4 * s->linesize);

        v->mb_type[0][s->block_index[i]] = s->mb_intra;

        if(s->mb_intra) {

            /* check if prediction blocks A and C are available */

            v->a_avail = v->c_avail = 0;

            if(i == 2 || i == 3 || !s->first_slice_line)

                v->a_avail = v->mb_type[0][s->block_index[i] - s->block_wrap[i]];

            if(i == 1 || i == 3 || s->mb_x)

                v->c_avail = v->mb_type[0][s->block_index[i] - 1];



            vc1_decode_intra_block(v, s->block[i], i, val, mquant, (i&4)?v->codingset2:v->codingset);

            if((i>3) && (s->flags & CODEC_FLAG_GRAY)) continue;

            v->vc1dsp.vc1_inv_trans_8x8(s->block[i]);

            if(v->rangeredfrm) for(j = 0; j < 64; j++) s->block[i][j] <<= 1;

            s->dsp.put_signed_pixels_clamped(s->block[i], s->dest[dst_idx] + off, i & 4 ? s->uvlinesize : s->linesize);

        } else if(val) {

            vc1_decode_p_block(v, s->block[i], i, mquant, ttmb, first_block, s->dest[dst_idx] + off, (i&4)?s->uvlinesize:s->linesize, (i&4) && (s->flags & CODEC_FLAG_GRAY), 0, 0, 0);

            if(!v->ttmbf && ttmb < 8) ttmb = -1;

            first_block = 0;

        }

    }

}

static int matroska_parse_rm_audio(MatroskaDemuxContext *matroska,

                                   MatroskaTrack *track,

                                   AVStream *st,

                                   uint8_t *data, int size,

                                   uint64_t timecode,

                                   int64_t pos)

{

    int a = st->codec->block_align;

    int sps = track->audio.sub_packet_size;

    int cfs = track->audio.coded_framesize;

    int h = track->audio.sub_packet_h;

    int y = track->audio.sub_packet_cnt;

    int w = track->audio.frame_size;

    int x;



    if (!track->audio.pkt_cnt) {

        if (track->audio.sub_packet_cnt == 0)

            track->audio.buf_timecode = timecode;

        if (st->codec->codec_id == AV_CODEC_ID_RA_288) {

            if (size < cfs * h / 2) {

                av_log(matroska->ctx, AV_LOG_ERROR,

                       "Corrupt int4 RM-style audio packet size\n");

                return AVERROR_INVALIDDATA;

            }

            for (x=0; x<h/2; x++)

                memcpy(track->audio.buf+x*2*w+y*cfs,

                       data+x*cfs, cfs);

        } else if (st->codec->codec_id == AV_CODEC_ID_SIPR) {

            if (size < w) {

                av_log(matroska->ctx, AV_LOG_ERROR,

                       "Corrupt sipr RM-style audio packet size\n");

                return AVERROR_INVALIDDATA;

            }

            memcpy(track->audio.buf + y*w, data, w);

        } else {

            if (size < sps * w / sps) {

                av_log(matroska->ctx, AV_LOG_ERROR,

                       "Corrupt generic RM-style audio packet size\n");

                return AVERROR_INVALIDDATA;

            }

            for (x=0; x<w/sps; x++)

                memcpy(track->audio.buf+sps*(h*x+((h+1)/2)*(y&1)+(y>>1)), data+x*sps, sps);

        }



        if (++track->audio.sub_packet_cnt >= h) {

            if (st->codec->codec_id == AV_CODEC_ID_SIPR)

                ff_rm_reorder_sipr_data(track->audio.buf, h, w);

            track->audio.sub_packet_cnt = 0;

            track->audio.pkt_cnt = h*w / a;

        }

    }



    while (track->audio.pkt_cnt) {

        AVPacket *pkt = NULL;

        if (!(pkt = av_mallocz(sizeof(AVPacket))) || av_new_packet(pkt, a) < 0){

            av_free(pkt);

            return AVERROR(ENOMEM);

        }

        memcpy(pkt->data, track->audio.buf

               + a * (h*w / a - track->audio.pkt_cnt--), a);

        pkt->pts = track->audio.buf_timecode;

        track->audio.buf_timecode = AV_NOPTS_VALUE;

        pkt->pos = pos;

        pkt->stream_index = st->index;

        dynarray_add(&matroska->packets,&matroska->num_packets,pkt);

    }



    return 0;

}

void exit_program(int ret)

{

    int i, j;



    for (i = 0; i < nb_filtergraphs; i++) {

        avfilter_graph_free(&filtergraphs[i]->graph);

        for (j = 0; j < filtergraphs[i]->nb_inputs; j++)

            av_freep(&filtergraphs[i]->inputs[j]);

        av_freep(&filtergraphs[i]->inputs);

        for (j = 0; j < filtergraphs[i]->nb_outputs; j++)

            av_freep(&filtergraphs[i]->outputs[j]);

        av_freep(&filtergraphs[i]->outputs);

        av_freep(&filtergraphs[i]);

    }

    av_freep(&filtergraphs);



    /* close files */

    for (i = 0; i < nb_output_files; i++) {

        AVFormatContext *s = output_files[i]->ctx;

        if (!(s->oformat->flags & AVFMT_NOFILE) && s->pb)

            avio_close(s->pb);

        avformat_free_context(s);

        av_dict_free(&output_files[i]->opts);

        av_freep(&output_files[i]);

    }

    for (i = 0; i < nb_output_streams; i++) {

        AVBitStreamFilterContext *bsfc = output_streams[i]->bitstream_filters;

        while (bsfc) {

            AVBitStreamFilterContext *next = bsfc->next;

            av_bitstream_filter_close(bsfc);

            bsfc = next;

        }

        output_streams[i]->bitstream_filters = NULL;



        if (output_streams[i]->output_frame) {

            AVFrame *frame = output_streams[i]->output_frame;

            if (frame->extended_data != frame->data)

                av_freep(&frame->extended_data);

            av_freep(&frame);

        }



        av_freep(&output_streams[i]->avfilter);

        av_freep(&output_streams[i]->filtered_frame);

        av_freep(&output_streams[i]);

    }

    for (i = 0; i < nb_input_files; i++) {

        avformat_close_input(&input_files[i]->ctx);

        av_freep(&input_files[i]);

    }

    for (i = 0; i < nb_input_streams; i++) {

        av_freep(&input_streams[i]->decoded_frame);

        av_dict_free(&input_streams[i]->opts);

        free_buffer_pool(input_streams[i]);

        av_freep(&input_streams[i]->filters);

        av_freep(&input_streams[i]);

    }



    if (vstats_file)

        fclose(vstats_file);

    av_free(vstats_filename);



    av_freep(&input_streams);

    av_freep(&input_files);

    av_freep(&output_streams);

    av_freep(&output_files);



    uninit_opts();

    av_free(audio_buf);

    allocated_audio_buf_size = 0;

    av_free(async_buf);

    allocated_async_buf_size = 0;



    avfilter_uninit();

    avformat_network_deinit();



    if (received_sigterm) {

        av_log(NULL, AV_LOG_INFO, "Received signal %d: terminating.\n",

               (int) received_sigterm);

        exit (255);

    }



    exit(ret);

}

static int parse_playlist(HLSContext *c, const char *url,

                          struct playlist *pls, AVIOContext *in)

{

    int ret = 0, is_segment = 0, is_variant = 0;

    int64_t duration = 0;

    enum KeyType key_type = KEY_NONE;

    uint8_t iv[16] = "";

    int has_iv = 0;

    char key[MAX_URL_SIZE] = "";

    char line[MAX_URL_SIZE];

    const char *ptr;

    int close_in = 0;

    int64_t seg_offset = 0;

    int64_t seg_size = -1;

    uint8_t *new_url = NULL;

    struct variant_info variant_info;

    char tmp_str[MAX_URL_SIZE];

    struct segment *cur_init_section = NULL;



    if (!in && c->http_persistent && c->playlist_pb) {

        in = c->playlist_pb;

        ret = open_url_keepalive(c->ctx, &c->playlist_pb, url);

        if (ret == AVERROR_EXIT) {

            return ret;

        } else if (ret < 0) {

            av_log(c->ctx, AV_LOG_WARNING,

                "keepalive request failed for '%s', retrying with new connection: %s\n",

                url, av_err2str(ret));

            in = NULL;

        }

    }



    if (!in) {

#if 1

        AVDictionary *opts = NULL;

        /* Some HLS servers don't like being sent the range header */

        av_dict_set(&opts, "seekable", "0", 0);



        // broker prior HTTP options that should be consistent across requests

        av_dict_set(&opts, "user_agent", c->user_agent, 0);

        av_dict_set(&opts, "cookies", c->cookies, 0);

        av_dict_set(&opts, "headers", c->headers, 0);

        av_dict_set(&opts, "http_proxy", c->http_proxy, 0);



        if (c->http_persistent)

            av_dict_set(&opts, "multiple_requests", "1", 0);



        ret = c->ctx->io_open(c->ctx, &in, url, AVIO_FLAG_READ, &opts);

        av_dict_free(&opts);

        if (ret < 0)

            return ret;



        if (c->http_persistent)

            c->playlist_pb = in;

        else

            close_in = 1;

#else

        ret = open_in(c, &in, url);

        if (ret < 0)

            return ret;

        close_in = 1;

#endif

    }



    if (av_opt_get(in, "location", AV_OPT_SEARCH_CHILDREN, &new_url) >= 0)

        url = new_url;



    read_chomp_line(in, line, sizeof(line));

    if (strcmp(line, "#EXTM3U")) {

        ret = AVERROR_INVALIDDATA;

        goto fail;

    }



    if (pls) {

        free_segment_list(pls);

        pls->finished = 0;

        pls->type = PLS_TYPE_UNSPECIFIED;

    }

    while (!avio_feof(in)) {

        read_chomp_line(in, line, sizeof(line));

        if (av_strstart(line, "#EXT-X-STREAM-INF:", &ptr)) {

            is_variant = 1;

            memset(&variant_info, 0, sizeof(variant_info));

            ff_parse_key_value(ptr, (ff_parse_key_val_cb) handle_variant_args,

                               &variant_info);

        } else if (av_strstart(line, "#EXT-X-KEY:", &ptr)) {

            struct key_info info = {{0}};

            ff_parse_key_value(ptr, (ff_parse_key_val_cb) handle_key_args,

                               &info);

            key_type = KEY_NONE;

            has_iv = 0;

            if (!strcmp(info.method, "AES-128"))

                key_type = KEY_AES_128;

            if (!strcmp(info.method, "SAMPLE-AES"))

                key_type = KEY_SAMPLE_AES;

            if (!strncmp(info.iv, "0x", 2) || !strncmp(info.iv, "0X", 2)) {

                ff_hex_to_data(iv, info.iv + 2);

                has_iv = 1;

            }

            av_strlcpy(key, info.uri, sizeof(key));

        } else if (av_strstart(line, "#EXT-X-MEDIA:", &ptr)) {

            struct rendition_info info = {{0}};

            ff_parse_key_value(ptr, (ff_parse_key_val_cb) handle_rendition_args,

                               &info);

            new_rendition(c, &info, url);

        } else if (av_strstart(line, "#EXT-X-TARGETDURATION:", &ptr)) {

            ret = ensure_playlist(c, &pls, url);

            if (ret < 0)

                goto fail;

            pls->target_duration = strtoll(ptr, NULL, 10) * AV_TIME_BASE;

        } else if (av_strstart(line, "#EXT-X-MEDIA-SEQUENCE:", &ptr)) {

            ret = ensure_playlist(c, &pls, url);

            if (ret < 0)

                goto fail;

            pls->start_seq_no = atoi(ptr);

        } else if (av_strstart(line, "#EXT-X-PLAYLIST-TYPE:", &ptr)) {

            ret = ensure_playlist(c, &pls, url);

            if (ret < 0)

                goto fail;

            if (!strcmp(ptr, "EVENT"))

                pls->type = PLS_TYPE_EVENT;

            else if (!strcmp(ptr, "VOD"))

                pls->type = PLS_TYPE_VOD;

        } else if (av_strstart(line, "#EXT-X-MAP:", &ptr)) {

            struct init_section_info info = {{0}};

            ret = ensure_playlist(c, &pls, url);

            if (ret < 0)

                goto fail;

            ff_parse_key_value(ptr, (ff_parse_key_val_cb) handle_init_section_args,

                               &info);

            cur_init_section = new_init_section(pls, &info, url);

        } else if (av_strstart(line, "#EXT-X-ENDLIST", &ptr)) {

            if (pls)

                pls->finished = 1;

        } else if (av_strstart(line, "#EXTINF:", &ptr)) {

            is_segment = 1;

            duration   = atof(ptr) * AV_TIME_BASE;

        } else if (av_strstart(line, "#EXT-X-BYTERANGE:", &ptr)) {

            seg_size = strtoll(ptr, NULL, 10);

            ptr = strchr(ptr, '@');

            if (ptr)

                seg_offset = strtoll(ptr+1, NULL, 10);

        } else if (av_strstart(line, "#", NULL)) {

            continue;

        } else if (line[0]) {

            if (is_variant) {

                if (!new_variant(c, &variant_info, line, url)) {

                    ret = AVERROR(ENOMEM);

                    goto fail;

                }

                is_variant = 0;

            }

            if (is_segment) {

                struct segment *seg;

                if (!pls) {

                    if (!new_variant(c, 0, url, NULL)) {

                        ret = AVERROR(ENOMEM);

                        goto fail;

                    }

                    pls = c->playlists[c->n_playlists - 1];

                }

                seg = av_malloc(sizeof(struct segment));

                if (!seg) {

                    ret = AVERROR(ENOMEM);

                    goto fail;

                }

                seg->duration = duration;

                seg->key_type = key_type;

                if (has_iv) {

                    memcpy(seg->iv, iv, sizeof(iv));

                } else {

                    int seq = pls->start_seq_no + pls->n_segments;

                    memset(seg->iv, 0, sizeof(seg->iv));

                    AV_WB32(seg->iv + 12, seq);

                }



                if (key_type != KEY_NONE) {

                    ff_make_absolute_url(tmp_str, sizeof(tmp_str), url, key);

                    seg->key = av_strdup(tmp_str);

                    if (!seg->key) {

                        av_free(seg);

                        ret = AVERROR(ENOMEM);

                        goto fail;

                    }

                } else {

                    seg->key = NULL;

                }



                ff_make_absolute_url(tmp_str, sizeof(tmp_str), url, line);

                seg->url = av_strdup(tmp_str);

                if (!seg->url) {

                    av_free(seg->key);

                    av_free(seg);

                    ret = AVERROR(ENOMEM);

                    goto fail;

                }



                dynarray_add(&pls->segments, &pls->n_segments, seg);

                is_segment = 0;



                seg->size = seg_size;

                if (seg_size >= 0) {

                    seg->url_offset = seg_offset;

                    seg_offset += seg_size;

                    seg_size = -1;

                } else {

                    seg->url_offset = 0;

                    seg_offset = 0;

                }



                seg->init_section = cur_init_section;

            }

        }

    }

    if (pls)

        pls->last_load_time = av_gettime_relative();



fail:

    av_free(new_url);

    if (close_in)

        ff_format_io_close(c->ctx, &in);

    return ret;

}

static int decode_slice(AVCodecContext *avctx, ProresThreadData *td)

{

    ProresContext *ctx = avctx->priv_data;

    int mb_x_pos  = td->x_pos;

    int mb_y_pos  = td->y_pos;

    int pic_num   = ctx->pic_num;

    int slice_num = td->slice_num;

    int mbs_per_slice = td->slice_width;

    const uint8_t *buf;

    uint8_t *y_data, *u_data, *v_data;

    AVFrame *pic = avctx->coded_frame;

    int i, sf, slice_width_factor;

    int slice_data_size, hdr_size, y_data_size, u_data_size, v_data_size;

    int y_linesize, u_linesize, v_linesize;



    buf             = ctx->slice_data[slice_num].index;

    slice_data_size = ctx->slice_data[slice_num + 1].index - buf;



    slice_width_factor = av_log2(mbs_per_slice);



    y_data     = pic->data[0];

    u_data     = pic->data[1];

    v_data     = pic->data[2];

    y_linesize = pic->linesize[0];

    u_linesize = pic->linesize[1];

    v_linesize = pic->linesize[2];



    if (pic->interlaced_frame) {

        if (!(pic_num ^ pic->top_field_first)) {

            y_data += y_linesize;

            u_data += u_linesize;

            v_data += v_linesize;

        }

        y_linesize <<= 1;

        u_linesize <<= 1;

        v_linesize <<= 1;

    }



    if (slice_data_size < 6) {

        av_log(avctx, AV_LOG_ERROR, "slice data too small\n");

        return AVERROR_INVALIDDATA;

    }



    /* parse slice header */

    hdr_size    = buf[0] >> 3;

    y_data_size = AV_RB16(buf + 2);

    u_data_size = AV_RB16(buf + 4);

    v_data_size = slice_data_size - y_data_size - u_data_size - hdr_size;



    if (v_data_size < 0 || hdr_size < 6) {

        av_log(avctx, AV_LOG_ERROR, "invalid data size\n");

        return AVERROR_INVALIDDATA;

    }



    sf = av_clip(buf[1], 1, 224);

    sf = sf > 128 ? (sf - 96) << 2 : sf;



    /* scale quantization matrixes according with slice's scale factor */

    /* TODO: this can be SIMD-optimized alot */

    if (ctx->qmat_changed || sf != ctx->prev_slice_sf) {

        ctx->prev_slice_sf = sf;

        for (i = 0; i < 64; i++) {

            ctx->qmat_luma_scaled[ctx->dsp.idct_permutation[i]]   = ctx->qmat_luma[i]   * sf;

            ctx->qmat_chroma_scaled[ctx->dsp.idct_permutation[i]] = ctx->qmat_chroma[i] * sf;

        }

    }



    /* decode luma plane */

    decode_slice_plane(ctx, td, buf + hdr_size, y_data_size,

                       (uint16_t*) (y_data + (mb_y_pos << 4) * y_linesize +

                                    (mb_x_pos << 5)), y_linesize,

                       mbs_per_slice, 4, slice_width_factor + 2,

                       ctx->qmat_luma_scaled);



    /* decode U chroma plane */

    decode_slice_plane(ctx, td, buf + hdr_size + y_data_size, u_data_size,

                       (uint16_t*) (u_data + (mb_y_pos << 4) * u_linesize +

                                    (mb_x_pos << ctx->mb_chroma_factor)),

                       u_linesize, mbs_per_slice, ctx->num_chroma_blocks,

                       slice_width_factor + ctx->chroma_factor - 1,

                       ctx->qmat_chroma_scaled);



    /* decode V chroma plane */

    decode_slice_plane(ctx, td, buf + hdr_size + y_data_size + u_data_size,

                       v_data_size,

                       (uint16_t*) (v_data + (mb_y_pos << 4) * v_linesize +

                                    (mb_x_pos << ctx->mb_chroma_factor)),

                       v_linesize, mbs_per_slice, ctx->num_chroma_blocks,

                       slice_width_factor + ctx->chroma_factor - 1,

                       ctx->qmat_chroma_scaled);



    return 0;

}

