static int decode_frame(FLACContext *s, int alloc_data_size)

{

    int bs_code, sr_code, bps_code, i;

    int ch_mode, bps, blocksize, samplerate;

    GetBitContext *gb = &s->gb;



    /* frame sync code */

    skip_bits(&s->gb, 16);



    /* block size and sample rate codes */

    bs_code = get_bits(gb, 4);

    sr_code = get_bits(gb, 4);



    /* channels and decorrelation */

    ch_mode = get_bits(gb, 4);

    if (ch_mode < FLAC_MAX_CHANNELS && s->channels == ch_mode+1) {

        ch_mode = FLAC_CHMODE_INDEPENDENT;

    } else if (ch_mode > FLAC_CHMODE_MID_SIDE || s->channels != 2) {

        av_log(s->avctx, AV_LOG_ERROR, "unsupported channel assignment %d (channels=%d)\n",

               ch_mode, s->channels);

        return -1;

    }



    /* bits per sample */

    bps_code = get_bits(gb, 3);

    if (bps_code == 0)

        bps= s->bps;

    else if ((bps_code != 3) && (bps_code != 7))

        bps = sample_size_table[bps_code];

    else {

        av_log(s->avctx, AV_LOG_ERROR, "invalid sample size code (%d)\n",

               bps_code);

        return -1;

    }

    if (bps > 16) {

        s->avctx->sample_fmt = SAMPLE_FMT_S32;

        s->sample_shift = 32 - bps;

        s->is32 = 1;

    } else {

        s->avctx->sample_fmt = SAMPLE_FMT_S16;

        s->sample_shift = 16 - bps;

        s->is32 = 0;

    }

    s->bps = s->avctx->bits_per_raw_sample = bps;



    /* reserved bit */

    if (get_bits1(gb)) {

        av_log(s->avctx, AV_LOG_ERROR, "broken stream, invalid padding\n");

        return -1;

    }



    /* sample or frame count */

    if (get_utf8(gb) < 0) {

        av_log(s->avctx, AV_LOG_ERROR, "utf8 fscked\n");

        return -1;

    }



    /* blocksize */

    if (bs_code == 0) {

        av_log(s->avctx, AV_LOG_ERROR, "reserved blocksize code: 0\n");

        return -1;

    } else if (bs_code == 6)

        blocksize = get_bits(gb, 8)+1;

    else if (bs_code == 7)

        blocksize = get_bits(gb, 16)+1;

    else

        blocksize = ff_flac_blocksize_table[bs_code];



    if (blocksize > s->max_blocksize) {

        av_log(s->avctx, AV_LOG_ERROR, "blocksize %d > %d\n", blocksize,

               s->max_blocksize);

        return -1;

    }



    if (blocksize * s->channels * (s->is32 ? 4 : 2) > alloc_data_size)

        return -1;



    /* sample rate */

    if (sr_code == 0)

        samplerate= s->samplerate;

    else if (sr_code < 12)

        samplerate = ff_flac_sample_rate_table[sr_code];

    else if (sr_code == 12)

        samplerate = get_bits(gb, 8) * 1000;

    else if (sr_code == 13)

        samplerate = get_bits(gb, 16);

    else if (sr_code == 14)

        samplerate = get_bits(gb, 16) * 10;

    else {

        av_log(s->avctx, AV_LOG_ERROR, "illegal sample rate code %d\n",

               sr_code);

        return -1;

    }



    /* header CRC-8 check */

    skip_bits(gb, 8);

    if (av_crc(av_crc_get_table(AV_CRC_8_ATM), 0, gb->buffer,

               get_bits_count(gb)/8)) {

        av_log(s->avctx, AV_LOG_ERROR, "header crc mismatch\n");

        return -1;

    }



    s->blocksize    = blocksize;

    s->samplerate   = samplerate;

    s->bps          = bps;

    s->ch_mode      = ch_mode;



//    dump_headers(s->avctx, (FLACStreaminfo *)s);



    /* subframes */

    for (i = 0; i < s->channels; i++) {

        if (decode_subframe(s, i) < 0)

            return -1;

    }



    align_get_bits(gb);



    /* frame footer */

    skip_bits(gb, 16); /* data crc */



    return 0;

}

static int ftp_getc(FTPContext *s)

{

    int len;

    if (s->control_buf_ptr >= s->control_buf_end) {

        if (s->conn_control_block_flag)

            return AVERROR_EXIT;

        len = ffurl_read(s->conn_control, s->control_buffer, CONTROL_BUFFER_SIZE);

        if (len < 0) {

            return len;

        } else if (!len) {

            return -1;

        } else {

            s->control_buf_ptr = s->control_buffer;

            s->control_buf_end = s->control_buffer + len;

        }

    }

    return *s->control_buf_ptr++;

}

static int filter_frame(AVFilterLink *inlink, AVFrame *in)

{

    AVFilterContext *ctx = inlink->dst;

    HDCDContext *s = ctx->priv;

    AVFilterLink *outlink = ctx->outputs[0];

    AVFrame *out;

    const int16_t *in_data;

    int32_t *out_data;

    int n, c;

    int detect, packets, pe_packets;



    out = ff_get_audio_buffer(outlink, in->nb_samples);

    if (!out) {

        av_frame_free(&in);

        return AVERROR(ENOMEM);

    }

    av_frame_copy_props(out, in);

    out->format = outlink->format;



    in_data  = (int16_t*)in->data[0];

    out_data = (int32_t*)out->data[0];

    for (n = 0; n < in->nb_samples * in->channels; n++) {

        out_data[n] = in_data[n];

    }



    detect = 0;

    packets = 0;

    pe_packets = 0;

    s->det_errors = 0;

    for (c = 0; c < inlink->channels; c++) {

        hdcd_state_t *state = &s->state[c];

        hdcd_process(s, state, out_data + c, in->nb_samples, out->channels);

        if (state->sustain) detect++;

        packets += state->code_counterA + state->code_counterB;

        pe_packets += state->count_peak_extend;

        s->uses_transient_filter |= !!state->count_transient_filter;

        s->max_gain_adjustment = FFMIN(s->max_gain_adjustment, GAINTOFLOAT(state->max_gain));

        s->det_errors += state->code_counterA_almost

            + state->code_counterB_checkfails

            + state->code_counterC_unmatched;

    }

    if (pe_packets) {

        /* if every valid packet has used PE, call it permanent */

        if (packets == pe_packets)

            s->peak_extend = HDCD_PE_PERMANENT;

        else

            s->peak_extend = HDCD_PE_INTERMITTENT;

    } else {

        s->peak_extend = HDCD_PE_NEVER;

    }

    /* HDCD is detected if a valid packet is active in all (both)

     * channels at the same time. */

    if (detect == inlink->channels) s->hdcd_detected = 1;



    s->sample_count += in->nb_samples * in->channels;



    av_frame_free(&in);

    return ff_filter_frame(outlink, out);

}

av_cold void ff_sws_init_input_funcs(SwsContext *c)

{

    enum AVPixelFormat srcFormat = c->srcFormat;



    c->chrToYV12 = NULL;

    switch (srcFormat) {

    case AV_PIX_FMT_YUYV422:

        c->chrToYV12 = yuy2ToUV_c;

        break;

    case AV_PIX_FMT_YVYU422:

        c->chrToYV12 = yvy2ToUV_c;

        break;

    case AV_PIX_FMT_UYVY422:

        c->chrToYV12 = uyvyToUV_c;

        break;

    case AV_PIX_FMT_NV12:

        c->chrToYV12 = nv12ToUV_c;

        break;

    case AV_PIX_FMT_NV21:

        c->chrToYV12 = nv21ToUV_c;

        break;

    case AV_PIX_FMT_RGB8:

    case AV_PIX_FMT_BGR8:

