static void common_init(MpegEncContext * s)

{

    static int inited=0;



    switch(s->msmpeg4_version){

    case 1:

    case 2:

        s->y_dc_scale_table=

        s->c_dc_scale_table= ff_mpeg1_dc_scale_table;

        break;

    case 3:

        if(s->workaround_bugs){

            s->y_dc_scale_table= old_ff_y_dc_scale_table;

            s->c_dc_scale_table= old_ff_c_dc_scale_table;

        } else{

            s->y_dc_scale_table= ff_mpeg4_y_dc_scale_table;

            s->c_dc_scale_table= ff_mpeg4_c_dc_scale_table;

        }

        break;

    case 4:

    case 5:

        s->y_dc_scale_table= wmv1_y_dc_scale_table;

        s->c_dc_scale_table= wmv1_c_dc_scale_table;

        break;

#if defined(CONFIG_WMV3_DECODER)||defined(CONFIG_VC1_DECODER)

    case 6:

        s->y_dc_scale_table= wmv3_dc_scale_table;

        s->c_dc_scale_table= wmv3_dc_scale_table;

        break;

#endif



    }





    if(s->msmpeg4_version>=4){

        ff_init_scantable(s->dsp.idct_permutation, &s->intra_scantable  , wmv1_scantable[1]);

        ff_init_scantable(s->dsp.idct_permutation, &s->intra_h_scantable, wmv1_scantable[2]);

        ff_init_scantable(s->dsp.idct_permutation, &s->intra_v_scantable, wmv1_scantable[3]);

        ff_init_scantable(s->dsp.idct_permutation, &s->inter_scantable  , wmv1_scantable[0]);

    }

    //Note the default tables are set in common_init in mpegvideo.c



    if(!inited){

        inited=1;



        init_h263_dc_for_msmpeg4();

    }

}

static int read_packet(AVFormatContext *s,

                          AVPacket *pkt)

{

    ByteIOContext *pb = s->pb;

    PutBitContext pbo;

    uint16_t buf[8 * MAX_FRAME_SIZE + 2];

    int packet_size;

    int sync;

    uint16_t* src=buf;

    int i, j, ret;



    if(url_feof(pb))

        return AVERROR_EOF;



    sync = get_le16(pb); // sync word

    packet_size = get_le16(pb) / 8;

    assert(packet_size < 8 * MAX_FRAME_SIZE);



    ret = get_buffer(pb, (uint8_t*)buf, (8 * packet_size) * sizeof(uint16_t));

    if(ret<0)

        return ret;

    if(ret != 8 * packet_size * sizeof(uint16_t))

        return AVERROR(EIO);



    av_new_packet(pkt, packet_size);



    init_put_bits(&pbo, pkt->data, packet_size);

    for(j=0; j < packet_size; j++)

        for(i=0; i<8;i++)

            put_bits(&pbo,1, AV_RL16(src++) == BIT_1 ? 1 : 0);



    flush_put_bits(&pbo);



    pkt->duration=1;

    return 0;

}

static int dv_encode_video_segment(AVCodecContext *avctx, DVwork_chunk *work_chunk)

{

    DVVideoContext *s = avctx->priv_data;

    int mb_index, i, j;

    int mb_x, mb_y, c_offset, linesize;

    uint8_t*  y_ptr;

    uint8_t*  data;

    uint8_t*  dif;

    uint8_t   scratch[64];

    EncBlockInfo  enc_blks[5*DV_MAX_BPM];

    PutBitContext pbs[5*DV_MAX_BPM];

    PutBitContext* pb;

    EncBlockInfo* enc_blk;

    int       vs_bit_size = 0;

    int       qnos[5] = {15, 15, 15, 15, 15}; /* No quantization */

    int*      qnosp = &qnos[0];



    dif = &s->buf[work_chunk->buf_offset*80];

    enc_blk = &enc_blks[0];

    for (mb_index = 0; mb_index < 5; mb_index++) {

        dv_calculate_mb_xy(s, work_chunk, mb_index, &mb_x, &mb_y);

        y_ptr    = s->picture.data[0] + ((mb_y * s->picture.linesize[0] + mb_x) << 3);

        c_offset = (((mb_y >>  (s->sys->pix_fmt == PIX_FMT_YUV420P)) * s->picture.linesize[1] +

                     (mb_x >> ((s->sys->pix_fmt == PIX_FMT_YUV411P) ? 2 : 1))) << 3);

        for (j = 0; j < 6; j++) {

            if (s->sys->pix_fmt == PIX_FMT_YUV422P) { /* 4:2:2 */

                if (j == 0 || j == 2) {

                    /* Y0 Y1 */

                    data     = y_ptr + ((j >> 1) * 8);

                    linesize = s->picture.linesize[0];

                } else if (j > 3) {

                    /* Cr Cb */

                    data     = s->picture.data[6 - j] + c_offset;

                    linesize = s->picture.linesize[6 - j];

                } else {

                    /* j=1 and j=3 are "dummy" blocks, used for AC data only */

                    data     = NULL;

                    linesize = 0;

                }

            } else { /* 4:1:1 or 4:2:0 */

                if (j < 4) {  /* Four Y blocks */

                    /* NOTE: at end of line, the macroblock is handled as 420 */

                    if (s->sys->pix_fmt == PIX_FMT_YUV411P && mb_x < (704 / 8)) {

                        data = y_ptr + (j * 8);

                    } else {

                        data = y_ptr + ((j & 1) * 8) + ((j >> 1) * 8 * s->picture.linesize[0]);

                    }

                    linesize = s->picture.linesize[0];

                } else {      /* Cr and Cb blocks */

                    /* don't ask Fabrice why they inverted Cb and Cr ! */

                    data     = s->picture.data    [6 - j] + c_offset;

                    linesize = s->picture.linesize[6 - j];

                    if (s->sys->pix_fmt == PIX_FMT_YUV411P && mb_x >= (704 / 8)) {

                        uint8_t* d;

                        uint8_t* b = scratch;

                        for (i = 0; i < 8; i++) {

                            d = data + 8 * linesize;

                            b[0] = data[0]; b[1] = data[1]; b[2] = data[2]; b[3] = data[3];

                            b[4] =    d[0]; b[5] =    d[1]; b[6] =    d[2]; b[7] =    d[3];

                            data += linesize;

                            b += 8;

                        }

                        data = scratch;

                        linesize = 8;

                    }

                }

            }



            vs_bit_size += dv_init_enc_block(enc_blk, data, linesize, s, j>>2);



            ++enc_blk;

        }

    }



    if (vs_total_ac_bits < vs_bit_size)

        dv_guess_qnos(&enc_blks[0], qnosp);



    /* DIF encoding process */

    for (j=0; j<5*s->sys->bpm;) {

        int start_mb = j;



        dif[3] = *qnosp++;

        dif += 4;



        /* First pass over individual cells only */

        for (i=0; i<s->sys->bpm; i++, j++) {

            int sz = s->sys->block_sizes[i]>>3;



            init_put_bits(&pbs[j], dif, sz);

            put_bits(&pbs[j], 9, (uint16_t)(((enc_blks[j].mb[0] >> 3) - 1024 + 2) >> 2));

            put_bits(&pbs[j], 1, enc_blks[j].dct_mode);

            put_bits(&pbs[j], 2, enc_blks[j].cno);



            dv_encode_ac(&enc_blks[j], &pbs[j], &pbs[j+1]);

            dif += sz;

        }



        /* Second pass over each MB space */

        pb = &pbs[start_mb];

        for (i=0; i<s->sys->bpm; i++) {

            if (enc_blks[start_mb+i].partial_bit_count)

                pb = dv_encode_ac(&enc_blks[start_mb+i], pb, &pbs[start_mb+s->sys->bpm]);

        }

    }



    /* Third and final pass over the whole video segment space */

    pb = &pbs[0];

    for (j=0; j<5*s->sys->bpm; j++) {

       if (enc_blks[j].partial_bit_count)

           pb = dv_encode_ac(&enc_blks[j], pb, &pbs[s->sys->bpm*5]);

       if (enc_blks[j].partial_bit_count)

            av_log(NULL, AV_LOG_ERROR, "ac bitstream overflow\n");

    }



    for (j=0; j<5*s->sys->bpm; j++)

       flush_put_bits(&pbs[j]);



    return 0;

}

static void draw_slice(AVFilterLink *inlink, int y, int h, int slice_dir)

{

    FadeContext *fade = inlink->dst->priv;

    AVFilterBufferRef *outpic = inlink->cur_buf;

    uint8_t *p;

    int i, j, plane;



    if (fade->factor < 65536) {

        /* luma or rgb plane */

        for (i = 0; i < h; i++) {

            p = outpic->data[0] + (y+i) * outpic->linesize[0];

            for (j = 0; j < inlink->w * fade->bpp; j++) {

                /* fade->factor is using 16 lower-order bits for decimal

                 * places. 32768 = 1 << 15, it is an integer representation

                 * of 0.5 and is for rounding. */

                *p = (*p * fade->factor + 32768) >> 16;

                p++;

            }

        }



        if (outpic->data[0] && outpic->data[1]) {

            /* chroma planes */

            for (plane = 1; plane < 3; plane++) {

                for (i = 0; i < h; i++) {

                    p = outpic->data[plane] + ((y+i) >> fade->vsub) * outpic->linesize[plane];

                    for (j = 0; j < inlink->w >> fade->hsub; j++) {

                        /* 8421367 = ((128 << 1) + 1) << 15. It is an integer

                         * representation of 128.5. The .5 is for rounding

                         * purposes. */

                        *p = ((*p - 128) * fade->factor + 8421367) >> 16;

                        p++;

                    }

                }

            }

        }

    }



    avfilter_draw_slice(inlink->dst->outputs[0], y, h, slice_dir);

}

static int decode_block_coeffs(VP56RangeCoder *c, DCTELEM block[16],

                               uint8_t probs[8][3][NUM_DCT_TOKENS-1],

                               int i, int zero_nhood, int16_t qmul[2])

{

    uint8_t *token_prob;

    int nonzero = 0;

    int coeff;



    do {

        token_prob = probs[vp8_coeff_band[i]][zero_nhood];



        if (!vp56_rac_get_prob_branchy(c, token_prob[0]))   // DCT_EOB

            return nonzero;



skip_eob:

        if (!vp56_rac_get_prob_branchy(c, token_prob[1])) { // DCT_0

            zero_nhood = 0;

            token_prob = probs[vp8_coeff_band[++i]][0];

            if (i < 16)

                goto skip_eob;

            return nonzero; // invalid input; blocks should end with EOB

        }



        if (!vp56_rac_get_prob_branchy(c, token_prob[2])) { // DCT_1

            coeff = 1;

            zero_nhood = 1;

        } else {

            zero_nhood = 2;



            if (!vp56_rac_get_prob_branchy(c, token_prob[3])) { // DCT 2,3,4

                coeff = vp56_rac_get_prob(c, token_prob[4]);

                if (coeff)

                    coeff += vp56_rac_get_prob(c, token_prob[5]);

                coeff += 2;

            } else {

                // DCT_CAT*

                if (!vp56_rac_get_prob_branchy(c, token_prob[6])) {

                    if (!vp56_rac_get_prob_branchy(c, token_prob[7])) { // DCT_CAT1

                        coeff  = 5 + vp56_rac_get_prob(c, vp8_dct_cat1_prob[0]);

                    } else {                                    // DCT_CAT2

                        coeff  = 7;

                        coeff += vp56_rac_get_prob(c, vp8_dct_cat2_prob[0]) << 1;

                        coeff += vp56_rac_get_prob(c, vp8_dct_cat2_prob[1]);

                    }

                } else {    // DCT_CAT3 and up

                    int a = vp56_rac_get_prob(c, token_prob[8]);

                    int b = vp56_rac_get_prob(c, token_prob[9+a]);

                    int cat = (a<<1) + b;

                    coeff  = 3 + (8<<cat);

                    coeff += vp8_rac_get_coeff(c, vp8_dct_cat_prob[cat]);

                }

            }

        }



        // todo: full [16] qmat? load into register?

        block[zigzag_scan[i]] = (vp8_rac_get(c) ? -coeff : coeff) * qmul[!!i];

        nonzero = ++i;

    } while (i < 16);



    return nonzero;

}

static void fill_mbaff_ref_list(H264Context *h){

    int list, i, j;

    for(list=0; list<2; list++){

        for(i=0; i<h->ref_count[list]; i++){

            Picture *frame = &h->ref_list[list][i];

            Picture *field = &h->ref_list[list][16+2*i];

            field[0] = *frame;

            for(j=0; j<3; j++)

                field[0].linesize[j] <<= 1;

            field[1] = field[0];

            for(j=0; j<3; j++)

                field[1].data[j] += frame->linesize[j];



            h->luma_weight[list][16+2*i] = h->luma_weight[list][16+2*i+1] = h->luma_weight[list][i];

            h->luma_offset[list][16+2*i] = h->luma_offset[list][16+2*i+1] = h->luma_offset[list][i];

            for(j=0; j<2; j++){

                h->chroma_weight[list][16+2*i][j] = h->chroma_weight[list][16+2*i+1][j] = h->chroma_weight[list][i][j];

                h->chroma_offset[list][16+2*i][j] = h->chroma_offset[list][16+2*i+1][j] = h->chroma_offset[list][i][j];

            }

        }

    }

    for(j=0; j<h->ref_count[1]; j++){

        for(i=0; i<h->ref_count[0]; i++)

            h->implicit_weight[j][16+2*i] = h->implicit_weight[j][16+2*i+1] = h->implicit_weight[j][i];

        memcpy(h->implicit_weight[16+2*j],   h->implicit_weight[j], sizeof(*h->implicit_weight));

        memcpy(h->implicit_weight[16+2*j+1], h->implicit_weight[j], sizeof(*h->implicit_weight));

    }

}

