    avpriv_float_dsp_init(&c->fdsp, avctx->flags & CODEC_FLAG_BITEXACT);



    if (init_vlc(&c->scale_diff, 9, ON2AVC_SCALE_DIFFS,

                 ff_on2avc_scale_diff_bits,  1, 1,

                 ff_on2avc_scale_diff_codes, 4, 4, 0)) {

        av_log(avctx, AV_LOG_ERROR, "Cannot init VLC\n");

        return AVERROR(ENOMEM);


    for (i = 1; i < 9; i++) {

        int idx = i - 1;

        if (ff_init_vlc_sparse(&c->cb_vlc[i], 9, ff_on2avc_quad_cb_elems[idx],

                               ff_on2avc_quad_cb_bits[idx],  1, 1,

                               ff_on2avc_quad_cb_codes[idx], 4, 4,

                               ff_on2avc_quad_cb_syms[idx],  2, 2, 0)) {

            av_log(avctx, AV_LOG_ERROR, "Cannot init VLC\n");

            on2avc_free_vlcs(c);

            return AVERROR(ENOMEM);



    for (i = 9; i < 16; i++) {

        int idx = i - 9;

        if (ff_init_vlc_sparse(&c->cb_vlc[i], 9, ff_on2avc_pair_cb_elems[idx],

                               ff_on2avc_pair_cb_bits[idx],  1, 1,

                               ff_on2avc_pair_cb_codes[idx], 2, 2,

                               ff_on2avc_pair_cb_syms[idx],  2, 2, 0)) {

            av_log(avctx, AV_LOG_ERROR, "Cannot init VLC\n");

            on2avc_free_vlcs(c);

            return AVERROR(ENOMEM);





    return 0;

static int ea_probe(AVProbeData *p)

{

    switch (AV_RL32(&p->buf[0])) {

    case ISNh_TAG:

    case SCHl_TAG:

    case SEAD_TAG:

    case SHEN_TAG:

    case kVGT_TAG:

    case MADk_TAG:

    case MPCh_TAG:

    case MVhd_TAG:

    case MVIh_TAG:

        break;

    default:

        return 0;

    }

    if (AV_RL32(&p->buf[4]) > 0xfffff && AV_RB32(&p->buf[4]) > 0xfffff)

        return 0;



    return AVPROBE_SCORE_MAX;

}

static int ulti_decode_frame(AVCodecContext *avctx,

                             void *data, int *data_size,

                             AVPacket *avpkt)

{

    const uint8_t *buf = avpkt->data;

    int buf_size = avpkt->size;

    UltimotionDecodeContext *s=avctx->priv_data;

    int modifier = 0;

    int uniq = 0;

    int mode = 0;

    int blocks = 0;

    int done = 0;

    int x = 0, y = 0;

    int i;

    int skip;

    int tmp;



    s->frame.reference = 1;

    s->frame.buffer_hints = FF_BUFFER_HINTS_VALID | FF_BUFFER_HINTS_PRESERVE | FF_BUFFER_HINTS_REUSABLE;

    if (avctx->reget_buffer(avctx, &s->frame) < 0) {

        av_log(avctx, AV_LOG_ERROR, "reget_buffer() failed\n");

        return -1;

    }



    while(!done) {

        int idx;

        if(blocks >= s->blocks || y >= s->height)

            break;//all blocks decoded



        idx = *buf++;

        if((idx & 0xF8) == 0x70) {

            switch(idx) {

            case 0x70: //change modifier

                modifier = *buf++;

                if(modifier>1)

                    av_log(avctx, AV_LOG_INFO, "warning: modifier must be 0 or 1, got %i\n", modifier);

                break;

            case 0x71: // set uniq flag

                uniq = 1;

                break;

            case 0x72: //toggle mode

                mode = !mode;

                break;

            case 0x73: //end-of-frame

                done = 1;

                break;

            case 0x74: //skip some blocks

                skip = *buf++;

                if ((blocks + skip) >= s->blocks)

                    break;

                blocks += skip;

                x += skip * 8;

                while(x >= s->width) {

                    x -= s->width;

                    y += 8;

                }

                break;

            default:

                av_log(avctx, AV_LOG_INFO, "warning: unknown escape 0x%02X\n", idx);

            }

        } else { //handle one block

            int code;

            int cf;

            int angle = 0;

            uint8_t Y[4]; // luma samples of block

            int tx = 0, ty = 0; //coords of subblock

            int chroma = 0;

            if (mode || uniq) {

                uniq = 0;

                cf = 1;

                chroma = 0;

            } else {

                cf = 0;

                if (idx)

                    chroma = *buf++;

            }

            for (i = 0; i < 4; i++) { // for every subblock

                code = (idx >> (6 - i*2)) & 3; //extract 2 bits

                if(!code) //skip subblock

                    continue;

                if(cf)

                    chroma = *buf++;

                tx = x + block_coords[i * 2];

                ty = y + block_coords[(i * 2) + 1];

                switch(code) {

                case 1:

                    tmp = *buf++;



                    angle = angle_by_index[(tmp >> 6) & 0x3];



                    Y[0] = tmp & 0x3F;

                    Y[1] = Y[0];



                    if (angle) {

                        Y[2] = Y[0]+1;

                        if (Y[2] > 0x3F)

                            Y[2] = 0x3F;

                        Y[3] = Y[2];

                    } else {

                        Y[2] = Y[0];

                        Y[3] = Y[0];

                    }

                    break;



                case 2:

                    if (modifier) { // unpack four luma samples

                        tmp = bytestream_get_be24(&buf);



                        Y[0] = (tmp >> 18) & 0x3F;

                        Y[1] = (tmp >> 12) & 0x3F;

                        Y[2] = (tmp >> 6) & 0x3F;

                        Y[3] = tmp & 0x3F;

                        angle = 16;

                    } else { // retrieve luma samples from codebook

                        tmp = bytestream_get_be16(&buf);



                        angle = (tmp >> 12) & 0xF;

                        tmp &= 0xFFF;

                        tmp <<= 2;

                        Y[0] = s->ulti_codebook[tmp];

                        Y[1] = s->ulti_codebook[tmp + 1];

                        Y[2] = s->ulti_codebook[tmp + 2];

                        Y[3] = s->ulti_codebook[tmp + 3];

                    }

                    break;



                case 3:

                    if (modifier) { // all 16 luma samples

                        uint8_t Luma[16];



                        tmp = bytestream_get_be24(&buf);

                        Luma[0] = (tmp >> 18) & 0x3F;

                        Luma[1] = (tmp >> 12) & 0x3F;

                        Luma[2] = (tmp >> 6) & 0x3F;

                        Luma[3] = tmp & 0x3F;



                        tmp = bytestream_get_be24(&buf);

                        Luma[4] = (tmp >> 18) & 0x3F;

                        Luma[5] = (tmp >> 12) & 0x3F;

                        Luma[6] = (tmp >> 6) & 0x3F;

                        Luma[7] = tmp & 0x3F;



                        tmp = bytestream_get_be24(&buf);

                        Luma[8] = (tmp >> 18) & 0x3F;

                        Luma[9] = (tmp >> 12) & 0x3F;

                        Luma[10] = (tmp >> 6) & 0x3F;

                        Luma[11] = tmp & 0x3F;



                        tmp = bytestream_get_be24(&buf);

                        Luma[12] = (tmp >> 18) & 0x3F;

                        Luma[13] = (tmp >> 12) & 0x3F;

                        Luma[14] = (tmp >> 6) & 0x3F;

                        Luma[15] = tmp & 0x3F;



                        ulti_convert_yuv(&s->frame, tx, ty, Luma, chroma);

                    } else {

                        tmp = *buf++;

                        if(tmp & 0x80) {

                            angle = (tmp >> 4) & 0x7;

                            tmp = (tmp << 8) + *buf++;

                            Y[0] = (tmp >> 6) & 0x3F;

                            Y[1] = tmp & 0x3F;

                            Y[2] = (*buf++) & 0x3F;

                            Y[3] = (*buf++) & 0x3F;

                            ulti_grad(&s->frame, tx, ty, Y, chroma, angle); //draw block

                        } else { // some patterns

                            int f0, f1;

                            f0 = *buf++;

                            f1 = tmp;

                            Y[0] = (*buf++) & 0x3F;

                            Y[1] = (*buf++) & 0x3F;

                            ulti_pattern(&s->frame, tx, ty, f1, f0, Y[0], Y[1], chroma);

                        }

                    }

                    break;

                }

                if(code != 3)

                    ulti_grad(&s->frame, tx, ty, Y, chroma, angle); // draw block

            }

            blocks++;

                x += 8;

            if(x >= s->width) {

                x = 0;

                y += 8;

            }

        }

    }



    *data_size=sizeof(AVFrame);

    *(AVFrame*)data= s->frame;



    return buf_size;

}

int locate_option(int argc, char **argv, const OptionDef *options,

                  const char *optname)

{

    const OptionDef *po;

    int i;



    for (i = 1; i < argc; i++) {

        const char *cur_opt = argv[i];



        if (*cur_opt++ != '-')

            continue;



        po = find_option(options, cur_opt);

        if (!po->name && cur_opt[0] == 'n' && cur_opt[1] == 'o')

            po = find_option(options, cur_opt + 2);



        if ((!po->name && !strcmp(cur_opt, optname)) ||

             (po->name && !strcmp(optname, po->name)))

            return i;



        if (!po || po->flags & HAS_ARG)

            i++;

    }

    return 0;

}

static inline int asym_quant(int c, int e, int qbits)

{

    int m;



    c = (((c << e) >> (24 - qbits)) + 1) >> 1;

    m = (1 << (qbits-1));

    if (c >= m)

        c = m - 1;

    av_assert2(c >= -m);

    return c;

}

static inline int compress_coef(int *coefs, int num)

{

    int i, res = 0;

    for (i = 0; i < num; i++)

        res += coef_test_compression(coefs[i]);

    return res == num ? 1 : 0;

}

void ff_simple_idct248_put(uint8_t *dest, int line_size, DCTELEM *block)

{

    int i;

    DCTELEM *ptr;



    /* butterfly */

    ptr = block;

    for(i=0;i<4;i++) {

        BF(0);

        BF(1);

        BF(2);

        BF(3);

        BF(4);

        BF(5);

        BF(6);

        BF(7);

        ptr += 2 * 8;

    }



    /* IDCT8 on each line */

    for(i=0; i<8; i++) {

        idctRowCondDC_8(block + i*8);

    }



    /* IDCT4 and store */

    for(i=0;i<8;i++) {

        idct4col_put(dest + i, 2 * line_size, block + i);

        idct4col_put(dest + line_size + i, 2 * line_size, block + 8 + i);

    }

}

static int vc1_decode_intra_block(VC1Context *v, int16_t block[64], int n,

                                  int coded, int mquant, int codingset)

{

    GetBitContext *gb = &v->s.gb;

    MpegEncContext *s = &v->s;

    int dc_pred_dir = 0; /* Direction of the DC prediction used */

    int i;

    int16_t *dc_val;

    int16_t *ac_val, *ac_val2;

    int dcdiff;

    int mb_pos = s->mb_x + s->mb_y * s->mb_stride;

    int a_avail = v->a_avail, c_avail = v->c_avail;

    int use_pred = s->ac_pred;

    int scale;

    int q1, q2 = 0;



    s->dsp.clear_block(block);



    /* XXX: Guard against dumb values of mquant */

    mquant = (mquant < 1) ? 0 : ((mquant > 31) ? 31 : mquant);



    /* Set DC scale - y and c use the same */

    s->y_dc_scale = s->y_dc_scale_table[mquant];

    s->c_dc_scale = s->c_dc_scale_table[mquant];



    /* Get DC differential */

    if (n < 4) {

        dcdiff = get_vlc2(&s->gb, ff_msmp4_dc_luma_vlc[s->dc_table_index].table, DC_VLC_BITS, 3);

    } else {

        dcdiff = get_vlc2(&s->gb, ff_msmp4_dc_chroma_vlc[s->dc_table_index].table, DC_VLC_BITS, 3);

    }

    if (dcdiff < 0) {

        av_log(s->avctx, AV_LOG_ERROR, "Illegal DC VLC\n");

        return -1;

    }

    if (dcdiff) {

        if (dcdiff == 119 /* ESC index value */) {

            /* TODO: Optimize */

            if (mquant == 1)      dcdiff = get_bits(gb, 10);

            else if (mquant == 2) dcdiff = get_bits(gb, 9);

            else                  dcdiff = get_bits(gb, 8);

        } else {

            if (mquant == 1)

                dcdiff = (dcdiff << 2) + get_bits(gb, 2) - 3;

            else if (mquant == 2)

                dcdiff = (dcdiff << 1) + get_bits1(gb)   - 1;

        }

        if (get_bits1(gb))

            dcdiff = -dcdiff;

    }



    /* Prediction */

    dcdiff += vc1_pred_dc(&v->s, v->overlap, mquant, n, a_avail, c_avail, &dc_val, &dc_pred_dir);

    *dc_val = dcdiff;



    /* Store the quantized DC coeff, used for prediction */



    if (n < 4) {

        block[0] = dcdiff * s->y_dc_scale;

    } else {

        block[0] = dcdiff * s->c_dc_scale;

    }



    //AC Decoding

    i = 1;



    /* check if AC is needed at all and adjust direction if needed */

    if (!a_avail) dc_pred_dir = 1;

    if (!c_avail) dc_pred_dir = 0;

    if (!a_avail && !c_avail) use_pred = 0;

    ac_val = s->ac_val[0][0] + s->block_index[n] * 16;

    ac_val2 = ac_val;



    scale = mquant * 2 + v->halfpq;



    if (dc_pred_dir) //left

        ac_val -= 16;

    else //top

        ac_val -= 16 * s->block_wrap[n];



    q1 = s->current_picture.f.qscale_table[mb_pos];

    if (dc_pred_dir && c_avail && mb_pos)

        q2 = s->current_picture.f.qscale_table[mb_pos - 1];

    if (!dc_pred_dir && a_avail && mb_pos >= s->mb_stride)

        q2 = s->current_picture.f.qscale_table[mb_pos - s->mb_stride];

    if ( dc_pred_dir && n == 1)

        q2 = q1;

    if (!dc_pred_dir && n == 2)

        q2 = q1;

    if (n == 3) q2 = q1;



    if (coded) {

        int last = 0, skip, value;

        int k;



        while (!last) {

            vc1_decode_ac_coeff(v, &last, &skip, &value, codingset);

            i += skip;

            if (i > 63)

                break;

            if (v->fcm == PROGRESSIVE)

                block[v->zz_8x8[0][i++]] = value;

            else {

                if (use_pred && (v->fcm == ILACE_FRAME)) {

                    if (!dc_pred_dir) // top

                        block[v->zz_8x8[2][i++]] = value;

                    else // left

                        block[v->zz_8x8[3][i++]] = value;

                } else {

                    block[v->zzi_8x8[i++]] = value;

                }

            }

        }



        /* apply AC prediction if needed */

        if (use_pred) {

            /* scale predictors if needed*/

            if (q2 && q1 != q2) {

                q1 = q1 * 2 + ((q1 == v->pq) ? v->halfpq : 0) - 1;

                q2 = q2 * 2 + ((q2 == v->pq) ? v->halfpq : 0) - 1;



                if (q1 < 1)

                    return AVERROR_INVALIDDATA;

                if (dc_pred_dir) { // left

                    for (k = 1; k < 8; k++)

                        block[k << v->left_blk_sh] += (ac_val[k] * q2 * ff_vc1_dqscale[q1 - 1] + 0x20000) >> 18;

                } else { //top

                    for (k = 1; k < 8; k++)

                        block[k << v->top_blk_sh] += (ac_val[k + 8] * q2 * ff_vc1_dqscale[q1 - 1] + 0x20000) >> 18;

                }

            } else {

                if (dc_pred_dir) { // left

                    for (k = 1; k < 8; k++)

                        block[k << v->left_blk_sh] += ac_val[k];

                } else { // top

                    for (k = 1; k < 8; k++)

                        block[k << v->top_blk_sh] += ac_val[k + 8];

                }

            }

        }

        /* save AC coeffs for further prediction */

        for (k = 1; k < 8; k++) {

            ac_val2[k    ] = block[k << v->left_blk_sh];

            ac_val2[k + 8] = block[k << v->top_blk_sh];

        }



        /* scale AC coeffs */

        for (k = 1; k < 64; k++)

            if (block[k]) {

                block[k] *= scale;

                if (!v->pquantizer)

                    block[k] += (block[k] < 0) ? -mquant : mquant;

            }



        if (use_pred) i = 63;

    } else { // no AC coeffs

        int k;



        memset(ac_val2, 0, 16 * 2);

        if (dc_pred_dir) { // left

            if (use_pred) {

                memcpy(ac_val2, ac_val, 8 * 2);

                if (q2 && q1 != q2) {

                    q1 = q1 * 2 + ((q1 == v->pq) ? v->halfpq : 0) - 1;

                    q2 = q2 * 2 + ((q2 == v->pq) ? v->halfpq : 0) - 1;

                    if (q1 < 1)

                        return AVERROR_INVALIDDATA;

                    for (k = 1; k < 8; k++)

                        ac_val2[k] = (ac_val2[k] * q2 * ff_vc1_dqscale[q1 - 1] + 0x20000) >> 18;

                }

            }

        } else { // top

            if (use_pred) {

                memcpy(ac_val2 + 8, ac_val + 8, 8 * 2);

                if (q2 && q1 != q2) {

                    q1 = q1 * 2 + ((q1 == v->pq) ? v->halfpq : 0) - 1;

                    q2 = q2 * 2 + ((q2 == v->pq) ? v->halfpq : 0) - 1;

                    if (q1 < 1)

                        return AVERROR_INVALIDDATA;

                    for (k = 1; k < 8; k++)

                        ac_val2[k + 8] = (ac_val2[k + 8] * q2 * ff_vc1_dqscale[q1 - 1] + 0x20000) >> 18;

                }

            }

        }



        /* apply AC prediction if needed */

        if (use_pred) {

            if (dc_pred_dir) { // left

                for (k = 1; k < 8; k++) {

                    block[k << v->left_blk_sh] = ac_val2[k] * scale;

                    if (!v->pquantizer && block[k << v->left_blk_sh])

                        block[k << v->left_blk_sh] += (block[k << v->left_blk_sh] < 0) ? -mquant : mquant;

                }

            } else { // top

                for (k = 1; k < 8; k++) {

                    block[k << v->top_blk_sh] = ac_val2[k + 8] * scale;

                    if (!v->pquantizer && block[k << v->top_blk_sh])

                        block[k << v->top_blk_sh] += (block[k << v->top_blk_sh] < 0) ? -mquant : mquant;

                }

            }

            i = 63;

        }

    }

    s->block_last_index[n] = i;



    return 0;

}

int rtjpeg_decode_frame_yuv420(RTJpegContext *c, AVFrame *f,

                               const uint8_t *buf, int buf_size) {

    GetBitContext gb;

    int w = c->w / 16, h = c->h / 16;

    int x, y;

    uint8_t *y1 = f->data[0], *y2 = f->data[0] + 8 * f->linesize[0];

    uint8_t *u = f->data[1], *v = f->data[2];

    init_get_bits(&gb, buf, buf_size * 8);

    for (y = 0; y < h; y++) {

        for (x = 0; x < w; x++) {

            DCTELEM *block = c->block;

            if (get_block(&gb, block, c->scan, c->lquant) > 0)

                c->dsp->idct_put(y1, f->linesize[0], block);

            y1 += 8;

            if (get_block(&gb, block, c->scan, c->lquant) > 0)

                c->dsp->idct_put(y1, f->linesize[0], block);

            y1 += 8;

            if (get_block(&gb, block, c->scan, c->lquant) > 0)

                c->dsp->idct_put(y2, f->linesize[0], block);

            y2 += 8;

            if (get_block(&gb, block, c->scan, c->lquant) > 0)

                c->dsp->idct_put(y2, f->linesize[0], block);

            y2 += 8;

            if (get_block(&gb, block, c->scan, c->cquant) > 0)

                c->dsp->idct_put(u, f->linesize[1], block);

            u += 8;

            if (get_block(&gb, block, c->scan, c->cquant) > 0)

                c->dsp->idct_put(v, f->linesize[2], block);

            v += 8;

        }

        y1 += 2 * 8 * (f->linesize[0] - w);

        y2 += 2 * 8 * (f->linesize[0] - w);

        u += 8 * (f->linesize[1] - w);

        v += 8 * (f->linesize[2] - w);

    }

    return get_bits_count(&gb) / 8;

}

static int dvbsub_probe(AVProbeData *p)

{

    int i, j, k;

    const uint8_t *end = p->buf + p->buf_size;

    int type, len;

    int max_score = 0;



    for(i=0; i<p->buf_size; i++){

        if (p->buf[i] == 0x0f) {

            const uint8_t *ptr = p->buf + i;

            uint8_t histogram[6] = {0};

            int min = 255;

            for(j=0; ptr + 6 < end; j++) {

                if (*ptr != 0x0f)

                    break;

                type    = ptr[1];

                //page_id = AV_RB16(ptr + 2);

                len     = AV_RB16(ptr + 4);

                if (type == 0x80) {

                    ;

                } else if (type >= 0x10 && type <= 0x14) {

                    histogram[type - 0x10] ++;

                } else

                    break;

                ptr += 6 + len;

            }

            for (k=0; k < 4; k++) {

                min = FFMIN(min, histogram[k]);

            }

            if (min && j > max_score)

                max_score = j;

        }

    }



    if (max_score > 5)

        return AVPROBE_SCORE_EXTENSION;



    return 0;

}

static int cinepak_decode (CinepakContext *s)

{

    const uint8_t  *eod = (s->data + s->size);

    int           i, result, strip_size, frame_flags, num_strips;

    int           y0 = 0;

    int           encoded_buf_size;



    if (s->size < 10)

        return -1;



    frame_flags = s->data[0];

    num_strips  = AV_RB16 (&s->data[8]);

    encoded_buf_size = ((s->data[1] << 16) | AV_RB16 (&s->data[2]));



    /* if this is the first frame, check for deviant Sega FILM data */

    if (s->sega_film_skip_bytes == -1) {

        if (encoded_buf_size != s->size) {

            /* If the encoded frame size differs from the frame size as indicated

             * by the container file, this data likely comes from a Sega FILM/CPK file.

             * If the frame header is followed by the bytes FE 00 00 06 00 00 then

             * this is probably one of the two known files that have 6 extra bytes

             * after the frame header. Else, assume 2 extra bytes. */

            if ((s->data[10] == 0xFE) &&

                (s->data[11] == 0x00) &&

                (s->data[12] == 0x00) &&

                (s->data[13] == 0x06) &&

                (s->data[14] == 0x00) &&

                (s->data[15] == 0x00))

                s->sega_film_skip_bytes = 6;

            else

                s->sega_film_skip_bytes = 2;

        } else

            s->sega_film_skip_bytes = 0;

    }



    s->data += 10 + s->sega_film_skip_bytes;



    if (num_strips > MAX_STRIPS)

        num_strips = MAX_STRIPS;



    for (i=0; i < num_strips; i++) {

        if ((s->data + 12) > eod)

            return -1;



        s->strips[i].id = s->data[0];

        s->strips[i].y1 = y0;

        s->strips[i].x1 = 0;

        s->strips[i].y2 = y0 + AV_RB16 (&s->data[8]);

        s->strips[i].x2 = s->avctx->width;



        strip_size = AV_RB24 (&s->data[1]) - 12;

        s->data   += 12;

        strip_size = ((s->data + strip_size) > eod) ? (eod - s->data) : strip_size;



        if ((i > 0) && !(frame_flags & 0x01)) {

            memcpy (s->strips[i].v4_codebook, s->strips[i-1].v4_codebook,

                sizeof(s->strips[i].v4_codebook));

            memcpy (s->strips[i].v1_codebook, s->strips[i-1].v1_codebook,

                sizeof(s->strips[i].v1_codebook));

        }



        result = cinepak_decode_strip (s, &s->strips[i], s->data, strip_size);



        if (result != 0)

            return result;



        s->data += strip_size;

        y0    = s->strips[i].y2;

    }

    return 0;

}

int ff_mpeg1_find_frame_end(ParseContext *pc, const uint8_t *buf, int buf_size, AVCodecParserContext *s)

{

    int i;

    uint32_t state = pc->state;



    /* EOF considered as end of frame */

    if (buf_size == 0)

        return 0;



/*

 0  frame start         -> 1/4

 1  first_SEQEXT        -> 0/2

 2  first field start   -> 3/0

 3  second_SEQEXT       -> 2/0

 4  searching end

*/



    for (i = 0; i < buf_size; i++) {

        av_assert1(pc->frame_start_found >= 0 && pc->frame_start_found <= 4);

        if (pc->frame_start_found & 1) {

            if (state == EXT_START_CODE && (buf[i] & 0xF0) != 0x80)

                pc->frame_start_found--;

            else if (state == EXT_START_CODE + 2) {

                if ((buf[i] & 3) == 3)

                    pc->frame_start_found = 0;

                else

                    pc->frame_start_found = (pc->frame_start_found + 1) & 3;

            }

            state++;

        } else {

            i = avpriv_find_start_code(buf + i, buf + buf_size, &state) - buf - 1;

            if (pc->frame_start_found == 0 && state >= SLICE_MIN_START_CODE && state <= SLICE_MAX_START_CODE) {

                i++;

                pc->frame_start_found = 4;

            }

            if (state == SEQ_END_CODE) {

                pc->frame_start_found = 0;

                pc->state=-1;

                return i+1;

            }

            if (pc->frame_start_found == 2 && state == SEQ_START_CODE)

                pc->frame_start_found = 0;

            if (pc->frame_start_found  < 4 && state == EXT_START_CODE)

                pc->frame_start_found++;

            if (pc->frame_start_found == 4 && (state & 0xFFFFFF00) == 0x100) {

                if (state < SLICE_MIN_START_CODE || state > SLICE_MAX_START_CODE) {

                    pc->frame_start_found = 0;

                    pc->state             = -1;

                    return i - 3;

                }

            }

            if (pc->frame_start_found == 0 && s && state == PICTURE_START_CODE) {

                ff_fetch_timestamp(s, i - 3, 1);

            }

        }

    }

    pc->state = state;

    return END_NOT_FOUND;

}

static int hwmap_config_output(AVFilterLink *outlink)

{

    AVFilterContext *avctx = outlink->src;

    HWMapContext      *ctx = avctx->priv;

    AVFilterLink   *inlink = avctx->inputs[0];

    AVHWFramesContext *hwfc;

    AVBufferRef *device;

    const AVPixFmtDescriptor *desc;

    int err;



    av_log(avctx, AV_LOG_DEBUG, "Configure hwmap %s -> %s.\n",

           av_get_pix_fmt_name(inlink->format),

           av_get_pix_fmt_name(outlink->format));



    av_buffer_unref(&ctx->hwframes_ref);



    device = avctx->hw_device_ctx;



    if (inlink->hw_frames_ctx) {

        hwfc = (AVHWFramesContext*)inlink->hw_frames_ctx->data;



        if (ctx->derive_device_type) {

            enum AVHWDeviceType type;



            type = av_hwdevice_find_type_by_name(ctx->derive_device_type);

            if (type == AV_HWDEVICE_TYPE_NONE) {

                av_log(avctx, AV_LOG_ERROR, "Invalid device type.\n");

                goto fail;

            }



            err = av_hwdevice_ctx_create_derived(&device, type,

                                                 hwfc->device_ref, 0);

            if (err < 0) {

                av_log(avctx, AV_LOG_ERROR, "Failed to created derived "

                       "device context: %d.\n", err);

                goto fail;

            }

        }



        desc = av_pix_fmt_desc_get(outlink->format);

        if (!desc) {

            err = AVERROR(EINVAL);

            goto fail;

        }



        if (inlink->format == hwfc->format &&

            (desc->flags & AV_PIX_FMT_FLAG_HWACCEL)) {

            // Map between two hardware formats (including the case of

            // undoing an existing mapping).



            if (!device) {

                av_log(avctx, AV_LOG_ERROR, "A device reference is "

                       "required to map to a hardware format.\n");

                err = AVERROR(EINVAL);

                goto fail;

            }



            err = av_hwframe_ctx_create_derived(&ctx->hwframes_ref,

                                                outlink->format,

                                                device,

                                                inlink->hw_frames_ctx, 0);

            if (err < 0) {

                av_log(avctx, AV_LOG_ERROR, "Failed to create derived "

                       "frames context: %d.\n", err);

                goto fail;

            }



        } else if ((outlink->format == hwfc->format &&

                    inlink->format  == hwfc->sw_format) ||

                   inlink->format == hwfc->format) {

            // Map from a hardware format to a software format, or

            // undo an existing such mapping.



            ctx->hwframes_ref = av_buffer_ref(inlink->hw_frames_ctx);

            if (!ctx->hwframes_ref) {

                err = AVERROR(ENOMEM);

                goto fail;

            }



        } else {

            // Non-matching formats - not supported.



            av_log(avctx, AV_LOG_ERROR, "Unsupported formats for "

                   "hwmap: from %s (%s) to %s.\n",

                   av_get_pix_fmt_name(inlink->format),

                   av_get_pix_fmt_name(hwfc->format),

                   av_get_pix_fmt_name(outlink->format));

            err = AVERROR(EINVAL);

            goto fail;

        }

    } else if (avctx->hw_device_ctx) {

        // Map from a software format to a hardware format.  This

        // creates a new hwframe context like hwupload, but then

        // returns frames mapped from that to the previous link in

        // order to fill them without an additional copy.



        if (!device) {

            av_log(avctx, AV_LOG_ERROR, "A device reference is "

                   "required to create new frames with backwards "

                   "mapping.\n");

            err = AVERROR(EINVAL);

            goto fail;

        }



        ctx->map_backwards = 1;



        ctx->hwframes_ref = av_hwframe_ctx_alloc(device);

        if (!ctx->hwframes_ref) {

            err = AVERROR(ENOMEM);

            goto fail;

        }

        hwfc = (AVHWFramesContext*)ctx->hwframes_ref->data;



        hwfc->format    = outlink->format;

        hwfc->sw_format = inlink->format;

        hwfc->width     = inlink->w;

        hwfc->height    = inlink->h;



        err = av_hwframe_ctx_init(ctx->hwframes_ref);

        if (err < 0) {

            av_log(avctx, AV_LOG_ERROR, "Failed to create frame "

                   "context for backward mapping: %d.\n", err);

            goto fail;

        }



    } else {

        av_log(avctx, AV_LOG_ERROR, "Mapping requires a hardware "

               "context (a device, or frames on input).\n");

        return AVERROR(EINVAL);

    }



    outlink->hw_frames_ctx = av_buffer_ref(ctx->hwframes_ref);

    if (!outlink->hw_frames_ctx) {

        err = AVERROR(ENOMEM);

        goto fail;

    }



    outlink->w = inlink->w;

    outlink->h = inlink->h;



    return 0;



fail:

    av_buffer_unref(&ctx->hwframes_ref);

    return err;

}

static int ape_tag_read_field(AVFormatContext *s)

{

    AVIOContext *pb = s->pb;

    uint8_t key[1024], *value;

    uint32_t size, flags;

    int i, c;



    size = avio_rl32(pb);  /* field size */

    flags = avio_rl32(pb); /* field flags */

    for (i = 0; i < sizeof(key) - 1; i++) {

        c = avio_r8(pb);

        if (c < 0x20 || c > 0x7E)

            break;

        else

            key[i] = c;

    }

    key[i] = 0;

    if (c != 0) {

        av_log(s, AV_LOG_WARNING, "Invalid APE tag key '%s'.\n", key);

        return -1;

    }

    if (size >= UINT_MAX)

        return -1;

    if (flags & APE_TAG_FLAG_IS_BINARY) {

        uint8_t filename[1024];

        AVStream *st = avformat_new_stream(s, NULL);

        if (!st)

            return AVERROR(ENOMEM);

        avio_get_str(pb, INT_MAX, filename, sizeof(filename));

        st->codec->extradata = av_malloc(size + FF_INPUT_BUFFER_PADDING_SIZE);

        if (!st->codec->extradata)

            return AVERROR(ENOMEM);

        if (avio_read(pb, st->codec->extradata, size) != size) {

            av_freep(&st->codec->extradata);

            return AVERROR(EIO);

        }

        st->codec->extradata_size = size;

        av_dict_set(&st->metadata, key, filename, 0);

        st->codec->codec_type = AVMEDIA_TYPE_ATTACHMENT;

    } else {

        value = av_malloc(size+1);

        if (!value)

            return AVERROR(ENOMEM);

        c = avio_read(pb, value, size);

        if (c < 0)

            return c;

        value[c] = 0;

        av_dict_set(&s->metadata, key, value, AV_DICT_DONT_STRDUP_VAL);

    }

    return 0;

}

void v_resample16_altivec(uint8_t *dst, int dst_width, const uint8_t *src,

                          int wrap, int16_t *filter)

{

    int sum, i;

    const uint8_t *s;

    vector unsigned char *tv, tmp, dstv, zero;

    vec_ss_t srchv[4], srclv[4], fv[4];

    vector signed short zeros, sumhv, sumlv;

    s = src;



    for(i=0;i<4;i++)

    {

        /*

           The vec_madds later on does an implicit >>15 on the result.

           Since FILTER_BITS is 8, and we have 15 bits of magnitude in

           a signed short, we have just enough bits to pre-shift our

           filter constants <<7 to compensate for vec_madds.

        */

        fv[i].s[0] = filter[i] << (15-FILTER_BITS);

        fv[i].v = vec_splat(fv[i].v, 0);

    }



    zero = vec_splat_u8(0);

    zeros = vec_splat_s16(0);





    /*

       When we're resampling, we'd ideally like both our input buffers,

       and output buffers to be 16-byte aligned, so we can do both aligned

       reads and writes. Sadly we can't always have this at the moment, so

       we opt for aligned writes, as unaligned writes have a huge overhead.

       To do this, do enough scalar resamples to get dst 16-byte aligned.

    */

    i = (-(int)dst) & 0xf;

    while(i>0) {

        sum = s[0 * wrap] * filter[0] +

        s[1 * wrap] * filter[1] +

        s[2 * wrap] * filter[2] +

        s[3 * wrap] * filter[3];

        sum = sum >> FILTER_BITS;

        if (sum<0) sum = 0; else if (sum>255) sum=255;

        dst[0] = sum;

        dst++;

        s++;

        dst_width--;

        i--;

    }



    /* Do our altivec resampling on 16 pixels at once. */

    while(dst_width>=16) {

        /*

           Read 16 (potentially unaligned) bytes from each of

           4 lines into 4 vectors, and split them into shorts.

           Interleave the multipy/accumulate for the resample

           filter with the loads to hide the 3 cycle latency

           the vec_madds have.

        */

        tv = (vector unsigned char *) &s[0 * wrap];

        tmp = vec_perm(tv[0], tv[1], vec_lvsl(0, &s[i * wrap]));

        srchv[0].v = (vector signed short) vec_mergeh(zero, tmp);

        srclv[0].v = (vector signed short) vec_mergel(zero, tmp);

        sumhv = vec_madds(srchv[0].v, fv[0].v, zeros);

        sumlv = vec_madds(srclv[0].v, fv[0].v, zeros);



        tv = (vector unsigned char *) &s[1 * wrap];

        tmp = vec_perm(tv[0], tv[1], vec_lvsl(0, &s[1 * wrap]));

        srchv[1].v = (vector signed short) vec_mergeh(zero, tmp);

        srclv[1].v = (vector signed short) vec_mergel(zero, tmp);

        sumhv = vec_madds(srchv[1].v, fv[1].v, sumhv);

        sumlv = vec_madds(srclv[1].v, fv[1].v, sumlv);



        tv = (vector unsigned char *) &s[2 * wrap];

        tmp = vec_perm(tv[0], tv[1], vec_lvsl(0, &s[2 * wrap]));

        srchv[2].v = (vector signed short) vec_mergeh(zero, tmp);

        srclv[2].v = (vector signed short) vec_mergel(zero, tmp);

        sumhv = vec_madds(srchv[2].v, fv[2].v, sumhv);

        sumlv = vec_madds(srclv[2].v, fv[2].v, sumlv);



        tv = (vector unsigned char *) &s[3 * wrap];

        tmp = vec_perm(tv[0], tv[1], vec_lvsl(0, &s[3 * wrap]));

        srchv[3].v = (vector signed short) vec_mergeh(zero, tmp);

        srclv[3].v = (vector signed short) vec_mergel(zero, tmp);

        sumhv = vec_madds(srchv[3].v, fv[3].v, sumhv);

        sumlv = vec_madds(srclv[3].v, fv[3].v, sumlv);



        /*

           Pack the results into our destination vector,

           and do an aligned write of that back to memory.

        */

        dstv = vec_packsu(sumhv, sumlv) ;

        vec_st(dstv, 0, (vector unsigned char *) dst);



        dst+=16;

        s+=16;

        dst_width-=16;

    }



    /*

       If there are any leftover pixels, resample them

       with the slow scalar method.

    */

    while(dst_width>0) {

        sum = s[0 * wrap] * filter[0] +

        s[1 * wrap] * filter[1] +

        s[2 * wrap] * filter[2] +

        s[3 * wrap] * filter[3];

        sum = sum >> FILTER_BITS;

        if (sum<0) sum = 0; else if (sum>255) sum=255;

        dst[0] = sum;

        dst++;

        s++;

        dst_width--;

    }

}

static void kmvc_decode_intra_8x8(KmvcContext * ctx, const uint8_t * src, int w, int h)

{

    BitBuf bb;

    int res, val;

    int i, j;

    int bx, by;

    int l0x, l1x, l0y, l1y;

    int mx, my;



    kmvc_init_getbits(bb, src);



    for (by = 0; by < h; by += 8)

        for (bx = 0; bx < w; bx += 8) {

            kmvc_getbit(bb, src, res);

            if (!res) {         // fill whole 8x8 block

                val = *src++;

                for (i = 0; i < 64; i++)

                    BLK(ctx->cur, bx + (i & 0x7), by + (i >> 3)) = val;

            } else {            // handle four 4x4 subblocks

                for (i = 0; i < 4; i++) {

                    l0x = bx + (i & 1) * 4;

                    l0y = by + (i & 2) * 2;

                    kmvc_getbit(bb, src, res);

                    if (!res) {

                        kmvc_getbit(bb, src, res);

                        if (!res) {     // fill whole 4x4 block

                            val = *src++;

                            for (j = 0; j < 16; j++)

                                BLK(ctx->cur, l0x + (j & 3), l0y + (j >> 2)) = val;

                        } else {        // copy block from already decoded place

                            val = *src++;

                            mx = val & 0xF;

                            my = val >> 4;

                            for (j = 0; j < 16; j++)

                                BLK(ctx->cur, l0x + (j & 3), l0y + (j >> 2)) =

                                    BLK(ctx->cur, l0x + (j & 3) - mx, l0y + (j >> 2) - my);

                        }

                    } else {    // descend to 2x2 sub-sub-blocks

                        for (j = 0; j < 4; j++) {

                            l1x = l0x + (j & 1) * 2;

                            l1y = l0y + (j & 2);

                            kmvc_getbit(bb, src, res);

                            if (!res) {

                                kmvc_getbit(bb, src, res);

                                if (!res) {     // fill whole 2x2 block

                                    val = *src++;

                                    BLK(ctx->cur, l1x, l1y) = val;

                                    BLK(ctx->cur, l1x + 1, l1y) = val;

                                    BLK(ctx->cur, l1x, l1y + 1) = val;

                                    BLK(ctx->cur, l1x + 1, l1y + 1) = val;

                                } else {        // copy block from already decoded place

                                    val = *src++;

                                    mx = val & 0xF;

                                    my = val >> 4;

                                    BLK(ctx->cur, l1x, l1y) = BLK(ctx->cur, l1x - mx, l1y - my);

                                    BLK(ctx->cur, l1x + 1, l1y) =

                                        BLK(ctx->cur, l1x + 1 - mx, l1y - my);

                                    BLK(ctx->cur, l1x, l1y + 1) =

                                        BLK(ctx->cur, l1x - mx, l1y + 1 - my);

                                    BLK(ctx->cur, l1x + 1, l1y + 1) =

                                        BLK(ctx->cur, l1x + 1 - mx, l1y + 1 - my);

                                }

                            } else {    // read values for block

                                BLK(ctx->cur, l1x, l1y) = *src++;

                                BLK(ctx->cur, l1x + 1, l1y) = *src++;

                                BLK(ctx->cur, l1x, l1y + 1) = *src++;

                                BLK(ctx->cur, l1x + 1, l1y + 1) = *src++;

                            }

                        }

                    }

                }

            }

        }

}

static av_cold int smvjpeg_decode_end(AVCodecContext *avctx)

{

    SMVJpegDecodeContext *s = avctx->priv_data;

    MJpegDecodeContext *jpg = &s->jpg;

    int ret;



    jpg->picture_ptr = NULL;

    av_frame_free(&s->picture[0]);

