        if (!s->temp[0])

            return AVERROR(ENOMEM);

    }

    return 0;

}

static void body(uint32_t ABCD[4], uint32_t X[16])

{

    int i av_unused;

    uint32_t t;

    uint32_t a = ABCD[3];

    uint32_t b = ABCD[2];

    uint32_t c = ABCD[1];

    uint32_t d = ABCD[0];



#if HAVE_BIGENDIAN

    for (i = 0; i < 16; i++)

        X[i] = av_bswap32(X[i]);

#endif



#if CONFIG_SMALL

    for (i = 0; i < 64; i++) {

        CORE(i, a, b, c, d);

        t = d;

        d = c;

        c = b;

        b = a;

        a = t;

    }

#else

#define CORE2(i)                                                        \

    CORE( i,   a,b,c,d); CORE((i+1),d,a,b,c);                           \

    CORE((i+2),c,d,a,b); CORE((i+3),b,c,d,a)

#define CORE4(i) CORE2(i); CORE2((i+4)); CORE2((i+8)); CORE2((i+12))

    CORE4(0); CORE4(16); CORE4(32); CORE4(48);

#endif



    ABCD[0] += d;

    ABCD[1] += c;

    ABCD[2] += b;

    ABCD[3] += a;

}

static int v210_read_header(AVFormatContext *ctx)

{

    V210DemuxerContext *s = ctx->priv_data;

    AVStream *st;



    st = avformat_new_stream(ctx, NULL);

    if (!st)

        return AVERROR(ENOMEM);



    st->codec->codec_type = AVMEDIA_TYPE_VIDEO;



    st->codec->codec_id = ctx->iformat->raw_codec_id;



    avpriv_set_pts_info(st, 64, s->framerate.den, s->framerate.num);



    st->codec->width    = s->width;

    st->codec->height   = s->height;

    st->codec->pix_fmt  = ctx->iformat->raw_codec_id == AV_CODEC_ID_V210 ?

                          AV_PIX_FMT_YUV422P10 : AV_PIX_FMT_YUV422P16;

    st->codec->bit_rate = av_rescale_q(GET_PACKET_SIZE(s->width, s->height),

                                       (AVRational){8,1}, st->time_base);



    return 0;

}

int ff_h263_decode_mb(MpegEncContext *s,

                      int16_t block[6][64])

{

    int cbpc, cbpy, i, cbp, pred_x, pred_y, mx, my, dquant;

    int16_t *mot_val;

    const int xy= s->mb_x + s->mb_y * s->mb_stride;

    int cbpb = 0, pb_mv_count = 0;



    assert(!s->h263_pred);



    if (s->pict_type == AV_PICTURE_TYPE_P) {

        do{

            if (get_bits1(&s->gb)) {

                /* skip mb */

                s->mb_intra = 0;

                for(i=0;i<6;i++)

                    s->block_last_index[i] = -1;

                s->mv_dir = MV_DIR_FORWARD;

                s->mv_type = MV_TYPE_16X16;

                s->current_picture.mb_type[xy] = MB_TYPE_SKIP | MB_TYPE_16x16 | MB_TYPE_L0;

                s->mv[0][0][0] = 0;

                s->mv[0][0][1] = 0;

                s->mb_skipped = !(s->obmc | s->loop_filter);

                goto end;

            }

            cbpc = get_vlc2(&s->gb, ff_h263_inter_MCBPC_vlc.table, INTER_MCBPC_VLC_BITS, 2);

            if (cbpc < 0){

                av_log(s->avctx, AV_LOG_ERROR, "cbpc damaged at %d %d\n", s->mb_x, s->mb_y);

                return -1;

            }

        }while(cbpc == 20);



        s->dsp.clear_blocks(s->block[0]);



        dquant = cbpc & 8;

        s->mb_intra = ((cbpc & 4) != 0);

        if (s->mb_intra) goto intra;



        if(s->pb_frame && get_bits1(&s->gb))

            pb_mv_count = h263_get_modb(&s->gb, s->pb_frame, &cbpb);

        cbpy = get_vlc2(&s->gb, ff_h263_cbpy_vlc.table, CBPY_VLC_BITS, 1);



        if(s->alt_inter_vlc==0 || (cbpc & 3)!=3)

            cbpy ^= 0xF;



        cbp = (cbpc & 3) | (cbpy << 2);

        if (dquant) {

            h263_decode_dquant(s);

        }



        s->mv_dir = MV_DIR_FORWARD;

        if ((cbpc & 16) == 0) {

            s->current_picture.mb_type[xy] = MB_TYPE_16x16 | MB_TYPE_L0;

            /* 16x16 motion prediction */

            s->mv_type = MV_TYPE_16X16;

            ff_h263_pred_motion(s, 0, 0, &pred_x, &pred_y);

            if (s->umvplus)

               mx = h263p_decode_umotion(s, pred_x);

            else

               mx = ff_h263_decode_motion(s, pred_x, 1);



            if (mx >= 0xffff)

                return -1;



            if (s->umvplus)

               my = h263p_decode_umotion(s, pred_y);

            else

               my = ff_h263_decode_motion(s, pred_y, 1);



            if (my >= 0xffff)

                return -1;

            s->mv[0][0][0] = mx;

            s->mv[0][0][1] = my;



            if (s->umvplus && (mx - pred_x) == 1 && (my - pred_y) == 1)

               skip_bits1(&s->gb); /* Bit stuffing to prevent PSC */

        } else {

            s->current_picture.mb_type[xy] = MB_TYPE_8x8 | MB_TYPE_L0;

            s->mv_type = MV_TYPE_8X8;

            for(i=0;i<4;i++) {

                mot_val = ff_h263_pred_motion(s, i, 0, &pred_x, &pred_y);

                if (s->umvplus)

                  mx = h263p_decode_umotion(s, pred_x);

                else

                  mx = ff_h263_decode_motion(s, pred_x, 1);

                if (mx >= 0xffff)

                    return -1;



                if (s->umvplus)

                  my = h263p_decode_umotion(s, pred_y);

                else

                  my = ff_h263_decode_motion(s, pred_y, 1);

                if (my >= 0xffff)

                    return -1;

                s->mv[0][i][0] = mx;

                s->mv[0][i][1] = my;

                if (s->umvplus && (mx - pred_x) == 1 && (my - pred_y) == 1)

                  skip_bits1(&s->gb); /* Bit stuffing to prevent PSC */

                mot_val[0] = mx;

                mot_val[1] = my;

            }

        }

    } else if(s->pict_type==AV_PICTURE_TYPE_B) {

        int mb_type;

        const int stride= s->b8_stride;

        int16_t *mot_val0 = s->current_picture.motion_val[0][2 * (s->mb_x + s->mb_y * stride)];

        int16_t *mot_val1 = s->current_picture.motion_val[1][2 * (s->mb_x + s->mb_y * stride)];

//        const int mv_xy= s->mb_x + 1 + s->mb_y * s->mb_stride;



        //FIXME ugly

        mot_val0[0       ]= mot_val0[2       ]= mot_val0[0+2*stride]= mot_val0[2+2*stride]=

        mot_val0[1       ]= mot_val0[3       ]= mot_val0[1+2*stride]= mot_val0[3+2*stride]=

        mot_val1[0       ]= mot_val1[2       ]= mot_val1[0+2*stride]= mot_val1[2+2*stride]=

        mot_val1[1       ]= mot_val1[3       ]= mot_val1[1+2*stride]= mot_val1[3+2*stride]= 0;



        do{

            mb_type= get_vlc2(&s->gb, h263_mbtype_b_vlc.table, H263_MBTYPE_B_VLC_BITS, 2);

            if (mb_type < 0){

                av_log(s->avctx, AV_LOG_ERROR, "b mb_type damaged at %d %d\n", s->mb_x, s->mb_y);

                return -1;

            }



            mb_type= h263_mb_type_b_map[ mb_type ];

        }while(!mb_type);



        s->mb_intra = IS_INTRA(mb_type);

        if(HAS_CBP(mb_type)){

            s->dsp.clear_blocks(s->block[0]);

            cbpc = get_vlc2(&s->gb, cbpc_b_vlc.table, CBPC_B_VLC_BITS, 1);

            if(s->mb_intra){

                dquant = IS_QUANT(mb_type);

                goto intra;

            }



            cbpy = get_vlc2(&s->gb, ff_h263_cbpy_vlc.table, CBPY_VLC_BITS, 1);



            if (cbpy < 0){

                av_log(s->avctx, AV_LOG_ERROR, "b cbpy damaged at %d %d\n", s->mb_x, s->mb_y);

                return -1;

            }



            if(s->alt_inter_vlc==0 || (cbpc & 3)!=3)

                cbpy ^= 0xF;



            cbp = (cbpc & 3) | (cbpy << 2);

        }else

            cbp=0;



        assert(!s->mb_intra);



        if(IS_QUANT(mb_type)){

            h263_decode_dquant(s);

        }



        if(IS_DIRECT(mb_type)){



            s->mv_dir = MV_DIR_FORWARD | MV_DIR_BACKWARD | MV_DIRECT;

            mb_type |= ff_mpeg4_set_direct_mv(s, 0, 0);

        }else{

            s->mv_dir = 0;

            s->mv_type= MV_TYPE_16X16;

//FIXME UMV



            if(USES_LIST(mb_type, 0)){

                int16_t *mot_val= ff_h263_pred_motion(s, 0, 0, &mx, &my);

                s->mv_dir = MV_DIR_FORWARD;



                mx = ff_h263_decode_motion(s, mx, 1);

                my = ff_h263_decode_motion(s, my, 1);



                s->mv[0][0][0] = mx;

                s->mv[0][0][1] = my;

                mot_val[0       ]= mot_val[2       ]= mot_val[0+2*stride]= mot_val[2+2*stride]= mx;

                mot_val[1       ]= mot_val[3       ]= mot_val[1+2*stride]= mot_val[3+2*stride]= my;

            }



            if(USES_LIST(mb_type, 1)){

                int16_t *mot_val= ff_h263_pred_motion(s, 0, 1, &mx, &my);

                s->mv_dir |= MV_DIR_BACKWARD;



                mx = ff_h263_decode_motion(s, mx, 1);

                my = ff_h263_decode_motion(s, my, 1);



                s->mv[1][0][0] = mx;

                s->mv[1][0][1] = my;

                mot_val[0       ]= mot_val[2       ]= mot_val[0+2*stride]= mot_val[2+2*stride]= mx;

                mot_val[1       ]= mot_val[3       ]= mot_val[1+2*stride]= mot_val[3+2*stride]= my;

            }

        }



        s->current_picture.mb_type[xy] = mb_type;

    } else { /* I-Frame */

        do{

            cbpc = get_vlc2(&s->gb, ff_h263_intra_MCBPC_vlc.table, INTRA_MCBPC_VLC_BITS, 2);

            if (cbpc < 0){

                av_log(s->avctx, AV_LOG_ERROR, "I cbpc damaged at %d %d\n", s->mb_x, s->mb_y);

                return -1;

            }

        }while(cbpc == 8);



        s->dsp.clear_blocks(s->block[0]);



        dquant = cbpc & 4;

        s->mb_intra = 1;

intra:

        s->current_picture.mb_type[xy] = MB_TYPE_INTRA;

        if (s->h263_aic) {

            s->ac_pred = get_bits1(&s->gb);

            if(s->ac_pred){

                s->current_picture.mb_type[xy] = MB_TYPE_INTRA | MB_TYPE_ACPRED;



                s->h263_aic_dir = get_bits1(&s->gb);

            }

        }else

            s->ac_pred = 0;



        if(s->pb_frame && get_bits1(&s->gb))

            pb_mv_count = h263_get_modb(&s->gb, s->pb_frame, &cbpb);

        cbpy = get_vlc2(&s->gb, ff_h263_cbpy_vlc.table, CBPY_VLC_BITS, 1);

        if(cbpy<0){

            av_log(s->avctx, AV_LOG_ERROR, "I cbpy damaged at %d %d\n", s->mb_x, s->mb_y);

            return -1;

        }

        cbp = (cbpc & 3) | (cbpy << 2);

        if (dquant) {

            h263_decode_dquant(s);

        }



        pb_mv_count += !!s->pb_frame;

    }



    while(pb_mv_count--){

        ff_h263_decode_motion(s, 0, 1);

        ff_h263_decode_motion(s, 0, 1);

    }



    /* decode each block */

    for (i = 0; i < 6; i++) {

        if (h263_decode_block(s, block[i], i, cbp&32) < 0)

            return -1;

        cbp+=cbp;

    }



    if(s->pb_frame && h263_skip_b_part(s, cbpb) < 0)

        return -1;

    if(s->obmc && !s->mb_intra){

        if(s->pict_type == AV_PICTURE_TYPE_P && s->mb_x+1<s->mb_width && s->mb_num_left != 1)

            preview_obmc(s);

    }

end:



        /* per-MB end of slice check */

    {

        int v= show_bits(&s->gb, 16);



        if (get_bits_left(&s->gb) < 16) {

            v >>= 16 - get_bits_left(&s->gb);

        }



        if(v==0)

            return SLICE_END;

    }



    return SLICE_OK;

}

static uint8_t *read_huffman_tables(FourXContext *f, uint8_t * const buf){

    int frequency[512];

    uint8_t flag[512];

    int up[512];

    uint8_t len_tab[257];

    int bits_tab[257];

    int start, end;

    uint8_t *ptr= buf;

    int j;



    memset(frequency, 0, sizeof(frequency));

    memset(up, -1, sizeof(up));



    start= *ptr++;

    end= *ptr++;

    for(;;){

        int i;



        for(i=start; i<=end; i++){

            frequency[i]= *ptr++;

//            printf("%d %d %d\n", start, end, frequency[i]);

        }

        start= *ptr++;

        if(start==0) break;



        end= *ptr++;

    }

    frequency[256]=1;



    while((ptr - buf)&3) ptr++; // 4byte align 



//    for(j=0; j<16; j++)

//        printf("%2X", ptr[j]);



    for(j=257; j<512; j++){

        int min_freq[2]= {256*256, 256*256};

        int smallest[2]= {0, 0};

        int i;

        for(i=0; i<j; i++){

            if(frequency[i] == 0) continue;

            if(frequency[i] < min_freq[1]){

                if(frequency[i] < min_freq[0]){

                    min_freq[1]= min_freq[0]; smallest[1]= smallest[0];

                    min_freq[0]= frequency[i];smallest[0]= i;

                }else{

                    min_freq[1]= frequency[i];smallest[1]= i;

                }

            }

        }

        if(min_freq[1] == 256*256) break;



        frequency[j]= min_freq[0] + min_freq[1];

        flag[ smallest[0] ]= 0;

        flag[ smallest[1] ]= 1;

        up[ smallest[0] ]= 

        up[ smallest[1] ]= j;

        frequency[ smallest[0] ]= frequency[ smallest[1] ]= 0;

    }



    for(j=0; j<257; j++){

        int node;

        int len=0;

        int bits=0;



        for(node= j; up[node] != -1; node= up[node]){

            bits += flag[node]<<len;

            len++;

            if(len > 31) av_log(f->avctx, AV_LOG_ERROR, "vlc length overflow\n"); //can this happen at all ?

        }



        bits_tab[j]= bits;

        len_tab[j]= len;

    }



    init_vlc(&f->pre_vlc, ACDC_VLC_BITS, 257, 

             len_tab , 1, 1,

             bits_tab, 4, 4);



    return ptr;

}

static int decode_frame_apng(AVCodecContext *avctx,

                        void *data, int *got_frame,

                        AVPacket *avpkt)

{

    PNGDecContext *const s = avctx->priv_data;

    int ret;

    AVFrame *p;



    ff_thread_release_buffer(avctx, &s->last_picture);

    FFSWAP(ThreadFrame, s->picture, s->last_picture);

    p = s->picture.f;



    if (!(s->state & PNG_IHDR)) {

        int side_data_size = 0;

        uint8_t *side_data = NULL;

        if (avpkt)

            side_data = av_packet_get_side_data(avpkt, AV_PKT_DATA_NEW_EXTRADATA, &side_data_size);



        if (side_data_size) {

            av_freep(&s->extra_data);

            s->extra_data = av_mallocz(side_data_size + AV_INPUT_BUFFER_PADDING_SIZE);

            if (!s->extra_data)

                return AVERROR(ENOMEM);

            s->extra_data_size = side_data_size;

            memcpy(s->extra_data, side_data, s->extra_data_size);

        }



        if (!s->extra_data_size)

            return AVERROR_INVALIDDATA;



        /* only init fields, there is no zlib use in extradata */

        s->zstream.zalloc = ff_png_zalloc;

        s->zstream.zfree  = ff_png_zfree;



        bytestream2_init(&s->gb, s->extra_data, s->extra_data_size);

        if ((ret = decode_frame_common(avctx, s, p, avpkt)) < 0)

            goto end;

    }



    /* reset state for a new frame */

    if ((ret = inflateInit(&s->zstream)) != Z_OK) {

        av_log(avctx, AV_LOG_ERROR, "inflateInit returned error %d\n", ret);

        ret = AVERROR_EXTERNAL;

        goto end;

    }

    s->y = 0;

    s->state &= ~(PNG_IDAT | PNG_ALLIMAGE);

    bytestream2_init(&s->gb, avpkt->data, avpkt->size);

    if ((ret = decode_frame_common(avctx, s, p, avpkt)) < 0)

        goto end;



    if (!(s->state & PNG_ALLIMAGE))

        av_log(avctx, AV_LOG_WARNING, "Frame did not contain a complete image\n");

    if (!(s->state & (PNG_ALLIMAGE|PNG_IDAT))) {

        ret = AVERROR_INVALIDDATA;

        goto end;

    }

    if ((ret = av_frame_ref(data, s->picture.f)) < 0)

        goto end;



    *got_frame = 1;

    ret = bytestream2_tell(&s->gb);



end:

    inflateEnd(&s->zstream);

    return ret;

}

static av_always_inline int process_frame(WriterContext *w,

                                          InputFile *ifile,

                                          AVFrame *frame, AVPacket *pkt)

{

    AVFormatContext *fmt_ctx = ifile->fmt_ctx;

    AVCodecContext *dec_ctx = ifile->streams[pkt->stream_index].dec_ctx;

    AVCodecParameters *par = ifile->streams[pkt->stream_index].st->codecpar;

    AVSubtitle sub;

    int ret = 0, got_frame = 0;



    if (dec_ctx->codec) {

        switch (par->codec_type) {

        case AVMEDIA_TYPE_VIDEO:

            ret = avcodec_decode_video2(dec_ctx, frame, &got_frame, pkt);

            break;



        case AVMEDIA_TYPE_AUDIO:

            ret = avcodec_decode_audio4(dec_ctx, frame, &got_frame, pkt);

            break;



        case AVMEDIA_TYPE_SUBTITLE:

            ret = avcodec_decode_subtitle2(dec_ctx, &sub, &got_frame, pkt);

            break;

        }

    }



    if (ret < 0)

        return ret;

    ret = FFMIN(ret, pkt->size); /* guard against bogus return values */

    pkt->data += ret;

    pkt->size -= ret;

    if (got_frame) {

        int is_sub = (par->codec_type == AVMEDIA_TYPE_SUBTITLE);

        nb_streams_frames[pkt->stream_index]++;

        if (do_show_frames)

            if (is_sub)

                show_subtitle(w, &sub, ifile->streams[pkt->stream_index].st, fmt_ctx);

            else

                show_frame(w, frame, ifile->streams[pkt->stream_index].st, fmt_ctx);

        if (is_sub)

            avsubtitle_free(&sub);

    }

    return got_frame;

}

static int mov_read_stsd(MOVContext *c, AVIOContext *pb, MOVAtom atom)

{

    AVStream *st;

    MOVStreamContext *sc;

    int ret;



    if (c->fc->nb_streams < 1)

        return 0;

    st = c->fc->streams[c->fc->nb_streams - 1];

    sc = st->priv_data;



    avio_r8(pb); /* version */

    avio_rb24(pb); /* flags */

    sc->stsd_count = avio_rb32(pb); /* entries */



    /* Prepare space for hosting multiple extradata. */

    sc->extradata = av_mallocz_array(sc->stsd_count, sizeof(*sc->extradata));

    if (!sc->extradata)

        return AVERROR(ENOMEM);



    sc->extradata_size = av_mallocz_array(sc->stsd_count, sizeof(*sc->extradata_size));

    if (!sc->extradata_size)

        return AVERROR(ENOMEM);



    ret = ff_mov_read_stsd_entries(c, pb, sc->stsd_count);

    if (ret < 0)

        return ret;



    /* Restore back the primary extradata. */

    av_freep(&st->codecpar->extradata);

    st->codecpar->extradata_size = sc->extradata_size[0];

    if (sc->extradata_size[0]) {

        st->codecpar->extradata = av_mallocz(sc->extradata_size[0] + AV_INPUT_BUFFER_PADDING_SIZE);

        if (!st->codecpar->extradata)

            return AVERROR(ENOMEM);

        memcpy(st->codecpar->extradata, sc->extradata[0], sc->extradata_size[0]);

    }



    return 0;

}

static void implicit_weight_table(H264Context *h){

    MpegEncContext * const s = &h->s;

    int ref0, ref1, i;

    int cur_poc = s->current_picture_ptr->poc;



    if(   h->ref_count[0] == 1 && h->ref_count[1] == 1

       && h->ref_list[0][0].poc + h->ref_list[1][0].poc == 2*cur_poc){

        h->use_weight= 0;

        h->use_weight_chroma= 0;

        return;

    }



    h->use_weight= 2;

    h->use_weight_chroma= 2;

    h->luma_log2_weight_denom= 5;

    h->chroma_log2_weight_denom= 5;

    for (i = 0; i < 2; i++) {

        h->luma_weight_flag[i]   = 0;

        h->chroma_weight_flag[i] = 0;

    }



    for(ref0=0; ref0 < h->ref_count[0]; ref0++){

        int poc0 = h->ref_list[0][ref0].poc;

        for(ref1=0; ref1 < h->ref_count[1]; ref1++){

            int poc1 = h->ref_list[1][ref1].poc;

            int td = av_clip(poc1 - poc0, -128, 127);

            if(td){

                int tb = av_clip(cur_poc - poc0, -128, 127);

                int tx = (16384 + (FFABS(td) >> 1)) / td;

                int dist_scale_factor = av_clip((tb*tx + 32) >> 6, -1024, 1023) >> 2;

                if(dist_scale_factor < -64 || dist_scale_factor > 128)

                    h->implicit_weight[ref0][ref1] = 32;

                else

                    h->implicit_weight[ref0][ref1] = 64 - dist_scale_factor;

            }else

                h->implicit_weight[ref0][ref1] = 32;

        }

    }

}

static av_cold int ra144_encode_init(AVCodecContext * avctx)

{

