error:

    ra144_encode_close(avctx);

    return ret;

}

static int mxf_read_generic_descriptor(void *arg, AVIOContext *pb, int tag, int size, UID uid, int64_t klv_offset)

{

    MXFDescriptor *descriptor = arg;

    descriptor->pix_fmt = AV_PIX_FMT_NONE;

    switch(tag) {

    case 0x3F01:

        descriptor->sub_descriptors_count = avio_rb32(pb);

        if (descriptor->sub_descriptors_count >= UINT_MAX / sizeof(UID))

            return AVERROR_INVALIDDATA;

        descriptor->sub_descriptors_refs = av_malloc(descriptor->sub_descriptors_count * sizeof(UID));

        if (!descriptor->sub_descriptors_refs)

            return AVERROR(ENOMEM);

        avio_skip(pb, 4); /* useless size of objects, always 16 according to specs */

        avio_read(pb, (uint8_t *)descriptor->sub_descriptors_refs, descriptor->sub_descriptors_count * sizeof(UID));

        break;

    case 0x3004:

        avio_read(pb, descriptor->essence_container_ul, 16);

        break;

    case 0x3006:

        descriptor->linked_track_id = avio_rb32(pb);

        break;

    case 0x3201: /* PictureEssenceCoding */

        avio_read(pb, descriptor->essence_codec_ul, 16);

        break;

    case 0x3203:

        descriptor->width = avio_rb32(pb);

        break;

    case 0x3202:

        descriptor->height = avio_rb32(pb);

        break;

    case 0x320C:

        descriptor->frame_layout = avio_r8(pb);

        break;

    case 0x320E:

        descriptor->aspect_ratio.num = avio_rb32(pb);

        descriptor->aspect_ratio.den = avio_rb32(pb);

        break;

    case 0x3301:

        descriptor->component_depth = avio_rb32(pb);

        break;

    case 0x3302:

        descriptor->horiz_subsampling = avio_rb32(pb);

        break;

    case 0x3308:

        descriptor->vert_subsampling = avio_rb32(pb);

        break;

    case 0x3D03:

        descriptor->sample_rate.num = avio_rb32(pb);

        descriptor->sample_rate.den = avio_rb32(pb);

        break;

    case 0x3D06: /* SoundEssenceCompression */

        avio_read(pb, descriptor->essence_codec_ul, 16);

        break;

    case 0x3D07:

        descriptor->channels = avio_rb32(pb);

        break;

    case 0x3D01:

        descriptor->bits_per_sample = avio_rb32(pb);

        break;

    case 0x3401:

        mxf_read_pixel_layout(pb, descriptor);

        break;

    default:

        /* Private uid used by SONY C0023S01.mxf */

        if (IS_KLV_KEY(uid, mxf_sony_mpeg4_extradata)) {



            descriptor->extradata = av_malloc(size + FF_INPUT_BUFFER_PADDING_SIZE);

            if (!descriptor->extradata)

                return AVERROR(ENOMEM);

            descriptor->extradata_size = size;

            avio_read(pb, descriptor->extradata, size);

        }

        break;

    }

    return 0;

}

int64_t ff_ape_parse_tag(AVFormatContext *s)

{

    AVIOContext *pb = s->pb;

    int file_size = avio_size(pb);

    uint32_t val, fields, tag_bytes;

    uint8_t buf[8];

    int64_t tag_start;

    int i;



    if (file_size < APE_TAG_FOOTER_BYTES)

        return 0;



    avio_seek(pb, file_size - APE_TAG_FOOTER_BYTES, SEEK_SET);



    avio_read(pb, buf, 8);     /* APETAGEX */

    if (strncmp(buf, "APETAGEX", 8)) {

        return 0;

    }



    val = avio_rl32(pb);       /* APE tag version */

    if (val > APE_TAG_VERSION) {

        av_log(s, AV_LOG_ERROR, "Unsupported tag version. (>=%d)\n", APE_TAG_VERSION);

        return 0;

    }



    tag_bytes = avio_rl32(pb); /* tag size */

    if (tag_bytes - APE_TAG_FOOTER_BYTES > (1024 * 1024 * 16)) {

        av_log(s, AV_LOG_ERROR, "Tag size is way too big\n");

        return 0;

    }



    tag_start = file_size - tag_bytes - APE_TAG_FOOTER_BYTES;

    if (tag_start < 0) {

        av_log(s, AV_LOG_ERROR, "Invalid tag size %u.\n", tag_bytes);

        return 0;

    }



    fields = avio_rl32(pb);    /* number of fields */

    if (fields > 65536) {

        av_log(s, AV_LOG_ERROR, "Too many tag fields (%d)\n", fields);

        return 0;

    }



    val = avio_rl32(pb);       /* flags */

    if (val & APE_TAG_FLAG_IS_HEADER) {

        av_log(s, AV_LOG_ERROR, "APE Tag is a header\n");

        return 0;

    }



    avio_seek(pb, file_size - tag_bytes, SEEK_SET);



    for (i=0; i<fields; i++)

        if (ape_tag_read_field(s) < 0) break;



    return tag_start;

}

static void* attribute_align_arg worker(void *v)

{

    ThreadContext *c = v;

    int our_job      = c->nb_jobs;

    int nb_threads   = c->nb_threads;

    unsigned int last_execute = 0;

    int self_id;



    pthread_mutex_lock(&c->current_job_lock);

    self_id = c->current_job++;

    for (;;) {

        while (our_job >= c->nb_jobs) {

            if (c->current_job == nb_threads + c->nb_jobs)

                pthread_cond_signal(&c->last_job_cond);



            while (last_execute == c->current_execute && !c->done)

                pthread_cond_wait(&c->current_job_cond, &c->current_job_lock);

            last_execute = c->current_execute;

            our_job = self_id;



            if (c->done) {

                pthread_mutex_unlock(&c->current_job_lock);

                return NULL;

            }

        }

        pthread_mutex_unlock(&c->current_job_lock);



        c->rets[our_job % c->nb_rets] = c->func(c->ctx, c->arg, our_job, c->nb_jobs);



        pthread_mutex_lock(&c->current_job_lock);

        our_job = c->current_job++;

    }

}

static int mkv_field_order(MatroskaDemuxContext *matroska, int64_t field_order)

{

    int major, minor, micro, bttb = 0;



    /* workaround a bug in our Matroska muxer, introduced in version 57.36 alongside

     * this function, and fixed in 57.52 */

    if (sscanf(matroska->muxingapp, "Lavf%d.%d.%d", &major, &minor, &micro) == 3)

        bttb = (major == 57 && minor >= 36 && minor <= 51 && micro >= 100);



    switch (field_order) {

    case MATROSKA_VIDEO_FIELDORDER_PROGRESSIVE:

        return AV_FIELD_PROGRESSIVE;

    case MATROSKA_VIDEO_FIELDORDER_UNDETERMINED:

        return AV_FIELD_UNKNOWN;

    case MATROSKA_VIDEO_FIELDORDER_TT:

        return AV_FIELD_TT;

    case MATROSKA_VIDEO_FIELDORDER_BB:

        return AV_FIELD_BB;

    case MATROSKA_VIDEO_FIELDORDER_BT:

        return bttb ? AV_FIELD_TB : AV_FIELD_BT;

    case MATROSKA_VIDEO_FIELDORDER_TB:

        return bttb ? AV_FIELD_BT : AV_FIELD_TB;

    default:

        return AV_FIELD_UNKNOWN;

    }

}

