static int rv10_decode_picture_header(MpegEncContext *s)

{

    int mb_count, pb_frame, marker, h, full_frame;



    /* skip packet header */

    h = get_bits(&s->gb, 8);

    if ((h & 0xc0) == 0xc0) {

        int len, pos;

        full_frame = 1;

        len = get_num(&s->gb);

        pos = get_num(&s->gb);

    } else {

        int seq, frame_size, pos;

        full_frame = 0;

        seq = get_bits(&s->gb, 8);

        frame_size = get_num(&s->gb);

        pos = get_num(&s->gb);

    }

    /* picture number */

    get_bits(&s->gb, 8);



    marker = get_bits(&s->gb, 1);



    if (get_bits(&s->gb, 1))

        s->pict_type = P_TYPE;

    else

        s->pict_type = I_TYPE;



    pb_frame = get_bits(&s->gb, 1);



#ifdef DEBUG

    printf("pict_type=%d pb_frame=%d\n", s->pict_type, pb_frame);

#endif



    if (pb_frame)

        return -1;



    s->qscale = get_bits(&s->gb, 5);



    if (s->pict_type == I_TYPE) {

        if (s->rv10_version == 3) {

            /* specific MPEG like DC coding not used */

            s->last_dc[0] = get_bits(&s->gb, 8);

            s->last_dc[1] = get_bits(&s->gb, 8);

            s->last_dc[2] = get_bits(&s->gb, 8);

#ifdef DEBUG

            printf("DC:%d %d %d\n",

                   s->last_dc[0],

                   s->last_dc[1],

                   s->last_dc[2]);

#endif

        }

    }

    /* if multiple packets per frame are sent, the position at which

       to display the macro blocks is coded here */

    if (!full_frame) {

        s->mb_x = get_bits(&s->gb, 6);	/* mb_x */

        s->mb_y = get_bits(&s->gb, 6);	/* mb_y */

        mb_count = get_bits(&s->gb, 12);

    } else {

        s->mb_x = 0;

        s->mb_y = 0;

        mb_count = s->mb_width * s->mb_height;

    }



    get_bits(&s->gb, 3);	/* ignored */

    s->f_code = 1;

    s->unrestricted_mv = 1;

#if 0

    s->h263_long_vectors = 1;

#endif

    return mb_count;

}

static int v4l2_read_header(AVFormatContext *s1)

{

    struct video_data *s = s1->priv_data;

    AVStream *st;

    int res = 0;

    uint32_t desired_format;

    enum AVCodecID codec_id = AV_CODEC_ID_NONE;

    enum AVPixelFormat pix_fmt = AV_PIX_FMT_NONE;

    struct v4l2_input input = { 0 };



    st = avformat_new_stream(s1, NULL);

    if (!st)

        return AVERROR(ENOMEM);



#if CONFIG_LIBV4L2

    /* silence libv4l2 logging. if fopen() fails v4l2_log_file will be NULL

       and errors will get sent to stderr */

    v4l2_log_file = fopen("/dev/null", "w");

#endif



    s->fd = device_open(s1);

    if (s->fd < 0)

        return s->fd;



    if (s->channel != -1) {

        /* set video input */

        av_log(s1, AV_LOG_DEBUG, "Selecting input_channel: %d\n", s->channel);

        if (v4l2_ioctl(s->fd, VIDIOC_S_INPUT, &s->channel) < 0) {

            res = AVERROR(errno);

            av_log(s1, AV_LOG_ERROR, "ioctl(VIDIOC_S_INPUT): %s\n", av_err2str(res));

            return res;

        }

    } else {

        /* get current video input */

        if (v4l2_ioctl(s->fd, VIDIOC_G_INPUT, &s->channel) < 0) {

            res = AVERROR(errno);

            av_log(s1, AV_LOG_ERROR, "ioctl(VIDIOC_G_INPUT): %s\n", av_err2str(res));

            return res;

        }

    }



    /* enum input */

    input.index = s->channel;

    if (v4l2_ioctl(s->fd, VIDIOC_ENUMINPUT, &input) < 0) {

        res = AVERROR(errno);

        av_log(s1, AV_LOG_ERROR, "ioctl(VIDIOC_ENUMINPUT): %s\n", av_err2str(res));

        return res;

    }

    s->std_id = input.std;

    av_log(s1, AV_LOG_DEBUG, "Current input_channel: %d, input_name: %s\n",

           s->channel, input.name);



    if (s->list_format) {

        list_formats(s1, s->fd, s->list_format);

        return AVERROR_EXIT;

    }



    if (s->list_standard) {

        list_standards(s1);

        return AVERROR_EXIT;

    }



    avpriv_set_pts_info(st, 64, 1, 1000000); /* 64 bits pts in us */



    if (s->pixel_format) {

        AVCodec *codec = avcodec_find_decoder_by_name(s->pixel_format);



        if (codec)

            s1->video_codec_id = codec->id;



        pix_fmt = av_get_pix_fmt(s->pixel_format);



        if (pix_fmt == AV_PIX_FMT_NONE && !codec) {

            av_log(s1, AV_LOG_ERROR, "No such input format: %s.\n",

                   s->pixel_format);



            return AVERROR(EINVAL);

        }

    }



    if (!s->width && !s->height) {

        struct v4l2_format fmt;



        av_log(s1, AV_LOG_VERBOSE,

               "Querying the device for the current frame size\n");

        fmt.type = V4L2_BUF_TYPE_VIDEO_CAPTURE;

        if (v4l2_ioctl(s->fd, VIDIOC_G_FMT, &fmt) < 0) {

            res = AVERROR(errno);

            av_log(s1, AV_LOG_ERROR, "ioctl(VIDIOC_G_FMT): %s\n", av_err2str(res));

            return res;

        }



        s->width  = fmt.fmt.pix.width;

        s->height = fmt.fmt.pix.height;

        av_log(s1, AV_LOG_VERBOSE,

               "Setting frame size to %dx%d\n", s->width, s->height);

    }



    res = device_try_init(s1, pix_fmt, &s->width, &s->height, &desired_format, &codec_id);

    if (res < 0) {

        v4l2_close(s->fd);

        return res;

    }



    /* If no pixel_format was specified, the codec_id was not known up

     * until now. Set video_codec_id in the context, as codec_id will

     * not be available outside this function

     */

    if (codec_id != AV_CODEC_ID_NONE && s1->video_codec_id == AV_CODEC_ID_NONE)

        s1->video_codec_id = codec_id;



    if ((res = av_image_check_size(s->width, s->height, 0, s1)) < 0)

        return res;



    s->frame_format = desired_format;



    if ((res = v4l2_set_parameters(s1)) < 0)

        return res;



    st->codec->pix_fmt = fmt_v4l2ff(desired_format, codec_id);

    s->frame_size =

        avpicture_get_size(st->codec->pix_fmt, s->width, s->height);



    if ((res = mmap_init(s1)) ||

        (res = mmap_start(s1)) < 0) {

        v4l2_close(s->fd);

        return res;

    }



    s->top_field_first = first_field(s->fd);



    st->codec->codec_type = AVMEDIA_TYPE_VIDEO;

    st->codec->codec_id = codec_id;

    if (codec_id == AV_CODEC_ID_RAWVIDEO)

        st->codec->codec_tag =

            avcodec_pix_fmt_to_codec_tag(st->codec->pix_fmt);

    if (desired_format == V4L2_PIX_FMT_YVU420)

        st->codec->codec_tag = MKTAG('Y', 'V', '1', '2');

    else if (desired_format == V4L2_PIX_FMT_YVU410)

        st->codec->codec_tag = MKTAG('Y', 'V', 'U', '9');

    st->codec->width = s->width;

    st->codec->height = s->height;

    st->codec->bit_rate = s->frame_size * av_q2d(st->avg_frame_rate) * 8;



    return 0;

}

avfilter_get_video_buffer_ref_from_arrays(uint8_t *data[4], int linesize[4], int perms,

                                          int w, int h, enum PixelFormat format)

{

    AVFilterBuffer *pic = av_mallocz(sizeof(AVFilterBuffer));

    AVFilterBufferRef *picref = av_mallocz(sizeof(AVFilterBufferRef));



    if (!pic || !picref)

        goto fail;



    picref->buf = pic;

    picref->buf->free = ff_avfilter_default_free_buffer;

    if (!(picref->video = av_mallocz(sizeof(AVFilterBufferRefVideoProps))))

        goto fail;



    picref->video->w = w;

    picref->video->h = h;



    /* make sure the buffer gets read permission or it's useless for output */

    picref->perms = perms | AV_PERM_READ;



    pic->refcount = 1;

    picref->type = AVMEDIA_TYPE_VIDEO;

    picref->format = format;



    memcpy(pic->data,        data,          sizeof(pic->data));

    memcpy(pic->linesize,    linesize,      sizeof(pic->linesize));

    memcpy(picref->data,     pic->data,     sizeof(picref->data));

    memcpy(picref->linesize, pic->linesize, sizeof(picref->linesize));



    return picref;



fail:

    if (picref && picref->video)

        av_free(picref->video);

    av_free(picref);

    av_free(pic);

    return NULL;

}

static int dca_decode_frame(AVCodecContext * avctx,
                            void *data, int *data_size,
                            AVPacket *avpkt)
{
    const uint8_t *buf = avpkt->data;
    int buf_size = avpkt->size;
    int i;
    int16_t *samples = data;
    DCAContext *s = avctx->priv_data;
    int channels;
    s->dca_buffer_size = dca_convert_bitstream(buf, buf_size, s->dca_buffer, DCA_MAX_FRAME_SIZE);
    if (s->dca_buffer_size == -1) {
        av_log(avctx, AV_LOG_ERROR, "Not a valid DCA frame\n");
    }
    init_get_bits(&s->gb, s->dca_buffer, s->dca_buffer_size * 8);
    if (dca_parse_frame_header(s) < 0) {
        //seems like the frame is corrupt, try with the next one
        *data_size=0;
        return buf_size;
    }
    //set AVCodec values with parsed data
    avctx->sample_rate = s->sample_rate;
    avctx->bit_rate = s->bit_rate;
    channels = s->prim_channels + !!s->lfe;
    if (s->amode<16) {
        avctx->channel_layout = dca_core_channel_layout[s->amode];
        if (s->lfe) {
            avctx->channel_layout |= CH_LOW_FREQUENCY;
            s->channel_order_tab = dca_channel_reorder_lfe[s->amode];
        } else
            s->channel_order_tab = dca_channel_reorder_nolfe[s->amode];
        if(avctx->request_channels == 2 && s->prim_channels > 2) {
            channels = 2;
            s->output = DCA_STEREO;
            avctx->channel_layout = CH_LAYOUT_STEREO;
        }
    } else {
        av_log(avctx, AV_LOG_ERROR, "Non standard configuration %d !\n",s->amode);
    }
    /* There is nothing that prevents a dts frame to change channel configuration
       but FFmpeg doesn't support that so only set the channels if it is previously
       unset. Ideally during the first probe for channels the crc should be checked
       and only set avctx->channels when the crc is ok. Right now the decoder could
       set the channels based on a broken first frame.*/
    if (!avctx->channels)
        avctx->channels = channels;
    if(*data_size < (s->sample_blocks / 8) * 256 * sizeof(int16_t) * channels)
    *data_size = 256 / 8 * s->sample_blocks * sizeof(int16_t) * channels;
    for (i = 0; i < (s->sample_blocks / 8); i++) {
        dca_decode_block(s);
        s->dsp.float_to_int16_interleave(samples, s->samples_chanptr, 256, channels);
        samples += 256 * channels;
    }
    return buf_size;
}

static int opus_packet(AVFormatContext *avf, int idx)

{

    struct ogg *ogg              = avf->priv_data;

    struct ogg_stream *os        = &ogg->streams[idx];

    AVStream *st                 = avf->streams[idx];

    struct oggopus_private *priv = os->private;

    uint8_t *packet              = os->buf + os->pstart;

    int ret;



    if (!os->psize)

        return AVERROR_INVALIDDATA;

    if (os->granule > INT64_MAX - UINT32_MAX) {

        av_log(avf, AV_LOG_ERROR, "Unsupported huge granule pos %"PRId64 "\n", os->granule);

        return AVERROR_INVALIDDATA;

    }



    if ((!os->lastpts || os->lastpts == AV_NOPTS_VALUE) && !(os->flags & OGG_FLAG_EOS)) {

        int seg, d;

        int duration;

        uint8_t *last_pkt  = os->buf + os->pstart;

        uint8_t *next_pkt  = last_pkt;



        duration = 0;

        seg = os->segp;

        d = opus_duration(last_pkt, os->psize);

        if (d < 0) {

            os->pflags |= AV_PKT_FLAG_CORRUPT;

            return 0;

        }

        duration += d;

        last_pkt = next_pkt =  next_pkt + os->psize;

        for (; seg < os->nsegs; seg++) {

            next_pkt += os->segments[seg];

            if (os->segments[seg] < 255 && next_pkt != last_pkt) {

                int d = opus_duration(last_pkt, next_pkt - last_pkt);

                if (d > 0)

                    duration += d;

                last_pkt = next_pkt;

            }

        }

        os->lastpts                 =

        os->lastdts                 = os->granule - duration;

    }



    if ((ret = opus_duration(packet, os->psize)) < 0)

        return ret;



    os->pduration = ret;

    if (os->lastpts != AV_NOPTS_VALUE) {

        if (st->start_time == AV_NOPTS_VALUE)

            st->start_time = os->lastpts;

        priv->cur_dts = os->lastdts = os->lastpts -= priv->pre_skip;

    }



    priv->cur_dts += os->pduration;

    if ((os->flags & OGG_FLAG_EOS)) {

        int64_t skip = priv->cur_dts - os->granule + priv->pre_skip;

        skip = FFMIN(skip, os->pduration);

        if (skip > 0) {

            os->pduration = skip < os->pduration ? os->pduration - skip : 1;

            os->end_trimming = skip;

            av_log(avf, AV_LOG_DEBUG,

                   "Last packet was truncated to %d due to end trimming.\n",

                   os->pduration);

        }

    }



    return 0;

}

static unsigned int mszh_decomp(unsigned char * srcptr, int srclen, unsigned char * destptr, unsigned int destsize)

{

    unsigned char *destptr_bak = destptr;

    unsigned char *destptr_end = destptr + destsize;

    unsigned char mask = 0;

    unsigned char maskbit = 0;

    unsigned int ofs, cnt;



    while (srclen > 0 && destptr < destptr_end) {

        if (maskbit == 0) {

            mask = *srcptr++;

            maskbit = 8;

            srclen--;

            continue;

        }

        if ((mask & (1 << (--maskbit))) == 0) {

            if (destptr + 4 > destptr_end)

                break;

            memcpy(destptr, srcptr, 4);

            srclen -= 4;

            destptr += 4;

            srcptr += 4;

        } else {

            ofs = *srcptr++;

            cnt = *srcptr++;

            ofs += cnt * 256;

            cnt = ((cnt >> 3) & 0x1f) + 1;

            ofs &= 0x7ff;

            srclen -= 2;

            cnt *= 4;

            if (destptr + cnt > destptr_end) {

                cnt =  destptr_end - destptr;

            }

            for (; cnt > 0; cnt--) {

                *destptr = *(destptr - ofs);

                destptr++;

            }

        }

    }



    return destptr - destptr_bak;

}

static int decode_codestream(Jpeg2000DecoderContext *s)

{

    Jpeg2000CodingStyle *codsty = s->codsty;

    Jpeg2000QuantStyle  *qntsty = s->qntsty;

    uint8_t *properties = s->properties;



    for (;;){

        int oldpos, marker, len, ret = 0;



        if (bytestream2_get_bytes_left(&s->g) < 2) {

            av_log(s->avctx, AV_LOG_ERROR, "Missing EOC\n");

            break;

        }



        marker = bytestream2_get_be16u(&s->g);

        av_dlog(s->avctx, "marker 0x%.4X at pos 0x%x\n", marker, bytestream2_tell(&s->g) - 4);

        oldpos = bytestream2_tell(&s->g);



        if (marker == JPEG2000_SOD){

            Jpeg2000Tile *tile = s->tile + s->curtileno;

            if (ret = init_tile(s, s->curtileno)) {

                av_log(s->avctx, AV_LOG_ERROR, "tile initialization failed\n");

                return ret;

            }

            if (ret = jpeg2000_decode_packets(s, tile)) {

                av_log(s->avctx, AV_LOG_ERROR, "packets decoding failed\n");

                return ret;

            }

            continue;

        }

        if (marker == JPEG2000_EOC)

            break;



        if (bytestream2_get_bytes_left(&s->g) < 2)

            return AVERROR(EINVAL);

        len = bytestream2_get_be16u(&s->g);

        switch (marker){

        case JPEG2000_SIZ:

            ret = get_siz(s);



            break;

        case JPEG2000_COC:

            ret = get_coc(s, codsty, properties);

            break;

        case JPEG2000_COD:

            ret = get_cod(s, codsty, properties);

            break;

        case JPEG2000_QCC:

            ret = get_qcc(s, len, qntsty, properties);

            break;

        case JPEG2000_QCD:

            ret = get_qcd(s, len, qntsty, properties);

            break;

        case JPEG2000_SOT:

            if (!(ret = get_sot(s))){

                codsty = s->tile[s->curtileno].codsty;

                qntsty = s->tile[s->curtileno].qntsty;

                properties = s->tile[s->curtileno].properties;

            }

            break;

        case JPEG2000_COM:

            // the comment is ignored

            bytestream2_skip(&s->g, len - 2);

            break;

        default:

            av_log(s->avctx, AV_LOG_ERROR, "unsupported marker 0x%.4X at pos 0x%x\n", marker, bytestream2_tell(&s->g) - 4);

            bytestream2_skip(&s->g, len - 2);

            break;

        }

        if (bytestream2_tell(&s->g) - oldpos != len || ret){

            av_log(s->avctx, AV_LOG_ERROR, "error during processing marker segment %.4x\n", marker);

            return ret ? ret : -1;

        }

    }

    return 0;

}

static int decode_unit(SCPRContext *s, PixelModel *pixel, unsigned step, unsigned *rval)

{

    GetByteContext *gb = &s->gb;

    RangeCoder *rc = &s->rc;

    unsigned totfr = pixel->total_freq;

    unsigned value, x = 0, cumfr = 0, cnt_x = 0;

    int i, j, ret, c, cnt_c;



    if ((ret = s->get_freq(rc, totfr, &value)) < 0)

        return ret;



    while (x < 16) {

        cnt_x = pixel->lookup[x];

        if (value >= cumfr + cnt_x)

            cumfr += cnt_x;

        else

            break;

        x++;

    }



    c = x * 16;

    cnt_c = 0;

    while (c < 256) {

        cnt_c = pixel->freq[c];

        if (value >= cumfr + cnt_c)

            cumfr += cnt_c;

        else

            break;

        c++;

    }

    s->decode(gb, rc, cumfr, cnt_c, totfr);

    pixel->freq[c] = cnt_c + step;

    pixel->lookup[x] = cnt_x + step;

    totfr += step;

    if (totfr > BOT) {

        totfr = 0;

        for (i = 0; i < 256; i++) {

            unsigned nc = (pixel->freq[i] >> 1) + 1;

            pixel->freq[i] = nc;

            totfr += nc;

        }

        for (i = 0; i < 16; i++) {

            unsigned sum = 0;

            unsigned i16_17 = i << 4;

            for (j = 0; j < 16; j++)

                sum += pixel->freq[i16_17 + j];

            pixel->lookup[i] = sum;

        }

    }

    pixel->total_freq = totfr;



    *rval = c & s->cbits;



    return 0;

}

static void sbr_env_estimate(float (*e_curr)[48], float X_high[64][40][2],

                             SpectralBandReplication *sbr, SBRData *ch_data)

{

    int e, i, m;



    if (sbr->bs_interpol_freq) {

        for (e = 0; e < ch_data->bs_num_env; e++) {

            const float recip_env_size = 0.5f / (ch_data->t_env[e + 1] - ch_data->t_env[e]);

            int ilb = ch_data->t_env[e]     * 2 + ENVELOPE_ADJUSTMENT_OFFSET;

            int iub = ch_data->t_env[e + 1] * 2 + ENVELOPE_ADJUSTMENT_OFFSET;



            for (m = 0; m < sbr->m[1]; m++) {

                float sum = 0.0f;



                for (i = ilb; i < iub; i++) {

                    sum += X_high[m + sbr->kx[1]][i][0] * X_high[m + sbr->kx[1]][i][0] +

                           X_high[m + sbr->kx[1]][i][1] * X_high[m + sbr->kx[1]][i][1];

                }

                e_curr[e][m] = sum * recip_env_size;

            }

        }

    } else {

        int k, p;



        for (e = 0; e < ch_data->bs_num_env; e++) {

            const int env_size = 2 * (ch_data->t_env[e + 1] - ch_data->t_env[e]);

            int ilb = ch_data->t_env[e]     * 2 + ENVELOPE_ADJUSTMENT_OFFSET;

            int iub = ch_data->t_env[e + 1] * 2 + ENVELOPE_ADJUSTMENT_OFFSET;

            const uint16_t *table = ch_data->bs_freq_res[e + 1] ? sbr->f_tablehigh : sbr->f_tablelow;



            for (p = 0; p < sbr->n[ch_data->bs_freq_res[e + 1]]; p++) {

                float sum = 0.0f;

                const int den = env_size * (table[p + 1] - table[p]);



                for (k = table[p]; k < table[p + 1]; k++) {

                    for (i = ilb; i < iub; i++) {

                        sum += X_high[k][i][0] * X_high[k][i][0] +

                               X_high[k][i][1] * X_high[k][i][1];

                    }

                }

                sum /= den;

                for (k = table[p]; k < table[p + 1]; k++) {

                    e_curr[e][k - sbr->kx[1]] = sum;

                }

            }

        }

    }

}

