static int sp5x_decode_frame(AVCodecContext *avctx,

                              void *data, int *data_size,

                              AVPacket *avpkt)

{

    const uint8_t *buf = avpkt->data;

    int buf_size = avpkt->size;

    AVPacket avpkt_recoded;

    const int qscale = 5;

    const uint8_t *buf_ptr;

    uint8_t *recoded;

    int i = 0, j = 0;



    if (!avctx->width || !avctx->height)

        return -1;



    buf_ptr = buf;



    recoded = av_mallocz(buf_size + 1024);

    if (!recoded)

        return -1;



    /* SOI */

    recoded[j++] = 0xFF;

    recoded[j++] = 0xD8;



    memcpy(recoded+j, &sp5x_data_dqt[0], sizeof(sp5x_data_dqt));

    memcpy(recoded+j+5, &sp5x_quant_table[qscale * 2], 64);

    memcpy(recoded+j+70, &sp5x_quant_table[(qscale * 2) + 1], 64);

    j += sizeof(sp5x_data_dqt);



    memcpy(recoded+j, &sp5x_data_dht[0], sizeof(sp5x_data_dht));

    j += sizeof(sp5x_data_dht);



    memcpy(recoded+j, &sp5x_data_sof[0], sizeof(sp5x_data_sof));

    AV_WB16(recoded+j+5, avctx->coded_height);

    AV_WB16(recoded+j+7, avctx->coded_width);

    j += sizeof(sp5x_data_sof);



    memcpy(recoded+j, &sp5x_data_sos[0], sizeof(sp5x_data_sos));

    j += sizeof(sp5x_data_sos);



    if(avctx->codec_id==CODEC_ID_AMV)

        for (i = 2; i < buf_size-2 && j < buf_size+1024-2; i++)

            recoded[j++] = buf[i];

    else

    for (i = 14; i < buf_size && j < buf_size+1024-2; i++)

    {

        recoded[j++] = buf[i];

        if (buf[i] == 0xff)

            recoded[j++] = 0;

    }



    /* EOI */

    recoded[j++] = 0xFF;

    recoded[j++] = 0xD9;



    avctx->flags &= ~CODEC_FLAG_EMU_EDGE;

    av_init_packet(&avpkt_recoded);

    avpkt_recoded.data = recoded;

    avpkt_recoded.size = j;

    i = ff_mjpeg_decode_frame(avctx, data, data_size, &avpkt_recoded);



    av_free(recoded);



    return i;

}

static int vorbis_parse_setup_hdr_modes(vorbis_context *vc) {

    GetBitContext *gb=&vc->gb;

    uint_fast8_t i;



    vc->mode_count=get_bits(gb, 6)+1;

    vc->modes=av_mallocz(vc->mode_count * sizeof(vorbis_mode));



    AV_DEBUG(" There are %d modes.\n", vc->mode_count);



    for(i=0;i<vc->mode_count;++i) {

        vorbis_mode *mode_setup=&vc->modes[i];



        mode_setup->blockflag=get_bits1(gb);

        mode_setup->windowtype=get_bits(gb, 16); //FIXME check

        mode_setup->transformtype=get_bits(gb, 16); //FIXME check

        mode_setup->mapping=get_bits(gb, 8); //FIXME check



        AV_DEBUG(" %d mode: blockflag %d, windowtype %d, transformtype %d, mapping %d \n", i, mode_setup->blockflag, mode_setup->windowtype, mode_setup->transformtype, mode_setup->mapping);

    }

    return 0;

}

static int smka_decode_frame(AVCodecContext *avctx, void *data,

                             int *got_frame_ptr, AVPacket *avpkt)

{

    AVFrame *frame     = data;

    const uint8_t *buf = avpkt->data;

    int buf_size = avpkt->size;

    GetBitContext gb;

    HuffContext h[4] = { { 0 } };

    VLC vlc[4]       = { { 0 } };

    int16_t *samples;

    uint8_t *samples8;

    int val;

    int i, res, ret;

    int unp_size;

    int bits, stereo;

    int pred[2] = {0, 0};



    if (buf_size <= 4) {

        av_log(avctx, AV_LOG_ERROR, "packet is too small\n");

        return AVERROR(EINVAL);

    }



    unp_size = AV_RL32(buf);



    init_get_bits(&gb, buf + 4, (buf_size - 4) * 8);



    if(!get_bits1(&gb)){

        av_log(avctx, AV_LOG_INFO, "Sound: no data\n");

        *got_frame_ptr = 0;

        return 1;

    }

    stereo = get_bits1(&gb);

    bits = get_bits1(&gb);

    if (stereo ^ (avctx->channels != 1)) {

        av_log(avctx, AV_LOG_ERROR, "channels mismatch\n");

        return AVERROR(EINVAL);

    }

    if (bits && avctx->sample_fmt == AV_SAMPLE_FMT_U8) {

        av_log(avctx, AV_LOG_ERROR, "sample format mismatch\n");

        return AVERROR(EINVAL);

    }



    /* get output buffer */

    frame->nb_samples = unp_size / (avctx->channels * (bits + 1));

    if ((ret = ff_get_buffer(avctx, frame, 0)) < 0) {

        av_log(avctx, AV_LOG_ERROR, "get_buffer() failed\n");

        return ret;

    }

    samples  = (int16_t *)frame->data[0];

    samples8 =            frame->data[0];



    // Initialize

    for(i = 0; i < (1 << (bits + stereo)); i++) {

        h[i].length = 256;

        h[i].maxlength = 0;

        h[i].current = 0;

        h[i].bits = av_mallocz(256 * 4);

        h[i].lengths = av_mallocz(256 * sizeof(int));

        h[i].values = av_mallocz(256 * sizeof(int));

        skip_bits1(&gb);

        smacker_decode_tree(&gb, &h[i], 0, 0);

        skip_bits1(&gb);

        if(h[i].current > 1) {

            res = init_vlc(&vlc[i], SMKTREE_BITS, h[i].length,

                    h[i].lengths, sizeof(int), sizeof(int),

                    h[i].bits, sizeof(uint32_t), sizeof(uint32_t), INIT_VLC_LE);

            if(res < 0) {

                av_log(avctx, AV_LOG_ERROR, "Cannot build VLC table\n");

                return -1;

            }

        }

    }

    /* this codec relies on wraparound instead of clipping audio */

    if(bits) { //decode 16-bit data

        for(i = stereo; i >= 0; i--)

            pred[i] = sign_extend(av_bswap16(get_bits(&gb, 16)), 16);

        for(i = 0; i <= stereo; i++)

            *samples++ = pred[i];

        for(; i < unp_size / 2; i++) {

            if(i & stereo) {

                if(vlc[2].table)

                    res = get_vlc2(&gb, vlc[2].table, SMKTREE_BITS, 3);

                else

                    res = 0;

                val  = h[2].values[res];

                if(vlc[3].table)

                    res = get_vlc2(&gb, vlc[3].table, SMKTREE_BITS, 3);

                else

                    res = 0;

                val |= h[3].values[res] << 8;

                pred[1] += sign_extend(val, 16);

                *samples++ = pred[1];

            } else {

                if(vlc[0].table)

                    res = get_vlc2(&gb, vlc[0].table, SMKTREE_BITS, 3);

                else

                    res = 0;

                val  = h[0].values[res];

                if(vlc[1].table)

                    res = get_vlc2(&gb, vlc[1].table, SMKTREE_BITS, 3);

                else

                    res = 0;

                val |= h[1].values[res] << 8;

                pred[0] += sign_extend(val, 16);

                *samples++ = pred[0];

            }

        }

    } else { //8-bit data

        for(i = stereo; i >= 0; i--)

            pred[i] = get_bits(&gb, 8);

        for(i = 0; i <= stereo; i++)

            *samples8++ = pred[i];

        for(; i < unp_size; i++) {

            if(i & stereo){

                if(vlc[1].table)

                    res = get_vlc2(&gb, vlc[1].table, SMKTREE_BITS, 3);

                else

                    res = 0;

                pred[1] += sign_extend(h[1].values[res], 8);

                *samples8++ = pred[1];

            } else {

                if(vlc[0].table)

                    res = get_vlc2(&gb, vlc[0].table, SMKTREE_BITS, 3);

                else

                    res = 0;

                pred[0] += sign_extend(h[0].values[res], 8);

                *samples8++ = pred[0];

            }

        }

    }



    for(i = 0; i < 4; i++) {

        if(vlc[i].table)

            ff_free_vlc(&vlc[i]);

        av_free(h[i].bits);

        av_free(h[i].lengths);

        av_free(h[i].values);

    }



    *got_frame_ptr = 1;



    return buf_size;

}

static void dct_error(const struct algo *dct, int test, int is_idct, int speed)

{

    int it, i, scale;

    int err_inf, v;

    int64_t err2, ti, ti1, it1;

    int64_t sysErr[64], sysErrMax = 0;

    int maxout = 0;

    int blockSumErrMax = 0, blockSumErr;

    AVLFG prng;



    av_lfg_init(&prng, 1);



    err_inf = 0;

    err2 = 0;

    for (i = 0; i < 64; i++)

        sysErr[i] = 0;

    for (it = 0; it < NB_ITS; it++) {

        for (i = 0; i < 64; i++)

            block1[i] = 0;

        switch (test) {

        case 0:

            for (i = 0; i < 64; i++)

                block1[i] = (av_lfg_get(&prng) % 512) - 256;

            if (is_idct) {

                ff_ref_fdct(block1);

                for (i = 0; i < 64; i++)

                    block1[i] >>= 3;

            }

            break;

        case 1: {

                int num = av_lfg_get(&prng) % 10 + 1;

                for (i = 0; i < num; i++)

                    block1[av_lfg_get(&prng) % 64] =

                        av_lfg_get(&prng) % 512 - 256;

            }

            break;

        case 2:

            block1[0] = av_lfg_get(&prng) % 4096 - 2048;

            block1[63] = (block1[0] & 1) ^ 1;

            break;

        }



        for (i = 0; i < 64; i++)

            block_org[i] = block1[i];



        if (dct->format == MMX_PERM) {

            for (i = 0; i < 64; i++)

                block[idct_mmx_perm[i]] = block1[i];

        } else if (dct->format == MMX_SIMPLE_PERM) {

            for (i = 0; i < 64; i++)

                block[idct_simple_mmx_perm[i]] = block1[i];

        } else if (dct->format == SSE2_PERM) {

            for (i = 0; i < 64; i++)

                block[(i & 0x38) | idct_sse2_row_perm[i & 7]] = block1[i];

        } else if (dct->format == PARTTRANS_PERM) {

            for (i = 0; i < 64; i++)

                block[(i & 0x24) | ((i & 3) << 3) | ((i >> 3) & 3)] = block1[i];

        } else {

            for (i = 0; i < 64; i++)

                block[i] = block1[i];

        }



        dct->func(block);

        mmx_emms();



        if (dct->format == SCALE_PERM) {

            for (i = 0; i < 64; i++) {

                scale = 8 * (1 << (AANSCALE_BITS + 11)) / ff_aanscales[i];

                block[i] = (block[i] * scale) >> AANSCALE_BITS;

            }

        }



        dct->ref(block1);



        blockSumErr = 0;

        for (i = 0; i < 64; i++) {

            v = abs(block[i] - block1[i]);

            if (v > err_inf)

                err_inf = v;

            err2 += v * v;

            sysErr[i] += block[i] - block1[i];

            blockSumErr += v;

            if (abs(block[i]) > maxout)

                maxout = abs(block[i]);

        }

        if (blockSumErrMax < blockSumErr)

            blockSumErrMax = blockSumErr;

    }

    for (i = 0; i < 64; i++)

        sysErrMax = FFMAX(sysErrMax, FFABS(sysErr[i]));



    for (i = 0; i < 64; i++) {

        if (i % 8 == 0)

            printf("\n");

        printf("%7d ", (int) sysErr[i]);

    }

    printf("\n");



    printf("%s %s: err_inf=%d err2=%0.8f syserr=%0.8f maxout=%d blockSumErr=%d\n",

           is_idct ? "IDCT" : "DCT", dct->name, err_inf,

           (double) err2 / NB_ITS / 64.0, (double) sysErrMax / NB_ITS,

           maxout, blockSumErrMax);



    if (!speed)

        return;



    /* speed test */

    for (i = 0; i < 64; i++)

        block1[i] = 0;



    switch (test) {

    case 0:

        for (i = 0; i < 64; i++)

            block1[i] = av_lfg_get(&prng) % 512 - 256;

        if (is_idct) {

            ff_ref_fdct(block1);

            for (i = 0; i < 64; i++)

                block1[i] >>= 3;

        }

        break;

    case 1:

    case 2:

        block1[0] = av_lfg_get(&prng) % 512 - 256;

        block1[1] = av_lfg_get(&prng) % 512 - 256;

        block1[2] = av_lfg_get(&prng) % 512 - 256;

        block1[3] = av_lfg_get(&prng) % 512 - 256;

        break;

    }



    if (dct->format == MMX_PERM) {

        for (i = 0; i < 64; i++)

            block[idct_mmx_perm[i]] = block1[i];

    } else if (dct->format == MMX_SIMPLE_PERM) {

        for (i = 0; i < 64; i++)

            block[idct_simple_mmx_perm[i]] = block1[i];

    } else {

        for (i = 0; i < 64; i++)

            block[i] = block1[i];

    }



    ti = gettime();

    it1 = 0;

    do {

        for (it = 0; it < NB_ITS_SPEED; it++) {

            for (i = 0; i < 64; i++)

                block[i] = block1[i];

            dct->func(block);

        }

        it1 += NB_ITS_SPEED;

        ti1 = gettime() - ti;

    } while (ti1 < 1000000);

    mmx_emms();



    printf("%s %s: %0.1f kdct/s\n", is_idct ? "IDCT" : "DCT", dct->name,

           (double) it1 * 1000.0 / (double) ti1);

}

static int msrle_decode_8_16_24_32(AVCodecContext *avctx, AVPicture *pic,

                                   int depth, GetByteContext *gb)

{

    uint8_t *output, *output_end;

    int p1, p2, line=avctx->height - 1, pos=0, i;

    uint16_t pix16;

    uint32_t pix32;

    unsigned int width= FFABS(pic->linesize[0]) / (depth >> 3);



    output     = pic->data[0] + (avctx->height - 1) * pic->linesize[0];

    output_end = pic->data[0] +  avctx->height      * pic->linesize[0];

    while (bytestream2_get_bytes_left(gb) > 0) {

        p1 = bytestream2_get_byteu(gb);

        if(p1 == 0) { //Escape code

            p2 = bytestream2_get_byte(gb);

            if(p2 == 0) { //End-of-line

                output = pic->data[0] + (--line) * pic->linesize[0];

                if (line < 0) {

                    if (bytestream2_get_be16(gb) == 1) { // end-of-picture

                        return 0;

                    } else {

                        av_log(avctx, AV_LOG_ERROR,

                               "Next line is beyond picture bounds (%d bytes left)\n",

                               bytestream2_get_bytes_left(gb));

                        return AVERROR_INVALIDDATA;

                    }

                }

                pos = 0;

                continue;

            } else if(p2 == 1) { //End-of-picture

                return 0;

            } else if(p2 == 2) { //Skip

                p1 = bytestream2_get_byte(gb);

                p2 = bytestream2_get_byte(gb);

                line -= p2;

                pos += p1;

                if (line < 0 || pos >= width){

                    av_log(avctx, AV_LOG_ERROR, "Skip beyond picture bounds\n");

                    return -1;

                }

                output = pic->data[0] + line * pic->linesize[0] + pos * (depth >> 3);

                continue;

            }

            // Copy data

            if ((pic->linesize[0] > 0 && output + p2 * (depth >> 3) > output_end) ||

                (pic->linesize[0] < 0 && output + p2 * (depth >> 3) < output_end)) {

                bytestream2_skip(gb, 2 * (depth >> 3));

                continue;

            } else if (bytestream2_get_bytes_left(gb) < p2 * (depth >> 3)) {

                av_log(avctx, AV_LOG_ERROR, "bytestream overrun\n");

                return AVERROR_INVALIDDATA;

            }



            if ((depth == 8) || (depth == 24)) {

                for(i = 0; i < p2 * (depth >> 3); i++) {

                    *output++ = bytestream2_get_byteu(gb);

                }

                // RLE8 copy is actually padded - and runs are not!

                if(depth == 8 && (p2 & 1)) {

                    bytestream2_skip(gb, 1);

                }

            } else if (depth == 16) {

                for(i = 0; i < p2; i++) {

                    *(uint16_t*)output = bytestream2_get_le16u(gb);

                    output += 2;

                }

            } else if (depth == 32) {

                for(i = 0; i < p2; i++) {

                    *(uint32_t*)output = bytestream2_get_le32u(gb);

                    output += 4;

                }

            }

            pos += p2;

        } else { //run of pixels

            uint8_t pix[3]; //original pixel

            if ((pic->linesize[0] > 0 && output + p1 * (depth >> 3) > output_end) ||

                (pic->linesize[0] < 0 && output + p1 * (depth >> 3) < output_end))

                continue;

            switch(depth){

            case  8: pix[0] = bytestream2_get_byte(gb);

                     break;

            case 16: pix16  = bytestream2_get_le16(gb);

                     break;

            case 24: pix[0] = bytestream2_get_byte(gb);

                     pix[1] = bytestream2_get_byte(gb);

                     pix[2] = bytestream2_get_byte(gb);

                     break;

            case 32: pix32  = bytestream2_get_le32(gb);

                     break;

            }

            switch(depth){

            case  8:

                for(i = 0; i < p1; i++)

                        *output++ = pix[0];

                break;

            case 16:

                for(i = 0; i < p1; i++) {

                        *(uint16_t*)output = pix16;

                        output += 2;

                }

                break;

            case 24:

                for(i = 0; i < p1; i++) {

                        *output++ = pix[0];

                        *output++ = pix[1];

                        *output++ = pix[2];

                }

                break;

            case 32:

                for(i = 0; i < p1; i++) {

                        *(uint32_t*)output = pix32;

                        output += 4;

                }

                break;

            }

            pos += p1;

        }

    }



    av_log(avctx, AV_LOG_WARNING, "MS RLE warning: no end-of-picture code\n");

    return 0;

}

av_cold void ff_cavsdsp_init_x86(CAVSDSPContext *c, AVCodecContext *avctx)

{

    int cpu_flags = av_get_cpu_flags();



    cavsdsp_init_mmx(c, avctx);

#if HAVE_AMD3DNOW_INLINE

    if (INLINE_AMD3DNOW(cpu_flags))

        cavsdsp_init_3dnow(c, avctx);

#endif /* HAVE_AMD3DNOW_INLINE */

#if HAVE_MMXEXT_INLINE

    if (INLINE_MMXEXT(cpu_flags)) {

        DSPFUNC(put, 0, 16, mmxext);

        DSPFUNC(put, 1,  8, mmxext);

        DSPFUNC(avg, 0, 16, mmxext);

        DSPFUNC(avg, 1,  8, mmxext);

    }

#endif

#if HAVE_MMX_EXTERNAL

    if (EXTERNAL_MMXEXT(cpu_flags)) {

        c->avg_cavs_qpel_pixels_tab[0][0] = avg_cavs_qpel16_mc00_mmxext;

        c->avg_cavs_qpel_pixels_tab[1][0] = avg_cavs_qpel8_mc00_mmxext;

    }

#endif

#if HAVE_SSE2_EXTERNAL

    if (EXTERNAL_SSE2(cpu_flags)) {

        c->put_cavs_qpel_pixels_tab[0][0] = put_cavs_qpel16_mc00_sse2;

        c->avg_cavs_qpel_pixels_tab[0][0] = avg_cavs_qpel16_mc00_sse2;

    }

#endif

}

static int finish_frame(AVCodecContext *avctx, AVFrame *pict)

{

    RV34DecContext *r = avctx->priv_data;

    MpegEncContext *s = &r->s;

    int got_picture = 0, ret;



    ff_er_frame_end(&s->er);

    ff_mpv_frame_end(s);

    s->mb_num_left = 0;



    if (HAVE_THREADS && (s->avctx->active_thread_type & FF_THREAD_FRAME))

        ff_thread_report_progress(&s->current_picture_ptr->tf, INT_MAX, 0);



    if (s->pict_type == AV_PICTURE_TYPE_B || s->low_delay) {

        if ((ret = av_frame_ref(pict, s->current_picture_ptr->f)) < 0)

            return ret;

        ff_print_debug_info(s, s->current_picture_ptr);

        got_picture = 1;

    } else if (s->last_picture_ptr != NULL) {

        if ((ret = av_frame_ref(pict, s->last_picture_ptr->f)) < 0)

            return ret;

        ff_print_debug_info(s, s->last_picture_ptr);

        got_picture = 1;

    }



    return got_picture;

}

static void init_parse_context(OptionParseContext *octx,

                               const OptionGroupDef *groups)

{

    static const OptionGroupDef global_group = { "global" };

    const OptionGroupDef *g = groups;

    int i;



    memset(octx, 0, sizeof(*octx));



    while (g->name)

        g++;

    octx->nb_groups = g - groups;

    octx->groups    = av_mallocz(sizeof(*octx->groups) * octx->nb_groups);

    if (!octx->groups)

        exit(1);



    for (i = 0; i < octx->nb_groups; i++)

        octx->groups[i].group_def = &groups[i];



    octx->global_opts.group_def = &global_group;

    octx->global_opts.arg       = "";



    init_opts();

}

static inline void write_back_non_zero_count(H264Context *h){

    MpegEncContext * const s = &h->s;

    const int mb_xy= s->mb_x + s->mb_y*s->mb_stride;

    int n;



    for( n = 0; n < 16+4+4; n++ )

        h->non_zero_count[mb_xy][n] = h->non_zero_count_cache[scan8[n]];

}

static int hls_read_packet(AVFormatContext *s, AVPacket *pkt)

{

    HLSContext *c = s->priv_data;

    int ret, i, minvariant = -1;



    if (c->first_packet) {

        recheck_discard_flags(s, 1);

        c->first_packet = 0;

    }



start:

    c->end_of_segment = 0;

    for (i = 0; i < c->n_variants; i++) {

        struct variant *var = c->variants[i];

        /* Make sure we've got one buffered packet from each open variant

         * stream */

        if (var->needed && !var->pkt.data) {

            while (1) {

                int64_t ts_diff;

                AVStream *st;

                ret = av_read_frame(var->ctx, &var->pkt);

                if (ret < 0) {

                    if (!url_feof(&var->pb))

                        return ret;

                    reset_packet(&var->pkt);

                    break;

                } else {

                    if (c->first_timestamp == AV_NOPTS_VALUE)

                        c->first_timestamp = var->pkt.dts;

                }



                if (c->seek_timestamp == AV_NOPTS_VALUE)

                    break;



                if (var->pkt.dts == AV_NOPTS_VALUE) {

                    c->seek_timestamp = AV_NOPTS_VALUE;

                    break;

                }



                st = var->ctx->streams[var->pkt.stream_index];

                ts_diff = av_rescale_rnd(var->pkt.dts, AV_TIME_BASE,

                                         st->time_base.den, AV_ROUND_DOWN) -

                          c->seek_timestamp;

                if (ts_diff >= 0 && (c->seek_flags  & AVSEEK_FLAG_ANY ||

                                     var->pkt.flags & AV_PKT_FLAG_KEY)) {

                    c->seek_timestamp = AV_NOPTS_VALUE;

                    break;

                }

            }

        }

        /* Check if this stream has the packet with the lowest dts */

        if (var->pkt.data) {

            struct variant *minvar = c->variants[minvariant];

            if (minvariant < 0 ||

                av_compare_ts(var->pkt.dts, var->ctx->streams[var->pkt.stream_index]->time_base,

                              minvar->pkt.dts, minvar->ctx->streams[minvar->pkt.stream_index]->time_base) > 0)

                minvariant = i;

        }

    }

    if (c->end_of_segment) {

        if (recheck_discard_flags(s, 0))

            goto start;

    }

    /* If we got a packet, return it */

    if (minvariant >= 0) {

        *pkt = c->variants[minvariant]->pkt;

        pkt->stream_index += c->variants[minvariant]->stream_offset;

        reset_packet(&c->variants[minvariant]->pkt);

        return 0;

    }

    return AVERROR_EOF;

}

static void mov_write_uuidprof_tag(ByteIOContext *pb, AVFormatContext *s)

{

    AVCodecContext *VideoCodec = s->streams[0]->codec;

    AVCodecContext *AudioCodec = s->streams[1]->codec;

    int AudioRate = AudioCodec->sample_rate;

    int FrameRate = ((VideoCodec->time_base.den) * (0x10000))/ (VideoCodec->time_base.num);

    int audio_kbitrate= AudioCodec->bit_rate / 1000;

    int video_kbitrate= FFMIN(VideoCodec->bit_rate / 1000, 800 - audio_kbitrate);



    put_be32(pb, 0x94 ); /* size */

    put_tag(pb, "uuid");

    put_tag(pb, "PROF");



    put_be32(pb, 0x21d24fce ); /* 96 bit UUID */

    put_be32(pb, 0xbb88695c );

    put_be32(pb, 0xfac9c740 );



    put_be32(pb, 0x0 );  /* ? */

    put_be32(pb, 0x3 );  /* 3 sections ? */



    put_be32(pb, 0x14 ); /* size */

    put_tag(pb, "FPRF");

    put_be32(pb, 0x0 );  /* ? */

    put_be32(pb, 0x0 );  /* ? */

    put_be32(pb, 0x0 );  /* ? */



    put_be32(pb, 0x2c );  /* size */

    put_tag(pb, "APRF");   /* audio */

    put_be32(pb, 0x0 );

    put_be32(pb, 0x2 );   /* TrackID */

    put_tag(pb, "mp4a");

    put_be32(pb, 0x20f );

    put_be32(pb, 0x0 );

    put_be32(pb, audio_kbitrate);

    put_be32(pb, audio_kbitrate);

    put_be32(pb, AudioRate );

    put_be32(pb, AudioCodec->channels );



    put_be32(pb, 0x34 );  /* size */

    put_tag(pb, "VPRF");   /* video */

    put_be32(pb, 0x0 );

    put_be32(pb, 0x1 );    /* TrackID */

    put_tag(pb, "mp4v");

    put_be32(pb, 0x103 );

    put_be32(pb, 0x0 );

    put_be32(pb, video_kbitrate);

    put_be32(pb, video_kbitrate);

    put_be32(pb, FrameRate);

    put_be32(pb, FrameRate);

    put_be16(pb, VideoCodec->width);

    put_be16(pb, VideoCodec->height);

    put_be32(pb, 0x010001); /* ? */

}

static void show_chapters(WriterContext *w, AVFormatContext *fmt_ctx)

{

    int i;



    writer_print_section_header(w, SECTION_ID_CHAPTERS);

    for (i = 0; i < fmt_ctx->nb_chapters; i++) {

        AVChapter *chapter = fmt_ctx->chapters[i];



        writer_print_section_header(w, SECTION_ID_CHAPTER);

        print_int("id", chapter->id);

        print_q  ("time_base", chapter->time_base, '/');

        print_int("start", chapter->start);

        print_time("start_time", chapter->start, &chapter->time_base);

        print_int("end", chapter->end);

        print_time("end_time", chapter->end, &chapter->time_base);

        show_tags(w, chapter->metadata, SECTION_ID_CHAPTER_TAGS);

        writer_print_section_footer(w);

    }

    writer_print_section_footer(w);

}

static void dxva_adjust_hwframes(AVCodecContext *avctx, AVHWFramesContext *frames_ctx)

{

    FFDXVASharedContext *sctx = DXVA_SHARED_CONTEXT(avctx);

    int surface_alignment, num_surfaces;



    frames_ctx->format = sctx->pix_fmt;



    /* decoding MPEG-2 requires additional alignment on some Intel GPUs,

    but it causes issues for H.264 on certain AMD GPUs..... */

    if (avctx->codec_id == AV_CODEC_ID_MPEG2VIDEO)

        surface_alignment = 32;

    /* the HEVC DXVA2 spec asks for 128 pixel aligned surfaces to ensure

    all coding features have enough room to work with */

    else if (avctx->codec_id == AV_CODEC_ID_HEVC)

        surface_alignment = 128;

    else

        surface_alignment = 16;



    /* 4 base work surfaces */

    num_surfaces = 4;



    /* add surfaces based on number of possible refs */

    if (avctx->codec_id == AV_CODEC_ID_H264 || avctx->codec_id == AV_CODEC_ID_HEVC)

        num_surfaces += 16;

    else

        num_surfaces += 2;



    /* add extra surfaces for frame threading */

    if (avctx->active_thread_type & FF_THREAD_FRAME)

        num_surfaces += avctx->thread_count;



    frames_ctx->sw_format = avctx->sw_pix_fmt == AV_PIX_FMT_YUV420P10 ?

                            AV_PIX_FMT_P010 : AV_PIX_FMT_NV12;

    frames_ctx->width = FFALIGN(avctx->coded_width, surface_alignment);

    frames_ctx->height = FFALIGN(avctx->coded_height, surface_alignment);

    frames_ctx->initial_pool_size = num_surfaces;





#if CONFIG_DXVA2

    if (frames_ctx->format == AV_PIX_FMT_DXVA2_VLD) {

        AVDXVA2FramesContext *frames_hwctx = frames_ctx->hwctx;



        frames_hwctx->surface_type = DXVA2_VideoDecoderRenderTarget;

    }

#endif



#if CONFIG_D3D11VA

    if (frames_ctx->format == AV_PIX_FMT_D3D11) {

        AVD3D11VAFramesContext *frames_hwctx = frames_ctx->hwctx;



        frames_hwctx->BindFlags |= D3D11_BIND_DECODER;

    }

#endif

}

static int mpc_probe(AVProbeData *p)

{

    const uint8_t *d = p->buf;

    if (p->buf_size < 32)

        return 0;

    if (d[0] == 'M' && d[1] == 'P' && d[2] == '+' && (d[3] == 0x17 || d[3] == 0x7))

        return AVPROBE_SCORE_MAX;

    if (d[0] == 'I' && d[1] == 'D' && d[2] == '3')

        return AVPROBE_SCORE_MAX / 2;

    return 0;

}

