#else

		*d++ = (bgr&0x1F)<<3;

		*d++ = (bgr&0x3E0)>>2;

		*d++ = (bgr&0x7C00)>>7;

		*d++ = 0;

#endif



#endif

	}

}

static int ipvideo_decode_block_opcode_0xD(IpvideoContext *s)

{

    int y;

    unsigned char P[2];



    /* 4-color block encoding: each 4x4 block is a different color */

    CHECK_STREAM_PTR(4);



    for (y = 0; y < 8; y++) {

        if (!(y & 3)) {

            P[0] = *s->stream_ptr++;

            P[1] = *s->stream_ptr++;

        }

        memset(s->pixel_ptr,     P[0], 4);

        memset(s->pixel_ptr + 4, P[1], 4);

        s->pixel_ptr += s->stride;

    }



    /* report success */

    return 0;

}

static int process_work_frame(AVFilterContext *ctx)

{

    FrameRateContext *s = ctx->priv;

    int64_t work_pts;

    int interpolate;

    int ret;



    if (!s->f1)

        return 0;

    if (!s->f0 && !s->flush)

        return 0;



    work_pts = s->start_pts + av_rescale_q(s->n, av_inv_q(s->dest_frame_rate), s->dest_time_base);



    if (work_pts >= s->pts1 && !s->flush)

        return 0;



    if (!s->f0) {

        s->work = av_frame_clone(s->f1);

    } else {

        if (work_pts >= s->pts1 + s->delta && s->flush)

            return 0;



        interpolate = av_rescale(work_pts - s->pts0, s->max, s->delta);

        ff_dlog(ctx, "process_work_frame() interpolate:%d/%d\n", interpolate, s->max);

        if (interpolate > s->interp_end) {

            s->work = av_frame_clone(s->f1);

        } else if (interpolate < s->interp_start) {

            s->work = av_frame_clone(s->f0);

        } else {

            ret = blend_frames(ctx, interpolate);

            if (ret < 0)

                return ret;

            if (ret == 0)

                s->work = av_frame_clone(interpolate > (s->max >> 1) ? s->f1 : s->f0);

        }

    }



    if (!s->work)

        return AVERROR(ENOMEM);



    s->work->pts = work_pts;

    s->n++;



    return 1;

}

int ff_h2645_packet_split(H2645Packet *pkt, const uint8_t *buf, int length,

                          void *logctx, int is_nalff, int nal_length_size,

                          enum AVCodecID codec_id)

{

    int consumed, ret = 0;

    const uint8_t *next_avc = buf + (is_nalff ? 0 : length);



    pkt->nb_nals = 0;

    while (length >= 4) {

        H2645NAL *nal;

        int extract_length = 0;

        int skip_trailing_zeros = 1;



        /*

         * Only parse an AVC1 length field if one is expected at the current

         * buffer position. There are unfortunately streams with multiple

         * NAL units covered by the length field. Those NAL units are delimited

         * by Annex B start code prefixes. ff_h2645_extract_rbsp() detects it

         * correctly and consumes only the first NAL unit. The additional NAL

         * units are handled here in the Annex B parsing code.

         */

        if (buf == next_avc) {

            int i;

            for (i = 0; i < nal_length_size; i++)

                extract_length = (extract_length << 8) | buf[i];



            if (extract_length > length) {

                av_log(logctx, AV_LOG_ERROR,

                       "Invalid NAL unit size (%d > %d).\n",

                       extract_length, length);

                return AVERROR_INVALIDDATA;

            }

            buf     += nal_length_size;

            length  -= nal_length_size;

            // keep track of the next AVC1 length field

            next_avc = buf + extract_length;

        } else {

            /*

             * expected to return immediately except for streams with mixed

             * NAL unit coding

             */

            int buf_index = find_next_start_code(buf, next_avc);



            buf    += buf_index;

            length -= buf_index;



            /*

             * break if an AVC1 length field is expected at the current buffer

             * position

             */

            if (buf == next_avc)

                continue;



            if (length > 0) {

                extract_length = length;

            } else if (pkt->nb_nals == 0) {

                av_log(logctx, AV_LOG_ERROR, "No NAL unit found\n");

                return AVERROR_INVALIDDATA;

            } else {

                break;

            }

        }



        if (pkt->nals_allocated < pkt->nb_nals + 1) {

            int new_size = pkt->nals_allocated + 1;

            H2645NAL *tmp = av_realloc_array(pkt->nals, new_size, sizeof(*tmp));

            if (!tmp)

                return AVERROR(ENOMEM);



            pkt->nals = tmp;

            memset(pkt->nals + pkt->nals_allocated, 0,

                   (new_size - pkt->nals_allocated) * sizeof(*tmp));

            pkt->nals_allocated = new_size;

        }

        nal = &pkt->nals[pkt->nb_nals++];



        consumed = ff_h2645_extract_rbsp(buf, extract_length, nal);

        if (consumed < 0)

            return consumed;



        /* see commit 3566042a0 */

        if (consumed < length - 3 &&

            buf[consumed]     == 0x00 && buf[consumed + 1] == 0x00 &&

            buf[consumed + 2] == 0x01 && buf[consumed + 3] == 0xE0)

            skip_trailing_zeros = 0;



        nal->size_bits = get_bit_length(nal, skip_trailing_zeros);



        ret = init_get_bits(&nal->gb, nal->data, nal->size_bits);

        if (ret < 0)

            return ret;



        if (codec_id == AV_CODEC_ID_HEVC)

            ret = hevc_parse_nal_header(nal, logctx);

        else

            ret = h264_parse_nal_header(nal, logctx);

        if (ret <= 0) {

            if (ret < 0) {

                av_log(logctx, AV_LOG_ERROR, "Invalid NAL unit %d, skipping.\n",

                       nal->type);

            }

            pkt->nb_nals--;

        }



        buf    += consumed;

        length -= consumed;

    }



    return 0;

}

static void png_filter_row(DSPContext *dsp, uint8_t *dst, int filter_type,

                           uint8_t *src, uint8_t *top, int size, int bpp)

{

    int i;



    switch(filter_type) {

    case PNG_FILTER_VALUE_NONE:

        memcpy(dst, src, size);

        break;

    case PNG_FILTER_VALUE_SUB:

        dsp->diff_bytes(dst, src, src-bpp, size);

        memcpy(dst, src, bpp);

        break;

    case PNG_FILTER_VALUE_UP:

        dsp->diff_bytes(dst, src, top, size);

        break;

    case PNG_FILTER_VALUE_AVG:

        for(i = 0; i < bpp; i++)

            dst[i] = src[i] - (top[i] >> 1);

        for(; i < size; i++)

            dst[i] = src[i] - ((src[i-bpp] + top[i]) >> 1);

        break;

    case PNG_FILTER_VALUE_PAETH:

        for(i = 0; i < bpp; i++)

            dst[i] = src[i] - top[i];

        sub_png_paeth_prediction(dst+i, src+i, top+i, size-i, bpp);

        break;

    }

}

static int dnxhd_init_vlc(DNXHDEncContext *ctx)

{

    int i, j, level, run;

    int max_level = 1<<(ctx->cid_table->bit_depth+2);



    FF_ALLOCZ_OR_GOTO(ctx->m.avctx, ctx->vlc_codes, max_level*4*sizeof(*ctx->vlc_codes), fail);

    FF_ALLOCZ_OR_GOTO(ctx->m.avctx, ctx->vlc_bits,  max_level*4*sizeof(*ctx->vlc_bits) , fail);

    FF_ALLOCZ_OR_GOTO(ctx->m.avctx, ctx->run_codes, 63*2,                                fail);

    FF_ALLOCZ_OR_GOTO(ctx->m.avctx, ctx->run_bits,  63,                                  fail);



    ctx->vlc_codes += max_level*2;

    ctx->vlc_bits  += max_level*2;

    for (level = -max_level; level < max_level; level++) {

        for (run = 0; run < 2; run++) {

            int index = (level<<1)|run;

            int sign, offset = 0, alevel = level;



            MASK_ABS(sign, alevel);

            if (alevel > 64) {

                offset = (alevel-1)>>6;

                alevel -= offset<<6;

            }

            for (j = 0; j < 257; j++) {

                if (ctx->cid_table->ac_level[j] >> 1 == alevel &&

                    (!offset || (ctx->cid_table->ac_index_flag[j] && offset)) &&

                    (!run    || (ctx->cid_table->ac_run_flag  [j] && run))) {

                    assert(!ctx->vlc_codes[index]);

                    if (alevel) {

                        ctx->vlc_codes[index] = (ctx->cid_table->ac_codes[j]<<1)|(sign&1);

                        ctx->vlc_bits [index] = ctx->cid_table->ac_bits[j]+1;

                    } else {

                        ctx->vlc_codes[index] = ctx->cid_table->ac_codes[j];

                        ctx->vlc_bits [index] = ctx->cid_table->ac_bits [j];

                    }

                    break;

                }

            }

            assert(!alevel || j < 257);

            if (offset) {

                ctx->vlc_codes[index] = (ctx->vlc_codes[index]<<ctx->cid_table->index_bits)|offset;

                ctx->vlc_bits [index]+= ctx->cid_table->index_bits;

            }

        }

    }

    for (i = 0; i < 62; i++) {

        int run = ctx->cid_table->run[i];

        assert(run < 63);

        ctx->run_codes[run] = ctx->cid_table->run_codes[i];

        ctx->run_bits [run] = ctx->cid_table->run_bits[i];

    }

    return 0;

 fail:

    return -1;

}

static int mpc8_decode_frame(AVCodecContext * avctx, void *data,

                             int *got_frame_ptr, AVPacket *avpkt)

{

    const uint8_t *buf = avpkt->data;

    int buf_size = avpkt->size;

    MPCContext *c = avctx->priv_data;

    GetBitContext gb2, *gb = &gb2;

    int i, j, k, ch, cnt, res, t;

    Band *bands = c->bands;

    int off;

    int maxband, keyframe;

    int last[2];



    /* get output buffer */

    c->frame.nb_samples = MPC_FRAME_SIZE;

    if ((res = avctx->get_buffer(avctx, &c->frame)) < 0) {

        av_log(avctx, AV_LOG_ERROR, "get_buffer() failed\n");

        return res;

    }



    keyframe = c->cur_frame == 0;



    if(keyframe){

        memset(c->Q, 0, sizeof(c->Q));

        c->last_bits_used = 0;

    }

    init_get_bits(gb, buf, buf_size * 8);

    skip_bits(gb, c->last_bits_used & 7);



    if(keyframe)

        maxband = mpc8_get_mod_golomb(gb, c->maxbands + 1);

    else{

        maxband = c->last_max_band + get_vlc2(gb, band_vlc.table, MPC8_BANDS_BITS, 2);

        if(maxband > 32) maxband -= 33;

    }



    if(maxband > c->maxbands + 1 || maxband >= BANDS) {

        av_log(avctx, AV_LOG_ERROR, "maxband %d too large\n",maxband);

        return AVERROR_INVALIDDATA;

    }

    c->last_max_band = maxband;



    /* read subband indexes */

    if(maxband){

        last[0] = last[1] = 0;

        for(i = maxband - 1; i >= 0; i--){

            for(ch = 0; ch < 2; ch++){

                last[ch] = get_vlc2(gb, res_vlc[last[ch] > 2].table, MPC8_RES_BITS, 2) + last[ch];

                if(last[ch] > 15) last[ch] -= 17;

                bands[i].res[ch] = last[ch];

            }

        }

        if(c->MSS){

            int mask;



            cnt = 0;

            for(i = 0; i < maxband; i++)

                if(bands[i].res[0] || bands[i].res[1])

                    cnt++;

            t = mpc8_get_mod_golomb(gb, cnt);

            mask = mpc8_get_mask(gb, cnt, t);

            for(i = maxband - 1; i >= 0; i--)

                if(bands[i].res[0] || bands[i].res[1]){

                    bands[i].msf = mask & 1;

                    mask >>= 1;

                }

        }

    }

    for(i = maxband; i < c->maxbands; i++)

        bands[i].res[0] = bands[i].res[1] = 0;



    if(keyframe){

        for(i = 0; i < 32; i++)

            c->oldDSCF[0][i] = c->oldDSCF[1][i] = 1;

    }



    for(i = 0; i < maxband; i++){

        if(bands[i].res[0] || bands[i].res[1]){

            cnt = !!bands[i].res[0] + !!bands[i].res[1] - 1;

            if(cnt >= 0){

                t = get_vlc2(gb, scfi_vlc[cnt].table, scfi_vlc[cnt].bits, 1);

                if(bands[i].res[0]) bands[i].scfi[0] = t >> (2 * cnt);

                if(bands[i].res[1]) bands[i].scfi[1] = t & 3;

            }

        }

    }



    for(i = 0; i < maxband; i++){

        for(ch = 0; ch < 2; ch++){

            if(!bands[i].res[ch]) continue;



            if(c->oldDSCF[ch][i]){

                bands[i].scf_idx[ch][0] = get_bits(gb, 7) - 6;

                c->oldDSCF[ch][i] = 0;

            }else{

                t = get_vlc2(gb, dscf_vlc[1].table, MPC8_DSCF1_BITS, 2);

                if(t == 64)

                    t += get_bits(gb, 6);

                bands[i].scf_idx[ch][0] = ((bands[i].scf_idx[ch][2] + t - 25) & 0x7F) - 6;

            }

            for(j = 0; j < 2; j++){

                if((bands[i].scfi[ch] << j) & 2)

                    bands[i].scf_idx[ch][j + 1] = bands[i].scf_idx[ch][j];

                else{

                    t = get_vlc2(gb, dscf_vlc[0].table, MPC8_DSCF0_BITS, 2);

                    if(t == 31)

                        t = 64 + get_bits(gb, 6);

                    bands[i].scf_idx[ch][j + 1] = ((bands[i].scf_idx[ch][j] + t - 25) & 0x7F) - 6;

                }

            }

        }

    }



    for(i = 0, off = 0; i < maxband; i++, off += SAMPLES_PER_BAND){

        for(ch = 0; ch < 2; ch++){

            res = bands[i].res[ch];

            switch(res){

            case -1:

                for(j = 0; j < SAMPLES_PER_BAND; j++)

                    c->Q[ch][off + j] = (av_lfg_get(&c->rnd) & 0x3FC) - 510;

                break;

            case 0:

                break;

            case 1:

                for(j = 0; j < SAMPLES_PER_BAND; j += SAMPLES_PER_BAND / 2){

                    cnt = get_vlc2(gb, q1_vlc.table, MPC8_Q1_BITS, 2);

                    t = mpc8_get_mask(gb, 18, cnt);

                    for(k = 0; k < SAMPLES_PER_BAND / 2; k++, t <<= 1)

                        c->Q[ch][off + j + k] = (t & 0x20000) ? (get_bits1(gb) << 1) - 1 : 0;

                }

                break;

            case 2:

                cnt = 6;//2*mpc8_thres[res]

                for(j = 0; j < SAMPLES_PER_BAND; j += 3){

                    t = get_vlc2(gb, q2_vlc[cnt > 3].table, MPC8_Q2_BITS, 2);

                    c->Q[ch][off + j + 0] = mpc8_idx50[t];

                    c->Q[ch][off + j + 1] = mpc8_idx51[t];

                    c->Q[ch][off + j + 2] = mpc8_idx52[t];

                    cnt = (cnt >> 1) + mpc8_huffq2[t];

                }

                break;

            case 3:

            case 4:

                for(j = 0; j < SAMPLES_PER_BAND; j += 2){

                    t = get_vlc2(gb, q3_vlc[res - 3].table, MPC8_Q3_BITS, 2) + q3_offsets[res - 3];

                    c->Q[ch][off + j + 1] = t >> 4;

                    c->Q[ch][off + j + 0] = (t & 8) ? (t & 0xF) - 16 : (t & 0xF);

                }

                break;

            case 5:

            case 6:

            case 7:

            case 8:

                cnt = 2 * mpc8_thres[res];

                for(j = 0; j < SAMPLES_PER_BAND; j++){

                    t = get_vlc2(gb, quant_vlc[res - 5][cnt > mpc8_thres[res]].table, quant_vlc[res - 5][cnt > mpc8_thres[res]].bits, 2) + quant_offsets[res - 5];

                    c->Q[ch][off + j] = t;

                    cnt = (cnt >> 1) + FFABS(c->Q[ch][off + j]);

                }

                break;

            default:

                for(j = 0; j < SAMPLES_PER_BAND; j++){

                    c->Q[ch][off + j] = get_vlc2(gb, q9up_vlc.table, MPC8_Q9UP_BITS, 2);

                    if(res != 9){

                        c->Q[ch][off + j] <<= res - 9;

                        c->Q[ch][off + j] |= get_bits(gb, res - 9);

                    }

                    c->Q[ch][off + j] -= (1 << (res - 2)) - 1;

                }

            }

        }

    }



    ff_mpc_dequantize_and_synth(c, maxband - 1, c->frame.data[0],

                                avctx->channels);



    c->cur_frame++;



    c->last_bits_used = get_bits_count(gb);

    if(c->cur_frame >= c->frames)

        c->cur_frame = 0;



    *got_frame_ptr   = 1;

    *(AVFrame *)data = c->frame;



    return c->cur_frame ? c->last_bits_used >> 3 : buf_size;

}

static void *ff_realloc_static(void *ptr, unsigned int size)

{

    int i;

    if(!ptr)

      return av_mallocz_static(size);

    /* Look for the old ptr */

    for(i = 0; i < last_static; i++) {

        if(array_static[i] == ptr) {

            array_static[i] = av_realloc(array_static[i], size);

            return array_static[i];

        }

    }

    return NULL;



}

static int escape124_decode_frame(AVCodecContext *avctx,

                                  void *data, int *got_frame,

                                  AVPacket *avpkt)

{

    int buf_size = avpkt->size;

    Escape124Context *s = avctx->priv_data;

    AVFrame *frame = data;



    GetBitContext gb;

    unsigned frame_flags, frame_size;

    unsigned i;



    unsigned superblock_index, cb_index = 1,

             superblock_col_index = 0,

             superblocks_per_row = avctx->width / 8, skip = -1;



    uint16_t* old_frame_data, *new_frame_data;

    unsigned old_stride, new_stride;



    int ret;



    if ((ret = init_get_bits8(&gb, avpkt->data, avpkt->size)) < 0)

        return ret;



    // This call also guards the potential depth reads for the

    // codebook unpacking.

    if (!can_safely_read(&gb, 64))

        return -1;



    frame_flags = get_bits_long(&gb, 32);

    frame_size  = get_bits_long(&gb, 32);



    // Leave last frame unchanged

    // FIXME: Is this necessary?  I haven't seen it in any real samples

    if (!(frame_flags & 0x114) || !(frame_flags & 0x7800000)) {

        if (!s->frame.data[0])

            return AVERROR_INVALIDDATA;



        av_log(avctx, AV_LOG_DEBUG, "Skipping frame\n");



        *got_frame = 1;

        if ((ret = av_frame_ref(frame, &s->frame)) < 0)

            return ret;



        return frame_size;

    }



    for (i = 0; i < 3; i++) {

        if (frame_flags & (1 << (17 + i))) {

            unsigned cb_depth, cb_size;

            if (i == 2) {

                // This codebook can be cut off at places other than

                // powers of 2, leaving some of the entries undefined.

                cb_size = get_bits_long(&gb, 20);

                cb_depth = av_log2(cb_size - 1) + 1;

            } else {

                cb_depth = get_bits(&gb, 4);

                if (i == 0) {

                    // This is the most basic codebook: pow(2,depth) entries

                    // for a depth-length key

                    cb_size = 1 << cb_depth;

                } else {

                    // This codebook varies per superblock

                    // FIXME: I don't think this handles integer overflow

                    // properly

                    cb_size = s->num_superblocks << cb_depth;

                }

            }

            av_free(s->codebooks[i].blocks);

            s->codebooks[i] = unpack_codebook(&gb, cb_depth, cb_size);

            if (!s->codebooks[i].blocks)

                return -1;

        }

    }



    if ((ret = ff_get_buffer(avctx, frame, AV_GET_BUFFER_FLAG_REF)) < 0)

        return ret;



    new_frame_data = (uint16_t*)frame->data[0];

    new_stride = frame->linesize[0] / 2;

    old_frame_data = (uint16_t*)s->frame.data[0];

    old_stride = s->frame.linesize[0] / 2;



    for (superblock_index = 0; superblock_index < s->num_superblocks;

         superblock_index++) {

        MacroBlock mb;

        SuperBlock sb;

        unsigned multi_mask = 0;



        if (skip == -1) {

            // Note that this call will make us skip the rest of the blocks

            // if the frame prematurely ends

            skip = decode_skip_count(&gb);

        }



        if (skip) {

            copy_superblock(new_frame_data, new_stride,

                            old_frame_data, old_stride);

        } else {

            copy_superblock(sb.pixels, 8,

                            old_frame_data, old_stride);



            while (can_safely_read(&gb, 1) && !get_bits1(&gb)) {

                unsigned mask;

                mb = decode_macroblock(s, &gb, &cb_index, superblock_index);

                mask = get_bits(&gb, 16);

                multi_mask |= mask;

                for (i = 0; i < 16; i++) {

                    if (mask & mask_matrix[i]) {

                        insert_mb_into_sb(&sb, mb, i);

                    }

                }

            }



            if (can_safely_read(&gb, 1) && !get_bits1(&gb)) {

                unsigned inv_mask = get_bits(&gb, 4);

                for (i = 0; i < 4; i++) {

                    if (inv_mask & (1 << i)) {

                        multi_mask ^= 0xF << i*4;

                    } else {

                        multi_mask ^= get_bits(&gb, 4) << i*4;

                    }

                }



                for (i = 0; i < 16; i++) {

                    if (multi_mask & mask_matrix[i]) {

                        if (!can_safely_read(&gb, 1))

                            break;

                        mb = decode_macroblock(s, &gb, &cb_index,

                                               superblock_index);

                        insert_mb_into_sb(&sb, mb, i);

                    }

                }

            } else if (frame_flags & (1 << 16)) {

                while (can_safely_read(&gb, 1) && !get_bits1(&gb)) {

                    mb = decode_macroblock(s, &gb, &cb_index, superblock_index);

                    insert_mb_into_sb(&sb, mb, get_bits(&gb, 4));

                }

            }



            copy_superblock(new_frame_data, new_stride, sb.pixels, 8);

        }



        superblock_col_index++;

        new_frame_data += 8;

        if (old_frame_data)

            old_frame_data += 8;

        if (superblock_col_index == superblocks_per_row) {

            new_frame_data += new_stride * 8 - superblocks_per_row * 8;

            if (old_frame_data)

                old_frame_data += old_stride * 8 - superblocks_per_row * 8;

            superblock_col_index = 0;

        }

        skip--;

    }



    av_log(avctx, AV_LOG_DEBUG,

           "Escape sizes: %i, %i, %i\n",

           frame_size, buf_size, get_bits_count(&gb) / 8);



    av_frame_unref(&s->frame);

    if ((ret = av_frame_ref(&s->frame, frame)) < 0)

        return ret;



    *got_frame = 1;



    return frame_size;

}

static int adx_decode_frame(AVCodecContext *avctx, void *data, int *data_size,

                            AVPacket *avpkt)

{

    const uint8_t *buf0 = avpkt->data;

    int buf_size        = avpkt->size;

    ADXContext *c       = avctx->priv_data;

    int16_t *samples    = data;

    const uint8_t *buf  = buf0;

    int rest            = buf_size;



    if (!c->header_parsed) {

        int hdrsize = adx_decode_header(avctx, buf, rest);

        if (!hdrsize)

            return -1;

        c->header_parsed = 1;

        buf  += hdrsize;

        rest -= hdrsize;

    }



    /* 18 bytes of data are expanded into 32*2 bytes of audio,

       so guard against buffer overflows */

    if (rest / 18 > *data_size / 64)

        rest = (*data_size / 64) * 18;



    if (c->in_temp) {

        int copysize = 18 * avctx->channels - c->in_temp;

        memcpy(c->dec_temp + c->in_temp, buf, copysize);

        rest -= copysize;

        buf  += copysize;

        if (avctx->channels == 1) {

            adx_decode(samples, c->dec_temp, c->prev);

            samples += 32;

        } else {

            adx_decode_stereo(samples, c->dec_temp, c->prev);

            samples += 32*2;

        }

    }



    if (avctx->channels == 1) {

        while (rest >= 18) {

            adx_decode(samples, buf, c->prev);

            rest    -= 18;

            buf     += 18;

            samples += 32;

        }

    } else {

        while (rest >= 18 * 2) {

            adx_decode_stereo(samples, buf, c->prev);

            rest    -= 18 * 2;

            buf     += 18 * 2;

            samples += 32 * 2;

        }

    }



    c->in_temp = rest;

    if (rest) {

        memcpy(c->dec_temp, buf, rest);

        buf += rest;

    }

    *data_size = (uint8_t*)samples - (uint8_t*)data;

    return buf - buf0;

}

static int vc1_decode_i_block_adv(VC1Context *v, DCTELEM block[64], int n, int coded, int codingset, int mquant)

{

    GetBitContext *gb = &v->s.gb;

    MpegEncContext *s = &v->s;

    int dc_pred_dir = 0; /* Direction of the DC prediction used */

    int run_diff, i;

    int16_t *dc_val;

    int16_t *ac_val, *ac_val2;

    int dcdiff;

    int a_avail = v->a_avail, c_avail = v->c_avail;

    int use_pred = s->ac_pred;

    int scale;

    int q1, q2 = 0;

    int mb_pos = s->mb_x + s->mb_y * s->mb_stride;



    /* Get DC differential */

    if (n < 4) {

        dcdiff = get_vlc2(&s->gb, ff_msmp4_dc_luma_vlc[s->dc_table_index].table, DC_VLC_BITS, 3);

    } else {

        dcdiff = get_vlc2(&s->gb, ff_msmp4_dc_chroma_vlc[s->dc_table_index].table, DC_VLC_BITS, 3);

    }

    if (dcdiff < 0){

        av_log(s->avctx, AV_LOG_ERROR, "Illegal DC VLC\n");

        return -1;

    }

    if (dcdiff)

    {

        if (dcdiff == 119 /* ESC index value */)

        {

            /* TODO: Optimize */

            if (mquant == 1) dcdiff = get_bits(gb, 10);

            else if (mquant == 2) dcdiff = get_bits(gb, 9);

            else dcdiff = get_bits(gb, 8);

        }

        else

        {

            if (mquant == 1)

                dcdiff = (dcdiff<<2) + get_bits(gb, 2) - 3;

            else if (mquant == 2)

                dcdiff = (dcdiff<<1) + get_bits(gb, 1) - 1;

        }

        if (get_bits(gb, 1))

            dcdiff = -dcdiff;

    }



    /* Prediction */

    dcdiff += vc1_pred_dc(&v->s, v->overlap, mquant, n, v->a_avail, v->c_avail, &dc_val, &dc_pred_dir);

    *dc_val = dcdiff;



    /* Store the quantized DC coeff, used for prediction */

    if (n < 4) {

        block[0] = dcdiff * s->y_dc_scale;

    } else {

        block[0] = dcdiff * s->c_dc_scale;

    }

    /* Skip ? */

    run_diff = 0;

    i = 0;



    //AC Decoding

    i = 1;



    /* check if AC is needed at all and adjust direction if needed */

    if(!a_avail) dc_pred_dir = 1;

    if(!c_avail) dc_pred_dir = 0;

    if(!a_avail && !c_avail) use_pred = 0;

    ac_val = s->ac_val[0][0] + s->block_index[n] * 16;

    ac_val2 = ac_val;



    scale = mquant * 2 + v->halfpq;



    if(dc_pred_dir) //left

        ac_val -= 16;

    else //top

        ac_val -= 16 * s->block_wrap[n];



    q1 = s->current_picture.qscale_table[mb_pos];

    if(dc_pred_dir && c_avail) q2 = s->current_picture.qscale_table[mb_pos - 1];

    if(!dc_pred_dir && a_avail) q2 = s->current_picture.qscale_table[mb_pos - s->mb_stride];

    if(n && n<4) q2 = q1;



    if(coded) {

        int last = 0, skip, value;

        const int8_t *zz_table;

        int k;



        if(v->s.ac_pred) {

            if(!dc_pred_dir)

                zz_table = vc1_horizontal_zz;

            else

                zz_table = vc1_vertical_zz;

        } else

            zz_table = vc1_normal_zz;



        while (!last) {

            vc1_decode_ac_coeff(v, &last, &skip, &value, codingset);

            i += skip;

            if(i > 63)

                break;

            block[zz_table[i++]] = value;

        }



        /* apply AC prediction if needed */

        if(use_pred) {

            /* scale predictors if needed*/

            if(q2 && q1!=q2) {

                q1 = q1 * 2 + ((q1 == v->pq) ? v->halfpq : 0) - 1;

                q2 = q2 * 2 + ((q2 == v->pq) ? v->halfpq : 0) - 1;



                if(dc_pred_dir) { //left

                    for(k = 1; k < 8; k++)

                        block[k << 3] += (ac_val[k] * q2 * vc1_dqscale[q1 - 1] + 0x20000) >> 18;

                } else { //top

                    for(k = 1; k < 8; k++)

                        block[k] += (ac_val[k + 8] * q2 * vc1_dqscale[q1 - 1] + 0x20000) >> 18;

                }

            } else {

                if(dc_pred_dir) { //left

                    for(k = 1; k < 8; k++)

                        block[k << 3] += ac_val[k];

                } else { //top

                    for(k = 1; k < 8; k++)

                        block[k] += ac_val[k + 8];

                }

            }

        }

        /* save AC coeffs for further prediction */

        for(k = 1; k < 8; k++) {

            ac_val2[k] = block[k << 3];

            ac_val2[k + 8] = block[k];

        }



        /* scale AC coeffs */

        for(k = 1; k < 64; k++)

            if(block[k]) {

                block[k] *= scale;

                if(!v->pquantizer)

                    block[k] += (block[k] < 0) ? -mquant : mquant;

            }



        if(use_pred) i = 63;

    } else { // no AC coeffs

        int k;



        memset(ac_val2, 0, 16 * 2);

        if(dc_pred_dir) {//left

            if(use_pred) {

                memcpy(ac_val2, ac_val, 8 * 2);

                if(q2 && q1!=q2) {

                    q1 = q1 * 2 + ((q1 == v->pq) ? v->halfpq : 0) - 1;

                    q2 = q2 * 2 + ((q2 == v->pq) ? v->halfpq : 0) - 1;

                    for(k = 1; k < 8; k++)

                        ac_val2[k] = (ac_val2[k] * q2 * vc1_dqscale[q1 - 1] + 0x20000) >> 18;

                }

            }

        } else {//top

            if(use_pred) {

                memcpy(ac_val2 + 8, ac_val + 8, 8 * 2);

                if(q2 && q1!=q2) {

                    q1 = q1 * 2 + ((q1 == v->pq) ? v->halfpq : 0) - 1;

                    q2 = q2 * 2 + ((q2 == v->pq) ? v->halfpq : 0) - 1;

                    for(k = 1; k < 8; k++)

                        ac_val2[k + 8] = (ac_val2[k + 8] * q2 * vc1_dqscale[q1 - 1] + 0x20000) >> 18;

                }

            }

        }



        /* apply AC prediction if needed */

        if(use_pred) {

            if(dc_pred_dir) { //left

                for(k = 1; k < 8; k++) {

                    block[k << 3] = ac_val2[k] * scale;

                    if(!v->pquantizer && block[k << 3])

                        block[k << 3] += (block[k << 3] < 0) ? -mquant : mquant;

                }

            } else { //top

                for(k = 1; k < 8; k++) {

                    block[k] = ac_val2[k + 8] * scale;

                    if(!v->pquantizer && block[k])

                        block[k] += (block[k] < 0) ? -mquant : mquant;

                }

            }

            i = 63;

        }

    }

    s->block_last_index[n] = i;



    return 0;

}

