static int a64_write_header(AVFormatContext *s)

{

    AVCodecContext *avctx = s->streams[0]->codec;

    uint8_t header[5] = {

        0x00, //load

        0x40, //address

        0x00, //mode

        0x00, //charset_lifetime (multi only)

        0x00  //fps in 50/fps;

    };



    if (avctx->extradata_size < 4) {

        av_log(s, AV_LOG_ERROR, "Missing extradata\n");

        return AVERROR(EINVAL);

    }



    switch (avctx->codec->id) {

    case AV_CODEC_ID_A64_MULTI:

        header[2] = 0x00;

        header[3] = AV_RB32(avctx->extradata+0);

        header[4] = 2;

        break;

    case AV_CODEC_ID_A64_MULTI5:

        header[2] = 0x01;

        header[3] = AV_RB32(avctx->extradata+0);

        header[4] = 3;

        break;

    default:

        return AVERROR(EINVAL);

    }

    avio_write(s->pb, header, 2);

    return 0;

}

static void rgb24_to_yuvj420p(AVPicture *dst, AVPicture *src,

                              int width, int height)

{

    int wrap, wrap3, width2;

    int r, g, b, r1, g1, b1, w;

    uint8_t *lum, *cb, *cr;

    const uint8_t *p;



    lum = dst->data[0];

    cb = dst->data[1];

    cr = dst->data[2];



    width2 = (width + 1) >> 1;

    wrap = dst->linesize[0];

    wrap3 = src->linesize[0];

    p = src->data[0];

    for(;height>=2;height -= 2) {

        for(w = width; w >= 2; w -= 2) {

            RGB_IN(r, g, b, p);

            r1 = r;

            g1 = g;

            b1 = b;

            lum[0] = RGB_TO_Y(r, g, b);



            RGB_IN(r, g, b, p + BPP);

            r1 += r;

            g1 += g;

            b1 += b;

            lum[1] = RGB_TO_Y(r, g, b);

            p += wrap3;

            lum += wrap;



            RGB_IN(r, g, b, p);

            r1 += r;

            g1 += g;

            b1 += b;

            lum[0] = RGB_TO_Y(r, g, b);



            RGB_IN(r, g, b, p + BPP);

            r1 += r;

            g1 += g;

            b1 += b;

            lum[1] = RGB_TO_Y(r, g, b);



            cb[0] = RGB_TO_U(r1, g1, b1, 2);

            cr[0] = RGB_TO_V(r1, g1, b1, 2);



            cb++;

            cr++;

            p += -wrap3 + 2 * BPP;

            lum += -wrap + 2;

        }

        if (w) {

            RGB_IN(r, g, b, p);

            r1 = r;

            g1 = g;

            b1 = b;

            lum[0] = RGB_TO_Y(r, g, b);

            p += wrap3;

            lum += wrap;

            RGB_IN(r, g, b, p);

            r1 += r;

            g1 += g;

            b1 += b;

            lum[0] = RGB_TO_Y(r, g, b);

            cb[0] = RGB_TO_U(r1, g1, b1, 1);

            cr[0] = RGB_TO_V(r1, g1, b1, 1);

            cb++;

            cr++;

            p += -wrap3 + BPP;

            lum += -wrap + 1;

        }

        p += wrap3 + (wrap3 - width * BPP);

        lum += wrap + (wrap - width);

        cb += dst->linesize[1] - width2;

        cr += dst->linesize[2] - width2;

    }

    /* handle odd height */

    if (height) {

        for(w = width; w >= 2; w -= 2) {

            RGB_IN(r, g, b, p);

            r1 = r;

            g1 = g;

            b1 = b;

            lum[0] = RGB_TO_Y(r, g, b);



            RGB_IN(r, g, b, p + BPP);

            r1 += r;

            g1 += g;

            b1 += b;

            lum[1] = RGB_TO_Y(r, g, b);

            cb[0] = RGB_TO_U(r1, g1, b1, 1);

            cr[0] = RGB_TO_V(r1, g1, b1, 1);

            cb++;

            cr++;

            p += 2 * BPP;

           lum += 2;

        }

        if (w) {

            RGB_IN(r, g, b, p);

            lum[0] = RGB_TO_Y(r, g, b);

            cb[0] = RGB_TO_U(r, g, b, 0);

            cr[0] = RGB_TO_V(r, g, b, 0);

        }

    }

}

static void decode_scaling_matrices(H264Context *h, SPS *sps,

                                    PPS *pps, int is_sps,

                                    uint8_t(*scaling_matrix4)[16],

                                    uint8_t(*scaling_matrix8)[64])

{

    int fallback_sps = !is_sps && sps->scaling_matrix_present;

    const uint8_t *fallback[4] = {

        fallback_sps ? sps->scaling_matrix4[0] : default_scaling4[0],

        fallback_sps ? sps->scaling_matrix4[3] : default_scaling4[1],

        fallback_sps ? sps->scaling_matrix8[0] : default_scaling8[0],

        fallback_sps ? sps->scaling_matrix8[3] : default_scaling8[1]

    };

    if (get_bits1(&h->gb)) {

        sps->scaling_matrix_present |= is_sps;

        decode_scaling_list(h, scaling_matrix4[0], 16, default_scaling4[0], fallback[0]);        // Intra, Y

        decode_scaling_list(h, scaling_matrix4[1], 16, default_scaling4[0], scaling_matrix4[0]); // Intra, Cr

        decode_scaling_list(h, scaling_matrix4[2], 16, default_scaling4[0], scaling_matrix4[1]); // Intra, Cb

        decode_scaling_list(h, scaling_matrix4[3], 16, default_scaling4[1], fallback[1]);        // Inter, Y

        decode_scaling_list(h, scaling_matrix4[4], 16, default_scaling4[1], scaling_matrix4[3]); // Inter, Cr

        decode_scaling_list(h, scaling_matrix4[5], 16, default_scaling4[1], scaling_matrix4[4]); // Inter, Cb

        if (is_sps || pps->transform_8x8_mode) {

            decode_scaling_list(h, scaling_matrix8[0], 64, default_scaling8[0], fallback[2]); // Intra, Y

            if (sps->chroma_format_idc == 3) {

                decode_scaling_list(h, scaling_matrix8[1], 64, default_scaling8[0], scaling_matrix8[0]); // Intra, Cr

                decode_scaling_list(h, scaling_matrix8[2], 64, default_scaling8[0], scaling_matrix8[1]); // Intra, Cb

            }

            decode_scaling_list(h, scaling_matrix8[3], 64, default_scaling8[1], fallback[3]); // Inter, Y

            if (sps->chroma_format_idc == 3) {

                decode_scaling_list(h, scaling_matrix8[4], 64, default_scaling8[1], scaling_matrix8[3]); // Inter, Cr

                decode_scaling_list(h, scaling_matrix8[5], 64, default_scaling8[1], scaling_matrix8[4]); // Inter, Cb

            }

        }

    }

}

int ff_cbs_write_packet(CodedBitstreamContext *ctx,

                        AVPacket *pkt,

                        CodedBitstreamFragment *frag)

{

    int err;



    err = ff_cbs_write_fragment_data(ctx, frag);

    if (err < 0)

        return err;



    av_new_packet(pkt, frag->data_size);

    if (err < 0)

        return err;



    memcpy(pkt->data, frag->data, frag->data_size);

    pkt->size = frag->data_size;



    return 0;

}

