static int mxf_read_source_clip(void *arg, AVIOContext *pb, int tag, int size, UID uid)

{

    MXFStructuralComponent *source_clip = arg;

    switch(tag) {

    case 0x0202:

        source_clip->duration = avio_rb64(pb);

        break;

    case 0x1201:

        source_clip->start_position = avio_rb64(pb);

        break;

    case 0x1101:

        /* UMID, only get last 16 bytes */

        avio_skip(pb, 16);

        avio_read(pb, source_clip->source_package_uid, 16);

        break;

    case 0x1102:

        source_clip->source_track_id = avio_rb32(pb);

        break;

    }

    return 0;

}

static void print_report(int is_last_report, int64_t timer_start, int64_t cur_time)

{

    char buf[1024];

    AVBPrint buf_script;

    OutputStream *ost;

    AVFormatContext *oc;

    int64_t total_size;

    AVCodecContext *enc;

    int frame_number, vid, i;

    double bitrate;

    double speed;

    int64_t pts = INT64_MIN + 1;

    static int64_t last_time = -1;

    static int qp_histogram[52];

    int hours, mins, secs, us;

    float t;



    if (!print_stats && !is_last_report && !progress_avio)

        return;



    if (!is_last_report) {

        if (last_time == -1) {

            last_time = cur_time;

            return;

        }

        if ((cur_time - last_time) < 500000)

            return;

        last_time = cur_time;

    }



    t = (cur_time-timer_start) / 1000000.0;





    oc = output_files[0]->ctx;



    total_size = avio_size(oc->pb);

    if (total_size <= 0) // FIXME improve avio_size() so it works with non seekable output too

        total_size = avio_tell(oc->pb);



    buf[0] = '\0';

    vid = 0;

    av_bprint_init(&buf_script, 0, 1);

    for (i = 0; i < nb_output_streams; i++) {

        float q = -1;

        ost = output_streams[i];

        enc = ost->enc_ctx;

        if (!ost->stream_copy)

            q = ost->quality / (float) FF_QP2LAMBDA;



        if (vid && enc->codec_type == AVMEDIA_TYPE_VIDEO) {

            snprintf(buf + strlen(buf), sizeof(buf) - strlen(buf), "q=%2.1f ", q);

            av_bprintf(&buf_script, "stream_%d_%d_q=%.1f\n",

                       ost->file_index, ost->index, q);

        }

        if (!vid && enc->codec_type == AVMEDIA_TYPE_VIDEO) {

            float fps;



            frame_number = ost->frame_number;

            fps = t > 1 ? frame_number / t : 0;

            snprintf(buf + strlen(buf), sizeof(buf) - strlen(buf), "frame=%5d fps=%3.*f q=%3.1f ",

                     frame_number, fps < 9.95, fps, q);

            av_bprintf(&buf_script, "frame=%d\n", frame_number);

            av_bprintf(&buf_script, "fps=%.1f\n", fps);

            av_bprintf(&buf_script, "stream_%d_%d_q=%.1f\n",

                       ost->file_index, ost->index, q);

            if (is_last_report)

                snprintf(buf + strlen(buf), sizeof(buf) - strlen(buf), "L");

            if (qp_hist) {

                int j;

                int qp = lrintf(q);

                if (qp >= 0 && qp < FF_ARRAY_ELEMS(qp_histogram))

                    qp_histogram[qp]++;

                for (j = 0; j < 32; j++)

                    snprintf(buf + strlen(buf), sizeof(buf) - strlen(buf), "%X", (int)lrintf(log2(qp_histogram[j] + 1)));

            }



            if ((enc->flags & AV_CODEC_FLAG_PSNR) && (ost->pict_type != AV_PICTURE_TYPE_NONE || is_last_report)) {

                int j;

                double error, error_sum = 0;

                double scale, scale_sum = 0;

                double p;

                char type[3] = { 'Y','U','V' };

                snprintf(buf + strlen(buf), sizeof(buf) - strlen(buf), "PSNR=");

                for (j = 0; j < 3; j++) {

                    if (is_last_report) {

                        error = enc->error[j];

                        scale = enc->width * enc->height * 255.0 * 255.0 * frame_number;

                    } else {

                        error = ost->error[j];

                        scale = enc->width * enc->height * 255.0 * 255.0;

                    }

                    if (j)

                        scale /= 4;

                    error_sum += error;

                    scale_sum += scale;

                    p = psnr(error / scale);

                    snprintf(buf + strlen(buf), sizeof(buf) - strlen(buf), "%c:%2.2f ", type[j], p);

                    av_bprintf(&buf_script, "stream_%d_%d_psnr_%c=%2.2f\n",

                               ost->file_index, ost->index, type[j] | 32, p);

                }

                p = psnr(error_sum / scale_sum);

                snprintf(buf + strlen(buf), sizeof(buf) - strlen(buf), "*:%2.2f ", psnr(error_sum / scale_sum));

                av_bprintf(&buf_script, "stream_%d_%d_psnr_all=%2.2f\n",

                           ost->file_index, ost->index, p);

            }

            vid = 1;

        }

        /* compute min output value */

        if (av_stream_get_end_pts(ost->st) != AV_NOPTS_VALUE)

            pts = FFMAX(pts, av_rescale_q(av_stream_get_end_pts(ost->st),

                                          ost->st->time_base, AV_TIME_BASE_Q));

        if (is_last_report)

            nb_frames_drop += ost->last_dropped;

    }



    secs = FFABS(pts) / AV_TIME_BASE;

    us = FFABS(pts) % AV_TIME_BASE;

    mins = secs / 60;

    secs %= 60;

    hours = mins / 60;

    mins %= 60;



    bitrate = pts && total_size >= 0 ? total_size * 8 / (pts / 1000.0) : -1;

    speed = t != 0.0 ? (double)pts / AV_TIME_BASE / t : -1;



    if (total_size < 0) snprintf(buf + strlen(buf), sizeof(buf) - strlen(buf),

                                 "size=N/A time=");

    else                snprintf(buf + strlen(buf), sizeof(buf) - strlen(buf),

                                 "size=%8.0fkB time=", total_size / 1024.0);

    if (pts < 0)

        snprintf(buf + strlen(buf), sizeof(buf) - strlen(buf), "-");

    snprintf(buf + strlen(buf), sizeof(buf) - strlen(buf),

             "%02d:%02d:%02d.%02d ", hours, mins, secs,

             (100 * us) / AV_TIME_BASE);



    if (bitrate < 0) {

        snprintf(buf + strlen(buf), sizeof(buf) - strlen(buf),"bitrate=N/A");

        av_bprintf(&buf_script, "bitrate=N/A\n");

    }else{

        snprintf(buf + strlen(buf), sizeof(buf) - strlen(buf),"bitrate=%6.1fkbits/s", bitrate);

        av_bprintf(&buf_script, "bitrate=%6.1fkbits/s\n", bitrate);

    }



    if (total_size < 0) av_bprintf(&buf_script, "total_size=N/A\n");

    else                av_bprintf(&buf_script, "total_size=%"PRId64"\n", total_size);

    av_bprintf(&buf_script, "out_time_ms=%"PRId64"\n", pts);

    av_bprintf(&buf_script, "out_time=%02d:%02d:%02d.%06d\n",

               hours, mins, secs, us);



    if (nb_frames_dup || nb_frames_drop)

        snprintf(buf + strlen(buf), sizeof(buf) - strlen(buf), " dup=%d drop=%d",

                nb_frames_dup, nb_frames_drop);

    av_bprintf(&buf_script, "dup_frames=%d\n", nb_frames_dup);

    av_bprintf(&buf_script, "drop_frames=%d\n", nb_frames_drop);



    if (speed < 0) {

        snprintf(buf + strlen(buf), sizeof(buf) - strlen(buf)," speed=N/A");

        av_bprintf(&buf_script, "speed=N/A\n");

    } else {

        snprintf(buf + strlen(buf), sizeof(buf) - strlen(buf)," speed=%4.3gx", speed);

        av_bprintf(&buf_script, "speed=%4.3gx\n", speed);

    }



    if (print_stats || is_last_report) {

        const char end = is_last_report ? '\n' : '\r';

        if (print_stats==1 && AV_LOG_INFO > av_log_get_level()) {

            fprintf(stderr, "%s    %c", buf, end);

        } else

            av_log(NULL, AV_LOG_INFO, "%s    %c", buf, end);



    fflush(stderr);

    }



    if (progress_avio) {

        av_bprintf(&buf_script, "progress=%s\n",

                   is_last_report ? "end" : "continue");

        avio_write(progress_avio, buf_script.str,

                   FFMIN(buf_script.len, buf_script.size - 1));

        avio_flush(progress_avio);

        av_bprint_finalize(&buf_script, NULL);

        if (is_last_report) {

            avio_closep(&progress_avio);

        }

    }



    if (is_last_report)

        print_final_stats(total_size);

}

static int mpegps_read_packet(AVFormatContext *s,

                              AVPacket *pkt)

{

    AVStream *st;

    int len, startcode, i, type, codec_id;

    int64_t pts, dts;



 redo:

    len = mpegps_read_pes_header(s, NULL, &startcode, &pts, &dts, 1);

    if (len < 0)

        return len;



    /* now find stream */

    for(i=0;i<s->nb_streams;i++) {

        st = s->streams[i];

        if (st->id == startcode)

            goto found;

    }

    if (startcode >= 0x1e0 && startcode <= 0x1ef) {

        type = CODEC_TYPE_VIDEO;

        codec_id = CODEC_ID_MPEG2VIDEO;

    } else if (startcode >= 0x1c0 && startcode <= 0x1df) {

        type = CODEC_TYPE_AUDIO;

        codec_id = CODEC_ID_MP2;

    } else if (startcode >= 0x80 && startcode <= 0x9f) {

        type = CODEC_TYPE_AUDIO;

        codec_id = CODEC_ID_AC3;

    } else if (startcode >= 0xa0 && startcode <= 0xbf) {

        type = CODEC_TYPE_AUDIO;

        codec_id = CODEC_ID_PCM_S16BE;

    } else {

    skip:

        /* skip packet */

        url_fskip(&s->pb, len);

        goto redo;

    }

    /* no stream found: add a new stream */

    st = av_new_stream(s, startcode);

    if (!st) 

        goto skip;

    st->codec.codec_type = type;

    st->codec.codec_id = codec_id;

    if (codec_id != CODEC_ID_PCM_S16BE)

        st->need_parsing = 1;

 found:

    if (startcode >= 0xa0 && startcode <= 0xbf) {

        int b1, freq;



        /* for LPCM, we just skip the header and consider it is raw

           audio data */

        if (len <= 3)

            goto skip;

        get_byte(&s->pb); /* emphasis (1), muse(1), reserved(1), frame number(5) */

        b1 = get_byte(&s->pb); /* quant (2), freq(2), reserved(1), channels(3) */

        get_byte(&s->pb); /* dynamic range control (0x80 = off) */

        len -= 3;

        freq = (b1 >> 4) & 3;

        st->codec.sample_rate = lpcm_freq_tab[freq];

        st->codec.channels = 1 + (b1 & 7);

        st->codec.bit_rate = st->codec.channels * st->codec.sample_rate * 2;

    }

    av_new_packet(pkt, len);

    get_buffer(&s->pb, pkt->data, pkt->size);

    pkt->pts = pts;

    pkt->dts = dts;

    pkt->stream_index = st->index;

#if 0

    printf("%d: pts=%0.3f dts=%0.3f\n",

           pkt->stream_index, pkt->pts / 90000.0, pkt->dts / 90000.0);

#endif

    return 0;

}

static void get_downmix_coeffs(AC3DecodeContext *ctx)

{

    int from = ctx->bsi.acmod;

    int to = ctx->output;

    float clev = clevs[ctx->bsi.cmixlev];

    float slev = slevs[ctx->bsi.surmixlev];

    ac3_audio_block *ab = &ctx->audio_block;



    if (to == AC3_OUTPUT_UNMODIFIED)

        return 0;



    switch (from) {

        case AC3_INPUT_DUALMONO:

            switch (to) {

                case AC3_OUTPUT_MONO:

                case AC3_OUTPUT_STEREO: /* We Assume that sum of both mono channels is requested */

                    ab->chcoeffs[0] *= LEVEL_MINUS_6DB;

                    ab->chcoeffs[1] *= LEVEL_MINUS_6DB;

                    break;

            }

            break;

        case AC3_INPUT_MONO:

            switch (to) {

                case AC3_OUTPUT_STEREO:

                    ab->chcoeffs[0] *= LEVEL_MINUS_3DB;

                    break;

            }

            break;

        case AC3_INPUT_STEREO:

            switch (to) {

                case AC3_OUTPUT_MONO:

                    ab->chcoeffs[0] *= LEVEL_MINUS_3DB;

                    ab->chcoeffs[1] *= LEVEL_MINUS_3DB;

                    break;

            }

            break;

        case AC3_INPUT_3F:

            switch (to) {

                case AC3_OUTPUT_MONO:

                    ab->chcoeffs[0] *= LEVEL_MINUS_3DB;

                    ab->chcoeffs[2] *= LEVEL_MINUS_3DB;

                    ab->chcoeffs[1] *= clev * LEVEL_PLUS_3DB;

                    break;

                case AC3_OUTPUT_STEREO:

                    ab->chcoeffs[1] *= clev;

                    break;

            }

            break;

        case AC3_INPUT_2F_1R:

            switch (to) {

                case AC3_OUTPUT_MONO:

                    ab->chcoeffs[0] *= LEVEL_MINUS_3DB;

                    ab->chcoeffs[1] *= LEVEL_MINUS_3DB;

                    ab->chcoeffs[2] *= slev * LEVEL_MINUS_3DB;

                    break;

                case AC3_OUTPUT_STEREO:

                    ab->chcoeffs[2] *= slev * LEVEL_MINUS_3DB;

                    break;

                case AC3_OUTPUT_DOLBY:

                    ab->chcoeffs[2] *= LEVEL_MINUS_3DB;

                    break;

            }

            break;

        case AC3_INPUT_3F_1R:

            switch (to) {

                case AC3_OUTPUT_MONO:

                    ab->chcoeffs[0] *= LEVEL_MINUS_3DB;

                    ab->chcoeffs[2] *= LEVEL_MINUS_3DB;

                    ab->chcoeffs[1] *= clev * LEVEL_PLUS_3DB;

                    ab->chcoeffs[3] *= slev * LEVEL_MINUS_3DB;

                    break;

                case AC3_OUTPUT_STEREO:

                    ab->chcoeffs[1] *= clev;

                    ab->chcoeffs[3] *= slev * LEVEL_MINUS_3DB;

                    break;

                case AC3_OUTPUT_DOLBY:

                    ab->chcoeffs[1] *= LEVEL_MINUS_3DB;

                    ab->chcoeffs[3] *= LEVEL_MINUS_3DB;

                    break;

            }

            break;

        case AC3_INPUT_2F_2R:

            switch (to) {

                case AC3_OUTPUT_MONO:

                    ab->chcoeffs[0] *= LEVEL_MINUS_3DB;

                    ab->chcoeffs[1] *= LEVEL_MINUS_3DB;

                    ab->chcoeffs[2] *= slev * LEVEL_MINUS_3DB;

                    ab->chcoeffs[3] *= slev * LEVEL_MINUS_3DB;

                    break;

                case AC3_OUTPUT_STEREO:

                    ab->chcoeffs[2] *= slev;

                    ab->chcoeffs[3] *= slev;

                    break;

                case AC3_OUTPUT_DOLBY:

                    ab->chcoeffs[2] *= LEVEL_MINUS_3DB;

                    ab->chcoeffs[3] *= LEVEL_MINUS_3DB;

                    break;

            }

            break;

        case AC3_INPUT_3F_2R:

            switch (to) {

                case AC3_OUTPUT_MONO:

                    ab->chcoeffs[0] *= LEVEL_MINUS_3DB;

                    ab->chcoeffs[2] *= LEVEL_MINUS_3DB;

                    ab->chcoeffs[1] *= clev * LEVEL_PLUS_3DB;

                    ab->chcoeffs[3] *= slev * LEVEL_MINUS_3DB;

                    ab->chcoeffs[4] *= slev * LEVEL_MINUS_3DB;

                    break;

                case AC3_OUTPUT_STEREO:

                    ab->chcoeffs[1] *= clev;

                    ab->chcoeffs[3] *= slev;

                    ab->chcoeffs[4] *= slev;

                    break;

                case AC3_OUTPUT_DOLBY:

                    ab->chcoeffs[1] *= LEVEL_MINUS_3DB;

                    ab->chcoeffs[3] *= LEVEL_MINUS_3DB;

                    ab->chcoeffs[4] *= LEVEL_MINUS_3DB;

                    break;

            }

            break;

    }

}

static av_cold void dsputil_init_mmx(DSPContext *c, AVCodecContext *avctx,

                                     int mm_flags)

{

    const int high_bit_depth = avctx->bits_per_raw_sample > 8;



#if HAVE_INLINE_ASM

    c->put_pixels_clamped        = ff_put_pixels_clamped_mmx;

    c->put_signed_pixels_clamped = ff_put_signed_pixels_clamped_mmx;

    c->add_pixels_clamped        = ff_add_pixels_clamped_mmx;



    if (!high_bit_depth) {

        c->clear_block  = clear_block_mmx;

        c->clear_blocks = clear_blocks_mmx;

        c->draw_edges   = draw_edges_mmx;



        SET_HPEL_FUNCS(put,        [0], 16, mmx);

        SET_HPEL_FUNCS(put_no_rnd, [0], 16, mmx);

        SET_HPEL_FUNCS(avg,        [0], 16, mmx);

        SET_HPEL_FUNCS(avg_no_rnd,    , 16, mmx);

        SET_HPEL_FUNCS(put,        [1],  8, mmx);

        SET_HPEL_FUNCS(put_no_rnd, [1],  8, mmx);

        SET_HPEL_FUNCS(avg,        [1],  8, mmx);



        switch (avctx->idct_algo) {

        case FF_IDCT_AUTO:

        case FF_IDCT_SIMPLEMMX:

            c->idct_put              = ff_simple_idct_put_mmx;

            c->idct_add              = ff_simple_idct_add_mmx;

            c->idct                  = ff_simple_idct_mmx;

            c->idct_permutation_type = FF_SIMPLE_IDCT_PERM;

            break;

        case FF_IDCT_XVIDMMX:

            c->idct_put              = ff_idct_xvid_mmx_put;

            c->idct_add              = ff_idct_xvid_mmx_add;

            c->idct                  = ff_idct_xvid_mmx;

            break;

        }

    }



    c->gmc = gmc_mmx;



    c->add_bytes = add_bytes_mmx;



    if (CONFIG_H263_DECODER || CONFIG_H263_ENCODER) {

        c->h263_v_loop_filter = h263_v_loop_filter_mmx;

        c->h263_h_loop_filter = h263_h_loop_filter_mmx;

    }

#endif /* HAVE_INLINE_ASM */



#if HAVE_YASM

    c->vector_clip_int32 = ff_vector_clip_int32_mmx;

#endif



}

static int copy_parameter_set(void **to, void **from, int count, int size)

{

    int i;



    for (i = 0; i < count; i++) {

        if (to[i] && !from[i]) {

            av_freep(&to[i]);

        } else if (from[i] && !to[i]) {

            to[i] = av_malloc(size);

            if (!to[i])

                return AVERROR(ENOMEM);

        }



        if (from[i])

            memcpy(to[i], from[i], size);

    }



    return 0;

}

int ff_celp_lp_synthesis_filter(int16_t *out,

                                const int16_t* filter_coeffs,

                                const int16_t* in,

                                int buffer_length,

                                int filter_length,

                                int stop_on_overflow,

                                int rounder)

{

    int i,n;



    // Avoids a +1 in the inner loop.

    filter_length++;



    for (n = 0; n < buffer_length; n++) {

        int sum = rounder;

        for (i = 1; i < filter_length; i++)

            sum -= filter_coeffs[i-1] * out[n-i];



        sum = (sum >> 12) + in[n];



        if (sum + 0x8000 > 0xFFFFU) {

            if (stop_on_overflow)

                return 1;

            sum = (sum >> 31) ^ 32767;

        }

        out[n] = sum;

    }



    return 0;

}

ff_rm_parse_packet (AVFormatContext *s, AVIOContext *pb,

                    AVStream *st, RMStream *ast, int len, AVPacket *pkt,

                    int *seq, int flags, int64_t timestamp)

{

    RMDemuxContext *rm = s->priv_data;

    int ret;



    if (st->codec->codec_type == AVMEDIA_TYPE_VIDEO) {

        rm->current_stream= st->id;

        ret = rm_assemble_video_frame(s, pb, rm, ast, pkt, len, seq, &timestamp);

        if(ret)

            return ret < 0 ? ret : -1; //got partial frame or error

    } else if (st->codec->codec_type == AVMEDIA_TYPE_AUDIO) {

        if ((ast->deint_id == DEINT_ID_GENR) ||

            (ast->deint_id == DEINT_ID_INT4) ||

            (ast->deint_id == DEINT_ID_SIPR)) {

            int x;

            int sps = ast->sub_packet_size;

            int cfs = ast->coded_framesize;

            int h = ast->sub_packet_h;

            int y = ast->sub_packet_cnt;

            int w = ast->audio_framesize;



            if (flags & 2)

                y = ast->sub_packet_cnt = 0;

            if (!y)

                ast->audiotimestamp = timestamp;



            switch (ast->deint_id) {

                case DEINT_ID_INT4:

                    for (x = 0; x < h/2; x++)

                        readfull(s, pb, ast->pkt.data+x*2*w+y*cfs, cfs);

                    break;

                case DEINT_ID_GENR:

                    for (x = 0; x < w/sps; x++)

                        readfull(s, pb, ast->pkt.data+sps*(h*x+((h+1)/2)*(y&1)+(y>>1)), sps);

                    break;

                case DEINT_ID_SIPR:

                    readfull(s, pb, ast->pkt.data + y * w, w);

                    break;

            }



            if (++(ast->sub_packet_cnt) < h)

                return -1;

            if (ast->deint_id == DEINT_ID_SIPR)

                ff_rm_reorder_sipr_data(ast->pkt.data, h, w);



             ast->sub_packet_cnt = 0;

             rm->audio_stream_num = st->index;

             rm->audio_pkt_cnt = h * w / st->codec->block_align;

        } else if ((ast->deint_id == DEINT_ID_VBRF) ||

                   (ast->deint_id == DEINT_ID_VBRS)) {

            int x;

            rm->audio_stream_num = st->index;

            ast->sub_packet_cnt = (avio_rb16(pb) & 0xf0) >> 4;

            if (ast->sub_packet_cnt) {

                for (x = 0; x < ast->sub_packet_cnt; x++)

                    ast->sub_packet_lengths[x] = avio_rb16(pb);

                rm->audio_pkt_cnt = ast->sub_packet_cnt;

                ast->audiotimestamp = timestamp;

            } else

                return -1;

        } else {

            av_get_packet(pb, pkt, len);

            rm_ac3_swap_bytes(st, pkt);

        }

    } else

        av_get_packet(pb, pkt, len);



    pkt->stream_index = st->index;



#if 0

    if (st->codec->codec_type == AVMEDIA_TYPE_VIDEO) {

        if(st->codec->codec_id == AV_CODEC_ID_RV20){

            int seq= 128*(pkt->data[2]&0x7F) + (pkt->data[3]>>1);

            av_log(s, AV_LOG_DEBUG, "%d %"PRId64" %d\n", *timestamp, *timestamp*512LL/25, seq);



            seq |= (timestamp&~0x3FFF);

            if(seq - timestamp >  0x2000) seq -= 0x4000;

            if(seq - timestamp < -0x2000) seq += 0x4000;

        }

    }

#endif



    pkt->pts = timestamp;

    if (flags & 2)

        pkt->flags |= AV_PKT_FLAG_KEY;



    return st->codec->codec_type == AVMEDIA_TYPE_AUDIO ? rm->audio_pkt_cnt : 0;

}

static int read_var_block_data(ALSDecContext *ctx, ALSBlockData *bd)

{

    ALSSpecificConfig *sconf = &ctx->sconf;

    AVCodecContext *avctx    = ctx->avctx;

    GetBitContext *gb        = &ctx->gb;

    unsigned int k;

    unsigned int s[8];

    unsigned int sx[8];

    unsigned int sub_blocks, log2_sub_blocks, sb_length;

    unsigned int start      = 0;

    unsigned int opt_order;

    int          sb;

    int32_t      *quant_cof = bd->quant_cof;

    int32_t      *current_res;





    // ensure variable block decoding by reusing this field

    bd->const_block = 0;



    bd->opt_order   = 1;

    bd->js_blocks   = get_bits1(gb);



    opt_order       = bd->opt_order;



    // determine the number of subblocks for entropy decoding

    if (!sconf->bgmc && !sconf->sb_part) {

        log2_sub_blocks = 0;

    } else {

        if (sconf->bgmc && sconf->sb_part)

            log2_sub_blocks = get_bits(gb, 2);

        else

            log2_sub_blocks = 2 * get_bits1(gb);

    }



    sub_blocks = 1 << log2_sub_blocks;



    // do not continue in case of a damaged stream since

    // block_length must be evenly divisible by sub_blocks

    if (bd->block_length & (sub_blocks - 1)) {

        av_log(avctx, AV_LOG_WARNING,

               "Block length is not evenly divisible by the number of subblocks.\n");

        return -1;

    }



    sb_length = bd->block_length >> log2_sub_blocks;



    if (sconf->bgmc) {

        s[0] = get_bits(gb, 8 + (sconf->resolution > 1));

        for (k = 1; k < sub_blocks; k++)

            s[k] = s[k - 1] + decode_rice(gb, 2);



        for (k = 0; k < sub_blocks; k++) {

            sx[k]   = s[k] & 0x0F;

            s [k] >>= 4;

        }

    } else {

        s[0] = get_bits(gb, 4 + (sconf->resolution > 1));

        for (k = 1; k < sub_blocks; k++)

            s[k] = s[k - 1] + decode_rice(gb, 0);

    }



    if (get_bits1(gb))

        bd->shift_lsbs = get_bits(gb, 4) + 1;



    bd->store_prev_samples = (bd->js_blocks && bd->raw_other) || bd->shift_lsbs;





    if (!sconf->rlslms) {

        if (sconf->adapt_order) {

            int opt_order_length = av_ceil_log2(av_clip((bd->block_length >> 3) - 1,

                                                2, sconf->max_order + 1));

            bd->opt_order        = get_bits(gb, opt_order_length);

        } else {

            bd->opt_order = sconf->max_order;

        }



        opt_order = bd->opt_order;



        if (opt_order) {

            int add_base;



            if (sconf->coef_table == 3) {

                add_base = 0x7F;



                // read coefficient 0

                quant_cof[0] = 32 * parcor_scaled_values[get_bits(gb, 7)];



                // read coefficient 1

                if (opt_order > 1)

                    quant_cof[1] = -32 * parcor_scaled_values[get_bits(gb, 7)];



                // read coefficients 2 to opt_order

                for (k = 2; k < opt_order; k++)

                    quant_cof[k] = get_bits(gb, 7);

            } else {

                int k_max;

                add_base = 1;



                // read coefficient 0 to 19

                k_max = FFMIN(opt_order, 20);

                for (k = 0; k < k_max; k++) {

                    int rice_param = parcor_rice_table[sconf->coef_table][k][1];

                    int offset     = parcor_rice_table[sconf->coef_table][k][0];

                    quant_cof[k] = decode_rice(gb, rice_param) + offset;

                }



                // read coefficients 20 to 126

                k_max = FFMIN(opt_order, 127);

                for (; k < k_max; k++)

                    quant_cof[k] = decode_rice(gb, 2) + (k & 1);



                // read coefficients 127 to opt_order

                for (; k < opt_order; k++)

                    quant_cof[k] = decode_rice(gb, 1);



                quant_cof[0] = 32 * parcor_scaled_values[quant_cof[0] + 64];



                if (opt_order > 1)

                    quant_cof[1] = -32 * parcor_scaled_values[quant_cof[1] + 64];

            }



            for (k = 2; k < opt_order; k++)

                quant_cof[k] = (quant_cof[k] << 14) + (add_base << 13);

        }

    }



    // read LTP gain and lag values

    if (sconf->long_term_prediction) {

        *bd->use_ltp = get_bits1(gb);



        if (*bd->use_ltp) {

            bd->ltp_gain[0]   = decode_rice(gb, 1) << 3;

            bd->ltp_gain[1]   = decode_rice(gb, 2) << 3;



            bd->ltp_gain[2]   = ltp_gain_values[get_unary(gb, 0, 4)][get_bits(gb, 2)];



            bd->ltp_gain[3]   = decode_rice(gb, 2) << 3;

            bd->ltp_gain[4]   = decode_rice(gb, 1) << 3;



            *bd->ltp_lag      = get_bits(gb, ctx->ltp_lag_length);

            *bd->ltp_lag     += FFMAX(4, opt_order + 1);

        }

    }



    // read first value and residuals in case of a random access block

    if (bd->ra_block) {

        if (opt_order)

            bd->raw_samples[0] = decode_rice(gb, avctx->bits_per_raw_sample - 4);

        if (opt_order > 1)

            bd->raw_samples[1] = decode_rice(gb, s[0] + 3);

        if (opt_order > 2)

            bd->raw_samples[2] = decode_rice(gb, s[0] + 1);



        start = FFMIN(opt_order, 3);

    }



    // read all residuals

    if (sconf->bgmc) {

        unsigned int delta[sub_blocks];

        unsigned int k    [sub_blocks];

        unsigned int b = av_clip((av_ceil_log2(bd->block_length) - 3) >> 1, 0, 5);

        unsigned int i = start;



        // read most significant bits

        unsigned int high;

        unsigned int low;

        unsigned int value;



        ff_bgmc_decode_init(gb, &high, &low, &value);



        current_res = bd->raw_samples + start;



        for (sb = 0; sb < sub_blocks; sb++, i = 0) {

            k    [sb] = s[sb] > b ? s[sb] - b : 0;

            delta[sb] = 5 - s[sb] + k[sb];



            ff_bgmc_decode(gb, sb_length, current_res,

                        delta[sb], sx[sb], &high, &low, &value, ctx->bgmc_lut, ctx->bgmc_lut_status);



            current_res += sb_length;

        }



        ff_bgmc_decode_end(gb);





        // read least significant bits and tails

        i = start;

        current_res = bd->raw_samples + start;



        for (sb = 0; sb < sub_blocks; sb++, i = 0) {

            unsigned int cur_tail_code = tail_code[sx[sb]][delta[sb]];

            unsigned int cur_k         = k[sb];

            unsigned int cur_s         = s[sb];



            for (; i < sb_length; i++) {

                int32_t res = *current_res;



                if (res == cur_tail_code) {

                    unsigned int max_msb =   (2 + (sx[sb] > 2) + (sx[sb] > 10))

                                          << (5 - delta[sb]);



                    res = decode_rice(gb, cur_s);



                    if (res >= 0) {

                        res += (max_msb    ) << cur_k;

                    } else {

                        res -= (max_msb - 1) << cur_k;

                    }

                } else {

                    if (res > cur_tail_code)

                        res--;



                    if (res & 1)

                        res = -res;



                    res >>= 1;



                    if (cur_k) {

                        res <<= cur_k;

                        res  |= get_bits_long(gb, cur_k);

                    }

                }



                *current_res++ = res;

            }

        }

    } else {

        current_res = bd->raw_samples + start;



        for (sb = 0; sb < sub_blocks; sb++, start = 0)

            for (; start < sb_length; start++)

                *current_res++ = decode_rice(gb, s[sb]);

     }



    if (!sconf->mc_coding || ctx->js_switch)

        align_get_bits(gb);



    return 0;

}

