static int flic_read_header(AVFormatContext *s,

                            AVFormatParameters *ap)

{

    FlicDemuxContext *flic = s->priv_data;

    ByteIOContext *pb = &s->pb;

    unsigned char header[FLIC_HEADER_SIZE];

    AVStream *st;

    int speed;

    int magic_number;



    flic->pts = 0;



    /* load the whole header and pull out the width and height */

    if (get_buffer(pb, header, FLIC_HEADER_SIZE) != FLIC_HEADER_SIZE)

        return AVERROR(EIO);



    magic_number = AV_RL16(&header[4]);

    speed = AV_RL32(&header[0x10]);



    /* initialize the decoder streams */

    st = av_new_stream(s, 0);

    if (!st)

        return AVERROR(ENOMEM);

    flic->video_stream_index = st->index;

    st->codec->codec_type = CODEC_TYPE_VIDEO;

    st->codec->codec_id = CODEC_ID_FLIC;

    st->codec->codec_tag = 0;  /* no fourcc */

    st->codec->width = AV_RL16(&header[0x08]);

    st->codec->height = AV_RL16(&header[0x0A]);



    if (!st->codec->width || !st->codec->height)

        return AVERROR_INVALIDDATA;



    /* send over the whole 128-byte FLIC header */

    st->codec->extradata_size = FLIC_HEADER_SIZE;

    st->codec->extradata = av_malloc(FLIC_HEADER_SIZE);

    memcpy(st->codec->extradata, header, FLIC_HEADER_SIZE);



    av_set_pts_info(st, 33, 1, 90000);



    /* Time to figure out the framerate: If there is a FLIC chunk magic

     * number at offset 0x10, assume this is from the Bullfrog game,

     * Magic Carpet. */

    if (AV_RL16(&header[0x10]) == FLIC_CHUNK_MAGIC_1) {



        flic->frame_pts_inc = FLIC_MC_PTS_INC;



        /* rewind the stream since the first chunk is at offset 12 */

        url_fseek(pb, 12, SEEK_SET);



        /* send over abbreviated FLIC header chunk */

        av_free(st->codec->extradata);

        st->codec->extradata_size = 12;

        st->codec->extradata = av_malloc(12);

        memcpy(st->codec->extradata, header, 12);



    } else if (magic_number == FLIC_FILE_MAGIC_1) {

        /*

         * in this case, the speed (n) is number of 1/70s ticks between frames:

         *

         *    pts        n * frame #

         *  --------  =  -----------  => pts = n * (90000/70) * frame #

         *   90000           70

         *

         *  therefore, the frame pts increment = n * 1285.7

         */

        flic->frame_pts_inc = speed * 1285.7;

    } else if ((magic_number == FLIC_FILE_MAGIC_2) ||

               (magic_number == FLIC_FILE_MAGIC_3)) {

        /*

         * in this case, the speed (n) is number of milliseconds between frames:

         *

         *    pts        n * frame #

         *  --------  =  -----------  => pts = n * 90 * frame #

         *   90000          1000

         *

         *  therefore, the frame pts increment = n * 90

         */

        flic->frame_pts_inc = speed * 90;

    } else {

        av_log(s, AV_LOG_INFO, "Invalid or unsupported magic chunk in file\n");

        return AVERROR_INVALIDDATA;

    }



    if (flic->frame_pts_inc == 0)

        flic->frame_pts_inc = FLIC_DEFAULT_PTS_INC;



    return 0;

}

static void show_format(WriterContext *w, AVFormatContext *fmt_ctx)

{

    char val_str[128];

    int64_t size = fmt_ctx->pb ? avio_size(fmt_ctx->pb) : -1;



    writer_print_section_header(w, SECTION_ID_FORMAT);

    print_str("filename",         fmt_ctx->filename);

    print_int("nb_streams",       fmt_ctx->nb_streams);

    print_int("nb_programs",      fmt_ctx->nb_programs);

    print_str("format_name",      fmt_ctx->iformat->name);

    if (!do_bitexact) {

        if (fmt_ctx->iformat->long_name) print_str    ("format_long_name", fmt_ctx->iformat->long_name);

        else                             print_str_opt("format_long_name", "unknown");

    }

    print_time("start_time",      fmt_ctx->start_time, &AV_TIME_BASE_Q);

    print_time("duration",        fmt_ctx->duration,   &AV_TIME_BASE_Q);

    if (size >= 0) print_val    ("size", size, unit_byte_str);

    else           print_str_opt("size", "N/A");

    if (fmt_ctx->bit_rate > 0) print_val    ("bit_rate", fmt_ctx->bit_rate, unit_bit_per_second_str);

    else                       print_str_opt("bit_rate", "N/A");

    print_int("probe_score", av_format_get_probe_score(fmt_ctx));

    show_tags(w, fmt_ctx->metadata, SECTION_ID_FORMAT_TAGS);



    writer_print_section_footer(w);

    fflush(stdout);

}

static void flush_encoders(OutputStream *ost_table, int nb_ostreams)

{

    int i, ret;



    for (i = 0; i < nb_ostreams; i++) {

        OutputStream   *ost = &ost_table[i];

        AVCodecContext *enc = ost->st->codec;

        AVFormatContext *os = output_files[ost->file_index].ctx;



        if (!ost->encoding_needed)

            continue;



        if (ost->st->codec->codec_type == AVMEDIA_TYPE_AUDIO && enc->frame_size <=1)

            continue;

        if (ost->st->codec->codec_type == AVMEDIA_TYPE_VIDEO && (os->oformat->flags & AVFMT_RAWPICTURE))

            continue;



        for(;;) {

            AVPacket pkt;

            int fifo_bytes;

            av_init_packet(&pkt);

            pkt.stream_index= ost->index;



            switch (ost->st->codec->codec_type) {

            case AVMEDIA_TYPE_AUDIO:

                fifo_bytes = av_fifo_size(ost->fifo);

                ret = 0;

                /* encode any samples remaining in fifo */

                if (fifo_bytes > 0) {

                    int osize = av_get_bytes_per_sample(enc->sample_fmt);

                    int fs_tmp = enc->frame_size;



                    av_fifo_generic_read(ost->fifo, audio_buf, fifo_bytes, NULL);

                    if (enc->codec->capabilities & CODEC_CAP_SMALL_LAST_FRAME) {

                        enc->frame_size = fifo_bytes / (osize * enc->channels);

                    } else { /* pad */

                        int frame_bytes = enc->frame_size*osize*enc->channels;

                        if (allocated_audio_buf_size < frame_bytes)

                            exit_program(1);

                        generate_silence(audio_buf+fifo_bytes, enc->sample_fmt, frame_bytes - fifo_bytes);

                    }



                    ret = avcodec_encode_audio(enc, bit_buffer, bit_buffer_size, (short *)audio_buf);

                    pkt.duration = av_rescale((int64_t)enc->frame_size*ost->st->time_base.den,

                                              ost->st->time_base.num, enc->sample_rate);

                    enc->frame_size = fs_tmp;

                }

                if (ret <= 0) {

                    ret = avcodec_encode_audio(enc, bit_buffer, bit_buffer_size, NULL);

                }

                if (ret < 0) {

                    av_log(NULL, AV_LOG_FATAL, "Audio encoding failed\n");

                    exit_program(1);

                }

                audio_size += ret;

                pkt.flags |= AV_PKT_FLAG_KEY;

                break;

            case AVMEDIA_TYPE_VIDEO:

                ret = avcodec_encode_video(enc, bit_buffer, bit_buffer_size, NULL);

                if (ret < 0) {

                    av_log(NULL, AV_LOG_FATAL, "Video encoding failed\n");

                    exit_program(1);

                }

                video_size += ret;

                if(enc->coded_frame && enc->coded_frame->key_frame)

                    pkt.flags |= AV_PKT_FLAG_KEY;

                if (ost->logfile && enc->stats_out) {

                    fprintf(ost->logfile, "%s", enc->stats_out);

                }

                break;

            default:

                ret=-1;

            }



            if (ret <= 0)

                break;

            pkt.data = bit_buffer;

            pkt.size = ret;

            if (enc->coded_frame && enc->coded_frame->pts != AV_NOPTS_VALUE)

                pkt.pts= av_rescale_q(enc->coded_frame->pts, enc->time_base, ost->st->time_base);

            write_frame(os, &pkt, ost->st->codec, ost->bitstream_filters);

        }

    }

}

static int mkv_write_chapters(AVFormatContext *s)

{

    MatroskaMuxContext *mkv = s->priv_data;

    AVIOContext *pb = s->pb;

    ebml_master chapters, editionentry;

    AVRational scale = {1, 1E9};

    int i, ret;



    if (!s->nb_chapters || mkv->wrote_chapters)

        return 0;



    ret = mkv_add_seekhead_entry(mkv->main_seekhead, MATROSKA_ID_CHAPTERS, avio_tell(pb));

    if (ret < 0) return ret;



    chapters     = start_ebml_master(pb, MATROSKA_ID_CHAPTERS    , 0);

    editionentry = start_ebml_master(pb, MATROSKA_ID_EDITIONENTRY, 0);

    put_ebml_uint(pb, MATROSKA_ID_EDITIONFLAGDEFAULT, 1);

    put_ebml_uint(pb, MATROSKA_ID_EDITIONFLAGHIDDEN , 0);

    for (i = 0; i < s->nb_chapters; i++) {

        ebml_master chapteratom, chapterdisplay;

        AVChapter *c     = s->chapters[i];

        AVDictionaryEntry *t = NULL;



        chapteratom = start_ebml_master(pb, MATROSKA_ID_CHAPTERATOM, 0);

        put_ebml_uint(pb, MATROSKA_ID_CHAPTERUID, c->id);

        put_ebml_uint(pb, MATROSKA_ID_CHAPTERTIMESTART,

                      av_rescale_q(c->start, c->time_base, scale));

        put_ebml_uint(pb, MATROSKA_ID_CHAPTERTIMEEND,

                      av_rescale_q(c->end,   c->time_base, scale));

        put_ebml_uint(pb, MATROSKA_ID_CHAPTERFLAGHIDDEN , 0);

        put_ebml_uint(pb, MATROSKA_ID_CHAPTERFLAGENABLED, 1);

        if ((t = av_dict_get(c->metadata, "title", NULL, 0))) {

            chapterdisplay = start_ebml_master(pb, MATROSKA_ID_CHAPTERDISPLAY, 0);

            put_ebml_string(pb, MATROSKA_ID_CHAPSTRING, t->value);

            put_ebml_string(pb, MATROSKA_ID_CHAPLANG  , "und");

            end_ebml_master(pb, chapterdisplay);

        }

        end_ebml_master(pb, chapteratom);

    }

    end_ebml_master(pb, editionentry);

    end_ebml_master(pb, chapters);



    mkv->wrote_chapters = 1;

    return 0;

}

static av_always_inline void filter_mb_row(AVCodecContext *avctx, void *tdata,

                              int jobnr, int threadnr, int is_vp7)

{

    VP8Context *s = avctx->priv_data;

    VP8ThreadData *td = &s->thread_data[threadnr];

    int mb_x, mb_y = td->thread_mb_pos >> 16, num_jobs = s->num_jobs;

    AVFrame *curframe = s->curframe->tf.f;

    VP8Macroblock *mb;

    VP8ThreadData *prev_td, *next_td;

    uint8_t *dst[3] = {

        curframe->data[0] + 16 * mb_y * s->linesize,

        curframe->data[1] +  8 * mb_y * s->uvlinesize,

        curframe->data[2] +  8 * mb_y * s->uvlinesize

    };



    if (s->mb_layout == 1)

        mb = s->macroblocks_base + ((s->mb_width + 1) * (mb_y + 1) + 1);

    else

        mb = s->macroblocks + (s->mb_height - mb_y - 1) * 2;



    if (mb_y == 0)

        prev_td = td;

    else

        prev_td = &s->thread_data[(jobnr + num_jobs - 1) % num_jobs];

    if (mb_y == s->mb_height - 1)

        next_td = td;

    else

        next_td = &s->thread_data[(jobnr + 1) % num_jobs];



    for (mb_x = 0; mb_x < s->mb_width; mb_x++, mb++) {

        VP8FilterStrength *f = &td->filter_strength[mb_x];

        if (prev_td != td)

            check_thread_pos(td, prev_td,

                             (mb_x + 1) + (s->mb_width + 3), mb_y - 1);

        if (next_td != td)

            if (next_td != &s->thread_data[0])

                check_thread_pos(td, next_td, mb_x + 1, mb_y + 1);



        if (num_jobs == 1) {

            if (s->filter.simple)

                backup_mb_border(s->top_border[mb_x + 1], dst[0],

                                 NULL, NULL, s->linesize, 0, 1);

            else

                backup_mb_border(s->top_border[mb_x + 1], dst[0],

                                 dst[1], dst[2], s->linesize, s->uvlinesize, 0);

        }



        if (s->filter.simple)

            filter_mb_simple(s, dst[0], f, mb_x, mb_y);

        else

            filter_mb(s, dst, f, mb_x, mb_y, is_vp7);

        dst[0] += 16;

        dst[1] += 8;

        dst[2] += 8;



        update_pos(td, mb_y, (s->mb_width + 3) + mb_x);

    }

}

static int decode_frame(FLACContext *s)

{

    int i, ret;

    GetBitContext *gb = &s->gb;

    FLACFrameInfo fi;



    if ((ret = ff_flac_decode_frame_header(s->avctx, gb, &fi, 0)) < 0) {

        av_log(s->avctx, AV_LOG_ERROR, "invalid frame header\n");

        return ret;

    }



    if (s->channels && fi.channels != s->channels && s->got_streaminfo) {

        s->channels = s->avctx->channels = fi.channels;

        ff_flac_set_channel_layout(s->avctx);

        ret = allocate_buffers(s);

        if (ret < 0)

            return ret;

    }

    s->channels = s->avctx->channels = fi.channels;

    if (!s->avctx->channel_layout)

        ff_flac_set_channel_layout(s->avctx);

    s->ch_mode = fi.ch_mode;



    if (!s->bps && !fi.bps) {

        av_log(s->avctx, AV_LOG_ERROR, "bps not found in STREAMINFO or frame header\n");

        return AVERROR_INVALIDDATA;

    }

    if (!fi.bps) {

        fi.bps = s->bps;

    } else if (s->bps && fi.bps != s->bps) {

        av_log(s->avctx, AV_LOG_ERROR, "switching bps mid-stream is not "

                                       "supported\n");

        return AVERROR_INVALIDDATA;

    }



    if (!s->bps) {

        s->bps = s->avctx->bits_per_raw_sample = fi.bps;

        flac_set_bps(s);

    }



    if (!s->max_blocksize)

        s->max_blocksize = FLAC_MAX_BLOCKSIZE;

    if (fi.blocksize > s->max_blocksize) {

        av_log(s->avctx, AV_LOG_ERROR, "blocksize %d > %d\n", fi.blocksize,

               s->max_blocksize);

        return AVERROR_INVALIDDATA;

    }

    s->blocksize = fi.blocksize;



    if (!s->samplerate && !fi.samplerate) {

        av_log(s->avctx, AV_LOG_ERROR, "sample rate not found in STREAMINFO"

                                        " or frame header\n");

        return AVERROR_INVALIDDATA;

    }

    if (fi.samplerate == 0)

        fi.samplerate = s->samplerate;

    s->samplerate = s->avctx->sample_rate = fi.samplerate;



    if (!s->got_streaminfo) {

        ret = allocate_buffers(s);

        if (ret < 0)

            return ret;

        ff_flacdsp_init(&s->dsp, s->avctx->sample_fmt, s->channels, s->bps);

        s->got_streaminfo = 1;

        dump_headers(s->avctx, (FLACStreaminfo *)s);

    }



//    dump_headers(s->avctx, (FLACStreaminfo *)s);



    /* subframes */

    for (i = 0; i < s->channels; i++) {

        if ((ret = decode_subframe(s, i)) < 0)

            return ret;

    }



    align_get_bits(gb);



    /* frame footer */

    skip_bits(gb, 16); /* data crc */



    return 0;

}

static int mov_read_mac_string(MOVContext *c, AVIOContext *pb, int len,

                               char *dst, int dstlen)

{

    char *p = dst;

    char *end = dst+dstlen-1;

    int i;



    for (i = 0; i < len; i++) {

        uint8_t t, c = avio_r8(pb);

        if (c < 0x80 && p < end)

            *p++ = c;

        else

            PUT_UTF8(mac_to_unicode[c-0x80], t, if (p < end) *p++ = t;);

    }

    *p = 0;

    return p - dst;

}

altivec_yuv2packedX (SwsContext *c,

		       int16_t *lumFilter, int16_t **lumSrc, int lumFilterSize,

		       int16_t *chrFilter, int16_t **chrSrc, int chrFilterSize,

		       uint8_t *dest, int dstW, int dstY)

{

  int i,j;

  vector signed short X,X0,X1,Y0,U0,V0,Y1,U1,V1,U,V;

  vector signed short R0,G0,B0,R1,G1,B1;



  vector unsigned char R,G,B;

  vector unsigned char *out,*nout;



  vector signed short   RND = vec_splat_s16(1<<3);

  vector unsigned short SCL = vec_splat_u16(4);

  unsigned long scratch[16] __attribute__ ((aligned (16)));



  vector signed short *YCoeffs, *CCoeffs;



  YCoeffs = c->vYCoeffsBank+dstY*lumFilterSize;

  CCoeffs = c->vCCoeffsBank+dstY*chrFilterSize;



  out = (vector unsigned char *)dest;



  for(i=0; i<dstW; i+=16){

    Y0 = RND;

    Y1 = RND;

    /* extract 16 coeffs from lumSrc */

    for(j=0; j<lumFilterSize; j++) {

      X0 = vec_ld (0,  &lumSrc[j][i]);

      X1 = vec_ld (16, &lumSrc[j][i]);

      Y0 = vec_mradds (X0, YCoeffs[j], Y0);

      Y1 = vec_mradds (X1, YCoeffs[j], Y1);

    }



    U = RND;

    V = RND;

    /* extract 8 coeffs from U,V */

    for(j=0; j<chrFilterSize; j++) {

      X  = vec_ld (0, &chrSrc[j][i/2]);

      U  = vec_mradds (X, CCoeffs[j], U);

      X  = vec_ld (0, &chrSrc[j][i/2+2048]);

      V  = vec_mradds (X, CCoeffs[j], V);

    }



    /* scale and clip signals */

    Y0 = vec_sra (Y0, SCL);

    Y1 = vec_sra (Y1, SCL);

    U  = vec_sra (U,  SCL);

    V  = vec_sra (V,  SCL);



    Y0 = vec_clip_s16 (Y0);

    Y1 = vec_clip_s16 (Y1);

    U  = vec_clip_s16 (U);

    V  = vec_clip_s16 (V);



    /* now we have

      Y0= y0 y1 y2 y3 y4 y5 y6 y7     Y1= y8 y9 y10 y11 y12 y13 y14 y15

      U= u0 u1 u2 u3 u4 u5 u6 u7      V= v0 v1 v2 v3 v4 v5 v6 v7



      Y0= y0 y1 y2 y3 y4 y5 y6 y7    Y1= y8 y9 y10 y11 y12 y13 y14 y15

      U0= u0 u0 u1 u1 u2 u2 u3 u3    U1= u4 u4 u5 u5 u6 u6 u7 u7

      V0= v0 v0 v1 v1 v2 v2 v3 v3    V1= v4 v4 v5 v5 v6 v6 v7 v7

    */



    U0 = vec_mergeh (U,U);

    V0 = vec_mergeh (V,V);



    U1 = vec_mergel (U,U);

    V1 = vec_mergel (V,V);



    cvtyuvtoRGB (c, Y0,U0,V0,&R0,&G0,&B0);

    cvtyuvtoRGB (c, Y1,U1,V1,&R1,&G1,&B1);



    R  = vec_packclp (R0,R1);

    G  = vec_packclp (G0,G1);

    B  = vec_packclp (B0,B1);



    switch(c->dstFormat) {

      case PIX_FMT_ABGR: out_abgr (R,G,B,out); break;

      case PIX_FMT_BGRA: out_bgra (R,G,B,out); break;

      case PIX_FMT_RGBA: out_rgba (R,G,B,out); break;

      case PIX_FMT_ARGB: out_argb (R,G,B,out); break;

      case PIX_FMT_RGB24: out_rgb24 (R,G,B,out); break;

      case PIX_FMT_BGR24: out_bgr24 (R,G,B,out); break;

      default:

        {

          /* If this is reached, the caller should have called yuv2packedXinC

             instead. */

          static int printed_error_message;

          if(!printed_error_message) {

            av_log(c, AV_LOG_ERROR, "altivec_yuv2packedX doesn't support %s output\n",

                    sws_format_name(c->dstFormat));

            printed_error_message=1;

          }

          return;

        }

    }

  }



  if (i < dstW) {

    i -= 16;



    Y0 = RND;

    Y1 = RND;

    /* extract 16 coeffs from lumSrc */

    for(j=0; j<lumFilterSize; j++) {

      X0 = vec_ld (0,  &lumSrc[j][i]);

      X1 = vec_ld (16, &lumSrc[j][i]);

      Y0 = vec_mradds (X0, YCoeffs[j], Y0);

      Y1 = vec_mradds (X1, YCoeffs[j], Y1);

    }



    U = RND;

    V = RND;

    /* extract 8 coeffs from U,V */

    for(j=0; j<chrFilterSize; j++) {

      X  = vec_ld (0, &chrSrc[j][i/2]);

      U  = vec_mradds (X, CCoeffs[j], U);

      X  = vec_ld (0, &chrSrc[j][i/2+2048]);

      V  = vec_mradds (X, CCoeffs[j], V);

    }



    /* scale and clip signals */

    Y0 = vec_sra (Y0, SCL);

    Y1 = vec_sra (Y1, SCL);

    U  = vec_sra (U,  SCL);

    V  = vec_sra (V,  SCL);



    Y0 = vec_clip_s16 (Y0);

    Y1 = vec_clip_s16 (Y1);

    U  = vec_clip_s16 (U);

    V  = vec_clip_s16 (V);



    /* now we have

       Y0= y0 y1 y2 y3 y4 y5 y6 y7     Y1= y8 y9 y10 y11 y12 y13 y14 y15

       U= u0 u1 u2 u3 u4 u5 u6 u7      V= v0 v1 v2 v3 v4 v5 v6 v7



       Y0= y0 y1 y2 y3 y4 y5 y6 y7    Y1= y8 y9 y10 y11 y12 y13 y14 y15

       U0= u0 u0 u1 u1 u2 u2 u3 u3    U1= u4 u4 u5 u5 u6 u6 u7 u7

       V0= v0 v0 v1 v1 v2 v2 v3 v3    V1= v4 v4 v5 v5 v6 v6 v7 v7

    */



    U0 = vec_mergeh (U,U);

    V0 = vec_mergeh (V,V);



    U1 = vec_mergel (U,U);

    V1 = vec_mergel (V,V);



    cvtyuvtoRGB (c, Y0,U0,V0,&R0,&G0,&B0);

    cvtyuvtoRGB (c, Y1,U1,V1,&R1,&G1,&B1);



    R  = vec_packclp (R0,R1);

    G  = vec_packclp (G0,G1);

    B  = vec_packclp (B0,B1);



    nout = (vector unsigned char *)scratch;

    switch(c->dstFormat) {

      case PIX_FMT_ABGR: out_abgr (R,G,B,nout); break;

      case PIX_FMT_BGRA: out_bgra (R,G,B,nout); break;

      case PIX_FMT_RGBA: out_rgba (R,G,B,nout); break;

      case PIX_FMT_ARGB: out_argb (R,G,B,nout); break;

      case PIX_FMT_RGB24: out_rgb24 (R,G,B,nout); break;

      case PIX_FMT_BGR24: out_bgr24 (R,G,B,nout); break;

      default:

        /* Unreachable, I think. */

        av_log(c, AV_LOG_ERROR, "altivec_yuv2packedX doesn't support %s output\n",

                sws_format_name(c->dstFormat));

        return;

    }



    memcpy (&((uint32_t*)dest)[i], scratch, (dstW-i)/4);

  }



}

