static void copy_frame(J2kEncoderContext *s)

{

    int tileno, compno, i, y, x;

    uint8_t *line;

    for (tileno = 0; tileno < s->numXtiles * s->numYtiles; tileno++){

        J2kTile *tile = s->tile + tileno;

        if (s->planar){

            for (compno = 0; compno < s->ncomponents; compno++){

                J2kComponent *comp = tile->comp + compno;

                int *dst = comp->data;

                line = s->picture->data[compno]

                       + comp->coord[1][0] * s->picture->linesize[compno]

                       + comp->coord[0][0];

                for (y = comp->coord[1][0]; y < comp->coord[1][1]; y++){

                    uint8_t *ptr = line;

                    for (x = comp->coord[0][0]; x < comp->coord[0][1]; x++)

                        *dst++ = *ptr++ - (1 << 7);

                    line += s->picture->linesize[compno];

                }

            }

        } else{

            line = s->picture->data[0] + tile->comp[0].coord[1][0] * s->picture->linesize[0]

                   + tile->comp[0].coord[0][0] * s->ncomponents;



            i = 0;

            for (y = tile->comp[0].coord[1][0]; y < tile->comp[0].coord[1][1]; y++){

                uint8_t *ptr = line;

                for (x = tile->comp[0].coord[0][0]; x < tile->comp[0].coord[0][1]; x++, i++){

                    for (compno = 0; compno < s->ncomponents; compno++){

                        tile->comp[compno].data[i] = *ptr++  - (1 << 7);

                    }

                }

                line += s->picture->linesize[0];

            }

        }

    }

}

static int av_seek_frame_generic(AVFormatContext *s,

                                 int stream_index, int64_t timestamp, int flags)

{

    int index;

    AVStream *st;

    AVIndexEntry *ie;



    st = s->streams[stream_index];



    index = av_index_search_timestamp(st, timestamp, flags);



    if(index < 0 || index==st->nb_index_entries-1){

        int i;

        AVPacket pkt;



        if(st->nb_index_entries){

            assert(st->index_entries);

            ie= &st->index_entries[st->nb_index_entries-1];

            url_fseek(s->pb, ie->pos, SEEK_SET);

            av_update_cur_dts(s, st, ie->timestamp);

        }else

            url_fseek(s->pb, 0, SEEK_SET);



        for(i=0;; i++) {

            int ret = av_read_frame(s, &pkt);

            if(ret<0)

                break;

            av_free_packet(&pkt);

            if(stream_index == pkt.stream_index){

                if((pkt.flags & PKT_FLAG_KEY) && pkt.dts > timestamp)

                    break;

            }

        }

        index = av_index_search_timestamp(st, timestamp, flags);

    }

    if (index < 0)

        return -1;



    av_read_frame_flush(s);

    if (s->iformat->read_seek){

        if(s->iformat->read_seek(s, stream_index, timestamp, flags) >= 0)

            return 0;

    }

    ie = &st->index_entries[index];

    url_fseek(s->pb, ie->pos, SEEK_SET);



    av_update_cur_dts(s, st, ie->timestamp);



    return 0;

}

static int ogg_read_packet(AVFormatContext *s, AVPacket *pkt)

{

    struct ogg *ogg;

    struct ogg_stream *os;

    int idx, ret;

    int pstart, psize;

    int64_t fpos, pts, dts;



    if (s->io_repositioned) {

        ogg_reset(s);

        s->io_repositioned = 0;




    //Get an ogg packet

retry:

    do {

        ret = ogg_packet(s, &idx, &pstart, &psize, &fpos);

        if (ret < 0)

            return ret;

    } while (idx < 0 || !s->streams[idx]);



    ogg = s->priv_data;

    os  = ogg->streams + idx;



    // pflags might not be set until after this

    pts = ogg_calc_pts(s, idx, &dts);

    ogg_validate_keyframe(s, idx, pstart, psize);



    if (os->keyframe_seek && !(os->pflags & AV_PKT_FLAG_KEY))

        goto retry;

    os->keyframe_seek = 0;



    //Alloc a pkt

    ret = av_new_packet(pkt, psize);

    if (ret < 0)

        return ret;

    pkt->stream_index = idx;

    memcpy(pkt->data, os->buf + pstart, psize);



    pkt->pts      = pts;

    pkt->dts      = dts;

    pkt->flags    = os->pflags;

    pkt->duration = os->pduration;

    pkt->pos      = fpos;



    if (os->end_trimming) {

        uint8_t *side_data = av_packet_new_side_data(pkt,

                                                     AV_PKT_DATA_SKIP_SAMPLES,

                                                     10);






        AV_WL32(side_data + 4, os->end_trimming);

        os->end_trimming = 0;




    if (os->new_metadata) {

        uint8_t *side_data = av_packet_new_side_data(pkt,

                                                     AV_PKT_DATA_METADATA_UPDATE,

                                                     os->new_metadata_size);






        memcpy(side_data, os->new_metadata, os->new_metadata_size);

        av_freep(&os->new_metadata);

        os->new_metadata_size = 0;




    return psize;

static int read_sl_header(PESContext *pes, SLConfigDescr *sl,

                          const uint8_t *buf, int buf_size)

{

    GetBitContext gb;

    int au_start_flag = 0, au_end_flag = 0, ocr_flag = 0, idle_flag = 0;

    int padding_flag = 0, padding_bits = 0, inst_bitrate_flag = 0;

    int dts_flag = -1, cts_flag = -1;

    int64_t dts = AV_NOPTS_VALUE, cts = AV_NOPTS_VALUE;



    init_get_bits(&gb, buf, buf_size * 8);



    if (sl->use_au_start)

        au_start_flag = get_bits1(&gb);

    if (sl->use_au_end)

        au_end_flag = get_bits1(&gb);

    if (!sl->use_au_start && !sl->use_au_end)

        au_start_flag = au_end_flag = 1;

    if (sl->ocr_len > 0)

        ocr_flag = get_bits1(&gb);

    if (sl->use_idle)

        idle_flag = get_bits1(&gb);

    if (sl->use_padding)

        padding_flag = get_bits1(&gb);

    if (padding_flag)

        padding_bits = get_bits(&gb, 3);



    if (!idle_flag && (!padding_flag || padding_bits != 0)) {

        if (sl->packet_seq_num_len)

            skip_bits_long(&gb, sl->packet_seq_num_len);

        if (sl->degr_prior_len)

            if (get_bits1(&gb))

                skip_bits(&gb, sl->degr_prior_len);

        if (ocr_flag)

            skip_bits_long(&gb, sl->ocr_len);

        if (au_start_flag) {

            if (sl->use_rand_acc_pt)

                get_bits1(&gb);

            if (sl->au_seq_num_len > 0)

                skip_bits_long(&gb, sl->au_seq_num_len);

            if (sl->use_timestamps) {

                dts_flag = get_bits1(&gb);

                cts_flag = get_bits1(&gb);

            }

        }

        if (sl->inst_bitrate_len)

            inst_bitrate_flag = get_bits1(&gb);

        if (dts_flag == 1)

            dts = get_ts64(&gb, sl->timestamp_len);

        if (cts_flag == 1)

            cts = get_ts64(&gb, sl->timestamp_len);

        if (sl->au_len > 0)

            skip_bits_long(&gb, sl->au_len);

        if (inst_bitrate_flag)

            skip_bits_long(&gb, sl->inst_bitrate_len);

    }



    if (dts != AV_NOPTS_VALUE)

        pes->dts = dts;

    if (cts != AV_NOPTS_VALUE)

        pes->pts = cts;



    if (sl->timestamp_len && sl->timestamp_res)

        avpriv_set_pts_info(pes->st, sl->timestamp_len, 1, sl->timestamp_res);



    return (get_bits_count(&gb) + 7) >> 3;

}

static int decode_nal_unit(HEVCContext *s, const H2645NAL *nal)

{

    HEVCLocalContext *lc = s->HEVClc;

    GetBitContext *gb    = &lc->gb;

    int ctb_addr_ts, ret;



    *gb              = nal->gb;

    s->nal_unit_type = nal->type;

    s->temporal_id   = nal->temporal_id;



    switch (s->nal_unit_type) {

    case HEVC_NAL_VPS:

        ret = ff_hevc_decode_nal_vps(gb, s->avctx, &s->ps);

        if (ret < 0)

            goto fail;

        break;

    case HEVC_NAL_SPS:

        ret = ff_hevc_decode_nal_sps(gb, s->avctx, &s->ps,

                                     s->apply_defdispwin);

        if (ret < 0)

            goto fail;

        break;

    case HEVC_NAL_PPS:

        ret = ff_hevc_decode_nal_pps(gb, s->avctx, &s->ps);

        if (ret < 0)

            goto fail;

        break;

    case HEVC_NAL_SEI_PREFIX:

    case HEVC_NAL_SEI_SUFFIX:

        ret = ff_hevc_decode_nal_sei(s);

        if (ret < 0)

            goto fail;

        break;

    case HEVC_NAL_TRAIL_R:

    case HEVC_NAL_TRAIL_N:

    case HEVC_NAL_TSA_N:

    case HEVC_NAL_TSA_R:

    case HEVC_NAL_STSA_N:

    case HEVC_NAL_STSA_R:

    case HEVC_NAL_BLA_W_LP:

    case HEVC_NAL_BLA_W_RADL:

    case HEVC_NAL_BLA_N_LP:

    case HEVC_NAL_IDR_W_RADL:

    case HEVC_NAL_IDR_N_LP:

    case HEVC_NAL_CRA_NUT:

    case HEVC_NAL_RADL_N:

    case HEVC_NAL_RADL_R:

    case HEVC_NAL_RASL_N:

    case HEVC_NAL_RASL_R:

        ret = hls_slice_header(s);

        if (ret < 0)

            return ret;



        if (s->max_ra == INT_MAX) {

            if (s->nal_unit_type == HEVC_NAL_CRA_NUT || IS_BLA(s)) {

                s->max_ra = s->poc;

            } else {

                if (IS_IDR(s))

                    s->max_ra = INT_MIN;

            }

        }



        if ((s->nal_unit_type == HEVC_NAL_RASL_R || s->nal_unit_type == HEVC_NAL_RASL_N) &&

            s->poc <= s->max_ra) {

            s->is_decoded = 0;

            break;

        } else {

            if (s->nal_unit_type == HEVC_NAL_RASL_R && s->poc > s->max_ra)

                s->max_ra = INT_MIN;

        }



        if (s->sh.first_slice_in_pic_flag) {

            ret = hevc_frame_start(s);

            if (ret < 0)

                return ret;

        } else if (!s->ref) {

            av_log(s->avctx, AV_LOG_ERROR, "First slice in a frame missing.\n");

            goto fail;

        }



        if (s->nal_unit_type != s->first_nal_type) {

            av_log(s->avctx, AV_LOG_ERROR,

                   "Non-matching NAL types of the VCL NALUs: %d %d\n",

                   s->first_nal_type, s->nal_unit_type);

            return AVERROR_INVALIDDATA;

        }



        if (!s->sh.dependent_slice_segment_flag &&

            s->sh.slice_type != HEVC_SLICE_I) {

            ret = ff_hevc_slice_rpl(s);

            if (ret < 0) {

                av_log(s->avctx, AV_LOG_WARNING,

                       "Error constructing the reference lists for the current slice.\n");

                goto fail;

            }

        }



        if (s->sh.first_slice_in_pic_flag && s->avctx->hwaccel) {

            ret = s->avctx->hwaccel->start_frame(s->avctx, NULL, 0);

            if (ret < 0)

                goto fail;

        }



        if (s->avctx->hwaccel) {

            ret = s->avctx->hwaccel->decode_slice(s->avctx, nal->raw_data, nal->raw_size);

            if (ret < 0)

                goto fail;

        } else {

            if (s->threads_number > 1 && s->sh.num_entry_point_offsets > 0)

                ctb_addr_ts = hls_slice_data_wpp(s, nal);

            else

                ctb_addr_ts = hls_slice_data(s);

            if (ctb_addr_ts >= (s->ps.sps->ctb_width * s->ps.sps->ctb_height)) {

                s->is_decoded = 1;

            }



            if (ctb_addr_ts < 0) {

                ret = ctb_addr_ts;

                goto fail;

            }

        }

        break;

    case HEVC_NAL_EOS_NUT:

    case HEVC_NAL_EOB_NUT:

        s->seq_decode = (s->seq_decode + 1) & 0xff;

        s->max_ra     = INT_MAX;

        break;

    case HEVC_NAL_AUD:

    case HEVC_NAL_FD_NUT:

        break;

    default:

        av_log(s->avctx, AV_LOG_INFO,

               "Skipping NAL unit %d\n", s->nal_unit_type);

    }



    return 0;

fail:

    if (s->avctx->err_recognition & AV_EF_EXPLODE)

        return ret;

    return 0;

}

static int adpcm_decode_frame(AVCodecContext *avctx, void *data,

                              int *got_frame_ptr, AVPacket *avpkt)

{

    const uint8_t *buf = avpkt->data;

    int buf_size = avpkt->size;

    ADPCMDecodeContext *c = avctx->priv_data;

    ADPCMChannelStatus *cs;

    int n, m, channel, i;

    short *samples;

    const uint8_t *src;

    int st; /* stereo */

    int count1, count2;

    int nb_samples, coded_samples, ret;



    nb_samples = get_nb_samples(avctx, buf, buf_size, &coded_samples);

    if (nb_samples <= 0) {

        av_log(avctx, AV_LOG_ERROR, "invalid number of samples in packet\n");

        return AVERROR_INVALIDDATA;

    }



    /* get output buffer */

    c->frame.nb_samples = nb_samples;

    if ((ret = avctx->get_buffer(avctx, &c->frame)) < 0) {

        av_log(avctx, AV_LOG_ERROR, "get_buffer() failed\n");

        return ret;

    }

    samples = (short *)c->frame.data[0];



    /* use coded_samples when applicable */

    /* it is always <= nb_samples, so the output buffer will be large enough */

    if (coded_samples) {

        if (coded_samples != nb_samples)

            av_log(avctx, AV_LOG_WARNING, "mismatch in coded sample count\n");

        c->frame.nb_samples = nb_samples = coded_samples;

    }



    src = buf;



    st = avctx->channels == 2 ? 1 : 0;



    switch(avctx->codec->id) {

    case CODEC_ID_ADPCM_IMA_QT:

        /* In QuickTime, IMA is encoded by chunks of 34 bytes (=64 samples).

           Channel data is interleaved per-chunk. */

        for (channel = 0; channel < avctx->channels; channel++) {

            int16_t predictor;

            int step_index;

            cs = &(c->status[channel]);

            /* (pppppp) (piiiiiii) */



            /* Bits 15-7 are the _top_ 9 bits of the 16-bit initial predictor value */

            predictor = AV_RB16(src);

            step_index = predictor & 0x7F;

            predictor &= 0xFF80;



            src += 2;



            if (cs->step_index == step_index) {

                int diff = (int)predictor - cs->predictor;

                if (diff < 0)

                    diff = - diff;

                if (diff > 0x7f)

                    goto update;

            } else {

            update:

                cs->step_index = step_index;

                cs->predictor = predictor;

            }



            if (cs->step_index > 88){

                av_log(avctx, AV_LOG_ERROR, "ERROR: step_index = %i\n", cs->step_index);

                cs->step_index = 88;

            }



            samples = (short *)c->frame.data[0] + channel;



            for (m = 0; m < 32; m++) {

                *samples = adpcm_ima_qt_expand_nibble(cs, src[0] & 0x0F, 3);

                samples += avctx->channels;

                *samples = adpcm_ima_qt_expand_nibble(cs, src[0] >> 4  , 3);

                samples += avctx->channels;

                src ++;

            }

        }

        break;

    case CODEC_ID_ADPCM_IMA_WAV:

        if (avctx->block_align != 0 && buf_size > avctx->block_align)

            buf_size = avctx->block_align;



        for(i=0; i<avctx->channels; i++){

            cs = &(c->status[i]);

            cs->predictor = *samples++ = (int16_t)bytestream_get_le16(&src);



            cs->step_index = *src++;

            if (cs->step_index > 88){

                av_log(avctx, AV_LOG_ERROR, "ERROR: step_index = %i\n", cs->step_index);

                cs->step_index = 88;

            }

            if (*src++) av_log(avctx, AV_LOG_ERROR, "unused byte should be null but is %d!!\n", src[-1]); /* unused */

        }



        for (n = (nb_samples - 1) / 8; n > 0; n--) {

            for (i = 0; i < avctx->channels; i++) {

                cs = &c->status[i];

                for (m = 0; m < 4; m++) {

                    uint8_t v = *src++;

                    *samples = adpcm_ima_expand_nibble(cs, v & 0x0F, 3);

                    samples += avctx->channels;

                    *samples = adpcm_ima_expand_nibble(cs, v >> 4  , 3);

                    samples += avctx->channels;

                }

                samples -= 8 * avctx->channels - 1;

            }

            samples += 7 * avctx->channels;

        }

        break;

    case CODEC_ID_ADPCM_4XM:

        for (i = 0; i < avctx->channels; i++)

            c->status[i].predictor= (int16_t)bytestream_get_le16(&src);



        for (i = 0; i < avctx->channels; i++) {

            c->status[i].step_index= (int16_t)bytestream_get_le16(&src);

            c->status[i].step_index = av_clip(c->status[i].step_index, 0, 88);

        }



        for (i = 0; i < avctx->channels; i++) {

            samples = (short *)c->frame.data[0] + i;

            cs = &c->status[i];

            for (n = nb_samples >> 1; n > 0; n--, src++) {

                uint8_t v = *src;

                *samples = adpcm_ima_expand_nibble(cs, v & 0x0F, 4);

                samples += avctx->channels;

                *samples = adpcm_ima_expand_nibble(cs, v >> 4  , 4);

                samples += avctx->channels;

            }

        }

        break;

    case CODEC_ID_ADPCM_MS:

    {

        int block_predictor;



        if (avctx->block_align != 0 && buf_size > avctx->block_align)

            buf_size = avctx->block_align;



        block_predictor = av_clip(*src++, 0, 6);

        c->status[0].coeff1 = ff_adpcm_AdaptCoeff1[block_predictor];

        c->status[0].coeff2 = ff_adpcm_AdaptCoeff2[block_predictor];

        if (st) {

            block_predictor = av_clip(*src++, 0, 6);

            c->status[1].coeff1 = ff_adpcm_AdaptCoeff1[block_predictor];

            c->status[1].coeff2 = ff_adpcm_AdaptCoeff2[block_predictor];

        }

        c->status[0].idelta = (int16_t)bytestream_get_le16(&src);

        if (st){

            c->status[1].idelta = (int16_t)bytestream_get_le16(&src);

        }



        c->status[0].sample1 = bytestream_get_le16(&src);

        if (st) c->status[1].sample1 = bytestream_get_le16(&src);

        c->status[0].sample2 = bytestream_get_le16(&src);

        if (st) c->status[1].sample2 = bytestream_get_le16(&src);



        *samples++ = c->status[0].sample2;

        if (st) *samples++ = c->status[1].sample2;

        *samples++ = c->status[0].sample1;

        if (st) *samples++ = c->status[1].sample1;

        for(n = (nb_samples - 2) >> (1 - st); n > 0; n--, src++) {

            *samples++ = adpcm_ms_expand_nibble(&c->status[0 ], src[0] >> 4  );

            *samples++ = adpcm_ms_expand_nibble(&c->status[st], src[0] & 0x0F);

        }

        break;

    }

    case CODEC_ID_ADPCM_IMA_DK4:

        if (avctx->block_align != 0 && buf_size > avctx->block_align)

            buf_size = avctx->block_align;



        for (channel = 0; channel < avctx->channels; channel++) {

            cs = &c->status[channel];

            cs->predictor  = (int16_t)bytestream_get_le16(&src);

            cs->step_index = av_clip(*src++, 0, 88);

            src++;

            *samples++ = cs->predictor;

        }

        for (n = nb_samples >> (1 - st); n > 0; n--, src++) {

            uint8_t v = *src;

            *samples++ = adpcm_ima_expand_nibble(&c->status[0 ], v >> 4  , 3);

            *samples++ = adpcm_ima_expand_nibble(&c->status[st], v & 0x0F, 3);

        }

        break;

    case CODEC_ID_ADPCM_IMA_DK3:

    {

        unsigned char last_byte = 0;

        unsigned char nibble;

        int decode_top_nibble_next = 0;

        int end_of_packet = 0;

        int diff_channel;



        if (avctx->block_align != 0 && buf_size > avctx->block_align)

            buf_size = avctx->block_align;



        c->status[0].predictor  = (int16_t)AV_RL16(src + 10);

        c->status[1].predictor  = (int16_t)AV_RL16(src + 12);

        c->status[0].step_index = av_clip(src[14], 0, 88);

        c->status[1].step_index = av_clip(src[15], 0, 88);

        /* sign extend the predictors */

        src += 16;

        diff_channel = c->status[1].predictor;



        /* the DK3_GET_NEXT_NIBBLE macro issues the break statement when

         * the buffer is consumed */

        while (1) {



            /* for this algorithm, c->status[0] is the sum channel and

             * c->status[1] is the diff channel */



            /* process the first predictor of the sum channel */

            DK3_GET_NEXT_NIBBLE();

            adpcm_ima_expand_nibble(&c->status[0], nibble, 3);



            /* process the diff channel predictor */

            DK3_GET_NEXT_NIBBLE();

            adpcm_ima_expand_nibble(&c->status[1], nibble, 3);



            /* process the first pair of stereo PCM samples */

            diff_channel = (diff_channel + c->status[1].predictor) / 2;

            *samples++ = c->status[0].predictor + c->status[1].predictor;

            *samples++ = c->status[0].predictor - c->status[1].predictor;



            /* process the second predictor of the sum channel */

            DK3_GET_NEXT_NIBBLE();

            adpcm_ima_expand_nibble(&c->status[0], nibble, 3);



            /* process the second pair of stereo PCM samples */

            diff_channel = (diff_channel + c->status[1].predictor) / 2;

            *samples++ = c->status[0].predictor + c->status[1].predictor;

            *samples++ = c->status[0].predictor - c->status[1].predictor;

        }

        break;

    }

    case CODEC_ID_ADPCM_IMA_ISS:

        for (channel = 0; channel < avctx->channels; channel++) {

            cs = &c->status[channel];

            cs->predictor  = (int16_t)bytestream_get_le16(&src);

            cs->step_index = av_clip(*src++, 0, 88);

            src++;

        }



        for (n = nb_samples >> (1 - st); n > 0; n--, src++) {

            uint8_t v1, v2;

            uint8_t v = *src;

            /* nibbles are swapped for mono */

            if (st) {

                v1 = v >> 4;

                v2 = v & 0x0F;

            } else {

                v2 = v >> 4;

                v1 = v & 0x0F;

            }

            *samples++ = adpcm_ima_expand_nibble(&c->status[0 ], v1, 3);

            *samples++ = adpcm_ima_expand_nibble(&c->status[st], v2, 3);

        }

        break;

    case CODEC_ID_ADPCM_IMA_APC:

        while (src < buf + buf_size) {

            uint8_t v = *src++;

            *samples++ = adpcm_ima_expand_nibble(&c->status[0],  v >> 4  , 3);

            *samples++ = adpcm_ima_expand_nibble(&c->status[st], v & 0x0F, 3);

        }

        break;

    case CODEC_ID_ADPCM_IMA_WS:

        for (channel = 0; channel < avctx->channels; channel++) {

            const uint8_t *src0;

            int src_stride;

            int16_t *smp = samples + channel;



            if (c->vqa_version == 3) {

                src0 = src + channel * buf_size / 2;

                src_stride = 1;

            } else {

                src0 = src + channel;

                src_stride = avctx->channels;

            }

            for (n = nb_samples / 2; n > 0; n--) {

                uint8_t v = *src0;

                src0 += src_stride;

                *smp = adpcm_ima_expand_nibble(&c->status[channel], v >> 4  , 3);

                smp += avctx->channels;

                *smp = adpcm_ima_expand_nibble(&c->status[channel], v & 0x0F, 3);

                smp += avctx->channels;

            }

        }

        src = buf + buf_size;

        break;

    case CODEC_ID_ADPCM_XA:

        while (buf_size >= 128) {

            xa_decode(samples, src, &c->status[0], &c->status[1],

                avctx->channels);

            src += 128;

            samples += 28 * 8;

            buf_size -= 128;

        }

        break;

    case CODEC_ID_ADPCM_IMA_EA_EACS:

        src += 4; // skip sample count (already read)



        for (i=0; i<=st; i++)

            c->status[i].step_index = av_clip(bytestream_get_le32(&src), 0, 88);

        for (i=0; i<=st; i++)

            c->status[i].predictor  = bytestream_get_le32(&src);



        for (n = nb_samples >> (1 - st); n > 0; n--, src++) {

            *samples++ = adpcm_ima_expand_nibble(&c->status[0],  *src>>4,   3);

            *samples++ = adpcm_ima_expand_nibble(&c->status[st], *src&0x0F, 3);

        }

        break;

    case CODEC_ID_ADPCM_IMA_EA_SEAD:

        for (n = nb_samples >> (1 - st); n > 0; n--, src++) {

            *samples++ = adpcm_ima_expand_nibble(&c->status[0], src[0] >> 4, 6);

            *samples++ = adpcm_ima_expand_nibble(&c->status[st],src[0]&0x0F, 6);

        }

        break;

    case CODEC_ID_ADPCM_EA:

    {

        int32_t previous_left_sample, previous_right_sample;

        int32_t current_left_sample, current_right_sample;

        int32_t next_left_sample, next_right_sample;

        int32_t coeff1l, coeff2l, coeff1r, coeff2r;

        uint8_t shift_left, shift_right;



        /* Each EA ADPCM frame has a 12-byte header followed by 30-byte pieces,

           each coding 28 stereo samples. */



        src += 4; // skip sample count (already read)



        current_left_sample   = (int16_t)bytestream_get_le16(&src);

        previous_left_sample  = (int16_t)bytestream_get_le16(&src);

        current_right_sample  = (int16_t)bytestream_get_le16(&src);

        previous_right_sample = (int16_t)bytestream_get_le16(&src);



        for (count1 = 0; count1 < nb_samples / 28; count1++) {

            coeff1l = ea_adpcm_table[ *src >> 4       ];

            coeff2l = ea_adpcm_table[(*src >> 4  ) + 4];

            coeff1r = ea_adpcm_table[*src & 0x0F];

            coeff2r = ea_adpcm_table[(*src & 0x0F) + 4];

            src++;



            shift_left  = 20 - (*src >> 4);

            shift_right = 20 - (*src & 0x0F);

            src++;



            for (count2 = 0; count2 < 28; count2++) {

                next_left_sample  = sign_extend(*src >> 4, 4) << shift_left;

                next_right_sample = sign_extend(*src,      4) << shift_right;

                src++;



                next_left_sample = (next_left_sample +

                    (current_left_sample * coeff1l) +

                    (previous_left_sample * coeff2l) + 0x80) >> 8;

                next_right_sample = (next_right_sample +

                    (current_right_sample * coeff1r) +

                    (previous_right_sample * coeff2r) + 0x80) >> 8;



                previous_left_sample = current_left_sample;

                current_left_sample = av_clip_int16(next_left_sample);

                previous_right_sample = current_right_sample;

                current_right_sample = av_clip_int16(next_right_sample);

                *samples++ = (unsigned short)current_left_sample;

                *samples++ = (unsigned short)current_right_sample;

            }

        }



        if (src - buf == buf_size - 2)

            src += 2; // Skip terminating 0x0000



        break;

    }

    case CODEC_ID_ADPCM_EA_MAXIS_XA:

    {

        int coeff[2][2], shift[2];



        for(channel = 0; channel < avctx->channels; channel++) {

            for (i=0; i<2; i++)

                coeff[channel][i] = ea_adpcm_table[(*src >> 4) + 4*i];

            shift[channel] = 20 - (*src & 0x0F);

            src++;

        }

        for (count1 = 0; count1 < nb_samples / 2; count1++) {

            for(i = 4; i >= 0; i-=4) { /* Pairwise samples LL RR (st) or LL LL (mono) */

                for(channel = 0; channel < avctx->channels; channel++) {

                    int32_t sample = sign_extend(src[channel] >> i, 4) << shift[channel];

                    sample = (sample +

                             c->status[channel].sample1 * coeff[channel][0] +

                             c->status[channel].sample2 * coeff[channel][1] + 0x80) >> 8;

                    c->status[channel].sample2 = c->status[channel].sample1;

                    c->status[channel].sample1 = av_clip_int16(sample);

                    *samples++ = c->status[channel].sample1;

                }

            }

            src+=avctx->channels;

        }

        /* consume whole packet */

        src = buf + buf_size;

        break;

    }

    case CODEC_ID_ADPCM_EA_R1:

    case CODEC_ID_ADPCM_EA_R2:

    case CODEC_ID_ADPCM_EA_R3: {

        /* channel numbering

           2chan: 0=fl, 1=fr

           4chan: 0=fl, 1=rl, 2=fr, 3=rr

           6chan: 0=fl, 1=c,  2=fr, 3=rl,  4=rr, 5=sub */

        const int big_endian = avctx->codec->id == CODEC_ID_ADPCM_EA_R3;

        int32_t previous_sample, current_sample, next_sample;

        int32_t coeff1, coeff2;

        uint8_t shift;

        unsigned int channel;

        uint16_t *samplesC;

        const uint8_t *srcC;

        const uint8_t *src_end = buf + buf_size;

        int count = 0;



        src += 4; // skip sample count (already read)



        for (channel=0; channel<avctx->channels; channel++) {

            int32_t offset = (big_endian ? bytestream_get_be32(&src)

                                         : bytestream_get_le32(&src))

                           + (avctx->channels-channel-1) * 4;



            if ((offset < 0) || (offset >= src_end - src - 4)) break;

            srcC  = src + offset;

            samplesC = samples + channel;



            if (avctx->codec->id == CODEC_ID_ADPCM_EA_R1) {

                current_sample  = (int16_t)bytestream_get_le16(&srcC);

                previous_sample = (int16_t)bytestream_get_le16(&srcC);

            } else {

                current_sample  = c->status[channel].predictor;

                previous_sample = c->status[channel].prev_sample;

            }



            for (count1 = 0; count1 < nb_samples / 28; count1++) {

                if (*srcC == 0xEE) {  /* only seen in R2 and R3 */

                    srcC++;

                    if (srcC > src_end - 30*2) break;

                    current_sample  = (int16_t)bytestream_get_be16(&srcC);

                    previous_sample = (int16_t)bytestream_get_be16(&srcC);



                    for (count2=0; count2<28; count2++) {

                        *samplesC = (int16_t)bytestream_get_be16(&srcC);

                        samplesC += avctx->channels;

                    }

                } else {

                    coeff1 = ea_adpcm_table[ *srcC>>4     ];

                    coeff2 = ea_adpcm_table[(*srcC>>4) + 4];

                    shift = 20 - (*srcC++ & 0x0F);



                    if (srcC > src_end - 14) break;

                    for (count2=0; count2<28; count2++) {

                        if (count2 & 1)

                            next_sample = sign_extend(*srcC++,    4) << shift;

                        else

                            next_sample = sign_extend(*srcC >> 4, 4) << shift;



                        next_sample += (current_sample  * coeff1) +

                                       (previous_sample * coeff2);

                        next_sample = av_clip_int16(next_sample >> 8);



                        previous_sample = current_sample;

                        current_sample  = next_sample;

                        *samplesC = current_sample;

                        samplesC += avctx->channels;

                    }

                }

            }

            if (!count) {

                count = count1;

            } else if (count != count1) {

                av_log(avctx, AV_LOG_WARNING, "per-channel sample count mismatch\n");

                count = FFMAX(count, count1);

            }



            if (avctx->codec->id != CODEC_ID_ADPCM_EA_R1) {

                c->status[channel].predictor   = current_sample;

                c->status[channel].prev_sample = previous_sample;

            }

        }



        c->frame.nb_samples = count * 28;

        src = src_end;

        break;

    }

    case CODEC_ID_ADPCM_EA_XAS:

        for (channel=0; channel<avctx->channels; channel++) {

            int coeff[2][4], shift[4];

            short *s2, *s = &samples[channel];

            for (n=0; n<4; n++, s+=32*avctx->channels) {

                for (i=0; i<2; i++)

                    coeff[i][n] = ea_adpcm_table[(src[0]&0x0F)+4*i];

                shift[n] = 20 - (src[2] & 0x0F);

                for (s2=s, i=0; i<2; i++, src+=2, s2+=avctx->channels)

                    s2[0] = (src[0]&0xF0) + (src[1]<<8);

            }



            for (m=2; m<32; m+=2) {

                s = &samples[m*avctx->channels + channel];

                for (n=0; n<4; n++, src++, s+=32*avctx->channels) {

                    for (s2=s, i=0; i<8; i+=4, s2+=avctx->channels) {

                        int level = sign_extend(*src >> (4 - i), 4) << shift[n];

                        int pred  = s2[-1*avctx->channels] * coeff[0][n]

                                  + s2[-2*avctx->channels] * coeff[1][n];

                        s2[0] = av_clip_int16((level + pred + 0x80) >> 8);

                    }

                }

            }

        }

        break;

    case CODEC_ID_ADPCM_IMA_AMV:

    case CODEC_ID_ADPCM_IMA_SMJPEG:

        if (avctx->codec->id == CODEC_ID_ADPCM_IMA_AMV) {

            c->status[0].predictor = sign_extend(bytestream_get_le16(&src), 16);

            c->status[0].step_index = av_clip(bytestream_get_le16(&src), 0, 88);

            src += 4;

        } else {

            c->status[0].predictor = sign_extend(bytestream_get_be16(&src), 16);

            c->status[0].step_index = av_clip(bytestream_get_byte(&src), 0, 88);

            src += 1;

        }



        for (n = nb_samples >> (1 - st); n > 0; n--, src++) {

            char hi, lo;

            lo = *src & 0x0F;

            hi = *src >> 4;



            if (avctx->codec->id == CODEC_ID_ADPCM_IMA_AMV)

                FFSWAP(char, hi, lo);



            *samples++ = adpcm_ima_expand_nibble(&c->status[0],

                lo, 3);

            *samples++ = adpcm_ima_expand_nibble(&c->status[0],

                hi, 3);

        }

        break;

    case CODEC_ID_ADPCM_CT:

        for (n = nb_samples >> (1 - st); n > 0; n--, src++) {

            uint8_t v = *src;

            *samples++ = adpcm_ct_expand_nibble(&c->status[0 ], v >> 4  );

            *samples++ = adpcm_ct_expand_nibble(&c->status[st], v & 0x0F);

        }

        break;

    case CODEC_ID_ADPCM_SBPRO_4:

    case CODEC_ID_ADPCM_SBPRO_3:

    case CODEC_ID_ADPCM_SBPRO_2:

        if (!c->status[0].step_index) {

            /* the first byte is a raw sample */

            *samples++ = 128 * (*src++ - 0x80);

            if (st)

              *samples++ = 128 * (*src++ - 0x80);

            c->status[0].step_index = 1;

            nb_samples--;

        }

        if (avctx->codec->id == CODEC_ID_ADPCM_SBPRO_4) {

            for (n = nb_samples >> (1 - st); n > 0; n--, src++) {

                *samples++ = adpcm_sbpro_expand_nibble(&c->status[0],

                    src[0] >> 4, 4, 0);

                *samples++ = adpcm_sbpro_expand_nibble(&c->status[st],

                    src[0] & 0x0F, 4, 0);

            }

        } else if (avctx->codec->id == CODEC_ID_ADPCM_SBPRO_3) {

            for (n = nb_samples / 3; n > 0; n--, src++) {

                *samples++ = adpcm_sbpro_expand_nibble(&c->status[0],

                     src[0] >> 5        , 3, 0);

                *samples++ = adpcm_sbpro_expand_nibble(&c->status[0],

                    (src[0] >> 2) & 0x07, 3, 0);

                *samples++ = adpcm_sbpro_expand_nibble(&c->status[0],

                    src[0] & 0x03, 2, 0);

            }

        } else {

            for (n = nb_samples >> (2 - st); n > 0; n--, src++) {

                *samples++ = adpcm_sbpro_expand_nibble(&c->status[0],

                     src[0] >> 6        , 2, 2);

                *samples++ = adpcm_sbpro_expand_nibble(&c->status[st],

                    (src[0] >> 4) & 0x03, 2, 2);

                *samples++ = adpcm_sbpro_expand_nibble(&c->status[0],

                    (src[0] >> 2) & 0x03, 2, 2);

                *samples++ = adpcm_sbpro_expand_nibble(&c->status[st],

                    src[0] & 0x03, 2, 2);

            }

        }

        break;

    case CODEC_ID_ADPCM_SWF:

    {

        GetBitContext gb;

        const int *table;

        int k0, signmask, nb_bits, count;

        int size = buf_size*8;



        init_get_bits(&gb, buf, size);



        //read bits & initial values

        nb_bits = get_bits(&gb, 2)+2;

        //av_log(NULL,AV_LOG_INFO,"nb_bits: %d\n", nb_bits);

        table = swf_index_tables[nb_bits-2];

        k0 = 1 << (nb_bits-2);

        signmask = 1 << (nb_bits-1);



        while (get_bits_count(&gb) <= size - 22*avctx->channels) {

            for (i = 0; i < avctx->channels; i++) {

                *samples++ = c->status[i].predictor = get_sbits(&gb, 16);

                c->status[i].step_index = get_bits(&gb, 6);

            }



            for (count = 0; get_bits_count(&gb) <= size - nb_bits*avctx->channels && count < 4095; count++) {

                int i;



                for (i = 0; i < avctx->channels; i++) {

                    // similar to IMA adpcm

                    int delta = get_bits(&gb, nb_bits);

                    int step = ff_adpcm_step_table[c->status[i].step_index];

                    long vpdiff = 0; // vpdiff = (delta+0.5)*step/4

                    int k = k0;



                    do {

                        if (delta & k)

                            vpdiff += step;

                        step >>= 1;

                        k >>= 1;

                    } while(k);

                    vpdiff += step;



                    if (delta & signmask)

                        c->status[i].predictor -= vpdiff;

                    else

                        c->status[i].predictor += vpdiff;



                    c->status[i].step_index += table[delta & (~signmask)];



                    c->status[i].step_index = av_clip(c->status[i].step_index, 0, 88);

                    c->status[i].predictor = av_clip_int16(c->status[i].predictor);



                    *samples++ = c->status[i].predictor;

                }

            }

        }

        src += buf_size;

        break;

    }

    case CODEC_ID_ADPCM_YAMAHA:

        for (n = nb_samples >> (1 - st); n > 0; n--, src++) {

            uint8_t v = *src;

            *samples++ = adpcm_yamaha_expand_nibble(&c->status[0 ], v & 0x0F);

            *samples++ = adpcm_yamaha_expand_nibble(&c->status[st], v >> 4  );

        }

        break;

    case CODEC_ID_ADPCM_THP:

    {

        int table[2][16];

        int prev[2][2];

        int ch;



        src += 4; // skip channel size

        src += 4; // skip number of samples (already read)



        for (i = 0; i < 32; i++)

            table[0][i] = (int16_t)bytestream_get_be16(&src);



        /* Initialize the previous sample.  */

        for (i = 0; i < 4; i++)

            prev[0][i] = (int16_t)bytestream_get_be16(&src);



        for (ch = 0; ch <= st; ch++) {

            samples = (short *)c->frame.data[0] + ch;



            /* Read in every sample for this channel.  */

            for (i = 0; i < nb_samples / 14; i++) {

                int index = (*src >> 4) & 7;

                unsigned int exp = *src++ & 15;

                int factor1 = table[ch][index * 2];

                int factor2 = table[ch][index * 2 + 1];



                /* Decode 14 samples.  */

                for (n = 0; n < 14; n++) {

                    int32_t sampledat;

                    if(n&1) sampledat = sign_extend(*src++, 4);

                    else    sampledat = sign_extend(*src >> 4, 4);



                    sampledat = ((prev[ch][0]*factor1

                                + prev[ch][1]*factor2) >> 11) + (sampledat << exp);

                    *samples = av_clip_int16(sampledat);

                    prev[ch][1] = prev[ch][0];

                    prev[ch][0] = *samples++;



                    /* In case of stereo, skip one sample, this sample

                       is for the other channel.  */

                    samples += st;

                }

            }

        }

        break;

    }



    default:

        return -1;

    }



    *got_frame_ptr   = 1;

    *(AVFrame *)data = c->frame;



    return src - buf;

}

static void noise_scale(int *coefs, int scale, int band_energy, int len)

{

    int ssign = scale < 0 ? -1 : 1;

    int s = FFABS(scale);

    unsigned int round;

    int i, out, c = exp2tab[s & 3];

    int nlz = 0;



    while (band_energy > 0x7fff) {

        band_energy >>= 1;

        nlz++;

    }

    c /= band_energy;

    s = 21 + nlz - (s >> 2);



    if (s > 0) {

        round = 1 << (s-1);

        for (i=0; i<len; i++) {

            out = (int)(((int64_t)coefs[i] * c) >> 32);

            coefs[i] = ((int)(out+round) >> s) * ssign;

        }

    }

    else {

        s = s + 32;

        round = 1 << (s-1);

        for (i=0; i<len; i++) {

            out = (int)((int64_t)((int64_t)coefs[i] * c + round) >> s);

            coefs[i] = out * ssign;

        }

    }

}

int ff_dirac_golomb_read_16bit(DiracGolombLUT *lut_ctx, const uint8_t *buf,

                               int bytes, uint8_t *_dst, int coeffs)

{

    int i, b, c_idx = 0;

    int16_t *dst = (int16_t *)_dst;

    DiracGolombLUT *future[4], *l = &lut_ctx[2*LUT_SIZE + buf[0]];

    INIT_RESIDUE(res, 0, 0);



#define APPEND_RESIDUE(N, M)         \

    N          |= M >> (N ## _bits); \

    N ## _bits +=      (M ## _bits)



    for (b = 1; b <= bytes; b++) {

        future[0] = &lut_ctx[buf[b]];

        future[1] = future[0] + 1*LUT_SIZE;

        future[2] = future[0] + 2*LUT_SIZE;

        future[3] = future[0] + 3*LUT_SIZE;



        if ((c_idx + 1) > coeffs)

            return c_idx;



        if (res_bits && l->sign) {

            int32_t coeff = 1;

            APPEND_RESIDUE(res, l->preamble);

            for (i = 0; i < (res_bits >> 1) - 1; i++) {

                coeff <<= 1;

                coeff |= (res >> (RSIZE_BITS - 2*i - 2)) & 1;

            }

            dst[c_idx++] = l->sign * (coeff - 1);

            res_bits = res = 0;

        }



        for (i = 0; i < LUT_BITS; i++)

            dst[c_idx + i] = l->ready[i];

        c_idx += l->ready_num;



        APPEND_RESIDUE(res, l->leftover);



        l = future[l->need_s ? 3 : !res_bits ? 2 : res_bits & 1];

    }



    return c_idx;

}

int ff_draw_slice(AVFilterLink *link, int y, int h, int slice_dir)

{

    uint8_t *src[4], *dst[4];

    int i, j, vsub, ret;

    int (*draw_slice)(AVFilterLink *, int, int, int);



    FF_TPRINTF_START(NULL, draw_slice); ff_tlog_link(NULL, link, 0); ff_tlog(NULL, " y:%d h:%d dir:%d\n", y, h, slice_dir);



    /* copy the slice if needed for permission reasons */

    if (link->src_buf) {

        vsub = av_pix_fmt_descriptors[link->format].log2_chroma_h;



        for (i = 0; i < 4; i++) {

            if (link->src_buf->data[i]) {

                src[i] = link->src_buf-> data[i] +

                    (y >> (i==1 || i==2 ? vsub : 0)) * link->src_buf-> linesize[i];

                dst[i] = link->cur_buf->data[i] +

                    (y >> (i==1 || i==2 ? vsub : 0)) * link->cur_buf->linesize[i];

            } else

                src[i] = dst[i] = NULL;

        }



        for (i = 0; i < 4; i++) {

            int planew =

                av_image_get_linesize(link->format, link->cur_buf->video->w, i);



            if (!src[i]) continue;



            for (j = 0; j < h >> (i==1 || i==2 ? vsub : 0); j++) {

                memcpy(dst[i], src[i], planew);

                src[i] += link->src_buf->linesize[i];

                dst[i] += link->cur_buf->linesize[i];

            }

        }

    }



    if (!(draw_slice = link->dstpad->draw_slice))

        draw_slice = default_draw_slice;

    ret = draw_slice(link, y, h, slice_dir);

    if (ret < 0)

        clear_link(link);

    return ret;

}

static int rm_read_index(AVFormatContext *s)

{

    AVIOContext *pb = s->pb;

    unsigned int size, n_pkts, str_id, next_off, n, pos, pts;

    AVStream *st;



    do {

        if (avio_rl32(pb) != MKTAG('I','N','D','X'))

            return -1;

        size     = avio_rb32(pb);

        if (size < 20)

            return -1;

        avio_skip(pb, 2);

        n_pkts   = avio_rb32(pb);

        str_id   = avio_rb16(pb);

        next_off = avio_rb32(pb);

        for (n = 0; n < s->nb_streams; n++)

            if (s->streams[n]->id == str_id) {

                st = s->streams[n];

                break;

            }

        if (n == s->nb_streams)

            goto skip;



        for (n = 0; n < n_pkts; n++) {

            avio_skip(pb, 2);

            pts = avio_rb32(pb);

            pos = avio_rb32(pb);

            avio_skip(pb, 4); /* packet no. */



            av_add_index_entry(st, pos, pts, 0, 0, AVINDEX_KEYFRAME);

        }



skip:

        if (next_off && avio_tell(pb) != next_off &&

            avio_seek(pb, next_off, SEEK_SET) < 0)

            return -1;

    } while (next_off);



    return 0;

}

int ff_huff_gen_len_table(uint8_t *dst, const uint64_t *stats, int stats_size, int skip0)

{

    HeapElem *h  = av_malloc_array(sizeof(*h), stats_size);

    int *up      = av_malloc_array(sizeof(*up) * 2, stats_size);

    uint8_t *len = av_malloc_array(sizeof(*len) * 2, stats_size);

    uint16_t *map= av_malloc_array(sizeof(*map), stats_size);

    int offset, i, next;

    int size = 0;

    int ret = 0;



    if (!h || !up || !len) {

        ret = AVERROR(ENOMEM);

        goto end;

    }



    for (i = 0; i<stats_size; i++) {

        dst[i] = 255;

        if (stats[i] || !skip0)

            map[size++] = i;

    }



    for (offset = 1; ; offset <<= 1) {

        for (i=0; i < size; i++) {

            h[i].name = i;

            h[i].val = (stats[map[i]] << 14) + offset;

        }

        for (i = size / 2 - 1; i >= 0; i--)

            heap_sift(h, i, size);



        for (next = size; next < size * 2 - 1; next++) {

            // merge the two smallest entries, and put it back in the heap

            uint64_t min1v = h[0].val;

            up[h[0].name] = next;

            h[0].val = INT64_MAX;

            heap_sift(h, 0, size);

            up[h[0].name] = next;

            h[0].name = next;

            h[0].val += min1v;

            heap_sift(h, 0, size);

        }



        len[2 * size - 2] = 0;

        for (i = 2 * size - 3; i >= size; i--)

            len[i] = len[up[i]] + 1;

        for (i = 0; i < size; i++) {

            dst[map[i]] = len[up[i]] + 1;

            if (dst[map[i]] >= 32) break;

        }

        if (i==size) break;

    }

end:

    av_free(h);

    av_free(up);

    av_free(len);

    av_free(map);

    return ret;

}

dshow_cycle_pins(AVFormatContext *avctx, enum dshowDeviceType devtype,

                 IBaseFilter *device_filter, IPin **ppin)

{

    IEnumPins *pins = 0;

    IPin *device_pin = NULL;

    IPin *pin;

    int r;



    const GUID *mediatype[2] = { &MEDIATYPE_Video, &MEDIATYPE_Audio };

    const char *devtypename = (devtype == VideoDevice) ? "video" : "audio";



    r = IBaseFilter_EnumPins(device_filter, &pins);

    if (r != S_OK) {

        av_log(avctx, AV_LOG_ERROR, "Could not enumerate pins.\n");

        return AVERROR(EIO);

    }



    while (IEnumPins_Next(pins, 1, &pin, NULL) == S_OK && !device_pin) {

        IKsPropertySet *p = NULL;

        IEnumMediaTypes *types;

        PIN_INFO info = {0};

        AM_MEDIA_TYPE *type;

        GUID category;

        DWORD r2;



        IPin_QueryPinInfo(pin, &info);

        IBaseFilter_Release(info.pFilter);



        if (info.dir != PINDIR_OUTPUT)

            goto next;

        if (IPin_QueryInterface(pin, &IID_IKsPropertySet, (void **) &p) != S_OK)

            goto next;

        if (IKsPropertySet_Get(p, &AMPROPSETID_Pin, AMPROPERTY_PIN_CATEGORY,

                               NULL, 0, &category, sizeof(GUID), &r2) != S_OK)

            goto next;

        if (!IsEqualGUID(&category, &PIN_CATEGORY_CAPTURE))

            goto next;



        if (IPin_EnumMediaTypes(pin, &types) != S_OK)

            goto next;



        IEnumMediaTypes_Reset(types);

        while (IEnumMediaTypes_Next(types, 1, &type, NULL) == S_OK && !device_pin) {

            if (IsEqualGUID(&type->majortype, mediatype[devtype])) {

                device_pin = pin;

                goto next;

            }

            CoTaskMemFree(type);

        }



next:

        if (types)

            IEnumMediaTypes_Release(types);

        if (p)

            IKsPropertySet_Release(p);

        if (device_pin != pin)

            IPin_Release(pin);

    }



    IEnumPins_Release(pins);



    if (!device_pin) {

        av_log(avctx, AV_LOG_ERROR,

               "Could not find output pin from %s capture device.\n", devtypename);

        return AVERROR(EIO);

    }

    *ppin = device_pin;



    return 0;

}

static int vaapi_h264_start_frame(AVCodecContext          *avctx,

                                  av_unused const uint8_t *buffer,

                                  av_unused uint32_t       size)

{

    H264Context * const h = avctx->priv_data;

    struct vaapi_context * const vactx = avctx->hwaccel_context;

    VAPictureParameterBufferH264 *pic_param;

    VAIQMatrixBufferH264 *iq_matrix;



    ff_dlog(avctx, "vaapi_h264_start_frame()\n");



    vactx->slice_param_size = sizeof(VASliceParameterBufferH264);



    /* Fill in VAPictureParameterBufferH264. */

    pic_param = ff_vaapi_alloc_pic_param(vactx, sizeof(VAPictureParameterBufferH264));

    if (!pic_param)

        return -1;

    fill_vaapi_pic(&pic_param->CurrPic, h->cur_pic_ptr, h->picture_structure);

    if (fill_vaapi_ReferenceFrames(pic_param, h) < 0)

        return -1;

    pic_param->picture_width_in_mbs_minus1                      = h->mb_width - 1;

    pic_param->picture_height_in_mbs_minus1                     = h->mb_height - 1;

    pic_param->bit_depth_luma_minus8                            = h->sps.bit_depth_luma - 8;

    pic_param->bit_depth_chroma_minus8                          = h->sps.bit_depth_chroma - 8;

    pic_param->num_ref_frames                                   = h->sps.ref_frame_count;

    pic_param->seq_fields.value                                 = 0; /* reset all bits */

    pic_param->seq_fields.bits.chroma_format_idc                = h->sps.chroma_format_idc;

    pic_param->seq_fields.bits.residual_colour_transform_flag   = h->sps.residual_color_transform_flag; /* XXX: only for 4:4:4 high profile? */

    pic_param->seq_fields.bits.gaps_in_frame_num_value_allowed_flag = h->sps.gaps_in_frame_num_allowed_flag;

    pic_param->seq_fields.bits.frame_mbs_only_flag              = h->sps.frame_mbs_only_flag;

    pic_param->seq_fields.bits.mb_adaptive_frame_field_flag     = h->sps.mb_aff;

    pic_param->seq_fields.bits.direct_8x8_inference_flag        = h->sps.direct_8x8_inference_flag;

    pic_param->seq_fields.bits.MinLumaBiPredSize8x8             = h->sps.level_idc >= 31; /* A.3.3.2 */

    pic_param->seq_fields.bits.log2_max_frame_num_minus4        = h->sps.log2_max_frame_num - 4;

    pic_param->seq_fields.bits.pic_order_cnt_type               = h->sps.poc_type;

    pic_param->seq_fields.bits.log2_max_pic_order_cnt_lsb_minus4 = h->sps.log2_max_poc_lsb - 4;

    pic_param->seq_fields.bits.delta_pic_order_always_zero_flag = h->sps.delta_pic_order_always_zero_flag;

    pic_param->num_slice_groups_minus1                          = h->pps.slice_group_count - 1;

    pic_param->slice_group_map_type                             = h->pps.mb_slice_group_map_type;

    pic_param->slice_group_change_rate_minus1                   = 0; /* XXX: unimplemented in Libav */

    pic_param->pic_init_qp_minus26                              = h->pps.init_qp - 26;

    pic_param->pic_init_qs_minus26                              = h->pps.init_qs - 26;

    pic_param->chroma_qp_index_offset                           = h->pps.chroma_qp_index_offset[0];

    pic_param->second_chroma_qp_index_offset                    = h->pps.chroma_qp_index_offset[1];

    pic_param->pic_fields.value                                 = 0; /* reset all bits */

    pic_param->pic_fields.bits.entropy_coding_mode_flag         = h->pps.cabac;

    pic_param->pic_fields.bits.weighted_pred_flag               = h->pps.weighted_pred;

    pic_param->pic_fields.bits.weighted_bipred_idc              = h->pps.weighted_bipred_idc;

    pic_param->pic_fields.bits.transform_8x8_mode_flag          = h->pps.transform_8x8_mode;

    pic_param->pic_fields.bits.field_pic_flag                   = h->picture_structure != PICT_FRAME;

    pic_param->pic_fields.bits.constrained_intra_pred_flag      = h->pps.constrained_intra_pred;

    pic_param->pic_fields.bits.pic_order_present_flag           = h->pps.pic_order_present;

    pic_param->pic_fields.bits.deblocking_filter_control_present_flag = h->pps.deblocking_filter_parameters_present;

    pic_param->pic_fields.bits.redundant_pic_cnt_present_flag   = h->pps.redundant_pic_cnt_present;

    pic_param->pic_fields.bits.reference_pic_flag               = h->nal_ref_idc != 0;

    pic_param->frame_num                                        = h->frame_num;



    /* Fill in VAIQMatrixBufferH264. */

    iq_matrix = ff_vaapi_alloc_iq_matrix(vactx, sizeof(VAIQMatrixBufferH264));

    if (!iq_matrix)

        return -1;

    memcpy(iq_matrix->ScalingList4x4, h->pps.scaling_matrix4, sizeof(iq_matrix->ScalingList4x4));

    memcpy(iq_matrix->ScalingList8x8[0], h->pps.scaling_matrix8[0], sizeof(iq_matrix->ScalingList8x8[0]));

    memcpy(iq_matrix->ScalingList8x8[1], h->pps.scaling_matrix8[3], sizeof(iq_matrix->ScalingList8x8[0]));

    return 0;

}

static void print_report(OutputFile *output_files,

                         OutputStream *ost_table, int nb_ostreams,

                         int is_last_report, int64_t timer_start)

{

    char buf[1024];

    OutputStream *ost;

    AVFormatContext *oc;

    int64_t total_size;

    AVCodecContext *enc;

    int frame_number, vid, i;

    double bitrate;

    int64_t pts = INT64_MAX;

    static int64_t last_time = -1;

    static int qp_histogram[52];

    int hours, mins, secs, us;



    if (!is_last_report) {

        int64_t cur_time;

        /* display the report every 0.5 seconds */

        cur_time = av_gettime();

        if (last_time == -1) {

            last_time = cur_time;

            return;

        }

        if ((cur_time - last_time) < 500000)

            return;

        last_time = cur_time;

    }





    oc = output_files[0].ctx;



    total_size = avio_size(oc->pb);

    if(total_size<0) // FIXME improve avio_size() so it works with non seekable output too

        total_size= avio_tell(oc->pb);



    buf[0] = '\0';

    vid = 0;

    for(i=0;i<nb_ostreams;i++) {

        float q = -1;

        ost = &ost_table[i];

        enc = ost->st->codec;

        if (!ost->st->stream_copy && enc->coded_frame)

            q = enc->coded_frame->quality/(float)FF_QP2LAMBDA;

        if (vid && enc->codec_type == AVMEDIA_TYPE_VIDEO) {

            snprintf(buf + strlen(buf), sizeof(buf) - strlen(buf), "q=%2.1f ", q);

        }

        if (!vid && enc->codec_type == AVMEDIA_TYPE_VIDEO) {

            float t = (av_gettime()-timer_start) / 1000000.0;



            frame_number = ost->frame_number;

            snprintf(buf + strlen(buf), sizeof(buf) - strlen(buf), "frame=%5d fps=%3d q=%3.1f ",

                     frame_number, (t>1)?(int)(frame_number/t+0.5) : 0, q);

            if(is_last_report)

                snprintf(buf + strlen(buf), sizeof(buf) - strlen(buf), "L");

            if(qp_hist){

                int j;

                int qp = lrintf(q);

                if(qp>=0 && qp<FF_ARRAY_ELEMS(qp_histogram))

                    qp_histogram[qp]++;

                for(j=0; j<32; j++)

                    snprintf(buf + strlen(buf), sizeof(buf) - strlen(buf), "%X", (int)lrintf(log(qp_histogram[j]+1)/log(2)));

            }

            if (enc->flags&CODEC_FLAG_PSNR){

                int j;

                double error, error_sum=0;

                double scale, scale_sum=0;

                char type[3]= {'Y','U','V'};

                snprintf(buf + strlen(buf), sizeof(buf) - strlen(buf), "PSNR=");

                for(j=0; j<3; j++){

                    if(is_last_report){

                        error= enc->error[j];

                        scale= enc->width*enc->height*255.0*255.0*frame_number;

                    }else{

                        error= enc->coded_frame->error[j];

                        scale= enc->width*enc->height*255.0*255.0;

                    }

                    if(j) scale/=4;

                    error_sum += error;

                    scale_sum += scale;

                    snprintf(buf + strlen(buf), sizeof(buf) - strlen(buf), "%c:%2.2f ", type[j], psnr(error/scale));

                }

                snprintf(buf + strlen(buf), sizeof(buf) - strlen(buf), "*:%2.2f ", psnr(error_sum/scale_sum));

            }

            vid = 1;

        }

        /* compute min output value */

        pts = FFMIN(pts, av_rescale_q(ost->st->pts.val,

                                      ost->st->time_base, AV_TIME_BASE_Q));

    }



    secs = pts / AV_TIME_BASE;

    us = pts % AV_TIME_BASE;

    mins = secs / 60;

    secs %= 60;

    hours = mins / 60;

    mins %= 60;



    bitrate = pts ? total_size * 8 / (pts / 1000.0) : 0;



    snprintf(buf + strlen(buf), sizeof(buf) - strlen(buf),

             "size=%8.0fkB time=", total_size / 1024.0);

    snprintf(buf + strlen(buf), sizeof(buf) - strlen(buf),

             "%02d:%02d:%02d.%02d ", hours, mins, secs,

             (100 * us) / AV_TIME_BASE);

    snprintf(buf + strlen(buf), sizeof(buf) - strlen(buf),

             "bitrate=%6.1fkbits/s", bitrate);



    if (nb_frames_dup || nb_frames_drop)

        snprintf(buf + strlen(buf), sizeof(buf) - strlen(buf), " dup=%d drop=%d",

                nb_frames_dup, nb_frames_drop);



    av_log(NULL, is_last_report ? AV_LOG_WARNING : AV_LOG_INFO, "%s    \r", buf);



    fflush(stderr);



    if (is_last_report) {

        int64_t raw= audio_size + video_size + extra_size;

        av_log(NULL, AV_LOG_INFO, "\n");

        av_log(NULL, AV_LOG_INFO, "video:%1.0fkB audio:%1.0fkB global headers:%1.0fkB muxing overhead %f%%\n",

               video_size/1024.0,

               audio_size/1024.0,

               extra_size/1024.0,

               100.0*(total_size - raw)/raw

        );

    }

}

int avcodec_copy_context(AVCodecContext *dest, const AVCodecContext *src)

{

    const AVCodec *orig_codec = dest->codec;

    uint8_t *orig_priv_data = dest->priv_data;



    if (avcodec_is_open(dest)) { // check that the dest context is uninitialized

        av_log(dest, AV_LOG_ERROR,

               "Tried to copy AVCodecContext %p into already-initialized %p\n",

               src, dest);

        return AVERROR(EINVAL);

    }



    av_opt_free(dest);

    av_free(dest->priv_data);



    memcpy(dest, src, sizeof(*dest));



    dest->priv_data       = orig_priv_data;

    dest->codec           = orig_codec;



    /* set values specific to opened codecs back to their default state */

    dest->slice_offset    = NULL;

    dest->hwaccel         = NULL;

    dest->internal        = NULL;



    /* reallocate values that should be allocated separately */

    dest->rc_eq           = NULL;

    dest->extradata       = NULL;

    dest->intra_matrix    = NULL;

    dest->inter_matrix    = NULL;

    dest->rc_override     = NULL;

    dest->subtitle_header = NULL;

    if (src->rc_eq) {

        dest->rc_eq = av_strdup(src->rc_eq);

        if (!dest->rc_eq)

            return AVERROR(ENOMEM);

    }



#define alloc_and_copy_or_fail(obj, size, pad) \

    if (src->obj && size > 0) { \

        dest->obj = av_malloc(size + pad); \

        if (!dest->obj) \

            goto fail; \

        memcpy(dest->obj, src->obj, size); \

        if (pad) \

            memset(((uint8_t *) dest->obj) + size, 0, pad); \

    }

    alloc_and_copy_or_fail(extradata,    src->extradata_size,

                           FF_INPUT_BUFFER_PADDING_SIZE);

    alloc_and_copy_or_fail(intra_matrix, 64 * sizeof(int16_t), 0);

    alloc_and_copy_or_fail(inter_matrix, 64 * sizeof(int16_t), 0);

    alloc_and_copy_or_fail(rc_override,  src->rc_override_count * sizeof(*src->rc_override), 0);

    alloc_and_copy_or_fail(subtitle_header, src->subtitle_header_size, 1);

    dest->subtitle_header_size = src->subtitle_header_size;

#undef alloc_and_copy_or_fail



    return 0;



fail:

    av_freep(&dest->rc_override);

    av_freep(&dest->intra_matrix);

    av_freep(&dest->inter_matrix);

    av_freep(&dest->extradata);

    av_freep(&dest->rc_eq);

    return AVERROR(ENOMEM);

}

static int rkmpp_retrieve_frame(AVCodecContext *avctx, AVFrame *frame)

{

    RKMPPDecodeContext *rk_context = avctx->priv_data;

    RKMPPDecoder *decoder = (RKMPPDecoder *)rk_context->decoder_ref->data;

    RKMPPFrameContext *framecontext = NULL;

    AVBufferRef *framecontextref = NULL;

    int ret;

    MppFrame mppframe = NULL;

    MppBuffer buffer = NULL;

    AVDRMFrameDescriptor *desc = NULL;

    AVDRMLayerDescriptor *layer = NULL;

    int retrycount = 0;

    int mode;

    MppFrameFormat mppformat;

    uint32_t drmformat;



    // on start of decoding, MPP can return -1, which is supposed to be expected

    // this is due to some internal MPP init which is not completed, that will

    // only happen in the first few frames queries, but should not be interpreted

    // as an error, Therefore we need to retry a couple times when we get -1

    // in order to let it time to complete it's init, then we sleep a bit between retries.

retry_get_frame:

    ret = decoder->mpi->decode_get_frame(decoder->ctx, &mppframe);

    if (ret != MPP_OK && ret != MPP_ERR_TIMEOUT && !decoder->first_frame) {

        if (retrycount < 5) {

            av_log(avctx, AV_LOG_DEBUG, "Failed to get a frame, retrying (code = %d, retrycount = %d)\n", ret, retrycount);

            usleep(10000);

            retrycount++;

            goto retry_get_frame;

        } else {

            av_log(avctx, AV_LOG_ERROR, "Failed to get a frame from MPP (code = %d)\n", ret);

            goto fail;

        }

    }



    if (mppframe) {

        // Check wether we have a special frame or not

        if (mpp_frame_get_info_change(mppframe)) {

            AVHWFramesContext *hwframes;



            av_log(avctx, AV_LOG_INFO, "Decoder noticed an info change (%dx%d), format=%d\n",

                                        (int)mpp_frame_get_width(mppframe), (int)mpp_frame_get_height(mppframe),

                                        (int)mpp_frame_get_fmt(mppframe));



            avctx->width = mpp_frame_get_width(mppframe);

            avctx->height = mpp_frame_get_height(mppframe);



            decoder->mpi->control(decoder->ctx, MPP_DEC_SET_INFO_CHANGE_READY, NULL);

            decoder->first_frame = 1;



            av_buffer_unref(&decoder->frames_ref);



            decoder->frames_ref = av_hwframe_ctx_alloc(decoder->device_ref);

            if (!decoder->frames_ref) {

                ret = AVERROR(ENOMEM);

                goto fail;

            }



            mppformat = mpp_frame_get_fmt(mppframe);

            drmformat = rkmpp_get_frameformat(mppformat);



            hwframes = (AVHWFramesContext*)decoder->frames_ref->data;

            hwframes->format    = AV_PIX_FMT_DRM_PRIME;

            hwframes->sw_format = drmformat == DRM_FORMAT_NV12 ? AV_PIX_FMT_NV12 : AV_PIX_FMT_NONE;

            hwframes->width     = avctx->width;

            hwframes->height    = avctx->height;

            ret = av_hwframe_ctx_init(decoder->frames_ref);

            if (ret < 0)

                goto fail;



            // here decoder is fully initialized, we need to feed it again with data

            ret = AVERROR(EAGAIN);

            goto fail;

        } else if (mpp_frame_get_eos(mppframe)) {

            av_log(avctx, AV_LOG_DEBUG, "Received a EOS frame.\n");

            decoder->eos_reached = 1;

            ret = AVERROR_EOF;

            goto fail;

        } else if (mpp_frame_get_discard(mppframe)) {

            av_log(avctx, AV_LOG_DEBUG, "Received a discard frame.\n");

            ret = AVERROR(EAGAIN);

            goto fail;

        } else if (mpp_frame_get_errinfo(mppframe)) {

            av_log(avctx, AV_LOG_ERROR, "Received a errinfo frame.\n");

            ret = AVERROR_UNKNOWN;

            goto fail;

        }



        // here we should have a valid frame

        av_log(avctx, AV_LOG_DEBUG, "Received a frame.\n");



        // setup general frame fields

        frame->format           = AV_PIX_FMT_DRM_PRIME;

        frame->width            = mpp_frame_get_width(mppframe);

        frame->height           = mpp_frame_get_height(mppframe);

        frame->pts              = mpp_frame_get_pts(mppframe);

        frame->color_range      = mpp_frame_get_color_range(mppframe);

        frame->color_primaries  = mpp_frame_get_color_primaries(mppframe);

        frame->color_trc        = mpp_frame_get_color_trc(mppframe);

        frame->colorspace       = mpp_frame_get_colorspace(mppframe);



        mode = mpp_frame_get_mode(mppframe);

        frame->interlaced_frame = ((mode & MPP_FRAME_FLAG_FIELD_ORDER_MASK) == MPP_FRAME_FLAG_DEINTERLACED);

        frame->top_field_first  = ((mode & MPP_FRAME_FLAG_FIELD_ORDER_MASK) == MPP_FRAME_FLAG_TOP_FIRST);



        mppformat = mpp_frame_get_fmt(mppframe);

        drmformat = rkmpp_get_frameformat(mppformat);



        // now setup the frame buffer info

        buffer = mpp_frame_get_buffer(mppframe);

        if (buffer) {

            desc = av_mallocz(sizeof(AVDRMFrameDescriptor));

            if (!desc) {

                ret = AVERROR(ENOMEM);

                goto fail;

            }



            desc->nb_objects = 1;

            desc->objects[0].fd = mpp_buffer_get_fd(buffer);

            desc->objects[0].size = mpp_buffer_get_size(buffer);



            desc->nb_layers = 1;

            layer = &desc->layers[0];

            layer->format = drmformat;

            layer->nb_planes = 2;



            layer->planes[0].object_index = 0;

            layer->planes[0].offset = 0;

            layer->planes[0].pitch = mpp_frame_get_hor_stride(mppframe);



            layer->planes[1].object_index = 0;

            layer->planes[1].offset = layer->planes[0].pitch * mpp_frame_get_ver_stride(mppframe);

            layer->planes[1].pitch = layer->planes[0].pitch;



            // we also allocate a struct in buf[0] that will allow to hold additionnal information

            // for releasing properly MPP frames and decoder

            framecontextref = av_buffer_allocz(sizeof(*framecontext));

            if (!framecontextref) {

                ret = AVERROR(ENOMEM);

                goto fail;

            }



            // MPP decoder needs to be closed only when all frames have been released.

            framecontext = (RKMPPFrameContext *)framecontextref->data;

            framecontext->decoder_ref = av_buffer_ref(rk_context->decoder_ref);

            framecontext->frame = mppframe;



            frame->data[0]  = (uint8_t *)desc;

            frame->buf[0]   = av_buffer_create((uint8_t *)desc, sizeof(*desc), rkmpp_release_frame,

                                               framecontextref, AV_BUFFER_FLAG_READONLY);



            if (!frame->buf[0]) {

                ret = AVERROR(ENOMEM);

                goto fail;

            }



            frame->hw_frames_ctx = av_buffer_ref(decoder->frames_ref);

            if (!frame->hw_frames_ctx) {

                ret = AVERROR(ENOMEM);

                goto fail;

            }



            decoder->first_frame = 0;

            return 0;

        } else {

            av_log(avctx, AV_LOG_ERROR, "Failed to retrieve the frame buffer, frame is dropped (code = %d)\n", ret);

            mpp_frame_deinit(&mppframe);

        }

    } else if (decoder->eos_reached) {

        return AVERROR_EOF;

    } else if (ret == MPP_ERR_TIMEOUT) {

        av_log(avctx, AV_LOG_DEBUG, "Timeout when trying to get a frame from MPP\n");

    }



    return AVERROR(EAGAIN);



fail:

    if (mppframe)

        mpp_frame_deinit(&mppframe);



    if (framecontext)

        av_buffer_unref(&framecontext->decoder_ref);



    if (framecontextref)

        av_buffer_unref(&framecontextref);



    if (desc)

        av_free(desc);



    return ret;

}

static av_cold int libssh_authentication(LIBSSHContext *libssh, const char *user, const char *password)

{

    int authorized = 0;

    int auth_methods;



    if (user)

        ssh_options_set(libssh->session, SSH_OPTIONS_USER, user);



    if (ssh_userauth_none(libssh->session, NULL) == SSH_AUTH_SUCCESS)

        return 0;



    auth_methods = ssh_userauth_list(libssh->session, NULL);



    if (auth_methods & SSH_AUTH_METHOD_PUBLICKEY) {

        if (libssh->priv_key) {

            ssh_string pub_key;

            ssh_private_key priv_key;

            int type;

            if (!ssh_try_publickey_from_file(libssh->session, libssh->priv_key, &pub_key, &type)) {

                priv_key = privatekey_from_file(libssh->session, libssh->priv_key, type, password);

                if (ssh_userauth_pubkey(libssh->session, NULL, pub_key, priv_key) == SSH_AUTH_SUCCESS) {

                    av_log(libssh, AV_LOG_DEBUG, "Authentication successful with selected private key.\n");

                    authorized = 1;

                }

            } else {

                av_log(libssh, AV_LOG_DEBUG, "Invalid key is provided.\n");

                return AVERROR(EACCES);

            }

        } else if (ssh_userauth_autopubkey(libssh->session, password) == SSH_AUTH_SUCCESS) {

            av_log(libssh, AV_LOG_DEBUG, "Authentication successful with auto selected key.\n");

            authorized = 1;

        }

    }



    if (!authorized && (auth_methods & SSH_AUTH_METHOD_PASSWORD)) {

        if (ssh_userauth_password(libssh->session, NULL, password) == SSH_AUTH_SUCCESS) {

            av_log(libssh, AV_LOG_DEBUG, "Authentication successful with password.\n");

            authorized = 1;

        }

    }



    if (!authorized) {

        av_log(libssh, AV_LOG_ERROR, "Authentication failed.\n");

        return AVERROR(EACCES);

    }



    return 0;

}

