static int wsvqa_read_header(AVFormatContext *s)

{

    WsVqaDemuxContext *wsvqa = s->priv_data;

    AVIOContext *pb = s->pb;

    AVStream *st;

    unsigned char *header;

    unsigned char scratch[VQA_PREAMBLE_SIZE];

    unsigned int chunk_tag;

    unsigned int chunk_size;

    int fps;



    /* initialize the video decoder stream */

    st = avformat_new_stream(s, NULL);

    if (!st)

        return AVERROR(ENOMEM);

    st->start_time = 0;

    wsvqa->video_stream_index = st->index;

    st->codec->codec_type = AVMEDIA_TYPE_VIDEO;

    st->codec->codec_id = AV_CODEC_ID_WS_VQA;

    st->codec->codec_tag = 0;  /* no fourcc */



    /* skip to the start of the VQA header */

    avio_seek(pb, 20, SEEK_SET);



    /* the VQA header needs to go to the decoder */

    st->codec->extradata_size = VQA_HEADER_SIZE;

    st->codec->extradata = av_mallocz(VQA_HEADER_SIZE + FF_INPUT_BUFFER_PADDING_SIZE);

    header = (unsigned char *)st->codec->extradata;

    if (avio_read(pb, st->codec->extradata, VQA_HEADER_SIZE) !=

        VQA_HEADER_SIZE) {

        av_free(st->codec->extradata);

        return AVERROR(EIO);

    }

    st->codec->width = AV_RL16(&header[6]);

    st->codec->height = AV_RL16(&header[8]);

    fps = header[12];

    st->nb_frames =

    st->duration  = AV_RL16(&header[4]);

    if (fps < 1 || fps > 30) {

        av_log(s, AV_LOG_ERROR, "invalid fps: %d\n", fps);

        return AVERROR_INVALIDDATA;

    }

    avpriv_set_pts_info(st, 64, 1, fps);



    wsvqa->version      = AV_RL16(&header[ 0]);

    wsvqa->sample_rate  = AV_RL16(&header[24]);

    wsvqa->channels     = header[26];

    wsvqa->bps          = header[27];

    wsvqa->audio_stream_index = -1;



    s->ctx_flags |= AVFMTCTX_NOHEADER;



    /* there are 0 or more chunks before the FINF chunk; iterate until

     * FINF has been skipped and the file will be ready to be demuxed */

    do {

        if (avio_read(pb, scratch, VQA_PREAMBLE_SIZE) != VQA_PREAMBLE_SIZE)

            return AVERROR(EIO);

        chunk_tag = AV_RB32(&scratch[0]);

        chunk_size = AV_RB32(&scratch[4]);



        /* catch any unknown header tags, for curiousity */

        switch (chunk_tag) {

        case CINF_TAG:

        case CINH_TAG:

        case CIND_TAG:

        case PINF_TAG:

        case PINH_TAG:

        case PIND_TAG:

        case FINF_TAG:

        case CMDS_TAG:

            break;



        default:

            av_log (s, AV_LOG_ERROR, " note: unknown chunk seen (%c%c%c%c)\n",

                scratch[0], scratch[1],

                scratch[2], scratch[3]);

            break;

        }



        avio_skip(pb, chunk_size);

    } while (chunk_tag != FINF_TAG);



    return 0;

}

static void flat_print_str(WriterContext *wctx, const char *key, const char *value)

{

    FlatContext *flat = wctx->priv;

    AVBPrint buf;



    flat_print_key_prefix(wctx);

    av_bprint_init(&buf, 1, AV_BPRINT_SIZE_UNLIMITED);

    printf("%s=", flat_escape_key_str(&buf, key, flat->sep));

    av_bprint_clear(&buf);

    printf("\"%s\"\n", flat_escape_value_str(&buf, value));

    av_bprint_finalize(&buf, NULL);

}

static int nut_write_packet(AVFormatContext *s, AVPacket *pkt){

    NUTContext *nut = s->priv_data;

    StreamContext *nus= &nut->stream[pkt->stream_index];

    AVIOContext *bc = s->pb, *dyn_bc;

    FrameCode *fc;

    int64_t coded_pts;

    int best_length, frame_code, flags, needed_flags, i, header_idx, best_header_idx;

    int key_frame = !!(pkt->flags & AV_PKT_FLAG_KEY);

    int store_sp=0;

    int ret;



    if(pkt->pts < 0)

        return -1;



    if(1LL<<(20+3*nut->header_count) <= avio_tell(bc))

        write_headers(s, bc);



    if(key_frame && !(nus->last_flags & FLAG_KEY))

        store_sp= 1;



    if(pkt->size + 30/*FIXME check*/ + avio_tell(bc) >= nut->last_syncpoint_pos + nut->max_distance)

        store_sp= 1;



//FIXME: Ensure store_sp is 1 in the first place.



    if(store_sp){

        Syncpoint *sp, dummy= {.pos= INT64_MAX};



        ff_nut_reset_ts(nut, *nus->time_base, pkt->dts);

        for(i=0; i<s->nb_streams; i++){

            AVStream *st= s->streams[i];

            int64_t dts_tb = av_rescale_rnd(pkt->dts,

                nus->time_base->num * (int64_t)nut->stream[i].time_base->den,

                nus->time_base->den * (int64_t)nut->stream[i].time_base->num,

                AV_ROUND_DOWN);

            int index= av_index_search_timestamp(st, dts_tb, AVSEEK_FLAG_BACKWARD);

            if(index>=0) dummy.pos= FFMIN(dummy.pos, st->index_entries[index].pos);

        }

        if(dummy.pos == INT64_MAX)

            dummy.pos= 0;

        sp= av_tree_find(nut->syncpoints, &dummy, (void *) ff_nut_sp_pos_cmp,

                         NULL);



        nut->last_syncpoint_pos= avio_tell(bc);

        ret = avio_open_dyn_buf(&dyn_bc);

        if(ret < 0)

            return ret;

        put_tt(nut, nus->time_base, dyn_bc, pkt->dts);

        ff_put_v(dyn_bc, sp ? (nut->last_syncpoint_pos - sp->pos)>>4 : 0);

        put_packet(nut, bc, dyn_bc, 1, SYNCPOINT_STARTCODE);



        ff_nut_add_sp(nut, nut->last_syncpoint_pos, 0/*unused*/, pkt->dts);

    }

    av_assert0(nus->last_pts != AV_NOPTS_VALUE);



    coded_pts = pkt->pts & ((1<<nus->msb_pts_shift)-1);

    if(ff_lsb2full(nus, coded_pts) != pkt->pts)

        coded_pts= pkt->pts + (1<<nus->msb_pts_shift);



    best_header_idx= find_best_header_idx(nut, pkt);



    best_length=INT_MAX;

    frame_code= -1;

    for(i=0; i<256; i++){

        int length= 0;

        FrameCode *fc= &nut->frame_code[i];

        int flags= fc->flags;



        if(flags & FLAG_INVALID)

            continue;

        needed_flags= get_needed_flags(nut, nus, fc, pkt);



        if(flags & FLAG_CODED){

            length++;

            flags = needed_flags;

        }



        if((flags & needed_flags) != needed_flags)

            continue;



        if((flags ^ needed_flags) & FLAG_KEY)

            continue;



        if(flags & FLAG_STREAM_ID)

            length+= ff_get_v_length(pkt->stream_index);



        if(pkt->size % fc->size_mul != fc->size_lsb)

            continue;

        if(flags & FLAG_SIZE_MSB)

            length += ff_get_v_length(pkt->size / fc->size_mul);



        if(flags & FLAG_CHECKSUM)

            length+=4;



        if(flags & FLAG_CODED_PTS)

            length += ff_get_v_length(coded_pts);



        if(   (flags & FLAG_CODED)

           && nut->header_len[best_header_idx] > nut->header_len[fc->header_idx]+1){

            flags |= FLAG_HEADER_IDX;

        }



        if(flags & FLAG_HEADER_IDX){

            length += 1 - nut->header_len[best_header_idx];

        }else{

            length -= nut->header_len[fc->header_idx];

        }



        length*=4;

        length+= !(flags & FLAG_CODED_PTS);

        length+= !(flags & FLAG_CHECKSUM);



        if(length < best_length){

            best_length= length;

            frame_code=i;

        }

    }

    av_assert0(frame_code != -1);

    fc= &nut->frame_code[frame_code];

    flags= fc->flags;

    needed_flags= get_needed_flags(nut, nus, fc, pkt);

    header_idx= fc->header_idx;



    ffio_init_checksum(bc, ff_crc04C11DB7_update, 0);

    avio_w8(bc, frame_code);

    if(flags & FLAG_CODED){

        ff_put_v(bc, (flags^needed_flags) & ~(FLAG_CODED));

        flags = needed_flags;

    }

    if(flags & FLAG_STREAM_ID)  ff_put_v(bc, pkt->stream_index);

    if(flags & FLAG_CODED_PTS)  ff_put_v(bc, coded_pts);

    if(flags & FLAG_SIZE_MSB)   ff_put_v(bc, pkt->size / fc->size_mul);

    if(flags & FLAG_HEADER_IDX) ff_put_v(bc, header_idx= best_header_idx);



    if(flags & FLAG_CHECKSUM)   avio_wl32(bc, ffio_get_checksum(bc));

    else                        ffio_get_checksum(bc);



    avio_write(bc, pkt->data + nut->header_len[header_idx], pkt->size - nut->header_len[header_idx]);

    nus->last_flags= flags;

    nus->last_pts= pkt->pts;



    //FIXME just store one per syncpoint

    if(flags & FLAG_KEY)

        av_add_index_entry(

            s->streams[pkt->stream_index],

            nut->last_syncpoint_pos,

            pkt->pts,

            0,

            0,

            AVINDEX_KEYFRAME);



    return 0;

}

ff_rm_parse_packet (AVFormatContext *s, ByteIOContext *pb,

                    AVStream *st, RMStream *ast, int len, AVPacket *pkt,

                    int *seq, int *flags, int64_t *timestamp)

{

    RMDemuxContext *rm = s->priv_data;



    if (st->codec->codec_type == CODEC_TYPE_VIDEO) {

        rm->current_stream= st->id;

        if(rm_assemble_video_frame(s, pb, rm, ast, pkt, len))

            return -1; //got partial frame

    } else if (st->codec->codec_type == CODEC_TYPE_AUDIO) {

        if ((st->codec->codec_id == CODEC_ID_RA_288) ||

            (st->codec->codec_id == CODEC_ID_COOK) ||

            (st->codec->codec_id == CODEC_ID_ATRAC3) ||

            (st->codec->codec_id == CODEC_ID_SIPR)) {

            int x;

            int sps = ast->sub_packet_size;

            int cfs = ast->coded_framesize;

            int h = ast->sub_packet_h;

            int y = ast->sub_packet_cnt;

            int w = ast->audio_framesize;



            if (*flags & 2)

                y = ast->sub_packet_cnt = 0;

            if (!y)

                ast->audiotimestamp = *timestamp;



            switch(st->codec->codec_id) {

                case CODEC_ID_RA_288:

                    for (x = 0; x < h/2; x++)

                        get_buffer(pb, ast->pkt.data+x*2*w+y*cfs, cfs);

                    break;

                case CODEC_ID_ATRAC3:

                case CODEC_ID_COOK:

                    for (x = 0; x < w/sps; x++)

                        get_buffer(pb, ast->pkt.data+sps*(h*x+((h+1)/2)*(y&1)+(y>>1)), sps);

                    break;

            }



            if (++(ast->sub_packet_cnt) < h)

                return -1;

            else {

                ast->sub_packet_cnt = 0;

                rm->audio_stream_num = st->index;

                rm->audio_pkt_cnt = h * w / st->codec->block_align - 1;

                // Release first audio packet

                av_new_packet(pkt, st->codec->block_align);

                memcpy(pkt->data, ast->pkt.data, st->codec->block_align); //FIXME avoid this

                *timestamp = ast->audiotimestamp;

                *flags = 2; // Mark first packet as keyframe

            }

        } else if (st->codec->codec_id == CODEC_ID_AAC) {

            int x;

            rm->audio_stream_num = st->index;

            ast->sub_packet_cnt = (get_be16(pb) & 0xf0) >> 4;

            if (ast->sub_packet_cnt) {

                for (x = 0; x < ast->sub_packet_cnt; x++)

                    ast->sub_packet_lengths[x] = get_be16(pb);

                // Release first audio packet

                rm->audio_pkt_cnt = ast->sub_packet_cnt - 1;

                av_get_packet(pb, pkt, ast->sub_packet_lengths[0]);

                *flags = 2; // Mark first packet as keyframe

            }

        } else {

            av_get_packet(pb, pkt, len);

            rm_ac3_swap_bytes(st, pkt);

        }

    } else

        av_get_packet(pb, pkt, len);



    if(  (st->discard >= AVDISCARD_NONKEY && !(*flags&2))

       || st->discard >= AVDISCARD_ALL){

        av_free_packet(pkt);

        return -1;

    }



    pkt->stream_index = st->index;



#if 0

    if (st->codec->codec_type == CODEC_TYPE_VIDEO) {

        if(st->codec->codec_id == CODEC_ID_RV20){

            int seq= 128*(pkt->data[2]&0x7F) + (pkt->data[3]>>1);

            av_log(s, AV_LOG_DEBUG, "%d %"PRId64" %d\n", *timestamp, *timestamp*512LL/25, seq);



            seq |= (*timestamp&~0x3FFF);

            if(seq - *timestamp >  0x2000) seq -= 0x4000;

            if(seq - *timestamp < -0x2000) seq += 0x4000;

        }

    }

#endif



    pkt->pts= *timestamp;

    if (*flags & 2)

        pkt->flags |= PKT_FLAG_KEY;



    return st->codec->codec_type == CODEC_TYPE_AUDIO ? rm->audio_pkt_cnt : 0;

}

static int tiff_unpack_strip(TiffContext *s, uint8_t* dst, int stride, const uint8_t *src, int size, int lines){

    int c, line, pixels, code;

    const uint8_t *ssrc = src;

    int width = ((s->width * s->bpp) + 7) >> 3;

#if CONFIG_ZLIB

    uint8_t *zbuf; unsigned long outlen;



    if(s->compr == TIFF_DEFLATE || s->compr == TIFF_ADOBE_DEFLATE){

        int ret;

        outlen = width * lines;

        zbuf = av_malloc(outlen);

        ret = tiff_uncompress(zbuf, &outlen, src, size);

        if(ret != Z_OK){

            av_log(s->avctx, AV_LOG_ERROR, "Uncompressing failed (%lu of %lu) with error %d\n", outlen, (unsigned long)width * lines, ret);

            av_free(zbuf);

            return -1;

        }

        src = zbuf;

        for(line = 0; line < lines; line++){

            memcpy(dst, src, width);

            dst += stride;

            src += width;

        }

        av_free(zbuf);

        return 0;

    }

#endif

    if(s->compr == TIFF_LZW){

        if(ff_lzw_decode_init(s->lzw, 8, src, size, FF_LZW_TIFF) < 0){

            av_log(s->avctx, AV_LOG_ERROR, "Error initializing LZW decoder\n");

            return -1;

        }

    }

    if(s->compr == TIFF_CCITT_RLE || s->compr == TIFF_G3 || s->compr == TIFF_G4){

        int i, ret = 0;

        uint8_t *src2 = av_malloc(size + FF_INPUT_BUFFER_PADDING_SIZE);



        if(!src2 || (unsigned)size + FF_INPUT_BUFFER_PADDING_SIZE < (unsigned)size){

            av_log(s->avctx, AV_LOG_ERROR, "Error allocating temporary buffer\n");

            return -1;

        }

        if(s->fax_opts & 2){

            av_log(s->avctx, AV_LOG_ERROR, "Uncompressed fax mode is not supported (yet)\n");

            av_free(src2);

            return -1;

        }

        if(!s->fill_order){

            memcpy(src2, src, size);

        }else{

            for(i = 0; i < size; i++)

                src2[i] = av_reverse[src[i]];

        }

        memset(src2+size, 0, FF_INPUT_BUFFER_PADDING_SIZE);

        switch(s->compr){

        case TIFF_CCITT_RLE:

        case TIFF_G3:

        case TIFF_G4:

            ret = ff_ccitt_unpack(s->avctx, src2, size, dst, lines, stride, s->compr, s->fax_opts);

            break;

        }

        av_free(src2);

        return ret;

    }

    for(line = 0; line < lines; line++){

        if(src - ssrc > size){

            av_log(s->avctx, AV_LOG_ERROR, "Source data overread\n");

            return -1;

        }

        switch(s->compr){

        case TIFF_RAW:

            if (ssrc + size - src < width)

                return AVERROR_INVALIDDATA;

            if (!s->fill_order) {

                memcpy(dst, src, width);

            } else {

                int i;

                for (i = 0; i < width; i++)

                    dst[i] = av_reverse[src[i]];

            }

            src += width;

            break;

        case TIFF_PACKBITS:

            for(pixels = 0; pixels < width;){

                code = (int8_t)*src++;

                if(code >= 0){

                    code++;

                    if(pixels + code > width){

                        av_log(s->avctx, AV_LOG_ERROR, "Copy went out of bounds\n");

                        return -1;

                    }

                    memcpy(dst + pixels, src, code);

                    src += code;

                    pixels += code;

                }else if(code != -128){ // -127..-1

                    code = (-code) + 1;

                    if(pixels + code > width){

                        av_log(s->avctx, AV_LOG_ERROR, "Run went out of bounds\n");

                        return -1;

                    }

                    c = *src++;

                    memset(dst + pixels, c, code);

                    pixels += code;

                }

            }

            break;

        case TIFF_LZW:

            pixels = ff_lzw_decode(s->lzw, dst, width);

            if(pixels < width){

                av_log(s->avctx, AV_LOG_ERROR, "Decoded only %i bytes of %i\n", pixels, width);

                return -1;

            }

            break;

        }

        dst += stride;

    }

    return 0;

}

inline static void RENAME(hcscale)(SwsContext *c, uint16_t *dst, long dstWidth, const uint8_t *src1, const uint8_t *src2,

                                   int srcW, int xInc, int flags, const int16_t *hChrFilter,

                                   const int16_t *hChrFilterPos, int hChrFilterSize,

                                   enum PixelFormat srcFormat, uint8_t *formatConvBuffer,

                                   uint32_t *pal)

{

    int32_t av_unused *mmx2FilterPos = c->chrMmx2FilterPos;

    int16_t av_unused *mmx2Filter    = c->chrMmx2Filter;

    int     av_unused canMMX2BeUsed  = c->canMMX2BeUsed;

    void    av_unused *mmx2FilterCode= c->chrMmx2FilterCode;



    if (isGray(srcFormat) || srcFormat==PIX_FMT_MONOBLACK || srcFormat==PIX_FMT_MONOWHITE)

        return;



    src1 += c->chrSrcOffset;

    src2 += c->chrSrcOffset;



    if (c->hcscale_internal) {

        c->hcscale_internal(formatConvBuffer, formatConvBuffer+VOFW, src1, src2, srcW, pal);

        src1= formatConvBuffer;

        src2= formatConvBuffer+VOFW;

    }



    if (!c->hcscale_fast)

    {

        c->hScale(dst     , dstWidth, src1, srcW, xInc, hChrFilter, hChrFilterPos, hChrFilterSize);

        c->hScale(dst+VOFW, dstWidth, src2, srcW, xInc, hChrFilter, hChrFilterPos, hChrFilterSize);

    } else { // fast bilinear upscale / crap downscale

#if ARCH_X86 && CONFIG_GPL

#if COMPILE_TEMPLATE_MMX2

        int i;

#if defined(PIC)

        DECLARE_ALIGNED(8, uint64_t, ebxsave);

#endif

        if (canMMX2BeUsed) {

            __asm__ volatile(

#if defined(PIC)

                "mov          %%"REG_b", %6         \n\t"

#endif

                "pxor             %%mm7, %%mm7      \n\t"

                "mov                 %0, %%"REG_c"  \n\t"

                "mov                 %1, %%"REG_D"  \n\t"

                "mov                 %2, %%"REG_d"  \n\t"

                "mov                 %3, %%"REG_b"  \n\t"

                "xor          %%"REG_a", %%"REG_a"  \n\t" // i

                PREFETCH"   (%%"REG_c")             \n\t"

                PREFETCH" 32(%%"REG_c")             \n\t"

                PREFETCH" 64(%%"REG_c")             \n\t"



                CALL_MMX2_FILTER_CODE

                CALL_MMX2_FILTER_CODE

                CALL_MMX2_FILTER_CODE

                CALL_MMX2_FILTER_CODE

                "xor          %%"REG_a", %%"REG_a"  \n\t" // i

                "mov                 %5, %%"REG_c"  \n\t" // src

                "mov                 %1, %%"REG_D"  \n\t" // buf1

                "add              $"AV_STRINGIFY(VOF)", %%"REG_D"  \n\t"

                PREFETCH"   (%%"REG_c")             \n\t"

                PREFETCH" 32(%%"REG_c")             \n\t"

                PREFETCH" 64(%%"REG_c")             \n\t"



                CALL_MMX2_FILTER_CODE

                CALL_MMX2_FILTER_CODE

                CALL_MMX2_FILTER_CODE

                CALL_MMX2_FILTER_CODE



#if defined(PIC)

                "mov %6, %%"REG_b"    \n\t"

#endif

                :: "m" (src1), "m" (dst), "m" (mmx2Filter), "m" (mmx2FilterPos),

                "m" (mmx2FilterCode), "m" (src2)

#if defined(PIC)

                ,"m" (ebxsave)

#endif

                : "%"REG_a, "%"REG_c, "%"REG_d, "%"REG_S, "%"REG_D

#if !defined(PIC)

                ,"%"REG_b

#endif

            );

            for (i=dstWidth-1; (i*xInc)>>16 >=srcW-1; i--) {

                //printf("%d %d %d\n", dstWidth, i, srcW);

                dst[i] = src1[srcW-1]*128;

                dst[i+VOFW] = src2[srcW-1]*128;

            }

        } else {

#endif /* COMPILE_TEMPLATE_MMX2 */

            x86_reg xInc_shr16 = (x86_reg) (xInc >> 16);

            uint16_t xInc_mask = xInc & 0xffff;

            __asm__ volatile(

                "xor %%"REG_a", %%"REG_a"               \n\t" // i

                "xor %%"REG_d", %%"REG_d"               \n\t" // xx

                "xorl    %%ecx, %%ecx                   \n\t" // xalpha

                ASMALIGN(4)

                "1:                                     \n\t"

                "mov        %0, %%"REG_S"               \n\t"

                "movzbl  (%%"REG_S", %%"REG_d"), %%edi  \n\t" //src[xx]

                "movzbl 1(%%"REG_S", %%"REG_d"), %%esi  \n\t" //src[xx+1]

                FAST_BILINEAR_X86

                "movw     %%si, (%%"REG_D", %%"REG_a", 2)   \n\t"



                "movzbl    (%5, %%"REG_d"), %%edi       \n\t" //src[xx]

                "movzbl   1(%5, %%"REG_d"), %%esi       \n\t" //src[xx+1]

                FAST_BILINEAR_X86

                "movw     %%si, "AV_STRINGIFY(VOF)"(%%"REG_D", %%"REG_a", 2)   \n\t"



                "addw       %4, %%cx                    \n\t" //xalpha += xInc&0xFFFF

                "adc        %3, %%"REG_d"               \n\t" //xx+= xInc>>16 + carry

                "add        $1, %%"REG_a"               \n\t"

                "cmp        %2, %%"REG_a"               \n\t"

                " jb        1b                          \n\t"



/* GCC 3.3 makes MPlayer crash on IA-32 machines when using "g" operand here,

   which is needed to support GCC 4.0. */

#if ARCH_X86_64 && AV_GCC_VERSION_AT_LEAST(3,4)

                :: "m" (src1), "m" (dst), "g" (dstWidth), "m" (xInc_shr16), "m" (xInc_mask),

#else

                :: "m" (src1), "m" (dst), "m" (dstWidth), "m" (xInc_shr16), "m" (xInc_mask),

#endif

                "r" (src2)

                : "%"REG_a, "%"REG_d, "%ecx", "%"REG_D, "%esi"

            );

#if COMPILE_TEMPLATE_MMX2

        } //if MMX2 can't be used

#endif

#else

        c->hcscale_fast(c, dst, dstWidth, src1, src2, srcW, xInc);

#endif /* ARCH_X86 */

    }



    if (c->chrConvertRange)

        c->chrConvertRange(dst, dstWidth);

}

static int rm_write_audio(AVFormatContext *s, const uint8_t *buf, int size, int flags)

{

    uint8_t *buf1;

    RMMuxContext *rm = s->priv_data;

    AVIOContext *pb = s->pb;

    StreamInfo *stream = rm->audio_stream;

    int i;



    /* XXX: suppress this malloc */

    buf1 = av_malloc(size * sizeof(uint8_t));





    write_packet_header(s, stream, size, !!(flags & AV_PKT_FLAG_KEY));



    if (stream->enc->codec_id == AV_CODEC_ID_AC3) {

        /* for AC-3, the words seem to be reversed */

        for(i=0;i<size;i+=2) {

            buf1[i] = buf[i+1];

            buf1[i+1] = buf[i];

        }

        avio_write(pb, buf1, size);

    } else {

        avio_write(pb, buf, size);

    }

    stream->nb_frames++;

    av_free(buf1);

    return 0;

}

static int lag_decode_frame(AVCodecContext *avctx,

                            void *data, int *got_frame, AVPacket *avpkt)

{

    const uint8_t *buf = avpkt->data;

    int buf_size = avpkt->size;

    LagarithContext *l = avctx->priv_data;

    ThreadFrame frame = { .f = data };

    AVFrame *const p  = data;

    uint8_t frametype = 0;

    uint32_t offset_gu = 0, offset_bv = 0, offset_ry = 9;

    uint32_t offs[4];

    uint8_t *srcs[4], *dst;

    int i, j, planes = 3;



    p->key_frame = 1;



    frametype = buf[0];



    offset_gu = AV_RL32(buf + 1);

    offset_bv = AV_RL32(buf + 5);



    switch (frametype) {

    case FRAME_SOLID_RGBA:

        avctx->pix_fmt = AV_PIX_FMT_RGB32;



        if (ff_thread_get_buffer(avctx, &frame, 0) < 0) {

            av_log(avctx, AV_LOG_ERROR, "get_buffer() failed\n");

            return -1;

        }



        dst = p->data[0];

        for (j = 0; j < avctx->height; j++) {

            for (i = 0; i < avctx->width; i++)

                AV_WN32(dst + i * 4, offset_gu);

            dst += p->linesize[0];

        }

        break;

    case FRAME_ARITH_RGBA:

        avctx->pix_fmt = AV_PIX_FMT_RGB32;

        planes = 4;

        offset_ry += 4;

        offs[3] = AV_RL32(buf + 9);

    case FRAME_ARITH_RGB24:

    case FRAME_U_RGB24:

        if (frametype == FRAME_ARITH_RGB24 || frametype == FRAME_U_RGB24)

            avctx->pix_fmt = AV_PIX_FMT_RGB24;



        if (ff_thread_get_buffer(avctx, &frame, 0) < 0) {

            av_log(avctx, AV_LOG_ERROR, "get_buffer() failed\n");

            return -1;

        }



        offs[0] = offset_bv;

        offs[1] = offset_gu;

        offs[2] = offset_ry;



        if (!l->rgb_planes) {

            l->rgb_stride = FFALIGN(avctx->width, 16);

            l->rgb_planes = av_malloc(l->rgb_stride * avctx->height * planes + 1);

            if (!l->rgb_planes) {

                av_log(avctx, AV_LOG_ERROR, "cannot allocate temporary buffer\n");

                return AVERROR(ENOMEM);

            }

        }

        for (i = 0; i < planes; i++)

            srcs[i] = l->rgb_planes + (i + 1) * l->rgb_stride * avctx->height - l->rgb_stride;

        if (offset_ry >= buf_size ||

            offset_gu >= buf_size ||

            offset_bv >= buf_size ||

            (planes == 4 && offs[3] >= buf_size)) {

            av_log(avctx, AV_LOG_ERROR,

                    "Invalid frame offsets\n");

            return AVERROR_INVALIDDATA;

        }

        for (i = 0; i < planes; i++)

            lag_decode_arith_plane(l, srcs[i],

                                   avctx->width, avctx->height,

                                   -l->rgb_stride, buf + offs[i],

                                   buf_size - offs[i]);

        dst = p->data[0];

        for (i = 0; i < planes; i++)

            srcs[i] = l->rgb_planes + i * l->rgb_stride * avctx->height;

        for (j = 0; j < avctx->height; j++) {

            for (i = 0; i < avctx->width; i++) {

                uint8_t r, g, b, a;

                r = srcs[0][i];

                g = srcs[1][i];

                b = srcs[2][i];

                r += g;

                b += g;

                if (frametype == FRAME_ARITH_RGBA) {

                    a = srcs[3][i];

                    AV_WN32(dst + i * 4, MKBETAG(a, r, g, b));

                } else {

                    dst[i * 3 + 0] = r;

                    dst[i * 3 + 1] = g;

                    dst[i * 3 + 2] = b;

                }

            }

            dst += p->linesize[0];

            for (i = 0; i < planes; i++)

                srcs[i] += l->rgb_stride;

        }

        break;

    case FRAME_ARITH_YUY2:

        avctx->pix_fmt = AV_PIX_FMT_YUV422P;



        if (ff_thread_get_buffer(avctx, &frame, 0) < 0) {

            av_log(avctx, AV_LOG_ERROR, "get_buffer() failed\n");

            return -1;

        }



        if (offset_ry >= buf_size ||

            offset_gu >= buf_size ||

            offset_bv >= buf_size) {

            av_log(avctx, AV_LOG_ERROR,

                   "Invalid frame offsets\n");

            return AVERROR_INVALIDDATA;

        }



        lag_decode_arith_plane(l, p->data[0], avctx->width, avctx->height,

                               p->linesize[0], buf + offset_ry,

                               buf_size - offset_ry);

        lag_decode_arith_plane(l, p->data[1], avctx->width / 2,

                               avctx->height, p->linesize[1],

                               buf + offset_gu, buf_size - offset_gu);

        lag_decode_arith_plane(l, p->data[2], avctx->width / 2,

                               avctx->height, p->linesize[2],

                               buf + offset_bv, buf_size - offset_bv);

        break;

    case FRAME_ARITH_YV12:

        avctx->pix_fmt = AV_PIX_FMT_YUV420P;



        if (ff_thread_get_buffer(avctx, &frame, 0) < 0) {

            av_log(avctx, AV_LOG_ERROR, "get_buffer() failed\n");

            return -1;

        }



        if (offset_ry >= buf_size ||

            offset_gu >= buf_size ||

            offset_bv >= buf_size) {

            av_log(avctx, AV_LOG_ERROR,

                   "Invalid frame offsets\n");

            return AVERROR_INVALIDDATA;

        }



        lag_decode_arith_plane(l, p->data[0], avctx->width, avctx->height,

                               p->linesize[0], buf + offset_ry,

                               buf_size - offset_ry);

        lag_decode_arith_plane(l, p->data[2], avctx->width / 2,

                               avctx->height / 2, p->linesize[2],

                               buf + offset_gu, buf_size - offset_gu);

        lag_decode_arith_plane(l, p->data[1], avctx->width / 2,

                               avctx->height / 2, p->linesize[1],

                               buf + offset_bv, buf_size - offset_bv);

        break;

    default:

        av_log(avctx, AV_LOG_ERROR,

               "Unsupported Lagarith frame type: %#x\n", frametype);

        return -1;

    }



    *got_frame = 1;



    return buf_size;

}

int ff_lzw_decode(LZWState *p, uint8_t *buf, int len){

    int l, c, code, oc, fc;

    uint8_t *sp;

    struct LZWState *s = (struct LZWState *)p;



    if (s->end_code < 0)

        return 0;



    l = len;

    sp = s->sp;

    oc = s->oc;

    fc = s->fc;



    for (;;) {

        while (sp > s->stack) {

            *buf++ = *(--sp);

            if ((--l) == 0)

                goto the_end;

        }

        c = lzw_get_code(s);

        if (c == s->end_code) {

            s->end_code = -1;

            break;

        } else if (c == s->clear_code) {

            s->cursize = s->codesize + 1;

            s->curmask = mask[s->cursize];

            s->slot = s->newcodes;

            s->top_slot = 1 << s->cursize;

            fc= oc= -1;

        } else {

            code = c;

            if (code >= s->slot) {

                *sp++ = fc;

                code = oc;

            }

            while (code >= s->newcodes) {

                *sp++ = s->suffix[code];

                code = s->prefix[code];

            }

            *sp++ = code;

            if (s->slot < s->top_slot && oc>=0) {

                s->suffix[s->slot] = code;

                s->prefix[s->slot++] = oc;

            }

            fc = code;

            oc = c;

            if (s->slot >= s->top_slot - s->extra_slot) {

                if (s->cursize < LZW_MAXBITS) {

                    s->top_slot <<= 1;

                    s->curmask = mask[++s->cursize];

                }

            }

        }

    }

  the_end:

    s->sp = sp;

    s->oc = oc;

    s->fc = fc;

    return len - l;

}

static void FUNCC(pred4x4_vertical)(uint8_t *_src, const uint8_t *topright, int _stride){

    pixel *src = (pixel*)_src;

    int stride = _stride/sizeof(pixel);

    const pixel4 a= ((pixel4*)(src-stride))[0];

    ((pixel4*)(src+0*stride))[0]= a;

    ((pixel4*)(src+1*stride))[0]= a;

    ((pixel4*)(src+2*stride))[0]= a;

    ((pixel4*)(src+3*stride))[0]= a;

}

static float get_band_cost_UQUAD_mips(struct AACEncContext *s,

                                      PutBitContext *pb, const float *in,

                                      const float *scaled, int size, int scale_idx,

                                      int cb, const float lambda, const float uplim,

                                      int *bits)

{

    const float Q34 = ff_aac_pow34sf_tab[POW_SF2_ZERO - scale_idx + SCALE_ONE_POS - SCALE_DIV_512];

    const float IQ  = ff_aac_pow2sf_tab [POW_SF2_ZERO + scale_idx - SCALE_ONE_POS + SCALE_DIV_512];

    int i;

    float cost = 0;

    int curbits = 0;

    int qc1, qc2, qc3, qc4;



    uint8_t *p_bits  = (uint8_t*)ff_aac_spectral_bits[cb-1];

    float   *p_codes = (float  *)ff_aac_codebook_vectors[cb-1];



    for (i = 0; i < size; i += 4) {

        const float *vec;

        int curidx;

        float *in_pos = (float *)&in[i];

        float di0, di1, di2, di3;

        int t0, t1, t2, t3, t4;



        qc1 = scaled[i  ] * Q34 + ROUND_STANDARD;

        qc2 = scaled[i+1] * Q34 + ROUND_STANDARD;

        qc3 = scaled[i+2] * Q34 + ROUND_STANDARD;

        qc4 = scaled[i+3] * Q34 + ROUND_STANDARD;



        __asm__ volatile (

            ".set push                                  \n\t"

            ".set noreorder                             \n\t"



            "ori        %[t4],  $zero,  2               \n\t"

            "slt        %[t0],  %[t4],  %[qc1]          \n\t"

            "slt        %[t1],  %[t4],  %[qc2]          \n\t"

            "slt        %[t2],  %[t4],  %[qc3]          \n\t"

            "slt        %[t3],  %[t4],  %[qc4]          \n\t"

            "movn       %[qc1], %[t4],  %[t0]           \n\t"

            "movn       %[qc2], %[t4],  %[t1]           \n\t"

            "movn       %[qc3], %[t4],  %[t2]           \n\t"

            "movn       %[qc4], %[t4],  %[t3]           \n\t"



            ".set pop                                   \n\t"



            : [qc1]"+r"(qc1), [qc2]"+r"(qc2),

              [qc3]"+r"(qc3), [qc4]"+r"(qc4),

              [t0]"=&r"(t0), [t1]"=&r"(t1), [t2]"=&r"(t2), [t3]"=&r"(t3),

              [t4]"=&r"(t4)

        );



        curidx = qc1;

        curidx *= 3;

        curidx += qc2;

        curidx *= 3;

        curidx += qc3;

        curidx *= 3;

        curidx += qc4;



        curbits += p_bits[curidx];

        curbits += uquad_sign_bits[curidx];

        vec     = &p_codes[curidx*4];



        __asm__ volatile (

            ".set push                                  \n\t"

            ".set noreorder                             \n\t"



            "lwc1       %[di0], 0(%[in_pos])            \n\t"

            "lwc1       %[di1], 4(%[in_pos])            \n\t"

            "lwc1       %[di2], 8(%[in_pos])            \n\t"

            "lwc1       %[di3], 12(%[in_pos])           \n\t"

            "abs.s      %[di0], %[di0]                  \n\t"

            "abs.s      %[di1], %[di1]                  \n\t"

            "abs.s      %[di2], %[di2]                  \n\t"

            "abs.s      %[di3], %[di3]                  \n\t"

            "lwc1       $f0,    0(%[vec])               \n\t"

            "lwc1       $f1,    4(%[vec])               \n\t"

            "lwc1       $f2,    8(%[vec])               \n\t"

            "lwc1       $f3,    12(%[vec])              \n\t"

            "nmsub.s    %[di0], %[di0], $f0,    %[IQ]   \n\t"

            "nmsub.s    %[di1], %[di1], $f1,    %[IQ]   \n\t"

            "nmsub.s    %[di2], %[di2], $f2,    %[IQ]   \n\t"

            "nmsub.s    %[di3], %[di3], $f3,    %[IQ]   \n\t"



            ".set pop                                   \n\t"



            : [di0]"=&f"(di0), [di1]"=&f"(di1),

              [di2]"=&f"(di2), [di3]"=&f"(di3)

            : [in_pos]"r"(in_pos), [vec]"r"(vec),

              [IQ]"f"(IQ)

            : "$f0", "$f1", "$f2", "$f3",

              "memory"

        );



        cost += di0 * di0 + di1 * di1

                + di2 * di2 + di3 * di3;

    }



    if (bits)

        *bits = curbits;

    return cost * lambda + curbits;

}

