static int plot_spectrum_column(AVFilterLink *inlink, AVFrame *insamples)

{

    AVFilterContext *ctx = inlink->dst;

    AVFilterLink *outlink = ctx->outputs[0];

    ShowSpectrumContext *s = ctx->priv;

    AVFrame *outpicref = s->outpicref;

    int ret, plane, x, y, z = s->orientation == VERTICAL ? s->h : s->w;



    /* fill a new spectrum column */

    /* initialize buffer for combining to black */

    clear_combine_buffer(s, z);



    ctx->internal->execute(ctx, plot_channel, NULL, NULL, s->nb_display_channels);



    for (y = 0; y < z * 3; y++) {

        s->combine_buffer[y] += s->color_buffer[0][y];

        for (x = 1; x < s->nb_display_channels; x++) {

            s->combine_buffer[y] += s->color_buffer[x][y];

        }

    }



    av_frame_make_writable(s->outpicref);

    /* copy to output */

    if (s->orientation == VERTICAL) {

        if (s->sliding == SCROLL) {

            for (plane = 0; plane < 3; plane++) {

                for (y = 0; y < s->h; y++) {

                    uint8_t *p = outpicref->data[plane] +

                                 y * outpicref->linesize[plane];

                    memmove(p, p + 1, s->w - 1);

                }

            }

            s->xpos = s->w - 1;

        } else if (s->sliding == RSCROLL) {

            for (plane = 0; plane < 3; plane++) {

                for (y = 0; y < s->h; y++) {

                    uint8_t *p = outpicref->data[plane] +

                                 y * outpicref->linesize[plane];

                    memmove(p + 1, p, s->w - 1);

                }

            }

            s->xpos = 0;

        }

        for (plane = 0; plane < 3; plane++) {

            uint8_t *p = outpicref->data[plane] + s->start_x +

                         (outlink->h - 1 - s->start_y) * outpicref->linesize[plane] +

                         s->xpos;

            for (y = 0; y < s->h; y++) {

                *p = lrintf(av_clipf(s->combine_buffer[3 * y + plane], 0, 255));

                p -= outpicref->linesize[plane];

            }

        }

    } else {

        if (s->sliding == SCROLL) {

            for (plane = 0; plane < 3; plane++) {

                for (y = 1; y < s->h; y++) {

                    memmove(outpicref->data[plane] + (y-1) * outpicref->linesize[plane],

                            outpicref->data[plane] + (y  ) * outpicref->linesize[plane],

                            s->w);

                }

            }

            s->xpos = s->h - 1;

        } else if (s->sliding == RSCROLL) {

            for (plane = 0; plane < 3; plane++) {

                for (y = s->h - 1; y >= 1; y--) {

                    memmove(outpicref->data[plane] + (y  ) * outpicref->linesize[plane],

                            outpicref->data[plane] + (y-1) * outpicref->linesize[plane],

                            s->w);

                }

            }

            s->xpos = 0;

        }

        for (plane = 0; plane < 3; plane++) {

            uint8_t *p = outpicref->data[plane] + s->start_x +

                         (s->xpos + s->start_y) * outpicref->linesize[plane];

            for (x = 0; x < s->w; x++) {

                *p = lrintf(av_clipf(s->combine_buffer[3 * x + plane], 0, 255));

                p++;

            }

        }

    }



    if (s->sliding != FULLFRAME || s->xpos == 0)

        outpicref->pts = insamples->pts;



    s->xpos++;

    if (s->orientation == VERTICAL && s->xpos >= s->w)

        s->xpos = 0;

    if (s->orientation == HORIZONTAL && s->xpos >= s->h)

        s->xpos = 0;

    if (!s->single_pic && (s->sliding != FULLFRAME || s->xpos == 0)) {

        ret = ff_filter_frame(outlink, av_frame_clone(s->outpicref));

        if (ret < 0)

            return ret;

    }



    return s->win_size;

}

int attribute_align_arg avcodec_open(AVCodecContext *avctx, AVCodec *codec)

{

    int ret= -1;



    /* If there is a user-supplied mutex locking routine, call it. */

    if (ff_lockmgr_cb) {

        if ((*ff_lockmgr_cb)(&codec_mutex, AV_LOCK_OBTAIN))

            return -1;

    }



    entangled_thread_counter++;

    if(entangled_thread_counter != 1){

        av_log(avctx, AV_LOG_ERROR, "insufficient thread locking around avcodec_open/close()\n");

        goto end;

    }



    if(avctx->codec || !codec)

        goto end;



    if (codec->priv_data_size > 0) {

        avctx->priv_data = av_mallocz(codec->priv_data_size);

        if (!avctx->priv_data) {

            ret = AVERROR(ENOMEM);

            goto end;

        }

    } else {

        avctx->priv_data = NULL;

    }



    if(avctx->coded_width && avctx->coded_height)

        avcodec_set_dimensions(avctx, avctx->coded_width, avctx->coded_height);

    else if(avctx->width && avctx->height)

        avcodec_set_dimensions(avctx, avctx->width, avctx->height);



#define SANE_NB_CHANNELS 128U

    if (((avctx->coded_width || avctx->coded_height)

        && av_image_check_size(avctx->coded_width, avctx->coded_height, 0, avctx))

        || avctx->channels > SANE_NB_CHANNELS) {

        ret = AVERROR(EINVAL);

        goto free_and_end;

    }



    avctx->codec = codec;

    if ((avctx->codec_type == AVMEDIA_TYPE_UNKNOWN || avctx->codec_type == codec->type) &&

        avctx->codec_id == CODEC_ID_NONE) {

        avctx->codec_type = codec->type;

        avctx->codec_id   = codec->id;

    }

    if(avctx->codec_id != codec->id || avctx->codec_type != codec->type){

        av_log(avctx, AV_LOG_ERROR, "codec type or id mismatches\n");

        goto free_and_end;

    }

    avctx->frame_number = 0;

    if (avctx->codec->max_lowres < avctx->lowres) {

        av_log(avctx, AV_LOG_ERROR, "The maximum value for lowres supported by the decoder is %d\n",

               avctx->codec->max_lowres);

        goto free_and_end;

    }



    if(avctx->codec->init){

        ret = avctx->codec->init(avctx);

        if (ret < 0) {

            goto free_and_end;

        }

    }

    ret=0;

end:

    entangled_thread_counter--;



    /* Release any user-supplied mutex. */

    if (ff_lockmgr_cb) {

        (*ff_lockmgr_cb)(&codec_mutex, AV_LOCK_RELEASE);

    }

    return ret;

free_and_end:

    av_freep(&avctx->priv_data);

    avctx->codec= NULL;

    goto end;

}

static int adx_decode(ADXContext *c, int16_t *out, int offset,

                      const uint8_t *in, int ch)

{

    ADXChannelState *prev = &c->prev[ch];

    GetBitContext gb;

    int scale = AV_RB16(in);

    int i;

    int s0, s1, s2, d;



    /* check if this is an EOF packet */

    if (scale & 0x8000)

        return -1;



    init_get_bits(&gb, in + 2, (BLOCK_SIZE - 2) * 8);

    out += offset;

    s1 = prev->s1;

    s2 = prev->s2;

    for (i = 0; i < BLOCK_SAMPLES; i++) {

        d  = get_sbits(&gb, 4);

        s0 = ((d << COEFF_BITS) * scale + c->coeff[0] * s1 + c->coeff[1] * s2) >> COEFF_BITS;

        s2 = s1;

        s1 = av_clip_int16(s0);

        *out++ = s1;

    }

    prev->s1 = s1;

    prev->s2 = s2;



    return 0;

}

static int ff_asf_get_packet(AVFormatContext *s, AVIOContext *pb)

{

    ASFContext *asf = s->priv_data;

    uint32_t packet_length, padsize;

    int rsize = 8;

    int c, d, e, off;



    // if we do not know packet size, allow skipping up to 32 kB

    off= 32768;

    if (s->packet_size > 0)

        off= (avio_tell(pb) - s->data_offset) % s->packet_size + 3;



    c=d=e=-1;

    while(off-- > 0){

        c=d; d=e;

        e= avio_r8(pb);

        if(c == 0x82 && !d && !e)

            break;




    if (c != 0x82) {

        /**

         * This code allows handling of -EAGAIN at packet boundaries (i.e.

         * if the packet sync code above triggers -EAGAIN). This does not

         * imply complete -EAGAIN handling support at random positions in

         * the stream.

         */

        if (pb->error == AVERROR(EAGAIN))

            return AVERROR(EAGAIN);

        if (!pb->eof_reached)

            av_log(s, AV_LOG_ERROR, "ff asf bad header %x  at:%"PRId64"\n", c, avio_tell(pb));


    if ((c & 0x8f) == 0x82) {

        if (d || e) {

            if (!pb->eof_reached)

                av_log(s, AV_LOG_ERROR, "ff asf bad non zero\n");



        c= avio_r8(pb);

        d= avio_r8(pb);

        rsize+=3;

    }else{

        avio_seek(pb, -1, SEEK_CUR); //FIXME




    asf->packet_flags    = c;

    asf->packet_property = d;



    DO_2BITS(asf->packet_flags >> 5, packet_length, s->packet_size);

    DO_2BITS(asf->packet_flags >> 1, padsize, 0); // sequence ignored

    DO_2BITS(asf->packet_flags >> 3, padsize, 0); // padding length



    //the following checks prevent overflows and infinite loops

    if(!packet_length || packet_length >= (1U<<29)){

        av_log(s, AV_LOG_ERROR, "invalid packet_length %d at:%"PRId64"\n", packet_length, avio_tell(pb));



    if(padsize >= packet_length){

        av_log(s, AV_LOG_ERROR, "invalid padsize %d at:%"PRId64"\n", padsize, avio_tell(pb));





    asf->packet_timestamp = avio_rl32(pb);

    avio_rl16(pb); /* duration */

    // rsize has at least 11 bytes which have to be present



    if (asf->packet_flags & 0x01) {

        asf->packet_segsizetype = avio_r8(pb); rsize++;

        asf->packet_segments = asf->packet_segsizetype & 0x3f;

    } else {

        asf->packet_segments = 1;

        asf->packet_segsizetype = 0x80;









    asf->packet_size_left = packet_length - padsize - rsize;

    if (packet_length < asf->hdr.min_pktsize)

        padsize += asf->hdr.min_pktsize - packet_length;

    asf->packet_padsize = padsize;

    av_dlog(s, "packet: size=%d padsize=%d  left=%d\n", s->packet_size, asf->packet_padsize, asf->packet_size_left);

    return 0;

static int mkv_write_tag(AVFormatContext *s, AVDictionary *m, unsigned int elementid,

                         unsigned int uid, ebml_master *tags)

{

    MatroskaMuxContext *mkv = s->priv_data;

    ebml_master tag, targets;

    AVDictionaryEntry *t = NULL;

    int ret;



    if (!tags->pos) {

        ret = mkv_add_seekhead_entry(mkv->main_seekhead, MATROSKA_ID_TAGS, avio_tell(s->pb));

        if (ret < 0) return ret;



        *tags = start_ebml_master(s->pb, MATROSKA_ID_TAGS, 0);

    }



    tag     = start_ebml_master(s->pb, MATROSKA_ID_TAG,        0);

    targets = start_ebml_master(s->pb, MATROSKA_ID_TAGTARGETS, 0);

    if (elementid)

        put_ebml_uint(s->pb, elementid, uid);

    end_ebml_master(s->pb, targets);



    while ((t = av_dict_get(m, "", t, AV_DICT_IGNORE_SUFFIX)))

        if (av_strcasecmp(t->key, "title") &&

            av_strcasecmp(t->key, "encoding_tool"))

            mkv_write_simpletag(s->pb, t);



    end_ebml_master(s->pb, tag);

    return 0;

}

static int decode_audio_specific_config(AACContext *ac,

                                        AVCodecContext *avctx,

                                        MPEG4AudioConfig *m4ac,

                                        const uint8_t *data, int bit_size,

                                        int sync_extension)

{

    GetBitContext gb;

    int i, ret;



    av_dlog(avctx, "extradata size %d\n", avctx->extradata_size);

    for (i = 0; i < avctx->extradata_size; i++)

        av_dlog(avctx, "%02x ", avctx->extradata[i]);

    av_dlog(avctx, "\n");



    init_get_bits(&gb, data, bit_size);



    if ((i = avpriv_mpeg4audio_get_config(m4ac, data, bit_size,

                                          sync_extension)) < 0)

        return AVERROR_INVALIDDATA;

    if (m4ac->sampling_index > 12) {

        av_log(avctx, AV_LOG_ERROR,

               "invalid sampling rate index %d\n",

               m4ac->sampling_index);

        return AVERROR_INVALIDDATA;

    }



    skip_bits_long(&gb, i);



    switch (m4ac->object_type) {

    case AOT_AAC_MAIN:

    case AOT_AAC_LC:

    case AOT_AAC_LTP:

        if ((ret = decode_ga_specific_config(ac, avctx, &gb,

                                            m4ac, m4ac->chan_config)) < 0)

            return ret;

        break;

    default:

        av_log(avctx, AV_LOG_ERROR,

               "Audio object type %s%d is not supported.\n",

               m4ac->sbr == 1 ? "SBR+" : "",

               m4ac->object_type);

        return AVERROR(ENOSYS);

    }



    av_dlog(avctx,

            "AOT %d chan config %d sampling index %d (%d) SBR %d PS %d\n",

            m4ac->object_type, m4ac->chan_config, m4ac->sampling_index,

            m4ac->sample_rate, m4ac->sbr,

            m4ac->ps);



    return get_bits_count(&gb);

}

static int rv34_set_deblock_coef(RV34DecContext *r)

{

    MpegEncContext *s = &r->s;

    int mvmask = 0, i, j;

    int midx = s->mb_x * 2 + s->mb_y * 2 * s->b8_stride;

    int16_t (*motion_val)[2] = s->current_picture_ptr->motion_val[0][midx];

    if(s->pict_type == FF_I_TYPE)

        return 0;

    for(j = 0; j < 16; j += 8){

        for(i = 0; i < 2; i++){

            if(is_mv_diff_gt_3(motion_val + i, 1))

                mvmask |= 0x11 << (j + i*2);

            if(is_mv_diff_gt_3(motion_val + i, s->b8_stride))

                mvmask |= 0x03 << (j + i*2);

        }

        motion_val += s->b8_stride;

    }

    return mvmask;

}

static int decode_header(MPADecodeContext *s, UINT32 header)

{

    int sample_rate, frame_size, mpeg25, padding;

    int sample_rate_index, bitrate_index;

    if (header & (1<<20)) {

        s->lsf = (header & (1<<19)) ? 0 : 1;

        mpeg25 = 0;

    } else {

        s->lsf = 1;

        mpeg25 = 1;

    }



    s->layer = 4 - ((header >> 17) & 3);

    /* extract frequency */

    sample_rate_index = (header >> 10) & 3;

    sample_rate = mpa_freq_tab[sample_rate_index] >> (s->lsf + mpeg25);

    if (sample_rate == 0)

        return 1;

    sample_rate_index += 3 * (s->lsf + mpeg25);

    s->sample_rate_index = sample_rate_index;

    s->error_protection = ((header >> 16) & 1) ^ 1;



    bitrate_index = (header >> 12) & 0xf;

    padding = (header >> 9) & 1;

    //extension = (header >> 8) & 1;

    s->mode = (header >> 6) & 3;

    s->mode_ext = (header >> 4) & 3;

    //copyright = (header >> 3) & 1;

    //original = (header >> 2) & 1;

    //emphasis = header & 3;



    if (s->mode == MPA_MONO)

        s->nb_channels = 1;

    else

        s->nb_channels = 2;



    if (bitrate_index != 0) {

        frame_size = mpa_bitrate_tab[s->lsf][s->layer - 1][bitrate_index];

        s->bit_rate = frame_size * 1000;

        switch(s->layer) {

        case 1:

            frame_size = (frame_size * 12000) / sample_rate;

            frame_size = (frame_size + padding) * 4;

            break;

        case 2:

            frame_size = (frame_size * 144000) / sample_rate;

            frame_size += padding;

            break;

        default:

        case 3:

            frame_size = (frame_size * 144000) / (sample_rate << s->lsf);

            frame_size += padding;

            break;

        }

        s->frame_size = frame_size;

    } else {

        /* if no frame size computed, signal it */

        if (!s->free_format_frame_size)

            return 1;

        /* free format: compute bitrate and real frame size from the

           frame size we extracted by reading the bitstream */

        s->frame_size = s->free_format_frame_size;

        switch(s->layer) {

        case 1:

            s->frame_size += padding  * 4;

            s->bit_rate = (s->frame_size * sample_rate) / 48000;

            break;

        case 2:

            s->frame_size += padding;

            s->bit_rate = (s->frame_size * sample_rate) / 144000;

            break;

        default:

        case 3:

            s->frame_size += padding;

            s->bit_rate = (s->frame_size * (sample_rate << s->lsf)) / 144000;

            break;

        }

    }

    s->sample_rate = sample_rate;



#ifdef DEBUG

    printf("layer%d, %d Hz, %d kbits/s, ",

           s->layer, s->sample_rate, s->bit_rate);

    if (s->nb_channels == 2) {

        if (s->layer == 3) {

            if (s->mode_ext & MODE_EXT_MS_STEREO)

                printf("ms-");

            if (s->mode_ext & MODE_EXT_I_STEREO)

                printf("i-");

        }

        printf("stereo");

    } else {

        printf("mono");

    }

    printf("\n");

#endif

    return 0;

}

static int avg_bits_per_pixel(int pix_fmt)

{

    int bits;

    const PixFmtInfo *pf;



    pf = &pix_fmt_info[pix_fmt];

    if (pf->is_packed) {

        switch(pix_fmt) {

        case PIX_FMT_RGB24:

        case PIX_FMT_BGR24:

            bits = 24;

            break;

        case PIX_FMT_RGBA32:

            bits = 32;

                        break;

        case PIX_FMT_RGB565:

        case PIX_FMT_RGB555:

            bits = 16;

                        break;

        case PIX_FMT_PAL8:

            bits = 8;

            break;

        default:

            bits = 32;

            break;

        }

    } else {

        bits = pf->depth;

        bits += (2 * pf->depth >> 

                 (pf->x_chroma_shift + pf->x_chroma_shift));

    }

    return bits;

}

