static void get_tag(AVFormatContext *s, AVIOContext *pb, const char *key, int type, int length)

{

    int buf_size = FFMAX(2*length, LEN_PRETTY_GUID) + 1;

    char *buf = av_malloc(buf_size);

    if (!buf)

        return;



    if (type == 0 && length == 4) {

        snprintf(buf, buf_size, "%"PRIi32, avio_rl32(pb));

    } else if (type == 1) {

        avio_get_str16le(pb, length, buf, buf_size);

        if (!strlen(buf)) {

           av_free(buf);

           return;

        }

    } else if (type == 3 && length == 4) {

        strcpy(buf, avio_rl32(pb) ? "true" : "false");

    } else if (type == 4 && length == 8) {

        int64_t num = avio_rl64(pb);

        if (!strcmp(key, "WM/EncodingTime") ||

            !strcmp(key, "WM/MediaOriginalBroadcastDateTime"))

            filetime_to_iso8601(buf, buf_size, num);

        else if (!strcmp(key, "WM/WMRVEncodeTime") ||

                 !strcmp(key, "WM/WMRVEndTime"))

            crazytime_to_iso8601(buf, buf_size, num);

        else if (!strcmp(key, "WM/WMRVExpirationDate"))

            oledate_to_iso8601(buf, buf_size, num);

        else if (!strcmp(key, "WM/WMRVBitrate"))

            snprintf(buf, buf_size, "%f", av_int2dbl(num));

        else

            snprintf(buf, buf_size, "%"PRIi64, num);

    } else if (type == 5 && length == 2) {

        snprintf(buf, buf_size, "%"PRIi16, avio_rl16(pb));

    } else if (type == 6 && length == 16) {

        ff_asf_guid guid;

        avio_read(pb, guid, 16);

        snprintf(buf, buf_size, PRI_PRETTY_GUID, ARG_PRETTY_GUID(guid));

    } else if (type == 2 && !strcmp(key, "WM/Picture")) {

        get_attachment(s, pb, length);

        av_freep(&buf);

        return;

    } else {

        av_freep(&buf);

        av_log(s, AV_LOG_WARNING, "unsupported metadata entry; key:%s, type:%d, length:0x%x\n", key, type, length);

        avio_skip(pb, length);

        return;

    }



    av_metadata_set2(&s->metadata, key, buf, 0);

    av_freep(&buf);

}

void ff_vorbis_floor1_render_list(vorbis_floor1_entry * list, int values,

                                  uint16_t *y_list, int *flag,

                                  int multiplier, float *out, int samples)

{

    int lx, ly, i;

    lx = 0;

    ly = y_list[0] * multiplier;

    for (i = 1; i < values; i++) {

        int pos = list[i].sort;

        if (flag[pos]) {

            int x1 = list[pos].x;

            int y1 = y_list[pos] * multiplier;

            if (lx < samples)

                render_line(lx, ly, FFMIN(x1,samples), y1, out);

            lx = x1;

            ly = y1;

        }

        if (lx >= samples)

            break;

    }

    if (lx < samples)

        render_line(lx, ly, samples, ly, out);

}

static void channel_weighting(float *su1, float *su2, int *p3)

{

    int band, nsample;

    /* w[x][y] y=0 is left y=1 is right */

    float w[2][2];



    if (p3[1] != 7 || p3[3] != 7) {

        get_channel_weights(p3[1], p3[0], w[0]);

        get_channel_weights(p3[3], p3[2], w[1]);



        for (band = 1; band < 4; band++) {

            for (nsample = 0; nsample < 8; nsample++) {

                su1[band * 256 + nsample] *= INTERPOLATE(w[0][0], w[0][1], nsample);

                su2[band * 256 + nsample] *= INTERPOLATE(w[1][0], w[1][1], nsample);

            }

            for(; nsample < 256; nsample++) {

                su1[band * 256  + nsample] *= w[1][0];

                su2[band * 256  + nsample] *= w[1][1];

            }

        }

    }

}

int ff_hevc_decode_nal_pps(HEVCContext *s)

{

    GetBitContext *gb = &s->HEVClc->gb;

    HEVCSPS      *sps = NULL;

    int pic_area_in_ctbs;

    int log2_diff_ctb_min_tb_size;

    int i, j, x, y, ctb_addr_rs, tile_id;

    int ret = 0;

    unsigned int pps_id = 0;



    AVBufferRef *pps_buf;

    HEVCPPS *pps = av_mallocz(sizeof(*pps));



    if (!pps)

        return AVERROR(ENOMEM);



    pps_buf = av_buffer_create((uint8_t *)pps, sizeof(*pps),

                               hevc_pps_free, NULL, 0);

    if (!pps_buf) {

        av_freep(&pps);

        return AVERROR(ENOMEM);

    }



    av_log(s->avctx, AV_LOG_DEBUG, "Decoding PPS\n");



    // Default values

    pps->loop_filter_across_tiles_enabled_flag = 1;

    pps->num_tile_columns                      = 1;

    pps->num_tile_rows                         = 1;

    pps->uniform_spacing_flag                  = 1;

    pps->disable_dbf                           = 0;

    pps->beta_offset                           = 0;

    pps->tc_offset                             = 0;

    pps->log2_max_transform_skip_block_size    = 2;



    // Coded parameters

    pps_id = get_ue_golomb_long(gb);

    if (pps_id >= MAX_PPS_COUNT) {

        av_log(s->avctx, AV_LOG_ERROR, "PPS id out of range: %d\n", pps_id);

        ret = AVERROR_INVALIDDATA;

        goto err;

    }

    pps->sps_id = get_ue_golomb_long(gb);

    if (pps->sps_id >= MAX_SPS_COUNT) {

        av_log(s->avctx, AV_LOG_ERROR, "SPS id out of range: %d\n", pps->sps_id);

        ret = AVERROR_INVALIDDATA;

        goto err;

    }

    if (!s->sps_list[pps->sps_id]) {

        av_log(s->avctx, AV_LOG_ERROR, "SPS %u does not exist.\n", pps->sps_id);

        ret = AVERROR_INVALIDDATA;

        goto err;

    }

    sps = (HEVCSPS *)s->sps_list[pps->sps_id]->data;



    pps->dependent_slice_segments_enabled_flag = get_bits1(gb);

    pps->output_flag_present_flag              = get_bits1(gb);

    pps->num_extra_slice_header_bits           = get_bits(gb, 3);



    pps->sign_data_hiding_flag = get_bits1(gb);



    pps->cabac_init_present_flag = get_bits1(gb);



    pps->num_ref_idx_l0_default_active = get_ue_golomb_long(gb) + 1;

    pps->num_ref_idx_l1_default_active = get_ue_golomb_long(gb) + 1;



    pps->pic_init_qp_minus26 = get_se_golomb(gb);



    pps->constrained_intra_pred_flag = get_bits1(gb);

    pps->transform_skip_enabled_flag = get_bits1(gb);



    pps->cu_qp_delta_enabled_flag = get_bits1(gb);

    pps->diff_cu_qp_delta_depth   = 0;

    if (pps->cu_qp_delta_enabled_flag)

        pps->diff_cu_qp_delta_depth = get_ue_golomb_long(gb);



    pps->cb_qp_offset = get_se_golomb(gb);

    if (pps->cb_qp_offset < -12 || pps->cb_qp_offset > 12) {

        av_log(s->avctx, AV_LOG_ERROR, "pps_cb_qp_offset out of range: %d\n",

               pps->cb_qp_offset);

        ret = AVERROR_INVALIDDATA;

        goto err;

    }

    pps->cr_qp_offset = get_se_golomb(gb);

    if (pps->cr_qp_offset < -12 || pps->cr_qp_offset > 12) {

        av_log(s->avctx, AV_LOG_ERROR, "pps_cr_qp_offset out of range: %d\n",

               pps->cr_qp_offset);

        ret = AVERROR_INVALIDDATA;

        goto err;

    }

    pps->pic_slice_level_chroma_qp_offsets_present_flag = get_bits1(gb);



    pps->weighted_pred_flag   = get_bits1(gb);

    pps->weighted_bipred_flag = get_bits1(gb);



    pps->transquant_bypass_enable_flag    = get_bits1(gb);

    pps->tiles_enabled_flag               = get_bits1(gb);

    pps->entropy_coding_sync_enabled_flag = get_bits1(gb);



    if (pps->tiles_enabled_flag) {

        pps->num_tile_columns = get_ue_golomb_long(gb) + 1;

        pps->num_tile_rows    = get_ue_golomb_long(gb) + 1;

        if (pps->num_tile_columns == 0 ||

            pps->num_tile_columns >= sps->width) {

            av_log(s->avctx, AV_LOG_ERROR, "num_tile_columns_minus1 out of range: %d\n",

                   pps->num_tile_columns - 1);

            ret = AVERROR_INVALIDDATA;

            goto err;

        }

        if (pps->num_tile_rows == 0 ||

            pps->num_tile_rows >= sps->height) {

            av_log(s->avctx, AV_LOG_ERROR, "num_tile_rows_minus1 out of range: %d\n",

                   pps->num_tile_rows - 1);

            ret = AVERROR_INVALIDDATA;

            goto err;

        }



        pps->column_width = av_malloc_array(pps->num_tile_columns, sizeof(*pps->column_width));

        pps->row_height   = av_malloc_array(pps->num_tile_rows,    sizeof(*pps->row_height));

        if (!pps->column_width || !pps->row_height) {

            ret = AVERROR(ENOMEM);

            goto err;

        }



        pps->uniform_spacing_flag = get_bits1(gb);

        if (!pps->uniform_spacing_flag) {

            uint64_t sum = 0;

            for (i = 0; i < pps->num_tile_columns - 1; i++) {

                pps->column_width[i] = get_ue_golomb_long(gb) + 1;

                sum                 += pps->column_width[i];

            }

            if (sum >= sps->ctb_width) {

                av_log(s->avctx, AV_LOG_ERROR, "Invalid tile widths.\n");

                ret = AVERROR_INVALIDDATA;

                goto err;

            }

            pps->column_width[pps->num_tile_columns - 1] = sps->ctb_width - sum;



            sum = 0;

            for (i = 0; i < pps->num_tile_rows - 1; i++) {

                pps->row_height[i] = get_ue_golomb_long(gb) + 1;

                sum               += pps->row_height[i];

            }

            if (sum >= sps->ctb_height) {

                av_log(s->avctx, AV_LOG_ERROR, "Invalid tile heights.\n");

                ret = AVERROR_INVALIDDATA;

                goto err;

            }

            pps->row_height[pps->num_tile_rows - 1] = sps->ctb_height - sum;

        }

        pps->loop_filter_across_tiles_enabled_flag = get_bits1(gb);

    }



    pps->seq_loop_filter_across_slices_enabled_flag = get_bits1(gb);



    pps->deblocking_filter_control_present_flag = get_bits1(gb);

    if (pps->deblocking_filter_control_present_flag) {

        pps->deblocking_filter_override_enabled_flag = get_bits1(gb);

        pps->disable_dbf                             = get_bits1(gb);

        if (!pps->disable_dbf) {

            pps->beta_offset = get_se_golomb(gb) * 2;

            pps->tc_offset = get_se_golomb(gb) * 2;

            if (pps->beta_offset/2 < -6 || pps->beta_offset/2 > 6) {

                av_log(s->avctx, AV_LOG_ERROR, "pps_beta_offset_div2 out of range: %d\n",

                       pps->beta_offset/2);

                ret = AVERROR_INVALIDDATA;

                goto err;

            }

            if (pps->tc_offset/2 < -6 || pps->tc_offset/2 > 6) {

                av_log(s->avctx, AV_LOG_ERROR, "pps_tc_offset_div2 out of range: %d\n",

                       pps->tc_offset/2);

                ret = AVERROR_INVALIDDATA;

                goto err;

            }

        }

    }



    pps->scaling_list_data_present_flag = get_bits1(gb);

    if (pps->scaling_list_data_present_flag) {

        set_default_scaling_list_data(&pps->scaling_list);

        ret = scaling_list_data(s, &pps->scaling_list, sps);

        if (ret < 0)

            goto err;

    }

    pps->lists_modification_present_flag = get_bits1(gb);

    pps->log2_parallel_merge_level       = get_ue_golomb_long(gb) + 2;

    if (pps->log2_parallel_merge_level > sps->log2_ctb_size) {

        av_log(s->avctx, AV_LOG_ERROR, "log2_parallel_merge_level_minus2 out of range: %d\n",

               pps->log2_parallel_merge_level - 2);

        ret = AVERROR_INVALIDDATA;

        goto err;

    }



    pps->slice_header_extension_present_flag = get_bits1(gb);



    if (get_bits1(gb)) { // pps_extension_present_flag

        int pps_range_extensions_flag = get_bits1(gb);

        /* int pps_extension_7bits = */ get_bits(gb, 7);

        if (sps->ptl.general_ptl.profile_idc == FF_PROFILE_HEVC_REXT && pps_range_extensions_flag) {

            pps_range_extensions(s, pps, sps);

        }

    }



    // Inferred parameters

    pps->col_bd   = av_malloc_array(pps->num_tile_columns + 1, sizeof(*pps->col_bd));

    pps->row_bd   = av_malloc_array(pps->num_tile_rows + 1,    sizeof(*pps->row_bd));

    pps->col_idxX = av_malloc_array(sps->ctb_width,    sizeof(*pps->col_idxX));

    if (!pps->col_bd || !pps->row_bd || !pps->col_idxX) {

        ret = AVERROR(ENOMEM);

        goto err;

    }



    if (pps->uniform_spacing_flag) {

        if (!pps->column_width) {

            pps->column_width = av_malloc_array(pps->num_tile_columns, sizeof(*pps->column_width));

            pps->row_height   = av_malloc_array(pps->num_tile_rows,    sizeof(*pps->row_height));

        }

        if (!pps->column_width || !pps->row_height) {

            ret = AVERROR(ENOMEM);

            goto err;

        }



        for (i = 0; i < pps->num_tile_columns; i++) {

            pps->column_width[i] = ((i + 1) * sps->ctb_width) / pps->num_tile_columns -

                                   (i * sps->ctb_width) / pps->num_tile_columns;

        }



        for (i = 0; i < pps->num_tile_rows; i++) {

            pps->row_height[i] = ((i + 1) * sps->ctb_height) / pps->num_tile_rows -

                                 (i * sps->ctb_height) / pps->num_tile_rows;

        }

    }



    pps->col_bd[0] = 0;

    for (i = 0; i < pps->num_tile_columns; i++)

        pps->col_bd[i + 1] = pps->col_bd[i] + pps->column_width[i];



    pps->row_bd[0] = 0;

    for (i = 0; i < pps->num_tile_rows; i++)

        pps->row_bd[i + 1] = pps->row_bd[i] + pps->row_height[i];



    for (i = 0, j = 0; i < sps->ctb_width; i++) {

        if (i > pps->col_bd[j])

            j++;

        pps->col_idxX[i] = j;

    }



    /**

     * 6.5

     */

    pic_area_in_ctbs     = sps->ctb_width    * sps->ctb_height;



    pps->ctb_addr_rs_to_ts = av_malloc_array(pic_area_in_ctbs,    sizeof(*pps->ctb_addr_rs_to_ts));

    pps->ctb_addr_ts_to_rs = av_malloc_array(pic_area_in_ctbs,    sizeof(*pps->ctb_addr_ts_to_rs));

    pps->tile_id           = av_malloc_array(pic_area_in_ctbs,    sizeof(*pps->tile_id));

    pps->min_tb_addr_zs_tab = av_malloc_array((sps->tb_mask+2) * (sps->tb_mask+2), sizeof(*pps->min_tb_addr_zs_tab));

    if (!pps->ctb_addr_rs_to_ts || !pps->ctb_addr_ts_to_rs ||

        !pps->tile_id || !pps->min_tb_addr_zs_tab) {

        ret = AVERROR(ENOMEM);

        goto err;

    }



    for (ctb_addr_rs = 0; ctb_addr_rs < pic_area_in_ctbs; ctb_addr_rs++) {

        int tb_x   = ctb_addr_rs % sps->ctb_width;

        int tb_y   = ctb_addr_rs / sps->ctb_width;

        int tile_x = 0;

        int tile_y = 0;

        int val    = 0;



        for (i = 0; i < pps->num_tile_columns; i++) {

            if (tb_x < pps->col_bd[i + 1]) {

                tile_x = i;

                break;

            }

        }



        for (i = 0; i < pps->num_tile_rows; i++) {

            if (tb_y < pps->row_bd[i + 1]) {

                tile_y = i;

                break;

            }

        }



        for (i = 0; i < tile_x; i++)

            val += pps->row_height[tile_y] * pps->column_width[i];

        for (i = 0; i < tile_y; i++)

            val += sps->ctb_width * pps->row_height[i];



        val += (tb_y - pps->row_bd[tile_y]) * pps->column_width[tile_x] +

               tb_x - pps->col_bd[tile_x];



        pps->ctb_addr_rs_to_ts[ctb_addr_rs] = val;

        pps->ctb_addr_ts_to_rs[val]         = ctb_addr_rs;

    }



    for (j = 0, tile_id = 0; j < pps->num_tile_rows; j++)

        for (i = 0; i < pps->num_tile_columns; i++, tile_id++)

            for (y = pps->row_bd[j]; y < pps->row_bd[j + 1]; y++)

                for (x = pps->col_bd[i]; x < pps->col_bd[i + 1]; x++)

                    pps->tile_id[pps->ctb_addr_rs_to_ts[y * sps->ctb_width + x]] = tile_id;



    pps->tile_pos_rs = av_malloc_array(tile_id, sizeof(*pps->tile_pos_rs));

    if (!pps->tile_pos_rs) {

        ret = AVERROR(ENOMEM);

        goto err;

    }



    for (j = 0; j < pps->num_tile_rows; j++)

        for (i = 0; i < pps->num_tile_columns; i++)

            pps->tile_pos_rs[j * pps->num_tile_columns + i] = pps->row_bd[j] * sps->ctb_width + pps->col_bd[i];



    log2_diff_ctb_min_tb_size = sps->log2_ctb_size - sps->log2_min_tb_size;

    pps->min_tb_addr_zs = &pps->min_tb_addr_zs_tab[1*(sps->tb_mask+2)+1];

    for (y = 0; y < sps->tb_mask+2; y++) {

        pps->min_tb_addr_zs_tab[y*(sps->tb_mask+2)] = -1;

        pps->min_tb_addr_zs_tab[y]    = -1;

    }

    for (y = 0; y < sps->tb_mask+1; y++) {

        for (x = 0; x < sps->tb_mask+1; x++) {

            int tb_x        = x >> log2_diff_ctb_min_tb_size;

            int tb_y        = y >> log2_diff_ctb_min_tb_size;

            int ctb_addr_rs = sps->ctb_width * tb_y + tb_x;

            int val         = pps->ctb_addr_rs_to_ts[ctb_addr_rs] <<

                              (log2_diff_ctb_min_tb_size * 2);

            for (i = 0; i < log2_diff_ctb_min_tb_size; i++) {

                int m = 1 << i;

                val += (m & x ? m * m : 0) + (m & y ? 2 * m * m : 0);

            }

            pps->min_tb_addr_zs[y * (sps->tb_mask+2) + x] = val;

        }

    }



    if (get_bits_left(gb) < 0) {

        av_log(s->avctx, AV_LOG_ERROR,

               "Overread PPS by %d bits\n", -get_bits_left(gb));

        goto err;

    }



    av_buffer_unref(&s->pps_list[pps_id]);

    s->pps_list[pps_id] = pps_buf;



    return 0;



err:

    av_buffer_unref(&pps_buf);

    return ret;

}

static int read_packet(ByteIOContext *pb, uint8_t *buf, int raw_packet_size)

{

    int skip, len;



    for(;;) {

        len = get_buffer(pb, buf, TS_PACKET_SIZE);

        if (len != TS_PACKET_SIZE)

            return AVERROR(EIO);

        /* check paquet sync byte */

        if (buf[0] != 0x47) {

            /* find a new packet start */

            url_fseek(pb, -TS_PACKET_SIZE, SEEK_CUR);

            if (mpegts_resync(pb) < 0)

                return AVERROR_INVALIDDATA;

            else

                continue;

        } else {

            skip = raw_packet_size - TS_PACKET_SIZE;

            if (skip > 0)

                url_fskip(pb, skip);

            break;

        }

    }

    return 0;

}

av_cold void ff_fft_init_arm(FFTContext *s)

{

    if (HAVE_NEON) {

        s->fft_permute  = ff_fft_permute_neon;

        s->fft_calc     = ff_fft_calc_neon;

        s->imdct_calc   = ff_imdct_calc_neon;

        s->imdct_half   = ff_imdct_half_neon;

        s->mdct_calc    = ff_mdct_calc_neon;

        s->permutation  = FF_MDCT_PERM_INTERLEAVE;

    }

}

int ff_jpegls_decode_picture(MJpegDecodeContext *s, int near, int point_transform, int ilv){

    int i, t = 0;

    uint8_t *zero, *last, *cur;

    JLSState *state;

    int off = 0, stride = 1, width, shift;



    zero = av_mallocz(s->picture.linesize[0]);

    last = zero;

    cur = s->picture.data[0];



    state = av_mallocz(sizeof(JLSState));

    /* initialize JPEG-LS state from JPEG parameters */

    state->near = near;

    state->bpp = (s->bits < 2) ? 2 : s->bits;

    state->maxval = s->maxval;

    state->T1 = s->t1;

    state->T2 = s->t2;

    state->T3 = s->t3;

    state->reset = s->reset;

    ff_jpegls_reset_coding_parameters(state, 0);

    ff_jpegls_init_state(state);



    if(s->bits <= 8)

        shift = point_transform + (8 - s->bits);

    else

        shift = point_transform + (16 - s->bits);



    if (s->avctx->debug & FF_DEBUG_PICT_INFO) {

        av_log(s->avctx, AV_LOG_DEBUG, "JPEG-LS params: %ix%i NEAR=%i MV=%i T(%i,%i,%i) RESET=%i, LIMIT=%i, qbpp=%i, RANGE=%i\n",

                s->width, s->height, state->near, state->maxval,

                state->T1, state->T2, state->T3,

                state->reset, state->limit, state->qbpp, state->range);

        av_log(s->avctx, AV_LOG_DEBUG, "JPEG params: ILV=%i Pt=%i BPP=%i, scan = %i\n",

                ilv, point_transform, s->bits, s->cur_scan);

    }

    if(ilv == 0) { /* separate planes */

        stride = (s->nb_components > 1) ? 3 : 1;

        off = av_clip(s->cur_scan - 1, 0, stride);

        width = s->width * stride;

        cur += off;

        for(i = 0; i < s->height; i++) {

            if(s->bits <= 8){

                ls_decode_line(state, s, last, cur, t, width, stride, off,  8);

                t = last[0];

            }else{

                ls_decode_line(state, s, last, cur, t, width, stride, off, 16);

                t = *((uint16_t*)last);

            }

            last = cur;

            cur += s->picture.linesize[0];



            if (s->restart_interval && !--s->restart_count) {

                align_get_bits(&s->gb);

                skip_bits(&s->gb, 16); /* skip RSTn */

            }

        }

    } else if(ilv == 1) { /* line interleaving */

        int j;

        int Rc[3] = {0, 0, 0};

        stride = (s->nb_components > 1) ? 3 : 1;

        memset(cur, 0, s->picture.linesize[0]);

        width = s->width * stride;

        for(i = 0; i < s->height; i++) {

            for(j = 0; j < stride; j++) {

                ls_decode_line(state, s, last + j, cur + j, Rc[j], width, stride, j, 8);

                Rc[j] = last[j];



                if (s->restart_interval && !--s->restart_count) {

                    align_get_bits(&s->gb);

                    skip_bits(&s->gb, 16); /* skip RSTn */

                }

            }

            last = cur;

            cur += s->picture.linesize[0];

        }

    } else if(ilv == 2) { /* sample interleaving */

        av_log(s->avctx, AV_LOG_ERROR, "Sample interleaved images are not supported.\n");

        av_free(state);

        av_free(zero);

        return -1;

    }



    if(shift){ /* we need to do point transform or normalize samples */

        int x, w;



        w = s->width * s->nb_components;



        if(s->bits <= 8){

            uint8_t *src = s->picture.data[0];



            for(i = 0; i < s->height; i++){

                for(x = off; x < w; x+= stride){

                    src[x] <<= shift;

                }

                src += s->picture.linesize[0];

            }

        }else{

            uint16_t *src = (uint16_t*) s->picture.data[0];



            for(i = 0; i < s->height; i++){

                for(x = 0; x < w; x++){

                    src[x] <<= shift;

                }

                src += s->picture.linesize[0]/2;

            }

        }

    }

    av_free(state);

    av_free(zero);



    return 0;

}

static void change_qscale(MpegEncContext * s, int dquant)

{

    s->qscale += dquant;



    if (s->qscale < 1)

        s->qscale = 1;

    else if (s->qscale > 31)

        s->qscale = 31;



    s->y_dc_scale= s->y_dc_scale_table[ s->qscale ];

    s->c_dc_scale= s->c_dc_scale_table[ s->qscale ];

}

void av_set_pts_info(AVStream *s, int pts_wrap_bits,

                     unsigned int pts_num, unsigned int pts_den)

{

    unsigned int gcd= av_gcd(pts_num, pts_den);

    s->pts_wrap_bits = pts_wrap_bits;

    s->time_base.num = pts_num/gcd;

    s->time_base.den = pts_den/gcd;



    if(gcd>1)

        av_log(NULL, AV_LOG_DEBUG, "st:%d removing common factor %d from timebase\n", s->index, gcd);

}

static int msvideo1_decode_init(AVCodecContext *avctx)

{

    Msvideo1Context *s = avctx->priv_data;



    s->avctx = avctx;



    /* figure out the colorspace based on the presence of a palette */

    if (s->avctx->palctrl) {

        s->mode_8bit = 1;

        avctx->pix_fmt = PIX_FMT_PAL8;

    } else {

        s->mode_8bit = 0;

        avctx->pix_fmt = PIX_FMT_RGB555;

    }



    dsputil_init(&s->dsp, avctx);



    s->frame.data[0] = NULL;



    return 0;

}

static void convert_matrix(DSPContext *dsp, int (*qmat)[64], uint16_t (*qmat16)[2][64],

                           const uint16_t *quant_matrix, int bias, int qmin, int qmax)

{

    int qscale;



    for(qscale=qmin; qscale<=qmax; qscale++){

        int i;

        if (dsp->fdct == ff_jpeg_fdct_islow 

#ifdef FAAN_POSTSCALE

            || dsp->fdct == ff_faandct

#endif

            ) {

            for(i=0;i<64;i++) {

                const int j= dsp->idct_permutation[i];

                /* 16 <= qscale * quant_matrix[i] <= 7905 */

                /* 19952         <= aanscales[i] * qscale * quant_matrix[i]           <= 249205026 */

                /* (1<<36)/19952 >= (1<<36)/(aanscales[i] * qscale * quant_matrix[i]) >= (1<<36)/249205026 */

                /* 3444240       >= (1<<36)/(aanscales[i] * qscale * quant_matrix[i]) >= 275 */



                qmat[qscale][i] = (int)((uint64_t_C(1) << QMAT_SHIFT) / 

                                (qscale * quant_matrix[j]));

            }

        } else if (dsp->fdct == fdct_ifast

#ifndef FAAN_POSTSCALE

                   || dsp->fdct == ff_faandct

#endif

                   ) {

            for(i=0;i<64;i++) {

                const int j= dsp->idct_permutation[i];

                /* 16 <= qscale * quant_matrix[i] <= 7905 */

                /* 19952         <= aanscales[i] * qscale * quant_matrix[i]           <= 249205026 */

                /* (1<<36)/19952 >= (1<<36)/(aanscales[i] * qscale * quant_matrix[i]) >= (1<<36)/249205026 */

                /* 3444240       >= (1<<36)/(aanscales[i] * qscale * quant_matrix[i]) >= 275 */



                qmat[qscale][i] = (int)((uint64_t_C(1) << (QMAT_SHIFT + 14)) / 

                                (aanscales[i] * qscale * quant_matrix[j]));

            }

        } else {

            for(i=0;i<64;i++) {

                const int j= dsp->idct_permutation[i];

                /* We can safely suppose that 16 <= quant_matrix[i] <= 255

                   So 16           <= qscale * quant_matrix[i]             <= 7905

                   so (1<<19) / 16 >= (1<<19) / (qscale * quant_matrix[i]) >= (1<<19) / 7905

                   so 32768        >= (1<<19) / (qscale * quant_matrix[i]) >= 67

                */

                qmat[qscale][i] = (int)((uint64_t_C(1) << QMAT_SHIFT) / (qscale * quant_matrix[j]));

//                qmat  [qscale][i] = (1 << QMAT_SHIFT_MMX) / (qscale * quant_matrix[i]);

                qmat16[qscale][0][i] = (1 << QMAT_SHIFT_MMX) / (qscale * quant_matrix[j]);



                if(qmat16[qscale][0][i]==0 || qmat16[qscale][0][i]==128*256) qmat16[qscale][0][i]=128*256-1;

                qmat16[qscale][1][i]= ROUNDED_DIV(bias<<(16-QUANT_BIAS_SHIFT), qmat16[qscale][0][i]);

            }

        }

    }

}

static int encode_dvd_subtitles(uint8_t *outbuf, int outbuf_size,

                                const AVSubtitle *h)

{

    uint8_t *q, *qq;

    int object_id;

    int offset1[20], offset2[20];

    int i, imax, color, alpha, rects = h->num_rects;

    unsigned long hmax;

    unsigned long hist[256];

    int           cmap[256];



    if (rects == 0 || h->rects == NULL)

        return -1;

    if (rects > 20)

        rects = 20;



    // analyze bitmaps, compress to 4 colors

    for (i=0; i<256; ++i) {

        hist[i] = 0;

        cmap[i] = 0;

    }

    for (object_id = 0; object_id < rects; object_id++)

        for (i=0; i<h->rects[object_id]->w*h->rects[object_id]->h; ++i) {

            color = h->rects[object_id]->pict.data[0][i];

            // only count non-transparent pixels

            alpha = ((uint32_t*)h->rects[object_id]->pict.data[1])[color] >> 24;

            hist[color] += alpha;

        }

    for (color=3;; --color) {

        hmax = 0;

        imax = 0;

        for (i=0; i<256; ++i)

            if (hist[i] > hmax) {

                imax = i;

                hmax = hist[i];

            }

        if (hmax == 0)

            break;

        if (color == 0)

            color = 3;

        av_log(NULL, AV_LOG_DEBUG, "dvd_subtitle hist[%d]=%ld -> col %d\n",

               imax, hist[imax], color);

        cmap[imax] = color;

        hist[imax] = 0;

    }





    // encode data block

    q = outbuf + 4;

    for (object_id = 0; object_id < rects; object_id++) {

        offset1[object_id] = q - outbuf;

        // worst case memory requirement: 1 nibble per pixel..

        if ((q - outbuf) + h->rects[object_id]->w*h->rects[object_id]->h/2

            + 17*rects + 21 > outbuf_size) {

            av_log(NULL, AV_LOG_ERROR, "dvd_subtitle too big\n");

            return -1;

        }

        dvd_encode_rle(&q, h->rects[object_id]->pict.data[0],

                       h->rects[object_id]->w*2,

                       h->rects[object_id]->w, h->rects[object_id]->h >> 1,

                       cmap);

        offset2[object_id] = q - outbuf;

        dvd_encode_rle(&q, h->rects[object_id]->pict.data[0] + h->rects[object_id]->w,

                       h->rects[object_id]->w*2,

                       h->rects[object_id]->w, h->rects[object_id]->h >> 1,

                       cmap);

    }



    // set data packet size

    qq = outbuf + 2;

    bytestream_put_be16(&qq, q - outbuf);



    // send start display command

    bytestream_put_be16(&q, (h->start_display_time*90) >> 10);

    bytestream_put_be16(&q, (q - outbuf) /*- 2 */ + 8 + 12*rects + 2);

    *q++ = 0x03; // palette - 4 nibbles

    *q++ = 0x03; *q++ = 0x7f;

    *q++ = 0x04; // alpha - 4 nibbles

    *q++ = 0xf0; *q++ = 0x00;

    //*q++ = 0x0f; *q++ = 0xff;



    // XXX not sure if more than one rect can really be encoded..

    // 12 bytes per rect

    for (object_id = 0; object_id < rects; object_id++) {

        int x2 = h->rects[object_id]->x + h->rects[object_id]->w - 1;

        int y2 = h->rects[object_id]->y + h->rects[object_id]->h - 1;



        *q++ = 0x05;

        // x1 x2 -> 6 nibbles

        *q++ = h->rects[object_id]->x >> 4;

        *q++ = (h->rects[object_id]->x << 4) | ((x2 >> 8) & 0xf);

        *q++ = x2;

        // y1 y2 -> 6 nibbles

        *q++ = h->rects[object_id]->y >> 4;

        *q++ = (h->rects[object_id]->y << 4) | ((y2 >> 8) & 0xf);

        *q++ = y2;



        *q++ = 0x06;

        // offset1, offset2

        bytestream_put_be16(&q, offset1[object_id]);

        bytestream_put_be16(&q, offset2[object_id]);

    }

    *q++ = 0x01; // start command

    *q++ = 0xff; // terminating command



    // send stop display command last

    bytestream_put_be16(&q, (h->end_display_time*90) >> 10);

    bytestream_put_be16(&q, (q - outbuf) - 2 /*+ 4*/);

    *q++ = 0x02; // set end

    *q++ = 0xff; // terminating command



    qq = outbuf;

    bytestream_put_be16(&qq, q - outbuf);



    av_log(NULL, AV_LOG_DEBUG, "subtitle_packet size=%td\n", q - outbuf);

    return q - outbuf;

}

static int bit_allocation(IMCContext *q, IMCChannel *chctx,
                          int stream_format_code, int freebits, int flag)
{
    int i, j;
    const float limit = -1.e20;
    float highest = 0.0;
    int indx;
    int t1 = 0;
    int t2 = 1;
    float summa = 0.0;
    int iacc = 0;
    int summer = 0;
    int rres, cwlen;
    float lowest = 1.e10;
    int low_indx = 0;
    float workT[32];
    int flg;
    int found_indx = 0;
    for (i = 0; i < BANDS; i++)
        highest = FFMAX(highest, chctx->flcoeffs1[i]);
    for (i = 0; i < BANDS - 1; i++)
        chctx->flcoeffs4[i] = chctx->flcoeffs3[i] - log2f(chctx->flcoeffs5[i]);
    chctx->flcoeffs4[BANDS - 1] = limit;
    highest = highest * 0.25;
    for (i = 0; i < BANDS; i++) {
        indx = -1;
        if ((band_tab[i + 1] - band_tab[i]) == chctx->bandWidthT[i])
            indx = 0;
        if ((band_tab[i + 1] - band_tab[i]) > chctx->bandWidthT[i])
            indx = 1;
        if (((band_tab[i + 1] - band_tab[i]) / 2) >= chctx->bandWidthT[i])
            indx = 2;
        if (indx == -1)
        chctx->flcoeffs4[i] += xTab[(indx * 2 + (chctx->flcoeffs1[i] < highest)) * 2 + flag];
    }
    if (stream_format_code & 0x2) {
        chctx->flcoeffs4[0] = limit;
        chctx->flcoeffs4[1] = limit;
        chctx->flcoeffs4[2] = limit;
        chctx->flcoeffs4[3] = limit;
    }
    for (i = (stream_format_code & 0x2) ? 4 : 0; i < BANDS - 1; i++) {
        iacc  += chctx->bandWidthT[i];
        summa += chctx->bandWidthT[i] * chctx->flcoeffs4[i];
    }
    chctx->bandWidthT[BANDS - 1] = 0;
    summa = (summa * 0.5 - freebits) / iacc;
    for (i = 0; i < BANDS / 2; i++) {
        rres = summer - freebits;
        if ((rres >= -8) && (rres <= 8))
            break;
        summer = 0;
        iacc   = 0;
        for (j = (stream_format_code & 0x2) ? 4 : 0; j < BANDS; j++) {
            cwlen = av_clipf(((chctx->flcoeffs4[j] * 0.5) - summa + 0.5), 0, 6);
            chctx->bitsBandT[j] = cwlen;
            summer += chctx->bandWidthT[j] * cwlen;
            if (cwlen > 0)
                iacc += chctx->bandWidthT[j];
        }
        flg = t2;
        t2 = 1;
        if (freebits < summer)
            t2 = -1;
        if (i == 0)
            flg = t2;
        if (flg != t2)
            t1++;
        summa = (float)(summer - freebits) / ((t1 + 1) * iacc) + summa;
    }
    for (i = (stream_format_code & 0x2) ? 4 : 0; i < BANDS; i++) {
        for (j = band_tab[i]; j < band_tab[i + 1]; j++)
            chctx->CWlengthT[j] = chctx->bitsBandT[i];
    }
    if (freebits > summer) {
        for (i = 0; i < BANDS; i++) {
            workT[i] = (chctx->bitsBandT[i] == 6) ? -1.e20
                                              : (chctx->bitsBandT[i] * -2 + chctx->flcoeffs4[i] - 0.415);
        }
        highest = 0.0;
        do {
            if (highest <= -1.e20)
                break;
            found_indx = 0;
            highest = -1.e20;
            for (i = 0; i < BANDS; i++) {
                if (workT[i] > highest) {
                    highest = workT[i];
                    found_indx = i;
                }
            }
            if (highest > -1.e20) {
                workT[found_indx] -= 2.0;
                if (++chctx->bitsBandT[found_indx] == 6)
                    workT[found_indx] = -1.e20;
                for (j = band_tab[found_indx]; j < band_tab[found_indx + 1] && (freebits > summer); j++) {
                    chctx->CWlengthT[j]++;
                    summer++;
                }
            }
        } while (freebits > summer);
    }
    if (freebits < summer) {
        for (i = 0; i < BANDS; i++) {
            workT[i] = chctx->bitsBandT[i] ? (chctx->bitsBandT[i] * -2 + chctx->flcoeffs4[i] + 1.585)
                                       : 1.e20;
        }
        if (stream_format_code & 0x2) {
            workT[0] = 1.e20;
            workT[1] = 1.e20;
            workT[2] = 1.e20;
            workT[3] = 1.e20;
        }
        while (freebits < summer) {
            lowest   = 1.e10;
            low_indx = 0;
            for (i = 0; i < BANDS; i++) {
                if (workT[i] < lowest) {
                    lowest   = workT[i];
                    low_indx = i;
                }
            }
            // if (lowest >= 1.e10)
            //     break;
            workT[low_indx] = lowest + 2.0;
            if (!--chctx->bitsBandT[low_indx])
                workT[low_indx] = 1.e20;
            for (j = band_tab[low_indx]; j < band_tab[low_indx+1] && (freebits < summer); j++) {
                if (chctx->CWlengthT[j] > 0) {
                    chctx->CWlengthT[j]--;
                    summer--;
                }
            }
        }
    }
    return 0;
}

static int sox_read_header(AVFormatContext *s)

{

    AVIOContext *pb = s->pb;

    unsigned header_size, comment_size;

    double sample_rate, sample_rate_frac;

    AVStream *st;



    st = avformat_new_stream(s, NULL);

    if (!st)

        return AVERROR(ENOMEM);



    st->codecpar->codec_type = AVMEDIA_TYPE_AUDIO;



    if (avio_rl32(pb) == SOX_TAG) {

        st->codecpar->codec_id = AV_CODEC_ID_PCM_S32LE;

        header_size         = avio_rl32(pb);

        avio_skip(pb, 8); /* sample count */

        sample_rate         = av_int2double(avio_rl64(pb));

        st->codecpar->channels = avio_rl32(pb);

        comment_size        = avio_rl32(pb);

    } else {

        st->codecpar->codec_id = AV_CODEC_ID_PCM_S32BE;

        header_size         = avio_rb32(pb);

        avio_skip(pb, 8); /* sample count */

        sample_rate         = av_int2double(avio_rb64(pb));

        st->codecpar->channels = avio_rb32(pb);

        comment_size        = avio_rb32(pb);

    }



    if (comment_size > 0xFFFFFFFFU - SOX_FIXED_HDR - 4U) {

        av_log(s, AV_LOG_ERROR, "invalid comment size (%u)\n", comment_size);

        return AVERROR_INVALIDDATA;

    }



    if (sample_rate <= 0 || sample_rate > INT_MAX) {

        av_log(s, AV_LOG_ERROR, "invalid sample rate (%f)\n", sample_rate);

        return AVERROR_INVALIDDATA;

    }



    sample_rate_frac = sample_rate - floor(sample_rate);

    if (sample_rate_frac)

        av_log(s, AV_LOG_WARNING,

               "truncating fractional part of sample rate (%f)\n",

               sample_rate_frac);



    if ((header_size + 4) & 7 || header_size < SOX_FIXED_HDR + comment_size

        || st->codecpar->channels > 65535) /* Reserve top 16 bits */ {

        av_log(s, AV_LOG_ERROR, "invalid header\n");

        return AVERROR_INVALIDDATA;

    }



    if (comment_size && comment_size < UINT_MAX) {

        char *comment = av_malloc(comment_size+1);

        if(!comment)

            return AVERROR(ENOMEM);

        if (avio_read(pb, comment, comment_size) != comment_size) {

            av_freep(&comment);

            return AVERROR(EIO);

        }

        comment[comment_size] = 0;



        av_dict_set(&s->metadata, "comment", comment,

                               AV_DICT_DONT_STRDUP_VAL);

    }



    avio_skip(pb, header_size - SOX_FIXED_HDR - comment_size);



    st->codecpar->sample_rate           = sample_rate;

    st->codecpar->bits_per_coded_sample = 32;

    st->codecpar->bit_rate              = st->codecpar->sample_rate *

                                          st->codecpar->bits_per_coded_sample *

                                          st->codecpar->channels;

    st->codecpar->block_align           = st->codecpar->bits_per_coded_sample *

                                          st->codecpar->channels / 8;



    avpriv_set_pts_info(st, 64, 1, st->codecpar->sample_rate);



    return 0;

}

static int decode_frame_png(AVCodecContext *avctx,

                        void *data, int *got_frame,

                        AVPacket *avpkt)

{

    PNGDecContext *const s = avctx->priv_data;

    const uint8_t *buf     = avpkt->data;

    int buf_size           = avpkt->size;

    AVFrame *p;

    int64_t sig;

    int ret;



    ff_thread_release_buffer(avctx, &s->last_picture);

    FFSWAP(ThreadFrame, s->picture, s->last_picture);

    p = s->picture.f;



    bytestream2_init(&s->gb, buf, buf_size);



    /* check signature */

    sig = bytestream2_get_be64(&s->gb);

    if (sig != PNGSIG &&

        sig != MNGSIG) {

        av_log(avctx, AV_LOG_ERROR, "Invalid PNG signature 0x%08"PRIX64".\n", sig);

        return AVERROR_INVALIDDATA;

    }



    s->y = s->has_trns = 0;

    s->hdr_state = 0;

    s->pic_state = 0;



    /* init the zlib */

    s->zstream.zalloc = ff_png_zalloc;

    s->zstream.zfree  = ff_png_zfree;

    s->zstream.opaque = NULL;

    ret = inflateInit(&s->zstream);

    if (ret != Z_OK) {

        av_log(avctx, AV_LOG_ERROR, "inflateInit returned error %d\n", ret);

        return AVERROR_EXTERNAL;

    }



    if ((ret = decode_frame_common(avctx, s, p, avpkt)) < 0)

        goto the_end;



    if (avctx->skip_frame == AVDISCARD_ALL) {

        *got_frame = 0;

        ret = bytestream2_tell(&s->gb);

        goto the_end;

    }



    if ((ret = av_frame_ref(data, s->picture.f)) < 0)

        return ret;



    *got_frame = 1;



    ret = bytestream2_tell(&s->gb);

the_end:

    inflateEnd(&s->zstream);

    s->crow_buf = NULL;

    return ret;

}

static int ass_decode_frame(AVCodecContext *avctx, void *data, int *got_sub_ptr,

                            AVPacket *avpkt)

{

    const char *ptr = avpkt->data;

    int len, size = avpkt->size;



    ff_ass_init(data);



    while (size > 0) {

        len = ff_ass_add_rect(data, ptr, 0, 0/* FIXME: duration */, 1);

        if (len < 0)

            return len;

        ptr  += len;

        size -= len;

    }



    *got_sub_ptr = avpkt->size > 0;

    return avpkt->size;

}

int attribute_align_arg avcodec_decode_audio4(AVCodecContext *avctx,

                                              AVFrame *frame,

                                              int *got_frame_ptr,

                                              const AVPacket *avpkt)

{

    AVCodecInternal *avci = avctx->internal;

    int ret = 0;



    *got_frame_ptr = 0;



    if (!avpkt->data && avpkt->size) {

        av_log(avctx, AV_LOG_ERROR, "invalid packet: NULL data, size != 0\n");

        return AVERROR(EINVAL);

    }

    if (!avctx->codec)

        return AVERROR(EINVAL);

    if (avctx->codec->type != AVMEDIA_TYPE_AUDIO) {

        av_log(avctx, AV_LOG_ERROR, "Invalid media type for audio\n");

        return AVERROR(EINVAL);

    }



    av_frame_unref(frame);



    if ((avctx->codec->capabilities & CODEC_CAP_DELAY) || avpkt->size || (avctx->active_thread_type & FF_THREAD_FRAME)) {

        uint8_t *side;

        int side_size;

        uint32_t discard_padding = 0;

        // copy to ensure we do not change avpkt

        AVPacket tmp = *avpkt;

        int did_split = av_packet_split_side_data(&tmp);

        ret = apply_param_change(avctx, &tmp);

        if (ret < 0) {

            av_log(avctx, AV_LOG_ERROR, "Error applying parameter changes.\n");

            if (avctx->err_recognition & AV_EF_EXPLODE)

                goto fail;

        }



        avctx->internal->pkt = &tmp;

        if (HAVE_THREADS && avctx->active_thread_type & FF_THREAD_FRAME)

            ret = ff_thread_decode_frame(avctx, frame, got_frame_ptr, &tmp);

        else {

            ret = avctx->codec->decode(avctx, frame, got_frame_ptr, &tmp);

            frame->pkt_dts = avpkt->dts;

        }

        if (ret >= 0 && *got_frame_ptr) {

            add_metadata_from_side_data(avctx, frame);

            avctx->frame_number++;

            av_frame_set_best_effort_timestamp(frame,

                                               guess_correct_pts(avctx,

                                                                 frame->pkt_pts,

                                                                 frame->pkt_dts));

            if (frame->format == AV_SAMPLE_FMT_NONE)

                frame->format = avctx->sample_fmt;

            if (!frame->channel_layout)

                frame->channel_layout = avctx->channel_layout;

            if (!av_frame_get_channels(frame))

                av_frame_set_channels(frame, avctx->channels);

            if (!frame->sample_rate)

                frame->sample_rate = avctx->sample_rate;

        }



        side= av_packet_get_side_data(avctx->internal->pkt, AV_PKT_DATA_SKIP_SAMPLES, &side_size);

        if(side && side_size>=10) {

            avctx->internal->skip_samples = AV_RL32(side);

            av_log(avctx, AV_LOG_DEBUG, "skip %d samples due to side data\n",

                   avctx->internal->skip_samples);

            discard_padding = AV_RL32(side + 4);

        }

        if (avctx->internal->skip_samples && *got_frame_ptr) {

            if(frame->nb_samples <= avctx->internal->skip_samples){

                *got_frame_ptr = 0;

                avctx->internal->skip_samples -= frame->nb_samples;

                av_log(avctx, AV_LOG_DEBUG, "skip whole frame, skip left: %d\n",

                       avctx->internal->skip_samples);

            } else {

                av_samples_copy(frame->extended_data, frame->extended_data, 0, avctx->internal->skip_samples,

                                frame->nb_samples - avctx->internal->skip_samples, avctx->channels, frame->format);

                if(avctx->pkt_timebase.num && avctx->sample_rate) {

                    int64_t diff_ts = av_rescale_q(avctx->internal->skip_samples,

                                                   (AVRational){1, avctx->sample_rate},

                                                   avctx->pkt_timebase);

                    if(frame->pkt_pts!=AV_NOPTS_VALUE)

                        frame->pkt_pts += diff_ts;

                    if(frame->pkt_dts!=AV_NOPTS_VALUE)

                        frame->pkt_dts += diff_ts;

                    if (av_frame_get_pkt_duration(frame) >= diff_ts)

                        av_frame_set_pkt_duration(frame, av_frame_get_pkt_duration(frame) - diff_ts);

                } else {

                    av_log(avctx, AV_LOG_WARNING, "Could not update timestamps for skipped samples.\n");

                }

                av_log(avctx, AV_LOG_DEBUG, "skip %d/%d samples\n",

                       avctx->internal->skip_samples, frame->nb_samples);

                frame->nb_samples -= avctx->internal->skip_samples;

                avctx->internal->skip_samples = 0;

            }

        }



        if (discard_padding > 0 && discard_padding <= frame->nb_samples && *got_frame_ptr) {

            if (discard_padding == frame->nb_samples) {

                *got_frame_ptr = 0;

            } else {

                if(avctx->pkt_timebase.num && avctx->sample_rate) {

                    int64_t diff_ts = av_rescale_q(frame->nb_samples - discard_padding,

                                                   (AVRational){1, avctx->sample_rate},

                                                   avctx->pkt_timebase);

                    if (av_frame_get_pkt_duration(frame) >= diff_ts)

                        av_frame_set_pkt_duration(frame, av_frame_get_pkt_duration(frame) - diff_ts);

                } else {

                    av_log(avctx, AV_LOG_WARNING, "Could not update timestamps for discarded samples.\n");

                }

                av_log(avctx, AV_LOG_DEBUG, "discard %d/%d samples\n",

                       discard_padding, frame->nb_samples);

                frame->nb_samples -= discard_padding;

            }

        }

fail:

        avctx->internal->pkt = NULL;

        if (did_split) {

            av_packet_free_side_data(&tmp);

            if(ret == tmp.size)

                ret = avpkt->size;

        }



        if (ret >= 0 && *got_frame_ptr) {

            if (!avctx->refcounted_frames) {

                int err = unrefcount_frame(avci, frame);

                if (err < 0)

                    return err;

            }

        } else

            av_frame_unref(frame);

    }



    return ret;

}

static int parse_dsd_diin(AVFormatContext *s, AVStream *st, uint64_t eof)

{

    AVIOContext *pb = s->pb;



    while (avio_tell(pb) + 12 <= eof) {

        uint32_t tag      = avio_rl32(pb);

        uint64_t size     = avio_rb64(pb);

        uint64_t orig_pos = avio_tell(pb);

        const char * metadata_tag = NULL;



        switch(tag) {

        case MKTAG('D','I','A','R'): metadata_tag = "artist"; break;

        case MKTAG('D','I','T','I'): metadata_tag = "title";  break;

        }



        if (metadata_tag && size > 4) {

            unsigned int tag_size = avio_rb32(pb);

            int ret = get_metadata(s, metadata_tag, FFMIN(tag_size, size - 4));

            if (ret < 0) {

                av_log(s, AV_LOG_ERROR, "cannot allocate metadata tag %s!\n", metadata_tag);

                return ret;

            }

        }



        avio_skip(pb, size - (avio_tell(pb) - orig_pos) + (size & 1));

    }



    return 0;

}

void checkasm_check_vf_interlace(void)

{

