static int build_table(VLC *vlc, int table_nb_bits, int nb_codes,

                       VLCcode *codes, int flags)

{

    int table_size, table_index, index, code_prefix, symbol, subtable_bits;

    int i, j, k, n, nb, inc;

    uint32_t code;

    VLC_TYPE (*table)[2];



    table_size = 1 << table_nb_bits;

    if (table_nb_bits > 30)

       return -1;

    table_index = alloc_table(vlc, table_size, flags & INIT_VLC_USE_NEW_STATIC);

    av_dlog(NULL, "new table index=%d size=%d\n", table_index, table_size);

    if (table_index < 0)

        return table_index;

    table = &vlc->table[table_index];



    for (i = 0; i < table_size; i++) {

        table[i][1] = 0; //bits

        table[i][0] = -1; //codes

    }



    /* first pass: map codes and compute auxiliary table sizes */

    for (i = 0; i < nb_codes; i++) {

        n      = codes[i].bits;

        code   = codes[i].code;

        symbol = codes[i].symbol;

        av_dlog(NULL, "i=%d n=%d code=0x%x\n", i, n, code);

        if (n <= table_nb_bits) {

            /* no need to add another table */

            j = code >> (32 - table_nb_bits);

            nb = 1 << (table_nb_bits - n);

            inc = 1;

            if (flags & INIT_VLC_LE) {

                j = bitswap_32(code);

                inc = 1 << n;

            }

            for (k = 0; k < nb; k++) {

                av_dlog(NULL, "%4x: code=%d n=%d\n", j, i, n);

                if (table[j][1] /*bits*/ != 0) {

                    av_log(NULL, AV_LOG_ERROR, "incorrect codes\n");

                    return AVERROR_INVALIDDATA;

                }

                table[j][1] = n; //bits

                table[j][0] = symbol;

                j += inc;

            }

        } else {

            /* fill auxiliary table recursively */

            n -= table_nb_bits;

            code_prefix = code >> (32 - table_nb_bits);

            subtable_bits = n;

            codes[i].bits = n;

            codes[i].code = code << table_nb_bits;

            for (k = i+1; k < nb_codes; k++) {

                n = codes[k].bits - table_nb_bits;

                if (n <= 0)

                    break;

                code = codes[k].code;

                if (code >> (32 - table_nb_bits) != code_prefix)

                    break;

                codes[k].bits = n;

                codes[k].code = code << table_nb_bits;

                subtable_bits = FFMAX(subtable_bits, n);

            }

            subtable_bits = FFMIN(subtable_bits, table_nb_bits);

            j = (flags & INIT_VLC_LE) ? bitswap_32(code_prefix) >> (32 - table_nb_bits) : code_prefix;

            table[j][1] = -subtable_bits;

            av_dlog(NULL, "%4x: n=%d (subtable)\n",

                    j, codes[i].bits + table_nb_bits);

            index = build_table(vlc, subtable_bits, k-i, codes+i, flags);

            if (index < 0)

                return index;

            /* note: realloc has been done, so reload tables */

            table = &vlc->table[table_index];

            table[j][0] = index; //code


            i = k-1;

        }

    }

    return table_index;

}

static int mp3_write_audio_packet(AVFormatContext *s, AVPacket *pkt)

{

    MP3Context  *mp3 = s->priv_data;



    if (pkt->data && pkt->size >= 4) {

        MPADecodeHeader c;

        int av_unused base;



        avpriv_mpegaudio_decode_header(&c, AV_RB32(pkt->data));



        if (!mp3->initial_bitrate)

            mp3->initial_bitrate = c.bit_rate;

        if ((c.bit_rate == 0) || (mp3->initial_bitrate != c.bit_rate))

            mp3->has_variable_bitrate = 1;



#ifdef FILTER_VBR_HEADERS

        /* filter out XING and INFO headers. */

        base = 4 + xing_offtbl[c.lsf == 1][c.nb_channels == 1];



        if (base + 4 <= pkt->size) {

            uint32_t v = AV_RB32(pkt->data + base);



            if (MKBETAG('X','i','n','g') == v || MKBETAG('I','n','f','o') == v)

                return 0;

        }



        /* filter out VBRI headers. */

        base = 4 + 32;



        if (base + 4 <= pkt->size && MKBETAG('V','B','R','I') == AV_RB32(pkt->data + base))

            return 0;

#endif



        if (mp3->xing_offset)

            mp3_xing_add_frame(mp3, pkt);

    }



    return ff_raw_write_packet(s, pkt);

}

static int process_output_surface(AVCodecContext *avctx, AVPacket *pkt, NvencSurface *tmpoutsurf)

{

    NvencContext *ctx = avctx->priv_data;

    NvencDynLoadFunctions *dl_fn = &ctx->nvenc_dload_funcs;

    NV_ENCODE_API_FUNCTION_LIST *p_nvenc = &dl_fn->nvenc_funcs;



    uint32_t slice_mode_data;

    uint32_t *slice_offsets;

    NV_ENC_LOCK_BITSTREAM lock_params = { 0 };

    NVENCSTATUS nv_status;

    int res = 0;



    enum AVPictureType pict_type;



    switch (avctx->codec->id) {

    case AV_CODEC_ID_H264:

      slice_mode_data = ctx->encode_config.encodeCodecConfig.h264Config.sliceModeData;

      break;

    case AV_CODEC_ID_H265:

      slice_mode_data = ctx->encode_config.encodeCodecConfig.hevcConfig.sliceModeData;

      break;

    default:

      av_log(avctx, AV_LOG_ERROR, "Unknown codec name\n");

      res = AVERROR(EINVAL);

      goto error;

    }

    slice_offsets = av_mallocz(slice_mode_data * sizeof(*slice_offsets));



    if (!slice_offsets)

        goto error;



    lock_params.version = NV_ENC_LOCK_BITSTREAM_VER;



    lock_params.doNotWait = 0;

    lock_params.outputBitstream = tmpoutsurf->output_surface;

    lock_params.sliceOffsets = slice_offsets;



    nv_status = p_nvenc->nvEncLockBitstream(ctx->nvencoder, &lock_params);

    if (nv_status != NV_ENC_SUCCESS) {

        res = nvenc_print_error(avctx, nv_status, "Failed locking bitstream buffer");

        goto error;

    }



    if (res = ff_alloc_packet2(avctx, pkt, lock_params.bitstreamSizeInBytes,0)) {

        p_nvenc->nvEncUnlockBitstream(ctx->nvencoder, tmpoutsurf->output_surface);

        goto error;

    }



    memcpy(pkt->data, lock_params.bitstreamBufferPtr, lock_params.bitstreamSizeInBytes);



    nv_status = p_nvenc->nvEncUnlockBitstream(ctx->nvencoder, tmpoutsurf->output_surface);

    if (nv_status != NV_ENC_SUCCESS)

        nvenc_print_error(avctx, nv_status, "Failed unlocking bitstream buffer, expect the gates of mordor to open");





    if (avctx->pix_fmt == AV_PIX_FMT_CUDA) {

        p_nvenc->nvEncUnmapInputResource(ctx->nvencoder, tmpoutsurf->in_map.mappedResource);

        av_frame_unref(tmpoutsurf->in_ref);

        ctx->registered_frames[tmpoutsurf->reg_idx].mapped = 0;



        tmpoutsurf->input_surface = NULL;

    }



    switch (lock_params.pictureType) {

    case NV_ENC_PIC_TYPE_IDR:

        pkt->flags |= AV_PKT_FLAG_KEY;

    case NV_ENC_PIC_TYPE_I:

        pict_type = AV_PICTURE_TYPE_I;

        break;

    case NV_ENC_PIC_TYPE_P:

        pict_type = AV_PICTURE_TYPE_P;

        break;

    case NV_ENC_PIC_TYPE_B:

        pict_type = AV_PICTURE_TYPE_B;

        break;

    case NV_ENC_PIC_TYPE_BI:

        pict_type = AV_PICTURE_TYPE_BI;

        break;

    default:

        av_log(avctx, AV_LOG_ERROR, "Unknown picture type encountered, expect the output to be broken.\n");

        av_log(avctx, AV_LOG_ERROR, "Please report this error and include as much information on how to reproduce it as possible.\n");

        res = AVERROR_EXTERNAL;

        goto error;

    }



#if FF_API_CODED_FRAME

FF_DISABLE_DEPRECATION_WARNINGS

    avctx->coded_frame->pict_type = pict_type;

FF_ENABLE_DEPRECATION_WARNINGS

#endif



    ff_side_data_set_encoder_stats(pkt,

        (lock_params.frameAvgQP - 1) * FF_QP2LAMBDA, NULL, 0, pict_type);



    res = nvenc_set_timestamp(avctx, &lock_params, pkt);

    if (res < 0)

        goto error2;



    av_free(slice_offsets);



    return 0;



error:

    timestamp_queue_dequeue(ctx->timestamp_list);



error2:

    av_free(slice_offsets);



    return res;

}

yuv2422_1_c_template(SwsContext *c, const int16_t *buf0,
                     const int16_t *ubuf[2], const int16_t *vbuf[2],
                     const int16_t *abuf0, uint8_t *dest, int dstW,
                     int uvalpha, int y, enum PixelFormat target)
{
    const int16_t *ubuf0 = ubuf[0], *vbuf0 = vbuf[0];
    int i;
    if (uvalpha < 2048) {
        for (i = 0; i < (dstW >> 1); i++) {
            int Y1 = buf0[i * 2]     >> 7;
            int Y2 = buf0[i * 2 + 1] >> 7;
            int U  = ubuf0[i]        >> 7;
            int V  = vbuf0[i]        >> 7;
            output_pixels(i * 4, Y1, U, Y2, V);
        }
    } else {
        const int16_t *ubuf1 = ubuf[1], *vbuf1 = vbuf[1];
        for (i = 0; i < (dstW >> 1); i++) {
            int Y1 =  buf0[i * 2]          >> 7;
            int Y2 =  buf0[i * 2 + 1]      >> 7;
            int U  = (ubuf0[i] + ubuf1[i]) >> 8;
            int V  = (vbuf0[i] + vbuf1[i]) >> 8;
            output_pixels(i * 4, Y1, U, Y2, V);
        }
    }
}

static int wv_get_value(WavpackFrameContext *ctx, GetBitContext *gb, int channel, int *last)

{

    int t, t2;

    int sign, base, add, ret;

    WvChannel *c = &ctx->ch[channel];



    *last = 0;



    if((ctx->ch[0].median[0] < 2U) && (ctx->ch[1].median[0] < 2U) && !ctx->zero && !ctx->one){

        if(ctx->zeroes){

            ctx->zeroes--;

            if(ctx->zeroes){

                c->slow_level -= LEVEL_DECAY(c->slow_level);

                return 0;

            }

        }else{

            t = get_unary_0_33(gb);

            if(t >= 2) t = get_bits(gb, t - 1) | (1 << (t-1));

            ctx->zeroes = t;

            if(ctx->zeroes){

                memset(ctx->ch[0].median, 0, sizeof(ctx->ch[0].median));

                memset(ctx->ch[1].median, 0, sizeof(ctx->ch[1].median));

                c->slow_level -= LEVEL_DECAY(c->slow_level);

                return 0;

            }

        }

    }



    if(get_bits_count(gb) >= ctx->data_size){

        *last = 1;

        return 0;

    }



    if(ctx->zero){

        t = 0;

        ctx->zero = 0;

    }else{

        t = get_unary_0_33(gb);

        if(get_bits_count(gb) >= ctx->data_size){

            *last = 1;

            return 0;

        }

        if(t == 16) {

            t2 = get_unary_0_33(gb);

            if(t2 < 2) t += t2;

            else t += get_bits(gb, t2 - 1) | (1 << (t2 - 1));

        }



        if(ctx->one){

            ctx->one = t&1;

            t = (t>>1) + 1;

        }else{

            ctx->one = t&1;

            t >>= 1;

        }

        ctx->zero = !ctx->one;

    }



    if(ctx->hybrid && !channel)

        update_error_limit(ctx);



    if(!t){

        base = 0;

        add = GET_MED(0) - 1;

        DEC_MED(0);

    }else if(t == 1){

        base = GET_MED(0);

        add = GET_MED(1) - 1;

        INC_MED(0);

        DEC_MED(1);

    }else if(t == 2){

        base = GET_MED(0) + GET_MED(1);

        add = GET_MED(2) - 1;

        INC_MED(0);

        INC_MED(1);

        DEC_MED(2);

    }else{

        base = GET_MED(0) + GET_MED(1) + GET_MED(2) * (t - 2);

        add = GET_MED(2) - 1;

        INC_MED(0);

        INC_MED(1);

        INC_MED(2);

    }

    if(!c->error_limit){

        ret = base + get_tail(gb, add);

    }else{

        int mid = (base*2 + add + 1) >> 1;

        while(add > c->error_limit){

            if(get_bits1(gb)){

                add -= (mid - base);

                base = mid;

            }else

                add = mid - base - 1;

            mid = (base*2 + add + 1) >> 1;

        }

        ret = mid;

    }

    sign = get_bits1(gb);

    if(ctx->hybrid_bitrate)

        c->slow_level += wp_log2(ret) - LEVEL_DECAY(c->slow_level);

    return sign ? ~ret : ret;

}

void *av_fast_realloc(void *ptr, unsigned int *size, size_t min_size)

{

    if (min_size < *size)

        return ptr;



    min_size = FFMAX(min_size + min_size / 16 + 32, min_size);



    ptr = av_realloc(ptr, min_size);

    /* we could set this to the unmodified min_size but this is safer

     * if the user lost the ptr and uses NULL now

     */

    if (!ptr)

        min_size = 0;



    *size = min_size;



    return ptr;

}

static inline int decode_residual_inter(AVSContext *h)

{

    int block;



    /* get coded block pattern */

    int cbp = get_ue_golomb(&h->gb);

    if (cbp > 63) {

        av_log(h->avctx, AV_LOG_ERROR, "illegal inter cbp\n");

        return AVERROR_INVALIDDATA;

    }

    h->cbp = cbp_tab[cbp][1];



    /* get quantizer */

    if (h->cbp && !h->qp_fixed)

        h->qp = (h->qp + get_se_golomb(&h->gb)) & 63;

    for (block = 0; block < 4; block++)

        if (h->cbp & (1 << block))

            decode_residual_block(h, &h->gb, inter_dec, 0, h->qp,

                                  h->cy + h->luma_scan[block], h->l_stride);

    decode_residual_chroma(h);



    return 0;

}

static int decode_pulses(Pulse *pulse, GetBitContext *gb,

                         const uint16_t *swb_offset, int num_swb)

{

    int i, pulse_swb;

    pulse->num_pulse = get_bits(gb, 2) + 1;

    pulse_swb        = get_bits(gb, 6);

    if (pulse_swb >= num_swb)

        return -1;

    pulse->pos[0]    = swb_offset[pulse_swb];

    pulse->pos[0]   += get_bits(gb, 5);

    if (pulse->pos[0] > 1023)

        return -1;

    pulse->amp[0]    = get_bits(gb, 4);

    for (i = 1; i < pulse->num_pulse; i++) {

        pulse->pos[i] = get_bits(gb, 5) + pulse->pos[i - 1];

        if (pulse->pos[i] > 1023)

            return -1;

        pulse->amp[i] = get_bits(gb, 4);

    }

    return 0;

}

static int aiff_probe(AVProbeData *p)

{

    /* check file header */

    if (p->buf_size < 16)

        return 0;

    if (p->buf[0] == 'F' && p->buf[1] == 'O' &&

        p->buf[2] == 'R' && p->buf[3] == 'M' &&

        p->buf[8] == 'A' && p->buf[9] == 'I' &&

        p->buf[10] == 'F' && (p->buf[11] == 'F' || p->buf[11] == 'C'))

        return AVPROBE_SCORE_MAX;

    else

        return 0;

}

static int encode_residual(FlacEncodeContext *ctx, int ch)

{

    int i, n;

    int min_order, max_order, opt_order, precision, omethod;

    int min_porder, max_porder;

    FlacFrame *frame;

    FlacSubframe *sub;

    int32_t coefs[MAX_LPC_ORDER][MAX_LPC_ORDER];

    int shift[MAX_LPC_ORDER];

    int32_t *res, *smp;



    frame = &ctx->frame;

    sub = &frame->subframes[ch];

    res = sub->residual;

    smp = sub->samples;

    n = frame->blocksize;



    /* CONSTANT */

    for(i=1; i<n; i++) {

        if(smp[i] != smp[0]) break;

    }

    if(i == n) {

        sub->type = sub->type_code = FLAC_SUBFRAME_CONSTANT;

        res[0] = smp[0];

        return sub->obits;

    }



    /* VERBATIM */

    if(n < 5) {

        sub->type = sub->type_code = FLAC_SUBFRAME_VERBATIM;

        encode_residual_verbatim(res, smp, n);

        return sub->obits * n;

    }



    min_order = ctx->options.min_prediction_order;

    max_order = ctx->options.max_prediction_order;

    min_porder = ctx->options.min_partition_order;

    max_porder = ctx->options.max_partition_order;

    precision = ctx->options.lpc_coeff_precision;

    omethod = ctx->options.prediction_order_method;



    /* FIXED */

    if(!ctx->options.use_lpc || max_order == 0 || (n <= max_order)) {

        uint32_t bits[MAX_FIXED_ORDER+1];

        if(max_order > MAX_FIXED_ORDER) max_order = MAX_FIXED_ORDER;

        opt_order = 0;

        bits[0] = UINT32_MAX;

        for(i=min_order; i<=max_order; i++) {

            encode_residual_fixed(res, smp, n, i);

            bits[i] = calc_rice_params_fixed(&sub->rc, min_porder, max_porder, res,

                                             n, i, sub->obits);

            if(bits[i] < bits[opt_order]) {

                opt_order = i;

            }

        }

        sub->order = opt_order;

        sub->type = FLAC_SUBFRAME_FIXED;

        sub->type_code = sub->type | sub->order;

        if(sub->order != max_order) {

            encode_residual_fixed(res, smp, n, sub->order);

            return calc_rice_params_fixed(&sub->rc, min_porder, max_porder, res, n,

                                          sub->order, sub->obits);

        }

        return bits[sub->order];

    }



    /* LPC */

    opt_order = ff_lpc_calc_coefs(&ctx->dsp, smp, n, max_order, precision, coefs,

                               shift, ctx->options.use_lpc, omethod, MAX_LPC_SHIFT, 0);



    if(omethod == ORDER_METHOD_2LEVEL ||

       omethod == ORDER_METHOD_4LEVEL ||

       omethod == ORDER_METHOD_8LEVEL) {

        int levels = 1 << omethod;

        uint32_t bits[levels];

        int order;

        int opt_index = levels-1;

        opt_order = max_order-1;

        bits[opt_index] = UINT32_MAX;

        for(i=levels-1; i>=0; i--) {

            order = min_order + (((max_order-min_order+1) * (i+1)) / levels)-1;

            if(order < 0) order = 0;

            encode_residual_lpc(res, smp, n, order+1, coefs[order], shift[order]);

            bits[i] = calc_rice_params_lpc(&sub->rc, min_porder, max_porder,

                                           res, n, order+1, sub->obits, precision);

            if(bits[i] < bits[opt_index]) {

                opt_index = i;

                opt_order = order;

            }

        }

        opt_order++;

    } else if(omethod == ORDER_METHOD_SEARCH) {

        // brute-force optimal order search

        uint32_t bits[MAX_LPC_ORDER];

        opt_order = 0;

        bits[0] = UINT32_MAX;

        for(i=min_order-1; i<max_order; i++) {

            encode_residual_lpc(res, smp, n, i+1, coefs[i], shift[i]);

            bits[i] = calc_rice_params_lpc(&sub->rc, min_porder, max_porder,

                                           res, n, i+1, sub->obits, precision);

            if(bits[i] < bits[opt_order]) {

                opt_order = i;

            }

        }

        opt_order++;

    } else if(omethod == ORDER_METHOD_LOG) {

        uint32_t bits[MAX_LPC_ORDER];

        int step;



        opt_order= min_order - 1 + (max_order-min_order)/3;

        memset(bits, -1, sizeof(bits));



        for(step=16 ;step; step>>=1){

            int last= opt_order;

            for(i=last-step; i<=last+step; i+= step){

                if(i<min_order-1 || i>=max_order || bits[i] < UINT32_MAX)

                    continue;

                encode_residual_lpc(res, smp, n, i+1, coefs[i], shift[i]);

                bits[i] = calc_rice_params_lpc(&sub->rc, min_porder, max_porder,

                                            res, n, i+1, sub->obits, precision);

                if(bits[i] < bits[opt_order])

                    opt_order= i;

            }

        }

        opt_order++;

    }



    sub->order = opt_order;

    sub->type = FLAC_SUBFRAME_LPC;

    sub->type_code = sub->type | (sub->order-1);

    sub->shift = shift[sub->order-1];

    for(i=0; i<sub->order; i++) {

        sub->coefs[i] = coefs[sub->order-1][i];

    }

    encode_residual_lpc(res, smp, n, sub->order, sub->coefs, sub->shift);

    return calc_rice_params_lpc(&sub->rc, min_porder, max_porder, res, n, sub->order,

                                sub->obits, precision);

}

static int decode_stream_header(NUTContext *nut){

    AVFormatContext *s= nut->avf;

    ByteIOContext *bc = &s->pb;

    StreamContext *stc;

    int class, nom, denom, stream_id;

    uint64_t tmp, end;

    AVStream *st;



    end= get_packetheader(nut, bc, 1);

    end += url_ftell(bc) - 4;



    GET_V(stream_id, tmp < s->nb_streams && !nut->stream[tmp].time_base.num);

    stc= &nut->stream[stream_id];



    st = s->streams[stream_id];

    if (!st)

        return AVERROR_NOMEM;



    class = get_v(bc);

    tmp = get_fourcc(bc);

    st->codec->codec_tag= tmp;

    switch(class)

    {

        case 0:

            st->codec->codec_type = CODEC_TYPE_VIDEO;

            st->codec->codec_id = codec_get_bmp_id(tmp);

            if (st->codec->codec_id == CODEC_ID_NONE)

                av_log(s, AV_LOG_ERROR, "Unknown codec?!\n");

            break;

        case 1:

            st->codec->codec_type = CODEC_TYPE_AUDIO;

            st->codec->codec_id = codec_get_wav_id(tmp);

            if (st->codec->codec_id == CODEC_ID_NONE)

                av_log(s, AV_LOG_ERROR, "Unknown codec?!\n");

            break;

        case 2:

//            st->codec->codec_type = CODEC_TYPE_TEXT;

//            break;

        case 3:

            st->codec->codec_type = CODEC_TYPE_DATA;

            break;

        default:

            av_log(s, AV_LOG_ERROR, "Unknown stream class (%d)\n", class);

            return -1;

    }

    GET_V(stc->time_base_id    , tmp < nut->time_base_count);

    GET_V(stc->msb_pts_shift   , tmp < 16);

    stc->max_pts_distance= get_v(bc);

    GET_V(stc->decode_delay    , tmp < 1000); //sanity limit, raise this if moors law is true

    st->codec->has_b_frames= stc->decode_delay;

    get_v(bc); //stream flags



    GET_V(st->codec->extradata_size, tmp < (1<<30));

    if(st->codec->extradata_size){

        st->codec->extradata= av_mallocz(st->codec->extradata_size + FF_INPUT_BUFFER_PADDING_SIZE);

        get_buffer(bc, st->codec->extradata, st->codec->extradata_size);

    }



    if (st->codec->codec_type == CODEC_TYPE_VIDEO){

        GET_V(st->codec->width , tmp > 0)

        GET_V(st->codec->height, tmp > 0)

        st->codec->sample_aspect_ratio.num= get_v(bc);

        st->codec->sample_aspect_ratio.den= get_v(bc);

        if((!st->codec->sample_aspect_ratio.num) != (!st->codec->sample_aspect_ratio.den)){

            av_log(s, AV_LOG_ERROR, "invalid aspect ratio\n");

            return -1;

        }

        get_v(bc); /* csp type */

    }else if (st->codec->codec_type == CODEC_TYPE_AUDIO){

        GET_V(st->codec->sample_rate , tmp > 0)

        tmp= get_v(bc); // samplerate_den

        if(tmp > st->codec->sample_rate){

            av_log(s, AV_LOG_ERROR, "bleh, libnut muxed this ;)\n");

            st->codec->sample_rate= tmp;

        }

        GET_V(st->codec->channels, tmp > 0)

    }

    if(skip_reserved(bc, end) || check_checksum(bc)){

        av_log(s, AV_LOG_ERROR, "Stream header %d checksum mismatch\n", stream_id);

        return -1;

    }

    stc->time_base= nut->time_base[stc->time_base_id];

    av_set_pts_info(s->streams[stream_id], 63, stc->time_base.num, stc->time_base.den);

    return 0;

}

void avformat_close_input(AVFormatContext **ps)

{

    AVFormatContext *s = *ps;

    AVIOContext *pb = (s->iformat->flags & AVFMT_NOFILE) || (s->flags & AVFMT_FLAG_CUSTOM_IO) ?

                       NULL : s->pb;

    flush_packet_queue(s);

    if (s->iformat->read_close)

        s->iformat->read_close(s);

    avformat_free_context(s);

    *ps = NULL;



    avio_close(pb);

}

int avresample_set_matrix(AVAudioResampleContext *avr, const double *matrix,

                          int stride)

{

    int in_channels, out_channels, i, o;



    in_channels  = av_get_channel_layout_nb_channels(avr->in_channel_layout);

    out_channels = av_get_channel_layout_nb_channels(avr->out_channel_layout);



    if ( in_channels < 0 ||  in_channels > AVRESAMPLE_MAX_CHANNELS ||

        out_channels < 0 || out_channels > AVRESAMPLE_MAX_CHANNELS) {

        av_log(avr, AV_LOG_ERROR, "Invalid channel layouts\n");

        return AVERROR(EINVAL);

    }



    if (avr->am->matrix)

        av_freep(avr->am->matrix);



#define CONVERT_MATRIX(type, expr)                                          \

    avr->am->matrix_## type[0] = av_mallocz(out_channels * in_channels *    \

                                            sizeof(*avr->am->matrix_## type[0])); \

    if (!avr->am->matrix_## type[0])                                        \

        return AVERROR(ENOMEM);                                             \

    for (o = 0; o < out_channels; o++) {                                    \

        if (o > 0)                                                          \

            avr->am->matrix_## type[o] = avr->am->matrix_## type[o - 1] +   \

                                         in_channels;                       \

        for (i = 0; i < in_channels; i++) {                                 \

            double v = matrix[o * stride + i];                              \

            avr->am->matrix_## type[o][i] = expr;                           \

        }                                                                   \

    }                                                                       \

    avr->am->matrix = (void **)avr->am->matrix_## type;



    switch (avr->mix_coeff_type) {

    case AV_MIX_COEFF_TYPE_Q8:

        CONVERT_MATRIX(q8, av_clip_int16(lrint(256.0 * v)))

        break;

    case AV_MIX_COEFF_TYPE_Q15:

        CONVERT_MATRIX(q15, av_clipl_int32(llrint(32768.0 * v)))

        break;

    case AV_MIX_COEFF_TYPE_FLT:

        CONVERT_MATRIX(flt, v)

        break;

    default:

        av_log(avr, AV_LOG_ERROR, "Invalid mix coeff type\n");

        return AVERROR(EINVAL);

    }



    /* TODO: detect situations where we can just swap around pointers

             instead of doing matrix multiplications with 0.0 and 1.0 */



    return 0;

}

