int ff_vaapi_commit_slices(FFVAContext *vactx)

{

    VABufferID *slice_buf_ids;

    VABufferID slice_param_buf_id, slice_data_buf_id;



    if (vactx->slice_count == 0)

        return 0;



    slice_buf_ids =

        av_fast_realloc(vactx->slice_buf_ids,

                        &vactx->slice_buf_ids_alloc,

                        (vactx->n_slice_buf_ids + 2) * sizeof(slice_buf_ids[0]));

    if (!slice_buf_ids)

        return -1;

    vactx->slice_buf_ids = slice_buf_ids;



    slice_param_buf_id = 0;

    if (vaCreateBuffer(vactx->display, vactx->context_id,

                       VASliceParameterBufferType,

                       vactx->slice_param_size,

                       vactx->slice_count, vactx->slice_params,

                       &slice_param_buf_id) != VA_STATUS_SUCCESS)

        return -1;

    vactx->slice_count = 0;



    slice_data_buf_id = 0;

    if (vaCreateBuffer(vactx->display, vactx->context_id,

                       VASliceDataBufferType,

                       vactx->slice_data_size,

                       1, (void *)vactx->slice_data,

                       &slice_data_buf_id) != VA_STATUS_SUCCESS)

        return -1;

    vactx->slice_data = NULL;

    vactx->slice_data_size = 0;



    slice_buf_ids[vactx->n_slice_buf_ids++] = slice_param_buf_id;

    slice_buf_ids[vactx->n_slice_buf_ids++] = slice_data_buf_id;

    return 0;

}

static int mjpeg_decode_init(AVCodecContext *avctx)

{

    MJpegDecodeContext *s = avctx->priv_data;

    MpegEncContext s2;



    s->avctx = avctx;



    /* ugly way to get the idct & scantable */

    memset(&s2, 0, sizeof(MpegEncContext));

    s2.flags= avctx->flags;

    s2.avctx= avctx;

//    s2->out_format = FMT_MJPEG;

    s2.width = 8;

    s2.height = 8;

    if (MPV_common_init(&s2) < 0)

       return -1;

    s->scantable= s2.intra_scantable;

    s->idct_put= s2.idct_put;

    MPV_common_end(&s2);



    s->mpeg_enc_ctx_allocated = 0;

    s->buffer_size = 102400; /* smaller buffer should be enough,

				but photojpg files could ahive bigger sizes */

    s->buffer = av_malloc(s->buffer_size);

    if (!s->buffer)

	return -1;

    s->start_code = -1;

    s->first_picture = 1;

    s->org_width = avctx->width;

    s->org_height = avctx->height;



    build_vlc(&s->vlcs[0][0], bits_dc_luminance, val_dc_luminance, 12);

    build_vlc(&s->vlcs[0][1], bits_dc_chrominance, val_dc_chrominance, 12);

    build_vlc(&s->vlcs[1][0], bits_ac_luminance, val_ac_luminance, 251);

    build_vlc(&s->vlcs[1][1], bits_ac_chrominance, val_ac_chrominance, 251);



    if (avctx->flags & CODEC_FLAG_EXTERN_HUFF)

    {

	printf("mjpeg: using external huffman table\n");

	init_get_bits(&s->gb, avctx->extradata, avctx->extradata_size);

	mjpeg_decode_dht(s);

	/* should check for error - but dunno */

    }



    return 0;

}

static int cbs_read_se_golomb(CodedBitstreamContext *ctx, BitstreamContext *bc,

                              const char *name, int32_t *write_to,

                              int32_t range_min, int32_t range_max)

{

    int32_t value;

    int position;



    if (ctx->trace_enable) {

        char bits[65];

        uint32_t v;

        unsigned int k;

        int i, j;



        position = bitstream_tell(bc);



        for (i = 0; i < 32; i++) {

            k = bitstream_read_bit(bc);

            bits[i] = k ? '1' : '0';

            if (k)

                break;

        }

        if (i >= 32) {

            av_log(ctx->log_ctx, AV_LOG_ERROR, "Invalid se-golomb "

                   "code found while reading %s: "

                   "more than 31 zeroes.\n", name);

            return AVERROR_INVALIDDATA;

        }

        v = 1;

        for (j = 0; j < i; j++) {

            k = bitstream_read_bit(bc);

            bits[i + j + 1] = k ? '1' : '0';

            v = v << 1 | k;

        }

        bits[i + j + 1] = 0;

        if (v & 1)

            value = -(int32_t)(v / 2);

        else

            value = v / 2;



        ff_cbs_trace_syntax_element(ctx, position, name, bits, value);

    } else {

        value = get_se_golomb_long(bc);

    }



    if (value < range_min || value > range_max) {

        av_log(ctx->log_ctx, AV_LOG_ERROR, "%s out of range: "

               "%"PRId32", but must be in [%"PRId32",%"PRId32"].\n",

               name, value, range_min, range_max);

        return AVERROR_INVALIDDATA;

    }



    *write_to = value;

    return 0;

}

static void dct_unquantize_mpeg1_c(MpegEncContext *s, 

                                   DCTELEM *block, int n, int qscale)

{

    int i, level, nCoeffs;

    const UINT16 *quant_matrix;



    if(s->alternate_scan) nCoeffs= 64;

    else nCoeffs= s->block_last_index[n]+1;



    if (s->mb_intra) {

        if (n < 4) 

            block[0] = block[0] * s->y_dc_scale;

        else

            block[0] = block[0] * s->c_dc_scale;

        /* XXX: only mpeg1 */

        quant_matrix = s->intra_matrix;

        for(i=1;i<nCoeffs;i++) {

            int j= zigzag_direct[i];

            level = block[j];

            if (level) {

                if (level < 0) {

                    level = -level;

                    level = (int)(level * qscale * quant_matrix[j]) >> 3;

                    level = (level - 1) | 1;

                    level = -level;

                } else {

                    level = (int)(level * qscale * quant_matrix[j]) >> 3;

                    level = (level - 1) | 1;

                }

#ifdef PARANOID

                if (level < -2048 || level > 2047)

                    fprintf(stderr, "unquant error %d %d\n", i, level);

#endif

                block[j] = level;

            }

        }

    } else {

        i = 0;

        quant_matrix = s->non_intra_matrix;

        for(;i<nCoeffs;i++) {

            int j= zigzag_direct[i];

            level = block[j];

            if (level) {

                if (level < 0) {

                    level = -level;

                    level = (((level << 1) + 1) * qscale *

                             ((int) (quant_matrix[j]))) >> 4;

                    level = (level - 1) | 1;

                    level = -level;

                } else {

                    level = (((level << 1) + 1) * qscale *

                             ((int) (quant_matrix[j]))) >> 4;

                    level = (level - 1) | 1;

                }

#ifdef PARANOID

                if (level < -2048 || level > 2047)

                    fprintf(stderr, "unquant error %d %d\n", i, level);

#endif

                block[j] = level;

            }

        }

    }

}

static int parse_inputs(const char **buf, AVFilterInOut **currInputs,

                        AVFilterInOut **openLinks, AVClass *log_ctx)

{

    int pad = 0;



    while(**buf == '[') {

        char *name = parse_link_name(buf, log_ctx);

        AVFilterInOut *match;



        if(!name)

            return -1;



        /* First check if the label is not in the openLinks list */

        match = extract_inout(name, openLinks);



        if(match) {

            /* A label of a open link. Make it one of the inputs of the next

               filter */

            if(match->type != LinkTypeOut) {

                av_log(log_ctx, AV_LOG_ERROR,

                       "Label \"%s\" appears twice as input!\n", match->name);

                return -1;

            }


        } else {

            /* Not in the list, so add it as an input */

            match = av_mallocz(sizeof(AVFilterInOut));

            match->name    = name;

            match->type    = LinkTypeIn;

            match->pad_idx = pad;

        }



        insert_inout(currInputs, match);



        *buf += consume_whitespace(*buf);

        pad++;

    }



    return pad;

}

static int configure_input_video_filter(FilterGraph *fg, InputFilter *ifilter,

                                        AVFilterInOut *in)

{

    AVFilterContext *last_filter;

    const AVFilter *buffer_filt = avfilter_get_by_name("buffer");

    InputStream *ist = ifilter->ist;

    InputFile     *f = input_files[ist->file_index];

    AVRational tb = ist->framerate.num ? av_inv_q(ist->framerate) :

                                         ist->st->time_base;

    AVRational fr = ist->framerate;

    AVRational sar;

    AVBPrint args;

    char name[255];

    int ret, pad_idx = 0;

    int64_t tsoffset = 0;

    AVBufferSrcParameters *par = av_buffersrc_parameters_alloc();



    if (!par)

        return AVERROR(ENOMEM);

    memset(par, 0, sizeof(*par));

    par->format = AV_PIX_FMT_NONE;



    if (ist->dec_ctx->codec_type == AVMEDIA_TYPE_AUDIO) {

        av_log(NULL, AV_LOG_ERROR, "Cannot connect video filter to audio input\n");

        return AVERROR(EINVAL);

    }



    if (!fr.num)

        fr = av_guess_frame_rate(input_files[ist->file_index]->ctx, ist->st, NULL);



    if (ist->dec_ctx->codec_type == AVMEDIA_TYPE_SUBTITLE) {

        ret = sub2video_prepare(ist);

        if (ret < 0)

            return ret;

    }



    sar = ist->st->sample_aspect_ratio.num ?

          ist->st->sample_aspect_ratio :

          ist->dec_ctx->sample_aspect_ratio;

    if(!sar.den)

        sar = (AVRational){0,1};

    av_bprint_init(&args, 0, 1);

    av_bprintf(&args,

             "video_size=%dx%d:pix_fmt=%d:time_base=%d/%d:"

             "pixel_aspect=%d/%d:sws_param=flags=%d", ist->resample_width,

             ist->resample_height,

             ist->hwaccel_retrieve_data ? ist->hwaccel_retrieved_pix_fmt : ist->resample_pix_fmt,

             tb.num, tb.den, sar.num, sar.den,

             SWS_BILINEAR + ((ist->dec_ctx->flags&AV_CODEC_FLAG_BITEXACT) ? SWS_BITEXACT:0));

    if (fr.num && fr.den)

        av_bprintf(&args, ":frame_rate=%d/%d", fr.num, fr.den);

    snprintf(name, sizeof(name), "graph %d input from stream %d:%d", fg->index,

             ist->file_index, ist->st->index);





    if ((ret = avfilter_graph_create_filter(&ifilter->filter, buffer_filt, name,

                                            args.str, NULL, fg->graph)) < 0)

        return ret;

    par->hw_frames_ctx = ist->hw_frames_ctx;

    ret = av_buffersrc_parameters_set(ifilter->filter, par);

    if (ret < 0)

        return ret;

    av_freep(&par);

    last_filter = ifilter->filter;



    if (ist->autorotate) {

        double theta = get_rotation(ist->st);



        if (fabs(theta - 90) < 1.0) {

            ret = insert_filter(&last_filter, &pad_idx, "transpose", "clock");

        } else if (fabs(theta - 180) < 1.0) {

            ret = insert_filter(&last_filter, &pad_idx, "hflip", NULL);

            if (ret < 0)

                return ret;

            ret = insert_filter(&last_filter, &pad_idx, "vflip", NULL);

        } else if (fabs(theta - 270) < 1.0) {

            ret = insert_filter(&last_filter, &pad_idx, "transpose", "cclock");

        } else if (fabs(theta) > 1.0) {

            char rotate_buf[64];

            snprintf(rotate_buf, sizeof(rotate_buf), "%f*PI/180", theta);

            ret = insert_filter(&last_filter, &pad_idx, "rotate", rotate_buf);

        }

        if (ret < 0)

            return ret;

    }



    if (ist->framerate.num) {

        AVFilterContext *setpts;



        snprintf(name, sizeof(name), "force CFR for input from stream %d:%d",

                 ist->file_index, ist->st->index);

        if ((ret = avfilter_graph_create_filter(&setpts,

                                                avfilter_get_by_name("setpts"),

                                                name, "N", NULL,

                                                fg->graph)) < 0)

            return ret;



        if ((ret = avfilter_link(last_filter, 0, setpts, 0)) < 0)

            return ret;



        last_filter = setpts;

    }



    if (do_deinterlace) {

        AVFilterContext *yadif;



        snprintf(name, sizeof(name), "deinterlace input from stream %d:%d",

                 ist->file_index, ist->st->index);

        if ((ret = avfilter_graph_create_filter(&yadif,

                                                avfilter_get_by_name("yadif"),

                                                name, "", NULL,

                                                fg->graph)) < 0)

            return ret;



        if ((ret = avfilter_link(last_filter, 0, yadif, 0)) < 0)

            return ret;



        last_filter = yadif;

    }



    snprintf(name, sizeof(name), "trim for input stream %d:%d",

             ist->file_index, ist->st->index);

    if (copy_ts) {

        tsoffset = f->start_time == AV_NOPTS_VALUE ? 0 : f->start_time;

        if (!start_at_zero && f->ctx->start_time != AV_NOPTS_VALUE)

            tsoffset += f->ctx->start_time;

    }

    ret = insert_trim(((f->start_time == AV_NOPTS_VALUE) || !f->accurate_seek) ?

                      AV_NOPTS_VALUE : tsoffset, f->recording_time,

                      &last_filter, &pad_idx, name);

    if (ret < 0)

        return ret;



    if ((ret = avfilter_link(last_filter, 0, in->filter_ctx, in->pad_idx)) < 0)

        return ret;

    return 0;

}

static void do_video_stats(OutputStream *ost, int frame_size)

{

    AVCodecContext *enc;

    int frame_number;

    double ti1, bitrate, avg_bitrate;



    /* this is executed just the first time do_video_stats is called */

    if (!vstats_file) {

        vstats_file = fopen(vstats_filename, "w");

        if (!vstats_file) {

            perror("fopen");

            exit(1);

        }

    }



    enc = ost->st->codec;

    if (enc->codec_type == AVMEDIA_TYPE_VIDEO) {

        frame_number = ost->frame_number;

        fprintf(vstats_file, "frame= %5d q= %2.1f ", frame_number, enc->coded_frame->quality / (float)FF_QP2LAMBDA);

        if (enc->flags&CODEC_FLAG_PSNR)

            fprintf(vstats_file, "PSNR= %6.2f ", psnr(enc->coded_frame->error[0] / (enc->width * enc->height * 255.0 * 255.0)));



        fprintf(vstats_file,"f_size= %6d ", frame_size);

        /* compute pts value */

        ti1 = ost->sync_opts * av_q2d(enc->time_base);

        if (ti1 < 0.01)

            ti1 = 0.01;



        bitrate     = (frame_size * 8) / av_q2d(enc->time_base) / 1000.0;

        avg_bitrate = (double)(video_size * 8) / ti1 / 1000.0;

        fprintf(vstats_file, "s_size= %8.0fkB time= %0.3f br= %7.1fkbits/s avg_br= %7.1fkbits/s ",

               (double)video_size / 1024, ti1, bitrate, avg_bitrate);

        fprintf(vstats_file, "type= %c\n", av_get_picture_type_char(enc->coded_frame->pict_type));

    }

}

void intra_predict(VP8Context *s, uint8_t *dst[3], VP8Macroblock *mb,

                   int mb_x, int mb_y)

{

    AVCodecContext *avctx = s->avctx;

    int x, y, mode, nnz, tr;



    // for the first row, we need to run xchg_mb_border to init the top edge to 127

    // otherwise, skip it if we aren't going to deblock

    if (!(avctx->flags & CODEC_FLAG_EMU_EDGE && !mb_y) && (s->deblock_filter || !mb_y))

        xchg_mb_border(s->top_border[mb_x+1], dst[0], dst[1], dst[2],

                       s->linesize, s->uvlinesize, mb_x, mb_y, s->mb_width,

                       s->filter.simple, 1);



    if (mb->mode < MODE_I4x4) {

        if (avctx->flags & CODEC_FLAG_EMU_EDGE) { // tested

            mode = check_intra_pred8x8_mode_emuedge(mb->mode, mb_x, mb_y);

        } else {

            mode = check_intra_pred8x8_mode(mb->mode, mb_x, mb_y);

        }

        s->hpc.pred16x16[mode](dst[0], s->linesize);

    } else {

        uint8_t *ptr = dst[0];

        uint8_t *intra4x4 = s->intra4x4_pred_mode_mb;

        uint8_t tr_top[4] = { 127, 127, 127, 127 };



        // all blocks on the right edge of the macroblock use bottom edge

        // the top macroblock for their topright edge

        uint8_t *tr_right = ptr - s->linesize + 16;



        // if we're on the right edge of the frame, said edge is extended

        // from the top macroblock

        if (mb_x == s->mb_width-1) {

            tr = tr_right[-1]*0x01010101;

            tr_right = (uint8_t *)&tr;

        }



        if (mb->skip)

            AV_ZERO128(s->non_zero_count_cache);



        for (y = 0; y < 4; y++) {

            uint8_t *topright = ptr + 4 - s->linesize;

            for (x = 0; x < 4; x++) {

                int copy = 0, linesize = s->linesize;

                uint8_t *dst = ptr+4*x;

                DECLARE_ALIGNED(4, uint8_t, copy_dst)[5*8];



                if ((y == 0 || x == 3) && mb_y == 0 && avctx->flags & CODEC_FLAG_EMU_EDGE) {

                    topright = tr_top;

                } else if (x == 3)

                    topright = tr_right;



                if (avctx->flags & CODEC_FLAG_EMU_EDGE) { // mb_x+x or mb_y+y is a hack but works

                    mode = check_intra_pred4x4_mode_emuedge(intra4x4[x], mb_x + x, mb_y + y, &copy);

                    if (copy) {

                        dst = copy_dst + 12;

                        linesize = 8;

                        if (!(mb_y + y)) {

                            copy_dst[3] = 127U;

                            * (uint32_t *) (copy_dst + 4) = 127U * 0x01010101U;

                        } else {

                            * (uint32_t *) (copy_dst + 4) = * (uint32_t *) (ptr+4*x-s->linesize);

                            if (!(mb_x + x)) {

                                copy_dst[3] = 129U;

                            } else {

                                copy_dst[3] = ptr[4*x-s->linesize-1];

                            }

                        }

                        if (!(mb_x + x)) {

                            copy_dst[11] =

                            copy_dst[19] =

                            copy_dst[27] =

                            copy_dst[35] = 129U;

                        } else {

                            copy_dst[11] = ptr[4*x              -1];

                            copy_dst[19] = ptr[4*x+s->linesize  -1];

                            copy_dst[27] = ptr[4*x+s->linesize*2-1];

                            copy_dst[35] = ptr[4*x+s->linesize*3-1];

                        }

                    }

                } else {

                    mode = intra4x4[x];

                }

                s->hpc.pred4x4[mode](dst, topright, linesize);

                if (copy) {

                    * (uint32_t *) (ptr+4*x)               = * (uint32_t *) (copy_dst + 12);

                    * (uint32_t *) (ptr+4*x+s->linesize)   = * (uint32_t *) (copy_dst + 20);

                    * (uint32_t *) (ptr+4*x+s->linesize*2) = * (uint32_t *) (copy_dst + 28);

                    * (uint32_t *) (ptr+4*x+s->linesize*3) = * (uint32_t *) (copy_dst + 36);

                }



                nnz = s->non_zero_count_cache[y][x];

                if (nnz) {

                    if (nnz == 1)

                        s->vp8dsp.vp8_idct_dc_add(ptr+4*x, s->block[y][x], s->linesize);

                    else

                        s->vp8dsp.vp8_idct_add(ptr+4*x, s->block[y][x], s->linesize);

                }

                topright += 4;

            }



            ptr   += 4*s->linesize;

            intra4x4 += 4;

        }

    }



    if (avctx->flags & CODEC_FLAG_EMU_EDGE) {

        mode = check_intra_pred8x8_mode_emuedge(s->chroma_pred_mode, mb_x, mb_y);

    } else {

        mode = check_intra_pred8x8_mode(s->chroma_pred_mode, mb_x, mb_y);

    }

    s->hpc.pred8x8[mode](dst[1], s->uvlinesize);

    s->hpc.pred8x8[mode](dst[2], s->uvlinesize);



    if (!(avctx->flags & CODEC_FLAG_EMU_EDGE && !mb_y) && (s->deblock_filter || !mb_y))

        xchg_mb_border(s->top_border[mb_x+1], dst[0], dst[1], dst[2],

                       s->linesize, s->uvlinesize, mb_x, mb_y, s->mb_width,

                       s->filter.simple, 0);

}

static int parse_icy(HTTPContext *s, const char *tag, const char *p)
{
    int len = 4 + strlen(p) + strlen(tag);
    int is_first = !s->icy_metadata_headers;
    int ret;
    if (s->icy_metadata_headers)
        len += strlen(s->icy_metadata_headers);
    if ((ret = av_reallocp(&s->icy_metadata_headers, len)) < 0)
        return ret;
    av_strlcatf(s->icy_metadata_headers, len, "%s: %s\n", tag, p);
    return 0;
}

static av_cold void decode_init_vlc(void){

    static int done = 0;



    if (!done) {

        int i;

        done = 1;



        init_vlc(&chroma_dc_coeff_token_vlc, CHROMA_DC_COEFF_TOKEN_VLC_BITS, 4*5,

                 &chroma_dc_coeff_token_len [0], 1, 1,

                 &chroma_dc_coeff_token_bits[0], 1, 1, 1);



        for(i=0; i<4; i++){

            init_vlc(&coeff_token_vlc[i], COEFF_TOKEN_VLC_BITS, 4*17,

                     &coeff_token_len [i][0], 1, 1,

                     &coeff_token_bits[i][0], 1, 1, 1);

        }



        for(i=0; i<3; i++){

            init_vlc(&chroma_dc_total_zeros_vlc[i], CHROMA_DC_TOTAL_ZEROS_VLC_BITS, 4,

                     &chroma_dc_total_zeros_len [i][0], 1, 1,

                     &chroma_dc_total_zeros_bits[i][0], 1, 1, 1);

        }

        for(i=0; i<15; i++){

            init_vlc(&total_zeros_vlc[i], TOTAL_ZEROS_VLC_BITS, 16,

                     &total_zeros_len [i][0], 1, 1,

                     &total_zeros_bits[i][0], 1, 1, 1);

        }



        for(i=0; i<6; i++){

            init_vlc(&run_vlc[i], RUN_VLC_BITS, 7,

                     &run_len [i][0], 1, 1,

                     &run_bits[i][0], 1, 1, 1);

        }

        init_vlc(&run7_vlc, RUN7_VLC_BITS, 16,

                 &run_len [6][0], 1, 1,

                 &run_bits[6][0], 1, 1, 1);

    }

}

static int dct_quantize_c(MpegEncContext *s, 

                        DCTELEM *block, int n,

                        int qscale, int *overflow)

{

    int i, j, level, last_non_zero, q;

    const int *qmat;

    int bias;

    int max=0;

    unsigned int threshold1, threshold2;



    av_fdct (block);



    /* we need this permutation so that we correct the IDCT

       permutation. will be moved into DCT code */

    block_permute(block);



    if (s->mb_intra) {

        if (!s->h263_aic) {

            if (n < 4)

                q = s->y_dc_scale;

            else

                q = s->c_dc_scale;

            q = q << 3;

        } else

            /* For AIC we skip quant/dequant of INTRADC */

            q = 1 << 3;



        /* note: block[0] is assumed to be positive */

        block[0] = (block[0] + (q >> 1)) / q;

        i = 1;

        last_non_zero = 0;

        qmat = s->q_intra_matrix[qscale];

        bias= s->intra_quant_bias<<(QMAT_SHIFT - 3 - QUANT_BIAS_SHIFT);

    } else {

        i = 0;

        last_non_zero = -1;

        qmat = s->q_inter_matrix[qscale];

        bias= s->inter_quant_bias<<(QMAT_SHIFT - 3 - QUANT_BIAS_SHIFT);

    }

    threshold1= (1<<(QMAT_SHIFT - 3)) - bias - 1;

    threshold2= threshold1<<1;



    for(;i<64;i++) {

        j = zigzag_direct[i];

        level = block[j];

        level = level * qmat[j];



//        if(   bias+level >= (1<<(QMAT_SHIFT - 3))

//           || bias-level >= (1<<(QMAT_SHIFT - 3))){

        if(((unsigned)(level+threshold1))>threshold2){

            if(level>0){

                level= (bias + level)>>(QMAT_SHIFT - 3);

                block[j]= level;

            }else{

                level= (bias - level)>>(QMAT_SHIFT - 3);

                block[j]= -level;

            }

            max |=level;

            last_non_zero = i;

        }else{

            block[j]=0;

        }

    }

    *overflow= s->max_qcoeff < max; //overflow might have happend



    return last_non_zero;

}

static void radix_sort(RCCMPEntry *data, int size)

{

    int buckets[RADIX_PASSES][NBUCKETS];

    RCCMPEntry *tmp = av_malloc_array(size, sizeof(*tmp));

    radix_count(data, size, buckets);

    radix_sort_pass(tmp, data, size, buckets[0], 0);

    radix_sort_pass(data, tmp, size, buckets[1], 1);

    if (buckets[2][NBUCKETS - 1] || buckets[3][NBUCKETS - 1]) {

        radix_sort_pass(tmp, data, size, buckets[2], 2);

        radix_sort_pass(data, tmp, size, buckets[3], 3);

    }

    av_free(tmp);

}

static inline void mix_3f_1r_to_stereo(AC3DecodeContext *ctx)

{

    int i;

    float (*output)[256] = ctx->audio_block.block_output;



    for (i = 0; i < 256; i++) {

        output[1][i] += (output[2][i] + output[4][i]);

        output[2][i] += (output[3][i] + output[4][i]);

    }

    memset(output[3], 0, sizeof(output[3]));

    memset(output[4], 0, sizeof(output[4]));

}

static int check(AVIOContext *pb, int64_t pos, uint32_t *ret_header)

{

    int64_t ret = avio_seek(pb, pos, SEEK_SET);

    unsigned header;

    MPADecodeHeader sd;

    if (ret < 0)

        return ret;



    header = avio_rb32(pb);

    if (ff_mpa_check_header(header) < 0)

        return -1;

    if (avpriv_mpegaudio_decode_header(&sd, header) == 1)

        return -1;



    if (ret_header)

        *ret_header = header;

    return sd.frame_size;

}

