                b->width = (w + !(orientation&1))>>1;

                b->height= (h + !(orientation>1))>>1;



                if(orientation&1) b->buf += (w+1)>>1;

                if(orientation>1) b->buf += b->stride>>1;



                if(level)

                    b->parent= &s->plane[plane_index].band[level-1][orientation];

            }

            w= (w+1)>>1;

