static int ljpeg_decode_yuv_scan(MJpegDecodeContext *s, int predictor, int point_transform){

    int i, mb_x, mb_y;

    const int nb_components=3;



    for(mb_y = 0; mb_y < s->mb_height; mb_y++) {

        for(mb_x = 0; mb_x < s->mb_width; mb_x++) {

            if (s->restart_interval && !s->restart_count)

                s->restart_count = s->restart_interval;



            if(mb_x==0 || mb_y==0 || s->interlaced){

                for(i=0;i<nb_components;i++) {

                    uint8_t *ptr;

                    int n, h, v, x, y, c, j, linesize;

                    n = s->nb_blocks[i];

                    c = s->comp_index[i];

                    h = s->h_scount[i];

                    v = s->v_scount[i];

                    x = 0;

                    y = 0;

                    linesize= s->linesize[c];



                    for(j=0; j<n; j++) {

                        int pred;



                        ptr = s->picture.data[c] + (linesize * (v * mb_y + y)) + (h * mb_x + x); //FIXME optimize this crap

                        if(y==0 && mb_y==0){

                            if(x==0 && mb_x==0){

                                pred= 128 << point_transform;

                            }else{

                                pred= ptr[-1];

                            }

                        }else{

                            if(x==0 && mb_x==0){

                                pred= ptr[-linesize];

                            }else{

                                PREDICT(pred, ptr[-linesize-1], ptr[-linesize], ptr[-1], predictor);

                            }

                        }



                        if (s->interlaced && s->bottom_field)

                            ptr += linesize >> 1;

                        *ptr= pred + (mjpeg_decode_dc(s, s->dc_index[i]) << point_transform);



                        if (++x == h) {

                            x = 0;

                            y++;

                        }

                    }

                }

            }else{

                for(i=0;i<nb_components;i++) {

                    uint8_t *ptr;

                    int n, h, v, x, y, c, j, linesize;

                    n = s->nb_blocks[i];

                    c = s->comp_index[i];

                    h = s->h_scount[i];

                    v = s->v_scount[i];

                    x = 0;

                    y = 0;

                    linesize= s->linesize[c];



                    for(j=0; j<n; j++) {

                        int pred;



                        ptr = s->picture.data[c] + (linesize * (v * mb_y + y)) + (h * mb_x + x); //FIXME optimize this crap

                        PREDICT(pred, ptr[-linesize-1], ptr[-linesize], ptr[-1], predictor);

                        *ptr= pred + (mjpeg_decode_dc(s, s->dc_index[i]) << point_transform);

                        if (++x == h) {

                            x = 0;

                            y++;

                        }

                    }

                }

            }

            if (s->restart_interval && !--s->restart_count) {

                align_get_bits(&s->gb);

                skip_bits(&s->gb, 16); /* skip RSTn */

            }

        }

    }

    return 0;

}

static void filter_mb_mbaff_edgecv( H264Context *h, uint8_t *pix, int stride, const int16_t bS[7], int bsi, int qp ) {

    const int qp_bd_offset = 6 * (h->sps.bit_depth_luma - 8);

    int index_a = qp - qp_bd_offset + h->slice_alpha_c0_offset;

    int alpha = alpha_table[index_a];

    int beta  = beta_table[qp - qp_bd_offset + h->slice_beta_offset];

    if (alpha ==0 || beta == 0) return;



    if( bS[0] < 4 ) {

        int8_t tc[4];

        tc[0] = tc0_table[index_a][bS[0*bsi]] + 1;

        tc[1] = tc0_table[index_a][bS[1*bsi]] + 1;

        tc[2] = tc0_table[index_a][bS[2*bsi]] + 1;

        tc[3] = tc0_table[index_a][bS[3*bsi]] + 1;

        h->h264dsp.h264_h_loop_filter_chroma_mbaff(pix, stride, alpha, beta, tc);

    } else {

        h->h264dsp.h264_h_loop_filter_chroma_mbaff_intra(pix, stride, alpha, beta);

    }

}

int cmdutils_read_file(const char *filename, char **bufptr, size_t *size)

{

    int ret;

    FILE *f = fopen(filename, "rb");



    if (!f) {

        av_log(NULL, AV_LOG_ERROR, "Cannot read file '%s': %s\n", filename,

               strerror(errno));

        return AVERROR(errno);

    }

    fseek(f, 0, SEEK_END);

    *size = ftell(f);

    fseek(f, 0, SEEK_SET);

    *bufptr = av_malloc(*size + 1);

    if (!*bufptr) {

        av_log(NULL, AV_LOG_ERROR, "Could not allocate file buffer\n");

        fclose(f);

        return AVERROR(ENOMEM);

    }

    ret = fread(*bufptr, 1, *size, f);

    if (ret < *size) {

        av_free(*bufptr);

        if (ferror(f)) {

            av_log(NULL, AV_LOG_ERROR, "Error while reading file '%s': %s\n",

                   filename, strerror(errno));

            ret = AVERROR(errno);

        } else

            ret = AVERROR_EOF;

    } else {

        ret = 0;

        (*bufptr)[(*size)++] = '\0';

    }



    fclose(f);

    return ret;

}

static inline int ff_mpeg4_pred_dc(MpegEncContext * s, int n, int level, int *dir_ptr, int encoding)

{

    int a, b, c, wrap, pred, scale, ret;

    int16_t *dc_val;



    /* find prediction */

    if (n < 4) {

        scale = s->y_dc_scale;

    } else {

        scale = s->c_dc_scale;

    }

    if(IS_3IV1)

        scale= 8;



    wrap= s->block_wrap[n];

    dc_val = s->dc_val[0] + s->block_index[n];



    /* B C

     * A X

     */

    a = dc_val[ - 1];

    b = dc_val[ - 1 - wrap];

    c = dc_val[ - wrap];



    /* outside slice handling (we can't do that by memset as we need the dc for error resilience) */

    if(s->first_slice_line && n!=3){

        if(n!=2) b=c= 1024;

        if(n!=1 && s->mb_x == s->resync_mb_x) b=a= 1024;

    }

    if(s->mb_x == s->resync_mb_x && s->mb_y == s->resync_mb_y+1){

        if(n==0 || n==4 || n==5)

            b=1024;

    }



    if (abs(a - b) < abs(b - c)) {

        pred = c;

        *dir_ptr = 1; /* top */

    } else {

        pred = a;

        *dir_ptr = 0; /* left */

    }

    /* we assume pred is positive */

    pred = FASTDIV((pred + (scale >> 1)), scale);



    if(encoding){

        ret = level - pred;

    }else{

        level += pred;

        ret= level;

        if(s->error_recognition>=3){

            if(level<0){

                av_log(s->avctx, AV_LOG_ERROR, "dc<0 at %dx%d\n", s->mb_x, s->mb_y);

                return -1;

            }

            if(level*scale > 2048 + scale){

                av_log(s->avctx, AV_LOG_ERROR, "dc overflow at %dx%d\n", s->mb_x, s->mb_y);

                return -1;

            }

        }

    }

    level *=scale;

    if(level&(~2047)){

        if(level<0)

            level=0;

        else if(!(s->workaround_bugs&FF_BUG_DC_CLIP))

            level=2047;

    }

    dc_val[0]= level;



    return ret;

}

static void encode_subband_c0run(SnowContext *s, SubBand *b, DWTELEM *src, DWTELEM *parent, int stride, int orientation){

    const int w= b->width;

    const int h= b->height;

    int x, y;



    if(1){

        int run=0;

        int runs[w*h];

        int run_index=0;



        for(y=0; y<h; y++){

            for(x=0; x<w; x++){

                int v, p=0;

                int /*ll=0, */l=0, lt=0, t=0, rt=0;

                v= src[x + y*stride];



                if(y){

                    t= src[x + (y-1)*stride];

                    if(x){

                        lt= src[x - 1 + (y-1)*stride];

                    }

                    if(x + 1 < w){

                        rt= src[x + 1 + (y-1)*stride];

                    }

                }

                if(x){

                    l= src[x - 1 + y*stride];

                    /*if(x > 1){

                        if(orientation==1) ll= src[y + (x-2)*stride];

                        else               ll= src[x - 2 + y*stride];

                    }*/

                }

                if(parent){

                    int px= x>>1;

                    int py= y>>1;

                    if(px<b->parent->width && py<b->parent->height) 

                        p= parent[px + py*2*stride];

                }

                if(!(/*ll|*/l|lt|t|rt|p)){

                    if(v){

                        runs[run_index++]= run;

                        run=0;

                    }else{

                        run++;

                    }

                }

            }

        }

        runs[run_index++]= run;

        run_index=0;

        run= runs[run_index++];



        put_symbol2(&s->c, b->state[1], run, 3);



        for(y=0; y<h; y++){

            for(x=0; x<w; x++){

                int v, p=0;

                int /*ll=0, */l=0, lt=0, t=0, rt=0;

                v= src[x + y*stride];



                if(y){

                    t= src[x + (y-1)*stride];

                    if(x){

                        lt= src[x - 1 + (y-1)*stride];

                    }

                    if(x + 1 < w){

                        rt= src[x + 1 + (y-1)*stride];

                    }

                }

                if(x){

                    l= src[x - 1 + y*stride];

                    /*if(x > 1){

                        if(orientation==1) ll= src[y + (x-2)*stride];

                        else               ll= src[x - 2 + y*stride];

                    }*/

                }

                if(parent){

                    int px= x>>1;

                    int py= y>>1;

                    if(px<b->parent->width && py<b->parent->height) 

                        p= parent[px + py*2*stride];

                }

                if(/*ll|*/l|lt|t|rt|p){

                    int context= av_log2(/*ABS(ll) + */3*ABS(l) + ABS(lt) + 2*ABS(t) + ABS(rt) + ABS(p));



                    put_rac(&s->c, &b->state[0][context], !!v);

                }else{

                    if(!run){

                        run= runs[run_index++];



                        put_symbol2(&s->c, b->state[1], run, 3);

                        assert(v);

                    }else{

                        run--;

                        assert(!v);

                    }

                }

                if(v){

                    int context= av_log2(/*ABS(ll) + */3*ABS(l) + ABS(lt) + 2*ABS(t) + ABS(rt) + ABS(p));



                    put_symbol2(&s->c, b->state[context + 2], ABS(v)-1, context-4);

                    put_rac(&s->c, &b->state[0][16 + 1 + 3 + quant3b[l&0xFF] + 3*quant3b[t&0xFF]], v<0);

                }

            }

        }

    }

}

static int tcp_write(URLContext *h, const uint8_t *buf, int size)

{

    TCPContext *s = h->priv_data;

    int ret, size1, fd_max, len;

    fd_set wfds;

    struct timeval tv;



    size1 = size;

    while (size > 0) {

        if (url_interrupt_cb())

            return AVERROR(EINTR);

        fd_max = s->fd;

        FD_ZERO(&wfds);

        FD_SET(s->fd, &wfds);

        tv.tv_sec = 0;

        tv.tv_usec = 100 * 1000;

        ret = select(fd_max + 1, NULL, &wfds, NULL, &tv);

        if (ret > 0 && FD_ISSET(s->fd, &wfds)) {

            len = send(s->fd, buf, size, 0);

            if (len < 0) {

                if (ff_neterrno() != FF_NETERROR(EINTR) &&

                    ff_neterrno() != FF_NETERROR(EAGAIN))

                    return ff_neterrno();

                continue;

            }

            size -= len;

            buf += len;

        } else if (ret < 0) {

            if (ff_neterrno() == FF_NETERROR(EINTR))

                continue;

            return -1;

        }

    }

    return size1 - size;

}

static int hls_coding_unit(HEVCContext *s, int x0, int y0, int log2_cb_size)

{

    int cb_size          = 1 << log2_cb_size;

    HEVCLocalContext *lc = &s->HEVClc;

    int log2_min_cb_size = s->sps->log2_min_cb_size;

    int length           = cb_size >> log2_min_cb_size;

    int min_cb_width     = s->sps->min_cb_width;

    int x_cb             = x0 >> log2_min_cb_size;

    int y_cb             = y0 >> log2_min_cb_size;

    int x, y;



    lc->cu.x                = x0;

    lc->cu.y                = y0;

    lc->cu.rqt_root_cbf     = 1;

    lc->cu.pred_mode        = MODE_INTRA;

    lc->cu.part_mode        = PART_2Nx2N;

    lc->cu.intra_split_flag = 0;

    lc->cu.pcm_flag         = 0;



    SAMPLE_CTB(s->skip_flag, x_cb, y_cb) = 0;

    for (x = 0; x < 4; x++)

        lc->pu.intra_pred_mode[x] = 1;

    if (s->pps->transquant_bypass_enable_flag) {

        lc->cu.cu_transquant_bypass_flag = ff_hevc_cu_transquant_bypass_flag_decode(s);

        if (lc->cu.cu_transquant_bypass_flag)

            set_deblocking_bypass(s, x0, y0, log2_cb_size);

    } else

        lc->cu.cu_transquant_bypass_flag = 0;



    if (s->sh.slice_type != I_SLICE) {

        uint8_t skip_flag = ff_hevc_skip_flag_decode(s, x0, y0, x_cb, y_cb);



        lc->cu.pred_mode = MODE_SKIP;

        x = y_cb * min_cb_width + x_cb;

        for (y = 0; y < length; y++) {

            memset(&s->skip_flag[x], skip_flag, length);

            x += min_cb_width;

        }

        lc->cu.pred_mode = skip_flag ? MODE_SKIP : MODE_INTER;

    }



    if (SAMPLE_CTB(s->skip_flag, x_cb, y_cb)) {

        hls_prediction_unit(s, x0, y0, cb_size, cb_size, log2_cb_size, 0);

        intra_prediction_unit_default_value(s, x0, y0, log2_cb_size);



        if (!s->sh.disable_deblocking_filter_flag)

            ff_hevc_deblocking_boundary_strengths(s, x0, y0, log2_cb_size,

                                                  lc->slice_or_tiles_up_boundary,

                                                  lc->slice_or_tiles_left_boundary);

    } else {

        if (s->sh.slice_type != I_SLICE)

            lc->cu.pred_mode = ff_hevc_pred_mode_decode(s);

        if (lc->cu.pred_mode != MODE_INTRA ||

            log2_cb_size == s->sps->log2_min_cb_size) {

            lc->cu.part_mode        = ff_hevc_part_mode_decode(s, log2_cb_size);

            lc->cu.intra_split_flag = lc->cu.part_mode == PART_NxN &&

                                      lc->cu.pred_mode == MODE_INTRA;

        }



        if (lc->cu.pred_mode == MODE_INTRA) {

            if (lc->cu.part_mode == PART_2Nx2N && s->sps->pcm_enabled_flag &&

                log2_cb_size >= s->sps->pcm.log2_min_pcm_cb_size &&

                log2_cb_size <= s->sps->pcm.log2_max_pcm_cb_size) {

                lc->cu.pcm_flag = ff_hevc_pcm_flag_decode(s);

            }

            if (lc->cu.pcm_flag) {

                int ret;

                intra_prediction_unit_default_value(s, x0, y0, log2_cb_size);

                ret = hls_pcm_sample(s, x0, y0, log2_cb_size);

                if (s->sps->pcm.loop_filter_disable_flag)

                    set_deblocking_bypass(s, x0, y0, log2_cb_size);



                if (ret < 0)

                    return ret;

            } else {

                intra_prediction_unit(s, x0, y0, log2_cb_size);

            }

        } else {

            intra_prediction_unit_default_value(s, x0, y0, log2_cb_size);

            switch (lc->cu.part_mode) {

            case PART_2Nx2N:

                hls_prediction_unit(s, x0, y0, cb_size, cb_size, log2_cb_size, 0);

                break;

            case PART_2NxN:

                hls_prediction_unit(s, x0, y0,               cb_size, cb_size / 2, log2_cb_size, 0);

                hls_prediction_unit(s, x0, y0 + cb_size / 2, cb_size, cb_size / 2, log2_cb_size, 1);

                break;

            case PART_Nx2N:

                hls_prediction_unit(s, x0,               y0, cb_size / 2, cb_size, log2_cb_size, 0);

                hls_prediction_unit(s, x0 + cb_size / 2, y0, cb_size / 2, cb_size, log2_cb_size, 1);

                break;

            case PART_2NxnU:

                hls_prediction_unit(s, x0, y0,               cb_size, cb_size     / 4, log2_cb_size, 0);

                hls_prediction_unit(s, x0, y0 + cb_size / 4, cb_size, cb_size * 3 / 4, log2_cb_size, 1);

                break;

            case PART_2NxnD:

                hls_prediction_unit(s, x0, y0,                   cb_size, cb_size * 3 / 4, log2_cb_size, 0);

                hls_prediction_unit(s, x0, y0 + cb_size * 3 / 4, cb_size, cb_size     / 4, log2_cb_size, 1);

                break;

            case PART_nLx2N:

                hls_prediction_unit(s, x0,               y0, cb_size     / 4, cb_size, log2_cb_size, 0);

                hls_prediction_unit(s, x0 + cb_size / 4, y0, cb_size * 3 / 4, cb_size, log2_cb_size, 1);

                break;

            case PART_nRx2N:

                hls_prediction_unit(s, x0,                   y0, cb_size * 3 / 4, cb_size, log2_cb_size, 0);

                hls_prediction_unit(s, x0 + cb_size * 3 / 4, y0, cb_size     / 4, cb_size, log2_cb_size, 1);

                break;

            case PART_NxN:

                hls_prediction_unit(s, x0,               y0,               cb_size / 2, cb_size / 2, log2_cb_size, 0);

                hls_prediction_unit(s, x0 + cb_size / 2, y0,               cb_size / 2, cb_size / 2, log2_cb_size, 1);

                hls_prediction_unit(s, x0,               y0 + cb_size / 2, cb_size / 2, cb_size / 2, log2_cb_size, 2);

                hls_prediction_unit(s, x0 + cb_size / 2, y0 + cb_size / 2, cb_size / 2, cb_size / 2, log2_cb_size, 3);

                break;

            }

        }



        if (!lc->cu.pcm_flag) {

            if (lc->cu.pred_mode != MODE_INTRA &&

                !(lc->cu.part_mode == PART_2Nx2N && lc->pu.merge_flag)) {

                lc->cu.rqt_root_cbf = ff_hevc_no_residual_syntax_flag_decode(s);

            }

            if (lc->cu.rqt_root_cbf) {

                lc->cu.max_trafo_depth = lc->cu.pred_mode == MODE_INTRA ?

                                         s->sps->max_transform_hierarchy_depth_intra + lc->cu.intra_split_flag :

                                         s->sps->max_transform_hierarchy_depth_inter;

                hls_transform_tree(s, x0, y0, x0, y0, x0, y0, log2_cb_size,

                                   log2_cb_size, 0, 0);

            } else {

                if (!s->sh.disable_deblocking_filter_flag)

                    ff_hevc_deblocking_boundary_strengths(s, x0, y0, log2_cb_size,

                                                          lc->slice_or_tiles_up_boundary,

                                                          lc->slice_or_tiles_left_boundary);

            }

        }

    }



    if (s->pps->cu_qp_delta_enabled_flag && lc->tu.is_cu_qp_delta_coded == 0)

        ff_hevc_set_qPy(s, x0, y0, x0, y0, log2_cb_size);



    x = y_cb * min_cb_width + x_cb;

    for (y = 0; y < length; y++) {

        memset(&s->qp_y_tab[x], lc->qp_y, length);

        x += min_cb_width;

    }



    set_ct_depth(s, x0, y0, log2_cb_size, lc->ct.depth);



    return 0;

}

static int alloc_buffer(InputStream *ist, FrameBuffer **pbuf)

{

    AVCodecContext *s = ist->st->codec;

    FrameBuffer  *buf = av_mallocz(sizeof(*buf));

    int ret;

    const int pixel_size = av_pix_fmt_descriptors[s->pix_fmt].comp[0].step_minus1+1;

    int h_chroma_shift, v_chroma_shift;

    int edge = 32; // XXX should be avcodec_get_edge_width(), but that fails on svq1

    int w = s->width, h = s->height;



    if (!buf)

        return AVERROR(ENOMEM);



    if (!(s->flags & CODEC_FLAG_EMU_EDGE)) {

        w += 2*edge;

        h += 2*edge;

    }



    avcodec_align_dimensions(s, &w, &h);

    if ((ret = av_image_alloc(buf->base, buf->linesize, w, h,

                              s->pix_fmt, 32)) < 0) {

        av_freep(&buf);

        return ret;

    }

    /* XXX this shouldn't be needed, but some tests break without this line

     * those decoders are buggy and need to be fixed.

     * the following tests fail:

     * bethsoft-vid, cdgraphics, ansi, aasc, fraps-v1, qtrle-1bit

     */

    memset(buf->base[0], 128, ret);



    avcodec_get_chroma_sub_sample(s->pix_fmt, &h_chroma_shift, &v_chroma_shift);

    for (int i = 0; i < FF_ARRAY_ELEMS(buf->data); i++) {

        const int h_shift = i==0 ? 0 : h_chroma_shift;

        const int v_shift = i==0 ? 0 : v_chroma_shift;

        if (s->flags & CODEC_FLAG_EMU_EDGE)

            buf->data[i] = buf->base[i];

        else

            buf->data[i] = buf->base[i] +

                           FFALIGN((buf->linesize[i]*edge >> v_shift) +

                                   (pixel_size*edge >> h_shift), 32);

    }

    buf->w       = s->width;

    buf->h       = s->height;

    buf->pix_fmt = s->pix_fmt;

    buf->ist     = ist;



    *pbuf = buf;

    return 0;

}

