static inline int init_pfa_reindex_tabs(MDCT15Context *s)

{

    int i, j;

    const int b_ptwo = s->ptwo_fft.nbits; /* Bits for the power of two FFTs */

    const int l_ptwo = 1 << b_ptwo; /* Total length for the power of two FFTs */

    const int inv_1 = l_ptwo << ((4 - b_ptwo) & 3); /* (2^b_ptwo)^-1 mod 15 */

    const int inv_2 = 0xeeeeeeef & ((1U << b_ptwo) - 1); /* 15^-1 mod 2^b_ptwo */



    s->pfa_prereindex = av_malloc(15 * l_ptwo * sizeof(*s->pfa_prereindex));

    if (!s->pfa_prereindex)

        return 1;



    s->pfa_postreindex = av_malloc(15 * l_ptwo * sizeof(*s->pfa_postreindex));

    if (!s->pfa_postreindex)

        return 1;



    /* Pre/Post-reindex */

    for (i = 0; i < l_ptwo; i++) {

        for (j = 0; j < 15; j++) {

            const int q_pre = ((l_ptwo * j)/15 + i) >> b_ptwo;

            const int q_post = (((j*inv_1)/15) + (i*inv_2)) >> b_ptwo;

            const int k_pre = 15*i + ((j - q_pre*15) << b_ptwo);

            const int k_post = i*inv_2*15 + j*inv_1 - 15*q_post*l_ptwo;

            s->pfa_prereindex[i*15 + j] = k_pre;

            s->pfa_postreindex[k_post] = l_ptwo*j + i;

        }

    }



    return 0;

}

static void mxf_write_identification(AVFormatContext *s)

{

    MXFContext *mxf = s->priv_data;

    AVIOContext *pb = s->pb;

    const char *company = "Libav";

    const char *product = "OP1a Muxer";

    const char *version;

    int length;



    mxf_write_metadata_key(pb, 0x013000);

    PRINT_KEY(s, "identification key", pb->buf_ptr - 16);



    version = s->streams[0]->codec->flags & CODEC_FLAG_BITEXACT ?

        "0.0.0" : AV_STRINGIFY(LIBAVFORMAT_VERSION);

    length = 84 + (strlen(company)+strlen(product)+strlen(version))*2; // utf-16

    klv_encode_ber_length(pb, length);



    // write uid

    mxf_write_local_tag(pb, 16, 0x3C0A);

    mxf_write_uuid(pb, Identification, 0);

    PRINT_KEY(s, "identification uid", pb->buf_ptr - 16);



    // write generation uid

    mxf_write_local_tag(pb, 16, 0x3C09);

    mxf_write_uuid(pb, Identification, 1);



    mxf_write_local_tag_utf16(pb, 0x3C01, company); // Company Name

    mxf_write_local_tag_utf16(pb, 0x3C02, product); // Product Name

    mxf_write_local_tag_utf16(pb, 0x3C04, version); // Version String



    // write product uid

    mxf_write_local_tag(pb, 16, 0x3C05);

    mxf_write_uuid(pb, Identification, 2);



    // modification date

    mxf_write_local_tag(pb, 8, 0x3C06);

    avio_wb64(pb, mxf->timestamp);

}

void opt_output_file(const char *filename)

{

    AVStream *st;

    AVFormatContext *oc;

    int use_video, use_audio, nb_streams, input_has_video, input_has_audio;

    int codec_id;



    if (!strcmp(filename, "-"))

        filename = "pipe:";



    oc = av_mallocz(sizeof(AVFormatContext));



    if (!file_format) {

        file_format = guess_format(NULL, filename, NULL);

        if (!file_format)

            file_format = &mpeg_mux_format;

    }



    oc->format = file_format;



    if (!strcmp(file_format->name, "ffm") && 

        strstart(filename, "http:", NULL)) {

        /* special case for files sent to ffserver: we get the stream

           parameters from ffserver */

        if (read_ffserver_streams(oc, filename) < 0) {

            fprintf(stderr, "Could not read stream parameters from '%s'\n", filename);

            exit(1);

        }

    } else {

        use_video = file_format->video_codec != CODEC_ID_NONE;

        use_audio = file_format->audio_codec != CODEC_ID_NONE;



        /* disable if no corresponding type found */

        check_audio_video_inputs(&input_has_video, &input_has_audio);

        if (!input_has_video)

            use_video = 0;

        if (!input_has_audio)

            use_audio = 0;



        /* manual disable */

        if (audio_disable) {

            use_audio = 0;

        }

        if (video_disable) {

            use_video = 0;

        }



        nb_streams = 0;

        if (use_video) {

            AVCodecContext *video_enc;



            st = av_mallocz(sizeof(AVStream));

            if (!st) {

                fprintf(stderr, "Could not alloc stream\n");

                exit(1);

            }

            video_enc = &st->codec;



            codec_id = file_format->video_codec;

            if (video_codec_id != CODEC_ID_NONE)

                codec_id = video_codec_id;



            video_enc->codec_id = codec_id;

            video_enc->codec_type = CODEC_TYPE_VIDEO;



            video_enc->bit_rate = video_bit_rate;

            video_enc->frame_rate = frame_rate; 



            video_enc->width = frame_width;

            video_enc->height = frame_height;

            if (!intra_only)

                video_enc->gop_size = gop_size;

            else

                video_enc->gop_size = 0;

            if (video_qscale || same_quality) {

                video_enc->flags |= CODEC_FLAG_QSCALE;

                video_enc->quality = video_qscale;

            }

            /* XXX: need to find a way to set codec parameters */

            if (oc->format == &ppm_format ||

                oc->format == &ppmpipe_format) {

                video_enc->pix_fmt = PIX_FMT_RGB24;

            }



            oc->streams[nb_streams] = st;

            nb_streams++;

        }



        if (use_audio) {

            AVCodecContext *audio_enc;



            st = av_mallocz(sizeof(AVStream));

            if (!st) {

                fprintf(stderr, "Could not alloc stream\n");

                exit(1);

            }

            audio_enc = &st->codec;

            codec_id = file_format->audio_codec;

            if (audio_codec_id != CODEC_ID_NONE)

                codec_id = audio_codec_id;

            audio_enc->codec_id = codec_id;

            audio_enc->codec_type = CODEC_TYPE_AUDIO;



            audio_enc->bit_rate = audio_bit_rate;

            audio_enc->sample_rate = audio_sample_rate;

            audio_enc->channels = audio_channels;

            oc->streams[nb_streams] = st;

            nb_streams++;

        }



        oc->nb_streams = nb_streams;



        if (!nb_streams) {

            fprintf(stderr, "No audio or video streams available\n");

            exit(1);

        }



        if (str_title)

            nstrcpy(oc->title, sizeof(oc->title), str_title);

        if (str_author)

            nstrcpy(oc->author, sizeof(oc->author), str_author);

        if (str_copyright)

            nstrcpy(oc->copyright, sizeof(oc->copyright), str_copyright);

        if (str_comment)

            nstrcpy(oc->comment, sizeof(oc->comment), str_comment);

    }



    output_files[nb_output_files] = oc;

    /* dump the file content */

    dump_format(oc, nb_output_files, filename, 1);

    nb_output_files++;



    strcpy(oc->filename, filename);



    /* check filename in case of an image number is expected */

    if (oc->format->flags & AVFMT_NEEDNUMBER) {

        if (filename_number_test(oc->filename) < 0)

            exit(1);

    }



    if (!(oc->format->flags & AVFMT_NOFILE)) {

        /* test if it already exists to avoid loosing precious files */

        if (!file_overwrite && 

            (strchr(filename, ':') == NULL ||

             strstart(filename, "file:", NULL))) {

            if (url_exist(filename)) {

                int c;



                printf("File '%s' already exists. Overwrite ? [y/N] ", filename);

                fflush(stdout);

                c = getchar();

                if (toupper(c) != 'Y') {

                    fprintf(stderr, "Not overwriting - exiting\n");

                    exit(1);

                }

            }

        }



        /* open the file */

        if (url_fopen(&oc->pb, filename, URL_WRONLY) < 0) {

            fprintf(stderr, "Could not open '%s'\n", filename);

            exit(1);

        }

    }



    /* reset some options */

    file_format = NULL;

    audio_disable = 0;

    video_disable = 0;

    audio_codec_id = CODEC_ID_NONE;

    video_codec_id = CODEC_ID_NONE;

}

static int decode_frame_mp3on4(AVCodecContext * avctx,

                        void *data, int *data_size,

                        const uint8_t * buf, int buf_size)

{

    MP3On4DecodeContext *s = avctx->priv_data;

    MPADecodeContext *m;

    int len, out_size = 0;

    uint32_t header;

    OUT_INT *out_samples = data;

    OUT_INT decoded_buf[MPA_FRAME_SIZE * MPA_MAX_CHANNELS];

    OUT_INT *outptr, *bp;

    int fsize;

    int fr, i, j, n;



    len = buf_size;



    *data_size = 0;

    // Discard too short frames

    if (buf_size < HEADER_SIZE)

        return -1;



    // If only one decoder interleave is not needed

    outptr = s->frames == 1 ? out_samples : decoded_buf;



    for (fr = 0; fr < s->frames; fr++) {

        fsize = AV_RB16(buf) >> 4;

        fsize = FFMIN3(fsize, len, MPA_MAX_CODED_FRAME_SIZE);

        m = s->mp3decctx[fr];

        assert (m != NULL);



        header = (AV_RB32(buf) & 0x000fffff) | s->syncword; // patch header



        if (ff_mpa_check_header(header) < 0) { // Bad header, discard block

            *data_size = 0;

            return buf_size;

        }



        ff_mpegaudio_decode_header(m, header);

        out_size += mp_decode_frame(m, outptr, buf, fsize);

        buf += fsize;

        len -= fsize;



        if(s->frames > 1) {

            n = m->avctx->frame_size*m->nb_channels;

            /* interleave output data */

            bp = out_samples + s->coff[fr];

            if(m->nb_channels == 1) {

                for(j = 0; j < n; j++) {

                    *bp = decoded_buf[j];

                    bp += avctx->channels;

                }

            } else {

                for(j = 0; j < n; j++) {

                    bp[0] = decoded_buf[j++];

                    bp[1] = decoded_buf[j];

                    bp += avctx->channels;

                }

            }

        }

    }



    /* update codec info */

    avctx->sample_rate = s->mp3decctx[0]->sample_rate;

    avctx->bit_rate = 0;

    for (i = 0; i < s->frames; i++)

        avctx->bit_rate += s->mp3decctx[i]->bit_rate;



    *data_size = out_size;

    return buf_size;

}

static int decode_frame(AVCodecContext *avctx,

                        void *data,

                        int *data_size,

                        AVPacket *avpkt)

{

    const uint8_t *buf = avpkt->data;

    const uint8_t *buf_end = avpkt->data + avpkt->size;

    int buf_size       = avpkt->size;

    DPXContext *const s = avctx->priv_data;

    AVFrame *picture  = data;

    AVFrame *const p = &s->picture;

    uint8_t *ptr;



    int magic_num, offset, endian;

    int x, y;

    int w, h, stride, bits_per_color, descriptor, elements, target_packet_size, source_packet_size;



    unsigned int rgbBuffer;



    if (avpkt->size <= 1634) {

        av_log(avctx, AV_LOG_ERROR, "Packet too small for DPX header\n");

        return AVERROR_INVALIDDATA;

    }



    magic_num = AV_RB32(buf);

    buf += 4;



    /* Check if the files "magic number" is "SDPX" which means it uses

     * big-endian or XPDS which is for little-endian files */

    if (magic_num == AV_RL32("SDPX")) {

        endian = 0;

    } else if (magic_num == AV_RB32("SDPX")) {

        endian = 1;

    } else {

        av_log(avctx, AV_LOG_ERROR, "DPX marker not found\n");

        return -1;

    }



    offset = read32(&buf, endian);

    if (avpkt->size <= offset) {

        av_log(avctx, AV_LOG_ERROR, "Invalid data start offset\n");

        return AVERROR_INVALIDDATA;

    }

    // Need to end in 0x304 offset from start of file

    buf = avpkt->data + 0x304;

    w = read32(&buf, endian);

    h = read32(&buf, endian);



    // Need to end in 0x320 to read the descriptor

    buf += 20;

    descriptor = buf[0];



    // Need to end in 0x323 to read the bits per color

    buf += 3;

    avctx->bits_per_raw_sample =

    bits_per_color = buf[0];



    buf += 825;

    avctx->sample_aspect_ratio.num = read32(&buf, endian);

    avctx->sample_aspect_ratio.den = read32(&buf, endian);

    if (avctx->sample_aspect_ratio.num > 0 && avctx->sample_aspect_ratio.den > 0)

        av_reduce(&avctx->sample_aspect_ratio.num, &avctx->sample_aspect_ratio.den,

                   avctx->sample_aspect_ratio.num,  avctx->sample_aspect_ratio.den,

                  0x10000);

    else

        avctx->sample_aspect_ratio = (AVRational){ 0, 0 };



    switch (descriptor) {

        case 51: // RGBA

            elements = 4;

            break;

        case 50: // RGB

            elements = 3;

            break;

        default:

            av_log(avctx, AV_LOG_ERROR, "Unsupported descriptor %d\n", descriptor);

            return -1;

    }



    switch (bits_per_color) {

        case 8:

            if (elements == 4) {

                avctx->pix_fmt = PIX_FMT_RGBA;

            } else {

                avctx->pix_fmt = PIX_FMT_RGB24;

            }

            source_packet_size = elements;

            target_packet_size = elements;

            break;

        case 10:

            avctx->pix_fmt = PIX_FMT_RGB48;

            target_packet_size = 6;

            source_packet_size = 4;

            break;

        case 12:

        case 16:

            if (endian) {

                avctx->pix_fmt = elements == 4 ? PIX_FMT_RGBA64BE : PIX_FMT_RGB48BE;

            } else {

                avctx->pix_fmt = elements == 4 ? PIX_FMT_RGBA64LE : PIX_FMT_RGB48LE;

            }

            target_packet_size =

            source_packet_size = elements * 2;

            break;

        default:

            av_log(avctx, AV_LOG_ERROR, "Unsupported color depth : %d\n", bits_per_color);

            return -1;

    }



    if (s->picture.data[0])

        avctx->release_buffer(avctx, &s->picture);

    if (av_image_check_size(w, h, 0, avctx))

        return -1;

    if (w != avctx->width || h != avctx->height)

        avcodec_set_dimensions(avctx, w, h);

    if (avctx->get_buffer(avctx, p) < 0) {

        av_log(avctx, AV_LOG_ERROR, "get_buffer() failed\n");

        return -1;

    }



    // Move pointer to offset from start of file

    buf =  avpkt->data + offset;



    ptr    = p->data[0];

    stride = p->linesize[0];



    if (source_packet_size*avctx->width*avctx->height > buf_end - buf) {

        av_log(avctx, AV_LOG_ERROR, "Overread buffer. Invalid header?\n");

        return -1;

    }

    switch (bits_per_color) {

        case 10:

            for (x = 0; x < avctx->height; x++) {

               uint16_t *dst = (uint16_t*)ptr;

               for (y = 0; y < avctx->width; y++) {

                   rgbBuffer = read32(&buf, endian);

                   // Read out the 10-bit colors and convert to 16-bit

                   *dst++ = make_16bit(rgbBuffer >> 16);

                   *dst++ = make_16bit(rgbBuffer >>  6);

                   *dst++ = make_16bit(rgbBuffer <<  4);

               }

               ptr += stride;

            }

            break;

        case 8:

        case 12: // Treat 12-bit as 16-bit

        case 16:

            if (source_packet_size == target_packet_size) {

                for (x = 0; x < avctx->height; x++) {

                    memcpy(ptr, buf, target_packet_size*avctx->width);

                    ptr += stride;

                    buf += source_packet_size*avctx->width;

                }

            } else {

                for (x = 0; x < avctx->height; x++) {

                    uint8_t *dst = ptr;

                    for (y = 0; y < avctx->width; y++) {

                        memcpy(dst, buf, target_packet_size);

                        dst += target_packet_size;

                        buf += source_packet_size;

                    }

                    ptr += stride;

                }

            }

            break;

    }



    *picture   = s->picture;

    *data_size = sizeof(AVPicture);



    return buf_size;

}

