static int mpeg4_unpack_bframes_filter(AVBSFContext *ctx, AVPacket *out)

{

    UnpackBFramesBSFContext *s = ctx->priv_data;

    int pos_p = -1, nb_vop = 0, pos_vop2 = -1, ret = 0;

    AVPacket *in;



    ret = ff_bsf_get_packet(ctx, &in);

    if (ret < 0)

        return ret;



    scan_buffer(in->data, in->size, &pos_p, &nb_vop, &pos_vop2);

    av_log(ctx, AV_LOG_DEBUG, "Found %d VOP startcode(s) in this packet.\n", nb_vop);



    if (pos_vop2 >= 0) {

        if (s->b_frame_buf) {

            av_log(ctx, AV_LOG_WARNING,

                   "Missing one N-VOP packet, discarding one B-frame.\n");

            av_freep(&s->b_frame_buf);

            s->b_frame_buf_size = 0;

        }

        /* store the packed B-frame in the BSFContext */

        s->b_frame_buf_size = in->size - pos_vop2;

        s->b_frame_buf      = create_new_buffer(in->data + pos_vop2, s->b_frame_buf_size);

        if (!s->b_frame_buf) {

            s->b_frame_buf_size = 0;

            av_packet_free(&in);

            return AVERROR(ENOMEM);

        }

    }



    if (nb_vop > 2) {

        av_log(ctx, AV_LOG_WARNING,

       "Found %d VOP headers in one packet, only unpacking one.\n", nb_vop);

    }



    if (nb_vop == 1 && s->b_frame_buf) {

        /* use frame from BSFContext */

        ret = av_packet_copy_props(out, in);

        if (ret < 0) {

            av_packet_free(&in);

            return ret;

        }



        av_packet_from_data(out, s->b_frame_buf, s->b_frame_buf_size);

        if (in->size <= MAX_NVOP_SIZE) {

            /* N-VOP */

            av_log(ctx, AV_LOG_DEBUG, "Skipping N-VOP.\n");

            s->b_frame_buf      = NULL;

            s->b_frame_buf_size = 0;

        } else {

            /* copy packet into BSFContext */

            s->b_frame_buf_size = in->size;

            s->b_frame_buf      = create_new_buffer(in->data, in->size);

            if (!s->b_frame_buf) {

                s->b_frame_buf_size = 0;

                av_packet_unref(out);

                av_packet_free(&in);

                return AVERROR(ENOMEM);

            }

        }

    } else if (nb_vop >= 2) {

        /* use first frame of the packet */

        av_packet_move_ref(out, in);

        out->size = pos_vop2;

    } else if (pos_p >= 0) {

        av_log(ctx, AV_LOG_DEBUG, "Updating DivX userdata (remove trailing 'p').\n");

        av_packet_move_ref(out, in);

        /* remove 'p' (packed) from the end of the (DivX) userdata string */

        out->data[pos_p] = '\0';

    } else {

        /* copy packet */

        av_packet_move_ref(out, in);

    }



    av_packet_free(&in);



    return 0;

}

static int set_string_number(void *obj, void *target_obj, const AVOption *o, const char *val, void *dst)

{

    int ret = 0;

    int num, den;

    char c;



    if (sscanf(val, "%d%*1[:/]%d%c", &num, &den, &c) == 2) {

        if ((ret = write_number(obj, o, dst, 1, den, num)) >= 0)

            return ret;

        ret = 0;

    }



    for (;;) {

        int i = 0;

        char buf[256];

        int cmd = 0;

        double d;

        int64_t intnum = 1;



        if (o->type == AV_OPT_TYPE_FLAGS) {

            if (*val == '+' || *val == '-')

                cmd = *(val++);

            for (; i < sizeof(buf) - 1 && val[i] && val[i] != '+' && val[i] != '-'; i++)

                buf[i] = val[i];

            buf[i] = 0;

        }



        {

            const AVOption *o_named = av_opt_find(target_obj, buf, o->unit, 0, 0);

            int res;

            int ci = 0;

            double const_values[64];

            const char * const_names[64];

            if (o_named && o_named->type == AV_OPT_TYPE_CONST)

                d = DEFAULT_NUMVAL(o_named);

            else {

                if (o->unit) {

                    for (o_named = NULL; o_named = av_opt_next(target_obj, o_named); ) {

                        if (o_named->type == AV_OPT_TYPE_CONST &&

                            o_named->unit &&

                            !strcmp(o_named->unit, o->unit)) {

                            if (ci + 6 >= FF_ARRAY_ELEMS(const_values)) {

                                av_log(obj, AV_LOG_ERROR, "const_values array too small for %s\n", o->unit);

                                return AVERROR_PATCHWELCOME;

                            }

                            const_names [ci  ] = o_named->name;

                            const_values[ci++] = DEFAULT_NUMVAL(o_named);

                        }

                    }

                }

                const_names [ci  ] = "default";

                const_values[ci++] = DEFAULT_NUMVAL(o);

                const_names [ci  ] = "max";

                const_values[ci++] = o->max;

                const_names [ci  ] = "min";

                const_values[ci++] = o->min;

                const_names [ci  ] = "none";

                const_values[ci++] = 0;

                const_names [ci  ] = "all";

                const_values[ci++] = ~0;

                const_names [ci] = NULL;

                const_values[ci] = 0;



                res = av_expr_parse_and_eval(&d, i ? buf : val, const_names,

                                            const_values, NULL, NULL, NULL, NULL, NULL, 0, obj);

                if (res < 0) {

                    av_log(obj, AV_LOG_ERROR, "Unable to parse option value \"%s\"\n", val);

                    return res;

                }

            }

        }

        if (o->type == AV_OPT_TYPE_FLAGS) {

            read_number(o, dst, NULL, NULL, &intnum);

            if      (cmd == '+') d = intnum | (int64_t)d;

            else if (cmd == '-') d = intnum &~(int64_t)d;

        }



        if ((ret = write_number(obj, o, dst, d, 1, 1)) < 0)

            return ret;

        val += i;

        if (!i || !*val)

            return 0;

    }



    return 0;

}

static int init_input(AVFormatContext *s, const char *filename, AVDictionary **options)

{

    int ret;

    AVProbeData pd = {filename, NULL, 0};



    if(s->iformat && !strlen(filename))

        return 0;



    if (s->pb) {

        s->flags |= AVFMT_FLAG_CUSTOM_IO;

        if (!s->iformat)

            return av_probe_input_buffer(s->pb, &s->iformat, filename, s, 0, 0);

        else if (s->iformat->flags & AVFMT_NOFILE)

            av_log(s, AV_LOG_WARNING, "Custom AVIOContext makes no sense and "

                                      "will be ignored with AVFMT_NOFILE format.\n");

        return 0;

    }



    if ( (s->iformat && s->iformat->flags & AVFMT_NOFILE) ||

        (!s->iformat && (s->iformat = av_probe_input_format(&pd, 0))))

        return 0;



    if ((ret = avio_open2(&s->pb, filename, AVIO_FLAG_READ,

                          &s->interrupt_callback, options)) < 0)

        return ret;

    if (s->iformat)

        return 0;

    return av_probe_input_buffer(s->pb, &s->iformat, filename, s, 0, 0);

}

static int mpeg1_decode_sequence(AVCodecContext *avctx,

                                 const uint8_t *buf, int buf_size)

{

    Mpeg1Context *s1  = avctx->priv_data;

    MpegEncContext *s = &s1->mpeg_enc_ctx;

    int width, height;

    int i, v, j;



    init_get_bits(&s->gb, buf, buf_size * 8);



    width  = get_bits(&s->gb, 12);

    height = get_bits(&s->gb, 12);

    if (width == 0 || height == 0) {

        av_log(avctx, AV_LOG_WARNING,

               "Invalid horizontal or vertical size value.\n");

        if (avctx->err_recognition & (AV_EF_BITSTREAM | AV_EF_COMPLIANT))

            return AVERROR_INVALIDDATA;

    }

    s->aspect_ratio_info = get_bits(&s->gb, 4);

    if (s->aspect_ratio_info == 0) {

        av_log(avctx, AV_LOG_ERROR, "aspect ratio has forbidden 0 value\n");

        if (avctx->err_recognition & (AV_EF_BITSTREAM | AV_EF_COMPLIANT))

            return AVERROR_INVALIDDATA;

    }

    s->frame_rate_index = get_bits(&s->gb, 4);

    if (s->frame_rate_index == 0 || s->frame_rate_index > 13) {

        av_log(avctx, AV_LOG_WARNING,

               "frame_rate_index %d is invalid\n", s->frame_rate_index);

        s->frame_rate_index = 1;

    }

    s->bit_rate = get_bits(&s->gb, 18) * 400;

    if (check_marker(&s->gb, "in sequence header") == 0) {

        return AVERROR_INVALIDDATA;

    }



    s->avctx->rc_buffer_size = get_bits(&s->gb, 10) * 1024 * 16;

    skip_bits(&s->gb, 1);



    /* get matrix */

    if (get_bits1(&s->gb)) {

        load_matrix(s, s->chroma_intra_matrix, s->intra_matrix, 1);

    } else {

        for (i = 0; i < 64; i++) {

            j = s->idsp.idct_permutation[i];

            v = ff_mpeg1_default_intra_matrix[i];

            s->intra_matrix[j]        = v;

            s->chroma_intra_matrix[j] = v;

        }

    }

    if (get_bits1(&s->gb)) {

        load_matrix(s, s->chroma_inter_matrix, s->inter_matrix, 0);

    } else {

        for (i = 0; i < 64; i++) {

            int j = s->idsp.idct_permutation[i];

            v = ff_mpeg1_default_non_intra_matrix[i];

            s->inter_matrix[j]        = v;

            s->chroma_inter_matrix[j] = v;

        }

    }



    if (show_bits(&s->gb, 23) != 0) {

        av_log(s->avctx, AV_LOG_ERROR, "sequence header damaged\n");

        return AVERROR_INVALIDDATA;

    }



    s->width  = width;

    s->height = height;



    /* We set MPEG-2 parameters so that it emulates MPEG-1. */

    s->progressive_sequence = 1;

    s->progressive_frame    = 1;

    s->picture_structure    = PICT_FRAME;

    s->first_field          = 0;

    s->frame_pred_frame_dct = 1;

    s->chroma_format        = 1;

    s->codec_id             =

    s->avctx->codec_id      = AV_CODEC_ID_MPEG1VIDEO;

    s->out_format           = FMT_MPEG1;

    s->swap_uv              = 0; // AFAIK VCR2 does not have SEQ_HEADER

    if (s->avctx->flags & AV_CODEC_FLAG_LOW_DELAY)

        s->low_delay = 1;



    if (s->avctx->debug & FF_DEBUG_PICT_INFO)

        av_log(s->avctx, AV_LOG_DEBUG, "vbv buffer: %d, bitrate:%"PRId64", aspect_ratio_info: %d \n",

               s->avctx->rc_buffer_size, s->bit_rate, s->aspect_ratio_info);



    return 0;

}

static int s302m_decode_frame(AVCodecContext *avctx, void *data,

                              int *got_frame_ptr, AVPacket *avpkt)

{

    S302Context *s = avctx->priv_data;

    AVFrame *frame     = data;

    const uint8_t *buf = avpkt->data;

    int buf_size       = avpkt->size;

    int block_size, ret;

    int i;

    int non_pcm_data_type = -1;



    int frame_size = s302m_parse_frame_header(avctx, buf, buf_size);

    if (frame_size < 0)

        return frame_size;



    buf_size -= AES3_HEADER_LEN;

    buf      += AES3_HEADER_LEN;



    /* get output buffer */

    block_size = (avctx->bits_per_raw_sample + 4) / 4;

    frame->nb_samples = 2 * (buf_size / block_size) / avctx->channels;

    if ((ret = ff_get_buffer(avctx, frame, 0)) < 0)

        return ret;



    avctx->bit_rate = 48000 * avctx->channels * (avctx->bits_per_raw_sample + 4) +

                      32 * 48000 / frame->nb_samples;

    buf_size = (frame->nb_samples * avctx->channels / 2) * block_size;



    if (avctx->bits_per_raw_sample == 24) {

        uint32_t *o = (uint32_t *)frame->data[0];

        for (; buf_size > 6; buf_size -= 7) {

            *o++ = (ff_reverse[buf[2]]        << 24) |

                   (ff_reverse[buf[1]]        << 16) |

                   (ff_reverse[buf[0]]        <<  8);

            *o++ = (ff_reverse[buf[6] & 0xf0] << 28) |

                   (ff_reverse[buf[5]]        << 20) |

                   (ff_reverse[buf[4]]        << 12) |

                   (ff_reverse[buf[3] & 0x0f] <<  4);

            buf += 7;

        }

        o = (uint32_t *)frame->data[0];

        if (avctx->channels == 2)

            for (i=0; i<frame->nb_samples * 2 - 6; i+=2) {

                if (o[i] || o[i+1] || o[i+2] || o[i+3])

                    break;

                if (o[i+4] == 0x96F87200U && o[i+5] == 0xA54E1F00) {

                    non_pcm_data_type = (o[i+6] >> 16) & 0x1F;

                    break;

                }

            }

    } else if (avctx->bits_per_raw_sample == 20) {

        uint32_t *o = (uint32_t *)frame->data[0];

        for (; buf_size > 5; buf_size -= 6) {

            *o++ = (ff_reverse[buf[2] & 0xf0] << 28) |

                   (ff_reverse[buf[1]]        << 20) |

                   (ff_reverse[buf[0]]        << 12);

            *o++ = (ff_reverse[buf[5] & 0xf0] << 28) |

                   (ff_reverse[buf[4]]        << 20) |

                   (ff_reverse[buf[3]]        << 12);

            buf += 6;

        }

        o = (uint32_t *)frame->data[0];

        if (avctx->channels == 2)

            for (i=0; i<frame->nb_samples * 2 - 6; i+=2) {

                if (o[i] || o[i+1] || o[i+2] || o[i+3])

                    break;

                if (o[i+4] == 0x6F872000U && o[i+5] == 0x54E1F000) {

                    non_pcm_data_type = (o[i+6] >> 16) & 0x1F;

                    break;

                }

            }

    } else {

        uint16_t *o = (uint16_t *)frame->data[0];

        for (; buf_size > 4; buf_size -= 5) {

            *o++ = (ff_reverse[buf[1]]        <<  8) |

                    ff_reverse[buf[0]];

            *o++ = (ff_reverse[buf[4] & 0xf0] << 12) |

                   (ff_reverse[buf[3]]        <<  4) |

                   (ff_reverse[buf[2]]        >>  4);

            buf += 5;

        }

        o = (uint16_t *)frame->data[0];

        if (avctx->channels == 2)

            for (i=0; i<frame->nb_samples * 2 - 6; i+=2) {

                if (o[i] || o[i+1] || o[i+2] || o[i+3])

                    break;

                if (o[i+4] == 0xF872U && o[i+5] == 0x4E1F) {

                    non_pcm_data_type = (o[i+6] & 0x1F);

                    break;

                }

            }

    }



    if (non_pcm_data_type != -1) {

        if (s->non_pcm_mode == 3) {

            av_log(avctx, AV_LOG_ERROR,

                   "S302 non PCM mode with data type %d not supported\n",

                   non_pcm_data_type);

            return AVERROR_PATCHWELCOME;

        }

        if (s->non_pcm_mode & 1) {

            return avpkt->size;

        }

    }



    avctx->sample_rate = 48000;



    *got_frame_ptr = 1;



    return avpkt->size;

}

static inline void skip_hdr_extension(GetBitContext *gb)

{

    int i, len;



    do {

        len = get_bits(gb, 8);

        for (i = 0; i < len; i++) skip_bits(gb, 8);

    } while(len);

}

int av_opt_set_dict2(void *obj, AVDictionary **options, int search_flags)

{

    AVDictionaryEntry *t = NULL;

    AVDictionary    *tmp = NULL;

    int ret = 0;



    if (!options)

        return 0;



    while ((t = av_dict_get(*options, "", t, AV_DICT_IGNORE_SUFFIX))) {

        ret = av_opt_set(obj, t->key, t->value, search_flags);

        if (ret == AVERROR_OPTION_NOT_FOUND)

            av_dict_set(&tmp, t->key, t->value, 0);

        else if (ret < 0) {

            av_log(obj, AV_LOG_ERROR, "Error setting option %s to value %s.\n", t->key, t->value);

            break;

        }

        ret = 0;

    }

    av_dict_free(options);

    *options = tmp;

    return ret;

}

matroska_read_header (AVFormatContext    *s,

                      AVFormatParameters *ap)

{

    MatroskaDemuxContext *matroska = s->priv_data;

    char *doctype;

    int version, last_level, res = 0;

    uint32_t id;



    matroska->ctx = s;



    /* First read the EBML header. */

    doctype = NULL;

    if ((res = ebml_read_header(matroska, &doctype, &version)) < 0)

        return res;

    if ((doctype == NULL) || strcmp(doctype, "matroska")) {

        av_log(matroska->ctx, AV_LOG_ERROR,

               "Wrong EBML doctype ('%s' != 'matroska').\n",

               doctype ? doctype : "(none)");

        if (doctype)

            av_free(doctype);

        return AVERROR_NOFMT;

    }

    av_free(doctype);

    if (version > 2) {

        av_log(matroska->ctx, AV_LOG_ERROR,

               "Matroska demuxer version 2 too old for file version %d\n",

               version);

        return AVERROR_NOFMT;

    }



    /* The next thing is a segment. */

    while (1) {

        if (!(id = ebml_peek_id(matroska, &last_level)))

            return AVERROR_IO;

        if (id == MATROSKA_ID_SEGMENT)

            break;



        /* oi! */

        av_log(matroska->ctx, AV_LOG_INFO,

               "Expected a Segment ID (0x%x), but received 0x%x!\n",

               MATROSKA_ID_SEGMENT, id);

        if ((res = ebml_read_skip(matroska)) < 0)

            return res;

    }



    /* We now have a Matroska segment.

     * Seeks are from the beginning of the segment,

     * after the segment ID/length. */

    if ((res = ebml_read_master(matroska, &id)) < 0)

        return res;

    matroska->segment_start = url_ftell(&s->pb);



    matroska->time_scale = 1000000;

    /* we've found our segment, start reading the different contents in here */

    while (res == 0) {

        if (!(id = ebml_peek_id(matroska, &matroska->level_up))) {

            res = AVERROR_IO;

            break;

        } else if (matroska->level_up) {

            matroska->level_up--;

            break;

        }



        switch (id) {

            /* stream info */

            case MATROSKA_ID_INFO: {

                if ((res = ebml_read_master(matroska, &id)) < 0)

                    break;

                res = matroska_parse_info(matroska);

                break;

            }



            /* track info headers */

            case MATROSKA_ID_TRACKS: {

                if ((res = ebml_read_master(matroska, &id)) < 0)

                    break;

                res = matroska_parse_tracks(matroska);

                break;

            }



            /* stream index */

            case MATROSKA_ID_CUES: {

                if (!matroska->index_parsed) {

                    if ((res = ebml_read_master(matroska, &id)) < 0)

                        break;

                    res = matroska_parse_index(matroska);

                } else

                    res = ebml_read_skip(matroska);

                break;

            }



            /* metadata */

            case MATROSKA_ID_TAGS: {

                if (!matroska->metadata_parsed) {

                    if ((res = ebml_read_master(matroska, &id)) < 0)

                        break;

                    res = matroska_parse_metadata(matroska);

                } else

                    res = ebml_read_skip(matroska);

                break;

            }



            /* file index (if seekable, seek to Cues/Tags to parse it) */

            case MATROSKA_ID_SEEKHEAD: {

                if ((res = ebml_read_master(matroska, &id)) < 0)

                    break;

                res = matroska_parse_seekhead(matroska);

                break;

            }



            case MATROSKA_ID_CLUSTER: {

                /* Do not read the master - this will be done in the next

                 * call to matroska_read_packet. */

                res = 1;

                break;

            }



            default:

                av_log(matroska->ctx, AV_LOG_INFO,

                       "Unknown matroska file header ID 0x%x\n", id);

            /* fall-through */



            case EBML_ID_VOID:

                res = ebml_read_skip(matroska);

                break;

        }



        if (matroska->level_up) {

            matroska->level_up--;

            break;

        }

    }



    /* Have we found a cluster? */

    if (ebml_peek_id(matroska, NULL) == MATROSKA_ID_CLUSTER) {

        int i, j;

        MatroskaTrack *track;

        AVStream *st;



        for (i = 0; i < matroska->num_tracks; i++) {

            enum CodecID codec_id = CODEC_ID_NONE;

            uint8_t *extradata = NULL;

            int extradata_size = 0;

            int extradata_offset = 0;

            track = matroska->tracks[i];



            /* libavformat does not really support subtitles.

             * Also apply some sanity checks. */

            if ((track->type == MATROSKA_TRACK_TYPE_SUBTITLE) ||

                (track->codec_id == NULL))

                continue;



            for(j=0; codec_tags[j].str; j++){

                if(!strncmp(codec_tags[j].str, track->codec_id,

                            strlen(codec_tags[j].str))){

                    codec_id= codec_tags[j].id;

                    break;

                }

            }



            /* Set the FourCC from the CodecID. */

            /* This is the MS compatibility mode which stores a

             * BITMAPINFOHEADER in the CodecPrivate. */

            if (!strcmp(track->codec_id,

                        MATROSKA_CODEC_ID_VIDEO_VFW_FOURCC) &&

                (track->codec_priv_size >= 40) &&

                (track->codec_priv != NULL)) {

                unsigned char *p;



                /* Offset of biCompression. Stored in LE. */

                p = (unsigned char *)track->codec_priv + 16;

                ((MatroskaVideoTrack *)track)->fourcc = (p[3] << 24) |

                                 (p[2] << 16) | (p[1] << 8) | p[0];

                codec_id = codec_get_id(codec_bmp_tags, ((MatroskaVideoTrack *)track)->fourcc);



            }



            /* This is the MS compatibility mode which stores a

             * WAVEFORMATEX in the CodecPrivate. */

            else if (!strcmp(track->codec_id,

                             MATROSKA_CODEC_ID_AUDIO_ACM) &&

                (track->codec_priv_size >= 18) &&

                (track->codec_priv != NULL)) {

                unsigned char *p;

                uint16_t tag;



                /* Offset of wFormatTag. Stored in LE. */

                p = (unsigned char *)track->codec_priv;

                tag = (p[1] << 8) | p[0];

                codec_id = codec_get_id(codec_wav_tags, tag);



            }



            else if (codec_id == CODEC_ID_MPEG1VIDEO ||

                     codec_id == CODEC_ID_MPEG2VIDEO ||

                     codec_id == CODEC_ID_MPEG4      ||

                     codec_id == CODEC_ID_MSMPEG4V3  ||

                     codec_id == CODEC_ID_H264) {

                track->flags |= MATROSKA_TRACK_REORDER;

            }



            else if (codec_id == CODEC_ID_AAC && !track->codec_priv_size) {

                MatroskaAudioTrack *audiotrack = (MatroskaAudioTrack *) track;

                int profile = matroska_aac_profile(track->codec_id);

                int sri = matroska_aac_sri(audiotrack->internal_samplerate);

                extradata = av_malloc(5);

                if (extradata == NULL)

                    return AVERROR_NOMEM;

                extradata[0] = (profile << 3) | ((sri&0x0E) >> 1);

                extradata[1] = ((sri&0x01) << 7) | (audiotrack->channels<<3);

                if (strstr(track->codec_id, "SBR")) {

                    sri = matroska_aac_sri(audiotrack->samplerate);

                    extradata[2] = 0x56;

                    extradata[3] = 0xE5;

                    extradata[4] = 0x80 | (sri<<3);

                    extradata_size = 5;

                } else {

                    extradata_size = 2;

                }

                track->default_duration = 1024*1000 / audiotrack->internal_samplerate;

            }



            else if (codec_id == CODEC_ID_TTA) {

                MatroskaAudioTrack *audiotrack = (MatroskaAudioTrack *) track;

                ByteIOContext b;

                extradata_size = 30;

                extradata = av_mallocz(extradata_size);

                if (extradata == NULL)

                    return AVERROR_NOMEM;

                init_put_byte(&b, extradata, extradata_size, 1,

                              NULL, NULL, NULL, NULL);

                put_buffer(&b, (uint8_t *) "TTA1", 4);

                put_le16(&b, 1);

                put_le16(&b, audiotrack->channels);

                put_le16(&b, audiotrack->bitdepth);

                put_le32(&b, audiotrack->samplerate);

                put_le32(&b, matroska->ctx->duration * audiotrack->samplerate);

            }



            else if (codec_id == CODEC_ID_RV10 || codec_id == CODEC_ID_RV20 ||

                     codec_id == CODEC_ID_RV30 || codec_id == CODEC_ID_RV40) {

                extradata_offset = 26;

                track->codec_priv_size -= extradata_offset;

                track->flags |= MATROSKA_TRACK_REAL_V;

            }



            if (codec_id == CODEC_ID_NONE) {

                av_log(matroska->ctx, AV_LOG_INFO,

                       "Unknown/unsupported CodecID %s.\n",

                       track->codec_id);

            }



            track->stream_index = matroska->num_streams;



            matroska->num_streams++;

            st = av_new_stream(s, track->stream_index);

            if (st == NULL)

                return AVERROR_NOMEM;

            av_set_pts_info(st, 64, matroska->time_scale, 1000*1000*1000); /* 64 bit pts in ns */



            st->codec->codec_id = codec_id;



            if (track->default_duration)

                av_reduce(&st->codec->time_base.num, &st->codec->time_base.den,

                          track->default_duration, 1000, 30000);



            if(extradata){

                st->codec->extradata = extradata;

                st->codec->extradata_size = extradata_size;

            } else if(track->codec_priv && track->codec_priv_size > 0){

                st->codec->extradata = av_malloc(track->codec_priv_size);

                if(st->codec->extradata == NULL)

                    return AVERROR_NOMEM;

                st->codec->extradata_size = track->codec_priv_size;

                memcpy(st->codec->extradata,track->codec_priv+extradata_offset,

                       track->codec_priv_size);

            }



            if (track->type == MATROSKA_TRACK_TYPE_VIDEO) {

                MatroskaVideoTrack *videotrack = (MatroskaVideoTrack *)track;



                st->codec->codec_type = CODEC_TYPE_VIDEO;

                st->codec->codec_tag = videotrack->fourcc;

                st->codec->width = videotrack->pixel_width;

                st->codec->height = videotrack->pixel_height;

                if (videotrack->display_width == 0)

                    videotrack->display_width= videotrack->pixel_width;

                if (videotrack->display_height == 0)

                    videotrack->display_height= videotrack->pixel_height;

                av_reduce(&st->codec->sample_aspect_ratio.num,

                          &st->codec->sample_aspect_ratio.den,

                          st->codec->height * videotrack->display_width,

                          st->codec-> width * videotrack->display_height,

                          255);

            } else if (track->type == MATROSKA_TRACK_TYPE_AUDIO) {

                MatroskaAudioTrack *audiotrack = (MatroskaAudioTrack *)track;



                st->codec->codec_type = CODEC_TYPE_AUDIO;

                st->codec->sample_rate = audiotrack->samplerate;

                st->codec->channels = audiotrack->channels;

            } else if (track->type == MATROSKA_TRACK_TYPE_SUBTITLE) {

                st->codec->codec_type = CODEC_TYPE_SUBTITLE;

            }



            /* What do we do with private data? E.g. for Vorbis. */

        }

        res = 0;

    }



    return res;

}

