int ff_lpc_calc_coefs(DSPContext *s,

                      const int32_t *samples, int blocksize, int min_order,

                      int max_order, int precision,

                      int32_t coefs[][MAX_LPC_ORDER], int *shift, int use_lpc,

                      int omethod, int max_shift, int zero_shift)

{

    double autoc[MAX_LPC_ORDER+1];

    double ref[MAX_LPC_ORDER];

    double lpc[MAX_LPC_ORDER][MAX_LPC_ORDER];

    int i, j, pass;

    int opt_order;



    assert(max_order >= MIN_LPC_ORDER && max_order <= MAX_LPC_ORDER);



    if(use_lpc == 1){

        s->flac_compute_autocorr(samples, blocksize, max_order, autoc);



        compute_lpc_coefs(autoc, max_order, &lpc[0][0], MAX_LPC_ORDER, 0, 1);



        for(i=0; i<max_order; i++)

            ref[i] = fabs(lpc[i][i]);

    }else{

        LLSModel m[2];

        double var[MAX_LPC_ORDER+1], weight;



        for(pass=0; pass<use_lpc-1; pass++){

            av_init_lls(&m[pass&1], max_order);



            weight=0;

            for(i=max_order; i<blocksize; i++){

                for(j=0; j<=max_order; j++)

                    var[j]= samples[i-j];



                if(pass){

                    double eval, inv, rinv;

                    eval= av_evaluate_lls(&m[(pass-1)&1], var+1, max_order-1);

                    eval= (512>>pass) + fabs(eval - var[0]);

                    inv = 1/eval;

                    rinv = sqrt(inv);

                    for(j=0; j<=max_order; j++)

                        var[j] *= rinv;

                    weight += inv;

                }else

                    weight++;



                av_update_lls(&m[pass&1], var, 1.0);

            }

            av_solve_lls(&m[pass&1], 0.001, 0);

        }



        for(i=0; i<max_order; i++){

            for(j=0; j<max_order; j++)

                lpc[i][j]=-m[(pass-1)&1].coeff[i][j];

            ref[i]= sqrt(m[(pass-1)&1].variance[i] / weight) * (blocksize - max_order) / 4000;

        }

        for(i=max_order-1; i>0; i--)

            ref[i] = ref[i-1] - ref[i];

    }

    opt_order = max_order;



    if(omethod == ORDER_METHOD_EST) {

        opt_order = estimate_best_order(ref, min_order, max_order);

        i = opt_order-1;

        quantize_lpc_coefs(lpc[i], i+1, precision, coefs[i], &shift[i], max_shift, zero_shift);

    } else {

        for(i=min_order-1; i<max_order; i++) {

            quantize_lpc_coefs(lpc[i], i+1, precision, coefs[i], &shift[i], max_shift, zero_shift);

        }

    }



    return opt_order;

}

static void idct(uint8_t *dst, int dst_linesize, int src[64])

{

    int i, j, k;

    double tmp[64];



    for (i = 0; i < 8; i++) {

        for (j = 0; j < 8; j++) {

            double sum = 0.0;



            for (k = 0; k < 8; k++)

                sum += c[k*8+j] * src[8*i+k];



            tmp[8*i+j] = sum;

        }

    }



    for (j = 0; j < 8; j++) {

        for (i = 0; i < 8; i++) {

            double sum = 0.0;



            for (k = 0; k < 8; k++)

                sum += c[k*8+i]*tmp[8*k+j];



            dst[dst_linesize*i + j] = av_clip_uint8((int)floor(sum+0.5));

        }

    }

}

static int decode_cce(AACContext * ac, GetBitContext * gb, ChannelElement * che) {

    int num_gain = 0;

    int c, g, sfb, ret, idx = 0;

    int sign;

    float scale;

    SingleChannelElement * sce = &che->ch[0];

    ChannelCoupling * coup     = &che->coup;



    coup->coupling_point = 2*get_bits1(gb);

    coup->num_coupled = get_bits(gb, 3);

    for (c = 0; c <= coup->num_coupled; c++) {

        num_gain++;

        coup->type[c] = get_bits1(gb) ? TYPE_CPE : TYPE_SCE;

        coup->id_select[c] = get_bits(gb, 4);

        if (coup->type[c] == TYPE_CPE) {

            coup->ch_select[c] = get_bits(gb, 2);

            if (coup->ch_select[c] == 3)

                num_gain++;

        } else

            coup->ch_select[c] = 1;

    }

    coup->coupling_point += get_bits1(gb);



    if (coup->coupling_point == 2) {

        av_log(ac->avccontext, AV_LOG_ERROR,

            "Independently switched CCE with 'invalid' domain signalled.\n");

        memset(coup, 0, sizeof(ChannelCoupling));

        return -1;

    }



    sign = get_bits(gb, 1);

    scale = pow(2., pow(2., (int)get_bits(gb, 2) - 3));



    if ((ret = decode_ics(ac, sce, gb, 0, 0)))

        return ret;



    for (c = 0; c < num_gain; c++) {

        int cge = 1;

        int gain = 0;

        float gain_cache = 1.;

        if (c) {

            cge = coup->coupling_point == AFTER_IMDCT ? 1 : get_bits1(gb);

            gain = cge ? get_vlc2(gb, vlc_scalefactors.table, 7, 3) - 60: 0;

            gain_cache = pow(scale, gain);

        }

        for (g = 0; g < sce->ics.num_window_groups; g++) {

            for (sfb = 0; sfb < sce->ics.max_sfb; sfb++, idx++) {

                if (sce->band_type[idx] != ZERO_BT) {

                    if (!cge) {

                        int t = get_vlc2(gb, vlc_scalefactors.table, 7, 3) - 60;

                        if (t) {

                            int s = 1;

                            if (sign) {

                                s  -= 2 * (t & 0x1);

                                t >>= 1;

                            }

                            gain += t;

                            gain_cache = pow(scale, gain) * s;

                        }

                    }

                    coup->gain[c][idx] = gain_cache;

                }

            }

        }

    }

    return 0;

}

