static int a64multi_encode_frame(AVCodecContext *avctx, AVPacket *pkt,

                                 const AVFrame *pict, int *got_packet)

{

    A64Context *c = avctx->priv_data;

    AVFrame *const p = (AVFrame *) & c->picture;



    int frame;

    int x, y;

    int b_height;

    int b_width;



    int req_size, ret;

    uint8_t *buf;



    int *charmap     = c->mc_charmap;

    uint8_t *colram  = c->mc_colram;

    uint8_t *charset = c->mc_charset;

    int *meta        = c->mc_meta_charset;

    int *best_cb     = c->mc_best_cb;



    int charset_size = 0x800 * (INTERLACED + 1);

    int colram_size  = 0x100 * c->mc_use_5col;

    int screen_size;



    if(CROP_SCREENS) {

        b_height = FFMIN(avctx->height,C64YRES) >> 3;

        b_width  = FFMIN(avctx->width ,C64XRES) >> 3;

        screen_size = b_width * b_height;

    } else {

        b_height = C64YRES >> 3;

        b_width  = C64XRES >> 3;

        screen_size = 0x400;

    }



    /* no data, means end encoding asap */

    if (!pict) {

        /* all done, end encoding */

        if (!c->mc_lifetime) return 0;

        /* no more frames in queue, prepare to flush remaining frames */

        if (!c->mc_frame_counter) {

            c->mc_lifetime = 0;

        }

        /* still frames in queue so limit lifetime to remaining frames */

        else c->mc_lifetime = c->mc_frame_counter;

    /* still new data available */

    } else {

        /* fill up mc_meta_charset with data until lifetime exceeds */

        if (c->mc_frame_counter < c->mc_lifetime) {

            *p = *pict;

            p->pict_type = AV_PICTURE_TYPE_I;

            p->key_frame = 1;

            to_meta_with_crop(avctx, p, meta + 32000 * c->mc_frame_counter);

            c->mc_frame_counter++;

            if (c->next_pts == AV_NOPTS_VALUE)

                c->next_pts = pict->pts;

            /* lifetime is not reached so wait for next frame first */

            return 0;

        }

    }



    /* lifetime reached so now convert X frames at once */

    if (c->mc_frame_counter == c->mc_lifetime) {

        req_size = 0;

        /* any frames to encode? */

        if (c->mc_lifetime) {

            req_size = charset_size + c->mc_lifetime*(screen_size + colram_size);

            if ((ret = ff_alloc_packet(pkt, req_size)) < 0) {

                av_log(avctx, AV_LOG_ERROR, "Error getting output packet of size %d.\n", req_size);

                return ret;

            }

            buf = pkt->data;



            /* calc optimal new charset + charmaps */

            ff_init_elbg(meta, 32, 1000 * c->mc_lifetime, best_cb, CHARSET_CHARS, 50, charmap, &c->randctx);

            ff_do_elbg  (meta, 32, 1000 * c->mc_lifetime, best_cb, CHARSET_CHARS, 50, charmap, &c->randctx);



            /* create colorram map and a c64 readable charset */

            render_charset(avctx, charset, colram);



            /* copy charset to buf */

            memcpy(buf, charset, charset_size);



            /* advance pointers */

            buf      += charset_size;

            charset  += charset_size;

        }



        /* write x frames to buf */

        for (frame = 0; frame < c->mc_lifetime; frame++) {

            /* copy charmap to buf. buf is uchar*, charmap is int*, so no memcpy here, sorry */

            for (y = 0; y < b_height; y++) {

                for (x = 0; x < b_width; x++) {

                    buf[y * b_width + x] = charmap[y * b_width + x];

                }

            }

            /* advance pointers */

            buf += screen_size;

            req_size += screen_size;



            /* compress and copy colram to buf */

            if (c->mc_use_5col) {

                a64_compress_colram(buf, charmap, colram);

                /* advance pointers */

                buf += colram_size;

                req_size += colram_size;

            }



            /* advance to next charmap */

            charmap += 1000;

        }



        AV_WB32(avctx->extradata + 4,  c->mc_frame_counter);

        AV_WB32(avctx->extradata + 8,  charset_size);

        AV_WB32(avctx->extradata + 12, screen_size + colram_size);



        /* reset counter */

        c->mc_frame_counter = 0;



        pkt->pts = pkt->dts = c->next_pts;

        c->next_pts         = AV_NOPTS_VALUE;



        pkt->size   = req_size;

        pkt->flags |= AV_PKT_FLAG_KEY;

        *got_packet = !!req_size;

    }

    return 0;

}

static av_always_inline void MPV_motion_internal(MpegEncContext *s,

                              uint8_t *dest_y, uint8_t *dest_cb,

                              uint8_t *dest_cr, int dir,

                              uint8_t **ref_picture,

                              op_pixels_func (*pix_op)[4],

                              qpel_mc_func (*qpix_op)[16], int is_mpeg12)

{

    int dxy, mx, my, src_x, src_y, motion_x, motion_y;

    int mb_x, mb_y, i;

    uint8_t *ptr, *dest;



    mb_x = s->mb_x;

    mb_y = s->mb_y;



    prefetch_motion(s, ref_picture, dir);



    if(!is_mpeg12 && s->obmc && s->pict_type != AV_PICTURE_TYPE_B){

        LOCAL_ALIGNED_8(int16_t, mv_cache, [4], [4][2]);

        Picture *cur_frame = &s->current_picture;

        const int xy= s->mb_x + s->mb_y*s->mb_stride;

        const int mot_stride= s->b8_stride;

        const int mot_xy= mb_x*2 + mb_y*2*mot_stride;



        av_assert2(!s->mb_skipped);



        AV_COPY32(mv_cache[1][1], cur_frame->motion_val[0][mot_xy    ]);

        AV_COPY32(mv_cache[1][2], cur_frame->motion_val[0][mot_xy + 1]);



        AV_COPY32(mv_cache[2][1], cur_frame->motion_val[0][mot_xy + mot_stride    ]);

        AV_COPY32(mv_cache[2][2], cur_frame->motion_val[0][mot_xy + mot_stride + 1]);



        AV_COPY32(mv_cache[3][1], cur_frame->motion_val[0][mot_xy + mot_stride    ]);

        AV_COPY32(mv_cache[3][2], cur_frame->motion_val[0][mot_xy + mot_stride + 1]);



        if (mb_y == 0 || IS_INTRA(cur_frame->mb_type[xy - s->mb_stride])) {

            AV_COPY32(mv_cache[0][1], mv_cache[1][1]);

            AV_COPY32(mv_cache[0][2], mv_cache[1][2]);

        }else{

            AV_COPY32(mv_cache[0][1], cur_frame->motion_val[0][mot_xy - mot_stride    ]);

            AV_COPY32(mv_cache[0][2], cur_frame->motion_val[0][mot_xy - mot_stride + 1]);

        }



        if (mb_x == 0 || IS_INTRA(cur_frame->mb_type[xy - 1])) {

            AV_COPY32(mv_cache[1][0], mv_cache[1][1]);

            AV_COPY32(mv_cache[2][0], mv_cache[2][1]);

        }else{

            AV_COPY32(mv_cache[1][0], cur_frame->motion_val[0][mot_xy - 1]);

            AV_COPY32(mv_cache[2][0], cur_frame->motion_val[0][mot_xy - 1 + mot_stride]);

        }



        if (mb_x + 1 >= s->mb_width || IS_INTRA(cur_frame->mb_type[xy + 1])) {

            AV_COPY32(mv_cache[1][3], mv_cache[1][2]);

            AV_COPY32(mv_cache[2][3], mv_cache[2][2]);

        }else{

            AV_COPY32(mv_cache[1][3], cur_frame->motion_val[0][mot_xy + 2]);

            AV_COPY32(mv_cache[2][3], cur_frame->motion_val[0][mot_xy + 2 + mot_stride]);

        }



        mx = 0;

        my = 0;

        for(i=0;i<4;i++) {

            const int x= (i&1)+1;

            const int y= (i>>1)+1;

            int16_t mv[5][2]= {

                {mv_cache[y][x  ][0], mv_cache[y][x  ][1]},

                {mv_cache[y-1][x][0], mv_cache[y-1][x][1]},

                {mv_cache[y][x-1][0], mv_cache[y][x-1][1]},

                {mv_cache[y][x+1][0], mv_cache[y][x+1][1]},

                {mv_cache[y+1][x][0], mv_cache[y+1][x][1]}};

            //FIXME cleanup

            obmc_motion(s, dest_y + ((i & 1) * 8) + (i >> 1) * 8 * s->linesize,

                        ref_picture[0],

                        mb_x * 16 + (i & 1) * 8, mb_y * 16 + (i >>1) * 8,

                        pix_op[1],

                        mv);



            mx += mv[0][0];

            my += mv[0][1];

        }

        if(!CONFIG_GRAY || !(s->flags&CODEC_FLAG_GRAY))

            chroma_4mv_motion(s, dest_cb, dest_cr, ref_picture, pix_op[1], mx, my);



        return;

    }



    switch(s->mv_type) {

    case MV_TYPE_16X16:

        if(s->mcsel){

            if(s->real_sprite_warping_points==1){

                gmc1_motion(s, dest_y, dest_cb, dest_cr,

                            ref_picture);

            }else{

                gmc_motion(s, dest_y, dest_cb, dest_cr,

                            ref_picture);

            }

        }else if(!is_mpeg12 && s->quarter_sample){

            qpel_motion(s, dest_y, dest_cb, dest_cr,

                        0, 0, 0,

                        ref_picture, pix_op, qpix_op,

                        s->mv[dir][0][0], s->mv[dir][0][1], 16);

        } else if (!is_mpeg12 && (CONFIG_WMV2_DECODER || CONFIG_WMV2_ENCODER) &&

                   s->mspel && s->codec_id == AV_CODEC_ID_WMV2) {

            ff_mspel_motion(s, dest_y, dest_cb, dest_cr,

                        ref_picture, pix_op,

                        s->mv[dir][0][0], s->mv[dir][0][1], 16);

        }else

        {

            mpeg_motion(s, dest_y, dest_cb, dest_cr, 0,

                        ref_picture, pix_op,

                        s->mv[dir][0][0], s->mv[dir][0][1], 16, mb_y);

        }

        break;

    case MV_TYPE_8X8:

    if (!is_mpeg12) {

        mx = 0;

        my = 0;

        if(s->quarter_sample){

            for(i=0;i<4;i++) {

                motion_x = s->mv[dir][i][0];

                motion_y = s->mv[dir][i][1];



                dxy = ((motion_y & 3) << 2) | (motion_x & 3);

                src_x = mb_x * 16 + (motion_x >> 2) + (i & 1) * 8;

                src_y = mb_y * 16 + (motion_y >> 2) + (i >>1) * 8;



                /* WARNING: do no forget half pels */

                src_x = av_clip(src_x, -16, s->width);

                if (src_x == s->width)

                    dxy &= ~3;

                src_y = av_clip(src_y, -16, s->height);

                if (src_y == s->height)

                    dxy &= ~12;



                ptr = ref_picture[0] + (src_y * s->linesize) + (src_x);

                if(s->flags&CODEC_FLAG_EMU_EDGE){

                    if(   (unsigned)src_x > FFMAX(s->h_edge_pos - (motion_x&3) - 8, 0)

                       || (unsigned)src_y > FFMAX(s->v_edge_pos - (motion_y&3) - 8, 0)){

                        s->vdsp.emulated_edge_mc(s->edge_emu_buffer, ptr,

                                            s->linesize, 9, 9,

                                            src_x, src_y,

                                            s->h_edge_pos, s->v_edge_pos);

                        ptr= s->edge_emu_buffer;

                    }

                }

                dest = dest_y + ((i & 1) * 8) + (i >> 1) * 8 * s->linesize;

                qpix_op[1][dxy](dest, ptr, s->linesize);



                mx += s->mv[dir][i][0]/2;

                my += s->mv[dir][i][1]/2;

            }

        }else{

            for(i=0;i<4;i++) {

                hpel_motion(s, dest_y + ((i & 1) * 8) + (i >> 1) * 8 * s->linesize,

                            ref_picture[0],

                            mb_x * 16 + (i & 1) * 8, mb_y * 16 + (i >>1) * 8,

                            pix_op[1],

                            s->mv[dir][i][0], s->mv[dir][i][1]);



                mx += s->mv[dir][i][0];

                my += s->mv[dir][i][1];

            }

        }



        if(!CONFIG_GRAY || !(s->flags&CODEC_FLAG_GRAY))

            chroma_4mv_motion(s, dest_cb, dest_cr, ref_picture, pix_op[1], mx, my);

    }

        break;

    case MV_TYPE_FIELD:

        if (s->picture_structure == PICT_FRAME) {

            if(!is_mpeg12 && s->quarter_sample){

                for(i=0; i<2; i++){

                    qpel_motion(s, dest_y, dest_cb, dest_cr,

                                1, i, s->field_select[dir][i],

                                ref_picture, pix_op, qpix_op,

                                s->mv[dir][i][0], s->mv[dir][i][1], 8);

                }

            }else{

                /* top field */

                mpeg_motion_field(s, dest_y, dest_cb, dest_cr,

                                  0, s->field_select[dir][0],

                                  ref_picture, pix_op,

                                  s->mv[dir][0][0], s->mv[dir][0][1], 8, mb_y);

                /* bottom field */

                mpeg_motion_field(s, dest_y, dest_cb, dest_cr,

                                  1, s->field_select[dir][1],

                                  ref_picture, pix_op,

                                  s->mv[dir][1][0], s->mv[dir][1][1], 8, mb_y);

            }

        } else {

            if(s->picture_structure != s->field_select[dir][0] + 1 && s->pict_type != AV_PICTURE_TYPE_B && !s->first_field){

                ref_picture = s->current_picture_ptr->f.data;

            }



            mpeg_motion(s, dest_y, dest_cb, dest_cr,

                        s->field_select[dir][0],

                        ref_picture, pix_op,

                        s->mv[dir][0][0], s->mv[dir][0][1], 16, mb_y>>1);

        }

        break;

    case MV_TYPE_16X8:

        for(i=0; i<2; i++){

            uint8_t ** ref2picture;



            if(s->picture_structure == s->field_select[dir][i] + 1

               || s->pict_type == AV_PICTURE_TYPE_B || s->first_field){

                ref2picture= ref_picture;

            }else{

                ref2picture = s->current_picture_ptr->f.data;

            }



            mpeg_motion(s, dest_y, dest_cb, dest_cr,

                        s->field_select[dir][i],

                        ref2picture, pix_op,

                        s->mv[dir][i][0], s->mv[dir][i][1] + 16*i, 8, mb_y>>1);



            dest_y += 16*s->linesize;

            dest_cb+= (16>>s->chroma_y_shift)*s->uvlinesize;

            dest_cr+= (16>>s->chroma_y_shift)*s->uvlinesize;

        }

        break;

    case MV_TYPE_DMV:

        if(s->picture_structure == PICT_FRAME){

            for(i=0; i<2; i++){

                int j;

                for(j=0; j<2; j++){

                    mpeg_motion_field(s, dest_y, dest_cb, dest_cr,

                                      j, j^i, ref_picture, pix_op,

                                      s->mv[dir][2*i + j][0],

                                      s->mv[dir][2*i + j][1], 8, mb_y);

                }

                pix_op = s->hdsp.avg_pixels_tab;

            }

        }else{

            for(i=0; i<2; i++){

                mpeg_motion(s, dest_y, dest_cb, dest_cr,

                            s->picture_structure != i+1,

                            ref_picture, pix_op,

                            s->mv[dir][2*i][0],s->mv[dir][2*i][1],16, mb_y>>1);



                // after put we make avg of the same block

                pix_op=s->hdsp.avg_pixels_tab;



                //opposite parity is always in the same frame if this is second field

                if(!s->first_field){

                    ref_picture = s->current_picture_ptr->f.data;

                }

            }

        }

    break;

    default: av_assert2(0);

    }

}

int ff_h264_decode_mb_cabac(H264Context *h) {

    MpegEncContext * const s = &h->s;

    int mb_xy;

    int mb_type, partition_count, cbp = 0;

    int dct8x8_allowed= h->pps.transform_8x8_mode;

    int decode_chroma = h->sps.chroma_format_idc == 1 || h->sps.chroma_format_idc == 2;

    const int pixel_shift = h->pixel_shift;



    mb_xy = h->mb_xy = s->mb_x + s->mb_y*s->mb_stride;



    tprintf(s->avctx, "pic:%d mb:%d/%d\n", h->frame_num, s->mb_x, s->mb_y);

    if( h->slice_type_nos != AV_PICTURE_TYPE_I ) {

        int skip;

        /* a skipped mb needs the aff flag from the following mb */

        if( FRAME_MBAFF && (s->mb_y&1)==1 && h->prev_mb_skipped )

            skip = h->next_mb_skipped;

        else

            skip = decode_cabac_mb_skip( h, s->mb_x, s->mb_y );

        /* read skip flags */

        if( skip ) {

            if( FRAME_MBAFF && (s->mb_y&1)==0 ){

                s->current_picture.f.mb_type[mb_xy] = MB_TYPE_SKIP;

                h->next_mb_skipped = decode_cabac_mb_skip( h, s->mb_x, s->mb_y+1 );

                if(!h->next_mb_skipped)

                    h->mb_mbaff = h->mb_field_decoding_flag = decode_cabac_field_decoding_flag(h);

            }



            decode_mb_skip(h);



            h->cbp_table[mb_xy] = 0;

            h->chroma_pred_mode_table[mb_xy] = 0;

            h->last_qscale_diff = 0;



            return 0;



        }

    }

    if(FRAME_MBAFF){

        if( (s->mb_y&1) == 0 )

            h->mb_mbaff =

            h->mb_field_decoding_flag = decode_cabac_field_decoding_flag(h);

    }



    h->prev_mb_skipped = 0;



    fill_decode_neighbors(h, -(MB_FIELD));



    if( h->slice_type_nos == AV_PICTURE_TYPE_B ) {

        int ctx = 0;

        assert(h->slice_type_nos == AV_PICTURE_TYPE_B);



        if( !IS_DIRECT( h->left_type[LTOP]-1 ) )

            ctx++;

        if( !IS_DIRECT( h->top_type-1 ) )

            ctx++;



        if( !get_cabac_noinline( &h->cabac, &h->cabac_state[27+ctx] ) ){

            mb_type= 0; /* B_Direct_16x16 */

        }else if( !get_cabac_noinline( &h->cabac, &h->cabac_state[27+3] ) ) {

            mb_type= 1 + get_cabac_noinline( &h->cabac, &h->cabac_state[27+5] ); /* B_L[01]_16x16 */

        }else{

            int bits;

            bits = get_cabac_noinline( &h->cabac, &h->cabac_state[27+4] ) << 3;

            bits+= get_cabac_noinline( &h->cabac, &h->cabac_state[27+5] ) << 2;

            bits+= get_cabac_noinline( &h->cabac, &h->cabac_state[27+5] ) << 1;

            bits+= get_cabac_noinline( &h->cabac, &h->cabac_state[27+5] );

            if( bits < 8 ){

                mb_type= bits + 3; /* B_Bi_16x16 through B_L1_L0_16x8 */

            }else if( bits == 13 ){

                mb_type= decode_cabac_intra_mb_type(h, 32, 0);

                goto decode_intra_mb;

            }else if( bits == 14 ){

                mb_type= 11; /* B_L1_L0_8x16 */

            }else if( bits == 15 ){

                mb_type= 22; /* B_8x8 */

            }else{

                bits= ( bits<<1 ) + get_cabac_noinline( &h->cabac, &h->cabac_state[27+5] );

                mb_type= bits - 4; /* B_L0_Bi_* through B_Bi_Bi_* */

            }

        }

            partition_count= b_mb_type_info[mb_type].partition_count;

            mb_type=         b_mb_type_info[mb_type].type;

    } else if( h->slice_type_nos == AV_PICTURE_TYPE_P ) {

        if( get_cabac_noinline( &h->cabac, &h->cabac_state[14] ) == 0 ) {

            /* P-type */

            if( get_cabac_noinline( &h->cabac, &h->cabac_state[15] ) == 0 ) {

                /* P_L0_D16x16, P_8x8 */

                mb_type= 3 * get_cabac_noinline( &h->cabac, &h->cabac_state[16] );

            } else {

                /* P_L0_D8x16, P_L0_D16x8 */

                mb_type= 2 - get_cabac_noinline( &h->cabac, &h->cabac_state[17] );

            }

            partition_count= p_mb_type_info[mb_type].partition_count;

            mb_type=         p_mb_type_info[mb_type].type;

        } else {

            mb_type= decode_cabac_intra_mb_type(h, 17, 0);

            goto decode_intra_mb;

        }

    } else {

        mb_type= decode_cabac_intra_mb_type(h, 3, 1);

        if(h->slice_type == AV_PICTURE_TYPE_SI && mb_type)

            mb_type--;

        assert(h->slice_type_nos == AV_PICTURE_TYPE_I);

decode_intra_mb:

        partition_count = 0;

        cbp= i_mb_type_info[mb_type].cbp;

        h->intra16x16_pred_mode= i_mb_type_info[mb_type].pred_mode;

        mb_type= i_mb_type_info[mb_type].type;

    }

    if(MB_FIELD)

        mb_type |= MB_TYPE_INTERLACED;



    h->slice_table[ mb_xy ]= h->slice_num;



    if(IS_INTRA_PCM(mb_type)) {

        static const uint16_t mb_sizes[4] = {256,384,512,768};

        const int mb_size = mb_sizes[h->sps.chroma_format_idc]*h->sps.bit_depth_luma >> 3;

        const uint8_t *ptr;



        // We assume these blocks are very rare so we do not optimize it.

        // FIXME The two following lines get the bitstream position in the cabac

        // decode, I think it should be done by a function in cabac.h (or cabac.c).

        ptr= h->cabac.bytestream;

        if(h->cabac.low&0x1) ptr--;

        if(CABAC_BITS==16){

            if(h->cabac.low&0x1FF) ptr--;

        }



        // The pixels are stored in the same order as levels in h->mb array.



        memcpy(h->mb, ptr, mb_size); ptr+=mb_size;



        ff_init_cabac_decoder(&h->cabac, ptr, h->cabac.bytestream_end - ptr);



        // All blocks are present

        h->cbp_table[mb_xy] = 0xf7ef;

        h->chroma_pred_mode_table[mb_xy] = 0;

        // In deblocking, the quantizer is 0

        s->current_picture.f.qscale_table[mb_xy] = 0;

        // All coeffs are present

        memset(h->non_zero_count[mb_xy], 16, 48);

        s->current_picture.f.mb_type[mb_xy] = mb_type;

        h->last_qscale_diff = 0;

        return 0;

    }



    if(MB_MBAFF){

        h->ref_count[0] <<= 1;

        h->ref_count[1] <<= 1;

    }



    fill_decode_caches(h, mb_type);



    if( IS_INTRA( mb_type ) ) {

        int i, pred_mode;

        if( IS_INTRA4x4( mb_type ) ) {

            if( dct8x8_allowed && get_cabac_noinline( &h->cabac, &h->cabac_state[399 + h->neighbor_transform_size] ) ) {

                mb_type |= MB_TYPE_8x8DCT;

                for( i = 0; i < 16; i+=4 ) {

                    int pred = pred_intra_mode( h, i );

                    int mode = decode_cabac_mb_intra4x4_pred_mode( h, pred );

                    fill_rectangle( &h->intra4x4_pred_mode_cache[ scan8[i] ], 2, 2, 8, mode, 1 );

                }

            } else {

                for( i = 0; i < 16; i++ ) {

                    int pred = pred_intra_mode( h, i );

                    h->intra4x4_pred_mode_cache[ scan8[i] ] = decode_cabac_mb_intra4x4_pred_mode( h, pred );



                //av_log( s->avctx, AV_LOG_ERROR, "i4x4 pred=%d mode=%d\n", pred, h->intra4x4_pred_mode_cache[ scan8[i] ] );

                }

            }

            write_back_intra_pred_mode(h);

            if( ff_h264_check_intra4x4_pred_mode(h) < 0 ) return -1;

        } else {

            h->intra16x16_pred_mode= ff_h264_check_intra_pred_mode( h, h->intra16x16_pred_mode, 0 );

            if( h->intra16x16_pred_mode < 0 ) return -1;

        }

        if(decode_chroma){

            h->chroma_pred_mode_table[mb_xy] =

            pred_mode                        = decode_cabac_mb_chroma_pre_mode( h );



            pred_mode= ff_h264_check_intra_pred_mode( h, pred_mode, 1 );

            if( pred_mode < 0 ) return -1;

            h->chroma_pred_mode= pred_mode;

        } else {

            h->chroma_pred_mode= DC_128_PRED8x8;

        }

    } else if( partition_count == 4 ) {

        int i, j, sub_partition_count[4], list, ref[2][4];



        if( h->slice_type_nos == AV_PICTURE_TYPE_B ) {

            for( i = 0; i < 4; i++ ) {

                h->sub_mb_type[i] = decode_cabac_b_mb_sub_type( h );

                sub_partition_count[i]= b_sub_mb_type_info[ h->sub_mb_type[i] ].partition_count;

                h->sub_mb_type[i]=      b_sub_mb_type_info[ h->sub_mb_type[i] ].type;

            }

            if( IS_DIRECT(h->sub_mb_type[0] | h->sub_mb_type[1] |

                          h->sub_mb_type[2] | h->sub_mb_type[3]) ) {

                ff_h264_pred_direct_motion(h, &mb_type);

                h->ref_cache[0][scan8[4]] =

                h->ref_cache[1][scan8[4]] =

                h->ref_cache[0][scan8[12]] =

                h->ref_cache[1][scan8[12]] = PART_NOT_AVAILABLE;

                    for( i = 0; i < 4; i++ )

                        fill_rectangle( &h->direct_cache[scan8[4*i]], 2, 2, 8, (h->sub_mb_type[i]>>1)&0xFF, 1 );

            }

        } else {

            for( i = 0; i < 4; i++ ) {

                h->sub_mb_type[i] = decode_cabac_p_mb_sub_type( h );

                sub_partition_count[i]= p_sub_mb_type_info[ h->sub_mb_type[i] ].partition_count;

                h->sub_mb_type[i]=      p_sub_mb_type_info[ h->sub_mb_type[i] ].type;

            }

        }



        for( list = 0; list < h->list_count; list++ ) {

                for( i = 0; i < 4; i++ ) {

                    if(IS_DIRECT(h->sub_mb_type[i])) continue;

                    if(IS_DIR(h->sub_mb_type[i], 0, list)){

                        if( h->ref_count[list] > 1 ){

                            ref[list][i] = decode_cabac_mb_ref( h, list, 4*i );

                            if(ref[list][i] >= (unsigned)h->ref_count[list]){

                                av_log(s->avctx, AV_LOG_ERROR, "Reference %d >= %d\n", ref[list][i], h->ref_count[list]);


                            }

                        }else

                            ref[list][i] = 0;

                    } else {

                        ref[list][i] = -1;

                    }

                                                       h->ref_cache[list][ scan8[4*i]+1 ]=

                    h->ref_cache[list][ scan8[4*i]+8 ]=h->ref_cache[list][ scan8[4*i]+9 ]= ref[list][i];

                }

        }



        if(dct8x8_allowed)

            dct8x8_allowed = get_dct8x8_allowed(h);



        for(list=0; list<h->list_count; list++){

            for(i=0; i<4; i++){

                h->ref_cache[list][ scan8[4*i]   ]=h->ref_cache[list][ scan8[4*i]+1 ];

                if(IS_DIRECT(h->sub_mb_type[i])){

                    fill_rectangle(h->mvd_cache[list][scan8[4*i]], 2, 2, 8, 0, 2);

                    continue;

                }



                if(IS_DIR(h->sub_mb_type[i], 0, list) && !IS_DIRECT(h->sub_mb_type[i])){

                    const int sub_mb_type= h->sub_mb_type[i];

                    const int block_width= (sub_mb_type & (MB_TYPE_16x16|MB_TYPE_16x8)) ? 2 : 1;

                    for(j=0; j<sub_partition_count[i]; j++){

                        int mpx, mpy;

                        int mx, my;

                        const int index= 4*i + block_width*j;

                        int16_t (* mv_cache)[2]= &h->mv_cache[list][ scan8[index] ];

                        uint8_t (* mvd_cache)[2]= &h->mvd_cache[list][ scan8[index] ];

                        pred_motion(h, index, block_width, list, h->ref_cache[list][ scan8[index] ], &mx, &my);

                        DECODE_CABAC_MB_MVD( h, list, index)

                        tprintf(s->avctx, "final mv:%d %d\n", mx, my);



                        if(IS_SUB_8X8(sub_mb_type)){

                            mv_cache[ 1 ][0]=

                            mv_cache[ 8 ][0]= mv_cache[ 9 ][0]= mx;

                            mv_cache[ 1 ][1]=

                            mv_cache[ 8 ][1]= mv_cache[ 9 ][1]= my;



                            mvd_cache[ 1 ][0]=

                            mvd_cache[ 8 ][0]= mvd_cache[ 9 ][0]= mpx;

                            mvd_cache[ 1 ][1]=

                            mvd_cache[ 8 ][1]= mvd_cache[ 9 ][1]= mpy;

                        }else if(IS_SUB_8X4(sub_mb_type)){

                            mv_cache[ 1 ][0]= mx;

                            mv_cache[ 1 ][1]= my;



                            mvd_cache[ 1 ][0]=  mpx;

                            mvd_cache[ 1 ][1]= mpy;

                        }else if(IS_SUB_4X8(sub_mb_type)){

                            mv_cache[ 8 ][0]= mx;

                            mv_cache[ 8 ][1]= my;



                            mvd_cache[ 8 ][0]= mpx;

                            mvd_cache[ 8 ][1]= mpy;

                        }

                        mv_cache[ 0 ][0]= mx;

                        mv_cache[ 0 ][1]= my;



                        mvd_cache[ 0 ][0]= mpx;

                        mvd_cache[ 0 ][1]= mpy;

                    }

                }else{

                    fill_rectangle(h->mv_cache [list][ scan8[4*i] ], 2, 2, 8, 0, 4);

                    fill_rectangle(h->mvd_cache[list][ scan8[4*i] ], 2, 2, 8, 0, 2);

                }

            }

        }

    } else if( IS_DIRECT(mb_type) ) {

        ff_h264_pred_direct_motion(h, &mb_type);

        fill_rectangle(h->mvd_cache[0][scan8[0]], 4, 4, 8, 0, 2);

        fill_rectangle(h->mvd_cache[1][scan8[0]], 4, 4, 8, 0, 2);

        dct8x8_allowed &= h->sps.direct_8x8_inference_flag;

    } else {

        int list, i;

        if(IS_16X16(mb_type)){

            for(list=0; list<h->list_count; list++){

                if(IS_DIR(mb_type, 0, list)){

                    int ref;

                    if(h->ref_count[list] > 1){

                        ref= decode_cabac_mb_ref(h, list, 0);

                        if(ref >= (unsigned)h->ref_count[list]){

                            av_log(s->avctx, AV_LOG_ERROR, "Reference %d >= %d\n", ref, h->ref_count[list]);


                        }

                    }else

                        ref=0;

                        fill_rectangle(&h->ref_cache[list][ scan8[0] ], 4, 4, 8, ref, 1);

                }

            }

            for(list=0; list<h->list_count; list++){

                if(IS_DIR(mb_type, 0, list)){

                    int mx,my,mpx,mpy;

                    pred_motion(h, 0, 4, list, h->ref_cache[list][ scan8[0] ], &mx, &my);

                    DECODE_CABAC_MB_MVD( h, list, 0)

                    tprintf(s->avctx, "final mv:%d %d\n", mx, my);



                    fill_rectangle(h->mvd_cache[list][ scan8[0] ], 4, 4, 8, pack8to16(mpx,mpy), 2);

                    fill_rectangle(h->mv_cache[list][ scan8[0] ], 4, 4, 8, pack16to32(mx,my), 4);

                }

            }

        }

        else if(IS_16X8(mb_type)){

            for(list=0; list<h->list_count; list++){

                    for(i=0; i<2; i++){

                        if(IS_DIR(mb_type, i, list)){

                            int ref;

                            if(h->ref_count[list] > 1){

                                ref= decode_cabac_mb_ref( h, list, 8*i );

                                if(ref >= (unsigned)h->ref_count[list]){

                                    av_log(s->avctx, AV_LOG_ERROR, "Reference %d >= %d\n", ref, h->ref_count[list]);


                                }

                            }else

                                ref=0;

                            fill_rectangle(&h->ref_cache[list][ scan8[0] + 16*i ], 4, 2, 8, ref, 1);

                        }else

                            fill_rectangle(&h->ref_cache[list][ scan8[0] + 16*i ], 4, 2, 8, (LIST_NOT_USED&0xFF), 1);

                    }

            }

            for(list=0; list<h->list_count; list++){

                for(i=0; i<2; i++){

                    if(IS_DIR(mb_type, i, list)){

                        int mx,my,mpx,mpy;

                        pred_16x8_motion(h, 8*i, list, h->ref_cache[list][scan8[0] + 16*i], &mx, &my);

                        DECODE_CABAC_MB_MVD( h, list, 8*i)

                        tprintf(s->avctx, "final mv:%d %d\n", mx, my);



                        fill_rectangle(h->mvd_cache[list][ scan8[0] + 16*i ], 4, 2, 8, pack8to16(mpx,mpy), 2);

                        fill_rectangle(h->mv_cache[list][ scan8[0] + 16*i ], 4, 2, 8, pack16to32(mx,my), 4);

                    }else{

                        fill_rectangle(h->mvd_cache[list][ scan8[0] + 16*i ], 4, 2, 8, 0, 2);

                        fill_rectangle(h-> mv_cache[list][ scan8[0] + 16*i ], 4, 2, 8, 0, 4);

                    }

                }

            }

        }else{

            assert(IS_8X16(mb_type));

            for(list=0; list<h->list_count; list++){

                    for(i=0; i<2; i++){

                        if(IS_DIR(mb_type, i, list)){ //FIXME optimize

                            int ref;

                            if(h->ref_count[list] > 1){

                                ref= decode_cabac_mb_ref( h, list, 4*i );

                                if(ref >= (unsigned)h->ref_count[list]){

                                    av_log(s->avctx, AV_LOG_ERROR, "Reference %d >= %d\n", ref, h->ref_count[list]);


                                }

                            }else

                                ref=0;

                            fill_rectangle(&h->ref_cache[list][ scan8[0] + 2*i ], 2, 4, 8, ref, 1);

                        }else

                            fill_rectangle(&h->ref_cache[list][ scan8[0] + 2*i ], 2, 4, 8, (LIST_NOT_USED&0xFF), 1);

                    }

            }

            for(list=0; list<h->list_count; list++){

                for(i=0; i<2; i++){

                    if(IS_DIR(mb_type, i, list)){

                        int mx,my,mpx,mpy;

                        pred_8x16_motion(h, i*4, list, h->ref_cache[list][ scan8[0] + 2*i ], &mx, &my);

                        DECODE_CABAC_MB_MVD( h, list, 4*i)



                        tprintf(s->avctx, "final mv:%d %d\n", mx, my);

                        fill_rectangle(h->mvd_cache[list][ scan8[0] + 2*i ], 2, 4, 8, pack8to16(mpx,mpy), 2);

                        fill_rectangle(h->mv_cache[list][ scan8[0] + 2*i ], 2, 4, 8, pack16to32(mx,my), 4);

                    }else{

                        fill_rectangle(h->mvd_cache[list][ scan8[0] + 2*i ], 2, 4, 8, 0, 2);

                        fill_rectangle(h-> mv_cache[list][ scan8[0] + 2*i ], 2, 4, 8, 0, 4);

                    }

                }

            }

        }

    }



   if( IS_INTER( mb_type ) ) {

        h->chroma_pred_mode_table[mb_xy] = 0;

        write_back_motion( h, mb_type );

   }



    if( !IS_INTRA16x16( mb_type ) ) {

        cbp  = decode_cabac_mb_cbp_luma( h );

        if(decode_chroma)

            cbp |= decode_cabac_mb_cbp_chroma( h ) << 4;

    }



    h->cbp_table[mb_xy] = h->cbp = cbp;



    if( dct8x8_allowed && (cbp&15) && !IS_INTRA( mb_type ) ) {

        mb_type |= MB_TYPE_8x8DCT * get_cabac_noinline( &h->cabac, &h->cabac_state[399 + h->neighbor_transform_size] );

    }



    /* It would be better to do this in fill_decode_caches, but we don't know

     * the transform mode of the current macroblock there. */

    if (CHROMA444 && IS_8x8DCT(mb_type)){

        int i;

        uint8_t *nnz_cache = h->non_zero_count_cache;

        for (i = 0; i < 2; i++){

            if (h->left_type[LEFT(i)] && !IS_8x8DCT(h->left_type[LEFT(i)])){

                nnz_cache[3+8* 1 + 2*8*i]=

                nnz_cache[3+8* 2 + 2*8*i]=

                nnz_cache[3+8* 6 + 2*8*i]=

                nnz_cache[3+8* 7 + 2*8*i]=

                nnz_cache[3+8*11 + 2*8*i]=

                nnz_cache[3+8*12 + 2*8*i]= IS_INTRA(mb_type) ? 64 : 0;

            }

        }

        if (h->top_type && !IS_8x8DCT(h->top_type)){

            uint32_t top_empty = CABAC && !IS_INTRA(mb_type) ? 0 : 0x40404040;

            AV_WN32A(&nnz_cache[4+8* 0], top_empty);

            AV_WN32A(&nnz_cache[4+8* 5], top_empty);

            AV_WN32A(&nnz_cache[4+8*10], top_empty);

        }

    }

    s->current_picture.f.mb_type[mb_xy] = mb_type;



    if( cbp || IS_INTRA16x16( mb_type ) ) {

        const uint8_t *scan, *scan8x8;

        const uint32_t *qmul;



        if(IS_INTERLACED(mb_type)){

            scan8x8= s->qscale ? h->field_scan8x8 : h->field_scan8x8_q0;

            scan= s->qscale ? h->field_scan : h->field_scan_q0;

        }else{

            scan8x8= s->qscale ? h->zigzag_scan8x8 : h->zigzag_scan8x8_q0;

            scan= s->qscale ? h->zigzag_scan : h->zigzag_scan_q0;

        }



        // decode_cabac_mb_dqp

        if(get_cabac_noinline( &h->cabac, &h->cabac_state[60 + (h->last_qscale_diff != 0)])){

            int val = 1;

            int ctx= 2;

            const int max_qp = 51 + 6*(h->sps.bit_depth_luma-8);



            while( get_cabac_noinline( &h->cabac, &h->cabac_state[60 + ctx] ) ) {

                ctx= 3;

                val++;

                if(val > 2*max_qp){ //prevent infinite loop

                    av_log(h->s.avctx, AV_LOG_ERROR, "cabac decode of qscale diff failed at %d %d\n", s->mb_x, s->mb_y);


                }

            }



            if( val&0x01 )

                val=   (val + 1)>>1 ;

            else

                val= -((val + 1)>>1);

            h->last_qscale_diff = val;

            s->qscale += val;

            if(((unsigned)s->qscale) > max_qp){

                if(s->qscale<0) s->qscale+= max_qp+1;

                else            s->qscale-= max_qp+1;

            }

            h->chroma_qp[0] = get_chroma_qp(h, 0, s->qscale);

            h->chroma_qp[1] = get_chroma_qp(h, 1, s->qscale);

        }else

            h->last_qscale_diff=0;



        decode_cabac_luma_residual(h, scan, scan8x8, pixel_shift, mb_type, cbp, 0);

        if(CHROMA444){

            decode_cabac_luma_residual(h, scan, scan8x8, pixel_shift, mb_type, cbp, 1);

            decode_cabac_luma_residual(h, scan, scan8x8, pixel_shift, mb_type, cbp, 2);

        } else if (CHROMA422) {

            if( cbp&0x30 ){

                int c;

                for( c = 0; c < 2; c++ ) {

                    //av_log( s->avctx, AV_LOG_ERROR, "INTRA C%d-DC\n",c );

                    decode_cabac_residual_dc_422(h, h->mb + ((256 + 16*16*c) << pixel_shift), 3,

                                                 CHROMA_DC_BLOCK_INDEX + c,

                                                 chroma422_dc_scan, 8);

                }

            }



            if( cbp&0x20 ) {

                int c, i, i8x8;

                for( c = 0; c < 2; c++ ) {

                    DCTELEM *mb = h->mb + (16*(16 + 16*c) << pixel_shift);

                    qmul = h->dequant4_coeff[c+1+(IS_INTRA( mb_type ) ? 0:3)][h->chroma_qp[c]];

                    for (i8x8 = 0; i8x8 < 2; i8x8++) {

                        for (i = 0; i < 4; i++) {

                            const int index = 16 + 16 * c + 8*i8x8 + i;

                            //av_log(s->avctx, AV_LOG_ERROR, "INTRA C%d-AC %d\n",c, index - 16);

                            decode_cabac_residual_nondc(h, mb, 4, index, scan + 1, qmul, 15);

                            mb += 16<<pixel_shift;

                        }

                    }

                }

            } else {

                fill_rectangle(&h->non_zero_count_cache[scan8[16]], 4, 4, 8, 0, 1);

                fill_rectangle(&h->non_zero_count_cache[scan8[32]], 4, 4, 8, 0, 1);

            }

        } else /* yuv420 */ {

            if( cbp&0x30 ){

                int c;

                for( c = 0; c < 2; c++ ) {

                    //av_log( s->avctx, AV_LOG_ERROR, "INTRA C%d-DC\n",c );

                    decode_cabac_residual_dc(h, h->mb + ((256 + 16*16*c) << pixel_shift), 3, CHROMA_DC_BLOCK_INDEX+c, chroma_dc_scan, 4);

                }

            }



            if( cbp&0x20 ) {

                int c, i;

                for( c = 0; c < 2; c++ ) {

                    qmul = h->dequant4_coeff[c+1+(IS_INTRA( mb_type ) ? 0:3)][h->chroma_qp[c]];

                    for( i = 0; i < 4; i++ ) {

                        const int index = 16 + 16 * c + i;

                        //av_log( s->avctx, AV_LOG_ERROR, "INTRA C%d-AC %d\n",c, index - 16 );

                        decode_cabac_residual_nondc(h, h->mb + (16*index << pixel_shift), 4, index, scan + 1, qmul, 15);

                    }

                }

            } else {

                fill_rectangle(&h->non_zero_count_cache[scan8[16]], 4, 4, 8, 0, 1);

                fill_rectangle(&h->non_zero_count_cache[scan8[32]], 4, 4, 8, 0, 1);

            }

        }

    } else {

        fill_rectangle(&h->non_zero_count_cache[scan8[ 0]], 4, 4, 8, 0, 1);

        fill_rectangle(&h->non_zero_count_cache[scan8[16]], 4, 4, 8, 0, 1);

        fill_rectangle(&h->non_zero_count_cache[scan8[32]], 4, 4, 8, 0, 1);

        h->last_qscale_diff = 0;

    }



    s->current_picture.f.qscale_table[mb_xy] = s->qscale;

    write_back_non_zero_count(h);



    if(MB_MBAFF){

        h->ref_count[0] >>= 1;

        h->ref_count[1] >>= 1;

    }



    return 0;

}

static int mov_write_trailer(AVFormatContext *s)

{

    MOVMuxContext *mov = s->priv_data;

    AVIOContext *pb = s->pb;

    int res = 0;

    int i;



    int64_t moov_pos = avio_tell(pb);



    if (!(mov->flags & FF_MOV_FLAG_FRAGMENT)) {

        /* Write size of mdat tag */

        if (mov->mdat_size + 8 <= UINT32_MAX) {

            avio_seek(pb, mov->mdat_pos, SEEK_SET);

            avio_wb32(pb, mov->mdat_size + 8);

        } else {

            /* overwrite 'wide' placeholder atom */

            avio_seek(pb, mov->mdat_pos - 8, SEEK_SET);

            /* special value: real atom size will be 64 bit value after

             * tag field */

            avio_wb32(pb, 1);

            ffio_wfourcc(pb, "mdat");

            avio_wb64(pb, mov->mdat_size + 16);

        }

        avio_seek(pb, mov->reserved_moov_size ? mov->reserved_moov_pos : moov_pos, SEEK_SET);



        mov_write_moov_tag(pb, mov, s);

        if(mov->reserved_moov_size){

            int64_t size=  mov->reserved_moov_size - (avio_tell(pb) - mov->reserved_moov_pos);

            if(size < 8){

                av_log(s, AV_LOG_ERROR, "reserved_moov_size is too small, needed %"PRId64" additional\n", 8-size);

                return -1;

            }

            avio_wb32(pb, size);

            ffio_wfourcc(pb, "free");

            for(i=0; i<size; i++)

                avio_w8(pb, 0);

            avio_seek(pb, moov_pos, SEEK_SET);

        }

    } else {

        mov_flush_fragment(s);

        mov_write_mfra_tag(pb, mov);

    }



    if (mov->chapter_track)

        av_freep(&mov->tracks[mov->chapter_track].enc);



    for (i=0; i<mov->nb_streams; i++) {

        if (mov->tracks[i].tag == MKTAG('r','t','p',' '))

            ff_mov_close_hinting(&mov->tracks[i]);

        else if (mov->tracks[i].tag == MKTAG('t','m','c','d'))

            av_freep(&mov->tracks[i].enc);

        if (mov->flags & FF_MOV_FLAG_FRAGMENT &&

            mov->tracks[i].vc1_info.struct_offset && s->pb->seekable) {

            int64_t off = avio_tell(pb);

            uint8_t buf[7];

            if (mov_write_dvc1_structs(&mov->tracks[i], buf) >= 0) {

                avio_seek(pb, mov->tracks[i].vc1_info.struct_offset, SEEK_SET);

                avio_write(pb, buf, 7);

                avio_seek(pb, off, SEEK_SET);

            }

        }

        av_freep(&mov->tracks[i].cluster);

        av_freep(&mov->tracks[i].frag_info);



        if (mov->tracks[i].vos_len)

            av_free(mov->tracks[i].vos_data);



    }



    avio_flush(pb);



    av_freep(&mov->tracks);



    return res;

}

static void dvbsub_parse_region_segment(AVCodecContext *avctx,

                                        const uint8_t *buf, int buf_size)

{

    DVBSubContext *ctx = avctx->priv_data;



    const uint8_t *buf_end = buf + buf_size;

    int region_id, object_id;

    int av_unused version;

    DVBSubRegion *region;

    DVBSubObject *object;

    DVBSubObjectDisplay *display;

    int fill;



    if (buf_size < 10)




    region_id = *buf++;



    region = get_region(ctx, region_id);



    if (!region) {

        region = av_mallocz(sizeof(DVBSubRegion));





        region->id = region_id;

        region->version = -1;



        region->next = ctx->region_list;

        ctx->region_list = region;

    }



    version = ((*buf)>>4) & 15;

    fill = ((*buf++) >> 3) & 1;



    region->width = AV_RB16(buf);

    buf += 2;

    region->height = AV_RB16(buf);

    buf += 2;



    if (region->width * region->height != region->buf_size) {

        av_free(region->pbuf);



        region->buf_size = region->width * region->height;



        region->pbuf = av_malloc(region->buf_size);



        fill = 1;

        region->dirty = 0;

    }



    region->depth = 1 << (((*buf++) >> 2) & 7);

    if(region->depth<2 || region->depth>8){

        av_log(avctx, AV_LOG_ERROR, "region depth %d is invalid\n", region->depth);

        region->depth= 4;

    }

    region->clut = *buf++;



    if (region->depth == 8) {

        region->bgcolor = *buf++;

        buf += 1;

    } else {

        buf += 1;



        if (region->depth == 4)

            region->bgcolor = (((*buf++) >> 4) & 15);

        else

            region->bgcolor = (((*buf++) >> 2) & 3);

    }



    av_dlog(avctx, "Region %d, (%dx%d)\n", region_id, region->width, region->height);



    if (fill) {

        memset(region->pbuf, region->bgcolor, region->buf_size);

        av_dlog(avctx, "Fill region (%d)\n", region->bgcolor);

    }



    delete_region_display_list(ctx, region);



    while (buf + 5 < buf_end) {

        object_id = AV_RB16(buf);

        buf += 2;



        object = get_object(ctx, object_id);



        if (!object) {

            object = av_mallocz(sizeof(DVBSubObject));



            object->id = object_id;

            object->next = ctx->object_list;

            ctx->object_list = object;

        }



        object->type = (*buf) >> 6;



        display = av_mallocz(sizeof(DVBSubObjectDisplay));



        display->object_id = object_id;

        display->region_id = region_id;



        display->x_pos = AV_RB16(buf) & 0xfff;

        buf += 2;

        display->y_pos = AV_RB16(buf) & 0xfff;

        buf += 2;



        if ((object->type == 1 || object->type == 2) && buf+1 < buf_end) {

            display->fgcolor = *buf++;

            display->bgcolor = *buf++;

        }



        display->region_list_next = region->display_list;

        region->display_list = display;



        display->object_list_next = object->display_list;

        object->display_list = display;

    }

}

static av_cold int adpcm_encode_init(AVCodecContext *avctx)

{

    ADPCMEncodeContext *s = avctx->priv_data;

    uint8_t *extradata;

    int i;

    if (avctx->channels > 2)

        return -1; /* only stereo or mono =) */



    if (avctx->trellis && (unsigned)avctx->trellis > 16U) {

        av_log(avctx, AV_LOG_ERROR, "invalid trellis size\n");

        return -1;

    }



    if (avctx->trellis) {

        int frontier  = 1 << avctx->trellis;

        int max_paths =  frontier * FREEZE_INTERVAL;

        FF_ALLOC_OR_GOTO(avctx, s->paths,

                         max_paths * sizeof(*s->paths), error);

        FF_ALLOC_OR_GOTO(avctx, s->node_buf,

                         2 * frontier * sizeof(*s->node_buf),  error);

        FF_ALLOC_OR_GOTO(avctx, s->nodep_buf,

                         2 * frontier * sizeof(*s->nodep_buf), error);

        FF_ALLOC_OR_GOTO(avctx, s->trellis_hash,

                         65536 * sizeof(*s->trellis_hash), error);

    }



    avctx->bits_per_coded_sample = av_get_bits_per_sample(avctx->codec->id);



    switch (avctx->codec->id) {

    case CODEC_ID_ADPCM_IMA_WAV:

        /* each 16 bits sample gives one nibble

           and we have 4 bytes per channel overhead */

        avctx->frame_size = (BLKSIZE - 4 * avctx->channels) * 8 /

                            (4 * avctx->channels) + 1;

        /* seems frame_size isn't taken into account...

           have to buffer the samples :-( */

        avctx->block_align = BLKSIZE;

        avctx->bits_per_coded_sample = 4;

        break;

    case CODEC_ID_ADPCM_IMA_QT:

        avctx->frame_size  = 64;

        avctx->block_align = 34 * avctx->channels;

        break;

    case CODEC_ID_ADPCM_MS:

        /* each 16 bits sample gives one nibble

           and we have 7 bytes per channel overhead */

        avctx->frame_size = (BLKSIZE - 7 * avctx->channels) * 2 / avctx->channels + 2;

        avctx->block_align = BLKSIZE;

        avctx->bits_per_coded_sample = 4;

        avctx->extradata_size = 32;

        extradata = avctx->extradata = av_malloc(avctx->extradata_size);

        if (!extradata)

            return AVERROR(ENOMEM);

        bytestream_put_le16(&extradata, avctx->frame_size);

        bytestream_put_le16(&extradata, 7); /* wNumCoef */

        for (i = 0; i < 7; i++) {

            bytestream_put_le16(&extradata, ff_adpcm_AdaptCoeff1[i] * 4);

            bytestream_put_le16(&extradata, ff_adpcm_AdaptCoeff2[i] * 4);

        }

        break;

    case CODEC_ID_ADPCM_YAMAHA:

        avctx->frame_size  = BLKSIZE * avctx->channels;

        avctx->block_align = BLKSIZE;

        break;

    case CODEC_ID_ADPCM_SWF:

        if (avctx->sample_rate != 11025 &&

            avctx->sample_rate != 22050 &&

            avctx->sample_rate != 44100) {

            av_log(avctx, AV_LOG_ERROR, "Sample rate must be 11025, "

                   "22050 or 44100\n");

            goto error;

        }

        avctx->frame_size = 512 * (avctx->sample_rate / 11025);

        break;

    default:

        goto error;

    }



    avctx->coded_frame = avcodec_alloc_frame();

    avctx->coded_frame->key_frame= 1;



    return 0;

error:

    av_freep(&s->paths);

    av_freep(&s->node_buf);

    av_freep(&s->nodep_buf);

    av_freep(&s->trellis_hash);

    return -1;

}

static void RENAME(sws_init_swScale)(SwsContext *c)

{

    enum PixelFormat srcFormat = c->srcFormat;



    if (!(c->flags & SWS_BITEXACT)) {

        if (c->flags & SWS_ACCURATE_RND) {

            c->yuv2yuv1     = RENAME(yuv2yuv1_ar    );

            c->yuv2yuvX     = RENAME(yuv2yuvX_ar    );

            switch (c->dstFormat) {

            case PIX_FMT_RGB32:   c->yuv2packedX = RENAME(yuv2rgb32_X_ar);   break;

            case PIX_FMT_BGR24:   c->yuv2packedX = RENAME(yuv2bgr24_X_ar);   break;

            case PIX_FMT_RGB555:  c->yuv2packedX = RENAME(yuv2rgb555_X_ar);  break;

            case PIX_FMT_RGB565:  c->yuv2packedX = RENAME(yuv2rgb565_X_ar);  break;

            case PIX_FMT_YUYV422: c->yuv2packedX = RENAME(yuv2yuyv422_X_ar); break;

            default: break;

            }

        } else {

            c->yuv2yuv1     = RENAME(yuv2yuv1    );

            c->yuv2yuvX     = RENAME(yuv2yuvX    );

            switch (c->dstFormat) {

            case PIX_FMT_RGB32:   c->yuv2packedX = RENAME(yuv2rgb32_X);   break;

            case PIX_FMT_BGR24:   c->yuv2packedX = RENAME(yuv2bgr24_X);   break;

            case PIX_FMT_RGB555:  c->yuv2packedX = RENAME(yuv2rgb555_X);  break;

            case PIX_FMT_RGB565:  c->yuv2packedX = RENAME(yuv2rgb565_X);  break;

            case PIX_FMT_YUYV422: c->yuv2packedX = RENAME(yuv2yuyv422_X); break;

            default: break;

            }

        }

        switch (c->dstFormat) {

        case PIX_FMT_RGB32:

                c->yuv2packed1 = RENAME(yuv2rgb32_1);

                c->yuv2packed2 = RENAME(yuv2rgb32_2);

                break;

        case PIX_FMT_BGR24:

                c->yuv2packed1 = RENAME(yuv2bgr24_1);

                c->yuv2packed2 = RENAME(yuv2bgr24_2);

                break;

        case PIX_FMT_RGB555:

                c->yuv2packed1 = RENAME(yuv2rgb555_1);

                c->yuv2packed2 = RENAME(yuv2rgb555_2);

                break;

        case PIX_FMT_RGB565:

                c->yuv2packed1 = RENAME(yuv2rgb565_1);

                c->yuv2packed2 = RENAME(yuv2rgb565_2);

                break;

        case PIX_FMT_YUYV422:

                c->yuv2packed1 = RENAME(yuv2yuyv422_1);

                c->yuv2packed2 = RENAME(yuv2yuyv422_2);

                break;

        default:

                break;

        }

    }



#if !COMPILE_TEMPLATE_MMX2

    c->hScale       = RENAME(hScale      );

#endif /* !COMPILE_TEMPLATE_MMX2 */



    // Use the new MMX scaler if the MMX2 one can't be used (it is faster than the x86 ASM one).

#if COMPILE_TEMPLATE_MMX2

    if (c->flags & SWS_FAST_BILINEAR && c->canMMX2BeUsed)

    {

        c->hyscale_fast = RENAME(hyscale_fast);

        c->hcscale_fast = RENAME(hcscale_fast);

    } else {

#endif /* COMPILE_TEMPLATE_MMX2 */

        c->hyscale_fast = NULL;

        c->hcscale_fast = NULL;

#if COMPILE_TEMPLATE_MMX2

    }

#endif /* COMPILE_TEMPLATE_MMX2 */



#if !COMPILE_TEMPLATE_MMX2

    switch(srcFormat) {

        case PIX_FMT_YUYV422  : c->chrToYV12 = RENAME(yuy2ToUV); break;

        case PIX_FMT_UYVY422  : c->chrToYV12 = RENAME(uyvyToUV); break;

        case PIX_FMT_NV12     : c->chrToYV12 = RENAME(nv12ToUV); break;

        case PIX_FMT_NV21     : c->chrToYV12 = RENAME(nv21ToUV); break;

        case PIX_FMT_GRAY16LE :

        case PIX_FMT_YUV420P9LE:

        case PIX_FMT_YUV422P10LE:

        case PIX_FMT_YUV420P10LE:

        case PIX_FMT_YUV420P16LE:

        case PIX_FMT_YUV422P16LE:

        case PIX_FMT_YUV444P16LE: c->hScale16= RENAME(hScale16); break;

    }

#endif /* !COMPILE_TEMPLATE_MMX2 */

    if (!c->chrSrcHSubSample) {

        switch(srcFormat) {

        case PIX_FMT_BGR24  : c->chrToYV12 = RENAME(bgr24ToUV); break;

        case PIX_FMT_RGB24  : c->chrToYV12 = RENAME(rgb24ToUV); break;

        default: break;

        }

    }



    switch (srcFormat) {

#if !COMPILE_TEMPLATE_MMX2

    case PIX_FMT_YUYV422  :

    case PIX_FMT_Y400A    :

                            c->lumToYV12 = RENAME(yuy2ToY); break;

    case PIX_FMT_UYVY422  :

                            c->lumToYV12 = RENAME(uyvyToY); break;

#endif /* !COMPILE_TEMPLATE_MMX2 */

    case PIX_FMT_BGR24    : c->lumToYV12 = RENAME(bgr24ToY); break;

    case PIX_FMT_RGB24    : c->lumToYV12 = RENAME(rgb24ToY); break;

    default: break;

    }

#if !COMPILE_TEMPLATE_MMX2

    if (c->alpPixBuf) {

        switch (srcFormat) {

        case PIX_FMT_Y400A  : c->alpToYV12 = RENAME(yuy2ToY); break;

        default: break;

        }

    }

#endif /* !COMPILE_TEMPLATE_MMX2 */

    if(isAnyRGB(c->srcFormat))

        c->hScale16= RENAME(hScale16);

}

static int encode_frame(AVCodecContext *avctx, AVPacket *pkt,

                        const AVFrame *pic, int *got_packet)

{

    ProresContext *ctx = avctx->priv_data;

    uint8_t *orig_buf, *buf, *slice_hdr, *slice_sizes, *tmp;

    uint8_t *picture_size_pos;

    PutBitContext pb;

    int x, y, i, mb, q = 0;

    int sizes[4] = { 0 };

    int slice_hdr_size = 2 + 2 * (ctx->num_planes - 1);

    int frame_size, picture_size, slice_size;

    int mbs_per_slice = ctx->mbs_per_slice;

    int pkt_size, ret;



    *avctx->coded_frame           = *pic;

    avctx->coded_frame->pict_type = AV_PICTURE_TYPE_I;

    avctx->coded_frame->key_frame = 1;



    pkt_size = ctx->mb_width * ctx->mb_height * 64 * 3 * 12

               + ctx->num_slices * 2 + 200 + FF_MIN_BUFFER_SIZE;



    if ((ret = ff_alloc_packet(pkt, pkt_size)) < 0) {

        av_log(avctx, AV_LOG_ERROR, "Error getting output packet.\n");

        return ret;

    }



    orig_buf = pkt->data;



    // frame atom

    orig_buf += 4;                              // frame size

    bytestream_put_be32  (&orig_buf, FRAME_ID); // frame container ID

    buf = orig_buf;



    // frame header

    tmp = buf;

    buf += 2;                                   // frame header size will be stored here

    bytestream_put_be16  (&buf, 0);             // version 1

    bytestream_put_buffer(&buf, "Lavc", 4);     // creator

    bytestream_put_be16  (&buf, avctx->width);

    bytestream_put_be16  (&buf, avctx->height);

    bytestream_put_byte  (&buf, ctx->chroma_factor << 6); // frame flags

    bytestream_put_byte  (&buf, 0);             // reserved

    bytestream_put_byte  (&buf, 0);             // primaries

    bytestream_put_byte  (&buf, 0);             // transfer function

    bytestream_put_byte  (&buf, 6);             // colour matrix - ITU-R BT.601-4

    bytestream_put_byte  (&buf, 0x40);          // source format and alpha information

    bytestream_put_byte  (&buf, 0);             // reserved

    bytestream_put_byte  (&buf, 0x03);          // matrix flags - both matrices are present

    // luma quantisation matrix

    for (i = 0; i < 64; i++)

        bytestream_put_byte(&buf, ctx->profile_info->quant[i]);

    // chroma quantisation matrix

    for (i = 0; i < 64; i++)

        bytestream_put_byte(&buf, ctx->profile_info->quant[i]);

    bytestream_put_be16  (&tmp, buf - orig_buf); // write back frame header size



    // picture header

    picture_size_pos = buf + 1;

    bytestream_put_byte  (&buf, 0x40);          // picture header size (in bits)

    buf += 4;                                   // picture data size will be stored here

    bytestream_put_be16  (&buf, ctx->num_slices); // total number of slices

    bytestream_put_byte  (&buf, av_log2(ctx->mbs_per_slice) << 4); // slice width and height in MBs



    // seek table - will be filled during slice encoding

    slice_sizes = buf;

    buf += ctx->num_slices * 2;



    // slices

    for (y = 0; y < ctx->mb_height; y++) {

        mbs_per_slice = ctx->mbs_per_slice;

        for (x = mb = 0; x < ctx->mb_width; x += mbs_per_slice, mb++) {

            while (ctx->mb_width - x < mbs_per_slice)

                mbs_per_slice >>= 1;

            q = find_slice_quant(avctx, pic, (mb + 1) * TRELLIS_WIDTH, x, y,

                                 mbs_per_slice);

        }



        for (x = ctx->slices_width - 1; x >= 0; x--) {

            ctx->slice_q[x] = ctx->nodes[q].quant;

            q = ctx->nodes[q].prev_node;

        }



        mbs_per_slice = ctx->mbs_per_slice;

        for (x = mb = 0; x < ctx->mb_width; x += mbs_per_slice, mb++) {

            q = ctx->slice_q[mb];



            while (ctx->mb_width - x < mbs_per_slice)

                mbs_per_slice >>= 1;



            bytestream_put_byte(&buf, slice_hdr_size << 3);

            slice_hdr = buf;

            buf += slice_hdr_size - 1;

            init_put_bits(&pb, buf, (pkt_size - (buf - orig_buf)) * 8);

            encode_slice(avctx, pic, &pb, sizes, x, y, q, mbs_per_slice);



            bytestream_put_byte(&slice_hdr, q);

            slice_size = slice_hdr_size + sizes[ctx->num_planes - 1];

            for (i = 0; i < ctx->num_planes - 1; i++) {

                bytestream_put_be16(&slice_hdr, sizes[i]);

                slice_size += sizes[i];

            }

            bytestream_put_be16(&slice_sizes, slice_size);

            buf += slice_size - slice_hdr_size;

        }

    }



    orig_buf -= 8;

    frame_size = buf - orig_buf;

    picture_size = buf - picture_size_pos - 6;

    bytestream_put_be32(&orig_buf, frame_size);

    bytestream_put_be32(&picture_size_pos, picture_size);



    pkt->size   = frame_size;

    pkt->flags |= AV_PKT_FLAG_KEY;

    *got_packet = 1;



    return 0;

}

static int epzs_motion_search4(MpegEncContext * s, int block,

                             int *mx_ptr, int *my_ptr,

                             int P[6][2], int pred_x, int pred_y,

                             int xmin, int ymin, int xmax, int ymax, uint8_t *ref_picture)

{

    int best[2]={0, 0};

    int d, dmin; 

    UINT8 *new_pic, *old_pic;

    const int pic_stride= s->linesize;

    const int pic_xy= ((s->mb_y*2 + (block>>1))*pic_stride + s->mb_x*2 + (block&1))*8;

    UINT16 *mv_penalty= s->mv_penalty[s->f_code] + MAX_MV; // f_code of the prev frame

    int quant= s->qscale; // qscale of the prev frame

    const int shift= 1+s->quarter_sample;



    new_pic = s->new_picture[0] + pic_xy;

    old_pic = ref_picture + pic_xy;



    dmin = pix_abs8x8(new_pic, old_pic, pic_stride);



    /* first line */

    if ((s->mb_y == 0 || s->first_slice_line || s->first_gob_line) && block<2) {

        CHECK_MV4(P[1][0]>>shift, P[1][1]>>shift)

    }else{

        CHECK_MV4(P[4][0]>>shift, P[4][1]>>shift)

        if(dmin<Z_THRESHOLD){

            *mx_ptr= P[4][0]>>shift;

            *my_ptr= P[4][1]>>shift;

//printf("M\n");

            return dmin;

        }

        CHECK_MV4(P[1][0]>>shift, P[1][1]>>shift)

        CHECK_MV4(P[2][0]>>shift, P[2][1]>>shift)

        CHECK_MV4(P[3][0]>>shift, P[3][1]>>shift)

    }

    CHECK_MV4(P[0][0]>>shift, P[0][1]>>shift)

    CHECK_MV4(P[5][0]>>shift, P[5][1]>>shift)



//check(best[0],best[1],0, b0)

    dmin= small_diamond_search4MV(s, best, dmin, new_pic, old_pic, pic_stride, 

                                   pred_x, pred_y, mv_penalty, quant, xmin, ymin, xmax, ymax, shift);

//check(best[0],best[1],0, b1)

    *mx_ptr= best[0];

    *my_ptr= best[1];    



//    printf("%d %d %d \n", best[0], best[1], dmin);

    return dmin;

}

static int ffm_write_write_index(int fd, int64_t pos)

{

    uint8_t buf[8];

    int i;



    for(i=0;i<8;i++)

        buf[i] = (pos >> (56 - i * 8)) & 0xff;

    lseek(fd, 8, SEEK_SET);

    if (write(fd, buf, 8) != 8)

        return AVERROR(EIO);

    return 8;

}

static void rv34_output_i16x16(RV34DecContext *r, int8_t *intra_types, int cbp)

{

    LOCAL_ALIGNED_16(DCTELEM, block16, [16]);

    MpegEncContext *s    = &r->s;

    GetBitContext  *gb   = &s->gb;

    int             q_dc = rv34_qscale_tab[ r->luma_dc_quant_i[s->qscale] ],

                    q_ac = rv34_qscale_tab[s->qscale];

    uint8_t        *dst  = s->dest[0];

    DCTELEM        *ptr  = s->block[0];

    int       avail[6*8] = {0};

    int i, j, itype, has_ac;



    memset(block16, 0, 16 * sizeof(*block16));



    // Set neighbour information.

    if(r->avail_cache[1])

        avail[0] = 1;

    if(r->avail_cache[2])

        avail[1] = avail[2] = 1;

    if(r->avail_cache[3])

        avail[3] = avail[4] = 1;

    if(r->avail_cache[4])

        avail[5] = 1;

    if(r->avail_cache[5])

        avail[8] = avail[16] = 1;

    if(r->avail_cache[9])

        avail[24] = avail[32] = 1;



    has_ac = rv34_decode_block(block16, gb, r->cur_vlcs, 3, 0, q_dc, q_dc, q_ac);

    if(has_ac)

        r->rdsp.rv34_inv_transform(block16);

    else

        r->rdsp.rv34_inv_transform_dc(block16);



    itype = ittrans16[intra_types[0]];

    itype = adjust_pred16(itype, r->avail_cache[6-4], r->avail_cache[6-1]);

    r->h.pred16x16[itype](dst, s->linesize);



    for(j = 0; j < 4; j++){

        for(i = 0; i < 4; i++, cbp >>= 1){

            int dc = block16[i + j*4];



            if(cbp & 1){

                has_ac = rv34_decode_block(ptr, gb, r->cur_vlcs, r->luma_vlc, 0, q_ac, q_ac, q_ac);

            }else

                has_ac = 0;



            if(has_ac){

                ptr[0] = dc;

                r->rdsp.rv34_idct_add(dst+4*i, s->linesize, ptr);

            }else

                r->rdsp.rv34_idct_dc_add(dst+4*i, s->linesize, dc);

        }



        dst += 4*s->linesize;

    }



    itype = ittrans16[intra_types[0]];

    if(itype == PLANE_PRED8x8) itype = DC_PRED8x8;

    itype = adjust_pred16(itype, r->avail_cache[6-4], r->avail_cache[6-1]);



    q_dc = rv34_qscale_tab[rv34_chroma_quant[1][s->qscale]];

    q_ac = rv34_qscale_tab[rv34_chroma_quant[0][s->qscale]];



    for(j = 1; j < 3; j++){

        dst = s->dest[j];

        r->h.pred8x8[itype](dst, s->uvlinesize);

        for(i = 0; i < 4; i++, cbp >>= 1){

            uint8_t *pdst;

            if(!(cbp & 1)) continue;

            pdst   = dst + (i&1)*4 + (i&2)*2*s->uvlinesize;



            rv34_process_block(r, pdst, s->uvlinesize,

                               r->chroma_vlc, 1, q_dc, q_ac);

        }

    }

}

static int atrac1_decode_frame(AVCodecContext *avctx, void *data,

                               int *data_size, AVPacket *avpkt)

{

    const uint8_t *buf = avpkt->data;

    int buf_size       = avpkt->size;

    AT1Ctx *q          = avctx->priv_data;

    int ch, ret, i;

    GetBitContext gb;

    float* samples = data;





    if (buf_size < 212 * q->channels) {

        av_log(q,AV_LOG_ERROR,"Not enought data to decode!\n");

        return -1;

    }



    for (ch = 0; ch < q->channels; ch++) {

        AT1SUCtx* su = &q->SUs[ch];



        init_get_bits(&gb, &buf[212 * ch], 212 * 8);



        /* parse block_size_mode, 1st byte */

        ret = at1_parse_bsm(&gb, su->log2_block_count);

        if (ret < 0)

            return ret;



        ret = at1_unpack_dequant(&gb, su, q->spec);

        if (ret < 0)

            return ret;



        ret = at1_imdct_block(su, q);

        if (ret < 0)

            return ret;

        at1_subband_synthesis(q, su, q->out_samples[ch]);

    }



    /* interleave; FIXME, should create/use a DSP function */

    if (q->channels == 1) {

        /* mono */

        memcpy(samples, q->out_samples[0], AT1_SU_SAMPLES * 4);

    } else {

        /* stereo */

        for (i = 0; i < AT1_SU_SAMPLES; i++) {

            samples[i * 2]     = q->out_samples[0][i];

            samples[i * 2 + 1] = q->out_samples[1][i];

        }

    }



    *data_size = q->channels * AT1_SU_SAMPLES * sizeof(*samples);

    return avctx->block_align;

}

static inline int mpeg2_decode_block_intra(MpegEncContext *s, int16_t *block, int n)

{

    int level, dc, diff, i, j, run;

    int component;

    RLTable *rl;

    uint8_t * const scantable = s->intra_scantable.permutated;

    const uint16_t *quant_matrix;

    const int qscale = s->qscale;

    int mismatch;



    /* DC coefficient */

    if (n < 4) {

        quant_matrix = s->intra_matrix;

        component = 0;

    } else {

        quant_matrix = s->chroma_intra_matrix;

        component = (n & 1) + 1;

    }

    diff = decode_dc(&s->gb, component);

    if (diff >= 0xffff)

        return -1;

    dc  = s->last_dc[component];

    dc += diff;

    s->last_dc[component] = dc;

    block[0] = dc << (3 - s->intra_dc_precision);

    av_dlog(s->avctx, "dc=%d\n", block[0]);

    mismatch = block[0] ^ 1;

    i = 0;

    if (s->intra_vlc_format)

        rl = &ff_rl_mpeg2;

    else

        rl = &ff_rl_mpeg1;



    {

        OPEN_READER(re, &s->gb);

        /* now quantify & encode AC coefficients */

        for (;;) {

            UPDATE_CACHE(re, &s->gb);

            GET_RL_VLC(level, run, re, &s->gb, rl->rl_vlc[0], TEX_VLC_BITS, 2, 0);



            if (level == 127) {

                break;

            } else if (level != 0) {

                i += run;

                j  = scantable[i];

                level = (level * qscale * quant_matrix[j]) >> 4;

                level = (level ^ SHOW_SBITS(re, &s->gb, 1)) - SHOW_SBITS(re, &s->gb, 1);

                LAST_SKIP_BITS(re, &s->gb, 1);

            } else {

                /* escape */

                run = SHOW_UBITS(re, &s->gb, 6) + 1; LAST_SKIP_BITS(re, &s->gb, 6);

                UPDATE_CACHE(re, &s->gb);

                level = SHOW_SBITS(re, &s->gb, 12); SKIP_BITS(re, &s->gb, 12);

                i += run;

                j  = scantable[i];

                if (level < 0) {

                    level = (-level * qscale * quant_matrix[j]) >> 4;

                    level = -level;

                } else {

                    level = (level * qscale * quant_matrix[j]) >> 4;

                }

            }

            if (i > 63) {

                av_log(s->avctx, AV_LOG_ERROR, "ac-tex damaged at %d %d\n", s->mb_x, s->mb_y);

                return -1;

            }



            mismatch ^= level;

            block[j]  = level;

        }

        CLOSE_READER(re, &s->gb);

    }

    block[63] ^= mismatch & 1;



    s->block_last_index[n] = i;

    return 0;

}

static inline int mov_stsc_index_valid(int index, int count)

{

    return index + 1 < count;

}

static int decode_frame(AVCodecContext *avctx, void *data, int *got_frame, AVPacket *avpkt)

{

    AVFrame *frame = data;

    const uint8_t *buf = avpkt->data;

    int buf_size = avpkt->size;

    ZmbvContext * const c = avctx->priv_data;

    int zret = Z_OK; // Zlib return code

    int len = buf_size;

    int hi_ver, lo_ver, ret;

    uint8_t *tmp;



    if ((ret = ff_get_buffer(avctx, frame, 0)) < 0) {

        av_log(avctx, AV_LOG_ERROR, "get_buffer() failed\n");

        return ret;

    }



    /* parse header */

    c->flags = buf[0];

    buf++; len--;

    if (c->flags & ZMBV_KEYFRAME) {

        hi_ver = buf[0];

        lo_ver = buf[1];

        c->comp = buf[2];

        c->fmt = buf[3];

        c->bw = buf[4];

        c->bh = buf[5];

        c->decode_intra = NULL;

        c->decode_xor = NULL;



        buf += 6;

        len -= 6;

        av_log(avctx, AV_LOG_DEBUG,

               "Flags=%X ver=%i.%i comp=%i fmt=%i blk=%ix%i\n",

               c->flags,hi_ver,lo_ver,c->comp,c->fmt,c->bw,c->bh);

        if (hi_ver != 0 || lo_ver != 1) {

            avpriv_request_sample(avctx, "Version %i.%i", hi_ver, lo_ver);

            return AVERROR_PATCHWELCOME;

        }

        if (c->bw == 0 || c->bh == 0) {

            avpriv_request_sample(avctx, "Block size %ix%i", c->bw, c->bh);

            return AVERROR_PATCHWELCOME;

        }

        if (c->comp != 0 && c->comp != 1) {

            avpriv_request_sample(avctx, "Compression type %i", c->comp);

            return AVERROR_PATCHWELCOME;

        }



        switch (c->fmt) {

        case ZMBV_FMT_8BPP:

            c->bpp = 8;

            c->decode_intra = zmbv_decode_intra;

            c->decode_xor = zmbv_decode_xor_8;

            break;

        case ZMBV_FMT_15BPP:

        case ZMBV_FMT_16BPP:

            c->bpp = 16;

            c->decode_intra = zmbv_decode_intra;

            c->decode_xor = zmbv_decode_xor_16;

            break;

#ifdef ZMBV_ENABLE_24BPP

        case ZMBV_FMT_24BPP:

            c->bpp = 24;

            c->decode_intra = zmbv_decode_intra;

            c->decode_xor = zmbv_decode_xor_24;

            break;

#endif //ZMBV_ENABLE_24BPP

        case ZMBV_FMT_32BPP:

            c->bpp = 32;

            c->decode_intra = zmbv_decode_intra;

            c->decode_xor = zmbv_decode_xor_32;

            break;

        default:

            c->decode_intra = NULL;

            c->decode_xor = NULL;

            avpriv_request_sample(avctx, "Format %i", c->fmt);

            return AVERROR_PATCHWELCOME;

        }



        zret = inflateReset(&c->zstream);

        if (zret != Z_OK) {

            av_log(avctx, AV_LOG_ERROR, "Inflate reset error: %d\n", zret);

            return AVERROR_UNKNOWN;

        }



        tmp = av_realloc(c->cur,  avctx->width * avctx->height * (c->bpp / 8));

        if (!tmp)

            return AVERROR(ENOMEM);

        c->cur = tmp;

        tmp = av_realloc(c->prev, avctx->width * avctx->height * (c->bpp / 8));

        if (!tmp)

            return AVERROR(ENOMEM);

        c->prev = tmp;

        c->bx   = (c->width  + c->bw - 1) / c->bw;

        c->by   = (c->height + c->bh - 1) / c->bh;

    }



    if (c->decode_intra == NULL) {

        av_log(avctx, AV_LOG_ERROR, "Error! Got no format or no keyframe!\n");

        return AVERROR_INVALIDDATA;

    }



    if (c->comp == 0) { //Uncompressed data

        if (c->decomp_size < len) {

            av_log(avctx, AV_LOG_ERROR, "Buffer too small\n");

            return AVERROR_INVALIDDATA;

        }

        memcpy(c->decomp_buf, buf, len);

    } else { // ZLIB-compressed data

        c->zstream.total_in = c->zstream.total_out = 0;

        c->zstream.next_in = buf;

        c->zstream.avail_in = len;

        c->zstream.next_out = c->decomp_buf;

        c->zstream.avail_out = c->decomp_size;

        zret = inflate(&c->zstream, Z_SYNC_FLUSH);

        if (zret != Z_OK && zret != Z_STREAM_END) {

            av_log(avctx, AV_LOG_ERROR, "inflate error %d\n", zret);

            return AVERROR_INVALIDDATA;

        }

        c->decomp_len = c->zstream.total_out;

    }

    if (c->flags & ZMBV_KEYFRAME) {

        frame->key_frame = 1;

        frame->pict_type = AV_PICTURE_TYPE_I;

        c->decode_intra(c);

    } else {

        frame->key_frame = 0;

        frame->pict_type = AV_PICTURE_TYPE_P;

        if (c->decomp_len)

            c->decode_xor(c);

    }



    /* update frames */

    {

        uint8_t *out, *src;

        int i, j;



        out = frame->data[0];

        src = c->cur;

        switch (c->fmt) {

        case ZMBV_FMT_8BPP:

            for (j = 0; j < c->height; j++) {

                for (i = 0; i < c->width; i++) {

                    out[i * 3 + 0] = c->pal[(*src) * 3 + 0];

                    out[i * 3 + 1] = c->pal[(*src) * 3 + 1];

                    out[i * 3 + 2] = c->pal[(*src) * 3 + 2];

                    src++;

                }

                out += frame->linesize[0];

            }

            break;

        case ZMBV_FMT_15BPP:

            for (j = 0; j < c->height; j++) {

                for (i = 0; i < c->width; i++) {

                    uint16_t tmp = AV_RL16(src);

                    src += 2;

                    out[i * 3 + 0] = (tmp & 0x7C00) >> 7;

                    out[i * 3 + 1] = (tmp & 0x03E0) >> 2;

                    out[i * 3 + 2] = (tmp & 0x001F) << 3;

                }

                out += frame->linesize[0];

            }

            break;

        case ZMBV_FMT_16BPP:

            for (j = 0; j < c->height; j++) {

                for (i = 0; i < c->width; i++) {

                    uint16_t tmp = AV_RL16(src);

                    src += 2;

                    out[i * 3 + 0] = (tmp & 0xF800) >> 8;

                    out[i * 3 + 1] = (tmp & 0x07E0) >> 3;

                    out[i * 3 + 2] = (tmp & 0x001F) << 3;

                }

                out += frame->linesize[0];

            }

            break;

#ifdef ZMBV_ENABLE_24BPP

        case ZMBV_FMT_24BPP:

            for (j = 0; j < c->height; j++) {

                memcpy(out, src, c->width * 3);

                src += c->width * 3;

                out += frame->linesize[0];

            }

            break;

#endif //ZMBV_ENABLE_24BPP

        case ZMBV_FMT_32BPP:

            for (j = 0; j < c->height; j++) {

                for (i = 0; i < c->width; i++) {

                    uint32_t tmp = AV_RL32(src);

                    src += 4;

                    AV_WB24(out+(i*3), tmp);

                }

                out += frame->linesize[0];

            }

            break;

        default:

            av_log(avctx, AV_LOG_ERROR, "Cannot handle format %i\n", c->fmt);

        }

        FFSWAP(uint8_t *, c->cur, c->prev);

    }

    *got_frame = 1;



    /* always report that the buffer was completely consumed */

    return buf_size;

}

static int build_filter(ResampleContext *c, void *filter, double factor, int tap_count, int alloc, int phase_count, int scale,

                        int filter_type, double kaiser_beta){

    int ph, i;

    double x, y, w, t;

    double *tab = av_malloc_array(tap_count+1,  sizeof(*tab));

    const int center= (tap_count-1)/2;



    if (!tab)

        return AVERROR(ENOMEM);



    /* if upsampling, only need to interpolate, no filter */

    if (factor > 1.0)

        factor = 1.0;



    av_assert0(phase_count == 1 || phase_count % 2 == 0);

    for(ph = 0; ph <= phase_count / 2; ph++) {

        double norm = 0;

        for(i=0;i<=tap_count;i++) {

            x = M_PI * ((double)(i - center) - (double)ph / phase_count) * factor;

            if (x == 0) y = 1.0;

            else        y = sin(x) / x;

            switch(filter_type){

            case SWR_FILTER_TYPE_CUBIC:{

                const float d= -0.5; //first order derivative = -0.5

                x = fabs(((double)(i - center) - (double)ph / phase_count) * factor);

                if(x<1.0) y= 1 - 3*x*x + 2*x*x*x + d*(            -x*x + x*x*x);

                else      y=                       d*(-4 + 8*x - 5*x*x + x*x*x);

                break;}

            case SWR_FILTER_TYPE_BLACKMAN_NUTTALL:

                w = 2.0*x / (factor*tap_count) + M_PI;

                t = cos(w);

                y *= 0.3635819 - 0.4891775 * t + 0.1365995 * (2*t*t-1) - 0.0106411 * (4*t*t*t - 3*t);

                break;

            case SWR_FILTER_TYPE_KAISER:

                w = 2.0*x / (factor*tap_count*M_PI);

                y *= bessel(kaiser_beta*sqrt(FFMAX(1-w*w, 0)));

                break;

            default:

                av_assert0(0);

            }



            tab[i] = y;

            if (i < tap_count)

                norm += y;

        }



        /* normalize so that an uniform color remains the same */

        switch(c->format){

        case AV_SAMPLE_FMT_S16P:

            for(i=0;i<tap_count;i++)

                ((int16_t*)filter)[ph * alloc + i] = av_clip(lrintf(tab[i] * scale / norm), INT16_MIN, INT16_MAX);

            if (tap_count % 2 == 0) {

                for (i = 0; i < tap_count; i++)

                    ((int16_t*)filter)[(phase_count-ph) * alloc + tap_count-1-i] = ((int16_t*)filter)[ph * alloc + i];

            }

            else {

                for (i = 1; i <= tap_count; i++)

                    ((int16_t*)filter)[(phase_count-ph) * alloc + tap_count-i] =

                        av_clip(lrintf(tab[i] * scale / (norm - tab[0] + tab[tap_count])), INT16_MIN, INT16_MAX);

            }

            break;

        case AV_SAMPLE_FMT_S32P:

            for(i=0;i<tap_count;i++)

                ((int32_t*)filter)[ph * alloc + i] = av_clipl_int32(llrint(tab[i] * scale / norm));

            if (tap_count % 2 == 0) {

                for (i = 0; i < tap_count; i++)

                    ((int32_t*)filter)[(phase_count-ph) * alloc + tap_count-1-i] = ((int32_t*)filter)[ph * alloc + i];

            }

            else {

                for (i = 1; i <= tap_count; i++)

                    ((int32_t*)filter)[(phase_count-ph) * alloc + tap_count-i] =

                        av_clipl_int32(llrint(tab[i] * scale / (norm - tab[0] + tab[tap_count])));

            }

            break;

        case AV_SAMPLE_FMT_FLTP:

            for(i=0;i<tap_count;i++)

                ((float*)filter)[ph * alloc + i] = tab[i] * scale / norm;

            if (tap_count % 2 == 0) {

                for (i = 0; i < tap_count; i++)

                    ((float*)filter)[(phase_count-ph) * alloc + tap_count-1-i] = ((float*)filter)[ph * alloc + i];

            }

            else {

                for (i = 1; i <= tap_count; i++)

                    ((float*)filter)[(phase_count-ph) * alloc + tap_count-i] = tab[i] * scale / (norm - tab[0] + tab[tap_count]);

            }

            break;

        case AV_SAMPLE_FMT_DBLP:

            for(i=0;i<tap_count;i++)

                ((double*)filter)[ph * alloc + i] = tab[i] * scale / norm;

            if (tap_count % 2 == 0) {

                for (i = 0; i < tap_count; i++)

                    ((double*)filter)[(phase_count-ph) * alloc + tap_count-1-i] = ((double*)filter)[ph * alloc + i];

            }

            else {

                for (i = 1; i <= tap_count; i++)

                    ((double*)filter)[(phase_count-ph) * alloc + tap_count-i] = tab[i] * scale / (norm - tab[0] + tab[tap_count]);

            }

            break;

        }

    }

#if 0

    {

#define LEN 1024

        int j,k;

        double sine[LEN + tap_count];

        double filtered[LEN];

        double maxff=-2, minff=2, maxsf=-2, minsf=2;

        for(i=0; i<LEN; i++){

            double ss=0, sf=0, ff=0;

            for(j=0; j<LEN+tap_count; j++)

                sine[j]= cos(i*j*M_PI/LEN);

            for(j=0; j<LEN; j++){

                double sum=0;

                ph=0;

                for(k=0; k<tap_count; k++)

                    sum += filter[ph * tap_count + k] * sine[k+j];

                filtered[j]= sum / (1<<FILTER_SHIFT);

                ss+= sine[j + center] * sine[j + center];

                ff+= filtered[j] * filtered[j];

                sf+= sine[j + center] * filtered[j];

            }

            ss= sqrt(2*ss/LEN);

            ff= sqrt(2*ff/LEN);

            sf= 2*sf/LEN;

            maxff= FFMAX(maxff, ff);

            minff= FFMIN(minff, ff);

