static void sr_1d97_float(float *p, int i0, int i1)

{

    int i;



    if (i1 <= i0 + 1) {

        if (i0 == 1)

            p[1] *= F_LFTG_K/2;

        else

            p[0] *= F_LFTG_X/2;

        return;

    }



    extend97_float(p, i0, i1);



    for (i = i0 / 2 - 1; i < i1 / 2 + 2; i++)

        p[2 * i]     -= F_LFTG_DELTA * (p[2 * i - 1] + p[2 * i + 1]);

    /* step 4 */

    for (i = i0 / 2 - 1; i < i1 / 2 + 1; i++)

        p[2 * i + 1] -= F_LFTG_GAMMA * (p[2 * i]     + p[2 * i + 2]);

    /*step 5*/

    for (i = i0 / 2; i < i1 / 2 + 1; i++)

        p[2 * i]     += F_LFTG_BETA  * (p[2 * i - 1] + p[2 * i + 1]);

    /* step 6 */

    for (i = i0 / 2; i < i1 / 2; i++)

        p[2 * i + 1] += F_LFTG_ALPHA * (p[2 * i]     + p[2 * i + 2]);

}

static int dca_find_frame_end(DCAParseContext * pc1, const uint8_t * buf,

                              int buf_size)

{

    int start_found, i;

    uint32_t state;

    ParseContext *pc = &pc1->pc;



    start_found = pc->frame_start_found;

    state = pc->state;



    i = 0;

    if (!start_found) {

        for (i = 0; i < buf_size; i++) {

            state = (state << 8) | buf[i];

            if (IS_MARKER(state, i, buf, buf_size)) {

                if (!pc1->lastmarker || state == pc1->lastmarker || pc1->lastmarker == DCA_HD_MARKER) {

                    start_found = 1;

                    pc1->lastmarker = state;

                    break;

                }

            }

        }

    }

    if (start_found) {

        for (; i < buf_size; i++) {

            pc1->size++;

            state = (state << 8) | buf[i];

            if (state == DCA_HD_MARKER && !pc1->hd_pos)

                pc1->hd_pos = pc1->size;

            if (IS_MARKER(state, i, buf, buf_size) && (state == pc1->lastmarker || pc1->lastmarker == DCA_HD_MARKER)) {

                if(pc1->framesize > pc1->size)

                    continue;

                if(!pc1->framesize){

                    pc1->framesize = pc1->hd_pos ? pc1->hd_pos : pc1->size;

                }

                pc->frame_start_found = 0;

                pc->state = -1;

                pc1->size = 0;

                return i - 3;

            }

        }

    }

    pc->frame_start_found = start_found;

    pc->state = state;

    return END_NOT_FOUND;

}

static int mpeg1_decode_picture(AVCodecContext *avctx, const uint8_t *buf,

                                int buf_size)

{

    Mpeg1Context *s1  = avctx->priv_data;

    MpegEncContext *s = &s1->mpeg_enc_ctx;

    int ref, f_code, vbv_delay;



    init_get_bits(&s->gb, buf, buf_size * 8);



    ref = get_bits(&s->gb, 10); /* temporal ref */

    s->pict_type = get_bits(&s->gb, 3);

    if (s->pict_type == 0 || s->pict_type > 3)

        return -1;



    vbv_delay = get_bits(&s->gb, 16);

    if (s->pict_type == AV_PICTURE_TYPE_P ||

        s->pict_type == AV_PICTURE_TYPE_B) {

        s->full_pel[0] = get_bits1(&s->gb);

        f_code = get_bits(&s->gb, 3);

        if (f_code == 0 && (avctx->err_recognition & AV_EF_BITSTREAM))

            return -1;

        s->mpeg_f_code[0][0] = f_code;

        s->mpeg_f_code[0][1] = f_code;

    }

    if (s->pict_type == AV_PICTURE_TYPE_B) {

        s->full_pel[1] = get_bits1(&s->gb);

        f_code = get_bits(&s->gb, 3);

        if (f_code == 0 && (avctx->err_recognition & AV_EF_BITSTREAM))

            return -1;

        s->mpeg_f_code[1][0] = f_code;

        s->mpeg_f_code[1][1] = f_code;

    }

    s->current_picture.f.pict_type = s->pict_type;

    s->current_picture.f.key_frame = s->pict_type == AV_PICTURE_TYPE_I;



    if (avctx->debug & FF_DEBUG_PICT_INFO)

        av_log(avctx, AV_LOG_DEBUG,

               "vbv_delay %d, ref %d type:%d\n", vbv_delay, ref, s->pict_type);



    s->y_dc_scale = 8;

    s->c_dc_scale = 8;

    return 0;

}

static int read_quant_tables(RangeCoder *c,

                             int16_t quant_table[MAX_CONTEXT_INPUTS][256])

{

    int i;

    int context_count = 1;



    for (i = 0; i < 5; i++) {

        context_count *= read_quant_table(c, quant_table[i], context_count);

        if (context_count > 32768U) {

            return AVERROR_INVALIDDATA;

        }

    }

    return (context_count + 1) / 2;

}

int av_copy_packet_side_data(AVPacket *pkt, AVPacket *src)

{

    if (src->side_data_elems) {

        int i;

        DUP_DATA(pkt->side_data, src->side_data,

                src->side_data_elems * sizeof(*src->side_data), 0, ALLOC_MALLOC);

        memset(pkt->side_data, 0,

                src->side_data_elems * sizeof(*src->side_data));

        for (i = 0; i < src->side_data_elems; i++) {

            DUP_DATA(pkt->side_data[i].data, src->side_data[i].data,

                    src->side_data[i].size, 1, ALLOC_MALLOC);

            pkt->side_data[i].size = src->side_data[i].size;

            pkt->side_data[i].type = src->side_data[i].type;

        }

    }

    return 0;



failed_alloc:

    av_destruct_packet(pkt);

    return AVERROR(ENOMEM);

}

static inline void RENAME(rgb32tobgr32)(const uint8_t *src, uint8_t *dst, long src_size)

{

#ifdef HAVE_MMX

/* TODO: unroll this loop */

	asm volatile (

		"xor %%"REG_a", %%"REG_a"	\n\t"

		ASMALIGN16

		"1:				\n\t"

		PREFETCH" 32(%0, %%"REG_a")	\n\t"

		"movq (%0, %%"REG_a"), %%mm0	\n\t"

		"movq %%mm0, %%mm1		\n\t"

		"movq %%mm0, %%mm2		\n\t"

		"pslld $16, %%mm0		\n\t"

		"psrld $16, %%mm1		\n\t"

		"pand "MANGLE(mask32r)", %%mm0	\n\t"

		"pand "MANGLE(mask32g)", %%mm2	\n\t"

		"pand "MANGLE(mask32b)", %%mm1	\n\t"

		"por %%mm0, %%mm2		\n\t"

		"por %%mm1, %%mm2		\n\t"

		MOVNTQ" %%mm2, (%1, %%"REG_a")	\n\t"

		"add $8, %%"REG_a"		\n\t"

		"cmp %2, %%"REG_a"		\n\t"

		" jb 1b				\n\t"

		:: "r" (src), "r"(dst), "r" (src_size-7)

		: "%"REG_a

	);



	__asm __volatile(SFENCE:::"memory");

	__asm __volatile(EMMS:::"memory");

#else

	unsigned i;

	unsigned num_pixels = src_size >> 2;

	for(i=0; i<num_pixels; i++)

	{

#ifdef WORDS_BIGENDIAN  

	  dst[4*i + 1] = src[4*i + 3];

	  dst[4*i + 2] = src[4*i + 2];

	  dst[4*i + 3] = src[4*i + 1];

#else

	  dst[4*i + 0] = src[4*i + 2];

	  dst[4*i + 1] = src[4*i + 1];

	  dst[4*i + 2] = src[4*i + 0];

#endif

	}

#endif

}

static int init_input(AVFormatContext *s, const char *filename,

                      AVDictionary **options)

{

    int ret;

    AVProbeData pd = { filename, NULL, 0 };

    int score = AVPROBE_SCORE_RETRY;



    if (s->pb) {

        s->flags |= AVFMT_FLAG_CUSTOM_IO;

        if (!s->iformat)

            return av_probe_input_buffer2(s->pb, &s->iformat, filename,

                                         s, 0, s->format_probesize);

        else if (s->iformat->flags & AVFMT_NOFILE)

            av_log(s, AV_LOG_WARNING, "Custom AVIOContext makes no sense and "

                                      "will be ignored with AVFMT_NOFILE format.\n");

        return 0;

    }



    if ((s->iformat && s->iformat->flags & AVFMT_NOFILE) ||

        (!s->iformat && (s->iformat = av_probe_input_format2(&pd, 0, &score))))

        return score;



    if ((ret = avio_open2(&s->pb, filename, AVIO_FLAG_READ | s->avio_flags,

                          &s->interrupt_callback, options)) < 0)

        return ret;

    if (s->iformat)

        return 0;

    return av_probe_input_buffer2(s->pb, &s->iformat, filename,

                                 s, 0, s->format_probesize);

}

