int attribute_align_arg avcodec_decode_audio4(AVCodecContext *avctx,

                                              AVFrame *frame,

                                              int *got_frame_ptr,

                                              AVPacket *avpkt)

{

    AVCodecInternal *avci = avctx->internal;

    int planar, channels;

    int ret = 0;



    *got_frame_ptr = 0;



    avctx->pkt = avpkt;



    if (!avpkt->data && avpkt->size) {

        av_log(avctx, AV_LOG_ERROR, "invalid packet: NULL data, size != 0\n");

        return AVERROR(EINVAL);

    }



    apply_param_change(avctx, avpkt);



    avcodec_get_frame_defaults(frame);



    if (!avctx->refcounted_frames)

        av_frame_unref(&avci->to_free);



    if ((avctx->codec->capabilities & CODEC_CAP_DELAY) || avpkt->size) {

        ret = avctx->codec->decode(avctx, frame, got_frame_ptr, avpkt);

        if (ret >= 0 && *got_frame_ptr) {

            avctx->frame_number++;

            frame->pkt_dts = avpkt->dts;

            if (frame->format == AV_SAMPLE_FMT_NONE)

                frame->format = avctx->sample_fmt;



            if (!avctx->refcounted_frames) {

                avci->to_free = *frame;

                avci->to_free.extended_data = avci->to_free.data;

                memset(frame->buf, 0, sizeof(frame->buf));

                frame->extended_buf    = NULL;

                frame->nb_extended_buf = 0;

            }

        } else if (frame->data[0])

            av_frame_unref(frame);

    }



    /* many decoders assign whole AVFrames, thus overwriting extended_data;

     * make sure it's set correctly; assume decoders that actually use

     * extended_data are doing it correctly */

    planar   = av_sample_fmt_is_planar(frame->format);

    channels = av_get_channel_layout_nb_channels(frame->channel_layout);

    if (!(planar && channels > AV_NUM_DATA_POINTERS))

        frame->extended_data = frame->data;



    return ret;

}

static int read_matrix_params(MLPDecodeContext *m, SubStream *s, GetBitContext *gbp)

{

    unsigned int mat, ch;



    s->num_primitive_matrices = get_bits(gbp, 4);

    m->matrix_changed++;



    for (mat = 0; mat < s->num_primitive_matrices; mat++) {

        int frac_bits, max_chan;

        s->matrix_out_ch[mat] = get_bits(gbp, 4);

        frac_bits             = get_bits(gbp, 4);

        s->lsb_bypass   [mat] = get_bits1(gbp);



        if (s->matrix_out_ch[mat] > s->max_matrix_channel) {

            av_log(m->avctx, AV_LOG_ERROR,

                    "Invalid channel %d specified as output from matrix.\n",

                    s->matrix_out_ch[mat]);

            return -1;

        }

        if (frac_bits > 14) {

            av_log(m->avctx, AV_LOG_ERROR,

                    "Too many fractional bits specified.\n");

            return -1;

        }



        max_chan = s->max_matrix_channel;

        if (!s->noise_type)

            max_chan+=2;



        for (ch = 0; ch <= max_chan; ch++) {

            int coeff_val = 0;

            if (get_bits1(gbp))

                coeff_val = get_sbits(gbp, frac_bits + 2);



            s->matrix_coeff[mat][ch] = coeff_val << (14 - frac_bits);

        }



        if (s->noise_type)

            s->matrix_noise_shift[mat] = get_bits(gbp, 4);

        else

            s->matrix_noise_shift[mat] = 0;

    }



    return 0;

}

static int libgsm_encode_frame(AVCodecContext *avctx, AVPacket *avpkt,

                               const AVFrame *frame, int *got_packet_ptr)

{

    int ret;

    gsm_signal *samples = (gsm_signal *)frame->data[0];

    struct gsm_state *state = avctx->priv_data;



    if ((ret = ff_alloc_packet2(avctx, avpkt, avctx->block_align)))

        return ret;



    switch(avctx->codec_id) {

    case AV_CODEC_ID_GSM:

        gsm_encode(state, samples, avpkt->data);

        break;

    case AV_CODEC_ID_GSM_MS:

        gsm_encode(state, samples,                  avpkt->data);

        gsm_encode(state, samples + GSM_FRAME_SIZE, avpkt->data + 32);

    }



    *got_packet_ptr = 1;

    return 0;

}

