static void process_synthesis_subpackets(QDM2Context *q, QDM2SubPNode *list)

{

    QDM2SubPNode *nodes[4];



    nodes[0] = qdm2_search_subpacket_type_in_list(list, 9);

    if (nodes[0] != NULL)

        process_subpacket_9(q, nodes[0]);



    nodes[1] = qdm2_search_subpacket_type_in_list(list, 10);

    if (nodes[1] != NULL)

        process_subpacket_10(q, nodes[1]);

    else

        process_subpacket_10(q, NULL);



    nodes[2] = qdm2_search_subpacket_type_in_list(list, 11);

    if (nodes[0] != NULL && nodes[1] != NULL && nodes[2] != NULL)

        process_subpacket_11(q, nodes[2]);

    else

        process_subpacket_11(q, NULL);



    nodes[3] = qdm2_search_subpacket_type_in_list(list, 12);

    if (nodes[0] != NULL && nodes[1] != NULL && nodes[3] != NULL)

        process_subpacket_12(q, nodes[3]);

    else

        process_subpacket_12(q, NULL);

}

static int ffm_read_data(AVFormatContext *s,

                         uint8_t *buf, int size, int header)

{

    FFMContext *ffm = s->priv_data;

    AVIOContext *pb = s->pb;

    int len, fill_size, size1, frame_offset, id;

    int64_t last_pos = -1;



    size1 = size;

    while (size > 0) {

    redo:

        len = ffm->packet_end - ffm->packet_ptr;

        if (len < 0)

            return -1;

        if (len > size)

            len = size;

        if (len == 0) {

            if (avio_tell(pb) == ffm->file_size)

                avio_seek(pb, ffm->packet_size, SEEK_SET);

    retry_read:

            if (pb->buffer_size != ffm->packet_size) {

                int64_t tell = avio_tell(pb);

                ffio_set_buf_size(pb, ffm->packet_size);

                avio_seek(pb, tell, SEEK_SET);

            }

            id = avio_rb16(pb); /* PACKET_ID */

            if (id != PACKET_ID) {

                if (ffm_resync(s, id) < 0)

                    return -1;

                last_pos = avio_tell(pb);

            }

            fill_size = avio_rb16(pb);

            ffm->dts = avio_rb64(pb);

            frame_offset = avio_rb16(pb);

            avio_read(pb, ffm->packet, ffm->packet_size - FFM_HEADER_SIZE);

            ffm->packet_end = ffm->packet + (ffm->packet_size - FFM_HEADER_SIZE - fill_size);

            if (ffm->packet_end < ffm->packet || frame_offset < 0)

                return -1;

            /* if first packet or resynchronization packet, we must

               handle it specifically */

            if (ffm->first_packet || (frame_offset & 0x8000)) {

                if (!frame_offset) {

                    /* This packet has no frame headers in it */

                    if (avio_tell(pb) >= ffm->packet_size * 3LL) {

                        int64_t seekback = FFMIN(ffm->packet_size * 2LL, avio_tell(pb) - last_pos);

                        seekback = FFMAX(seekback, 0);

                        avio_seek(pb, -seekback, SEEK_CUR);

                        goto retry_read;

                    }

                    /* This is bad, we cannot find a valid frame header */

                    return 0;

                }

                ffm->first_packet = 0;

                if ((frame_offset & 0x7fff) < FFM_HEADER_SIZE)

                    return -1;

                ffm->packet_ptr = ffm->packet + (frame_offset & 0x7fff) - FFM_HEADER_SIZE;

                if (!header)

                    break;

            } else {

                ffm->packet_ptr = ffm->packet;

            }

            goto redo;

        }

        memcpy(buf, ffm->packet_ptr, len);

        buf += len;

        ffm->packet_ptr += len;

        size -= len;

        header = 0;

    }

    return size1 - size;

}

static int udp_close(URLContext *h)

{

    UDPContext *s = h->priv_data;

    int ret;



    if (s->is_multicast && (h->flags & AVIO_FLAG_READ))

        udp_leave_multicast_group(s->udp_fd, (struct sockaddr *)&s->dest_addr);

    closesocket(s->udp_fd);

    av_fifo_free(s->fifo);

#if HAVE_PTHREADS

    if (s->thread_started) {

        pthread_cancel(s->circular_buffer_thread);

        ret = pthread_join(s->circular_buffer_thread, NULL);

        if (ret != 0)

            av_log(h, AV_LOG_ERROR, "pthread_join(): %s\n", strerror(ret));

    }



    pthread_mutex_destroy(&s->mutex);

    pthread_cond_destroy(&s->cond);

#endif

    return 0;

}

static void decode_profile_tier_level(GetBitContext *gb, AVCodecContext *avctx,

                                      PTLCommon *ptl)

{

    int i;



    ptl->profile_space = get_bits(gb, 2);

    ptl->tier_flag     = get_bits1(gb);

    ptl->profile_idc   = get_bits(gb, 5);

    if (ptl->profile_idc == FF_PROFILE_HEVC_MAIN)

        av_log(avctx, AV_LOG_DEBUG, "Main profile bitstream\n");

    else if (ptl->profile_idc == FF_PROFILE_HEVC_MAIN_10)

        av_log(avctx, AV_LOG_DEBUG, "Main 10 profile bitstream\n");

    else if (ptl->profile_idc == FF_PROFILE_HEVC_MAIN_STILL_PICTURE)

        av_log(avctx, AV_LOG_DEBUG, "Main Still Picture profile bitstream\n");

    else

        av_log(avctx, AV_LOG_WARNING, "Unknown HEVC profile: %d\n", ptl->profile_idc);



    for (i = 0; i < 32; i++)

        ptl->profile_compatibility_flag[i] = get_bits1(gb);

    ptl->progressive_source_flag    = get_bits1(gb);

    ptl->interlaced_source_flag     = get_bits1(gb);

    ptl->non_packed_constraint_flag = get_bits1(gb);

    ptl->frame_only_constraint_flag = get_bits1(gb);



    skip_bits(gb, 16); // XXX_reserved_zero_44bits[0..15]

    skip_bits(gb, 16); // XXX_reserved_zero_44bits[16..31]

    skip_bits(gb, 12); // XXX_reserved_zero_44bits[32..43]

}

static int init_image(TiffContext *s, ThreadFrame *frame)

{

    int ret;



    switch (s->planar * 1000 + s->bpp * 10 + s->bppcount) {

    case 11:

        if (!s->palette_is_set) {

            s->avctx->pix_fmt = AV_PIX_FMT_MONOBLACK;

            break;

        }

    case 21:

    case 41:

    case 81:

        s->avctx->pix_fmt = s->palette_is_set ? AV_PIX_FMT_PAL8 : AV_PIX_FMT_GRAY8;

        break;

    case 243:

        if (s->photometric == TIFF_PHOTOMETRIC_YCBCR) {

            if (s->subsampling[0] == 1 && s->subsampling[1] == 1) {

                s->avctx->pix_fmt = AV_PIX_FMT_YUV444P;

            } else if (s->subsampling[0] == 2 && s->subsampling[1] == 1) {

                s->avctx->pix_fmt = AV_PIX_FMT_YUV422P;

            } else if (s->subsampling[0] == 4 && s->subsampling[1] == 1) {

                s->avctx->pix_fmt = AV_PIX_FMT_YUV411P;

            } else if (s->subsampling[0] == 1 && s->subsampling[1] == 2) {

                s->avctx->pix_fmt = AV_PIX_FMT_YUV440P;

            } else if (s->subsampling[0] == 2 && s->subsampling[1] == 2) {

                s->avctx->pix_fmt = AV_PIX_FMT_YUV420P;

            } else if (s->subsampling[0] == 4 && s->subsampling[1] == 4) {

                s->avctx->pix_fmt = AV_PIX_FMT_YUV410P;

            } else {

                av_log(s->avctx, AV_LOG_ERROR, "Unsupported YCbCr subsampling\n");

                return AVERROR_PATCHWELCOME;

            }

        } else

            s->avctx->pix_fmt = AV_PIX_FMT_RGB24;

        break;

    case 161:

        s->avctx->pix_fmt = s->le ? AV_PIX_FMT_GRAY16LE : AV_PIX_FMT_GRAY16BE;

        break;

    case 162:

        s->avctx->pix_fmt = AV_PIX_FMT_YA8;

        break;

    case 322:

        s->avctx->pix_fmt = s->le ? AV_PIX_FMT_YA16LE : AV_PIX_FMT_YA16BE;

        break;

    case 324:

        s->avctx->pix_fmt = AV_PIX_FMT_RGBA;

        break;

    case 483:

        s->avctx->pix_fmt = s->le ? AV_PIX_FMT_RGB48LE  : AV_PIX_FMT_RGB48BE;

        break;

    case 644:

        s->avctx->pix_fmt = s->le ? AV_PIX_FMT_RGBA64LE  : AV_PIX_FMT_RGBA64BE;

        break;

    case 1243:

        s->avctx->pix_fmt = AV_PIX_FMT_GBRP;

        break;

    case 1324:

        s->avctx->pix_fmt = AV_PIX_FMT_GBRAP;

        break;

    case 1483:

        s->avctx->pix_fmt = s->le ? AV_PIX_FMT_GBRP16LE : AV_PIX_FMT_GBRP16BE;

        break;

    case 1644:

        s->avctx->pix_fmt = s->le ? AV_PIX_FMT_GBRAP16LE : AV_PIX_FMT_GBRAP16BE;

        break;

    default:

        av_log(s->avctx, AV_LOG_ERROR,

               "This format is not supported (bpp=%d, bppcount=%d)\n",

               s->bpp, s->bppcount);

        return AVERROR_INVALIDDATA;

    }



    if (s->photometric == TIFF_PHOTOMETRIC_YCBCR) {

        const AVPixFmtDescriptor *desc = av_pix_fmt_desc_get(s->avctx->pix_fmt);

        if((desc->flags & AV_PIX_FMT_FLAG_RGB) || desc->nb_components < 3) {

            av_log(s->avctx, AV_LOG_ERROR, "Unsupported YCbCr variant\n");

            return AVERROR_INVALIDDATA;

        }

    }



    if (s->width != s->avctx->width || s->height != s->avctx->height) {

        ret = ff_set_dimensions(s->avctx, s->width, s->height);

        if (ret < 0)

            return ret;

    }

    if ((ret = ff_thread_get_buffer(s->avctx, frame, 0)) < 0)

        return ret;

    if (s->avctx->pix_fmt == AV_PIX_FMT_PAL8) {

        memcpy(frame->f->data[1], s->palette, sizeof(s->palette));

    }

    return 0;

}

int attribute_align_arg avcodec_decode_audio3(AVCodecContext *avctx, int16_t *samples,

                         int *frame_size_ptr,

                         AVPacket *avpkt)

{

    AVFrame frame;

    int ret, got_frame = 0;



    if (avctx->get_buffer != avcodec_default_get_buffer) {

        av_log(avctx, AV_LOG_ERROR, "A custom get_buffer() cannot be used with "

               "avcodec_decode_audio3()\n");

        return AVERROR(EINVAL);

    }



    ret = avcodec_decode_audio4(avctx, &frame, &got_frame, avpkt);



    if (ret >= 0 && got_frame) {

        int ch, plane_size;

        int planar = av_sample_fmt_is_planar(avctx->sample_fmt);

        int data_size = av_samples_get_buffer_size(&plane_size, avctx->channels,

                                                   frame.nb_samples,

                                                   avctx->sample_fmt, 1);

        if (*frame_size_ptr < data_size) {

            av_log(avctx, AV_LOG_ERROR, "output buffer size is too small for "

                   "the current frame (%d < %d)\n", *frame_size_ptr, data_size);

            return AVERROR(EINVAL);

        }



        memcpy(samples, frame.extended_data[0], plane_size);



        if (planar && avctx->channels > 1) {

            uint8_t *out = ((uint8_t *)samples) + plane_size;

            for (ch = 1; ch < avctx->channels; ch++) {

                memcpy(out, frame.extended_data[ch], plane_size);

                out += plane_size;

            }

        }

        *frame_size_ptr = data_size;

    } else {

        *frame_size_ptr = 0;

    }

    return ret;

}

static void dca_exss_parse_header(DCAContext *s)
{
    int asset_size[8];
    int ss_index;
    int blownup;
    int num_audiop = 1;
    int num_assets = 1;
    int active_ss_mask[8];
    int i, j;
    int start_posn;
    int hdrsize;
    uint32_t mkr;
    if (get_bits_left(&s->gb) < 52)
        return;
    start_posn = get_bits_count(&s->gb) - 32;
    skip_bits(&s->gb, 8); // user data
    ss_index = get_bits(&s->gb, 2);
    blownup = get_bits1(&s->gb);
    hdrsize = get_bits(&s->gb,  8 + 4 * blownup) + 1; // header_size
    skip_bits(&s->gb, 16 + 4 * blownup); // hd_size
    s->static_fields = get_bits1(&s->gb);
    if (s->static_fields) {
        skip_bits(&s->gb, 2); // reference clock code
        skip_bits(&s->gb, 3); // frame duration code
        if (get_bits1(&s->gb))
            skip_bits_long(&s->gb, 36); // timestamp
        /* a single stream can contain multiple audio assets that can be
         * combined to form multiple audio presentations */
        num_audiop = get_bits(&s->gb, 3) + 1;
        if (num_audiop > 1) {
            avpriv_request_sample(s->avctx,
                                  "Multiple DTS-HD audio presentations");
            /* ignore such streams for now */
            return;
        }
        num_assets = get_bits(&s->gb, 3) + 1;
        if (num_assets > 1) {
            avpriv_request_sample(s->avctx, "Multiple DTS-HD audio assets");
            /* ignore such streams for now */
            return;
        }
        for (i = 0; i < num_audiop; i++)
            active_ss_mask[i] = get_bits(&s->gb, ss_index + 1);
        for (i = 0; i < num_audiop; i++)
            for (j = 0; j <= ss_index; j++)
                if (active_ss_mask[i] & (1 << j))
                    skip_bits(&s->gb, 8); // active asset mask
        s->mix_metadata = get_bits1(&s->gb);
        if (s->mix_metadata) {
            int mix_out_mask_size;
            skip_bits(&s->gb, 2); // adjustment level
            mix_out_mask_size  = (get_bits(&s->gb, 2) + 1) << 2;
            s->num_mix_configs =  get_bits(&s->gb, 2) + 1;
            for (i = 0; i < s->num_mix_configs; i++) {
                int mix_out_mask        = get_bits(&s->gb, mix_out_mask_size);
                s->mix_config_num_ch[i] = dca_exss_mask2count(mix_out_mask);
            }
        }
    }
    for (i = 0; i < num_assets; i++)
        asset_size[i] = get_bits_long(&s->gb, 16 + 4 * blownup);
    for (i = 0; i < num_assets; i++) {
        if (dca_exss_parse_asset_header(s))
            return;
    }
    /* not parsed further, we were only interested in the extensions mask
     * from the asset header */
        j = get_bits_count(&s->gb);
        if (start_posn + hdrsize * 8 > j)
            skip_bits_long(&s->gb, start_posn + hdrsize * 8 - j);
        for (i = 0; i < num_assets; i++) {
            start_posn = get_bits_count(&s->gb);
            mkr        = get_bits_long(&s->gb, 32);
            /* parse extensions that we know about */
            if (mkr == 0x655e315e) {
                dca_xbr_parse_frame(s);
            } else if (mkr == 0x47004a03) {
                dca_xxch_decode_frame(s);
                s->core_ext_mask |= DCA_EXT_XXCH; /* xxx use for chan reordering */
            } else {
                av_log(s->avctx, AV_LOG_DEBUG,
                       "DTS-ExSS: unknown marker = 0x%08x\n", mkr);
            }
            /* skip to end of block */
            j = get_bits_count(&s->gb);
            if (start_posn + asset_size[i] * 8 > j)
                skip_bits_long(&s->gb, start_posn + asset_size[i] * 8 - j);
        }
}

static int idcin_read_header(AVFormatContext *s)
{
    AVIOContext *pb = s->pb;
    IdcinDemuxContext *idcin = s->priv_data;
    AVStream *st;
    unsigned int width, height;
    unsigned int sample_rate, bytes_per_sample, channels;
    /* get the 5 header parameters */
    width = avio_rl32(pb);
    height = avio_rl32(pb);
    sample_rate = avio_rl32(pb);
    bytes_per_sample = avio_rl32(pb);
    channels = avio_rl32(pb);
    st = avformat_new_stream(s, NULL);
    if (!st)
        return AVERROR(ENOMEM);
    avpriv_set_pts_info(st, 33, 1, IDCIN_FPS);
    idcin->video_stream_index = st->index;
    st->codec->codec_type = AVMEDIA_TYPE_VIDEO;
    st->codec->codec_id = AV_CODEC_ID_IDCIN;
    st->codec->codec_tag = 0;  /* no fourcc */
    st->codec->width = width;
    st->codec->height = height;
    /* load up the Huffman tables into extradata */
    st->codec->extradata_size = HUFFMAN_TABLE_SIZE;
    st->codec->extradata = av_malloc(HUFFMAN_TABLE_SIZE);
    if (avio_read(pb, st->codec->extradata, HUFFMAN_TABLE_SIZE) !=
        HUFFMAN_TABLE_SIZE)
        return AVERROR(EIO);
    /* if sample rate is 0, assume no audio */
    if (sample_rate) {
        idcin->audio_present = 1;
        st = avformat_new_stream(s, NULL);
        if (!st)
            return AVERROR(ENOMEM);
        avpriv_set_pts_info(st, 33, 1, IDCIN_FPS);
        idcin->audio_stream_index = st->index;
        st->codec->codec_type = AVMEDIA_TYPE_AUDIO;
        st->codec->codec_tag = 1;
        st->codec->channels = channels;
        st->codec->sample_rate = sample_rate;
        st->codec->bits_per_coded_sample = bytes_per_sample * 8;
        st->codec->bit_rate = sample_rate * bytes_per_sample * 8 * channels;
        st->codec->block_align = bytes_per_sample * channels;
        if (bytes_per_sample == 1)
            st->codec->codec_id = AV_CODEC_ID_PCM_U8;
        else
            st->codec->codec_id = AV_CODEC_ID_PCM_S16LE;
        if (sample_rate % 14 != 0) {
            idcin->audio_chunk_size1 = (sample_rate / 14) *
            bytes_per_sample * channels;
            idcin->audio_chunk_size2 = (sample_rate / 14 + 1) *
                bytes_per_sample * channels;
        } else {
            idcin->audio_chunk_size1 = idcin->audio_chunk_size2 =
                (sample_rate / 14) * bytes_per_sample * channels;
        idcin->current_audio_chunk = 0;
    } else
        idcin->audio_present = 1;
    idcin->next_chunk_is_video = 1;
    idcin->pts = 0;
    return 0;

static int update_size(AVCodecContext *ctx, int w, int h, enum AVPixelFormat fmt)

{

    VP9Context *s = ctx->priv_data;

    uint8_t *p;

    int bytesperpixel = s->bytesperpixel;



    av_assert0(w > 0 && h > 0);



    if (s->intra_pred_data[0] && w == ctx->width && h == ctx->height && ctx->pix_fmt == fmt)

        return 0;



    ctx->width   = w;

    ctx->height  = h;

    ctx->pix_fmt = fmt;

    s->sb_cols   = (w + 63) >> 6;

    s->sb_rows   = (h + 63) >> 6;

    s->cols      = (w + 7) >> 3;

    s->rows      = (h + 7) >> 3;



#define assign(var, type, n) var = (type) p; p += s->sb_cols * (n) * sizeof(*var)

    av_freep(&s->intra_pred_data[0]);

    // FIXME we slightly over-allocate here for subsampled chroma, but a little

    // bit of padding shouldn't affect performance...

    p = av_malloc(s->sb_cols * (128 + 192 * bytesperpixel +

                                sizeof(*s->lflvl) + 16 * sizeof(*s->above_mv_ctx)));

    if (!p)

        return AVERROR(ENOMEM);

    assign(s->intra_pred_data[0],  uint8_t *,             64 * bytesperpixel);

    assign(s->intra_pred_data[1],  uint8_t *,             64 * bytesperpixel);

    assign(s->intra_pred_data[2],  uint8_t *,             64 * bytesperpixel);

    assign(s->above_y_nnz_ctx,     uint8_t *,             16);

    assign(s->above_mode_ctx,      uint8_t *,             16);

    assign(s->above_mv_ctx,        VP56mv(*)[2],          16);

    assign(s->above_uv_nnz_ctx[0], uint8_t *,             16);

    assign(s->above_uv_nnz_ctx[1], uint8_t *,             16);

    assign(s->above_partition_ctx, uint8_t *,              8);

    assign(s->above_skip_ctx,      uint8_t *,              8);

    assign(s->above_txfm_ctx,      uint8_t *,              8);

    assign(s->above_segpred_ctx,   uint8_t *,              8);

    assign(s->above_intra_ctx,     uint8_t *,              8);

    assign(s->above_comp_ctx,      uint8_t *,              8);

    assign(s->above_ref_ctx,       uint8_t *,              8);

    assign(s->above_filter_ctx,    uint8_t *,              8);

    assign(s->lflvl,               struct VP9Filter *,     1);

#undef assign



    // these will be re-allocated a little later

    av_freep(&s->b_base);

    av_freep(&s->block_base);



    if (s->bpp != s->last_bpp) {

        ff_vp9dsp_init(&s->dsp, s->bpp);

        ff_videodsp_init(&s->vdsp, s->bpp);

        s->last_bpp = s->bpp;

    }



    return 0;

}

static int64_t mmsh_seek(URLContext *h, int64_t pos, int whence)

{

    MMSHContext *mmsh = h->priv_data;

    MMSContext *mms   = &mmsh->mms;



    if(pos == 0 && whence == SEEK_CUR)

        return mms->asf_header_read_size + mms->remaining_in_len + mmsh->chunk_seq * mms->asf_packet_len;

    return AVERROR(ENOSYS);

}

static void kmvc_decode_inter_8x8(KmvcContext * ctx, const uint8_t * src, int w, int h)

{

    BitBuf bb;

    int res, val;

    int i, j;

    int bx, by;

    int l0x, l1x, l0y, l1y;

    int mx, my;



    kmvc_init_getbits(bb, src);



    for (by = 0; by < h; by += 8)

        for (bx = 0; bx < w; bx += 8) {

            kmvc_getbit(bb, src, res);

            if (!res) {

                kmvc_getbit(bb, src, res);

                if (!res) {     // fill whole 8x8 block

                    val = *src++;

                    for (i = 0; i < 64; i++)

                        BLK(ctx->cur, bx + (i & 0x7), by + (i >> 3)) = val;

                } else {        // copy block from previous frame

                    for (i = 0; i < 64; i++)

                        BLK(ctx->cur, bx + (i & 0x7), by + (i >> 3)) =

                            BLK(ctx->prev, bx + (i & 0x7), by + (i >> 3));

                }

            } else {            // handle four 4x4 subblocks

                for (i = 0; i < 4; i++) {

                    l0x = bx + (i & 1) * 4;

                    l0y = by + (i & 2) * 2;

                    kmvc_getbit(bb, src, res);

                    if (!res) {

                        kmvc_getbit(bb, src, res);

                        if (!res) {     // fill whole 4x4 block

                            val = *src++;

                            for (j = 0; j < 16; j++)

                                BLK(ctx->cur, l0x + (j & 3), l0y + (j >> 2)) = val;

                        } else {        // copy block

                            val = *src++;

                            mx = (val & 0xF) - 8;

                            my = (val >> 4) - 8;

                            for (j = 0; j < 16; j++)

                                BLK(ctx->cur, l0x + (j & 3), l0y + (j >> 2)) =

                                    BLK(ctx->prev, l0x + (j & 3) + mx, l0y + (j >> 2) + my);

                        }

                    } else {    // descend to 2x2 sub-sub-blocks

                        for (j = 0; j < 4; j++) {

                            l1x = l0x + (j & 1) * 2;

                            l1y = l0y + (j & 2);

                            kmvc_getbit(bb, src, res);

                            if (!res) {

                                kmvc_getbit(bb, src, res);

                                if (!res) {     // fill whole 2x2 block

                                    val = *src++;

                                    BLK(ctx->cur, l1x, l1y) = val;

                                    BLK(ctx->cur, l1x + 1, l1y) = val;

                                    BLK(ctx->cur, l1x, l1y + 1) = val;

                                    BLK(ctx->cur, l1x + 1, l1y + 1) = val;

                                } else {        // copy block

                                    val = *src++;

                                    mx = (val & 0xF) - 8;

                                    my = (val >> 4) - 8;

                                    BLK(ctx->cur, l1x, l1y) = BLK(ctx->prev, l1x + mx, l1y + my);

                                    BLK(ctx->cur, l1x + 1, l1y) =

                                        BLK(ctx->prev, l1x + 1 + mx, l1y + my);

                                    BLK(ctx->cur, l1x, l1y + 1) =

                                        BLK(ctx->prev, l1x + mx, l1y + 1 + my);

                                    BLK(ctx->cur, l1x + 1, l1y + 1) =

                                        BLK(ctx->prev, l1x + 1 + mx, l1y + 1 + my);

                                }

                            } else {    // read values for block

                                BLK(ctx->cur, l1x, l1y) = *src++;

                                BLK(ctx->cur, l1x + 1, l1y) = *src++;

                                BLK(ctx->cur, l1x, l1y + 1) = *src++;

                                BLK(ctx->cur, l1x + 1, l1y + 1) = *src++;

                            }

                        }

                    }

                }

            }

        }

}

static int encode_hq_slice(AVCodecContext *avctx, void *arg)

{

    SliceArgs *slice_dat = arg;

    VC2EncContext *s = slice_dat->ctx;

    PutBitContext *pb = &slice_dat->pb;

    const int slice_x = slice_dat->x;

    const int slice_y = slice_dat->y;

    const int quant_idx = slice_dat->quant_idx;

    const int slice_bytes_max = slice_dat->bytes;

    uint8_t quants[MAX_DWT_LEVELS][4];

    int p, level, orientation;



    /* The reference decoder ignores it, and its typical length is 0 */

    memset(put_bits_ptr(pb), 0, s->prefix_bytes);

    skip_put_bytes(pb, s->prefix_bytes);



    put_bits(pb, 8, quant_idx);



    /* Slice quantization (slice_quantizers() in the specs) */

    for (level = 0; level < s->wavelet_depth; level++)

        for (orientation = !!level; orientation < 4; orientation++)

            quants[level][orientation] = FFMAX(quant_idx - s->quant[level][orientation], 0);



    /* Luma + 2 Chroma planes */

    for (p = 0; p < 3; p++) {

        int bytes_start, bytes_len, pad_s, pad_c;

        bytes_start = put_bits_count(pb) >> 3;

        put_bits(pb, 8, 0);

        for (level = 0; level < s->wavelet_depth; level++) {

            for (orientation = !!level; orientation < 4; orientation++) {

                encode_subband(s, pb, slice_x, slice_y,

                               &s->plane[p].band[level][orientation],

                               quants[level][orientation]);

            }

        }

        avpriv_align_put_bits(pb);

        bytes_len = (put_bits_count(pb) >> 3) - bytes_start - 1;

        if (p == 2) {

            int len_diff = slice_bytes_max - (put_bits_count(pb) >> 3);

            pad_s = FFALIGN((bytes_len + len_diff), s->size_scaler)/s->size_scaler;

            pad_c = (pad_s*s->size_scaler) - bytes_len;

        } else {

            pad_s = FFALIGN(bytes_len, s->size_scaler)/s->size_scaler;

            pad_c = (pad_s*s->size_scaler) - bytes_len;

        }

        pb->buf[bytes_start] = pad_s;

        flush_put_bits(pb);



        skip_put_bytes(pb, pad_c);

    }



    return 0;

}

int ff_rtsp_setup_output_streams(AVFormatContext *s, const char *addr)

{

    RTSPState *rt = s->priv_data;

    RTSPMessageHeader reply1, *reply = &reply1;

    int i;

    char *sdp;

    AVFormatContext sdp_ctx, *ctx_array[1];



    s->start_time_realtime = av_gettime();



    /* Announce the stream */

    sdp = av_mallocz(SDP_MAX_SIZE);

    if (sdp == NULL)

        return AVERROR(ENOMEM);

    /* We create the SDP based on the RTSP AVFormatContext where we

     * aren't allowed to change the filename field. (We create the SDP

     * based on the RTSP context since the contexts for the RTP streams

     * don't exist yet.) In order to specify a custom URL with the actual

     * peer IP instead of the originally specified hostname, we create

     * a temporary copy of the AVFormatContext, where the custom URL is set.

     *

     * FIXME: Create the SDP without copying the AVFormatContext.

     * This either requires setting up the RTP stream AVFormatContexts

     * already here (complicating things immensely) or getting a more

     * flexible SDP creation interface.

     */

    sdp_ctx = *s;

    ff_url_join(sdp_ctx.filename, sizeof(sdp_ctx.filename),

                "rtsp", NULL, addr, -1, NULL);

    ctx_array[0] = &sdp_ctx;

    if (avf_sdp_create(ctx_array, 1, sdp, SDP_MAX_SIZE)) {

        av_free(sdp);

        return AVERROR_INVALIDDATA;

    }

    av_log(s, AV_LOG_VERBOSE, "SDP:\n%s\n", sdp);

    ff_rtsp_send_cmd_with_content(s, "ANNOUNCE", rt->control_uri,

                                  "Content-Type: application/sdp\r\n",

                                  reply, NULL, sdp, strlen(sdp));

    av_free(sdp);

    if (reply->status_code != RTSP_STATUS_OK)

        return AVERROR_INVALIDDATA;



    /* Set up the RTSPStreams for each AVStream */

    for (i = 0; i < s->nb_streams; i++) {

        RTSPStream *rtsp_st;

        AVStream *st = s->streams[i];



        rtsp_st = av_mallocz(sizeof(RTSPStream));

        if (!rtsp_st)

            return AVERROR(ENOMEM);

        dynarray_add(&rt->rtsp_streams, &rt->nb_rtsp_streams, rtsp_st);



        st->priv_data = rtsp_st;

        rtsp_st->stream_index = i;



        av_strlcpy(rtsp_st->control_url, rt->control_uri, sizeof(rtsp_st->control_url));

        /* Note, this must match the relative uri set in the sdp content */

        av_strlcatf(rtsp_st->control_url, sizeof(rtsp_st->control_url),

                    "/streamid=%d", i);

    }



    return 0;

}

static int smjpeg_read_packet(AVFormatContext *s, AVPacket *pkt)

{

    SMJPEGContext *sc = s->priv_data;

    uint32_t dtype, ret, size, timestamp;

    int64_t pos;



    if (s->pb->eof_reached)

        return AVERROR_EOF;

    pos   = avio_tell(s->pb);

    dtype = avio_rl32(s->pb);

    switch (dtype) {

    case SMJPEG_SNDD:

        timestamp = avio_rb32(s->pb);

        size = avio_rb32(s->pb);

        ret = av_get_packet(s->pb, pkt, size);

        pkt->stream_index = sc->audio_stream_index;

        pkt->pts = timestamp;

        pkt->pos = pos;

        break;

    case SMJPEG_VIDD:

        timestamp = avio_rb32(s->pb);

        size = avio_rb32(s->pb);

        ret = av_get_packet(s->pb, pkt, size);

        pkt->stream_index = sc->video_stream_index;

        pkt->pts = timestamp;

        pkt->pos = pos;

        break;

    case SMJPEG_DONE:

        ret = AVERROR_EOF;

        break;

    default:

        av_log(s, AV_LOG_ERROR, "unknown chunk %x\n", dtype);

        ret = AVERROR_INVALIDDATA;

        break;

    }

    return ret;

}

static int vc1_decode_p_mb(VC1Context *v)

{

    MpegEncContext *s = &v->s;

    GetBitContext *gb = &s->gb;

    int i, j;

    int mb_pos = s->mb_x + s->mb_y * s->mb_stride;

    int cbp; /* cbp decoding stuff */

    int mqdiff, mquant; /* MB quantization */

    int ttmb = v->ttfrm; /* MB Transform type */



    int mb_has_coeffs = 1; /* last_flag */

    int dmv_x, dmv_y; /* Differential MV components */

    int index, index1; /* LUT indexes */

    int val, sign; /* temp values */

    int first_block = 1;

    int dst_idx, off;

    int skipped, fourmv;

    int block_cbp = 0, pat;

    int apply_loop_filter;



    mquant = v->pq; /* Loosy initialization */



    if (v->mv_type_is_raw)

        fourmv = get_bits1(gb);

    else

        fourmv = v->mv_type_mb_plane[mb_pos];

    if (v->skip_is_raw)

        skipped = get_bits1(gb);

    else

        skipped = v->s.mbskip_table[mb_pos];



    s->dsp.clear_blocks(s->block[0]);



    apply_loop_filter = s->loop_filter && !(s->avctx->skip_loop_filter >= AVDISCARD_NONKEY);

    if (!fourmv) /* 1MV mode */

    {

        if (!skipped)

        {

            GET_MVDATA(dmv_x, dmv_y);



            if (s->mb_intra) {

                s->current_picture.motion_val[1][s->block_index[0]][0] = 0;

                s->current_picture.motion_val[1][s->block_index[0]][1] = 0;

            }

            s->current_picture.mb_type[mb_pos] = s->mb_intra ? MB_TYPE_INTRA : MB_TYPE_16x16;

            vc1_pred_mv(s, 0, dmv_x, dmv_y, 1, v->range_x, v->range_y, v->mb_type[0]);



            /* FIXME Set DC val for inter block ? */

            if (s->mb_intra && !mb_has_coeffs)

            {

                GET_MQUANT();

                s->ac_pred = get_bits1(gb);

                cbp = 0;

            }

            else if (mb_has_coeffs)

            {

                if (s->mb_intra) s->ac_pred = get_bits1(gb);

                cbp = get_vlc2(&v->s.gb, v->cbpcy_vlc->table, VC1_CBPCY_P_VLC_BITS, 2);

                GET_MQUANT();

            }

            else

            {

                mquant = v->pq;

                cbp = 0;

            }

            s->current_picture.qscale_table[mb_pos] = mquant;



            if (!v->ttmbf && !s->mb_intra && mb_has_coeffs)

                ttmb = get_vlc2(gb, ff_vc1_ttmb_vlc[v->tt_index].table,

                                VC1_TTMB_VLC_BITS, 2);

            if(!s->mb_intra) vc1_mc_1mv(v, 0);

            dst_idx = 0;

            for (i=0; i<6; i++)

            {

                s->dc_val[0][s->block_index[i]] = 0;

                dst_idx += i >> 2;

                val = ((cbp >> (5 - i)) & 1);

                off = (i & 4) ? 0 : ((i & 1) * 8 + (i & 2) * 4 * s->linesize);

                v->mb_type[0][s->block_index[i]] = s->mb_intra;

                if(s->mb_intra) {

                    /* check if prediction blocks A and C are available */

                    v->a_avail = v->c_avail = 0;

                    if(i == 2 || i == 3 || !s->first_slice_line)

                        v->a_avail = v->mb_type[0][s->block_index[i] - s->block_wrap[i]];

                    if(i == 1 || i == 3 || s->mb_x)

                        v->c_avail = v->mb_type[0][s->block_index[i] - 1];



                    vc1_decode_intra_block(v, s->block[i], i, val, mquant, (i&4)?v->codingset2:v->codingset);

                    if((i>3) && (s->flags & CODEC_FLAG_GRAY)) continue;

                    s->dsp.vc1_inv_trans_8x8(s->block[i]);

                    if(v->rangeredfrm) for(j = 0; j < 64; j++) s->block[i][j] <<= 1;

                    s->dsp.put_signed_pixels_clamped(s->block[i], s->dest[dst_idx] + off, s->linesize >> ((i & 4) >> 2));

                    if(v->pq >= 9 && v->overlap) {

                        if(v->c_avail)

                            s->dsp.vc1_h_overlap(s->dest[dst_idx] + off, s->linesize >> ((i & 4) >> 2));

                        if(v->a_avail)

                            s->dsp.vc1_v_overlap(s->dest[dst_idx] + off, s->linesize >> ((i & 4) >> 2));

                    }

                    if(apply_loop_filter && s->mb_x && s->mb_x != (s->mb_width - 1) && s->mb_y && s->mb_y != (s->mb_height - 1)){

                        int left_cbp, top_cbp;

                        if(i & 4){

                            left_cbp = v->cbp[s->mb_x - 1]            >> (i * 4);

                            top_cbp  = v->cbp[s->mb_x - s->mb_stride] >> (i * 4);

                        }else{

                            left_cbp = (i & 1) ? (cbp >> ((i-1)*4)) : (v->cbp[s->mb_x - 1]           >> ((i+1)*4));

                            top_cbp  = (i & 2) ? (cbp >> ((i-2)*4)) : (v->cbp[s->mb_x - s->mb_stride] >> ((i+2)*4));

                        }

                        if(left_cbp & 0xC)

                            s->dsp.vc1_loop_filter(s->dest[dst_idx] + off, 1, i & 4 ? s->uvlinesize : s->linesize, 8, mquant);

                        if(top_cbp  & 0xA)

                            s->dsp.vc1_loop_filter(s->dest[dst_idx] + off, i & 4 ? s->uvlinesize : s->linesize, 1, 8, mquant);

                    }

                    block_cbp |= 0xF << (i << 2);

                } else if(val) {

                    int left_cbp = 0, top_cbp = 0, filter = 0;

                    if(apply_loop_filter && s->mb_x && s->mb_x != (s->mb_width - 1) && s->mb_y && s->mb_y != (s->mb_height - 1)){

                        filter = 1;

                        if(i & 4){

                            left_cbp = v->cbp[s->mb_x - 1]            >> (i * 4);

                            top_cbp  = v->cbp[s->mb_x - s->mb_stride] >> (i * 4);

                        }else{

                            left_cbp = (i & 1) ? (cbp >> ((i-1)*4)) : (v->cbp[s->mb_x - 1]           >> ((i+1)*4));

                            top_cbp  = (i & 2) ? (cbp >> ((i-2)*4)) : (v->cbp[s->mb_x - s->mb_stride] >> ((i+2)*4));

                        }

                        if(left_cbp & 0xC)

                            s->dsp.vc1_loop_filter(s->dest[dst_idx] + off, 1, i & 4 ? s->uvlinesize : s->linesize, 8, mquant);

                        if(top_cbp  & 0xA)

                            s->dsp.vc1_loop_filter(s->dest[dst_idx] + off, i & 4 ? s->uvlinesize : s->linesize, 1, 8, mquant);

                    }

                    pat = vc1_decode_p_block(v, s->block[i], i, mquant, ttmb, first_block, s->dest[dst_idx] + off, (i&4)?s->uvlinesize:s->linesize, (i&4) && (s->flags & CODEC_FLAG_GRAY), filter, left_cbp, top_cbp);

                    block_cbp |= pat << (i << 2);

                    if(!v->ttmbf && ttmb < 8) ttmb = -1;

                    first_block = 0;

                }

            }

        }

        else //Skipped

        {

            s->mb_intra = 0;

            for(i = 0; i < 6; i++) {

                v->mb_type[0][s->block_index[i]] = 0;

                s->dc_val[0][s->block_index[i]] = 0;

            }

            s->current_picture.mb_type[mb_pos] = MB_TYPE_SKIP;

            s->current_picture.qscale_table[mb_pos] = 0;

            vc1_pred_mv(s, 0, 0, 0, 1, v->range_x, v->range_y, v->mb_type[0]);

            vc1_mc_1mv(v, 0);

            return 0;

        }

    } //1MV mode

    else //4MV mode

    {

        if (!skipped /* unskipped MB */)

        {

            int intra_count = 0, coded_inter = 0;

            int is_intra[6], is_coded[6];

            /* Get CBPCY */

            cbp = get_vlc2(&v->s.gb, v->cbpcy_vlc->table, VC1_CBPCY_P_VLC_BITS, 2);

            for (i=0; i<6; i++)

            {

                val = ((cbp >> (5 - i)) & 1);

                s->dc_val[0][s->block_index[i]] = 0;

                s->mb_intra = 0;

                if(i < 4) {

                    dmv_x = dmv_y = 0;

                    s->mb_intra = 0;

                    mb_has_coeffs = 0;

                    if(val) {

                        GET_MVDATA(dmv_x, dmv_y);

                    }

                    vc1_pred_mv(s, i, dmv_x, dmv_y, 0, v->range_x, v->range_y, v->mb_type[0]);

                    if(!s->mb_intra) vc1_mc_4mv_luma(v, i);

                    intra_count += s->mb_intra;

                    is_intra[i] = s->mb_intra;

                    is_coded[i] = mb_has_coeffs;

                }

                if(i&4){

                    is_intra[i] = (intra_count >= 3);

                    is_coded[i] = val;

                }

                if(i == 4) vc1_mc_4mv_chroma(v);

                v->mb_type[0][s->block_index[i]] = is_intra[i];

                if(!coded_inter) coded_inter = !is_intra[i] & is_coded[i];

            }

            // if there are no coded blocks then don't do anything more

            if(!intra_count && !coded_inter) return 0;

            dst_idx = 0;

            GET_MQUANT();

            s->current_picture.qscale_table[mb_pos] = mquant;

            /* test if block is intra and has pred */

            {

                int intrapred = 0;

                for(i=0; i<6; i++)

                    if(is_intra[i]) {

                        if(((!s->first_slice_line || (i==2 || i==3)) && v->mb_type[0][s->block_index[i] - s->block_wrap[i]])

                            || ((s->mb_x || (i==1 || i==3)) && v->mb_type[0][s->block_index[i] - 1])) {

                            intrapred = 1;

                            break;

                        }

                    }

                if(intrapred)s->ac_pred = get_bits1(gb);

                else s->ac_pred = 0;

            }

            if (!v->ttmbf && coded_inter)

                ttmb = get_vlc2(gb, ff_vc1_ttmb_vlc[v->tt_index].table, VC1_TTMB_VLC_BITS, 2);

            for (i=0; i<6; i++)

            {

                dst_idx += i >> 2;

                off = (i & 4) ? 0 : ((i & 1) * 8 + (i & 2) * 4 * s->linesize);

                s->mb_intra = is_intra[i];

                if (is_intra[i]) {

                    /* check if prediction blocks A and C are available */

                    v->a_avail = v->c_avail = 0;

                    if(i == 2 || i == 3 || !s->first_slice_line)

                        v->a_avail = v->mb_type[0][s->block_index[i] - s->block_wrap[i]];

                    if(i == 1 || i == 3 || s->mb_x)

                        v->c_avail = v->mb_type[0][s->block_index[i] - 1];



                    vc1_decode_intra_block(v, s->block[i], i, is_coded[i], mquant, (i&4)?v->codingset2:v->codingset);

                    if((i>3) && (s->flags & CODEC_FLAG_GRAY)) continue;

                    s->dsp.vc1_inv_trans_8x8(s->block[i]);

                    if(v->rangeredfrm) for(j = 0; j < 64; j++) s->block[i][j] <<= 1;

                    s->dsp.put_signed_pixels_clamped(s->block[i], s->dest[dst_idx] + off, (i&4)?s->uvlinesize:s->linesize);

                    if(v->pq >= 9 && v->overlap) {

                        if(v->c_avail)

                            s->dsp.vc1_h_overlap(s->dest[dst_idx] + off, s->linesize >> ((i & 4) >> 2));

                        if(v->a_avail)

                            s->dsp.vc1_v_overlap(s->dest[dst_idx] + off, s->linesize >> ((i & 4) >> 2));

                    }

                    if(v->s.loop_filter && s->mb_x && s->mb_x != (s->mb_width - 1) && s->mb_y && s->mb_y != (s->mb_height - 1)){

                        int left_cbp, top_cbp;

                        if(i & 4){

                            left_cbp = v->cbp[s->mb_x - 1]            >> (i * 4);

                            top_cbp  = v->cbp[s->mb_x - s->mb_stride] >> (i * 4);

                        }else{

                            left_cbp = (i & 1) ? (cbp >> ((i-1)*4)) : (v->cbp[s->mb_x - 1]           >> ((i+1)*4));

                            top_cbp  = (i & 2) ? (cbp >> ((i-2)*4)) : (v->cbp[s->mb_x - s->mb_stride] >> ((i+2)*4));

                        }

                        if(left_cbp & 0xC)

                            s->dsp.vc1_loop_filter(s->dest[dst_idx] + off, 1, i & 4 ? s->uvlinesize : s->linesize, 8, mquant);

                        if(top_cbp  & 0xA)

                            s->dsp.vc1_loop_filter(s->dest[dst_idx] + off, i & 4 ? s->uvlinesize : s->linesize, 1, 8, mquant);

                    }

                    block_cbp |= 0xF << (i << 2);

                } else if(is_coded[i]) {

                    int left_cbp = 0, top_cbp = 0, filter = 0;

                    if(v->s.loop_filter && s->mb_x && s->mb_x != (s->mb_width - 1) && s->mb_y && s->mb_y != (s->mb_height - 1)){

                        filter = 1;

                        if(i & 4){

                            left_cbp = v->cbp[s->mb_x - 1]            >> (i * 4);

                            top_cbp  = v->cbp[s->mb_x - s->mb_stride] >> (i * 4);

                        }else{

                            left_cbp = (i & 1) ? (cbp >> ((i-1)*4)) : (v->cbp[s->mb_x - 1]           >> ((i+1)*4));

                            top_cbp  = (i & 2) ? (cbp >> ((i-2)*4)) : (v->cbp[s->mb_x - s->mb_stride] >> ((i+2)*4));

                        }

                        if(left_cbp & 0xC)

                            s->dsp.vc1_loop_filter(s->dest[dst_idx] + off, 1, i & 4 ? s->uvlinesize : s->linesize, 8, mquant);

                        if(top_cbp  & 0xA)

                            s->dsp.vc1_loop_filter(s->dest[dst_idx] + off, i & 4 ? s->uvlinesize : s->linesize, 1, 8, mquant);

                    }

                    pat = vc1_decode_p_block(v, s->block[i], i, mquant, ttmb, first_block, s->dest[dst_idx] + off, (i&4)?s->uvlinesize:s->linesize, (i&4) && (s->flags & CODEC_FLAG_GRAY), filter, left_cbp, top_cbp);

                    block_cbp |= pat << (i << 2);

                    if(!v->ttmbf && ttmb < 8) ttmb = -1;

                    first_block = 0;

                }

            }

            return 0;

        }

        else //Skipped MB

        {

            s->mb_intra = 0;

            s->current_picture.qscale_table[mb_pos] = 0;

            for (i=0; i<6; i++) {

                v->mb_type[0][s->block_index[i]] = 0;

                s->dc_val[0][s->block_index[i]] = 0;

            }

            for (i=0; i<4; i++)

            {

                vc1_pred_mv(s, i, 0, 0, 0, v->range_x, v->range_y, v->mb_type[0]);

                vc1_mc_4mv_luma(v, i);

            }

            vc1_mc_4mv_chroma(v);

            s->current_picture.qscale_table[mb_pos] = 0;

            return 0;

        }

    }

    v->cbp[s->mb_x] = block_cbp;



    /* Should never happen */

    return -1;

}

static void hybrid6_cx(float (*in)[2], float (*out)[32][2], const float (*filter)[7][2], int len)

{

    int i, j, ssb;

    int N = 8;

    float temp[8][2];



    for (i = 0; i < len; i++, in++) {

        for (ssb = 0; ssb < N; ssb++) {

            float sum_re = filter[ssb][6][0] * in[6][0], sum_im = filter[ssb][6][0] * in[6][1];

            for (j = 0; j < 6; j++) {

                float in0_re = in[j][0];

                float in0_im = in[j][1];

                float in1_re = in[12-j][0];

                float in1_im = in[12-j][1];

                sum_re += filter[ssb][j][0] * (in0_re + in1_re) - filter[ssb][j][1] * (in0_im - in1_im);

                sum_im += filter[ssb][j][0] * (in0_im + in1_im) + filter[ssb][j][1] * (in0_re - in1_re);

            }

            temp[ssb][0] = sum_re;

            temp[ssb][1] = sum_im;

        }

        out[0][i][0] = temp[6][0];

        out[0][i][1] = temp[6][1];

        out[1][i][0] = temp[7][0];

        out[1][i][1] = temp[7][1];

        out[2][i][0] = temp[0][0];

        out[2][i][1] = temp[0][1];

        out[3][i][0] = temp[1][0];

        out[3][i][1] = temp[1][1];

        out[4][i][0] = temp[2][0] + temp[5][0];

        out[4][i][1] = temp[2][1] + temp[5][1];

        out[5][i][0] = temp[3][0] + temp[4][0];

        out[5][i][1] = temp[3][1] + temp[4][1];

    }

}

static void RENAME(yuv2yuv1)(SwsContext *c, const int16_t *lumSrc,

                             const int16_t *chrUSrc, const int16_t *chrVSrc,

                             const int16_t *alpSrc,

                             uint8_t *dest, uint8_t *uDest, uint8_t *vDest,

                             uint8_t *aDest, int dstW, int chrDstW)

{

    int p= 4;

    const int16_t *src[4]= { alpSrc + dstW, lumSrc + dstW, chrUSrc + chrDstW, chrVSrc + chrDstW };

    uint8_t *dst[4]= { aDest, dest, uDest, vDest };

    x86_reg counter[4]= { dstW, dstW, chrDstW, chrDstW };



    while (p--) {

        if (dst[p]) {

            __asm__ volatile(

                "mov %2, %%"REG_a"                    \n\t"

                ".p2align               4             \n\t" /* FIXME Unroll? */

                "1:                                   \n\t"

                "movq  (%0, %%"REG_a", 2), %%mm0      \n\t"

                "movq 8(%0, %%"REG_a", 2), %%mm1      \n\t"

                "psraw                 $7, %%mm0      \n\t"

                "psraw                 $7, %%mm1      \n\t"

                "packuswb           %%mm1, %%mm0      \n\t"

                MOVNTQ(%%mm0, (%1, %%REGa))

                "add                   $8, %%"REG_a"  \n\t"

                "jnc                   1b             \n\t"

                :: "r" (src[p]), "r" (dst[p] + counter[p]),

                   "g" (-counter[p])

                : "%"REG_a

            );

        }

    }

}

static int vp3_decode_frame(AVCodecContext *avctx,

                            void *data, int *data_size,

                            const uint8_t *buf, int buf_size)

{

    Vp3DecodeContext *s = avctx->priv_data;

    GetBitContext gb;

    static int counter = 0;

    int i;



    init_get_bits(&gb, buf, buf_size * 8);



    if (s->theora && get_bits1(&gb))

    {

        av_log(avctx, AV_LOG_ERROR, "Header packet passed to frame decoder, skipping\n");

        return -1;

    }



    s->keyframe = !get_bits1(&gb);

    if (!s->theora)

        skip_bits(&gb, 1);

    s->last_quality_index = s->quality_index;



    s->nqis=0;

    do{

        s->qis[s->nqis++]= get_bits(&gb, 6);

    } while(s->theora >= 0x030200 && s->nqis<3 && get_bits1(&gb));



    s->quality_index= s->qis[0];



    if (s->avctx->debug & FF_DEBUG_PICT_INFO)

        av_log(s->avctx, AV_LOG_INFO, " VP3 %sframe #%d: Q index = %d\n",

            s->keyframe?"key":"", counter, s->quality_index);

    counter++;



    if (s->quality_index != s->last_quality_index) {

        init_dequantizer(s);

        init_loop_filter(s);

    }



    if (s->keyframe) {

        if (!s->theora)

        {

            skip_bits(&gb, 4); /* width code */

            skip_bits(&gb, 4); /* height code */

            if (s->version)

            {

                s->version = get_bits(&gb, 5);

                if (counter == 1)

                    av_log(s->avctx, AV_LOG_DEBUG, "VP version: %d\n", s->version);

            }

        }

        if (s->version || s->theora)

        {

                if (get_bits1(&gb))

                    av_log(s->avctx, AV_LOG_ERROR, "Warning, unsupported keyframe coding type?!\n");

            skip_bits(&gb, 2); /* reserved? */

        }



        if (s->last_frame.data[0] == s->golden_frame.data[0]) {

            if (s->golden_frame.data[0])

                avctx->release_buffer(avctx, &s->golden_frame);

            s->last_frame= s->golden_frame; /* ensure that we catch any access to this released frame */

        } else {

            if (s->golden_frame.data[0])

                avctx->release_buffer(avctx, &s->golden_frame);

            if (s->last_frame.data[0])

                avctx->release_buffer(avctx, &s->last_frame);

        }



        s->golden_frame.reference = 3;

        if(avctx->get_buffer(avctx, &s->golden_frame) < 0) {

            av_log(s->avctx, AV_LOG_ERROR, "vp3: get_buffer() failed\n");

            return -1;

        }



        /* golden frame is also the current frame */

        s->current_frame= s->golden_frame;



        /* time to figure out pixel addresses? */

        if (!s->pixel_addresses_inited)

        {

            if (!s->flipped_image)

                vp3_calculate_pixel_addresses(s);

            else

                theora_calculate_pixel_addresses(s);

            s->pixel_addresses_inited = 1;

        }

    } else {

        /* allocate a new current frame */

        s->current_frame.reference = 3;

        if (!s->pixel_addresses_inited) {

            av_log(s->avctx, AV_LOG_ERROR, "vp3: first frame not a keyframe\n");

            return -1;

        }

        if(avctx->get_buffer(avctx, &s->current_frame) < 0) {

            av_log(s->avctx, AV_LOG_ERROR, "vp3: get_buffer() failed\n");

            return -1;

        }

    }



    s->current_frame.qscale_table= s->qscale_table; //FIXME allocate individual tables per AVFrame

    s->current_frame.qstride= 0;



    {START_TIMER

    init_frame(s, &gb);

    STOP_TIMER("init_frame")}



#if KEYFRAMES_ONLY

if (!s->keyframe) {



    memcpy(s->current_frame.data[0], s->golden_frame.data[0],

        s->current_frame.linesize[0] * s->height);

    memcpy(s->current_frame.data[1], s->golden_frame.data[1],

        s->current_frame.linesize[1] * s->height / 2);

    memcpy(s->current_frame.data[2], s->golden_frame.data[2],

        s->current_frame.linesize[2] * s->height / 2);



} else {

#endif



    {START_TIMER

    if (unpack_superblocks(s, &gb)){

        av_log(s->avctx, AV_LOG_ERROR, "error in unpack_superblocks\n");

        return -1;

    }

    STOP_TIMER("unpack_superblocks")}

    {START_TIMER

    if (unpack_modes(s, &gb)){

        av_log(s->avctx, AV_LOG_ERROR, "error in unpack_modes\n");

        return -1;

    }

    STOP_TIMER("unpack_modes")}

    {START_TIMER

    if (unpack_vectors(s, &gb)){

        av_log(s->avctx, AV_LOG_ERROR, "error in unpack_vectors\n");

        return -1;

    }

    STOP_TIMER("unpack_vectors")}

    {START_TIMER

    if (unpack_dct_coeffs(s, &gb)){

        av_log(s->avctx, AV_LOG_ERROR, "error in unpack_dct_coeffs\n");

        return -1;

    }

    STOP_TIMER("unpack_dct_coeffs")}

    {START_TIMER



    reverse_dc_prediction(s, 0, s->fragment_width, s->fragment_height);

    if ((avctx->flags & CODEC_FLAG_GRAY) == 0) {

        reverse_dc_prediction(s, s->fragment_start[1],

            s->fragment_width / 2, s->fragment_height / 2);

        reverse_dc_prediction(s, s->fragment_start[2],

            s->fragment_width / 2, s->fragment_height / 2);

    }

    STOP_TIMER("reverse_dc_prediction")}

    {START_TIMER



    for (i = 0; i < s->macroblock_height; i++)

        render_slice(s, i);

    STOP_TIMER("render_fragments")}



    {START_TIMER

    apply_loop_filter(s);

    STOP_TIMER("apply_loop_filter")}

#if KEYFRAMES_ONLY

}

#endif



    *data_size=sizeof(AVFrame);

    *(AVFrame*)data= s->current_frame;



    /* release the last frame, if it is allocated and if it is not the

     * golden frame */

    if ((s->last_frame.data[0]) &&

        (s->last_frame.data[0] != s->golden_frame.data[0]))

        avctx->release_buffer(avctx, &s->last_frame);



    /* shuffle frames (last = current) */

    s->last_frame= s->current_frame;

    s->current_frame.data[0]= NULL; /* ensure that we catch any access to this released frame */



    return buf_size;

}

static char *ts_value_string (char *buf, int buf_size, int64_t ts)

