static int configure_video_filters(FilterGraph *fg)

{

    InputStream  *ist = fg->inputs[0]->ist;

    OutputStream *ost = fg->outputs[0]->ost;

    AVFilterContext *in_filter, *out_filter, *filter;

    AVCodecContext *codec = ost->st->codec;

    AVBufferSinkParams *buffersink_params = av_buffersink_params_alloc();

    char *pix_fmts;

    AVRational sample_aspect_ratio;

    char args[255];

    int ret;



    avfilter_graph_free(&fg->graph);

    fg->graph = avfilter_graph_alloc();

    if (!fg->graph)

        return AVERROR(ENOMEM);



    if (ist->st->sample_aspect_ratio.num) {

        sample_aspect_ratio = ist->st->sample_aspect_ratio;

    } else

        sample_aspect_ratio = ist->st->codec->sample_aspect_ratio;



    snprintf(args, 255, "%d:%d:%d:%d:%d:%d:%d:flags=%d", ist->st->codec->width,

             ist->st->codec->height, ist->st->codec->pix_fmt, 1, AV_TIME_BASE,

             sample_aspect_ratio.num, sample_aspect_ratio.den, SWS_BILINEAR + ((ist->st->codec->flags&CODEC_FLAG_BITEXACT) ? SWS_BITEXACT:0));



    ret = avfilter_graph_create_filter(&fg->inputs[0]->filter,

                                       avfilter_get_by_name("buffer"),

                                       "src", args, NULL, fg->graph);

    if (ret < 0)

        return ret;



#if FF_API_OLD_VSINK_API

    ret = avfilter_graph_create_filter(&fg->outputs[0]->filter,

                                       avfilter_get_by_name("buffersink"),

                                       "out", NULL, NULL, fg->graph);

#else

    ret = avfilter_graph_create_filter(&fg->outputs[0]->filter,

                                       avfilter_get_by_name("buffersink"),

                                       "out", NULL, buffersink_params, fg->graph);

#endif

    av_freep(&buffersink_params);



    if (ret < 0)

        return ret;

    in_filter  = fg->inputs[0]->filter;

    out_filter = fg->outputs[0]->filter;



    if (codec->width || codec->height) {

        snprintf(args, 255, "%d:%d:flags=0x%X",

                 codec->width,

                 codec->height,

                 (unsigned)ost->sws_flags);

        if ((ret = avfilter_graph_create_filter(&filter, avfilter_get_by_name("scale"),

                                                NULL, args, NULL, fg->graph)) < 0)

            return ret;

        if ((ret = avfilter_link(in_filter, 0, filter, 0)) < 0)

            return ret;

        in_filter = filter;

    }



    if ((pix_fmts = choose_pixel_fmts(ost))) {

        if ((ret = avfilter_graph_create_filter(&filter,

                                                avfilter_get_by_name("format"),

                                                "format", pix_fmts, NULL,

                                                fg->graph)) < 0)

            return ret;

        if ((ret = avfilter_link(filter, 0, out_filter, 0)) < 0)

            return ret;



        out_filter = filter;

        av_freep(&pix_fmts);

    }



    snprintf(args, sizeof(args), "flags=0x%X", (unsigned)ost->sws_flags);

    fg->graph->scale_sws_opts = av_strdup(args);



    if (ost->avfilter) {

        AVFilterInOut *outputs = avfilter_inout_alloc();

        AVFilterInOut *inputs  = avfilter_inout_alloc();



        outputs->name    = av_strdup("in");

        outputs->filter_ctx = in_filter;

        outputs->pad_idx = 0;

        outputs->next    = NULL;



        inputs->name    = av_strdup("out");

        inputs->filter_ctx = out_filter;

        inputs->pad_idx = 0;

        inputs->next    = NULL;



        if ((ret = avfilter_graph_parse(fg->graph, ost->avfilter, &inputs, &outputs, NULL)) < 0)

            return ret;

        av_freep(&ost->avfilter);

    } else {

        if ((ret = avfilter_link(in_filter, 0, out_filter, 0)) < 0)

            return ret;

    }



    if (ost->keep_pix_fmt)

        avfilter_graph_set_auto_convert(fg->graph,

                                        AVFILTER_AUTO_CONVERT_NONE);



    if ((ret = avfilter_graph_config(fg->graph, NULL)) < 0)

        return ret;



    ost->filter = fg->outputs[0];



    return 0;

}

static int mov_write_moov_tag(ByteIOContext *pb, MOVContext *mov)

{

    int pos, i;

    pos = url_ftell(pb);

    put_be32(pb, 0); /* size placeholder*/

    put_tag(pb, "moov");

    mov->timescale = globalTimescale;



    for (i=0; i<MAX_STREAMS; i++) {

        if(mov->tracks[i].entry <= 0) continue;



        if(mov->tracks[i].enc->codec_type == CODEC_TYPE_VIDEO) {

            mov->tracks[i].timescale = mov->tracks[i].enc->frame_rate;

            mov->tracks[i].sampleDuration = mov->tracks[i].enc->frame_rate_base;

        }

        else if(mov->tracks[i].enc->codec_type == CODEC_TYPE_AUDIO) {

            /* If AMR, track timescale = 8000, AMR_WB = 16000 */

            if(mov->tracks[i].enc->codec_id == CODEC_ID_AMR_NB) {

                mov->tracks[i].sampleDuration = 160;  // Bytes per chunk

                mov->tracks[i].timescale = 8000;

            }

            else {

                mov->tracks[i].timescale = mov->tracks[i].enc->sample_rate;

                mov->tracks[i].sampleDuration = mov->tracks[i].enc->frame_size;

            }

        }



        mov->tracks[i].trackDuration = 

            mov->tracks[i].sampleCount * mov->tracks[i].sampleDuration;

        mov->tracks[i].time = mov->time;

        mov->tracks[i].trackID = i+1;

    }



    mov_write_mvhd_tag(pb, mov);

    //mov_write_iods_tag(pb, mov);

    for (i=0; i<MAX_STREAMS; i++) {

        if(mov->tracks[i].entry > 0) {

            mov_write_trak_tag(pb, &(mov->tracks[i]));

        }

    }



    return updateSize(pb, pos);

}

int ff_h264_decode_slice_header(H264Context *h, H264SliceContext *sl)

{

    const SPS *sps;

    const PPS *pps;

    unsigned int first_mb_in_slice;

    unsigned int pps_id;

    int ret;

    unsigned int slice_type, tmp, i, j;

    int last_pic_structure, last_pic_droppable;

    int needs_reinit = 0;

    int field_pic_flag, bottom_field_flag;

    int frame_num, droppable, picture_structure;

    int mb_aff_frame = 0;



    h->qpel_put = h->h264qpel.put_h264_qpel_pixels_tab;

    h->qpel_avg = h->h264qpel.avg_h264_qpel_pixels_tab;



    first_mb_in_slice = get_ue_golomb(&sl->gb);



    if (first_mb_in_slice == 0) { // FIXME better field boundary detection

        if (h->current_slice && h->cur_pic_ptr && FIELD_PICTURE(h)) {

            ff_h264_field_end(h, sl, 1);

        }



        h->current_slice = 0;

        if (!h->first_field) {

            if (h->cur_pic_ptr && !h->droppable) {

                ff_thread_report_progress(&h->cur_pic_ptr->tf, INT_MAX,

                                          h->picture_structure == PICT_BOTTOM_FIELD);

            }

            h->cur_pic_ptr = NULL;

        }

    }



    slice_type = get_ue_golomb_31(&sl->gb);

    if (slice_type > 9) {

        av_log(h->avctx, AV_LOG_ERROR,

               "slice type %d too large at %d\n",

               slice_type, first_mb_in_slice);

        return AVERROR_INVALIDDATA;

    }

    if (slice_type > 4) {

        slice_type -= 5;

        sl->slice_type_fixed = 1;

    } else

        sl->slice_type_fixed = 0;



    slice_type         = ff_h264_golomb_to_pict_type[slice_type];

    sl->slice_type     = slice_type;

    sl->slice_type_nos = slice_type & 3;



    if (h->nal_unit_type  == NAL_IDR_SLICE &&

        sl->slice_type_nos != AV_PICTURE_TYPE_I) {

        av_log(h->avctx, AV_LOG_ERROR, "A non-intra slice in an IDR NAL unit.\n");

        return AVERROR_INVALIDDATA;

    }



    // to make a few old functions happy, it's wrong though

    if (!h->setup_finished)

        h->pict_type = sl->slice_type;



    pps_id = get_ue_golomb(&sl->gb);

    if (pps_id >= MAX_PPS_COUNT) {

        av_log(h->avctx, AV_LOG_ERROR, "pps_id %u out of range\n", pps_id);

        return AVERROR_INVALIDDATA;

    }

    if (!h->ps.pps_list[pps_id]) {

        av_log(h->avctx, AV_LOG_ERROR,

               "non-existing PPS %u referenced\n",

               pps_id);

        return AVERROR_INVALIDDATA;

    }

    if (!h->setup_finished) {

        h->ps.pps = (const PPS*)h->ps.pps_list[pps_id]->data;

    } else if (h->ps.pps != (const PPS*)h->ps.pps_list[pps_id]->data) {

        av_log(h->avctx, AV_LOG_ERROR, "PPS changed between slices\n");

        return AVERROR_INVALIDDATA;

    }



    if (!h->ps.sps_list[h->ps.pps->sps_id]) {

        av_log(h->avctx, AV_LOG_ERROR,

               "non-existing SPS %u referenced\n",

               h->ps.pps->sps_id);

        return AVERROR_INVALIDDATA;

    }



    if (h->ps.sps != (const SPS*)h->ps.sps_list[h->ps.pps->sps_id]->data) {

        h->ps.sps = (SPS*)h->ps.sps_list[h->ps.pps->sps_id]->data;



        if (h->bit_depth_luma    != h->ps.sps->bit_depth_luma ||

            h->chroma_format_idc != h->ps.sps->chroma_format_idc)

            needs_reinit         = 1;



        if (h->flags & AV_CODEC_FLAG_LOW_DELAY ||

            (h->ps.sps->bitstream_restriction_flag &&

             !h->ps.sps->num_reorder_frames)) {

            if (h->avctx->has_b_frames > 1 || h->delayed_pic[0])

                av_log(h->avctx, AV_LOG_WARNING, "Delayed frames seen. "

                       "Reenabling low delay requires a codec flush.\n");

            else

                h->low_delay = 1;

        }



        if (h->avctx->has_b_frames < 2)

            h->avctx->has_b_frames = !h->low_delay;



    }



    pps = h->ps.pps;

    sps = h->ps.sps;



    if (!h->setup_finished) {

        h->avctx->profile = ff_h264_get_profile(sps);

        h->avctx->level   = sps->level_idc;

        h->avctx->refs    = sps->ref_frame_count;



        if (h->mb_width  != sps->mb_width ||

            h->mb_height != sps->mb_height * (2 - sps->frame_mbs_only_flag))

            needs_reinit = 1;



        h->mb_width  = sps->mb_width;

        h->mb_height = sps->mb_height * (2 - sps->frame_mbs_only_flag);

        h->mb_num    = h->mb_width * h->mb_height;

        h->mb_stride = h->mb_width + 1;



        h->b_stride = h->mb_width * 4;



        h->chroma_y_shift = sps->chroma_format_idc <= 1; // 400 uses yuv420p



        h->width  = 16 * h->mb_width;

        h->height = 16 * h->mb_height;



        ret = init_dimensions(h);

        if (ret < 0)

            return ret;



        if (sps->video_signal_type_present_flag) {

            h->avctx->color_range = sps->full_range ? AVCOL_RANGE_JPEG

                : AVCOL_RANGE_MPEG;

            if (sps->colour_description_present_flag) {

                if (h->avctx->colorspace != sps->colorspace)

                    needs_reinit = 1;

                h->avctx->color_primaries = sps->color_primaries;

                h->avctx->color_trc       = sps->color_trc;

                h->avctx->colorspace      = sps->colorspace;

            }

        }

    }



    if (h->context_initialized && needs_reinit) {

        h->context_initialized = 0;

        if (sl != h->slice_ctx) {

            av_log(h->avctx, AV_LOG_ERROR,

                   "changing width %d -> %d / height %d -> %d on "

                   "slice %d\n",

                   h->width, h->avctx->coded_width,

                   h->height, h->avctx->coded_height,

                   h->current_slice + 1);

            return AVERROR_INVALIDDATA;

        }



        ff_h264_flush_change(h);



        if ((ret = get_pixel_format(h)) < 0)

            return ret;

        h->avctx->pix_fmt = ret;



        av_log(h->avctx, AV_LOG_INFO, "Reinit context to %dx%d, "

               "pix_fmt: %d\n", h->width, h->height, h->avctx->pix_fmt);



        if ((ret = h264_slice_header_init(h)) < 0) {

            av_log(h->avctx, AV_LOG_ERROR,

                   "h264_slice_header_init() failed\n");

            return ret;

        }

    }

    if (!h->context_initialized) {

        if (sl != h->slice_ctx) {

            av_log(h->avctx, AV_LOG_ERROR,

                   "Cannot (re-)initialize context during parallel decoding.\n");

            return AVERROR_PATCHWELCOME;

        }



        if ((ret = get_pixel_format(h)) < 0)

            return ret;

        h->avctx->pix_fmt = ret;



        if ((ret = h264_slice_header_init(h)) < 0) {

            av_log(h->avctx, AV_LOG_ERROR,

                   "h264_slice_header_init() failed\n");

            return ret;

        }

    }



    frame_num = get_bits(&sl->gb, sps->log2_max_frame_num);

    if (!h->setup_finished)

        h->frame_num = frame_num;



    sl->mb_mbaff       = 0;



    last_pic_structure = h->picture_structure;

    last_pic_droppable = h->droppable;



    droppable = h->nal_ref_idc == 0;

    if (sps->frame_mbs_only_flag) {

        picture_structure = PICT_FRAME;

    } else {

        field_pic_flag = get_bits1(&sl->gb);

        if (field_pic_flag) {

            bottom_field_flag = get_bits1(&sl->gb);

            picture_structure = PICT_TOP_FIELD + bottom_field_flag;

        } else {

            picture_structure = PICT_FRAME;

            mb_aff_frame      = sps->mb_aff;

        }

    }

    if (!h->setup_finished) {

        h->droppable         = droppable;

        h->picture_structure = picture_structure;

        h->mb_aff_frame      = mb_aff_frame;

    }

    sl->mb_field_decoding_flag = h->picture_structure != PICT_FRAME;



    if (h->current_slice != 0) {

        if (last_pic_structure != picture_structure ||

            last_pic_droppable != droppable) {

            av_log(h->avctx, AV_LOG_ERROR,

                   "Changing field mode (%d -> %d) between slices is not allowed\n",

                   last_pic_structure, h->picture_structure);

            return AVERROR_INVALIDDATA;

        } else if (!h->cur_pic_ptr) {

            av_log(h->avctx, AV_LOG_ERROR,

                   "unset cur_pic_ptr on slice %d\n",

                   h->current_slice + 1);

            return AVERROR_INVALIDDATA;

        }

    } else {

        /* Shorten frame num gaps so we don't have to allocate reference

         * frames just to throw them away */

        if (h->frame_num != h->prev_frame_num) {

            int unwrap_prev_frame_num = h->prev_frame_num;

            int max_frame_num         = 1 << sps->log2_max_frame_num;



            if (unwrap_prev_frame_num > h->frame_num)

                unwrap_prev_frame_num -= max_frame_num;



            if ((h->frame_num - unwrap_prev_frame_num) > sps->ref_frame_count) {

                unwrap_prev_frame_num = (h->frame_num - sps->ref_frame_count) - 1;

                if (unwrap_prev_frame_num < 0)

                    unwrap_prev_frame_num += max_frame_num;



                h->prev_frame_num = unwrap_prev_frame_num;

            }

        }



        /* See if we have a decoded first field looking for a pair...

         * Here, we're using that to see if we should mark previously

         * decode frames as "finished".

         * We have to do that before the "dummy" in-between frame allocation,

         * since that can modify s->current_picture_ptr. */

        if (h->first_field) {

            assert(h->cur_pic_ptr);

            assert(h->cur_pic_ptr->f->buf[0]);

            assert(h->cur_pic_ptr->reference != DELAYED_PIC_REF);



            /* figure out if we have a complementary field pair */

            if (!FIELD_PICTURE(h) || h->picture_structure == last_pic_structure) {

                /* Previous field is unmatched. Don't display it, but let it

                 * remain for reference if marked as such. */

                if (!last_pic_droppable && last_pic_structure != PICT_FRAME) {

                    ff_thread_report_progress(&h->cur_pic_ptr->tf, INT_MAX,

                                              last_pic_structure == PICT_TOP_FIELD);

                }

            } else {

                if (h->cur_pic_ptr->frame_num != h->frame_num) {

                    /* This and previous field were reference, but had

                     * different frame_nums. Consider this field first in

                     * pair. Throw away previous field except for reference

                     * purposes. */

                    if (!last_pic_droppable && last_pic_structure != PICT_FRAME) {

                        ff_thread_report_progress(&h->cur_pic_ptr->tf, INT_MAX,

                                                  last_pic_structure == PICT_TOP_FIELD);

                    }

                } else {

                    /* Second field in complementary pair */

                    if (!((last_pic_structure   == PICT_TOP_FIELD &&

                           h->picture_structure == PICT_BOTTOM_FIELD) ||

                          (last_pic_structure   == PICT_BOTTOM_FIELD &&

                           h->picture_structure == PICT_TOP_FIELD))) {

                        av_log(h->avctx, AV_LOG_ERROR,

                               "Invalid field mode combination %d/%d\n",

                               last_pic_structure, h->picture_structure);

                        h->picture_structure = last_pic_structure;

                        h->droppable         = last_pic_droppable;

                        return AVERROR_INVALIDDATA;

                    } else if (last_pic_droppable != h->droppable) {

                        avpriv_request_sample(h->avctx,

                                              "Found reference and non-reference fields in the same frame, which");

                        h->picture_structure = last_pic_structure;

                        h->droppable         = last_pic_droppable;

                        return AVERROR_PATCHWELCOME;

                    }

                }

            }

        }



        while (h->frame_num != h->prev_frame_num &&

               h->frame_num != (h->prev_frame_num + 1) % (1 << sps->log2_max_frame_num)) {

            H264Picture *prev = h->short_ref_count ? h->short_ref[0] : NULL;

            av_log(h->avctx, AV_LOG_DEBUG, "Frame num gap %d %d\n",

                   h->frame_num, h->prev_frame_num);

            ret = initialize_cur_frame(h);

            if (ret < 0) {

                h->first_field = 0;

                return ret;

            }



            h->prev_frame_num++;

            h->prev_frame_num        %= 1 << sps->log2_max_frame_num;

            h->cur_pic_ptr->frame_num = h->prev_frame_num;

            ff_thread_report_progress(&h->cur_pic_ptr->tf, INT_MAX, 0);

            ff_thread_report_progress(&h->cur_pic_ptr->tf, INT_MAX, 1);

            ret = ff_generate_sliding_window_mmcos(h, 1);

            if (ret < 0 && (h->avctx->err_recognition & AV_EF_EXPLODE))

                return ret;

            ret = ff_h264_execute_ref_pic_marking(h, h->mmco, h->mmco_index);

            if (ret < 0 && (h->avctx->err_recognition & AV_EF_EXPLODE))

                return ret;

            /* Error concealment: If a ref is missing, copy the previous ref

             * in its place.

             * FIXME: Avoiding a memcpy would be nice, but ref handling makes

             * many assumptions about there being no actual duplicates.

             * FIXME: This does not copy padding for out-of-frame motion

             * vectors.  Given we are concealing a lost frame, this probably

             * is not noticeable by comparison, but it should be fixed. */

            if (h->short_ref_count) {

                if (prev &&

                    h->short_ref[0]->f->width == prev->f->width &&

                    h->short_ref[0]->f->height == prev->f->height &&

                    h->short_ref[0]->f->format == prev->f->format) {

                    av_image_copy(h->short_ref[0]->f->data,

                                  h->short_ref[0]->f->linesize,

                                  (const uint8_t **)prev->f->data,

                                  prev->f->linesize,

                                  prev->f->format,

                                  h->mb_width  * 16,

                                  h->mb_height * 16);

                    h->short_ref[0]->poc = prev->poc + 2;

                }

                h->short_ref[0]->frame_num = h->prev_frame_num;

            }

        }



        /* See if we have a decoded first field looking for a pair...

         * We're using that to see whether to continue decoding in that

         * frame, or to allocate a new one. */

        if (h->first_field) {

            assert(h->cur_pic_ptr);

            assert(h->cur_pic_ptr->f->buf[0]);

            assert(h->cur_pic_ptr->reference != DELAYED_PIC_REF);



            /* figure out if we have a complementary field pair */

            if (!FIELD_PICTURE(h) || h->picture_structure == last_pic_structure) {

                /* Previous field is unmatched. Don't display it, but let it

                 * remain for reference if marked as such. */

                h->cur_pic_ptr = NULL;

                h->first_field = FIELD_PICTURE(h);

            } else {

                if (h->cur_pic_ptr->frame_num != h->frame_num) {

                    /* This and the previous field had different frame_nums.

                     * Consider this field first in pair. Throw away previous

                     * one except for reference purposes. */

                    h->first_field = 1;

                    h->cur_pic_ptr = NULL;

                } else {

                    /* Second field in complementary pair */

                    h->first_field = 0;

                }

            }

        } else {

            /* Frame or first field in a potentially complementary pair */

            h->first_field = FIELD_PICTURE(h);

        }



        if (!FIELD_PICTURE(h) || h->first_field) {

            if (h264_frame_start(h) < 0) {

                h->first_field = 0;

                return AVERROR_INVALIDDATA;

            }

        } else {

            release_unused_pictures(h, 0);

        }

    }



    assert(h->mb_num == h->mb_width * h->mb_height);

    if (first_mb_in_slice << FIELD_OR_MBAFF_PICTURE(h) >= h->mb_num ||

        first_mb_in_slice >= h->mb_num) {

        av_log(h->avctx, AV_LOG_ERROR, "first_mb_in_slice overflow\n");

        return AVERROR_INVALIDDATA;

    }

    sl->resync_mb_x = sl->mb_x =  first_mb_in_slice % h->mb_width;

    sl->resync_mb_y = sl->mb_y = (first_mb_in_slice / h->mb_width) <<

                                 FIELD_OR_MBAFF_PICTURE(h);

    if (h->picture_structure == PICT_BOTTOM_FIELD)

        sl->resync_mb_y = sl->mb_y = sl->mb_y + 1;

    assert(sl->mb_y < h->mb_height);



    if (h->picture_structure == PICT_FRAME) {

        h->curr_pic_num = h->frame_num;

        h->max_pic_num  = 1 << sps->log2_max_frame_num;

    } else {

        h->curr_pic_num = 2 * h->frame_num + 1;

        h->max_pic_num  = 1 << (sps->log2_max_frame_num + 1);

    }



    if (h->nal_unit_type == NAL_IDR_SLICE)

        get_ue_golomb(&sl->gb); /* idr_pic_id */



    if (sps->poc_type == 0) {

        int poc_lsb = get_bits(&sl->gb, sps->log2_max_poc_lsb);



        if (!h->setup_finished)

            h->poc_lsb = poc_lsb;



        if (pps->pic_order_present == 1 && h->picture_structure == PICT_FRAME) {

            int delta_poc_bottom = get_se_golomb(&sl->gb);

            if (!h->setup_finished)

                h->delta_poc_bottom = delta_poc_bottom;

        }

    }



    if (sps->poc_type == 1 && !sps->delta_pic_order_always_zero_flag) {

        int delta_poc = get_se_golomb(&sl->gb);



        if (!h->setup_finished)

            h->delta_poc[0] = delta_poc;



        if (pps->pic_order_present == 1 && h->picture_structure == PICT_FRAME) {

            delta_poc = get_se_golomb(&sl->gb);



            if (!h->setup_finished)

                h->delta_poc[1] = delta_poc;

        }

    }



    if (!h->setup_finished)

        ff_init_poc(h, h->cur_pic_ptr->field_poc, &h->cur_pic_ptr->poc);



    if (pps->redundant_pic_cnt_present)

        sl->redundant_pic_count = get_ue_golomb(&sl->gb);



    if (sl->slice_type_nos == AV_PICTURE_TYPE_B)

        sl->direct_spatial_mv_pred = get_bits1(&sl->gb);



    ret = ff_h264_parse_ref_count(&sl->list_count, sl->ref_count,

                                  &sl->gb, pps, sl->slice_type_nos,

                                  h->picture_structure);

    if (ret < 0)

        return ret;



    if (sl->slice_type_nos != AV_PICTURE_TYPE_I) {

       ret = ff_h264_decode_ref_pic_list_reordering(h, sl);

       if (ret < 0) {

           sl->ref_count[1] = sl->ref_count[0] = 0;

           return ret;

       }

    }



    if ((pps->weighted_pred && sl->slice_type_nos == AV_PICTURE_TYPE_P) ||

        (pps->weighted_bipred_idc == 1 &&

         sl->slice_type_nos == AV_PICTURE_TYPE_B))

        ff_h264_pred_weight_table(&sl->gb, sps, sl->ref_count,

                                  sl->slice_type_nos, &sl->pwt);

    else if (pps->weighted_bipred_idc == 2 &&

             sl->slice_type_nos == AV_PICTURE_TYPE_B) {

        implicit_weight_table(h, sl, -1);

    } else {

        sl->pwt.use_weight = 0;

        for (i = 0; i < 2; i++) {

            sl->pwt.luma_weight_flag[i]   = 0;

            sl->pwt.chroma_weight_flag[i] = 0;

        }

    }



    // If frame-mt is enabled, only update mmco tables for the first slice

    // in a field. Subsequent slices can temporarily clobber h->mmco_index

    // or h->mmco, which will cause ref list mix-ups and decoding errors

    // further down the line. This may break decoding if the first slice is

    // corrupt, thus we only do this if frame-mt is enabled.

    if (h->nal_ref_idc) {

        ret = ff_h264_decode_ref_pic_marking(h, &sl->gb,

                                             !(h->avctx->active_thread_type & FF_THREAD_FRAME) ||

                                             h->current_slice == 0);

        if (ret < 0 && (h->avctx->err_recognition & AV_EF_EXPLODE))

            return AVERROR_INVALIDDATA;

    }



    if (FRAME_MBAFF(h)) {

        ff_h264_fill_mbaff_ref_list(h, sl);



        if (pps->weighted_bipred_idc == 2 && sl->slice_type_nos == AV_PICTURE_TYPE_B) {

            implicit_weight_table(h, sl, 0);

            implicit_weight_table(h, sl, 1);

        }

    }



    if (sl->slice_type_nos == AV_PICTURE_TYPE_B && !sl->direct_spatial_mv_pred)

        ff_h264_direct_dist_scale_factor(h, sl);

    ff_h264_direct_ref_list_init(h, sl);



    if (sl->slice_type_nos != AV_PICTURE_TYPE_I && pps->cabac) {

        tmp = get_ue_golomb_31(&sl->gb);

        if (tmp > 2) {

            av_log(h->avctx, AV_LOG_ERROR, "cabac_init_idc %u overflow\n", tmp);

            return AVERROR_INVALIDDATA;

        }

        sl->cabac_init_idc = tmp;

    }



    sl->last_qscale_diff = 0;

    tmp = pps->init_qp + get_se_golomb(&sl->gb);

    if (tmp > 51 + 6 * (sps->bit_depth_luma - 8)) {

        av_log(h->avctx, AV_LOG_ERROR, "QP %u out of range\n", tmp);

        return AVERROR_INVALIDDATA;

    }

    sl->qscale       = tmp;

    sl->chroma_qp[0] = get_chroma_qp(h, 0, sl->qscale);

    sl->chroma_qp[1] = get_chroma_qp(h, 1, sl->qscale);

    // FIXME qscale / qp ... stuff

    if (sl->slice_type == AV_PICTURE_TYPE_SP)

        get_bits1(&sl->gb); /* sp_for_switch_flag */

    if (sl->slice_type == AV_PICTURE_TYPE_SP ||

        sl->slice_type == AV_PICTURE_TYPE_SI)

        get_se_golomb(&sl->gb); /* slice_qs_delta */



    sl->deblocking_filter     = 1;

    sl->slice_alpha_c0_offset = 0;

    sl->slice_beta_offset     = 0;

    if (pps->deblocking_filter_parameters_present) {

        tmp = get_ue_golomb_31(&sl->gb);

        if (tmp > 2) {

            av_log(h->avctx, AV_LOG_ERROR,

                   "deblocking_filter_idc %u out of range\n", tmp);

            return AVERROR_INVALIDDATA;

        }

        sl->deblocking_filter = tmp;

        if (sl->deblocking_filter < 2)

            sl->deblocking_filter ^= 1;  // 1<->0



        if (sl->deblocking_filter) {

            sl->slice_alpha_c0_offset = get_se_golomb(&sl->gb) * 2;

            sl->slice_beta_offset     = get_se_golomb(&sl->gb) * 2;

            if (sl->slice_alpha_c0_offset >  12 ||

                sl->slice_alpha_c0_offset < -12 ||

                sl->slice_beta_offset >  12     ||

                sl->slice_beta_offset < -12) {

                av_log(h->avctx, AV_LOG_ERROR,

                       "deblocking filter parameters %d %d out of range\n",

                       sl->slice_alpha_c0_offset, sl->slice_beta_offset);

                return AVERROR_INVALIDDATA;

            }

        }

    }



    if (h->avctx->skip_loop_filter >= AVDISCARD_ALL ||

        (h->avctx->skip_loop_filter >= AVDISCARD_NONKEY &&

         sl->slice_type_nos != AV_PICTURE_TYPE_I) ||

        (h->avctx->skip_loop_filter >= AVDISCARD_BIDIR  &&

         sl->slice_type_nos == AV_PICTURE_TYPE_B) ||

        (h->avctx->skip_loop_filter >= AVDISCARD_NONREF &&

         h->nal_ref_idc == 0))

        sl->deblocking_filter = 0;



    if (sl->deblocking_filter == 1 && h->max_contexts > 1) {

        if (h->avctx->flags2 & AV_CODEC_FLAG2_FAST) {

            /* Cheat slightly for speed:

             * Do not bother to deblock across slices. */

            sl->deblocking_filter = 2;

        } else {

            h->max_contexts = 1;

            if (!h->single_decode_warning) {

                av_log(h->avctx, AV_LOG_INFO,

                       "Cannot parallelize deblocking type 1, decoding such frames in sequential order\n");

                h->single_decode_warning = 1;

            }

            if (sl != h->slice_ctx) {

                av_log(h->avctx, AV_LOG_ERROR,

                       "Deblocking switched inside frame.\n");

                return 1;

            }

        }

    }

    sl->qp_thresh = 15 -

                   FFMIN(sl->slice_alpha_c0_offset, sl->slice_beta_offset) -

                   FFMAX3(0,

                          pps->chroma_qp_index_offset[0],

                          pps->chroma_qp_index_offset[1]) +

                   6 * (sps->bit_depth_luma - 8);



    sl->slice_num       = ++h->current_slice;

    if (sl->slice_num >= MAX_SLICES) {

        av_log(h->avctx, AV_LOG_ERROR,

               "Too many slices, increase MAX_SLICES and recompile\n");

    }



    for (j = 0; j < 2; j++) {

        int id_list[16];

        int *ref2frm = sl->ref2frm[sl->slice_num & (MAX_SLICES - 1)][j];

        for (i = 0; i < 16; i++) {

            id_list[i] = 60;

            if (j < sl->list_count && i < sl->ref_count[j] &&

                sl->ref_list[j][i].parent->f->buf[0]) {

                int k;

                AVBuffer *buf = sl->ref_list[j][i].parent->f->buf[0]->buffer;

                for (k = 0; k < h->short_ref_count; k++)

                    if (h->short_ref[k]->f->buf[0]->buffer == buf) {

                        id_list[i] = k;

                        break;

                    }

                for (k = 0; k < h->long_ref_count; k++)

                    if (h->long_ref[k] && h->long_ref[k]->f->buf[0]->buffer == buf) {

                        id_list[i] = h->short_ref_count + k;

                        break;

                    }

            }

        }



        ref2frm[0] =

        ref2frm[1] = -1;

        for (i = 0; i < 16; i++)

            ref2frm[i + 2] = 4 * id_list[i] + (sl->ref_list[j][i].reference & 3);

        ref2frm[18 + 0] =

        ref2frm[18 + 1] = -1;

        for (i = 16; i < 48; i++)

            ref2frm[i + 4] = 4 * id_list[(i - 16) >> 1] +

                             (sl->ref_list[j][i].reference & 3);

    }



    if (h->avctx->debug & FF_DEBUG_PICT_INFO) {

        av_log(h->avctx, AV_LOG_DEBUG,

               "slice:%d %s mb:%d %c%s%s pps:%u frame:%d poc:%d/%d ref:%d/%d qp:%d loop:%d:%d:%d weight:%d%s %s\n",

               sl->slice_num,

               (h->picture_structure == PICT_FRAME ? "F" : h->picture_structure == PICT_TOP_FIELD ? "T" : "B"),

               first_mb_in_slice,

               av_get_picture_type_char(sl->slice_type),

               sl->slice_type_fixed ? " fix" : "",

               h->nal_unit_type == NAL_IDR_SLICE ? " IDR" : "",

               pps_id, h->frame_num,

               h->cur_pic_ptr->field_poc[0],

               h->cur_pic_ptr->field_poc[1],

               sl->ref_count[0], sl->ref_count[1],

               sl->qscale,

               sl->deblocking_filter,

               sl->slice_alpha_c0_offset, sl->slice_beta_offset,

               sl->pwt.use_weight,

               sl->pwt.use_weight == 1 && sl->pwt.use_weight_chroma ? "c" : "",

               sl->slice_type == AV_PICTURE_TYPE_B ? (sl->direct_spatial_mv_pred ? "SPAT" : "TEMP") : "");

    }



    return 0;

}

static av_always_inline void mpeg_motion_lowres(MpegEncContext *s,

                                                uint8_t *dest_y,

                                                uint8_t *dest_cb,

                                                uint8_t *dest_cr,

                                                int field_based,

                                                int bottom_field,

                                                int field_select,

                                                uint8_t **ref_picture,

                                                h264_chroma_mc_func *pix_op,

                                                int motion_x, int motion_y,

                                                int h, int mb_y)

{

    uint8_t *ptr_y, *ptr_cb, *ptr_cr;

    int mx, my, src_x, src_y, uvsrc_x, uvsrc_y, uvlinesize, linesize, sx, sy,

        uvsx, uvsy;

    const int lowres     = s->avctx->lowres;

    const int op_index   = FFMIN(lowres-1+s->chroma_x_shift, 2);

    const int block_s    = 8>>lowres;

    const int s_mask     = (2 << lowres) - 1;

    const int h_edge_pos = s->h_edge_pos >> lowres;

    const int v_edge_pos = s->v_edge_pos >> lowres;

    linesize   = s->current_picture.f.linesize[0] << field_based;

    uvlinesize = s->current_picture.f.linesize[1] << field_based;



    // FIXME obviously not perfect but qpel will not work in lowres anyway

    if (s->quarter_sample) {

        motion_x /= 2;

        motion_y /= 2;

    }



    if(field_based){

        motion_y += (bottom_field - field_select)*((1 << lowres)-1);

    }



    sx = motion_x & s_mask;

    sy = motion_y & s_mask;

    src_x = s->mb_x * 2 * block_s + (motion_x >> lowres + 1);

    src_y = (mb_y * 2 * block_s >> field_based) + (motion_y >> lowres + 1);



    if (s->out_format == FMT_H263) {

        uvsx    = ((motion_x >> 1) & s_mask) | (sx & 1);

        uvsy    = ((motion_y >> 1) & s_mask) | (sy & 1);

        uvsrc_x = src_x >> 1;

        uvsrc_y = src_y >> 1;

    } else if (s->out_format == FMT_H261) {

        // even chroma mv's are full pel in H261

        mx      = motion_x / 4;

        my      = motion_y / 4;

        uvsx    = (2 * mx) & s_mask;

        uvsy    = (2 * my) & s_mask;

        uvsrc_x = s->mb_x * block_s + (mx >> lowres);

        uvsrc_y =    mb_y * block_s + (my >> lowres);

    } else {

        if(s->chroma_y_shift){

            mx      = motion_x / 2;

            my      = motion_y / 2;

            uvsx    = mx & s_mask;

            uvsy    = my & s_mask;

            uvsrc_x = s->mb_x * block_s                 + (mx >> lowres + 1);

            uvsrc_y =   (mb_y * block_s >> field_based) + (my >> lowres + 1);

        } else {

            if(s->chroma_x_shift){

            //Chroma422

                mx = motion_x / 2;

                uvsx = mx & s_mask;

                uvsy = motion_y & s_mask;

                uvsrc_y = src_y;

                uvsrc_x = s->mb_x*block_s               + (mx >> (lowres+1));

            } else {

            //Chroma444

                uvsx = motion_x & s_mask;

                uvsy = motion_y & s_mask;

                uvsrc_x = src_x;

                uvsrc_y = src_y;

            }

        }

    }



    ptr_y  = ref_picture[0] + src_y   * linesize   + src_x;

    ptr_cb = ref_picture[1] + uvsrc_y * uvlinesize + uvsrc_x;

    ptr_cr = ref_picture[2] + uvsrc_y * uvlinesize + uvsrc_x;



    if ((unsigned) src_x > FFMAX( h_edge_pos - (!!sx) - 2 * block_s,       0) || uvsrc_y<0 ||

        (unsigned) src_y > FFMAX((v_edge_pos >> field_based) - (!!sy) - h, 0)) {

        s->vdsp.emulated_edge_mc(s->edge_emu_buffer, ptr_y,

                                linesize >> field_based, 17, 17 + field_based,

                                src_x, src_y << field_based, h_edge_pos,

                                v_edge_pos);

        ptr_y = s->edge_emu_buffer;

        if (!CONFIG_GRAY || !(s->flags & CODEC_FLAG_GRAY)) {

            uint8_t *uvbuf = s->edge_emu_buffer + 18 * s->linesize;

            s->vdsp.emulated_edge_mc(uvbuf , ptr_cb, uvlinesize >> field_based, 9,

                                    9 + field_based,

                                    uvsrc_x, uvsrc_y << field_based,

                                    h_edge_pos >> 1, v_edge_pos >> 1);

            s->vdsp.emulated_edge_mc(uvbuf + 16, ptr_cr, uvlinesize >> field_based, 9,

                                    9 + field_based,

                                    uvsrc_x, uvsrc_y << field_based,

                                    h_edge_pos >> 1, v_edge_pos >> 1);

            ptr_cb = uvbuf;

            ptr_cr = uvbuf + 16;

        }

    }



    // FIXME use this for field pix too instead of the obnoxious hack which changes picture.f.data

    if (bottom_field) {

        dest_y  += s->linesize;

        dest_cb += s->uvlinesize;

        dest_cr += s->uvlinesize;

    }



    if (field_select) {

        ptr_y   += s->linesize;

        ptr_cb  += s->uvlinesize;

        ptr_cr  += s->uvlinesize;

    }



    sx = (sx << 2) >> lowres;

    sy = (sy << 2) >> lowres;

    pix_op[lowres - 1](dest_y, ptr_y, linesize, h, sx, sy);



    if (!CONFIG_GRAY || !(s->flags & CODEC_FLAG_GRAY)) {

        int hc = s->chroma_y_shift ? (h+1-bottom_field)>>1 : h;

        uvsx = (uvsx << 2) >> lowres;

        uvsy = (uvsy << 2) >> lowres;

        if (hc) {

            pix_op[op_index](dest_cb, ptr_cb, uvlinesize, hc, uvsx, uvsy);

            pix_op[op_index](dest_cr, ptr_cr, uvlinesize, hc, uvsx, uvsy);

        }

    }

    // FIXME h261 lowres loop filter

}

static av_always_inline void idct_internal(uint8_t *dst, DCTELEM *block, int stride, int block_stride, int shift, int add){

    int i;

    uint8_t *cm = ff_cropTbl + MAX_NEG_CROP;



    block[0] += 1<<(shift-1);



    for(i=0; i<4; i++){

        const int z0=  block[0 + block_stride*i]     +  block[2 + block_stride*i];

        const int z1=  block[0 + block_stride*i]     -  block[2 + block_stride*i];

        const int z2= (block[1 + block_stride*i]>>1) -  block[3 + block_stride*i];

        const int z3=  block[1 + block_stride*i]     + (block[3 + block_stride*i]>>1);



        block[0 + block_stride*i]= z0 + z3;

        block[1 + block_stride*i]= z1 + z2;

        block[2 + block_stride*i]= z1 - z2;

        block[3 + block_stride*i]= z0 - z3;

    }



    for(i=0; i<4; i++){

        const int z0=  block[i + block_stride*0]     +  block[i + block_stride*2];

        const int z1=  block[i + block_stride*0]     -  block[i + block_stride*2];

        const int z2= (block[i + block_stride*1]>>1) -  block[i + block_stride*3];

        const int z3=  block[i + block_stride*1]     + (block[i + block_stride*3]>>1);



        dst[i + 0*stride]= cm[ add*dst[i + 0*stride] + ((z0 + z3) >> shift) ];

        dst[i + 1*stride]= cm[ add*dst[i + 1*stride] + ((z1 + z2) >> shift) ];

        dst[i + 2*stride]= cm[ add*dst[i + 2*stride] + ((z1 - z2) >> shift) ];

        dst[i + 3*stride]= cm[ add*dst[i + 3*stride] + ((z0 - z3) >> shift) ];

    }

}

static int mxf_parse_index(MXFContext *mxf, int track_id, AVStream *st)

{

    int64_t accumulated_offset = 0;

    int j, k, ret, nb_sorted_segments;

    MXFIndexTableSegment **sorted_segments;

    int n_delta = track_id - 1;  /* TrackID = 1-based stream index */



    if (track_id < 1) {

        av_log(mxf->fc, AV_LOG_ERROR, "TrackID not positive: %i\n", track_id);

        return AVERROR_INVALIDDATA;

    }



    if ((ret = mxf_get_sorted_table_segments(mxf, &nb_sorted_segments, &sorted_segments)))

        return ret;



    for (j = 0; j < nb_sorted_segments; j++) {

        int duration, sample_duration = 1, last_sample_size = 0;

        int64_t segment_size;

        MXFIndexTableSegment *tableseg = sorted_segments[j];



        /* reset accumulated_offset on BodySID change */

        if (j > 0 && tableseg->body_sid != sorted_segments[j-1]->body_sid)

            accumulated_offset = 0;



        if (n_delta >= tableseg->nb_delta_entries && st->index != 0)

            continue;

        duration = tableseg->index_duration > 0 ? tableseg->index_duration :

            st->duration - st->nb_index_entries;

        segment_size = tableseg->edit_unit_byte_count * duration;

        /* check small EditUnitByteCount for audio */

        if (tableseg->edit_unit_byte_count && tableseg->edit_unit_byte_count < 32

            && !tableseg->index_duration) {

            /* duration might be prime relative to the new sample_duration,

             * which means we need to handle the last frame differently */

            sample_duration = 8192;

            last_sample_size = (duration % sample_duration) * tableseg->edit_unit_byte_count;

            tableseg->edit_unit_byte_count *= sample_duration;

            duration /= sample_duration;

            if (last_sample_size) duration++;

        }



        for (k = 0; k < duration; k++) {

            int64_t pos;

            int size, flags = 0;



            if (k < tableseg->nb_index_entries) {

                pos = tableseg->stream_offset_entries[k];

                if (n_delta < tableseg->nb_delta_entries) {

                    if (n_delta < tableseg->nb_delta_entries - 1) {

                        size =

                            tableseg->slice_offset_entries[k][tableseg->slice[n_delta+1]-1] +

                            tableseg->element_delta[n_delta+1] -

                            tableseg->element_delta[n_delta];

                        if (tableseg->slice[n_delta] > 0)

                            size -= tableseg->slice_offset_entries[k][tableseg->slice[n_delta]-1];

                    } else if (k < duration - 1) {

                        size = tableseg->stream_offset_entries[k+1] -

                            tableseg->stream_offset_entries[k] -

                            tableseg->slice_offset_entries[k][tableseg->slice[tableseg->nb_delta_entries-1]-1] -

                            tableseg->element_delta[tableseg->nb_delta_entries-1];

                    } else

                        size = 0;

                    if (tableseg->slice[n_delta] > 0)

                        pos += tableseg->slice_offset_entries[k][tableseg->slice[n_delta]-1];

                    pos += tableseg->element_delta[n_delta];

                } else

                    size = 0;

                flags = !(tableseg->flag_entries[k] & 0x30) ? AVINDEX_KEYFRAME : 0;

            } else {

                pos = (int64_t)k * tableseg->edit_unit_byte_count + accumulated_offset;

                if (n_delta < tableseg->nb_delta_entries - 1)

                    size = tableseg->element_delta[n_delta+1] - tableseg->element_delta[n_delta];

                else {

                    /* use smaller size for last sample if we should */

                    if (last_sample_size && k == duration - 1)

                        size = last_sample_size;

                    else

                        size = tableseg->edit_unit_byte_count;

                    if (tableseg->nb_delta_entries)

                        size -= tableseg->element_delta[tableseg->nb_delta_entries-1];

                }

                if (n_delta < tableseg->nb_delta_entries)

                    pos += tableseg->element_delta[n_delta];

                flags = AVINDEX_KEYFRAME;

            }



            if (mxf_absolute_bodysid_offset(mxf, tableseg->body_sid, pos, &pos) < 0) {

                /* probably partial file - no point going further for this stream */

                break;

            }



            av_dlog(mxf->fc, "Stream %d IndexEntry %d TrackID %d Offset %"PRIx64" Timestamp %"PRId64"\n",

                    st->index, st->nb_index_entries, track_id, pos, sample_duration * st->nb_index_entries);



            if ((ret = av_add_index_entry(st, pos, sample_duration * st->nb_index_entries, size, 0, flags)) < 0)

                return ret;

        }

        accumulated_offset += segment_size;

    }



    av_free(sorted_segments);



    return 0;

}

static void fill_picture_parameters(const AVCodecContext *avctx, AVDXVAContext *ctx, const HEVCContext *h,

                                    DXVA_PicParams_HEVC *pp)

{

    const HEVCFrame *current_picture = h->ref;

    int i, j, k;



    memset(pp, 0, sizeof(*pp));



    pp->PicWidthInMinCbsY  = h->sps->min_cb_width;

    pp->PicHeightInMinCbsY = h->sps->min_cb_height;



    pp->wFormatAndSequenceInfoFlags = (h->sps->chroma_format_idc          <<  0) |

                                      (h->sps->separate_colour_plane_flag <<  2) |

                                      ((h->sps->bit_depth - 8)            <<  3) |

                                      ((h->sps->bit_depth - 8)            <<  6) |

                                      ((h->sps->log2_max_poc_lsb - 4)     <<  9) |

                                      (0                                  << 13) |

                                      (0                                  << 14) |

                                      (0                                  << 15);



    fill_picture_entry(&pp->CurrPic, ff_dxva2_get_surface_index(avctx, ctx, current_picture->frame), 0);



    pp->sps_max_dec_pic_buffering_minus1         = h->sps->temporal_layer[h->sps->max_sub_layers - 1].max_dec_pic_buffering - 1;

    pp->log2_min_luma_coding_block_size_minus3   = h->sps->log2_min_cb_size - 3;

    pp->log2_diff_max_min_luma_coding_block_size = h->sps->log2_diff_max_min_coding_block_size;

    pp->log2_min_transform_block_size_minus2     = h->sps->log2_min_tb_size - 2;

    pp->log2_diff_max_min_transform_block_size   = h->sps->log2_max_trafo_size  - h->sps->log2_min_tb_size;

    pp->max_transform_hierarchy_depth_inter      = h->sps->max_transform_hierarchy_depth_inter;

    pp->max_transform_hierarchy_depth_intra      = h->sps->max_transform_hierarchy_depth_intra;

    pp->num_short_term_ref_pic_sets              = h->sps->nb_st_rps;

    pp->num_long_term_ref_pics_sps               = h->sps->num_long_term_ref_pics_sps;



    pp->num_ref_idx_l0_default_active_minus1     = h->pps->num_ref_idx_l0_default_active - 1;

    pp->num_ref_idx_l1_default_active_minus1     = h->pps->num_ref_idx_l1_default_active - 1;

    pp->init_qp_minus26                          = h->pps->pic_init_qp_minus26;



    if (h->sh.short_term_ref_pic_set_sps_flag == 0 && h->sh.short_term_rps) {

        pp->ucNumDeltaPocsOfRefRpsIdx            = h->sh.short_term_rps->num_delta_pocs;

        pp->wNumBitsForShortTermRPSInSlice       = h->sh.short_term_ref_pic_set_size;

    }



    pp->dwCodingParamToolFlags = (h->sps->scaling_list_enable_flag               <<  0) |

                                 (h->sps->amp_enabled_flag                       <<  1) |

                                 (h->sps->sao_enabled                            <<  2) |

                                 (h->sps->pcm_enabled_flag                       <<  3) |

                                 ((h->sps->pcm_enabled_flag ? (h->sps->pcm.bit_depth - 1) : 0)            <<  4) |

                                 ((h->sps->pcm_enabled_flag ? (h->sps->pcm.bit_depth_chroma - 1) : 0)     <<  8) |

                                 ((h->sps->pcm_enabled_flag ? (h->sps->pcm.log2_min_pcm_cb_size - 3) : 0) << 12) |

                                 ((h->sps->pcm_enabled_flag ? (h->sps->pcm.log2_max_pcm_cb_size - h->sps->pcm.log2_min_pcm_cb_size) : 0) << 14) |

                                 (h->sps->pcm.loop_filter_disable_flag           << 16) |

                                 (h->sps->long_term_ref_pics_present_flag        << 17) |

                                 (h->sps->sps_temporal_mvp_enabled_flag          << 18) |

                                 (h->sps->sps_strong_intra_smoothing_enable_flag << 19) |

                                 (h->pps->dependent_slice_segments_enabled_flag  << 20) |

                                 (h->pps->output_flag_present_flag               << 21) |

                                 (h->pps->num_extra_slice_header_bits            << 22) |

                                 (h->pps->sign_data_hiding_flag                  << 25) |

                                 (h->pps->cabac_init_present_flag                << 26) |

                                 (0                                              << 27);



    pp->dwCodingSettingPicturePropertyFlags = (h->pps->constrained_intra_pred_flag                <<  0) |

                                              (h->pps->transform_skip_enabled_flag                <<  1) |

                                              (h->pps->cu_qp_delta_enabled_flag                   <<  2) |

                                              (h->pps->pic_slice_level_chroma_qp_offsets_present_flag <<  3) |

                                              (h->pps->weighted_pred_flag                         <<  4) |

                                              (h->pps->weighted_bipred_flag                       <<  5) |

                                              (h->pps->transquant_bypass_enable_flag              <<  6) |

                                              (h->pps->tiles_enabled_flag                         <<  7) |

                                              (h->pps->entropy_coding_sync_enabled_flag           <<  8) |

                                              (h->pps->uniform_spacing_flag                       <<  9) |

                                              ((h->pps->tiles_enabled_flag ? h->pps->loop_filter_across_tiles_enabled_flag : 0) << 10) |

                                              (h->pps->seq_loop_filter_across_slices_enabled_flag << 11) |

                                              (h->pps->deblocking_filter_override_enabled_flag    << 12) |

                                              (h->pps->disable_dbf                                << 13) |

                                              (h->pps->lists_modification_present_flag            << 14) |

                                              (h->pps->slice_header_extension_present_flag        << 15) |

                                              (IS_IRAP(h)                                         << 16) |

                                              (IS_IDR(h)                                          << 17) |

                                              /* IntraPicFlag */

                                              (IS_IRAP(h)                                         << 18) |

                                              (0                                                  << 19);

    pp->pps_cb_qp_offset            = h->pps->cb_qp_offset;

    pp->pps_cr_qp_offset            = h->pps->cr_qp_offset;

    if (h->pps->tiles_enabled_flag) {

        pp->num_tile_columns_minus1 = h->pps->num_tile_columns - 1;

        pp->num_tile_rows_minus1    = h->pps->num_tile_rows - 1;



        if (!h->pps->uniform_spacing_flag) {

            for (i = 0; i < h->pps->num_tile_columns; i++)

                pp->column_width_minus1[i] = h->pps->column_width[i] - 1;



            for (i = 0; i < h->pps->num_tile_rows; i++)

                pp->row_height_minus1[i] = h->pps->row_height[i] - 1;

        }

    }



    pp->diff_cu_qp_delta_depth           = h->pps->diff_cu_qp_delta_depth;

    pp->pps_beta_offset_div2             = h->pps->beta_offset / 2;

    pp->pps_tc_offset_div2               = h->pps->tc_offset / 2;

    pp->log2_parallel_merge_level_minus2 = h->pps->log2_parallel_merge_level - 2;

    pp->CurrPicOrderCntVal               = h->poc;



    // empty the lists

    memset(&pp->RefPicList, 0xff, sizeof(pp->RefPicList));

    memset(&pp->RefPicSetStCurrBefore, 0xff, sizeof(pp->RefPicSetStCurrBefore));

    memset(&pp->RefPicSetStCurrAfter, 0xff, sizeof(pp->RefPicSetStCurrAfter));

    memset(&pp->RefPicSetLtCurr, 0xff, sizeof(pp->RefPicSetLtCurr));



    // fill RefPicList from the DPB

    for (i = 0, j = 0; i < FF_ARRAY_ELEMS(h->DPB); i++) {

        const HEVCFrame *frame = &h->DPB[i];

        if (frame != current_picture && (frame->flags & (HEVC_FRAME_FLAG_LONG_REF | HEVC_FRAME_FLAG_SHORT_REF))) {

            fill_picture_entry(&pp->RefPicList[j], ff_dxva2_get_surface_index(avctx, ctx, frame->frame), !!(frame->flags & HEVC_FRAME_FLAG_LONG_REF));

            pp->PicOrderCntValList[j] = frame->poc;

            j++;

        }

    }



    #define DO_REF_LIST(ref_idx, ref_list) { \

        const RefPicList *rpl = &h->rps[ref_idx]; \

        av_assert0(rpl->nb_refs <= FF_ARRAY_ELEMS(pp->ref_list)); \

        for (j = 0, k = 0; j < rpl->nb_refs; j++) { \

            if (rpl->ref[j]) { \

                pp->ref_list[k] = get_refpic_index(pp, ff_dxva2_get_surface_index(avctx, ctx, rpl->ref[j]->frame)); \

                k++; \

            } \

        } \

    }



    // Fill short term and long term lists

    DO_REF_LIST(ST_CURR_BEF, RefPicSetStCurrBefore);

    DO_REF_LIST(ST_CURR_AFT, RefPicSetStCurrAfter);

    DO_REF_LIST(LT_CURR, RefPicSetLtCurr);



    pp->StatusReportFeedbackNumber = 1 + DXVA_CONTEXT_REPORT_ID(avctx, ctx)++;

}

av_cold int ff_yuv2rgb_c_init_tables(SwsContext *c, const int inv_table[4],

                                     int fullRange, int brightness,

                                     int contrast, int saturation)

{

    const int isRgb = c->dstFormat == AV_PIX_FMT_RGB32     ||

                      c->dstFormat == AV_PIX_FMT_RGB32_1   ||

                      c->dstFormat == AV_PIX_FMT_BGR24     ||

                      c->dstFormat == AV_PIX_FMT_RGB565BE  ||

                      c->dstFormat == AV_PIX_FMT_RGB565LE  ||

                      c->dstFormat == AV_PIX_FMT_RGB555BE  ||

                      c->dstFormat == AV_PIX_FMT_RGB555LE  ||

                      c->dstFormat == AV_PIX_FMT_RGB444BE  ||

                      c->dstFormat == AV_PIX_FMT_RGB444LE  ||

                      c->dstFormat == AV_PIX_FMT_RGB8      ||

                      c->dstFormat == AV_PIX_FMT_RGB4      ||

                      c->dstFormat == AV_PIX_FMT_RGB4_BYTE ||

                      c->dstFormat == AV_PIX_FMT_MONOBLACK;

    const int isNotNe = c->dstFormat == AV_PIX_FMT_NE(RGB565LE, RGB565BE) ||

                        c->dstFormat == AV_PIX_FMT_NE(RGB555LE, RGB555BE) ||

                        c->dstFormat == AV_PIX_FMT_NE(RGB444LE, RGB444BE) ||

                        c->dstFormat == AV_PIX_FMT_NE(BGR565LE, BGR565BE) ||

                        c->dstFormat == AV_PIX_FMT_NE(BGR555LE, BGR555BE) ||

                        c->dstFormat == AV_PIX_FMT_NE(BGR444LE, BGR444BE);

    const int bpp = c->dstFormatBpp;

    uint8_t *y_table;

    uint16_t *y_table16;

    uint32_t *y_table32;

    int i, base, rbase, gbase, bbase, av_uninit(abase), needAlpha;

    const int yoffs = fullRange ? 384 : 326;



    int64_t crv =  inv_table[0];

    int64_t cbu =  inv_table[1];

    int64_t cgu = -inv_table[2];

    int64_t cgv = -inv_table[3];

    int64_t cy  = 1 << 16;

    int64_t oy  = 0;

    int64_t yb  = 0;



    if (!fullRange) {

        cy = (cy * 255) / 219;

        oy = 16 << 16;

    } else {

        crv = (crv * 224) / 255;

        cbu = (cbu * 224) / 255;

        cgu = (cgu * 224) / 255;

        cgv = (cgv * 224) / 255;

    }



    cy   = (cy  * contrast)              >> 16;

    crv  = (crv * contrast * saturation) >> 32;

    cbu  = (cbu * contrast * saturation) >> 32;

    cgu  = (cgu * contrast * saturation) >> 32;

    cgv  = (cgv * contrast * saturation) >> 32;

    oy  -= 256 * brightness;



    c->uOffset = 0x0400040004000400LL;

    c->vOffset = 0x0400040004000400LL;

    c->yCoeff  = roundToInt16(cy  * 8192) * 0x0001000100010001ULL;

    c->vrCoeff = roundToInt16(crv * 8192) * 0x0001000100010001ULL;

    c->ubCoeff = roundToInt16(cbu * 8192) * 0x0001000100010001ULL;

    c->vgCoeff = roundToInt16(cgv * 8192) * 0x0001000100010001ULL;

    c->ugCoeff = roundToInt16(cgu * 8192) * 0x0001000100010001ULL;

    c->yOffset = roundToInt16(oy  *    8) * 0x0001000100010001ULL;



    c->yuv2rgb_y_coeff   = (int16_t)roundToInt16(cy  << 13);

    c->yuv2rgb_y_offset  = (int16_t)roundToInt16(oy  <<  9);

    c->yuv2rgb_v2r_coeff = (int16_t)roundToInt16(crv << 13);

    c->yuv2rgb_v2g_coeff = (int16_t)roundToInt16(cgv << 13);

    c->yuv2rgb_u2g_coeff = (int16_t)roundToInt16(cgu << 13);

    c->yuv2rgb_u2b_coeff = (int16_t)roundToInt16(cbu << 13);



    //scale coefficients by cy

    crv = ((crv << 16) + 0x8000) / cy;

    cbu = ((cbu << 16) + 0x8000) / cy;

    cgu = ((cgu << 16) + 0x8000) / cy;

    cgv = ((cgv << 16) + 0x8000) / cy;



    av_freep(&c->yuvTable);



    switch (bpp) {

    case 1:

        c->yuvTable = av_malloc(1024);

        y_table     = c->yuvTable;

        yb = -(384 << 16) - oy;

        for (i = 0; i < 1024 - 110; i++) {

            y_table[i + 110]  = av_clip_uint8((yb + 0x8000) >> 16) >> 7;

            yb               += cy;

        }

        fill_table(c->table_gU, 1, cgu, y_table + yoffs);

        fill_gv_table(c->table_gV, 1, cgv);

        break;

    case 4:

    case 4 | 128:

        rbase       = isRgb ? 3 : 0;

        gbase       = 1;

        bbase       = isRgb ? 0 : 3;

        c->yuvTable = av_malloc(1024 * 3);

        y_table     = c->yuvTable;

        yb = -(384 << 16) - oy;

        for (i = 0; i < 1024 - 110; i++) {

            int yval                = av_clip_uint8((yb + 0x8000) >> 16);

            y_table[i + 110]        = (yval >> 7)        << rbase;

            y_table[i +  37 + 1024] = ((yval + 43) / 85) << gbase;

            y_table[i + 110 + 2048] = (yval >> 7)        << bbase;

            yb += cy;

        }

        fill_table(c->table_rV, 1, crv, y_table + yoffs);

        fill_table(c->table_gU, 1, cgu, y_table + yoffs + 1024);

        fill_table(c->table_bU, 1, cbu, y_table + yoffs + 2048);

        fill_gv_table(c->table_gV, 1, cgv);

        break;

    case 8:

        rbase       = isRgb ? 5 : 0;

        gbase       = isRgb ? 2 : 3;

        bbase       = isRgb ? 0 : 6;

        c->yuvTable = av_malloc(1024 * 3);

        y_table     = c->yuvTable;

        yb = -(384 << 16) - oy;

        for (i = 0; i < 1024 - 38; i++) {

            int yval               = av_clip_uint8((yb + 0x8000) >> 16);

            y_table[i + 16]        = ((yval + 18) / 36) << rbase;

            y_table[i + 16 + 1024] = ((yval + 18) / 36) << gbase;

            y_table[i + 37 + 2048] = ((yval + 43) / 85) << bbase;

            yb += cy;

        }

        fill_table(c->table_rV, 1, crv, y_table + yoffs);

        fill_table(c->table_gU, 1, cgu, y_table + yoffs + 1024);

        fill_table(c->table_bU, 1, cbu, y_table + yoffs + 2048);

        fill_gv_table(c->table_gV, 1, cgv);

        break;

    case 12:

        rbase       = isRgb ? 8 : 0;

        gbase       = 4;

        bbase       = isRgb ? 0 : 8;

        c->yuvTable = av_malloc(1024 * 3 * 2);

        y_table16   = c->yuvTable;

        yb = -(384 << 16) - oy;

        for (i = 0; i < 1024; i++) {

            uint8_t yval        = av_clip_uint8((yb + 0x8000) >> 16);

            y_table16[i]        = (yval >> 4) << rbase;

            y_table16[i + 1024] = (yval >> 4) << gbase;

            y_table16[i + 2048] = (yval >> 4) << bbase;

            yb += cy;

        }

        if (isNotNe)

            for (i = 0; i < 1024 * 3; i++)

                y_table16[i] = av_bswap16(y_table16[i]);

        fill_table(c->table_rV, 2, crv, y_table16 + yoffs);

        fill_table(c->table_gU, 2, cgu, y_table16 + yoffs + 1024);

        fill_table(c->table_bU, 2, cbu, y_table16 + yoffs + 2048);

        fill_gv_table(c->table_gV, 2, cgv);

        break;

    case 15:

    case 16:

        rbase       = isRgb ? bpp - 5 : 0;

        gbase       = 5;

        bbase       = isRgb ? 0 : (bpp - 5);

        c->yuvTable = av_malloc(1024 * 3 * 2);

        y_table16   = c->yuvTable;

        yb = -(384 << 16) - oy;

        for (i = 0; i < 1024; i++) {

            uint8_t yval        = av_clip_uint8((yb + 0x8000) >> 16);

            y_table16[i]        = (yval >> 3)          << rbase;

            y_table16[i + 1024] = (yval >> (18 - bpp)) << gbase;

            y_table16[i + 2048] = (yval >> 3)          << bbase;

            yb += cy;

        }

        if (isNotNe)

            for (i = 0; i < 1024 * 3; i++)

                y_table16[i] = av_bswap16(y_table16[i]);

        fill_table(c->table_rV, 2, crv, y_table16 + yoffs);

        fill_table(c->table_gU, 2, cgu, y_table16 + yoffs + 1024);

        fill_table(c->table_bU, 2, cbu, y_table16 + yoffs + 2048);

        fill_gv_table(c->table_gV, 2, cgv);

        break;

    case 24:

    case 48:

        c->yuvTable = av_malloc(1024);

        y_table     = c->yuvTable;

        yb = -(384 << 16) - oy;

        for (i = 0; i < 1024; i++) {

            y_table[i]  = av_clip_uint8((yb + 0x8000) >> 16);

            yb         += cy;

        }

        fill_table(c->table_rV, 1, crv, y_table + yoffs);

        fill_table(c->table_gU, 1, cgu, y_table + yoffs);

        fill_table(c->table_bU, 1, cbu, y_table + yoffs);

        fill_gv_table(c->table_gV, 1, cgv);

        break;

    case 32:

    case 64:

        base      = (c->dstFormat == AV_PIX_FMT_RGB32_1 ||

                     c->dstFormat == AV_PIX_FMT_BGR32_1) ? 8 : 0;

        rbase     = base + (isRgb ? 16 : 0);

        gbase     = base + 8;

        bbase     = base + (isRgb ? 0 : 16);

        needAlpha = CONFIG_SWSCALE_ALPHA && isALPHA(c->srcFormat);

        if (!needAlpha)

            abase = (base + 24) & 31;

        c->yuvTable = av_malloc(1024 * 3 * 4);

        y_table32   = c->yuvTable;

        yb = -(384 << 16) - oy;

        for (i = 0; i < 1024; i++) {

            unsigned yval       = av_clip_uint8((yb + 0x8000) >> 16);

            y_table32[i]        = (yval << rbase) +

                                  (needAlpha ? 0 : (255u << abase));

            y_table32[i + 1024] =  yval << gbase;

            y_table32[i + 2048] =  yval << bbase;

            yb += cy;

        }

        fill_table(c->table_rV, 4, crv, y_table32 + yoffs);

        fill_table(c->table_gU, 4, cgu, y_table32 + yoffs + 1024);

        fill_table(c->table_bU, 4, cbu, y_table32 + yoffs + 2048);

        fill_gv_table(c->table_gV, 4, cgv);

        break;

    default:

        if(!isPlanar(c->dstFormat) || bpp <= 24)

            av_log(c, AV_LOG_ERROR, "%ibpp not supported by yuv2rgb\n", bpp);

        return -1;

    }

    return 0;

}

static void build_chunks(MOVTrack *trk)

{

    int i;

    MOVIentry *chunk= &trk->cluster[0];

    uint64_t chunkSize = chunk->size;

    chunk->chunkNum= 1;

    trk->chunkCount= 1;

    for(i=1; i<trk->entry; i++){

        if(chunk->pos + chunkSize == trk->cluster[i].pos){

            chunkSize             += trk->cluster[i].size;

            chunk->samplesInChunk += trk->cluster[i].entries;

        }else{

            trk->cluster[i].chunkNum = chunk->chunkNum+1;

            chunk=&trk->cluster[i];

            chunkSize = chunk->size;

            trk->chunkCount++;

        }

    }

}

static int encode_frame(AVCodecContext *avctx, AVPacket *pkt,

                        const AVFrame *pic, int *got_packet)

{

    ProresContext *ctx = avctx->priv_data;

    uint8_t *orig_buf, *buf, *slice_hdr, *slice_sizes, *tmp;

    uint8_t *picture_size_pos;

    PutBitContext pb;

    int x, y, i, mb, q = 0;

    int sizes[4] = { 0 };

    int slice_hdr_size = 2 + 2 * (ctx->num_planes - 1);

    int frame_size, picture_size, slice_size;

    int pkt_size, ret;

    uint8_t frame_flags;



    *avctx->coded_frame           = *pic;

    avctx->coded_frame->pict_type = AV_PICTURE_TYPE_I;

    avctx->coded_frame->key_frame = 1;



    pkt_size = ctx->frame_size_upper_bound;



    if ((ret = ff_alloc_packet(pkt, pkt_size + FF_MIN_BUFFER_SIZE)) < 0) {

        av_log(avctx, AV_LOG_ERROR, "Error getting output packet.\n");

        return ret;

    }



    orig_buf = pkt->data;



    // frame atom

    orig_buf += 4;                              // frame size

    bytestream_put_be32  (&orig_buf, FRAME_ID); // frame container ID

    buf = orig_buf;



    // frame header

    tmp = buf;

    buf += 2;                                   // frame header size will be stored here

    bytestream_put_be16  (&buf, 0);             // version 1

    bytestream_put_buffer(&buf, ctx->vendor, 4);

    bytestream_put_be16  (&buf, avctx->width);

    bytestream_put_be16  (&buf, avctx->height);



    frame_flags = ctx->chroma_factor << 6;

    if (avctx->flags & CODEC_FLAG_INTERLACED_DCT)

        frame_flags |= pic->top_field_first ? 0x04 : 0x08;

    bytestream_put_byte  (&buf, frame_flags);



    bytestream_put_byte  (&buf, 0);             // reserved

    bytestream_put_byte  (&buf, avctx->color_primaries);

    bytestream_put_byte  (&buf, avctx->color_trc);

    bytestream_put_byte  (&buf, avctx->colorspace);

    bytestream_put_byte  (&buf, 0x40 | (ctx->alpha_bits >> 3));

    bytestream_put_byte  (&buf, 0);             // reserved

    if (ctx->quant_sel != QUANT_MAT_DEFAULT) {

        bytestream_put_byte  (&buf, 0x03);      // matrix flags - both matrices are present

        // luma quantisation matrix

        for (i = 0; i < 64; i++)

            bytestream_put_byte(&buf, ctx->quant_mat[i]);

        // chroma quantisation matrix

        for (i = 0; i < 64; i++)

            bytestream_put_byte(&buf, ctx->quant_mat[i]);

    } else {

        bytestream_put_byte  (&buf, 0x00);      // matrix flags - default matrices are used

    }

    bytestream_put_be16  (&tmp, buf - orig_buf); // write back frame header size



    for (ctx->cur_picture_idx = 0;

         ctx->cur_picture_idx < ctx->pictures_per_frame;

         ctx->cur_picture_idx++) {

        // picture header

        picture_size_pos = buf + 1;

        bytestream_put_byte  (&buf, 0x40);          // picture header size (in bits)

        buf += 4;                                   // picture data size will be stored here

        bytestream_put_be16  (&buf, ctx->slices_per_picture);

        bytestream_put_byte  (&buf, av_log2(ctx->mbs_per_slice) << 4); // slice width and height in MBs



        // seek table - will be filled during slice encoding

        slice_sizes = buf;

        buf += ctx->slices_per_picture * 2;



        // slices

        if (!ctx->force_quant) {

            ret = avctx->execute2(avctx, find_quant_thread, NULL, NULL,

                                  ctx->mb_height);

            if (ret)

                return ret;

        }



        for (y = 0; y < ctx->mb_height; y++) {

            int mbs_per_slice = ctx->mbs_per_slice;

            for (x = mb = 0; x < ctx->mb_width; x += mbs_per_slice, mb++) {

                q = ctx->force_quant ? ctx->force_quant

                                     : ctx->slice_q[mb + y * ctx->slices_width];



                while (ctx->mb_width - x < mbs_per_slice)

                    mbs_per_slice >>= 1;



                bytestream_put_byte(&buf, slice_hdr_size << 3);

                slice_hdr = buf;

                buf += slice_hdr_size - 1;

                init_put_bits(&pb, buf, (pkt_size - (buf - orig_buf)) * 8);

                ret = encode_slice(avctx, pic, &pb, sizes, x, y, q,

                                   mbs_per_slice);

                if (ret < 0)

                    return ret;



                bytestream_put_byte(&slice_hdr, q);

                slice_size = slice_hdr_size + sizes[ctx->num_planes - 1];

                for (i = 0; i < ctx->num_planes - 1; i++) {

                    bytestream_put_be16(&slice_hdr, sizes[i]);

                    slice_size += sizes[i];

                }

                bytestream_put_be16(&slice_sizes, slice_size);

                buf += slice_size - slice_hdr_size;

            }

        }



        if (ctx->pictures_per_frame == 1)

            picture_size = buf - picture_size_pos - 6;

        else

            picture_size = buf - picture_size_pos + 1;

        bytestream_put_be32(&picture_size_pos, picture_size);

    }



    orig_buf -= 8;

    frame_size = buf - orig_buf;

    bytestream_put_be32(&orig_buf, frame_size);



    pkt->size   = frame_size;

    pkt->flags |= AV_PKT_FLAG_KEY;

    *got_packet = 1;



    return 0;

}

void ff_lag_rac_init(lag_rac *l, GetBitContext *gb, int length)

{

    int i, j;



    /* According to reference decoder "1st byte is garbage",

     * however, it gets skipped by the call to align_get_bits()

     */

    align_get_bits(gb);

    l->bytestream_start =

    l->bytestream       = gb->buffer + get_bits_count(gb) / 8;

    l->bytestream_end   = l->bytestream_start + length;



    l->range        = 0x80;

    l->low          = *l->bytestream >> 1;

    l->hash_shift   = FFMAX(l->scale - 8, 0);



    for (i = j = 0; i < 256; i++) {

        unsigned r = i << l->hash_shift;

        while (l->prob[j + 1] <= r)

            j++;

        l->range_hash[i] = j;

    }



    /* Add conversion factor to hash_shift so we don't have to in lag_get_rac. */

    l->hash_shift += 23;

}

static inline void decode_residual_inter(AVSContext *h) {

    int block;



    /* get coded block pattern */

    h->cbp = cbp_tab[get_ue_golomb(&h->s.gb)][1];

    /* get quantizer */

    if(h->cbp && !h->qp_fixed)

        h->qp += get_se_golomb(&h->s.gb);

    for(block=0;block<4;block++)

        if(h->cbp & (1<<block))

            decode_residual_block(h,&h->s.gb,inter_2dvlc,0,h->qp,

                                  h->cy + h->luma_scan[block], h->l_stride);

    decode_residual_chroma(h);

}

int avpriv_mpa_decode_header(AVCodecContext *avctx, uint32_t head, int *sample_rate, int *channels, int *frame_size, int *bit_rate)

{

    MPADecodeHeader s1, *s = &s1;



    if (ff_mpa_check_header(head) != 0)

        return -1;



    if (avpriv_mpegaudio_decode_header(s, head) != 0) {

        return -1;

    }



    switch(s->layer) {

    case 1:

        avctx->codec_id = AV_CODEC_ID_MP1;

        *frame_size = 384;

        break;

    case 2:

        avctx->codec_id = AV_CODEC_ID_MP2;

        *frame_size = 1152;

        break;

    default:

    case 3:

        if (avctx->codec_id != AV_CODEC_ID_MP3ADU)

            avctx->codec_id = AV_CODEC_ID_MP3;

        if (s->lsf)

            *frame_size = 576;

        else

            *frame_size = 1152;

        break;

    }



    *sample_rate = s->sample_rate;

    *channels = s->nb_channels;

    *bit_rate = s->bit_rate;

    return s->frame_size;

}

static int seek_frame_generic(AVFormatContext *s,

                                 int stream_index, int64_t timestamp, int flags)

{

    int index;

    int64_t ret;

    AVStream *st;

    AVIndexEntry *ie;



    st = s->streams[stream_index];



    index = av_index_search_timestamp(st, timestamp, flags);



    if(index < 0 && st->nb_index_entries && timestamp < st->index_entries[0].timestamp)

        return -1;



    if(index < 0 || index==st->nb_index_entries-1){

        AVPacket pkt;

        int nonkey=0;



        if(st->nb_index_entries){

            assert(st->index_entries);

            ie= &st->index_entries[st->nb_index_entries-1];

            if ((ret = avio_seek(s->pb, ie->pos, SEEK_SET)) < 0)

                return ret;

            ff_update_cur_dts(s, st, ie->timestamp);

        }else{

            if ((ret = avio_seek(s->pb, s->data_offset, SEEK_SET)) < 0)

                return ret;

        }

        for (;;) {

            int read_status;

            do{

                read_status = av_read_frame(s, &pkt);

            } while (read_status == AVERROR(EAGAIN));

            if (read_status < 0)

                break;

            av_free_packet(&pkt);

            if(stream_index == pkt.stream_index && pkt.dts > timestamp){

                if(pkt.flags & AV_PKT_FLAG_KEY)

                    break;

                if(nonkey++ > 1000){

                    av_log(s, AV_LOG_ERROR,"seek_frame_generic failed as this stream seems to contain no keyframes after the target timestamp, %d non keyframes found\n", nonkey);

                    break;

                }

            }

        }

        index = av_index_search_timestamp(st, timestamp, flags);

    }

    if (index < 0)

        return -1;



    ff_read_frame_flush(s);

    AV_NOWARN_DEPRECATED(

    if (s->iformat->read_seek){

        if(s->iformat->read_seek(s, stream_index, timestamp, flags) >= 0)

            return 0;

    }

    )

    ie = &st->index_entries[index];

    if ((ret = avio_seek(s->pb, ie->pos, SEEK_SET)) < 0)

        return ret;

    ff_update_cur_dts(s, st, ie->timestamp);



    return 0;

}

static void dvbsub_parse_page_segment(AVCodecContext *avctx,

                                        const uint8_t *buf, int buf_size)

{

    DVBSubContext *ctx = avctx->priv_data;

    DVBSubRegionDisplay *display;

    DVBSubRegionDisplay *tmp_display_list, **tmp_ptr;



    const uint8_t *buf_end = buf + buf_size;

    int region_id;

    int page_state;



    if (buf_size < 1)

        return;



    ctx->time_out = *buf++;

    page_state = ((*buf++) >> 2) & 3;



    av_dlog(avctx, "Page time out %ds, state %d\n", ctx->time_out, page_state);



    if (page_state == 2) {

        delete_state(ctx);

    }



    tmp_display_list = ctx->display_list;

    ctx->display_list = NULL;

    ctx->display_list_size = 0;



    while (buf + 5 < buf_end) {

        region_id = *buf++;

        buf += 1;



        display = tmp_display_list;

        tmp_ptr = &tmp_display_list;



        while (display && display->region_id != region_id) {

            tmp_ptr = &display->next;

            display = display->next;

        }



        if (!display)

            display = av_mallocz(sizeof(DVBSubRegionDisplay));



        display->region_id = region_id;



        display->x_pos = AV_RB16(buf);

        buf += 2;

        display->y_pos = AV_RB16(buf);

        buf += 2;



        *tmp_ptr = display->next;



        display->next = ctx->display_list;

        ctx->display_list = display;

        ctx->display_list_size++;



        av_dlog(avctx, "Region %d, (%d,%d)\n", region_id, display->x_pos, display->y_pos);

    }



    while (tmp_display_list) {

        display = tmp_display_list;



        tmp_display_list = display->next;



        av_free(display);

    }



}

static int get_key(const char **ropts, const char *delim, char *key, unsigned key_size)

{

    unsigned key_pos = 0;

    const char *opts = *ropts;



    opts += strspn(opts, WHITESPACES);

    while (is_key_char(*opts)) {

        key[key_pos++] = *opts;

        if (key_pos == key_size)

            key_pos--;

        (opts)++;

    }

    opts += strspn(opts, WHITESPACES);

    if (!*opts || !strchr(delim, *opts))

        return AVERROR(EINVAL);

    opts++;

    key[key_pos++] = 0;

    if (key_pos == key_size)

        key[key_pos - 4] = key[key_pos - 3] = key[key_pos - 2] = '.';

    *ropts = opts;

    return 0;

}

static void expand_timestamps(void *log, struct sbg_script *s)

{

    int i, nb_rel = 0;

    int64_t now, cur_ts, delta = 0;



    for (i = 0; i < s->nb_tseq; i++)

        nb_rel += s->tseq[i].ts.type == 'N';

    if (nb_rel == s->nb_tseq) {

        /* All ts are relative to NOW: consider NOW = 0 */

        now = 0;

        if (s->start_ts != AV_NOPTS_VALUE)

            av_log(log, AV_LOG_WARNING,

                   "Start time ignored in a purely relative script.\n");

    } else if (nb_rel == 0 && s->start_ts != AV_NOPTS_VALUE ||

               s->opt_start_at_first) {

        /* All ts are absolute and start time is specified */

        if (s->start_ts == AV_NOPTS_VALUE)

            s->start_ts = s->tseq[0].ts.t;

        now = s->start_ts;

    } else {

        /* Mixed relative/absolute ts: expand */

        time_t now0;

        struct tm *tm, tmpbuf;



        av_log(log, AV_LOG_WARNING,

               "Scripts with mixed absolute and relative timestamps can give "

               "unexpected results (pause, seeking, time zone change).\n");

#undef time

        time(&now0);

        tm = localtime_r(&now0, &tmpbuf);

        now = tm ? tm->tm_hour * 3600 + tm->tm_min * 60 + tm->tm_sec :

                   now0 % DAY;

        av_log(log, AV_LOG_INFO, "Using %02d:%02d:%02d as NOW.\n",

               (int)(now / 3600), (int)(now / 60) % 60, (int)now % 60);

        now *= AV_TIME_BASE;

        for (i = 0; i < s->nb_tseq; i++) {

            if (s->tseq[i].ts.type == 'N') {

                s->tseq[i].ts.t += now;

                s->tseq[i].ts.type = 'T'; /* not necessary */

            }

        }

    }

    if (s->start_ts == AV_NOPTS_VALUE)

        s->start_ts = s->opt_start_at_first ? s->tseq[0].ts.t : now;

    s->end_ts = s->opt_duration ? s->start_ts + s->opt_duration :

                AV_NOPTS_VALUE; /* may be overridden later by -E option */

    cur_ts = now;

    for (i = 0; i < s->nb_tseq; i++) {

        if (s->tseq[i].ts.t + delta < cur_ts)

            delta += DAY_TS;

        cur_ts = s->tseq[i].ts.t += delta;

    }

}

static void generate_len_table(uint8_t *dst, uint64_t *stats, int size){

    heap_elem_t h[size];

    int up[2*size];

    int len[2*size];

    int offset, i, next;



    for(offset=1; ; offset<<=1){

        for(i=0; i<size; i++){

            h[i].name = i;

            h[i].val = (stats[i] << 8) + offset;

        }

        for(i=size/2-1; i>=0; i--)

            heap_sift(h, i, size);



        for(next=size; next<size*2-1; next++){

            // merge the two smallest entries, and put it back in the heap

            uint64_t min1v = h[0].val;

            up[h[0].name] = next;

            h[0].val = INT64_MAX;

            heap_sift(h, 0, size);

            up[h[0].name] = next;

            h[0].name = next;

            h[0].val += min1v;

            heap_sift(h, 0, size);

        }



        len[2*size-2] = 0;

        for(i=2*size-3; i>=size; i--)

            len[i] = len[up[i]] + 1;

        for(i=0; i<size; i++) {

            dst[i] = len[up[i]] + 1;

            if(dst[i] > 32) break;

        }

        if(i==size) break;

    }

}

static int scale_vaapi_filter_frame(AVFilterLink *inlink, AVFrame *input_frame)

{

    AVFilterContext *avctx = inlink->dst;

    AVFilterLink *outlink = avctx->outputs[0];

    ScaleVAAPIContext *ctx = avctx->priv;

    AVFrame *output_frame = NULL;

    VASurfaceID input_surface, output_surface;

    VAProcPipelineParameterBuffer params;

    VABufferID params_id;

    VAStatus vas;

    int err;



    av_log(ctx, AV_LOG_DEBUG, "Filter input: %s, %ux%u (%"PRId64").\n",

           av_get_pix_fmt_name(input_frame->format),

           input_frame->width, input_frame->height, input_frame->pts);



    if (ctx->va_context == VA_INVALID_ID)

        return AVERROR(EINVAL);



    input_surface = (VASurfaceID)(uintptr_t)input_frame->data[3];

    av_log(ctx, AV_LOG_DEBUG, "Using surface %#x for scale input.\n",

           input_surface);



    output_frame = av_frame_alloc();

    if (!output_frame) {

        av_log(ctx, AV_LOG_ERROR, "Failed to allocate output frame.");

        err = AVERROR(ENOMEM);

        goto fail;

    }



    err = av_hwframe_get_buffer(ctx->output_frames_ref, output_frame, 0);

    if (err < 0) {

        av_log(ctx, AV_LOG_ERROR, "Failed to get surface for "

               "output: %d\n.", err);

    }



    output_surface = (VASurfaceID)(uintptr_t)output_frame->data[3];

    av_log(ctx, AV_LOG_DEBUG, "Using surface %#x for scale output.\n",

           output_surface);



    memset(&params, 0, sizeof(params));



    params.surface = input_surface;

    params.surface_region = 0;

    params.surface_color_standard =

        vaapi_proc_colour_standard(input_frame->colorspace);



    params.output_region = 0;

    params.output_background_color = 0xff000000;

    params.output_color_standard = params.surface_color_standard;



    params.pipeline_flags = 0;

    params.filter_flags = VA_FILTER_SCALING_HQ;



    vas = vaBeginPicture(ctx->hwctx->display,

                         ctx->va_context, output_surface);

    if (vas != VA_STATUS_SUCCESS) {

        av_log(ctx, AV_LOG_ERROR, "Failed to attach new picture: "

               "%d (%s).\n", vas, vaErrorStr(vas));

        err = AVERROR(EIO);

        goto fail;

    }



    vas = vaCreateBuffer(ctx->hwctx->display, ctx->va_context,

                         VAProcPipelineParameterBufferType,

                         sizeof(params), 1, &params, &params_id);

    if (vas != VA_STATUS_SUCCESS) {

        av_log(ctx, AV_LOG_ERROR, "Failed to create parameter buffer: "

               "%d (%s).\n", vas, vaErrorStr(vas));

        err = AVERROR(EIO);

        goto fail_after_begin;

    }

    av_log(ctx, AV_LOG_DEBUG, "Pipeline parameter buffer is %#x.\n",

           params_id);



    vas = vaRenderPicture(ctx->hwctx->display, ctx->va_context,

                          &params_id, 1);

    if (vas != VA_STATUS_SUCCESS) {

        av_log(ctx, AV_LOG_ERROR, "Failed to render parameter buffer: "

               "%d (%s).\n", vas, vaErrorStr(vas));

        err = AVERROR(EIO);

        goto fail_after_begin;

    }



    vas = vaEndPicture(ctx->hwctx->display, ctx->va_context);

    if (vas != VA_STATUS_SUCCESS) {

        av_log(ctx, AV_LOG_ERROR, "Failed to start picture processing: "

               "%d (%s).\n", vas, vaErrorStr(vas));

        err = AVERROR(EIO);

        goto fail_after_render;

    }



    if (ctx->hwctx->driver_quirks &

        AV_VAAPI_DRIVER_QUIRK_RENDER_PARAM_BUFFERS) {

        vas = vaDestroyBuffer(ctx->hwctx->display, params_id);

        if (vas != VA_STATUS_SUCCESS) {

            av_log(ctx, AV_LOG_ERROR, "Failed to free parameter buffer: "

                   "%d (%s).\n", vas, vaErrorStr(vas));

            // And ignore.

        }

    }



    av_frame_copy_props(output_frame, input_frame);

    av_frame_free(&input_frame);



    av_log(ctx, AV_LOG_DEBUG, "Filter output: %s, %ux%u (%"PRId64").\n",

           av_get_pix_fmt_name(output_frame->format),

           output_frame->width, output_frame->height, output_frame->pts);



    return ff_filter_frame(outlink, output_frame);



    // We want to make sure that if vaBeginPicture has been called, we also

    // call vaRenderPicture and vaEndPicture.  These calls may well fail or

    // do something else nasty, but once we're in this failure case there

    // isn't much else we can do.

fail_after_begin:

    vaRenderPicture(ctx->hwctx->display, ctx->va_context, &params_id, 1);

fail_after_render:

    vaEndPicture(ctx->hwctx->display, ctx->va_context);

fail:

    av_frame_free(&input_frame);

    av_frame_free(&output_frame);

    return err;

}

static int get_packet(URLContext *s, int for_header)

{

    RTMPContext *rt = s->priv_data;

    int ret;

    uint8_t *p;

    const uint8_t *next;

    uint32_t data_size;

    uint32_t ts, cts, pts=0;



    if (rt->state == STATE_STOPPED)

        return AVERROR_EOF;



    for (;;) {

        RTMPPacket rpkt = { 0 };

        if ((ret = ff_rtmp_packet_read(rt->stream, &rpkt,

                                       rt->chunk_size, rt->prev_pkt[0])) <= 0) {

            if (ret == 0) {

                return AVERROR(EAGAIN);

            } else {

                return AVERROR(EIO);

            }

        }

        rt->bytes_read += ret;

        if (rt->bytes_read > rt->last_bytes_read + rt->client_report_size) {

            av_log(s, AV_LOG_DEBUG, "Sending bytes read report\n");

            gen_bytes_read(s, rt, rpkt.timestamp + 1);

            rt->last_bytes_read = rt->bytes_read;

        }



        ret = rtmp_parse_result(s, rt, &rpkt);

        if (ret < 0) {//serious error in current packet

            ff_rtmp_packet_destroy(&rpkt);

            return -1;

        }

        if (rt->state == STATE_STOPPED) {

            ff_rtmp_packet_destroy(&rpkt);

            return AVERROR_EOF;

        }

        if (for_header && (rt->state == STATE_PLAYING || rt->state == STATE_PUBLISHING)) {

            ff_rtmp_packet_destroy(&rpkt);

            return 0;

        }

        if (!rpkt.data_size || !rt->is_input) {

            ff_rtmp_packet_destroy(&rpkt);

            continue;

        }

        if (rpkt.type == RTMP_PT_VIDEO || rpkt.type == RTMP_PT_AUDIO ||

           (rpkt.type == RTMP_PT_NOTIFY && !memcmp("\002\000\012onMetaData", rpkt.data, 13))) {

            ts = rpkt.timestamp;



            // generate packet header and put data into buffer for FLV demuxer

            rt->flv_off  = 0;

            rt->flv_size = rpkt.data_size + 15;

            rt->flv_data = p = av_realloc(rt->flv_data, rt->flv_size);

            bytestream_put_byte(&p, rpkt.type);

            bytestream_put_be24(&p, rpkt.data_size);

            bytestream_put_be24(&p, ts);

            bytestream_put_byte(&p, ts >> 24);

            bytestream_put_be24(&p, 0);

            bytestream_put_buffer(&p, rpkt.data, rpkt.data_size);

            bytestream_put_be32(&p, 0);

            ff_rtmp_packet_destroy(&rpkt);

            return 0;

        } else if (rpkt.type == RTMP_PT_METADATA) {

            // we got raw FLV data, make it available for FLV demuxer

            rt->flv_off  = 0;

            rt->flv_size = rpkt.data_size;

            rt->flv_data = av_realloc(rt->flv_data, rt->flv_size);

            /* rewrite timestamps */

            next = rpkt.data;

            ts = rpkt.timestamp;

            while (next - rpkt.data < rpkt.data_size - 11) {

                next++;

                data_size = bytestream_get_be24(&next);

                p=next;

                cts = bytestream_get_be24(&next);

                cts |= bytestream_get_byte(&next) << 24;

                if (pts==0)

                    pts=cts;

                ts += cts - pts;

                pts = cts;

                bytestream_put_be24(&p, ts);

                bytestream_put_byte(&p, ts >> 24);

                next += data_size + 3 + 4;

            }

            memcpy(rt->flv_data, rpkt.data, rpkt.data_size);

            ff_rtmp_packet_destroy(&rpkt);

            return 0;

        }

        ff_rtmp_packet_destroy(&rpkt);

    }

}

static void save_display_set(DVBSubContext *ctx)
{
    DVBSubRegion *region;
    DVBSubRegionDisplay *display;
    DVBSubCLUT *clut;
    uint32_t *clut_table;
    int x_pos, y_pos, width, height;
    int x, y, y_off, x_off;
    uint32_t *pbuf;
    char filename[32];
    static int fileno_index = 0;
    x_pos = -1;
    y_pos = -1;
    width = 0;
    height = 0;
    for (display = ctx->display_list; display; display = display->next) {
        region = get_region(ctx, display->region_id);
        if (x_pos == -1) {
            x_pos = display->x_pos;
            y_pos = display->y_pos;
            width = region->width;
            height = region->height;
        } else {
            if (display->x_pos < x_pos) {
                width += (x_pos - display->x_pos);
                x_pos = display->x_pos;
            }
            if (display->y_pos < y_pos) {
                height += (y_pos - display->y_pos);
                y_pos = display->y_pos;
            }
            if (display->x_pos + region->width > x_pos + width) {
                width = display->x_pos + region->width - x_pos;
            }
            if (display->y_pos + region->height > y_pos + height) {
                height = display->y_pos + region->height - y_pos;
            }
        }
    }
    if (x_pos >= 0) {
        pbuf = av_malloc(width * height * 4);
        for (display = ctx->display_list; display; display = display->next) {
            region = get_region(ctx, display->region_id);
            x_off = display->x_pos - x_pos;
            y_off = display->y_pos - y_pos;
            clut = get_clut(ctx, region->clut);
            if (!clut)
                clut = &default_clut;
            switch (region->depth) {
            case 2:
                clut_table = clut->clut4;
                break;
            case 8:
                clut_table = clut->clut256;
                break;
            case 4:
            default:
                clut_table = clut->clut16;
                break;
            }
            for (y = 0; y < region->height; y++) {
                for (x = 0; x < region->width; x++) {
                    pbuf[((y + y_off) * width) + x_off + x] =
                        clut_table[region->pbuf[y * region->width + x]];
                }
            }
        }
        snprintf(filename, sizeof(filename), "dvbs.%d", fileno_index);
        png_save2(filename, pbuf, width, height);
        av_freep(&pbuf);
    }
    fileno_index++;
}

void ff_MPV_encode_init_x86(MpegEncContext *s)

{

    int mm_flags = av_get_cpu_flags();

    const int dct_algo = s->avctx->dct_algo;



    if (dct_algo == FF_DCT_AUTO || dct_algo == FF_DCT_MMX) {

#if HAVE_MMX_INLINE

        if (mm_flags & AV_CPU_FLAG_MMX && HAVE_MMX)

            s->dct_quantize = dct_quantize_MMX;

#endif

#if HAVE_MMXEXT_INLINE

        if (mm_flags & AV_CPU_FLAG_MMXEXT && HAVE_MMXEXT)

            s->dct_quantize = dct_quantize_MMX2;

#endif

#if HAVE_SSE2_INLINE

        if (mm_flags & AV_CPU_FLAG_SSE2 && HAVE_SSE2)

            s->dct_quantize = dct_quantize_SSE2;

#endif

#if HAVE_SSSE3_INLINE

        if (mm_flags & AV_CPU_FLAG_SSSE3)

            s->dct_quantize = dct_quantize_SSSE3;

#endif

    }

}

static inline void RENAME(LEToUV)(uint8_t *dstU, uint8_t *dstV, const uint8_t *src1, const uint8_t *src2, long width, uint32_t *unused)

{

#if COMPILE_TEMPLATE_MMX

    __asm__ volatile(

        "mov                    %0, %%"REG_a"       \n\t"

        "1:                                         \n\t"

        "movq    (%1, %%"REG_a",2), %%mm0           \n\t"

        "movq   8(%1, %%"REG_a",2), %%mm1           \n\t"

        "movq    (%2, %%"REG_a",2), %%mm2           \n\t"

        "movq   8(%2, %%"REG_a",2), %%mm3           \n\t"

        "psrlw                  $8, %%mm0           \n\t"

        "psrlw                  $8, %%mm1           \n\t"

        "psrlw                  $8, %%mm2           \n\t"

        "psrlw                  $8, %%mm3           \n\t"

        "packuswb            %%mm1, %%mm0           \n\t"

        "packuswb            %%mm3, %%mm2           \n\t"

        "movq                %%mm0, (%3, %%"REG_a") \n\t"

        "movq                %%mm2, (%4, %%"REG_a") \n\t"

        "add                    $8, %%"REG_a"       \n\t"

        " js                    1b                  \n\t"

        : : "g" ((x86_reg)-width), "r" (src1+width*2), "r" (src2+width*2), "r" (dstU+width), "r" (dstV+width)

        : "%"REG_a

    );

#else

    int i;

    // FIXME I don't think this code is right for YUV444/422, since then h is not subsampled so

    // we need to skip each second pixel. Same for BEToUV.

    for (i=0; i<width; i++) {

        dstU[i]= src1[2*i + 1];

        dstV[i]= src2[2*i + 1];

    }

#endif

}

static void hls_decode_neighbour(HEVCContext *s, int x_ctb, int y_ctb,

                                 int ctb_addr_ts)

{

    HEVCLocalContext *lc  = &s->HEVClc;

    int ctb_size          = 1 << s->ps.sps->log2_ctb_size;

    int ctb_addr_rs       = s->ps.pps->ctb_addr_ts_to_rs[ctb_addr_ts];

    int ctb_addr_in_slice = ctb_addr_rs - s->sh.slice_addr;



    s->tab_slice_address[ctb_addr_rs] = s->sh.slice_addr;



    if (s->ps.pps->entropy_coding_sync_enabled_flag) {

        if (x_ctb == 0 && (y_ctb & (ctb_size - 1)) == 0)

            lc->first_qp_group = 1;

        lc->end_of_tiles_x = s->ps.sps->width;

    } else if (s->ps.pps->tiles_enabled_flag) {

        if (ctb_addr_ts && s->ps.pps->tile_id[ctb_addr_ts] != s->ps.pps->tile_id[ctb_addr_ts - 1]) {

            int idxX = s->ps.pps->col_idxX[x_ctb >> s->ps.sps->log2_ctb_size];

            lc->start_of_tiles_x = x_ctb;

            lc->end_of_tiles_x   = x_ctb + (s->ps.pps->column_width[idxX] << s->ps.sps->log2_ctb_size);

            lc->first_qp_group   = 1;

        }

    } else {

        lc->end_of_tiles_x = s->ps.sps->width;

    }



    lc->end_of_tiles_y = FFMIN(y_ctb + ctb_size, s->ps.sps->height);



    lc->boundary_flags = 0;

    if (s->ps.pps->tiles_enabled_flag) {

        if (x_ctb > 0 && s->ps.pps->tile_id[ctb_addr_ts] != s->ps.pps->tile_id[s->ps.pps->ctb_addr_rs_to_ts[ctb_addr_rs - 1]])

            lc->boundary_flags |= BOUNDARY_LEFT_TILE;

        if (x_ctb > 0 && s->tab_slice_address[ctb_addr_rs] != s->tab_slice_address[ctb_addr_rs - 1])

            lc->boundary_flags |= BOUNDARY_LEFT_SLICE;

        if (y_ctb > 0 && s->ps.pps->tile_id[ctb_addr_ts] != s->ps.pps->tile_id[s->ps.pps->ctb_addr_rs_to_ts[ctb_addr_rs - s->ps.sps->ctb_width]])

            lc->boundary_flags |= BOUNDARY_UPPER_TILE;

        if (y_ctb > 0 && s->tab_slice_address[ctb_addr_rs] != s->tab_slice_address[ctb_addr_rs - s->ps.sps->ctb_width])

            lc->boundary_flags |= BOUNDARY_UPPER_SLICE;

    } else {

        if (!ctb_addr_in_slice > 0)

            lc->boundary_flags |= BOUNDARY_LEFT_SLICE;

        if (ctb_addr_in_slice < s->ps.sps->ctb_width)

            lc->boundary_flags |= BOUNDARY_UPPER_SLICE;

    }



    lc->ctb_left_flag = ((x_ctb > 0) && (ctb_addr_in_slice > 0) && !(lc->boundary_flags & BOUNDARY_LEFT_TILE));

    lc->ctb_up_flag   = ((y_ctb > 0) && (ctb_addr_in_slice >= s->ps.sps->ctb_width) && !(lc->boundary_flags & BOUNDARY_UPPER_TILE));

    lc->ctb_up_right_flag = ((y_ctb > 0)  && (ctb_addr_in_slice+1 >= s->ps.sps->ctb_width) && (s->ps.pps->tile_id[ctb_addr_ts] == s->ps.pps->tile_id[s->ps.pps->ctb_addr_rs_to_ts[ctb_addr_rs+1 - s->ps.sps->ctb_width]]));

    lc->ctb_up_left_flag = ((x_ctb > 0) && (y_ctb > 0)  && (ctb_addr_in_slice-1 >= s->ps.sps->ctb_width) && (s->ps.pps->tile_id[ctb_addr_ts] == s->ps.pps->tile_id[s->ps.pps->ctb_addr_rs_to_ts[ctb_addr_rs-1 - s->ps.sps->ctb_width]]));

}

static int vorbis_packet(AVFormatContext *s, int idx)

{

    struct ogg *ogg = s->priv_data;

    struct ogg_stream *os = ogg->streams + idx;

    struct oggvorbis_private *priv = os->private;

    int duration;



    /* first packet handling

       here we parse the duration of each packet in the first page and compare

       the total duration to the page granule to find the encoder delay and

       set the first timestamp */

    if (!os->lastpts) {

        int seg;

        uint8_t *last_pkt = os->buf + os->pstart;

        uint8_t *next_pkt = last_pkt;

        int first_duration = 0;



        avpriv_vorbis_parse_reset(&priv->vp);

        duration = 0;

        for (seg = 0; seg < os->nsegs; seg++) {

            if (os->segments[seg] < 255) {

                int d = avpriv_vorbis_parse_frame(&priv->vp, last_pkt, 1);

                if (d < 0) {

                    duration = os->granule;

                    break;

                }

                if (!duration)

                    first_duration = d;

                duration += d;

                last_pkt = next_pkt + os->segments[seg];

            }

            next_pkt += os->segments[seg];

        }

        os->lastpts = os->lastdts   = os->granule - duration;

        s->streams[idx]->start_time = os->lastpts + first_duration;

        if (s->streams[idx]->duration)

            s->streams[idx]->duration -= s->streams[idx]->start_time;

        s->streams[idx]->cur_dts    = AV_NOPTS_VALUE;

        priv->final_pts             = AV_NOPTS_VALUE;

        avpriv_vorbis_parse_reset(&priv->vp);

    }



    /* parse packet duration */

    if (os->psize > 0) {

        duration = avpriv_vorbis_parse_frame(&priv->vp, os->buf + os->pstart, 1);

        if (duration <= 0) {

            os->pflags |= AV_PKT_FLAG_CORRUPT;

            return 0;

        }

        os->pduration = duration;

    }



    /* final packet handling

       here we save the pts of the first packet in the final page, sum up all

       packet durations in the final page except for the last one, and compare

       to the page granule to find the duration of the final packet */

    if (os->flags & OGG_FLAG_EOS) {

        if (os->lastpts != AV_NOPTS_VALUE) {

            priv->final_pts = os->lastpts;

            priv->final_duration = 0;

        }

        if (os->segp == os->nsegs)

            os->pduration = os->granule - priv->final_pts - priv->final_duration;

        priv->final_duration += os->pduration;

    }



    return 0;

}

int ff_vaapi_render_picture(FFVAContext *vactx, VASurfaceID surface)

{

    VABufferID va_buffers[3];

    unsigned int n_va_buffers = 0;



    if (!vactx->pic_param_buf_id)

        return 0;



    vaUnmapBuffer(vactx->display, vactx->pic_param_buf_id);

    va_buffers[n_va_buffers++] = vactx->pic_param_buf_id;



    if (vactx->iq_matrix_buf_id) {

        vaUnmapBuffer(vactx->display, vactx->iq_matrix_buf_id);

        va_buffers[n_va_buffers++] = vactx->iq_matrix_buf_id;

    }



    if (vactx->bitplane_buf_id) {

        vaUnmapBuffer(vactx->display, vactx->bitplane_buf_id);

        va_buffers[n_va_buffers++] = vactx->bitplane_buf_id;

    }



    if (vaBeginPicture(vactx->display, vactx->context_id,

                       surface) != VA_STATUS_SUCCESS)

        return -1;



    if (vaRenderPicture(vactx->display, vactx->context_id,

                        va_buffers, n_va_buffers) != VA_STATUS_SUCCESS)

        return -1;



    if (vaRenderPicture(vactx->display, vactx->context_id,

                        vactx->slice_buf_ids,

                        vactx->n_slice_buf_ids) != VA_STATUS_SUCCESS)

        return -1;



    if (vaEndPicture(vactx->display, vactx->context_id) != VA_STATUS_SUCCESS)

        return -1;



    return 0;

}

static void loop_filter(H264Context *h){

    MpegEncContext * const s = &h->s;

    uint8_t  *dest_y, *dest_cb, *dest_cr;

    int linesize, uvlinesize, mb_x, mb_y;

    const int end_mb_y= s->mb_y + FRAME_MBAFF;

    const int old_slice_type= h->slice_type;



    if(h->deblocking_filter) {

        for(mb_x= 0; mb_x<s->mb_width; mb_x++){

            for(mb_y=end_mb_y - FRAME_MBAFF; mb_y<= end_mb_y; mb_y++){

                int list, mb_xy, mb_type;

                mb_xy = h->mb_xy = mb_x + mb_y*s->mb_stride;

                h->slice_num= h->slice_table[mb_xy];

                mb_type= s->current_picture.mb_type[mb_xy];

                h->list_count= h->list_counts[mb_xy];



                if(FRAME_MBAFF)

                    h->mb_mbaff = h->mb_field_decoding_flag = !!IS_INTERLACED(mb_type);



                s->mb_x= mb_x;

                s->mb_y= mb_y;

                dest_y  = s->current_picture.data[0] + (mb_x + mb_y * s->linesize  ) * 16;

                dest_cb = s->current_picture.data[1] + (mb_x + mb_y * s->uvlinesize) * 8;

                dest_cr = s->current_picture.data[2] + (mb_x + mb_y * s->uvlinesize) * 8;

                    //FIXME simplify above



                if (MB_FIELD) {

                    linesize   = h->mb_linesize   = s->linesize * 2;

                    uvlinesize = h->mb_uvlinesize = s->uvlinesize * 2;

                    if(mb_y&1){ //FIXME move out of this function?

                        dest_y -= s->linesize*15;

                        dest_cb-= s->uvlinesize*7;

                        dest_cr-= s->uvlinesize*7;

                    }

                } else {

                    linesize   = h->mb_linesize   = s->linesize;

                    uvlinesize = h->mb_uvlinesize = s->uvlinesize;

                }

                backup_mb_border(h, dest_y, dest_cb, dest_cr, linesize, uvlinesize, 0);

                if(fill_filter_caches(h, mb_type) < 0)

                    continue;

                h->chroma_qp[0] = get_chroma_qp(h, 0, s->current_picture.qscale_table[mb_xy]);

                h->chroma_qp[1] = get_chroma_qp(h, 1, s->current_picture.qscale_table[mb_xy]);



                if (FRAME_MBAFF) {

                    ff_h264_filter_mb     (h, mb_x, mb_y, dest_y, dest_cb, dest_cr, linesize, uvlinesize);

                } else {

                    ff_h264_filter_mb_fast(h, mb_x, mb_y, dest_y, dest_cb, dest_cr, linesize, uvlinesize);

                }

            }

        }

    }

    h->slice_type= old_slice_type;

    s->mb_x= 0;

    s->mb_y= end_mb_y - FRAME_MBAFF;

}

static int mov_write_tfhd_tag(AVIOContext *pb, MOVTrack *track,

                              int64_t moof_offset)

{

    int64_t pos = avio_tell(pb);

    uint32_t flags = MOV_TFHD_DEFAULT_SIZE | MOV_TFHD_DEFAULT_DURATION |

                     MOV_TFHD_BASE_DATA_OFFSET;

    if (!track->entry) {

        flags |= MOV_TFHD_DURATION_IS_EMPTY;

    } else {

        flags |= MOV_TFHD_DEFAULT_FLAGS;

    }



    /* Don't set a default sample size, the silverlight player refuses

     * to play files with that set. Don't set a default sample duration,

     * WMP freaks out if it is set. */

    if (track->mode == MODE_ISM)

        flags &= ~(MOV_TFHD_DEFAULT_SIZE | MOV_TFHD_DEFAULT_DURATION);



    avio_wb32(pb, 0); /* size placeholder */

    ffio_wfourcc(pb, "tfhd");

    avio_w8(pb, 0); /* version */

    avio_wb24(pb, flags);



    avio_wb32(pb, track->track_id); /* track-id */

    if (flags & MOV_TFHD_BASE_DATA_OFFSET)

        avio_wb64(pb, moof_offset);

    if (flags & MOV_TFHD_DEFAULT_DURATION) {

        track->default_duration = get_cluster_duration(track, 0);

        avio_wb32(pb, track->default_duration);

    }

    if (flags & MOV_TFHD_DEFAULT_SIZE) {

        track->default_size = track->entry ? track->cluster[0].size : 1;

        avio_wb32(pb, track->default_size);

    } else

        track->default_size = -1;



    if (flags & MOV_TFHD_DEFAULT_FLAGS) {

        track->default_sample_flags =

            track->enc->codec_type == AVMEDIA_TYPE_VIDEO ?

            (MOV_FRAG_SAMPLE_FLAG_DEPENDS_YES | MOV_FRAG_SAMPLE_FLAG_IS_NON_SYNC) :

            MOV_FRAG_SAMPLE_FLAG_DEPENDS_NO;

        avio_wb32(pb, track->default_sample_flags);

    }



    return update_size(pb, pos);

}

static int normalize_samples(AC3EncodeContext *s)

{

    int v = 14 - log2_tab(s, s->windowed_samples, AC3_WINDOW_SIZE);

    lshift_tab(s->windowed_samples, AC3_WINDOW_SIZE, v);

    return v - 9;

}

static int decode_subframe_fixed(FLACContext *s, int32_t *decoded,

                                 int pred_order, int bps)

{

    const int blocksize = s->blocksize;

    unsigned av_uninit(a), av_uninit(b), av_uninit(c), av_uninit(d);

    int i;

    int ret;



    /* warm up samples */

    for (i = 0; i < pred_order; i++) {

        decoded[i] = get_sbits_long(&s->gb, bps);

    }



    if ((ret = decode_residuals(s, decoded, pred_order)) < 0)

        return ret;



    if (pred_order > 0)

        a = decoded[pred_order-1];

    if (pred_order > 1)

        b = a - decoded[pred_order-2];

    if (pred_order > 2)

        c = b - decoded[pred_order-2] + decoded[pred_order-3];

    if (pred_order > 3)

        d = c - decoded[pred_order-2] + 2*decoded[pred_order-3] - decoded[pred_order-4];



    switch (pred_order) {

    case 0:

        break;

    case 1:

        for (i = pred_order; i < blocksize; i++)

            decoded[i] = a += decoded[i];

        break;

    case 2:

        for (i = pred_order; i < blocksize; i++)

            decoded[i] = a += b += decoded[i];

        break;

    case 3:

        for (i = pred_order; i < blocksize; i++)

            decoded[i] = a += b += c += decoded[i];

        break;

    case 4:

        for (i = pred_order; i < blocksize; i++)

            decoded[i] = a += b += c += d += decoded[i];

        break;

    default:

        av_log(s->avctx, AV_LOG_ERROR, "illegal pred order %d\n", pred_order);

        return AVERROR_INVALIDDATA;

    }



    return 0;

}

static int add_tonal_components(float *spectrum, int num_components,

                                TonalComponent *components)

{

    int i, j, last_pos = -1;

    float *input, *output;



    for (i = 0; i < num_components; i++) {

        last_pos = FFMAX(components[i].pos + components[i].num_coefs, last_pos);

        input    = components[i].coef;

        output   = &spectrum[components[i].pos];



        for (j = 0; j < components[i].num_coefs; j++)

            output[i] += input[i];

    }



    return last_pos;

}

static inline void RENAME(yuv2rgb32_1)(SwsContext *c, const uint16_t *buf0,

                                       const uint16_t *ubuf0, const uint16_t *ubuf1,

                                       const uint16_t *vbuf0, const uint16_t *vbuf1,

                                       const uint16_t *abuf0, uint8_t *dest,

                                       int dstW, int uvalpha, enum PixelFormat dstFormat,

                                       int flags, int y)

{

    x86_reg uv_off = c->uv_off << 1;

    const uint16_t *buf1= buf0; //FIXME needed for RGB1/BGR1



    if (uvalpha < 2048) { // note this is not correct (shifts chrominance by 0.5 pixels) but it is a bit faster

        if (CONFIG_SWSCALE_ALPHA && c->alpPixBuf) {

            __asm__ volatile(

                "mov %%"REG_b", "ESP_OFFSET"(%5)        \n\t"

                "mov        %4, %%"REG_b"               \n\t"

                "push %%"REG_BP"                        \n\t"

                YSCALEYUV2RGB1(%%REGBP, %5, %6)

                YSCALEYUV2RGB1_ALPHA(%%REGBP)

                WRITEBGR32(%%REGb, 8280(%5), %%REGBP, %%mm2, %%mm4, %%mm5, %%mm7, %%mm0, %%mm1, %%mm3, %%mm6)

                "pop %%"REG_BP"                         \n\t"

                "mov "ESP_OFFSET"(%5), %%"REG_b"        \n\t"

                :: "c" (buf0), "d" (abuf0), "S" (ubuf0), "D" (ubuf1), "m" (dest),

                   "a" (&c->redDither), "m"(uv_off)

            );

        } else {

            __asm__ volatile(

                "mov %%"REG_b", "ESP_OFFSET"(%5)        \n\t"

                "mov        %4, %%"REG_b"               \n\t"

                "push %%"REG_BP"                        \n\t"

                YSCALEYUV2RGB1(%%REGBP, %5, %6)

                "pcmpeqd %%mm7, %%mm7                   \n\t"

                WRITEBGR32(%%REGb, 8280(%5), %%REGBP, %%mm2, %%mm4, %%mm5, %%mm7, %%mm0, %%mm1, %%mm3, %%mm6)

                "pop %%"REG_BP"                         \n\t"

                "mov "ESP_OFFSET"(%5), %%"REG_b"        \n\t"

                :: "c" (buf0), "d" (buf1), "S" (ubuf0), "D" (ubuf1), "m" (dest),

                   "a" (&c->redDither), "m"(uv_off)

            );

        }

    } else {

        if (CONFIG_SWSCALE_ALPHA && c->alpPixBuf) {

            __asm__ volatile(

                "mov %%"REG_b", "ESP_OFFSET"(%5)        \n\t"

                "mov        %4, %%"REG_b"               \n\t"

                "push %%"REG_BP"                        \n\t"

                YSCALEYUV2RGB1b(%%REGBP, %5, %6)

                YSCALEYUV2RGB1_ALPHA(%%REGBP)

                WRITEBGR32(%%REGb, 8280(%5), %%REGBP, %%mm2, %%mm4, %%mm5, %%mm7, %%mm0, %%mm1, %%mm3, %%mm6)

                "pop %%"REG_BP"                         \n\t"

                "mov "ESP_OFFSET"(%5), %%"REG_b"        \n\t"

                :: "c" (buf0), "d" (abuf0), "S" (ubuf0), "D" (ubuf1), "m" (dest),

                   "a" (&c->redDither), "m"(uv_off)

            );

        } else {

            __asm__ volatile(

                "mov %%"REG_b", "ESP_OFFSET"(%5)        \n\t"

                "mov        %4, %%"REG_b"               \n\t"

                "push %%"REG_BP"                        \n\t"

                YSCALEYUV2RGB1b(%%REGBP, %5, %6)

                "pcmpeqd %%mm7, %%mm7                   \n\t"

                WRITEBGR32(%%REGb, 8280(%5), %%REGBP, %%mm2, %%mm4, %%mm5, %%mm7, %%mm0, %%mm1, %%mm3, %%mm6)

                "pop %%"REG_BP"                         \n\t"

                "mov "ESP_OFFSET"(%5), %%"REG_b"        \n\t"

                :: "c" (buf0), "d" (buf1), "S" (ubuf0), "D" (ubuf1), "m" (dest),

                   "a" (&c->redDither), "m"(uv_off)

            );

        }

    }

}

static int libopenjpeg_copy_packed8(AVCodecContext *avctx, const AVFrame *frame, opj_image_t *image)

{

    int compno;

    int x;

    int y;

    int *image_line;

    int frame_index;

    const int numcomps = image->numcomps;



    for (compno = 0; compno < numcomps; ++compno) {

        if (image->comps[compno].w > frame->linesize[0] / numcomps) {

            av_log(avctx, AV_LOG_ERROR, "Error: frame's linesize is too small for the image\n");

            return 0;

        }

    }



    for (compno = 0; compno < numcomps; ++compno) {

        for (y = 0; y < avctx->height; ++y) {

            image_line = image->comps[compno].data + y * image->comps[compno].w;

            frame_index = y * frame->linesize[0] + compno;

            for (x = 0; x < avctx->width; ++x) {

                image_line[x] = frame->data[0][frame_index];

                frame_index += numcomps;

            }

            for (; x < image->comps[compno].w; ++x) {

                image_line[x] = image_line[x - 1];

            }

        }

        for (; y < image->comps[compno].h; ++y) {

            image_line = image->comps[compno].data + y * image->comps[compno].w;

            for (x = 0; x < image->comps[compno].w; ++x) {

                image_line[x] = image_line[x - image->comps[compno].w];

            }

        }

    }



    return 1;

}

static av_cold int decode_init(AVCodecContext *avctx)

{

    ASV1Context *const a = avctx->priv_data;

    const int scale      = avctx->codec_id == AV_CODEC_ID_ASV1 ? 1 : 2;

    int i;



    if (avctx->extradata_size < 1) {

        av_log(avctx, AV_LOG_ERROR, "No extradata provided\n");

        return AVERROR_INVALIDDATA;

    }



    ff_asv_common_init(avctx);

    ff_blockdsp_init(&a->bdsp, avctx);

    ff_idctdsp_init(&a->idsp, avctx);

    init_vlcs(a);

    ff_init_scantable(a->idsp.idct_permutation, &a->scantable, ff_asv_scantab);

    avctx->pix_fmt = AV_PIX_FMT_YUV420P;



    a->inv_qscale = avctx->extradata[0];

    if (a->inv_qscale == 0) {

        av_log(avctx, AV_LOG_ERROR, "illegal qscale 0\n");

        if (avctx->codec_id == AV_CODEC_ID_ASV1)

            a->inv_qscale = 6;

        else

            a->inv_qscale = 10;

    }



    for (i = 0; i < 64; i++) {

        int index = ff_asv_scantab[i];



        a->intra_matrix[i] = 64 * scale * ff_mpeg1_default_intra_matrix[index] /

                             a->inv_qscale;

    }



    return 0;

}

int ff_mjpeg_decode_sos(MJpegDecodeContext *s, const uint8_t *mb_bitmask,

                        const AVFrame *reference)

{

    int len, nb_components, i, h, v, predictor, point_transform;

    int index, id, ret;

    const int block_size = s->lossless ? 1 : 8;

    int ilv, prev_shift;



    if (!s->got_picture) {

        av_log(s->avctx, AV_LOG_WARNING,

                "Can not process SOS before SOF, skipping\n");

        return -1;

    }



    av_assert0(s->picture_ptr->data[0]);

    /* XXX: verify len field validity */

    len = get_bits(&s->gb, 16);

    nb_components = get_bits(&s->gb, 8);

    if (nb_components == 0 || nb_components > MAX_COMPONENTS) {

        av_log(s->avctx, AV_LOG_ERROR,

               "decode_sos: nb_components (%d) unsupported\n", nb_components);

        return AVERROR_PATCHWELCOME;

    }

    if (len != 6 + 2 * nb_components) {

        av_log(s->avctx, AV_LOG_ERROR, "decode_sos: invalid len (%d)\n", len);

        return AVERROR_INVALIDDATA;

    }

    for (i = 0; i < nb_components; i++) {

        id = get_bits(&s->gb, 8) - 1;

        av_log(s->avctx, AV_LOG_DEBUG, "component: %d\n", id);

        /* find component index */

        for (index = 0; index < s->nb_components; index++)

            if (id == s->component_id[index])

                break;

        if (index == s->nb_components) {

            av_log(s->avctx, AV_LOG_ERROR,

                   "decode_sos: index(%d) out of components\n", index);

            return AVERROR_INVALIDDATA;

        }

        /* Metasoft MJPEG codec has Cb and Cr swapped */

        if (s->avctx->codec_tag == MKTAG('M', 'T', 'S', 'J')

            && nb_components == 3 && s->nb_components == 3 && i)

            index = 3 - i;



        if(nb_components == 3 && s->nb_components == 3 && s->avctx->pix_fmt == AV_PIX_FMT_GBR24P)

            index = (i+2)%3;

        if(nb_components == 1 && s->nb_components == 3 && s->avctx->pix_fmt == AV_PIX_FMT_GBR24P)

            index = (index+2)%3;



        s->comp_index[i] = index;



        s->nb_blocks[i] = s->h_count[index] * s->v_count[index];

        s->h_scount[i]  = s->h_count[index];

        s->v_scount[i]  = s->v_count[index];



        s->dc_index[i] = get_bits(&s->gb, 4);

        s->ac_index[i] = get_bits(&s->gb, 4);



        if (s->dc_index[i] <  0 || s->ac_index[i] < 0 ||

            s->dc_index[i] >= 4 || s->ac_index[i] >= 4)

            goto out_of_range;

        if (!s->vlcs[0][s->dc_index[i]].table || !(s->progressive ? s->vlcs[2][s->ac_index[0]].table : s->vlcs[1][s->ac_index[i]].table))

            goto out_of_range;

    }



    predictor = get_bits(&s->gb, 8);       /* JPEG Ss / lossless JPEG predictor /JPEG-LS NEAR */

    ilv = get_bits(&s->gb, 8);             /* JPEG Se / JPEG-LS ILV */

    if(s->avctx->codec_tag != AV_RL32("CJPG")){

        prev_shift      = get_bits(&s->gb, 4); /* Ah */

        point_transform = get_bits(&s->gb, 4); /* Al */

    }else

        prev_shift = point_transform = 0;



    if (nb_components > 1) {

        /* interleaved stream */

        s->mb_width  = (s->width  + s->h_max * block_size - 1) / (s->h_max * block_size);

        s->mb_height = (s->height + s->v_max * block_size - 1) / (s->v_max * block_size);

    } else if (!s->ls) { /* skip this for JPEG-LS */

        h = s->h_max / s->h_scount[0];

        v = s->v_max / s->v_scount[0];

        s->mb_width     = (s->width  + h * block_size - 1) / (h * block_size);

        s->mb_height    = (s->height + v * block_size - 1) / (v * block_size);

        s->nb_blocks[0] = 1;

        s->h_scount[0]  = 1;

        s->v_scount[0]  = 1;

    }



    if (s->avctx->debug & FF_DEBUG_PICT_INFO)

        av_log(s->avctx, AV_LOG_DEBUG, "%s %s p:%d >>:%d ilv:%d bits:%d skip:%d %s comp:%d\n",

               s->lossless ? "lossless" : "sequential DCT", s->rgb ? "RGB" : "",

               predictor, point_transform, ilv, s->bits, s->mjpb_skiptosod,

               s->pegasus_rct ? "PRCT" : (s->rct ? "RCT" : ""), nb_components);





    /* mjpeg-b can have padding bytes between sos and image data, skip them */

    for (i = s->mjpb_skiptosod; i > 0; i--)

        skip_bits(&s->gb, 8);



next_field:

    for (i = 0; i < nb_components; i++)

        s->last_dc[i] = 1024;



    if (s->lossless) {

        av_assert0(s->picture_ptr == &s->picture);

        if (CONFIG_JPEGLS_DECODER && s->ls) {

//            for () {

//            reset_ls_coding_parameters(s, 0);



            if ((ret = ff_jpegls_decode_picture(s, predictor,

                                                point_transform, ilv)) < 0)

                return ret;

        } else {

            if (s->rgb) {

                if ((ret = ljpeg_decode_rgb_scan(s, nb_components, predictor, point_transform)) < 0)

                    return ret;

            } else {

                if ((ret = ljpeg_decode_yuv_scan(s, predictor,

                                                 point_transform,

                                                 nb_components)) < 0)

                    return ret;

            }

        }

    } else {

        if (s->progressive && predictor) {

            av_assert0(s->picture_ptr == &s->picture);

            if ((ret = mjpeg_decode_scan_progressive_ac(s, predictor,

                                                        ilv, prev_shift,

                                                        point_transform)) < 0)

                return ret;

        } else {

            if ((ret = mjpeg_decode_scan(s, nb_components,

                                         prev_shift, point_transform,

                                         mb_bitmask, reference)) < 0)

                return ret;

        }

    }



    if (s->interlaced &&

        get_bits_left(&s->gb) > 32 &&

        show_bits(&s->gb, 8) == 0xFF) {

        GetBitContext bak = s->gb;

        align_get_bits(&bak);

        if (show_bits(&bak, 16) == 0xFFD1) {

            av_log(s->avctx, AV_LOG_DEBUG, "AVRn interlaced picture marker found\n");

            s->gb = bak;

            skip_bits(&s->gb, 16);

            s->bottom_field ^= 1;



            goto next_field;

        }

    }



    emms_c();

    return 0;

 out_of_range:

    av_log(s->avctx, AV_LOG_ERROR, "decode_sos: ac/dc index out of range\n");

    return AVERROR_INVALIDDATA;

}

static void do_video_out(AVFormatContext *s, 

                         AVOutputStream *ost, 

                         AVInputStream *ist,

                         AVFrame *in_picture,

                         int *frame_size, AVOutputStream *audio_sync)

{

    int nb_frames, i, ret;

    AVFrame *final_picture, *formatted_picture;

    AVFrame picture_format_temp, picture_crop_temp;

    static uint8_t *video_buffer= NULL;

    uint8_t *buf = NULL, *buf1 = NULL;

    AVCodecContext *enc, *dec;

    enum PixelFormat target_pixfmt;



#define VIDEO_BUFFER_SIZE (1024*1024)



    avcodec_get_frame_defaults(&picture_format_temp);

    avcodec_get_frame_defaults(&picture_crop_temp);



    enc = &ost->st->codec;

    dec = &ist->st->codec;



    /* by default, we output a single frame */

    nb_frames = 1;



    *frame_size = 0;



    if(sync_method){

        double vdelta;

        vdelta = ost->sync_ipts * enc->frame_rate / enc->frame_rate_base - ost->sync_opts;

        //FIXME set to 0.5 after we fix some dts/pts bugs like in avidec.c

        if (vdelta < -1.1)

            nb_frames = 0;

        else if (vdelta > 1.1)

            nb_frames = 2;

//printf("vdelta:%f, ost->sync_opts:%lld, ost->sync_ipts:%f nb_frames:%d\n", vdelta, ost->sync_opts, ost->sync_ipts, nb_frames);

    }

    ost->sync_opts+= nb_frames;



    if (nb_frames <= 0) 

        return;



    if (!video_buffer)

        video_buffer = av_malloc(VIDEO_BUFFER_SIZE);

    if (!video_buffer)

        return;



    /* convert pixel format if needed */

    target_pixfmt = ost->video_resample || ost->video_pad

        ? PIX_FMT_YUV420P : enc->pix_fmt;

    if (dec->pix_fmt != target_pixfmt) {

        int size;



        /* create temporary picture */

        size = avpicture_get_size(target_pixfmt, dec->width, dec->height);

        buf = av_malloc(size);

        if (!buf)

            return;

        formatted_picture = &picture_format_temp;

        avpicture_fill((AVPicture*)formatted_picture, buf, target_pixfmt, dec->width, dec->height);



        if (img_convert((AVPicture*)formatted_picture, target_pixfmt, 

                        (AVPicture *)in_picture, dec->pix_fmt, 

                        dec->width, dec->height) < 0) {



            if (verbose >= 0)

                fprintf(stderr, "pixel format conversion not handled\n");



            goto the_end;

        }

    } else {

        formatted_picture = in_picture;

    }



    /* XXX: resampling could be done before raw format conversion in

       some cases to go faster */

    /* XXX: only works for YUV420P */

    if (ost->video_resample) {

        final_picture = &ost->pict_tmp;

        img_resample(ost->img_resample_ctx, (AVPicture*)final_picture, (AVPicture*)formatted_picture);



        if (ost->padtop || ost->padbottom || ost->padleft || ost->padright) {

            fill_pad_region((AVPicture*)final_picture, enc->height, enc->width,

                    ost->padtop, ost->padbottom, ost->padleft, ost->padright,

                    padcolor);

        }



	if (enc->pix_fmt != PIX_FMT_YUV420P) {

            int size;



	    av_free(buf);

            /* create temporary picture */

            size = avpicture_get_size(enc->pix_fmt, enc->width, enc->height);

            buf = av_malloc(size);

            if (!buf)

                return;

            final_picture = &picture_format_temp;

            avpicture_fill((AVPicture*)final_picture, buf, enc->pix_fmt, enc->width, enc->height);



            if (img_convert((AVPicture*)final_picture, enc->pix_fmt, 

                            (AVPicture*)&ost->pict_tmp, PIX_FMT_YUV420P, 

                            enc->width, enc->height) < 0) {



                if (verbose >= 0)

                    fprintf(stderr, "pixel format conversion not handled\n");



                goto the_end;

            }

	}

    } else if (ost->video_crop) {

        picture_crop_temp.data[0] = formatted_picture->data[0] +

                (ost->topBand * formatted_picture->linesize[0]) + ost->leftBand;



        picture_crop_temp.data[1] = formatted_picture->data[1] +

                ((ost->topBand >> 1) * formatted_picture->linesize[1]) +

                (ost->leftBand >> 1);



        picture_crop_temp.data[2] = formatted_picture->data[2] +

                ((ost->topBand >> 1) * formatted_picture->linesize[2]) +

                (ost->leftBand >> 1);



        picture_crop_temp.linesize[0] = formatted_picture->linesize[0];

        picture_crop_temp.linesize[1] = formatted_picture->linesize[1];

        picture_crop_temp.linesize[2] = formatted_picture->linesize[2];

        final_picture = &picture_crop_temp;

    } else if (ost->video_pad) {

        final_picture = &ost->pict_tmp;



        for (i = 0; i < 3; i++) {

            uint8_t *optr, *iptr;

            int shift = (i == 0) ? 0 : 1;

            int y, yheight;



            /* set offset to start writing image into */

            optr = final_picture->data[i] + (((final_picture->linesize[i] * 

                            ost->padtop) + ost->padleft) >> shift);

            iptr = formatted_picture->data[i];



            yheight = (enc->height - ost->padtop - ost->padbottom) >> shift;

            for (y = 0; y < yheight; y++) {

                /* copy unpadded image row into padded image row */

                memcpy(optr, iptr, formatted_picture->linesize[i]);

                optr += final_picture->linesize[i];

                iptr += formatted_picture->linesize[i];

            }

        }



        fill_pad_region((AVPicture*)final_picture, enc->height, enc->width,

                ost->padtop, ost->padbottom, ost->padleft, ost->padright,

                padcolor);



        if (enc->pix_fmt != PIX_FMT_YUV420P) {

            int size;



            av_free(buf);

            /* create temporary picture */

            size = avpicture_get_size(enc->pix_fmt, enc->width, enc->height);

            buf = av_malloc(size);

            if (!buf)

                return;

            final_picture = &picture_format_temp;

            avpicture_fill((AVPicture*)final_picture, buf, enc->pix_fmt, enc->width, enc->height);



            if (img_convert((AVPicture*)final_picture, enc->pix_fmt, 

                        (AVPicture*)&ost->pict_tmp, PIX_FMT_YUV420P, 

                        enc->width, enc->height) < 0) {



                if (verbose >= 0)

                    fprintf(stderr, "pixel format conversion not handled\n");



                goto the_end;

            }

        }

    } else {

        final_picture = formatted_picture;

    }

    /* duplicates frame if needed */

    /* XXX: pb because no interleaving */

    for(i=0;i<nb_frames;i++) {

        AVPacket pkt;

        av_init_packet(&pkt);

        pkt.stream_index= ost->index;



        if (s->oformat->flags & AVFMT_RAWPICTURE) {

            /* raw pictures are written as AVPicture structure to

               avoid any copies. We support temorarily the older

               method. */

            AVFrame* old_frame = enc->coded_frame;

	    enc->coded_frame = dec->coded_frame; //FIXME/XXX remove this hack

            pkt.data= (uint8_t *)final_picture;

            pkt.size=  sizeof(AVPicture);

            if(dec->coded_frame)

                pkt.pts= dec->coded_frame->pts;

            if(dec->coded_frame && dec->coded_frame->key_frame)

                pkt.flags |= PKT_FLAG_KEY;



            av_write_frame(s, &pkt);

	    enc->coded_frame = old_frame;

        } else {

            AVFrame big_picture;



            big_picture= *final_picture;

            /* better than nothing: use input picture interlaced

               settings */

            big_picture.interlaced_frame = in_picture->interlaced_frame;

            if(do_interlace_me || do_interlace_dct){

                if(top_field_first == -1)

                    big_picture.top_field_first = in_picture->top_field_first;

                else

                    big_picture.top_field_first = 1;

            }



            /* handles sameq here. This is not correct because it may

               not be a global option */

            if (same_quality) {

                big_picture.quality = ist->st->quality;

            }else

                big_picture.quality = ost->st->quality;

            if(!me_threshold)

                big_picture.pict_type = 0;

            big_picture.pts = AV_NOPTS_VALUE; //FIXME

            ret = avcodec_encode_video(enc, 

                                       video_buffer, VIDEO_BUFFER_SIZE,

                                       &big_picture);

            //enc->frame_number = enc->real_pict_num;

            if(ret){

                pkt.data= video_buffer;

                pkt.size= ret;

                if(enc->coded_frame)

                    pkt.pts= enc->coded_frame->pts;

                if(enc->coded_frame && enc->coded_frame->key_frame)

                    pkt.flags |= PKT_FLAG_KEY;

                av_write_frame(s, &pkt);

                *frame_size = ret;

                //fprintf(stderr,"\nFrame: %3d %3d size: %5d type: %d",

                //        enc->frame_number-1, enc->real_pict_num, ret,

                //        enc->pict_type);

                /* if two pass, output log */

                if (ost->logfile && enc->stats_out) {

                    fprintf(ost->logfile, "%s", enc->stats_out);

                }

            }

        }

        ost->frame_number++;

    }

 the_end:

    av_free(buf);

    av_free(buf1);

}

static void av_always_inline filter_mb_edgecv( uint8_t *pix, int stride, const int16_t bS[4], unsigned int qp, H264Context *h ) {

    const int qp_bd_offset = 6 * (h->sps.bit_depth_luma - 8);

    const unsigned int index_a = qp - qp_bd_offset + h->slice_alpha_c0_offset;

    const int alpha = alpha_table[index_a];

    const int beta  = beta_table[qp - qp_bd_offset + h->slice_beta_offset];

    if (alpha ==0 || beta == 0) return;



    if( bS[0] < 4 ) {

        int8_t tc[4];

        tc[0] = tc0_table[index_a][bS[0]]+1;

        tc[1] = tc0_table[index_a][bS[1]]+1;

        tc[2] = tc0_table[index_a][bS[2]]+1;

        tc[3] = tc0_table[index_a][bS[3]]+1;

        h->h264dsp.h264_h_loop_filter_chroma(pix, stride, alpha, beta, tc);

    } else {

        h->h264dsp.h264_h_loop_filter_chroma_intra(pix, stride, alpha, beta);

    }

}

int ff_h263_decode_frame(AVCodecContext *avctx,

                             void *data, int *data_size,

                             AVPacket *avpkt)

{

    const uint8_t *buf = avpkt->data;

    int buf_size = avpkt->size;

    MpegEncContext *s = avctx->priv_data;

    int ret;

    AVFrame *pict = data;



#ifdef PRINT_FRAME_TIME

uint64_t time= rdtsc();

#endif

#ifdef DEBUG

    av_log(avctx, AV_LOG_DEBUG, "*****frame %d size=%d\n", avctx->frame_number, buf_size);

    if(buf_size>0)

        av_log(avctx, AV_LOG_DEBUG, "bytes=%x %x %x %x\n", buf[0], buf[1], buf[2], buf[3]);

#endif

    s->flags= avctx->flags;

    s->flags2= avctx->flags2;



    /* no supplementary picture */

    if (buf_size == 0) {

        /* special case for last picture */

        if (s->low_delay==0 && s->next_picture_ptr) {

            *pict= *(AVFrame*)s->next_picture_ptr;

            s->next_picture_ptr= NULL;



            *data_size = sizeof(AVFrame);

        }



        return 0;

    }



    if(s->flags&CODEC_FLAG_TRUNCATED){

        int next;



        if(CONFIG_MPEG4_DECODER && s->codec_id==CODEC_ID_MPEG4){

            next= ff_mpeg4_find_frame_end(&s->parse_context, buf, buf_size);

        }else if(CONFIG_H263_DECODER && s->codec_id==CODEC_ID_H263){

            next= ff_h263_find_frame_end(&s->parse_context, buf, buf_size);

        }else{

            av_log(s->avctx, AV_LOG_ERROR, "this codec does not support truncated bitstreams\n");

            return -1;

        }



        if( ff_combine_frame(&s->parse_context, next, (const uint8_t **)&buf, &buf_size) < 0 )

            return buf_size;

    }





retry:



    if(s->bitstream_buffer_size && (s->divx_packed || buf_size<20)){ //divx 5.01+/xvid frame reorder

        init_get_bits(&s->gb, s->bitstream_buffer, s->bitstream_buffer_size*8);

    }else

        init_get_bits(&s->gb, buf, buf_size*8);

    s->bitstream_buffer_size=0;



    if (!s->context_initialized) {

        if (MPV_common_init(s) < 0) //we need the idct permutaton for reading a custom matrix

            return -1;

    }



    /* We need to set current_picture_ptr before reading the header,

     * otherwise we cannot store anyting in there */

    if(s->current_picture_ptr==NULL || s->current_picture_ptr->data[0]){

        int i= ff_find_unused_picture(s, 0);

        s->current_picture_ptr= &s->picture[i];

    }



    /* let's go :-) */

    if (CONFIG_WMV2_DECODER && s->msmpeg4_version==5) {

        ret= ff_wmv2_decode_picture_header(s);

    } else if (CONFIG_MSMPEG4_DECODER && s->msmpeg4_version) {

        ret = msmpeg4_decode_picture_header(s);

    } else if (s->h263_pred) {

        if(s->avctx->extradata_size && s->picture_number==0){

            GetBitContext gb;



            init_get_bits(&gb, s->avctx->extradata, s->avctx->extradata_size*8);

            ret = ff_mpeg4_decode_picture_header(s, &gb);

        }

        ret = ff_mpeg4_decode_picture_header(s, &s->gb);

    } else if (s->codec_id == CODEC_ID_H263I) {

        ret = intel_h263_decode_picture_header(s);

    } else if (s->h263_flv) {

        ret = flv_h263_decode_picture_header(s);

    } else {

        ret = h263_decode_picture_header(s);

    }



    if(ret==FRAME_SKIPPED) return get_consumed_bytes(s, buf_size);



    /* skip if the header was thrashed */

    if (ret < 0){

        av_log(s->avctx, AV_LOG_ERROR, "header damaged\n");

        return -1;

    }



    avctx->has_b_frames= !s->low_delay;



