            Jpeg2000Component *comp     = tile->comp + compno;

            Jpeg2000CodingStyle *codsty = tile->codsty + compno;

            Jpeg2000QuantStyle *qntsty  = tile->qntsty + compno;



            for (reslevelno = RSpoc; reslevelno < FFMIN(codsty->nreslevels, REpoc); reslevelno++) {

                uint8_t reducedresno = codsty->nreslevels - 1 -reslevelno; //  ==> N_L - r

                Jpeg2000ResLevel *rlevel = comp->reslevel + reslevelno;

                step_x = FFMIN(step_x, rlevel->log2_prec_width  + reducedresno);

                step_y = FFMIN(step_y, rlevel->log2_prec_height + reducedresno);

            }

        }

        step_x = 1<<step_x;

        step_y = 1<<step_y;



        for (y = tile->coord[1][0]; y < tile->coord[1][1]; y = (y/step_y + 1)*step_y) {

            for (x = tile->coord[0][0]; x < tile->coord[0][1]; x = (x/step_x + 1)*step_x) {

                for (compno = CSpoc; compno < CEpoc; compno++) {

                    Jpeg2000Component *comp     = tile->comp + compno;

                    Jpeg2000CodingStyle *codsty = tile->codsty + compno;

                    Jpeg2000QuantStyle *qntsty  = tile->qntsty + compno;

                    int xc = x / s->cdx[compno];

                    int yc = y / s->cdy[compno];



                    for (reslevelno = RSpoc; reslevelno < FFMIN(codsty->nreslevels, REpoc); reslevelno++) {

                        unsigned prcx, prcy;

                        uint8_t reducedresno = codsty->nreslevels - 1 -reslevelno; //  ==> N_L - r

                        Jpeg2000ResLevel *rlevel = comp->reslevel + reslevelno;



                        if (yc % (1 << (rlevel->log2_prec_height + reducedresno)) && y != tile->coord[1][0]) //FIXME this is a subset of the check

                            continue;



                        if (xc % (1 << (rlevel->log2_prec_width + reducedresno)) && x != tile->coord[0][0]) //FIXME this is a subset of the check

                            continue;



                        // check if a precinct exists

                        prcx   = ff_jpeg2000_ceildivpow2(xc, reducedresno) >> rlevel->log2_prec_width;

                        prcy   = ff_jpeg2000_ceildivpow2(yc, reducedresno) >> rlevel->log2_prec_height;

                        prcx  -= ff_jpeg2000_ceildivpow2(comp->coord_o[0][0], reducedresno) >> rlevel->log2_prec_width;

                        prcy  -= ff_jpeg2000_ceildivpow2(comp->coord_o[1][0], reducedresno) >> rlevel->log2_prec_height;



                        precno = prcx + rlevel->num_precincts_x * prcy;



                        if (prcx >= rlevel->num_precincts_x || prcy >= rlevel->num_precincts_y) {

                            av_log(s->avctx, AV_LOG_WARNING, "prc %d %d outside limits %d %d\n",

                                   prcx, prcy, rlevel->num_precincts_x, rlevel->num_precincts_y);

                            continue;

                        }



                        for (layno = 0; layno < LYEpoc; layno++) {

                            if ((ret = jpeg2000_decode_packet(s, tile, &tp_index, codsty, rlevel,

                                                              precno, layno,

                                                              qntsty->expn + (reslevelno ? 3 * (reslevelno - 1) + 1 : 0),

                                                              qntsty->nguardbits)) < 0)

                                return ret;

                        }

                    }

                }

            }

        }

        break;



    default:

        break;

    }



    return ret;

}

static av_cold int vmdaudio_decode_init(AVCodecContext *avctx)

{

    VmdAudioContext *s = avctx->priv_data;



    if (avctx->channels < 1 || avctx->channels > 2) {

        av_log(avctx, AV_LOG_ERROR, "invalid number of channels\n");

        return AVERROR(EINVAL);

    }

    if (avctx->block_align < 1) {

        av_log(avctx, AV_LOG_ERROR, "invalid block align\n");

        return AVERROR(EINVAL);

    }



    avctx->channel_layout = avctx->channels == 1 ? AV_CH_LAYOUT_MONO :

                                                   AV_CH_LAYOUT_STEREO;



    if (avctx->bits_per_coded_sample == 16)

        avctx->sample_fmt = AV_SAMPLE_FMT_S16;

    else

        avctx->sample_fmt = AV_SAMPLE_FMT_U8;

    s->out_bps = av_get_bytes_per_sample(avctx->sample_fmt);



    s->chunk_size = avctx->block_align + avctx->channels * (s->out_bps == 2);



    avcodec_get_frame_defaults(&s->frame);

    avctx->coded_frame = &s->frame;



    av_log(avctx, AV_LOG_DEBUG, "%d channels, %d bits/sample, "

           "block align = %d, sample rate = %d\n",

           avctx->channels, avctx->bits_per_coded_sample, avctx->block_align,

           avctx->sample_rate);



    return 0;

}

static int sunrast_decode_frame(AVCodecContext *avctx, void *data,

                                int *got_frame, AVPacket *avpkt)

{

    const uint8_t *buf       = avpkt->data;

    const uint8_t *buf_end   = avpkt->data + avpkt->size;

    AVFrame * const p        = data;

    unsigned int w, h, depth, type, maptype, maplength, stride, x, y, len, alen;

    uint8_t *ptr, *ptr2 = NULL;

    const uint8_t *bufstart = buf;

    int ret;



    if (avpkt->size < 32)

        return AVERROR_INVALIDDATA;



    if (AV_RB32(buf) != RAS_MAGIC) {

        av_log(avctx, AV_LOG_ERROR, "this is not sunras encoded data\n");

        return AVERROR_INVALIDDATA;

    }



    w         = AV_RB32(buf + 4);

    h         = AV_RB32(buf + 8);

    depth     = AV_RB32(buf + 12);

    type      = AV_RB32(buf + 20);

    maptype   = AV_RB32(buf + 24);

    maplength = AV_RB32(buf + 28);

    buf      += 32;



    if (type == RT_EXPERIMENTAL) {

        avpriv_request_sample(avctx, "TIFF/IFF/EXPERIMENTAL (compression) type");

        return AVERROR_PATCHWELCOME;

    }

    if (type > RT_FORMAT_IFF) {

        av_log(avctx, AV_LOG_ERROR, "invalid (compression) type\n");

        return AVERROR_INVALIDDATA;

    }

    if (maptype == RMT_RAW) {

        avpriv_request_sample(avctx, "Unknown colormap type");

        return AVERROR_PATCHWELCOME;

    }

    if (maptype > RMT_RAW) {

        av_log(avctx, AV_LOG_ERROR, "invalid colormap type\n");

        return AVERROR_INVALIDDATA;

    }



    if (type == RT_FORMAT_TIFF || type == RT_FORMAT_IFF) {

        av_log(avctx, AV_LOG_ERROR, "unsupported (compression) type\n");

        return -1;

    }



    switch (depth) {

        case 1:

            avctx->pix_fmt = maplength ? AV_PIX_FMT_PAL8 : AV_PIX_FMT_MONOWHITE;

            break;

        case 4:

            avctx->pix_fmt = maplength ? AV_PIX_FMT_PAL8 : AV_PIX_FMT_NONE;

            break;

        case 8:

            avctx->pix_fmt = maplength ? AV_PIX_FMT_PAL8 : AV_PIX_FMT_GRAY8;

            break;

        case 24:

            avctx->pix_fmt = (type == RT_FORMAT_RGB) ? AV_PIX_FMT_RGB24 : AV_PIX_FMT_BGR24;

            break;

        case 32:

            avctx->pix_fmt = (type == RT_FORMAT_RGB) ? AV_PIX_FMT_0RGB : AV_PIX_FMT_0BGR;

            break;

        default:

            av_log(avctx, AV_LOG_ERROR, "invalid depth\n");

            return AVERROR_INVALIDDATA;

    }



    ret = ff_set_dimensions(avctx, w, h);

    if (ret < 0)

        return ret;



    if ((ret = ff_get_buffer(avctx, p, 0)) < 0)

        return ret;



    p->pict_type = AV_PICTURE_TYPE_I;



    if (buf_end - buf < maplength)

        return AVERROR_INVALIDDATA;



    if (depth > 8 && maplength) {

        av_log(avctx, AV_LOG_WARNING, "useless colormap found or file is corrupted, trying to recover\n");



    } else if (maplength) {

        unsigned int len = maplength / 3;



        if (maplength % 3 || maplength > 768) {

            av_log(avctx, AV_LOG_WARNING, "invalid colormap length\n");

            return AVERROR_INVALIDDATA;

        }



        ptr = p->data[1];

        for (x = 0; x < len; x++, ptr += 4)

            *(uint32_t *)ptr = (0xFFU<<24) + (buf[x]<<16) + (buf[len+x]<<8) + buf[len+len+x];

    }



    buf += maplength;



    if (maplength && depth < 8) {

        ptr = ptr2 = av_malloc_array((w + 15), h);

        if (!ptr)

            return AVERROR(ENOMEM);

        stride = (w + 15 >> 3) * depth;

    } else {

    ptr    = p->data[0];

    stride = p->linesize[0];

    }



    /* scanlines are aligned on 16 bit boundaries */

    len  = (depth * w + 7) >> 3;

    alen = len + (len & 1);



    if (type == RT_BYTE_ENCODED) {

        int value, run;

        uint8_t *end = ptr + h * stride;



        x = 0;

        while (ptr != end && buf < buf_end) {

            run = 1;

            if (buf_end - buf < 1)

                return AVERROR_INVALIDDATA;



            if ((value = *buf++) == RLE_TRIGGER) {

                run = *buf++ + 1;

                if (run != 1)

                    value = *buf++;

            }

            while (run--) {

                if (x < len)

                    ptr[x] = value;

                if (++x >= alen) {

                    x = 0;

                    ptr += stride;

                    if (ptr == end)

                        break;

                }

            }

        }

    } else {

        for (y = 0; y < h; y++) {

            if (buf_end - buf < len)

                break;

            memcpy(ptr, buf, len);

            ptr += stride;

            buf += alen;

        }

    }

    if (avctx->pix_fmt == AV_PIX_FMT_PAL8 && depth < 8) {

        uint8_t *ptr_free = ptr2;

        ptr = p->data[0];

        for (y=0; y<h; y++) {

            for (x = 0; x < (w + 7 >> 3) * depth; x++) {

                if (depth == 1) {

                    ptr[8*x]   = ptr2[x] >> 7;

                    ptr[8*x+1] = ptr2[x] >> 6 & 1;

                    ptr[8*x+2] = ptr2[x] >> 5 & 1;

                    ptr[8*x+3] = ptr2[x] >> 4 & 1;

                    ptr[8*x+4] = ptr2[x] >> 3 & 1;

                    ptr[8*x+5] = ptr2[x] >> 2 & 1;

                    ptr[8*x+6] = ptr2[x] >> 1 & 1;

                    ptr[8*x+7] = ptr2[x]      & 1;

                } else {

                    ptr[2*x]   = ptr2[x] >> 4;

                    ptr[2*x+1] = ptr2[x] & 0xF;

                }

            }

            ptr  += p->linesize[0];

            ptr2 += (w + 15 >> 3) * depth;

        }

        av_freep(&ptr_free);

    }



    *got_frame = 1;



    return buf - bufstart;

}

static int xan_decode_frame(AVCodecContext *avctx,

                            void *data, int *data_size,

                            AVPacket *avpkt)

{

    const uint8_t *buf = avpkt->data;

    int ret, buf_size = avpkt->size;

    XanContext *s = avctx->priv_data;



    if (avctx->codec->id == CODEC_ID_XAN_WC3) {

        const uint8_t *buf_end = buf + buf_size;

        int tag = 0;

        while (buf_end - buf > 8 && tag != VGA__TAG) {

            unsigned *tmpptr;

            uint32_t new_pal;

            int size;

            int i;

            tag  = bytestream_get_le32(&buf);

            size = bytestream_get_be32(&buf);

            size = FFMIN(size, buf_end - buf);

            switch (tag) {

            case PALT_TAG:

                if (size < PALETTE_SIZE)

                    return AVERROR_INVALIDDATA;

                if (s->palettes_count >= PALETTES_MAX)

                    return AVERROR_INVALIDDATA;

                tmpptr = av_realloc(s->palettes, (s->palettes_count + 1) * AVPALETTE_SIZE);

                if (!tmpptr)

                    return AVERROR(ENOMEM);

                s->palettes = tmpptr;

                tmpptr += s->palettes_count * AVPALETTE_COUNT;

                for (i = 0; i < PALETTE_COUNT; i++) {

#if RUNTIME_GAMMA

                    int r = gamma_corr(*buf++);

                    int g = gamma_corr(*buf++);

                    int b = gamma_corr(*buf++);

#else

                    int r = gamma_lookup[*buf++];

                    int g = gamma_lookup[*buf++];

                    int b = gamma_lookup[*buf++];

#endif

                    *tmpptr++ = (r << 16) | (g << 8) | b;

                }

                s->palettes_count++;

                break;

            case SHOT_TAG:

                if (size < 4)

                    return AVERROR_INVALIDDATA;

                new_pal = bytestream_get_le32(&buf);

                if (new_pal < s->palettes_count) {

                    s->cur_palette = new_pal;

                } else

                    av_log(avctx, AV_LOG_ERROR, "Invalid palette selected\n");

                break;

            case VGA__TAG:

                break;

            default:

                buf += size;

                break;

            }

        }

        buf_size = buf_end - buf;

    }

    if ((ret = avctx->get_buffer(avctx, &s->current_frame))) {

        av_log(s->avctx, AV_LOG_ERROR, "get_buffer() failed\n");

        return ret;

    }

    s->current_frame.reference = 3;



    if (!s->frame_size)

        s->frame_size = s->current_frame.linesize[0] * s->avctx->height;



    memcpy(s->current_frame.data[1], s->palettes + s->cur_palette * AVPALETTE_COUNT, AVPALETTE_SIZE);



    s->buf = buf;

    s->size = buf_size;



    xan_wc3_decode_frame(s);



    /* release the last frame if it is allocated */

    if (s->last_frame.data[0])

        avctx->release_buffer(avctx, &s->last_frame);



    *data_size = sizeof(AVFrame);

    *(AVFrame*)data = s->current_frame;



    /* shuffle frames */

    FFSWAP(AVFrame, s->current_frame, s->last_frame);



    /* always report that the buffer was completely consumed */

    return buf_size;

}

av_cold int MPV_encode_init(AVCodecContext *avctx)

{

    MpegEncContext *s = avctx->priv_data;

    int i;

    int chroma_h_shift, chroma_v_shift;



    MPV_encode_defaults(s);



    switch (avctx->codec_id) {

    case CODEC_ID_MPEG2VIDEO:

        if(avctx->pix_fmt != PIX_FMT_YUV420P && avctx->pix_fmt != PIX_FMT_YUV422P){

            av_log(avctx, AV_LOG_ERROR, "only YUV420 and YUV422 are supported\n");

            return -1;

        }

        break;

    case CODEC_ID_LJPEG:

    case CODEC_ID_MJPEG:

        if(avctx->pix_fmt != PIX_FMT_YUVJ420P && avctx->pix_fmt != PIX_FMT_YUVJ422P && avctx->pix_fmt != PIX_FMT_RGB32 &&

           ((avctx->pix_fmt != PIX_FMT_YUV420P && avctx->pix_fmt != PIX_FMT_YUV422P) || avctx->strict_std_compliance>FF_COMPLIANCE_INOFFICIAL)){

            av_log(avctx, AV_LOG_ERROR, "colorspace not supported in jpeg\n");

            return -1;

        }

        break;

    default:

        if(avctx->pix_fmt != PIX_FMT_YUV420P){

            av_log(avctx, AV_LOG_ERROR, "only YUV420 is supported\n");

            return -1;

        }

    }



    switch (avctx->pix_fmt) {

    case PIX_FMT_YUVJ422P:

    case PIX_FMT_YUV422P:

        s->chroma_format = CHROMA_422;

        break;

    case PIX_FMT_YUVJ420P:

    case PIX_FMT_YUV420P:

    default:

        s->chroma_format = CHROMA_420;

        break;

    }



    s->bit_rate = avctx->bit_rate;

    s->width = avctx->width;

    s->height = avctx->height;

    if(avctx->gop_size > 600 && avctx->strict_std_compliance>FF_COMPLIANCE_EXPERIMENTAL){

        av_log(avctx, AV_LOG_ERROR, "Warning keyframe interval too large! reducing it ...\n");

        avctx->gop_size=600;

    }

    s->gop_size = avctx->gop_size;

    s->avctx = avctx;

    s->flags= avctx->flags;

    s->flags2= avctx->flags2;

    s->max_b_frames= avctx->max_b_frames;

    s->codec_id= avctx->codec->id;

    s->luma_elim_threshold  = avctx->luma_elim_threshold;

    s->chroma_elim_threshold= avctx->chroma_elim_threshold;

    s->strict_std_compliance= avctx->strict_std_compliance;

    s->data_partitioning= avctx->flags & CODEC_FLAG_PART;

    s->quarter_sample= (avctx->flags & CODEC_FLAG_QPEL)!=0;

    s->mpeg_quant= avctx->mpeg_quant;

    s->rtp_mode= !!avctx->rtp_payload_size;

    s->intra_dc_precision= avctx->intra_dc_precision;

    s->user_specified_pts = AV_NOPTS_VALUE;



    if (s->gop_size <= 1) {

        s->intra_only = 1;

        s->gop_size = 12;

    } else {

        s->intra_only = 0;

    }



    s->me_method = avctx->me_method;



    /* Fixed QSCALE */

    s->fixed_qscale = !!(avctx->flags & CODEC_FLAG_QSCALE);



    s->adaptive_quant= (   s->avctx->lumi_masking

                        || s->avctx->dark_masking

                        || s->avctx->temporal_cplx_masking

                        || s->avctx->spatial_cplx_masking

                        || s->avctx->p_masking

                        || s->avctx->border_masking

                        || (s->flags&CODEC_FLAG_QP_RD))

                       && !s->fixed_qscale;



    s->obmc= !!(s->flags & CODEC_FLAG_OBMC);

    s->loop_filter= !!(s->flags & CODEC_FLAG_LOOP_FILTER);

    s->alternate_scan= !!(s->flags & CODEC_FLAG_ALT_SCAN);

    s->intra_vlc_format= !!(s->flags2 & CODEC_FLAG2_INTRA_VLC);

    s->q_scale_type= !!(s->flags2 & CODEC_FLAG2_NON_LINEAR_QUANT);



    if(avctx->rc_max_rate && !avctx->rc_buffer_size){

        av_log(avctx, AV_LOG_ERROR, "a vbv buffer size is needed, for encoding with a maximum bitrate\n");

        return -1;

    }



    if(avctx->rc_min_rate && avctx->rc_max_rate != avctx->rc_min_rate){

        av_log(avctx, AV_LOG_INFO, "Warning min_rate > 0 but min_rate != max_rate isn't recommended!\n");

    }



    if(avctx->rc_min_rate && avctx->rc_min_rate > avctx->bit_rate){

        av_log(avctx, AV_LOG_ERROR, "bitrate below min bitrate\n");

        return -1;

    }



    if(avctx->rc_max_rate && avctx->rc_max_rate < avctx->bit_rate){

        av_log(avctx, AV_LOG_INFO, "bitrate above max bitrate\n");

        return -1;

    }



    if(avctx->rc_max_rate && avctx->rc_max_rate == avctx->bit_rate && avctx->rc_max_rate != avctx->rc_min_rate){

        av_log(avctx, AV_LOG_INFO, "impossible bitrate constraints, this will fail\n");

    }



    if(avctx->rc_buffer_size && avctx->bit_rate*av_q2d(avctx->time_base) > avctx->rc_buffer_size){

        av_log(avctx, AV_LOG_ERROR, "VBV buffer too small for bitrate\n");

        return -1;

    }



    if(avctx->bit_rate*av_q2d(avctx->time_base) > avctx->bit_rate_tolerance){

        av_log(avctx, AV_LOG_ERROR, "bitrate tolerance too small for bitrate\n");

        return -1;

    }



    if(   s->avctx->rc_max_rate && s->avctx->rc_min_rate == s->avctx->rc_max_rate

       && (s->codec_id == CODEC_ID_MPEG1VIDEO || s->codec_id == CODEC_ID_MPEG2VIDEO)

       && 90000LL * (avctx->rc_buffer_size-1) > s->avctx->rc_max_rate*0xFFFFLL){



        av_log(avctx, AV_LOG_INFO, "Warning vbv_delay will be set to 0xFFFF (=VBR) as the specified vbv buffer is too large for the given bitrate!\n");

    }



    if((s->flags & CODEC_FLAG_4MV) && s->codec_id != CODEC_ID_MPEG4

       && s->codec_id != CODEC_ID_H263 && s->codec_id != CODEC_ID_H263P && s->codec_id != CODEC_ID_FLV1){

        av_log(avctx, AV_LOG_ERROR, "4MV not supported by codec\n");

        return -1;

    }



    if(s->obmc && s->avctx->mb_decision != FF_MB_DECISION_SIMPLE){

        av_log(avctx, AV_LOG_ERROR, "OBMC is only supported with simple mb decision\n");

        return -1;

    }



    if(s->obmc && s->codec_id != CODEC_ID_H263 && s->codec_id != CODEC_ID_H263P){

        av_log(avctx, AV_LOG_ERROR, "OBMC is only supported with H263(+)\n");

        return -1;

    }



    if(s->quarter_sample && s->codec_id != CODEC_ID_MPEG4){

        av_log(avctx, AV_LOG_ERROR, "qpel not supported by codec\n");

        return -1;

    }



    if(s->data_partitioning && s->codec_id != CODEC_ID_MPEG4){

        av_log(avctx, AV_LOG_ERROR, "data partitioning not supported by codec\n");

        return -1;

    }



    if(s->max_b_frames && s->codec_id != CODEC_ID_MPEG4 && s->codec_id != CODEC_ID_MPEG1VIDEO && s->codec_id != CODEC_ID_MPEG2VIDEO){

        av_log(avctx, AV_LOG_ERROR, "b frames not supported by codec\n");

        return -1;

    }



    if((s->flags & (CODEC_FLAG_INTERLACED_DCT|CODEC_FLAG_INTERLACED_ME|CODEC_FLAG_ALT_SCAN))

       && s->codec_id != CODEC_ID_MPEG4 && s->codec_id != CODEC_ID_MPEG2VIDEO){

        av_log(avctx, AV_LOG_ERROR, "interlacing not supported by codec\n");

        return -1;

    }



    if(s->mpeg_quant && s->codec_id != CODEC_ID_MPEG4){ //FIXME mpeg2 uses that too

        av_log(avctx, AV_LOG_ERROR, "mpeg2 style quantization not supported by codec\n");

        return -1;

    }



    if((s->flags & CODEC_FLAG_CBP_RD) && !avctx->trellis){

        av_log(avctx, AV_LOG_ERROR, "CBP RD needs trellis quant\n");

        return -1;

    }



    if((s->flags & CODEC_FLAG_QP_RD) && s->avctx->mb_decision != FF_MB_DECISION_RD){

        av_log(avctx, AV_LOG_ERROR, "QP RD needs mbd=2\n");

        return -1;

    }



    if(s->avctx->scenechange_threshold < 1000000000 && (s->flags & CODEC_FLAG_CLOSED_GOP)){

        av_log(avctx, AV_LOG_ERROR, "closed gop with scene change detection are not supported yet, set threshold to 1000000000\n");

        return -1;

    }



    if((s->flags2 & CODEC_FLAG2_INTRA_VLC) && s->codec_id != CODEC_ID_MPEG2VIDEO){

        av_log(avctx, AV_LOG_ERROR, "intra vlc table not supported by codec\n");

        return -1;

    }



    if(s->flags & CODEC_FLAG_LOW_DELAY){

        if (s->codec_id != CODEC_ID_MPEG2VIDEO){

            av_log(avctx, AV_LOG_ERROR, "low delay forcing is only available for mpeg2\n");

            return -1;

        }

        if (s->max_b_frames != 0){

            av_log(avctx, AV_LOG_ERROR, "b frames cannot be used with low delay\n");

            return -1;

        }

    }



    if(s->q_scale_type == 1){

        if(s->codec_id != CODEC_ID_MPEG2VIDEO){

            av_log(avctx, AV_LOG_ERROR, "non linear quant is only available for mpeg2\n");

            return -1;

        }

        if(avctx->qmax > 12){

            av_log(avctx, AV_LOG_ERROR, "non linear quant only supports qmax <= 12 currently\n");

            return -1;

        }

    }



    if(s->avctx->thread_count > 1 && s->codec_id != CODEC_ID_MPEG4

       && s->codec_id != CODEC_ID_MPEG1VIDEO && s->codec_id != CODEC_ID_MPEG2VIDEO

       && (s->codec_id != CODEC_ID_H263P || !(s->flags & CODEC_FLAG_H263P_SLICE_STRUCT))){

        av_log(avctx, AV_LOG_ERROR, "multi threaded encoding not supported by codec\n");

        return -1;

    }



    if(s->avctx->thread_count < 1){

        av_log(avctx, AV_LOG_ERROR, "automatic thread number detection not supported by codec, patch welcome\n");

        return -1;

    }



    if(s->avctx->thread_count > 1)

        s->rtp_mode= 1;



    if(!avctx->time_base.den || !avctx->time_base.num){

        av_log(avctx, AV_LOG_ERROR, "framerate not set\n");

        return -1;

    }



    i= (INT_MAX/2+128)>>8;

    if(avctx->me_threshold >= i){

        av_log(avctx, AV_LOG_ERROR, "me_threshold too large, max is %d\n", i - 1);

        return -1;

    }

    if(avctx->mb_threshold >= i){

        av_log(avctx, AV_LOG_ERROR, "mb_threshold too large, max is %d\n", i - 1);

        return -1;

    }



    if(avctx->b_frame_strategy && (avctx->flags&CODEC_FLAG_PASS2)){

        av_log(avctx, AV_LOG_INFO, "notice: b_frame_strategy only affects the first pass\n");

        avctx->b_frame_strategy = 0;

    }



    i= av_gcd(avctx->time_base.den, avctx->time_base.num);

    if(i > 1){

        av_log(avctx, AV_LOG_INFO, "removing common factors from framerate\n");

        avctx->time_base.den /= i;

        avctx->time_base.num /= i;

//        return -1;

    }



    if(s->codec_id==CODEC_ID_MJPEG){

        s->intra_quant_bias= 1<<(QUANT_BIAS_SHIFT-1); //(a + x/2)/x

        s->inter_quant_bias= 0;

    }else if(s->mpeg_quant || s->codec_id==CODEC_ID_MPEG1VIDEO || s->codec_id==CODEC_ID_MPEG2VIDEO){

        s->intra_quant_bias= 3<<(QUANT_BIAS_SHIFT-3); //(a + x*3/8)/x

        s->inter_quant_bias= 0;

    }else{

        s->intra_quant_bias=0;

        s->inter_quant_bias=-(1<<(QUANT_BIAS_SHIFT-2)); //(a - x/4)/x

    }



    if(avctx->intra_quant_bias != FF_DEFAULT_QUANT_BIAS)

        s->intra_quant_bias= avctx->intra_quant_bias;

    if(avctx->inter_quant_bias != FF_DEFAULT_QUANT_BIAS)

        s->inter_quant_bias= avctx->inter_quant_bias;



    avcodec_get_chroma_sub_sample(avctx->pix_fmt, &chroma_h_shift, &chroma_v_shift);



    if(avctx->codec_id == CODEC_ID_MPEG4 && s->avctx->time_base.den > (1<<16)-1){

        av_log(avctx, AV_LOG_ERROR, "timebase not supported by mpeg 4 standard\n");

        return -1;

    }

    s->time_increment_bits = av_log2(s->avctx->time_base.den - 1) + 1;



    switch(avctx->codec->id) {

    case CODEC_ID_MPEG1VIDEO:

        s->out_format = FMT_MPEG1;

        s->low_delay= !!(s->flags & CODEC_FLAG_LOW_DELAY);

        avctx->delay= s->low_delay ? 0 : (s->max_b_frames + 1);

        break;

    case CODEC_ID_MPEG2VIDEO:

        s->out_format = FMT_MPEG1;

        s->low_delay= !!(s->flags & CODEC_FLAG_LOW_DELAY);

        avctx->delay= s->low_delay ? 0 : (s->max_b_frames + 1);

        s->rtp_mode= 1;

        break;

    case CODEC_ID_LJPEG:

    case CODEC_ID_MJPEG:

        s->out_format = FMT_MJPEG;

        s->intra_only = 1; /* force intra only for jpeg */

        if(avctx->codec->id == CODEC_ID_MJPEG || avctx->pix_fmt != PIX_FMT_BGRA){

        s->mjpeg_vsample[0] = 2;

        s->mjpeg_vsample[1] = 2>>chroma_v_shift;

        s->mjpeg_vsample[2] = 2>>chroma_v_shift;

        s->mjpeg_hsample[0] = 2;

        s->mjpeg_hsample[1] = 2>>chroma_h_shift;

        s->mjpeg_hsample[2] = 2>>chroma_h_shift;

        }else{

            s->mjpeg_vsample[0] = s->mjpeg_hsample[0] =

            s->mjpeg_vsample[1] = s->mjpeg_hsample[1] =

            s->mjpeg_vsample[2] = s->mjpeg_hsample[2] = 1;

        }

        if (!(CONFIG_MJPEG_ENCODER || CONFIG_LJPEG_ENCODER)

            || ff_mjpeg_encode_init(s) < 0)

            return -1;

        avctx->delay=0;

        s->low_delay=1;

        break;

    case CODEC_ID_H261:

        if (!CONFIG_H261_ENCODER)  return -1;

        if (ff_h261_get_picture_format(s->width, s->height) < 0) {

            av_log(avctx, AV_LOG_ERROR, "The specified picture size of %dx%d is not valid for the H.261 codec.\nValid sizes are 176x144, 352x288\n", s->width, s->height);

            return -1;

        }

        s->out_format = FMT_H261;

        avctx->delay=0;

        s->low_delay=1;

        break;

    case CODEC_ID_H263:

        if (!CONFIG_H263_ENCODER)  return -1;

        if (h263_get_picture_format(s->width, s->height) == 7) {

            av_log(avctx, AV_LOG_INFO, "The specified picture size of %dx%d is not valid for the H.263 codec.\nValid sizes are 128x96, 176x144, 352x288, 704x576, and 1408x1152. Try H.263+.\n", s->width, s->height);

            return -1;

        }

        s->out_format = FMT_H263;

        s->obmc= (avctx->flags & CODEC_FLAG_OBMC) ? 1:0;

        avctx->delay=0;

        s->low_delay=1;

        break;

    case CODEC_ID_H263P:

        s->out_format = FMT_H263;

        s->h263_plus = 1;

        /* Fx */

        s->umvplus = (avctx->flags & CODEC_FLAG_H263P_UMV) ? 1:0;

        s->h263_aic= (avctx->flags & CODEC_FLAG_AC_PRED) ? 1:0;

        s->modified_quant= s->h263_aic;

        s->alt_inter_vlc= (avctx->flags & CODEC_FLAG_H263P_AIV) ? 1:0;

        s->obmc= (avctx->flags & CODEC_FLAG_OBMC) ? 1:0;

        s->loop_filter= (avctx->flags & CODEC_FLAG_LOOP_FILTER) ? 1:0;

        s->unrestricted_mv= s->obmc || s->loop_filter || s->umvplus;

        s->h263_slice_structured= (s->flags & CODEC_FLAG_H263P_SLICE_STRUCT) ? 1:0;



        /* /Fx */

        /* These are just to be sure */

        avctx->delay=0;

        s->low_delay=1;

        break;

    case CODEC_ID_FLV1:

        s->out_format = FMT_H263;

        s->h263_flv = 2; /* format = 1; 11-bit codes */

        s->unrestricted_mv = 1;

        s->rtp_mode=0; /* don't allow GOB */

        avctx->delay=0;

        s->low_delay=1;

        break;

    case CODEC_ID_RV10:

        s->out_format = FMT_H263;

        avctx->delay=0;

        s->low_delay=1;

        break;

    case CODEC_ID_RV20:

        s->out_format = FMT_H263;

        avctx->delay=0;

        s->low_delay=1;

        s->modified_quant=1;

        s->h263_aic=1;

        s->h263_plus=1;

        s->loop_filter=1;

        s->unrestricted_mv= s->obmc || s->loop_filter || s->umvplus;

        break;

    case CODEC_ID_MPEG4:

        s->out_format = FMT_H263;

        s->h263_pred = 1;

        s->unrestricted_mv = 1;

        s->low_delay= s->max_b_frames ? 0 : 1;

        avctx->delay= s->low_delay ? 0 : (s->max_b_frames + 1);

        break;

    case CODEC_ID_MSMPEG4V1:

        s->out_format = FMT_H263;

        s->h263_msmpeg4 = 1;

        s->h263_pred = 1;

        s->unrestricted_mv = 1;

        s->msmpeg4_version= 1;

        avctx->delay=0;

        s->low_delay=1;

        break;

    case CODEC_ID_MSMPEG4V2:

        s->out_format = FMT_H263;

        s->h263_msmpeg4 = 1;

        s->h263_pred = 1;

        s->unrestricted_mv = 1;

        s->msmpeg4_version= 2;

        avctx->delay=0;

        s->low_delay=1;

        break;

    case CODEC_ID_MSMPEG4V3:

        s->out_format = FMT_H263;

        s->h263_msmpeg4 = 1;

        s->h263_pred = 1;

        s->unrestricted_mv = 1;

        s->msmpeg4_version= 3;

        s->flipflop_rounding=1;

        avctx->delay=0;

        s->low_delay=1;

        break;

    case CODEC_ID_WMV1:

        s->out_format = FMT_H263;

        s->h263_msmpeg4 = 1;

        s->h263_pred = 1;

        s->unrestricted_mv = 1;

        s->msmpeg4_version= 4;

        s->flipflop_rounding=1;

        avctx->delay=0;

        s->low_delay=1;

        break;

    case CODEC_ID_WMV2:

        s->out_format = FMT_H263;

        s->h263_msmpeg4 = 1;

        s->h263_pred = 1;

        s->unrestricted_mv = 1;

        s->msmpeg4_version= 5;

        s->flipflop_rounding=1;

        avctx->delay=0;

        s->low_delay=1;

        break;

    default:

        return -1;

    }



    avctx->has_b_frames= !s->low_delay;



    s->encoding = 1;



    s->progressive_frame=

    s->progressive_sequence= !(avctx->flags & (CODEC_FLAG_INTERLACED_DCT|CODEC_FLAG_INTERLACED_ME|CODEC_FLAG_ALT_SCAN));



    /* init */

    if (MPV_common_init(s) < 0)

        return -1;



    if(!s->dct_quantize)

        s->dct_quantize = dct_quantize_c;

    if(!s->denoise_dct)

        s->denoise_dct = denoise_dct_c;

    s->fast_dct_quantize = s->dct_quantize;

    if(avctx->trellis)

        s->dct_quantize = dct_quantize_trellis_c;



    if((CONFIG_H263P_ENCODER || CONFIG_RV20_ENCODER) && s->modified_quant)

        s->chroma_qscale_table= ff_h263_chroma_qscale_table;



    s->quant_precision=5;



    ff_set_cmp(&s->dsp, s->dsp.ildct_cmp, s->avctx->ildct_cmp);

    ff_set_cmp(&s->dsp, s->dsp.frame_skip_cmp, s->avctx->frame_skip_cmp);



    if (CONFIG_H261_ENCODER && s->out_format == FMT_H261)

        ff_h261_encode_init(s);

    if (CONFIG_ANY_H263_ENCODER && s->out_format == FMT_H263)

        h263_encode_init(s);

    if (CONFIG_MSMPEG4_ENCODER && s->msmpeg4_version)

        ff_msmpeg4_encode_init(s);

    if ((CONFIG_MPEG1VIDEO_ENCODER || CONFIG_MPEG2VIDEO_ENCODER)

        && s->out_format == FMT_MPEG1)

        ff_mpeg1_encode_init(s);



    /* init q matrix */

    for(i=0;i<64;i++) {

        int j= s->dsp.idct_permutation[i];

        if(CONFIG_MPEG4_ENCODER && s->codec_id==CODEC_ID_MPEG4 && s->mpeg_quant){

            s->intra_matrix[j] = ff_mpeg4_default_intra_matrix[i];

            s->inter_matrix[j] = ff_mpeg4_default_non_intra_matrix[i];

        }else if(s->out_format == FMT_H263 || s->out_format == FMT_H261){

            s->intra_matrix[j] =

            s->inter_matrix[j] = ff_mpeg1_default_non_intra_matrix[i];

        }else

        { /* mpeg1/2 */

            s->intra_matrix[j] = ff_mpeg1_default_intra_matrix[i];

            s->inter_matrix[j] = ff_mpeg1_default_non_intra_matrix[i];

        }

        if(s->avctx->intra_matrix)

            s->intra_matrix[j] = s->avctx->intra_matrix[i];

        if(s->avctx->inter_matrix)

            s->inter_matrix[j] = s->avctx->inter_matrix[i];

    }



    /* precompute matrix */

    /* for mjpeg, we do include qscale in the matrix */

    if (s->out_format != FMT_MJPEG) {

        ff_convert_matrix(&s->dsp, s->q_intra_matrix, s->q_intra_matrix16,

                       s->intra_matrix, s->intra_quant_bias, avctx->qmin, 31, 1);

        ff_convert_matrix(&s->dsp, s->q_inter_matrix, s->q_inter_matrix16,

                       s->inter_matrix, s->inter_quant_bias, avctx->qmin, 31, 0);

    }



    if(ff_rate_control_init(s) < 0)

        return -1;



    return 0;

}

static void read_sbr_envelope(SpectralBandReplication *sbr, GetBitContext *gb,

                              SBRData *ch_data, int ch)

{

    int bits;

    int i, j, k;

    VLC_TYPE (*t_huff)[2], (*f_huff)[2];

    int t_lav, f_lav;

    const int delta = (ch == 1 && sbr->bs_coupling == 1) + 1;

    const int odd = sbr->n[1] & 1;



    if (sbr->bs_coupling && ch) {

        if (ch_data->bs_amp_res) {

            bits   = 5;

            t_huff = vlc_sbr[T_HUFFMAN_ENV_BAL_3_0DB].table;

            t_lav  = vlc_sbr_lav[T_HUFFMAN_ENV_BAL_3_0DB];

            f_huff = vlc_sbr[F_HUFFMAN_ENV_BAL_3_0DB].table;

            f_lav  = vlc_sbr_lav[F_HUFFMAN_ENV_BAL_3_0DB];

        } else {

            bits   = 6;

            t_huff = vlc_sbr[T_HUFFMAN_ENV_BAL_1_5DB].table;

            t_lav  = vlc_sbr_lav[T_HUFFMAN_ENV_BAL_1_5DB];

            f_huff = vlc_sbr[F_HUFFMAN_ENV_BAL_1_5DB].table;

            f_lav  = vlc_sbr_lav[F_HUFFMAN_ENV_BAL_1_5DB];

        }

    } else {

        if (ch_data->bs_amp_res) {

            bits   = 6;

            t_huff = vlc_sbr[T_HUFFMAN_ENV_3_0DB].table;

            t_lav  = vlc_sbr_lav[T_HUFFMAN_ENV_3_0DB];

            f_huff = vlc_sbr[F_HUFFMAN_ENV_3_0DB].table;

            f_lav  = vlc_sbr_lav[F_HUFFMAN_ENV_3_0DB];

        } else {

            bits   = 7;

            t_huff = vlc_sbr[T_HUFFMAN_ENV_1_5DB].table;

            t_lav  = vlc_sbr_lav[T_HUFFMAN_ENV_1_5DB];

            f_huff = vlc_sbr[F_HUFFMAN_ENV_1_5DB].table;

            f_lav  = vlc_sbr_lav[F_HUFFMAN_ENV_1_5DB];

        }

    }



    for (i = 0; i < ch_data->bs_num_env; i++) {

        if (ch_data->bs_df_env[i]) {

            // bs_freq_res[0] == bs_freq_res[bs_num_env] from prev frame

            if (ch_data->bs_freq_res[i + 1] == ch_data->bs_freq_res[i]) {

                for (j = 0; j < sbr->n[ch_data->bs_freq_res[i + 1]]; j++)

                    ch_data->env_facs_q[i + 1][j] = ch_data->env_facs_q[i][j] + delta * (get_vlc2(gb, t_huff, 9, 3) - t_lav);

            } else if (ch_data->bs_freq_res[i + 1]) {

                for (j = 0; j < sbr->n[ch_data->bs_freq_res[i + 1]]; j++) {

                    k = (j + odd) >> 1; // find k such that f_tablelow[k] <= f_tablehigh[j] < f_tablelow[k + 1]

                    ch_data->env_facs_q[i + 1][j] = ch_data->env_facs_q[i][k] + delta * (get_vlc2(gb, t_huff, 9, 3) - t_lav);

                }

            } else {

                for (j = 0; j < sbr->n[ch_data->bs_freq_res[i + 1]]; j++) {

                    k = j ? 2*j - odd : 0; // find k such that f_tablehigh[k] == f_tablelow[j]

                    ch_data->env_facs_q[i + 1][j] = ch_data->env_facs_q[i][k] + delta * (get_vlc2(gb, t_huff, 9, 3) - t_lav);

                }

            }

        } else {

            ch_data->env_facs_q[i + 1][0] = delta * get_bits(gb, bits); // bs_env_start_value_balance

            for (j = 1; j < sbr->n[ch_data->bs_freq_res[i + 1]]; j++)

                ch_data->env_facs_q[i + 1][j] = ch_data->env_facs_q[i + 1][j - 1] + delta * (get_vlc2(gb, f_huff, 9, 3) - f_lav);

        }

    }



    //assign 0th elements of env_facs_q from last elements

    memcpy(ch_data->env_facs_q[0], ch_data->env_facs_q[ch_data->bs_num_env],

           sizeof(ch_data->env_facs_q[0]));

}

static int pva_read_packet(AVFormatContext *s, AVPacket *pkt) {

    ByteIOContext *pb = s->pb;

    PVAContext *pvactx = s->priv_data;

    int ret, syncword, streamid, reserved, flags, length, pts_flag;

    int64_t pva_pts = AV_NOPTS_VALUE;



recover:

    syncword = get_be16(pb);

    streamid = get_byte(pb);

    get_byte(pb);               /* counter not used */

    reserved = get_byte(pb);

    flags    = get_byte(pb);

    length   = get_be16(pb);



    pts_flag = flags & 0x10;



    if (syncword != PVA_MAGIC) {

        av_log(s, AV_LOG_ERROR, "invalid syncword\n");

        return AVERROR(EIO);

    }

    if (streamid != PVA_VIDEO_PAYLOAD && streamid != PVA_AUDIO_PAYLOAD) {

        av_log(s, AV_LOG_ERROR, "invalid streamid\n");

        return AVERROR(EIO);

    }

    if (reserved != 0x55) {

        av_log(s, AV_LOG_WARNING, "expected reserved byte to be 0x55\n");

    }

    if (length > PVA_MAX_PAYLOAD_LENGTH) {

        av_log(s, AV_LOG_ERROR, "invalid payload length %u\n", length);

        return AVERROR(EIO);

    }



    if (streamid == PVA_VIDEO_PAYLOAD && pts_flag) {

        pva_pts = get_be32(pb);

        length -= 4;

    } else if (streamid == PVA_AUDIO_PAYLOAD) {

        /* PVA Audio Packets either start with a signaled PES packet or

         * are a continuation of the previous PES packet. New PES packets

         * always start at the beginning of a PVA Packet, never somewhere in

         * the middle. */

        if (!pvactx->continue_pes) {

            int pes_signal, pes_header_data_length, pes_packet_length,

                pes_flags;

            unsigned char pes_header_data[256];



            pes_signal             = get_be24(pb);

            get_byte(pb);

            pes_packet_length      = get_be16(pb);

            pes_flags              = get_be16(pb);

            pes_header_data_length = get_byte(pb);



            if (pes_signal != 1) {

                av_log(s, AV_LOG_WARNING, "expected signaled PES packet, "

                                          "trying to recover\n");

                url_fskip(pb, length - 9);

                goto recover;

            }



            get_buffer(pb, pes_header_data, pes_header_data_length);

            length -= 9 + pes_header_data_length;



            pes_packet_length -= 3 + pes_header_data_length;



            pvactx->continue_pes = pes_packet_length;



            if (pes_flags & 0x80 && (pes_header_data[0] & 0xf0) == 0x20)

                pva_pts = ff_parse_pes_pts(pes_header_data);

        }



        pvactx->continue_pes -= length;



        if (pvactx->continue_pes < 0) {

            av_log(s, AV_LOG_WARNING, "audio data corruption\n");

            pvactx->continue_pes = 0;

        }

    }



    if ((ret = av_get_packet(pb, pkt, length)) <= 0)

        return AVERROR(EIO);



    pkt->stream_index = streamid - 1;

    if (pva_pts != AV_NOPTS_VALUE)

        pkt->pts = pva_pts;



    return ret;

}

