static inline int decode_bytes(const uint8_t *inbuffer, uint8_t *out, int bytes)

{

    static const uint32_t tab[4] = {

        AV_BE2NE32C(0x37c511f2), AV_BE2NE32C(0xf237c511),

        AV_BE2NE32C(0x11f237c5), AV_BE2NE32C(0xc511f237),

    };

    int i, off;

    uint32_t c;

    const uint32_t *buf;

    uint32_t *obuf = (uint32_t *) out;

    /* FIXME: 64 bit platforms would be able to do 64 bits at a time.

     * I'm too lazy though, should be something like

     * for (i = 0; i < bitamount / 64; i++)

     *     (int64_t) out[i] = 0x37c511f237c511f2 ^ av_be2ne64(int64_t) in[i]);

     * Buffer alignment needs to be checked. */



    off = (intptr_t) inbuffer & 3;

    buf = (const uint32_t *) (inbuffer - off);

    c = tab[off];

    bytes += 3 + off;

    for (i = 0; i < bytes / 4; i++)

        obuf[i] = c ^ buf[i];



    return off;

}

static inline void rv40_weak_loop_filter(uint8_t *src, const int step,

                                         const int filter_p1, const int filter_q1,

                                         const int alpha, const int beta,

                                         const int lim_p0q0,

                                         const int lim_q1, const int lim_p1,

                                         const int diff_p1p0, const int diff_q1q0,

                                         const int diff_p1p2, const int diff_q1q2)

{

    uint8_t *cm = ff_cropTbl + MAX_NEG_CROP;

    int t, u, diff;



    t = src[0*step] - src[-1*step];

    if(!t)

        return;

    u = (alpha * FFABS(t)) >> 7;

    if(u > 3 - (filter_p1 && filter_q1))

        return;



    t <<= 2;

    if(filter_p1 && filter_q1)

        t += src[-2*step] - src[1*step];

    diff = CLIP_SYMM((t + 4) >> 3, lim_p0q0);

    src[-1*step] = cm[src[-1*step] + diff];

    src[ 0*step] = cm[src[ 0*step] - diff];

    if(FFABS(diff_p1p2) <= beta && filter_p1){

        t = (diff_p1p0 + diff_p1p2 - diff) >> 1;

        src[-2*step] = cm[src[-2*step] - CLIP_SYMM(t, lim_p1)];

    }

    if(FFABS(diff_q1q2) <= beta && filter_q1){

        t = (diff_q1q0 + diff_q1q2 + diff) >> 1;

        src[ 1*step] = cm[src[ 1*step] - CLIP_SYMM(t, lim_q1)];

    }

}

static int fileTest(uint8_t *ref[4], int refStride[4], int w, int h, FILE *fp,

                    enum AVPixelFormat srcFormat_in,

                    enum AVPixelFormat dstFormat_in)

{

    char buf[256];



    while (fgets(buf, sizeof(buf), fp)) {

        struct Results r;

        enum AVPixelFormat srcFormat;

        char srcStr[12];

        int srcW, srcH;

        enum AVPixelFormat dstFormat;

        char dstStr[12];

        int dstW, dstH;

        int flags;

        int ret;



        ret = sscanf(buf,

                     " %12s %dx%d -> %12s %dx%d flags=%d CRC=%x"

                     " SSD=%"PRId64 ", %"PRId64 ", %"PRId64 ", %"PRId64 "\n",

                     srcStr, &srcW, &srcH, dstStr, &dstW, &dstH,

                     &flags, &r.crc, &r.ssdY, &r.ssdU, &r.ssdV, &r.ssdA);

        if (ret != 12) {

            srcStr[0] = dstStr[0] = 0;

            ret       = sscanf(buf, "%12s -> %12s\n", srcStr, dstStr);

        }



        srcFormat = av_get_pix_fmt(srcStr);

        dstFormat = av_get_pix_fmt(dstStr);



        if (srcFormat == AV_PIX_FMT_NONE || dstFormat == AV_PIX_FMT_NONE) {

            fprintf(stderr, "malformed input file\n");

            return -1;

        }

        if ((srcFormat_in != AV_PIX_FMT_NONE && srcFormat_in != srcFormat) ||

            (dstFormat_in != AV_PIX_FMT_NONE && dstFormat_in != dstFormat))

            continue;

        if (ret != 12) {

            printf("%s", buf);

            continue;

        }



        doTest(ref, refStride, w, h,

               srcFormat, dstFormat,

               srcW, srcH, dstW, dstH, flags,

               &r);

    }



    return 0;

}

static int dirac_decode_frame_internal(DiracContext *s)

{

    DWTContext d;

    int y, i, comp, dsty;



    if (s->low_delay) {

        /* [DIRAC_STD] 13.5.1 low_delay_transform_data() */

        for (comp = 0; comp < 3; comp++) {

            Plane *p = &s->plane[comp];

            memset(p->idwt_buf, 0, p->idwt_stride * p->idwt_height * sizeof(IDWTELEM));

        }

        if (!s->zero_res)

            decode_lowdelay(s);

    }



    for (comp = 0; comp < 3; comp++) {

        Plane *p       = &s->plane[comp];

        uint8_t *frame = s->current_picture->avframe->data[comp];



        /* FIXME: small resolutions */

        for (i = 0; i < 4; i++)

            s->edge_emu_buffer[i] = s->edge_emu_buffer_base + i*FFALIGN(p->width, 16);



        if (!s->zero_res && !s->low_delay)

        {

            memset(p->idwt_buf, 0, p->idwt_stride * p->idwt_height * sizeof(IDWTELEM));

            decode_component(s, comp); /* [DIRAC_STD] 13.4.1 core_transform_data() */

        }

        if (ff_spatial_idwt_init2(&d, p->idwt_buf, p->idwt_width, p->idwt_height, p->idwt_stride,

                                  s->wavelet_idx+2, s->wavelet_depth, p->idwt_tmp))

            return -1;



        if (!s->num_refs) { /* intra */

            for (y = 0; y < p->height; y += 16) {

                ff_spatial_idwt_slice2(&d, y+16); /* decode */

                s->diracdsp.put_signed_rect_clamped(frame + y*p->stride, p->stride,

                                                    p->idwt_buf + y*p->idwt_stride, p->idwt_stride, p->width, 16);

            }

        } else { /* inter */

            int rowheight = p->ybsep*p->stride;



            select_dsp_funcs(s, p->width, p->height, p->xblen, p->yblen);



            for (i = 0; i < s->num_refs; i++)

                interpolate_refplane(s, s->ref_pics[i], comp, p->width, p->height);



            memset(s->mctmp, 0, 4*p->yoffset*p->stride);



            dsty = -p->yoffset;

            for (y = 0; y < s->blheight; y++) {

                int h     = 0,

                    start = FFMAX(dsty, 0);

                uint16_t *mctmp    = s->mctmp + y*rowheight;

                DiracBlock *blocks = s->blmotion + y*s->blwidth;



                init_obmc_weights(s, p, y);



                if (y == s->blheight-1 || start+p->ybsep > p->height)

                    h = p->height - start;

                else

                    h = p->ybsep - (start - dsty);

                if (h < 0)

                    break;



                memset(mctmp+2*p->yoffset*p->stride, 0, 2*rowheight);

                mc_row(s, blocks, mctmp, comp, dsty);



                mctmp += (start - dsty)*p->stride + p->xoffset;

                ff_spatial_idwt_slice2(&d, start + h); /* decode */

                s->diracdsp.add_rect_clamped(frame + start*p->stride, mctmp, p->stride,

                                             p->idwt_buf + start*p->idwt_stride, p->idwt_stride, p->width, h);



                dsty += p->ybsep;

            }

        }

    }





    return 0;

}

void updateMMXDitherTables(SwsContext *c, int dstY, int lumBufIndex, int chrBufIndex,

                           int lastInLumBuf, int lastInChrBuf)

{

    const int dstH= c->dstH;

    const int flags= c->flags;

    int16_t **lumPixBuf= c->lumPixBuf;

    int16_t **chrUPixBuf= c->chrUPixBuf;

    int16_t **alpPixBuf= c->alpPixBuf;

    const int vLumBufSize= c->vLumBufSize;

    const int vChrBufSize= c->vChrBufSize;

    int32_t *vLumFilterPos= c->vLumFilterPos;

    int32_t *vChrFilterPos= c->vChrFilterPos;

    int16_t *vLumFilter= c->vLumFilter;

    int16_t *vChrFilter= c->vChrFilter;

    int32_t *lumMmxFilter= c->lumMmxFilter;

    int32_t *chrMmxFilter= c->chrMmxFilter;

    int32_t av_unused *alpMmxFilter= c->alpMmxFilter;

    const int vLumFilterSize= c->vLumFilterSize;

    const int vChrFilterSize= c->vChrFilterSize;

    const int chrDstY= dstY>>c->chrDstVSubSample;

    const int firstLumSrcY= vLumFilterPos[dstY]; //First line needed as input

    const int firstChrSrcY= vChrFilterPos[chrDstY]; //First line needed as input



    c->blueDither= ff_dither8[dstY&1];

    if (c->dstFormat == PIX_FMT_RGB555 || c->dstFormat == PIX_FMT_BGR555)

        c->greenDither= ff_dither8[dstY&1];

    else

        c->greenDither= ff_dither4[dstY&1];

    c->redDither= ff_dither8[(dstY+1)&1];

    if (dstY < dstH - 2) {

        const int16_t **lumSrcPtr= (const int16_t **)(void*) lumPixBuf + lumBufIndex + firstLumSrcY - lastInLumBuf + vLumBufSize;

        const int16_t **chrUSrcPtr= (const int16_t **)(void*) chrUPixBuf + chrBufIndex + firstChrSrcY - lastInChrBuf + vChrBufSize;

        const int16_t **alpSrcPtr= (CONFIG_SWSCALE_ALPHA && alpPixBuf) ? (const int16_t **)(void*) alpPixBuf + lumBufIndex + firstLumSrcY - lastInLumBuf + vLumBufSize : NULL;

        int i;



        if (firstLumSrcY < 0 || firstLumSrcY + vLumFilterSize > c->srcH) {

            const int16_t **tmpY = (const int16_t **) lumPixBuf + 2 * vLumBufSize;

            int neg = -firstLumSrcY, i, end = FFMIN(c->srcH - firstLumSrcY, vLumFilterSize);

            for (i = 0; i < neg;            i++)

                tmpY[i] = lumSrcPtr[neg];

            for (     ; i < end;            i++)

                tmpY[i] = lumSrcPtr[i];

            for (     ; i < vLumFilterSize; i++)

                tmpY[i] = tmpY[i-1];

            lumSrcPtr = tmpY;



            if (alpSrcPtr) {

                const int16_t **tmpA = (const int16_t **) alpPixBuf + 2 * vLumBufSize;

                for (i = 0; i < neg;            i++)

                    tmpA[i] = alpSrcPtr[neg];

                for (     ; i < end;            i++)

                    tmpA[i] = alpSrcPtr[i];

                for (     ; i < vLumFilterSize; i++)

                    tmpA[i] = tmpA[i - 1];

                alpSrcPtr = tmpA;

            }

        }

        if (firstChrSrcY < 0 || firstChrSrcY + vChrFilterSize > c->chrSrcH) {

            const int16_t **tmpU = (const int16_t **) chrUPixBuf + 2 * vChrBufSize;

            int neg = -firstChrSrcY, i, end = FFMIN(c->chrSrcH - firstChrSrcY, vChrFilterSize);

            for (i = 0; i < neg;            i++) {

                tmpU[i] = chrUSrcPtr[neg];

            }

            for (     ; i < end;            i++) {

                tmpU[i] = chrUSrcPtr[i];

            }

            for (     ; i < vChrFilterSize; i++) {

                tmpU[i] = tmpU[i - 1];

            }

            chrUSrcPtr = tmpU;

        }



        if (flags & SWS_ACCURATE_RND) {

            int s= APCK_SIZE / 8;

            for (i=0; i<vLumFilterSize; i+=2) {

                *(const void**)&lumMmxFilter[s*i              ]= lumSrcPtr[i  ];

                *(const void**)&lumMmxFilter[s*i+APCK_PTR2/4  ]= lumSrcPtr[i+(vLumFilterSize>1)];

                lumMmxFilter[s*i+APCK_COEF/4  ]=

                lumMmxFilter[s*i+APCK_COEF/4+1]= vLumFilter[dstY*vLumFilterSize + i    ]

                + (vLumFilterSize>1 ? vLumFilter[dstY*vLumFilterSize + i + 1]<<16 : 0);

                if (CONFIG_SWSCALE_ALPHA && alpPixBuf) {

                    *(const void**)&alpMmxFilter[s*i              ]= alpSrcPtr[i  ];

                    *(const void**)&alpMmxFilter[s*i+APCK_PTR2/4  ]= alpSrcPtr[i+(vLumFilterSize>1)];

                    alpMmxFilter[s*i+APCK_COEF/4  ]=

                    alpMmxFilter[s*i+APCK_COEF/4+1]= lumMmxFilter[s*i+APCK_COEF/4  ];

                }

            }

            for (i=0; i<vChrFilterSize; i+=2) {

                *(const void**)&chrMmxFilter[s*i              ]= chrUSrcPtr[i  ];

                *(const void**)&chrMmxFilter[s*i+APCK_PTR2/4  ]= chrUSrcPtr[i+(vChrFilterSize>1)];

                chrMmxFilter[s*i+APCK_COEF/4  ]=

                chrMmxFilter[s*i+APCK_COEF/4+1]= vChrFilter[chrDstY*vChrFilterSize + i    ]

                + (vChrFilterSize>1 ? vChrFilter[chrDstY*vChrFilterSize + i + 1]<<16 : 0);

            }

        } else {

            for (i=0; i<vLumFilterSize; i++) {

                *(const void**)&lumMmxFilter[4*i+0]= lumSrcPtr[i];

                lumMmxFilter[4*i+2]=

                lumMmxFilter[4*i+3]=

                ((uint16_t)vLumFilter[dstY*vLumFilterSize + i])*0x10001;

                if (CONFIG_SWSCALE_ALPHA && alpPixBuf) {

                    *(const void**)&alpMmxFilter[4*i+0]= alpSrcPtr[i];

                    alpMmxFilter[4*i+2]=

                    alpMmxFilter[4*i+3]= lumMmxFilter[4*i+2];

                }

            }

            for (i=0; i<vChrFilterSize; i++) {

                *(const void**)&chrMmxFilter[4*i+0]= chrUSrcPtr[i];

                chrMmxFilter[4*i+2]=

                chrMmxFilter[4*i+3]=

                ((uint16_t)vChrFilter[chrDstY*vChrFilterSize + i])*0x10001;

            }

        }

    }

}

static av_cold int alloc_buffers(AVCodecContext *avctx, AACEncContext *s)

{

    FF_ALLOCZ_OR_GOTO(avctx, s->buffer.samples, 3 * 1024 * s->channels * sizeof(s->buffer.samples[0]), alloc_fail);

    FF_ALLOCZ_OR_GOTO(avctx, s->cpe, sizeof(ChannelElement) * s->chan_map[0], alloc_fail);

    FF_ALLOCZ_OR_GOTO(avctx, avctx->extradata, 5 + FF_INPUT_BUFFER_PADDING_SIZE, alloc_fail);



    for(int ch = 0; ch < s->channels; ch++)

        s->planar_samples[ch] = s->buffer.samples + 3 * 1024 * ch;



    return 0;

alloc_fail:

    return AVERROR(ENOMEM);

}

void ff_aac_update_ltp(AACEncContext *s, SingleChannelElement *sce)

{

    int i, j, lag;

    float corr, s0, s1, max_corr = 0.0f;

    float *samples = &s->planar_samples[s->cur_channel][1024];

    float *pred_signal = &sce->ltp_state[0];

    int samples_num = 2048;



    if (s->profile != FF_PROFILE_AAC_LTP)

        return;



    /* Calculate lag */

    for (i = 0; i < samples_num; i++) {

        s0 = s1 = 0.0f;

        for (j = 0; j < samples_num; j++) {

            if (j + 1024 < i)

                continue;

            s0 += samples[j]*pred_signal[j-i+1024];

            s1 += pred_signal[j-i+1024]*pred_signal[j-i+1024];

        }

        corr = s1 > 0.0f ? s0/sqrt(s1) : 0.0f;

        if (corr > max_corr) {

            max_corr = corr;

            lag = i;

        }

    }

    lag = av_clip_uintp2(lag, 11); /* 11 bits => 2^11 = 0->2047 */



    if (!lag) {

        sce->ics.ltp.lag = lag;

        return;

    }



    s0 = s1 = 0.0f;

    for (i = 0; i < lag; i++) {

        s0 += samples[i];

        s1 += pred_signal[i-lag+1024];

    }



    sce->ics.ltp.coef_idx = quant_array_idx(s0/s1, ltp_coef, 8);

    sce->ics.ltp.coef     = ltp_coef[sce->ics.ltp.coef_idx];



    /* Predict the new samples */

    if (lag < 1024)

        samples_num = lag + 1024;

    for (i = 0; i < samples_num; i++)

        pred_signal[i+1024] = sce->ics.ltp.coef*pred_signal[i-lag+1024];

    memset(&pred_signal[samples_num], 0, (2048 - samples_num)*sizeof(float));



    sce->ics.ltp.lag = lag;

}

