static int pcx_encode_frame(AVCodecContext *avctx,

                            unsigned char *buf, int buf_size, void *data)

{

    PCXContext *s = avctx->priv_data;

    AVFrame *const pict = &s->picture;

    const uint8_t *buf_start = buf;

    const uint8_t *buf_end   = buf + buf_size;



    int bpp, nplanes, i, y, line_bytes, written;

    const uint32_t *pal = NULL;


    const uint8_t *src;



    *pict = *(AVFrame *)data;

    pict->pict_type = AV_PICTURE_TYPE_I;

    pict->key_frame = 1;



    if (avctx->width > 65535 || avctx->height > 65535) {

        av_log(avctx, AV_LOG_ERROR, "image dimensions do not fit in 16 bits\n");

        return -1;

    }



    switch (avctx->pix_fmt) {

    case PIX_FMT_RGB24:

        bpp = 8;

        nplanes = 3;

        break;

    case PIX_FMT_RGB8:

    case PIX_FMT_BGR8:

    case PIX_FMT_RGB4_BYTE:

    case PIX_FMT_BGR4_BYTE:

    case PIX_FMT_GRAY8:

        bpp = 8;

        nplanes = 1;

        ff_set_systematic_pal2(palette256, avctx->pix_fmt);

        pal = palette256;

        break;

    case PIX_FMT_PAL8:

        bpp = 8;

        nplanes = 1;

        pal = (uint32_t *)pict->data[1];

        break;

    case PIX_FMT_MONOBLACK:

        bpp = 1;

        nplanes = 1;

        pal = monoblack_pal;

        break;

    default:

        av_log(avctx, AV_LOG_ERROR, "unsupported pixfmt\n");

        return -1;

    }



    line_bytes = (avctx->width * bpp + 7) >> 3;

    line_bytes = (line_bytes + 1) & ~1;



    bytestream_put_byte(&buf, 10);                  // manufacturer

    bytestream_put_byte(&buf, 5);                   // version

    bytestream_put_byte(&buf, 1);                   // encoding

    bytestream_put_byte(&buf, bpp);                 // bits per pixel per plane

    bytestream_put_le16(&buf, 0);                   // x min

    bytestream_put_le16(&buf, 0);                   // y min

    bytestream_put_le16(&buf, avctx->width - 1);    // x max

    bytestream_put_le16(&buf, avctx->height - 1);   // y max

    bytestream_put_le16(&buf, 0);                   // horizontal DPI

    bytestream_put_le16(&buf, 0);                   // vertical DPI

    for (i = 0; i < 16; i++)

        bytestream_put_be24(&buf, pal ? pal[i] : 0);// palette (<= 16 color only)

    bytestream_put_byte(&buf, 0);                   // reserved

    bytestream_put_byte(&buf, nplanes);             // number of planes

    bytestream_put_le16(&buf, line_bytes);          // scanline plane size in bytes



    while (buf - buf_start < 128)

        *buf++= 0;



    src = pict->data[0];



    for (y = 0; y < avctx->height; y++) {

        if ((written = pcx_rle_encode(buf, buf_end - buf,

                                      src, line_bytes, nplanes)) < 0) {

            av_log(avctx, AV_LOG_ERROR, "buffer too small\n");

            return -1;

        }

        buf += written;

        src += pict->linesize[0];

    }



    if (nplanes == 1 && bpp == 8) {

        if (buf_end - buf < 257) {

            av_log(avctx, AV_LOG_ERROR, "buffer too small\n");

            return -1;

        }

        bytestream_put_byte(&buf, 12);

        for (i = 0; i < 256; i++) {

            bytestream_put_be24(&buf, pal[i]);

        }

    }



    return buf - buf_start;

}

static int dxtory_decode_v1_rgb(AVCodecContext *avctx, AVFrame *pic,

                                const uint8_t *src, int src_size,

                                int id, int bpp)

{

    int h;

    uint8_t *dst;

    int ret;



    if (src_size < avctx->width * avctx->height * bpp) {

        av_log(avctx, AV_LOG_ERROR, "packet too small\n");

        return AVERROR_INVALIDDATA;

    }



    avctx->pix_fmt = id;

    if ((ret = ff_get_buffer(avctx, pic, 0)) < 0)

        return ret;



    dst = pic->data[0];

    for (h = 0; h < avctx->height; h++) {

        memcpy(dst, src, avctx->width * bpp);

        src += avctx->width * bpp;

        dst += pic->linesize[0];

    }



    return 0;

}

static int mov_read_smi(MOVContext *c, AVIOContext *pb, MOVAtom atom)

{

    AVStream *st;



    if (c->fc->nb_streams < 1)

        return 0;

    st = c->fc->streams[c->fc->nb_streams-1];



    if ((uint64_t)atom.size > (1<<30))

        return AVERROR_INVALIDDATA;



    // currently SVQ3 decoder expect full STSD header - so let's fake it

    // this should be fixed and just SMI header should be passed

    av_free(st->codec->extradata);

    st->codec->extradata = av_mallocz(atom.size + 0x5a + FF_INPUT_BUFFER_PADDING_SIZE);

    if (!st->codec->extradata)

        return AVERROR(ENOMEM);

    st->codec->extradata_size = 0x5a + atom.size;

    memcpy(st->codec->extradata, "SVQ3", 4); // fake

    avio_read(pb, st->codec->extradata + 0x5a, atom.size);

    av_log(c->fc, AV_LOG_TRACE, "Reading SMI %"PRId64"  %s\n", atom.size, st->codec->extradata + 0x5a);

    return 0;

}

AVFilterFormats *avfilter_merge_formats(AVFilterFormats *a, AVFilterFormats *b)

{

    AVFilterFormats *ret;

    unsigned i, j, k = 0;



    ret = av_mallocz(sizeof(AVFilterFormats));



    /* merge list of formats */

    ret->formats = av_malloc(sizeof(*ret->formats) * FFMIN(a->format_count,

                                                           b->format_count));

    for(i = 0; i < a->format_count; i ++)

        for(j = 0; j < b->format_count; j ++)

            if(a->formats[i] == b->formats[j])

                ret->formats[k++] = a->formats[i];



    /* check that there was at least one common format */

    if(!(ret->format_count = k)) {

        av_free(ret->formats);

        av_free(ret);

        return NULL;

    }



    /* merge and update all the references */

    ret->refs = av_malloc(sizeof(AVFilterFormats**)*(a->refcount+b->refcount));

    for(i = 0; i < a->refcount; i ++) {

        ret->refs[ret->refcount] = a->refs[i];

        *ret->refs[ret->refcount++] = ret;

    }

    for(i = 0; i < b->refcount; i ++) {

        ret->refs[ret->refcount] = b->refs[i];

        *ret->refs[ret->refcount++] = ret;

    }



    av_free(a->refs);

    av_free(a->formats);

    av_free(a);



    av_free(b->refs);

    av_free(b->formats);

    av_free(b);



    return ret;

}

