static void lfe_downsample(DCAEncContext *c, const int32_t *input)

{

    /* FIXME: make 128x LFE downsampling possible */

    const int lfech = lfe_index[c->channel_config];

    int i, j, lfes;

    int32_t hist[512];

    int32_t accum;

    int hist_start = 0;



    for (i = 0; i < 512; i++)

        hist[i] = c->history[i][c->channels - 1];



    for (lfes = 0; lfes < DCA_LFE_SAMPLES; lfes++) {

        /* Calculate the convolution */

        accum = 0;



        for (i = hist_start, j = 0; i < 512; i++, j++)

            accum += mul32(hist[i], lfe_fir_64i[j]);

        for (i = 0; i < hist_start; i++, j++)

            accum += mul32(hist[i], lfe_fir_64i[j]);



        c->downsampled_lfe[lfes] = accum;



        /* Copy in 64 new samples from input */

        for (i = 0; i < 64; i++)

            hist[i + hist_start] = input[(lfes * 64 + i) * c->channels + lfech];



        hist_start = (hist_start + 64) & 511;

    }

}

static int indeo3_decode_frame(AVCodecContext *avctx,

                               void *data, int *data_size,

                               const uint8_t *buf, int buf_size)

{

    Indeo3DecodeContext *s=avctx->priv_data;

    uint8_t *src, *dest;

    int y;



    iv_decode_frame(s, buf, buf_size);



    if(s->frame.data[0])

        avctx->release_buffer(avctx, &s->frame);



    s->frame.reference = 0;

    if(avctx->get_buffer(avctx, &s->frame) < 0) {

        av_log(s->avctx, AV_LOG_ERROR, "get_buffer() failed\n");

        return -1;

    }



    src = s->cur_frame->Ybuf;

    dest = s->frame.data[0];

    for (y = 0; y < s->height; y++) {

        memcpy(dest, src, s->cur_frame->y_w);

        src += s->cur_frame->y_w;

        dest += s->frame.linesize[0];

    }



    if (!(s->avctx->flags & CODEC_FLAG_GRAY))

    {

        src = s->cur_frame->Ubuf;

        dest = s->frame.data[1];

        for (y = 0; y < s->height / 4; y++) {

            memcpy(dest, src, s->cur_frame->uv_w);

            src += s->cur_frame->uv_w;

            dest += s->frame.linesize[1];

        }



        src = s->cur_frame->Vbuf;

        dest = s->frame.data[2];

        for (y = 0; y < s->height / 4; y++) {

            memcpy(dest, src, s->cur_frame->uv_w);

            src += s->cur_frame->uv_w;

            dest += s->frame.linesize[2];

        }

    }



    *data_size=sizeof(AVFrame);

    *(AVFrame*)data= s->frame;



    return buf_size;

}

static void filter_mb_edgech( H264Context *h, uint8_t *pix, int stride, int bS[4], int qp ) {

    int i, d;

    const int index_a = clip( qp + h->slice_alpha_c0_offset, 0, 51 );

    const int alpha = alpha_table[index_a];

    const int beta  = beta_table[clip( qp + h->slice_beta_offset, 0, 51 )];

    const int pix_next  = stride;



    for( i = 0; i < 4; i++ )

    {

        if( bS[i] == 0 ) {

            pix += 2;

            continue;

        }



        /* 2px edge length (see deblocking_filter_edgecv) */

        for( d = 0; d < 2; d++ ) {

            const uint8_t p0 = pix[-1*pix_next];

            const uint8_t p1 = pix[-2*pix_next];

            const uint8_t q0 = pix[0];

            const uint8_t q1 = pix[1*pix_next];



            if( abs( p0 - q0 ) >= alpha ||

                abs( p1 - p0 ) >= beta ||

                abs( q1 - q0 ) >= beta ) {

                pix++;

                continue;

            }



            if( bS[i] < 4 ) {

                int tc = tc0_table[index_a][bS[i] - 1] + 1;

                int i_delta = clip( (((q0 - p0 ) << 2) + (p1 - q1) + 4) >> 3, -tc, tc );



                pix[-pix_next] = clip( p0 + i_delta, 0, 255 );    /* p0' */

                pix[0]         = clip( q0 - i_delta, 0, 255 );    /* q0' */

            }

            else

            {

                pix[-pix_next] = ( 2*p1 + p0 + q1 + 2 ) >> 2;   /* p0' */

                pix[0]         = ( 2*q1 + q0 + p1 + 2 ) >> 2;   /* q0' */

            }

            pix++;

        }

    }

}

static int msrle_decode_frame(AVCodecContext *avctx,

                              void *data, int *got_frame,

                              AVPacket *avpkt)

{

    const uint8_t *buf = avpkt->data;

    int buf_size = avpkt->size;

    MsrleContext *s = avctx->priv_data;

    int istride = FFALIGN(avctx->width*avctx->bits_per_coded_sample, 32) / 8;

    int ret;



    s->buf = buf;

    s->size = buf_size;



    if ((ret = ff_reget_buffer(avctx, s->frame)) < 0)

        return ret;



    if (avctx->bits_per_coded_sample > 1 && avctx->bits_per_coded_sample <= 8) {

        const uint8_t *pal = av_packet_get_side_data(avpkt, AV_PKT_DATA_PALETTE, NULL);



        if (pal) {

            s->frame->palette_has_changed = 1;

            memcpy(s->pal, pal, AVPALETTE_SIZE);

        }

        /* make the palette available */

        memcpy(s->frame->data[1], s->pal, AVPALETTE_SIZE);

    }



    /* FIXME how to correctly detect RLE ??? */

    if (avctx->height * istride == avpkt->size) { /* assume uncompressed */

        int linesize = (avctx->width * avctx->bits_per_coded_sample + 7) / 8;

        uint8_t *ptr = s->frame->data[0];

        uint8_t *buf = avpkt->data + (avctx->height-1)*istride;

        int i, j;



        for (i = 0; i < avctx->height; i++) {

            if (avctx->bits_per_coded_sample == 4) {

                for (j = 0; j < avctx->width - 1; j += 2) {

                    ptr[j+0] = buf[j>>1] >> 4;

                    ptr[j+1] = buf[j>>1] & 0xF;

                }

                if (avctx->width & 1)

                    ptr[j+0] = buf[j>>1] >> 4;

            } else {

                memcpy(ptr, buf, linesize);

            }

            buf -= istride;

            ptr += s->frame->linesize[0];

        }

    } else {

        bytestream2_init(&s->gb, buf, buf_size);

        ff_msrle_decode(avctx, (AVPicture*)s->frame, avctx->bits_per_coded_sample, &s->gb);

    }



    if ((ret = av_frame_ref(data, s->frame)) < 0)

        return ret;



    *got_frame      = 1;



    /* report that the buffer was completely consumed */

    return buf_size;

}

