static void compute_antialias_fixed(MPADecodeContext *s, GranuleDef *g)

{

    int32_t *ptr, *csa;

    int n, i;



    /* we antialias only "long" bands */

    if (g->block_type == 2) {

        if (!g->switch_point)

            return;

        /* XXX: check this for 8000Hz case */

        n = 1;

    } else {

        n = SBLIMIT - 1;

    }



    ptr = g->sb_hybrid + 18;

    for(i = n;i > 0;i--) {

        int tmp0, tmp1, tmp2;

        csa = &csa_table[0][0];

#define INT_AA(j) \

            tmp0 = ptr[-1-j];\

            tmp1 = ptr[   j];\

            tmp2= MULH(tmp0 + tmp1, csa[0+4*j]);\

            ptr[-1-j] = 4*(tmp2 - MULH(tmp1, csa[2+4*j]));\

            ptr[   j] = 4*(tmp2 + MULH(tmp0, csa[3+4*j]));



        INT_AA(0)

        INT_AA(1)

        INT_AA(2)

        INT_AA(3)

        INT_AA(4)

        INT_AA(5)

        INT_AA(6)

        INT_AA(7)



        ptr += 18;

    }

}

av_cold struct FFIIRFilterCoeffs* ff_iir_filter_init_coeffs(enum IIRFilterType filt_type,

                                                    enum IIRFilterMode filt_mode,

                                                    int order, float cutoff_ratio,

                                                    float stopband, float ripple)

{

    int i, j;

    FFIIRFilterCoeffs *c;

    double wa;

    double p[MAXORDER + 1][2];



    if(filt_type != FF_FILTER_TYPE_BUTTERWORTH || filt_mode != FF_FILTER_MODE_LOWPASS)

        return NULL;

    if(order <= 1 || (order & 1) || order > MAXORDER || cutoff_ratio >= 1.0)

        return NULL;



    c = av_malloc(sizeof(FFIIRFilterCoeffs));

    c->cx = av_malloc(sizeof(c->cx[0]) * ((order >> 1) + 1));

    c->cy = av_malloc(sizeof(c->cy[0]) * order);

    c->order = order;



    wa = 2 * tan(M_PI * 0.5 * cutoff_ratio);



    c->cx[0] = 1;

    for(i = 1; i < (order >> 1) + 1; i++)

        c->cx[i] = c->cx[i - 1] * (order - i + 1LL) / i;



    p[0][0] = 1.0;

    p[0][1] = 0.0;

    for(i = 1; i <= order; i++)

        p[i][0] = p[i][1] = 0.0;

    for(i = 0; i < order; i++){

        double zp[2];

        double th = (i + (order >> 1) + 0.5) * M_PI / order;

        double a_re, a_im, c_re, c_im;

        zp[0] = cos(th) * wa;

        zp[1] = sin(th) * wa;

        a_re = zp[0] + 2.0;

        c_re = zp[0] - 2.0;

        a_im =

        c_im = zp[1];

        zp[0] = (a_re * c_re + a_im * c_im) / (c_re * c_re + c_im * c_im);

        zp[1] = (a_im * c_re - a_re * c_im) / (c_re * c_re + c_im * c_im);



        for(j = order; j >= 1; j--)

        {

            a_re = p[j][0];

            a_im = p[j][1];

            p[j][0] = a_re*zp[0] - a_im*zp[1] + p[j-1][0];

            p[j][1] = a_re*zp[1] + a_im*zp[0] + p[j-1][1];

        }

        a_re    = p[0][0]*zp[0] - p[0][1]*zp[1];

        p[0][1] = p[0][0]*zp[1] + p[0][1]*zp[0];

        p[0][0] = a_re;

    }

    c->gain = p[order][0];

    for(i = 0; i < order; i++){

        c->gain += p[i][0];

        c->cy[i] = (-p[i][0] * p[order][0] + -p[i][1] * p[order][1]) /

                   (p[order][0] * p[order][0] + p[order][1] * p[order][1]);

    }

    c->gain /= 1 << order;



    return c;

}

static void av_estimate_timings_from_bit_rate(AVFormatContext *ic)

{

    int64_t filesize, duration;

    int bit_rate, i;

    AVStream *st;



    /* if bit_rate is already set, we believe it */

    if (ic->bit_rate == 0) {

        bit_rate = 0;

        for(i=0;i<ic->nb_streams;i++) {

            st = ic->streams[i];

            bit_rate += st->codec->bit_rate;

        }

        ic->bit_rate = bit_rate;

    }



    /* if duration is already set, we believe it */

    if (ic->duration == AV_NOPTS_VALUE &&

        ic->bit_rate != 0 &&

        ic->file_size != 0)  {

        filesize = ic->file_size;

        if (filesize > 0) {

            for(i = 0; i < ic->nb_streams; i++) {

                st = ic->streams[i];

                duration= av_rescale(8*filesize, st->time_base.den, ic->bit_rate*(int64_t)st->time_base.num);

                if (st->duration == AV_NOPTS_VALUE)

                    st->duration = duration;

            }

        }

    }

}

static void fft(AC3MDCTContext *mdct, IComplex *z, int ln)

{

    int j, l, np, np2;

    int nblocks, nloops;

    register IComplex *p,*q;

    int tmp_re, tmp_im;



    np = 1 << ln;



    /* reverse */

    for (j = 0; j < np; j++) {

        int k = av_reverse[j] >> (8 - ln);

        if (k < j)

            FFSWAP(IComplex, z[k], z[j]);

    }



    /* pass 0 */



    p = &z[0];

    j = np >> 1;

    do {

        BF(p[0].re, p[0].im, p[1].re, p[1].im,

           p[0].re, p[0].im, p[1].re, p[1].im);

        p += 2;

    } while (--j);



    /* pass 1 */



    p = &z[0];

    j = np >> 2;

    do {

        BF(p[0].re, p[0].im, p[2].re,  p[2].im,

           p[0].re, p[0].im, p[2].re,  p[2].im);

        BF(p[1].re, p[1].im, p[3].re,  p[3].im,

           p[1].re, p[1].im, p[3].im, -p[3].re);

        p+=4;

    } while (--j);



    /* pass 2 .. ln-1 */



    nblocks = np >> 3;

    nloops  =  1 << 2;

    np2     = np >> 1;

    do {

        p = z;

        q = z + nloops;

        for (j = 0; j < nblocks; j++) {

            BF(p->re, p->im, q->re, q->im,

               p->re, p->im, q->re, q->im);

            p++;

            q++;

            for(l = nblocks; l < np2; l += nblocks) {

                CMUL(tmp_re, tmp_im, mdct->costab[l], -mdct->sintab[l], q->re, q->im);

                BF(p->re, p->im, q->re,  q->im,

                   p->re, p->im, tmp_re, tmp_im);

                p++;

                q++;

            }

            p += nloops;

            q += nloops;

        }

        nblocks = nblocks >> 1;

        nloops  = nloops  << 1;

    } while (nblocks);

}

static int mjpeg_decode_init(AVCodecContext *avctx)

{

    MJpegDecodeContext *s = avctx->priv_data;

    MpegEncContext s2;



    s->avctx = avctx;



    /* ugly way to get the idct & scantable FIXME */

    memset(&s2, 0, sizeof(MpegEncContext));

    s2.avctx= avctx;

//    s2->out_format = FMT_MJPEG;

    dsputil_init(&s2.dsp, avctx);

    DCT_common_init(&s2);



    s->scantable= s2.intra_scantable;

    s->idct_put= s2.dsp.idct_put;



    s->mpeg_enc_ctx_allocated = 0;

    s->buffer_size = 102400; /* smaller buffer should be enough,

				but photojpg files could ahive bigger sizes */

    s->buffer = av_malloc(s->buffer_size);

    if (!s->buffer)

	return -1;

    s->start_code = -1;

    s->first_picture = 1;

    s->org_height = avctx->coded_height;



    build_vlc(&s->vlcs[0][0], bits_dc_luminance, val_dc_luminance, 12);

    build_vlc(&s->vlcs[0][1], bits_dc_chrominance, val_dc_chrominance, 12);

    build_vlc(&s->vlcs[1][0], bits_ac_luminance, val_ac_luminance, 251);

    build_vlc(&s->vlcs[1][1], bits_ac_chrominance, val_ac_chrominance, 251);



    if (avctx->flags & CODEC_FLAG_EXTERN_HUFF)

    {

	av_log(avctx, AV_LOG_INFO, "mjpeg: using external huffman table\n");

	init_get_bits(&s->gb, avctx->extradata, avctx->extradata_size*8);

	mjpeg_decode_dht(s);

	/* should check for error - but dunno */

    }



    return 0;

}

int ff_thread_ref_frame(ThreadFrame *dst, ThreadFrame *src)

{

    int ret;



    dst->owner = src->owner;



    ret = av_frame_ref(dst->f, src->f);

    if (ret < 0)

        return ret;



    av_assert0(!dst->progress);



    if (src->progress &&

        !(dst->progress = av_buffer_ref(src->progress))) {

        ff_thread_release_buffer(dst->owner, dst);

        return AVERROR(ENOMEM);

    }



    return 0;

}

static void do_udp_write(void *arg, void *buf, int size) {

    URLContext *h = arg;

    UDPContext *s = h->priv_data;



    int ret;



    if (!(h->flags & AVIO_FLAG_NONBLOCK)) {

        ret = ff_network_wait_fd(s->udp_fd, 1);

        if (ret < 0) {

            s->circular_buffer_error = ret;

            return;

        }

    }



    if (!s->is_connected) {

        ret = sendto (s->udp_fd, buf, size, 0,

                      (struct sockaddr *) &s->dest_addr,

                      s->dest_addr_len);

    } else

        ret = send(s->udp_fd, buf, size, 0);



    s->circular_buffer_error=ret;

}

av_cold struct FFPsyPreprocessContext* ff_psy_preprocess_init(AVCodecContext *avctx)

{

    FFPsyPreprocessContext *ctx;

    int i;

    float cutoff_coeff = 0;

    ctx        = av_mallocz(sizeof(FFPsyPreprocessContext));

    ctx->avctx = avctx;



    if (avctx->cutoff > 0)

        cutoff_coeff = 2.0 * avctx->cutoff / avctx->sample_rate;



    if (cutoff_coeff)

    ctx->fcoeffs = ff_iir_filter_init_coeffs(FF_FILTER_TYPE_BUTTERWORTH, FF_FILTER_MODE_LOWPASS,

                                             FILT_ORDER, cutoff_coeff, 0.0, 0.0);

    if (ctx->fcoeffs) {

        ctx->fstate = av_mallocz(sizeof(ctx->fstate[0]) * avctx->channels);

        for (i = 0; i < avctx->channels; i++)

            ctx->fstate[i] = ff_iir_filter_init_state(FILT_ORDER);

    }

    return ctx;

}

static void png_filter_row(PNGDSPContext *dsp, uint8_t *dst, int filter_type,

                           uint8_t *src, uint8_t *last, int size, int bpp)

{

    int i, p, r, g, b, a;



    switch (filter_type) {

    case PNG_FILTER_VALUE_NONE:

        memcpy(dst, src, size);

        break;

    case PNG_FILTER_VALUE_SUB:

        for (i = 0; i < bpp; i++) {

            dst[i] = src[i];

        }

        if (bpp == 4) {

            p = *(int*)dst;

            for (; i < size; i += bpp) {

                int s = *(int*)(src + i);

                p = ((s & 0x7f7f7f7f) + (p & 0x7f7f7f7f)) ^ ((s ^ p) & 0x80808080);

                *(int*)(dst + i) = p;

            }

        } else {

#define OP_SUB(x,s,l) x+s

            UNROLL_FILTER(OP_SUB);

        }

        break;

    case PNG_FILTER_VALUE_UP:

        dsp->add_bytes_l2(dst, src, last, size);

        break;

    case PNG_FILTER_VALUE_AVG:

        for (i = 0; i < bpp; i++) {

            p = (last[i] >> 1);

            dst[i] = p + src[i];

        }

#define OP_AVG(x,s,l) (((x + l) >> 1) + s) & 0xff

        UNROLL_FILTER(OP_AVG);

        break;

    case PNG_FILTER_VALUE_PAETH:

        for (i = 0; i < bpp; i++) {

            p = last[i];

            dst[i] = p + src[i];

        }

        if (bpp > 2 && size > 4) {

            // would write off the end of the array if we let it process the last pixel with bpp=3

            int w = bpp == 4 ? size : size - 3;

            dsp->add_paeth_prediction(dst + i, src + i, last + i, w - i, bpp);

            i = w;

        }

        ff_add_png_paeth_prediction(dst + i, src + i, last + i, size - i, bpp);

        break;

    }

}

static void vp56_mc(VP56Context *s, int b, int plane, uint8_t *src,

                    int stride, int x, int y)

{

    uint8_t *dst = s->frames[VP56_FRAME_CURRENT]->data[plane] + s->block_offset[b];

    uint8_t *src_block;

    int src_offset;

    int overlap_offset = 0;

    int mask = s->vp56_coord_div[b] - 1;

    int deblock_filtering = s->deblock_filtering;

    int dx;

    int dy;



    if (s->avctx->skip_loop_filter >= AVDISCARD_ALL ||

        (s->avctx->skip_loop_filter >= AVDISCARD_NONKEY

         && !s->frames[VP56_FRAME_CURRENT]->key_frame))

        deblock_filtering = 0;



    dx = s->mv[b].x / s->vp56_coord_div[b];

    dy = s->mv[b].y / s->vp56_coord_div[b];



    if (b >= 4) {

        x /= 2;

        y /= 2;

    }

    x += dx - 2;

    y += dy - 2;



    if (x<0 || x+12>=s->plane_width[plane] ||

        y<0 || y+12>=s->plane_height[plane]) {

        s->vdsp.emulated_edge_mc(s->edge_emu_buffer,

                            src + s->block_offset[b] + (dy-2)*stride + (dx-2),

                            stride, 12, 12, x, y,

                            s->plane_width[plane],

                            s->plane_height[plane]);

        src_block = s->edge_emu_buffer;

        src_offset = 2 + 2*stride;

    } else if (deblock_filtering) {

        /* only need a 12x12 block, but there is no such dsp function, */

        /* so copy a 16x12 block */

        s->hdsp.put_pixels_tab[0][0](s->edge_emu_buffer,

                                     src + s->block_offset[b] + (dy-2)*stride + (dx-2),

                                     stride, 12);

        src_block = s->edge_emu_buffer;

        src_offset = 2 + 2*stride;

    } else {

        src_block = src;

        src_offset = s->block_offset[b] + dy*stride + dx;

    }



    if (deblock_filtering)

        vp56_deblock_filter(s, src_block, stride, dx&7, dy&7);



    if (s->mv[b].x & mask)

        overlap_offset += (s->mv[b].x > 0) ? 1 : -1;

    if (s->mv[b].y & mask)

        overlap_offset += (s->mv[b].y > 0) ? stride : -stride;



    if (overlap_offset) {

        if (s->filter)

            s->filter(s, dst, src_block, src_offset, src_offset+overlap_offset,

                      stride, s->mv[b], mask, s->filter_selection, b<4);

        else

            s->vp3dsp.put_no_rnd_pixels_l2(dst, src_block+src_offset,

                                           src_block+src_offset+overlap_offset,

                                           stride, 8);

    } else {

        s->hdsp.put_pixels_tab[1][0](dst, src_block+src_offset, stride, 8);

    }

}

