int ff_h263_decode_picture_header(MpegEncContext *s)

{

    int format, width, height, i;

    uint32_t startcode;



    align_get_bits(&s->gb);



    if (show_bits(&s->gb, 2) == 2 && s->avctx->frame_number == 0) {

         av_log(s->avctx, AV_LOG_WARNING, "Header looks like RTP instead of H.263\n");

    }



    startcode= get_bits(&s->gb, 22-8);



    for(i= get_bits_left(&s->gb); i>24; i-=8) {

        startcode = ((startcode << 8) | get_bits(&s->gb, 8)) & 0x003FFFFF;



        if(startcode == 0x20)

            break;

    }



    if (startcode != 0x20) {

        av_log(s->avctx, AV_LOG_ERROR, "Bad picture start code\n");

        return -1;

    }

    /* temporal reference */

    i = get_bits(&s->gb, 8); /* picture timestamp */

    if( (s->picture_number&~0xFF)+i < s->picture_number)

        i+= 256;

    s->picture_number= (s->picture_number&~0xFF) + i;



    /* PTYPE starts here */

    if (get_bits1(&s->gb) != 1) {

        /* marker */

        av_log(s->avctx, AV_LOG_ERROR, "Bad marker\n");

        return -1;

    }

    if (get_bits1(&s->gb) != 0) {

        av_log(s->avctx, AV_LOG_ERROR, "Bad H263 id\n");

        return -1;      /* h263 id */

    }

    skip_bits1(&s->gb);         /* split screen off */

    skip_bits1(&s->gb);         /* camera  off */

    skip_bits1(&s->gb);         /* freeze picture release off */



    format = get_bits(&s->gb, 3);

    /*

        0    forbidden

        1    sub-QCIF

        10   QCIF

        7       extended PTYPE (PLUSPTYPE)

    */



    if (format != 7 && format != 6) {

        s->h263_plus = 0;

        /* H.263v1 */

        width = ff_h263_format[format][0];

        height = ff_h263_format[format][1];

        if (!width)

            return -1;



        s->pict_type = AV_PICTURE_TYPE_I + get_bits1(&s->gb);



        s->h263_long_vectors = get_bits1(&s->gb);



        if (get_bits1(&s->gb) != 0) {

            av_log(s->avctx, AV_LOG_ERROR, "H263 SAC not supported\n");

            return -1; /* SAC: off */

        }

        s->obmc= get_bits1(&s->gb); /* Advanced prediction mode */

        s->unrestricted_mv = s->h263_long_vectors || s->obmc;



        s->pb_frame = get_bits1(&s->gb);

        s->chroma_qscale= s->qscale = get_bits(&s->gb, 5);

        skip_bits1(&s->gb); /* Continuous Presence Multipoint mode: off */



        s->width = width;

        s->height = height;

        s->avctx->sample_aspect_ratio= (AVRational){12,11};

        s->avctx->framerate = (AVRational){ 30000, 1001 };

    } else {

        int ufep;



        /* H.263v2 */

        s->h263_plus = 1;

        ufep = get_bits(&s->gb, 3); /* Update Full Extended PTYPE */



        /* ufep other than 0 and 1 are reserved */

        if (ufep == 1) {

            /* OPPTYPE */

            format = get_bits(&s->gb, 3);

            av_dlog(s->avctx, "ufep=1, format: %d\n", format);

            s->custom_pcf= get_bits1(&s->gb);

            s->umvplus = get_bits1(&s->gb); /* Unrestricted Motion Vector */

            if (get_bits1(&s->gb) != 0) {

                av_log(s->avctx, AV_LOG_ERROR, "Syntax-based Arithmetic Coding (SAC) not supported\n");

            }

            s->obmc= get_bits1(&s->gb); /* Advanced prediction mode */

            s->h263_aic = get_bits1(&s->gb); /* Advanced Intra Coding (AIC) */

            s->loop_filter= get_bits1(&s->gb);

            s->unrestricted_mv = s->umvplus || s->obmc || s->loop_filter;

            if(s->avctx->lowres)

                s->loop_filter = 0;



            s->h263_slice_structured= get_bits1(&s->gb);

            if (get_bits1(&s->gb) != 0) {

                av_log(s->avctx, AV_LOG_ERROR, "Reference Picture Selection not supported\n");

            }

            if (get_bits1(&s->gb) != 0) {

                av_log(s->avctx, AV_LOG_ERROR, "Independent Segment Decoding not supported\n");

            }

            s->alt_inter_vlc= get_bits1(&s->gb);

            s->modified_quant= get_bits1(&s->gb);

            if(s->modified_quant)

                s->chroma_qscale_table= ff_h263_chroma_qscale_table;



            skip_bits(&s->gb, 1); /* Prevent start code emulation */



            skip_bits(&s->gb, 3); /* Reserved */

        } else if (ufep != 0) {

            av_log(s->avctx, AV_LOG_ERROR, "Bad UFEP type (%d)\n", ufep);

            return -1;

        }



        /* MPPTYPE */

        s->pict_type = get_bits(&s->gb, 3);

        switch(s->pict_type){

        case 0: s->pict_type= AV_PICTURE_TYPE_I;break;

        case 1: s->pict_type= AV_PICTURE_TYPE_P;break;

        case 2: s->pict_type= AV_PICTURE_TYPE_P;s->pb_frame = 3;break;

        case 3: s->pict_type= AV_PICTURE_TYPE_B;break;

        case 7: s->pict_type= AV_PICTURE_TYPE_I;break; //ZYGO

        default:

            return -1;

        }

        skip_bits(&s->gb, 2);

        s->no_rounding = get_bits1(&s->gb);

        skip_bits(&s->gb, 4);



        /* Get the picture dimensions */

        if (ufep) {

            if (format == 6) {

                /* Custom Picture Format (CPFMT) */

                s->aspect_ratio_info = get_bits(&s->gb, 4);

                av_dlog(s->avctx, "aspect: %d\n", s->aspect_ratio_info);

                /* aspect ratios:

                0 - forbidden

                1 - 1:1

                2 - 12:11 (CIF 4:3)

                3 - 10:11 (525-type 4:3)

                4 - 16:11 (CIF 16:9)

                5 - 40:33 (525-type 16:9)

                6-14 - reserved

                */

                width = (get_bits(&s->gb, 9) + 1) * 4;

                skip_bits1(&s->gb);

                height = get_bits(&s->gb, 9) * 4;

                av_dlog(s->avctx, "\nH.263+ Custom picture: %dx%d\n",width,height);

                if (s->aspect_ratio_info == FF_ASPECT_EXTENDED) {

                    /* aspected dimensions */

                    s->avctx->sample_aspect_ratio.num= get_bits(&s->gb, 8);

                    s->avctx->sample_aspect_ratio.den= get_bits(&s->gb, 8);

                }else{

                    s->avctx->sample_aspect_ratio= ff_h263_pixel_aspect[s->aspect_ratio_info];

                }

            } else {

                width = ff_h263_format[format][0];

                height = ff_h263_format[format][1];

                s->avctx->sample_aspect_ratio= (AVRational){12,11};

            }

            s->avctx->sample_aspect_ratio.den <<= s->ehc_mode;

            if ((width == 0) || (height == 0))

                return -1;

            s->width = width;

            s->height = height;



            if(s->custom_pcf){

                int gcd;

                s->avctx->framerate.num  = 1800000;

                s->avctx->framerate.den  = 1000 + get_bits1(&s->gb);

                s->avctx->framerate.den *= get_bits(&s->gb, 7);

                if(s->avctx->framerate.den == 0){

                    av_log(s, AV_LOG_ERROR, "zero framerate\n");

                    return -1;

                }

                gcd= av_gcd(s->avctx->framerate.den, s->avctx->framerate.num);

                s->avctx->framerate.den /= gcd;

                s->avctx->framerate.num /= gcd;

            }else{

                s->avctx->framerate = (AVRational){ 30000, 1001 };

            }

        }



        if(s->custom_pcf){

            skip_bits(&s->gb, 2); //extended Temporal reference

        }



        if (ufep) {

            if (s->umvplus) {

                if(get_bits1(&s->gb)==0) /* Unlimited Unrestricted Motion Vectors Indicator (UUI) */

                    skip_bits1(&s->gb);

            }

            if(s->h263_slice_structured){

                if (get_bits1(&s->gb) != 0) {

                    av_log(s->avctx, AV_LOG_ERROR, "rectangular slices not supported\n");

                }

                if (get_bits1(&s->gb) != 0) {

                    av_log(s->avctx, AV_LOG_ERROR, "unordered slices not supported\n");

                }

            }

        }



        s->qscale = get_bits(&s->gb, 5);

    }



    if (s->width == 0 || s->height == 0) {

        av_log(s->avctx, AV_LOG_ERROR, "dimensions 0\n");

        return -1;

    }

    s->mb_width = (s->width  + 15) / 16;

    s->mb_height = (s->height  + 15) / 16;

    s->mb_num = s->mb_width * s->mb_height;



    if (s->pb_frame) {

        skip_bits(&s->gb, 3); /* Temporal reference for B-pictures */

        if (s->custom_pcf)

            skip_bits(&s->gb, 2); //extended Temporal reference

        skip_bits(&s->gb, 2); /* Quantization information for B-pictures */

    }



    if (s->pict_type!=AV_PICTURE_TYPE_B) {

        s->time            = s->picture_number;

        s->pp_time         = s->time - s->last_non_b_time;

        s->last_non_b_time = s->time;

    }else{

        s->time    = s->picture_number;

        s->pb_time = s->pp_time - (s->last_non_b_time - s->time);

        if (s->pp_time <=s->pb_time ||

            s->pp_time <= s->pp_time - s->pb_time ||

            s->pp_time <= 0){

            s->pp_time = 2;

            s->pb_time = 1;

        }

        ff_mpeg4_init_direct_mv(s);

    }



    /* PEI */

    if (skip_1stop_8data_bits(&s->gb) < 0)

        return AVERROR_INVALIDDATA;



    if(s->h263_slice_structured){

        if (get_bits1(&s->gb) != 1) {

            av_log(s->avctx, AV_LOG_ERROR, "SEPB1 marker missing\n");

            return -1;

        }



        ff_h263_decode_mba(s);



        if (get_bits1(&s->gb) != 1) {

            av_log(s->avctx, AV_LOG_ERROR, "SEPB2 marker missing\n");

            return -1;

        }

    }

    s->f_code = 1;



    if(s->h263_aic){

         s->y_dc_scale_table=

         s->c_dc_scale_table= ff_aic_dc_scale_table;

    }else{

        s->y_dc_scale_table=

        s->c_dc_scale_table= ff_mpeg1_dc_scale_table;

    }



        ff_h263_show_pict_info(s);

    if (s->pict_type == AV_PICTURE_TYPE_I && s->codec_tag == AV_RL32("ZYGO") && get_bits_left(&s->gb) >= 85 + 13*3*16 + 50){

        int i,j;

        for(i=0; i<85; i++) av_log(s->avctx, AV_LOG_DEBUG, "%d", get_bits1(&s->gb));

        av_log(s->avctx, AV_LOG_DEBUG, "\n");

        for(i=0; i<13; i++){

            for(j=0; j<3; j++){

                int v= get_bits(&s->gb, 8);

                v |= get_sbits(&s->gb, 8)<<8;

                av_log(s->avctx, AV_LOG_DEBUG, " %5d", v);

            }

            av_log(s->avctx, AV_LOG_DEBUG, "\n");

        }

        for(i=0; i<50; i++) av_log(s->avctx, AV_LOG_DEBUG, "%d", get_bits1(&s->gb));

    }



    return 0;

}

static inline void ff_mpeg4_set_one_direct_mv(MpegEncContext *s, int mx, int my, int i){

    static const int tab_size = sizeof(s->direct_scale_mv[0])/sizeof(int16_t);

    static const int tab_bias = (tab_size/2);

    int xy= s->block_index[i];

    uint16_t time_pp= s->pp_time;

    uint16_t time_pb= s->pb_time;

    int p_mx, p_my;



    p_mx= s->next_picture.motion_val[0][xy][0];

    if((unsigned)(p_mx + tab_bias) < tab_size){

        s->mv[0][i][0] = s->direct_scale_mv[0][p_mx + tab_bias] + mx;

        s->mv[1][i][0] = mx ? s->mv[0][i][0] - p_mx

                            : s->direct_scale_mv[1][p_mx + tab_bias];

    }else{

        s->mv[0][i][0] = p_mx*time_pb/time_pp + mx;

        s->mv[1][i][0] = mx ? s->mv[0][i][0] - p_mx

                            : p_mx*(time_pb - time_pp)/time_pp;

    }

    p_my= s->next_picture.motion_val[0][xy][1];

    if((unsigned)(p_my + tab_bias) < tab_size){

        s->mv[0][i][1] = s->direct_scale_mv[0][p_my + tab_bias] + my;

        s->mv[1][i][1] = my ? s->mv[0][i][1] - p_my

                            : s->direct_scale_mv[1][p_my + tab_bias];

    }else{

        s->mv[0][i][1] = p_my*time_pb/time_pp + my;

        s->mv[1][i][1] = my ? s->mv[0][i][1] - p_my

                            : p_my*(time_pb - time_pp)/time_pp;

    }

}

static int read_braindead_odml_indx(AVFormatContext *s, int frame_num){

    AVIContext *avi = s->priv_data;

    AVIOContext *pb = s->pb;

    int longs_pre_entry= avio_rl16(pb);

    int index_sub_type = avio_r8(pb);

    int index_type     = avio_r8(pb);

    int entries_in_use = avio_rl32(pb);

    int chunk_id       = avio_rl32(pb);

    int64_t base       = avio_rl64(pb);

    int stream_id= 10*((chunk_id&0xFF) - '0') + (((chunk_id>>8)&0xFF) - '0');

    AVStream *st;

    AVIStream *ast;

    int i;

    int64_t last_pos= -1;

    int64_t filesize= avi->fsize;



    av_dlog(s, "longs_pre_entry:%d index_type:%d entries_in_use:%d chunk_id:%X base:%16"PRIX64"\n",

            longs_pre_entry,index_type, entries_in_use, chunk_id, base);



    if(stream_id >= s->nb_streams || stream_id < 0)

        return -1;

    st= s->streams[stream_id];

    ast = st->priv_data;



    if(index_sub_type)

        return -1;



    avio_rl32(pb);



    if(index_type && longs_pre_entry != 2)

        return -1;

    if(index_type>1)

        return -1;



    if(filesize > 0 && base >= filesize){

        av_log(s, AV_LOG_ERROR, "ODML index invalid\n");

        if(base>>32 == (base & 0xFFFFFFFF) && (base & 0xFFFFFFFF) < filesize && filesize <= 0xFFFFFFFF)

            base &= 0xFFFFFFFF;

        else

            return -1;

    }



    for(i=0; i<entries_in_use; i++){

        if(index_type){

            int64_t pos= avio_rl32(pb) + base - 8;

            int len    = avio_rl32(pb);

            int key= len >= 0;

            len &= 0x7FFFFFFF;



#ifdef DEBUG_SEEK

            av_log(s, AV_LOG_ERROR, "pos:%"PRId64", len:%X\n", pos, len);

#endif

            if(url_feof(pb))

                return -1;



            if(last_pos == pos || pos == base - 8)

                avi->non_interleaved= 1;

            if(last_pos != pos && (len || !ast->sample_size))

                av_add_index_entry(st, pos, ast->cum_len, len, 0, key ? AVINDEX_KEYFRAME : 0);



            ast->cum_len += get_duration(ast, len);

            last_pos= pos;

        }else{

            int64_t offset, pos;

            int duration;

            offset = avio_rl64(pb);

            avio_rl32(pb);       /* size */

            duration = avio_rl32(pb);



            if(url_feof(pb))

                return -1;



            pos = avio_tell(pb);



            if(avi->odml_depth > MAX_ODML_DEPTH){

                av_log(s, AV_LOG_ERROR, "Too deeply nested ODML indexes\n");

                return -1;

            }



            avio_seek(pb, offset+8, SEEK_SET);

            avi->odml_depth++;

            read_braindead_odml_indx(s, frame_num);

            avi->odml_depth--;

            frame_num += duration;



            avio_seek(pb, pos, SEEK_SET);

        }

    }

    avi->index_loaded=1;

    return 0;

}

static inline void RENAME(rgb24ToUV)(uint8_t *dstU, uint8_t *dstV, const uint8_t *src1, const uint8_t *src2, long width, uint32_t *unused)

{

#if COMPILE_TEMPLATE_MMX

    assert(src1==src2);

    RENAME(bgr24ToUV_mmx)(dstU, dstV, src1, width, PIX_FMT_RGB24);

#else

    int i;

    assert(src1==src2);

    for (i=0; i<width; i++) {

        int r= src1[3*i + 0];

        int g= src1[3*i + 1];

        int b= src1[3*i + 2];



        dstU[i]= (RU*r + GU*g + BU*b + (257<<(RGB2YUV_SHIFT-1)))>>RGB2YUV_SHIFT;

        dstV[i]= (RV*r + GV*g + BV*b + (257<<(RGB2YUV_SHIFT-1)))>>RGB2YUV_SHIFT;

    }

#endif

}

static int noise(AVBitStreamFilterContext *bsfc, AVCodecContext *avctx, const char *args,

                     uint8_t **poutbuf, int *poutbuf_size,

                     const uint8_t *buf, int buf_size, int keyframe){

    unsigned int *state= bsfc->priv_data;

    int amount= args ? atoi(args) : (*state % 10001+1);

    int i;



    if(amount <= 0)

        return AVERROR(EINVAL);



    *poutbuf= av_malloc(buf_size + FF_INPUT_BUFFER_PADDING_SIZE);





    memcpy(*poutbuf, buf, buf_size + FF_INPUT_BUFFER_PADDING_SIZE);

    for(i=0; i<buf_size; i++){

        (*state) += (*poutbuf)[i] + 1;

        if(*state % amount == 0)

            (*poutbuf)[i] = *state;

    }

    return 1;

}

