static inline int is_yuv_planar(const PixFmtInfo *ps)

{

    return (ps->color_type == FF_COLOR_YUV ||

            ps->color_type == FF_COLOR_YUV_JPEG) &&

        ps->pixel_type == FF_PIXEL_PLANAR;

}

int av_opencl_create_kernel(AVOpenCLKernelEnv *env, const char *kernel_name)

{

    cl_int status;

    int i, ret = 0;

    LOCK_OPENCL;

    if (strlen(kernel_name) + 1 > AV_OPENCL_MAX_KERNEL_NAME_SIZE) {

        av_log(&openclutils, AV_LOG_ERROR, "Created kernel name %s is too long\n", kernel_name);

        ret = AVERROR(EINVAL);

        goto end;

    }

    if (!env->kernel) {

        if (gpu_env.kernel_count >= MAX_KERNEL_NUM) {

            av_log(&openclutils, AV_LOG_ERROR,

            "Could not create kernel with name '%s', maximum number of kernels %d already reached\n",

                kernel_name, MAX_KERNEL_NUM);

            ret = AVERROR(EINVAL);

            goto end;

        }

        for (i = 0; i < gpu_env.program_count; i++) {

            env->kernel = clCreateKernel(gpu_env.programs[i], kernel_name, &status);

            if (status == CL_SUCCESS)

                break;

        }

        if (status != CL_SUCCESS) {

            av_log(&openclutils, AV_LOG_ERROR, "Could not create OpenCL kernel: %s\n", opencl_errstr(status));

            ret = AVERROR_EXTERNAL;

            goto end;

        }

        gpu_env.kernel_count++;

        env->command_queue = gpu_env.command_queue;

        av_strlcpy(env->kernel_name, kernel_name, sizeof(env->kernel_name));

    }

end:

    UNLOCK_OPENCL;

    return ret;

}

static int pulse_write_packet(AVFormatContext *h, AVPacket *pkt)

{

    PulseData *s = h->priv_data;

    int size     = pkt->size;

    uint8_t *buf = pkt->data;

    int error;



    if (s->stream_index != pkt->stream_index)

        return 0;



    if ((error = pa_simple_write(s->pa, buf, size, &error))) {

        av_log(s, AV_LOG_ERROR, "pa_simple_write failed: %s\n", pa_strerror(error));

        return AVERROR(EIO);

    }



    return 0;

}

static inline int decode_picture_parameter_set(H264Context *h, int bit_length){

    MpegEncContext * const s = &h->s;

    unsigned int tmp, pps_id= get_ue_golomb(&s->gb);

    PPS *pps;



    pps = alloc_parameter_set(h, (void **)h->pps_buffers, pps_id, MAX_PPS_COUNT, sizeof(PPS), "pps");

    if(pps == NULL)

        return -1;



    tmp= get_ue_golomb(&s->gb);

    if(tmp>=MAX_SPS_COUNT || h->sps_buffers[tmp] == NULL){

        av_log(h->s.avctx, AV_LOG_ERROR, "sps_id out of range\n");

        return -1;

    }

    pps->sps_id= tmp;



    pps->cabac= get_bits1(&s->gb);

    pps->pic_order_present= get_bits1(&s->gb);

    pps->slice_group_count= get_ue_golomb(&s->gb) + 1;

    if(pps->slice_group_count > 1 ){

        pps->mb_slice_group_map_type= get_ue_golomb(&s->gb);

        av_log(h->s.avctx, AV_LOG_ERROR, "FMO not supported\n");

        switch(pps->mb_slice_group_map_type){

        case 0:

#if 0

|   for( i = 0; i <= num_slice_groups_minus1; i++ ) |   |        |

|    run_length[ i ]                                |1  |ue(v)   |

#endif

            break;

        case 2:

#if 0

|   for( i = 0; i < num_slice_groups_minus1; i++ )  |   |        |

|{                                                  |   |        |

|    top_left_mb[ i ]                               |1  |ue(v)   |

|    bottom_right_mb[ i ]                           |1  |ue(v)   |

|   }                                               |   |        |

#endif

            break;

        case 3:

        case 4:

        case 5:

#if 0

|   slice_group_change_direction_flag               |1  |u(1)    |

|   slice_group_change_rate_minus1                  |1  |ue(v)   |

#endif

            break;

        case 6:

#if 0

|   slice_group_id_cnt_minus1                       |1  |ue(v)   |

|   for( i = 0; i <= slice_group_id_cnt_minus1; i++ |   |        |

|)                                                  |   |        |

|    slice_group_id[ i ]                            |1  |u(v)    |

#endif

            break;

        }

    }

    pps->ref_count[0]= get_ue_golomb(&s->gb) + 1;

    pps->ref_count[1]= get_ue_golomb(&s->gb) + 1;

    if(pps->ref_count[0]-1 > 32-1 || pps->ref_count[1]-1 > 32-1){

        av_log(h->s.avctx, AV_LOG_ERROR, "reference overflow (pps)\n");

        pps->ref_count[0]= pps->ref_count[1]= 1;

        return -1;

    }



    pps->weighted_pred= get_bits1(&s->gb);

    pps->weighted_bipred_idc= get_bits(&s->gb, 2);

    pps->init_qp= get_se_golomb(&s->gb) + 26;

    pps->init_qs= get_se_golomb(&s->gb) + 26;

    pps->chroma_qp_index_offset[0]= get_se_golomb(&s->gb);

    pps->deblocking_filter_parameters_present= get_bits1(&s->gb);

    pps->constrained_intra_pred= get_bits1(&s->gb);

    pps->redundant_pic_cnt_present = get_bits1(&s->gb);



    pps->transform_8x8_mode= 0;

    h->dequant_coeff_pps= -1; //contents of sps/pps can change even if id doesn't, so reinit

    memcpy(pps->scaling_matrix4, h->sps_buffers[pps->sps_id]->scaling_matrix4, sizeof(pps->scaling_matrix4));

    memcpy(pps->scaling_matrix8, h->sps_buffers[pps->sps_id]->scaling_matrix8, sizeof(pps->scaling_matrix8));



    if(get_bits_count(&s->gb) < bit_length){

        pps->transform_8x8_mode= get_bits1(&s->gb);

        decode_scaling_matrices(h, h->sps_buffers[pps->sps_id], pps, 0, pps->scaling_matrix4, pps->scaling_matrix8);

        pps->chroma_qp_index_offset[1]= get_se_golomb(&s->gb); //second_chroma_qp_index_offset

    } else {

        pps->chroma_qp_index_offset[1]= pps->chroma_qp_index_offset[0];

    }



    build_qp_table(pps, 0, pps->chroma_qp_index_offset[0]);

    build_qp_table(pps, 1, pps->chroma_qp_index_offset[1]);

    if(pps->chroma_qp_index_offset[0] != pps->chroma_qp_index_offset[1])

        h->pps.chroma_qp_diff= 1;



    if(s->avctx->debug&FF_DEBUG_PICT_INFO){

        av_log(h->s.avctx, AV_LOG_DEBUG, "pps:%u sps:%u %s slice_groups:%d ref:%d/%d %s qp:%d/%d/%d/%d %s %s %s %s\n",

               pps_id, pps->sps_id,

               pps->cabac ? "CABAC" : "CAVLC",

               pps->slice_group_count,

               pps->ref_count[0], pps->ref_count[1],

               pps->weighted_pred ? "weighted" : "",

               pps->init_qp, pps->init_qs, pps->chroma_qp_index_offset[0], pps->chroma_qp_index_offset[1],

               pps->deblocking_filter_parameters_present ? "LPAR" : "",

               pps->constrained_intra_pred ? "CONSTR" : "",

               pps->redundant_pic_cnt_present ? "REDU" : "",

               pps->transform_8x8_mode ? "8x8DCT" : ""

               );

    }



    return 0;

}

static int xface_encode_frame(AVCodecContext *avctx, AVPacket *pkt,

                              const AVFrame *frame, int *got_packet)

{

    XFaceContext *xface = avctx->priv_data;

    ProbRangesQueue pq = {{ 0 }, 0};

    uint8_t bitmap_copy[XFACE_PIXELS];

    BigInt b = {0};

    int i, j, k, ret = 0;

    const uint8_t *buf;

    uint8_t *p;

    char intbuf[XFACE_MAX_DIGITS];



    if (avctx->width || avctx->height) {

        if (avctx->width != XFACE_WIDTH || avctx->height != XFACE_HEIGHT) {

            av_log(avctx, AV_LOG_ERROR,

                   "Size value %dx%d not supported, only accepts a size of %dx%d\n",

                   avctx->width, avctx->height, XFACE_WIDTH, XFACE_HEIGHT);

            return AVERROR(EINVAL);

        }

    }

    avctx->width  = XFACE_WIDTH;

    avctx->height = XFACE_HEIGHT;



    /* convert image from MONOWHITE to 1=black 0=white bitmap */

    buf = frame->data[0];

    for (i = 0, j = 0; i < XFACE_PIXELS; ) {

        for (k = 0; k < 8; k++)

            xface->bitmap[i++] = (buf[j]>>(7-k))&1;

        if (++j == XFACE_WIDTH/8) {

            buf += frame->linesize[0];

            j = 0;

        }

    }



    /* create a copy of bitmap */

    memcpy(bitmap_copy, xface->bitmap, XFACE_PIXELS);

    ff_xface_generate_face(xface->bitmap, bitmap_copy);



    encode_block(xface->bitmap,                         16, 16, 0, &pq);

    encode_block(xface->bitmap + 16,                    16, 16, 0, &pq);

    encode_block(xface->bitmap + 32,                    16, 16, 0, &pq);

    encode_block(xface->bitmap + XFACE_WIDTH * 16,      16, 16, 0, &pq);

    encode_block(xface->bitmap + XFACE_WIDTH * 16 + 16, 16, 16, 0, &pq);

    encode_block(xface->bitmap + XFACE_WIDTH * 16 + 32, 16, 16, 0, &pq);

    encode_block(xface->bitmap + XFACE_WIDTH * 32,      16, 16, 0, &pq);

    encode_block(xface->bitmap + XFACE_WIDTH * 32 + 16, 16, 16, 0, &pq);

    encode_block(xface->bitmap + XFACE_WIDTH * 32 + 32, 16, 16, 0, &pq);



    while (pq.prob_ranges_idx > 0)

        push_integer(&b, pq.prob_ranges[--pq.prob_ranges_idx]);



    /* write the inverted big integer in b to intbuf */

    i = 0;

    while (b.nb_words) {

        uint8_t r;

        ff_big_div(&b, XFACE_PRINTS, &r);

        intbuf[i++] = r + XFACE_FIRST_PRINT;

    }



    if ((ret = ff_alloc_packet2(avctx, pkt, i+2)) < 0)

        return ret;



    /* revert the number, and close the buffer */

    p = pkt->data;

    while (--i >= 0)

        *(p++) = intbuf[i];

    *(p++) = '\n';

    *(p++) = 0;



    pkt->flags |= AV_PKT_FLAG_KEY;

    *got_packet = 1;



    return 0;

}

yuv2422_1_c_template(SwsContext *c, const uint16_t *buf0,

                     const uint16_t *ubuf0, const uint16_t *ubuf1,

                     const uint16_t *vbuf0, const uint16_t *vbuf1,

                     const uint16_t *abuf0, uint8_t *dest, int dstW,

                     int uvalpha, enum PixelFormat dstFormat,

                     int flags, int y, enum PixelFormat target)

{

    int i;



    if (uvalpha < 2048) {

        for (i = 0; i < (dstW >> 1); i++) {

            int Y1 = buf0[i * 2]     >> 7;

            int Y2 = buf0[i * 2 + 1] >> 7;

            int U  = ubuf1[i]        >> 7;

            int V  = vbuf1[i]        >> 7;



            output_pixels(i * 4, Y1, U, Y2, V);

        }

    } else {

        for (i = 0; i < (dstW >> 1); i++) {

            int Y1 =  buf0[i * 2]          >> 7;

            int Y2 =  buf0[i * 2 + 1]      >> 7;

            int U  = (ubuf0[i] + ubuf1[i]) >> 8;

            int V  = (vbuf0[i] + vbuf1[i]) >> 8;



            output_pixels(i * 4, Y1, U, Y2, V);

        }

    }

}

static void encode_signal_range(VC2EncContext *s)

{

    int idx;

    AVCodecContext *avctx = s->avctx;

    const AVPixFmtDescriptor *fmt = av_pix_fmt_desc_get(avctx->pix_fmt);

    const int depth = fmt->comp[0].depth;

    if (depth == 8 && avctx->color_range == AVCOL_RANGE_JPEG) {

        idx = 1;

        s->bpp = 1;

        s->diff_offset = 128;

    } else if (depth == 8 && (avctx->color_range == AVCOL_RANGE_MPEG ||

               avctx->color_range == AVCOL_RANGE_UNSPECIFIED)) {

        idx = 2;

        s->bpp = 1;

        s->diff_offset = 128;

    } else if (depth == 10) {

        idx = 3;

        s->bpp = 2;

        s->diff_offset = 512;

    } else {

        idx = 4;

        s->bpp = 2;

        s->diff_offset = 2048;

    }

    put_bits(&s->pb, 1, !s->strict_compliance);

    if (!s->strict_compliance)

        put_vc2_ue_uint(&s->pb, idx);

}

static av_cold int tta_decode_init(AVCodecContext * avctx)
{
    TTAContext *s = avctx->priv_data;
    int i;
    s->avctx = avctx;
    // 30bytes includes a seektable with one frame
    if (avctx->extradata_size < 30)
        return -1;
    init_get_bits(&s->gb, avctx->extradata, avctx->extradata_size * 8);
    if (show_bits_long(&s->gb, 32) == AV_RL32("TTA1"))
    {
        /* signature */
        skip_bits(&s->gb, 32);
        s->format = get_bits(&s->gb, 16);
        if (s->format > 2) {
            av_log(s->avctx, AV_LOG_ERROR, "Invalid format\n");
            return -1;
        if (s->format == FORMAT_ENCRYPTED) {
            av_log_missing_feature(s->avctx, "Encrypted TTA", 0);
            return AVERROR(EINVAL);
        avctx->channels = s->channels = get_bits(&s->gb, 16);
        avctx->bits_per_coded_sample = get_bits(&s->gb, 16);
        s->bps = (avctx->bits_per_coded_sample + 7) / 8;
        avctx->sample_rate = get_bits_long(&s->gb, 32);
        s->data_length = get_bits_long(&s->gb, 32);
        skip_bits(&s->gb, 32); // CRC32 of header
        switch(s->bps) {
        case 2:
            avctx->sample_fmt = AV_SAMPLE_FMT_S16;
            avctx->bits_per_raw_sample = 16;
            break;
        case 3:
            avctx->sample_fmt = AV_SAMPLE_FMT_S32;
            avctx->bits_per_raw_sample = 24;
            break;
        default:
            av_log(avctx, AV_LOG_ERROR, "Invalid/unsupported sample format.\n");
        // prevent overflow
        if (avctx->sample_rate > 0x7FFFFF) {
            av_log(avctx, AV_LOG_ERROR, "sample_rate too large\n");
            return AVERROR(EINVAL);
        s->frame_length = 256 * avctx->sample_rate / 245;
        s->last_frame_length = s->data_length % s->frame_length;
        s->total_frames = s->data_length / s->frame_length +
                        (s->last_frame_length ? 1 : 0);
        av_log(s->avctx, AV_LOG_DEBUG, "format: %d chans: %d bps: %d rate: %d block: %d\n",
            s->format, avctx->channels, avctx->bits_per_coded_sample, avctx->sample_rate,
            avctx->block_align);
        av_log(s->avctx, AV_LOG_DEBUG, "data_length: %d frame_length: %d last: %d total: %d\n",
            s->data_length, s->frame_length, s->last_frame_length, s->total_frames);
        // FIXME: seek table
        for (i = 0; i < s->total_frames; i++)
            skip_bits(&s->gb, 32);
        skip_bits(&s->gb, 32); // CRC32 of seektable
        if(s->frame_length >= UINT_MAX / (s->channels * sizeof(int32_t))){
            av_log(avctx, AV_LOG_ERROR, "frame_length too large\n");
            return -1;
        if (s->bps == 2) {
            s->decode_buffer = av_mallocz(sizeof(int32_t)*s->frame_length*s->channels);
            if (!s->decode_buffer)
                return AVERROR(ENOMEM);
        s->ch_ctx = av_malloc(avctx->channels * sizeof(*s->ch_ctx));
        if (!s->ch_ctx) {
            av_freep(&s->decode_buffer);
            return AVERROR(ENOMEM);
    } else {
        av_log(avctx, AV_LOG_ERROR, "Wrong extradata present\n");
        return -1;
    avcodec_get_frame_defaults(&s->frame);
    avctx->coded_frame = &s->frame;
    return 0;

static int parse_ffconfig(const char *filename)

{

    FILE *f;

    char line[1024];

    char cmd[64];

    char arg[1024];

    const char *p;

    int val, errors, line_num;

    FFStream **last_stream, *stream, *redirect;

    FFStream **last_feed, *feed, *s;

    AVCodecContext audio_enc, video_enc;

    enum AVCodecID audio_id, video_id;



    f = fopen(filename, "r");

    if (!f) {

        perror(filename);

        return -1;

    }



    errors = 0;

    line_num = 0;

    first_stream = NULL;

    last_stream = &first_stream;

    first_feed = NULL;

    last_feed = &first_feed;

    stream = NULL;

    feed = NULL;

    redirect = NULL;

    audio_id = AV_CODEC_ID_NONE;

    video_id = AV_CODEC_ID_NONE;



#define ERROR(...) report_config_error(filename, line_num, &errors, __VA_ARGS__)

    for(;;) {

        if (fgets(line, sizeof(line), f) == NULL)

            break;

        line_num++;

        p = line;

        while (av_isspace(*p))

            p++;

        if (*p == '\0' || *p == '#')

            continue;



        get_arg(cmd, sizeof(cmd), &p);



        if (!av_strcasecmp(cmd, "Port")) {

            get_arg(arg, sizeof(arg), &p);

            val = atoi(arg);

            if (val < 1 || val > 65536) {

                ERROR("Invalid_port: %s\n", arg);

            }

            my_http_addr.sin_port = htons(val);

        } else if (!av_strcasecmp(cmd, "BindAddress")) {

            get_arg(arg, sizeof(arg), &p);

            if (resolve_host(&my_http_addr.sin_addr, arg) != 0) {

                ERROR("%s:%d: Invalid host/IP address: %s\n", arg);

            }

        } else if (!av_strcasecmp(cmd, "NoDaemon")) {

            // do nothing here, its the default now

        } else if (!av_strcasecmp(cmd, "RTSPPort")) {

            get_arg(arg, sizeof(arg), &p);

            val = atoi(arg);

            if (val < 1 || val > 65536) {

                ERROR("%s:%d: Invalid port: %s\n", arg);

            }

            my_rtsp_addr.sin_port = htons(atoi(arg));

        } else if (!av_strcasecmp(cmd, "RTSPBindAddress")) {

            get_arg(arg, sizeof(arg), &p);

            if (resolve_host(&my_rtsp_addr.sin_addr, arg) != 0) {

                ERROR("Invalid host/IP address: %s\n", arg);

            }

        } else if (!av_strcasecmp(cmd, "MaxHTTPConnections")) {

            get_arg(arg, sizeof(arg), &p);

            val = atoi(arg);

            if (val < 1 || val > 65536) {

                ERROR("Invalid MaxHTTPConnections: %s\n", arg);

            }

            nb_max_http_connections = val;

        } else if (!av_strcasecmp(cmd, "MaxClients")) {

            get_arg(arg, sizeof(arg), &p);

            val = atoi(arg);

            if (val < 1 || val > nb_max_http_connections) {

                ERROR("Invalid MaxClients: %s\n", arg);

            } else {

                nb_max_connections = val;

            }

        } else if (!av_strcasecmp(cmd, "MaxBandwidth")) {

            int64_t llval;

            get_arg(arg, sizeof(arg), &p);

            llval = strtoll(arg, NULL, 10);

            if (llval < 10 || llval > 10000000) {

                ERROR("Invalid MaxBandwidth: %s\n", arg);

            } else

                max_bandwidth = llval;

        } else if (!av_strcasecmp(cmd, "CustomLog")) {

            if (!ffserver_debug)

                get_arg(logfilename, sizeof(logfilename), &p);

        } else if (!av_strcasecmp(cmd, "<Feed")) {

            /*********************************************/

            /* Feed related options */

            char *q;

            if (stream || feed) {

                ERROR("Already in a tag\n");

            } else {

                feed = av_mallocz(sizeof(FFStream));

                get_arg(feed->filename, sizeof(feed->filename), &p);

                q = strrchr(feed->filename, '>');

                if (*q)

                    *q = '\0';



                for (s = first_feed; s; s = s->next) {

                    if (!strcmp(feed->filename, s->filename)) {

                        ERROR("Feed '%s' already registered\n", s->filename);

                    }

                }



                feed->fmt = av_guess_format("ffm", NULL, NULL);

                /* defaut feed file */

                snprintf(feed->feed_filename, sizeof(feed->feed_filename),

                         "/tmp/%s.ffm", feed->filename);

                feed->feed_max_size = 5 * 1024 * 1024;

                feed->is_feed = 1;

                feed->feed = feed; /* self feeding :-) */



                /* add in stream list */

                *last_stream = feed;

                last_stream = &feed->next;

                /* add in feed list */

                *last_feed = feed;

                last_feed = &feed->next_feed;

            }

        } else if (!av_strcasecmp(cmd, "Launch")) {

            if (feed) {

                int i;



                feed->child_argv = av_mallocz(64 * sizeof(char *));



                for (i = 0; i < 62; i++) {

                    get_arg(arg, sizeof(arg), &p);

                    if (!arg[0])

                        break;



                    feed->child_argv[i] = av_strdup(arg);

                }



                feed->child_argv[i] = av_asprintf("http://%s:%d/%s",

                        (my_http_addr.sin_addr.s_addr == INADDR_ANY) ? "127.0.0.1" :

                    inet_ntoa(my_http_addr.sin_addr),

                    ntohs(my_http_addr.sin_port), feed->filename);

            }

        } else if (!av_strcasecmp(cmd, "ReadOnlyFile")) {

            if (feed) {

                get_arg(feed->feed_filename, sizeof(feed->feed_filename), &p);

                feed->readonly = 1;

            } else if (stream) {

                get_arg(stream->feed_filename, sizeof(stream->feed_filename), &p);

            }

        } else if (!av_strcasecmp(cmd, "File")) {

            if (feed) {

                get_arg(feed->feed_filename, sizeof(feed->feed_filename), &p);

            } else if (stream)

                get_arg(stream->feed_filename, sizeof(stream->feed_filename), &p);

        } else if (!av_strcasecmp(cmd, "Truncate")) {

            if (feed) {

                get_arg(arg, sizeof(arg), &p);

                feed->truncate = strtod(arg, NULL);

            }

        } else if (!av_strcasecmp(cmd, "FileMaxSize")) {

            if (feed) {

                char *p1;

                double fsize;



                get_arg(arg, sizeof(arg), &p);

                p1 = arg;

                fsize = strtod(p1, &p1);

                switch(av_toupper(*p1)) {

                case 'K':

                    fsize *= 1024;

                    break;

                case 'M':

                    fsize *= 1024 * 1024;

                    break;

                case 'G':

                    fsize *= 1024 * 1024 * 1024;

                    break;

                }

                feed->feed_max_size = (int64_t)fsize;

                if (feed->feed_max_size < FFM_PACKET_SIZE*4) {

                    ERROR("Feed max file size is too small, must be at least %d\n", FFM_PACKET_SIZE*4);

                }

            }

        } else if (!av_strcasecmp(cmd, "</Feed>")) {

            if (!feed) {

                ERROR("No corresponding <Feed> for </Feed>\n");

            }

            feed = NULL;

        } else if (!av_strcasecmp(cmd, "<Stream")) {

            /*********************************************/

            /* Stream related options */

            char *q;

            if (stream || feed) {

                ERROR("Already in a tag\n");

            } else {

                FFStream *s;

                stream = av_mallocz(sizeof(FFStream));

                get_arg(stream->filename, sizeof(stream->filename), &p);

                q = strrchr(stream->filename, '>');

                if (q)

                    *q = '\0';



                for (s = first_stream; s; s = s->next) {

                    if (!strcmp(stream->filename, s->filename)) {

                        ERROR("Stream '%s' already registered\n", s->filename);

                    }

                }



                stream->fmt = ffserver_guess_format(NULL, stream->filename, NULL);

                avcodec_get_context_defaults3(&video_enc, NULL);

                avcodec_get_context_defaults3(&audio_enc, NULL);



                audio_id = AV_CODEC_ID_NONE;

                video_id = AV_CODEC_ID_NONE;

                if (stream->fmt) {

                    audio_id = stream->fmt->audio_codec;

                    video_id = stream->fmt->video_codec;

                }



                *last_stream = stream;

                last_stream = &stream->next;

            }

        } else if (!av_strcasecmp(cmd, "Feed")) {

            get_arg(arg, sizeof(arg), &p);

            if (stream) {

                FFStream *sfeed;



                sfeed = first_feed;

                while (sfeed != NULL) {

                    if (!strcmp(sfeed->filename, arg))

                        break;

                    sfeed = sfeed->next_feed;

                }

                if (!sfeed)

                    ERROR("feed '%s' not defined\n", arg);

                else

                    stream->feed = sfeed;

            }

        } else if (!av_strcasecmp(cmd, "Format")) {

            get_arg(arg, sizeof(arg), &p);

            if (stream) {

                if (!strcmp(arg, "status")) {

                    stream->stream_type = STREAM_TYPE_STATUS;

                    stream->fmt = NULL;

                } else {

                    stream->stream_type = STREAM_TYPE_LIVE;

                    /* jpeg cannot be used here, so use single frame jpeg */

                    if (!strcmp(arg, "jpeg"))

                        strcpy(arg, "mjpeg");

                    stream->fmt = ffserver_guess_format(arg, NULL, NULL);

                    if (!stream->fmt) {

                        ERROR("Unknown Format: %s\n", arg);

                    }

                }

                if (stream->fmt) {

                    audio_id = stream->fmt->audio_codec;

                    video_id = stream->fmt->video_codec;

                }

            }

        } else if (!av_strcasecmp(cmd, "InputFormat")) {

            get_arg(arg, sizeof(arg), &p);

            if (stream) {

                stream->ifmt = av_find_input_format(arg);

                if (!stream->ifmt) {

                    ERROR("Unknown input format: %s\n", arg);

                }

            }

        } else if (!av_strcasecmp(cmd, "FaviconURL")) {

            if (stream && stream->stream_type == STREAM_TYPE_STATUS) {

                get_arg(stream->feed_filename, sizeof(stream->feed_filename), &p);

            } else {

                ERROR("FaviconURL only permitted for status streams\n");

            }

        } else if (!av_strcasecmp(cmd, "Author")) {

            if (stream)

                get_arg(stream->author, sizeof(stream->author), &p);

        } else if (!av_strcasecmp(cmd, "Comment")) {

            if (stream)

                get_arg(stream->comment, sizeof(stream->comment), &p);

        } else if (!av_strcasecmp(cmd, "Copyright")) {

            if (stream)

                get_arg(stream->copyright, sizeof(stream->copyright), &p);

        } else if (!av_strcasecmp(cmd, "Title")) {

            if (stream)

                get_arg(stream->title, sizeof(stream->title), &p);

        } else if (!av_strcasecmp(cmd, "Preroll")) {

            get_arg(arg, sizeof(arg), &p);

            if (stream)

                stream->prebuffer = atof(arg) * 1000;

        } else if (!av_strcasecmp(cmd, "StartSendOnKey")) {

            if (stream)

                stream->send_on_key = 1;

        } else if (!av_strcasecmp(cmd, "AudioCodec")) {

            get_arg(arg, sizeof(arg), &p);

            audio_id = opt_codec(arg, AVMEDIA_TYPE_AUDIO);

            if (audio_id == AV_CODEC_ID_NONE) {

                ERROR("Unknown AudioCodec: %s\n", arg);

            }

        } else if (!av_strcasecmp(cmd, "VideoCodec")) {

            get_arg(arg, sizeof(arg), &p);

            video_id = opt_codec(arg, AVMEDIA_TYPE_VIDEO);

            if (video_id == AV_CODEC_ID_NONE) {

                ERROR("Unknown VideoCodec: %s\n", arg);

            }

        } else if (!av_strcasecmp(cmd, "MaxTime")) {

            get_arg(arg, sizeof(arg), &p);

            if (stream)

                stream->max_time = atof(arg) * 1000;

        } else if (!av_strcasecmp(cmd, "AudioBitRate")) {

            get_arg(arg, sizeof(arg), &p);

            if (stream)

                audio_enc.bit_rate = lrintf(atof(arg) * 1000);

        } else if (!av_strcasecmp(cmd, "AudioChannels")) {

            get_arg(arg, sizeof(arg), &p);

            if (stream)

                audio_enc.channels = atoi(arg);

        } else if (!av_strcasecmp(cmd, "AudioSampleRate")) {

            get_arg(arg, sizeof(arg), &p);

            if (stream)

                audio_enc.sample_rate = atoi(arg);

        } else if (!av_strcasecmp(cmd, "AudioQuality")) {

            get_arg(arg, sizeof(arg), &p);

            if (stream) {

//                audio_enc.quality = atof(arg) * 1000;

            }

        } else if (!av_strcasecmp(cmd, "VideoBitRateRange")) {

            if (stream) {

                int minrate, maxrate;



                get_arg(arg, sizeof(arg), &p);



                if (sscanf(arg, "%d-%d", &minrate, &maxrate) == 2) {

                    video_enc.rc_min_rate = minrate * 1000;

                    video_enc.rc_max_rate = maxrate * 1000;

                } else {

                    ERROR("Incorrect format for VideoBitRateRange -- should be <min>-<max>: %s\n", arg);

                }

            }

        } else if (!av_strcasecmp(cmd, "Debug")) {

            if (stream) {

                get_arg(arg, sizeof(arg), &p);

                video_enc.debug = strtol(arg,0,0);

            }

        } else if (!av_strcasecmp(cmd, "Strict")) {

            if (stream) {

                get_arg(arg, sizeof(arg), &p);

                video_enc.strict_std_compliance = atoi(arg);

            }

        } else if (!av_strcasecmp(cmd, "VideoBufferSize")) {

            if (stream) {

                get_arg(arg, sizeof(arg), &p);

                video_enc.rc_buffer_size = atoi(arg) * 8*1024;

            }

        } else if (!av_strcasecmp(cmd, "VideoBitRateTolerance")) {

            if (stream) {

                get_arg(arg, sizeof(arg), &p);

                video_enc.bit_rate_tolerance = atoi(arg) * 1000;

            }

        } else if (!av_strcasecmp(cmd, "VideoBitRate")) {

            get_arg(arg, sizeof(arg), &p);

            if (stream) {

                video_enc.bit_rate = atoi(arg) * 1000;

            }

        } else if (!av_strcasecmp(cmd, "VideoSize")) {

            get_arg(arg, sizeof(arg), &p);

            if (stream) {

                av_parse_video_size(&video_enc.width, &video_enc.height, arg);

                if ((video_enc.width % 16) != 0 ||

                    (video_enc.height % 16) != 0) {

                    ERROR("Image size must be a multiple of 16\n");

                }

            }

        } else if (!av_strcasecmp(cmd, "VideoFrameRate")) {

            get_arg(arg, sizeof(arg), &p);

            if (stream) {

                AVRational frame_rate;

                if (av_parse_video_rate(&frame_rate, arg) < 0) {

                    ERROR("Incorrect frame rate: %s\n", arg);

                } else {

                    video_enc.time_base.num = frame_rate.den;

                    video_enc.time_base.den = frame_rate.num;

                }

            }

        } else if (!av_strcasecmp(cmd, "PixelFormat")) {

            get_arg(arg, sizeof(arg), &p);

            if (stream) {

                video_enc.pix_fmt = av_get_pix_fmt(arg);

                if (video_enc.pix_fmt == AV_PIX_FMT_NONE) {

                    ERROR("Unknown pixel format: %s\n", arg);

                }

            }

        } else if (!av_strcasecmp(cmd, "VideoGopSize")) {

            get_arg(arg, sizeof(arg), &p);

            if (stream)

                video_enc.gop_size = atoi(arg);

        } else if (!av_strcasecmp(cmd, "VideoIntraOnly")) {

            if (stream)

                video_enc.gop_size = 1;

        } else if (!av_strcasecmp(cmd, "VideoHighQuality")) {

            if (stream)

                video_enc.mb_decision = FF_MB_DECISION_BITS;

        } else if (!av_strcasecmp(cmd, "Video4MotionVector")) {

            if (stream) {

                video_enc.mb_decision = FF_MB_DECISION_BITS; //FIXME remove

                video_enc.flags |= CODEC_FLAG_4MV;

            }

        } else if (!av_strcasecmp(cmd, "AVOptionVideo") ||

                   !av_strcasecmp(cmd, "AVOptionAudio")) {

            char arg2[1024];

            AVCodecContext *avctx;

            int type;

            get_arg(arg, sizeof(arg), &p);

            get_arg(arg2, sizeof(arg2), &p);

            if (!av_strcasecmp(cmd, "AVOptionVideo")) {

                avctx = &video_enc;

                type = AV_OPT_FLAG_VIDEO_PARAM;

            } else {

                avctx = &audio_enc;

                type = AV_OPT_FLAG_AUDIO_PARAM;

            }

            if (ffserver_opt_default(arg, arg2, avctx, type|AV_OPT_FLAG_ENCODING_PARAM)) {

                ERROR("Error setting %s option to %s %s\n", cmd, arg, arg2);

            }

        } else if (!av_strcasecmp(cmd, "AVPresetVideo") ||

                   !av_strcasecmp(cmd, "AVPresetAudio")) {

            AVCodecContext *avctx;

            int type;

            get_arg(arg, sizeof(arg), &p);

            if (!av_strcasecmp(cmd, "AVPresetVideo")) {

                avctx = &video_enc;

                video_enc.codec_id = video_id;

                type = AV_OPT_FLAG_VIDEO_PARAM;

            } else {

                avctx = &audio_enc;

                audio_enc.codec_id = audio_id;

                type = AV_OPT_FLAG_AUDIO_PARAM;

            }

            if (ffserver_opt_preset(arg, avctx, type|AV_OPT_FLAG_ENCODING_PARAM, &audio_id, &video_id)) {

                ERROR("AVPreset error: %s\n", arg);

            }

        } else if (!av_strcasecmp(cmd, "VideoTag")) {

            get_arg(arg, sizeof(arg), &p);

            if ((strlen(arg) == 4) && stream)

                video_enc.codec_tag = MKTAG(arg[0], arg[1], arg[2], arg[3]);

        } else if (!av_strcasecmp(cmd, "BitExact")) {

            if (stream)

                video_enc.flags |= CODEC_FLAG_BITEXACT;

        } else if (!av_strcasecmp(cmd, "DctFastint")) {

            if (stream)

                video_enc.dct_algo  = FF_DCT_FASTINT;

        } else if (!av_strcasecmp(cmd, "IdctSimple")) {

            if (stream)

                video_enc.idct_algo = FF_IDCT_SIMPLE;

        } else if (!av_strcasecmp(cmd, "Qscale")) {

            get_arg(arg, sizeof(arg), &p);

            if (stream) {

                video_enc.flags |= CODEC_FLAG_QSCALE;

                video_enc.global_quality = FF_QP2LAMBDA * atoi(arg);

            }

        } else if (!av_strcasecmp(cmd, "VideoQDiff")) {

            get_arg(arg, sizeof(arg), &p);

            if (stream) {

                video_enc.max_qdiff = atoi(arg);

                if (video_enc.max_qdiff < 1 || video_enc.max_qdiff > 31) {

                    ERROR("VideoQDiff out of range\n");

                }

            }

        } else if (!av_strcasecmp(cmd, "VideoQMax")) {

            get_arg(arg, sizeof(arg), &p);

            if (stream) {

                video_enc.qmax = atoi(arg);

                if (video_enc.qmax < 1 || video_enc.qmax > 31) {

                    ERROR("VideoQMax out of range\n");

                }

            }

        } else if (!av_strcasecmp(cmd, "VideoQMin")) {

            get_arg(arg, sizeof(arg), &p);

            if (stream) {

                video_enc.qmin = atoi(arg);

                if (video_enc.qmin < 1 || video_enc.qmin > 31) {

                    ERROR("VideoQMin out of range\n");

                }

            }

        } else if (!av_strcasecmp(cmd, "LumiMask")) {

            get_arg(arg, sizeof(arg), &p);

            if (stream)

                video_enc.lumi_masking = atof(arg);

        } else if (!av_strcasecmp(cmd, "DarkMask")) {

            get_arg(arg, sizeof(arg), &p);

            if (stream)

                video_enc.dark_masking = atof(arg);

        } else if (!av_strcasecmp(cmd, "NoVideo")) {

            video_id = AV_CODEC_ID_NONE;

        } else if (!av_strcasecmp(cmd, "NoAudio")) {

            audio_id = AV_CODEC_ID_NONE;

        } else if (!av_strcasecmp(cmd, "ACL")) {

            parse_acl_row(stream, feed, NULL, p, filename, line_num);

        } else if (!av_strcasecmp(cmd, "DynamicACL")) {

            if (stream) {

                get_arg(stream->dynamic_acl, sizeof(stream->dynamic_acl), &p);

            }

        } else if (!av_strcasecmp(cmd, "RTSPOption")) {

            get_arg(arg, sizeof(arg), &p);

            if (stream) {

                av_freep(&stream->rtsp_option);

                stream->rtsp_option = av_strdup(arg);

            }

        } else if (!av_strcasecmp(cmd, "MulticastAddress")) {

            get_arg(arg, sizeof(arg), &p);

            if (stream) {

                if (resolve_host(&stream->multicast_ip, arg) != 0) {

                    ERROR("Invalid host/IP address: %s\n", arg);

                }

                stream->is_multicast = 1;

                stream->loop = 1; /* default is looping */

            }

        } else if (!av_strcasecmp(cmd, "MulticastPort")) {

            get_arg(arg, sizeof(arg), &p);

            if (stream)

                stream->multicast_port = atoi(arg);

        } else if (!av_strcasecmp(cmd, "MulticastTTL")) {

            get_arg(arg, sizeof(arg), &p);

            if (stream)

                stream->multicast_ttl = atoi(arg);

        } else if (!av_strcasecmp(cmd, "NoLoop")) {

            if (stream)

                stream->loop = 0;

        } else if (!av_strcasecmp(cmd, "</Stream>")) {

            if (!stream) {

                ERROR("No corresponding <Stream> for </Stream>\n");

            } else {

                if (stream->feed && stream->fmt && strcmp(stream->fmt->name, "ffm") != 0) {

                    if (audio_id != AV_CODEC_ID_NONE) {

                        audio_enc.codec_type = AVMEDIA_TYPE_AUDIO;

                        audio_enc.codec_id = audio_id;

                        add_codec(stream, &audio_enc);

                    }

                    if (video_id != AV_CODEC_ID_NONE) {

                        video_enc.codec_type = AVMEDIA_TYPE_VIDEO;

                        video_enc.codec_id = video_id;

                        add_codec(stream, &video_enc);

                    }

                }

                stream = NULL;

            }

        } else if (!av_strcasecmp(cmd, "<Redirect")) {

            /*********************************************/

            char *q;

            if (stream || feed || redirect) {

                ERROR("Already in a tag\n");

            } else {

                redirect = av_mallocz(sizeof(FFStream));

                *last_stream = redirect;

                last_stream = &redirect->next;



                get_arg(redirect->filename, sizeof(redirect->filename), &p);

                q = strrchr(redirect->filename, '>');

                if (*q)

                    *q = '\0';

                redirect->stream_type = STREAM_TYPE_REDIRECT;

            }

        } else if (!av_strcasecmp(cmd, "URL")) {

            if (redirect)

                get_arg(redirect->feed_filename, sizeof(redirect->feed_filename), &p);

        } else if (!av_strcasecmp(cmd, "</Redirect>")) {

            if (!redirect) {

                ERROR("No corresponding <Redirect> for </Redirect>\n");

            } else {

                if (!redirect->feed_filename[0]) {

                    ERROR("No URL found for <Redirect>\n");

                }

                redirect = NULL;

            }

        } else if (!av_strcasecmp(cmd, "LoadModule")) {

            ERROR("Loadable modules no longer supported\n");

        } else {

            ERROR("Incorrect keyword: '%s'\n", cmd);

        }

    }

#undef ERROR



    fclose(f);

    if (errors)

        return -1;

    else

        return 0;

}

static void updateMMXDitherTables(SwsContext *c, int dstY, int lumBufIndex, int chrBufIndex,

                                  int lastInLumBuf, int lastInChrBuf)

{

    const int dstH= c->dstH;

    const int flags= c->flags;

    int16_t **lumPixBuf= c->lumPixBuf;

    int16_t **chrUPixBuf= c->chrUPixBuf;

    int16_t **chrVPixBuf= c->chrVPixBuf;

    int16_t **alpPixBuf= c->alpPixBuf;

    const int vLumBufSize= c->vLumBufSize;

    const int vChrBufSize= c->vChrBufSize;

    int16_t *vLumFilterPos= c->vLumFilterPos;

    int16_t *vChrFilterPos= c->vChrFilterPos;

    int16_t *vLumFilter= c->vLumFilter;

    int16_t *vChrFilter= c->vChrFilter;

    int32_t *lumMmxFilter= c->lumMmxFilter;

    int32_t *chrMmxFilter= c->chrMmxFilter;

    int32_t av_unused *alpMmxFilter= c->alpMmxFilter;

    const int vLumFilterSize= c->vLumFilterSize;

    const int vChrFilterSize= c->vChrFilterSize;

    const int chrDstY= dstY>>c->chrDstVSubSample;

    const int firstLumSrcY= vLumFilterPos[dstY]; //First line needed as input

    const int firstChrSrcY= vChrFilterPos[chrDstY]; //First line needed as input



    c->blueDither= ff_dither8[dstY&1];

    if (c->dstFormat == PIX_FMT_RGB555 || c->dstFormat == PIX_FMT_BGR555)

        c->greenDither= ff_dither8[dstY&1];

    else

        c->greenDither= ff_dither4[dstY&1];

    c->redDither= ff_dither8[(dstY+1)&1];

    if (dstY < dstH - 2) {

        const int16_t **lumSrcPtr= (const int16_t **) lumPixBuf + lumBufIndex + firstLumSrcY - lastInLumBuf + vLumBufSize;

        const int16_t **chrUSrcPtr= (const int16_t **) chrUPixBuf + chrBufIndex + firstChrSrcY - lastInChrBuf + vChrBufSize;

        const int16_t **chrVSrcPtr= (const int16_t **) chrVPixBuf + chrBufIndex + firstChrSrcY - lastInChrBuf + vChrBufSize;

        const int16_t **alpSrcPtr= (CONFIG_SWSCALE_ALPHA && alpPixBuf) ? (const int16_t **) alpPixBuf + lumBufIndex + firstLumSrcY - lastInLumBuf + vLumBufSize : NULL;

        int i;

        if (flags & SWS_ACCURATE_RND) {

            int s= APCK_SIZE / 8;

            for (i=0; i<vLumFilterSize; i+=2) {

                *(const void**)&lumMmxFilter[s*i              ]= lumSrcPtr[i  ];

                *(const void**)&lumMmxFilter[s*i+APCK_PTR2/4  ]= lumSrcPtr[i+(vLumFilterSize>1)];

                lumMmxFilter[s*i+APCK_COEF/4  ]=

                lumMmxFilter[s*i+APCK_COEF/4+1]= vLumFilter[dstY*vLumFilterSize + i    ]

                           + (vLumFilterSize>1 ? vLumFilter[dstY*vLumFilterSize + i + 1]<<16 : 0);

                if (CONFIG_SWSCALE_ALPHA && alpPixBuf) {

                    *(const void**)&alpMmxFilter[s*i              ]= alpSrcPtr[i  ];

                    *(const void**)&alpMmxFilter[s*i+APCK_PTR2/4  ]= alpSrcPtr[i+(vLumFilterSize>1)];

                    alpMmxFilter[s*i+APCK_COEF/4  ]=

                    alpMmxFilter[s*i+APCK_COEF/4+1]= lumMmxFilter[s*i+APCK_COEF/4  ];

                }

            }

            for (i=0; i<vChrFilterSize; i+=2) {

                *(const void**)&chrMmxFilter[s*i              ]= chrUSrcPtr[i  ];

                *(const void**)&chrMmxFilter[s*i+APCK_PTR2/4  ]= chrUSrcPtr[i+(vChrFilterSize>1)];

                chrMmxFilter[s*i+APCK_COEF/4  ]=

                chrMmxFilter[s*i+APCK_COEF/4+1]= vChrFilter[chrDstY*vChrFilterSize + i    ]

                           + (vChrFilterSize>1 ? vChrFilter[chrDstY*vChrFilterSize + i + 1]<<16 : 0);

            }

        } else {

            for (i=0; i<vLumFilterSize; i++) {

                *(const void**)&lumMmxFilter[4*i+0]= lumSrcPtr[i];

                lumMmxFilter[4*i+2]=

                lumMmxFilter[4*i+3]=

                    ((uint16_t)vLumFilter[dstY*vLumFilterSize + i])*0x10001;

                if (CONFIG_SWSCALE_ALPHA && alpPixBuf) {

                    *(const void**)&alpMmxFilter[4*i+0]= alpSrcPtr[i];

                    alpMmxFilter[4*i+2]=

                    alpMmxFilter[4*i+3]= lumMmxFilter[4*i+2];

                }

            }

            for (i=0; i<vChrFilterSize; i++) {

                *(const void**)&chrMmxFilter[4*i+0]= chrUSrcPtr[i];

                chrMmxFilter[4*i+2]=

                chrMmxFilter[4*i+3]=

                    ((uint16_t)vChrFilter[chrDstY*vChrFilterSize + i])*0x10001;

            }

        }

    }

}

static inline int decode_alpha_block(const SHQContext *s, GetBitContext *gb, uint8_t last_alpha[16], uint8_t *dest, int linesize)

{

    uint8_t block[128];

    int i = 0, x, y;



    memset(block, 0, sizeof(block));



    {

        OPEN_READER(re, gb);



        for ( ;; ) {

            int run, level;



            UPDATE_CACHE_LE(re, gb);

            GET_VLC(run, re, gb, ff_dc_alpha_run_vlc_le.table, ALPHA_VLC_BITS, 2);



            if (run == 128) break;

            i += run;

            if (i >= 128)

                return AVERROR_INVALIDDATA;



            UPDATE_CACHE_LE(re, gb);

            GET_VLC(level, re, gb, ff_dc_alpha_level_vlc_le.table, ALPHA_VLC_BITS, 2);

            block[i++] = level;

        }



        CLOSE_READER(re, gb);

    }



    for (y = 0; y < 8; y++) {

        for (x = 0; x < 16; x++) {

            last_alpha[x] -= block[y * 16 + x];

        }

        memcpy(dest, last_alpha, 16);

        dest += linesize;

    }



    return 0;

}

static int dvbsub_read_4bit_string(uint8_t *destbuf, int dbuf_len,

                                   const uint8_t **srcbuf, int buf_size,

                                   int non_mod, uint8_t *map_table)

{

    GetBitContext gb;



    int bits;

    int run_length;

    int pixels_read = 0;



    init_get_bits(&gb, *srcbuf, buf_size << 3);



    while (get_bits_count(&gb) < buf_size << 3 && pixels_read < dbuf_len) {

        bits = get_bits(&gb, 4);



        if (bits) {

            if (non_mod != 1 || bits != 1) {

                if (map_table)

                    *destbuf++ = map_table[bits];

                else

                    *destbuf++ = bits;

            }

            pixels_read++;

        } else {

            bits = get_bits1(&gb);

            if (bits == 0) {

                run_length = get_bits(&gb, 3);



                if (run_length == 0) {

                    (*srcbuf) += (get_bits_count(&gb) + 7) >> 3;

                    return pixels_read;

                }



                run_length += 2;



                if (map_table)

                    bits = map_table[0];

                else

                    bits = 0;



                while (run_length-- > 0 && pixels_read < dbuf_len) {

                    *destbuf++ = bits;

                    pixels_read++;

                }

            } else {

                bits = get_bits1(&gb);

                if (bits == 0) {

                    run_length = get_bits(&gb, 2) + 4;

                    bits = get_bits(&gb, 4);



                    if (non_mod == 1 && bits == 1)

                        pixels_read += run_length;

                    else {

                        if (map_table)

                            bits = map_table[bits];

                        while (run_length-- > 0 && pixels_read < dbuf_len) {

                            *destbuf++ = bits;

                            pixels_read++;

                        }

                    }

                } else {

                    bits = get_bits(&gb, 2);

                    if (bits == 2) {

                        run_length = get_bits(&gb, 4) + 9;

                        bits = get_bits(&gb, 4);



                        if (non_mod == 1 && bits == 1)

                            pixels_read += run_length;

                        else {

                            if (map_table)

                                bits = map_table[bits];

                            while (run_length-- > 0 && pixels_read < dbuf_len) {

                                *destbuf++ = bits;

                                pixels_read++;

                            }

                        }

                    } else if (bits == 3) {

                        run_length = get_bits(&gb, 8) + 25;

                        bits = get_bits(&gb, 4);



                        if (non_mod == 1 && bits == 1)

                            pixels_read += run_length;

                        else {

                            if (map_table)

                                bits = map_table[bits];

                            while (run_length-- > 0 && pixels_read < dbuf_len) {

                                *destbuf++ = bits;

                                pixels_read++;

                            }

                        }

                    } else if (bits == 1) {

                        pixels_read += 2;

                        if (map_table)

                            bits = map_table[0];

                        else

                            bits = 0;

                        if (pixels_read <= dbuf_len) {

                            *destbuf++ = bits;

                            *destbuf++ = bits;

                        }

                    } else {

                        if (map_table)

                            bits = map_table[0];

                        else

                            bits = 0;

                        *destbuf++ = bits;

                        pixels_read ++;

                    }

                }

            }

        }

    }



    if (get_bits(&gb, 8))

        av_log(0, AV_LOG_ERROR, "DVBSub error: line overflow\n");



    (*srcbuf) += (get_bits_count(&gb) + 7) >> 3;



    return pixels_read;

}

static void copy_block(uint16_t *pdest, uint16_t *psrc, int block_size, int pitch)

{

    int y;



    for (y = 0; y != block_size; y++, pdest += pitch, psrc += pitch)

        memcpy(pdest, psrc, block_size * sizeof(pdest[0]));

}

static int ffm2_read_header(AVFormatContext *s)

{

    FFMContext *ffm = s->priv_data;

    AVStream *st;

    AVIOContext *pb = s->pb;

    AVCodecContext *codec, *dummy_codec = NULL;

    AVCodecParameters *codecpar;

    const AVCodecDescriptor *codec_desc;

    int ret;

    int f_main = 0, f_cprv = -1, f_stvi = -1, f_stau = -1;

    AVCodec *enc;

    char *buffer;



    ffm->packet_size = avio_rb32(pb);

    if (ffm->packet_size != FFM_PACKET_SIZE) {

        av_log(s, AV_LOG_ERROR, "Invalid packet size %d, expected size was %d\n",

               ffm->packet_size, FFM_PACKET_SIZE);

        ret = AVERROR_INVALIDDATA;

        goto fail;

    }



    ffm->write_index = avio_rb64(pb);

    /* get also filesize */

    if (pb->seekable) {

        ffm->file_size = avio_size(pb);

        if (ffm->write_index && 0)

            adjust_write_index(s);

    } else {

        ffm->file_size = (UINT64_C(1) << 63) - 1;

    }

    dummy_codec = avcodec_alloc_context3(NULL);



    while(!avio_feof(pb)) {

        unsigned id = avio_rb32(pb);

        unsigned size = avio_rb32(pb);

        int64_t next = avio_tell(pb) + size;

        char rc_eq_buf[128];



        if(!id)

            break;



        switch(id) {

        case MKBETAG('M', 'A', 'I', 'N'):

            if (f_main++) {

                ret = AVERROR(EINVAL);

                goto fail;

            }

            avio_rb32(pb); /* nb_streams */

            avio_rb32(pb); /* total bitrate */

            break;

        case MKBETAG('C', 'O', 'M', 'M'):

            f_cprv = f_stvi = f_stau = 0;

            st = avformat_new_stream(s, NULL);

            if (!st) {

                ret = AVERROR(ENOMEM);

                goto fail;

            }



            avpriv_set_pts_info(st, 64, 1, 1000000);



            codec = st->codec;

            codecpar = st->codecpar;

            /* generic info */

            codecpar->codec_id = avio_rb32(pb);

            codec_desc = avcodec_descriptor_get(codecpar->codec_id);

            if (!codec_desc) {

                av_log(s, AV_LOG_ERROR, "Invalid codec id: %d\n", codecpar->codec_id);

                codecpar->codec_id = AV_CODEC_ID_NONE;

                ret = AVERROR_INVALIDDATA;

                goto fail;

            }

            codecpar->codec_type = avio_r8(pb);

            if (codecpar->codec_type != codec_desc->type) {

                av_log(s, AV_LOG_ERROR, "Codec type mismatch: expected %d, found %d\n",

                       codec_desc->type, codecpar->codec_type);

                codecpar->codec_id = AV_CODEC_ID_NONE;

                codecpar->codec_type = AVMEDIA_TYPE_UNKNOWN;

                ret = AVERROR_INVALIDDATA;

                goto fail;

            }

            codecpar->bit_rate = avio_rb32(pb);

            if (codecpar->bit_rate < 0) {

                av_log(codec, AV_LOG_ERROR, "Invalid bit rate %"PRId64"\n", codecpar->bit_rate);

                ret = AVERROR_INVALIDDATA;

                goto fail;

            }

            codec->flags = avio_rb32(pb);

            codec->flags2 = avio_rb32(pb);

            codec->debug = avio_rb32(pb);

            if (codec->flags & AV_CODEC_FLAG_GLOBAL_HEADER) {

                int size = avio_rb32(pb);

                if (size < 0 || size >= FF_MAX_EXTRADATA_SIZE) {

                    av_log(s, AV_LOG_ERROR, "Invalid extradata size %d\n", size);

                    ret = AVERROR_INVALIDDATA;

                    goto fail;

                }

                codecpar->extradata = av_mallocz(size + AV_INPUT_BUFFER_PADDING_SIZE);

                if (!codecpar->extradata)

                    return AVERROR(ENOMEM);

                codecpar->extradata_size = size;

                avio_read(pb, codecpar->extradata, size);

            }

            break;

        case MKBETAG('S', 'T', 'V', 'I'):

            if (f_stvi++) {

                ret = AVERROR(EINVAL);

                goto fail;

            }

            codec->time_base.num = avio_rb32(pb);

            codec->time_base.den = avio_rb32(pb);

            if (codec->time_base.num <= 0 || codec->time_base.den <= 0) {

                av_log(s, AV_LOG_ERROR, "Invalid time base %d/%d\n",

                       codec->time_base.num, codec->time_base.den);

                ret = AVERROR_INVALIDDATA;

                goto fail;

            }

            codecpar->width = avio_rb16(pb);

            codecpar->height = avio_rb16(pb);

            ret = av_image_check_size(codecpar->width, codecpar->height, 0, s);

            if (ret < 0)

                goto fail;

            avio_rb16(pb); // gop_size

            codecpar->format = avio_rb32(pb);

            if (!av_pix_fmt_desc_get(codecpar->format)) {

                av_log(s, AV_LOG_ERROR, "Invalid pix fmt id: %d\n", codecpar->format);

                codecpar->format = AV_PIX_FMT_NONE;

                goto fail;

            }

            avio_r8(pb);   // qmin

            avio_r8(pb);   // qmax

            avio_r8(pb);   // max_qdiff

            avio_rb16(pb); // qcompress / 10000.0

            avio_rb16(pb); // qblur / 10000.0

            avio_rb32(pb); // bit_rate_tolerance

            avio_get_str(pb, INT_MAX, rc_eq_buf, sizeof(rc_eq_buf));



            avio_rb32(pb); // rc_max_rate

            avio_rb32(pb); // rc_min_rate

            avio_rb32(pb); // rc_buffer_size

            avio_rb64(pb); // i_quant_factor

            avio_rb64(pb); // b_quant_factor

            avio_rb64(pb); // i_quant_offset

            avio_rb64(pb); // b_quant_offset

            avio_rb32(pb); // dct_algo

            avio_rb32(pb); // strict_std_compliance

            avio_rb32(pb); // max_b_frames

            avio_rb32(pb); // mpeg_quant

            avio_rb32(pb); // intra_dc_precision

            avio_rb32(pb); // me_method

            avio_rb32(pb); // mb_decision

            avio_rb32(pb); // nsse_weight

            avio_rb32(pb); // frame_skip_cmp

            avio_rb64(pb); // rc_buffer_aggressivity

            codecpar->codec_tag = avio_rb32(pb);

            avio_r8(pb);   // thread_count

            avio_rb32(pb); // coder_type

            avio_rb32(pb); // me_cmp

            avio_rb32(pb); // me_subpel_quality

            avio_rb32(pb); // me_range

            avio_rb32(pb); // keyint_min

            avio_rb32(pb); // scenechange_threshold

            avio_rb32(pb); // b_frame_strategy

            avio_rb64(pb); // qcompress

            avio_rb64(pb); // qblur

            avio_rb32(pb); // max_qdiff

            avio_rb32(pb); // refs

            break;

        case MKBETAG('S', 'T', 'A', 'U'):

            if (f_stau++) {

                ret = AVERROR(EINVAL);

                goto fail;

            }

            codecpar->sample_rate = avio_rb32(pb);

            VALIDATE_PARAMETER(sample_rate, "sample rate",        codecpar->sample_rate < 0)

            codecpar->channels = avio_rl16(pb);

            VALIDATE_PARAMETER(channels,    "number of channels", codecpar->channels < 0)

            codecpar->frame_size = avio_rl16(pb);

            VALIDATE_PARAMETER(frame_size,  "frame size",         codecpar->frame_size < 0)

            break;

        case MKBETAG('C', 'P', 'R', 'V'):

            if (f_cprv++) {

                ret = AVERROR(EINVAL);

                goto fail;

            }

            enc = avcodec_find_encoder(codecpar->codec_id);

            if (enc && enc->priv_data_size && enc->priv_class) {

                buffer = av_malloc(size + 1);

                if (!buffer) {

                    ret = AVERROR(ENOMEM);

                    goto fail;

                }

                avio_get_str(pb, size, buffer, size + 1);

                if ((ret = ffm_append_recommended_configuration(st, &buffer)) < 0)

                    goto fail;

            }

            break;

        case MKBETAG('S', '2', 'V', 'I'):

            if (f_stvi++ || !size) {

                ret = AVERROR(EINVAL);

                goto fail;

            }

            buffer = av_malloc(size);

            if (!buffer) {

                ret = AVERROR(ENOMEM);

                goto fail;

            }

            avio_get_str(pb, INT_MAX, buffer, size);

            // The lack of AVOptions support in AVCodecParameters makes this back and forth copying needed

            avcodec_parameters_to_context(dummy_codec, codecpar);

            av_set_options_string(dummy_codec, buffer, "=", ",");

            avcodec_parameters_from_context(codecpar, dummy_codec);

            if ((ret = ffm_append_recommended_configuration(st, &buffer)) < 0)

                goto fail;

            break;

        case MKBETAG('S', '2', 'A', 'U'):

            if (f_stau++ || !size) {

                ret = AVERROR(EINVAL);

                goto fail;

            }

            buffer = av_malloc(size);

            if (!buffer) {

                ret = AVERROR(ENOMEM);

                goto fail;

            }

            avio_get_str(pb, INT_MAX, buffer, size);

            // The lack of AVOptions support in AVCodecParameters makes this back and forth copying needed

            avcodec_parameters_to_context(dummy_codec, codecpar);

            av_set_options_string(dummy_codec, buffer, "=", ",");

            avcodec_parameters_from_context(codecpar, dummy_codec);

            if ((ret = ffm_append_recommended_configuration(st, &buffer)) < 0)

                goto fail;

            break;

        }

        avio_seek(pb, next, SEEK_SET);

    }



    /* get until end of block reached */

    while ((avio_tell(pb) % ffm->packet_size) != 0 && !pb->eof_reached)

        avio_r8(pb);



    /* init packet demux */

    ffm->packet_ptr = ffm->packet;

    ffm->packet_end = ffm->packet;

    ffm->frame_offset = 0;

    ffm->dts = 0;

    ffm->read_state = READ_HEADER;

    ffm->first_packet = 1;

    avcodec_free_context(&dummy_codec);

    return 0;

 fail:

    avcodec_free_context(&dummy_codec);

    return ret;

}

static double get_audio_clock(VideoState *is)

{

    double pts;

    int hw_buf_size, bytes_per_sec;

    pts = is->audio_clock;

    hw_buf_size = audio_write_get_buf_size(is);

    bytes_per_sec = 0;

    if (is->audio_st) {

        bytes_per_sec = is->audio_st->codec->sample_rate *

                        2 * is->audio_st->codec->channels;

    }

    if (bytes_per_sec)

        pts -= (double)hw_buf_size / bytes_per_sec;

    return pts;

}

uint8_t *ff_stream_new_side_data(AVStream *st, enum AVPacketSideDataType type,

                                 int size)

{

    AVPacketSideData *sd, *tmp;

    int i;

    uint8_t *data = av_malloc(size);



    if (!data)

        return NULL;



    for (i = 0; i < st->nb_side_data; i++) {

        sd = &st->side_data[i];



        if (sd->type == type) {

            av_freep(&sd->data);

            sd->data = data;

            sd->size = size;

            return sd->data;

        }

    }



    tmp = av_realloc_array(st->side_data, st->nb_side_data + 1, sizeof(*tmp));

    if (!tmp) {

        av_freep(&data);

        return NULL;

    }



    st->side_data = tmp;

    st->nb_side_data++;



    sd = &st->side_data[st->nb_side_data - 1];

    sd->type = type;

    sd->data = data;

    sd->size = size;

    return data;

}

static int adts_write_packet(AVFormatContext *s, AVPacket *pkt)

{

    ADTSContext *adts = s->priv_data;

    AVIOContext *pb = s->pb;

    uint8_t buf[ADTS_HEADER_SIZE];



    if (!pkt->size)

        return 0;

    if (adts->write_adts) {

        ff_adts_write_frame_header(adts, buf, pkt->size, adts->pce_size);

        avio_write(pb, buf, ADTS_HEADER_SIZE);

        if (adts->pce_size) {

            avio_write(pb, adts->pce_data, adts->pce_size);

            adts->pce_size = 0;

        }

    }

    avio_write(pb, pkt->data, pkt->size);

    avio_flush(pb);



    return 0;

}

static int parse_optional_info(DCACoreDecoder *s)

{

    DCAContext *dca = s->avctx->priv_data;

    int ret = -1;



    // Time code stamp

    if (s->ts_present)

        skip_bits_long(&s->gb, 32);



    // Auxiliary data

    if (s->aux_present && (ret = parse_aux_data(s)) < 0

        && (s->avctx->err_recognition & AV_EF_EXPLODE))

        return ret;



    if (ret < 0)

        s->prim_dmix_embedded = 0;



    // Core extensions

    if (s->ext_audio_present && !dca->core_only) {

        int sync_pos = FFMIN(s->frame_size / 4, s->gb.size_in_bits / 32) - 1;

        int last_pos = get_bits_count(&s->gb) / 32;

        int size, dist;



        // Search for extension sync words aligned on 4-byte boundary. Search

        // must be done backwards from the end of core frame to work around

        // sync word aliasing issues.

        switch (s->ext_audio_type) {

        case EXT_AUDIO_XCH:

            if (dca->request_channel_layout)

                break;



            // The distance between XCH sync word and end of the core frame

            // must be equal to XCH frame size. Off by one error is allowed for

            // compatibility with legacy bitstreams. Minimum XCH frame size is

            // 96 bytes. AMODE and PCHS are further checked to reduce

            // probability of alias sync detection.

            for (; sync_pos >= last_pos; sync_pos--) {

                if (AV_RB32(s->gb.buffer + sync_pos * 4) == DCA_SYNCWORD_XCH) {

                    s->gb.index = (sync_pos + 1) * 32;

                    size = get_bits(&s->gb, 10) + 1;

                    dist = s->frame_size - sync_pos * 4;

                    if (size >= 96

                        && (size == dist || size - 1 == dist)

                        && get_bits(&s->gb, 7) == 0x08) {

                        s->xch_pos = get_bits_count(&s->gb);

                        break;

                    }

                }

            }



            if (s->avctx->err_recognition & AV_EF_EXPLODE) {

                av_log(s->avctx, AV_LOG_ERROR, "XCH sync word not found\n");

                return AVERROR_INVALIDDATA;

            }

            break;



        case EXT_AUDIO_X96:

            // The distance between X96 sync word and end of the core frame

            // must be equal to X96 frame size. Minimum X96 frame size is 96

            // bytes.

            for (; sync_pos >= last_pos; sync_pos--) {

                if (AV_RB32(s->gb.buffer + sync_pos * 4) == DCA_SYNCWORD_X96) {

                    s->gb.index = (sync_pos + 1) * 32;

                    size = get_bits(&s->gb, 12) + 1;

                    dist = s->frame_size - sync_pos * 4;

                    if (size >= 96 && size == dist) {

                        s->x96_pos = get_bits_count(&s->gb);

                        break;

                    }

                }

            }



            if (s->avctx->err_recognition & AV_EF_EXPLODE) {

                av_log(s->avctx, AV_LOG_ERROR, "X96 sync word not found\n");

                return AVERROR_INVALIDDATA;

            }

            break;



        case EXT_AUDIO_XXCH:

            if (dca->request_channel_layout)

                break;



            // XXCH frame header CRC must be valid. Minimum XXCH frame header

            // size is 11 bytes.

            for (; sync_pos >= last_pos; sync_pos--) {

                if (AV_RB32(s->gb.buffer + sync_pos * 4) == DCA_SYNCWORD_XXCH) {

                    s->gb.index = (sync_pos + 1) * 32;

                    size = get_bits(&s->gb, 6) + 1;

                    if (size >= 11 &&

                        !ff_dca_check_crc(&s->gb, (sync_pos + 1) * 32,

                                          sync_pos * 32 + size * 8)) {

                        s->xxch_pos = sync_pos * 32;

                        break;

                    }

                }

            }



            if (s->avctx->err_recognition & AV_EF_EXPLODE) {

                av_log(s->avctx, AV_LOG_ERROR, "XXCH sync word not found\n");

                return AVERROR_INVALIDDATA;

            }

            break;

        }

    }



    return 0;

}

static void generate_silence(uint8_t* buf, enum AVSampleFormat sample_fmt, size_t size)

{

