}

static void get_tag(AVFormatContext *s, const char *key, int type, int len, int type2_size)

{

    char *value;

    int64_t off = avio_tell(s->pb);



    if ((unsigned)len >= (UINT_MAX - 1) / 2)

        return;



    value = av_malloc(2 * len + 1);

    if (!value)

        goto finish;



    if (type == 0) {         // UTF16-LE

        avio_get_str16le(s->pb, len, value, 2 * len + 1);

    } else if (type == -1) { // ASCII

        avio_read(s->pb, value, len);

        value[len]=0;

    } else if (type == 1) {  // byte array

        if (!strcmp(key, "WM/Picture")) { // handle cover art

            asf_read_picture(s, len);

        } else if (!strcmp(key, "ID3")) { // handle ID3 tag

            get_id3_tag(s, len);

        } else {

            av_log(s, AV_LOG_VERBOSE, "Unsupported byte array in tag %s.\n", key);

        }

        goto finish;

    } else if (type > 1 && type <= 5) {  // boolean or DWORD or QWORD or WORD

        uint64_t num = get_value(s->pb, type, type2_size);

        snprintf(value, len, "%"PRIu64, num);

    } else if (type == 6) { // (don't) handle GUID

        av_log(s, AV_LOG_DEBUG, "Unsupported GUID value in tag %s.\n", key);

        goto finish;

    } else {

        av_log(s, AV_LOG_DEBUG,

               "Unsupported value type %d in tag %s.\n", type, key);

        goto finish;

    }

    if (*value)

        av_dict_set(&s->metadata, key, value, 0);



finish:

    av_freep(&value);

    avio_seek(s->pb, off + len, SEEK_SET);

}

av_cold int ff_yuv2rgb_c_init_tables(SwsContext *c, const int inv_table[4], int fullRange,

                                     int brightness, int contrast, int saturation)

{

    const int isRgb =      c->dstFormat==PIX_FMT_RGB32

                        || c->dstFormat==PIX_FMT_RGB32_1

                        || c->dstFormat==PIX_FMT_BGR24

                        || c->dstFormat==PIX_FMT_RGB565BE

                        || c->dstFormat==PIX_FMT_RGB565LE

                        || c->dstFormat==PIX_FMT_RGB555BE

                        || c->dstFormat==PIX_FMT_RGB555LE

                        || c->dstFormat==PIX_FMT_RGB444BE

                        || c->dstFormat==PIX_FMT_RGB444LE

                        || c->dstFormat==PIX_FMT_RGB8

                        || c->dstFormat==PIX_FMT_RGB4

                        || c->dstFormat==PIX_FMT_RGB4_BYTE

                        || c->dstFormat==PIX_FMT_MONOBLACK;

    const int isNotNe =    c->dstFormat==PIX_FMT_NE(RGB565LE,RGB565BE)

                        || c->dstFormat==PIX_FMT_NE(RGB555LE,RGB555BE)

                        || c->dstFormat==PIX_FMT_NE(RGB444LE,RGB444BE)

                        || c->dstFormat==PIX_FMT_NE(BGR565LE,BGR565BE)

                        || c->dstFormat==PIX_FMT_NE(BGR555LE,BGR555BE)

                        || c->dstFormat==PIX_FMT_NE(BGR444LE,BGR444BE);

    const int bpp = c->dstFormatBpp;

    uint8_t *y_table;

    uint16_t *y_table16;

    uint32_t *y_table32;

    int i, base, rbase, gbase, bbase, abase, needAlpha;

    const int yoffs = fullRange ? 384 : 326;



    int64_t crv =  inv_table[0];

    int64_t cbu =  inv_table[1];

    int64_t cgu = -inv_table[2];

    int64_t cgv = -inv_table[3];

    int64_t cy  = 1<<16;

    int64_t oy  = 0;



    int64_t yb = 0;



    if (!fullRange) {

        cy = (cy*255) / 219;

        oy = 16<<16;

    } else {

        crv = (crv*224) / 255;

        cbu = (cbu*224) / 255;

        cgu = (cgu*224) / 255;

        cgv = (cgv*224) / 255;

    }



    cy  = (cy *contrast             ) >> 16;

    crv = (crv*contrast * saturation) >> 32;

    cbu = (cbu*contrast * saturation) >> 32;

    cgu = (cgu*contrast * saturation) >> 32;

    cgv = (cgv*contrast * saturation) >> 32;

    oy -= 256*brightness;



    c->uOffset=   0x0400040004000400LL;

    c->vOffset=   0x0400040004000400LL;

    c->yCoeff=    roundToInt16(cy *8192) * 0x0001000100010001ULL;

    c->vrCoeff=   roundToInt16(crv*8192) * 0x0001000100010001ULL;

    c->ubCoeff=   roundToInt16(cbu*8192) * 0x0001000100010001ULL;

    c->vgCoeff=   roundToInt16(cgv*8192) * 0x0001000100010001ULL;

    c->ugCoeff=   roundToInt16(cgu*8192) * 0x0001000100010001ULL;

    c->yOffset=   roundToInt16(oy *   8) * 0x0001000100010001ULL;



    c->yuv2rgb_y_coeff  = (int16_t)roundToInt16(cy <<13);

    c->yuv2rgb_y_offset = (int16_t)roundToInt16(oy << 9);

    c->yuv2rgb_v2r_coeff= (int16_t)roundToInt16(crv<<13);

    c->yuv2rgb_v2g_coeff= (int16_t)roundToInt16(cgv<<13);

    c->yuv2rgb_u2g_coeff= (int16_t)roundToInt16(cgu<<13);

    c->yuv2rgb_u2b_coeff= (int16_t)roundToInt16(cbu<<13);



    //scale coefficients by cy

    crv = ((crv << 16) + 0x8000) / cy;

    cbu = ((cbu << 16) + 0x8000) / cy;

    cgu = ((cgu << 16) + 0x8000) / cy;

    cgv = ((cgv << 16) + 0x8000) / cy;



    av_free(c->yuvTable);



    switch (bpp) {

    case 1:

        c->yuvTable = av_malloc(1024);

        y_table = c->yuvTable;

        yb = -(384<<16) - oy;

        for (i = 0; i < 1024-110; i++) {

            y_table[i+110] = av_clip_uint8((yb + 0x8000) >> 16) >> 7;

            yb += cy;

        }

        fill_table(c->table_gU, 1, cgu, y_table + yoffs);

        fill_gv_table(c->table_gV, 1, cgv);

        break;

    case 4:

    case 4|128:

        rbase = isRgb ? 3 : 0;

        gbase = 1;

        bbase = isRgb ? 0 : 3;

        c->yuvTable = av_malloc(1024*3);

        y_table = c->yuvTable;

        yb = -(384<<16) - oy;

        for (i = 0; i < 1024-110; i++) {

            int yval = av_clip_uint8((yb + 0x8000) >> 16);

            y_table[i+110     ] =  (yval >> 7)       << rbase;

            y_table[i+ 37+1024] = ((yval + 43) / 85) << gbase;

            y_table[i+110+2048] =  (yval >> 7)       << bbase;

            yb += cy;

        }

        fill_table(c->table_rV, 1, crv, y_table + yoffs);

        fill_table(c->table_gU, 1, cgu, y_table + yoffs + 1024);

        fill_table(c->table_bU, 1, cbu, y_table + yoffs + 2048);

        fill_gv_table(c->table_gV, 1, cgv);

        break;

    case 8:

        rbase = isRgb ? 5 : 0;

        gbase = isRgb ? 2 : 3;

        bbase = isRgb ? 0 : 6;

        c->yuvTable = av_malloc(1024*3);

        y_table = c->yuvTable;

        yb = -(384<<16) - oy;

        for (i = 0; i < 1024-38; i++) {

            int yval = av_clip_uint8((yb + 0x8000) >> 16);

            y_table[i+16     ] = ((yval + 18) / 36) << rbase;

            y_table[i+16+1024] = ((yval + 18) / 36) << gbase;

            y_table[i+37+2048] = ((yval + 43) / 85) << bbase;

            yb += cy;

        }

        fill_table(c->table_rV, 1, crv, y_table + yoffs);

        fill_table(c->table_gU, 1, cgu, y_table + yoffs + 1024);

        fill_table(c->table_bU, 1, cbu, y_table + yoffs + 2048);

        fill_gv_table(c->table_gV, 1, cgv);

        break;

    case 12:

        rbase = isRgb ? 8 : 0;

        gbase = 4;

        bbase = isRgb ? 0 : 8;

        c->yuvTable = av_malloc(1024*3*2);

        y_table16 = c->yuvTable;

        yb = -(384<<16) - oy;

        for (i = 0; i < 1024; i++) {

            uint8_t yval = av_clip_uint8((yb + 0x8000) >> 16);

            y_table16[i     ] = (yval >> 4) << rbase;

            y_table16[i+1024] = (yval >> 4) << gbase;

            y_table16[i+2048] = (yval >> 4) << bbase;

            yb += cy;

        }

        if (isNotNe)

            for (i = 0; i < 1024*3; i++)

                y_table16[i] = av_bswap16(y_table16[i]);

        fill_table(c->table_rV, 2, crv, y_table16 + yoffs);

        fill_table(c->table_gU, 2, cgu, y_table16 + yoffs + 1024);

        fill_table(c->table_bU, 2, cbu, y_table16 + yoffs + 2048);

        fill_gv_table(c->table_gV, 2, cgv);

        break;

    case 15:

    case 16:

        rbase = isRgb ? bpp - 5 : 0;

        gbase = 5;

        bbase = isRgb ? 0 : (bpp - 5);

        c->yuvTable = av_malloc(1024*3*2);

        y_table16 = c->yuvTable;

        yb = -(384<<16) - oy;

        for (i = 0; i < 1024; i++) {

            uint8_t yval = av_clip_uint8((yb + 0x8000) >> 16);

            y_table16[i     ] = (yval >> 3)          << rbase;

            y_table16[i+1024] = (yval >> (18 - bpp)) << gbase;

            y_table16[i+2048] = (yval >> 3)          << bbase;

            yb += cy;

        }

        if(isNotNe)

            for (i = 0; i < 1024*3; i++)

                y_table16[i] = av_bswap16(y_table16[i]);

        fill_table(c->table_rV, 2, crv, y_table16 + yoffs);

        fill_table(c->table_gU, 2, cgu, y_table16 + yoffs + 1024);

        fill_table(c->table_bU, 2, cbu, y_table16 + yoffs + 2048);

        fill_gv_table(c->table_gV, 2, cgv);

        break;

    case 24:

    case 48:

        c->yuvTable = av_malloc(1024);

        y_table = c->yuvTable;

        yb = -(384<<16) - oy;

        for (i = 0; i < 1024; i++) {

            y_table[i] = av_clip_uint8((yb + 0x8000) >> 16);

            yb += cy;

        }

        fill_table(c->table_rV, 1, crv, y_table + yoffs);

        fill_table(c->table_gU, 1, cgu, y_table + yoffs);

        fill_table(c->table_bU, 1, cbu, y_table + yoffs);

        fill_gv_table(c->table_gV, 1, cgv);

        break;

    case 32:

        base = (c->dstFormat == PIX_FMT_RGB32_1 || c->dstFormat == PIX_FMT_BGR32_1) ? 8 : 0;

        rbase = base + (isRgb ? 16 : 0);

        gbase = base + 8;

        bbase = base + (isRgb ? 0 : 16);

        needAlpha = CONFIG_SWSCALE_ALPHA && isALPHA(c->srcFormat);

        if (!needAlpha)

            abase = (base + 24) & 31;

        c->yuvTable = av_malloc(1024*3*4);

        y_table32 = c->yuvTable;

        yb = -(384<<16) - oy;

        for (i = 0; i < 1024; i++) {

            unsigned yval = av_clip_uint8((yb + 0x8000) >> 16);

            y_table32[i     ] = (yval << rbase) + (needAlpha ? 0 : (255u << abase));

            y_table32[i+1024] = yval << gbase;

            y_table32[i+2048] = yval << bbase;

            yb += cy;

        }

        fill_table(c->table_rV, 4, crv, y_table32 + yoffs);

        fill_table(c->table_gU, 4, cgu, y_table32 + yoffs + 1024);

        fill_table(c->table_bU, 4, cbu, y_table32 + yoffs + 2048);

        fill_gv_table(c->table_gV, 4, cgv);

        break;

    default:

        c->yuvTable = NULL;

        av_log(c, AV_LOG_ERROR, "%ibpp not supported by yuv2rgb\n", bpp);

        return -1;

    }

    return 0;

}

static int config_input_ref(AVFilterLink *inlink)

{

    const AVPixFmtDescriptor *desc = av_pix_fmt_desc_get(inlink->format);

    AVFilterContext *ctx  = inlink->dst;

    PSNRContext *s = ctx->priv;

    unsigned sum;

    int j;



    s->nb_components = desc->nb_components;

    if (ctx->inputs[0]->w != ctx->inputs[1]->w ||

        ctx->inputs[0]->h != ctx->inputs[1]->h) {

        av_log(ctx, AV_LOG_ERROR, "Width and height of input videos must be same.\n");

        return AVERROR(EINVAL);

    }

    if (ctx->inputs[0]->format != ctx->inputs[1]->format) {

        av_log(ctx, AV_LOG_ERROR, "Inputs must be of same pixel format.\n");

        return AVERROR(EINVAL);

    }



    s->max[0] = (1 << (desc->comp[0].depth_minus1 + 1)) - 1;

    s->max[1] = (1 << (desc->comp[1].depth_minus1 + 1)) - 1;

    s->max[2] = (1 << (desc->comp[2].depth_minus1 + 1)) - 1;

    s->max[3] = (1 << (desc->comp[3].depth_minus1 + 1)) - 1;



    s->is_rgb = ff_fill_rgba_map(s->rgba_map, inlink->format) >= 0;

    s->comps[0] = s->is_rgb ? 'r' : 'y' ;

    s->comps[1] = s->is_rgb ? 'g' : 'u' ;

    s->comps[2] = s->is_rgb ? 'b' : 'v' ;

    s->comps[3] = 'a';



    s->planeheight[1] = s->planeheight[2] = FF_CEIL_RSHIFT(inlink->h, desc->log2_chroma_h);

    s->planeheight[0] = s->planeheight[3] = inlink->h;

    s->planewidth[1]  = s->planewidth[2]  = FF_CEIL_RSHIFT(inlink->w, desc->log2_chroma_w);

    s->planewidth[0]  = s->planewidth[3]  = inlink->w;

    sum = 0;

    for (j = 0; j < s->nb_components; j++)

        sum += s->planeheight[j] * s->planewidth[j];

    for (j = 0; j < s->nb_components; j++) {

        s->planeweight[j] = (double) s->planeheight[j] * s->planewidth[j] / sum;

        s->average_max += s->max[j] * s->planeweight[j];

    }



    s->compute_mse = desc->comp[0].depth_minus1 > 7 ? compute_images_mse_16bit : compute_images_mse;



    return 0;

}

int dv_produce_packet(DVDemuxContext *c, AVPacket *pkt,

                      uint8_t* buf, int buf_size)

{

    int size, i;

    uint8_t *ppcm[4] = {0};



    if (buf_size < DV_PROFILE_BYTES ||

        !(c->sys = dv_frame_profile(buf)) ||

        buf_size < c->sys->frame_size) {

          return -1;   /* Broken frame, or not enough data */

    }



    /* Queueing audio packet */

    /* FIXME: in case of no audio/bad audio we have to do something */

    size = dv_extract_audio_info(c, buf);

    for (i = 0; i < c->ach; i++) {

       c->audio_pkt[i].size = size;

       c->audio_pkt[i].pts  = c->abytes * 30000*8 / c->ast[i]->codec->bit_rate;

       ppcm[i] = c->audio_buf[i];

    }

    dv_extract_audio(buf, ppcm, c->sys);

    c->abytes += size;



    /* We work with 720p frames split in half, thus even frames have

     * channels 0,1 and odd 2,3. */

    if (c->sys->height == 720) {

        if (buf[1] & 0x0C)

            c->audio_pkt[2].size = c->audio_pkt[3].size = 0;

        else

            c->audio_pkt[0].size = c->audio_pkt[1].size = 0;

    }



    /* Now it's time to return video packet */

    size = dv_extract_video_info(c, buf);

    av_init_packet(pkt);

    pkt->data         = buf;

    pkt->size         = size;

    pkt->flags       |= PKT_FLAG_KEY;

    pkt->stream_index = c->vst->id;

    pkt->pts          = c->frames;



    c->frames++;



    return size;

}

