static int hls_decode_entry_wpp(AVCodecContext *avctxt, void *input_ctb_row, int job, int self_id)

{

    HEVCContext *s1  = avctxt->priv_data, *s;

    HEVCLocalContext *lc;

    int ctb_size    = 1<< s1->ps.sps->log2_ctb_size;

    int more_data   = 1;

    int *ctb_row_p    = input_ctb_row;

    int ctb_row = ctb_row_p[job];

    int ctb_addr_rs = s1->sh.slice_ctb_addr_rs + ctb_row * ((s1->ps.sps->width + ctb_size - 1) >> s1->ps.sps->log2_ctb_size);

    int ctb_addr_ts = s1->ps.pps->ctb_addr_rs_to_ts[ctb_addr_rs];

    int thread = ctb_row % s1->threads_number;

    int ret;



    s = s1->sList[self_id];

    lc = s->HEVClc;



    if(ctb_row) {

        ret = init_get_bits8(&lc->gb, s->data + s->sh.offset[ctb_row - 1], s->sh.size[ctb_row - 1]);



        if (ret < 0)

            return ret;

        ff_init_cabac_decoder(&lc->cc, s->data + s->sh.offset[(ctb_row)-1], s->sh.size[ctb_row - 1]);

    }



    while(more_data && ctb_addr_ts < s->ps.sps->ctb_size) {

        int x_ctb = (ctb_addr_rs % s->ps.sps->ctb_width) << s->ps.sps->log2_ctb_size;

        int y_ctb = (ctb_addr_rs / s->ps.sps->ctb_width) << s->ps.sps->log2_ctb_size;



        hls_decode_neighbour(s, x_ctb, y_ctb, ctb_addr_ts);



        ff_thread_await_progress2(s->avctx, ctb_row, thread, SHIFT_CTB_WPP);



        if (avpriv_atomic_int_get(&s1->wpp_err)){

            ff_thread_report_progress2(s->avctx, ctb_row , thread, SHIFT_CTB_WPP);

            return 0;

        }



        ff_hevc_cabac_init(s, ctb_addr_ts);

        hls_sao_param(s, x_ctb >> s->ps.sps->log2_ctb_size, y_ctb >> s->ps.sps->log2_ctb_size);

        more_data = hls_coding_quadtree(s, x_ctb, y_ctb, s->ps.sps->log2_ctb_size, 0);



        if (more_data < 0) {

            s->tab_slice_address[ctb_addr_rs] = -1;



            return more_data;

        }



        ctb_addr_ts++;



        ff_hevc_save_states(s, ctb_addr_ts);

        ff_thread_report_progress2(s->avctx, ctb_row, thread, 1);

        ff_hevc_hls_filters(s, x_ctb, y_ctb, ctb_size);



        if (!more_data && (x_ctb+ctb_size) < s->ps.sps->width && ctb_row != s->sh.num_entry_point_offsets) {



            return 0;

        }



        if ((x_ctb+ctb_size) >= s->ps.sps->width && (y_ctb+ctb_size) >= s->ps.sps->height ) {

            ff_hevc_hls_filter(s, x_ctb, y_ctb, ctb_size);

            ff_thread_report_progress2(s->avctx, ctb_row , thread, SHIFT_CTB_WPP);

            return ctb_addr_ts;

        }

        ctb_addr_rs       = s->ps.pps->ctb_addr_ts_to_rs[ctb_addr_ts];

        x_ctb+=ctb_size;



        if(x_ctb >= s->ps.sps->width) {

            break;

        }

    }




    return 0;

}

static int mpegts_raw_read_packet(AVFormatContext *s,

                                  AVPacket *pkt)

{

    MpegTSContext *ts = s->priv_data;

    int ret, i;

    int64_t pcr_h, next_pcr_h, pos;

    int pcr_l, next_pcr_l;

    uint8_t pcr_buf[12];

    uint8_t *data;



    if (av_new_packet(pkt, TS_PACKET_SIZE) < 0)

        return AVERROR(ENOMEM);

    pkt->pos= avio_tell(s->pb);

    ret = read_packet(s, pkt->data, ts->raw_packet_size, &data);

    if (ret < 0) {

        av_free_packet(pkt);

        return ret;

    }

    if (data != pkt->data)

        memcpy(pkt->data, data, ts->raw_packet_size);

    finished_reading_packet(s, ts->raw_packet_size);

    if (ts->mpeg2ts_compute_pcr) {

        /* compute exact PCR for each packet */

        if (parse_pcr(&pcr_h, &pcr_l, pkt->data) == 0) {

            /* we read the next PCR (XXX: optimize it by using a bigger buffer */

            pos = avio_tell(s->pb);

            for(i = 0; i < MAX_PACKET_READAHEAD; i++) {

                avio_seek(s->pb, pos + i * ts->raw_packet_size, SEEK_SET);

                avio_read(s->pb, pcr_buf, 12);

                if (parse_pcr(&next_pcr_h, &next_pcr_l, pcr_buf) == 0) {

                    /* XXX: not precise enough */

                    ts->pcr_incr = ((next_pcr_h - pcr_h) * 300 + (next_pcr_l - pcr_l)) /

                        (i + 1);

                    break;

                }

            }

            avio_seek(s->pb, pos, SEEK_SET);

            /* no next PCR found: we use previous increment */

            ts->cur_pcr = pcr_h * 300 + pcr_l;

        }

        pkt->pts = ts->cur_pcr;

        pkt->duration = ts->pcr_incr;

        ts->cur_pcr += ts->pcr_incr;

    }

    pkt->stream_index = 0;

    return 0;

}

static inline void RENAME(rgb24tobgr16)(const uint8_t *src, uint8_t *dst, int src_size)

{

    const uint8_t *s = src;

    const uint8_t *end;

    const uint8_t *mm_end;

    uint16_t *d = (uint16_t *)dst;

    end = s + src_size;

    __asm__ volatile(PREFETCH"    %0"::"m"(*src):"memory");

    __asm__ volatile(

        "movq         %0, %%mm7     \n\t"

        "movq         %1, %%mm6     \n\t"

        ::"m"(red_16mask),"m"(green_16mask));

    mm_end = end - 11;

    while (s < mm_end) {

        __asm__ volatile(

            PREFETCH"    32%1           \n\t"

            "movd          %1, %%mm0    \n\t"

            "movd         3%1, %%mm3    \n\t"

            "punpckldq    6%1, %%mm0    \n\t"

            "punpckldq    9%1, %%mm3    \n\t"

            "movq       %%mm0, %%mm1    \n\t"

            "movq       %%mm0, %%mm2    \n\t"

            "movq       %%mm3, %%mm4    \n\t"

            "movq       %%mm3, %%mm5    \n\t"

            "psrlq         $3, %%mm0    \n\t"

            "psrlq         $3, %%mm3    \n\t"

            "pand          %2, %%mm0    \n\t"

            "pand          %2, %%mm3    \n\t"

            "psrlq         $5, %%mm1    \n\t"

            "psrlq         $5, %%mm4    \n\t"

            "pand       %%mm6, %%mm1    \n\t"

            "pand       %%mm6, %%mm4    \n\t"

            "psrlq         $8, %%mm2    \n\t"

            "psrlq         $8, %%mm5    \n\t"

            "pand       %%mm7, %%mm2    \n\t"

            "pand       %%mm7, %%mm5    \n\t"

            "por        %%mm1, %%mm0    \n\t"

            "por        %%mm4, %%mm3    \n\t"

            "por        %%mm2, %%mm0    \n\t"

            "por        %%mm5, %%mm3    \n\t"

            "psllq        $16, %%mm3    \n\t"

            "por        %%mm3, %%mm0    \n\t"

            MOVNTQ"     %%mm0, %0       \n\t"

            :"=m"(*d):"m"(*s),"m"(blue_16mask):"memory");

        d += 4;

        s += 12;

    }

    __asm__ volatile(SFENCE:::"memory");

    __asm__ volatile(EMMS:::"memory");

    while (s < end) {

        const int b = *s++;

        const int g = *s++;

        const int r = *s++;

        *d++ = (b>>3) | ((g&0xFC)<<3) | ((r&0xF8)<<8);

    }

}

static void png_save2(const char *filename, uint32_t *bitmap, int w, int h)

{

    int x, y, v;

    FILE *f;

    char fname[40], fname2[40];

    char command[1024];



    snprintf(fname, 40, "%s.ppm", filename);



    f = fopen(fname, "w");

    if (!f) {

        perror(fname);

        exit(1);

    }

    fprintf(f, "P6\n"

            "%d %d\n"

            "%d\n",

            w, h, 255);

    for(y = 0; y < h; y++) {

        for(x = 0; x < w; x++) {

            v = bitmap[y * w + x];

            putc((v >> 16) & 0xff, f);

            putc((v >> 8) & 0xff, f);

            putc((v >> 0) & 0xff, f);

        }

    }

    fclose(f);





    snprintf(fname2, 40, "%s-a.pgm", filename);



    f = fopen(fname2, "w");

    if (!f) {

        perror(fname2);

        exit(1);

    }

    fprintf(f, "P5\n"

            "%d %d\n"

            "%d\n",

            w, h, 255);

    for(y = 0; y < h; y++) {

        for(x = 0; x < w; x++) {

            v = bitmap[y * w + x];

            putc((v >> 24) & 0xff, f);

        }

    }

    fclose(f);



    snprintf(command, 1024, "pnmtopng -alpha %s %s > %s.png 2> /dev/null", fname2, fname, filename);

    system(command);



    snprintf(command, 1024, "rm %s %s", fname, fname2);

    system(command);

}

static int spdif_write_packet(struct AVFormatContext *s, AVPacket *pkt)

{

    IEC61937Context *ctx = s->priv_data;

    int ret, padding;



    ctx->out_buf = pkt->data;

    ctx->out_bytes = pkt->size;

    ctx->length_code = FFALIGN(pkt->size, 2) << 3;

    ctx->use_preamble = 1;

    ctx->extra_bswap = 0;



    ret = ctx->header_info(s, pkt);

    if (ret < 0)

        return ret;

    if (!ctx->pkt_offset)

        return 0;



    padding = (ctx->pkt_offset - ctx->use_preamble * BURST_HEADER_SIZE - ctx->out_bytes) & ~1;

    if (padding < 0) {

        av_log(s, AV_LOG_ERROR, "bitrate is too high\n");

        return AVERROR(EINVAL);

    }



    if (ctx->use_preamble) {

        put_le16(s->pb, SYNCWORD1);       //Pa

        put_le16(s->pb, SYNCWORD2);       //Pb

        put_le16(s->pb, ctx->data_type);  //Pc

        put_le16(s->pb, ctx->length_code);//Pd

    }



    if (HAVE_BIGENDIAN ^ ctx->extra_bswap) {

    put_buffer(s->pb, ctx->out_buf, ctx->out_bytes & ~1);

    } else {

    av_fast_malloc(&ctx->buffer, &ctx->buffer_size, ctx->out_bytes + FF_INPUT_BUFFER_PADDING_SIZE);

    if (!ctx->buffer)

        return AVERROR(ENOMEM);

    ff_spdif_bswap_buf16((uint16_t *)ctx->buffer, (uint16_t *)ctx->out_buf, ctx->out_bytes >> 1);

    put_buffer(s->pb, ctx->buffer, ctx->out_bytes & ~1);

    }



    if (ctx->out_bytes & 1)

        put_be16(s->pb, ctx->out_buf[ctx->out_bytes - 1]);



    put_nbyte(s->pb, 0, padding);



    av_log(s, AV_LOG_DEBUG, "type=%x len=%i pkt_offset=%i\n",

           ctx->data_type, ctx->out_bytes, ctx->pkt_offset);



    put_flush_packet(s->pb);

    return 0;

}

av_cold void ff_rl_init(RLTable *rl,

                        uint8_t static_store[2][2 * MAX_RUN + MAX_LEVEL + 3])

{

    int8_t  max_level[MAX_RUN + 1], max_run[MAX_LEVEL + 1];

    uint8_t index_run[MAX_RUN + 1];

    int last, run, level, start, end, i;



    /* If table is static, we can quit if rl->max_level[0] is not NULL */

    if (static_store && rl->max_level[0])

        return;



    /* compute max_level[], max_run[] and index_run[] */

    for (last = 0; last < 2; last++) {

        if (last == 0) {

            start = 0;

            end = rl->last;

        } else {

            start = rl->last;

            end = rl->n;

        }



        memset(max_level, 0, MAX_RUN + 1);

        memset(max_run, 0, MAX_LEVEL + 1);

        memset(index_run, rl->n, MAX_RUN + 1);

        for (i = start; i < end; i++) {

            run   = rl->table_run[i];

            level = rl->table_level[i];

            if (index_run[run] == rl->n)

                index_run[run] = i;

            if (level > max_level[run])

                max_level[run] = level;

            if (run > max_run[level])

                max_run[level] = run;

        }

        if (static_store)

            rl->max_level[last] = static_store[last];

        else

            rl->max_level[last] = av_malloc(MAX_RUN + 1);

        memcpy(rl->max_level[last], max_level, MAX_RUN + 1);

        if (static_store)

            rl->max_run[last]   = static_store[last] + MAX_RUN + 1;

        else

            rl->max_run[last]   = av_malloc(MAX_LEVEL + 1);

        memcpy(rl->max_run[last], max_run, MAX_LEVEL + 1);

        if (static_store)

            rl->index_run[last] = static_store[last] + MAX_RUN + MAX_LEVEL + 2;

        else

            rl->index_run[last] = av_malloc(MAX_RUN + 1);

        memcpy(rl->index_run[last], index_run, MAX_RUN + 1);

    }

}

static int msf_read_header(AVFormatContext *s)

{

    unsigned codec, align, size;

    AVStream *st;



    avio_skip(s->pb, 4);



    st = avformat_new_stream(s, NULL);

    if (!st)

        return AVERROR(ENOMEM);



    st->codec->codec_type  = AVMEDIA_TYPE_AUDIO;

    codec                  = avio_rb32(s->pb);

    st->codec->channels    = avio_rb32(s->pb);

    if (st->codec->channels <= 0)

        return AVERROR_INVALIDDATA;

    size = avio_rb32(s->pb);

    st->codec->sample_rate = avio_rb32(s->pb);

    if (st->codec->sample_rate <= 0)

        return AVERROR_INVALIDDATA;

    align = avio_rb32(s->pb) ;

    if (align > INT_MAX / st->codec->channels)

        return AVERROR_INVALIDDATA;

    st->codec->block_align = align;

    switch (codec) {

    case 0: st->codec->codec_id = AV_CODEC_ID_PCM_S16BE; break;

    case 3: st->codec->block_align = 16 * st->codec->channels;

            st->codec->codec_id = AV_CODEC_ID_ADPCM_PSX; break;

    case 7: st->need_parsing = AVSTREAM_PARSE_FULL_RAW;

            st->codec->codec_id = AV_CODEC_ID_MP3;       break;

    default:

            avpriv_request_sample(s, "Codec %d", codec);

            return AVERROR_PATCHWELCOME;

    }

    st->duration = av_get_audio_frame_duration(st->codec, size);

    avio_skip(s->pb, 0x40 - avio_tell(s->pb));

    avpriv_set_pts_info(st, 64, 1, st->codec->sample_rate);



    return 0;

}

static int32_t tag_tree_size(uint16_t w, uint16_t h)

{

    uint32_t res = 0;

    while (w > 1 || h > 1) {

        res += w * h;

        if (res + 1 >= INT32_MAX)

            return -1;

        w = (w + 1) >> 1;

        h = (h + 1) >> 1;

    }

    return (int32_t)(res + 1);

}

static int mov_write_packet(AVFormatContext *s, AVPacket *pkt)

{

    MOVContext *mov = s->priv_data;

    ByteIOContext *pb = s->pb;

    MOVTrack *trk = &mov->tracks[pkt->stream_index];

    AVCodecContext *enc = trk->enc;

    unsigned int samplesInChunk = 0;

    int size= pkt->size;



    if (url_is_streamed(s->pb)) return 0; /* Can't handle that */

    if (!size) return 0; /* Discard 0 sized packets */



    if (enc->codec_id == CODEC_ID_AMR_NB) {

        /* We must find out how many AMR blocks there are in one packet */

        static uint16_t packed_size[16] =

            {13, 14, 16, 18, 20, 21, 27, 32, 6, 0, 0, 0, 0, 0, 0, 0};

        int len = 0;



        while (len < size && samplesInChunk < 100) {

            len += packed_size[(pkt->data[len] >> 3) & 0x0F];

            samplesInChunk++;

        }

        if(samplesInChunk > 1){

            av_log(s, AV_LOG_ERROR, "fatal error, input is not a single packet, implement a AVParser for it\n");

            return -1;

        }

    } else if (trk->sampleSize)

        samplesInChunk = size/trk->sampleSize;

    else

        samplesInChunk = 1;



    /* copy extradata if it exists */

    if (trk->vosLen == 0 && enc->extradata_size > 0) {

        trk->vosLen = enc->extradata_size;

        trk->vosData = av_malloc(trk->vosLen);

        memcpy(trk->vosData, enc->extradata, trk->vosLen);

    }



    if (enc->codec_id == CODEC_ID_H264 && trk->vosLen > 0 && *(uint8_t *)trk->vosData != 1) {

        /* from x264 or from bytestream h264 */

        /* nal reformating needed */

        int ret = ff_avc_parse_nal_units(pkt->data, &pkt->data, &pkt->size);

        if (ret < 0)

            return ret;

        assert(pkt->size);

        size = pkt->size;

    } else if (enc->codec_id == CODEC_ID_DNXHD && !trk->vosLen) {

        /* copy frame header to create needed atoms */

        if (size < 640)

            return -1;

        trk->vosLen = 640;

        trk->vosData = av_malloc(trk->vosLen);

        memcpy(trk->vosData, pkt->data, 640);

    }



    if (!(trk->entry % MOV_INDEX_CLUSTER_SIZE)) {

        trk->cluster = av_realloc(trk->cluster, (trk->entry + MOV_INDEX_CLUSTER_SIZE) * sizeof(*trk->cluster));

        if (!trk->cluster)

            return -1;

    }



    trk->cluster[trk->entry].pos = url_ftell(pb);

    trk->cluster[trk->entry].samplesInChunk = samplesInChunk;

    trk->cluster[trk->entry].size = size;

    trk->cluster[trk->entry].entries = samplesInChunk;

    trk->cluster[trk->entry].dts = pkt->dts;

    trk->trackDuration = pkt->dts - trk->cluster[0].dts + pkt->duration;



    if(enc->codec_type == CODEC_TYPE_VIDEO) {

        if (pkt->dts != pkt->pts)

            trk->hasBframes = 1;

        trk->cluster[trk->entry].cts = pkt->pts - pkt->dts;

        trk->cluster[trk->entry].key_frame = !!(pkt->flags & PKT_FLAG_KEY);

        if(trk->cluster[trk->entry].key_frame)

            trk->hasKeyframes++;

    }

    trk->entry++;

    trk->sampleCount += samplesInChunk;

    mov->mdat_size += size;



    put_buffer(pb, pkt->data, size);



    put_flush_packet(pb);

    return 0;

}

static inline void RENAME(rgb24tobgr24)(const uint8_t *src, uint8_t *dst, long src_size)

{

    unsigned i;

#if COMPILE_TEMPLATE_MMX

    x86_reg mmx_size= 23 - src_size;

    __asm__ volatile (

        "test             %%"REG_a", %%"REG_a"          \n\t"

        "jns                     2f                     \n\t"

        "movq     "MANGLE(mask24r)", %%mm5              \n\t"

        "movq     "MANGLE(mask24g)", %%mm6              \n\t"

        "movq     "MANGLE(mask24b)", %%mm7              \n\t"

        ".p2align                 4                     \n\t"

        "1:                                             \n\t"

        PREFETCH" 32(%1, %%"REG_a")                     \n\t"

        "movq       (%1, %%"REG_a"), %%mm0              \n\t" // BGR BGR BG

        "movq       (%1, %%"REG_a"), %%mm1              \n\t" // BGR BGR BG

        "movq      2(%1, %%"REG_a"), %%mm2              \n\t" // R BGR BGR B

        "psllq                  $16, %%mm0              \n\t" // 00 BGR BGR

        "pand                 %%mm5, %%mm0              \n\t"

        "pand                 %%mm6, %%mm1              \n\t"

        "pand                 %%mm7, %%mm2              \n\t"

        "por                  %%mm0, %%mm1              \n\t"

        "por                  %%mm2, %%mm1              \n\t"

        "movq      6(%1, %%"REG_a"), %%mm0              \n\t" // BGR BGR BG

        MOVNTQ"               %%mm1,   (%2, %%"REG_a")  \n\t" // RGB RGB RG

        "movq      8(%1, %%"REG_a"), %%mm1              \n\t" // R BGR BGR B

        "movq     10(%1, %%"REG_a"), %%mm2              \n\t" // GR BGR BGR

        "pand                 %%mm7, %%mm0              \n\t"

        "pand                 %%mm5, %%mm1              \n\t"

        "pand                 %%mm6, %%mm2              \n\t"

        "por                  %%mm0, %%mm1              \n\t"

        "por                  %%mm2, %%mm1              \n\t"

        "movq     14(%1, %%"REG_a"), %%mm0              \n\t" // R BGR BGR B

        MOVNTQ"               %%mm1,  8(%2, %%"REG_a")  \n\t" // B RGB RGB R

        "movq     16(%1, %%"REG_a"), %%mm1              \n\t" // GR BGR BGR

        "movq     18(%1, %%"REG_a"), %%mm2              \n\t" // BGR BGR BG

        "pand                 %%mm6, %%mm0              \n\t"

        "pand                 %%mm7, %%mm1              \n\t"

        "pand                 %%mm5, %%mm2              \n\t"

        "por                  %%mm0, %%mm1              \n\t"

        "por                  %%mm2, %%mm1              \n\t"

        MOVNTQ"               %%mm1, 16(%2, %%"REG_a")  \n\t"

        "add                    $24, %%"REG_a"          \n\t"

        " js                     1b                     \n\t"

        "2:                                             \n\t"

        : "+a" (mmx_size)

        : "r" (src-mmx_size), "r"(dst-mmx_size)

    );



    __asm__ volatile(SFENCE:::"memory");

    __asm__ volatile(EMMS:::"memory");



    if (mmx_size==23) return; //finished, was multiple of 8



    src+= src_size;

    dst+= src_size;

    src_size= 23-mmx_size;

    src-= src_size;

    dst-= src_size;

#endif

    for (i=0; i<src_size; i+=3) {

        register uint8_t x;

        x          = src[i + 2];

        dst[i + 1] = src[i + 1];

        dst[i + 2] = src[i + 0];

        dst[i + 0] = x;

    }

}

static inline void mix_2f_2r_to_mono(AC3DecodeContext *ctx)

{

    int i;

    float (*output)[256] = ctx->audio_block.block_output;



    for (i = 0; i < 256; i++)

        output[1][i] = (output[2][i] + output[3][i] + output[4][i]);

    memset(output[2], 0, sizeof(output[2]));

    memset(output[3], 0, sizeof(output[3]));

    memset(output[4], 0, sizeof(output[4]));

}

static void ebml_free(EbmlSyntax *syntax, void *data)

{

    int i, j;

    for (i = 0; syntax[i].id; i++) {

        void *data_off = (char *) data + syntax[i].data_offset;

        switch (syntax[i].type) {

        case EBML_STR:

        case EBML_UTF8:

            av_freep(data_off);

            break;

        case EBML_BIN:

            av_freep(&((EbmlBin *) data_off)->data);

            break;

        case EBML_LEVEL1:

        case EBML_NEST:

            if (syntax[i].list_elem_size) {

                EbmlList *list = data_off;

                char *ptr = list->elem;

                for (j = 0; j < list->nb_elem;

                     j++, ptr += syntax[i].list_elem_size)

                    ebml_free(syntax[i].def.n, ptr);

                av_freep(&list->elem);


            } else

                ebml_free(syntax[i].def.n, data_off);

        default:

            break;

        }

    }

}

int av_thread_message_queue_alloc(AVThreadMessageQueue **mq,

                                  unsigned nelem,

                                  unsigned elsize)

{

#if HAVE_THREADS

    AVThreadMessageQueue *rmq;

    int ret = 0;



    if (nelem > INT_MAX / elsize)

        return AVERROR(EINVAL);

    if (!(rmq = av_mallocz(sizeof(*rmq))))

        return AVERROR(ENOMEM);

    if ((ret = pthread_mutex_init(&rmq->lock, NULL))) {

        av_free(rmq);

        return AVERROR(ret);

    }

    if ((ret = pthread_cond_init(&rmq->cond, NULL))) {

        pthread_mutex_destroy(&rmq->lock);

        av_free(rmq);

        return AVERROR(ret);

    }

    if (!(rmq->fifo = av_fifo_alloc(elsize * nelem))) {

        pthread_cond_destroy(&rmq->cond);

        pthread_mutex_destroy(&rmq->lock);

        av_free(rmq);

        return AVERROR(ret);

    }

    rmq->elsize = elsize;

    *mq = rmq;

    return 0;

#else

    *mq = NULL;

    return AVERROR(ENOSYS);

#endif /* HAVE_THREADS */

}

