static int mxf_read_local_tags(MXFContext *mxf, KLVPacket *klv, int (*read_child)(), int ctx_size, enum MXFMetadataSetType type)

{

    ByteIOContext *pb = mxf->fc->pb;

    MXFMetadataSet *ctx = ctx_size ? av_mallocz(ctx_size) : mxf;

    uint64_t klv_end = url_ftell(pb) + klv->length;



    if (!ctx)

        return -1;

    while (url_ftell(pb) + 4 < klv_end) {

        int tag = get_be16(pb);

        int size = get_be16(pb); /* KLV specified by 0x53 */

        uint64_t next = url_ftell(pb) + size;

        UID uid;



        if (!size) { /* ignore empty tag, needed for some files with empty UMID tag */

            av_log(mxf->fc, AV_LOG_ERROR, "local tag 0x%04X with 0 size\n", tag);

            continue;

        }

        if (tag > 0x7FFF) { /* dynamic tag */

            int i;

            for (i = 0; i < mxf->local_tags_count; i++) {

                int local_tag = AV_RB16(mxf->local_tags+i*18);

                if (local_tag == tag) {

                    memcpy(uid, mxf->local_tags+i*18+2, 16);

                    dprintf(mxf->fc, "local tag 0x%04X\n", local_tag);

#ifdef DEBUG

                    PRINT_KEY(mxf->fc, "uid", uid);

#endif

                }

            }

        }

        if (ctx_size && tag == 0x3C0A)

            get_buffer(pb, ctx->uid, 16);

        else

            read_child(ctx, pb, tag, size, uid);



        url_fseek(pb, next, SEEK_SET);

    }

    if (ctx_size) ctx->type = type;

    return ctx_size ? mxf_add_metadata_set(mxf, ctx) : 0;

}

static int X264_frame(AVCodecContext *ctx, AVPacket *pkt, const AVFrame *frame,

                      int *got_packet)

{

    X264Context *x4 = ctx->priv_data;

    x264_nal_t *nal;

    int nnal, i, ret;

    x264_picture_t pic_out = {0};

    int pict_type;



    x264_picture_init( &x4->pic );

    x4->pic.img.i_csp   = x4->params.i_csp;

    if (x264_bit_depth > 8)

        x4->pic.img.i_csp |= X264_CSP_HIGH_DEPTH;

    x4->pic.img.i_plane = avfmt2_num_planes(ctx->pix_fmt);



    if (frame) {

        for (i = 0; i < x4->pic.img.i_plane; i++) {

            x4->pic.img.plane[i]    = frame->data[i];

            x4->pic.img.i_stride[i] = frame->linesize[i];

        }



        x4->pic.i_pts  = frame->pts;



        switch (frame->pict_type) {

        case AV_PICTURE_TYPE_I:

            x4->pic.i_type = x4->forced_idr > 0 ? X264_TYPE_IDR

                                                : X264_TYPE_KEYFRAME;

            break;

        case AV_PICTURE_TYPE_P:

            x4->pic.i_type = X264_TYPE_P;

            break;

        case AV_PICTURE_TYPE_B:

            x4->pic.i_type = X264_TYPE_B;

            break;

        default:

            x4->pic.i_type = X264_TYPE_AUTO;

            break;

        }

        reconfig_encoder(ctx, frame);



        if (x4->a53_cc) {

            void *sei_data;

            size_t sei_size;



            ret = ff_alloc_a53_sei(frame, 0, &sei_data, &sei_size);

            if (ret < 0) {

                av_log(ctx, AV_LOG_ERROR, "Not enough memory for closed captions, skipping\n");

            } else if (sei_data) {

                x4->pic.extra_sei.payloads = av_mallocz(sizeof(x4->pic.extra_sei.payloads[0]));

                if (x4->pic.extra_sei.payloads == NULL) {

                    av_log(ctx, AV_LOG_ERROR, "Not enough memory for closed captions, skipping\n");

                    av_free(sei_data);

                } else {

                    x4->pic.extra_sei.sei_free = av_free;



                    x4->pic.extra_sei.payloads[0].payload_size = sei_size;

                    x4->pic.extra_sei.payloads[0].payload = sei_data;

                    x4->pic.extra_sei.num_payloads = 1;

                    x4->pic.extra_sei.payloads[0].payload_type = 4;

                }

            }

        }

    }



    do {

        if (x264_encoder_encode(x4->enc, &nal, &nnal, frame? &x4->pic: NULL, &pic_out) < 0)

            return AVERROR_EXTERNAL;



        ret = encode_nals(ctx, pkt, nal, nnal);

        if (ret < 0)

            return ret;

    } while (!ret && !frame && x264_encoder_delayed_frames(x4->enc));



    pkt->pts = pic_out.i_pts;

    pkt->dts = pic_out.i_dts;





    switch (pic_out.i_type) {

    case X264_TYPE_IDR:

    case X264_TYPE_I:

        pict_type = AV_PICTURE_TYPE_I;

        break;

    case X264_TYPE_P:

        pict_type = AV_PICTURE_TYPE_P;

        break;

    case X264_TYPE_B:

    case X264_TYPE_BREF:

        pict_type = AV_PICTURE_TYPE_B;

        break;

    default:

        pict_type = AV_PICTURE_TYPE_NONE;

    }

#if FF_API_CODED_FRAME

FF_DISABLE_DEPRECATION_WARNINGS

    ctx->coded_frame->pict_type = pict_type;

FF_ENABLE_DEPRECATION_WARNINGS

#endif



    pkt->flags |= AV_PKT_FLAG_KEY*pic_out.b_keyframe;

    if (ret) {

        ff_side_data_set_encoder_stats(pkt, (pic_out.i_qpplus1 - 1) * FF_QP2LAMBDA, NULL, 0, pict_type);



#if FF_API_CODED_FRAME

FF_DISABLE_DEPRECATION_WARNINGS

        ctx->coded_frame->quality = (pic_out.i_qpplus1 - 1) * FF_QP2LAMBDA;

FF_ENABLE_DEPRECATION_WARNINGS

#endif

    }



    *got_packet = ret;

    return 0;

}

int flv_h263_decode_picture_header(MpegEncContext *s)

{

    int format, width, height;



    /* picture header */

    if (get_bits_long(&s->gb, 17) != 1) {

        av_log(s->avctx, AV_LOG_ERROR, "Bad picture start code\n");

        return -1;

    }

    format = get_bits(&s->gb, 5);

    if (format != 0 && format != 1) {

        av_log(s->avctx, AV_LOG_ERROR, "Bad picture format\n");

        return -1;

    }

    s->h263_flv = format+1;

    s->picture_number = get_bits(&s->gb, 8); /* picture timestamp */

    format = get_bits(&s->gb, 3);

    switch (format) {

    case 0:

        width = get_bits(&s->gb, 8);

        height = get_bits(&s->gb, 8);

        break;

    case 1:

        width = get_bits(&s->gb, 16);

        height = get_bits(&s->gb, 16);

        break;

    case 2:

        width = 352;

        height = 288;

        break;

    case 3:

        width = 176;

        height = 144;

        break;

    case 4:

        width = 128;

        height = 96;

        break;

    case 5:

        width = 320;

        height = 240;

        break;

    case 6:

        width = 160;

        height = 120;

        break;

    default:

        width = height = 0;

        break;

    }

    if ((width == 0) || (height == 0))

        return -1;

    s->width = width;

    s->height = height;



    s->pict_type = I_TYPE + get_bits(&s->gb, 2);

    if (s->pict_type > P_TYPE)

        s->pict_type = P_TYPE;

    skip_bits1(&s->gb);	/* deblocking flag */

    s->qscale = get_bits(&s->gb, 5);



    s->h263_plus = 0;



    s->unrestricted_mv = 1;

    s->h263_long_vectors = 0;



    /* PEI */

    while (get_bits1(&s->gb) != 0) {

        skip_bits(&s->gb, 8);

    }

    s->f_code = 1;



    if(s->avctx->debug & FF_DEBUG_PICT_INFO){

        av_log(s->avctx, AV_LOG_DEBUG, "%c esc_type:%d, qp:%d num:%d\n",

               av_get_pict_type_char(s->pict_type), s->h263_flv-1, s->qscale, s->picture_number);

    }



    s->y_dc_scale_table=

    s->c_dc_scale_table= ff_mpeg1_dc_scale_table;



    return 0;

}

static int libopenjpeg_copy_unpacked8(AVCodecContext *avctx, const AVFrame *frame, opj_image_t *image)

{

    int compno;

    int x;

    int y;

    int width;

    int height;

    int *image_line;

    int frame_index;

    const int numcomps = image->numcomps;



    for (compno = 0; compno < numcomps; ++compno) {

        if (image->comps[compno].w > frame->linesize[compno]) {

            av_log(avctx, AV_LOG_ERROR, "Error: frame's linesize is too small for the image\n");

            return 0;

        }

    }



    for (compno = 0; compno < numcomps; ++compno) {

        width  = avctx->width / image->comps[compno].dx;

        height = avctx->height / image->comps[compno].dy;

        for (y = 0; y < height; ++y) {

            image_line = image->comps[compno].data + y * image->comps[compno].w;

            frame_index = y * frame->linesize[compno];

            for (x = 0; x < width; ++x)

                image_line[x] = frame->data[compno][frame_index++];

            for (; x < image->comps[compno].w; ++x) {

                image_line[x] = image_line[x - 1];

            }

        }

        for (; y < image->comps[compno].h; ++y) {

            image_line = image->comps[compno].data + y * image->comps[compno].w;

            for (x = 0; x < image->comps[compno].w; ++x) {

                image_line[x] = image_line[x - image->comps[compno].w];

            }

        }

    }



    return 1;

}

static int url_alloc_for_protocol(URLContext **puc, struct URLProtocol *up,

                                  const char *filename, int flags,

                                  const AVIOInterruptCB *int_cb)

{

    URLContext *uc;

    int err;



#if CONFIG_NETWORK

    if (up->flags & URL_PROTOCOL_FLAG_NETWORK && !ff_network_init())

        return AVERROR(EIO);

#endif

    if ((flags & AVIO_FLAG_READ) && !up->url_read) {

        av_log(NULL, AV_LOG_ERROR,

               "Impossible to open the '%s' protocol for reading\n", up->name);

        return AVERROR(EIO);

    }

    if ((flags & AVIO_FLAG_WRITE) && !up->url_write) {

        av_log(NULL, AV_LOG_ERROR,

               "Impossible to open the '%s' protocol for writing\n", up->name);

        return AVERROR(EIO);

    }

    uc = av_mallocz(sizeof(URLContext) + strlen(filename) + 1);

    if (!uc) {

        err = AVERROR(ENOMEM);

        goto fail;

    }

    uc->av_class = &ffurl_context_class;

    uc->filename = (char *)&uc[1];

    strcpy(uc->filename, filename);

    uc->prot            = up;

    uc->flags           = flags;

    uc->is_streamed     = 0; /* default = not streamed */

    uc->max_packet_size = 0; /* default: stream file */

    if (up->priv_data_size) {

        uc->priv_data = av_mallocz(up->priv_data_size);

        if (!uc->priv_data) {

            err = AVERROR(ENOMEM);

            goto fail;

        }

        if (up->priv_data_class) {

            int proto_len= strlen(up->name);

            char *start = strchr(uc->filename, ',');

            *(const AVClass **)uc->priv_data = up->priv_data_class;

            av_opt_set_defaults(uc->priv_data);

            if(!strncmp(up->name, uc->filename, proto_len) && uc->filename + proto_len == start){

                int ret= 0;

                char *p= start;

                char sep= *++p;

                char *key, *val;

                p++;

                while(ret >= 0 && (key= strchr(p, sep)) && p<key && (val = strchr(key+1, sep))){

                    *val= *key= 0;

                    ret= av_opt_set(uc->priv_data, p, key+1, 0);

                    if (ret == AVERROR_OPTION_NOT_FOUND)

                        av_log(uc, AV_LOG_ERROR, "Key '%s' not found.\n", p);

                    *val= *key= sep;

                    p= val+1;

                }

                if(ret<0 || p!=key){

                    av_log(uc, AV_LOG_ERROR, "Error parsing options string %s\n", start);

                    av_freep(&uc->priv_data);

                    av_freep(&uc);

                    err = AVERROR(EINVAL);

                    goto fail;

                }

                memmove(start, key+1, strlen(key));

            }

        }

    }

    if (int_cb)

        uc->interrupt_callback = *int_cb;



    *puc = uc;

    return 0;

fail:

    *puc = NULL;

    if (uc)

        av_freep(&uc->priv_data);

    av_freep(&uc);

#if CONFIG_NETWORK

    if (up->flags & URL_PROTOCOL_FLAG_NETWORK)

        ff_network_close();

#endif

    return err;

}

static int ff_vp56_decode_mbs(AVCodecContext *avctx, void *data,

                              int jobnr, int threadnr)

{

    VP56Context *s0 = avctx->priv_data;

    int is_alpha = (jobnr == 1);

    VP56Context *s = is_alpha ? s0->alpha_context : s0;

    AVFrame *const p = s->frames[VP56_FRAME_CURRENT];

    int mb_row, mb_col, mb_row_flip, mb_offset = 0;

    int block, y, uv;

    ptrdiff_t stride_y, stride_uv;

    int res;

    int damaged = 0;



    if (p->key_frame) {

        p->pict_type = AV_PICTURE_TYPE_I;

        s->default_models_init(s);

        for (block=0; block<s->mb_height*s->mb_width; block++)

            s->macroblocks[block].type = VP56_MB_INTRA;

    } else {

        p->pict_type = AV_PICTURE_TYPE_P;

        vp56_parse_mb_type_models(s);

        s->parse_vector_models(s);

        s->mb_type = VP56_MB_INTER_NOVEC_PF;

    }



    if (s->parse_coeff_models(s))

        goto next;



    memset(s->prev_dc, 0, sizeof(s->prev_dc));

    s->prev_dc[1][VP56_FRAME_CURRENT] = 128;

    s->prev_dc[2][VP56_FRAME_CURRENT] = 128;



    for (block=0; block < 4*s->mb_width+6; block++) {

        s->above_blocks[block].ref_frame = VP56_FRAME_NONE;

        s->above_blocks[block].dc_coeff = 0;

        s->above_blocks[block].not_null_dc = 0;

    }

    s->above_blocks[2*s->mb_width + 2].ref_frame = VP56_FRAME_CURRENT;

    s->above_blocks[3*s->mb_width + 4].ref_frame = VP56_FRAME_CURRENT;



    stride_y  = p->linesize[0];

    stride_uv = p->linesize[1];



    if (s->flip < 0)

        mb_offset = 7;



    /* main macroblocks loop */

    for (mb_row=0; mb_row<s->mb_height; mb_row++) {

        if (s->flip < 0)

            mb_row_flip = s->mb_height - mb_row - 1;

        else

            mb_row_flip = mb_row;



        for (block=0; block<4; block++) {

            s->left_block[block].ref_frame = VP56_FRAME_NONE;

            s->left_block[block].dc_coeff = 0;

            s->left_block[block].not_null_dc = 0;

        }

        memset(s->coeff_ctx, 0, sizeof(s->coeff_ctx));

        memset(s->coeff_ctx_last, 24, sizeof(s->coeff_ctx_last));



        s->above_block_idx[0] = 1;

        s->above_block_idx[1] = 2;

        s->above_block_idx[2] = 1;

        s->above_block_idx[3] = 2;

        s->above_block_idx[4] = 2*s->mb_width + 2 + 1;

        s->above_block_idx[5] = 3*s->mb_width + 4 + 1;



        s->block_offset[s->frbi] = (mb_row_flip*16 + mb_offset) * stride_y;

        s->block_offset[s->srbi] = s->block_offset[s->frbi] + 8*stride_y;

        s->block_offset[1] = s->block_offset[0] + 8;

        s->block_offset[3] = s->block_offset[2] + 8;

        s->block_offset[4] = (mb_row_flip*8 + mb_offset) * stride_uv;

        s->block_offset[5] = s->block_offset[4];



        for (mb_col=0; mb_col<s->mb_width; mb_col++) {

            if (!damaged) {

                int ret = vp56_decode_mb(s, mb_row, mb_col, is_alpha);

                if (ret < 0)

                    damaged = 1;

            }

            if (damaged)

                vp56_conceal_mb(s, mb_row, mb_col, is_alpha);



            for (y=0; y<4; y++) {

                s->above_block_idx[y] += 2;

                s->block_offset[y] += 16;

            }



            for (uv=4; uv<6; uv++) {

                s->above_block_idx[uv] += 1;

                s->block_offset[uv] += 8;

            }

        }

    }



next:

    if (p->key_frame || s->golden_frame) {

        av_frame_unref(s->frames[VP56_FRAME_GOLDEN]);

        if ((res = av_frame_ref(s->frames[VP56_FRAME_GOLDEN], p)) < 0)

            return res;

    }



    av_frame_unref(s->frames[VP56_FRAME_PREVIOUS]);

    FFSWAP(AVFrame *, s->frames[VP56_FRAME_CURRENT],

                      s->frames[VP56_FRAME_PREVIOUS]);

    return 0;

}

static int draw_slice(AVFilterLink *inlink, int y0, int h, int slice_dir)

{

    AlphaExtractContext *extract = inlink->dst->priv;

    AVFilterBufferRef *cur_buf = inlink->cur_buf;

    AVFilterBufferRef *out_buf = inlink->dst->outputs[0]->out_buf;



    if (extract->is_packed_rgb) {

        int x, y;

        uint8_t *pin, *pout;

        for (y = y0; y < (y0 + h); y++) {

            pin = cur_buf->data[0] + y * cur_buf->linesize[0] + extract->rgba_map[A];

            pout = out_buf->data[0] + y * out_buf->linesize[0];

            for (x = 0; x < out_buf->video->w; x++) {

                *pout = *pin;

                pout += 1;

                pin += 4;

            }

        }

    } else if (cur_buf->linesize[A] == out_buf->linesize[Y]) {

        const int linesize = cur_buf->linesize[A];

        memcpy(out_buf->data[Y] + y0 * linesize,

               cur_buf->data[A] + y0 * linesize,

               linesize * h);

    } else {

        const int linesize = FFMIN(out_buf->linesize[Y], cur_buf->linesize[A]);

        int y;

        for (y = y0; y < (y0 + h); y++) {

            memcpy(out_buf->data[Y] + y * out_buf->linesize[Y],

                   cur_buf->data[A] + y * cur_buf->linesize[A],

                   linesize);

        }

    }

    return ff_draw_slice(inlink->dst->outputs[0], y0, h, slice_dir);

}

static int sad16_altivec(void *v, uint8_t *pix1, uint8_t *pix2, int line_size, int h)

{

    int i;

    int s;

    const vector unsigned int zero = (const vector unsigned int)vec_splat_u32(0);

    vector unsigned char perm1, perm2, *pix1v, *pix2v;

    vector unsigned char t1, t2, t3,t4, t5;

    vector unsigned int sad;

    vector signed int sumdiffs;



    sad = (vector unsigned int)vec_splat_u32(0);





    for (i = 0; i < h; i++) {

        /* Read potentially unaligned pixels into t1 and t2 */

        perm1 = vec_lvsl(0, pix1);

        pix1v = (vector unsigned char *) pix1;

        perm2 = vec_lvsl(0, pix2);

        pix2v = (vector unsigned char *) pix2;

        t1 = vec_perm(pix1v[0], pix1v[1], perm1);

        t2 = vec_perm(pix2v[0], pix2v[1], perm2);



        /* Calculate a sum of abs differences vector */

        t3 = vec_max(t1, t2);

        t4 = vec_min(t1, t2);

        t5 = vec_sub(t3, t4);



        /* Add each 4 pixel group together and put 4 results into sad */

        sad = vec_sum4s(t5, sad);



        pix1 += line_size;

        pix2 += line_size;

    }



    /* Sum up the four partial sums, and put the result into s */

    sumdiffs = vec_sums((vector signed int) sad, (vector signed int) zero);

    sumdiffs = vec_splat(sumdiffs, 3);

    vec_ste(sumdiffs, 0, &s);



    return s;

}

void rgb8tobgr8(const uint8_t *src, uint8_t *dst, unsigned int src_size)

{

	unsigned i;

	unsigned num_pixels = src_size;

	for(i=0; i<num_pixels; i++)

	{

	    unsigned b,g,r;

	    register uint8_t rgb;

	    rgb = src[i];

	    r = (rgb&0x07);

	    g = (rgb&0x38)>>3;

	    b = (rgb&0xC0)>>6;

	    dst[i] = ((b<<1)&0x07) | ((g&0x07)<<3) | ((r&0x03)<<6);

	}

}

