static int flashsv_decode_block(AVCodecContext *avctx, AVPacket *avpkt,

                                GetBitContext *gb, int block_size,

                                int width, int height, int x_pos, int y_pos,

                                int blk_idx)

{

    struct FlashSVContext *s = avctx->priv_data;

    uint8_t *line = s->tmpblock;

    int k;

    int ret = inflateReset(&s->zstream);

    if (ret != Z_OK) {

        av_log(avctx, AV_LOG_ERROR, "Inflate reset error: %d\n", ret);

        return AVERROR_UNKNOWN;

    }

    if (s->zlibprime_curr || s->zlibprime_prev) {

        ret = flashsv2_prime(s,

                             s->blocks[blk_idx].pos,

                             s->blocks[blk_idx].size);

        if (ret < 0)

            return ret;

    }

    s->zstream.next_in   = avpkt->data + get_bits_count(gb) / 8;

    s->zstream.avail_in  = block_size;

    s->zstream.next_out  = s->tmpblock;

    s->zstream.avail_out = s->block_size * 3;

    ret = inflate(&s->zstream, Z_FINISH);

    if (ret == Z_DATA_ERROR) {

        av_log(avctx, AV_LOG_ERROR, "Zlib resync occurred\n");

        inflateSync(&s->zstream);

        ret = inflate(&s->zstream, Z_FINISH);

    }



    if (ret != Z_OK && ret != Z_STREAM_END) {

        //return -1;

    }



    if (s->is_keyframe) {

        s->blocks[blk_idx].pos  = s->keyframedata + (get_bits_count(gb) / 8);

        s->blocks[blk_idx].size = block_size;

    }



    y_pos += s->diff_start;



    if (!s->color_depth) {

        /* Flash Screen Video stores the image upside down, so copy

         * lines to destination in reverse order. */

        for (k = 1; k <= s->diff_height; k++) {

            memcpy(s->frame->data[0] + x_pos * 3 +

                   (s->image_height - y_pos - k) * s->frame->linesize[0],

                   line, width * 3);

            /* advance source pointer to next line */

            line += width * 3;

        }

    } else {

        /* hybrid 15-bit/palette mode */

        decode_hybrid(s->tmpblock, s->frame->data[0],

                      s->image_height - (y_pos + 1 + s->diff_height),

                      x_pos, s->diff_height, width,

                      s->frame->linesize[0], s->pal);

    }

    skip_bits_long(gb, 8 * block_size); /* skip the consumed bits */

    return 0;

}

static av_always_inline void filter_mb_dir(H264Context *h, int mb_x, int mb_y, uint8_t *img_y, uint8_t *img_cb, uint8_t *img_cr, unsigned int linesize, unsigned int uvlinesize, int mb_xy, int mb_type, int mvy_limit, int first_vertical_edge_done, int chroma, int chroma444, int dir) {

    MpegEncContext * const s = &h->s;

    int edge;

    int chroma_qp_avg[2];

    const int mbm_xy = dir == 0 ? mb_xy -1 : h->top_mb_xy;

    const int mbm_type = dir == 0 ? h->left_type[LTOP] : h->top_type;



    // how often to recheck mv-based bS when iterating between edges

    static const uint8_t mask_edge_tab[2][8]={{0,3,3,3,1,1,1,1},

                                              {0,3,1,1,3,3,3,3}};

    const int mask_edge = mask_edge_tab[dir][(mb_type>>3)&7];

    const int edges = mask_edge== 3 && !(h->cbp&15) ? 1 : 4;



    // how often to recheck mv-based bS when iterating along each edge

    const int mask_par0 = mb_type & (MB_TYPE_16x16 | (MB_TYPE_8x16 >> dir));



    if(mbm_type && !first_vertical_edge_done){



        if (FRAME_MBAFF && (dir == 1) && ((mb_y&1) == 0)

            && IS_INTERLACED(mbm_type&~mb_type)

            ) {

            // This is a special case in the norm where the filtering must

            // be done twice (one each of the field) even if we are in a

            // frame macroblock.

            //

            unsigned int tmp_linesize   = 2 *   linesize;

            unsigned int tmp_uvlinesize = 2 * uvlinesize;

            int mbn_xy = mb_xy - 2 * s->mb_stride;

            int j;



            for(j=0; j<2; j++, mbn_xy += s->mb_stride){

                DECLARE_ALIGNED(8, int16_t, bS)[4];

                int qp;

                if (IS_INTRA(mb_type | s->current_picture.f.mb_type[mbn_xy])) {

                    AV_WN64A(bS, 0x0003000300030003ULL);

                } else {

                    if (!CABAC && IS_8x8DCT(s->current_picture.f.mb_type[mbn_xy])) {

                        bS[0]= 1+((h->cbp_table[mbn_xy] & 0x4000)||h->non_zero_count_cache[scan8[0]+0]);

                        bS[1]= 1+((h->cbp_table[mbn_xy] & 0x4000)||h->non_zero_count_cache[scan8[0]+1]);

                        bS[2]= 1+((h->cbp_table[mbn_xy] & 0x8000)||h->non_zero_count_cache[scan8[0]+2]);

                        bS[3]= 1+((h->cbp_table[mbn_xy] & 0x8000)||h->non_zero_count_cache[scan8[0]+3]);

                    }else{

                    const uint8_t *mbn_nnz = h->non_zero_count[mbn_xy] + 3*4;

                    int i;

                    for( i = 0; i < 4; i++ ) {

                        bS[i] = 1 + !!(h->non_zero_count_cache[scan8[0]+i] | mbn_nnz[i]);

                    }

                    }

                }

                // Do not use s->qscale as luma quantizer because it has not the same

                // value in IPCM macroblocks.

                qp = (s->current_picture.f.qscale_table[mb_xy] + s->current_picture.f.qscale_table[mbn_xy] + 1) >> 1;

                tprintf(s->avctx, "filter mb:%d/%d dir:%d edge:%d, QPy:%d ls:%d uvls:%d", mb_x, mb_y, dir, edge, qp, tmp_linesize, tmp_uvlinesize);

                { int i; for (i = 0; i < 4; i++) tprintf(s->avctx, " bS[%d]:%d", i, bS[i]); tprintf(s->avctx, "\n"); }

                filter_mb_edgeh( &img_y[j*linesize], tmp_linesize, bS, qp, h );

                chroma_qp_avg[0] = (h->chroma_qp[0] + get_chroma_qp(h, 0, s->current_picture.f.qscale_table[mbn_xy]) + 1) >> 1;

                chroma_qp_avg[1] = (h->chroma_qp[1] + get_chroma_qp(h, 1, s->current_picture.f.qscale_table[mbn_xy]) + 1) >> 1;

                if (chroma) {

                    if (chroma444) {

                        filter_mb_edgeh (&img_cb[j*uvlinesize], tmp_uvlinesize, bS, chroma_qp_avg[0], h);

                        filter_mb_edgeh (&img_cr[j*uvlinesize], tmp_uvlinesize, bS, chroma_qp_avg[1], h);

                    } else {

                        filter_mb_edgech(&img_cb[j*uvlinesize], tmp_uvlinesize, bS, chroma_qp_avg[0], h);

                        filter_mb_edgech(&img_cr[j*uvlinesize], tmp_uvlinesize, bS, chroma_qp_avg[1], h);

                    }

                }

            }

        }else{

            DECLARE_ALIGNED(8, int16_t, bS)[4];

            int qp;



            if( IS_INTRA(mb_type|mbm_type)) {

                AV_WN64A(bS, 0x0003000300030003ULL);

                if (   (!IS_INTERLACED(mb_type|mbm_type))

                    || ((FRAME_MBAFF || (s->picture_structure != PICT_FRAME)) && (dir == 0))

                )

                    AV_WN64A(bS, 0x0004000400040004ULL);

            } else {

                int i;

                int mv_done;



                if( dir && FRAME_MBAFF && IS_INTERLACED(mb_type ^ mbm_type)) {

                    AV_WN64A(bS, 0x0001000100010001ULL);

                    mv_done = 1;

                }

                else if( mask_par0 && ((mbm_type & (MB_TYPE_16x16 | (MB_TYPE_8x16 >> dir)))) ) {

                    int b_idx= 8 + 4;

                    int bn_idx= b_idx - (dir ? 8:1);



                    bS[0] = bS[1] = bS[2] = bS[3] = check_mv(h, 8 + 4, bn_idx, mvy_limit);

                    mv_done = 1;

                }

                else

                    mv_done = 0;



                for( i = 0; i < 4; i++ ) {

                    int x = dir == 0 ? 0 : i;

                    int y = dir == 0 ? i    : 0;

                    int b_idx= 8 + 4 + x + 8*y;

                    int bn_idx= b_idx - (dir ? 8:1);



                    if( h->non_zero_count_cache[b_idx] |

                        h->non_zero_count_cache[bn_idx] ) {

                        bS[i] = 2;

                    }

                    else if(!mv_done)

                    {

                        bS[i] = check_mv(h, b_idx, bn_idx, mvy_limit);

                    }

                }

            }



            /* Filter edge */

            // Do not use s->qscale as luma quantizer because it has not the same

            // value in IPCM macroblocks.

            if(bS[0]+bS[1]+bS[2]+bS[3]){

                qp = (s->current_picture.f.qscale_table[mb_xy] + s->current_picture.f.qscale_table[mbm_xy] + 1) >> 1;

                //tprintf(s->avctx, "filter mb:%d/%d dir:%d edge:%d, QPy:%d, QPc:%d, QPcn:%d\n", mb_x, mb_y, dir, edge, qp, h->chroma_qp[0], s->current_picture.qscale_table[mbn_xy]);

                tprintf(s->avctx, "filter mb:%d/%d dir:%d edge:%d, QPy:%d ls:%d uvls:%d", mb_x, mb_y, dir, edge, qp, linesize, uvlinesize);

                //{ int i; for (i = 0; i < 4; i++) tprintf(s->avctx, " bS[%d]:%d", i, bS[i]); tprintf(s->avctx, "\n"); }

                chroma_qp_avg[0] = (h->chroma_qp[0] + get_chroma_qp(h, 0, s->current_picture.f.qscale_table[mbm_xy]) + 1) >> 1;

                chroma_qp_avg[1] = (h->chroma_qp[1] + get_chroma_qp(h, 1, s->current_picture.f.qscale_table[mbm_xy]) + 1) >> 1;

                if( dir == 0 ) {

                    filter_mb_edgev( &img_y[0], linesize, bS, qp, h );

                    if (chroma) {

                        if (chroma444) {

                            filter_mb_edgev ( &img_cb[0], uvlinesize, bS, chroma_qp_avg[0], h);

                            filter_mb_edgev ( &img_cr[0], uvlinesize, bS, chroma_qp_avg[1], h);

                        } else {

                            filter_mb_edgecv( &img_cb[0], uvlinesize, bS, chroma_qp_avg[0], h);

                            filter_mb_edgecv( &img_cr[0], uvlinesize, bS, chroma_qp_avg[1], h);

                        }

                    }

                } else {

                    filter_mb_edgeh( &img_y[0], linesize, bS, qp, h );

                    if (chroma) {

                        if (chroma444) {

                            filter_mb_edgeh ( &img_cb[0], uvlinesize, bS, chroma_qp_avg[0], h);

                            filter_mb_edgeh ( &img_cr[0], uvlinesize, bS, chroma_qp_avg[1], h);

                        } else {

                            filter_mb_edgech( &img_cb[0], uvlinesize, bS, chroma_qp_avg[0], h);

                            filter_mb_edgech( &img_cr[0], uvlinesize, bS, chroma_qp_avg[1], h);

                        }

                    }

                }

            }

        }

    }



    /* Calculate bS */

    for( edge = 1; edge < edges; edge++ ) {

        DECLARE_ALIGNED(8, int16_t, bS)[4];

        int qp;



        if( IS_8x8DCT(mb_type & (edge<<24)) ) // (edge&1) && IS_8x8DCT(mb_type)

            continue;



        if( IS_INTRA(mb_type)) {

            AV_WN64A(bS, 0x0003000300030003ULL);

        } else {

            int i;

            int mv_done;



            if( edge & mask_edge ) {

                AV_ZERO64(bS);

                mv_done = 1;

            }

            else if( mask_par0 ) {

                int b_idx= 8 + 4 + edge * (dir ? 8:1);

                int bn_idx= b_idx - (dir ? 8:1);



                bS[0] = bS[1] = bS[2] = bS[3] = check_mv(h, b_idx, bn_idx, mvy_limit);

                mv_done = 1;

            }

            else

                mv_done = 0;



            for( i = 0; i < 4; i++ ) {

                int x = dir == 0 ? edge : i;

                int y = dir == 0 ? i    : edge;

                int b_idx= 8 + 4 + x + 8*y;

                int bn_idx= b_idx - (dir ? 8:1);



                if( h->non_zero_count_cache[b_idx] |

                    h->non_zero_count_cache[bn_idx] ) {

                    bS[i] = 2;

                }

                else if(!mv_done)

                {

                    bS[i] = check_mv(h, b_idx, bn_idx, mvy_limit);

                }

            }



            if(bS[0]+bS[1]+bS[2]+bS[3] == 0)

                continue;

        }



        /* Filter edge */

        // Do not use s->qscale as luma quantizer because it has not the same

        // value in IPCM macroblocks.

        qp = s->current_picture.f.qscale_table[mb_xy];

        //tprintf(s->avctx, "filter mb:%d/%d dir:%d edge:%d, QPy:%d, QPc:%d, QPcn:%d\n", mb_x, mb_y, dir, edge, qp, h->chroma_qp[0], s->current_picture.qscale_table[mbn_xy]);

        tprintf(s->avctx, "filter mb:%d/%d dir:%d edge:%d, QPy:%d ls:%d uvls:%d", mb_x, mb_y, dir, edge, qp, linesize, uvlinesize);

        //{ int i; for (i = 0; i < 4; i++) tprintf(s->avctx, " bS[%d]:%d", i, bS[i]); tprintf(s->avctx, "\n"); }

        if( dir == 0 ) {

            filter_mb_edgev( &img_y[4*edge << h->pixel_shift], linesize, bS, qp, h );

            if (chroma) {

                if (chroma444) {

                    filter_mb_edgev ( &img_cb[4*edge << h->pixel_shift], uvlinesize, bS, h->chroma_qp[0], h);

                    filter_mb_edgev ( &img_cr[4*edge << h->pixel_shift], uvlinesize, bS, h->chroma_qp[1], h);

                } else if( (edge&1) == 0 ) {

                    filter_mb_edgecv( &img_cb[2*edge << h->pixel_shift], uvlinesize, bS, h->chroma_qp[0], h);

                    filter_mb_edgecv( &img_cr[2*edge << h->pixel_shift], uvlinesize, bS, h->chroma_qp[1], h);

                }

            }

        } else {

            filter_mb_edgeh( &img_y[4*edge*linesize], linesize, bS, qp, h );

            if (chroma) {

                if (chroma444) {

                    filter_mb_edgeh ( &img_cb[4*edge*uvlinesize], uvlinesize, bS, h->chroma_qp[0], h);

                    filter_mb_edgeh ( &img_cr[4*edge*uvlinesize], uvlinesize, bS, h->chroma_qp[1], h);

                } else if( (edge&1) == 0 ) {

                    filter_mb_edgech( &img_cb[2*edge*uvlinesize], uvlinesize, bS, h->chroma_qp[0], h);

                    filter_mb_edgech( &img_cr[2*edge*uvlinesize], uvlinesize, bS, h->chroma_qp[1], h);

                }

            }

        }

    }

}

static int mov_read_close(AVFormatContext *s)

{

    MOVContext *mov = s->priv_data;

    int i, j;



    for (i = 0; i < s->nb_streams; i++) {

        AVStream *st = s->streams[i];

        MOVStreamContext *sc = st->priv_data;



        av_freep(&sc->ctts_data);

        for (j = 0; j < sc->drefs_count; j++) {

            av_freep(&sc->drefs[j].path);

            av_freep(&sc->drefs[j].dir);

        }

        av_freep(&sc->drefs);

        if (sc->pb && sc->pb != s->pb)

            avio_close(sc->pb);



        av_freep(&sc->chunk_offsets);

        av_freep(&sc->stsc_data);

        av_freep(&sc->sample_sizes);

        av_freep(&sc->keyframes);

        av_freep(&sc->stts_data);

        av_freep(&sc->stps_data);

        av_freep(&sc->rap_group);

        av_freep(&sc->display_matrix);

    }



    if (mov->dv_demux) {

        avformat_free_context(mov->dv_fctx);

        mov->dv_fctx = NULL;

    }



    av_freep(&mov->trex_data);



    return 0;

}

static int color_request_frame(AVFilterLink *link)

{

    ColorContext *color = link->src->priv;

    AVFilterBufferRef *picref = ff_get_video_buffer(link, AV_PERM_WRITE, color->w, color->h);

    int ret;



    picref->video->pixel_aspect = (AVRational) {1, 1};

    picref->pts                 = color->pts++;

    picref->pos                 = -1;



    ret = ff_start_frame(link, avfilter_ref_buffer(picref, ~0));

    if (ret < 0)

        goto fail;



    ff_draw_rectangle(picref->data, picref->linesize,

                      color->line, color->line_step, color->hsub, color->vsub,

                      0, 0, color->w, color->h);

    ret = ff_draw_slice(link, 0, color->h, 1);

    if (ret < 0)

        goto fail;



    ret = ff_end_frame(link);



fail:

    avfilter_unref_buffer(picref);



    return ret;

}

static int mov_read_stsd(MOVContext *c, ByteIOContext *pb, MOV_atom_t atom)

{

    AVStream *st = c->fc->streams[c->fc->nb_streams-1];

    MOVStreamContext *sc = st->priv_data;

    int j, entries, pseudo_stream_id;



    get_byte(pb); /* version */

    get_be24(pb); /* flags */



    entries = get_be32(pb);



    for(pseudo_stream_id=0; pseudo_stream_id<entries; pseudo_stream_id++) {

        //Parsing Sample description table

        enum CodecID id;

        int dref_id;

        MOV_atom_t a = { 0, 0, 0 };

        offset_t start_pos = url_ftell(pb);

        int size = get_be32(pb); /* size */

        uint32_t format = get_le32(pb); /* data format */



        get_be32(pb); /* reserved */

        get_be16(pb); /* reserved */

        dref_id = get_be16(pb);



        if (st->codec->codec_tag &&

            st->codec->codec_tag != format &&

            (c->fc->video_codec_id ? codec_get_id(codec_movvideo_tags, format) != c->fc->video_codec_id

                                   : st->codec->codec_tag != MKTAG('j','p','e','g'))

           ){

            /* Multiple fourcc, we skip JPEG. This is not correct, we should

             * export it as a separate AVStream but this needs a few changes

             * in the MOV demuxer, patch welcome. */

            av_log(c->fc, AV_LOG_WARNING, "multiple fourcc not supported\n");

            url_fskip(pb, size - (url_ftell(pb) - start_pos));

            continue;

        }

        sc->pseudo_stream_id = st->codec->codec_tag ? -1 : pseudo_stream_id;

        sc->dref_id= dref_id;



        st->codec->codec_tag = format;

        id = codec_get_id(codec_movaudio_tags, format);

        if (id<=0 && (format&0xFFFF) == 'm'+('s'<<8))

            id = codec_get_id(codec_wav_tags, bswap_32(format)&0xFFFF);



        if (st->codec->codec_type != CODEC_TYPE_VIDEO && id > 0) {

            st->codec->codec_type = CODEC_TYPE_AUDIO;

        } else if (st->codec->codec_type != CODEC_TYPE_AUDIO && /* do not overwrite codec type */

                   format && format != MKTAG('m','p','4','s')) { /* skip old asf mpeg4 tag */

            id = codec_get_id(codec_movvideo_tags, format);

            if (id <= 0)

                id = codec_get_id(codec_bmp_tags, format);

            if (id > 0)

                st->codec->codec_type = CODEC_TYPE_VIDEO;

            else if(st->codec->codec_type == CODEC_TYPE_DATA){

                id = codec_get_id(ff_codec_movsubtitle_tags, format);

                if(id > 0)

                    st->codec->codec_type = CODEC_TYPE_SUBTITLE;

            }

        }



        dprintf(c->fc, "size=%d 4CC= %c%c%c%c codec_type=%d\n", size,

                (format >> 0) & 0xff, (format >> 8) & 0xff, (format >> 16) & 0xff,

                (format >> 24) & 0xff, st->codec->codec_type);



        if(st->codec->codec_type==CODEC_TYPE_VIDEO) {

            uint8_t codec_name[32];

            unsigned int color_depth;

            int color_greyscale;



            st->codec->codec_id = id;

            get_be16(pb); /* version */

            get_be16(pb); /* revision level */

            get_be32(pb); /* vendor */

            get_be32(pb); /* temporal quality */

            get_be32(pb); /* spatial quality */



            st->codec->width = get_be16(pb); /* width */

            st->codec->height = get_be16(pb); /* height */



            get_be32(pb); /* horiz resolution */

            get_be32(pb); /* vert resolution */

            get_be32(pb); /* data size, always 0 */

            get_be16(pb); /* frames per samples */



            get_buffer(pb, codec_name, 32); /* codec name, pascal string */

            if (codec_name[0] <= 31) {

                memcpy(st->codec->codec_name, &codec_name[1],codec_name[0]);

                st->codec->codec_name[codec_name[0]] = 0;

            }



            st->codec->bits_per_coded_sample = get_be16(pb); /* depth */

            st->codec->color_table_id = get_be16(pb); /* colortable id */

            dprintf(c->fc, "depth %d, ctab id %d\n",

                   st->codec->bits_per_coded_sample, st->codec->color_table_id);

            /* figure out the palette situation */

            color_depth = st->codec->bits_per_coded_sample & 0x1F;

            color_greyscale = st->codec->bits_per_coded_sample & 0x20;



            /* if the depth is 2, 4, or 8 bpp, file is palettized */

            if ((color_depth == 2) || (color_depth == 4) ||

                (color_depth == 8)) {

                /* for palette traversal */

                unsigned int color_start, color_count, color_end;

                unsigned char r, g, b;



                if (color_greyscale) {

                    int color_index, color_dec;

                    /* compute the greyscale palette */

                    st->codec->bits_per_coded_sample = color_depth;

                    color_count = 1 << color_depth;

                    color_index = 255;

                    color_dec = 256 / (color_count - 1);

                    for (j = 0; j < color_count; j++) {

                        r = g = b = color_index;

                        c->palette_control.palette[j] =

                            (r << 16) | (g << 8) | (b);

                        color_index -= color_dec;

                        if (color_index < 0)

                            color_index = 0;

                    }

                } else if (st->codec->color_table_id) {

                    const uint8_t *color_table;

                    /* if flag bit 3 is set, use the default palette */

                    color_count = 1 << color_depth;

                    if (color_depth == 2)

                        color_table = ff_qt_default_palette_4;

                    else if (color_depth == 4)

                        color_table = ff_qt_default_palette_16;

                    else

                        color_table = ff_qt_default_palette_256;



                    for (j = 0; j < color_count; j++) {

                        r = color_table[j * 4 + 0];

                        g = color_table[j * 4 + 1];

                        b = color_table[j * 4 + 2];

                        c->palette_control.palette[j] =

                            (r << 16) | (g << 8) | (b);

                    }

                } else {

                    /* load the palette from the file */

                    color_start = get_be32(pb);

                    color_count = get_be16(pb);

                    color_end = get_be16(pb);

                    if ((color_start <= 255) &&

                        (color_end <= 255)) {

                        for (j = color_start; j <= color_end; j++) {

                            /* each R, G, or B component is 16 bits;

                             * only use the top 8 bits; skip alpha bytes

                             * up front */

                            get_byte(pb);

                            get_byte(pb);

                            r = get_byte(pb);

                            get_byte(pb);

                            g = get_byte(pb);

                            get_byte(pb);

                            b = get_byte(pb);

                            get_byte(pb);

                            c->palette_control.palette[j] =

                                (r << 16) | (g << 8) | (b);

                        }

                    }

                }

                st->codec->palctrl = &c->palette_control;

                st->codec->palctrl->palette_changed = 1;

            } else

                st->codec->palctrl = NULL;

        } else if(st->codec->codec_type==CODEC_TYPE_AUDIO) {

            int bits_per_sample, flags;

            uint16_t version = get_be16(pb);



            st->codec->codec_id = id;

            get_be16(pb); /* revision level */

            get_be32(pb); /* vendor */



            st->codec->channels = get_be16(pb);             /* channel count */

            dprintf(c->fc, "audio channels %d\n", st->codec->channels);

            st->codec->bits_per_coded_sample = get_be16(pb);      /* sample size */



            sc->audio_cid = get_be16(pb);

            get_be16(pb); /* packet size = 0 */



            st->codec->sample_rate = ((get_be32(pb) >> 16));



            //Read QT version 1 fields. In version 0 these do not exist.

            dprintf(c->fc, "version =%d, isom =%d\n",version,c->isom);

            if(!c->isom) {

                if(version==1) {

                    sc->samples_per_frame = get_be32(pb);

                    get_be32(pb); /* bytes per packet */

                    sc->bytes_per_frame = get_be32(pb);

                    get_be32(pb); /* bytes per sample */

                } else if(version==2) {

                    get_be32(pb); /* sizeof struct only */

                    st->codec->sample_rate = av_int2dbl(get_be64(pb)); /* float 64 */

                    st->codec->channels = get_be32(pb);

                    get_be32(pb); /* always 0x7F000000 */

                    st->codec->bits_per_coded_sample = get_be32(pb); /* bits per channel if sound is uncompressed */

                    flags = get_be32(pb); /* lcpm format specific flag */

                    sc->bytes_per_frame = get_be32(pb); /* bytes per audio packet if constant */

                    sc->samples_per_frame = get_be32(pb); /* lpcm frames per audio packet if constant */

                    if (format == MKTAG('l','p','c','m'))

                        st->codec->codec_id = mov_get_lpcm_codec_id(st->codec->bits_per_coded_sample, flags);

                }

            }



            switch (st->codec->codec_id) {

            case CODEC_ID_PCM_S8:

            case CODEC_ID_PCM_U8:

                if (st->codec->bits_per_coded_sample == 16)

                    st->codec->codec_id = CODEC_ID_PCM_S16BE;

                break;

            case CODEC_ID_PCM_S16LE:

            case CODEC_ID_PCM_S16BE:

                if (st->codec->bits_per_coded_sample == 8)

                    st->codec->codec_id = CODEC_ID_PCM_S8;

                else if (st->codec->bits_per_coded_sample == 24)

                    st->codec->codec_id =

                        st->codec->codec_id == CODEC_ID_PCM_S16BE ?

                        CODEC_ID_PCM_S24BE : CODEC_ID_PCM_S24LE;

                break;

            /* set values for old format before stsd version 1 appeared */

            case CODEC_ID_MACE3:

                sc->samples_per_frame = 6;

                sc->bytes_per_frame = 2*st->codec->channels;

                break;

            case CODEC_ID_MACE6:

                sc->samples_per_frame = 6;

                sc->bytes_per_frame = 1*st->codec->channels;

                break;

            case CODEC_ID_ADPCM_IMA_QT:

                sc->samples_per_frame = 64;

                sc->bytes_per_frame = 34*st->codec->channels;

                break;

            case CODEC_ID_GSM:

                sc->samples_per_frame = 160;

                sc->bytes_per_frame = 33;

                break;

            default:

                break;

            }



            bits_per_sample = av_get_bits_per_sample(st->codec->codec_id);

            if (bits_per_sample) {

                st->codec->bits_per_coded_sample = bits_per_sample;

                sc->sample_size = (bits_per_sample >> 3) * st->codec->channels;

            }

        } else if(st->codec->codec_type==CODEC_TYPE_SUBTITLE){

            st->codec->codec_id= id;

        } else {

            /* other codec type, just skip (rtp, mp4s, tmcd ...) */

            url_fskip(pb, size - (url_ftell(pb) - start_pos));

        }

        /* this will read extra atoms at the end (wave, alac, damr, avcC, SMI ...) */

        a.size = size - (url_ftell(pb) - start_pos);

        if (a.size > 8) {

            if (mov_read_default(c, pb, a) < 0)

                return -1;

        } else if (a.size > 0)

            url_fskip(pb, a.size);

    }



    if(st->codec->codec_type==CODEC_TYPE_AUDIO && st->codec->sample_rate==0 && sc->time_scale>1)

        st->codec->sample_rate= sc->time_scale;



    /* special codec parameters handling */

    switch (st->codec->codec_id) {

#ifdef CONFIG_DV_DEMUXER

    case CODEC_ID_DVAUDIO:

        c->dv_fctx = av_alloc_format_context();

        c->dv_demux = dv_init_demux(c->dv_fctx);

        if (!c->dv_demux) {

            av_log(c->fc, AV_LOG_ERROR, "dv demux context init error\n");

            return -1;

        }

        sc->dv_audio_container = 1;

        st->codec->codec_id = CODEC_ID_PCM_S16LE;

        break;

#endif

    /* no ifdef since parameters are always those */

    case CODEC_ID_AMR_WB:

        st->codec->sample_rate= 16000;

        st->codec->channels= 1; /* really needed */

        break;

    case CODEC_ID_QCELP:

    case CODEC_ID_AMR_NB:

        st->codec->frame_size= sc->samples_per_frame;

        st->codec->sample_rate= 8000;

        st->codec->channels= 1; /* really needed */

        break;

    case CODEC_ID_MP2:

    case CODEC_ID_MP3:

        st->codec->codec_type = CODEC_TYPE_AUDIO; /* force type after stsd for m1a hdlr */

        st->need_parsing = AVSTREAM_PARSE_FULL;

        break;

    case CODEC_ID_GSM:

    case CODEC_ID_ADPCM_MS:

    case CODEC_ID_ADPCM_IMA_WAV:

        st->codec->block_align = sc->bytes_per_frame;

        break;

    case CODEC_ID_ALAC:

        if (st->codec->extradata_size == 36)

            st->codec->frame_size = AV_RB32((st->codec->extradata+12));

        break;

    default:

        break;

    }



    return 0;

}

void ff_hevc_deblocking_boundary_strengths(HEVCContext *s, int x0, int y0,

                                           int log2_trafo_size)

{

    HEVCLocalContext *lc = &s->HEVClc;

    MvField *tab_mvf     = s->ref->tab_mvf;

    int log2_min_pu_size = s->sps->log2_min_pu_size;

    int log2_min_tu_size = s->sps->log2_min_tb_size;

    int min_pu_width     = s->sps->min_pu_width;

    int min_tu_width     = s->sps->min_tb_width;

    int is_intra = tab_mvf[(y0 >> log2_min_pu_size) * min_pu_width +

                           (x0 >> log2_min_pu_size)].is_intra;

    int i, j, bs;



    if (y0 > 0 && (y0 & 7) == 0) {

        int yp_pu = (y0 - 1) >> log2_min_pu_size;

        int yq_pu =  y0      >> log2_min_pu_size;

        int yp_tu = (y0 - 1) >> log2_min_tu_size;

        int yq_tu =  y0      >> log2_min_tu_size;



        for (i = 0; i < (1 << log2_trafo_size); i += 4) {

            int x_pu = (x0 + i) >> log2_min_pu_size;

            int x_tu = (x0 + i) >> log2_min_tu_size;

            MvField *top  = &tab_mvf[yp_pu * min_pu_width + x_pu];

            MvField *curr = &tab_mvf[yq_pu * min_pu_width + x_pu];

            uint8_t top_cbf_luma  = s->cbf_luma[yp_tu * min_tu_width + x_tu];

            uint8_t curr_cbf_luma = s->cbf_luma[yq_tu * min_tu_width + x_tu];

            RefPicList *top_refPicList = ff_hevc_get_ref_list(s, s->ref,

                                                              x0 + i, y0 - 1);



            bs = boundary_strength(s, curr, curr_cbf_luma,

                                   top, top_cbf_luma, top_refPicList, 1);

            if (!s->sh.slice_loop_filter_across_slices_enabled_flag &&

                lc->boundary_flags & BOUNDARY_UPPER_SLICE &&

                (y0 % (1 << s->sps->log2_ctb_size)) == 0)

                bs = 0;

            else if (!s->pps->loop_filter_across_tiles_enabled_flag &&

                     lc->boundary_flags & BOUNDARY_UPPER_TILE &&

                     (y0 % (1 << s->sps->log2_ctb_size)) == 0)

                bs = 0;

            if (bs)

                s->horizontal_bs[((x0 + i) + y0 * s->bs_width) >> 2] = bs;

        }

    }



    // bs for TU internal horizontal PU boundaries

    if (log2_trafo_size > s->sps->log2_min_pu_size && !is_intra)

        for (j = 8; j < (1 << log2_trafo_size); j += 8) {

            int yp_pu = (y0 + j - 1) >> log2_min_pu_size;

            int yq_pu = (y0 + j)     >> log2_min_pu_size;

            int yp_tu = (y0 + j - 1) >> log2_min_tu_size;

            int yq_tu = (y0 + j)     >> log2_min_tu_size;



            for (i = 0; i < (1 << log2_trafo_size); i += 4) {

                int x_pu = (x0 + i) >> log2_min_pu_size;

                int x_tu = (x0 + i) >> log2_min_tu_size;

                MvField *top  = &tab_mvf[yp_pu * min_pu_width + x_pu];

                MvField *curr = &tab_mvf[yq_pu * min_pu_width + x_pu];

                uint8_t top_cbf_luma  = s->cbf_luma[yp_tu * min_tu_width + x_tu];

                uint8_t curr_cbf_luma = s->cbf_luma[yq_tu * min_tu_width + x_tu];

                RefPicList *top_refPicList = ff_hevc_get_ref_list(s, s->ref,

                                                                  x0 + i,

                                                                  y0 + j - 1);



                bs = boundary_strength(s, curr, curr_cbf_luma,

                                       top, top_cbf_luma, top_refPicList, 0);

                if (bs)

                    s->horizontal_bs[((x0 + i) + (y0 + j) * s->bs_width) >> 2] = bs;

            }

        }



    // bs for vertical TU boundaries

    if (x0 > 0 && (x0 & 7) == 0) {

        int xp_pu = (x0 - 1) >> log2_min_pu_size;

        int xq_pu =  x0      >> log2_min_pu_size;

        int xp_tu = (x0 - 1) >> log2_min_tu_size;

        int xq_tu =  x0      >> log2_min_tu_size;



        for (i = 0; i < (1 << log2_trafo_size); i += 4) {

            int y_pu      = (y0 + i) >> log2_min_pu_size;

            int y_tu      = (y0 + i) >> log2_min_tu_size;

            MvField *left = &tab_mvf[y_pu * min_pu_width + xp_pu];

            MvField *curr = &tab_mvf[y_pu * min_pu_width + xq_pu];



            uint8_t left_cbf_luma = s->cbf_luma[y_tu * min_tu_width + xp_tu];

            uint8_t curr_cbf_luma = s->cbf_luma[y_tu * min_tu_width + xq_tu];

            RefPicList *left_refPicList = ff_hevc_get_ref_list(s, s->ref,

                                                               x0 - 1, y0 + i);



            bs = boundary_strength(s, curr, curr_cbf_luma,

                                   left, left_cbf_luma, left_refPicList, 1);

            if (!s->sh.slice_loop_filter_across_slices_enabled_flag &&

                lc->boundary_flags & BOUNDARY_LEFT_SLICE &&

                (x0 % (1 << s->sps->log2_ctb_size)) == 0)

                bs = 0;

            else if (!s->pps->loop_filter_across_tiles_enabled_flag &&

                     lc->boundary_flags & BOUNDARY_LEFT_TILE &&

                     (x0 % (1 << s->sps->log2_ctb_size)) == 0)

                bs = 0;

            if (bs)

                s->vertical_bs[(x0 >> 3) + ((y0 + i) >> 2) * s->bs_width] = bs;

        }

    }



    // bs for TU internal vertical PU boundaries

    if (log2_trafo_size > log2_min_pu_size && !is_intra)

        for (j = 0; j < (1 << log2_trafo_size); j += 4) {

            int y_pu = (y0 + j) >> log2_min_pu_size;

            int y_tu = (y0 + j) >> log2_min_tu_size;



            for (i = 8; i < (1 << log2_trafo_size); i += 8) {

                int xp_pu = (x0 + i - 1) >> log2_min_pu_size;

                int xq_pu = (x0 + i)     >> log2_min_pu_size;

                int xp_tu = (x0 + i - 1) >> log2_min_tu_size;

                int xq_tu = (x0 + i)     >> log2_min_tu_size;

                MvField *left = &tab_mvf[y_pu * min_pu_width + xp_pu];

                MvField *curr = &tab_mvf[y_pu * min_pu_width + xq_pu];

                uint8_t left_cbf_luma = s->cbf_luma[y_tu * min_tu_width + xp_tu];

                uint8_t curr_cbf_luma = s->cbf_luma[y_tu * min_tu_width + xq_tu];

                RefPicList *left_refPicList = ff_hevc_get_ref_list(s, s->ref,

                                                                   x0 + i - 1,

                                                                   y0 + j);



                bs = boundary_strength(s, curr, curr_cbf_luma,

                                       left, left_cbf_luma, left_refPicList, 0);

                if (bs)

                    s->vertical_bs[((x0 + i) >> 3) + ((y0 + j) >> 2) * s->bs_width] = bs;

            }

        }

}

int ffv1_init_slice_state(FFV1Context *f, FFV1Context *fs)

{

    int j;



    fs->plane_count  = f->plane_count;

    fs->transparency = f->transparency;

    for (j = 0; j < f->plane_count; j++) {

        PlaneContext *const p = &fs->plane[j];



        if (fs->ac) {

            if (!p->state)

                p->state = av_malloc(CONTEXT_SIZE * p->context_count *

                                     sizeof(uint8_t));

            if (!p->state)

                return AVERROR(ENOMEM);

        } else {

            if (!p->vlc_state)

                p->vlc_state = av_malloc(p->context_count * sizeof(VlcState));

            if (!p->vlc_state)

                return AVERROR(ENOMEM);

        }

    }



    if (fs->ac > 1) {

        //FIXME only redo if state_transition changed

        for (j = 1; j < 256; j++) {

            fs->c.one_state[j]        = f->state_transition[j];

            fs->c.zero_state[256 - j] = 256 - fs->c.one_state[j];

        }

    }



    return 0;

}

static int vdpau_vc1_start_frame(AVCodecContext *avctx,

                                 const uint8_t *buffer, uint32_t size)

{

    VC1Context * const v  = avctx->priv_data;

    MpegEncContext * const s = &v->s;

    Picture *pic          = s->current_picture_ptr;

    struct vdpau_picture_context *pic_ctx = pic->hwaccel_picture_private;

    VdpPictureInfoVC1 *info = &pic_ctx->info.vc1;

    VdpVideoSurface ref;



    /*  fill LvPictureInfoVC1 struct */

    info->forward_reference  = VDP_INVALID_HANDLE;

    info->backward_reference = VDP_INVALID_HANDLE;



    switch (s->pict_type) {

    case AV_PICTURE_TYPE_B:

        ref = ff_vdpau_get_surface_id(&s->next_picture.f);

        assert(ref != VDP_INVALID_HANDLE);

        info->backward_reference = ref;

        /* fall-through */

    case AV_PICTURE_TYPE_P:

        ref = ff_vdpau_get_surface_id(&s->last_picture.f);

        assert(ref != VDP_INVALID_HANDLE);

        info->forward_reference  = ref;

    }



    info->slice_count       = 0;

    if (v->bi_type)

        info->picture_type  = 4;

    else

        info->picture_type  = s->pict_type - 1 + s->pict_type / 3;



    info->frame_coding_mode = v->fcm ? (v->fcm + 1) : 0;

    info->postprocflag      = v->postprocflag;

    info->pulldown          = v->broadcast;

    info->interlace         = v->interlace;

    info->tfcntrflag        = v->tfcntrflag;

    info->finterpflag       = v->finterpflag;

    info->psf               = v->psf;

    info->dquant            = v->dquant;

    info->panscan_flag      = v->panscanflag;

    info->refdist_flag      = v->refdist_flag;

    info->quantizer         = v->quantizer_mode;

    info->extended_mv       = v->extended_mv;

    info->extended_dmv      = v->extended_dmv;

    info->overlap           = v->overlap;

    info->vstransform       = v->vstransform;

    info->loopfilter        = v->s.loop_filter;

    info->fastuvmc          = v->fastuvmc;

    info->range_mapy_flag   = v->range_mapy_flag;

    info->range_mapy        = v->range_mapy;

    info->range_mapuv_flag  = v->range_mapuv_flag;

    info->range_mapuv       = v->range_mapuv;

    /* Specific to simple/main profile only */

    info->multires          = v->multires;

    info->syncmarker        = v->resync_marker;

    info->rangered          = v->rangered | (v->rangeredfrm << 1);

    info->maxbframes        = v->s.max_b_frames;

    info->deblockEnable     = v->postprocflag & 1;

    info->pquant            = v->pq;



    return ff_vdpau_common_start_frame(pic_ctx, buffer, size);

}

static int cinvideo_decode_frame(AVCodecContext *avctx,

                                 void *data, int *data_size,

                                 AVPacket *avpkt)

{

    const uint8_t *buf = avpkt->data;

    int buf_size = avpkt->size;

    CinVideoContext *cin = avctx->priv_data;

    int i, y, palette_type, palette_colors_count, bitmap_frame_type, bitmap_frame_size;



    cin->frame.buffer_hints = FF_BUFFER_HINTS_VALID | FF_BUFFER_HINTS_PRESERVE | FF_BUFFER_HINTS_REUSABLE;

    if (avctx->reget_buffer(avctx, &cin->frame)) {

        av_log(cin->avctx, AV_LOG_ERROR, "delphinecinvideo: reget_buffer() failed to allocate a frame\n");

        return -1;

    }



    palette_type = buf[0];

    palette_colors_count = AV_RL16(buf+1);

    bitmap_frame_type = buf[3];

    buf += 4;



    bitmap_frame_size = buf_size - 4;



    /* handle palette */



    if (palette_type == 0) {

        for (i = 0; i < palette_colors_count; ++i) {

            cin->palette[i] = bytestream_get_le24(&buf);

            bitmap_frame_size -= 3;

        }

    } else {

        for (i = 0; i < palette_colors_count; ++i) {

            cin->palette[buf[0]] = AV_RL24(buf+1);

            buf += 4;

            bitmap_frame_size -= 4;

        }

    }

    memcpy(cin->frame.data[1], cin->palette, sizeof(cin->palette));

    cin->frame.palette_has_changed = 1;



    /* note: the decoding routines below assumes that surface.width = surface.pitch */

    switch (bitmap_frame_type) {

    case 9:

        cin_decode_rle(buf, bitmap_frame_size,

          cin->bitmap_table[CIN_CUR_BMP], cin->bitmap_size);

        break;

    case 34:

        cin_decode_rle(buf, bitmap_frame_size,

          cin->bitmap_table[CIN_CUR_BMP], cin->bitmap_size);

        cin_apply_delta_data(cin->bitmap_table[CIN_PRE_BMP],

          cin->bitmap_table[CIN_CUR_BMP], cin->bitmap_size);

        break;

    case 35:

        cin_decode_huffman(buf, bitmap_frame_size,

          cin->bitmap_table[CIN_INT_BMP], cin->bitmap_size);

        cin_decode_rle(cin->bitmap_table[CIN_INT_BMP], bitmap_frame_size,

          cin->bitmap_table[CIN_CUR_BMP], cin->bitmap_size);

        break;

    case 36:

        bitmap_frame_size = cin_decode_huffman(buf, bitmap_frame_size,

          cin->bitmap_table[CIN_INT_BMP], cin->bitmap_size);

        cin_decode_rle(cin->bitmap_table[CIN_INT_BMP], bitmap_frame_size,

          cin->bitmap_table[CIN_CUR_BMP], cin->bitmap_size);

        cin_apply_delta_data(cin->bitmap_table[CIN_PRE_BMP],

          cin->bitmap_table[CIN_CUR_BMP], cin->bitmap_size);

        break;

    case 37:

        cin_decode_huffman(buf, bitmap_frame_size,

          cin->bitmap_table[CIN_CUR_BMP], cin->bitmap_size);

        break;

    case 38:

        cin_decode_lzss(buf, bitmap_frame_size,

          cin->bitmap_table[CIN_CUR_BMP], cin->bitmap_size);

        break;

    case 39:

        cin_decode_lzss(buf, bitmap_frame_size,

          cin->bitmap_table[CIN_CUR_BMP], cin->bitmap_size);

        cin_apply_delta_data(cin->bitmap_table[CIN_PRE_BMP],

          cin->bitmap_table[CIN_CUR_BMP], cin->bitmap_size);

        break;

    }



    for (y = 0; y < cin->avctx->height; ++y)

        memcpy(cin->frame.data[0] + (cin->avctx->height - 1 - y) * cin->frame.linesize[0],

          cin->bitmap_table[CIN_CUR_BMP] + y * cin->avctx->width,

          cin->avctx->width);



    FFSWAP(uint8_t *, cin->bitmap_table[CIN_CUR_BMP], cin->bitmap_table[CIN_PRE_BMP]);



    *data_size = sizeof(AVFrame);

    *(AVFrame *)data = cin->frame;



    return buf_size;

}

static void RENAME(decode_rgb_frame)(FFV1Context *s, uint8_t *src[3], int w, int h, int stride[3])

{

    int x, y, p;

    TYPE *sample[4][2];

    int lbd    = s->avctx->bits_per_raw_sample <= 8;

    int bits   = s->avctx->bits_per_raw_sample > 0 ? s->avctx->bits_per_raw_sample : 8;

    int offset = 1 << bits;



    for (x = 0; x < 4; x++) {

        sample[x][0] = RENAME(s->sample_buffer) +  x * 2      * (w + 6) + 3;

        sample[x][1] = RENAME(s->sample_buffer) + (x * 2 + 1) * (w + 6) + 3;

    }



    s->run_index = 0;



    memset(RENAME(s->sample_buffer), 0, 8 * (w + 6) * sizeof(*RENAME(s->sample_buffer)));



    for (y = 0; y < h; y++) {

        for (p = 0; p < 3 + s->transparency; p++) {

            TYPE *temp = sample[p][0]; // FIXME: try a normal buffer



            sample[p][0] = sample[p][1];

            sample[p][1] = temp;



            sample[p][1][-1]= sample[p][0][0  ];

            sample[p][0][ w]= sample[p][0][w-1];

            if (lbd && s->slice_coding_mode == 0)

                RENAME(decode_line)(s, w, sample[p], (p + 1)/2, 9);

            else

                RENAME(decode_line)(s, w, sample[p], (p + 1)/2, bits + (s->slice_coding_mode != 1));

        }

        for (x = 0; x < w; x++) {

            int g = sample[0][1][x];

            int b = sample[1][1][x];

            int r = sample[2][1][x];

            int a = sample[3][1][x];



            if (s->slice_coding_mode != 1) {

                b -= offset;

                r -= offset;

                g -= (b * s->slice_rct_by_coef + r * s->slice_rct_ry_coef) >> 2;

                b += g;

                r += g;

            }



            if (lbd)

                *((uint32_t*)(src[0] + x*4 + stride[0]*y)) = b + (g<<8) + (r<<16) + (a<<24);

            else if (sizeof(TYPE) == 4) {

                *((uint16_t*)(src[0] + x*2 + stride[0]*y)) = g;

                *((uint16_t*)(src[1] + x*2 + stride[1]*y)) = b;

                *((uint16_t*)(src[2] + x*2 + stride[2]*y)) = r;

            } else {

                *((uint16_t*)(src[0] + x*2 + stride[0]*y)) = b;

                *((uint16_t*)(src[1] + x*2 + stride[1]*y)) = g;

                *((uint16_t*)(src[2] + x*2 + stride[2]*y)) = r;

            }

        }

    }

}

