        if (pps->chroma_qp_offset_list_len_minus1 && pps->chroma_qp_offset_list_len_minus1 >= 5) {

            av_log(avctx, AV_LOG_ERROR,

                   "chroma_qp_offset_list_len_minus1 shall be in the range [0, 5].\n");

