{

    FF_ALLOCZ_OR_GOTO(ctx->m.avctx, ctx->mb_rc, 8160*ctx->m.avctx->qmax*sizeof(RCEntry), fail);

    if (ctx->m.avctx->mb_decision != FF_MB_DECISION_RD)

        FF_ALLOCZ_OR_GOTO(ctx->m.avctx, ctx->mb_cmp, ctx->m.mb_num*sizeof(RCCMPEntry), fail);



    ctx->frame_bits = (ctx->cid_table->coding_unit_size - 640 - 4 - ctx->min_padding) * 8;

    ctx->qscale = 1;

    ctx->lambda = 2<<LAMBDA_FRAC_BITS; // qscale 2

    return 0;

 fail:

    return -1;

}

static int dirac_decode_frame(AVCodecContext *avctx, void *data, int *data_size, AVPacket *pkt)

{

    DiracContext *s     = avctx->priv_data;

    DiracFrame *picture = data;

    uint8_t *buf        = pkt->data;

    int buf_size        = pkt->size;

    int i, data_unit_size, buf_idx = 0;



    /* release unused frames */

    for (i = 0; i < MAX_FRAMES; i++)

        if (s->all_frames[i].avframe.data[0] && !s->all_frames[i].avframe.reference) {

            avctx->release_buffer(avctx, &s->all_frames[i].avframe);

            memset(s->all_frames[i].interpolated, 0, sizeof(s->all_frames[i].interpolated));

        }



    s->current_picture = NULL;

    *data_size = 0;



    /* end of stream, so flush delayed pics */

    if (buf_size == 0)

        return get_delayed_pic(s, (AVFrame *)data, data_size);



    for (;;) {

        /*[DIRAC_STD] Here starts the code from parse_info() defined in 9.6

          [DIRAC_STD] PARSE_INFO_PREFIX = "BBCD" as defined in ISO/IEC 646

          BBCD start code search */

        for (; buf_idx + DATA_UNIT_HEADER_SIZE < buf_size; buf_idx++) {

            if (buf[buf_idx  ] == 'B' && buf[buf_idx+1] == 'B' &&

                buf[buf_idx+2] == 'C' && buf[buf_idx+3] == 'D')

                break;

        }

        /* BBCD found or end of data */

        if (buf_idx + DATA_UNIT_HEADER_SIZE >= buf_size)

            break;



        data_unit_size = AV_RB32(buf+buf_idx+5);

        if (buf_idx + data_unit_size > buf_size || !data_unit_size) {

            if(buf_idx + data_unit_size > buf_size)

            av_log(s->avctx, AV_LOG_ERROR,

                   "Data unit with size %d is larger than input buffer, discarding\n",

                   data_unit_size);

            buf_idx += 4;

            continue;

        }

        /* [DIRAC_STD] dirac_decode_data_unit makes reference to the while defined in 9.3 inside the function parse_sequence() */

        if (dirac_decode_data_unit(avctx, buf+buf_idx, data_unit_size))

        {

            av_log(s->avctx, AV_LOG_ERROR,"Error in dirac_decode_data_unit\n");

            return -1;

        }

        buf_idx += data_unit_size;

    }



    if (!s->current_picture)

        return 0;



    if (s->current_picture->avframe.display_picture_number > s->frame_number) {

        DiracFrame *delayed_frame = remove_frame(s->delay_frames, s->frame_number);



        s->current_picture->avframe.reference |= DELAYED_PIC_REF;



        if (add_frame(s->delay_frames, MAX_DELAY, s->current_picture)) {

            int min_num = s->delay_frames[0]->avframe.display_picture_number;

            /* Too many delayed frames, so we display the frame with the lowest pts */

            av_log(avctx, AV_LOG_ERROR, "Delay frame overflow\n");

            delayed_frame = s->delay_frames[0];



            for (i = 1; s->delay_frames[i]; i++)

                if (s->delay_frames[i]->avframe.display_picture_number < min_num)

                    min_num = s->delay_frames[i]->avframe.display_picture_number;



            delayed_frame = remove_frame(s->delay_frames, min_num);

            add_frame(s->delay_frames, MAX_DELAY, s->current_picture);

        }



        if (delayed_frame) {

            delayed_frame->avframe.reference ^= DELAYED_PIC_REF;

            *(AVFrame*)data = delayed_frame->avframe;

            *data_size = sizeof(AVFrame);

        }

    } else if (s->current_picture->avframe.display_picture_number == s->frame_number) {

        /* The right frame at the right time :-) */

        *(AVFrame*)data = s->current_picture->avframe;

        *data_size = sizeof(AVFrame);

    }



    if (*data_size)

        s->frame_number = picture->avframe.display_picture_number + 1;



    return buf_idx;

}

static int opt_default(const char *opt, const char *arg){

    int type;

    const AVOption *o= NULL;

    int opt_types[]={AV_OPT_FLAG_VIDEO_PARAM, AV_OPT_FLAG_AUDIO_PARAM, 0, AV_OPT_FLAG_SUBTITLE_PARAM, 0};



    for(type=0; type<CODEC_TYPE_NB; type++){

        const AVOption *o2 = av_find_opt(avctx_opts[0], opt, NULL, opt_types[type], opt_types[type]);

        if(o2)

            o = av_set_string(avctx_opts[type], opt, arg);

    }

    if(!o)

        o = av_set_string(avformat_opts, opt, arg);

    if(!o)

        o = av_set_string(sws_opts, opt, arg);

    if(!o){

        if(opt[0] == 'a')

            o = av_set_string(avctx_opts[CODEC_TYPE_AUDIO], opt+1, arg);

        else if(opt[0] == 'v')

            o = av_set_string(avctx_opts[CODEC_TYPE_VIDEO], opt+1, arg);

        else if(opt[0] == 's')

            o = av_set_string(avctx_opts[CODEC_TYPE_SUBTITLE], opt+1, arg);

    }

    if(!o)

        return -1;



//    av_log(NULL, AV_LOG_ERROR, "%s:%s: %f 0x%0X\n", opt, arg, av_get_double(avctx_opts, opt, NULL), (int)av_get_int(avctx_opts, opt, NULL));



    //FIXME we should always use avctx_opts, ... for storing options so there wont be any need to keep track of whats set over this

    opt_names= av_realloc(opt_names, sizeof(void*)*(opt_name_count+1));

    opt_names[opt_name_count++]= o->name;



#ifdef CONFIG_FFM_MUXER

    /* disable generate of real time pts in ffm (need to be supressed anyway) */

    if(avctx_opts[0]->flags & CODEC_FLAG_BITEXACT)

        ffm_nopts = 1;

#endif



    if(avctx_opts[0]->debug)

        av_log_set_level(AV_LOG_DEBUG);

    return 0;

}

static int configure_output_video_filter(FilterGraph *fg, OutputFilter *ofilter, AVFilterInOut *out)

{

    char *pix_fmts;

    OutputStream *ost = ofilter->ost;

    OutputFile    *of = output_files[ost->file_index];

    AVFilterContext *last_filter = out->filter_ctx;

    int pad_idx = out->pad_idx;

    int ret;

    char name[255];



    snprintf(name, sizeof(name), "output stream %d:%d", ost->file_index, ost->index);

    ret = avfilter_graph_create_filter(&ofilter->filter,

                                       avfilter_get_by_name("buffersink"),

                                       name, NULL, NULL, fg->graph);

    if (ret < 0)

        return ret;



    if (!hw_device_ctx && (ofilter->width || ofilter->height)) {

        char args[255];

        AVFilterContext *filter;



        snprintf(args, sizeof(args), "%d:%d:0x%X",

                 ofilter->width, ofilter->height,

                 (unsigned)ost->sws_flags);

        snprintf(name, sizeof(name), "scaler for output stream %d:%d",

                 ost->file_index, ost->index);

        if ((ret = avfilter_graph_create_filter(&filter, avfilter_get_by_name("scale"),

                                                name, args, NULL, fg->graph)) < 0)

            return ret;

        if ((ret = avfilter_link(last_filter, pad_idx, filter, 0)) < 0)

            return ret;



        last_filter = filter;

        pad_idx = 0;

    }



    if ((pix_fmts = choose_pix_fmts(ofilter))) {

        AVFilterContext *filter;

        snprintf(name, sizeof(name), "pixel format for output stream %d:%d",

                 ost->file_index, ost->index);

        ret = avfilter_graph_create_filter(&filter,

                                           avfilter_get_by_name("format"),

                                           "format", pix_fmts, NULL, fg->graph);

        av_freep(&pix_fmts);

        if (ret < 0)

            return ret;

        if ((ret = avfilter_link(last_filter, pad_idx, filter, 0)) < 0)

            return ret;



        last_filter = filter;

        pad_idx     = 0;

    }



    if (ost->frame_rate.num) {

        AVFilterContext *fps;

        char args[255];



        snprintf(args, sizeof(args), "fps=%d/%d", ost->frame_rate.num,

                 ost->frame_rate.den);

        snprintf(name, sizeof(name), "fps for output stream %d:%d",

                 ost->file_index, ost->index);

        ret = avfilter_graph_create_filter(&fps, avfilter_get_by_name("fps"),

                                           name, args, NULL, fg->graph);

        if (ret < 0)

            return ret;



        ret = avfilter_link(last_filter, pad_idx, fps, 0);

        if (ret < 0)

            return ret;

        last_filter = fps;

        pad_idx = 0;

    }



    snprintf(name, sizeof(name), "trim for output stream %d:%d",

             ost->file_index, ost->index);

    ret = insert_trim(of->start_time, of->recording_time,

                      &last_filter, &pad_idx, name);

    if (ret < 0)

        return ret;





    if ((ret = avfilter_link(last_filter, pad_idx, ofilter->filter, 0)) < 0)

        return ret;



    return 0;

}

