static inline int sub_left_prediction(HYuvContext *s, uint8_t *dst,

                                      const uint8_t *src, int w, int left)

{

    int i;

    if (s->bps <= 8) {

        if (w < 32) {

            for (i = 0; i < w; i++) {

                const int temp = src[i];

                dst[i] = temp - left;

                left   = temp;

            }

            return left;

        } else {

            for (i = 0; i < 32; i++) {

                const int temp = src[i];

                dst[i] = temp - left;

                left   = temp;

            }

            s->llvidencdsp.diff_bytes(dst + 32, src + 32, src + 31, w - 32);

            return src[w-1];

        }

    } else {

        const uint16_t *src16 = (const uint16_t *)src;

        uint16_t       *dst16 = (      uint16_t *)dst;

        if (w < 32) {

            for (i = 0; i < w; i++) {

                const int temp = src16[i];

                dst16[i] = temp - left;

                left   = temp;

            }

            return left;

        } else {

            for (i = 0; i < 16; i++) {

                const int temp = src16[i];

                dst16[i] = temp - left;

                left   = temp;

            }

            s->hencdsp.diff_int16(dst16 + 16, src16 + 16, src16 + 15, s->n - 1, w - 16);

            return src16[w-1];

        }

    }

}

int ffurl_register_protocol(URLProtocol *protocol, int size)

{

    URLProtocol **p;

    if (size < sizeof(URLProtocol)) {

        URLProtocol *temp = av_mallocz(sizeof(URLProtocol));

        memcpy(temp, protocol, size);

        protocol = temp;

    }

    p = &first_protocol;

    while (*p != NULL)

        p = &(*p)->next;

    *p             = protocol;

    protocol->next = NULL;

    return 0;

}

static void rv34_idct_add_c(uint8_t *dst, int stride, DCTELEM *block){

    int      temp[16];

    uint8_t *cm = ff_cropTbl + MAX_NEG_CROP;

    int      i;



    rv34_row_transform(temp, block);

    memset(block, 0, 16*sizeof(DCTELEM));



    for(i = 0; i < 4; i++){

        const int z0 = 13*(temp[4*0+i] +    temp[4*2+i]) + 0x200;

        const int z1 = 13*(temp[4*0+i] -    temp[4*2+i]) + 0x200;

        const int z2 =  7* temp[4*1+i] - 17*temp[4*3+i];

        const int z3 = 17* temp[4*1+i] +  7*temp[4*3+i];



        dst[0] = cm[ dst[0] + ( (z0 + z3) >> 10 ) ];

        dst[1] = cm[ dst[1] + ( (z1 + z2) >> 10 ) ];

        dst[2] = cm[ dst[2] + ( (z1 - z2) >> 10 ) ];

        dst[3] = cm[ dst[3] + ( (z0 - z3) >> 10 ) ];



        dst  += stride;

    }

}

