static int vfw_read_header(AVFormatContext *s, AVFormatParameters *ap)

{

    struct vfw_ctx *ctx = s->priv_data;

    AVCodecContext *codec;

    AVStream *st;

    int devnum;

    int bisize;

    BITMAPINFO *bi;

    CAPTUREPARMS cparms;

    DWORD biCompression;

    WORD biBitCount;

    int width;

    int height;

    int ret;



    if(!ap->time_base.den) {

        av_log(s, AV_LOG_ERROR, "A time base must be specified.\n");

        return AVERROR_IO;

    }



    ctx->s = s;



    ctx->hwnd = capCreateCaptureWindow(NULL, 0, 0, 0, 0, 0, HWND_MESSAGE, 0);

    if(!ctx->hwnd) {

        av_log(s, AV_LOG_ERROR, "Could not create capture window.\n");

        return AVERROR_IO;

    }



    /* If atoi fails, devnum==0 and the default device is used */

    devnum = atoi(s->filename);



    ret = SendMessage(ctx->hwnd, WM_CAP_DRIVER_CONNECT, devnum, 0);

    if(!ret) {

        av_log(s, AV_LOG_ERROR, "Could not connect to device.\n");

        DestroyWindow(ctx->hwnd);

        return AVERROR(ENODEV);

    }



    SendMessage(ctx->hwnd, WM_CAP_SET_OVERLAY, 0, 0);

    SendMessage(ctx->hwnd, WM_CAP_SET_PREVIEW, 0, 0);



    ret = SendMessage(ctx->hwnd, WM_CAP_SET_CALLBACK_VIDEOSTREAM, 0,

                      (LPARAM) videostream_cb);

    if(!ret) {

        av_log(s, AV_LOG_ERROR, "Could not set video stream callback.\n");

        goto fail_io;

    }



    SetWindowLongPtr(ctx->hwnd, GWLP_USERDATA, (LONG_PTR) ctx);



    st = av_new_stream(s, 0);

    if(!st) {

        vfw_read_close(s);

        return AVERROR_NOMEM;

    }



    /* Set video format */

    bisize = SendMessage(ctx->hwnd, WM_CAP_GET_VIDEOFORMAT, 0, 0);

    if(!bisize)

        goto fail_io;

    bi = av_malloc(bisize);

    if(!bi) {

        vfw_read_close(s);

        return AVERROR_NOMEM;

    }

    ret = SendMessage(ctx->hwnd, WM_CAP_GET_VIDEOFORMAT, bisize, (LPARAM) bi);

    if(!ret)

        goto fail_bi;



    dump_bih(s, &bi->bmiHeader);



    width  = ap->width  ? ap->width  : bi->bmiHeader.biWidth ;

    height = ap->height ? ap->height : bi->bmiHeader.biHeight;

    bi->bmiHeader.biWidth  = width ;

    bi->bmiHeader.biHeight = height;



#if 0

    /* For testing yet unsupported compressions

     * Copy these values from user-supplied verbose information */

    bi->bmiHeader.biWidth       = 320;

    bi->bmiHeader.biHeight      = 240;

    bi->bmiHeader.biPlanes      = 1;

    bi->bmiHeader.biBitCount    = 12;

    bi->bmiHeader.biCompression = MKTAG('I','4','2','0');

    bi->bmiHeader.biSizeImage   = 115200;

    dump_bih(s, &bi->bmiHeader);

#endif



    ret = SendMessage(ctx->hwnd, WM_CAP_SET_VIDEOFORMAT, bisize, (LPARAM) bi);

    if(!ret) {

        av_log(s, AV_LOG_ERROR, "Could not set Video Format.\n");

        goto fail_bi;

    }



    biCompression = bi->bmiHeader.biCompression;

    biBitCount = bi->bmiHeader.biBitCount;



    av_free(bi);



    /* Set sequence setup */

    ret = SendMessage(ctx->hwnd, WM_CAP_GET_SEQUENCE_SETUP, sizeof(cparms),

                      (LPARAM) &cparms);

    if(!ret)

        goto fail_io;



    dump_captureparms(s, &cparms);



    cparms.fYield = 1; // Spawn a background thread

    cparms.dwRequestMicroSecPerFrame =

                               (ap->time_base.num*1000000) / ap->time_base.den;

    cparms.fAbortLeftMouse = 0;

    cparms.fAbortRightMouse = 0;

    cparms.fCaptureAudio = 0;

    cparms.vKeyAbort = 0;



    ret = SendMessage(ctx->hwnd, WM_CAP_SET_SEQUENCE_SETUP, sizeof(cparms),

                      (LPARAM) &cparms);

    if(!ret)

        goto fail_io;



    codec = st->codec;

    codec->time_base = ap->time_base;

    codec->codec_type = CODEC_TYPE_VIDEO;

    codec->width = width;

    codec->height = height;

    codec->pix_fmt = vfw_pixfmt(biCompression, biBitCount);

    if(codec->pix_fmt == PIX_FMT_NONE) {

        codec->codec_id = vfw_codecid(biCompression);

        if(codec->codec_id == CODEC_ID_NONE) {

            av_log(s, AV_LOG_ERROR, "Unknown compression type. "

                             "Please report verbose (-v 9) debug information.\n");

            vfw_read_close(s);

            return AVERROR_PATCHWELCOME;

        }

        codec->bits_per_coded_sample = biBitCount;

    } else {

        codec->codec_id = CODEC_ID_RAWVIDEO;

        if(biCompression == BI_RGB)

            codec->bits_per_coded_sample = biBitCount;

    }



    av_set_pts_info(st, 32, 1, 1000);



    ctx->mutex = CreateMutex(NULL, 0, NULL);

    if(!ctx->mutex) {

        av_log(s, AV_LOG_ERROR, "Could not create Mutex.\n" );

        goto fail_io;

    }

    ctx->event = CreateEvent(NULL, 1, 0, NULL);

    if(!ctx->event) {

        av_log(s, AV_LOG_ERROR, "Could not create Event.\n" );

        goto fail_io;

    }



    ret = SendMessage(ctx->hwnd, WM_CAP_SEQUENCE_NOFILE, 0, 0);

    if(!ret) {

        av_log(s, AV_LOG_ERROR, "Could not start capture sequence.\n" );

        goto fail_io;

    }



    return 0;



fail_bi:

    av_free(bi);



fail_io:

    vfw_read_close(s);

    return AVERROR_IO;

}

static int decode_wmv9(AVCodecContext *avctx, const uint8_t *buf, int buf_size,

                       int x, int y, int w, int h, int wmv9_mask)

{

    MSS2Context *ctx  = avctx->priv_data;

    MSS12Context *c   = &ctx->c;

    VC1Context *v     = avctx->priv_data;

    MpegEncContext *s = &v->s;

    AVFrame *f;

    int ret;



    ff_mpeg_flush(avctx);



    init_get_bits(&s->gb, buf, buf_size * 8);



    s->loop_filter = avctx->skip_loop_filter < AVDISCARD_ALL;



    if (ff_vc1_parse_frame_header(v, &s->gb) < 0) {

        av_log(v->s.avctx, AV_LOG_ERROR, "header error\n");

        return AVERROR_INVALIDDATA;

    }



    if (s->pict_type != AV_PICTURE_TYPE_I) {

        av_log(v->s.avctx, AV_LOG_ERROR, "expected I-frame\n");

        return AVERROR_INVALIDDATA;

    }



    avctx->pix_fmt = AV_PIX_FMT_YUV420P;



    if ((ret = ff_MPV_frame_start(s, avctx)) < 0) {

        av_log(v->s.avctx, AV_LOG_ERROR, "ff_MPV_frame_start error\n");

        avctx->pix_fmt = AV_PIX_FMT_RGB24;

        return ret;

    }



    ff_mpeg_er_frame_start(s);



    v->bits = buf_size * 8;



    v->end_mb_x = (w + 15) >> 4;

    s->end_mb_y = (h + 15) >> 4;

    if (v->respic & 1)

        v->end_mb_x = v->end_mb_x + 1 >> 1;

    if (v->respic & 2)

        s->end_mb_y = s->end_mb_y + 1 >> 1;



    ff_vc1_decode_blocks(v);



    ff_er_frame_end(&s->er);



    ff_MPV_frame_end(s);



    f = &s->current_picture.f;



    if (v->respic == 3) {

        ctx->dsp.upsample_plane(f->data[0], f->linesize[0], w,      h);

        ctx->dsp.upsample_plane(f->data[1], f->linesize[1], w >> 1, h >> 1);

        ctx->dsp.upsample_plane(f->data[2], f->linesize[2], w >> 1, h >> 1);

    } else if (v->respic)

        avpriv_request_sample(v->s.avctx,

                              "Asymmetric WMV9 rectangle subsampling");



    av_assert0(f->linesize[1] == f->linesize[2]);



    if (wmv9_mask != -1)

        ctx->dsp.mss2_blit_wmv9_masked(c->rgb_pic + y * c->rgb_stride + x * 3,

                                       c->rgb_stride, wmv9_mask,

                                       c->pal_pic + y * c->pal_stride + x,

                                       c->pal_stride,

                                       f->data[0], f->linesize[0],

                                       f->data[1], f->data[2], f->linesize[1],

                                       w, h);

    else

        ctx->dsp.mss2_blit_wmv9(c->rgb_pic + y * c->rgb_stride + x * 3,

                                c->rgb_stride,

                                f->data[0], f->linesize[0],

                                f->data[1], f->data[2], f->linesize[1],

                                w, h);



    avctx->pix_fmt = AV_PIX_FMT_RGB24;



    return 0;

}

yuv2rgb_1_c_template(SwsContext *c, const int16_t *buf0,
                     const int16_t *ubuf[2], const int16_t *vbuf[2],
                     const int16_t *abuf0, uint8_t *dest, int dstW,
                     int uvalpha, int y, enum PixelFormat target,
                     int hasAlpha)
{
    const int16_t *ubuf0 = ubuf[0], *vbuf0 = vbuf[0];
    int i;
    if (uvalpha < 2048) {
        for (i = 0; i < (dstW >> 1); i++) {
            int Y1 = buf0[i * 2]     >> 7;
            int Y2 = buf0[i * 2 + 1] >> 7;
            int U  = ubuf0[i]        >> 7;
            int V  = vbuf0[i]        >> 7;
            int A1, A2;
            const void *r =  c->table_rV[V],
                       *g = (c->table_gU[U] + c->table_gV[V]),
                       *b =  c->table_bU[U];
            if (hasAlpha) {
                A1 = abuf0[i * 2    ] >> 7;
                A2 = abuf0[i * 2 + 1] >> 7;
            }
            yuv2rgb_write(dest, i, Y1, Y2, hasAlpha ? A1 : 0, hasAlpha ? A2 : 0,
                          r, g, b, y, target, hasAlpha);
        }
    } else {
        const int16_t *ubuf1 = ubuf[1], *vbuf1 = vbuf[1];
        for (i = 0; i < (dstW >> 1); i++) {
            int Y1 =  buf0[i * 2]          >> 7;
            int Y2 =  buf0[i * 2 + 1]      >> 7;
            int U  = (ubuf0[i] + ubuf1[i]) >> 8;
            int V  = (vbuf0[i] + vbuf1[i]) >> 8;
            int A1, A2;
            const void *r =  c->table_rV[V],
                       *g = (c->table_gU[U] + c->table_gV[V]),
                       *b =  c->table_bU[U];
            if (hasAlpha) {
                A1 = abuf0[i * 2    ] >> 7;
                A2 = abuf0[i * 2 + 1] >> 7;
            }
            yuv2rgb_write(dest, i, Y1, Y2, hasAlpha ? A1 : 0, hasAlpha ? A2 : 0,
                          r, g, b, y, target, hasAlpha);
        }
    }
}

static AVStream * parse_media_type(AVFormatContext *s, AVStream *st, int sid,

                                   ff_asf_guid mediatype, ff_asf_guid subtype,

                                   ff_asf_guid formattype, int size)

{

    WtvContext *wtv = s->priv_data;

    AVIOContext *pb = wtv->pb;

    if (!ff_guidcmp(subtype, ff_mediasubtype_cpfilters_processed) &&

        !ff_guidcmp(formattype, ff_format_cpfilters_processed)) {

        ff_asf_guid actual_subtype;

        ff_asf_guid actual_formattype;



        if (size < 32) {

            av_log(s, AV_LOG_WARNING, "format buffer size underflow\n");

            avio_skip(pb, size);

            return NULL;

        }



        avio_skip(pb, size - 32);

        ff_get_guid(pb, &actual_subtype);

        ff_get_guid(pb, &actual_formattype);

        avio_seek(pb, -size, SEEK_CUR);



        st = parse_media_type(s, st, sid, mediatype, actual_subtype, actual_formattype, size - 32);

        avio_skip(pb, 32);

        return st;

    } else if (!ff_guidcmp(mediatype, ff_mediatype_audio)) {

        st = new_stream(s, st, sid, AVMEDIA_TYPE_AUDIO);

        if (!st)

            return NULL;

        if (!ff_guidcmp(formattype, ff_format_waveformatex)) {

            int ret = ff_get_wav_header(pb, st->codec, size);

            if (ret < 0)

                return NULL;

        } else {

            if (ff_guidcmp(formattype, ff_format_none))

                av_log(s, AV_LOG_WARNING, "unknown formattype:"FF_PRI_GUID"\n", FF_ARG_GUID(formattype));

            avio_skip(pb, size);

        }



        if (!memcmp(subtype + 4, (const uint8_t[]){FF_MEDIASUBTYPE_BASE_GUID}, 12)) {

            st->codec->codec_id = ff_wav_codec_get_id(AV_RL32(subtype), st->codec->bits_per_coded_sample);

        } else if (!ff_guidcmp(subtype, mediasubtype_mpeg1payload)) {

            if (st->codec->extradata && st->codec->extradata_size >= 22)

                parse_mpeg1waveformatex(st);

            else

                av_log(s, AV_LOG_WARNING, "MPEG1WAVEFORMATEX underflow\n");

        } else {

            st->codec->codec_id = ff_codec_guid_get_id(ff_codec_wav_guids, subtype);

            if (st->codec->codec_id == AV_CODEC_ID_NONE)

                av_log(s, AV_LOG_WARNING, "unknown subtype:"FF_PRI_GUID"\n", FF_ARG_GUID(subtype));

        }

        return st;

    } else if (!ff_guidcmp(mediatype, ff_mediatype_video)) {

        st = new_stream(s, st, sid, AVMEDIA_TYPE_VIDEO);

        if (!st)

            return NULL;

        if (!ff_guidcmp(formattype, ff_format_videoinfo2)) {

            int consumed = parse_videoinfoheader2(s, st);

            avio_skip(pb, FFMAX(size - consumed, 0));

        } else if (!ff_guidcmp(formattype, ff_format_mpeg2_video)) {

            int consumed = parse_videoinfoheader2(s, st);

            int count;

            avio_skip(pb, 4);

            count = avio_rl32(pb);

            avio_skip(pb, 12);

            if (count && ff_get_extradata(st->codec, pb, count) < 0) {

               ff_free_stream(s, st);

               return NULL;

            }

            consumed += 20 + count;

            avio_skip(pb, FFMAX(size - consumed, 0));

        } else {

            if (ff_guidcmp(formattype, ff_format_none))

                av_log(s, AV_LOG_WARNING, "unknown formattype:"FF_PRI_GUID"\n", FF_ARG_GUID(formattype));

            avio_skip(pb, size);

        }



        if (!memcmp(subtype + 4, (const uint8_t[]){FF_MEDIASUBTYPE_BASE_GUID}, 12)) {

            st->codec->codec_id = ff_codec_get_id(ff_codec_bmp_tags, AV_RL32(subtype));

        } else {

            st->codec->codec_id = ff_codec_guid_get_id(ff_video_guids, subtype);

        }

        if (st->codec->codec_id == AV_CODEC_ID_NONE)

            av_log(s, AV_LOG_WARNING, "unknown subtype:"FF_PRI_GUID"\n", FF_ARG_GUID(subtype));

        return st;

    } else if (!ff_guidcmp(mediatype, mediatype_mpeg2_pes) &&

               !ff_guidcmp(subtype, mediasubtype_dvb_subtitle)) {

        st = new_stream(s, st, sid, AVMEDIA_TYPE_SUBTITLE);

        if (!st)

            return NULL;

        if (ff_guidcmp(formattype, ff_format_none))

            av_log(s, AV_LOG_WARNING, "unknown formattype:"FF_PRI_GUID"\n", FF_ARG_GUID(formattype));

        avio_skip(pb, size);

        st->codec->codec_id = AV_CODEC_ID_DVB_SUBTITLE;

        return st;

    } else if (!ff_guidcmp(mediatype, mediatype_mstvcaption) &&

               (!ff_guidcmp(subtype, mediasubtype_teletext) || !ff_guidcmp(subtype, mediasubtype_dtvccdata))) {

        st = new_stream(s, st, sid, AVMEDIA_TYPE_SUBTITLE);

        if (!st)

            return NULL;

        if (ff_guidcmp(formattype, ff_format_none))

            av_log(s, AV_LOG_WARNING, "unknown formattype:"FF_PRI_GUID"\n", FF_ARG_GUID(formattype));

        avio_skip(pb, size);

        st->codec->codec_id = !ff_guidcmp(subtype, mediasubtype_teletext) ? AV_CODEC_ID_DVB_TELETEXT : AV_CODEC_ID_EIA_608;

        return st;

    } else if (!ff_guidcmp(mediatype, mediatype_mpeg2_sections) &&

               !ff_guidcmp(subtype, mediasubtype_mpeg2_sections)) {

        if (ff_guidcmp(formattype, ff_format_none))

            av_log(s, AV_LOG_WARNING, "unknown formattype:"FF_PRI_GUID"\n", FF_ARG_GUID(formattype));

        avio_skip(pb, size);

        return NULL;

    }



    av_log(s, AV_LOG_WARNING, "unknown media type, mediatype:"FF_PRI_GUID

                              ", subtype:"FF_PRI_GUID", formattype:"FF_PRI_GUID"\n",

                              FF_ARG_GUID(mediatype), FF_ARG_GUID(subtype), FF_ARG_GUID(formattype));

    avio_skip(pb, size);

    return NULL;

}

static void intra_predict_dc_4blk_8x8_msa(uint8_t *src, int32_t stride)

{

    uint8_t lp_cnt;

    uint32_t src0, src1, src3, src2 = 0;

    uint32_t out0, out1, out2, out3;

    v16u8 src_top;

    v8u16 add;

    v4u32 sum;



    src_top = LD_UB(src - stride);

    add = __msa_hadd_u_h((v16u8) src_top, (v16u8) src_top);

    sum = __msa_hadd_u_w(add, add);

    src0 = __msa_copy_u_w((v4i32) sum, 0);

    src1 = __msa_copy_u_w((v4i32) sum, 1);



    for (lp_cnt = 0; lp_cnt < 4; lp_cnt++) {

        src0 += src[lp_cnt * stride - 1];

        src2 += src[(4 + lp_cnt) * stride - 1];

    }



    src0 = (src0 + 4) >> 3;

    src3 = (src1 + src2 + 4) >> 3;

    src1 = (src1 + 2) >> 2;

    src2 = (src2 + 2) >> 2;

    out0 = src0 * 0x01010101;

    out1 = src1 * 0x01010101;

    out2 = src2 * 0x01010101;

    out3 = src3 * 0x01010101;



    for (lp_cnt = 4; lp_cnt--;) {

        SW(out0, src);

        SW(out1, (src + 4));

        SW(out2, (src + 4 * stride));

        SW(out3, (src + 4 * stride + 4));

        src += stride;

    }

}

static int init_poc(H264Context *h){

    MpegEncContext * const s = &h->s;

    const int max_frame_num= 1<<h->sps.log2_max_frame_num;

    int field_poc[2];



    h->frame_num_offset= h->prev_frame_num_offset;

    if(h->frame_num < h->prev_frame_num)

        h->frame_num_offset += max_frame_num;



    if(h->sps.poc_type==0){

        const int max_poc_lsb= 1<<h->sps.log2_max_poc_lsb;



        if     (h->poc_lsb < h->prev_poc_lsb && h->prev_poc_lsb - h->poc_lsb >= max_poc_lsb/2)

            h->poc_msb = h->prev_poc_msb + max_poc_lsb;

        else if(h->poc_lsb > h->prev_poc_lsb && h->prev_poc_lsb - h->poc_lsb < -max_poc_lsb/2)

            h->poc_msb = h->prev_poc_msb - max_poc_lsb;

        else

            h->poc_msb = h->prev_poc_msb;

//printf("poc: %d %d\n", h->poc_msb, h->poc_lsb);

        field_poc[0] =

        field_poc[1] = h->poc_msb + h->poc_lsb;

        if(s->picture_structure == PICT_FRAME)

            field_poc[1] += h->delta_poc_bottom;

    }else if(h->sps.poc_type==1){

        int abs_frame_num, expected_delta_per_poc_cycle, expectedpoc;

        int i;



        if(h->sps.poc_cycle_length != 0)

            abs_frame_num = h->frame_num_offset + h->frame_num;

        else

            abs_frame_num = 0;



        if(h->nal_ref_idc==0 && abs_frame_num > 0)

            abs_frame_num--;



        expected_delta_per_poc_cycle = 0;

        for(i=0; i < h->sps.poc_cycle_length; i++)

            expected_delta_per_poc_cycle += h->sps.offset_for_ref_frame[ i ]; //FIXME integrate during sps parse



        if(abs_frame_num > 0){

            int poc_cycle_cnt          = (abs_frame_num - 1) / h->sps.poc_cycle_length;

            int frame_num_in_poc_cycle = (abs_frame_num - 1) % h->sps.poc_cycle_length;



            expectedpoc = poc_cycle_cnt * expected_delta_per_poc_cycle;

            for(i = 0; i <= frame_num_in_poc_cycle; i++)

                expectedpoc = expectedpoc + h->sps.offset_for_ref_frame[ i ];

        } else

            expectedpoc = 0;



        if(h->nal_ref_idc == 0)

            expectedpoc = expectedpoc + h->sps.offset_for_non_ref_pic;



        field_poc[0] = expectedpoc + h->delta_poc[0];

        field_poc[1] = field_poc[0] + h->sps.offset_for_top_to_bottom_field;



        if(s->picture_structure == PICT_FRAME)

            field_poc[1] += h->delta_poc[1];

    }else{

        int poc= 2*(h->frame_num_offset + h->frame_num);



        if(!h->nal_ref_idc)

            poc--;



        field_poc[0]= poc;

        field_poc[1]= poc;

    }



    if(s->picture_structure != PICT_BOTTOM_FIELD) {

        s->current_picture_ptr->field_poc[0]= field_poc[0];

        s->current_picture_ptr->poc = field_poc[0];

    }

    if(s->picture_structure != PICT_TOP_FIELD) {

        s->current_picture_ptr->field_poc[1]= field_poc[1];

        s->current_picture_ptr->poc = field_poc[1];

    }

    if(!FIELD_PICTURE || !s->first_field) {

        Picture *cur = s->current_picture_ptr;

        cur->poc= FFMIN(cur->field_poc[0], cur->field_poc[1]);

    }



    return 0;

}

static int avui_encode_frame(AVCodecContext *avctx, AVPacket *pkt,

                             const AVFrame *pic, int *got_packet)

{

    uint8_t *dst, *src = pic->data[0];

    int i, j, skip, ret, size, interlaced;



    interlaced = avctx->field_order > AV_FIELD_PROGRESSIVE;



    if (avctx->height == 486) {

        skip = 10;

    } else {

        skip = 16;

    }

    size = 2 * avctx->width * (avctx->height + skip) + 8 * interlaced;

    if ((ret = ff_alloc_packet2(avctx, pkt, size)) < 0)

        return ret;

    dst = pkt->data;

    if (!(avctx->extradata = av_mallocz(24 + FF_INPUT_BUFFER_PADDING_SIZE)))

        return AVERROR(ENOMEM);

    avctx->extradata_size = 24;

    memcpy(avctx->extradata, "\0\0\0\x18""APRGAPRG0001", 16);

    if (interlaced) {

        avctx->extradata[19] = 2;

    } else {

        avctx->extradata[19] = 1;

        dst += avctx->width * skip;

    }



    avctx->coded_frame->reference = 0;

    avctx->coded_frame->key_frame = 1;

    avctx->coded_frame->pict_type = AV_PICTURE_TYPE_I;



    for (i = 0; i <= interlaced; i++) {

        if (interlaced && avctx->height == 486) {

            src = pic->data[0] + (1 - i) * pic->linesize[0];

        } else {

            src = pic->data[0] + i * pic->linesize[0];

        }

        dst += avctx->width * skip + 4 * i;

        for (j = 0; j < avctx->height; j += interlaced + 1) {

            memcpy(dst, src, avctx->width * 2);

            src += (interlaced + 1) * pic->linesize[0];

            dst += avctx->width * 2;

        }

    }



    pkt->flags |= AV_PKT_FLAG_KEY;

    *got_packet = 1;

    return 0;

}

int av_resample(AVResampleContext *c, short *dst, short *src, int *consumed, int src_size, int dst_size, int update_ctx){

    int dst_index, i;

    int index= c->index;

    int frac= c->frac;

    int dst_incr_frac= c->dst_incr % c->src_incr;

    int dst_incr=      c->dst_incr / c->src_incr;

    int compensation_distance= c->compensation_distance;



  if(compensation_distance == 0 && c->filter_length == 1 && c->phase_shift==0){

        int64_t index2= ((int64_t)index)<<32;

        int64_t incr= (1LL<<32) * c->dst_incr / c->src_incr;

        dst_size= FFMIN(dst_size, (src_size-1-index) * (int64_t)c->src_incr / c->dst_incr);



        for(dst_index=0; dst_index < dst_size; dst_index++){

            dst[dst_index] = src[index2>>32];

            index2 += incr;

        }

        frac += dst_index * dst_incr_frac;

        index += dst_index * dst_incr;

        index += frac / c->src_incr;

        frac %= c->src_incr;

  }else{

    for(dst_index=0; dst_index < dst_size; dst_index++){

        FELEM *filter= c->filter_bank + c->filter_length*(index & c->phase_mask);

        int sample_index= index >> c->phase_shift;

        FELEM2 val=0;



        if(sample_index < 0){

            for(i=0; i<c->filter_length; i++)

                val += src[FFABS(sample_index + i) % src_size] * filter[i];

        }else if(sample_index + c->filter_length > src_size){

            break;

        }else if(c->linear){

            FELEM2 v2=0;

            for(i=0; i<c->filter_length; i++){

                val += src[sample_index + i] * (FELEM2)filter[i];

                v2  += src[sample_index + i] * (FELEM2)filter[i + c->filter_length];

            }

            val+=(v2-val)*(FELEML)frac / c->src_incr;

        }else{

            for(i=0; i<c->filter_length; i++){

                val += src[sample_index + i] * (FELEM2)filter[i];

            }

        }



#ifdef CONFIG_RESAMPLE_AUDIOPHILE_KIDDY_MODE

        dst[dst_index] = av_clip_int16(lrintf(val));

#else

        val = (val + (1<<(FILTER_SHIFT-1)))>>FILTER_SHIFT;

        dst[dst_index] = (unsigned)(val + 32768) > 65535 ? (val>>31) ^ 32767 : val;

#endif



        frac += dst_incr_frac;

        index += dst_incr;

        if(frac >= c->src_incr){

            frac -= c->src_incr;

            index++;

        }



        if(dst_index + 1 == compensation_distance){

            compensation_distance= 0;

            dst_incr_frac= c->ideal_dst_incr % c->src_incr;

            dst_incr=      c->ideal_dst_incr / c->src_incr;

        }

    }

  }

    *consumed= FFMAX(index, 0) >> c->phase_shift;

    if(index>=0) index &= c->phase_mask;



    if(compensation_distance){

        compensation_distance -= dst_index;

        assert(compensation_distance > 0);

    }

    if(update_ctx){

        c->frac= frac;

        c->index= index;

        c->dst_incr= dst_incr_frac + c->src_incr*dst_incr;

        c->compensation_distance= compensation_distance;

    }

#if 0

    if(update_ctx && !c->compensation_distance){

#undef rand

        av_resample_compensate(c, rand() % (8000*2) - 8000, 8000*2);

av_log(NULL, AV_LOG_DEBUG, "%d %d %d\n", c->dst_incr, c->ideal_dst_incr, c->compensation_distance);

    }

#endif



    return dst_index;

}

