static inline void RENAME(yuv2yuvX)(int16_t *lumFilter, int16_t **lumSrc, int lumFilterSize,

				    int16_t *chrFilter, int16_t **chrSrc, int chrFilterSize,

				    uint8_t *dest, uint8_t *uDest, uint8_t *vDest, int dstW,

				    int16_t * lumMmxFilter, int16_t * chrMmxFilter)

{

#ifdef HAVE_MMX

	if(uDest != NULL)

	{

		asm volatile(

				YSCALEYUV2YV12X(0)

				:: "m" (-chrFilterSize), "r" (chrSrc+chrFilterSize),

				"r" (chrMmxFilter+chrFilterSize*4), "r" (uDest), "m" (dstW>>1)

				: "%eax", "%edx", "%esi"

			);



		asm volatile(

				YSCALEYUV2YV12X(4096)

				:: "m" (-chrFilterSize), "r" (chrSrc+chrFilterSize),

				"r" (chrMmxFilter+chrFilterSize*4), "r" (vDest), "m" (dstW>>1)

				: "%eax", "%edx", "%esi"

			);

	}



	asm volatile(

			YSCALEYUV2YV12X(0)

			:: "m" (-lumFilterSize), "r" (lumSrc+lumFilterSize),

			   "r" (lumMmxFilter+lumFilterSize*4), "r" (dest), "m" (dstW)

			: "%eax", "%edx", "%esi"

		);

#else

	//FIXME Optimize (just quickly writen not opti..)

	int i;

	for(i=0; i<dstW; i++)

	{

		int val=0;

		int j;

		for(j=0; j<lumFilterSize; j++)

			val += lumSrc[j][i] * lumFilter[j];



		dest[i]= MIN(MAX(val>>19, 0), 255);

	}



	if(uDest != NULL)

		for(i=0; i<(dstW>>1); i++)

		{

			int u=0;

			int v=0;

			int j;

			for(j=0; j<lumFilterSize; j++)

			{

				u += chrSrc[j][i] * chrFilter[j];

				v += chrSrc[j][i + 2048] * chrFilter[j];

			}



			uDest[i]= MIN(MAX(u>>19, 0), 255);

			vDest[i]= MIN(MAX(v>>19, 0), 255);

		}

#endif

}

static int huff_build12(VLC *vlc, uint8_t *len)

{

    HuffEntry he[4096];

    uint32_t codes[4096];

    uint8_t bits[4096];

    uint16_t syms[4096];

    uint32_t code;

    int i;



    for (i = 0; i < 4096; i++) {

        he[i].sym = 4095 - i;

        he[i].len = len[i];

        if (len[i] == 0)

            return AVERROR_INVALIDDATA;

    }

    AV_QSORT(he, 4096, HuffEntry, huff_cmp_len12);



    code = 1;

    for (i = 4095; i >= 0; i--) {

        codes[i] = code >> (32 - he[i].len);

        bits[i]  = he[i].len;

        syms[i]  = he[i].sym;

        code += 0x80000000u >> (he[i].len - 1);

    }



    ff_free_vlc(vlc);

    return ff_init_vlc_sparse(vlc, FFMIN(he[4095].len, 14), 4096,

                              bits,  sizeof(*bits),  sizeof(*bits),

                              codes, sizeof(*codes), sizeof(*codes),

                              syms,  sizeof(*syms),  sizeof(*syms), 0);

}

