            s->xvid_build= -1;

#endif

    }



    if(s->xvid_build==0 && s->divx_version==0 && s->lavc_build==0){

        if(s->codec_tag == AV_RL32("DIVX") && s->vo_type==0 && s->vol_control_parameters==0)

            s->divx_version= 400; //divx 4

    }



    if(s->xvid_build && s->divx_version){

        s->divx_version=

        s->divx_build= 0;

    }



    if(s->workaround_bugs&FF_BUG_AUTODETECT){

        if(s->codec_tag == AV_RL32("XVIX"))

            s->workaround_bugs|= FF_BUG_XVID_ILACE;



        if(s->codec_tag == AV_RL32("UMP4")){

            s->workaround_bugs|= FF_BUG_UMP4;

        }



        if(s->divx_version>=500 && s->divx_build<1814){

            s->workaround_bugs|= FF_BUG_QPEL_CHROMA;

        }



        if(s->divx_version>502 && s->divx_build<1814){

            s->workaround_bugs|= FF_BUG_QPEL_CHROMA2;

        }



        if(s->xvid_build && s->xvid_build<=3)

            s->padding_bug_score= 256*256*256*64;



        if(s->xvid_build && s->xvid_build<=1)

            s->workaround_bugs|= FF_BUG_QPEL_CHROMA;



        if(s->xvid_build && s->xvid_build<=12)

            s->workaround_bugs|= FF_BUG_EDGE;



        if(s->xvid_build && s->xvid_build<=32)

            s->workaround_bugs|= FF_BUG_DC_CLIP;



#define SET_QPEL_FUNC(postfix1, postfix2) \

    s->dsp.put_ ## postfix1 = ff_put_ ## postfix2;\

    s->dsp.put_no_rnd_ ## postfix1 = ff_put_no_rnd_ ## postfix2;\

    s->dsp.avg_ ## postfix1 = ff_avg_ ## postfix2;



        if(s->lavc_build && s->lavc_build<4653)

            s->workaround_bugs|= FF_BUG_STD_QPEL;



        if(s->lavc_build && s->lavc_build<4655)

            s->workaround_bugs|= FF_BUG_DIRECT_BLOCKSIZE;



        if(s->lavc_build && s->lavc_build<4670){

            s->workaround_bugs|= FF_BUG_EDGE;

        }



        if(s->lavc_build && s->lavc_build<=4712)

            s->workaround_bugs|= FF_BUG_DC_CLIP;



        if(s->divx_version)

            s->workaround_bugs|= FF_BUG_DIRECT_BLOCKSIZE;

//printf("padding_bug_score: %d\n", s->padding_bug_score);

        if(s->divx_version==501 && s->divx_build==20020416)

            s->padding_bug_score= 256*256*256*64;



        if(s->divx_version && s->divx_version<500){

            s->workaround_bugs|= FF_BUG_EDGE;

        }



        if(s->divx_version)

            s->workaround_bugs|= FF_BUG_HPEL_CHROMA;

#if 0

        if(s->divx_version==500)

            s->padding_bug_score= 256*256*256*64;



        /* very ugly XVID padding bug detection FIXME/XXX solve this differently

         * Let us hope this at least works.

         */

        if(   s->resync_marker==0 && s->data_partitioning==0 && s->divx_version==0

           && s->codec_id==CODEC_ID_MPEG4 && s->vo_type==0)

            s->workaround_bugs|= FF_BUG_NO_PADDING;



        if(s->lavc_build && s->lavc_build<4609) //FIXME not sure about the version num but a 4609 file seems ok

            s->workaround_bugs|= FF_BUG_NO_PADDING;

#endif

    }



    if(s->workaround_bugs& FF_BUG_STD_QPEL){

        SET_QPEL_FUNC(qpel_pixels_tab[0][ 5], qpel16_mc11_old_c)

        SET_QPEL_FUNC(qpel_pixels_tab[0][ 7], qpel16_mc31_old_c)

        SET_QPEL_FUNC(qpel_pixels_tab[0][ 9], qpel16_mc12_old_c)

        SET_QPEL_FUNC(qpel_pixels_tab[0][11], qpel16_mc32_old_c)

        SET_QPEL_FUNC(qpel_pixels_tab[0][13], qpel16_mc13_old_c)

        SET_QPEL_FUNC(qpel_pixels_tab[0][15], qpel16_mc33_old_c)



        SET_QPEL_FUNC(qpel_pixels_tab[1][ 5], qpel8_mc11_old_c)

        SET_QPEL_FUNC(qpel_pixels_tab[1][ 7], qpel8_mc31_old_c)

        SET_QPEL_FUNC(qpel_pixels_tab[1][ 9], qpel8_mc12_old_c)

        SET_QPEL_FUNC(qpel_pixels_tab[1][11], qpel8_mc32_old_c)

        SET_QPEL_FUNC(qpel_pixels_tab[1][13], qpel8_mc13_old_c)

        SET_QPEL_FUNC(qpel_pixels_tab[1][15], qpel8_mc33_old_c)

    }



    if(avctx->debug & FF_DEBUG_BUGS)

        av_log(s->avctx, AV_LOG_DEBUG, "bugs: %X lavc_build:%d xvid_build:%d divx_version:%d divx_build:%d %s\n",

               s->workaround_bugs, s->lavc_build, s->xvid_build, s->divx_version, s->divx_build,

               s->divx_packed ? "p" : "");



#if 0 // dump bits per frame / qp / complexity

{

    static FILE *f=NULL;

    if(!f) f=fopen("rate_qp_cplx.txt", "w");

    fprintf(f, "%d %d %f\n", buf_size, s->qscale, buf_size*(double)s->qscale);

}

#endif



#if HAVE_MMX

    if(s->codec_id == CODEC_ID_MPEG4 && s->xvid_build && avctx->idct_algo == FF_IDCT_AUTO && (mm_flags & FF_MM_MMX)){

        avctx->idct_algo= FF_IDCT_XVIDMMX;

        avctx->coded_width= 0; // force reinit

//        dsputil_init(&s->dsp, avctx);

        s->picture_number=0;

    }

#endif



        /* After H263 & mpeg4 header decode we have the height, width,*/

        /* and other parameters. So then we could init the picture   */

        /* FIXME: By the way H263 decoder is evolving it should have */

        /* an H263EncContext                                         */



    if (   s->width  != avctx->coded_width

        || s->height != avctx->coded_height) {

        /* H.263 could change picture size any time */

        ParseContext pc= s->parse_context; //FIXME move these demuxng hack to avformat

        s->parse_context.buffer=0;

        MPV_common_end(s);

        s->parse_context= pc;

    }

    if (!s->context_initialized) {

        avcodec_set_dimensions(avctx, s->width, s->height);



        goto retry;

    }



    if((s->codec_id==CODEC_ID_H263 || s->codec_id==CODEC_ID_H263P))

        s->gob_index = ff_h263_get_gob_height(s);



    // for hurry_up==5

    s->current_picture.pict_type= s->pict_type;

    s->current_picture.key_frame= s->pict_type == FF_I_TYPE;



    /* skip B-frames if we don't have reference frames */

    if(s->last_picture_ptr==NULL && (s->pict_type==FF_B_TYPE || s->dropable)) return get_consumed_bytes(s, buf_size);

    /* skip b frames if we are in a hurry */

    if(avctx->hurry_up && s->pict_type==FF_B_TYPE) return get_consumed_bytes(s, buf_size);

    if(   (avctx->skip_frame >= AVDISCARD_NONREF && s->pict_type==FF_B_TYPE)

       || (avctx->skip_frame >= AVDISCARD_NONKEY && s->pict_type!=FF_I_TYPE)

       ||  avctx->skip_frame >= AVDISCARD_ALL)

        return get_consumed_bytes(s, buf_size);

    /* skip everything if we are in a hurry>=5 */

    if(avctx->hurry_up>=5) return get_consumed_bytes(s, buf_size);



    if(s->next_p_frame_damaged){

        if(s->pict_type==FF_B_TYPE)

            return get_consumed_bytes(s, buf_size);

        else

            s->next_p_frame_damaged=0;

    }



    if((s->avctx->flags2 & CODEC_FLAG2_FAST) && s->pict_type==FF_B_TYPE){

        s->me.qpel_put= s->dsp.put_2tap_qpel_pixels_tab;

        s->me.qpel_avg= s->dsp.avg_2tap_qpel_pixels_tab;

    }else if((!s->no_rounding) || s->pict_type==FF_B_TYPE){

        s->me.qpel_put= s->dsp.put_qpel_pixels_tab;

        s->me.qpel_avg= s->dsp.avg_qpel_pixels_tab;

    }else{

        s->me.qpel_put= s->dsp.put_no_rnd_qpel_pixels_tab;

        s->me.qpel_avg= s->dsp.avg_qpel_pixels_tab;

    }



    if(MPV_frame_start(s, avctx) < 0)

        return -1;



#ifdef DEBUG

    av_log(avctx, AV_LOG_DEBUG, "qscale=%d\n", s->qscale);

#endif



    ff_er_frame_start(s);



    //the second part of the wmv2 header contains the MB skip bits which are stored in current_picture->mb_type

    //which is not available before MPV_frame_start()

    if (CONFIG_WMV2_DECODER && s->msmpeg4_version==5){

        ret = ff_wmv2_decode_secondary_picture_header(s);

        if(ret<0) return ret;

        if(ret==1) goto intrax8_decoded;

    }



    /* decode each macroblock */

    s->mb_x=0;

    s->mb_y=0;



    decode_slice(s);

    while(s->mb_y<s->mb_height){

        if(s->msmpeg4_version){

            if(s->slice_height==0 || s->mb_x!=0 || (s->mb_y%s->slice_height)!=0 || get_bits_count(&s->gb) > s->gb.size_in_bits)

                break;

        }else{

            if(ff_h263_resync(s)<0)

                break;

        }



        if(s->msmpeg4_version<4 && s->h263_pred)

            ff_mpeg4_clean_buffers(s);



        decode_slice(s);

    }



    if (s->h263_msmpeg4 && s->msmpeg4_version<4 && s->pict_type==FF_I_TYPE)

        if(!CONFIG_MSMPEG4_DECODER || msmpeg4_decode_ext_header(s, buf_size) < 0){

            s->error_status_table[s->mb_num-1]= AC_ERROR|DC_ERROR|MV_ERROR;

        }



    /* divx 5.01+ bistream reorder stuff */

    if(s->codec_id==CODEC_ID_MPEG4 && s->bitstream_buffer_size==0 && s->divx_packed){

        int current_pos= get_bits_count(&s->gb)>>3;

        int startcode_found=0;



        if(buf_size - current_pos > 5){

            int i;

            for(i=current_pos; i<buf_size-3; i++){

                if(buf[i]==0 && buf[i+1]==0 && buf[i+2]==1 && buf[i+3]==0xB6){

                    startcode_found=1;

                    break;

                }

            }

        }

        if(s->gb.buffer == s->bitstream_buffer && buf_size>20){ //xvid style

            startcode_found=1;

            current_pos=0;

        }



        if(startcode_found){

            s->bitstream_buffer= av_fast_realloc(

                s->bitstream_buffer,

                &s->allocated_bitstream_buffer_size,

                buf_size - current_pos + FF_INPUT_BUFFER_PADDING_SIZE);

            memcpy(s->bitstream_buffer, buf + current_pos, buf_size - current_pos);

            s->bitstream_buffer_size= buf_size - current_pos;

        }

    }



intrax8_decoded:

    ff_er_frame_end(s);



    MPV_frame_end(s);



assert(s->current_picture.pict_type == s->current_picture_ptr->pict_type);

assert(s->current_picture.pict_type == s->pict_type);

    if (s->pict_type == FF_B_TYPE || s->low_delay) {

        *pict= *(AVFrame*)s->current_picture_ptr;

    } else if (s->last_picture_ptr != NULL) {

        *pict= *(AVFrame*)s->last_picture_ptr;

    }



    if(s->last_picture_ptr || s->low_delay){

        *data_size = sizeof(AVFrame);

        ff_print_debug_info(s, pict);

    }



    /* Return the Picture timestamp as the frame number */

    /* we subtract 1 because it is added on utils.c     */

    avctx->frame_number = s->picture_number - 1;



#ifdef PRINT_FRAME_TIME

av_log(avctx, AV_LOG_DEBUG, "%"PRId64"\n", rdtsc()-time);

#endif



    return get_consumed_bytes(s, buf_size);

}

static av_always_inline int lcg_random(int previous_val)

{

    return previous_val * 1664525 + 1013904223;

}

static int open_slave(AVFormatContext *avf, char *slave, TeeSlave *tee_slave)

{

    int i, ret;

    AVDictionary *options = NULL;

    AVDictionaryEntry *entry;

    char *filename;

    char *format = NULL, *select = NULL;

    AVFormatContext *avf2 = NULL;

    AVStream *st, *st2;

    int stream_count;

    int fullret;

    char *subselect = NULL, *next_subselect = NULL, *first_subselect = NULL, *tmp_select = NULL;



    if ((ret = parse_slave_options(avf, slave, &options, &filename)) < 0)

        return ret;



#define STEAL_OPTION(option, field) do {                                \

        if ((entry = av_dict_get(options, option, NULL, 0))) {          \

            field = entry->value;                                       \

            entry->value = NULL; /* prevent it from being freed */      \

            av_dict_set(&options, option, NULL, 0);                     \

        }                                                               \

    } while (0)



    STEAL_OPTION("f", format);

    STEAL_OPTION("select", select);



    ret = avformat_alloc_output_context2(&avf2, NULL, format, filename);

    if (ret < 0)

        goto end;

    av_dict_copy(&avf2->metadata, avf->metadata, 0);

    avf2->opaque   = avf->opaque;

    avf2->io_open  = avf->io_open;

    avf2->io_close = avf->io_close;



    tee_slave->stream_map = av_calloc(avf->nb_streams, sizeof(*tee_slave->stream_map));

    if (!tee_slave->stream_map) {

        ret = AVERROR(ENOMEM);

        goto end;

    }



    stream_count = 0;

    for (i = 0; i < avf->nb_streams; i++) {

        st = avf->streams[i];

        if (select) {

            tmp_select = av_strdup(select);  // av_strtok is destructive so we regenerate it in each loop

            if (!tmp_select) {

                ret = AVERROR(ENOMEM);

                goto end;

            }

            fullret = 0;

            first_subselect = tmp_select;

            next_subselect = NULL;

            while (subselect = av_strtok(first_subselect, slave_select_sep, &next_subselect)) {

                first_subselect = NULL;



                ret = avformat_match_stream_specifier(avf, avf->streams[i], subselect);

                if (ret < 0) {

                    av_log(avf, AV_LOG_ERROR,

                           "Invalid stream specifier '%s' for output '%s'\n",

                           subselect, slave);

                    goto end;

                }

                if (ret != 0) {

                    fullret = 1; // match

                    break;

                }

            }

            av_freep(&tmp_select);



            if (fullret == 0) { /* no match */

                tee_slave->stream_map[i] = -1;

                continue;

            }

        }

        tee_slave->stream_map[i] = stream_count++;



        if (!(st2 = avformat_new_stream(avf2, NULL))) {

            ret = AVERROR(ENOMEM);

            goto end;

        }

        st2->id = st->id;

        st2->r_frame_rate        = st->r_frame_rate;

        st2->time_base           = st->time_base;

        st2->start_time          = st->start_time;

        st2->duration            = st->duration;

        st2->nb_frames           = st->nb_frames;

        st2->disposition         = st->disposition;

        st2->sample_aspect_ratio = st->sample_aspect_ratio;

        st2->avg_frame_rate      = st->avg_frame_rate;

        av_dict_copy(&st2->metadata, st->metadata, 0);

        if ((ret = avcodec_parameters_copy(st2->codecpar, st->codecpar)) < 0)

            goto end;

    }



    if (!(avf2->oformat->flags & AVFMT_NOFILE)) {

        if ((ret = avf2->io_open(avf2, &avf2->pb, filename, AVIO_FLAG_WRITE, NULL)) < 0) {

            av_log(avf, AV_LOG_ERROR, "Slave '%s': error opening: %s\n",

                   slave, av_err2str(ret));

            goto end;

        }

    }



    if ((ret = avformat_write_header(avf2, &options)) < 0) {

        av_log(avf, AV_LOG_ERROR, "Slave '%s': error writing header: %s\n",

               slave, av_err2str(ret));

        goto end;

    }



    tee_slave->avf = avf2;

    tee_slave->bsfs = av_calloc(avf2->nb_streams, sizeof(TeeSlave));

    if (!tee_slave->bsfs) {

        ret = AVERROR(ENOMEM);

        goto end;

    }



    entry = NULL;

    while (entry = av_dict_get(options, "bsfs", NULL, AV_DICT_IGNORE_SUFFIX)) {

        const char *spec = entry->key + strlen("bsfs");

        if (*spec) {

            if (strspn(spec, slave_bsfs_spec_sep) != 1) {

                av_log(avf, AV_LOG_ERROR,

                       "Specifier separator in '%s' is '%c', but only characters '%s' "

                       "are allowed\n", entry->key, *spec, slave_bsfs_spec_sep);

                return AVERROR(EINVAL);

            }

            spec++; /* consume separator */

        }



        for (i = 0; i < avf2->nb_streams; i++) {

            ret = avformat_match_stream_specifier(avf2, avf2->streams[i], spec);

            if (ret < 0) {

                av_log(avf, AV_LOG_ERROR,

                       "Invalid stream specifier '%s' in bsfs option '%s' for slave "

                       "output '%s'\n", spec, entry->key, filename);

                goto end;

            }



            if (ret > 0) {

                av_log(avf, AV_LOG_DEBUG, "spec:%s bsfs:%s matches stream %d of slave "

                       "output '%s'\n", spec, entry->value, i, filename);

                if (tee_slave->bsfs[i]) {

                    av_log(avf, AV_LOG_WARNING,

                           "Duplicate bsfs specification associated to stream %d of slave "

                           "output '%s', filters will be ignored\n", i, filename);

                    continue;

                }

                ret = parse_bsfs(avf, entry->value, &tee_slave->bsfs[i]);

                if (ret < 0) {

                    av_log(avf, AV_LOG_ERROR,

                           "Error parsing bitstream filter sequence '%s' associated to "

                           "stream %d of slave output '%s'\n", entry->value, i, filename);

                    goto end;

                }

            }

        }



        av_dict_set(&options, entry->key, NULL, 0);

    }



    if (options) {

        entry = NULL;

        while ((entry = av_dict_get(options, "", entry, AV_DICT_IGNORE_SUFFIX)))

            av_log(avf2, AV_LOG_ERROR, "Unknown option '%s'\n", entry->key);

        ret = AVERROR_OPTION_NOT_FOUND;

        goto end;

    }



end:

    av_free(format);

    av_free(select);

    av_dict_free(&options);

    av_freep(&tmp_select);

    return ret;

}

static av_cold int cuvid_decode_init(AVCodecContext *avctx)

{

    CuvidContext *ctx = avctx->priv_data;

    AVCUDADeviceContext *device_hwctx;

    AVHWDeviceContext *device_ctx;

    AVHWFramesContext *hwframe_ctx;

    CUVIDPARSERPARAMS cuparseinfo;

    CUVIDEOFORMATEX cuparse_ext;

    CUVIDSOURCEDATAPACKET seq_pkt;

    CUdevice device;

    CUcontext cuda_ctx = NULL;

    CUcontext dummy;

    const AVBitStreamFilter *bsf;

    int ret = 0;



    enum AVPixelFormat pix_fmts[3] = { AV_PIX_FMT_CUDA,

                                       AV_PIX_FMT_NV12,

                                       AV_PIX_FMT_NONE };



    ret = ff_get_format(avctx, pix_fmts);

    if (ret < 0) {

        av_log(avctx, AV_LOG_ERROR, "ff_get_format failed: %d\n", ret);

        return ret;

    }



    ctx->frame_queue = av_fifo_alloc(MAX_FRAME_COUNT * sizeof(CUVIDPARSERDISPINFO));

    if (!ctx->frame_queue) {

        ret = AVERROR(ENOMEM);

        goto error;

    }



    avctx->pix_fmt = ret;



    if (avctx->hw_frames_ctx) {

        ctx->hwframe = av_buffer_ref(avctx->hw_frames_ctx);

        if (!ctx->hwframe) {

            ret = AVERROR(ENOMEM);

            goto error;

        }



        hwframe_ctx = (AVHWFramesContext*)ctx->hwframe->data;



        ctx->hwdevice = av_buffer_ref(hwframe_ctx->device_ref);

        if (!ctx->hwdevice) {

            ret = AVERROR(ENOMEM);

            goto error;

        }



        device_ctx = hwframe_ctx->device_ctx;

        device_hwctx = device_ctx->hwctx;

        cuda_ctx = device_hwctx->cuda_ctx;

    } else {

        ctx->hwdevice = av_hwdevice_ctx_alloc(AV_HWDEVICE_TYPE_CUDA);

        if (!ctx->hwdevice) {

            av_log(avctx, AV_LOG_ERROR, "Error allocating hwdevice\n");

            ret = AVERROR(ENOMEM);

            goto error;

        }



        ret = CHECK_CU(cuInit(0));

        if (ret < 0)

            goto error;



        ret = CHECK_CU(cuDeviceGet(&device, 0));

        if (ret < 0)

            goto error;



        ret = CHECK_CU(cuCtxCreate(&cuda_ctx, CU_CTX_SCHED_BLOCKING_SYNC, device));

        if (ret < 0)

            goto error;



        device_ctx = (AVHWDeviceContext*)ctx->hwdevice->data;

        device_ctx->free = cuvid_ctx_free;



        device_hwctx = device_ctx->hwctx;

        device_hwctx->cuda_ctx = cuda_ctx;



        ret = CHECK_CU(cuCtxPopCurrent(&dummy));

        if (ret < 0)

            goto error;



        ret = av_hwdevice_ctx_init(ctx->hwdevice);

        if (ret < 0) {

            av_log(avctx, AV_LOG_ERROR, "av_hwdevice_ctx_init failed\n");

            goto error;

        }



        ctx->hwframe = av_hwframe_ctx_alloc(ctx->hwdevice);

        if (!ctx->hwframe) {

            av_log(avctx, AV_LOG_ERROR, "av_hwframe_ctx_alloc failed\n");

            ret = AVERROR(ENOMEM);

            goto error;

        }

    }



    memset(&cuparseinfo, 0, sizeof(cuparseinfo));

    memset(&cuparse_ext, 0, sizeof(cuparse_ext));

    memset(&seq_pkt, 0, sizeof(seq_pkt));



    cuparseinfo.pExtVideoInfo = &cuparse_ext;



    switch (avctx->codec->id) {






#if CONFIG_H264_CUVID_DECODER

    case AV_CODEC_ID_H264:

        cuparseinfo.CodecType = cudaVideoCodec_H264;



#if CONFIG_HEVC_CUVID_DECODER

    case AV_CODEC_ID_HEVC:

        cuparseinfo.CodecType = cudaVideoCodec_HEVC;



#if CONFIG_MJPEG_CUVID_DECODER

    case AV_CODEC_ID_MJPEG:

        cuparseinfo.CodecType = cudaVideoCodec_JPEG;



#if CONFIG_MPEG1_CUVID_DECODER

    case AV_CODEC_ID_MPEG1VIDEO:

        cuparseinfo.CodecType = cudaVideoCodec_MPEG1;



#if CONFIG_MPEG2_CUVID_DECODER

    case AV_CODEC_ID_MPEG2VIDEO:

        cuparseinfo.CodecType = cudaVideoCodec_MPEG2;



#if CONFIG_MPEG4_CUVID_DECODER

    case AV_CODEC_ID_MPEG4:




#if CONFIG_VP8_CUVID_DECODER

    case AV_CODEC_ID_VP8:

        cuparseinfo.CodecType = cudaVideoCodec_VP8;



#if CONFIG_VP9_CUVID_DECODER

    case AV_CODEC_ID_VP9:

        cuparseinfo.CodecType = cudaVideoCodec_VP9;



#if CONFIG_VC1_CUVID_DECODER

    case AV_CODEC_ID_VC1:

        cuparseinfo.CodecType = cudaVideoCodec_VC1;



    default:

        av_log(avctx, AV_LOG_ERROR, "Invalid CUVID codec!\n");

        return AVERROR_BUG;

    }



    if (avctx->codec->id == AV_CODEC_ID_H264 || avctx->codec->id == AV_CODEC_ID_HEVC) {

        if (avctx->codec->id == AV_CODEC_ID_H264)

            bsf = av_bsf_get_by_name("h264_mp4toannexb");

        else

            bsf = av_bsf_get_by_name("hevc_mp4toannexb");



        if (!bsf) {

            ret = AVERROR_BSF_NOT_FOUND;

            goto error;

        }

        if (ret = av_bsf_alloc(bsf, &ctx->bsf)) {

            goto error;

        }

        if (((ret = avcodec_parameters_from_context(ctx->bsf->par_in, avctx)) < 0) || ((ret = av_bsf_init(ctx->bsf)) < 0)) {

            av_bsf_free(&ctx->bsf);

            goto error;

        }



        cuparse_ext.format.seqhdr_data_length = ctx->bsf->par_out->extradata_size;

        memcpy(cuparse_ext.raw_seqhdr_data,

               ctx->bsf->par_out->extradata,

               FFMIN(sizeof(cuparse_ext.raw_seqhdr_data), ctx->bsf->par_out->extradata_size));

    } else if (avctx->extradata_size > 0) {

        cuparse_ext.format.seqhdr_data_length = avctx->extradata_size;

        memcpy(cuparse_ext.raw_seqhdr_data,

               avctx->extradata,

               FFMIN(sizeof(cuparse_ext.raw_seqhdr_data), avctx->extradata_size));

    }



    cuparseinfo.ulMaxNumDecodeSurfaces = MAX_FRAME_COUNT;

    cuparseinfo.ulMaxDisplayDelay = 4;

    cuparseinfo.pUserData = avctx;

    cuparseinfo.pfnSequenceCallback = cuvid_handle_video_sequence;

    cuparseinfo.pfnDecodePicture = cuvid_handle_picture_decode;

    cuparseinfo.pfnDisplayPicture = cuvid_handle_picture_display;



    ret = CHECK_CU(cuCtxPushCurrent(cuda_ctx));

    if (ret < 0)

        goto error;



    ret = cuvid_test_dummy_decoder(avctx, &cuparseinfo);

    if (ret < 0)

        goto error;



    ret = CHECK_CU(cuvidCreateVideoParser(&ctx->cuparser, &cuparseinfo));

    if (ret < 0)

        goto error;



    seq_pkt.payload = cuparse_ext.raw_seqhdr_data;

    seq_pkt.payload_size = cuparse_ext.format.seqhdr_data_length;



    if (seq_pkt.payload && seq_pkt.payload_size) {

        ret = CHECK_CU(cuvidParseVideoData(ctx->cuparser, &seq_pkt));

        if (ret < 0)

            goto error;

    }



    ret = CHECK_CU(cuCtxPopCurrent(&dummy));

    if (ret < 0)

        goto error;



    return 0;



error:

    cuvid_decode_end(avctx);

    return ret;

}

static int tcp_wait_fd(int fd, int write)

{

    int ev = write ? POLLOUT : POLLIN;

    struct pollfd p = { .fd = fd, .events = ev, .revents = 0 };

    int ret;



    ret = poll(&p, 1, 100);

    return ret < 0 ? ff_neterrno() : p.revents & ev ? 0 : AVERROR(EAGAIN);

}

static int file_check(URLContext *h, int mask)

{

#if HAVE_ACCESS && defined(R_OK)

    int ret = 0;

    if (access(h->filename, F_OK) < 0)

        return AVERROR(errno);

    if (mask&AVIO_FLAG_READ)

        if (access(h->filename, R_OK) >= 0)

            ret |= AVIO_FLAG_READ;

    if (mask&AVIO_FLAG_WRITE)

        if (access(h->filename, W_OK) >= 0)

            ret |= AVIO_FLAG_WRITE;

#else

    struct stat st;

    int ret = stat(h->filename, &st);

    if (ret < 0)

        return AVERROR(errno);



    ret |= st.st_mode&S_IRUSR ? mask&AVIO_FLAG_READ  : 0;

    ret |= st.st_mode&S_IWUSR ? mask&AVIO_FLAG_WRITE : 0;

#endif

    return ret;

}

static int rv10_decode_packet(AVCodecContext *avctx, 

                             uint8_t *buf, int buf_size)

{

    MpegEncContext *s = avctx->priv_data;

    int i, mb_count, mb_pos, left;



    init_get_bits(&s->gb, buf, buf_size*8);

#if 0

    for(i=0; i<buf_size*8 && i<100; i++)

        printf("%d", get_bits1(&s->gb));

    printf("\n");

    return 0;

#endif

    if(s->codec_id ==CODEC_ID_RV10)

        mb_count = rv10_decode_picture_header(s);

    else

        mb_count = rv20_decode_picture_header(s);

    if (mb_count < 0) {

        av_log(s->avctx, AV_LOG_ERROR, "HEADER ERROR\n");

        return -1;

    }



    if (s->mb_x >= s->mb_width ||

        s->mb_y >= s->mb_height) {

        av_log(s->avctx, AV_LOG_ERROR, "POS ERROR %d %d\n", s->mb_x, s->mb_y);

        return -1;

    }

    mb_pos = s->mb_y * s->mb_width + s->mb_x;

    left = s->mb_width * s->mb_height - mb_pos;

    if (mb_count > left) {

        av_log(s->avctx, AV_LOG_ERROR, "COUNT ERROR\n");

        return -1;

    }

//if(s->pict_type == P_TYPE) return 0;



    if (s->mb_x == 0 && s->mb_y == 0) {

        if(MPV_frame_start(s, avctx) < 0)

            return -1;

    }



#ifdef DEBUG

    printf("qscale=%d\n", s->qscale);

#endif



    /* default quantization values */

    if(s->codec_id== CODEC_ID_RV10){

        if(s->mb_y==0) s->first_slice_line=1;

    }else{

        s->first_slice_line=1;    

        s->resync_mb_x= s->mb_x;

        s->resync_mb_y= s->mb_y;

    }

    if(s->h263_aic){

        s->y_dc_scale_table= 

        s->c_dc_scale_table= ff_aic_dc_scale_table;

    }else{

        s->y_dc_scale_table=

        s->c_dc_scale_table= ff_mpeg1_dc_scale_table;

    }

    s->y_dc_scale= s->y_dc_scale_table[ s->qscale ];

    s->c_dc_scale= s->c_dc_scale_table[ s->qscale ];



    s->rv10_first_dc_coded[0] = 0;

    s->rv10_first_dc_coded[1] = 0;

    s->rv10_first_dc_coded[2] = 0;



    s->block_wrap[0]=

    s->block_wrap[1]=

    s->block_wrap[2]=

    s->block_wrap[3]= s->mb_width*2 + 2;

    s->block_wrap[4]=

    s->block_wrap[5]= s->mb_width + 2;

    ff_init_block_index(s);

    /* decode each macroblock */

    for(i=0;i<mb_count;i++) {

        int ret;

        ff_update_block_index(s);

#ifdef DEBUG

        printf("**mb x=%d y=%d\n", s->mb_x, s->mb_y);

#endif



	s->dsp.clear_blocks(s->block[0]);

        s->mv_dir = MV_DIR_FORWARD;

        s->mv_type = MV_TYPE_16X16; 

        ret=ff_h263_decode_mb(s, s->block);



        if (ret == SLICE_ERROR) {

            av_log(s->avctx, AV_LOG_ERROR, "ERROR at MB %d %d\n", s->mb_x, s->mb_y);

            return -1;

        }

        ff_h263_update_motion_val(s);

        MPV_decode_mb(s, s->block);

        if (++s->mb_x == s->mb_width) {

            s->mb_x = 0;

            s->mb_y++;

            ff_init_block_index(s);

        }

        if(s->mb_x == s->resync_mb_x)

            s->first_slice_line=0;

        if(ret == SLICE_END) break;

    }



    return buf_size;

}

static void RENAME(extract_even)(const uint8_t *src, uint8_t *dst, x86_reg count)

{

    dst +=   count;

    src += 2*count;

    count= - count;



#if COMPILE_TEMPLATE_MMX

    if(count <= -16) {

        count += 15;

        __asm__ volatile(

            "pcmpeqw       %%mm7, %%mm7        \n\t"

            "psrlw            $8, %%mm7        \n\t"

            "1:                                \n\t"

            "movq -30(%1, %0, 2), %%mm0        \n\t"

            "movq -22(%1, %0, 2), %%mm1        \n\t"

            "movq -14(%1, %0, 2), %%mm2        \n\t"

            "movq  -6(%1, %0, 2), %%mm3        \n\t"

            "pand          %%mm7, %%mm0        \n\t"

            "pand          %%mm7, %%mm1        \n\t"

            "pand          %%mm7, %%mm2        \n\t"

            "pand          %%mm7, %%mm3        \n\t"

            "packuswb      %%mm1, %%mm0        \n\t"

            "packuswb      %%mm3, %%mm2        \n\t"

            MOVNTQ"        %%mm0,-15(%2, %0)   \n\t"

            MOVNTQ"        %%mm2,- 7(%2, %0)   \n\t"

            "add             $16, %0           \n\t"

            " js 1b                            \n\t"

            : "+r"(count)

            : "r"(src), "r"(dst)

        );

        count -= 15;

    }

#endif

    while(count<0) {

        dst[count]= src[2*count];

        count++;

    }

}

static void intra_predict_horiz_16x16_msa(uint8_t *src, int32_t src_stride,

                                          uint8_t *dst, int32_t dst_stride)

{

    uint32_t row;

    uint8_t inp0, inp1, inp2, inp3;

    v16u8 src0, src1, src2, src3;



    for (row = 4; row--;) {

        inp0 = src[0];

        src += src_stride;

        inp1 = src[0];

        src += src_stride;

        inp2 = src[0];

        src += src_stride;

        inp3 = src[0];

        src += src_stride;



        src0 = (v16u8) __msa_fill_b(inp0);

        src1 = (v16u8) __msa_fill_b(inp1);

        src2 = (v16u8) __msa_fill_b(inp2);

        src3 = (v16u8) __msa_fill_b(inp3);



        ST_UB4(src0, src1, src2, src3, dst, dst_stride);

        dst += (4 * dst_stride);

    }

}

int read_file(const char *filename, char **bufptr, size_t *size)

{

    FILE *f = fopen(filename, "rb");



    if (!f) {

        av_log(NULL, AV_LOG_ERROR, "Cannot read file '%s': %s\n", filename, strerror(errno));

        return AVERROR(errno);

    }

    fseek(f, 0, SEEK_END);

    *size = ftell(f);

    fseek(f, 0, SEEK_SET);

    *bufptr = av_malloc(*size + 1);

    if (!*bufptr) {

        av_log(NULL, AV_LOG_ERROR, "Could not allocate file buffer\n");

        fclose(f);

        return AVERROR(ENOMEM);

    }

    fread(*bufptr, 1, *size, f);

    (*bufptr)[*size++] = '\0';



    fclose(f);

    return 0;

}

int64_t ff_gen_search(AVFormatContext *s, int stream_index, int64_t target_ts,

                      int64_t pos_min, int64_t pos_max, int64_t pos_limit,

                      int64_t ts_min, int64_t ts_max, int flags, int64_t *ts_ret,

                      int64_t (*read_timestamp)(struct AVFormatContext *, int , int64_t *, int64_t ))

{

    int64_t pos, ts;

    int64_t start_pos, filesize;

    int no_change;



    av_dlog(s, "gen_seek: %d %s\n", stream_index, av_ts2str(target_ts));



    if(ts_min == AV_NOPTS_VALUE){

        pos_min = s->data_offset;

        ts_min = ff_read_timestamp(s, stream_index, &pos_min, INT64_MAX, read_timestamp);

        if (ts_min == AV_NOPTS_VALUE)

            return -1;

    }



    if(ts_min >= target_ts){

        *ts_ret= ts_min;

        return pos_min;

    }



    if(ts_max == AV_NOPTS_VALUE){

        int step= 1024;

        filesize = avio_size(s->pb);

        pos_max = filesize - 1;

        do{

            pos_max = FFMAX(0, pos_max - step);

            ts_max = ff_read_timestamp(s, stream_index, &pos_max, pos_max + step, read_timestamp);

            step += step;

        }while(ts_max == AV_NOPTS_VALUE && pos_max > 0);

        if (ts_max == AV_NOPTS_VALUE)

            return -1;



        for(;;){

            int64_t tmp_pos= pos_max + 1;

            int64_t tmp_ts= ff_read_timestamp(s, stream_index, &tmp_pos, INT64_MAX, read_timestamp);

            if(tmp_ts == AV_NOPTS_VALUE)

                break;

            ts_max= tmp_ts;

            pos_max= tmp_pos;

            if(tmp_pos >= filesize)

                break;

        }

        pos_limit= pos_max;

    }



    if(ts_max <= target_ts){

        *ts_ret= ts_max;

        return pos_max;

    }



    if(ts_min > ts_max){

        return -1;

    }else if(ts_min == ts_max){

        pos_limit= pos_min;

    }



    no_change=0;

    while (pos_min < pos_limit) {

        av_dlog(s, "pos_min=0x%"PRIx64" pos_max=0x%"PRIx64" dts_min=%s dts_max=%s\n",

                pos_min, pos_max, av_ts2str(ts_min), av_ts2str(ts_max));

        assert(pos_limit <= pos_max);



        if(no_change==0){

            int64_t approximate_keyframe_distance= pos_max - pos_limit;

            // interpolate position (better than dichotomy)

            pos = av_rescale(target_ts - ts_min, pos_max - pos_min, ts_max - ts_min)

                + pos_min - approximate_keyframe_distance;

        }else if(no_change==1){

            // bisection, if interpolation failed to change min or max pos last time

            pos = (pos_min + pos_limit)>>1;

        }else{

            /* linear search if bisection failed, can only happen if there

               are very few or no keyframes between min/max */

            pos=pos_min;

        }

        if(pos <= pos_min)

            pos= pos_min + 1;

        else if(pos > pos_limit)

            pos= pos_limit;

        start_pos= pos;



        ts = ff_read_timestamp(s, stream_index, &pos, INT64_MAX, read_timestamp); //may pass pos_limit instead of -1

        if(pos == pos_max)

            no_change++;

        else

            no_change=0;

        av_dlog(s, "%"PRId64" %"PRId64" %"PRId64" / %s %s %s target:%s limit:%"PRId64" start:%"PRId64" noc:%d\n",

                pos_min, pos, pos_max,

                av_ts2str(ts_min), av_ts2str(ts), av_ts2str(ts_max), av_ts2str(target_ts),

                pos_limit, start_pos, no_change);

        if(ts == AV_NOPTS_VALUE){

            av_log(s, AV_LOG_ERROR, "read_timestamp() failed in the middle\n");

            return -1;

        }

        assert(ts != AV_NOPTS_VALUE);

        if (target_ts <= ts) {

            pos_limit = start_pos - 1;

            pos_max = pos;

            ts_max = ts;

        }

        if (target_ts >= ts) {

            pos_min = pos;

            ts_min = ts;

        }

    }



    pos = (flags & AVSEEK_FLAG_BACKWARD) ? pos_min : pos_max;

    ts  = (flags & AVSEEK_FLAG_BACKWARD) ?  ts_min :  ts_max;

#if 0

    pos_min = pos;

    ts_min = ff_read_timestamp(s, stream_index, &pos_min, INT64_MAX, read_timestamp);

    pos_min++;

    ts_max = ff_read_timestamp(s, stream_index, &pos_min, INT64_MAX, read_timestamp);

    av_dlog(s, "pos=0x%"PRIx64" %s<=%s<=%s\n",

            pos, av_ts2str(ts_min), av_ts2str(target_ts), av_ts2str(ts_max));

#endif

    *ts_ret= ts;

    return pos;

}

static inline int get_amv(Mpeg4DecContext *ctx, int n)

{

    MpegEncContext *s = &ctx->m;

    int x, y, mb_v, sum, dx, dy, shift;

    int len     = 1 << (s->f_code + 4);

    const int a = s->sprite_warping_accuracy;



    if (s->workaround_bugs & FF_BUG_AMV)

        len >>= s->quarter_sample;



    if (s->real_sprite_warping_points == 1) {

        if (ctx->divx_version == 500 && ctx->divx_build == 413)

            sum = s->sprite_offset[0][n] / (1 << (a - s->quarter_sample));

        else

            sum = RSHIFT(s->sprite_offset[0][n] << s->quarter_sample, a);

    } else {

        dx    = s->sprite_delta[n][0];

        dy    = s->sprite_delta[n][1];

        shift = ctx->sprite_shift[0];

        if (n)

            dy -= 1 << (shift + a + 1);

        else

            dx -= 1 << (shift + a + 1);

        mb_v = s->sprite_offset[0][n] + dx * s->mb_x * 16 + dy * s->mb_y * 16;



        sum = 0;

        for (y = 0; y < 16; y++) {

            int v;



            v = mb_v + dy * y;

            // FIXME optimize

            for (x = 0; x < 16; x++) {

                sum += v >> shift;

                v   += dx;

            }

        }

        sum = RSHIFT(sum, a + 8 - s->quarter_sample);

    }



    if (sum < -len)

        sum = -len;

    else if (sum >= len)

        sum = len - 1;



    return sum;

}

static void ready_codebook(vorbis_enc_codebook *cb)

{

    int i;



    ff_vorbis_len2vlc(cb->lens, cb->codewords, cb->nentries);



    if (!cb->lookup) {

        cb->pow2 = cb->dimentions = NULL;

    } else {

        int vals = cb_lookup_vals(cb->lookup, cb->ndimentions, cb->nentries);

        cb->dimentions = av_malloc(sizeof(float) * cb->nentries * cb->ndimentions);

        cb->pow2 = av_mallocz(sizeof(float) * cb->nentries);

        for (i = 0; i < cb->nentries; i++) {

            float last = 0;

            int j;

            int div = 1;

            for (j = 0; j < cb->ndimentions; j++) {

                int off;

                if (cb->lookup == 1)

                    off = (i / div) % vals; // lookup type 1

                else

                    off = i * cb->ndimentions + j; // lookup type 2



                cb->dimentions[i * cb->ndimentions + j] = last + cb->min + cb->quantlist[off] * cb->delta;

                if (cb->seq_p)

                    last = cb->dimentions[i * cb->ndimentions + j];

                cb->pow2[i] += cb->dimentions[i * cb->ndimentions + j] * cb->dimentions[i * cb->ndimentions + j];

                div *= vals;

            }

            cb->pow2[i] /= 2.;

        }

    }

}

static int adx_decode_frame(AVCodecContext *avctx, void *data,

                            int *got_frame_ptr, AVPacket *avpkt)

{

    int buf_size        = avpkt->size;

    ADXContext *c       = avctx->priv_data;

    int16_t *samples;

    const uint8_t *buf  = avpkt->data;

    int num_blocks, ch, ret;



    if (c->eof) {

        *got_frame_ptr = 0;

        return buf_size;

    }



    if(AV_RB16(buf) == 0x8000){

        int header_size;

        if ((ret = avpriv_adx_decode_header(avctx, buf,

                                            buf_size, &header_size,

                                            c->coeff)) < 0) {

            av_log(avctx, AV_LOG_ERROR, "error parsing ADX header\n");


        }

        c->channels = avctx->channels;

        if(buf_size < header_size)


        buf += header_size;

        buf_size -= header_size;

    }





    /* calculate number of blocks in the packet */

    num_blocks = buf_size / (BLOCK_SIZE * c->channels);



    /* if the packet is not an even multiple of BLOCK_SIZE, check for an EOF

       packet */

    if (!num_blocks || buf_size % (BLOCK_SIZE * avctx->channels)) {

        if (buf_size >= 4 && (AV_RB16(buf) & 0x8000)) {

            c->eof = 1;

            *got_frame_ptr = 0;

            return avpkt->size;

        }


    }



    /* get output buffer */

    c->frame.nb_samples = num_blocks * BLOCK_SAMPLES;

    if ((ret = avctx->get_buffer(avctx, &c->frame)) < 0) {

        av_log(avctx, AV_LOG_ERROR, "get_buffer() failed\n");

        return ret;

    }

    samples = (int16_t *)c->frame.data[0];



    while (num_blocks--) {

        for (ch = 0; ch < c->channels; ch++) {

            if (adx_decode(c, samples + ch, buf, ch)) {

                c->eof = 1;

                buf = avpkt->data + avpkt->size;

                break;

            }

            buf_size -= BLOCK_SIZE;

            buf      += BLOCK_SIZE;

        }

        samples += BLOCK_SAMPLES * c->channels;

    }



    *got_frame_ptr   = 1;

    *(AVFrame *)data = c->frame;



    return buf - avpkt->data;

}

static int gif_read_image(GifState *s, AVFrame *frame)

{

    int left, top, width, height, bits_per_pixel, code_size, flags;

    int is_interleaved, has_local_palette, y, pass, y1, linesize, pal_size;

    uint32_t *ptr, *pal, *px, *pr, *ptr1;

    int ret;

    uint8_t *idx;



    /* At least 9 bytes of Image Descriptor. */

    if (bytestream2_get_bytes_left(&s->gb) < 9)

        return AVERROR_INVALIDDATA;



    left   = bytestream2_get_le16u(&s->gb);

    top    = bytestream2_get_le16u(&s->gb);

    width  = bytestream2_get_le16u(&s->gb);

    height = bytestream2_get_le16u(&s->gb);

    flags  = bytestream2_get_byteu(&s->gb);

    is_interleaved = flags & 0x40;

    has_local_palette = flags & 0x80;

    bits_per_pixel = (flags & 0x07) + 1;



    av_dlog(s->avctx, "image x=%d y=%d w=%d h=%d\n", left, top, width, height);



    if (has_local_palette) {

        pal_size = 1 << bits_per_pixel;



        if (bytestream2_get_bytes_left(&s->gb) < pal_size * 3)

            return AVERROR_INVALIDDATA;



        gif_read_palette(s, s->local_palette, pal_size);

        pal = s->local_palette;

    } else {

        if (!s->has_global_palette) {

            av_log(s->avctx, AV_LOG_ERROR, "picture doesn't have either global or local palette.\n");

            return AVERROR_INVALIDDATA;

        }



        pal = s->global_palette;

    }



    if (s->keyframe) {

        if (s->transparent_color_index == -1 && s->has_global_palette) {

            /* transparency wasn't set before the first frame, fill with background color */

            gif_fill(frame, s->bg_color);

        } else {

            /* otherwise fill with transparent color.

             * this is necessary since by default picture filled with 0x80808080. */

            gif_fill(frame, s->trans_color);

        }

    }



    /* verify that all the image is inside the screen dimensions */

    if (left + width > s->screen_width ||

        top + height > s->screen_height) {

        av_log(s->avctx, AV_LOG_ERROR, "image is outside the screen dimensions.\n");

        return AVERROR_INVALIDDATA;

    }

    if (width <= 0 || height <= 0) {

        av_log(s->avctx, AV_LOG_ERROR, "Invalid image dimensions.\n");

        return AVERROR_INVALIDDATA;

    }



    /* process disposal method */

    if (s->gce_prev_disposal == GCE_DISPOSAL_BACKGROUND) {

        gif_fill_rect(frame, s->stored_bg_color, s->gce_l, s->gce_t, s->gce_w, s->gce_h);

    } else if (s->gce_prev_disposal == GCE_DISPOSAL_RESTORE) {

        gif_copy_img_rect(s->stored_img, (uint32_t *)frame->data[0],

            frame->linesize[0] / sizeof(uint32_t), s->gce_l, s->gce_t, s->gce_w, s->gce_h);

    }



    s->gce_prev_disposal = s->gce_disposal;



    if (s->gce_disposal != GCE_DISPOSAL_NONE) {

        s->gce_l = left;  s->gce_t = top;

        s->gce_w = width; s->gce_h = height;



        if (s->gce_disposal == GCE_DISPOSAL_BACKGROUND) {

            if (s->transparent_color_index >= 0)

                s->stored_bg_color = s->trans_color;

            else

                s->stored_bg_color = s->bg_color;

        } else if (s->gce_disposal == GCE_DISPOSAL_RESTORE) {

            av_fast_malloc(&s->stored_img, &s->stored_img_size, frame->linesize[0] * frame->height);

            if (!s->stored_img)

                return AVERROR(ENOMEM);



            gif_copy_img_rect((uint32_t *)frame->data[0], s->stored_img,

                frame->linesize[0] / sizeof(uint32_t), left, top, width, height);

        }

    }



    /* Expect at least 2 bytes: 1 for lzw code size and 1 for block size. */

    if (bytestream2_get_bytes_left(&s->gb) < 2)

        return AVERROR_INVALIDDATA;



    /* now get the image data */

    code_size = bytestream2_get_byteu(&s->gb);

    if ((ret = ff_lzw_decode_init(s->lzw, code_size, s->gb.buffer,

                                  bytestream2_get_bytes_left(&s->gb), FF_LZW_GIF)) < 0) {

        av_log(s->avctx, AV_LOG_ERROR, "LZW init failed\n");

        return ret;

    }



    /* read all the image */

    linesize = frame->linesize[0] / sizeof(uint32_t);

    ptr1 = (uint32_t *)frame->data[0] + top * linesize + left;

    ptr = ptr1;

    pass = 0;

    y1 = 0;

    for (y = 0; y < height; y++) {

        int count = ff_lzw_decode(s->lzw, s->idx_line, width);

        if (count != width) {

            if (count)

                av_log(s->avctx, AV_LOG_ERROR, "LZW decode failed\n");

            goto decode_tail;

        }



        pr = ptr + width;



        for (px = ptr, idx = s->idx_line; px < pr; px++, idx++) {

            if (*idx != s->transparent_color_index)

                *px = pal[*idx];

        }



        if (is_interleaved) {

            switch(pass) {

            default:

            case 0:

            case 1:

                y1 += 8;

                ptr += linesize * 8;

                if (y1 >= height) {

                    y1 = pass ? 2 : 4;

                    ptr = ptr1 + linesize * y1;

                    pass++;

                }

                break;

            case 2:

                y1 += 4;

                ptr += linesize * 4;

                if (y1 >= height) {

                    y1 = 1;

                    ptr = ptr1 + linesize;

                    pass++;

                }

                break;

            case 3:

                y1 += 2;

                ptr += linesize * 2;

                break;

            }

        } else {

            ptr += linesize;

        }

    }



 decode_tail:

    /* read the garbage data until end marker is found */

    ff_lzw_decode_tail(s->lzw);



    /* Graphic Control Extension's scope is single frame.

     * Remove its influence. */

    s->transparent_color_index = -1;

    s->gce_disposal = GCE_DISPOSAL_NONE;



    return 0;

}

static int decode_slice_thread(AVCodecContext *avctx, void *arg, int jobnr, int threadnr)

{

    ProresContext *ctx = avctx->priv_data;

    SliceContext *slice = &ctx->slices[jobnr];

    const uint8_t *buf = slice->data;

    AVFrame *pic = ctx->frame;

    int i, hdr_size, qscale, log2_chroma_blocks_per_mb;

    int luma_stride, chroma_stride;

    int y_data_size, u_data_size, v_data_size, a_data_size;

    uint8_t *dest_y, *dest_u, *dest_v, *dest_a;

    int16_t qmat_luma_scaled[64];

    int16_t qmat_chroma_scaled[64];

    int mb_x_shift;



    slice->ret = -1;

    //av_log(avctx, AV_LOG_INFO, "slice %d mb width %d mb x %d y %d\n",

    //       jobnr, slice->mb_count, slice->mb_x, slice->mb_y);



    // slice header

    hdr_size = buf[0] >> 3;

    qscale = av_clip(buf[1], 1, 224);

    qscale = qscale > 128 ? qscale - 96 << 2: qscale;

    y_data_size = AV_RB16(buf + 2);

    u_data_size = AV_RB16(buf + 4);

    v_data_size = slice->data_size - y_data_size - u_data_size - hdr_size;

    if (hdr_size > 7) v_data_size = AV_RB16(buf + 6);

    a_data_size = slice->data_size - y_data_size - u_data_size -

                  v_data_size - hdr_size;



    if (y_data_size < 0 || u_data_size < 0 || v_data_size < 0

        || hdr_size+y_data_size+u_data_size+v_data_size > slice->data_size){

        av_log(avctx, AV_LOG_ERROR, "invalid plane data size\n");

        return -1;

    }



    buf += hdr_size;



    for (i = 0; i < 64; i++) {

        qmat_luma_scaled  [i] = ctx->qmat_luma  [i] * qscale;

        qmat_chroma_scaled[i] = ctx->qmat_chroma[i] * qscale;

    }



    if (ctx->frame_type == 0) {

        luma_stride   = pic->linesize[0];

        chroma_stride = pic->linesize[1];

    } else {

        luma_stride   = pic->linesize[0] << 1;

        chroma_stride = pic->linesize[1] << 1;

    }



    if (avctx->pix_fmt == AV_PIX_FMT_YUV444P10 || avctx->pix_fmt == AV_PIX_FMT_YUVA444P10) {

        mb_x_shift = 5;

        log2_chroma_blocks_per_mb = 2;

    } else {

        mb_x_shift = 4;

        log2_chroma_blocks_per_mb = 1;

    }



    dest_y = pic->data[0] + (slice->mb_y << 4) * luma_stride + (slice->mb_x << 5);

    dest_u = pic->data[1] + (slice->mb_y << 4) * chroma_stride + (slice->mb_x << mb_x_shift);

    dest_v = pic->data[2] + (slice->mb_y << 4) * chroma_stride + (slice->mb_x << mb_x_shift);

    dest_a = pic->data[3] + (slice->mb_y << 4) * luma_stride + (slice->mb_x << 5);



    if (ctx->frame_type && ctx->first_field ^ ctx->frame->top_field_first) {

        dest_y += pic->linesize[0];

        dest_u += pic->linesize[1];

        dest_v += pic->linesize[2];

        dest_a += pic->linesize[3];

    }



    decode_slice_luma(avctx, slice, (uint16_t*)dest_y, luma_stride,

                      buf, y_data_size, qmat_luma_scaled);



    if (!(avctx->flags & CODEC_FLAG_GRAY)) {

        decode_slice_chroma(avctx, slice, (uint16_t*)dest_u, chroma_stride,

                            buf + y_data_size, u_data_size,

                            qmat_chroma_scaled, log2_chroma_blocks_per_mb);

        decode_slice_chroma(avctx, slice, (uint16_t*)dest_v, chroma_stride,

                            buf + y_data_size + u_data_size, v_data_size,

                            qmat_chroma_scaled, log2_chroma_blocks_per_mb);

    }

    /* decode alpha plane if available */

    if (ctx->alpha_info && dest_a && a_data_size)

        decode_slice_alpha(ctx, (uint16_t*)dest_a, luma_stride,

                           buf + y_data_size + u_data_size + v_data_size,

                           a_data_size, slice->mb_count);



    slice->ret = 0;

    return 0;

}

static void flush_buffered(AVFormatContext *s1, int last)

{

    RTPMuxContext *s = s1->priv_data;

    if (s->buf_ptr != s->buf) {

        // If only sending one single NAL unit, skip the aggregation framing

        if (s->buffered_nals == 1)

            ff_rtp_send_data(s1, s->buf + 4, s->buf_ptr - s->buf - 4, last);

        else

            ff_rtp_send_data(s1, s->buf, s->buf_ptr - s->buf, last);

    }

    s->buf_ptr = s->buf;

    s->buffered_nals = 0;

}

static int vp8_lossy_decode_frame(AVCodecContext *avctx, AVFrame *p,
                                  int *got_frame, uint8_t *data_start,
                                  unsigned int data_size)
{
    WebPContext *s = avctx->priv_data;
    AVPacket pkt;
    int ret;
    if (!s->initialized) {
        ff_vp8_decode_init(avctx);
        s->initialized = 1;
    }
    avctx->pix_fmt = s->has_alpha ? AV_PIX_FMT_YUVA420P : AV_PIX_FMT_YUV420P;
    s->lossless = 0;
    if (data_size > INT_MAX) {
        av_log(avctx, AV_LOG_ERROR, "unsupported chunk size\n");
        return AVERROR_PATCHWELCOME;
    }
    av_init_packet(&pkt);
    pkt.data = data_start;
    pkt.size = data_size;
    ret = ff_vp8_decode_frame(avctx, p, got_frame, &pkt);
    if (ret < 0)
        return ret;
    update_canvas_size(avctx, avctx->width, avctx->height);
    if (s->has_alpha) {
        ret = vp8_lossy_decode_alpha(avctx, p, s->alpha_data,
                                     s->alpha_data_size);
        if (ret < 0)
            return ret;
    }
    return ret;
}

static int v4l2_send_frame(AVCodecContext *avctx, const AVFrame *frame)

{

    V4L2m2mContext *s = avctx->priv_data;

    V4L2Context *const output = &s->output;



    return ff_v4l2_context_enqueue_frame(output, frame);

}

static int vp8_decode_frame(AVCodecContext *avctx, void *data, int *data_size,

                            AVPacket *avpkt)

{

    VP8Context *s = avctx->priv_data;

    int ret, mb_x, mb_y, i, y, referenced;

    enum AVDiscard skip_thresh;

    AVFrame *curframe;



    if ((ret = decode_frame_header(s, avpkt->data, avpkt->size)) < 0)

        return ret;



    referenced = s->update_last || s->update_golden == VP56_FRAME_CURRENT

                                || s->update_altref == VP56_FRAME_CURRENT;



    skip_thresh = !referenced ? AVDISCARD_NONREF :

                    !s->keyframe ? AVDISCARD_NONKEY : AVDISCARD_ALL;



    if (avctx->skip_frame >= skip_thresh) {

        s->invisible = 1;

        goto skip_decode;

    }



    for (i = 0; i < 4; i++)

        if (&s->frames[i] != s->framep[VP56_FRAME_PREVIOUS] &&

            &s->frames[i] != s->framep[VP56_FRAME_GOLDEN] &&

            &s->frames[i] != s->framep[VP56_FRAME_GOLDEN2]) {

            curframe = s->framep[VP56_FRAME_CURRENT] = &s->frames[i];

            break;

        }

    if (curframe->data[0])

        avctx->release_buffer(avctx, curframe);



    curframe->key_frame = s->keyframe;

    curframe->pict_type = s->keyframe ? FF_I_TYPE : FF_P_TYPE;

    curframe->reference = referenced ? 3 : 0;

    if ((ret = avctx->get_buffer(avctx, curframe))) {

        av_log(avctx, AV_LOG_ERROR, "get_buffer() failed!\n");

        return ret;

    }



    // Given that arithmetic probabilities are updated every frame, it's quite likely

    // that the values we have on a random interframe are complete junk if we didn't

    // start decode on a keyframe. So just don't display anything rather than junk.

    if (!s->keyframe && (!s->framep[VP56_FRAME_PREVIOUS] ||

                         !s->framep[VP56_FRAME_GOLDEN] ||

                         !s->framep[VP56_FRAME_GOLDEN2])) {

        av_log(avctx, AV_LOG_WARNING, "Discarding interframe without a prior keyframe!\n");

        return AVERROR_INVALIDDATA;

    }



    s->linesize   = curframe->linesize[0];

    s->uvlinesize = curframe->linesize[1];



    if (!s->edge_emu_buffer)

        s->edge_emu_buffer = av_malloc(21*s->linesize);



    memset(s->top_nnz, 0, s->mb_width*sizeof(*s->top_nnz));



    // top edge of 127 for intra prediction

    if (!(avctx->flags & CODEC_FLAG_EMU_EDGE)) {

        memset(curframe->data[0] - s->linesize  -1, 127, s->linesize  +1);

        memset(curframe->data[1] - s->uvlinesize-1, 127, s->uvlinesize+1);

        memset(curframe->data[2] - s->uvlinesize-1, 127, s->uvlinesize+1);

    }



    for (mb_y = 0; mb_y < s->mb_height; mb_y++) {

        VP56RangeCoder *c = &s->coeff_partition[mb_y & (s->num_coeff_partitions-1)];

        VP8Macroblock *mb = s->macroblocks + mb_y*s->mb_stride;

        uint8_t *intra4x4 = s->intra4x4_pred_mode + 4*mb_y*s->b4_stride;

        uint8_t *dst[3] = {

            curframe->data[0] + 16*mb_y*s->linesize,

            curframe->data[1] +  8*mb_y*s->uvlinesize,

            curframe->data[2] +  8*mb_y*s->uvlinesize

        };



        memset(s->left_nnz, 0, sizeof(s->left_nnz));



        // left edge of 129 for intra prediction

        if (!(avctx->flags & CODEC_FLAG_EMU_EDGE))

            for (i = 0; i < 3; i++)

                for (y = 0; y < 16>>!!i; y++)

                    dst[i][y*curframe->linesize[i]-1] = 129;



        for (mb_x = 0; mb_x < s->mb_width; mb_x++) {

            decode_mb_mode(s, mb, mb_x, mb_y, intra4x4 + 4*mb_x);



            if (!mb->skip)

                decode_mb_coeffs(s, c, mb, s->top_nnz[mb_x], s->left_nnz);

            else {

                AV_ZERO128(s->non_zero_count_cache);    // luma

                AV_ZERO64(s->non_zero_count_cache[4]);  // chroma

            }



            if (mb->mode <= MODE_I4x4) {

                intra_predict(s, dst, mb, intra4x4 + 4*mb_x, mb_x, mb_y);

                memset(mb->bmv, 0, sizeof(mb->bmv));

            } else {

                inter_predict(s, dst, mb, mb_x, mb_y);

            }



            if (!mb->skip) {

                idct_mb(s, dst[0], dst[1], dst[2], mb);

            } else {

                AV_ZERO64(s->left_nnz);

                AV_WN64(s->top_nnz[mb_x], 0);   // array of 9, so unaligned



                // Reset DC block predictors if they would exist if the mb had coefficients

                if (mb->mode != MODE_I4x4 && mb->mode != VP8_MVMODE_SPLIT) {

                    s->left_nnz[8]      = 0;

                    s->top_nnz[mb_x][8] = 0;

                }

            }



            dst[0] += 16;

            dst[1] += 8;

            dst[2] += 8;

            mb++;

        }

        if (mb_y && s->filter.level && avctx->skip_loop_filter < skip_thresh) {

            if (s->filter.simple)

                filter_mb_row_simple(s, mb_y-1);

            else

                filter_mb_row(s, mb_y-1);

        }

    }

    if (s->filter.level && avctx->skip_loop_filter < skip_thresh) {

        if (s->filter.simple)

            filter_mb_row_simple(s, mb_y-1);

        else

            filter_mb_row(s, mb_y-1);

    }



skip_decode:

    // if future frames don't use the updated probabilities,

    // reset them to the values we saved

    if (!s->update_probabilities)

        s->prob[0] = s->prob[1];



    // check if golden and altref are swapped

    if (s->update_altref == VP56_FRAME_GOLDEN &&

        s->update_golden == VP56_FRAME_GOLDEN2)

        FFSWAP(AVFrame *, s->framep[VP56_FRAME_GOLDEN], s->framep[VP56_FRAME_GOLDEN2]);

    else {

        if (s->update_altref != VP56_FRAME_NONE)

            s->framep[VP56_FRAME_GOLDEN2] = s->framep[s->update_altref];



        if (s->update_golden != VP56_FRAME_NONE)

            s->framep[VP56_FRAME_GOLDEN] = s->framep[s->update_golden];

    }



    if (s->update_last) // move cur->prev

        s->framep[VP56_FRAME_PREVIOUS] = s->framep[VP56_FRAME_CURRENT];



    // release no longer referenced frames

    for (i = 0; i < 4; i++)

        if (s->frames[i].data[0] &&

            &s->frames[i] != s->framep[VP56_FRAME_CURRENT] &&

            &s->frames[i] != s->framep[VP56_FRAME_PREVIOUS] &&

            &s->frames[i] != s->framep[VP56_FRAME_GOLDEN] &&

            &s->frames[i] != s->framep[VP56_FRAME_GOLDEN2])

            avctx->release_buffer(avctx, &s->frames[i]);



    if (!s->invisible) {

        *(AVFrame*)data = *s->framep[VP56_FRAME_CURRENT];

        *data_size = sizeof(AVFrame);

    }



    return avpkt->size;

}

void ff_init_vscale_pfn(SwsContext *c,

    yuv2planar1_fn yuv2plane1,

    yuv2planarX_fn yuv2planeX,

    yuv2interleavedX_fn yuv2nv12cX,

    yuv2packed1_fn yuv2packed1,

    yuv2packed2_fn yuv2packed2,

    yuv2packedX_fn yuv2packedX,

    yuv2anyX_fn yuv2anyX, int use_mmx)

{

    VScalerContext *lumCtx = NULL;

    VScalerContext *chrCtx = NULL;

    int idx = c->numDesc - (c->is_internal_gamma ? 2 : 1); //FIXME avoid hardcoding indexes



    if (isPlanarYUV(c->dstFormat) || (isGray(c->dstFormat) && !isALPHA(c->dstFormat))) {

        if (!isGray(c->dstFormat)) {

            chrCtx = c->desc[idx].instance;



            chrCtx->filter[0] = use_mmx ? (int16_t*)c->chrMmxFilter : c->vChrFilter;

            chrCtx->filter_size = c->vChrFilterSize;

            chrCtx->filter_pos = c->vChrFilterPos;

            chrCtx->isMMX = use_mmx;



            --idx;

            if (yuv2nv12cX)               chrCtx->pfn = yuv2nv12cX;

            else if (c->vChrFilterSize == 1) chrCtx->pfn = yuv2plane1;

            else                             chrCtx->pfn = yuv2planeX;

        }



        lumCtx = c->desc[idx].instance;



        lumCtx->filter[0] = use_mmx ? (int16_t*)c->lumMmxFilter : c->vLumFilter;

        lumCtx->filter[1] = use_mmx ? (int16_t*)c->alpMmxFilter : c->vLumFilter;

        lumCtx->filter_size = c->vLumFilterSize;

        lumCtx->filter_pos = c->vLumFilterPos;

        lumCtx->isMMX = use_mmx;



        if (c->vLumFilterSize == 1) lumCtx->pfn = yuv2plane1;

        else                        lumCtx->pfn = yuv2planeX;



    } else {

        lumCtx = c->desc[idx].instance;

        chrCtx = &lumCtx[1];



        lumCtx->filter[0] = c->vLumFilter;

        lumCtx->filter_size = c->vLumFilterSize;

        lumCtx->filter_pos = c->vLumFilterPos;



        chrCtx->filter[0] = c->vChrFilter;

        chrCtx->filter_size = c->vChrFilterSize;

        chrCtx->filter_pos = c->vChrFilterPos;



        lumCtx->isMMX = use_mmx;

        chrCtx->isMMX = use_mmx;



        if (yuv2packedX) {

            if (c->yuv2packed1 && c->vLumFilterSize == 1 && c->vChrFilterSize <= 2)

                lumCtx->pfn = yuv2packed1;

            else if (c->yuv2packed2 && c->vLumFilterSize == 2 && c->vChrFilterSize == 2)

                lumCtx->pfn = yuv2packed2;

            else

                lumCtx->pfn = yuv2packedX;

        } else

            lumCtx->pfn = yuv2anyX;

    }

}

static int flv_read_packet(AVFormatContext *s, AVPacket *pkt)

{

    int ret, i, type, size, pts, flags, is_audio, next, pos;

    AVStream *st = NULL;



 for(;;){

    pos = url_ftell(s->pb);

    url_fskip(s->pb, 4); /* size of previous packet */

    type = get_byte(s->pb);

    size = get_be24(s->pb);

    pts = get_be24(s->pb);

    pts |= get_byte(s->pb) << 24;

//    av_log(s, AV_LOG_DEBUG, "type:%d, size:%d, pts:%d\n", type, size, pts);

    if (url_feof(s->pb))

        return AVERROR(EIO);

    url_fskip(s->pb, 3); /* stream id, always 0 */

    flags = 0;



    if(size == 0)

        continue;



    next= size + url_ftell(s->pb);



    if (type == FLV_TAG_TYPE_AUDIO) {

        is_audio=1;

        flags = get_byte(s->pb);

    } else if (type == FLV_TAG_TYPE_VIDEO) {

        is_audio=0;

        flags = get_byte(s->pb);

    } else {

        if (type == FLV_TAG_TYPE_META && size > 13+1+4)

            flv_read_metabody(s, next);

        else /* skip packet */

            av_log(s, AV_LOG_ERROR, "skipping flv packet: type %d, size %d, flags %d\n", type, size, flags);

        url_fseek(s->pb, next, SEEK_SET);

        continue;

    }



    /* now find stream */

    for(i=0;i<s->nb_streams;i++) {

        st = s->streams[i];

        if (st->id == is_audio)

            break;

    }

    if(i == s->nb_streams){

        av_log(NULL, AV_LOG_ERROR, "invalid stream\n");

        st= create_stream(s, is_audio);

        s->ctx_flags &= ~AVFMTCTX_NOHEADER;

    }

//    av_log(NULL, AV_LOG_DEBUG, "%d %X %d \n", is_audio, flags, st->discard);

    if(  (st->discard >= AVDISCARD_NONKEY && !((flags & FLV_VIDEO_FRAMETYPE_MASK) == FLV_FRAME_KEY ||         is_audio))

       ||(st->discard >= AVDISCARD_BIDIR  &&  ((flags & FLV_VIDEO_FRAMETYPE_MASK) == FLV_FRAME_DISP_INTER && !is_audio))

       || st->discard >= AVDISCARD_ALL

       ){

        url_fseek(s->pb, next, SEEK_SET);

        continue;

    }

    if ((flags & FLV_VIDEO_FRAMETYPE_MASK) == FLV_FRAME_KEY)

        av_add_index_entry(st, pos, pts, size, 0, AVINDEX_KEYFRAME);

    break;

 }



    // if not streamed and no duration from metadata then seek to end to find the duration from the timestamps

    if(!url_is_streamed(s->pb) && s->duration==AV_NOPTS_VALUE){

        int size;

        const int pos= url_ftell(s->pb);

        const int fsize= url_fsize(s->pb);

        url_fseek(s->pb, fsize-4, SEEK_SET);

        size= get_be32(s->pb);

        url_fseek(s->pb, fsize-3-size, SEEK_SET);

        if(size == get_be24(s->pb) + 11){

            s->duration= get_be24(s->pb) * (int64_t)AV_TIME_BASE / 1000;

        }

        url_fseek(s->pb, pos, SEEK_SET);

    }



    if(is_audio){

        if(!st->codec->sample_rate || !st->codec->bits_per_sample || (!st->codec->codec_id && !st->codec->codec_tag)) {

            st->codec->channels = (flags & FLV_AUDIO_CHANNEL_MASK) == FLV_STEREO ? 2 : 1;

            if((flags & FLV_AUDIO_CODECID_MASK) == FLV_CODECID_NELLYMOSER_8HZ_MONO)

                st->codec->sample_rate= 8000;

            else

                st->codec->sample_rate = (44100 << ((flags & FLV_AUDIO_SAMPLERATE_MASK) >> FLV_AUDIO_SAMPLERATE_OFFSET) >> 3);

            st->codec->bits_per_sample = (flags & FLV_AUDIO_SAMPLESIZE_MASK) ? 16 : 8;

            flv_set_audio_codec(s, st, flags & FLV_AUDIO_CODECID_MASK);

        }

    }else{

        size -= flv_set_video_codec(s, st, flags & FLV_VIDEO_CODECID_MASK);

    }



    ret= av_get_packet(s->pb, pkt, size - 1);

    if (ret <= 0) {

        return AVERROR(EIO);

    }

    /* note: we need to modify the packet size here to handle the last

       packet */

    pkt->size = ret;

    pkt->pts = pts;

    pkt->stream_index = st->index;



    if (is_audio || ((flags & FLV_VIDEO_FRAMETYPE_MASK) == FLV_FRAME_KEY))

        pkt->flags |= PKT_FLAG_KEY;



    return ret;

}

