    s->mb_width  = (s->avctx->coded_width +15) / 16;

    s->mb_height = (s->avctx->coded_height+15) / 16;



    // we allocate a border around the top/left of intra4x4 modes

    // this is 4 blocks for intra4x4 to keep 4-byte alignment for fill_rectangle

    s->mb_stride = s->mb_width+1;

    s->b4_stride = 4*s->mb_stride;



    s->macroblocks_base        = av_mallocz(s->mb_stride*(s->mb_height+1)*sizeof(*s->macroblocks));

    s->intra4x4_pred_mode_base = av_mallocz(s->b4_stride*(4*s->mb_height+1));

    s->top_nnz                 = av_mallocz(s->mb_width*sizeof(*s->top_nnz));



    if (!s->macroblocks_base || !s->intra4x4_pred_mode_base || !s->top_nnz)

        return AVERROR(ENOMEM);



    s->macroblocks        = s->macroblocks_base        + 1 + s->mb_stride;

    s->intra4x4_pred_mode = s->intra4x4_pred_mode_base + 4 + s->b4_stride;



    memset(s->intra4x4_pred_mode_base, DC_PRED, s->b4_stride);

    for (i = 0; i < 4*s->mb_height; i++)

        s->intra4x4_pred_mode[i*s->b4_stride-1] = DC_PRED;



    return 0;

}

static void predictor_decompress_fir_adapt(int32_t *error_buffer,

                                           int32_t *buffer_out,

                                           int output_size,

                                           int readsamplesize,

                                           int16_t *predictor_coef_table,

                                           int predictor_coef_num,

                                           int predictor_quantitization)

{

    int i;



    /* first sample always copies */

    *buffer_out = *error_buffer;



    if (!predictor_coef_num) {

        if (output_size <= 1)

            return;



        memcpy(&buffer_out[1], &error_buffer[1],

               (output_size - 1) * sizeof(*buffer_out));

        return;

    }



    if (predictor_coef_num == 31) {

        /* simple 1st-order prediction */

        if (output_size <= 1)

            return;

        for (i = 1; i < output_size; i++) {

            buffer_out[i] = sign_extend(buffer_out[i - 1] + error_buffer[i],

                                        readsamplesize);

        }

        return;

    }



    /* read warm-up samples */

    for (i = 0; i < predictor_coef_num; i++) {

        buffer_out[i + 1] = sign_extend(buffer_out[i] + error_buffer[i + 1],

                                        readsamplesize);

    }



    /* NOTE: 4 and 8 are very common cases that could be optimized. */



    /* general case */

    for (i = predictor_coef_num; i < output_size - 1; i++) {

        int j;

        int val = 0;

        int error_val = error_buffer[i + 1];

        int error_sign;

        int d = buffer_out[i - predictor_coef_num];



        for (j = 0; j < predictor_coef_num; j++) {

            val += (buffer_out[i - j] - d) *

                   predictor_coef_table[j];

        }



        val = (val + (1 << (predictor_quantitization - 1))) >>

              predictor_quantitization;

        val += d + error_val;



        buffer_out[i + 1] = sign_extend(val, readsamplesize);



        /* adapt LPC coefficients */

        error_sign = sign_only(error_val);

        if (error_sign) {

            for (j = predictor_coef_num - 1; j >= 0 && error_val * error_sign > 0; j--) {

                int sign;

                val  = d - buffer_out[i - j];

                sign = sign_only(val) * error_sign;

                predictor_coef_table[j] -= sign;

                val *= sign;

                error_val -= ((val >> predictor_quantitization) *

                              (predictor_coef_num - j));

            }

        }

    }

}

static int alloc_audio_output_buf(AVCodecContext *dec, AVCodecContext *enc,

                                  int nb_samples, int *buf_linesize)

{

    int64_t audio_buf_samples;

    int audio_buf_size;



    /* calculate required number of samples to allocate */

    audio_buf_samples = ((int64_t)nb_samples * enc->sample_rate + dec->sample_rate) /

                        dec->sample_rate;

    audio_buf_samples = 4 * audio_buf_samples + 10000; // safety factors for resampling

    audio_buf_samples = FFMAX(audio_buf_samples, enc->frame_size);

    if (audio_buf_samples > INT_MAX)

        return AVERROR(EINVAL);



    audio_buf_size = av_samples_get_buffer_size(buf_linesize, enc->channels,

                                                audio_buf_samples,

                                                enc->sample_fmt, 0);

    if (audio_buf_size < 0)

        return audio_buf_size;



    av_fast_malloc(&audio_buf, &allocated_audio_buf_size, audio_buf_size);

    if (!audio_buf)

        return AVERROR(ENOMEM);



    return 0;

}

static int nut_write_header(AVFormatContext * avf) {

    NUTContext * priv = avf->priv_data;

    AVIOContext * bc = avf->pb;

    nut_muxer_opts_tt mopts = {

        .output = {

            .priv = bc,

            .write = av_write,

        },

        .alloc = { av_malloc, av_realloc, av_free },

        .write_index = 1,

        .realtime_stream = 0,

        .max_distance = 32768,

        .fti = NULL,

    };

    nut_stream_header_tt * s;

    int i;



    priv->s = s = av_mallocz((avf->nb_streams + 1) * sizeof*s);





    for (i = 0; i < avf->nb_streams; i++) {

        AVCodecContext * codec = avf->streams[i]->codec;

        int j;

        int fourcc = 0;

        int num, denom, ssize;



        s[i].type = codec->codec_type == AVMEDIA_TYPE_VIDEO ? NUT_VIDEO_CLASS : NUT_AUDIO_CLASS;



        if (codec->codec_tag) fourcc = codec->codec_tag;

        else fourcc = ff_codec_get_tag(nut_tags, codec->codec_id);



        if (!fourcc) {

            if (codec->codec_type == AVMEDIA_TYPE_VIDEO) fourcc = ff_codec_get_tag(ff_codec_bmp_tags, codec->codec_id);

            if (codec->codec_type == AVMEDIA_TYPE_AUDIO) fourcc = ff_codec_get_tag(ff_codec_wav_tags, codec->codec_id);

        }



        s[i].fourcc_len = 4;

        s[i].fourcc = av_malloc(s[i].fourcc_len);

        for (j = 0; j < s[i].fourcc_len; j++) s[i].fourcc[j] = (fourcc >> (j*8)) & 0xFF;



        ff_parse_specific_params(codec, &num, &ssize, &denom);

        avpriv_set_pts_info(avf->streams[i], 60, denom, num);



        s[i].time_base.num = denom;

        s[i].time_base.den = num;



        s[i].fixed_fps = 0;

        s[i].decode_delay = codec->has_b_frames;

        s[i].codec_specific_len = codec->extradata_size;

        s[i].codec_specific = codec->extradata;



        if (codec->codec_type == AVMEDIA_TYPE_VIDEO) {

            s[i].width = codec->width;

            s[i].height = codec->height;

            s[i].sample_width = 0;

            s[i].sample_height = 0;

            s[i].colorspace_type = 0;

        } else {

            s[i].samplerate_num = codec->sample_rate;

            s[i].samplerate_denom = 1;

            s[i].channel_count = codec->channels;

        }

    }



    s[avf->nb_streams].type = -1;

    priv->nut = nut_muxer_init(&mopts, s, NULL);



    return 0;

}

static inline int RENAME(yuv420_rgb16)(SwsContext *c, uint8_t* src[], int srcStride[], int srcSliceY,

             int srcSliceH, uint8_t* dst[], int dstStride[]){

    int y, h_size;



    if(c->srcFormat == PIX_FMT_YUV422P){

	srcStride[1] *= 2;

	srcStride[2] *= 2;

    }



    h_size= (c->dstW+7)&~7;

    if(h_size*2 > dstStride[0]) h_size-=8;



    __asm__ __volatile__ ("pxor %mm4, %mm4;" /* zero mm4 */ );

//printf("%X %X %X %X %X %X %X %X %X %X\n", (int)&c->redDither, (int)&b5Dither, (int)src[0], (int)src[1], (int)src[2], (int)dst[0],

//srcStride[0],srcStride[1],srcStride[2],dstStride[0]);

    for (y= 0; y<srcSliceH; y++ ) {

	uint8_t *_image = dst[0] + (y+srcSliceY)*dstStride[0];

	uint8_t *_py = src[0] + y*srcStride[0];

	uint8_t *_pu = src[1] + (y>>1)*srcStride[1];

	uint8_t *_pv = src[2] + (y>>1)*srcStride[2];

	long index= -h_size/2;



	b5Dither= dither8[y&1];

	g6Dither= dither4[y&1];

	g5Dither= dither8[y&1];

	r5Dither= dither8[(y+1)&1];

	    /* this mmx assembly code deals with SINGLE scan line at a time, it convert 8

	       pixels in each iteration */

	    __asm__ __volatile__ (

	/* load data for start of next scan line */

		     "movd (%2, %0), %%mm0;" /* Load 4 Cb 00 00 00 00 u3 u2 u1 u0 */

		     "movd (%3, %0), %%mm1;" /* Load 4 Cr 00 00 00 00 v3 v2 v1 v0 */

		     "movq (%5, %0, 2), %%mm6;" /* Load 8  Y Y7 Y6 Y5 Y4 Y3 Y2 Y1 Y0 */

//		    ".balign 16			\n\t"

		    "1:				\n\t"

/* no speed diference on my p3@500 with prefetch,

 * if it is faster for anyone with -benchmark then tell me

			PREFETCH" 64(%0) \n\t"

			PREFETCH" 64(%1) \n\t"

			PREFETCH" 64(%2) \n\t"

*/

YUV2RGB



#ifdef DITHER1XBPP

			"paddusb "MANGLE(b5Dither)", %%mm0;"

			"paddusb "MANGLE(g6Dither)", %%mm2;"

			"paddusb "MANGLE(r5Dither)", %%mm1;"

#endif

		     /* mask unneeded bits off */

		     "pand "MANGLE(mmx_redmask)", %%mm0;" /* b7b6b5b4 b3_0_0_0 b7b6b5b4 b3_0_0_0 */

		     "pand "MANGLE(mmx_grnmask)", %%mm2;" /* g7g6g5g4 g3g2_0_0 g7g6g5g4 g3g2_0_0 */

		     "pand "MANGLE(mmx_redmask)", %%mm1;" /* r7r6r5r4 r3_0_0_0 r7r6r5r4 r3_0_0_0 */



		     "psrlw $3,%%mm0;" /* 0_0_0_b7 b6b5b4b3 0_0_0_b7 b6b5b4b3 */

		     "pxor %%mm4, %%mm4;" /* zero mm4 */



		     "movq %%mm0, %%mm5;" /* Copy B7-B0 */

		     "movq %%mm2, %%mm7;" /* Copy G7-G0 */



		     /* convert rgb24 plane to rgb16 pack for pixel 0-3 */

		     "punpcklbw %%mm4, %%mm2;" /* 0_0_0_0 0_0_0_0 g7g6g5g4 g3g2_0_0 */

		     "punpcklbw %%mm1, %%mm0;" /* r7r6r5r4 r3_0_0_0 0_0_0_b7 b6b5b4b3 */



		     "psllw $3, %%mm2;" /* 0_0_0_0 0_g7g6g5 g4g3g2_0 0_0_0_0 */

		     "por %%mm2, %%mm0;" /* r7r6r5r4 r3g7g6g5 g4g3g2b7 b6b5b4b3 */



		     "movq 8 (%5, %0, 2), %%mm6;" /* Load 8 Y Y7 Y6 Y5 Y4 Y3 Y2 Y1 Y0 */

		     MOVNTQ " %%mm0, (%1);" /* store pixel 0-3 */



		     /* convert rgb24 plane to rgb16 pack for pixel 0-3 */

		     "punpckhbw %%mm4, %%mm7;" /* 0_0_0_0 0_0_0_0 g7g6g5g4 g3g2_0_0 */

		     "punpckhbw %%mm1, %%mm5;" /* r7r6r5r4 r3_0_0_0 0_0_0_b7 b6b5b4b3 */



		     "psllw $3, %%mm7;" /* 0_0_0_0 0_g7g6g5 g4g3g2_0 0_0_0_0 */

		     "movd 4 (%2, %0), %%mm0;" /* Load 4 Cb 00 00 00 00 u3 u2 u1 u0 */



		     "por %%mm7, %%mm5;" /* r7r6r5r4 r3g7g6g5 g4g3g2b7 b6b5b4b3 */

		     "movd 4 (%3, %0), %%mm1;" /* Load 4 Cr 00 00 00 00 v3 v2 v1 v0 */



		     MOVNTQ " %%mm5, 8 (%1);" /* store pixel 4-7 */



		     "add $16, %1			\n\t"

		     "add $4, %0			\n\t"

		     " js 1b				\n\t"



		     : "+r" (index), "+r" (_image)

		     : "r" (_pu - index), "r" (_pv - index), "r"(&c->redDither), "r" (_py - 2*index)

		     );

    }



    __asm__ __volatile__ (EMMS);



    return srcSliceH;

}

size_t av_cpu_max_align(void)

{

    int flags = av_get_cpu_flags();



    if (flags & AV_CPU_FLAG_AVX)

        return 32;

    if (flags & (AV_CPU_FLAG_ALTIVEC | AV_CPU_FLAG_SSE | AV_CPU_FLAG_NEON))

        return 16;



    return 8;

}

static void h261_loop_filter_c(uint8_t *src, int stride){

    int x,y,xy,yz;

    int temp[64];



    for(x=0; x<8; x++){

        temp[x      ] = 4*src[x           ];

        temp[x + 7*8] = 4*src[x + 7*stride];

    }

    for(y=1; y<7; y++){

        for(x=0; x<8; x++){

            xy = y * stride + x;

            yz = y * 8 + x;

            temp[yz] = src[xy - stride] + 2*src[xy] + src[xy + stride];

        }

    }



    for(y=0; y<8; y++){

        src[  y*stride] = (temp[  y*8] + 2)>>2;

        src[7+y*stride] = (temp[7+y*8] + 2)>>2;

        for(x=1; x<7; x++){

            xy = y * stride + x;

            yz = y * 8 + x;

            src[xy] = (temp[yz-1] + 2*temp[yz] + temp[yz+1] + 8)>>4;

        }

    }

}

int ff_rtsp_connect(AVFormatContext *s)

{

    RTSPState *rt = s->priv_data;

    char host[1024], path[1024], tcpname[1024], cmd[2048], auth[128];

    char *option_list, *option, *filename;

    int port, err, tcp_fd;

    RTSPMessageHeader reply1 = {}, *reply = &reply1;

    int lower_transport_mask = 0;

    char real_challenge[64];

    struct sockaddr_storage peer;

    socklen_t peer_len = sizeof(peer);



    if (!ff_network_init())

        return AVERROR(EIO);

redirect:

    rt->control_transport = RTSP_MODE_PLAIN;

    /* extract hostname and port */

    av_url_split(NULL, 0, auth, sizeof(auth),

                 host, sizeof(host), &port, path, sizeof(path), s->filename);

    if (*auth) {

        av_strlcpy(rt->auth, auth, sizeof(rt->auth));

    }

    if (port < 0)

        port = RTSP_DEFAULT_PORT;



    /* search for options */

    option_list = strrchr(path, '?');

    if (option_list) {

        /* Strip out the RTSP specific options, write out the rest of

         * the options back into the same string. */

        filename = option_list;

        while (option_list) {

            /* move the option pointer */

            option = ++option_list;

            option_list = strchr(option_list, '&');

            if (option_list)

                *option_list = 0;



            /* handle the options */

            if (!strcmp(option, "udp")) {

                lower_transport_mask |= (1<< RTSP_LOWER_TRANSPORT_UDP);

            } else if (!strcmp(option, "multicast")) {

                lower_transport_mask |= (1<< RTSP_LOWER_TRANSPORT_UDP_MULTICAST);

            } else if (!strcmp(option, "tcp")) {

                lower_transport_mask |= (1<< RTSP_LOWER_TRANSPORT_TCP);

            } else if(!strcmp(option, "http")) {

                lower_transport_mask |= (1<< RTSP_LOWER_TRANSPORT_TCP);

                rt->control_transport = RTSP_MODE_TUNNEL;

            } else {

                /* Write options back into the buffer, using memmove instead

                 * of strcpy since the strings may overlap. */

                int len = strlen(option);

                memmove(++filename, option, len);

                filename += len;

                if (option_list) *filename = '&';

            }

        }

        *filename = 0;

    }



    if (!lower_transport_mask)

        lower_transport_mask = (1 << RTSP_LOWER_TRANSPORT_NB) - 1;



    if (s->oformat) {

        /* Only UDP or TCP - UDP multicast isn't supported. */

        lower_transport_mask &= (1 << RTSP_LOWER_TRANSPORT_UDP) |

                                (1 << RTSP_LOWER_TRANSPORT_TCP);

        if (!lower_transport_mask || rt->control_transport == RTSP_MODE_TUNNEL) {

            av_log(s, AV_LOG_ERROR, "Unsupported lower transport method, "

                                    "only UDP and TCP are supported for output.\n");

            err = AVERROR(EINVAL);

            goto fail;

        }

    }



    /* Construct the URI used in request; this is similar to s->filename,

     * but with authentication credentials removed and RTSP specific options

     * stripped out. */

    ff_url_join(rt->control_uri, sizeof(rt->control_uri), "rtsp", NULL,

                host, port, "%s", path);



    if (rt->control_transport == RTSP_MODE_TUNNEL) {

        /* set up initial handshake for tunneling */

        char httpname[1024];

        char sessioncookie[17];

        char headers[1024];



        ff_url_join(httpname, sizeof(httpname), "http", auth, host, port, "%s", path);

        snprintf(sessioncookie, sizeof(sessioncookie), "%08x%08x",

                 av_get_random_seed(), av_get_random_seed());



        /* GET requests */

        if (url_alloc(&rt->rtsp_hd, httpname, URL_RDONLY) < 0) {

            err = AVERROR(EIO);

            goto fail;

        }



        /* generate GET headers */

        snprintf(headers, sizeof(headers),

                 "x-sessioncookie: %s\r\n"

                 "Accept: application/x-rtsp-tunnelled\r\n"

                 "Pragma: no-cache\r\n"

                 "Cache-Control: no-cache\r\n",

                 sessioncookie);

        ff_http_set_headers(rt->rtsp_hd, headers);



        /* complete the connection */

        if (url_connect(rt->rtsp_hd)) {

            err = AVERROR(EIO);

            goto fail;

        }



        /* POST requests */

        if (url_alloc(&rt->rtsp_hd_out, httpname, URL_WRONLY) < 0 ) {

            err = AVERROR(EIO);

            goto fail;

        }



        /* generate POST headers */

        snprintf(headers, sizeof(headers),

                 "x-sessioncookie: %s\r\n"

                 "Content-Type: application/x-rtsp-tunnelled\r\n"

                 "Pragma: no-cache\r\n"

                 "Cache-Control: no-cache\r\n"

                 "Content-Length: 32767\r\n"

                 "Expires: Sun, 9 Jan 1972 00:00:00 GMT\r\n",

                 sessioncookie);

        ff_http_set_headers(rt->rtsp_hd_out, headers);

        ff_http_set_chunked_transfer_encoding(rt->rtsp_hd_out, 0);



        /* Initialize the authentication state for the POST session. The HTTP

         * protocol implementation doesn't properly handle multi-pass

         * authentication for POST requests, since it would require one of

         * the following:

         * - implementing Expect: 100-continue, which many HTTP servers

         *   don't support anyway, even less the RTSP servers that do HTTP

         *   tunneling

         * - sending the whole POST data until getting a 401 reply specifying

         *   what authentication method to use, then resending all that data

         * - waiting for potential 401 replies directly after sending the

         *   POST header (waiting for some unspecified time)

         * Therefore, we copy the full auth state, which works for both basic

         * and digest. (For digest, we would have to synchronize the nonce

         * count variable between the two sessions, if we'd do more requests

         * with the original session, though.)

         */

        ff_http_init_auth_state(rt->rtsp_hd_out, rt->rtsp_hd);



        /* complete the connection */

        if (url_connect(rt->rtsp_hd_out)) {

            err = AVERROR(EIO);

            goto fail;

        }

    } else {

        /* open the tcp connection */

        ff_url_join(tcpname, sizeof(tcpname), "tcp", NULL, host, port, NULL);

        if (url_open(&rt->rtsp_hd, tcpname, URL_RDWR) < 0) {

            err = AVERROR(EIO);

            goto fail;

        }

        rt->rtsp_hd_out = rt->rtsp_hd;

    }

    rt->seq = 0;



    tcp_fd = url_get_file_handle(rt->rtsp_hd);

    if (!getpeername(tcp_fd, (struct sockaddr*) &peer, &peer_len)) {

        getnameinfo((struct sockaddr*) &peer, peer_len, host, sizeof(host),

                    NULL, 0, NI_NUMERICHOST);

    }



    /* request options supported by the server; this also detects server

     * type */

    for (rt->server_type = RTSP_SERVER_RTP;;) {

        cmd[0] = 0;

        if (rt->server_type == RTSP_SERVER_REAL)

            av_strlcat(cmd,

                       /**

                        * The following entries are required for proper

                        * streaming from a Realmedia server. They are

                        * interdependent in some way although we currently

                        * don't quite understand how. Values were copied

                        * from mplayer SVN r23589.

                        * @param CompanyID is a 16-byte ID in base64

                        * @param ClientChallenge is a 16-byte ID in hex

                        */

                       "ClientChallenge: 9e26d33f2984236010ef6253fb1887f7\r\n"

                       "PlayerStarttime: [28/03/2003:22:50:23 00:00]\r\n"

                       "CompanyID: KnKV4M4I/B2FjJ1TToLycw==\r\n"

                       "GUID: 00000000-0000-0000-0000-000000000000\r\n",

                       sizeof(cmd));

        ff_rtsp_send_cmd(s, "OPTIONS", rt->control_uri, cmd, reply, NULL);

        if (reply->status_code != RTSP_STATUS_OK) {

            err = AVERROR_INVALIDDATA;

            goto fail;

        }



        /* detect server type if not standard-compliant RTP */

        if (rt->server_type != RTSP_SERVER_REAL && reply->real_challenge[0]) {

            rt->server_type = RTSP_SERVER_REAL;

            continue;

        } else if (!strncasecmp(reply->server, "WMServer/", 9)) {

            rt->server_type = RTSP_SERVER_WMS;

        } else if (rt->server_type == RTSP_SERVER_REAL)

            strcpy(real_challenge, reply->real_challenge);

        break;

    }



    if (s->iformat)

        err = rtsp_setup_input_streams(s, reply);

    else

        err = rtsp_setup_output_streams(s, host);

    if (err)

        goto fail;



    do {

        int lower_transport = ff_log2_tab[lower_transport_mask &

                                  ~(lower_transport_mask - 1)];



        err = make_setup_request(s, host, port, lower_transport,

                                 rt->server_type == RTSP_SERVER_REAL ?

                                     real_challenge : NULL);

        if (err < 0)

            goto fail;

        lower_transport_mask &= ~(1 << lower_transport);

        if (lower_transport_mask == 0 && err == 1) {

            err = FF_NETERROR(EPROTONOSUPPORT);

            goto fail;

        }

    } while (err);



    rt->state = RTSP_STATE_IDLE;

    rt->seek_timestamp = 0; /* default is to start stream at position zero */

    return 0;

 fail:

    ff_rtsp_close_streams(s);

    ff_rtsp_close_connections(s);

    if (reply->status_code >=300 && reply->status_code < 400 && s->iformat) {

        av_strlcpy(s->filename, reply->location, sizeof(s->filename));

        av_log(s, AV_LOG_INFO, "Status %d: Redirecting to %s\n",

               reply->status_code,

               s->filename);

        goto redirect;

    }

    ff_network_close();

    return err;

}

static int ipvideo_decode_frame(AVCodecContext *avctx,

                                void *data, int *got_frame,

                                AVPacket *avpkt)

{

    const uint8_t *buf = avpkt->data;

    int buf_size = avpkt->size;

    IpvideoContext *s = avctx->priv_data;

    AVFrame *frame = data;

    int ret;



    if (buf_size < 2)

        return AVERROR_INVALIDDATA;



    /* decoding map contains 4 bits of information per 8x8 block */

    s->decoding_map_size = AV_RL16(avpkt->data);



    /* compressed buffer needs to be large enough to at least hold an entire

     * decoding map */

    if (buf_size < s->decoding_map_size + 2)

        return buf_size;



    if (av_packet_get_side_data(avpkt, AV_PKT_DATA_PARAM_CHANGE, NULL)) {

        av_frame_unref(s->last_frame);

        av_frame_unref(s->second_last_frame);

    }



    s->decoding_map = buf + 2;

    bytestream2_init(&s->stream_ptr, buf + 2 + s->decoding_map_size,

                     buf_size - s->decoding_map_size);



    if ((ret = ff_get_buffer(avctx, frame, AV_GET_BUFFER_FLAG_REF)) < 0)

        return ret;



    if (!s->is_16bpp) {

        int size;

        const uint8_t *pal = av_packet_get_side_data(avpkt, AV_PKT_DATA_PALETTE, &size);

        if (pal && size == AVPALETTE_SIZE) {

            frame->palette_has_changed = 1;

            memcpy(s->pal, pal, AVPALETTE_SIZE);

        } else if (pal) {

            av_log(avctx, AV_LOG_ERROR, "Palette size %d is wrong\n", size);

        }

    }



    ipvideo_decode_opcodes(s, frame);



    *got_frame = 1;



    /* shuffle frames */

    av_frame_unref(s->second_last_frame);

    FFSWAP(AVFrame*, s->second_last_frame, s->last_frame);

    if ((ret = av_frame_ref(s->last_frame, frame)) < 0)

        return ret;



    /* report that the buffer was completely consumed */

    return buf_size;

}

static int process_ipmovie_chunk(IPMVEContext *s, AVIOContext *pb,

    AVPacket *pkt)

{

    unsigned char chunk_preamble[CHUNK_PREAMBLE_SIZE];

    int chunk_type;

    int chunk_size;

    unsigned char opcode_preamble[OPCODE_PREAMBLE_SIZE];

    unsigned char opcode_type;

    unsigned char opcode_version;

    int opcode_size;

    unsigned char scratch[1024];

    int i, j;

    int first_color, last_color;

    int audio_flags;

    unsigned char r, g, b;

    unsigned int width, height;



    /* see if there are any pending packets */

    chunk_type = load_ipmovie_packet(s, pb, pkt);

    if (chunk_type != CHUNK_DONE)

        return chunk_type;



    /* read the next chunk, wherever the file happens to be pointing */

    if (avio_feof(pb))

        return CHUNK_EOF;

    if (avio_read(pb, chunk_preamble, CHUNK_PREAMBLE_SIZE) !=

        CHUNK_PREAMBLE_SIZE)

        return CHUNK_BAD;

    chunk_size = AV_RL16(&chunk_preamble[0]);

    chunk_type = AV_RL16(&chunk_preamble[2]);



    av_log(s->avf, AV_LOG_TRACE, "chunk type 0x%04X, 0x%04X bytes: ", chunk_type, chunk_size);



    switch (chunk_type) {



    case CHUNK_INIT_AUDIO:

        av_log(s->avf, AV_LOG_TRACE, "initialize audio\n");

        break;



    case CHUNK_AUDIO_ONLY:

        av_log(s->avf, AV_LOG_TRACE, "audio only\n");

        break;



    case CHUNK_INIT_VIDEO:

        av_log(s->avf, AV_LOG_TRACE, "initialize video\n");

        break;



    case CHUNK_VIDEO:

        av_log(s->avf, AV_LOG_TRACE, "video (and audio)\n");

        break;



    case CHUNK_SHUTDOWN:

        av_log(s->avf, AV_LOG_TRACE, "shutdown\n");

        break;



    case CHUNK_END:

        av_log(s->avf, AV_LOG_TRACE, "end\n");

        break;



    default:

        av_log(s->avf, AV_LOG_TRACE, "invalid chunk\n");

        chunk_type = CHUNK_BAD;

        break;



    }



    while ((chunk_size > 0) && (chunk_type != CHUNK_BAD)) {



        /* read the next chunk, wherever the file happens to be pointing */

        if (avio_feof(pb)) {

            chunk_type = CHUNK_EOF;

            break;

        }

        if (avio_read(pb, opcode_preamble, CHUNK_PREAMBLE_SIZE) !=

            CHUNK_PREAMBLE_SIZE) {

            chunk_type = CHUNK_BAD;

            break;

        }



        opcode_size = AV_RL16(&opcode_preamble[0]);

        opcode_type = opcode_preamble[2];

        opcode_version = opcode_preamble[3];



        chunk_size -= OPCODE_PREAMBLE_SIZE;

        chunk_size -= opcode_size;

        if (chunk_size < 0) {

            av_log(s->avf, AV_LOG_TRACE, "chunk_size countdown just went negative\n");

            chunk_type = CHUNK_BAD;

            break;

        }



        av_log(s->avf, AV_LOG_TRACE, "  opcode type %02X, version %d, 0x%04X bytes: ",

                opcode_type, opcode_version, opcode_size);

        switch (opcode_type) {



        case OPCODE_END_OF_STREAM:

            av_log(s->avf, AV_LOG_TRACE, "end of stream\n");

            avio_skip(pb, opcode_size);

            break;



        case OPCODE_END_OF_CHUNK:

            av_log(s->avf, AV_LOG_TRACE, "end of chunk\n");

            avio_skip(pb, opcode_size);

            break;



        case OPCODE_CREATE_TIMER:

            av_log(s->avf, AV_LOG_TRACE, "create timer\n");

            if ((opcode_version > 0) || (opcode_size != 6)) {

                av_log(s->avf, AV_LOG_TRACE, "bad create_timer opcode\n");

                chunk_type = CHUNK_BAD;

                break;

            }

            if (avio_read(pb, scratch, opcode_size) !=

                opcode_size) {

                chunk_type = CHUNK_BAD;

                break;

            }

            s->frame_pts_inc = ((uint64_t)AV_RL32(&scratch[0])) * AV_RL16(&scratch[4]);

            break;



        case OPCODE_INIT_AUDIO_BUFFERS:

            av_log(s->avf, AV_LOG_TRACE, "initialize audio buffers\n");

            if (opcode_version > 1 || opcode_size > 10 || opcode_size < 6) {

                av_log(s->avf, AV_LOG_TRACE, "bad init_audio_buffers opcode\n");

                chunk_type = CHUNK_BAD;

                break;

            }

            if (avio_read(pb, scratch, opcode_size) !=

                opcode_size) {

                chunk_type = CHUNK_BAD;

                break;

            }

            s->audio_sample_rate = AV_RL16(&scratch[4]);

            audio_flags = AV_RL16(&scratch[2]);

            /* bit 0 of the flags: 0 = mono, 1 = stereo */

            s->audio_channels = (audio_flags & 1) + 1;

            /* bit 1 of the flags: 0 = 8 bit, 1 = 16 bit */

            s->audio_bits = (((audio_flags >> 1) & 1) + 1) * 8;

            /* bit 2 indicates compressed audio in version 1 opcode */

            if ((opcode_version == 1) && (audio_flags & 0x4))

                s->audio_type = AV_CODEC_ID_INTERPLAY_DPCM;

            else if (s->audio_bits == 16)

                s->audio_type = AV_CODEC_ID_PCM_S16LE;

            else

                s->audio_type = AV_CODEC_ID_PCM_U8;

            av_log(s->avf, AV_LOG_TRACE, "audio: %d bits, %d Hz, %s, %s format\n",

                    s->audio_bits, s->audio_sample_rate,

                    (s->audio_channels == 2) ? "stereo" : "mono",

                    (s->audio_type == AV_CODEC_ID_INTERPLAY_DPCM) ?

                    "Interplay audio" : "PCM");

            break;



        case OPCODE_START_STOP_AUDIO:

            av_log(s->avf, AV_LOG_TRACE, "start/stop audio\n");

            avio_skip(pb, opcode_size);

            break;



        case OPCODE_INIT_VIDEO_BUFFERS:

            av_log(s->avf, AV_LOG_TRACE, "initialize video buffers\n");

            if ((opcode_version > 2) || (opcode_size > 8) || opcode_size < 4

                || opcode_version == 2 && opcode_size < 8

            ) {

                av_log(s->avf, AV_LOG_TRACE, "bad init_video_buffers opcode\n");

                chunk_type = CHUNK_BAD;

                break;

            }

            if (avio_read(pb, scratch, opcode_size) !=

                opcode_size) {

                chunk_type = CHUNK_BAD;

                break;

            }

            width  = AV_RL16(&scratch[0]) * 8;

            height = AV_RL16(&scratch[2]) * 8;

            if (width != s->video_width) {

                s->video_width = width;

                s->changed++;

            }

            if (height != s->video_height) {

                s->video_height = height;

                s->changed++;

            }

            if (opcode_version < 2 || !AV_RL16(&scratch[6])) {

                s->video_bpp = 8;

            } else {

                s->video_bpp = 16;

            }

            av_log(s->avf, AV_LOG_TRACE, "video resolution: %d x %d\n",

                    s->video_width, s->video_height);

            break;



        case OPCODE_UNKNOWN_06:

        case OPCODE_UNKNOWN_0E:

        case OPCODE_UNKNOWN_10:

        case OPCODE_UNKNOWN_12:

        case OPCODE_UNKNOWN_13:

        case OPCODE_UNKNOWN_14:

        case OPCODE_UNKNOWN_15:

            av_log(s->avf, AV_LOG_TRACE, "unknown (but documented) opcode %02X\n", opcode_type);

            avio_skip(pb, opcode_size);

            break;



        case OPCODE_SEND_BUFFER:

            av_log(s->avf, AV_LOG_TRACE, "send buffer\n");

            avio_skip(pb, opcode_size);

            s->send_buffer = 1;

            break;



        case OPCODE_AUDIO_FRAME:

            av_log(s->avf, AV_LOG_TRACE, "audio frame\n");



            /* log position and move on for now */

            s->audio_chunk_offset = avio_tell(pb);

            s->audio_chunk_size = opcode_size;

            avio_skip(pb, opcode_size);

            break;



        case OPCODE_SILENCE_FRAME:

            av_log(s->avf, AV_LOG_TRACE, "silence frame\n");

            avio_skip(pb, opcode_size);

            break;



        case OPCODE_INIT_VIDEO_MODE:

            av_log(s->avf, AV_LOG_TRACE, "initialize video mode\n");

            avio_skip(pb, opcode_size);

            break;



        case OPCODE_CREATE_GRADIENT:

            av_log(s->avf, AV_LOG_TRACE, "create gradient\n");

            avio_skip(pb, opcode_size);

            break;



        case OPCODE_SET_PALETTE:

            av_log(s->avf, AV_LOG_TRACE, "set palette\n");

            /* check for the logical maximum palette size

             * (3 * 256 + 4 bytes) */

            if (opcode_size > 0x304 || opcode_size < 4) {

                av_log(s->avf, AV_LOG_TRACE, "demux_ipmovie: set_palette opcode with invalid size\n");

                chunk_type = CHUNK_BAD;

                break;

            }

            if (avio_read(pb, scratch, opcode_size) != opcode_size) {

                chunk_type = CHUNK_BAD;

                break;

            }



            /* load the palette into internal data structure */

            first_color = AV_RL16(&scratch[0]);

            last_color = first_color + AV_RL16(&scratch[2]) - 1;

            /* sanity check (since they are 16 bit values) */

            if (   (first_color > 0xFF) || (last_color > 0xFF)

                || (last_color - first_color + 1)*3 + 4 > opcode_size) {

                av_log(s->avf, AV_LOG_TRACE, "demux_ipmovie: set_palette indexes out of range (%d -> %d)\n",

                    first_color, last_color);

                chunk_type = CHUNK_BAD;

                break;

            }

            j = 4;  /* offset of first palette data */

            for (i = first_color; i <= last_color; i++) {

                /* the palette is stored as a 6-bit VGA palette, thus each

                 * component is shifted up to a 8-bit range */

                r = scratch[j++] * 4;

                g = scratch[j++] * 4;

                b = scratch[j++] * 4;

                s->palette[i] = (0xFFU << 24) | (r << 16) | (g << 8) | (b);

                s->palette[i] |= s->palette[i] >> 6 & 0x30303;

            }

            s->has_palette = 1;

            break;



        case OPCODE_SET_PALETTE_COMPRESSED:

            av_log(s->avf, AV_LOG_TRACE, "set palette compressed\n");

            avio_skip(pb, opcode_size);

            break;



        case OPCODE_SET_DECODING_MAP:

            av_log(s->avf, AV_LOG_TRACE, "set decoding map\n");



            /* log position and move on for now */

            s->decode_map_chunk_offset = avio_tell(pb);

            s->decode_map_chunk_size = opcode_size;

            avio_skip(pb, opcode_size);

            break;



        case OPCODE_VIDEO_DATA_11:

            av_log(s->avf, AV_LOG_TRACE, "set video data\n");

            s->frame_format = 0x11;



            /* log position and move on for now */

            s->video_chunk_offset = avio_tell(pb);

            s->video_chunk_size = opcode_size;

            avio_skip(pb, opcode_size);

            break;



        default:

            av_log(s->avf, AV_LOG_TRACE, "*** unknown opcode type\n");

            chunk_type = CHUNK_BAD;

            break;



        }

    }



    if (s->avf->nb_streams == 1 && s->audio_type)

        init_audio(s->avf);



    /* make a note of where the stream is sitting */

    s->next_chunk_offset = avio_tell(pb);



    /* dispatch the first of any pending packets */

    if ((chunk_type == CHUNK_VIDEO) || (chunk_type == CHUNK_AUDIO_ONLY))

        chunk_type = load_ipmovie_packet(s, pb, pkt);



    return chunk_type;

}

static OutputStream *new_video_stream(OptionsContext *o, AVFormatContext *oc, int source_index)

{

    AVStream *st;

    OutputStream *ost;

    AVCodecContext *video_enc;

    char *frame_rate = NULL, *frame_aspect_ratio = NULL;



    ost = new_output_stream(o, oc, AVMEDIA_TYPE_VIDEO, source_index);

    st  = ost->st;

    video_enc = ost->enc_ctx;



    MATCH_PER_STREAM_OPT(frame_rates, str, frame_rate, oc, st);

    if (frame_rate && av_parse_video_rate(&ost->frame_rate, frame_rate) < 0) {

        av_log(NULL, AV_LOG_FATAL, "Invalid framerate value: %s\n", frame_rate);

        exit_program(1);

    }

    if (frame_rate && video_sync_method == VSYNC_PASSTHROUGH)

        av_log(NULL, AV_LOG_ERROR, "Using -vsync 0 and -r can produce invalid output files\n");



    MATCH_PER_STREAM_OPT(frame_aspect_ratios, str, frame_aspect_ratio, oc, st);

    if (frame_aspect_ratio) {

        AVRational q;

        if (av_parse_ratio(&q, frame_aspect_ratio, 255, 0, NULL) < 0 ||

            q.num <= 0 || q.den <= 0) {

            av_log(NULL, AV_LOG_FATAL, "Invalid aspect ratio: %s\n", frame_aspect_ratio);

            exit_program(1);

        }

        ost->frame_aspect_ratio = q;

    }



    MATCH_PER_STREAM_OPT(filter_scripts, str, ost->filters_script, oc, st);

    MATCH_PER_STREAM_OPT(filters,        str, ost->filters,        oc, st);



    if (!ost->stream_copy) {

        const char *p = NULL;

        char *frame_size = NULL;

        char *frame_pix_fmt = NULL;

        char *intra_matrix = NULL, *inter_matrix = NULL;

        char *chroma_intra_matrix = NULL;

        int do_pass = 0;

        int i;



        MATCH_PER_STREAM_OPT(frame_sizes, str, frame_size, oc, st);

        if (frame_size && av_parse_video_size(&video_enc->width, &video_enc->height, frame_size) < 0) {

            av_log(NULL, AV_LOG_FATAL, "Invalid frame size: %s.\n", frame_size);

            exit_program(1);

        }



        video_enc->bits_per_raw_sample = frame_bits_per_raw_sample;

        MATCH_PER_STREAM_OPT(frame_pix_fmts, str, frame_pix_fmt, oc, st);

        if (frame_pix_fmt && *frame_pix_fmt == '+') {

            ost->keep_pix_fmt = 1;

            if (!*++frame_pix_fmt)

                frame_pix_fmt = NULL;

        }

        if (frame_pix_fmt && (video_enc->pix_fmt = av_get_pix_fmt(frame_pix_fmt)) == AV_PIX_FMT_NONE) {

            av_log(NULL, AV_LOG_FATAL, "Unknown pixel format requested: %s.\n", frame_pix_fmt);

            exit_program(1);

        }

        st->sample_aspect_ratio = video_enc->sample_aspect_ratio;



        if (intra_only)

            video_enc->gop_size = 0;

        MATCH_PER_STREAM_OPT(intra_matrices, str, intra_matrix, oc, st);

        if (intra_matrix) {

            if (!(video_enc->intra_matrix = av_mallocz(sizeof(*video_enc->intra_matrix) * 64))) {

                av_log(NULL, AV_LOG_FATAL, "Could not allocate memory for intra matrix.\n");

                exit_program(1);

            }

            parse_matrix_coeffs(video_enc->intra_matrix, intra_matrix);

        }

        MATCH_PER_STREAM_OPT(chroma_intra_matrices, str, chroma_intra_matrix, oc, st);

        if (chroma_intra_matrix) {

            uint16_t *p = av_mallocz(sizeof(*video_enc->chroma_intra_matrix) * 64);

            if (!p) {

                av_log(NULL, AV_LOG_FATAL, "Could not allocate memory for intra matrix.\n");

                exit_program(1);

            }

            av_codec_set_chroma_intra_matrix(video_enc, p);

            parse_matrix_coeffs(p, chroma_intra_matrix);

        }

        MATCH_PER_STREAM_OPT(inter_matrices, str, inter_matrix, oc, st);

        if (inter_matrix) {

            if (!(video_enc->inter_matrix = av_mallocz(sizeof(*video_enc->inter_matrix) * 64))) {

                av_log(NULL, AV_LOG_FATAL, "Could not allocate memory for inter matrix.\n");

                exit_program(1);

            }

            parse_matrix_coeffs(video_enc->inter_matrix, inter_matrix);

        }



        MATCH_PER_STREAM_OPT(rc_overrides, str, p, oc, st);

        for (i = 0; p; i++) {

            int start, end, q;

            int e = sscanf(p, "%d,%d,%d", &start, &end, &q);

            if (e != 3) {

                av_log(NULL, AV_LOG_FATAL, "error parsing rc_override\n");

                exit_program(1);

            }

            /* FIXME realloc failure */

            video_enc->rc_override =

                av_realloc_array(video_enc->rc_override,

                                 i + 1, sizeof(RcOverride));

            video_enc->rc_override[i].start_frame = start;

            video_enc->rc_override[i].end_frame   = end;

            if (q > 0) {

                video_enc->rc_override[i].qscale         = q;

                video_enc->rc_override[i].quality_factor = 1.0;

            }

            else {

                video_enc->rc_override[i].qscale         = 0;

                video_enc->rc_override[i].quality_factor = -q/100.0;

            }

            p = strchr(p, '/');

            if (p) p++;

        }

        video_enc->rc_override_count = i;



        if (do_psnr)

            video_enc->flags|= CODEC_FLAG_PSNR;



        /* two pass mode */

        MATCH_PER_STREAM_OPT(pass, i, do_pass, oc, st);

        if (do_pass) {

            if (do_pass & 1) {

                video_enc->flags |= CODEC_FLAG_PASS1;

                av_dict_set(&ost->encoder_opts, "flags", "+pass1", AV_DICT_APPEND);

            }

            if (do_pass & 2) {

                video_enc->flags |= CODEC_FLAG_PASS2;

                av_dict_set(&ost->encoder_opts, "flags", "+pass2", AV_DICT_APPEND);

            }

        }



        MATCH_PER_STREAM_OPT(passlogfiles, str, ost->logfile_prefix, oc, st);

        if (ost->logfile_prefix &&

            !(ost->logfile_prefix = av_strdup(ost->logfile_prefix)))

            exit_program(1);



        MATCH_PER_STREAM_OPT(forced_key_frames, str, ost->forced_keyframes, oc, st);

        if (ost->forced_keyframes)

            ost->forced_keyframes = av_strdup(ost->forced_keyframes);



        MATCH_PER_STREAM_OPT(force_fps, i, ost->force_fps, oc, st);



        ost->top_field_first = -1;

        MATCH_PER_STREAM_OPT(top_field_first, i, ost->top_field_first, oc, st);





        ost->avfilter = get_ost_filters(o, oc, ost);

        if (!ost->avfilter)

            exit_program(1);

    } else {

        MATCH_PER_STREAM_OPT(copy_initial_nonkeyframes, i, ost->copy_initial_nonkeyframes, oc ,st);

    }



    if (ost->stream_copy)

        check_streamcopy_filters(o, oc, ost, AVMEDIA_TYPE_VIDEO);



    return ost;

}

int av_lockmgr_register(int (*cb)(void **mutex, enum AVLockOp op))

{

    if (lockmgr_cb) {

        // There is no good way to rollback a failure to destroy the

        // mutex, so we ignore failures.

        lockmgr_cb(&codec_mutex,    AV_LOCK_DESTROY);

        lockmgr_cb(&avformat_mutex, AV_LOCK_DESTROY);

        lockmgr_cb     = NULL;

        codec_mutex    = NULL;

        avformat_mutex = NULL;

    }



    if (cb) {

        void *new_codec_mutex    = NULL;

        void *new_avformat_mutex = NULL;

        int err;

        if (err = cb(&new_codec_mutex, AV_LOCK_CREATE)) {

            return err > 0 ? AVERROR_UNKNOWN : err;

        }

        if (err = cb(&new_avformat_mutex, AV_LOCK_CREATE)) {

            // Ignore failures to destroy the newly created mutex.

            cb(&new_codec_mutex, AV_LOCK_DESTROY);

            return err > 0 ? AVERROR_UNKNOWN : err;

        }

        lockmgr_cb     = cb;

        codec_mutex    = new_codec_mutex;

        avformat_mutex = new_avformat_mutex;

    }



    return 0;

}

static void compute_stereo(MPADecodeContext *s, GranuleDef *g0, GranuleDef *g1)

{

    int i, j, k, l;

    int sf_max, sf, len, non_zero_found;

    INTFLOAT (*is_tab)[16], *tab0, *tab1, tmp0, tmp1, v1, v2;

    int non_zero_found_short[3];



    /* intensity stereo */

    if (s->mode_ext & MODE_EXT_I_STEREO) {

        if (!s->lsf) {

            is_tab = is_table;

            sf_max = 7;

        } else {

            is_tab = is_table_lsf[g1->scalefac_compress & 1];

            sf_max = 16;

        }



        tab0 = g0->sb_hybrid + 576;

        tab1 = g1->sb_hybrid + 576;



        non_zero_found_short[0] = 0;

        non_zero_found_short[1] = 0;

        non_zero_found_short[2] = 0;

        k = (13 - g1->short_start) * 3 + g1->long_end - 3;

        for (i = 12; i >= g1->short_start; i--) {

            /* for last band, use previous scale factor */

            if (i != 11)

                k -= 3;

            len = band_size_short[s->sample_rate_index][i];

            for (l = 2; l >= 0; l--) {

                tab0 -= len;

                tab1 -= len;

                if (!non_zero_found_short[l]) {

                    /* test if non zero band. if so, stop doing i-stereo */

                    for (j = 0; j < len; j++) {

                        if (tab1[j] != 0) {

                            non_zero_found_short[l] = 1;

                            goto found1;

                        }

                    }

                    sf = g1->scale_factors[k + l];

                    if (sf >= sf_max)

                        goto found1;



                    v1 = is_tab[0][sf];

                    v2 = is_tab[1][sf];

                    for (j = 0; j < len; j++) {

                        tmp0    = tab0[j];

                        tab0[j] = MULLx(tmp0, v1, FRAC_BITS);

                        tab1[j] = MULLx(tmp0, v2, FRAC_BITS);

                    }

                } else {

found1:

                    if (s->mode_ext & MODE_EXT_MS_STEREO) {

                        /* lower part of the spectrum : do ms stereo

                           if enabled */

                        for (j = 0; j < len; j++) {

                            tmp0    = tab0[j];

                            tmp1    = tab1[j];

                            tab0[j] = MULLx(tmp0 + tmp1, ISQRT2, FRAC_BITS);

                            tab1[j] = MULLx(tmp0 - tmp1, ISQRT2, FRAC_BITS);

                        }

                    }

                }

            }

        }



        non_zero_found = non_zero_found_short[0] |

                         non_zero_found_short[1] |

                         non_zero_found_short[2];



        for (i = g1->long_end - 1;i >= 0;i--) {

            len   = band_size_long[s->sample_rate_index][i];

            tab0 -= len;

            tab1 -= len;

            /* test if non zero band. if so, stop doing i-stereo */

            if (!non_zero_found) {

                for (j = 0; j < len; j++) {

                    if (tab1[j] != 0) {

                        non_zero_found = 1;

                        goto found2;

                    }

                }

                /* for last band, use previous scale factor */

                k  = (i == 21) ? 20 : i;

                sf = g1->scale_factors[k];

                if (sf >= sf_max)

                    goto found2;

                v1 = is_tab[0][sf];

                v2 = is_tab[1][sf];

                for (j = 0; j < len; j++) {

                    tmp0    = tab0[j];

                    tab0[j] = MULLx(tmp0, v1, FRAC_BITS);

                    tab1[j] = MULLx(tmp0, v2, FRAC_BITS);

                }

            } else {

found2:

                if (s->mode_ext & MODE_EXT_MS_STEREO) {

                    /* lower part of the spectrum : do ms stereo

                       if enabled */

                    for (j = 0; j < len; j++) {

                        tmp0    = tab0[j];

                        tmp1    = tab1[j];

                        tab0[j] = MULLx(tmp0 + tmp1, ISQRT2, FRAC_BITS);

                        tab1[j] = MULLx(tmp0 - tmp1, ISQRT2, FRAC_BITS);

                    }

                }

            }

        }

    } else if (s->mode_ext & MODE_EXT_MS_STEREO) {

        /* ms stereo ONLY */

        /* NOTE: the 1/sqrt(2) normalization factor is included in the

           global gain */

#if USE_FLOATS

       s->fdsp->butterflies_float(g0->sb_hybrid, g1->sb_hybrid, 576);

#else

        tab0 = g0->sb_hybrid;

        tab1 = g1->sb_hybrid;

        for (i = 0; i < 576; i++) {

            tmp0    = tab0[i];

            tmp1    = tab1[i];

            tab0[i] = tmp0 + tmp1;

            tab1[i] = tmp0 - tmp1;

        }

#endif

    }

}

static int gxf_probe(AVProbeData *p) {

    static const uint8_t startcode[] = {0, 0, 0, 0, 1, 0xbc}; // start with map packet

    static const uint8_t endcode[] = {0, 0, 0, 0, 0xe1, 0xe2};

    if (p->buf_size < 16)

        return 0;

    if (!memcmp(p->buf, startcode, sizeof(startcode)) &&

        !memcmp(&p->buf[16 - sizeof(endcode)], endcode, sizeof(endcode)))

        return AVPROBE_SCORE_MAX;

    return 0;

}

static int targa_decode_rle(AVCodecContext *avctx, TargaContext *s, const uint8_t *src, int src_size, uint8_t *dst, int w, int h, int stride, int bpp)

{

    int i, x, y;

    int depth = (bpp + 1) >> 3;

    int type, count;

    int diff;

    const uint8_t *src_end = src + src_size;



    diff = stride - w * depth;

    x = y = 0;

    while(y < h){

        CHECK_BUFFER_SIZE(src, src_end, 1, "image type");

        type = *src++;

        count = (type & 0x7F) + 1;

        type &= 0x80;

        if((x + count > w) && (x + count + 1 > (h - y) * w)){

            av_log(avctx, AV_LOG_ERROR, "Packet went out of bounds: position (%i,%i) size %i\n", x, y, count);

            return -1;

        }

        if(type){

            CHECK_BUFFER_SIZE(src, src_end, depth, "image data");

        }else{

            CHECK_BUFFER_SIZE(src, src_end, count * depth, "image data");

        }

        for(i = 0; i < count; i++){

            switch(depth){

            case 1:

                *dst = *src;

                break;

            case 2:

                AV_WN16A(dst, AV_RN16A(src));

                break;

            case 3:

                dst[0] = src[0];

                dst[1] = src[1];

                dst[2] = src[2];

                break;

            case 4:

                AV_WN32A(dst, AV_RN32A(src));

                break;

            }

            dst += depth;

            if(!type)

                src += depth;



            x++;

            if(x == w){

                x = 0;

                y++;

                dst += diff;

            }

        }

        if(type)

            src += depth;

    }

    return src_size;

}

static int udp_read_packet(AVFormatContext *s, RTSPStream **prtsp_st,

                           uint8_t *buf, int buf_size)

{

    RTSPState *rt = s->priv_data;

    RTSPStream *rtsp_st;

    fd_set rfds;

    int fd, fd_max, n, i, ret, tcp_fd, timeout_cnt = 0;

    struct timeval tv;



    for (;;) {

        if (url_interrupt_cb())

            return AVERROR(EINTR);

        FD_ZERO(&rfds);

        if (rt->rtsp_hd) {

            tcp_fd = fd_max = url_get_file_handle(rt->rtsp_hd);

            FD_SET(tcp_fd, &rfds);

        } else {

            fd_max = 0;

            tcp_fd = -1;

        }

        for (i = 0; i < rt->nb_rtsp_streams; i++) {

            rtsp_st = rt->rtsp_streams[i];

            if (rtsp_st->rtp_handle) {

                /* currently, we cannot probe RTCP handle because of

                 * blocking restrictions */

                fd = url_get_file_handle(rtsp_st->rtp_handle);

                if (fd > fd_max)

                    fd_max = fd;

                FD_SET(fd, &rfds);

            }

        }

        tv.tv_sec = 0;

        tv.tv_usec = SELECT_TIMEOUT_MS * 1000;

        n = select(fd_max + 1, &rfds, NULL, NULL, &tv);

        if (n > 0) {

            timeout_cnt = 0;

            for (i = 0; i < rt->nb_rtsp_streams; i++) {

                rtsp_st = rt->rtsp_streams[i];

                if (rtsp_st->rtp_handle) {

                    fd = url_get_file_handle(rtsp_st->rtp_handle);

                    if (FD_ISSET(fd, &rfds)) {

                        ret = url_read(rtsp_st->rtp_handle, buf, buf_size);

                        if (ret > 0) {

                            *prtsp_st = rtsp_st;

                            return ret;

                        }

                    }

                }

            }

#if CONFIG_RTSP_DEMUXER

            if (tcp_fd != -1 && FD_ISSET(tcp_fd, &rfds)) {

                RTSPMessageHeader reply;



                ret = ff_rtsp_read_reply(s, &reply, NULL, 0);

                if (ret < 0)

                    return ret;

                /* XXX: parse message */

                if (rt->state != RTSP_STATE_STREAMING)

                    return 0;

            }

#endif

        } else if (n == 0 && ++timeout_cnt >= MAX_TIMEOUTS) {

            return FF_NETERROR(ETIMEDOUT);

        } else if (n < 0 && errno != EINTR)

            return AVERROR(errno);

    }

}

static int amf_parse_object(AVFormatContext *s, AVStream *astream, AVStream *vstream, const char *key, int64_t max_pos, int depth) {

    AVCodecContext *acodec, *vcodec;

    ByteIOContext *ioc;

    AMFDataType amf_type;

    char str_val[256];

    double num_val;



    num_val = 0;

    ioc = s->pb;



    amf_type = get_byte(ioc);



    switch(amf_type) {

        case AMF_DATA_TYPE_NUMBER:

            num_val = av_int2dbl(get_be64(ioc)); break;

        case AMF_DATA_TYPE_BOOL:

            num_val = get_byte(ioc); break;

        case AMF_DATA_TYPE_STRING:

            if(amf_get_string(ioc, str_val, sizeof(str_val)) < 0)

                return -1;

            break;

        case AMF_DATA_TYPE_OBJECT: {

            unsigned int keylen;



            while(url_ftell(ioc) < max_pos - 2 && (keylen = get_be16(ioc))) {

                url_fskip(ioc, keylen); //skip key string

                if(amf_parse_object(s, NULL, NULL, NULL, max_pos, depth + 1) < 0)

                    return -1; //if we couldn't skip, bomb out.

            }

            if(get_byte(ioc) != AMF_END_OF_OBJECT)

                return -1;

        }

            break;

        case AMF_DATA_TYPE_NULL:

        case AMF_DATA_TYPE_UNDEFINED:

        case AMF_DATA_TYPE_UNSUPPORTED:

            break; //these take up no additional space

        case AMF_DATA_TYPE_MIXEDARRAY:

            url_fskip(ioc, 4); //skip 32-bit max array index

            while(url_ftell(ioc) < max_pos - 2 && amf_get_string(ioc, str_val, sizeof(str_val)) > 0) {

                //this is the only case in which we would want a nested parse to not skip over the object

                if(amf_parse_object(s, astream, vstream, str_val, max_pos, depth + 1) < 0)

                    return -1;

            }

            if(get_byte(ioc) != AMF_END_OF_OBJECT)

                return -1;

            break;

        case AMF_DATA_TYPE_ARRAY: {

            unsigned int arraylen, i;



            arraylen = get_be32(ioc);

            for(i = 0; i < arraylen && url_ftell(ioc) < max_pos - 1; i++) {

                if(amf_parse_object(s, NULL, NULL, NULL, max_pos, depth + 1) < 0)

                    return -1; //if we couldn't skip, bomb out.

            }

        }

            break;

        case AMF_DATA_TYPE_DATE:

            url_fskip(ioc, 8 + 2); //timestamp (double) and UTC offset (int16)

            break;

        default: //unsupported type, we couldn't skip

            return -1;

    }



    if(depth == 1 && key) { //only look for metadata values when we are not nested and key != NULL

        acodec = astream ? astream->codec : NULL;

        vcodec = vstream ? vstream->codec : NULL;



        if(amf_type == AMF_DATA_TYPE_BOOL) {

        } else if(amf_type == AMF_DATA_TYPE_NUMBER) {

            if(!strcmp(key, "duration")) s->duration = num_val * AV_TIME_BASE;

            else if(!strcmp(key, "videodatarate") && vcodec && 0 <= (int)(num_val * 1024.0))

                vcodec->bit_rate = num_val * 1024.0;

        }

    }



    return 0;

}

static void mkv_write_simpletag(AVIOContext *pb, AVDictionaryEntry *t)

{

    uint8_t *key = av_strdup(t->key);

    uint8_t *p   = key;

    const uint8_t *lang = NULL;

    ebml_master tag;



    if ((p = strrchr(p, '-')) &&

        (lang = av_convert_lang_to(p + 1, AV_LANG_ISO639_2_BIBL)))

        *p = 0;



    p = key;

    while (*p) {

        if (*p == ' ')

            *p = '_';

        else if (*p >= 'a' && *p <= 'z')

            *p -= 'a' - 'A';

        p++;

    }



    tag = start_ebml_master(pb, MATROSKA_ID_SIMPLETAG, 0);

    put_ebml_string(pb, MATROSKA_ID_TAGNAME, key);

    if (lang)

        put_ebml_string(pb, MATROSKA_ID_TAGLANG, lang);

    put_ebml_string(pb, MATROSKA_ID_TAGSTRING, t->value);

    end_ebml_master(pb, tag);



    av_freep(&key);

}

static inline int decode_hrd_parameters(H264Context *h, SPS *sps)

{

    int cpb_count, i;

    cpb_count = get_ue_golomb_31(&h->gb) + 1;



    if (cpb_count > 32U) {

        av_log(h->avctx, AV_LOG_ERROR, "cpb_count %d invalid\n", cpb_count);

        return AVERROR_INVALIDDATA;

    }



    get_bits(&h->gb, 4); /* bit_rate_scale */

    get_bits(&h->gb, 4); /* cpb_size_scale */

    for (i = 0; i < cpb_count; i++) {

        get_ue_golomb_long(&h->gb); /* bit_rate_value_minus1 */

        get_ue_golomb_long(&h->gb); /* cpb_size_value_minus1 */

        get_bits1(&h->gb);          /* cbr_flag */

    }

    sps->initial_cpb_removal_delay_length = get_bits(&h->gb, 5) + 1;

    sps->cpb_removal_delay_length         = get_bits(&h->gb, 5) + 1;

    sps->dpb_output_delay_length          = get_bits(&h->gb, 5) + 1;

    sps->time_offset_length               = get_bits(&h->gb, 5);

    sps->cpb_cnt                          = cpb_count;

    return 0;

}

int av_aes_init(AVAES *a, const uint8_t *key, int key_bits, int decrypt) {

    int i, j, t, rconpointer = 0;

    uint8_t tk[8][4];

    int KC= key_bits>>5;

    int rounds= KC + 6;

    uint8_t  log8[256];

    uint8_t alog8[512];



    if(!enc_multbl[4][1023]){

        j=1;

        for(i=0; i<255; i++){

            alog8[i]=

            alog8[i+255]= j;

            log8[j]= i;

            j^= j+j;

            if(j>255) j^= 0x11B;

        }

        for(i=0; i<256; i++){

            j= i ? alog8[255-log8[i]] : 0;

            j ^= (j<<1) ^ (j<<2) ^ (j<<3) ^ (j<<4);

            j = (j ^ (j>>8) ^ 99) & 255;

            inv_sbox[j]= i;

            sbox    [i]= j;

        }

        init_multbl2(dec_multbl[0], (int[4]){0xe, 0x9, 0xd, 0xb}, log8, alog8, inv_sbox);

        init_multbl2(enc_multbl[0], (int[4]){0x2, 0x1, 0x1, 0x3}, log8, alog8, sbox);

    }



    if(key_bits!=128 && key_bits!=192 && key_bits!=256)

        return -1;



    a->rounds= rounds;



    memcpy(tk, key, KC*4);



    for(t= 0; t < (rounds+1)*16;) {

        memcpy(a->round_key[0][0]+t, tk, KC*4);

        t+= KC*4;



        for(i = 0; i < 4; i++)

            tk[0][i] ^= sbox[tk[KC-1][(i+1)&3]];

        tk[0][0] ^= rcon[rconpointer++];



        for(j = 1; j < KC; j++){

            if(KC != 8 || j != KC>>1)

                for(i = 0; i < 4; i++) tk[j][i] ^=      tk[j-1][i];

            else

                for(i = 0; i < 4; i++) tk[j][i] ^= sbox[tk[j-1][i]];

        }

    }



    if(decrypt){

        for(i=1; i<rounds; i++){

            uint8_t tmp[3][16];

            memcpy(tmp[2], a->round_key[i][0], 16);

            subshift(tmp[1], 0, sbox);

            mix(tmp, dec_multbl, 1, 3);

            memcpy(a->round_key[i][0], tmp[0], 16);

        }

    }else{

        for(i=0; i<(rounds+1)>>1; i++){

            for(j=0; j<16; j++)

                FFSWAP(int, a->round_key[i][0][j], a->round_key[rounds-i][0][j]);

        }

    }



    return 0;

}

static int grab_read_header(AVFormatContext *s1, AVFormatParameters *ap)

{

    VideoData *s = s1->priv_data;

    AVStream *st;

    int video_fd;

    int desired_palette, desired_depth;

    struct video_tuner tuner;

    struct video_audio audio;

    struct video_picture pict;

    int j;

    int vformat_num = FF_ARRAY_ELEMS(video_formats);



    av_log(s1, AV_LOG_WARNING, "V4L input device is deprecated and will be removed in the next release.");



    if (ap->time_base.den <= 0) {

        av_log(s1, AV_LOG_ERROR, "Wrong time base (%d)\n", ap->time_base.den);

        return -1;

    }

    s->time_base = ap->time_base;



    s->video_win.width = ap->width;

    s->video_win.height = ap->height;



    st = avformat_new_stream(s1, NULL);

    if (!st)

        return AVERROR(ENOMEM);

    avpriv_set_pts_info(st, 64, 1, 1000000); /* 64 bits pts in us */



    video_fd = open(s1->filename, O_RDWR);

    if (video_fd < 0) {

        av_log(s1, AV_LOG_ERROR, "%s: %s\n", s1->filename, strerror(errno));

        goto fail;

    }



    if (ioctl(video_fd, VIDIOCGCAP, &s->video_cap) < 0) {

        av_log(s1, AV_LOG_ERROR, "VIDIOCGCAP: %s\n", strerror(errno));

        goto fail;

    }



    if (!(s->video_cap.type & VID_TYPE_CAPTURE)) {

        av_log(s1, AV_LOG_ERROR, "Fatal: grab device does not handle capture\n");

        goto fail;

    }



    /* no values set, autodetect them */

    if (s->video_win.width <= 0 || s->video_win.height <= 0) {

        if (ioctl(video_fd, VIDIOCGWIN, &s->video_win, sizeof(s->video_win)) < 0) {

            av_log(s1, AV_LOG_ERROR, "VIDIOCGWIN: %s\n", strerror(errno));

            goto fail;

        }

    }



    if(av_image_check_size(s->video_win.width, s->video_win.height, 0, s1) < 0)

        return -1;



    desired_palette = -1;

    desired_depth = -1;

    for (j = 0; j < vformat_num; j++) {

        if (ap->pix_fmt == video_formats[j].pix_fmt) {

            desired_palette = video_formats[j].palette;

            desired_depth = video_formats[j].depth;

            break;

        }

    }



    /* set tv standard */

    if (!ioctl(video_fd, VIDIOCGTUNER, &tuner)) {

        tuner.mode = s->standard;

        ioctl(video_fd, VIDIOCSTUNER, &tuner);

    }



    /* unmute audio */

    audio.audio = 0;

    ioctl(video_fd, VIDIOCGAUDIO, &audio);

    memcpy(&s->audio_saved, &audio, sizeof(audio));

    audio.flags &= ~VIDEO_AUDIO_MUTE;

    ioctl(video_fd, VIDIOCSAUDIO, &audio);



    ioctl(video_fd, VIDIOCGPICT, &pict);

    av_dlog(s1, "v4l: colour=%d hue=%d brightness=%d constrast=%d whiteness=%d\n",

            pict.colour, pict.hue, pict.brightness, pict.contrast, pict.whiteness);

    /* try to choose a suitable video format */

    pict.palette = desired_palette;

    pict.depth= desired_depth;

    if (desired_palette == -1 || ioctl(video_fd, VIDIOCSPICT, &pict) < 0) {

        for (j = 0; j < vformat_num; j++) {

            pict.palette = video_formats[j].palette;

            pict.depth = video_formats[j].depth;

            if (-1 != ioctl(video_fd, VIDIOCSPICT, &pict))

                break;

        }

        if (j >= vformat_num)

            goto fail1;

    }



    if (ioctl(video_fd, VIDIOCGMBUF, &s->gb_buffers) < 0) {

        /* try to use read based access */

        int val;



        s->video_win.x = 0;

        s->video_win.y = 0;

        s->video_win.chromakey = -1;

        s->video_win.flags = 0;



        if (ioctl(video_fd, VIDIOCSWIN, s->video_win) < 0) {

            av_log(s1, AV_LOG_ERROR, "VIDIOCSWIN: %s\n", strerror(errno));

            goto fail;

        }



        s->frame_format = pict.palette;



        val = 1;

        if (ioctl(video_fd, VIDIOCCAPTURE, &val) < 0) {

            av_log(s1, AV_LOG_ERROR, "VIDIOCCAPTURE: %s\n", strerror(errno));

            goto fail;

        }



        s->time_frame = av_gettime() * s->time_base.den / s->time_base.num;

        s->use_mmap = 0;

    } else {

        s->video_buf = mmap(0, s->gb_buffers.size, PROT_READ|PROT_WRITE, MAP_SHARED, video_fd, 0);

        if ((unsigned char*)-1 == s->video_buf) {

            s->video_buf = mmap(0, s->gb_buffers.size, PROT_READ|PROT_WRITE, MAP_PRIVATE, video_fd, 0);

            if ((unsigned char*)-1 == s->video_buf) {

                av_log(s1, AV_LOG_ERROR, "mmap: %s\n", strerror(errno));

                goto fail;

            }

        }

        s->gb_frame = 0;

        s->time_frame = av_gettime() * s->time_base.den / s->time_base.num;



        /* start to grab the first frame */

        s->gb_buf.frame = s->gb_frame % s->gb_buffers.frames;

        s->gb_buf.height = s->video_win.height;

        s->gb_buf.width = s->video_win.width;

        s->gb_buf.format = pict.palette;



        if (ioctl(video_fd, VIDIOCMCAPTURE, &s->gb_buf) < 0) {

            if (errno != EAGAIN) {

            fail1:

                av_log(s1, AV_LOG_ERROR, "VIDIOCMCAPTURE: %s\n", strerror(errno));

            } else {

                av_log(s1, AV_LOG_ERROR, "Fatal: grab device does not receive any video signal\n");

            }

            goto fail;

        }

        for (j = 1; j < s->gb_buffers.frames; j++) {

          s->gb_buf.frame = j;

          ioctl(video_fd, VIDIOCMCAPTURE, &s->gb_buf);

        }

        s->frame_format = s->gb_buf.format;

        s->use_mmap = 1;

    }



    for (j = 0; j < vformat_num; j++) {

        if (s->frame_format == video_formats[j].palette) {

            s->frame_size = s->video_win.width * s->video_win.height * video_formats[j].depth / 8;

            st->codec->pix_fmt = video_formats[j].pix_fmt;

            break;

        }

    }



    if (j >= vformat_num)

        goto fail;



    s->fd = video_fd;



    st->codec->codec_type = AVMEDIA_TYPE_VIDEO;

    st->codec->codec_id = AV_CODEC_ID_RAWVIDEO;

    st->codec->width = s->video_win.width;

    st->codec->height = s->video_win.height;

    st->codec->time_base = s->time_base;

    st->codec->bit_rate = s->frame_size * 1/av_q2d(st->codec->time_base) * 8;



    return 0;

 fail:

    if (video_fd >= 0)

        close(video_fd);

    return AVERROR(EIO);

}

