    int8_t (*opd_mapped)[PS_MAX_NR_IIDICC] = opd_mapped_buf;

    const int8_t *k_to_i = is34 ? k_to_i_34 : k_to_i_20;

    TABLE_CONST float (*H_LUT)[8][4] = (PS_BASELINE || ps->icc_mode < 3) ? HA : HB;



    //Remapping

    if (ps->num_env_old) {

        memcpy(H11[0][0], H11[0][ps->num_env_old], PS_MAX_NR_IIDICC*sizeof(H11[0][0][0]));

        memcpy(H11[1][0], H11[1][ps->num_env_old], PS_MAX_NR_IIDICC*sizeof(H11[1][0][0]));

        memcpy(H12[0][0], H12[0][ps->num_env_old], PS_MAX_NR_IIDICC*sizeof(H12[0][0][0]));

        memcpy(H12[1][0], H12[1][ps->num_env_old], PS_MAX_NR_IIDICC*sizeof(H12[1][0][0]));

        memcpy(H21[0][0], H21[0][ps->num_env_old], PS_MAX_NR_IIDICC*sizeof(H21[0][0][0]));

        memcpy(H21[1][0], H21[1][ps->num_env_old], PS_MAX_NR_IIDICC*sizeof(H21[1][0][0]));

        memcpy(H22[0][0], H22[0][ps->num_env_old], PS_MAX_NR_IIDICC*sizeof(H22[0][0][0]));

        memcpy(H22[1][0], H22[1][ps->num_env_old], PS_MAX_NR_IIDICC*sizeof(H22[1][0][0]));

    }



    if (is34) {

        remap34(&iid_mapped, ps->iid_par, ps->nr_iid_par, ps->num_env, 1);

        remap34(&icc_mapped, ps->icc_par, ps->nr_icc_par, ps->num_env, 1);

        if (ps->enable_ipdopd) {

            remap34(&ipd_mapped, ps->ipd_par, ps->nr_ipdopd_par, ps->num_env, 0);

            remap34(&opd_mapped, ps->opd_par, ps->nr_ipdopd_par, ps->num_env, 0);

        }

        if (!ps->is34bands_old) {

            map_val_20_to_34(H11[0][0]);

            map_val_20_to_34(H11[1][0]);

            map_val_20_to_34(H12[0][0]);

            map_val_20_to_34(H12[1][0]);

            map_val_20_to_34(H21[0][0]);

            map_val_20_to_34(H21[1][0]);

            map_val_20_to_34(H22[0][0]);

            map_val_20_to_34(H22[1][0]);

            ipdopd_reset(ipd_hist, opd_hist);

        }

    } else {

        remap20(&iid_mapped, ps->iid_par, ps->nr_iid_par, ps->num_env, 1);

        remap20(&icc_mapped, ps->icc_par, ps->nr_icc_par, ps->num_env, 1);

        if (ps->enable_ipdopd) {

            remap20(&ipd_mapped, ps->ipd_par, ps->nr_ipdopd_par, ps->num_env, 0);

            remap20(&opd_mapped, ps->opd_par, ps->nr_ipdopd_par, ps->num_env, 0);

        }

        if (ps->is34bands_old) {

            map_val_34_to_20(H11[0][0]);

            map_val_34_to_20(H11[1][0]);

            map_val_34_to_20(H12[0][0]);

            map_val_34_to_20(H12[1][0]);

            map_val_34_to_20(H21[0][0]);

            map_val_34_to_20(H21[1][0]);

            map_val_34_to_20(H22[0][0]);

            map_val_34_to_20(H22[1][0]);

            ipdopd_reset(ipd_hist, opd_hist);

        }

    }



    //Mixing

    for (e = 0; e < ps->num_env; e++) {

        for (b = 0; b < NR_PAR_BANDS[is34]; b++) {

            float h11, h12, h21, h22;

            h11 = H_LUT[iid_mapped[e][b] + 7 + 23 * ps->iid_quant][icc_mapped[e][b]][0];

            h12 = H_LUT[iid_mapped[e][b] + 7 + 23 * ps->iid_quant][icc_mapped[e][b]][1];

            h21 = H_LUT[iid_mapped[e][b] + 7 + 23 * ps->iid_quant][icc_mapped[e][b]][2];

            h22 = H_LUT[iid_mapped[e][b] + 7 + 23 * ps->iid_quant][icc_mapped[e][b]][3];



            if (!PS_BASELINE && ps->enable_ipdopd && 2*b <= NR_PAR_BANDS[is34]) {

                //The spec say says to only run this smoother when enable_ipdopd

                //is set but the reference decoder appears to run it constantly

                float h11i, h12i, h21i, h22i;

                float ipd_adj_re, ipd_adj_im;

                int opd_idx = opd_hist[b] * 8 + opd_mapped[e][b];

                int ipd_idx = ipd_hist[b] * 8 + ipd_mapped[e][b];

                float opd_re = pd_re_smooth[opd_idx];

                float opd_im = pd_im_smooth[opd_idx];

                float ipd_re = pd_re_smooth[ipd_idx];

                float ipd_im = pd_im_smooth[ipd_idx];

                opd_hist[b] = opd_idx & 0x3F;

                ipd_hist[b] = ipd_idx & 0x3F;



                ipd_adj_re = opd_re*ipd_re + opd_im*ipd_im;

                ipd_adj_im = opd_im*ipd_re - opd_re*ipd_im;

                h11i = h11 * opd_im;

                h11  = h11 * opd_re;

                h12i = h12 * ipd_adj_im;

                h12  = h12 * ipd_adj_re;

                h21i = h21 * opd_im;

                h21  = h21 * opd_re;

                h22i = h22 * ipd_adj_im;

                h22  = h22 * ipd_adj_re;

                H11[1][e+1][b] = h11i;

                H12[1][e+1][b] = h12i;

                H21[1][e+1][b] = h21i;

                H22[1][e+1][b] = h22i;

            }

            H11[0][e+1][b] = h11;

            H12[0][e+1][b] = h12;

            H21[0][e+1][b] = h21;

            H22[0][e+1][b] = h22;

        }

        for (k = 0; k < NR_BANDS[is34]; k++) {

            float h[2][4];

            float h_step[2][4];

            int start = ps->border_position[e];

            int stop  = ps->border_position[e+1];

            float width = 1.f / (stop - start);

            b = k_to_i[k];

            h[0][0] = H11[0][e][b];

            h[0][1] = H12[0][e][b];

            h[0][2] = H21[0][e][b];

            h[0][3] = H22[0][e][b];

            if (!PS_BASELINE && ps->enable_ipdopd) {

            //Is this necessary? ps_04_new seems unchanged

            if ((is34 && k <= 13 && k >= 9) || (!is34 && k <= 1)) {

                h[1][0] = -H11[1][e][b];

                h[1][1] = -H12[1][e][b];

                h[1][2] = -H21[1][e][b];

                h[1][3] = -H22[1][e][b];

            } else {

                h[1][0] = H11[1][e][b];

                h[1][1] = H12[1][e][b];

                h[1][2] = H21[1][e][b];

                h[1][3] = H22[1][e][b];

            }

            }

            //Interpolation

            h_step[0][0] = (H11[0][e+1][b] - h[0][0]) * width;

            h_step[0][1] = (H12[0][e+1][b] - h[0][1]) * width;

            h_step[0][2] = (H21[0][e+1][b] - h[0][2]) * width;

            h_step[0][3] = (H22[0][e+1][b] - h[0][3]) * width;

            if (!PS_BASELINE && ps->enable_ipdopd) {

                h_step[1][0] = (H11[1][e+1][b] - h[1][0]) * width;

                h_step[1][1] = (H12[1][e+1][b] - h[1][1]) * width;

                h_step[1][2] = (H21[1][e+1][b] - h[1][2]) * width;

                h_step[1][3] = (H22[1][e+1][b] - h[1][3]) * width;

            }

            ps->dsp.stereo_interpolate[!PS_BASELINE && ps->enable_ipdopd](

                l[k] + start + 1, r[k] + start + 1,

                h, h_step, stop - start);

        }

    }

}

static int decode_header(MPADecodeContext *s, uint32_t header)

{

    int sample_rate, frame_size, mpeg25, padding;

    int sample_rate_index, bitrate_index;

    if (header & (1<<20)) {

        s->lsf = (header & (1<<19)) ? 0 : 1;

        mpeg25 = 0;

    } else {

        s->lsf = 1;

        mpeg25 = 1;

    }



    s->layer = 4 - ((header >> 17) & 3);

    /* extract frequency */

    sample_rate_index = (header >> 10) & 3;

    sample_rate = mpa_freq_tab[sample_rate_index] >> (s->lsf + mpeg25);

    sample_rate_index += 3 * (s->lsf + mpeg25);

    s->sample_rate_index = sample_rate_index;

    s->error_protection = ((header >> 16) & 1) ^ 1;

    s->sample_rate = sample_rate;



    bitrate_index = (header >> 12) & 0xf;

    padding = (header >> 9) & 1;

    //extension = (header >> 8) & 1;

    s->mode = (header >> 6) & 3;

    s->mode_ext = (header >> 4) & 3;

    //copyright = (header >> 3) & 1;

    //original = (header >> 2) & 1;

    //emphasis = header & 3;



    if (s->mode == MPA_MONO)

        s->nb_channels = 1;

    else

        s->nb_channels = 2;



    if (bitrate_index != 0) {

        frame_size = mpa_bitrate_tab[s->lsf][s->layer - 1][bitrate_index];

        s->bit_rate = frame_size * 1000;

        switch(s->layer) {

        case 1:

            frame_size = (frame_size * 12000) / sample_rate;

            frame_size = (frame_size + padding) * 4;

            break;

        case 2:

            frame_size = (frame_size * 144000) / sample_rate;

            frame_size += padding;

            break;

        default:

        case 3:

            frame_size = (frame_size * 144000) / (sample_rate << s->lsf);

            frame_size += padding;

            break;

        }

        s->frame_size = frame_size;

    } else {

        /* if no frame size computed, signal it */

        if (!s->free_format_frame_size)

            return 1;

        /* free format: compute bitrate and real frame size from the

           frame size we extracted by reading the bitstream */

        s->frame_size = s->free_format_frame_size;

        switch(s->layer) {

        case 1:

            s->frame_size += padding  * 4;

            s->bit_rate = (s->frame_size * sample_rate) / 48000;

            break;

        case 2:

            s->frame_size += padding;

            s->bit_rate = (s->frame_size * sample_rate) / 144000;

            break;

        default:

        case 3:

            s->frame_size += padding;

            s->bit_rate = (s->frame_size * (sample_rate << s->lsf)) / 144000;

            break;

        }

    }



#if defined(DEBUG)

    dprintf("layer%d, %d Hz, %d kbits/s, ",

           s->layer, s->sample_rate, s->bit_rate);

    if (s->nb_channels == 2) {

        if (s->layer == 3) {

            if (s->mode_ext & MODE_EXT_MS_STEREO)

                dprintf("ms-");

            if (s->mode_ext & MODE_EXT_I_STEREO)

                dprintf("i-");

        }

        dprintf("stereo");

    } else {

        dprintf("mono");

    }

    dprintf("\n");

#endif

    return 0;

}

static int dx2_decode_slice_rgb(GetBitContext *gb, AVFrame *frame,

                                int line, int left, uint8_t lru[3][8])

{

    int x, y;

    int width    = frame->width;

    int stride   = frame->linesize[0];

    uint8_t *dst = frame->data[0] + stride * line;



    for (y = 0; y < left && get_bits_left(gb) > 16; y++) {

        for (x = 0; x < width; x++) {

            dst[x * 3 + 0] = decode_sym(gb, lru[0]);

            dst[x * 3 + 1] = decode_sym(gb, lru[1]);

            dst[x * 3 + 2] = decode_sym(gb, lru[2]);

        }



        dst += stride;

    }



    return y;

}

static int mjpeg_decode_frame(AVCodecContext *avctx, 

                              void *data, int *data_size,

                              uint8_t *buf, int buf_size)

{

    MJpegDecodeContext *s = avctx->priv_data;

    uint8_t *buf_end, *buf_ptr;

    int i, start_code;

    AVPicture *picture = data;



    *data_size = 0;



    /* no supplementary picture */

    if (buf_size == 0)

        return 0;



    buf_ptr = buf;

    buf_end = buf + buf_size;

    while (buf_ptr < buf_end) {

        /* find start next marker */

        start_code = find_marker(&buf_ptr, buf_end);

	{

	    /* EOF */

            if (start_code < 0) {

		goto the_end;

            } else {

                dprintf("marker=%x avail_size_in_buf=%d\n", start_code, buf_end - buf_ptr);



		if ((buf_end - buf_ptr) > s->buffer_size)

		{

		    av_free(s->buffer);

		    s->buffer_size = buf_end-buf_ptr;

		    s->buffer = av_malloc(s->buffer_size);

		    dprintf("buffer too small, expanding to %d bytes\n",

			s->buffer_size);

		}



		/* unescape buffer of SOS */

		if (start_code == SOS)

		{

		    uint8_t *src = buf_ptr;

		    uint8_t *dst = s->buffer;



		    while (src<buf_end)

		    {

			uint8_t x = *(src++);



			*(dst++) = x;

			if (x == 0xff)

			{

			    while(*src == 0xff) src++;



			    x = *(src++);

			    if (x >= 0xd0 && x <= 0xd7)

				*(dst++) = x;

			    else if (x)

				break;

			}

		    }

		    init_get_bits(&s->gb, s->buffer, (dst - s->buffer)*8);



		    dprintf("escaping removed %d bytes\n",

			(buf_end - buf_ptr) - (dst - s->buffer));

		}

		else

		    init_get_bits(&s->gb, buf_ptr, (buf_end - buf_ptr)*8);



		s->start_code = start_code;

                if(s->avctx->debug & FF_DEBUG_STARTCODE){

                    printf("startcode: %X\n", start_code);

                }



		/* process markers */

		if (start_code >= 0xd0 && start_code <= 0xd7) {

		    dprintf("restart marker: %d\n", start_code&0x0f);

		} else if (s->first_picture) {

		    /* APP fields */

		    if (start_code >= 0xe0 && start_code <= 0xef)

			mjpeg_decode_app(s);

		    /* Comment */

		    else if (start_code == COM)

			mjpeg_decode_com(s);

		}



                switch(start_code) {

                case SOI:

		    s->restart_interval = 0;

                    /* nothing to do on SOI */

                    break;

                case DQT:

                    mjpeg_decode_dqt(s);

                    break;

                case DHT:

                    mjpeg_decode_dht(s);

                    break;

                case SOF0:

                    s->lossless=0;

                    if (mjpeg_decode_sof(s) < 0) 

			return -1;

                    break;

                case SOF3:

                    s->lossless=1;

                    if (mjpeg_decode_sof(s) < 0) 

			return -1;

                    break;

		case EOI:

eoi_parser:

		    {

                        if (s->interlaced) {

                            s->bottom_field ^= 1;

                            /* if not bottom field, do not output image yet */

                            if (s->bottom_field)

                                goto not_the_end;

                        }

                        for(i=0;i<3;i++) {

                            picture->data[i] = s->current_picture[i];

			    picture->linesize[i] = (s->interlaced) ?

				s->linesize[i] >> 1 : s->linesize[i];

                        }

                        *data_size = sizeof(AVPicture);

                        avctx->height = s->height;

                        if (s->interlaced)

                            avctx->height *= 2;

                        avctx->width = s->width;

                        /* XXX: not complete test ! */

                        switch((s->h_count[0] << 4) | s->v_count[0]) {

                        case 0x11:

                            if(s->rgb){

                                avctx->pix_fmt = PIX_FMT_RGBA32;

                            }else

                                avctx->pix_fmt = PIX_FMT_YUV444P;

                            break;

                        case 0x21:

                            avctx->pix_fmt = PIX_FMT_YUV422P;

                            break;

                        default:

                        case 0x22:

                            avctx->pix_fmt = PIX_FMT_YUV420P;

                            break;

                        }

                        /* dummy quality */

                        /* XXX: infer it with matrix */

//                    	avctx->quality = 3; 

                        goto the_end;

                    }

		    break;

                case SOS:

                    mjpeg_decode_sos(s);

		    /* buggy avid puts EOI every 10-20th frame */

		    /* if restart period is over process EOI */

		    if ((s->buggy_avid && !s->interlaced) || s->restart_interval)

			goto eoi_parser;

                    break;

		case DRI:

		    mjpeg_decode_dri(s);

		    break;

		case SOF1:

		case SOF2:

		case SOF5:

		case SOF6:

		case SOF7:

		case SOF9:

		case SOF10:

		case SOF11:

		case SOF13:

		case SOF14:

		case SOF15:

		case JPG:

		    printf("mjpeg: unsupported coding type (%x)\n", start_code);

		    break;

//		default:

//		    printf("mjpeg: unsupported marker (%x)\n", start_code);

//		    break;

                }



not_the_end:

		/* eof process start code */

		buf_ptr += (get_bits_count(&s->gb)+7)/8;

		dprintf("marker parser used %d bytes (%d bits)\n",

		    (get_bits_count(&s->gb)+7)/8, get_bits_count(&s->gb));

            }

        }

    }

the_end:

    dprintf("mjpeg decode frame unused %d bytes\n", buf_end - buf_ptr);

//    return buf_end - buf_ptr;

    return buf_ptr - buf;

}

static av_cold int svq3_decode_init(AVCodecContext *avctx)

{

    SVQ3Context *svq3 = avctx->priv_data;

    H264Context *h = &svq3->h;

    MpegEncContext *s = &h->s;

    int m;

    unsigned char *extradata;

    unsigned char *extradata_end;

    unsigned int size;

    int marker_found = 0;



    if (ff_h264_decode_init(avctx) < 0)

        return -1;



    s->flags  = avctx->flags;

    s->flags2 = avctx->flags2;

    s->unrestricted_mv = 1;

    h->is_complex=1;

    h->sps.chroma_format_idc = 1;

    avctx->pix_fmt = avctx->codec->pix_fmts[0];



    if (!s->context_initialized) {

        h->chroma_qp[0] = h->chroma_qp[1] = 4;



        svq3->halfpel_flag  = 1;

        svq3->thirdpel_flag = 1;

        svq3->unknown_flag  = 0;





        /* prowl for the "SEQH" marker in the extradata */

        extradata = (unsigned char *)avctx->extradata;

        extradata_end = avctx->extradata + avctx->extradata_size;

        if (extradata) {

            for (m = 0; m + 8 < avctx->extradata_size; m++) {

                if (!memcmp(extradata, "SEQH", 4)) {

                    marker_found = 1;

                    break;

                }

                extradata++;

            }

        }



        /* if a match was found, parse the extra data */

        if (marker_found) {



            GetBitContext gb;

            int frame_size_code;



            size = AV_RB32(&extradata[4]);

            if (size > extradata_end - extradata - 8)

                return AVERROR_INVALIDDATA;

            init_get_bits(&gb, extradata + 8, size*8);



            /* 'frame size code' and optional 'width, height' */

            frame_size_code = get_bits(&gb, 3);

            switch (frame_size_code) {

                case 0: avctx->width = 160; avctx->height = 120; break;

                case 1: avctx->width = 128; avctx->height =  96; break;

                case 2: avctx->width = 176; avctx->height = 144; break;

                case 3: avctx->width = 352; avctx->height = 288; break;

                case 4: avctx->width = 704; avctx->height = 576; break;

                case 5: avctx->width = 240; avctx->height = 180; break;

                case 6: avctx->width = 320; avctx->height = 240; break;

                case 7:

                    avctx->width  = get_bits(&gb, 12);

                    avctx->height = get_bits(&gb, 12);

                    break;

            }



            svq3->halfpel_flag  = get_bits1(&gb);

            svq3->thirdpel_flag = get_bits1(&gb);



            /* unknown fields */

            skip_bits1(&gb);

            skip_bits1(&gb);

            skip_bits1(&gb);

            skip_bits1(&gb);



            s->low_delay = get_bits1(&gb);



            /* unknown field */

            skip_bits1(&gb);



            while (get_bits1(&gb)) {

                skip_bits(&gb, 8);

            }



            svq3->unknown_flag = get_bits1(&gb);

            avctx->has_b_frames = !s->low_delay;

            if (svq3->unknown_flag) {

#if CONFIG_ZLIB

                unsigned watermark_width  = svq3_get_ue_golomb(&gb);

                unsigned watermark_height = svq3_get_ue_golomb(&gb);

                int u1 = svq3_get_ue_golomb(&gb);

                int u2 = get_bits(&gb, 8);

                int u3 = get_bits(&gb, 2);

                int u4 = svq3_get_ue_golomb(&gb);

                unsigned long buf_len = watermark_width*watermark_height*4;

                int offset = (get_bits_count(&gb)+7)>>3;

                uint8_t *buf;



                if ((uint64_t)watermark_width*4 > UINT_MAX/watermark_height)

                    return -1;



                buf = av_malloc(buf_len);

                av_log(avctx, AV_LOG_DEBUG, "watermark size: %dx%d\n", watermark_width, watermark_height);

                av_log(avctx, AV_LOG_DEBUG, "u1: %x u2: %x u3: %x compressed data size: %d offset: %d\n", u1, u2, u3, u4, offset);

                if (uncompress(buf, &buf_len, extradata + 8 + offset, size - offset) != Z_OK) {

                    av_log(avctx, AV_LOG_ERROR, "could not uncompress watermark logo\n");

                    av_free(buf);

                    return -1;

                }

                svq3->watermark_key = ff_svq1_packet_checksum(buf, buf_len, 0);

                svq3->watermark_key = svq3->watermark_key << 16 | svq3->watermark_key;

                av_log(avctx, AV_LOG_DEBUG, "watermark key %#x\n", svq3->watermark_key);

                av_free(buf);

#else

                av_log(avctx, AV_LOG_ERROR, "this svq3 file contains watermark which need zlib support compiled in\n");

                return -1;

#endif

            }

        }



        s->width  = avctx->width;

        s->height = avctx->height;



        if (ff_MPV_common_init(s) < 0)

            return -1;



        h->b_stride = 4*s->mb_width;



        if (ff_h264_alloc_tables(h) < 0) {

            av_log(avctx, AV_LOG_ERROR, "svq3 memory allocation failed\n");

            return AVERROR(ENOMEM);

        }

    }



    return 0;

}

int ff_vp56_decode_frame(AVCodecContext *avctx, void *data, int *data_size,

                         AVPacket *avpkt)

{

    const uint8_t *buf = avpkt->data;

    VP56Context *s = avctx->priv_data;

    AVFrame *const p = s->framep[VP56_FRAME_CURRENT];

    int remaining_buf_size = avpkt->size;

    int is_alpha, av_uninit(alpha_offset);



    if (s->has_alpha) {

        if (remaining_buf_size < 3)

            return -1;

        alpha_offset = bytestream_get_be24(&buf);

        remaining_buf_size -= 3;

        if (remaining_buf_size < alpha_offset)

            return -1;

    }



    for (is_alpha=0; is_alpha < 1+s->has_alpha; is_alpha++) {

        int mb_row, mb_col, mb_row_flip, mb_offset = 0;

        int block, y, uv, stride_y, stride_uv;

        int golden_frame = 0;

        int res;



        s->modelp = &s->models[is_alpha];



        res = s->parse_header(s, buf, remaining_buf_size, &golden_frame);

        if (!res)

            return -1;



        if (res == 2) {

            int i;

            for (i = 0; i < 4; i++) {

                if (s->frames[i].data[0])

                    avctx->release_buffer(avctx, &s->frames[i]);

            }

            if (is_alpha)

                return -1;

        }



        if (!is_alpha) {

            p->reference = 1;

            if (avctx->get_buffer(avctx, p) < 0) {

                av_log(avctx, AV_LOG_ERROR, "get_buffer() failed\n");

                return -1;

            }



            if (res == 2)

                if (vp56_size_changed(avctx)) {

                    avctx->release_buffer(avctx, p);

                    return -1;

                }

        }



        if (p->key_frame) {

            p->pict_type = AV_PICTURE_TYPE_I;

            s->default_models_init(s);

            for (block=0; block<s->mb_height*s->mb_width; block++)

                s->macroblocks[block].type = VP56_MB_INTRA;

        } else {

            p->pict_type = AV_PICTURE_TYPE_P;

            vp56_parse_mb_type_models(s);

            s->parse_vector_models(s);

            s->mb_type = VP56_MB_INTER_NOVEC_PF;

        }



        s->parse_coeff_models(s);



        memset(s->prev_dc, 0, sizeof(s->prev_dc));

        s->prev_dc[1][VP56_FRAME_CURRENT] = 128;

        s->prev_dc[2][VP56_FRAME_CURRENT] = 128;



        for (block=0; block < 4*s->mb_width+6; block++) {

            s->above_blocks[block].ref_frame = VP56_FRAME_NONE;

            s->above_blocks[block].dc_coeff = 0;

            s->above_blocks[block].not_null_dc = 0;

        }

        s->above_blocks[2*s->mb_width + 2].ref_frame = VP56_FRAME_CURRENT;

        s->above_blocks[3*s->mb_width + 4].ref_frame = VP56_FRAME_CURRENT;



        stride_y  = p->linesize[0];

        stride_uv = p->linesize[1];



        if (s->flip < 0)

            mb_offset = 7;



        /* main macroblocks loop */

        for (mb_row=0; mb_row<s->mb_height; mb_row++) {

            if (s->flip < 0)

                mb_row_flip = s->mb_height - mb_row - 1;

            else

                mb_row_flip = mb_row;



            for (block=0; block<4; block++) {

                s->left_block[block].ref_frame = VP56_FRAME_NONE;

                s->left_block[block].dc_coeff = 0;

                s->left_block[block].not_null_dc = 0;

            }

            memset(s->coeff_ctx, 0, sizeof(s->coeff_ctx));

            memset(s->coeff_ctx_last, 24, sizeof(s->coeff_ctx_last));



            s->above_block_idx[0] = 1;

            s->above_block_idx[1] = 2;

            s->above_block_idx[2] = 1;

            s->above_block_idx[3] = 2;

            s->above_block_idx[4] = 2*s->mb_width + 2 + 1;

            s->above_block_idx[5] = 3*s->mb_width + 4 + 1;



            s->block_offset[s->frbi] = (mb_row_flip*16 + mb_offset) * stride_y;

            s->block_offset[s->srbi] = s->block_offset[s->frbi] + 8*stride_y;

            s->block_offset[1] = s->block_offset[0] + 8;

            s->block_offset[3] = s->block_offset[2] + 8;

            s->block_offset[4] = (mb_row_flip*8 + mb_offset) * stride_uv;

            s->block_offset[5] = s->block_offset[4];



            for (mb_col=0; mb_col<s->mb_width; mb_col++) {

                vp56_decode_mb(s, mb_row, mb_col, is_alpha);



                for (y=0; y<4; y++) {

                    s->above_block_idx[y] += 2;

                    s->block_offset[y] += 16;

                }



                for (uv=4; uv<6; uv++) {

                    s->above_block_idx[uv] += 1;

                    s->block_offset[uv] += 8;

                }

            }

        }



        if (p->key_frame || golden_frame) {

            if (s->framep[VP56_FRAME_GOLDEN]->data[0] &&

                s->framep[VP56_FRAME_GOLDEN] != s->framep[VP56_FRAME_GOLDEN2])

                avctx->release_buffer(avctx, s->framep[VP56_FRAME_GOLDEN]);

            s->framep[VP56_FRAME_GOLDEN] = p;

        }



        if (s->has_alpha) {

            FFSWAP(AVFrame *, s->framep[VP56_FRAME_GOLDEN],

                              s->framep[VP56_FRAME_GOLDEN2]);

            buf += alpha_offset;

            remaining_buf_size -= alpha_offset;

        }

    }



    if (s->framep[VP56_FRAME_PREVIOUS] == s->framep[VP56_FRAME_GOLDEN] ||

        s->framep[VP56_FRAME_PREVIOUS] == s->framep[VP56_FRAME_GOLDEN2]) {

        if (s->framep[VP56_FRAME_UNUSED] != s->framep[VP56_FRAME_GOLDEN] &&

            s->framep[VP56_FRAME_UNUSED] != s->framep[VP56_FRAME_GOLDEN2])

            FFSWAP(AVFrame *, s->framep[VP56_FRAME_PREVIOUS],

                              s->framep[VP56_FRAME_UNUSED]);

        else

            FFSWAP(AVFrame *, s->framep[VP56_FRAME_PREVIOUS],

                              s->framep[VP56_FRAME_UNUSED2]);

    } else if (s->framep[VP56_FRAME_PREVIOUS]->data[0])

        avctx->release_buffer(avctx, s->framep[VP56_FRAME_PREVIOUS]);

    FFSWAP(AVFrame *, s->framep[VP56_FRAME_CURRENT],

                      s->framep[VP56_FRAME_PREVIOUS]);



    p->qstride = 0;

    p->qscale_table = s->qscale_table;

    p->qscale_type = FF_QSCALE_TYPE_VP56;

    *(AVFrame*)data = *p;

    *data_size = sizeof(AVFrame);



    return avpkt->size;

}

static int mov_read_esds(MOVContext *c, ByteIOContext *pb, MOVAtom atom)

{

    AVStream *st = c->fc->streams[c->fc->nb_streams-1];

    int tag, len;



    get_be32(pb); /* version + flags */

    len = mp4_read_descr(c, pb, &tag);

    if (tag == MP4ESDescrTag) {

        get_be16(pb); /* ID */

        get_byte(pb); /* priority */

    } else

        get_be16(pb); /* ID */



    len = mp4_read_descr(c, pb, &tag);

    if (tag == MP4DecConfigDescrTag) {

        int object_type_id = get_byte(pb);

        get_byte(pb); /* stream type */

        get_be24(pb); /* buffer size db */

        get_be32(pb); /* max bitrate */

        get_be32(pb); /* avg bitrate */



        st->codec->codec_id= ff_codec_get_id(ff_mp4_obj_type, object_type_id);

        dprintf(c->fc, "esds object type id %d\n", object_type_id);

        len = mp4_read_descr(c, pb, &tag);

        if (tag == MP4DecSpecificDescrTag) {

            dprintf(c->fc, "Specific MPEG4 header len=%d\n", len);

            if((uint64_t)len > (1<<30))

                return -1;

            st->codec->extradata = av_mallocz(len + FF_INPUT_BUFFER_PADDING_SIZE);

            if (!st->codec->extradata)

                return AVERROR(ENOMEM);

            get_buffer(pb, st->codec->extradata, len);

            st->codec->extradata_size = len;

            if (st->codec->codec_id == CODEC_ID_AAC) {

                MPEG4AudioConfig cfg;

                ff_mpeg4audio_get_config(&cfg, st->codec->extradata,

                                         st->codec->extradata_size);

                if (cfg.chan_config > 7)

                    return -1;

                st->codec->channels = ff_mpeg4audio_channels[cfg.chan_config];

                if (cfg.object_type == 29 && cfg.sampling_index < 3) // old mp3on4

                    st->codec->sample_rate = ff_mpa_freq_tab[cfg.sampling_index];

                else

                    st->codec->sample_rate = cfg.sample_rate; // ext sample rate ?

                dprintf(c->fc, "mp4a config channels %d obj %d ext obj %d "

                        "sample rate %d ext sample rate %d\n", st->codec->channels,

                        cfg.object_type, cfg.ext_object_type,

                        cfg.sample_rate, cfg.ext_sample_rate);

                if (!(st->codec->codec_id = ff_codec_get_id(mp4_audio_types,

                                                            cfg.object_type)))

                    st->codec->codec_id = CODEC_ID_AAC;

            }

        }

    }

    return 0;

}

av_cold int ff_nvenc_encode_close(AVCodecContext *avctx)

{

    NVENCContext *ctx               = avctx->priv_data;

    NV_ENCODE_API_FUNCTION_LIST *nv = &ctx->nvel.nvenc_funcs;

    int i;



    av_frame_free(&avctx->coded_frame);



    if (ctx->in) {

        for (i = 0; i < ctx->nb_surfaces; ++i) {

            nv->nvEncDestroyInputBuffer(ctx->nvenc_ctx, ctx->in[i].in);

            nv->nvEncDestroyBitstreamBuffer(ctx->nvenc_ctx, ctx->out[i].out);

        }

    }



    av_freep(&ctx->in);

    av_freep(&ctx->out);



    if (ctx->nvenc_ctx)

        nv->nvEncDestroyEncoder(ctx->nvenc_ctx);



    if (ctx->cu_context)

        ctx->nvel.cu_ctx_destroy(ctx->cu_context);



    if (ctx->nvel.nvenc)

        dlclose(ctx->nvel.nvenc);



    if (ctx->nvel.cuda)

        dlclose(ctx->nvel.cuda);



    return 0;

}

static QDM2SubPNode *qdm2_search_subpacket_type_in_list(QDM2SubPNode *list,

                                                        int type)

{

    while (list != NULL && list->packet != NULL) {

        if (list->packet->type == type)

            return list;

        list = list->next;

    }

    return NULL;

}

static int segment_end(AVFormatContext *s, int write_trailer, int is_last)

{

    SegmentContext *seg = s->priv_data;

    AVFormatContext *oc = seg->avf;

    int ret = 0;



    av_write_frame(oc, NULL); /* Flush any buffered data (fragmented mp4) */

    if (write_trailer)

        ret = av_write_trailer(oc);



    if (ret < 0)

        av_log(s, AV_LOG_ERROR, "Failure occurred when ending segment '%s'\n",

               oc->filename);



    if (seg->list) {

        if (seg->list_size || seg->list_type == LIST_TYPE_M3U8) {

            SegmentListEntry *entry = av_mallocz(sizeof(*entry));

            if (!entry) {

                ret = AVERROR(ENOMEM);

                goto end;

            }



            /* append new element */

            memcpy(entry, &seg->cur_entry, sizeof(*entry));

            if (!seg->segment_list_entries)

                seg->segment_list_entries = seg->segment_list_entries_end = entry;

            else

                seg->segment_list_entries_end->next = entry;

            seg->segment_list_entries_end = entry;



            /* drop first item */

            if (seg->list_size && seg->segment_count > seg->list_size) {

                entry = seg->segment_list_entries;

                seg->segment_list_entries = seg->segment_list_entries->next;

                av_free(entry->filename);

                av_freep(&entry);

            }



            avio_close(seg->list_pb);

            if ((ret = segment_list_open(s)) < 0)

                goto end;

            for (entry = seg->segment_list_entries; entry; entry = entry->next)

                segment_list_print_entry(seg->list_pb, seg->list_type, entry, s);

            if (seg->list_type == LIST_TYPE_M3U8 && is_last)

                avio_printf(seg->list_pb, "#EXT-X-ENDLIST\n");

        } else {

            segment_list_print_entry(seg->list_pb, seg->list_type, &seg->cur_entry, s);

        }

        avio_flush(seg->list_pb);

    }



    av_log(s, AV_LOG_VERBOSE, "segment:'%s' count:%d ended\n",

           seg->avf->filename, seg->segment_count);

    seg->segment_count++;



end:

    avio_close(oc->pb);



    return ret;

}

static void get_default_channel_layouts(OutputStream *ost, InputStream *ist)

{

    char layout_name[256];

    AVCodecContext *enc = ost->st->codec;

    AVCodecContext *dec = ist->st->codec;



    if (dec->channel_layout &&

        av_get_channel_layout_nb_channels(dec->channel_layout) != dec->channels) {

        av_get_channel_layout_string(layout_name, sizeof(layout_name),

                                     dec->channels, dec->channel_layout);

        av_log(NULL, AV_LOG_ERROR, "New channel layout (%s) is invalid\n",

               layout_name);

        dec->channel_layout = 0;

    }

    if (!dec->channel_layout) {

        if (enc->channel_layout && dec->channels == enc->channels) {

            dec->channel_layout = enc->channel_layout;

        } else {

            dec->channel_layout = av_get_default_channel_layout(dec->channels);



            if (!dec->channel_layout) {

                av_log(NULL, AV_LOG_FATAL, "Unable to find default channel "

                       "layout for Input Stream #%d.%d\n", ist->file_index,

                       ist->st->index);

                exit_program(1);

            }

        }

        av_get_channel_layout_string(layout_name, sizeof(layout_name),

                                     dec->channels, dec->channel_layout);

        av_log(NULL, AV_LOG_WARNING, "Guessed Channel Layout for  Input Stream "

               "#%d.%d : %s\n", ist->file_index, ist->st->index, layout_name);

    }

    if (!enc->channel_layout) {

        if (dec->channels == enc->channels) {

            enc->channel_layout = dec->channel_layout;

            return;

        } else {

            enc->channel_layout = av_get_default_channel_layout(enc->channels);

        }

        if (!enc->channel_layout) {

            av_log(NULL, AV_LOG_FATAL, "Unable to find default channel layout "

                   "for Output Stream #%d.%d\n", ost->file_index,

                   ost->st->index);

            exit_program(1);

        }

        av_get_channel_layout_string(layout_name, sizeof(layout_name),

                                     enc->channels, enc->channel_layout);

        av_log(NULL, AV_LOG_WARNING, "Guessed Channel Layout for Output Stream "

               "#%d.%d : %s\n", ost->file_index, ost->st->index, layout_name);

    }

}

static enum AVPixelFormat get_format(HEVCContext *s, const HEVCSPS *sps)

{

    #define HWACCEL_MAX (CONFIG_HEVC_DXVA2_HWACCEL + CONFIG_HEVC_D3D11VA_HWACCEL + CONFIG_HEVC_VAAPI_HWACCEL + CONFIG_HEVC_VDPAU_HWACCEL)

    enum AVPixelFormat pix_fmts[HWACCEL_MAX + 2], *fmt = pix_fmts;



    switch (sps->pix_fmt) {

    case AV_PIX_FMT_YUV420P:

    case AV_PIX_FMT_YUVJ420P:

#if CONFIG_HEVC_DXVA2_HWACCEL

        *fmt++ = AV_PIX_FMT_DXVA2_VLD;

#endif

#if CONFIG_HEVC_D3D11VA_HWACCEL

        *fmt++ = AV_PIX_FMT_D3D11VA_VLD;

#endif

#if CONFIG_HEVC_VAAPI_HWACCEL

        *fmt++ = AV_PIX_FMT_VAAPI;

#endif

#if CONFIG_HEVC_VDPAU_HWACCEL

        *fmt++ = AV_PIX_FMT_VDPAU;

#endif

        break;

    case AV_PIX_FMT_YUV420P10:

#if CONFIG_HEVC_DXVA2_HWACCEL

        *fmt++ = AV_PIX_FMT_DXVA2_VLD;

#endif

#if CONFIG_HEVC_D3D11VA_HWACCEL

        *fmt++ = AV_PIX_FMT_D3D11VA_VLD;

#endif

#if CONFIG_HEVC_VAAPI_HWACCEL

        *fmt++ = AV_PIX_FMT_VAAPI;

#endif

        break;

    }



    *fmt++ = sps->pix_fmt;

    *fmt = AV_PIX_FMT_NONE;



    return ff_get_format(s->avctx, pix_fmts);

}

