        init_vlc(&ac_ccp_vlc, VLC_BITS, 16, 

                 &ac_ccp_tab[0][1], 2, 1,

                 &ac_ccp_tab[0][0], 2, 1);

        init_vlc(&level_vlc,  VLC_BITS, 7, 

