static inline void decode_subblock3(DCTELEM *dst, int code, const int is_block2, GetBitContext *gb, VLC *vlc,

                                    int q_dc, int q_ac1, int q_ac2)

{

    int coeffs[4];



    coeffs[0] = modulo_three_table[code][0];

    coeffs[1] = modulo_three_table[code][1];

    coeffs[2] = modulo_three_table[code][2];

    coeffs[3] = modulo_three_table[code][3];

    decode_coeff(dst  , coeffs[0], 3, gb, vlc, q_dc);

    if(is_block2){

        decode_coeff(dst+8, coeffs[1], 2, gb, vlc, q_ac1);

        decode_coeff(dst+1, coeffs[2], 2, gb, vlc, q_ac1);

    }else{

        decode_coeff(dst+1, coeffs[1], 2, gb, vlc, q_ac1);

        decode_coeff(dst+8, coeffs[2], 2, gb, vlc, q_ac1);

    }

    decode_coeff(dst+9, coeffs[3], 2, gb, vlc, q_ac2);

}

static int mm_probe(AVProbeData *p)

{

    /* the first chunk is always the header */

    if (p->buf_size < MM_PREAMBLE_SIZE)

        return 0;

    if (AV_RL16(&p->buf[0]) != MM_TYPE_HEADER)

        return 0;

    if (AV_RL32(&p->buf[2]) != MM_HEADER_LEN_V && AV_RL32(&p->buf[2]) != MM_HEADER_LEN_AV)

        return 0;



    /* only return half certainty since this check is a bit sketchy */

    return AVPROBE_SCORE_MAX / 2;

}

static int tcp_write_packet(AVFormatContext *s, RTSPStream *rtsp_st)

{

    RTSPState *rt = s->priv_data;

    AVFormatContext *rtpctx = rtsp_st->transport_priv;

    uint8_t *buf, *ptr;

    int size;

    uint8_t *interleave_header, *interleaved_packet;



    size = avio_close_dyn_buf(rtpctx->pb, &buf);

    ptr = buf;

    while (size > 4) {

        uint32_t packet_len = AV_RB32(ptr);

        int id;

        /* The interleaving header is exactly 4 bytes, which happens to be

         * the same size as the packet length header from

         * url_open_dyn_packet_buf. So by writing the interleaving header

         * over these bytes, we get a consecutive interleaved packet

         * that can be written in one call. */

        interleaved_packet = interleave_header = ptr;

        ptr += 4;

        size -= 4;

        if (packet_len > size || packet_len < 2)

            break;

        if (ptr[1] >= RTCP_SR && ptr[1] <= RTCP_APP)

            id = rtsp_st->interleaved_max; /* RTCP */

        else

            id = rtsp_st->interleaved_min; /* RTP */

        interleave_header[0] = '$';

        interleave_header[1] = id;

        AV_WB16(interleave_header + 2, packet_len);

        url_write(rt->rtsp_hd_out, interleaved_packet, 4 + packet_len);

        ptr += packet_len;

        size -= packet_len;

    }

    av_free(buf);

    url_open_dyn_packet_buf(&rtpctx->pb, RTSP_TCP_MAX_PACKET_SIZE);

    return 0;

}

static int find_and_decode_index(NUTContext *nut){

    AVFormatContext *s= nut->avf;

    ByteIOContext *bc = s->pb;

    uint64_t tmp, end;

    int i, j, syncpoint_count;

    int64_t filesize= url_fsize(bc);

    int64_t *syncpoints;

    int8_t *has_keyframe;



    url_fseek(bc, filesize-12, SEEK_SET);

    url_fseek(bc, filesize-get_be64(bc), SEEK_SET);

    if(get_be64(bc) != INDEX_STARTCODE){

        av_log(s, AV_LOG_ERROR, "no index at the end\n");

        return -1;

    }



    end= get_packetheader(nut, bc, 1, INDEX_STARTCODE);

    end += url_ftell(bc);



    ff_get_v(bc); //max_pts

    GET_V(syncpoint_count, tmp < INT_MAX/8 && tmp > 0)

    syncpoints= av_malloc(sizeof(int64_t)*syncpoint_count);

    has_keyframe= av_malloc(sizeof(int8_t)*(syncpoint_count+1));

    for(i=0; i<syncpoint_count; i++){

        GET_V(syncpoints[i], tmp>0)

        if(i)

            syncpoints[i] += syncpoints[i-1];

    }



    for(i=0; i<s->nb_streams; i++){

        int64_t last_pts= -1;

        for(j=0; j<syncpoint_count;){

            uint64_t x= ff_get_v(bc);

            int type= x&1;

            int n= j;

            x>>=1;

            if(type){

                int flag= x&1;

                x>>=1;

                if(n+x >= syncpoint_count + 1){

                    av_log(s, AV_LOG_ERROR, "index overflow A\n");

                    return -1;

                }

                while(x--)

                    has_keyframe[n++]= flag;

                has_keyframe[n++]= !flag;

            }else{

                while(x != 1){

                    if(n>=syncpoint_count + 1){

                        av_log(s, AV_LOG_ERROR, "index overflow B\n");

                        return -1;

                    }

                    has_keyframe[n++]= x&1;

                    x>>=1;

                }

            }

            if(has_keyframe[0]){

                av_log(s, AV_LOG_ERROR, "keyframe before first syncpoint in index\n");

                return -1;

            }

            assert(n<=syncpoint_count+1);

            for(; j<n; j++){

                if(has_keyframe[j]){

                    uint64_t B, A= ff_get_v(bc);

                    if(!A){

                        A= ff_get_v(bc);

                        B= ff_get_v(bc);

                        //eor_pts[j][i] = last_pts + A + B

                    }else

                        B= 0;

                    av_add_index_entry(

                        s->streams[i],

                        16*syncpoints[j-1],

                        last_pts + A,

                        0,

                        0,

                        AVINDEX_KEYFRAME);

                    last_pts += A + B;

                }

            }

        }

    }



    if(skip_reserved(bc, end) || get_checksum(bc)){

        av_log(s, AV_LOG_ERROR, "index checksum mismatch\n");

        return -1;

    }

    return 0;

}

static int get_packet_size(const uint8_t *buf, int size)

{

    int score, fec_score, dvhs_score;



    if (size < (TS_FEC_PACKET_SIZE * 5 + 1))

        return AVERROR_INVALIDDATA;



    score      = analyze(buf, size, TS_PACKET_SIZE, NULL);

    dvhs_score = analyze(buf, size, TS_DVHS_PACKET_SIZE, NULL);

    fec_score  = analyze(buf, size, TS_FEC_PACKET_SIZE, NULL);

    av_dlog(NULL, "score: %d, dvhs_score: %d, fec_score: %d \n",

            score, dvhs_score, fec_score);



    if (score > fec_score && score > dvhs_score)

        return TS_PACKET_SIZE;

    else if (dvhs_score > score && dvhs_score > fec_score)

        return TS_DVHS_PACKET_SIZE;

    else if (score < fec_score && dvhs_score < fec_score)

        return TS_FEC_PACKET_SIZE;

    else

        return AVERROR_INVALIDDATA;

}

static void matroska_execute_seekhead(MatroskaDemuxContext *matroska)

{

    EbmlList *seekhead_list = &matroska->seekhead;

    MatroskaSeekhead *seekhead = seekhead_list->elem;

    int64_t before_pos = avio_tell(matroska->ctx->pb);

    int i;



    // we should not do any seeking in the streaming case

    if (!matroska->ctx->pb->seekable ||

        (matroska->ctx->flags & AVFMT_FLAG_IGNIDX))

        return;



    for (i = 0; i < seekhead_list->nb_elem; i++) {

        if (seekhead[i].pos <= before_pos)

            continue;



        // defer cues parsing until we actually need cue data.

        if (seekhead[i].id == MATROSKA_ID_CUES) {

            matroska->cues_parsing_deferred = 1;

            continue;

        }



        if (matroska_parse_seekhead_entry(matroska, i) < 0)

            break;

    }

}

static void load_cursor(VmncContext *c, const uint8_t *src)

{

    int i, j, p;

    const int bpp   = c->bpp2;

    uint8_t *dst8   =             c->curbits;

    uint16_t *dst16 = (uint16_t *)c->curbits;

    uint32_t *dst32 = (uint32_t *)c->curbits;



    for (j = 0; j < c->cur_h; j++) {

        for (i = 0; i < c->cur_w; i++) {

            p = vmnc_get_pixel(src, bpp, c->bigendian);

            src += bpp;

            if (bpp == 1)

                *dst8++ = p;

            if (bpp == 2)

                *dst16++ = p;

            if (bpp == 4)

                *dst32++ = p;

        }

    }

    dst8  =            c->curmask;

    dst16 = (uint16_t*)c->curmask;

    dst32 = (uint32_t*)c->curmask;

    for (j = 0; j < c->cur_h; j++) {

        for (i = 0; i < c->cur_w; i++) {

            p = vmnc_get_pixel(src, bpp, c->bigendian);

            src += bpp;

            if (bpp == 1)

                *dst8++ = p;

            if (bpp == 2)

                *dst16++ = p;

            if (bpp == 4)

                *dst32++ = p;

        }

    }

}

