AVChapter *ff_new_chapter(AVFormatContext *s, int id, AVRational time_base, int64_t start, int64_t end, const char *title)

{

    AVChapter *chapter = NULL;

    int i;



    for(i=0; i<s->nb_chapters; i++)

        if(s->chapters[i]->id == id)

            chapter = s->chapters[i];



    if(!chapter){

        chapter= av_mallocz(sizeof(AVChapter));

        if(!chapter)

            return NULL;

        dynarray_add(&s->chapters, &s->nb_chapters, chapter);

    }

    if(chapter->title)

        av_free(chapter->title);

    chapter->title = av_strdup(title);

    chapter->id    = id;

    chapter->time_base= time_base;

    chapter->start = start;

    chapter->end   = end;



    return chapter;

}

int ff_hevc_split_packet(HEVCContext *s, HEVCPacket *pkt, const uint8_t *buf, int length,

                         AVCodecContext *avctx, int is_nalff, int nal_length_size)

{

    int consumed, ret = 0;



    pkt->nb_nals = 0;

    while (length >= 4) {

        HEVCNAL *nal;

        int extract_length = 0;



        if (is_nalff) {

            int i;

            for (i = 0; i < nal_length_size; i++)

                extract_length = (extract_length << 8) | buf[i];

            buf    += nal_length_size;

            length -= nal_length_size;



            if (extract_length > length) {

                av_log(avctx, AV_LOG_ERROR, "Invalid NAL unit size.\n");

                return AVERROR_INVALIDDATA;

            }

        } else {

            /* search start code */

            while (buf[0] != 0 || buf[1] != 0 || buf[2] != 1) {

                ++buf;

                --length;

                if (length < 4) {

                    if (pkt->nb_nals > 0) {

                        // No more start codes: we discarded some irrelevant

                        // bytes at the end of the packet.

                        return 0;

                    } else {

                        av_log(avctx, AV_LOG_ERROR, "No start code is found.\n");

                        return AVERROR_INVALIDDATA;

                    }

                }

            }



            buf           += 3;

            length        -= 3;

            extract_length = length;

        }



        if (pkt->nals_allocated < pkt->nb_nals + 1) {

            int new_size = pkt->nals_allocated + 1;

            void *tmp = av_realloc_array(pkt->nals, new_size, sizeof(*pkt->nals));



            if (!tmp)

                return AVERROR(ENOMEM);



            pkt->nals = tmp;

            memset(pkt->nals + pkt->nals_allocated, 0,

                   (new_size - pkt->nals_allocated) * sizeof(*pkt->nals));



            nal = &pkt->nals[pkt->nb_nals];

            nal->skipped_bytes_pos_size = 1024; // initial buffer size

            nal->skipped_bytes_pos = av_malloc_array(nal->skipped_bytes_pos_size, sizeof(*nal->skipped_bytes_pos));

            if (!nal->skipped_bytes_pos)

                return AVERROR(ENOMEM);



            pkt->nals_allocated = new_size;

        }

        nal = &pkt->nals[pkt->nb_nals];



        consumed = ff_hevc_extract_rbsp(s, buf, extract_length, nal);

        if (consumed < 0)

            return consumed;



        pkt->nb_nals++;



        ret = init_get_bits8(&nal->gb, nal->data, nal->size);

        if (ret < 0)

            return ret;



        ret = hls_nal_unit(nal, avctx);

        if (ret <= 0) {

            if (ret < 0) {

                av_log(avctx, AV_LOG_ERROR, "Invalid NAL unit %d, skipping.\n",

                       nal->type);

            }

            pkt->nb_nals--;

        }



        buf    += consumed;

        length -= consumed;

    }



    return 0;

}

static int mxf_decrypt_triplet(AVFormatContext *s, AVPacket *pkt, KLVPacket *klv)

{

    static const uint8_t checkv[16] = {0x43, 0x48, 0x55, 0x4b, 0x43, 0x48, 0x55, 0x4b, 0x43, 0x48, 0x55, 0x4b, 0x43, 0x48, 0x55, 0x4b};

    MXFContext *mxf = s->priv_data;

    AVIOContext *pb = s->pb;

    int64_t end = avio_tell(pb) + klv->length;

    uint64_t size;

    uint64_t orig_size;

    uint64_t plaintext_size;

    uint8_t ivec[16];

    uint8_t tmpbuf[16];

    int index;



    if (!mxf->aesc && s->key && s->keylen == 16) {

        mxf->aesc = av_malloc(av_aes_size);

        if (!mxf->aesc)

            return -1;

        av_aes_init(mxf->aesc, s->key, 128, 1);

    }

    // crypto context

    avio_skip(pb, klv_decode_ber_length(pb));

    // plaintext offset

    klv_decode_ber_length(pb);

    plaintext_size = avio_rb64(pb);

    // source klv key

    klv_decode_ber_length(pb);

    avio_read(pb, klv->key, 16);

    if (!IS_KLV_KEY(klv, mxf_essence_element_key))

        return -1;

    index = mxf_get_stream_index(s, klv);

    if (index < 0)

        return -1;

    // source size

    klv_decode_ber_length(pb);

    orig_size = avio_rb64(pb);

    if (orig_size < plaintext_size)

        return -1;

    // enc. code

    size = klv_decode_ber_length(pb);

    if (size < 32 || size - 32 < orig_size)

        return -1;

    avio_read(pb, ivec, 16);

    avio_read(pb, tmpbuf, 16);

    if (mxf->aesc)

        av_aes_crypt(mxf->aesc, tmpbuf, tmpbuf, 1, ivec, 1);

    if (memcmp(tmpbuf, checkv, 16))

        av_log(s, AV_LOG_ERROR, "probably incorrect decryption key\n");

    size -= 32;

    av_get_packet(pb, pkt, size);

    size -= plaintext_size;

    if (mxf->aesc)

        av_aes_crypt(mxf->aesc, &pkt->data[plaintext_size],

                     &pkt->data[plaintext_size], size >> 4, ivec, 1);

    pkt->size = orig_size;

    pkt->stream_index = index;

    avio_skip(pb, end - avio_tell(pb));

    return 0;

}

