static int msrle_decode_pal4(AVCodecContext *avctx, AVPicture *pic,

                              const uint8_t *data, int data_size)

{

    int stream_ptr = 0;

    unsigned char rle_code;

    unsigned char extra_byte, odd_pixel;

    unsigned char stream_byte;

    int pixel_ptr = 0;

    int row_dec = pic->linesize[0];

    int row_ptr = (avctx->height - 1) * row_dec;

    int frame_size = row_dec * avctx->height;

    int i;



    while (row_ptr >= 0) {

        FETCH_NEXT_STREAM_BYTE();

        rle_code = stream_byte;

        if (rle_code == 0) {

            /* fetch the next byte to see how to handle escape code */

            FETCH_NEXT_STREAM_BYTE();

            if (stream_byte == 0) {

                /* line is done, goto the next one */

                row_ptr -= row_dec;

                pixel_ptr = 0;

            } else if (stream_byte == 1) {

                /* decode is done */

                return 0;

            } else if (stream_byte == 2) {

                /* reposition frame decode coordinates */

                FETCH_NEXT_STREAM_BYTE();

                pixel_ptr += stream_byte;

                FETCH_NEXT_STREAM_BYTE();

                row_ptr -= stream_byte * row_dec;

            } else {

                // copy pixels from encoded stream

                odd_pixel =  stream_byte & 1;

                rle_code = (stream_byte + 1) / 2;

                extra_byte = rle_code & 0x01;

                if (row_ptr + pixel_ptr + stream_byte > frame_size) {

                    av_log(avctx, AV_LOG_ERROR, " MS RLE: frame ptr just went out of bounds (1)\n");

                    return -1;

                }



                for (i = 0; i < rle_code; i++) {

                    if (pixel_ptr >= avctx->width)

                        break;

                    FETCH_NEXT_STREAM_BYTE();

                    pic->data[0][row_ptr + pixel_ptr] = stream_byte >> 4;

                    pixel_ptr++;

                    if (i + 1 == rle_code && odd_pixel)

                        break;

                    if (pixel_ptr >= avctx->width)

                        break;

                    pic->data[0][row_ptr + pixel_ptr] = stream_byte & 0x0F;

                    pixel_ptr++;

                }



                // if the RLE code is odd, skip a byte in the stream

                if (extra_byte)

                    stream_ptr++;

            }

        } else {

            // decode a run of data

            if (row_ptr + pixel_ptr + stream_byte > frame_size) {

                av_log(avctx, AV_LOG_ERROR, " MS RLE: frame ptr just went out of bounds (1)\n");

                return -1;

            }

            FETCH_NEXT_STREAM_BYTE();

            for (i = 0; i < rle_code; i++) {

                if (pixel_ptr >= avctx->width)

                    break;

                if ((i & 1) == 0)

                    pic->data[0][row_ptr + pixel_ptr] = stream_byte >> 4;

                else

                    pic->data[0][row_ptr + pixel_ptr] = stream_byte & 0x0F;

                pixel_ptr++;

            }

        }

    }



    /* one last sanity check on the way out */

    if (stream_ptr < data_size) {

        av_log(avctx, AV_LOG_ERROR, " MS RLE: ended frame decode with bytes left over (%d < %d)\n",

            stream_ptr, data_size);

        return -1;

    }



    return 0;

}

static void vc1_mc_4mv_chroma4(VC1Context *v)

{

    MpegEncContext *s = &v->s;

    DSPContext *dsp = &v->s.dsp;

    uint8_t *srcU, *srcV;

    int uvsrc_x, uvsrc_y;

    int uvmx_field[4], uvmy_field[4];

    int i, off, tx, ty;

    int fieldmv = v->blk_mv_type[s->block_index[0]];

    static const int s_rndtblfield[16] = { 0, 0, 1, 2, 4, 4, 5, 6, 2, 2, 3, 8, 6, 6, 7, 12 };

    int v_dist = fieldmv ? 1 : 4; // vertical offset for lower sub-blocks

    int v_edge_pos = s->v_edge_pos >> 1;



    if (!v->s.last_picture.f.data[0])

        return;

    if (s->flags & CODEC_FLAG_GRAY)

        return;



    for (i = 0; i < 4; i++) {

        tx = s->mv[0][i][0];

        uvmx_field[i] = (tx + ((tx & 3) == 3)) >> 1;

        ty = s->mv[0][i][1];

        if (fieldmv)

            uvmy_field[i] = (ty >> 4) * 8 + s_rndtblfield[ty & 0xF];

        else

            uvmy_field[i] = (ty + ((ty & 3) == 3)) >> 1;

    }



    for (i = 0; i < 4; i++) {

        off = (i & 1) * 4 + ((i & 2) ? v_dist * s->uvlinesize : 0);

        uvsrc_x = s->mb_x * 8 +  (i & 1) * 4           + (uvmx_field[i] >> 2);

        uvsrc_y = s->mb_y * 8 + ((i & 2) ? v_dist : 0) + (uvmy_field[i] >> 2);

        // FIXME: implement proper pull-back (see vc1cropmv.c, vc1CROPMV_ChromaPullBack())

        uvsrc_x = av_clip(uvsrc_x, -8, s->avctx->coded_width  >> 1);

        uvsrc_y = av_clip(uvsrc_y, -8, s->avctx->coded_height >> 1);

        srcU = s->last_picture.f.data[1] + uvsrc_y * s->uvlinesize + uvsrc_x;

        srcV = s->last_picture.f.data[2] + uvsrc_y * s->uvlinesize + uvsrc_x;

        uvmx_field[i] = (uvmx_field[i] & 3) << 1;

        uvmy_field[i] = (uvmy_field[i] & 3) << 1;



        if (fieldmv && !(uvsrc_y & 1))

            v_edge_pos--;

        if (fieldmv && (uvsrc_y & 1) && uvsrc_y < 2)

            uvsrc_y--;

        if ((v->mv_mode == MV_PMODE_INTENSITY_COMP)

            || s->h_edge_pos < 10 || v_edge_pos < (5 << fieldmv)

            || (unsigned)uvsrc_x > (s->h_edge_pos >> 1) - 5

            || (unsigned)uvsrc_y > v_edge_pos - (5 << fieldmv)) {

            s->dsp.emulated_edge_mc(s->edge_emu_buffer, srcU, s->uvlinesize,

                                    5, (5 << fieldmv), uvsrc_x, uvsrc_y,

                                    s->h_edge_pos >> 1, v_edge_pos);

            s->dsp.emulated_edge_mc(s->edge_emu_buffer + 16, srcV, s->uvlinesize,

                                    5, (5 << fieldmv), uvsrc_x, uvsrc_y,

                                    s->h_edge_pos >> 1, v_edge_pos);

            srcU = s->edge_emu_buffer;

            srcV = s->edge_emu_buffer + 16;



            /* if we deal with intensity compensation we need to scale source blocks */

            if (v->mv_mode == MV_PMODE_INTENSITY_COMP) {

                int i, j;

                uint8_t *src, *src2;



                src  = srcU;

                src2 = srcV;

                for (j = 0; j < 5; j++) {

                    for (i = 0; i < 5; i++) {

                        src[i]  = v->lutuv[src[i]];

                        src2[i] = v->lutuv[src2[i]];

                    }

                    src  += s->uvlinesize << 1;

                    src2 += s->uvlinesize << 1;

                }

            }

        }

        if (!v->rnd) {

            dsp->put_h264_chroma_pixels_tab[1](s->dest[1] + off, srcU, s->uvlinesize << fieldmv, 4, uvmx_field[i], uvmy_field[i]);

            dsp->put_h264_chroma_pixels_tab[1](s->dest[2] + off, srcV, s->uvlinesize << fieldmv, 4, uvmx_field[i], uvmy_field[i]);

        } else {

            v->vc1dsp.put_no_rnd_vc1_chroma_pixels_tab[1](s->dest[1] + off, srcU, s->uvlinesize << fieldmv, 4, uvmx_field[i], uvmy_field[i]);

            v->vc1dsp.put_no_rnd_vc1_chroma_pixels_tab[1](s->dest[2] + off, srcV, s->uvlinesize << fieldmv, 4, uvmx_field[i], uvmy_field[i]);

        }

    }

}

static int mjpegb_decode_frame(AVCodecContext *avctx, 

                              void *data, int *data_size,

                              UINT8 *buf, int buf_size)

{

    MJpegDecodeContext *s = avctx->priv_data;

    UINT8 *buf_end, *buf_ptr;

    int i;

    AVPicture *picture = data;

    GetBitContext hgb; /* for the header */

    uint32_t dqt_offs, dht_offs, sof_offs, sos_offs, second_field_offs;

    uint32_t field_size;



    *data_size = 0;



    /* no supplementary picture */

    if (buf_size == 0)

        return 0;



    buf_ptr = buf;

    buf_end = buf + buf_size;



read_header:

    /* reset on every SOI */

    s->restart_interval = 0;



    init_get_bits(&hgb, buf_ptr, /*buf_size*/buf_end - buf_ptr);



    skip_bits(&hgb, 32); /* reserved zeros */



    if (get_bits(&hgb, 32) != be2me_32(ff_get_fourcc("mjpg")))

    {

	dprintf("not mjpeg-b (bad fourcc)\n");

	return 0;

    }



    field_size = get_bits(&hgb, 32); /* field size */

    dprintf("field size: 0x%x\n", field_size);

    skip_bits(&hgb, 32); /* padded field size */

    second_field_offs = get_bits(&hgb, 32);

    dprintf("second field offs: 0x%x\n", second_field_offs);

    if (second_field_offs)

	s->interlaced = 1;



    dqt_offs = get_bits(&hgb, 32);

    dprintf("dqt offs: 0x%x\n", dqt_offs);

    if (dqt_offs)

    {

	init_get_bits(&s->gb, buf+dqt_offs, buf_end - (buf+dqt_offs));

	s->start_code = DQT;

	mjpeg_decode_dqt(s);

    }



    dht_offs = get_bits(&hgb, 32);

    dprintf("dht offs: 0x%x\n", dht_offs);

    if (dht_offs)

    {

	init_get_bits(&s->gb, buf+dht_offs, buf_end - (buf+dht_offs));

	s->start_code = DHT;

	mjpeg_decode_dht(s);

    }



    sof_offs = get_bits(&hgb, 32);

    dprintf("sof offs: 0x%x\n", sof_offs);

    if (sof_offs)

    {

	init_get_bits(&s->gb, buf+sof_offs, buf_end - (buf+sof_offs));

	s->start_code = SOF0;

	if (mjpeg_decode_sof0(s) < 0)

	    return -1;

    }



    sos_offs = get_bits(&hgb, 32);

    dprintf("sos offs: 0x%x\n", sos_offs);

    if (sos_offs)

    {

//	init_get_bits(&s->gb, buf+sos_offs, buf_end - (buf+sos_offs));

	init_get_bits(&s->gb, buf+sos_offs, field_size);

	s->start_code = SOS;

	mjpeg_decode_sos(s);

    }



    skip_bits(&hgb, 32); /* start of data offset */



    if (s->interlaced) {

        s->bottom_field ^= 1;

        /* if not bottom field, do not output image yet */

        if (s->bottom_field && second_field_offs)

	{

	    buf_ptr = buf + second_field_offs;

	    second_field_offs = 0;

	    goto read_header;

    	}

    }



    for(i=0;i<3;i++) {

        picture->data[i] = s->current_picture[i];

        picture->linesize[i] = (s->interlaced) ?

    	    s->linesize[i] >> 1 : s->linesize[i];

    }

    *data_size = sizeof(AVPicture);

    avctx->height = s->height;

    if (s->interlaced)

        avctx->height *= 2;

    avctx->width = s->width;

    /* XXX: not complete test ! */

    switch((s->h_count[0] << 4) | s->v_count[0]) {

        case 0x11:

    	    avctx->pix_fmt = PIX_FMT_YUV444P;

            break;

        case 0x21:

            avctx->pix_fmt = PIX_FMT_YUV422P;

            break;

        default:

	case 0x22:

            avctx->pix_fmt = PIX_FMT_YUV420P;

            break;

    }

    /* dummy quality */

    /* XXX: infer it with matrix */

//    avctx->quality = 3; 



    return buf_ptr - buf;

}

static int idcin_read_seek(AVFormatContext *s, int stream_index,

                           int64_t timestamp, int flags)

{

    IdcinDemuxContext *idcin = s->priv_data;



    if (idcin->first_pkt_pos > 0) {

        int ret = avio_seek(s->pb, idcin->first_pkt_pos, SEEK_SET);

        if (ret < 0)

            return ret;

        ff_update_cur_dts(s, s->streams[idcin->video_stream_index], 0);

        idcin->next_chunk_is_video = 1;

        idcin->current_audio_chunk = 0;

        return 0;

    }

    return -1;

}

static int output_frame(H264Context *h, AVFrame *dst, H264Picture *srcp)
{
    AVFrame *src = srcp->f;
    const AVPixFmtDescriptor *desc = av_pix_fmt_desc_get(src->format);
    int i;
    int ret = av_frame_ref(dst, src);
    if (ret < 0)
        return ret;
    av_dict_set(&dst->metadata, "stereo_mode", ff_h264_sei_stereo_mode(h), 0);
    if (srcp->sei_recovery_frame_cnt == 0)
        dst->key_frame = 1;
    if (!srcp->crop)
        return 0;
    for (i = 0; i < desc->nb_components; i++) {
        int hshift = (i > 0) ? desc->log2_chroma_w : 0;
        int vshift = (i > 0) ? desc->log2_chroma_h : 0;
        int off    = ((srcp->crop_left >> hshift) << h->pixel_shift) +
                      (srcp->crop_top  >> vshift) * dst->linesize[i];
        dst->data[i] += off;
    }
    return 0;
}

int ff_mjpeg_decode_frame(AVCodecContext *avctx, void *data, int *got_frame,

                          AVPacket *avpkt)

{

    AVFrame     *frame = data;

    const uint8_t *buf = avpkt->data;

    int buf_size       = avpkt->size;

    MJpegDecodeContext *s = avctx->priv_data;

    const uint8_t *buf_end, *buf_ptr;

    const uint8_t *unescaped_buf_ptr;

    int hshift, vshift;

    int unescaped_buf_size;

    int start_code;

    int i, index;

    int ret = 0;

    int is16bit;



    av_dict_free(&s->exif_metadata);

    av_freep(&s->stereo3d);

    s->adobe_transform = -1;



    buf_ptr = buf;

    buf_end = buf + buf_size;

    while (buf_ptr < buf_end) {

        /* find start next marker */

        start_code = ff_mjpeg_find_marker(s, &buf_ptr, buf_end,

                                          &unescaped_buf_ptr,

                                          &unescaped_buf_size);

        /* EOF */

        if (start_code < 0) {

            break;

        } else if (unescaped_buf_size > INT_MAX / 8) {

            av_log(avctx, AV_LOG_ERROR,

                   "MJPEG packet 0x%x too big (%d/%d), corrupt data?\n",

                   start_code, unescaped_buf_size, buf_size);

            return AVERROR_INVALIDDATA;

        }

        av_log(avctx, AV_LOG_DEBUG, "marker=%x avail_size_in_buf=%"PTRDIFF_SPECIFIER"\n",

               start_code, buf_end - buf_ptr);



        ret = init_get_bits8(&s->gb, unescaped_buf_ptr, unescaped_buf_size);



        if (ret < 0) {

            av_log(avctx, AV_LOG_ERROR, "invalid buffer\n");

            goto fail;

        }



        s->start_code = start_code;

        if (s->avctx->debug & FF_DEBUG_STARTCODE)

            av_log(avctx, AV_LOG_DEBUG, "startcode: %X\n", start_code);



        /* process markers */

        if (start_code >= 0xd0 && start_code <= 0xd7)

            av_log(avctx, AV_LOG_DEBUG,

                   "restart marker: %d\n", start_code & 0x0f);

            /* APP fields */

        else if (start_code >= APP0 && start_code <= APP15)

            mjpeg_decode_app(s);

            /* Comment */

        else if (start_code == COM)

            mjpeg_decode_com(s);



        ret = -1;



        if (!CONFIG_JPEGLS_DECODER &&

            (start_code == SOF48 || start_code == LSE)) {

            av_log(avctx, AV_LOG_ERROR, "JPEG-LS support not enabled.\n");

            return AVERROR(ENOSYS);

        }



        if (avctx->skip_frame == AVDISCARD_ALL) {

            switch(start_code) {

            case SOF0:

            case SOF1:

            case SOF2:

            case SOF3:

            case SOF48:

            case SOI:

            case SOS:

            case EOI:

                break;

            default:

                goto skip;

            }

        }



        switch (start_code) {

        case SOI:

            s->restart_interval = 0;

            s->restart_count    = 0;

            /* nothing to do on SOI */

            break;

        case DQT:

            ff_mjpeg_decode_dqt(s);

            break;

        case DHT:

            if ((ret = ff_mjpeg_decode_dht(s)) < 0) {

                av_log(avctx, AV_LOG_ERROR, "huffman table decode error\n");

                goto fail;

            }

            break;

        case SOF0:

        case SOF1:

            s->lossless    = 0;

            s->ls          = 0;

            s->progressive = 0;

            if ((ret = ff_mjpeg_decode_sof(s)) < 0)

                goto fail;

            break;

        case SOF2:

            s->lossless    = 0;

            s->ls          = 0;

            s->progressive = 1;

            if ((ret = ff_mjpeg_decode_sof(s)) < 0)

                goto fail;

            break;

        case SOF3:

            s->avctx->properties |= FF_CODEC_PROPERTY_LOSSLESS;

            s->lossless    = 1;

            s->ls          = 0;

            s->progressive = 0;

            if ((ret = ff_mjpeg_decode_sof(s)) < 0)

                goto fail;

            break;

        case SOF48:

            s->avctx->properties |= FF_CODEC_PROPERTY_LOSSLESS;

            s->lossless    = 1;

            s->ls          = 1;

            s->progressive = 0;

            if ((ret = ff_mjpeg_decode_sof(s)) < 0)

                goto fail;

            break;

        case LSE:

            if (!CONFIG_JPEGLS_DECODER ||

                (ret = ff_jpegls_decode_lse(s)) < 0)

                goto fail;

            break;

        case EOI:

eoi_parser:

            s->cur_scan = 0;

            if (!s->got_picture) {

                av_log(avctx, AV_LOG_WARNING,

                       "Found EOI before any SOF, ignoring\n");

                break;

            }

            if (s->interlaced) {

                s->bottom_field ^= 1;

                /* if not bottom field, do not output image yet */

                if (s->bottom_field == !s->interlace_polarity)

                    break;

            }

            if (avctx->skip_frame == AVDISCARD_ALL) {

                s->got_picture = 0;

                goto the_end_no_picture;

            }

            if ((ret = av_frame_ref(frame, s->picture_ptr)) < 0)

                return ret;

            *got_frame = 1;

            s->got_picture = 0;



            if (!s->lossless) {

                int qp = FFMAX3(s->qscale[0],

                                s->qscale[1],

                                s->qscale[2]);

                int qpw = (s->width + 15) / 16;

                AVBufferRef *qp_table_buf = av_buffer_alloc(qpw);

                if (qp_table_buf) {

                    memset(qp_table_buf->data, qp, qpw);

                    av_frame_set_qp_table(data, qp_table_buf, 0, FF_QSCALE_TYPE_MPEG1);

                }



                if(avctx->debug & FF_DEBUG_QP)

                    av_log(avctx, AV_LOG_DEBUG, "QP: %d\n", qp);

            }



            goto the_end;

        case SOS:

            s->cur_scan++;

            if (avctx->skip_frame == AVDISCARD_ALL)

                break;



            if ((ret = ff_mjpeg_decode_sos(s, NULL, 0, NULL)) < 0 &&

                (avctx->err_recognition & AV_EF_EXPLODE))

                goto fail;

            break;

        case DRI:

            mjpeg_decode_dri(s);

            break;

        case SOF5:

        case SOF6:

        case SOF7:

        case SOF9:

        case SOF10:

        case SOF11:

        case SOF13:

        case SOF14:

        case SOF15:

        case JPG:

            av_log(avctx, AV_LOG_ERROR,

                   "mjpeg: unsupported coding type (%x)\n", start_code);

            break;

        }



skip:

        /* eof process start code */

        buf_ptr += (get_bits_count(&s->gb) + 7) / 8;

        av_log(avctx, AV_LOG_DEBUG,

               "marker parser used %d bytes (%d bits)\n",

               (get_bits_count(&s->gb) + 7) / 8, get_bits_count(&s->gb));

    }

    if (s->got_picture && s->cur_scan) {

        av_log(avctx, AV_LOG_WARNING, "EOI missing, emulating\n");

        goto eoi_parser;

    }

    av_log(avctx, AV_LOG_FATAL, "No JPEG data found in image\n");

    return AVERROR_INVALIDDATA;

fail:

    s->got_picture = 0;

    return ret;

the_end:



    is16bit = av_pix_fmt_desc_get(s->avctx->pix_fmt)->comp[0].step > 1;



    if (AV_RB32(s->upscale_h)) {

        int p;

        av_assert0(avctx->pix_fmt == AV_PIX_FMT_YUVJ444P ||

                   avctx->pix_fmt == AV_PIX_FMT_YUV444P  ||

                   avctx->pix_fmt == AV_PIX_FMT_YUVJ440P ||

                   avctx->pix_fmt == AV_PIX_FMT_YUV440P  ||

                   avctx->pix_fmt == AV_PIX_FMT_YUVA444P ||

                   avctx->pix_fmt == AV_PIX_FMT_YUVJ420P ||

                   avctx->pix_fmt == AV_PIX_FMT_YUV420P  ||

                   avctx->pix_fmt == AV_PIX_FMT_YUV420P16||

                   avctx->pix_fmt == AV_PIX_FMT_YUVA420P  ||

                   avctx->pix_fmt == AV_PIX_FMT_YUVA420P16||

                   avctx->pix_fmt == AV_PIX_FMT_GBRP     ||

                   avctx->pix_fmt == AV_PIX_FMT_GBRAP

                  );

        avcodec_get_chroma_sub_sample(s->avctx->pix_fmt, &hshift, &vshift);

        for (p = 0; p<4; p++) {

            uint8_t *line = s->picture_ptr->data[p];

            int w = s->width;

            int h = s->height;

            if (!s->upscale_h[p])

                continue;

            if (p==1 || p==2) {

                w = AV_CEIL_RSHIFT(w, hshift);

                h = AV_CEIL_RSHIFT(h, vshift);

            }

            if (s->upscale_v[p])

                h = (h+1)>>1;

            av_assert0(w > 0);

            for (i = 0; i < h; i++) {

                if (s->upscale_h[p] == 1) {

                    if (is16bit) ((uint16_t*)line)[w - 1] = ((uint16_t*)line)[(w - 1) / 2];

                    else                      line[w - 1] = line[(w - 1) / 2];

                    for (index = w - 2; index > 0; index--) {

                        if (is16bit)

                            ((uint16_t*)line)[index] = (((uint16_t*)line)[index / 2] + ((uint16_t*)line)[(index + 1) / 2]) >> 1;

                        else

                            line[index] = (line[index / 2] + line[(index + 1) / 2]) >> 1;

                    }

                } else if (s->upscale_h[p] == 2) {

                    if (is16bit) {

                        ((uint16_t*)line)[w - 1] = ((uint16_t*)line)[(w - 1) / 3];

                        if (w > 1)

                            ((uint16_t*)line)[w - 2] = ((uint16_t*)line)[w - 1];

                    } else {

                        line[w - 1] = line[(w - 1) / 3];

                        if (w > 1)

                            line[w - 2] = line[w - 1];

                    }

                    for (index = w - 3; index > 0; index--) {

                        line[index] = (line[index / 3] + line[(index + 1) / 3] + line[(index + 2) / 3] + 1) / 3;

                    }

                }

                line += s->linesize[p];

            }

        }

    }

    if (AV_RB32(s->upscale_v)) {

        int p;

        av_assert0(avctx->pix_fmt == AV_PIX_FMT_YUVJ444P ||

                   avctx->pix_fmt == AV_PIX_FMT_YUV444P  ||

                   avctx->pix_fmt == AV_PIX_FMT_YUVJ422P ||

                   avctx->pix_fmt == AV_PIX_FMT_YUV422P  ||

                   avctx->pix_fmt == AV_PIX_FMT_YUVJ420P ||

                   avctx->pix_fmt == AV_PIX_FMT_YUV420P  ||

                   avctx->pix_fmt == AV_PIX_FMT_YUV440P  ||

                   avctx->pix_fmt == AV_PIX_FMT_YUVJ440P ||

                   avctx->pix_fmt == AV_PIX_FMT_YUVA444P ||

                   avctx->pix_fmt == AV_PIX_FMT_YUVA420P  ||

                   avctx->pix_fmt == AV_PIX_FMT_YUVA420P16||

                   avctx->pix_fmt == AV_PIX_FMT_GBRP     ||

                   avctx->pix_fmt == AV_PIX_FMT_GBRAP

                   );

        avcodec_get_chroma_sub_sample(s->avctx->pix_fmt, &hshift, &vshift);

        for (p = 0; p < 4; p++) {

            uint8_t *dst;

            int w = s->width;

            int h = s->height;

            if (!s->upscale_v[p])

                continue;

            if (p==1 || p==2) {

                w = AV_CEIL_RSHIFT(w, hshift);

                h = AV_CEIL_RSHIFT(h, vshift);

            }

            dst = &((uint8_t *)s->picture_ptr->data[p])[(h - 1) * s->linesize[p]];

            for (i = h - 1; i; i--) {

                uint8_t *src1 = &((uint8_t *)s->picture_ptr->data[p])[i / 2 * s->linesize[p]];

                uint8_t *src2 = &((uint8_t *)s->picture_ptr->data[p])[(i + 1) / 2 * s->linesize[p]];

                if (src1 == src2 || i == h - 1) {

                    memcpy(dst, src1, w);

                } else {

                    for (index = 0; index < w; index++)

                        dst[index] = (src1[index] + src2[index]) >> 1;

                }

                dst -= s->linesize[p];

            }

        }

    }

    if (s->flipped) {

        int j;

        avcodec_get_chroma_sub_sample(s->avctx->pix_fmt, &hshift, &vshift);

        for (index=0; index<4; index++) {

            uint8_t *dst = s->picture_ptr->data[index];

            int w = s->picture_ptr->width;

            int h = s->picture_ptr->height;

            if(index && index<3){

                w = AV_CEIL_RSHIFT(w, hshift);

                h = AV_CEIL_RSHIFT(h, vshift);

            }

            if(dst){

                uint8_t *dst2 = dst + s->picture_ptr->linesize[index]*(h-1);

                for (i=0; i<h/2; i++) {

                    for (j=0; j<w; j++)

                        FFSWAP(int, dst[j], dst2[j]);

                    dst  += s->picture_ptr->linesize[index];

                    dst2 -= s->picture_ptr->linesize[index];

                }

            }

        }

    }

    if (s->adobe_transform == 0 && s->avctx->pix_fmt == AV_PIX_FMT_GBRAP) {

        int w = s->picture_ptr->width;

        int h = s->picture_ptr->height;

        for (i=0; i<h; i++) {

            int j;

            uint8_t *dst[4];

            for (index=0; index<4; index++) {

                dst[index] =   s->picture_ptr->data[index]

                             + s->picture_ptr->linesize[index]*i;

            }

            for (j=0; j<w; j++) {

                int k = dst[3][j];

                int r = dst[0][j] * k;

                int g = dst[1][j] * k;

                int b = dst[2][j] * k;

                dst[0][j] = g*257 >> 16;

                dst[1][j] = b*257 >> 16;

                dst[2][j] = r*257 >> 16;

                dst[3][j] = 255;

            }

        }

    }

    if (s->adobe_transform == 2 && s->avctx->pix_fmt == AV_PIX_FMT_YUVA444P) {

        int w = s->picture_ptr->width;

        int h = s->picture_ptr->height;

        for (i=0; i<h; i++) {

            int j;

            uint8_t *dst[4];

            for (index=0; index<4; index++) {

                dst[index] =   s->picture_ptr->data[index]

                             + s->picture_ptr->linesize[index]*i;

            }

            for (j=0; j<w; j++) {

                int k = dst[3][j];

                int r = (255 - dst[0][j]) * k;

                int g = (128 - dst[1][j]) * k;

                int b = (128 - dst[2][j]) * k;

                dst[0][j] = r*257 >> 16;

                dst[1][j] = (g*257 >> 16) + 128;

                dst[2][j] = (b*257 >> 16) + 128;

                dst[3][j] = 255;

            }

        }

    }



    if (s->stereo3d) {

        AVStereo3D *stereo = av_stereo3d_create_side_data(data);

        if (stereo) {

            stereo->type  = s->stereo3d->type;

            stereo->flags = s->stereo3d->flags;

        }

        av_freep(&s->stereo3d);

    }



    av_dict_copy(avpriv_frame_get_metadatap(data), s->exif_metadata, 0);

    av_dict_free(&s->exif_metadata);



the_end_no_picture:

    av_log(avctx, AV_LOG_DEBUG, "decode frame unused %"PTRDIFF_SPECIFIER" bytes\n",

           buf_end - buf_ptr);

//  return buf_end - buf_ptr;

    return buf_ptr - buf;

}

static int vp3_update_thread_context(AVCodecContext *dst, const AVCodecContext *src)

{

    Vp3DecodeContext *s = dst->priv_data, *s1 = src->priv_data;

    int qps_changed = 0, i, err;



#define copy_fields(to, from, start_field, end_field) memcpy(&to->start_field, &from->start_field, (char*)&to->end_field - (char*)&to->start_field)



    if (!s1->current_frame.data[0]

        ||s->width != s1->width

        ||s->height!= s1->height) {

        if (s != s1)

            copy_fields(s, s1, golden_frame, current_frame);

        return -1;

    }



    if (s != s1) {

        // init tables if the first frame hasn't been decoded

        if (!s->current_frame.data[0]) {

            int y_fragment_count, c_fragment_count;

            s->avctx = dst;

            err = allocate_tables(dst);

            if (err)

                return err;

            y_fragment_count = s->fragment_width[0] * s->fragment_height[0];

            c_fragment_count = s->fragment_width[1] * s->fragment_height[1];

            memcpy(s->motion_val[0], s1->motion_val[0], y_fragment_count * sizeof(*s->motion_val[0]));

            memcpy(s->motion_val[1], s1->motion_val[1], c_fragment_count * sizeof(*s->motion_val[1]));

        }



        // copy previous frame data

        copy_fields(s, s1, golden_frame, dsp);



        // copy qscale data if necessary

        for (i = 0; i < 3; i++) {

            if (s->qps[i] != s1->qps[1]) {

                qps_changed = 1;

                memcpy(&s->qmat[i], &s1->qmat[i], sizeof(s->qmat[i]));

            }

        }



        if (s->qps[0] != s1->qps[0])

            memcpy(&s->bounding_values_array, &s1->bounding_values_array, sizeof(s->bounding_values_array));



        if (qps_changed)

            copy_fields(s, s1, qps, superblock_count);

#undef copy_fields

    }



    update_frames(dst);



    return 0;

}

void ff_init_elbg(int *points, int dim, int numpoints, int *codebook,

                  int numCB, int max_steps, int *closest_cb,

                  AVLFG *rand_state)

{

    int i, k;



    if (numpoints > 24*numCB) {

        /* ELBG is very costly for a big number of points. So if we have a lot

           of them, get a good initial codebook to save on iterations       */

        int *temp_points = av_malloc(dim*(numpoints/8)*sizeof(int));

        for (i=0; i<numpoints/8; i++) {

            k = (i*BIG_PRIME) % numpoints;

            memcpy(temp_points + i*dim, points + k*dim, dim*sizeof(int));

        }



        ff_init_elbg(temp_points, dim, numpoints/8, codebook, numCB, 2*max_steps, closest_cb, rand_state);

        ff_do_elbg(temp_points, dim, numpoints/8, codebook, numCB, 2*max_steps, closest_cb, rand_state);



        av_free(temp_points);



    } else  // If not, initialize the codebook with random positions

        for (i=0; i < numCB; i++)

            memcpy(codebook + i*dim, points + ((i*BIG_PRIME)%numpoints)*dim,

                   dim*sizeof(int));



}

