static void sbr_hf_assemble(float Y[2][38][64][2], const float X_high[64][40][2],

                            SpectralBandReplication *sbr, SBRData *ch_data,

                            const int e_a[2])

{

    int e, i, j, m;

    const int h_SL = 4 * !sbr->bs_smoothing_mode;

    const int kx = sbr->kx[1];

    const int m_max = sbr->m[1];

    static const float h_smooth[5] = {

        0.33333333333333,

        0.30150283239582,

        0.21816949906249,

        0.11516383427084,

        0.03183050093751,

    };

    static const int8_t phi[2][4] = {

        {  1,  0, -1,  0}, // real

        {  0,  1,  0, -1}, // imaginary

    };

    float (*g_temp)[48] = ch_data->g_temp, (*q_temp)[48] = ch_data->q_temp;

    int indexnoise = ch_data->f_indexnoise;

    int indexsine  = ch_data->f_indexsine;

    memcpy(Y[0], Y[1], sizeof(Y[0]));



    if (sbr->reset) {

        for (i = 0; i < h_SL; i++) {

            memcpy(g_temp[i + 2*ch_data->t_env[0]], sbr->gain[0], m_max * sizeof(sbr->gain[0][0]));

            memcpy(q_temp[i + 2*ch_data->t_env[0]], sbr->q_m[0],  m_max * sizeof(sbr->q_m[0][0]));

        }

    } else if (h_SL) {

        memcpy(g_temp[2*ch_data->t_env[0]], g_temp[2*ch_data->t_env_num_env_old], 4*sizeof(g_temp[0]));

        memcpy(q_temp[2*ch_data->t_env[0]], q_temp[2*ch_data->t_env_num_env_old], 4*sizeof(q_temp[0]));

    }



    for (e = 0; e < ch_data->bs_num_env; e++) {

        for (i = 2 * ch_data->t_env[e]; i < 2 * ch_data->t_env[e + 1]; i++) {

            memcpy(g_temp[h_SL + i], sbr->gain[e], m_max * sizeof(sbr->gain[0][0]));

            memcpy(q_temp[h_SL + i], sbr->q_m[e],  m_max * sizeof(sbr->q_m[0][0]));

        }

    }



    for (e = 0; e < ch_data->bs_num_env; e++) {

        for (i = 2 * ch_data->t_env[e]; i < 2 * ch_data->t_env[e + 1]; i++) {

            int phi_sign = (1 - 2*(kx & 1));



            if (h_SL && e != e_a[0] && e != e_a[1]) {

                for (m = 0; m < m_max; m++) {

                    const int idx1 = i + h_SL;

                    float g_filt = 0.0f;

                    for (j = 0; j <= h_SL; j++)

                        g_filt += g_temp[idx1 - j][m] * h_smooth[j];

                    Y[1][i][m + kx][0] =

                        X_high[m + kx][i + ENVELOPE_ADJUSTMENT_OFFSET][0] * g_filt;

                    Y[1][i][m + kx][1] =

                        X_high[m + kx][i + ENVELOPE_ADJUSTMENT_OFFSET][1] * g_filt;

                }

            } else {

                for (m = 0; m < m_max; m++) {

                    const float g_filt = g_temp[i + h_SL][m];

                    Y[1][i][m + kx][0] =

                        X_high[m + kx][i + ENVELOPE_ADJUSTMENT_OFFSET][0] * g_filt;

                    Y[1][i][m + kx][1] =

                        X_high[m + kx][i + ENVELOPE_ADJUSTMENT_OFFSET][1] * g_filt;

                }

            }



            if (e != e_a[0] && e != e_a[1]) {

                for (m = 0; m < m_max; m++) {

                    indexnoise = (indexnoise + 1) & 0x1ff;

                    if (sbr->s_m[e][m]) {

                        Y[1][i][m + kx][0] +=

                            sbr->s_m[e][m] * phi[0][indexsine];

                        Y[1][i][m + kx][1] +=

                            sbr->s_m[e][m] * (phi[1][indexsine] * phi_sign);

                    } else {

                        float q_filt;

                        if (h_SL) {

                            const int idx1 = i + h_SL;

                            q_filt = 0.0f;

                            for (j = 0; j <= h_SL; j++)

                                q_filt += q_temp[idx1 - j][m] * h_smooth[j];

                        } else {

                            q_filt = q_temp[i][m];

                        }

                        Y[1][i][m + kx][0] +=

                            q_filt * sbr_noise_table[indexnoise][0];

                        Y[1][i][m + kx][1] +=

                            q_filt * sbr_noise_table[indexnoise][1];

                    }

                    phi_sign = -phi_sign;

                }

            } else {

                indexnoise = (indexnoise + m_max) & 0x1ff;

                for (m = 0; m < m_max; m++) {

                    Y[1][i][m + kx][0] +=

                        sbr->s_m[e][m] * phi[0][indexsine];

                    Y[1][i][m + kx][1] +=

                        sbr->s_m[e][m] * (phi[1][indexsine] * phi_sign);

                    phi_sign = -phi_sign;

                }

            }

            indexsine = (indexsine + 1) & 3;

        }

    }

    ch_data->f_indexnoise = indexnoise;

    ch_data->f_indexsine  = indexsine;

}

int ff_init_poc(H264Context *h, int pic_field_poc[2], int *pic_poc)

{

    const SPS *sps = h->ps.sps;

    const int max_frame_num = 1 << sps->log2_max_frame_num;

    int field_poc[2];



    h->frame_num_offset = h->prev_frame_num_offset;

    if (h->frame_num < h->prev_frame_num)

        h->frame_num_offset += max_frame_num;



    if (sps->poc_type == 0) {

        const int max_poc_lsb = 1 << sps->log2_max_poc_lsb;



        if (h->poc_lsb < h->prev_poc_lsb &&

            h->prev_poc_lsb - h->poc_lsb >= max_poc_lsb / 2)

            h->poc_msb = h->prev_poc_msb + max_poc_lsb;

        else if (h->poc_lsb > h->prev_poc_lsb &&

                 h->prev_poc_lsb - h->poc_lsb < -max_poc_lsb / 2)

            h->poc_msb = h->prev_poc_msb - max_poc_lsb;

        else

            h->poc_msb = h->prev_poc_msb;

        field_poc[0] =

        field_poc[1] = h->poc_msb + h->poc_lsb;

        if (h->picture_structure == PICT_FRAME)

            field_poc[1] += h->delta_poc_bottom;

    } else if (sps->poc_type == 1) {

        int abs_frame_num, expected_delta_per_poc_cycle, expectedpoc;

        int i;



        if (sps->poc_cycle_length != 0)

            abs_frame_num = h->frame_num_offset + h->frame_num;

        else

            abs_frame_num = 0;



        if (h->nal_ref_idc == 0 && abs_frame_num > 0)

            abs_frame_num--;



        expected_delta_per_poc_cycle = 0;

        for (i = 0; i < sps->poc_cycle_length; i++)

            // FIXME integrate during sps parse

            expected_delta_per_poc_cycle += sps->offset_for_ref_frame[i];



        if (abs_frame_num > 0) {

            int poc_cycle_cnt          = (abs_frame_num - 1) / sps->poc_cycle_length;

            int frame_num_in_poc_cycle = (abs_frame_num - 1) % sps->poc_cycle_length;



            expectedpoc = poc_cycle_cnt * expected_delta_per_poc_cycle;

            for (i = 0; i <= frame_num_in_poc_cycle; i++)

                expectedpoc = expectedpoc + sps->offset_for_ref_frame[i];

        } else

            expectedpoc = 0;



        if (h->nal_ref_idc == 0)

            expectedpoc = expectedpoc + sps->offset_for_non_ref_pic;



        field_poc[0] = expectedpoc + h->delta_poc[0];

        field_poc[1] = field_poc[0] + sps->offset_for_top_to_bottom_field;



        if (h->picture_structure == PICT_FRAME)

            field_poc[1] += h->delta_poc[1];

    } else {

        int poc = 2 * (h->frame_num_offset + h->frame_num);



        if (!h->nal_ref_idc)

            poc--;



        field_poc[0] = poc;

        field_poc[1] = poc;

    }



    if (h->picture_structure != PICT_BOTTOM_FIELD)

        pic_field_poc[0] = field_poc[0];

    if (h->picture_structure != PICT_TOP_FIELD)

        pic_field_poc[1] = field_poc[1];

    *pic_poc = FFMIN(pic_field_poc[0], pic_field_poc[1]);



    return 0;

}

static int sdp_parse_rtpmap(AVFormatContext *s,

                            AVStream *st, RTSPStream *rtsp_st,

                            int payload_type, const char *p)

{

    AVCodecContext *codec = st->codec;

    char buf[256];

    int i;

    AVCodec *c;

    const char *c_name;



    /* See if we can handle this kind of payload.

     * The space should normally not be there but some Real streams or

     * particular servers ("RealServer Version 6.1.3.970", see issue 1658)

     * have a trailing space. */

    get_word_sep(buf, sizeof(buf), "/ ", &p);

    if (payload_type < RTP_PT_PRIVATE) {

        /* We are in a standard case

         * (from http://www.iana.org/assignments/rtp-parameters). */

        codec->codec_id = ff_rtp_codec_id(buf, codec->codec_type);

    }



    if (codec->codec_id == AV_CODEC_ID_NONE) {

        RTPDynamicProtocolHandler *handler =

            ff_rtp_handler_find_by_name(buf, codec->codec_type);

        init_rtp_handler(handler, rtsp_st, st);

        /* If no dynamic handler was found, check with the list of standard

         * allocated types, if such a stream for some reason happens to

         * use a private payload type. This isn't handled in rtpdec.c, since

         * the format name from the rtpmap line never is passed into rtpdec. */

        if (!rtsp_st->dynamic_handler)

            codec->codec_id = ff_rtp_codec_id(buf, codec->codec_type);

    }



    c = avcodec_find_decoder(codec->codec_id);

    if (c && c->name)

        c_name = c->name;

    else

        c_name = "(null)";



    get_word_sep(buf, sizeof(buf), "/", &p);

    i = atoi(buf);

    switch (codec->codec_type) {

    case AVMEDIA_TYPE_AUDIO:

        av_log(s, AV_LOG_DEBUG, "audio codec set to: %s\n", c_name);

        codec->sample_rate = RTSP_DEFAULT_AUDIO_SAMPLERATE;

        codec->channels = RTSP_DEFAULT_NB_AUDIO_CHANNELS;

        if (i > 0) {

            codec->sample_rate = i;

            avpriv_set_pts_info(st, 32, 1, codec->sample_rate);

            get_word_sep(buf, sizeof(buf), "/", &p);

            i = atoi(buf);

            if (i > 0)

                codec->channels = i;

        }

        av_log(s, AV_LOG_DEBUG, "audio samplerate set to: %i\n",

               codec->sample_rate);

        av_log(s, AV_LOG_DEBUG, "audio channels set to: %i\n",

               codec->channels);

        break;

    case AVMEDIA_TYPE_VIDEO:

        av_log(s, AV_LOG_DEBUG, "video codec set to: %s\n", c_name);

        if (i > 0)

            avpriv_set_pts_info(st, 32, 1, i);

        break;

    default:

        break;

    }

    if (rtsp_st->dynamic_handler && rtsp_st->dynamic_handler->init)

        rtsp_st->dynamic_handler->init(s, st->index,

                                       rtsp_st->dynamic_protocol_context);

    return 0;

}

void ff_dsputil_init_ppc(DSPContext* c, AVCodecContext *avctx)

{

    const int high_bit_depth = avctx->bits_per_raw_sample > 8;



    // Common optimizations whether AltiVec is available or not

    c->prefetch = prefetch_ppc;

    if (!high_bit_depth) {

    switch (check_dcbzl_effect()) {

        case 32:

            c->clear_blocks = clear_blocks_dcbz32_ppc;

            break;

        case 128:

            c->clear_blocks = clear_blocks_dcbz128_ppc;

            break;

        default:

            break;

    }

    }



#if HAVE_ALTIVEC

    if(CONFIG_H264_DECODER) ff_dsputil_h264_init_ppc(c, avctx);



    if (av_get_cpu_flags() & AV_CPU_FLAG_ALTIVEC) {

        ff_dsputil_init_altivec(c, avctx);

        ff_float_init_altivec(c, avctx);

        ff_int_init_altivec(c, avctx);

        c->gmc1 = ff_gmc1_altivec;



#if CONFIG_ENCODERS

        if (avctx->bits_per_raw_sample <= 8 &&

            (avctx->dct_algo == FF_DCT_AUTO ||

             avctx->dct_algo == FF_DCT_ALTIVEC)) {

            c->fdct = ff_fdct_altivec;

        }

#endif //CONFIG_ENCODERS



        if (avctx->bits_per_raw_sample <= 8) {

            if ((avctx->idct_algo == FF_IDCT_AUTO) ||

                (avctx->idct_algo == FF_IDCT_ALTIVEC)) {

                c->idct_put = ff_idct_put_altivec;

                c->idct_add = ff_idct_add_altivec;

                c->idct_permutation_type = FF_TRANSPOSE_IDCT_PERM;

            }else if((CONFIG_VP3_DECODER || CONFIG_VP5_DECODER || CONFIG_VP6_DECODER) &&

                     avctx->idct_algo==FF_IDCT_VP3){

                c->idct_put = ff_vp3_idct_put_altivec;

                c->idct_add = ff_vp3_idct_add_altivec;

                c->idct     = ff_vp3_idct_altivec;

                c->idct_permutation_type = FF_TRANSPOSE_IDCT_PERM;

            }

        }



    }

#endif /* HAVE_ALTIVEC */

}

static int ffm_is_avail_data(AVFormatContext *s, int size)

{

    FFMContext *ffm = s->priv_data;

    int64_t pos, avail_size;

    int len;



    len = ffm->packet_end - ffm->packet_ptr;

    if (size <= len)

        return 1;

    pos = avio_tell(s->pb);

    if (!ffm->write_index) {

        if (pos == ffm->file_size)

            return AVERROR_EOF;

        avail_size = ffm->file_size - pos;

    } else {

    if (pos == ffm->write_index) {

        /* exactly at the end of stream */

        if (ffm->server_attached)

            return AVERROR(EAGAIN);

        else

            return AVERROR_INVALIDDATA;

    } else if (pos < ffm->write_index) {

        avail_size = ffm->write_index - pos;

    } else {

        avail_size = (ffm->file_size - pos) + (ffm->write_index - FFM_PACKET_SIZE);

    }

    }

    avail_size = (avail_size / ffm->packet_size) * (ffm->packet_size - FFM_HEADER_SIZE) + len;

    if (size <= avail_size)

        return 1;

    else if (ffm->server_attached)

        return AVERROR(EAGAIN);

    else

        return AVERROR_INVALIDDATA;

}

static int execute_ref_pic_marking(H264Context *h, MMCO *mmco, int mmco_count){
    MpegEncContext * const s = &h->s;
    int i, j;
    int current_ref_assigned=0;
    Picture *pic;
    if((s->avctx->debug&FF_DEBUG_MMCO) && mmco_count==0)
        av_log(h->s.avctx, AV_LOG_DEBUG, "no mmco here\n");
    for(i=0; i<mmco_count; i++){
        int structure, frame_num, unref_pic;
        if(s->avctx->debug&FF_DEBUG_MMCO)
            av_log(h->s.avctx, AV_LOG_DEBUG, "mmco:%d %d %d\n", h->mmco[i].opcode, h->mmco[i].short_pic_num, h->mmco[i].long_arg);
        switch(mmco[i].opcode){
        case MMCO_SHORT2UNUSED:
            if(s->avctx->debug&FF_DEBUG_MMCO)
                av_log(h->s.avctx, AV_LOG_DEBUG, "mmco: unref short %d count %d\n", h->mmco[i].short_pic_num, h->short_ref_count);
            frame_num = pic_num_extract(h, mmco[i].short_pic_num, &structure);
            pic = find_short(h, frame_num, &j);
            if (pic) {
                if (unreference_pic(h, pic, structure ^ PICT_FRAME))
                    remove_short_at_index(h, j);
            } else if(s->avctx->debug&FF_DEBUG_MMCO)
                av_log(h->s.avctx, AV_LOG_DEBUG, "mmco: unref short failure\n");
        case MMCO_SHORT2LONG:
            if (FIELD_PICTURE && mmco[i].long_arg < h->long_ref_count &&
                    h->long_ref[mmco[i].long_arg]->frame_num ==
                                              mmco[i].short_pic_num / 2) {
                /* do nothing, we've already moved this field pair. */
                int frame_num = mmco[i].short_pic_num >> FIELD_PICTURE;
                pic= remove_long(h, mmco[i].long_arg);
                if(pic) unreference_pic(h, pic, 0);
                h->long_ref[ mmco[i].long_arg ]= remove_short(h, frame_num);
                if (h->long_ref[ mmco[i].long_arg ]){
                    h->long_ref[ mmco[i].long_arg ]->long_ref=1;
                    h->long_ref_count++;
        case MMCO_LONG2UNUSED:
            j = pic_num_extract(h, mmco[i].long_arg, &structure);
            pic = h->long_ref[j];
            if (pic) {
                if (unreference_pic(h, pic, structure ^ PICT_FRAME))
                    remove_long_at_index(h, j);
            } else if(s->avctx->debug&FF_DEBUG_MMCO)
                av_log(h->s.avctx, AV_LOG_DEBUG, "mmco: unref long failure\n");
        case MMCO_LONG:
            unref_pic = 1;
            if (FIELD_PICTURE && !s->first_field) {
                if (h->long_ref[mmco[i].long_arg] == s->current_picture_ptr) {
                    /* Just mark second field as referenced */
                    unref_pic = 0;
                } else if (s->current_picture_ptr->reference) {
                    /* First field in pair is in short term list or
                     * at a different long term index.
                     * This is not allowed; see 7.4.3, notes 2 and 3.
                     * Report the problem and keep the pair where it is,
                     * and mark this field valid.
                        "illegal long term reference assignment for second "
                        "field in complementary field pair (first field is "
                        "short term or has non-matching long index)\n");
                    unref_pic = 0;
            if (unref_pic) {
                pic= remove_long(h, mmco[i].long_arg);
                if(pic) unreference_pic(h, pic, 0);
                h->long_ref[ mmco[i].long_arg ]= s->current_picture_ptr;
                h->long_ref[ mmco[i].long_arg ]->long_ref=1;
                h->long_ref_count++;
            s->current_picture_ptr->reference |= s->picture_structure;
            current_ref_assigned=1;
        case MMCO_SET_MAX_LONG:
            assert(mmco[i].long_arg <= 16);
            // just remove the long term which index is greater than new max
            for(j = mmco[i].long_arg; j<16; j++){
                pic = remove_long(h, j);
                if (pic) unreference_pic(h, pic, 0);
        case MMCO_RESET:
            while(h->short_ref_count){
                pic= remove_short(h, h->short_ref[0]->frame_num);
                if(pic) unreference_pic(h, pic, 0);
            for(j = 0; j < 16; j++) {
                pic= remove_long(h, j);
                if(pic) unreference_pic(h, pic, 0);
        default: assert(0);
    if (!current_ref_assigned && FIELD_PICTURE &&
            !s->first_field && s->current_picture_ptr->reference) {
        /* Second field of complementary field pair; the first field of
         * which is already referenced. If short referenced, it
         * should be first entry in short_ref. If not, it must exist
         * in long_ref; trying to put it on the short list here is an
         * error in the encoded bit stream (ref: 7.4.3, NOTE 2 and 3).
        if (h->short_ref_count && h->short_ref[0] == s->current_picture_ptr) {
            /* Just mark the second field valid */
            s->current_picture_ptr->reference = PICT_FRAME;
        } else if (s->current_picture_ptr->long_ref) {
            av_log(h->s.avctx, AV_LOG_ERROR, "illegal short term reference "
                                             "assignment for second field "
                                             "in complementary field pair "
                                             "(first field is long term)\n");
            /*
             * First field in reference, but not in any sensible place on our
             * reference lists. This shouldn't happen unless reference
             * handling somewhere else is wrong.
            assert(0);
        current_ref_assigned = 1;
    if(!current_ref_assigned){
        pic= remove_short(h, s->current_picture_ptr->frame_num);
        if(pic){
            unreference_pic(h, pic, 0);
            av_log(h->s.avctx, AV_LOG_ERROR, "illegal short term buffer state detected\n");
        if(h->short_ref_count)
            memmove(&h->short_ref[1], &h->short_ref[0], h->short_ref_count*sizeof(Picture*));
        h->short_ref[0]= s->current_picture_ptr;
        h->short_ref[0]->long_ref=0;
        h->short_ref_count++;
        s->current_picture_ptr->reference |= s->picture_structure;
    print_short_term(h);
    print_long_term(h);
    return 0;

static void filter_samples(AVFilterLink *inlink, AVFilterBufferRef *samplesref)

{

    AVFilterContext *ctx = inlink->dst;

    ShowInfoContext *showinfo = ctx->priv;

    uint32_t plane_checksum[8] = {0}, checksum = 0;

    char chlayout_str[128];

    int plane;



    for (plane = 0; samplesref->data[plane] && plane < 8; plane++) {

        uint8_t *data = samplesref->data[plane];

        int linesize = samplesref->linesize[plane];



        plane_checksum[plane] = av_adler32_update(plane_checksum[plane],

                                                  data, linesize);

        checksum = av_adler32_update(checksum, data, linesize);

    }



    av_get_channel_layout_string(chlayout_str, sizeof(chlayout_str), -1,

                                 samplesref->audio->channel_layout);



    av_log(ctx, AV_LOG_INFO,

           "n:%d pts:%"PRId64" pts_time:%f pos:%"PRId64" "

           "fmt:%s chlayout:%s nb_samples:%d rate:%d planar:%d "

           "checksum:%u plane_checksum[%u %u %u %u %u %u %u %u]\n",

           showinfo->frame,

           samplesref->pts, samplesref->pts * av_q2d(inlink->time_base),

           samplesref->pos,

           av_get_sample_fmt_name(samplesref->format),

           chlayout_str,

           samplesref->audio->nb_samples,

           samplesref->audio->sample_rate,

           samplesref->audio->planar,

           checksum,

           plane_checksum[0], plane_checksum[1], plane_checksum[2], plane_checksum[3],

           plane_checksum[4], plane_checksum[5], plane_checksum[6], plane_checksum[7]);



    showinfo->frame++;



    avfilter_filter_samples(inlink->dst->outputs[0], samplesref);

}

static av_cold int vaapi_encode_init_rate_control(AVCodecContext *avctx)

{

    VAAPIEncodeContext *ctx = avctx->priv_data;

    int hrd_buffer_size;

    int hrd_initial_buffer_fullness;



    if (avctx->rc_buffer_size)

        hrd_buffer_size = avctx->rc_buffer_size;

    else

        hrd_buffer_size = avctx->bit_rate;

    if (avctx->rc_initial_buffer_occupancy)

        hrd_initial_buffer_fullness = avctx->rc_initial_buffer_occupancy;

    else

        hrd_initial_buffer_fullness = hrd_buffer_size * 3 / 4;



    ctx->rc_params.misc.type = VAEncMiscParameterTypeRateControl;

    ctx->rc_params.rc = (VAEncMiscParameterRateControl) {

        .bits_per_second   = avctx->bit_rate,

        .target_percentage = 66,

        .window_size       = 1000,

        .initial_qp        = (avctx->qmax >= 0 ? avctx->qmax : 40),

        .min_qp            = (avctx->qmin >= 0 ? avctx->qmin : 18),

        .basic_unit_size   = 0,

    };

    ctx->global_params[ctx->nb_global_params] =

        &ctx->rc_params.misc;

    ctx->global_params_size[ctx->nb_global_params++] =

        sizeof(ctx->rc_params);



    ctx->hrd_params.misc.type = VAEncMiscParameterTypeHRD;

    ctx->hrd_params.hrd = (VAEncMiscParameterHRD) {

        .initial_buffer_fullness = hrd_initial_buffer_fullness,

        .buffer_size             = hrd_buffer_size,

    };

    ctx->global_params[ctx->nb_global_params] =

        &ctx->hrd_params.misc;

    ctx->global_params_size[ctx->nb_global_params++] =

        sizeof(ctx->hrd_params);



    return 0;

}

static void compute_pkt_fields(AVFormatContext *s, AVStream *st, 

                               AVCodecParserContext *pc, AVPacket *pkt)

{

    int num, den, presentation_delayed;



    /* handle wrapping */

    if(st->cur_dts != AV_NOPTS_VALUE){

        if(pkt->pts != AV_NOPTS_VALUE)

            pkt->pts= lsb2full(pkt->pts, st->cur_dts, st->pts_wrap_bits);

        if(pkt->dts != AV_NOPTS_VALUE)

            pkt->dts= lsb2full(pkt->dts, st->cur_dts, st->pts_wrap_bits);

    }



    if (pkt->duration == 0) {

        compute_frame_duration(&num, &den, s, st, pc, pkt);

        if (den && num) {

            pkt->duration = av_rescale(1, num * (int64_t)st->time_base.den, den * (int64_t)st->time_base.num);

        }

    }



    /* do we have a video B frame ? */

    presentation_delayed = 0;

    if (st->codec.codec_type == CODEC_TYPE_VIDEO) {

        /* XXX: need has_b_frame, but cannot get it if the codec is

           not initialized */

        if ((st->codec.codec_id == CODEC_ID_MPEG1VIDEO ||

             st->codec.codec_id == CODEC_ID_MPEG2VIDEO ||

             st->codec.codec_id == CODEC_ID_MPEG4 ||

             st->codec.codec_id == CODEC_ID_H264) && 

            pc && pc->pict_type != FF_B_TYPE)

            presentation_delayed = 1;

        /* this may be redundant, but it shouldnt hurt */

        if(pkt->dts != AV_NOPTS_VALUE && pkt->pts != AV_NOPTS_VALUE && pkt->pts > pkt->dts)

            presentation_delayed = 1;

    }



    if(st->cur_dts == AV_NOPTS_VALUE){

        if(presentation_delayed) st->cur_dts = -pkt->duration;

        else                     st->cur_dts = 0;

    }



//    av_log(NULL, AV_LOG_DEBUG, "IN delayed:%d pts:%lld, dts:%lld cur_dts:%lld\n", presentation_delayed, pkt->pts, pkt->dts, st->cur_dts);

    /* interpolate PTS and DTS if they are not present */

    if (presentation_delayed) {

        /* DTS = decompression time stamp */

        /* PTS = presentation time stamp */

        if (pkt->dts == AV_NOPTS_VALUE) {

            /* if we know the last pts, use it */

            if(st->last_IP_pts != AV_NOPTS_VALUE)

                st->cur_dts = pkt->dts = st->last_IP_pts;

            else

                pkt->dts = st->cur_dts;

        } else {

            st->cur_dts = pkt->dts;

        }

        /* this is tricky: the dts must be incremented by the duration

           of the frame we are displaying, i.e. the last I or P frame */

        if (st->last_IP_duration == 0)

            st->cur_dts += pkt->duration;

        else

            st->cur_dts += st->last_IP_duration;

        st->last_IP_duration  = pkt->duration;

        st->last_IP_pts= pkt->pts;

        /* cannot compute PTS if not present (we can compute it only

           by knowing the futur */

    } else {

        /* presentation is not delayed : PTS and DTS are the same */

        if (pkt->pts == AV_NOPTS_VALUE) {

            if (pkt->dts == AV_NOPTS_VALUE) {

                pkt->pts = st->cur_dts;

                pkt->dts = st->cur_dts;

            }

            else {

                st->cur_dts = pkt->dts;

                pkt->pts = pkt->dts;

            }

        } else {

            st->cur_dts = pkt->pts;

            pkt->dts = pkt->pts;

        }

        st->cur_dts += pkt->duration;

    }

//    av_log(NULL, AV_LOG_DEBUG, "OUTdelayed:%d pts:%lld, dts:%lld cur_dts:%lld\n", presentation_delayed, pkt->pts, pkt->dts, st->cur_dts);



    /* update flags */

    if (pc) {

        pkt->flags = 0;

        /* key frame computation */

        switch(st->codec.codec_type) {

        case CODEC_TYPE_VIDEO:

            if (pc->pict_type == FF_I_TYPE)

                pkt->flags |= PKT_FLAG_KEY;

            break;

        case CODEC_TYPE_AUDIO:

            pkt->flags |= PKT_FLAG_KEY;

            break;

        default:

            break;

        }

    }



    /* convert the packet time stamp units */

    if(pkt->pts != AV_NOPTS_VALUE)

        pkt->pts = av_rescale(pkt->pts, AV_TIME_BASE * (int64_t)st->time_base.num, st->time_base.den);

    if(pkt->dts != AV_NOPTS_VALUE)

        pkt->dts = av_rescale(pkt->dts, AV_TIME_BASE * (int64_t)st->time_base.num, st->time_base.den);



    /* duration field */

    pkt->duration = av_rescale(pkt->duration, AV_TIME_BASE * (int64_t)st->time_base.num, st->time_base.den);

}

static int ffm_read_packet(AVFormatContext *s, AVPacket *pkt)

{

    int size;

    FFMContext *ffm = s->priv_data;

    int duration, ret;



    switch(ffm->read_state) {

    case READ_HEADER:

        if ((ret = ffm_is_avail_data(s, FRAME_HEADER_SIZE+4)) < 0)

            return ret;



        av_dlog(s, "pos=%08"PRIx64" spos=%"PRIx64", write_index=%"PRIx64" size=%"PRIx64"\n",

               avio_tell(s->pb), s->pb->pos, ffm->write_index, ffm->file_size);

        if (ffm_read_data(s, ffm->header, FRAME_HEADER_SIZE, 1) !=

            FRAME_HEADER_SIZE)

            return -1;

        if (ffm->header[1] & FLAG_DTS)

            if (ffm_read_data(s, ffm->header+16, 4, 1) != 4)

                return -1;

        ffm->read_state = READ_DATA;

        /* fall thru */

    case READ_DATA:

        size = AV_RB24(ffm->header + 2);

        if ((ret = ffm_is_avail_data(s, size)) < 0)

            return ret;



        duration = AV_RB24(ffm->header + 5);



        av_new_packet(pkt, size);

        pkt->stream_index = ffm->header[0];

        if ((unsigned)pkt->stream_index >= s->nb_streams) {

            av_log(s, AV_LOG_ERROR, "invalid stream index %d\n", pkt->stream_index);

            av_free_packet(pkt);

            ffm->read_state = READ_HEADER;

            return -1;

        }

        pkt->pos = avio_tell(s->pb);

        if (ffm->header[1] & FLAG_KEY_FRAME)

            pkt->flags |= AV_PKT_FLAG_KEY;



        ffm->read_state = READ_HEADER;

        if (ffm_read_data(s, pkt->data, size, 0) != size) {

            /* bad case: desynchronized packet. we cancel all the packet loading */

            av_free_packet(pkt);

            return -1;

        }

        pkt->pts = AV_RB64(ffm->header+8);

        if (ffm->header[1] & FLAG_DTS)

            pkt->dts = pkt->pts - AV_RB32(ffm->header+16);

        else

            pkt->dts = pkt->pts;

        pkt->duration = duration;

        break;

    }

    return 0;

}

