static void colored_fputs(int level, int tint, const char *str)

{

    if (!*str)

        return;



    if (use_color < 0)

        check_color_terminal();



#if defined(_WIN32) && !defined(__MINGW32CE__) && HAVE_SETCONSOLETEXTATTRIBUTE

    if (use_color && level != AV_LOG_INFO/8)

        SetConsoleTextAttribute(con, background | color[level]);

    fputs(str, stderr);

    if (use_color && level != AV_LOG_INFO/8)

        SetConsoleTextAttribute(con, attr_orig);

#else

    if (use_color == 1 && level != AV_LOG_INFO/8) {

        fprintf(stderr,

                "\033[%d;3%dm%s\033[0m",

                (color[level] >> 4) & 15,

                color[level] & 15,

                str);

    } else if (tint && use_color == 256) {

        fprintf(stderr,

                "\033[48;5;%dm\033[38;5;%dm%s\033[0m",

                (color[level] >> 16) & 0xff,

                tint,

                str);

    } else if (use_color == 256 && level != AV_LOG_INFO/8) {

        fprintf(stderr,

                "\033[48;5;%dm\033[38;5;%dm%s\033[0m",

                (color[level] >> 16) & 0xff,

                (color[level] >> 8) & 0xff,

                str);

    } else

        fputs(str, stderr);

#endif



}

static int aasc_decode_frame(AVCodecContext *avctx,

                              void *data, int *got_frame,

                              AVPacket *avpkt)

{

    const uint8_t *buf = avpkt->data;

    int buf_size       = avpkt->size;

    AascContext *s     = avctx->priv_data;

    int compr, i, stride, ret;



    s->frame.reference = 1;

    s->frame.buffer_hints = FF_BUFFER_HINTS_VALID | FF_BUFFER_HINTS_PRESERVE | FF_BUFFER_HINTS_REUSABLE;

    if ((ret = avctx->reget_buffer(avctx, &s->frame)) < 0) {

        av_log(avctx, AV_LOG_ERROR, "reget_buffer() failed\n");

        return ret;

    }



    compr     = AV_RL32(buf);

    buf      += 4;

    buf_size -= 4;

    switch (compr) {

    case 0:

        stride = (avctx->width * 3 + 3) & ~3;

        for (i = avctx->height - 1; i >= 0; i--) {

            memcpy(s->frame.data[0] + i * s->frame.linesize[0], buf, avctx->width * 3);

            buf += stride;

        }

        break;

    case 1:

        bytestream2_init(&s->gb, buf - 4, buf_size + 4);

        ff_msrle_decode(avctx, (AVPicture*)&s->frame, 8, &s->gb);

        break;

    default:

        av_log(avctx, AV_LOG_ERROR, "Unknown compression type %d\n", compr);

        return AVERROR_INVALIDDATA;

    }



    *got_frame = 1;

    *(AVFrame*)data = s->frame;



    /* report that the buffer was completely consumed */

    return buf_size;

}

static int rv10_decode_packet(AVCodecContext *avctx, 

                             uint8_t *buf, int buf_size)

{

    MpegEncContext *s = avctx->priv_data;

    int i, mb_count, mb_pos, left;



    init_get_bits(&s->gb, buf, buf_size*8);

#if 0

    for(i=0; i<buf_size*8 && i<200; i++)

        printf("%d", get_bits1(&s->gb));

    printf("\n");

    return 0;

#endif

    if(s->codec_id ==CODEC_ID_RV10)

        mb_count = rv10_decode_picture_header(s);

    else

        mb_count = rv20_decode_picture_header(s);

    if (mb_count < 0) {

        av_log(s->avctx, AV_LOG_ERROR, "HEADER ERROR\n");

        return -1;

    }



    if (s->mb_x >= s->mb_width ||

        s->mb_y >= s->mb_height) {

        av_log(s->avctx, AV_LOG_ERROR, "POS ERROR %d %d\n", s->mb_x, s->mb_y);

        return -1;

    }

    mb_pos = s->mb_y * s->mb_width + s->mb_x;

    left = s->mb_width * s->mb_height - mb_pos;

    if (mb_count > left) {

        av_log(s->avctx, AV_LOG_ERROR, "COUNT ERROR\n");

        return -1;

    }

//if(s->pict_type == P_TYPE) return 0;



    if (s->mb_x == 0 && s->mb_y == 0) {

        if(MPV_frame_start(s, avctx) < 0)

            return -1;

    }



#ifdef DEBUG

    printf("qscale=%d\n", s->qscale);

#endif



    /* default quantization values */

    if(s->codec_id== CODEC_ID_RV10){

        if(s->mb_y==0) s->first_slice_line=1;

    }else{

        s->first_slice_line=1;    

        s->resync_mb_x= s->mb_x;

        s->resync_mb_y= s->mb_y;

    }

    if(s->h263_aic){

        s->y_dc_scale_table= 

        s->c_dc_scale_table= ff_aic_dc_scale_table;

    }else{

        s->y_dc_scale_table=

        s->c_dc_scale_table= ff_mpeg1_dc_scale_table;

    }



    if(s->modified_quant)

        s->chroma_qscale_table= ff_h263_chroma_qscale_table;



    ff_set_qscale(s, s->qscale);



    s->rv10_first_dc_coded[0] = 0;

    s->rv10_first_dc_coded[1] = 0;

    s->rv10_first_dc_coded[2] = 0;



    s->block_wrap[0]=

    s->block_wrap[1]=

    s->block_wrap[2]=

    s->block_wrap[3]= s->mb_width*2 + 2;

    s->block_wrap[4]=

    s->block_wrap[5]= s->mb_width + 2;

    ff_init_block_index(s);

    /* decode each macroblock */

    for(i=0;i<mb_count;i++) {

        int ret;

        ff_update_block_index(s);

#ifdef DEBUG

        printf("**mb x=%d y=%d\n", s->mb_x, s->mb_y);

#endif



	s->dsp.clear_blocks(s->block[0]);

        s->mv_dir = MV_DIR_FORWARD;

        s->mv_type = MV_TYPE_16X16; 

        ret=ff_h263_decode_mb(s, s->block);



        if (ret == SLICE_ERROR) {

            av_log(s->avctx, AV_LOG_ERROR, "ERROR at MB %d %d\n", s->mb_x, s->mb_y);

            return -1;

        }

        ff_h263_update_motion_val(s);

        MPV_decode_mb(s, s->block);

        if(s->loop_filter)

            ff_h263_loop_filter(s);



        if (++s->mb_x == s->mb_width) {

            s->mb_x = 0;

            s->mb_y++;

            ff_init_block_index(s);

        }

        if(s->mb_x == s->resync_mb_x)

            s->first_slice_line=0;

        if(ret == SLICE_END) break;

    }



    return buf_size;

}

static int asf_read_simple_index(AVFormatContext *s, const GUIDParseTable *g)

{

    ASFContext *asf = s->priv_data;

    AVIOContext *pb = s->pb;

    AVStream *st    = NULL;

    uint64_t interval; // index entry time interval in 100 ns units, usually it's 1s

    uint32_t pkt_num, nb_entries;

    int32_t prev_pkt_num = -1;

    int i, ret;

    uint64_t size = avio_rl64(pb);



    // simple index objects should be ordered by stream number, this loop tries to find

    // the first not indexed video stream

    for (i = 0; i < asf->nb_streams; i++) {

        if ((asf->asf_st[i]->type == AVMEDIA_TYPE_VIDEO) && !asf->asf_st[i]->indexed) {

            asf->asf_st[i]->indexed = 1;

            st = s->streams[asf->asf_st[i]->index];

            break;

        }

    }

    if (!st) {

        avio_skip(pb, size - 24); // if there's no video stream, skip index object

        return 0;

    }

    avio_skip(pb, 16); // skip File ID

    interval = avio_rl64(pb);

    avio_skip(pb, 4);

    nb_entries = avio_rl32(pb);

    for (i = 0; i < nb_entries; i++) {

        pkt_num = avio_rl32(pb);

        ret = avio_skip(pb, 2);

        if (ret < 0) {

            av_log(s, AV_LOG_ERROR, "Skipping failed in asf_read_simple_index.\n");

            return ret;

        }

        if (prev_pkt_num != pkt_num) {

            av_add_index_entry(st, asf->first_packet_offset + asf->packet_size *

                               pkt_num, av_rescale(interval, i, 10000),

                               asf->packet_size, 0, AVINDEX_KEYFRAME);

            prev_pkt_num = pkt_num;

        }

    }

    asf->is_simple_index = 1;

    align_position(pb, asf->offset, size);



    return 0;

}

