static void ac3_decode_transform_coeffs_ch(AC3DecodeContext *s, int ch_index, mant_groups *m)

{

    int start_freq = s->start_freq[ch_index];

    int end_freq   = s->end_freq[ch_index];

    uint8_t *baps  = s->bap[ch_index];

    int8_t *exps   = s->dexps[ch_index];

    int32_t *coeffs = s->fixed_coeffs[ch_index];

    int dither     = (ch_index == CPL_CH) || s->dither_flag[ch_index];

    GetBitContext *gbc = &s->gbc;

    int freq;



    for (freq = start_freq; freq < end_freq; freq++) {

        int bap = baps[freq];

        int mantissa;

        switch (bap) {

        case 0:

            /* random noise with approximate range of -0.707 to 0.707 */

            if (dither)

                mantissa = (((av_lfg_get(&s->dith_state)>>8)*181)>>8) - 5931008;

            else

                mantissa = 0;

            break;

        case 1:

            if (m->b1) {

                m->b1--;

                mantissa = m->b1_mant[m->b1];

            } else {

                int bits      = get_bits(gbc, 5);

                mantissa      = b1_mantissas[bits][0];

                m->b1_mant[1] = b1_mantissas[bits][1];

                m->b1_mant[0] = b1_mantissas[bits][2];

                m->b1         = 2;


            break;

        case 2:

            if (m->b2) {

                m->b2--;

                mantissa = m->b2_mant[m->b2];

            } else {

                int bits      = get_bits(gbc, 7);

                mantissa      = b2_mantissas[bits][0];

                m->b2_mant[1] = b2_mantissas[bits][1];

                m->b2_mant[0] = b2_mantissas[bits][2];

                m->b2         = 2;


            break;

        case 3:

            mantissa = b3_mantissas[get_bits(gbc, 3)];

            break;

        case 4:

            if (m->b4) {

                m->b4 = 0;

                mantissa = m->b4_mant;

            } else {

                int bits   = get_bits(gbc, 7);

                mantissa   = b4_mantissas[bits][0];

                m->b4_mant = b4_mantissas[bits][1];

                m->b4      = 1;


            break;

        case 5:

            mantissa = b5_mantissas[get_bits(gbc, 4)];

            break;

        default: /* 6 to 15 */

            /* Shift mantissa and sign-extend it. */





            mantissa = get_sbits(gbc, quantization_tab[bap]);

            mantissa <<= 24 - quantization_tab[bap];

            break;


        coeffs[freq] = mantissa >> exps[freq];

static void draw_bar(TestSourceContext *test, const uint8_t color[4],

                     unsigned x, unsigned y, unsigned w, unsigned h,

                     AVFrame *frame)

{

    const AVPixFmtDescriptor *desc = av_pix_fmt_desc_get(frame->format);

    uint8_t *p, *p0;

    int plane;



    x = FFMIN(x, test->w - 1);

    y = FFMIN(y, test->h - 1);

    w = FFMIN(w, test->w - x);

    h = FFMIN(h, test->h - y);



    av_assert0(x + w <= test->w);

    av_assert0(y + h <= test->h);



    for (plane = 0; frame->data[plane]; plane++) {

        const int c = color[plane];

        const int linesize = frame->linesize[plane];

        int i, px, py, pw, ph;



        if (plane == 1 || plane == 2) {

            px = x >> desc->log2_chroma_w;

            pw = w >> desc->log2_chroma_w;

            py = y >> desc->log2_chroma_h;

            ph = h >> desc->log2_chroma_h;

        } else {

            px = x;

            pw = w;

            py = y;

            ph = h;

        }



        p0 = p = frame->data[plane] + py * linesize + px;

        memset(p, c, pw);

        p += linesize;

        for (i = 1; i < ph; i++, p += linesize)

            memcpy(p, p0, pw);

    }

}

static inline int64_t gb_get_v(GetBitContext *gb)

{

    int64_t v = 0;

    int bits = 0;

    while(get_bits1(gb) && bits < 64-7){

        v <<= 7;

        v |= get_bits(gb, 7);

        bits += 7;

    }

    v <<= 7;

    v |= get_bits(gb, 7);



    return v;

}

static int unpack_vlcs(Vp3DecodeContext *s, GetBitContext *gb,

                        VLC *table, int coeff_index,

                        int plane,

                        int eob_run)

{

    int i, j = 0;

    int token;

    int zero_run = 0;

    DCTELEM coeff = 0;

    int bits_to_get;

    int blocks_ended;

    int coeff_i = 0;

    int num_coeffs = s->num_coded_frags[plane][coeff_index];

    int16_t *dct_tokens = s->dct_tokens[plane][coeff_index];



    /* local references to structure members to avoid repeated deferences */

    int *coded_fragment_list = s->coded_fragment_list[plane];

    Vp3Fragment *all_fragments = s->all_fragments;

    VLC_TYPE (*vlc_table)[2] = table->table;



    if (num_coeffs < 0)

        av_log(s->avctx, AV_LOG_ERROR, "Invalid number of coefficents at level %d\n", coeff_index);



    if (eob_run > num_coeffs) {

        coeff_i = blocks_ended = num_coeffs;

        eob_run -= num_coeffs;

    } else {

        coeff_i = blocks_ended = eob_run;

        eob_run = 0;

    }



    // insert fake EOB token to cover the split between planes or zzi

    if (blocks_ended)

        dct_tokens[j++] = blocks_ended << 2;



    while (coeff_i < num_coeffs && get_bits_left(gb) > 0) {

            /* decode a VLC into a token */

            token = get_vlc2(gb, vlc_table, 11, 3);

            /* use the token to get a zero run, a coefficient, and an eob run */

            if (token <= 6) {

                eob_run = eob_run_base[token];

                if (eob_run_get_bits[token])

                    eob_run += get_bits(gb, eob_run_get_bits[token]);



                // record only the number of blocks ended in this plane,

                // any spill will be recorded in the next plane.

                if (eob_run > num_coeffs - coeff_i) {

                    dct_tokens[j++] = TOKEN_EOB(num_coeffs - coeff_i);

                    blocks_ended   += num_coeffs - coeff_i;

                    eob_run        -= num_coeffs - coeff_i;

                    coeff_i         = num_coeffs;

                } else {

                    dct_tokens[j++] = TOKEN_EOB(eob_run);

                    blocks_ended   += eob_run;

                    coeff_i        += eob_run;

                    eob_run = 0;

                }

            } else {

                bits_to_get = coeff_get_bits[token];

                if (bits_to_get)

                    bits_to_get = get_bits(gb, bits_to_get);

                coeff = coeff_tables[token][bits_to_get];



                zero_run = zero_run_base[token];

                if (zero_run_get_bits[token])

                    zero_run += get_bits(gb, zero_run_get_bits[token]);



                if (zero_run) {

                    dct_tokens[j++] = TOKEN_ZERO_RUN(coeff, zero_run);

                } else {

                    // Save DC into the fragment structure. DC prediction is

                    // done in raster order, so the actual DC can't be in with

                    // other tokens. We still need the token in dct_tokens[]

                    // however, or else the structure collapses on itself.

                    if (!coeff_index)

                        all_fragments[coded_fragment_list[coeff_i]].dc = coeff;



                    dct_tokens[j++] = TOKEN_COEFF(coeff);

                }



                if (coeff_index + zero_run > 64) {

                    av_log(s->avctx, AV_LOG_DEBUG, "Invalid zero run of %d with"

                           " %d coeffs left\n", zero_run, 64-coeff_index);

                    zero_run = 64 - coeff_index;

                }



                // zero runs code multiple coefficients,

                // so don't try to decode coeffs for those higher levels

                for (i = coeff_index+1; i <= coeff_index+zero_run; i++)

                    s->num_coded_frags[plane][i]--;

                coeff_i++;

            }

    }



    if (blocks_ended > s->num_coded_frags[plane][coeff_index])

        av_log(s->avctx, AV_LOG_ERROR, "More blocks ended than coded!\n");



    // decrement the number of blocks that have higher coeffecients for each

    // EOB run at this level

    if (blocks_ended)

        for (i = coeff_index+1; i < 64; i++)

            s->num_coded_frags[plane][i] -= blocks_ended;



    // setup the next buffer

    if (plane < 2)

        s->dct_tokens[plane+1][coeff_index] = dct_tokens + j;

    else if (coeff_index < 63)

        s->dct_tokens[0][coeff_index+1] = dct_tokens + j;



    return eob_run;

}

int ff_copy_whitelists(AVFormatContext *dst, AVFormatContext *src)

{

    av_assert0(!dst->codec_whitelist && !dst->format_whitelist);

    dst-> codec_whitelist = av_strdup(src->codec_whitelist);

    dst->format_whitelist = av_strdup(src->format_whitelist);

    if (   (src-> codec_whitelist && !dst-> codec_whitelist)

        || (src->format_whitelist && !dst->format_whitelist)) {

        av_log(dst, AV_LOG_ERROR, "Failed to duplicate whitelist\n");

        return AVERROR(ENOMEM);

    }

    return 0;

}

static void init_dequant4_coeff_table(H264Context *h){

    int i,j,q,x;

    const int transpose = (h->h264dsp.h264_idct_add != ff_h264_idct_add_c); //FIXME ugly

    for(i=0; i<6; i++ ){

        h->dequant4_coeff[i] = h->dequant4_buffer[i];

        for(j=0; j<i; j++){

            if(!memcmp(h->pps.scaling_matrix4[j], h->pps.scaling_matrix4[i], 16*sizeof(uint8_t))){

                h->dequant4_coeff[i] = h->dequant4_buffer[j];

                break;

            }

        }

        if(j<i)

            continue;



        for(q=0; q<52; q++){

            int shift = div6[q] + 2;

            int idx = rem6[q];

            for(x=0; x<16; x++)

                h->dequant4_coeff[i][q][transpose ? (x>>2)|((x<<2)&0xF) : x] =

                    ((uint32_t)dequant4_coeff_init[idx][(x&1) + ((x>>2)&1)] *

                    h->pps.scaling_matrix4[i][x]) << shift;

        }

    }

}

static int mpeg_mux_write_packet(AVFormatContext *ctx, AVPacket *pkt)

{

    MpegMuxContext *s = ctx->priv_data;

    int stream_index= pkt->stream_index;

    int size= pkt->size;

    uint8_t *buf= pkt->data;

    AVStream *st = ctx->streams[stream_index];

    StreamInfo *stream = st->priv_data;

    int64_t pts, dts, new_start_pts, new_start_dts;

    int len, avail_size;



    //XXX/FIXME this is and always was broken

//    compute_pts_dts(st, &pts, &dts, pkt->pts);



    pts= pkt->pts;

    dts= pkt->dts;



    if(s->is_svcd) {

        /* offset pts and dts slightly into the future to be able

           to do the compatibility fix below.*/

        pts = (pts + 2) & ((1LL << 33) - 1);

        dts = (dts + 2) & ((1LL << 33) - 1);



        if (stream->packet_number == 0 && dts == pts)

            /* For the very first packet we want to force the DTS to be included.

               This increases compatibility with lots of DVD players.

               Since the MPEG-2 standard mandates that DTS is only written when

               it is different from PTS we have to move it slightly into the past.*/

            dts = (dts - 2) & ((1LL << 33) - 1);

    }

    if(s->is_vcd) {

        /* We have to offset the PTS, so that it is consistent with the SCR.

           SCR starts at 36000, but the first two packs contain only padding

           and the first pack from the other stream, respectively, may also have

           been written before.

           So the real data starts at SCR 36000+3*1200. */

        pts = (pts + 36000 + 3600) & ((1LL << 33) - 1);

        dts = (dts + 36000 + 3600) & ((1LL << 33) - 1);

    }



#if 0

    update_scr(ctx,stream_index,pts);



    printf("%d: pts=%0.3f dts=%0.3f scr=%0.3f\n", 

           stream_index, 

           pts / 90000.0, 

           dts / 90000.0, 

           s->last_scr / 90000.0);

#endif



    /* we assume here that pts != AV_NOPTS_VALUE */

    new_start_pts = stream->start_pts;

    new_start_dts = stream->start_dts;



    if (stream->start_pts == AV_NOPTS_VALUE) {

        new_start_pts = pts;

        new_start_dts = dts;

    }

    avail_size = get_packet_payload_size(ctx, stream_index,

                                         new_start_pts, 

                                         new_start_dts);

    if (stream->buffer_ptr >= avail_size) {



        update_scr(ctx,stream_index,stream->start_pts);



        /* unlikely case: outputing the pts or dts increase the packet

           size so that we cannot write the start of the next

           packet. In this case, we must flush the current packet with

           padding.

           Note: this always happens for the first audio and video packet

           in a VCD file, since they do not carry any data.*/

        flush_packet(ctx, stream_index,

                     stream->start_pts, stream->start_dts, s->last_scr);

        stream->buffer_ptr = 0;

    }

    stream->start_pts = new_start_pts;

    stream->start_dts = new_start_dts;

    stream->nb_frames++;

    if (stream->frame_start_offset == 0)

        stream->frame_start_offset = stream->buffer_ptr;

    while (size > 0) {

        avail_size = get_packet_payload_size(ctx, stream_index,

                                             stream->start_pts, 

                                             stream->start_dts);

        len = avail_size - stream->buffer_ptr;

        if (len > size)

            len = size;

        memcpy(stream->buffer + stream->buffer_ptr, buf, len);

        stream->buffer_ptr += len;

        buf += len;

        size -= len;

        if (stream->buffer_ptr >= avail_size) {



            update_scr(ctx,stream_index,stream->start_pts);



            /* if packet full, we send it now */

            flush_packet(ctx, stream_index,

                         stream->start_pts, stream->start_dts, s->last_scr);

            stream->buffer_ptr = 0;



            if (s->is_vcd) {

                /* Write one or more padding sectors, if necessary, to reach

                   the constant overall bitrate.*/

                int vcd_pad_bytes;



                while((vcd_pad_bytes = get_vcd_padding_size(ctx,stream->start_pts) ) >= s->packet_size)

                    put_vcd_padding_sector(ctx);

            }



            /* Make sure only the FIRST pes packet for this frame has

               a timestamp */

            stream->start_pts = AV_NOPTS_VALUE;

            stream->start_dts = AV_NOPTS_VALUE;

        }

    }



    return 0;

}

SwsFilter *sws_getDefaultFilter(float lumaGBlur, float chromaGBlur,

                                float lumaSharpen, float chromaSharpen,

                                float chromaHShift, float chromaVShift,

                                int verbose)

{

    SwsFilter *filter = av_malloc(sizeof(SwsFilter));

    if (!filter)

        return NULL;



    if (lumaGBlur != 0.0) {

        filter->lumH = sws_getGaussianVec(lumaGBlur, 3.0);

        filter->lumV = sws_getGaussianVec(lumaGBlur, 3.0);

    } else {

        filter->lumH = sws_getIdentityVec();

        filter->lumV = sws_getIdentityVec();

    }



    if (chromaGBlur != 0.0) {

        filter->chrH = sws_getGaussianVec(chromaGBlur, 3.0);

        filter->chrV = sws_getGaussianVec(chromaGBlur, 3.0);

    } else {

        filter->chrH = sws_getIdentityVec();

        filter->chrV = sws_getIdentityVec();

    }



    if (!filter->lumH || !filter->lumV || !filter->chrH || !filter->chrV) {

        sws_freeVec(filter->lumH);

        sws_freeVec(filter->lumV);

        sws_freeVec(filter->chrH);

        sws_freeVec(filter->chrV);

        av_freep(&filter);

        return NULL;

    }



    if (chromaSharpen != 0.0) {

        SwsVector *id = sws_getIdentityVec();

        sws_scaleVec(filter->chrH, -chromaSharpen);

        sws_scaleVec(filter->chrV, -chromaSharpen);

        sws_addVec(filter->chrH, id);

        sws_addVec(filter->chrV, id);

        sws_freeVec(id);

    }



    if (lumaSharpen != 0.0) {

        SwsVector *id = sws_getIdentityVec();

        sws_scaleVec(filter->lumH, -lumaSharpen);

        sws_scaleVec(filter->lumV, -lumaSharpen);

        sws_addVec(filter->lumH, id);

        sws_addVec(filter->lumV, id);

        sws_freeVec(id);

    }



    if (chromaHShift != 0.0)

        sws_shiftVec(filter->chrH, (int)(chromaHShift + 0.5));



    if (chromaVShift != 0.0)

        sws_shiftVec(filter->chrV, (int)(chromaVShift + 0.5));



    sws_normalizeVec(filter->chrH, 1.0);

    sws_normalizeVec(filter->chrV, 1.0);

    sws_normalizeVec(filter->lumH, 1.0);

    sws_normalizeVec(filter->lumV, 1.0);



    if (verbose)

        sws_printVec2(filter->chrH, NULL, AV_LOG_DEBUG);

    if (verbose)

        sws_printVec2(filter->lumH, NULL, AV_LOG_DEBUG);



    return filter;

}

static int decode_frame(AVCodecContext * avctx, void *data, int *data_size,

                        AVPacket *avpkt)

{

    const uint8_t *buf  = avpkt->data;

    int buf_size        = avpkt->size;

    MPADecodeContext *s = avctx->priv_data;

    uint32_t header;

    int out_size;

    OUT_INT *out_samples = data;



    if (buf_size < HEADER_SIZE)

        return AVERROR_INVALIDDATA;



    header = AV_RB32(buf);

    if (ff_mpa_check_header(header) < 0) {

        av_log(avctx, AV_LOG_ERROR, "Header missing\n");

        return AVERROR_INVALIDDATA;

    }



    if (avpriv_mpegaudio_decode_header((MPADecodeHeader *)s, header) == 1) {

        /* free format: prepare to compute frame size */

        s->frame_size = -1;

        return AVERROR_INVALIDDATA;

    }

    /* update codec info */

    avctx->channels       = s->nb_channels;

    avctx->channel_layout = s->nb_channels == 1 ? AV_CH_LAYOUT_MONO : AV_CH_LAYOUT_STEREO;

    if (!avctx->bit_rate)

        avctx->bit_rate = s->bit_rate;

    avctx->sub_id = s->layer;



    if (*data_size < 1152 * avctx->channels * sizeof(OUT_INT))

        return AVERROR(EINVAL);

    *data_size = 0;



    if (s->frame_size <= 0 || s->frame_size > buf_size) {

        av_log(avctx, AV_LOG_ERROR, "incomplete frame\n");

        return AVERROR_INVALIDDATA;

    } else if (s->frame_size < buf_size) {

        av_log(avctx, AV_LOG_ERROR, "incorrect frame size\n");

        buf_size= s->frame_size;

    }



    out_size = mp_decode_frame(s, out_samples, buf, buf_size);

    if (out_size >= 0) {

        *data_size         = out_size;

        avctx->sample_rate = s->sample_rate;

        //FIXME maybe move the other codec info stuff from above here too

    } else {

        av_log(avctx, AV_LOG_ERROR, "Error while decoding MPEG audio frame.\n");

        /* Only return an error if the bad frame makes up the whole packet.

           If there is more data in the packet, just consume the bad frame

           instead of returning an error, which would discard the whole

           packet. */

        if (buf_size == avpkt->size)

            return out_size;

    }

    s->frame_size = 0;

    return buf_size;

}

