static inline void mix_2f_2r_to_stereo(AC3DecodeContext *ctx)

{

    int i;

    float (*output)[256] = ctx->audio_block.block_output;



    for (i = 0; i < 256; i++) {

        output[1][i] += output[3][i];

        output[2][i] += output[4][i];

    }

    memset(output[3], 0, sizeof(output[3]));

    memset(output[4], 0, sizeof(output[4]));

}

static int segment_start(AVFormatContext *s)

{

    SegmentContext *seg = s->priv_data;

    AVFormatContext *oc = seg->avf;

    int err = 0;



    if (seg->wrap)

        seg->number %= seg->wrap;



    if (av_get_frame_filename(oc->filename, sizeof(oc->filename),

                              s->filename, seg->number++) < 0)

        return AVERROR(EINVAL);



    if ((err = avio_open2(&oc->pb, oc->filename, AVIO_FLAG_WRITE,

                          &s->interrupt_callback, NULL)) < 0)

        return err;



    if (!oc->priv_data && oc->oformat->priv_data_size > 0) {

        oc->priv_data = av_mallocz(oc->oformat->priv_data_size);

        if (!oc->priv_data) {

            avio_close(oc->pb);

            return AVERROR(ENOMEM);

        }

        if (oc->oformat->priv_class) {

            *(const AVClass**)oc->priv_data = oc->oformat->priv_class;

            av_opt_set_defaults(oc->priv_data);

        }

    }



    if ((err = oc->oformat->write_header(oc)) < 0) {

        goto fail;

    }



    return 0;



fail:

    av_log(oc, AV_LOG_ERROR, "Failure occurred when starting segment '%s'\n",

           oc->filename);

    avio_close(oc->pb);

    av_freep(&oc->priv_data);



    return err;

}

static int put_image(struct vf_instance *vf, mp_image_t *mpi, double pts)

{

    mp_image_t *dmpi;

    if (vf->priv->in.fmt == vf->priv->out.fmt) { //nothing to do

        dmpi = mpi;

    } else {

        int out_off_left, out_off_right;

        int in_off_left  = vf->priv->in.row_left   * mpi->stride[0]  +

                           vf->priv->in.off_left;

        int in_off_right = vf->priv->in.row_right  * mpi->stride[0]  +

                           vf->priv->in.off_right;



        dmpi = ff_vf_get_image(vf->next, IMGFMT_RGB24, MP_IMGTYPE_TEMP,

                            MP_IMGFLAG_ACCEPT_STRIDE,

                            vf->priv->out.width, vf->priv->out.height);

        out_off_left   = vf->priv->out.row_left  * dmpi->stride[0] +

                         vf->priv->out.off_left;

        out_off_right  = vf->priv->out.row_right * dmpi->stride[0] +

                         vf->priv->out.off_right;



        switch (vf->priv->out.fmt) {

        case SIDE_BY_SIDE_LR:

        case SIDE_BY_SIDE_RL:

        case SIDE_BY_SIDE_2_LR:

        case SIDE_BY_SIDE_2_RL:

        case ABOVE_BELOW_LR:

        case ABOVE_BELOW_RL:

        case ABOVE_BELOW_2_LR:

        case ABOVE_BELOW_2_RL:

        case INTERLEAVE_ROWS_LR:

        case INTERLEAVE_ROWS_RL:

            memcpy_pic2(dmpi->planes[0] + out_off_left,

                       mpi->planes[0] + in_off_left,

                       3 * vf->priv->width,

                       vf->priv->height,

                       dmpi->stride[0] * vf->priv->row_step,

                       mpi->stride[0] * vf->priv->row_step,

                       vf->priv->row_step != 1);

            memcpy_pic2(dmpi->planes[0] + out_off_right,

                       mpi->planes[0] + in_off_right,

                       3 * vf->priv->width,

                       vf->priv->height,

                       dmpi->stride[0] * vf->priv->row_step,

                       mpi->stride[0] * vf->priv->row_step,

                       vf->priv->row_step != 1);

            break;

        case MONO_L:

        case MONO_R:

            memcpy_pic(dmpi->planes[0],

                       mpi->planes[0] + in_off_left,

                       3 * vf->priv->width,

                       vf->priv->height,

                       dmpi->stride[0],

                       mpi->stride[0]);

            break;

        case ANAGLYPH_RC_GRAY:

        case ANAGLYPH_RC_HALF:

        case ANAGLYPH_RC_COLOR:

        case ANAGLYPH_RC_DUBOIS:

        case ANAGLYPH_GM_GRAY:

        case ANAGLYPH_GM_HALF:

        case ANAGLYPH_GM_COLOR:

        case ANAGLYPH_YB_GRAY:

        case ANAGLYPH_YB_HALF:

        case ANAGLYPH_YB_COLOR: {

            int i,x,y,il,ir,o;

            unsigned char *source     = mpi->planes[0];

            unsigned char *dest       = dmpi->planes[0];

            unsigned int   out_width  = vf->priv->out.width;

            int           *ana_matrix[3];



            for(i = 0; i < 3; i++)

                ana_matrix[i] = vf->priv->ana_matrix[i];



            for (y = 0; y < vf->priv->out.height; y++) {

                o   = dmpi->stride[0] * y;

                il  = in_off_left  + y * mpi->stride[0];

                ir  = in_off_right + y * mpi->stride[0];

                for (x = 0; x < out_width; x++) {

                    dest[o    ]  = ana_convert(

                                   ana_matrix[0], source + il, source + ir); //red out

                    dest[o + 1]  = ana_convert(

                                   ana_matrix[1], source + il, source + ir); //green out

                    dest[o + 2]  = ana_convert(

                                   ana_matrix[2], source + il, source + ir); //blue out

                    il += 3;

                    ir += 3;

                    o  += 3;

                }

            }

            break;

        }

        default:

            ff_mp_msg(MSGT_VFILTER, MSGL_WARN,

                   "[stereo3d] stereo format of output is not supported\n");

            return 0;

            break;

        }

    }

    return ff_vf_next_put_image(vf, dmpi, pts);

}

static int udp_open(URLContext *h, const char *uri, int flags)

{

    char hostname[1024], localaddr[1024] = "";

    int port, udp_fd = -1, tmp, bind_ret = -1;

    UDPContext *s = h->priv_data;

    int is_output;

    const char *p;

    char buf[256];

    struct sockaddr_storage my_addr;

    int len;

    int reuse_specified = 0;

    int i, include = 0, num_sources = 0;

    char *sources[32];



    h->is_streamed = 1;

    h->max_packet_size = 1472;



    is_output = !(flags & AVIO_FLAG_READ);



    s->ttl = 16;

    s->buffer_size = is_output ? UDP_TX_BUF_SIZE : UDP_MAX_PKT_SIZE;



    s->circular_buffer_size = 7*188*4096;



    p = strchr(uri, '?');

    if (p) {

        if (av_find_info_tag(buf, sizeof(buf), "reuse", p)) {

            char *endptr = NULL;

            s->reuse_socket = strtol(buf, &endptr, 10);

            /* assume if no digits were found it is a request to enable it */

            if (buf == endptr)

                s->reuse_socket = 1;

            reuse_specified = 1;

        }

        if (av_find_info_tag(buf, sizeof(buf), "overrun_nonfatal", p)) {

            char *endptr = NULL;

            s->overrun_nonfatal = strtol(buf, &endptr, 10);

            /* assume if no digits were found it is a request to enable it */

            if (buf == endptr)

                s->overrun_nonfatal = 1;





        }

        if (av_find_info_tag(buf, sizeof(buf), "ttl", p)) {

            s->ttl = strtol(buf, NULL, 10);

        }

        if (av_find_info_tag(buf, sizeof(buf), "localport", p)) {

            s->local_port = strtol(buf, NULL, 10);

        }

        if (av_find_info_tag(buf, sizeof(buf), "pkt_size", p)) {

            h->max_packet_size = strtol(buf, NULL, 10);

        }

        if (av_find_info_tag(buf, sizeof(buf), "buffer_size", p)) {

            s->buffer_size = strtol(buf, NULL, 10);

        }

        if (av_find_info_tag(buf, sizeof(buf), "connect", p)) {

            s->is_connected = strtol(buf, NULL, 10);

        }

        if (av_find_info_tag(buf, sizeof(buf), "fifo_size", p)) {

            s->circular_buffer_size = strtol(buf, NULL, 10)*188;



                       "'circular_buffer_size' option was set but it is not supported "


        }

        if (av_find_info_tag(buf, sizeof(buf), "localaddr", p)) {

            av_strlcpy(localaddr, buf, sizeof(localaddr));

        }

        if (av_find_info_tag(buf, sizeof(buf), "sources", p))

            include = 1;

        if (include || av_find_info_tag(buf, sizeof(buf), "block", p)) {

            char *source_start;



            source_start = buf;

            while (1) {

                char *next = strchr(source_start, ',');

                if (next)

                    *next = '\0';

                sources[num_sources] = av_strdup(source_start);

                if (!sources[num_sources])

                    goto fail;

                source_start = next + 1;

                num_sources++;

                if (num_sources >= FF_ARRAY_ELEMS(sources) || !next)

                    break;

            }

        }

    }



    /* fill the dest addr */

    av_url_split(NULL, 0, NULL, 0, hostname, sizeof(hostname), &port, NULL, 0, uri);



    /* XXX: fix av_url_split */

    if (hostname[0] == '\0' || hostname[0] == '?') {

        /* only accepts null hostname if input */

        if (!(flags & AVIO_FLAG_READ))

            goto fail;

    } else {

        if (ff_udp_set_remote_url(h, uri) < 0)

            goto fail;

    }



    if ((s->is_multicast || !s->local_port) && (h->flags & AVIO_FLAG_READ))

        s->local_port = port;

    udp_fd = udp_socket_create(s, &my_addr, &len, localaddr);

    if (udp_fd < 0)

        goto fail;



    /* Follow the requested reuse option, unless it's multicast in which

     * case enable reuse unless explicitly disabled.

     */

    if (s->reuse_socket || (s->is_multicast && !reuse_specified)) {

        s->reuse_socket = 1;

        if (setsockopt (udp_fd, SOL_SOCKET, SO_REUSEADDR, &(s->reuse_socket), sizeof(s->reuse_socket)) != 0)

            goto fail;

    }



    /* If multicast, try binding the multicast address first, to avoid

     * receiving UDP packets from other sources aimed at the same UDP

     * port. This fails on windows. This makes sending to the same address

     * using sendto() fail, so only do it if we're opened in read-only mode. */

    if (s->is_multicast && !(h->flags & AVIO_FLAG_WRITE)) {

        bind_ret = bind(udp_fd,(struct sockaddr *)&s->dest_addr, len);

    }

    /* bind to the local address if not multicast or if the multicast

     * bind failed */

    /* the bind is needed to give a port to the socket now */

    if (bind_ret < 0 && bind(udp_fd,(struct sockaddr *)&my_addr, len) < 0) {

        log_net_error(h, AV_LOG_ERROR, "bind failed");

        goto fail;

    }



    len = sizeof(my_addr);

    getsockname(udp_fd, (struct sockaddr *)&my_addr, &len);

    s->local_port = udp_port(&my_addr, len);



    if (s->is_multicast) {

        if (h->flags & AVIO_FLAG_WRITE) {

            /* output */

            if (udp_set_multicast_ttl(udp_fd, s->ttl, (struct sockaddr *)&s->dest_addr) < 0)

                goto fail;

        }

        if (h->flags & AVIO_FLAG_READ) {

            /* input */

            if (num_sources == 0 || !include) {

                if (udp_join_multicast_group(udp_fd, (struct sockaddr *)&s->dest_addr) < 0)

                    goto fail;



                if (num_sources) {

                    if (udp_set_multicast_sources(udp_fd, (struct sockaddr *)&s->dest_addr, s->dest_addr_len, sources, num_sources, 0) < 0)

                        goto fail;

                }

            } else if (include && num_sources) {

                if (udp_set_multicast_sources(udp_fd, (struct sockaddr *)&s->dest_addr, s->dest_addr_len, sources, num_sources, 1) < 0)

                    goto fail;

            } else {

                av_log(NULL, AV_LOG_ERROR, "invalid udp settings: inclusive multicast but no sources given\n");

                goto fail;

            }

        }

    }



    if (is_output) {

        /* limit the tx buf size to limit latency */

        tmp = s->buffer_size;

        if (setsockopt(udp_fd, SOL_SOCKET, SO_SNDBUF, &tmp, sizeof(tmp)) < 0) {

            log_net_error(h, AV_LOG_ERROR, "setsockopt(SO_SNDBUF)");

            goto fail;

        }

    } else {

        /* set udp recv buffer size to the largest possible udp packet size to

         * avoid losing data on OSes that set this too low by default. */

        tmp = s->buffer_size;

        if (setsockopt(udp_fd, SOL_SOCKET, SO_RCVBUF, &tmp, sizeof(tmp)) < 0) {

            log_net_error(h, AV_LOG_WARNING, "setsockopt(SO_RECVBUF)");

        }

        /* make the socket non-blocking */

        ff_socket_nonblock(udp_fd, 1);

    }

    if (s->is_connected) {

        if (connect(udp_fd, (struct sockaddr *) &s->dest_addr, s->dest_addr_len)) {

            log_net_error(h, AV_LOG_ERROR, "connect");

            goto fail;

        }

    }



    for (i = 0; i < num_sources; i++)

        av_freep(&sources[i]);



    s->udp_fd = udp_fd;



#if HAVE_PTHREAD_CANCEL

    if (!is_output && s->circular_buffer_size) {

        int ret;



        /* start the task going */

        s->fifo = av_fifo_alloc(s->circular_buffer_size);

        ret = pthread_mutex_init(&s->mutex, NULL);

        if (ret != 0) {

            av_log(h, AV_LOG_ERROR, "pthread_mutex_init failed : %s\n", strerror(ret));

            goto fail;

        }

        ret = pthread_cond_init(&s->cond, NULL);

        if (ret != 0) {

            av_log(h, AV_LOG_ERROR, "pthread_cond_init failed : %s\n", strerror(ret));

            goto cond_fail;

        }

        ret = pthread_create(&s->circular_buffer_thread, NULL, circular_buffer_task, h);

        if (ret != 0) {

            av_log(h, AV_LOG_ERROR, "pthread_create failed : %s\n", strerror(ret));

            goto thread_fail;

        }

        s->thread_started = 1;

    }

#endif



    return 0;

#if HAVE_PTHREAD_CANCEL

 thread_fail:

    pthread_cond_destroy(&s->cond);

 cond_fail:

    pthread_mutex_destroy(&s->mutex);

#endif

 fail:

    if (udp_fd >= 0)

        closesocket(udp_fd);

    av_fifo_free(s->fifo);

    for (i = 0; i < num_sources; i++)

        av_freep(&sources[i]);

    return AVERROR(EIO);

}

static int vc1_decode_frame(AVCodecContext *avctx, void *data,

                            int *data_size, AVPacket *avpkt)

{

    const uint8_t *buf = avpkt->data;

    int buf_size = avpkt->size, n_slices = 0, i;

    VC1Context *v = avctx->priv_data;

    MpegEncContext *s = &v->s;

    AVFrame *pict = data;

    uint8_t *buf2 = NULL;

    const uint8_t *buf_start = buf;

    int mb_height, n_slices1;

    struct {

        uint8_t *buf;

        GetBitContext gb;

        int mby_start;

    } *slices = NULL, *tmp;



    /* no supplementary picture */

    if (buf_size == 0 || (buf_size == 4 && AV_RB32(buf) == VC1_CODE_ENDOFSEQ)) {

        /* special case for last picture */

        if (s->low_delay == 0 && s->next_picture_ptr) {

            *pict = s->next_picture_ptr->f;

            s->next_picture_ptr = NULL;



            *data_size = sizeof(AVFrame);

        }



        return 0;

    }



    if (s->avctx->codec->capabilities&CODEC_CAP_HWACCEL_VDPAU) {

        if (v->profile < PROFILE_ADVANCED)

            avctx->pix_fmt = AV_PIX_FMT_VDPAU_WMV3;

        else

            avctx->pix_fmt = AV_PIX_FMT_VDPAU_VC1;

    }



    //for advanced profile we may need to parse and unescape data

    if (avctx->codec_id == AV_CODEC_ID_VC1 || avctx->codec_id == AV_CODEC_ID_VC1IMAGE) {

        int buf_size2 = 0;

        buf2 = av_mallocz(buf_size + FF_INPUT_BUFFER_PADDING_SIZE);



        if (IS_MARKER(AV_RB32(buf))) { /* frame starts with marker and needs to be parsed */

            const uint8_t *start, *end, *next;

            int size;



            next = buf;

            for (start = buf, end = buf + buf_size; next < end; start = next) {

                next = find_next_marker(start + 4, end);

                size = next - start - 4;

                if (size <= 0) continue;

                switch (AV_RB32(start)) {

                case VC1_CODE_FRAME:

                    if (avctx->hwaccel ||

                        s->avctx->codec->capabilities&CODEC_CAP_HWACCEL_VDPAU)

                        buf_start = start;

                    buf_size2 = vc1_unescape_buffer(start + 4, size, buf2);

                    break;

                case VC1_CODE_FIELD: {

                    int buf_size3;

                    tmp = av_realloc(slices, sizeof(*slices) * (n_slices+1));

                    if (!tmp)

                        goto err;

                    slices = tmp;

                    slices[n_slices].buf = av_mallocz(buf_size + FF_INPUT_BUFFER_PADDING_SIZE);

                    if (!slices[n_slices].buf)

                        goto err;

                    buf_size3 = vc1_unescape_buffer(start + 4, size,

                                                    slices[n_slices].buf);

                    init_get_bits(&slices[n_slices].gb, slices[n_slices].buf,

                                  buf_size3 << 3);

                    /* assuming that the field marker is at the exact middle,

                       hope it's correct */

                    slices[n_slices].mby_start = s->mb_height >> 1;

                    n_slices1 = n_slices - 1; // index of the last slice of the first field

                    n_slices++;

                    break;

                }

                case VC1_CODE_ENTRYPOINT: /* it should be before frame data */

                    buf_size2 = vc1_unescape_buffer(start + 4, size, buf2);

                    init_get_bits(&s->gb, buf2, buf_size2 * 8);

                    ff_vc1_decode_entry_point(avctx, v, &s->gb);

                    break;

                case VC1_CODE_SLICE: {

                    int buf_size3;

                    tmp = av_realloc(slices, sizeof(*slices) * (n_slices+1));

                    if (!tmp)

                        goto err;

                    slices = tmp;

                    slices[n_slices].buf = av_mallocz(buf_size + FF_INPUT_BUFFER_PADDING_SIZE);

                    if (!slices[n_slices].buf)

                        goto err;

                    buf_size3 = vc1_unescape_buffer(start + 4, size,

                                                    slices[n_slices].buf);

                    init_get_bits(&slices[n_slices].gb, slices[n_slices].buf,

                                  buf_size3 << 3);

                    slices[n_slices].mby_start = get_bits(&slices[n_slices].gb, 9);

                    n_slices++;

                    break;

                }

                }

            }

        } else if (v->interlace && ((buf[0] & 0xC0) == 0xC0)) { /* WVC1 interlaced stores both fields divided by marker */

            const uint8_t *divider;

            int buf_size3;



            divider = find_next_marker(buf, buf + buf_size);

            if ((divider == (buf + buf_size)) || AV_RB32(divider) != VC1_CODE_FIELD) {

                av_log(avctx, AV_LOG_ERROR, "Error in WVC1 interlaced frame\n");

                goto err;

            } else { // found field marker, unescape second field

                tmp = av_realloc(slices, sizeof(*slices) * (n_slices+1));

                if (!tmp)

                    goto err;

                slices = tmp;

                slices[n_slices].buf = av_mallocz(buf_size + FF_INPUT_BUFFER_PADDING_SIZE);

                if (!slices[n_slices].buf)

                    goto err;

                buf_size3 = vc1_unescape_buffer(divider + 4, buf + buf_size - divider - 4, slices[n_slices].buf);

                init_get_bits(&slices[n_slices].gb, slices[n_slices].buf,

                              buf_size3 << 3);

                slices[n_slices].mby_start = s->mb_height >> 1;

                n_slices1 = n_slices - 1;

                n_slices++;

            }

            buf_size2 = vc1_unescape_buffer(buf, divider - buf, buf2);

        } else {

            buf_size2 = vc1_unescape_buffer(buf, buf_size, buf2);

        }

        init_get_bits(&s->gb, buf2, buf_size2*8);

    } else

        init_get_bits(&s->gb, buf, buf_size*8);



    if (v->res_sprite) {

        v->new_sprite  = !get_bits1(&s->gb);

        v->two_sprites =  get_bits1(&s->gb);

        /* res_sprite means a Windows Media Image stream, AV_CODEC_ID_*IMAGE means

           we're using the sprite compositor. These are intentionally kept separate

           so you can get the raw sprites by using the wmv3 decoder for WMVP or

           the vc1 one for WVP2 */

        if (avctx->codec_id == AV_CODEC_ID_WMV3IMAGE || avctx->codec_id == AV_CODEC_ID_VC1IMAGE) {

            if (v->new_sprite) {

                // switch AVCodecContext parameters to those of the sprites

                avctx->width  = avctx->coded_width  = v->sprite_width;

                avctx->height = avctx->coded_height = v->sprite_height;

            } else {

                goto image;

            }

        }

    }



    if (s->context_initialized &&

        (s->width  != avctx->coded_width ||

         s->height != avctx->coded_height)) {

        ff_vc1_decode_end(avctx);

    }



    if (!s->context_initialized) {

        if (ff_msmpeg4_decode_init(avctx) < 0 || ff_vc1_decode_init_alloc_tables(v) < 0)

            return -1;



        s->low_delay = !avctx->has_b_frames || v->res_sprite;



        if (v->profile == PROFILE_ADVANCED) {

            s->h_edge_pos = avctx->coded_width;

            s->v_edge_pos = avctx->coded_height;

        }

    }



    /* We need to set current_picture_ptr before reading the header,

     * otherwise we cannot store anything in there. */

    if (s->current_picture_ptr == NULL || s->current_picture_ptr->f.data[0]) {

        int i = ff_find_unused_picture(s, 0);

        if (i < 0)

            goto err;

        s->current_picture_ptr = &s->picture[i];

    }



    // do parse frame header

    v->pic_header_flag = 0;

    if (v->profile < PROFILE_ADVANCED) {

        if (ff_vc1_parse_frame_header(v, &s->gb) == -1) {

            goto err;

        }

    } else {

        if (ff_vc1_parse_frame_header_adv(v, &s->gb) == -1) {

            goto err;

        }

    }



    if ((avctx->codec_id == AV_CODEC_ID_WMV3IMAGE || avctx->codec_id == AV_CODEC_ID_VC1IMAGE)

        && s->pict_type != AV_PICTURE_TYPE_I) {

        av_log(v->s.avctx, AV_LOG_ERROR, "Sprite decoder: expected I-frame\n");

        goto err;

    }



    // process pulldown flags

    s->current_picture_ptr->f.repeat_pict = 0;

    // Pulldown flags are only valid when 'broadcast' has been set.

    // So ticks_per_frame will be 2

    if (v->rff) {

        // repeat field

        s->current_picture_ptr->f.repeat_pict = 1;

    } else if (v->rptfrm) {

        // repeat frames

        s->current_picture_ptr->f.repeat_pict = v->rptfrm * 2;

    }



    // for skipping the frame

    s->current_picture.f.pict_type = s->pict_type;

    s->current_picture.f.key_frame = s->pict_type == AV_PICTURE_TYPE_I;



    /* skip B-frames if we don't have reference frames */

    if (s->last_picture_ptr == NULL && (s->pict_type == AV_PICTURE_TYPE_B || s->dropable)) {

        goto err;

    }

    if ((avctx->skip_frame >= AVDISCARD_NONREF && s->pict_type == AV_PICTURE_TYPE_B) ||

        (avctx->skip_frame >= AVDISCARD_NONKEY && s->pict_type != AV_PICTURE_TYPE_I) ||

         avctx->skip_frame >= AVDISCARD_ALL) {

        goto end;

    }



    if (s->next_p_frame_damaged) {

        if (s->pict_type == AV_PICTURE_TYPE_B)

            goto end;

        else

            s->next_p_frame_damaged = 0;

    }



    if (ff_MPV_frame_start(s, avctx) < 0) {

        goto err;

    }



    s->me.qpel_put = s->dsp.put_qpel_pixels_tab;

    s->me.qpel_avg = s->dsp.avg_qpel_pixels_tab;



    if ((CONFIG_VC1_VDPAU_DECODER)

        &&s->avctx->codec->capabilities&CODEC_CAP_HWACCEL_VDPAU)

        ff_vdpau_vc1_decode_picture(s, buf_start, (buf + buf_size) - buf_start);

    else if (avctx->hwaccel) {

        if (avctx->hwaccel->start_frame(avctx, buf, buf_size) < 0)

            goto err;

        if (avctx->hwaccel->decode_slice(avctx, buf_start, (buf + buf_size) - buf_start) < 0)

            goto err;

        if (avctx->hwaccel->end_frame(avctx) < 0)

            goto err;

    } else {

        ff_er_frame_start(s);



        v->bits = buf_size * 8;

        v->end_mb_x = s->mb_width;

        if (v->field_mode) {

            uint8_t *tmp[2];

            s->current_picture.f.linesize[0] <<= 1;

            s->current_picture.f.linesize[1] <<= 1;

            s->current_picture.f.linesize[2] <<= 1;

            s->linesize                      <<= 1;

            s->uvlinesize                    <<= 1;

            tmp[0]          = v->mv_f_last[0];

            tmp[1]          = v->mv_f_last[1];

            v->mv_f_last[0] = v->mv_f_next[0];

            v->mv_f_last[1] = v->mv_f_next[1];

            v->mv_f_next[0] = v->mv_f[0];

            v->mv_f_next[1] = v->mv_f[1];

            v->mv_f[0] = tmp[0];

            v->mv_f[1] = tmp[1];

        }

        mb_height = s->mb_height >> v->field_mode;

        for (i = 0; i <= n_slices; i++) {

            if (i > 0 &&  slices[i - 1].mby_start >= mb_height) {

                if (v->field_mode <= 0) {

                    av_log(v->s.avctx, AV_LOG_ERROR, "Slice %d starts beyond "

                           "picture boundary (%d >= %d)\n", i,

                           slices[i - 1].mby_start, mb_height);

                    continue;

                }

                v->second_field = 1;

                v->blocks_off   = s->mb_width  * s->mb_height << 1;

                v->mb_off       = s->mb_stride * s->mb_height >> 1;

            } else {

                v->second_field = 0;

                v->blocks_off   = 0;

                v->mb_off       = 0;

            }

            if (i) {

                v->pic_header_flag = 0;

                if (v->field_mode && i == n_slices1 + 2) {

                    if (ff_vc1_parse_frame_header_adv(v, &s->gb) < 0) {

                        av_log(v->s.avctx, AV_LOG_ERROR, "Field header damaged\n");

                        continue;

                    }

                } else if (get_bits1(&s->gb)) {

                    v->pic_header_flag = 1;

                    if (ff_vc1_parse_frame_header_adv(v, &s->gb) < 0) {

                        av_log(v->s.avctx, AV_LOG_ERROR, "Slice header damaged\n");

                        continue;

                    }

                }

            }

            s->start_mb_y = (i == 0) ? 0 : FFMAX(0, slices[i-1].mby_start % mb_height);

            if (!v->field_mode || v->second_field)

                s->end_mb_y = (i == n_slices     ) ? mb_height : FFMIN(mb_height, slices[i].mby_start % mb_height);

            else

                s->end_mb_y = (i <= n_slices1 + 1) ? mb_height : FFMIN(mb_height, slices[i].mby_start % mb_height);

            ff_vc1_decode_blocks(v);

            if (i != n_slices)

                s->gb = slices[i].gb;

        }

        if (v->field_mode) {

            v->second_field = 0;

            if (s->pict_type == AV_PICTURE_TYPE_B) {

                memcpy(v->mv_f_base, v->mv_f_next_base,

                       2 * (s->b8_stride * (s->mb_height * 2 + 1) + s->mb_stride * (s->mb_height + 1) * 2));

            }

            s->current_picture.f.linesize[0] >>= 1;

            s->current_picture.f.linesize[1] >>= 1;

            s->current_picture.f.linesize[2] >>= 1;

            s->linesize                      >>= 1;

            s->uvlinesize                    >>= 1;

        }

        av_dlog(s->avctx, "Consumed %i/%i bits\n",

                get_bits_count(&s->gb), s->gb.size_in_bits);

//  if (get_bits_count(&s->gb) > buf_size * 8)

//      return -1;

        ff_er_frame_end(s);

    }



    ff_MPV_frame_end(s);



    if (avctx->codec_id == AV_CODEC_ID_WMV3IMAGE || avctx->codec_id == AV_CODEC_ID_VC1IMAGE) {

image:

        avctx->width  = avctx->coded_width  = v->output_width;

        avctx->height = avctx->coded_height = v->output_height;

        if (avctx->skip_frame >= AVDISCARD_NONREF)

            goto end;

#if CONFIG_WMV3IMAGE_DECODER || CONFIG_VC1IMAGE_DECODER

        if (vc1_decode_sprites(v, &s->gb))

            goto err;

#endif

        *pict      = v->sprite_output_frame;

        *data_size = sizeof(AVFrame);

    } else {

        if (s->pict_type == AV_PICTURE_TYPE_B || s->low_delay) {

            *pict = s->current_picture_ptr->f;

        } else if (s->last_picture_ptr != NULL) {

            *pict = s->last_picture_ptr->f;

        }

        if (s->last_picture_ptr || s->low_delay) {

            *data_size = sizeof(AVFrame);

            ff_print_debug_info(s, pict);

        }

    }



end:

    av_free(buf2);

    for (i = 0; i < n_slices; i++)

        av_free(slices[i].buf);

    av_free(slices);

    return buf_size;



err:

    av_free(buf2);

    for (i = 0; i < n_slices; i++)

        av_free(slices[i].buf);

    av_free(slices);

    return -1;

}

int ff_h263_decode_frame(AVCodecContext *avctx,

                             void *data, int *got_frame,

                             AVPacket *avpkt)

{

    const uint8_t *buf = avpkt->data;

    int buf_size = avpkt->size;

    MpegEncContext *s = avctx->priv_data;

    int ret;

    AVFrame *pict = data;



    s->flags= avctx->flags;

    s->flags2= avctx->flags2;



    /* no supplementary picture */

    if (buf_size == 0) {

        /* special case for last picture */

        if (s->low_delay==0 && s->next_picture_ptr) {

            if ((ret = av_frame_ref(pict, &s->next_picture_ptr->f)) < 0)

                return ret;

            s->next_picture_ptr= NULL;



            *got_frame = 1;

        }



        return 0;

    }



    if(s->flags&CODEC_FLAG_TRUNCATED){

        int next;



        if(CONFIG_MPEG4_DECODER && s->codec_id==AV_CODEC_ID_MPEG4){

            next= ff_mpeg4_find_frame_end(&s->parse_context, buf, buf_size);

        }else if(CONFIG_H263_DECODER && s->codec_id==AV_CODEC_ID_H263){

            next= ff_h263_find_frame_end(&s->parse_context, buf, buf_size);

        }else if(CONFIG_H263P_DECODER && s->codec_id==AV_CODEC_ID_H263P){

            next= ff_h263_find_frame_end(&s->parse_context, buf, buf_size);

        }else{

            av_log(s->avctx, AV_LOG_ERROR, "this codec does not support truncated bitstreams\n");

            return AVERROR(EINVAL);

        }



        if( ff_combine_frame(&s->parse_context, next, (const uint8_t **)&buf, &buf_size) < 0 )

            return buf_size;

    }





retry:

    if(s->divx_packed && s->bitstream_buffer_size){

        int i;

        for(i=0; i<buf_size-3; i++){

            if(buf[i]==0 && buf[i+1]==0 && buf[i+2]==1){

                if(buf[i+3]==0xB0){

                    av_log(s->avctx, AV_LOG_WARNING, "Discarding excessive bitstream in packed xvid\n");

                    s->bitstream_buffer_size=0;

                }

                break;

            }

        }

    }



    if(s->bitstream_buffer_size && (s->divx_packed || buf_size<20)){ //divx 5.01+/xvid frame reorder

        init_get_bits(&s->gb, s->bitstream_buffer, s->bitstream_buffer_size*8);

    }else

        init_get_bits(&s->gb, buf, buf_size*8);

    s->bitstream_buffer_size=0;



    if (!s->context_initialized) {

        if ((ret = ff_MPV_common_init(s)) < 0) //we need the idct permutaton for reading a custom matrix

            return ret;

    }



    /* We need to set current_picture_ptr before reading the header,

     * otherwise we cannot store anyting in there */

    if (s->current_picture_ptr == NULL || s->current_picture_ptr->f.data[0]) {

        int i= ff_find_unused_picture(s, 0);

        if (i < 0)

            return i;

        s->current_picture_ptr= &s->picture[i];

    }



    /* let's go :-) */

    if (CONFIG_WMV2_DECODER && s->msmpeg4_version==5) {

        ret= ff_wmv2_decode_picture_header(s);

    } else if (CONFIG_MSMPEG4_DECODER && s->msmpeg4_version) {

        ret = ff_msmpeg4_decode_picture_header(s);

    } else if (CONFIG_MPEG4_DECODER && s->h263_pred) {

        if(s->avctx->extradata_size && s->picture_number==0){

            GetBitContext gb;



            init_get_bits(&gb, s->avctx->extradata, s->avctx->extradata_size*8);

            ret = ff_mpeg4_decode_picture_header(s, &gb);

        }

        ret = ff_mpeg4_decode_picture_header(s, &s->gb);

    } else if (CONFIG_H263I_DECODER && s->codec_id == AV_CODEC_ID_H263I) {

        ret = ff_intel_h263_decode_picture_header(s);

    } else if (CONFIG_FLV_DECODER && s->h263_flv) {

        ret = ff_flv_decode_picture_header(s);

    } else {

        ret = ff_h263_decode_picture_header(s);

    }



    if (ret < 0 || ret==FRAME_SKIPPED) {

        if (   s->width  != avctx->coded_width

            || s->height != avctx->coded_height) {

                av_log(s->avctx, AV_LOG_WARNING, "Reverting picture dimensions change due to header decoding failure\n");

                s->width = avctx->coded_width;

                s->height= avctx->coded_height;

        }

    }

    if(ret==FRAME_SKIPPED) return get_consumed_bytes(s, buf_size);



    /* skip if the header was thrashed */

    if (ret < 0){

        av_log(s->avctx, AV_LOG_ERROR, "header damaged\n");

        return ret;

    }



    avctx->has_b_frames= !s->low_delay;



    if(s->xvid_build==-1 && s->divx_version==-1 && s->lavc_build==-1){

        if(s->stream_codec_tag == AV_RL32("XVID") ||

           s->codec_tag == AV_RL32("XVID") || s->codec_tag == AV_RL32("XVIX") ||

           s->codec_tag == AV_RL32("RMP4") || s->codec_tag == AV_RL32("ZMP4") ||

           s->codec_tag == AV_RL32("SIPP")

           )

            s->xvid_build= 0;

#if 0

        if(s->codec_tag == AV_RL32("DIVX") && s->vo_type==0 && s->vol_control_parameters==1

           && s->padding_bug_score > 0 && s->low_delay) // XVID with modified fourcc

            s->xvid_build= 0;

#endif

    }



    if(s->xvid_build==-1 && s->divx_version==-1 && s->lavc_build==-1){

        if(s->codec_tag == AV_RL32("DIVX") && s->vo_type==0 && s->vol_control_parameters==0)

            s->divx_version= 400; //divx 4

    }



    if(s->xvid_build>=0 && s->divx_version>=0){

        s->divx_version=

        s->divx_build= -1;

    }



    if(s->workaround_bugs&FF_BUG_AUTODETECT){

        if(s->codec_tag == AV_RL32("XVIX"))

            s->workaround_bugs|= FF_BUG_XVID_ILACE;



        if(s->codec_tag == AV_RL32("UMP4")){

            s->workaround_bugs|= FF_BUG_UMP4;

        }



        if(s->divx_version>=500 && s->divx_build<1814){

            s->workaround_bugs|= FF_BUG_QPEL_CHROMA;

        }



        if(s->divx_version>502 && s->divx_build<1814){

            s->workaround_bugs|= FF_BUG_QPEL_CHROMA2;

        }



        if(s->xvid_build<=3U)

            s->padding_bug_score= 256*256*256*64;



        if(s->xvid_build<=1U)

            s->workaround_bugs|= FF_BUG_QPEL_CHROMA;



        if(s->xvid_build<=12U)

            s->workaround_bugs|= FF_BUG_EDGE;



        if(s->xvid_build<=32U)

            s->workaround_bugs|= FF_BUG_DC_CLIP;



#define SET_QPEL_FUNC(postfix1, postfix2) \

    s->dsp.put_ ## postfix1 = ff_put_ ## postfix2;\

    s->dsp.put_no_rnd_ ## postfix1 = ff_put_no_rnd_ ## postfix2;\

    s->dsp.avg_ ## postfix1 = ff_avg_ ## postfix2;



        if(s->lavc_build<4653U)

            s->workaround_bugs|= FF_BUG_STD_QPEL;



        if(s->lavc_build<4655U)

            s->workaround_bugs|= FF_BUG_DIRECT_BLOCKSIZE;



        if(s->lavc_build<4670U){

            s->workaround_bugs|= FF_BUG_EDGE;

        }



        if(s->lavc_build<=4712U)

            s->workaround_bugs|= FF_BUG_DC_CLIP;



        if(s->divx_version>=0)

            s->workaround_bugs|= FF_BUG_DIRECT_BLOCKSIZE;

        if(s->divx_version==501 && s->divx_build==20020416)

            s->padding_bug_score= 256*256*256*64;



        if(s->divx_version<500U){

            s->workaround_bugs|= FF_BUG_EDGE;

        }



        if(s->divx_version>=0)

            s->workaround_bugs|= FF_BUG_HPEL_CHROMA;

#if 0

        if(s->divx_version==500)

            s->padding_bug_score= 256*256*256*64;



        /* very ugly XVID padding bug detection FIXME/XXX solve this differently

         * Let us hope this at least works.

         */

        if(   s->resync_marker==0 && s->data_partitioning==0 && s->divx_version==-1

           && s->codec_id==AV_CODEC_ID_MPEG4 && s->vo_type==0)

            s->workaround_bugs|= FF_BUG_NO_PADDING;



        if(s->lavc_build<4609U) //FIXME not sure about the version num but a 4609 file seems ok

            s->workaround_bugs|= FF_BUG_NO_PADDING;

#endif

    }



    if(s->workaround_bugs& FF_BUG_STD_QPEL){

        SET_QPEL_FUNC(qpel_pixels_tab[0][ 5], qpel16_mc11_old_c)

        SET_QPEL_FUNC(qpel_pixels_tab[0][ 7], qpel16_mc31_old_c)

        SET_QPEL_FUNC(qpel_pixels_tab[0][ 9], qpel16_mc12_old_c)

        SET_QPEL_FUNC(qpel_pixels_tab[0][11], qpel16_mc32_old_c)

        SET_QPEL_FUNC(qpel_pixels_tab[0][13], qpel16_mc13_old_c)

        SET_QPEL_FUNC(qpel_pixels_tab[0][15], qpel16_mc33_old_c)



        SET_QPEL_FUNC(qpel_pixels_tab[1][ 5], qpel8_mc11_old_c)

        SET_QPEL_FUNC(qpel_pixels_tab[1][ 7], qpel8_mc31_old_c)

        SET_QPEL_FUNC(qpel_pixels_tab[1][ 9], qpel8_mc12_old_c)

        SET_QPEL_FUNC(qpel_pixels_tab[1][11], qpel8_mc32_old_c)

        SET_QPEL_FUNC(qpel_pixels_tab[1][13], qpel8_mc13_old_c)

        SET_QPEL_FUNC(qpel_pixels_tab[1][15], qpel8_mc33_old_c)

    }



    if(avctx->debug & FF_DEBUG_BUGS)

        av_log(s->avctx, AV_LOG_DEBUG, "bugs: %X lavc_build:%d xvid_build:%d divx_version:%d divx_build:%d %s\n",

               s->workaround_bugs, s->lavc_build, s->xvid_build, s->divx_version, s->divx_build,

               s->divx_packed ? "p" : "");



#if HAVE_MMX

    if (s->codec_id == AV_CODEC_ID_MPEG4 && s->xvid_build>=0 && avctx->idct_algo == FF_IDCT_AUTO && (av_get_cpu_flags() & AV_CPU_FLAG_MMX)) {

        avctx->idct_algo= FF_IDCT_XVIDMMX;

        ff_dct_common_init(s);

        goto retry;

    }

#endif



        /* After H263 & mpeg4 header decode we have the height, width,*/

        /* and other parameters. So then we could init the picture   */

        /* FIXME: By the way H263 decoder is evolving it should have */

        /* an H263EncContext                                         */



    if (s->width  != avctx->coded_width  ||

        s->height != avctx->coded_height ||

        s->context_reinit) {

        /* H.263 could change picture size any time */

        s->context_reinit = 0;



        avcodec_set_dimensions(avctx, s->width, s->height);



        if ((ret = ff_MPV_common_frame_size_change(s)))

            return ret;

    }



    if((s->codec_id==AV_CODEC_ID_H263 || s->codec_id==AV_CODEC_ID_H263P || s->codec_id == AV_CODEC_ID_H263I))

        s->gob_index = ff_h263_get_gob_height(s);



    // for skipping the frame

    s->current_picture.f.pict_type = s->pict_type;

    s->current_picture.f.key_frame = s->pict_type == AV_PICTURE_TYPE_I;



    /* skip B-frames if we don't have reference frames */

    if (s->last_picture_ptr == NULL &&

        (s->pict_type == AV_PICTURE_TYPE_B || s->droppable))

        return get_consumed_bytes(s, buf_size);

    if(   (avctx->skip_frame >= AVDISCARD_NONREF && s->pict_type==AV_PICTURE_TYPE_B)

       || (avctx->skip_frame >= AVDISCARD_NONKEY && s->pict_type!=AV_PICTURE_TYPE_I)

       ||  avctx->skip_frame >= AVDISCARD_ALL)

        return get_consumed_bytes(s, buf_size);



    if(s->next_p_frame_damaged){

        if(s->pict_type==AV_PICTURE_TYPE_B)

            return get_consumed_bytes(s, buf_size);

        else

            s->next_p_frame_damaged=0;

    }



    if((!s->no_rounding) || s->pict_type==AV_PICTURE_TYPE_B){

        s->me.qpel_put= s->dsp.put_qpel_pixels_tab;

        s->me.qpel_avg= s->dsp.avg_qpel_pixels_tab;

    }else{

        s->me.qpel_put= s->dsp.put_no_rnd_qpel_pixels_tab;

        s->me.qpel_avg= s->dsp.avg_qpel_pixels_tab;

    }



    if ((ret = ff_MPV_frame_start(s, avctx)) < 0)

        return ret;



    if (!s->divx_packed && !avctx->hwaccel)

        ff_thread_finish_setup(avctx);



    if (CONFIG_MPEG4_VDPAU_DECODER && (s->avctx->codec->capabilities & CODEC_CAP_HWACCEL_VDPAU)) {

        ff_vdpau_mpeg4_decode_picture(s, s->gb.buffer, s->gb.buffer_end - s->gb.buffer);

        goto frame_end;

    }



    if (avctx->hwaccel) {

        if ((ret = avctx->hwaccel->start_frame(avctx, s->gb.buffer, s->gb.buffer_end - s->gb.buffer)) < 0)

            return ret;

    }



    ff_mpeg_er_frame_start(s);



    //the second part of the wmv2 header contains the MB skip bits which are stored in current_picture->mb_type

    //which is not available before ff_MPV_frame_start()

    if (CONFIG_WMV2_DECODER && s->msmpeg4_version==5){

        ret = ff_wmv2_decode_secondary_picture_header(s);

        if(ret<0) return ret;

        if(ret==1) goto frame_end;

    }



    /* decode each macroblock */

    s->mb_x=0;

    s->mb_y=0;



    ret = decode_slice(s);

    while(s->mb_y<s->mb_height){

        if(s->msmpeg4_version){

            if(s->slice_height==0 || s->mb_x!=0 || (s->mb_y%s->slice_height)!=0 || get_bits_left(&s->gb)<0)

                break;

        }else{

            int prev_x=s->mb_x, prev_y=s->mb_y;

            if(ff_h263_resync(s)<0)

                break;

            if (prev_y * s->mb_width + prev_x < s->mb_y * s->mb_width + s->mb_x)

                s->er.error_occurred = 1;

        }



        if(s->msmpeg4_version<4 && s->h263_pred)

            ff_mpeg4_clean_buffers(s);



        if (decode_slice(s) < 0) ret = AVERROR_INVALIDDATA;

    }



    if (s->msmpeg4_version && s->msmpeg4_version<4 && s->pict_type==AV_PICTURE_TYPE_I)

        if(!CONFIG_MSMPEG4_DECODER || ff_msmpeg4_decode_ext_header(s, buf_size) < 0){

            s->er.error_status_table[s->mb_num - 1] = ER_MB_ERROR;

        }



    av_assert1(s->bitstream_buffer_size==0);

frame_end:

    ff_er_frame_end(&s->er);



    if (avctx->hwaccel) {

        if ((ret = avctx->hwaccel->end_frame(avctx)) < 0)

            return ret;

    }



    ff_MPV_frame_end(s);



    /* divx 5.01+ bitstream reorder stuff */

    /* Since this clobbers the input buffer and hwaccel codecs still need the

     * data during hwaccel->end_frame we should not do this any earlier */

    if(s->codec_id==AV_CODEC_ID_MPEG4 && s->divx_packed){

        int current_pos= s->gb.buffer == s->bitstream_buffer ? 0 : (get_bits_count(&s->gb)>>3);

        int startcode_found=0;



        if(buf_size - current_pos > 7){

            int i;

            for(i=current_pos; i<buf_size-4; i++){

                if(buf[i]==0 && buf[i+1]==0 && buf[i+2]==1 && buf[i+3]==0xB6){

                    startcode_found=!(buf[i+4]&0x40);

                    break;

                }

            }

        }



        if(startcode_found){

            av_fast_malloc(

                &s->bitstream_buffer,

                &s->allocated_bitstream_buffer_size,

                buf_size - current_pos + FF_INPUT_BUFFER_PADDING_SIZE);

            if (!s->bitstream_buffer)

                return AVERROR(ENOMEM);

            memcpy(s->bitstream_buffer, buf + current_pos, buf_size - current_pos);

            s->bitstream_buffer_size= buf_size - current_pos;

        }

    }



    if (!s->divx_packed && avctx->hwaccel)

        ff_thread_finish_setup(avctx);



    av_assert1(s->current_picture.f.pict_type == s->current_picture_ptr->f.pict_type);

    av_assert1(s->current_picture.f.pict_type == s->pict_type);

    if (s->pict_type == AV_PICTURE_TYPE_B || s->low_delay) {

        if ((ret = av_frame_ref(pict, &s->current_picture_ptr->f)) < 0)

            return ret;

        ff_print_debug_info(s, s->current_picture_ptr, pict);

        ff_mpv_export_qp_table(s, pict, s->current_picture_ptr, FF_QSCALE_TYPE_MPEG1);

    } else if (s->last_picture_ptr != NULL) {

        if ((ret = av_frame_ref(pict, &s->last_picture_ptr->f)) < 0)

            return ret;

        ff_print_debug_info(s, s->last_picture_ptr, pict);

        ff_mpv_export_qp_table(s, pict, s->last_picture_ptr, FF_QSCALE_TYPE_MPEG1);

    }



    if(s->last_picture_ptr || s->low_delay){

        if (   pict->format == AV_PIX_FMT_YUV420P

            && (s->codec_tag == AV_RL32("GEOV") || s->codec_tag == AV_RL32("GEOX"))) {

            int x, y, p;

            av_frame_make_writable(pict);

            for (p=0; p<3; p++) {

                int w = FF_CEIL_RSHIFT(pict-> width, !!p);

                int h = FF_CEIL_RSHIFT(pict->height, !!p);

                int linesize = pict->linesize[p];

                for (y=0; y<(h>>1); y++)

                    for (x=0; x<w; x++)

                        FFSWAP(int,

                               pict->data[p][x + y*linesize],

                               pict->data[p][x + (h-1-y)*linesize]);

            }

        }

        *got_frame = 1;

    }



    return (ret && (avctx->err_recognition & AV_EF_EXPLODE))?ret:get_consumed_bytes(s, buf_size);

}

void avcodec_free_context(AVCodecContext **pavctx)

{

    AVCodecContext *avctx = *pavctx;



    if (!avctx)

        return;



    avcodec_close(avctx);



    av_freep(&avctx->extradata);

    av_freep(&avctx->subtitle_header);






    av_freep(pavctx);

}

void ff_mpeg_flush(AVCodecContext *avctx){

    int i;

    MpegEncContext *s = avctx->priv_data;



    if(s==NULL || s->picture==NULL)

        return;



    for(i=0; i<MAX_PICTURE_COUNT; i++){

       if(s->picture[i].data[0] && (   s->picture[i].type == FF_BUFFER_TYPE_INTERNAL

                                    || s->picture[i].type == FF_BUFFER_TYPE_USER))

        avctx->release_buffer(avctx, (AVFrame*)&s->picture[i]);

    }

    s->current_picture_ptr = s->last_picture_ptr = s->next_picture_ptr = NULL;



    s->mb_x= s->mb_y= 0;



    s->parse_context.state= -1;

    s->parse_context.frame_start_found= 0;

    s->parse_context.overread= 0;

    s->parse_context.overread_index= 0;

    s->parse_context.index= 0;

    s->parse_context.last_index= 0;

    s->bitstream_buffer_size=0;


}

static int jacosub_read_header(AVFormatContext *s)

{

    AVBPrint header;

    AVIOContext *pb = s->pb;

    char line[JSS_MAX_LINESIZE];

    JACOsubContext *jacosub = s->priv_data;

    int shift_set = 0; // only the first shift matters

    int merge_line = 0;

    int i, ret;



    AVStream *st = avformat_new_stream(s, NULL);

    if (!st)

        return AVERROR(ENOMEM);

    avpriv_set_pts_info(st, 64, 1, 100);

    st->codec->codec_type = AVMEDIA_TYPE_SUBTITLE;

    st->codec->codec_id   = AV_CODEC_ID_JACOSUB;



    jacosub->timeres = 30;



    av_bprint_init(&header, 1024+FF_INPUT_BUFFER_PADDING_SIZE, 4096);



    while (!avio_feof(pb)) {

        int cmd_len;

        const char *p = line;

        int64_t pos = avio_tell(pb);

        int len = ff_get_line(pb, line, sizeof(line));



        p = jss_skip_whitespace(p);



        /* queue timed line */

        if (merge_line || timed_line(p)) {

            AVPacket *sub;



            sub = ff_subtitles_queue_insert(&jacosub->q, line, len, merge_line);

            if (!sub)

                return AVERROR(ENOMEM);

            sub->pos = pos;

            merge_line = len > 1 && !strcmp(&line[len - 2], "\\\n");

            continue;

        }



        /* skip all non-compiler commands and focus on the command */

        if (*p != '#')

            continue;

        p++;

        i = get_jss_cmd(p[0]);

        if (i == -1)

            continue;



        /* trim command + spaces */

        cmd_len = strlen(cmds[i]);

        if (av_strncasecmp(p, cmds[i], cmd_len) == 0)

            p += cmd_len;

        else

            p++;

        p = jss_skip_whitespace(p);



        /* handle commands which affect the whole script */

        switch (cmds[i][0]) {

        case 'S': // SHIFT command affect the whole script...

            if (!shift_set) {

                jacosub->shift = get_shift(jacosub->timeres, p);

                shift_set = 1;

            }

            av_bprintf(&header, "#S %s", p);

            break;

        case 'T': // ...but must be placed after TIMERES

            jacosub->timeres = strtol(p, NULL, 10);

            if (!jacosub->timeres)

                jacosub->timeres = 30;

            else

                av_bprintf(&header, "#T %s", p);

            break;

        }

    }



    /* general/essential directives in the extradata */

    ret = avpriv_bprint_to_extradata(st->codec, &header);

    if (ret < 0)

        return ret;



    /* SHIFT and TIMERES affect the whole script so packet timing can only be

     * done in a second pass */

    for (i = 0; i < jacosub->q.nb_subs; i++) {

        AVPacket *sub = &jacosub->q.subs[i];

        read_ts(jacosub, sub->data, &sub->pts, &sub->duration);

    }

    ff_subtitles_queue_finalize(&jacosub->q);



    return 0;

}

static int get_packet_payload_size(AVFormatContext *ctx, int stream_index,

                                   int64_t pts, int64_t dts)

{

    MpegMuxContext *s = ctx->priv_data;

    int buf_index;

    StreamInfo *stream;



    stream = ctx->streams[stream_index]->priv_data;



    buf_index = 0;

    if (((s->packet_number % s->pack_header_freq) == 0)) {

        /* pack header size */

        if (s->is_mpeg2) 

            buf_index += 14;

        else

            buf_index += 12;



        if (s->is_vcd) {

            /* there is exactly one system header for each stream in a VCD MPEG,

               One in the very first video packet and one in the very first

               audio packet (see VCD standard p. IV-7 and IV-8).*/



            if (stream->packet_number==0)

                /* The system headers refer only to the stream they occur in,

                   so they have a constant size.*/

                buf_index += 15;



        } else {            

            if ((s->packet_number % s->system_header_freq) == 0)

                buf_index += s->system_header_size;

        }

    }



    if (s->is_vcd && stream->packet_number==0)

        /* the first pack of each stream contains only the pack header,

           the system header and some padding (see VCD standard p. IV-6) 

           Add the padding size, so that the actual payload becomes 0.*/

        buf_index += s->packet_size - buf_index;

    else {

        /* packet header size */

        buf_index += 6;

        if (s->is_mpeg2)

            buf_index += 3;

        if (pts != AV_NOPTS_VALUE) {

            if (dts != pts)

                buf_index += 5 + 5;

            else

                buf_index += 5;



        } else {

            if (!s->is_mpeg2)

                buf_index++;

        }



        if (stream->id < 0xc0) {

            /* AC3/LPCM private data header */

            buf_index += 4;

            if (stream->id >= 0xa0) {

                int n;

                buf_index += 3;

                /* NOTE: we round the payload size to an integer number of

                   LPCM samples */

                n = (s->packet_size - buf_index) % stream->lpcm_align;

                if (n)

                    buf_index += (stream->lpcm_align - n);

            }

        }



        if (s->is_vcd && stream->id == AUDIO_ID)

            /* The VCD standard demands that 20 zero bytes follow

               each audio packet (see standard p. IV-8).*/

            buf_index+=20;

    }

    return s->packet_size - buf_index; 

}

ogm_header(AVFormatContext *s, int idx)

{

    struct ogg *ogg = s->priv_data;

    struct ogg_stream *os = ogg->streams + idx;

    AVStream *st = s->streams[idx];

    const uint8_t *p = os->buf + os->pstart;

    uint64_t time_unit;

    uint64_t spu;

    uint32_t size;



    if(!(*p & 1))

        return 0;



    if(*p == 1) {

        p++;



        if(*p == 'v'){

            int tag;

            st->codec->codec_type = AVMEDIA_TYPE_VIDEO;

            p += 8;

            tag = bytestream_get_le32(&p);

            st->codec->codec_id = ff_codec_get_id(ff_codec_bmp_tags, tag);

            st->codec->codec_tag = tag;

        } else if (*p == 't') {

            st->codec->codec_type = AVMEDIA_TYPE_SUBTITLE;

            st->codec->codec_id = CODEC_ID_TEXT;

            p += 12;

        } else {

            uint8_t acid[5];

            int cid;

            st->codec->codec_type = AVMEDIA_TYPE_AUDIO;

            p += 8;

            bytestream_get_buffer(&p, acid, 4);

            acid[4] = 0;

            cid = strtol(acid, NULL, 16);

            st->codec->codec_id = ff_codec_get_id(ff_codec_wav_tags, cid);

            // our parser completely breaks AAC in Ogg

            if (st->codec->codec_id != CODEC_ID_AAC)

                st->need_parsing = AVSTREAM_PARSE_FULL;

        }



        size        = bytestream_get_le32(&p);

        size        = FFMIN(size, os->psize);

        time_unit   = bytestream_get_le64(&p);

        spu         = bytestream_get_le64(&p);

        p += 4;                     /* default_len */

        p += 8;                     /* buffersize + bits_per_sample */



        if(st->codec->codec_type == AVMEDIA_TYPE_VIDEO){

            st->codec->width = bytestream_get_le32(&p);

            st->codec->height = bytestream_get_le32(&p);

            avpriv_set_pts_info(st, 64, time_unit, spu * 10000000);

        } else {

            st->codec->channels = bytestream_get_le16(&p);

            p += 2;                 /* block_align */

            st->codec->bit_rate = bytestream_get_le32(&p) * 8;

            st->codec->sample_rate = spu * 10000000 / time_unit;

            avpriv_set_pts_info(st, 64, 1, st->codec->sample_rate);

            if (size >= 56 && st->codec->codec_id == CODEC_ID_AAC) {

                p += 4;

                size -= 4;

            }

            if (size > 52) {

                av_assert0(FF_INPUT_BUFFER_PADDING_SIZE <= 52);

                size -= 52;

                st->codec->extradata_size = size;

                st->codec->extradata = av_malloc(size + FF_INPUT_BUFFER_PADDING_SIZE);

                bytestream_get_buffer(&p, st->codec->extradata, size);

            }

        }

    } else if (*p == 3) {

        if (os->psize > 8)

            ff_vorbis_comment(s, &st->metadata, p+7, os->psize-8);

    }



    return 1;

}

static int ape_decode_frame(AVCodecContext *avctx, void *data,

                            int *got_frame_ptr, AVPacket *avpkt)

{

    AVFrame *frame     = data;

    const uint8_t *buf = avpkt->data;

    APEContext *s = avctx->priv_data;

    uint8_t *sample8;

    int16_t *sample16;

    int32_t *sample24;

    int i, ch, ret;

    int blockstodecode;



    /* this should never be negative, but bad things will happen if it is, so

       check it just to make sure. */

    av_assert0(s->samples >= 0);



    if(!s->samples){

        uint32_t nblocks, offset;

        int buf_size;



        if (!avpkt->size) {

            *got_frame_ptr = 0;

            return 0;

        }

        if (avpkt->size < 8) {

            av_log(avctx, AV_LOG_ERROR, "Packet is too small\n");

            return AVERROR_INVALIDDATA;

        }

        buf_size = avpkt->size & ~3;

        if (buf_size != avpkt->size) {

            av_log(avctx, AV_LOG_WARNING, "packet size is not a multiple of 4. "

                   "extra bytes at the end will be skipped.\n");

        }

        if (s->fileversion < 3950) // previous versions overread two bytes

            buf_size += 2;

        av_fast_malloc(&s->data, &s->data_size, buf_size);

        if (!s->data)

            return AVERROR(ENOMEM);

        s->dsp.bswap_buf((uint32_t*)s->data, (const uint32_t*)buf, buf_size >> 2);

        memset(s->data + (buf_size & ~3), 0, buf_size & 3);

        s->ptr = s->data;

        s->data_end = s->data + buf_size;



        nblocks = bytestream_get_be32(&s->ptr);

        offset  = bytestream_get_be32(&s->ptr);

        if (s->fileversion >= 3900) {

            if (offset > 3) {

                av_log(avctx, AV_LOG_ERROR, "Incorrect offset passed\n");

                s->data = NULL;

                return AVERROR_INVALIDDATA;

            }

            if (s->data_end - s->ptr < offset) {

                av_log(avctx, AV_LOG_ERROR, "Packet is too small\n");

                return AVERROR_INVALIDDATA;

            }

            s->ptr += offset;

        } else {

            if ((ret = init_get_bits8(&s->gb, s->ptr, s->data_end - s->ptr)) < 0)

                return ret;

            if (s->fileversion > 3800)

                skip_bits_long(&s->gb, offset * 8);

            else

                skip_bits_long(&s->gb, offset);

        }



        if (!nblocks || nblocks > INT_MAX) {

            av_log(avctx, AV_LOG_ERROR, "Invalid sample count: %u.\n", nblocks);

            return AVERROR_INVALIDDATA;

        }

        s->samples = nblocks;



        /* Initialize the frame decoder */

        if (init_frame_decoder(s) < 0) {

            av_log(avctx, AV_LOG_ERROR, "Error reading frame header\n");

            return AVERROR_INVALIDDATA;

        }

    }



    if (!s->data) {

        *got_frame_ptr = 0;

        return avpkt->size;

    }



    blockstodecode = FFMIN(s->blocks_per_loop, s->samples);

    // for old files coefficients were not interleaved,

    // so we need to decode all of them at once

    if (s->fileversion < 3930)

        blockstodecode = s->samples;



    /* reallocate decoded sample buffer if needed */

    av_fast_malloc(&s->decoded_buffer, &s->decoded_size,

                   2 * FFALIGN(blockstodecode, 8) * sizeof(*s->decoded_buffer));

    if (!s->decoded_buffer)

        return AVERROR(ENOMEM);

    memset(s->decoded_buffer, 0, s->decoded_size);

    s->decoded[0] = s->decoded_buffer;

    s->decoded[1] = s->decoded_buffer + FFALIGN(blockstodecode, 8);



    /* get output buffer */

    frame->nb_samples = blockstodecode;

    if ((ret = ff_get_buffer(avctx, frame, 0)) < 0)

        return ret;



    s->error=0;



    if ((s->channels == 1) || (s->frameflags & APE_FRAMECODE_PSEUDO_STEREO))

        ape_unpack_mono(s, blockstodecode);

    else

        ape_unpack_stereo(s, blockstodecode);

    emms_c();



    if (s->error) {

        s->samples=0;

        av_log(avctx, AV_LOG_ERROR, "Error decoding frame\n");

        return AVERROR_INVALIDDATA;

    }



    switch (s->bps) {

    case 8:

        for (ch = 0; ch < s->channels; ch++) {

            sample8 = (uint8_t *)frame->data[ch];

            for (i = 0; i < blockstodecode; i++)

                *sample8++ = (s->decoded[ch][i] + 0x80) & 0xff;

        }

        break;

    case 16:

        for (ch = 0; ch < s->channels; ch++) {

            sample16 = (int16_t *)frame->data[ch];

            for (i = 0; i < blockstodecode; i++)

                *sample16++ = s->decoded[ch][i];

        }

        break;

    case 24:

        for (ch = 0; ch < s->channels; ch++) {

            sample24 = (int32_t *)frame->data[ch];

            for (i = 0; i < blockstodecode; i++)

                *sample24++ = s->decoded[ch][i] << 8;

        }

        break;

    }



    s->samples -= blockstodecode;



    *got_frame_ptr = 1;



    return !s->samples ? avpkt->size : 0;

}

static inline void RENAME(rgb32tobgr16)(const uint8_t *src, uint8_t *dst, long src_size)

{

    const uint8_t *s = src;

    const uint8_t *end;

#if COMPILE_TEMPLATE_MMX

    const uint8_t *mm_end;

#endif

    uint16_t *d = (uint16_t *)dst;

    end = s + src_size;

#if COMPILE_TEMPLATE_MMX

    __asm__ volatile(PREFETCH"    %0"::"m"(*src):"memory");

    __asm__ volatile(

        "movq          %0, %%mm7    \n\t"

        "movq          %1, %%mm6    \n\t"

        ::"m"(red_16mask),"m"(green_16mask));

    mm_end = end - 15;

    while (s < mm_end) {

        __asm__ volatile(

            PREFETCH"    32%1           \n\t"

            "movd          %1, %%mm0    \n\t"

            "movd         4%1, %%mm3    \n\t"

            "punpckldq    8%1, %%mm0    \n\t"

            "punpckldq   12%1, %%mm3    \n\t"

            "movq       %%mm0, %%mm1    \n\t"

            "movq       %%mm0, %%mm2    \n\t"

            "movq       %%mm3, %%mm4    \n\t"

            "movq       %%mm3, %%mm5    \n\t"

            "psllq         $8, %%mm0    \n\t"

            "psllq         $8, %%mm3    \n\t"

            "pand       %%mm7, %%mm0    \n\t"

            "pand       %%mm7, %%mm3    \n\t"

            "psrlq         $5, %%mm1    \n\t"

            "psrlq         $5, %%mm4    \n\t"

            "pand       %%mm6, %%mm1    \n\t"

            "pand       %%mm6, %%mm4    \n\t"

            "psrlq        $19, %%mm2    \n\t"

            "psrlq        $19, %%mm5    \n\t"

            "pand          %2, %%mm2    \n\t"

            "pand          %2, %%mm5    \n\t"

            "por        %%mm1, %%mm0    \n\t"

            "por        %%mm4, %%mm3    \n\t"

            "por        %%mm2, %%mm0    \n\t"

            "por        %%mm5, %%mm3    \n\t"

            "psllq        $16, %%mm3    \n\t"

            "por        %%mm3, %%mm0    \n\t"

            MOVNTQ"     %%mm0, %0       \n\t"

            :"=m"(*d):"m"(*s),"m"(blue_16mask):"memory");

        d += 4;

        s += 16;

    }

    __asm__ volatile(SFENCE:::"memory");

    __asm__ volatile(EMMS:::"memory");

#endif

    while (s < end) {

        register int rgb = *(const uint32_t*)s; s += 4;

        *d++ = ((rgb&0xF8)<<8) + ((rgb&0xFC00)>>5) + ((rgb&0xF80000)>>19);

    }

}

static int truemotion1_decode_header(TrueMotion1Context *s)

{

    int i;

    int width_shift = 0;

    int new_pix_fmt;

    struct frame_header header;

    uint8_t header_buffer[128];  /* logical maximum size of the header */

    const uint8_t *sel_vector_table;



    header.header_size = ((s->buf[0] >> 5) | (s->buf[0] << 3)) & 0x7f;

    if (s->buf[0] < 0x10)

    {

        av_log(s->avctx, AV_LOG_ERROR, "invalid header size (%d)\n", s->buf[0]);

        return -1;

    }



    /* unscramble the header bytes with a XOR operation */

    memset(header_buffer, 0, 128);

    for (i = 1; i < header.header_size; i++)

        header_buffer[i - 1] = s->buf[i] ^ s->buf[i + 1];



    header.compression = header_buffer[0];

    header.deltaset = header_buffer[1];

    header.vectable = header_buffer[2];

    header.ysize = AV_RL16(&header_buffer[3]);

    header.xsize = AV_RL16(&header_buffer[5]);

    header.checksum = AV_RL16(&header_buffer[7]);

    header.version = header_buffer[9];

    header.header_type = header_buffer[10];

    header.flags = header_buffer[11];

    header.control = header_buffer[12];



    /* Version 2 */

    if (header.version >= 2)

    {

        if (header.header_type > 3)

        {

            av_log(s->avctx, AV_LOG_ERROR, "invalid header type (%d)\n", header.header_type);

            return -1;

        } else if ((header.header_type == 2) || (header.header_type == 3)) {

            s->flags = header.flags;

            if (!(s->flags & FLAG_INTERFRAME))

                s->flags |= FLAG_KEYFRAME;

        } else

            s->flags = FLAG_KEYFRAME;

    } else /* Version 1 */

        s->flags = FLAG_KEYFRAME;



    if (s->flags & FLAG_SPRITE) {

        av_log(s->avctx, AV_LOG_INFO, "SPRITE frame found, please report the sample to the developers\n");

        /* FIXME header.width, height, xoffset and yoffset aren't initialized */

#if 0

        s->w = header.width;

        s->h = header.height;

        s->x = header.xoffset;

        s->y = header.yoffset;

#else

        return -1;

#endif

    } else {

        s->w = header.xsize;

        s->h = header.ysize;

        if (header.header_type < 2) {

            if ((s->w < 213) && (s->h >= 176))

            {

                s->flags |= FLAG_INTERPOLATED;

                av_log(s->avctx, AV_LOG_INFO, "INTERPOLATION selected, please report the sample to the developers\n");

            }

        }

    }



    if (header.compression >= 17) {

        av_log(s->avctx, AV_LOG_ERROR, "invalid compression type (%d)\n", header.compression);

        return -1;

    }



    if ((header.deltaset != s->last_deltaset) ||

        (header.vectable != s->last_vectable))

        select_delta_tables(s, header.deltaset);



    if ((header.compression & 1) && header.header_type)

        sel_vector_table = pc_tbl2;

    else {

        if (header.vectable < 4)

            sel_vector_table = tables[header.vectable - 1];

        else {

            av_log(s->avctx, AV_LOG_ERROR, "invalid vector table id (%d)\n", header.vectable);

            return -1;

        }

    }



    if (compression_types[header.compression].algorithm == ALGO_RGB24H) {

        new_pix_fmt = PIX_FMT_RGB32;

        width_shift = 1;

    } else

        new_pix_fmt = PIX_FMT_RGB555; // RGB565 is supported as well



    s->w >>= width_shift;

    if (av_image_check_size(s->w, s->h, 0, s->avctx) < 0)

        return -1;



    if (s->w != s->avctx->width || s->h != s->avctx->height ||

        new_pix_fmt != s->avctx->pix_fmt) {

        if (s->frame.data[0])

            s->avctx->release_buffer(s->avctx, &s->frame);

        s->avctx->sample_aspect_ratio = (AVRational){ 1 << width_shift, 1 };

        s->avctx->pix_fmt = new_pix_fmt;

        avcodec_set_dimensions(s->avctx, s->w, s->h);

        av_fast_malloc(&s->vert_pred, &s->vert_pred_size, s->avctx->width * sizeof(unsigned int));

    }



    /* There is 1 change bit per 4 pixels, so each change byte represents

     * 32 pixels; divide width by 4 to obtain the number of change bits and

     * then round up to the nearest byte. */

    s->mb_change_bits_row_size = ((s->avctx->width >> (2 - width_shift)) + 7) >> 3;



    if ((header.deltaset != s->last_deltaset) || (header.vectable != s->last_vectable))

    {

        if (compression_types[header.compression].algorithm == ALGO_RGB24H)

            gen_vector_table24(s, sel_vector_table);

        else

        if (s->avctx->pix_fmt == PIX_FMT_RGB555)

            gen_vector_table15(s, sel_vector_table);

        else

            gen_vector_table16(s, sel_vector_table);

    }



    /* set up pointers to the other key data chunks */

    s->mb_change_bits = s->buf + header.header_size;

    if (s->flags & FLAG_KEYFRAME) {

        /* no change bits specified for a keyframe; only index bytes */

        s->index_stream = s->mb_change_bits;

    } else {

        /* one change bit per 4x4 block */

        s->index_stream = s->mb_change_bits +

            (s->mb_change_bits_row_size * (s->avctx->height >> 2));

    }

    s->index_stream_size = s->size - (s->index_stream - s->buf);



    s->last_deltaset = header.deltaset;

    s->last_vectable = header.vectable;

    s->compression = header.compression;

    s->block_width = compression_types[header.compression].block_width;

    s->block_height = compression_types[header.compression].block_height;

    s->block_type = compression_types[header.compression].block_type;



    if (s->avctx->debug & FF_DEBUG_PICT_INFO)

        av_log(s->avctx, AV_LOG_INFO, "tables: %d / %d c:%d %dx%d t:%d %s%s%s%s\n",

            s->last_deltaset, s->last_vectable, s->compression, s->block_width,

            s->block_height, s->block_type,

            s->flags & FLAG_KEYFRAME ? " KEY" : "",

            s->flags & FLAG_INTERFRAME ? " INTER" : "",

            s->flags & FLAG_SPRITE ? " SPRITE" : "",

            s->flags & FLAG_INTERPOLATED ? " INTERPOL" : "");



    return header.header_size;

}

static int opt_input_ts_scale(const char *opt, const char *arg)

{

    unsigned int stream;

    double scale;

    char *p;



    stream = strtol(arg, &p, 0);

    if (*p)

        p++;

    scale= strtod(p, &p);



    if(stream >= MAX_STREAMS)

        ffmpeg_exit(1);



    ts_scale = grow_array(ts_scale, sizeof(*ts_scale), &nb_ts_scale, stream + 1);

    ts_scale[stream] = scale;

    return 0;

}

static av_always_inline int normal_limit(uint8_t *p, int stride, int E, int I)

{

    LOAD_PIXELS

    return simple_limit(p, stride, 2*E+I)

        && FFABS(p3-p2) <= I && FFABS(p2-p1) <= I && FFABS(p1-p0) <= I

        && FFABS(q3-q2) <= I && FFABS(q2-q1) <= I && FFABS(q1-q0) <= I;

}

static int mov_open_dref(AVIOContext **pb, const char *src, MOVDref *ref,

                         AVIOInterruptCB *int_cb, int use_absolute_path, AVFormatContext *fc)

{

    /* try relative path, we do not try the absolute because it can leak information about our

       system to an attacker */

    if (ref->nlvl_to > 0 && ref->nlvl_from > 0) {

        char filename[1024];

        const char *src_path;

        int i, l;



        /* find a source dir */

        src_path = strrchr(src, '/');

        if (src_path)

            src_path++;

        else

            src_path = src;



        /* find a next level down to target */

        for (i = 0, l = strlen(ref->path) - 1; l >= 0; l--)

            if (ref->path[l] == '/') {

                if (i == ref->nlvl_to - 1)

                    break;

                else

                    i++;

            }



        /* compose filename if next level down to target was found */

        if (i == ref->nlvl_to - 1 && src_path - src  < sizeof(filename)) {

            memcpy(filename, src, src_path - src);

            filename[src_path - src] = 0;



            for (i = 1; i < ref->nlvl_from; i++)

                av_strlcat(filename, "../", sizeof(filename));



            av_strlcat(filename, ref->path + l + 1, sizeof(filename));



            if (!avio_open2(pb, filename, AVIO_FLAG_READ, int_cb, NULL))

                return 0;

        }

    } else if (use_absolute_path) {

        av_log(fc, AV_LOG_WARNING, "Using absolute path on user request, "

               "this is a possible security issue\n");

        if (!avio_open2(pb, ref->path, AVIO_FLAG_READ, int_cb, NULL))

            return 0;

    }



    return AVERROR(ENOENT);

}

static int swScale(SwsContext *c, const uint8_t* src[],

                   int srcStride[], int srcSliceY,

                   int srcSliceH, uint8_t* dst[], int dstStride[])

{

    /* load a few things into local vars to make the code more readable? and faster */

    const int srcW= c->srcW;

    const int dstW= c->dstW;

    const int dstH= c->dstH;

    const int chrDstW= c->chrDstW;

    const int chrSrcW= c->chrSrcW;

    const int lumXInc= c->lumXInc;

    const int chrXInc= c->chrXInc;

    const enum PixelFormat dstFormat= c->dstFormat;

    const int flags= c->flags;

    int16_t *vLumFilterPos= c->vLumFilterPos;

    int16_t *vChrFilterPos= c->vChrFilterPos;

    int16_t *hLumFilterPos= c->hLumFilterPos;

    int16_t *hChrFilterPos= c->hChrFilterPos;

    int16_t *vLumFilter= c->vLumFilter;

    int16_t *vChrFilter= c->vChrFilter;

    int16_t *hLumFilter= c->hLumFilter;

    int16_t *hChrFilter= c->hChrFilter;

    int32_t *lumMmxFilter= c->lumMmxFilter;

    int32_t *chrMmxFilter= c->chrMmxFilter;

    int32_t av_unused *alpMmxFilter= c->alpMmxFilter;

    const int vLumFilterSize= c->vLumFilterSize;

    const int vChrFilterSize= c->vChrFilterSize;

    const int hLumFilterSize= c->hLumFilterSize;

    const int hChrFilterSize= c->hChrFilterSize;

    int16_t **lumPixBuf= c->lumPixBuf;

    int16_t **chrUPixBuf= c->chrUPixBuf;

    int16_t **chrVPixBuf= c->chrVPixBuf;

    int16_t **alpPixBuf= c->alpPixBuf;

    const int vLumBufSize= c->vLumBufSize;

    const int vChrBufSize= c->vChrBufSize;

    uint8_t *formatConvBuffer= c->formatConvBuffer;

    const int chrSrcSliceY= srcSliceY >> c->chrSrcVSubSample;

    const int chrSrcSliceH= -((-srcSliceH) >> c->chrSrcVSubSample);

    int lastDstY;

    uint32_t *pal=c->pal_yuv;

    yuv2planar1_fn yuv2yuv1 = c->yuv2yuv1;

    yuv2planarX_fn yuv2yuvX = c->yuv2yuvX;

    yuv2packed1_fn yuv2packed1 = c->yuv2packed1;

    yuv2packed2_fn yuv2packed2 = c->yuv2packed2;

    yuv2packedX_fn yuv2packedX = c->yuv2packedX;



    /* vars which will change and which we need to store back in the context */

    int dstY= c->dstY;

    int lumBufIndex= c->lumBufIndex;

    int chrBufIndex= c->chrBufIndex;

    int lastInLumBuf= c->lastInLumBuf;

    int lastInChrBuf= c->lastInChrBuf;



    if (isPacked(c->srcFormat)) {

        src[0]=

        src[1]=

        src[2]=

        src[3]= src[0];

        srcStride[0]=

        srcStride[1]=

        srcStride[2]=

        srcStride[3]= srcStride[0];

    }

    srcStride[1]<<= c->vChrDrop;

    srcStride[2]<<= c->vChrDrop;



    DEBUG_BUFFERS("swScale() %p[%d] %p[%d] %p[%d] %p[%d] -> %p[%d] %p[%d] %p[%d] %p[%d]\n",

                  src[0], srcStride[0], src[1], srcStride[1], src[2], srcStride[2], src[3], srcStride[3],

                  dst[0], dstStride[0], dst[1], dstStride[1], dst[2], dstStride[2], dst[3], dstStride[3]);

    DEBUG_BUFFERS("srcSliceY: %d srcSliceH: %d dstY: %d dstH: %d\n",

                   srcSliceY,    srcSliceH,    dstY,    dstH);

    DEBUG_BUFFERS("vLumFilterSize: %d vLumBufSize: %d vChrFilterSize: %d vChrBufSize: %d\n",

                   vLumFilterSize,    vLumBufSize,    vChrFilterSize,    vChrBufSize);



    if (dstStride[0]%8 !=0 || dstStride[1]%8 !=0 || dstStride[2]%8 !=0 || dstStride[3]%8 != 0) {

        static int warnedAlready=0; //FIXME move this into the context perhaps

        if (flags & SWS_PRINT_INFO && !warnedAlready) {

            av_log(c, AV_LOG_WARNING, "Warning: dstStride is not aligned!\n"

                   "         ->cannot do aligned memory accesses anymore\n");

            warnedAlready=1;

        }

    }



    /* Note the user might start scaling the picture in the middle so this

       will not get executed. This is not really intended but works

       currently, so people might do it. */

    if (srcSliceY ==0) {

        lumBufIndex=-1;

        chrBufIndex=-1;

        dstY=0;

        lastInLumBuf= -1;

        lastInChrBuf= -1;

    }



    lastDstY= dstY;



    for (;dstY < dstH; dstY++) {

        unsigned char *dest =dst[0]+dstStride[0]*dstY;

        const int chrDstY= dstY>>c->chrDstVSubSample;

        unsigned char *uDest=dst[1]+dstStride[1]*chrDstY;

        unsigned char *vDest=dst[2]+dstStride[2]*chrDstY;

        unsigned char *aDest=(CONFIG_SWSCALE_ALPHA && alpPixBuf) ? dst[3]+dstStride[3]*dstY : NULL;



        const int firstLumSrcY= vLumFilterPos[dstY]; //First line needed as input

        const int firstLumSrcY2= vLumFilterPos[FFMIN(dstY | ((1<<c->chrDstVSubSample) - 1), dstH-1)];

        const int firstChrSrcY= vChrFilterPos[chrDstY]; //First line needed as input

        int lastLumSrcY= firstLumSrcY + vLumFilterSize -1; // Last line needed as input

        int lastLumSrcY2=firstLumSrcY2+ vLumFilterSize -1; // Last line needed as input

        int lastChrSrcY= firstChrSrcY + vChrFilterSize -1; // Last line needed as input

        int enough_lines;



        //handle holes (FAST_BILINEAR & weird filters)

        if (firstLumSrcY > lastInLumBuf) lastInLumBuf= firstLumSrcY-1;

        if (firstChrSrcY > lastInChrBuf) lastInChrBuf= firstChrSrcY-1;

        assert(firstLumSrcY >= lastInLumBuf - vLumBufSize + 1);

        assert(firstChrSrcY >= lastInChrBuf - vChrBufSize + 1);



        DEBUG_BUFFERS("dstY: %d\n", dstY);

        DEBUG_BUFFERS("\tfirstLumSrcY: %d lastLumSrcY: %d lastInLumBuf: %d\n",

                         firstLumSrcY,    lastLumSrcY,    lastInLumBuf);

        DEBUG_BUFFERS("\tfirstChrSrcY: %d lastChrSrcY: %d lastInChrBuf: %d\n",

                         firstChrSrcY,    lastChrSrcY,    lastInChrBuf);



        // Do we have enough lines in this slice to output the dstY line

        enough_lines = lastLumSrcY2 < srcSliceY + srcSliceH && lastChrSrcY < -((-srcSliceY - srcSliceH)>>c->chrSrcVSubSample);



        if (!enough_lines) {

            lastLumSrcY = srcSliceY + srcSliceH - 1;

            lastChrSrcY = chrSrcSliceY + chrSrcSliceH - 1;

            DEBUG_BUFFERS("buffering slice: lastLumSrcY %d lastChrSrcY %d\n",

                                            lastLumSrcY, lastChrSrcY);

        }



        //Do horizontal scaling

        while(lastInLumBuf < lastLumSrcY) {

            const uint8_t *src1= src[0]+(lastInLumBuf + 1 - srcSliceY)*srcStride[0];

            const uint8_t *src2= src[3]+(lastInLumBuf + 1 - srcSliceY)*srcStride[3];

            lumBufIndex++;

            assert(lumBufIndex < 2*vLumBufSize);

            assert(lastInLumBuf + 1 - srcSliceY < srcSliceH);

            assert(lastInLumBuf + 1 - srcSliceY >= 0);

            hyscale(c, lumPixBuf[ lumBufIndex ], dstW, src1, srcW, lumXInc,

                    hLumFilter, hLumFilterPos, hLumFilterSize,

                    formatConvBuffer,

                    pal, 0);

            if (CONFIG_SWSCALE_ALPHA && alpPixBuf)

                hyscale(c, alpPixBuf[ lumBufIndex ], dstW, src2, srcW,

                        lumXInc, hLumFilter, hLumFilterPos, hLumFilterSize,

                        formatConvBuffer,

                        pal, 1);

            lastInLumBuf++;

            DEBUG_BUFFERS("\t\tlumBufIndex %d: lastInLumBuf: %d\n",

                               lumBufIndex,    lastInLumBuf);

        }

        while(lastInChrBuf < lastChrSrcY) {

            const uint8_t *src1= src[1]+(lastInChrBuf + 1 - chrSrcSliceY)*srcStride[1];

            const uint8_t *src2= src[2]+(lastInChrBuf + 1 - chrSrcSliceY)*srcStride[2];

            chrBufIndex++;

            assert(chrBufIndex < 2*vChrBufSize);

            assert(lastInChrBuf + 1 - chrSrcSliceY < (chrSrcSliceH));

            assert(lastInChrBuf + 1 - chrSrcSliceY >= 0);

            //FIXME replace parameters through context struct (some at least)



            if (c->needs_hcscale)

                hcscale(c, chrUPixBuf[chrBufIndex], chrVPixBuf[chrBufIndex],

                          chrDstW, src1, src2, chrSrcW, chrXInc,

                          hChrFilter, hChrFilterPos, hChrFilterSize,

                          formatConvBuffer, pal);

            lastInChrBuf++;

            DEBUG_BUFFERS("\t\tchrBufIndex %d: lastInChrBuf: %d\n",

                               chrBufIndex,    lastInChrBuf);

        }

        //wrap buf index around to stay inside the ring buffer

        if (lumBufIndex >= vLumBufSize) lumBufIndex-= vLumBufSize;

        if (chrBufIndex >= vChrBufSize) chrBufIndex-= vChrBufSize;

        if (!enough_lines)

            break; //we can't output a dstY line so let's try with the next slice



#if HAVE_MMX

        updateMMXDitherTables(c, dstY, lumBufIndex, chrBufIndex, lastInLumBuf, lastInChrBuf);

#endif

        if (dstY >= dstH-2) {

            // hmm looks like we can't use MMX here without overwriting this array's tail

            find_c_packed_planar_out_funcs(c, &yuv2yuv1, &yuv2yuvX,

                                           &yuv2packed1, &yuv2packed2,

                                           &yuv2packedX);

        }



        {

            const int16_t **lumSrcPtr= (const int16_t **) lumPixBuf + lumBufIndex + firstLumSrcY - lastInLumBuf + vLumBufSize;

            const int16_t **chrUSrcPtr= (const int16_t **) chrUPixBuf + chrBufIndex + firstChrSrcY - lastInChrBuf + vChrBufSize;

            const int16_t **chrVSrcPtr= (const int16_t **) chrVPixBuf + chrBufIndex + firstChrSrcY - lastInChrBuf + vChrBufSize;

            const int16_t **alpSrcPtr= (CONFIG_SWSCALE_ALPHA && alpPixBuf) ? (const int16_t **) alpPixBuf + lumBufIndex + firstLumSrcY - lastInLumBuf + vLumBufSize : NULL;

            if (isPlanarYUV(dstFormat) || dstFormat==PIX_FMT_GRAY8) { //YV12 like

                const int chrSkipMask= (1<<c->chrDstVSubSample)-1;

                if ((dstY&chrSkipMask) || isGray(dstFormat)) uDest=vDest= NULL; //FIXME split functions in lumi / chromi

                if (c->yuv2yuv1 && vLumFilterSize == 1 && vChrFilterSize == 1) { // unscaled YV12

                    const int16_t *lumBuf = lumSrcPtr[0];

                    const int16_t *chrUBuf= chrUSrcPtr[0];

                    const int16_t *chrVBuf= chrVSrcPtr[0];

                    const int16_t *alpBuf= (CONFIG_SWSCALE_ALPHA && alpPixBuf) ? alpSrcPtr[0] : NULL;

                    yuv2yuv1(c, lumBuf, chrUBuf, chrVBuf, alpBuf, dest,

                                uDest, vDest, aDest, dstW, chrDstW);

                } else { //General YV12

                    yuv2yuvX(c,

                                vLumFilter+dstY*vLumFilterSize   , lumSrcPtr, vLumFilterSize,

                                vChrFilter+chrDstY*vChrFilterSize, chrUSrcPtr,

                                chrVSrcPtr, vChrFilterSize,

                                alpSrcPtr, dest, uDest, vDest, aDest, dstW, chrDstW);

                }

            } else {

                assert(lumSrcPtr  + vLumFilterSize - 1 < lumPixBuf  + vLumBufSize*2);

                assert(chrUSrcPtr + vChrFilterSize - 1 < chrUPixBuf + vChrBufSize*2);

                if (c->yuv2packed1 && vLumFilterSize == 1 && vChrFilterSize == 2) { //unscaled RGB

                    int chrAlpha= vChrFilter[2*dstY+1];

                    yuv2packed1(c, *lumSrcPtr, *chrUSrcPtr, *(chrUSrcPtr+1),

                                   *chrVSrcPtr, *(chrVSrcPtr+1),

                                   alpPixBuf ? *alpSrcPtr : NULL,

                                   dest, dstW, chrAlpha, dstFormat, flags, dstY);

                } else if (c->yuv2packed2 && vLumFilterSize == 2 && vChrFilterSize == 2) { //bilinear upscale RGB

                    int lumAlpha= vLumFilter[2*dstY+1];

                    int chrAlpha= vChrFilter[2*dstY+1];

                    lumMmxFilter[2]=

                    lumMmxFilter[3]= vLumFilter[2*dstY   ]*0x10001;

                    chrMmxFilter[2]=

                    chrMmxFilter[3]= vChrFilter[2*chrDstY]*0x10001;

                    yuv2packed2(c, *lumSrcPtr, *(lumSrcPtr+1), *chrUSrcPtr, *(chrUSrcPtr+1),

                                   *chrVSrcPtr, *(chrVSrcPtr+1),

                                   alpPixBuf ? *alpSrcPtr : NULL, alpPixBuf ? *(alpSrcPtr+1) : NULL,

                                   dest, dstW, lumAlpha, chrAlpha, dstY);

                } else { //general RGB

                    yuv2packedX(c,

                                   vLumFilter+dstY*vLumFilterSize, lumSrcPtr, vLumFilterSize,

                                   vChrFilter+dstY*vChrFilterSize, chrUSrcPtr, chrVSrcPtr, vChrFilterSize,

                                   alpSrcPtr, dest, dstW, dstY);

                }

            }

        }

    }



    if ((dstFormat == PIX_FMT_YUVA420P) && !alpPixBuf)

        fillPlane(dst[3], dstStride[3], dstW, dstY-lastDstY, lastDstY, 255);



#if HAVE_MMX2

    if (av_get_cpu_flags() & AV_CPU_FLAG_MMX2)

        __asm__ volatile("sfence":::"memory");

#endif

    emms_c();



    /* store changed local vars back in the context */

    c->dstY= dstY;

    c->lumBufIndex= lumBufIndex;

    c->chrBufIndex= chrBufIndex;

    c->lastInLumBuf= lastInLumBuf;

    c->lastInChrBuf= lastInChrBuf;



    return dstY - lastDstY;

}

int sws_setColorspaceDetails(struct SwsContext *c, const int inv_table[4],

                             int srcRange, const int table[4], int dstRange,

                             int brightness, int contrast, int saturation)

{

    const AVPixFmtDescriptor *desc_dst = av_pix_fmt_desc_get(c->dstFormat);

    const AVPixFmtDescriptor *desc_src = av_pix_fmt_desc_get(c->srcFormat);

    memcpy(c->srcColorspaceTable, inv_table, sizeof(int) * 4);

    memcpy(c->dstColorspaceTable, table, sizeof(int) * 4);



    c->brightness = brightness;

    c->contrast   = contrast;

    c->saturation = saturation;

    c->srcRange   = srcRange;

    c->dstRange   = dstRange;

    if (isYUV(c->dstFormat) || isGray(c->dstFormat))

        return -1;



    c->dstFormatBpp = av_get_bits_per_pixel(desc_dst);

    c->srcFormatBpp = av_get_bits_per_pixel(desc_src);



    ff_yuv2rgb_c_init_tables(c, inv_table, srcRange, brightness,

                             contrast, saturation);

    // FIXME factorize



    if (HAVE_ALTIVEC && av_get_cpu_flags() & AV_CPU_FLAG_ALTIVEC)

        ff_yuv2rgb_init_tables_altivec(c, inv_table, brightness,

                                       contrast, saturation);

    return 0;

}

static int submit_stats(AVCodecContext *avctx)

{

#ifdef TH_ENCCTL_2PASS_IN

    TheoraContext *h = avctx->priv_data;

    int bytes;


        if (!avctx->stats_in) {

            av_log(avctx, AV_LOG_ERROR, "No statsfile for second pass\n");

            return AVERROR(EINVAL);


        h->stats_size = strlen(avctx->stats_in) * 3/4;

        h->stats      = av_malloc(h->stats_size);





        h->stats_size = av_base64_decode(h->stats, avctx->stats_in, h->stats_size);


    while (h->stats_size - h->stats_offset > 0) {

        bytes = th_encode_ctl(h->t_state, TH_ENCCTL_2PASS_IN,

                              h->stats + h->stats_offset,

                              h->stats_size - h->stats_offset);

        if (bytes < 0) {

            av_log(avctx, AV_LOG_ERROR, "Error submitting stats\n");

            return AVERROR_EXTERNAL;


        if (!bytes)

            return 0;

        h->stats_offset += bytes;


    return 0;

#else

    av_log(avctx, AV_LOG_ERROR, "libtheora too old to support 2pass\n");

    return AVERROR(ENOSUP);

#endif

static int encode_plane(AVCodecContext *avctx, uint8_t *src,

                        uint8_t *dst, int stride,

                        int width, int height, PutByteContext *pb)

{

    UtvideoContext *c        = avctx->priv_data;

    uint8_t  lengths[256];

    uint64_t counts[256]     = { 0 };



    HuffEntry he[256];



    uint32_t offset = 0, slice_len = 0;

    int      i, sstart, send = 0;

    int      symbol;



    /* Do prediction / make planes */

    switch (c->frame_pred) {

    case PRED_NONE:

        for (i = 0; i < c->slices; i++) {

            sstart = send;

            send   = height * (i + 1) / c->slices;

            write_plane(src + sstart * stride, dst + sstart * width,

                        stride, width, send - sstart);

        }

        break;

    case PRED_LEFT:

        for (i = 0; i < c->slices; i++) {

            sstart = send;

            send   = height * (i + 1) / c->slices;

            left_predict(src + sstart * stride, dst + sstart * width,

                         stride, width, send - sstart);

        }

        break;

    case PRED_MEDIAN:

        for (i = 0; i < c->slices; i++) {

            sstart = send;

            send   = height * (i + 1) / c->slices;

            median_predict(c, src + sstart * stride, dst + sstart * width,

                           stride, width, send - sstart);

        }

        break;

    default:

        av_log(avctx, AV_LOG_ERROR, "Unknown prediction mode: %d\n",

               c->frame_pred);

        return AVERROR_OPTION_NOT_FOUND;

    }



    /* Count the usage of values */

    count_usage(dst, width, height, counts);



    /* Check for a special case where only one symbol was used */

    for (symbol = 0; symbol < 256; symbol++) {

        /* If non-zero count is found, see if it matches width * height */

        if (counts[symbol]) {

            /* Special case if only one symbol was used */

            if (counts[symbol] == width * height) {

                /*

                 * Write a zero for the single symbol

                 * used in the plane, else 0xFF.

                 */

                for (i = 0; i < 256; i++) {

                    if (i == symbol)

                        bytestream2_put_byte(pb, 0);

                    else

                        bytestream2_put_byte(pb, 0xFF);

                }



                /* Write zeroes for lengths */

                for (i = 0; i < c->slices; i++)

                    bytestream2_put_le32(pb, 0);



                /* And that's all for that plane folks */

                return 0;

            }

            break;

        }

    }



    /* Calculate huffman lengths */

    ff_huff_gen_len_table(lengths, counts);



    /*

     * Write the plane's header into the output packet:

     * - huffman code lengths (256 bytes)

     * - slice end offsets (gotten from the slice lengths)

     */

    for (i = 0; i < 256; i++) {

        bytestream2_put_byte(pb, lengths[i]);



        he[i].len = lengths[i];

        he[i].sym = i;

    }



    /* Calculate the huffman codes themselves */

    calculate_codes(he);



    send = 0;

    for (i = 0; i < c->slices; i++) {

        sstart  = send;

        send    = height * (i + 1) / c->slices;



        /*

         * Write the huffman codes to a buffer,

         * get the offset in bits and convert to bytes.

         */

        offset += write_huff_codes(dst + sstart * width, c->slice_bits,

                                   width * (send - sstart), width,

                                   send - sstart, he) >> 3;



        slice_len = offset - slice_len;



        /* Byteswap the written huffman codes */

        c->dsp.bswap_buf((uint32_t *) c->slice_bits,

                         (uint32_t *) c->slice_bits,

                         slice_len >> 2);



        /* Write the offset to the stream */

        bytestream2_put_le32(pb, offset);



        /* Seek to the data part of the packet */

        bytestream2_seek_p(pb, 4 * (c->slices - i - 1) +

                           offset - slice_len, SEEK_CUR);



        /* Write the slices' data into the output packet */

        bytestream2_put_buffer(pb, c->slice_bits, slice_len);



        /* Seek back to the slice offsets */

        bytestream2_seek_p(pb, -4 * (c->slices - i - 1) - offset,

                           SEEK_CUR);



        slice_len = offset;

    }



    /* And at the end seek to the end of written slice(s) */

    bytestream2_seek_p(pb, offset, SEEK_CUR);



    return 0;

}

static av_cold int g726_encode_init(AVCodecContext *avctx)

{

    G726Context* c = avctx->priv_data;



    if (avctx->strict_std_compliance > FF_COMPLIANCE_UNOFFICIAL &&

        avctx->sample_rate != 8000) {

        av_log(avctx, AV_LOG_ERROR, "Sample rates other than 8kHz are not "

               "allowed when the compliance level is higher than unofficial. "

               "Resample or reduce the compliance level.\n");

        return AVERROR(EINVAL);

    }

    av_assert0(avctx->sample_rate > 0);



    if(avctx->channels != 1){

        av_log(avctx, AV_LOG_ERROR, "Only mono is supported\n");

        return -1;

    }



    if (avctx->bit_rate % avctx->sample_rate) {

        av_log(avctx, AV_LOG_ERROR, "Bitrate - Samplerate combination is invalid\n");

        return AVERROR(EINVAL);

    }

    c->code_size = (avctx->bit_rate + avctx->sample_rate/2) / avctx->sample_rate;

    if (c->code_size < 2 || c->code_size > 5) {

        av_log(avctx, AV_LOG_ERROR, "Invalid number of bits %d\n", c->code_size);

        return AVERROR(EINVAL);

    }

    avctx->bits_per_coded_sample = c->code_size;



    g726_reset(c, c->code_size - 2);



    avctx->coded_frame = avcodec_alloc_frame();

    if (!avctx->coded_frame)

        return AVERROR(ENOMEM);

    avctx->coded_frame->key_frame = 1;



    /* select a frame size that will end on a byte boundary and have a size of

       approximately 1024 bytes */

    avctx->frame_size = ((int[]){ 4096, 2736, 2048, 1640 })[c->code_size - 2];



    return 0;

}

static int decode_dc_progressive(MJpegDecodeContext *s, int16_t *block,

                                 int component, int dc_index,

                                 uint16_t *quant_matrix, int Al)

{

    int val;

    s->bdsp.clear_block(block);

    val = mjpeg_decode_dc(s, dc_index);

    if (val == 0xfffff) {

        av_log(s->avctx, AV_LOG_ERROR, "error dc\n");

        return AVERROR_INVALIDDATA;

    }

    val = (val * (quant_matrix[0] << Al)) + s->last_dc[component];

    s->last_dc[component] = val;

    block[0] = val;

    return 0;

}

static void vp7_idct_add_c(uint8_t *dst, int16_t block[16], ptrdiff_t stride)

{

    int i, a1, b1, c1, d1;

    int16_t tmp[16];



    for (i = 0; i < 4; i++) {

        a1 = (block[i * 4 + 0] + block[i * 4 + 2]) * 23170;

        b1 = (block[i * 4 + 0] - block[i * 4 + 2]) * 23170;

        c1 = block[i * 4 + 1] * 12540 - block[i * 4 + 3] * 30274;

        d1 = block[i * 4 + 1] * 30274 + block[i * 4 + 3] * 12540;

        AV_ZERO64(block + i * 4);

        tmp[i * 4 + 0] = (a1 + d1) >> 14;

        tmp[i * 4 + 3] = (a1 - d1) >> 14;

        tmp[i * 4 + 1] = (b1 + c1) >> 14;

        tmp[i * 4 + 2] = (b1 - c1) >> 14;

    }



    for (i = 0; i < 4; i++) {

        a1 = (tmp[i + 0] + tmp[i + 8]) * 23170;

        b1 = (tmp[i + 0] - tmp[i + 8]) * 23170;

        c1 = tmp[i + 4] * 12540 - tmp[i + 12] * 30274;

        d1 = tmp[i + 4] * 30274 + tmp[i + 12] * 12540;

        dst[0 * stride + i] = av_clip_uint8(dst[0 * stride + i] +

                                            ((a1 + d1 + 0x20000) >> 18));

        dst[3 * stride + i] = av_clip_uint8(dst[3 * stride + i] +

                                            ((a1 - d1 + 0x20000) >> 18));

        dst[1 * stride + i] = av_clip_uint8(dst[1 * stride + i] +

                                            ((b1 + c1 + 0x20000) >> 18));

        dst[2 * stride + i] = av_clip_uint8(dst[2 * stride + i] +

                                            ((b1 - c1 + 0x20000) >> 18));

    }

}

void ff_er_add_slice(ERContext *s, int startx, int starty,

                     int endx, int endy, int status)

{

    const int start_i  = av_clip(startx + starty * s->mb_width, 0, s->mb_num - 1);

    const int end_i    = av_clip(endx   + endy   * s->mb_width, 0, s->mb_num);

    const int start_xy = s->mb_index2xy[start_i];

    const int end_xy   = s->mb_index2xy[end_i];

    int mask           = -1;



    if (s->avctx->hwaccel && s->avctx->hwaccel->decode_slice)

        return;



    if (start_i > end_i || start_xy > end_xy) {

        av_log(s->avctx, AV_LOG_ERROR,

               "internal error, slice end before start\n");

        return;

    }



    if (!s->avctx->error_concealment)

        return;



    mask &= ~VP_START;

    if (status & (ER_AC_ERROR | ER_AC_END)) {

        mask           &= ~(ER_AC_ERROR | ER_AC_END);

        s->error_count -= end_i - start_i + 1;

    }

    if (status & (ER_DC_ERROR | ER_DC_END)) {

        mask           &= ~(ER_DC_ERROR | ER_DC_END);

        s->error_count -= end_i - start_i + 1;

    }

    if (status & (ER_MV_ERROR | ER_MV_END)) {

        mask           &= ~(ER_MV_ERROR | ER_MV_END);

        s->error_count -= end_i - start_i + 1;

    }



    if (status & ER_MB_ERROR) {

        s->error_occurred = 1;

        s->error_count    = INT_MAX;

    }



    if (mask == ~0x7F) {

        memset(&s->error_status_table[start_xy], 0,

               (end_xy - start_xy) * sizeof(uint8_t));

    } else {

        int i;

        for (i = start_xy; i < end_xy; i++)

            s->error_status_table[i] &= mask;

    }



    if (end_i == s->mb_num)

        s->error_count = INT_MAX;

    else {

        s->error_status_table[end_xy] &= mask;

        s->error_status_table[end_xy] |= status;

    }



    s->error_status_table[start_xy] |= VP_START;



    if (start_xy > 0 && !(s->avctx->active_thread_type & FF_THREAD_SLICE) &&

        er_supported(s) && s->avctx->skip_top * s->mb_width < start_i) {

        int prev_status = s->error_status_table[s->mb_index2xy[start_i - 1]];



        prev_status &= ~ VP_START;

        if (prev_status != (ER_MV_END | ER_DC_END | ER_AC_END)) {

            s->error_occurred = 1;

            s->error_count = INT_MAX;

        }

    }

}

static inline void RENAME(yuv2yuvX)(SwsContext *c, const int16_t *lumFilter,

                                    const int16_t **lumSrc, int lumFilterSize,

                                    const int16_t *chrFilter, const int16_t **chrUSrc,

                                    const int16_t **chrVSrc,

                                    int chrFilterSize, const int16_t **alpSrc,

                                    uint8_t *dest, uint8_t *uDest, uint8_t *vDest,

                                    uint8_t *aDest, long dstW, long chrDstW)

{

    if (uDest) {

        YSCALEYUV2YV12X(CHR_MMX_FILTER_OFFSET, uDest, chrDstW, 0)

        YSCALEYUV2YV12X(CHR_MMX_FILTER_OFFSET, vDest, chrDstW + c->uv_off, c->uv_off)

    }

    if (CONFIG_SWSCALE_ALPHA && aDest) {

        YSCALEYUV2YV12X(ALP_MMX_FILTER_OFFSET, aDest, dstW, 0)

    }



    YSCALEYUV2YV12X(LUM_MMX_FILTER_OFFSET, dest, dstW, 0)

}

