static void filter_mb( H264Context *h, int mb_x, int mb_y ) {

    MpegEncContext * const s = &h->s;

    const int mb_xy= mb_x + mb_y*s->mb_stride;

    uint8_t *img_y  = s->current_picture.data[0] + (mb_y * 16* s->linesize  ) + mb_x * 16;

    uint8_t *img_cb = s->current_picture.data[1] + (mb_y * 8 * s->uvlinesize) + mb_x * 8;

    uint8_t *img_cr = s->current_picture.data[2] + (mb_y * 8 * s->uvlinesize) + mb_x * 8;

    int linesize, uvlinesize;

    int dir;

#if 0

    /* FIXME what's that ? */

    if( !s->decode )

        return;

#endif



    /* FIXME Implement deblocking filter for field MB */

    if( h->sps.mb_aff ) {

        return;

    }

    linesize = s->linesize;

    uvlinesize = s->uvlinesize;



    /* dir : 0 -> vertical edge, 1 -> horizontal edge */

    for( dir = 0; dir < 2; dir++ )

    {

        int start = 0;

        int edge;



        /* test picture boundary */

        if( ( dir == 0 && mb_x == 0 ) || ( dir == 1 && mb_y == 0 ) ) {

            start = 1;

        }

        /* FIXME test slice boundary */

        if( h->disable_deblocking_filter_idc == 2 ) {

        }



        /* Calculate bS */

        for( edge = start; edge < 4; edge++ ) {

            /* mbn_xy: neighbour macroblock (how that works for field ?) */

            int mbn_xy = edge > 0 ? mb_xy : ( dir == 0 ? mb_xy -1 : mb_xy - s->mb_stride );

            int bS[4];

            int qp;



            if( IS_INTRA( s->current_picture.mb_type[mb_xy] ) ||

                IS_INTRA( s->current_picture.mb_type[mbn_xy] ) ) {

                bS[0] = bS[1] = bS[2] = bS[3] = ( edge == 0 ? 4 : 3 );

            } else {

                int i;

                for( i = 0; i < 4; i++ ) {

                    static const uint8_t block_idx_xy[4][4] = {

                        { 0, 2, 8,  10}, { 1, 3, 9,  11},

                        { 4, 6, 12, 14}, { 5, 7, 13, 15}

                    };



                    int x = dir == 0 ? edge : i;

                    int y = dir == 0 ? i    : edge;

                    int xn = (x - (dir == 0 ? 1 : 0 ))&0x03;

                    int yn = (y - (dir == 0 ? 0 : 1 ))&0x03;



                    if( h->non_zero_count[mb_xy][block_idx_xy[x][y]] != 0 ||

                        h->non_zero_count[mbn_xy][block_idx_xy[xn][yn]] != 0 ) {

                        bS[i] = 2;

                    }

                    else if( h->slice_type == P_TYPE ) {

                        const int b8_xy = h->mb2b8_xy[mb_xy]+(y>>1)*h->b8_stride+(x>>1);

                        const int b8n_xy= h->mb2b8_xy[mbn_xy]+(yn>>1)*h->b8_stride+(xn>>1);

                        const int b_xy  = h->mb2b_xy[mb_xy]+y*h->b_stride+x;

                        const int bn_xy = h->mb2b_xy[mbn_xy]+yn*h->b_stride+xn;

                        if( s->current_picture.ref_index[0][b8_xy] != s->current_picture.ref_index[0][b8n_xy] ||

                            ABS( s->current_picture.motion_val[0][b_xy][0] - s->current_picture.motion_val[0][bn_xy][0] ) >= 4 ||

                            ABS( s->current_picture.motion_val[0][b_xy][1] - s->current_picture.motion_val[0][bn_xy][1] ) >= 4 )

                            bS[i] = 1;

                        else

                            bS[i] = 0;

                    }

                    else {

                        /* FIXME Add support for B frame */

                        return;

                    }

                }

            }



            /* Filter edge */

            qp = ( s->current_picture.qscale_table[mb_xy] + s->current_picture.qscale_table[mbn_xy] + 1 ) >> 1;

            if( dir == 0 ) {

                filter_mb_edgev( h, &img_y[4*edge], linesize, bS, qp );

                if( (edge&1) == 0 ) {

                    int chroma_qp = ( get_chroma_qp( h, s->current_picture.qscale_table[mb_xy] ) +

                                      get_chroma_qp( h, s->current_picture.qscale_table[mbn_xy] ) + 1 ) >> 1;

                    filter_mb_edgecv( h, &img_cb[2*edge], uvlinesize, bS, chroma_qp );

                    filter_mb_edgecv( h, &img_cr[2*edge], uvlinesize, bS, chroma_qp );

                }

            } else {

                filter_mb_edgeh( h, &img_y[4*edge*linesize], linesize, bS, qp );

                if( (edge&1) == 0 ) {

                    int chroma_qp = ( get_chroma_qp( h, s->current_picture.qscale_table[mb_xy] ) +

                                      get_chroma_qp( h, s->current_picture.qscale_table[mbn_xy] ) + 1 ) >> 1;

                    filter_mb_edgech( h, &img_cb[2*edge*uvlinesize], uvlinesize, bS, chroma_qp );

                    filter_mb_edgech( h, &img_cr[2*edge*uvlinesize], uvlinesize, bS, chroma_qp );

                }

            }

        }

    }

}

void mpeg_motion_internal(MpegEncContext *s,

                          uint8_t *dest_y,

                          uint8_t *dest_cb,

                          uint8_t *dest_cr,

                          int field_based,

                          int bottom_field,

                          int field_select,

                          uint8_t **ref_picture,

                          op_pixels_func (*pix_op)[4],

                          int motion_x,

                          int motion_y,

                          int h,

                          int is_mpeg12,

                          int mb_y)

{

    uint8_t *ptr_y, *ptr_cb, *ptr_cr;

    int dxy, uvdxy, mx, my, src_x, src_y,

        uvsrc_x, uvsrc_y, v_edge_pos;

    ptrdiff_t uvlinesize, linesize;



#if 0

    if (s->quarter_sample) {

        motion_x >>= 1;

        motion_y >>= 1;

    }

#endif



    v_edge_pos = s->v_edge_pos >> field_based;

    linesize   = s->current_picture.f.linesize[0] << field_based;

    uvlinesize = s->current_picture.f.linesize[1] << field_based;



    dxy   = ((motion_y & 1) << 1) | (motion_x & 1);

    src_x = s->mb_x * 16 + (motion_x >> 1);

    src_y = (mb_y << (4 - field_based)) + (motion_y >> 1);



    if (!is_mpeg12 && s->out_format == FMT_H263) {

        if ((s->workaround_bugs & FF_BUG_HPEL_CHROMA) && field_based) {

            mx      = (motion_x >> 1) | (motion_x & 1);

            my      = motion_y >> 1;

            uvdxy   = ((my & 1) << 1) | (mx & 1);

            uvsrc_x = s->mb_x * 8 + (mx >> 1);

            uvsrc_y = (mb_y << (3 - field_based)) + (my >> 1);

        } else {

            uvdxy   = dxy | (motion_y & 2) | ((motion_x & 2) >> 1);

            uvsrc_x = src_x >> 1;

            uvsrc_y = src_y >> 1;

        }

    // Even chroma mv's are full pel in H261

    } else if (!is_mpeg12 && s->out_format == FMT_H261) {

        mx      = motion_x / 4;

        my      = motion_y / 4;

        uvdxy   = 0;

        uvsrc_x = s->mb_x * 8 + mx;

        uvsrc_y = mb_y * 8 + my;

    } else {

        if (s->chroma_y_shift) {

            mx      = motion_x / 2;

            my      = motion_y / 2;

            uvdxy   = ((my & 1) << 1) | (mx & 1);

            uvsrc_x = s->mb_x * 8 + (mx >> 1);

            uvsrc_y = (mb_y << (3 - field_based)) + (my >> 1);

        } else {

            if (s->chroma_x_shift) {

                // Chroma422

                mx      = motion_x / 2;

                uvdxy   = ((motion_y & 1) << 1) | (mx & 1);

                uvsrc_x = s->mb_x * 8 + (mx >> 1);

                uvsrc_y = src_y;

            } else {

                // Chroma444

                uvdxy   = dxy;

                uvsrc_x = src_x;

                uvsrc_y = src_y;

            }

        }

    }



    ptr_y  = ref_picture[0] + src_y * linesize + src_x;

    ptr_cb = ref_picture[1] + uvsrc_y * uvlinesize + uvsrc_x;

    ptr_cr = ref_picture[2] + uvsrc_y * uvlinesize + uvsrc_x;



    if ((unsigned)src_x > FFMAX(s->h_edge_pos - (motion_x & 1) - 16, 0) ||

        (unsigned)src_y > FFMAX(v_edge_pos - (motion_y & 1) - h, 0)) {

        if (is_mpeg12 ||

            s->codec_id == AV_CODEC_ID_MPEG2VIDEO ||

            s->codec_id == AV_CODEC_ID_MPEG1VIDEO) {

            av_log(s->avctx, AV_LOG_DEBUG,

                   "MPEG motion vector out of boundary (%d %d)\n", src_x,

                   src_y);

            return;

        }

        s->vdsp.emulated_edge_mc(s->edge_emu_buffer, ptr_y,

                                 s->linesize, s->linesize,

                                 17, 17 + field_based,

                                 src_x, src_y << field_based,

                                 s->h_edge_pos, s->v_edge_pos);

        ptr_y = s->edge_emu_buffer;

        if (!CONFIG_GRAY || !(s->flags & CODEC_FLAG_GRAY)) {

            uint8_t *uvbuf = s->edge_emu_buffer + 18 * s->linesize;

            s->vdsp.emulated_edge_mc(uvbuf, ptr_cb,

                                     s->uvlinesize, s->uvlinesize,

                                     9, 9 + field_based,

                                     uvsrc_x, uvsrc_y << field_based,

                                     s->h_edge_pos >> 1, s->v_edge_pos >> 1);

            s->vdsp.emulated_edge_mc(uvbuf + 16, ptr_cr,

                                     s->uvlinesize, s->uvlinesize,

                                     9, 9 + field_based,

                                     uvsrc_x, uvsrc_y << field_based,

                                     s->h_edge_pos >> 1, s->v_edge_pos >> 1);

            ptr_cb = uvbuf;

            ptr_cr = uvbuf + 16;

        }

    }



    /* FIXME use this for field pix too instead of the obnoxious hack which

     * changes picture.data */

    if (bottom_field) {

        dest_y  += s->linesize;

        dest_cb += s->uvlinesize;

        dest_cr += s->uvlinesize;

    }



    if (field_select) {

        ptr_y  += s->linesize;

        ptr_cb += s->uvlinesize;

        ptr_cr += s->uvlinesize;

    }



    pix_op[0][dxy](dest_y, ptr_y, linesize, h);



    if (!CONFIG_GRAY || !(s->flags & CODEC_FLAG_GRAY)) {

        pix_op[s->chroma_x_shift][uvdxy]

            (dest_cb, ptr_cb, uvlinesize, h >> s->chroma_y_shift);

        pix_op[s->chroma_x_shift][uvdxy]

            (dest_cr, ptr_cr, uvlinesize, h >> s->chroma_y_shift);

    }

    if (!is_mpeg12 && (CONFIG_H261_ENCODER || CONFIG_H261_DECODER) &&

        s->out_format == FMT_H261) {

        ff_h261_loop_filter(s);

    }

}

static av_cold int vp9_decode_free(AVCodecContext *ctx)

{

    VP9Context *s = ctx->priv_data;

    int i;



    for (i = 0; i < 2; i++) {

        if (s->frames[i].tf.f->data[0])

            vp9_unref_frame(ctx, &s->frames[i]);

        av_frame_free(&s->frames[i].tf.f);

    }

    for (i = 0; i < 8; i++) {

        if (s->refs[i].f->data[0])

            ff_thread_release_buffer(ctx, &s->refs[i]);

        av_frame_free(&s->refs[i].f);

        if (s->next_refs[i].f->data[0])

            ff_thread_release_buffer(ctx, &s->next_refs[i]);

        av_frame_free(&s->next_refs[i].f);

    }

    av_freep(&s->above_partition_ctx);

    av_freep(&s->c_b);

    s->c_b_size = 0;

    av_freep(&s->b_base);

    av_freep(&s->block_base);



    return 0;

}

static int ffm_read_header(AVFormatContext *s)

{

    FFMContext *ffm = s->priv_data;

    AVStream *st;

    AVIOContext *pb = s->pb;

    AVCodecContext *codec;

    const AVCodecDescriptor *codec_desc;

    int i, nb_streams;

    uint32_t tag;



    /* header */

    tag = avio_rl32(pb);

    if (tag == MKTAG('F', 'F', 'M', '2'))

        return ffm2_read_header(s);

    if (tag != MKTAG('F', 'F', 'M', '1'))


    ffm->packet_size = avio_rb32(pb);

    if (ffm->packet_size != FFM_PACKET_SIZE)


    ffm->write_index = avio_rb64(pb);

    /* get also filesize */

    if (pb->seekable) {

        ffm->file_size = avio_size(pb);

        if (ffm->write_index && 0)

            adjust_write_index(s);

    } else {

        ffm->file_size = (UINT64_C(1) << 63) - 1;




    nb_streams = avio_rb32(pb);

    avio_rb32(pb); /* total bitrate */

    /* read each stream */

    for(i=0;i<nb_streams;i++) {

        char rc_eq_buf[128];



        st = avformat_new_stream(s, NULL);

        if (!st)




        avpriv_set_pts_info(st, 64, 1, 1000000);



        codec = st->codec;

        /* generic info */

        codec->codec_id = avio_rb32(pb);

        codec_desc = avcodec_descriptor_get(codec->codec_id);

        if (!codec_desc) {

            av_log(s, AV_LOG_ERROR, "Invalid codec id: %d\n", codec->codec_id);

            codec->codec_id = AV_CODEC_ID_NONE;



        codec->codec_type = avio_r8(pb); /* codec_type */

        if (codec->codec_type != codec_desc->type) {

            av_log(s, AV_LOG_ERROR, "Codec type mismatch: expected %d, found %d\n",

                   codec_desc->type, codec->codec_type);

            codec->codec_id = AV_CODEC_ID_NONE;

            codec->codec_type = AVMEDIA_TYPE_UNKNOWN;



        codec->bit_rate = avio_rb32(pb);

        codec->flags = avio_rb32(pb);

        codec->flags2 = avio_rb32(pb);

        codec->debug = avio_rb32(pb);

        /* specific info */

        switch(codec->codec_type) {

        case AVMEDIA_TYPE_VIDEO:

            codec->time_base.num = avio_rb32(pb);

            codec->time_base.den = avio_rb32(pb);

            if (codec->time_base.num <= 0 || codec->time_base.den <= 0) {

                av_log(s, AV_LOG_ERROR, "Invalid time base %d/%d\n",

                       codec->time_base.num, codec->time_base.den);



            codec->width = avio_rb16(pb);

            codec->height = avio_rb16(pb);

            codec->gop_size = avio_rb16(pb);

            codec->pix_fmt = avio_rb32(pb);






            codec->qmin = avio_r8(pb);

            codec->qmax = avio_r8(pb);

            codec->max_qdiff = avio_r8(pb);

            codec->qcompress = avio_rb16(pb) / 10000.0;

            codec->qblur = avio_rb16(pb) / 10000.0;

            codec->bit_rate_tolerance = avio_rb32(pb);

            avio_get_str(pb, INT_MAX, rc_eq_buf, sizeof(rc_eq_buf));

            codec->rc_eq = av_strdup(rc_eq_buf);

            codec->rc_max_rate = avio_rb32(pb);

            codec->rc_min_rate = avio_rb32(pb);

            codec->rc_buffer_size = avio_rb32(pb);

            codec->i_quant_factor = av_int2double(avio_rb64(pb));

            codec->b_quant_factor = av_int2double(avio_rb64(pb));

            codec->i_quant_offset = av_int2double(avio_rb64(pb));

            codec->b_quant_offset = av_int2double(avio_rb64(pb));

            codec->dct_algo = avio_rb32(pb);

            codec->strict_std_compliance = avio_rb32(pb);

            codec->max_b_frames = avio_rb32(pb);

            codec->mpeg_quant = avio_rb32(pb);

            codec->intra_dc_precision = avio_rb32(pb);

            codec->me_method = avio_rb32(pb);

            codec->mb_decision = avio_rb32(pb);

            codec->nsse_weight = avio_rb32(pb);

            codec->frame_skip_cmp = avio_rb32(pb);

            codec->rc_buffer_aggressivity = av_int2double(avio_rb64(pb));

            codec->codec_tag = avio_rb32(pb);

            codec->thread_count = avio_r8(pb);

            codec->coder_type = avio_rb32(pb);

            codec->me_cmp = avio_rb32(pb);

            codec->me_subpel_quality = avio_rb32(pb);

            codec->me_range = avio_rb32(pb);

            codec->keyint_min = avio_rb32(pb);

            codec->scenechange_threshold = avio_rb32(pb);

            codec->b_frame_strategy = avio_rb32(pb);

            codec->qcompress = av_int2double(avio_rb64(pb));

            codec->qblur = av_int2double(avio_rb64(pb));

            codec->max_qdiff = avio_rb32(pb);

            codec->refs = avio_rb32(pb);

            break;

        case AVMEDIA_TYPE_AUDIO:

            codec->sample_rate = avio_rb32(pb);

            codec->channels = avio_rl16(pb);

            codec->frame_size = avio_rl16(pb);

            break;

        default:



        if (codec->flags & AV_CODEC_FLAG_GLOBAL_HEADER) {

            int size = avio_rb32(pb);

            codec->extradata = av_mallocz(size + AV_INPUT_BUFFER_PADDING_SIZE);

            if (!codec->extradata)

                return AVERROR(ENOMEM);

            codec->extradata_size = size;

            avio_read(pb, codec->extradata, size);




        avcodec_parameters_from_context(st->codecpar, codec);




    /* get until end of block reached */

    while ((avio_tell(pb) % ffm->packet_size) != 0 && !pb->eof_reached)

        avio_r8(pb);



    /* init packet demux */

    ffm->packet_ptr = ffm->packet;

    ffm->packet_end = ffm->packet;

    ffm->frame_offset = 0;

    ffm->dts = 0;

    ffm->read_state = READ_HEADER;

    ffm->first_packet = 1;

    return 0;

 fail:

    ffm_close(s);

    return -1;

static int sdp_read_header(AVFormatContext *s)

{

    RTSPState *rt = s->priv_data;

    RTSPStream *rtsp_st;

    int size, i, err;

    char *content;

    char url[1024];



    if (!ff_network_init())

        return AVERROR(EIO);



    if (s->max_delay < 0) /* Not set by the caller */

        s->max_delay = DEFAULT_REORDERING_DELAY;

    if (rt->rtsp_flags & RTSP_FLAG_CUSTOM_IO)

        rt->lower_transport = RTSP_LOWER_TRANSPORT_CUSTOM;



    /* read the whole sdp file */

    /* XXX: better loading */

    content = av_malloc(SDP_MAX_SIZE);



    size = avio_read(s->pb, content, SDP_MAX_SIZE - 1);

    if (size <= 0) {

        av_free(content);

        return AVERROR_INVALIDDATA;

    }

    content[size] ='\0';



    err = ff_sdp_parse(s, content);

    av_freep(&content);

    if (err) goto fail;



    /* open each RTP stream */

    for (i = 0; i < rt->nb_rtsp_streams; i++) {

        char namebuf[50];

        rtsp_st = rt->rtsp_streams[i];



        if (!(rt->rtsp_flags & RTSP_FLAG_CUSTOM_IO)) {

            AVDictionary *opts = map_to_opts(rt);



            getnameinfo((struct sockaddr*) &rtsp_st->sdp_ip, sizeof(rtsp_st->sdp_ip),

                        namebuf, sizeof(namebuf), NULL, 0, NI_NUMERICHOST);

            ff_url_join(url, sizeof(url), "rtp", NULL,

                        namebuf, rtsp_st->sdp_port,

                        "?localport=%d&ttl=%d&connect=%d&write_to_source=%d",

                        rtsp_st->sdp_port, rtsp_st->sdp_ttl,

                        rt->rtsp_flags & RTSP_FLAG_FILTER_SRC ? 1 : 0,

                        rt->rtsp_flags & RTSP_FLAG_RTCP_TO_SOURCE ? 1 : 0);



            append_source_addrs(url, sizeof(url), "sources",

                                rtsp_st->nb_include_source_addrs,

                                rtsp_st->include_source_addrs);

            append_source_addrs(url, sizeof(url), "block",

                                rtsp_st->nb_exclude_source_addrs,

                                rtsp_st->exclude_source_addrs);

            err = ffurl_open(&rtsp_st->rtp_handle, url, AVIO_FLAG_READ_WRITE,

                           &s->interrupt_callback, &opts);



            av_dict_free(&opts);



            if (err < 0) {

                err = AVERROR_INVALIDDATA;

                goto fail;

            }

        }

        if ((err = ff_rtsp_open_transport_ctx(s, rtsp_st)))

            goto fail;

    }

    return 0;

fail:

    ff_rtsp_close_streams(s);

    ff_network_close();

    return err;

}

static int mov_create_chapter_track(AVFormatContext *s, int tracknum)

{

    MOVMuxContext *mov = s->priv_data;

    MOVTrack *track = &mov->tracks[tracknum];

    AVPacket pkt = { .stream_index = tracknum, .flags = AV_PKT_FLAG_KEY };

    int i, len;

    // These properties are required to make QT recognize the chapter track

    uint8_t chapter_properties[43] = { 0, 0, 0, 0, 0, 0, 0, 1, };



    track->mode = mov->mode;

    track->tag = MKTAG('t','e','x','t');

    track->timescale = MOV_TIMESCALE;

    track->enc = avcodec_alloc_context3(NULL);

    if (!track->enc)


    track->enc->codec_type = AVMEDIA_TYPE_SUBTITLE;

    track->enc->extradata = av_malloc(sizeof(chapter_properties));

    if (track->enc->extradata == NULL)


    track->enc->extradata_size = sizeof(chapter_properties);

    memcpy(track->enc->extradata, chapter_properties, sizeof(chapter_properties));



    for (i = 0; i < s->nb_chapters; i++) {

        AVChapter *c = s->chapters[i];

        AVDictionaryEntry *t;



        int64_t end = av_rescale_q(c->end, c->time_base, (AVRational){1,MOV_TIMESCALE});

        pkt.pts = pkt.dts = av_rescale_q(c->start, c->time_base, (AVRational){1,MOV_TIMESCALE});

        pkt.duration = end - pkt.dts;



        if ((t = av_dict_get(c->metadata, "title", NULL, 0))) {

            len      = strlen(t->value);

            pkt.size = len + 2;

            pkt.data = av_malloc(pkt.size);



            AV_WB16(pkt.data, len);

            memcpy(pkt.data + 2, t->value, len);

            ff_mov_write_packet(s, &pkt);

            av_freep(&pkt.data);

        }

    }



    return 0;

}

static void compute_rematrixing_strategy(AC3EncodeContext *s)

{

    int nb_coefs;

    int blk, bnd, i;

    AC3Block *block, *av_uninit(block0);



    if (s->channel_mode != AC3_CHMODE_STEREO)

        return;



    for (blk = 0; blk < AC3_MAX_BLOCKS; blk++) {

        block = &s->blocks[blk];

        block->new_rematrixing_strategy = !blk;



        if (!s->rematrixing_enabled) {

            block0 = block;

            continue;

        }



        block->num_rematrixing_bands = 4;

        if (block->cpl_in_use) {

            block->num_rematrixing_bands -= (s->start_freq[CPL_CH] <= 61);

            block->num_rematrixing_bands -= (s->start_freq[CPL_CH] == 37);

            if (blk && block->num_rematrixing_bands != block0->num_rematrixing_bands)

                block->new_rematrixing_strategy = 1;

        }

        nb_coefs = FFMIN(block->end_freq[1], block->end_freq[2]);



        for (bnd = 0; bnd < block->num_rematrixing_bands; bnd++) {

            /* calculate calculate sum of squared coeffs for one band in one block */

            int start = ff_ac3_rematrix_band_tab[bnd];

            int end   = FFMIN(nb_coefs, ff_ac3_rematrix_band_tab[bnd+1]);

            CoefSumType sum[4] = {0,};

            for (i = start; i < end; i++) {

                CoefType lt = block->mdct_coef[1][i];

                CoefType rt = block->mdct_coef[2][i];

                CoefType md = lt + rt;

                CoefType sd = lt - rt;

                MAC_COEF(sum[0], lt, lt);

                MAC_COEF(sum[1], rt, rt);

                MAC_COEF(sum[2], md, md);

                MAC_COEF(sum[3], sd, sd);

            }



            /* compare sums to determine if rematrixing will be used for this band */

            if (FFMIN(sum[2], sum[3]) < FFMIN(sum[0], sum[1]))

                block->rematrixing_flags[bnd] = 1;

            else

                block->rematrixing_flags[bnd] = 0;



            /* determine if new rematrixing flags will be sent */

            if (blk &&

                block->rematrixing_flags[bnd] != block0->rematrixing_flags[bnd]) {

                block->new_rematrixing_strategy = 1;

            }

        }

        block0 = block;

    }

}

int ff_msmpeg4_pred_dc(MpegEncContext *s, int n,

                       int16_t **dc_val_ptr, int *dir_ptr)

{

    int a, b, c, wrap, pred, scale;

    int16_t *dc_val;



    /* find prediction */

    if (n < 4) {

        scale = s->y_dc_scale;

    } else {

        scale = s->c_dc_scale;

    }



    wrap = s->block_wrap[n];

    dc_val= s->dc_val[0] + s->block_index[n];



    /* B C

     * A X

     */

    a = dc_val[ - 1];

    b = dc_val[ - 1 - wrap];

    c = dc_val[ - wrap];



    if(s->first_slice_line && (n&2)==0 && s->msmpeg4_version<4){

        b=c=1024;

    }



    /* XXX: the following solution consumes divisions, but it does not

       necessitate to modify mpegvideo.c. The problem comes from the

       fact they decided to store the quantized DC (which would lead

       to problems if Q could vary !) */

#if ARCH_X86 && HAVE_7REGS && HAVE_EBX_AVAILABLE

    __asm__ volatile(

        "movl %3, %%eax         \n\t"

        "shrl $1, %%eax         \n\t"

        "addl %%eax, %2         \n\t"

        "addl %%eax, %1         \n\t"

        "addl %0, %%eax         \n\t"

        "mull %4                \n\t"

        "movl %%edx, %0         \n\t"

        "movl %1, %%eax         \n\t"

        "mull %4                \n\t"

        "movl %%edx, %1         \n\t"

        "movl %2, %%eax         \n\t"

        "mull %4                \n\t"

        "movl %%edx, %2         \n\t"

        : "+b" (a), "+c" (b), "+D" (c)

        : "g" (scale), "S" (ff_inverse[scale])

        : "%eax", "%edx"

    );

#else

    /* Divisions are costly everywhere; optimize the most common case. */

    if (scale == 8) {

        a = (a + (8 >> 1)) / 8;

        b = (b + (8 >> 1)) / 8;

        c = (c + (8 >> 1)) / 8;

    } else {

        a = FASTDIV((a + (scale >> 1)), scale);

        b = FASTDIV((b + (scale >> 1)), scale);

        c = FASTDIV((c + (scale >> 1)), scale);

    }

#endif

    /* XXX: WARNING: they did not choose the same test as MPEG4. This

       is very important ! */

    if(s->msmpeg4_version>3){

        if(s->inter_intra_pred){

            uint8_t *dest;

            int wrap;



            if(n==1){

                pred=a;

                *dir_ptr = 0;

            }else if(n==2){

                pred=c;

                *dir_ptr = 1;

            }else if(n==3){

                if (abs(a - b) < abs(b - c)) {

                    pred = c;

                    *dir_ptr = 1;

                } else {

                    pred = a;

                    *dir_ptr = 0;

                }

            }else{

                if(n<4){

                    wrap= s->linesize;

                    dest= s->current_picture.f.data[0] + (((n >> 1) + 2*s->mb_y) * 8*  wrap ) + ((n & 1) + 2*s->mb_x) * 8;

                }else{

                    wrap= s->uvlinesize;

                    dest= s->current_picture.f.data[n - 3] + (s->mb_y * 8 * wrap) + s->mb_x * 8;

                }

                if(s->mb_x==0) a= (1024 + (scale>>1))/scale;

                else           a= get_dc(dest-8, wrap, scale*8);

                if(s->mb_y==0) c= (1024 + (scale>>1))/scale;

                else           c= get_dc(dest-8*wrap, wrap, scale*8);



                if (s->h263_aic_dir==0) {

                    pred= a;

                    *dir_ptr = 0;

                }else if (s->h263_aic_dir==1) {

                    if(n==0){

                        pred= c;

                        *dir_ptr = 1;

                    }else{

                        pred= a;

                        *dir_ptr = 0;

                    }

                }else if (s->h263_aic_dir==2) {

                    if(n==0){

                        pred= a;

                        *dir_ptr = 0;

                    }else{

                        pred= c;

                        *dir_ptr = 1;

                    }

                } else {

                    pred= c;

                    *dir_ptr = 1;

                }

            }

        }else{

            if (abs(a - b) < abs(b - c)) {

                pred = c;

                *dir_ptr = 1;

            } else {

                pred = a;

                *dir_ptr = 0;

            }

        }

    }else{

        if (abs(a - b) <= abs(b - c)) {

            pred = c;

            *dir_ptr = 1;

        } else {

            pred = a;

            *dir_ptr = 0;

        }

    }



    /* update predictor */

    *dc_val_ptr = &dc_val[0];

    return pred;

}

int url_open(URLContext **puc, const char *filename, int flags)

{

    URLProtocol *up;

    const char *p;

    char proto_str[128], *q;



    p = filename;

    q = proto_str;

    while (*p != '\0' && *p != ':') {

        /* protocols can only contain alphabetic chars */

        if (!isalpha(*p))

            goto file_proto;

        if ((q - proto_str) < sizeof(proto_str) - 1)

            *q++ = *p;

        p++;

    }

    /* if the protocol has length 1, we consider it is a dos drive */

    if (*p == '\0' || (q - proto_str) <= 1) {

    file_proto:

        strcpy(proto_str, "file");

    } else {

        *q = '\0';

    }



    up = first_protocol;

    while (up != NULL) {

        if (!strcmp(proto_str, up->name))

            return url_open_protocol (puc, up, filename, flags);

        up = up->next;

    }

    *puc = NULL;

    return AVERROR(ENOENT);

}

struct SwsContext *sws_getContext(int srcW, int srcH, int srcFormat,

                                  int dstW, int dstH, int dstFormat,

                                  int flags, SwsFilter *srcFilter,

                                  SwsFilter *dstFilter, double *param)

{

    struct SwsContext *ctx;



    ctx = av_malloc(sizeof(struct SwsContext));

    if (ctx)

        ctx->av_class = av_mallocz(sizeof(AVClass));

    if (!ctx || !ctx->av_class) {

        av_log(NULL, AV_LOG_ERROR, "Cannot allocate a resampling context!\n");



        return NULL;

    }



    if ((srcH != dstH) || (srcW != dstW)) {

        if ((srcFormat != PIX_FMT_YUV420P) || (dstFormat != PIX_FMT_YUV420P)) {

            av_log(NULL, AV_LOG_INFO, "PIX_FMT_YUV420P will be used as an intermediate format for rescaling\n");

        }

        ctx->resampling_ctx = img_resample_init(dstW, dstH, srcW, srcH);

    } else {

        ctx->resampling_ctx = av_malloc(sizeof(ImgReSampleContext));

        ctx->resampling_ctx->iheight = srcH;

        ctx->resampling_ctx->iwidth = srcW;

        ctx->resampling_ctx->oheight = dstH;

        ctx->resampling_ctx->owidth = dstW;

    }

    ctx->src_pix_fmt = srcFormat;

    ctx->dst_pix_fmt = dstFormat;



    return ctx;

}

static int vp8_encode(AVCodecContext *avctx, AVPacket *pkt,

                      const AVFrame *frame, int *got_packet)

{

    VP8Context *ctx = avctx->priv_data;

    struct vpx_image *rawimg = NULL;

    struct vpx_image *rawimg_alpha = NULL;

    int64_t timestamp = 0;

    int res, coded_size;

    vpx_enc_frame_flags_t flags = 0;



    if (frame) {

        rawimg                      = &ctx->rawimg;

        rawimg->planes[VPX_PLANE_Y] = frame->data[0];

        rawimg->planes[VPX_PLANE_U] = frame->data[1];

        rawimg->planes[VPX_PLANE_V] = frame->data[2];

        rawimg->stride[VPX_PLANE_Y] = frame->linesize[0];

        rawimg->stride[VPX_PLANE_U] = frame->linesize[1];

        rawimg->stride[VPX_PLANE_V] = frame->linesize[2];

        if (ctx->is_alpha) {

            uint8_t *u_plane, *v_plane;

            rawimg_alpha = &ctx->rawimg_alpha;

            rawimg_alpha->planes[VPX_PLANE_Y] = frame->data[3];

            u_plane = av_malloc(frame->linesize[1] * frame->height);

            memset(u_plane, 0x80, frame->linesize[1] * frame->height);

            rawimg_alpha->planes[VPX_PLANE_U] = u_plane;

            v_plane = av_malloc(frame->linesize[2] * frame->height);

            memset(v_plane, 0x80, frame->linesize[2] * frame->height);

            rawimg_alpha->planes[VPX_PLANE_V] = v_plane;

            rawimg_alpha->stride[VPX_PLANE_Y] = frame->linesize[0];

            rawimg_alpha->stride[VPX_PLANE_U] = frame->linesize[1];

            rawimg_alpha->stride[VPX_PLANE_V] = frame->linesize[2];

        }

        timestamp                   = frame->pts;

        if (frame->pict_type == AV_PICTURE_TYPE_I)

            flags |= VPX_EFLAG_FORCE_KF;

    }



    res = vpx_codec_encode(&ctx->encoder, rawimg, timestamp,

                           avctx->ticks_per_frame, flags, ctx->deadline);

    if (res != VPX_CODEC_OK) {

        log_encoder_error(avctx, "Error encoding frame");

        return AVERROR_INVALIDDATA;

    }



    if (ctx->is_alpha) {

        res = vpx_codec_encode(&ctx->encoder_alpha, rawimg_alpha, timestamp,

                               avctx->ticks_per_frame, flags, ctx->deadline);

        if (res != VPX_CODEC_OK) {

            log_encoder_error(avctx, "Error encoding alpha frame");

            return AVERROR_INVALIDDATA;

        }

    }



    coded_size = queue_frames(avctx, pkt, avctx->coded_frame);



    if (!frame && avctx->flags & CODEC_FLAG_PASS1) {

        unsigned int b64_size = AV_BASE64_SIZE(ctx->twopass_stats.sz);



        avctx->stats_out = av_malloc(b64_size);

        if (!avctx->stats_out) {

            av_log(avctx, AV_LOG_ERROR, "Stat buffer alloc (%d bytes) failed\n",

                   b64_size);

            return AVERROR(ENOMEM);

        }

        av_base64_encode(avctx->stats_out, b64_size, ctx->twopass_stats.buf,

                         ctx->twopass_stats.sz);

    }



    if (rawimg_alpha) {

        av_freep(&rawimg_alpha->planes[VPX_PLANE_U]);

        av_freep(&rawimg_alpha->planes[VPX_PLANE_V]);

    }



    *got_packet = !!coded_size;

    return 0;

}

void av_opt_freep_ranges(AVOptionRanges **rangesp)

{

    int i;

    AVOptionRanges *ranges = *rangesp;



    if (!ranges)

        return;



    for (i = 0; i < ranges->nb_ranges * ranges->nb_components; i++) {

        AVOptionRange *range = ranges->range[i];

        av_freep(&range->str);

        av_freep(&ranges->range[i]);

    }

    av_freep(&ranges->range);

    av_freep(rangesp);

}

static int oggvorbis_encode_frame(AVCodecContext *avctx, AVPacket *avpkt,

                                  const AVFrame *frame, int *got_packet_ptr)

{

    OggVorbisEncContext *s = avctx->priv_data;

    ogg_packet op;

    int ret, duration;



    /* send samples to libvorbis */

    if (frame) {

        const int samples = frame->nb_samples;

        float **buffer;

        int c, channels = s->vi.channels;



        buffer = vorbis_analysis_buffer(&s->vd, samples);

        for (c = 0; c < channels; c++) {

            int co = (channels > 8) ? c :

                     ff_vorbis_encoding_channel_layout_offsets[channels - 1][c];

            memcpy(buffer[c], frame->extended_data[co],

                   samples * sizeof(*buffer[c]));

        }

        if ((ret = vorbis_analysis_wrote(&s->vd, samples)) < 0) {

            av_log(avctx, AV_LOG_ERROR, "error in vorbis_analysis_wrote()\n");

            return vorbis_error_to_averror(ret);

        }

        if ((ret = ff_af_queue_add(&s->afq, frame)) < 0)

            return ret;

    } else {

        if (!s->eof)

            if ((ret = vorbis_analysis_wrote(&s->vd, 0)) < 0) {

                av_log(avctx, AV_LOG_ERROR, "error in vorbis_analysis_wrote()\n");

                return vorbis_error_to_averror(ret);

            }

        s->eof = 1;

    }



    /* retrieve available packets from libvorbis */

    while ((ret = vorbis_analysis_blockout(&s->vd, &s->vb)) == 1) {

        if ((ret = vorbis_analysis(&s->vb, NULL)) < 0)

            break;

        if ((ret = vorbis_bitrate_addblock(&s->vb)) < 0)

            break;



        /* add any available packets to the output packet buffer */

        while ((ret = vorbis_bitrate_flushpacket(&s->vd, &op)) == 1) {

            if (av_fifo_space(s->pkt_fifo) < sizeof(ogg_packet) + op.bytes) {

                av_log(avctx, AV_LOG_ERROR, "packet buffer is too small\n");

                return AVERROR_BUG;

            }

            av_fifo_generic_write(s->pkt_fifo, &op, sizeof(ogg_packet), NULL);

            av_fifo_generic_write(s->pkt_fifo, op.packet, op.bytes, NULL);

        }

        if (ret < 0) {

            av_log(avctx, AV_LOG_ERROR, "error getting available packets\n");

            break;

        }

    }

    if (ret < 0) {

        av_log(avctx, AV_LOG_ERROR, "error getting available packets\n");

        return vorbis_error_to_averror(ret);

    }



    /* check for available packets */

    if (av_fifo_size(s->pkt_fifo) < sizeof(ogg_packet))

        return 0;



    av_fifo_generic_read(s->pkt_fifo, &op, sizeof(ogg_packet), NULL);



    if ((ret = ff_alloc_packet2(avctx, avpkt, op.bytes)))

        return ret;

    av_fifo_generic_read(s->pkt_fifo, avpkt->data, op.bytes, NULL);



    avpkt->pts = ff_samples_to_time_base(avctx, op.granulepos);



    duration = avpriv_vorbis_parse_frame(&s->vp, avpkt->data, avpkt->size);

    if (duration > 0) {

        /* we do not know encoder delay until we get the first packet from

         * libvorbis, so we have to update the AudioFrameQueue counts */

        if (!avctx->delay && s->afq.frames) {

            avctx->delay              = duration;

            av_assert0(!s->afq.remaining_delay);

            s->afq.frames->duration  += duration;

            s->afq.frames->pts       -= duration;

            s->afq.remaining_samples += duration;

        }

        ff_af_queue_remove(&s->afq, duration, &avpkt->pts, &avpkt->duration);

    }



    *got_packet_ptr = 1;

    return 0;

}

void ff_er_add_slice(ERContext *s, int startx, int starty,

                     int endx, int endy, int status)

{

    const int start_i  = av_clip(startx + starty * s->mb_width, 0, s->mb_num - 1);

    const int end_i    = av_clip(endx   + endy   * s->mb_width, 0, s->mb_num);

    const int start_xy = s->mb_index2xy[start_i];

    const int end_xy   = s->mb_index2xy[end_i];

    int mask           = -1;



    if (s->avctx->hwaccel)

        return;



    if (start_i > end_i || start_xy > end_xy) {

        av_log(s->avctx, AV_LOG_ERROR,

               "internal error, slice end before start\n");

        return;

    }



    if (!s->avctx->err_recognition)

        return;



    mask &= ~VP_START;

    if (status & (ER_AC_ERROR | ER_AC_END)) {

        mask           &= ~(ER_AC_ERROR | ER_AC_END);

        s->error_count -= end_i - start_i + 1;

    }

    if (status & (ER_DC_ERROR | ER_DC_END)) {

        mask           &= ~(ER_DC_ERROR | ER_DC_END);

        s->error_count -= end_i - start_i + 1;

    }

    if (status & (ER_MV_ERROR | ER_MV_END)) {

        mask           &= ~(ER_MV_ERROR | ER_MV_END);

        s->error_count -= end_i - start_i + 1;

    }



    if (status & ER_MB_ERROR) {

        s->error_occurred = 1;

        s->error_count    = INT_MAX;

    }



    if (mask == ~0x7F) {

        memset(&s->error_status_table[start_xy], 0,

               (end_xy - start_xy) * sizeof(uint8_t));

    } else {

        int i;

        for (i = start_xy; i < end_xy; i++)

            s->error_status_table[i] &= mask;

    }



    if (end_i == s->mb_num)

        s->error_count = INT_MAX;

    else {

        s->error_status_table[end_xy] &= mask;

        s->error_status_table[end_xy] |= status;

    }



    s->error_status_table[start_xy] |= VP_START;



    if (start_xy > 0 && !(s->avctx->active_thread_type & FF_THREAD_SLICE) &&

        s->avctx->skip_top * s->mb_width < start_i) {

        int prev_status = s->error_status_table[s->mb_index2xy[start_i - 1]];



        prev_status &= ~ VP_START;

        if (prev_status != (ER_MV_END | ER_DC_END | ER_AC_END)) {

            s->error_occurred = 1;

            s->error_count = INT_MAX;

        }

    }

}

static void avc_luma_hv_qrt_4w_msa(const uint8_t *src_x, const uint8_t *src_y,

                                   int32_t src_stride, uint8_t *dst,

                                   int32_t dst_stride, int32_t height)

{

    uint32_t loop_cnt;

    v16i8 src_hz0, src_hz1, src_hz2, src_hz3;

    v16i8 src_vt0, src_vt1, src_vt2, src_vt3, src_vt4;

    v16i8 src_vt5, src_vt6, src_vt7, src_vt8;

    v16i8 mask0, mask1, mask2;

    v8i16 hz_out0, hz_out1, vert_out0, vert_out1;

    v8i16 out0, out1;

    v16u8 out;



    LD_SB3(&luma_mask_arr[48], 16, mask0, mask1, mask2);



    LD_SB5(src_y, src_stride, src_vt0, src_vt1, src_vt2, src_vt3, src_vt4);

    src_y += (5 * src_stride);



    src_vt0 = (v16i8) __msa_insve_w((v4i32) src_vt0, 1, (v4i32) src_vt1);

    src_vt1 = (v16i8) __msa_insve_w((v4i32) src_vt1, 1, (v4i32) src_vt2);

    src_vt2 = (v16i8) __msa_insve_w((v4i32) src_vt2, 1, (v4i32) src_vt3);

    src_vt3 = (v16i8) __msa_insve_w((v4i32) src_vt3, 1, (v4i32) src_vt4);



    XORI_B4_128_SB(src_vt0, src_vt1, src_vt2, src_vt3);



    for (loop_cnt = (height >> 2); loop_cnt--;) {

        LD_SB4(src_x, src_stride, src_hz0, src_hz1, src_hz2, src_hz3);

        src_x += (4 * src_stride);



        XORI_B4_128_SB(src_hz0, src_hz1, src_hz2, src_hz3);



        hz_out0 = AVC_XOR_VSHF_B_AND_APPLY_6TAP_HORIZ_FILT_SH(src_hz0,

                                                              src_hz1, mask0,

                                                              mask1, mask2);

        hz_out1 = AVC_XOR_VSHF_B_AND_APPLY_6TAP_HORIZ_FILT_SH(src_hz2,

                                                              src_hz3, mask0,

                                                              mask1, mask2);



        SRARI_H2_SH(hz_out0, hz_out1, 5);

        SAT_SH2_SH(hz_out0, hz_out1, 7);



        LD_SB4(src_y, src_stride, src_vt5, src_vt6, src_vt7, src_vt8);

        src_y += (4 * src_stride);



        src_vt4 = (v16i8) __msa_insve_w((v4i32) src_vt4, 1, (v4i32) src_vt5);

        src_vt5 = (v16i8) __msa_insve_w((v4i32) src_vt5, 1, (v4i32) src_vt6);

        src_vt6 = (v16i8) __msa_insve_w((v4i32) src_vt6, 1, (v4i32) src_vt7);

        src_vt7 = (v16i8) __msa_insve_w((v4i32) src_vt7, 1, (v4i32) src_vt8);



        XORI_B4_128_SB(src_vt4, src_vt5, src_vt6, src_vt7);



        /* filter calc */

        vert_out0 = AVC_CALC_DPADD_B_6PIX_2COEFF_R_SH(src_vt0, src_vt1,

                                                      src_vt2, src_vt3,

                                                      src_vt4, src_vt5);

        vert_out1 = AVC_CALC_DPADD_B_6PIX_2COEFF_R_SH(src_vt2, src_vt3,

                                                      src_vt4, src_vt5,

                                                      src_vt6, src_vt7);



        SRARI_H2_SH(vert_out0, vert_out1, 5);

        SAT_SH2_SH(vert_out0, vert_out1, 7);



        out0 = __msa_srari_h((hz_out0 + vert_out0), 1);

        out1 = __msa_srari_h((hz_out1 + vert_out1), 1);



        SAT_SH2_SH(out0, out1, 7);

        out = PCKEV_XORI128_UB(out0, out1);

        ST4x4_UB(out, out, 0, 1, 2, 3, dst, dst_stride);

        dst += (4 * dst_stride);



        src_vt3 = src_vt7;

        src_vt1 = src_vt5;

        src_vt0 = src_vt4;

        src_vt4 = src_vt8;

        src_vt2 = src_vt6;

    }

}

static void qtrle_decode_24bpp(QtrleContext *s)

{

    int stream_ptr;

    int header;

    int start_line;

    int lines_to_change;

    signed char rle_code;

    int row_ptr, pixel_ptr;

    int row_inc = s->frame.linesize[0];

    unsigned char r, g, b;

    unsigned char *rgb = s->frame.data[0];

    int pixel_limit = s->frame.linesize[0] * s->avctx->height;



    /* check if this frame is even supposed to change */

    if (s->size < 8)

        return;



    /* start after the chunk size */

    stream_ptr = 4;



    /* fetch the header */

    CHECK_STREAM_PTR(2);

    header = BE_16(&s->buf[stream_ptr]);

    stream_ptr += 2;



    /* if a header is present, fetch additional decoding parameters */

    if (header & 0x0008) {

        CHECK_STREAM_PTR(8);

        start_line = BE_16(&s->buf[stream_ptr]);

        stream_ptr += 4;

        lines_to_change = BE_16(&s->buf[stream_ptr]);

        stream_ptr += 4;

    } else {

        start_line = 0;

        lines_to_change = s->avctx->height;

    }



    row_ptr = row_inc * start_line;

    while (lines_to_change--) {

        CHECK_STREAM_PTR(2);

        pixel_ptr = row_ptr + (s->buf[stream_ptr++] - 1) * 3;



        while ((rle_code = (signed char)s->buf[stream_ptr++]) != -1) {

            if (rle_code == 0) {

                /* there's another skip code in the stream */

                CHECK_STREAM_PTR(1);

                pixel_ptr += (s->buf[stream_ptr++] - 1) * 3;

                CHECK_PIXEL_PTR(0);  /* make sure pixel_ptr is positive */

            } else if (rle_code < 0) {

                /* decode the run length code */

                rle_code = -rle_code;

                CHECK_STREAM_PTR(3);

                r = s->buf[stream_ptr++];

                g = s->buf[stream_ptr++];

                b = s->buf[stream_ptr++];



                CHECK_PIXEL_PTR(rle_code * 3);



                while (rle_code--) {

                    rgb[pixel_ptr++] = r;

                    rgb[pixel_ptr++] = g;

                    rgb[pixel_ptr++] = b;

                }

            } else {

                CHECK_STREAM_PTR(rle_code * 3);

                CHECK_PIXEL_PTR(rle_code * 3);



                /* copy pixels directly to output */

                while (rle_code--) {

                    rgb[pixel_ptr++] = s->buf[stream_ptr++];

                    rgb[pixel_ptr++] = s->buf[stream_ptr++];

                    rgb[pixel_ptr++] = s->buf[stream_ptr++];

                }

            }

        }

        row_ptr += row_inc;

    }

}

static void rtcp_send_sr(AVFormatContext *s1, int64_t ntp_time)

{

    RTPDemuxContext *s = s1->priv_data;

    uint32_t rtp_ts;



#if defined(DEBUG)

    printf("RTCP: %02x %"PRIx64" %x\n", s->payload_type, ntp_time, s->timestamp);

#endif



    if (s->first_rtcp_ntp_time == AV_NOPTS_VALUE) s->first_rtcp_ntp_time = ntp_time;

    s->last_rtcp_ntp_time = ntp_time;

    rtp_ts = av_rescale_q(ntp_time - s->first_rtcp_ntp_time, AV_TIME_BASE_Q,

                          s1->streams[0]->time_base) + s->base_timestamp;

    put_byte(s1->pb, (RTP_VERSION << 6));

    put_byte(s1->pb, 200);

    put_be16(s1->pb, 6); /* length in words - 1 */

    put_be32(s1->pb, s->ssrc);

    put_be32(s1->pb, ntp_time / 1000000);

    put_be32(s1->pb, ((ntp_time % 1000000) << 32) / 1000000);

    put_be32(s1->pb, rtp_ts);

    put_be32(s1->pb, s->packet_count);

    put_be32(s1->pb, s->octet_count);

    put_flush_packet(s1->pb);

}

static void decode_cabac_residual( H264Context *h, DCTELEM *block, int cat, int n, const uint8_t *scantable, const uint32_t *qmul, int max_coeff) {

    static const int significant_coeff_flag_offset[2][6] = {

      { 105+0, 105+15, 105+29, 105+44, 105+47, 402 },

      { 277+0, 277+15, 277+29, 277+44, 277+47, 436 }

    };

    static const int last_coeff_flag_offset[2][6] = {

      { 166+0, 166+15, 166+29, 166+44, 166+47, 417 },

      { 338+0, 338+15, 338+29, 338+44, 338+47, 451 }

    };

    static const int coeff_abs_level_m1_offset[6] = {

        227+0, 227+10, 227+20, 227+30, 227+39, 426

    };

    static const uint8_t significant_coeff_flag_offset_8x8[2][63] = {

      { 0, 1, 2, 3, 4, 5, 5, 4, 4, 3, 3, 4, 4, 4, 5, 5,

        4, 4, 4, 4, 3, 3, 6, 7, 7, 7, 8, 9,10, 9, 8, 7,

        7, 6,11,12,13,11, 6, 7, 8, 9,14,10, 9, 8, 6,11,

       12,13,11, 6, 9,14,10, 9,11,12,13,11,14,10,12 },

      { 0, 1, 1, 2, 2, 3, 3, 4, 5, 6, 7, 7, 7, 8, 4, 5,

        6, 9,10,10, 8,11,12,11, 9, 9,10,10, 8,11,12,11,

        9, 9,10,10, 8,11,12,11, 9, 9,10,10, 8,13,13, 9,

        9,10,10, 8,13,13, 9, 9,10,10,14,14,14,14,14 }

    };

    /* node ctx: 0..3: abslevel1 (with abslevelgt1 == 0).

     * 4..7: abslevelgt1 + 3 (and abslevel1 doesn't matter).

     * map node ctx => cabac ctx for level=1 */

    static const uint8_t coeff_abs_level1_ctx[8] = { 1, 2, 3, 4, 0, 0, 0, 0 };

    /* map node ctx => cabac ctx for level>1 */

    static const uint8_t coeff_abs_levelgt1_ctx[8] = { 5, 5, 5, 5, 6, 7, 8, 9 };

    static const uint8_t coeff_abs_level_transition[2][8] = {

    /* update node ctx after decoding a level=1 */

        { 1, 2, 3, 3, 4, 5, 6, 7 },

    /* update node ctx after decoding a level>1 */

        { 4, 4, 4, 4, 5, 6, 7, 7 }

    };



    int index[64];



    int av_unused last;

    int coeff_count = 0;

    int node_ctx = 0;



    uint8_t *significant_coeff_ctx_base;

    uint8_t *last_coeff_ctx_base;

    uint8_t *abs_level_m1_ctx_base;



#ifndef ARCH_X86

#define CABAC_ON_STACK

#endif

#ifdef CABAC_ON_STACK

#define CC &cc

    CABACContext cc;

    cc.range     = h->cabac.range;

    cc.low       = h->cabac.low;

    cc.bytestream= h->cabac.bytestream;

#else

#define CC &h->cabac

#endif





    /* cat: 0-> DC 16x16  n = 0

     *      1-> AC 16x16  n = luma4x4idx

     *      2-> Luma4x4   n = luma4x4idx

     *      3-> DC Chroma n = iCbCr

     *      4-> AC Chroma n = 4 * iCbCr + chroma4x4idx

     *      5-> Luma8x8   n = 4 * luma8x8idx

     */



    /* read coded block flag */

    if( cat != 5 ) {

        if( get_cabac( CC, &h->cabac_state[85 + get_cabac_cbf_ctx( h, cat, n ) ] ) == 0 ) {

            if( cat == 1 || cat == 2 )

                h->non_zero_count_cache[scan8[n]] = 0;

            else if( cat == 4 )

                h->non_zero_count_cache[scan8[16+n]] = 0;

#ifdef CABAC_ON_STACK

            h->cabac.range     = cc.range     ;

            h->cabac.low       = cc.low       ;

            h->cabac.bytestream= cc.bytestream;

#endif

            return;

        }

    }



    significant_coeff_ctx_base = h->cabac_state

        + significant_coeff_flag_offset[MB_FIELD][cat];

    last_coeff_ctx_base = h->cabac_state

        + last_coeff_flag_offset[MB_FIELD][cat];

    abs_level_m1_ctx_base = h->cabac_state

        + coeff_abs_level_m1_offset[cat];



    if( cat == 5 ) {

#define DECODE_SIGNIFICANCE( coefs, sig_off, last_off ) \

        for(last= 0; last < coefs; last++) { \

            uint8_t *sig_ctx = significant_coeff_ctx_base + sig_off; \

            if( get_cabac( CC, sig_ctx )) { \

                uint8_t *last_ctx = last_coeff_ctx_base + last_off; \

                index[coeff_count++] = last; \

                if( get_cabac( CC, last_ctx ) ) { \

                    last= max_coeff; \

                    break; \

                } \

            } \

        }\

        if( last == max_coeff -1 ) {\

            index[coeff_count++] = last;\

        }

        const uint8_t *sig_off = significant_coeff_flag_offset_8x8[MB_FIELD];

#if defined(ARCH_X86) && defined(HAVE_7REGS) && defined(HAVE_EBX_AVAILABLE) && !defined(BROKEN_RELOCATIONS)

        coeff_count= decode_significance_8x8_x86(CC, significant_coeff_ctx_base, index, sig_off);

    } else {

        coeff_count= decode_significance_x86(CC, max_coeff, significant_coeff_ctx_base, index);

#else

        DECODE_SIGNIFICANCE( 63, sig_off[last], last_coeff_flag_offset_8x8[last] );

    } else {

        DECODE_SIGNIFICANCE( max_coeff - 1, last, last );

#endif

    }

    assert(coeff_count > 0);



    if( cat == 0 )

        h->cbp_table[h->mb_xy] |= 0x100;

    else if( cat == 1 || cat == 2 )

        h->non_zero_count_cache[scan8[n]] = coeff_count;

    else if( cat == 3 )

        h->cbp_table[h->mb_xy] |= 0x40 << n;

    else if( cat == 4 )

        h->non_zero_count_cache[scan8[16+n]] = coeff_count;

    else {

        assert( cat == 5 );

        fill_rectangle(&h->non_zero_count_cache[scan8[n]], 2, 2, 8, coeff_count, 1);

    }



    for( coeff_count--; coeff_count >= 0; coeff_count-- ) {

        uint8_t *ctx = coeff_abs_level1_ctx[node_ctx] + abs_level_m1_ctx_base;



        int j= scantable[index[coeff_count]];



        if( get_cabac( CC, ctx ) == 0 ) {

            node_ctx = coeff_abs_level_transition[0][node_ctx];

            if( !qmul ) {

                block[j] = get_cabac_bypass_sign( CC, -1);

            }else{

                block[j] = (get_cabac_bypass_sign( CC, -qmul[j]) + 32) >> 6;

            }

        } else {

            int coeff_abs = 2;

            ctx = coeff_abs_levelgt1_ctx[node_ctx] + abs_level_m1_ctx_base;

            node_ctx = coeff_abs_level_transition[1][node_ctx];



            while( coeff_abs < 15 && get_cabac( CC, ctx ) ) {

                coeff_abs++;

            }



            if( coeff_abs >= 15 ) {

                int j = 0;

                while( get_cabac_bypass( CC ) ) {

                    j++;

                }



                coeff_abs=1;

                while( j-- ) {

                    coeff_abs += coeff_abs + get_cabac_bypass( CC );

                }

                coeff_abs+= 14;

            }



            if( !qmul ) {

                if( get_cabac_bypass( CC ) ) block[j] = -coeff_abs;

                else                                block[j] =  coeff_abs;

            }else{

                if( get_cabac_bypass( CC ) ) block[j] = (-coeff_abs * qmul[j] + 32) >> 6;

                else                                block[j] = ( coeff_abs * qmul[j] + 32) >> 6;

            }

        }

    }

#ifdef CABAC_ON_STACK

            h->cabac.range     = cc.range     ;

            h->cabac.low       = cc.low       ;

            h->cabac.bytestream= cc.bytestream;

#endif



}

static inline void downmix_2f_2r_to_dolby(float *samples)

{

    int i;



    for (i = 0; i < 256; i++) {

        samples[i] -= samples[i + 512];

        samples[i + 256] += samples[i + 768];

        samples[i + 512] = samples[i + 768] = 0;

    }

}

