static int wc3_read_packet(AVFormatContext *s,

                           AVPacket *pkt)

{

    Wc3DemuxContext *wc3 = s->priv_data;

    ByteIOContext *pb = s->pb;

    unsigned int fourcc_tag;

    unsigned int size;

    int packet_read = 0;

    int ret = 0;

    unsigned char text[1024];

    unsigned int palette_number;

    int i;

    unsigned char r, g, b;

    int base_palette_index;



    while (!packet_read) {



        fourcc_tag = get_le32(pb);

        /* chunk sizes are 16-bit aligned */

        size = (get_be32(pb) + 1) & (~1);

        if (url_feof(pb))

            return AVERROR(EIO);



        switch (fourcc_tag) {



        case BRCH_TAG:

            /* no-op */

            break;



        case SHOT_TAG:

            /* load up new palette */

            palette_number = get_le32(pb);

            if (palette_number >= wc3->palette_count)

                return AVERROR_INVALIDDATA;

            base_palette_index = palette_number * PALETTE_COUNT * 3;

            for (i = 0; i < PALETTE_COUNT; i++) {

                r = wc3->palettes[base_palette_index + i * 3 + 0];

                g = wc3->palettes[base_palette_index + i * 3 + 1];

                b = wc3->palettes[base_palette_index + i * 3 + 2];

                wc3->palette_control.palette[i] = (r << 16) | (g << 8) | (b);

            }

            wc3->palette_control.palette_changed = 1;

            break;



        case VGA__TAG:

            /* send out video chunk */

            ret= av_get_packet(pb, pkt, size);

            pkt->stream_index = wc3->video_stream_index;

            pkt->pts = wc3->pts;

            packet_read = 1;

            break;



        case TEXT_TAG:

            /* subtitle chunk */

#if 0

            url_fseek(pb, size, SEEK_CUR);

#else

            if ((unsigned)size > sizeof(text) || (ret = get_buffer(pb, text, size)) != size)

                ret = AVERROR(EIO);

            else {

                int i = 0;

                av_log (s, AV_LOG_DEBUG, "Subtitle time!\n");

                av_log (s, AV_LOG_DEBUG, "  inglish: %s\n", &text[i + 1]);

                i += text[i] + 1;

                av_log (s, AV_LOG_DEBUG, "  doytsch: %s\n", &text[i + 1]);

                i += text[i] + 1;

                av_log (s, AV_LOG_DEBUG, "  fronsay: %s\n", &text[i + 1]);

            }

#endif

            break;



        case AUDI_TAG:

            /* send out audio chunk */

            ret= av_get_packet(pb, pkt, size);

            pkt->stream_index = wc3->audio_stream_index;

            pkt->pts = wc3->pts;



            /* time to advance pts */

            wc3->pts++;



            packet_read = 1;

            break;



        default:

            av_log (s, AV_LOG_ERROR, "  unrecognized WC3 chunk: %c%c%c%c (0x%02X%02X%02X%02X)\n",

                (uint8_t)fourcc_tag, (uint8_t)(fourcc_tag >> 8), (uint8_t)(fourcc_tag >> 16), (uint8_t)(fourcc_tag >> 24),

                (uint8_t)fourcc_tag, (uint8_t)(fourcc_tag >> 8), (uint8_t)(fourcc_tag >> 16), (uint8_t)(fourcc_tag >> 24));

            ret = AVERROR_INVALIDDATA;

            packet_read = 1;

            break;

        }

    }



    return ret;

}

static int rate_control(AVCodecContext *avctx, void *arg)

{

    SliceArgs *slice_dat = arg;

    VC2EncContext *s = slice_dat->ctx;

    const int sx = slice_dat->x;

    const int sy = slice_dat->y;

    int quant_buf[2], bits_buf[2], quant = s->q_start, range = s->q_start/3;

    const int64_t top = slice_dat->bits_ceil;

    const double percent = s->tolerance;

    const double bottom = top - top*(percent/100.0f);

    int bits = count_hq_slice(s, sx, sy, quant);

    range -= range & 1; /* Make it an even number */

    while ((bits > top) || (bits < bottom)) {

        range *= bits > top ? +1 : -1;

        quant = av_clip(quant + range, 0, s->q_ceil);

        bits = count_hq_slice(s, sx, sy, quant);

        range = av_clip(range/2, 1, s->q_ceil);

        if (quant_buf[1] == quant) {

            quant = bits_buf[0] < bits ? quant_buf[0] : quant;

            bits = bits_buf[0] < bits ? bits_buf[0] : bits;

            break;

        }

        quant_buf[1] = quant_buf[0];

        quant_buf[0] = quant;

        bits_buf[1] = bits_buf[0];

        bits_buf[0] = bits;

    }

    slice_dat->quant_idx = av_clip(quant, 0, s->q_ceil);

    slice_dat->bytes = FFALIGN((bits >> 3), s->size_scaler) + 4 + s->prefix_bytes;



    return 0;

}

static int ogg_read_page(AVFormatContext *s, int *str)

{

    AVIOContext *bc = s->pb;

    struct ogg *ogg = s->priv_data;

    struct ogg_stream *os;

    int ret, i = 0;

    int flags, nsegs;

    uint64_t gp;

    uint32_t serial;

    int size, idx;

    uint8_t sync[4];

    int sp = 0;



    ret = avio_read(bc, sync, 4);

    if (ret < 4)

        return ret < 0 ? ret : AVERROR_EOF;



    do{

        int c;



        if (sync[sp & 3] == 'O' &&

            sync[(sp + 1) & 3] == 'g' &&

            sync[(sp + 2) & 3] == 'g' && sync[(sp + 3) & 3] == 'S')

            break;



        c = avio_r8(bc);

        if (bc->eof_reached)

            return AVERROR_EOF;

        sync[sp++ & 3] = c;

    }while (i++ < MAX_PAGE_SIZE);



    if (i >= MAX_PAGE_SIZE){

        av_log (s, AV_LOG_INFO, "ogg, can't find sync word\n");

        return AVERROR_INVALIDDATA;

    }



    if (avio_r8(bc) != 0)      /* version */

        return AVERROR_INVALIDDATA;



    flags = avio_r8(bc);

    gp = avio_rl64 (bc);

    serial = avio_rl32 (bc);

    avio_skip(bc, 8); /* seq, crc */

    nsegs = avio_r8(bc);



    idx = ogg_find_stream (ogg, serial);

    if (idx < 0){

        if (ogg->headers) {

            int n;



            for (n = 0; n < ogg->nstreams; n++) {

                av_freep(&ogg->streams[n].buf);

                if (!ogg->state || ogg->state->streams[n].private != ogg->streams[n].private)

                    av_freep(&ogg->streams[n].private);

            }

            ogg->curidx   = -1;

            ogg->nstreams = 0;

            idx = ogg_new_stream(s, serial, 0);

        } else {

            idx = ogg_new_stream(s, serial, 1);

        }

        if (idx < 0)

            return idx;

    }



    os = ogg->streams + idx;

    os->page_pos = avio_tell(bc) - 27;



    if(os->psize > 0)

        ogg_new_buf(ogg, idx);



    ret = avio_read(bc, os->segments, nsegs);

    if (ret < nsegs)

        return ret < 0 ? ret : AVERROR_EOF;



    os->nsegs = nsegs;

    os->segp = 0;



    size = 0;

    for (i = 0; i < nsegs; i++)

        size += os->segments[i];



    if (flags & OGG_FLAG_CONT || os->incomplete){

        if (!os->psize){

            while (os->segp < os->nsegs){

                int seg = os->segments[os->segp++];

                os->pstart += seg;

                if (seg < 255)

                    break;

            }

            os->sync_pos = os->page_pos;

        }

    }else{

        os->psize = 0;

        os->sync_pos = os->page_pos;

    }



    if (os->bufsize - os->bufpos < size){

        uint8_t *nb = av_malloc (os->bufsize *= 2);

        memcpy (nb, os->buf, os->bufpos);

        av_free (os->buf);

        os->buf = nb;

    }



    ret = avio_read(bc, os->buf + os->bufpos, size);

    if (ret < size)

        return ret < 0 ? ret : AVERROR_EOF;



    os->bufpos += size;

    os->granule = gp;

    os->flags = flags;



    if (str)

        *str = idx;



    return 0;

}

void ff_ivi_recompose53(const IVIPlaneDesc *plane, uint8_t *dst,

                        const ptrdiff_t dst_pitch)

{

    int             x, y, indx;

    int32_t         p0, p1, p2, p3, tmp0, tmp1, tmp2;

    int32_t         b0_1, b0_2, b1_1, b1_2, b1_3, b2_1, b2_2, b2_3, b2_4, b2_5, b2_6;

    int32_t         b3_1, b3_2, b3_3, b3_4, b3_5, b3_6, b3_7, b3_8, b3_9;

    ptrdiff_t       pitch, back_pitch;

    const short     *b0_ptr, *b1_ptr, *b2_ptr, *b3_ptr;

    const int       num_bands = 4;



    /* all bands should have the same pitch */

    pitch = plane->bands[0].pitch;



    /* pixels at the position "y-1" will be set to pixels at the "y" for the 1st iteration */

    back_pitch = 0;



    /* get pointers to the wavelet bands */

    b0_ptr = plane->bands[0].buf;

    b1_ptr = plane->bands[1].buf;

    b2_ptr = plane->bands[2].buf;

    b3_ptr = plane->bands[3].buf;



    for (y = 0; y < plane->height; y += 2) {



        if (y+2 >= plane->height)

            pitch= 0;

        /* load storage variables with values */

        if (num_bands > 0) {

            b0_1 = b0_ptr[0];

            b0_2 = b0_ptr[pitch];

        }



        if (num_bands > 1) {

            b1_1 = b1_ptr[back_pitch];

            b1_2 = b1_ptr[0];

            b1_3 = b1_1 - b1_2*6 + b1_ptr[pitch];

        }



        if (num_bands > 2) {

            b2_2 = b2_ptr[0];     // b2[x,  y  ]

            b2_3 = b2_2;          // b2[x+1,y  ] = b2[x,y]

            b2_5 = b2_ptr[pitch]; // b2[x  ,y+1]

            b2_6 = b2_5;          // b2[x+1,y+1] = b2[x,y+1]

        }



        if (num_bands > 3) {

            b3_2 = b3_ptr[back_pitch]; // b3[x  ,y-1]

            b3_3 = b3_2;               // b3[x+1,y-1] = b3[x  ,y-1]

            b3_5 = b3_ptr[0];          // b3[x  ,y  ]

            b3_6 = b3_5;               // b3[x+1,y  ] = b3[x  ,y  ]

            b3_8 = b3_2 - b3_5*6 + b3_ptr[pitch];

            b3_9 = b3_8;

        }



        for (x = 0, indx = 0; x < plane->width; x+=2, indx++) {

            if (x+2 >= plane->width) {

                b0_ptr --;

                b1_ptr --;

                b2_ptr --;

                b3_ptr --;

            }



            /* some values calculated in the previous iterations can */

            /* be reused in the next ones, so do appropriate copying */

            b2_1 = b2_2; // b2[x-1,y  ] = b2[x,  y  ]

            b2_2 = b2_3; // b2[x  ,y  ] = b2[x+1,y  ]

            b2_4 = b2_5; // b2[x-1,y+1] = b2[x  ,y+1]

            b2_5 = b2_6; // b2[x  ,y+1] = b2[x+1,y+1]

            b3_1 = b3_2; // b3[x-1,y-1] = b3[x  ,y-1]

            b3_2 = b3_3; // b3[x  ,y-1] = b3[x+1,y-1]

            b3_4 = b3_5; // b3[x-1,y  ] = b3[x  ,y  ]

            b3_5 = b3_6; // b3[x  ,y  ] = b3[x+1,y  ]

            b3_7 = b3_8; // vert_HPF(x-1)

            b3_8 = b3_9; // vert_HPF(x  )



            p0 = p1 = p2 = p3 = 0;



            /* process the LL-band by applying LPF both vertically and horizontally */

            if (num_bands > 0) {

                tmp0 = b0_1;

                tmp2 = b0_2;

                b0_1 = b0_ptr[indx+1];

                b0_2 = b0_ptr[pitch+indx+1];

                tmp1 = tmp0 + b0_1;



                p0 =  tmp0 << 4;

                p1 =  tmp1 << 3;

                p2 = (tmp0 + tmp2) << 3;

                p3 = (tmp1 + tmp2 + b0_2) << 2;

            }



            /* process the HL-band by applying HPF vertically and LPF horizontally */

            if (num_bands > 1) {

                tmp0 = b1_2;

                tmp1 = b1_1;

                b1_2 = b1_ptr[indx+1];

                b1_1 = b1_ptr[back_pitch+indx+1];



                tmp2 = tmp1 - tmp0*6 + b1_3;

                b1_3 = b1_1 - b1_2*6 + b1_ptr[pitch+indx+1];



                p0 += (tmp0 + tmp1) << 3;

                p1 += (tmp0 + tmp1 + b1_1 + b1_2) << 2;

                p2 +=  tmp2 << 2;

                p3 += (tmp2 + b1_3) << 1;

            }



            /* process the LH-band by applying LPF vertically and HPF horizontally */

            if (num_bands > 2) {

                b2_3 = b2_ptr[indx+1];

                b2_6 = b2_ptr[pitch+indx+1];



                tmp0 = b2_1 + b2_2;

                tmp1 = b2_1 - b2_2*6 + b2_3;



                p0 += tmp0 << 3;

                p1 += tmp1 << 2;

                p2 += (tmp0 + b2_4 + b2_5) << 2;

                p3 += (tmp1 + b2_4 - b2_5*6 + b2_6) << 1;

            }



            /* process the HH-band by applying HPF both vertically and horizontally */

            if (num_bands > 3) {

                b3_6 = b3_ptr[indx+1];            // b3[x+1,y  ]

                b3_3 = b3_ptr[back_pitch+indx+1]; // b3[x+1,y-1]



                tmp0 = b3_1 + b3_4;

                tmp1 = b3_2 + b3_5;

                tmp2 = b3_3 + b3_6;



                b3_9 = b3_3 - b3_6*6 + b3_ptr[pitch+indx+1];



                p0 += (tmp0 + tmp1) << 2;

                p1 += (tmp0 - tmp1*6 + tmp2) << 1;

                p2 += (b3_7 + b3_8) << 1;

                p3 +=  b3_7 - b3_8*6 + b3_9;

            }



            /* output four pixels */

            dst[x]             = av_clip_uint8((p0 >> 6) + 128);

            dst[x+1]           = av_clip_uint8((p1 >> 6) + 128);

            dst[dst_pitch+x]   = av_clip_uint8((p2 >> 6) + 128);

            dst[dst_pitch+x+1] = av_clip_uint8((p3 >> 6) + 128);

        }// for x



        dst += dst_pitch << 1;



        back_pitch = -pitch;



        b0_ptr += pitch + 1;

        b1_ptr += pitch + 1;

        b2_ptr += pitch + 1;

        b3_ptr += pitch + 1;

    }

}

static int genh_read_packet(AVFormatContext *s, AVPacket *pkt)

{

    AVCodecContext *codec = s->streams[0]->codec;

    GENHDemuxContext *c = s->priv_data;

    int ret;



    if (c->dsp_int_type == 1 && codec->codec_id == AV_CODEC_ID_ADPCM_THP &&

        codec->channels > 1) {

        int i, ch;



        if (avio_feof(s->pb))

            return AVERROR_EOF;

        av_new_packet(pkt, 8 * codec->channels);

        for (i = 0; i < 8 / c->interleave_size; i++) {

            for (ch = 0; ch < codec->channels; ch++) {

                pkt->data[ch * 8 + i*c->interleave_size+0] = avio_r8(s->pb);

                pkt->data[ch * 8 + i*c->interleave_size+1] = avio_r8(s->pb);

            }

        }

        ret = 0;

    } else {

        ret = av_get_packet(s->pb, pkt, codec->block_align ? codec->block_align : 1024 * codec->channels);

    }



    pkt->stream_index = 0;

    return ret;

}

static av_cold int MPA_encode_init(AVCodecContext *avctx)

{

    MpegAudioContext *s = avctx->priv_data;

    int freq = avctx->sample_rate;

    int bitrate = avctx->bit_rate;

    int channels = avctx->channels;

    int i, v, table;

    float a;



    if (channels <= 0 || channels > 2){

        av_log(avctx, AV_LOG_ERROR, "encoding %d channel(s) is not allowed in mp2\n", channels);

        return AVERROR(EINVAL);

    }

    bitrate = bitrate / 1000;

    s->nb_channels = channels;

    avctx->frame_size = MPA_FRAME_SIZE;

    avctx->delay      = 512 - 32 + 1;



    /* encoding freq */

    s->lsf = 0;

    for(i=0;i<3;i++) {

        if (avpriv_mpa_freq_tab[i] == freq)

            break;

        if ((avpriv_mpa_freq_tab[i] / 2) == freq) {

            s->lsf = 1;

            break;

        }

    }

    if (i == 3){

        av_log(avctx, AV_LOG_ERROR, "Sampling rate %d is not allowed in mp2\n", freq);

        return AVERROR(EINVAL);

    }

    s->freq_index = i;



    /* encoding bitrate & frequency */

    for(i=0;i<15;i++) {

        if (avpriv_mpa_bitrate_tab[s->lsf][1][i] == bitrate)

            break;

    }

    if (i == 15){

        av_log(avctx, AV_LOG_ERROR, "bitrate %d is not allowed in mp2\n", bitrate);

        return AVERROR(EINVAL);

    }

    s->bitrate_index = i;



    /* compute total header size & pad bit */



    a = (float)(bitrate * 1000 * MPA_FRAME_SIZE) / (freq * 8.0);

    s->frame_size = ((int)a) * 8;



    /* frame fractional size to compute padding */

    s->frame_frac = 0;

    s->frame_frac_incr = (int)((a - floor(a)) * 65536.0);



    /* select the right allocation table */

    table = ff_mpa_l2_select_table(bitrate, s->nb_channels, freq, s->lsf);



    /* number of used subbands */

    s->sblimit = ff_mpa_sblimit_table[table];

    s->alloc_table = ff_mpa_alloc_tables[table];



    av_dlog(avctx, "%d kb/s, %d Hz, frame_size=%d bits, table=%d, padincr=%x\n",

            bitrate, freq, s->frame_size, table, s->frame_frac_incr);



    for(i=0;i<s->nb_channels;i++)

        s->samples_offset[i] = 0;



    for(i=0;i<257;i++) {

        int v;

        v = ff_mpa_enwindow[i];

#if WFRAC_BITS != 16

        v = (v + (1 << (16 - WFRAC_BITS - 1))) >> (16 - WFRAC_BITS);

#endif

        s->filter_bank[i] = v;

        if ((i & 63) != 0)

            v = -v;

        if (i != 0)

            s->filter_bank[512 - i] = v;

    }



    for(i=0;i<64;i++) {

        v = (int)(pow(2.0, (3 - i) / 3.0) * (1 << 20));

        if (v <= 0)

            v = 1;

        s->scale_factor_table[i] = v;

        s->scale_factor_inv_table[i] = pow(2.0, -(3 - i) / 3.0) / (float)(1 << 20);

    }

    for(i=0;i<128;i++) {

        v = i - 64;

        if (v <= -3)

            v = 0;

        else if (v < 0)

            v = 1;

        else if (v == 0)

            v = 2;

        else if (v < 3)

            v = 3;

        else

            v = 4;

        s->scale_diff_table[i] = v;

    }



    for(i=0;i<17;i++) {

        v = ff_mpa_quant_bits[i];

        if (v < 0)

            v = -v;

        else

            v = v * 3;

        s->total_quant_bits[i] = 12 * v;

    }



    return 0;

}

