static av_cold int fieldmatch_init(AVFilterContext *ctx)

{

    const FieldMatchContext *fm = ctx->priv;

    AVFilterPad pad = {

        .name         = av_strdup("main"),

        .type         = AVMEDIA_TYPE_VIDEO,

        .filter_frame = filter_frame,

        .config_props = config_input,

    };



    if (!pad.name)

        return AVERROR(ENOMEM);

    ff_insert_inpad(ctx, INPUT_MAIN, &pad);



    if (fm->ppsrc) {

        pad.name = av_strdup("clean_src");

        pad.config_props = NULL;

        if (!pad.name)

            return AVERROR(ENOMEM);

        ff_insert_inpad(ctx, INPUT_CLEANSRC, &pad);

    }



    if ((fm->blockx & (fm->blockx - 1)) ||

        (fm->blocky & (fm->blocky - 1))) {

        av_log(ctx, AV_LOG_ERROR, "blockx and blocky settings must be power of two\n");

        return AVERROR(EINVAL);

    }



    if (fm->combpel > fm->blockx * fm->blocky) {

        av_log(ctx, AV_LOG_ERROR, "Combed pixel should not be larger than blockx x blocky\n");

        return AVERROR(EINVAL);

    }



    return 0;

}

void avpriv_tak_parse_streaminfo(GetBitContext *gb, TAKStreamInfo *s)

{

    uint64_t channel_mask = 0;

    int frame_type, i;



    s->codec = get_bits(gb, TAK_ENCODER_CODEC_BITS);

    skip_bits(gb, TAK_ENCODER_PROFILE_BITS);



    frame_type = get_bits(gb, TAK_SIZE_FRAME_DURATION_BITS);

    s->samples = get_bits64(gb, TAK_SIZE_SAMPLES_NUM_BITS);



    s->data_type   = get_bits(gb, TAK_FORMAT_DATA_TYPE_BITS);

    s->sample_rate = get_bits(gb, TAK_FORMAT_SAMPLE_RATE_BITS) +

                     TAK_SAMPLE_RATE_MIN;

    s->bps         = get_bits(gb, TAK_FORMAT_BPS_BITS) +

                     TAK_BPS_MIN;

    s->channels    = get_bits(gb, TAK_FORMAT_CHANNEL_BITS) +

                     TAK_CHANNELS_MIN;



    if (get_bits1(gb)) {

        skip_bits(gb, TAK_FORMAT_VALID_BITS);

        if (get_bits1(gb)) {

            for (i = 0; i < s->channels; i++) {

                int value = get_bits(gb, TAK_FORMAT_CH_LAYOUT_BITS);



                if (value < FF_ARRAY_ELEMS(tak_channel_layouts))

                    channel_mask |= tak_channel_layouts[value];

            }

        }

    }



    s->ch_layout     = channel_mask;

    s->frame_samples = tak_get_nb_samples(s->sample_rate, frame_type);

}

int show_formats(void *optctx, const char *opt, const char *arg)

{

    AVInputFormat *ifmt  = NULL;

    AVOutputFormat *ofmt = NULL;

    const char *last_name;



    printf("File formats:\n"

           " D. = Demuxing supported\n"

           " .E = Muxing supported\n"

           " --\n");

    last_name = "000";

    for (;;) {

        int decode = 0;

        int encode = 0;

        const char *name      = NULL;

        const char *long_name = NULL;



        while ((ofmt = av_oformat_next(ofmt))) {

            if ((name == NULL || strcmp(ofmt->name, name) < 0) &&

                strcmp(ofmt->name, last_name) > 0) {

                name      = ofmt->name;

                long_name = ofmt->long_name;

                encode    = 1;

            }

        }

        while ((ifmt = av_iformat_next(ifmt))) {

            if ((name == NULL || strcmp(ifmt->name, name) < 0) &&

                strcmp(ifmt->name, last_name) > 0) {

                name      = ifmt->name;

                long_name = ifmt->long_name;

                encode    = 0;

            }

            if (name && strcmp(ifmt->name, name) == 0)

                decode = 1;

        }

        if (name == NULL)

            break;

        last_name = name;



        printf(" %s%s %-15s %s\n",

               decode ? "D" : " ",

               encode ? "E" : " ",

               name,

            long_name ? long_name:" ");

    }

    return 0;

}

