    return AVERROR(EIO);

}

int ff_jpegls_decode_lse(MJpegDecodeContext *s)

{

    int id;

    int tid, wt, maxtab, i, j;



    int len = get_bits(&s->gb, 16);  /* length: FIXME: verify field validity */

    id = get_bits(&s->gb, 8);



    switch (id) {

    case 1:

        s->maxval = get_bits(&s->gb, 16);

        s->t1     = get_bits(&s->gb, 16);

        s->t2     = get_bits(&s->gb, 16);

        s->t3     = get_bits(&s->gb, 16);

        s->reset  = get_bits(&s->gb, 16);



//        ff_jpegls_reset_coding_parameters(s, 0);

        //FIXME quant table?

        break;

    case 2:

        s->palette_index = 0;

    case 3:

        tid= get_bits(&s->gb, 8);

        wt = get_bits(&s->gb, 8);



        if (len < 5)

            return AVERROR_INVALIDDATA;



        if (wt < 1 || wt > MAX_COMPONENTS) {

            avpriv_request_sample(s->avctx, "wt %d", wt);

            return AVERROR_PATCHWELCOME;

        }



        if (!s->maxval)

            maxtab = 255;

        else if ((5 + wt*(s->maxval+1)) < 65535)

            maxtab = s->maxval;

        else

            maxtab = 65530/wt - 1;



        if(s->avctx->debug & FF_DEBUG_PICT_INFO) {

            av_log(s->avctx, AV_LOG_DEBUG, "LSE palette %d tid:%d wt:%d maxtab:%d\n", id, tid, wt, maxtab);

        }

        if (maxtab >= 256) {

            avpriv_request_sample(s->avctx, ">8bit palette");

            return AVERROR_PATCHWELCOME;

        }

        maxtab = FFMIN(maxtab, (len - 5) / wt + s->palette_index);



        if (s->palette_index > maxtab)

            return AVERROR_INVALIDDATA;



        if ((s->avctx->pix_fmt == AV_PIX_FMT_GRAY8 || s->avctx->pix_fmt == AV_PIX_FMT_PAL8) &&

            (s->picture_ptr->format == AV_PIX_FMT_GRAY8 || s->picture_ptr->format == AV_PIX_FMT_PAL8)) {

            uint32_t *pal = s->picture_ptr->data[1];

            s->picture_ptr->format =

            s->avctx->pix_fmt = AV_PIX_FMT_PAL8;

            for (i=s->palette_index; i<=maxtab; i++) {

                pal[i] = 0;

                for (j=0; j<wt; j++) {

                    pal[i] |= get_bits(&s->gb, 8) << (8*(wt-j-1));

                }

            }

            s->palette_index = i;

        }

        break;

    case 4:

        avpriv_request_sample(s->avctx, "oversize image");

        return AVERROR(ENOSYS);

    default:

        av_log(s->avctx, AV_LOG_ERROR, "invalid id %d\n", id);

        return AVERROR_INVALIDDATA;

    }

    av_dlog(s->avctx, "ID=%i, T=%i,%i,%i\n", id, s->t1, s->t2, s->t3);



    return 0;

}

static int mov_read_stss(MOVContext *c, AVIOContext *pb, MOVAtom atom)

{

    AVStream *st;

    MOVStreamContext *sc;

    unsigned int i, entries;



    if (c->fc->nb_streams < 1)

        return 0;

    st = c->fc->streams[c->fc->nb_streams-1];

    sc = st->priv_data;



    avio_r8(pb); /* version */

    avio_rb24(pb); /* flags */



    entries = avio_rb32(pb);



    av_dlog(c->fc, "keyframe_count = %d\n", entries);



    if (!entries)

    {

        sc->keyframe_absent = 1;

        if (!st->need_parsing)

            st->need_parsing = AVSTREAM_PARSE_HEADERS;

        return 0;

    }

    if (entries >= UINT_MAX / sizeof(int))

        return AVERROR_INVALIDDATA;

    sc->keyframes = av_malloc(entries * sizeof(int));

    if (!sc->keyframes)

        return AVERROR(ENOMEM);



    for (i = 0; i < entries && !pb->eof_reached; i++) {

        sc->keyframes[i] = avio_rb32(pb);

        //av_dlog(c->fc, "keyframes[]=%d\n", sc->keyframes[i]);

    }



    sc->keyframe_count = i;



    if (pb->eof_reached)

        return AVERROR_EOF;



    return 0;

}

void swr_compensate(struct SwrContext *s, int sample_delta, int compensation_distance){

    ResampleContext *c= s->resample;

//    sample_delta += (c->ideal_dst_incr - c->dst_incr)*(int64_t)c->compensation_distance / c->ideal_dst_incr;

    c->compensation_distance= compensation_distance;

    c->dst_incr = c->ideal_dst_incr - c->ideal_dst_incr * (int64_t)sample_delta / compensation_distance;

}

int MPV_frame_start(MpegEncContext *s, AVCodecContext *avctx)

{

    int i;

    Picture *pic;

    s->mb_skipped = 0;



    assert(s->last_picture_ptr==NULL || s->out_format != FMT_H264 || s->codec_id == CODEC_ID_SVQ3);



    /* mark&release old frames */

    if (s->pict_type != FF_B_TYPE && s->last_picture_ptr && s->last_picture_ptr != s->next_picture_ptr && s->last_picture_ptr->data[0]) {

      if(s->out_format != FMT_H264 || s->codec_id == CODEC_ID_SVQ3){

          free_frame_buffer(s, s->last_picture_ptr);



        /* release forgotten pictures */

        /* if(mpeg124/h263) */

        if(!s->encoding){

            for(i=0; i<MAX_PICTURE_COUNT; i++){

                if(s->picture[i].data[0] && &s->picture[i] != s->next_picture_ptr && s->picture[i].reference){

                    av_log(avctx, AV_LOG_ERROR, "releasing zombie picture\n");

                    free_frame_buffer(s, &s->picture[i]);

                }

            }

        }

      }

    }

alloc:

    if(!s->encoding){

        /* release non reference frames */

        for(i=0; i<MAX_PICTURE_COUNT; i++){

            if(s->picture[i].data[0] && !s->picture[i].reference /*&& s->picture[i].type!=FF_BUFFER_TYPE_SHARED*/){

                free_frame_buffer(s, &s->picture[i]);

            }

        }



        if(s->current_picture_ptr && s->current_picture_ptr->data[0]==NULL)

            pic= s->current_picture_ptr; //we already have a unused image (maybe it was set before reading the header)

        else{

            i= ff_find_unused_picture(s, 0);

            pic= &s->picture[i];

        }



        pic->reference= 0;

        if (!s->dropable){

            if (s->codec_id == CODEC_ID_H264)

                pic->reference = s->picture_structure;

            else if (s->pict_type != FF_B_TYPE)

                pic->reference = 3;

        }



        pic->coded_picture_number= s->coded_picture_number++;



        if(ff_alloc_picture(s, pic, 0) < 0)

            return -1;



        s->current_picture_ptr= pic;

        s->current_picture_ptr->top_field_first= s->top_field_first; //FIXME use only the vars from current_pic

        s->current_picture_ptr->interlaced_frame= !s->progressive_frame && !s->progressive_sequence;

    }



    s->current_picture_ptr->pict_type= s->pict_type;

//    if(s->flags && CODEC_FLAG_QSCALE)

  //      s->current_picture_ptr->quality= s->new_picture_ptr->quality;

    s->current_picture_ptr->key_frame= s->pict_type == FF_I_TYPE;



    ff_copy_picture(&s->current_picture, s->current_picture_ptr);



    if (s->pict_type != FF_B_TYPE) {

        s->last_picture_ptr= s->next_picture_ptr;

        if(!s->dropable)

            s->next_picture_ptr= s->current_picture_ptr;

    }

/*    av_log(s->avctx, AV_LOG_DEBUG, "L%p N%p C%p L%p N%p C%p type:%d drop:%d\n", s->last_picture_ptr, s->next_picture_ptr,s->current_picture_ptr,

        s->last_picture_ptr    ? s->last_picture_ptr->data[0] : NULL,

        s->next_picture_ptr    ? s->next_picture_ptr->data[0] : NULL,

        s->current_picture_ptr ? s->current_picture_ptr->data[0] : NULL,

        s->pict_type, s->dropable);*/



    if(s->last_picture_ptr) ff_copy_picture(&s->last_picture, s->last_picture_ptr);

    if(s->next_picture_ptr) ff_copy_picture(&s->next_picture, s->next_picture_ptr);



    if(s->pict_type != FF_I_TYPE && (s->last_picture_ptr==NULL || s->last_picture_ptr->data[0]==NULL) && !s->dropable && s->codec_id != CODEC_ID_H264){

        av_log(avctx, AV_LOG_ERROR, "warning: first frame is no keyframe\n");

        assert(s->pict_type != FF_B_TYPE); //these should have been dropped if we don't have a reference

        goto alloc;

    }



    assert(s->pict_type == FF_I_TYPE || (s->last_picture_ptr && s->last_picture_ptr->data[0]));



    if(s->picture_structure!=PICT_FRAME && s->out_format != FMT_H264){

        int i;

        for(i=0; i<4; i++){

            if(s->picture_structure == PICT_BOTTOM_FIELD){

                 s->current_picture.data[i] += s->current_picture.linesize[i];

            }

            s->current_picture.linesize[i] *= 2;

            s->last_picture.linesize[i] *=2;

            s->next_picture.linesize[i] *=2;

        }

    }



    s->hurry_up= s->avctx->hurry_up;

    s->error_recognition= avctx->error_recognition;



    /* set dequantizer, we can't do it during init as it might change for mpeg4

       and we can't do it in the header decode as init is not called for mpeg4 there yet */

    if(s->mpeg_quant || s->codec_id == CODEC_ID_MPEG2VIDEO){

        s->dct_unquantize_intra = s->dct_unquantize_mpeg2_intra;

        s->dct_unquantize_inter = s->dct_unquantize_mpeg2_inter;

    }else if(s->out_format == FMT_H263 || s->out_format == FMT_H261){

        s->dct_unquantize_intra = s->dct_unquantize_h263_intra;

        s->dct_unquantize_inter = s->dct_unquantize_h263_inter;

    }else{

        s->dct_unquantize_intra = s->dct_unquantize_mpeg1_intra;

        s->dct_unquantize_inter = s->dct_unquantize_mpeg1_inter;

    }



    if(s->dct_error_sum){

        assert(s->avctx->noise_reduction && s->encoding);



        update_noise_reduction(s);

    }



    if(CONFIG_MPEG_XVMC_DECODER && s->avctx->xvmc_acceleration)

        return ff_xvmc_field_start(s, avctx);



    return 0;

}

static int pcm_dvd_decode_frame(AVCodecContext *avctx, void *data,

                                int *got_frame_ptr, AVPacket *avpkt)

{

    AVFrame *frame     = data;

    const uint8_t *src = avpkt->data;

    int buf_size       = avpkt->size;

    PCMDVDContext *s   = avctx->priv_data;

    int retval;

    int blocks;

    void *dst;



    if (buf_size < 3) {

        av_log(avctx, AV_LOG_ERROR, "PCM packet too small\n");

        return AVERROR_INVALIDDATA;




    if ((retval = pcm_dvd_parse_header(avctx, src)))

        return retval;






    src      += 3;

    buf_size -= 3;



    blocks = (buf_size + s->extra_sample_count) / s->block_size;



    /* get output buffer */

    frame->nb_samples = blocks * s->samples_per_block;

    if ((retval = ff_get_buffer(avctx, frame, 0)) < 0) {

        av_log(avctx, AV_LOG_ERROR, "get_buffer() failed\n");

        return retval;


    dst = frame->data[0];



    /* consume leftover samples from last packet */

    if (s->extra_sample_count) {

        int missing_samples = s->block_size - s->extra_sample_count;

        if (buf_size >= missing_samples) {

            memcpy(s->extra_samples + s->extra_sample_count, src,

                   missing_samples);

            dst = pcm_dvd_decode_samples(avctx, s->extra_samples, dst, 1);

            src += missing_samples;

            buf_size -= missing_samples;


            blocks--;

        } else {

            /* new packet still doesn't have enough samples */

            memcpy(s->extra_samples + s->extra_sample_count, src, buf_size);

            s->extra_sample_count += buf_size;

            return avpkt->size;





    /* decode remaining complete samples */

    if (blocks) {

        pcm_dvd_decode_samples(avctx, src, dst, blocks);

        buf_size -= blocks * s->block_size;




    /* store leftover samples */

    if (buf_size) {

        src += blocks * s->block_size;

        memcpy(s->extra_samples, src, buf_size);

        s->extra_sample_count = buf_size;




    *got_frame_ptr = 1;



    return avpkt->size;

static inline void ls_decode_line(JLSState *state, MJpegDecodeContext *s,

                                  void *last, void *dst, int last2, int w,

                                  int stride, int comp, int bits)

{

    int i, x = 0;

    int Ra, Rb, Rc, Rd;

    int D0, D1, D2;



    while (x < w) {

        int err, pred;



        /* compute gradients */

        Ra = x ? R(dst, x - stride) : R(last, x);

        Rb = R(last, x);

        Rc = x ? R(last, x - stride) : last2;

        Rd = (x >= w - stride) ? R(last, x) : R(last, x + stride);

        D0 = Rd - Rb;

        D1 = Rb - Rc;

        D2 = Rc - Ra;

        /* run mode */

        if ((FFABS(D0) <= state->near) &&

            (FFABS(D1) <= state->near) &&

            (FFABS(D2) <= state->near)) {

            int r;

            int RItype;



            /* decode full runs while available */

            while (get_bits1(&s->gb)) {

                int r;

                r = 1 << ff_log2_run[state->run_index[comp]];

                if (x + r * stride > w)

                    r = (w - x) / stride;

                for (i = 0; i < r; i++) {

                    W(dst, x, Ra);

                    x += stride;

                }

                /* if EOL reached, we stop decoding */

                if (r != 1 << ff_log2_run[state->run_index[comp]])

                    return;

                if (state->run_index[comp] < 31)

                    state->run_index[comp]++;

                if (x + stride > w)

                    return;

            }

            /* decode aborted run */

            r = ff_log2_run[state->run_index[comp]];

            if (r)

                r = get_bits_long(&s->gb, r);

            if (x + r * stride > w) {

                r = (w - x) / stride;

            }

            for (i = 0; i < r; i++) {

                W(dst, x, Ra);

                x += stride;

            }



            if (x >= w) {

                av_log(NULL, AV_LOG_ERROR, "run overflow\n");


                return;

            }



            /* decode run termination value */

            Rb     = R(last, x);

            RItype = (FFABS(Ra - Rb) <= state->near) ? 1 : 0;

            err    = ls_get_code_runterm(&s->gb, state, RItype,

                                         ff_log2_run[state->run_index[comp]]);

            if (state->run_index[comp])

                state->run_index[comp]--;



            if (state->near && RItype) {

                pred = Ra + err;

            } else {

                if (Rb < Ra)

                    pred = Rb - err;

                else

                    pred = Rb + err;

            }

        } else { /* regular mode */

            int context, sign;



            context = ff_jpegls_quantize(state, D0) * 81 +

                      ff_jpegls_quantize(state, D1) *  9 +

                      ff_jpegls_quantize(state, D2);

            pred    = mid_pred(Ra, Ra + Rb - Rc, Rb);



            if (context < 0) {

                context = -context;

                sign    = 1;

            } else {

                sign = 0;

            }



            if (sign) {

                pred = av_clip(pred - state->C[context], 0, state->maxval);

                err  = -ls_get_code_regular(&s->gb, state, context);

            } else {

                pred = av_clip(pred + state->C[context], 0, state->maxval);

                err  = ls_get_code_regular(&s->gb, state, context);

            }



            /* we have to do something more for near-lossless coding */

            pred += err;

        }

        if (state->near) {

            if (pred < -state->near)

                pred += state->range * state->twonear;

            else if (pred > state->maxval + state->near)

                pred -= state->range * state->twonear;

            pred = av_clip(pred, 0, state->maxval);

        }



        pred &= state->maxval;

        W(dst, x, pred);

        x += stride;

    }

}

static void do_video_out(AVFormatContext *s,

                         OutputStream *ost,

                         AVFrame *in_picture,

                         float quality)

{

    int ret, format_video_sync;

    AVPacket pkt;

    AVCodecContext *enc = ost->st->codec;

    int nb_frames;

    double sync_ipts, delta;

    double duration = 0;

    int frame_size = 0;

    InputStream *ist = NULL;



    if (ost->source_index >= 0)

        ist = input_streams[ost->source_index];



    if(ist && ist->st->start_time != AV_NOPTS_VALUE && ist->st->first_dts != AV_NOPTS_VALUE && ost->frame_rate.num)

        duration = 1/(av_q2d(ost->frame_rate) * av_q2d(enc->time_base));



    sync_ipts = in_picture->pts;

    delta = sync_ipts - ost->sync_opts + duration;



    /* by default, we output a single frame */

    nb_frames = 1;



    format_video_sync = video_sync_method;

    if (format_video_sync == VSYNC_AUTO)

        format_video_sync = (s->oformat->flags & AVFMT_VARIABLE_FPS) ? ((s->oformat->flags & AVFMT_NOTIMESTAMPS) ? VSYNC_PASSTHROUGH : VSYNC_VFR) : 1;



    switch (format_video_sync) {

    case VSYNC_CFR:

        // FIXME set to 0.5 after we fix some dts/pts bugs like in avidec.c

        if (delta < -1.1)

            nb_frames = 0;

        else if (delta > 1.1)

            nb_frames = lrintf(delta);

        break;

    case VSYNC_VFR:

        if (delta <= -0.6)

            nb_frames = 0;

        else if (delta > 0.6)

            ost->sync_opts = lrint(sync_ipts);

        break;

    case VSYNC_DROP:

    case VSYNC_PASSTHROUGH:

        ost->sync_opts = lrint(sync_ipts);

        break;

    default:

        av_assert0(0);

    }



    nb_frames = FFMIN(nb_frames, ost->max_frames - ost->frame_number);

    if (nb_frames == 0) {

        nb_frames_drop++;

        av_log(NULL, AV_LOG_VERBOSE, "*** drop!\n");

        return;

    } else if (nb_frames > 1) {

        if (nb_frames > dts_error_threshold * 30) {

            av_log(NULL, AV_LOG_ERROR, "%d frame duplication too large, skiping\n", nb_frames - 1);

            nb_frames_drop++;

            return;

        }

        nb_frames_dup += nb_frames - 1;

        av_log(NULL, AV_LOG_VERBOSE, "*** %d dup!\n", nb_frames - 1);

    }





duplicate_frame:

    av_init_packet(&pkt);

    pkt.data = NULL;

    pkt.size = 0;



    in_picture->pts = ost->sync_opts;



    if (!check_recording_time(ost))

        return;



    if (s->oformat->flags & AVFMT_RAWPICTURE &&

        enc->codec->id == CODEC_ID_RAWVIDEO) {

        /* raw pictures are written as AVPicture structure to

           avoid any copies. We support temporarily the older

           method. */

        enc->coded_frame->interlaced_frame = in_picture->interlaced_frame;

        enc->coded_frame->top_field_first  = in_picture->top_field_first;

        pkt.data   = (uint8_t *)in_picture;

        pkt.size   =  sizeof(AVPicture);

        pkt.pts    = av_rescale_q(in_picture->pts, enc->time_base, ost->st->time_base);

        pkt.flags |= AV_PKT_FLAG_KEY;



        write_frame(s, &pkt, ost);

        video_size += pkt.size;

    } else {

        int got_packet;

        AVFrame big_picture;



        big_picture = *in_picture;

        /* better than nothing: use input picture interlaced

           settings */

        big_picture.interlaced_frame = in_picture->interlaced_frame;

        if (ost->st->codec->flags & (CODEC_FLAG_INTERLACED_DCT|CODEC_FLAG_INTERLACED_ME)) {

            if (ost->top_field_first == -1)

                big_picture.top_field_first = in_picture->top_field_first;

            else

                big_picture.top_field_first = !!ost->top_field_first;

        }



        /* handles same_quant here. This is not correct because it may

           not be a global option */

        big_picture.quality = quality;

        if (!enc->me_threshold)

            big_picture.pict_type = 0;

        if (ost->forced_kf_index < ost->forced_kf_count &&

            big_picture.pts >= ost->forced_kf_pts[ost->forced_kf_index]) {

            big_picture.pict_type = AV_PICTURE_TYPE_I;

            ost->forced_kf_index++;

        }

        update_benchmark(NULL);

        ret = avcodec_encode_video2(enc, &pkt, &big_picture, &got_packet);

        update_benchmark("encode_video %d.%d", ost->file_index, ost->index);

        if (ret < 0) {

            av_log(NULL, AV_LOG_FATAL, "Video encoding failed\n");

            exit_program(1);

        }



        if (got_packet) {

            if (pkt.pts == AV_NOPTS_VALUE && !(enc->codec->capabilities & CODEC_CAP_DELAY))

                pkt.pts = ost->sync_opts;



            if (pkt.pts != AV_NOPTS_VALUE)

                pkt.pts = av_rescale_q(pkt.pts, enc->time_base, ost->st->time_base);

            if (pkt.dts != AV_NOPTS_VALUE)

                pkt.dts = av_rescale_q(pkt.dts, enc->time_base, ost->st->time_base);



            if (debug_ts) {

                av_log(NULL, AV_LOG_INFO, "encoder -> type:video "

                    "pkt_pts:%s pkt_pts_time:%s pkt_dts:%s pkt_dts_time:%s\n",

                    av_ts2str(pkt.pts), av_ts2timestr(pkt.pts, &ost->st->time_base),

                    av_ts2str(pkt.dts), av_ts2timestr(pkt.dts, &ost->st->time_base));

            }



            write_frame(s, &pkt, ost);

            frame_size = pkt.size;

            video_size += pkt.size;

            av_free_packet(&pkt);



            /* if two pass, output log */

            if (ost->logfile && enc->stats_out) {

                fprintf(ost->logfile, "%s", enc->stats_out);

            }

        }

    }

    ost->sync_opts++;

    /*

     * For video, number of frames in == number of packets out.

     * But there may be reordering, so we can't throw away frames on encoder

     * flush, we need to limit them here, before they go into encoder.

     */

    ost->frame_number++;



    if(--nb_frames)

        goto duplicate_frame;



    if (vstats_filename && frame_size)

        do_video_stats(output_files[ost->file_index]->ctx, ost, frame_size);

}

int opt_loglevel(void *optctx, const char *opt, const char *arg)

{

    const struct { const char *name; int level; } log_levels[] = {

        { "quiet"  , AV_LOG_QUIET   },

        { "panic"  , AV_LOG_PANIC   },

        { "fatal"  , AV_LOG_FATAL   },

        { "error"  , AV_LOG_ERROR   },

        { "warning", AV_LOG_WARNING },

        { "info"   , AV_LOG_INFO    },

        { "verbose", AV_LOG_VERBOSE },

        { "debug"  , AV_LOG_DEBUG   },

    };

    char *tail;

    int level;

    int i;



    for (i = 0; i < FF_ARRAY_ELEMS(log_levels); i++) {

        if (!strcmp(log_levels[i].name, arg)) {

            av_log_set_level(log_levels[i].level);

            return 0;

        }

    }



    level = strtol(arg, &tail, 10);

    if (*tail) {

        av_log(NULL, AV_LOG_FATAL, "Invalid loglevel \"%s\". "

               "Possible levels are numbers or:\n", arg);

        for (i = 0; i < FF_ARRAY_ELEMS(log_levels); i++)

            av_log(NULL, AV_LOG_FATAL, "\"%s\"\n", log_levels[i].name);

        exit(1);

    }

    av_log_set_level(level);

    return 0;

}

const AVOption *av_opt_next(void *obj, const AVOption *last)

{

    AVClass *class = *(AVClass**)obj;

    if (!last && class->option && class->option[0].name)

        return class->option;

    if (last && last[1].name)

        return ++last;

    return NULL;

}

int avfilter_graph_create_filter(AVFilterContext **filt_ctx, AVFilter *filt,

                                 const char *name, const char *args, void *opaque,

                                 AVFilterGraph *graph_ctx)

{

    int ret;



    *filt_ctx = avfilter_graph_alloc_filter(graph_ctx, filt, name);

    if (!*filt_ctx)

        return AVERROR(ENOMEM);



    ret = avfilter_init_filter(*filt_ctx, args, opaque);

    if (ret < 0)

        goto fail;



    return 0;



fail:

    if (*filt_ctx)

        avfilter_free(*filt_ctx);

    *filt_ctx = NULL;

    return ret;

}

int ff_pred_weight_table(H264Context *h)
{
    int list, i;
    int luma_def, chroma_def;
    h->use_weight             = 0;
    h->use_weight_chroma      = 0;
    h->luma_log2_weight_denom = get_ue_golomb(&h->gb);
    if (h->sps.chroma_format_idc)
        h->chroma_log2_weight_denom = get_ue_golomb(&h->gb);
    luma_def   = 1 << h->luma_log2_weight_denom;
    chroma_def = 1 << h->chroma_log2_weight_denom;
    for (list = 0; list < 2; list++) {
        h->luma_weight_flag[list]   = 0;
        h->chroma_weight_flag[list] = 0;
        for (i = 0; i < h->ref_count[list]; i++) {
            int luma_weight_flag, chroma_weight_flag;
            luma_weight_flag = get_bits1(&h->gb);
            if (luma_weight_flag) {
                h->luma_weight[i][list][0] = get_se_golomb(&h->gb);
                h->luma_weight[i][list][1] = get_se_golomb(&h->gb);
                if (h->luma_weight[i][list][0] != luma_def ||
                    h->luma_weight[i][list][1] != 0) {
                    h->use_weight             = 1;
                    h->luma_weight_flag[list] = 1;
            } else {
                h->luma_weight[i][list][0] = luma_def;
                h->luma_weight[i][list][1] = 0;
            if (h->sps.chroma_format_idc) {
                chroma_weight_flag = get_bits1(&h->gb);
