                        h->chroma_weight[i][list][j][1] = get_se_golomb(&h->gb);
                        if (h->chroma_weight[i][list][j][0] != chroma_def ||
                            h->chroma_weight[i][list][j][1] != 0) {
                            h->use_weight_chroma        = 1;
                            h->chroma_weight_flag[list] = 1;
                } else {
                    int j;
                    for (j = 0; j < 2; j++) {
                        h->chroma_weight[i][list][j][0] = chroma_def;
                        h->chroma_weight[i][list][j][1] = 0;
        if (h->slice_type_nos != AV_PICTURE_TYPE_B)
            break;
    h->use_weight = h->use_weight || h->use_weight_chroma;
    return 0;

static int mpeg_decode_frame(AVCodecContext *avctx, void *data,

                             int *got_output, AVPacket *avpkt)

{

    const uint8_t *buf = avpkt->data;

    int buf_size = avpkt->size;

    Mpeg1Context *s = avctx->priv_data;

    AVFrame *picture = data;

    MpegEncContext *s2 = &s->mpeg_enc_ctx;

    av_dlog(avctx, "fill_buffer\n");



    if (buf_size == 0 || (buf_size == 4 && AV_RB32(buf) == SEQ_END_CODE)) {

        /* special case for last picture */

        if (s2->low_delay == 0 && s2->next_picture_ptr) {

            int ret = av_frame_ref(picture, &s2->next_picture_ptr->f);

            if (ret < 0)

                return ret;



            s2->next_picture_ptr = NULL;



            *got_output = 1;

        }

        return buf_size;

    }



    if (s2->flags & CODEC_FLAG_TRUNCATED) {

        int next = ff_mpeg1_find_frame_end(&s2->parse_context, buf,

                                           buf_size, NULL);



        if (ff_combine_frame(&s2->parse_context, next,

                             (const uint8_t **) &buf, &buf_size) < 0)

            return buf_size;

    }



    if (s->mpeg_enc_ctx_allocated == 0 && avctx->codec_tag == AV_RL32("VCR2"))

        vcr2_init_sequence(avctx);



    s->slice_count = 0;



    if (avctx->extradata && !s->extradata_decoded) {

        int ret = decode_chunks(avctx, picture, got_output,

                                avctx->extradata, avctx->extradata_size);

        s->extradata_decoded = 1;

        if (ret < 0 && (avctx->err_recognition & AV_EF_EXPLODE))

            return ret;

    }



    return decode_chunks(avctx, picture, got_output, buf, buf_size);

}

static void blur(CoverContext *cover, AVFrame *in, int offx, int offy)

{

    int x, y, p;



    for (p=0; p<3; p++) {

        int ox = offx>>!!p;

        int oy = offy>>!!p;

        int stride = in->linesize[p];

        uint8_t *data = in->data[p] + ox + oy * stride;

        int w = FF_CEIL_RSHIFT(cover->width , !!p);

        int h = FF_CEIL_RSHIFT(cover->height, !!p);

        int iw = FF_CEIL_RSHIFT(in->width , !!p);

        int ih = FF_CEIL_RSHIFT(in->height, !!p);

        for (y = 0; y < h; y++) {

            for (x = 0; x < w; x++) {

                int c = 0;

                int s = 0;

                if (ox) {

                    int scale = 65536 / (x + 1);

                    s += data[-1 + y*stride] * scale;

                    c += scale;

                }

                if (oy) {

                    int scale = 65536 / (y + 1);

                    s += data[x - stride] * scale;

                    c += scale;

                }

                if (ox + w < iw) {

                    int scale = 65536 / (w - x);

                    s += data[w + y*stride] * scale;

                    c += scale;

                }

                if (oy + h < ih) {

                    int scale = 65536 / (h - y);

                    s += data[x + h*stride] * scale;

                    c += scale;

                }

                data[x + y*stride] = (s + (c>>1)) / c;

            }

        }

    }

}

static int wav_read_header(AVFormatContext *s)
{
    int64_t size, av_uninit(data_size);
    int64_t sample_count = 0;
    int rf64 = 0;
    char start_code[32];
    uint32_t tag;
    AVIOContext *pb      = s->pb;
    AVStream *st         = NULL;
    WAVDemuxContext *wav = s->priv_data;
    int ret, got_fmt = 0;
    int64_t next_tag_ofs, data_ofs = -1;
    wav->unaligned = avio_tell(s->pb) & 1;
    wav->smv_data_ofs = -1;
    /* read chunk ID */
    tag = avio_rl32(pb);
    switch (tag) {
    case MKTAG('R', 'I', 'F', 'F'):
        break;
    case MKTAG('R', 'I', 'F', 'X'):
        wav->rifx = 1;
        break;
    case MKTAG('R', 'F', '6', '4'):
        rf64 = 1;
        break;
    default:
        av_get_codec_tag_string(start_code, sizeof(start_code), tag);
        av_log(s, AV_LOG_ERROR, "invalid start code %s in RIFF header\n", start_code);
        return AVERROR_INVALIDDATA;
    /* read chunk size */
    avio_rl32(pb);
    /* read format */
    if (avio_rl32(pb) != MKTAG('W', 'A', 'V', 'E')) {
        av_log(s, AV_LOG_ERROR, "invalid format in RIFF header\n");
        return AVERROR_INVALIDDATA;
    if (rf64) {
        if (avio_rl32(pb) != MKTAG('d', 's', '6', '4'))
            return AVERROR_INVALIDDATA;
        size = avio_rl32(pb);
        if (size < 24)
            return AVERROR_INVALIDDATA;
        avio_rl64(pb); /* RIFF size */
        data_size    = avio_rl64(pb);
        sample_count = avio_rl64(pb);
        if (data_size < 0 || sample_count < 0) {
            av_log(s, AV_LOG_ERROR, "negative data_size and/or sample_count in "
                   "ds64: data_size = %"PRId64", sample_count = %"PRId64"\n",
                   data_size, sample_count);
            return AVERROR_INVALIDDATA;
        avio_skip(pb, size - 24); /* skip rest of ds64 chunk */
    for (;;) {
        AVStream *vst;
        size         = next_tag(pb, &tag, wav->rifx);
        next_tag_ofs = avio_tell(pb) + size;
        if (avio_feof(pb))
            break;
        switch (tag) {
        case MKTAG('f', 'm', 't', ' '):
            /* only parse the first 'fmt ' tag found */
            if (!got_fmt && (ret = wav_parse_fmt_tag(s, size, &st)) < 0) {
                return ret;
            } else if (got_fmt)
                av_log(s, AV_LOG_WARNING, "found more than one 'fmt ' tag\n");
            got_fmt = 1;
            break;
        case MKTAG('d', 'a', 't', 'a'):
            if (!got_fmt) {
                av_log(s, AV_LOG_ERROR,
                       "found no 'fmt ' tag before the 'data' tag\n");
                return AVERROR_INVALIDDATA;
            if (rf64) {
                next_tag_ofs = wav->data_end = avio_tell(pb) + data_size;
            } else if (size != 0xFFFFFFFF) {
                data_size    = size;
                next_tag_ofs = wav->data_end = size ? next_tag_ofs : INT64_MAX;
            } else {
                av_log(s, AV_LOG_WARNING, "Ignoring maximum wav data size, "
                       "file may be invalid\n");
                data_size    = 0;
                next_tag_ofs = wav->data_end = INT64_MAX;
            data_ofs = avio_tell(pb);
            /* don't look for footer metadata if we can't seek or if we don't
             * know where the data tag ends
             */
            if (!pb->seekable || (!rf64 && !size))
                goto break_loop;
            break;
        case MKTAG('f', 'a', 'c', 't'):
            if (!sample_count)
                sample_count = (!wav->rifx ? avio_rl32(pb) : avio_rb32(pb));
            break;
        case MKTAG('b', 'e', 'x', 't'):
            if ((ret = wav_parse_bext_tag(s, size)) < 0)
                return ret;
            break;
        case MKTAG('S','M','V','0'):
            if (!got_fmt) {
                av_log(s, AV_LOG_ERROR, "found no 'fmt ' tag before the 'SMV0' tag\n");
                return AVERROR_INVALIDDATA;
            // SMV file, a wav file with video appended.
            if (size != MKTAG('0','2','0','0')) {
                av_log(s, AV_LOG_ERROR, "Unknown SMV version found\n");
                goto break_loop;
            av_log(s, AV_LOG_DEBUG, "Found SMV data\n");
            wav->smv_given_first = 0;
            vst = avformat_new_stream(s, NULL);
            if (!vst)
                return AVERROR(ENOMEM);
            avio_r8(pb);
            vst->id = 1;
            vst->codec->codec_type = AVMEDIA_TYPE_VIDEO;
            vst->codec->codec_id = AV_CODEC_ID_SMVJPEG;
            vst->codec->width  = avio_rl24(pb);
            vst->codec->height = avio_rl24(pb);
            if (ff_alloc_extradata(vst->codec, 4)) {
                av_log(s, AV_LOG_ERROR, "Could not allocate extradata.\n");
                return AVERROR(ENOMEM);
            size = avio_rl24(pb);
            wav->smv_data_ofs = avio_tell(pb) + (size - 5) * 3;
            avio_rl24(pb);
            wav->smv_block_size = avio_rl24(pb);
            avpriv_set_pts_info(vst, 32, 1, avio_rl24(pb));
            vst->duration = avio_rl24(pb);
            avio_rl24(pb);
            avio_rl24(pb);
            wav->smv_frames_per_jpeg = avio_rl24(pb);
            if (wav->smv_frames_per_jpeg > 65536) {
                av_log(s, AV_LOG_ERROR, "too many frames per jpeg\n");
                return AVERROR_INVALIDDATA;
            AV_WL32(vst->codec->extradata, wav->smv_frames_per_jpeg);
            wav->smv_cur_pt = 0;
            goto break_loop;
        case MKTAG('L', 'I', 'S', 'T'):
            if (size < 4) {
                av_log(s, AV_LOG_ERROR, "too short LIST tag\n");
                return AVERROR_INVALIDDATA;
            switch (avio_rl32(pb)) {
            case MKTAG('I', 'N', 'F', 'O'):
                ff_read_riff_info(s, size - 4);
            break;
        /* seek to next tag unless we know that we'll run into EOF */
        if ((avio_size(pb) > 0 && next_tag_ofs >= avio_size(pb)) ||
            wav_seek_tag(wav, pb, next_tag_ofs, SEEK_SET) < 0) {
            break;
break_loop:
    if (data_ofs < 0) {
        av_log(s, AV_LOG_ERROR, "no 'data' tag found\n");
        return AVERROR_INVALIDDATA;
    avio_seek(pb, data_ofs, SEEK_SET);
    if (   data_size > 0 && sample_count && st->codec->channels
        && (data_size << 3) / sample_count / st->codec->channels > st->codec->bits_per_coded_sample) {
        av_log(s, AV_LOG_WARNING, "ignoring wrong sample_count %"PRId64"\n", sample_count);
        sample_count = 0;
    if (!sample_count || av_get_exact_bits_per_sample(st->codec->codec_id) > 0)
        if (   st->codec->channels
            && data_size
            && av_get_bits_per_sample(st->codec->codec_id)
            && wav->data_end <= avio_size(pb))
            sample_count = (data_size << 3)
                                  /
                (st->codec->channels * (uint64_t)av_get_bits_per_sample(st->codec->codec_id));
    if (sample_count)
        st->duration = sample_count;
    ff_metadata_conv_ctx(s, NULL, wav_metadata_conv);
    ff_metadata_conv_ctx(s, NULL, ff_riff_info_conv);
    return 0;

static int parse_bsfs(void *log_ctx, const char *bsfs_spec,

                      AVBitStreamFilterContext **bsfs)

{

    char *bsf_name, *buf, *saveptr;

    int ret = 0;



    if (!(buf = av_strdup(bsfs_spec)))

        return AVERROR(ENOMEM);



    while (bsf_name = av_strtok(buf, ",", &saveptr)) {

        AVBitStreamFilterContext *bsf = av_bitstream_filter_init(bsf_name);



        if (!bsf) {

            av_log(log_ctx, AV_LOG_ERROR,

                   "Cannot initialize bitstream filter with name '%s', "

                   "unknown filter or internal error happened\n",

                   bsf_name);

            ret = AVERROR_UNKNOWN;

            goto end;

        }



        /* append bsf context to the list of bsf contexts */

        *bsfs = bsf;

        bsfs = &bsf->next;



        buf = NULL;

    }



end:

    av_free(buf);

    return ret;

}

void ff_ivi_output_plane(IVIPlaneDesc *plane, uint8_t *dst, int dst_pitch)
{
    int             x, y;
    const int16_t   *src  = plane->bands[0].buf;
    uint32_t        pitch = plane->bands[0].pitch;
    for (y = 0; y < plane->height; y++) {
        for (x = 0; x < plane->width; x++)
            dst[x] = av_clip_uint8(src[x] + 128);
        src += pitch;
        dst += dst_pitch;
    }
}

static int ff_estimate_motion_b(MpegEncContext * s,

                       int mb_x, int mb_y, int16_t (*mv_table)[2], int ref_index, int f_code)

{

    MotionEstContext * const c= &s->me;

    int mx, my, dmin;

    int P[10][2];

    const int shift= 1+s->quarter_sample;

    const int mot_stride = s->mb_stride;

    const int mot_xy = mb_y*mot_stride + mb_x;

    uint8_t * const mv_penalty= c->mv_penalty[f_code] + MAX_MV;

    int mv_scale;



    c->penalty_factor    = get_penalty_factor(s->lambda, s->lambda2, c->avctx->me_cmp);

    c->sub_penalty_factor= get_penalty_factor(s->lambda, s->lambda2, c->avctx->me_sub_cmp);

    c->mb_penalty_factor = get_penalty_factor(s->lambda, s->lambda2, c->avctx->mb_cmp);

    c->current_mv_penalty= mv_penalty;



    get_limits(s, 16*mb_x, 16*mb_y);



    switch(s->me_method) {

    case ME_ZERO:

    default:

	no_motion_search(s, &mx, &my);

        dmin = 0;

        mx-= mb_x*16;

        my-= mb_y*16;

        break;

#if 0

    case ME_FULL:

	dmin = full_motion_search(s, &mx, &my, range, ref_picture);

        mx-= mb_x*16;

        my-= mb_y*16;

        break;

    case ME_LOG:

	dmin = log_motion_search(s, &mx, &my, range / 2, ref_picture);

        mx-= mb_x*16;

        my-= mb_y*16;

        break;

    case ME_PHODS:

	dmin = phods_motion_search(s, &mx, &my, range / 2, ref_picture);

        mx-= mb_x*16;

        my-= mb_y*16;

        break;

#endif

    case ME_X1:

    case ME_EPZS:

       {

            P_LEFT[0]        = mv_table[mot_xy - 1][0];

            P_LEFT[1]        = mv_table[mot_xy - 1][1];



            if(P_LEFT[0]       > (c->xmax<<shift)) P_LEFT[0]       = (c->xmax<<shift);



            /* special case for first line */

            if (!s->first_slice_line) {

                P_TOP[0] = mv_table[mot_xy - mot_stride             ][0];

                P_TOP[1] = mv_table[mot_xy - mot_stride             ][1];

                P_TOPRIGHT[0] = mv_table[mot_xy - mot_stride + 1         ][0];

                P_TOPRIGHT[1] = mv_table[mot_xy - mot_stride + 1         ][1];

                if(P_TOP[1] > (c->ymax<<shift)) P_TOP[1]= (c->ymax<<shift);

                if(P_TOPRIGHT[0] < (c->xmin<<shift)) P_TOPRIGHT[0]= (c->xmin<<shift);

                if(P_TOPRIGHT[1] > (c->ymax<<shift)) P_TOPRIGHT[1]= (c->ymax<<shift);



                P_MEDIAN[0]= mid_pred(P_LEFT[0], P_TOP[0], P_TOPRIGHT[0]);

                P_MEDIAN[1]= mid_pred(P_LEFT[1], P_TOP[1], P_TOPRIGHT[1]);

            }

            c->pred_x= P_LEFT[0];

            c->pred_y= P_LEFT[1];

        }



        if(mv_table == s->b_forw_mv_table){

            mv_scale= (s->pb_time<<16) / (s->pp_time<<shift);

        }else{

            mv_scale= ((s->pb_time - s->pp_time)<<16) / (s->pp_time<<shift);

        }



        dmin = ff_epzs_motion_search(s, &mx, &my, P, 0, ref_index, s->p_mv_table, mv_scale, 0, 16);



        break;

    }



    dmin= c->sub_motion_search(s, &mx, &my, dmin, 0, ref_index, 0, 16);



    if(c->avctx->me_sub_cmp != c->avctx->mb_cmp && !c->skip)

        dmin= get_mb_score(s, mx, my, 0, ref_index);



//printf("%d %d %d %d//", s->mb_x, s->mb_y, mx, my);

//    s->mb_type[mb_y*s->mb_width + mb_x]= mb_type;

    mv_table[mot_xy][0]= mx;

    mv_table[mot_xy][1]= my;



    return dmin;

}

static int vc1_decode_b_mb_intfr(VC1Context *v)

{

    MpegEncContext *s = &v->s;

    GetBitContext *gb = &s->gb;

    int i, j;

    int mb_pos = s->mb_x + s->mb_y * s->mb_stride;

    int cbp = 0; /* cbp decoding stuff */

    int mqdiff, mquant; /* MB quantization */

    int ttmb = v->ttfrm; /* MB Transform type */

    int mvsw = 0; /* motion vector switch */

    int mb_has_coeffs = 1; /* last_flag */

    int dmv_x, dmv_y; /* Differential MV components */

    int val; /* temp value */

    int first_block = 1;

    int dst_idx, off;

    int skipped, direct, twomv = 0;

    int block_cbp = 0, pat, block_tt = 0;

    int idx_mbmode = 0, mvbp;

    int stride_y, fieldtx;

    int bmvtype = BMV_TYPE_BACKWARD;

    int dir, dir2;



    mquant = v->pq; /* Lossy initialization */

    s->mb_intra = 0;

    if (v->skip_is_raw)

        skipped = get_bits1(gb);

    else

        skipped = v->s.mbskip_table[mb_pos];



    if (!skipped) {

        idx_mbmode = get_vlc2(gb, v->mbmode_vlc->table, VC1_INTFR_NON4MV_MBMODE_VLC_BITS, 2);

        if (ff_vc1_mbmode_intfrp[0][idx_mbmode][0] == MV_PMODE_INTFR_2MV_FIELD) {

            twomv = 1;

            v->blk_mv_type[s->block_index[0]] = 1;

            v->blk_mv_type[s->block_index[1]] = 1;

            v->blk_mv_type[s->block_index[2]] = 1;

            v->blk_mv_type[s->block_index[3]] = 1;

        } else {

            v->blk_mv_type[s->block_index[0]] = 0;

            v->blk_mv_type[s->block_index[1]] = 0;

            v->blk_mv_type[s->block_index[2]] = 0;

            v->blk_mv_type[s->block_index[3]] = 0;

        }

    }



    if (v->dmb_is_raw)

        direct = get_bits1(gb);

    else

        direct = v->direct_mb_plane[mb_pos];



    if (direct) {



        s->mv[0][0][0] = s->current_picture.motion_val[0][s->block_index[0]][0] = scale_mv(s->next_picture.motion_val[1][s->block_index[0]][0], v->bfraction, 0, s->quarter_sample);

        s->mv[0][0][1] = s->current_picture.motion_val[0][s->block_index[0]][1] = scale_mv(s->next_picture.motion_val[1][s->block_index[0]][1], v->bfraction, 0, s->quarter_sample);

        s->mv[1][0][0] = s->current_picture.motion_val[1][s->block_index[0]][0] = scale_mv(s->next_picture.motion_val[1][s->block_index[0]][0], v->bfraction, 1, s->quarter_sample);

        s->mv[1][0][1] = s->current_picture.motion_val[1][s->block_index[0]][1] = scale_mv(s->next_picture.motion_val[1][s->block_index[0]][1], v->bfraction, 1, s->quarter_sample);



        if (twomv) {

            s->mv[0][2][0] = s->current_picture.motion_val[0][s->block_index[2]][0] = scale_mv(s->next_picture.motion_val[1][s->block_index[2]][0], v->bfraction, 0, s->quarter_sample);

            s->mv[0][2][1] = s->current_picture.motion_val[0][s->block_index[2]][1] = scale_mv(s->next_picture.motion_val[1][s->block_index[2]][1], v->bfraction, 0, s->quarter_sample);

            s->mv[1][2][0] = s->current_picture.motion_val[1][s->block_index[2]][0] = scale_mv(s->next_picture.motion_val[1][s->block_index[2]][0], v->bfraction, 1, s->quarter_sample);

            s->mv[1][2][1] = s->current_picture.motion_val[1][s->block_index[2]][1] = scale_mv(s->next_picture.motion_val[1][s->block_index[2]][1], v->bfraction, 1, s->quarter_sample);



            for (i = 1; i < 4; i += 2) {

                s->mv[0][i][0] = s->current_picture.motion_val[0][s->block_index[i]][0] = s->mv[0][i-1][0];

                s->mv[0][i][1] = s->current_picture.motion_val[0][s->block_index[i]][1] = s->mv[0][i-1][1];

                s->mv[1][i][0] = s->current_picture.motion_val[1][s->block_index[i]][0] = s->mv[1][i-1][0];

                s->mv[1][i][1] = s->current_picture.motion_val[1][s->block_index[i]][1] = s->mv[1][i-1][1];

            }

        } else {

            for (i = 1; i < 4; i++) {

                s->mv[0][i][0] = s->current_picture.motion_val[0][s->block_index[i]][0] = s->mv[0][0][0];

                s->mv[0][i][1] = s->current_picture.motion_val[0][s->block_index[i]][1] = s->mv[0][0][1];

                s->mv[1][i][0] = s->current_picture.motion_val[1][s->block_index[i]][0] = s->mv[1][0][0];

                s->mv[1][i][1] = s->current_picture.motion_val[1][s->block_index[i]][1] = s->mv[1][0][1];

            }

        }

    }



    if (ff_vc1_mbmode_intfrp[0][idx_mbmode][0] == MV_PMODE_INTFR_INTRA) { // intra MB

        for (i = 0; i < 4; i++) {

            s->mv[0][i][0] = s->current_picture.motion_val[0][s->block_index[i]][0] = 0;

            s->mv[0][i][1] = s->current_picture.motion_val[0][s->block_index[i]][1] = 0;

            s->mv[1][i][0] = s->current_picture.motion_val[1][s->block_index[i]][0] = 0;

            s->mv[1][i][1] = s->current_picture.motion_val[1][s->block_index[i]][1] = 0;

        }

        s->current_picture.mb_type[mb_pos] = MB_TYPE_INTRA;

        s->mb_intra = v->is_intra[s->mb_x] = 1;

        for (i = 0; i < 6; i++)

            v->mb_type[0][s->block_index[i]] = 1;

        fieldtx = v->fieldtx_plane[mb_pos] = get_bits1(gb);

        mb_has_coeffs = get_bits1(gb);

        if (mb_has_coeffs)

            cbp = 1 + get_vlc2(&v->s.gb, v->cbpcy_vlc->table, VC1_CBPCY_P_VLC_BITS, 2);

        v->s.ac_pred = v->acpred_plane[mb_pos] = get_bits1(gb);

        GET_MQUANT();

        s->current_picture.qscale_table[mb_pos] = mquant;

        /* Set DC scale - y and c use the same (not sure if necessary here) */

        s->y_dc_scale = s->y_dc_scale_table[mquant];

        s->c_dc_scale = s->c_dc_scale_table[mquant];

        dst_idx = 0;

        for (i = 0; i < 6; i++) {

            s->dc_val[0][s->block_index[i]] = 0;

            dst_idx += i >> 2;

            val = ((cbp >> (5 - i)) & 1);

            v->mb_type[0][s->block_index[i]] = s->mb_intra;

            v->a_avail = v->c_avail = 0;

            if (i == 2 || i == 3 || !s->first_slice_line)

                v->a_avail = v->mb_type[0][s->block_index[i] - s->block_wrap[i]];

            if (i == 1 || i == 3 || s->mb_x)

                v->c_avail = v->mb_type[0][s->block_index[i] - 1];



            vc1_decode_intra_block(v, s->block[i], i, val, mquant,

                                   (i & 4) ? v->codingset2 : v->codingset);

            if (i > 3 && (s->flags & CODEC_FLAG_GRAY))

                continue;

            v->vc1dsp.vc1_inv_trans_8x8(s->block[i]);

            if (i < 4) {

                stride_y = s->linesize << fieldtx;

                off = (fieldtx) ? ((i & 1) * 8) + ((i & 2) >> 1) * s->linesize : (i & 1) * 8 + 4 * (i & 2) * s->linesize;

            } else {

                stride_y = s->uvlinesize;

                off = 0;

            }

            s->dsp.put_signed_pixels_clamped(s->block[i], s->dest[dst_idx] + off, stride_y);

        }

    } else {

        s->mb_intra = v->is_intra[s->mb_x] = 0;

        if (!direct) {

            if (skipped || !s->mb_intra) {

                bmvtype = decode012(gb);

                switch (bmvtype) {

                case 0:

                    bmvtype = (v->bfraction >= (B_FRACTION_DEN/2)) ? BMV_TYPE_BACKWARD : BMV_TYPE_FORWARD;

                    break;

                case 1:

                    bmvtype = (v->bfraction >= (B_FRACTION_DEN/2)) ? BMV_TYPE_FORWARD : BMV_TYPE_BACKWARD;

                    break;

                case 2:

                    bmvtype  = BMV_TYPE_INTERPOLATED;

                }

            }



            if (twomv && bmvtype != BMV_TYPE_INTERPOLATED)

                mvsw = get_bits1(gb);

        }



        if (!skipped) { // inter MB

            mb_has_coeffs = ff_vc1_mbmode_intfrp[0][idx_mbmode][3];

            if (mb_has_coeffs)

                cbp = 1 + get_vlc2(&v->s.gb, v->cbpcy_vlc->table, VC1_CBPCY_P_VLC_BITS, 2);

            if (!direct) {

                if (bmvtype == BMV_TYPE_INTERPOLATED && twomv) {

                    v->fourmvbp = get_vlc2(gb, v->fourmvbp_vlc->table, VC1_4MV_BLOCK_PATTERN_VLC_BITS, 1);

                } else if (bmvtype == BMV_TYPE_INTERPOLATED || twomv) {

                    v->twomvbp = get_vlc2(gb, v->twomvbp_vlc->table, VC1_2MV_BLOCK_PATTERN_VLC_BITS, 1);

                }

            }



            for (i = 0; i < 6; i++)

                v->mb_type[0][s->block_index[i]] = 0;

            fieldtx = v->fieldtx_plane[mb_pos] = ff_vc1_mbmode_intfrp[0][idx_mbmode][1];

            /* for all motion vector read MVDATA and motion compensate each block */

            dst_idx = 0;

            if (direct) {

                if (twomv) {

                    for (i = 0; i < 4; i++) {

                        vc1_mc_4mv_luma(v, i, 0, 0);

                        vc1_mc_4mv_luma(v, i, 1, 1);

                    }

                    vc1_mc_4mv_chroma4(v, 0, 0, 0);

                    vc1_mc_4mv_chroma4(v, 1, 1, 1);

                } else {

                    vc1_mc_1mv(v, 0);

                    vc1_interp_mc(v);

                }

            } else if (twomv && bmvtype == BMV_TYPE_INTERPOLATED) {

                mvbp = v->fourmvbp;

                for (i = 0; i < 4; i++) {

                    dir = i==1 || i==3;

                    dmv_x = dmv_y = 0;

                    val = ((mvbp >> (3 - i)) & 1);

                    if (val)

                        get_mvdata_interlaced(v, &dmv_x, &dmv_y, 0);

                    j = i > 1 ? 2 : 0;

                    vc1_pred_mv_intfr(v, j, dmv_x, dmv_y, 2, v->range_x, v->range_y, v->mb_type[0], dir);

                    vc1_mc_4mv_luma(v, j, dir, dir);

                    vc1_mc_4mv_luma(v, j+1, dir, dir);

                }



                vc1_mc_4mv_chroma4(v, 0, 0, 0);

                vc1_mc_4mv_chroma4(v, 1, 1, 1);

            } else if (bmvtype == BMV_TYPE_INTERPOLATED) {

                mvbp = v->twomvbp;

                dmv_x = dmv_y = 0;

                if (mvbp & 2)

                    get_mvdata_interlaced(v, &dmv_x, &dmv_y, 0);



                vc1_pred_mv_intfr(v, 0, dmv_x, dmv_y, 1, v->range_x, v->range_y, v->mb_type[0], 0);

                vc1_mc_1mv(v, 0);



                dmv_x = dmv_y = 0;

                if (mvbp & 1)

                    get_mvdata_interlaced(v, &dmv_x, &dmv_y, 0);



                vc1_pred_mv_intfr(v, 0, dmv_x, dmv_y, 1, v->range_x, v->range_y, v->mb_type[0], 1);

                vc1_interp_mc(v);

            } else if (twomv) {

                dir = bmvtype == BMV_TYPE_BACKWARD;

                dir2 = dir;

                if (mvsw)

                    dir2 = !dir;

                mvbp = v->twomvbp;

                dmv_x = dmv_y = 0;

                if (mvbp & 2)

                    get_mvdata_interlaced(v, &dmv_x, &dmv_y, 0);

                vc1_pred_mv_intfr(v, 0, dmv_x, dmv_y, 2, v->range_x, v->range_y, v->mb_type[0], dir);



                dmv_x = dmv_y = 0;

                if (mvbp & 1)

                    get_mvdata_interlaced(v, &dmv_x, &dmv_y, 0);

                vc1_pred_mv_intfr(v, 2, dmv_x, dmv_y, 2, v->range_x, v->range_y, v->mb_type[0], dir2);



                if (mvsw) {

                    for (i = 0; i < 2; i++) {

                        s->mv[dir][i+2][0] = s->mv[dir][i][0] = s->current_picture.motion_val[dir][s->block_index[i+2]][0] = s->current_picture.motion_val[dir][s->block_index[i]][0];

                        s->mv[dir][i+2][1] = s->mv[dir][i][1] = s->current_picture.motion_val[dir][s->block_index[i+2]][1] = s->current_picture.motion_val[dir][s->block_index[i]][1];

                        s->mv[dir2][i+2][0] = s->mv[dir2][i][0] = s->current_picture.motion_val[dir2][s->block_index[i]][0] = s->current_picture.motion_val[dir2][s->block_index[i+2]][0];

                        s->mv[dir2][i+2][1] = s->mv[dir2][i][1] = s->current_picture.motion_val[dir2][s->block_index[i]][1] = s->current_picture.motion_val[dir2][s->block_index[i+2]][1];

                    }

                } else {

                    vc1_pred_mv_intfr(v, 0, 0, 0, 2, v->range_x, v->range_y, v->mb_type[0], !dir);

                    vc1_pred_mv_intfr(v, 2, 0, 0, 2, v->range_x, v->range_y, v->mb_type[0], !dir);

                }



                vc1_mc_4mv_luma(v, 0, dir, 0);

                vc1_mc_4mv_luma(v, 1, dir, 0);

                vc1_mc_4mv_luma(v, 2, dir2, 0);

                vc1_mc_4mv_luma(v, 3, dir2, 0);

                vc1_mc_4mv_chroma4(v, dir, dir2, 0);

            } else {

                dir = bmvtype == BMV_TYPE_BACKWARD;



                mvbp = ff_vc1_mbmode_intfrp[0][idx_mbmode][2];

                dmv_x = dmv_y = 0;

                if (mvbp)

                    get_mvdata_interlaced(v, &dmv_x, &dmv_y, 0);



                vc1_pred_mv_intfr(v, 0, dmv_x, dmv_y, 1, v->range_x, v->range_y, v->mb_type[0], dir);

                v->blk_mv_type[s->block_index[0]] = 1;

                v->blk_mv_type[s->block_index[1]] = 1;

                v->blk_mv_type[s->block_index[2]] = 1;

                v->blk_mv_type[s->block_index[3]] = 1;

                vc1_pred_mv_intfr(v, 0, 0, 0, 2, v->range_x, v->range_y, 0, !dir);

                for (i = 0; i < 2; i++) {

                    s->mv[!dir][i+2][0] = s->mv[!dir][i][0] = s->current_picture.motion_val[!dir][s->block_index[i+2]][0] = s->current_picture.motion_val[!dir][s->block_index[i]][0];

                    s->mv[!dir][i+2][1] = s->mv[!dir][i][1] = s->current_picture.motion_val[!dir][s->block_index[i+2]][1] = s->current_picture.motion_val[!dir][s->block_index[i]][1];

                }

                vc1_mc_1mv(v, dir);

            }



            if (cbp)

                GET_MQUANT();  // p. 227

            s->current_picture.qscale_table[mb_pos] = mquant;

            if (!v->ttmbf && cbp)

                ttmb = get_vlc2(gb, ff_vc1_ttmb_vlc[v->tt_index].table, VC1_TTMB_VLC_BITS, 2);

            for (i = 0; i < 6; i++) {

                s->dc_val[0][s->block_index[i]] = 0;

                dst_idx += i >> 2;

                val = ((cbp >> (5 - i)) & 1);

                if (!fieldtx)

                    off = (i & 4) ? 0 : ((i & 1) * 8 + (i & 2) * 4 * s->linesize);

                else

                    off = (i & 4) ? 0 : ((i & 1) * 8 + ((i > 1) * s->linesize));

                if (val) {

                    pat = vc1_decode_p_block(v, s->block[i], i, mquant, ttmb,

                                             first_block, s->dest[dst_idx] + off,

                                             (i & 4) ? s->uvlinesize : (s->linesize << fieldtx),

                                             (i & 4) && (s->flags & CODEC_FLAG_GRAY), &block_tt);

                    block_cbp |= pat << (i << 2);

                    if (!v->ttmbf && ttmb < 8)

                        ttmb = -1;

                    first_block = 0;

                }

            }



        } else { // skipped

            dir = 0;

            for (i = 0; i < 6; i++) {

                v->mb_type[0][s->block_index[i]] = 0;

                s->dc_val[0][s->block_index[i]] = 0;

            }

            s->current_picture.mb_type[mb_pos]      = MB_TYPE_SKIP;

            s->current_picture.qscale_table[mb_pos] = 0;

            v->blk_mv_type[s->block_index[0]] = 0;

            v->blk_mv_type[s->block_index[1]] = 0;

            v->blk_mv_type[s->block_index[2]] = 0;

            v->blk_mv_type[s->block_index[3]] = 0;



            if (!direct) {

                if (bmvtype == BMV_TYPE_INTERPOLATED) {

                    vc1_pred_mv_intfr(v, 0, 0, 0, 1, v->range_x, v->range_y, v->mb_type[0], 0);

                    vc1_pred_mv_intfr(v, 0, 0, 0, 1, v->range_x, v->range_y, v->mb_type[0], 1);

                } else {

                    dir = bmvtype == BMV_TYPE_BACKWARD;

                    vc1_pred_mv_intfr(v, 0, 0, 0, 1, v->range_x, v->range_y, v->mb_type[0], dir);

                    if (mvsw) {

                        int dir2 = dir;

                        if (mvsw)

                            dir2 = !dir;

                        for (i = 0; i < 2; i++) {

                            s->mv[dir][i+2][0] = s->mv[dir][i][0] = s->current_picture.motion_val[dir][s->block_index[i+2]][0] = s->current_picture.motion_val[dir][s->block_index[i]][0];

                            s->mv[dir][i+2][1] = s->mv[dir][i][1] = s->current_picture.motion_val[dir][s->block_index[i+2]][1] = s->current_picture.motion_val[dir][s->block_index[i]][1];

                            s->mv[dir2][i+2][0] = s->mv[dir2][i][0] = s->current_picture.motion_val[dir2][s->block_index[i]][0] = s->current_picture.motion_val[dir2][s->block_index[i+2]][0];

                            s->mv[dir2][i+2][1] = s->mv[dir2][i][1] = s->current_picture.motion_val[dir2][s->block_index[i]][1] = s->current_picture.motion_val[dir2][s->block_index[i+2]][1];

                        }

                    } else {

                        v->blk_mv_type[s->block_index[0]] = 1;

                        v->blk_mv_type[s->block_index[1]] = 1;

                        v->blk_mv_type[s->block_index[2]] = 1;

                        v->blk_mv_type[s->block_index[3]] = 1;

                        vc1_pred_mv_intfr(v, 0, 0, 0, 2, v->range_x, v->range_y, 0, !dir);

                        for (i = 0; i < 2; i++) {

                            s->mv[!dir][i+2][0] = s->mv[!dir][i][0] = s->current_picture.motion_val[!dir][s->block_index[i+2]][0] = s->current_picture.motion_val[!dir][s->block_index[i]][0];

                            s->mv[!dir][i+2][1] = s->mv[!dir][i][1] = s->current_picture.motion_val[!dir][s->block_index[i+2]][1] = s->current_picture.motion_val[!dir][s->block_index[i]][1];

                        }

                    }

                }

            }



            vc1_mc_1mv(v, dir);

            if (direct || bmvtype == BMV_TYPE_INTERPOLATED) {

                vc1_interp_mc(v);

            }

        }

    }

    if (s->mb_x == s->mb_width - 1)

        memmove(v->is_intra_base, v->is_intra, sizeof(v->is_intra_base[0]) * s->mb_stride);

    v->cbp[s->mb_x]      = block_cbp;

    v->ttblk[s->mb_x]    = block_tt;

    return 0;

}

static int execute_code(AVCodecContext * avctx, int c)

{

    AnsiContext *s = avctx->priv_data;

    int ret, i, width, height;

    switch(c) {

    case 'A': //Cursor Up

        s->y = FFMAX(s->y - (s->nb_args > 0 ? s->args[0]*s->font_height : s->font_height), 0);

        break;

    case 'B': //Cursor Down

        s->y = FFMIN(s->y + (s->nb_args > 0 ? s->args[0]*s->font_height : s->font_height), avctx->height - s->font_height);

        break;

    case 'C': //Cursor Right

        s->x = FFMIN(s->x + (s->nb_args > 0 ? s->args[0]*FONT_WIDTH : FONT_WIDTH), avctx->width  - FONT_WIDTH);

        break;

    case 'D': //Cursor Left

        s->x = FFMAX(s->x - (s->nb_args > 0 ? s->args[0]*FONT_WIDTH : FONT_WIDTH), 0);

        break;

    case 'H': //Cursor Position

    case 'f': //Horizontal and Vertical Position

        s->y = s->nb_args > 0 ? av_clip((s->args[0] - 1)*s->font_height, 0, avctx->height - s->font_height) : 0;

        s->x = s->nb_args > 1 ? av_clip((s->args[1] - 1)*FONT_WIDTH,     0, avctx->width  - FONT_WIDTH) : 0;

        break;

    case 'h': //set creen mode

    case 'l': //reset screen mode

        if (s->nb_args < 2)

            s->args[0] = DEFAULT_SCREEN_MODE;

        switch(s->args[0]) {

        case 0: case 1: case 4: case 5: case 13: case 19: //320x200 (25 rows)

            s->font = ff_cga_font;

            s->font_height = 8;

            width  = 40<<3;

            height = 25<<3;

            break;

        case 2: case 3: //640x400 (25 rows)

            s->font = ff_vga16_font;

            s->font_height = 16;

            width  = 80<<3;

            height = 25<<4;

            break;

        case 6: case 14: //640x200 (25 rows)

            s->font = ff_cga_font;

            s->font_height = 8;

            width  = 80<<3;

            height = 25<<3;

            break;

        case 7: //set line wrapping

            break;

        case 15: case 16: //640x350 (43 rows)

            s->font = ff_cga_font;

            s->font_height = 8;

            width  = 80<<3;

            height = 43<<3;

            break;

        case 17: case 18: //640x480 (60 rows)

            s->font = ff_cga_font;

            s->font_height = 8;

            width  = 80<<3;

            height = 60<<4;

            break;

        default:

            avpriv_request_sample(avctx, "Unsupported screen mode");

        }

        if (width != avctx->width || height != avctx->height) {

            av_frame_unref(s->frame);

            ret = ff_set_dimensions(avctx, width, height);

            if (ret < 0)

                return ret;

            ret = ff_get_buffer(avctx, s->frame, AV_GET_BUFFER_FLAG_REF);

            if (ret < 0) {

                av_log(avctx, AV_LOG_ERROR, "get_buffer() failed\n");

                return ret;

            }

            s->frame->pict_type           = AV_PICTURE_TYPE_I;

            s->frame->palette_has_changed = 1;

            memcpy(s->frame->data[1], ff_cga_palette, 16 * 4);

            erase_screen(avctx);

        } else if (c == 'l') {

            erase_screen(avctx);

        }

        break;

    case 'J': //Erase in Page

        switch (s->args[0]) {

        case 0:

            erase_line(avctx, s->x, avctx->width - s->x);

            if (s->y < avctx->height - s->font_height)

                memset(s->frame->data[0] + (s->y + s->font_height)*s->frame->linesize[0],

                    DEFAULT_BG_COLOR, (avctx->height - s->y - s->font_height)*s->frame->linesize[0]);

            break;

        case 1:

            erase_line(avctx, 0, s->x);

            if (s->y > 0)

                memset(s->frame->data[0], DEFAULT_BG_COLOR, s->y * s->frame->linesize[0]);

            break;

        case 2:

            erase_screen(avctx);

        }

        break;

    case 'K': //Erase in Line

        switch(s->args[0]) {

        case 0:

            erase_line(avctx, s->x, avctx->width - s->x);

            break;

        case 1:

            erase_line(avctx, 0, s->x);

            break;

        case 2:

            erase_line(avctx, 0, avctx->width);

        }

        break;

    case 'm': //Select Graphics Rendition

        if (s->nb_args == 0) {

            s->nb_args = 1;

            s->args[0] = 0;

        }

        for (i = 0; i < FFMIN(s->nb_args, MAX_NB_ARGS); i++) {

            int m = s->args[i];

            if (m == 0) {

                s->attributes = 0;

                s->fg = DEFAULT_FG_COLOR;

                s->bg = DEFAULT_BG_COLOR;

            } else if (m == 1 || m == 2 || m == 4 || m == 5 || m == 7 || m == 8) {

                s->attributes |= 1 << (m - 1);

            } else if (m >= 30 && m <= 38) {

                s->fg = ansi_to_cga[m - 30];

            } else if (m == 39) {

                s->fg = ansi_to_cga[DEFAULT_FG_COLOR];

            } else if (m >= 40 && m <= 47) {

                s->bg = ansi_to_cga[m - 40];

            } else if (m == 49) {

                s->fg = ansi_to_cga[DEFAULT_BG_COLOR];

            } else {

                avpriv_request_sample(avctx, "Unsupported rendition parameter");

            }

        }

        break;

    case 'n': //Device Status Report

    case 'R': //report current line and column

        /* ignore */

        break;

    case 's': //Save Cursor Position

        s->sx = s->x;

        s->sy = s->y;

        break;

    case 'u': //Restore Cursor Position

        s->x = av_clip(s->sx, 0, avctx->width  - FONT_WIDTH);

        s->y = av_clip(s->sy, 0, avctx->height - s->font_height);

        break;

    default:

        avpriv_request_sample(avctx, "Unknown escape code");

        break;

    }

    return 0;

}

int avpicture_layout(const AVPicture* src, int pix_fmt, int width, int height,

                     unsigned char *dest, int dest_size)

{

    PixFmtInfo* pf = &pix_fmt_info[pix_fmt];

    int i, j, w, h, data_planes;

    const unsigned char* s; 

    int size = avpicture_get_size(pix_fmt, width, height);



    if (size > dest_size)

        return -1;



    if (pf->pixel_type == FF_PIXEL_PACKED || pf->pixel_type == FF_PIXEL_PALETTE) {

        if (pix_fmt == PIX_FMT_YUV422 || 

            pix_fmt == PIX_FMT_UYVY422 || 

            pix_fmt == PIX_FMT_RGB565 ||

            pix_fmt == PIX_FMT_RGB555)

            w = width * 2;

	else if (pix_fmt == PIX_FMT_UYVY411)

	  w = width + width/2;

	else if (pix_fmt == PIX_FMT_PAL8)

	  w = width;

	else

	  w = width * (pf->depth * pf->nb_channels / 8);



	data_planes = 1;

	h = height;

    } else {

        data_planes = pf->nb_channels;

	w = (width*pf->depth + 7)/8;

	h = height;

    }



    for (i=0; i<data_planes; i++) {

         if (i == 1) {

	     w = width >> pf->x_chroma_shift;

	     h = height >> pf->y_chroma_shift;

	 }

         s = src->data[i];

	 for(j=0; j<h; j++) {

	     memcpy(dest, s, w);

	     dest += w;

	     s += src->linesize[i];

	 }

    }



    if (pf->pixel_type == FF_PIXEL_PALETTE)

	memcpy((unsigned char *)(((size_t)dest + 3) & ~3), src->data[1], 256 * 4);



    return size;

}

static int read_access_unit(AVCodecContext *avctx, void* data,
                            int *got_frame_ptr, AVPacket *avpkt)
{
    const uint8_t *buf = avpkt->data;
    int buf_size = avpkt->size;
    MLPDecodeContext *m = avctx->priv_data;
    GetBitContext gb;
    unsigned int length, substr;
    unsigned int substream_start;
    unsigned int header_size = 4;
    unsigned int substr_header_size = 0;
    uint8_t substream_parity_present[MAX_SUBSTREAMS];
    uint16_t substream_data_len[MAX_SUBSTREAMS];
    uint8_t parity_bits;
    int ret;
    if (buf_size < 4)
        return AVERROR_INVALIDDATA;
    length = (AV_RB16(buf) & 0xfff) * 2;
    if (length < 4 || length > buf_size)
        return AVERROR_INVALIDDATA;
    init_get_bits(&gb, (buf + 4), (length - 4) * 8);
    m->is_major_sync_unit = 0;
    if (show_bits_long(&gb, 31) == (0xf8726fba >> 1)) {
        if (read_major_sync(m, &gb) < 0)
        m->is_major_sync_unit = 1;
        header_size += m->major_sync_header_size;
    if (!m->params_valid) {
        av_log(m->avctx, AV_LOG_WARNING,
               "Stream parameters not seen; skipping frame.\n");
        *got_frame_ptr = 0;
        return length;
    substream_start = 0;
    for (substr = 0; substr < m->num_substreams; substr++) {
        int extraword_present, checkdata_present, end, nonrestart_substr;
        extraword_present = get_bits1(&gb);
        nonrestart_substr = get_bits1(&gb);
        checkdata_present = get_bits1(&gb);
        skip_bits1(&gb);
        end = get_bits(&gb, 12) * 2;
        substr_header_size += 2;
        if (extraword_present) {
            if (m->avctx->codec_id == AV_CODEC_ID_MLP) {
                av_log(m->avctx, AV_LOG_ERROR, "There must be no extraword for MLP.\n");
            skip_bits(&gb, 16);
            substr_header_size += 2;
        if (!(nonrestart_substr ^ m->is_major_sync_unit)) {
            av_log(m->avctx, AV_LOG_ERROR, "Invalid nonrestart_substr.\n");
        if (end + header_size + substr_header_size > length) {
            av_log(m->avctx, AV_LOG_ERROR,
                   "Indicated length of substream %d data goes off end of "
                   "packet.\n", substr);
            end = length - header_size - substr_header_size;
        if (end < substream_start) {
            av_log(avctx, AV_LOG_ERROR,
                   "Indicated end offset of substream %d data "
                   "is smaller than calculated start offset.\n",
                   substr);
        if (substr > m->max_decoded_substream)
            continue;
        substream_parity_present[substr] = checkdata_present;
        substream_data_len[substr] = end - substream_start;
        substream_start = end;
    parity_bits  = ff_mlp_calculate_parity(buf, 4);
    parity_bits ^= ff_mlp_calculate_parity(buf + header_size, substr_header_size);
    if ((((parity_bits >> 4) ^ parity_bits) & 0xF) != 0xF) {
        av_log(avctx, AV_LOG_ERROR, "Parity check failed.\n");
    buf += header_size + substr_header_size;
    for (substr = 0; substr <= m->max_decoded_substream; substr++) {
        SubStream *s = &m->substream[substr];
        init_get_bits(&gb, buf, substream_data_len[substr] * 8);
        m->matrix_changed = 0;
        memset(m->filter_changed, 0, sizeof(m->filter_changed));
        s->blockpos = 0;
        do {
            if (get_bits1(&gb)) {
                if (get_bits1(&gb)) {
                    /* A restart header should be present. */
                    if (read_restart_header(m, &gb, buf, substr) < 0)
                        goto next_substr;
                    s->restart_seen = 1;
                if (!s->restart_seen)
                    goto next_substr;
                if (read_decoding_params(m, &gb, substr) < 0)
                    goto next_substr;
            if (!s->restart_seen)
                goto next_substr;
            if ((ret = read_block_data(m, &gb, substr)) < 0)
                return ret;
            if (get_bits_count(&gb) >= substream_data_len[substr] * 8)
                goto substream_length_mismatch;
        } while (!get_bits1(&gb));
        skip_bits(&gb, (-get_bits_count(&gb)) & 15);
        if (substream_data_len[substr] * 8 - get_bits_count(&gb) >= 32) {
            int shorten_by;
            if (get_bits(&gb, 16) != 0xD234)
                return AVERROR_INVALIDDATA;
            shorten_by = get_bits(&gb, 16);
            if      (m->avctx->codec_id == AV_CODEC_ID_TRUEHD && shorten_by  & 0x2000)
                s->blockpos -= FFMIN(shorten_by & 0x1FFF, s->blockpos);
            else if (m->avctx->codec_id == AV_CODEC_ID_MLP    && shorten_by != 0xD234)
                return AVERROR_INVALIDDATA;
            if (substr == m->max_decoded_substream)
                av_log(m->avctx, AV_LOG_INFO, "End of stream indicated.\n");
        if (substream_parity_present[substr]) {
            uint8_t parity, checksum;
            if (substream_data_len[substr] * 8 - get_bits_count(&gb) != 16)
                goto substream_length_mismatch;
            parity   = ff_mlp_calculate_parity(buf, substream_data_len[substr] - 2);
            checksum = ff_mlp_checksum8       (buf, substream_data_len[substr] - 2);
            if ((get_bits(&gb, 8) ^ parity) != 0xa9    )
                av_log(m->avctx, AV_LOG_ERROR, "Substream %d parity check failed.\n", substr);
            if ( get_bits(&gb, 8)           != checksum)
                av_log(m->avctx, AV_LOG_ERROR, "Substream %d checksum failed.\n"    , substr);
        if (substream_data_len[substr] * 8 != get_bits_count(&gb))
            goto substream_length_mismatch;
next_substr:
        if (!s->restart_seen)
            av_log(m->avctx, AV_LOG_ERROR,
                   "No restart header present in substream %d.\n", substr);
        buf += substream_data_len[substr];
    if ((ret = output_data(m, m->max_decoded_substream, data, got_frame_ptr)) < 0)
        return ret;
    return length;
substream_length_mismatch:
    av_log(m->avctx, AV_LOG_ERROR, "substream %d length mismatch\n", substr);
    return AVERROR_INVALIDDATA;
error:
    m->params_valid = 0;
    return AVERROR_INVALIDDATA;

enum AVCodecID av_guess_codec(AVOutputFormat *fmt, const char *short_name,

                              const char *filename, const char *mime_type,

                              enum AVMediaType type)

{

    if (av_match_name("segment", fmt->name) || av_match_name("ssegment", fmt->name)) {

        fmt = av_guess_format(NULL, filename, NULL);

    }



    if (type == AVMEDIA_TYPE_VIDEO) {

        enum AVCodecID codec_id = AV_CODEC_ID_NONE;



#if CONFIG_IMAGE2_MUXER

        if (!strcmp(fmt->name, "image2") || !strcmp(fmt->name, "image2pipe")) {

            codec_id = ff_guess_image2_codec(filename);

        }

#endif

        if (codec_id == AV_CODEC_ID_NONE)

            codec_id = fmt->video_codec;

        return codec_id;

    } else if (type == AVMEDIA_TYPE_AUDIO)

        return fmt->audio_codec;

    else if (type == AVMEDIA_TYPE_SUBTITLE)

        return fmt->subtitle_codec;

    else

        return AV_CODEC_ID_NONE;

}

static int wav_parse_fmt_tag(AVFormatContext *s, int64_t size, AVStream **st)

{

    AVIOContext *pb = s->pb;

    int ret;



    /* parse fmt header */

    *st = av_new_stream(s, 0);

    if (!*st)

        return AVERROR(ENOMEM);



    ff_get_wav_header(pb, (*st)->codec, size);

    if (ret < 0)

        return ret;

    (*st)->need_parsing = AVSTREAM_PARSE_FULL;



    av_set_pts_info(*st, 64, 1, (*st)->codec->sample_rate);



    return 0;

}

static int chunk_mux_init(AVFormatContext *s)

{

    WebMChunkContext *wc = s->priv_data;

    AVFormatContext *oc;

    int ret;



    ret = avformat_alloc_output_context2(&wc->avf, wc->oformat, NULL, NULL);

    if (ret < 0)

        return ret;

    oc = wc->avf;



    oc->interrupt_callback = s->interrupt_callback;

    oc->max_delay          = s->max_delay;

    av_dict_copy(&oc->metadata, s->metadata, 0);



    oc->priv_data = av_mallocz(oc->oformat->priv_data_size);

    if (!oc->priv_data) {

        avio_close(oc->pb);

        return AVERROR(ENOMEM);

    }

    *(const AVClass**)oc->priv_data = oc->oformat->priv_class;

    av_opt_set_defaults(oc->priv_data);

    av_opt_set_int(oc->priv_data, "dash", 1, 0);

    av_opt_set_int(oc->priv_data, "cluster_time_limit", wc->chunk_duration, 0);

    av_opt_set_int(oc->priv_data, "live", 1, 0);



    oc->streams = s->streams;

    oc->nb_streams = s->nb_streams;



    return 0;

}

static int interp(RA144Context *ractx, int16_t *out, int block_num,

                  int copyold, int energy)

{

    int work[10];

    int a = block_num + 1;

    int b = NBLOCKS - a;

    int x;



    // Interpolate block coefficients from the this frame forth block and

    // last frame forth block

    for (x=0; x<30; x++)

        out[x] = (a * ractx->lpc_coef[0][x] + b * ractx->lpc_coef[1][x])>> 2;



    if (eval_refl(work, out, ractx)) {

        // The interpolated coefficients are unstable, copy either new or old

        // coefficients

        int_to_int16(out, ractx->lpc_coef[copyold]);

        return rescale_rms(ractx->lpc_refl_rms[copyold], energy);

    } else {

        return rescale_rms(rms(work), energy);

    }

}

int ff_framesync_request_frame(FFFrameSync *fs, AVFilterLink *outlink)

{

    AVFilterContext *ctx = outlink->src;

    int input, ret;



    if ((ret = ff_framesync_process_frame(fs, 0)) < 0)

        return ret;

    if (ret > 0)

        return 0;

    if (fs->eof)

        return AVERROR_EOF;

    input = fs->in_request;

    ret = ff_request_frame(ctx->inputs[input]);

    if (ret == AVERROR_EOF) {

        if ((ret = ff_framesync_add_frame(fs, input, NULL)) < 0)

            return ret;

        if ((ret = ff_framesync_process_frame(fs, 0)) < 0)

            return ret;

        ret = 0;

    }

    return ret;

}

static Jpeg2000TgtNode *ff_jpeg2000_tag_tree_init(int w, int h)

{

    int pw = w, ph = h;

    Jpeg2000TgtNode *res, *t, *t2;

    int32_t tt_size;



    tt_size = tag_tree_size(w, h);

    if (tt_size == -1)

        return NULL;



    t = res = av_mallocz_array(tt_size, sizeof(*t));

    if (!res)

        return NULL;



    while (w > 1 || h > 1) {

        int i, j;

        pw = w;

        ph = h;



        w  = (w + 1) >> 1;

        h  = (h + 1) >> 1;

        t2 = t + pw * ph;



        for (i = 0; i < ph; i++)

            for (j = 0; j < pw; j++)

                t[i * pw + j].parent = &t2[(i >> 1) * w + (j >> 1)];



        t = t2;

    }

    t[0].parent = NULL;

    return res;

}

static int planarRgb16ToRgb16Wrapper(SwsContext *c, const uint8_t *src[],

                                     int srcStride[], int srcSliceY, int srcSliceH,

                                     uint8_t *dst[], int dstStride[])

{

    const uint16_t *src102[] = { (uint16_t *)src[1], (uint16_t *)src[0], (uint16_t *)src[2] };

    const uint16_t *src201[] = { (uint16_t *)src[2], (uint16_t *)src[0], (uint16_t *)src[1] };

    int stride102[] = { srcStride[1], srcStride[0], srcStride[2] };

    int stride201[] = { srcStride[2], srcStride[0], srcStride[1] };

    const AVPixFmtDescriptor *src_format = av_pix_fmt_desc_get(c->srcFormat);

    const AVPixFmtDescriptor *dst_format = av_pix_fmt_desc_get(c->dstFormat);

    int bits_per_sample = src_format->comp[0].depth_minus1 + 1;

    int swap = 0;

    if ( HAVE_BIGENDIAN && !(src_format->flags & AV_PIX_FMT_FLAG_BE) ||

        !HAVE_BIGENDIAN &&   src_format->flags & AV_PIX_FMT_FLAG_BE)

        swap++;

    if ( HAVE_BIGENDIAN && !(dst_format->flags & AV_PIX_FMT_FLAG_BE) ||

        !HAVE_BIGENDIAN &&   dst_format->flags & AV_PIX_FMT_FLAG_BE)

        swap += 2;



    if ((src_format->flags & (AV_PIX_FMT_FLAG_PLANAR | AV_PIX_FMT_FLAG_RGB)) !=

        (AV_PIX_FMT_FLAG_PLANAR | AV_PIX_FMT_FLAG_RGB)) {

        av_log(c, AV_LOG_ERROR, "unsupported planar RGB conversion %s -> %s\n",

               src_format->name, dst_format->name);

        return srcSliceH;

    }

    switch (c->dstFormat) {

    case AV_PIX_FMT_BGR48LE:

    case AV_PIX_FMT_BGR48BE:

        gbr16ptopacked16(src102, stride102,

                         dst[0] + srcSliceY * dstStride[0], dstStride[0],

                         srcSliceH, 0, swap, bits_per_sample, c->srcW);

        break;

    case AV_PIX_FMT_RGB48LE:

    case AV_PIX_FMT_RGB48BE:

        gbr16ptopacked16(src201, stride201,

                         dst[0] + srcSliceY * dstStride[0], dstStride[0],

                         srcSliceH, 0, swap, bits_per_sample, c->srcW);

        break;

    case AV_PIX_FMT_RGBA64LE:

    case AV_PIX_FMT_RGBA64BE:

         gbr16ptopacked16(src201, stride201,

                          dst[0] + srcSliceY * dstStride[0], dstStride[0],

                          srcSliceH, 1, swap, bits_per_sample, c->srcW);

        break;

    case AV_PIX_FMT_BGRA64LE:

    case AV_PIX_FMT_BGRA64BE:

        gbr16ptopacked16(src102, stride102,

                         dst[0] + srcSliceY * dstStride[0], dstStride[0],

                         srcSliceH, 1, swap, bits_per_sample, c->srcW);

        break;

    default:

        av_log(c, AV_LOG_ERROR,

               "unsupported planar RGB conversion %s -> %s\n",

               src_format->name, dst_format->name);

    }



    return srcSliceH;

}

void put_pixels16_altivec(uint8_t *block, const uint8_t *pixels, int line_size, int h)

{

POWERPC_TBL_DECLARE(altivec_put_pixels16_num, 1);

#ifdef ALTIVEC_USE_REFERENCE_C_CODE

    int i;



POWERPC_TBL_START_COUNT(altivec_put_pixels16_num, 1);



    for(i=0; i<h; i++) {

      *((uint32_t*)(block )) = (((const struct unaligned_32 *) (pixels))->l);

      *((uint32_t*)(block+4)) = (((const struct unaligned_32 *) (pixels+4))->l);

      *((uint32_t*)(block+8)) = (((const struct unaligned_32 *) (pixels+8))->l);

      *((uint32_t*)(block+12)) = (((const struct unaligned_32 *) (pixels+12))->l);

      pixels+=line_size;

      block +=line_size;

    }



POWERPC_TBL_STOP_COUNT(altivec_put_pixels16_num, 1);



#else /* ALTIVEC_USE_REFERENCE_C_CODE */

    register vector unsigned char pixelsv1, pixelsv2;

    register vector unsigned char perm = vec_lvsl(0, pixels);

    int i;



POWERPC_TBL_START_COUNT(altivec_put_pixels16_num, 1);



    for(i=0; i<h; i++) {

      pixelsv1 = vec_ld(0, (unsigned char*)pixels);

      pixelsv2 = vec_ld(16, (unsigned char*)pixels);

      vec_st(vec_perm(pixelsv1, pixelsv2, perm),

             0, (unsigned char*)block);

      pixels+=line_size;

      block +=line_size;

    }



POWERPC_TBL_STOP_COUNT(altivec_put_pixels16_num, 1);



#endif /* ALTIVEC_USE_REFERENCE_C_CODE */

}

static int nvdec_vp9_start_frame(AVCodecContext *avctx, const uint8_t *buffer, uint32_t size)

{

    VP9SharedContext *h = avctx->priv_data;

    const AVPixFmtDescriptor *pixdesc = av_pix_fmt_desc_get(avctx->sw_pix_fmt);



    NVDECContext      *ctx = avctx->internal->hwaccel_priv_data;

    CUVIDPICPARAMS     *pp = &ctx->pic_params;

    CUVIDVP9PICPARAMS *ppc = &pp->CodecSpecific.vp9;

    FrameDecodeData *fdd;

    NVDECFrame *cf;

    AVFrame *cur_frame = h->frames[CUR_FRAME].tf.f;



    int ret, i;



    ret = ff_nvdec_start_frame(avctx, cur_frame);

    if (ret < 0)

        return ret;



    fdd = (FrameDecodeData*)cur_frame->private_ref->data;

    cf  = (NVDECFrame*)fdd->hwaccel_priv;



    *pp = (CUVIDPICPARAMS) {

        .PicWidthInMbs     = (cur_frame->width  + 15) / 16,

        .FrameHeightInMbs  = (cur_frame->height + 15) / 16,

        .CurrPicIdx        = cf->idx,



        .CodecSpecific.vp9 = {

            .width                    = cur_frame->width,

            .height                   = cur_frame->height,



            .LastRefIdx               = get_ref_idx(h->refs[h->h.refidx[0]].f),

            .GoldenRefIdx             = get_ref_idx(h->refs[h->h.refidx[1]].f),

            .AltRefIdx                = get_ref_idx(h->refs[h->h.refidx[2]].f),



            .profile                  = h->h.profile,

            .frameContextIdx          = h->h.framectxid,

            .frameType                = !h->h.keyframe,

            .showFrame                = !h->h.invisible,

            .errorResilient           = h->h.errorres,

            .frameParallelDecoding    = h->h.parallelmode,

            .subSamplingX             = pixdesc->log2_chroma_w,

            .subSamplingY             = pixdesc->log2_chroma_h,

            .intraOnly                = h->h.intraonly,

            .allow_high_precision_mv  = h->h.keyframe ? 0 : h->h.highprecisionmvs,

            .refreshEntropyProbs      = h->h.refreshctx,



            .bitDepthMinus8Luma       = pixdesc->comp[0].depth - 8,

            .bitDepthMinus8Chroma     = pixdesc->comp[1].depth - 8,



            .loopFilterLevel          = h->h.filter.level,

            .loopFilterSharpness      = h->h.filter.sharpness,

            .modeRefLfEnabled         = h->h.lf_delta.enabled,



            .log2_tile_columns        = h->h.tiling.log2_tile_cols,

            .log2_tile_rows           = h->h.tiling.log2_tile_rows,



            .segmentEnabled           = h->h.segmentation.enabled,

            .segmentMapUpdate         = h->h.segmentation.update_map,

            .segmentMapTemporalUpdate = h->h.segmentation.temporal,

            .segmentFeatureMode       = h->h.segmentation.absolute_vals,



            .qpYAc                    = h->h.yac_qi,

            .qpYDc                    = h->h.ydc_qdelta,

            .qpChDc                   = h->h.uvdc_qdelta,

            .qpChAc                   = h->h.uvac_qdelta,



            .resetFrameContext        = h->h.resetctx,

            .mcomp_filter_type        = h->h.filtermode ^ (h->h.filtermode <= 1),



            .frameTagSize             = h->h.uncompressed_header_size,

            .offsetToDctParts         = h->h.compressed_header_size,



            .refFrameSignBias[0]      = 0,

        }

    };



    for (i = 0; i < 2; i++)

        ppc->mbModeLfDelta[i] = h->h.lf_delta.mode[i];



    for (i = 0; i < 4; i++)

        ppc->mbRefLfDelta[i] = h->h.lf_delta.ref[i];



    for (i = 0; i < 7; i++)

        ppc->mb_segment_tree_probs[i] = h->h.segmentation.prob[i];



    for (i = 0; i < 3; i++) {

        ppc->activeRefIdx[i] = h->h.refidx[i];

        ppc->segment_pred_probs[i] = h->h.segmentation.pred_prob[i];

        ppc->refFrameSignBias[i + 1] = h->h.signbias[i];

    }



    for (i = 0; i < 8; i++) {

        ppc->segmentFeatureEnable[i][0] = h->h.segmentation.feat[i].q_enabled;

        ppc->segmentFeatureEnable[i][1] = h->h.segmentation.feat[i].lf_enabled;

        ppc->segmentFeatureEnable[i][2] = h->h.segmentation.feat[i].ref_enabled;

        ppc->segmentFeatureEnable[i][3] = h->h.segmentation.feat[i].skip_enabled;



        ppc->segmentFeatureData[i][0] = h->h.segmentation.feat[i].q_val;

        ppc->segmentFeatureData[i][1] = h->h.segmentation.feat[i].lf_val;

        ppc->segmentFeatureData[i][2] = h->h.segmentation.feat[i].ref_val;

        ppc->segmentFeatureData[i][3] = 0;

    }



    switch (avctx->colorspace) {

    default:

    case AVCOL_SPC_UNSPECIFIED:

        ppc->colorSpace = 0;

        break;

    case AVCOL_SPC_BT470BG:

        ppc->colorSpace = 1;

        break;

    case AVCOL_SPC_BT709:

        ppc->colorSpace = 2;

        break;

    case AVCOL_SPC_SMPTE170M:

        ppc->colorSpace = 3;

        break;

    case AVCOL_SPC_SMPTE240M:

        ppc->colorSpace = 4;

        break;

    case AVCOL_SPC_BT2020_NCL:

        ppc->colorSpace = 5;

        break;

    case AVCOL_SPC_RESERVED:

        ppc->colorSpace = 6;

        break;

    case AVCOL_SPC_RGB:

        ppc->colorSpace = 7;

        break;

    }



    return 0;

}

static int draw_text(AVFilterContext *ctx, AVFilterBufferRef *picref,

                     int width, int height)

{

    DrawTextContext *dtext = ctx->priv;

    uint32_t code = 0, prev_code = 0;

    int x = 0, y = 0, i = 0, ret;

    int max_text_line_w = 0, len;

    int box_w, box_h;

    char *text = dtext->text;

    uint8_t *p;

    int y_min = 32000, y_max = -32000;

    int x_min = 32000, x_max = -32000;

    FT_Vector delta;

    Glyph *glyph = NULL, *prev_glyph = NULL;

    Glyph dummy = { 0 };



    time_t now = time(0);

    struct tm ltime;

    uint8_t *buf = dtext->expanded_text;

    int buf_size = dtext->expanded_text_size;



    if(dtext->basetime != AV_NOPTS_VALUE)

        now= picref->pts*av_q2d(ctx->inputs[0]->time_base) + dtext->basetime/1000000;



    if (!buf) {

        buf_size = 2*strlen(dtext->text)+1;

        buf = av_malloc(buf_size);

    }



#if HAVE_LOCALTIME_R

    localtime_r(&now, &ltime);

#else

    if(strchr(dtext->text, '%'))

        ltime= *localtime(&now);

#endif



    do {

        *buf = 1;

        if (strftime(buf, buf_size, dtext->text, &ltime) != 0 || *buf == 0)

            break;

        buf_size *= 2;

    } while ((buf = av_realloc(buf, buf_size)));



    if (dtext->tc_opt_string) {

        char tcbuf[AV_TIMECODE_STR_SIZE];

        av_timecode_make_string(&dtext->tc, tcbuf, dtext->frame_id++);


        buf = av_asprintf("%s%s", dtext->text, tcbuf);

    }



    if (!buf)

        return AVERROR(ENOMEM);

    text = dtext->expanded_text = buf;

    dtext->expanded_text_size = buf_size;

    if ((len = strlen(text)) > dtext->nb_positions) {

        if (!(dtext->positions =

              av_realloc(dtext->positions, len*sizeof(*dtext->positions))))

            return AVERROR(ENOMEM);

        dtext->nb_positions = len;

    }



    x = 0;

    y = 0;



    /* load and cache glyphs */

    for (i = 0, p = text; *p; i++) {

        GET_UTF8(code, *p++, continue;);



        /* get glyph */

        dummy.code = code;

        glyph = av_tree_find(dtext->glyphs, &dummy, glyph_cmp, NULL);

        if (!glyph) {

            load_glyph(ctx, &glyph, code);

        }



        y_min = FFMIN(glyph->bbox.yMin, y_min);

        y_max = FFMAX(glyph->bbox.yMax, y_max);

        x_min = FFMIN(glyph->bbox.xMin, x_min);

        x_max = FFMAX(glyph->bbox.xMax, x_max);

    }

    dtext->max_glyph_h = y_max - y_min;

    dtext->max_glyph_w = x_max - x_min;



    /* compute and save position for each glyph */

    glyph = NULL;

    for (i = 0, p = text; *p; i++) {

        GET_UTF8(code, *p++, continue;);



        /* skip the \n in the sequence \r\n */

        if (prev_code == '\r' && code == '\n')

            continue;



        prev_code = code;

        if (is_newline(code)) {

            max_text_line_w = FFMAX(max_text_line_w, x);

            y += dtext->max_glyph_h;

            x = 0;

            continue;

        }



        /* get glyph */

        prev_glyph = glyph;

        dummy.code = code;

        glyph = av_tree_find(dtext->glyphs, &dummy, glyph_cmp, NULL);



        /* kerning */

        if (dtext->use_kerning && prev_glyph && glyph->code) {

            FT_Get_Kerning(dtext->face, prev_glyph->code, glyph->code,

                           ft_kerning_default, &delta);

            x += delta.x >> 6;

        }



        /* save position */

        dtext->positions[i].x = x + glyph->bitmap_left;

        dtext->positions[i].y = y - glyph->bitmap_top + y_max;

        if (code == '\t') x  = (x / dtext->tabsize + 1)*dtext->tabsize;

        else              x += glyph->advance;

    }



    max_text_line_w = FFMAX(x, max_text_line_w);



    dtext->var_values[VAR_TW] = dtext->var_values[VAR_TEXT_W] = max_text_line_w;

    dtext->var_values[VAR_TH] = dtext->var_values[VAR_TEXT_H] = y + dtext->max_glyph_h;



    dtext->var_values[VAR_MAX_GLYPH_W] = dtext->max_glyph_w;

    dtext->var_values[VAR_MAX_GLYPH_H] = dtext->max_glyph_h;

    dtext->var_values[VAR_MAX_GLYPH_A] = dtext->var_values[VAR_ASCENT ] = y_max;

    dtext->var_values[VAR_MAX_GLYPH_D] = dtext->var_values[VAR_DESCENT] = y_min;



    dtext->var_values[VAR_LINE_H] = dtext->var_values[VAR_LH] = dtext->max_glyph_h;



    dtext->x = dtext->var_values[VAR_X] = av_expr_eval(dtext->x_pexpr, dtext->var_values, &dtext->prng);

    dtext->y = dtext->var_values[VAR_Y] = av_expr_eval(dtext->y_pexpr, dtext->var_values, &dtext->prng);

    dtext->x = dtext->var_values[VAR_X] = av_expr_eval(dtext->x_pexpr, dtext->var_values, &dtext->prng);

    dtext->draw = av_expr_eval(dtext->draw_pexpr, dtext->var_values, &dtext->prng);



    if(!dtext->draw)

        return 0;



    box_w = FFMIN(width - 1 , max_text_line_w);

    box_h = FFMIN(height - 1, y + dtext->max_glyph_h);



    /* draw box */

    if (dtext->draw_box)

        ff_blend_rectangle(&dtext->dc, &dtext->boxcolor,

                           picref->data, picref->linesize, width, height,

                           dtext->x, dtext->y, box_w, box_h);



    if (dtext->shadowx || dtext->shadowy) {

        if ((ret = draw_glyphs(dtext, picref, width, height, dtext->shadowcolor.rgba,

                               &dtext->shadowcolor, dtext->shadowx, dtext->shadowy)) < 0)

            return ret;

    }



    if ((ret = draw_glyphs(dtext, picref, width, height, dtext->fontcolor.rgba,

                           &dtext->fontcolor, 0, 0)) < 0)

        return ret;



    return 0;

}

static int av_thread_message_queue_recv_locked(AVThreadMessageQueue *mq,

                                               void *msg,

                                               unsigned flags)

{

    while (!mq->err_recv && av_fifo_size(mq->fifo) < mq->elsize) {

        if ((flags & AV_THREAD_MESSAGE_NONBLOCK))

            return AVERROR(EAGAIN);

        pthread_cond_wait(&mq->cond, &mq->lock);

    }

    if (av_fifo_size(mq->fifo) < mq->elsize)

        return mq->err_recv;

    av_fifo_generic_read(mq->fifo, msg, mq->elsize, NULL);

    pthread_cond_signal(&mq->cond);

    return 0;

}

void av_thread_message_flush(AVThreadMessageQueue *mq)

{

#if HAVE_THREADS

    int used, off;

    void *free_func = mq->free_func;



    pthread_mutex_lock(&mq->lock);

    used = av_fifo_size(mq->fifo);

    if (free_func)

        for (off = 0; off < used; off += mq->elsize)

            av_fifo_generic_peek_at(mq->fifo, mq, off, mq->elsize, free_func_wrap);

    av_fifo_drain(mq->fifo, used);

    pthread_cond_broadcast(&mq->cond);

    pthread_mutex_unlock(&mq->lock);

#endif /* HAVE_THREADS */

}

int av_open_input_stream(AVFormatContext **ic_ptr,

                         AVIOContext *pb, const char *filename,

                         AVInputFormat *fmt, AVFormatParameters *ap)

{

    int err;

    AVDictionary *opts;

    AVFormatContext *ic;

    AVFormatParameters default_ap;



    if(!ap){

        ap=&default_ap;

        memset(ap, 0, sizeof(default_ap));

    }

    opts = convert_format_parameters(ap);



    if(!ap->prealloced_context)

        ic = avformat_alloc_context();

    else

        ic = *ic_ptr;

    if (!ic) {

        err = AVERROR(ENOMEM);

        goto fail;

    }

    if (pb && fmt && fmt->flags & AVFMT_NOFILE)

        av_log(ic, AV_LOG_WARNING, "Custom AVIOContext makes no sense and "

                                   "will be ignored with AVFMT_NOFILE format.\n");

    else

        ic->pb = pb;



    err = avformat_open_input(&ic, filename, fmt, &opts);

    ic->pb = ic->pb ? ic->pb : pb; // don't leak custom pb if it wasn't set above



    *ic_ptr = ic;

fail:

    av_dict_free(&opts);

    return err;

}

static av_cold int libgsm_encode_init(AVCodecContext *avctx) {

    if (avctx->channels > 1) {

        av_log(avctx, AV_LOG_ERROR, "Mono required for GSM, got %d channels\n",

               avctx->channels);

        return -1;




    if (avctx->sample_rate != 8000) {

        av_log(avctx, AV_LOG_ERROR, "Sample rate 8000Hz required for GSM, got %dHz\n",

               avctx->sample_rate);

        if (avctx->strict_std_compliance > FF_COMPLIANCE_UNOFFICIAL)

            return -1;


    if (avctx->bit_rate != 13000 /* Official */ &&

        avctx->bit_rate != 13200 /* Very common */ &&

        avctx->bit_rate != 0 /* Unknown; a.o. mov does not set bitrate when decoding */ ) {

        av_log(avctx, AV_LOG_ERROR, "Bitrate 13000bps required for GSM, got %dbps\n",

               avctx->bit_rate);

        if (avctx->strict_std_compliance > FF_COMPLIANCE_UNOFFICIAL)

            return -1;




    avctx->priv_data = gsm_create();



    switch(avctx->codec_id) {

    case CODEC_ID_GSM:

        avctx->frame_size = GSM_FRAME_SIZE;

        avctx->block_align = GSM_BLOCK_SIZE;

        break;

    case CODEC_ID_GSM_MS: {

        int one = 1;

        gsm_option(avctx->priv_data, GSM_OPT_WAV49, &one);

        avctx->frame_size = 2*GSM_FRAME_SIZE;

        avctx->block_align = GSM_MS_BLOCK_SIZE;





    avctx->coded_frame= avcodec_alloc_frame();







    return 0;

static void avc_wgt_4x2_msa(uint8_t *data,

                            int32_t stride,

                            int32_t log2_denom,

                            int32_t src_weight,

                            int32_t offset_in)

{

    uint32_t data0, data1;

    v16u8 zero = { 0 };

    v16u8 src0, src1;

    v4i32 res0, res1;

    v8i16 temp0, temp1;

    v16u8 vec0, vec1;

    v8i16 wgt, denom, offset;



    offset_in <<= (log2_denom);



    if (log2_denom) {

        offset_in += (1 << (log2_denom - 1));

    }



    wgt = __msa_fill_h(src_weight);

    offset = __msa_fill_h(offset_in);

    denom = __msa_fill_h(log2_denom);



    data0 = LOAD_WORD(data);

    data1 = LOAD_WORD(data + stride);



    src0 = (v16u8) __msa_fill_w(data0);

    src1 = (v16u8) __msa_fill_w(data1);



    ILVR_B_2VECS_UB(src0, src1, zero, zero, vec0, vec1);



    temp0 = wgt * (v8i16) vec0;

    temp1 = wgt * (v8i16) vec1;



    temp0 = __msa_adds_s_h(temp0, offset);

    temp1 = __msa_adds_s_h(temp1, offset);



    temp0 = __msa_maxi_s_h(temp0, 0);

    temp1 = __msa_maxi_s_h(temp1, 0);



    temp0 = __msa_srl_h(temp0, denom);

    temp1 = __msa_srl_h(temp1, denom);



    temp0 = (v8i16) __msa_sat_u_h((v8u16) temp0, 7);

    temp1 = (v8i16) __msa_sat_u_h((v8u16) temp1, 7);



    res0 = (v4i32) __msa_pckev_b((v16i8) temp0, (v16i8) temp0);

    res1 = (v4i32) __msa_pckev_b((v16i8) temp1, (v16i8) temp1);



    data0 = __msa_copy_u_w(res0, 0);

    data1 = __msa_copy_u_w(res1, 0);



    STORE_WORD(data, data0);

    data += stride;

    STORE_WORD(data, data1);

}

void ff_imdct_calc_3dn2(MDCTContext *s, FFTSample *output,

                        const FFTSample *input, FFTSample *tmp)

{

    long n8, n4, n2, n;

    x86_reg k;

    const uint16_t *revtab = s->fft.revtab;

    const FFTSample *tcos = s->tcos;

    const FFTSample *tsin = s->tsin;

    const FFTSample *in1, *in2;

    FFTComplex *z = (FFTComplex *)tmp;



    n = 1 << s->nbits;

    n2 = n >> 1;

    n4 = n >> 2;

    n8 = n >> 3;



    /* pre rotation */

    in1 = input;

    in2 = input + n2 - 1;

    for(k = 0; k < n4; k++) {

        // FIXME a single block is faster, but gcc 2.95 and 3.4.x on 32bit can't compile it

        asm volatile(

            "movd       %0, %%mm0 \n\t"

            "movd       %2, %%mm1 \n\t"

            "punpckldq  %1, %%mm0 \n\t"

            "punpckldq  %3, %%mm1 \n\t"

            "movq    %%mm0, %%mm2 \n\t"

            "pfmul   %%mm1, %%mm0 \n\t"

            "pswapd  %%mm1, %%mm1 \n\t"

            "pfmul   %%mm1, %%mm2 \n\t"

            "pfpnacc %%mm2, %%mm0 \n\t"

            ::"m"(in2[-2*k]), "m"(in1[2*k]),

              "m"(tcos[k]), "m"(tsin[k])

        );

        asm volatile(

            "movq    %%mm0, %0    \n\t"

            :"=m"(z[revtab[k]])

        );

    }



    ff_fft_calc(&s->fft, z);



    /* post rotation + reordering */

    for(k = 0; k < n4; k++) {

        asm volatile(

            "movq       %0, %%mm0 \n\t"

            "movd       %1, %%mm1 \n\t"

            "punpckldq  %2, %%mm1 \n\t"

            "movq    %%mm0, %%mm2 \n\t"

            "pfmul   %%mm1, %%mm0 \n\t"

            "pswapd  %%mm1, %%mm1 \n\t"

            "pfmul   %%mm1, %%mm2 \n\t"

            "pfpnacc %%mm2, %%mm0 \n\t"

            "movq    %%mm0, %0    \n\t"

            :"+m"(z[k])

            :"m"(tcos[k]), "m"(tsin[k])

        );

    }



    k = n-8;

    asm volatile("movd %0, %%mm7" ::"r"(1<<31));

    asm volatile(

        "1: \n\t"

        "movq    (%4,%0), %%mm0 \n\t" // z[n8+k]

        "neg %0 \n\t"

        "pswapd -8(%4,%0), %%mm1 \n\t" // z[n8-1-k]

        "movq      %%mm0, %%mm2 \n\t"

        "pxor      %%mm7, %%mm2 \n\t"

        "punpckldq %%mm1, %%mm2 \n\t"

        "pswapd    %%mm2, %%mm3 \n\t"

        "punpckhdq %%mm1, %%mm0 \n\t"

        "pswapd    %%mm0, %%mm4 \n\t"

        "pxor      %%mm7, %%mm0 \n\t"

        "pxor      %%mm7, %%mm4 \n\t"

        "movq      %%mm3, -8(%3,%0) \n\t" // output[n-2-2*k] = { z[n8-1-k].im, -z[n8+k].re }

        "movq      %%mm4, -8(%2,%0) \n\t" // output[n2-2-2*k]= { -z[n8-1-k].re, z[n8+k].im }

        "neg %0 \n\t"

        "movq      %%mm0, (%1,%0) \n\t"   // output[2*k]     = { -z[n8+k].im, z[n8-1-k].re }

        "movq      %%mm2, (%2,%0) \n\t"   // output[n2+2*k]  = { -z[n8+k].re, z[n8-1-k].im }

        "sub $8, %0 \n\t"

        "jge 1b \n\t"

        :"+r"(k)

        :"r"(output), "r"(output+n2), "r"(output+n), "r"(z+n8)

        :"memory"

    );

    asm volatile("femms");

}

