static int aac_decode_frame(AVCodecContext *avccontext, void *data,

                            int *data_size, AVPacket *avpkt)

{

    const uint8_t *buf = avpkt->data;

    int buf_size = avpkt->size;

    AACContext *ac = avccontext->priv_data;

    ChannelElement *che = NULL, *che_prev = NULL;

    GetBitContext gb;

    enum RawDataBlockType elem_type, elem_type_prev = TYPE_END;

    int err, elem_id, data_size_tmp;

    int buf_consumed;

    int samples = 1024, multiplier;

    int buf_offset;



    init_get_bits(&gb, buf, buf_size * 8);



    if (show_bits(&gb, 12) == 0xfff) {

        if (parse_adts_frame_header(ac, &gb) < 0) {

            av_log(avccontext, AV_LOG_ERROR, "Error decoding AAC frame header.\n");

            return -1;

        }

        if (ac->m4ac.sampling_index > 12) {

            av_log(ac->avccontext, AV_LOG_ERROR, "invalid sampling rate index %d\n", ac->m4ac.sampling_index);

            return -1;

        }

    }




    // parse

    while ((elem_type = get_bits(&gb, 3)) != TYPE_END) {

        elem_id = get_bits(&gb, 4);



        if (elem_type < TYPE_DSE && !(che=get_che(ac, elem_type, elem_id))) {

            av_log(ac->avccontext, AV_LOG_ERROR, "channel element %d.%d is not allocated\n", elem_type, elem_id);

            return -1;

        }



        switch (elem_type) {



        case TYPE_SCE:

            err = decode_ics(ac, &che->ch[0], &gb, 0, 0);

            break;



        case TYPE_CPE:

            err = decode_cpe(ac, &gb, che);

            break;



        case TYPE_CCE:

            err = decode_cce(ac, &gb, che);

            break;



        case TYPE_LFE:

            err = decode_ics(ac, &che->ch[0], &gb, 0, 0);

            break;



        case TYPE_DSE:

            err = skip_data_stream_element(ac, &gb);

            break;



        case TYPE_PCE: {

            enum ChannelPosition new_che_pos[4][MAX_ELEM_ID];

            memset(new_che_pos, 0, 4 * MAX_ELEM_ID * sizeof(new_che_pos[0][0]));

            if ((err = decode_pce(ac, new_che_pos, &gb)))

                break;

            if (ac->output_configured > OC_TRIAL_PCE)

                av_log(avccontext, AV_LOG_ERROR,

                       "Not evaluating a further program_config_element as this construct is dubious at best.\n");

            else

                err = output_configure(ac, ac->che_pos, new_che_pos, 0, OC_TRIAL_PCE);

            break;

        }



        case TYPE_FIL:

            if (elem_id == 15)

                elem_id += get_bits(&gb, 8) - 1;

            if (get_bits_left(&gb) < 8 * elem_id) {

                    av_log(avccontext, AV_LOG_ERROR, overread_err);

                    return -1;

            }

            while (elem_id > 0)

                elem_id -= decode_extension_payload(ac, &gb, elem_id, che_prev, elem_type_prev);

            err = 0; /* FIXME */

            break;



        default:

            err = -1; /* should not happen, but keeps compiler happy */

            break;

        }



        che_prev       = che;

        elem_type_prev = elem_type;



        if (err)

            return err;



        if (get_bits_left(&gb) < 3) {

            av_log(avccontext, AV_LOG_ERROR, overread_err);

            return -1;

        }

    }



    spectral_to_sample(ac);



    multiplier = (ac->m4ac.sbr == 1) ? ac->m4ac.ext_sample_rate > ac->m4ac.sample_rate : 0;

    samples <<= multiplier;

    if (ac->output_configured < OC_LOCKED) {

        avccontext->sample_rate = ac->m4ac.sample_rate << multiplier;

        avccontext->frame_size = samples;

    }



    data_size_tmp = samples * avccontext->channels * sizeof(int16_t);

    if (*data_size < data_size_tmp) {

        av_log(avccontext, AV_LOG_ERROR,

               "Output buffer too small (%d) or trying to output too many samples (%d) for this frame.\n",

               *data_size, data_size_tmp);

        return -1;

    }

    *data_size = data_size_tmp;



    ac->dsp.float_to_int16_interleave(data, (const float **)ac->output_data, samples, avccontext->channels);



    if (ac->output_configured)

        ac->output_configured = OC_LOCKED;



    buf_consumed = (get_bits_count(&gb) + 7) >> 3;

    for (buf_offset = buf_consumed; buf_offset < buf_size; buf_offset++)

        if (buf[buf_offset])

            break;



    return buf_size > buf_offset ? buf_consumed : buf_size;

}

static inline void dv_guess_qnos(EncBlockInfo* blks, int* qnos)

{

    int size[5];

    int i, j, k, a, prev, a2;

    EncBlockInfo* b;



    size[4]= 1<<24;

    do {

       b = blks;

       for (i=0; i<5; i++) {

          if (!qnos[i])

              continue;



          qnos[i]--;

          size[i] = 0;

          for (j=0; j<6; j++, b++) {

             for (a=0; a<4; a++) {

                if (b->area_q[a] != dv_quant_shifts[qnos[i] + dv_quant_offset[b->cno]][a]) {

                    b->bit_size[a] = 1; // 4 areas 4 bits for EOB :)

                    b->area_q[a]++;

                    prev= b->prev[a];

                    for (k= b->next[prev] ; k<mb_area_start[a+1]; k= b->next[k]) {

                       b->mb[k] >>= 1;

                       if (b->mb[k]) {

                           b->bit_size[a] += dv_rl2vlc_size(k - prev - 1, b->mb[k]);

                           prev= k;

                       } else {

                           if(b->next[k] >= mb_area_start[a+1] && b->next[k]<64){

                                for(a2=a+1; b->next[k] >= mb_area_start[a2+1]; a2++);

                                assert(a2<4);

                                assert(b->mb[b->next[k]]);

                                b->bit_size[a2] += dv_rl2vlc_size(b->next[k] - prev - 1, b->mb[b->next[k]])

                                                  -dv_rl2vlc_size(b->next[k] -    k - 1, b->mb[b->next[k]]);

                           }

                           b->next[prev] = b->next[k];

                       }

                    }

                    b->prev[a+1]= prev;

                }

                size[i] += b->bit_size[a];

             }

          }

          if(vs_total_ac_bits >= size[0] + size[1] + size[2] + size[3] + size[4])

                return;

       }

    } while (qnos[0]|qnos[1]|qnos[2]|qnos[3]|qnos[4]);





    for(a=2; a==2 || vs_total_ac_bits < size[0]; a+=a){

        b = blks;

        size[0] = 5*6*4; //EOB

        for (j=0; j<6*5; j++, b++) {

            prev= b->prev[0];

            for (k= b->next[prev]; k<64; k= b->next[k]) {

                if(b->mb[k] < a && b->mb[k] > -a){

                    b->next[prev] = b->next[k];

                }else{

                    size[0] += dv_rl2vlc_size(k - prev - 1, b->mb[k]);

                    prev= k;

                }

            }

        }

    }

}

static av_cold int hnm_decode_init(AVCodecContext *avctx)

{

    Hnm4VideoContext *hnm = avctx->priv_data;



    if (avctx->extradata_size < 1) {

        av_log(avctx, AV_LOG_ERROR,

               "Extradata missing, decoder requires version number\n");

        return AVERROR_INVALIDDATA;

    }



    hnm->version   = avctx->extradata[0];

    avctx->pix_fmt = AV_PIX_FMT_PAL8;

    hnm->width     = avctx->width;

    hnm->height    = avctx->height;

    hnm->buffer1   = av_mallocz(avctx->width * avctx->height);

    hnm->buffer2   = av_mallocz(avctx->width * avctx->height);

    hnm->processed = av_mallocz(avctx->width * avctx->height);



    if (!hnm->buffer1 || !hnm->buffer2 || !hnm->processed) {

        av_log(avctx, AV_LOG_ERROR, "av_mallocz() failed\n");

        av_freep(&hnm->buffer1);

        av_freep(&hnm->buffer2);

        av_freep(&hnm->processed);

        return AVERROR(ENOMEM);

    }



    hnm->current  = hnm->buffer1;

    hnm->previous = hnm->buffer2;



    return 0;

}

static int tqi_decode_frame(AVCodecContext *avctx,

                            void *data, int *data_size,

                            AVPacket *avpkt)

{

    const uint8_t *buf = avpkt->data;

    int buf_size = avpkt->size;

    const uint8_t *buf_end = buf+buf_size;

    TqiContext *t = avctx->priv_data;

    MpegEncContext *s = &t->s;



    s->width  = AV_RL16(&buf[0]);

    s->height = AV_RL16(&buf[2]);

    tqi_calculate_qtable(s, buf[4]);

    buf += 8;



    if (t->frame.data[0])

        avctx->release_buffer(avctx, &t->frame);



    if (s->avctx->width!=s->width || s->avctx->height!=s->height)

        avcodec_set_dimensions(s->avctx, s->width, s->height);



    if(avctx->get_buffer(avctx, &t->frame) < 0) {

        av_log(avctx, AV_LOG_ERROR, "get_buffer() failed\n");

        return -1;

    }



    av_fast_malloc(&t->bitstream_buf, &t->bitstream_buf_size, (buf_end-buf) + FF_INPUT_BUFFER_PADDING_SIZE);

    if (!t->bitstream_buf)

        return AVERROR(ENOMEM);

    s->dsp.bswap_buf(t->bitstream_buf, (const uint32_t*)buf, (buf_end-buf)/4);

    init_get_bits(&s->gb, t->bitstream_buf, 8*(buf_end-buf));



    s->last_dc[0] = s->last_dc[1] = s->last_dc[2] = 0;

    for (s->mb_y=0; s->mb_y<(avctx->height+15)/16; s->mb_y++)

    for (s->mb_x=0; s->mb_x<(avctx->width+15)/16; s->mb_x++)

    {

        if(tqi_decode_mb(s, t->block) < 0)

            break;

        tqi_idct_put(t, t->block);

    }



    *data_size = sizeof(AVFrame);

    *(AVFrame*)data = t->frame;

    return buf_size;

}

static void sbr_dequant(SpectralBandReplication *sbr, int id_aac)

{

    int k, e;

    int ch;



    if (id_aac == TYPE_CPE && sbr->bs_coupling) {

        float alpha      = sbr->data[0].bs_amp_res ?  1.0f :  0.5f;

        float pan_offset = sbr->data[0].bs_amp_res ? 12.0f : 24.0f;

        for (e = 1; e <= sbr->data[0].bs_num_env; e++) {

            for (k = 0; k < sbr->n[sbr->data[0].bs_freq_res[e]]; k++) {

                float temp1 = exp2f(sbr->data[0].env_facs[e][k] * alpha + 7.0f);

                float temp2 = exp2f((pan_offset - sbr->data[1].env_facs[e][k]) * alpha);

                float fac   = temp1 / (1.0f + temp2);

                sbr->data[0].env_facs[e][k] = fac;

                sbr->data[1].env_facs[e][k] = fac * temp2;

            }

        }

        for (e = 1; e <= sbr->data[0].bs_num_noise; e++) {

            for (k = 0; k < sbr->n_q; k++) {

                float temp1 = exp2f(NOISE_FLOOR_OFFSET - sbr->data[0].noise_facs[e][k] + 1);

                float temp2 = exp2f(12 - sbr->data[1].noise_facs[e][k]);

                float fac   = temp1 / (1.0f + temp2);

                sbr->data[0].noise_facs[e][k] = fac;

                sbr->data[1].noise_facs[e][k] = fac * temp2;

            }

        }

    } else { // SCE or one non-coupled CPE

        for (ch = 0; ch < (id_aac == TYPE_CPE) + 1; ch++) {

            float alpha = sbr->data[ch].bs_amp_res ? 1.0f : 0.5f;

            for (e = 1; e <= sbr->data[ch].bs_num_env; e++)

                for (k = 0; k < sbr->n[sbr->data[ch].bs_freq_res[e]]; k++)

                    sbr->data[ch].env_facs[e][k] =

                        exp2f(alpha * sbr->data[ch].env_facs[e][k] + 6.0f);

            for (e = 1; e <= sbr->data[ch].bs_num_noise; e++)

                for (k = 0; k < sbr->n_q; k++)

                    sbr->data[ch].noise_facs[e][k] =

                        exp2f(NOISE_FLOOR_OFFSET - sbr->data[ch].noise_facs[e][k]);

        }

    }

}

static inline int16_t logadd(int16_t a, int16_t b)

{

    int16_t c = a - b;

    uint8_t address = FFMIN((ABS(c) >> 1), 255);



    return ((c >= 0) ? (a + latab[address]) : (b + latab[address]));

}

static int write_manifest(AVFormatContext *s, int final)

{

    DASHContext *c = s->priv_data;

    AVIOContext *out;

    char temp_filename[1024];

    int ret, i;

    AVDictionaryEntry *title = av_dict_get(s->metadata, "title", NULL, 0);



    snprintf(temp_filename, sizeof(temp_filename), "%s.tmp", s->filename);

    ret = avio_open2(&out, temp_filename, AVIO_FLAG_WRITE, &s->interrupt_callback, NULL);

    if (ret < 0) {

        av_log(s, AV_LOG_ERROR, "Unable to open %s for writing\n", temp_filename);

        return ret;

    }

    avio_printf(out, "<?xml version=\"1.0\" encoding=\"utf-8\"?>\n");

    avio_printf(out, "<MPD xmlns:xsi=\"http://www.w3.org/2001/XMLSchema-instance\"\n"

                "\txmlns=\"urn:mpeg:dash:schema:mpd:2011\"\n"

                "\txmlns:xlink=\"http://www.w3.org/1999/xlink\"\n"

                "\txsi:schemaLocation=\"urn:mpeg:DASH:schema:MPD:2011 http://standards.iso.org/ittf/PubliclyAvailableStandards/MPEG-DASH_schema_files/DASH-MPD.xsd\"\n"

                "\tprofiles=\"urn:mpeg:dash:profile:isoff-live:2011\"\n"

                "\ttype=\"%s\"\n", final ? "static" : "dynamic");

    if (final) {

        avio_printf(out, "\tmediaPresentationDuration=\"");

        write_time(out, c->total_duration);

        avio_printf(out, "\"\n");

    } else {

        int update_period = c->last_duration / AV_TIME_BASE;

        if (c->use_template && !c->use_timeline)

            update_period = 500;

        avio_printf(out, "\tminimumUpdatePeriod=\"PT%dS\"\n", update_period);

        avio_printf(out, "\tsuggestedPresentationDelay=\"PT%dS\"\n", c->last_duration / AV_TIME_BASE);

        if (!c->availability_start_time[0] && s->nb_streams > 0 && c->streams[0].nb_segments > 0) {

            time_t t = time(NULL);

            struct tm *ptm, tmbuf;

            ptm = gmtime_r(&t, &tmbuf);

            if (ptm) {

                if (!strftime(c->availability_start_time, sizeof(c->availability_start_time),

                              "%Y-%m-%dT%H:%M:%S", ptm))

                    c->availability_start_time[0] = '\0';

            }

        }

        if (c->availability_start_time[0])

            avio_printf(out, "\tavailabilityStartTime=\"%s\"\n", c->availability_start_time);

        if (c->window_size && c->use_template) {

            avio_printf(out, "\ttimeShiftBufferDepth=\"");

            write_time(out, c->last_duration * c->window_size);

            avio_printf(out, "\"\n");

        }

    }

    avio_printf(out, "\tminBufferTime=\"");

    write_time(out, c->last_duration);

    avio_printf(out, "\">\n");

    avio_printf(out, "\t<ProgramInformation>\n");

    if (title) {

        char *escaped = xmlescape(title->value);

        avio_printf(out, "\t\t<Title>%s</Title>\n", escaped);

        av_free(escaped);

    }

    avio_printf(out, "\t</ProgramInformation>\n");

    if (c->window_size && s->nb_streams > 0 && c->streams[0].nb_segments > 0 && !c->use_template) {

        OutputStream *os = &c->streams[0];

        int start_index = FFMAX(os->nb_segments - c->window_size, 0);

        int64_t start_time = av_rescale_q(os->segments[start_index]->time, s->streams[0]->time_base, AV_TIME_BASE_Q);

        avio_printf(out, "\t<Period start=\"");

        write_time(out, start_time);

        avio_printf(out, "\">\n");

    } else {

        avio_printf(out, "\t<Period start=\"PT0.0S\">\n");

    }



    if (c->has_video) {

        avio_printf(out, "\t\t<AdaptationSet id=\"video\" segmentAlignment=\"true\" bitstreamSwitching=\"true\">\n");

        for (i = 0; i < s->nb_streams; i++) {

            AVStream *st = s->streams[i];

            OutputStream *os = &c->streams[i];

            if (s->streams[i]->codec->codec_type != AVMEDIA_TYPE_VIDEO)

                continue;

            avio_printf(out, "\t\t\t<Representation id=\"%d\" mimeType=\"video/mp4\" codecs=\"%s\"%s width=\"%d\" height=\"%d\">\n", i, os->codec_str, os->bandwidth_str, st->codec->width, st->codec->height);

            output_segment_list(&c->streams[i], out, c);

            avio_printf(out, "\t\t\t</Representation>\n");

        }

        avio_printf(out, "\t\t</AdaptationSet>\n");

    }

    if (c->has_audio) {

        avio_printf(out, "\t\t<AdaptationSet id=\"audio\" segmentAlignment=\"true\" bitstreamSwitching=\"true\">\n");

        for (i = 0; i < s->nb_streams; i++) {

            AVStream *st = s->streams[i];

            OutputStream *os = &c->streams[i];

            if (s->streams[i]->codec->codec_type != AVMEDIA_TYPE_AUDIO)

                continue;

            avio_printf(out, "\t\t\t<Representation id=\"%d\" mimeType=\"audio/mp4\" codecs=\"%s\"%s audioSamplingRate=\"%d\">\n", i, os->codec_str, os->bandwidth_str, st->codec->sample_rate);

            avio_printf(out, "\t\t\t\t<AudioChannelConfiguration schemeIdUri=\"urn:mpeg:dash:23003:3:audio_channel_configuration:2011\" value=\"%d\" />\n", st->codec->channels);

            output_segment_list(&c->streams[i], out, c);

            avio_printf(out, "\t\t\t</Representation>\n");

        }

        avio_printf(out, "\t\t</AdaptationSet>\n");

    }

    avio_printf(out, "\t</Period>\n");

    avio_printf(out, "</MPD>\n");

    avio_flush(out);

    avio_close(out);

    return ff_rename(temp_filename, s->filename, s);

}

static int get_scale_factor(H264SliceContext *sl,

                            int poc, int poc1, int i)

{

    int poc0 = sl->ref_list[0][i].poc;

    int td = av_clip_int8(poc1 - poc0);

    if (td == 0 || sl->ref_list[0][i].parent->long_ref) {

        return 256;

    } else {

        int tb = av_clip_int8(poc - poc0);

        int tx = (16384 + (FFABS(td) >> 1)) / td;

        return av_clip_intp2((tb * tx + 32) >> 6, 10);

    }

}

static int get_video_frame(VideoState *is, AVFrame *frame, int64_t *pts, AVPacket *pkt)

{

    int got_picture, i;



    if (packet_queue_get(&is->videoq, pkt, 1) < 0)

        return -1;



    if (pkt->data == flush_pkt.data) {

        avcodec_flush_buffers(is->video_st->codec);



        SDL_LockMutex(is->pictq_mutex);

        // Make sure there are no long delay timers (ideally we should just flush the que but thats harder)

        for (i = 0; i < VIDEO_PICTURE_QUEUE_SIZE; i++) {

            is->pictq[i].skip = 1;

        }

        while (is->pictq_size && !is->videoq.abort_request) {

            SDL_CondWait(is->pictq_cond, is->pictq_mutex);

        }

        is->video_current_pos = -1;

        is->frame_last_pts = AV_NOPTS_VALUE;

        is->frame_last_duration = 0;

        is->frame_timer = (double)av_gettime() / 1000000.0;

        is->frame_last_dropped_pts = AV_NOPTS_VALUE;

        SDL_UnlockMutex(is->pictq_mutex);



        return 0;

    }



    avcodec_decode_video2(is->video_st->codec, frame, &got_picture, pkt);



    if (got_picture) {

        int ret = 1;



        if (decoder_reorder_pts == -1) {

            *pts = av_frame_get_best_effort_timestamp(frame);

        } else if (decoder_reorder_pts) {

            *pts = frame->pkt_pts;

        } else {

            *pts = frame->pkt_dts;

        }



        if (*pts == AV_NOPTS_VALUE) {

            *pts = 0;

        }



        if (((is->av_sync_type == AV_SYNC_AUDIO_MASTER && is->audio_st) || is->av_sync_type == AV_SYNC_EXTERNAL_CLOCK) &&

             (framedrop>0 || (framedrop && is->audio_st))) {

            SDL_LockMutex(is->pictq_mutex);

            if (is->frame_last_pts != AV_NOPTS_VALUE && *pts) {

                double clockdiff = get_video_clock(is) - get_master_clock(is);

                double dpts = av_q2d(is->video_st->time_base) * *pts;

                double ptsdiff = dpts - is->frame_last_pts;

                if (fabs(clockdiff) < AV_NOSYNC_THRESHOLD &&

                     ptsdiff > 0 && ptsdiff < AV_NOSYNC_THRESHOLD &&

                     clockdiff + ptsdiff - is->frame_last_filter_delay < 0) {

                    is->frame_last_dropped_pos = pkt->pos;

                    is->frame_last_dropped_pts = dpts;

                    is->frame_drops_early++;

                    ret = 0;

                }

            }

            SDL_UnlockMutex(is->pictq_mutex);

        }



        return ret;

    }

    return 0;

}

static int X264_frame(AVCodecContext *ctx, uint8_t *buf,

                      int bufsize, void *data)

{

    X264Context *x4 = ctx->priv_data;

    AVFrame *frame = data;

    x264_nal_t *nal;

    int nnal, i;

    x264_picture_t pic_out;



    x4->pic.img.i_csp   = X264_CSP_I420;

    x4->pic.img.i_plane = 3;



    if (frame) {

        for (i = 0; i < 3; i++) {

            x4->pic.img.plane[i]    = frame->data[i];

            x4->pic.img.i_stride[i] = frame->linesize[i];

        }



        x4->pic.i_pts  = frame->pts;

        x4->pic.i_type = X264_TYPE_AUTO;

    }



    if (x264_encoder_encode(x4->enc, &nal, &nnal, frame? &x4->pic: NULL, &pic_out) < 0)

        return -1;



    bufsize = encode_nals(ctx, buf, bufsize, nal, nnal, 0);

    if (bufsize < 0)

        return -1;



    /* FIXME: dts */

    x4->out_pic.pts = pic_out.i_pts;



    switch (pic_out.i_type) {

    case X264_TYPE_IDR:

    case X264_TYPE_I:

        x4->out_pic.pict_type = FF_I_TYPE;

        break;

    case X264_TYPE_P:

        x4->out_pic.pict_type = FF_P_TYPE;

        break;

    case X264_TYPE_B:

    case X264_TYPE_BREF:

        x4->out_pic.pict_type = FF_B_TYPE;

        break;

    }



    x4->out_pic.key_frame = pic_out.i_type == X264_TYPE_IDR;

    x4->out_pic.quality   = (pic_out.i_qpplus1 - 1) * FF_QP2LAMBDA;



    return bufsize;

}

static void fill_buffer(ByteIOContext *s)

{

    int len;



    /* no need to do anything if EOF already reached */

    if (s->eof_reached)

        return;



    if(s->update_checksum){

        if(s->buf_end > s->checksum_ptr)

            s->checksum= s->update_checksum(s->checksum, s->checksum_ptr, s->buf_end - s->checksum_ptr);

        s->checksum_ptr= s->buffer;

    }



    len = s->read_packet(s->opaque, s->buffer, s->buffer_size);

    if (len <= 0) {

        /* do not modify buffer if EOF reached so that a seek back can

           be done without rereading data */

        s->eof_reached = 1;

        if(len<0)

            s->error= len;

    } else {

        s->pos += len;

        s->buf_ptr = s->buffer;

        s->buf_end = s->buffer + len;

    }

}

static int adx_encode_frame(AVCodecContext *avctx, uint8_t *frame,

                            int buf_size, void *data)

{

    ADXContext *c          = avctx->priv_data;

    const int16_t *samples = data;

    uint8_t *dst           = frame;

    int ch;



    if (!c->header_parsed) {

        int hdrsize = adx_encode_header(avctx, dst, buf_size);

        dst += hdrsize;

        c->header_parsed = 1;

    }



    for (ch = 0; ch < avctx->channels; ch++) {

        adx_encode(c, dst, samples + ch, &c->prev[ch], avctx->channels);

        dst += BLOCK_SIZE;

    }

    return dst - frame;

}

static int bmp_parse(AVCodecParserContext *s, AVCodecContext *avctx,

                     const uint8_t **poutbuf, int *poutbuf_size,

                     const uint8_t *buf, int buf_size)

{

    BMPParseContext *bpc = s->priv_data;

    uint64_t state = bpc->pc.state64;

    int next = END_NOT_FOUND;

    int i = 0;



    *poutbuf_size = 0;



restart:

    if (bpc->pc.frame_start_found <= 2+4+4) {

        for (; i < buf_size; i++) {

            state = (state << 8) | buf[i];

            if (bpc->pc.frame_start_found == 0) {

                if ((state >> 48) == (('B' << 8) | 'M')) {

                    bpc->fsize = av_bswap32(state >> 16);

                    bpc->pc.frame_start_found = 1;

                }

            } else if (bpc->pc.frame_start_found == 2+4+4) {

//                 unsigned hsize = av_bswap32(state>>32);

                unsigned ihsize = av_bswap32(state);

                if (ihsize < 12 || ihsize > 200) {

                    bpc->pc.frame_start_found = 0;

                    continue;

                }

                bpc->pc.frame_start_found++;

                bpc->remaining_size = bpc->fsize + i - 17;



                if (bpc->pc.index + i > 17) {

                    next = i - 17;

                    state = 0;

                    break;

                } else {

                    bpc->pc.state64 = 0;

                    goto restart;

                }

            } else if (bpc->pc.frame_start_found)

                bpc->pc.frame_start_found++;

        }

        bpc->pc.state64 = state;

    } else {

        if (bpc->remaining_size) {

            i = FFMIN(bpc->remaining_size, buf_size);

            bpc->remaining_size -= i;

            if (bpc->remaining_size)

                goto flush;



            bpc->pc.frame_start_found = 0;

            goto restart;

        }

    }



flush:

    if (ff_combine_frame(&bpc->pc, next, &buf, &buf_size) < 0)

        return buf_size;



    if (next != END_NOT_FOUND && next < 0)

        bpc->pc.frame_start_found = FFMAX(bpc->pc.frame_start_found - i - 1, 0);

    else

        bpc->pc.frame_start_found = 0;



    *poutbuf      = buf;

    *poutbuf_size = buf_size;

    return next;

}

static int avi_read_seek(AVFormatContext *s, int stream_index, int64_t timestamp, int flags)

{

    AVIContext *avi = s->priv_data;

    AVStream *st;

    int i, index;

    int64_t pos;

    AVIStream *ast;



    if (!avi->index_loaded) {

        /* we only load the index on demand */

        avi_load_index(s);

        avi->index_loaded = 1;

    }

    assert(stream_index>= 0);



    st = s->streams[stream_index];

    ast= st->priv_data;

    index= av_index_search_timestamp(st, timestamp * FFMAX(ast->sample_size, 1), flags);

    if(index<0)

        return -1;



    /* find the position */

    pos = st->index_entries[index].pos;

    timestamp = st->index_entries[index].timestamp / FFMAX(ast->sample_size, 1);



    av_dlog(s, "XX %"PRId64" %d %"PRId64"\n",

            timestamp, index, st->index_entries[index].timestamp);



    if (CONFIG_DV_DEMUXER && avi->dv_demux) {

        /* One and only one real stream for DV in AVI, and it has video  */

        /* offsets. Calling with other stream indexes should have failed */

        /* the av_index_search_timestamp call above.                     */

        assert(stream_index == 0);



        /* Feed the DV video stream version of the timestamp to the */

        /* DV demux so it can synthesize correct timestamps.        */

        ff_dv_offset_reset(avi->dv_demux, timestamp);



        avio_seek(s->pb, pos, SEEK_SET);

        avi->stream_index= -1;

        return 0;

    }



    for(i = 0; i < s->nb_streams; i++) {

        AVStream *st2 = s->streams[i];

        AVIStream *ast2 = st2->priv_data;



        ast2->packet_size=

        ast2->remaining= 0;



        if (ast2->sub_ctx) {

            seek_subtitle(st, st2, timestamp);

            continue;

        }



        if (st2->nb_index_entries <= 0)

            continue;



//        assert(st2->codec->block_align);

        assert((int64_t)st2->time_base.num*ast2->rate == (int64_t)st2->time_base.den*ast2->scale);

        index = av_index_search_timestamp(

                st2,

                av_rescale_q(timestamp, st->time_base, st2->time_base) * FFMAX(ast2->sample_size, 1),

                flags | AVSEEK_FLAG_BACKWARD);

        if(index<0)

            index=0;



        if(!avi->non_interleaved){

            while(index>0 && st2->index_entries[index].pos > pos)

                index--;

            while(index+1 < st2->nb_index_entries && st2->index_entries[index].pos < pos)

                index++;

        }



        av_dlog(s, "%"PRId64" %d %"PRId64"\n",

                timestamp, index, st2->index_entries[index].timestamp);

        /* extract the current frame number */

        ast2->frame_offset = st2->index_entries[index].timestamp;

    }



    /* do the seek */

    avio_seek(s->pb, pos, SEEK_SET);

    avi->stream_index= -1;

    return 0;

}

static int opt_streamid(const char *opt, const char *arg)

{

    int idx;

    char *p;

    char idx_str[16];



    av_strlcpy(idx_str, arg, sizeof(idx_str));

    p = strchr(idx_str, ':');

    if (!p) {

        fprintf(stderr,

                "Invalid value '%s' for option '%s', required syntax is 'index:value'\n",

                arg, opt);

        ffmpeg_exit(1);

    }

    *p++ = '\0';

    idx = parse_number_or_die(opt, idx_str, OPT_INT, 0, INT_MAX);

    streamid_map = grow_array(streamid_map, sizeof(*streamid_map), &nb_streamid_map, idx+1);

    streamid_map[idx] = parse_number_or_die(opt, p, OPT_INT, 0, INT_MAX);

    return 0;

}

static void avc_luma_midv_qrt_16w_msa(const uint8_t *src, int32_t src_stride,

                                      uint8_t *dst, int32_t dst_stride,

                                      int32_t height, uint8_t vert_offset)

{

    uint32_t multiple8_cnt;



    for (multiple8_cnt = 2; multiple8_cnt--;) {

        avc_luma_midv_qrt_8w_msa(src, src_stride, dst, dst_stride, height,

                                 vert_offset);



        src += 8;

        dst += 8;

    }

}

static void RENAME(yuv2rgb32_1)(SwsContext *c, const uint16_t *buf0,

