    if (avctx->dsp_mask) {

        if (avctx->dsp_mask & FF_MM_FORCE)

            mm_flags |= (avctx->dsp_mask & 0xffff);

        else

            mm_flags &= ~(avctx->dsp_mask & 0xffff);

    }



#if 0

    av_log(avctx, AV_LOG_INFO, "libavcodec: CPU flags:");

