        av_log(avctx, AV_LOG_INFO, " mmx");

    if (mm_flags & MM_MMXEXT)

        av_log(avctx, AV_LOG_INFO, " mmxext");

    if (mm_flags & MM_3DNOW)

        av_log(avctx, AV_LOG_INFO, " 3dnow");

    if (mm_flags & MM_SSE)

        av_log(avctx, AV_LOG_INFO, " sse");

    if (mm_flags & MM_SSE2)

        av_log(avctx, AV_LOG_INFO, " sse2");

