static void guess_palette(DVDSubContext* ctx,

                          uint32_t *rgba_palette,

                          uint32_t subtitle_color)

{

    static const uint8_t level_map[4][4] = {

        // this configuration (full range, lowest to highest) in tests

        // seemed most common, so assume this

        {0xff},

        {0x00, 0xff},

        {0x00, 0x80, 0xff},

        {0x00, 0x55, 0xaa, 0xff},

    };

    uint8_t color_used[16] = { 0 };

    int nb_opaque_colors, i, level, j, r, g, b;

    uint8_t *colormap = ctx->colormap, *alpha = ctx->alpha;



    if(ctx->has_palette) {

        for(i = 0; i < 4; i++)

            rgba_palette[i] = (ctx->palette[colormap[i]] & 0x00ffffff)

                              | ((alpha[i] * 17U) << 24);

        return;

    }



    for(i = 0; i < 4; i++)

        rgba_palette[i] = 0;



    nb_opaque_colors = 0;

    for(i = 0; i < 4; i++) {

        if (alpha[i] != 0 && !color_used[colormap[i]]) {

            color_used[colormap[i]] = 1;

            nb_opaque_colors++;

        }

    }



    if (nb_opaque_colors == 0)

        return;



    j = 0;

    memset(color_used, 0, 16);

    for(i = 0; i < 4; i++) {

        if (alpha[i] != 0) {

            if (!color_used[colormap[i]])  {

                level = level_map[nb_opaque_colors - 1][j];

                r = (((subtitle_color >> 16) & 0xff) * level) >> 8;

                g = (((subtitle_color >> 8) & 0xff) * level) >> 8;

                b = (((subtitle_color >> 0) & 0xff) * level) >> 8;

                rgba_palette[i] = b | (g << 8) | (r << 16) | ((alpha[i] * 17) << 24);

                color_used[colormap[i]] = (i + 1);

                j++;

            } else {

                rgba_palette[i] = (rgba_palette[color_used[colormap[i]] - 1] & 0x00ffffff) |

                                    ((alpha[i] * 17) << 24);

            }

        }

    }

}

int ff_generate_sliding_window_mmcos(H264Context *h, int first_slice)

{

    MMCO mmco_temp[MAX_MMCO_COUNT], *mmco = first_slice ? h->mmco : mmco_temp;

    int mmco_index = 0, i;



    assert(h->long_ref_count + h->short_ref_count <= h->sps.ref_frame_count);



    if (h->short_ref_count &&

        h->long_ref_count + h->short_ref_count == h->sps.ref_frame_count &&

        !(FIELD_PICTURE(h) && !h->first_field && h->cur_pic_ptr->reference)) {

        mmco[0].opcode        = MMCO_SHORT2UNUSED;

        mmco[0].short_pic_num = h->short_ref[h->short_ref_count - 1]->frame_num;

        mmco_index            = 1;

        if (FIELD_PICTURE(h)) {

            mmco[0].short_pic_num *= 2;

            mmco[1].opcode         = MMCO_SHORT2UNUSED;

            mmco[1].short_pic_num  = mmco[0].short_pic_num + 1;

            mmco_index             = 2;

        }

    }



    if (first_slice) {

        h->mmco_index = mmco_index;

    } else if (!first_slice && mmco_index >= 0 &&

               (mmco_index != h->mmco_index ||

                (i = check_opcodes(h->mmco, mmco_temp, mmco_index)))) {

        av_log(h->avctx, AV_LOG_ERROR,

               "Inconsistent MMCO state between slices [%d, %d, %d]\n",

               mmco_index, h->mmco_index, i);

        return AVERROR_INVALIDDATA;

    }

    return 0;

}

ImgReSampleContext *img_resample_full_init(int owidth, int oheight,

                                      int iwidth, int iheight,

                                      int topBand, int bottomBand,

        int leftBand, int rightBand,

        int padtop, int padbottom,

        int padleft, int padright)

{

    ImgReSampleContext *s;



    s = av_mallocz(sizeof(ImgReSampleContext));

    if (!s)




    s->line_buf = av_mallocz(owidth * (LINE_BUF_HEIGHT + NB_TAPS));

    if (!s->line_buf) 

        goto fail;



    s->owidth = owidth;

    s->oheight = oheight;

    s->iwidth = iwidth;

    s->iheight = iheight;



    s->topBand = topBand;

    s->bottomBand = bottomBand;

    s->leftBand = leftBand;

    s->rightBand = rightBand;



    s->padtop = padtop;

    s->padbottom = padbottom;

    s->padleft = padleft;

    s->padright = padright;



    s->pad_owidth = owidth - (padleft + padright);

    s->pad_oheight = oheight - (padtop + padbottom);



    s->h_incr = ((iwidth - leftBand - rightBand) * POS_FRAC) / s->pad_owidth;

    s->v_incr = ((iheight - topBand - bottomBand) * POS_FRAC) / s->pad_oheight; 



    av_build_filter(&s->h_filters[0][0], (float) s->pad_owidth  / 

            (float) (iwidth - leftBand - rightBand), NB_TAPS, NB_PHASES, 1<<FILTER_BITS, 0);

    av_build_filter(&s->v_filters[0][0], (float) s->pad_oheight / 

            (float) (iheight - topBand - bottomBand), NB_TAPS, NB_PHASES, 1<<FILTER_BITS, 0);



    return s;

fail:

    av_free(s);


}

static inline void idct4col_add(uint8_t *dest, int line_size, const DCTELEM *col)

{

    int c0, c1, c2, c3, a0, a1, a2, a3;

    const uint8_t *cm = ff_cropTbl + MAX_NEG_CROP;



    a0 = col[8*0];

    a1 = col[8*1];

    a2 = col[8*2];

    a3 = col[8*3];

    c0 = (a0 + a2)*C3 + (1 << (C_SHIFT - 1));

    c2 = (a0 - a2)*C3 + (1 << (C_SHIFT - 1));

    c1 = a1 * C1 + a3 * C2;

    c3 = a1 * C2 - a3 * C1;

    dest[0] = cm[dest[0] + ((c0 + c1) >> C_SHIFT)];

    dest += line_size;

    dest[0] = cm[dest[0] + ((c2 + c3) >> C_SHIFT)];

    dest += line_size;

    dest[0] = cm[dest[0] + ((c2 - c3) >> C_SHIFT)];

    dest += line_size;

    dest[0] = cm[dest[0] + ((c0 - c1) >> C_SHIFT)];

}

