                    if(flags & SWS_FULL_CHR_H_INT) {

                        yuv2rgbXinC_full(c, //FIXME write a packed2_full function

                                         vLumFilter+dstY*vLumFilterSize, lumSrcPtr, vLumFilterSize,

                                         vChrFilter+dstY*vChrFilterSize, chrSrcPtr, vChrFilterSize,

                                         alpSrcPtr, dest, dstW, dstY);

                    } else {

                        c->yuv2packed2(c, *lumSrcPtr, *(lumSrcPtr+1), *chrSrcPtr, *(chrSrcPtr+1),

                                       alpPixBuf ? *alpSrcPtr : NULL, alpPixBuf ? *(alpSrcPtr+1) : NULL,

                                       dest, dstW, lumAlpha, chrAlpha, dstY);

                    }

                } else { //general RGB

                    if(flags & SWS_FULL_CHR_H_INT) {

                        yuv2rgbXinC_full(c,

                                         vLumFilter+dstY*vLumFilterSize, lumSrcPtr, vLumFilterSize,

                                         vChrFilter+dstY*vChrFilterSize, chrSrcPtr, vChrFilterSize,

                                         alpSrcPtr, dest, dstW, dstY);

                    } else {

                        c->yuv2packedX(c,

                                       vLumFilter+dstY*vLumFilterSize, lumSrcPtr, vLumFilterSize,

                                       vChrFilter+dstY*vChrFilterSize, chrSrcPtr, vChrFilterSize,

                                       alpSrcPtr, dest, dstW, dstY);

                    }

                }

            }

        } else { // hmm looks like we can't use MMX here without overwriting this array's tail

            const int16_t **lumSrcPtr= (const int16_t **)lumPixBuf + lumBufIndex + firstLumSrcY - lastInLumBuf + vLumBufSize;

            const int16_t **chrSrcPtr= (const int16_t **)chrPixBuf + chrBufIndex + firstChrSrcY - lastInChrBuf + vChrBufSize;

            const int16_t **alpSrcPtr= (CONFIG_SWSCALE_ALPHA && alpPixBuf) ? (const int16_t **)alpPixBuf + lumBufIndex + firstLumSrcY - lastInLumBuf + vLumBufSize : NULL;

            if (dstFormat == PIX_FMT_NV12 || dstFormat == PIX_FMT_NV21) {

                const int chrSkipMask= (1<<c->chrDstVSubSample)-1;

                if (dstY&chrSkipMask) uDest= NULL; //FIXME split functions in lumi / chromi

                yuv2nv12XinC(

                             vLumFilter+dstY*vLumFilterSize   , lumSrcPtr, vLumFilterSize,

                             vChrFilter+chrDstY*vChrFilterSize, chrSrcPtr, vChrFilterSize,

                             dest, uDest, dstW, chrDstW, dstFormat);

            } else if (isPlanarYUV(dstFormat) || dstFormat==PIX_FMT_GRAY8) { //YV12

                const int chrSkipMask= (1<<c->chrDstVSubSample)-1;

                if ((dstY&chrSkipMask) || isGray(dstFormat)) uDest=vDest= NULL; //FIXME split functions in lumi / chromi

                if (is16BPS(dstFormat) || isNBPS(dstFormat)) {

                    yuv2yuvX16inC(

                                  vLumFilter+dstY*vLumFilterSize   , lumSrcPtr, vLumFilterSize,

                                  vChrFilter+chrDstY*vChrFilterSize, chrSrcPtr, vChrFilterSize,

                                  alpSrcPtr, (uint16_t *) dest, (uint16_t *) uDest, (uint16_t *) vDest, (uint16_t *) aDest, dstW, chrDstW,

                                  dstFormat);

                } else {

                    yuv2yuvXinC(

                                vLumFilter+dstY*vLumFilterSize   , lumSrcPtr, vLumFilterSize,

                                vChrFilter+chrDstY*vChrFilterSize, chrSrcPtr, vChrFilterSize,

                                alpSrcPtr, dest, uDest, vDest, aDest, dstW, chrDstW);

                }

            } else {

                assert(lumSrcPtr + vLumFilterSize - 1 < lumPixBuf + vLumBufSize*2);

                assert(chrSrcPtr + vChrFilterSize - 1 < chrPixBuf + vChrBufSize*2);

                if(flags & SWS_FULL_CHR_H_INT) {

                    yuv2rgbXinC_full(c,

                                     vLumFilter+dstY*vLumFilterSize, lumSrcPtr, vLumFilterSize,

                                     vChrFilter+dstY*vChrFilterSize, chrSrcPtr, vChrFilterSize,

                                     alpSrcPtr, dest, dstW, dstY);

                } else {

                    yuv2packedXinC(c,

                                   vLumFilter+dstY*vLumFilterSize, lumSrcPtr, vLumFilterSize,

                                   vChrFilter+dstY*vChrFilterSize, chrSrcPtr, vChrFilterSize,

                                   alpSrcPtr, dest, dstW, dstY);

                }

            }

        }

    }



    if ((dstFormat == PIX_FMT_YUVA420P) && !alpPixBuf)

        fillPlane(dst[3], dstStride[3], dstW, dstY-lastDstY, lastDstY, 255);



#if COMPILE_TEMPLATE_MMX

    if (flags & SWS_CPU_CAPS_MMX2 )  __asm__ volatile("sfence":::"memory");

    /* On K6 femms is faster than emms. On K7 femms is directly mapped to emms. */

    if (flags & SWS_CPU_CAPS_3DNOW)  __asm__ volatile("femms" :::"memory");

    else                             __asm__ volatile("emms"  :::"memory");

#endif

    /* store changed local vars back in the context */

    c->dstY= dstY;

    c->lumBufIndex= lumBufIndex;

    c->chrBufIndex= chrBufIndex;

    c->lastInLumBuf= lastInLumBuf;

    c->lastInChrBuf= lastInChrBuf;



    return dstY - lastDstY;

}

static inline int wv_unpack_mono(WavpackFrameContext *s, GetBitContext *gb,

                                 void *dst, const int type)

{

    int i, j, count = 0;

    int last, t;

    int A, S, T;

    int pos                  = s->pos;

    uint32_t crc             = s->sc.crc;

    uint32_t crc_extra_bits  = s->extra_sc.crc;

    int16_t *dst16           = dst;

    int32_t *dst32           = dst;

    float *dstfl             = dst;



    s->one = s->zero = s->zeroes = 0;

    do {

        T = wv_get_value(s, gb, 0, &last);

        S = 0;

        if (last)

            break;

        for (i = 0; i < s->terms; i++) {

            t = s->decorr[i].value;

            if (t > 8) {

                if (t & 1)

                    A =  2U * s->decorr[i].samplesA[0] - s->decorr[i].samplesA[1];

                else

                    A = (int)(3U * s->decorr[i].samplesA[0] - s->decorr[i].samplesA[1]) >> 1;

                s->decorr[i].samplesA[1] = s->decorr[i].samplesA[0];

                j                        = 0;

            } else {

                A = s->decorr[i].samplesA[pos];

                j = (pos + t) & 7;

            }

            if (type != AV_SAMPLE_FMT_S16P)

                S = T + ((s->decorr[i].weightA * (int64_t)A + 512) >> 10);

            else

                S = T + ((s->decorr[i].weightA * A + 512) >> 10);

            if (A && T)

                s->decorr[i].weightA -= ((((T ^ A) >> 30) & 2) - 1) * s->decorr[i].delta;

            s->decorr[i].samplesA[j] = T = S;

        }

        pos = (pos + 1) & 7;

        crc = crc * 3 + S;



        if (type == AV_SAMPLE_FMT_FLTP) {

            *dstfl++ = wv_get_value_float(s, &crc_extra_bits, S);

        } else if (type == AV_SAMPLE_FMT_S32P) {

            *dst32++ = wv_get_value_integer(s, &crc_extra_bits, S);

        } else {

            *dst16++ = wv_get_value_integer(s, &crc_extra_bits, S);

        }

        count++;

    } while (!last && count < s->samples);



    wv_reset_saved_context(s);



    if (last && count < s->samples) {

        int size = av_get_bytes_per_sample(type);

        memset((uint8_t*)dst + count*size, 0, (s->samples-count)*size);

    }



    if (s->avctx->err_recognition & AV_EF_CRCCHECK) {

        int ret = wv_check_crc(s, crc, crc_extra_bits);

        if (ret < 0 && s->avctx->err_recognition & AV_EF_EXPLODE)

            return ret;

    }



    return 0;

}

static void sample_queue_push(HintSampleQueue *queue, uint8_t *data, int size,

                              int sample)

{

    /* No need to keep track of smaller samples, since describing them

     * with immediates is more efficient. */

    if (size <= 14)

        return;

    if (!queue->samples || queue->len >= queue->size) {

        HintSample *samples;

        samples = av_realloc(queue->samples, sizeof(HintSample) * (queue->size + 10));

        if (!samples)

            return;

        queue->size += 10;

        queue->samples = samples;

    }

    queue->samples[queue->len].data = data;

    queue->samples[queue->len].size = size;

    queue->samples[queue->len].sample_number = sample;

    queue->samples[queue->len].offset   = 0;

    queue->samples[queue->len].own_data = 0;

    queue->len++;

}

static inline int mpeg4_decode_block(MpegEncContext * s, DCTELEM * block,

                              int n, int coded, int intra)

{

    int level, i, last, run;

    int dc_pred_dir;

    RLTable * rl;

    RL_VLC_ELEM * rl_vlc;

    const UINT8 * scan_table;

    int qmul, qadd;



    if(intra) {

	/* DC coef */

        if(s->partitioned_frame){

            level = s->dc_val[0][ s->block_index[n] ];

            if(n<4) level= (level + (s->y_dc_scale>>1))/s->y_dc_scale; //FIXME optimizs

            else    level= (level + (s->c_dc_scale>>1))/s->c_dc_scale;

            dc_pred_dir= (s->pred_dir_table[s->mb_x + s->mb_y*s->mb_width]<<n)&32;

        }else{

            level = mpeg4_decode_dc(s, n, &dc_pred_dir);

            if (level < 0)

                return -1;

        }

        block[0] = level;

        i = 0;

        if (!coded) 

            goto not_coded;

        rl = &rl_intra;

        rl_vlc = rl_intra.rl_vlc[0];

        if (s->ac_pred) {

            if (dc_pred_dir == 0) 

                scan_table = s->intra_v_scantable.permutated; /* left */

            else

                scan_table = s->intra_h_scantable.permutated; /* top */

        } else {

            scan_table = s->intra_scantable.permutated;

        }

        qmul=1;

        qadd=0;

    } else {

        i = -1;

        if (!coded) {

            s->block_last_index[n] = i;

            return 0;

        }

        rl = &rl_inter;



        scan_table = s->intra_scantable.permutated;



        if(s->mpeg_quant){

            qmul=1;

            qadd=0;

            rl_vlc = rl_inter.rl_vlc[0];        

        }else{

            qmul = s->qscale << 1;

            qadd = (s->qscale - 1) | 1;

            rl_vlc = rl_inter.rl_vlc[s->qscale];

        }

    }

  {

    OPEN_READER(re, &s->gb);

    for(;;) {

        UPDATE_CACHE(re, &s->gb);

        GET_RL_VLC(level, run, re, &s->gb, rl_vlc, TEX_VLC_BITS, 2);

        if (level==0) {

            int cache;

            cache= GET_CACHE(re, &s->gb);

            /* escape */

            if (cache&0x80000000) {

                if (cache&0x40000000) {

                    /* third escape */

                    SKIP_CACHE(re, &s->gb, 2);

                    last=  SHOW_UBITS(re, &s->gb, 1); SKIP_CACHE(re, &s->gb, 1);

                    run=   SHOW_UBITS(re, &s->gb, 6); LAST_SKIP_CACHE(re, &s->gb, 6);

                    SKIP_COUNTER(re, &s->gb, 2+1+6);

                    UPDATE_CACHE(re, &s->gb);



                    if(SHOW_UBITS(re, &s->gb, 1)==0){

                        fprintf(stderr, "1. marker bit missing in 3. esc\n");

                        return -1;

                    }; SKIP_CACHE(re, &s->gb, 1);



                    level= SHOW_SBITS(re, &s->gb, 12); SKIP_CACHE(re, &s->gb, 12);



                    if(SHOW_UBITS(re, &s->gb, 1)==0){

                        fprintf(stderr, "2. marker bit missing in 3. esc\n");

                        return -1;

                    }; LAST_SKIP_CACHE(re, &s->gb, 1);



                    SKIP_COUNTER(re, &s->gb, 1+12+1);



                    if(level*s->qscale>1024 || level*s->qscale<-1024){

                        fprintf(stderr, "|level| overflow in 3. esc, qp=%d\n", s->qscale);

                        return -1;

                    }

#if 1 

                    {

                        const int abs_level= ABS(level);

                        if(abs_level<=MAX_LEVEL && run<=MAX_RUN && ((s->workaround_bugs&FF_BUG_AC_VLC)==0)){

                            const int run1= run - rl->max_run[last][abs_level] - 1;

                            if(abs_level <= rl->max_level[last][run]){

                                fprintf(stderr, "illegal 3. esc, vlc encoding possible\n");

                                return -1;

                            }

                            if(abs_level <= rl->max_level[last][run]*2){

                                fprintf(stderr, "illegal 3. esc, esc 1 encoding possible\n");

                                return -1;

                            }

                            if(run1 >= 0 && abs_level <= rl->max_level[last][run1]){

                                fprintf(stderr, "illegal 3. esc, esc 2 encoding possible\n");

                                return -1;

                            }

                        }

                    }

#endif

		    if (level>0) level= level * qmul + qadd;

                    else         level= level * qmul - qadd;



                    i+= run + 1;

                    if(last) i+=192;

                } else {

                    /* second escape */

#if MIN_CACHE_BITS < 20

                    LAST_SKIP_BITS(re, &s->gb, 2);

                    UPDATE_CACHE(re, &s->gb);

#else

                    SKIP_BITS(re, &s->gb, 2);

#endif

                    GET_RL_VLC(level, run, re, &s->gb, rl_vlc, TEX_VLC_BITS, 2);

                    i+= run + rl->max_run[run>>7][level/qmul] +1; //FIXME opt indexing

                    level = (level ^ SHOW_SBITS(re, &s->gb, 1)) - SHOW_SBITS(re, &s->gb, 1);

                    LAST_SKIP_BITS(re, &s->gb, 1);

                }

            } else {

                /* first escape */

#if MIN_CACHE_BITS < 19

                LAST_SKIP_BITS(re, &s->gb, 1);

                UPDATE_CACHE(re, &s->gb);

#else

                SKIP_BITS(re, &s->gb, 1);

#endif

                GET_RL_VLC(level, run, re, &s->gb, rl_vlc, TEX_VLC_BITS, 2);

                i+= run;

                level = level + rl->max_level[run>>7][(run-1)&63] * qmul;//FIXME opt indexing

                level = (level ^ SHOW_SBITS(re, &s->gb, 1)) - SHOW_SBITS(re, &s->gb, 1);

                LAST_SKIP_BITS(re, &s->gb, 1);

            }

        } else {

            i+= run;

            level = (level ^ SHOW_SBITS(re, &s->gb, 1)) - SHOW_SBITS(re, &s->gb, 1);

            LAST_SKIP_BITS(re, &s->gb, 1);

        }

        if (i > 62){

            i-= 192;

            if(i&(~63)){

                fprintf(stderr, "ac-tex damaged at %d %d\n", s->mb_x, s->mb_y);

                return -1;

            }



            block[scan_table[i]] = level;

            break;

        }



        block[scan_table[i]] = level;

    }

    CLOSE_READER(re, &s->gb);

  }

 not_coded:

    if (s->mb_intra) {

        mpeg4_pred_ac(s, block, n, dc_pred_dir);

        if (s->ac_pred) {

            i = 63; /* XXX: not optimal */

        }

    }

    s->block_last_index[n] = i;

    return 0;

}

static int parse_vtrk(AVFormatContext *s,

                      FourxmDemuxContext *fourxm, uint8_t *buf, int size)

{

    AVStream *st;

    /* check that there is enough data */

    if (size != vtrk_SIZE) {

        return AVERROR_INVALIDDATA;

    }



    /* allocate a new AVStream */

    st = avformat_new_stream(s, NULL);

    if (!st)

        return AVERROR(ENOMEM);



    avpriv_set_pts_info(st, 60, 1, fourxm->fps);



    fourxm->video_stream_index = st->index;



    st->codec->codec_type     = AVMEDIA_TYPE_VIDEO;

    st->codec->codec_id       = AV_CODEC_ID_4XM;

    st->codec->extradata_size = 4;

    st->codec->extradata      = av_malloc(4);

    AV_WL32(st->codec->extradata, AV_RL32(buf + 16));

    st->codec->width  = AV_RL32(buf + 36);

    st->codec->height = AV_RL32(buf + 40);



    return 0;

}

int ff_mpeg4audio_get_config(MPEG4AudioConfig *c, const uint8_t *buf, int buf_size)

{

    GetBitContext gb;

    int specific_config_bitindex;



    init_get_bits(&gb, buf, buf_size*8);

    c->object_type = get_object_type(&gb);

    c->sample_rate = get_sample_rate(&gb, &c->sampling_index);

    c->chan_config = get_bits(&gb, 4);

    if (c->chan_config < FF_ARRAY_ELEMS(ff_mpeg4audio_channels))

        c->channels = ff_mpeg4audio_channels[c->chan_config];

    c->sbr = -1;

    if (c->object_type == AOT_SBR || (c->object_type == AOT_PS &&

        // check for W6132 Annex YYYY draft MP3onMP4

        !(show_bits(&gb, 3) & 0x03 && !(show_bits(&gb, 9) & 0x3F)))) {

        c->ext_object_type = AOT_SBR;

        c->sbr = 1;

        c->ext_sample_rate = get_sample_rate(&gb, &c->ext_sampling_index);

        c->object_type = get_object_type(&gb);

        if (c->object_type == AOT_ER_BSAC)

            c->ext_chan_config = get_bits(&gb, 4);

    } else {

        c->ext_object_type = AOT_NULL;

        c->ext_sample_rate = 0;

    }

    specific_config_bitindex = get_bits_count(&gb);



    if (c->object_type == AOT_ALS) {

        skip_bits(&gb, 5);

        if (show_bits_long(&gb, 24) != MKBETAG('\0','A','L','S'))

            skip_bits_long(&gb, 24);



        specific_config_bitindex = get_bits_count(&gb);



        if (parse_config_ALS(&gb, c))

            return -1;

    }



    if (c->ext_object_type != AOT_SBR) {

        int bits_left = buf_size*8 - get_bits_count(&gb);

        for (; bits_left > 15; bits_left--) {

            if (show_bits(&gb, 11) == 0x2b7) { // sync extension

                get_bits(&gb, 11);

                c->ext_object_type = get_object_type(&gb);

                if (c->ext_object_type == AOT_SBR && (c->sbr = get_bits1(&gb)) == 1)

                    c->ext_sample_rate = get_sample_rate(&gb, &c->ext_sampling_index);

                break;

            } else

                get_bits1(&gb); // skip 1 bit

        }

    }

    return specific_config_bitindex;

}

void ff_hevc_luma_mv_mvp_mode(HEVCContext *s, int x0, int y0, int nPbW,

                              int nPbH, int log2_cb_size, int part_idx,

                              int merge_idx, MvField *mv,

                              int mvp_lx_flag, int LX)

{

    HEVCLocalContext *lc = s->HEVClc;

    MvField *tab_mvf = s->ref->tab_mvf;

    int isScaledFlag_L0 = 0;

    int availableFlagLXA0 = 1;

    int availableFlagLXB0 = 1;

    int numMVPCandLX = 0;

    int min_pu_width = s->sps->min_pu_width;



    int xA0, yA0;

    int is_available_a0;

    int xA1, yA1;

    int is_available_a1;

    int xB0, yB0;

    int is_available_b0;

    int xB1, yB1;

    int is_available_b1;

    int xB2, yB2;

    int is_available_b2;



    Mv mvpcand_list[2] = { { 0 } };

    Mv mxA;

    Mv mxB;

    int ref_idx_curr = 0;

    int ref_idx = 0;

    int pred_flag_index_l0;

    int pred_flag_index_l1;



    const int cand_bottom_left = lc->na.cand_bottom_left;

    const int cand_left        = lc->na.cand_left;

    const int cand_up_left     = lc->na.cand_up_left;

    const int cand_up          = lc->na.cand_up;

    const int cand_up_right    = lc->na.cand_up_right_sap;

    ref_idx_curr       = LX;

    ref_idx            = mv->ref_idx[LX];

    pred_flag_index_l0 = LX;

    pred_flag_index_l1 = !LX;



    // left bottom spatial candidate

    xA0 = x0 - 1;

    yA0 = y0 + nPbH;



    is_available_a0 = AVAILABLE(cand_bottom_left, A0) &&

                      yA0 < s->sps->height &&

                      PRED_BLOCK_AVAILABLE(A0);



    //left spatial merge candidate

    xA1    = x0 - 1;

    yA1    = y0 + nPbH - 1;



    is_available_a1 = AVAILABLE(cand_left, A1);

    if (is_available_a0 || is_available_a1)

        isScaledFlag_L0 = 1;



    if (is_available_a0) {

        if (MP_MX(A0, pred_flag_index_l0, mxA)) {

            goto b_candidates;

        }

        if (MP_MX(A0, pred_flag_index_l1, mxA)) {

            goto b_candidates;

        }

    }



    if (is_available_a1) {

        if (MP_MX(A1, pred_flag_index_l0, mxA)) {

            goto b_candidates;

        }

        if (MP_MX(A1, pred_flag_index_l1, mxA)) {

            goto b_candidates;

        }

    }



    if (is_available_a0) {

        if (MP_MX_LT(A0, pred_flag_index_l0, mxA)) {

            goto b_candidates;

        }

        if (MP_MX_LT(A0, pred_flag_index_l1, mxA)) {

            goto b_candidates;

        }

    }



    if (is_available_a1) {

        if (MP_MX_LT(A1, pred_flag_index_l0, mxA)) {

            goto b_candidates;

        }

        if (MP_MX_LT(A1, pred_flag_index_l1, mxA)) {

            goto b_candidates;

        }

    }

    availableFlagLXA0 = 0;



b_candidates:

    // B candidates

    // above right spatial merge candidate

    xB0    = x0 + nPbW;

    yB0    = y0 - 1;



    is_available_b0 =  AVAILABLE(cand_up_right, B0) &&

                       xB0 < s->sps->width &&

                       PRED_BLOCK_AVAILABLE(B0);



    // above spatial merge candidate

    xB1    = x0 + nPbW - 1;

    yB1    = y0 - 1;

    is_available_b1 = AVAILABLE(cand_up, B1);



    // above left spatial merge candidate

    xB2 = x0 - 1;

    yB2 = y0 - 1;

    is_available_b2 = AVAILABLE(cand_up_left, B2);



    // above right spatial merge candidate

    if (is_available_b0) {

        if (MP_MX(B0, pred_flag_index_l0, mxB)) {

            goto scalef;

        }

        if (MP_MX(B0, pred_flag_index_l1, mxB)) {

            goto scalef;

        }

    }



    // above spatial merge candidate

    if (is_available_b1) {

        if (MP_MX(B1, pred_flag_index_l0, mxB)) {

            goto scalef;

        }

        if (MP_MX(B1, pred_flag_index_l1, mxB)) {

            goto scalef;

        }

    }



    // above left spatial merge candidate

    if (is_available_b2) {

        if (MP_MX(B2, pred_flag_index_l0, mxB)) {

            goto scalef;

        }

        if (MP_MX(B2, pred_flag_index_l1, mxB)) {

            goto scalef;

        }

    }

    availableFlagLXB0 = 0;



scalef:

    if (!isScaledFlag_L0) {

        if (availableFlagLXB0) {

            availableFlagLXA0 = 1;

            mxA = mxB;

        }

        availableFlagLXB0 = 0;



        // XB0 and L1

        if (is_available_b0) {

            availableFlagLXB0 = MP_MX_LT(B0, pred_flag_index_l0, mxB);

            if (!availableFlagLXB0)

                availableFlagLXB0 = MP_MX_LT(B0, pred_flag_index_l1, mxB);

        }



        if (is_available_b1 && !availableFlagLXB0) {

            availableFlagLXB0 = MP_MX_LT(B1, pred_flag_index_l0, mxB);

            if (!availableFlagLXB0)

                availableFlagLXB0 = MP_MX_LT(B1, pred_flag_index_l1, mxB);

        }



        if (is_available_b2 && !availableFlagLXB0) {

            availableFlagLXB0 = MP_MX_LT(B2, pred_flag_index_l0, mxB);

            if (!availableFlagLXB0)

                availableFlagLXB0 = MP_MX_LT(B2, pred_flag_index_l1, mxB);

        }

    }



    if (availableFlagLXA0)

        mvpcand_list[numMVPCandLX++] = mxA;



    if (availableFlagLXB0 && (!availableFlagLXA0 || mxA.x != mxB.x || mxA.y != mxB.y))

        mvpcand_list[numMVPCandLX++] = mxB;



    //temporal motion vector prediction candidate

    if (numMVPCandLX < 2 && s->sh.slice_temporal_mvp_enabled_flag &&

        mvp_lx_flag == numMVPCandLX) {

        Mv mv_col;

        int available_col = temporal_luma_motion_vector(s, x0, y0, nPbW,

                                                        nPbH, ref_idx,

                                                        &mv_col, LX);

        if (available_col)

            mvpcand_list[numMVPCandLX++] = mv_col;

    }



    mv->mv[LX] = mvpcand_list[mvp_lx_flag];

}

static int vc1_decode_intra_block(VC1Context *v, DCTELEM block[64], int n, int coded, int mquant, int codingset)

{

    GetBitContext *gb = &v->s.gb;

    MpegEncContext *s = &v->s;

    int dc_pred_dir = 0; /* Direction of the DC prediction used */

    int run_diff, i;

    int16_t *dc_val;

    int16_t *ac_val, *ac_val2;

    int dcdiff;

    int mb_pos = s->mb_x + s->mb_y * s->mb_stride;

    int a_avail = v->a_avail, c_avail = v->c_avail;

    int use_pred = s->ac_pred;

    int scale;

    int q1, q2 = 0;



    /* XXX: Guard against dumb values of mquant */

    mquant = (mquant < 1) ? 0 : ( (mquant>31) ? 31 : mquant );



    /* Set DC scale - y and c use the same */

    s->y_dc_scale = s->y_dc_scale_table[mquant];

    s->c_dc_scale = s->c_dc_scale_table[mquant];



    /* Get DC differential */

    if (n < 4) {

        dcdiff = get_vlc2(&s->gb, ff_msmp4_dc_luma_vlc[s->dc_table_index].table, DC_VLC_BITS, 3);

    } else {

        dcdiff = get_vlc2(&s->gb, ff_msmp4_dc_chroma_vlc[s->dc_table_index].table, DC_VLC_BITS, 3);

    }

    if (dcdiff < 0){

        av_log(s->avctx, AV_LOG_ERROR, "Illegal DC VLC\n");

        return -1;

    }

    if (dcdiff)

    {

        if (dcdiff == 119 /* ESC index value */)

        {

            /* TODO: Optimize */

            if (mquant == 1) dcdiff = get_bits(gb, 10);

            else if (mquant == 2) dcdiff = get_bits(gb, 9);

            else dcdiff = get_bits(gb, 8);

        }

        else

        {

            if (mquant == 1)

                dcdiff = (dcdiff<<2) + get_bits(gb, 2) - 3;

            else if (mquant == 2)

                dcdiff = (dcdiff<<1) + get_bits(gb, 1) - 1;

        }

        if (get_bits(gb, 1))

            dcdiff = -dcdiff;

    }



    /* Prediction */

    dcdiff += vc1_pred_dc(&v->s, v->overlap, mquant, n, a_avail, c_avail, &dc_val, &dc_pred_dir);

    *dc_val = dcdiff;



    /* Store the quantized DC coeff, used for prediction */



    if (n < 4) {

        block[0] = dcdiff * s->y_dc_scale;

    } else {

        block[0] = dcdiff * s->c_dc_scale;

    }

    /* Skip ? */

    run_diff = 0;

    i = 0;



    //AC Decoding

    i = 1;



    /* check if AC is needed at all and adjust direction if needed */

    if(!a_avail) dc_pred_dir = 1;

    if(!c_avail) dc_pred_dir = 0;

    if(!a_avail && !c_avail) use_pred = 0;

    ac_val = s->ac_val[0][0] + s->block_index[n] * 16;

    ac_val2 = ac_val;



    scale = mquant * 2 + v->halfpq;



    if(dc_pred_dir) //left

        ac_val -= 16;

    else //top

        ac_val -= 16 * s->block_wrap[n];



    q1 = s->current_picture.qscale_table[mb_pos];

    if(dc_pred_dir && c_avail) q2 = s->current_picture.qscale_table[mb_pos - 1];

    if(!dc_pred_dir && a_avail) q2 = s->current_picture.qscale_table[mb_pos - s->mb_stride];

    if(n && n<4) q2 = q1;



    if(coded) {

        int last = 0, skip, value;

        const int8_t *zz_table;

        int k;



        zz_table = vc1_simple_progressive_8x8_zz;



        while (!last) {

            vc1_decode_ac_coeff(v, &last, &skip, &value, codingset);

            i += skip;

            if(i > 63)

                break;

            block[zz_table[i++]] = value;

        }



        /* apply AC prediction if needed */

        if(use_pred) {

            /* scale predictors if needed*/

            if(q2 && q1!=q2) {

                q1 = q1 * 2 + ((q1 == v->pq) ? v->halfpq : 0) - 1;

                q2 = q2 * 2 + ((q2 == v->pq) ? v->halfpq : 0) - 1;



                if(dc_pred_dir) { //left

                    for(k = 1; k < 8; k++)

                        block[k << 3] += (ac_val[k] * q2 * vc1_dqscale[q1 - 1] + 0x20000) >> 18;

                } else { //top

                    for(k = 1; k < 8; k++)

                        block[k] += (ac_val[k + 8] * q2 * vc1_dqscale[q1 - 1] + 0x20000) >> 18;

                }

            } else {

                if(dc_pred_dir) { //left

                    for(k = 1; k < 8; k++)

                        block[k << 3] += ac_val[k];

                } else { //top

                    for(k = 1; k < 8; k++)

                        block[k] += ac_val[k + 8];

                }

            }

        }

        /* save AC coeffs for further prediction */

        for(k = 1; k < 8; k++) {

            ac_val2[k] = block[k << 3];

            ac_val2[k + 8] = block[k];

        }



        /* scale AC coeffs */

        for(k = 1; k < 64; k++)

            if(block[k]) {

                block[k] *= scale;

                if(!v->pquantizer)

                    block[k] += (block[k] < 0) ? -mquant : mquant;

            }



        if(use_pred) i = 63;

    } else { // no AC coeffs

        int k;



        memset(ac_val2, 0, 16 * 2);

        if(dc_pred_dir) {//left

            if(use_pred) {

                memcpy(ac_val2, ac_val, 8 * 2);

                if(q2 && q1!=q2) {

                    q1 = q1 * 2 + ((q1 == v->pq) ? v->halfpq : 0) - 1;

                    q2 = q2 * 2 + ((q2 == v->pq) ? v->halfpq : 0) - 1;

                    for(k = 1; k < 8; k++)

                        ac_val2[k] = (ac_val2[k] * q2 * vc1_dqscale[q1 - 1] + 0x20000) >> 18;

                }

            }

        } else {//top

            if(use_pred) {

                memcpy(ac_val2 + 8, ac_val + 8, 8 * 2);

                if(q2 && q1!=q2) {

                    q1 = q1 * 2 + ((q1 == v->pq) ? v->halfpq : 0) - 1;

                    q2 = q2 * 2 + ((q2 == v->pq) ? v->halfpq : 0) - 1;

                    for(k = 1; k < 8; k++)

                        ac_val2[k + 8] = (ac_val2[k + 8] * q2 * vc1_dqscale[q1 - 1] + 0x20000) >> 18;

                }

            }

        }



        /* apply AC prediction if needed */

        if(use_pred) {

            if(dc_pred_dir) { //left

                for(k = 1; k < 8; k++) {

                    block[k << 3] = ac_val2[k] * scale;

                    if(!v->pquantizer && block[k << 3])

                        block[k << 3] += (block[k << 3] < 0) ? -mquant : mquant;

                }

            } else { //top

                for(k = 1; k < 8; k++) {

                    block[k] = ac_val2[k + 8] * scale;

                    if(!v->pquantizer && block[k])

                        block[k] += (block[k] < 0) ? -mquant : mquant;

                }

            }

            i = 63;

        }

    }

    s->block_last_index[n] = i;



    return 0;

}

static int can_safely_read(GetBitContext* gb, uint64_t bits) {

    return get_bits_left(gb) >= bits;

}

static int tta_probe(AVProbeData *p)

{

    const uint8_t *d = p->buf;

    if (p->buf_size < 4)

        return 0;

    if (d[0] == 'T' && d[1] == 'T' && d[2] == 'A' && d[3] == '1')

        return 80;

    return 0;

}

static void list_formats(AVFormatContext *ctx, int type)

{

    const struct video_data *s = ctx->priv_data;

    struct v4l2_fmtdesc vfd = { .type = V4L2_BUF_TYPE_VIDEO_CAPTURE };



    while(!v4l2_ioctl(s->fd, VIDIOC_ENUM_FMT, &vfd)) {

        enum AVCodecID codec_id = avpriv_fmt_v4l2codec(vfd.pixelformat);

        enum AVPixelFormat pix_fmt = avpriv_fmt_v4l2ff(vfd.pixelformat, codec_id);



        vfd.index++;



        if (!(vfd.flags & V4L2_FMT_FLAG_COMPRESSED) &&

            type & V4L_RAWFORMATS) {

            const char *fmt_name = av_get_pix_fmt_name(pix_fmt);

            av_log(ctx, AV_LOG_INFO, "Raw       : %9s : %20s :",

                   fmt_name ? fmt_name : "Unsupported",

                   vfd.description);

        } else if (vfd.flags & V4L2_FMT_FLAG_COMPRESSED &&

                   type & V4L_COMPFORMATS) {

            AVCodec *codec = avcodec_find_decoder(codec_id);

            av_log(ctx, AV_LOG_INFO, "Compressed: %9s : %20s :",

                   codec ? codec->name : "Unsupported",

                   vfd.description);

        } else {

            continue;

        }



#ifdef V4L2_FMT_FLAG_EMULATED

        if (vfd.flags & V4L2_FMT_FLAG_EMULATED)

            av_log(ctx, AV_LOG_INFO, " Emulated :");

#endif

#if HAVE_STRUCT_V4L2_FRMIVALENUM_DISCRETE

        list_framesizes(ctx, vfd.pixelformat);

#endif

        av_log(ctx, AV_LOG_INFO, "\n");

    }

}

static int cinepak_decode_strip (CinepakContext *s,

                                 cvid_strip *strip, const uint8_t *data, int size)

{

    const uint8_t *eod = (data + size);

    int      chunk_id, chunk_size;



    /* coordinate sanity checks */

    if (strip->x1 >= s->width  || strip->x2 > s->width  ||

        strip->y1 >= s->height || strip->y2 > s->height ||

        strip->x1 >= strip->x2 || strip->y1 >= strip->y2)

        return -1;



    while ((data + 4) <= eod) {

        chunk_id   = data[0];

        chunk_size = AV_RB24 (&data[1]) - 4;

        if(chunk_size < 0)

            return -1;



        data      += 4;

        chunk_size = ((data + chunk_size) > eod) ? (eod - data) : chunk_size;



        switch (chunk_id) {



        case 0x20:

        case 0x21:

        case 0x24:

        case 0x25:

            cinepak_decode_codebook (strip->v4_codebook, chunk_id,

                chunk_size, data);

            break;



        case 0x22:

        case 0x23:

        case 0x26:

        case 0x27:

            cinepak_decode_codebook (strip->v1_codebook, chunk_id,

                chunk_size, data);

            break;



        case 0x30:

        case 0x31:

        case 0x32:

            return cinepak_decode_vectors (s, strip, chunk_id,

                chunk_size, data);

        }



        data += chunk_size;

    }



    return -1;

}

static int ast_write_header(AVFormatContext *s)

{

    ASTMuxContext *ast = s->priv_data;

    AVIOContext *pb = s->pb;

    AVCodecContext *enc;

    unsigned int codec_tag;



    if (s->nb_streams == 1) {

        enc = s->streams[0]->codec;

    } else {

        av_log(s, AV_LOG_ERROR, "only one stream is supported\n");

        return AVERROR(EINVAL);

    }



    if (enc->codec_id == AV_CODEC_ID_ADPCM_AFC) {

        av_log(s, AV_LOG_ERROR, "muxing ADPCM AFC is not implemented\n");

        return AVERROR_PATCHWELCOME;

    }



    codec_tag = ff_codec_get_tag(ff_codec_ast_tags, enc->codec_id);

    if (!codec_tag) {

        av_log(s, AV_LOG_ERROR, "unsupported codec\n");

        return AVERROR(EINVAL);

    }



    if (ast->loopstart && ast->loopend && ast->loopstart >= ast->loopend) {

        av_log(s, AV_LOG_ERROR, "loopend can't be less or equal to loopstart\n");

        return AVERROR(EINVAL);

    }



    /* Convert milliseconds to samples */

    CHECK_LOOP(start)

    CHECK_LOOP(end)



    ffio_wfourcc(pb, "STRM");



    ast->size = avio_tell(pb);

    avio_wb32(pb, 0); /* File size minus header */

    avio_wb16(pb, codec_tag);

    avio_wb16(pb, 16); /* Bit depth */

    avio_wb16(pb, enc->channels);

    avio_wb16(pb, 0xFFFF);

    avio_wb32(pb, enc->sample_rate);



    ast->samples = avio_tell(pb);

    avio_wb32(pb, 0); /* Number of samples */

    avio_wb32(pb, 0); /* Loopstart */

    avio_wb32(pb, 0); /* Loopend */

    avio_wb32(pb, 0); /* Size of first block */



    /* Unknown */

    avio_wb32(pb, 0);

    avio_wl32(pb, 0x7F);

    avio_wb64(pb, 0);

    avio_wb64(pb, 0);

    avio_wb32(pb, 0);



    avio_flush(pb);



    return 0;

}

static int read_old_huffman_tables(HYuvContext *s)

{

    GetBitContext gb;

    int i;



    init_get_bits(&gb, classic_shift_luma,

                  classic_shift_luma_table_size * 8);

    if (read_len_table(s->len[0], &gb) < 0)

        return -1;



    init_get_bits(&gb, classic_shift_chroma,

                  classic_shift_chroma_table_size * 8);

    if (read_len_table(s->len[1], &gb) < 0)

        return -1;



    for(i=0; i<256; i++) s->bits[0][i] = classic_add_luma  [i];

    for(i=0; i<256; i++) s->bits[1][i] = classic_add_chroma[i];



    if (s->bitstream_bpp >= 24) {

        memcpy(s->bits[1], s->bits[0], 256 * sizeof(uint32_t));

        memcpy(s->len[1] , s->len [0], 256 * sizeof(uint8_t));

    }

    memcpy(s->bits[2], s->bits[1], 256 * sizeof(uint32_t));

    memcpy(s->len[2] , s->len [1], 256 * sizeof(uint8_t));



    for (i = 0; i < 3; i++) {

        ff_free_vlc(&s->vlc[i]);

        init_vlc(&s->vlc[i], VLC_BITS, 256, s->len[i], 1, 1,

                 s->bits[i], 4, 4, 0);

    }



    generate_joint_tables(s);



    return 0;

}

static int decode_ics_info(AACContext *ac, IndividualChannelStream *ics,

                           GetBitContext *gb)

{

    const MPEG4AudioConfig *const m4ac = &ac->oc[1].m4ac;

    const int aot = m4ac->object_type;

    const int sampling_index = m4ac->sampling_index;

    if (aot != AOT_ER_AAC_ELD) {

        if (get_bits1(gb)) {

            av_log(ac->avctx, AV_LOG_ERROR, "Reserved bit set.\n");

            return AVERROR_INVALIDDATA;

        }

        ics->window_sequence[1] = ics->window_sequence[0];

        ics->window_sequence[0] = get_bits(gb, 2);

        if (aot == AOT_ER_AAC_LD &&

            ics->window_sequence[0] != ONLY_LONG_SEQUENCE) {

            av_log(ac->avctx, AV_LOG_ERROR,

                   "AAC LD is only defined for ONLY_LONG_SEQUENCE but "

                   "window sequence %d found.\n", ics->window_sequence[0]);

            ics->window_sequence[0] = ONLY_LONG_SEQUENCE;

            return AVERROR_INVALIDDATA;

        }

        ics->use_kb_window[1]   = ics->use_kb_window[0];

        ics->use_kb_window[0]   = get_bits1(gb);

    }

    ics->num_window_groups  = 1;

    ics->group_len[0]       = 1;

    if (ics->window_sequence[0] == EIGHT_SHORT_SEQUENCE) {

        int i;

        ics->max_sfb = get_bits(gb, 4);

        for (i = 0; i < 7; i++) {

            if (get_bits1(gb)) {

                ics->group_len[ics->num_window_groups - 1]++;

            } else {

                ics->num_window_groups++;

                ics->group_len[ics->num_window_groups - 1] = 1;

            }

        }

        ics->num_windows       = 8;

        ics->swb_offset        =    ff_swb_offset_128[sampling_index];

        ics->num_swb           =   ff_aac_num_swb_128[sampling_index];

        ics->tns_max_bands     = ff_tns_max_bands_128[sampling_index];

        ics->predictor_present = 0;

    } else {

        ics->max_sfb           = get_bits(gb, 6);

        ics->num_windows       = 1;

        if (aot == AOT_ER_AAC_LD || aot == AOT_ER_AAC_ELD) {

            if (m4ac->frame_length_short) {

                ics->swb_offset    =     ff_swb_offset_480[sampling_index];

                ics->num_swb       =    ff_aac_num_swb_480[sampling_index];

                ics->tns_max_bands =  ff_tns_max_bands_480[sampling_index];

            } else {

                ics->swb_offset    =     ff_swb_offset_512[sampling_index];

                ics->num_swb       =    ff_aac_num_swb_512[sampling_index];

                ics->tns_max_bands =  ff_tns_max_bands_512[sampling_index];

            }

            if (!ics->num_swb || !ics->swb_offset)

                return AVERROR_BUG;

        } else {

            ics->swb_offset    =    ff_swb_offset_1024[sampling_index];

            ics->num_swb       =   ff_aac_num_swb_1024[sampling_index];

            ics->tns_max_bands = ff_tns_max_bands_1024[sampling_index];

        }

        if (aot != AOT_ER_AAC_ELD) {

            ics->predictor_present     = get_bits1(gb);

            ics->predictor_reset_group = 0;

        }

        if (ics->predictor_present) {

            if (aot == AOT_AAC_MAIN) {

                if (decode_prediction(ac, ics, gb)) {

                    return AVERROR_INVALIDDATA;

                }

            } else if (aot == AOT_AAC_LC ||

                       aot == AOT_ER_AAC_LC) {

                av_log(ac->avctx, AV_LOG_ERROR,

                       "Prediction is not allowed in AAC-LC.\n");

                return AVERROR_INVALIDDATA;

            } else {

                if (aot == AOT_ER_AAC_LD) {

                    av_log(ac->avctx, AV_LOG_ERROR,

                           "LTP in ER AAC LD not yet implemented.\n");

                    return AVERROR_PATCHWELCOME;

                }

                if ((ics->ltp.present = get_bits(gb, 1)))

                    decode_ltp(&ics->ltp, gb, ics->max_sfb);

            }

        }

    }



    if (ics->max_sfb > ics->num_swb) {

        av_log(ac->avctx, AV_LOG_ERROR,

               "Number of scalefactor bands in group (%d) "

               "exceeds limit (%d).\n",

               ics->max_sfb, ics->num_swb);

        return AVERROR_INVALIDDATA;

    }



    return 0;

}

static void dvbsub_parse_region_segment(AVCodecContext *avctx,

                                        uint8_t *buf, int buf_size)

{

    DVBSubContext *ctx = (DVBSubContext*) avctx->priv_data;



    uint8_t *buf_end = buf + buf_size;

    int region_id, object_id;

    DVBSubRegion *region;

    DVBSubObject *object;

    DVBSubObjectDisplay *display;

    int fill;



    if (buf_size < 10)

        return;



    region_id = *buf++;



    region = get_region(ctx, region_id);



    if (region == NULL)

    {

        region = av_mallocz(sizeof(DVBSubRegion));



        region->id = region_id;



        region->next = ctx->region_list;

        ctx->region_list = region;




    fill = ((*buf++) >> 3) & 1;



    region->width = AV_RB16(buf);

    buf += 2;

    region->height = AV_RB16(buf);

    buf += 2;



    if (region->width * region->height != region->buf_size) {

        if (region->pbuf != 0)

            av_free(region->pbuf);



        region->buf_size = region->width * region->height;



        region->pbuf = av_malloc(region->buf_size);



        fill = 1;




    region->depth = 1 << (((*buf++) >> 2) & 7);





    region->clut = *buf++;



    if (region->depth == 8)

        region->bgcolour = *buf++;

    else {

        buf += 1;



        if (region->depth == 4)

            region->bgcolour = (((*buf++) >> 4) & 15);

        else

            region->bgcolour = (((*buf++) >> 2) & 3);




#ifdef DEBUG

    av_log(avctx, AV_LOG_INFO, "Region %d, (%dx%d)\n", region_id, region->width, region->height);

#endif



    if (fill) {

        memset(region->pbuf, region->bgcolour, region->buf_size);

#ifdef DEBUG

        av_log(avctx, AV_LOG_INFO, "Fill region (%d)\n", region->bgcolour);

#endif




    delete_region_display_list(ctx, region);



    while (buf + 5 < buf_end) {

        object_id = AV_RB16(buf);

        buf += 2;



        object = get_object(ctx, object_id);



        if (object == NULL) {

            object = av_mallocz(sizeof(DVBSubObject));



            object->id = object_id;

            object->next = ctx->object_list;

            ctx->object_list = object;




        object->type = (*buf) >> 6;



        display = av_mallocz(sizeof(DVBSubObjectDisplay));



        display->object_id = object_id;

        display->region_id = region_id;



        display->x_pos = AV_RB16(buf) & 0xfff;

        buf += 2;

        display->y_pos = AV_RB16(buf) & 0xfff;

        buf += 2;



        if ((object->type == 1 || object->type == 2) && buf+1 < buf_end) {

            display->fgcolour = *buf++;

            display->bgcolour = *buf++;




        display->region_list_next = region->display_list;

        region->display_list = display;



        display->object_list_next = object->display_list;

        object->display_list = display;

int ff_unlock_avcodec(const AVCodec *codec)

{

    if (codec->caps_internal & FF_CODEC_CAP_INIT_THREADSAFE || !codec->init)

        return 0;



    av_assert0(ff_avcodec_locked);

    ff_avcodec_locked = 0;

    atomic_fetch_add(&entangled_thread_counter, -1);

    if (lockmgr_cb) {

        if ((*lockmgr_cb)(&codec_mutex, AV_LOCK_RELEASE))

            return -1;

    }



    return 0;

}

static inline void copy(LZOContext *c, int cnt)

{

    register const uint8_t *src = c->in;

    register uint8_t *dst       = c->out;


    if (cnt > c->in_end - src) {

        cnt       = FFMAX(c->in_end - src, 0);

        c->error |= AV_LZO_INPUT_DEPLETED;

    }

    if (cnt > c->out_end - dst) {

        cnt       = FFMAX(c->out_end - dst, 0);

        c->error |= AV_LZO_OUTPUT_FULL;

    }

#if defined(INBUF_PADDED) && defined(OUTBUF_PADDED)

    AV_COPY32U(dst, src);

    src += 4;

    dst += 4;

    cnt -= 4;

    if (cnt > 0)

#endif

    memcpy(dst, src, cnt);

    c->in  = src + cnt;

    c->out = dst + cnt;

}

static int mxf_read_generic_descriptor(void *arg, AVIOContext *pb, int tag, int size, UID uid)

{

    MXFDescriptor *descriptor = arg;

    switch(tag) {

    case 0x3F01:

        descriptor->sub_descriptors_count = avio_rb32(pb);

        if (descriptor->sub_descriptors_count >= UINT_MAX / sizeof(UID))

            return -1;

        descriptor->sub_descriptors_refs = av_malloc(descriptor->sub_descriptors_count * sizeof(UID));

        if (!descriptor->sub_descriptors_refs)

            return -1;

        avio_skip(pb, 4); /* useless size of objects, always 16 according to specs */

        avio_read(pb, (uint8_t *)descriptor->sub_descriptors_refs, descriptor->sub_descriptors_count * sizeof(UID));

        break;

    case 0x3004:

        avio_read(pb, descriptor->essence_container_ul, 16);

        break;

    case 0x3006:

        descriptor->linked_track_id = avio_rb32(pb);

        break;

    case 0x3201: /* PictureEssenceCoding */

        avio_read(pb, descriptor->essence_codec_ul, 16);

        break;

    case 0x3203:

        descriptor->width = avio_rb32(pb);

        break;

    case 0x3202:

        descriptor->height = avio_rb32(pb);

        break;

    case 0x320E:

        descriptor->aspect_ratio.num = avio_rb32(pb);

        descriptor->aspect_ratio.den = avio_rb32(pb);

        break;

    case 0x3D03:

        descriptor->sample_rate.num = avio_rb32(pb);

        descriptor->sample_rate.den = avio_rb32(pb);

        break;

    case 0x3D06: /* SoundEssenceCompression */

        avio_read(pb, descriptor->essence_codec_ul, 16);

        break;

    case 0x3D07:

        descriptor->channels = avio_rb32(pb);

        break;

    case 0x3D01:

        descriptor->bits_per_sample = avio_rb32(pb);

        break;

    case 0x3401:

        mxf_read_pixel_layout(pb, descriptor);

        break;

    default:

        /* Private uid used by SONY C0023S01.mxf */

        if (IS_KLV_KEY(uid, mxf_sony_mpeg4_extradata)) {

            descriptor->extradata = av_malloc(size + FF_INPUT_BUFFER_PADDING_SIZE);

            if (!descriptor->extradata)

                return -1;

            descriptor->extradata_size = size;

            avio_read(pb, descriptor->extradata, size);

        }

        break;

    }

    return 0;

}

static int fir_channel(AVFilterContext *ctx, void *arg, int ch, int nb_jobs)

{

    AudioFIRContext *s = ctx->priv;

    const float *src = (const float *)s->in[0]->extended_data[ch];

    int index1 = (s->index + 1) % 3;

    int index2 = (s->index + 2) % 3;

    float *sum = s->sum[ch];

    AVFrame *out = arg;

    float *block;

    float *dst;

    int n, i, j;



    memset(sum, 0, sizeof(*sum) * s->fft_length);

    block = s->block[ch] + s->part_index * s->block_size;

    memset(block, 0, sizeof(*block) * s->fft_length);



    s->fdsp->vector_fmul_scalar(block + s->part_size, src, s->dry_gain, s->nb_samples);

    emms_c();



    av_rdft_calc(s->rdft[ch], block);

    block[2 * s->part_size] = block[1];

    block[1] = 0;



    j = s->part_index;



    for (i = 0; i < s->nb_partitions; i++) {

        const int coffset = i * s->coeff_size;

        const FFTComplex *coeff = s->coeff[ch * !s->one2many] + coffset;



        block = s->block[ch] + j * s->block_size;

        s->fcmul_add(sum, block, (const float *)coeff, s->part_size);



        if (j == 0)

            j = s->nb_partitions;

        j--;

    }



    sum[1] = sum[2 * s->part_size];

    av_rdft_calc(s->irdft[ch], sum);



    dst = (float *)s->buffer->extended_data[ch] + index1 * s->part_size;

    for (n = 0; n < s->part_size; n++) {

        dst[n] += sum[n];

    }



    dst = (float *)s->buffer->extended_data[ch] + index2 * s->part_size;



    memcpy(dst, sum + s->part_size, s->part_size * sizeof(*dst));



    dst = (float *)s->buffer->extended_data[ch] + s->index * s->part_size;



    if (out) {

        float *ptr = (float *)out->extended_data[ch];

        s->fdsp->vector_fmul_scalar(ptr, dst, s->gain * s->wet_gain, out->nb_samples);

        emms_c();

    }



    return 0;

}

static int aiff_read_packet(AVFormatContext *s,

                            AVPacket *pkt)

{

    AVStream *st = s->streams[0];

    AIFFInputContext *aiff = s->priv_data;

    int64_t max_size;

    int res, size;



    /* calculate size of remaining data */

    max_size = aiff->data_end - avio_tell(s->pb);

    if (max_size <= 0)

        return AVERROR_EOF;



    /* Now for that packet */

    if (st->codec->block_align >= 17) // GSM, QCLP, IMA4

        size = st->codec->block_align;

    else

        size = (MAX_SIZE / st->codec->block_align) * st->codec->block_align;

    size = FFMIN(max_size, size);

    res = av_get_packet(s->pb, pkt, size);

    if (res < 0)

        return res;



    if (size >= st->codec->block_align)

        pkt->flags &= ~AV_PKT_FLAG_CORRUPT;

    /* Only one stream in an AIFF file */

    pkt->stream_index = 0;

    pkt->duration     = (res / st->codec->block_align) * aiff->block_duration;

    return 0;

}

static int get_riff(AVFormatContext *s, AVIOContext *pb)

{

    AVIContext *avi = s->priv_data;

    char header[8];

    int i;



    /* check RIFF header */

    avio_read(pb, header, 4);

    avi->riff_end  = avio_rl32(pb); /* RIFF chunk size */

    avi->riff_end += avio_tell(pb); /* RIFF chunk end */

    avio_read(pb, header + 4, 4);



    for (i = 0; avi_headers[i][0]; i++)

        if (!memcmp(header, avi_headers[i], 8))

            break;

    if (!avi_headers[i][0])

        return AVERROR_INVALIDDATA;



    if (header[7] == 0x19)

        av_log(s, AV_LOG_INFO,

               "This file has been generated by a totally broken muxer.\n");



    return 0;

}

static int decode_segment(TAKDecContext *s, int8_t mode, int32_t *decoded, int len)

{

    struct CParam code;

    GetBitContext *gb = &s->gb;

    int i;



    if (!mode) {

        memset(decoded, 0, len * sizeof(*decoded));

        return 0;

    }



    if (mode > FF_ARRAY_ELEMS(xcodes))

        return AVERROR_INVALIDDATA;

    code = xcodes[mode - 1];



    for (i = 0; i < len; i++) {

        int x = get_bits_long(gb, code.init);

        if (x >= code.escape && get_bits1(gb)) {

            x |= 1 << code.init;

            if (x >= code.aescape) {

                int scale = get_unary(gb, 1, 9);

                if (scale == 9) {

                    int scale_bits = get_bits(gb, 3);

                    if (scale_bits > 0) {

                        if (scale_bits == 7) {

                            scale_bits += get_bits(gb, 5);

                            if (scale_bits > 29)

                                return AVERROR_INVALIDDATA;

                        }

                        scale = get_bits_long(gb, scale_bits) + 1;

                        x    += code.scale * scale;

                    }

                    x += code.bias;

                } else

                    x += code.scale * scale - code.escape;

            } else

                x -= code.escape;

        }

        decoded[i] = (x >> 1) ^ -(x & 1);

    }



    return 0;

}

static int paf_video_decode(AVCodecContext *avctx, void *data,

                            int *got_frame, AVPacket *pkt)

{

    PAFVideoDecContext *c = avctx->priv_data;

    uint8_t code, *dst, *end;

    int i, frame, ret;



    if (pkt->size < 2)

        return AVERROR_INVALIDDATA;



    bytestream2_init(&c->gb, pkt->data, pkt->size);



    code = bytestream2_get_byte(&c->gb);

    if ((code & 0xF) > 4) {

        avpriv_request_sample(avctx, "unknown/invalid code");

        return AVERROR_INVALIDDATA;

    }



    if ((ret = ff_reget_buffer(avctx, c->pic)) < 0)

        return ret;



    if (code & 0x20) {  // frame is keyframe

        for (i = 0; i < 4; i++)

            memset(c->frame[i], 0, c->frame_size);



        memset(c->pic->data[1], 0, AVPALETTE_SIZE);

        c->current_frame  = 0;

        c->pic->key_frame = 1;

        c->pic->pict_type = AV_PICTURE_TYPE_I;

    } else {

        c->pic->key_frame = 0;

        c->pic->pict_type = AV_PICTURE_TYPE_P;

    }



    if (code & 0x40) {  // palette update

        uint32_t *out = (uint32_t *)c->pic->data[1];

        int index, count;



        index = bytestream2_get_byte(&c->gb);

        count = bytestream2_get_byte(&c->gb) + 1;



        if (index + count > 256)

            return AVERROR_INVALIDDATA;

        if (bytestream2_get_bytes_left(&c->gb) < 3 * count)

            return AVERROR_INVALIDDATA;



        out += index;

        for (i = 0; i < count; i++) {

            unsigned r, g, b;



            r = bytestream2_get_byteu(&c->gb);

            r = r << 2 | r >> 4;

            g = bytestream2_get_byteu(&c->gb);

            g = g << 2 | g >> 4;

            b = bytestream2_get_byteu(&c->gb);

            b = b << 2 | b >> 4;

            *out++ = (0xFFU << 24) | (r << 16) | (g << 8) | b;

        }

        c->pic->palette_has_changed = 1;

    }



    switch (code & 0x0F) {

    case 0:

        /* Block-based motion compensation using 4x4 blocks with either

         * horizontal or vertical vectors; might incorporate VQ as well. */

        if ((ret = decode_0(c, pkt->data, code)) < 0)

            return ret;

        break;

    case 1:

        /* Uncompressed data. This mode specifies that (width * height) bytes

         * should be copied directly from the encoded buffer into the output. */

        dst = c->frame[c->current_frame];

        // possibly chunk length data

        bytestream2_skip(&c->gb, 2);

        if (bytestream2_get_bytes_left(&c->gb) < c->video_size)

            return AVERROR_INVALIDDATA;

        bytestream2_get_bufferu(&c->gb, dst, c->video_size);

        break;

    case 2:

        /* Copy reference frame: Consume the next byte in the stream as the

         * reference frame (which should be 0, 1, 2, or 3, and should not be

         * the same as the current frame number). */

        frame = bytestream2_get_byte(&c->gb);

        if (frame > 3)

            return AVERROR_INVALIDDATA;

        if (frame != c->current_frame)

            memcpy(c->frame[c->current_frame], c->frame[frame], c->frame_size);

        break;

    case 4:

        /* Run length encoding.*/

        dst = c->frame[c->current_frame];

        end = dst + c->video_size;



        bytestream2_skip(&c->gb, 2);



        while (dst < end) {

            int8_t code;

            int count;



            if (bytestream2_get_bytes_left(&c->gb) < 2)

                return AVERROR_INVALIDDATA;



            code  = bytestream2_get_byteu(&c->gb);

            count = FFABS(code) + 1;



            if (dst + count > end)

                return AVERROR_INVALIDDATA;

            if (code < 0)

                memset(dst, bytestream2_get_byteu(&c->gb), count);

            else

                bytestream2_get_buffer(&c->gb, dst, count);

            dst += count;

        }

        break;

    default:

        av_assert0(0);

    }



    av_image_copy_plane(c->pic->data[0], c->pic->linesize[0],

                        c->frame[c->current_frame], c->width,

                        c->width, c->height);



    c->current_frame = (c->current_frame + 1) & 3;

    if ((ret = av_frame_ref(data, c->pic)) < 0)

        return ret;



    *got_frame = 1;



    return pkt->size;

}

int avresample_get_matrix(AVAudioResampleContext *avr, double *matrix,

                          int stride)

{

    int in_channels, out_channels, i, o;



    in_channels  = av_get_channel_layout_nb_channels(avr->in_channel_layout);

    out_channels = av_get_channel_layout_nb_channels(avr->out_channel_layout);



    if ( in_channels < 0 ||  in_channels > AVRESAMPLE_MAX_CHANNELS ||

        out_channels < 0 || out_channels > AVRESAMPLE_MAX_CHANNELS) {

        av_log(avr, AV_LOG_ERROR, "Invalid channel layouts\n");

        return AVERROR(EINVAL);

    }



    switch (avr->mix_coeff_type) {

    case AV_MIX_COEFF_TYPE_Q8:

        if (!avr->am->matrix_q8[0]) {

            av_log(avr, AV_LOG_ERROR, "matrix is not set\n");

            return AVERROR(EINVAL);

        }

        for (o = 0; o < out_channels; o++)

            for (i = 0; i < in_channels; i++)

                matrix[o * stride + i] = avr->am->matrix_q8[o][i] / 256.0;

        break;

    case AV_MIX_COEFF_TYPE_Q15:

        if (!avr->am->matrix_q15[0]) {

            av_log(avr, AV_LOG_ERROR, "matrix is not set\n");

            return AVERROR(EINVAL);

        }

        for (o = 0; o < out_channels; o++)

            for (i = 0; i < in_channels; i++)

                matrix[o * stride + i] = avr->am->matrix_q15[o][i] / 32768.0;

        break;

    case AV_MIX_COEFF_TYPE_FLT:

        if (!avr->am->matrix_flt[0]) {

            av_log(avr, AV_LOG_ERROR, "matrix is not set\n");

            return AVERROR(EINVAL);

        }

        for (o = 0; o < out_channels; o++)

            for (i = 0; i < in_channels; i++)

                matrix[o * stride + i] = avr->am->matrix_flt[o][i];

        break;

    default:

        av_log(avr, AV_LOG_ERROR, "Invalid mix coeff type\n");

        return AVERROR(EINVAL);

    }

    return 0;

}

static int parse_packet(AVFormatContext *s, AVPacket *pkt, int stream_index)

{

    AVPacket out_pkt = { 0 }, flush_pkt = { 0 };

    AVStream *st = s->streams[stream_index];

    uint8_t *data = pkt ? pkt->data : NULL;

    int size      = pkt ? pkt->size : 0;

    int ret = 0, got_output = 0;



    if (!pkt) {

        av_init_packet(&flush_pkt);

        pkt        = &flush_pkt;

        got_output = 1;

    }



    while (size > 0 || (pkt == &flush_pkt && got_output)) {

        int len;



        av_init_packet(&out_pkt);

        len = av_parser_parse2(st->parser, st->codec,

                               &out_pkt.data, &out_pkt.size, data, size,

                               pkt->pts, pkt->dts, pkt->pos);



        pkt->pts = pkt->dts = AV_NOPTS_VALUE;

        /* increment read pointer */

        data += len;

        size -= len;



        got_output = !!out_pkt.size;



        if (!out_pkt.size)

            continue;



        if (pkt->side_data) {

            out_pkt.side_data       = pkt->side_data;

            out_pkt.side_data_elems = pkt->side_data_elems;

            pkt->side_data          = NULL;

            pkt->side_data_elems    = 0;

        }



        /* set the duration */

        out_pkt.duration = 0;

        if (st->codec->codec_type == AVMEDIA_TYPE_AUDIO) {

            if (st->codec->sample_rate > 0) {

                out_pkt.duration =

                    av_rescale_q_rnd(st->parser->duration,

                                     (AVRational) { 1, st->codec->sample_rate },

                                     st->time_base,

                                     AV_ROUND_DOWN);

            }

        }



        out_pkt.stream_index = st->index;

        out_pkt.pts          = st->parser->pts;

        out_pkt.dts          = st->parser->dts;

        out_pkt.pos          = st->parser->pos;



        if (st->parser->key_frame == 1 ||

            (st->parser->key_frame == -1 &&

             st->parser->pict_type == AV_PICTURE_TYPE_I))

            out_pkt.flags |= AV_PKT_FLAG_KEY;



        compute_pkt_fields(s, st, st->parser, &out_pkt);



        if ((s->iformat->flags & AVFMT_GENERIC_INDEX) &&

            out_pkt.flags & AV_PKT_FLAG_KEY) {

            ff_reduce_index(s, st->index);

            av_add_index_entry(st, st->parser->frame_offset, out_pkt.dts,

                               0, 0, AVINDEX_KEYFRAME);

        }



        if (out_pkt.data == pkt->data && out_pkt.size == pkt->size) {

            out_pkt.buf = pkt->buf;

            pkt->buf    = NULL;

        }

        if ((ret = av_dup_packet(&out_pkt)) < 0)

            goto fail;



        if (!add_to_pktbuf(&s->internal->parse_queue, &out_pkt, &s->internal->parse_queue_end)) {

            av_packet_unref(&out_pkt);

            ret = AVERROR(ENOMEM);

            goto fail;

        }

    }



    /* end of the stream => close and free the parser */

    if (pkt == &flush_pkt) {

        av_parser_close(st->parser);

        st->parser = NULL;

    }



fail:

    av_packet_unref(pkt);

    return ret;

}

int avpriv_dv_produce_packet(DVDemuxContext *c, AVPacket *pkt,

                      uint8_t* buf, int buf_size, int64_t pos)

{

    int size, i;

    uint8_t *ppcm[4] = {0};



    if (buf_size < DV_PROFILE_BYTES ||

        !(c->sys = avpriv_dv_frame_profile(c->sys, buf, buf_size)) ||

        buf_size < c->sys->frame_size) {

          return -1;   /* Broken frame, or not enough data */

    }



    /* Queueing audio packet */

    /* FIXME: in case of no audio/bad audio we have to do something */

    size = dv_extract_audio_info(c, buf);

    for (i = 0; i < c->ach; i++) {

       c->audio_pkt[i].pos  = pos;

       c->audio_pkt[i].size = size;

       c->audio_pkt[i].pts  = c->abytes * 30000*8 / c->ast[i]->codec->bit_rate;

       ppcm[i] = c->audio_buf[i];

    }

    dv_extract_audio(buf, ppcm, c->sys);



    /* We work with 720p frames split in half, thus even frames have

     * channels 0,1 and odd 2,3. */

    if (c->sys->height == 720) {

        if (buf[1] & 0x0C) {

            c->audio_pkt[2].size = c->audio_pkt[3].size = 0;

        } else {

            c->audio_pkt[0].size = c->audio_pkt[1].size = 0;

            c->abytes += size;

        }

    } else {

        c->abytes += size;

    }



    /* Now it's time to return video packet */

    size = dv_extract_video_info(c, buf);

    av_init_packet(pkt);

    pkt->data         = buf;

    pkt->pos          = pos;

    pkt->size         = size;

    pkt->flags       |= AV_PKT_FLAG_KEY;

    pkt->stream_index = c->vst->id;

    pkt->pts          = c->frames;



    c->frames++;



    return size;

}

static int gdv_decode_frame(AVCodecContext *avctx, void *data,

                            int *got_frame, AVPacket *avpkt)

{

    GDVContext *gdv = avctx->priv_data;

    GetByteContext *gb = &gdv->gb;

    PutByteContext *pb = &gdv->pb;

    AVFrame *frame = data;

    int ret, i, pal_size;

    const uint8_t *pal = av_packet_get_side_data(avpkt, AV_PKT_DATA_PALETTE, &pal_size);

    int compression;

    unsigned flags;

    uint8_t *dst;



    if ((ret = ff_get_buffer(avctx, frame, 0)) < 0)

        return ret;

    if (pal && pal_size == AVPALETTE_SIZE)

        memcpy(gdv->pal, pal, AVPALETTE_SIZE);



    bytestream2_init(gb, avpkt->data, avpkt->size);

    bytestream2_init_writer(pb, gdv->frame, gdv->frame_size);



    flags = bytestream2_get_le32(gb);

    compression = flags & 0xF;



    rescale(gdv, gdv->frame, avctx->width, avctx->height,

            !!(flags & 0x10), !!(flags & 0x20));



    switch (compression) {

    case 1:

        memset(gdv->frame + PREAMBLE_SIZE, 0, gdv->frame_size - PREAMBLE_SIZE);

    case 0:

        if (bytestream2_get_bytes_left(gb) < 256*3)

            return AVERROR_INVALIDDATA;

        for (i = 0; i < 256; i++) {

            unsigned r = bytestream2_get_byte(gb);

            unsigned g = bytestream2_get_byte(gb);

            unsigned b = bytestream2_get_byte(gb);

            gdv->pal[i] = 0xFFU << 24 | r << 18 | g << 10 | b << 2;

        }

        break;

    case 2:

        ret = decompress_2(avctx);

        break;

    case 3:

        break;

    case 5:

        ret = decompress_5(avctx, flags >> 8);

        break;

    case 6:

        ret = decompress_68(avctx, flags >> 8, 0);

        break;

    case 8:

        ret = decompress_68(avctx, flags >> 8, 1);

        break;

    default:

        return AVERROR_INVALIDDATA;

    }



    memcpy(frame->data[1], gdv->pal, AVPALETTE_SIZE);

    dst = frame->data[0];



    if (!gdv->scale_v && !gdv->scale_h) {

        int sidx = PREAMBLE_SIZE, didx = 0;

        int y, x;



        for (y = 0; y < avctx->height; y++) {

            for (x = 0; x < avctx->width; x++) {

                dst[x+didx] = gdv->frame[x+sidx];

            }

            sidx += avctx->width;

            didx += frame->linesize[0];

        }

    } else {

        int sidx = PREAMBLE_SIZE, didx = 0;

        int y, x;



        for (y = 0; y < avctx->height; y++) {

            if (!gdv->scale_v) {

                for (x = 0; x < avctx->width; x++) {

                    dst[didx + x] = gdv->frame[sidx + x];

                }

            } else {

                for (x = 0; x < avctx->width; x++) {

                    dst[didx + x] = gdv->frame[sidx + x/2];

                }

            }

            if (!gdv->scale_h || ((y & 1) == 1)) {

                sidx += !gdv->scale_v ? avctx->width : avctx->width/2;

            }

            didx += frame->linesize[0];

        }

    }



    *got_frame = 1;



    return ret < 0 ? ret : avpkt->size;

}

int ff_rle_encode(uint8_t *outbuf, int out_size, const uint8_t *ptr , int bpp, int w,

                  int add_rep, int xor_rep, int add_raw, int xor_raw)

{

    int count, x;

    uint8_t *out = outbuf;



    for(x = 0; x < w; x += count) {

        /* see if we can encode the next set of pixels with RLE */

        if((count = count_pixels(ptr, w-x, bpp, 1)) > 1) {

            if(out + bpp + 1 > outbuf + out_size) return -1;

            *out++ = (count ^ xor_rep) + add_rep;

            memcpy(out, ptr, bpp);

            out += bpp;

        } else {

            /* fall back on uncompressed */

            count = count_pixels(ptr, w-x, bpp, 0);

            *out++ = (count ^ xor_raw) + add_raw;



            if(out + bpp*count > outbuf + out_size) return -1;

            memcpy(out, ptr, bpp * count);

            out += bpp * count;

        }



        ptr += count * bpp;

    }



    return out - outbuf;

}

static void stream_component_close(VideoState *is, int stream_index)

{

    AVFormatContext *ic = is->ic;

    AVCodecContext *avctx;



    if (stream_index < 0 || stream_index >= ic->nb_streams)

        return;

    avctx = ic->streams[stream_index]->codec;



    switch (avctx->codec_type) {

    case AVMEDIA_TYPE_AUDIO:

        packet_queue_abort(&is->audioq);



        SDL_CloseAudio();



        packet_queue_flush(&is->audioq);

        av_free_packet(&is->audio_pkt);

        if (is->swr_ctx)

            swr_free(&is->swr_ctx);

        av_freep(&is->audio_buf1);

        is->audio_buf = NULL;

        av_freep(&is->frame);



        if (is->rdft) {

            av_rdft_end(is->rdft);

            av_freep(&is->rdft_data);

            is->rdft = NULL;

            is->rdft_bits = 0;

        }

        break;

    case AVMEDIA_TYPE_VIDEO:

        packet_queue_abort(&is->videoq);



        /* note: we also signal this mutex to make sure we deblock the

           video thread in all cases */

        SDL_LockMutex(is->pictq_mutex);

        SDL_CondSignal(is->pictq_cond);

        SDL_UnlockMutex(is->pictq_mutex);



        SDL_WaitThread(is->video_tid, NULL);



        packet_queue_flush(&is->videoq);

        break;

    case AVMEDIA_TYPE_SUBTITLE:

        packet_queue_abort(&is->subtitleq);



        /* note: we also signal this mutex to make sure we deblock the

           video thread in all cases */

        SDL_LockMutex(is->subpq_mutex);

        is->subtitle_stream_changed = 1;



        SDL_CondSignal(is->subpq_cond);

        SDL_UnlockMutex(is->subpq_mutex);



        SDL_WaitThread(is->subtitle_tid, NULL);



        packet_queue_flush(&is->subtitleq);

        break;

    default:

        break;

    }



    ic->streams[stream_index]->discard = AVDISCARD_ALL;

    avcodec_close(avctx);

#if CONFIG_AVFILTER

    free_buffer_pool(&is->buffer_pool);

#endif

    switch (avctx->codec_type) {

    case AVMEDIA_TYPE_AUDIO:

        is->audio_st = NULL;

        is->audio_stream = -1;

        break;

    case AVMEDIA_TYPE_VIDEO:

        is->video_st = NULL;

        is->video_stream = -1;

        break;

    case AVMEDIA_TYPE_SUBTITLE:

        is->subtitle_st = NULL;

        is->subtitle_stream = -1;

        break;

    default:

        break;

    }

}

static inline int mpeg1_decode_block_inter(MpegEncContext *s, int16_t *block, int n)

{

    int level, i, j, run;

    RLTable *rl = &ff_rl_mpeg1;

    uint8_t * const scantable    = s->intra_scantable.permutated;

    const uint16_t *quant_matrix = s->inter_matrix;

    const int qscale             = s->qscale;



    {

        OPEN_READER(re, &s->gb);

        i = -1;

        // special case for first coefficient, no need to add second VLC table

        UPDATE_CACHE(re, &s->gb);

        if (((int32_t)GET_CACHE(re, &s->gb)) < 0) {

            level = (3 * qscale * quant_matrix[0]) >> 5;

            level = (level - 1) | 1;

            if (GET_CACHE(re, &s->gb) & 0x40000000)

                level = -level;

            block[0] = level;

            i++;

            SKIP_BITS(re, &s->gb, 2);

            if (((int32_t)GET_CACHE(re, &s->gb)) <= (int32_t)0xBFFFFFFF)

                goto end;

        }

        /* now quantify & encode AC coefficients */

        for (;;) {

            GET_RL_VLC(level, run, re, &s->gb, rl->rl_vlc[0], TEX_VLC_BITS, 2, 0);



            if (level != 0) {

                i += run;

                j = scantable[i];

                level = ((level * 2 + 1) * qscale * quant_matrix[j]) >> 5;

                level = (level - 1) | 1;

                level = (level ^ SHOW_SBITS(re, &s->gb, 1)) - SHOW_SBITS(re, &s->gb, 1);

                SKIP_BITS(re, &s->gb, 1);

            } else {

                /* escape */

                run = SHOW_UBITS(re, &s->gb, 6) + 1; LAST_SKIP_BITS(re, &s->gb, 6);

                UPDATE_CACHE(re, &s->gb);

                level = SHOW_SBITS(re, &s->gb, 8); SKIP_BITS(re, &s->gb, 8);

                if (level == -128) {

                    level = SHOW_UBITS(re, &s->gb, 8) - 256; SKIP_BITS(re, &s->gb, 8);

                } else if (level == 0) {

                    level = SHOW_UBITS(re, &s->gb, 8)      ; SKIP_BITS(re, &s->gb, 8);

                }

                i += run;

                j = scantable[i];

                if (level < 0) {

                    level = -level;

                    level = ((level * 2 + 1) * qscale * quant_matrix[j]) >> 5;

                    level = (level - 1) | 1;

                    level = -level;

                } else {

                    level = ((level * 2 + 1) * qscale * quant_matrix[j]) >> 5;

                    level = (level - 1) | 1;

                }

            }

            if (i > 63) {

                av_log(s->avctx, AV_LOG_ERROR, "ac-tex damaged at %d %d\n", s->mb_x, s->mb_y);

                return -1;

            }



            block[j] = level;

            if (((int32_t)GET_CACHE(re, &s->gb)) <= (int32_t)0xBFFFFFFF)

                break;

            UPDATE_CACHE(re, &s->gb);

        }

end:

        LAST_SKIP_BITS(re, &s->gb, 2);

        CLOSE_READER(re, &s->gb);

    }

    s->block_last_index[n] = i;

    return 0;

}

static void vp8_decode_mv_mb_modes(AVCodecContext *avctx, VP8Frame *curframe,

                                   VP8Frame *prev_frame)

{

    VP8Context *s = avctx->priv_data;

    int mb_x, mb_y;



    s->mv_min.y = -MARGIN;

    s->mv_max.y = ((s->mb_height - 1) << 6) + MARGIN;

    for (mb_y = 0; mb_y < s->mb_height; mb_y++) {

        VP8Macroblock *mb = s->macroblocks_base +

                            ((s->mb_width + 1) * (mb_y + 1) + 1);

        int mb_xy = mb_y * s->mb_width;



        AV_WN32A(s->intra4x4_pred_mode_left, DC_PRED * 0x01010101);



        s->mv_min.x = -MARGIN;

        s->mv_max.x = ((s->mb_width - 1) << 6) + MARGIN;

        for (mb_x = 0; mb_x < s->mb_width; mb_x++, mb_xy++, mb++) {

            if (mb_y == 0)

                AV_WN32A((mb - s->mb_width - 1)->intra4x4_pred_mode_top,

                         DC_PRED * 0x01010101);

            decode_mb_mode(s, mb, mb_x, mb_y, curframe->seg_map->data + mb_xy,

                           prev_frame && prev_frame->seg_map ?

                           prev_frame->seg_map->data + mb_xy : NULL, 1);

            s->mv_min.x -= 64;

            s->mv_max.x -= 64;

        }

        s->mv_min.y -= 64;

        s->mv_max.y -= 64;

    }

}

static av_always_inline void mc_luma_scaled(VP9Context *s, vp9_scaled_mc_func smc,

                                            vp9_mc_func (*mc)[2],

                                            uint8_t *dst, ptrdiff_t dst_stride,

                                            const uint8_t *ref, ptrdiff_t ref_stride,

                                            ThreadFrame *ref_frame,

                                            ptrdiff_t y, ptrdiff_t x, const VP56mv *in_mv,

                                            int px, int py, int pw, int ph,

                                            int bw, int bh, int w, int h, int bytesperpixel,

                                            const uint16_t *scale, const uint8_t *step)

{

    if (s->s.frames[CUR_FRAME].tf.f->width == ref_frame->f->width &&

        s->s.frames[CUR_FRAME].tf.f->height == ref_frame->f->height) {

        mc_luma_unscaled(s, mc, dst, dst_stride, ref, ref_stride, ref_frame,

                         y, x, in_mv, bw, bh, w, h, bytesperpixel);

    } else {

#define scale_mv(n, dim) (((int64_t)(n) * scale[dim]) >> 14)

    int mx, my;

    int refbw_m1, refbh_m1;

    int th;

    VP56mv mv;



    mv.x = av_clip(in_mv->x, -(x + pw - px + 4) * 8, (s->cols * 8 - x + px + 3) * 8);

    mv.y = av_clip(in_mv->y, -(y + ph - py + 4) * 8, (s->rows * 8 - y + py + 3) * 8);

    // BUG libvpx seems to scale the two components separately. This introduces

    // rounding errors but we have to reproduce them to be exactly compatible

    // with the output from libvpx...

    mx = scale_mv(mv.x * 2, 0) + scale_mv(x * 16, 0);

    my = scale_mv(mv.y * 2, 1) + scale_mv(y * 16, 1);



    y = my >> 4;

    x = mx >> 4;

    ref += y * ref_stride + x * bytesperpixel;

    mx &= 15;

    my &= 15;

    refbw_m1 = ((bw - 1) * step[0] + mx) >> 4;

    refbh_m1 = ((bh - 1) * step[1] + my) >> 4;

    // FIXME bilinear filter only needs 0/1 pixels, not 3/4

    // we use +7 because the last 7 pixels of each sbrow can be changed in

    // the longest loopfilter of the next sbrow

    th = (y + refbh_m1 + 4 + 7) >> 6;

    ff_thread_await_progress(ref_frame, FFMAX(th, 0), 0);

    if (x < 3 || y < 3 || x + 4 >= w - refbw_m1 || y + 4 >= h - refbh_m1) {

        s->vdsp.emulated_edge_mc(s->edge_emu_buffer,

                                 ref - 3 * ref_stride - 3 * bytesperpixel,

                                 288, ref_stride,

                                 refbw_m1 + 8, refbh_m1 + 8,

                                 x - 3, y - 3, w, h);

        ref = s->edge_emu_buffer + 3 * 288 + 3 * bytesperpixel;

        ref_stride = 288;

    }

    smc(dst, dst_stride, ref, ref_stride, bh, mx, my, step[0], step[1]);

    }

}

int ff_draw_init(FFDrawContext *draw, enum PixelFormat format, unsigned flags)

{

    const AVPixFmtDescriptor *desc = &av_pix_fmt_descriptors[format];

    const AVComponentDescriptor *c;

    unsigned i, nb_planes = 0;

    int pixelstep[MAX_PLANES] = { 0 };



    if (!desc->name)

        return AVERROR(EINVAL);

    if (desc->flags & ~(PIX_FMT_PLANAR | PIX_FMT_RGB))

        return AVERROR(ENOSYS);

    for (i = 0; i < desc->nb_components; i++) {

        c = &desc->comp[i];

        /* for now, only 8-bits formats */

        if (c->depth_minus1 != 8 - 1)

            return AVERROR(ENOSYS);

        if (c->plane >= MAX_PLANES)

            return AVERROR(ENOSYS);

        /* strange interleaving */

        if (pixelstep[c->plane] != 0 &&

            pixelstep[c->plane] != c->step_minus1 + 1)

            return AVERROR(ENOSYS);

        pixelstep[c->plane] = c->step_minus1 + 1;

        if (pixelstep[c->plane] >= 8)

            return AVERROR(ENOSYS);

        nb_planes = FFMAX(nb_planes, c->plane + 1);

    }

    if ((desc->log2_chroma_w || desc->log2_chroma_h) && nb_planes < 3)

        return AVERROR(ENOSYS); /* exclude NV12 and NV21 */

    memset(draw, 0, sizeof(*draw));

    draw->desc      = desc;

    draw->format    = format;

    draw->nb_planes = nb_planes;

    memcpy(draw->pixelstep, pixelstep, sizeof(draw->pixelstep));

    if (nb_planes >= 3 && !(desc->flags & PIX_FMT_RGB)) {

        draw->hsub[1] = draw->hsub[2] = draw->hsub_max = desc->log2_chroma_w;

        draw->vsub[1] = draw->vsub[2] = draw->vsub_max = desc->log2_chroma_h;

    }

    for (i = 0; i < ((desc->nb_components - 1) | 1); i++)

        draw->comp_mask[desc->comp[i].plane] |=

            1 << (desc->comp[i].offset_plus1 - 1);

    return 0;

}

av_cold void ff_dct_init_mmx(DCTContext *s)

{

#if HAVE_YASM

    int has_vectors = av_get_cpu_flags();

    if (has_vectors & AV_CPU_FLAG_SSE && HAVE_SSE)

        s->dct32 = ff_dct32_float_sse;

    if (has_vectors & AV_CPU_FLAG_SSE2 && HAVE_SSE)

        s->dct32 = ff_dct32_float_sse2;

    if (has_vectors & AV_CPU_FLAG_AVX && HAVE_AVX)

        s->dct32 = ff_dct32_float_avx;

#endif

}

int ff_reget_buffer(AVCodecContext *avctx, AVFrame *frame)

{

    AVFrame *tmp;

    int ret;



    av_assert0(avctx->codec_type == AVMEDIA_TYPE_VIDEO);



    if (!frame->data[0])

        return ff_get_buffer(avctx, frame, AV_GET_BUFFER_FLAG_REF);



    if (av_frame_is_writable(frame)) {

        frame->pkt_pts = avctx->internal->pkt ? avctx->internal->pkt->pts : AV_NOPTS_VALUE;

        frame->reordered_opaque = avctx->reordered_opaque;

        return 0;

    }



    tmp = av_frame_alloc();

    if (!tmp)

        return AVERROR(ENOMEM);



    av_frame_move_ref(tmp, frame);



    ret = ff_get_buffer(avctx, frame, AV_GET_BUFFER_FLAG_REF);

    if (ret < 0) {

        av_frame_free(&tmp);

        return ret;

    }



    av_frame_copy(frame, tmp);

    av_frame_free(&tmp);



    return 0;

}

static av_always_inline void h264_filter_mb_fast_internal(H264Context *h,

                                                          H264SliceContext *sl,

                                                          int mb_x, int mb_y,

                                                          uint8_t *img_y,

                                                          uint8_t *img_cb,

                                                          uint8_t *img_cr,

                                                          unsigned int linesize,

                                                          unsigned int uvlinesize,

                                                          int pixel_shift)

{

    int chroma = !(CONFIG_GRAY && (h->flags&CODEC_FLAG_GRAY));

    int chroma444 = CHROMA444(h);

    int chroma422 = CHROMA422(h);



    int mb_xy = h->mb_xy;

    int left_type = sl->left_type[LTOP];

    int top_type  = sl->top_type;



    int qp_bd_offset = 6 * (h->sps.bit_depth_luma - 8);

    int a = 52 + h->slice_alpha_c0_offset - qp_bd_offset;

    int b = 52 + h->slice_beta_offset - qp_bd_offset;



    int mb_type = h->cur_pic.mb_type[mb_xy];

    int qp      = h->cur_pic.qscale_table[mb_xy];

    int qp0     = h->cur_pic.qscale_table[mb_xy - 1];

    int qp1     = h->cur_pic.qscale_table[sl->top_mb_xy];

    int qpc = get_chroma_qp( h, 0, qp );

    int qpc0 = get_chroma_qp( h, 0, qp0 );

    int qpc1 = get_chroma_qp( h, 0, qp1 );

    qp0 = (qp + qp0 + 1) >> 1;

    qp1 = (qp + qp1 + 1) >> 1;

    qpc0 = (qpc + qpc0 + 1) >> 1;

    qpc1 = (qpc + qpc1 + 1) >> 1;



    if( IS_INTRA(mb_type) ) {

        static const int16_t bS4[4] = {4,4,4,4};

        static const int16_t bS3[4] = {3,3,3,3};

        const int16_t *bSH = FIELD_PICTURE(h) ? bS3 : bS4;

        if(left_type)

            filter_mb_edgev( &img_y[4*0<<pixel_shift], linesize, bS4, qp0, a, b, h, 1);

        if( IS_8x8DCT(mb_type) ) {

            filter_mb_edgev( &img_y[4*2<<pixel_shift], linesize, bS3, qp, a, b, h, 0);

            if(top_type){

                filter_mb_edgeh( &img_y[4*0*linesize], linesize, bSH, qp1, a, b, h, 1);

            }

            filter_mb_edgeh( &img_y[4*2*linesize], linesize, bS3, qp, a, b, h, 0);

        } else {

            filter_mb_edgev( &img_y[4*1<<pixel_shift], linesize, bS3, qp, a, b, h, 0);

            filter_mb_edgev( &img_y[4*2<<pixel_shift], linesize, bS3, qp, a, b, h, 0);

            filter_mb_edgev( &img_y[4*3<<pixel_shift], linesize, bS3, qp, a, b, h, 0);

            if(top_type){

                filter_mb_edgeh( &img_y[4*0*linesize], linesize, bSH, qp1, a, b, h, 1);

            }

            filter_mb_edgeh( &img_y[4*1*linesize], linesize, bS3, qp, a, b, h, 0);

            filter_mb_edgeh( &img_y[4*2*linesize], linesize, bS3, qp, a, b, h, 0);

            filter_mb_edgeh( &img_y[4*3*linesize], linesize, bS3, qp, a, b, h, 0);

        }

        if(chroma){

            if(chroma444){

                if(left_type){

                    filter_mb_edgev( &img_cb[4*0<<pixel_shift], linesize, bS4, qpc0, a, b, h, 1);

                    filter_mb_edgev( &img_cr[4*0<<pixel_shift], linesize, bS4, qpc0, a, b, h, 1);

                }

                if( IS_8x8DCT(mb_type) ) {

                    filter_mb_edgev( &img_cb[4*2<<pixel_shift], linesize, bS3, qpc, a, b, h, 0);

                    filter_mb_edgev( &img_cr[4*2<<pixel_shift], linesize, bS3, qpc, a, b, h, 0);

                    if(top_type){

                        filter_mb_edgeh( &img_cb[4*0*linesize], linesize, bSH, qpc1, a, b, h, 1 );

                        filter_mb_edgeh( &img_cr[4*0*linesize], linesize, bSH, qpc1, a, b, h, 1 );

                    }

                    filter_mb_edgeh( &img_cb[4*2*linesize], linesize, bS3, qpc, a, b, h, 0);

                    filter_mb_edgeh( &img_cr[4*2*linesize], linesize, bS3, qpc, a, b, h, 0);

                } else {

                    filter_mb_edgev( &img_cb[4*1<<pixel_shift], linesize, bS3, qpc, a, b, h, 0);

                    filter_mb_edgev( &img_cr[4*1<<pixel_shift], linesize, bS3, qpc, a, b, h, 0);

                    filter_mb_edgev( &img_cb[4*2<<pixel_shift], linesize, bS3, qpc, a, b, h, 0);

                    filter_mb_edgev( &img_cr[4*2<<pixel_shift], linesize, bS3, qpc, a, b, h, 0);

                    filter_mb_edgev( &img_cb[4*3<<pixel_shift], linesize, bS3, qpc, a, b, h, 0);

                    filter_mb_edgev( &img_cr[4*3<<pixel_shift], linesize, bS3, qpc, a, b, h, 0);

                    if(top_type){

                        filter_mb_edgeh( &img_cb[4*0*linesize], linesize, bSH, qpc1, a, b, h, 1);

                        filter_mb_edgeh( &img_cr[4*0*linesize], linesize, bSH, qpc1, a, b, h, 1);

                    }

                    filter_mb_edgeh( &img_cb[4*1*linesize], linesize, bS3, qpc, a, b, h, 0);

                    filter_mb_edgeh( &img_cr[4*1*linesize], linesize, bS3, qpc, a, b, h, 0);

                    filter_mb_edgeh( &img_cb[4*2*linesize], linesize, bS3, qpc, a, b, h, 0);

                    filter_mb_edgeh( &img_cr[4*2*linesize], linesize, bS3, qpc, a, b, h, 0);

                    filter_mb_edgeh( &img_cb[4*3*linesize], linesize, bS3, qpc, a, b, h, 0);

                    filter_mb_edgeh( &img_cr[4*3*linesize], linesize, bS3, qpc, a, b, h, 0);

                }

            }else if(chroma422){

                if(left_type){

                    filter_mb_edgecv(&img_cb[2*0<<pixel_shift], uvlinesize, bS4, qpc0, a, b, h, 1);

                    filter_mb_edgecv(&img_cr[2*0<<pixel_shift], uvlinesize, bS4, qpc0, a, b, h, 1);

                }

                filter_mb_edgecv(&img_cb[2*2<<pixel_shift], uvlinesize, bS3, qpc, a, b, h, 0);

                filter_mb_edgecv(&img_cr[2*2<<pixel_shift], uvlinesize, bS3, qpc, a, b, h, 0);

                if(top_type){

                    filter_mb_edgech(&img_cb[4*0*uvlinesize], uvlinesize, bSH, qpc1, a, b, h, 1);

                    filter_mb_edgech(&img_cr[4*0*uvlinesize], uvlinesize, bSH, qpc1, a, b, h, 1);

                }

                filter_mb_edgech(&img_cb[4*1*uvlinesize], uvlinesize, bS3, qpc, a, b, h, 0);

                filter_mb_edgech(&img_cr[4*1*uvlinesize], uvlinesize, bS3, qpc, a, b, h, 0);

                filter_mb_edgech(&img_cb[4*2*uvlinesize], uvlinesize, bS3, qpc, a, b, h, 0);

                filter_mb_edgech(&img_cr[4*2*uvlinesize], uvlinesize, bS3, qpc, a, b, h, 0);

                filter_mb_edgech(&img_cb[4*3*uvlinesize], uvlinesize, bS3, qpc, a, b, h, 0);

                filter_mb_edgech(&img_cr[4*3*uvlinesize], uvlinesize, bS3, qpc, a, b, h, 0);

            }else{

                if(left_type){

                    filter_mb_edgecv( &img_cb[2*0<<pixel_shift], uvlinesize, bS4, qpc0, a, b, h, 1);

                    filter_mb_edgecv( &img_cr[2*0<<pixel_shift], uvlinesize, bS4, qpc0, a, b, h, 1);

                }

                filter_mb_edgecv( &img_cb[2*2<<pixel_shift], uvlinesize, bS3, qpc, a, b, h, 0);

                filter_mb_edgecv( &img_cr[2*2<<pixel_shift], uvlinesize, bS3, qpc, a, b, h, 0);

                if(top_type){

                    filter_mb_edgech( &img_cb[2*0*uvlinesize], uvlinesize, bSH, qpc1, a, b, h, 1);

                    filter_mb_edgech( &img_cr[2*0*uvlinesize], uvlinesize, bSH, qpc1, a, b, h, 1);

                }

                filter_mb_edgech( &img_cb[2*2*uvlinesize], uvlinesize, bS3, qpc, a, b, h, 0);

                filter_mb_edgech( &img_cr[2*2*uvlinesize], uvlinesize, bS3, qpc, a, b, h, 0);

            }

        }

        return;

    } else {

        LOCAL_ALIGNED_8(int16_t, bS, [2], [4][4]);

        int edges;

        if( IS_8x8DCT(mb_type) && (sl->cbp&7) == 7 && !chroma444 ) {

            edges = 4;

            AV_WN64A(bS[0][0], 0x0002000200020002ULL);

            AV_WN64A(bS[0][2], 0x0002000200020002ULL);

            AV_WN64A(bS[1][0], 0x0002000200020002ULL);

            AV_WN64A(bS[1][2], 0x0002000200020002ULL);

        } else {

            int mask_edge1 = (3*(((5*mb_type)>>5)&1)) | (mb_type>>4); //(mb_type & (MB_TYPE_16x16 | MB_TYPE_8x16)) ? 3 : (mb_type & MB_TYPE_16x8) ? 1 : 0;

            int mask_edge0 = 3*((mask_edge1>>1) & ((5*left_type)>>5)&1); // (mb_type & (MB_TYPE_16x16 | MB_TYPE_8x16)) && (h->left_type[LTOP] & (MB_TYPE_16x16 | MB_TYPE_8x16)) ? 3 : 0;

            int step =  1+(mb_type>>24); //IS_8x8DCT(mb_type) ? 2 : 1;

            edges = 4 - 3*((mb_type>>3) & !(sl->cbp & 15)); //(mb_type & MB_TYPE_16x16) && !(h->cbp & 15) ? 1 : 4;

            h->h264dsp.h264_loop_filter_strength(bS, sl->non_zero_count_cache, sl->ref_cache, sl->mv_cache,

                                                 sl->list_count==2, edges, step, mask_edge0, mask_edge1, FIELD_PICTURE(h));

        }

        if( IS_INTRA(left_type) )

            AV_WN64A(bS[0][0], 0x0004000400040004ULL);

        if( IS_INTRA(top_type) )

            AV_WN64A(bS[1][0], FIELD_PICTURE(h) ? 0x0003000300030003ULL : 0x0004000400040004ULL);



#define FILTER(hv,dir,edge,intra)\

        if(AV_RN64A(bS[dir][edge])) {                                   \

            filter_mb_edge##hv( &img_y[4*edge*(dir?linesize:1<<pixel_shift)], linesize, bS[dir][edge], edge ? qp : qp##dir, a, b, h, intra );\

            if(chroma){\

                if(chroma444){\

                    filter_mb_edge##hv( &img_cb[4*edge*(dir?linesize:1<<pixel_shift)], linesize, bS[dir][edge], edge ? qpc : qpc##dir, a, b, h, intra );\

                    filter_mb_edge##hv( &img_cr[4*edge*(dir?linesize:1<<pixel_shift)], linesize, bS[dir][edge], edge ? qpc : qpc##dir, a, b, h, intra );\

                } else if(!(edge&1)) {\

                    filter_mb_edgec##hv( &img_cb[2*edge*(dir?uvlinesize:1<<pixel_shift)], uvlinesize, bS[dir][edge], edge ? qpc : qpc##dir, a, b, h, intra );\

                    filter_mb_edgec##hv( &img_cr[2*edge*(dir?uvlinesize:1<<pixel_shift)], uvlinesize, bS[dir][edge], edge ? qpc : qpc##dir, a, b, h, intra );\

                }\

            }\

        }

        if(left_type)

            FILTER(v,0,0,1);

        if( edges == 1 ) {

            if(top_type)

                FILTER(h,1,0,1);

        } else if( IS_8x8DCT(mb_type) ) {

            FILTER(v,0,2,0);

            if(top_type)

                FILTER(h,1,0,1);

            FILTER(h,1,2,0);

        } else {

            FILTER(v,0,1,0);

            FILTER(v,0,2,0);

            FILTER(v,0,3,0);

            if(top_type)

                FILTER(h,1,0,1);

            FILTER(h,1,1,0);

            FILTER(h,1,2,0);

            FILTER(h,1,3,0);

        }

#undef FILTER

    }

}

static int mpc7_decode_frame(AVCodecContext * avctx, void *data,

                             int *got_frame_ptr, AVPacket *avpkt)

{

    const uint8_t *buf = avpkt->data;

    int buf_size = avpkt->size;

    MPCContext *c = avctx->priv_data;

    GetBitContext gb;

    uint8_t *bits;

    int i, ch;

    int mb = -1;

    Band *bands = c->bands;

    int off, ret;

    int bits_used, bits_avail;



    memset(bands, 0, sizeof(*bands) * (c->maxbands + 1));

    if(buf_size <= 4){

        av_log(avctx, AV_LOG_ERROR, "Too small buffer passed (%i bytes)\n", buf_size);

        return AVERROR(EINVAL);

    }



    /* get output buffer */

    c->frame.nb_samples = buf[1] ? c->lastframelen : MPC_FRAME_SIZE;

    if ((ret = avctx->get_buffer(avctx, &c->frame)) < 0) {

        av_log(avctx, AV_LOG_ERROR, "get_buffer() failed\n");

        return ret;

    }



    bits = av_malloc(((buf_size - 1) & ~3) + FF_INPUT_BUFFER_PADDING_SIZE);



    c->dsp.bswap_buf((uint32_t*)bits, (const uint32_t*)(buf + 4), (buf_size - 4) >> 2);

    init_get_bits(&gb, bits, (buf_size - 4)* 8);

    skip_bits_long(&gb, buf[0]);



    /* read subband indexes */

    for(i = 0; i <= c->maxbands; i++){

        for(ch = 0; ch < 2; ch++){

            int t = 4;

            if(i) t = get_vlc2(&gb, hdr_vlc.table, MPC7_HDR_BITS, 1) - 5;

            if(t == 4) bands[i].res[ch] = get_bits(&gb, 4);

            else bands[i].res[ch] = bands[i-1].res[ch] + t;

        }



        if(bands[i].res[0] || bands[i].res[1]){

            mb = i;

            if(c->MSS) bands[i].msf = get_bits1(&gb);

        }

    }

    /* get scale indexes coding method */

    for(i = 0; i <= mb; i++)

        for(ch = 0; ch < 2; ch++)

            if(bands[i].res[ch]) bands[i].scfi[ch] = get_vlc2(&gb, scfi_vlc.table, MPC7_SCFI_BITS, 1);

    /* get scale indexes */

    for(i = 0; i <= mb; i++){

        for(ch = 0; ch < 2; ch++){

            if(bands[i].res[ch]){

                bands[i].scf_idx[ch][2] = c->oldDSCF[ch][i];

                bands[i].scf_idx[ch][0] = get_scale_idx(&gb, bands[i].scf_idx[ch][2]);

                switch(bands[i].scfi[ch]){

                case 0:

                    bands[i].scf_idx[ch][1] = get_scale_idx(&gb, bands[i].scf_idx[ch][0]);

                    bands[i].scf_idx[ch][2] = get_scale_idx(&gb, bands[i].scf_idx[ch][1]);

                    break;

                case 1:

                    bands[i].scf_idx[ch][1] = get_scale_idx(&gb, bands[i].scf_idx[ch][0]);

                    bands[i].scf_idx[ch][2] = bands[i].scf_idx[ch][1];

                    break;

                case 2:

                    bands[i].scf_idx[ch][1] = bands[i].scf_idx[ch][0];

                    bands[i].scf_idx[ch][2] = get_scale_idx(&gb, bands[i].scf_idx[ch][1]);

                    break;

                case 3:

                    bands[i].scf_idx[ch][2] = bands[i].scf_idx[ch][1] = bands[i].scf_idx[ch][0];

                    break;

                }

                c->oldDSCF[ch][i] = bands[i].scf_idx[ch][2];

            }

        }

    }

    /* get quantizers */

    memset(c->Q, 0, sizeof(c->Q));

    off = 0;

    for(i = 0; i < BANDS; i++, off += SAMPLES_PER_BAND)

        for(ch = 0; ch < 2; ch++)

            idx_to_quant(c, &gb, bands[i].res[ch], c->Q[ch] + off);



    ff_mpc_dequantize_and_synth(c, mb, c->frame.data[0], 2);



    av_free(bits);



    bits_used = get_bits_count(&gb);

    bits_avail = (buf_size - 4) * 8;

    if(!buf[1] && ((bits_avail < bits_used) || (bits_used + 32 <= bits_avail))){

        av_log(NULL,0, "Error decoding frame: used %i of %i bits\n", bits_used, bits_avail);

        return -1;

    }

    if(c->frames_to_skip){

        c->frames_to_skip--;

        *got_frame_ptr = 0;

        return buf_size;

    }



    *got_frame_ptr   = 1;

    *(AVFrame *)data = c->frame;



    return buf_size;

}

uint8_t* ff_AMediaCodec_getOutputBuffer(FFAMediaCodec* codec, size_t idx, size_t *out_size)

{

    uint8_t *ret = NULL;

    JNIEnv *env = NULL;



    jobject buffer = NULL;



    JNI_GET_ENV_OR_RETURN(env, codec, NULL);



    if (codec->has_get_i_o_buffer) {

        buffer = (*env)->CallObjectMethod(env, codec->object, codec->jfields.get_output_buffer_id, idx);

        if (ff_jni_exception_check(env, 1, codec) < 0) {

            goto fail;

        }

    } else {

        if (!codec->output_buffers) {

            codec->output_buffers = (*env)->CallObjectMethod(env, codec->object, codec->jfields.get_output_buffers_id);

            if (ff_jni_exception_check(env, 1, codec) < 0) {

                goto fail;

            }



            codec->output_buffers = (*env)->NewGlobalRef(env, codec->output_buffers);

            if (ff_jni_exception_check(env, 1, codec) < 0) {

                goto fail;

            }

        }



        buffer = (*env)->GetObjectArrayElement(env, codec->output_buffers, idx);

        if (ff_jni_exception_check(env, 1, codec) < 0) {

            goto fail;

        }

    }



    ret = (*env)->GetDirectBufferAddress(env, buffer);

    *out_size = (*env)->GetDirectBufferCapacity(env, buffer);

fail:

    if (buffer) {

        (*env)->DeleteLocalRef(env, buffer);

    }



    return ret;

}

static int try_decode_video_frame(AVCodecContext *codec_ctx, AVPacket *pkt, int decode)

{

    int ret = 0;

    int got_frame = 0;

    AVFrame *frame = NULL;

    int skip_frame = codec_ctx->skip_frame;



    if (!avcodec_is_open(codec_ctx)) {

        const AVCodec *codec = avcodec_find_decoder(codec_ctx->codec_id);



        ret = avcodec_open2(codec_ctx, codec, NULL);

        if (ret < 0) {

            av_log(codec_ctx, AV_LOG_ERROR, "Failed to open codec\n");

            goto end;

        }

    }



    frame = av_frame_alloc();

    if (!frame) {

        av_log(NULL, AV_LOG_ERROR, "Failed to allocate frame\n");

        goto end;

    }



    if (!decode && codec_ctx->codec->caps_internal & FF_CODEC_CAP_SKIP_FRAME_FILL_PARAM) {

        codec_ctx->skip_frame = AVDISCARD_ALL;

    }



    do {

        ret = avcodec_decode_video2(codec_ctx, frame, &got_frame, pkt);

        av_assert0(decode || (!decode && !got_frame));

        if (ret < 0)

            break;

        pkt->data += ret;

        pkt->size -= ret;



        if (got_frame) {

            break;

        }

    } while (pkt->size > 0);



end:

    codec_ctx->skip_frame = skip_frame;



    av_frame_free(&frame);

    return ret;

}

static int tiff_decode_tag(TiffContext *s, AVFrame *frame)

{

    unsigned tag, type, count, off, value = 0, value2 = 0;

    int i, start;

    int pos;

    int ret;

    double *dp;



    ret = ff_tread_tag(&s->gb, s->le, &tag, &type, &count, &start);

    if (ret < 0) {

        goto end;

    }



    off = bytestream2_tell(&s->gb);

    if (count == 1) {

        switch (type) {

        case TIFF_BYTE:

        case TIFF_SHORT:

        case TIFF_LONG:

            value = ff_tget(&s->gb, type, s->le);

            break;

        case TIFF_RATIONAL:

            value  = ff_tget(&s->gb, TIFF_LONG, s->le);

            value2 = ff_tget(&s->gb, TIFF_LONG, s->le);

            break;

        case TIFF_STRING:

            if (count <= 4) {

                break;

            }

        default:

            value = UINT_MAX;

        }

    }



    switch (tag) {

    case TIFF_WIDTH:

        s->width = value;

        break;

    case TIFF_HEIGHT:

        s->height = value;

        break;

    case TIFF_BPP:

        s->bppcount = count;

        if (count > 4) {

            av_log(s->avctx, AV_LOG_ERROR,

                   "This format is not supported (bpp=%d, %d components)\n",

                   s->bpp, count);

            return AVERROR_INVALIDDATA;

        }

        if (count == 1)

            s->bpp = value;

        else {

            switch (type) {

            case TIFF_BYTE:

            case TIFF_SHORT:

            case TIFF_LONG:

                s->bpp = 0;

                if (bytestream2_get_bytes_left(&s->gb) < type_sizes[type] * count)

                    return AVERROR_INVALIDDATA;

                for (i = 0; i < count; i++)

                    s->bpp += ff_tget(&s->gb, type, s->le);

                break;

            default:

                s->bpp = -1;

            }

        }

        break;

    case TIFF_SAMPLES_PER_PIXEL:

        if (count != 1) {

            av_log(s->avctx, AV_LOG_ERROR,

                   "Samples per pixel requires a single value, many provided\n");

            return AVERROR_INVALIDDATA;

        }

        if (value > 4U) {

            av_log(s->avctx, AV_LOG_ERROR,

                   "Samples per pixel %d is too large\n", value);

            return AVERROR_INVALIDDATA;

        }

        if (s->bppcount == 1)

            s->bpp *= value;

        s->bppcount = value;

        break;

    case TIFF_COMPR:

        s->compr     = value;

        s->predictor = 0;

        switch (s->compr) {

        case TIFF_RAW:

        case TIFF_PACKBITS:

        case TIFF_LZW:

        case TIFF_CCITT_RLE:

            break;

        case TIFF_G3:

        case TIFF_G4:

            s->fax_opts = 0;

            break;

        case TIFF_DEFLATE:

        case TIFF_ADOBE_DEFLATE:

#if CONFIG_ZLIB

            break;

#else

            av_log(s->avctx, AV_LOG_ERROR, "Deflate: ZLib not compiled in\n");

            return AVERROR(ENOSYS);

#endif

        case TIFF_JPEG:

        case TIFF_NEWJPEG:

            avpriv_report_missing_feature(s->avctx, "JPEG compression");

            return AVERROR_PATCHWELCOME;

        case TIFF_LZMA:

#if CONFIG_LZMA

            break;

#else

            av_log(s->avctx, AV_LOG_ERROR, "LZMA not compiled in\n");

            return AVERROR(ENOSYS);

#endif

        default:

            av_log(s->avctx, AV_LOG_ERROR, "Unknown compression method %i\n",

                   s->compr);

            return AVERROR_INVALIDDATA;

        }

        break;

    case TIFF_ROWSPERSTRIP:

        if (!value || (type == TIFF_LONG && value == UINT_MAX))

            value = s->height;

        s->rps = FFMIN(value, s->height);

        break;

    case TIFF_STRIP_OFFS:

        if (count == 1) {

            s->strippos = 0;

            s->stripoff = value;

        } else

            s->strippos = off;

        s->strips = count;

        if (s->strips == 1)

            s->rps = s->height;

        s->sot = type;

        break;

    case TIFF_STRIP_SIZE:

        if (count == 1) {

            s->stripsizesoff = 0;

            s->stripsize     = value;

            s->strips        = 1;

        } else {

            s->stripsizesoff = off;

        }

        s->strips = count;

        s->sstype = type;

        break;

    case TIFF_XRES:

    case TIFF_YRES:

        set_sar(s, tag, value, value2);

        break;

    case TIFF_TILE_BYTE_COUNTS:

    case TIFF_TILE_LENGTH:

    case TIFF_TILE_OFFSETS:

    case TIFF_TILE_WIDTH:

        av_log(s->avctx, AV_LOG_ERROR, "Tiled images are not supported\n");

        return AVERROR_PATCHWELCOME;

        break;

    case TIFF_PREDICTOR:

        s->predictor = value;

        break;

    case TIFF_PHOTOMETRIC:

        switch (value) {

        case TIFF_PHOTOMETRIC_WHITE_IS_ZERO:

        case TIFF_PHOTOMETRIC_BLACK_IS_ZERO:

        case TIFF_PHOTOMETRIC_RGB:

        case TIFF_PHOTOMETRIC_PALETTE:

        case TIFF_PHOTOMETRIC_YCBCR:

            s->photometric = value;

            break;

        case TIFF_PHOTOMETRIC_ALPHA_MASK:

        case TIFF_PHOTOMETRIC_SEPARATED:

        case TIFF_PHOTOMETRIC_CIE_LAB:

        case TIFF_PHOTOMETRIC_ICC_LAB:

        case TIFF_PHOTOMETRIC_ITU_LAB:

        case TIFF_PHOTOMETRIC_CFA:

        case TIFF_PHOTOMETRIC_LOG_L:

        case TIFF_PHOTOMETRIC_LOG_LUV:

        case TIFF_PHOTOMETRIC_LINEAR_RAW:

            avpriv_report_missing_feature(s->avctx,

                                          "PhotometricInterpretation 0x%04X",

                                          value);

            return AVERROR_PATCHWELCOME;

        default:

            av_log(s->avctx, AV_LOG_ERROR, "PhotometricInterpretation %u is "

                   "unknown\n", value);

            return AVERROR_INVALIDDATA;

        }

        break;

    case TIFF_FILL_ORDER:

        if (value < 1 || value > 2) {

            av_log(s->avctx, AV_LOG_ERROR,

                   "Unknown FillOrder value %d, trying default one\n", value);

            value = 1;

        }

        s->fill_order = value - 1;

        break;

    case TIFF_PAL: {

        GetByteContext pal_gb[3];

        off = type_sizes[type];

        if (count / 3 > 256 ||

            bytestream2_get_bytes_left(&s->gb) < count / 3 * off * 3)

            return AVERROR_INVALIDDATA;



        pal_gb[0] = pal_gb[1] = pal_gb[2] = s->gb;

        bytestream2_skip(&pal_gb[1], count / 3 * off);

        bytestream2_skip(&pal_gb[2], count / 3 * off * 2);



        off = (type_sizes[type] - 1) << 3;

        for (i = 0; i < count / 3; i++) {

            uint32_t p = 0xFF000000;

            p |= (ff_tget(&pal_gb[0], type, s->le) >> off) << 16;

            p |= (ff_tget(&pal_gb[1], type, s->le) >> off) << 8;

            p |=  ff_tget(&pal_gb[2], type, s->le) >> off;

            s->palette[i] = p;

        }

        s->palette_is_set = 1;

        break;

    }

    case TIFF_PLANAR:

        s->planar = value == 2;

        break;

    case TIFF_YCBCR_SUBSAMPLING:

        if (count != 2) {

            av_log(s->avctx, AV_LOG_ERROR, "subsample count invalid\n");

            return AVERROR_INVALIDDATA;

        }

        for (i = 0; i < count; i++)

            s->subsampling[i] = ff_tget(&s->gb, type, s->le);

        break;

    case TIFF_T4OPTIONS:

        if (s->compr == TIFF_G3)

            s->fax_opts = value;

        break;

    case TIFF_T6OPTIONS:

        if (s->compr == TIFF_G4)

            s->fax_opts = value;

        break;

#define ADD_METADATA(count, name, sep)\

    if ((ret = add_metadata(count, type, name, sep, s, frame)) < 0) {\

        av_log(s->avctx, AV_LOG_ERROR, "Error allocating temporary buffer\n");\

        goto end;\

    }

    case TIFF_MODEL_PIXEL_SCALE:

        ADD_METADATA(count, "ModelPixelScaleTag", NULL);

        break;

    case TIFF_MODEL_TRANSFORMATION:

        ADD_METADATA(count, "ModelTransformationTag", NULL);

        break;

    case TIFF_MODEL_TIEPOINT:

        ADD_METADATA(count, "ModelTiepointTag", NULL);

        break;

    case TIFF_GEO_KEY_DIRECTORY:

        ADD_METADATA(1, "GeoTIFF_Version", NULL);

        ADD_METADATA(2, "GeoTIFF_Key_Revision", ".");

        s->geotag_count   = ff_tget_short(&s->gb, s->le);

        if (s->geotag_count > count / 4 - 1) {

            s->geotag_count = count / 4 - 1;

            av_log(s->avctx, AV_LOG_WARNING, "GeoTIFF key directory buffer shorter than specified\n");

        }

        if (bytestream2_get_bytes_left(&s->gb) < s->geotag_count * sizeof(int16_t) * 4) {

            s->geotag_count = 0;

            return -1;

        }

        s->geotags = av_mallocz_array(s->geotag_count, sizeof(TiffGeoTag));

        if (!s->geotags) {

            av_log(s->avctx, AV_LOG_ERROR, "Error allocating temporary buffer\n");

            s->geotag_count = 0;

            goto end;

        }

        for (i = 0; i < s->geotag_count; i++) {

            s->geotags[i].key    = ff_tget_short(&s->gb, s->le);

            s->geotags[i].type   = ff_tget_short(&s->gb, s->le);

            s->geotags[i].count  = ff_tget_short(&s->gb, s->le);



            if (!s->geotags[i].type)

                s->geotags[i].val  = get_geokey_val(s->geotags[i].key, ff_tget_short(&s->gb, s->le));

            else

                s->geotags[i].offset = ff_tget_short(&s->gb, s->le);

        }

        break;

    case TIFF_GEO_DOUBLE_PARAMS:

        if (count >= INT_MAX / sizeof(int64_t))

            return AVERROR_INVALIDDATA;

        if (bytestream2_get_bytes_left(&s->gb) < count * sizeof(int64_t))

            return AVERROR_INVALIDDATA;

        dp = av_malloc_array(count, sizeof(double));

        if (!dp) {

            av_log(s->avctx, AV_LOG_ERROR, "Error allocating temporary buffer\n");

            goto end;

        }

        for (i = 0; i < count; i++)

            dp[i] = ff_tget_double(&s->gb, s->le);

        for (i = 0; i < s->geotag_count; i++) {

            if (s->geotags[i].type == TIFF_GEO_DOUBLE_PARAMS) {

                if (s->geotags[i].count == 0

                    || s->geotags[i].offset + s->geotags[i].count > count) {

                    av_log(s->avctx, AV_LOG_WARNING, "Invalid GeoTIFF key %d\n", s->geotags[i].key);

                } else {

                    char *ap = doubles2str(&dp[s->geotags[i].offset], s->geotags[i].count, ", ");

                    if (!ap) {

                        av_log(s->avctx, AV_LOG_ERROR, "Error allocating temporary buffer\n");

                        av_freep(&dp);

                        return AVERROR(ENOMEM);

                    }

                    s->geotags[i].val = ap;

                }

            }

        }

        av_freep(&dp);

        break;

    case TIFF_GEO_ASCII_PARAMS:

        pos = bytestream2_tell(&s->gb);

        for (i = 0; i < s->geotag_count; i++) {

            if (s->geotags[i].type == TIFF_GEO_ASCII_PARAMS) {

                if (s->geotags[i].count == 0

                    || s->geotags[i].offset +  s->geotags[i].count > count) {

                    av_log(s->avctx, AV_LOG_WARNING, "Invalid GeoTIFF key %d\n", s->geotags[i].key);

                } else {

                    char *ap;



                    bytestream2_seek(&s->gb, pos + s->geotags[i].offset, SEEK_SET);

                    if (bytestream2_get_bytes_left(&s->gb) < s->geotags[i].count)

                        return AVERROR_INVALIDDATA;

                    ap = av_malloc(s->geotags[i].count);

                    if (!ap) {

                        av_log(s->avctx, AV_LOG_ERROR, "Error allocating temporary buffer\n");

                        return AVERROR(ENOMEM);

                    }

                    bytestream2_get_bufferu(&s->gb, ap, s->geotags[i].count);

                    ap[s->geotags[i].count - 1] = '\0'; //replace the "|" delimiter with a 0 byte

                    s->geotags[i].val = ap;

                }

            }

        }

        break;

    case TIFF_ARTIST:

        ADD_METADATA(count, "artist", NULL);

        break;

    case TIFF_COPYRIGHT:

        ADD_METADATA(count, "copyright", NULL);

        break;

    case TIFF_DATE:

        ADD_METADATA(count, "date", NULL);

        break;

    case TIFF_DOCUMENT_NAME:

        ADD_METADATA(count, "document_name", NULL);

        break;

    case TIFF_HOST_COMPUTER:

        ADD_METADATA(count, "computer", NULL);

        break;

    case TIFF_IMAGE_DESCRIPTION:

        ADD_METADATA(count, "description", NULL);

        break;

    case TIFF_MAKE:

        ADD_METADATA(count, "make", NULL);

        break;

    case TIFF_MODEL:

        ADD_METADATA(count, "model", NULL);

        break;

    case TIFF_PAGE_NAME:

        ADD_METADATA(count, "page_name", NULL);

        break;

    case TIFF_PAGE_NUMBER:

        ADD_METADATA(count, "page_number", " / ");

        break;

    case TIFF_SOFTWARE_NAME:

        ADD_METADATA(count, "software", NULL);

        break;

    default:

        if (s->avctx->err_recognition & AV_EF_EXPLODE) {

            av_log(s->avctx, AV_LOG_ERROR,

                   "Unknown or unsupported tag %d/0X%0X\n",

                   tag, tag);

            return AVERROR_INVALIDDATA;

        }

    }

end:

    bytestream2_seek(&s->gb, start, SEEK_SET);

    return 0;

}

static int reap_filters(void)

{

    AVFilterBufferRef *picref;

    AVFrame *filtered_frame = NULL;

    int i;

    int64_t frame_pts;



    /* Reap all buffers present in the buffer sinks */

    for (i = 0; i < nb_output_streams; i++) {

        OutputStream *ost = output_streams[i];

        OutputFile    *of = output_files[ost->file_index];

        int ret = 0;



        if (!ost->filter)

            continue;



        if (!ost->filtered_frame && !(ost->filtered_frame = avcodec_alloc_frame())) {

            return AVERROR(ENOMEM);

        } else

            avcodec_get_frame_defaults(ost->filtered_frame);

        filtered_frame = ost->filtered_frame;



        while (1) {

            ret = av_buffersink_get_buffer_ref(ost->filter->filter, &picref,

                                               AV_BUFFERSINK_FLAG_NO_REQUEST);

            if (ret < 0) {

                if (ret != AVERROR(EAGAIN) && ret != AVERROR_EOF) {

                    char buf[256];

                    av_strerror(ret, buf, sizeof(buf));

                    av_log(NULL, AV_LOG_WARNING,

                           "Error in av_buffersink_get_buffer_ref(): %s\n", buf);




            frame_pts = AV_NOPTS_VALUE;

            if (picref->pts != AV_NOPTS_VALUE) {

                filtered_frame->pts = frame_pts = av_rescale_q(picref->pts,

                                                ost->filter->filter->inputs[0]->time_base,

                                                ost->st->codec->time_base) -

                                    av_rescale_q(of->start_time,

                                                AV_TIME_BASE_Q,

                                                ost->st->codec->time_base);



                if (of->start_time && filtered_frame->pts < 0) {

                    avfilter_unref_buffer(picref);

                    continue;



            //if (ost->source_index >= 0)

            //    *filtered_frame= *input_streams[ost->source_index]->decoded_frame; //for me_threshold





            switch (ost->filter->filter->inputs[0]->type) {

            case AVMEDIA_TYPE_VIDEO:

                avfilter_copy_buf_props(filtered_frame, picref);

                filtered_frame->pts = frame_pts;

                if (!ost->frame_aspect_ratio)

                    ost->st->codec->sample_aspect_ratio = picref->video->sample_aspect_ratio;



                do_video_out(of->ctx, ost, filtered_frame);


            case AVMEDIA_TYPE_AUDIO:

                avfilter_copy_buf_props(filtered_frame, picref);

                filtered_frame->pts = frame_pts;







                do_audio_out(of->ctx, ost, filtered_frame);


            default:

                // TODO support subtitle filters

                av_assert0(0);




            avfilter_unref_buffer(picref);





    return 0;

static av_always_inline void hl_decode_mb_predict_luma(H264Context *h, int mb_type, int is_h264, int simple, int transform_bypass,

                                                       int pixel_shift, int *block_offset, int linesize, uint8_t *dest_y, int p)

{

    MpegEncContext * const s = &h->s;

    void (*idct_add)(uint8_t *dst, DCTELEM *block, int stride);

    void (*idct_dc_add)(uint8_t *dst, DCTELEM *block, int stride);

    int i;

    int qscale = p == 0 ? s->qscale : h->chroma_qp[p-1];

    block_offset += 16*p;

    if(IS_INTRA4x4(mb_type)){

        if(simple || !s->encoding){

            if(IS_8x8DCT(mb_type)){

                if(transform_bypass){

                    idct_dc_add =

                    idct_add    = s->dsp.add_pixels8;

                }else{

                    idct_dc_add = h->h264dsp.h264_idct8_dc_add;

                    idct_add    = h->h264dsp.h264_idct8_add;

                }

                for(i=0; i<16; i+=4){

                    uint8_t * const ptr= dest_y + block_offset[i];

                    const int dir= h->intra4x4_pred_mode_cache[ scan8[i] ];

                    if(transform_bypass && h->sps.profile_idc==244 && dir<=1){

                        h->hpc.pred8x8l_add[dir](ptr, h->mb + (i*16+p*256 << pixel_shift), linesize);

                    }else{

                        const int nnz = h->non_zero_count_cache[ scan8[i+p*16] ];

                        h->hpc.pred8x8l[ dir ](ptr, (h->topleft_samples_available<<i)&0x8000,

                                                    (h->topright_samples_available<<i)&0x4000, linesize);

                        if(nnz){

                            if(nnz == 1 && dctcoef_get(h->mb, pixel_shift, i*16+p*256))

                                idct_dc_add(ptr, h->mb + (i*16+p*256 << pixel_shift), linesize);

                            else

                                idct_add   (ptr, h->mb + (i*16+p*256 << pixel_shift), linesize);

                        }

                    }

                }

            }else{

                if(transform_bypass){

                    idct_dc_add =

                    idct_add    = s->dsp.add_pixels4;

                }else{

                    idct_dc_add = h->h264dsp.h264_idct_dc_add;

                    idct_add    = h->h264dsp.h264_idct_add;

                }

                for(i=0; i<16; i++){

                    uint8_t * const ptr= dest_y + block_offset[i];

                    const int dir= h->intra4x4_pred_mode_cache[ scan8[i] ];



                    if(transform_bypass && h->sps.profile_idc==244 && dir<=1){

                        h->hpc.pred4x4_add[dir](ptr, h->mb + (i*16+p*256 << pixel_shift), linesize);

                    }else{

                        uint8_t *topright;

                        int nnz, tr;

                        uint64_t tr_high;

                        if(dir == DIAG_DOWN_LEFT_PRED || dir == VERT_LEFT_PRED){

                            const int topright_avail= (h->topright_samples_available<<i)&0x8000;

                            assert(s->mb_y || linesize <= block_offset[i]);

                            if(!topright_avail){

                                if (pixel_shift) {

                                    tr_high= ((uint16_t*)ptr)[3 - linesize/2]*0x0001000100010001ULL;

                                    topright= (uint8_t*) &tr_high;

                                } else {

                                    tr= ptr[3 - linesize]*0x01010101;

                                    topright= (uint8_t*) &tr;

                                }

                            }else

                                topright= ptr + (4 << pixel_shift) - linesize;

                        }else

                            topright= NULL;



                        h->hpc.pred4x4[ dir ](ptr, topright, linesize);

                        nnz = h->non_zero_count_cache[ scan8[i+p*16] ];

                        if(nnz){

                            if(is_h264){

                                if(nnz == 1 && dctcoef_get(h->mb, pixel_shift, i*16+p*256))

                                    idct_dc_add(ptr, h->mb + (i*16+p*256 << pixel_shift), linesize);

                                else

                                    idct_add   (ptr, h->mb + (i*16+p*256 << pixel_shift), linesize);

                            }else

                                ff_svq3_add_idct_c(ptr, h->mb + i*16+p*256, linesize, qscale, 0);

                        }

                    }

                }

            }

        }

    }else{

        h->hpc.pred16x16[ h->intra16x16_pred_mode ](dest_y , linesize);

        if(is_h264){

            if(h->non_zero_count_cache[ scan8[LUMA_DC_BLOCK_INDEX+p] ]){

                if(!transform_bypass)

                    h->h264dsp.h264_luma_dc_dequant_idct(h->mb+(p*256 << pixel_shift), h->mb_luma_dc[p], h->dequant4_coeff[p][qscale][0]);

                else{

                    static const uint8_t dc_mapping[16] = { 0*16, 1*16, 4*16, 5*16, 2*16, 3*16, 6*16, 7*16,

                                                            8*16, 9*16,12*16,13*16,10*16,11*16,14*16,15*16};

                    for(i = 0; i < 16; i++)

                        dctcoef_set(h->mb+p*256, pixel_shift, dc_mapping[i], dctcoef_get(h->mb_luma_dc[p], pixel_shift, i));

                }

            }

        }else

            ff_svq3_luma_dc_dequant_idct_c(h->mb+p*256, h->mb_luma_dc[p], qscale);

    }

}

static int adx_read_packet(AVFormatContext *s, AVPacket *pkt)
{
    ADXDemuxerContext *c = s->priv_data;
    AVCodecContext *avctx = s->streams[0]->codec;
    int ret, size;
    size = BLOCK_SIZE * avctx->channels;
    pkt->pos = avio_tell(s->pb);
    pkt->stream_index = 0;
    ret = av_get_packet(s->pb, pkt, size);
    if (ret != size) {
        av_free_packet(pkt);
        return ret < 0 ? ret : AVERROR(EIO);
    if (AV_RB16(pkt->data) & 0x8000) {
        av_free_packet(pkt);
        return AVERROR_EOF;
    pkt->size     = size;
    pkt->duration = 1;
    pkt->pts      = (pkt->pos - c->header_size) / size;
    return 0;

static int put_flac_codecpriv(AVFormatContext *s, ByteIOContext *pb, AVCodecContext *codec)

{

    // if the extradata_size is greater than FLAC_STREAMINFO_SIZE,

    // assume that it's in Matroska format already

    if (codec->extradata_size < FLAC_STREAMINFO_SIZE) {

        av_log(s, AV_LOG_ERROR, "Invalid FLAC extradata\n");

        return -1;

    } else if (codec->extradata_size == FLAC_STREAMINFO_SIZE) {

        // only the streaminfo packet

        put_buffer(pb, "fLaC", 4);

        put_byte(pb, 0x80);

        put_be24(pb, FLAC_STREAMINFO_SIZE);

    } else if(memcmp("fLaC", codec->extradata, 4)) {

        av_log(s, AV_LOG_ERROR, "Invalid FLAC extradata\n");

        return -1;

    }

    put_buffer(pb, codec->extradata, codec->extradata_size);

    return 0;

}

int avcodec_open(AVCodecContext *avctx, AVCodec *codec)

{

    int ret;



    if(avctx->codec)

        return -1;



    avctx->codec = codec;

    avctx->codec_id = codec->id;

    avctx->frame_number = 0;

    if (codec->priv_data_size > 0) {

        avctx->priv_data = av_mallocz(codec->priv_data_size);

        if (!avctx->priv_data) 

            return -ENOMEM;

    } else {

        avctx->priv_data = NULL;

    }



    if(avctx->coded_width && avctx->coded_height)

        avcodec_set_dimensions(avctx, avctx->coded_width, avctx->coded_height);

    else if(avctx->width && avctx->height)

        avcodec_set_dimensions(avctx, avctx->width, avctx->height);



    if((avctx->coded_width||avctx->coded_height) && avcodec_check_dimensions(avctx,avctx->coded_width,avctx->coded_height)){

        av_freep(&avctx->priv_data);

        return -1;

    }



    ret = avctx->codec->init(avctx);

    if (ret < 0) {

        av_freep(&avctx->priv_data);

        return ret;

    }

    return 0;

}

static int decode_block_coeffs_internal(VP56RangeCoder *r, int16_t block[16],

                                        uint8_t probs[16][3][NUM_DCT_TOKENS - 1],

                                        int i, uint8_t *token_prob,

                                        int16_t qmul[2])

{

    VP56RangeCoder c = *r;

    goto skip_eob;

    do {

        int coeff;

        if (!vp56_rac_get_prob_branchy(&c, token_prob[0]))   // DCT_EOB

            break;



skip_eob:

        if (!vp56_rac_get_prob_branchy(&c, token_prob[1])) { // DCT_0

            if (++i == 16)

                break; // invalid input; blocks should end with EOB

            token_prob = probs[i][0];

            goto skip_eob;

        }



        if (!vp56_rac_get_prob_branchy(&c, token_prob[2])) { // DCT_1

            coeff = 1;

            token_prob = probs[i + 1][1];

        } else {

            if (!vp56_rac_get_prob_branchy(&c, token_prob[3])) { // DCT 2,3,4

                coeff = vp56_rac_get_prob_branchy(&c, token_prob[4]);

                if (coeff)

                    coeff += vp56_rac_get_prob(&c, token_prob[5]);

                coeff += 2;

            } else {

                // DCT_CAT*

                if (!vp56_rac_get_prob_branchy(&c, token_prob[6])) {

                    if (!vp56_rac_get_prob_branchy(&c, token_prob[7])) { // DCT_CAT1

                        coeff = 5 + vp56_rac_get_prob(&c, vp8_dct_cat1_prob[0]);

                    } else {                                    // DCT_CAT2

                        coeff  = 7;

                        coeff += vp56_rac_get_prob(&c, vp8_dct_cat2_prob[0]) << 1;

                        coeff += vp56_rac_get_prob(&c, vp8_dct_cat2_prob[1]);

                    }

                } else {    // DCT_CAT3 and up

                    int a   = vp56_rac_get_prob(&c, token_prob[8]);

                    int b   = vp56_rac_get_prob(&c, token_prob[9 + a]);

                    int cat = (a << 1) + b;

                    coeff  = 3 + (8 << cat);

                    coeff += vp8_rac_get_coeff(&c, ff_vp8_dct_cat_prob[cat]);

                }

            }

            token_prob = probs[i + 1][2];

        }

        block[zigzag_scan[i]] = (vp8_rac_get(&c) ? -coeff : coeff) * qmul[!!i];

    } while (++i < 16);



    *r = c;

    return i;

}

static void imdct12(INTFLOAT *out, INTFLOAT *in)

{

    INTFLOAT in0, in1, in2, in3, in4, in5, t1, t2;



    in0  = in[0*3];

    in1  = in[1*3] + in[0*3];

    in2  = in[2*3] + in[1*3];

    in3  = in[3*3] + in[2*3];

    in4  = in[4*3] + in[3*3];

    in5  = in[5*3] + in[4*3];

    in5 += in3;

    in3 += in1;



    in2  = MULH3(in2, C3, 2);

    in3  = MULH3(in3, C3, 4);



    t1   = in0 - in4;

    t2   = MULH3(in1 - in5, C4, 2);



    out[ 7] =

    out[10] = t1 + t2;

    out[ 1] =

    out[ 4] = t1 - t2;



    in0    += SHR(in4, 1);

    in4     = in0 + in2;

    in5    += 2*in1;

    in1     = MULH3(in5 + in3, C5, 1);

    out[ 8] =

    out[ 9] = in4 + in1;

    out[ 2] =

    out[ 3] = in4 - in1;



    in0    -= in2;

    in5     = MULH3(in5 - in3, C6, 2);

    out[ 0] =

    out[ 5] = in0 - in5;

    out[ 6] =

    out[11] = in0 + in5;

}

static int dxa_read_header(AVFormatContext *s, AVFormatParameters *ap)

{

    AVIOContext *pb = s->pb;

    DXAContext *c = s->priv_data;

    AVStream *st, *ast;

    uint32_t tag;

    int32_t fps;

    int w, h;

    int num, den;

    int flags;



    tag = avio_rl32(pb);

    if (tag != MKTAG('D', 'E', 'X', 'A'))

        return -1;

    flags = avio_r8(pb);

    c->frames = avio_rb16(pb);

    if(!c->frames){

        av_log(s, AV_LOG_ERROR, "File contains no frames ???\n");

        return -1;

    }



    fps = avio_rb32(pb);

    if(fps > 0){

        den = 1000;

        num = fps;

    }else if (fps < 0){

        den = 100000;

        num = -fps;

    }else{

        den = 10;

        num = 1;

    }

    w = avio_rb16(pb);

    h = avio_rb16(pb);

    c->has_sound = 0;



    st = av_new_stream(s, 0);

    if (!st)

        return -1;



    // Parse WAV data header

    if(avio_rl32(pb) == MKTAG('W', 'A', 'V', 'E')){

        uint32_t size, fsize;

        c->has_sound = 1;

        size = avio_rb32(pb);

        c->vidpos = avio_tell(pb) + size;

        avio_skip(pb, 16);

        fsize = avio_rl32(pb);



        ast = av_new_stream(s, 0);

        if (!ast)

            return -1;

        ff_get_wav_header(pb, ast->codec, fsize);

        // find 'data' chunk

        while(avio_tell(pb) < c->vidpos && !pb->eof_reached){

            tag = avio_rl32(pb);

            fsize = avio_rl32(pb);

            if(tag == MKTAG('d', 'a', 't', 'a')) break;

            avio_skip(pb, fsize);

        }

        c->bpc = (fsize + c->frames - 1) / c->frames;

        if(ast->codec->block_align)

            c->bpc = ((c->bpc + ast->codec->block_align - 1) / ast->codec->block_align) * ast->codec->block_align;

        c->bytes_left = fsize;

        c->wavpos = avio_tell(pb);

        avio_seek(pb, c->vidpos, SEEK_SET);

    }



    /* now we are ready: build format streams */

    st->codec->codec_type = AVMEDIA_TYPE_VIDEO;

    st->codec->codec_id   = CODEC_ID_DXA;

    st->codec->width      = w;

    st->codec->height     = h;

    av_reduce(&den, &num, den, num, (1UL<<31)-1);

    av_set_pts_info(st, 33, num, den);

    /* flags & 0x80 means that image is interlaced,

     * flags & 0x40 means that image has double height

     * either way set true height

     */

    if(flags & 0xC0){

        st->codec->height >>= 1;

    }

    c->readvid = !c->has_sound;

    c->vidpos  = avio_tell(pb);

    s->start_time = 0;

    s->duration = (int64_t)c->frames * AV_TIME_BASE * num / den;

    av_log(s, AV_LOG_DEBUG, "%d frame(s)\n",c->frames);



    return 0;

}

static int get_cv_color_primaries(AVCodecContext *avctx,

                                  CFStringRef *primaries)

{

    enum AVColorPrimaries pri = avctx->color_primaries;

    switch (pri) {

        case AVCOL_PRI_UNSPECIFIED:

            *primaries = NULL;

            break;



        case AVCOL_PRI_BT709:

            *primaries = kCVImageBufferColorPrimaries_ITU_R_709_2;

            break;



        case AVCOL_PRI_BT2020:

            *primaries = kCVImageBufferColorPrimaries_ITU_R_2020;

            break;



        default:

            av_log(avctx, AV_LOG_ERROR, "Color primaries %s is not supported.\n", av_color_primaries_name(pri));

            *primaries = NULL;

            return -1;

    }



    return 0;

}

static void avc_wgt_4x4multiple_msa(uint8_t *data,

                                    int32_t stride,

                                    int32_t height,

                                    int32_t log2_denom,

                                    int32_t src_weight,

                                    int32_t offset_in)

{

    uint8_t cnt;

    uint32_t data0, data1, data2, data3;

    v16u8 zero = { 0 };

    v16u8 src0, src1, src2, src3;

    v8u16 temp0, temp1, temp2, temp3;

    v8i16 wgt, denom, offset;



    offset_in <<= (log2_denom);



    if (log2_denom) {

        offset_in += (1 << (log2_denom - 1));

    }



    wgt = __msa_fill_h(src_weight);

    offset = __msa_fill_h(offset_in);

    denom = __msa_fill_h(log2_denom);



    for (cnt = height / 4; cnt--;) {

        LOAD_4WORDS_WITH_STRIDE(data, stride, data0, data1, data2, data3);



        src0 = (v16u8) __msa_fill_w(data0);

        src1 = (v16u8) __msa_fill_w(data1);

        src2 = (v16u8) __msa_fill_w(data2);

        src3 = (v16u8) __msa_fill_w(data3);



        ILVR_B_4VECS_UH(src0, src1, src2, src3, zero, zero, zero, zero,

                        temp0, temp1, temp2, temp3);



        temp0 *= wgt;

        temp1 *= wgt;

        temp2 *= wgt;

        temp3 *= wgt;



        ADDS_S_H_4VECS_UH(temp0, offset, temp1, offset,

                          temp2, offset, temp3, offset,

                          temp0, temp1, temp2, temp3);



        MAXI_S_H_4VECS_UH(temp0, temp1, temp2, temp3, 0);



        SRL_H_4VECS_UH(temp0, temp1, temp2, temp3,

                       temp0, temp1, temp2, temp3, denom);



        SAT_U_H_4VECS_UH(temp0, temp1, temp2, temp3, 7);



        PCKEV_B_STORE_4_BYTES_4(temp0, temp1, temp2, temp3, data, stride);

        data += (4 * stride);

    }

}

static void FUNC(flac_decorrelate_indep_c)(uint8_t **out, int32_t **in,

                                           int channels, int len, int shift)

{

