}

static int mov_open_dref(MOVContext *c, AVIOContext **pb, const char *src, MOVDref *ref,

                         AVIOInterruptCB *int_cb)

{

    AVOpenCallback open_func = c->fc->open_cb;



    if (!open_func)

        open_func = ffio_open2_wrapper;



    /* try relative path, we do not try the absolute because it can leak information about our

       system to an attacker */

    if (ref->nlvl_to > 0 && ref->nlvl_from > 0 && ref->path[0] != '/') {

        char filename[1025];

        const char *src_path;

        int i, l;



        /* find a source dir */

        src_path = strrchr(src, '/');

        if (src_path)

            src_path++;

        else

            src_path = src;



        /* find a next level down to target */

        for (i = 0, l = strlen(ref->path) - 1; l >= 0; l--)

            if (ref->path[l] == '/') {

                if (i == ref->nlvl_to - 1)

                    break;

                else

                    i++;

            }



        /* compose filename if next level down to target was found */

        if (i == ref->nlvl_to - 1 && src_path - src  < sizeof(filename)) {

            memcpy(filename, src, src_path - src);

            filename[src_path - src] = 0;



            for (i = 1; i < ref->nlvl_from; i++)

                av_strlcat(filename, "../", sizeof(filename));



            av_strlcat(filename, ref->path + l + 1, sizeof(filename));

            if (!c->use_absolute_path && !c->fc->open_cb)

                if(strstr(ref->path + l + 1, "..") || ref->nlvl_from > 1)

                    return AVERROR(ENOENT);



            if (strlen(filename) + 1 == sizeof(filename))

                return AVERROR(ENOENT);

            if (!open_func(c->fc, pb, filename, AVIO_FLAG_READ, int_cb, NULL))

                return 0;

        }

    } else if (c->use_absolute_path) {

        av_log(c->fc, AV_LOG_WARNING, "Using absolute path on user request, "

               "this is a possible security issue\n");

        if (!open_func(c->fc, pb, ref->path, AVIO_FLAG_READ, int_cb, NULL))

            return 0;

    } else if (c->fc->open_cb) {

        if (!open_func(c->fc, pb, ref->path, AVIO_FLAG_READ, int_cb, NULL))

            return 0;

    } else {

        av_log(c->fc, AV_LOG_ERROR,

               "Absolute path %s not tried for security reasons, "

               "set demuxer option use_absolute_path to allow absolute paths\n",

               ref->path);

    }



    return AVERROR(ENOENT);

}

static void filter_mb_edgev( H264Context *h, uint8_t *pix, int stride, int16_t bS[4], int qp ) {

    int i, d;

    const int index_a = qp + h->slice_alpha_c0_offset;

    const int alpha = (alpha_table+52)[index_a];

    const int beta  = (beta_table+52)[qp + h->slice_beta_offset];



    if( bS[0] < 4 ) {

        int8_t tc[4];

        for(i=0; i<4; i++)

            tc[i] = bS[i] ? (tc0_table+52)[index_a][bS[i] - 1] : -1;

        h->s.dsp.h264_h_loop_filter_luma(pix, stride, alpha, beta, tc);

    } else {

        h->s.dsp.h264_h_loop_filter_luma_intra(pix, stride, alpha, beta);

    }

}

static void selfTest(uint8_t *src[4], int stride[4], int w, int h){

    enum PixelFormat srcFormat, dstFormat;

    int srcW, srcH, dstW, dstH;

    int flags;



    for (srcFormat = 0; srcFormat < PIX_FMT_NB; srcFormat++) {

        for (dstFormat = 0; dstFormat < PIX_FMT_NB; dstFormat++) {

            printf("%s -> %s\n",

                   sws_format_name(srcFormat),

                   sws_format_name(dstFormat));

            fflush(stdout);



            srcW= w;

            srcH= h;

            for (dstW=w - w/3; dstW<= 4*w/3; dstW+= w/3){

                for (dstH=h - h/3; dstH<= 4*h/3; dstH+= h/3){

                    for (flags=1; flags<33; flags*=2) {

                        int res;



                        res = doTest(src, stride, w, h, srcFormat, dstFormat,

                                     srcW, srcH, dstW, dstH, flags);

                        if (res < 0) {

                            dstW = 4 * w / 3;

                            dstH = 4 * h / 3;

                            flags = 33;

                        }

                    }

                }

            }

        }

    }

}

void ff_eac3_apply_spectral_extension(AC3DecodeContext *s)

{

    int bin, bnd, ch, i;

    uint8_t wrapflag[SPX_MAX_BANDS]={1,0,}, num_copy_sections, copy_sizes[SPX_MAX_BANDS];

    float rms_energy[SPX_MAX_BANDS];



    /* Set copy index mapping table. Set wrap flags to apply a notch filter at

       wrap points later on. */

    bin = s->spx_dst_start_freq;

    num_copy_sections = 0;

    for (bnd = 0; bnd < s->num_spx_bands; bnd++) {

        int copysize;

        int bandsize = s->spx_band_sizes[bnd];

        if (bin + bandsize > s->spx_src_start_freq) {

            copy_sizes[num_copy_sections++] = bin - s->spx_dst_start_freq;

            bin = s->spx_dst_start_freq;

            wrapflag[bnd] = 1;

        }

        for (i = 0; i < bandsize; i += copysize) {

            if (bin == s->spx_src_start_freq) {

                copy_sizes[num_copy_sections++] = bin - s->spx_dst_start_freq;

                bin = s->spx_dst_start_freq;

            }

            copysize = FFMIN(bandsize - i, s->spx_src_start_freq - bin);

            bin += copysize;

        }

    }

    copy_sizes[num_copy_sections++] = bin - s->spx_dst_start_freq;



    for (ch = 1; ch <= s->fbw_channels; ch++) {

        if (!s->channel_uses_spx[ch])

            continue;



        /* Copy coeffs from normal bands to extension bands */

        bin = s->spx_src_start_freq;

        for (i = 0; i < num_copy_sections; i++) {

            memcpy(&s->transform_coeffs[ch][bin],

                   &s->transform_coeffs[ch][s->spx_dst_start_freq],

                   copy_sizes[i]*sizeof(float));

            bin += copy_sizes[i];

        }



        /* Calculate RMS energy for each SPX band. */

        bin = s->spx_src_start_freq;

        for (bnd = 0; bnd < s->num_spx_bands; bnd++) {

            int bandsize = s->spx_band_sizes[bnd];

            float accum = 0.0f;

            for (i = 0; i < bandsize; i++) {

                float coeff = s->transform_coeffs[ch][bin++];

                accum += coeff * coeff;

            }

            rms_energy[bnd] = sqrtf(accum / bandsize);

        }



        /* Apply a notch filter at transitions between normal and extension

           bands and at all wrap points. */

        if (s->spx_atten_code[ch] >= 0) {

            const float *atten_tab = ff_eac3_spx_atten_tab[s->spx_atten_code[ch]];

            bin = s->spx_src_start_freq - 2;

            for (bnd = 0; bnd < s->num_spx_bands; bnd++) {

                if (wrapflag[bnd]) {

                    float *coeffs = &s->transform_coeffs[ch][bin];

                    coeffs[0] *= atten_tab[0];

                    coeffs[1] *= atten_tab[1];

                    coeffs[2] *= atten_tab[2];

                    coeffs[3] *= atten_tab[1];

                    coeffs[4] *= atten_tab[0];

                }

                bin += s->spx_band_sizes[bnd];

            }

        }



        /* Apply noise-blended coefficient scaling based on previously

           calculated RMS energy, blending factors, and SPX coordinates for

           each band. */

        bin = s->spx_src_start_freq;

        for (bnd = 0; bnd < s->num_spx_bands; bnd++) {

            float nscale = s->spx_noise_blend[ch][bnd] * rms_energy[bnd] * (1.0f / INT32_MIN);

            float sscale = s->spx_signal_blend[ch][bnd];

            for (i = 0; i < s->spx_band_sizes[bnd]; i++) {

                float noise  = nscale * (int32_t)av_lfg_get(&s->dith_state);

                s->transform_coeffs[ch][bin]   *= sscale;

                s->transform_coeffs[ch][bin++] += noise;

            }

        }

    }

}

static int add_crc_to_array(uint32_t crc, int64_t pts)

{

    if (size_of_array <= number_of_elements) {

        if (size_of_array == 0)

            size_of_array = 10;

        size_of_array *= 2;

        crc_array = av_realloc(crc_array, size_of_array * sizeof(uint32_t));

        pts_array = av_realloc(pts_array, size_of_array * sizeof(int64_t));

        if ((crc_array == NULL) || (pts_array == NULL)) {

            av_log(NULL, AV_LOG_ERROR, "Can't allocate array to store crcs\n");

            return AVERROR(ENOMEM);

        }

    }

    crc_array[number_of_elements] = crc;

    pts_array[number_of_elements] = pts;

    number_of_elements++;

    return 0;

}

static av_cold void init_mv_penalty_and_fcode(MpegEncContext *s)

{

    int f_code;

    int mv;



    for(f_code=1; f_code<=MAX_FCODE; f_code++){

        for(mv=-MAX_MV; mv<=MAX_MV; mv++){

            int len;



            if(mv==0) len= ff_mvtab[0][1];

            else{

                int val, bit_size, code;



                bit_size = f_code - 1;



                val=mv;

                if (val < 0)

                    val = -val;

                val--;

                code = (val >> bit_size) + 1;

                if(code<33){

                    len= ff_mvtab[code][1] + 1 + bit_size;

                }else{

                    len= ff_mvtab[32][1] + av_log2(code>>5) + 2 + bit_size;

                }

            }



            mv_penalty[f_code][mv+MAX_MV]= len;

        }

    }



    for(f_code=MAX_FCODE; f_code>0; f_code--){

        for(mv=-(16<<f_code); mv<(16<<f_code); mv++){

            fcode_tab[mv+MAX_MV]= f_code;

        }

    }



    for(mv=0; mv<MAX_MV*2+1; mv++){

        umv_fcode_tab[mv]= 1;

    }

}

static av_always_inline int setup_classifs(vorbis_context *vc,

                                           vorbis_residue *vr,

                                           uint8_t *do_not_decode,

                                           unsigned ch_used,

                                           int partition_count)

{

    int p, j, i;

    unsigned c_p_c         = vc->codebooks[vr->classbook].dimensions;

    unsigned inverse_class = ff_inverse[vr->classifications];

    unsigned temp, temp2;

    for (p = 0, j = 0; j < ch_used; ++j) {

        if (!do_not_decode[j]) {

            temp = get_vlc2(&vc->gb, vc->codebooks[vr->classbook].vlc.table,

                                     vc->codebooks[vr->classbook].nb_bits, 3);



            av_dlog(NULL, "Classword: %u\n", temp);



            assert(vr->classifications > 1 && temp <= 65536); //needed for inverse[]



            for (i = 0; i < c_p_c; ++i) {

                temp2 = (((uint64_t)temp) * inverse_class) >> 32;

                if (partition_count + c_p_c - 1 - i < vr->ptns_to_read)

                    vr->classifs[p + partition_count + c_p_c - 1 - i] =

                        temp - temp2 * vr->classifications;

                temp = temp2;

            }

        }

        p += vr->ptns_to_read;

    }

    return 0;

}

static uint32_t adler32(uint32_t adler, const uint8_t *buf, unsigned int len)

{

    unsigned long s1 = adler & 0xffff;

    unsigned long s2 = (adler >> 16) & 0xffff;

    int k;



    if (buf == NULL) return 1L;



    while (len > 0) {

        k = len < NMAX ? len : NMAX;

        len -= k;

        while (k >= 16) {

            DO16(buf);

            k -= 16;

        }

        if (k != 0) do {

            DO1(buf);

        } while (--k);

        s1 %= BASE;

        s2 %= BASE;

    }

    return (s2 << 16) | s1;

}

void event_loop(void)

{

    SDL_Event event;

    double incr, pos, frac;



    for(;;) {

        SDL_WaitEvent(&event);

        switch(event.type) {

        case SDL_KEYDOWN:

            switch(event.key.keysym.sym) {

            case SDLK_ESCAPE:

            case SDLK_q:

                do_exit();

                break;

            case SDLK_f:

                toggle_full_screen();

                break;

            case SDLK_p:

            case SDLK_SPACE:

                toggle_pause();

                break;

            case SDLK_s: //S: Step to next frame

                step_to_next_frame();

                break;

            case SDLK_a:

                if (cur_stream) 

                    stream_cycle_channel(cur_stream, CODEC_TYPE_AUDIO);

                break;

            case SDLK_v:

                if (cur_stream) 

                    stream_cycle_channel(cur_stream, CODEC_TYPE_VIDEO);

                break;

            case SDLK_w:

                toggle_audio_display();

                break;

            case SDLK_LEFT:

                incr = -10.0;

                goto do_seek;

            case SDLK_RIGHT:

                incr = 10.0;

                goto do_seek;

            case SDLK_UP:

                incr = 60.0;

                goto do_seek;

            case SDLK_DOWN:

                incr = -60.0;

            do_seek:

                if (cur_stream) {

                    pos = get_master_clock(cur_stream);

printf("%f %f %d %d %d %d\n", (float)pos, (float)incr, cur_stream->av_sync_type == AV_SYNC_VIDEO_MASTER, 

cur_stream->av_sync_type == AV_SYNC_AUDIO_MASTER, cur_stream->video_st, cur_stream->audio_st);

                    pos += incr;

                    stream_seek(cur_stream, (int64_t)(pos * AV_TIME_BASE));

                }

                break;

            default:

                break;

            }

            break;

        case SDL_MOUSEBUTTONDOWN:

	    if (cur_stream) {

		int ns, hh, mm, ss;

		int tns, thh, tmm, tss;

		tns = cur_stream->ic->duration/1000000LL;

		thh = tns/3600;

		tmm = (tns%3600)/60;

		tss = (tns%60);

		frac = (double)event.button.x/(double)cur_stream->width;

		ns = frac*tns;

		hh = ns/3600;

		mm = (ns%3600)/60;

		ss = (ns%60);

		fprintf(stderr, "Seek to %2.0f%% (%2d:%02d:%02d) of total duration (%2d:%02d:%02d)       \n", frac*100,

			hh, mm, ss, thh, tmm, tss);

		stream_seek(cur_stream, (int64_t)(cur_stream->ic->start_time+frac*cur_stream->ic->duration));

	    }

	    break;

        case SDL_VIDEORESIZE:

            if (cur_stream) {

                screen = SDL_SetVideoMode(event.resize.w, event.resize.h, 0, 

                                          SDL_HWSURFACE|SDL_RESIZABLE|SDL_ASYNCBLIT|SDL_HWACCEL);

                cur_stream->width = event.resize.w;

                cur_stream->height = event.resize.h;

            }

            break;

        case SDL_QUIT:

        case FF_QUIT_EVENT:

            do_exit();

            break;

        case FF_ALLOC_EVENT:

            alloc_picture(event.user.data1);

            break;

        case FF_REFRESH_EVENT:

            video_refresh_timer(event.user.data1);

            break;

        default:

            break;

        }

    }

}

