    s->bytestream_end   = (uint8_t *)buf + buf_size;



    if ((ret = ff_pnm_decode_header(avctx, s)) < 0)

        return ret;



    if ((ret = ff_get_buffer(avctx, p, 0)) < 0)

        return ret;

    p->pict_type = AV_PICTURE_TYPE_I;

    p->key_frame = 1;



    switch (avctx->pix_fmt) {

    default:

        return AVERROR(EINVAL);

    case AV_PIX_FMT_RGBA64BE:

        n = avctx->width * 8;

        components=4;

        sample_len=16;

        goto do_read;

    case AV_PIX_FMT_RGB48BE:

        n = avctx->width * 6;

        components=3;

        sample_len=16;

        goto do_read;

    case AV_PIX_FMT_RGBA:

        n = avctx->width * 4;

        components=4;

        sample_len=8;

        goto do_read;

    case AV_PIX_FMT_RGB24:

        n = avctx->width * 3;

        components=3;

        sample_len=8;

        goto do_read;

    case AV_PIX_FMT_GRAY8:

        n = avctx->width;

        components=1;

        sample_len=8;

        if (s->maxval < 255) {

            upgrade = 1;

            maskval = (2 << av_log2(s->maxval)) - 1;

        }

        goto do_read;

    case AV_PIX_FMT_GRAY8A:

        n = avctx->width * 2;

        components=2;

        sample_len=8;

        goto do_read;

    case AV_PIX_FMT_GRAY16BE:

    case AV_PIX_FMT_GRAY16LE:

        n = avctx->width * 2;

        components=1;

        sample_len=16;

        if (s->maxval < 65535) {

            upgrade = 2;

            maskval = (2 << av_log2(s->maxval)) - 1;

        }

        goto do_read;

    case AV_PIX_FMT_MONOWHITE:

    case AV_PIX_FMT_MONOBLACK:

        n = (avctx->width + 7) >> 3;

        components=1;

        sample_len=1;

        is_mono = 1;

    do_read:

        ptr      = p->data[0];

        linesize = p->linesize[0];

        if (s->bytestream + n * avctx->height > s->bytestream_end)

            return AVERROR_INVALIDDATA;

        if(s->type < 4 || (is_mono && s->type==7)){

            for (i=0; i<avctx->height; i++) {

                PutBitContext pb;

                init_put_bits(&pb, ptr, linesize);

                for(j=0; j<avctx->width * components; j++){

                    unsigned int c=0;

                    int v=0;

                    if(s->type < 4)

                    while(s->bytestream < s->bytestream_end && (*s->bytestream < '0' || *s->bytestream > '9' ))

                        s->bytestream++;

                    if(s->bytestream >= s->bytestream_end)

                        return AVERROR_INVALIDDATA;

                    if (is_mono) {

                        /* read a single digit */

                        v = (*s->bytestream++)&1;

                    } else {

                        /* read a sequence of digits */

                        do {

                            v = 10*v + c;

                            c = (*s->bytestream++) - '0';

                        } while (c <= 9);

                    }

                    put_bits(&pb, sample_len, (((1<<sample_len)-1)*v + (s->maxval>>1))/s->maxval);

                }

                flush_put_bits(&pb);

                ptr+= linesize;

            }

        }else{

        for (i = 0; i < avctx->height; i++) {

            if (!upgrade)

                memcpy(ptr, s->bytestream, n);

            else if (upgrade == 1) {

                unsigned int j, f = (255 * 128 + s->maxval / 2) / s->maxval;

                for (j = 0; j < n; j++)

                    ptr[j] = ((s->bytestream[j] & maskval) * f + 64) >> 7;

            } else if (upgrade == 2) {

                unsigned int j, v, f = (65535 * 32768 + s->maxval / 2) / s->maxval;

                for (j = 0; j < n / 2; j++) {

                    v = av_be2ne16(((uint16_t *)s->bytestream)[j]) & maskval;

                    ((uint16_t *)ptr)[j] = (v * f + 16384) >> 15;

                }

            }

            s->bytestream += n;

            ptr           += linesize;

        }

        }

        break;

    case AV_PIX_FMT_YUV420P:

    case AV_PIX_FMT_YUV420P9BE:

    case AV_PIX_FMT_YUV420P10BE:

        {

            unsigned char *ptr1, *ptr2;



            n        = avctx->width;

            ptr      = p->data[0];

            linesize = p->linesize[0];

            if (s->maxval >= 256)

                n *= 2;

            if (s->bytestream + n * avctx->height * 3 / 2 > s->bytestream_end)

                return AVERROR_INVALIDDATA;

            for (i = 0; i < avctx->height; i++) {

                memcpy(ptr, s->bytestream, n);

                s->bytestream += n;

                ptr           += linesize;

            }

            ptr1 = p->data[1];

            ptr2 = p->data[2];

            n >>= 1;

            h = avctx->height >> 1;

            for (i = 0; i < h; i++) {

                memcpy(ptr1, s->bytestream, n);

                s->bytestream += n;

                memcpy(ptr2, s->bytestream, n);

                s->bytestream += n;

                ptr1 += p->linesize[1];

                ptr2 += p->linesize[2];

            }

        }

        break;

    case AV_PIX_FMT_YUV420P16:

        {

            uint16_t *ptr1, *ptr2;

            const int f = (65535 * 32768 + s->maxval / 2) / s->maxval;

            unsigned int j, v;



            n        = avctx->width * 2;

            ptr      = p->data[0];

            linesize = p->linesize[0];

            if (s->bytestream + n * avctx->height * 3 / 2 > s->bytestream_end)

                return AVERROR_INVALIDDATA;

            for (i = 0; i < avctx->height; i++) {

                for (j = 0; j < n / 2; j++) {

                    v = av_be2ne16(((uint16_t *)s->bytestream)[j]);

                    ((uint16_t *)ptr)[j] = (v * f + 16384) >> 15;

                }

                s->bytestream += n;

                ptr           += linesize;

            }

            ptr1 = (uint16_t*)p->data[1];

            ptr2 = (uint16_t*)p->data[2];

            n >>= 1;

            h = avctx->height >> 1;

            for (i = 0; i < h; i++) {

                for (j = 0; j < n / 2; j++) {

                    v = av_be2ne16(((uint16_t *)s->bytestream)[j]);

                    ptr1[j] = (v * f + 16384) >> 15;

                }

                s->bytestream += n;



                for (j = 0; j < n / 2; j++) {

                    v = av_be2ne16(((uint16_t *)s->bytestream)[j]);

                    ptr2[j] = (v * f + 16384) >> 15;

                }

                s->bytestream += n;



                ptr1 += p->linesize[1] / 2;

                ptr2 += p->linesize[2] / 2;

            }

        }

        break;

    }

    *got_frame = 1;



    return s->bytestream - s->bytestream_start;

}

int ff_audio_mix_get_matrix(AudioMix *am, double *matrix, int stride)

{

    int i, o;



    if ( am->in_channels <= 0 ||  am->in_channels > AVRESAMPLE_MAX_CHANNELS ||

        am->out_channels <= 0 || am->out_channels > AVRESAMPLE_MAX_CHANNELS) {

        av_log(am, AV_LOG_ERROR, "Invalid channel counts\n");

        return AVERROR(EINVAL);

    }



#define GET_MATRIX_CONVERT(suffix, scale)                                   \

    if (!am->matrix_ ## suffix[0]) {                                        \

        av_log(am, AV_LOG_ERROR, "matrix is not set\n");                    \

        return AVERROR(EINVAL);                                             \

    }                                                                       \

    for (o = 0; o < am->out_channels; o++)                                  \

        for (i = 0; i < am->in_channels; i++)                               \

            matrix[o * stride + i] = am->matrix_ ## suffix[o][i] * (scale);



    switch (am->coeff_type) {

    case AV_MIX_COEFF_TYPE_Q8:

        GET_MATRIX_CONVERT(q8, 1.0 / 256.0);

        break;

    case AV_MIX_COEFF_TYPE_Q15:

        GET_MATRIX_CONVERT(q15, 1.0 / 32768.0);

        break;

    case AV_MIX_COEFF_TYPE_FLT:

        GET_MATRIX_CONVERT(flt, 1.0);

        break;

    default:

        av_log(am, AV_LOG_ERROR, "Invalid mix coeff type\n");

        return AVERROR(EINVAL);

    }



    return 0;

}

static int link_filter_inouts(AVFilterContext *filt_ctx,

                              AVFilterInOut **curr_inputs,

                              AVFilterInOut **open_inputs, void *log_ctx)

{

    int pad, ret;



    for (pad = 0; pad < filt_ctx->input_count; pad++) {

        AVFilterInOut *p = *curr_inputs;



        if (p)

            *curr_inputs = (*curr_inputs)->next;

        else if (!(p = av_mallocz(sizeof(*p))))

            return AVERROR(ENOMEM);



        if (p->filter_ctx) {

            if ((ret = link_filter(p->filter_ctx, p->pad_idx, filt_ctx, pad, log_ctx)) < 0)

                return ret;

            av_free(p->name);

            av_free(p);

        } else {

            p->filter_ctx = filt_ctx;

            p->pad_idx = pad;

            append_inout(open_inputs, &p);

        }

    }



    if (*curr_inputs) {

        av_log(log_ctx, AV_LOG_ERROR,

               "Too many inputs specified for the \"%s\" filter.\n",

               filt_ctx->filter->name);

        return AVERROR(EINVAL);

    }



    pad = filt_ctx->output_count;

    while (pad--) {

        AVFilterInOut *currlinkn = av_mallocz(sizeof(AVFilterInOut));

        if (!currlinkn)

            return AVERROR(ENOMEM);

        currlinkn->filter_ctx  = filt_ctx;

        currlinkn->pad_idx = pad;

        insert_inout(curr_inputs, currlinkn);

    }



    return 0;

}

