int ff_mov_add_hinted_packet(AVFormatContext *s, AVPacket *pkt,

                             int track_index, int sample)

{

    MOVMuxContext *mov = s->priv_data;

    MOVTrack *trk = &mov->tracks[track_index];

    AVFormatContext *rtp_ctx = trk->rtp_ctx;

    uint8_t *buf = NULL;

    int size;

    AVIOContext *hintbuf = NULL;

    AVPacket hint_pkt;

    int ret = 0, count;



    if (!rtp_ctx)

        return AVERROR(ENOENT);

    if (!rtp_ctx->pb)

        return AVERROR(ENOMEM);



    sample_queue_push(&trk->sample_queue, pkt, sample);



    /* Feed the packet to the RTP muxer */

    ff_write_chained(rtp_ctx, 0, pkt, s);



    /* Fetch the output from the RTP muxer, open a new output buffer

     * for next time. */

    size = avio_close_dyn_buf(rtp_ctx->pb, &buf);

    if ((ret = url_open_dyn_packet_buf(&rtp_ctx->pb,

                                       RTP_MAX_PACKET_SIZE)) < 0)

        goto done;



    if (size <= 0)

        goto done;



    /* Open a buffer for writing the hint */

    if ((ret = avio_open_dyn_buf(&hintbuf)) < 0)

        goto done;

    av_init_packet(&hint_pkt);

    count = write_hint_packets(hintbuf, buf, size, trk, &hint_pkt.dts);

    av_freep(&buf);



    /* Write the hint data into the hint track */

    hint_pkt.size = size = avio_close_dyn_buf(hintbuf, &buf);

    hint_pkt.data = buf;

    hint_pkt.pts  = hint_pkt.dts;

    hint_pkt.stream_index = track_index;

    if (pkt->flags & AV_PKT_FLAG_KEY)

        hint_pkt.flags |= AV_PKT_FLAG_KEY;

    if (count > 0)

        ff_mov_write_packet(s, &hint_pkt);

done:

    av_free(buf);

    sample_queue_retain(&trk->sample_queue);

    return ret;

}

static void decode_lowdelay(DiracContext *s)

{

    AVCodecContext *avctx = s->avctx;

    int slice_x, slice_y, bytes, bufsize;

    const uint8_t *buf;

    struct lowdelay_slice *slices;

    int slice_num = 0;



    slices = av_mallocz_array(s->lowdelay.num_x, s->lowdelay.num_y * sizeof(struct lowdelay_slice));



    align_get_bits(&s->gb);

    /*[DIRAC_STD] 13.5.2 Slices. slice(sx,sy) */

    buf = s->gb.buffer + get_bits_count(&s->gb)/8;

    bufsize = get_bits_left(&s->gb);



    for (slice_y = 0; bufsize > 0 && slice_y < s->lowdelay.num_y; slice_y++)

        for (slice_x = 0; bufsize > 0 && slice_x < s->lowdelay.num_x; slice_x++) {

            bytes = (slice_num+1) * s->lowdelay.bytes.num / s->lowdelay.bytes.den

                - slice_num    * s->lowdelay.bytes.num / s->lowdelay.bytes.den;



            slices[slice_num].bytes   = bytes;

            slices[slice_num].slice_x = slice_x;

            slices[slice_num].slice_y = slice_y;

            init_get_bits(&slices[slice_num].gb, buf, bufsize);

            slice_num++;



            buf     += bytes;

            bufsize -= bytes*8;

        }



    avctx->execute(avctx, decode_lowdelay_slice, slices, NULL, slice_num,

                   sizeof(struct lowdelay_slice)); /* [DIRAC_STD] 13.5.2 Slices */

    intra_dc_prediction(&s->plane[0].band[0][0]);  /* [DIRAC_STD] 13.3 intra_dc_prediction() */

    intra_dc_prediction(&s->plane[1].band[0][0]);  /* [DIRAC_STD] 13.3 intra_dc_prediction() */

    intra_dc_prediction(&s->plane[2].band[0][0]);  /* [DIRAC_STD] 13.3 intra_dc_prediction() */

    av_free(slices);

}

static void copy_video_props(AVFilterBufferRefVideoProps *dst, AVFilterBufferRefVideoProps *src) {

    *dst = *src;

    if (src->qp_table) {

        int qsize = src->qp_table_size;

        dst->qp_table = av_malloc(qsize);

        memcpy(dst->qp_table, src->qp_table, qsize);

    }

}

int attribute_align_arg avcodec_encode_audio2(AVCodecContext *avctx,

                                              AVPacket *avpkt,

                                              const AVFrame *frame,

                                              int *got_packet_ptr)

{

    int ret;

    int user_packet = !!avpkt->data;

    int nb_samples;



    *got_packet_ptr = 0;



    if (!(avctx->codec->capabilities & CODEC_CAP_DELAY) && !frame) {

        av_free_packet(avpkt);

        av_init_packet(avpkt);

        avpkt->size = 0;

        return 0;

    }



    /* check for valid frame size */

    if (frame) {

        nb_samples = frame->nb_samples;

        if (avctx->codec->capabilities & CODEC_CAP_SMALL_LAST_FRAME) {

            if (nb_samples > avctx->frame_size)

                return AVERROR(EINVAL);

        } else if (!(avctx->codec->capabilities & CODEC_CAP_VARIABLE_FRAME_SIZE)) {

            if (nb_samples != avctx->frame_size)

                return AVERROR(EINVAL);

        }

    } else {

        nb_samples = avctx->frame_size;

    }



    if (avctx->codec->encode2) {

        ret = avctx->codec->encode2(avctx, avpkt, frame, got_packet_ptr);

        if (!ret && *got_packet_ptr) {

            if (!(avctx->codec->capabilities & CODEC_CAP_DELAY)) {

                if (avpkt->pts == AV_NOPTS_VALUE)

                    avpkt->pts = frame->pts;

                if (!avpkt->duration)

                    avpkt->duration = ff_samples_to_time_base(avctx,

                                                              frame->nb_samples);

            }

            avpkt->dts = avpkt->pts;

        } else {

            avpkt->size = 0;

        }

    } else {

        /* for compatibility with encoders not supporting encode2(), we need to

           allocate a packet buffer if the user has not provided one or check

           the size otherwise */

        int fs_tmp   = 0;

        int buf_size = avpkt->size;

        if (!user_packet) {

            if (avctx->codec->capabilities & CODEC_CAP_VARIABLE_FRAME_SIZE) {

                av_assert0(av_get_bits_per_sample(avctx->codec_id) != 0);

                buf_size = nb_samples * avctx->channels *

                           av_get_bits_per_sample(avctx->codec_id) / 8;

            } else {

                /* this is a guess as to the required size.

                   if an encoder needs more than this, it should probably

                   implement encode2() */

                buf_size = 2 * avctx->frame_size * avctx->channels *

                           av_get_bytes_per_sample(avctx->sample_fmt);

                buf_size += FF_MIN_BUFFER_SIZE;

            }

        }

        if ((ret = ff_alloc_packet(avpkt, buf_size)))

            return ret;



        /* Encoders using AVCodec.encode() that support

           CODEC_CAP_SMALL_LAST_FRAME require avctx->frame_size to be set to

           the smaller size when encoding the last frame.

           This code can be removed once all encoders supporting

           CODEC_CAP_SMALL_LAST_FRAME use encode2() */

        if ((avctx->codec->capabilities & CODEC_CAP_SMALL_LAST_FRAME) &&

            nb_samples < avctx->frame_size) {

            fs_tmp = avctx->frame_size;

            avctx->frame_size = nb_samples;

        }



        /* encode the frame */

        ret = avctx->codec->encode(avctx, avpkt->data, avpkt->size,

                                   frame ? frame->data[0] : NULL);

        if (ret >= 0) {

            if (!ret) {

                /* no output. if the packet data was allocated by libavcodec,

                   free it */

                if (!user_packet)

                    av_freep(&avpkt->data);

            } else {

                if (avctx->coded_frame)

                    avpkt->pts = avpkt->dts = avctx->coded_frame->pts;

                /* Set duration for final small packet. This can be removed

                   once all encoders supporting CODEC_CAP_SMALL_LAST_FRAME use

                   encode2() */

                if (fs_tmp) {

                    avpkt->duration = ff_samples_to_time_base(avctx,

                                                              avctx->frame_size);

                }

            }

            avpkt->size = ret;

            *got_packet_ptr = (ret > 0);

            ret = 0;

        }



        if (fs_tmp)

            avctx->frame_size = fs_tmp;

    }

    if (!ret) {

        if (!user_packet && avpkt->data) {

            uint8_t *new_data = av_realloc(avpkt->data, avpkt->size);

            if (new_data)

                avpkt->data = new_data;

        }



        avctx->frame_number++;

    }



    if (ret < 0 || !*got_packet_ptr)

        av_free_packet(avpkt);



    /* NOTE: if we add any audio encoders which output non-keyframe packets,

             this needs to be moved to the encoders, but for now we can do it

             here to simplify things */

    avpkt->flags |= AV_PKT_FLAG_KEY;



    return ret;

}

static int matroska_parse_frame(MatroskaDemuxContext *matroska,

                                MatroskaTrack *track, AVStream *st,

                                uint8_t *data, int pkt_size,

                                uint64_t timecode, uint64_t duration,

                                int64_t pos, int is_keyframe)

{

    MatroskaTrackEncoding *encodings = track->encodings.elem;

    uint8_t *pkt_data = data;

    int offset = 0, res;

    AVPacket *pkt;



    if (encodings && encodings->scope & 1) {

        res = matroska_decode_buffer(&pkt_data, &pkt_size, track);

        if (res < 0)

            return res;

    }



    if (st->codec->codec_id == AV_CODEC_ID_WAVPACK) {

        uint8_t *wv_data;

        res = matroska_parse_wavpack(track, pkt_data, &wv_data, &pkt_size);

        if (res < 0) {

            av_log(matroska->ctx, AV_LOG_ERROR,

                   "Error parsing a wavpack block.\n");

            goto fail;

        }

        if (pkt_data != data)


        pkt_data = wv_data;

    }



    if (st->codec->codec_id == AV_CODEC_ID_PRORES)

        offset = 8;



    pkt = av_mallocz(sizeof(AVPacket));

    /* XXX: prevent data copy... */

    if (av_new_packet(pkt, pkt_size + offset) < 0) {

        av_free(pkt);


        return AVERROR(ENOMEM);

    }



    if (st->codec->codec_id == AV_CODEC_ID_PRORES) {

        uint8_t *buf = pkt->data;

        bytestream_put_be32(&buf, pkt_size);

        bytestream_put_be32(&buf, MKBETAG('i', 'c', 'p', 'f'));

    }



    memcpy(pkt->data + offset, pkt_data, pkt_size);



    if (pkt_data != data)

        av_free(pkt_data);



    pkt->flags        = is_keyframe;

    pkt->stream_index = st->index;



    if (track->ms_compat)

        pkt->dts = timecode;

    else

        pkt->pts = timecode;

    pkt->pos = pos;

    if (st->codec->codec_id == AV_CODEC_ID_TEXT)

        pkt->convergence_duration = duration;

    else if (track->type != MATROSKA_TRACK_TYPE_SUBTITLE)

        pkt->duration = duration;



    if (st->codec->codec_id == AV_CODEC_ID_SSA)

        matroska_fix_ass_packet(matroska, pkt, duration);



    if (matroska->prev_pkt                                 &&

        timecode                         != AV_NOPTS_VALUE &&

        matroska->prev_pkt->pts          == timecode       &&

        matroska->prev_pkt->stream_index == st->index      &&

        st->codec->codec_id == AV_CODEC_ID_SSA)

        matroska_merge_packets(matroska->prev_pkt, pkt);

    else {

        dynarray_add(&matroska->packets, &matroska->num_packets, pkt);

        matroska->prev_pkt = pkt;

    }



    return 0;



fail:

    if (pkt_data != data)


    return res;

}

void *av_fast_realloc(void *ptr, unsigned int *size, unsigned int min_size)

{

    if(min_size < *size) 

        return ptr;



    *size= 17*min_size/16 + 32;



    return av_realloc(ptr, *size);

}

static int get_video_frame(VideoState *is, AVFrame *frame, int64_t *pts, AVPacket *pkt, int *serial)

{

    int got_picture;



    if (packet_queue_get(&is->videoq, pkt, 1, serial) < 0)

        return -1;



    if (pkt->data == flush_pkt.data) {

        avcodec_flush_buffers(is->video_st->codec);



        SDL_LockMutex(is->pictq_mutex);

        // Make sure there are no long delay timers (ideally we should just flush the queue but that's harder)

        while (is->pictq_size && !is->videoq.abort_request) {

            SDL_CondWait(is->pictq_cond, is->pictq_mutex);

        }

        is->video_current_pos = -1;

        is->frame_last_pts = AV_NOPTS_VALUE;

        is->frame_last_duration = 0;

        is->frame_timer = (double)av_gettime() / 1000000.0;

        is->frame_last_dropped_pts = AV_NOPTS_VALUE;

        SDL_UnlockMutex(is->pictq_mutex);



        return 0;

    }



    if(avcodec_decode_video2(is->video_st->codec, frame, &got_picture, pkt) < 0)

        return 0;



    if (got_picture) {

        int ret = 1;



        if (decoder_reorder_pts == -1) {

            *pts = av_frame_get_best_effort_timestamp(frame);

        } else if (decoder_reorder_pts) {

            *pts = frame->pkt_pts;

        } else {

            *pts = frame->pkt_dts;

        }



        if (*pts == AV_NOPTS_VALUE) {

            *pts = 0;

        }



        if (framedrop>0 || (framedrop && get_master_sync_type(is) != AV_SYNC_VIDEO_MASTER)) {

            SDL_LockMutex(is->pictq_mutex);

            if (is->frame_last_pts != AV_NOPTS_VALUE && *pts) {

                double clockdiff = get_video_clock(is) - get_master_clock(is);

                double dpts = av_q2d(is->video_st->time_base) * *pts;

                double ptsdiff = dpts - is->frame_last_pts;

                if (fabs(clockdiff) < AV_NOSYNC_THRESHOLD &&

                     ptsdiff > 0 && ptsdiff < AV_NOSYNC_THRESHOLD &&

                     clockdiff + ptsdiff - is->frame_last_filter_delay < 0) {

                    is->frame_last_dropped_pos = pkt->pos;

                    is->frame_last_dropped_pts = dpts;

                    is->frame_drops_early++;

                    ret = 0;

                }

            }

            SDL_UnlockMutex(is->pictq_mutex);

        }



        return ret;

    }

    return 0;

}

int ff_fft_init(FFTContext *s, int nbits, int inverse)

{

    int i, j, m, n;

    float alpha, c1, s1, s2;

    int shuffle = 0;

    int av_unused has_vectors;



    s->nbits = nbits;

    n = 1 << nbits;



    s->exptab = av_malloc((n / 2) * sizeof(FFTComplex));

    if (!s->exptab)

        goto fail;

    s->revtab = av_malloc(n * sizeof(uint16_t));

    if (!s->revtab)

        goto fail;

    s->inverse = inverse;



    s2 = inverse ? 1.0 : -1.0;



    for(i=0;i<(n/2);i++) {

        alpha = 2 * M_PI * (float)i / (float)n;

        c1 = cos(alpha);

        s1 = sin(alpha) * s2;

        s->exptab[i].re = c1;

        s->exptab[i].im = s1;

    }

    s->fft_calc = ff_fft_calc_c;

    s->imdct_calc = ff_imdct_calc;

    s->imdct_half = ff_imdct_half;

    s->exptab1 = NULL;



#ifdef HAVE_MMX

    has_vectors = mm_support();

    shuffle = 1;

    if (has_vectors & MM_3DNOWEXT) {

        /* 3DNowEx for K7/K8 */

        s->imdct_calc = ff_imdct_calc_3dn2;


        s->fft_calc = ff_fft_calc_3dn2;

    } else if (has_vectors & MM_3DNOW) {

        /* 3DNow! for K6-2/3 */

        s->fft_calc = ff_fft_calc_3dn;

    } else if (has_vectors & MM_SSE) {

        /* SSE for P3/P4 */

        s->imdct_calc = ff_imdct_calc_sse;

        s->imdct_half = ff_imdct_half_sse;

        s->fft_calc = ff_fft_calc_sse;

    } else {

        shuffle = 0;

    }

#elif defined HAVE_ALTIVEC && !defined ALTIVEC_USE_REFERENCE_C_CODE

    has_vectors = mm_support();

    if (has_vectors & MM_ALTIVEC) {

        s->fft_calc = ff_fft_calc_altivec;

        shuffle = 1;

    }

#endif



    /* compute constant table for HAVE_SSE version */

    if (shuffle) {

        int np, nblocks, np2, l;

        FFTComplex *q;



        np = 1 << nbits;

        nblocks = np >> 3;

        np2 = np >> 1;

        s->exptab1 = av_malloc(np * 2 * sizeof(FFTComplex));

        if (!s->exptab1)

            goto fail;

        q = s->exptab1;

        do {

            for(l = 0; l < np2; l += 2 * nblocks) {

                *q++ = s->exptab[l];

                *q++ = s->exptab[l + nblocks];



                q->re = -s->exptab[l].im;

                q->im = s->exptab[l].re;

                q++;

                q->re = -s->exptab[l + nblocks].im;

                q->im = s->exptab[l + nblocks].re;

                q++;

            }

            nblocks = nblocks >> 1;

        } while (nblocks != 0);

        av_freep(&s->exptab);

    }



    /* compute bit reverse table */



    for(i=0;i<n;i++) {

        m=0;

        for(j=0;j<nbits;j++) {

            m |= ((i >> j) & 1) << (nbits-j-1);

        }

        s->revtab[i]=m;

    }

    return 0;

 fail:

    av_freep(&s->revtab);

    av_freep(&s->exptab);

    av_freep(&s->exptab1);

    return -1;

}

static void write_mainheader(NUTContext *nut, AVIOContext *bc)

{

    int i, j, tmp_pts, tmp_flags, tmp_stream, tmp_mul, tmp_size, tmp_fields,

        tmp_head_idx;

    int64_t tmp_match;



    ff_put_v(bc, nut->version);

    if (nut->version > 3)

        ff_put_v(bc, nut->minor_version);

    ff_put_v(bc, nut->avf->nb_streams);

    ff_put_v(bc, nut->max_distance);

    ff_put_v(bc, nut->time_base_count);



    for (i = 0; i < nut->time_base_count; i++) {

        ff_put_v(bc, nut->time_base[i].num);

        ff_put_v(bc, nut->time_base[i].den);

    }



    tmp_pts      = 0;

    tmp_mul      = 1;

    tmp_stream   = 0;

    tmp_match    = 1 - (1LL << 62);

    tmp_head_idx = 0;

    for (i = 0; i < 256; ) {

        tmp_fields = 0;

        tmp_size   = 0;

//        tmp_res=0;

        if (tmp_pts      != nut->frame_code[i].pts_delta ) tmp_fields = 1;

        if (tmp_mul      != nut->frame_code[i].size_mul  ) tmp_fields = 2;

        if (tmp_stream   != nut->frame_code[i].stream_id ) tmp_fields = 3;

        if (tmp_size     != nut->frame_code[i].size_lsb  ) tmp_fields = 4;

//        if (tmp_res    != nut->frame_code[i].res            ) tmp_fields=5;

        if (tmp_head_idx != nut->frame_code[i].header_idx) tmp_fields = 8;



        tmp_pts    = nut->frame_code[i].pts_delta;

        tmp_flags  = nut->frame_code[i].flags;

        tmp_stream = nut->frame_code[i].stream_id;

        tmp_mul    = nut->frame_code[i].size_mul;

        tmp_size   = nut->frame_code[i].size_lsb;

//        tmp_res   = nut->frame_code[i].res;

        tmp_head_idx = nut->frame_code[i].header_idx;



        for (j = 0; i < 256; j++, i++) {

            if (i == 'N') {

                j--;

                continue;

            }

            if (nut->frame_code[i].pts_delta  != tmp_pts      ||

                nut->frame_code[i].flags      != tmp_flags    ||

                nut->frame_code[i].stream_id  != tmp_stream   ||

                nut->frame_code[i].size_mul   != tmp_mul      ||

                nut->frame_code[i].size_lsb   != tmp_size + j ||

//              nut->frame_code[i].res        != tmp_res      ||

                nut->frame_code[i].header_idx != tmp_head_idx)

                break;

        }

        if (j != tmp_mul - tmp_size)

            tmp_fields = 6;



        ff_put_v(bc, tmp_flags);

        ff_put_v(bc, tmp_fields);

        if (tmp_fields > 0) put_s(bc, tmp_pts);

        if (tmp_fields > 1) ff_put_v(bc, tmp_mul);

        if (tmp_fields > 2) ff_put_v(bc, tmp_stream);

        if (tmp_fields > 3) ff_put_v(bc, tmp_size);

        if (tmp_fields > 4) ff_put_v(bc, 0 /*tmp_res*/);

        if (tmp_fields > 5) ff_put_v(bc, j);

        if (tmp_fields > 6) ff_put_v(bc, tmp_match);

        if (tmp_fields > 7) ff_put_v(bc, tmp_head_idx);

    }

    ff_put_v(bc, nut->header_count - 1);

    for (i = 1; i < nut->header_count; i++) {

        ff_put_v(bc, nut->header_len[i]);

        avio_write(bc, nut->header[i], nut->header_len[i]);

    }

    // flags had been effectively introduced in version 4

    if (nut->version > NUT_STABLE_VERSION)

        ff_put_v(bc, nut->flags);

}

static int mov_text_decode_frame(AVCodecContext *avctx,
                            void *data, int *got_sub_ptr, AVPacket *avpkt)
{
    AVSubtitle *sub = data;
    MovTextContext *m = avctx->priv_data;
    int ret;
    AVBPrint buf;
    char *ptr = avpkt->data;
    char *end;
    int text_length, tsmb_type, ret_tsmb;
    uint64_t tsmb_size;
    const uint8_t *tsmb;
    if (!ptr || avpkt->size < 2)
        return AVERROR_INVALIDDATA;
    /*
     * A packet of size two with value zero is an empty subtitle
     * used to mark the end of the previous non-empty subtitle.
     * We can just drop them here as we have duration information
     * already. If the value is non-zero, then it's technically a
     * bad packet.
     */
    if (avpkt->size == 2)
        return AV_RB16(ptr) == 0 ? 0 : AVERROR_INVALIDDATA;
    /*
     * The first two bytes of the packet are the length of the text string
     * In complex cases, there are style descriptors appended to the string
     * so we can't just assume the packet size is the string size.
     */
    text_length = AV_RB16(ptr);
    end = ptr + FFMIN(2 + text_length, avpkt->size);
    ptr += 2;
    tsmb_size = 0;
    m->tracksize = 2 + text_length;
    m->style_entries = 0;
    m->box_flags = 0;
    m->count_s = 0;
    // Note that the spec recommends lines be no longer than 2048 characters.
    av_bprint_init(&buf, 0, AV_BPRINT_SIZE_UNLIMITED);
    if (text_length + 2 != avpkt->size) {
        while (m->tracksize + 8 <= avpkt->size) {
            // A box is a minimum of 8 bytes.
            tsmb = ptr + m->tracksize - 2;
            tsmb_size = AV_RB32(tsmb);
            tsmb += 4;
            tsmb_type = AV_RB32(tsmb);
            tsmb += 4;
            if (tsmb_size == 1) {
                if (m->tracksize + 16 > avpkt->size)
                    break;
                tsmb_size = AV_RB64(tsmb);
                tsmb += 8;
                m->size_var = 16;
            } else
                m->size_var = 8;
            //size_var is equal to 8 or 16 depending on the size of box
            if (tsmb_size == 0) {
                av_log(avctx, AV_LOG_ERROR, "tsmb_size is 0\n");
                return AVERROR_INVALIDDATA;
            }
            if (tsmb_size > avpkt->size - m->tracksize)
                break;
            for (size_t i = 0; i < box_count; i++) {
                if (tsmb_type == box_types[i].type) {
                    if (m->tracksize + m->size_var + box_types[i].base_size > avpkt->size)
                        break;
                    ret_tsmb = box_types[i].decode(tsmb, m, avpkt);
                    if (ret_tsmb == -1)
                        break;
                }
            }
            m->tracksize = m->tracksize + tsmb_size;
        }
        text_to_ass(&buf, ptr, end, m);
    } else
        text_to_ass(&buf, ptr, end, m);
    ret = ff_ass_add_rect(sub, buf.str, m->readorder++, 0, NULL, NULL);
    av_bprint_finalize(&buf, NULL);
    if (ret < 0)
        return ret;
    *got_sub_ptr = sub->num_rects > 0;
    return avpkt->size;
}

static int ra144_decode_frame(AVCodecContext * avctx, void *data,

                              int *got_frame_ptr, AVPacket *avpkt)

{

    AVFrame *frame     = data;

    const uint8_t *buf = avpkt->data;

    int buf_size = avpkt->size;

    static const uint8_t sizes[LPC_ORDER] = {6, 5, 5, 4, 4, 3, 3, 3, 3, 2};

    unsigned int refl_rms[NBLOCKS];           // RMS of the reflection coefficients

    int16_t block_coefs[NBLOCKS][LPC_ORDER];  // LPC coefficients of each sub-block

    unsigned int lpc_refl[LPC_ORDER];         // LPC reflection coefficients of the frame

    int i, j;

    int ret;

    int16_t *samples;

    unsigned int energy;



    RA144Context *ractx = avctx->priv_data;

    GetBitContext gb;



    if (buf_size < FRAME_SIZE) {

        av_log(avctx, AV_LOG_ERROR,

               "Frame too small (%d bytes). Truncated file?\n", buf_size);

        *got_frame_ptr = 0;

        return AVERROR_INVALIDDATA;

    }



    /* get output buffer */

    frame->nb_samples = NBLOCKS * BLOCKSIZE;

    if ((ret = ff_get_buffer(avctx, frame, 0)) < 0)

        return ret;

    samples = (int16_t *)frame->data[0];



    init_get_bits8(&gb, buf, FRAME_SIZE);



    for (i = 0; i < LPC_ORDER; i++)

        lpc_refl[i] = ff_lpc_refl_cb[i][get_bits(&gb, sizes[i])];



    ff_eval_coefs(ractx->lpc_coef[0], lpc_refl);

    ractx->lpc_refl_rms[0] = ff_rms(lpc_refl);



    energy = ff_energy_tab[get_bits(&gb, 5)];



    refl_rms[0] = ff_interp(ractx, block_coefs[0], 1, 1, ractx->old_energy);

    refl_rms[1] = ff_interp(ractx, block_coefs[1], 2,

                            energy <= ractx->old_energy,

                            ff_t_sqrt(energy*ractx->old_energy) >> 12);

    refl_rms[2] = ff_interp(ractx, block_coefs[2], 3, 0, energy);

    refl_rms[3] = ff_rescale_rms(ractx->lpc_refl_rms[0], energy);



    ff_int_to_int16(block_coefs[3], ractx->lpc_coef[0]);



    for (i=0; i < NBLOCKS; i++) {

        do_output_subblock(ractx, block_coefs[i], refl_rms[i], &gb);



        for (j=0; j < BLOCKSIZE; j++)

            *samples++ = av_clip_int16(ractx->curr_sblock[j + 10] << 2);

    }



    ractx->old_energy = energy;

    ractx->lpc_refl_rms[1] = ractx->lpc_refl_rms[0];



    FFSWAP(unsigned int *, ractx->lpc_coef[0], ractx->lpc_coef[1]);



    *got_frame_ptr = 1;



    return FRAME_SIZE;

}

static int decode_sequence_header_adv(VC1Context *v, GetBitContext *gb)

{

    v->res_rtm_flag = 1;

    v->level = get_bits(gb, 3);

    if (v->level >= 5) {

        av_log(v->s.avctx, AV_LOG_ERROR, "Reserved LEVEL %i\n",v->level);

    }

    v->chromaformat = get_bits(gb, 2);

    if (v->chromaformat != 1) {

        av_log(v->s.avctx, AV_LOG_ERROR,

               "Only 4:2:0 chroma format supported\n");

        return -1;

    }



    // (fps-2)/4 (->30)

    v->frmrtq_postproc       = get_bits(gb, 3); //common

    // (bitrate-32kbps)/64kbps

    v->bitrtq_postproc       = get_bits(gb, 5); //common

    v->postprocflag          = get_bits1(gb);   //common



    v->s.avctx->coded_width  = (get_bits(gb, 12) + 1) << 1;

    v->s.avctx->coded_height = (get_bits(gb, 12) + 1) << 1;

    v->s.avctx->width        = v->s.avctx->coded_width;

    v->s.avctx->height       = v->s.avctx->coded_height;

    v->broadcast             = get_bits1(gb);

    v->interlace             = get_bits1(gb);

    v->tfcntrflag            = get_bits1(gb);

    v->finterpflag           = get_bits1(gb);

    skip_bits1(gb); // reserved



    av_log(v->s.avctx, AV_LOG_DEBUG,

           "Advanced Profile level %i:\nfrmrtq_postproc=%i, bitrtq_postproc=%i\n"

           "LoopFilter=%i, ChromaFormat=%i, Pulldown=%i, Interlace: %i\n"

           "TFCTRflag=%i, FINTERPflag=%i\n",

           v->level, v->frmrtq_postproc, v->bitrtq_postproc,

           v->s.loop_filter, v->chromaformat, v->broadcast, v->interlace,

           v->tfcntrflag, v->finterpflag);



    v->psf = get_bits1(gb);

    if (v->psf) { //PsF, 6.1.13

        av_log(v->s.avctx, AV_LOG_ERROR, "Progressive Segmented Frame mode: not supported (yet)\n");

        return -1;

    }

    v->s.max_b_frames = v->s.avctx->max_b_frames = 7;

    if (get_bits1(gb)) { //Display Info - decoding is not affected by it

        int w, h, ar = 0;

        av_log(v->s.avctx, AV_LOG_DEBUG, "Display extended info:\n");

        w = get_bits(gb, 14) + 1;

        h = get_bits(gb, 14) + 1;

        av_log(v->s.avctx, AV_LOG_DEBUG, "Display dimensions: %ix%i\n", w, h);

        if (get_bits1(gb))

            ar = get_bits(gb, 4);

        if (ar && ar < 14) {

            v->s.avctx->sample_aspect_ratio = ff_vc1_pixel_aspect[ar];

        } else if (ar == 15) {

            w = get_bits(gb, 8) + 1;

            h = get_bits(gb, 8) + 1;

            v->s.avctx->sample_aspect_ratio = (AVRational){w, h};

        } else {

            av_reduce(&v->s.avctx->sample_aspect_ratio.num,

                      &v->s.avctx->sample_aspect_ratio.den,

                      v->s.avctx->height * w,

                      v->s.avctx->width * h,

                      1 << 30);

        }

        av_log(v->s.avctx, AV_LOG_DEBUG, "Aspect: %i:%i\n",

               v->s.avctx->sample_aspect_ratio.num,

               v->s.avctx->sample_aspect_ratio.den);



        if (get_bits1(gb)) { //framerate stuff

            if (get_bits1(gb)) {

                v->s.avctx->time_base.num = 32;

                v->s.avctx->time_base.den = get_bits(gb, 16) + 1;

            } else {

                int nr, dr;

                nr = get_bits(gb, 8);

                dr = get_bits(gb, 4);

                if (nr && nr < 8 && dr && dr < 3) {

                    v->s.avctx->time_base.num = ff_vc1_fps_dr[dr - 1];

                    v->s.avctx->time_base.den = ff_vc1_fps_nr[nr - 1] * 1000;

                }

            }

            if (v->broadcast) { // Pulldown may be present

                v->s.avctx->time_base.den  *= 2;

                v->s.avctx->ticks_per_frame = 2;

            }

        }



        if (get_bits1(gb)) {

            v->color_prim    = get_bits(gb, 8);

            v->transfer_char = get_bits(gb, 8);

            v->matrix_coef   = get_bits(gb, 8);

        }

    }



    v->hrd_param_flag = get_bits1(gb);

    if (v->hrd_param_flag) {

        int i;

        v->hrd_num_leaky_buckets = get_bits(gb, 5);

        skip_bits(gb, 4); //bitrate exponent

        skip_bits(gb, 4); //buffer size exponent

        for (i = 0; i < v->hrd_num_leaky_buckets; i++) {

            skip_bits(gb, 16); //hrd_rate[n]

            skip_bits(gb, 16); //hrd_buffer[n]

        }

    }

    return 0;

}

void opt_input_file(const char *filename)

{

    AVFormatContext *ic;

    AVFormatParameters params, *ap = &params;

    int err, i, ret, rfps;



    /* get default parameters from command line */

    memset(ap, 0, sizeof(*ap));

    ap->sample_rate = audio_sample_rate;

    ap->channels = audio_channels;

    ap->frame_rate = frame_rate;

    ap->width = frame_width;

    ap->height = frame_height;



    /* open the input file with generic libav function */

    err = av_open_input_file(&ic, filename, file_iformat, 0, ap);

    if (err < 0) {

        print_error(filename, err);

        exit(1);

    }



    /* If not enough info to get the stream parameters, we decode the

       first frames to get it. (used in mpeg case for example) */

    ret = av_find_stream_info(ic);

    if (ret < 0) {

        fprintf(stderr, "%s: could not find codec parameters\n", filename);

        exit(1);

    }



    /* update the current parameters so that they match the one of the input stream */

    for(i=0;i<ic->nb_streams;i++) {

        AVCodecContext *enc = &ic->streams[i]->codec;

        switch(enc->codec_type) {

        case CODEC_TYPE_AUDIO:

            //fprintf(stderr, "\nInput Audio channels: %d", enc->channels);

            audio_channels = enc->channels;

            audio_sample_rate = enc->sample_rate;

            break;

        case CODEC_TYPE_VIDEO:

            frame_height = enc->height;

            frame_width = enc->width;

            rfps = ic->streams[i]->r_frame_rate;

            if (enc->frame_rate != rfps) {

                fprintf(stderr,"\nSeems that stream %d comes from film source: %2.2f->%2.2f\n",

                    i, (float)enc->frame_rate / FRAME_RATE_BASE,

                    (float)rfps / FRAME_RATE_BASE);

            }

            /* update the current frame rate to match the stream frame rate */

            frame_rate = rfps;

            break;

        default:

            abort();

        }

    }



    input_files[nb_input_files] = ic;

    /* dump the file content */

    dump_format(ic, nb_input_files, filename, 0);

    nb_input_files++;

    file_iformat = NULL;

    file_oformat = NULL;

}

static int parse_iplconvkernel(IplConvKernel **kernel, char *buf, void *log_ctx)

{

    char shape_filename[128] = "", shape_str[32] = "rect";

    int cols = 0, rows = 0, anchor_x = 0, anchor_y = 0, shape = CV_SHAPE_RECT;

    int *values = NULL, ret;



    sscanf(buf, "%dx%d+%dx%d/%32[^=]=%127s", &cols, &rows, &anchor_x, &anchor_y, shape_str, shape_filename);



    if      (!strcmp(shape_str, "rect"   )) shape = CV_SHAPE_RECT;

    else if (!strcmp(shape_str, "cross"  )) shape = CV_SHAPE_CROSS;

    else if (!strcmp(shape_str, "ellipse")) shape = CV_SHAPE_ELLIPSE;

    else if (!strcmp(shape_str, "custom" )) {

        shape = CV_SHAPE_CUSTOM;

        if ((ret = read_shape_from_file(&cols, &rows, &values, shape_filename, log_ctx)) < 0)

            return ret;

    } else {

        av_log(log_ctx, AV_LOG_ERROR,

               "Shape unspecified or type '%s' unknown.\n", shape_str);

        return AVERROR(EINVAL);

    }



    if (rows <= 0 || cols <= 0) {

        av_log(log_ctx, AV_LOG_ERROR,

               "Invalid non-positive values for shape size %dx%d\n", cols, rows);

        return AVERROR(EINVAL);

    }



    if (anchor_x < 0 || anchor_y < 0 || anchor_x >= cols || anchor_y >= rows) {

        av_log(log_ctx, AV_LOG_ERROR,

               "Shape anchor %dx%d is not inside the rectangle with size %dx%d.\n",

               anchor_x, anchor_y, cols, rows);

        return AVERROR(EINVAL);

    }



    *kernel = cvCreateStructuringElementEx(cols, rows, anchor_x, anchor_y, shape, values);

    av_freep(&values);

    if (!*kernel)

        return AVERROR(ENOMEM);



    av_log(log_ctx, AV_LOG_VERBOSE, "Structuring element: w:%d h:%d x:%d y:%d shape:%s\n",

           rows, cols, anchor_x, anchor_y, shape_str);

    return 0;

}

static int amovie_request_frame(AVFilterLink *outlink)

{

    MovieContext *movie = outlink->src->priv;

    int ret;



    if (movie->is_done)

        return AVERROR_EOF;

    if ((ret = amovie_get_samples(outlink)) < 0)

        return ret;



    avfilter_filter_samples(outlink, avfilter_ref_buffer(movie->samplesref, ~0));

    avfilter_unref_buffer(movie->samplesref);

    movie->samplesref = NULL;



    return 0;

}

inline static void RENAME(hcscale)(uint16_t *dst, long dstWidth, uint8_t *src1, uint8_t *src2,

