    c->butterflies_float_interleave = butterflies_float_interleave_c;

    c->vector_fmul_scalar = vector_fmul_scalar_c;

    c->vector_fmac_scalar = vector_fmac_scalar_c;



    c->shrink[0]= av_image_copy_plane;

    c->shrink[1]= ff_shrink22;

    c->shrink[2]= ff_shrink44;

    c->shrink[3]= ff_shrink88;



    c->prefetch= just_return;



    memset(c->put_2tap_qpel_pixels_tab, 0, sizeof(c->put_2tap_qpel_pixels_tab));

    memset(c->avg_2tap_qpel_pixels_tab, 0, sizeof(c->avg_2tap_qpel_pixels_tab));



#undef FUNC

#undef FUNCC

#define FUNC(f, depth) f ## _ ## depth

#define FUNCC(f, depth) f ## _ ## depth ## _c



#define dspfunc1(PFX, IDX, NUM, depth)\

    c->PFX ## _pixels_tab[IDX][0] = FUNCC(PFX ## _pixels ## NUM        , depth);\

    c->PFX ## _pixels_tab[IDX][1] = FUNCC(PFX ## _pixels ## NUM ## _x2 , depth);\

    c->PFX ## _pixels_tab[IDX][2] = FUNCC(PFX ## _pixels ## NUM ## _y2 , depth);\

    c->PFX ## _pixels_tab[IDX][3] = FUNCC(PFX ## _pixels ## NUM ## _xy2, depth)



#define dspfunc2(PFX, IDX, NUM, depth)\

    c->PFX ## _pixels_tab[IDX][ 0] = FUNCC(PFX ## NUM ## _mc00, depth);\

    c->PFX ## _pixels_tab[IDX][ 1] = FUNCC(PFX ## NUM ## _mc10, depth);\

    c->PFX ## _pixels_tab[IDX][ 2] = FUNCC(PFX ## NUM ## _mc20, depth);\

    c->PFX ## _pixels_tab[IDX][ 3] = FUNCC(PFX ## NUM ## _mc30, depth);\

    c->PFX ## _pixels_tab[IDX][ 4] = FUNCC(PFX ## NUM ## _mc01, depth);\

    c->PFX ## _pixels_tab[IDX][ 5] = FUNCC(PFX ## NUM ## _mc11, depth);\

    c->PFX ## _pixels_tab[IDX][ 6] = FUNCC(PFX ## NUM ## _mc21, depth);\

    c->PFX ## _pixels_tab[IDX][ 7] = FUNCC(PFX ## NUM ## _mc31, depth);\

    c->PFX ## _pixels_tab[IDX][ 8] = FUNCC(PFX ## NUM ## _mc02, depth);\

    c->PFX ## _pixels_tab[IDX][ 9] = FUNCC(PFX ## NUM ## _mc12, depth);\

    c->PFX ## _pixels_tab[IDX][10] = FUNCC(PFX ## NUM ## _mc22, depth);\

    c->PFX ## _pixels_tab[IDX][11] = FUNCC(PFX ## NUM ## _mc32, depth);\

    c->PFX ## _pixels_tab[IDX][12] = FUNCC(PFX ## NUM ## _mc03, depth);\

    c->PFX ## _pixels_tab[IDX][13] = FUNCC(PFX ## NUM ## _mc13, depth);\

    c->PFX ## _pixels_tab[IDX][14] = FUNCC(PFX ## NUM ## _mc23, depth);\

    c->PFX ## _pixels_tab[IDX][15] = FUNCC(PFX ## NUM ## _mc33, depth)





#define BIT_DEPTH_FUNCS(depth, dct)\

    c->get_pixels                    = FUNCC(get_pixels   ## dct   , depth);\

    c->draw_edges                    = FUNCC(draw_edges            , depth);\

    c->emulated_edge_mc              = FUNC (ff_emulated_edge_mc   , depth);\

    c->clear_block                   = FUNCC(clear_block  ## dct   , depth);\

    c->clear_blocks                  = FUNCC(clear_blocks ## dct   , depth);\

    c->add_pixels8                   = FUNCC(add_pixels8  ## dct   , depth);\

    c->add_pixels4                   = FUNCC(add_pixels4  ## dct   , depth);\

    c->put_no_rnd_pixels_l2[0]       = FUNCC(put_no_rnd_pixels16_l2, depth);\

    c->put_no_rnd_pixels_l2[1]       = FUNCC(put_no_rnd_pixels8_l2 , depth);\

\

    c->put_h264_chroma_pixels_tab[0] = FUNCC(put_h264_chroma_mc8   , depth);\

    c->put_h264_chroma_pixels_tab[1] = FUNCC(put_h264_chroma_mc4   , depth);\

    c->put_h264_chroma_pixels_tab[2] = FUNCC(put_h264_chroma_mc2   , depth);\

    c->avg_h264_chroma_pixels_tab[0] = FUNCC(avg_h264_chroma_mc8   , depth);\

    c->avg_h264_chroma_pixels_tab[1] = FUNCC(avg_h264_chroma_mc4   , depth);\

    c->avg_h264_chroma_pixels_tab[2] = FUNCC(avg_h264_chroma_mc2   , depth);\

\

    dspfunc1(put       , 0, 16, depth);\

    dspfunc1(put       , 1,  8, depth);\

    dspfunc1(put       , 2,  4, depth);\

    dspfunc1(put       , 3,  2, depth);\

    dspfunc1(put_no_rnd, 0, 16, depth);\

    dspfunc1(put_no_rnd, 1,  8, depth);\

    dspfunc1(avg       , 0, 16, depth);\

    dspfunc1(avg       , 1,  8, depth);\

    dspfunc1(avg       , 2,  4, depth);\

    dspfunc1(avg       , 3,  2, depth);\

    dspfunc1(avg_no_rnd, 0, 16, depth);\

    dspfunc1(avg_no_rnd, 1,  8, depth);\

\

    dspfunc2(put_h264_qpel, 0, 16, depth);\

    dspfunc2(put_h264_qpel, 1,  8, depth);\

    dspfunc2(put_h264_qpel, 2,  4, depth);\

    dspfunc2(put_h264_qpel, 3,  2, depth);\

    dspfunc2(avg_h264_qpel, 0, 16, depth);\

    dspfunc2(avg_h264_qpel, 1,  8, depth);\

    dspfunc2(avg_h264_qpel, 2,  4, depth);



    switch (avctx->bits_per_raw_sample) {

    case 9:

        if (c->dct_bits == 32) {

            BIT_DEPTH_FUNCS(9, _32);

        } else {

            BIT_DEPTH_FUNCS(9, _16);

        }

        break;

    case 10:

        if (c->dct_bits == 32) {

            BIT_DEPTH_FUNCS(10, _32);

        } else {

            BIT_DEPTH_FUNCS(10, _16);

        }

        break;

    default:

        av_log(avctx, AV_LOG_DEBUG, "Unsupported bit depth: %d\n", avctx->bits_per_raw_sample);

    case 8:

        BIT_DEPTH_FUNCS(8, _16);

        break;

    }





    if (HAVE_MMX)        dsputil_init_mmx   (c, avctx);

    if (ARCH_ARM)        dsputil_init_arm   (c, avctx);

    if (CONFIG_MLIB)     dsputil_init_mlib  (c, avctx);

    if (HAVE_VIS)        dsputil_init_vis   (c, avctx);

    if (ARCH_ALPHA)      dsputil_init_alpha (c, avctx);

    if (ARCH_PPC)        dsputil_init_ppc   (c, avctx);

    if (HAVE_MMI)        dsputil_init_mmi   (c, avctx);

    if (ARCH_SH4)        dsputil_init_sh4   (c, avctx);

    if (ARCH_BFIN)       dsputil_init_bfin  (c, avctx);



    for(i=0; i<64; i++){

        if(!c->put_2tap_qpel_pixels_tab[0][i])

            c->put_2tap_qpel_pixels_tab[0][i]= c->put_h264_qpel_pixels_tab[0][i];

        if(!c->avg_2tap_qpel_pixels_tab[0][i])

            c->avg_2tap_qpel_pixels_tab[0][i]= c->avg_h264_qpel_pixels_tab[0][i];

    }



    ff_init_scantable_permutation(c->idct_permutation,

                                  c->idct_permutation_type);

}

static void decode(GetByteContext *gb, RangeCoder *rc, unsigned cumFreq, unsigned freq, unsigned total_freq)

{

    rc->code -= cumFreq * rc->range;

    rc->range *= freq;



    while (rc->range < TOP && bytestream2_get_bytes_left(gb) > 0) {

        unsigned byte = bytestream2_get_byte(gb);

        rc->code = (rc->code << 8) | byte;

        rc->range <<= 8;

    }

}

int ff_thread_get_buffer(AVCodecContext *avctx, ThreadFrame *f, int flags)

{

    PerThreadContext *p = avctx->internal->thread_ctx;

    int err;



    f->owner = avctx;



    if (!(avctx->active_thread_type & FF_THREAD_FRAME))

        return ff_get_buffer(avctx, f->f, flags);



    if (atomic_load(&p->state) != STATE_SETTING_UP &&

        (avctx->codec->update_thread_context || !avctx->thread_safe_callbacks)) {

        av_log(avctx, AV_LOG_ERROR, "get_buffer() cannot be called after ff_thread_finish_setup()\n");

        return -1;

    }



    if (avctx->internal->allocate_progress) {

        atomic_int *progress;

        f->progress = av_buffer_alloc(2 * sizeof(*progress));

        if (!f->progress) {

            return AVERROR(ENOMEM);

        }

        progress = (atomic_int*)f->progress->data;



        atomic_store(&progress[0], -1);

        atomic_store(&progress[1], -1);

    }



    pthread_mutex_lock(&p->parent->buffer_mutex);

    if (avctx->thread_safe_callbacks ||

        avctx->get_buffer2 == avcodec_default_get_buffer2) {

        err = ff_get_buffer(avctx, f->f, flags);

    } else {

        p->requested_frame = f->f;

        p->requested_flags = flags;

        atomic_store_explicit(&p->state, STATE_GET_BUFFER, memory_order_release);

        pthread_mutex_lock(&p->progress_mutex);

        pthread_cond_signal(&p->progress_cond);



        while (atomic_load(&p->state) != STATE_SETTING_UP)

            pthread_cond_wait(&p->progress_cond, &p->progress_mutex);



        err = p->result;



        pthread_mutex_unlock(&p->progress_mutex);



    }

    if (!avctx->thread_safe_callbacks && !avctx->codec->update_thread_context)

        ff_thread_finish_setup(avctx);



    if (err)

        av_buffer_unref(&f->progress);



    pthread_mutex_unlock(&p->parent->buffer_mutex);



    return err;

}

static int rv10_decode_frame(AVCodecContext *avctx,

                             void *data, int *data_size,

                             AVPacket *avpkt)

{

    const uint8_t *buf = avpkt->data;

    int buf_size = avpkt->size;

    MpegEncContext *s = avctx->priv_data;

    int i;

    AVFrame *pict = data;

    int slice_count;

    const uint8_t *slices_hdr = NULL;



    av_dlog(avctx, "*****frame %d size=%d\n", avctx->frame_number, buf_size);



    /* no supplementary picture */

    if (buf_size == 0) {

        return 0;

    }



    if(!avctx->slice_count){

        slice_count = (*buf++) + 1;

        slices_hdr = buf + 4;

        buf += 8 * slice_count;

    }else

        slice_count = avctx->slice_count;



    for(i=0; i<slice_count; i++){

        int offset= get_slice_offset(avctx, slices_hdr, i);

        int size, size2;



        if(i+1 == slice_count)

            size= buf_size - offset;

        else

            size= get_slice_offset(avctx, slices_hdr, i+1) - offset;



        if(i+2 >= slice_count)

            size2= buf_size - offset;

        else

            size2= get_slice_offset(avctx, slices_hdr, i+2) - offset;



        if(rv10_decode_packet(avctx, buf+offset, size, size2) > 8*size)

            i++;

    }



    if(s->current_picture_ptr != NULL && s->mb_y>=s->mb_height){

        ff_er_frame_end(s);

        MPV_frame_end(s);



        if (s->pict_type == AV_PICTURE_TYPE_B || s->low_delay) {

            *pict= *(AVFrame*)s->current_picture_ptr;

        } else if (s->last_picture_ptr != NULL) {

            *pict= *(AVFrame*)s->last_picture_ptr;

        }



        if(s->last_picture_ptr || s->low_delay){

            *data_size = sizeof(AVFrame);

            ff_print_debug_info(s, pict);

        }

        s->current_picture_ptr= NULL; //so we can detect if frame_end wasnt called (find some nicer solution...)

    }



    return buf_size;

}

static void output_client_manifest(struct VideoFiles *files,

                                   const char *basename, int split)

{

    char filename[1000];

    FILE *out;

    int i, j;



    if (split)

        snprintf(filename, sizeof(filename), "Manifest");

    else

        snprintf(filename, sizeof(filename), "%s.ismc", basename);

    out = fopen(filename, "w");

    if (!out) {

        perror(filename);

        return;

    }

    fprintf(out, "<?xml version=\"1.0\" encoding=\"utf-8\"?>\n");

    fprintf(out, "<SmoothStreamingMedia MajorVersion=\"2\" MinorVersion=\"0\" "

                 "Duration=\"%"PRId64 "\">\n", files->duration * 10);

    if (files->video_file >= 0) {

        struct VideoFile *vf = files->files[files->video_file];

        int index = 0;

        fprintf(out,

                "\t<StreamIndex Type=\"video\" QualityLevels=\"%d\" "

                "Chunks=\"%d\" "

                "Url=\"QualityLevels({bitrate})/Fragments(video={start time})\">\n",

                files->nb_video_files, vf->chunks);

        for (i = 0; i < files->nb_files; i++) {

            vf = files->files[i];

            if (!vf->is_video)

                continue;

            fprintf(out,

                    "\t\t<QualityLevel Index=\"%d\" Bitrate=\"%d\" "

                    "FourCC=\"%s\" MaxWidth=\"%d\" MaxHeight=\"%d\" "

                    "CodecPrivateData=\"",

                    index, vf->bitrate, vf->fourcc, vf->width, vf->height);

            for (j = 0; j < vf->codec_private_size; j++)

                fprintf(out, "%02X", vf->codec_private[j]);

            fprintf(out, "\" />\n");

            index++;

        }

        vf = files->files[files->video_file];

        for (i = 0; i < vf->chunks; i++)

            fprintf(out, "\t\t<c n=\"%d\" d=\"%d\" />\n", i,

                    vf->offsets[i].duration);

        fprintf(out, "\t</StreamIndex>\n");

    }

    if (files->audio_file >= 0) {

        struct VideoFile *vf = files->files[files->audio_file];

        int index = 0;

        fprintf(out,

                "\t<StreamIndex Type=\"audio\" QualityLevels=\"%d\" "

                "Chunks=\"%d\" "

                "Url=\"QualityLevels({bitrate})/Fragments(audio={start time})\">\n",

                files->nb_audio_files, vf->chunks);

        for (i = 0; i < files->nb_files; i++) {

            vf = files->files[i];

            if (!vf->is_audio)

                continue;

            fprintf(out,

                    "\t\t<QualityLevel Index=\"%d\" Bitrate=\"%d\" "

                    "FourCC=\"%s\" SamplingRate=\"%d\" Channels=\"%d\" "

                    "BitsPerSample=\"16\" PacketSize=\"%d\" "

                    "AudioTag=\"%d\" CodecPrivateData=\"",

                    index, vf->bitrate, vf->fourcc, vf->sample_rate,

                    vf->channels, vf->blocksize, vf->tag);

            for (j = 0; j < vf->codec_private_size; j++)

                fprintf(out, "%02X", vf->codec_private[j]);

            fprintf(out, "\" />\n");

            index++;

        }

        vf = files->files[files->audio_file];

        for (i = 0; i < vf->chunks; i++)

            fprintf(out, "\t\t<c n=\"%d\" d=\"%d\" />\n",

                    i, vf->offsets[i].duration);

        fprintf(out, "\t</StreamIndex>\n");

    }

    fprintf(out, "</SmoothStreamingMedia>\n");

    fclose(out);

}

static int aa_read_header(AVFormatContext *s)

{

    int i, j, idx, largest_idx = -1;

    uint32_t nkey, nval, toc_size, npairs, header_seed, start;

    char key[128], val[128], codec_name[64] = {0};

    uint8_t output[24], dst[8], src[8];

    int64_t largest_size = -1, current_size = -1;

    struct toc_entry {

        uint32_t offset;

        uint32_t size;

    } TOC[MAX_TOC_ENTRIES];

    uint32_t header_key_part[4];

    uint8_t header_key[16];

    AADemuxContext *c = s->priv_data;

    AVIOContext *pb = s->pb;

    AVStream *st;



    /* parse .aa header */

    avio_skip(pb, 4); // file size

    avio_skip(pb, 4); // magic string

    toc_size = avio_rb32(pb); // TOC size

    avio_skip(pb, 4); // unidentified integer

    if (toc_size > MAX_TOC_ENTRIES)

        return AVERROR_INVALIDDATA;

    for (i = 0; i < toc_size; i++) { // read TOC

        avio_skip(pb, 4); // TOC entry index

        TOC[i].offset = avio_rb32(pb); // block offset

        TOC[i].size = avio_rb32(pb); // block size

    }

    avio_skip(pb, 24); // header termination block (ignored)

    npairs = avio_rb32(pb); // read dictionary entries

    if (npairs > MAX_DICTIONARY_ENTRIES)

        return AVERROR_INVALIDDATA;

    for (i = 0; i < npairs; i++) {

        memset(val, 0, sizeof(val));

        memset(key, 0, sizeof(key));

        avio_skip(pb, 1); // unidentified integer

        nkey = avio_rb32(pb); // key string length

        nval = avio_rb32(pb); // value string length

        if (nkey > sizeof(key)) {

            avio_skip(pb, nkey);

        } else {

            avio_read(pb, key, nkey); // key string

        }

        if (nval > sizeof(val)) {

            avio_skip(pb, nval);

        } else {

            avio_read(pb, val, nval); // value string

        }

        if (!strcmp(key, "codec")) {

            av_log(s, AV_LOG_DEBUG, "Codec is <%s>\n", val);

            strncpy(codec_name, val, sizeof(codec_name) - 1);

        }

        if (!strcmp(key, "HeaderSeed")) {

            av_log(s, AV_LOG_DEBUG, "HeaderSeed is <%s>\n", val);

            header_seed = atoi(val);

        }

        if (!strcmp(key, "HeaderKey")) { // this looks like "1234567890 1234567890 1234567890 1234567890"

            av_log(s, AV_LOG_DEBUG, "HeaderKey is <%s>\n", val);

            sscanf(val, "%u%u%u%u", &header_key_part[0], &header_key_part[1], &header_key_part[2], &header_key_part[3]);

            for (idx = 0; idx < 4; idx++) {

                AV_WB32(&header_key[idx * 4], header_key_part[idx]); // convert each part to BE!

            }

            av_log(s, AV_LOG_DEBUG, "Processed HeaderKey is ");

            for (i = 0; i < 16; i++)

                av_log(s, AV_LOG_DEBUG, "%02x", header_key[i]);

            av_log(s, AV_LOG_DEBUG, "\n");

        }

    }



    /* verify fixed key */

    if (c->aa_fixed_key_len != 16) {

        av_log(s, AV_LOG_ERROR, "aa_fixed_key value needs to be 16 bytes!\n");

        return AVERROR(EINVAL);

    }



    /* verify codec */

    if ((c->codec_second_size = get_second_size(codec_name)) == -1) {

        av_log(s, AV_LOG_ERROR, "unknown codec <%s>!\n", codec_name);

        return AVERROR(EINVAL);

    }



    /* decryption key derivation */

    c->tea_ctx = av_tea_alloc();

    if (!c->tea_ctx)

        return AVERROR(ENOMEM);

    av_tea_init(c->tea_ctx, c->aa_fixed_key, 16);

    output[0] = output[1] = 0; // purely for padding purposes

    memcpy(output + 2, header_key, 16);

    idx = 0;

    for (i = 0; i < 3; i++) { // TEA CBC with weird mixed endianness

        AV_WB32(src, header_seed);

        AV_WB32(src + 4, header_seed + 1);

        header_seed += 2;

        av_tea_crypt(c->tea_ctx, dst, src, 1, NULL, 0); // TEA ECB encrypt

        for (j = 0; j < TEA_BLOCK_SIZE && idx < 18; j+=1, idx+=1) {

            output[idx] = output[idx] ^ dst[j];

        }

    }

    memcpy(c->file_key, output + 2, 16); // skip first 2 bytes of output

    av_log(s, AV_LOG_DEBUG, "File key is ");

    for (i = 0; i < 16; i++)

        av_log(s, AV_LOG_DEBUG, "%02x", c->file_key[i]);

    av_log(s, AV_LOG_DEBUG, "\n");



    /* decoder setup */

    st = avformat_new_stream(s, NULL);

    if (!st) {

        av_freep(&c->tea_ctx);

        return AVERROR(ENOMEM);

    }

    st->codec->codec_type = AVMEDIA_TYPE_AUDIO;

    if (!strcmp(codec_name, "mp332")) {

        st->codec->codec_id = AV_CODEC_ID_MP3;

        st->codec->sample_rate = 22050;

        st->need_parsing = AVSTREAM_PARSE_FULL_RAW;

        st->start_time = 0;

    } else if (!strcmp(codec_name, "acelp85")) {

        st->codec->codec_id = AV_CODEC_ID_SIPR;

        st->codec->block_align = 19;

        st->codec->channels = 1;

        st->codec->sample_rate = 8500;

    } else if (!strcmp(codec_name, "acelp16")) {

        st->codec->codec_id = AV_CODEC_ID_SIPR;

        st->codec->block_align = 20;

        st->codec->channels = 1;

        st->codec->sample_rate = 16000;

    }



    /* determine, and jump to audio start offset */

    for (i = 1; i < toc_size; i++) { // skip the first entry!

        current_size = TOC[i].size;

        if (current_size > largest_size) {

            largest_idx = i;

            largest_size = current_size;

        }

    }

    start = TOC[largest_idx].offset;

    avio_seek(pb, start, SEEK_SET);

    c->current_chapter_size = 0;



    return 0;

}

vorbis_comment(AVFormatContext * as, uint8_t *buf, int size)

{

    const uint8_t *p = buf;

    const uint8_t *end = buf + size;

    unsigned s, n, j;



    if (size < 8) /* must have vendor_length and user_comment_list_length */

        return -1;



    s = bytestream_get_le32(&p);



    if (end - p < s)

        return -1;



    p += s;



    n = bytestream_get_le32(&p);



    while (p < end && n > 0) {

        const char *t, *v;

        int tl, vl;



        s = bytestream_get_le32(&p);



        if (end - p < s)

            break;



        t = p;

        p += s;

        n--;



        v = memchr(t, '=', s);

        if (!v)

            continue;



        tl = v - t;

        vl = s - tl - 1;

        v++;



        if (tl && vl) {

            char *tt, *ct;



            tt = av_malloc(tl + 1);

            ct = av_malloc(vl + 1);

            if (!tt || !ct) {

                av_freep(&tt);

                av_freep(&ct);

                av_log(as, AV_LOG_WARNING, "out-of-memory error. skipping VorbisComment tag.\n");

                continue;

            }



            for (j = 0; j < tl; j++)

                tt[j] = toupper(t[j]);

            tt[tl] = 0;



            memcpy(ct, v, vl);

            ct[vl] = 0;



            av_metadata_set(&as->metadata, tt, ct);



            av_freep(&tt);

            av_freep(&ct);

        }

    }



    if (p != end)

        av_log(as, AV_LOG_INFO, "%ti bytes of comment header remain\n", end-p);

    if (n > 0)

        av_log(as, AV_LOG_INFO,

               "truncated comment header, %i comments not found\n", n);



    return 0;

}

static float get_band_cost_ESC_mips(struct AACEncContext *s,

                                    PutBitContext *pb, const float *in,

                                    const float *scaled, int size, int scale_idx,

                                    int cb, const float lambda, const float uplim,

                                    int *bits)

{

    const float Q34 = ff_aac_pow34sf_tab[POW_SF2_ZERO - scale_idx + SCALE_ONE_POS - SCALE_DIV_512];

    const float IQ  = ff_aac_pow2sf_tab [POW_SF2_ZERO + scale_idx - SCALE_ONE_POS + SCALE_DIV_512];

    const float CLIPPED_ESCAPE = 165140.0f * IQ;

    int i;

    float cost = 0;

    int qc1, qc2, qc3, qc4;

    int curbits = 0;



    uint8_t *p_bits  = (uint8_t*)ff_aac_spectral_bits[cb-1];

    float   *p_codes = (float*  )ff_aac_codebook_vectors[cb-1];



    for (i = 0; i < size; i += 4) {

        const float *vec, *vec2;

        int curidx, curidx2;

        float t1, t2, t3, t4;

        float di1, di2, di3, di4;

        int cond0, cond1, cond2, cond3;

        int c1, c2, c3, c4;

        int t6, t7;



        qc1 = scaled[i  ] * Q34 + ROUND_STANDARD;

        qc2 = scaled[i+1] * Q34 + ROUND_STANDARD;

        qc3 = scaled[i+2] * Q34 + ROUND_STANDARD;

        qc4 = scaled[i+3] * Q34 + ROUND_STANDARD;



        __asm__ volatile (

            ".set push                                  \n\t"

            ".set noreorder                             \n\t"



            "ori        %[t6],      $zero,  15          \n\t"

            "ori        %[t7],      $zero,  16          \n\t"

            "shll_s.w   %[c1],      %[qc1], 18          \n\t"

            "shll_s.w   %[c2],      %[qc2], 18          \n\t"

            "shll_s.w   %[c3],      %[qc3], 18          \n\t"

            "shll_s.w   %[c4],      %[qc4], 18          \n\t"

            "srl        %[c1],      %[c1],  18          \n\t"

            "srl        %[c2],      %[c2],  18          \n\t"

            "srl        %[c3],      %[c3],  18          \n\t"

            "srl        %[c4],      %[c4],  18          \n\t"

            "slt        %[cond0],   %[t6],  %[qc1]      \n\t"

            "slt        %[cond1],   %[t6],  %[qc2]      \n\t"

            "slt        %[cond2],   %[t6],  %[qc3]      \n\t"

            "slt        %[cond3],   %[t6],  %[qc4]      \n\t"

            "movn       %[qc1],     %[t7],  %[cond0]    \n\t"

            "movn       %[qc2],     %[t7],  %[cond1]    \n\t"

            "movn       %[qc3],     %[t7],  %[cond2]    \n\t"

            "movn       %[qc4],     %[t7],  %[cond3]    \n\t"



            ".set pop                                   \n\t"



            : [qc1]"+r"(qc1), [qc2]"+r"(qc2),

              [qc3]"+r"(qc3), [qc4]"+r"(qc4),

              [cond0]"=&r"(cond0), [cond1]"=&r"(cond1),

              [cond2]"=&r"(cond2), [cond3]"=&r"(cond3),

              [c1]"=&r"(c1), [c2]"=&r"(c2),

              [c3]"=&r"(c3), [c4]"=&r"(c4),

              [t6]"=&r"(t6), [t7]"=&r"(t7)

        );



        curidx = 17 * qc1;

        curidx += qc2;



        curidx2 = 17 * qc3;

        curidx2 += qc4;



        curbits += p_bits[curidx];

        curbits += esc_sign_bits[curidx];

        vec     = &p_codes[curidx*2];



        curbits += p_bits[curidx2];

        curbits += esc_sign_bits[curidx2];

        vec2     = &p_codes[curidx2*2];



        curbits += (av_log2(c1) * 2 - 3) & (-cond0);

        curbits += (av_log2(c2) * 2 - 3) & (-cond1);

        curbits += (av_log2(c3) * 2 - 3) & (-cond2);

        curbits += (av_log2(c4) * 2 - 3) & (-cond3);



        t1 = fabsf(in[i  ]);

        t2 = fabsf(in[i+1]);

        t3 = fabsf(in[i+2]);

        t4 = fabsf(in[i+3]);



        if (cond0) {

            if (t1 >= CLIPPED_ESCAPE) {

                di1 = t1 - CLIPPED_ESCAPE;

            } else {

                di1 = t1 - c1 * cbrtf(c1) * IQ;

            }

        } else

            di1 = t1 - vec[0] * IQ;



        if (cond1) {

            if (t2 >= CLIPPED_ESCAPE) {

                di2 = t2 - CLIPPED_ESCAPE;

            } else {

                di2 = t2 - c2 * cbrtf(c2) * IQ;

            }

        } else

            di2 = t2 - vec[1] * IQ;



        if (cond2) {

            if (t3 >= CLIPPED_ESCAPE) {

                di3 = t3 - CLIPPED_ESCAPE;

            } else {

                di3 = t3 - c3 * cbrtf(c3) * IQ;

            }

        } else

            di3 = t3 - vec2[0] * IQ;



        if (cond3) {

            if (t4 >= CLIPPED_ESCAPE) {

                di4 = t4 - CLIPPED_ESCAPE;

            } else {

                di4 = t4 - c4 * cbrtf(c4) * IQ;

            }

        } else

            di4 = t4 - vec2[1]*IQ;



        cost += di1 * di1 + di2 * di2

                + di3 * di3 + di4 * di4;

    }



    if (bits)

        *bits = curbits;

    return cost * lambda + curbits;

}

static PayloadContext *h264_new_context(void)

{

    PayloadContext *data =

        av_mallocz(sizeof(PayloadContext) +

                   FF_INPUT_BUFFER_PADDING_SIZE);



    if (data) {

        data->cookie = MAGIC_COOKIE;

    }



    return data;

}

static inline int parse_nal_units(AVCodecParserContext *s,

                                  AVCodecContext *avctx,

                                  const uint8_t *buf, int buf_size)

{

    H264Context *h = s->priv_data;

    const uint8_t *buf_end = buf + buf_size;

    unsigned int pps_id;

    unsigned int slice_type;

    int state;

    const uint8_t *ptr;



    /* set some sane default values */

    s->pict_type = FF_I_TYPE;

    s->key_frame = 0;



    h->s.avctx= avctx;

    h->sei_recovery_frame_cnt = -1;

    h->sei_dpb_output_delay         =  0;

    h->sei_cpb_removal_delay        = -1;

    h->sei_buffering_period_present =  0;



    for(;;) {

        int src_length, dst_length, consumed;

        buf = ff_find_start_code(buf, buf_end, &state);

        if(buf >= buf_end)

            break;

        --buf;

        src_length = buf_end - buf;

        switch (state & 0x1f) {

        case NAL_SLICE:

        case NAL_IDR_SLICE:

            // Do not walk the whole buffer just to decode slice header

            if (src_length > 20)

                src_length = 20;

            break;

        }

        ptr= ff_h264_decode_nal(h, buf, &dst_length, &consumed, src_length);

        if (ptr==NULL || dst_length < 0)

            break;



        init_get_bits(&h->s.gb, ptr, 8*dst_length);

        switch(h->nal_unit_type) {

        case NAL_SPS:

            ff_h264_decode_seq_parameter_set(h);

            break;

        case NAL_PPS:

            ff_h264_decode_picture_parameter_set(h, h->s.gb.size_in_bits);

            break;

        case NAL_SEI:

            ff_h264_decode_sei(h);

            break;

        case NAL_IDR_SLICE:

            s->key_frame = 1;

            /* fall through */

        case NAL_SLICE:

            get_ue_golomb(&h->s.gb);  // skip first_mb_in_slice

            slice_type = get_ue_golomb_31(&h->s.gb);

            s->pict_type = golomb_to_pict_type[slice_type % 5];

            if (h->sei_recovery_frame_cnt >= 0) {

                /* key frame, since recovery_frame_cnt is set */

                s->key_frame = 1;

            }

            pps_id= get_ue_golomb(&h->s.gb);

            if(pps_id>=MAX_PPS_COUNT) {

                av_log(h->s.avctx, AV_LOG_ERROR, "pps_id out of range\n");

                return -1;

            }

            if(!h->pps_buffers[pps_id]) {

                av_log(h->s.avctx, AV_LOG_ERROR, "non-existing PPS referenced\n");

                return -1;

            }

            h->pps= *h->pps_buffers[pps_id];

            if(!h->sps_buffers[h->pps.sps_id]) {

                av_log(h->s.avctx, AV_LOG_ERROR, "non-existing SPS referenced\n");

                return -1;

            }

            h->sps = *h->sps_buffers[h->pps.sps_id];

            h->frame_num = get_bits(&h->s.gb, h->sps.log2_max_frame_num);



            if(h->sps.frame_mbs_only_flag){

                h->s.picture_structure= PICT_FRAME;

            }else{

                if(get_bits1(&h->s.gb)) { //field_pic_flag

                    h->s.picture_structure= PICT_TOP_FIELD + get_bits1(&h->s.gb); //bottom_field_flag

                } else {

                    h->s.picture_structure= PICT_FRAME;

                }

            }



            if(h->sps.pic_struct_present_flag) {

                switch (h->sei_pic_struct) {

                    case SEI_PIC_STRUCT_TOP_FIELD:

                    case SEI_PIC_STRUCT_BOTTOM_FIELD:

                        s->repeat_pict = 0;

                        break;

                    case SEI_PIC_STRUCT_FRAME:

                    case SEI_PIC_STRUCT_TOP_BOTTOM:

                    case SEI_PIC_STRUCT_BOTTOM_TOP:

                        s->repeat_pict = 1;

                        break;

                    case SEI_PIC_STRUCT_TOP_BOTTOM_TOP:

                    case SEI_PIC_STRUCT_BOTTOM_TOP_BOTTOM:

                        s->repeat_pict = 2;

                        break;

                    case SEI_PIC_STRUCT_FRAME_DOUBLING:

                        s->repeat_pict = 3;

                        break;

                    case SEI_PIC_STRUCT_FRAME_TRIPLING:

                        s->repeat_pict = 5;

                        break;

                    default:

                        s->repeat_pict = h->s.picture_structure == PICT_FRAME ? 1 : 0;

                        break;

                }

            } else {

                s->repeat_pict = h->s.picture_structure == PICT_FRAME ? 1 : 0;

            }



            return 0; /* no need to evaluate the rest */

        }

        buf += consumed;

    }

    /* didn't find a picture! */

    av_log(h->s.avctx, AV_LOG_ERROR, "missing picture in access unit\n");

    return -1;

}

static void ff_h264_idct_add16_sse2(uint8_t *dst, const int *block_offset, DCTELEM *block, int stride, const uint8_t nnzc[6*8]){

    int i;

    for(i=0; i<16; i+=2)

        if(nnzc[ scan8[i+0] ]|nnzc[ scan8[i+1] ])

            ff_x264_add8x4_idct_sse2 (dst + block_offset[i], block + i*16, stride);

}

static int mpeg4_decode_sprite_trajectory(Mpeg4DecContext *ctx, GetBitContext *gb)
{
    MpegEncContext *s = &ctx->m;
    int a     = 2 << s->sprite_warping_accuracy;
    int rho   = 3  - s->sprite_warping_accuracy;
    int r     = 16 / a;
    int alpha = 0;
    int beta  = 0;
    int w     = s->width;
    int h     = s->height;
    int min_ab, i, w2, h2, w3, h3;
    int sprite_ref[4][2];
    int virtual_ref[2][2];
    // only true for rectangle shapes
    const int vop_ref[4][2] = { { 0, 0 },         { s->width, 0 },
                                { 0, s->height }, { s->width, s->height } };
    int d[4][2]             = { { 0, 0 }, { 0, 0 }, { 0, 0 }, { 0, 0 } };
    if (w <= 0 || h <= 0)
        return AVERROR_INVALIDDATA;
    for (i = 0; i < ctx->num_sprite_warping_points; i++) {
        int length;
        int x = 0, y = 0;
        length = get_vlc2(gb, sprite_trajectory.table, SPRITE_TRAJ_VLC_BITS, 3);
        if (length > 0)
            x = get_xbits(gb, length);
        if (!(ctx->divx_version == 500 && ctx->divx_build == 413))
            check_marker(s->avctx, gb, "before sprite_trajectory");
        length = get_vlc2(gb, sprite_trajectory.table, SPRITE_TRAJ_VLC_BITS, 3);
        if (length > 0)
            y = get_xbits(gb, length);
        check_marker(s->avctx, gb, "after sprite_trajectory");
        ctx->sprite_traj[i][0] = d[i][0] = x;
        ctx->sprite_traj[i][1] = d[i][1] = y;
    for (; i < 4; i++)
        ctx->sprite_traj[i][0] = ctx->sprite_traj[i][1] = 0;
    while ((1 << alpha) < w)
        alpha++;
    while ((1 << beta) < h)
        beta++;  /* typo in the MPEG-4 std for the definition of w' and h' */
    w2 = 1 << alpha;
    h2 = 1 << beta;
    // Note, the 4th point isn't used for GMC
    if (ctx->divx_version == 500 && ctx->divx_build == 413) {
        sprite_ref[0][0] = a * vop_ref[0][0] + d[0][0];
        sprite_ref[0][1] = a * vop_ref[0][1] + d[0][1];
        sprite_ref[1][0] = a * vop_ref[1][0] + d[0][0] + d[1][0];
        sprite_ref[1][1] = a * vop_ref[1][1] + d[0][1] + d[1][1];
        sprite_ref[2][0] = a * vop_ref[2][0] + d[0][0] + d[2][0];
        sprite_ref[2][1] = a * vop_ref[2][1] + d[0][1] + d[2][1];
    } else {
        sprite_ref[0][0] = (a >> 1) * (2 * vop_ref[0][0] + d[0][0]);
        sprite_ref[0][1] = (a >> 1) * (2 * vop_ref[0][1] + d[0][1]);
        sprite_ref[1][0] = (a >> 1) * (2 * vop_ref[1][0] + d[0][0] + d[1][0]);
        sprite_ref[1][1] = (a >> 1) * (2 * vop_ref[1][1] + d[0][1] + d[1][1]);
        sprite_ref[2][0] = (a >> 1) * (2 * vop_ref[2][0] + d[0][0] + d[2][0]);
        sprite_ref[2][1] = (a >> 1) * (2 * vop_ref[2][1] + d[0][1] + d[2][1]);
    /* sprite_ref[3][0] = (a >> 1) * (2 * vop_ref[3][0] + d[0][0] + d[1][0] + d[2][0] + d[3][0]);
     * sprite_ref[3][1] = (a >> 1) * (2 * vop_ref[3][1] + d[0][1] + d[1][1] + d[2][1] + d[3][1]); */
    /* This is mostly identical to the MPEG-4 std (and is totally unreadable
     * because of that...). Perhaps it should be reordered to be more readable.
     * The idea behind this virtual_ref mess is to be able to use shifts later
     * per pixel instead of divides so the distance between points is converted
     * from w&h based to w2&h2 based which are of the 2^x form. */
    virtual_ref[0][0] = 16 * (vop_ref[0][0] + w2) +
                         ROUNDED_DIV(((w - w2) *
                                      (r * sprite_ref[0][0] - 16 * vop_ref[0][0]) +
                                      w2 * (r * sprite_ref[1][0] - 16 * vop_ref[1][0])), w);
    virtual_ref[0][1] = 16 * vop_ref[0][1] +
                        ROUNDED_DIV(((w - w2) *
                                     (r * sprite_ref[0][1] - 16 * vop_ref[0][1]) +
                                     w2 * (r * sprite_ref[1][1] - 16 * vop_ref[1][1])), w);
    virtual_ref[1][0] = 16 * vop_ref[0][0] +
                        ROUNDED_DIV(((h - h2) * (r * sprite_ref[0][0] - 16 * vop_ref[0][0]) +
                                     h2 * (r * sprite_ref[2][0] - 16 * vop_ref[2][0])), h);
    virtual_ref[1][1] = 16 * (vop_ref[0][1] + h2) +
                        ROUNDED_DIV(((h - h2) * (r * sprite_ref[0][1] - 16 * vop_ref[0][1]) +
                                     h2 * (r * sprite_ref[2][1] - 16 * vop_ref[2][1])), h);
    switch (ctx->num_sprite_warping_points) {
    case 0:
        s->sprite_offset[0][0] =
        s->sprite_offset[0][1] =
        s->sprite_offset[1][0] =
        s->sprite_offset[1][1] = 0;
        s->sprite_delta[0][0]  = a;
        s->sprite_delta[0][1]  =
        s->sprite_delta[1][0]  = 0;
        s->sprite_delta[1][1]  = a;
        ctx->sprite_shift[0]   =
        ctx->sprite_shift[1]   = 0;
        break;
    case 1:     // GMC only
        s->sprite_offset[0][0] = sprite_ref[0][0] - a * vop_ref[0][0];
        s->sprite_offset[0][1] = sprite_ref[0][1] - a * vop_ref[0][1];
        s->sprite_offset[1][0] = ((sprite_ref[0][0] >> 1) | (sprite_ref[0][0] & 1)) -
                                 a * (vop_ref[0][0] / 2);
        s->sprite_offset[1][1] = ((sprite_ref[0][1] >> 1) | (sprite_ref[0][1] & 1)) -
                                 a * (vop_ref[0][1] / 2);
        s->sprite_delta[0][0]  = a;
        s->sprite_delta[0][1]  =
        s->sprite_delta[1][0]  = 0;
        s->sprite_delta[1][1]  = a;
        ctx->sprite_shift[0]   =
        ctx->sprite_shift[1]   = 0;
        break;
    case 2:
        s->sprite_offset[0][0] = (sprite_ref[0][0] << (alpha + rho)) +
                                 (-r * sprite_ref[0][0] + virtual_ref[0][0]) *
                                 (-vop_ref[0][0]) +
                                 (r * sprite_ref[0][1] - virtual_ref[0][1]) *
                                 (-vop_ref[0][1]) + (1 << (alpha + rho - 1));
        s->sprite_offset[0][1] = (sprite_ref[0][1] << (alpha + rho)) +
                                 (-r * sprite_ref[0][1] + virtual_ref[0][1]) *
                                 (-vop_ref[0][0]) +
                                 (-r * sprite_ref[0][0] + virtual_ref[0][0]) *
                                 (-vop_ref[0][1]) + (1 << (alpha + rho - 1));
        s->sprite_offset[1][0] = ((-r * sprite_ref[0][0] + virtual_ref[0][0]) *
                                  (-2 * vop_ref[0][0] + 1) +
                                  (r * sprite_ref[0][1] - virtual_ref[0][1]) *
                                  (-2 * vop_ref[0][1] + 1) + 2 * w2 * r *
                                  sprite_ref[0][0] - 16 * w2 + (1 << (alpha + rho + 1)));
        s->sprite_offset[1][1] = ((-r * sprite_ref[0][1] + virtual_ref[0][1]) *
                                  (-2 * vop_ref[0][0] + 1) +
                                  (-r * sprite_ref[0][0] + virtual_ref[0][0]) *
                                  (-2 * vop_ref[0][1] + 1) + 2 * w2 * r *
                                  sprite_ref[0][1] - 16 * w2 + (1 << (alpha + rho + 1)));
        s->sprite_delta[0][0] = (-r * sprite_ref[0][0] + virtual_ref[0][0]);
        s->sprite_delta[0][1] = (+r * sprite_ref[0][1] - virtual_ref[0][1]);
        s->sprite_delta[1][0] = (-r * sprite_ref[0][1] + virtual_ref[0][1]);
        s->sprite_delta[1][1] = (-r * sprite_ref[0][0] + virtual_ref[0][0]);
        ctx->sprite_shift[0]  = alpha + rho;
        ctx->sprite_shift[1]  = alpha + rho + 2;
        break;
    case 3:
        min_ab = FFMIN(alpha, beta);
        w3     = w2 >> min_ab;
        h3     = h2 >> min_ab;
        s->sprite_offset[0][0] = (sprite_ref[0][0] * (1<<(alpha + beta + rho - min_ab))) +
                                 (-r * sprite_ref[0][0] + virtual_ref[0][0]) *
                                 h3 * (-vop_ref[0][0]) +
                                 (-r * sprite_ref[0][0] + virtual_ref[1][0]) *
                                 w3 * (-vop_ref[0][1]) +
                                 (1 << (alpha + beta + rho - min_ab - 1));
        s->sprite_offset[0][1] = (sprite_ref[0][1] * (1 << (alpha + beta + rho - min_ab))) +
                                 (-r * sprite_ref[0][1] + virtual_ref[0][1]) *
                                 h3 * (-vop_ref[0][0]) +
                                 (-r * sprite_ref[0][1] + virtual_ref[1][1]) *
                                 w3 * (-vop_ref[0][1]) +
                                 (1 << (alpha + beta + rho - min_ab - 1));
        s->sprite_offset[1][0] = (-r * sprite_ref[0][0] + virtual_ref[0][0]) *
                                 h3 * (-2 * vop_ref[0][0] + 1) +
                                 (-r * sprite_ref[0][0] + virtual_ref[1][0]) *
                                 w3 * (-2 * vop_ref[0][1] + 1) + 2 * w2 * h3 *
                                 r * sprite_ref[0][0] - 16 * w2 * h3 +
                                 (1 << (alpha + beta + rho - min_ab + 1));
        s->sprite_offset[1][1] = (-r * sprite_ref[0][1] + virtual_ref[0][1]) *
                                 h3 * (-2 * vop_ref[0][0] + 1) +
                                 (-r * sprite_ref[0][1] + virtual_ref[1][1]) *
                                 w3 * (-2 * vop_ref[0][1] + 1) + 2 * w2 * h3 *
                                 r * sprite_ref[0][1] - 16 * w2 * h3 +
                                 (1 << (alpha + beta + rho - min_ab + 1));
        s->sprite_delta[0][0] = (-r * sprite_ref[0][0] + virtual_ref[0][0]) * h3;
        s->sprite_delta[0][1] = (-r * sprite_ref[0][0] + virtual_ref[1][0]) * w3;
        s->sprite_delta[1][0] = (-r * sprite_ref[0][1] + virtual_ref[0][1]) * h3;
        s->sprite_delta[1][1] = (-r * sprite_ref[0][1] + virtual_ref[1][1]) * w3;
        ctx->sprite_shift[0]  = alpha + beta + rho - min_ab;
        ctx->sprite_shift[1]  = alpha + beta + rho - min_ab + 2;
        break;
    /* try to simplify the situation */
    if (s->sprite_delta[0][0] == a << ctx->sprite_shift[0] &&
        s->sprite_delta[0][1] == 0 &&
        s->sprite_delta[1][0] == 0 &&
        s->sprite_delta[1][1] == a << ctx->sprite_shift[0]) {
        s->sprite_offset[0][0] >>= ctx->sprite_shift[0];
        s->sprite_offset[0][1] >>= ctx->sprite_shift[0];
        s->sprite_offset[1][0] >>= ctx->sprite_shift[1];
        s->sprite_offset[1][1] >>= ctx->sprite_shift[1];
        s->sprite_delta[0][0] = a;
        s->sprite_delta[0][1] = 0;
        s->sprite_delta[1][0] = 0;
        s->sprite_delta[1][1] = a;
        ctx->sprite_shift[0] = 0;
        ctx->sprite_shift[1] = 0;
        s->real_sprite_warping_points = 1;
    } else {
        int shift_y = 16 - ctx->sprite_shift[0];
        int shift_c = 16 - ctx->sprite_shift[1];
        if (shift_c < 0 || shift_y < 0 ||
            FFABS(s->sprite_offset[0][0]) >= INT_MAX >> shift_y  ||
            FFABS(s->sprite_offset[1][0]) >= INT_MAX >> shift_c  ||
            FFABS(s->sprite_offset[0][1]) >= INT_MAX >> shift_y  ||
            FFABS(s->sprite_offset[1][1]) >= INT_MAX >> shift_c
        ) {
            avpriv_request_sample(s->avctx, "Too large sprite shift or offset");
        for (i = 0; i < 2; i++) {
            s->sprite_offset[0][i] *= 1 << shift_y;
            s->sprite_offset[1][i] *= 1 << shift_c;
            s->sprite_delta[0][i]  *= 1 << shift_y;
            s->sprite_delta[1][i]  *= 1 << shift_y;
            ctx->sprite_shift[i]     = 16;
        s->real_sprite_warping_points = ctx->num_sprite_warping_points;
    return 0;

static int ff_filter_frame_framed(AVFilterLink *link, AVFrame *frame)

{

    int (*filter_frame)(AVFilterLink *, AVFrame *);

    AVFilterContext *dstctx = link->dst;

    AVFilterPad *dst = link->dstpad;

    AVFrame *out;

    int ret;

    AVFilterCommand *cmd= link->dst->command_queue;

    int64_t pts;



    if (link->closed) {

        av_frame_free(&frame);

        return AVERROR_EOF;

    }



    if (!(filter_frame = dst->filter_frame))

        filter_frame = default_filter_frame;



    /* copy the frame if needed */

    if (dst->needs_writable && !av_frame_is_writable(frame)) {

        av_log(link->dst, AV_LOG_DEBUG, "Copying data in avfilter.\n");



        /* Maybe use ff_copy_buffer_ref instead? */

        switch (link->type) {

        case AVMEDIA_TYPE_VIDEO:

            out = ff_get_video_buffer(link, link->w, link->h);

            break;

        case AVMEDIA_TYPE_AUDIO:

            out = ff_get_audio_buffer(link, frame->nb_samples);

            break;

        default:

            ret = AVERROR(EINVAL);

            goto fail;

        }

        if (!out) {

            ret = AVERROR(ENOMEM);

            goto fail;

        }



        ret = av_frame_copy_props(out, frame);

        if (ret < 0)

            goto fail;



        switch (link->type) {

        case AVMEDIA_TYPE_VIDEO:

            av_image_copy(out->data, out->linesize, (const uint8_t **)frame->data, frame->linesize,

                          frame->format, frame->width, frame->height);

            break;

        case AVMEDIA_TYPE_AUDIO:

            av_samples_copy(out->extended_data, frame->extended_data,

                            0, 0, frame->nb_samples,

                            av_get_channel_layout_nb_channels(frame->channel_layout),

                            frame->format);

            break;

        default:

            ret = AVERROR(EINVAL);

            goto fail;

        }



        av_frame_free(&frame);

    } else

        out = frame;



    while(cmd && cmd->time <= out->pts * av_q2d(link->time_base)){

        av_log(link->dst, AV_LOG_DEBUG,

               "Processing command time:%f command:%s arg:%s\n",

               cmd->time, cmd->command, cmd->arg);

        avfilter_process_command(link->dst, cmd->command, cmd->arg, 0, 0, cmd->flags);

        ff_command_queue_pop(link->dst);

        cmd= link->dst->command_queue;

    }



    pts = out->pts;

    if (dstctx->enable_str) {

        int64_t pos = av_frame_get_pkt_pos(out);

        dstctx->var_values[VAR_N] = link->frame_count;

        dstctx->var_values[VAR_T] = pts == AV_NOPTS_VALUE ? NAN : pts * av_q2d(link->time_base);

        dstctx->var_values[VAR_POS] = pos == -1 ? NAN : pos;



        dstctx->is_disabled = fabs(av_expr_eval(dstctx->enable, dstctx->var_values, NULL)) < 0.5;

        if (dstctx->is_disabled &&

            (dstctx->filter->flags & AVFILTER_FLAG_SUPPORT_TIMELINE_GENERIC))

            filter_frame = default_filter_frame;

    }

    ret = filter_frame(link, out);

    link->frame_count++;

    link->frame_requested = 0;

    ff_update_link_current_pts(link, pts);

    return ret;



fail:

    av_frame_free(&out);

    av_frame_free(&frame);

    return ret;

}

static inline void FUNC(idctRowCondDC)(int16_t *row, int extra_shift)

{

    int a0, a1, a2, a3, b0, b1, b2, b3;



#if HAVE_FAST_64BIT

#define ROW0_MASK (0xffffLL << 48 * HAVE_BIGENDIAN)

    if (((((uint64_t *)row)[0] & ~ROW0_MASK) | ((uint64_t *)row)[1]) == 0) {

        uint64_t temp;

        if (DC_SHIFT - extra_shift > 0) {

            temp = (row[0] << (DC_SHIFT - extra_shift)) & 0xffff;

        } else {

            temp = (row[0] >> (extra_shift - DC_SHIFT)) & 0xffff;

        }

        temp += temp << 16;

        temp += temp << 32;

        ((uint64_t *)row)[0] = temp;

        ((uint64_t *)row)[1] = temp;

        return;

    }

#else

    if (!(((uint32_t*)row)[1] |

          ((uint32_t*)row)[2] |

          ((uint32_t*)row)[3] |

          row[1])) {

        uint32_t temp;

        if (DC_SHIFT - extra_shift > 0) {

            temp = (row[0] << (DC_SHIFT - extra_shift)) & 0xffff;

        } else {

            temp = (row[0] >> (extra_shift - DC_SHIFT)) & 0xffff;

        }

        temp += temp << 16;

        ((uint32_t*)row)[0]=((uint32_t*)row)[1] =

            ((uint32_t*)row)[2]=((uint32_t*)row)[3] = temp;

        return;

    }

#endif



    a0 = (W4 * row[0]) + (1 << (ROW_SHIFT - 1));

    a1 = a0;

    a2 = a0;

    a3 = a0;



    a0 += W2 * row[2];

    a1 += W6 * row[2];

    a2 -= W6 * row[2];

    a3 -= W2 * row[2];



    b0 = MUL(W1, row[1]);

    MAC(b0, W3, row[3]);

    b1 = MUL(W3, row[1]);

    MAC(b1, -W7, row[3]);

    b2 = MUL(W5, row[1]);

    MAC(b2, -W1, row[3]);

    b3 = MUL(W7, row[1]);

    MAC(b3, -W5, row[3]);



    if (AV_RN64A(row + 4)) {

        a0 +=   W4*row[4] + W6*row[6];

        a1 += - W4*row[4] - W2*row[6];

        a2 += - W4*row[4] + W2*row[6];

        a3 +=   W4*row[4] - W6*row[6];



        MAC(b0,  W5, row[5]);

        MAC(b0,  W7, row[7]);



        MAC(b1, -W1, row[5]);

        MAC(b1, -W5, row[7]);



        MAC(b2,  W7, row[5]);

        MAC(b2,  W3, row[7]);



        MAC(b3,  W3, row[5]);

        MAC(b3, -W1, row[7]);

    }



    row[0] = (a0 + b0) >> (ROW_SHIFT + extra_shift);

    row[7] = (a0 - b0) >> (ROW_SHIFT + extra_shift);

    row[1] = (a1 + b1) >> (ROW_SHIFT + extra_shift);

    row[6] = (a1 - b1) >> (ROW_SHIFT + extra_shift);

    row[2] = (a2 + b2) >> (ROW_SHIFT + extra_shift);

    row[5] = (a2 - b2) >> (ROW_SHIFT + extra_shift);

    row[3] = (a3 + b3) >> (ROW_SHIFT + extra_shift);

    row[4] = (a3 - b3) >> (ROW_SHIFT + extra_shift);

}

static int io_write_data_type(void *opaque, uint8_t *buf, int size,

                              enum AVIODataMarkerType type, int64_t time)

{

    char timebuf[30], content[5] = { 0 };

    const char *str;

    switch (type) {

    case AVIO_DATA_MARKER_HEADER:         str = "header";   break;

    case AVIO_DATA_MARKER_SYNC_POINT:     str = "sync";     break;

    case AVIO_DATA_MARKER_BOUNDARY_POINT: str = "boundary"; break;

    case AVIO_DATA_MARKER_UNKNOWN:        str = "unknown";  break;

    case AVIO_DATA_MARKER_TRAILER:        str = "trailer";  break;


    }

    if (time == AV_NOPTS_VALUE)

        snprintf(timebuf, sizeof(timebuf), "nopts");

    else

        snprintf(timebuf, sizeof(timebuf), "%"PRId64, time);

    // There can be multiple header/trailer callbacks, only log the box type

    // for header at out_size == 0

    if (type != AVIO_DATA_MARKER_UNKNOWN &&

        type != AVIO_DATA_MARKER_TRAILER &&

        (type != AVIO_DATA_MARKER_HEADER || out_size == 0) &&

        size >= 8)

        memcpy(content, &buf[4], 4);

    else

        snprintf(content, sizeof(content), "-");

    printf("write_data len %d, time %s, type %s atom %s\n", size, timebuf, str, content);

    return io_write(opaque, buf, size);

}

static void release_buffer(AVCodecContext *avctx, AVFrame *pic)

{

