static int vp3_decode_frame(AVCodecContext *avctx, 

                            void *data, int *data_size,

                            uint8_t *buf, int buf_size)

{

    Vp3DecodeContext *s = avctx->priv_data;

    GetBitContext gb;

    static int counter = 0;



    init_get_bits(&gb, buf, buf_size * 8);



    if (s->theora && get_bits1(&gb))

    {

	int ptype = get_bits(&gb, 7);



	skip_bits(&gb, 6*8); /* "theora" */



	switch(ptype)

	{

	    case 1:

		theora_decode_comments(avctx, gb);

		break;

	    case 2:

		theora_decode_tables(avctx, gb);

    		init_dequantizer(s);

		break;

	    default:

		av_log(avctx, AV_LOG_ERROR, "Unknown Theora config packet: %d\n", ptype);

	}

	return buf_size;

    }



    s->keyframe = !get_bits1(&gb);

    if (!s->theora)

	skip_bits(&gb, 1);

    s->last_quality_index = s->quality_index;

    s->quality_index = get_bits(&gb, 6);

    if (s->theora >= 0x030200)

        skip_bits1(&gb);



    if (s->avctx->debug & FF_DEBUG_PICT_INFO)

	av_log(s->avctx, AV_LOG_INFO, " VP3 %sframe #%d: Q index = %d\n",

	    s->keyframe?"key":"", counter, s->quality_index);

    counter++;



    if (s->quality_index != s->last_quality_index)

        init_dequantizer(s);



    if (s->keyframe) {

	if (!s->theora)

	{

	    skip_bits(&gb, 4); /* width code */

	    skip_bits(&gb, 4); /* height code */

	    if (s->version)

	    {

		s->version = get_bits(&gb, 5);

		if (counter == 1)

		    av_log(s->avctx, AV_LOG_DEBUG, "VP version: %d\n", s->version);

	    }

	}

	if (s->version || s->theora)

	{

    	    if (get_bits1(&gb))

    	        av_log(s->avctx, AV_LOG_ERROR, "Warning, unsupported keyframe coding type?!\n");

	    skip_bits(&gb, 2); /* reserved? */

	}



        if (s->last_frame.data[0] == s->golden_frame.data[0]) {

            if (s->golden_frame.data[0])

                avctx->release_buffer(avctx, &s->golden_frame);

            s->last_frame= s->golden_frame; /* ensure that we catch any access to this released frame */

        } else {

            if (s->golden_frame.data[0])

                avctx->release_buffer(avctx, &s->golden_frame);

            if (s->last_frame.data[0])

                avctx->release_buffer(avctx, &s->last_frame);

        }



        s->golden_frame.reference = 3;

        if(avctx->get_buffer(avctx, &s->golden_frame) < 0) {

            av_log(s->avctx, AV_LOG_ERROR, "vp3: get_buffer() failed\n");

            return -1;

        }



        /* golden frame is also the current frame */

        memcpy(&s->current_frame, &s->golden_frame, sizeof(AVFrame));



        /* time to figure out pixel addresses? */

        if (!s->pixel_addresses_inited)

	{

	    if (!s->flipped_image)

        	vp3_calculate_pixel_addresses(s);

	    else

		theora_calculate_pixel_addresses(s);

	}

    } else {

        /* allocate a new current frame */

        s->current_frame.reference = 3;

        if(avctx->get_buffer(avctx, &s->current_frame) < 0) {

            av_log(s->avctx, AV_LOG_ERROR, "vp3: get_buffer() failed\n");

            return -1;

        }

    }



    s->current_frame.qscale_table= s->qscale_table; //FIXME allocate individual tables per AVFrame

    s->current_frame.qstride= 0;



    init_frame(s, &gb);



#if KEYFRAMES_ONLY

if (!s->keyframe) {



    memcpy(s->current_frame.data[0], s->golden_frame.data[0],

        s->current_frame.linesize[0] * s->height);

    memcpy(s->current_frame.data[1], s->golden_frame.data[1],

        s->current_frame.linesize[1] * s->height / 2);

    memcpy(s->current_frame.data[2], s->golden_frame.data[2],

        s->current_frame.linesize[2] * s->height / 2);



} else {

#endif



    if (unpack_superblocks(s, &gb) ||

        unpack_modes(s, &gb) ||

        unpack_vectors(s, &gb) ||

        unpack_dct_coeffs(s, &gb)) {



        av_log(s->avctx, AV_LOG_ERROR, "  vp3: could not decode frame\n");

        return -1;

    }



    reverse_dc_prediction(s, 0, s->fragment_width, s->fragment_height);

    render_fragments(s, 0, s->width, s->height, 0);

//    apply_loop_filter(s);



    if ((avctx->flags & CODEC_FLAG_GRAY) == 0) {

        reverse_dc_prediction(s, s->u_fragment_start,

            s->fragment_width / 2, s->fragment_height / 2);

        reverse_dc_prediction(s, s->v_fragment_start,

            s->fragment_width / 2, s->fragment_height / 2);

        render_fragments(s, s->u_fragment_start, s->width / 2, s->height / 2, 1);

        render_fragments(s, s->v_fragment_start, s->width / 2, s->height / 2, 2);

    } else {

        memset(s->current_frame.data[1], 0x80, s->width * s->height / 4);

        memset(s->current_frame.data[2], 0x80, s->width * s->height / 4);

    }



#if KEYFRAMES_ONLY

}

#endif



    *data_size=sizeof(AVFrame);

    *(AVFrame*)data= s->current_frame;



    /* release the last frame, if it is allocated and if it is not the

     * golden frame */

    if ((s->last_frame.data[0]) &&

        (s->last_frame.data[0] != s->golden_frame.data[0]))

        avctx->release_buffer(avctx, &s->last_frame);



    /* shuffle frames (last = current) */

    memcpy(&s->last_frame, &s->current_frame, sizeof(AVFrame));

    s->current_frame.data[0]= NULL; /* ensure that we catch any access to this released frame */



    return buf_size;

}

static int au_read_header(AVFormatContext *s)

{

    int size;

    unsigned int tag;

    AVIOContext *pb = s->pb;

    unsigned int id, channels, rate;

    enum AVCodecID codec;

    AVStream *st;



    /* check ".snd" header */

    tag = avio_rl32(pb);

    if (tag != MKTAG('.', 's', 'n', 'd'))

        return -1;

    size = avio_rb32(pb); /* header size */

    avio_rb32(pb); /* data size */



    id = avio_rb32(pb);

    rate = avio_rb32(pb);

    channels = avio_rb32(pb);



    codec = ff_codec_get_id(codec_au_tags, id);



    if (!av_get_bits_per_sample(codec)) {

        av_log_ask_for_sample(s, "could not determine bits per sample\n");

        return AVERROR_PATCHWELCOME;

    }



    if (channels == 0 || channels > 64) {

        av_log(s, AV_LOG_ERROR, "Invalid number of channels %d\n", channels);

        return AVERROR_INVALIDDATA;

    }



    if (size >= 24) {

        /* skip unused data */

        avio_skip(pb, size - 24);

    }



    /* now we are ready: build format streams */

    st = avformat_new_stream(s, NULL);

    if (!st)

        return -1;

    st->codec->codec_type = AVMEDIA_TYPE_AUDIO;

    st->codec->codec_tag = id;

    st->codec->codec_id = codec;

    st->codec->channels = channels;

    st->codec->sample_rate = rate;

    avpriv_set_pts_info(st, 64, 1, rate);

    return 0;

}

static av_always_inline void encode_mb_internal(MpegEncContext *s, int motion_x, int motion_y, int mb_block_height, int mb_block_count)

{

    int16_t weight[8][64];

    DCTELEM orig[8][64];

    const int mb_x= s->mb_x;

    const int mb_y= s->mb_y;

    int i;

    int skip_dct[8];

    int dct_offset   = s->linesize*8; //default for progressive frames

    uint8_t *ptr_y, *ptr_cb, *ptr_cr;

    int wrap_y, wrap_c;



    for(i=0; i<mb_block_count; i++) skip_dct[i]=s->skipdct;



    if(s->adaptive_quant){

        const int last_qp= s->qscale;

        const int mb_xy= mb_x + mb_y*s->mb_stride;



        s->lambda= s->lambda_table[mb_xy];

        update_qscale(s);



        if(!(s->flags&CODEC_FLAG_QP_RD)){

            s->qscale= s->current_picture_ptr->qscale_table[mb_xy];

            s->dquant= s->qscale - last_qp;



            if(s->out_format==FMT_H263){

                s->dquant= av_clip(s->dquant, -2, 2);



                if(s->codec_id==CODEC_ID_MPEG4){

                    if(!s->mb_intra){

                        if(s->pict_type == FF_B_TYPE){

                            if(s->dquant&1 || s->mv_dir&MV_DIRECT)

                                s->dquant= 0;

                        }

                        if(s->mv_type==MV_TYPE_8X8)

                            s->dquant=0;

                    }

                }

            }

        }

        ff_set_qscale(s, last_qp + s->dquant);

    }else if(s->flags&CODEC_FLAG_QP_RD)

        ff_set_qscale(s, s->qscale + s->dquant);



    wrap_y = s->linesize;

    wrap_c = s->uvlinesize;

    ptr_y = s->new_picture.data[0] + (mb_y * 16 * wrap_y) + mb_x * 16;

    ptr_cb = s->new_picture.data[1] + (mb_y * mb_block_height * wrap_c) + mb_x * 8;

    ptr_cr = s->new_picture.data[2] + (mb_y * mb_block_height * wrap_c) + mb_x * 8;



    if(mb_x*16+16 > s->width || mb_y*16+16 > s->height){

        uint8_t *ebuf= s->edge_emu_buffer + 32;

        ff_emulated_edge_mc(ebuf            , ptr_y , wrap_y,16,16,mb_x*16,mb_y*16, s->width   , s->height);

        ptr_y= ebuf;

        ff_emulated_edge_mc(ebuf+18*wrap_y  , ptr_cb, wrap_c, 8, mb_block_height, mb_x*8, mb_y*8, s->width>>1, s->height>>1);

        ptr_cb= ebuf+18*wrap_y;

        ff_emulated_edge_mc(ebuf+18*wrap_y+8, ptr_cr, wrap_c, 8, mb_block_height, mb_x*8, mb_y*8, s->width>>1, s->height>>1);

        ptr_cr= ebuf+18*wrap_y+8;

    }



    if (s->mb_intra) {

        if(s->flags&CODEC_FLAG_INTERLACED_DCT){

            int progressive_score, interlaced_score;



            s->interlaced_dct=0;

            progressive_score= s->dsp.ildct_cmp[4](s, ptr_y           , NULL, wrap_y, 8)

                              +s->dsp.ildct_cmp[4](s, ptr_y + wrap_y*8, NULL, wrap_y, 8) - 400;



            if(progressive_score > 0){

                interlaced_score = s->dsp.ildct_cmp[4](s, ptr_y           , NULL, wrap_y*2, 8)

                                  +s->dsp.ildct_cmp[4](s, ptr_y + wrap_y  , NULL, wrap_y*2, 8);

                if(progressive_score > interlaced_score){

                    s->interlaced_dct=1;



                    dct_offset= wrap_y;

                    wrap_y<<=1;

                    if (s->chroma_format == CHROMA_422)

                        wrap_c<<=1;

                }

            }

        }



        s->dsp.get_pixels(s->block[0], ptr_y                 , wrap_y);

        s->dsp.get_pixels(s->block[1], ptr_y              + 8, wrap_y);

        s->dsp.get_pixels(s->block[2], ptr_y + dct_offset    , wrap_y);

        s->dsp.get_pixels(s->block[3], ptr_y + dct_offset + 8, wrap_y);



        if(s->flags&CODEC_FLAG_GRAY){

            skip_dct[4]= 1;

            skip_dct[5]= 1;

        }else{

            s->dsp.get_pixels(s->block[4], ptr_cb, wrap_c);

            s->dsp.get_pixels(s->block[5], ptr_cr, wrap_c);

            if(!s->chroma_y_shift){ /* 422 */

                s->dsp.get_pixels(s->block[6], ptr_cb + (dct_offset>>1), wrap_c);

                s->dsp.get_pixels(s->block[7], ptr_cr + (dct_offset>>1), wrap_c);

            }

        }

    }else{

        op_pixels_func (*op_pix)[4];

        qpel_mc_func (*op_qpix)[16];

        uint8_t *dest_y, *dest_cb, *dest_cr;



        dest_y  = s->dest[0];

        dest_cb = s->dest[1];

        dest_cr = s->dest[2];



        if ((!s->no_rounding) || s->pict_type==FF_B_TYPE){

            op_pix = s->dsp.put_pixels_tab;

            op_qpix= s->dsp.put_qpel_pixels_tab;

        }else{

            op_pix = s->dsp.put_no_rnd_pixels_tab;

            op_qpix= s->dsp.put_no_rnd_qpel_pixels_tab;

        }



        if (s->mv_dir & MV_DIR_FORWARD) {

            MPV_motion(s, dest_y, dest_cb, dest_cr, 0, s->last_picture.data, op_pix, op_qpix);

            op_pix = s->dsp.avg_pixels_tab;

            op_qpix= s->dsp.avg_qpel_pixels_tab;

        }

        if (s->mv_dir & MV_DIR_BACKWARD) {

            MPV_motion(s, dest_y, dest_cb, dest_cr, 1, s->next_picture.data, op_pix, op_qpix);

        }



        if(s->flags&CODEC_FLAG_INTERLACED_DCT){

            int progressive_score, interlaced_score;



            s->interlaced_dct=0;

            progressive_score= s->dsp.ildct_cmp[0](s, dest_y           , ptr_y           , wrap_y, 8)

                              +s->dsp.ildct_cmp[0](s, dest_y + wrap_y*8, ptr_y + wrap_y*8, wrap_y, 8) - 400;



            if(s->avctx->ildct_cmp == FF_CMP_VSSE) progressive_score -= 400;



            if(progressive_score>0){

                interlaced_score = s->dsp.ildct_cmp[0](s, dest_y           , ptr_y           , wrap_y*2, 8)

                                  +s->dsp.ildct_cmp[0](s, dest_y + wrap_y  , ptr_y + wrap_y  , wrap_y*2, 8);



                if(progressive_score > interlaced_score){

                    s->interlaced_dct=1;



                    dct_offset= wrap_y;

                    wrap_y<<=1;

                    if (s->chroma_format == CHROMA_422)

                        wrap_c<<=1;

                }

            }

        }



        s->dsp.diff_pixels(s->block[0], ptr_y                 , dest_y                 , wrap_y);

        s->dsp.diff_pixels(s->block[1], ptr_y              + 8, dest_y              + 8, wrap_y);

        s->dsp.diff_pixels(s->block[2], ptr_y + dct_offset    , dest_y + dct_offset    , wrap_y);

        s->dsp.diff_pixels(s->block[3], ptr_y + dct_offset + 8, dest_y + dct_offset + 8, wrap_y);



        if(s->flags&CODEC_FLAG_GRAY){

            skip_dct[4]= 1;

            skip_dct[5]= 1;

        }else{

            s->dsp.diff_pixels(s->block[4], ptr_cb, dest_cb, wrap_c);

            s->dsp.diff_pixels(s->block[5], ptr_cr, dest_cr, wrap_c);

            if(!s->chroma_y_shift){ /* 422 */

                s->dsp.diff_pixels(s->block[6], ptr_cb + (dct_offset>>1), dest_cb + (dct_offset>>1), wrap_c);

                s->dsp.diff_pixels(s->block[7], ptr_cr + (dct_offset>>1), dest_cr + (dct_offset>>1), wrap_c);

            }

        }

        /* pre quantization */

        if(s->current_picture.mc_mb_var[s->mb_stride*mb_y+ mb_x]<2*s->qscale*s->qscale){

            //FIXME optimize

            if(s->dsp.sad[1](NULL, ptr_y               , dest_y               , wrap_y, 8) < 20*s->qscale) skip_dct[0]= 1;

            if(s->dsp.sad[1](NULL, ptr_y            + 8, dest_y            + 8, wrap_y, 8) < 20*s->qscale) skip_dct[1]= 1;

            if(s->dsp.sad[1](NULL, ptr_y +dct_offset   , dest_y +dct_offset   , wrap_y, 8) < 20*s->qscale) skip_dct[2]= 1;

            if(s->dsp.sad[1](NULL, ptr_y +dct_offset+ 8, dest_y +dct_offset+ 8, wrap_y, 8) < 20*s->qscale) skip_dct[3]= 1;

            if(s->dsp.sad[1](NULL, ptr_cb              , dest_cb              , wrap_c, 8) < 20*s->qscale) skip_dct[4]= 1;

            if(s->dsp.sad[1](NULL, ptr_cr              , dest_cr              , wrap_c, 8) < 20*s->qscale) skip_dct[5]= 1;

            if(!s->chroma_y_shift){ /* 422 */

                if(s->dsp.sad[1](NULL, ptr_cb +(dct_offset>>1), dest_cb +(dct_offset>>1), wrap_c, 8) < 20*s->qscale) skip_dct[6]= 1;

                if(s->dsp.sad[1](NULL, ptr_cr +(dct_offset>>1), dest_cr +(dct_offset>>1), wrap_c, 8) < 20*s->qscale) skip_dct[7]= 1;

            }

        }

    }



    if(s->avctx->quantizer_noise_shaping){

        if(!skip_dct[0]) get_visual_weight(weight[0], ptr_y                 , wrap_y);

        if(!skip_dct[1]) get_visual_weight(weight[1], ptr_y              + 8, wrap_y);

        if(!skip_dct[2]) get_visual_weight(weight[2], ptr_y + dct_offset    , wrap_y);

        if(!skip_dct[3]) get_visual_weight(weight[3], ptr_y + dct_offset + 8, wrap_y);

        if(!skip_dct[4]) get_visual_weight(weight[4], ptr_cb                , wrap_c);

        if(!skip_dct[5]) get_visual_weight(weight[5], ptr_cr                , wrap_c);

        if(!s->chroma_y_shift){ /* 422 */

            if(!skip_dct[6]) get_visual_weight(weight[6], ptr_cb + (dct_offset>>1), wrap_c);

            if(!skip_dct[7]) get_visual_weight(weight[7], ptr_cr + (dct_offset>>1), wrap_c);

        }

        memcpy(orig[0], s->block[0], sizeof(DCTELEM)*64*mb_block_count);

    }



    /* DCT & quantize */

    assert(s->out_format!=FMT_MJPEG || s->qscale==8);

    {

        for(i=0;i<mb_block_count;i++) {

            if(!skip_dct[i]){

                int overflow;

                s->block_last_index[i] = s->dct_quantize(s, s->block[i], i, s->qscale, &overflow);

            // FIXME we could decide to change to quantizer instead of clipping

            // JS: I don't think that would be a good idea it could lower quality instead

            //     of improve it. Just INTRADC clipping deserves changes in quantizer

                if (overflow) clip_coeffs(s, s->block[i], s->block_last_index[i]);

            }else

                s->block_last_index[i]= -1;

        }

        if(s->avctx->quantizer_noise_shaping){

            for(i=0;i<mb_block_count;i++) {

                if(!skip_dct[i]){

                    s->block_last_index[i] = dct_quantize_refine(s, s->block[i], weight[i], orig[i], i, s->qscale);

                }

            }

        }



        if(s->luma_elim_threshold && !s->mb_intra)

            for(i=0; i<4; i++)

                dct_single_coeff_elimination(s, i, s->luma_elim_threshold);

        if(s->chroma_elim_threshold && !s->mb_intra)

            for(i=4; i<mb_block_count; i++)

                dct_single_coeff_elimination(s, i, s->chroma_elim_threshold);



        if(s->flags & CODEC_FLAG_CBP_RD){

            for(i=0;i<mb_block_count;i++) {

                if(s->block_last_index[i] == -1)

                    s->coded_score[i]= INT_MAX/256;

            }

        }

    }



    if((s->flags&CODEC_FLAG_GRAY) && s->mb_intra){

        s->block_last_index[4]=

        s->block_last_index[5]= 0;

        s->block[4][0]=

        s->block[5][0]= (1024 + s->c_dc_scale/2)/ s->c_dc_scale;

    }



    //non c quantize code returns incorrect block_last_index FIXME

    if(s->alternate_scan && s->dct_quantize != dct_quantize_c){

        for(i=0; i<mb_block_count; i++){

            int j;

            if(s->block_last_index[i]>0){

                for(j=63; j>0; j--){

                    if(s->block[i][ s->intra_scantable.permutated[j] ]) break;

                }

                s->block_last_index[i]= j;

            }

        }

    }



    /* huffman encode */

    switch(s->codec_id){ //FIXME funct ptr could be slightly faster

    case CODEC_ID_MPEG1VIDEO:

    case CODEC_ID_MPEG2VIDEO:

        if (CONFIG_MPEG1VIDEO_ENCODER || CONFIG_MPEG2VIDEO_ENCODER)

            mpeg1_encode_mb(s, s->block, motion_x, motion_y);

        break;

    case CODEC_ID_MPEG4:

        if (CONFIG_MPEG4_ENCODER)

            mpeg4_encode_mb(s, s->block, motion_x, motion_y);

        break;

    case CODEC_ID_MSMPEG4V2:

    case CODEC_ID_MSMPEG4V3:

    case CODEC_ID_WMV1:

        if (CONFIG_MSMPEG4_ENCODER)

            msmpeg4_encode_mb(s, s->block, motion_x, motion_y);

        break;

    case CODEC_ID_WMV2:

        if (CONFIG_WMV2_ENCODER)

            ff_wmv2_encode_mb(s, s->block, motion_x, motion_y);

        break;

    case CODEC_ID_H261:

        if (CONFIG_H261_ENCODER)

            ff_h261_encode_mb(s, s->block, motion_x, motion_y);

        break;

    case CODEC_ID_H263:

    case CODEC_ID_H263P:

    case CODEC_ID_FLV1:

    case CODEC_ID_RV10:

    case CODEC_ID_RV20:

        if (CONFIG_H263_ENCODER || CONFIG_H263P_ENCODER ||

            CONFIG_FLV_ENCODER  || CONFIG_RV10_ENCODER  || CONFIG_RV20_ENCODER)

            h263_encode_mb(s, s->block, motion_x, motion_y);

        break;

    case CODEC_ID_MJPEG:

        if (CONFIG_MJPEG_ENCODER)

            ff_mjpeg_encode_mb(s, s->block);

        break;

    default:

        assert(0);

    }

}

void av_log_format_line(void *ptr, int level, const char *fmt, va_list vl,

                        char *line, int line_size, int *print_prefix)

{

    char part[3][512];

    format_line(ptr, level, fmt, vl, part, sizeof(part[0]), print_prefix, NULL);

    snprintf(line, line_size, "%s%s%s", part[0], part[1], part[2]);

}

static inline void RENAME(rgb32tobgr15)(const uint8_t *src, uint8_t *dst, long src_size)

{

	const uint8_t *s = src;

	const uint8_t *end;

#ifdef HAVE_MMX

	const uint8_t *mm_end;

#endif

	uint16_t *d = (uint16_t *)dst;

	end = s + src_size;

#ifdef HAVE_MMX

	__asm __volatile(PREFETCH"	%0"::"m"(*src):"memory");

	__asm __volatile(

	    "movq	%0, %%mm7\n\t"

	    "movq	%1, %%mm6\n\t"

	    ::"m"(red_15mask),"m"(green_15mask));

	mm_end = end - 15;

	while(s < mm_end)

	{

	    __asm __volatile(

		PREFETCH" 32%1\n\t"

		"movd	%1, %%mm0\n\t"

		"movd	4%1, %%mm3\n\t"

		"punpckldq 8%1, %%mm0\n\t"

		"punpckldq 12%1, %%mm3\n\t"

		"movq	%%mm0, %%mm1\n\t"

		"movq	%%mm0, %%mm2\n\t"

		"movq	%%mm3, %%mm4\n\t"

		"movq	%%mm3, %%mm5\n\t"

		"psllq	$7, %%mm0\n\t"

		"psllq	$7, %%mm3\n\t"

		"pand	%%mm7, %%mm0\n\t"

		"pand	%%mm7, %%mm3\n\t"

		"psrlq	$6, %%mm1\n\t"

		"psrlq	$6, %%mm4\n\t"

		"pand	%%mm6, %%mm1\n\t"

		"pand	%%mm6, %%mm4\n\t"

		"psrlq	$19, %%mm2\n\t"

		"psrlq	$19, %%mm5\n\t"

		"pand	%2, %%mm2\n\t"

		"pand	%2, %%mm5\n\t"

		"por	%%mm1, %%mm0\n\t"

		"por	%%mm4, %%mm3\n\t"

		"por	%%mm2, %%mm0\n\t"

		"por	%%mm5, %%mm3\n\t"

		"psllq	$16, %%mm3\n\t"

		"por	%%mm3, %%mm0\n\t"

		MOVNTQ"	%%mm0, %0\n\t"

		:"=m"(*d):"m"(*s),"m"(blue_15mask):"memory");

		d += 4;

		s += 16;

	}

	__asm __volatile(SFENCE:::"memory");

	__asm __volatile(EMMS:::"memory");

#endif

	while(s < end)

	{

		register int rgb = *(uint32_t*)s; s += 4;

		*d++ = ((rgb&0xF8)<<7) + ((rgb&0xF800)>>6) + ((rgb&0xF80000)>>19);

	}

}

static int http_receive_data(HTTPContext *c)

{

    HTTPContext *c1;



    if (c->buffer_end > c->buffer_ptr) {

        int len;



        len = recv(c->fd, c->buffer_ptr, c->buffer_end - c->buffer_ptr, 0);

        if (len < 0) {

            if (ff_neterrno() != FF_NETERROR(EAGAIN) &&

                ff_neterrno() != FF_NETERROR(EINTR))

                /* error : close connection */

                goto fail;

        } else if (len == 0)

            /* end of connection : close it */

            goto fail;

        else {

            c->buffer_ptr += len;

            c->data_count += len;

            update_datarate(&c->datarate, c->data_count);

        }

    }



    if (c->buffer_ptr - c->buffer >= 2 && c->data_count > FFM_PACKET_SIZE) {

        if (c->buffer[0] != 'f' ||

            c->buffer[1] != 'm') {

            http_log("Feed stream has become desynchronized -- disconnecting\n");

            goto fail;

        }

    }



    if (c->buffer_ptr >= c->buffer_end) {

        FFStream *feed = c->stream;

        /* a packet has been received : write it in the store, except

           if header */

        if (c->data_count > FFM_PACKET_SIZE) {



            //            printf("writing pos=0x%"PRIx64" size=0x%"PRIx64"\n", feed->feed_write_index, feed->feed_size);

            /* XXX: use llseek or url_seek */

            lseek(c->feed_fd, feed->feed_write_index, SEEK_SET);

            if (write(c->feed_fd, c->buffer, FFM_PACKET_SIZE) < 0) {

                http_log("Error writing to feed file: %s\n", strerror(errno));

                goto fail;

            }



            feed->feed_write_index += FFM_PACKET_SIZE;

            /* update file size */

            if (feed->feed_write_index > c->stream->feed_size)

                feed->feed_size = feed->feed_write_index;



            /* handle wrap around if max file size reached */

            if (c->stream->feed_max_size && feed->feed_write_index >= c->stream->feed_max_size)

                feed->feed_write_index = FFM_PACKET_SIZE;



            /* write index */

            ffm_write_write_index(c->feed_fd, feed->feed_write_index);



            /* wake up any waiting connections */

            for(c1 = first_http_ctx; c1 != NULL; c1 = c1->next) {

                if (c1->state == HTTPSTATE_WAIT_FEED &&

                    c1->stream->feed == c->stream->feed)

                    c1->state = HTTPSTATE_SEND_DATA;

            }

        } else {

            /* We have a header in our hands that contains useful data */

            AVFormatContext *s = NULL;

            ByteIOContext *pb;

            AVInputFormat *fmt_in;

            int i;



            url_open_buf(&pb, c->buffer, c->buffer_end - c->buffer, URL_RDONLY);

            pb->is_streamed = 1;



            /* use feed output format name to find corresponding input format */

            fmt_in = av_find_input_format(feed->fmt->name);

            if (!fmt_in)

                goto fail;



            av_open_input_stream(&s, pb, c->stream->feed_filename, fmt_in, NULL);



            /* Now we have the actual streams */

            if (s->nb_streams != feed->nb_streams) {

                av_close_input_stream(s);

                av_free(pb);

                goto fail;

            }



            for (i = 0; i < s->nb_streams; i++)

                memcpy(feed->streams[i]->codec,

                       s->streams[i]->codec, sizeof(AVCodecContext));



            av_close_input_stream(s);

            av_free(pb);

        }

        c->buffer_ptr = c->buffer;

    }



    return 0;

 fail:

    c->stream->feed_opened = 0;

    close(c->feed_fd);

    /* wake up any waiting connections to stop waiting for feed */

    for(c1 = first_http_ctx; c1 != NULL; c1 = c1->next) {

        if (c1->state == HTTPSTATE_WAIT_FEED &&

            c1->stream->feed == c->stream->feed)

            c1->state = HTTPSTATE_SEND_DATA_TRAILER;

    }

    return -1;

}

static int init_filter_param(AVFilterContext *ctx, FilterParam *fp, const char *effect_type, int width)

{

    int z;

    const char *effect = fp->amount == 0 ? "none" : fp->amount < 0 ? "blur" : "sharpen";



    if  (!(fp->msize_x & fp->msize_y & 1)) {

        av_log(ctx, AV_LOG_ERROR,

               "Invalid even size for %s matrix size %dx%d\n",

               effect_type, fp->msize_x, fp->msize_y);

        return AVERROR(EINVAL);

    }



    av_log(ctx, AV_LOG_VERBOSE, "effect:%s type:%s msize_x:%d msize_y:%d amount:%0.2f\n",

           effect, effect_type, fp->msize_x, fp->msize_y, fp->amount / 65535.0);



    for (z = 0; z < 2 * fp->steps_y; z++)

        fp->sc[z] = av_malloc(sizeof(*(fp->sc[z])) * (width + 2 * fp->steps_x));



    return 0;

}

static void do_video_out(AVFormatContext *s,

                         AVOutputStream *ost,

                         AVInputStream *ist,

                         AVFrame *in_picture,

                         int *frame_size)

{

    int nb_frames, i, ret;

    AVFrame *final_picture, *formatted_picture, *resampling_dst, *padding_src;

    AVFrame picture_crop_temp, picture_pad_temp;

    AVCodecContext *enc, *dec;



    avcodec_get_frame_defaults(&picture_crop_temp);

    avcodec_get_frame_defaults(&picture_pad_temp);



    enc = ost->st->codec;

    dec = ist->st->codec;



    /* by default, we output a single frame */

    nb_frames = 1;



    *frame_size = 0;



    if(video_sync_method>0 || (video_sync_method && av_q2d(enc->time_base) > 0.001)){

        double vdelta;

        vdelta = get_sync_ipts(ost) / av_q2d(enc->time_base) - ost->sync_opts;

        //FIXME set to 0.5 after we fix some dts/pts bugs like in avidec.c

        if (vdelta < -1.1)

            nb_frames = 0;

        else if (video_sync_method == 2)

            ost->sync_opts= lrintf(get_sync_ipts(ost) / av_q2d(enc->time_base));

        else if (vdelta > 1.1)

            nb_frames = lrintf(vdelta);

//fprintf(stderr, "vdelta:%f, ost->sync_opts:%"PRId64", ost->sync_ipts:%f nb_frames:%d\n", vdelta, ost->sync_opts, ost->sync_ipts, nb_frames);

        if (nb_frames == 0){

            ++nb_frames_drop;

            if (verbose>2)

                fprintf(stderr, "*** drop!\n");

        }else if (nb_frames > 1) {

            nb_frames_dup += nb_frames;

            if (verbose>2)

                fprintf(stderr, "*** %d dup!\n", nb_frames-1);

        }

    }else

        ost->sync_opts= lrintf(get_sync_ipts(ost) / av_q2d(enc->time_base));



    nb_frames= FFMIN(nb_frames, max_frames[CODEC_TYPE_VIDEO] - ost->frame_number);

    if (nb_frames <= 0)

        return;



    if (ost->video_crop) {

        if (av_picture_crop((AVPicture *)&picture_crop_temp, (AVPicture *)in_picture, dec->pix_fmt, ost->topBand, ost->leftBand) < 0) {

            av_log(NULL, AV_LOG_ERROR, "error cropping picture\n");

            if (exit_on_error)

                av_exit(1);

            return;

        }

        formatted_picture = &picture_crop_temp;

    } else {

        formatted_picture = in_picture;

    }



    final_picture = formatted_picture;

    padding_src = formatted_picture;

    resampling_dst = &ost->pict_tmp;

    if (ost->video_pad) {

        final_picture = &ost->pict_tmp;

        if (ost->video_resample) {

            if (av_picture_crop((AVPicture *)&picture_pad_temp, (AVPicture *)final_picture, enc->pix_fmt, ost->padtop, ost->padleft) < 0) {

                av_log(NULL, AV_LOG_ERROR, "error padding picture\n");

                if (exit_on_error)

                    av_exit(1);

                return;

            }

            resampling_dst = &picture_pad_temp;

        }

    }



    if (ost->video_resample) {

        padding_src = NULL;

        final_picture = &ost->pict_tmp;

        sws_scale(ost->img_resample_ctx, formatted_picture->data, formatted_picture->linesize,

              0, ost->resample_height, resampling_dst->data, resampling_dst->linesize);

    }



    if (ost->video_pad) {

        av_picture_pad((AVPicture*)final_picture, (AVPicture *)padding_src,

                enc->height, enc->width, enc->pix_fmt,

                ost->padtop, ost->padbottom, ost->padleft, ost->padright, padcolor);

    }



    /* duplicates frame if needed */

    for(i=0;i<nb_frames;i++) {

        AVPacket pkt;

        av_init_packet(&pkt);

        pkt.stream_index= ost->index;



        if (s->oformat->flags & AVFMT_RAWPICTURE) {

            /* raw pictures are written as AVPicture structure to

               avoid any copies. We support temorarily the older

               method. */

            AVFrame* old_frame = enc->coded_frame;

            enc->coded_frame = dec->coded_frame; //FIXME/XXX remove this hack

            pkt.data= (uint8_t *)final_picture;

            pkt.size=  sizeof(AVPicture);

            pkt.pts= av_rescale_q(ost->sync_opts, enc->time_base, ost->st->time_base);

            pkt.flags |= PKT_FLAG_KEY;



            write_frame(s, &pkt, ost->st->codec, bitstream_filters[ost->file_index][pkt.stream_index]);

            enc->coded_frame = old_frame;

        } else {

            AVFrame big_picture;



            big_picture= *final_picture;

            /* better than nothing: use input picture interlaced

               settings */

            big_picture.interlaced_frame = in_picture->interlaced_frame;

            if(avctx_opts[CODEC_TYPE_VIDEO]->flags & (CODEC_FLAG_INTERLACED_DCT|CODEC_FLAG_INTERLACED_ME)){

                if(top_field_first == -1)

                    big_picture.top_field_first = in_picture->top_field_first;

                else

                    big_picture.top_field_first = top_field_first;

            }



            /* handles sameq here. This is not correct because it may

               not be a global option */

            if (same_quality) {

                big_picture.quality = ist->st->quality;

            }else

                big_picture.quality = ost->st->quality;

            if(!me_threshold)

                big_picture.pict_type = 0;

//            big_picture.pts = AV_NOPTS_VALUE;

            big_picture.pts= ost->sync_opts;

//            big_picture.pts= av_rescale(ost->sync_opts, AV_TIME_BASE*(int64_t)enc->time_base.num, enc->time_base.den);

//av_log(NULL, AV_LOG_DEBUG, "%"PRId64" -> encoder\n", ost->sync_opts);

            ret = avcodec_encode_video(enc,

                                       bit_buffer, bit_buffer_size,

                                       &big_picture);

            if (ret == -1) {

                fprintf(stderr, "Video encoding failed\n");

                av_exit(1);

            }

            //enc->frame_number = enc->real_pict_num;

            if(ret>0){

                pkt.data= bit_buffer;

                pkt.size= ret;

                if(enc->coded_frame->pts != AV_NOPTS_VALUE)

                    pkt.pts= av_rescale_q(enc->coded_frame->pts, enc->time_base, ost->st->time_base);

/*av_log(NULL, AV_LOG_DEBUG, "encoder -> %"PRId64"/%"PRId64"\n",

   pkt.pts != AV_NOPTS_VALUE ? av_rescale(pkt.pts, enc->time_base.den, AV_TIME_BASE*(int64_t)enc->time_base.num) : -1,

   pkt.dts != AV_NOPTS_VALUE ? av_rescale(pkt.dts, enc->time_base.den, AV_TIME_BASE*(int64_t)enc->time_base.num) : -1);*/



                if(enc->coded_frame->key_frame)

                    pkt.flags |= PKT_FLAG_KEY;

                write_frame(s, &pkt, ost->st->codec, bitstream_filters[ost->file_index][pkt.stream_index]);

                *frame_size = ret;

                video_size += ret;

                //fprintf(stderr,"\nFrame: %3d %3d size: %5d type: %d",

                //        enc->frame_number-1, enc->real_pict_num, ret,

                //        enc->pict_type);

                /* if two pass, output log */

                if (ost->logfile && enc->stats_out) {

                    fprintf(ost->logfile, "%s", enc->stats_out);

                }

            }

        }

        ost->sync_opts++;

        ost->frame_number++;

    }

}

static int process_ea_header(AVFormatContext *s) {

    uint32_t blockid, size = 0;

    EaDemuxContext *ea = s->priv_data;

    ByteIOContext *pb = &s->pb;



    blockid = get_le32(pb);

    if (blockid == MVhd_TAG) {

        size = get_le32(pb);

        process_video_header_vp6(s);

        url_fskip(pb, size-32);

        blockid = get_le32(pb);

    }

    if (blockid != SCHl_TAG)

        return 0;

    size += get_le32(pb);

    blockid = get_le32(pb);

    if (blockid == GSTR_TAG) {

        url_fskip(pb, 4);

    } else if (blockid != PT00_TAG) {

        av_log (s, AV_LOG_ERROR, "unknown SCHl headerid\n");

        return 0;

    }



    process_audio_header_elements(s);



    /* skip to the start of the data */

    url_fseek(pb, size, SEEK_SET);



    return 1;

}

static void check_external_clock_sync(VideoState *is, double pts) {

    if (fabs(get_external_clock(is) - pts) > AV_NOSYNC_THRESHOLD) {

        update_external_clock_pts(is, pts);

    }

}

static int mov_read_stsd(MOVContext *c, ByteIOContext *pb, MOV_atom_t atom)

{

    AVStream *st = c->fc->streams[c->fc->nb_streams-1];

    MOVStreamContext *sc = (MOVStreamContext *)st->priv_data;

    int entries, frames_per_sample;

    uint32_t format;



    print_atom("stsd", atom);



    get_byte(pb); /* version */

    get_byte(pb); get_byte(pb); get_byte(pb); /* flags */



    entries = get_be32(pb);



    while(entries--) {

        enum CodecID id;

	int size = get_be32(pb); /* size */

        format = get_le32(pb); /* data format */



        get_be32(pb); /* reserved */

        get_be16(pb); /* reserved */

        get_be16(pb); /* index */



        /* for MPEG4: set codec type by looking for it */

        id = codec_get_id(mov_video_tags, format);

        if (id >= 0) {

            AVCodec *codec;

	    codec = avcodec_find_decoder(id);

            if (codec)

		st->codec.codec_type = codec->type;

        }

#ifdef DEBUG

        printf("size=%d 4CC= %c%c%c%c codec_type=%d\n",

               size,

               (format >> 0) & 0xff,

               (format >> 8) & 0xff,

               (format >> 16) & 0xff,

               (format >> 24) & 0xff,

               st->codec.codec_type);

#endif

	st->codec.codec_tag = format;

	if(st->codec.codec_type==CODEC_TYPE_VIDEO) {

	    MOV_atom_t a = { 0, 0, 0 };

            st->codec.codec_id = id;

            get_be16(pb); /* version */

            get_be16(pb); /* revision level */

            get_be32(pb); /* vendor */

            get_be32(pb); /* temporal quality */

            get_be32(pb); /* spacial quality */

            st->codec.width = get_be16(pb); /* width */

            st->codec.height = get_be16(pb); /* height */

#if 1

            if (st->codec.codec_id == CODEC_ID_MPEG4) {

                /* in some MPEG4 the width/height are not correct, so

                   we ignore this info */

                st->codec.width = 0;

                st->codec.height = 0;

            }

#endif

            get_be32(pb); /* horiz resolution */

            get_be32(pb); /* vert resolution */

            get_be32(pb); /* data size, always 0 */

            frames_per_sample = get_be16(pb); /* frames per samples */

#ifdef DEBUG

	    printf("frames/samples = %d\n", frames_per_sample);

#endif

	    get_buffer(pb, (uint8_t *)st->codec.codec_name, 32); /* codec name */



	    st->codec.bits_per_sample = get_be16(pb); /* depth */

            st->codec.color_table_id = get_be16(pb); /* colortable id */



            st->codec.frame_rate      = 25;

            st->codec.frame_rate_base = 1;



	    size -= (16+8*4+2+32+2*2);

#if 0

	    while (size >= 8) {

		MOV_atom_t a;

                int64_t start_pos;



		a.size = get_be32(pb);

		a.type = get_le32(pb);

		size -= 8;

#ifdef DEBUG

                printf("VIDEO: atom_type=%c%c%c%c atom.size=%Ld size_left=%d\n",

                       (a.type >> 0) & 0xff,

                       (a.type >> 8) & 0xff,

                       (a.type >> 16) & 0xff,

                       (a.type >> 24) & 0xff,

		       a.size, size);

#endif

                start_pos = url_ftell(pb);



		switch(a.type) {

                case MKTAG('e', 's', 'd', 's'):

                    {

                        int tag, len;

                        /* Well, broken but suffisant for some MP4 streams */

                        get_be32(pb); /* version + flags */

			len = mov_mp4_read_descr(pb, &tag);

                        if (tag == 0x03) {

                            /* MP4ESDescrTag */

                            get_be16(pb); /* ID */

                            get_byte(pb); /* priority */

			    len = mov_mp4_read_descr(pb, &tag);

                            if (tag != 0x04)

                                goto fail;

                            /* MP4DecConfigDescrTag */

                            get_byte(pb); /* objectTypeId */

                            get_be32(pb); /* streamType + buffer size */

			    get_be32(pb); /* max bit rate */

                            get_be32(pb); /* avg bit rate */

                            len = mp4_read_descr(pb, &tag);

                            if (tag != 0x05)

                                goto fail;

                            /* MP4DecSpecificDescrTag */

#ifdef DEBUG

                            printf("Specific MPEG4 header len=%d\n", len);

#endif

                            sc->header_data = av_mallocz(len);

                            if (sc->header_data) {

                                get_buffer(pb, sc->header_data, len);

				sc->header_len = len;

                            }

                        }

                        /* in any case, skip garbage */

                    }

                    break;

                default:

                    break;

                }

	    fail:

		printf("ATOMENEWSIZE %Ld   %d\n", atom.size, url_ftell(pb) - start_pos);

		if (atom.size > 8) {

		    url_fskip(pb, (atom.size - 8) -

			      ((url_ftell(pb) - start_pos)));

		    size -= atom.size - 8;

		}

	    }

            if (size > 0) {

                /* unknown extension */

                url_fskip(pb, size);

            }

#else

            a.size = size;

	    mov_read_default(c, pb, a);

#endif

	} else {

            get_be16(pb); /* version */

            get_be16(pb); /* revision level */

            get_be32(pb); /* vendor */



            st->codec.channels = get_be16(pb);		/* channel count */

	    st->codec.bits_per_sample = get_be16(pb);	/* sample size */



	    st->codec.codec_id = codec_get_id(mov_audio_tags, format);

            /* handle specific s8 codec */

            get_be16(pb); /* compression id = 0*/

            get_be16(pb); /* packet size = 0 */



            st->codec.sample_rate = ((get_be32(pb) >> 16));

	    //printf("CODECID %d  %d  %.4s\n", st->codec.codec_id, CODEC_ID_PCM_S16BE, (char*)&format);



	    switch (st->codec.codec_id) {

	    case CODEC_ID_PCM_S16BE:

		if (st->codec.bits_per_sample == 8)

		    st->codec.codec_id = CODEC_ID_PCM_S8;

                /* fall */

	    case CODEC_ID_PCM_U8:

		st->codec.bit_rate = st->codec.sample_rate * 8;

		break;

	    default:

                ;

	    }

	    get_be32(pb); /* samples per packet */

	    get_be32(pb); /* bytes per packet */

            get_be32(pb); /* bytes per frame */

            get_be32(pb); /* bytes per sample */



	    {

		MOV_atom_t a = { format, url_ftell(pb), size - (16 + 20 + 16 + 8) };

		mov_read_default(c, pb, a);

	    }

        }

    }



    return 0;

}

int av_packet_add_side_data(AVPacket *pkt, enum AVPacketSideDataType type,

                            uint8_t *data, size_t size)

{

    int elems = pkt->side_data_elems;



    if ((unsigned)elems + 1 > INT_MAX / sizeof(*pkt->side_data))

        return AVERROR(ERANGE);



    pkt->side_data = av_realloc(pkt->side_data,

                                (elems + 1) * sizeof(*pkt->side_data));

    if (!pkt->side_data)

        return AVERROR(ENOMEM);



    pkt->side_data[elems].data = data;

    pkt->side_data[elems].size = size;

    pkt->side_data[elems].type = type;

    pkt->side_data_elems++;



    return 0;

}

static int get_siz(J2kDecoderContext *s)
{
    int i, ret;
    if (s->buf_end - s->buf < 36)
                        bytestream_get_be16(&s->buf); // Rsiz (skipped)
             s->width = bytestream_get_be32(&s->buf); // width
            s->height = bytestream_get_be32(&s->buf); // height
    s->image_offset_x = bytestream_get_be32(&s->buf); // X0Siz
    s->image_offset_y = bytestream_get_be32(&s->buf); // Y0Siz
        s->tile_width = bytestream_get_be32(&s->buf); // XTSiz
       s->tile_height = bytestream_get_be32(&s->buf); // YTSiz
     s->tile_offset_x = bytestream_get_be32(&s->buf); // XT0Siz
     s->tile_offset_y = bytestream_get_be32(&s->buf); // YT0Siz
       s->ncomponents = bytestream_get_be16(&s->buf); // CSiz
    if (s->buf_end - s->buf < 2 * s->ncomponents)
    for (i = 0; i < s->ncomponents; i++){ // Ssiz_i XRsiz_i, YRsiz_i
        uint8_t x = bytestream_get_byte(&s->buf);
        s->cbps[i] = (x & 0x7f) + 1;
        s->precision = FFMAX(s->cbps[i], s->precision);
        s->sgnd[i] = !!(x & 0x80);
        s->cdx[i] = bytestream_get_byte(&s->buf);
        s->cdy[i] = bytestream_get_byte(&s->buf);
    }
    s->numXtiles = ff_j2k_ceildiv(s->width - s->tile_offset_x, s->tile_width);
    s->numYtiles = ff_j2k_ceildiv(s->height - s->tile_offset_y, s->tile_height);
    s->tile = av_mallocz(s->numXtiles * s->numYtiles * sizeof(J2kTile));
    if (!s->tile)
        return AVERROR(ENOMEM);
    for (i = 0; i < s->numXtiles * s->numYtiles; i++){
        J2kTile *tile = s->tile + i;
        tile->comp = av_mallocz(s->ncomponents * sizeof(J2kComponent));
        if (!tile->comp)
            return AVERROR(ENOMEM);
    }
    s->avctx->width = s->width - s->image_offset_x;
    s->avctx->height = s->height - s->image_offset_y;
    switch(s->ncomponents){
        case 1: if (s->precision > 8) {
                    s->avctx->pix_fmt    = PIX_FMT_GRAY16;
                } else s->avctx->pix_fmt = PIX_FMT_GRAY8;
                break;
        case 3: if (s->precision > 8) {
                    s->avctx->pix_fmt    = PIX_FMT_RGB48;
                } else s->avctx->pix_fmt = PIX_FMT_RGB24;
                break;
        case 4: s->avctx->pix_fmt = PIX_FMT_BGRA; break;
    }
    if (s->picture.data[0])
        s->avctx->release_buffer(s->avctx, &s->picture);
    if ((ret = s->avctx->get_buffer(s->avctx, &s->picture)) < 0)
        return ret;
    s->picture.pict_type = FF_I_TYPE;
    s->picture.key_frame = 1;
    return 0;
}

static int decode_ref_pic_marking(H264Context *h, GetBitContext *gb){

    MpegEncContext * const s = &h->s;

    int i;




    if(h->nal_unit_type == NAL_IDR_SLICE){ //FIXME fields

        s->broken_link= get_bits1(gb) -1;

        h->mmco[0].long_arg= get_bits1(gb) - 1; // current_long_term_idx

        if(h->mmco[0].long_arg == -1)


        else{

            h->mmco[0].opcode= MMCO_LONG;

            h->mmco_index= 1;

        }

    }else{

        if(get_bits1(gb)){ // adaptive_ref_pic_marking_mode_flag

            for(i= 0; i<MAX_MMCO_COUNT; i++) {

                MMCOOpcode opcode= get_ue_golomb(gb);



                h->mmco[i].opcode= opcode;

                if(opcode==MMCO_SHORT2UNUSED || opcode==MMCO_SHORT2LONG){

                    h->mmco[i].short_pic_num= (h->curr_pic_num - get_ue_golomb(gb) - 1) & (h->max_pic_num - 1);

/*                    if(h->mmco[i].short_pic_num >= h->short_ref_count || h->short_ref[ h->mmco[i].short_pic_num ] == NULL){

                        av_log(s->avctx, AV_LOG_ERROR, "illegal short ref in memory management control operation %d\n", mmco);

                        return -1;

                    }*/

                }

                if(opcode==MMCO_SHORT2LONG || opcode==MMCO_LONG2UNUSED || opcode==MMCO_LONG || opcode==MMCO_SET_MAX_LONG){

                    unsigned int long_arg= get_ue_golomb(gb);

                    if(long_arg >= 32 || (long_arg >= 16 && !(opcode == MMCO_LONG2UNUSED && FIELD_PICTURE))){

                        av_log(h->s.avctx, AV_LOG_ERROR, "illegal long ref in memory management control operation %d\n", opcode);

                        return -1;

                    }

                    h->mmco[i].long_arg= long_arg;

                }



                if(opcode > (unsigned)MMCO_LONG){

                    av_log(h->s.avctx, AV_LOG_ERROR, "illegal memory management control operation %d\n", opcode);

                    return -1;

                }

                if(opcode == MMCO_END)

                    break;

            }

            h->mmco_index= i;

        }else{

            assert(h->long_ref_count + h->short_ref_count <= h->sps.ref_frame_count);



            if(h->short_ref_count && h->long_ref_count + h->short_ref_count == h->sps.ref_frame_count &&

                    !(FIELD_PICTURE && !s->first_field && s->current_picture_ptr->reference)) {

                h->mmco[0].opcode= MMCO_SHORT2UNUSED;

                h->mmco[0].short_pic_num= h->short_ref[ h->short_ref_count - 1 ]->frame_num;

                h->mmco_index= 1;

                if (FIELD_PICTURE) {

                    h->mmco[0].short_pic_num *= 2;

                    h->mmco[1].opcode= MMCO_SHORT2UNUSED;

                    h->mmco[1].short_pic_num= h->mmco[0].short_pic_num + 1;

                    h->mmco_index= 2;

                }

            }else


        }

    }



    return 0;

}

static int decode_main_header(NUTContext *nut){

    AVFormatContext *s= nut->avf;

    ByteIOContext *bc = &s->pb;

    uint64_t tmp, end;

    unsigned int stream_count;

    int i, j, tmp_stream, tmp_mul, tmp_pts, tmp_size, count, tmp_res;



    end= get_packetheader(nut, bc, 1);

    end += url_ftell(bc) - 4;



    GET_V(tmp              , tmp >=2 && tmp <= 3)

    GET_V(stream_count     , tmp > 0 && tmp <=MAX_STREAMS)



    nut->max_distance = get_v(bc);

    if(nut->max_distance > 65536){

        av_log(s, AV_LOG_DEBUG, "max_distance %d\n", nut->max_distance);

        nut->max_distance= 65536;

    }



    GET_V(nut->time_base_count, tmp>0 && tmp<INT_MAX / sizeof(AVRational))

    nut->time_base= av_malloc(nut->time_base_count * sizeof(AVRational));



    for(i=0; i<nut->time_base_count; i++){

        GET_V(nut->time_base[i].num, tmp>0 && tmp<(1ULL<<31))

        GET_V(nut->time_base[i].den, tmp>0 && tmp<(1ULL<<31))

        if(ff_gcd(nut->time_base[i].num, nut->time_base[i].den) != 1){

            av_log(s, AV_LOG_ERROR, "time base invalid\n");

            return -1;

        }

    }

    tmp_pts=0;

    tmp_mul=1;

    tmp_stream=0;

    for(i=0; i<256;){

        int tmp_flags = get_v(bc);

        int tmp_fields= get_v(bc);

        if(tmp_fields>0) tmp_pts   = get_s(bc);

        if(tmp_fields>1) tmp_mul   = get_v(bc);

        if(tmp_fields>2) tmp_stream= get_v(bc);

        if(tmp_fields>3) tmp_size  = get_v(bc);

        else             tmp_size  = 0;

        if(tmp_fields>4) tmp_res   = get_v(bc);

        else             tmp_res   = 0;

        if(tmp_fields>5) count     = get_v(bc);

        else             count     = tmp_mul - tmp_size;



        while(tmp_fields-- > 6)

           get_v(bc);



        if(count == 0 || i+count > 256){

            av_log(s, AV_LOG_ERROR, "illegal count %d at %d\n", count, i);

            return -1;

        }

        if(tmp_stream >= stream_count){

            av_log(s, AV_LOG_ERROR, "illegal stream number\n");

            return -1;

        }



        for(j=0; j<count; j++,i++){

            if (i == 'N') {

                nut->frame_code[i].flags= FLAG_INVALID;

                j--;

                continue;

            }

            nut->frame_code[i].flags           = tmp_flags ;

            nut->frame_code[i].pts_delta       = tmp_pts   ;

            nut->frame_code[i].stream_id       = tmp_stream;

            nut->frame_code[i].size_mul        = tmp_mul   ;

            nut->frame_code[i].size_lsb        = tmp_size+j;

            nut->frame_code[i].reserved_count  = tmp_res   ;

        }

    }

    assert(nut->frame_code['N'].flags == FLAG_INVALID);



    if(skip_reserved(bc, end) || check_checksum(bc)){

        av_log(s, AV_LOG_ERROR, "Main header checksum mismatch\n");

        return -1;

    }



    nut->stream = av_mallocz(sizeof(StreamContext)*stream_count);

    for(i=0; i<stream_count; i++){

        av_new_stream(s, i);

    }



    return 0;

}

static void enqueue_packet(RTPDemuxContext *s, uint8_t *buf, int len)

{

    uint16_t seq   = AV_RB16(buf + 2);

    RTPPacket **cur = &s->queue, *packet;



    /* Find the correct place in the queue to insert the packet */

    while (*cur) {

        int16_t diff = seq - (*cur)->seq;

        if (diff < 0)

            break;

        cur = &(*cur)->next;

    }



    packet = av_mallocz(sizeof(*packet));

    if (!packet)

        return;

    packet->recvtime = av_gettime_relative();

    packet->seq      = seq;

    packet->len      = len;

    packet->buf      = buf;

    packet->next     = *cur;

    *cur = packet;

    s->queue_len++;

}

int ff_rv34_decode_frame(AVCodecContext *avctx,

                            void *data, int *data_size,

                            const uint8_t *buf, int buf_size)

{

    RV34DecContext *r = avctx->priv_data;

    MpegEncContext *s = &r->s;

    AVFrame *pict = data;

    SliceInfo si;

    int i;

    int slice_count;

    const uint8_t *slices_hdr = NULL;

    int last = 0;



    /* no supplementary picture */

    if (buf_size == 0) {

        /* special case for last picture */

        if (s->low_delay==0 && s->next_picture_ptr) {

            *pict= *(AVFrame*)s->next_picture_ptr;

            s->next_picture_ptr= NULL;



            *data_size = sizeof(AVFrame);

        }

        return 0;

    }



    if(!avctx->slice_count){

        slice_count = (*buf++) + 1;

        slices_hdr = buf + 4;

        buf += 8 * slice_count;

    }else

        slice_count = avctx->slice_count;



    for(i=0; i<slice_count; i++){

        int offset= get_slice_offset(avctx, slices_hdr, i);

        int size;

        if(i+1 == slice_count)

            size= buf_size - offset;

        else

            size= get_slice_offset(avctx, slices_hdr, i+1) - offset;



        if(offset > buf_size){

            av_log(avctx, AV_LOG_ERROR, "Slice offset is greater than frame size\n");

            break;

        }



        r->si.end = s->mb_width * s->mb_height;

        if(i+1 < slice_count){

            init_get_bits(&s->gb, buf+get_slice_offset(avctx, slices_hdr, i+1), (buf_size-get_slice_offset(avctx, slices_hdr, i+1))*8);

            if(r->parse_slice_header(r, &r->s.gb, &si) < 0){

                if(i+2 < slice_count)

                    size = get_slice_offset(avctx, slices_hdr, i+2) - offset;

                else

                    size = buf_size - offset;

            }else

                r->si.end = si.start;

        }

        if(!i && si.type == FF_B_TYPE && (!s->last_picture_ptr || !s->last_picture_ptr->data[0]))

            return -1;

        last = rv34_decode_slice(r, r->si.end, buf + offset, size);

        s->mb_num_left = r->s.mb_x + r->s.mb_y*r->s.mb_width - r->si.start;

        if(last)

            break;

    }



    if(last){

        if(r->loop_filter)

            r->loop_filter(r, s->mb_height - 1);

        ff_er_frame_end(s);

        MPV_frame_end(s);

        if (s->pict_type == FF_B_TYPE || s->low_delay) {

            *pict= *(AVFrame*)s->current_picture_ptr;

        } else if (s->last_picture_ptr != NULL) {

            *pict= *(AVFrame*)s->last_picture_ptr;

        }



        if(s->last_picture_ptr || s->low_delay){

            *data_size = sizeof(AVFrame);

            ff_print_debug_info(s, pict);

        }

        s->current_picture_ptr= NULL; //so we can detect if frame_end wasnt called (find some nicer solution...)

    }

    return buf_size;

}

static av_cold int mss2_decode_init(AVCodecContext *avctx)

{

    MSS2Context * const ctx = avctx->priv_data;

    MSS12Context *c = &ctx->c;

