static int expand(AVFilterContext *ctx, double *pz, int nb, double *coeffs)

{

    int i;



    coeffs[0] = 1.0;

    coeffs[1] = 0.0;



    for (i = 0; i < nb; i++) {

        coeffs[2 * (i + 1)    ] = 0.0;

        coeffs[2 * (i + 1) + 1] = 0.0;

    }



    for (i = 0; i < nb; i++)

        multiply(pz[2 * i], pz[2 * i + 1], nb, coeffs);



    for (i = 0; i < nb + 1; i++) {

        if (fabs(coeffs[2 * i + 1]) > DBL_EPSILON) {

            av_log(ctx, AV_LOG_ERROR, "coeff: %lf of z^%d is not real; poles/zeros are not complex conjugates.\n",

                   coeffs[2 * i + i], i);

            return AVERROR(EINVAL);

        }

    }



    return 0;

}

static int64_t ffm_seek1(AVFormatContext *s, int64_t pos1)

{

    FFMContext *ffm = s->priv_data;

    AVIOContext *pb = s->pb;

    int64_t pos;



    pos = FFMIN(pos1, ffm->file_size - FFM_PACKET_SIZE);

    pos = FFMAX(pos, FFM_PACKET_SIZE);

    av_dlog(s, "seek to %"PRIx64" -> %"PRIx64"\n", pos1, pos);

    return avio_seek(pb, pos, SEEK_SET);

}

static int raw_read_header(AVFormatContext *s, AVFormatParameters *ap)

{

    AVStream *st;

    int id;



    st = av_new_stream(s, 0);

    if (!st)

        return AVERROR_NOMEM;

    if (ap) {

        id = s->iformat->value;

        if (id == CODEC_ID_RAWVIDEO) {

            st->codec->codec_type = CODEC_TYPE_VIDEO;

        } else {

            st->codec->codec_type = CODEC_TYPE_AUDIO;

        }

        st->codec->codec_id = id;



        switch(st->codec->codec_type) {

        case CODEC_TYPE_AUDIO:

            st->codec->sample_rate = ap->sample_rate;

            st->codec->channels = ap->channels;

            av_set_pts_info(st, 64, 1, st->codec->sample_rate);

            break;

        case CODEC_TYPE_VIDEO:

            av_set_pts_info(st, 64, ap->time_base.num, ap->time_base.den);

            st->codec->width = ap->width;

            st->codec->height = ap->height;

            st->codec->pix_fmt = ap->pix_fmt;

            if(st->codec->pix_fmt == PIX_FMT_NONE)

                st->codec->pix_fmt= PIX_FMT_YUV420P;

            break;

        default:

            return -1;

        }

    } else {

        return -1;

    }

    return 0;

}

static av_cold int twin_decode_close(AVCodecContext *avctx)

{

    TwinContext *tctx = avctx->priv_data;

    int i;



    for (i = 0; i < 3; i++) {

        ff_mdct_end(&tctx->mdct_ctx[i]);

        av_free(tctx->cos_tabs[i]);

    }





    av_free(tctx->curr_frame);

    av_free(tctx->spectrum);

    av_free(tctx->prev_frame);

    av_free(tctx->tmp_buf);



    return 0;

}

static int asf_read_seek(AVFormatContext *s, int stream_index,

                         int64_t pts, int flags)

{

    ASFContext *asf = s->priv_data;

    AVStream *st    = s->streams[stream_index];

    int64_t pos;

    int index;



    if (s->packet_size <= 0)

        return -1;



    /* Try using the protocol's read_seek if available */

    if (s->pb) {

        int ret = avio_seek_time(s->pb, stream_index, pts, flags);

        if (ret >= 0)

            asf_reset_header(s);

        if (ret != AVERROR(ENOSYS))

            return ret;

    }



    if (!asf->index_read)

        asf_build_simple_index(s, stream_index);



    if ((asf->index_read && st->index_entries)) {

        index = av_index_search_timestamp(st, pts, flags);

        if (index >= 0) {

            /* find the position */

            pos = st->index_entries[index].pos;



            /* do the seek */

            av_log(s, AV_LOG_DEBUG, "SEEKTO: %"PRId64"\n", pos);

            avio_seek(s->pb, pos, SEEK_SET);

            asf_reset_header(s);

            return 0;

        }

    }

    /* no index or seeking by index failed */

    if (ff_seek_frame_binary(s, stream_index, pts, flags) < 0)

        return -1;

    asf_reset_header(s);

    return 0;

}

void ff_mpeg_unref_picture(MpegEncContext *s, Picture *pic)

{

    int off = offsetof(Picture, mb_mean) + sizeof(pic->mb_mean);



    pic->tf.f = &pic->f;

    /* WM Image / Screen codecs allocate internal buffers with different

     * dimensions / colorspaces; ignore user-defined callbacks for these. */

    if (s->codec_id != AV_CODEC_ID_WMV3IMAGE &&

        s->codec_id != AV_CODEC_ID_VC1IMAGE  &&

        s->codec_id != AV_CODEC_ID_MSS2)

        ff_thread_release_buffer(s->avctx, &pic->tf);

    else

        av_frame_unref(&pic->f);



    av_buffer_unref(&pic->hwaccel_priv_buf);



    if (pic->needs_realloc)

        ff_free_picture_tables(pic);



    memset((uint8_t*)pic + off, 0, sizeof(*pic) - off);

}

static int shorten_decode_frame(AVCodecContext *avctx, void *data,

                                int *got_frame_ptr, AVPacket *avpkt)

{

    AVFrame *frame     = data;

    const uint8_t *buf = avpkt->data;

    int buf_size       = avpkt->size;

    ShortenContext *s  = avctx->priv_data;

    int i, input_buf_size = 0;

    int ret;



    /* allocate internal bitstream buffer */

    if (s->max_framesize == 0) {

        void *tmp_ptr;

        s->max_framesize = 8192; // should hopefully be enough for the first header

        tmp_ptr = av_fast_realloc(s->bitstream, &s->allocated_bitstream_size,

                                  s->max_framesize + FF_INPUT_BUFFER_PADDING_SIZE);

        if (!tmp_ptr) {

            av_log(avctx, AV_LOG_ERROR, "error allocating bitstream buffer\n");

            return AVERROR(ENOMEM);

        }

        s->bitstream = tmp_ptr;

    }



    /* append current packet data to bitstream buffer */

    if (1 && s->max_framesize) { //FIXME truncated

        buf_size       = FFMIN(buf_size, s->max_framesize - s->bitstream_size);

        input_buf_size = buf_size;



        if (s->bitstream_index + s->bitstream_size + buf_size >

            s->allocated_bitstream_size) {

            memmove(s->bitstream, &s->bitstream[s->bitstream_index],

                    s->bitstream_size);

            s->bitstream_index = 0;

        }

        if (buf)

            memcpy(&s->bitstream[s->bitstream_index + s->bitstream_size], buf,

                   buf_size);

        buf               = &s->bitstream[s->bitstream_index];

        buf_size         += s->bitstream_size;

        s->bitstream_size = buf_size;



        /* do not decode until buffer has at least max_framesize bytes or

         * the end of the file has been reached */

        if (buf_size < s->max_framesize && avpkt->data) {

            *got_frame_ptr = 0;

            return input_buf_size;

        }

    }

    /* init and position bitstream reader */

    init_get_bits(&s->gb, buf, buf_size * 8);

    skip_bits(&s->gb, s->bitindex);



    /* process header or next subblock */

    if (!s->got_header) {

        if ((ret = read_header(s)) < 0)

            return ret;

        *got_frame_ptr = 0;

        goto finish_frame;

    }



    /* if quit command was read previously, don't decode anything */

    if (s->got_quit_command) {

        *got_frame_ptr = 0;

        return avpkt->size;

    }



    s->cur_chan = 0;

    while (s->cur_chan < s->channels) {

        unsigned cmd;

        int len;



        if (get_bits_left(&s->gb) < 3 + FNSIZE) {

            *got_frame_ptr = 0;

            break;

        }



        cmd = get_ur_golomb_shorten(&s->gb, FNSIZE);



        if (cmd > FN_VERBATIM) {

            av_log(avctx, AV_LOG_ERROR, "unknown shorten function %d\n", cmd);

            *got_frame_ptr = 0;

            break;

        }



        if (!is_audio_command[cmd]) {

            /* process non-audio command */

            switch (cmd) {

            case FN_VERBATIM:

                len = get_ur_golomb_shorten(&s->gb, VERBATIM_CKSIZE_SIZE);

                while (len--)

                    get_ur_golomb_shorten(&s->gb, VERBATIM_BYTE_SIZE);

                break;

            case FN_BITSHIFT:

                s->bitshift = get_ur_golomb_shorten(&s->gb, BITSHIFTSIZE);

                break;

            case FN_BLOCKSIZE: {

                unsigned blocksize = get_uint(s, av_log2(s->blocksize));

                if (blocksize > s->blocksize) {

                    av_log(avctx, AV_LOG_ERROR,

                           "Increasing block size is not supported\n");

                    return AVERROR_PATCHWELCOME;

                }

                if (!blocksize || blocksize > MAX_BLOCKSIZE) {

                    av_log(avctx, AV_LOG_ERROR, "invalid or unsupported "

                                                "block size: %d\n", blocksize);

                    return AVERROR(EINVAL);

                }

                s->blocksize = blocksize;

                break;

            }

            case FN_QUIT:

                s->got_quit_command = 1;

                break;

            }

            if (cmd == FN_BLOCKSIZE || cmd == FN_QUIT) {

                *got_frame_ptr = 0;

                break;

            }

        } else {

            /* process audio command */

            int residual_size = 0;

            int channel = s->cur_chan;

            int32_t coffset;



            /* get Rice code for residual decoding */

            if (cmd != FN_ZERO) {

                residual_size = get_ur_golomb_shorten(&s->gb, ENERGYSIZE);

                /* This is a hack as version 0 differed in the definition

                 * of get_sr_golomb_shorten(). */

                if (s->version == 0)

                    residual_size--;

            }



            /* calculate sample offset using means from previous blocks */

            if (s->nmean == 0)

                coffset = s->offset[channel][0];

            else {

                int32_t sum = (s->version < 2) ? 0 : s->nmean / 2;

                for (i = 0; i < s->nmean; i++)

                    sum += s->offset[channel][i];

                coffset = sum / s->nmean;

                if (s->version >= 2)

                    coffset = s->bitshift == 0 ? coffset : coffset >> s->bitshift - 1 >> 1;

            }



            /* decode samples for this channel */

            if (cmd == FN_ZERO) {

                for (i = 0; i < s->blocksize; i++)

                    s->decoded[channel][i] = 0;

            } else {

                if ((ret = decode_subframe_lpc(s, cmd, channel,

                                               residual_size, coffset)) < 0)

                    return ret;

            }



            /* update means with info from the current block */

            if (s->nmean > 0) {

                int32_t sum = (s->version < 2) ? 0 : s->blocksize / 2;

                for (i = 0; i < s->blocksize; i++)

                    sum += s->decoded[channel][i];



                for (i = 1; i < s->nmean; i++)

                    s->offset[channel][i - 1] = s->offset[channel][i];



                if (s->version < 2)

                    s->offset[channel][s->nmean - 1] = sum / s->blocksize;

                else

                    s->offset[channel][s->nmean - 1] = (sum / s->blocksize) << s->bitshift;

            }



            /* copy wrap samples for use with next block */

            for (i = -s->nwrap; i < 0; i++)

                s->decoded[channel][i] = s->decoded[channel][i + s->blocksize];



            /* shift samples to add in unused zero bits which were removed

             * during encoding */

            fix_bitshift(s, s->decoded[channel]);



            /* if this is the last channel in the block, output the samples */

            s->cur_chan++;

            if (s->cur_chan == s->channels) {

                uint8_t *samples_u8;

                int16_t *samples_s16;

                int chan;



                /* get output buffer */

                frame->nb_samples = s->blocksize;

                if ((ret = ff_get_buffer(avctx, frame, 0)) < 0)

                    return ret;



                for (chan = 0; chan < s->channels; chan++) {

                    samples_u8  = ((uint8_t **)frame->extended_data)[chan];

                    samples_s16 = ((int16_t **)frame->extended_data)[chan];

                    for (i = 0; i < s->blocksize; i++) {

                        switch (s->internal_ftype) {

                        case TYPE_U8:

                            *samples_u8++ = av_clip_uint8(s->decoded[chan][i]);

                            break;

                        case TYPE_S16HL:

                        case TYPE_S16LH:

                            *samples_s16++ = av_clip_int16(s->decoded[chan][i]);

                            break;

                        }

                    }

                }



                *got_frame_ptr = 1;

            }

        }

    }

    if (s->cur_chan < s->channels)

        *got_frame_ptr = 0;



finish_frame:

    s->bitindex = get_bits_count(&s->gb) - 8 * (get_bits_count(&s->gb) / 8);

    i           = get_bits_count(&s->gb) / 8;

    if (i > buf_size) {

        av_log(s->avctx, AV_LOG_ERROR, "overread: %d\n", i - buf_size);

        s->bitstream_size  = 0;

        s->bitstream_index = 0;

        return AVERROR_INVALIDDATA;

    }

    if (s->bitstream_size) {

        s->bitstream_index += i;

        s->bitstream_size  -= i;

        return input_buf_size;

    } else

        return i;

}

int64_t ff_lsb2full(StreamContext *stream, int64_t lsb){

    int64_t mask = (1<<stream->msb_pts_shift)-1;

    int64_t delta= stream->last_pts - mask/2;

    return  ((lsb - delta)&mask) + delta;

}

int ff_audio_rechunk_interleave(AVFormatContext *s, AVPacket *out, AVPacket *pkt, int flush,

                        int (*get_packet)(AVFormatContext *, AVPacket *, AVPacket *, int),

                        int (*compare_ts)(AVFormatContext *, AVPacket *, AVPacket *))

{

    int i;



    if (pkt) {

        AVStream *st = s->streams[pkt->stream_index];

        AudioInterleaveContext *aic = st->priv_data;

        if (st->codec->codec_type == AVMEDIA_TYPE_AUDIO) {

            unsigned new_size = av_fifo_size(aic->fifo) + pkt->size;

            if (new_size > aic->fifo_size) {

                if (av_fifo_realloc2(aic->fifo, new_size) < 0)

                    return -1;

                aic->fifo_size = new_size;

            }

            av_fifo_generic_write(aic->fifo, pkt->data, pkt->size, NULL);

        } else {

            // rewrite pts and dts to be decoded time line position

            pkt->pts = pkt->dts = aic->dts;

            aic->dts += pkt->duration;

            ff_interleave_add_packet(s, pkt, compare_ts);

        }

        pkt = NULL;

    }



    for (i = 0; i < s->nb_streams; i++) {

        AVStream *st = s->streams[i];

        if (st->codec->codec_type == AVMEDIA_TYPE_AUDIO) {

            AVPacket new_pkt;

            while (interleave_new_audio_packet(s, &new_pkt, i, flush))

                ff_interleave_add_packet(s, &new_pkt, compare_ts);

        }

    }



    return get_packet(s, out, NULL, flush);

}

