static void opt_output_file(const char *filename)

{

    AVFormatContext *oc;

    int err, use_video, use_audio, use_subtitle;

    int input_has_video, input_has_audio, input_has_subtitle;

    AVFormatParameters params, *ap = &params;

    AVOutputFormat *file_oformat;



    if (!strcmp(filename, "-"))

        filename = "pipe:";



    oc = avformat_alloc_context();

    if (!oc) {

        print_error(filename, AVERROR(ENOMEM));

        ffmpeg_exit(1);

    }



    if (last_asked_format) {

        file_oformat = av_guess_format(last_asked_format, NULL, NULL);

        if (!file_oformat) {

            fprintf(stderr, "Requested output format '%s' is not a suitable output format\n", last_asked_format);

            ffmpeg_exit(1);

        }

        last_asked_format = NULL;

    } else {

        file_oformat = av_guess_format(NULL, filename, NULL);

        if (!file_oformat) {

            fprintf(stderr, "Unable to find a suitable output format for '%s'\n",

                    filename);

            ffmpeg_exit(1);

        }

    }



    oc->oformat = file_oformat;

    av_strlcpy(oc->filename, filename, sizeof(oc->filename));



    if (!strcmp(file_oformat->name, "ffm") &&

        av_strstart(filename, "http:", NULL)) {

        /* special case for files sent to ffserver: we get the stream

           parameters from ffserver */

        int err = read_ffserver_streams(oc, filename);

        if (err < 0) {

            print_error(filename, err);

            ffmpeg_exit(1);

        }

    } else {

        use_video = file_oformat->video_codec != CODEC_ID_NONE || video_stream_copy || video_codec_name;

        use_audio = file_oformat->audio_codec != CODEC_ID_NONE || audio_stream_copy || audio_codec_name;

        use_subtitle = file_oformat->subtitle_codec != CODEC_ID_NONE || subtitle_stream_copy || subtitle_codec_name;



        /* disable if no corresponding type found and at least one

           input file */

        if (nb_input_files > 0) {

            check_audio_video_sub_inputs(&input_has_video, &input_has_audio,

                                         &input_has_subtitle);

            if (!input_has_video)

                use_video = 0;

            if (!input_has_audio)

                use_audio = 0;

            if (!input_has_subtitle)

                use_subtitle = 0;

        }



        /* manual disable */

        if (audio_disable)    use_audio    = 0;

        if (video_disable)    use_video    = 0;

        if (subtitle_disable) use_subtitle = 0;



        if (use_video)    new_video_stream(oc, nb_output_files);

        if (use_audio)    new_audio_stream(oc, nb_output_files);

        if (use_subtitle) new_subtitle_stream(oc, nb_output_files);



        oc->timestamp = recording_timestamp;



        av_metadata_copy(&oc->metadata, metadata, 0);

        av_metadata_free(&metadata);

    }



    output_files[nb_output_files++] = oc;



    /* check filename in case of an image number is expected */

    if (oc->oformat->flags & AVFMT_NEEDNUMBER) {

        if (!av_filename_number_test(oc->filename)) {

            print_error(oc->filename, AVERROR_NUMEXPECTED);

            ffmpeg_exit(1);

        }

    }



    if (!(oc->oformat->flags & AVFMT_NOFILE)) {

        /* test if it already exists to avoid loosing precious files */

        if (!file_overwrite &&

            (strchr(filename, ':') == NULL ||

             filename[1] == ':' ||

             av_strstart(filename, "file:", NULL))) {

            if (url_exist(filename)) {

                if (!using_stdin) {

                    fprintf(stderr,"File '%s' already exists. Overwrite ? [y/N] ", filename);

                    fflush(stderr);

                    if (!read_yesno()) {

                        fprintf(stderr, "Not overwriting - exiting\n");

                        ffmpeg_exit(1);

                    }

                }

                else {

                    fprintf(stderr,"File '%s' already exists. Exiting.\n", filename);

                    ffmpeg_exit(1);

                }

            }

        }



        /* open the file */

        if ((err = avio_open(&oc->pb, filename, AVIO_FLAG_WRITE)) < 0) {

            print_error(filename, err);

            ffmpeg_exit(1);

        }

    }



    memset(ap, 0, sizeof(*ap));

    if (av_set_parameters(oc, ap) < 0) {

        fprintf(stderr, "%s: Invalid encoding parameters\n",

                oc->filename);

        ffmpeg_exit(1);

    }



    oc->preload= (int)(mux_preload*AV_TIME_BASE);

    oc->max_delay= (int)(mux_max_delay*AV_TIME_BASE);

    oc->loop_output = loop_output;

    oc->flags |= AVFMT_FLAG_NONBLOCK;



    set_context_opts(oc, avformat_opts, AV_OPT_FLAG_ENCODING_PARAM, NULL);



    av_freep(&forced_key_frames);

}

static int smc_decode_frame(AVCodecContext *avctx,

                             void *data, int *got_frame,

                             AVPacket *avpkt)

{

    const uint8_t *buf = avpkt->data;

    int buf_size = avpkt->size;

    SmcContext *s = avctx->priv_data;

    const uint8_t *pal = av_packet_get_side_data(avpkt, AV_PKT_DATA_PALETTE, NULL);

    int ret;



    bytestream2_init(&s->gb, buf, buf_size);



    if ((ret = ff_reget_buffer(avctx, s->frame)) < 0)

        return ret;



    if (pal) {

        s->frame->palette_has_changed = 1;

        memcpy(s->pal, pal, AVPALETTE_SIZE);

    }



    smc_decode_stream(s);



    *got_frame      = 1;

    if ((ret = av_frame_ref(data, s->frame)) < 0)

        return ret;



    /* always report that the buffer was completely consumed */

    return buf_size;

}

static inline void apply_8x8(MpegEncContext *s,

                             uint8_t *dest_y,

                             uint8_t *dest_cb,

                             uint8_t *dest_cr,

                             int dir,

                             uint8_t **ref_picture,

                             qpel_mc_func (*qpix_op)[16],

                             op_pixels_func (*pix_op)[4])

{

    int dxy, mx, my, src_x, src_y;

    int i;

    int mb_x = s->mb_x;

    int mb_y = s->mb_y;

    uint8_t *ptr, *dest;



    mx = 0;

    my = 0;

    if (s->quarter_sample) {

        for (i = 0; i < 4; i++) {

            int motion_x = s->mv[dir][i][0];

            int motion_y = s->mv[dir][i][1];



            dxy   = ((motion_y & 3) << 2) | (motion_x & 3);

            src_x = mb_x * 16 + (motion_x >> 2) + (i & 1) * 8;

            src_y = mb_y * 16 + (motion_y >> 2) + (i >> 1) * 8;



            /* WARNING: do no forget half pels */

            src_x = av_clip(src_x, -16, s->width);

            if (src_x == s->width)

                dxy &= ~3;

            src_y = av_clip(src_y, -16, s->height);

            if (src_y == s->height)

                dxy &= ~12;



            ptr = ref_picture[0] + (src_y * s->linesize) + (src_x);

            if ((unsigned)src_x > FFMAX(s->h_edge_pos - (motion_x & 3) - 8, 0) ||

                (unsigned)src_y > FFMAX(s->v_edge_pos - (motion_y & 3) - 8, 0)) {

                s->vdsp.emulated_edge_mc(s->edge_emu_buffer, ptr,

                                         s->linesize, s->linesize,

                                         9, 9,

                                         src_x, src_y,

                                         s->h_edge_pos,

                                         s->v_edge_pos);

                ptr = s->edge_emu_buffer;

            }

            dest = dest_y + ((i & 1) * 8) + (i >> 1) * 8 * s->linesize;

            qpix_op[1][dxy](dest, ptr, s->linesize);



            mx += s->mv[dir][i][0] / 2;

            my += s->mv[dir][i][1] / 2;

        }

    } else {

        for (i = 0; i < 4; i++) {

            hpel_motion(s,

                        dest_y + ((i & 1) * 8) + (i >> 1) * 8 * s->linesize,

                        ref_picture[0],

                        mb_x * 16 + (i & 1) * 8,

                        mb_y * 16 + (i >> 1) * 8,

                        pix_op[1],

                        s->mv[dir][i][0],

                        s->mv[dir][i][1]);



            mx += s->mv[dir][i][0];

            my += s->mv[dir][i][1];

        }

    }



    if (!CONFIG_GRAY || !(s->flags & CODEC_FLAG_GRAY))

        chroma_4mv_motion(s, dest_cb, dest_cr,

                          ref_picture, pix_op[1], mx, my);

}

void mpeg_motion_internal(MpegEncContext *s,

                          uint8_t *dest_y,

                          uint8_t *dest_cb,

                          uint8_t *dest_cr,

                          int field_based,

                          int bottom_field,

                          int field_select,

                          uint8_t **ref_picture,

                          op_pixels_func (*pix_op)[4],

                          int motion_x,

                          int motion_y,

                          int h,

                          int is_mpeg12,

                          int mb_y)

{

    uint8_t *ptr_y, *ptr_cb, *ptr_cr;

    int dxy, uvdxy, mx, my, src_x, src_y,

        uvsrc_x, uvsrc_y, v_edge_pos;

    ptrdiff_t uvlinesize, linesize;



#if 0

    if (s->quarter_sample) {

        motion_x >>= 1;

        motion_y >>= 1;

    }

#endif



    v_edge_pos = s->v_edge_pos >> field_based;

    linesize   = s->current_picture.f->linesize[0] << field_based;

    uvlinesize = s->current_picture.f->linesize[1] << field_based;



    dxy   = ((motion_y & 1) << 1) | (motion_x & 1);

    src_x = s->mb_x * 16 + (motion_x >> 1);

    src_y = (mb_y << (4 - field_based)) + (motion_y >> 1);



    if (!is_mpeg12 && s->out_format == FMT_H263) {

        if ((s->workaround_bugs & FF_BUG_HPEL_CHROMA) && field_based) {

            mx      = (motion_x >> 1) | (motion_x & 1);

            my      = motion_y >> 1;

            uvdxy   = ((my & 1) << 1) | (mx & 1);

            uvsrc_x = s->mb_x * 8 + (mx >> 1);

            uvsrc_y = (mb_y << (3 - field_based)) + (my >> 1);

        } else {

            uvdxy   = dxy | (motion_y & 2) | ((motion_x & 2) >> 1);

            uvsrc_x = src_x >> 1;

            uvsrc_y = src_y >> 1;

        }

    // Even chroma mv's are full pel in H261

    } else if (!is_mpeg12 && s->out_format == FMT_H261) {

        mx      = motion_x / 4;

        my      = motion_y / 4;

        uvdxy   = 0;

        uvsrc_x = s->mb_x * 8 + mx;

        uvsrc_y = mb_y * 8 + my;

    } else {

        if (s->chroma_y_shift) {

            mx      = motion_x / 2;

            my      = motion_y / 2;

            uvdxy   = ((my & 1) << 1) | (mx & 1);

            uvsrc_x = s->mb_x * 8 + (mx >> 1);

            uvsrc_y = (mb_y << (3 - field_based)) + (my >> 1);

        } else {

            if (s->chroma_x_shift) {

                // Chroma422

                mx      = motion_x / 2;

                uvdxy   = ((motion_y & 1) << 1) | (mx & 1);

                uvsrc_x = s->mb_x * 8 + (mx >> 1);

                uvsrc_y = src_y;

            } else {

                // Chroma444

                uvdxy   = dxy;

                uvsrc_x = src_x;

                uvsrc_y = src_y;

            }

        }

    }



    ptr_y  = ref_picture[0] + src_y * linesize + src_x;

    ptr_cb = ref_picture[1] + uvsrc_y * uvlinesize + uvsrc_x;

    ptr_cr = ref_picture[2] + uvsrc_y * uvlinesize + uvsrc_x;



    if ((unsigned)src_x > FFMAX(s->h_edge_pos - (motion_x & 1) - 16, 0) ||

        (unsigned)src_y > FFMAX(v_edge_pos - (motion_y & 1) - h, 0)) {

        if (is_mpeg12 ||

            s->codec_id == AV_CODEC_ID_MPEG2VIDEO ||

            s->codec_id == AV_CODEC_ID_MPEG1VIDEO) {

            av_log(s->avctx, AV_LOG_DEBUG,

                   "MPEG motion vector out of boundary (%d %d)\n", src_x,

                   src_y);

            return;

        }

        s->vdsp.emulated_edge_mc(s->sc.edge_emu_buffer, ptr_y,

                                 s->linesize, s->linesize,

                                 17, 17 + field_based,

                                 src_x, src_y << field_based,

                                 s->h_edge_pos, s->v_edge_pos);

        ptr_y = s->sc.edge_emu_buffer;

        if (!CONFIG_GRAY || !(s->avctx->flags & AV_CODEC_FLAG_GRAY)) {

            uint8_t *uvbuf = s->sc.edge_emu_buffer + 18 * s->linesize;

            s->vdsp.emulated_edge_mc(uvbuf, ptr_cb,

                                     s->uvlinesize, s->uvlinesize,

                                     9, 9 + field_based,

                                     uvsrc_x, uvsrc_y << field_based,

                                     s->h_edge_pos >> 1, s->v_edge_pos >> 1);

            s->vdsp.emulated_edge_mc(uvbuf + 16, ptr_cr,

                                     s->uvlinesize, s->uvlinesize,

                                     9, 9 + field_based,

                                     uvsrc_x, uvsrc_y << field_based,

                                     s->h_edge_pos >> 1, s->v_edge_pos >> 1);

            ptr_cb = uvbuf;

            ptr_cr = uvbuf + 16;

        }

    }



    /* FIXME use this for field pix too instead of the obnoxious hack which

     * changes picture.data */

    if (bottom_field) {

        dest_y  += s->linesize;

        dest_cb += s->uvlinesize;

        dest_cr += s->uvlinesize;

    }



    if (field_select) {

        ptr_y  += s->linesize;

        ptr_cb += s->uvlinesize;

        ptr_cr += s->uvlinesize;

    }



    pix_op[0][dxy](dest_y, ptr_y, linesize, h);



    if (!CONFIG_GRAY || !(s->avctx->flags & AV_CODEC_FLAG_GRAY)) {

        pix_op[s->chroma_x_shift][uvdxy]

            (dest_cb, ptr_cb, uvlinesize, h >> s->chroma_y_shift);

        pix_op[s->chroma_x_shift][uvdxy]

            (dest_cr, ptr_cr, uvlinesize, h >> s->chroma_y_shift);

    }

    if (!is_mpeg12 && (CONFIG_H261_ENCODER || CONFIG_H261_DECODER) &&

        s->out_format == FMT_H261) {

        ff_h261_loop_filter(s);

    }

}

static void parse_palette_segment(AVCodecContext *avctx,

                                  const uint8_t *buf, int buf_size)

{

    PGSSubContext *ctx = avctx->priv_data;



    const uint8_t *buf_end = buf + buf_size;

    const uint8_t *cm      = ff_crop_tab + MAX_NEG_CROP;

    int color_id;

    int y, cb, cr, alpha;

    int r, g, b, r_add, g_add, b_add;



    /* Skip two null bytes */

    buf += 2;



    while (buf < buf_end) {

        color_id  = bytestream_get_byte(&buf);

        y         = bytestream_get_byte(&buf);

        cr        = bytestream_get_byte(&buf);

        cb        = bytestream_get_byte(&buf);

        alpha     = bytestream_get_byte(&buf);



        YUV_TO_RGB1(cb, cr);

        YUV_TO_RGB2(r, g, b, y);



        av_dlog(avctx, "Color %d := (%d,%d,%d,%d)\n", color_id, r, g, b, alpha);



        /* Store color in palette */

        ctx->clut[color_id] = RGBA(r,g,b,alpha);

    }

}

static int transcode(OutputFile *output_files, int nb_output_files,

                     InputFile  *input_files,  int nb_input_files)

{

    int ret, i;

    AVFormatContext *is, *os;

    OutputStream *ost;

    InputStream *ist;

    uint8_t *no_packet;

    int no_packet_count = 0;

    int64_t timer_start;

    int key;



    if (!(no_packet = av_mallocz(nb_input_files)))

        exit_program(1);



    ret = transcode_init(output_files, nb_output_files, input_files, nb_input_files);

    if (ret < 0)

        goto fail;



    if (!using_stdin) {

        av_log(NULL, AV_LOG_INFO, "Press [q] to stop, [?] for help\n");

    }



    timer_start = av_gettime();



    for (; received_sigterm == 0;) {

        int file_index, ist_index;

        AVPacket pkt;

        int64_t ipts_min;

        double opts_min;

        int64_t cur_time= av_gettime();



        ipts_min = INT64_MAX;

        opts_min = 1e100;

        /* if 'q' pressed, exits */

        if (!using_stdin) {

            static int64_t last_time;

            if (received_nb_signals)

                break;

            /* read_key() returns 0 on EOF */

            if(cur_time - last_time >= 100000 && !run_as_daemon){

                key =  read_key();

                last_time = cur_time;

            }else

                key = -1;

            if (key == 'q')

                break;

            if (key == '+') av_log_set_level(av_log_get_level()+10);

            if (key == '-') av_log_set_level(av_log_get_level()-10);

            if (key == 's') qp_hist     ^= 1;

            if (key == 'h'){

                if (do_hex_dump){

                    do_hex_dump = do_pkt_dump = 0;

                } else if(do_pkt_dump){

                    do_hex_dump = 1;

                } else

                    do_pkt_dump = 1;

                av_log_set_level(AV_LOG_DEBUG);

            }

#if CONFIG_AVFILTER

            if (key == 'c' || key == 'C'){

                char buf[4096], target[64], command[256], arg[256] = {0};

                double time;

                int k, n = 0;

                fprintf(stderr, "\nEnter command: <target> <time> <command>[ <argument>]\n");

                i = 0;

                while ((k = read_key()) != '\n' && k != '\r' && i < sizeof(buf)-1)

                    if (k > 0)

                        buf[i++] = k;

                buf[i] = 0;

                if (k > 0 &&

                    (n = sscanf(buf, "%63[^ ] %lf %255[^ ] %255[^\n]", target, &time, command, arg)) >= 3) {

                    av_log(NULL, AV_LOG_DEBUG, "Processing command target:%s time:%f command:%s arg:%s",

                           target, time, command, arg);

                    for (i = 0; i < nb_output_streams; i++) {

                        ost = &output_streams[i];

                        if (ost->graph) {

                            if (time < 0) {

                                ret = avfilter_graph_send_command(ost->graph, target, command, arg, buf, sizeof(buf),

                                                                  key == 'c' ? AVFILTER_CMD_FLAG_ONE : 0);

                                fprintf(stderr, "Command reply for stream %d: ret:%d res:%s\n", i, ret, buf);

                            } else {

                                ret = avfilter_graph_queue_command(ost->graph, target, command, arg, 0, time);

                            }

                        }

                    }

                } else {

                    av_log(NULL, AV_LOG_ERROR,

                           "Parse error, at least 3 arguments were expected, "

                           "only %d given in string '%s'\n", n, buf);

                }

            }

#endif

            if (key == 'd' || key == 'D'){

                int debug=0;

                if(key == 'D') {

                    debug = input_streams[0].st->codec->debug<<1;

                    if(!debug) debug = 1;

                    while(debug & (FF_DEBUG_DCT_COEFF|FF_DEBUG_VIS_QP|FF_DEBUG_VIS_MB_TYPE)) //unsupported, would just crash

                        debug += debug;

                }else

                    if(scanf("%d", &debug)!=1)

                        fprintf(stderr,"error parsing debug value\n");

                for(i=0;i<nb_input_streams;i++) {

                    input_streams[i].st->codec->debug = debug;

                }

                for(i=0;i<nb_output_streams;i++) {

                    ost = &output_streams[i];

                    ost->st->codec->debug = debug;

                }

                if(debug) av_log_set_level(AV_LOG_DEBUG);

                fprintf(stderr,"debug=%d\n", debug);

            }

            if (key == '?'){

                fprintf(stderr, "key    function\n"

                                "?      show this help\n"

                                "+      increase verbosity\n"

                                "-      decrease verbosity\n"

                                "c      Send command to filtergraph\n"

                                "D      cycle through available debug modes\n"

                                "h      dump packets/hex press to cycle through the 3 states\n"

                                "q      quit\n"

                                "s      Show QP histogram\n"

                );

            }

        }



        /* select the stream that we must read now by looking at the

           smallest output pts */

        file_index = -1;

        for (i = 0; i < nb_output_streams; i++) {

            OutputFile *of;

            int64_t ipts;

            double  opts;

            ost = &output_streams[i];

            of = &output_files[ost->file_index];

            os = output_files[ost->file_index].ctx;

            ist = &input_streams[ost->source_index];

            if (ost->is_past_recording_time || no_packet[ist->file_index] ||

                (os->pb && avio_tell(os->pb) >= of->limit_filesize))

                continue;

            opts = ost->st->pts.val * av_q2d(ost->st->time_base);

            ipts = ist->pts;

            if (!input_files[ist->file_index].eof_reached) {

                if (ipts < ipts_min) {

                    ipts_min = ipts;

                    if (input_sync)

                        file_index = ist->file_index;

                }

                if (opts < opts_min) {

                    opts_min = opts;

                    if (!input_sync) file_index = ist->file_index;

                }

            }

            if (ost->frame_number >= ost->max_frames) {

                int j;

                for (j = 0; j < of->ctx->nb_streams; j++)

                    output_streams[of->ost_index + j].is_past_recording_time = 1;

                continue;

            }

        }

        /* if none, if is finished */

        if (file_index < 0) {

            if (no_packet_count) {

                no_packet_count = 0;

                memset(no_packet, 0, nb_input_files);

                usleep(10000);

                continue;

            }

            break;

        }



        /* read a frame from it and output it in the fifo */

        is  = input_files[file_index].ctx;

        ret = av_read_frame(is, &pkt);

        if (ret == AVERROR(EAGAIN)) {

            no_packet[file_index] = 1;

            no_packet_count++;

            continue;

        }

        if (ret < 0) {

            input_files[file_index].eof_reached = 1;

            if (opt_shortest)

                break;

            else

                continue;

        }



        no_packet_count = 0;

        memset(no_packet, 0, nb_input_files);



        if (do_pkt_dump) {

            av_pkt_dump_log2(NULL, AV_LOG_DEBUG, &pkt, do_hex_dump,

                             is->streams[pkt.stream_index]);

        }

        /* the following test is needed in case new streams appear

           dynamically in stream : we ignore them */

        if (pkt.stream_index >= input_files[file_index].nb_streams)

            goto discard_packet;

        ist_index = input_files[file_index].ist_index + pkt.stream_index;

        ist = &input_streams[ist_index];

        if (ist->discard)

            goto discard_packet;



        if (pkt.dts != AV_NOPTS_VALUE)

            pkt.dts += av_rescale_q(input_files[ist->file_index].ts_offset, AV_TIME_BASE_Q, ist->st->time_base);

        if (pkt.pts != AV_NOPTS_VALUE)

            pkt.pts += av_rescale_q(input_files[ist->file_index].ts_offset, AV_TIME_BASE_Q, ist->st->time_base);



        if (pkt.pts != AV_NOPTS_VALUE)

            pkt.pts *= ist->ts_scale;

        if (pkt.dts != AV_NOPTS_VALUE)

            pkt.dts *= ist->ts_scale;



        //fprintf(stderr, "next:%"PRId64" dts:%"PRId64"/%"PRId64" off:%"PRId64" %d\n",

        //        ist->next_dts,

        //        ist->dts, av_rescale_q(pkt.dts, ist->st->time_base, AV_TIME_BASE_Q), input_files[ist->file_index].ts_offset,

        //        ist->st->codec->codec_type);

        if (pkt.dts != AV_NOPTS_VALUE && ist->next_dts != AV_NOPTS_VALUE

            && (is->iformat->flags & AVFMT_TS_DISCONT)) {

            int64_t pkt_dts = av_rescale_q(pkt.dts, ist->st->time_base, AV_TIME_BASE_Q);

            int64_t delta   = pkt_dts - ist->next_dts;

            if((delta < -1LL*dts_delta_threshold*AV_TIME_BASE ||

                (delta > 1LL*dts_delta_threshold*AV_TIME_BASE &&

                 ist->st->codec->codec_type != AVMEDIA_TYPE_SUBTITLE) ||

                pkt_dts+1<ist->pts)&& !copy_ts){

                input_files[ist->file_index].ts_offset -= delta;

                av_log(NULL, AV_LOG_DEBUG,

                       "timestamp discontinuity %"PRId64", new offset= %"PRId64"\n",

                       delta, input_files[ist->file_index].ts_offset);

                pkt.dts-= av_rescale_q(delta, AV_TIME_BASE_Q, ist->st->time_base);

                if (pkt.pts != AV_NOPTS_VALUE)

                    pkt.pts-= av_rescale_q(delta, AV_TIME_BASE_Q, ist->st->time_base);

            }

        }



        // fprintf(stderr,"read #%d.%d size=%d\n", ist->file_index, ist->st->index, pkt.size);

        if (output_packet(ist, output_streams, nb_output_streams, &pkt) < 0) {



            av_log(NULL, AV_LOG_ERROR, "Error while decoding stream #%d:%d\n",

                   ist->file_index, ist->st->index);

            if (exit_on_error)

                exit_program(1);

            av_free_packet(&pkt);

            continue;

        }



    discard_packet:

        av_free_packet(&pkt);



        /* dump report by using the output first video and audio streams */

        print_report(output_files, output_streams, nb_output_streams, 0, timer_start, cur_time);

    }



    /* at the end of stream, we must flush the decoder buffers */

    for (i = 0; i < nb_input_streams; i++) {

        ist = &input_streams[i];

        if (ist->decoding_needed) {

            output_packet(ist, output_streams, nb_output_streams, NULL);

        }

    }

    flush_encoders(output_streams, nb_output_streams);



    term_exit();



    /* write the trailer if needed and close file */

    for (i = 0; i < nb_output_files; i++) {

        os = output_files[i].ctx;

        av_write_trailer(os);

    }



    /* dump report by using the first video and audio streams */

    print_report(output_files, output_streams, nb_output_streams, 1, timer_start, av_gettime());



    /* close each encoder */

    for (i = 0; i < nb_output_streams; i++) {

        ost = &output_streams[i];

        if (ost->encoding_needed) {

            av_freep(&ost->st->codec->stats_in);

            avcodec_close(ost->st->codec);

        }

#if CONFIG_AVFILTER

        avfilter_graph_free(&ost->graph);

#endif

    }



    /* close each decoder */

    for (i = 0; i < nb_input_streams; i++) {

        ist = &input_streams[i];

        if (ist->decoding_needed) {

            avcodec_close(ist->st->codec);

        }

    }



    /* finished ! */

    ret = 0;



 fail:

    av_freep(&no_packet);



    if (output_streams) {

        for (i = 0; i < nb_output_streams; i++) {

            ost = &output_streams[i];

            if (ost) {

                if (ost->stream_copy)

                    av_freep(&ost->st->codec->extradata);

                if (ost->logfile) {

                    fclose(ost->logfile);

                    ost->logfile = NULL;

                }

                av_fifo_free(ost->fifo); /* works even if fifo is not

                                             initialized but set to zero */

                av_freep(&ost->st->codec->subtitle_header);

                av_free(ost->resample_frame.data[0]);

                av_free(ost->forced_kf_pts);

                if (ost->video_resample)

                    sws_freeContext(ost->img_resample_ctx);

                swr_free(&ost->swr);

                av_dict_free(&ost->opts);

            }

        }

    }

    return ret;

}

void *av_realloc(void *ptr, size_t size)

{

#if CONFIG_MEMALIGN_HACK

    int diff;

#endif



    /* let's disallow possible ambiguous cases */

    if (size > (MAX_MALLOC_SIZE-16))

        return NULL;



#if CONFIG_MEMALIGN_HACK

    //FIXME this isn't aligned correctly, though it probably isn't needed

    if(!ptr) return av_malloc(size);

    diff= ((char*)ptr)[-1];

    return (char*)realloc((char*)ptr - diff, size + diff) + diff;

#else

    return realloc(ptr, size + !size);

#endif

}

static av_cold int raw_close_decoder(AVCodecContext *avctx)

{

    RawVideoContext *context = avctx->priv_data;



    av_freep(&context->buffer);

    return 0;

}

static int mc_subpel(DiracContext *s, DiracBlock *block, const uint8_t *src[5],

                     int x, int y, int ref, int plane)

{

    Plane *p = &s->plane[plane];

    uint8_t **ref_hpel = s->ref_pics[ref]->hpel[plane];

    int motion_x = block->u.mv[ref][0];

    int motion_y = block->u.mv[ref][1];

    int mx, my, i, epel, nplanes = 0;



    if (plane) {

        motion_x >>= s->chroma_x_shift;

        motion_y >>= s->chroma_y_shift;

    }



    mx         = motion_x & ~(-1 << s->mv_precision);

    my         = motion_y & ~(-1 << s->mv_precision);

    motion_x >>= s->mv_precision;

    motion_y >>= s->mv_precision;

    /* normalize subpel coordinates to epel */

    /* TODO: template this function? */

    mx      <<= 3 - s->mv_precision;

    my      <<= 3 - s->mv_precision;



    x += motion_x;

    y += motion_y;

    epel = (mx|my)&1;



    /* hpel position */

    if (!((mx|my)&3)) {

        nplanes = 1;

        src[0] = ref_hpel[(my>>1)+(mx>>2)] + y*p->stride + x;

    } else {

        /* qpel or epel */

        nplanes = 4;

        for (i = 0; i < 4; i++)

            src[i] = ref_hpel[i] + y*p->stride + x;



        /* if we're interpolating in the right/bottom halves, adjust the planes as needed

           we increment x/y because the edge changes for half of the pixels */

        if (mx > 4) {

            src[0] += 1;

            src[2] += 1;

            x++;

        }

        if (my > 4) {

            src[0] += p->stride;

            src[1] += p->stride;

            y++;

        }



        /* hpel planes are:

           [0]: F  [1]: H

           [2]: V  [3]: C */

        if (!epel) {

            /* check if we really only need 2 planes since either mx or my is

               a hpel position. (epel weights of 0 handle this there) */

            if (!(mx&3)) {

                /* mx == 0: average [0] and [2]

                   mx == 4: average [1] and [3] */

                src[!mx] = src[2 + !!mx];

                nplanes = 2;

            } else if (!(my&3)) {

                src[0] = src[(my>>1)  ];

                src[1] = src[(my>>1)+1];

                nplanes = 2;

            }

        } else {

            /* adjust the ordering if needed so the weights work */

            if (mx > 4) {

                FFSWAP(const uint8_t *, src[0], src[1]);

                FFSWAP(const uint8_t *, src[2], src[3]);

            }

            if (my > 4) {

                FFSWAP(const uint8_t *, src[0], src[2]);

                FFSWAP(const uint8_t *, src[1], src[3]);

            }

            src[4] = epel_weights[my&3][mx&3];

        }

    }



    /* fixme: v/h _edge_pos */

    if (x + p->xblen > p->width +EDGE_WIDTH/2 ||

        y + p->yblen > p->height+EDGE_WIDTH/2 ||

        x < 0 || y < 0) {

        for (i = 0; i < nplanes; i++) {

            ff_emulated_edge_mc(s->edge_emu_buffer[i], src[i],

                                p->stride, p->stride,

                                p->xblen, p->yblen, x, y,

                                p->width+EDGE_WIDTH/2, p->height+EDGE_WIDTH/2);

            src[i] = s->edge_emu_buffer[i];

        }

    }

    return (nplanes>>1) + epel;

}

static int decode_block_progressive(MJpegDecodeContext *s, int16_t *block,

                                    uint8_t *last_nnz, int ac_index,

                                    int16_t *quant_matrix,

                                    int ss, int se, int Al, int *EOBRUN)

{

    int code, i, j, level, val, run;



    if (*EOBRUN) {

        (*EOBRUN)--;

        return 0;

    }



    {

        OPEN_READER(re, &s->gb);

        for (i = ss; ; i++) {

            UPDATE_CACHE(re, &s->gb);

            GET_VLC(code, re, &s->gb, s->vlcs[2][ac_index].table, 9, 2);



            run = ((unsigned) code) >> 4;

            code &= 0xF;

            if (code) {

                i += run;

                if (code > MIN_CACHE_BITS - 16)

                    UPDATE_CACHE(re, &s->gb);



                {

                    int cache = GET_CACHE(re, &s->gb);

                    int sign  = (~cache) >> 31;

                    level     = (NEG_USR32(sign ^ cache,code) ^ sign) - sign;

                }



                LAST_SKIP_BITS(re, &s->gb, code);



                if (i >= se) {

                    if (i == se) {

                        j = s->scantable.permutated[se];

                        block[j] = level * quant_matrix[j] << Al;

                        break;

                    }

                    av_log(s->avctx, AV_LOG_ERROR, "error count: %d\n", i);

                    return AVERROR_INVALIDDATA;

                }

                j = s->scantable.permutated[i];

                block[j] = level * quant_matrix[j] << Al;

            } else {

                if (run == 0xF) {// ZRL - skip 15 coefficients

                    i += 15;

                    if (i >= se) {

                        av_log(s->avctx, AV_LOG_ERROR, "ZRL overflow: %d\n", i);

                        return AVERROR_INVALIDDATA;

                    }

                } else {

                    val = (1 << run);

                    if (run) {

                        UPDATE_CACHE(re, &s->gb);

                        val += NEG_USR32(GET_CACHE(re, &s->gb), run);

                        LAST_SKIP_BITS(re, &s->gb, run);

                    }

                    *EOBRUN = val - 1;

                    break;

                }

            }

        }

        CLOSE_READER(re, &s->gb);

    }



    if (i > *last_nnz)

        *last_nnz = i;



    return 0;

}

void rgb32tobgr24(const uint8_t *src, uint8_t *dst, long src_size)

{

	long i;

	long num_pixels = src_size >> 2;

	for(i=0; i<num_pixels; i++)

	{

		#ifdef WORDS_BIGENDIAN

			/* RGB32 (= A,B,G,R) -> BGR24 (= B,G,R) */

			dst[3*i + 0] = src[4*i + 1];

			dst[3*i + 1] = src[4*i + 2];

			dst[3*i + 2] = src[4*i + 3];

		#else

			dst[3*i + 0] = src[4*i + 2];

			dst[3*i + 1] = src[4*i + 1];

			dst[3*i + 2] = src[4*i + 0];

		#endif

	}

}

static int initFilter(int16_t **outFilter, int16_t **filterPos, int *outFilterSize, int xInc,

                      int srcW, int dstW, int filterAlign, int one, int flags, int cpu_flags,

                      SwsVector *srcFilter, SwsVector *dstFilter, double param[2], int is_horizontal)

{

    int i;

    int filterSize;

    int filter2Size;

    int minFilterSize;

    int64_t *filter=NULL;

    int64_t *filter2=NULL;

    const int64_t fone= 1LL<<54;

    int ret= -1;



    emms_c(); //FIXME this should not be required but it IS (even for non-MMX versions)



    // NOTE: the +3 is for the MMX(+1)/SSE(+3) scaler which reads over the end

    FF_ALLOC_OR_GOTO(NULL, *filterPos, (dstW+3)*sizeof(int16_t), fail);



    if (FFABS(xInc - 0x10000) <10) { // unscaled

        int i;

        filterSize= 1;

        FF_ALLOCZ_OR_GOTO(NULL, filter, dstW*sizeof(*filter)*filterSize, fail);



        for (i=0; i<dstW; i++) {

            filter[i*filterSize]= fone;

            (*filterPos)[i]=i;

        }



    } else if (flags&SWS_POINT) { // lame looking point sampling mode

        int i;

        int xDstInSrc;

        filterSize= 1;

        FF_ALLOC_OR_GOTO(NULL, filter, dstW*sizeof(*filter)*filterSize, fail);



        xDstInSrc= xInc/2 - 0x8000;

        for (i=0; i<dstW; i++) {

            int xx= (xDstInSrc - ((filterSize-1)<<15) + (1<<15))>>16;



            (*filterPos)[i]= xx;

            filter[i]= fone;

            xDstInSrc+= xInc;

        }

    } else if ((xInc <= (1<<16) && (flags&SWS_AREA)) || (flags&SWS_FAST_BILINEAR)) { // bilinear upscale

        int i;

        int xDstInSrc;

        filterSize= 2;

        FF_ALLOC_OR_GOTO(NULL, filter, dstW*sizeof(*filter)*filterSize, fail);



        xDstInSrc= xInc/2 - 0x8000;

        for (i=0; i<dstW; i++) {

            int xx= (xDstInSrc - ((filterSize-1)<<15) + (1<<15))>>16;

            int j;



            (*filterPos)[i]= xx;

            //bilinear upscale / linear interpolate / area averaging

            for (j=0; j<filterSize; j++) {

                int64_t coeff= fone - FFABS((xx<<16) - xDstInSrc)*(fone>>16);

                if (coeff<0) coeff=0;

                filter[i*filterSize + j]= coeff;

                xx++;

            }

            xDstInSrc+= xInc;

        }

    } else {

        int xDstInSrc;

        int sizeFactor;



        if      (flags&SWS_BICUBIC)      sizeFactor=  4;

        else if (flags&SWS_X)            sizeFactor=  8;

        else if (flags&SWS_AREA)         sizeFactor=  1; //downscale only, for upscale it is bilinear

        else if (flags&SWS_GAUSS)        sizeFactor=  8;   // infinite ;)

        else if (flags&SWS_LANCZOS)      sizeFactor= param[0] != SWS_PARAM_DEFAULT ? ceil(2*param[0]) : 6;

        else if (flags&SWS_SINC)         sizeFactor= 20; // infinite ;)

        else if (flags&SWS_SPLINE)       sizeFactor= 20;  // infinite ;)

        else if (flags&SWS_BILINEAR)     sizeFactor=  2;

        else {

            sizeFactor= 0; //GCC warning killer

            assert(0);

        }



        if (xInc <= 1<<16)      filterSize= 1 + sizeFactor; // upscale

        else                    filterSize= 1 + (sizeFactor*srcW + dstW - 1)/ dstW;



        if (filterSize > srcW-2) filterSize=srcW-2;



        FF_ALLOC_OR_GOTO(NULL, filter, dstW*sizeof(*filter)*filterSize, fail);



        xDstInSrc= xInc - 0x10000;

        for (i=0; i<dstW; i++) {

            int xx= (xDstInSrc - ((filterSize-2)<<16)) / (1<<17);

            int j;

            (*filterPos)[i]= xx;

            for (j=0; j<filterSize; j++) {

                int64_t d= ((int64_t)FFABS((xx<<17) - xDstInSrc))<<13;

                double floatd;

                int64_t coeff;



                if (xInc > 1<<16)

                    d= d*dstW/srcW;

                floatd= d * (1.0/(1<<30));



                if (flags & SWS_BICUBIC) {

                    int64_t B= (param[0] != SWS_PARAM_DEFAULT ? param[0] :   0) * (1<<24);

                    int64_t C= (param[1] != SWS_PARAM_DEFAULT ? param[1] : 0.6) * (1<<24);



                    if (d >= 1LL<<31) {

                        coeff = 0.0;

                    } else {

                        int64_t dd  = (d  * d) >> 30;

                        int64_t ddd = (dd * d) >> 30;



                        if (d < 1LL<<30)

                            coeff = (12*(1<<24)-9*B-6*C)*ddd + (-18*(1<<24)+12*B+6*C)*dd + (6*(1<<24)-2*B)*(1<<30);

                        else

                            coeff = (-B-6*C)*ddd + (6*B+30*C)*dd + (-12*B-48*C)*d + (8*B+24*C)*(1<<30);

                    }

                    coeff *= fone>>(30+24);

                }

/*                else if (flags & SWS_X) {

                    double p= param ? param*0.01 : 0.3;

                    coeff = d ? sin(d*M_PI)/(d*M_PI) : 1.0;

                    coeff*= pow(2.0, - p*d*d);

                }*/

                else if (flags & SWS_X) {

                    double A= param[0] != SWS_PARAM_DEFAULT ? param[0] : 1.0;

                    double c;



                    if (floatd<1.0)

                        c = cos(floatd*M_PI);

                    else

                        c=-1.0;

                    if (c<0.0)      c= -pow(-c, A);

                    else            c=  pow( c, A);

                    coeff= (c*0.5 + 0.5)*fone;

                } else if (flags & SWS_AREA) {

                    int64_t d2= d - (1<<29);

                    if      (d2*xInc < -(1LL<<(29+16))) coeff= 1.0 * (1LL<<(30+16));

                    else if (d2*xInc <  (1LL<<(29+16))) coeff= -d2*xInc + (1LL<<(29+16));

                    else coeff=0.0;

                    coeff *= fone>>(30+16);

                } else if (flags & SWS_GAUSS) {

                    double p= param[0] != SWS_PARAM_DEFAULT ? param[0] : 3.0;

                    coeff = (pow(2.0, - p*floatd*floatd))*fone;

                } else if (flags & SWS_SINC) {

                    coeff = (d ? sin(floatd*M_PI)/(floatd*M_PI) : 1.0)*fone;

                } else if (flags & SWS_LANCZOS) {

                    double p= param[0] != SWS_PARAM_DEFAULT ? param[0] : 3.0;

                    coeff = (d ? sin(floatd*M_PI)*sin(floatd*M_PI/p)/(floatd*floatd*M_PI*M_PI/p) : 1.0)*fone;

                    if (floatd>p) coeff=0;

                } else if (flags & SWS_BILINEAR) {

                    coeff= (1<<30) - d;

                    if (coeff<0) coeff=0;

                    coeff *= fone >> 30;

                } else if (flags & SWS_SPLINE) {

                    double p=-2.196152422706632;

                    coeff = getSplineCoeff(1.0, 0.0, p, -p-1.0, floatd) * fone;

                } else {

                    coeff= 0.0; //GCC warning killer

                    assert(0);

                }



                filter[i*filterSize + j]= coeff;

                xx++;

            }

            xDstInSrc+= 2*xInc;

        }

    }



    /* apply src & dst Filter to filter -> filter2

       av_free(filter);

    */

    assert(filterSize>0);

    filter2Size= filterSize;

    if (srcFilter) filter2Size+= srcFilter->length - 1;

    if (dstFilter) filter2Size+= dstFilter->length - 1;

    assert(filter2Size>0);

    FF_ALLOCZ_OR_GOTO(NULL, filter2, filter2Size*dstW*sizeof(*filter2), fail);



    for (i=0; i<dstW; i++) {

        int j, k;



        if(srcFilter) {

            for (k=0; k<srcFilter->length; k++) {

                for (j=0; j<filterSize; j++)

                    filter2[i*filter2Size + k + j] += srcFilter->coeff[k]*filter[i*filterSize + j];

            }

        } else {

            for (j=0; j<filterSize; j++)

                filter2[i*filter2Size + j]= filter[i*filterSize + j];

        }

        //FIXME dstFilter



        (*filterPos)[i]+= (filterSize-1)/2 - (filter2Size-1)/2;

    }

    av_freep(&filter);



    /* try to reduce the filter-size (step1 find size and shift left) */

    // Assume it is near normalized (*0.5 or *2.0 is OK but * 0.001 is not).

    minFilterSize= 0;

    for (i=dstW-1; i>=0; i--) {

        int min= filter2Size;

        int j;

        int64_t cutOff=0.0;



        /* get rid of near zero elements on the left by shifting left */

        for (j=0; j<filter2Size; j++) {

            int k;

            cutOff += FFABS(filter2[i*filter2Size]);



            if (cutOff > SWS_MAX_REDUCE_CUTOFF*fone) break;



            /* preserve monotonicity because the core can't handle the filter otherwise */

            if (i<dstW-1 && (*filterPos)[i] >= (*filterPos)[i+1]) break;



            // move filter coefficients left

            for (k=1; k<filter2Size; k++)

                filter2[i*filter2Size + k - 1]= filter2[i*filter2Size + k];

            filter2[i*filter2Size + k - 1]= 0;

            (*filterPos)[i]++;

        }



        cutOff=0;

        /* count near zeros on the right */

        for (j=filter2Size-1; j>0; j--) {

            cutOff += FFABS(filter2[i*filter2Size + j]);



            if (cutOff > SWS_MAX_REDUCE_CUTOFF*fone) break;

            min--;

        }



        if (min>minFilterSize) minFilterSize= min;

    }



    if (HAVE_ALTIVEC && cpu_flags & AV_CPU_FLAG_ALTIVEC) {

        // we can handle the special case 4,

        // so we don't want to go to the full 8

        if (minFilterSize < 5)

            filterAlign = 4;



        // We really don't want to waste our time

        // doing useless computation, so fall back on

        // the scalar C code for very small filters.

        // Vectorizing is worth it only if you have a

        // decent-sized vector.

        if (minFilterSize < 3)

            filterAlign = 1;

    }



    if (HAVE_MMX && cpu_flags & AV_CPU_FLAG_MMX) {

        // special case for unscaled vertical filtering

        if (minFilterSize == 1 && filterAlign == 2)

            filterAlign= 1;

    }



    assert(minFilterSize > 0);

    filterSize= (minFilterSize +(filterAlign-1)) & (~(filterAlign-1));

    assert(filterSize > 0);

    filter= av_malloc(filterSize*dstW*sizeof(*filter));

    if (filterSize >= MAX_FILTER_SIZE*16/((flags&SWS_ACCURATE_RND) ? APCK_SIZE : 16) || !filter)

        goto fail;

    *outFilterSize= filterSize;



    if (flags&SWS_PRINT_INFO)

        av_log(NULL, AV_LOG_VERBOSE, "SwScaler: reducing / aligning filtersize %d -> %d\n", filter2Size, filterSize);

    /* try to reduce the filter-size (step2 reduce it) */

    for (i=0; i<dstW; i++) {

        int j;



        for (j=0; j<filterSize; j++) {

            if (j>=filter2Size) filter[i*filterSize + j]= 0;

            else               filter[i*filterSize + j]= filter2[i*filter2Size + j];

            if((flags & SWS_BITEXACT) && j>=minFilterSize)

                filter[i*filterSize + j]= 0;

        }

    }



    //FIXME try to align filterPos if possible



    //fix borders

    if (is_horizontal) {

        for (i = 0; i < dstW; i++) {

            int j;

            if ((*filterPos)[i] < 0) {

                // move filter coefficients left to compensate for filterPos

                for (j = 1; j < filterSize; j++) {

                    int left = FFMAX(j + (*filterPos)[i], 0);

                    filter[i * filterSize + left] += filter[i * filterSize + j];

                    filter[i * filterSize + j   ]  = 0;

                }

                (*filterPos)[i] = 0;

            }



            if ((*filterPos)[i] + filterSize > srcW) {

                int shift = (*filterPos)[i] + filterSize - srcW;

                // move filter coefficients right to compensate for filterPos

                for (j = filterSize - 2; j >= 0; j--) {

                    int right = FFMIN(j + shift, filterSize - 1);

                    filter[i * filterSize + right] += filter[i * filterSize + j];

                    filter[i * filterSize + j    ]  = 0;

                }

                (*filterPos)[i] = srcW - filterSize;

            }

        }

    }



    // Note the +1 is for the MMX scaler which reads over the end

    /* align at 16 for AltiVec (needed by hScale_altivec_real) */

    FF_ALLOCZ_OR_GOTO(NULL, *outFilter, *outFilterSize*(dstW+3)*sizeof(int16_t), fail);



    /* normalize & store in outFilter */

    for (i=0; i<dstW; i++) {

        int j;

        int64_t error=0;

        int64_t sum=0;



        for (j=0; j<filterSize; j++) {

            sum+= filter[i*filterSize + j];

        }

        sum= (sum + one/2)/ one;

        for (j=0; j<*outFilterSize; j++) {

            int64_t v= filter[i*filterSize + j] + error;

            int intV= ROUNDED_DIV(v, sum);

            (*outFilter)[i*(*outFilterSize) + j]= intV;

            error= v - intV*sum;

        }

    }



    (*filterPos)[dstW+0] =

    (*filterPos)[dstW+1] =

    (*filterPos)[dstW+2] = (*filterPos)[dstW-1]; // the MMX/SSE scaler will read over the end

    for (i=0; i<*outFilterSize; i++) {

        int k= (dstW - 1) * (*outFilterSize) + i;

        (*outFilter)[k + 1 * (*outFilterSize)] =

        (*outFilter)[k + 2 * (*outFilterSize)] =

        (*outFilter)[k + 3 * (*outFilterSize)] = (*outFilter)[k];

    }



    ret=0;

fail:

    av_free(filter);

    av_free(filter2);

    return ret;

}

static int select_input_picture(MpegEncContext *s)

{

    int i, ret;



    for (i = 1; i < MAX_PICTURE_COUNT; i++)

        s->reordered_input_picture[i - 1] = s->reordered_input_picture[i];

    s->reordered_input_picture[MAX_PICTURE_COUNT - 1] = NULL;



    /* set next picture type & ordering */

    if (!s->reordered_input_picture[0] && s->input_picture[0]) {

        if (/*s->picture_in_gop_number >= s->gop_size ||*/

            !s->next_picture_ptr || s->intra_only) {

            s->reordered_input_picture[0] = s->input_picture[0];

            s->reordered_input_picture[0]->f->pict_type = AV_PICTURE_TYPE_I;

            s->reordered_input_picture[0]->f->coded_picture_number =

                s->coded_picture_number++;

        } else {

            int b_frames;



            if (s->avctx->frame_skip_threshold || s->avctx->frame_skip_factor) {

                if (s->picture_in_gop_number < s->gop_size &&

                    skip_check(s, s->input_picture[0], s->next_picture_ptr)) {

                    // FIXME check that te gop check above is +-1 correct

                    av_frame_unref(s->input_picture[0]->f);



                    emms_c();

                    ff_vbv_update(s, 0);



                    goto no_output_pic;

                }

            }



            if (s->avctx->flags & AV_CODEC_FLAG_PASS2) {

                for (i = 0; i < s->max_b_frames + 1; i++) {

                    int pict_num = s->input_picture[0]->f->display_picture_number + i;



                    if (pict_num >= s->rc_context.num_entries)

                        break;

                    if (!s->input_picture[i]) {

                        s->rc_context.entry[pict_num - 1].new_pict_type = AV_PICTURE_TYPE_P;

                        break;

                    }



                    s->input_picture[i]->f->pict_type =

                        s->rc_context.entry[pict_num].new_pict_type;

                }

            }



            if (s->avctx->b_frame_strategy == 0) {

                b_frames = s->max_b_frames;

                while (b_frames && !s->input_picture[b_frames])

                    b_frames--;

            } else if (s->avctx->b_frame_strategy == 1) {

                for (i = 1; i < s->max_b_frames + 1; i++) {

                    if (s->input_picture[i] &&

                        s->input_picture[i]->b_frame_score == 0) {

                        s->input_picture[i]->b_frame_score =

                            get_intra_count(s,

                                            s->input_picture[i    ]->f->data[0],

                                            s->input_picture[i - 1]->f->data[0],

                                            s->linesize) + 1;

                    }

                }

                for (i = 0; i < s->max_b_frames + 1; i++) {

                    if (!s->input_picture[i] ||

                        s->input_picture[i]->b_frame_score - 1 >

                            s->mb_num / s->avctx->b_sensitivity)

                        break;

                }



                b_frames = FFMAX(0, i - 1);



                /* reset scores */

                for (i = 0; i < b_frames + 1; i++) {

                    s->input_picture[i]->b_frame_score = 0;

                }

            } else if (s->avctx->b_frame_strategy == 2) {

                b_frames = estimate_best_b_count(s);

            } else {

                av_log(s->avctx, AV_LOG_ERROR, "illegal b frame strategy\n");

                b_frames = 0;

            }



            emms_c();



            for (i = b_frames - 1; i >= 0; i--) {

                int type = s->input_picture[i]->f->pict_type;

                if (type && type != AV_PICTURE_TYPE_B)

                    b_frames = i;

            }

            if (s->input_picture[b_frames]->f->pict_type == AV_PICTURE_TYPE_B &&

                b_frames == s->max_b_frames) {

                av_log(s->avctx, AV_LOG_ERROR,

                       "warning, too many b frames in a row\n");

            }



            if (s->picture_in_gop_number + b_frames >= s->gop_size) {

                if ((s->mpv_flags & FF_MPV_FLAG_STRICT_GOP) &&

                    s->gop_size > s->picture_in_gop_number) {

                    b_frames = s->gop_size - s->picture_in_gop_number - 1;

                } else {

                    if (s->avctx->flags & AV_CODEC_FLAG_CLOSED_GOP)

                        b_frames = 0;

                    s->input_picture[b_frames]->f->pict_type = AV_PICTURE_TYPE_I;

                }

            }



            if ((s->avctx->flags & AV_CODEC_FLAG_CLOSED_GOP) && b_frames &&

                s->input_picture[b_frames]->f->pict_type == AV_PICTURE_TYPE_I)

                b_frames--;



            s->reordered_input_picture[0] = s->input_picture[b_frames];

            if (s->reordered_input_picture[0]->f->pict_type != AV_PICTURE_TYPE_I)

                s->reordered_input_picture[0]->f->pict_type = AV_PICTURE_TYPE_P;

            s->reordered_input_picture[0]->f->coded_picture_number =

                s->coded_picture_number++;

            for (i = 0; i < b_frames; i++) {

                s->reordered_input_picture[i + 1] = s->input_picture[i];

                s->reordered_input_picture[i + 1]->f->pict_type =

                    AV_PICTURE_TYPE_B;

                s->reordered_input_picture[i + 1]->f->coded_picture_number =

                    s->coded_picture_number++;

            }

        }

    }

no_output_pic:

    ff_mpeg_unref_picture(s->avctx, &s->new_picture);



    if (s->reordered_input_picture[0]) {

        s->reordered_input_picture[0]->reference =

           s->reordered_input_picture[0]->f->pict_type !=

               AV_PICTURE_TYPE_B ? 3 : 0;



        if ((ret = ff_mpeg_ref_picture(s->avctx, &s->new_picture, s->reordered_input_picture[0])))

            return ret;



        if (s->reordered_input_picture[0]->shared || s->avctx->rc_buffer_size) {

            // input is a shared pix, so we can't modifiy it -> alloc a new

            // one & ensure that the shared one is reuseable



            Picture *pic;

            int i = ff_find_unused_picture(s->avctx, s->picture, 0);

            if (i < 0)

                return i;

            pic = &s->picture[i];



            pic->reference = s->reordered_input_picture[0]->reference;

            if (alloc_picture(s, pic, 0) < 0) {

                return -1;

            }



            ret = av_frame_copy_props(pic->f, s->reordered_input_picture[0]->f);

            if (ret < 0)

                return ret;



            /* mark us unused / free shared pic */

            av_frame_unref(s->reordered_input_picture[0]->f);

            s->reordered_input_picture[0]->shared = 0;



            s->current_picture_ptr = pic;

        } else {

            // input is not a shared pix -> reuse buffer for current_pix

            s->current_picture_ptr = s->reordered_input_picture[0];

            for (i = 0; i < 4; i++) {

                s->new_picture.f->data[i] += INPLACE_OFFSET;

            }

        }

        ff_mpeg_unref_picture(s->avctx, &s->current_picture);

        if ((ret = ff_mpeg_ref_picture(s->avctx, &s->current_picture,

                                       s->current_picture_ptr)) < 0)

            return ret;



        s->picture_number = s->new_picture.f->display_picture_number;

    }

    return 0;

}

static int h264_slice_header_init(H264Context *h)

{

    int nb_slices = (HAVE_THREADS &&

                     h->avctx->active_thread_type & FF_THREAD_SLICE) ?

                    h->avctx->thread_count : 1;

    int i, ret;



    ff_set_sar(h->avctx, h->sps.sar);

    av_pix_fmt_get_chroma_sub_sample(h->avctx->pix_fmt,

                                     &h->chroma_x_shift, &h->chroma_y_shift);



    if (h->sps.timing_info_present_flag) {

        int64_t den = h->sps.time_scale;

        if (h->x264_build < 44U)

            den *= 2;

        av_reduce(&h->avctx->framerate.den, &h->avctx->framerate.num,

                  h->sps.num_units_in_tick, den, 1 << 30);

    }



    ff_h264_free_tables(h);



    h->first_field           = 0;

    h->prev_interlaced_frame = 1;



    init_scan_tables(h);

    ret = ff_h264_alloc_tables(h);

    if (ret < 0) {

        av_log(h->avctx, AV_LOG_ERROR, "Could not allocate memory\n");

        return ret;

    }



    if (h->sps.bit_depth_luma < 8 || h->sps.bit_depth_luma > 10) {

        av_log(h->avctx, AV_LOG_ERROR, "Unsupported bit depth %d\n",

               h->sps.bit_depth_luma);

        return AVERROR_INVALIDDATA;

    }



    h->avctx->bits_per_raw_sample = h->sps.bit_depth_luma;

    h->pixel_shift                = h->sps.bit_depth_luma > 8;

    h->chroma_format_idc          = h->sps.chroma_format_idc;

    h->bit_depth_luma             = h->sps.bit_depth_luma;



    ff_h264dsp_init(&h->h264dsp, h->sps.bit_depth_luma,

                    h->sps.chroma_format_idc);

    ff_h264chroma_init(&h->h264chroma, h->sps.bit_depth_chroma);

    ff_h264qpel_init(&h->h264qpel, h->sps.bit_depth_luma);

    ff_h264_pred_init(&h->hpc, h->avctx->codec_id, h->sps.bit_depth_luma,

                      h->sps.chroma_format_idc);

    ff_videodsp_init(&h->vdsp, h->sps.bit_depth_luma);



    if (nb_slices > H264_MAX_THREADS || (nb_slices > h->mb_height && h->mb_height)) {

        int max_slices;

        if (h->mb_height)

            max_slices = FFMIN(H264_MAX_THREADS, h->mb_height);

        else

            max_slices = H264_MAX_THREADS;

        av_log(h->avctx, AV_LOG_WARNING, "too many threads/slices %d,"

               " reducing to %d\n", nb_slices, max_slices);

        nb_slices = max_slices;

    }

    h->slice_context_count = nb_slices;



    if (!HAVE_THREADS || !(h->avctx->active_thread_type & FF_THREAD_SLICE)) {

        ret = ff_h264_slice_context_init(h, &h->slice_ctx[0]);

        if (ret < 0) {

            av_log(h->avctx, AV_LOG_ERROR, "context_init() failed.\n");

            return ret;

        }

    } else {

        for (i = 0; i < h->slice_context_count; i++) {

            H264SliceContext *sl = &h->slice_ctx[i];



            sl->h264               = h;

            sl->intra4x4_pred_mode = h->intra4x4_pred_mode + i * 8 * 2 * h->mb_stride;

            sl->mvd_table[0]       = h->mvd_table[0]       + i * 8 * 2 * h->mb_stride;

            sl->mvd_table[1]       = h->mvd_table[1]       + i * 8 * 2 * h->mb_stride;



            if ((ret = ff_h264_slice_context_init(h, sl)) < 0) {

                av_log(h->avctx, AV_LOG_ERROR, "context_init() failed.\n");

                return ret;

            }

        }

    }



    h->context_initialized = 1;



    return 0;

}

int ff_mpv_frame_start(MpegEncContext *s, AVCodecContext *avctx)

{

    int i, ret;

    Picture *pic;

    s->mb_skipped = 0;



    /* mark & release old frames */

    if (s->pict_type != AV_PICTURE_TYPE_B && s->last_picture_ptr &&

        s->last_picture_ptr != s->next_picture_ptr &&

        s->last_picture_ptr->f->buf[0]) {

        ff_mpeg_unref_picture(s->avctx, s->last_picture_ptr);

    }



    /* release forgotten pictures */

    /* if (MPEG-124 / H.263) */

    for (i = 0; i < MAX_PICTURE_COUNT; i++) {

        if (&s->picture[i] != s->last_picture_ptr &&

            &s->picture[i] != s->next_picture_ptr &&

            s->picture[i].reference && !s->picture[i].needs_realloc) {

            ff_mpeg_unref_picture(s->avctx, &s->picture[i]);

        }

    }



    ff_mpeg_unref_picture(s->avctx, &s->current_picture);



    /* release non reference frames */

    for (i = 0; i < MAX_PICTURE_COUNT; i++) {

        if (!s->picture[i].reference)

            ff_mpeg_unref_picture(s->avctx, &s->picture[i]);

    }



    if (s->current_picture_ptr && !s->current_picture_ptr->f->buf[0]) {

        // we already have a unused image

        // (maybe it was set before reading the header)

        pic = s->current_picture_ptr;

    } else {

        i   = ff_find_unused_picture(s->avctx, s->picture, 0);

        if (i < 0) {

            av_log(s->avctx, AV_LOG_ERROR, "no frame buffer available\n");

            return i;

        }

        pic = &s->picture[i];

    }



    pic->reference = 0;

    if (!s->droppable) {

        if (s->pict_type != AV_PICTURE_TYPE_B)

            pic->reference = 3;

    }



    pic->f->coded_picture_number = s->coded_picture_number++;



    if (alloc_picture(s, pic, 0) < 0)

        return -1;



    s->current_picture_ptr = pic;

    // FIXME use only the vars from current_pic

    s->current_picture_ptr->f->top_field_first = s->top_field_first;

    if (s->codec_id == AV_CODEC_ID_MPEG1VIDEO ||

        s->codec_id == AV_CODEC_ID_MPEG2VIDEO) {

        if (s->picture_structure != PICT_FRAME)

            s->current_picture_ptr->f->top_field_first =

                (s->picture_structure == PICT_TOP_FIELD) == s->first_field;

    }

    s->current_picture_ptr->f->interlaced_frame = !s->progressive_frame &&

                                                 !s->progressive_sequence;

    s->current_picture_ptr->field_picture      =  s->picture_structure != PICT_FRAME;



    s->current_picture_ptr->f->pict_type = s->pict_type;

    // if (s->avctx->flags && AV_CODEC_FLAG_QSCALE)

    //     s->current_picture_ptr->quality = s->new_picture_ptr->quality;

    s->current_picture_ptr->f->key_frame = s->pict_type == AV_PICTURE_TYPE_I;



    if ((ret = ff_mpeg_ref_picture(s->avctx, &s->current_picture,

                                   s->current_picture_ptr)) < 0)

        return ret;



    if (s->pict_type != AV_PICTURE_TYPE_B) {

        s->last_picture_ptr = s->next_picture_ptr;

        if (!s->droppable)

            s->next_picture_ptr = s->current_picture_ptr;

    }

    ff_dlog(s->avctx, "L%p N%p C%p L%p N%p C%p type:%d drop:%d\n",

            s->last_picture_ptr, s->next_picture_ptr,s->current_picture_ptr,

            s->last_picture_ptr    ? s->last_picture_ptr->f->data[0]    : NULL,

            s->next_picture_ptr    ? s->next_picture_ptr->f->data[0]    : NULL,

            s->current_picture_ptr ? s->current_picture_ptr->f->data[0] : NULL,

            s->pict_type, s->droppable);



    if ((!s->last_picture_ptr || !s->last_picture_ptr->f->buf[0]) &&

        (s->pict_type != AV_PICTURE_TYPE_I ||

         s->picture_structure != PICT_FRAME)) {

        int h_chroma_shift, v_chroma_shift;

        av_pix_fmt_get_chroma_sub_sample(s->avctx->pix_fmt,

                                         &h_chroma_shift, &v_chroma_shift);

        if (s->pict_type != AV_PICTURE_TYPE_I)

            av_log(avctx, AV_LOG_ERROR,

                   "warning: first frame is no keyframe\n");

        else if (s->picture_structure != PICT_FRAME)

            av_log(avctx, AV_LOG_INFO,

                   "allocate dummy last picture for field based first keyframe\n");



        /* Allocate a dummy frame */

        i = ff_find_unused_picture(s->avctx, s->picture, 0);

        if (i < 0) {

            av_log(s->avctx, AV_LOG_ERROR, "no frame buffer available\n");

            return i;

        }

        s->last_picture_ptr = &s->picture[i];



        s->last_picture_ptr->reference   = 3;

        s->last_picture_ptr->f->pict_type = AV_PICTURE_TYPE_I;



        if (alloc_picture(s, s->last_picture_ptr, 0) < 0) {

            s->last_picture_ptr = NULL;

            return -1;

        }



        memset(s->last_picture_ptr->f->data[0], 0,

               avctx->height * s->last_picture_ptr->f->linesize[0]);

        memset(s->last_picture_ptr->f->data[1], 0x80,

               (avctx->height >> v_chroma_shift) *

               s->last_picture_ptr->f->linesize[1]);

        memset(s->last_picture_ptr->f->data[2], 0x80,

               (avctx->height >> v_chroma_shift) *

               s->last_picture_ptr->f->linesize[2]);



        ff_thread_report_progress(&s->last_picture_ptr->tf, INT_MAX, 0);

        ff_thread_report_progress(&s->last_picture_ptr->tf, INT_MAX, 1);

    }

    if ((!s->next_picture_ptr || !s->next_picture_ptr->f->buf[0]) &&

        s->pict_type == AV_PICTURE_TYPE_B) {

        /* Allocate a dummy frame */

        i = ff_find_unused_picture(s->avctx, s->picture, 0);

        if (i < 0) {

            av_log(s->avctx, AV_LOG_ERROR, "no frame buffer available\n");

            return i;

        }

        s->next_picture_ptr = &s->picture[i];



        s->next_picture_ptr->reference   = 3;

        s->next_picture_ptr->f->pict_type = AV_PICTURE_TYPE_I;



        if (alloc_picture(s, s->next_picture_ptr, 0) < 0) {

            s->next_picture_ptr = NULL;

            return -1;

        }

        ff_thread_report_progress(&s->next_picture_ptr->tf, INT_MAX, 0);

        ff_thread_report_progress(&s->next_picture_ptr->tf, INT_MAX, 1);

    }



    if (s->last_picture_ptr) {

        ff_mpeg_unref_picture(s->avctx, &s->last_picture);

        if (s->last_picture_ptr->f->buf[0] &&

            (ret = ff_mpeg_ref_picture(s->avctx, &s->last_picture,

                                       s->last_picture_ptr)) < 0)

            return ret;

    }

    if (s->next_picture_ptr) {

        ff_mpeg_unref_picture(s->avctx, &s->next_picture);

        if (s->next_picture_ptr->f->buf[0] &&

            (ret = ff_mpeg_ref_picture(s->avctx, &s->next_picture,

                                       s->next_picture_ptr)) < 0)

            return ret;

    }



    if (s->pict_type != AV_PICTURE_TYPE_I &&

        !(s->last_picture_ptr && s->last_picture_ptr->f->buf[0])) {

        av_log(s, AV_LOG_ERROR,

               "Non-reference picture received and no reference available\n");

        return AVERROR_INVALIDDATA;

    }



    if (s->picture_structure!= PICT_FRAME) {

        int i;

        for (i = 0; i < 4; i++) {

            if (s->picture_structure == PICT_BOTTOM_FIELD) {

                s->current_picture.f->data[i] +=

                    s->current_picture.f->linesize[i];

            }

            s->current_picture.f->linesize[i] *= 2;

            s->last_picture.f->linesize[i]    *= 2;

            s->next_picture.f->linesize[i]    *= 2;

        }

    }



    /* set dequantizer, we can't do it during init as

     * it might change for MPEG-4 and we can't do it in the header

     * decode as init is not called for MPEG-4 there yet */

    if (s->mpeg_quant || s->codec_id == AV_CODEC_ID_MPEG2VIDEO) {

        s->dct_unquantize_intra = s->dct_unquantize_mpeg2_intra;

        s->dct_unquantize_inter = s->dct_unquantize_mpeg2_inter;

    } else if (s->out_format == FMT_H263 || s->out_format == FMT_H261) {

        s->dct_unquantize_intra = s->dct_unquantize_h263_intra;

        s->dct_unquantize_inter = s->dct_unquantize_h263_inter;

    } else {

        s->dct_unquantize_intra = s->dct_unquantize_mpeg1_intra;

        s->dct_unquantize_inter = s->dct_unquantize_mpeg1_inter;

    }



#if FF_API_XVMC

FF_DISABLE_DEPRECATION_WARNINGS

    if (CONFIG_MPEG_XVMC_DECODER && s->avctx->xvmc_acceleration)

        return ff_xvmc_field_start(s, avctx);

FF_ENABLE_DEPRECATION_WARNINGS

#endif /* FF_API_XVMC */



    return 0;

}

int ff_init_me(MpegEncContext *s){

    MotionEstContext * const c= &s->me;

    int cache_size= FFMIN(ME_MAP_SIZE>>ME_MAP_SHIFT, 1<<ME_MAP_SHIFT);

    int dia_size= FFMAX(FFABS(s->avctx->dia_size)&255, FFABS(s->avctx->pre_dia_size)&255);



    if(FFMIN(s->avctx->dia_size, s->avctx->pre_dia_size) < -ME_MAP_SIZE){

        av_log(s->avctx, AV_LOG_ERROR, "ME_MAP size is too small for SAB diamond\n");

        return -1;

    }

    //special case of snow is needed because snow uses its own iterative ME code

    if(s->me_method!=ME_ZERO && s->me_method!=ME_EPZS && s->me_method!=ME_X1 && s->avctx->codec_id != AV_CODEC_ID_SNOW){

        av_log(s->avctx, AV_LOG_ERROR, "me_method is only allowed to be set to zero and epzs; for hex,umh,full and others see dia_size\n");

        return -1;

    }



    c->avctx= s->avctx;



    if(cache_size < 2*dia_size && !c->stride){

        av_log(s->avctx, AV_LOG_INFO, "ME_MAP size may be a little small for the selected diamond size\n");

    }



    ff_set_cmp(&s->dsp, s->dsp.me_pre_cmp, c->avctx->me_pre_cmp);

    ff_set_cmp(&s->dsp, s->dsp.me_cmp, c->avctx->me_cmp);

    ff_set_cmp(&s->dsp, s->dsp.me_sub_cmp, c->avctx->me_sub_cmp);

    ff_set_cmp(&s->dsp, s->dsp.mb_cmp, c->avctx->mb_cmp);



    c->flags    = get_flags(c, 0, c->avctx->me_cmp    &FF_CMP_CHROMA);

    c->sub_flags= get_flags(c, 0, c->avctx->me_sub_cmp&FF_CMP_CHROMA);

    c->mb_flags = get_flags(c, 0, c->avctx->mb_cmp    &FF_CMP_CHROMA);



/*FIXME s->no_rounding b_type*/

    if(s->flags&CODEC_FLAG_QPEL){

        c->sub_motion_search= qpel_motion_search;

        c->qpel_avg= s->dsp.avg_qpel_pixels_tab;

        if(s->no_rounding) c->qpel_put= s->dsp.put_no_rnd_qpel_pixels_tab;

        else               c->qpel_put= s->dsp.put_qpel_pixels_tab;

    }else{

        if(c->avctx->me_sub_cmp&FF_CMP_CHROMA)

            c->sub_motion_search= hpel_motion_search;

        else if(   c->avctx->me_sub_cmp == FF_CMP_SAD

                && c->avctx->    me_cmp == FF_CMP_SAD

                && c->avctx->    mb_cmp == FF_CMP_SAD)

            c->sub_motion_search= sad_hpel_motion_search; // 2050 vs. 2450 cycles

        else

            c->sub_motion_search= hpel_motion_search;

    }

    c->hpel_avg= s->dsp.avg_pixels_tab;

    if(s->no_rounding) c->hpel_put= s->dsp.put_no_rnd_pixels_tab;

    else               c->hpel_put= s->dsp.put_pixels_tab;



    if(s->linesize){

        c->stride  = s->linesize;

        c->uvstride= s->uvlinesize;

    }else{

        c->stride  = 16*s->mb_width + 32;

        c->uvstride=  8*s->mb_width + 16;

    }



    /* 8x8 fullpel search would need a 4x4 chroma compare, which we do

     * not have yet, and even if we had, the motion estimation code

     * does not expect it. */

    if(s->codec_id != AV_CODEC_ID_SNOW){

        if((c->avctx->me_cmp&FF_CMP_CHROMA)/* && !s->dsp.me_cmp[2]*/){

            s->dsp.me_cmp[2]= zero_cmp;

        }

        if((c->avctx->me_sub_cmp&FF_CMP_CHROMA) && !s->dsp.me_sub_cmp[2]){

            s->dsp.me_sub_cmp[2]= zero_cmp;

        }

        c->hpel_put[2][0]= c->hpel_put[2][1]=

        c->hpel_put[2][2]= c->hpel_put[2][3]= zero_hpel;

    }



    if(s->codec_id == AV_CODEC_ID_H261){

        c->sub_motion_search= no_sub_motion_search;

    }



    return 0;

}

static inline int msmpeg4_decode_block(MpegEncContext * s, DCTELEM * block,

                              int n, int coded)

{

    int level, i, last, run, run_diff;

    int dc_pred_dir;

    RLTable *rl;

    RL_VLC_ELEM *rl_vlc;

    const UINT8 *scan_table;

    int qmul, qadd;



    if (s->mb_intra) {

        qmul=1;

        qadd=0;



	/* DC coef */

        set_stat(ST_DC);

        level = msmpeg4_decode_dc(s, n, &dc_pred_dir);

#ifdef PRINT_MB

{

    static int c;

    if(n==0) c=0;

