static int sdp_parse(AVFormatContext *s, const char *content)

{

    const char *p;

    int letter;

    /* Some SDP lines, particularly for Realmedia or ASF RTSP streams,

     * contain long SDP lines containing complete ASF Headers (several

     * kB) or arrays of MDPR (RM stream descriptor) headers plus

     * "rulebooks" describing their properties. Therefore, the SDP line

     * buffer is large.

     *

     * The Vorbis FMTP line can be up to 16KB - see sdp_parse_fmtp. */

    char buf[16384], *q;

    SDPParseState sdp_parse_state, *s1 = &sdp_parse_state;



    memset(s1, 0, sizeof(SDPParseState));

    p = content;

    for(;;) {

        skip_spaces(&p);

        letter = *p;

        if (letter == '\0')

            break;

        p++;

        if (*p != '=')

            goto next_line;

        p++;

        /* get the content */

        q = buf;

        while (*p != '\n' && *p != '\r' && *p != '\0') {

            if ((q - buf) < sizeof(buf) - 1)

                *q++ = *p;

            p++;

        }

        *q = '\0';

        sdp_parse_line(s, s1, letter, buf);

    next_line:

        while (*p != '\n' && *p != '\0')

            p++;

        if (*p == '\n')

            p++;

    }

    return 0;

}

static void flush_change(H264Context *h)

{

    h->outputed_poc = h->next_outputed_poc = INT_MIN;

    h->prev_interlaced_frame = 1;

    idr(h);

    h->prev_frame_num = -1;

    if (h->s.current_picture_ptr)

        h->s.current_picture_ptr->f.reference = 0;

    h->s.first_field = 0;

    memset(h->ref_list[0], 0, sizeof(h->ref_list[0]));

    memset(h->ref_list[1], 0, sizeof(h->ref_list[1]));

    memset(h->default_ref_list[0], 0, sizeof(h->default_ref_list[0]));

    memset(h->default_ref_list[1], 0, sizeof(h->default_ref_list[1]));

    ff_h264_reset_sei(h);

    h->recovery_frame= -1;

    h->sync= 0;

    h->list_count = 0;

    h->current_slice = 0;

}

static ResampleContext *resample_init(ResampleContext *c, int out_rate, int in_rate, int filter_size, int phase_shift, int linear,
                                    double cutoff0, enum AVSampleFormat format, enum SwrFilterType filter_type, int kaiser_beta,
                                    double precision, int cheby){
    double cutoff = cutoff0? cutoff0 : 0.97;
    double factor= FFMIN(out_rate * cutoff / in_rate, 1.0);
    int phase_count= 1<<phase_shift;
    if (!c || c->phase_shift != phase_shift || c->linear!=linear || c->factor != factor
           || c->filter_length != FFMAX((int)ceil(filter_size/factor), 1) || c->format != format
           || c->filter_type != filter_type || c->kaiser_beta != kaiser_beta) {
        c = av_mallocz(sizeof(*c));
        if (!c)
            return NULL;
        c->format= format;
        c->felem_size= av_get_bytes_per_sample(c->format);
        switch(c->format){
        case AV_SAMPLE_FMT_S16P:
            c->filter_shift = 15;
            break;
        case AV_SAMPLE_FMT_S32P:
            c->filter_shift = 30;
            break;
        case AV_SAMPLE_FMT_FLTP:
        case AV_SAMPLE_FMT_DBLP:
            c->filter_shift = 0;
            break;
        default:
            av_log(NULL, AV_LOG_ERROR, "Unsupported sample format\n");
            av_assert0(0);
        c->phase_shift   = phase_shift;
        c->phase_mask    = phase_count - 1;
        c->linear        = linear;
        c->factor        = factor;
        c->filter_length = FFMAX((int)ceil(filter_size/factor), 1);
        c->filter_alloc  = FFALIGN(c->filter_length, 8);
        c->filter_bank   = av_calloc(c->filter_alloc, (phase_count+1)*c->felem_size);
        c->filter_type   = filter_type;
        c->kaiser_beta   = kaiser_beta;
        if (!c->filter_bank)
        if (build_filter(c, (void*)c->filter_bank, factor, c->filter_length, c->filter_alloc, phase_count, 1<<c->filter_shift, filter_type, kaiser_beta))
        memcpy(c->filter_bank + (c->filter_alloc*phase_count+1)*c->felem_size, c->filter_bank, (c->filter_alloc-1)*c->felem_size);
        memcpy(c->filter_bank + (c->filter_alloc*phase_count  )*c->felem_size, c->filter_bank + (c->filter_alloc - 1)*c->felem_size, c->felem_size);
    c->compensation_distance= 0;
    if(!av_reduce(&c->src_incr, &c->dst_incr, out_rate, in_rate * (int64_t)phase_count, INT32_MAX/2))
    c->ideal_dst_incr= c->dst_incr;
    c->index= -phase_count*((c->filter_length-1)/2);
    c->frac= 0;
    return c;
error:
    av_freep(&c->filter_bank);
    av_free(c);
    return NULL;

static int decode_packet(AVCodecContext *avctx, void *data, int *got_frame_ptr,

                         AVPacket* avpkt)

{

    WmallDecodeCtx *s = avctx->priv_data;

    GetBitContext* gb  = &s->pgb;

    const uint8_t* buf = avpkt->data;

    int buf_size       = avpkt->size;

    int num_bits_prev_frame, packet_sequence_number, spliced_packet;



    s->frame.nb_samples = 0;



    if (s->packet_done || s->packet_loss) {

        s->packet_done = 0;



        /* sanity check for the buffer length */

        if (buf_size < avctx->block_align)

            return 0;



        s->next_packet_start = buf_size - avctx->block_align;

        buf_size             = avctx->block_align;

        s->buf_bit_size      = buf_size << 3;



        /* parse packet header */

        init_get_bits(gb, buf, s->buf_bit_size);

        packet_sequence_number = get_bits(gb, 4);

        skip_bits(gb, 1);   // Skip seekable_frame_in_packet, currently ununused

        spliced_packet = get_bits1(gb);

        if (spliced_packet)

            avpriv_request_sample(avctx, "Bitstream splicing");



        /* get number of bits that need to be added to the previous frame */

        num_bits_prev_frame = get_bits(gb, s->log2_frame_size);



        /* check for packet loss */

        if (!s->packet_loss &&

            ((s->packet_sequence_number + 1) & 0xF) != packet_sequence_number) {

            s->packet_loss = 1;

            av_log(avctx, AV_LOG_ERROR, "Packet loss detected! seq %x vs %x\n",

                   s->packet_sequence_number, packet_sequence_number);

        }

        s->packet_sequence_number = packet_sequence_number;



        if (num_bits_prev_frame > 0) {

            int remaining_packet_bits = s->buf_bit_size - get_bits_count(gb);

            if (num_bits_prev_frame >= remaining_packet_bits) {

                num_bits_prev_frame = remaining_packet_bits;

                s->packet_done = 1;

            }



            /* Append the previous frame data to the remaining data from the

             * previous packet to create a full frame. */

            save_bits(s, gb, num_bits_prev_frame, 1);



            /* decode the cross packet frame if it is valid */

            if (num_bits_prev_frame < remaining_packet_bits && !s->packet_loss)

                decode_frame(s);

        } else if (s->num_saved_bits - s->frame_offset) {

            av_dlog(avctx, "ignoring %x previously saved bits\n",

                    s->num_saved_bits - s->frame_offset);

        }



        if (s->packet_loss) {

            /* Reset number of saved bits so that the decoder does not start

             * to decode incomplete frames in the s->len_prefix == 0 case. */

            s->num_saved_bits = 0;

            s->packet_loss    = 0;

            init_put_bits(&s->pb, s->frame_data, MAX_FRAMESIZE);

        }



    } else {

        int frame_size;



        s->buf_bit_size = (avpkt->size - s->next_packet_start) << 3;

        init_get_bits(gb, avpkt->data, s->buf_bit_size);

        skip_bits(gb, s->packet_offset);



        if (s->len_prefix && remaining_bits(s, gb) > s->log2_frame_size &&

            (frame_size = show_bits(gb, s->log2_frame_size)) &&

            frame_size <= remaining_bits(s, gb)) {

            save_bits(s, gb, frame_size, 0);

            s->packet_done = !decode_frame(s);

        } else if (!s->len_prefix

                   && s->num_saved_bits > get_bits_count(&s->gb)) {

            /* when the frames do not have a length prefix, we don't know the

             * compressed length of the individual frames however, we know what

             * part of a new packet belongs to the previous frame therefore we

             * save the incoming packet first, then we append the "previous

             * frame" data from the next packet so that we get a buffer that

             * only contains full frames */

            s->packet_done = !decode_frame(s);

        } else {

            s->packet_done = 1;

        }

    }



    if (s->packet_done && !s->packet_loss &&

        remaining_bits(s, gb) > 0) {

        /* save the rest of the data so that it can be decoded

         * with the next packet */

        save_bits(s, gb, remaining_bits(s, gb), 0);

    }



    *(AVFrame *)data = s->frame;

    *got_frame_ptr   = s->frame.nb_samples > 0;

    s->packet_offset = get_bits_count(gb) & 7;



    return (s->packet_loss) ? AVERROR_INVALIDDATA : get_bits_count(gb) >> 3;

}

