static int scan_mmco_reset(AVCodecParserContext *s)

{

    H264ParseContext *p = s->priv_data;

    H264Context      *h = &p->h;

    H264SliceContext *sl = &h->slice_ctx[0];



    sl->slice_type_nos = s->pict_type & 3;



    if (h->pps.redundant_pic_cnt_present)

        get_ue_golomb(&sl->gb); // redundant_pic_count



    if (ff_set_ref_count(h, sl) < 0)

        return AVERROR_INVALIDDATA;



    if (sl->slice_type_nos != AV_PICTURE_TYPE_I) {

        int list;

        for (list = 0; list < sl->list_count; list++) {

            if (get_bits1(&sl->gb)) {

                int index;

                for (index = 0; ; index++) {

                    unsigned int reordering_of_pic_nums_idc = get_ue_golomb_31(&sl->gb);



                    if (reordering_of_pic_nums_idc < 3)

                        get_ue_golomb(&sl->gb);

                    else if (reordering_of_pic_nums_idc > 3) {

                        av_log(h->avctx, AV_LOG_ERROR,

                               "illegal reordering_of_pic_nums_idc %d\n",

                               reordering_of_pic_nums_idc);

                        return AVERROR_INVALIDDATA;

                    } else

                        break;



                    if (index >= sl->ref_count[list]) {

                        av_log(h->avctx, AV_LOG_ERROR,

                               "reference count %d overflow\n", index);

                        return AVERROR_INVALIDDATA;

                    }

                }

            }

        }

    }



    if ((h->pps.weighted_pred && sl->slice_type_nos == AV_PICTURE_TYPE_P) ||

        (h->pps.weighted_bipred_idc == 1 && sl->slice_type_nos == AV_PICTURE_TYPE_B))

        ff_pred_weight_table(h, sl);



    if (get_bits1(&sl->gb)) { // adaptive_ref_pic_marking_mode_flag

        int i;

        for (i = 0; i < MAX_MMCO_COUNT; i++) {

            MMCOOpcode opcode = get_ue_golomb_31(&sl->gb);

            if (opcode > (unsigned) MMCO_LONG) {

                av_log(h->avctx, AV_LOG_ERROR,

                       "illegal memory management control operation %d\n",

                       opcode);

                return AVERROR_INVALIDDATA;

            }

            if (opcode == MMCO_END)

               return 0;

            else if (opcode == MMCO_RESET)

                return 1;



            if (opcode == MMCO_SHORT2UNUSED || opcode == MMCO_SHORT2LONG)

                get_ue_golomb(&sl->gb);

            if (opcode == MMCO_SHORT2LONG || opcode == MMCO_LONG2UNUSED ||

                opcode == MMCO_LONG || opcode == MMCO_SET_MAX_LONG)

                get_ue_golomb_31(&sl->gb);

        }

    }



    return 0;

}

static int qdm2_decode_init(AVCodecContext *avctx)

{

    QDM2Context *s = avctx->priv_data;

    uint8_t *extradata;

    int extradata_size;

    int tmp_val, tmp, size;

    int i;

    float alpha;



    /* extradata parsing



    Structure:

    wave {

        frma (QDM2)

        QDCA

        QDCP

    }



    32  size (including this field)

    32  tag (=frma)

    32  type (=QDM2 or QDMC)



    32  size (including this field, in bytes)

    32  tag (=QDCA) // maybe mandatory parameters

    32  unknown (=1)

    32  channels (=2)

    32  samplerate (=44100)

    32  bitrate (=96000)

    32  block size (=4096)

    32  frame size (=256) (for one channel)

    32  packet size (=1300)



    32  size (including this field, in bytes)

    32  tag (=QDCP) // maybe some tuneable parameters

    32  float1 (=1.0)

    32  zero ?

    32  float2 (=1.0)

    32  float3 (=1.0)

    32  unknown (27)

    32  unknown (8)

    32  zero ?

    */



    if (!avctx->extradata || (avctx->extradata_size < 48)) {

        av_log(avctx, AV_LOG_ERROR, "extradata missing or truncated\n");

        return -1;

    }



    extradata = avctx->extradata;

    extradata_size = avctx->extradata_size;



    while (extradata_size > 7) {

        if (!memcmp(extradata, "frmaQDM", 7))

            break;

        extradata++;

        extradata_size--;

    }



    if (extradata_size < 12) {

        av_log(avctx, AV_LOG_ERROR, "not enough extradata (%i)\n",

               extradata_size);

        return -1;

    }



    if (memcmp(extradata, "frmaQDM", 7)) {

        av_log(avctx, AV_LOG_ERROR, "invalid headers, QDM? not found\n");

        return -1;

    }



    if (extradata[7] == 'C') {

//        s->is_qdmc = 1;

        av_log(avctx, AV_LOG_ERROR, "stream is QDMC version 1, which is not supported\n");

        return -1;

    }



    extradata += 8;

    extradata_size -= 8;



    size = BE_32(extradata);



    if(size > extradata_size){

        av_log(avctx, AV_LOG_ERROR, "extradata size too small, %i < %i\n",

               extradata_size, size);

        return -1;

    }



    extradata += 4;

    av_log(avctx, AV_LOG_DEBUG, "size: %d\n", size);

    if (BE_32(extradata) != MKBETAG('Q','D','C','A')) {

        av_log(avctx, AV_LOG_ERROR, "invalid extradata, expecting QDCA\n");

        return -1;

    }



    extradata += 8;



    avctx->channels = s->nb_channels = s->channels = BE_32(extradata);

    extradata += 4;



    avctx->sample_rate = BE_32(extradata);

    extradata += 4;



    avctx->bit_rate = BE_32(extradata);

    extradata += 4;



    s->group_size = BE_32(extradata);

    extradata += 4;



    s->fft_size = BE_32(extradata);

    extradata += 4;



    s->checksum_size = BE_32(extradata);

    extradata += 4;



    s->fft_order = av_log2(s->fft_size) + 1;

    s->fft_frame_size = 2 * s->fft_size; // complex has two floats



    // something like max decodable tones

    s->group_order = av_log2(s->group_size) + 1;

    s->frame_size = s->group_size / 16; // 16 iterations per super block



    if (s->fft_order == 8)

        s->sub_sampling = 1;

    else

        s->sub_sampling = 2;

    s->frequency_range = 255 / (1 << (2 - s->sub_sampling));



    switch ((s->sub_sampling * 2 + s->channels - 1)) {

        case 0: tmp = 40; break;

        case 1: tmp = 48; break;

        case 2: tmp = 56; break;

        case 3: tmp = 72; break;

        case 4: tmp = 80; break;

        case 5: tmp = 100;break;

        default: tmp=s->sub_sampling; break;

    }

    tmp_val = 0;

    if ((tmp * 1000) < avctx->bit_rate)  tmp_val = 1;

    if ((tmp * 1440) < avctx->bit_rate)  tmp_val = 2;

    if ((tmp * 1760) < avctx->bit_rate)  tmp_val = 3;

    if ((tmp * 2240) < avctx->bit_rate)  tmp_val = 4;

    s->cm_table_select = tmp_val;



    if (s->sub_sampling == 0)

        tmp = 16000;

    else

        tmp = ((-(s->sub_sampling -1)) & 8000) + 20000;

    /*

    0: 16000 -> 1

    1: 20000 -> 2

    2: 28000 -> 2

    */

    if (tmp < 8000)

        s->coeff_per_sb_select = 0;

    else if (tmp <= 16000)

        s->coeff_per_sb_select = 1;

    else

        s->coeff_per_sb_select = 2;



    if (s->fft_order != 8 && s->fft_order != 9)

        av_log(avctx, AV_LOG_ERROR, "Unknown FFT order (%d), contact the developers!\n", s->fft_order);



    ff_fft_init(&s->fft_ctx, s->fft_order - 1, 1);



    for (i = 1; i < (1 << (s->fft_order - 2)); i++) {

        alpha = 2 * M_PI * (float)i / (float)(1 << (s->fft_order - 1));

        s->exptab[i].re = cos(alpha);

        s->exptab[i].im = sin(alpha);

    }



    qdm2_init(s);



//    dump_context(s);

    return 0;

}

static void new_audio_stream(AVFormatContext *oc)

{

    AVStream *st;

    AVCodec *codec= NULL;

    AVCodecContext *audio_enc;

    enum CodecID codec_id;



    st = av_new_stream(oc, oc->nb_streams < nb_streamid_map ? streamid_map[oc->nb_streams] : 0);

    if (!st) {

        fprintf(stderr, "Could not alloc stream\n");

        ffmpeg_exit(1);

    }



    output_codecs = grow_array(output_codecs, sizeof(*output_codecs), &nb_output_codecs, nb_output_codecs + 1);

    if(!audio_stream_copy){

        if (audio_codec_name) {

            codec_id = find_codec_or_die(audio_codec_name, AVMEDIA_TYPE_AUDIO, 1,

                                         avcodec_opts[AVMEDIA_TYPE_AUDIO]->strict_std_compliance);

            codec = avcodec_find_encoder_by_name(audio_codec_name);

            output_codecs[nb_output_codecs-1] = codec;

        } else {

            codec_id = av_guess_codec(oc->oformat, NULL, oc->filename, NULL, AVMEDIA_TYPE_AUDIO);

            codec = avcodec_find_encoder(codec_id);

        }

    }



    avcodec_get_context_defaults3(st->codec, codec);



    bitstream_filters[nb_output_files] =

        grow_array(bitstream_filters[nb_output_files],

                   sizeof(*bitstream_filters[nb_output_files]),

                   &nb_bitstream_filters[nb_output_files], oc->nb_streams);

    bitstream_filters[nb_output_files][oc->nb_streams - 1]= audio_bitstream_filters;

    audio_bitstream_filters= NULL;



    avcodec_thread_init(st->codec, thread_count);



    audio_enc = st->codec;

    audio_enc->codec_type = AVMEDIA_TYPE_AUDIO;



    if(audio_codec_tag)

        audio_enc->codec_tag= audio_codec_tag;



    if (oc->oformat->flags & AVFMT_GLOBALHEADER) {

        audio_enc->flags |= CODEC_FLAG_GLOBAL_HEADER;

        avcodec_opts[AVMEDIA_TYPE_AUDIO]->flags|= CODEC_FLAG_GLOBAL_HEADER;

    }

    if (audio_stream_copy) {

        st->stream_copy = 1;

        audio_enc->channels = audio_channels;

        audio_enc->sample_rate = audio_sample_rate;

    } else {

        audio_enc->codec_id = codec_id;

        set_context_opts(audio_enc, avcodec_opts[AVMEDIA_TYPE_AUDIO], AV_OPT_FLAG_AUDIO_PARAM | AV_OPT_FLAG_ENCODING_PARAM, codec);



        if (audio_qscale > QSCALE_NONE) {

            audio_enc->flags |= CODEC_FLAG_QSCALE;

            audio_enc->global_quality = st->quality = FF_QP2LAMBDA * audio_qscale;

        }

        audio_enc->channels = audio_channels;

        audio_enc->sample_fmt = audio_sample_fmt;

        audio_enc->sample_rate = audio_sample_rate;

        audio_enc->channel_layout = channel_layout;

        if (avcodec_channel_layout_num_channels(channel_layout) != audio_channels)

            audio_enc->channel_layout = 0;

        choose_sample_fmt(st, codec);

        choose_sample_rate(st, codec);

    }

    audio_enc->time_base= (AVRational){1, audio_sample_rate};

    if (audio_language) {

        av_metadata_set2(&st->metadata, "language", audio_language, 0);

        av_freep(&audio_language);

    }



    /* reset some key parameters */

    audio_disable = 0;

    av_freep(&audio_codec_name);

    audio_stream_copy = 0;

}

static void frame_erasure(EVRCContext *e, float *samples)

{

    float ilspf[FILTER_ORDER], ilpc[FILTER_ORDER], idelay[NB_SUBFRAMES],

          tmp[SUBFRAME_SIZE + 6], f;

    int i, j;



    for (i = 0; i < FILTER_ORDER; i++) {

        if (e->bitrate != RATE_QUANT)

            e->lspf[i] = e->prev_lspf[i] * 0.875 + 0.125 * (i + 1) * 0.048;

        else

            e->lspf[i] = e->prev_lspf[i];

    }



    if (e->prev_error_flag)

        e->avg_acb_gain *= 0.75;

    if (e->bitrate == RATE_FULL)

        memcpy(e->pitch_back, e->pitch, ACB_SIZE * sizeof(float));

    if (e->last_valid_bitrate == RATE_QUANT)

        e->bitrate = RATE_QUANT;

    else

        e->bitrate = RATE_FULL;



    if (e->bitrate == RATE_FULL || e->bitrate == RATE_HALF) {

        e->pitch_delay = e->prev_pitch_delay;

    } else {

        float sum = 0;



        idelay[0] = idelay[1] = idelay[2] = MIN_DELAY;



        for (i = 0; i < NB_SUBFRAMES; i++)

            sum += evrc_energy_quant[e->prev_energy_gain][i];

        sum /= (float) NB_SUBFRAMES;

        sum  = pow(10, sum);

        for (i = 0; i < NB_SUBFRAMES; i++)

            e->energy_vector[i] = sum;

    }



    if (fabs(e->pitch_delay - e->prev_pitch_delay) > 15)

        e->prev_pitch_delay = e->pitch_delay;



    for (i = 0; i < NB_SUBFRAMES; i++) {

        int subframe_size = subframe_sizes[i];

        int pitch_lag;



        interpolate_lsp(ilspf, e->lspf, e->prev_lspf, i);



        if (e->bitrate != RATE_QUANT) {

            if (e->avg_acb_gain < 0.3) {

                idelay[0] = estimation_delay[i];

                idelay[1] = estimation_delay[i + 1];

                idelay[2] = estimation_delay[i + 2];

            } else {

                interpolate_delay(idelay, e->pitch_delay, e->prev_pitch_delay, i);

            }

        }



        pitch_lag = lrintf((idelay[1] + idelay[0]) / 2.0);

        decode_predictor_coeffs(ilspf, ilpc);



        if (e->bitrate != RATE_QUANT) {

            acb_excitation(e, e->pitch + ACB_SIZE,

                           e->avg_acb_gain, idelay, subframe_size);

            for (j = 0; j < subframe_size; j++)

                e->pitch[ACB_SIZE + j] *= e->fade_scale;

            e->fade_scale = FFMAX(e->fade_scale - 0.05, 0.0);

        } else {

            for (j = 0; j < subframe_size; j++)

                e->pitch[ACB_SIZE + j] = e->energy_vector[i];

        }



        memcpy(e->pitch, e->pitch + subframe_size, ACB_SIZE * sizeof(float));



        if (e->bitrate != RATE_QUANT && e->avg_acb_gain < 0.4) {

            f = 0.1 * e->avg_fcb_gain;

            for (j = 0; j < subframe_size; j++)

                e->pitch[ACB_SIZE + j] += f;

        } else if (e->bitrate == RATE_QUANT) {

            for (j = 0; j < subframe_size; j++)

                e->pitch[ACB_SIZE + j] = e->energy_vector[i];

        }



        synthesis_filter(e->pitch + ACB_SIZE, ilpc,

                         e->synthesis, subframe_size, tmp);

        postfilter(e, tmp, ilpc, samples, pitch_lag,

                   &postfilter_coeffs[e->bitrate], subframe_size);



        samples += subframe_size;

    }

}

void ff_mdct_calcw_c(FFTContext *s, FFTDouble *out, const FFTSample *input)

{

    int i, j, n, n8, n4, n2, n3;

    FFTDouble re, im;

    const uint16_t *revtab = s->revtab;

    const FFTSample *tcos = s->tcos;

    const FFTSample *tsin = s->tsin;

    FFTComplex *x = s->tmp_buf;

    FFTDComplex *o = (FFTDComplex *)out;



    n = 1 << s->mdct_bits;

    n2 = n >> 1;

    n4 = n >> 2;

    n8 = n >> 3;

    n3 = 3 * n4;



    /* pre rotation */

    for(i=0;i<n8;i++) {

        re = RSCALE(-input[2*i+n3] - input[n3-1-2*i]);

        im = RSCALE(-input[n4+2*i] + input[n4-1-2*i]);

        j = revtab[i];

        CMUL(x[j].re, x[j].im, re, im, -tcos[i], tsin[i]);



        re = RSCALE( input[2*i]    - input[n2-1-2*i]);

        im = RSCALE(-input[n2+2*i] - input[ n-1-2*i]);

        j = revtab[n8 + i];

        CMUL(x[j].re, x[j].im, re, im, -tcos[n8 + i], tsin[n8 + i]);

    }



    s->fft_calc(s, x);



    /* post rotation */

    for(i=0;i<n8;i++) {

        FFTDouble r0, i0, r1, i1;

        CMULL(i1, r0, x[n8-i-1].re, x[n8-i-1].im, -tsin[n8-i-1], -tcos[n8-i-1]);

        CMULL(i0, r1, x[n8+i  ].re, x[n8+i  ].im, -tsin[n8+i  ], -tcos[n8+i  ]);

        o[n8-i-1].re = r0;

        o[n8-i-1].im = i0;

        o[n8+i  ].re = r1;

        o[n8+i  ].im = i1;

    }

}

static int mmap_read_frame(struct video_data *s, void *frame, int64_t *ts)

{

    struct v4l2_buffer buf;

    int res;



    memset(&buf, 0, sizeof(struct v4l2_buffer));

    buf.type = V4L2_BUF_TYPE_VIDEO_CAPTURE;

    buf.memory = V4L2_MEMORY_MMAP;



    /* FIXME: Some special treatment might be needed in case of loss of signal... */

    while ((res = ioctl(s->fd, VIDIOC_DQBUF, &buf)) < 0 &&

           ((errno == EAGAIN) || (errno == EINTR)));

    if (res < 0) {

        av_log(NULL, AV_LOG_ERROR, "ioctl(VIDIOC_DQBUF): %s\n", strerror(errno));



        return -1;

    }

    assert (buf.index < s->buffers);

    assert(buf.bytesused == s->frame_size);

    /* Image is at s->buff_start[buf.index] */

    memcpy(frame, s->buf_start[buf.index], buf.bytesused);

    *ts = buf.timestamp.tv_sec * int64_t_C(1000000) + buf.timestamp.tv_usec;



    res = ioctl (s->fd, VIDIOC_QBUF, &buf);

    if (res < 0) {

        av_log(NULL, AV_LOG_ERROR, "ioctl(VIDIOC_QBUF)\n");



        return -1;

    }



    return s->buf_len[buf.index];

}

static void avc_luma_midh_qrt_4w_msa(const uint8_t *src, int32_t src_stride,

                                     uint8_t *dst, int32_t dst_stride,

                                     int32_t height, uint8_t horiz_offset)

{

    uint32_t row;

    v16i8 src0, src1, src2, src3, src4, src5, src6;

    v8i16 vt_res0, vt_res1, vt_res2, vt_res3;

    v4i32 hz_res0, hz_res1;

    v8i16 dst0, dst1;

    v8i16 shf_vec0, shf_vec1, shf_vec2, shf_vec3, shf_vec4, shf_vec5;

    v8i16 mask0 = { 0, 5, 1, 6, 2, 7, 3, 8 };

    v8i16 mask1 = { 1, 4, 2, 5, 3, 6, 4, 7 };

    v8i16 mask2 = { 2, 3, 3, 4, 4, 5, 5, 6 };

    v8i16 minus5h = __msa_ldi_h(-5);

    v8i16 plus20h = __msa_ldi_h(20);

    v8i16 zeros = { 0 };

    v16u8 out;



    LD_SB5(src, src_stride, src0, src1, src2, src3, src4);

    src += (5 * src_stride);

    XORI_B5_128_SB(src0, src1, src2, src3, src4);



    for (row = (height >> 1); row--;) {

        LD_SB2(src, src_stride, src5, src6);

        src += (2 * src_stride);



        XORI_B2_128_SB(src5, src6);

        AVC_CALC_DPADD_B_6PIX_2COEFF_SH(src0, src1, src2, src3, src4, src5,

                                        vt_res0, vt_res1);

        AVC_CALC_DPADD_B_6PIX_2COEFF_SH(src1, src2, src3, src4, src5, src6,

                                        vt_res2, vt_res3);

        VSHF_H3_SH(vt_res0, vt_res1, vt_res0, vt_res1, vt_res0, vt_res1,

                   mask0, mask1, mask2, shf_vec0, shf_vec1, shf_vec2);

        VSHF_H3_SH(vt_res2, vt_res3, vt_res2, vt_res3, vt_res2, vt_res3,

                   mask0, mask1, mask2, shf_vec3, shf_vec4, shf_vec5);

        hz_res0 = __msa_hadd_s_w(shf_vec0, shf_vec0);

        DPADD_SH2_SW(shf_vec1, shf_vec2, minus5h, plus20h, hz_res0, hz_res0);

        hz_res1 = __msa_hadd_s_w(shf_vec3, shf_vec3);

        DPADD_SH2_SW(shf_vec4, shf_vec5, minus5h, plus20h, hz_res1, hz_res1);



        SRARI_W2_SW(hz_res0, hz_res1, 10);

        SAT_SW2_SW(hz_res0, hz_res1, 7);



        dst0 = __msa_srari_h(shf_vec2, 5);

        dst1 = __msa_srari_h(shf_vec5, 5);



        SAT_SH2_SH(dst0, dst1, 7);



        if (horiz_offset) {

            dst0 = __msa_ilvod_h(zeros, dst0);

            dst1 = __msa_ilvod_h(zeros, dst1);

        } else {

            ILVEV_H2_SH(dst0, zeros, dst1, zeros, dst0, dst1);

        }



        hz_res0 = __msa_aver_s_w(hz_res0, (v4i32) dst0);

        hz_res1 = __msa_aver_s_w(hz_res1, (v4i32) dst1);

        dst0 = __msa_pckev_h((v8i16) hz_res1, (v8i16) hz_res0);



        out = PCKEV_XORI128_UB(dst0, dst0);

        ST4x2_UB(out, dst, dst_stride);



        dst += (2 * dst_stride);



        src0 = src2;

        src1 = src3;

        src2 = src4;

        src3 = src5;

        src4 = src6;

    }

}

static void print_codec(const AVCodec *c)

{

    int encoder = av_codec_is_encoder(c);



    printf("%s %s [%s]:\n", encoder ? "Encoder" : "Decoder", c->name,

           c->long_name ? c->long_name : "");



    printf("    General capabilities: ");

    if (c->capabilities & AV_CODEC_CAP_DRAW_HORIZ_BAND)

        printf("horizband ");

    if (c->capabilities & AV_CODEC_CAP_DR1)

        printf("dr1 ");

    if (c->capabilities & AV_CODEC_CAP_TRUNCATED)

        printf("trunc ");

    if (c->capabilities & AV_CODEC_CAP_DELAY)

        printf("delay ");

    if (c->capabilities & AV_CODEC_CAP_SMALL_LAST_FRAME)

        printf("small ");

    if (c->capabilities & AV_CODEC_CAP_SUBFRAMES)

        printf("subframes ");

    if (c->capabilities & AV_CODEC_CAP_EXPERIMENTAL)

        printf("exp ");

    if (c->capabilities & AV_CODEC_CAP_CHANNEL_CONF)

        printf("chconf ");

    if (c->capabilities & AV_CODEC_CAP_PARAM_CHANGE)

        printf("small ");

    if (c->capabilities & AV_CODEC_CAP_PARAM_CHANGE)

        printf("variable ");

    if (c->capabilities & (AV_CODEC_CAP_FRAME_THREADS |

                           AV_CODEC_CAP_SLICE_THREADS |

                           AV_CODEC_CAP_AUTO_THREADS))

        printf("threads ");

    if (!c->capabilities)

        printf("none");

    printf("\n");



    if (c->type == AVMEDIA_TYPE_VIDEO) {

        printf("    Threading capabilities: ");

        switch (c->capabilities & (AV_CODEC_CAP_FRAME_THREADS |

                                   AV_CODEC_CAP_SLICE_THREADS |

                                   AV_CODEC_CAP_AUTO_THREADS)) {

        case AV_CODEC_CAP_FRAME_THREADS |

             AV_CODEC_CAP_SLICE_THREADS: printf("frame and slice"); break;

        case AV_CODEC_CAP_FRAME_THREADS: printf("frame");           break;

        case AV_CODEC_CAP_SLICE_THREADS: printf("slice");           break;

        case AV_CODEC_CAP_AUTO_THREADS : printf("auto");            break;

        default:                         printf("none");            break;

        }

        printf("\n");

    }



    if (c->supported_framerates) {

        const AVRational *fps = c->supported_framerates;



        printf("    Supported framerates:");

        while (fps->num) {

            printf(" %d/%d", fps->num, fps->den);

            fps++;

        }

        printf("\n");

    }

    PRINT_CODEC_SUPPORTED(c, pix_fmts, enum AVPixelFormat, "pixel formats",

                          AV_PIX_FMT_NONE, GET_PIX_FMT_NAME);

    PRINT_CODEC_SUPPORTED(c, supported_samplerates, int, "sample rates", 0,

                          GET_SAMPLE_RATE_NAME);

    PRINT_CODEC_SUPPORTED(c, sample_fmts, enum AVSampleFormat, "sample formats",

                          AV_SAMPLE_FMT_NONE, GET_SAMPLE_FMT_NAME);

    PRINT_CODEC_SUPPORTED(c, channel_layouts, uint64_t, "channel layouts",

                          0, GET_CH_LAYOUT_DESC);



    if (c->priv_class) {

        show_help_children(c->priv_class,

                           AV_OPT_FLAG_ENCODING_PARAM |

                           AV_OPT_FLAG_DECODING_PARAM);

    }

}

static int init_processing_chain(AVFilterContext *ctx, int in_width, int in_height,

                                 int out_width, int out_height)

{

    NPPScaleContext *s = ctx->priv;



    AVHWFramesContext *in_frames_ctx;



    enum AVPixelFormat in_format;

    enum AVPixelFormat out_format;

    enum AVPixelFormat in_deinterleaved_format;

    enum AVPixelFormat out_deinterleaved_format;



    int i, ret, last_stage = -1;



    /* check that we have a hw context */

    if (!ctx->inputs[0]->hw_frames_ctx) {

        av_log(ctx, AV_LOG_ERROR, "No hw context provided on input\n");

        return AVERROR(EINVAL);

    }

    in_frames_ctx = (AVHWFramesContext*)ctx->inputs[0]->hw_frames_ctx->data;

    in_format     = in_frames_ctx->sw_format;

    out_format    = (s->format == AV_PIX_FMT_NONE) ? in_format : s->format;



    if (!format_is_supported(in_format)) {

        av_log(ctx, AV_LOG_ERROR, "Unsupported input format: %s\n",

               av_get_pix_fmt_name(in_format));

        return AVERROR(ENOSYS);

    }

    if (!format_is_supported(out_format)) {

        av_log(ctx, AV_LOG_ERROR, "Unsupported output format: %s\n",

               av_get_pix_fmt_name(out_format));

        return AVERROR(ENOSYS);

    }



    in_deinterleaved_format  = get_deinterleaved_format(in_format);

    out_deinterleaved_format = get_deinterleaved_format(out_format);

    if (in_deinterleaved_format  == AV_PIX_FMT_NONE ||

        out_deinterleaved_format == AV_PIX_FMT_NONE)

        return AVERROR_BUG;



    /* figure out which stages need to be done */

    if (in_width != out_width || in_height != out_height ||

        in_deinterleaved_format != out_deinterleaved_format) {

        s->stages[STAGE_RESIZE].stage_needed = 1;



        if (s->interp_algo == NPPI_INTER_SUPER &&

            (out_width > in_width && out_height > in_height)) {

            s->interp_algo = NPPI_INTER_LANCZOS;

            av_log(ctx, AV_LOG_WARNING, "super-sampling not supported for output dimensions, using lanczos instead.\n");

        }

        if (s->interp_algo == NPPI_INTER_SUPER &&

            !(out_width < in_width && out_height < in_height)) {

            s->interp_algo = NPPI_INTER_CUBIC;

            av_log(ctx, AV_LOG_WARNING, "super-sampling not supported for output dimensions, using cubic instead.\n");

        }

    }



    if (!s->stages[STAGE_RESIZE].stage_needed && in_format == out_format)

        s->passthrough = 1;



    if (!s->passthrough) {

        if (in_format != in_deinterleaved_format)

            s->stages[STAGE_DEINTERLEAVE].stage_needed = 1;

        if (out_format != out_deinterleaved_format)

            s->stages[STAGE_INTERLEAVE].stage_needed = 1;

    }



    s->stages[STAGE_DEINTERLEAVE].in_fmt              = in_format;

    s->stages[STAGE_DEINTERLEAVE].out_fmt             = in_deinterleaved_format;

    s->stages[STAGE_DEINTERLEAVE].planes_in[0].width  = in_width;

    s->stages[STAGE_DEINTERLEAVE].planes_in[0].height = in_height;



    s->stages[STAGE_RESIZE].in_fmt               = in_deinterleaved_format;

    s->stages[STAGE_RESIZE].out_fmt              = out_deinterleaved_format;

    s->stages[STAGE_RESIZE].planes_in[0].width   = in_width;

    s->stages[STAGE_RESIZE].planes_in[0].height  = in_height;

    s->stages[STAGE_RESIZE].planes_out[0].width  = out_width;

    s->stages[STAGE_RESIZE].planes_out[0].height = out_height;



    s->stages[STAGE_INTERLEAVE].in_fmt              = out_deinterleaved_format;

    s->stages[STAGE_INTERLEAVE].out_fmt             = out_format;

    s->stages[STAGE_INTERLEAVE].planes_in[0].width  = out_width;

    s->stages[STAGE_INTERLEAVE].planes_in[0].height = out_height;



    /* init the hardware contexts */

    for (i = 0; i < FF_ARRAY_ELEMS(s->stages); i++) {

        if (!s->stages[i].stage_needed)

            continue;



        ret = init_stage(&s->stages[i], in_frames_ctx->device_ref);

        if (ret < 0)

            return ret;



        last_stage = i;

    }



    if (last_stage < 0)

    {

        ctx->outputs[0]->hw_frames_ctx = av_buffer_ref(ctx->inputs[0]->hw_frames_ctx);

        return 0;

    }



    ctx->outputs[0]->hw_frames_ctx = av_buffer_ref(s->stages[last_stage].frames_ctx);

    if (!ctx->outputs[0]->hw_frames_ctx)

        return AVERROR(ENOMEM);



    return 0;

}

static int read_uncompressed_sgi(unsigned char* out_buf, uint8_t* out_end,

                const uint8_t *in_buf, const uint8_t *in_end, SgiState* s)

{

    int x, y, z;

    const uint8_t *ptr;

    unsigned int offset = s->height * s->width * s->bytes_per_channel;



    /* Test buffer size. */

    if (offset * s->depth > in_end - in_buf) {

       return -1;

    }



    for (y = s->height - 1; y >= 0; y--) {

        out_end = out_buf + (y * s->linesize);

        for (x = s->width; x > 0; x--) {

            ptr = in_buf += s->bytes_per_channel;

            for(z = 0; z < s->depth; z ++) {

                memcpy(out_end, ptr, s->bytes_per_channel);

                out_end += s->bytes_per_channel;

                ptr += offset;

            }

        }

    }

    return 0;

}

int ff_mov_write_packet(AVFormatContext *s, AVPacket *pkt)

{

    MOVMuxContext *mov = s->priv_data;

    AVIOContext *pb = s->pb;

    MOVTrack *trk = &mov->tracks[pkt->stream_index];

    AVCodecContext *enc = trk->enc;

    unsigned int samples_in_chunk = 0;

    int size = pkt->size;

    uint8_t *reformatted_data = NULL;



    if (mov->flags & FF_MOV_FLAG_FRAGMENT) {

        int ret;

        if (mov->fragments > 0) {

            if (!trk->mdat_buf) {

                if ((ret = avio_open_dyn_buf(&trk->mdat_buf)) < 0)

                    return ret;

            }

            pb = trk->mdat_buf;

        } else {

            if (!mov->mdat_buf) {

                if ((ret = avio_open_dyn_buf(&mov->mdat_buf)) < 0)

                    return ret;

            }

            pb = mov->mdat_buf;

        }

    }



    if (enc->codec_id == AV_CODEC_ID_AMR_NB) {

        /* We must find out how many AMR blocks there are in one packet */

        static uint16_t packed_size[16] =

            {13, 14, 16, 18, 20, 21, 27, 32, 6, 0, 0, 0, 0, 0, 0, 1};

        int len = 0;



        while (len < size && samples_in_chunk < 100) {

            len += packed_size[(pkt->data[len] >> 3) & 0x0F];

            samples_in_chunk++;

        }

        if (samples_in_chunk > 1) {

            av_log(s, AV_LOG_ERROR, "fatal error, input is not a single packet, implement a AVParser for it\n");

            return -1;

        }

    } else if (trk->sample_size)

        samples_in_chunk = size / trk->sample_size;

    else

        samples_in_chunk = 1;



    /* copy extradata if it exists */

    if (trk->vos_len == 0 && enc->extradata_size > 0) {

        trk->vos_len  = enc->extradata_size;

        trk->vos_data = av_malloc(trk->vos_len);

        memcpy(trk->vos_data, enc->extradata, trk->vos_len);

    }



    if (enc->codec_id == AV_CODEC_ID_H264 && trk->vos_len > 0 && *(uint8_t *)trk->vos_data != 1) {

        /* from x264 or from bytestream h264 */

        /* nal reformating needed */

        if (trk->hint_track >= 0 && trk->hint_track < mov->nb_streams) {

            ff_avc_parse_nal_units_buf(pkt->data, &reformatted_data,

                                       &size);

            avio_write(pb, reformatted_data, size);

        } else {

            size = ff_avc_parse_nal_units(pb, pkt->data, pkt->size);

        }

    } else if (enc->codec_id == AV_CODEC_ID_HEVC && trk->vos_len > 6 &&

               (AV_RB24(trk->vos_data) == 1 || AV_RB32(trk->vos_data) == 1)) {

        /* extradata is Annex B, assume the bitstream is too and convert it */

        if (trk->hint_track >= 0 && trk->hint_track < mov->nb_streams) {

            ff_hevc_annexb2mp4_buf(pkt->data, &reformatted_data, &size, 0, NULL);

            avio_write(pb, reformatted_data, size);

        } else {

            size = ff_hevc_annexb2mp4(pb, pkt->data, pkt->size, 0, NULL);

        }

    } else {

        avio_write(pb, pkt->data, size);

    }



    if ((enc->codec_id == AV_CODEC_ID_DNXHD ||

         enc->codec_id == AV_CODEC_ID_AC3) && !trk->vos_len) {

        /* copy frame to create needed atoms */

        trk->vos_len  = size;

        trk->vos_data = av_malloc(size);

        if (!trk->vos_data)

            return AVERROR(ENOMEM);

        memcpy(trk->vos_data, pkt->data, size);

    }



    if (trk->entry >= trk->cluster_capacity) {

        unsigned new_capacity = 2 * (trk->entry + MOV_INDEX_CLUSTER_SIZE);

        if (av_reallocp_array(&trk->cluster, new_capacity,

                              sizeof(*trk->cluster)))

            return AVERROR(ENOMEM);

        trk->cluster_capacity = new_capacity;

    }



    trk->cluster[trk->entry].pos              = avio_tell(pb) - size;

    trk->cluster[trk->entry].samples_in_chunk = samples_in_chunk;

    trk->cluster[trk->entry].size             = size;

    trk->cluster[trk->entry].entries          = samples_in_chunk;

    trk->cluster[trk->entry].dts              = pkt->dts;

    if (!trk->entry && trk->start_dts != AV_NOPTS_VALUE) {

        /* First packet of a new fragment. We already wrote the duration

         * of the last packet of the previous fragment based on track_duration,

         * which might not exactly match our dts. Therefore adjust the dts

         * of this packet to be what the previous packets duration implies. */

        trk->cluster[trk->entry].dts = trk->start_dts + trk->track_duration;

    }

    if (!trk->entry && trk->start_dts == AV_NOPTS_VALUE && !mov->use_editlist &&

        s->avoid_negative_ts == AVFMT_AVOID_NEG_TS_MAKE_ZERO) {

        /* Not using edit lists and shifting the first track to start from zero.

         * If the other streams start from a later timestamp, we won't be able

         * to signal the difference in starting time without an edit list.

         * Thus move the timestamp for this first sample to 0, increasing

         * its duration instead. */

        trk->cluster[trk->entry].dts = trk->start_dts = 0;

    }

    if (trk->start_dts == AV_NOPTS_VALUE) {

        trk->start_dts = pkt->dts;

        if (pkt->dts && mov->flags & FF_MOV_FLAG_EMPTY_MOOV)

            av_log(s, AV_LOG_WARNING,

                   "Track %d starts with a nonzero dts %"PRId64". This "

                   "currently isn't handled correctly in combination with "

                   "empty_moov.\n", pkt->stream_index, pkt->dts);

    }

    trk->track_duration = pkt->dts - trk->start_dts + pkt->duration;



    if (pkt->pts == AV_NOPTS_VALUE) {

        av_log(s, AV_LOG_WARNING, "pts has no value\n");

        pkt->pts = pkt->dts;

    }

    if (pkt->dts != pkt->pts)

        trk->flags |= MOV_TRACK_CTTS;

    trk->cluster[trk->entry].cts   = pkt->pts - pkt->dts;

    trk->cluster[trk->entry].flags = 0;

    if (enc->codec_id == AV_CODEC_ID_VC1) {

        mov_parse_vc1_frame(pkt, trk, mov->fragments);

    } else if (pkt->flags & AV_PKT_FLAG_KEY) {

        if (mov->mode == MODE_MOV && enc->codec_id == AV_CODEC_ID_MPEG2VIDEO &&

            trk->entry > 0) { // force sync sample for the first key frame

            mov_parse_mpeg2_frame(pkt, &trk->cluster[trk->entry].flags);

            if (trk->cluster[trk->entry].flags & MOV_PARTIAL_SYNC_SAMPLE)

                trk->flags |= MOV_TRACK_STPS;

        } else {

            trk->cluster[trk->entry].flags = MOV_SYNC_SAMPLE;

        }

        if (trk->cluster[trk->entry].flags & MOV_SYNC_SAMPLE)

            trk->has_keyframes++;

    }

    trk->entry++;

    trk->sample_count += samples_in_chunk;

    mov->mdat_size    += size;



    if (trk->hint_track >= 0 && trk->hint_track < mov->nb_streams)

        ff_mov_add_hinted_packet(s, pkt, trk->hint_track, trk->entry,

                                 reformatted_data, size);

    av_free(reformatted_data);

    return 0;

}

static void do_video_out(AVFormatContext *s,

                         OutputStream *ost,

                         AVFrame *in_picture,

                         int *frame_size)

{

    int ret, format_video_sync;

    AVPacket pkt;

    AVCodecContext *enc = ost->enc_ctx;



    *frame_size = 0;



    format_video_sync = video_sync_method;

    if (format_video_sync == VSYNC_AUTO)

        format_video_sync = (s->oformat->flags & AVFMT_NOTIMESTAMPS) ? VSYNC_PASSTHROUGH :

                            (s->oformat->flags & AVFMT_VARIABLE_FPS) ? VSYNC_VFR : VSYNC_CFR;

    if (format_video_sync != VSYNC_PASSTHROUGH &&

        ost->frame_number &&

        in_picture->pts != AV_NOPTS_VALUE &&

        in_picture->pts < ost->sync_opts) {

        nb_frames_drop++;

        av_log(NULL, AV_LOG_WARNING,

               "*** dropping frame %d from stream %d at ts %"PRId64"\n",

               ost->frame_number, ost->st->index, in_picture->pts);

        return;

    }



    if (in_picture->pts == AV_NOPTS_VALUE)

        in_picture->pts = ost->sync_opts;

    ost->sync_opts = in_picture->pts;





    if (!ost->frame_number)

        ost->first_pts = in_picture->pts;



    av_init_packet(&pkt);

    pkt.data = NULL;

    pkt.size = 0;



    if (ost->frame_number >= ost->max_frames)

        return;



    if (enc->flags & (AV_CODEC_FLAG_INTERLACED_DCT | AV_CODEC_FLAG_INTERLACED_ME) &&

        ost->top_field_first >= 0)

        in_picture->top_field_first = !!ost->top_field_first;



    in_picture->quality = enc->global_quality;

    in_picture->pict_type = 0;

    if (ost->forced_kf_index < ost->forced_kf_count &&

        in_picture->pts >= ost->forced_kf_pts[ost->forced_kf_index]) {

        in_picture->pict_type = AV_PICTURE_TYPE_I;

        ost->forced_kf_index++;

    }



    ost->frames_encoded++;



    ret = avcodec_send_frame(enc, in_picture);

    if (ret < 0)

        goto error;



    /*

     * For video, there may be reordering, so we can't throw away frames on

     * encoder flush, we need to limit them here, before they go into encoder.

     */

    ost->frame_number++;



    while (1) {

        ret = avcodec_receive_packet(enc, &pkt);

        if (ret == AVERROR(EAGAIN))

            break;

        if (ret < 0)

            goto error;



        av_packet_rescale_ts(&pkt, enc->time_base, ost->st->time_base);

        output_packet(s, &pkt, ost);

        *frame_size = pkt.size;



        /* if two pass, output log */

        if (ost->logfile && enc->stats_out) {

            fprintf(ost->logfile, "%s", enc->stats_out);

        }



        ost->sync_opts++;

    }



    return;

error:

    av_assert0(ret != AVERROR(EAGAIN) && ret != AVERROR_EOF);

    av_log(NULL, AV_LOG_FATAL, "Video encoding failed\n");

    exit_program(1);

}

static int decode_frame_mp3on4(AVCodecContext * avctx,

                        void *data, int *data_size,

                        AVPacket *avpkt)

{

    const uint8_t *buf = avpkt->data;

    int buf_size = avpkt->size;

    MP3On4DecodeContext *s = avctx->priv_data;

    MPADecodeContext *m;

    int fsize, len = buf_size, out_size = 0;

    uint32_t header;

    OUT_INT *out_samples = data;

    OUT_INT *outptr, *bp;

    int fr, j, n;



    if(*data_size < MPA_FRAME_SIZE * MPA_MAX_CHANNELS * s->frames * sizeof(OUT_INT))

        return -1;



    *data_size = 0;

    // Discard too short frames

    if (buf_size < HEADER_SIZE)

        return -1;



    // If only one decoder interleave is not needed

    outptr = s->frames == 1 ? out_samples : s->decoded_buf;



    avctx->bit_rate = 0;



    for (fr = 0; fr < s->frames; fr++) {

        fsize = AV_RB16(buf) >> 4;

        fsize = FFMIN3(fsize, len, MPA_MAX_CODED_FRAME_SIZE);

        m = s->mp3decctx[fr];

        assert (m != NULL);



        header = (AV_RB32(buf) & 0x000fffff) | s->syncword; // patch header



        if (ff_mpa_check_header(header) < 0) // Bad header, discard block

            break;



        avpriv_mpegaudio_decode_header((MPADecodeHeader *)m, header);

        out_size += mp_decode_frame(m, outptr, buf, fsize);

        buf += fsize;

        len -= fsize;



        if(s->frames > 1) {

            n = m->avctx->frame_size*m->nb_channels;

            /* interleave output data */

            bp = out_samples + s->coff[fr];

            if(m->nb_channels == 1) {

                for(j = 0; j < n; j++) {

                    *bp = s->decoded_buf[j];

                    bp += avctx->channels;

                }

            } else {

                for(j = 0; j < n; j++) {

                    bp[0] = s->decoded_buf[j++];

                    bp[1] = s->decoded_buf[j];

                    bp += avctx->channels;

                }

            }

        }

        avctx->bit_rate += m->bit_rate;

    }



    /* update codec info */

    avctx->sample_rate = s->mp3decctx[0]->sample_rate;



    *data_size = out_size;

    return buf_size;

}

int ff_mpv_common_frame_size_change(MpegEncContext *s)

{

    int i, err = 0;



    if (!s->context_initialized)

        return AVERROR(EINVAL);



    if (s->slice_context_count > 1) {

        for (i = 0; i < s->slice_context_count; i++) {

            free_duplicate_context(s->thread_context[i]);

        }

        for (i = 1; i < s->slice_context_count; i++) {

            av_freep(&s->thread_context[i]);

        }

    } else

        free_duplicate_context(s);



    free_context_frame(s);



    if (s->picture)

        for (i = 0; i < MAX_PICTURE_COUNT; i++) {

                s->picture[i].needs_realloc = 1;

        }



    s->last_picture_ptr         =

    s->next_picture_ptr         =

    s->current_picture_ptr      = NULL;



    // init

    if (s->codec_id == AV_CODEC_ID_MPEG2VIDEO && !s->progressive_sequence)

        s->mb_height = (s->height + 31) / 32 * 2;

    else

        s->mb_height = (s->height + 15) / 16;



    if ((s->width || s->height) &&

        (err = av_image_check_size(s->width, s->height, 0, s->avctx)) < 0)

        goto fail;



    if ((err = init_context_frame(s)))

        goto fail;



    memset(s->thread_context, 0, sizeof(s->thread_context));

    s->thread_context[0]   = s;



    if (s->width && s->height) {

        int nb_slices = s->slice_context_count;

        if (nb_slices > 1) {

            for (i = 0; i < nb_slices; i++) {

                if (i) {

                    s->thread_context[i] = av_malloc(sizeof(MpegEncContext));

                    memcpy(s->thread_context[i], s, sizeof(MpegEncContext));

                }

                if ((err = init_duplicate_context(s->thread_context[i])) < 0)

                    goto fail;

                    s->thread_context[i]->start_mb_y =

                        (s->mb_height * (i) + nb_slices / 2) / nb_slices;

                    s->thread_context[i]->end_mb_y   =

                        (s->mb_height * (i + 1) + nb_slices / 2) / nb_slices;

            }

        } else {

            err = init_duplicate_context(s);

            if (err < 0)

                goto fail;

            s->start_mb_y = 0;

            s->end_mb_y   = s->mb_height;

        }

        s->slice_context_count = nb_slices;

    }



    return 0;

 fail:

    ff_mpv_common_end(s);

    return err;

}

static int dvbsub_parse_display_definition_segment(AVCodecContext *avctx,

                                                   const uint8_t *buf,

                                                   int buf_size)

{

    DVBSubContext *ctx = avctx->priv_data;

    DVBSubDisplayDefinition *display_def = ctx->display_definition;

    int dds_version, info_byte;



    if (buf_size < 5)

        return AVERROR_INVALIDDATA;



    info_byte   = bytestream_get_byte(&buf);

    dds_version = info_byte >> 4;

    if (display_def && display_def->version == dds_version)

        return 0; // already have this display definition version



    if (!display_def) {

        display_def             = av_mallocz(sizeof(*display_def));

        if (!display_def)

            return AVERROR(ENOMEM);

        ctx->display_definition = display_def;

    }



    display_def->version = dds_version;

    display_def->x       = 0;

    display_def->y       = 0;

    display_def->width   = bytestream_get_be16(&buf) + 1;

    display_def->height  = bytestream_get_be16(&buf) + 1;

    if (!avctx->width || !avctx->height) {

        avctx->width  = display_def->width;

        avctx->height = display_def->height;

    }



    if (buf_size < 13)

        return AVERROR_INVALIDDATA;



    if (info_byte & 1<<3) { // display_window_flag

        display_def->x = bytestream_get_be16(&buf);

        display_def->width  = bytestream_get_be16(&buf) - display_def->x + 1;

        display_def->y = bytestream_get_be16(&buf);

        display_def->height = bytestream_get_be16(&buf) - display_def->y + 1;

    }



    return 0;

}

static void init_scan_tables(H264Context *h)

{

    int i;

    for (i = 0; i < 16; i++) {

#define TRANSPOSE(x) (x >> 2) | ((x << 2) & 0xF)

        h->zigzag_scan[i] = TRANSPOSE(ff_zigzag_scan[i]);

        h->field_scan[i]  = TRANSPOSE(field_scan[i]);

#undef TRANSPOSE

    }

    for (i = 0; i < 64; i++) {

#define TRANSPOSE(x) (x >> 3) | ((x & 7) << 3)

        h->zigzag_scan8x8[i]       = TRANSPOSE(ff_zigzag_direct[i]);

        h->zigzag_scan8x8_cavlc[i] = TRANSPOSE(zigzag_scan8x8_cavlc[i]);

        h->field_scan8x8[i]        = TRANSPOSE(field_scan8x8[i]);

        h->field_scan8x8_cavlc[i]  = TRANSPOSE(field_scan8x8_cavlc[i]);

#undef TRANSPOSE

    }

    if (h->sps.transform_bypass) { // FIXME same ugly

        h->zigzag_scan_q0          = ff_zigzag_scan;

        h->zigzag_scan8x8_q0       = ff_zigzag_direct;

        h->zigzag_scan8x8_cavlc_q0 = zigzag_scan8x8_cavlc;

        h->field_scan_q0           = field_scan;

        h->field_scan8x8_q0        = field_scan8x8;

        h->field_scan8x8_cavlc_q0  = field_scan8x8_cavlc;

    } else {

        h->zigzag_scan_q0          = h->zigzag_scan;

        h->zigzag_scan8x8_q0       = h->zigzag_scan8x8;

        h->zigzag_scan8x8_cavlc_q0 = h->zigzag_scan8x8_cavlc;

        h->field_scan_q0           = h->field_scan;

        h->field_scan8x8_q0        = h->field_scan8x8;

        h->field_scan8x8_cavlc_q0  = h->field_scan8x8_cavlc;

    }

}

void avg_pixels8_altivec(uint8_t * block, const uint8_t * pixels, int line_size, int h)

{

POWERPC_TBL_DECLARE(altivec_avg_pixels8_num, 1);

#ifdef ALTIVEC_USE_REFERENCE_C_CODE

    int i;

POWERPC_TBL_START_COUNT(altivec_avg_pixels8_num, 1);

    for (i = 0; i < h; i++) {

        *((uint32_t *) (block)) =

            (((*((uint32_t *) (block))) |

              ((((const struct unaligned_32 *) (pixels))->l))) -

             ((((*((uint32_t *) (block))) ^

                ((((const struct unaligned_32 *) (pixels))->

                  l))) & 0xFEFEFEFEUL) >> 1));

        *((uint32_t *) (block + 4)) =

            (((*((uint32_t *) (block + 4))) |

              ((((const struct unaligned_32 *) (pixels + 4))->l))) -

             ((((*((uint32_t *) (block + 4))) ^

                ((((const struct unaligned_32 *) (pixels +

                                                  4))->

                  l))) & 0xFEFEFEFEUL) >> 1));

        pixels += line_size;

        block += line_size;

    }

POWERPC_TBL_STOP_COUNT(altivec_avg_pixels8_num, 1);



#else /* ALTIVEC_USE_REFERENCE_C_CODE */

    register vector unsigned char pixelsv1, pixelsv2, pixelsv, blockv;

    int i;



POWERPC_TBL_START_COUNT(altivec_avg_pixels8_num, 1);



   for (i = 0; i < h; i++) {

     /*

       block is 8 bytes-aligned, so we're either in the

       left block (16 bytes-aligned) or in the right block (not)

     */

     int rightside = ((unsigned long)block & 0x0000000F);



     blockv = vec_ld(0, block);

     pixelsv1 = vec_ld(0, (unsigned char*)pixels);

     pixelsv2 = vec_ld(16, (unsigned char*)pixels);

     pixelsv = vec_perm(pixelsv1, pixelsv2, vec_lvsl(0, pixels));



     if (rightside)

     {

       pixelsv = vec_perm(blockv, pixelsv, vcprm(0,1,s0,s1));

     }

     else

     {

       pixelsv = vec_perm(blockv, pixelsv, vcprm(s0,s1,2,3));

     }



     blockv = vec_avg(blockv, pixelsv);



     vec_st(blockv, 0, block);



     pixels += line_size;

     block += line_size;

   }



POWERPC_TBL_STOP_COUNT(altivec_avg_pixels8_num, 1);



#endif /* ALTIVEC_USE_REFERENCE_C_CODE */

}

int avformat_open_input(AVFormatContext **ps, const char *filename,

                        AVInputFormat *fmt, AVDictionary **options)

{

    AVFormatContext *s = *ps;

    int ret = 0;

    AVDictionary *tmp = NULL;

    ID3v2ExtraMeta *id3v2_extra_meta = NULL;



    if (!s && !(s = avformat_alloc_context()))

        return AVERROR(ENOMEM);

    if (!s->av_class) {

        av_log(NULL, AV_LOG_ERROR, "Input context has not been properly allocated by avformat_alloc_context() and is not NULL either\n");

        return AVERROR(EINVAL);

    }

    if (fmt)

        s->iformat = fmt;



    if (options)

        av_dict_copy(&tmp, *options, 0);



    if ((ret = av_opt_set_dict(s, &tmp)) < 0)

        goto fail;



    if ((ret = init_input(s, filename, &tmp)) < 0)

        goto fail;

    s->probe_score = ret;

    avio_skip(s->pb, s->skip_initial_bytes);



    /* Check filename in case an image number is expected. */

    if (s->iformat->flags & AVFMT_NEEDNUMBER) {

        if (!av_filename_number_test(filename)) {

            ret = AVERROR(EINVAL);

            goto fail;

        }

    }



    s->duration = s->start_time = AV_NOPTS_VALUE;

    av_strlcpy(s->filename, filename ? filename : "", sizeof(s->filename));



    /* Allocate private data. */

    if (s->iformat->priv_data_size > 0) {

        if (!(s->priv_data = av_mallocz(s->iformat->priv_data_size))) {

            ret = AVERROR(ENOMEM);

            goto fail;

        }

        if (s->iformat->priv_class) {

            *(const AVClass **) s->priv_data = s->iformat->priv_class;

            av_opt_set_defaults(s->priv_data);

            if ((ret = av_opt_set_dict(s->priv_data, &tmp)) < 0)

                goto fail;

        }

    }



    /* e.g. AVFMT_NOFILE formats will not have a AVIOContext */

    if (s->pb)

        ff_id3v2_read(s, ID3v2_DEFAULT_MAGIC, &id3v2_extra_meta);



    if (!(s->flags&AVFMT_FLAG_PRIV_OPT) && s->iformat->read_header)

        if ((ret = s->iformat->read_header(s)) < 0)

            goto fail;



    if (id3v2_extra_meta) {

        if (!strcmp(s->iformat->name, "mp3") || !strcmp(s->iformat->name, "aac") ||

            !strcmp(s->iformat->name, "tta")) {

            if ((ret = ff_id3v2_parse_apic(s, &id3v2_extra_meta)) < 0)

                goto fail;

        } else

            av_log(s, AV_LOG_DEBUG, "demuxer does not support additional id3 data, skipping\n");

    }

    ff_id3v2_free_extra_meta(&id3v2_extra_meta);



    if ((ret = avformat_queue_attached_pictures(s)) < 0)

        goto fail;



    if (!(s->flags&AVFMT_FLAG_PRIV_OPT) && s->pb && !s->data_offset)

        s->data_offset = avio_tell(s->pb);



    s->raw_packet_buffer_remaining_size = RAW_PACKET_BUFFER_SIZE;



    if (options) {

        av_dict_free(options);

        *options = tmp;

    }

    *ps = s;

    return 0;



fail:

    ff_id3v2_free_extra_meta(&id3v2_extra_meta);

    av_dict_free(&tmp);

    if (s->pb && !(s->flags & AVFMT_FLAG_CUSTOM_IO))

        avio_close(s->pb);

    avformat_free_context(s);

    *ps = NULL;

    return ret;

}

static av_always_inline void hl_decode_mb_predict_luma(const H264Context *h,

                                                       H264SliceContext *sl,

                                                       int mb_type, int simple,

                                                       int transform_bypass,

                                                       int pixel_shift,

                                                       const int *block_offset,

                                                       int linesize,

                                                       uint8_t *dest_y, int p)

{

    void (*idct_add)(uint8_t *dst, int16_t *block, int stride);

    void (*idct_dc_add)(uint8_t *dst, int16_t *block, int stride);

    int i;

    int qscale = p == 0 ? sl->qscale : sl->chroma_qp[p - 1];

    block_offset += 16 * p;

    if (IS_INTRA4x4(mb_type)) {

        if (IS_8x8DCT(mb_type)) {

            if (transform_bypass) {

                idct_dc_add =

                idct_add    = h->h264dsp.h264_add_pixels8_clear;

            } else {

                idct_dc_add = h->h264dsp.h264_idct8_dc_add;

                idct_add    = h->h264dsp.h264_idct8_add;

            }

            for (i = 0; i < 16; i += 4) {

                uint8_t *const ptr = dest_y + block_offset[i];

                const int dir      = sl->intra4x4_pred_mode_cache[scan8[i]];

                if (transform_bypass && h->sps.profile_idc == 244 && dir <= 1) {

                    h->hpc.pred8x8l_add[dir](ptr, sl->mb + (i * 16 + p * 256 << pixel_shift), linesize);

                } else {

                    const int nnz = sl->non_zero_count_cache[scan8[i + p * 16]];

                    h->hpc.pred8x8l[dir](ptr, (sl->topleft_samples_available << i) & 0x8000,

                                         (sl->topright_samples_available << i) & 0x4000, linesize);

                    if (nnz) {

                        if (nnz == 1 && dctcoef_get(sl->mb, pixel_shift, i * 16 + p * 256))

                            idct_dc_add(ptr, sl->mb + (i * 16 + p * 256 << pixel_shift), linesize);

                        else

                            idct_add(ptr, sl->mb + (i * 16 + p * 256 << pixel_shift), linesize);

                    }

                }

            }

        } else {

            if (transform_bypass) {

                idct_dc_add  =

                idct_add     = h->h264dsp.h264_add_pixels4_clear;

            } else {

                idct_dc_add = h->h264dsp.h264_idct_dc_add;

                idct_add    = h->h264dsp.h264_idct_add;

            }

            for (i = 0; i < 16; i++) {

                uint8_t *const ptr = dest_y + block_offset[i];

                const int dir      = sl->intra4x4_pred_mode_cache[scan8[i]];



                if (transform_bypass && h->sps.profile_idc == 244 && dir <= 1) {

                    h->hpc.pred4x4_add[dir](ptr, sl->mb + (i * 16 + p * 256 << pixel_shift), linesize);

                } else {

                    uint8_t *topright;

                    int nnz, tr;

                    uint64_t tr_high;

                    if (dir == DIAG_DOWN_LEFT_PRED || dir == VERT_LEFT_PRED) {

                        const int topright_avail = (sl->topright_samples_available << i) & 0x8000;

                        assert(sl->mb_y || linesize <= block_offset[i]);

                        if (!topright_avail) {

                            if (pixel_shift) {

                                tr_high  = ((uint16_t *)ptr)[3 - linesize / 2] * 0x0001000100010001ULL;

                                topright = (uint8_t *)&tr_high;

                            } else {

                                tr       = ptr[3 - linesize] * 0x01010101u;

                                topright = (uint8_t *)&tr;

                            }

                        } else

                            topright = ptr + (4 << pixel_shift) - linesize;

                    } else

                        topright = NULL;



                    h->hpc.pred4x4[dir](ptr, topright, linesize);

                    nnz = sl->non_zero_count_cache[scan8[i + p * 16]];

                    if (nnz) {

                        if (nnz == 1 && dctcoef_get(sl->mb, pixel_shift, i * 16 + p * 256))

                            idct_dc_add(ptr, sl->mb + (i * 16 + p * 256 << pixel_shift), linesize);

                        else

                            idct_add(ptr, sl->mb + (i * 16 + p * 256 << pixel_shift), linesize);

                    }

                }

            }

        }

    } else {

        h->hpc.pred16x16[sl->intra16x16_pred_mode](dest_y, linesize);

        if (sl->non_zero_count_cache[scan8[LUMA_DC_BLOCK_INDEX + p]]) {

            if (!transform_bypass)

                h->h264dsp.h264_luma_dc_dequant_idct(sl->mb + (p * 256 << pixel_shift),

                                                     sl->mb_luma_dc[p],

                                                     h->dequant4_coeff[p][qscale][0]);

            else {

                static const uint8_t dc_mapping[16] = {

                     0 * 16,  1 * 16,  4 * 16,  5 * 16,

                     2 * 16,  3 * 16,  6 * 16,  7 * 16,

                     8 * 16,  9 * 16, 12 * 16, 13 * 16,

                    10 * 16, 11 * 16, 14 * 16, 15 * 16

                };

                for (i = 0; i < 16; i++)

                    dctcoef_set(sl->mb + (p * 256 << pixel_shift),

                                pixel_shift, dc_mapping[i],

                                dctcoef_get(sl->mb_luma_dc[p],

                                            pixel_shift, i));

            }

        }

    }

}

static void peak_write_chunk(AVFormatContext *s)

{

    WAVMuxContext *wav = s->priv_data;

    AVIOContext *pb = s->pb;

    AVCodecContext *enc = s->streams[0]->codec;

    int64_t peak = ff_start_tag(s->pb, "levl");

    int64_t now0;

    time_t now_secs;

    char timestamp[28];



    /* Peak frame of incomplete block at end */

    if (wav->peak_block_pos)

        peak_write_frame(s);



    memset(timestamp, 0, sizeof(timestamp));

    if (!(s->flags & AVFMT_FLAG_BITEXACT)) {

        struct tm tmpbuf;

        av_log(s, AV_LOG_INFO, "Writing local time and date to Peak Envelope Chunk\n");

        now0 = av_gettime();

        now_secs = now0 / 1000000;

        strftime(timestamp, sizeof(timestamp), "%Y:%m:%d:%H:%M:%S:", localtime_r(&now_secs, &tmpbuf));

        av_strlcatf(timestamp, sizeof(timestamp), "%03d", (int)((now0 / 1000) % 1000));

    }



    avio_wl32(pb, 1);                           /* version */

    avio_wl32(pb, wav->peak_format);            /* 8 or 16 bit */

    avio_wl32(pb, wav->peak_ppv);               /* positive and negative */

    avio_wl32(pb, wav->peak_block_size);        /* frames per value */

    avio_wl32(pb, enc->channels);               /* number of channels */

    avio_wl32(pb, wav->peak_num_frames);        /* number of peak frames */

    avio_wl32(pb, wav->peak_pos_pop);           /* audio sample frame index */

    avio_wl32(pb, 128);                         /* equal to size of header */

    avio_write(pb, timestamp, 28);              /* ASCII time stamp */

    ffio_fill(pb, 0, 60);



    avio_write(pb, wav->peak_output, wav->peak_outbuf_bytes);



    ff_end_tag(pb, peak);



    if (!wav->data)

        wav->data = peak;

}

int ff_socket_nonblock(int socket, int enable)

{

#ifdef __MINGW32__

   return ioctlsocket(socket, FIONBIO, &enable);

#else

   if (enable)

      return fcntl(socket, F_SETFL, fcntl(socket, F_GETFL) | O_NONBLOCK);

   else

      return fcntl(socket, F_SETFL, fcntl(socket, F_GETFL) & ~O_NONBLOCK);

#endif

}

static void filter(FSPPContext *p, uint8_t *dst, uint8_t *src,

                   int dst_stride, int src_stride,

                   int width, int height,

                   uint8_t *qp_store, int qp_stride, int is_luma)

{

    int x, x0, y, es, qy, t;



    const int stride = is_luma ? p->temp_stride : (width + 16);

    const int step = 6 - p->log2_count;

    const int qpsh = 4 - p->hsub * !is_luma;

    const int qpsv = 4 - p->vsub * !is_luma;



    DECLARE_ALIGNED(32, int32_t, block_align)[4 * 8 * BLOCKSZ + 4 * 8 * BLOCKSZ];

    int16_t *block  = (int16_t *)block_align;

    int16_t *block3 = (int16_t *)(block_align + 4 * 8 * BLOCKSZ);



    memset(block3, 0, 4 * 8 * BLOCKSZ);



    if (!src || !dst) return;



    for (y = 0; y < height; y++) {

        int index = 8 + 8 * stride + y * stride;

        memcpy(p->src + index, src + y * src_stride, width);

        for (x = 0; x < 8; x++) {

            p->src[index         - x - 1] = p->src[index +         x    ];

            p->src[index + width + x    ] = p->src[index + width - x - 1];

        }

    }



    for (y = 0; y < 8; y++) {

        memcpy(p->src + (     7 - y    ) * stride, p->src + (     y + 8    ) * stride, stride);

        memcpy(p->src + (height + 8 + y) * stride, p->src + (height - y + 7) * stride, stride);

    }

    //FIXME (try edge emu)



    for (y = 8; y < 24; y++)

        memset(p->temp + 8 + y * stride, 0, width * sizeof(int16_t));



    for (y = step; y < height + 8; y += step) {    //step= 1,2

        const int y1 = y - 8 + step;                 //l5-7  l4-6;

        qy = y - 4;



        if (qy > height - 1) qy = height - 1;

        if (qy < 0) qy = 0;



        qy = (qy >> qpsv) * qp_stride;

        p->row_fdct(block, p->src + y * stride + 2 - (y&1), stride, 2);



        for (x0 = 0; x0 < width + 8 - 8 * (BLOCKSZ - 1); x0 += 8 * (BLOCKSZ - 1)) {

            p->row_fdct(block + 8 * 8, p->src + y * stride + 8 + x0 + 2 - (y&1), stride, 2 * (BLOCKSZ - 1));



            if (p->qp)

                p->column_fidct((int16_t *)(&p->threshold_mtx[0]), block + 0 * 8, block3 + 0 * 8, 8 * (BLOCKSZ - 1)); //yes, this is a HOTSPOT

            else

                for (x = 0; x < 8 * (BLOCKSZ - 1); x += 8) {

                    t = x + x0 - 2;                    //correct t=x+x0-2-(y&1), but its the same



                    if (t < 0) t = 0;                   //t always < width-2



                    t = qp_store[qy + (t >> qpsh)];

                    t = ff_norm_qscale(t, p->qscale_type);



                    if (t != p->prev_q) p->prev_q = t, p->mul_thrmat((int16_t *)(&p->threshold_mtx_noq[0]), (int16_t *)(&p->threshold_mtx[0]), t);

                    p->column_fidct((int16_t *)(&p->threshold_mtx[0]), block + x * 8, block3 + x * 8, 8); //yes, this is a HOTSPOT

                }

            p->row_idct(block3 + 0 * 8, p->temp + (y & 15) * stride + x0 + 2 - (y & 1), stride, 2 * (BLOCKSZ - 1));

            memmove(block,  block  + (BLOCKSZ - 1) * 64, 8 * 8 * sizeof(int16_t)); //cycling

            memmove(block3, block3 + (BLOCKSZ - 1) * 64, 6 * 8 * sizeof(int16_t));

        }



        es = width + 8 - x0; //  8, ...

        if (es > 8)

            p->row_fdct(block + 8 * 8, p->src + y * stride + 8 + x0 + 2 - (y & 1), stride, (es - 4) >> 2);



        p->column_fidct((int16_t *)(&p->threshold_mtx[0]), block, block3, es&(~1));

        p->row_idct(block3 + 0 * 8, p->temp + (y & 15) * stride + x0 + 2 - (y & 1), stride, es >> 2);



        if (!(y1 & 7) && y1) {

            if (y1 & 8)

                p->store_slice(dst + (y1 - 8) * dst_stride, p->temp + 8 + 8 * stride,

                               dst_stride, stride, width, 8, 5 - p->log2_count);

            else

                p->store_slice2(dst + (y1 - 8) * dst_stride, p->temp + 8 + 0 * stride,

                                dst_stride, stride, width, 8, 5 - p->log2_count);

        }

    }



    if (y & 7) {  // height % 8 != 0

        if (y & 8)

            p->store_slice(dst + ((y - 8) & ~7) * dst_stride, p->temp + 8 + 8 * stride,

                           dst_stride, stride, width, y&7, 5 - p->log2_count);

        else

            p->store_slice2(dst + ((y - 8) & ~7) * dst_stride, p->temp + 8 + 0 * stride,

                            dst_stride, stride, width, y&7, 5 - p->log2_count);

    }

}

static int replaygain_export(AVStream *st,

                             const uint8_t *track_gain, const uint8_t *track_peak,

                             const uint8_t *album_gain, const uint8_t *album_peak)

{

    AVPacketSideData *sd, *tmp;

    AVReplayGain *replaygain;

    int32_t tg, ag;

    uint32_t tp, ap;



    tg = parse_value(track_gain, INT32_MIN);

    ag = parse_value(album_gain, INT32_MIN);

    tp = parse_value(track_peak, 0);

    ap = parse_value(album_peak, 0);



    if (tg == INT32_MIN && ag == INT32_MIN)

        return 0;



    replaygain = av_mallocz(sizeof(*replaygain));

    if (!replaygain)

        return AVERROR(ENOMEM);



    tmp = av_realloc_array(st->side_data, st->nb_side_data + 1, sizeof(*tmp));

    if (!tmp) {

        av_freep(&replaygain);

        return AVERROR(ENOMEM);

    }

    st->side_data = tmp;

    st->nb_side_data++;



    sd = &st->side_data[st->nb_side_data - 1];

    sd->type = AV_PKT_DATA_REPLAYGAIN;

    sd->data = (uint8_t*)replaygain;

    sd->size = sizeof(*replaygain);



    replaygain->track_gain = tg;

    replaygain->track_peak = tp;

    replaygain->album_gain = ag;

    replaygain->album_peak = ap;



    return 0;

}

static int gif_read_header1(GifState *s)

{

    uint8_t sig[6];

    int v, n;

    int background_color_index;



    if (bytestream2_get_bytes_left(&s->gb) < 13)

        return AVERROR_INVALIDDATA;



    /* read gif signature */

    bytestream2_get_bufferu(&s->gb, sig, 6);

    if (memcmp(sig, gif87a_sig, 6) != 0 &&

        memcmp(sig, gif89a_sig, 6) != 0)

        return AVERROR_INVALIDDATA;



    /* read screen header */

    s->transparent_color_index = -1;

    s->screen_width = bytestream2_get_le16u(&s->gb);

    s->screen_height = bytestream2_get_le16u(&s->gb);

    if(   (unsigned)s->screen_width  > 32767

       || (unsigned)s->screen_height > 32767){

        av_log(s->avctx, AV_LOG_ERROR, "picture size too large\n");

        return AVERROR_INVALIDDATA;

    }



    av_fast_malloc(&s->idx_line, &s->idx_line_size, s->screen_width);

    if (!s->idx_line)

        return AVERROR(ENOMEM);



    v = bytestream2_get_byteu(&s->gb);

    s->color_resolution = ((v & 0x70) >> 4) + 1;

    s->has_global_palette = (v & 0x80);

    s->bits_per_pixel = (v & 0x07) + 1;

    background_color_index = bytestream2_get_byteu(&s->gb);

    n = bytestream2_get_byteu(&s->gb);

    if (n) {

        s->avctx->sample_aspect_ratio.num = n + 15;

        s->avctx->sample_aspect_ratio.den = 64;

    }



    av_dlog(s->avctx, "screen_w=%d screen_h=%d bpp=%d global_palette=%d\n",

           s->screen_width, s->screen_height, s->bits_per_pixel,

           s->has_global_palette);



    if (s->has_global_palette) {

        s->background_color_index = background_color_index;

        n = 1 << s->bits_per_pixel;

        if (bytestream2_get_bytes_left(&s->gb) < n * 3)

            return AVERROR_INVALIDDATA;



        gif_read_palette(s, s->global_palette, n);

        s->bg_color = s->global_palette[s->background_color_index];

    } else

        s->background_color_index = -1;



    return 0;

}

static int read_header(ShortenContext *s)

{

    int i, ret;

    int maxnlpc = 0;

    /* shorten signature */

    if (get_bits_long(&s->gb, 32) != AV_RB32("ajkg")) {

        av_log(s->avctx, AV_LOG_ERROR, "missing shorten magic 'ajkg'\n");

        return -1;

    }



    s->lpcqoffset = 0;

    s->blocksize = DEFAULT_BLOCK_SIZE;

    s->nmean = -1;

    s->version = get_bits(&s->gb, 8);

    s->internal_ftype = get_uint(s, TYPESIZE);



    s->channels = get_uint(s, CHANSIZE);

    if (s->channels > MAX_CHANNELS) {

        av_log(s->avctx, AV_LOG_ERROR, "too many channels: %d\n", s->channels);

        return -1;

    }

    s->avctx->channels = s->channels;



    /* get blocksize if version > 0 */

    if (s->version > 0) {

        int skip_bytes, blocksize;



        blocksize = get_uint(s, av_log2(DEFAULT_BLOCK_SIZE));

        if (!blocksize || blocksize > MAX_BLOCKSIZE) {

            av_log(s->avctx, AV_LOG_ERROR, "invalid or unsupported block size: %d\n",

                   blocksize);

            return AVERROR(EINVAL);

        }

        s->blocksize = blocksize;



        maxnlpc = get_uint(s, LPCQSIZE);

        s->nmean = get_uint(s, 0);



        skip_bytes = get_uint(s, NSKIPSIZE);

        for (i=0; i<skip_bytes; i++) {

            skip_bits(&s->gb, 8);

        }

    }

    s->nwrap = FFMAX(NWRAP, maxnlpc);



    if ((ret = allocate_buffers(s)) < 0)

        return ret;



    if ((ret = init_offset(s)) < 0)

        return ret;



    if (s->version > 1)

        s->lpcqoffset = V2LPCQOFFSET;



    if (get_ur_golomb_shorten(&s->gb, FNSIZE) != FN_VERBATIM) {

        av_log(s->avctx, AV_LOG_ERROR, "missing verbatim section at beginning of stream\n");

        return -1;

    }



    s->header_size = get_ur_golomb_shorten(&s->gb, VERBATIM_CKSIZE_SIZE);

    if (s->header_size >= OUT_BUFFER_SIZE || s->header_size < CANONICAL_HEADER_SIZE) {

        av_log(s->avctx, AV_LOG_ERROR, "header is wrong size: %d\n", s->header_size);

        return -1;

    }



    for (i=0; i<s->header_size; i++)

        s->header[i] = (char)get_ur_golomb_shorten(&s->gb, VERBATIM_BYTE_SIZE);



    if (decode_wave_header(s->avctx, s->header, s->header_size) < 0)

        return -1;



    s->cur_chan = 0;

    s->bitshift = 0;



    s->got_header = 1;



    return 0;

}

void parse_options(void *optctx, int argc, char **argv, const OptionDef *options,

                   void (*parse_arg_function)(void *, const char*))

{

    const char *opt;

    int optindex, handleoptions = 1, ret;



    /* perform system-dependent conversions for arguments list */

    prepare_app_arguments(&argc, &argv);



    /* parse options */

    optindex = 1;

    while (optindex < argc) {

        opt = argv[optindex++];



        if (handleoptions && opt[0] == '-' && opt[1] != '\0') {

            if (opt[1] == '-' && opt[2] == '\0') {

                handleoptions = 0;

                continue;

            }

            opt++;



            if ((ret = parse_option(optctx, opt, argv[optindex], options)) < 0)

                exit(1);

            optindex += ret;

        } else {

            if (parse_arg_function)

                parse_arg_function(optctx, opt);

        }

    }

}

void ff_aac_search_for_ltp(AACEncContext *s, SingleChannelElement *sce,

                           int common_window)

{

    int w, g, w2, i, start = 0, count = 0;

    int saved_bits = -(15 + FFMIN(sce->ics.max_sfb, MAX_LTP_LONG_SFB));

    float *C34 = &s->scoefs[128*0], *PCD = &s->scoefs[128*1];

    float *PCD34 = &s->scoefs[128*2];

    const int max_ltp = FFMIN(sce->ics.max_sfb, MAX_LTP_LONG_SFB);



    if (sce->ics.window_sequence[0] == EIGHT_SHORT_SEQUENCE ||

        !sce->ics.ltp.lag)

        return;



    for (w = 0; w < sce->ics.num_windows; w += sce->ics.group_len[w]) {

        start = 0;

        for (g = 0;  g < sce->ics.num_swb; g++) {

            int bits1 = 0, bits2 = 0;

            float dist1 = 0.0f, dist2 = 0.0f;

            if (w*16+g > max_ltp) {

                start += sce->ics.swb_sizes[g];

                continue;

            }

            for (w2 = 0; w2 < sce->ics.group_len[w]; w2++) {

                int bits_tmp1, bits_tmp2;

                FFPsyBand *band = &s->psy.ch[s->cur_channel].psy_bands[(w+w2)*16+g];

                for (i = 0; i < sce->ics.swb_sizes[g]; i++)

                    PCD[i] = sce->coeffs[start+(w+w2)*128+i] - sce->lcoeffs[start+(w+w2)*128+i];

                abs_pow34_v(C34,  &sce->coeffs[start+(w+w2)*128],  sce->ics.swb_sizes[g]);

                abs_pow34_v(PCD34, PCD, sce->ics.swb_sizes[g]);

                dist1 += quantize_band_cost(s, &sce->coeffs[start+(w+w2)*128], C34, sce->ics.swb_sizes[g],

                                            sce->sf_idx[(w+w2)*16+g], sce->band_type[(w+w2)*16+g],

                                            s->lambda/band->threshold, INFINITY, &bits_tmp1, NULL, 0);

                dist2 += quantize_band_cost(s, PCD, PCD34, sce->ics.swb_sizes[g],

                                            sce->sf_idx[(w+w2)*16+g],

                                            sce->band_type[(w+w2)*16+g],

                                            s->lambda/band->threshold, INFINITY, &bits_tmp2, NULL, 0);

                bits1 += bits_tmp1;

                bits2 += bits_tmp2;

            }

            if (dist2 < dist1 && bits2 < bits1) {

                for (w2 = 0; w2 < sce->ics.group_len[w]; w2++)

                    for (i = 0; i < sce->ics.swb_sizes[g]; i++)

                        sce->coeffs[start+(w+w2)*128+i] -= sce->lcoeffs[start+(w+w2)*128+i];

                sce->ics.ltp.used[w*16+g] = 1;

                saved_bits += bits1 - bits2;

                count++;

            }

            start += sce->ics.swb_sizes[g];

        }

    }



    sce->ics.ltp.present = !!count && (saved_bits >= 0);

    sce->ics.predictor_present = !!sce->ics.ltp.present;



    /* Reset any marked sfbs */

    if (!sce->ics.ltp.present && !!count) {

        for (w = 0; w < sce->ics.num_windows; w += sce->ics.group_len[w]) {

            start = 0;

            for (g = 0;  g < sce->ics.num_swb; g++) {

                if (sce->ics.ltp.used[w*16+g]) {

                    for (w2 = 0; w2 < sce->ics.group_len[w]; w2++) {

                        for (i = 0; i < sce->ics.swb_sizes[g]; i++) {

                            sce->coeffs[start+(w+w2)*128+i] += sce->lcoeffs[start+(w+w2)*128+i];

                        }

                    }

                }

                start += sce->ics.swb_sizes[g];

            }

        }

    }

}

void av_opencl_buffer_release(cl_mem *cl_buf)

{

    cl_int status = 0;

    if (!cl_buf)

        return;

    status = clReleaseMemObject(*cl_buf);

    if (status != CL_SUCCESS) {

        av_log(&openclutils, AV_LOG_ERROR, "Could not release OpenCL buffer: %s\n", opencl_errstr(status));

    }

    memset(cl_buf, 0, sizeof(*cl_buf));

}

int ff_rv34_decode_frame(AVCodecContext *avctx,

                            void *data, int *got_picture_ptr,

                            AVPacket *avpkt)

{

    const uint8_t *buf = avpkt->data;

    int buf_size = avpkt->size;

    RV34DecContext *r = avctx->priv_data;

    MpegEncContext *s = &r->s;

    AVFrame *pict = data;

    SliceInfo si;

    int i, ret;

    int slice_count;

    const uint8_t *slices_hdr = NULL;

    int last = 0;



    /* no supplementary picture */

    if (buf_size == 0) {

        /* special case for last picture */

        if (s->low_delay==0 && s->next_picture_ptr) {

            if ((ret = av_frame_ref(pict, &s->next_picture_ptr->f)) < 0)

                return ret;

            s->next_picture_ptr = NULL;



            *got_picture_ptr = 1;

        }

        return 0;

    }



    if(!avctx->slice_count){

        slice_count = (*buf++) + 1;

        slices_hdr = buf + 4;

        buf += 8 * slice_count;

        buf_size -= 1 + 8 * slice_count;

    }else

        slice_count = avctx->slice_count;



    //parse first slice header to check whether this frame can be decoded

    if(get_slice_offset(avctx, slices_hdr, 0) < 0 ||

       get_slice_offset(avctx, slices_hdr, 0) > buf_size){

        av_log(avctx, AV_LOG_ERROR, "Slice offset is invalid\n");

        return AVERROR_INVALIDDATA;

    }

    init_get_bits(&s->gb, buf+get_slice_offset(avctx, slices_hdr, 0), (buf_size-get_slice_offset(avctx, slices_hdr, 0))*8);

    if(r->parse_slice_header(r, &r->s.gb, &si) < 0 || si.start){

        av_log(avctx, AV_LOG_ERROR, "First slice header is incorrect\n");

        return AVERROR_INVALIDDATA;

    }

    if ((!s->last_picture_ptr || !s->last_picture_ptr->f.data[0]) &&

        si.type == AV_PICTURE_TYPE_B) {

        av_log(avctx, AV_LOG_ERROR, "Invalid decoder state: B-frame without "

               "reference data.\n");

        return AVERROR_INVALIDDATA;

    }

    if(   (avctx->skip_frame >= AVDISCARD_NONREF && si.type==AV_PICTURE_TYPE_B)

       || (avctx->skip_frame >= AVDISCARD_NONKEY && si.type!=AV_PICTURE_TYPE_I)

       ||  avctx->skip_frame >= AVDISCARD_ALL)

        return avpkt->size;



    /* first slice */

    if (si.start == 0) {

        if (s->mb_num_left > 0) {

            av_log(avctx, AV_LOG_ERROR, "New frame but still %d MB left.",

                   s->mb_num_left);

            ff_er_frame_end(&s->er);

            ff_MPV_frame_end(s);

        }



        if (s->width != si.width || s->height != si.height) {

            int err;



            av_log(s->avctx, AV_LOG_WARNING, "Changing dimensions to %dx%d\n",

                   si.width, si.height);



            s->width  = si.width;

            s->height = si.height;



            err = ff_set_dimensions(s->avctx, s->width, s->height);

            if (err < 0)

                return err;



            if ((err = ff_MPV_common_frame_size_change(s)) < 0)

                return err;

            if ((err = rv34_decoder_realloc(r)) < 0)

                return err;

        }

        s->pict_type = si.type ? si.type : AV_PICTURE_TYPE_I;

        if (ff_MPV_frame_start(s, s->avctx) < 0)

            return -1;

        ff_mpeg_er_frame_start(s);

        if (!r->tmp_b_block_base) {

            int i;



            r->tmp_b_block_base = av_malloc(s->linesize * 48);

            for (i = 0; i < 2; i++)

                r->tmp_b_block_y[i] = r->tmp_b_block_base

                                      + i * 16 * s->linesize;

            for (i = 0; i < 4; i++)

                r->tmp_b_block_uv[i] = r->tmp_b_block_base + 32 * s->linesize

                                       + (i >> 1) * 8 * s->uvlinesize

                                       + (i &  1) * 16;

        }

        r->cur_pts = si.pts;

        if (s->pict_type != AV_PICTURE_TYPE_B) {

            r->last_pts = r->next_pts;

            r->next_pts = r->cur_pts;

        } else {

            int refdist = GET_PTS_DIFF(r->next_pts, r->last_pts);

            int dist0   = GET_PTS_DIFF(r->cur_pts,  r->last_pts);

            int dist1   = GET_PTS_DIFF(r->next_pts, r->cur_pts);



            if(!refdist){

                r->mv_weight1 = r->mv_weight2 = r->weight1 = r->weight2 = 8192;

                r->scaled_weight = 0;

            }else{

                r->mv_weight1 = (dist0 << 14) / refdist;

                r->mv_weight2 = (dist1 << 14) / refdist;

                if((r->mv_weight1|r->mv_weight2) & 511){

                    r->weight1 = r->mv_weight1;

                    r->weight2 = r->mv_weight2;

                    r->scaled_weight = 0;

                }else{

                    r->weight1 = r->mv_weight1 >> 9;

                    r->weight2 = r->mv_weight2 >> 9;

                    r->scaled_weight = 1;

                }

            }

        }

        s->mb_x = s->mb_y = 0;

        ff_thread_finish_setup(s->avctx);

    } else if (HAVE_THREADS &&

               (s->avctx->active_thread_type & FF_THREAD_FRAME)) {

        av_log(s->avctx, AV_LOG_ERROR, "Decoder needs full frames in frame "

               "multithreading mode (start MB is %d).\n", si.start);

        return AVERROR_INVALIDDATA;

    }



    for(i = 0; i < slice_count; i++){

        int offset = get_slice_offset(avctx, slices_hdr, i);

        int size;

        if(i+1 == slice_count)

            size = buf_size - offset;

        else

            size = get_slice_offset(avctx, slices_hdr, i+1) - offset;



        if(offset < 0 || offset > buf_size){

            av_log(avctx, AV_LOG_ERROR, "Slice offset is invalid\n");

            break;

        }



        r->si.end = s->mb_width * s->mb_height;

        s->mb_num_left = r->s.mb_x + r->s.mb_y*r->s.mb_width - r->si.start;



        if(i+1 < slice_count){

            if (get_slice_offset(avctx, slices_hdr, i+1) < 0 ||

                get_slice_offset(avctx, slices_hdr, i+1) > buf_size) {

                av_log(avctx, AV_LOG_ERROR, "Slice offset is invalid\n");

                break;

            }

            init_get_bits(&s->gb, buf+get_slice_offset(avctx, slices_hdr, i+1), (buf_size-get_slice_offset(avctx, slices_hdr, i+1))*8);

            if(r->parse_slice_header(r, &r->s.gb, &si) < 0){

                if(i+2 < slice_count)

                    size = get_slice_offset(avctx, slices_hdr, i+2) - offset;

                else

                    size = buf_size - offset;

            }else

                r->si.end = si.start;

        }

        if (size < 0 || size > buf_size - offset) {

            av_log(avctx, AV_LOG_ERROR, "Slice size is invalid\n");

            break;

        }

        last = rv34_decode_slice(r, r->si.end, buf + offset, size);

        if(last)

            break;

    }



    if (s->current_picture_ptr) {

        if (last) {

            if(r->loop_filter)

                r->loop_filter(r, s->mb_height - 1);



            ret = finish_frame(avctx, pict);

            if (ret < 0)

                return ret;

            *got_picture_ptr = ret;

        } else if (HAVE_THREADS &&

                   (s->avctx->active_thread_type & FF_THREAD_FRAME)) {

            av_log(avctx, AV_LOG_INFO, "marking unfished frame as finished\n");

            /* always mark the current frame as finished, frame-mt supports

             * only complete frames */

            ff_er_frame_end(&s->er);

            ff_MPV_frame_end(s);

            s->mb_num_left = 0;

            ff_thread_report_progress(&s->current_picture_ptr->tf, INT_MAX, 0);

            return AVERROR_INVALIDDATA;

        }

    }



    return avpkt->size;

}

static int get_preset_file_2(const char *preset_name, const char *codec_name, AVIOContext **s)

{

    int i, ret = 1;

    char filename[1000];

    const char *base[3] = { getenv("AVCONV_DATADIR"),

                            getenv("HOME"),

                            AVCONV_DATADIR,

                            };



    for (i = 0; i < FF_ARRAY_ELEMS(base) && ret; i++) {

        if (!base[i])

            continue;

        if (codec_name) {

            snprintf(filename, sizeof(filename), "%s%s/%s-%s.avpreset", base[i],

                     i != 1 ? "" : "/.avconv", codec_name, preset_name);

            ret = avio_open2(s, filename, AVIO_FLAG_READ, &int_cb, NULL);

        }

        if (ret) {

            snprintf(filename, sizeof(filename), "%s%s/%s.avpreset", base[i],

                     i != 1 ? "" : "/.avconv", preset_name);

            ret = avio_open2(s, filename, AVIO_FLAG_READ, &int_cb, NULL);

        }

    }

    return ret;

}

static int mov_write_mvhd_tag(ByteIOContext *pb, MOVContext *mov)

{

    int maxTrackID = 1, i;

    int64_t maxTrackLenTemp, maxTrackLen = 0;

    int version;



    for (i=0; i<MAX_STREAMS; i++) {

        if(mov->tracks[i].entry > 0) {

            maxTrackLenTemp = av_rescale_rnd(mov->tracks[i].trackDuration, globalTimescale, mov->tracks[i].timescale, AV_ROUND_UP);

            if(maxTrackLen < maxTrackLenTemp)

                maxTrackLen = maxTrackLenTemp;

            if(maxTrackID < mov->tracks[i].trackID)

                maxTrackID = mov->tracks[i].trackID;

        }

    }



    version = maxTrackLen < UINT32_MAX ? 0 : 1;

    (version == 1) ? put_be32(pb, 120) : put_be32(pb, 108); /* size */

    put_tag(pb, "mvhd");

    put_byte(pb, version);

    put_be24(pb, 0); /* flags */

    if (version == 1) {

        put_be64(pb, mov->time);

        put_be64(pb, mov->time);

    } else {

        put_be32(pb, mov->time); /* creation time */

        put_be32(pb, mov->time); /* modification time */

    }

    put_be32(pb, mov->timescale); /* timescale */

    (version == 1) ? put_be64(pb, maxTrackLen) : put_be32(pb, maxTrackLen); /* duration of longest track */



    put_be32(pb, 0x00010000); /* reserved (preferred rate) 1.0 = normal */

    put_be16(pb, 0x0100); /* reserved (preferred volume) 1.0 = normal */

    put_be16(pb, 0); /* reserved */

    put_be32(pb, 0); /* reserved */

    put_be32(pb, 0); /* reserved */



    /* Matrix structure */

    put_be32(pb, 0x00010000); /* reserved */

    put_be32(pb, 0x0); /* reserved */

    put_be32(pb, 0x0); /* reserved */

    put_be32(pb, 0x0); /* reserved */

    put_be32(pb, 0x00010000); /* reserved */

    put_be32(pb, 0x0); /* reserved */

    put_be32(pb, 0x0); /* reserved */

    put_be32(pb, 0x0); /* reserved */

    put_be32(pb, 0x40000000); /* reserved */



    put_be32(pb, 0); /* reserved (preview time) */

    put_be32(pb, 0); /* reserved (preview duration) */

    put_be32(pb, 0); /* reserved (poster time) */

    put_be32(pb, 0); /* reserved (selection time) */

    put_be32(pb, 0); /* reserved (selection duration) */

    put_be32(pb, 0); /* reserved (current time) */

    put_be32(pb, maxTrackID+1); /* Next track id */

    return 0x6c;

}

static int g2m_init_buffers(G2MContext *c)

{

    int aligned_height;



    if (!c->framebuf || c->old_width < c->width || c->old_height < c->height) {

        c->framebuf_stride = FFALIGN(c->width * 3, 16);

        aligned_height     = FFALIGN(c->height,    16);

        av_free(c->framebuf);

        c->framebuf = av_mallocz(c->framebuf_stride * aligned_height);

        if (!c->framebuf)

            return AVERROR(ENOMEM);

    }

    if (!c->synth_tile || !c->jpeg_tile ||

        c->old_tile_w < c->tile_width ||

        c->old_tile_h < c->tile_height) {

        c->tile_stride = FFALIGN(c->tile_width * 3, 16);

        aligned_height = FFALIGN(c->tile_height,    16);

        av_free(c->synth_tile);

        av_free(c->jpeg_tile);

        av_free(c->kempf_buf);

        av_free(c->kempf_flags);

        c->synth_tile  = av_mallocz(c->tile_stride      * aligned_height);

        c->jpeg_tile   = av_mallocz(c->tile_stride      * aligned_height);

        c->kempf_buf   = av_mallocz((c->tile_width + 1) * aligned_height

                                    + FF_INPUT_BUFFER_PADDING_SIZE);

        c->kempf_flags = av_mallocz( c->tile_width      * aligned_height);

        if (!c->synth_tile || !c->jpeg_tile ||

            !c->kempf_buf || !c->kempf_flags)

            return AVERROR(ENOMEM);

    }



    return 0;

}

int ff_mpv_common_frame_size_change(MpegEncContext *s)

{

    int i, err = 0;



    if (!s->context_initialized)

        return AVERROR(EINVAL);



    if (s->slice_context_count > 1) {

        for (i = 0; i < s->slice_context_count; i++) {

            free_duplicate_context(s->thread_context[i]);

        }

        for (i = 1; i < s->slice_context_count; i++) {

            av_freep(&s->thread_context[i]);

        }

    } else

        free_duplicate_context(s);



    free_context_frame(s);



    if (s->picture)

        for (i = 0; i < MAX_PICTURE_COUNT; i++) {

                s->picture[i].needs_realloc = 1;

        }



    s->last_picture_ptr         =

    s->next_picture_ptr         =

    s->current_picture_ptr      = NULL;



    // init

    if (s->codec_id == AV_CODEC_ID_MPEG2VIDEO && !s->progressive_sequence)

        s->mb_height = (s->height + 31) / 32 * 2;

    else

        s->mb_height = (s->height + 15) / 16;



    if ((s->width || s->height) &&

        (err = av_image_check_size(s->width, s->height, 0, s->avctx)) < 0)

        goto fail;



    if ((err = init_context_frame(s)))

        goto fail;



    s->thread_context[0]   = s;



    if (s->width && s->height) {

        int nb_slices = s->slice_context_count;

        if (nb_slices > 1) {

            for (i = 1; i < nb_slices; i++) {

                s->thread_context[i] = av_malloc(sizeof(MpegEncContext));

                memcpy(s->thread_context[i], s, sizeof(MpegEncContext));

            }



            for (i = 0; i < nb_slices; i++) {

                if ((err = init_duplicate_context(s->thread_context[i])) < 0)

                    goto fail;

                    s->thread_context[i]->start_mb_y =

                        (s->mb_height * (i) + nb_slices / 2) / nb_slices;

                    s->thread_context[i]->end_mb_y   =

                        (s->mb_height * (i + 1) + nb_slices / 2) / nb_slices;

            }

        } else {

            err = init_duplicate_context(s);

            if (err < 0)

                goto fail;

            s->start_mb_y = 0;

            s->end_mb_y   = s->mb_height;

        }

        s->slice_context_count = nb_slices;

    }



    return 0;

 fail:

    ff_mpv_common_end(s);

    return err;

}

void ff_snow_horizontal_compose97i_mmx(DWTELEM *b, int width){

    const int w2= (width+1)>>1;

    DWTELEM temp[width >> 1];

    const int w_l= (width>>1);

    const int w_r= w2 - 1;

    int i;



    { // Lift 0

        DWTELEM * const ref = b + w2 - 1;



        i = 1;

        b[0] = b[0] - ((W_DM * 2 * ref[1]+W_DO)>>W_DS);

        asm volatile(

            "pcmpeqd    %%mm7, %%mm7         \n\t"

            "pslld        $31, %%mm7         \n\t"

            "psrld        $29, %%mm7         \n\t"

           ::);

        for(; i<w_l-3; i+=4){

            asm volatile(

                "movq     (%1), %%mm2        \n\t"

                "movq    8(%1), %%mm6        \n\t"

                "paddd   4(%1), %%mm2        \n\t"

                "paddd  12(%1), %%mm6        \n\t"

                "movq    %%mm2, %%mm0        \n\t"

                "movq    %%mm6, %%mm4        \n\t"

                "paddd   %%mm2, %%mm2        \n\t"

                "paddd   %%mm6, %%mm6        \n\t"

                "paddd   %%mm0, %%mm2        \n\t"

                "paddd   %%mm4, %%mm6        \n\t"

                "paddd   %%mm7, %%mm2        \n\t"

                "paddd   %%mm7, %%mm6        \n\t"

                "psrad      $3, %%mm2        \n\t"

                "psrad      $3, %%mm6        \n\t"

                "movq     (%0), %%mm0        \n\t"

                "movq    8(%0), %%mm4        \n\t"

                "psubd   %%mm2, %%mm0        \n\t"

                "psubd   %%mm6, %%mm4        \n\t"

                "movq    %%mm0, (%0)         \n\t"

                "movq    %%mm4, 8(%0)        \n\t"

                :: "r"(&b[i]), "r"(&ref[i])

                 : "memory"

               );

        }

        snow_horizontal_compose_lift_lead_out(i, b, b, ref, width, w_l, 0, W_DM, W_DO, W_DS);

    }



    { // Lift 1

        DWTELEM * const dst = b+w2;



        i = 0;

        for(; i<w_r-3; i+=4){

            asm volatile(

                "movq     (%1), %%mm2        \n\t"

                "movq    8(%1), %%mm6        \n\t"

                "paddd   4(%1), %%mm2        \n\t"

                "paddd  12(%1), %%mm6        \n\t"

                "movq     (%0), %%mm0        \n\t"

                "movq    8(%0), %%mm4        \n\t"

                "psubd   %%mm2, %%mm0        \n\t"

                "psubd   %%mm6, %%mm4        \n\t"

                "movq    %%mm0, (%0)         \n\t"

                "movq    %%mm4, 8(%0)        \n\t"

                :: "r"(&dst[i]), "r"(&b[i])

                 : "memory"

               );

        }

        snow_horizontal_compose_lift_lead_out(i, dst, dst, b, width, w_r, 1, W_CM, W_CO, W_CS);

    }



    { // Lift 2

        DWTELEM * const ref = b+w2 - 1;



        i = 1;

        b[0] = b[0] + (((2 * ref[1] + W_BO) + 4 * b[0]) >> W_BS);

        asm volatile(

            "pslld          $1, %%mm7        \n\t"

           ::);

        for(; i<w_l-3; i+=4){

            asm volatile(

                "movq     (%1), %%mm0        \n\t"

                "movq    8(%1), %%mm4        \n\t"

                "paddd   4(%1), %%mm0        \n\t"

                "paddd  12(%1), %%mm4        \n\t"

                "paddd   %%mm7, %%mm0        \n\t"

                "paddd   %%mm7, %%mm4        \n\t"

                "psrad      $2, %%mm0        \n\t"

                "psrad      $2, %%mm4        \n\t"

                "movq     (%0), %%mm1        \n\t"

                "movq    8(%0), %%mm5        \n\t"

                "paddd   %%mm1, %%mm0        \n\t"

                "paddd   %%mm5, %%mm4        \n\t"

                "psrad      $2, %%mm0        \n\t"

                "psrad      $2, %%mm4        \n\t"

                "paddd   %%mm1, %%mm0        \n\t"

                "paddd   %%mm5, %%mm4        \n\t"

                "movq    %%mm0, (%0)         \n\t"

                "movq    %%mm4, 8(%0)        \n\t"

                :: "r"(&b[i]), "r"(&ref[i])

                 : "memory"

               );

        }

        snow_horizontal_compose_liftS_lead_out(i, b, b, ref, width, w_l);

    }



    { // Lift 3

        DWTELEM * const src = b+w2;

        i = 0;



        for(; i<w_r-3; i+=4){

            asm volatile(

                "movq    4(%1), %%mm2        \n\t"

                "movq   12(%1), %%mm6        \n\t"

                "paddd    (%1), %%mm2        \n\t"

                "paddd   8(%1), %%mm6        \n\t"

                "movq     (%0), %%mm0        \n\t"

                "movq    8(%0), %%mm4        \n\t"

                "paddd   %%mm2, %%mm0        \n\t"

                "paddd   %%mm6, %%mm4        \n\t"

                "psrad      $1, %%mm2        \n\t"

                "psrad      $1, %%mm6        \n\t"

                "paddd   %%mm0, %%mm2        \n\t"

                "paddd   %%mm4, %%mm6        \n\t"

                "movq    %%mm2, (%2)         \n\t"

                "movq    %%mm6, 8(%2)        \n\t"

                :: "r"(&src[i]), "r"(&b[i]), "r"(&temp[i])

                 : "memory"

               );

        }

        snow_horizontal_compose_lift_lead_out(i, temp, src, b, width, w_r, 1, -W_AM, W_AO+1, W_AS);

    }



    {

        snow_interleave_line_header(&i, width, b, temp);



        for (; (i & 0xE) != 0xE; i-=2){

            b[i+1] = temp[i>>1];

            b[i] = b[i>>1];

        }

        for (i-=14; i>=0; i-=16){

            asm volatile(

                "movq        (%1), %%mm0       \n\t"

                "movq       8(%1), %%mm2       \n\t"

                "movq      16(%1), %%mm4       \n\t"

                "movq      24(%1), %%mm6       \n\t"

                "movq        (%1), %%mm1       \n\t"

                "movq       8(%1), %%mm3       \n\t"

                "movq      16(%1), %%mm5       \n\t"

                "movq      24(%1), %%mm7       \n\t"

                "punpckldq   (%2), %%mm0       \n\t"

                "punpckldq  8(%2), %%mm2       \n\t"

                "punpckldq 16(%2), %%mm4       \n\t"

                "punpckldq 24(%2), %%mm6       \n\t"

                "movq       %%mm0, (%0)        \n\t"

                "movq       %%mm2, 16(%0)      \n\t"

                "movq       %%mm4, 32(%0)      \n\t"

                "movq       %%mm6, 48(%0)      \n\t"

                "punpckhdq   (%2), %%mm1       \n\t"

                "punpckhdq  8(%2), %%mm3       \n\t"

                "punpckhdq 16(%2), %%mm5       \n\t"

                "punpckhdq 24(%2), %%mm7       \n\t"

                "movq       %%mm1, 8(%0)       \n\t"

                "movq       %%mm3, 24(%0)      \n\t"

                "movq       %%mm5, 40(%0)      \n\t"

                "movq       %%mm7, 56(%0)      \n\t"

                :: "r"(&b[i]), "r"(&b[i>>1]), "r"(&temp[i>>1])

                 : "memory"

               );

        }

    }

}

static int oma_read_packet(AVFormatContext *s, AVPacket *pkt)

{

    OMAContext *oc = s->priv_data;

    int packet_size = s->streams[0]->codec->block_align;

    int ret = av_get_packet(s->pb, pkt, packet_size);



    if (ret <= 0)

        return AVERROR(EIO);



    pkt->stream_index = 0;



    if (oc->encrypted) {

        /* previous unencrypted block saved in IV for

         * the next packet (CBC mode) */

        av_des_crypt(&oc->av_des, pkt->data, pkt->data,

                     (packet_size >> 3), oc->iv, 1);

    }



    return ret;

}

static int rtsp_fetch_packet(AVFormatContext *s, AVPacket *pkt)

{

    RTSPState *rt = s->priv_data;

    int ret, len;

    uint8_t buf[10 * RTP_MAX_PACKET_LENGTH];

    RTSPStream *rtsp_st;



    /* get next frames from the same RTP packet */

    if (rt->cur_transport_priv) {

        if (rt->transport == RTSP_TRANSPORT_RDT)

            ret = ff_rdt_parse_packet(rt->cur_transport_priv, pkt, NULL, 0);

        else

            ret = rtp_parse_packet(rt->cur_transport_priv, pkt, NULL, 0);

        if (ret == 0) {

            rt->cur_transport_priv = NULL;

            return 0;

        } else if (ret == 1) {

            return 0;

        } else {

            rt->cur_transport_priv = NULL;

        }

    }



    /* read next RTP packet */

 redo:

    switch(rt->lower_transport) {

    default:

#if CONFIG_RTSP_DEMUXER

    case RTSP_LOWER_TRANSPORT_TCP:

        len = tcp_read_packet(s, &rtsp_st, buf, sizeof(buf));

        break;

#endif

    case RTSP_LOWER_TRANSPORT_UDP:

    case RTSP_LOWER_TRANSPORT_UDP_MULTICAST:

        len = udp_read_packet(s, &rtsp_st, buf, sizeof(buf));

        if (len >=0 && rtsp_st->transport_priv && rt->transport == RTSP_TRANSPORT_RTP)

            rtp_check_and_send_back_rr(rtsp_st->transport_priv, len);

        break;

    }

    if (len < 0)

        return len;

    if (len == 0)

        return AVERROR_EOF;

    if (rt->transport == RTSP_TRANSPORT_RDT)

        ret = ff_rdt_parse_packet(rtsp_st->transport_priv, pkt, buf, len);

    else

        ret = rtp_parse_packet(rtsp_st->transport_priv, pkt, buf, len);

    if (ret < 0)

        goto redo;

    if (ret == 1) {

        /* more packets may follow, so we save the RTP context */

        rt->cur_transport_priv = rtsp_st->transport_priv;

    }



    return ret;

}

rtsp_open_transport_ctx(AVFormatContext *s, RTSPStream *rtsp_st)

{

    RTSPState *rt = s->priv_data;

    AVStream *st = NULL;



    /* open the RTP context */

    if (rtsp_st->stream_index >= 0)

        st = s->streams[rtsp_st->stream_index];

    if (!st)

        s->ctx_flags |= AVFMTCTX_NOHEADER;



    if (rt->transport == RTSP_TRANSPORT_RDT)

        rtsp_st->transport_priv = ff_rdt_parse_open(s, st->index,

                                            rtsp_st->dynamic_protocol_context,

                                            rtsp_st->dynamic_handler);

    else

        rtsp_st->transport_priv = rtp_parse_open(s, st, rtsp_st->rtp_handle,

                                         rtsp_st->sdp_payload_type,

                                         &rtsp_st->rtp_payload_data);



    if (!rtsp_st->transport_priv) {

         return AVERROR(ENOMEM);

    } else if (rt->transport != RTSP_TRANSPORT_RDT) {

        if(rtsp_st->dynamic_handler) {

            rtp_parse_set_dynamic_protocol(rtsp_st->transport_priv,

                                           rtsp_st->dynamic_protocol_context,

                                           rtsp_st->dynamic_handler);

        }

    }



    return 0;

}

void ff_print_debug_info2(AVCodecContext *avctx, AVFrame *pict, uint8_t *mbskip_table,

                         uint32_t *mbtype_table, int8_t *qscale_table, int16_t (*motion_val[2])[2],

                         int *low_delay,

                         int mb_width, int mb_height, int mb_stride, int quarter_sample)

{

    if ((avctx->flags2 & AV_CODEC_FLAG2_EXPORT_MVS) && mbtype_table && motion_val[0]) {

        const int shift = 1 + quarter_sample;

        const int mv_sample_log2 = avctx->codec_id == AV_CODEC_ID_H264 || avctx->codec_id == AV_CODEC_ID_SVQ3 ? 2 : 1;

        const int mv_stride      = (mb_width << mv_sample_log2) +

                                   (avctx->codec->id == AV_CODEC_ID_H264 ? 0 : 1);

        int mb_x, mb_y, mbcount = 0;



        /* size is width * height * 2 * 4 where 2 is for directions and 4 is

         * for the maximum number of MB (4 MB in case of IS_8x8) */

        AVMotionVector *mvs = av_malloc_array(mb_width * mb_height, 2 * 4 * sizeof(AVMotionVector));

        if (!mvs)

            return;



        for (mb_y = 0; mb_y < mb_height; mb_y++) {

            for (mb_x = 0; mb_x < mb_width; mb_x++) {

                int i, direction, mb_type = mbtype_table[mb_x + mb_y * mb_stride];

                for (direction = 0; direction < 2; direction++) {

                    if (!USES_LIST(mb_type, direction))

                        continue;

                    if (IS_8X8(mb_type)) {

                        for (i = 0; i < 4; i++) {

                            int sx = mb_x * 16 + 4 + 8 * (i & 1);

                            int sy = mb_y * 16 + 4 + 8 * (i >> 1);

                            int xy = (mb_x * 2 + (i & 1) +

                                      (mb_y * 2 + (i >> 1)) * mv_stride) << (mv_sample_log2 - 1);

                            int mx = (motion_val[direction][xy][0] >> shift) + sx;

                            int my = (motion_val[direction][xy][1] >> shift) + sy;

                            mbcount += add_mb(mvs + mbcount, mb_type, sx, sy, mx, my, direction);

                        }

                    } else if (IS_16X8(mb_type)) {

                        for (i = 0; i < 2; i++) {

                            int sx = mb_x * 16 + 8;

                            int sy = mb_y * 16 + 4 + 8 * i;

                            int xy = (mb_x * 2 + (mb_y * 2 + i) * mv_stride) << (mv_sample_log2 - 1);

                            int mx = (motion_val[direction][xy][0] >> shift);

                            int my = (motion_val[direction][xy][1] >> shift);



                            if (IS_INTERLACED(mb_type))

                                my *= 2;



                            mbcount += add_mb(mvs + mbcount, mb_type, sx, sy, mx + sx, my + sy, direction);

                        }

                    } else if (IS_8X16(mb_type)) {

                        for (i = 0; i < 2; i++) {

                            int sx = mb_x * 16 + 4 + 8 * i;

                            int sy = mb_y * 16 + 8;

                            int xy = (mb_x * 2 + i + mb_y * 2 * mv_stride) << (mv_sample_log2 - 1);

                            int mx = motion_val[direction][xy][0] >> shift;

                            int my = motion_val[direction][xy][1] >> shift;



                            if (IS_INTERLACED(mb_type))

                                my *= 2;



                            mbcount += add_mb(mvs + mbcount, mb_type, sx, sy, mx + sx, my + sy, direction);

                        }

                    } else {

                          int sx = mb_x * 16 + 8;

                          int sy = mb_y * 16 + 8;

                          int xy = (mb_x + mb_y * mv_stride) << mv_sample_log2;

                          int mx = (motion_val[direction][xy][0]>>shift) + sx;

                          int my = (motion_val[direction][xy][1]>>shift) + sy;

                          mbcount += add_mb(mvs + mbcount, mb_type, sx, sy, mx, my, direction);

                    }

                }

            }

        }



        if (mbcount) {

            AVFrameSideData *sd;



            av_log(avctx, AV_LOG_DEBUG, "Adding %d MVs info to frame %d\n", mbcount, avctx->frame_number);

            sd = av_frame_new_side_data(pict, AV_FRAME_DATA_MOTION_VECTORS, mbcount * sizeof(AVMotionVector));

            if (!sd) {

                av_freep(&mvs);

                return;

            }

            memcpy(sd->data, mvs, mbcount * sizeof(AVMotionVector));

        }



        av_freep(&mvs);

    }



    /* TODO: export all the following to make them accessible for users (and filters) */

    if (avctx->hwaccel || !mbtype_table

#if FF_API_CAP_VDPAU

        || (avctx->codec->capabilities&AV_CODEC_CAP_HWACCEL_VDPAU)

#endif

        )

        return;





    if (avctx->debug & (FF_DEBUG_SKIP | FF_DEBUG_QP | FF_DEBUG_MB_TYPE)) {

        int x,y;



        av_log(avctx, AV_LOG_DEBUG, "New frame, type: %c\n",

               av_get_picture_type_char(pict->pict_type));

        for (y = 0; y < mb_height; y++) {

            for (x = 0; x < mb_width; x++) {

                if (avctx->debug & FF_DEBUG_SKIP) {

                    int count = mbskip_table ? mbskip_table[x + y * mb_stride] : 0;

                    if (count > 9)

                        count = 9;

                    av_log(avctx, AV_LOG_DEBUG, "%1d", count);

                }

                if (avctx->debug & FF_DEBUG_QP) {

                    av_log(avctx, AV_LOG_DEBUG, "%2d",

                           qscale_table[x + y * mb_stride]);

                }

                if (avctx->debug & FF_DEBUG_MB_TYPE) {

                    int mb_type = mbtype_table[x + y * mb_stride];

                    // Type & MV direction

                    if (IS_PCM(mb_type))

                        av_log(avctx, AV_LOG_DEBUG, "P");

                    else if (IS_INTRA(mb_type) && IS_ACPRED(mb_type))

                        av_log(avctx, AV_LOG_DEBUG, "A");

                    else if (IS_INTRA4x4(mb_type))

                        av_log(avctx, AV_LOG_DEBUG, "i");

                    else if (IS_INTRA16x16(mb_type))

                        av_log(avctx, AV_LOG_DEBUG, "I");

                    else if (IS_DIRECT(mb_type) && IS_SKIP(mb_type))

                        av_log(avctx, AV_LOG_DEBUG, "d");

                    else if (IS_DIRECT(mb_type))

                        av_log(avctx, AV_LOG_DEBUG, "D");

                    else if (IS_GMC(mb_type) && IS_SKIP(mb_type))

                        av_log(avctx, AV_LOG_DEBUG, "g");

                    else if (IS_GMC(mb_type))

                        av_log(avctx, AV_LOG_DEBUG, "G");

                    else if (IS_SKIP(mb_type))

                        av_log(avctx, AV_LOG_DEBUG, "S");

                    else if (!USES_LIST(mb_type, 1))

                        av_log(avctx, AV_LOG_DEBUG, ">");

                    else if (!USES_LIST(mb_type, 0))

                        av_log(avctx, AV_LOG_DEBUG, "<");

                    else {

                        av_assert2(USES_LIST(mb_type, 0) && USES_LIST(mb_type, 1));

                        av_log(avctx, AV_LOG_DEBUG, "X");

                    }



                    // segmentation

                    if (IS_8X8(mb_type))

                        av_log(avctx, AV_LOG_DEBUG, "+");

                    else if (IS_16X8(mb_type))

                        av_log(avctx, AV_LOG_DEBUG, "-");

                    else if (IS_8X16(mb_type))

                        av_log(avctx, AV_LOG_DEBUG, "|");

                    else if (IS_INTRA(mb_type) || IS_16X16(mb_type))

                        av_log(avctx, AV_LOG_DEBUG, " ");

                    else

                        av_log(avctx, AV_LOG_DEBUG, "?");





                    if (IS_INTERLACED(mb_type))

                        av_log(avctx, AV_LOG_DEBUG, "=");

                    else

                        av_log(avctx, AV_LOG_DEBUG, " ");

                }

            }

            av_log(avctx, AV_LOG_DEBUG, "\n");

        }

    }



    if ((avctx->debug & (FF_DEBUG_VIS_QP | FF_DEBUG_VIS_MB_TYPE)) ||

        (avctx->debug_mv)) {

        int mb_y;

        int i;

        int h_chroma_shift, v_chroma_shift, block_height;

#if FF_API_VISMV

        const int shift = 1 + quarter_sample;

        uint8_t *ptr;

        const int width          = avctx->width;

        const int height         = avctx->height;

#endif

        const int mv_sample_log2 = avctx->codec_id == AV_CODEC_ID_H264 || avctx->codec_id == AV_CODEC_ID_SVQ3 ? 2 : 1;

        const int mv_stride      = (mb_width << mv_sample_log2) +

                                   (avctx->codec->id == AV_CODEC_ID_H264 ? 0 : 1);



        *low_delay = 0; // needed to see the vectors without trashing the buffers



        avcodec_get_chroma_sub_sample(avctx->pix_fmt, &h_chroma_shift, &v_chroma_shift);



        av_frame_make_writable(pict);



        pict->opaque = NULL;

#if FF_API_VISMV

        ptr          = pict->data[0];

#endif

        block_height = 16 >> v_chroma_shift;



        for (mb_y = 0; mb_y < mb_height; mb_y++) {

            int mb_x;

            for (mb_x = 0; mb_x < mb_width; mb_x++) {

                const int mb_index = mb_x + mb_y * mb_stride;

#if FF_API_VISMV

                if ((avctx->debug_mv) && motion_val[0]) {

                    int type;

                    for (type = 0; type < 3; type++) {

                        int direction = 0;

                        switch (type) {

                        case 0:

                            if ((!(avctx->debug_mv & FF_DEBUG_VIS_MV_P_FOR)) ||

                                (pict->pict_type!= AV_PICTURE_TYPE_P))

                                continue;

                            direction = 0;

                            break;

                        case 1:

                            if ((!(avctx->debug_mv & FF_DEBUG_VIS_MV_B_FOR)) ||

                                (pict->pict_type!= AV_PICTURE_TYPE_B))

                                continue;

                            direction = 0;

                            break;

                        case 2:

                            if ((!(avctx->debug_mv & FF_DEBUG_VIS_MV_B_BACK)) ||

                                (pict->pict_type!= AV_PICTURE_TYPE_B))

                                continue;

                            direction = 1;

                            break;

                        }

                        if (!USES_LIST(mbtype_table[mb_index], direction))

                            continue;



                        if (IS_8X8(mbtype_table[mb_index])) {

                            int i;

                            for (i = 0; i < 4; i++) {

                                int sx = mb_x * 16 + 4 + 8 * (i & 1);

                                int sy = mb_y * 16 + 4 + 8 * (i >> 1);

                                int xy = (mb_x * 2 + (i & 1) +

                                          (mb_y * 2 + (i >> 1)) * mv_stride) << (mv_sample_log2 - 1);

                                int mx = (motion_val[direction][xy][0] >> shift) + sx;

                                int my = (motion_val[direction][xy][1] >> shift) + sy;

                                draw_arrow(ptr, sx, sy, mx, my, width,

                                           height, pict->linesize[0], 100, 0, direction);

                            }

                        } else if (IS_16X8(mbtype_table[mb_index])) {

                            int i;

                            for (i = 0; i < 2; i++) {

                                int sx = mb_x * 16 + 8;

                                int sy = mb_y * 16 + 4 + 8 * i;

                                int xy = (mb_x * 2 + (mb_y * 2 + i) * mv_stride) << (mv_sample_log2 - 1);

                                int mx = (motion_val[direction][xy][0] >> shift);

                                int my = (motion_val[direction][xy][1] >> shift);



                                if (IS_INTERLACED(mbtype_table[mb_index]))

                                    my *= 2;



                                draw_arrow(ptr, sx, sy, mx + sx, my + sy, width,

                                           height, pict->linesize[0], 100, 0, direction);

                            }

                        } else if (IS_8X16(mbtype_table[mb_index])) {

                            int i;

                            for (i = 0; i < 2; i++) {

                                int sx = mb_x * 16 + 4 + 8 * i;

                                int sy = mb_y * 16 + 8;

                                int xy = (mb_x * 2 + i + mb_y * 2 * mv_stride) << (mv_sample_log2 - 1);

                                int mx = motion_val[direction][xy][0] >> shift;

                                int my = motion_val[direction][xy][1] >> shift;



                                if (IS_INTERLACED(mbtype_table[mb_index]))

                                    my *= 2;



                                draw_arrow(ptr, sx, sy, mx + sx, my + sy, width,

                                           height, pict->linesize[0], 100, 0, direction);

                            }

                        } else {

                              int sx= mb_x * 16 + 8;

                              int sy= mb_y * 16 + 8;

                              int xy= (mb_x + mb_y * mv_stride) << mv_sample_log2;

                              int mx= (motion_val[direction][xy][0]>>shift) + sx;

                              int my= (motion_val[direction][xy][1]>>shift) + sy;

                              draw_arrow(ptr, sx, sy, mx, my, width, height, pict->linesize[0], 100, 0, direction);

                        }

                    }

                }

#endif

                if ((avctx->debug & FF_DEBUG_VIS_QP)) {

                    uint64_t c = (qscale_table[mb_index] * 128 / 31) *

                                 0x0101010101010101ULL;

                    int y;

                    for (y = 0; y < block_height; y++) {

                        *(uint64_t *)(pict->data[1] + 8 * mb_x +

                                      (block_height * mb_y + y) *

                                      pict->linesize[1]) = c;

                        *(uint64_t *)(pict->data[2] + 8 * mb_x +

                                      (block_height * mb_y + y) *

                                      pict->linesize[2]) = c;

                    }

                }

                if ((avctx->debug & FF_DEBUG_VIS_MB_TYPE) &&

                    motion_val[0]) {

                    int mb_type = mbtype_table[mb_index];

                    uint64_t u,v;

                    int y;

#define COLOR(theta, r) \

    u = (int)(128 + r * cos(theta * 3.141592 / 180)); \

    v = (int)(128 + r * sin(theta * 3.141592 / 180));





                    u = v = 128;

                    if (IS_PCM(mb_type)) {

                        COLOR(120, 48)

                    } else if ((IS_INTRA(mb_type) && IS_ACPRED(mb_type)) ||

                               IS_INTRA16x16(mb_type)) {

                        COLOR(30, 48)

                    } else if (IS_INTRA4x4(mb_type)) {

                        COLOR(90, 48)

                    } else if (IS_DIRECT(mb_type) && IS_SKIP(mb_type)) {

                        // COLOR(120, 48)

                    } else if (IS_DIRECT(mb_type)) {

                        COLOR(150, 48)

                    } else if (IS_GMC(mb_type) && IS_SKIP(mb_type)) {

                        COLOR(170, 48)

                    } else if (IS_GMC(mb_type)) {

                        COLOR(190, 48)

                    } else if (IS_SKIP(mb_type)) {

                        // COLOR(180, 48)

                    } else if (!USES_LIST(mb_type, 1)) {

                        COLOR(240, 48)

                    } else if (!USES_LIST(mb_type, 0)) {

                        COLOR(0, 48)

                    } else {

                        av_assert2(USES_LIST(mb_type, 0) && USES_LIST(mb_type, 1));

                        COLOR(300,48)

                    }



                    u *= 0x0101010101010101ULL;

                    v *= 0x0101010101010101ULL;

                    for (y = 0; y < block_height; y++) {

                        *(uint64_t *)(pict->data[1] + 8 * mb_x +

                                      (block_height * mb_y + y) * pict->linesize[1]) = u;

                        *(uint64_t *)(pict->data[2] + 8 * mb_x +

                                      (block_height * mb_y + y) * pict->linesize[2]) = v;

                    }



                    // segmentation

                    if (IS_8X8(mb_type) || IS_16X8(mb_type)) {

                        *(uint64_t *)(pict->data[0] + 16 * mb_x + 0 +

                                      (16 * mb_y + 8) * pict->linesize[0]) ^= 0x8080808080808080ULL;

                        *(uint64_t *)(pict->data[0] + 16 * mb_x + 8 +

                                      (16 * mb_y + 8) * pict->linesize[0]) ^= 0x8080808080808080ULL;

                    }

                    if (IS_8X8(mb_type) || IS_8X16(mb_type)) {

                        for (y = 0; y < 16; y++)

                            pict->data[0][16 * mb_x + 8 + (16 * mb_y + y) *

                                          pict->linesize[0]] ^= 0x80;

                    }

                    if (IS_8X8(mb_type) && mv_sample_log2 >= 2) {

                        int dm = 1 << (mv_sample_log2 - 2);

                        for (i = 0; i < 4; i++) {

                            int sx = mb_x * 16 + 8 * (i & 1);

                            int sy = mb_y * 16 + 8 * (i >> 1);

                            int xy = (mb_x * 2 + (i & 1) +

                                     (mb_y * 2 + (i >> 1)) * mv_stride) << (mv_sample_log2 - 1);

                            // FIXME bidir

                            int32_t *mv = (int32_t *) &motion_val[0][xy];

                            if (mv[0] != mv[dm] ||

                                mv[dm * mv_stride] != mv[dm * (mv_stride + 1)])

                                for (y = 0; y < 8; y++)

                                    pict->data[0][sx + 4 + (sy + y) * pict->linesize[0]] ^= 0x80;

                            if (mv[0] != mv[dm * mv_stride] || mv[dm] != mv[dm * (mv_stride + 1)])

                                *(uint64_t *)(pict->data[0] + sx + (sy + 4) *

                                              pict->linesize[0]) ^= 0x8080808080808080ULL;

                        }

                    }



                    if (IS_INTERLACED(mb_type) &&

                        avctx->codec->id == AV_CODEC_ID_H264) {

                        // hmm

                    }

                }

                if (mbskip_table)

                    mbskip_table[mb_index] = 0;

            }

        }

    }

}

static void alloc_picture(void *opaque)

{

    VideoState *is = opaque;

    VideoPicture *vp;



    vp = &is->pictq[is->pictq_windex];



    if (vp->bmp)

        SDL_FreeYUVOverlay(vp->bmp);



#if CONFIG_AVFILTER

    if (vp->picref)

        avfilter_unref_buffer(vp->picref);

    vp->picref = NULL;



    vp->width   = is->out_video_filter->inputs[0]->w;

    vp->height  = is->out_video_filter->inputs[0]->h;

    vp->pix_fmt = is->out_video_filter->inputs[0]->format;

#else

    vp->width   = is->video_st->codec->width;

    vp->height  = is->video_st->codec->height;

    vp->pix_fmt = is->video_st->codec->pix_fmt;

#endif



    vp->bmp = SDL_CreateYUVOverlay(vp->width, vp->height,

                                   SDL_YV12_OVERLAY,

                                   screen);











    SDL_LockMutex(is->pictq_mutex);

    vp->allocated = 1;

    SDL_CondSignal(is->pictq_cond);

    SDL_UnlockMutex(is->pictq_mutex);

static int decode_nal_unit(HEVCContext *s, const HEVCNAL *nal)

{

    HEVCLocalContext *lc = &s->HEVClc;

    GetBitContext *gb    = &lc->gb;

    int ctb_addr_ts, ret;



    ret = init_get_bits8(gb, nal->data, nal->size);

    if (ret < 0)

        return ret;



    ret = hls_nal_unit(s);

    if (ret < 0) {

        av_log(s->avctx, AV_LOG_ERROR, "Invalid NAL unit %d, skipping.\n",

               s->nal_unit_type);

        goto fail;

    } else if (!ret)

        return 0;



    switch (s->nal_unit_type) {

    case NAL_VPS:

        ret = ff_hevc_decode_nal_vps(gb, s->avctx, &s->ps);

        if (ret < 0)

            goto fail;

        break;

    case NAL_SPS:

        ret = ff_hevc_decode_nal_sps(gb, s->avctx, &s->ps,

                                     s->apply_defdispwin);

        if (ret < 0)

            goto fail;

        break;

    case NAL_PPS:

        ret = ff_hevc_decode_nal_pps(gb, s->avctx, &s->ps);

        if (ret < 0)

            goto fail;

        break;

    case NAL_SEI_PREFIX:

    case NAL_SEI_SUFFIX:

        ret = ff_hevc_decode_nal_sei(s);

        if (ret < 0)

            goto fail;

        break;

    case NAL_TRAIL_R:

    case NAL_TRAIL_N:

    case NAL_TSA_N:

    case NAL_TSA_R:

    case NAL_STSA_N:

    case NAL_STSA_R:

    case NAL_BLA_W_LP:

    case NAL_BLA_W_RADL:

    case NAL_BLA_N_LP:

    case NAL_IDR_W_RADL:

    case NAL_IDR_N_LP:

    case NAL_CRA_NUT:

    case NAL_RADL_N:

    case NAL_RADL_R:

    case NAL_RASL_N:

    case NAL_RASL_R:

        ret = hls_slice_header(s);

        if (ret < 0)

            return ret;



        if (s->max_ra == INT_MAX) {

            if (s->nal_unit_type == NAL_CRA_NUT || IS_BLA(s)) {

                s->max_ra = s->poc;

            } else {

                if (IS_IDR(s))

                    s->max_ra = INT_MIN;

            }

        }



        if ((s->nal_unit_type == NAL_RASL_R || s->nal_unit_type == NAL_RASL_N) &&

            s->poc <= s->max_ra) {

            s->is_decoded = 0;

            break;

        } else {

            if (s->nal_unit_type == NAL_RASL_R && s->poc > s->max_ra)

                s->max_ra = INT_MIN;

        }



        if (s->sh.first_slice_in_pic_flag) {

            ret = hevc_frame_start(s);

            if (ret < 0)

                return ret;

        } else if (!s->ref) {

            av_log(s->avctx, AV_LOG_ERROR, "First slice in a frame missing.\n");

            goto fail;

        }



        if (s->nal_unit_type != s->first_nal_type) {

            av_log(s->avctx, AV_LOG_ERROR,

                   "Non-matching NAL types of the VCL NALUs: %d %d\n",

                   s->first_nal_type, s->nal_unit_type);

            return AVERROR_INVALIDDATA;

        }



        if (!s->sh.dependent_slice_segment_flag &&

            s->sh.slice_type != I_SLICE) {

            ret = ff_hevc_slice_rpl(s);

            if (ret < 0) {

                av_log(s->avctx, AV_LOG_WARNING,

                       "Error constructing the reference lists for the current slice.\n");

                goto fail;

            }

        }



        if (s->sh.first_slice_in_pic_flag && s->avctx->hwaccel) {

            ret = s->avctx->hwaccel->start_frame(s->avctx, NULL, 0);

            if (ret < 0)

                goto fail;

        }



        if (s->avctx->hwaccel) {

            ret = s->avctx->hwaccel->decode_slice(s->avctx, nal->raw_data, nal->raw_size);

            if (ret < 0)

                goto fail;

        } else {

            ctb_addr_ts = hls_slice_data(s);

            if (ctb_addr_ts >= (s->ps.sps->ctb_width * s->ps.sps->ctb_height)) {

                s->is_decoded = 1;

                if ((s->ps.pps->transquant_bypass_enable_flag ||

                     (s->ps.sps->pcm.loop_filter_disable_flag && s->ps.sps->pcm_enabled_flag)) &&

                    s->ps.sps->sao_enabled)

                    restore_tqb_pixels(s);

            }



            if (ctb_addr_ts < 0) {

                ret = ctb_addr_ts;

                goto fail;

            }

        }

        break;

    case NAL_EOS_NUT:

    case NAL_EOB_NUT:

        s->seq_decode = (s->seq_decode + 1) & 0xff;

        s->max_ra     = INT_MAX;

        break;

    case NAL_AUD:

    case NAL_FD_NUT:

        break;

    default:

        av_log(s->avctx, AV_LOG_INFO,

               "Skipping NAL unit %d\n", s->nal_unit_type);

    }



    return 0;

fail:

    if (s->avctx->err_recognition & AV_EF_EXPLODE)

        return ret;

    return 0;

}

static inline int vc1_i_pred_dc(MpegEncContext *s, int overlap, int pq, int n,

                              int16_t **dc_val_ptr, int *dir_ptr)

{

    int a, b, c, wrap, pred, scale;

    int16_t *dc_val;

    static const uint16_t dcpred[32] = {

    -1, 1024,  512,  341,  256,  205,  171,  146,  128,

         114,  102,   93,   85,   79,   73,   68,   64,

          60,   57,   54,   51,   49,   47,   45,   43,

          41,   39,   38,   37,   35,   34,   33

    };



    /* find prediction - wmv3_dc_scale always used here in fact */

    if (n < 4)     scale = s->y_dc_scale;

    else           scale = s->c_dc_scale;



    wrap = s->block_wrap[n];

    dc_val= s->dc_val[0] + s->block_index[n];



    /* B A

     * C X

     */

    c = dc_val[ - 1];

    b = dc_val[ - 1 - wrap];

    a = dc_val[ - wrap];



    if (pq < 9 || !overlap)

    {

        /* Set outer values */

        if (!s->mb_y && (n!=2 && n!=3)) b=a=dcpred[scale];

        if (s->mb_x == 0 && (n!=1 && n!=3)) b=c=dcpred[scale];

    }

    else

    {

        /* Set outer values */

        if (!s->mb_y && (n!=2 && n!=3)) b=a=0;

        if (s->mb_x == 0 && (n!=1 && n!=3)) b=c=0;

    }



    if (abs(a - b) <= abs(b - c)) {

        pred = c;

        *dir_ptr = 1;//left

    } else {

        pred = a;

        *dir_ptr = 0;//top

    }



    /* update predictor */

    *dc_val_ptr = &dc_val[0];

    return pred;

}

void rgb24toyv12_c(const uint8_t *src, uint8_t *ydst, uint8_t *udst,

                   uint8_t *vdst, int width, int height, int lumStride,

                   int chromStride, int srcStride)

{

    int y;

    const int chromWidth = width >> 1;



    for (y = 0; y < height; y += 2) {

        int i;

        for (i = 0; i < chromWidth; i++) {

            unsigned int b = src[6 * i + 0];

            unsigned int g = src[6 * i + 1];

            unsigned int r = src[6 * i + 2];



            unsigned int Y = ((RY * r + GY * g + BY * b) >> RGB2YUV_SHIFT) +  16;

            unsigned int V = ((RV * r + GV * g + BV * b) >> RGB2YUV_SHIFT) + 128;

            unsigned int U = ((RU * r + GU * g + BU * b) >> RGB2YUV_SHIFT) + 128;



            udst[i]     = U;

            vdst[i]     = V;

            ydst[2 * i] = Y;



            b = src[6 * i + 3];

            g = src[6 * i + 4];

            r = src[6 * i + 5];



            Y = ((RY * r + GY * g + BY * b) >> RGB2YUV_SHIFT) + 16;

            ydst[2 * i + 1] = Y;

        }

        ydst += lumStride;

        src  += srcStride;



        if (y+1 == height)

            break;



        for (i = 0; i < chromWidth; i++) {

            unsigned int b = src[6 * i + 0];

            unsigned int g = src[6 * i + 1];

            unsigned int r = src[6 * i + 2];



            unsigned int Y = ((RY * r + GY * g + BY * b) >> RGB2YUV_SHIFT) + 16;



            ydst[2 * i] = Y;



            b = src[6 * i + 3];

            g = src[6 * i + 4];

            r = src[6 * i + 5];



            Y = ((RY * r + GY * g + BY * b) >> RGB2YUV_SHIFT) + 16;

            ydst[2 * i + 1] = Y;

        }

        udst += chromStride;

        vdst += chromStride;

        ydst += lumStride;

        src  += srcStride;

    }

}

static void sdp_parse_fmtp_config(AVCodecContext *codec, char *attr, char *value)

{

    switch (codec->codec_id) {

        case CODEC_ID_MPEG4:

        case CODEC_ID_AAC:

            if (!strcmp(attr, "config")) {

                /* decode the hexa encoded parameter */

                int len = hex_to_data(NULL, value);



                codec->extradata = av_mallocz(len + FF_INPUT_BUFFER_PADDING_SIZE);

                if (!codec->extradata)

                    return;

                codec->extradata_size = len;

                hex_to_data(codec->extradata, value);

            }

            break;

        default:

            break;

    }

    return;

}

static int mp3_header_decompress(AVBitStreamFilterContext *bsfc, AVCodecContext *avctx, const char *args,

                     uint8_t **poutbuf, int *poutbuf_size,

                     const uint8_t *buf, int buf_size, int keyframe){

    uint32_t header;

    int sample_rate= avctx->sample_rate;

    int sample_rate_index=0;

    int lsf, mpeg25, bitrate_index, frame_size;



    header = (buf[0] << 24) | (buf[1] << 16) | (buf[2] << 8) | buf[3];

    if(ff_mpa_check_header(header) >= 0){

        *poutbuf= (uint8_t *) buf;

        *poutbuf_size= buf_size;



        return 0;

    }



    header= 0xFFE00000 | ((4-3)<<17) | (1<<16); //FIXME simplify



    lsf     = sample_rate < (24000+32000)/2;

    mpeg25  = sample_rate < (12000+16000)/2;

    header |= (!mpeg25)<<20;

    header |= (!lsf   )<<19;

    if(sample_rate<<(lsf+mpeg25) < (44100+32000)/2)

        sample_rate_index |= 2;

    else if(sample_rate<<(lsf+mpeg25) > (44100+48000)/2)

        sample_rate_index |= 1;



    header |= sample_rate_index<<10;

    sample_rate= mpa_freq_tab[sample_rate_index] >> (lsf + mpeg25); //in case sample rate is a little off



    for(bitrate_index=2; bitrate_index<30; bitrate_index++){

        frame_size = mpa_bitrate_tab[lsf][2][bitrate_index>>1];

        frame_size = (frame_size * 144000) / (sample_rate << lsf) + (bitrate_index&1);

        if(frame_size == buf_size + 4)

            break;

    }

    if(bitrate_index == 30){

        av_log(avctx, AV_LOG_ERROR, "couldnt find bitrate_index\n");

        return -1;

    }



    header |= (bitrate_index&1)<<9;

    header |= (bitrate_index>>1)<<12;

    header |= (avctx->channels==1 ? MPA_MONO : MPA_JSTEREO)<<6;



    *poutbuf_size= buf_size + 4;

    *poutbuf= av_malloc(buf_size + 4 + FF_INPUT_BUFFER_PADDING_SIZE);

    memcpy(*poutbuf + 4, buf, buf_size + FF_INPUT_BUFFER_PADDING_SIZE);



    if(avctx->channels==2){

        if(lsf){

            FFSWAP(int, (*poutbuf)[5], (*poutbuf)[6]);

            header |= ((*poutbuf)[5] & 0xC0)>>2;

        }else{

            header |= (*poutbuf)[5] & 0x30;

        }

    }



    (*poutbuf)[0]= header>>24;

    (*poutbuf)[1]= header>>16;

    (*poutbuf)[2]= header>> 8;

    (*poutbuf)[3]= header    ;



    return 1;

}

static int get_cod(Jpeg2000DecoderContext *s, Jpeg2000CodingStyle *c,

                   uint8_t *properties)

{

    Jpeg2000CodingStyle tmp;

    int compno;



    if (s->buf_end - s->buf < 5)

        return AVERROR(EINVAL);



    tmp.log2_prec_width  =

    tmp.log2_prec_height = 15;



    tmp.csty = bytestream_get_byte(&s->buf);



    // get progression order

    tmp.prog_order = bytestream_get_byte(&s->buf);



    tmp.nlayers = bytestream_get_be16(&s->buf);

    tmp.mct     = bytestream_get_byte(&s->buf); // multiple component transformation



    get_cox(s, &tmp);

    for (compno = 0; compno < s->ncomponents; compno++)

        if (!(properties[compno] & HAD_COC))

            memcpy(c + compno, &tmp, sizeof(tmp));

    return 0;

}

static int32_t scalarproduct_and_madd_int16_c(int16_t *v1, const int16_t *v2,

                                              const int16_t *v3,

                                              int order, int mul)

{

    int res = 0;



    while (order--) {

        res   += *v1 * *v2++;

        *v1++ += mul * *v3++;

    }

    return res;

}

static int avi_read_header(AVFormatContext *s, AVFormatParameters *ap)

{

    AVIContext *avi = s->priv_data;

    ByteIOContext *pb = &s->pb;

    uint32_t tag, tag1, handler;

    int codec_type, stream_index, frame_period, bit_rate;

    unsigned int size, nb_frames;

    int i, n;

    AVStream *st;

    AVIStream *ast = NULL;

    int xan_video = 0;  /* hack to support Xan A/V */

    char str_track[4];



    avi->stream_index= -1;



    if (get_riff(avi, pb) < 0)

        return -1;



    /* first list tag */

    stream_index = -1;

    codec_type = -1;

    frame_period = 0;

    for(;;) {

        if (url_feof(pb))

            goto fail;

        tag = get_le32(pb);

        size = get_le32(pb);

#ifdef DEBUG

        print_tag("tag", tag, size);

#endif



        switch(tag) {

        case MKTAG('L', 'I', 'S', 'T'):

            /* ignored, except when start of video packets */

            tag1 = get_le32(pb);

#ifdef DEBUG

            print_tag("list", tag1, 0);

#endif

            if (tag1 == MKTAG('m', 'o', 'v', 'i')) {

                avi->movi_list = url_ftell(pb) - 4;

                if(size) avi->movi_end = avi->movi_list + size + (size & 1);

                else     avi->movi_end = url_fsize(pb);

#ifdef DEBUG

                printf("movi end=%"PRIx64"\n", avi->movi_end);

#endif

                goto end_of_header;

            }

            break;

        case MKTAG('d', 'm', 'l', 'h'):

            avi->is_odml = 1;

            url_fskip(pb, size + (size & 1));

            break;

        case MKTAG('a', 'v', 'i', 'h'):

            /* avi header */

            /* using frame_period is bad idea */

            frame_period = get_le32(pb);

            bit_rate = get_le32(pb) * 8;

            get_le32(pb);

            avi->non_interleaved |= get_le32(pb) & AVIF_MUSTUSEINDEX;



            url_fskip(pb, 2 * 4);

            n = get_le32(pb);

            for(i=0;i<n;i++) {

                AVIStream *ast;

                st = av_new_stream(s, i);

                if (!st)

                    goto fail;



                ast = av_mallocz(sizeof(AVIStream));

                if (!ast)

                    goto fail;

                st->priv_data = ast;

            }

            url_fskip(pb, size - 7 * 4);

            break;

        case MKTAG('s', 't', 'r', 'h'):

            /* stream header */

            stream_index++;

            tag1 = get_le32(pb);

            handler = get_le32(pb); /* codec tag */

#ifdef DEBUG

            print_tag("strh", tag1, -1);

#endif

            if(tag1 == MKTAG('i', 'a', 'v', 's') || tag1 == MKTAG('i', 'v', 'a', 's')){

                /*

                 * After some consideration -- I don't think we

                 * have to support anything but DV in a type1 AVIs.

                 */

                if (s->nb_streams != 1)

                    goto fail;



                if (handler != MKTAG('d', 'v', 's', 'd') &&

                    handler != MKTAG('d', 'v', 'h', 'd') &&

                    handler != MKTAG('d', 'v', 's', 'l'))

                   goto fail;



                ast = s->streams[0]->priv_data;

                av_freep(&s->streams[0]->codec->extradata);

                av_freep(&s->streams[0]);

                s->nb_streams = 0;

                if (ENABLE_DV_DEMUXER) {

                    avi->dv_demux = dv_init_demux(s);

                    if (!avi->dv_demux)

                        goto fail;

                }

                s->streams[0]->priv_data = ast;

                url_fskip(pb, 3 * 4);

                ast->scale = get_le32(pb);

                ast->rate = get_le32(pb);

                stream_index = s->nb_streams - 1;

                url_fskip(pb, size - 7*4);

                break;

            }



            if (stream_index >= s->nb_streams) {

                url_fskip(pb, size - 8);

                /* ignore padding stream */

                if (tag1 == MKTAG('p', 'a', 'd', 's'))

                    stream_index--;

                break;

            }

            st = s->streams[stream_index];

            ast = st->priv_data;

            st->codec->stream_codec_tag= handler;



            get_le32(pb); /* flags */

            get_le16(pb); /* priority */

            get_le16(pb); /* language */

            get_le32(pb); /* initial frame */

            ast->scale = get_le32(pb);

            ast->rate = get_le32(pb);

            if(ast->scale && ast->rate){

            }else if(frame_period){

                ast->rate = 1000000;

                ast->scale = frame_period;

            }else{

                ast->rate = 25;

                ast->scale = 1;

            }

            av_set_pts_info(st, 64, ast->scale, ast->rate);



            ast->cum_len=get_le32(pb); /* start */

            nb_frames = get_le32(pb);



            st->start_time = 0;

            st->duration = nb_frames;

            get_le32(pb); /* buffer size */

            get_le32(pb); /* quality */

            ast->sample_size = get_le32(pb); /* sample ssize */

            ast->cum_len *= FFMAX(1, ast->sample_size);

//            av_log(NULL, AV_LOG_DEBUG, "%d %d %d %d\n", ast->rate, ast->scale, ast->start, ast->sample_size);



            switch(tag1) {

            case MKTAG('v', 'i', 'd', 's'):

                codec_type = CODEC_TYPE_VIDEO;



                ast->sample_size = 0;

                break;

            case MKTAG('a', 'u', 'd', 's'):

                codec_type = CODEC_TYPE_AUDIO;

                break;

            case MKTAG('t', 'x', 't', 's'):

                //FIXME

                codec_type = CODEC_TYPE_DATA; //CODEC_TYPE_SUB ?  FIXME

                break;

            case MKTAG('p', 'a', 'd', 's'):

                codec_type = CODEC_TYPE_UNKNOWN;

                stream_index--;

                break;

            default:

                av_log(s, AV_LOG_ERROR, "unknown stream type %X\n", tag1);

                goto fail;

            }

            ast->frame_offset= ast->cum_len;

            url_fskip(pb, size - 12 * 4);

            break;

        case MKTAG('s', 't', 'r', 'f'):

            /* stream header */

            if (stream_index >= s->nb_streams || avi->dv_demux) {

                url_fskip(pb, size);

            } else {

                st = s->streams[stream_index];

                switch(codec_type) {

                case CODEC_TYPE_VIDEO:

                    get_le32(pb); /* size */

                    st->codec->width = get_le32(pb);

                    st->codec->height = get_le32(pb);

                    get_le16(pb); /* panes */

                    st->codec->bits_per_sample= get_le16(pb); /* depth */

                    tag1 = get_le32(pb);

                    get_le32(pb); /* ImageSize */

                    get_le32(pb); /* XPelsPerMeter */

                    get_le32(pb); /* YPelsPerMeter */

                    get_le32(pb); /* ClrUsed */

                    get_le32(pb); /* ClrImportant */



                    if(size > 10*4 && size<(1<<30)){

                        st->codec->extradata_size= size - 10*4;

                        st->codec->extradata= av_malloc(st->codec->extradata_size + FF_INPUT_BUFFER_PADDING_SIZE);

                        get_buffer(pb, st->codec->extradata, st->codec->extradata_size);

                    }



                    if(st->codec->extradata_size & 1) //FIXME check if the encoder really did this correctly

                        get_byte(pb);



                    /* Extract palette from extradata if bpp <= 8 */

                    /* This code assumes that extradata contains only palette */

                    /* This is true for all paletted codecs implemented in ffmpeg */

                    if (st->codec->extradata_size && (st->codec->bits_per_sample <= 8)) {

                        st->codec->palctrl = av_mallocz(sizeof(AVPaletteControl));

#ifdef WORDS_BIGENDIAN

                        for (i = 0; i < FFMIN(st->codec->extradata_size, AVPALETTE_SIZE)/4; i++)

                            st->codec->palctrl->palette[i] = bswap_32(((uint32_t*)st->codec->extradata)[i]);

#else

                        memcpy(st->codec->palctrl->palette, st->codec->extradata,

                               FFMIN(st->codec->extradata_size, AVPALETTE_SIZE));

#endif

                        st->codec->palctrl->palette_changed = 1;

                    }



#ifdef DEBUG

                    print_tag("video", tag1, 0);

#endif

                    st->codec->codec_type = CODEC_TYPE_VIDEO;

                    st->codec->codec_tag = tag1;

                    st->codec->codec_id = codec_get_id(codec_bmp_tags, tag1);

                    if (st->codec->codec_id == CODEC_ID_XAN_WC4)

                        xan_video = 1;

                    st->need_parsing = 2; //only parse headers dont do slower repacketization, this is needed to get the pict type which is needed for generating correct pts

//                    url_fskip(pb, size - 5 * 4);

                    break;

                case CODEC_TYPE_AUDIO:

                    get_wav_header(pb, st->codec, size);

                    if(ast->sample_size && st->codec->block_align && ast->sample_size % st->codec->block_align)

                        av_log(s, AV_LOG_DEBUG, "invalid sample size or block align detected\n");

                    if (size%2) /* 2-aligned (fix for Stargate SG-1 - 3x18 - Shades of Grey.avi) */

                        url_fskip(pb, 1);

                    /* special case time: To support Xan DPCM, hardcode

                     * the format if Xxan is the video codec */

                    st->need_parsing = 1;

                    /* ADTS header is in extradata, AAC without header must be stored as exact frames, parser not needed and it will fail */

                    if (st->codec->codec_id == CODEC_ID_AAC && st->codec->extradata_size)

                        st->need_parsing = 0;

                    /* force parsing as several audio frames can be in

                       one packet */

                    if (xan_video)

                        st->codec->codec_id = CODEC_ID_XAN_DPCM;

                    break;

                default:

                    st->codec->codec_type = CODEC_TYPE_DATA;

                    st->codec->codec_id= CODEC_ID_NONE;

                    st->codec->codec_tag= 0;

                    url_fskip(pb, size);

                    break;

                }

            }

            break;

        case MKTAG('i', 'n', 'd', 'x'):

            i= url_ftell(pb);

            if(!url_is_streamed(pb) && !(s->flags & AVFMT_FLAG_IGNIDX)){

                read_braindead_odml_indx(s, 0);

            }

            url_fseek(pb, i+size, SEEK_SET);

            break;

        case MKTAG('I', 'N', 'A', 'M'):

            avi_read_tag(pb, s->title, sizeof(s->title), size);

            break;

        case MKTAG('I', 'A', 'R', 'T'):

            avi_read_tag(pb, s->author, sizeof(s->author), size);

            break;

        case MKTAG('I', 'C', 'O', 'P'):

            avi_read_tag(pb, s->copyright, sizeof(s->copyright), size);

            break;

        case MKTAG('I', 'C', 'M', 'T'):

            avi_read_tag(pb, s->comment, sizeof(s->comment), size);

            break;

        case MKTAG('I', 'G', 'N', 'R'):

            avi_read_tag(pb, s->genre, sizeof(s->genre), size);

            break;

        case MKTAG('I', 'P', 'R', 'D'):

            avi_read_tag(pb, s->album, sizeof(s->album), size);

            break;

        case MKTAG('I', 'P', 'R', 'T'):

            avi_read_tag(pb, str_track, sizeof(str_track), size);

            sscanf(str_track, "%d", &s->track);

            break;

        default:

            /* skip tag */

            size += (size & 1);

            url_fskip(pb, size);

            break;

        }

    }

 end_of_header:

    /* check stream number */

    if (stream_index != s->nb_streams - 1) {

    fail:

        for(i=0;i<s->nb_streams;i++) {

            av_freep(&s->streams[i]->codec->extradata);

            av_freep(&s->streams[i]);

        }

        return -1;

    }



    if(!avi->index_loaded && !url_is_streamed(pb))

        avi_load_index(s);

    avi->index_loaded = 1;

    avi->non_interleaved |= guess_ni_flag(s);

    if(avi->non_interleaved)

        clean_index(s);



    return 0;

}

static int ffserver_parse_config_feed(FFServerConfig *config, const char *cmd, const char **p,

                                      FFServerStream **pfeed)

{

    FFServerStream *feed;

    char arg[1024];

    av_assert0(pfeed);

    feed = *pfeed;

    if (!av_strcasecmp(cmd, "<Feed")) {

        char *q;

        FFServerStream *s;

        feed = av_mallocz(sizeof(FFServerStream));

        if (!feed)

            return AVERROR(ENOMEM);

        ffserver_get_arg(feed->filename, sizeof(feed->filename), p);

        q = strrchr(feed->filename, '>');

        if (*q)

            *q = '\0';



        for (s = config->first_feed; s; s = s->next) {

            if (!strcmp(feed->filename, s->filename))

                ERROR("Feed '%s' already registered\n", s->filename);

        }



        feed->fmt = av_guess_format("ffm", NULL, NULL);

        /* default feed file */

        snprintf(feed->feed_filename, sizeof(feed->feed_filename),

                 "/tmp/%s.ffm", feed->filename);

        feed->feed_max_size = 5 * 1024 * 1024;

        feed->is_feed = 1;

        feed->feed = feed; /* self feeding :-) */

        *pfeed = feed;

        return 0;

    }

    av_assert0(feed);

    if (!av_strcasecmp(cmd, "Launch")) {

        int i;



        feed->child_argv = av_mallocz(64 * sizeof(char *));

        if (!feed->child_argv)

            return AVERROR(ENOMEM);

        for (i = 0; i < 62; i++) {

            ffserver_get_arg(arg, sizeof(arg), p);

            if (!arg[0])

                break;



            feed->child_argv[i] = av_strdup(arg);

            if (!feed->child_argv[i])

                return AVERROR(ENOMEM);

        }



        feed->child_argv[i] =

            av_asprintf("http://%s:%d/%s",

                        (config->http_addr.sin_addr.s_addr == INADDR_ANY) ? "127.0.0.1" :

                        inet_ntoa(config->http_addr.sin_addr), ntohs(config->http_addr.sin_port),

                        feed->filename);

        if (!feed->child_argv[i])

            return AVERROR(ENOMEM);

    } else if (!av_strcasecmp(cmd, "ACL")) {

        ffserver_parse_acl_row(NULL, feed, NULL, *p, config->filename,

                config->line_num);

    } else if (!av_strcasecmp(cmd, "File") || !av_strcasecmp(cmd, "ReadOnlyFile")) {

        ffserver_get_arg(feed->feed_filename, sizeof(feed->feed_filename), p);

        feed->readonly = !av_strcasecmp(cmd, "ReadOnlyFile");

    } else if (!av_strcasecmp(cmd, "Truncate")) {

        ffserver_get_arg(arg, sizeof(arg), p);

        /* assume Truncate is true in case no argument is specified */

        if (!arg[0]) {

            feed->truncate = 1;

        } else {

            WARNING("Truncate N syntax in configuration file is deprecated, "

                    "use Truncate alone with no arguments\n");

            feed->truncate = strtod(arg, NULL);

        }

    } else if (!av_strcasecmp(cmd, "FileMaxSize")) {

        char *p1;

        double fsize;



        ffserver_get_arg(arg, sizeof(arg), p);

        p1 = arg;

        fsize = strtod(p1, &p1);

        switch(av_toupper(*p1)) {

        case 'K':

            fsize *= 1024;

            break;

        case 'M':

            fsize *= 1024 * 1024;

            break;

        case 'G':

            fsize *= 1024 * 1024 * 1024;

            break;

        default:

            ERROR("Invalid file size: %s\n", arg);

            break;

        }

        feed->feed_max_size = (int64_t)fsize;

        if (feed->feed_max_size < FFM_PACKET_SIZE*4)

            ERROR("Feed max file size is too small, must be at least %d\n",

                    FFM_PACKET_SIZE*4);

    } else if (!av_strcasecmp(cmd, "</Feed>")) {

        *pfeed = NULL;

    } else {

        ERROR("Invalid entry '%s' inside <Feed></Feed>\n", cmd);

    }

    return 0;

}

static void build_feed_streams(void)

{

    FFServerStream *stream, *feed;

    int i;



    /* gather all streams */

    for(stream = config.first_stream; stream; stream = stream->next) {

        feed = stream->feed;

        if (feed) {

            if (stream->is_feed) {

                for(i=0;i<stream->nb_streams;i++)

                    stream->feed_streams[i] = i;

            } else {

                /* we handle a stream coming from a feed */

                for(i=0;i<stream->nb_streams;i++)

                    stream->feed_streams[i] = add_av_stream(feed,

                                                            stream->streams[i]);

            }

        }

    }



    /* create feed files if needed */

    for(feed = config.first_feed; feed; feed = feed->next_feed) {

        int fd;



        if (avio_check(feed->feed_filename, AVIO_FLAG_READ) > 0) {

            /* See if it matches */

            AVFormatContext *s = NULL;

            int matches = 0;



            if (avformat_open_input(&s, feed->feed_filename, NULL, NULL) >= 0) {

                /* set buffer size */

                ffio_set_buf_size(s->pb, FFM_PACKET_SIZE);

                /* Now see if it matches */

                if (s->nb_streams == feed->nb_streams) {

                    matches = 1;

                    for(i=0;i<s->nb_streams;i++) {

                        AVStream *sf, *ss;

                        sf = feed->streams[i];

                        ss = s->streams[i];



                        if (sf->index != ss->index ||

                            sf->id != ss->id) {

                            http_log("Index & Id do not match for stream %d (%s)\n",

                                   i, feed->feed_filename);

                            matches = 0;

                        } else {

                            AVCodecContext *ccf, *ccs;



                            ccf = sf->codec;

                            ccs = ss->codec;

#define CHECK_CODEC(x)  (ccf->x != ccs->x)



                            if (CHECK_CODEC(codec_id) || CHECK_CODEC(codec_type)) {

                                http_log("Codecs do not match for stream %d\n", i);

                                matches = 0;

                            } else if (CHECK_CODEC(bit_rate) || CHECK_CODEC(flags)) {

                                http_log("Codec bitrates do not match for stream %d\n", i);

                                matches = 0;

                            } else if (ccf->codec_type == AVMEDIA_TYPE_VIDEO) {

                                if (CHECK_CODEC(time_base.den) ||

                                    CHECK_CODEC(time_base.num) ||

                                    CHECK_CODEC(width) ||

                                    CHECK_CODEC(height)) {

                                    http_log("Codec width, height and framerate do not match for stream %d\n", i);

                                    matches = 0;

                                }

                            } else if (ccf->codec_type == AVMEDIA_TYPE_AUDIO) {

                                if (CHECK_CODEC(sample_rate) ||

                                    CHECK_CODEC(channels) ||

                                    CHECK_CODEC(frame_size)) {

                                    http_log("Codec sample_rate, channels, frame_size do not match for stream %d\n", i);

                                    matches = 0;

                                }

                            } else {

                                http_log("Unknown codec type\n");

                                matches = 0;

                            }

                        }

                        if (!matches)

                            break;

                    }

                } else

                    http_log("Deleting feed file '%s' as stream counts differ (%d != %d)\n",

                        feed->feed_filename, s->nb_streams, feed->nb_streams);



                avformat_close_input(&s);

            } else

                http_log("Deleting feed file '%s' as it appears to be corrupt\n",

                        feed->feed_filename);



            if (!matches) {

                if (feed->readonly) {

                    http_log("Unable to delete feed file '%s' as it is marked readonly\n",

                        feed->feed_filename);

                    exit(1);

                }

                unlink(feed->feed_filename);

            }

        }

        if (avio_check(feed->feed_filename, AVIO_FLAG_WRITE) <= 0) {

            AVFormatContext *s = avformat_alloc_context();



            if (!s) {

                http_log("Failed to allocate context\n");

                exit(1);

            }



            if (feed->readonly) {

                http_log("Unable to create feed file '%s' as it is marked readonly\n",

                    feed->feed_filename);

                exit(1);

            }



            /* only write the header of the ffm file */

            if (avio_open(&s->pb, feed->feed_filename, AVIO_FLAG_WRITE) < 0) {

                http_log("Could not open output feed file '%s'\n",

                         feed->feed_filename);

                exit(1);

            }

            s->oformat = feed->fmt;

            s->nb_streams = feed->nb_streams;

            s->streams = feed->streams;

            if (avformat_write_header(s, NULL) < 0) {

                http_log("Container doesn't support the required parameters\n");

                exit(1);

            }

            /* XXX: need better API */

            av_freep(&s->priv_data);

            avio_closep(&s->pb);

            s->streams = NULL;

            s->nb_streams = 0;

            avformat_free_context(s);

        }

        /* get feed size and write index */

        fd = open(feed->feed_filename, O_RDONLY);

        if (fd < 0) {

            http_log("Could not open output feed file '%s'\n",

                    feed->feed_filename);

            exit(1);

        }



        feed->feed_write_index = FFMAX(ffm_read_write_index(fd), FFM_PACKET_SIZE);

        feed->feed_size = lseek(fd, 0, SEEK_END);

        /* ensure that we do not wrap before the end of file */

        if (feed->feed_max_size && feed->feed_max_size < feed->feed_size)

            feed->feed_max_size = feed->feed_size;



        close(fd);

    }

}

static int mjpeg_decode_dht(MJpegDecodeContext *s)

{

    int len, index, i, class, n, v, code_max;

    uint8_t bits_table[17];

    uint8_t val_table[256];



    len = get_bits(&s->gb, 16) - 2;



    while (len > 0) {

        if (len < 17)

            return -1;

        class = get_bits(&s->gb, 4);

        if (class >= 2)

            return -1;

        index = get_bits(&s->gb, 4);

        if (index >= 4)

            return -1;

        n = 0;

        for(i=1;i<=16;i++) {

            bits_table[i] = get_bits(&s->gb, 8);

            n += bits_table[i];

        }

        len -= 17;

        if (len < n || n > 256)

            return -1;



        code_max = 0;

        for(i=0;i<n;i++) {

            v = get_bits(&s->gb, 8);

            if (v > code_max)

                code_max = v;

            val_table[i] = v;

        }

        len -= n;



        /* build VLC and flush previous vlc if present */

        free_vlc(&s->vlcs[class][index]);

        dprintf("class=%d index=%d nb_codes=%d\n",

               class, index, code_max + 1);

        build_vlc(&s->vlcs[class][index], bits_table, val_table, code_max + 1);

    }

    return 0;

}

int ff_mov_read_stsd_entries(MOVContext *c, AVIOContext *pb, int entries)

{

    AVStream *st;

    MOVStreamContext *sc;

    int j, pseudo_stream_id;



    if (c->fc->nb_streams < 1)

        return 0;

    st = c->fc->streams[c->fc->nb_streams-1];

    sc = st->priv_data;



    for (pseudo_stream_id=0; pseudo_stream_id<entries; pseudo_stream_id++) {

        //Parsing Sample description table

        enum AVCodecID id;

        int dref_id = 1;

        MOVAtom a = { AV_RL32("stsd") };

        int64_t start_pos = avio_tell(pb);

        int size = avio_rb32(pb); /* size */

        uint32_t format = avio_rl32(pb); /* data format */



        if (size >= 16) {

            avio_rb32(pb); /* reserved */

            avio_rb16(pb); /* reserved */

            dref_id = avio_rb16(pb);

        }



        if (st->codec->codec_tag &&

            st->codec->codec_tag != format &&

            (c->fc->video_codec_id ? ff_codec_get_id(ff_codec_movvideo_tags, format) != c->fc->video_codec_id

                                   : st->codec->codec_tag != MKTAG('j','p','e','g'))

           ){

            /* Multiple fourcc, we skip JPEG. This is not correct, we should

             * export it as a separate AVStream but this needs a few changes

             * in the MOV demuxer, patch welcome. */

        multiple_stsd:

            av_log(c->fc, AV_LOG_WARNING, "multiple fourcc not supported\n");

            avio_skip(pb, size - (avio_tell(pb) - start_pos));

            continue;

        }

        /* we cannot demux concatenated h264 streams because of different extradata */

        if (st->codec->codec_tag && st->codec->codec_tag == AV_RL32("avc1"))

            goto multiple_stsd;

        sc->pseudo_stream_id = st->codec->codec_tag ? -1 : pseudo_stream_id;

        sc->dref_id= dref_id;



        st->codec->codec_tag = format;

        id = ff_codec_get_id(ff_codec_movaudio_tags, format);

        if (id<=0 && ((format&0xFFFF) == 'm'+('s'<<8) || (format&0xFFFF) == 'T'+('S'<<8)))

            id = ff_codec_get_id(ff_codec_wav_tags, av_bswap32(format)&0xFFFF);



        if (st->codec->codec_type != AVMEDIA_TYPE_VIDEO && id > 0) {

            st->codec->codec_type = AVMEDIA_TYPE_AUDIO;

        } else if (st->codec->codec_type != AVMEDIA_TYPE_AUDIO && /* do not overwrite codec type */

                   format && format != MKTAG('m','p','4','s')) { /* skip old asf mpeg4 tag */

            id = ff_codec_get_id(ff_codec_movvideo_tags, format);

            if (id <= 0)

                id = ff_codec_get_id(ff_codec_bmp_tags, format);

            if (id > 0)

                st->codec->codec_type = AVMEDIA_TYPE_VIDEO;

            else if (st->codec->codec_type == AVMEDIA_TYPE_DATA){

                id = ff_codec_get_id(ff_codec_movsubtitle_tags, format);

                if (id > 0)

                    st->codec->codec_type = AVMEDIA_TYPE_SUBTITLE;

            }

        }



        av_dlog(c->fc, "size=%d 4CC= %c%c%c%c codec_type=%d\n", size,

                (format >> 0) & 0xff, (format >> 8) & 0xff, (format >> 16) & 0xff,

                (format >> 24) & 0xff, st->codec->codec_type);



        if (st->codec->codec_type==AVMEDIA_TYPE_VIDEO) {

            unsigned int color_depth, len;

            int color_greyscale;

            int color_table_id;



            st->codec->codec_id = id;

            avio_rb16(pb); /* version */

            avio_rb16(pb); /* revision level */

            avio_rb32(pb); /* vendor */

            avio_rb32(pb); /* temporal quality */

            avio_rb32(pb); /* spatial quality */



            st->codec->width = avio_rb16(pb); /* width */

            st->codec->height = avio_rb16(pb); /* height */



            avio_rb32(pb); /* horiz resolution */

            avio_rb32(pb); /* vert resolution */

            avio_rb32(pb); /* data size, always 0 */

            avio_rb16(pb); /* frames per samples */



            len = avio_r8(pb); /* codec name, pascal string */

            if (len > 31)

                len = 31;

            mov_read_mac_string(c, pb, len, st->codec->codec_name, 32);

            if (len < 31)

                avio_skip(pb, 31 - len);

            /* codec_tag YV12 triggers an UV swap in rawdec.c */

            if (!memcmp(st->codec->codec_name, "Planar Y'CbCr 8-bit 4:2:0", 25))

                st->codec->codec_tag=MKTAG('I', '4', '2', '0');



            st->codec->bits_per_coded_sample = avio_rb16(pb); /* depth */

            color_table_id = avio_rb16(pb); /* colortable id */

            av_dlog(c->fc, "depth %d, ctab id %d\n",

                   st->codec->bits_per_coded_sample, color_table_id);

            /* figure out the palette situation */

            color_depth = st->codec->bits_per_coded_sample & 0x1F;

            color_greyscale = st->codec->bits_per_coded_sample & 0x20;



            /* if the depth is 2, 4, or 8 bpp, file is palettized */

            if ((color_depth == 2) || (color_depth == 4) ||

                (color_depth == 8)) {

                /* for palette traversal */

                unsigned int color_start, color_count, color_end;

                unsigned char r, g, b;



                if (color_greyscale) {

                    int color_index, color_dec;

                    /* compute the greyscale palette */

                    st->codec->bits_per_coded_sample = color_depth;

                    color_count = 1 << color_depth;

                    color_index = 255;

                    color_dec = 256 / (color_count - 1);

                    for (j = 0; j < color_count; j++) {

                        r = g = b = color_index;

                        sc->palette[j] =

                            (r << 16) | (g << 8) | (b);

                        color_index -= color_dec;

                        if (color_index < 0)

                            color_index = 0;

                    }

                } else if (color_table_id) {

                    const uint8_t *color_table;

                    /* if flag bit 3 is set, use the default palette */

                    color_count = 1 << color_depth;

                    if (color_depth == 2)

                        color_table = ff_qt_default_palette_4;

                    else if (color_depth == 4)

                        color_table = ff_qt_default_palette_16;

                    else

                        color_table = ff_qt_default_palette_256;



                    for (j = 0; j < color_count; j++) {

                        r = color_table[j * 3 + 0];

                        g = color_table[j * 3 + 1];

                        b = color_table[j * 3 + 2];

                        sc->palette[j] =

                            (r << 16) | (g << 8) | (b);

                    }

                } else {

                    /* load the palette from the file */

                    color_start = avio_rb32(pb);

                    color_count = avio_rb16(pb);

                    color_end = avio_rb16(pb);

                    if ((color_start <= 255) &&

                        (color_end <= 255)) {

                        for (j = color_start; j <= color_end; j++) {

                            /* each R, G, or B component is 16 bits;

                             * only use the top 8 bits; skip alpha bytes

                             * up front */

                            avio_r8(pb);

                            avio_r8(pb);

                            r = avio_r8(pb);

                            avio_r8(pb);

                            g = avio_r8(pb);

                            avio_r8(pb);

                            b = avio_r8(pb);

                            avio_r8(pb);

                            sc->palette[j] =

                                (r << 16) | (g << 8) | (b);

                        }

                    }

                }

                sc->has_palette = 1;

            }

        } else if (st->codec->codec_type==AVMEDIA_TYPE_AUDIO) {

            int bits_per_sample, flags;

            uint16_t version = avio_rb16(pb);



            st->codec->codec_id = id;

            avio_rb16(pb); /* revision level */

            avio_rb32(pb); /* vendor */



            st->codec->channels = avio_rb16(pb);             /* channel count */

            av_dlog(c->fc, "audio channels %d\n", st->codec->channels);

            st->codec->bits_per_coded_sample = avio_rb16(pb);      /* sample size */



            sc->audio_cid = avio_rb16(pb);

            avio_rb16(pb); /* packet size = 0 */



            st->codec->sample_rate = ((avio_rb32(pb) >> 16));



            //Read QT version 1 fields. In version 0 these do not exist.

            av_dlog(c->fc, "version =%d, isom =%d\n",version,c->isom);

            if (!c->isom) {

                if (version==1) {

                    sc->samples_per_frame = avio_rb32(pb);

                    avio_rb32(pb); /* bytes per packet */

                    sc->bytes_per_frame = avio_rb32(pb);

                    avio_rb32(pb); /* bytes per sample */

                } else if (version==2) {

                    avio_rb32(pb); /* sizeof struct only */

                    st->codec->sample_rate = av_int2double(avio_rb64(pb)); /* float 64 */

                    st->codec->channels = avio_rb32(pb);

                    avio_rb32(pb); /* always 0x7F000000 */

                    st->codec->bits_per_coded_sample = avio_rb32(pb); /* bits per channel if sound is uncompressed */

                    flags = avio_rb32(pb); /* lpcm format specific flag */

                    sc->bytes_per_frame = avio_rb32(pb); /* bytes per audio packet if constant */

                    sc->samples_per_frame = avio_rb32(pb); /* lpcm frames per audio packet if constant */

                    if (format == MKTAG('l','p','c','m'))

                        st->codec->codec_id = ff_mov_get_lpcm_codec_id(st->codec->bits_per_coded_sample, flags);

                }

            }



            switch (st->codec->codec_id) {

            case AV_CODEC_ID_PCM_S8:

            case AV_CODEC_ID_PCM_U8:

                if (st->codec->bits_per_coded_sample == 16)

                    st->codec->codec_id = AV_CODEC_ID_PCM_S16BE;

                break;

            case AV_CODEC_ID_PCM_S16LE:

            case AV_CODEC_ID_PCM_S16BE:

                if (st->codec->bits_per_coded_sample == 8)

                    st->codec->codec_id = AV_CODEC_ID_PCM_S8;

                else if (st->codec->bits_per_coded_sample == 24)

                    st->codec->codec_id =

                        st->codec->codec_id == AV_CODEC_ID_PCM_S16BE ?

                        AV_CODEC_ID_PCM_S24BE : AV_CODEC_ID_PCM_S24LE;

                break;

            /* set values for old format before stsd version 1 appeared */

            case AV_CODEC_ID_MACE3:

                sc->samples_per_frame = 6;

                sc->bytes_per_frame = 2*st->codec->channels;

                break;

            case AV_CODEC_ID_MACE6:

                sc->samples_per_frame = 6;

                sc->bytes_per_frame = 1*st->codec->channels;

                break;

            case AV_CODEC_ID_ADPCM_IMA_QT:

                sc->samples_per_frame = 64;

                sc->bytes_per_frame = 34*st->codec->channels;

                break;

            case AV_CODEC_ID_GSM:

                sc->samples_per_frame = 160;

                sc->bytes_per_frame = 33;

                break;

            default:

                break;

            }



            bits_per_sample = av_get_bits_per_sample(st->codec->codec_id);

            if (bits_per_sample) {

                st->codec->bits_per_coded_sample = bits_per_sample;

                sc->sample_size = (bits_per_sample >> 3) * st->codec->channels;

            }

        } else if (st->codec->codec_type==AVMEDIA_TYPE_SUBTITLE){

            // ttxt stsd contains display flags, justification, background

            // color, fonts, and default styles, so fake an atom to read it

            MOVAtom fake_atom = { .size = size - (avio_tell(pb) - start_pos) };

            if (format != AV_RL32("mp4s")) // mp4s contains a regular esds atom

                mov_read_glbl(c, pb, fake_atom);

            st->codec->codec_id= id;

            st->codec->width = sc->width;

            st->codec->height = sc->height;

        } else {

            /* other codec type, just skip (rtp, mp4s, tmcd ...) */

            avio_skip(pb, size - (avio_tell(pb) - start_pos));

        }

        /* this will read extra atoms at the end (wave, alac, damr, avcC, SMI ...) */

        a.size = size - (avio_tell(pb) - start_pos);

        if (a.size > 8) {

            int ret;

            if ((ret = mov_read_default(c, pb, a)) < 0)

                return ret;

        } else if (a.size > 0)

            avio_skip(pb, a.size);

    }



    if (st->codec->codec_type==AVMEDIA_TYPE_AUDIO && st->codec->sample_rate==0 && sc->time_scale>1)

        st->codec->sample_rate= sc->time_scale;



    /* special codec parameters handling */

    switch (st->codec->codec_id) {

#if CONFIG_DV_DEMUXER

    case AV_CODEC_ID_DVAUDIO:

        c->dv_fctx = avformat_alloc_context();

        c->dv_demux = avpriv_dv_init_demux(c->dv_fctx);

        if (!c->dv_demux) {

            av_log(c->fc, AV_LOG_ERROR, "dv demux context init error\n");

            return AVERROR(ENOMEM);

        }

        sc->dv_audio_container = 1;

        st->codec->codec_id = AV_CODEC_ID_PCM_S16LE;

        break;

#endif

    /* no ifdef since parameters are always those */

    case AV_CODEC_ID_QCELP:

        // force sample rate for qcelp when not stored in mov

        if (st->codec->codec_tag != MKTAG('Q','c','l','p'))

            st->codec->sample_rate = 8000;

        st->codec->channels= 1; /* really needed */

        break;

    case AV_CODEC_ID_AMR_NB:

        st->codec->channels= 1; /* really needed */

        /* force sample rate for amr, stsd in 3gp does not store sample rate */

        st->codec->sample_rate = 8000;

        break;

    case AV_CODEC_ID_AMR_WB:

        st->codec->channels    = 1;

        st->codec->sample_rate = 16000;

        break;

    case AV_CODEC_ID_MP2:

    case AV_CODEC_ID_MP3:

        st->codec->codec_type = AVMEDIA_TYPE_AUDIO; /* force type after stsd for m1a hdlr */

        st->need_parsing = AVSTREAM_PARSE_FULL;

        break;

    case AV_CODEC_ID_GSM:

    case AV_CODEC_ID_ADPCM_MS:

    case AV_CODEC_ID_ADPCM_IMA_WAV:

    case AV_CODEC_ID_ILBC:

        st->codec->block_align = sc->bytes_per_frame;

        break;

    case AV_CODEC_ID_ALAC:

        if (st->codec->extradata_size == 36) {

            st->codec->channels   = AV_RB8 (st->codec->extradata+21);

            st->codec->sample_rate = AV_RB32(st->codec->extradata+32);

        }

        break;

    case AV_CODEC_ID_VC1:

        st->need_parsing = AVSTREAM_PARSE_FULL;

        break;

    default:

        break;

    }



    return 0;

}

static int normalize_bits(int num, int width)

{

    int i = 0;

    int bits = (width) ? 31 : 15;

    int limit = 1 << (bits - 1);



    if (num) {

        if (num == -1)

            return bits;

        if (num < 0)

            num = ~num;

        for (i = 0; num < limit; i++)

            num <<= 1;

    }

    return i;

}

static int decode_vop_header(MpegEncContext *s, GetBitContext *gb){

    int time_incr, time_increment;



    s->pict_type = get_bits(gb, 2) + AV_PICTURE_TYPE_I;        /* pict type: I = 0 , P = 1 */

    if(s->pict_type==AV_PICTURE_TYPE_B && s->low_delay && s->vol_control_parameters==0 && !(s->flags & CODEC_FLAG_LOW_DELAY)){

        av_log(s->avctx, AV_LOG_ERROR, "low_delay flag incorrectly, clearing it\n");

        s->low_delay=0;

    }



    s->partitioned_frame= s->data_partitioning && s->pict_type!=AV_PICTURE_TYPE_B;

    if(s->partitioned_frame)

        s->decode_mb= mpeg4_decode_partitioned_mb;

    else

        s->decode_mb= mpeg4_decode_mb;



    time_incr=0;

    while (get_bits1(gb) != 0)

        time_incr++;



    check_marker(gb, "before time_increment");



    if(s->time_increment_bits==0 || !(show_bits(gb, s->time_increment_bits+1)&1)){

        av_log(s->avctx, AV_LOG_ERROR, "hmm, seems the headers are not complete, trying to guess time_increment_bits\n");



        for(s->time_increment_bits=1 ;s->time_increment_bits<16; s->time_increment_bits++){

            if (    s->pict_type == AV_PICTURE_TYPE_P

                || (s->pict_type == AV_PICTURE_TYPE_S && s->vol_sprite_usage==GMC_SPRITE)) {

                if((show_bits(gb, s->time_increment_bits+6)&0x37) == 0x30) break;

            }else

                if((show_bits(gb, s->time_increment_bits+5)&0x1F) == 0x18) break;

        }



        av_log(s->avctx, AV_LOG_ERROR, "my guess is %d bits ;)\n",s->time_increment_bits);

    }



    if(IS_3IV1) time_increment= get_bits1(gb); //FIXME investigate further

    else time_increment= get_bits(gb, s->time_increment_bits);



    if(s->pict_type!=AV_PICTURE_TYPE_B){

        s->last_time_base= s->time_base;

        s->time_base+= time_incr;

        s->time= s->time_base*s->avctx->time_base.den + time_increment;

        if(s->workaround_bugs&FF_BUG_UMP4){

            if(s->time < s->last_non_b_time){

                /* header is not mpeg-4-compatible, broken encoder,

                 * trying to workaround */

                s->time_base++;

                s->time+= s->avctx->time_base.den;

            }

        }

        s->pp_time= s->time - s->last_non_b_time;

        s->last_non_b_time= s->time;

    }else{

        s->time= (s->last_time_base + time_incr)*s->avctx->time_base.den + time_increment;

        s->pb_time= s->pp_time - (s->last_non_b_time - s->time);

        if(s->pp_time <=s->pb_time || s->pp_time <= s->pp_time - s->pb_time || s->pp_time<=0){

            /* messed up order, maybe after seeking? skipping current b-frame */

            return FRAME_SKIPPED;

        }

        ff_mpeg4_init_direct_mv(s);



        if(s->t_frame==0) s->t_frame= s->pb_time;

        if(s->t_frame==0) s->t_frame=1; // 1/0 protection

        s->pp_field_time= (  ROUNDED_DIV(s->last_non_b_time, s->t_frame)

                           - ROUNDED_DIV(s->last_non_b_time - s->pp_time, s->t_frame))*2;

        s->pb_field_time= (  ROUNDED_DIV(s->time, s->t_frame)

                           - ROUNDED_DIV(s->last_non_b_time - s->pp_time, s->t_frame))*2;

        if(!s->progressive_sequence){

            if(s->pp_field_time <= s->pb_field_time || s->pb_field_time <= 1)

                return FRAME_SKIPPED;

        }

    }



    if(s->avctx->time_base.num)

        s->current_picture_ptr->f.pts = (s->time + s->avctx->time_base.num / 2) / s->avctx->time_base.num;

    else

        s->current_picture_ptr->f.pts = AV_NOPTS_VALUE;

    if(s->avctx->debug&FF_DEBUG_PTS)

        av_log(s->avctx, AV_LOG_DEBUG, "MPEG4 PTS: %"PRId64"\n",

               s->current_picture_ptr->f.pts);



    check_marker(gb, "before vop_coded");



    /* vop coded */

    if (get_bits1(gb) != 1){

        if(s->avctx->debug&FF_DEBUG_PICT_INFO)

            av_log(s->avctx, AV_LOG_ERROR, "vop not coded\n");

        return FRAME_SKIPPED;

    }

    if (s->shape != BIN_ONLY_SHAPE && ( s->pict_type == AV_PICTURE_TYPE_P

                          || (s->pict_type == AV_PICTURE_TYPE_S && s->vol_sprite_usage==GMC_SPRITE))) {

        /* rounding type for motion estimation */

        s->no_rounding = get_bits1(gb);

    } else {

        s->no_rounding = 0;

    }

//FIXME reduced res stuff



     if (s->shape != RECT_SHAPE) {

         if (s->vol_sprite_usage != 1 || s->pict_type != AV_PICTURE_TYPE_I) {

             skip_bits(gb, 13); /* width */

             skip_bits1(gb);   /* marker */

             skip_bits(gb, 13); /* height */

             skip_bits1(gb);   /* marker */

             skip_bits(gb, 13); /* hor_spat_ref */

             skip_bits1(gb);   /* marker */

             skip_bits(gb, 13); /* ver_spat_ref */

         }

         skip_bits1(gb); /* change_CR_disable */



         if (get_bits1(gb) != 0) {

             skip_bits(gb, 8); /* constant_alpha_value */

         }

     }

//FIXME complexity estimation stuff



     if (s->shape != BIN_ONLY_SHAPE) {

         skip_bits_long(gb, s->cplx_estimation_trash_i);

         if(s->pict_type != AV_PICTURE_TYPE_I)

            skip_bits_long(gb, s->cplx_estimation_trash_p);

         if(s->pict_type == AV_PICTURE_TYPE_B)

            skip_bits_long(gb, s->cplx_estimation_trash_b);



         s->intra_dc_threshold= ff_mpeg4_dc_threshold[ get_bits(gb, 3) ];

         if(!s->progressive_sequence){

             s->top_field_first= get_bits1(gb);

             s->alternate_scan= get_bits1(gb);

         }else

             s->alternate_scan= 0;

     }



     if(s->alternate_scan){

         ff_init_scantable(s->dsp.idct_permutation, &s->inter_scantable  , ff_alternate_vertical_scan);

         ff_init_scantable(s->dsp.idct_permutation, &s->intra_scantable  , ff_alternate_vertical_scan);

         ff_init_scantable(s->dsp.idct_permutation, &s->intra_h_scantable, ff_alternate_vertical_scan);

         ff_init_scantable(s->dsp.idct_permutation, &s->intra_v_scantable, ff_alternate_vertical_scan);

     } else{

         ff_init_scantable(s->dsp.idct_permutation, &s->inter_scantable  , ff_zigzag_direct);

         ff_init_scantable(s->dsp.idct_permutation, &s->intra_scantable  , ff_zigzag_direct);

         ff_init_scantable(s->dsp.idct_permutation, &s->intra_h_scantable, ff_alternate_horizontal_scan);

         ff_init_scantable(s->dsp.idct_permutation, &s->intra_v_scantable, ff_alternate_vertical_scan);

     }



     if(s->pict_type == AV_PICTURE_TYPE_S && (s->vol_sprite_usage==STATIC_SPRITE || s->vol_sprite_usage==GMC_SPRITE)){

         mpeg4_decode_sprite_trajectory(s, gb);

         if(s->sprite_brightness_change) av_log(s->avctx, AV_LOG_ERROR, "sprite_brightness_change not supported\n");

         if(s->vol_sprite_usage==STATIC_SPRITE) av_log(s->avctx, AV_LOG_ERROR, "static sprite not supported\n");

     }



     if (s->shape != BIN_ONLY_SHAPE) {

         s->chroma_qscale= s->qscale = get_bits(gb, s->quant_precision);

         if(s->qscale==0){

             av_log(s->avctx, AV_LOG_ERROR, "Error, header damaged or not MPEG4 header (qscale=0)\n");

             return -1; // makes no sense to continue, as there is nothing left from the image then

         }



         if (s->pict_type != AV_PICTURE_TYPE_I) {

             s->f_code = get_bits(gb, 3);       /* fcode_for */

             if(s->f_code==0){

                 av_log(s->avctx, AV_LOG_ERROR, "Error, header damaged or not MPEG4 header (f_code=0)\n");

                 return -1; // makes no sense to continue, as the MV decoding will break very quickly

             }

         }else

             s->f_code=1;



         if (s->pict_type == AV_PICTURE_TYPE_B) {

             s->b_code = get_bits(gb, 3);

         }else

             s->b_code=1;



         if(s->avctx->debug&FF_DEBUG_PICT_INFO){

             av_log(s->avctx, AV_LOG_DEBUG, "qp:%d fc:%d,%d %s size:%d pro:%d alt:%d top:%d %spel part:%d resync:%d w:%d a:%d rnd:%d vot:%d%s dc:%d ce:%d/%d/%d\n",

                 s->qscale, s->f_code, s->b_code,

                 s->pict_type == AV_PICTURE_TYPE_I ? "I" : (s->pict_type == AV_PICTURE_TYPE_P ? "P" : (s->pict_type == AV_PICTURE_TYPE_B ? "B" : "S")),

                 gb->size_in_bits,s->progressive_sequence, s->alternate_scan, s->top_field_first,

                 s->quarter_sample ? "q" : "h", s->data_partitioning, s->resync_marker, s->num_sprite_warping_points,

                 s->sprite_warping_accuracy, 1-s->no_rounding, s->vo_type, s->vol_control_parameters ? " VOLC" : " ", s->intra_dc_threshold, s->cplx_estimation_trash_i, s->cplx_estimation_trash_p, s->cplx_estimation_trash_b);

         }



         if(!s->scalability){

             if (s->shape!=RECT_SHAPE && s->pict_type!=AV_PICTURE_TYPE_I) {

                 skip_bits1(gb); // vop shape coding type

             }

         }else{

             if(s->enhancement_type){

                 int load_backward_shape= get_bits1(gb);

                 if(load_backward_shape){

                     av_log(s->avctx, AV_LOG_ERROR, "load backward shape isn't supported\n");

                 }

             }

             skip_bits(gb, 2); //ref_select_code

         }

     }

     /* detect buggy encoders which don't set the low_delay flag (divx4/xvid/opendivx)*/

     // note we cannot detect divx5 without b-frames easily (although it's buggy too)

     if(s->vo_type==0 && s->vol_control_parameters==0 && s->divx_version==-1 && s->picture_number==0){

         av_log(s->avctx, AV_LOG_WARNING, "looks like this file was encoded with (divx4/(old)xvid/opendivx) -> forcing low_delay flag\n");

         s->low_delay=1;

     }



     s->picture_number++; // better than pic number==0 always ;)



     s->y_dc_scale_table= ff_mpeg4_y_dc_scale_table; //FIXME add short header support

     s->c_dc_scale_table= ff_mpeg4_c_dc_scale_table;



     if(s->workaround_bugs&FF_BUG_EDGE){

         s->h_edge_pos= s->width;

         s->v_edge_pos= s->height;

     }

     return 0;

}

static int decompress_p(AVCodecContext *avctx,

                        uint32_t *dst, int linesize,

                        uint32_t *prev, int plinesize)

{

    SCPRContext *s = avctx->priv_data;

    GetByteContext *gb = &s->gb;

    int ret, temp, min, max, x, y, cx = 0, cx1 = 0;

    int backstep = linesize - avctx->width;

    const int cxshift = s->cxshift;



    if (bytestream2_get_byte(gb) == 0)

        return 0;

    bytestream2_skip(gb, 1);

    init_rangecoder(&s->rc, gb);



    ret  = decode_value(s, s->range_model, 256, 1, &min);

    ret |= decode_value(s, s->range_model, 256, 1, &temp);

    min += temp << 8;

    ret |= decode_value(s, s->range_model, 256, 1, &max);

    ret |= decode_value(s, s->range_model, 256, 1, &temp);

    if (ret < 0)

        return ret;



    max += temp << 8;

    memset(s->blocks, 0, sizeof(*s->blocks) * s->nbcount);



    while (min <= max) {

        int fill, count;



        ret  = decode_value(s, s->fill_model,  5,   10, &fill);

        ret |= decode_value(s, s->count_model, 256, 20, &count);

        if (ret < 0)

            return ret;



        while (min < s->nbcount && count-- > 0) {

            s->blocks[min++] = fill;

        }

    }



    for (y = 0; y < s->nby; y++) {

        for (x = 0; x < s->nbx; x++) {

            int sy1 = 0, sy2 = 16, sx1 = 0, sx2 = 16;



            if (s->blocks[y * s->nbx + x] == 0)

                continue;



            if (((s->blocks[y * s->nbx + x] - 1) & 1) > 0) {

                ret  = decode_value(s, s->sxy_model[0], 16, 100, &sx1);

                ret |= decode_value(s, s->sxy_model[1], 16, 100, &sy1);

                ret |= decode_value(s, s->sxy_model[2], 16, 100, &sx2);

                ret |= decode_value(s, s->sxy_model[3], 16, 100, &sy2);

                if (ret < 0)

                    return ret;



                sx2++;

                sy2++;

            }

            if (((s->blocks[y * s->nbx + x] - 1) & 2) > 0) {

                int i, j, by = y * 16, bx = x * 16;

                int mvx, mvy;



                ret  = decode_value(s, s->mv_model[0], 512, 100, &mvx);

                ret |= decode_value(s, s->mv_model[1], 512, 100, &mvy);

                if (ret < 0)

                    return ret;



                mvx -= 256;

                mvy -= 256;



                if (by + mvy + sy1 < 0 || bx + mvx + sx1 < 0)

                    return AVERROR_INVALIDDATA;



                for (i = 0; i < sy2 - sy1 && (by + sy1 + i) < avctx->height; i++) {

                    for (j = 0; j < sx2 - sx1 && (bx + sx1 + j) < avctx->width; j++) {

                        dst[(by + i + sy1) * linesize + bx + sx1 + j] = prev[(by + mvy + sy1 + i) * plinesize + bx + sx1 + mvx + j];

                    }

                }

            } else {

                int run, r, g, b, z, bx = x * 16 + sx1, by = y * 16 + sy1;

                unsigned clr, ptype = 0;



                for (; by < y * 16 + sy2 && by < avctx->height;) {

                    ret = decode_value(s, s->op_model[ptype], 6, 1000, &ptype);

                    if (ptype == 0) {

                        ret = decode_unit(s, &s->pixel_model[0][cx + cx1], 400, &r);

                        if (ret < 0)

                            return ret;



                        cx1 = (cx << 6) & 0xFC0;

                        cx = r >> cxshift;

                        ret = decode_unit(s, &s->pixel_model[1][cx + cx1], 400, &g);

                        if (ret < 0)

                            return ret;



                        cx1 = (cx << 6) & 0xFC0;

                        cx = g >> cxshift;

                        ret = decode_unit(s, &s->pixel_model[2][cx + cx1], 400, &b);

                        if (ret < 0)

                            return ret;



                        cx1 = (cx << 6) & 0xFC0;

                        cx = b >> cxshift;

                        clr = (b << 16) + (g << 8) + r;

                    }

                    if (ptype > 5)

                        return AVERROR_INVALIDDATA;

                    ret = decode_value(s, s->run_model[ptype], 256, 400, &run);

                    if (ret < 0)

                        return ret;



                    switch (ptype) {

                    case 0:

                        while (run-- > 0) {

                            if (by >= avctx->height)

                                return AVERROR_INVALIDDATA;



                            dst[by * linesize + bx] = clr;

                            bx++;

                            if (bx >= x * 16 + sx2 || bx >= avctx->width) {

                                bx = x * 16 + sx1;

                                by++;

                            }

                        }

                        break;

                    case 1:

                        while (run-- > 0) {

                            if (bx == 0) {

                                if (by < 1)

                                    return AVERROR_INVALIDDATA;

                                z = backstep;

                            } else {

                                z = 0;

                            }



                            if (by >= avctx->height)

                                return AVERROR_INVALIDDATA;



                            clr = dst[by * linesize + bx - 1 - z];

                            dst[by * linesize + bx] = clr;

                            bx++;

                            if (bx >= x * 16 + sx2 || bx >= avctx->width) {

                                bx = x * 16 + sx1;

                                by++;

                            }

                        }

                        break;

                    case 2:

                        while (run-- > 0) {

                            if (by < 1 || by >= avctx->height)

                                return AVERROR_INVALIDDATA;



                            clr = dst[(by - 1) * linesize + bx];

                            dst[by * linesize + bx] = clr;

                            bx++;

                            if (bx >= x * 16 + sx2 || bx >= avctx->width) {

                                bx = x * 16 + sx1;

                                by++;

                            }

                        }

                        break;

                    case 3:

                        while (run-- > 0) {

                            if (by >= avctx->height)

                                return AVERROR_INVALIDDATA;



                            clr = prev[by * linesize + bx];

                            dst[by * linesize + bx] = clr;

                            bx++;

                            if (bx >= x * 16 + sx2 || bx >= avctx->width) {

                                bx = x * 16 + sx1;

                                by++;

                            }

                        }

                        break;

                    case 4:

                        while (run-- > 0) {

                            uint8_t *odst = (uint8_t *)dst;



                            if (by < 1 || by >= avctx->height)

                                return AVERROR_INVALIDDATA;



                            if (bx == 0) {

                                z = backstep;

                            } else {

                                z = 0;

                            }



                            r = odst[((by - 1) * linesize + bx) * 4] +

                                odst[(by * linesize + bx - 1 - z) * 4] -

                                odst[((by - 1) * linesize + bx - 1 - z) * 4];

                            g = odst[((by - 1) * linesize + bx) * 4 + 1] +

                                odst[(by * linesize + bx - 1 - z) * 4 + 1] -

                                odst[((by - 1) * linesize + bx - 1 - z) * 4 + 1];

                            b = odst[((by - 1) * linesize + bx) * 4 + 2] +

                                odst[(by * linesize + bx - 1 - z) * 4 + 2] -

                                odst[((by - 1) * linesize + bx - 1 - z) * 4 + 2];

                            clr = ((b & 0xFF) << 16) + ((g & 0xFF) << 8) + (r & 0xFF);

                            dst[by * linesize + bx] = clr;

                            bx++;

                            if (bx >= x * 16 + sx2 || bx >= avctx->width) {

                                bx = x * 16 + sx1;

                                by++;

                            }

                        }

                        break;

                    case 5:

                        while (run-- > 0) {

                            if (by < 1 || by >= avctx->height)

                                return AVERROR_INVALIDDATA;



                            if (bx == 0) {

                                z = backstep;

                            } else {

                                z = 0;

                            }



                            clr = dst[(by - 1) * linesize + bx - 1 - z];

                            dst[by * linesize + bx] = clr;

                            bx++;

                            if (bx >= x * 16 + sx2 || bx >= avctx->width) {

                                bx = x * 16 + sx1;

                                by++;

                            }

                        }

                        break;

                    }



                    if (avctx->bits_per_coded_sample == 16) {

                        cx1 = (clr & 0xFF00) >> 2;

                        cx = (clr & 0xFFFFFF) >> 16;

                    } else {

                        cx1 = (clr & 0xFC00) >> 4;

                        cx = (clr & 0xFFFFFF) >> 18;

                    }

                }

            }

        }

    }



    return 0;

}

static av_cold int decode_init_mp3on4(AVCodecContext * avctx)

{

    MP3On4DecodeContext *s = avctx->priv_data;

    MPEG4AudioConfig cfg;

    int i;



    if ((avctx->extradata_size < 2) || (avctx->extradata == NULL)) {

        av_log(avctx, AV_LOG_ERROR, "Codec extradata missing or too short.\n");

        return AVERROR_INVALIDDATA;

    }



    avpriv_mpeg4audio_get_config(&cfg, avctx->extradata,

                                 avctx->extradata_size * 8, 1);

    if (!cfg.chan_config || cfg.chan_config > 7) {

        av_log(avctx, AV_LOG_ERROR, "Invalid channel config number.\n");

        return AVERROR_INVALIDDATA;

    }

    s->frames             = mp3Frames[cfg.chan_config];

    s->coff               = chan_offset[cfg.chan_config];

    avctx->channels       = ff_mpeg4audio_channels[cfg.chan_config];

    avctx->channel_layout = chan_layout[cfg.chan_config];



    if (cfg.sample_rate < 16000)

        s->syncword = 0xffe00000;

    else

        s->syncword = 0xfff00000;



    /* Init the first mp3 decoder in standard way, so that all tables get builded

     * We replace avctx->priv_data with the context of the first decoder so that

     * decode_init() does not have to be changed.

     * Other decoders will be initialized here copying data from the first context

     */

    // Allocate zeroed memory for the first decoder context

    s->mp3decctx[0] = av_mallocz(sizeof(MPADecodeContext));

    if (!s->mp3decctx[0])

        goto alloc_fail;

    // Put decoder context in place to make init_decode() happy

    avctx->priv_data = s->mp3decctx[0];

    decode_init(avctx);

    // Restore mp3on4 context pointer

    avctx->priv_data = s;

    s->mp3decctx[0]->adu_mode = 1; // Set adu mode



    /* Create a separate codec/context for each frame (first is already ok).

     * Each frame is 1 or 2 channels - up to 5 frames allowed

     */

    for (i = 1; i < s->frames; i++) {

        s->mp3decctx[i] = av_mallocz(sizeof(MPADecodeContext));

        if (!s->mp3decctx[i])

            goto alloc_fail;

        s->mp3decctx[i]->adu_mode = 1;

        s->mp3decctx[i]->avctx = avctx;

        s->mp3decctx[i]->mpadsp = s->mp3decctx[0]->mpadsp;

    }



    return 0;

alloc_fail:

    decode_close_mp3on4(avctx);

    return AVERROR(ENOMEM);

}

static void avc_luma_midv_qrt_and_aver_dst_8w_msa(const uint8_t *src,

                                                  int32_t src_stride,

                                                  uint8_t *dst,

                                                  int32_t dst_stride,

                                                  int32_t height,

                                                  uint8_t vert_offset)

{

    int32_t loop_cnt;

    v16i8 src0, src1, src2, src3, src4;

    v16u8 dst0, dst1, dst2, dst3;

    v16i8 mask0, mask1, mask2;

    v8i16 hz_out0, hz_out1, hz_out2, hz_out3;

    v8i16 hz_out4, hz_out5, hz_out6, hz_out7, hz_out8;

    v8i16 res0, res1, res2, res3;

    v8i16 res4, res5, res6, res7;



    LD_SB3(&luma_mask_arr[0], 16, mask0, mask1, mask2);



    LD_SB5(src, src_stride, src0, src1, src2, src3, src4);

    XORI_B5_128_SB(src0, src1, src2, src3, src4);

    src += (5 * src_stride);



    hz_out0 = AVC_HORZ_FILTER_SH(src0, mask0, mask1, mask2);

    hz_out1 = AVC_HORZ_FILTER_SH(src1, mask0, mask1, mask2);

    hz_out2 = AVC_HORZ_FILTER_SH(src2, mask0, mask1, mask2);

    hz_out3 = AVC_HORZ_FILTER_SH(src3, mask0, mask1, mask2);

    hz_out4 = AVC_HORZ_FILTER_SH(src4, mask0, mask1, mask2);



    for (loop_cnt = (height >> 2); loop_cnt--;) {

        LD_SB4(src, src_stride, src0, src1, src2, src3);

        XORI_B4_128_SB(src0, src1, src2, src3);

        src += (4 * src_stride);



        LD_UB4(dst, dst_stride, dst0, dst1, dst2, dst3);



        hz_out5 = AVC_HORZ_FILTER_SH(src0, mask0, mask1, mask2);

        hz_out6 = AVC_HORZ_FILTER_SH(src1, mask0, mask1, mask2);

        hz_out7 = AVC_HORZ_FILTER_SH(src2, mask0, mask1, mask2);

        hz_out8 = AVC_HORZ_FILTER_SH(src3, mask0, mask1, mask2);



        res0 = AVC_CALC_DPADD_H_6PIX_2COEFF_SH(hz_out0, hz_out1, hz_out2,

                                               hz_out3, hz_out4, hz_out5);

        res2 = AVC_CALC_DPADD_H_6PIX_2COEFF_SH(hz_out1, hz_out2, hz_out3,

                                               hz_out4, hz_out5, hz_out6);

        res4 = AVC_CALC_DPADD_H_6PIX_2COEFF_SH(hz_out2, hz_out3, hz_out4,

                                               hz_out5, hz_out6, hz_out7);

        res6 = AVC_CALC_DPADD_H_6PIX_2COEFF_SH(hz_out3, hz_out4, hz_out5,

                                               hz_out6, hz_out7, hz_out8);



        if (vert_offset) {

            res1 = __msa_srari_h(hz_out3, 5);

            res3 = __msa_srari_h(hz_out4, 5);

            res5 = __msa_srari_h(hz_out5, 5);

            res7 = __msa_srari_h(hz_out6, 5);

        } else {

            res1 = __msa_srari_h(hz_out2, 5);

            res3 = __msa_srari_h(hz_out3, 5);

            res5 = __msa_srari_h(hz_out4, 5);

            res7 = __msa_srari_h(hz_out5, 5);

        }



        SAT_SH4_SH(res1, res3, res5, res7, 7);



        res0 = __msa_aver_s_h(res0, res1);

        res1 = __msa_aver_s_h(res2, res3);

        res2 = __msa_aver_s_h(res4, res5);

        res3 = __msa_aver_s_h(res6, res7);

        ILVR_D2_UB(dst1, dst0, dst3, dst2, dst0, dst1);

        CONVERT_UB_AVG_ST8x4_UB(res0, res1, res2, res3, dst0, dst1,

                                dst, dst_stride);

        dst += (4 * dst_stride);



        hz_out0 = hz_out4;

        hz_out1 = hz_out5;

        hz_out2 = hz_out6;

        hz_out3 = hz_out7;

        hz_out4 = hz_out8;

    }

}

static const AVClass *filter_child_class_next(const AVClass *prev)

{

    AVFilter **f = NULL;



    while (prev && *(f = av_filter_next(f)))

        if ((*f)->priv_class == prev)

            break;



    while (*(f = av_filter_next(f)))

        if ((*f)->priv_class)

            return (*f)->priv_class;



    return NULL;

}

static av_always_inline void mpeg_motion_lowres(MpegEncContext *s,

                               uint8_t *dest_y, uint8_t *dest_cb, uint8_t *dest_cr,

                               int field_based, int bottom_field, int field_select,

                               uint8_t **ref_picture, h264_chroma_mc_func *pix_op,

                               int motion_x, int motion_y, int h)

{

    uint8_t *ptr_y, *ptr_cb, *ptr_cr;

    int mx, my, src_x, src_y, uvsrc_x, uvsrc_y, uvlinesize, linesize, sx, sy, uvsx, uvsy;

    const int lowres= s->avctx->lowres;

    const int block_s= 8>>lowres;

    const int s_mask= (2<<lowres)-1;

    const int h_edge_pos = s->h_edge_pos >> lowres;

    const int v_edge_pos = s->v_edge_pos >> lowres;

    linesize   = s->current_picture.linesize[0] << field_based;

    uvlinesize = s->current_picture.linesize[1] << field_based;



    if(s->quarter_sample){ //FIXME obviously not perfect but qpel wont work in lowres anyway

        motion_x/=2;

        motion_y/=2;

    }



    if(field_based){

        motion_y += (bottom_field - field_select)*((1<<lowres)-1);

    }



    sx= motion_x & s_mask;

    sy= motion_y & s_mask;

    src_x = s->mb_x*2*block_s               + (motion_x >> (lowres+1));

    src_y =(s->mb_y*2*block_s>>field_based) + (motion_y >> (lowres+1));



    if (s->out_format == FMT_H263) {

        uvsx = ((motion_x>>1) & s_mask) | (sx&1);

        uvsy = ((motion_y>>1) & s_mask) | (sy&1);

        uvsrc_x = src_x>>1;

        uvsrc_y = src_y>>1;

    }else if(s->out_format == FMT_H261){//even chroma mv's are full pel in H261

        mx = motion_x / 4;

        my = motion_y / 4;

        uvsx = (2*mx) & s_mask;

        uvsy = (2*my) & s_mask;

        uvsrc_x = s->mb_x*block_s               + (mx >> lowres);

        uvsrc_y = s->mb_y*block_s               + (my >> lowres);

    } else {

        mx = motion_x / 2;

        my = motion_y / 2;

        uvsx = mx & s_mask;

        uvsy = my & s_mask;

        uvsrc_x = s->mb_x*block_s               + (mx >> (lowres+1));

        uvsrc_y =(s->mb_y*block_s>>field_based) + (my >> (lowres+1));

    }



    ptr_y  = ref_picture[0] + src_y * linesize + src_x;

    ptr_cb = ref_picture[1] + uvsrc_y * uvlinesize + uvsrc_x;

    ptr_cr = ref_picture[2] + uvsrc_y * uvlinesize + uvsrc_x;



    if(   (unsigned)src_x > h_edge_pos                 - (!!sx) - 2*block_s

       || (unsigned)src_y >(v_edge_pos >> field_based) - (!!sy) - h){

            ff_emulated_edge_mc(s->edge_emu_buffer, ptr_y, s->linesize, 17, 17+field_based,

                             src_x, src_y<<field_based, h_edge_pos, v_edge_pos);

            ptr_y = s->edge_emu_buffer;

            if(!(s->flags&CODEC_FLAG_GRAY)){

                uint8_t *uvbuf= s->edge_emu_buffer+18*s->linesize;

                ff_emulated_edge_mc(uvbuf  , ptr_cb, s->uvlinesize, 9, 9+field_based,

                                 uvsrc_x, uvsrc_y<<field_based, h_edge_pos>>1, v_edge_pos>>1);

                ff_emulated_edge_mc(uvbuf+16, ptr_cr, s->uvlinesize, 9, 9+field_based,

                                 uvsrc_x, uvsrc_y<<field_based, h_edge_pos>>1, v_edge_pos>>1);

                ptr_cb= uvbuf;

                ptr_cr= uvbuf+16;

            }

    }



    if(bottom_field){ //FIXME use this for field pix too instead of the obnoxious hack which changes picture.data

        dest_y += s->linesize;

        dest_cb+= s->uvlinesize;

        dest_cr+= s->uvlinesize;

    }



    if(field_select){

        ptr_y += s->linesize;

        ptr_cb+= s->uvlinesize;

        ptr_cr+= s->uvlinesize;

    }



    sx <<= 2 - lowres;

    sy <<= 2 - lowres;

    pix_op[lowres-1](dest_y, ptr_y, linesize, h, sx, sy);



    if(!(s->flags&CODEC_FLAG_GRAY)){

        uvsx <<= 2 - lowres;

        uvsy <<= 2 - lowres;

        pix_op[lowres](dest_cb, ptr_cb, uvlinesize, h >> s->chroma_y_shift, uvsx, uvsy);

        pix_op[lowres](dest_cr, ptr_cr, uvlinesize, h >> s->chroma_y_shift, uvsx, uvsy);

    }

    //FIXME h261 lowres loop filter

}

static int encode_slice_plane(AVCodecContext *avctx, int mb_count,

        uint8_t *src, int src_stride, uint8_t *buf, unsigned buf_size,

        int *qmat, int chroma)

{

    ProresContext* ctx = avctx->priv_data;

    FDCTDSPContext *fdsp = &ctx->fdsp;

    DECLARE_ALIGNED(16, int16_t, blocks)[DEFAULT_SLICE_MB_WIDTH << 8], *block;

    int i, blocks_per_slice;

    PutBitContext pb;



    block = blocks;

    for (i = 0; i < mb_count; i++) {

        fdct_get(fdsp, src,                  src_stride, block + (0 << 6));

        fdct_get(fdsp, src + 8 * src_stride, src_stride, block + ((2 - chroma) << 6));

        if (!chroma) {

            fdct_get(fdsp, src + 16,                  src_stride, block + (1 << 6));

            fdct_get(fdsp, src + 16 + 8 * src_stride, src_stride, block + (3 << 6));

        }



        block += (256 >> chroma);

        src   += (32  >> chroma);

    }



    blocks_per_slice = mb_count << (2 - chroma);

    init_put_bits(&pb, buf, buf_size << 3);



    encode_dc_coeffs(&pb, blocks, blocks_per_slice, qmat);

    encode_ac_coeffs(avctx, &pb, blocks, blocks_per_slice, qmat);



    flush_put_bits(&pb);

    return put_bits_ptr(&pb) - pb.buf;

}

static inline void render_line_unrolled(intptr_t x, intptr_t y, int x1,

                                        intptr_t sy, int ady, int adx,

                                        float *buf)

{

    int err = -adx;

    x -= x1 - 1;

    buf += x1 - 1;

    while (++x < 0) {

        err += ady;

        if (err >= 0) {

            err += ady - adx;

            y   += sy;

            buf[x++] = ff_vorbis_floor1_inverse_db_table[y];

        }

        buf[x] = ff_vorbis_floor1_inverse_db_table[y];

    }

    if (x <= 0) {

        if (err + ady >= 0)

            y += sy;

        buf[x] = ff_vorbis_floor1_inverse_db_table[y];

    }

}

