static int ivi_decode_blocks(GetBitContext *gb, IVIBandDesc *band,

                             IVITile *tile, AVCodecContext *avctx)

{

    int mbn, blk, num_blocks, blk_size, ret, is_intra, mc_type = 0;

    int mv_x = 0, mv_y = 0;

    int32_t prev_dc;

    uint32_t cbp, quant, buf_offs;

    IVIMbInfo *mb;

    ivi_mc_func mc_with_delta_func, mc_no_delta_func;

    const uint8_t *scale_tab;



    /* init intra prediction for the DC coefficient */

    prev_dc    = 0;

    blk_size   = band->blk_size;

    /* number of blocks per mb */

    num_blocks = (band->mb_size != blk_size) ? 4 : 1;

    if (blk_size == 8) {

        mc_with_delta_func = ff_ivi_mc_8x8_delta;

        mc_no_delta_func   = ff_ivi_mc_8x8_no_delta;

    } else {

        mc_with_delta_func = ff_ivi_mc_4x4_delta;

        mc_no_delta_func   = ff_ivi_mc_4x4_no_delta;

    }



    for (mbn = 0, mb = tile->mbs; mbn < tile->num_MBs; mb++, mbn++) {

        is_intra = !mb->type;

        cbp      = mb->cbp;

        buf_offs = mb->buf_offs;



        quant = band->glob_quant + mb->q_delta;

        if (avctx->codec_id == AV_CODEC_ID_INDEO4)

            quant = av_clip(quant, 0, 31);

        else

            quant = av_clip(quant, 0, 23);



        scale_tab = is_intra ? band->intra_scale : band->inter_scale;

        if (scale_tab)

            quant = scale_tab[quant];



        if (!is_intra) {

            mv_x = mb->mv_x;

            mv_y = mb->mv_y;

            if (band->is_halfpel) {

                mc_type = ((mv_y & 1) << 1) | (mv_x & 1);

                mv_x >>= 1;

                mv_y >>= 1; /* convert halfpel vectors into fullpel ones */

            }

            if (mb->type) {

                int dmv_x, dmv_y, cx, cy;



                dmv_x = mb->mv_x >> band->is_halfpel;

                dmv_y = mb->mv_y >> band->is_halfpel;

                cx    = mb->mv_x &  band->is_halfpel;

                cy    = mb->mv_y &  band->is_halfpel;



                if (mb->xpos + dmv_x < 0 ||

                    mb->xpos + dmv_x + band->mb_size + cx > band->pitch ||

                    mb->ypos + dmv_y < 0 ||

                    mb->ypos + dmv_y + band->mb_size + cy > band->aheight) {

                    return AVERROR_INVALIDDATA;

                }

            }

        }



        for (blk = 0; blk < num_blocks; blk++) {

            /* adjust block position in the buffer according to its number */

            if (blk & 1) {

                buf_offs += blk_size;

            } else if (blk == 2) {

                buf_offs -= blk_size;

                buf_offs += blk_size * band->pitch;

            }



            if (cbp & 1) { /* block coded ? */

                ret = ivi_decode_coded_blocks(gb, band, mc_with_delta_func,

                                              mv_x, mv_y, &prev_dc, is_intra,

                                              mc_type, quant, buf_offs, avctx);

                if (ret < 0)

                    return ret;

            } else {

                /* block not coded */

                /* for intra blocks apply the dc slant transform */

                /* for inter - perform the motion compensation without delta */

                if (is_intra) {

                    if (band->dc_transform)

                        band->dc_transform(&prev_dc, band->buf + buf_offs,

                                           band->pitch, blk_size);

                } else {

                    ret = ivi_mc(mc_no_delta_func, band->buf, band->ref_buf,

                                 buf_offs, mv_x, mv_y, band->pitch, mc_type);

                    if (ret < 0)

                        return ret;

                }

            }



            cbp >>= 1;

        }// for blk

    }// for mbn



    align_get_bits(gb);



    return 0;

}

void checkasm_check_fixed_dsp(void)

{

    LOCAL_ALIGNED_32(int32_t, src0, [BUF_SIZE]);

    LOCAL_ALIGNED_32(int32_t, src1, [BUF_SIZE]);

    LOCAL_ALIGNED_32(int32_t, src2, [BUF_SIZE]);

    AVFixedDSPContext *fdsp = avpriv_alloc_fixed_dsp(1);



    randomize_buffers();

    if (check_func(fdsp->vector_fmul, "vector_fmul"))

        check_vector_fmul(src0, src1);

    if (check_func(fdsp->vector_fmul_add, "vector_fmul_add"))

        check_vector_fmul_add(src0, src1, src2);

    if (check_func(fdsp->vector_fmul_reverse, "vector_fmul_reverse"))

        check_vector_fmul(src0, src1);

    if (check_func(fdsp->vector_fmul_window, "vector_fmul_window"))

        check_vector_fmul_window(src0, src1, src2);

    if (check_func(fdsp->vector_fmul_window_scaled, "vector_fmul_window_scaled"))

        check_vector_fmul_window_scaled(src0, src1, src2);

    report("vector_fmul");

    if (check_func(fdsp->butterflies_fixed, "butterflies_fixed"))

        check_butterflies(src0, src1);

    report("butterflies_fixed");

    if (check_func(fdsp->scalarproduct_fixed, "scalarproduct_fixed"))

        check_scalarproduct_fixed(src0, src1);

    report("scalarproduct_fixed");



    av_freep(&fdsp);

}

int ff_read_riff_info(AVFormatContext *s, int64_t size)

{

    int64_t start, end, cur;

    AVIOContext *pb = s->pb;



    start = avio_tell(pb);

    end = start + size;



    while ((cur = avio_tell(pb)) >= 0 && cur <= end - 8 /* = tag + size */) {

        uint32_t chunk_code;

        int64_t chunk_size;

        char key[5] = {0};

        char *value;



        chunk_code = avio_rl32(pb);

        chunk_size = avio_rl32(pb);



        if (chunk_size > end || end - chunk_size < cur || chunk_size == UINT_MAX) {

            avio_seek(pb, -9, SEEK_CUR);

            chunk_code = avio_rl32(pb);

            chunk_size = avio_rl32(pb);

            if (chunk_size > end || end - chunk_size < cur || chunk_size == UINT_MAX) {

                av_log(s, AV_LOG_WARNING, "too big INFO subchunk\n");

                return AVERROR_INVALIDDATA;

            }

        }



        chunk_size += (chunk_size & 1);



        if (!chunk_code) {

            if (chunk_size)

                avio_skip(pb, chunk_size);

            continue;

        }



        value = av_mallocz(chunk_size + 1);

        if (!value) {

            av_log(s, AV_LOG_ERROR, "out of memory, unable to read INFO tag\n");

            return AVERROR(ENOMEM);

        }



        AV_WL32(key, chunk_code);



        if (avio_read(pb, value, chunk_size) != chunk_size) {

            av_log(s, AV_LOG_WARNING, "premature end of file while reading INFO tag\n");

        }



        av_dict_set(&s->metadata, key, value, AV_DICT_DONT_STRDUP_VAL);

    }



    return 0;

}

void ff_mpeg_flush(AVCodecContext *avctx){

    int i;

    MpegEncContext *s = avctx->priv_data;



    if(s==NULL || s->picture==NULL)

        return;



    for (i = 0; i < MAX_PICTURE_COUNT; i++)

        ff_mpeg_unref_picture(s, &s->picture[i]);

    s->current_picture_ptr = s->last_picture_ptr = s->next_picture_ptr = NULL;



    ff_mpeg_unref_picture(s, &s->current_picture);

    ff_mpeg_unref_picture(s, &s->last_picture);

    ff_mpeg_unref_picture(s, &s->next_picture);



    s->mb_x= s->mb_y= 0;



    s->parse_context.state= -1;

    s->parse_context.frame_start_found= 0;

    s->parse_context.overread= 0;

    s->parse_context.overread_index= 0;

    s->parse_context.index= 0;

    s->parse_context.last_index= 0;

    s->bitstream_buffer_size=0;

    s->pp_time=0;

}

