static int mp3_header_compress(AVBitStreamFilterContext *bsfc, AVCodecContext *avctx, const char *args,

                     uint8_t **poutbuf, int *poutbuf_size,

                     const uint8_t *buf, int buf_size, int keyframe){

    uint32_t header;

    int mode_extension;



    if(avctx->strict_std_compliance > FF_COMPLIANCE_EXPERIMENTAL){

        av_log(avctx, AV_LOG_ERROR, "not standards compliant\n");

        return -1;

    }



    header = (buf[0] << 24) | (buf[1] << 16) | (buf[2] << 8) | buf[3];

    mode_extension= (header>>4)&3;



    if(ff_mpa_check_header(header) < 0 || (header&0x70000) != 0x30000){

        *poutbuf= (uint8_t *) buf;

        *poutbuf_size= buf_size;



        av_log(avctx, AV_LOG_INFO, "cannot compress %08X\n", header);

        return 0;

    }



    *poutbuf_size= buf_size - 4;

    *poutbuf= av_malloc(buf_size - 4 + FF_INPUT_BUFFER_PADDING_SIZE);

    memcpy(*poutbuf, buf + 4, buf_size - 4 + FF_INPUT_BUFFER_PADDING_SIZE);



    if(avctx->channels==2){

        if((header & (3<<19)) != 3<<19){

            (*poutbuf)[1] &= 0x3F;

            (*poutbuf)[1] |= mode_extension<<6;

            FFSWAP(int, (*poutbuf)[1], (*poutbuf)[2]);

        }else{

            (*poutbuf)[1] &= 0x8F;

            (*poutbuf)[1] |= mode_extension<<4;

        }

    }



    return 1;

}

static int set_segment_filename(AVFormatContext *s)

{

    SegmentContext *seg = s->priv_data;

    AVFormatContext *oc = seg->avf;

    size_t size;



    if (seg->segment_idx_wrap)

        seg->segment_idx %= seg->segment_idx_wrap;

    if (seg->use_strftime) {

        time_t now0;

        struct tm *tm, tmpbuf;

        time(&now0);

        tm = localtime_r(&now0, &tmpbuf);

        if (!strftime(oc->filename, sizeof(oc->filename), s->filename, tm)) {

            av_log(oc, AV_LOG_ERROR, "Could not get segment filename with strftime\n");

            return AVERROR(EINVAL);

        }

    } else if (av_get_frame_filename(oc->filename, sizeof(oc->filename),

                                     s->filename, seg->segment_idx) < 0) {

        av_log(oc, AV_LOG_ERROR, "Invalid segment filename template '%s'\n", s->filename);

        return AVERROR(EINVAL);

    }



    /* copy modified name in list entry */

    size = strlen(av_basename(oc->filename)) + 1;

    if (seg->entry_prefix)

        size += strlen(seg->entry_prefix);



    seg->cur_entry.filename = av_mallocz(size);

    if (!seg->cur_entry.filename)

        return AVERROR(ENOMEM);

    snprintf(seg->cur_entry.filename, size, "%s%s",

             seg->entry_prefix ? seg->entry_prefix : "",

             av_basename(oc->filename));



    return 0;

}

static int hwmap_filter_frame(AVFilterLink *link, AVFrame *input)

{

    AVFilterContext *avctx = link->dst;

    AVFilterLink  *outlink = avctx->outputs[0];

    HWMapContext      *ctx = avctx->priv;

    AVFrame *map = NULL;

    int err;



    av_log(ctx, AV_LOG_DEBUG, "Filter input: %s, %ux%u (%"PRId64").\n",

           av_get_pix_fmt_name(input->format),

           input->width, input->height, input->pts);



    map = av_frame_alloc();

    if (!map) {

        err = AVERROR(ENOMEM);

        goto fail;

    }



    map->format = outlink->format;

    map->hw_frames_ctx = av_buffer_ref(ctx->hwframes_ref);

    if (!map->hw_frames_ctx) {

        err = AVERROR(ENOMEM);

        goto fail;

    }



    if (ctx->map_backwards && !input->hw_frames_ctx) {

        // If we mapped backwards from hardware to software, we need

        // to attach the hardware frame context to the input frame to

        // make the mapping visible to av_hwframe_map().

        input->hw_frames_ctx = av_buffer_ref(ctx->hwframes_ref);

        if (!input->hw_frames_ctx) {

            err = AVERROR(ENOMEM);

            goto fail;

        }

    }



    err = av_hwframe_map(map, input, ctx->mode);

    if (err < 0) {

        av_log(avctx, AV_LOG_ERROR, "Failed to map frame: %d.\n", err);

        goto fail;

    }



    err = av_frame_copy_props(map, input);

    if (err < 0)

        goto fail;



    av_frame_free(&input);



    av_log(ctx, AV_LOG_DEBUG, "Filter output: %s, %ux%u (%"PRId64").\n",

           av_get_pix_fmt_name(map->format),

           map->width, map->height, map->pts);



    return ff_filter_frame(outlink, map);



fail:

    av_frame_free(&input);

    av_frame_free(&map);

    return err;

}

static int opus_decode_packet(AVCodecContext *avctx, void *data,

                              int *got_frame_ptr, AVPacket *avpkt)

{

    OpusContext *c      = avctx->priv_data;

    AVFrame *frame      = data;

    const uint8_t *buf  = avpkt->data;

    int buf_size        = avpkt->size;

    int coded_samples   = 0;

    int decoded_samples = 0;

    int i, ret;



    for (i = 0; i < c->nb_streams; i++) {

        OpusStreamContext *s = &c->streams[i];

        s->out[0] =

        s->out[1] = NULL;

    }



    /* decode the header of the first sub-packet to find out the sample count */

    if (buf) {

        OpusPacket *pkt = &c->streams[0].packet;

        ret = ff_opus_parse_packet(pkt, buf, buf_size, c->nb_streams > 1);

        if (ret < 0) {

            av_log(avctx, AV_LOG_ERROR, "Error parsing the packet header.\n");

            return ret;

        }

        coded_samples += pkt->frame_count * pkt->frame_duration;

        c->streams[0].silk_samplerate = get_silk_samplerate(pkt->config);

    }



    frame->nb_samples = coded_samples + c->streams[0].delayed_samples;



    /* no input or buffered data => nothing to do */

    if (!frame->nb_samples) {

        *got_frame_ptr = 0;

        return 0;

    }



    /* setup the data buffers */

    ret = ff_get_buffer(avctx, frame, 0);

    if (ret < 0)

        return ret;

    frame->nb_samples = 0;



    for (i = 0; i < avctx->channels; i++) {

        ChannelMap *map = &c->channel_maps[i];

        if (!map->copy)

            c->streams[map->stream_idx].out[map->channel_idx] = (float*)frame->extended_data[i];

    }



    for (i = 0; i < c->nb_streams; i++)

        c->streams[i].out_size = frame->linesize[0];



    /* decode each sub-packet */

    for (i = 0; i < c->nb_streams; i++) {

        OpusStreamContext *s = &c->streams[i];



        if (i && buf) {

            ret = ff_opus_parse_packet(&s->packet, buf, buf_size, i != c->nb_streams - 1);

            if (ret < 0) {

                av_log(avctx, AV_LOG_ERROR, "Error parsing the packet header.\n");

                return ret;

            }

            if (coded_samples != s->packet.frame_count * s->packet.frame_duration) {

                av_log(avctx, AV_LOG_ERROR,

                       "Mismatching coded sample count in substream %d.\n", i);

                return AVERROR_INVALIDDATA;

            }



            s->silk_samplerate = get_silk_samplerate(s->packet.config);

        }



        ret = opus_decode_subpacket(&c->streams[i], buf,

                                    s->packet.data_size, coded_samples);

        if (ret < 0)

            return ret;

        if (decoded_samples && ret != decoded_samples) {

            av_log(avctx, AV_LOG_ERROR, "Different numbers of decoded samples "

                   "in a multi-channel stream\n");

            return AVERROR_INVALIDDATA;

        }

        decoded_samples = ret;

        buf      += s->packet.packet_size;

        buf_size -= s->packet.packet_size;

    }



    for (i = 0; i < avctx->channels; i++) {

        ChannelMap *map = &c->channel_maps[i];



        /* handle copied channels */

        if (map->copy) {

            memcpy(frame->extended_data[i],

                   frame->extended_data[map->copy_idx],

                   frame->linesize[0]);

        } else if (map->silence) {

            memset(frame->extended_data[i], 0, frame->linesize[0]);

        }



        if (c->gain_i) {

            c->fdsp->vector_fmul_scalar((float*)frame->extended_data[i],

                                       (float*)frame->extended_data[i],

                                       c->gain, FFALIGN(decoded_samples, 8));

        }

    }



    frame->nb_samples = decoded_samples;

    *got_frame_ptr    = !!decoded_samples;



    return avpkt->size;

}

static void av_always_inline filter_mb_dir(H264Context *h, int mb_x, int mb_y, uint8_t *img_y, uint8_t *img_cb, uint8_t *img_cr, unsigned int linesize, unsigned int uvlinesize, int mb_xy, int mb_type, int mvy_limit, int first_vertical_edge_done, int dir) {

    MpegEncContext * const s = &h->s;

    int edge;

    const int mbm_xy = dir == 0 ? mb_xy -1 : h->top_mb_xy;

    const int mbm_type = s->current_picture.mb_type[mbm_xy];

    int (*ref2frm) [64] = h->ref2frm[ h->slice_num          &(MAX_SLICES-1) ][0] + (MB_MBAFF ? 20 : 2);

    int (*ref2frmm)[64] = h->ref2frm[ h->slice_table[mbm_xy]&(MAX_SLICES-1) ][0] + (MB_MBAFF ? 20 : 2);

    int start = h->slice_table[mbm_xy] == 0xFFFF ? 1 : 0;



    const int edges = (mb_type & (MB_TYPE_16x16|MB_TYPE_SKIP))

                              == (MB_TYPE_16x16|MB_TYPE_SKIP) ? 1 : 4;

    // how often to recheck mv-based bS when iterating between edges

    const int mask_edge = (mb_type & (MB_TYPE_16x16 | (MB_TYPE_16x8 << dir))) ? 3 :

                          (mb_type & (MB_TYPE_8x16 >> dir)) ? 1 : 0;

    // how often to recheck mv-based bS when iterating along each edge

    const int mask_par0 = mb_type & (MB_TYPE_16x16 | (MB_TYPE_8x16 >> dir));



    if (first_vertical_edge_done) {

        start = 1;

    }



    if (h->deblocking_filter==2 && h->slice_table[mbm_xy] != h->slice_table[mb_xy])

        start = 1;



    if (FRAME_MBAFF && (dir == 1) && ((mb_y&1) == 0) && start == 0

        && !IS_INTERLACED(mb_type)

        && IS_INTERLACED(mbm_type)

        ) {

        // This is a special case in the norm where the filtering must

        // be done twice (one each of the field) even if we are in a

        // frame macroblock.

        //

        static const int nnz_idx[4] = {4,5,6,3};

        unsigned int tmp_linesize   = 2 *   linesize;

        unsigned int tmp_uvlinesize = 2 * uvlinesize;

        int mbn_xy = mb_xy - 2 * s->mb_stride;

        int qp;

        int i, j;

        int16_t bS[4];



        for(j=0; j<2; j++, mbn_xy += s->mb_stride){

            if( IS_INTRA(mb_type) ||

                IS_INTRA(s->current_picture.mb_type[mbn_xy]) ) {

                bS[0] = bS[1] = bS[2] = bS[3] = 3;

            } else {

                const uint8_t *mbn_nnz = h->non_zero_count[mbn_xy];

                for( i = 0; i < 4; i++ ) {

                    if( h->non_zero_count_cache[scan8[0]+i] != 0 ||

                        mbn_nnz[nnz_idx[i]] != 0 )

                        bS[i] = 2;

                    else

                        bS[i] = 1;

                }

            }

            // Do not use s->qscale as luma quantizer because it has not the same

            // value in IPCM macroblocks.

            qp = ( s->current_picture.qscale_table[mb_xy] + s->current_picture.qscale_table[mbn_xy] + 1 ) >> 1;

            tprintf(s->avctx, "filter mb:%d/%d dir:%d edge:%d, QPy:%d ls:%d uvls:%d", mb_x, mb_y, dir, edge, qp, tmp_linesize, tmp_uvlinesize);

            { int i; for (i = 0; i < 4; i++) tprintf(s->avctx, " bS[%d]:%d", i, bS[i]); tprintf(s->avctx, "\n"); }

            filter_mb_edgeh( h, &img_y[j*linesize], tmp_linesize, bS, qp );

            filter_mb_edgech( h, &img_cb[j*uvlinesize], tmp_uvlinesize, bS,

                              ( h->chroma_qp[0] + get_chroma_qp( h, 0, s->current_picture.qscale_table[mbn_xy] ) + 1 ) >> 1);

            filter_mb_edgech( h, &img_cr[j*uvlinesize], tmp_uvlinesize, bS,

                              ( h->chroma_qp[1] + get_chroma_qp( h, 1, s->current_picture.qscale_table[mbn_xy] ) + 1 ) >> 1);

        }



        start = 1;

    }



    /* Calculate bS */

    for( edge = start; edge < edges; edge++ ) {

        /* mbn_xy: neighbor macroblock */

        const int mbn_xy = edge > 0 ? mb_xy : mbm_xy;

        const int mbn_type = s->current_picture.mb_type[mbn_xy];

        int (*ref2frmn)[64] = edge > 0 ? ref2frm : ref2frmm;

        int16_t bS[4];

        int qp;



        if( (edge&1) && IS_8x8DCT(mb_type) )

            continue;



        if( IS_INTRA(mb_type) ||

            IS_INTRA(mbn_type) ) {

            int value;

            if (edge == 0) {

                if (   (!IS_INTERLACED(mb_type) && !IS_INTERLACED(mbm_type))

                    || ((FRAME_MBAFF || (s->picture_structure != PICT_FRAME)) && (dir == 0))

                ) {

                    value = 4;

                } else {

                    value = 3;

                }

            } else {

                value = 3;

            }

            bS[0] = bS[1] = bS[2] = bS[3] = value;

        } else {

            int i, l;

            int mv_done;



            if( edge & mask_edge ) {

                bS[0] = bS[1] = bS[2] = bS[3] = 0;

                mv_done = 1;

            }

            else if( FRAME_MBAFF && IS_INTERLACED(mb_type ^ mbn_type)) {

                bS[0] = bS[1] = bS[2] = bS[3] = 1;

                mv_done = 1;

            }

            else if( mask_par0 && (edge || (mbn_type & (MB_TYPE_16x16 | (MB_TYPE_8x16 >> dir)))) ) {

                int b_idx= 8 + 4 + edge * (dir ? 8:1);

                int bn_idx= b_idx - (dir ? 8:1);

                int v = 0;



                for( l = 0; !v && l < 1 + (h->slice_type_nos == FF_B_TYPE); l++ ) {

                    v |= ref2frm[l][h->ref_cache[l][b_idx]] != ref2frmn[l][h->ref_cache[l][bn_idx]] ||

                         FFABS( h->mv_cache[l][b_idx][0] - h->mv_cache[l][bn_idx][0] ) >= 4 ||

                         FFABS( h->mv_cache[l][b_idx][1] - h->mv_cache[l][bn_idx][1] ) >= mvy_limit;

                }



                if(h->slice_type_nos == FF_B_TYPE && v){

                    v=0;

                    for( l = 0; !v && l < 2; l++ ) {

                        int ln= 1-l;

                        v |= ref2frm[l][h->ref_cache[l][b_idx]] != ref2frmn[ln][h->ref_cache[ln][bn_idx]] ||

                            FFABS( h->mv_cache[l][b_idx][0] - h->mv_cache[ln][bn_idx][0] ) >= 4 ||

                            FFABS( h->mv_cache[l][b_idx][1] - h->mv_cache[ln][bn_idx][1] ) >= mvy_limit;

                    }

                }



                bS[0] = bS[1] = bS[2] = bS[3] = v;

                mv_done = 1;

            }

            else

                mv_done = 0;



            for( i = 0; i < 4; i++ ) {

                int x = dir == 0 ? edge : i;

                int y = dir == 0 ? i    : edge;

                int b_idx= 8 + 4 + x + 8*y;

                int bn_idx= b_idx - (dir ? 8:1);



                if( h->non_zero_count_cache[b_idx] != 0 ||

                    h->non_zero_count_cache[bn_idx] != 0 ) {

                    bS[i] = 2;

                }

                else if(!mv_done)

                {

                    bS[i] = 0;

                    for( l = 0; l < 1 + (h->slice_type_nos == FF_B_TYPE); l++ ) {

                        if( ref2frm[l][h->ref_cache[l][b_idx]] != ref2frmn[l][h->ref_cache[l][bn_idx]] ||

                            FFABS( h->mv_cache[l][b_idx][0] - h->mv_cache[l][bn_idx][0] ) >= 4 ||

                            FFABS( h->mv_cache[l][b_idx][1] - h->mv_cache[l][bn_idx][1] ) >= mvy_limit ) {

                            bS[i] = 1;

                            break;

                        }

                    }



                    if(h->slice_type_nos == FF_B_TYPE && bS[i]){

                        bS[i] = 0;

                        for( l = 0; l < 2; l++ ) {

                            int ln= 1-l;

                            if( ref2frm[l][h->ref_cache[l][b_idx]] != ref2frmn[ln][h->ref_cache[ln][bn_idx]] ||

                                FFABS( h->mv_cache[l][b_idx][0] - h->mv_cache[ln][bn_idx][0] ) >= 4 ||

                                FFABS( h->mv_cache[l][b_idx][1] - h->mv_cache[ln][bn_idx][1] ) >= mvy_limit ) {

                                bS[i] = 1;

                                break;

                            }

                        }

                    }

                }

            }



            if(bS[0]+bS[1]+bS[2]+bS[3] == 0)

                continue;

        }



        /* Filter edge */

        // Do not use s->qscale as luma quantizer because it has not the same

        // value in IPCM macroblocks.

        qp = ( s->current_picture.qscale_table[mb_xy] + s->current_picture.qscale_table[mbn_xy] + 1 ) >> 1;

        //tprintf(s->avctx, "filter mb:%d/%d dir:%d edge:%d, QPy:%d, QPc:%d, QPcn:%d\n", mb_x, mb_y, dir, edge, qp, h->chroma_qp, s->current_picture.qscale_table[mbn_xy]);

        tprintf(s->avctx, "filter mb:%d/%d dir:%d edge:%d, QPy:%d ls:%d uvls:%d", mb_x, mb_y, dir, edge, qp, linesize, uvlinesize);

        { int i; for (i = 0; i < 4; i++) tprintf(s->avctx, " bS[%d]:%d", i, bS[i]); tprintf(s->avctx, "\n"); }

        if( dir == 0 ) {

            filter_mb_edgev( h, &img_y[4*edge], linesize, bS, qp );

            if( (edge&1) == 0 ) {

                filter_mb_edgecv( h, &img_cb[2*edge], uvlinesize, bS,

                                  ( h->chroma_qp[0] + get_chroma_qp( h, 0, s->current_picture.qscale_table[mbn_xy] ) + 1 ) >> 1);

                filter_mb_edgecv( h, &img_cr[2*edge], uvlinesize, bS,

                                  ( h->chroma_qp[1] + get_chroma_qp( h, 1, s->current_picture.qscale_table[mbn_xy] ) + 1 ) >> 1);

            }

        } else {

            filter_mb_edgeh( h, &img_y[4*edge*linesize], linesize, bS, qp );

            if( (edge&1) == 0 ) {

                filter_mb_edgech( h, &img_cb[2*edge*uvlinesize], uvlinesize, bS,

                                  ( h->chroma_qp[0] + get_chroma_qp( h, 0, s->current_picture.qscale_table[mbn_xy] ) + 1 ) >> 1);

                filter_mb_edgech( h, &img_cr[2*edge*uvlinesize], uvlinesize, bS,

                                  ( h->chroma_qp[1] + get_chroma_qp( h, 1, s->current_picture.qscale_table[mbn_xy] ) + 1 ) >> 1);

            }

        }

    }

}

static int vorbis_parse_setup_hdr_modes(vorbis_context *vc) {

    GetBitContext *gb=&vc->gb;

    uint_fast8_t i;



    vc->mode_count=get_bits(gb, 6)+1;

    vc->modes=(vorbis_mode *)av_mallocz(vc->mode_count * sizeof(vorbis_mode));



    AV_DEBUG(" There are %d modes.\n", vc->mode_count);



    for(i=0;i<vc->mode_count;++i) {

        vorbis_mode *mode_setup=&vc->modes[i];



        mode_setup->blockflag=get_bits1(gb);

        mode_setup->windowtype=get_bits(gb, 16); //FIXME check

        mode_setup->transformtype=get_bits(gb, 16); //FIXME check

        mode_setup->mapping=get_bits(gb, 8); //FIXME check



        AV_DEBUG(" %d mode: blockflag %d, windowtype %d, transformtype %d, mapping %d \n", i, mode_setup->blockflag, mode_setup->windowtype, mode_setup->transformtype, mode_setup->mapping);

    }

    return 0;

}

const uint8_t *ff_h264_decode_nal(H264Context *h, const uint8_t *src,

                                  int *dst_length, int *consumed, int length)

{

    int i, si, di;

    uint8_t *dst;

    int bufidx;



    // src[0]&0x80; // forbidden bit

    h->nal_ref_idc   = src[0] >> 5;

    h->nal_unit_type = src[0] & 0x1F;



    src++;

    length--;



#define STARTCODE_TEST                                                  \

    if (i + 2 < length && src[i + 1] == 0 && src[i + 2] <= 3) {         \

        if (src[i + 2] != 3) {                                          \

            /* startcode, so we must be past the end */                 \

            length = i;                                                 \

        }                                                               \

        break;                                                          \

    }



#if HAVE_FAST_UNALIGNED

#define FIND_FIRST_ZERO                                                 \

    if (i > 0 && !src[i])                                               \

        i--;                                                            \

    while (src[i])                                                      \

        i++



#if HAVE_FAST_64BIT

    for (i = 0; i + 1 < length; i += 9) {

        if (!((~AV_RN64A(src + i) &

               (AV_RN64A(src + i) - 0x0100010001000101ULL)) &

              0x8000800080008080ULL))

            continue;

        FIND_FIRST_ZERO;

        STARTCODE_TEST;

        i -= 7;

    }

#else

    for (i = 0; i + 1 < length; i += 5) {

        if (!((~AV_RN32A(src + i) &

               (AV_RN32A(src + i) - 0x01000101U)) &

              0x80008080U))

            continue;

        FIND_FIRST_ZERO;

        STARTCODE_TEST;

        i -= 3;

    }

#endif

#else

    for (i = 0; i + 1 < length; i += 2) {

        if (src[i])

            continue;

        if (i > 0 && src[i - 1] == 0)

            i--;

        STARTCODE_TEST;

    }

#endif



    if (i >= length - 1) { // no escaped 0

        *dst_length = length;

        *consumed   = length + 1; // +1 for the header

        return src;

    }



    // use second escape buffer for inter data

    bufidx = h->nal_unit_type == NAL_DPC ? 1 : 0;

    av_fast_malloc(&h->rbsp_buffer[bufidx], &h->rbsp_buffer_size[bufidx],

                   length + FF_INPUT_BUFFER_PADDING_SIZE);

    dst = h->rbsp_buffer[bufidx];



    if (dst == NULL)

        return NULL;



    memcpy(dst, src, i);

    si = di = i;

    while (si + 2 < length) {

        // remove escapes (very rare 1:2^22)

        if (src[si + 2] > 3) {

            dst[di++] = src[si++];

            dst[di++] = src[si++];

        } else if (src[si] == 0 && src[si + 1] == 0) {

            if (src[si + 2] == 3) { // escape

                dst[di++]  = 0;

                dst[di++]  = 0;

                si        += 3;

                continue;

            } else // next start code

                goto nsc;

        }



        dst[di++] = src[si++];

    }

    while (si < length)

        dst[di++] = src[si++];



nsc:

    memset(dst + di, 0, FF_INPUT_BUFFER_PADDING_SIZE);



    *dst_length = di;

    *consumed   = si + 1; // +1 for the header

    /* FIXME store exact number of bits in the getbitcontext

     * (it is needed for decoding) */

    return dst;

}

static int decode_ics_info(AACContext *ac, IndividualChannelStream *ics,

                           GetBitContext *gb)

{

    if (get_bits1(gb)) {

        av_log(ac->avctx, AV_LOG_ERROR, "Reserved bit set.\n");

        return AVERROR_INVALIDDATA;

    }

    ics->window_sequence[1] = ics->window_sequence[0];

    ics->window_sequence[0] = get_bits(gb, 2);

    ics->use_kb_window[1]   = ics->use_kb_window[0];

    ics->use_kb_window[0]   = get_bits1(gb);

    ics->num_window_groups  = 1;

    ics->group_len[0]       = 1;

    if (ics->window_sequence[0] == EIGHT_SHORT_SEQUENCE) {

        int i;

        ics->max_sfb = get_bits(gb, 4);

        for (i = 0; i < 7; i++) {

            if (get_bits1(gb)) {

                ics->group_len[ics->num_window_groups - 1]++;

            } else {

                ics->num_window_groups++;

                ics->group_len[ics->num_window_groups - 1] = 1;

            }

        }

        ics->num_windows       = 8;

        ics->swb_offset        =    ff_swb_offset_128[ac->m4ac.sampling_index];

        ics->num_swb           =   ff_aac_num_swb_128[ac->m4ac.sampling_index];

        ics->tns_max_bands     = ff_tns_max_bands_128[ac->m4ac.sampling_index];

        ics->predictor_present = 0;

    } else {

        ics->max_sfb               = get_bits(gb, 6);

        ics->num_windows           = 1;

        ics->swb_offset            =    ff_swb_offset_1024[ac->m4ac.sampling_index];

        ics->num_swb               =   ff_aac_num_swb_1024[ac->m4ac.sampling_index];

        ics->tns_max_bands         = ff_tns_max_bands_1024[ac->m4ac.sampling_index];

        ics->predictor_present     = get_bits1(gb);

        ics->predictor_reset_group = 0;

        if (ics->predictor_present) {

            if (ac->m4ac.object_type == AOT_AAC_MAIN) {

                if (decode_prediction(ac, ics, gb)) {

                    return AVERROR_INVALIDDATA;

                }

            } else if (ac->m4ac.object_type == AOT_AAC_LC) {

                av_log(ac->avctx, AV_LOG_ERROR, "Prediction is not allowed in AAC-LC.\n");

                return AVERROR_INVALIDDATA;

            } else {

                if ((ics->ltp.present = get_bits(gb, 1)))

                    decode_ltp(ac, &ics->ltp, gb, ics->max_sfb);

            }

        }

    }



    if (ics->max_sfb > ics->num_swb) {

        av_log(ac->avctx, AV_LOG_ERROR,

               "Number of scalefactor bands in group (%d) exceeds limit (%d).\n",

               ics->max_sfb, ics->num_swb);

        return AVERROR_INVALIDDATA;

    }



    return 0;

}

static int mov_read_udta_string(MOVContext *c, AVIOContext *pb, MOVAtom atom)

{

    char tmp_key[5];

    char key2[32], language[4] = {0};

