    case MKTAG(0xa9,'o','p','e'): key = "original_artist"; break;

    case MKTAG(0xa9,'p','r','d'): key = "producer";  break;

    case MKTAG(0xa9,'p','r','f'): key = "performers"; break;

    case MKTAG(0xa9,'r','e','q'): key = "playback_requirements"; break;

    case MKTAG(0xa9,'s','r','c'): key = "original_source"; break;

    case MKTAG(0xa9,'s','t','3'): key = "subtitle";  break;

    case MKTAG(0xa9,'s','w','r'): key = "encoder";   break;

    case MKTAG(0xa9,'t','o','o'): key = "encoder";   break;

    case MKTAG(0xa9,'t','r','k'): key = "track";     break;

    case MKTAG(0xa9,'u','r','l'): key = "URL";       break;

    case MKTAG(0xa9,'w','r','n'): key = "warning";   break;

    case MKTAG(0xa9,'w','r','t'): key = "composer";  break;

    case MKTAG(0xa9,'x','y','z'): key = "location";  break;

    }

retry:

    if (c->itunes_metadata && atom.size > 8) {

        int data_size = avio_rb32(pb);

        int tag = avio_rl32(pb);

        if (tag == MKTAG('d','a','t','a') && data_size <= atom.size) {

            data_type = avio_rb32(pb); // type

            avio_rb32(pb); // unknown

            str_size = data_size - 16;

            atom.size -= 16;



            if (atom.type == MKTAG('c', 'o', 'v', 'r')) {

                int ret = mov_read_covr(c, pb, data_type, str_size);

                if (ret < 0) {

                    av_log(c->fc, AV_LOG_ERROR, "Error parsing cover art.\n");

                }

                return ret;

            } else if (!key && c->found_hdlr_mdta && c->meta_keys) {

                uint32_t index = AV_RB32(&atom.type);

                if (index < c->meta_keys_count) {

                    key = c->meta_keys[index];

                } else {

                    av_log(c->fc, AV_LOG_WARNING,

                           "The index of 'data' is out of range: %d >= %d.\n",

                           index, c->meta_keys_count);

                }

            }

        } else return 0;

    } else if (atom.size > 4 && key && !c->itunes_metadata && !raw) {

        str_size = avio_rb16(pb); // string length

        if (str_size > atom.size) {

            raw = 1;

            avio_seek(pb, -2, SEEK_CUR);

            av_log(c->fc, AV_LOG_WARNING, "UDTA parsing failed retrying raw\n");

            goto retry;

        }

        langcode = avio_rb16(pb);

        ff_mov_lang_to_iso639(langcode, language);

        atom.size -= 4;

    } else

        str_size = atom.size;



    if (c->export_all && !key) {

        snprintf(tmp_key, 5, "%.4s", (char*)&atom.type);

        key = tmp_key;

    }



    if (!key)

        return 0;

    if (atom.size < 0 || str_size >= INT_MAX/2)

        return AVERROR_INVALIDDATA;



    // Allocates enough space if data_type is a float32 number, otherwise

    // worst-case requirement for output string in case of utf8 coded input

    num = (data_type == 23);

    str_size_alloc = (num ? 512 : (raw ? str_size : str_size * 2)) + 1;

    str = av_mallocz(str_size_alloc);

    if (!str)

        return AVERROR(ENOMEM);



    if (parse)

        parse(c, pb, str_size, key);

    else {

        if (!raw && (data_type == 3 || (data_type == 0 && (langcode < 0x400 || langcode == 0x7fff)))) { // MAC Encoded

            mov_read_mac_string(c, pb, str_size, str, str_size_alloc);

        } else if (data_type == 23 && str_size >= 4) {  // BE float32

            float val = av_int2float(avio_rb32(pb));

            if (snprintf(str, str_size_alloc, "%f", val) >= str_size_alloc) {

                av_log(c->fc, AV_LOG_ERROR,

                       "Failed to store the float32 number (%f) in string.\n", val);


                return AVERROR_INVALIDDATA;

            }

        } else {

            int ret = ffio_read_size(pb, str, str_size);

            if (ret < 0) {


                return ret;

            }

            str[str_size] = 0;

        }

        c->fc->event_flags |= AVFMT_EVENT_FLAG_METADATA_UPDATED;

        av_dict_set(&c->fc->metadata, key, str, 0);

        if (*language && strcmp(language, "und")) {

            snprintf(key2, sizeof(key2), "%s-%s", key, language);

            av_dict_set(&c->fc->metadata, key2, str, 0);

        }

    }

    av_log(c->fc, AV_LOG_TRACE, "lang \"%3s\" ", language);

    av_log(c->fc, AV_LOG_TRACE, "tag \"%s\" value \"%s\" atom \"%.4s\" %d %"PRId64"\n",

            key, str, (char*)&atom.type, str_size_alloc, atom.size);



    av_freep(&str);

    return 0;

}

static void mov_text_style_cb(void *priv, const char style, int close)

{

    MovTextContext *s = priv;

    if (!close) {

        if (!(s->box_flags & STYL_BOX)) {   //first style entry



            s->style_attributes_temp = av_malloc(sizeof(*s->style_attributes_temp));



            if (!s->style_attributes_temp) {

                av_bprint_clear(&s->buffer);

                s->box_flags &= ~STYL_BOX;


            }



            s->style_attributes_temp->style_flag = 0;

            s->style_attributes_temp->style_start = AV_RB16(&s->text_pos);

        } else {

            if (s->style_attributes_temp->style_flag) { //break the style record here and start a new one

                s->style_attributes_temp->style_end = AV_RB16(&s->text_pos);

                av_dynarray_add(&s->style_attributes, &s->count, s->style_attributes_temp);

                s->style_attributes_temp = av_malloc(sizeof(*s->style_attributes_temp));

                if (!s->style_attributes_temp) {

                    mov_text_cleanup(s);

                    av_bprint_clear(&s->buffer);

                    s->box_flags &= ~STYL_BOX;


                }



                s->style_attributes_temp->style_flag = s->style_attributes[s->count - 1]->style_flag;

                s->style_attributes_temp->style_start = AV_RB16(&s->text_pos);

            } else {

                s->style_attributes_temp->style_flag = 0;

                s->style_attributes_temp->style_start = AV_RB16(&s->text_pos);

            }

        }

        switch (style){

        case 'b':

            s->style_attributes_temp->style_flag |= STYLE_FLAG_BOLD;

            break;

        case 'i':

            s->style_attributes_temp->style_flag |= STYLE_FLAG_ITALIC;

            break;

        case 'u':

            s->style_attributes_temp->style_flag |= STYLE_FLAG_UNDERLINE;

            break;

        }




    } else {

        s->style_attributes_temp->style_end = AV_RB16(&s->text_pos);

        av_dynarray_add(&s->style_attributes, &s->count, s->style_attributes_temp);



        s->style_attributes_temp = av_malloc(sizeof(*s->style_attributes_temp));



        if (!s->style_attributes_temp) {

            mov_text_cleanup(s);

            av_bprint_clear(&s->buffer);

            s->box_flags &= ~STYL_BOX;


        }



        s->style_attributes_temp->style_flag = s->style_attributes[s->count - 1]->style_flag;

        switch (style){

        case 'b':

            s->style_attributes_temp->style_flag &= ~STYLE_FLAG_BOLD;

            break;

        case 'i':

            s->style_attributes_temp->style_flag &= ~STYLE_FLAG_ITALIC;

            break;

        case 'u':

            s->style_attributes_temp->style_flag &= ~STYLE_FLAG_UNDERLINE;

            break;

        }

        if (s->style_attributes_temp->style_flag) { //start of new style record

            s->style_attributes_temp->style_start = AV_RB16(&s->text_pos);

        }

    }

    s->box_flags |= STYL_BOX;

}

static int compute_pkt_fields2(AVStream *st, AVPacket *pkt){

    int delay = FFMAX(st->codec->has_b_frames, !!st->codec->max_b_frames);

    int num, den, frame_size, i;



//    av_log(st->codec, AV_LOG_DEBUG, "av_write_frame: pts:%"PRId64" dts:%"PRId64" cur_dts:%"PRId64" b:%d size:%d st:%d\n", pkt->pts, pkt->dts, st->cur_dts, delay, pkt->size, pkt->stream_index);



/*    if(pkt->pts == AV_NOPTS_VALUE && pkt->dts == AV_NOPTS_VALUE)

        return -1;*/



    /* duration field */

    if (pkt->duration == 0) {

        compute_frame_duration(&num, &den, st, NULL, pkt);

        if (den && num) {

            pkt->duration = av_rescale(1, num * (int64_t)st->time_base.den, den * (int64_t)st->time_base.num);

        }

    }



    if(pkt->pts == AV_NOPTS_VALUE && pkt->dts != AV_NOPTS_VALUE && delay==0)

        pkt->pts= pkt->dts;



    //XXX/FIXME this is a temporary hack until all encoders output pts

    if((pkt->pts == 0 || pkt->pts == AV_NOPTS_VALUE) && pkt->dts == AV_NOPTS_VALUE && !delay){

        pkt->dts=

//        pkt->pts= st->cur_dts;

        pkt->pts= st->pts.val;

    }



    //calculate dts from pts

    if(pkt->pts != AV_NOPTS_VALUE && pkt->dts == AV_NOPTS_VALUE){

        st->pts_buffer[0]= pkt->pts;

        for(i=1; i<delay+1 && st->pts_buffer[i] == AV_NOPTS_VALUE; i++)

            st->pts_buffer[i]= (i-delay-1) * pkt->duration;

        for(i=0; i<delay && st->pts_buffer[i] > st->pts_buffer[i+1]; i++)

            FFSWAP(int64_t, st->pts_buffer[i], st->pts_buffer[i+1]);



        pkt->dts= st->pts_buffer[0];

    }



    if(st->cur_dts && st->cur_dts != AV_NOPTS_VALUE && st->cur_dts >= pkt->dts){

        av_log(st->codec, AV_LOG_ERROR, "error, non monotone timestamps %"PRId64" >= %"PRId64"\n", st->cur_dts, pkt->dts);

        return -1;

    }

    if(pkt->dts != AV_NOPTS_VALUE && pkt->pts != AV_NOPTS_VALUE && pkt->pts < pkt->dts){

        av_log(st->codec, AV_LOG_ERROR, "error, pts < dts\n");

        return -1;

    }



//    av_log(NULL, AV_LOG_DEBUG, "av_write_frame: pts2:%"PRId64" dts2:%"PRId64"\n", pkt->pts, pkt->dts);

    st->cur_dts= pkt->dts;

    st->pts.val= pkt->dts;



    /* update pts */

    switch (st->codec->codec_type) {

    case CODEC_TYPE_AUDIO:

        frame_size = get_audio_frame_size(st->codec, pkt->size);



        /* HACK/FIXME, we skip the initial 0 size packets as they are most

           likely equal to the encoder delay, but it would be better if we

           had the real timestamps from the encoder */

        if (frame_size >= 0 && (pkt->size || st->pts.num!=st->pts.den>>1 || st->pts.val)) {

            av_frac_add(&st->pts, (int64_t)st->time_base.den * frame_size);

        }

        break;

    case CODEC_TYPE_VIDEO:

        av_frac_add(&st->pts, (int64_t)st->time_base.den * st->codec->time_base.num);

        break;

    default:

        break;

    }

    return 0;

}

static int dnxhd_encode_fast(AVCodecContext *avctx, DNXHDEncContext *ctx)

{

    int max_bits = 0;

    int ret, x, y;

    if ((ret = dnxhd_find_qscale(ctx)) < 0)

        return ret;

    for (y = 0; y < ctx->m.mb_height; y++) {

        for (x = 0; x < ctx->m.mb_width; x++) {

            int mb = y * ctx->m.mb_width + x;

            int rc = (ctx->qscale * ctx->m.mb_num ) + mb;

            int delta_bits;

            ctx->mb_qscale[mb] = ctx->qscale;

            ctx->mb_bits[mb] = ctx->mb_rc[rc].bits;

            max_bits += ctx->mb_rc[rc].bits;

            if (!RC_VARIANCE) {

                delta_bits = ctx->mb_rc[rc].bits -

                             ctx->mb_rc[rc + ctx->m.mb_num].bits;

                ctx->mb_cmp[mb].mb = mb;

                ctx->mb_cmp[mb].value =

                    delta_bits ? ((ctx->mb_rc[rc].ssd -

                                   ctx->mb_rc[rc + ctx->m.mb_num].ssd) * 100) /

                                  delta_bits

                               : INT_MIN; // avoid increasing qscale

            }

        }

        max_bits += 31; // worst padding

    }

    if (!ret) {

        if (RC_VARIANCE)

            avctx->execute2(avctx, dnxhd_mb_var_thread,

                            NULL, NULL, ctx->m.mb_height);

        radix_sort(ctx->mb_cmp, ctx->m.mb_num);

        for (x = 0; x < ctx->m.mb_num && max_bits > ctx->frame_bits; x++) {

            int mb = ctx->mb_cmp[x].mb;

            int rc = (ctx->qscale * ctx->m.mb_num ) + mb;

            max_bits -= ctx->mb_rc[rc].bits -

                        ctx->mb_rc[rc + ctx->m.mb_num].bits;

            ctx->mb_qscale[mb] = ctx->qscale + 1;

            ctx->mb_bits[mb]   = ctx->mb_rc[rc + ctx->m.mb_num].bits;

        }

    }

    return 0;

}

static int img_read_header(AVFormatContext *s1, AVFormatParameters *ap)

{

    VideoData *s = s1->priv_data;

    int ret, first_index, last_index;

    char buf[1024];

    ByteIOContext pb1, *f = &pb1;

    AVStream *st;



    st = av_new_stream(s1, 0);

    if (!st) {

        av_free(s);

        return -ENOMEM;

    }



    if (ap && ap->image_format)

        s->img_fmt = ap->image_format;



    strcpy(s->path, s1->filename);

    s->img_number = 0;



    /* find format */

    if (s1->iformat->flags & AVFMT_NOFILE)

        s->is_pipe = 0;

    else

        s->is_pipe = 1;



    if (!ap || !ap->frame_rate) {

        st->codec.frame_rate      = 25;

        st->codec.frame_rate_base = 1;

    } else {

        st->codec.frame_rate      = ap->frame_rate;

        st->codec.frame_rate_base = ap->frame_rate_base;

    }



    if (!s->is_pipe) {

        if (find_image_range(&first_index, &last_index, s->path) < 0)

            goto fail;

        s->img_number = first_index;

        /* compute duration */

        st->start_time = 0;

        st->duration = ((int64_t)AV_TIME_BASE * 

                        (last_index - first_index + 1) * 

                        st->codec.frame_rate_base) / st->codec.frame_rate;

        if (get_frame_filename(buf, sizeof(buf), s->path, s->img_number) < 0)

            goto fail;

        if (url_fopen(f, buf, URL_RDONLY) < 0)

            goto fail;

    } else {

        f = &s1->pb;

    }



    ret = av_read_image(f, s1->filename, s->img_fmt, read_header_alloc_cb, s);

    if (ret < 0)

        goto fail1;



    if (!s->is_pipe) {

        url_fclose(f);

    } else {

        url_fseek(f, 0, SEEK_SET);

    }



    st->codec.codec_type = CODEC_TYPE_VIDEO;

    st->codec.codec_id = CODEC_ID_RAWVIDEO;

    st->codec.width = s->width;

    st->codec.height = s->height;

    st->codec.pix_fmt = s->pix_fmt;

    s->img_size = avpicture_get_size(s->pix_fmt, s->width, s->height);



    return 0;

 fail1:

    if (!s->is_pipe)

        url_fclose(f);

 fail:

    av_free(s);

    return -EIO;

}

static int read_restart_header(MLPDecodeContext *m, BitstreamContext *bc,

                               const uint8_t *buf, unsigned int substr)

{

    SubStream *s = &m->substream[substr];

    unsigned int ch;

    int sync_word, tmp;

    uint8_t checksum;

    uint8_t lossless_check;

    int start_count = bitstream_tell(bc);

    int min_channel, max_channel, max_matrix_channel;

    const int std_max_matrix_channel = m->avctx->codec_id == AV_CODEC_ID_MLP

                                     ? MAX_MATRIX_CHANNEL_MLP

                                     : MAX_MATRIX_CHANNEL_TRUEHD;



    sync_word = bitstream_read(bc, 13);



    if (sync_word != 0x31ea >> 1) {

        av_log(m->avctx, AV_LOG_ERROR,

               "restart header sync incorrect (got 0x%04x)\n", sync_word);

        return AVERROR_INVALIDDATA;

    }



    s->noise_type = bitstream_read_bit(bc);



    if (m->avctx->codec_id == AV_CODEC_ID_MLP && s->noise_type) {

        av_log(m->avctx, AV_LOG_ERROR, "MLP must have 0x31ea sync word.\n");

        return AVERROR_INVALIDDATA;

    }



    bitstream_skip(bc, 16); /* Output timestamp */



    min_channel        = bitstream_read(bc, 4);

    max_channel        = bitstream_read(bc, 4);

    max_matrix_channel = bitstream_read(bc, 4);



    if (max_matrix_channel > std_max_matrix_channel) {

        av_log(m->avctx, AV_LOG_ERROR,

               "Max matrix channel cannot be greater than %d.\n",

               max_matrix_channel);

        return AVERROR_INVALIDDATA;

    }



    if (max_channel != max_matrix_channel) {

        av_log(m->avctx, AV_LOG_ERROR,

               "Max channel must be equal max matrix channel.\n");

        return AVERROR_INVALIDDATA;

    }



    /* This should happen for TrueHD streams with >6 channels and MLP's noise

     * type. It is not yet known if this is allowed. */

    if (s->max_channel > MAX_MATRIX_CHANNEL_MLP && !s->noise_type) {

        avpriv_request_sample(m->avctx,

                              "%d channels (more than the "

                              "maximum supported by the decoder)",

                              s->max_channel + 2);

        return AVERROR_PATCHWELCOME;

    }



    if (min_channel > max_channel) {

        av_log(m->avctx, AV_LOG_ERROR,

               "Substream min channel cannot be greater than max channel.\n");

        return AVERROR_INVALIDDATA;

    }



    s->min_channel        = min_channel;

    s->max_channel        = max_channel;

    s->max_matrix_channel = max_matrix_channel;



    if (m->avctx->request_channel_layout && (s->mask & m->avctx->request_channel_layout) ==

        m->avctx->request_channel_layout && m->max_decoded_substream > substr) {

        av_log(m->avctx, AV_LOG_DEBUG,

               "Extracting %d-channel downmix (0x%"PRIx64") from substream %d. "

               "Further substreams will be skipped.\n",

               s->max_channel + 1, s->mask, substr);

        m->max_decoded_substream = substr;

    }



    s->noise_shift   = bitstream_read(bc,  4);

    s->noisegen_seed = bitstream_read(bc, 23);



    bitstream_skip(bc, 19);



    s->data_check_present = bitstream_read_bit(bc);

    lossless_check = bitstream_read(bc, 8);

    if (substr == m->max_decoded_substream

        && s->lossless_check_data != 0xffffffff) {

        tmp = xor_32_to_8(s->lossless_check_data);

        if (tmp != lossless_check)

            av_log(m->avctx, AV_LOG_WARNING,

                   "Lossless check failed - expected %02x, calculated %02x.\n",

                   lossless_check, tmp);

    }



    bitstream_skip(bc, 16);



    memset(s->ch_assign, 0, sizeof(s->ch_assign));



    for (ch = 0; ch <= s->max_matrix_channel; ch++) {

        int ch_assign = bitstream_read(bc, 6);

        if (m->avctx->codec_id == AV_CODEC_ID_TRUEHD) {

            uint64_t channel = thd_channel_layout_extract_channel(s->mask,

                                                                  ch_assign);

            ch_assign = av_get_channel_layout_channel_index(s->mask,

                                                            channel);

        }

        if (ch_assign < 0 || ch_assign > s->max_matrix_channel) {

            avpriv_request_sample(m->avctx,

                                  "Assignment of matrix channel %d to invalid output channel %d",

                                  ch, ch_assign);

            return AVERROR_PATCHWELCOME;

        }

        s->ch_assign[ch_assign] = ch;

    }



    checksum = ff_mlp_restart_checksum(buf, bitstream_tell(bc) - start_count);



    if (checksum != bitstream_read(bc, 8))

        av_log(m->avctx, AV_LOG_ERROR, "restart header checksum error\n");



    /* Set default decoding parameters. */

    s->param_presence_flags   = 0xff;

    s->num_primitive_matrices = 0;

    s->blocksize              = 8;

    s->lossless_check_data    = 0;



    memset(s->output_shift   , 0, sizeof(s->output_shift   ));

    memset(s->quant_step_size, 0, sizeof(s->quant_step_size));



    for (ch = s->min_channel; ch <= s->max_channel; ch++) {

        ChannelParams *cp = &s->channel_params[ch];

        cp->filter_params[FIR].order = 0;

        cp->filter_params[IIR].order = 0;

        cp->filter_params[FIR].shift = 0;

        cp->filter_params[IIR].shift = 0;



        /* Default audio coding is 24-bit raw PCM. */

        cp->huff_offset      = 0;

        cp->sign_huff_offset = -(1 << 23);

        cp->codebook         = 0;

        cp->huff_lsbs        = 24;

    }



    if (substr == m->max_decoded_substream) {

        m->avctx->channels       = s->max_matrix_channel + 1;

        m->avctx->channel_layout = s->mask;

        m->dsp.mlp_pack_output = m->dsp.mlp_select_pack_output(s->ch_assign,

                                                               s->output_shift,

                                                               s->max_matrix_channel,

                                                               m->avctx->sample_fmt == AV_SAMPLE_FMT_S32);

    }



    return 0;

}

static void do_streamcopy(InputStream *ist, OutputStream *ost, const AVPacket *pkt)

{

    OutputFile *of = output_files[ost->file_index];

    int64_t ost_tb_start_time = av_rescale_q(of->start_time, AV_TIME_BASE_Q, ost->st->time_base);

    AVPacket opkt;



    av_init_packet(&opkt);



    if ((!ost->frame_number && !(pkt->flags & AV_PKT_FLAG_KEY)) &&

        !ost->copy_initial_nonkeyframes)

        return;



    if (of->recording_time != INT64_MAX &&

        ist->last_dts >= of->recording_time + of->start_time) {

        ost->finished = 1;

        return;

    }



    /* force the input stream PTS */

    if (ost->st->codec->codec_type == AVMEDIA_TYPE_AUDIO)

        audio_size += pkt->size;

    else if (ost->st->codec->codec_type == AVMEDIA_TYPE_VIDEO) {

        video_size += pkt->size;

        ost->sync_opts++;

    }



    if (pkt->pts != AV_NOPTS_VALUE)

        opkt.pts = av_rescale_q(pkt->pts, ist->st->time_base, ost->st->time_base) - ost_tb_start_time;

    else

        opkt.pts = AV_NOPTS_VALUE;



    if (pkt->dts == AV_NOPTS_VALUE)

        opkt.dts = av_rescale_q(ist->last_dts, AV_TIME_BASE_Q, ost->st->time_base);

    else

        opkt.dts = av_rescale_q(pkt->dts, ist->st->time_base, ost->st->time_base);

    opkt.dts -= ost_tb_start_time;



    opkt.duration = av_rescale_q(pkt->duration, ist->st->time_base, ost->st->time_base);

    opkt.flags    = pkt->flags;



    // FIXME remove the following 2 lines they shall be replaced by the bitstream filters

    if (  ost->st->codec->codec_id != AV_CODEC_ID_H264

       && ost->st->codec->codec_id != AV_CODEC_ID_MPEG1VIDEO

       && ost->st->codec->codec_id != AV_CODEC_ID_MPEG2VIDEO

       && ost->st->codec->codec_id != AV_CODEC_ID_VC1

       ) {

        if (av_parser_change(ist->st->parser, ost->st->codec, &opkt.data, &opkt.size, pkt->data, pkt->size, pkt->flags & AV_PKT_FLAG_KEY)) {

            opkt.buf = av_buffer_create(opkt.data, opkt.size, av_buffer_default_free, NULL, 0);

            if (!opkt.buf)

                exit(1);

        }

    } else {

        opkt.data = pkt->data;

        opkt.size = pkt->size;

    }



    write_frame(of->ctx, &opkt, ost);

    ost->st->codec->frame_number++;

}

static int init_pass2(MpegEncContext *s)

{

    RateControlContext *rcc = &s->rc_context;

    AVCodecContext *a       = s->avctx;

    int i, toobig;

    double fps             = get_fps(s->avctx);

    double complexity[5]   = { 0 }; // approximate bits at quant=1

    uint64_t const_bits[5] = { 0 }; // quantizer independent bits

    uint64_t all_const_bits;

    uint64_t all_available_bits = (uint64_t)(s->bit_rate *

                                             (double)rcc->num_entries / fps);

    double rate_factor          = 0;

    double step;

    const int filter_size = (int)(a->qblur * 4) | 1;

    double expected_bits;

    double *qscale, *blurred_qscale, qscale_sum;



    /* find complexity & const_bits & decide the pict_types */

    for (i = 0; i < rcc->num_entries; i++) {

        RateControlEntry *rce = &rcc->entry[i];



        rce->new_pict_type                = rce->pict_type;

        rcc->i_cplx_sum[rce->pict_type]  += rce->i_tex_bits * rce->qscale;

        rcc->p_cplx_sum[rce->pict_type]  += rce->p_tex_bits * rce->qscale;

        rcc->mv_bits_sum[rce->pict_type] += rce->mv_bits;

        rcc->frame_count[rce->pict_type]++;



        complexity[rce->new_pict_type] += (rce->i_tex_bits + rce->p_tex_bits) *

                                          (double)rce->qscale;

        const_bits[rce->new_pict_type] += rce->mv_bits + rce->misc_bits;

    }



    all_const_bits = const_bits[AV_PICTURE_TYPE_I] +

                     const_bits[AV_PICTURE_TYPE_P] +

                     const_bits[AV_PICTURE_TYPE_B];



    if (all_available_bits < all_const_bits) {

        av_log(s->avctx, AV_LOG_ERROR, "requested bitrate is too low\n");

        return -1;

    }



    qscale         = av_malloc(sizeof(double) * rcc->num_entries);

    blurred_qscale = av_malloc(sizeof(double) * rcc->num_entries);

    toobig = 0;



    for (step = 256 * 256; step > 0.0000001; step *= 0.5) {

        expected_bits = 0;

        rate_factor  += step;



        rcc->buffer_index = s->avctx->rc_buffer_size / 2;



        /* find qscale */

        for (i = 0; i < rcc->num_entries; i++) {

            RateControlEntry *rce = &rcc->entry[i];



            qscale[i] = get_qscale(s, &rcc->entry[i], rate_factor, i);

            rcc->last_qscale_for[rce->pict_type] = qscale[i];

        }

        assert(filter_size % 2 == 1);



        /* fixed I/B QP relative to P mode */

        for (i = FFMAX(0, rcc->num_entries - 300); i < rcc->num_entries; i++) {

            RateControlEntry *rce = &rcc->entry[i];



            qscale[i] = get_diff_limited_q(s, rce, qscale[i]);

        }



        for (i = rcc->num_entries - 1; i >= 0; i--) {

            RateControlEntry *rce = &rcc->entry[i];



            qscale[i] = get_diff_limited_q(s, rce, qscale[i]);

        }



        /* smooth curve */

        for (i = 0; i < rcc->num_entries; i++) {

            RateControlEntry *rce = &rcc->entry[i];

            const int pict_type   = rce->new_pict_type;

            int j;

            double q = 0.0, sum = 0.0;



            for (j = 0; j < filter_size; j++) {

                int index    = i + j - filter_size / 2;

                double d     = index - i;

                double coeff = a->qblur == 0 ? 1.0 : exp(-d * d / (a->qblur * a->qblur));



                if (index < 0 || index >= rcc->num_entries)

                    continue;

                if (pict_type != rcc->entry[index].new_pict_type)

                    continue;

                q   += qscale[index] * coeff;

                sum += coeff;

            }

            blurred_qscale[i] = q / sum;

        }



        /* find expected bits */

        for (i = 0; i < rcc->num_entries; i++) {

            RateControlEntry *rce = &rcc->entry[i];

            double bits;



            rce->new_qscale = modify_qscale(s, rce, blurred_qscale[i], i);



            bits  = qp2bits(rce, rce->new_qscale) + rce->mv_bits + rce->misc_bits;

            bits += 8 * ff_vbv_update(s, bits);



            rce->expected_bits = expected_bits;

            expected_bits     += bits;

        }



        av_dlog(s->avctx,

                "expected_bits: %f all_available_bits: %d rate_factor: %f\n",

                expected_bits, (int)all_available_bits, rate_factor);

        if (expected_bits > all_available_bits) {

            rate_factor -= step;

            ++toobig;

        }

    }

    av_free(qscale);

    av_free(blurred_qscale);



    /* check bitrate calculations and print info */

    qscale_sum = 0.0;

    for (i = 0; i < rcc->num_entries; i++) {

        av_dlog(s, "[lavc rc] entry[%d].new_qscale = %.3f  qp = %.3f\n",

                i,

                rcc->entry[i].new_qscale,

                rcc->entry[i].new_qscale / FF_QP2LAMBDA);

        qscale_sum += av_clip(rcc->entry[i].new_qscale / FF_QP2LAMBDA,

                              s->avctx->qmin, s->avctx->qmax);

    }

    assert(toobig <= 40);

    av_log(s->avctx, AV_LOG_DEBUG,

           "[lavc rc] requested bitrate: %d bps  expected bitrate: %d bps\n",

           s->bit_rate,

           (int)(expected_bits / ((double)all_available_bits / s->bit_rate)));

    av_log(s->avctx, AV_LOG_DEBUG,

           "[lavc rc] estimated target average qp: %.3f\n",

           (float)qscale_sum / rcc->num_entries);

    if (toobig == 0) {

        av_log(s->avctx, AV_LOG_INFO,

               "[lavc rc] Using all of requested bitrate is not "

               "necessary for this video with these parameters.\n");

    } else if (toobig == 40) {

        av_log(s->avctx, AV_LOG_ERROR,

               "[lavc rc] Error: bitrate too low for this video "

               "with these parameters.\n");

        return -1;

    } else if (fabs(expected_bits / all_available_bits - 1.0) > 0.01) {

        av_log(s->avctx, AV_LOG_ERROR,

               "[lavc rc] Error: 2pass curve failed to converge\n");

        return -1;

    }



    return 0;

}

static void paint_mouse_pointer(XImage *image, AVFormatContext *s1)

{

    X11GrabContext *s = s1->priv_data;

    int x_off    = s->x_off;

    int y_off    = s->y_off;

    int width    = s->width;

    int height   = s->height;

    Display *dpy = s->dpy;

    XFixesCursorImage *xcim;

    int x, y;

    int line, column;

    int to_line, to_column;

    int pixstride = image->bits_per_pixel >> 3;

    /* Warning: in its insanity, xlib provides unsigned image data through a

     * char* pointer, so we have to make it uint8_t to make things not break.

     * Anyone who performs further investigation of the xlib API likely risks

     * permanent brain damage. */

    uint8_t *pix = image->data;

    Window root;

    XSetWindowAttributes attr;



    /* Code doesn't currently support 16-bit or PAL8 */

    if (image->bits_per_pixel != 24 && image->bits_per_pixel != 32)

        return;



    if (!s->c)

        s->c = XCreateFontCursor(dpy, XC_left_ptr);

    root = DefaultRootWindow(dpy);

    attr.cursor = s->c;

    XChangeWindowAttributes(dpy, root, CWCursor, &attr);



    xcim = XFixesGetCursorImage(dpy);

    if (!xcim) {

        av_log(s1, AV_LOG_WARNING,

               "XFixes extension not available, impossible to draw cursor\n");

        s->draw_mouse = 0;

        return;

    }



    x = xcim->x - xcim->xhot;

    y = xcim->y - xcim->yhot;



    to_line   = FFMIN((y + xcim->height), (height + y_off));

    to_column = FFMIN((x + xcim->width),  (width  + x_off));



    for (line = FFMAX(y, y_off); line < to_line; line++) {

        for (column = FFMAX(x, x_off); column < to_column; column++) {

            int xcim_addr  = (line  - y)     * xcim->width + column - x;

            int image_addr = ((line - y_off) * width       + column - x_off) * pixstride;

            int r          = (uint8_t)(xcim->pixels[xcim_addr] >>  0);

            int g          = (uint8_t)(xcim->pixels[xcim_addr] >>  8);

            int b          = (uint8_t)(xcim->pixels[xcim_addr] >> 16);

            int a          = (uint8_t)(xcim->pixels[xcim_addr] >> 24);



            if (a == 255) {

                pix[image_addr + 0] = r;

                pix[image_addr + 1] = g;

                pix[image_addr + 2] = b;

            } else if (a) {

                /* pixel values from XFixesGetCursorImage come premultiplied by alpha */

                pix[image_addr + 0] = r + (pix[image_addr + 0] * (255 - a) + 255 / 2) / 255;

                pix[image_addr + 1] = g + (pix[image_addr + 1] * (255 - a) + 255 / 2) / 255;

                pix[image_addr + 2] = b + (pix[image_addr + 2] * (255 - a) + 255 / 2) / 255;

            }

        }

    }



    XFree(xcim);

    xcim = NULL;

}

static FFPsyWindowInfo psy_3gpp_window(FFPsyContext *ctx,

                                       const int16_t *audio, const int16_t *la,

                                       int channel, int prev_type)

{

    int i, j;

    int br               = ctx->avctx->bit_rate / ctx->avctx->channels;

    int attack_ratio     = br <= 16000 ? 18 : 10;

    Psy3gppContext *pctx = (Psy3gppContext*) ctx->model_priv_data;

    Psy3gppChannel *pch  = &pctx->ch[channel];

    uint8_t grouping     = 0;

    FFPsyWindowInfo wi;



    memset(&wi, 0, sizeof(wi));

    if (la) {

        float s[8], v;

        int switch_to_eight = 0;

        float sum = 0.0, sum2 = 0.0;

        int attack_n = 0;

        for (i = 0; i < 8; i++) {

            for (j = 0; j < 128; j++) {

                v = iir_filter(la[(i*128+j)*ctx->avctx->channels], pch->iir_state);

                sum += v*v;

            }

            s[i]  = sum;

            sum2 += sum;

        }

        for (i = 0; i < 8; i++) {

            if (s[i] > pch->win_energy * attack_ratio) {

                attack_n        = i + 1;

                switch_to_eight = 1;

                break;

            }

        }

        pch->win_energy = pch->win_energy*7/8 + sum2/64;



        wi.window_type[1] = prev_type;

        switch (prev_type) {

        case ONLY_LONG_SEQUENCE:

            wi.window_type[0] = switch_to_eight ? LONG_START_SEQUENCE : ONLY_LONG_SEQUENCE;

            break;

        case LONG_START_SEQUENCE:

            wi.window_type[0] = EIGHT_SHORT_SEQUENCE;

            grouping = pch->next_grouping;

            break;

        case LONG_STOP_SEQUENCE:

            wi.window_type[0] = ONLY_LONG_SEQUENCE;

            break;

        case EIGHT_SHORT_SEQUENCE:

            wi.window_type[0] = switch_to_eight ? EIGHT_SHORT_SEQUENCE : LONG_STOP_SEQUENCE;

            grouping = switch_to_eight ? pch->next_grouping : 0;

            break;

        }

        pch->next_grouping = window_grouping[attack_n];

    } else {

        for (i = 0; i < 3; i++)

            wi.window_type[i] = prev_type;

        grouping = (prev_type == EIGHT_SHORT_SEQUENCE) ? window_grouping[0] : 0;

    }



    wi.window_shape   = 1;

    if (wi.window_type[0] != EIGHT_SHORT_SEQUENCE) {

        wi.num_windows = 1;

        wi.grouping[0] = 1;

    } else {

        int lastgrp = 0;

        wi.num_windows = 8;

        for (i = 0; i < 8; i++) {

            if (!((grouping >> i) & 1))

                lastgrp = i;

            wi.grouping[lastgrp]++;

        }

    }



    return wi;

}

static int amr_read_packet(AVFormatContext *s,

                          AVPacket *pkt)

{

    AVCodecContext *enc = s->streams[0]->codec;

    int read, size, toc, mode;



    if (url_feof(&s->pb))

    {

        return AVERROR_IO;

    }



//FIXME this is wrong, this should rather be in a AVParset

    toc=get_byte(&s->pb);

    mode = (toc >> 3) & 0x0F;



    if (enc->codec_id == CODEC_ID_AMR_NB)

    {

        static const uint8_t packed_size[16] = {12, 13, 15, 17, 19, 20, 26, 31, 5, 0, 0, 0, 0, 0, 0, 0};



        size=packed_size[mode]+1;

    }

    else if(enc->codec_id == CODEC_ID_AMR_WB)

    {

        static uint8_t packed_size[16] = {18, 24, 33, 37, 41, 47, 51, 59, 61, 6, 6, 0, 0, 0, 1, 1};



        size=packed_size[mode];

    }

    else

    {

        assert(0);

    }



    if ( (size==0) || av_new_packet(pkt, size))

    {

        return AVERROR_IO;

    }



    pkt->stream_index = 0;

    pkt->pos= url_ftell(&s->pb);

    pkt->data[0]=toc;

    pkt->duration= enc->codec_id == CODEC_ID_AMR_NB ? 160 : 320;

    read = get_buffer(&s->pb, pkt->data+1, size-1);



    if (read != size-1)

    {

        av_free_packet(pkt);

        return AVERROR_IO;

    }



    return 0;

}

static void park_frame_worker_threads(FrameThreadContext *fctx, int thread_count)

{

    int i;



    for (i = 0; i < thread_count; i++) {

        PerThreadContext *p = &fctx->threads[i];



        if (p->state != STATE_INPUT_READY) {

            pthread_mutex_lock(&p->progress_mutex);

            while (p->state != STATE_INPUT_READY)

                pthread_cond_wait(&p->output_cond, &p->progress_mutex);

            pthread_mutex_unlock(&p->progress_mutex);

        }


    }

}

static int nut_read_packet(AVFormatContext *s, AVPacket *pkt)

{

    NUTContext *nut = s->priv_data;

    ByteIOContext *bc = &s->pb;

    int i, frame_code=0, ret, skip;

    int64_t ts, back_ptr;



    for(;;){

        int64_t pos= url_ftell(bc);

        uint64_t tmp= nut->next_startcode;

        nut->next_startcode=0;



        if (url_feof(bc))

            return -1;



        if(tmp){

            pos-=8;

        }else{

            frame_code = get_byte(bc);

            if(frame_code == 'N'){

                tmp= frame_code;

                for(i=1; i<8; i++)

                    tmp = (tmp<<8) + get_byte(bc);

            }

        }

        switch(tmp){

        case MAIN_STARTCODE:

        case STREAM_STARTCODE:

        case INDEX_STARTCODE:

            skip= get_packetheader(nut, bc, 0);

            url_fseek(bc, skip, SEEK_CUR);

            break;

        case INFO_STARTCODE:

            if(decode_info_header(nut)<0)

                goto resync;

            break;

        case SYNCPOINT_STARTCODE:

            if(decode_syncpoint(nut, &ts, &back_ptr)<0)

                goto resync;

            frame_code = get_byte(bc);

        case 0:

            ret= decode_frame(nut, pkt, frame_code);

            if(ret==0)

                return 0;

            else if(ret==1) //ok but discard packet

                break;

        default:

resync:

av_log(s, AV_LOG_DEBUG, "syncing from %"PRId64"\n", pos);

            tmp= find_any_startcode(bc, nut->last_syncpoint_pos+1);

            if(tmp==0)

                return -1;

av_log(s, AV_LOG_DEBUG, "sync\n");

            nut->next_startcode= tmp;

        }

    }

}

void rgb8tobgr8(const uint8_t *src, uint8_t *dst, long src_size)

{

	long i;

	long num_pixels = src_size;

	for(i=0; i<num_pixels; i++)

	{

	    unsigned b,g,r;

	    register uint8_t rgb;

	    rgb = src[i];

	    r = (rgb&0x07);

	    g = (rgb&0x38)>>3;

	    b = (rgb&0xC0)>>6;

	    dst[i] = ((b<<1)&0x07) | ((g&0x07)<<3) | ((r&0x03)<<6);

	}

}

static av_always_inline void hl_decode_mb_internal(H264Context *h, int simple){

    MpegEncContext * const s = &h->s;

    const int mb_x= s->mb_x;

    const int mb_y= s->mb_y;

    const int mb_xy= h->mb_xy;

    const int mb_type= s->current_picture.mb_type[mb_xy];

    uint8_t  *dest_y, *dest_cb, *dest_cr;

    int linesize, uvlinesize /*dct_offset*/;

    int i;

    int *block_offset = &h->block_offset[0];

    const int transform_bypass = !simple && (s->qscale == 0 && h->sps.transform_bypass);

    const int is_h264 = simple || s->codec_id == CODEC_ID_H264;

    void (*idct_add)(uint8_t *dst, DCTELEM *block, int stride);

    void (*idct_dc_add)(uint8_t *dst, DCTELEM *block, int stride);



    dest_y  = s->current_picture.data[0] + (mb_x + mb_y * s->linesize  ) * 16;

    dest_cb = s->current_picture.data[1] + (mb_x + mb_y * s->uvlinesize) * 8;

    dest_cr = s->current_picture.data[2] + (mb_x + mb_y * s->uvlinesize) * 8;



    s->dsp.prefetch(dest_y + (s->mb_x&3)*4*s->linesize + 64, s->linesize, 4);

    s->dsp.prefetch(dest_cb + (s->mb_x&7)*s->uvlinesize + 64, dest_cr - dest_cb, 2);



    if (!simple && MB_FIELD) {

        linesize   = h->mb_linesize   = s->linesize * 2;

        uvlinesize = h->mb_uvlinesize = s->uvlinesize * 2;

        block_offset = &h->block_offset[24];

        if(mb_y&1){ //FIXME move out of this function?

            dest_y -= s->linesize*15;

            dest_cb-= s->uvlinesize*7;

            dest_cr-= s->uvlinesize*7;

        }

        if(FRAME_MBAFF) {

            int list;

            for(list=0; list<h->list_count; list++){

                if(!USES_LIST(mb_type, list))

                    continue;

                if(IS_16X16(mb_type)){

                    int8_t *ref = &h->ref_cache[list][scan8[0]];

                    fill_rectangle(ref, 4, 4, 8, (16+*ref)^(s->mb_y&1), 1);

                }else{

                    for(i=0; i<16; i+=4){

                        int ref = h->ref_cache[list][scan8[i]];

                        if(ref >= 0)

                            fill_rectangle(&h->ref_cache[list][scan8[i]], 2, 2, 8, (16+ref)^(s->mb_y&1), 1);

                    }

                }

            }

        }

    } else {

        linesize   = h->mb_linesize   = s->linesize;

        uvlinesize = h->mb_uvlinesize = s->uvlinesize;

//        dct_offset = s->linesize * 16;

    }



    if (!simple && IS_INTRA_PCM(mb_type)) {

        for (i=0; i<16; i++) {

            memcpy(dest_y + i*  linesize, h->mb       + i*8, 16);

        }

        for (i=0; i<8; i++) {

            memcpy(dest_cb+ i*uvlinesize, h->mb + 128 + i*4,  8);

            memcpy(dest_cr+ i*uvlinesize, h->mb + 160 + i*4,  8);

        }

    } else {

        if(IS_INTRA(mb_type)){

            if(h->deblocking_filter)

                xchg_mb_border(h, dest_y, dest_cb, dest_cr, linesize, uvlinesize, 1, simple);



            if(simple || !ENABLE_GRAY || !(s->flags&CODEC_FLAG_GRAY)){

                h->hpc.pred8x8[ h->chroma_pred_mode ](dest_cb, uvlinesize);

                h->hpc.pred8x8[ h->chroma_pred_mode ](dest_cr, uvlinesize);

            }



            if(IS_INTRA4x4(mb_type)){

                if(simple || !s->encoding){

                    if(IS_8x8DCT(mb_type)){

                        if(transform_bypass){

                            idct_dc_add =

                            idct_add    = s->dsp.add_pixels8;

                        }else if(IS_8x8DCT(mb_type)){

                            idct_dc_add = s->dsp.h264_idct8_dc_add;

                            idct_add    = s->dsp.h264_idct8_add;

                        }

                        for(i=0; i<16; i+=4){

                            uint8_t * const ptr= dest_y + block_offset[i];

                            const int dir= h->intra4x4_pred_mode_cache[ scan8[i] ];

                            if(transform_bypass && h->sps.profile_idc==244 && dir<=1){

                                h->hpc.pred8x8l_add[dir](ptr, h->mb + i*16, linesize);

                            }else{

                                const int nnz = h->non_zero_count_cache[ scan8[i] ];

                                h->hpc.pred8x8l[ dir ](ptr, (h->topleft_samples_available<<i)&0x8000,

                                                            (h->topright_samples_available<<i)&0x4000, linesize);

                                if(nnz){

                                    if(nnz == 1 && h->mb[i*16])

                                        idct_dc_add(ptr, h->mb + i*16, linesize);

                                    else

                                        idct_add   (ptr, h->mb + i*16, linesize);

                                }

                            }

                        }

                    }else{

                        if(transform_bypass){

                            idct_dc_add =

                            idct_add    = s->dsp.add_pixels4;

                        }else{

                            idct_dc_add = s->dsp.h264_idct_dc_add;

                            idct_add    = s->dsp.h264_idct_add;

                        }

                    for(i=0; i<16; i++){

                        uint8_t * const ptr= dest_y + block_offset[i];

                        const int dir= h->intra4x4_pred_mode_cache[ scan8[i] ];



                        if(transform_bypass && h->sps.profile_idc==244 && dir<=1){

                            h->hpc.pred4x4_add[dir](ptr, h->mb + i*16, linesize);

                        }else{

                            uint8_t *topright;

                            int nnz, tr;

                            if(dir == DIAG_DOWN_LEFT_PRED || dir == VERT_LEFT_PRED){

                                const int topright_avail= (h->topright_samples_available<<i)&0x8000;

                                assert(mb_y || linesize <= block_offset[i]);

                                if(!topright_avail){

                                    tr= ptr[3 - linesize]*0x01010101;

                                    topright= (uint8_t*) &tr;

                                }else

                                    topright= ptr + 4 - linesize;

                            }else

                                topright= NULL;



                            h->hpc.pred4x4[ dir ](ptr, topright, linesize);

                            nnz = h->non_zero_count_cache[ scan8[i] ];

                            if(nnz){

                                if(is_h264){

                                    if(nnz == 1 && h->mb[i*16])

                                        idct_dc_add(ptr, h->mb + i*16, linesize);

                                    else

                                        idct_add   (ptr, h->mb + i*16, linesize);

                                }else

                                    svq3_add_idct_c(ptr, h->mb + i*16, linesize, s->qscale, 0);

                            }

                        }

                    }

                    }

                }

            }else{

                h->hpc.pred16x16[ h->intra16x16_pred_mode ](dest_y , linesize);

                if(is_h264){

                    if(!transform_bypass)

                        h264_luma_dc_dequant_idct_c(h->mb, s->qscale, h->dequant4_coeff[0][s->qscale][0]);

                }else

                    svq3_luma_dc_dequant_idct_c(h->mb, s->qscale);

            }

            if(h->deblocking_filter)

                xchg_mb_border(h, dest_y, dest_cb, dest_cr, linesize, uvlinesize, 0, simple);

        }else if(is_h264){

            hl_motion(h, dest_y, dest_cb, dest_cr,

                      s->me.qpel_put, s->dsp.put_h264_chroma_pixels_tab,

                      s->me.qpel_avg, s->dsp.avg_h264_chroma_pixels_tab,

                      s->dsp.weight_h264_pixels_tab, s->dsp.biweight_h264_pixels_tab);

        }





        if(!IS_INTRA4x4(mb_type)){

            if(is_h264){

                if(IS_INTRA16x16(mb_type)){

                    if(transform_bypass){

                        if(h->sps.profile_idc==244 && (h->intra16x16_pred_mode==VERT_PRED8x8 || h->intra16x16_pred_mode==HOR_PRED8x8)){

                            h->hpc.pred16x16_add[h->intra16x16_pred_mode](dest_y, block_offset, h->mb, linesize);

                        }else{

                            for(i=0; i<16; i++){

                                if(h->non_zero_count_cache[ scan8[i] ] || h->mb[i*16])

                                    s->dsp.add_pixels4(dest_y + block_offset[i], h->mb + i*16, linesize);

                            }

                        }

                    }else{

                         s->dsp.h264_idct_add16intra(dest_y, block_offset, h->mb, linesize, h->non_zero_count_cache);

                    }

                }else if(h->cbp&15){

                    if(transform_bypass){

                        const int di = IS_8x8DCT(mb_type) ? 4 : 1;

                        idct_add= IS_8x8DCT(mb_type) ? s->dsp.add_pixels8 : s->dsp.add_pixels4;

                        for(i=0; i<16; i+=di){

                            if(h->non_zero_count_cache[ scan8[i] ]){

                                idct_add(dest_y + block_offset[i], h->mb + i*16, linesize);

                            }

                        }

                    }else{

                        if(IS_8x8DCT(mb_type)){

                            s->dsp.h264_idct8_add4(dest_y, block_offset, h->mb, linesize, h->non_zero_count_cache);

                        }else{

                            s->dsp.h264_idct_add16(dest_y, block_offset, h->mb, linesize, h->non_zero_count_cache);

                        }

                    }

                }

            }else{

                for(i=0; i<16; i++){

                    if(h->non_zero_count_cache[ scan8[i] ] || h->mb[i*16]){ //FIXME benchmark weird rule, & below

                        uint8_t * const ptr= dest_y + block_offset[i];

                        svq3_add_idct_c(ptr, h->mb + i*16, linesize, s->qscale, IS_INTRA(mb_type) ? 1 : 0);

                    }

                }

            }

        }



        if((simple || !ENABLE_GRAY || !(s->flags&CODEC_FLAG_GRAY)) && (h->cbp&0x30)){

            uint8_t *dest[2] = {dest_cb, dest_cr};

            if(transform_bypass){

                idct_add = idct_dc_add = s->dsp.add_pixels4;

            }else{

                idct_add = s->dsp.h264_idct_add;

                idct_dc_add = s->dsp.h264_idct_dc_add;

                chroma_dc_dequant_idct_c(h->mb + 16*16, h->chroma_qp[0], h->dequant4_coeff[IS_INTRA(mb_type) ? 1:4][h->chroma_qp[0]][0]);

                chroma_dc_dequant_idct_c(h->mb + 16*16+4*16, h->chroma_qp[1], h->dequant4_coeff[IS_INTRA(mb_type) ? 2:5][h->chroma_qp[1]][0]);

            }

            if(is_h264){

                if(transform_bypass && IS_INTRA(mb_type) && h->sps.profile_idc==244 && (h->chroma_pred_mode==VERT_PRED8x8 || h->chroma_pred_mode==HOR_PRED8x8)){

                    h->hpc.pred8x8_add[h->chroma_pred_mode](dest[0], block_offset + 16, h->mb + 16*16, uvlinesize);

                    h->hpc.pred8x8_add[h->chroma_pred_mode](dest[1], block_offset + 20, h->mb + 20*16, uvlinesize);

                }else{

                    for(i=16; i<16+8; i++){

                        if(h->non_zero_count_cache[ scan8[i] ])

                            idct_add   (dest[(i&4)>>2] + block_offset[i], h->mb + i*16, uvlinesize);

                        else if(h->mb[i*16])

                            idct_dc_add(dest[(i&4)>>2] + block_offset[i], h->mb + i*16, uvlinesize);

                    }

                }

            }else{

                for(i=16; i<16+8; i++){

                    if(h->non_zero_count_cache[ scan8[i] ] || h->mb[i*16]){

                        uint8_t * const ptr= dest[(i&4)>>2] + block_offset[i];

                        svq3_add_idct_c(ptr, h->mb + i*16, uvlinesize, chroma_qp[s->qscale + 12] - 12, 2);

                    }

                }

            }

        }

    }

    if(h->deblocking_filter) {

        backup_mb_border(h, dest_y, dest_cb, dest_cr, linesize, uvlinesize, simple);

        fill_caches(h, mb_type, 1); //FIXME don't fill stuff which isn't used by filter_mb

        h->chroma_qp[0] = get_chroma_qp(h, 0, s->current_picture.qscale_table[mb_xy]);

        h->chroma_qp[1] = get_chroma_qp(h, 1, s->current_picture.qscale_table[mb_xy]);

        if (!simple && FRAME_MBAFF) {

            filter_mb     (h, mb_x, mb_y, dest_y, dest_cb, dest_cr, linesize, uvlinesize);

        } else {

            filter_mb_fast(h, mb_x, mb_y, dest_y, dest_cb, dest_cr, linesize, uvlinesize);

        }

    }

}

static void sbr_hf_g_filt_c(int (*Y)[2], const int (*X_high)[40][2],

                          const SoftFloat *g_filt, int m_max, intptr_t ixh)

{

    int m;

    int64_t accu;



    for (m = 0; m < m_max; m++) {

        int64_t r = 1LL << (22-g_filt[m].exp);

        accu = (int64_t)X_high[m][ixh][0] * ((g_filt[m].mant + 0x40)>>7);

        Y[m][0] = (int)((accu + r) >> (23-g_filt[m].exp));



        accu = (int64_t)X_high[m][ixh][1] * ((g_filt[m].mant + 0x40)>>7);

        Y[m][1] = (int)((accu + r) >> (23-g_filt[m].exp));

    }

}

static int output_frame(AVFilterLink *outlink, int need_request)

{

    AVFilterContext *ctx = outlink->src;

    MixContext      *s = ctx->priv;

    AVFrame *out_buf, *in_buf;

    int nb_samples, ns, ret, i;



    ret = calc_active_inputs(s);

    if (ret < 0)

        return ret;



    if (s->input_state[0] & INPUT_ON) {

        /* first input live: use the corresponding frame size */

        nb_samples = frame_list_next_frame_size(s->frame_list);

        for (i = 1; i < s->nb_inputs; i++) {

            if (s->input_state[i] & INPUT_ON) {

                ns = av_audio_fifo_size(s->fifos[i]);

                if (ns < nb_samples) {

                    if (!(s->input_state[i] & INPUT_EOF))

                        /* unclosed input with not enough samples */

                        return need_request ? ff_request_frame(ctx->inputs[i]) : 0;

                    /* closed input to drain */

                    nb_samples = ns;

                }

            }

        }

    } else {

        /* first input closed: use the available samples */

        nb_samples = INT_MAX;

        for (i = 1; i < s->nb_inputs; i++) {

            if (s->input_state[i] & INPUT_ON) {

                ns = av_audio_fifo_size(s->fifos[i]);

                nb_samples = FFMIN(nb_samples, ns);

            }

        }

        if (nb_samples == INT_MAX)

            return AVERROR_EOF;

    }



    s->next_pts = frame_list_next_pts(s->frame_list);

    frame_list_remove_samples(s->frame_list, nb_samples);



    calculate_scales(s, nb_samples);



    if (nb_samples == 0)

        return 0;



    out_buf = ff_get_audio_buffer(outlink, nb_samples);

    if (!out_buf)

        return AVERROR(ENOMEM);



    in_buf = ff_get_audio_buffer(outlink, nb_samples);

    if (!in_buf) {

        av_frame_free(&out_buf);

        return AVERROR(ENOMEM);

    }



    for (i = 0; i < s->nb_inputs; i++) {

        if (s->input_state[i] & INPUT_ON) {

            int planes, plane_size, p;



            av_audio_fifo_read(s->fifos[i], (void **)in_buf->extended_data,

                               nb_samples);



            planes     = s->planar ? s->nb_channels : 1;

            plane_size = nb_samples * (s->planar ? 1 : s->nb_channels);

            plane_size = FFALIGN(plane_size, 16);



            if (out_buf->format == AV_SAMPLE_FMT_FLT ||

                out_buf->format == AV_SAMPLE_FMT_FLTP) {

                for (p = 0; p < planes; p++) {

                    s->fdsp->vector_fmac_scalar((float *)out_buf->extended_data[p],

                                                (float *) in_buf->extended_data[p],

                                                s->input_scale[i], plane_size);

                }

            } else {

                for (p = 0; p < planes; p++) {

                    s->fdsp->vector_dmac_scalar((double *)out_buf->extended_data[p],

                                                (double *) in_buf->extended_data[p],

                                                s->input_scale[i], plane_size);

                }

            }

        }

    }

    av_frame_free(&in_buf);



    out_buf->pts = s->next_pts;

    if (s->next_pts != AV_NOPTS_VALUE)

        s->next_pts += nb_samples;



    return ff_filter_frame(outlink, out_buf);

}

make_setup_request (AVFormatContext *s, const char *host, int port, int protocol)

{

    RTSPState *rt = s->priv_data;

    int j, i, err;

    RTSPStream *rtsp_st;

    AVStream *st;

    RTSPHeader reply1, *reply = &reply1;

    char cmd[2048];



    /* for each stream, make the setup request */

    /* XXX: we assume the same server is used for the control of each

       RTSP stream */



    for(j = RTSP_RTP_PORT_MIN, i = 0; i < rt->nb_rtsp_streams; ++i) {

        char transport[2048];



        rtsp_st = rt->rtsp_streams[i];



        /* compute available transports */

        transport[0] = '\0';



        /* RTP/UDP */

        if (protocol == RTSP_PROTOCOL_RTP_UDP) {

            char buf[256];



            /* first try in specified port range */

            if (RTSP_RTP_PORT_MIN != 0) {

                while(j <= RTSP_RTP_PORT_MAX) {

                    snprintf(buf, sizeof(buf), "rtp://%s?localport=%d", host, j);

                    j += 2; /* we will use two port by rtp stream (rtp and rtcp) */

                    if (url_open(&rtsp_st->rtp_handle, buf, URL_RDWR) == 0) {

                        goto rtp_opened;

                    }

                }

            }



/*            then try on any port

**            if (url_open(&rtsp_st->rtp_handle, "rtp://", URL_RDONLY) < 0) {

**                err = AVERROR_INVALIDDATA;

**                goto fail;

**            }

*/



        rtp_opened:

            port = rtp_get_local_port(rtsp_st->rtp_handle);

            if (transport[0] != '\0')

                av_strlcat(transport, ",", sizeof(transport));

            snprintf(transport + strlen(transport), sizeof(transport) - strlen(transport) - 1,

                     "RTP/AVP/UDP;unicast;client_port=%d-%d",

                     port, port + 1);

        }



        /* RTP/TCP */

        else if (protocol == RTSP_PROTOCOL_RTP_TCP) {

            if (transport[0] != '\0')

                av_strlcat(transport, ",", sizeof(transport));

            snprintf(transport + strlen(transport), sizeof(transport) - strlen(transport) - 1,

                     "RTP/AVP/TCP");

        }



        else if (protocol == RTSP_PROTOCOL_RTP_UDP_MULTICAST) {

            if (transport[0] != '\0')

                av_strlcat(transport, ",", sizeof(transport));

            snprintf(transport + strlen(transport),

                     sizeof(transport) - strlen(transport) - 1,

                     "RTP/AVP/UDP;multicast");

        }

        snprintf(cmd, sizeof(cmd),

                 "SETUP %s RTSP/1.0\r\n"

                 "Transport: %s\r\n",

                 rtsp_st->control_url, transport);

        rtsp_send_cmd(s, cmd, reply, NULL);

        if (reply->status_code == 461 /* Unsupported protocol */ && i == 0) {

            err = 1;

            goto fail;

        } else if (reply->status_code != RTSP_STATUS_OK ||

                   reply->nb_transports != 1) {

            err = AVERROR_INVALIDDATA;

            goto fail;

        }



        /* XXX: same protocol for all streams is required */

        if (i > 0) {

            if (reply->transports[0].protocol != rt->protocol) {

                err = AVERROR_INVALIDDATA;

                goto fail;

            }

        } else {

            rt->protocol = reply->transports[0].protocol;

        }



        /* close RTP connection if not choosen */

        if (reply->transports[0].protocol != RTSP_PROTOCOL_RTP_UDP &&

            (protocol == RTSP_PROTOCOL_RTP_UDP)) {

            url_close(rtsp_st->rtp_handle);

            rtsp_st->rtp_handle = NULL;

        }



        switch(reply->transports[0].protocol) {

        case RTSP_PROTOCOL_RTP_TCP:

            rtsp_st->interleaved_min = reply->transports[0].interleaved_min;

            rtsp_st->interleaved_max = reply->transports[0].interleaved_max;

            break;



        case RTSP_PROTOCOL_RTP_UDP:

            {

                char url[1024];



                /* XXX: also use address if specified */

                snprintf(url, sizeof(url), "rtp://%s:%d",

                         host, reply->transports[0].server_port_min);

                if (rtp_set_remote_url(rtsp_st->rtp_handle, url) < 0) {

                    err = AVERROR_INVALIDDATA;

                    goto fail;

                }

            }

            break;

        case RTSP_PROTOCOL_RTP_UDP_MULTICAST:

            {

                char url[1024];

                struct in_addr in;



                in.s_addr = htonl(reply->transports[0].destination);

                snprintf(url, sizeof(url), "rtp://%s:%d?ttl=%d",

                         inet_ntoa(in),

                         reply->transports[0].port_min,

                         reply->transports[0].ttl);

                if (url_open(&rtsp_st->rtp_handle, url, URL_RDWR) < 0) {

                    err = AVERROR_INVALIDDATA;

                    goto fail;

                }

            }

            break;

        }

        /* open the RTP context */

        st = NULL;

        if (rtsp_st->stream_index >= 0)

            st = s->streams[rtsp_st->stream_index];

        if (!st)

            s->ctx_flags |= AVFMTCTX_NOHEADER;

        rtsp_st->rtp_ctx = rtp_parse_open(s, st, rtsp_st->rtp_handle, rtsp_st->sdp_payload_type, &rtsp_st->rtp_payload_data);



        if (!rtsp_st->rtp_ctx) {

            err = AVERROR(ENOMEM);

            goto fail;

        } else {

            if(rtsp_st->dynamic_handler) {

                rtsp_st->rtp_ctx->dynamic_protocol_context= rtsp_st->dynamic_protocol_context;

                rtsp_st->rtp_ctx->parse_packet= rtsp_st->dynamic_handler->parse_packet;

            }

        }

    }



    return 0;



fail:

    for (i=0; i<rt->nb_rtsp_streams; i++) {

        if (rt->rtsp_streams[i]->rtp_handle) {

            url_close(rt->rtsp_streams[i]->rtp_handle);

            rt->rtsp_streams[i]->rtp_handle = NULL;

        }

    }

    return err;

}

static int add_metadata(int count, int type,

                        const char *name, const char *sep, TiffContext *s)

{

    switch(type) {

    case TIFF_DOUBLE: return add_doubles_metadata(count, name, sep, s);

    case TIFF_SHORT : return add_shorts_metadata(count, name, sep, s);

    case TIFF_STRING: return add_string_metadata(count, name, s);

    default         : return AVERROR_INVALIDDATA;

    };

}

real_parse_asm_rule(AVStream *st, const char *p, const char *end)

{

    do {

        /* can be either averagebandwidth= or AverageBandwidth= */

#if AV_HAVE_INCOMPATIBLE_LIBAV_ABI

        if (sscanf(p, " %*1[Aa]verage%*1[Bb]andwidth=%d", &st->codec->bit_rate) == 1)

#else

        if (sscanf(p, " %*1[Aa]verage%*1[Bb]andwidth=%"SCNd64, &st->codec->bit_rate) == 1)

#endif

            break;

        if (!(p = strchr(p, ',')) || p > end)

            p = end;

        p++;

    } while (p < end);

}

static int vp3_decode_frame(AVCodecContext *avctx,

                            void *data, int *data_size,

                            AVPacket *avpkt)

{

    const uint8_t *buf = avpkt->data;

    int buf_size = avpkt->size;

    Vp3DecodeContext *s = avctx->priv_data;

    GetBitContext gb;

    static int counter = 0;

    int i;



    init_get_bits(&gb, buf, buf_size * 8);



    if (s->theora && get_bits1(&gb))

    {

        av_log(avctx, AV_LOG_ERROR, "Header packet passed to frame decoder, skipping\n");

        return -1;

    }



    s->keyframe = !get_bits1(&gb);

    if (!s->theora)

        skip_bits(&gb, 1);

    for (i = 0; i < 3; i++)

        s->last_qps[i] = s->qps[i];



    s->nqps=0;

    do{

        s->qps[s->nqps++]= get_bits(&gb, 6);

    } while(s->theora >= 0x030200 && s->nqps<3 && get_bits1(&gb));

    for (i = s->nqps; i < 3; i++)

        s->qps[i] = -1;



    if (s->avctx->debug & FF_DEBUG_PICT_INFO)

        av_log(s->avctx, AV_LOG_INFO, " VP3 %sframe #%d: Q index = %d\n",

            s->keyframe?"key":"", counter, s->qps[0]);

    counter++;



    if (s->qps[0] != s->last_qps[0])

        init_loop_filter(s);



    for (i = 0; i < s->nqps; i++)

        // reinit all dequantizers if the first one changed, because

        // the DC of the first quantizer must be used for all matrices

        if (s->qps[i] != s->last_qps[i] || s->qps[0] != s->last_qps[0])

            init_dequantizer(s, i);



    if (avctx->skip_frame >= AVDISCARD_NONKEY && !s->keyframe)

        return buf_size;



    s->current_frame.reference = 3;

    if (avctx->get_buffer(avctx, &s->current_frame) < 0) {

        av_log(s->avctx, AV_LOG_ERROR, "get_buffer() failed\n");

        return -1;

    }



    if (s->keyframe) {

        if (!s->theora)

        {

            skip_bits(&gb, 4); /* width code */

            skip_bits(&gb, 4); /* height code */

            if (s->version)

            {

                s->version = get_bits(&gb, 5);

                if (counter == 1)

                    av_log(s->avctx, AV_LOG_DEBUG, "VP version: %d\n", s->version);

            }

        }

        if (s->version || s->theora)

        {

                if (get_bits1(&gb))

                    av_log(s->avctx, AV_LOG_ERROR, "Warning, unsupported keyframe coding type?!\n");

            skip_bits(&gb, 2); /* reserved? */

        }

    } else {

        if (!s->golden_frame.data[0]) {

            av_log(s->avctx, AV_LOG_ERROR, "vp3: first frame not a keyframe\n");

            avctx->release_buffer(avctx, &s->current_frame);

            return -1;

        }

    }



    s->current_frame.qscale_table= s->qscale_table; //FIXME allocate individual tables per AVFrame

    s->current_frame.qstride= 0;



    init_frame(s, &gb);



    if (unpack_superblocks(s, &gb)){

        av_log(s->avctx, AV_LOG_ERROR, "error in unpack_superblocks\n");

        return -1;

    }

    if (unpack_modes(s, &gb)){

        av_log(s->avctx, AV_LOG_ERROR, "error in unpack_modes\n");

        return -1;

    }

    if (unpack_vectors(s, &gb)){

        av_log(s->avctx, AV_LOG_ERROR, "error in unpack_vectors\n");

        return -1;

    }

    if (unpack_block_qpis(s, &gb)){

        av_log(s->avctx, AV_LOG_ERROR, "error in unpack_block_qpis\n");

        return -1;

    }

    if (unpack_dct_coeffs(s, &gb)){

        av_log(s->avctx, AV_LOG_ERROR, "error in unpack_dct_coeffs\n");

        return -1;

    }



    for (i = 0; i < 3; i++) {

        if (s->flipped_image)

            s->data_offset[i] = 0;

        else

            s->data_offset[i] = ((s->height>>!!i)-1) * s->current_frame.linesize[i];

    }



    s->last_slice_end = 0;

    for (i = 0; i < s->c_superblock_height; i++)

        render_slice(s, i);



    // filter the last row

    for (i = 0; i < 3; i++) {

        int row = (s->height >> (3+!!i)) - 1;

        apply_loop_filter(s, i, row, row+1);

    }

    vp3_draw_horiz_band(s, s->height);



    *data_size=sizeof(AVFrame);

    *(AVFrame*)data= s->current_frame;



    /* release the last frame, if it is allocated and if it is not the

     * golden frame */

    if ((s->last_frame.data[0]) &&

        (s->last_frame.data[0] != s->golden_frame.data[0]))

        avctx->release_buffer(avctx, &s->last_frame);



    /* shuffle frames (last = current) */

    s->last_frame= s->current_frame;



    if (s->keyframe) {

        if (s->golden_frame.data[0])

            avctx->release_buffer(avctx, &s->golden_frame);

        s->golden_frame = s->current_frame;

    }



    s->current_frame.data[0]= NULL; /* ensure that we catch any access to this released frame */



    return buf_size;

}

static int dxva2_vc1_end_frame(AVCodecContext *avctx)

{

    VC1Context *v = avctx->priv_data;

    struct dxva2_picture_context *ctx_pic = v->s.current_picture_ptr->hwaccel_picture_private;

    int ret;



    if (ctx_pic->bitstream_size <= 0)

        return -1;



    ret = ff_dxva2_common_end_frame(avctx, &v->s.current_picture_ptr->f,

                                    &ctx_pic->pp, sizeof(ctx_pic->pp),

                                    NULL, 0,

                                    commit_bitstream_and_slice_buffer);

    if (!ret)

        ff_mpeg_draw_horiz_band(&v->s, 0, avctx->height);

    return ret;

}

static int kmvc_decode_intra_8x8(KmvcContext * ctx, int w, int h)

{

    BitBuf bb;

    int res, val;

    int i, j;

    int bx, by;

    int l0x, l1x, l0y, l1y;

    int mx, my;



    kmvc_init_getbits(bb, &ctx->g);



    for (by = 0; by < h; by += 8)

        for (bx = 0; bx < w; bx += 8) {

            if (!bytestream2_get_bytes_left(&ctx->g)) {

                av_log(ctx->avctx, AV_LOG_ERROR, "Data overrun\n");

                return AVERROR_INVALIDDATA;

            }

            kmvc_getbit(bb, &ctx->g, res);

            if (!res) {         // fill whole 8x8 block

                val = bytestream2_get_byte(&ctx->g);

                for (i = 0; i < 64; i++)

                    BLK(ctx->cur, bx + (i & 0x7), by + (i >> 3)) = val;

            } else {            // handle four 4x4 subblocks

                for (i = 0; i < 4; i++) {

                    l0x = bx + (i & 1) * 4;

                    l0y = by + (i & 2) * 2;

                    kmvc_getbit(bb, &ctx->g, res);

                    if (!res) {

                        kmvc_getbit(bb, &ctx->g, res);

                        if (!res) {     // fill whole 4x4 block

                            val = bytestream2_get_byte(&ctx->g);

                            for (j = 0; j < 16; j++)

                                BLK(ctx->cur, l0x + (j & 3), l0y + (j >> 2)) = val;

                        } else {        // copy block from already decoded place

                            val = bytestream2_get_byte(&ctx->g);

                            mx = val & 0xF;

                            my = val >> 4;

                            if ((l0x-mx) + 320*(l0y-my) < 0 || (l0x-mx) + 320*(l0y-my) > 316*196) {

                                av_log(ctx->avctx, AV_LOG_ERROR, "Invalid MV\n");

                                return AVERROR_INVALIDDATA;

                            }

                            for (j = 0; j < 16; j++)

                                BLK(ctx->cur, l0x + (j & 3), l0y + (j >> 2)) =

                                    BLK(ctx->cur, l0x + (j & 3) - mx, l0y + (j >> 2) - my);

                        }

                    } else {    // descend to 2x2 sub-sub-blocks

                        for (j = 0; j < 4; j++) {

                            l1x = l0x + (j & 1) * 2;

                            l1y = l0y + (j & 2);

                            kmvc_getbit(bb, &ctx->g, res);

                            if (!res) {

                                kmvc_getbit(bb, &ctx->g, res);

                                if (!res) {     // fill whole 2x2 block

                                    val = bytestream2_get_byte(&ctx->g);

                                    BLK(ctx->cur, l1x, l1y) = val;

                                    BLK(ctx->cur, l1x + 1, l1y) = val;

                                    BLK(ctx->cur, l1x, l1y + 1) = val;

                                    BLK(ctx->cur, l1x + 1, l1y + 1) = val;

                                } else {        // copy block from already decoded place

                                    val = bytestream2_get_byte(&ctx->g);

                                    mx = val & 0xF;

                                    my = val >> 4;

                                    if ((l1x-mx) + 320*(l1y-my) < 0 || (l1x-mx) + 320*(l1y-my) > 318*198) {

                                        av_log(ctx->avctx, AV_LOG_ERROR, "Invalid MV\n");

                                        return AVERROR_INVALIDDATA;

                                    }

                                    BLK(ctx->cur, l1x, l1y) = BLK(ctx->cur, l1x - mx, l1y - my);

                                    BLK(ctx->cur, l1x + 1, l1y) =

                                        BLK(ctx->cur, l1x + 1 - mx, l1y - my);

                                    BLK(ctx->cur, l1x, l1y + 1) =

                                        BLK(ctx->cur, l1x - mx, l1y + 1 - my);

                                    BLK(ctx->cur, l1x + 1, l1y + 1) =

                                        BLK(ctx->cur, l1x + 1 - mx, l1y + 1 - my);

                                }

                            } else {    // read values for block

                                BLK(ctx->cur, l1x, l1y) = bytestream2_get_byte(&ctx->g);

                                BLK(ctx->cur, l1x + 1, l1y) = bytestream2_get_byte(&ctx->g);

                                BLK(ctx->cur, l1x, l1y + 1) = bytestream2_get_byte(&ctx->g);

                                BLK(ctx->cur, l1x + 1, l1y + 1) = bytestream2_get_byte(&ctx->g);

                            }

                        }

                    }

                }

            }

        }



    return 0;

}

static int asf_read_metadata_obj(AVFormatContext *s, const GUIDParseTable *g)

{

    ASFContext *asf   = s->priv_data;

    AVIOContext *pb   = s->pb;

    uint64_t size     = avio_rl64(pb);

    uint16_t nb_recs  = avio_rl16(pb); // number of records in the Description Records list

    int i, ret;



    for (i = 0; i < nb_recs; i++) {

        uint16_t name_len, buflen, type, val_len, st_num;

        uint8_t *name = NULL;



        avio_skip(pb, 2); // skip reserved field

        st_num   = avio_rl16(pb);

        name_len = avio_rl16(pb);

        buflen   = 2 * name_len + 1;

        if (!name_len)

            break;

        type     = avio_rl16(pb);

        val_len  = avio_rl32(pb);

        name     = av_malloc(name_len);

        if (!name)

            return AVERROR(ENOMEM);

        avio_get_str16le(pb, name_len, name,

                         buflen);



        if (!strcmp(name, "AspectRatioX") || !strcmp(name, "AspectRatioY")) {

            asf_store_aspect_ratio(s, st_num, name);

        } else {

            if (st_num < ASF_MAX_STREAMS) {

                if ((ret = process_metadata(s, name, name_len, val_len, type,

                                            &asf->asf_sd[st_num].asf_met)) < 0)

                    break;

            } else

                av_freep(&name);

        }

    }



    align_position(pb, asf->offset, size);

    return 0;

}

matroska_parse_blockgroup (MatroskaDemuxContext *matroska,

                           uint64_t              cluster_time)

{

    int res = 0;

    uint32_t id;

    AVPacket *pkt = NULL;

    int is_keyframe = PKT_FLAG_KEY, last_num_packets = matroska->num_packets;

    uint64_t duration = AV_NOPTS_VALUE;

    int track = -1;

    uint8_t *data;

    int size = 0;

    int64_t pos = 0;



    av_log(matroska->ctx, AV_LOG_DEBUG, "parsing blockgroup...\n");



    while (res == 0) {

        if (!(id = ebml_peek_id(matroska, &matroska->level_up))) {

            res = AVERROR_IO;

            break;

        } else if (matroska->level_up) {

            matroska->level_up--;

            break;

        }



        switch (id) {

            /* one block inside the group. Note, block parsing is one

             * of the harder things, so this code is a bit complicated.

             * See http://www.matroska.org/ for documentation. */

            case MATROSKA_ID_BLOCK: {

                pos = url_ftell(&matroska->ctx->pb);

                res = ebml_read_binary(matroska, &id, &data, &size);

                break;

            }



            case MATROSKA_ID_BLOCKDURATION: {

                if ((res = ebml_read_uint(matroska, &id, &duration)) < 0)

                    break;

                break;

            }



            case MATROSKA_ID_BLOCKREFERENCE:

                /* We've found a reference, so not even the first frame in

                 * the lace is a key frame. */

                is_keyframe = 0;

                if (last_num_packets != matroska->num_packets)

                    matroska->packets[last_num_packets]->flags = 0;

                res = ebml_read_skip(matroska);

                break;



            default:

                av_log(matroska->ctx, AV_LOG_INFO,

                       "Unknown entry 0x%x in blockgroup data\n", id);

                /* fall-through */



            case EBML_ID_VOID:

                res = ebml_read_skip(matroska);

                break;

        }



        if (matroska->level_up) {

            matroska->level_up--;

            break;

        }

    }



    if (res)

        return res;



    if (size > 0)

        res = matroska_parse_block(matroska, data, size, pos, cluster_time,

                                   is_keyframe, &track, &pkt);



    if (pkt)

    {

        if (duration != AV_NOPTS_VALUE)

            pkt->duration = duration;

        else if (track >= 0 && track < matroska->num_tracks)

            pkt->duration = matroska->tracks[track]->default_duration / matroska->time_scale;

    }



    return res;

}

static int ipvideo_decode_block_opcode_0x7(IpvideoContext *s)

{

    int x, y;

    unsigned char P[2];

    unsigned int flags;



    /* 2-color encoding */

    CHECK_STREAM_PTR(2);



    P[0] = *s->stream_ptr++;

    P[1] = *s->stream_ptr++;



    if (P[0] <= P[1]) {



        /* need 8 more bytes from the stream */

        CHECK_STREAM_PTR(8);



        for (y = 0; y < 8; y++) {

            flags = *s->stream_ptr++ | 0x100;

            for (; flags != 1; flags >>= 1)

                *s->pixel_ptr++ = P[flags & 1];

            s->pixel_ptr += s->line_inc;

        }



    } else {



        /* need 2 more bytes from the stream */

        CHECK_STREAM_PTR(2);



        flags = bytestream_get_le16(&s->stream_ptr);

        for (y = 0; y < 8; y += 2) {

            for (x = 0; x < 8; x += 2, flags >>= 1) {

                s->pixel_ptr[x                ] =

                s->pixel_ptr[x + 1            ] =

                s->pixel_ptr[x +     s->stride] =

                s->pixel_ptr[x + 1 + s->stride] = P[flags & 1];

            }

            s->pixel_ptr += s->stride * 2;

        }

    }



    /* report success */

    return 0;

}

int attribute_align_arg sws_scale(struct SwsContext *c,

                                  const uint8_t * const srcSlice[],

                                  const int srcStride[], int srcSliceY,

                                  int srcSliceH, uint8_t *const dst[],

                                  const int dstStride[])

{

    int i, ret;

    const uint8_t *src2[4] = { srcSlice[0], srcSlice[1], srcSlice[2], srcSlice[3] };

    uint8_t *dst2[4] = { dst[0], dst[1], dst[2], dst[3] };

    uint8_t *rgb0_tmp = NULL;



    // do not mess up sliceDir if we have a "trailing" 0-size slice

    if (srcSliceH == 0)

        return 0;



    if (!check_image_pointers(srcSlice, c->srcFormat, srcStride)) {

        av_log(c, AV_LOG_ERROR, "bad src image pointers\n");

        return 0;

    }

    if (!check_image_pointers((const uint8_t* const*)dst, c->dstFormat, dstStride)) {

        av_log(c, AV_LOG_ERROR, "bad dst image pointers\n");

        return 0;

    }



    if (c->sliceDir == 0 && srcSliceY != 0 && srcSliceY + srcSliceH != c->srcH) {

        av_log(c, AV_LOG_ERROR, "Slices start in the middle!\n");

        return 0;

    }

    if (c->sliceDir == 0) {

        if (srcSliceY == 0) c->sliceDir = 1; else c->sliceDir = -1;

    }



    if (usePal(c->srcFormat)) {

        for (i = 0; i < 256; i++) {

            int p, r, g, b, y, u, v, a = 0xff;

            if (c->srcFormat == AV_PIX_FMT_PAL8) {

                p = ((const uint32_t *)(srcSlice[1]))[i];

                a = (p >> 24) & 0xFF;

                r = (p >> 16) & 0xFF;

                g = (p >>  8) & 0xFF;

                b =  p        & 0xFF;

            } else if (c->srcFormat == AV_PIX_FMT_RGB8) {

                r = ( i >> 5     ) * 36;

                g = ((i >> 2) & 7) * 36;

                b = ( i       & 3) * 85;

            } else if (c->srcFormat == AV_PIX_FMT_BGR8) {

                b = ( i >> 6     ) * 85;

                g = ((i >> 3) & 7) * 36;

                r = ( i       & 7) * 36;

            } else if (c->srcFormat == AV_PIX_FMT_RGB4_BYTE) {

                r = ( i >> 3     ) * 255;

                g = ((i >> 1) & 3) * 85;

                b = ( i       & 1) * 255;

            } else if (c->srcFormat == AV_PIX_FMT_GRAY8 || c->srcFormat == AV_PIX_FMT_GRAY8A) {

                r = g = b = i;

            } else {

                av_assert1(c->srcFormat == AV_PIX_FMT_BGR4_BYTE);

                b = ( i >> 3     ) * 255;

                g = ((i >> 1) & 3) * 85;

                r = ( i       & 1) * 255;

            }

#define RGB2YUV_SHIFT 15

#define BY ( (int) (0.114 * 219 / 255 * (1 << RGB2YUV_SHIFT) + 0.5))

#define BV (-(int) (0.081 * 224 / 255 * (1 << RGB2YUV_SHIFT) + 0.5))

#define BU ( (int) (0.500 * 224 / 255 * (1 << RGB2YUV_SHIFT) + 0.5))

#define GY ( (int) (0.587 * 219 / 255 * (1 << RGB2YUV_SHIFT) + 0.5))

#define GV (-(int) (0.419 * 224 / 255 * (1 << RGB2YUV_SHIFT) + 0.5))

#define GU (-(int) (0.331 * 224 / 255 * (1 << RGB2YUV_SHIFT) + 0.5))

#define RY ( (int) (0.299 * 219 / 255 * (1 << RGB2YUV_SHIFT) + 0.5))

#define RV ( (int) (0.500 * 224 / 255 * (1 << RGB2YUV_SHIFT) + 0.5))

#define RU (-(int) (0.169 * 224 / 255 * (1 << RGB2YUV_SHIFT) + 0.5))



            y = av_clip_uint8((RY * r + GY * g + BY * b + ( 33 << (RGB2YUV_SHIFT - 1))) >> RGB2YUV_SHIFT);

            u = av_clip_uint8((RU * r + GU * g + BU * b + (257 << (RGB2YUV_SHIFT - 1))) >> RGB2YUV_SHIFT);

            v = av_clip_uint8((RV * r + GV * g + BV * b + (257 << (RGB2YUV_SHIFT - 1))) >> RGB2YUV_SHIFT);

            c->pal_yuv[i]= y + (u<<8) + (v<<16) + ((unsigned)a<<24);



            switch (c->dstFormat) {

            case AV_PIX_FMT_BGR32:

#if !HAVE_BIGENDIAN

            case AV_PIX_FMT_RGB24:

#endif

                c->pal_rgb[i]=  r + (g<<8) + (b<<16) + ((unsigned)a<<24);

                break;

            case AV_PIX_FMT_BGR32_1:

#if HAVE_BIGENDIAN

            case AV_PIX_FMT_BGR24:

#endif

                c->pal_rgb[i]= a + (r<<8) + (g<<16) + ((unsigned)b<<24);

                break;

            case AV_PIX_FMT_RGB32_1:

#if HAVE_BIGENDIAN

            case AV_PIX_FMT_RGB24:

#endif

                c->pal_rgb[i]= a + (b<<8) + (g<<16) + ((unsigned)r<<24);

                break;

            case AV_PIX_FMT_RGB32:

#if !HAVE_BIGENDIAN

            case AV_PIX_FMT_BGR24:

#endif

            default:

                c->pal_rgb[i]=  b + (g<<8) + (r<<16) + ((unsigned)a<<24);

            }

        }

    }



    if (c->src0Alpha && !c->dst0Alpha && isALPHA(c->dstFormat)) {

        uint8_t *base;

        int x,y;

        rgb0_tmp = av_malloc(FFABS(srcStride[0]) * srcSliceH + 32);

        base = srcStride[0] < 0 ? rgb0_tmp - srcStride[0] * (srcSliceH-1) : rgb0_tmp;

        for (y=0; y<srcSliceH; y++){

            memcpy(base + srcStride[0]*y, src2[0] + srcStride[0]*y, 4*c->srcW);

            for (x=c->src0Alpha-1; x<4*c->srcW; x+=4) {

                base[ srcStride[0]*y + x] = 0xFF;

            }

        }

        src2[0] = base;

    }



    // copy strides, so they can safely be modified

    if (c->sliceDir == 1) {

        // slices go from top to bottom

        int srcStride2[4] = { srcStride[0], srcStride[1], srcStride[2],

                              srcStride[3] };

        int dstStride2[4] = { dstStride[0], dstStride[1], dstStride[2],

                              dstStride[3] };



        reset_ptr(src2, c->srcFormat);

        reset_ptr((void*)dst2, c->dstFormat);



        /* reset slice direction at end of frame */

        if (srcSliceY + srcSliceH == c->srcH)

            c->sliceDir = 0;



        ret = c->swScale(c, src2, srcStride2, srcSliceY, srcSliceH, dst2,

                          dstStride2);

    } else {

        // slices go from bottom to top => we flip the image internally

        int srcStride2[4] = { -srcStride[0], -srcStride[1], -srcStride[2],

                              -srcStride[3] };

        int dstStride2[4] = { -dstStride[0], -dstStride[1], -dstStride[2],

                              -dstStride[3] };



        src2[0] += (srcSliceH - 1) * srcStride[0];

        if (!usePal(c->srcFormat))

            src2[1] += ((srcSliceH >> c->chrSrcVSubSample) - 1) * srcStride[1];

        src2[2] += ((srcSliceH >> c->chrSrcVSubSample) - 1) * srcStride[2];

        src2[3] += (srcSliceH - 1) * srcStride[3];

        dst2[0] += ( c->dstH                         - 1) * dstStride[0];

        dst2[1] += ((c->dstH >> c->chrDstVSubSample) - 1) * dstStride[1];

        dst2[2] += ((c->dstH >> c->chrDstVSubSample) - 1) * dstStride[2];

        dst2[3] += ( c->dstH                         - 1) * dstStride[3];



        reset_ptr(src2, c->srcFormat);

        reset_ptr((void*)dst2, c->dstFormat);



        /* reset slice direction at end of frame */

        if (!srcSliceY)

            c->sliceDir = 0;



        ret = c->swScale(c, src2, srcStride2, c->srcH-srcSliceY-srcSliceH,

                          srcSliceH, dst2, dstStride2);

    }



    av_free(rgb0_tmp);

    return ret;

}

static void do_rematrixing(AC3DecodeContext *s)

{

    int bnd, i;

    int end, bndend;

    int tmp0, tmp1;



    end = FFMIN(s->end_freq[1], s->end_freq[2]);



    for(bnd=0; bnd<s->num_rematrixing_bands; bnd++) {

        if(s->rematrixing_flags[bnd]) {

            bndend = FFMIN(end, ff_ac3_rematrix_band_tab[bnd+1]);

            for(i=ff_ac3_rematrix_band_tab[bnd]; i<bndend; i++) {

                tmp0 = s->fixed_coeffs[1][i];

                tmp1 = s->fixed_coeffs[2][i];

                s->fixed_coeffs[1][i] = tmp0 + tmp1;

                s->fixed_coeffs[2][i] = tmp0 - tmp1;

            }

        }

    }

}

static int scan_file(AVFormatContext *avctx, AVStream *vst, AVStream *ast, int file)

{

    MlvContext *mlv = avctx->priv_data;

    AVIOContext *pb = mlv->pb[file];

    int ret;

    while (!avio_feof(pb)) {

        int type;

        unsigned int size;

        type = avio_rl32(pb);

        size = avio_rl32(pb);

        avio_skip(pb, 8); //timestamp

        if (size < 16)

            break;

        size -= 16;

        if (vst && type == MKTAG('R','A','W','I') && size >= 164) {

            vst->codec->width  = avio_rl16(pb);

            vst->codec->height = avio_rl16(pb);




            if (avio_rl32(pb) != 1)

                avpriv_request_sample(avctx, "raw api version");

            avio_skip(pb, 20); // pointer, width, height, pitch, frame_size

            vst->codec->bits_per_coded_sample = avio_rl32(pb);









            avio_skip(pb, 8 + 16 + 24); // black_level, white_level, xywh, active_area, exposure_bias

            if (avio_rl32(pb) != 0x2010100) /* RGGB */

                avpriv_request_sample(avctx, "cfa_pattern");

            avio_skip(pb, 80); // calibration_illuminant1, color_matrix1, dynamic_range

            vst->codec->pix_fmt  = AV_PIX_FMT_BAYER_RGGB16LE;

            vst->codec->codec_tag = MKTAG('B', 'I', 'T', 16);

            size -= 164;

        } else if (ast && type == MKTAG('W', 'A', 'V', 'I') && size >= 16) {

            ret = ff_get_wav_header(avctx, pb, ast->codec, 16, 0);



            size -= 16;

        } else if (type == MKTAG('I','N','F','O')) {

            if (size > 0)

                read_string(avctx, pb, "info", size);

            continue;

        } else if (type == MKTAG('I','D','N','T') && size >= 36) {

            read_string(avctx, pb, "cameraName", 32);

            read_uint32(avctx, pb, "cameraModel", "0x%"PRIx32);

            size -= 36;

            if (size >= 32) {

                read_string(avctx, pb, "cameraSerial", 32);

                size -= 32;


        } else if (type == MKTAG('L','E','N','S') && size >= 48) {

            read_uint16(avctx, pb, "focalLength", "%i");

            read_uint16(avctx, pb, "focalDist", "%i");

            read_uint16(avctx, pb, "aperture", "%i");

            read_uint8(avctx, pb, "stabilizerMode", "%i");

            read_uint8(avctx, pb, "autofocusMode", "%i");

            read_uint32(avctx, pb, "flags", "0x%"PRIx32);

            read_uint32(avctx, pb, "lensID", "%"PRIi32);

            read_string(avctx, pb, "lensName", 32);

            size -= 48;

            if (size >= 32) {

                read_string(avctx, pb, "lensSerial", 32);

                size -= 32;


        } else if (vst && type == MKTAG('V', 'I', 'D', 'F') && size >= 4) {

            uint64_t pts = avio_rl32(pb);

            ff_add_index_entry(&vst->index_entries, &vst->nb_index_entries, &vst->index_entries_allocated_size,

                               avio_tell(pb) - 20, pts, file, 0, AVINDEX_KEYFRAME);

            size -= 4;

        } else if (ast && type == MKTAG('A', 'U', 'D', 'F') && size >= 4) {

            uint64_t pts = avio_rl32(pb);

            ff_add_index_entry(&ast->index_entries, &ast->nb_index_entries, &ast->index_entries_allocated_size,

                               avio_tell(pb) - 20, pts, file, 0, AVINDEX_KEYFRAME);

            size -= 4;

        } else if (vst && type == MKTAG('W','B','A','L') && size >= 28) {

            read_uint32(avctx, pb, "wb_mode", "%"PRIi32);

            read_uint32(avctx, pb, "kelvin", "%"PRIi32);

            read_uint32(avctx, pb, "wbgain_r", "%"PRIi32);

            read_uint32(avctx, pb, "wbgain_g", "%"PRIi32);

            read_uint32(avctx, pb, "wbgain_b", "%"PRIi32);

            read_uint32(avctx, pb, "wbs_gm", "%"PRIi32);

            read_uint32(avctx, pb, "wbs_ba", "%"PRIi32);

            size -= 28;

        } else if (type == MKTAG('R','T','C','I') && size >= 20) {

            char str[32];

            struct tm time = { 0 };

            time.tm_sec    = avio_rl16(pb);

            time.tm_min    = avio_rl16(pb);

            time.tm_hour   = avio_rl16(pb);

            time.tm_mday   = avio_rl16(pb);

            time.tm_mon    = avio_rl16(pb);

            time.tm_year   = avio_rl16(pb);

            time.tm_wday   = avio_rl16(pb);

            time.tm_yday   = avio_rl16(pb);

            time.tm_isdst  = avio_rl16(pb);

            avio_skip(pb, 2);

            if (strftime(str, sizeof(str), "%Y-%m-%d %H:%M:%S", &time))

                av_dict_set(&avctx->metadata, "time", str, 0);

            size -= 20;

        } else if (type == MKTAG('E','X','P','O') && size >= 16) {

            av_dict_set(&avctx->metadata, "isoMode", avio_rl32(pb) ? "auto" : "manual", 0);

            read_uint32(avctx, pb, "isoValue", "%"PRIi32);

            read_uint32(avctx, pb, "isoAnalog", "%"PRIi32);

            read_uint32(avctx, pb, "digitalGain", "%"PRIi32);

            size -= 16;

            if (size >= 8) {

                read_uint64(avctx, pb, "shutterValue", "%"PRIi64);

                size -= 8;


        } else if (type == MKTAG('S','T','Y','L') && size >= 36) {

            read_uint32(avctx, pb, "picStyleId", "%"PRIi32);

            read_uint32(avctx, pb, "contrast", "%"PRIi32);

            read_uint32(avctx, pb, "sharpness", "%"PRIi32);

            read_uint32(avctx, pb, "saturation", "%"PRIi32);

            read_uint32(avctx, pb, "colortone", "%"PRIi32);

            read_string(avctx, pb, "picStyleName", 16);

            size -= 36;

        } else if (type == MKTAG('M','A','R','K')) {

        } else if (type == MKTAG('N','U','L','L')) {

        } else if (type == MKTAG('M','L','V','I')) { /* occurs when MLV and Mnn files are concatenated */

        } else {

            av_log(avctx, AV_LOG_INFO, "unsupported tag %c%c%c%c, size %u\n", type&0xFF, (type>>8)&0xFF, (type>>16)&0xFF, (type>>24)&0xFF, size);


        avio_skip(pb, size);


    return 0;

static int get_codec_data(ByteIOContext *pb, AVStream *vst,

                          AVStream *ast, int myth) {

    frametype_t frametype;

    if (!vst && !myth)

        return 1; // no codec data needed

    while (!url_feof(pb)) {

        int size, subtype;

        frametype = get_byte(pb);

        switch (frametype) {

            case NUV_EXTRADATA:

                subtype = get_byte(pb);

                url_fskip(pb, 6);

                size = PKTSIZE(get_le32(pb));

                if (subtype == 'R') {

                    vst->codec->extradata_size = size;

                    vst->codec->extradata = av_malloc(size);

                    get_buffer(pb, vst->codec->extradata, size);

                    size = 0;

                    if (!myth)

                        return 1;

                }

                break;

            case NUV_MYTHEXT:

                url_fskip(pb, 7);

                size = PKTSIZE(get_le32(pb));

                if (size != 128 * 4)

                    break;

                get_le32(pb); // version

                if (vst) {

                    vst->codec->codec_tag = get_le32(pb);

                    vst->codec->codec_id =

                        codec_get_id(codec_bmp_tags, vst->codec->codec_tag);

                } else

                    url_fskip(pb, 4);



                if (ast) {

                    ast->codec->codec_tag = get_le32(pb);

                    ast->codec->sample_rate = get_le32(pb);

                    ast->codec->bits_per_sample = get_le32(pb);

                    ast->codec->channels = get_le32(pb);

                    ast->codec->codec_id =

                        wav_codec_get_id(ast->codec->codec_tag,

                                         ast->codec->bits_per_sample);

                } else

                    url_fskip(pb, 4 * 4);



                size -= 6 * 4;

                url_fskip(pb, size);

                return 1;

            case NUV_SEEKP:

                size = 11;

                break;

            default:

                url_fskip(pb, 7);

                size = PKTSIZE(get_le32(pb));

                break;

        }

        url_fskip(pb, size);

    }

    return 0;

}

static inline void RENAME(rgb24to15)(const uint8_t *src, uint8_t *dst, unsigned src_size)

{

	const uint8_t *s = src;

	const uint8_t *end;

#ifdef HAVE_MMX

	const uint8_t *mm_end;

#endif

	uint16_t *d = (uint16_t *)dst;

	end = s + src_size;

#ifdef HAVE_MMX

	__asm __volatile(PREFETCH"	%0"::"m"(*src):"memory");

	__asm __volatile(

	    "movq	%0, %%mm7\n\t"

	    "movq	%1, %%mm6\n\t"

	    ::"m"(red_15mask),"m"(green_15mask));

	mm_end = end - 11;

	while(s < mm_end)

	{

	    __asm __volatile(

		PREFETCH" 32%1\n\t"

		"movd	%1, %%mm0\n\t"

		"movd	3%1, %%mm3\n\t"

		"punpckldq 6%1, %%mm0\n\t"

		"punpckldq 9%1, %%mm3\n\t"

		"movq	%%mm0, %%mm1\n\t"

		"movq	%%mm0, %%mm2\n\t"

		"movq	%%mm3, %%mm4\n\t"

		"movq	%%mm3, %%mm5\n\t"

		"psrlq	$3, %%mm0\n\t"

		"psrlq	$3, %%mm3\n\t"

		"pand	%2, %%mm0\n\t"

		"pand	%2, %%mm3\n\t"

		"psrlq	$6, %%mm1\n\t"

		"psrlq	$6, %%mm4\n\t"

		"pand	%%mm6, %%mm1\n\t"

		"pand	%%mm6, %%mm4\n\t"

		"psrlq	$9, %%mm2\n\t"

		"psrlq	$9, %%mm5\n\t"

		"pand	%%mm7, %%mm2\n\t"

		"pand	%%mm7, %%mm5\n\t"

		"por	%%mm1, %%mm0\n\t"

		"por	%%mm4, %%mm3\n\t"

		"por	%%mm2, %%mm0\n\t"

		"por	%%mm5, %%mm3\n\t"

		"psllq	$16, %%mm3\n\t"

		"por	%%mm3, %%mm0\n\t"

		MOVNTQ"	%%mm0, %0\n\t"

		:"=m"(*d):"m"(*s),"m"(blue_15mask):"memory");

		d += 4;

		s += 12;

	}

	__asm __volatile(SFENCE:::"memory");

	__asm __volatile(EMMS:::"memory");

#endif

	while(s < end)

	{

		const int b= *s++;

		const int g= *s++;

		const int r= *s++;

		*d++ = (b>>3) | ((g&0xF8)<<2) | ((r&0xF8)<<7);

	}

}

static int rsd_read_header(AVFormatContext *s)

{

    AVIOContext *pb = s->pb;

    int i, ret, version, start = 0x800;

    AVCodecParameters *par;

    AVStream *st = avformat_new_stream(s, NULL);



    if (!st)

        return AVERROR(ENOMEM);



    avio_skip(pb, 3); // "RSD"

    version = avio_r8(pb) - '0';



    par = st->codecpar;

    par->codec_type = AVMEDIA_TYPE_AUDIO;

    par->codec_tag  = avio_rl32(pb);

    par->codec_id   = ff_codec_get_id(rsd_tags, par->codec_tag);

    if (!par->codec_id) {

        char tag_buf[32];



        av_get_codec_tag_string(tag_buf, sizeof(tag_buf), par->codec_tag);

        for (i=0; i < FF_ARRAY_ELEMS(rsd_unsupported_tags); i++) {

            if (par->codec_tag == rsd_unsupported_tags[i]) {

                avpriv_request_sample(s, "Codec tag: %s", tag_buf);

                return AVERROR_PATCHWELCOME;

            }

        }

        av_log(s, AV_LOG_ERROR, "Unknown codec tag: %s\n", tag_buf);

        return AVERROR_INVALIDDATA;

    }



    par->channels = avio_rl32(pb);

    if (!par->channels)

        return AVERROR_INVALIDDATA;



    avio_skip(pb, 4); // Bit depth

    par->sample_rate = avio_rl32(pb);

    if (!par->sample_rate)

        return AVERROR_INVALIDDATA;



    avio_skip(pb, 4); // Unknown



    switch (par->codec_id) {

    case AV_CODEC_ID_XMA2:

        par->block_align = 2048;

        ff_alloc_extradata(par, 34);

        if (!par->extradata)

            return AVERROR(ENOMEM);

        memset(par->extradata, 0, 34);

        break;

    case AV_CODEC_ID_ADPCM_PSX:

        par->block_align = 16 * par->channels;

        if (pb->seekable)

            st->duration = av_get_audio_frame_duration2(par, avio_size(pb) - start);

        break;

    case AV_CODEC_ID_ADPCM_IMA_RAD:

        par->block_align = 20 * par->channels;

        if (pb->seekable)

            st->duration = av_get_audio_frame_duration2(par, avio_size(pb) - start);

        break;

    case AV_CODEC_ID_ADPCM_IMA_WAV:

        if (version == 2)

            start = avio_rl32(pb);



        par->bits_per_coded_sample = 4;

        par->block_align = 36 * par->channels;

        if (pb->seekable)

            st->duration = av_get_audio_frame_duration2(par, avio_size(pb) - start);

        break;

    case AV_CODEC_ID_ADPCM_THP_LE:

        /* RSD3GADP is mono, so only alloc enough memory

           to store the coeff table for a single channel. */



        start = avio_rl32(pb);



        if ((ret = ff_get_extradata(s, par, s->pb, 32)) < 0)

            return ret;

        if (pb->seekable)

            st->duration = av_get_audio_frame_duration2(par, avio_size(pb) - start);

        break;

    case AV_CODEC_ID_ADPCM_THP:

        par->block_align = 8 * par->channels;

        avio_skip(s->pb, 0x1A4 - avio_tell(s->pb));



        if ((ret = ff_alloc_extradata(st->codecpar, 32 * par->channels)) < 0)

            return ret;



        for (i = 0; i < par->channels; i++) {

            avio_read(s->pb, st->codecpar->extradata + 32 * i, 32);

            avio_skip(s->pb, 8);

        }

        if (pb->seekable)

            st->duration = (avio_size(pb) - start) / (8 * par->channels) * 14;

        break;

    case AV_CODEC_ID_PCM_S16LE:

    case AV_CODEC_ID_PCM_S16BE:

        if (version != 4)

            start = avio_rl32(pb);



        if (pb->seekable)

            st->duration = (avio_size(pb) - start) / 2 / par->channels;

        break;

    }



    avio_skip(pb, start - avio_tell(pb));

    if (par->codec_id == AV_CODEC_ID_XMA2) {

        avio_skip(pb, avio_rb32(pb) + avio_rb32(pb));

        st->duration = avio_rb32(pb);

    }



    avpriv_set_pts_info(st, 64, 1, par->sample_rate);



    return 0;

}

static int http_prepare_data(HTTPContext *c)

{

    int i, len, ret;

    AVFormatContext *ctx;



    switch(c->state) {

    case HTTPSTATE_SEND_DATA_HEADER:

        memset(&c->fmt_ctx, 0, sizeof(c->fmt_ctx));

        pstrcpy(c->fmt_ctx.author, sizeof(c->fmt_ctx.author), 

                c->stream->author);

        pstrcpy(c->fmt_ctx.comment, sizeof(c->fmt_ctx.comment), 

                c->stream->comment);

        pstrcpy(c->fmt_ctx.copyright, sizeof(c->fmt_ctx.copyright), 

                c->stream->copyright);

        pstrcpy(c->fmt_ctx.title, sizeof(c->fmt_ctx.title), 

                c->stream->title);



        /* open output stream by using specified codecs */

        c->fmt_ctx.oformat = c->stream->fmt;

        c->fmt_ctx.nb_streams = c->stream->nb_streams;

        for(i=0;i<c->fmt_ctx.nb_streams;i++) {

            AVStream *st;

            st = av_mallocz(sizeof(AVStream));

            c->fmt_ctx.streams[i] = st;

            /* if file or feed, then just take streams from FFStream struct */

            if (!c->stream->feed || 

                c->stream->feed == c->stream)

                memcpy(st, c->stream->streams[i], sizeof(AVStream));

            else

                memcpy(st, c->stream->feed->streams[c->stream->feed_streams[i]],

                           sizeof(AVStream));

            st->codec.frame_number = 0; /* XXX: should be done in

                                           AVStream, not in codec */

        }

        c->got_key_frame = 0;



        /* prepare header and save header data in a stream */

        if (url_open_dyn_buf(&c->fmt_ctx.pb) < 0) {

            /* XXX: potential leak */

            return -1;

        }

        c->fmt_ctx.pb.is_streamed = 1;



        av_write_header(&c->fmt_ctx);



        len = url_close_dyn_buf(&c->fmt_ctx.pb, &c->pb_buffer);

        c->buffer_ptr = c->pb_buffer;

        c->buffer_end = c->pb_buffer + len;



        c->state = HTTPSTATE_SEND_DATA;

        c->last_packet_sent = 0;

        break;

    case HTTPSTATE_SEND_DATA:

        /* find a new packet */

        {

            AVPacket pkt;



            /* read a packet from the input stream */

            if (c->stream->feed) {

                ffm_set_write_index(c->fmt_in, 

                                    c->stream->feed->feed_write_index,

                                    c->stream->feed->feed_size);

            }



            if (c->stream->max_time && 

                c->stream->max_time + c->start_time - cur_time < 0) {

                /* We have timed out */

                c->state = HTTPSTATE_SEND_DATA_TRAILER;

            } else {

                if (c->is_packetized) {

                    if (compute_send_delay(c) > 0) {

                        c->state = HTTPSTATE_WAIT;

                        return 1; /* state changed */

                    }

                }

                if (av_read_frame(c->fmt_in, &pkt) < 0) {

                    if (c->stream->feed && c->stream->feed->feed_opened) {

                        /* if coming from feed, it means we reached the end of the

                           ffm file, so must wait for more data */

                        c->state = HTTPSTATE_WAIT_FEED;

                        return 1; /* state changed */

                    } else {

                        /* must send trailer now because eof or error */

                        c->state = HTTPSTATE_SEND_DATA_TRAILER;

                    }

                } else {

                    /* update first pts if needed */

                    if (c->first_pts == AV_NOPTS_VALUE)

                        c->first_pts = pkt.pts;



                    /* send it to the appropriate stream */

                    if (c->stream->feed) {

                        /* if coming from a feed, select the right stream */

                        if (c->switch_pending) {

                            c->switch_pending = 0;

                            for(i=0;i<c->stream->nb_streams;i++) {

                                if (c->switch_feed_streams[i] == pkt.stream_index) {

                                    if (pkt.flags & PKT_FLAG_KEY) {

                                        do_switch_stream(c, i);

                                    }

                                }

                                if (c->switch_feed_streams[i] >= 0) {

                                    c->switch_pending = 1;

                                }

                            }

                        }

                        for(i=0;i<c->stream->nb_streams;i++) {

                            if (c->feed_streams[i] == pkt.stream_index) {

                                pkt.stream_index = i;

                                if (pkt.flags & PKT_FLAG_KEY) {

                                    c->got_key_frame |= 1 << i;

                                }

                                /* See if we have all the key frames, then 

                                 * we start to send. This logic is not quite

                                 * right, but it works for the case of a 

                                 * single video stream with one or more

                                 * audio streams (for which every frame is 

                                 * typically a key frame). 

                                 */

                                if (!c->stream->send_on_key || 

                                    ((c->got_key_frame + 1) >> c->stream->nb_streams)) {

                                    goto send_it;

                                }

                            }

                        }

                    } else {

                        AVCodecContext *codec;



                    send_it:

                        /* specific handling for RTP: we use several

                           output stream (one for each RTP

                           connection). XXX: need more abstract handling */

                        if (c->is_packetized) {

                            c->packet_stream_index = pkt.stream_index;

                            ctx = c->rtp_ctx[c->packet_stream_index];

                            codec = &ctx->streams[0]->codec;

                        } else {

                            ctx = &c->fmt_ctx;

                            /* Fudge here */

                            codec = &ctx->streams[pkt.stream_index]->codec;

                        }



                        codec->key_frame = ((pkt.flags & PKT_FLAG_KEY) != 0);



#ifdef PJSG

                        if (codec->codec_type == CODEC_TYPE_AUDIO) {

                            codec->frame_size = (codec->sample_rate * pkt.duration + 500000) / 1000000;

                            /* printf("Calculated size %d, from sr %d, duration %d\n", codec->frame_size, codec->sample_rate, pkt.duration); */

                        }

#endif



                        if (c->is_packetized) {

                            ret = url_open_dyn_packet_buf(&ctx->pb, 

                                                          url_get_max_packet_size(c->rtp_handles[c->packet_stream_index]));

                            c->packet_byte_count = 0;

                            c->packet_start_time_us = av_gettime();

                        } else {

                            ret = url_open_dyn_buf(&ctx->pb);

                        }

                        if (ret < 0) {

                            /* XXX: potential leak */

                            return -1;

                        }

                        if (av_write_packet(ctx, &pkt, pkt.pts)) {

                            c->state = HTTPSTATE_SEND_DATA_TRAILER;

                        }



                        len = url_close_dyn_buf(&ctx->pb, &c->pb_buffer);

                        c->buffer_ptr = c->pb_buffer;

                        c->buffer_end = c->pb_buffer + len;



                        codec->frame_number++;

                    }

#ifndef AV_READ_FRAME

                    av_free_packet(&pkt);

#endif

                }

            }

        }

        break;

    default:

    case HTTPSTATE_SEND_DATA_TRAILER:

        /* last packet test ? */

        if (c->last_packet_sent || c->is_packetized)

            return -1;

        ctx = &c->fmt_ctx;

        /* prepare header */

        if (url_open_dyn_buf(&ctx->pb) < 0) {

            /* XXX: potential leak */

            return -1;

        }

        av_write_trailer(ctx);

        len = url_close_dyn_buf(&ctx->pb, &c->pb_buffer);

        c->buffer_ptr = c->pb_buffer;

        c->buffer_end = c->pb_buffer + len;



        c->last_packet_sent = 1;

        break;

    }

    return 0;

}

static void decode_fixed_sparse(AMRFixed *fixed_sparse, const uint16_t *pulses,

                                const enum Mode mode, const int subframe)

{

    av_assert1(MODE_4k75 <= mode && mode <= MODE_12k2);



    if (mode == MODE_12k2) {

        ff_decode_10_pulses_35bits(pulses, fixed_sparse, gray_decode, 5, 3);

    } else if (mode == MODE_10k2) {

        decode_8_pulses_31bits(pulses, fixed_sparse);

    } else {

        int *pulse_position = fixed_sparse->x;

        int i, pulse_subset;

        const int fixed_index = pulses[0];



        if (mode <= MODE_5k15) {

            pulse_subset      = ((fixed_index >> 3) & 8)     + (subframe << 1);

            pulse_position[0] = ( fixed_index       & 7) * 5 + track_position[pulse_subset];

            pulse_position[1] = ((fixed_index >> 3) & 7) * 5 + track_position[pulse_subset + 1];

            fixed_sparse->n = 2;

        } else if (mode == MODE_5k9) {

            pulse_subset      = ((fixed_index & 1) << 1) + 1;

            pulse_position[0] = ((fixed_index >> 1) & 7) * 5 + pulse_subset;

            pulse_subset      = (fixed_index  >> 4) & 3;

            pulse_position[1] = ((fixed_index >> 6) & 7) * 5 + pulse_subset + (pulse_subset == 3 ? 1 : 0);

            fixed_sparse->n = pulse_position[0] == pulse_position[1] ? 1 : 2;

        } else if (mode == MODE_6k7) {

            pulse_position[0] = (fixed_index        & 7) * 5;

            pulse_subset      = (fixed_index  >> 2) & 2;

            pulse_position[1] = ((fixed_index >> 4) & 7) * 5 + pulse_subset + 1;

            pulse_subset      = (fixed_index  >> 6) & 2;

            pulse_position[2] = ((fixed_index >> 8) & 7) * 5 + pulse_subset + 2;

            fixed_sparse->n = 3;

        } else { // mode <= MODE_7k95

            pulse_position[0] = gray_decode[ fixed_index        & 7];

            pulse_position[1] = gray_decode[(fixed_index >> 3)  & 7] + 1;

            pulse_position[2] = gray_decode[(fixed_index >> 6)  & 7] + 2;

            pulse_subset      = (fixed_index >> 9) & 1;

            pulse_position[3] = gray_decode[(fixed_index >> 10) & 7] + pulse_subset + 3;

            fixed_sparse->n = 4;

        }

        for (i = 0; i < fixed_sparse->n; i++)

            fixed_sparse->y[i] = (pulses[1] >> i) & 1 ? 1.0 : -1.0;

    }

}

static void hb_synthesis(AMRWBContext *ctx, int subframe, float *samples,

                         const float *exc, const float *isf, const float *isf_past)

{

    float hb_lpc[LP_ORDER_16k];

    enum Mode mode = ctx->fr_cur_mode;



    if (mode == MODE_6k60) {

        float e_isf[LP_ORDER_16k]; // ISF vector for extrapolation

        double e_isp[LP_ORDER_16k];



        ff_weighted_vector_sumf(e_isf, isf_past, isf, isfp_inter[subframe],

                                1.0 - isfp_inter[subframe], LP_ORDER);



        extrapolate_isf(e_isf, e_isf);



        e_isf[LP_ORDER_16k - 1] *= 2.0;

        ff_acelp_lsf2lspd(e_isp, e_isf, LP_ORDER_16k);

        ff_amrwb_lsp2lpc(e_isp, hb_lpc, LP_ORDER_16k);



        lpc_weighting(hb_lpc, hb_lpc, 0.9, LP_ORDER_16k);

    } else {

        lpc_weighting(hb_lpc, ctx->lp_coef[subframe], 0.6, LP_ORDER);

    }



    ff_celp_lp_synthesis_filterf(samples, hb_lpc, exc, AMRWB_SFR_SIZE_16k,

                                 (mode == MODE_6k60) ? LP_ORDER_16k : LP_ORDER);

}

static always_inline void dv_set_class_number(DCTELEM* blk, EncBlockInfo* bi, 

                                              const uint8_t* zigzag_scan, int bias)

{

    int i, area;

    int run;

    int classes[] = {12, 24, 36, 0xffff};



    run = 0;

    bi->mb[0] = blk[0]; 

    bi->cno = 0;

    for (area = 0; area < 4; area++) {

       bi->prev_run[area] = run;

       bi->bit_size[area] = 0;

       for (i=mb_area_start[area]; i<mb_area_start[area+1]; i++) {

          bi->mb[i] = (blk[zigzag_scan[i]] / 16);

          while ((bi->mb[i] ^ (bi->mb[i] >> 8)) > classes[bi->cno])

              bi->cno++;



          if (bi->mb[i]) {

              bi->bit_size[area] += dv_rl2vlc_size(run, bi->mb[i]);

	      run = 0;

          } else

              ++run;

       }

    }

    bi->bit_size[3] += 4; /* EOB marker */

    bi->cno += bias;



    if (bi->cno >= 3) { /* FIXME: we have to recreate bit_size[], prev_run[] */

        bi->cno = 3;

	for (i=1; i<64; i++)

	   bi->mb[i] /= 2;

    }

}

static int test_vector_fmul_window(AVFloatDSPContext *fdsp, AVFloatDSPContext *cdsp,

                                   const float *v1, const float *v2, const float *v3)

{

    LOCAL_ALIGNED(32, float, cdst, [LEN]);

    LOCAL_ALIGNED(32, float, odst, [LEN]);

    int ret;



    cdsp->vector_fmul_window(cdst, v1, v2, v3, LEN / 2);

    fdsp->vector_fmul_window(odst, v1, v2, v3, LEN / 2);



    if (ret = compare_floats(cdst, odst, LEN, ARBITRARY_FMUL_WINDOW_CONST))

        av_log(NULL, AV_LOG_ERROR, "vector_fmul_window failed\n");



    return ret;

}

matroska_parse_block(MatroskaDemuxContext *matroska, uint8_t *data, int size,

                     int64_t pos, uint64_t cluster_time, uint64_t duration,

                     int is_keyframe, int is_bframe)

{

    int res = 0;

    int track;

    AVStream *st;

    AVPacket *pkt;

    uint8_t *origdata = data;

    int16_t block_time;

    uint32_t *lace_size = NULL;

    int n, flags, laces = 0;

    uint64_t num;

    int stream_index;



    /* first byte(s): tracknum */

    if ((n = matroska_ebmlnum_uint(data, size, &num)) < 0) {

        av_log(matroska->ctx, AV_LOG_ERROR, "EBML block data error\n");

        av_free(origdata);

        return res;

    }

    data += n;

    size -= n;



    /* fetch track from num */

    track = matroska_find_track_by_num(matroska, num);

    if (size <= 3 || track < 0 || track >= matroska->num_tracks) {

        av_log(matroska->ctx, AV_LOG_INFO,

               "Invalid stream %d or size %u\n", track, size);

        av_free(origdata);

        return res;

    }

    stream_index = matroska->tracks[track]->stream_index;

    if (stream_index < 0 || stream_index >= matroska->ctx->nb_streams) {

        av_free(origdata);

        return res;

    }

    st = matroska->ctx->streams[stream_index];

    if (st->discard >= AVDISCARD_ALL) {

        av_free(origdata);

        return res;

    }

    if (duration == AV_NOPTS_VALUE)

        duration = matroska->tracks[track]->default_duration / matroska->time_scale;



    /* block_time (relative to cluster time) */

    block_time = AV_RB16(data);

    data += 2;

    flags = *data++;

    size -= 3;

    if (is_keyframe == -1)

        is_keyframe = flags & 0x80 ? PKT_FLAG_KEY : 0;



    if (matroska->skip_to_keyframe) {

        if (!is_keyframe || st != matroska->skip_to_stream) {

            av_free(origdata);

            return res;

        }

        matroska->skip_to_keyframe = 0;

    }



    switch ((flags & 0x06) >> 1) {

        case 0x0: /* no lacing */

            laces = 1;

            lace_size = av_mallocz(sizeof(int));

            lace_size[0] = size;

            break;



        case 0x1: /* xiph lacing */

        case 0x2: /* fixed-size lacing */

        case 0x3: /* EBML lacing */

            assert(size>0); // size <=3 is checked before size-=3 above

            laces = (*data) + 1;

            data += 1;

            size -= 1;

            lace_size = av_mallocz(laces * sizeof(int));



            switch ((flags & 0x06) >> 1) {

                case 0x1: /* xiph lacing */ {

                    uint8_t temp;

                    uint32_t total = 0;

                    for (n = 0; res == 0 && n < laces - 1; n++) {

                        while (1) {

                            if (size == 0) {

                                res = -1;

                                break;

                            }

                            temp = *data;

                            lace_size[n] += temp;

                            data += 1;

                            size -= 1;

                            if (temp != 0xff)

                                break;

                        }

                        total += lace_size[n];

                    }

                    lace_size[n] = size - total;

                    break;

                }



                case 0x2: /* fixed-size lacing */

                    for (n = 0; n < laces; n++)

                        lace_size[n] = size / laces;

                    break;



                case 0x3: /* EBML lacing */ {

                    uint32_t total;

                    n = matroska_ebmlnum_uint(data, size, &num);

                    if (n < 0) {

                        av_log(matroska->ctx, AV_LOG_INFO,

                               "EBML block data error\n");

                        break;

                    }

                    data += n;

                    size -= n;

                    total = lace_size[0] = num;

                    for (n = 1; res == 0 && n < laces - 1; n++) {

                        int64_t snum;

                        int r;

                        r = matroska_ebmlnum_sint (data, size, &snum);

                        if (r < 0) {

                            av_log(matroska->ctx, AV_LOG_INFO,

                                   "EBML block data error\n");

                            break;

                        }

                        data += r;

                        size -= r;

                        lace_size[n] = lace_size[n - 1] + snum;

                        total += lace_size[n];

                    }

                    lace_size[n] = size - total;

                    break;

                }

            }

            break;

    }



    if (res == 0) {

        uint64_t timecode = AV_NOPTS_VALUE;



        if (cluster_time != (uint64_t)-1

            && (block_time >= 0 || cluster_time >= -block_time))

            timecode = cluster_time + block_time;



        for (n = 0; n < laces; n++) {

            if (st->codec->codec_id == CODEC_ID_RA_288 ||

                st->codec->codec_id == CODEC_ID_COOK ||

                st->codec->codec_id == CODEC_ID_ATRAC3) {

                MatroskaAudioTrack *audiotrack = (MatroskaAudioTrack *)matroska->tracks[track];

                int a = st->codec->block_align;

                int sps = audiotrack->sub_packet_size;

                int cfs = audiotrack->coded_framesize;

                int h = audiotrack->sub_packet_h;

                int y = audiotrack->sub_packet_cnt;

                int w = audiotrack->frame_size;

                int x;



                if (!audiotrack->pkt_cnt) {

                    if (st->codec->codec_id == CODEC_ID_RA_288)

                        for (x=0; x<h/2; x++)

                            memcpy(audiotrack->buf+x*2*w+y*cfs,

                                   data+x*cfs, cfs);

                    else

                        for (x=0; x<w/sps; x++)

                            memcpy(audiotrack->buf+sps*(h*x+((h+1)/2)*(y&1)+(y>>1)), data+x*sps, sps);



                    if (++audiotrack->sub_packet_cnt >= h) {

                        audiotrack->sub_packet_cnt = 0;

                        audiotrack->pkt_cnt = h*w / a;

                    }

                }

                while (audiotrack->pkt_cnt) {

                    pkt = av_mallocz(sizeof(AVPacket));

                    av_new_packet(pkt, a);

                    memcpy(pkt->data, audiotrack->buf

                           + a * (h*w / a - audiotrack->pkt_cnt--), a);

                    pkt->pos = pos;

                    pkt->stream_index = stream_index;

                    matroska_queue_packet(matroska, pkt);

                }

            } else {

                int result, offset = 0, ilen, olen, pkt_size = lace_size[n];

                uint8_t *pkt_data = data;



                if (matroska->tracks[track]->encoding_scope & 1) {

                    switch (matroska->tracks[track]->encoding_algo) {

                    case MATROSKA_TRACK_ENCODING_COMP_HEADERSTRIP:

                        offset = matroska->tracks[track]->encoding_settings_len;

                        break;

                    case MATROSKA_TRACK_ENCODING_COMP_LZO:

                        pkt_data = NULL;

                        do {

                            ilen = lace_size[n];

                            olen = pkt_size *= 3;

                            pkt_data = av_realloc(pkt_data,

                                                  pkt_size+LZO_OUTPUT_PADDING);

                            result = lzo1x_decode(pkt_data, &olen, data, &ilen);

                        } while (result==LZO_OUTPUT_FULL && pkt_size<10000000);

                        if (result) {

                            av_free(pkt_data);

                            continue;

                        }

                        pkt_size -= olen;

                        break;

#ifdef CONFIG_ZLIB

                    case MATROSKA_TRACK_ENCODING_COMP_ZLIB: {

                        z_stream zstream = {0};

                        pkt_data = NULL;

                        if (inflateInit(&zstream) != Z_OK)

                            continue;

                        zstream.next_in = data;

                        zstream.avail_in = lace_size[n];

                        do {

                            pkt_size *= 3;

                            pkt_data = av_realloc(pkt_data, pkt_size);

                            zstream.avail_out = pkt_size - zstream.total_out;

                            zstream.next_out = pkt_data + zstream.total_out;

                            result = inflate(&zstream, Z_NO_FLUSH);

                        } while (result==Z_OK && pkt_size<10000000);

                        pkt_size = zstream.total_out;

                        inflateEnd(&zstream);

                        if (result != Z_STREAM_END) {

                            av_free(pkt_data);

                            continue;

                        }

                        break;

                    }

#endif

#ifdef CONFIG_BZLIB

                    case MATROSKA_TRACK_ENCODING_COMP_BZLIB: {

                        bz_stream bzstream = {0};

                        pkt_data = NULL;

                        if (BZ2_bzDecompressInit(&bzstream, 0, 0) != BZ_OK)

                            continue;

                        bzstream.next_in = data;

                        bzstream.avail_in = lace_size[n];

                        do {

                            pkt_size *= 3;

                            pkt_data = av_realloc(pkt_data, pkt_size);

                            bzstream.avail_out = pkt_size - bzstream.total_out_lo32;

                            bzstream.next_out = pkt_data + bzstream.total_out_lo32;

                            result = BZ2_bzDecompress(&bzstream);

                        } while (result==BZ_OK && pkt_size<10000000);

                        pkt_size = bzstream.total_out_lo32;

                        BZ2_bzDecompressEnd(&bzstream);

                        if (result != BZ_STREAM_END) {

                            av_free(pkt_data);

                            continue;

                        }

                        break;

                    }

#endif

                    }

                }



                pkt = av_mallocz(sizeof(AVPacket));

                /* XXX: prevent data copy... */

                if (av_new_packet(pkt, pkt_size+offset) < 0) {


                    res = AVERROR(ENOMEM);

                    n = laces-1;

                    break;

                }

                if (offset)

                    memcpy (pkt->data, matroska->tracks[track]->encoding_settings, offset);

                memcpy (pkt->data+offset, pkt_data, pkt_size);



                if (n == 0)

                    pkt->flags = is_keyframe;

                pkt->stream_index = stream_index;



                pkt->pts = timecode;

                pkt->pos = pos;

                pkt->duration = duration;



                matroska_queue_packet(matroska, pkt);

            }



            if (timecode != AV_NOPTS_VALUE)

                timecode = duration ? timecode + duration : AV_NOPTS_VALUE;

            data += lace_size[n];

        }

    }



    av_free(lace_size);

    av_free(origdata);

    return res;

}

yuv2planeX_16_c_template(const int16_t *filter, int filterSize,

                         const int32_t **src, uint16_t *dest, int dstW,

                         int big_endian, int output_bits)

{

    int i;

    int shift = 15;

    av_assert0(output_bits == 16);



    for (i = 0; i < dstW; i++) {

        int val = 1 << (shift - 1);

        int j;



        /* range of val is [0,0x7FFFFFFF], so 31 bits, but with lanczos/spline

         * filters (or anything with negative coeffs, the range can be slightly

         * wider in both directions. To account for this overflow, we subtract

         * a constant so it always fits in the signed range (assuming a

         * reasonable filterSize), and re-add that at the end. */

        val -= 0x40000000;

        for (j = 0; j < filterSize; j++)

            val += src[j][i] * filter[j];



        output_pixel(&dest[i], val, 0x8000, int);

    }

}

static int generate_coupling_coordinates(AC3DecodeContext * ctx)

{

    ac3_audio_block *ab = &ctx->audio_block;

    uint8_t exp, mstrcplco;

    int16_t mant;

    uint32_t cplbndstrc = (1 << ab->ncplsubnd) >> 1;

    int ch, bnd, sbnd;

    float cplco;



    if (ab->cplcoe)

        for (ch = 0; ch < ctx->bsi.nfchans; ch++)

            if (ab->cplcoe & (1 << ch)) {

                mstrcplco = 3 * ab->mstrcplco[ch];

                sbnd = ab->cplbegf;

                for (bnd = 0; bnd < ab->ncplbnd; bnd++) {

                    exp = ab->cplcoexp[ch][bnd];

                    if (exp == 15)

                        mant = ab->cplcomant[ch][bnd] <<= 14;

                    else

                        mant = (ab->cplcomant[ch][bnd] | 0x10) << 13;

                    cplco = to_float(exp + mstrcplco, mant);

                    if (ctx->bsi.acmod == 0x02 && (ab->flags & AC3_AB_PHSFLGINU) && ch == 1

                            && (ab->phsflg & (1 << bnd)))

                        cplco = -cplco; /* invert the right channel */

                    ab->cplco[ch][sbnd++] = cplco;

                    while (cplbndstrc & ab->cplbndstrc) {

                        cplbndstrc >>= 1;

                        ab->cplco[ch][sbnd++] = cplco;

                    }

                    cplbndstrc >>= 1;

                }

            }



    return 0;

}

