static int plot_cqt(AVFilterLink *inlink)

{

    AVFilterContext *ctx = inlink->dst;

    ShowCQTContext *s = ctx->priv;

    AVFilterLink *outlink = ctx->outputs[0];

    int fft_len = 1 << s->fft_bits;

    FFTSample result[VIDEO_WIDTH][4];

    int x, y, ret = 0;

    int linesize = s->outpicref->linesize[0];

    int video_scale = s->fullhd ? 2 : 1;

    int video_width = (VIDEO_WIDTH/2) * video_scale;

    int spectogram_height = (SPECTOGRAM_HEIGHT/2) * video_scale;

    int spectogram_start = (SPECTOGRAM_START/2) * video_scale;

    int font_height = (FONT_HEIGHT/2) * video_scale;



    /* real part contains left samples, imaginary part contains right samples */

    memcpy(s->fft_result, s->fft_data, fft_len * sizeof(*s->fft_data));

    av_fft_permute(s->fft_context, s->fft_result);

    av_fft_calc(s->fft_context, s->fft_result);

    s->fft_result[fft_len] = s->fft_result[0];



    /* calculating cqt */

    for (x = 0; x < VIDEO_WIDTH; x++) {

        int u;

        FFTComplex v = {0,0};

        FFTComplex w = {0,0};

        FFTComplex l, r;



        for (u = 0; u < s->coeffs[x].len; u++) {

            FFTSample value = s->coeffs[x].values[u];

            int index = s->coeffs[x].start + u;

            v.re += value * s->fft_result[index].re;

            v.im += value * s->fft_result[index].im;

            w.re += value * s->fft_result[fft_len - index].re;

            w.im += value * s->fft_result[fft_len - index].im;

        }



        /* separate left and right, (and multiply by 2.0) */

        l.re = v.re + w.re;

        l.im = v.im - w.im;

        r.re = w.im + v.im;

        r.im = w.re - v.re;

        /* result is power, not amplitude */

        result[x][0] = l.re * l.re + l.im * l.im;

        result[x][2] = r.re * r.re + r.im * r.im;

        result[x][1] = 0.5f * (result[x][0] + result[x][2]);



        if (s->gamma2 == 1.0f)

            result[x][3] = result[x][1];

        else if (s->gamma2 == 2.0f)

            result[x][3] = sqrtf(result[x][1]);

        else if (s->gamma2 == 3.0f)

            result[x][3] = cbrtf(result[x][1]);

        else if (s->gamma2 == 4.0f)

            result[x][3] = sqrtf(sqrtf(result[x][1]));

        else

            result[x][3] = expf(logf(result[x][1]) * (1.0f / s->gamma2));



        result[x][0] = FFMIN(1.0f, result[x][0]);

        result[x][1] = FFMIN(1.0f, result[x][1]);

        result[x][2] = FFMIN(1.0f, result[x][2]);

        if (s->gamma == 1.0f) {

            result[x][0] = 255.0f * result[x][0];

            result[x][1] = 255.0f * result[x][1];

            result[x][2] = 255.0f * result[x][2];

        } else if (s->gamma == 2.0f) {

            result[x][0] = 255.0f * sqrtf(result[x][0]);

            result[x][1] = 255.0f * sqrtf(result[x][1]);

            result[x][2] = 255.0f * sqrtf(result[x][2]);

        } else if (s->gamma == 3.0f) {

            result[x][0] = 255.0f * cbrtf(result[x][0]);

            result[x][1] = 255.0f * cbrtf(result[x][1]);

            result[x][2] = 255.0f * cbrtf(result[x][2]);

        } else if (s->gamma == 4.0f) {

            result[x][0] = 255.0f * sqrtf(sqrtf(result[x][0]));

            result[x][1] = 255.0f * sqrtf(sqrtf(result[x][1]));

            result[x][2] = 255.0f * sqrtf(sqrtf(result[x][2]));

        } else {

            result[x][0] = 255.0f * expf(logf(result[x][0]) * (1.0f / s->gamma));

            result[x][1] = 255.0f * expf(logf(result[x][1]) * (1.0f / s->gamma));

            result[x][2] = 255.0f * expf(logf(result[x][2]) * (1.0f / s->gamma));

        }

    }



    if (!s->fullhd) {

        for (x = 0; x < video_width; x++) {

            result[x][0] = 0.5f * (result[2*x][0] + result[2*x+1][0]);

            result[x][1] = 0.5f * (result[2*x][1] + result[2*x+1][1]);

            result[x][2] = 0.5f * (result[2*x][2] + result[2*x+1][2]);

            result[x][3] = 0.5f * (result[2*x][3] + result[2*x+1][3]);

        }

    }



    for (x = 0; x < video_width; x++) {

        s->spectogram[s->spectogram_index*linesize + 3*x] = result[x][0] + 0.5f;

        s->spectogram[s->spectogram_index*linesize + 3*x + 1] = result[x][1] + 0.5f;

        s->spectogram[s->spectogram_index*linesize + 3*x + 2] = result[x][2] + 0.5f;

    }



    /* drawing */

    if (!s->spectogram_count) {

        uint8_t *data = (uint8_t*) s->outpicref->data[0];

        float rcp_result[VIDEO_WIDTH];

        int total_length = linesize * spectogram_height;

        int back_length = linesize * s->spectogram_index;



        for (x = 0; x < video_width; x++)

            rcp_result[x] = 1.0f / (result[x][3]+0.0001f);



        /* drawing bar */

        for (y = 0; y < spectogram_height; y++) {

            float height = (spectogram_height - y) * (1.0f/spectogram_height);

            uint8_t *lineptr = data + y * linesize;

            for (x = 0; x < video_width; x++) {

                float mul;

                if (result[x][3] <= height) {

                    *lineptr++ = 0;

                    *lineptr++ = 0;

                    *lineptr++ = 0;

                } else {

                    mul = (result[x][3] - height) * rcp_result[x];

                    *lineptr++ = mul * result[x][0] + 0.5f;

                    *lineptr++ = mul * result[x][1] + 0.5f;

                    *lineptr++ = mul * result[x][2] + 0.5f;

                }

            }

        }



        /* drawing font */

        if (s->font_alpha && s->draw_text) {

            for (y = 0; y < font_height; y++) {

                uint8_t *lineptr = data + (spectogram_height + y) * linesize;

                uint8_t *spectogram_src = s->spectogram + s->spectogram_index * linesize;

                uint8_t *fontcolor_value = s->fontcolor_value;

                for (x = 0; x < video_width; x++) {

                    uint8_t alpha = s->font_alpha[y*video_width+x];

                    lineptr[3*x] = (spectogram_src[3*x] * (255-alpha) + fontcolor_value[0] * alpha + 255) >> 8;

                    lineptr[3*x+1] = (spectogram_src[3*x+1] * (255-alpha) + fontcolor_value[1] * alpha + 255) >> 8;

                    lineptr[3*x+2] = (spectogram_src[3*x+2] * (255-alpha) + fontcolor_value[2] * alpha + 255) >> 8;

                    fontcolor_value += 3;

                }

            }

        } else if (s->draw_text) {

            for (y = 0; y < font_height; y++) {

                uint8_t *lineptr = data + (spectogram_height + y) * linesize;

                memcpy(lineptr, s->spectogram + s->spectogram_index * linesize, video_width*3);

            }

            for (x = 0; x < video_width; x += video_width/10) {

                int u;

                static const char str[] = "EF G A BC D ";

                uint8_t *startptr = data + spectogram_height * linesize + x * 3;

                for (u = 0; str[u]; u++) {

                    int v;

                    for (v = 0; v < 16; v++) {

                        uint8_t *p = startptr + v * linesize * video_scale + 8 * 3 * u * video_scale;

                        int ux = x + 8 * u * video_scale;

                        int mask;

                        for (mask = 0x80; mask; mask >>= 1) {

                            if (mask & avpriv_vga16_font[str[u] * 16 + v]) {

                                p[0] = s->fontcolor_value[3*ux];

                                p[1] = s->fontcolor_value[3*ux+1];

                                p[2] = s->fontcolor_value[3*ux+2];

                                if (video_scale == 2) {

                                    p[linesize] = p[0];

                                    p[linesize+1] = p[1];

                                    p[linesize+2] = p[2];

                                    p[3] = p[linesize+3] = s->fontcolor_value[3*ux+3];

                                    p[4] = p[linesize+4] = s->fontcolor_value[3*ux+4];

                                    p[5] = p[linesize+5] = s->fontcolor_value[3*ux+5];

                                }

                            }

                            p  += 3 * video_scale;

                            ux += video_scale;

                        }

                    }

                }

            }

        } else {

            for (y = 0; y < font_height; y++) {

                uint8_t *lineptr = data + (spectogram_height + y) * linesize;

                uint8_t *spectogram_src = s->spectogram + s->spectogram_index * linesize;

                for (x = 0; x < video_width; x++) {

                    lineptr[3*x] = spectogram_src[3*x];

                    lineptr[3*x+1] = spectogram_src[3*x+1];

                    lineptr[3*x+2] = spectogram_src[3*x+2];

                }

            }

        }



        /* drawing spectogram/sonogram */

        data += spectogram_start * linesize;

        memcpy(data, s->spectogram + s->spectogram_index*linesize, total_length - back_length);



        data += total_length - back_length;

        if (back_length)

            memcpy(data, s->spectogram, back_length);



        s->outpicref->pts = s->frame_count;

        ret = ff_filter_frame(outlink, av_frame_clone(s->outpicref));

        s->req_fullfilled = 1;

        s->frame_count++;

    }

    s->spectogram_count = (s->spectogram_count + 1) % s->count;

    s->spectogram_index = (s->spectogram_index + spectogram_height - 1) % spectogram_height;

    return ret;

}

static void tqi_calculate_qtable(TqiContext *t, int quant)

{

    const int qscale = (215 - 2*quant)*5;

    int i;



    t->intra_matrix[0] = (ff_inv_aanscales[0] * ff_mpeg1_default_intra_matrix[0]) >> 11;

    for(i=1; i<64; i++)

        t->intra_matrix[i] = (ff_inv_aanscales[i] * ff_mpeg1_default_intra_matrix[i] * qscale + 32) >> 14;

}

static void free_input_threads(void)

{

    int i;



    if (nb_input_files == 1)

        return;



    transcoding_finished = 1;



    for (i = 0; i < nb_input_files; i++) {

        InputFile *f = input_files[i];

        AVPacket pkt;



        if (f->joined)

            continue;



        pthread_mutex_lock(&f->fifo_lock);

        while (av_fifo_size(f->fifo)) {

            av_fifo_generic_read(f->fifo, &pkt, sizeof(pkt), NULL);

            av_free_packet(&pkt);

        }

        pthread_cond_signal(&f->fifo_cond);

        pthread_mutex_unlock(&f->fifo_lock);



        pthread_join(f->thread, NULL);

        f->joined = 1;



        while (av_fifo_size(f->fifo)) {

            av_fifo_generic_read(f->fifo, &pkt, sizeof(pkt), NULL);

            av_free_packet(&pkt);

        }

        av_fifo_free(f->fifo);

    }

}

static int vc1_decode_p_block(VC1Context *v, DCTELEM block[64], int n, int mquant, int ttmb, int first_block,

                              uint8_t *dst, int linesize, int skip_block, int apply_filter, int cbp_top, int cbp_left)

{

    MpegEncContext *s = &v->s;

    GetBitContext *gb = &s->gb;

    int i, j;

    int subblkpat = 0;

    int scale, off, idx, last, skip, value;

    int ttblk = ttmb & 7;

    int pat = 0;



    if(ttmb == -1) {

        ttblk = ff_vc1_ttblk_to_tt[v->tt_index][get_vlc2(gb, ff_vc1_ttblk_vlc[v->tt_index].table, VC1_TTBLK_VLC_BITS, 1)];

    }

    if(ttblk == TT_4X4) {

        subblkpat = ~(get_vlc2(gb, ff_vc1_subblkpat_vlc[v->tt_index].table, VC1_SUBBLKPAT_VLC_BITS, 1) + 1);

    }

    if((ttblk != TT_8X8 && ttblk != TT_4X4) && (v->ttmbf || (ttmb != -1 && (ttmb & 8) && !first_block))) {

        subblkpat = decode012(gb);

        if(subblkpat) subblkpat ^= 3; //swap decoded pattern bits

        if(ttblk == TT_8X4_TOP || ttblk == TT_8X4_BOTTOM) ttblk = TT_8X4;

        if(ttblk == TT_4X8_RIGHT || ttblk == TT_4X8_LEFT) ttblk = TT_4X8;

    }

    scale = 2 * mquant + ((v->pq == mquant) ? v->halfpq : 0);



    // convert transforms like 8X4_TOP to generic TT and SUBBLKPAT

    if(ttblk == TT_8X4_TOP || ttblk == TT_8X4_BOTTOM) {

        subblkpat = 2 - (ttblk == TT_8X4_TOP);

        ttblk = TT_8X4;

    }

    if(ttblk == TT_4X8_RIGHT || ttblk == TT_4X8_LEFT) {

        subblkpat = 2 - (ttblk == TT_4X8_LEFT);

        ttblk = TT_4X8;

    }

    switch(ttblk) {

    case TT_8X8:

        pat = 0xF;

        i = 0;

        last = 0;

        while (!last) {

            vc1_decode_ac_coeff(v, &last, &skip, &value, v->codingset2);

            i += skip;

            if(i > 63)

                break;

            idx = wmv1_scantable[0][i++];

            block[idx] = value * scale;

            if(!v->pquantizer)

                block[idx] += (block[idx] < 0) ? -mquant : mquant;

        }

        if(!skip_block){

            s->dsp.vc1_inv_trans_8x8(block);

            s->dsp.add_pixels_clamped(block, dst, linesize);

            if(apply_filter && cbp_top  & 0xC)

                vc1_loop_filter(dst, 1, linesize, 8, mquant);

            if(apply_filter && cbp_left & 0xA)

                vc1_loop_filter(dst, linesize, 1, 8, mquant);

        }

        break;

    case TT_4X4:

        pat = ~subblkpat & 0xF;

        for(j = 0; j < 4; j++) {

            last = subblkpat & (1 << (3 - j));

            i = 0;

            off = (j & 1) * 4 + (j & 2) * 16;

            while (!last) {

                vc1_decode_ac_coeff(v, &last, &skip, &value, v->codingset2);

                i += skip;

                if(i > 15)

                    break;

                idx = ff_vc1_simple_progressive_4x4_zz[i++];

                block[idx + off] = value * scale;

                if(!v->pquantizer)

                    block[idx + off] += (block[idx + off] < 0) ? -mquant : mquant;

            }

            if(!(subblkpat & (1 << (3 - j))) && !skip_block){

                s->dsp.vc1_inv_trans_4x4(dst + (j&1)*4 + (j&2)*2*linesize, linesize, block + off);

                if(apply_filter && (j&2 ? pat & (1<<(j-2)) : (cbp_top & (1 << (j + 2)))))

                    vc1_loop_filter(dst + (j&1)*4 + (j&2)*2*linesize, 1, linesize, 4, mquant);

                if(apply_filter && (j&1 ? pat & (1<<(j-1)) : (cbp_left & (1 << (j + 1)))))

                    vc1_loop_filter(dst + (j&1)*4 + (j&2)*2*linesize, linesize, 1, 4, mquant);

            }

        }

        break;

    case TT_8X4:

        pat = ~((subblkpat & 2)*6 + (subblkpat & 1)*3) & 0xF;

        for(j = 0; j < 2; j++) {

            last = subblkpat & (1 << (1 - j));

            i = 0;

            off = j * 32;

            while (!last) {

                vc1_decode_ac_coeff(v, &last, &skip, &value, v->codingset2);

                i += skip;

                if(i > 31)

                    break;

                idx = v->zz_8x4[i++]+off;

                block[idx] = value * scale;

                if(!v->pquantizer)

                    block[idx] += (block[idx] < 0) ? -mquant : mquant;

            }

            if(!(subblkpat & (1 << (1 - j))) && !skip_block){

                s->dsp.vc1_inv_trans_8x4(dst + j*4*linesize, linesize, block + off);

                if(apply_filter && j ? pat & 0x3 : (cbp_top & 0xC))

                    vc1_loop_filter(dst + j*4*linesize, 1, linesize, 8, mquant);

                if(apply_filter && cbp_left & (2 << j))

                    vc1_loop_filter(dst + j*4*linesize, linesize, 1, 4, mquant);

            }

        }

        break;

    case TT_4X8:

        pat = ~(subblkpat*5) & 0xF;

        for(j = 0; j < 2; j++) {

            last = subblkpat & (1 << (1 - j));

            i = 0;

            off = j * 4;

            while (!last) {

                vc1_decode_ac_coeff(v, &last, &skip, &value, v->codingset2);

                i += skip;

                if(i > 31)

                    break;

                idx = v->zz_4x8[i++]+off;

                block[idx] = value * scale;

                if(!v->pquantizer)

                    block[idx] += (block[idx] < 0) ? -mquant : mquant;

            }

            if(!(subblkpat & (1 << (1 - j))) && !skip_block){

                s->dsp.vc1_inv_trans_4x8(dst + j*4, linesize, block + off);

                if(apply_filter && cbp_top & (2 << j))

                    vc1_loop_filter(dst + j*4, 1, linesize, 4, mquant);

                if(apply_filter && j ? pat & 0x5 : (cbp_left & 0xA))

                    vc1_loop_filter(dst + j*4, linesize, 1, 8, mquant);

            }

        }

        break;

    }

    return pat;

}

static int ac3_eac3_probe(AVProbeData *p, enum AVCodecID expected_codec_id)

{

    int max_frames, first_frames = 0, frames;

    uint8_t *buf, *buf2, *end;

    AC3HeaderInfo hdr;

    GetBitContext gbc;

    enum AVCodecID codec_id = AV_CODEC_ID_AC3;



    max_frames = 0;

    buf = p->buf;

    end = buf + p->buf_size;



    for(; buf < end; buf++) {

        if(buf > p->buf && !(buf[0] == 0x0B && buf[1] == 0x77)

                        && !(buf[0] == 0x77 && buf[1] == 0x0B) )

            continue;

        buf2 = buf;



        for(frames = 0; buf2 < end; frames++) {

            uint8_t buf3[4096];

            int i;

            if(!memcmp(buf2, "\x1\x10\0\0\0\0\0\0", 8))

                buf2+=16;

            if (buf[0] == 0x77 && buf[1] == 0x0B) {

                for(i=0; i<8; i+=2) {

                    buf3[i  ] = buf[i+1];

                    buf3[i+1] = buf[i  ];

                }

                init_get_bits(&gbc, buf3, 54);

            }else

                init_get_bits(&gbc, buf2, 54);

            if(avpriv_ac3_parse_header(&gbc, &hdr) < 0)

                break;

            if(buf2 + hdr.frame_size > end)

                break;

            if (buf[0] == 0x77 && buf[1] == 0x0B) {

                av_assert0(hdr.frame_size <= sizeof(buf3));

                for(; i<hdr.frame_size; i+=2) {

                    buf3[i  ] = buf[i+1];

                    buf3[i+1] = buf[i  ];

                }

            }

            if(av_crc(av_crc_get_table(AV_CRC_16_ANSI), 0, gbc.buffer + 2, hdr.frame_size - 2))

                break;

            if (hdr.bitstream_id > 10)

                codec_id = AV_CODEC_ID_EAC3;

            buf2 += hdr.frame_size;

        }

        max_frames = FFMAX(max_frames, frames);

        if(buf == p->buf)

            first_frames = frames;

    }

    if(codec_id != expected_codec_id) return 0;

    // keep this in sync with mp3 probe, both need to avoid

    // issues with MPEG-files!

    if   (first_frames>=4) return AVPROBE_SCORE_MAX/2+1;

    else if(max_frames>200)return AVPROBE_SCORE_MAX/2;

    else if(max_frames>=4) return AVPROBE_SCORE_MAX/4;

    else if(max_frames>=1) return 1;

    else                   return 0;

}

static int asf_read_frame_header(AVFormatContext *s, AVIOContext *pb){

    ASFContext *asf = s->priv_data;

    int rsize = 1;

    int num = avio_r8(pb);

    int64_t ts0, ts1;



    asf->packet_segments--;

    asf->packet_key_frame = num >> 7;

    asf->stream_index = asf->asfid2avid[num & 0x7f];

    // sequence should be ignored!

    DO_2BITS(asf->packet_property >> 4, asf->packet_seq, 0);

    DO_2BITS(asf->packet_property >> 2, asf->packet_frag_offset, 0);

    DO_2BITS(asf->packet_property, asf->packet_replic_size, 0);

//printf("key:%d stream:%d seq:%d offset:%d replic_size:%d\n", asf->packet_key_frame, asf->stream_index, asf->packet_seq, //asf->packet_frag_offset, asf->packet_replic_size);

    if (asf->packet_replic_size >= 8) {

        asf->packet_obj_size = avio_rl32(pb);

        if(asf->packet_obj_size >= (1<<24) || asf->packet_obj_size <= 0){

            av_log(s, AV_LOG_ERROR, "packet_obj_size invalid\n");



        asf->packet_frag_timestamp = avio_rl32(pb); // timestamp

        if(asf->packet_replic_size >= 8+38+4){

//            for(i=0; i<asf->packet_replic_size-8; i++)

//                av_log(s, AV_LOG_DEBUG, "%02X ",avio_r8(pb));

//            av_log(s, AV_LOG_DEBUG, "\n");

            avio_skip(pb, 10);

            ts0= avio_rl64(pb);

            ts1= avio_rl64(pb);

            avio_skip(pb, 12);

            avio_rl32(pb);

            avio_skip(pb, asf->packet_replic_size - 8 - 38 - 4);

            if(ts0!= -1) asf->packet_frag_timestamp= ts0/10000;

            else         asf->packet_frag_timestamp= AV_NOPTS_VALUE;

        }else

            avio_skip(pb, asf->packet_replic_size - 8);

        rsize += asf->packet_replic_size; // FIXME - check validity

    } else if (asf->packet_replic_size==1){

        // multipacket - frag_offset is beginning timestamp

        asf->packet_time_start = asf->packet_frag_offset;

        asf->packet_frag_offset = 0;

        asf->packet_frag_timestamp = asf->packet_timestamp;



        asf->packet_time_delta = avio_r8(pb);

        rsize++;

    }else if(asf->packet_replic_size!=0){

        av_log(s, AV_LOG_ERROR, "unexpected packet_replic_size of %d\n", asf->packet_replic_size);







    if (asf->packet_flags & 0x01) {

        DO_2BITS(asf->packet_segsizetype >> 6, asf->packet_frag_size, 0); // 0 is illegal

        if(asf->packet_frag_size > asf->packet_size_left - rsize){

            if (asf->packet_frag_size > asf->packet_size_left - rsize + asf->packet_padsize) {

                av_log(s, AV_LOG_ERROR, "packet_frag_size is invalid (%d-%d)\n", asf->packet_size_left, rsize);


            } else {

                int diff = asf->packet_frag_size - (asf->packet_size_left - rsize);

                asf->packet_size_left += diff;

                asf->packet_padsize   -= diff;



        //printf("Fragsize %d\n", asf->packet_frag_size);

    } else {

        asf->packet_frag_size = asf->packet_size_left - rsize;

        //printf("Using rest  %d %d %d\n", asf->packet_frag_size, asf->packet_size_left, rsize);


    if (asf->packet_replic_size == 1) {

        asf->packet_multi_size = asf->packet_frag_size;

        if (asf->packet_multi_size > asf->packet_size_left)



    asf->packet_size_left -= rsize;

    //printf("___objsize____  %d   %d    rs:%d\n", asf->packet_obj_size, asf->packet_frag_offset, rsize);



    return 0;

static void mp_decode_line(MotionPixelsContext *mp, GetBitContext *gb, int y)

{

    YuvPixel p;

    const int y0 = y * mp->avctx->width;

    int w, i, x = 0;



    p = mp->vpt[y];

    if (mp->changes_map[y0 + x] == 0) {

        memset(mp->gradient_scale, 1, sizeof(mp->gradient_scale));

        ++x;

    }

    while (x < mp->avctx->width) {

        w = mp->changes_map[y0 + x];

        if (w != 0) {

            if ((y & 3) == 0) {

                if (mp->changes_map[y0 + x + mp->avctx->width] < w ||

                    mp->changes_map[y0 + x + mp->avctx->width * 2] < w ||

                    mp->changes_map[y0 + x + mp->avctx->width * 3] < w) {

                    for (i = (x + 3) & ~3; i < x + w; i += 4) {

                        mp->hpt[((y / 4) * mp->avctx->width + i) / 4] = mp_get_yuv_from_rgb(mp, i, y);

                    }

                }

            }

            x += w;

            memset(mp->gradient_scale, 1, sizeof(mp->gradient_scale));

            p = mp_get_yuv_from_rgb(mp, x - 1, y);

        } else {

            p.y += mp_gradient(mp, 0, mp_get_vlc(mp, gb));


            if ((x & 3) == 0) {

                if ((y & 3) == 0) {

                    p.v += mp_gradient(mp, 1, mp_get_vlc(mp, gb));


                    p.u += mp_gradient(mp, 2, mp_get_vlc(mp, gb));


                    mp->hpt[((y / 4) * mp->avctx->width + x) / 4] = p;

                } else {

                    p.v = mp->hpt[((y / 4) * mp->avctx->width + x) / 4].v;

                    p.u = mp->hpt[((y / 4) * mp->avctx->width + x) / 4].u;

                }

            }

            mp_set_rgb_from_yuv(mp, x, y, &p);

            ++x;

        }

    }

}

void avcodec_string(char *buf, int buf_size, AVCodecContext *enc, int encode)

{

    const char *codec_type;

    const char *codec_name;

    const char *profile = NULL;

    const AVCodec *p;

    int64_t bitrate;

    int new_line = 0;

    AVRational display_aspect_ratio;

    const char *separator = enc->dump_separator ? (const char *)enc->dump_separator : ", ";



    if (!buf || buf_size <= 0)

        return;

    codec_type = av_get_media_type_string(enc->codec_type);

    codec_name = avcodec_get_name(enc->codec_id);

    if (enc->profile != FF_PROFILE_UNKNOWN) {

        if (enc->codec)

            p = enc->codec;

        else

            p = encode ? avcodec_find_encoder(enc->codec_id) :

                        avcodec_find_decoder(enc->codec_id);

        if (p)

            profile = av_get_profile_name(p, enc->profile);

    }



    snprintf(buf, buf_size, "%s: %s", codec_type ? codec_type : "unknown",

             codec_name);

    buf[0] ^= 'a' ^ 'A'; /* first letter in uppercase */



    if (enc->codec && strcmp(enc->codec->name, codec_name))

        snprintf(buf + strlen(buf), buf_size - strlen(buf), " (%s)", enc->codec->name);



    if (profile)

        snprintf(buf + strlen(buf), buf_size - strlen(buf), " (%s)", profile);

    if (   enc->codec_type == AVMEDIA_TYPE_VIDEO

        && av_log_get_level() >= AV_LOG_VERBOSE

        && enc->refs)

        snprintf(buf + strlen(buf), buf_size - strlen(buf),

                 ", %d reference frame%s",

                 enc->refs, enc->refs > 1 ? "s" : "");



    if (enc->codec_tag) {

        char tag_buf[32];

        av_get_codec_tag_string(tag_buf, sizeof(tag_buf), enc->codec_tag);

        snprintf(buf + strlen(buf), buf_size - strlen(buf),

                 " (%s / 0x%04X)", tag_buf, enc->codec_tag);

    }



    switch (enc->codec_type) {

    case AVMEDIA_TYPE_VIDEO:

        {

            char detail[256] = "(";



            av_strlcat(buf, separator, buf_size);



            snprintf(buf + strlen(buf), buf_size - strlen(buf),

                 "%s", enc->pix_fmt == AV_PIX_FMT_NONE ? "none" :

                     av_get_pix_fmt_name(enc->pix_fmt));

            if (enc->bits_per_raw_sample && enc->pix_fmt != AV_PIX_FMT_NONE &&

                enc->bits_per_raw_sample < av_pix_fmt_desc_get(enc->pix_fmt)->comp[0].depth)

                av_strlcatf(detail, sizeof(detail), "%d bpc, ", enc->bits_per_raw_sample);

            if (enc->color_range != AVCOL_RANGE_UNSPECIFIED)

                av_strlcatf(detail, sizeof(detail), "%s, ",

                            av_color_range_name(enc->color_range));



            if (enc->colorspace != AVCOL_SPC_UNSPECIFIED ||

                enc->color_primaries != AVCOL_PRI_UNSPECIFIED ||

                enc->color_trc != AVCOL_TRC_UNSPECIFIED) {

                if (enc->colorspace != (int)enc->color_primaries ||

                    enc->colorspace != (int)enc->color_trc) {

                    new_line = 1;

                    av_strlcatf(detail, sizeof(detail), "%s/%s/%s, ",

                                av_color_space_name(enc->colorspace),

                                av_color_primaries_name(enc->color_primaries),

                                av_color_transfer_name(enc->color_trc));

                } else

                    av_strlcatf(detail, sizeof(detail), "%s, ",

                                av_get_colorspace_name(enc->colorspace));

            }



            if (av_log_get_level() >= AV_LOG_DEBUG &&

                enc->chroma_sample_location != AVCHROMA_LOC_UNSPECIFIED)

                av_strlcatf(detail, sizeof(detail), "%s, ",

                            av_chroma_location_name(enc->chroma_sample_location));



            if (strlen(detail) > 1) {

                detail[strlen(detail) - 2] = 0;

                av_strlcatf(buf, buf_size, "%s)", detail);

            }

        }



        if (enc->width) {

            av_strlcat(buf, new_line ? separator : ", ", buf_size);



            snprintf(buf + strlen(buf), buf_size - strlen(buf),

                     "%dx%d",

                     enc->width, enc->height);



            if (av_log_get_level() >= AV_LOG_VERBOSE &&

                (enc->width != enc->coded_width ||

                 enc->height != enc->coded_height))

                snprintf(buf + strlen(buf), buf_size - strlen(buf),

                         " (%dx%d)", enc->coded_width, enc->coded_height);



            if (enc->sample_aspect_ratio.num) {

                av_reduce(&display_aspect_ratio.num, &display_aspect_ratio.den,

                          enc->width * enc->sample_aspect_ratio.num,

                          enc->height * enc->sample_aspect_ratio.den,

                          1024 * 1024);

                snprintf(buf + strlen(buf), buf_size - strlen(buf),

                         " [SAR %d:%d DAR %d:%d]",

                         enc->sample_aspect_ratio.num, enc->sample_aspect_ratio.den,

                         display_aspect_ratio.num, display_aspect_ratio.den);

            }

            if (av_log_get_level() >= AV_LOG_DEBUG) {

                int g = av_gcd(enc->time_base.num, enc->time_base.den);

                snprintf(buf + strlen(buf), buf_size - strlen(buf),

                         ", %d/%d",

                         enc->time_base.num / g, enc->time_base.den / g);

            }

        }

        if (encode) {

            snprintf(buf + strlen(buf), buf_size - strlen(buf),

                     ", q=%d-%d", enc->qmin, enc->qmax);

        } else {

            if (enc->properties & FF_CODEC_PROPERTY_CLOSED_CAPTIONS)

                snprintf(buf + strlen(buf), buf_size - strlen(buf),

                         ", Closed Captions");

            if (enc->properties & FF_CODEC_PROPERTY_LOSSLESS)

                snprintf(buf + strlen(buf), buf_size - strlen(buf),

                         ", lossless");

        }

        break;

    case AVMEDIA_TYPE_AUDIO:

        av_strlcat(buf, separator, buf_size);



        if (enc->sample_rate) {

            snprintf(buf + strlen(buf), buf_size - strlen(buf),

                     "%d Hz, ", enc->sample_rate);

        }

        av_get_channel_layout_string(buf + strlen(buf), buf_size - strlen(buf), enc->channels, enc->channel_layout);

        if (enc->sample_fmt != AV_SAMPLE_FMT_NONE) {

            snprintf(buf + strlen(buf), buf_size - strlen(buf),

                     ", %s", av_get_sample_fmt_name(enc->sample_fmt));

        }

        if (   enc->bits_per_raw_sample > 0

            && enc->bits_per_raw_sample != av_get_bytes_per_sample(enc->sample_fmt) * 8)

            snprintf(buf + strlen(buf), buf_size - strlen(buf),

                     " (%d bit)", enc->bits_per_raw_sample);

        break;

    case AVMEDIA_TYPE_DATA:

        if (av_log_get_level() >= AV_LOG_DEBUG) {

            int g = av_gcd(enc->time_base.num, enc->time_base.den);

            if (g)

                snprintf(buf + strlen(buf), buf_size - strlen(buf),

                         ", %d/%d",

                         enc->time_base.num / g, enc->time_base.den / g);

        }

        break;

    case AVMEDIA_TYPE_SUBTITLE:

        if (enc->width)

            snprintf(buf + strlen(buf), buf_size - strlen(buf),

                     ", %dx%d", enc->width, enc->height);

        break;

    default:

        return;

    }

    if (encode) {

        if (enc->flags & AV_CODEC_FLAG_PASS1)

            snprintf(buf + strlen(buf), buf_size - strlen(buf),

                     ", pass 1");

        if (enc->flags & AV_CODEC_FLAG_PASS2)

            snprintf(buf + strlen(buf), buf_size - strlen(buf),

                     ", pass 2");

    }

    bitrate = get_bit_rate(enc);

    if (bitrate != 0) {

        snprintf(buf + strlen(buf), buf_size - strlen(buf),

                 ", %"PRId64" kb/s", bitrate / 1000);

    } else if (enc->rc_max_rate > 0) {

        snprintf(buf + strlen(buf), buf_size - strlen(buf),

                 ", max. %"PRId64" kb/s", (int64_t)enc->rc_max_rate / 1000);

    }

}

static int decode_slice_header(H264Context *h, H264Context *h0)

{

    unsigned int first_mb_in_slice;

    unsigned int pps_id;

    int ret;

    unsigned int slice_type, tmp, i, j;

    int default_ref_list_done = 0;

    int last_pic_structure, last_pic_droppable;

    int needs_reinit = 0;

    int field_pic_flag, bottom_field_flag;



    h->me.qpel_put = h->h264qpel.put_h264_qpel_pixels_tab;

    h->me.qpel_avg = h->h264qpel.avg_h264_qpel_pixels_tab;



    first_mb_in_slice = get_ue_golomb(&h->gb);



    if (first_mb_in_slice == 0) { // FIXME better field boundary detection

        if (h0->current_slice && h->cur_pic_ptr && FIELD_PICTURE(h)) {

            field_end(h, 1);

        }



        h0->current_slice = 0;

        if (!h0->first_field) {

            if (h->cur_pic_ptr && !h->droppable) {

                ff_thread_report_progress(&h->cur_pic_ptr->tf, INT_MAX,

                                          h->picture_structure == PICT_BOTTOM_FIELD);

            }

            h->cur_pic_ptr = NULL;

        }

    }



    slice_type = get_ue_golomb_31(&h->gb);

    if (slice_type > 9) {

        av_log(h->avctx, AV_LOG_ERROR,

               "slice type %d too large at %d %d\n",

               slice_type, h->mb_x, h->mb_y);

        return AVERROR_INVALIDDATA;

    }

    if (slice_type > 4) {

        slice_type -= 5;

        h->slice_type_fixed = 1;

    } else

        h->slice_type_fixed = 0;



    slice_type = golomb_to_pict_type[slice_type];

    if (slice_type == AV_PICTURE_TYPE_I ||

        (h0->current_slice != 0 && slice_type == h0->last_slice_type)) {

        default_ref_list_done = 1;

    }

    h->slice_type     = slice_type;

    h->slice_type_nos = slice_type & 3;



    if (h->nal_unit_type  == NAL_IDR_SLICE &&

        h->slice_type_nos != AV_PICTURE_TYPE_I) {

        av_log(h->avctx, AV_LOG_ERROR, "A non-intra slice in an IDR NAL unit.\n");

        return AVERROR_INVALIDDATA;

    }



    // to make a few old functions happy, it's wrong though

    h->pict_type = h->slice_type;



    pps_id = get_ue_golomb(&h->gb);

    if (pps_id >= MAX_PPS_COUNT) {

        av_log(h->avctx, AV_LOG_ERROR, "pps_id %u out of range\n", pps_id);

        return AVERROR_INVALIDDATA;

    }

    if (!h0->pps_buffers[pps_id]) {

        av_log(h->avctx, AV_LOG_ERROR,

               "non-existing PPS %u referenced\n",

               pps_id);

        return AVERROR_INVALIDDATA;

    }

    h->pps = *h0->pps_buffers[pps_id];



    if (!h0->sps_buffers[h->pps.sps_id]) {

        av_log(h->avctx, AV_LOG_ERROR,

               "non-existing SPS %u referenced\n",

               h->pps.sps_id);

        return AVERROR_INVALIDDATA;

    }



    if (h->pps.sps_id != h->sps.sps_id ||

        h0->sps_buffers[h->pps.sps_id]->new) {

        h0->sps_buffers[h->pps.sps_id]->new = 0;



        h->sps = *h0->sps_buffers[h->pps.sps_id];



        if (h->bit_depth_luma    != h->sps.bit_depth_luma ||

            h->chroma_format_idc != h->sps.chroma_format_idc) {

            h->bit_depth_luma    = h->sps.bit_depth_luma;

            h->chroma_format_idc = h->sps.chroma_format_idc;

            needs_reinit         = 1;

        }

        if ((ret = h264_set_parameter_from_sps(h)) < 0)

            return ret;

    }



    h->avctx->profile = ff_h264_get_profile(&h->sps);

    h->avctx->level   = h->sps.level_idc;

    h->avctx->refs    = h->sps.ref_frame_count;



    if (h->mb_width  != h->sps.mb_width ||

        h->mb_height != h->sps.mb_height * (2 - h->sps.frame_mbs_only_flag))

        needs_reinit = 1;



    h->mb_width  = h->sps.mb_width;

    h->mb_height = h->sps.mb_height * (2 - h->sps.frame_mbs_only_flag);

    h->mb_num    = h->mb_width * h->mb_height;

    h->mb_stride = h->mb_width + 1;



    h->b_stride = h->mb_width * 4;



    h->chroma_y_shift = h->sps.chroma_format_idc <= 1; // 400 uses yuv420p



    h->width  = 16 * h->mb_width;

    h->height = 16 * h->mb_height;



    ret = init_dimensions(h);

    if (ret < 0)

        return ret;



    if (h->sps.video_signal_type_present_flag) {

        h->avctx->color_range = h->sps.full_range ? AVCOL_RANGE_JPEG

                                                  : AVCOL_RANGE_MPEG;

        if (h->sps.colour_description_present_flag) {

            if (h->avctx->colorspace != h->sps.colorspace)

                needs_reinit = 1;

            h->avctx->color_primaries = h->sps.color_primaries;

            h->avctx->color_trc       = h->sps.color_trc;

            h->avctx->colorspace      = h->sps.colorspace;

        }

    }



    if (h->context_initialized &&

        (h->width  != h->avctx->coded_width   ||

         h->height != h->avctx->coded_height  ||

         needs_reinit)) {

        if (h != h0) {

            av_log(h->avctx, AV_LOG_ERROR,

                   "changing width %d -> %d / height %d -> %d on "

                   "slice %d\n",

                   h->width, h->avctx->coded_width,

                   h->height, h->avctx->coded_height,

                   h0->current_slice + 1);

            return AVERROR_INVALIDDATA;

        }



        flush_change(h);



        if ((ret = get_pixel_format(h)) < 0)

            return ret;

        h->avctx->pix_fmt = ret;



        av_log(h->avctx, AV_LOG_INFO, "Reinit context to %dx%d, "

               "pix_fmt: %d\n", h->width, h->height, h->avctx->pix_fmt);



        if ((ret = h264_slice_header_init(h, 1)) < 0) {

            av_log(h->avctx, AV_LOG_ERROR,

                   "h264_slice_header_init() failed\n");

            return ret;

        }

    }

    if (!h->context_initialized) {

        if (h != h0) {

            av_log(h->avctx, AV_LOG_ERROR,

                   "Cannot (re-)initialize context during parallel decoding.\n");

            return AVERROR_PATCHWELCOME;

        }



        if ((ret = get_pixel_format(h)) < 0)

            return ret;

        h->avctx->pix_fmt = ret;



        if ((ret = h264_slice_header_init(h, 0)) < 0) {

            av_log(h->avctx, AV_LOG_ERROR,

                   "h264_slice_header_init() failed\n");

            return ret;

        }

    }



    if (h == h0 && h->dequant_coeff_pps != pps_id) {

        h->dequant_coeff_pps = pps_id;

        init_dequant_tables(h);

    }



    h->frame_num = get_bits(&h->gb, h->sps.log2_max_frame_num);



    h->mb_mbaff        = 0;

    h->mb_aff_frame    = 0;

    last_pic_structure = h0->picture_structure;

    last_pic_droppable = h0->droppable;

    h->droppable       = h->nal_ref_idc == 0;

    if (h->sps.frame_mbs_only_flag) {

        h->picture_structure = PICT_FRAME;

    } else {

        field_pic_flag = get_bits1(&h->gb);

        if (field_pic_flag) {

            bottom_field_flag = get_bits1(&h->gb);

            h->picture_structure = PICT_TOP_FIELD + bottom_field_flag;

        } else {

            h->picture_structure = PICT_FRAME;

            h->mb_aff_frame      = h->sps.mb_aff;

        }

    }

    h->mb_field_decoding_flag = h->picture_structure != PICT_FRAME;



    if (h0->current_slice != 0) {

        if (last_pic_structure != h->picture_structure ||

            last_pic_droppable != h->droppable) {

            av_log(h->avctx, AV_LOG_ERROR,

                   "Changing field mode (%d -> %d) between slices is not allowed\n",

                   last_pic_structure, h->picture_structure);

            h->picture_structure = last_pic_structure;

            h->droppable         = last_pic_droppable;

            return AVERROR_INVALIDDATA;

        } else if (!h0->cur_pic_ptr) {

            av_log(h->avctx, AV_LOG_ERROR,

                   "unset cur_pic_ptr on slice %d\n",

                   h0->current_slice + 1);

            return AVERROR_INVALIDDATA;

        }

    } else {

        /* Shorten frame num gaps so we don't have to allocate reference

         * frames just to throw them away */

        if (h->frame_num != h->prev_frame_num) {

            int unwrap_prev_frame_num = h->prev_frame_num;

            int max_frame_num         = 1 << h->sps.log2_max_frame_num;



            if (unwrap_prev_frame_num > h->frame_num)

                unwrap_prev_frame_num -= max_frame_num;



            if ((h->frame_num - unwrap_prev_frame_num) > h->sps.ref_frame_count) {

                unwrap_prev_frame_num = (h->frame_num - h->sps.ref_frame_count) - 1;

                if (unwrap_prev_frame_num < 0)

                    unwrap_prev_frame_num += max_frame_num;



                h->prev_frame_num = unwrap_prev_frame_num;

            }

        }



        /* See if we have a decoded first field looking for a pair...

         * Here, we're using that to see if we should mark previously

         * decode frames as "finished".

         * We have to do that before the "dummy" in-between frame allocation,

         * since that can modify s->current_picture_ptr. */

        if (h0->first_field) {

            assert(h0->cur_pic_ptr);

            assert(h0->cur_pic_ptr->f.buf[0]);

            assert(h0->cur_pic_ptr->reference != DELAYED_PIC_REF);



            /* figure out if we have a complementary field pair */

            if (!FIELD_PICTURE(h) || h->picture_structure == last_pic_structure) {

                /* Previous field is unmatched. Don't display it, but let it

                 * remain for reference if marked as such. */

                if (!last_pic_droppable && last_pic_structure != PICT_FRAME) {

                    ff_thread_report_progress(&h0->cur_pic_ptr->tf, INT_MAX,

                                              last_pic_structure == PICT_TOP_FIELD);

                }

            } else {

                if (h0->cur_pic_ptr->frame_num != h->frame_num) {

                    /* This and previous field were reference, but had

                     * different frame_nums. Consider this field first in

                     * pair. Throw away previous field except for reference

                     * purposes. */

                    if (!last_pic_droppable && last_pic_structure != PICT_FRAME) {

                        ff_thread_report_progress(&h0->cur_pic_ptr->tf, INT_MAX,

                                                  last_pic_structure == PICT_TOP_FIELD);

                    }

                } else {

                    /* Second field in complementary pair */

                    if (!((last_pic_structure   == PICT_TOP_FIELD &&

                           h->picture_structure == PICT_BOTTOM_FIELD) ||

                          (last_pic_structure   == PICT_BOTTOM_FIELD &&

                           h->picture_structure == PICT_TOP_FIELD))) {

                        av_log(h->avctx, AV_LOG_ERROR,

                               "Invalid field mode combination %d/%d\n",

                               last_pic_structure, h->picture_structure);

                        h->picture_structure = last_pic_structure;

                        h->droppable         = last_pic_droppable;

                        return AVERROR_INVALIDDATA;

                    } else if (last_pic_droppable != h->droppable) {

                        avpriv_request_sample(h->avctx,

                                              "Found reference and non-reference fields in the same frame, which");

                        h->picture_structure = last_pic_structure;

                        h->droppable         = last_pic_droppable;

                        return AVERROR_PATCHWELCOME;

                    }

                }

            }

        }



        while (h->frame_num != h->prev_frame_num &&

               h->frame_num != (h->prev_frame_num + 1) % (1 << h->sps.log2_max_frame_num)) {

            Picture *prev = h->short_ref_count ? h->short_ref[0] : NULL;

            av_log(h->avctx, AV_LOG_DEBUG, "Frame num gap %d %d\n",

                   h->frame_num, h->prev_frame_num);

            ret = h264_frame_start(h);

            if (ret < 0) {

                h0->first_field = 0;

                return ret;

            }



            h->prev_frame_num++;

            h->prev_frame_num        %= 1 << h->sps.log2_max_frame_num;

            h->cur_pic_ptr->frame_num = h->prev_frame_num;

            ff_thread_report_progress(&h->cur_pic_ptr->tf, INT_MAX, 0);

            ff_thread_report_progress(&h->cur_pic_ptr->tf, INT_MAX, 1);

            ret = ff_generate_sliding_window_mmcos(h, 1);

            if (ret < 0 && (h->avctx->err_recognition & AV_EF_EXPLODE))

                return ret;

            ret = ff_h264_execute_ref_pic_marking(h, h->mmco, h->mmco_index);

            if (ret < 0 && (h->avctx->err_recognition & AV_EF_EXPLODE))

                return ret;

            /* Error concealment: If a ref is missing, copy the previous ref

             * in its place.

             * FIXME: Avoiding a memcpy would be nice, but ref handling makes

             * many assumptions about there being no actual duplicates.

             * FIXME: This does not copy padding for out-of-frame motion

             * vectors.  Given we are concealing a lost frame, this probably

             * is not noticeable by comparison, but it should be fixed. */

            if (h->short_ref_count) {

                if (prev) {

                    av_image_copy(h->short_ref[0]->f.data,

                                  h->short_ref[0]->f.linesize,

                                  (const uint8_t **)prev->f.data,

                                  prev->f.linesize,

                                  h->avctx->pix_fmt,

                                  h->mb_width  * 16,

                                  h->mb_height * 16);

                    h->short_ref[0]->poc = prev->poc + 2;

                }

                h->short_ref[0]->frame_num = h->prev_frame_num;

            }

        }



        /* See if we have a decoded first field looking for a pair...

         * We're using that to see whether to continue decoding in that

         * frame, or to allocate a new one. */

        if (h0->first_field) {

            assert(h0->cur_pic_ptr);

            assert(h0->cur_pic_ptr->f.buf[0]);

            assert(h0->cur_pic_ptr->reference != DELAYED_PIC_REF);



            /* figure out if we have a complementary field pair */

            if (!FIELD_PICTURE(h) || h->picture_structure == last_pic_structure) {

                /* Previous field is unmatched. Don't display it, but let it

                 * remain for reference if marked as such. */

                h0->cur_pic_ptr = NULL;

                h0->first_field = FIELD_PICTURE(h);

            } else {

                if (h0->cur_pic_ptr->frame_num != h->frame_num) {

                    /* This and the previous field had different frame_nums.

                     * Consider this field first in pair. Throw away previous

                     * one except for reference purposes. */

                    h0->first_field = 1;

                    h0->cur_pic_ptr = NULL;

                } else {

                    /* Second field in complementary pair */

                    h0->first_field = 0;

                }

            }

        } else {

            /* Frame or first field in a potentially complementary pair */

            h0->first_field = FIELD_PICTURE(h);

        }



        if (!FIELD_PICTURE(h) || h0->first_field) {

            if (h264_frame_start(h) < 0) {

                h0->first_field = 0;

                return AVERROR_INVALIDDATA;

            }

        } else {

            release_unused_pictures(h, 0);

        }

    }

    if (h != h0 && (ret = clone_slice(h, h0)) < 0)

        return ret;



    h->cur_pic_ptr->frame_num = h->frame_num; // FIXME frame_num cleanup



    assert(h->mb_num == h->mb_width * h->mb_height);

    if (first_mb_in_slice << FIELD_OR_MBAFF_PICTURE(h) >= h->mb_num ||

        first_mb_in_slice >= h->mb_num) {

        av_log(h->avctx, AV_LOG_ERROR, "first_mb_in_slice overflow\n");

        return AVERROR_INVALIDDATA;

    }

    h->resync_mb_x = h->mb_x =  first_mb_in_slice % h->mb_width;

    h->resync_mb_y = h->mb_y = (first_mb_in_slice / h->mb_width) <<

                               FIELD_OR_MBAFF_PICTURE(h);

    if (h->picture_structure == PICT_BOTTOM_FIELD)

        h->resync_mb_y = h->mb_y = h->mb_y + 1;

    assert(h->mb_y < h->mb_height);



    if (h->picture_structure == PICT_FRAME) {

        h->curr_pic_num = h->frame_num;

        h->max_pic_num  = 1 << h->sps.log2_max_frame_num;

    } else {

        h->curr_pic_num = 2 * h->frame_num + 1;

        h->max_pic_num  = 1 << (h->sps.log2_max_frame_num + 1);

    }



    if (h->nal_unit_type == NAL_IDR_SLICE)

        get_ue_golomb(&h->gb); /* idr_pic_id */



    if (h->sps.poc_type == 0) {

        h->poc_lsb = get_bits(&h->gb, h->sps.log2_max_poc_lsb);



        if (h->pps.pic_order_present == 1 && h->picture_structure == PICT_FRAME)

            h->delta_poc_bottom = get_se_golomb(&h->gb);

    }



    if (h->sps.poc_type == 1 && !h->sps.delta_pic_order_always_zero_flag) {

        h->delta_poc[0] = get_se_golomb(&h->gb);



        if (h->pps.pic_order_present == 1 && h->picture_structure == PICT_FRAME)

            h->delta_poc[1] = get_se_golomb(&h->gb);

    }



    ff_init_poc(h, h->cur_pic_ptr->field_poc, &h->cur_pic_ptr->poc);



    if (h->pps.redundant_pic_cnt_present)

        h->redundant_pic_count = get_ue_golomb(&h->gb);



    ret = ff_set_ref_count(h);

    if (ret < 0)

        return ret;

    else if (ret == 1)

        default_ref_list_done = 0;



    if (!default_ref_list_done)

        ff_h264_fill_default_ref_list(h);



    if (h->slice_type_nos != AV_PICTURE_TYPE_I) {

       ret = ff_h264_decode_ref_pic_list_reordering(h);

       if (ret < 0) {

           h->ref_count[1] = h->ref_count[0] = 0;

           return ret;

       }

    }



    if ((h->pps.weighted_pred && h->slice_type_nos == AV_PICTURE_TYPE_P) ||

        (h->pps.weighted_bipred_idc == 1 &&

         h->slice_type_nos == AV_PICTURE_TYPE_B))

        ff_pred_weight_table(h);

    else if (h->pps.weighted_bipred_idc == 2 &&

             h->slice_type_nos == AV_PICTURE_TYPE_B) {

        implicit_weight_table(h, -1);

    } else {

        h->use_weight = 0;

        for (i = 0; i < 2; i++) {

            h->luma_weight_flag[i]   = 0;

            h->chroma_weight_flag[i] = 0;

        }

    }



    // If frame-mt is enabled, only update mmco tables for the first slice

    // in a field. Subsequent slices can temporarily clobber h->mmco_index

    // or h->mmco, which will cause ref list mix-ups and decoding errors

    // further down the line. This may break decoding if the first slice is

    // corrupt, thus we only do this if frame-mt is enabled.

    if (h->nal_ref_idc) {

        ret = ff_h264_decode_ref_pic_marking(h0, &h->gb,

                                             !(h->avctx->active_thread_type & FF_THREAD_FRAME) ||

                                             h0->current_slice == 0);

        if (ret < 0 && (h->avctx->err_recognition & AV_EF_EXPLODE))

            return AVERROR_INVALIDDATA;

    }



    if (FRAME_MBAFF(h)) {

        ff_h264_fill_mbaff_ref_list(h);



        if (h->pps.weighted_bipred_idc == 2 && h->slice_type_nos == AV_PICTURE_TYPE_B) {

            implicit_weight_table(h, 0);

            implicit_weight_table(h, 1);

        }

    }



    if (h->slice_type_nos == AV_PICTURE_TYPE_B && !h->direct_spatial_mv_pred)

        ff_h264_direct_dist_scale_factor(h);

    ff_h264_direct_ref_list_init(h);



    if (h->slice_type_nos != AV_PICTURE_TYPE_I && h->pps.cabac) {

        tmp = get_ue_golomb_31(&h->gb);

        if (tmp > 2) {

            av_log(h->avctx, AV_LOG_ERROR, "cabac_init_idc %u overflow\n", tmp);

            return AVERROR_INVALIDDATA;

        }

        h->cabac_init_idc = tmp;

    }



    h->last_qscale_diff = 0;

    tmp = h->pps.init_qp + get_se_golomb(&h->gb);

    if (tmp > 51 + 6 * (h->sps.bit_depth_luma - 8)) {

        av_log(h->avctx, AV_LOG_ERROR, "QP %u out of range\n", tmp);

        return AVERROR_INVALIDDATA;

    }

    h->qscale       = tmp;

    h->chroma_qp[0] = get_chroma_qp(h, 0, h->qscale);

    h->chroma_qp[1] = get_chroma_qp(h, 1, h->qscale);

    // FIXME qscale / qp ... stuff

    if (h->slice_type == AV_PICTURE_TYPE_SP)

        get_bits1(&h->gb); /* sp_for_switch_flag */

    if (h->slice_type == AV_PICTURE_TYPE_SP ||

        h->slice_type == AV_PICTURE_TYPE_SI)

        get_se_golomb(&h->gb); /* slice_qs_delta */



    h->deblocking_filter     = 1;

    h->slice_alpha_c0_offset = 52;

    h->slice_beta_offset     = 52;

    if (h->pps.deblocking_filter_parameters_present) {

        tmp = get_ue_golomb_31(&h->gb);

        if (tmp > 2) {

            av_log(h->avctx, AV_LOG_ERROR,

                   "deblocking_filter_idc %u out of range\n", tmp);

            return AVERROR_INVALIDDATA;

        }

        h->deblocking_filter = tmp;

        if (h->deblocking_filter < 2)

            h->deblocking_filter ^= 1;  // 1<->0



        if (h->deblocking_filter) {

            h->slice_alpha_c0_offset += get_se_golomb(&h->gb) << 1;

            h->slice_beta_offset     += get_se_golomb(&h->gb) << 1;

            if (h->slice_alpha_c0_offset > 104U ||

                h->slice_beta_offset     > 104U) {

                av_log(h->avctx, AV_LOG_ERROR,

                       "deblocking filter parameters %d %d out of range\n",

                       h->slice_alpha_c0_offset, h->slice_beta_offset);

                return AVERROR_INVALIDDATA;

            }

        }

    }



    if (h->avctx->skip_loop_filter >= AVDISCARD_ALL ||

        (h->avctx->skip_loop_filter >= AVDISCARD_NONKEY &&

         h->slice_type_nos != AV_PICTURE_TYPE_I) ||

        (h->avctx->skip_loop_filter >= AVDISCARD_BIDIR  &&

         h->slice_type_nos == AV_PICTURE_TYPE_B) ||

        (h->avctx->skip_loop_filter >= AVDISCARD_NONREF &&

         h->nal_ref_idc == 0))

        h->deblocking_filter = 0;



    if (h->deblocking_filter == 1 && h0->max_contexts > 1) {

        if (h->avctx->flags2 & CODEC_FLAG2_FAST) {

            /* Cheat slightly for speed:

             * Do not bother to deblock across slices. */

            h->deblocking_filter = 2;

        } else {

            h0->max_contexts = 1;

            if (!h0->single_decode_warning) {

                av_log(h->avctx, AV_LOG_INFO,

                       "Cannot parallelize deblocking type 1, decoding such frames in sequential order\n");

                h0->single_decode_warning = 1;

            }

            if (h != h0) {

                av_log(h->avctx, AV_LOG_ERROR,

                       "Deblocking switched inside frame.\n");

                return 1;

            }

        }

    }

    h->qp_thresh = 15 + 52 -

                   FFMIN(h->slice_alpha_c0_offset, h->slice_beta_offset) -

                   FFMAX3(0,

                          h->pps.chroma_qp_index_offset[0],

                          h->pps.chroma_qp_index_offset[1]) +

                   6 * (h->sps.bit_depth_luma - 8);



    h0->last_slice_type = slice_type;

    h->slice_num        = ++h0->current_slice;

    if (h->slice_num >= MAX_SLICES) {

        av_log(h->avctx, AV_LOG_ERROR,

               "Too many slices, increase MAX_SLICES and recompile\n");

    }



    for (j = 0; j < 2; j++) {

        int id_list[16];

        int *ref2frm = h->ref2frm[h->slice_num & (MAX_SLICES - 1)][j];

        for (i = 0; i < 16; i++) {

            id_list[i] = 60;

            if (j < h->list_count && i < h->ref_count[j] &&

                h->ref_list[j][i].f.buf[0]) {

                int k;

                AVBuffer *buf = h->ref_list[j][i].f.buf[0]->buffer;

                for (k = 0; k < h->short_ref_count; k++)

                    if (h->short_ref[k]->f.buf[0]->buffer == buf) {

                        id_list[i] = k;

                        break;

                    }

                for (k = 0; k < h->long_ref_count; k++)

                    if (h->long_ref[k] && h->long_ref[k]->f.buf[0]->buffer == buf) {

                        id_list[i] = h->short_ref_count + k;

                        break;

                    }

            }

        }



        ref2frm[0] =

        ref2frm[1] = -1;

        for (i = 0; i < 16; i++)

            ref2frm[i + 2] = 4 * id_list[i] + (h->ref_list[j][i].reference & 3);

        ref2frm[18 + 0] =

        ref2frm[18 + 1] = -1;

        for (i = 16; i < 48; i++)

            ref2frm[i + 4] = 4 * id_list[(i - 16) >> 1] +

                             (h->ref_list[j][i].reference & 3);

    }



    if (h->avctx->debug & FF_DEBUG_PICT_INFO) {

        av_log(h->avctx, AV_LOG_DEBUG,

               "slice:%d %s mb:%d %c%s%s pps:%u frame:%d poc:%d/%d ref:%d/%d qp:%d loop:%d:%d:%d weight:%d%s %s\n",

               h->slice_num,

               (h->picture_structure == PICT_FRAME ? "F" : h->picture_structure == PICT_TOP_FIELD ? "T" : "B"),

               first_mb_in_slice,

               av_get_picture_type_char(h->slice_type),

               h->slice_type_fixed ? " fix" : "",

               h->nal_unit_type == NAL_IDR_SLICE ? " IDR" : "",

               pps_id, h->frame_num,

               h->cur_pic_ptr->field_poc[0],

               h->cur_pic_ptr->field_poc[1],

               h->ref_count[0], h->ref_count[1],

               h->qscale,

               h->deblocking_filter,

               h->slice_alpha_c0_offset / 2 - 26, h->slice_beta_offset / 2 - 26,

               h->use_weight,

               h->use_weight == 1 && h->use_weight_chroma ? "c" : "",

               h->slice_type == AV_PICTURE_TYPE_B ? (h->direct_spatial_mv_pred ? "SPAT" : "TEMP") : "");

    }



    return 0;

}

static av_cold int channelmap_init(AVFilterContext *ctx)

{

    ChannelMapContext *s = ctx->priv;

    int ret;

    char *mapping, separator = '|';

    int map_entries = 0;

    char buf[256];

    enum MappingMode mode;

    uint64_t out_ch_mask = 0;

    int i;



    mapping = s->mapping_str;



    if (!mapping) {

        mode = MAP_NONE;

    } else {

        char *dash = strchr(mapping, '-');

        if (!dash) {  // short mapping

            if (av_isdigit(*mapping))

                mode = MAP_ONE_INT;

            else

                mode = MAP_ONE_STR;

        } else if (av_isdigit(*mapping)) {

            if (av_isdigit(*(dash+1)))

                mode = MAP_PAIR_INT_INT;

            else

                mode = MAP_PAIR_INT_STR;

        } else {

            if (av_isdigit(*(dash+1)))

                mode = MAP_PAIR_STR_INT;

            else

                mode = MAP_PAIR_STR_STR;

        }

#if FF_API_OLD_FILTER_OPTS

        if (strchr(mapping, ',')) {

            av_log(ctx, AV_LOG_WARNING, "This syntax is deprecated, use "

                   "'|' to separate the mappings.\n");

            separator = ',';

        }

#endif

    }



    if (mode != MAP_NONE) {

        char *sep = mapping;

        map_entries = 1;

        while ((sep = strchr(sep, separator))) {

            if (*++sep)  // Allow trailing comma

                map_entries++;

        }

    }



    if (map_entries > MAX_CH) {

        av_log(ctx, AV_LOG_ERROR, "Too many channels mapped: '%d'.\n", map_entries);

        ret = AVERROR(EINVAL);

        goto fail;

    }



    for (i = 0; i < map_entries; i++) {

        int in_ch_idx = -1, out_ch_idx = -1;

        uint64_t in_ch = 0, out_ch = 0;

        static const char err[] = "Failed to parse channel map\n";

        switch (mode) {

        case MAP_ONE_INT:

            if (get_channel_idx(&mapping, &in_ch_idx, separator, MAX_CH) < 0) {

                ret = AVERROR(EINVAL);

                av_log(ctx, AV_LOG_ERROR, err);

                goto fail;

            }

            s->map[i].in_channel_idx  = in_ch_idx;

            s->map[i].out_channel_idx = i;

            break;

        case MAP_ONE_STR:

            if (!get_channel(&mapping, &in_ch, separator)) {

                av_log(ctx, AV_LOG_ERROR, err);

                ret = AVERROR(EINVAL);

                goto fail;

            }

            s->map[i].in_channel      = in_ch;

            s->map[i].out_channel_idx = i;

            break;

        case MAP_PAIR_INT_INT:

            if (get_channel_idx(&mapping, &in_ch_idx, '-', MAX_CH) < 0 ||

                get_channel_idx(&mapping, &out_ch_idx, separator, MAX_CH) < 0) {

                av_log(ctx, AV_LOG_ERROR, err);

                ret = AVERROR(EINVAL);

                goto fail;

            }

            s->map[i].in_channel_idx  = in_ch_idx;

            s->map[i].out_channel_idx = out_ch_idx;

            break;

        case MAP_PAIR_INT_STR:

            if (get_channel_idx(&mapping, &in_ch_idx, '-', MAX_CH) < 0 ||

                get_channel(&mapping, &out_ch, separator) < 0 ||

                out_ch & out_ch_mask) {

                av_log(ctx, AV_LOG_ERROR, err);

                ret = AVERROR(EINVAL);

                goto fail;

            }

            s->map[i].in_channel_idx  = in_ch_idx;

            s->map[i].out_channel     = out_ch;

            out_ch_mask |= out_ch;

            break;

        case MAP_PAIR_STR_INT:

            if (get_channel(&mapping, &in_ch, '-') < 0 ||

                get_channel_idx(&mapping, &out_ch_idx, separator, MAX_CH) < 0) {

                av_log(ctx, AV_LOG_ERROR, err);

                ret = AVERROR(EINVAL);

                goto fail;

            }

            s->map[i].in_channel      = in_ch;

            s->map[i].out_channel_idx = out_ch_idx;

            break;

        case MAP_PAIR_STR_STR:

            if (get_channel(&mapping, &in_ch, '-') < 0 ||

                get_channel(&mapping, &out_ch, separator) < 0 ||

                out_ch & out_ch_mask) {

                av_log(ctx, AV_LOG_ERROR, err);

                ret = AVERROR(EINVAL);

                goto fail;

            }

            s->map[i].in_channel = in_ch;

            s->map[i].out_channel = out_ch;

            out_ch_mask |= out_ch;

            break;

        }

    }

    s->mode          = mode;

    s->nch           = map_entries;

    s->output_layout = out_ch_mask ? out_ch_mask :

                       av_get_default_channel_layout(map_entries);



    if (s->channel_layout_str) {

        uint64_t fmt;

        if ((fmt = av_get_channel_layout(s->channel_layout_str)) == 0) {

            av_log(ctx, AV_LOG_ERROR, "Error parsing channel layout: '%s'.\n",

                   s->channel_layout_str);

            ret = AVERROR(EINVAL);

            goto fail;

        }

        if (mode == MAP_NONE) {

            int i;

            s->nch = av_get_channel_layout_nb_channels(fmt);

            for (i = 0; i < s->nch; i++) {

                s->map[i].in_channel_idx  = i;

                s->map[i].out_channel_idx = i;

            }

        } else if (out_ch_mask && out_ch_mask != fmt) {

            av_get_channel_layout_string(buf, sizeof(buf), 0, out_ch_mask);

            av_log(ctx, AV_LOG_ERROR,

                   "Output channel layout '%s' does not match the list of channel mapped: '%s'.\n",

                   s->channel_layout_str, buf);

            ret = AVERROR(EINVAL);

            goto fail;

        } else if (s->nch != av_get_channel_layout_nb_channels(fmt)) {

            av_log(ctx, AV_LOG_ERROR,

                   "Output channel layout %s does not match the number of channels mapped %d.\n",

                   s->channel_layout_str, s->nch);

            ret = AVERROR(EINVAL);

            goto fail;

        }

        s->output_layout = fmt;

    }

    ff_add_channel_layout(&s->channel_layouts, s->output_layout);



    if (mode == MAP_PAIR_INT_STR || mode == MAP_PAIR_STR_STR) {

        for (i = 0; i < s->nch; i++) {

            s->map[i].out_channel_idx = av_get_channel_layout_channel_index(

                s->output_layout, s->map[i].out_channel);

        }

    }



fail:

    av_opt_free(s);

    return ret;

}

static void pred_weight_table(HEVCContext *s, GetBitContext *gb)

{

    int i = 0;

    int j = 0;

    uint8_t luma_weight_l0_flag[16];

    uint8_t chroma_weight_l0_flag[16];

    uint8_t luma_weight_l1_flag[16];

    uint8_t chroma_weight_l1_flag[16];

    int luma_log2_weight_denom;



    luma_log2_weight_denom = get_ue_golomb_long(gb);

    if (luma_log2_weight_denom < 0 || luma_log2_weight_denom > 7)

        av_log(s->avctx, AV_LOG_ERROR, "luma_log2_weight_denom %d is invalid\n", luma_log2_weight_denom);

    s->sh.luma_log2_weight_denom = av_clip_uintp2(luma_log2_weight_denom, 3);

    if (s->ps.sps->chroma_format_idc != 0) {

        int delta = get_se_golomb(gb);

        s->sh.chroma_log2_weight_denom = av_clip_uintp2(s->sh.luma_log2_weight_denom + delta, 3);

    }



    for (i = 0; i < s->sh.nb_refs[L0]; i++) {

        luma_weight_l0_flag[i] = get_bits1(gb);

        if (!luma_weight_l0_flag[i]) {

            s->sh.luma_weight_l0[i] = 1 << s->sh.luma_log2_weight_denom;

            s->sh.luma_offset_l0[i] = 0;

        }

    }

    if (s->ps.sps->chroma_format_idc != 0) {

        for (i = 0; i < s->sh.nb_refs[L0]; i++)

            chroma_weight_l0_flag[i] = get_bits1(gb);

    } else {

        for (i = 0; i < s->sh.nb_refs[L0]; i++)

            chroma_weight_l0_flag[i] = 0;

    }

    for (i = 0; i < s->sh.nb_refs[L0]; i++) {

        if (luma_weight_l0_flag[i]) {

            int delta_luma_weight_l0 = get_se_golomb(gb);

            s->sh.luma_weight_l0[i] = (1 << s->sh.luma_log2_weight_denom) + delta_luma_weight_l0;

            s->sh.luma_offset_l0[i] = get_se_golomb(gb);

        }

        if (chroma_weight_l0_flag[i]) {

            for (j = 0; j < 2; j++) {

                int delta_chroma_weight_l0 = get_se_golomb(gb);

                int delta_chroma_offset_l0 = get_se_golomb(gb);

                s->sh.chroma_weight_l0[i][j] = (1 << s->sh.chroma_log2_weight_denom) + delta_chroma_weight_l0;

                s->sh.chroma_offset_l0[i][j] = av_clip((delta_chroma_offset_l0 - ((128 * s->sh.chroma_weight_l0[i][j])

                                                                                    >> s->sh.chroma_log2_weight_denom) + 128), -128, 127);

            }

        } else {

            s->sh.chroma_weight_l0[i][0] = 1 << s->sh.chroma_log2_weight_denom;

            s->sh.chroma_offset_l0[i][0] = 0;

            s->sh.chroma_weight_l0[i][1] = 1 << s->sh.chroma_log2_weight_denom;

            s->sh.chroma_offset_l0[i][1] = 0;

        }

    }

    if (s->sh.slice_type == HEVC_SLICE_B) {

        for (i = 0; i < s->sh.nb_refs[L1]; i++) {

            luma_weight_l1_flag[i] = get_bits1(gb);

            if (!luma_weight_l1_flag[i]) {

                s->sh.luma_weight_l1[i] = 1 << s->sh.luma_log2_weight_denom;

                s->sh.luma_offset_l1[i] = 0;

            }

        }

        if (s->ps.sps->chroma_format_idc != 0) {

            for (i = 0; i < s->sh.nb_refs[L1]; i++)

                chroma_weight_l1_flag[i] = get_bits1(gb);

        } else {

            for (i = 0; i < s->sh.nb_refs[L1]; i++)

                chroma_weight_l1_flag[i] = 0;

        }

        for (i = 0; i < s->sh.nb_refs[L1]; i++) {

            if (luma_weight_l1_flag[i]) {

                int delta_luma_weight_l1 = get_se_golomb(gb);

                s->sh.luma_weight_l1[i] = (1 << s->sh.luma_log2_weight_denom) + delta_luma_weight_l1;

                s->sh.luma_offset_l1[i] = get_se_golomb(gb);

            }

            if (chroma_weight_l1_flag[i]) {

                for (j = 0; j < 2; j++) {

                    int delta_chroma_weight_l1 = get_se_golomb(gb);

                    int delta_chroma_offset_l1 = get_se_golomb(gb);

                    s->sh.chroma_weight_l1[i][j] = (1 << s->sh.chroma_log2_weight_denom) + delta_chroma_weight_l1;

                    s->sh.chroma_offset_l1[i][j] = av_clip((delta_chroma_offset_l1 - ((128 * s->sh.chroma_weight_l1[i][j])

                                                                                        >> s->sh.chroma_log2_weight_denom) + 128), -128, 127);

                }

            } else {

                s->sh.chroma_weight_l1[i][0] = 1 << s->sh.chroma_log2_weight_denom;

                s->sh.chroma_offset_l1[i][0] = 0;

                s->sh.chroma_weight_l1[i][1] = 1 << s->sh.chroma_log2_weight_denom;

                s->sh.chroma_offset_l1[i][1] = 0;

            }

        }

    }

}

static void filter_mb_mbaff_edgev( H264Context *h, uint8_t *pix, int stride, int16_t bS[8], int qp[2] ) {

    int i;

    for( i = 0; i < 16; i++, pix += stride) {

        int index_a;

        int alpha;

        int beta;



        int qp_index;

        int bS_index = (i >> 1);

        if (!MB_FIELD) {

            bS_index &= ~1;

            bS_index |= (i & 1);

        }



        if( bS[bS_index] == 0 ) {

            continue;

        }



        qp_index = MB_FIELD ? (i >> 3) : (i & 1);

        index_a = qp[qp_index] + h->slice_alpha_c0_offset;

        alpha = (alpha_table+52)[index_a];

        beta  = (beta_table+52)[qp[qp_index] + h->slice_beta_offset];



        if( bS[bS_index] < 4 ) {

            const int tc0 = (tc0_table+52)[index_a][bS[bS_index] - 1];

            const int p0 = pix[-1];

            const int p1 = pix[-2];

            const int p2 = pix[-3];

            const int q0 = pix[0];

            const int q1 = pix[1];

            const int q2 = pix[2];



            if( FFABS( p0 - q0 ) < alpha &&

                FFABS( p1 - p0 ) < beta &&

                FFABS( q1 - q0 ) < beta ) {

                int tc = tc0;

                int i_delta;



                if( FFABS( p2 - p0 ) < beta ) {

                    pix[-2] = p1 + av_clip( ( p2 + ( ( p0 + q0 + 1 ) >> 1 ) - ( p1 << 1 ) ) >> 1, -tc0, tc0 );

                    tc++;

                }

                if( FFABS( q2 - q0 ) < beta ) {

                    pix[1] = q1 + av_clip( ( q2 + ( ( p0 + q0 + 1 ) >> 1 ) - ( q1 << 1 ) ) >> 1, -tc0, tc0 );

                    tc++;

                }



                i_delta = av_clip( (((q0 - p0 ) << 2) + (p1 - q1) + 4) >> 3, -tc, tc );

                pix[-1] = av_clip_uint8( p0 + i_delta );    /* p0' */

                pix[0]  = av_clip_uint8( q0 - i_delta );    /* q0' */

                tprintf(h->s.avctx, "filter_mb_mbaff_edgev i:%d, qp:%d, indexA:%d, alpha:%d, beta:%d, tc:%d\n# bS:%d -> [%02x, %02x, %02x, %02x, %02x, %02x] =>[%02x, %02x, %02x, %02x]\n", i, qp[qp_index], index_a, alpha, beta, tc, bS[bS_index], pix[-3], p1, p0, q0, q1, pix[2], p1, pix[-1], pix[0], q1);

            }

        }else{

            const int p0 = pix[-1];

            const int p1 = pix[-2];

            const int p2 = pix[-3];



            const int q0 = pix[0];

            const int q1 = pix[1];

            const int q2 = pix[2];



            if( FFABS( p0 - q0 ) < alpha &&

                FFABS( p1 - p0 ) < beta &&

                FFABS( q1 - q0 ) < beta ) {



                if(FFABS( p0 - q0 ) < (( alpha >> 2 ) + 2 )){

                    if( FFABS( p2 - p0 ) < beta)

                    {

                        const int p3 = pix[-4];

                        /* p0', p1', p2' */

                        pix[-1] = ( p2 + 2*p1 + 2*p0 + 2*q0 + q1 + 4 ) >> 3;

                        pix[-2] = ( p2 + p1 + p0 + q0 + 2 ) >> 2;

                        pix[-3] = ( 2*p3 + 3*p2 + p1 + p0 + q0 + 4 ) >> 3;

                    } else {

                        /* p0' */

                        pix[-1] = ( 2*p1 + p0 + q1 + 2 ) >> 2;

                    }

                    if( FFABS( q2 - q0 ) < beta)

                    {

                        const int q3 = pix[3];

                        /* q0', q1', q2' */

                        pix[0] = ( p1 + 2*p0 + 2*q0 + 2*q1 + q2 + 4 ) >> 3;

                        pix[1] = ( p0 + q0 + q1 + q2 + 2 ) >> 2;

                        pix[2] = ( 2*q3 + 3*q2 + q1 + q0 + p0 + 4 ) >> 3;

                    } else {

                        /* q0' */

                        pix[0] = ( 2*q1 + q0 + p1 + 2 ) >> 2;

                    }

                }else{

                    /* p0', q0' */

                    pix[-1] = ( 2*p1 + p0 + q1 + 2 ) >> 2;

                    pix[ 0] = ( 2*q1 + q0 + p1 + 2 ) >> 2;

                }

                tprintf(h->s.avctx, "filter_mb_mbaff_edgev i:%d, qp:%d, indexA:%d, alpha:%d, beta:%d\n# bS:4 -> [%02x, %02x, %02x, %02x, %02x, %02x] =>[%02x, %02x, %02x, %02x, %02x, %02x]\n", i, qp[qp_index], index_a, alpha, beta, p2, p1, p0, q0, q1, q2, pix[-3], pix[-2], pix[-1], pix[0], pix[1], pix[2]);

            }

        }

    }

}

static void do_audio_out(AVFormatContext *s, 

                         AVOutputStream *ost, 

                         AVInputStream *ist,

                         unsigned char *buf, int size)

{

    uint8_t *buftmp;

    static uint8_t *audio_buf = NULL;

    static uint8_t *audio_out = NULL;

    const int audio_out_size= 4*MAX_AUDIO_PACKET_SIZE;



    int size_out, frame_bytes, ret;

    AVCodecContext *enc;



    /* SC: dynamic allocation of buffers */

    if (!audio_buf)

        audio_buf = av_malloc(2*MAX_AUDIO_PACKET_SIZE);

    if (!audio_out)

        audio_out = av_malloc(audio_out_size);

    if (!audio_buf || !audio_out)

        return;               /* Should signal an error ! */





    enc = &ost->st->codec;



    if (ost->audio_resample) {

        buftmp = audio_buf;

        size_out = audio_resample(ost->resample, 

                                  (short *)buftmp, (short *)buf,

                                  size / (ist->st->codec.channels * 2));

        size_out = size_out * enc->channels * 2;

    } else {

        buftmp = buf;

        size_out = size;

    }



    /* now encode as many frames as possible */

    if (enc->frame_size > 1) {

        /* output resampled raw samples */

        fifo_write(&ost->fifo, buftmp, size_out, 

                   &ost->fifo.wptr);



        frame_bytes = enc->frame_size * 2 * enc->channels;



        while (fifo_read(&ost->fifo, audio_buf, frame_bytes, 

                     &ost->fifo.rptr) == 0) {

            AVPacket pkt;

            av_init_packet(&pkt);



            ret = avcodec_encode_audio(enc, audio_out, audio_out_size, 

                                       (short *)audio_buf);

            audio_size += ret;

            pkt.stream_index= ost->index;

            pkt.data= audio_out;

            pkt.size= ret;

            if(enc->coded_frame)

                pkt.pts= enc->coded_frame->pts;

            pkt.flags |= PKT_FLAG_KEY;

            av_write_frame(s, &pkt);

        }

    } else {

        AVPacket pkt;

        av_init_packet(&pkt);

        /* output a pcm frame */

        /* XXX: change encoding codec API to avoid this ? */

        switch(enc->codec->id) {

        case CODEC_ID_PCM_S16LE:

        case CODEC_ID_PCM_S16BE:

        case CODEC_ID_PCM_U16LE:

        case CODEC_ID_PCM_U16BE:

            break;

        default:

            size_out = size_out >> 1;

            break;

        }

        ret = avcodec_encode_audio(enc, audio_out, size_out, 

				   (short *)buftmp);

        audio_size += ret;

        pkt.stream_index= ost->index;

        pkt.data= audio_out;

        pkt.size= ret;

        if(enc->coded_frame)

            pkt.pts= enc->coded_frame->pts;

        pkt.flags |= PKT_FLAG_KEY;

        av_write_frame(s, &pkt);

    }

}

static int libopus_encode(AVCodecContext *avctx, AVPacket *avpkt,

                          const AVFrame *frame, int *got_packet_ptr)

{

    LibopusEncContext *opus = avctx->priv_data;

    const int sample_size   = avctx->channels *

                              av_get_bytes_per_sample(avctx->sample_fmt);

    uint8_t *audio;

    int ret;

    int discard_padding;



    if (frame) {

        ret = ff_af_queue_add(&opus->afq, frame);

        if (ret < 0)

            return ret;

        if (frame->nb_samples < opus->opts.packet_size) {

            audio = opus->samples;

            memcpy(audio, frame->data[0], frame->nb_samples * sample_size);

        } else

            audio = frame->data[0];

    } else {

        if (!opus->afq.remaining_samples)

            return 0;

        audio = opus->samples;

        memset(audio, 0, opus->opts.packet_size * sample_size);

    }



    /* Maximum packet size taken from opusenc in opus-tools. 60ms packets

     * consist of 3 frames in one packet. The maximum frame size is 1275

     * bytes along with the largest possible packet header of 7 bytes. */

    if ((ret = ff_alloc_packet2(avctx, avpkt, (1275 * 3 + 7) * opus->stream_count, 0)) < 0)

        return ret;



    if (avctx->sample_fmt == AV_SAMPLE_FMT_FLT)

        ret = opus_multistream_encode_float(opus->enc, (float *)audio,

                                            opus->opts.packet_size,

                                            avpkt->data, avpkt->size);

    else

        ret = opus_multistream_encode(opus->enc, (opus_int16 *)audio,

                                      opus->opts.packet_size,

                                      avpkt->data, avpkt->size);



    if (ret < 0) {

        av_log(avctx, AV_LOG_ERROR,

               "Error encoding frame: %s\n", opus_strerror(ret));

        return ff_opus_error_to_averror(ret);

    }



    av_shrink_packet(avpkt, ret);



    ff_af_queue_remove(&opus->afq, opus->opts.packet_size,

                       &avpkt->pts, &avpkt->duration);



    discard_padding = opus->opts.packet_size - avpkt->duration;

    // Check if subtraction resulted in an overflow

    if ((discard_padding < opus->opts.packet_size) != (avpkt->duration > 0)) {

        av_free_packet(avpkt);

        av_free(avpkt);

        return AVERROR(EINVAL);

    }

    if (discard_padding > 0) {

        uint8_t* side_data = av_packet_new_side_data(avpkt,

                                                     AV_PKT_DATA_SKIP_SAMPLES,

                                                     10);

        if(!side_data) {

            av_free_packet(avpkt);

            av_free(avpkt);

            return AVERROR(ENOMEM);

        }

        AV_WL32(side_data + 4, discard_padding);

    }



    *got_packet_ptr = 1;



    return 0;

}

int avio_open2(AVIOContext **s, const char *filename, int flags,

               const AVIOInterruptCB *int_cb, AVDictionary **options)

{

    AVIOInternal *internal;

    const URLProtocol **protocols;

    URLContext *h;

    int err;



    protocols = ffurl_get_protocols(NULL, NULL);

    if (!protocols)

        return AVERROR(ENOMEM);



    err = ffurl_open(&h, filename, flags, int_cb, options, protocols);

    if (err < 0) {

        av_freep(&protocols);

        return err;

    }



    err = ffio_fdopen(s, h);

    if (err < 0) {

        ffurl_close(h);

        av_freep(&protocols);

        return err;

    }



    internal = (*s)->opaque;

    internal->protocols = protocols;



    return 0;

}

static int decode_vop_header(Mpeg4DecContext *ctx, GetBitContext *gb)

{

    MpegEncContext *s = &ctx->m;

    int time_incr, time_increment;

    int64_t pts;



    s->pict_type = get_bits(gb, 2) + AV_PICTURE_TYPE_I;        /* pict type: I = 0 , P = 1 */

    if (s->pict_type == AV_PICTURE_TYPE_B && s->low_delay &&

        s->vol_control_parameters == 0 && !(s->flags & CODEC_FLAG_LOW_DELAY)) {

        av_log(s->avctx, AV_LOG_ERROR, "low_delay flag incorrectly, clearing it\n");

        s->low_delay = 0;

    }



    s->partitioned_frame = s->data_partitioning && s->pict_type != AV_PICTURE_TYPE_B;

    if (s->partitioned_frame)

        s->decode_mb = mpeg4_decode_partitioned_mb;

    else

        s->decode_mb = mpeg4_decode_mb;



    time_incr = 0;

    while (get_bits1(gb) != 0)

        time_incr++;



    check_marker(gb, "before time_increment");



    if (ctx->time_increment_bits == 0 ||

        !(show_bits(gb, ctx->time_increment_bits + 1) & 1)) {

        av_log(s->avctx, AV_LOG_ERROR,

               "hmm, seems the headers are not complete, trying to guess time_increment_bits\n");



        for (ctx->time_increment_bits = 1;

             ctx->time_increment_bits < 16;

             ctx->time_increment_bits++) {

            if (s->pict_type == AV_PICTURE_TYPE_P ||

                (s->pict_type == AV_PICTURE_TYPE_S &&

                 ctx->vol_sprite_usage == GMC_SPRITE)) {

                if ((show_bits(gb, ctx->time_increment_bits + 6) & 0x37) == 0x30)

                    break;

            } else if ((show_bits(gb, ctx->time_increment_bits + 5) & 0x1F) == 0x18)

                break;

        }



        av_log(s->avctx, AV_LOG_ERROR,

               "my guess is %d bits ;)\n", ctx->time_increment_bits);

        if (s->avctx->time_base.den && 4*s->avctx->time_base.den < 1<<ctx->time_increment_bits) {

            s->avctx->time_base.den = 1<<ctx->time_increment_bits;

        }

    }



    if (IS_3IV1)

        time_increment = get_bits1(gb);        // FIXME investigate further

    else

        time_increment = get_bits(gb, ctx->time_increment_bits);



    if (s->pict_type != AV_PICTURE_TYPE_B) {

        s->last_time_base = s->time_base;

        s->time_base     += time_incr;

        s->time = s->time_base * s->avctx->time_base.den + time_increment;

        if (s->workaround_bugs & FF_BUG_UMP4) {

            if (s->time < s->last_non_b_time) {

                /* header is not mpeg-4-compatible, broken encoder,

                 * trying to workaround */

                s->time_base++;

                s->time += s->avctx->time_base.den;

            }

        }

        s->pp_time         = s->time - s->last_non_b_time;

        s->last_non_b_time = s->time;

    } else {

        s->time    = (s->last_time_base + time_incr) * s->avctx->time_base.den + time_increment;

        s->pb_time = s->pp_time - (s->last_non_b_time - s->time);

        if (s->pp_time <= s->pb_time ||

            s->pp_time <= s->pp_time - s->pb_time ||

            s->pp_time <= 0) {

            /* messed up order, maybe after seeking? skipping current b-frame */

            return FRAME_SKIPPED;

        }

        ff_mpeg4_init_direct_mv(s);



        if (ctx->t_frame == 0)

            ctx->t_frame = s->pb_time;

        if (ctx->t_frame == 0)

            ctx->t_frame = 1;  // 1/0 protection

        s->pp_field_time = (ROUNDED_DIV(s->last_non_b_time, ctx->t_frame) -

                            ROUNDED_DIV(s->last_non_b_time - s->pp_time, ctx->t_frame)) * 2;

        s->pb_field_time = (ROUNDED_DIV(s->time, ctx->t_frame) -

                            ROUNDED_DIV(s->last_non_b_time - s->pp_time, ctx->t_frame)) * 2;

        if (!s->progressive_sequence) {

            if (s->pp_field_time <= s->pb_field_time || s->pb_field_time <= 1)

                return FRAME_SKIPPED;

        }

    }



    if (s->avctx->time_base.num)

        pts = ROUNDED_DIV(s->time, s->avctx->time_base.num);

    else

        pts = AV_NOPTS_VALUE;

    if (s->avctx->debug&FF_DEBUG_PTS)

        av_log(s->avctx, AV_LOG_DEBUG, "MPEG4 PTS: %"PRId64"\n",

               pts);



    check_marker(gb, "before vop_coded");



    /* vop coded */

    if (get_bits1(gb) != 1) {

        if (s->avctx->debug & FF_DEBUG_PICT_INFO)

            av_log(s->avctx, AV_LOG_ERROR, "vop not coded\n");

        return FRAME_SKIPPED;

    }

    if (ctx->new_pred)

        decode_new_pred(ctx, gb);



    if (ctx->shape != BIN_ONLY_SHAPE &&

                    (s->pict_type == AV_PICTURE_TYPE_P ||

                     (s->pict_type == AV_PICTURE_TYPE_S &&

                      ctx->vol_sprite_usage == GMC_SPRITE))) {

        /* rounding type for motion estimation */

        s->no_rounding = get_bits1(gb);

    } else {

        s->no_rounding = 0;

    }

    // FIXME reduced res stuff



    if (ctx->shape != RECT_SHAPE) {

        if (ctx->vol_sprite_usage != 1 || s->pict_type != AV_PICTURE_TYPE_I) {

            skip_bits(gb, 13);  /* width */

            skip_bits1(gb);     /* marker */

            skip_bits(gb, 13);  /* height */

            skip_bits1(gb);     /* marker */

            skip_bits(gb, 13);  /* hor_spat_ref */

            skip_bits1(gb);     /* marker */

            skip_bits(gb, 13);  /* ver_spat_ref */

        }

        skip_bits1(gb);         /* change_CR_disable */



        if (get_bits1(gb) != 0)

            skip_bits(gb, 8);   /* constant_alpha_value */

    }



    // FIXME complexity estimation stuff



    if (ctx->shape != BIN_ONLY_SHAPE) {

        skip_bits_long(gb, ctx->cplx_estimation_trash_i);

        if (s->pict_type != AV_PICTURE_TYPE_I)

            skip_bits_long(gb, ctx->cplx_estimation_trash_p);

        if (s->pict_type == AV_PICTURE_TYPE_B)

            skip_bits_long(gb, ctx->cplx_estimation_trash_b);



        if (get_bits_left(gb) < 3) {

            av_log(s->avctx, AV_LOG_ERROR, "Header truncated\n");

            return -1;

        }

        ctx->intra_dc_threshold = ff_mpeg4_dc_threshold[get_bits(gb, 3)];

        if (!s->progressive_sequence) {

            s->top_field_first = get_bits1(gb);

            s->alternate_scan  = get_bits1(gb);

        } else

            s->alternate_scan = 0;

    }



    if (s->alternate_scan) {

        ff_init_scantable(s->dsp.idct_permutation, &s->inter_scantable,   ff_alternate_vertical_scan);

        ff_init_scantable(s->dsp.idct_permutation, &s->intra_scantable,   ff_alternate_vertical_scan);

        ff_init_scantable(s->dsp.idct_permutation, &s->intra_h_scantable, ff_alternate_vertical_scan);

        ff_init_scantable(s->dsp.idct_permutation, &s->intra_v_scantable, ff_alternate_vertical_scan);

    } else {

        ff_init_scantable(s->dsp.idct_permutation, &s->inter_scantable,   ff_zigzag_direct);

        ff_init_scantable(s->dsp.idct_permutation, &s->intra_scantable,   ff_zigzag_direct);

        ff_init_scantable(s->dsp.idct_permutation, &s->intra_h_scantable, ff_alternate_horizontal_scan);

        ff_init_scantable(s->dsp.idct_permutation, &s->intra_v_scantable, ff_alternate_vertical_scan);

    }



    if (s->pict_type == AV_PICTURE_TYPE_S &&

        (ctx->vol_sprite_usage == STATIC_SPRITE ||

         ctx->vol_sprite_usage == GMC_SPRITE)) {

        if (mpeg4_decode_sprite_trajectory(ctx, gb) < 0)

            return AVERROR_INVALIDDATA;

        if (ctx->sprite_brightness_change)

            av_log(s->avctx, AV_LOG_ERROR,

                   "sprite_brightness_change not supported\n");

        if (ctx->vol_sprite_usage == STATIC_SPRITE)

            av_log(s->avctx, AV_LOG_ERROR, "static sprite not supported\n");

    }



    if (ctx->shape != BIN_ONLY_SHAPE) {

        s->chroma_qscale = s->qscale = get_bits(gb, s->quant_precision);

        if (s->qscale == 0) {

            av_log(s->avctx, AV_LOG_ERROR,

                   "Error, header damaged or not MPEG4 header (qscale=0)\n");

            return -1;  // makes no sense to continue, as there is nothing left from the image then

        }



        if (s->pict_type != AV_PICTURE_TYPE_I) {

            s->f_code = get_bits(gb, 3);        /* fcode_for */

            if (s->f_code == 0) {

                av_log(s->avctx, AV_LOG_ERROR,

                       "Error, header damaged or not MPEG4 header (f_code=0)\n");

                s->f_code = 1;

                return -1;  // makes no sense to continue, as there is nothing left from the image then

            }

        } else

            s->f_code = 1;



        if (s->pict_type == AV_PICTURE_TYPE_B) {

            s->b_code = get_bits(gb, 3);

            if (s->b_code == 0) {

                av_log(s->avctx, AV_LOG_ERROR,

                       "Error, header damaged or not MPEG4 header (b_code=0)\n");

                s->b_code=1;

                return -1; // makes no sense to continue, as the MV decoding will break very quickly

            }

        } else

            s->b_code = 1;



        if (s->avctx->debug & FF_DEBUG_PICT_INFO) {

            av_log(s->avctx, AV_LOG_DEBUG,

                   "qp:%d fc:%d,%d %s size:%d pro:%d alt:%d top:%d %spel part:%d resync:%d w:%d a:%d rnd:%d vot:%d%s dc:%d ce:%d/%d/%d time:%"PRId64" tincr:%d\n",

                   s->qscale, s->f_code, s->b_code,

                   s->pict_type == AV_PICTURE_TYPE_I ? "I" : (s->pict_type == AV_PICTURE_TYPE_P ? "P" : (s->pict_type == AV_PICTURE_TYPE_B ? "B" : "S")),

                   gb->size_in_bits,s->progressive_sequence, s->alternate_scan,

                   s->top_field_first, s->quarter_sample ? "q" : "h",

                   s->data_partitioning, ctx->resync_marker,

                   ctx->num_sprite_warping_points, s->sprite_warping_accuracy,

                   1 - s->no_rounding, s->vo_type,

                   s->vol_control_parameters ? " VOLC" : " ", ctx->intra_dc_threshold,

                   ctx->cplx_estimation_trash_i, ctx->cplx_estimation_trash_p,

                   ctx->cplx_estimation_trash_b,

                   s->time,

                   time_increment

                  );

        }



        if (!ctx->scalability) {

            if (ctx->shape != RECT_SHAPE && s->pict_type != AV_PICTURE_TYPE_I)

                skip_bits1(gb);  // vop shape coding type

        } else {

            if (ctx->enhancement_type) {

                int load_backward_shape = get_bits1(gb);

                if (load_backward_shape)

                    av_log(s->avctx, AV_LOG_ERROR,

                           "load backward shape isn't supported\n");

            }

            skip_bits(gb, 2);  // ref_select_code

        }

    }

    /* detect buggy encoders which don't set the low_delay flag

     * (divx4/xvid/opendivx). Note we cannot detect divx5 without b-frames

     * easily (although it's buggy too) */

    if (s->vo_type == 0 && s->vol_control_parameters == 0 &&

        ctx->divx_version == -1 && s->picture_number == 0) {

        av_log(s->avctx, AV_LOG_WARNING,

               "looks like this file was encoded with (divx4/(old)xvid/opendivx) -> forcing low_delay flag\n");

        s->low_delay = 1;

    }



    s->picture_number++;  // better than pic number==0 always ;)



    // FIXME add short header support

    s->y_dc_scale_table = ff_mpeg4_y_dc_scale_table;

    s->c_dc_scale_table = ff_mpeg4_c_dc_scale_table;



    if (s->workaround_bugs & FF_BUG_EDGE) {

        s->h_edge_pos = s->width;

        s->v_edge_pos = s->height;

    }

    return 0;

}

static int vorbis_encode_frame(AVCodecContext *avctx, AVPacket *avpkt,

                               const AVFrame *frame, int *got_packet_ptr)

{

    vorbis_enc_context *venc = avctx->priv_data;

    int i, ret, need_more;

    int samples = 0, frame_size = 1 << (venc->log2_blocksize[1] - 1);

    vorbis_enc_mode *mode;

    vorbis_enc_mapping *mapping;

    PutBitContext pb;



    if (frame) {

        if ((ret = ff_af_queue_add(&venc->afq, frame)) < 0)

            return ret;

        ff_bufqueue_add(avctx, &venc->bufqueue, av_frame_clone(frame));

    } else

        if (!venc->afq.remaining_samples)

            return 0;



    need_more = venc->bufqueue.available * avctx->frame_size < frame_size;

    need_more = frame && need_more;

    if (need_more)

        return 0;



    /* Pad the bufqueue with empty frames for encoding the last packet. */

    if (!frame) {

        if (venc->bufqueue.available * avctx->frame_size < frame_size) {

            int frames_needed = (frame_size/avctx->frame_size) - venc->bufqueue.available;



            for (int i = 0; i < frames_needed; i++) {

               AVFrame *empty = spawn_empty_frame(avctx, venc->channels);

               if (!empty)

                   return AVERROR(ENOMEM);



               ff_bufqueue_add(avctx, &venc->bufqueue, empty);

            }

        }

    }



    move_audio(venc, venc->scratch, &samples, avctx->frame_size);



    if (!apply_window_and_mdct(venc, venc->scratch, samples))

        return 0;



    if ((ret = ff_alloc_packet2(avctx, avpkt, 8192, 0)) < 0)

        return ret;



    init_put_bits(&pb, avpkt->data, avpkt->size);



    if (pb.size_in_bits - put_bits_count(&pb) < 1 + ilog(venc->nmodes - 1)) {

        av_log(avctx, AV_LOG_ERROR, "output buffer is too small\n");

        return AVERROR(EINVAL);

    }



    put_bits(&pb, 1, 0); // magic bit



    put_bits(&pb, ilog(venc->nmodes - 1), 0); // 0 bits, the mode



    mode    = &venc->modes[0];

    mapping = &venc->mappings[mode->mapping];

    if (mode->blockflag) {

        put_bits(&pb, 1, 0);

        put_bits(&pb, 1, 0);

    }



    for (i = 0; i < venc->channels; i++) {

        vorbis_enc_floor *fc = &venc->floors[mapping->floor[mapping->mux[i]]];

        uint16_t posts[MAX_FLOOR_VALUES];

        floor_fit(venc, fc, &venc->coeffs[i * samples], posts, samples);

        if (floor_encode(venc, fc, &pb, posts, &venc->floor[i * samples], samples)) {

            av_log(avctx, AV_LOG_ERROR, "output buffer is too small\n");

            return AVERROR(EINVAL);

        }

    }



    for (i = 0; i < venc->channels * samples; i++)

        venc->coeffs[i] /= venc->floor[i];



    for (i = 0; i < mapping->coupling_steps; i++) {

        float *mag = venc->coeffs + mapping->magnitude[i] * samples;

        float *ang = venc->coeffs + mapping->angle[i]     * samples;

        int j;

        for (j = 0; j < samples; j++) {

            float a = ang[j];

            ang[j] -= mag[j];

            if (mag[j] > 0)

                ang[j] = -ang[j];

            if (ang[j] < 0)

                mag[j] = a;

        }

    }



    if (residue_encode(venc, &venc->residues[mapping->residue[mapping->mux[0]]],

                       &pb, venc->coeffs, samples, venc->channels)) {

        av_log(avctx, AV_LOG_ERROR, "output buffer is too small\n");

        return AVERROR(EINVAL);

    }



    flush_put_bits(&pb);

    avpkt->size = put_bits_count(&pb) >> 3;



    ff_af_queue_remove(&venc->afq, frame_size, &avpkt->pts, &avpkt->duration);



    if (frame_size > avpkt->duration) {

        uint8_t *side = av_packet_new_side_data(avpkt, AV_PKT_DATA_SKIP_SAMPLES, 10);

        if (!side)

            return AVERROR(ENOMEM);

        AV_WL32(&side[4], frame_size - avpkt->duration);

    }



    *got_packet_ptr = 1;

    return 0;

}

static inline void RENAME(rgb24tobgr16)(const uint8_t *src, uint8_t *dst, unsigned int src_size)

{

	const uint8_t *s = src;

	const uint8_t *end;

#ifdef HAVE_MMX

	const uint8_t *mm_end;

#endif

	uint16_t *d = (uint16_t *)dst;

	end = s + src_size;

#ifdef HAVE_MMX

	__asm __volatile(PREFETCH"	%0"::"m"(*src):"memory");

	__asm __volatile(

	    "movq	%0, %%mm7\n\t"

	    "movq	%1, %%mm6\n\t"

	    ::"m"(red_16mask),"m"(green_16mask));

	mm_end = end - 15;

	while(s < mm_end)

	{

	    __asm __volatile(

		PREFETCH" 32%1\n\t"

		"movd	%1, %%mm0\n\t"

		"movd	3%1, %%mm3\n\t"

		"punpckldq 6%1, %%mm0\n\t"

		"punpckldq 9%1, %%mm3\n\t"

		"movq	%%mm0, %%mm1\n\t"

		"movq	%%mm0, %%mm2\n\t"

		"movq	%%mm3, %%mm4\n\t"

		"movq	%%mm3, %%mm5\n\t"

		"psllq	$8, %%mm0\n\t"

		"psllq	$8, %%mm3\n\t"

		"pand	%%mm7, %%mm0\n\t"

		"pand	%%mm7, %%mm3\n\t"

		"psrlq	$5, %%mm1\n\t"

		"psrlq	$5, %%mm4\n\t"

		"pand	%%mm6, %%mm1\n\t"

		"pand	%%mm6, %%mm4\n\t"

		"psrlq	$19, %%mm2\n\t"

		"psrlq	$19, %%mm5\n\t"

		"pand	%2, %%mm2\n\t"

		"pand	%2, %%mm5\n\t"

		"por	%%mm1, %%mm0\n\t"

		"por	%%mm4, %%mm3\n\t"

		"por	%%mm2, %%mm0\n\t"

		"por	%%mm5, %%mm3\n\t"

		"psllq	$16, %%mm3\n\t"

		"por	%%mm3, %%mm0\n\t"

		MOVNTQ"	%%mm0, %0\n\t"

		:"=m"(*d):"m"(*s),"m"(blue_16mask):"memory");

		d += 4;

		s += 12;

	}

	__asm __volatile(SFENCE:::"memory");

	__asm __volatile(EMMS:::"memory");

#endif

	while(s < end)

	{

		const int r= *s++;

		const int g= *s++;

		const int b= *s++;

		*d++ = (b>>3) | ((g&0xFC)<<3) | ((r&0xF8)<<8);

	}

}

static int probe_file(WriterContext *wctx, const char *filename)

{

    AVFormatContext *fmt_ctx;

    int ret, i;

    int section_id;



    do_read_frames = do_show_frames || do_count_frames;

    do_read_packets = do_show_packets || do_count_packets;



    ret = open_input_file(&fmt_ctx, filename);

    if (ret < 0)

        return ret;



    nb_streams_frames  = av_calloc(fmt_ctx->nb_streams, sizeof(*nb_streams_frames));

    nb_streams_packets = av_calloc(fmt_ctx->nb_streams, sizeof(*nb_streams_packets));

    selected_streams   = av_calloc(fmt_ctx->nb_streams, sizeof(*selected_streams));



    for (i = 0; i < fmt_ctx->nb_streams; i++) {

        if (stream_specifier) {

            ret = avformat_match_stream_specifier(fmt_ctx,

                                                  fmt_ctx->streams[i],

                                                  stream_specifier);

            if (ret < 0)

                goto end;

            else

                selected_streams[i] = ret;

            ret = 0;

        } else {

            selected_streams[i] = 1;

        }

    }



    if (do_read_frames || do_read_packets) {

        if (do_show_frames && do_show_packets &&

            wctx->writer->flags & WRITER_FLAG_PUT_PACKETS_AND_FRAMES_IN_SAME_CHAPTER)

            section_id = SECTION_ID_PACKETS_AND_FRAMES;

        else if (do_show_packets && !do_show_frames)

            section_id = SECTION_ID_PACKETS;

        else // (!do_show_packets && do_show_frames)

            section_id = SECTION_ID_FRAMES;

        if (do_show_frames || do_show_packets)

            writer_print_section_header(wctx, section_id);

        read_packets(wctx, fmt_ctx);

        if (do_show_frames || do_show_packets)

            writer_print_section_footer(wctx);

    }

    if (do_show_programs)

        show_programs(wctx, fmt_ctx);

    if (do_show_streams)

        show_streams(wctx, fmt_ctx);

    if (do_show_chapters)

        show_chapters(wctx, fmt_ctx);

    if (do_show_format)

        show_format(wctx, fmt_ctx);



end:

    close_input_file(&fmt_ctx);

    av_freep(&nb_streams_frames);

    av_freep(&nb_streams_packets);

    av_freep(&selected_streams);



    return ret;

}

static int decode_frame_header(AVCodecContext *ctx,

                               const uint8_t *data, int size, int *ref)

{

    VP9Context *s = ctx->priv_data;

    int c, i, j, k, l, m, n, w, h, max, size2, res, sharp;

    int last_invisible;

    const uint8_t *data2;



    /* general header */

    if ((res = init_get_bits8(&s->gb, data, size)) < 0) {

        av_log(ctx, AV_LOG_ERROR, "Failed to initialize bitstream reader\n");

        return res;

    }

    if (get_bits(&s->gb, 2) != 0x2) { // frame marker

        av_log(ctx, AV_LOG_ERROR, "Invalid frame marker\n");

        return AVERROR_INVALIDDATA;

    }

    s->profile = get_bits1(&s->gb);

    if (get_bits1(&s->gb)) { // reserved bit

        av_log(ctx, AV_LOG_ERROR, "Reserved bit should be zero\n");

        return AVERROR_INVALIDDATA;

    }

    if (get_bits1(&s->gb)) {

        *ref = get_bits(&s->gb, 3);

        return 0;

    }

    s->last_uses_2pass = s->uses_2pass;

    s->last_keyframe  = s->keyframe;

    s->keyframe       = !get_bits1(&s->gb);

    last_invisible    = s->invisible;

    s->invisible      = !get_bits1(&s->gb);

    s->errorres       = get_bits1(&s->gb);

    s->use_last_frame_mvs = !s->errorres && !last_invisible;

    if (s->keyframe) {

        if (get_bits_long(&s->gb, 24) != VP9_SYNCCODE) { // synccode

            av_log(ctx, AV_LOG_ERROR, "Invalid sync code\n");

            return AVERROR_INVALIDDATA;

        }

        s->colorspace = get_bits(&s->gb, 3);

        if (s->colorspace == 7) { // RGB = profile 1

            av_log(ctx, AV_LOG_ERROR, "RGB not supported in profile 0\n");

            return AVERROR_INVALIDDATA;

        }

        s->fullrange  = get_bits1(&s->gb);

        // for profile 1, here follows the subsampling bits

        s->refreshrefmask = 0xff;

        w = get_bits(&s->gb, 16) + 1;

        h = get_bits(&s->gb, 16) + 1;

        if (get_bits1(&s->gb)) // display size

            skip_bits(&s->gb, 32);

    } else {

        s->intraonly  = s->invisible ? get_bits1(&s->gb) : 0;

        s->resetctx   = s->errorres ? 0 : get_bits(&s->gb, 2);

        if (s->intraonly) {

            if (get_bits_long(&s->gb, 24) != VP9_SYNCCODE) { // synccode

                av_log(ctx, AV_LOG_ERROR, "Invalid sync code\n");

                return AVERROR_INVALIDDATA;

            }

            s->refreshrefmask = get_bits(&s->gb, 8);

            w = get_bits(&s->gb, 16) + 1;

            h = get_bits(&s->gb, 16) + 1;

            if (get_bits1(&s->gb)) // display size

                skip_bits(&s->gb, 32);

        } else {

            s->refreshrefmask = get_bits(&s->gb, 8);

            s->refidx[0]      = get_bits(&s->gb, 3);

            s->signbias[0]    = get_bits1(&s->gb);

            s->refidx[1]      = get_bits(&s->gb, 3);

            s->signbias[1]    = get_bits1(&s->gb);

            s->refidx[2]      = get_bits(&s->gb, 3);

            s->signbias[2]    = get_bits1(&s->gb);

            if (!s->refs[s->refidx[0]].f->data[0] ||

                !s->refs[s->refidx[1]].f->data[0] ||

                !s->refs[s->refidx[2]].f->data[0]) {

                av_log(ctx, AV_LOG_ERROR, "Not all references are available\n");

                return AVERROR_INVALIDDATA;

            }

            if (get_bits1(&s->gb)) {

                w = s->refs[s->refidx[0]].f->width;

                h = s->refs[s->refidx[0]].f->height;

            } else if (get_bits1(&s->gb)) {

                w = s->refs[s->refidx[1]].f->width;

                h = s->refs[s->refidx[1]].f->height;

            } else if (get_bits1(&s->gb)) {

                w = s->refs[s->refidx[2]].f->width;

                h = s->refs[s->refidx[2]].f->height;

            } else {

                w = get_bits(&s->gb, 16) + 1;

                h = get_bits(&s->gb, 16) + 1;

            }

            // Note that in this code, "CUR_FRAME" is actually before we

            // have formally allocated a frame, and thus actually represents

            // the _last_ frame

            s->use_last_frame_mvs &= s->frames[CUR_FRAME].tf.f->width == w &&

                                     s->frames[CUR_FRAME].tf.f->height == h;

            if (get_bits1(&s->gb)) // display size

                skip_bits(&s->gb, 32);

            s->highprecisionmvs = get_bits1(&s->gb);

            s->filtermode = get_bits1(&s->gb) ? FILTER_SWITCHABLE :

                                                get_bits(&s->gb, 2);

            s->allowcompinter = s->signbias[0] != s->signbias[1] ||

                                s->signbias[0] != s->signbias[2];

            if (s->allowcompinter) {

                if (s->signbias[0] == s->signbias[1]) {

                    s->fixcompref    = 2;

                    s->varcompref[0] = 0;

                    s->varcompref[1] = 1;

                } else if (s->signbias[0] == s->signbias[2]) {

                    s->fixcompref    = 1;

                    s->varcompref[0] = 0;

                    s->varcompref[1] = 2;

                } else {

                    s->fixcompref    = 0;

                    s->varcompref[0] = 1;

                    s->varcompref[1] = 2;

                }

            }

        }

    }

    s->refreshctx   = s->errorres ? 0 : get_bits1(&s->gb);

    s->parallelmode = s->errorres ? 1 : get_bits1(&s->gb);

    s->framectxid   = c = get_bits(&s->gb, 2);



    /* loopfilter header data */

    s->filter.level = get_bits(&s->gb, 6);

    sharp = get_bits(&s->gb, 3);

    // if sharpness changed, reinit lim/mblim LUTs. if it didn't change, keep

    // the old cache values since they are still valid

    if (s->filter.sharpness != sharp)

        memset(s->filter.lim_lut, 0, sizeof(s->filter.lim_lut));

    s->filter.sharpness = sharp;

    if ((s->lf_delta.enabled = get_bits1(&s->gb))) {

        if (get_bits1(&s->gb)) {

            for (i = 0; i < 4; i++)

                if (get_bits1(&s->gb))

                    s->lf_delta.ref[i] = get_sbits_inv(&s->gb, 6);

            for (i = 0; i < 2; i++)

                if (get_bits1(&s->gb))

                    s->lf_delta.mode[i] = get_sbits_inv(&s->gb, 6);

        }

    } else {

        memset(&s->lf_delta, 0, sizeof(s->lf_delta));

    }



    /* quantization header data */

    s->yac_qi      = get_bits(&s->gb, 8);

    s->ydc_qdelta  = get_bits1(&s->gb) ? get_sbits_inv(&s->gb, 4) : 0;

    s->uvdc_qdelta = get_bits1(&s->gb) ? get_sbits_inv(&s->gb, 4) : 0;

    s->uvac_qdelta = get_bits1(&s->gb) ? get_sbits_inv(&s->gb, 4) : 0;

    s->lossless    = s->yac_qi == 0 && s->ydc_qdelta == 0 &&

                     s->uvdc_qdelta == 0 && s->uvac_qdelta == 0;



    /* segmentation header info */

    if ((s->segmentation.enabled = get_bits1(&s->gb))) {

        if ((s->segmentation.update_map = get_bits1(&s->gb))) {

            for (i = 0; i < 7; i++)

                s->prob.seg[i] = get_bits1(&s->gb) ?

                                 get_bits(&s->gb, 8) : 255;

            if ((s->segmentation.temporal = get_bits1(&s->gb)))

                for (i = 0; i < 3; i++)

                    s->prob.segpred[i] = get_bits1(&s->gb) ?

                                         get_bits(&s->gb, 8) : 255;

        } else {

            s->use_last_frame_segmap = !s->keyframe && !s->intraonly &&

                s->frames[CUR_FRAME].tf.f->width == w &&

                s->frames[CUR_FRAME].tf.f->height == h;

        }



        if (get_bits1(&s->gb)) {

            s->segmentation.absolute_vals = get_bits1(&s->gb);

            for (i = 0; i < 8; i++) {

                if ((s->segmentation.feat[i].q_enabled = get_bits1(&s->gb)))

                    s->segmentation.feat[i].q_val = get_sbits_inv(&s->gb, 8);

                if ((s->segmentation.feat[i].lf_enabled = get_bits1(&s->gb)))

                    s->segmentation.feat[i].lf_val = get_sbits_inv(&s->gb, 6);

                if ((s->segmentation.feat[i].ref_enabled = get_bits1(&s->gb)))

                    s->segmentation.feat[i].ref_val = get_bits(&s->gb, 2);

                s->segmentation.feat[i].skip_enabled = get_bits1(&s->gb);

            }

        }

    } else {

        s->segmentation.feat[0].q_enabled    = 0;

        s->segmentation.feat[0].lf_enabled   = 0;

        s->segmentation.feat[0].skip_enabled = 0;

        s->segmentation.feat[0].ref_enabled  = 0;

    }



    // set qmul[] based on Y/UV, AC/DC and segmentation Q idx deltas

    for (i = 0; i < (s->segmentation.enabled ? 8 : 1); i++) {

        int qyac, qydc, quvac, quvdc, lflvl, sh;



        if (s->segmentation.feat[i].q_enabled) {

            if (s->segmentation.absolute_vals)

                qyac = s->segmentation.feat[i].q_val;

            else

                qyac = s->yac_qi + s->segmentation.feat[i].q_val;

        } else {

            qyac  = s->yac_qi;

        }

        qydc  = av_clip_uintp2(qyac + s->ydc_qdelta, 8);

        quvdc = av_clip_uintp2(qyac + s->uvdc_qdelta, 8);

        quvac = av_clip_uintp2(qyac + s->uvac_qdelta, 8);

        qyac  = av_clip_uintp2(qyac, 8);



        s->segmentation.feat[i].qmul[0][0] = vp9_dc_qlookup[qydc];

        s->segmentation.feat[i].qmul[0][1] = vp9_ac_qlookup[qyac];

        s->segmentation.feat[i].qmul[1][0] = vp9_dc_qlookup[quvdc];

        s->segmentation.feat[i].qmul[1][1] = vp9_ac_qlookup[quvac];



        sh = s->filter.level >= 32;

        if (s->segmentation.feat[i].lf_enabled) {

            if (s->segmentation.absolute_vals)

                lflvl = s->segmentation.feat[i].lf_val;

            else

                lflvl = s->filter.level + s->segmentation.feat[i].lf_val;

        } else {

            lflvl  = s->filter.level;

        }

        s->segmentation.feat[i].lflvl[0][0] =

        s->segmentation.feat[i].lflvl[0][1] =

            av_clip_uintp2(lflvl + (s->lf_delta.ref[0] << sh), 6);

        for (j = 1; j < 4; j++) {

            s->segmentation.feat[i].lflvl[j][0] =

                av_clip_uintp2(lflvl + ((s->lf_delta.ref[j] +

                                         s->lf_delta.mode[0]) << sh), 6);

            s->segmentation.feat[i].lflvl[j][1] =

                av_clip_uintp2(lflvl + ((s->lf_delta.ref[j] +

                                         s->lf_delta.mode[1]) << sh), 6);

        }

    }



    /* tiling info */

    if ((res = update_size(ctx, w, h)) < 0) {

        av_log(ctx, AV_LOG_ERROR, "Failed to initialize decoder for %dx%d\n", w, h);

        return res;

    }

    for (s->tiling.log2_tile_cols = 0;

         (s->sb_cols >> s->tiling.log2_tile_cols) > 64;

         s->tiling.log2_tile_cols++) ;

    for (max = 0; (s->sb_cols >> max) >= 4; max++) ;

    max = FFMAX(0, max - 1);

    while (max > s->tiling.log2_tile_cols) {

        if (get_bits1(&s->gb))

            s->tiling.log2_tile_cols++;

        else

            break;

    }

    s->tiling.log2_tile_rows = decode012(&s->gb);

    s->tiling.tile_rows = 1 << s->tiling.log2_tile_rows;

    if (s->tiling.tile_cols != (1 << s->tiling.log2_tile_cols)) {

        s->tiling.tile_cols = 1 << s->tiling.log2_tile_cols;

        s->c_b = av_fast_realloc(s->c_b, &s->c_b_size,

                                 sizeof(VP56RangeCoder) * s->tiling.tile_cols);

        if (!s->c_b) {

            av_log(ctx, AV_LOG_ERROR, "Ran out of memory during range coder init\n");

            return AVERROR(ENOMEM);

        }

    }



    if (s->keyframe || s->errorres || s->intraonly) {

        s->prob_ctx[0].p = s->prob_ctx[1].p = s->prob_ctx[2].p =

                           s->prob_ctx[3].p = vp9_default_probs;

        memcpy(s->prob_ctx[0].coef, vp9_default_coef_probs,

               sizeof(vp9_default_coef_probs));

        memcpy(s->prob_ctx[1].coef, vp9_default_coef_probs,

               sizeof(vp9_default_coef_probs));

        memcpy(s->prob_ctx[2].coef, vp9_default_coef_probs,

               sizeof(vp9_default_coef_probs));

        memcpy(s->prob_ctx[3].coef, vp9_default_coef_probs,

               sizeof(vp9_default_coef_probs));

    }



    // next 16 bits is size of the rest of the header (arith-coded)

    size2 = get_bits(&s->gb, 16);

    data2 = align_get_bits(&s->gb);

    if (size2 > size - (data2 - data)) {

        av_log(ctx, AV_LOG_ERROR, "Invalid compressed header size\n");

        return AVERROR_INVALIDDATA;

    }

    ff_vp56_init_range_decoder(&s->c, data2, size2);

    if (vp56_rac_get_prob_branchy(&s->c, 128)) { // marker bit

        av_log(ctx, AV_LOG_ERROR, "Marker bit was set\n");

        return AVERROR_INVALIDDATA;

    }



    if (s->keyframe || s->intraonly) {

        memset(s->counts.coef, 0, sizeof(s->counts.coef) + sizeof(s->counts.eob));

    } else {

        memset(&s->counts, 0, sizeof(s->counts));

    }

    // FIXME is it faster to not copy here, but do it down in the fw updates

    // as explicit copies if the fw update is missing (and skip the copy upon

    // fw update)?

    s->prob.p = s->prob_ctx[c].p;



    // txfm updates

    if (s->lossless) {

        s->txfmmode = TX_4X4;

    } else {

        s->txfmmode = vp8_rac_get_uint(&s->c, 2);

        if (s->txfmmode == 3)

            s->txfmmode += vp8_rac_get(&s->c);



        if (s->txfmmode == TX_SWITCHABLE) {

            for (i = 0; i < 2; i++)

                if (vp56_rac_get_prob_branchy(&s->c, 252))

                    s->prob.p.tx8p[i] = update_prob(&s->c, s->prob.p.tx8p[i]);

            for (i = 0; i < 2; i++)

                for (j = 0; j < 2; j++)

                    if (vp56_rac_get_prob_branchy(&s->c, 252))

                        s->prob.p.tx16p[i][j] =

                            update_prob(&s->c, s->prob.p.tx16p[i][j]);

            for (i = 0; i < 2; i++)

                for (j = 0; j < 3; j++)

                    if (vp56_rac_get_prob_branchy(&s->c, 252))

                        s->prob.p.tx32p[i][j] =

                            update_prob(&s->c, s->prob.p.tx32p[i][j]);

        }

    }



    // coef updates

    for (i = 0; i < 4; i++) {

        uint8_t (*ref)[2][6][6][3] = s->prob_ctx[c].coef[i];

        if (vp8_rac_get(&s->c)) {

            for (j = 0; j < 2; j++)

                for (k = 0; k < 2; k++)

                    for (l = 0; l < 6; l++)

                        for (m = 0; m < 6; m++) {

                            uint8_t *p = s->prob.coef[i][j][k][l][m];

                            uint8_t *r = ref[j][k][l][m];

                            if (m >= 3 && l == 0) // dc only has 3 pt

                                break;

                            for (n = 0; n < 3; n++) {

                                if (vp56_rac_get_prob_branchy(&s->c, 252)) {

                                    p[n] = update_prob(&s->c, r[n]);

                                } else {

                                    p[n] = r[n];

                                }

                            }

                            p[3] = 0;

                        }

        } else {

            for (j = 0; j < 2; j++)

                for (k = 0; k < 2; k++)

                    for (l = 0; l < 6; l++)

                        for (m = 0; m < 6; m++) {

                            uint8_t *p = s->prob.coef[i][j][k][l][m];

                            uint8_t *r = ref[j][k][l][m];

                            if (m > 3 && l == 0) // dc only has 3 pt

                                break;

                            memcpy(p, r, 3);

                            p[3] = 0;

                        }

        }

        if (s->txfmmode == i)

            break;

    }



    // mode updates

    for (i = 0; i < 3; i++)

        if (vp56_rac_get_prob_branchy(&s->c, 252))

            s->prob.p.skip[i] = update_prob(&s->c, s->prob.p.skip[i]);

    if (!s->keyframe && !s->intraonly) {

        for (i = 0; i < 7; i++)

            for (j = 0; j < 3; j++)

                if (vp56_rac_get_prob_branchy(&s->c, 252))

                    s->prob.p.mv_mode[i][j] =

                        update_prob(&s->c, s->prob.p.mv_mode[i][j]);



        if (s->filtermode == FILTER_SWITCHABLE)

            for (i = 0; i < 4; i++)

                for (j = 0; j < 2; j++)

                    if (vp56_rac_get_prob_branchy(&s->c, 252))

                        s->prob.p.filter[i][j] =

                            update_prob(&s->c, s->prob.p.filter[i][j]);



        for (i = 0; i < 4; i++)

            if (vp56_rac_get_prob_branchy(&s->c, 252))

                s->prob.p.intra[i] = update_prob(&s->c, s->prob.p.intra[i]);



        if (s->allowcompinter) {

            s->comppredmode = vp8_rac_get(&s->c);

            if (s->comppredmode)

                s->comppredmode += vp8_rac_get(&s->c);

            if (s->comppredmode == PRED_SWITCHABLE)

                for (i = 0; i < 5; i++)

                    if (vp56_rac_get_prob_branchy(&s->c, 252))

                        s->prob.p.comp[i] =

                            update_prob(&s->c, s->prob.p.comp[i]);

        } else {

            s->comppredmode = PRED_SINGLEREF;

        }



        if (s->comppredmode != PRED_COMPREF) {

            for (i = 0; i < 5; i++) {

                if (vp56_rac_get_prob_branchy(&s->c, 252))

                    s->prob.p.single_ref[i][0] =

                        update_prob(&s->c, s->prob.p.single_ref[i][0]);

                if (vp56_rac_get_prob_branchy(&s->c, 252))

                    s->prob.p.single_ref[i][1] =

                        update_prob(&s->c, s->prob.p.single_ref[i][1]);

            }

        }



        if (s->comppredmode != PRED_SINGLEREF) {

            for (i = 0; i < 5; i++)

                if (vp56_rac_get_prob_branchy(&s->c, 252))

                    s->prob.p.comp_ref[i] =

                        update_prob(&s->c, s->prob.p.comp_ref[i]);

        }



        for (i = 0; i < 4; i++)

            for (j = 0; j < 9; j++)

                if (vp56_rac_get_prob_branchy(&s->c, 252))

                    s->prob.p.y_mode[i][j] =

                        update_prob(&s->c, s->prob.p.y_mode[i][j]);



        for (i = 0; i < 4; i++)

            for (j = 0; j < 4; j++)

                for (k = 0; k < 3; k++)

                    if (vp56_rac_get_prob_branchy(&s->c, 252))

                        s->prob.p.partition[3 - i][j][k] =

                            update_prob(&s->c, s->prob.p.partition[3 - i][j][k]);



        // mv fields don't use the update_prob subexp model for some reason

        for (i = 0; i < 3; i++)

            if (vp56_rac_get_prob_branchy(&s->c, 252))

                s->prob.p.mv_joint[i] = (vp8_rac_get_uint(&s->c, 7) << 1) | 1;



        for (i = 0; i < 2; i++) {

            if (vp56_rac_get_prob_branchy(&s->c, 252))

                s->prob.p.mv_comp[i].sign = (vp8_rac_get_uint(&s->c, 7) << 1) | 1;



            for (j = 0; j < 10; j++)

                if (vp56_rac_get_prob_branchy(&s->c, 252))

                    s->prob.p.mv_comp[i].classes[j] =

                        (vp8_rac_get_uint(&s->c, 7) << 1) | 1;



            if (vp56_rac_get_prob_branchy(&s->c, 252))

                s->prob.p.mv_comp[i].class0 = (vp8_rac_get_uint(&s->c, 7) << 1) | 1;



            for (j = 0; j < 10; j++)

                if (vp56_rac_get_prob_branchy(&s->c, 252))

                    s->prob.p.mv_comp[i].bits[j] =

                        (vp8_rac_get_uint(&s->c, 7) << 1) | 1;

        }



        for (i = 0; i < 2; i++) {

            for (j = 0; j < 2; j++)

                for (k = 0; k < 3; k++)

                    if (vp56_rac_get_prob_branchy(&s->c, 252))

                        s->prob.p.mv_comp[i].class0_fp[j][k] =

                            (vp8_rac_get_uint(&s->c, 7) << 1) | 1;



            for (j = 0; j < 3; j++)

                if (vp56_rac_get_prob_branchy(&s->c, 252))

                    s->prob.p.mv_comp[i].fp[j] =

                        (vp8_rac_get_uint(&s->c, 7) << 1) | 1;

        }



        if (s->highprecisionmvs) {

            for (i = 0; i < 2; i++) {

                if (vp56_rac_get_prob_branchy(&s->c, 252))

                    s->prob.p.mv_comp[i].class0_hp =

                        (vp8_rac_get_uint(&s->c, 7) << 1) | 1;



                if (vp56_rac_get_prob_branchy(&s->c, 252))

                    s->prob.p.mv_comp[i].hp =

                        (vp8_rac_get_uint(&s->c, 7) << 1) | 1;

            }

        }

    }



    return (data2 - data) + size2;

}

yuv2422_1_c_template(SwsContext *c, const int16_t *buf0,

                     const int16_t *ubuf[2], const int16_t *vbuf[2],

                     const int16_t *abuf0, uint8_t *dest, int dstW,

                     int uvalpha, int y, enum PixelFormat target)

{

    const int16_t *ubuf0 = ubuf[0], *ubuf1 = ubuf[1],

                  *vbuf0 = vbuf[0], *vbuf1 = vbuf[1];

    int i;



    if (uvalpha < 2048) {

        for (i = 0; i < (dstW >> 1); i++) {

            int Y1 = buf0[i * 2]     >> 7;

            int Y2 = buf0[i * 2 + 1] >> 7;

            int U  = ubuf1[i]        >> 7;

            int V  = vbuf1[i]        >> 7;



            output_pixels(i * 4, Y1, U, Y2, V);

        }

    } else {

        for (i = 0; i < (dstW >> 1); i++) {

            int Y1 =  buf0[i * 2]          >> 7;

            int Y2 =  buf0[i * 2 + 1]      >> 7;

            int U  = (ubuf0[i] + ubuf1[i]) >> 8;

            int V  = (vbuf0[i] + vbuf1[i]) >> 8;



            output_pixels(i * 4, Y1, U, Y2, V);

        }

    }

}

static void decode_sublayer_hrd(HEVCContext *s, int nb_cpb,

                                int subpic_params_present)

{

    GetBitContext *gb = &s->HEVClc.gb;

    int i;



    for (i = 0; i < nb_cpb; i++) {

        get_ue_golomb_long(gb); // bit_rate_value_minus1

        get_ue_golomb_long(gb); // cpb_size_value_minus1



        if (subpic_params_present) {

            get_ue_golomb_long(gb); // cpb_size_du_value_minus1

            get_ue_golomb_long(gb); // bit_rate_du_value_minus1

        }

        skip_bits1(gb); // cbr_flag

    }

}

static void mpeg4_encode_visual_object_header(MpegEncContext * s){

    int profile_and_level_indication;

    int vo_ver_id;



    if(s->max_b_frames || s->quarter_sample){

        profile_and_level_indication= 0xF1; // adv simple level 1

        vo_ver_id= 5;

    }else{

        profile_and_level_indication= 0x01; // simple level 1

        vo_ver_id= 1;

    }

    //FIXME levels



    put_bits(&s->pb, 16, 0);

    put_bits(&s->pb, 16, VOS_STARTCODE);



    put_bits(&s->pb, 8, profile_and_level_indication);



    put_bits(&s->pb, 16, 0);

    put_bits(&s->pb, 16, VISUAL_OBJ_STARTCODE);



    put_bits(&s->pb, 1, 1);

        put_bits(&s->pb, 4, vo_ver_id);

        put_bits(&s->pb, 3, 1); //priority



    put_bits(&s->pb, 4, 1); //visual obj type== video obj



    put_bits(&s->pb, 1, 0); //video signal type == no clue //FIXME



    ff_mpeg4_stuffing(&s->pb);

}

static void add_entry1(TiffEncoderContext *s,

                       enum TiffTags tag, enum TiffTypes type, int val)

{

    uint16_t w  = val;

    uint32_t dw = val;

    add_entry(s, tag, type, 1, type == TIFF_SHORT ? (void *)&w : (void *)&dw);

}

int ff_hevc_decode_nal_sps(HEVCContext *s)

{

    const AVPixFmtDescriptor *desc;

    GetBitContext *gb = &s->HEVClc->gb;

    int ret    = 0;

    int sps_id = 0;

    int log2_diff_max_min_transform_block_size;

    int bit_depth_chroma, start, vui_present, sublayer_ordering_info;

    int i;



    HEVCSPS *sps;

    AVBufferRef *sps_buf = av_buffer_allocz(sizeof(*sps));



    if (!sps_buf)

        return AVERROR(ENOMEM);

    sps = (HEVCSPS*)sps_buf->data;



    av_log(s->avctx, AV_LOG_DEBUG, "Decoding SPS\n");



    // Coded parameters



    sps->vps_id = get_bits(gb, 4);

    if (sps->vps_id >= MAX_VPS_COUNT) {

        av_log(s->avctx, AV_LOG_ERROR, "VPS id out of range: %d\n", sps->vps_id);

        ret = AVERROR_INVALIDDATA;

        goto err;

    }



    if (!s->vps_list[sps->vps_id]) {

        av_log(s->avctx, AV_LOG_ERROR, "VPS does not exist \n");

        ret = AVERROR_INVALIDDATA;

        goto err;

    }



    sps->max_sub_layers = get_bits(gb, 3) + 1;

    if (sps->max_sub_layers > MAX_SUB_LAYERS) {

        av_log(s->avctx, AV_LOG_ERROR, "sps_max_sub_layers out of range: %d\n",

               sps->max_sub_layers);

        ret = AVERROR_INVALIDDATA;

        goto err;

    }



    skip_bits1(gb); // temporal_id_nesting_flag



    parse_ptl(s, &sps->ptl, sps->max_sub_layers);



    sps_id = get_ue_golomb_long(gb);

    if (sps_id >= MAX_SPS_COUNT) {

        av_log(s->avctx, AV_LOG_ERROR, "SPS id out of range: %d\n", sps_id);

        ret = AVERROR_INVALIDDATA;

        goto err;

    }



    sps->chroma_format_idc = get_ue_golomb_long(gb);

    if (sps->chroma_format_idc != 1) {

        avpriv_report_missing_feature(s->avctx, "chroma_format_idc != 1\n");

        ret = AVERROR_PATCHWELCOME;

        goto err;

    }



    if (sps->chroma_format_idc == 3)

        sps->separate_colour_plane_flag = get_bits1(gb);



    sps->width  = get_ue_golomb_long(gb);

    sps->height = get_ue_golomb_long(gb);

    if ((ret = av_image_check_size(sps->width,

                                   sps->height, 0, s->avctx)) < 0)

        goto err;



    if (get_bits1(gb)) { // pic_conformance_flag

        //TODO: * 2 is only valid for 420

        sps->pic_conf_win.left_offset   = get_ue_golomb_long(gb) * 2;

        sps->pic_conf_win.right_offset  = get_ue_golomb_long(gb) * 2;

        sps->pic_conf_win.top_offset    = get_ue_golomb_long(gb) * 2;

        sps->pic_conf_win.bottom_offset = get_ue_golomb_long(gb) * 2;



        if (s->avctx->flags2 & CODEC_FLAG2_IGNORE_CROP) {

            av_log(s->avctx, AV_LOG_DEBUG,

                   "discarding sps conformance window, "

                   "original values are l:%u r:%u t:%u b:%u\n",

                   sps->pic_conf_win.left_offset,

                   sps->pic_conf_win.right_offset,

                   sps->pic_conf_win.top_offset,

                   sps->pic_conf_win.bottom_offset);



            sps->pic_conf_win.left_offset   =

            sps->pic_conf_win.right_offset  =

            sps->pic_conf_win.top_offset    =

            sps->pic_conf_win.bottom_offset = 0;

        }

        sps->output_window = sps->pic_conf_win;

    }



    sps->bit_depth   = get_ue_golomb_long(gb) + 8;

    bit_depth_chroma = get_ue_golomb_long(gb) + 8;

    if (bit_depth_chroma != sps->bit_depth) {

        av_log(s->avctx, AV_LOG_ERROR,

               "Luma bit depth (%d) is different from chroma bit depth (%d), "

               "this is unsupported.\n",

               sps->bit_depth, bit_depth_chroma);

        ret = AVERROR_INVALIDDATA;

        goto err;

    }



    if (sps->chroma_format_idc == 1) {

        switch (sps->bit_depth) {

        case 8:  sps->pix_fmt = AV_PIX_FMT_YUV420P;   break;

        case 9:  sps->pix_fmt = AV_PIX_FMT_YUV420P9;  break;

        case 10: sps->pix_fmt = AV_PIX_FMT_YUV420P10; break;

        default:

            av_log(s->avctx, AV_LOG_ERROR, "Unsupported bit depth: %d\n",

                   sps->bit_depth);

            ret = AVERROR_PATCHWELCOME;

            goto err;

        }

    } else {

        av_log(s->avctx, AV_LOG_ERROR,

               "non-4:2:0 support is currently unspecified.\n");

        return AVERROR_PATCHWELCOME;

    }



    desc = av_pix_fmt_desc_get(sps->pix_fmt);

    if (!desc) {

        ret = AVERROR(EINVAL);

        goto err;

    }



    sps->hshift[0] = sps->vshift[0] = 0;

    sps->hshift[2] = sps->hshift[1] = desc->log2_chroma_w;

    sps->vshift[2] = sps->vshift[1] = desc->log2_chroma_h;



    sps->pixel_shift = sps->bit_depth > 8;



    sps->log2_max_poc_lsb = get_ue_golomb_long(gb) + 4;

    if (sps->log2_max_poc_lsb > 16) {

        av_log(s->avctx, AV_LOG_ERROR, "log2_max_pic_order_cnt_lsb_minus4 out range: %d\n",

               sps->log2_max_poc_lsb - 4);

        ret = AVERROR_INVALIDDATA;

        goto err;

    }



    sublayer_ordering_info = get_bits1(gb);

    start = sublayer_ordering_info ? 0 : sps->max_sub_layers - 1;

    for (i = start; i < sps->max_sub_layers; i++) {

        sps->temporal_layer[i].max_dec_pic_buffering = get_ue_golomb_long(gb) + 1;

        sps->temporal_layer[i].num_reorder_pics      = get_ue_golomb_long(gb);

        sps->temporal_layer[i].max_latency_increase  = get_ue_golomb_long(gb) - 1;

        if (sps->temporal_layer[i].max_dec_pic_buffering > MAX_DPB_SIZE) {

            av_log(s->avctx, AV_LOG_ERROR, "sps_max_dec_pic_buffering_minus1 out of range: %d\n",

                   sps->temporal_layer[i].max_dec_pic_buffering - 1);

            ret = AVERROR_INVALIDDATA;

            goto err;

        }

        if (sps->temporal_layer[i].num_reorder_pics > sps->temporal_layer[i].max_dec_pic_buffering - 1) {

            av_log(s->avctx, AV_LOG_ERROR, "sps_max_num_reorder_pics out of range: %d\n",

                   sps->temporal_layer[i].num_reorder_pics);

            ret = AVERROR_INVALIDDATA;

            goto err;

        }

    }



    if (!sublayer_ordering_info) {

        for (i = 0; i < start; i++) {

            sps->temporal_layer[i].max_dec_pic_buffering = sps->temporal_layer[start].max_dec_pic_buffering;

            sps->temporal_layer[i].num_reorder_pics      = sps->temporal_layer[start].num_reorder_pics;

            sps->temporal_layer[i].max_latency_increase  = sps->temporal_layer[start].max_latency_increase;

        }

    }



    sps->log2_min_cb_size                    = get_ue_golomb_long(gb) + 3;

    sps->log2_diff_max_min_coding_block_size = get_ue_golomb_long(gb);

    sps->log2_min_tb_size                    = get_ue_golomb_long(gb) + 2;

    log2_diff_max_min_transform_block_size   = get_ue_golomb_long(gb);

    sps->log2_max_trafo_size                 = log2_diff_max_min_transform_block_size +

                                               sps->log2_min_tb_size;



    if (sps->log2_min_tb_size >= sps->log2_min_cb_size) {

        av_log(s->avctx, AV_LOG_ERROR, "Invalid value for log2_min_tb_size");

        ret = AVERROR_INVALIDDATA;

        goto err;

    }

    sps->max_transform_hierarchy_depth_inter = get_ue_golomb_long(gb);

    sps->max_transform_hierarchy_depth_intra = get_ue_golomb_long(gb);



    sps->scaling_list_enable_flag = get_bits1(gb);

    if (sps->scaling_list_enable_flag) {

        set_default_scaling_list_data(&sps->scaling_list);



        if (get_bits1(gb)) {

            ret = scaling_list_data(s, &sps->scaling_list);

            if (ret < 0)

                goto err;

        }

    }



    sps->amp_enabled_flag = get_bits1(gb);

    sps->sao_enabled      = get_bits1(gb);



    sps->pcm_enabled_flag = get_bits1(gb);

    if (sps->pcm_enabled_flag) {

        sps->pcm.bit_depth   = get_bits(gb, 4) + 1;

        sps->pcm.bit_depth_chroma = get_bits(gb, 4) + 1;

        sps->pcm.log2_min_pcm_cb_size = get_ue_golomb_long(gb) + 3;

        sps->pcm.log2_max_pcm_cb_size = sps->pcm.log2_min_pcm_cb_size +

                                        get_ue_golomb_long(gb);

        if (sps->pcm.bit_depth > sps->bit_depth) {

            av_log(s->avctx, AV_LOG_ERROR,

                   "PCM bit depth (%d) is greater than normal bit depth (%d)\n",

                   sps->pcm.bit_depth, sps->bit_depth);

            ret = AVERROR_INVALIDDATA;

            goto err;

        }



        sps->pcm.loop_filter_disable_flag = get_bits1(gb);

    }



    sps->nb_st_rps = get_ue_golomb_long(gb);

    if (sps->nb_st_rps > MAX_SHORT_TERM_RPS_COUNT) {

        av_log(s->avctx, AV_LOG_ERROR, "Too many short term RPS: %d.\n",

               sps->nb_st_rps);

        ret = AVERROR_INVALIDDATA;

        goto err;

    }

    for (i = 0; i < sps->nb_st_rps; i++) {

        if ((ret = ff_hevc_decode_short_term_rps(s, &sps->st_rps[i],

                                                 sps, 0)) < 0)

            goto err;

    }



    sps->long_term_ref_pics_present_flag = get_bits1(gb);

    if (sps->long_term_ref_pics_present_flag) {

        sps->num_long_term_ref_pics_sps = get_ue_golomb_long(gb);

        for (i = 0; i < sps->num_long_term_ref_pics_sps; i++) {

            sps->lt_ref_pic_poc_lsb_sps[i]       = get_bits(gb, sps->log2_max_poc_lsb);

            sps->used_by_curr_pic_lt_sps_flag[i] = get_bits1(gb);

        }

    }



    sps->sps_temporal_mvp_enabled_flag          = get_bits1(gb);

    sps->sps_strong_intra_smoothing_enable_flag = get_bits1(gb);

    sps->vui.sar = (AVRational){0, 1};

    vui_present = get_bits1(gb);

    if (vui_present)

        decode_vui(s, sps);

    skip_bits1(gb); // sps_extension_flag



    if (s->apply_defdispwin) {

        sps->output_window.left_offset   += sps->vui.def_disp_win.left_offset;

        sps->output_window.right_offset  += sps->vui.def_disp_win.right_offset;

        sps->output_window.top_offset    += sps->vui.def_disp_win.top_offset;

        sps->output_window.bottom_offset += sps->vui.def_disp_win.bottom_offset;

    }

    if (sps->output_window.left_offset & (0x1F >> (sps->pixel_shift)) &&

        !(s->avctx->flags & CODEC_FLAG_UNALIGNED)) {

        sps->output_window.left_offset &= ~(0x1F >> (sps->pixel_shift));

        av_log(s->avctx, AV_LOG_WARNING, "Reducing left output window to %d "

               "chroma samples to preserve alignment.\n",

               sps->output_window.left_offset);

    }

    sps->output_width  = sps->width -

                         (sps->output_window.left_offset + sps->output_window.right_offset);

    sps->output_height = sps->height -

                         (sps->output_window.top_offset + sps->output_window.bottom_offset);

    if (sps->output_width <= 0 || sps->output_height <= 0) {

        av_log(s->avctx, AV_LOG_WARNING, "Invalid visible frame dimensions: %dx%d.\n",

               sps->output_width, sps->output_height);

        if (s->avctx->err_recognition & AV_EF_EXPLODE) {

            ret = AVERROR_INVALIDDATA;

            goto err;

        }

        av_log(s->avctx, AV_LOG_WARNING,

               "Displaying the whole video surface.\n");

        sps->pic_conf_win.left_offset   =

        sps->pic_conf_win.right_offset  =

        sps->pic_conf_win.top_offset    =

        sps->pic_conf_win.bottom_offset = 0;

        sps->output_width               = sps->width;

        sps->output_height              = sps->height;

    }



    // Inferred parameters

    sps->log2_ctb_size = sps->log2_min_cb_size +

                         sps->log2_diff_max_min_coding_block_size;

    sps->log2_min_pu_size = sps->log2_min_cb_size - 1;



    sps->ctb_width  = (sps->width  + (1 << sps->log2_ctb_size) - 1) >> sps->log2_ctb_size;

    sps->ctb_height = (sps->height + (1 << sps->log2_ctb_size) - 1) >> sps->log2_ctb_size;

    sps->ctb_size   = sps->ctb_width * sps->ctb_height;



    sps->min_cb_width  = sps->width  >> sps->log2_min_cb_size;

    sps->min_cb_height = sps->height >> sps->log2_min_cb_size;

    sps->min_tb_width  = sps->width  >> sps->log2_min_tb_size;

    sps->min_tb_height = sps->height >> sps->log2_min_tb_size;

    sps->min_pu_width  = sps->width  >> sps->log2_min_pu_size;

    sps->min_pu_height = sps->height >> sps->log2_min_pu_size;



    sps->qp_bd_offset = 6 * (sps->bit_depth - 8);



    if (sps->width  & ((1 << sps->log2_min_cb_size) - 1) ||

        sps->height & ((1 << sps->log2_min_cb_size) - 1)) {

        av_log(s->avctx, AV_LOG_ERROR, "Invalid coded frame dimensions.\n");

        goto err;

    }



    if (sps->log2_ctb_size > MAX_LOG2_CTB_SIZE) {

        av_log(s->avctx, AV_LOG_ERROR, "CTB size out of range: 2^%d\n", sps->log2_ctb_size);

        goto err;

    }

    if (sps->max_transform_hierarchy_depth_inter > sps->log2_ctb_size - sps->log2_min_tb_size) {

        av_log(s->avctx, AV_LOG_ERROR, "max_transform_hierarchy_depth_inter out of range: %d\n",

               sps->max_transform_hierarchy_depth_inter);

        goto err;

    }

    if (sps->max_transform_hierarchy_depth_intra > sps->log2_ctb_size - sps->log2_min_tb_size) {

        av_log(s->avctx, AV_LOG_ERROR, "max_transform_hierarchy_depth_intra out of range: %d\n",

               sps->max_transform_hierarchy_depth_intra);

        goto err;

    }

    if (sps->log2_max_trafo_size > FFMIN(sps->log2_ctb_size, 5)) {

        av_log(s->avctx, AV_LOG_ERROR,

               "max transform block size out of range: %d\n",

               sps->log2_max_trafo_size);

        goto err;

    }



    if (s->avctx->debug & FF_DEBUG_BITSTREAM) {

        av_log(s->avctx, AV_LOG_DEBUG,

               "Parsed SPS: id %d; coded wxh: %dx%d; "

               "cropped wxh: %dx%d; pix_fmt: %s.\n",

               sps_id, sps->width, sps->height,

               sps->output_width, sps->output_height,

               av_get_pix_fmt_name(sps->pix_fmt));

    }



    /* check if this is a repeat of an already parsed SPS, then keep the

     * original one.

     * otherwise drop all PPSes that depend on it */

    if (s->sps_list[sps_id] &&

        !memcmp(s->sps_list[sps_id]->data, sps_buf->data, sps_buf->size)) {

        av_buffer_unref(&sps_buf);

    } else {

        for (i = 0; i < FF_ARRAY_ELEMS(s->pps_list); i++) {

            if (s->pps_list[i] && ((HEVCPPS*)s->pps_list[i]->data)->sps_id == sps_id)

                av_buffer_unref(&s->pps_list[i]);

        }

        av_buffer_unref(&s->sps_list[sps_id]);

        s->sps_list[sps_id] = sps_buf;

    }



    return 0;



err:

    av_buffer_unref(&sps_buf);

    return ret;

}

static void do_audio_out(AVFormatContext *s, OutputStream *ost,

                         InputStream *ist, AVFrame *decoded_frame)

{

    uint8_t *buftmp;



    int size_out, frame_bytes, resample_changed;

    AVCodecContext *enc = ost->st->codec;

    AVCodecContext *dec = ist->st->codec;

    int osize = av_get_bytes_per_sample(enc->sample_fmt);

    int isize = av_get_bytes_per_sample(dec->sample_fmt);

    uint8_t *buf = decoded_frame->data[0];

    int size     = decoded_frame->nb_samples * dec->channels * isize;



    if (alloc_audio_output_buf(dec, enc, decoded_frame->nb_samples) < 0) {

        av_log(NULL, AV_LOG_FATAL, "Error allocating audio buffer\n");

        exit_program(1);

    }



    if (enc->channels != dec->channels || enc->sample_rate != dec->sample_rate)

        ost->audio_resample = 1;



    resample_changed = ost->resample_sample_fmt  != dec->sample_fmt ||

                       ost->resample_channels    != dec->channels   ||

                       ost->resample_sample_rate != dec->sample_rate;



    if ((ost->audio_resample && !ost->resample) || resample_changed) {

        if (resample_changed) {

            av_log(NULL, AV_LOG_INFO, "Input stream #%d:%d frame changed from rate:%d fmt:%s ch:%d to rate:%d fmt:%s ch:%d\n",

                   ist->file_index, ist->st->index,

                   ost->resample_sample_rate, av_get_sample_fmt_name(ost->resample_sample_fmt), ost->resample_channels,

                   dec->sample_rate, av_get_sample_fmt_name(dec->sample_fmt), dec->channels);

            ost->resample_sample_fmt  = dec->sample_fmt;

            ost->resample_channels    = dec->channels;

            ost->resample_sample_rate = dec->sample_rate;

            if (ost->resample)

                audio_resample_close(ost->resample);

        }

        /* if audio_sync_method is >1 the resampler is needed for audio drift compensation */

        if (audio_sync_method <= 1 &&

            ost->resample_sample_fmt  == enc->sample_fmt &&

            ost->resample_channels    == enc->channels   &&

            ost->resample_sample_rate == enc->sample_rate) {

            ost->resample = NULL;

            ost->audio_resample = 0;

        } else if (ost->audio_resample) {

            if (dec->sample_fmt != AV_SAMPLE_FMT_S16)

                av_log(NULL, AV_LOG_WARNING, "Using s16 intermediate sample format for resampling\n");

            ost->resample = av_audio_resample_init(enc->channels,    dec->channels,

                                                   enc->sample_rate, dec->sample_rate,

                                                   enc->sample_fmt,  dec->sample_fmt,

                                                   16, 10, 0, 0.8);

            if (!ost->resample) {

                av_log(NULL, AV_LOG_FATAL, "Can not resample %d channels @ %d Hz to %d channels @ %d Hz\n",

                       dec->channels, dec->sample_rate,

                       enc->channels, enc->sample_rate);

                exit_program(1);

            }

        }

    }



#define MAKE_SFMT_PAIR(a,b) ((a)+AV_SAMPLE_FMT_NB*(b))

    if (!ost->audio_resample && dec->sample_fmt != enc->sample_fmt &&

        MAKE_SFMT_PAIR(enc->sample_fmt,dec->sample_fmt) != ost->reformat_pair) {

        if (ost->reformat_ctx)

            av_audio_convert_free(ost->reformat_ctx);

        ost->reformat_ctx = av_audio_convert_alloc(enc->sample_fmt, 1,

                                                   dec->sample_fmt, 1, NULL, 0);

        if (!ost->reformat_ctx) {

            av_log(NULL, AV_LOG_FATAL, "Cannot convert %s sample format to %s sample format\n",

                   av_get_sample_fmt_name(dec->sample_fmt),

                   av_get_sample_fmt_name(enc->sample_fmt));

            exit_program(1);

        }

        ost->reformat_pair = MAKE_SFMT_PAIR(enc->sample_fmt,dec->sample_fmt);

    }



    if (audio_sync_method) {

        double delta = get_sync_ipts(ost, ist->last_dts) * enc->sample_rate - ost->sync_opts -

                       av_fifo_size(ost->fifo) / (enc->channels * osize);

        int idelta = delta * dec->sample_rate / enc->sample_rate;

        int byte_delta = idelta * isize * dec->channels;



        // FIXME resample delay

        if (fabs(delta) > 50) {

            if (ist->is_start || fabs(delta) > audio_drift_threshold*enc->sample_rate) {

                if (byte_delta < 0) {

                    byte_delta = FFMAX(byte_delta, -size);

                    size += byte_delta;

                    buf  -= byte_delta;

                    av_log(NULL, AV_LOG_VERBOSE, "discarding %d audio samples\n",

                           -byte_delta / (isize * dec->channels));

                    if (!size)

                        return;

                    ist->is_start = 0;

                } else {

                    av_fast_malloc(&async_buf, &allocated_async_buf_size,

                                   byte_delta + size);

                    if (!async_buf) {

                        av_log(NULL, AV_LOG_FATAL, "Out of memory in do_audio_out\n");

                        exit_program(1);

                    }



                    if (alloc_audio_output_buf(dec, enc, decoded_frame->nb_samples + idelta) < 0) {

                        av_log(NULL, AV_LOG_FATAL, "Error allocating audio buffer\n");

                        exit_program(1);

                    }

                    ist->is_start = 0;



                    generate_silence(async_buf, dec->sample_fmt, byte_delta);

                    memcpy(async_buf + byte_delta, buf, size);

                    buf = async_buf;

                    size += byte_delta;

                    av_log(NULL, AV_LOG_VERBOSE, "adding %d audio samples of silence\n", idelta);

                }

            } else if (audio_sync_method > 1) {

                int comp = av_clip(delta, -audio_sync_method, audio_sync_method);

                av_assert0(ost->audio_resample);

                av_log(NULL, AV_LOG_VERBOSE, "compensating audio timestamp drift:%f compensation:%d in:%d\n",

                       delta, comp, enc->sample_rate);

//                fprintf(stderr, "drift:%f len:%d opts:%"PRId64" ipts:%"PRId64" fifo:%d\n", delta, -1, ost->sync_opts, (int64_t)(get_sync_ipts(ost) * enc->sample_rate), av_fifo_size(ost->fifo)/(ost->st->codec->channels * 2));

                av_resample_compensate(*(struct AVResampleContext**)ost->resample, comp, enc->sample_rate);

            }

        }

    } else

        ost->sync_opts = lrintf(get_sync_ipts(ost, ist->last_dts) * enc->sample_rate) -

                                av_fifo_size(ost->fifo) / (enc->channels * osize); // FIXME wrong



    if (ost->audio_resample) {

        buftmp = audio_buf;

        size_out = audio_resample(ost->resample,

                                  (short *)buftmp, (short *)buf,

                                  size / (dec->channels * isize));

        size_out = size_out * enc->channels * osize;

    } else {

        buftmp = buf;

        size_out = size;

    }



    if (!ost->audio_resample && dec->sample_fmt != enc->sample_fmt) {

        const void *ibuf[6] = { buftmp };

        void *obuf[6]  = { audio_buf };

        int istride[6] = { isize };

        int ostride[6] = { osize };

        int len = size_out / istride[0];

        if (av_audio_convert(ost->reformat_ctx, obuf, ostride, ibuf, istride, len) < 0) {

            printf("av_audio_convert() failed\n");

            if (exit_on_error)

                exit_program(1);

            return;

        }

        buftmp = audio_buf;

        size_out = len * osize;

    }



    /* now encode as many frames as possible */

    if (!(enc->codec->capabilities & CODEC_CAP_VARIABLE_FRAME_SIZE)) {

        /* output resampled raw samples */

        if (av_fifo_realloc2(ost->fifo, av_fifo_size(ost->fifo) + size_out) < 0) {

            av_log(NULL, AV_LOG_FATAL, "av_fifo_realloc2() failed\n");

            exit_program(1);

        }

        av_fifo_generic_write(ost->fifo, buftmp, size_out, NULL);



        frame_bytes = enc->frame_size * osize * enc->channels;



        while (av_fifo_size(ost->fifo) >= frame_bytes) {

            av_fifo_generic_read(ost->fifo, audio_buf, frame_bytes, NULL);

            encode_audio_frame(s, ost, audio_buf, frame_bytes);

        }

    } else {

        encode_audio_frame(s, ost, buftmp, size_out);

    }

}

static int decode_cell(Indeo3DecodeContext *ctx, AVCodecContext *avctx,

                       Plane *plane, Cell *cell, const uint8_t *data_ptr,

                       const uint8_t *last_ptr)

{

    int           x, mv_x, mv_y, mode, vq_index, prim_indx, second_indx;

    int           zoom_fac;

    int           offset, error = 0, swap_quads[2];

    uint8_t       code, *block, *ref_block = 0;

    const vqEntry *delta[2];

    const uint8_t *data_start = data_ptr;



    /* get coding mode and VQ table index from the VQ descriptor byte */

    code     = *data_ptr++;

    mode     = code >> 4;

    vq_index = code & 0xF;



    /* setup output and reference pointers */

    offset = (cell->ypos << 2) * plane->pitch + (cell->xpos << 2);

    block  =  plane->pixels[ctx->buf_sel] + offset;

    if (!cell->mv_ptr) {

        /* use previous line as reference for INTRA cells */

        ref_block = block - plane->pitch;

    } else if (mode >= 10) {

        /* for mode 10 and 11 INTER first copy the predicted cell into the current one */

        /* so we don't need to do data copying for each RLE code later */

        copy_cell(ctx, plane, cell);

    } else {

        /* set the pointer to the reference pixels for modes 0-4 INTER */

        mv_y      = cell->mv_ptr[0];

        mv_x      = cell->mv_ptr[1];

        if (   mv_x + 4*cell->xpos < 0

            || mv_y + 4*cell->ypos < 0

            || mv_x + 4*cell->xpos + 4*cell->width  > plane->width

            || mv_y + 4*cell->ypos + 4*cell->height > plane->height) {

            av_log(avctx, AV_LOG_ERROR, "motion vector %d %d outside reference\n", mv_x + 4*cell->xpos, mv_y + 4*cell->ypos);

            return AVERROR_INVALIDDATA;

        }

        offset   += mv_y * plane->pitch + mv_x;

        ref_block = plane->pixels[ctx->buf_sel ^ 1] + offset;

    }



    /* select VQ tables as follows: */

    /* modes 0 and 3 use only the primary table for all lines in a block */

    /* while modes 1 and 4 switch between primary and secondary tables on alternate lines */

    if (mode == 1 || mode == 4) {

        code        = ctx->alt_quant[vq_index];

        prim_indx   = (code >> 4)  + ctx->cb_offset;

        second_indx = (code & 0xF) + ctx->cb_offset;

    } else {

        vq_index += ctx->cb_offset;

        prim_indx = second_indx = vq_index;

    }



    if (prim_indx >= 24 || second_indx >= 24) {

        av_log(avctx, AV_LOG_ERROR, "Invalid VQ table indexes! Primary: %d, secondary: %d!\n",

               prim_indx, second_indx);

        return AVERROR_INVALIDDATA;

    }



    delta[0] = &vq_tab[second_indx];

    delta[1] = &vq_tab[prim_indx];

    swap_quads[0] = second_indx >= 16;

    swap_quads[1] = prim_indx   >= 16;



    /* requantize the prediction if VQ index of this cell differs from VQ index */

    /* of the predicted cell in order to avoid overflows. */

    if (vq_index >= 8 && ref_block) {

        for (x = 0; x < cell->width << 2; x++)

            ref_block[x] = requant_tab[vq_index & 7][ref_block[x] & 127];

    }



    error = IV3_NOERR;



    switch (mode) {

    case 0: /*------------------ MODES 0 & 1 (4x4 block processing) --------------------*/

    case 1:

    case 3: /*------------------ MODES 3 & 4 (4x8 block processing) --------------------*/

    case 4:

        if (mode >= 3 && cell->mv_ptr) {

            av_log(avctx, AV_LOG_ERROR, "Attempt to apply Mode 3/4 to an INTER cell!\n");

            return AVERROR_INVALIDDATA;

        }



        zoom_fac = mode >= 3;

        error = decode_cell_data(cell, block, ref_block, plane->pitch, 0, zoom_fac,

                                 mode, delta, swap_quads, &data_ptr, last_ptr);

        break;

    case 10: /*-------------------- MODE 10 (8x8 block processing) ---------------------*/

    case 11: /*----------------- MODE 11 (4x8 INTER block processing) ------------------*/

        if (mode == 10 && !cell->mv_ptr) { /* MODE 10 INTRA processing */

            error = decode_cell_data(cell, block, ref_block, plane->pitch, 1, 1,

                                     mode, delta, swap_quads, &data_ptr, last_ptr);

        } else { /* mode 10 and 11 INTER processing */

            if (mode == 11 && !cell->mv_ptr) {

               av_log(avctx, AV_LOG_ERROR, "Attempt to use Mode 11 for an INTRA cell!\n");

               return AVERROR_INVALIDDATA;

            }



            zoom_fac = mode == 10;

            error = decode_cell_data(cell, block, ref_block, plane->pitch,

                                     zoom_fac, 1, mode, delta, swap_quads,

                                     &data_ptr, last_ptr);

        }

        break;

    default:

        av_log(avctx, AV_LOG_ERROR, "Unsupported coding mode: %d\n", mode);

        return AVERROR_INVALIDDATA;

    }//switch mode



    switch (error) {

    case IV3_BAD_RLE:

        av_log(avctx, AV_LOG_ERROR, "Mode %d: RLE code %X is not allowed at the current line\n",

               mode, data_ptr[-1]);

        return AVERROR_INVALIDDATA;

    case IV3_BAD_DATA:

        av_log(avctx, AV_LOG_ERROR, "Mode %d: invalid VQ data\n", mode);

        return AVERROR_INVALIDDATA;

    case IV3_BAD_COUNTER:

        av_log(avctx, AV_LOG_ERROR, "Mode %d: RLE-FB invalid counter: %d\n", mode, code);

        return AVERROR_INVALIDDATA;

    case IV3_UNSUPPORTED:

        av_log(avctx, AV_LOG_ERROR, "Mode %d: unsupported RLE code: %X\n", mode, data_ptr[-1]);

        return AVERROR_INVALIDDATA;

    case IV3_OUT_OF_DATA:

        av_log(avctx, AV_LOG_ERROR, "Mode %d: attempt to read past end of buffer\n", mode);

        return AVERROR_INVALIDDATA;

    }



    return data_ptr - data_start; /* report number of bytes consumed from the input buffer */

}

static void reduce_matrix(AudioMix *am, const double *matrix, int stride)

{

    int i, o;



    memset(am->output_zero, 0, sizeof(am->output_zero));

    memset(am->input_skip,  0, sizeof(am->input_skip));

    memset(am->output_skip, 0, sizeof(am->output_skip));



    /* exclude output channels if they can be zeroed instead of mixed */

    for (o = 0; o < am->out_channels; o++) {

        int zero = 1;



        /* check if the output is always silent */

        for (i = 0; i < am->in_channels; i++) {

            if (matrix[o * stride + i] != 0.0) {

                zero = 0;

                break;

            }

        }

        /* check if the corresponding input channel makes a contribution to

           any output channel */

        if (o < am->in_channels) {

            for (i = 0; i < am->out_channels; i++) {

                if (matrix[i * stride + o] != 0.0) {

                    zero = 0;

                    break;

                }

            }

        }

        if (zero) {

            am->output_zero[o] = 1;

            am->out_matrix_channels--;

        }

    }

    if (am->out_matrix_channels == 0) {

        am->in_matrix_channels = 0;

        return;

    }



    /* skip input channels that contribute fully only to the corresponding

       output channel */

    for (i = 0; i < FFMIN(am->in_channels, am->out_channels); i++) {

        int skip = 1;



        for (o = 0; o < am->out_channels; o++) {

            int i0;

            if ((o != i && matrix[o * stride + i] != 0.0) ||

                (o == i && matrix[o * stride + i] != 1.0)) {

                skip = 0;

                break;

            }

            /* if the input contributes fully to the output, also check that no

               other inputs contribute to this output */

            if (o == i) {

                for (i0 = 0; i0 < am->in_channels; i0++) {

                    if (i0 != i && matrix[o * stride + i0] != 0.0) {

                        skip = 0;

                        break;

                    }

                }

            }

        }

        if (skip) {

            am->input_skip[i] = 1;

            am->in_matrix_channels--;

        }

    }

    /* skip input channels that do not contribute to any output channel */

    for (; i < am->in_channels; i++) {

        int contrib = 0;



        for (o = 0; o < am->out_channels; o++) {

            if (matrix[o * stride + i] != 0.0) {

                contrib = 1;

                break;

            }

        }

        if (!contrib) {

            am->input_skip[i] = 1;

            am->in_matrix_channels--;

        }

    }

    if (am->in_matrix_channels == 0) {

        am->out_matrix_channels = 0;

        return;

    }



    /* skip output channels that only get full contribution from the

       corresponding input channel */

    for (o = 0; o < FFMIN(am->in_channels, am->out_channels); o++) {

        int skip = 1;

        int o0;



        for (i = 0; i < am->in_channels; i++) {

            if ((o != i && matrix[o * stride + i] != 0.0) ||

                (o == i && matrix[o * stride + i] != 1.0)) {

                skip = 0;

                break;

            }

        }

        /* check if the corresponding input channel makes a contribution to

           any other output channel */

        i = o;

        for (o0 = 0; o0 < am->out_channels; o0++) {

            if (o0 != i && matrix[o0 * stride + i] != 0.0) {

                skip = 0;

                break;

            }

        }

        if (skip) {

            am->output_skip[o] = 1;

            am->out_matrix_channels--;

        }

    }

    if (am->out_matrix_channels == 0) {

        am->in_matrix_channels = 0;

        return;

    }

}

static int decode_slice_header(H264Context *h, H264Context *h0){

    MpegEncContext * const s = &h->s;

    MpegEncContext * const s0 = &h0->s;

    unsigned int first_mb_in_slice;

    unsigned int pps_id;

    int num_ref_idx_active_override_flag;

    unsigned int slice_type, tmp, i, j;

    int default_ref_list_done = 0;

    int last_pic_structure;



    s->dropable= h->nal_ref_idc == 0;



    if((s->avctx->flags2 & CODEC_FLAG2_FAST) && !h->nal_ref_idc){

        s->me.qpel_put= s->dsp.put_2tap_qpel_pixels_tab;

        s->me.qpel_avg= s->dsp.avg_2tap_qpel_pixels_tab;

    }else{

        s->me.qpel_put= s->dsp.put_h264_qpel_pixels_tab;

        s->me.qpel_avg= s->dsp.avg_h264_qpel_pixels_tab;

    }



    first_mb_in_slice= get_ue_golomb(&s->gb);



    if((s->flags2 & CODEC_FLAG2_CHUNKS) && first_mb_in_slice == 0){

        h0->current_slice = 0;

        if (!s0->first_field)

            s->current_picture_ptr= NULL;

    }



    slice_type= get_ue_golomb_31(&s->gb);

    if(slice_type > 9){

        av_log(h->s.avctx, AV_LOG_ERROR, "slice type too large (%d) at %d %d\n", h->slice_type, s->mb_x, s->mb_y);

        return -1;

    }

    if(slice_type > 4){

        slice_type -= 5;

        h->slice_type_fixed=1;

    }else

        h->slice_type_fixed=0;



    slice_type= golomb_to_pict_type[ slice_type ];

    if (slice_type == FF_I_TYPE

        || (h0->current_slice != 0 && slice_type == h0->last_slice_type) ) {

        default_ref_list_done = 1;

    }

    h->slice_type= slice_type;

    h->slice_type_nos= slice_type & 3;



    s->pict_type= h->slice_type; // to make a few old functions happy, it's wrong though

    if (s->pict_type == FF_B_TYPE && s0->last_picture_ptr == NULL) {

        av_log(h->s.avctx, AV_LOG_ERROR,

               "B picture before any references, skipping\n");

        return -1;

    }



    pps_id= get_ue_golomb(&s->gb);

    if(pps_id>=MAX_PPS_COUNT){

        av_log(h->s.avctx, AV_LOG_ERROR, "pps_id out of range\n");

        return -1;

    }

    if(!h0->pps_buffers[pps_id]) {

        av_log(h->s.avctx, AV_LOG_ERROR, "non-existing PPS referenced\n");

        return -1;

    }

    h->pps= *h0->pps_buffers[pps_id];



    if(!h0->sps_buffers[h->pps.sps_id]) {

        av_log(h->s.avctx, AV_LOG_ERROR, "non-existing SPS referenced\n");

        return -1;

    }

    h->sps = *h0->sps_buffers[h->pps.sps_id];



    if(h == h0 && h->dequant_coeff_pps != pps_id){

        h->dequant_coeff_pps = pps_id;

        init_dequant_tables(h);

    }



    s->mb_width= h->sps.mb_width;

    s->mb_height= h->sps.mb_height * (2 - h->sps.frame_mbs_only_flag);



    h->b_stride=  s->mb_width*4;

    h->b8_stride= s->mb_width*2;



    s->width = 16*s->mb_width - 2*FFMIN(h->sps.crop_right, 7);

    if(h->sps.frame_mbs_only_flag)

        s->height= 16*s->mb_height - 2*FFMIN(h->sps.crop_bottom, 7);

    else

        s->height= 16*s->mb_height - 4*FFMIN(h->sps.crop_bottom, 3);



    if (s->context_initialized

        && (   s->width != s->avctx->width || s->height != s->avctx->height)) {

        if(h != h0)

            return -1;   // width / height changed during parallelized decoding

        free_tables(h);

        flush_dpb(s->avctx);

        MPV_common_end(s);

    }

    if (!s->context_initialized) {

        if(h != h0)

            return -1;  // we cant (re-)initialize context during parallel decoding

        if (MPV_common_init(s) < 0)

            return -1;

        s->first_field = 0;



        init_scan_tables(h);

        alloc_tables(h);



        for(i = 1; i < s->avctx->thread_count; i++) {

            H264Context *c;

            c = h->thread_context[i] = av_malloc(sizeof(H264Context));

            memcpy(c, h->s.thread_context[i], sizeof(MpegEncContext));

            memset(&c->s + 1, 0, sizeof(H264Context) - sizeof(MpegEncContext));

            c->sps = h->sps;

            c->pps = h->pps;

            init_scan_tables(c);

            clone_tables(c, h);

        }



        for(i = 0; i < s->avctx->thread_count; i++)

            if(context_init(h->thread_context[i]) < 0)

                return -1;



        s->avctx->width = s->width;

        s->avctx->height = s->height;

        s->avctx->sample_aspect_ratio= h->sps.sar;

        if(!s->avctx->sample_aspect_ratio.den)

            s->avctx->sample_aspect_ratio.den = 1;



        if(h->sps.timing_info_present_flag){

            s->avctx->time_base= (AVRational){h->sps.num_units_in_tick * 2, h->sps.time_scale};

            if(h->x264_build > 0 && h->x264_build < 44)

                s->avctx->time_base.den *= 2;

            av_reduce(&s->avctx->time_base.num, &s->avctx->time_base.den,

                      s->avctx->time_base.num, s->avctx->time_base.den, 1<<30);

        }

    }



    h->frame_num= get_bits(&s->gb, h->sps.log2_max_frame_num);



    h->mb_mbaff = 0;

    h->mb_aff_frame = 0;

    last_pic_structure = s0->picture_structure;

    if(h->sps.frame_mbs_only_flag){

        s->picture_structure= PICT_FRAME;

    }else{

        if(get_bits1(&s->gb)) { //field_pic_flag

            s->picture_structure= PICT_TOP_FIELD + get_bits1(&s->gb); //bottom_field_flag

        } else {

            s->picture_structure= PICT_FRAME;

            h->mb_aff_frame = h->sps.mb_aff;

        }

    }

    h->mb_field_decoding_flag= s->picture_structure != PICT_FRAME;



    if(h0->current_slice == 0){

        while(h->frame_num !=  h->prev_frame_num &&

              h->frame_num != (h->prev_frame_num+1)%(1<<h->sps.log2_max_frame_num)){

            av_log(NULL, AV_LOG_DEBUG, "Frame num gap %d %d\n", h->frame_num, h->prev_frame_num);

            frame_start(h);

            h->prev_frame_num++;

            h->prev_frame_num %= 1<<h->sps.log2_max_frame_num;

            s->current_picture_ptr->frame_num= h->prev_frame_num;

            execute_ref_pic_marking(h, NULL, 0);

        }



        /* See if we have a decoded first field looking for a pair... */

        if (s0->first_field) {

            assert(s0->current_picture_ptr);

            assert(s0->current_picture_ptr->data[0]);

            assert(s0->current_picture_ptr->reference != DELAYED_PIC_REF);



            /* figure out if we have a complementary field pair */

            if (!FIELD_PICTURE || s->picture_structure == last_pic_structure) {

                /*

                 * Previous field is unmatched. Don't display it, but let it

                 * remain for reference if marked as such.

                 */

                s0->current_picture_ptr = NULL;

                s0->first_field = FIELD_PICTURE;



            } else {

                if (h->nal_ref_idc &&

                        s0->current_picture_ptr->reference &&

                        s0->current_picture_ptr->frame_num != h->frame_num) {

                    /*

                     * This and previous field were reference, but had

                     * different frame_nums. Consider this field first in

                     * pair. Throw away previous field except for reference

                     * purposes.

                     */

                    s0->first_field = 1;

                    s0->current_picture_ptr = NULL;



                } else {

                    /* Second field in complementary pair */

                    s0->first_field = 0;

                }

            }



        } else {

            /* Frame or first field in a potentially complementary pair */

            assert(!s0->current_picture_ptr);

            s0->first_field = FIELD_PICTURE;

        }



        if((!FIELD_PICTURE || s0->first_field) && frame_start(h) < 0) {

            s0->first_field = 0;

            return -1;

        }

    }

    if(h != h0)

        clone_slice(h, h0);



    s->current_picture_ptr->frame_num= h->frame_num; //FIXME frame_num cleanup



    assert(s->mb_num == s->mb_width * s->mb_height);

    if(first_mb_in_slice << FIELD_OR_MBAFF_PICTURE >= s->mb_num ||

       first_mb_in_slice                    >= s->mb_num){

        av_log(h->s.avctx, AV_LOG_ERROR, "first_mb_in_slice overflow\n");

        return -1;

    }

    s->resync_mb_x = s->mb_x = first_mb_in_slice % s->mb_width;

    s->resync_mb_y = s->mb_y = (first_mb_in_slice / s->mb_width) << FIELD_OR_MBAFF_PICTURE;

    if (s->picture_structure == PICT_BOTTOM_FIELD)

        s->resync_mb_y = s->mb_y = s->mb_y + 1;

    assert(s->mb_y < s->mb_height);



    if(s->picture_structure==PICT_FRAME){

        h->curr_pic_num=   h->frame_num;

        h->max_pic_num= 1<< h->sps.log2_max_frame_num;

    }else{

        h->curr_pic_num= 2*h->frame_num + 1;

        h->max_pic_num= 1<<(h->sps.log2_max_frame_num + 1);

    }



    if(h->nal_unit_type == NAL_IDR_SLICE){

        get_ue_golomb(&s->gb); /* idr_pic_id */

    }



    if(h->sps.poc_type==0){

        h->poc_lsb= get_bits(&s->gb, h->sps.log2_max_poc_lsb);



        if(h->pps.pic_order_present==1 && s->picture_structure==PICT_FRAME){

            h->delta_poc_bottom= get_se_golomb(&s->gb);

        }

    }



    if(h->sps.poc_type==1 && !h->sps.delta_pic_order_always_zero_flag){

        h->delta_poc[0]= get_se_golomb(&s->gb);



        if(h->pps.pic_order_present==1 && s->picture_structure==PICT_FRAME)

            h->delta_poc[1]= get_se_golomb(&s->gb);

    }



    init_poc(h);



    if(h->pps.redundant_pic_cnt_present){

        h->redundant_pic_count= get_ue_golomb(&s->gb);

    }



    //set defaults, might be overridden a few lines later

    h->ref_count[0]= h->pps.ref_count[0];

    h->ref_count[1]= h->pps.ref_count[1];



    if(h->slice_type_nos != FF_I_TYPE){

        if(h->slice_type_nos == FF_B_TYPE){

            h->direct_spatial_mv_pred= get_bits1(&s->gb);

        }

        num_ref_idx_active_override_flag= get_bits1(&s->gb);



        if(num_ref_idx_active_override_flag){

            h->ref_count[0]= get_ue_golomb(&s->gb) + 1;

            if(h->slice_type_nos==FF_B_TYPE)

                h->ref_count[1]= get_ue_golomb(&s->gb) + 1;



            if(h->ref_count[0]-1 > 32-1 || h->ref_count[1]-1 > 32-1){

                av_log(h->s.avctx, AV_LOG_ERROR, "reference overflow\n");

                h->ref_count[0]= h->ref_count[1]= 1;

                return -1;

            }

        }

        if(h->slice_type_nos == FF_B_TYPE)

            h->list_count= 2;

        else

            h->list_count= 1;

    }else

        h->list_count= 0;



    if(!default_ref_list_done){

        fill_default_ref_list(h);

    }



    if(h->slice_type_nos!=FF_I_TYPE && decode_ref_pic_list_reordering(h) < 0)

        return -1;



    if(h->slice_type_nos!=FF_I_TYPE){

        s->last_picture_ptr= &h->ref_list[0][0];

        ff_copy_picture(&s->last_picture, s->last_picture_ptr);

    }

    if(h->slice_type_nos==FF_B_TYPE){

        s->next_picture_ptr= &h->ref_list[1][0];

        ff_copy_picture(&s->next_picture, s->next_picture_ptr);

    }



    if(   (h->pps.weighted_pred          && h->slice_type_nos == FF_P_TYPE )

       ||  (h->pps.weighted_bipred_idc==1 && h->slice_type_nos== FF_B_TYPE ) )

        pred_weight_table(h);

    else if(h->pps.weighted_bipred_idc==2 && h->slice_type_nos== FF_B_TYPE)

        implicit_weight_table(h);

    else {

        h->use_weight = 0;

        for (i = 0; i < 2; i++) {

            h->luma_weight_flag[i]   = 0;

            h->chroma_weight_flag[i] = 0;

        }

    }



    if(h->nal_ref_idc)

        decode_ref_pic_marking(h0, &s->gb);



    if(FRAME_MBAFF)

        fill_mbaff_ref_list(h);



    if(h->slice_type_nos==FF_B_TYPE && !h->direct_spatial_mv_pred)

        direct_dist_scale_factor(h);

    direct_ref_list_init(h);



    if( h->slice_type_nos != FF_I_TYPE && h->pps.cabac ){

        tmp = get_ue_golomb_31(&s->gb);

        if(tmp > 2){

            av_log(s->avctx, AV_LOG_ERROR, "cabac_init_idc overflow\n");

            return -1;

        }

        h->cabac_init_idc= tmp;

    }



    h->last_qscale_diff = 0;

    tmp = h->pps.init_qp + get_se_golomb(&s->gb);

    if(tmp>51){

        av_log(s->avctx, AV_LOG_ERROR, "QP %u out of range\n", tmp);

        return -1;

    }

    s->qscale= tmp;

    h->chroma_qp[0] = get_chroma_qp(h, 0, s->qscale);

    h->chroma_qp[1] = get_chroma_qp(h, 1, s->qscale);

    //FIXME qscale / qp ... stuff

    if(h->slice_type == FF_SP_TYPE){

        get_bits1(&s->gb); /* sp_for_switch_flag */

    }

    if(h->slice_type==FF_SP_TYPE || h->slice_type == FF_SI_TYPE){

        get_se_golomb(&s->gb); /* slice_qs_delta */

    }



    h->deblocking_filter = 1;

    h->slice_alpha_c0_offset = 0;

    h->slice_beta_offset = 0;

    if( h->pps.deblocking_filter_parameters_present ) {

        tmp= get_ue_golomb_31(&s->gb);

        if(tmp > 2){

            av_log(s->avctx, AV_LOG_ERROR, "deblocking_filter_idc %u out of range\n", tmp);

            return -1;

        }

        h->deblocking_filter= tmp;

        if(h->deblocking_filter < 2)

            h->deblocking_filter^= 1; // 1<->0



        if( h->deblocking_filter ) {

            h->slice_alpha_c0_offset = get_se_golomb(&s->gb) << 1;

            h->slice_beta_offset = get_se_golomb(&s->gb) << 1;

        }

    }



    if(   s->avctx->skip_loop_filter >= AVDISCARD_ALL

       ||(s->avctx->skip_loop_filter >= AVDISCARD_NONKEY && h->slice_type_nos != FF_I_TYPE)

       ||(s->avctx->skip_loop_filter >= AVDISCARD_BIDIR  && h->slice_type_nos == FF_B_TYPE)

       ||(s->avctx->skip_loop_filter >= AVDISCARD_NONREF && h->nal_ref_idc == 0))

        h->deblocking_filter= 0;



    if(h->deblocking_filter == 1 && h0->max_contexts > 1) {

        if(s->avctx->flags2 & CODEC_FLAG2_FAST) {

            /* Cheat slightly for speed:

               Do not bother to deblock across slices. */

            h->deblocking_filter = 2;

        } else {

            h0->max_contexts = 1;

            if(!h0->single_decode_warning) {

                av_log(s->avctx, AV_LOG_INFO, "Cannot parallelize deblocking type 1, decoding such frames in sequential order\n");

                h0->single_decode_warning = 1;

            }

            if(h != h0)

                return 1; // deblocking switched inside frame

        }

    }



#if 0 //FMO

    if( h->pps.num_slice_groups > 1  && h->pps.mb_slice_group_map_type >= 3 && h->pps.mb_slice_group_map_type <= 5)

        slice_group_change_cycle= get_bits(&s->gb, ?);

#endif



    h0->last_slice_type = slice_type;

    h->slice_num = ++h0->current_slice;

    if(h->slice_num >= MAX_SLICES){

        av_log(s->avctx, AV_LOG_ERROR, "Too many slices, increase MAX_SLICES and recompile\n");

    }



    for(j=0; j<2; j++){

        int *ref2frm= h->ref2frm[h->slice_num&(MAX_SLICES-1)][j];

        ref2frm[0]=

        ref2frm[1]= -1;

        for(i=0; i<16; i++)

            ref2frm[i+2]= 4*h->ref_list[j][i].frame_num

                          +(h->ref_list[j][i].reference&3);

        ref2frm[18+0]=

        ref2frm[18+1]= -1;

        for(i=16; i<48; i++)

            ref2frm[i+4]= 4*h->ref_list[j][i].frame_num

                          +(h->ref_list[j][i].reference&3);

    }



    h->emu_edge_width= (s->flags&CODEC_FLAG_EMU_EDGE) ? 0 : 16;

    h->emu_edge_height= (FRAME_MBAFF || FIELD_PICTURE) ? 0 : h->emu_edge_width;



    s->avctx->refs= h->sps.ref_frame_count;



    if(s->avctx->debug&FF_DEBUG_PICT_INFO){

        av_log(h->s.avctx, AV_LOG_DEBUG, "slice:%d %s mb:%d %c%s%s pps:%u frame:%d poc:%d/%d ref:%d/%d qp:%d loop:%d:%d:%d weight:%d%s %s\n",

               h->slice_num,

               (s->picture_structure==PICT_FRAME ? "F" : s->picture_structure==PICT_TOP_FIELD ? "T" : "B"),

               first_mb_in_slice,

               av_get_pict_type_char(h->slice_type), h->slice_type_fixed ? " fix" : "", h->nal_unit_type == NAL_IDR_SLICE ? " IDR" : "",

               pps_id, h->frame_num,

               s->current_picture_ptr->field_poc[0], s->current_picture_ptr->field_poc[1],

               h->ref_count[0], h->ref_count[1],

               s->qscale,

               h->deblocking_filter, h->slice_alpha_c0_offset/2, h->slice_beta_offset/2,

               h->use_weight,

               h->use_weight==1 && h->use_weight_chroma ? "c" : "",

               h->slice_type == FF_B_TYPE ? (h->direct_spatial_mv_pred ? "SPAT" : "TEMP") : ""

               );

    }



    return 0;

}

static void yuvj444p_to_rgb24(AVPicture *dst, AVPicture *src,

                              int width, int height)

{

    uint8_t *y1_ptr, *cb_ptr, *cr_ptr, *d, *d1;

    int w, y, cb, cr, r_add, g_add, b_add;

    uint8_t *cm = cropTbl + MAX_NEG_CROP;

    unsigned int r, g, b;



    d = dst->data[0];

    y1_ptr = src->data[0];

    cb_ptr = src->data[1];

    cr_ptr = src->data[2];

    for(;height > 0; height --) {

        d1 = d;

        for(w = width; w > 0; w--) {

            YUV_TO_RGB1(cb_ptr[0], cr_ptr[0]);



            YUV_TO_RGB2(r, g, b, y1_ptr[0]);

            RGB_OUT(d1, r, g, b);

            d1 += BPP;



            y1_ptr++;

            cb_ptr++;

            cr_ptr++;

        }

        d += dst->linesize[0];

        y1_ptr += src->linesize[0] - width;

        cb_ptr += src->linesize[1] - width;

        cr_ptr += src->linesize[2] - width;

    }

}

static int rtcp_parse_packet(RTPDemuxContext *s, const unsigned char *buf, int len)

{

    int payload_len;

    while (len >= 2) {

        switch (buf[1]) {

        case RTCP_SR:

            if (len < 16) {

                av_log(NULL, AV_LOG_ERROR, "Invalid length for RTCP SR packet\n");

                return AVERROR_INVALIDDATA;

            }

            payload_len = (AV_RB16(buf + 2) + 1) * 4;



            s->last_rtcp_ntp_time = AV_RB64(buf + 8);

            s->last_rtcp_timestamp = AV_RB32(buf + 16);

            if (s->first_rtcp_ntp_time == AV_NOPTS_VALUE) {

                s->first_rtcp_ntp_time = s->last_rtcp_ntp_time;

                if (!s->base_timestamp)

                    s->base_timestamp = s->last_rtcp_timestamp;

                s->rtcp_ts_offset = s->last_rtcp_timestamp - s->base_timestamp;

            }



            buf += payload_len;

            len -= payload_len;

            break;

        case RTCP_BYE:

            return -RTCP_BYE;

        default:

            return -1;

        }

    }

    return -1;

}

static int mov_read_header(AVFormatContext *s)

{

    MOVContext *mov = s->priv_data;

    AVIOContext *pb = s->pb;

    int j, err;

    MOVAtom atom = { AV_RL32("root") };

    int i;



    if (mov->decryption_key_len != 0 && mov->decryption_key_len != AES_CTR_KEY_SIZE) {

        av_log(s, AV_LOG_ERROR, "Invalid decryption key len %d expected %d\n",

            mov->decryption_key_len, AES_CTR_KEY_SIZE);

        return AVERROR(EINVAL);

    }



    mov->fc = s;

    mov->trak_index = -1;

    /* .mov and .mp4 aren't streamable anyway (only progressive download if moov is before mdat) */

    if (pb->seekable)

        atom.size = avio_size(pb);

    else

        atom.size = INT64_MAX;



    /* check MOV header */

    do {

    if (mov->moov_retry)

        avio_seek(pb, 0, SEEK_SET);

    if ((err = mov_read_default(mov, pb, atom)) < 0) {

        av_log(s, AV_LOG_ERROR, "error reading header\n");

        mov_read_close(s);

        return err;

    }

    } while (pb->seekable && !mov->found_moov && !mov->moov_retry++);

    if (!mov->found_moov) {

        av_log(s, AV_LOG_ERROR, "moov atom not found\n");

        mov_read_close(s);

        return AVERROR_INVALIDDATA;

    }

    av_log(mov->fc, AV_LOG_TRACE, "on_parse_exit_offset=%"PRId64"\n", avio_tell(pb));



    if (pb->seekable) {

        if (mov->nb_chapter_tracks > 0 && !mov->ignore_chapters)

            mov_read_chapters(s);

        for (i = 0; i < s->nb_streams; i++)

            if (s->streams[i]->codecpar->codec_tag == AV_RL32("tmcd")) {

                mov_read_timecode_track(s, s->streams[i]);

            } else if (s->streams[i]->codecpar->codec_tag == AV_RL32("rtmd")) {

                mov_read_rtmd_track(s, s->streams[i]);

            }

    }



    /* copy timecode metadata from tmcd tracks to the related video streams */

    for (i = 0; i < s->nb_streams; i++) {

        AVStream *st = s->streams[i];

        MOVStreamContext *sc = st->priv_data;

        if (sc->timecode_track > 0) {

            AVDictionaryEntry *tcr;

            int tmcd_st_id = -1;



            for (j = 0; j < s->nb_streams; j++)

                if (s->streams[j]->id == sc->timecode_track)

                    tmcd_st_id = j;



            if (tmcd_st_id < 0 || tmcd_st_id == i)

                continue;

            tcr = av_dict_get(s->streams[tmcd_st_id]->metadata, "timecode", NULL, 0);

            if (tcr)

                av_dict_set(&st->metadata, "timecode", tcr->value, 0);

        }

    }

    export_orphan_timecode(s);



    for (i = 0; i < s->nb_streams; i++) {

        AVStream *st = s->streams[i];

        MOVStreamContext *sc = st->priv_data;

        fix_timescale(mov, sc);

        if(st->codecpar->codec_type == AVMEDIA_TYPE_AUDIO && st->codecpar->codec_id == AV_CODEC_ID_AAC) {

            st->skip_samples = sc->start_pad;

        }

        if (st->codecpar->codec_type == AVMEDIA_TYPE_VIDEO && sc->nb_frames_for_fps > 0 && sc->duration_for_fps > 0)

            av_reduce(&st->avg_frame_rate.num, &st->avg_frame_rate.den,

                      sc->time_scale*(int64_t)sc->nb_frames_for_fps, sc->duration_for_fps, INT_MAX);

        if (st->codecpar->codec_type == AVMEDIA_TYPE_SUBTITLE) {

            if (st->codecpar->width <= 0 || st->codecpar->height <= 0) {

                st->codecpar->width  = sc->width;

                st->codecpar->height = sc->height;

            }

            if (st->codecpar->codec_id == AV_CODEC_ID_DVD_SUBTITLE) {

                if ((err = mov_rewrite_dvd_sub_extradata(st)) < 0)

                    return err;

            }

        }

        if (mov->handbrake_version &&

            mov->handbrake_version <= 1000000*0 + 1000*10 + 2 &&  // 0.10.2

            st->codecpar->codec_id == AV_CODEC_ID_MP3

        ) {

            av_log(s, AV_LOG_VERBOSE, "Forcing full parsing for mp3 stream\n");

            st->need_parsing = AVSTREAM_PARSE_FULL;

        }

    }



    if (mov->trex_data) {

        for (i = 0; i < s->nb_streams; i++) {

            AVStream *st = s->streams[i];

            MOVStreamContext *sc = st->priv_data;

            if (st->duration > 0)

                st->codecpar->bit_rate = sc->data_size * 8 * sc->time_scale / st->duration;

        }

    }



    if (mov->use_mfra_for > 0) {

        for (i = 0; i < s->nb_streams; i++) {

            AVStream *st = s->streams[i];

            MOVStreamContext *sc = st->priv_data;

            if (sc->duration_for_fps > 0) {

                st->codecpar->bit_rate = sc->data_size * 8 * sc->time_scale /

                    sc->duration_for_fps;

            }

        }

    }



    for (i = 0; i < mov->bitrates_count && i < s->nb_streams; i++) {

        if (mov->bitrates[i]) {

            s->streams[i]->codecpar->bit_rate = mov->bitrates[i];

        }

    }



    ff_rfps_calculate(s);



    for (i = 0; i < s->nb_streams; i++) {

        AVStream *st = s->streams[i];

        MOVStreamContext *sc = st->priv_data;



        switch (st->codecpar->codec_type) {

        case AVMEDIA_TYPE_AUDIO:

            err = ff_replaygain_export(st, s->metadata);

            if (err < 0) {

                mov_read_close(s);

                return err;

            }

            break;

        case AVMEDIA_TYPE_VIDEO:

            if (sc->display_matrix) {

                err = av_stream_add_side_data(st, AV_PKT_DATA_DISPLAYMATRIX, (uint8_t*)sc->display_matrix,

                                              sizeof(int32_t) * 9);

                if (err < 0)

                    return err;



                sc->display_matrix = NULL;

            }

            if (sc->stereo3d) {

                err = av_stream_add_side_data(st, AV_PKT_DATA_STEREO3D,

                                              (uint8_t *)sc->stereo3d,

                                              sizeof(*sc->stereo3d));

                if (err < 0)

                    return err;



                sc->stereo3d = NULL;

            }

            if (sc->spherical) {

                err = av_stream_add_side_data(st, AV_PKT_DATA_SPHERICAL,

                                              (uint8_t *)sc->spherical,

                                              sc->spherical_size);

                if (err < 0)

                    return err;



                sc->spherical = NULL;

            }

            break;

        }

    }

    ff_configure_buffers_for_index(s, AV_TIME_BASE);



    return 0;

}

static int thread_execute(AVCodecContext *avctx, action_func* func, void *arg, int *ret, int job_count, int job_size)

{

    SliceThreadContext *c = avctx->internal->thread_ctx;



    if (!(avctx->active_thread_type&FF_THREAD_SLICE) || avctx->thread_count <= 1)

        return avcodec_default_execute(avctx, func, arg, ret, job_count, job_size);



    if (job_count <= 0)

        return 0;



    pthread_mutex_lock(&c->current_job_lock);



    c->current_job = avctx->thread_count;

    c->job_count = job_count;

    c->job_size = job_size;

    c->args = arg;

    c->func = func;

    c->rets = ret;

    c->current_execute++;

    pthread_cond_broadcast(&c->current_job_cond);



    thread_park_workers(c, avctx->thread_count);



    return 0;

}

static void gain_compensate(COOKContext *q, cook_gains *gains_ptr,

                            float* previous_buffer)

{

    const float fc = q->pow2tab[gains_ptr->previous[0] + 63];

    float *buffer = q->mono_mdct_output;

    int i;



    /* Overlap with the previous block. */

    for(i=0 ; i<q->samples_per_channel ; i++) {

        buffer[i] *= fc;

        buffer[i] += previous_buffer[i];

    }



    /* Apply gain profile */

    for (i = 0; i < 8; i++) {

        if (gains_ptr->now[i] || gains_ptr->now[i + 1])

            interpolate(q, &buffer[q->gain_size_factor * i],

                        gains_ptr->now[i], gains_ptr->now[i + 1]);

    }



    /* Save away the current to be previous block. */

    memcpy(previous_buffer, buffer+q->samples_per_channel,

           sizeof(float)*q->samples_per_channel);

}

int ff_mov_init_hinting(AVFormatContext *s, int index, int src_index)

{

    MOVMuxContext *mov  = s->priv_data;

    MOVTrack *track     = &mov->tracks[index];

    MOVTrack *src_track = &mov->tracks[src_index];

    AVStream *src_st    = s->streams[src_index];

    int ret = AVERROR(ENOMEM);

    AVOutputFormat *rtp_format = av_guess_format("rtp", NULL, NULL);



    track->tag = MKTAG('r','t','p',' ');

    track->src_track = src_index;



    if (!rtp_format) {

        ret = AVERROR(ENOENT);

        goto fail;

    }



    track->enc = avcodec_alloc_context();

    if (!track->enc)

        goto fail;

    track->enc->codec_type = AVMEDIA_TYPE_DATA;

    track->enc->codec_tag  = track->tag;



    track->rtp_ctx = avformat_alloc_context();

    if (!track->rtp_ctx)

        goto fail;

    track->rtp_ctx->oformat = rtp_format;

    if (!av_new_stream(track->rtp_ctx, 0))

        goto fail;



    /* Copy stream parameters */

    track->rtp_ctx->streams[0]->sample_aspect_ratio =

                        src_st->sample_aspect_ratio;



    /* Remove the allocated codec context, link to the original one

     * instead, to give the rtp muxer access to codec parameters. */

    av_free(track->rtp_ctx->streams[0]->codec);

    track->rtp_ctx->streams[0]->codec = src_st->codec;



    if ((ret = url_open_dyn_packet_buf(&track->rtp_ctx->pb,

                                       RTP_MAX_PACKET_SIZE)) < 0)

        goto fail;

    ret = av_write_header(track->rtp_ctx);

    if (ret)

        goto fail;



    /* Copy the RTP AVStream timebase back to the hint AVStream */

    track->timescale = track->rtp_ctx->streams[0]->time_base.den;



    /* Mark the hinted track that packets written to it should be

     * sent to this track for hinting. */

    src_track->hint_track = index;

    return 0;

fail:

    av_log(s, AV_LOG_WARNING,

           "Unable to initialize hinting of stream %d\n", src_index);

    if (track->rtp_ctx && track->rtp_ctx->pb) {

        uint8_t *buf;

        url_close_dyn_buf(track->rtp_ctx->pb, &buf);

        av_free(buf);

    }

    if (track->rtp_ctx && track->rtp_ctx->streams[0]) {

        av_metadata_free(&track->rtp_ctx->streams[0]->metadata);


        av_free(track->rtp_ctx->streams[0]);

    }

    if (track->rtp_ctx) {

        av_metadata_free(&track->rtp_ctx->metadata);

        av_free(track->rtp_ctx->priv_data);

        av_freep(&track->rtp_ctx);

    }

    av_freep(&track->enc);

    /* Set a default timescale, to avoid crashes in dump_format */

    track->timescale = 90000;

    return ret;

}

static inline int l3_unscale(int value, int exponent)

{

    unsigned int m;

    int e;



    e  = table_4_3_exp  [4 * value + (exponent & 3)];

    m  = table_4_3_value[4 * value + (exponent & 3)];

    e -= exponent >> 2;

#ifdef DEBUG

    if(e < 1)

        av_log(NULL, AV_LOG_WARNING, "l3_unscale: e is %d\n", e);

#endif

    if (e > (SUINT)31)

        return 0;

    m = (m + (1 << (e - 1))) >> e;



    return m;

}

static int handle_p_frame_apng(AVCodecContext *avctx, PNGDecContext *s,

                               AVFrame *p)

{

    size_t x, y;

    uint8_t *buffer = av_malloc(s->image_linesize * s->height);



    if (!buffer)

        return AVERROR(ENOMEM);



    if (s->blend_op == APNG_BLEND_OP_OVER &&

        avctx->pix_fmt != AV_PIX_FMT_RGBA &&

        avctx->pix_fmt != AV_PIX_FMT_GRAY8A &&

        avctx->pix_fmt != AV_PIX_FMT_PAL8) {

        avpriv_request_sample(avctx, "Blending with pixel format %s",

                              av_get_pix_fmt_name(avctx->pix_fmt));

        return AVERROR_PATCHWELCOME;

    }



    // Do the disposal operation specified by the last frame on the frame

    if (s->last_dispose_op != APNG_DISPOSE_OP_PREVIOUS) {

        ff_thread_await_progress(&s->last_picture, INT_MAX, 0);

        memcpy(buffer, s->last_picture.f->data[0], s->image_linesize * s->height);



        if (s->last_dispose_op == APNG_DISPOSE_OP_BACKGROUND)

            for (y = s->last_y_offset; y < s->last_y_offset + s->last_h; ++y)

                memset(buffer + s->image_linesize * y + s->bpp * s->last_x_offset, 0, s->bpp * s->last_w);



        memcpy(s->previous_picture.f->data[0], buffer, s->image_linesize * s->height);

        ff_thread_report_progress(&s->previous_picture, INT_MAX, 0);

    } else {

        ff_thread_await_progress(&s->previous_picture, INT_MAX, 0);

        memcpy(buffer, s->previous_picture.f->data[0], s->image_linesize * s->height);

    }



    // Perform blending

    if (s->blend_op == APNG_BLEND_OP_SOURCE) {

        for (y = s->y_offset; y < s->y_offset + s->cur_h; ++y) {

            size_t row_start = s->image_linesize * y + s->bpp * s->x_offset;

            memcpy(buffer + row_start, p->data[0] + row_start, s->bpp * s->cur_w);

        }

    } else { // APNG_BLEND_OP_OVER

        for (y = s->y_offset; y < s->y_offset + s->cur_h; ++y) {

            uint8_t *foreground = p->data[0] + s->image_linesize * y + s->bpp * s->x_offset;

            uint8_t *background = buffer + s->image_linesize * y + s->bpp * s->x_offset;

            for (x = s->x_offset; x < s->x_offset + s->cur_w; ++x, foreground += s->bpp, background += s->bpp) {

                size_t b;

                uint8_t foreground_alpha, background_alpha, output_alpha;

                uint8_t output[4];



                // Since we might be blending alpha onto alpha, we use the following equations:

                // output_alpha = foreground_alpha + (1 - foreground_alpha) * background_alpha

                // output = (foreground_alpha * foreground + (1 - foreground_alpha) * background_alpha * background) / output_alpha



                switch (avctx->pix_fmt) {

                case AV_PIX_FMT_RGBA:

                    foreground_alpha = foreground[3];

                    background_alpha = background[3];

                    break;



                case AV_PIX_FMT_GRAY8A:

                    foreground_alpha = foreground[1];

                    background_alpha = background[1];

                    break;



                case AV_PIX_FMT_PAL8:

                    foreground_alpha = s->palette[foreground[0]] >> 24;

                    background_alpha = s->palette[background[0]] >> 24;

                    break;

                }



                if (foreground_alpha == 0)

                    continue;



                if (foreground_alpha == 255) {

                    memcpy(background, foreground, s->bpp);

                    continue;

                }



                if (avctx->pix_fmt == AV_PIX_FMT_PAL8) {

                    // TODO: Alpha blending with PAL8 will likely need the entire image converted over to RGBA first

                    avpriv_request_sample(avctx, "Alpha blending palette samples");

                    background[0] = foreground[0];

                    continue;

                }



                output_alpha = foreground_alpha + FAST_DIV255((255 - foreground_alpha) * background_alpha);



                for (b = 0; b < s->bpp - 1; ++b) {

                    if (output_alpha == 0) {

                        output[b] = 0;

                    } else if (background_alpha == 255) {

                        output[b] = FAST_DIV255(foreground_alpha * foreground[b] + (255 - foreground_alpha) * background[b]);

                    } else {

                        output[b] = (255 * foreground_alpha * foreground[b] + (255 - foreground_alpha) * background_alpha * background[b]) / (255 * output_alpha);

                    }

                }

                output[b] = output_alpha;

                memcpy(background, output, s->bpp);

            }

        }

    }



    // Copy blended buffer into the frame and free

    memcpy(p->data[0], buffer, s->image_linesize * s->height);

    av_free(buffer);



    return 0;

}

static int kalman_smoothen(WMAVoiceContext *s, int pitch,

                           const float *in, float *out, int size)

{

    int n;

    float optimal_gain = 0, dot;

    const float *ptr = &in[-FFMAX(s->min_pitch_val, pitch - 3)],

                *end = &in[-FFMIN(s->max_pitch_val, pitch + 3)],

                *best_hist_ptr;



    /* find best fitting point in history */

    do {

        dot = ff_scalarproduct_float_c(in, ptr, size);

        if (dot > optimal_gain) {

            optimal_gain  = dot;

            best_hist_ptr = ptr;

        }

    } while (--ptr >= end);



    if (optimal_gain <= 0)

        return -1;

    dot = ff_scalarproduct_float_c(best_hist_ptr, best_hist_ptr, size);

    if (dot <= 0) // would be 1.0

        return -1;



    if (optimal_gain <= dot) {

        dot = dot / (dot + 0.6 * optimal_gain); // 0.625-1.000

    } else

        dot = 0.625;



    /* actual smoothing */

    for (n = 0; n < size; n++)

        out[n] = best_hist_ptr[n] + dot * (in[n] - best_hist_ptr[n]);



    return 0;

}

static av_always_inline void thread_park_workers(SliceThreadContext *c, int thread_count)

{

    while (c->current_job != thread_count + c->job_count)

        pthread_cond_wait(&c->last_job_cond, &c->current_job_lock);

    pthread_mutex_unlock(&c->current_job_lock);

}

int av_image_get_linesize(enum PixelFormat pix_fmt, int width, int plane)

{

    const AVPixFmtDescriptor *desc = &av_pix_fmt_descriptors[pix_fmt];

    int max_step     [4];       /* max pixel step for each plane */

    int max_step_comp[4];       /* the component for each plane which has the max pixel step */

    int s, linesize;



    if ((unsigned)pix_fmt >= PIX_FMT_NB || desc->flags & PIX_FMT_HWACCEL)

        return AVERROR(EINVAL);



    av_image_fill_max_pixsteps(max_step, max_step_comp, desc);

    s = (max_step_comp[plane] == 1 || max_step_comp[plane] == 2) ? desc->log2_chroma_w : 0;

    linesize = max_step[plane] * (((width + (1 << s) - 1)) >> s);

    if (desc->flags & PIX_FMT_BITSTREAM)

        linesize = (linesize + 7) >> 3;

    return linesize;

}

static int field_end(H264Context *h, int in_setup)

{

    MpegEncContext *const s     = &h->s;

    AVCodecContext *const avctx = s->avctx;

    int err = 0;

    s->mb_y = 0;



    if (!in_setup && !s->droppable)

        ff_thread_report_progress(&s->current_picture_ptr->f, INT_MAX,

                                  s->picture_structure == PICT_BOTTOM_FIELD);



    if (CONFIG_H264_VDPAU_DECODER &&

        s->avctx->codec->capabilities & CODEC_CAP_HWACCEL_VDPAU)

        ff_vdpau_h264_set_reference_frames(s);



    if (in_setup || !(avctx->active_thread_type & FF_THREAD_FRAME)) {

        if (!s->droppable) {

            err = ff_h264_execute_ref_pic_marking(h, h->mmco, h->mmco_index);

            h->prev_poc_msb = h->poc_msb;

            h->prev_poc_lsb = h->poc_lsb;

        }

        h->prev_frame_num_offset = h->frame_num_offset;

        h->prev_frame_num        = h->frame_num;

        h->outputed_poc          = h->next_outputed_poc;

    }



    if (avctx->hwaccel) {

        if (avctx->hwaccel->end_frame(avctx) < 0)

            av_log(avctx, AV_LOG_ERROR,

                   "hardware accelerator failed to decode picture\n");

    }



    if (CONFIG_H264_VDPAU_DECODER &&

        s->avctx->codec->capabilities & CODEC_CAP_HWACCEL_VDPAU)

        ff_vdpau_h264_picture_complete(s);



    /*

     * FIXME: Error handling code does not seem to support interlaced

     * when slices span multiple rows

     * The ff_er_add_slice calls don't work right for bottom

     * fields; they cause massive erroneous error concealing

     * Error marking covers both fields (top and bottom).

     * This causes a mismatched s->error_count

     * and a bad error table. Further, the error count goes to

     * INT_MAX when called for bottom field, because mb_y is

     * past end by one (callers fault) and resync_mb_y != 0

     * causes problems for the first MB line, too.

     */

    if (!FIELD_PICTURE && h->current_slice)

        ff_er_frame_end(s);



    ff_MPV_frame_end(s);



    h->current_slice = 0;



    return err;

}

static int vmd_decode(VmdVideoContext *s, AVFrame *frame)

{

    int i;

    unsigned int *palette32;

    unsigned char r, g, b;



    GetByteContext gb;



    unsigned char meth;

    unsigned char *dp;   /* pointer to current frame */

    unsigned char *pp;   /* pointer to previous frame */

    unsigned char len;

    int ofs;



    int frame_x, frame_y;

    int frame_width, frame_height;



    frame_x = AV_RL16(&s->buf[6]);

    frame_y = AV_RL16(&s->buf[8]);

    frame_width = AV_RL16(&s->buf[10]) - frame_x + 1;

    frame_height = AV_RL16(&s->buf[12]) - frame_y + 1;

    if (frame_x < 0 || frame_width < 0 ||

        frame_x >= s->avctx->width ||

        frame_width > s->avctx->width ||

        frame_x + frame_width > s->avctx->width) {

        av_log(s->avctx, AV_LOG_ERROR,

               "Invalid horizontal range %d-%d\n",

               frame_x, frame_width);

        return AVERROR_INVALIDDATA;

    }

    if (frame_y < 0 || frame_height < 0 ||

        frame_y >= s->avctx->height ||

        frame_height > s->avctx->height ||

        frame_y + frame_height > s->avctx->height) {

        av_log(s->avctx, AV_LOG_ERROR,

               "Invalid vertical range %d-%d\n",

               frame_x, frame_width);

        return AVERROR_INVALIDDATA;

    }



    if ((frame_width == s->avctx->width && frame_height == s->avctx->height) &&

        (frame_x || frame_y)) {



        s->x_off = frame_x;

        s->y_off = frame_y;

    }

    frame_x -= s->x_off;

    frame_y -= s->y_off;



    /* if only a certain region will be updated, copy the entire previous

     * frame before the decode */

    if (s->prev_frame.data[0] &&

        (frame_x || frame_y || (frame_width != s->avctx->width) ||

        (frame_height != s->avctx->height))) {



        memcpy(frame->data[0], s->prev_frame.data[0],

            s->avctx->height * frame->linesize[0]);

    }



    /* check if there is a new palette */

    bytestream2_init(&gb, s->buf + 16, s->size - 16);

    if (s->buf[15] & 0x02) {

        bytestream2_skip(&gb, 2);

        palette32 = (unsigned int *)s->palette;

        if (bytestream2_get_bytes_left(&gb) >= PALETTE_COUNT * 3) {

            for (i = 0; i < PALETTE_COUNT; i++) {

                r = bytestream2_get_byteu(&gb) * 4;

                g = bytestream2_get_byteu(&gb) * 4;

                b = bytestream2_get_byteu(&gb) * 4;

                palette32[i] = (r << 16) | (g << 8) | (b);

            }

        } else {

            av_log(s->avctx, AV_LOG_ERROR, "Incomplete palette\n");

            return AVERROR_INVALIDDATA;

        }

        s->size -= PALETTE_COUNT * 3 + 2;

    }

    if (s->size > 0) {

        /* originally UnpackFrame in VAG's code */

        bytestream2_init(&gb, gb.buffer, s->buf + s->size - gb.buffer);

        if (bytestream2_get_bytes_left(&gb) < 1)

            return AVERROR_INVALIDDATA;

        meth = bytestream2_get_byteu(&gb);

        if (meth & 0x80) {

            lz_unpack(gb.buffer, bytestream2_get_bytes_left(&gb),

                      s->unpack_buffer, s->unpack_buffer_size);

            meth &= 0x7F;

            bytestream2_init(&gb, s->unpack_buffer, s->unpack_buffer_size);

        }



        dp = &frame->data[0][frame_y * frame->linesize[0] + frame_x];

        pp = &s->prev_frame.data[0][frame_y * s->prev_frame.linesize[0] + frame_x];

        switch (meth) {

        case 1:

            for (i = 0; i < frame_height; i++) {

                ofs = 0;

                do {

                    len = bytestream2_get_byte(&gb);

                    if (len & 0x80) {

                        len = (len & 0x7F) + 1;

                        if (ofs + len > frame_width || bytestream2_get_bytes_left(&gb) < len)

                            return AVERROR_INVALIDDATA;

                        bytestream2_get_buffer(&gb, &dp[ofs], len);

                        ofs += len;

                    } else {

                        /* interframe pixel copy */

                        if (ofs + len + 1 > frame_width || !s->prev_frame.data[0])

                            return AVERROR_INVALIDDATA;

                        memcpy(&dp[ofs], &pp[ofs], len + 1);

                        ofs += len + 1;

                    }

                } while (ofs < frame_width);

                if (ofs > frame_width) {

                    av_log(s->avctx, AV_LOG_ERROR, "VMD video: offset > width (%d > %d)\n",

                        ofs, frame_width);

                    return AVERROR_INVALIDDATA;

                }

                dp += frame->linesize[0];

                pp += s->prev_frame.linesize[0];

            }

            break;



        case 2:

            for (i = 0; i < frame_height; i++) {

                bytestream2_get_buffer(&gb, dp, frame_width);

                dp += frame->linesize[0];

                pp += s->prev_frame.linesize[0];

            }

            break;



        case 3:

            for (i = 0; i < frame_height; i++) {

                ofs = 0;

                do {

                    len = bytestream2_get_byte(&gb);

                    if (len & 0x80) {

                        len = (len & 0x7F) + 1;

                        if (bytestream2_get_byte(&gb) == 0xFF)

                            len = rle_unpack(gb.buffer, &dp[ofs],

                                             len, bytestream2_get_bytes_left(&gb),

                                             frame_width - ofs);

                        else

                            bytestream2_get_buffer(&gb, &dp[ofs], len);

                        bytestream2_skip(&gb, len);

                    } else {

                        /* interframe pixel copy */

                        if (ofs + len + 1 > frame_width || !s->prev_frame.data[0])

                            return AVERROR_INVALIDDATA;

                        memcpy(&dp[ofs], &pp[ofs], len + 1);

                        ofs += len + 1;

                    }

                } while (ofs < frame_width);

                if (ofs > frame_width) {

                    av_log(s->avctx, AV_LOG_ERROR, "VMD video: offset > width (%d > %d)\n",

                        ofs, frame_width);

                    return AVERROR_INVALIDDATA;

                }

                dp += frame->linesize[0];

                pp += s->prev_frame.linesize[0];

            }

            break;

        }

    }

    return 0;

}

static void joint_decode(COOKContext *q, float* mlt_buffer1,

                         float* mlt_buffer2) {

    int i,j;

    int decouple_tab[SUBBAND_SIZE];

    float decode_buffer[2048];  //Only 1060 might be needed.

    int idx, cpl_tmp,tmp_idx;

    float f1,f2;

    float* cplscale;



    memset(decouple_tab, 0, sizeof(decouple_tab));

    memset(decode_buffer, 0, sizeof(decode_buffer));



    /* Make sure the buffers are zeroed out. */

    memset(mlt_buffer1,0, 1024*sizeof(float));

    memset(mlt_buffer2,0, 1024*sizeof(float));

    decouple_info(q, decouple_tab);

    mono_decode(q, decode_buffer);



    /* The two channels are stored interleaved in decode_buffer. */

    for (i=0 ; i<q->js_subband_start ; i++) {

        for (j=0 ; j<SUBBAND_SIZE ; j++) {

            mlt_buffer1[i*20+j] = decode_buffer[i*40+j];

            mlt_buffer2[i*20+j] = decode_buffer[i*40+20+j];

        }

    }



    /* When we reach js_subband_start (the higher frequencies)

       the coefficients are stored in a coupling scheme. */

    idx = (1 << q->js_vlc_bits) - 1;

    if (q->js_subband_start < q->subbands) {

        for (i=0 ; i<q->subbands ; i++) {

            cpl_tmp = cplband[i + q->js_subband_start];

            idx -=decouple_tab[cpl_tmp];

            cplscale = (float*)cplscales[q->js_vlc_bits-2];  //choose decoupler table

            f1 = cplscale[decouple_tab[cpl_tmp]];

            f2 = cplscale[idx-1];

            for (j=0 ; j<SUBBAND_SIZE ; j++) {

                tmp_idx = ((2*q->js_subband_start + i)*20)+j;

                mlt_buffer1[20*(i+q->js_subband_start) + j] = f1 * decode_buffer[tmp_idx];

                mlt_buffer2[20*(i+q->js_subband_start) + j] = f2 * decode_buffer[tmp_idx];

            }

            idx = (1 << q->js_vlc_bits) - 1;

        }

    }

}

av_cold void ff_synth_filter_init(SynthFilterContext *c)

{

    c->synth_filter_float = synth_filter_float;



    if (ARCH_ARM) ff_synth_filter_init_arm(c);

    if (ARCH_X86) ff_synth_filter_init_x86(c);

}

int main(int argc, char** argv)

{

    FILE *f= fopen(argv[1], "rb+");

    int count= atoi(argv[2]);

    int maxburst= atoi(argv[3]);

    int length;



    srand (time (0));



    fseek(f, 0, SEEK_END);

    length= ftell(f);

    fseek(f, 0, SEEK_SET);



    while(count--){

        int burst= 1 + random() * (uint64_t) (abs(maxburst)-1) / RAND_MAX;

        int pos= random() * (uint64_t) length / RAND_MAX;

        fseek(f, pos, SEEK_SET);



        if(maxburst<0) burst= -maxburst;



        if(pos + burst > length)

            continue;



        while(burst--){

            int val= random() * 256ULL / RAND_MAX;



            if(maxburst<0) val=0;



            fwrite(&val, 1, 1, f);

        }

    }



    return 0;

}

static av_cold int oggvorbis_encode_init(AVCodecContext *avccontext)

{

    OggVorbisContext *context = avccontext->priv_data;

    ogg_packet header, header_comm, header_code;

    uint8_t *p;

    unsigned int offset;



    vorbis_info_init(&context->vi);

    if (oggvorbis_init_encoder(&context->vi, avccontext) < 0) {

        av_log(avccontext, AV_LOG_ERROR, "oggvorbis_encode_init: init_encoder failed\n");

        return -1;

    }

    vorbis_analysis_init(&context->vd, &context->vi);

    vorbis_block_init(&context->vd, &context->vb);



    vorbis_comment_init(&context->vc);

    vorbis_comment_add_tag(&context->vc, "encoder", LIBAVCODEC_IDENT);



    vorbis_analysis_headerout(&context->vd, &context->vc, &header,

                              &header_comm, &header_code);



    avccontext->extradata_size =

        1 + xiph_len(header.bytes) + xiph_len(header_comm.bytes) +

        header_code.bytes;

    p = avccontext->extradata =

            av_malloc(avccontext->extradata_size + FF_INPUT_BUFFER_PADDING_SIZE);

    p[0]    = 2;

    offset  = 1;

    offset += av_xiphlacing(&p[offset], header.bytes);

    offset += av_xiphlacing(&p[offset], header_comm.bytes);

    memcpy(&p[offset], header.packet, header.bytes);

    offset += header.bytes;

    memcpy(&p[offset], header_comm.packet, header_comm.bytes);

    offset += header_comm.bytes;

    memcpy(&p[offset], header_code.packet, header_code.bytes);

    offset += header_code.bytes;

    assert(offset == avccontext->extradata_size);



#if 0

    vorbis_block_clear(&context->vb);

    vorbis_dsp_clear(&context->vd);

    vorbis_info_clear(&context->vi);

#endif

    vorbis_comment_clear(&context->vc);



    avccontext->frame_size = OGGVORBIS_FRAME_SIZE;



    avccontext->coded_frame = avcodec_alloc_frame();



    return 0;

}

static int iff_read_header(AVFormatContext *s)

{

    IffDemuxContext *iff = s->priv_data;

    AVIOContext *pb = s->pb;

    AVStream *st;

    uint8_t *buf;

    uint32_t chunk_id, data_size;

    uint32_t screenmode = 0, num, den;

    unsigned transparency = 0;

    unsigned masking = 0; // no mask

    uint8_t fmt[16];

    int fmt_size;



    st = avformat_new_stream(s, NULL);

    if (!st)

        return AVERROR(ENOMEM);



    st->codec->channels = 1;

    st->codec->channel_layout = AV_CH_LAYOUT_MONO;

    avio_skip(pb, 8);

    // codec_tag used by ByteRun1 decoder to distinguish progressive (PBM) and interlaced (ILBM) content

    st->codec->codec_tag = avio_rl32(pb);



    while(!url_feof(pb)) {

        uint64_t orig_pos;

        int res;

        const char *metadata_tag = NULL;

        chunk_id = avio_rl32(pb);

        data_size = avio_rb32(pb);

        orig_pos = avio_tell(pb);



        switch(chunk_id) {

        case ID_VHDR:

            st->codec->codec_type = AVMEDIA_TYPE_AUDIO;



            if (data_size < 14)

                return AVERROR_INVALIDDATA;

            avio_skip(pb, 12);

            st->codec->sample_rate = avio_rb16(pb);

            if (data_size >= 16) {

                avio_skip(pb, 1);

                iff->svx8_compression = avio_r8(pb);

            }

            break;



        case ID_MHDR:

            st->codec->codec_type = AVMEDIA_TYPE_AUDIO;



            iff->maud_bits = -1;

            iff->maud_compression = -1;

            if (data_size < 32)

                return AVERROR_INVALIDDATA;

            avio_skip(pb, 4);

            iff->maud_bits = avio_rb16(pb);

            avio_skip(pb, 2);

            num = avio_rb32(pb);

            den = avio_rb16(pb);

            if (!den)

                return AVERROR_INVALIDDATA;

            avio_skip(pb, 2);

            st->codec->sample_rate = num / den;

            st->codec->channels = avio_rb16(pb);

            iff->maud_compression = avio_rb16(pb);

            if (st->codec->channels == 1)

                st->codec->channel_layout = AV_CH_LAYOUT_MONO;

            else if (st->codec->channels == 2)

                st->codec->channel_layout = AV_CH_LAYOUT_STEREO;

            break;



        case ID_ABIT:

        case ID_BODY:

        case ID_DBOD:

        case ID_MDAT:

            iff->body_pos = avio_tell(pb);

            iff->body_size = data_size;

            break;



        case ID_CHAN:

            if (data_size < 4)

                return AVERROR_INVALIDDATA;

            if (avio_rb32(pb) < 6) {

                st->codec->channels       = 1;

                st->codec->channel_layout = AV_CH_LAYOUT_MONO;

            } else {

                st->codec->channels       = 2;

                st->codec->channel_layout = AV_CH_LAYOUT_STEREO;

            }

            break;



        case ID_CAMG:

            if (data_size < 4)

                return AVERROR_INVALIDDATA;

            screenmode                = avio_rb32(pb);

            break;



        case ID_CMAP:

            st->codec->extradata_size = data_size + IFF_EXTRA_VIDEO_SIZE;

            st->codec->extradata      = av_malloc(data_size + IFF_EXTRA_VIDEO_SIZE + FF_INPUT_BUFFER_PADDING_SIZE);

            if (!st->codec->extradata)

                return AVERROR(ENOMEM);

            if (avio_read(pb, st->codec->extradata + IFF_EXTRA_VIDEO_SIZE, data_size) < 0)

                return AVERROR(EIO);

            break;



        case ID_BMHD:

            iff->bitmap_compression = -1;

            st->codec->codec_type            = AVMEDIA_TYPE_VIDEO;

            if (data_size <= 8)

                return AVERROR_INVALIDDATA;

            st->codec->width                 = avio_rb16(pb);

            st->codec->height                = avio_rb16(pb);

            avio_skip(pb, 4); // x, y offset

            st->codec->bits_per_coded_sample = avio_r8(pb);

            if (data_size >= 10)

                masking                      = avio_r8(pb);

            if (data_size >= 11)

                iff->bitmap_compression      = avio_r8(pb);

            if (data_size >= 14) {

                avio_skip(pb, 1); // padding

                transparency                 = avio_rb16(pb);

            }

            if (data_size >= 16) {

                st->sample_aspect_ratio.num  = avio_r8(pb);

                st->sample_aspect_ratio.den  = avio_r8(pb);

            }

            break;



        case ID_DPEL:

            if (data_size < 4 || (data_size & 3))

                return AVERROR_INVALIDDATA;

            if ((fmt_size = avio_read(pb, fmt, sizeof(fmt))) < 0)

                return fmt_size;

            if (fmt_size == sizeof(deep_rgb24) && !memcmp(fmt, deep_rgb24, sizeof(deep_rgb24)))

                st->codec->pix_fmt = AV_PIX_FMT_RGB24;

            else if (fmt_size == sizeof(deep_rgba) && !memcmp(fmt, deep_rgba, sizeof(deep_rgba)))

                st->codec->pix_fmt = AV_PIX_FMT_RGBA;

            else if (fmt_size == sizeof(deep_bgra) && !memcmp(fmt, deep_bgra, sizeof(deep_bgra)))

                st->codec->pix_fmt = AV_PIX_FMT_BGRA;

            else if (fmt_size == sizeof(deep_argb) && !memcmp(fmt, deep_argb, sizeof(deep_argb)))

                st->codec->pix_fmt = AV_PIX_FMT_ARGB;

            else if (fmt_size == sizeof(deep_abgr) && !memcmp(fmt, deep_abgr, sizeof(deep_abgr)))

                st->codec->pix_fmt = AV_PIX_FMT_ABGR;

            else {

                av_log_ask_for_sample(s, "unsupported color format\n");

                return AVERROR_PATCHWELCOME;

            }

            break;



        case ID_DGBL:

            st->codec->codec_type            = AVMEDIA_TYPE_VIDEO;

            if (data_size < 8)

                return AVERROR_INVALIDDATA;

            st->codec->width                 = avio_rb16(pb);

            st->codec->height                = avio_rb16(pb);

            iff->bitmap_compression          = avio_rb16(pb);

            st->sample_aspect_ratio.num      = avio_r8(pb);

            st->sample_aspect_ratio.den      = avio_r8(pb);

            st->codec->bits_per_coded_sample = 24;

            break;



        case ID_DLOC:

            if (data_size < 4)

                return AVERROR_INVALIDDATA;

            st->codec->width  = avio_rb16(pb);

            st->codec->height = avio_rb16(pb);

            break;



        case ID_ANNO:

        case ID_TEXT:      metadata_tag = "comment";   break;

        case ID_AUTH:      metadata_tag = "artist";    break;

        case ID_COPYRIGHT: metadata_tag = "copyright"; break;

        case ID_NAME:      metadata_tag = "title";     break;

        }



        if (metadata_tag) {

            if ((res = get_metadata(s, metadata_tag, data_size)) < 0) {

                av_log(s, AV_LOG_ERROR, "cannot allocate metadata tag %s!\n", metadata_tag);

                return res;

            }

        }

        avio_skip(pb, data_size - (avio_tell(pb) - orig_pos) + (data_size & 1));

    }



    avio_seek(pb, iff->body_pos, SEEK_SET);



    switch(st->codec->codec_type) {

    case AVMEDIA_TYPE_AUDIO:

        avpriv_set_pts_info(st, 32, 1, st->codec->sample_rate);



        if (st->codec->codec_tag == ID_16SV)

            st->codec->codec_id = AV_CODEC_ID_PCM_S16BE_PLANAR;

        else if (st->codec->codec_tag == ID_MAUD) {

            if (iff->maud_bits == 8 && !iff->maud_compression) {

                st->codec->codec_id = AV_CODEC_ID_PCM_U8;

            } else if (iff->maud_bits == 16 && !iff->maud_compression) {

                st->codec->codec_id = AV_CODEC_ID_PCM_S16BE;

            } else if (iff->maud_bits ==  8 && iff->maud_compression == 2) {

                st->codec->codec_id = AV_CODEC_ID_PCM_ALAW;

            } else if (iff->maud_bits ==  8 && iff->maud_compression == 3) {

                st->codec->codec_id = AV_CODEC_ID_PCM_MULAW;

            } else {

                av_log_ask_for_sample(s, "unsupported compression %d and bit depth %d\n", iff->maud_compression, iff->maud_bits);

                return AVERROR_PATCHWELCOME;

            }



            st->codec->bits_per_coded_sample =

                av_get_bits_per_sample(st->codec->codec_id);



            st->codec->block_align =

                st->codec->bits_per_coded_sample * st->codec->channels / 8;

        } else {

        switch (iff->svx8_compression) {

        case COMP_NONE:

            st->codec->codec_id = AV_CODEC_ID_PCM_S8_PLANAR;

            break;

        case COMP_FIB:

            st->codec->codec_id = AV_CODEC_ID_8SVX_FIB;

            break;

        case COMP_EXP:

            st->codec->codec_id = AV_CODEC_ID_8SVX_EXP;

            break;

        default:

            av_log(s, AV_LOG_ERROR,

                   "Unknown SVX8 compression method '%d'\n", iff->svx8_compression);

            return -1;

        }

        }



        st->codec->bits_per_coded_sample = av_get_bits_per_sample(st->codec->codec_id);

        st->codec->bit_rate = st->codec->channels * st->codec->sample_rate * st->codec->bits_per_coded_sample;

        st->codec->block_align = st->codec->channels * st->codec->bits_per_coded_sample;

        break;



    case AVMEDIA_TYPE_VIDEO:

        iff->bpp          = st->codec->bits_per_coded_sample;

        if ((screenmode & 0x800 /* Hold And Modify */) && iff->bpp <= 8) {

            iff->ham      = iff->bpp > 6 ? 6 : 4;

            st->codec->bits_per_coded_sample = 24;

        }

        iff->flags        = (screenmode & 0x80 /* Extra HalfBrite */) && iff->bpp <= 8;

        iff->masking      = masking;

        iff->transparency = transparency;



        if (!st->codec->extradata) {

            st->codec->extradata_size = IFF_EXTRA_VIDEO_SIZE;

            st->codec->extradata      = av_malloc(IFF_EXTRA_VIDEO_SIZE + FF_INPUT_BUFFER_PADDING_SIZE);

            if (!st->codec->extradata)

                return AVERROR(ENOMEM);

        }

        buf = st->codec->extradata;

        bytestream_put_be16(&buf, IFF_EXTRA_VIDEO_SIZE);

        bytestream_put_byte(&buf, iff->bitmap_compression);

        bytestream_put_byte(&buf, iff->bpp);

        bytestream_put_byte(&buf, iff->ham);

        bytestream_put_byte(&buf, iff->flags);

        bytestream_put_be16(&buf, iff->transparency);

        bytestream_put_byte(&buf, iff->masking);

        st->codec->codec_id = AV_CODEC_ID_IFF_ILBM;

        break;

    default:

        return -1;

    }



    return 0;

}

static int unpack_modes(Vp3DecodeContext *s, GetBitContext *gb)

{

    int i, j, k;

    int scheme;

    int current_macroblock;

    int current_fragment;

    int coding_mode;

    int custom_mode_alphabet[CODING_MODE_COUNT];



    if (s->keyframe) {

        for (i = 0; i < s->fragment_count; i++)

            s->all_fragments[i].coding_method = MODE_INTRA;



    } else {



        /* fetch the mode coding scheme for this frame */

        scheme = get_bits(gb, 3);



        /* is it a custom coding scheme? */

        if (scheme == 0) {




                custom_mode_alphabet[get_bits(gb, 3)] = i;

        }



        /* iterate through all of the macroblocks that contain 1 or more

         * coded fragments */

        for (i = 0; i < s->u_superblock_start; i++) {



            for (j = 0; j < 4; j++) {

                current_macroblock = s->superblock_macroblocks[i * 4 + j];

                if ((current_macroblock == -1) ||

                    (s->macroblock_coding[current_macroblock] == MODE_COPY))

                    continue;

                if (current_macroblock >= s->macroblock_count) {

                    av_log(s->avctx, AV_LOG_ERROR, "  vp3:unpack_modes(): bad macroblock number (%d >= %d)\n",

                        current_macroblock, s->macroblock_count);

                    return 1;

                }



                /* mode 7 means get 3 bits for each coding mode */

                if (scheme == 7)

                    coding_mode = get_bits(gb, 3);

                else if(scheme == 0)

                    coding_mode = custom_mode_alphabet

                        [get_vlc2(gb, s->mode_code_vlc.table, 3, 3)];

                else

                    coding_mode = ModeAlphabet[scheme-1]

                        [get_vlc2(gb, s->mode_code_vlc.table, 3, 3)];



                s->macroblock_coding[current_macroblock] = coding_mode;

                for (k = 0; k < 6; k++) {

                    current_fragment =

                        s->macroblock_fragments[current_macroblock * 6 + k];

                    if (current_fragment == -1)

                        continue;

                    if (current_fragment >= s->fragment_count) {

                        av_log(s->avctx, AV_LOG_ERROR, "  vp3:unpack_modes(): bad fragment number (%d >= %d)\n",

                            current_fragment, s->fragment_count);

                        return 1;

                    }

                    if (s->all_fragments[current_fragment].coding_method !=

                        MODE_COPY)

                        s->all_fragments[current_fragment].coding_method =

                            coding_mode;

                }

            }

        }

    }



    return 0;

}

static int vpx_decode(AVCodecContext *avctx,

                      void *data, int *got_frame, AVPacket *avpkt)

{

    VPxContext *ctx = avctx->priv_data;

    AVFrame *picture = data;

    const void *iter = NULL;

    const void *iter_alpha = NULL;

    struct vpx_image *img, *img_alpha;

    int ret;

    uint8_t *side_data = NULL;

    int side_data_size = 0;



    ret = decode_frame(avctx, &ctx->decoder, avpkt->data, avpkt->size);

    if (ret)

        return ret;



    side_data = av_packet_get_side_data(avpkt,

                                        AV_PKT_DATA_MATROSKA_BLOCKADDITIONAL,

                                        &side_data_size);

    if (side_data_size > 1) {

        const uint64_t additional_id = AV_RB64(side_data);

        side_data += 8;

        side_data_size -= 8;

        if (additional_id == 1) {  // 1 stands for alpha channel data.

            if (!ctx->has_alpha_channel) {

                ctx->has_alpha_channel = 1;

                ret = vpx_init(avctx,

#if CONFIG_LIBVPX_VP8_DECODER && CONFIG_LIBVPX_VP9_DECODER

                               (avctx->codec_id == AV_CODEC_ID_VP8) ?

                               &vpx_codec_vp8_dx_algo : &vpx_codec_vp9_dx_algo,

#elif CONFIG_LIBVPX_VP8_DECODER

                               &vpx_codec_vp8_dx_algo,

#else

                               &vpx_codec_vp9_dx_algo,

#endif

                               1);

                if (ret)

                    return ret;

            }

            ret = decode_frame(avctx, &ctx->decoder_alpha, side_data,

                               side_data_size);

            if (ret)

                return ret;

        }

    }



    if ((img = vpx_codec_get_frame(&ctx->decoder, &iter)) &&

        (!ctx->has_alpha_channel ||

         (img_alpha = vpx_codec_get_frame(&ctx->decoder_alpha, &iter_alpha)))) {

        uint8_t *planes[4];

        int linesizes[4];



        if (img->d_w > img->w || img->d_h > img->h) {

            av_log(avctx, AV_LOG_ERROR, "Display dimensions %dx%d exceed storage %dx%d\n",

                   img->d_w, img->d_h, img->w, img->h);

            return AVERROR_EXTERNAL;

        }



        if ((ret = set_pix_fmt(avctx, img, ctx->has_alpha_channel)) < 0) {

#ifdef VPX_IMG_FMT_HIGHBITDEPTH

            av_log(avctx, AV_LOG_ERROR, "Unsupported output colorspace (%d) / bit_depth (%d)\n",

                   img->fmt, img->bit_depth);

#else

            av_log(avctx, AV_LOG_ERROR, "Unsupported output colorspace (%d) / bit_depth (%d)\n",

                   img->fmt, 8);

#endif

            return ret;

        }



        if ((int) img->d_w != avctx->width || (int) img->d_h != avctx->height) {

            av_log(avctx, AV_LOG_INFO, "dimension change! %dx%d -> %dx%d\n",

                   avctx->width, avctx->height, img->d_w, img->d_h);

            ret = ff_set_dimensions(avctx, img->d_w, img->d_h);

            if (ret < 0)

                return ret;

        }

        if ((ret = ff_get_buffer(avctx, picture, 0)) < 0)

            return ret;



        planes[0] = img->planes[VPX_PLANE_Y];

        planes[1] = img->planes[VPX_PLANE_U];

        planes[2] = img->planes[VPX_PLANE_V];

        planes[3] =

            ctx->has_alpha_channel ? img_alpha->planes[VPX_PLANE_Y] : NULL;

        linesizes[0] = img->stride[VPX_PLANE_Y];

        linesizes[1] = img->stride[VPX_PLANE_U];

        linesizes[2] = img->stride[VPX_PLANE_V];

        linesizes[3] =

            ctx->has_alpha_channel ? img_alpha->stride[VPX_PLANE_Y] : 0;

        av_image_copy(picture->data, picture->linesize, (const uint8_t**)planes,

                      linesizes, avctx->pix_fmt, img->d_w, img->d_h);

        *got_frame           = 1;

    }

    return avpkt->size;

}

static int ipvideo_decode_block_opcode_0xB(IpvideoContext *s)

{

    int y;



    /* 64-color encoding (each pixel in block is a different color) */

    CHECK_STREAM_PTR(64);



    for (y = 0; y < 8; y++) {

        memcpy(s->pixel_ptr, s->stream_ptr, 8);

        s->stream_ptr += 8;

        s->pixel_ptr  += s->stride;

    }



    /* report success */

    return 0;

}

static int mov_read_tkhd(MOVContext *c, AVIOContext *pb, MOVAtom atom)

{

    int i;

    int width;

    int height;

    int64_t disp_transform[2];

    int display_matrix[3][3];

    AVStream *st;

    MOVStreamContext *sc;

    int version;

    int flags;



    if (c->fc->nb_streams < 1)

        return 0;

    st = c->fc->streams[c->fc->nb_streams-1];

    sc = st->priv_data;



    version = avio_r8(pb);

    flags = avio_rb24(pb);

    st->disposition |= (flags & MOV_TKHD_FLAG_ENABLED) ? AV_DISPOSITION_DEFAULT : 0;



    if (version == 1) {

        avio_rb64(pb);

        avio_rb64(pb);

    } else {

        avio_rb32(pb); /* creation time */

        avio_rb32(pb); /* modification time */

    }

    st->id = (int)avio_rb32(pb); /* track id (NOT 0 !)*/

    avio_rb32(pb); /* reserved */



    /* highlevel (considering edits) duration in movie timebase */

    (version == 1) ? avio_rb64(pb) : avio_rb32(pb);

    avio_rb32(pb); /* reserved */

    avio_rb32(pb); /* reserved */



    avio_rb16(pb); /* layer */

    avio_rb16(pb); /* alternate group */

    avio_rb16(pb); /* volume */

    avio_rb16(pb); /* reserved */



    //read in the display matrix (outlined in ISO 14496-12, Section 6.2.2)

    // they're kept in fixed point format through all calculations

    // save u,v,z to store the whole matrix in the AV_PKT_DATA_DISPLAYMATRIX

    // side data, but the scale factor is not needed to calculate aspect ratio

    for (i = 0; i < 3; i++) {

        display_matrix[i][0] = avio_rb32(pb);   // 16.16 fixed point

        display_matrix[i][1] = avio_rb32(pb);   // 16.16 fixed point

        display_matrix[i][2] = avio_rb32(pb);   //  2.30 fixed point

    }



    width = avio_rb32(pb);       // 16.16 fixed point track width

    height = avio_rb32(pb);      // 16.16 fixed point track height

    sc->width = width >> 16;

    sc->height = height >> 16;



    // save the matrix when it is not the default identity

    if (display_matrix[0][0] != (1 << 16) ||

        display_matrix[1][1] != (1 << 16) ||

        display_matrix[2][2] != (1 << 30) ||

        display_matrix[0][1] || display_matrix[0][2] ||

        display_matrix[1][0] || display_matrix[1][2] ||

        display_matrix[2][0] || display_matrix[2][1]) {

        int i, j;



        av_freep(&sc->display_matrix);

        sc->display_matrix = av_malloc(sizeof(int32_t) * 9);

        if (!sc->display_matrix)

            return AVERROR(ENOMEM);



        for (i = 0; i < 3; i++)

            for (j = 0; j < 3; j++)

                sc->display_matrix[i * 3 + j] = display_matrix[j][i];

    }



    // transform the display width/height according to the matrix

    // skip this if the rotation angle is 0 degrees

    // to keep the same scale, use [width height 1<<16]

    if (width && height && sc->display_matrix &&

        av_display_rotation_get(sc->display_matrix) != 0.0f) {

        for (i = 0; i < 2; i++)

            disp_transform[i] =

                (int64_t)  width  * display_matrix[0][i] +

                (int64_t)  height * display_matrix[1][i] +

                ((int64_t) display_matrix[2][i] << 16);



        //sample aspect ratio is new width/height divided by old width/height

        st->sample_aspect_ratio = av_d2q(

            ((double) disp_transform[0] * height) /

            ((double) disp_transform[1] * width), INT_MAX);

    }

    return 0;

}

uint8_t *av_packet_new_side_data(AVPacket *pkt, enum AVPacketSideDataType type,

                                 int size)

{

    int elems = pkt->side_data_elems;



    if ((unsigned)elems + 1 > INT_MAX / sizeof(*pkt->side_data))

        return NULL;

    if ((unsigned)size > INT_MAX - FF_INPUT_BUFFER_PADDING_SIZE)

        return NULL;



    pkt->side_data = av_realloc(pkt->side_data,

                                (elems + 1) * sizeof(*pkt->side_data));

    if (!pkt->side_data)

        return NULL;



    pkt->side_data[elems].data = av_malloc(size + FF_INPUT_BUFFER_PADDING_SIZE);

    if (!pkt->side_data[elems].data)

        return NULL;

    pkt->side_data[elems].size = size;

    pkt->side_data[elems].type = type;

    pkt->side_data_elems++;



    return pkt->side_data[elems].data;

}

static void rtsp_parse_transport(RTSPMessageHeader *reply, const char *p)

{

    char transport_protocol[16];

    char profile[16];

    char lower_transport[16];

    char parameter[16];

    RTSPTransportField *th;

    char buf[256];



    reply->nb_transports = 0;



    for(;;) {

        skip_spaces(&p);

        if (*p == '\0')

            break;



        th = &reply->transports[reply->nb_transports];



        get_word_sep(transport_protocol, sizeof(transport_protocol),

                     "/", &p);

        if (!strcasecmp (transport_protocol, "rtp")) {

            get_word_sep(profile, sizeof(profile), "/;,", &p);

            lower_transport[0] = '\0';

            /* rtp/avp/<protocol> */

            if (*p == '/') {

                get_word_sep(lower_transport, sizeof(lower_transport),

                             ";,", &p);

            }

            th->transport = RTSP_TRANSPORT_RTP;

        } else if (!strcasecmp (transport_protocol, "x-pn-tng") ||

                   !strcasecmp (transport_protocol, "x-real-rdt")) {

            /* x-pn-tng/<protocol> */

            get_word_sep(lower_transport, sizeof(lower_transport), "/;,", &p);

            profile[0] = '\0';

            th->transport = RTSP_TRANSPORT_RDT;

        }

        if (!strcasecmp(lower_transport, "TCP"))

            th->lower_transport = RTSP_LOWER_TRANSPORT_TCP;

        else

            th->lower_transport = RTSP_LOWER_TRANSPORT_UDP;



        if (*p == ';')

            p++;

        /* get each parameter */

        while (*p != '\0' && *p != ',') {

            get_word_sep(parameter, sizeof(parameter), "=;,", &p);

            if (!strcmp(parameter, "port")) {

                if (*p == '=') {

                    p++;

                    rtsp_parse_range(&th->port_min, &th->port_max, &p);

                }

            } else if (!strcmp(parameter, "client_port")) {

                if (*p == '=') {

                    p++;

                    rtsp_parse_range(&th->client_port_min,

                                     &th->client_port_max, &p);

                }

            } else if (!strcmp(parameter, "server_port")) {

                if (*p == '=') {

                    p++;

                    rtsp_parse_range(&th->server_port_min,

                                     &th->server_port_max, &p);

                }

            } else if (!strcmp(parameter, "interleaved")) {

                if (*p == '=') {

                    p++;

                    rtsp_parse_range(&th->interleaved_min,

                                     &th->interleaved_max, &p);

                }

            } else if (!strcmp(parameter, "multicast")) {

                if (th->lower_transport == RTSP_LOWER_TRANSPORT_UDP)

                    th->lower_transport = RTSP_LOWER_TRANSPORT_UDP_MULTICAST;

            } else if (!strcmp(parameter, "ttl")) {

                if (*p == '=') {

                    p++;

                    th->ttl = strtol(p, (char **)&p, 10);

                }

            } else if (!strcmp(parameter, "destination")) {

                struct in_addr ipaddr;



                if (*p == '=') {

                    p++;

                    get_word_sep(buf, sizeof(buf), ";,", &p);

                    if (inet_aton(buf, &ipaddr))

                        th->destination = ntohl(ipaddr.s_addr);

                }

            }

            while (*p != ';' && *p != '\0' && *p != ',')

                p++;

            if (*p == ';')

                p++;

        }

        if (*p == ',')

            p++;



        reply->nb_transports++;

    }

}

static int mov_write_avcc_tag(ByteIOContext *pb, MOVTrack *track)

{

    offset_t pos = url_ftell(pb);



    put_be32(pb, 0);

    put_tag(pb, "avcC");

    if (track->vosLen > 6) {

        /* check for h264 start code */

        if (AV_RB32(track->vosData) == 0x00000001) {

            uint8_t *buf, *end;

            uint32_t sps_size=0, pps_size=0;

            uint8_t *sps=0, *pps=0;



            avc_parse_nal_units(&track->vosData, &track->vosLen);

            buf = track->vosData;

            end = track->vosData + track->vosLen;



            /* look for sps and pps */

            while (buf < end) {

                unsigned int size;

                uint8_t nal_type;

                size = AV_RB32(buf);

                nal_type = buf[4] & 0x1f;

                if (nal_type == 7) { /* SPS */

                    sps = buf + 4;

                    sps_size = size;

                } else if (nal_type == 8) { /* PPS */

                    pps = buf + 4;

                    pps_size = size;

                }

                buf += size + 4;

            }

            assert(sps);

            assert(pps);



            put_byte(pb, 1); /* version */

            put_byte(pb, sps[1]); /* profile */

            put_byte(pb, sps[2]); /* profile compat */

            put_byte(pb, sps[3]); /* level */

            put_byte(pb, 0xff); /* 6 bits reserved (111111) + 2 bits nal size length - 1 (11) */

            put_byte(pb, 0xe1); /* 3 bits reserved (111) + 5 bits number of sps (00001) */



            put_be16(pb, sps_size);

            put_buffer(pb, sps, sps_size);

            put_byte(pb, 1); /* number of pps */

            put_be16(pb, pps_size);

            put_buffer(pb, pps, pps_size);

        } else {

            put_buffer(pb, track->vosData, track->vosLen);

        }

    }

    return updateSize(pb, pos);

}

static inline int compress_coeffs(int *coef, int order, int c_bits)

{

    int i, res = 0;

    const int low_idx   = c_bits ?  4 : 2;

    const int shift_val = c_bits ?  8 : 4;

    const int high_idx  = c_bits ? 11 : 5;

    for (i = 0; i < order; i++)

        if (coef[i] < low_idx || coef[i] > high_idx)

            res++;

    if (res == order)

        for (i = 0; i < order; i++)

            coef[i] -= (coef[i] > high_idx) ? shift_val : 0;

    return res == order;

}

