    char c;

    AVSubtitle *sub = data;

    const char *ptr = avpkt->data;

    AVBPrint buf;



    /* To be removed later */

    if (sscanf(ptr, "%*u:%*u:%*u.%*u,%*u:%*u:%*u.%*u%c", &c) == 1) {

        av_log(avctx, AV_LOG_ERROR, "AVPacket is not clean (contains timing "

               "information). You need to upgrade your libavformat or "

               "sanitize your packet.\n");

        return AVERROR_INVALIDDATA;

    }



    av_bprint_init(&buf, 0, AV_BPRINT_SIZE_UNLIMITED);

    // note: no need to rescale pts & duration since they are in the same

    // timebase as ASS (1/100)

    if (ptr && avpkt->size > 0 && !subviewer_event_to_ass(&buf, ptr))

        ff_ass_add_rect(sub, buf.str, avpkt->pts, avpkt->duration, 0);

    *got_sub_ptr = sub->num_rects > 0;

    av_bprint_finalize(&buf, NULL);

    return avpkt->size;

}

void ff_mpeg4_pred_ac(MpegEncContext *s, int16_t *block, int n, int dir)

{

    int i;

    int16_t *ac_val, *ac_val1;

    int8_t *const qscale_table = s->current_picture.qscale_table;



    /* find prediction */

    ac_val  = s->ac_val[0][0] + s->block_index[n] * 16;

    ac_val1 = ac_val;

    if (s->ac_pred) {

        if (dir == 0) {

            const int xy = s->mb_x - 1 + s->mb_y * s->mb_stride;

            /* left prediction */

            ac_val -= 16;



            if (s->mb_x == 0 || s->qscale == qscale_table[xy] ||

                n == 1 || n == 3) {

                /* same qscale */

                for (i = 1; i < 8; i++)

                    block[s->idsp.idct_permutation[i << 3]] += ac_val[i];

            } else {

                /* different qscale, we must rescale */

                for (i = 1; i < 8; i++)

                    block[s->idsp.idct_permutation[i << 3]] += ROUNDED_DIV(ac_val[i] * qscale_table[xy], s->qscale);

            }

        } else {

            const int xy = s->mb_x + s->mb_y * s->mb_stride - s->mb_stride;

            /* top prediction */

            ac_val -= 16 * s->block_wrap[n];



            if (s->mb_y == 0 || s->qscale == qscale_table[xy] ||

                n == 2 || n == 3) {

                /* same qscale */

                for (i = 1; i < 8; i++)

                    block[s->idsp.idct_permutation[i]] += ac_val[i + 8];

            } else {

                /* different qscale, we must rescale */

                for (i = 1; i < 8; i++)

                    block[s->idsp.idct_permutation[i]] += ROUNDED_DIV(ac_val[i + 8] * qscale_table[xy], s->qscale);

            }

        }

    }

    /* left copy */

    for (i = 1; i < 8; i++)

        ac_val1[i] = block[s->idsp.idct_permutation[i << 3]];



    /* top copy */

    for (i = 1; i < 8; i++)

        ac_val1[8 + i] = block[s->idsp.idct_permutation[i]];

}

static int standard_decode_picture_header(VC9Context *v)

{

    int status = 0;



    if (v->finterpflag) v->interpfrm = get_bits(&v->gb, 1);

    skip_bits(&v->gb, 2); //framecnt unused

    if (v->rangered) v->rangeredfrm = get_bits(&v->gb, 1);

    v->pict_type = get_bits(&v->gb, 1);

    if (v->avctx->max_b_frames && !v->pict_type)

    {

        if (get_bits(&v->gb, 1)) v->pict_type = I_TYPE;

        else v->pict_type = P_TYPE;

    }

    else v->pict_type++; //P_TYPE



    switch (v->pict_type)

    {

    case I_TYPE: status = decode_i_picture_header(v); break;

    case BI_TYPE: status = decode_b_picture_header(v); break;

    case P_TYPE: status = decode_p_picture_header(v); break;

    case B_TYPE: status = decode_b_picture_header(v); break;

    }



    if (status == FRAME_SKIPED)

    {

      av_log(v, AV_LOG_INFO, "Skipping frame...\n");

      return status;

    }



    /* AC/DC Syntax */

    v->transacfrm = get_bits(&v->gb, 1);

    if (v->transacfrm) v->transacfrm += get_bits(&v->gb, 1);

    if (v->pict_type == I_TYPE || v->pict_type == BI_TYPE)

    {

        v->transacfrm2 = get_bits(&v->gb, 1);

        if (v->transacfrm2) v->transacfrm2 += get_bits(&v->gb, 1);

    }

    v->transacdctab = get_bits(&v->gb, 1);



    return 0;

}

static void rtsp_cmd_setup(HTTPContext *c, const char *url, 

                           RTSPHeader *h)

{

    FFStream *stream;

    int stream_index, port;

    char buf[1024];

    char path1[1024];

    const char *path;

    HTTPContext *rtp_c;

    RTSPTransportField *th;

    struct sockaddr_in dest_addr;

    RTSPActionServerSetup setup;



    /* find which url is asked */

    url_split(NULL, 0, NULL, 0, NULL, path1, sizeof(path1), url);

    path = path1;

    if (*path == '/')

        path++;



    /* now check each stream */

    for(stream = first_stream; stream != NULL; stream = stream->next) {

        if (!stream->is_feed && stream->fmt == &rtp_mux) {

            /* accept aggregate filenames only if single stream */

            if (!strcmp(path, stream->filename)) {

                if (stream->nb_streams != 1) {

                    rtsp_reply_error(c, RTSP_STATUS_AGGREGATE);

                    return;

                }

                stream_index = 0;

                goto found;

            }



            for(stream_index = 0; stream_index < stream->nb_streams;

                stream_index++) {

                snprintf(buf, sizeof(buf), "%s/streamid=%d", 

                         stream->filename, stream_index);

                if (!strcmp(path, buf))

                    goto found;

            }

        }

    }

    /* no stream found */

    rtsp_reply_error(c, RTSP_STATUS_SERVICE); /* XXX: right error ? */

    return;

 found:



    /* generate session id if needed */

    if (h->session_id[0] == '\0') {

        snprintf(h->session_id, sizeof(h->session_id), 

                 "%08x%08x", (int)random(), (int)random());

    }



    /* find rtp session, and create it if none found */

    rtp_c = find_rtp_session(h->session_id);

    if (!rtp_c) {

        /* always prefer UDP */

        th = find_transport(h, RTSP_PROTOCOL_RTP_UDP);

        if (!th) {

            th = find_transport(h, RTSP_PROTOCOL_RTP_TCP);

            if (!th) {

                rtsp_reply_error(c, RTSP_STATUS_TRANSPORT);

                return;

            }

        }



        rtp_c = rtp_new_connection(&c->from_addr, stream, h->session_id,

                                   th->protocol);

        if (!rtp_c) {

            rtsp_reply_error(c, RTSP_STATUS_BANDWIDTH);

            return;

        }



        /* open input stream */

        if (open_input_stream(rtp_c, "") < 0) {

            rtsp_reply_error(c, RTSP_STATUS_INTERNAL);

            return;

        }

    }



    /* test if stream is OK (test needed because several SETUP needs

       to be done for a given file) */

    if (rtp_c->stream != stream) {

        rtsp_reply_error(c, RTSP_STATUS_SERVICE);

        return;

    }



    /* test if stream is already set up */

    if (rtp_c->rtp_ctx[stream_index]) {

        rtsp_reply_error(c, RTSP_STATUS_STATE);

        return;

    }



    /* check transport */

    th = find_transport(h, rtp_c->rtp_protocol);

    if (!th || (th->protocol == RTSP_PROTOCOL_RTP_UDP && 

                th->client_port_min <= 0)) {

        rtsp_reply_error(c, RTSP_STATUS_TRANSPORT);

        return;

    }



    /* setup default options */

    setup.transport_option[0] = '\0';

    dest_addr = rtp_c->from_addr;

    dest_addr.sin_port = htons(th->client_port_min);



    /* add transport option if needed */

    if (ff_rtsp_callback) {

        setup.ipaddr = ntohl(dest_addr.sin_addr.s_addr);

        if (ff_rtsp_callback(RTSP_ACTION_SERVER_SETUP, rtp_c->session_id, 

                             (char *)&setup, sizeof(setup),

                             stream->rtsp_option) < 0) {

            rtsp_reply_error(c, RTSP_STATUS_TRANSPORT);

            return;

        }

        dest_addr.sin_addr.s_addr = htonl(setup.ipaddr);

    }



    /* setup stream */

    if (rtp_new_av_stream(rtp_c, stream_index, &dest_addr, c) < 0) {

        rtsp_reply_error(c, RTSP_STATUS_TRANSPORT);

        return;

    }



    /* now everything is OK, so we can send the connection parameters */

    rtsp_reply_header(c, RTSP_STATUS_OK);

    /* session ID */

    url_fprintf(c->pb, "Session: %s\r\n", rtp_c->session_id);



    switch(rtp_c->rtp_protocol) {

    case RTSP_PROTOCOL_RTP_UDP:

        port = rtp_get_local_port(rtp_c->rtp_handles[stream_index]);

        url_fprintf(c->pb, "Transport: RTP/AVP/UDP;unicast;"

                    "client_port=%d-%d;server_port=%d-%d",

                    th->client_port_min, th->client_port_min + 1,

                    port, port + 1);

        break;

    case RTSP_PROTOCOL_RTP_TCP:

        url_fprintf(c->pb, "Transport: RTP/AVP/TCP;interleaved=%d-%d",

                    stream_index * 2, stream_index * 2 + 1);

        break;

    default:

        break;

    }

    if (setup.transport_option[0] != '\0') {

        url_fprintf(c->pb, ";%s", setup.transport_option);

    }

    url_fprintf(c->pb, "\r\n");





    url_fprintf(c->pb, "\r\n");

}

static int show_format(WriterContext *w, AVFormatContext *fmt_ctx)

{

    char val_str[128];

    int64_t size = fmt_ctx->pb ? avio_size(fmt_ctx->pb) : -1;

    int ret = 0;



    writer_print_section_header(w, SECTION_ID_FORMAT);

    print_str("filename",         fmt_ctx->filename);

    print_int("nb_streams",       fmt_ctx->nb_streams);

    print_int("nb_programs",      fmt_ctx->nb_programs);

    print_str("format_name",      fmt_ctx->iformat->name);

    if (!do_bitexact) {

        if (fmt_ctx->iformat->long_name) print_str    ("format_long_name", fmt_ctx->iformat->long_name);

        else                             print_str_opt("format_long_name", "unknown");

    }

    print_time("start_time",      fmt_ctx->start_time, &AV_TIME_BASE_Q);

    print_time("duration",        fmt_ctx->duration,   &AV_TIME_BASE_Q);

    if (size >= 0) print_val    ("size", size, unit_byte_str);

    else           print_str_opt("size", "N/A");

    if (fmt_ctx->bit_rate > 0) print_val    ("bit_rate", fmt_ctx->bit_rate, unit_bit_per_second_str);

    else                       print_str_opt("bit_rate", "N/A");

    print_int("probe_score", av_format_get_probe_score(fmt_ctx));

    ret = show_tags(w, fmt_ctx->metadata, SECTION_ID_FORMAT_TAGS);



    writer_print_section_footer(w);

    fflush(stdout);

    return ret;

}

int av_asrc_buffer_add_audio_buffer_ref(AVFilterContext *ctx,

                                        AVFilterBufferRef *samplesref,

                                        int av_unused flags)

{

    BufferSourceContext *abuffer = ctx->priv;

    AVFilterLink *link;

    int ret, logged = 0;



    if (av_fifo_space(abuffer->fifo) < sizeof(samplesref)) {

        av_log(ctx, AV_LOG_ERROR,

               "Buffering limit reached. Please consume some available frames "

               "before adding new ones.\n");

        return AVERROR(EINVAL);

    }



    // Normalize input



    link = ctx->outputs[0];

    if (samplesref->audio->sample_rate != link->sample_rate) {



        log_input_change(ctx, link, samplesref);

        logged = 1;



        abuffer->sample_rate = samplesref->audio->sample_rate;



        if (!abuffer->aresample) {

            ret = insert_filter(abuffer, link, &abuffer->aresample, "aresample");

            if (ret < 0) return ret;

        } else {

            link = abuffer->aresample->outputs[0];

            if (samplesref->audio->sample_rate == link->sample_rate)

                remove_filter(&abuffer->aresample);

            else

                if ((ret = reconfigure_filter(abuffer, abuffer->aresample)) < 0)

                    return ret;

        }

    }



    link = ctx->outputs[0];

    if (samplesref->format                != link->format         ||

        samplesref->audio->channel_layout != link->channel_layout ||

        samplesref->audio->planar         != link->planar) {



        if (!logged) log_input_change(ctx, link, samplesref);



        abuffer->sample_format  = samplesref->format;

        abuffer->channel_layout = samplesref->audio->channel_layout;

        abuffer->packing_format = samplesref->audio->planar;



        if (!abuffer->aconvert) {

            ret = insert_filter(abuffer, link, &abuffer->aconvert, "aconvert");

            if (ret < 0) return ret;

        } else {

            link = abuffer->aconvert->outputs[0];

            if (samplesref->format                == link->format         &&

                samplesref->audio->channel_layout == link->channel_layout &&

                samplesref->audio->planar         == link->planar

               )

                remove_filter(&abuffer->aconvert);

            else

                if ((ret = reconfigure_filter(abuffer, abuffer->aconvert)) < 0)

                    return ret;

        }

    }



    if (sizeof(samplesref) != av_fifo_generic_write(abuffer->fifo, &samplesref,

                                                    sizeof(samplesref), NULL)) {

        av_log(ctx, AV_LOG_ERROR, "Error while writing to FIFO\n");

        return AVERROR(EINVAL);

    }



    return 0;

}

static V4L2Buffer* v4l2_dequeue_v4l2buf(V4L2Context *ctx, int timeout)

{

    struct v4l2_plane planes[VIDEO_MAX_PLANES];

    struct v4l2_buffer buf = { 0 };

    V4L2Buffer* avbuf = NULL;

    struct pollfd pfd = {

        .events =  POLLIN | POLLRDNORM | POLLPRI | POLLOUT | POLLWRNORM, /* default blocking capture */

        .fd = ctx_to_m2mctx(ctx)->fd,

    };

    int ret;



    if (V4L2_TYPE_IS_OUTPUT(ctx->type))

        pfd.events =  POLLOUT | POLLWRNORM;



    for (;;) {

        ret = poll(&pfd, 1, timeout);

        if (ret > 0)

            break;

        if (errno == EINTR)

            continue;



        /* timeout is being used to indicate last valid bufer when draining */

        if (ctx_to_m2mctx(ctx)->draining)

            ctx->done = 1;



        return NULL;

    }



    /* 0. handle errors */

    if (pfd.revents & POLLERR) {

        av_log(logger(ctx), AV_LOG_WARNING, "%s POLLERR\n", ctx->name);

        return NULL;

    }



    /* 1. handle resolution changes */

    if (pfd.revents & POLLPRI) {

        ret = v4l2_handle_event(ctx);

        if (ret < 0) {

            /* if re-init failed, abort */

            ctx->done = EINVAL;

            return NULL;

        }

        if (ret) {

            /* if re-init was successful drop the buffer (if there was one)

             * since we had to reconfigure capture (unmap all buffers)

             */

            return NULL;

        }

    }



    /* 2. dequeue the buffer */

    if (pfd.revents & (POLLIN | POLLRDNORM | POLLOUT | POLLWRNORM)) {



        if (!V4L2_TYPE_IS_OUTPUT(ctx->type)) {

            /* there is a capture buffer ready */

            if (pfd.revents & (POLLIN | POLLRDNORM))

                goto dequeue;



            /* the driver is ready to accept more input; instead of waiting for the capture

             * buffer to complete we return NULL so input can proceed (we are single threaded)

             */

            if (pfd.revents & (POLLOUT | POLLWRNORM))

                return NULL;

        }



dequeue:

        memset(&buf, 0, sizeof(buf));

        buf.memory = V4L2_MEMORY_MMAP;

        buf.type = ctx->type;

        if (V4L2_TYPE_IS_MULTIPLANAR(ctx->type)) {

            memset(planes, 0, sizeof(planes));

            buf.length = VIDEO_MAX_PLANES;

            buf.m.planes = planes;

        }



        ret = ioctl(ctx_to_m2mctx(ctx)->fd, VIDIOC_DQBUF, &buf);

        if (ret) {

            if (errno != EAGAIN) {

                ctx->done = errno;

                if (errno != EPIPE)

                    av_log(logger(ctx), AV_LOG_DEBUG, "%s VIDIOC_DQBUF, errno (%s)\n",

                        ctx->name, av_err2str(AVERROR(errno)));

            }

        } else {

            avbuf = &ctx->buffers[buf.index];

            avbuf->status = V4L2BUF_AVAILABLE;

            avbuf->buf = buf;

            if (V4L2_TYPE_IS_MULTIPLANAR(ctx->type)) {

                memcpy(avbuf->planes, planes, sizeof(planes));

                avbuf->buf.m.planes = avbuf->planes;

            }

        }

    }



    return avbuf;

}

static int decode_extradata_ps(const uint8_t *data, int size, H264ParamSets *ps,

                               int is_avc, void *logctx)

{

    H2645Packet pkt = { 0 };

    int i, ret = 0;



    ret = ff_h2645_packet_split(&pkt, data, size, logctx, is_avc, 2, AV_CODEC_ID_H264);

    if (ret < 0) {

        ret = 0;

        goto fail;

    }



    for (i = 0; i < pkt.nb_nals; i++) {

        H2645NAL *nal = &pkt.nals[i];

        switch (nal->type) {

        case H264_NAL_SPS:

            ret = ff_h264_decode_seq_parameter_set(&nal->gb, logctx, ps, 0);

            if (ret < 0)

                goto fail;

            break;

        case H264_NAL_PPS:

            ret = ff_h264_decode_picture_parameter_set(&nal->gb, logctx, ps,

                                                       nal->size_bits);

            if (ret < 0)

                goto fail;

            break;

        default:

            av_log(logctx, AV_LOG_VERBOSE, "Ignoring NAL type %d in extradata\n",

                   nal->type);

            break;

        }

    }



fail:

    ff_h2645_packet_uninit(&pkt);

    return ret;

}

int ff_qsv_decode_init(AVCodecContext *avctx, QSVContext *q, mfxSession session)

{

    mfxVideoParam param = { { 0 } };

    int ret;



    q->async_fifo = av_fifo_alloc((1 + q->async_depth) *

                                  (sizeof(mfxSyncPoint) + sizeof(QSVFrame*)));

    if (!q->async_fifo)

        return AVERROR(ENOMEM);



    ret = qsv_init_session(avctx, q, session);

    if (ret < 0) {

        av_log(avctx, AV_LOG_ERROR, "Error initializing an MFX session\n");

        return ret;

    }





    ret = ff_qsv_codec_id_to_mfx(avctx->codec_id);

    if (ret < 0)

        return ret;



    param.mfx.CodecId      = ret;

    param.mfx.CodecProfile = avctx->profile;

    param.mfx.CodecLevel   = avctx->level;



    param.mfx.FrameInfo.BitDepthLuma   = 8;

    param.mfx.FrameInfo.BitDepthChroma = 8;

    param.mfx.FrameInfo.Shift          = 0;

    param.mfx.FrameInfo.FourCC         = MFX_FOURCC_NV12;

    param.mfx.FrameInfo.Width          = avctx->coded_width;

    param.mfx.FrameInfo.Height         = avctx->coded_height;

    param.mfx.FrameInfo.ChromaFormat   = MFX_CHROMAFORMAT_YUV420;



    param.IOPattern   = q->iopattern;

    param.AsyncDepth  = q->async_depth;

    param.ExtParam    = q->ext_buffers;

    param.NumExtParam = q->nb_ext_buffers;



    ret = MFXVideoDECODE_Init(q->session, &param);

    if (ret < 0) {

        av_log(avctx, AV_LOG_ERROR, "Error initializing the MFX video decoder\n");

        return ff_qsv_error(ret);

    }



    return 0;

}

