        break;

    case 5:

        s->decode_mb= wmv2_decode_mb;

        break;

    }



    s->slice_height= s->mb_height; //to avoid 1/0 if the first frame isnt a keyframe



    return 0;

}

static void start_frame_overlay(AVFilterLink *inlink, AVFilterBufferRef *inpicref)

{

    AVFilterContext *ctx = inlink->dst;

    OverlayContext *over = ctx->priv;



    inpicref->pts = av_rescale_q(inpicref->pts, ctx->inputs[OVERLAY]->time_base,

                                 ctx->outputs[0]->time_base);



    if (!over->overpicref) over->overpicref      = inpicref;

    else                   over->overpicref_next = inpicref;

}

static int cllc_decode_frame(AVCodecContext *avctx, void *data,

                             int *got_picture_ptr, AVPacket *avpkt)

{

    CLLCContext *ctx = avctx->priv_data;

    AVFrame *pic = avctx->coded_frame;

    uint8_t *src = avpkt->data;

    uint8_t *swapped_buf_new;

    uint32_t info_tag, info_offset;

    GetBitContext gb;

    int coding_type, ret;



    if (pic->data[0])

        avctx->release_buffer(avctx, pic);



    pic->reference = 0;



    /* Make sure our bswap16'd buffer is big enough */

    swapped_buf_new = av_fast_realloc(ctx->swapped_buf,

                                      &ctx->swapped_buf_size, avpkt->size);

    if (!swapped_buf_new) {

        av_log(avctx, AV_LOG_ERROR, "Could not realloc swapped buffer.\n");

        return AVERROR(ENOMEM);

    }

    ctx->swapped_buf = swapped_buf_new;



    /* Skip the INFO header if present */

    info_offset = 0;

    info_tag    = AV_RL32(src);

    if (info_tag == MKTAG('I', 'N', 'F', 'O')) {

        info_offset = AV_RL32(src + 4);

        if (info_offset > UINT32_MAX - 8 || info_offset + 8 > avpkt->size) {

            av_log(avctx, AV_LOG_ERROR,

                   "Invalid INFO header offset: 0x%08X is too large.\n",

                   info_offset);

            return AVERROR_INVALIDDATA;

        }



        info_offset += 8;

        src         += info_offset;



        av_log(avctx, AV_LOG_DEBUG, "Skipping INFO chunk.\n");

    }



    /* bswap16 the buffer since CLLC's bitreader works in 16-bit words */

    ctx->dsp.bswap16_buf((uint16_t *) ctx->swapped_buf, (uint16_t *) src,

                         (avpkt->size - info_offset) / 2);



    init_get_bits(&gb, ctx->swapped_buf, (avpkt->size - info_offset) * 8);



    /*

     * Read in coding type. The types are as follows:

     *

     * 0 - YUY2

     * 1 - BGR24 (Triples)

     * 2 - BGR24 (Quads)

     * 3 - BGRA

     */

    coding_type = (AV_RL32(src) >> 8) & 0xFF;

    av_log(avctx, AV_LOG_DEBUG, "Frame coding type: %d\n", coding_type);



    switch (coding_type) {

    case 1:

    case 2:

        avctx->pix_fmt             = PIX_FMT_RGB24;

        avctx->bits_per_raw_sample = 8;



        ret = avctx->get_buffer(avctx, pic);

        if (ret < 0) {

            av_log(avctx, AV_LOG_ERROR, "Could not allocate buffer.\n");

            return ret;

        }



        ret = decode_rgb24_frame(ctx, &gb, pic);

        if (ret < 0)

            return ret;



        break;

    case 3:

        avctx->pix_fmt             = PIX_FMT_ARGB;

        avctx->bits_per_raw_sample = 8;



        ret = avctx->get_buffer(avctx, pic);

        if (ret < 0) {

            av_log(avctx, AV_LOG_ERROR, "Could not allocate buffer.\n");

            return ret;

        }



        ret = decode_argb_frame(ctx, &gb, pic);

        if (ret < 0)

            return ret;



        break;

    default:

        av_log(avctx, AV_LOG_ERROR, "Unknown coding type: %d.\n", coding_type);

        return AVERROR_INVALIDDATA;

    }



    pic->key_frame = 1;

    pic->pict_type = AV_PICTURE_TYPE_I;



    *got_picture_ptr = 1;

    *(AVFrame *)data = *pic;



    return avpkt->size;

}

static int decode_frame(AVCodecContext *avctx, const uint8_t *databuf,

                        float **out_samples)

{

    ATRAC3Context *q = avctx->priv_data;

    int ret, i, ch;

    uint8_t *ptr1;



    if (q->coding_mode == JOINT_STEREO) {

        /* channel coupling mode */



        /* Decode sound unit pairs (channels are expected to be even).

         * Multichannel joint stereo interleaves pairs (6ch: 2ch + 2ch + 2ch) */

        const uint8_t *js_databuf;

        int js_pair, js_block_align;



        js_block_align = (avctx->block_align / avctx->channels) * 2; /* block pair */



        for (ch = 0; ch < avctx->channels; ch = ch + 2) {

            js_pair = ch/2;

            js_databuf = databuf + js_pair * js_block_align; /* align to current pair */



            /* Set the bitstream reader at the start of first channel sound unit. */

            init_get_bits(&q->gb,

                          js_databuf, js_block_align * 8);



            /* decode Sound Unit 1 */

            ret = decode_channel_sound_unit(q, &q->gb, &q->units[ch],

                                            out_samples[ch], ch, JOINT_STEREO);

            if (ret != 0)

                return ret;



            /* Framedata of the su2 in the joint-stereo mode is encoded in

             * reverse byte order so we need to swap it first. */

            if (js_databuf == q->decoded_bytes_buffer) {

                uint8_t *ptr2 = q->decoded_bytes_buffer + js_block_align - 1;

                ptr1          = q->decoded_bytes_buffer;

                for (i = 0; i < js_block_align / 2; i++, ptr1++, ptr2--)

                    FFSWAP(uint8_t, *ptr1, *ptr2);

            } else {

                const uint8_t *ptr2 = js_databuf + js_block_align - 1;

                for (i = 0; i < js_block_align; i++)

                    q->decoded_bytes_buffer[i] = *ptr2--;

            }



            /* Skip the sync codes (0xF8). */

            ptr1 = q->decoded_bytes_buffer;

            for (i = 4; *ptr1 == 0xF8; i++, ptr1++) {

                if (i >= js_block_align)

                    return AVERROR_INVALIDDATA;

            }





            /* set the bitstream reader at the start of the second Sound Unit */

            init_get_bits8(&q->gb,

                           ptr1, q->decoded_bytes_buffer + js_block_align - ptr1);



            /* Fill the Weighting coeffs delay buffer */

            memmove(q->weighting_delay[js_pair], &q->weighting_delay[js_pair][2],

                    4 * sizeof(*q->weighting_delay[js_pair]));

            q->weighting_delay[js_pair][4] = get_bits1(&q->gb);

            q->weighting_delay[js_pair][5] = get_bits(&q->gb, 3);



            for (i = 0; i < 4; i++) {

                q->matrix_coeff_index_prev[js_pair][i] = q->matrix_coeff_index_now[js_pair][i];

                q->matrix_coeff_index_now[js_pair][i]  = q->matrix_coeff_index_next[js_pair][i];

                q->matrix_coeff_index_next[js_pair][i] = get_bits(&q->gb, 2);

            }



            /* Decode Sound Unit 2. */

            ret = decode_channel_sound_unit(q, &q->gb, &q->units[ch+1],

                                            out_samples[ch+1], ch+1, JOINT_STEREO);

            if (ret != 0)

                return ret;



            /* Reconstruct the channel coefficients. */

            reverse_matrixing(out_samples[ch], out_samples[ch+1],

                              q->matrix_coeff_index_prev[js_pair],

                              q->matrix_coeff_index_now[js_pair]);



            channel_weighting(out_samples[ch], out_samples[ch+1], q->weighting_delay[js_pair]);

        }

    } else {

        /* single channels */

        /* Decode the channel sound units. */

        for (i = 0; i < avctx->channels; i++) {

            /* Set the bitstream reader at the start of a channel sound unit. */

            init_get_bits(&q->gb,

                          databuf + i * avctx->block_align / avctx->channels,

                          avctx->block_align * 8 / avctx->channels);



            ret = decode_channel_sound_unit(q, &q->gb, &q->units[i],

                                            out_samples[i], i, q->coding_mode);

            if (ret != 0)

                return ret;

        }

    }



    /* Apply the iQMF synthesis filter. */

    for (i = 0; i < avctx->channels; i++) {

        float *p1 = out_samples[i];

        float *p2 = p1 + 256;

        float *p3 = p2 + 256;

        float *p4 = p3 + 256;

        ff_atrac_iqmf(p1, p2, 256, p1, q->units[i].delay_buf1, q->temp_buf);

        ff_atrac_iqmf(p4, p3, 256, p3, q->units[i].delay_buf2, q->temp_buf);

        ff_atrac_iqmf(p1, p3, 512, p1, q->units[i].delay_buf3, q->temp_buf);

    }



    return 0;

}

static void decode_refpass(Jpeg2000T1Context *t1, int width, int height,

                           int bpno, int vert_causal_ctx_csty_symbol)

{

    int phalf, nhalf;

    int y0, x, y;



    phalf = 1 << (bpno - 1);

    nhalf = -phalf;



    for (y0 = 0; y0 < height; y0 += 4)

        for (x = 0; x < width; x++)

            for (y = y0; y < height && y < y0 + 4; y++)

                if ((t1->flags[y + 1][x + 1] & (JPEG2000_T1_SIG | JPEG2000_T1_VIS)) == JPEG2000_T1_SIG) {

                    int flags_mask = (vert_causal_ctx_csty_symbol && y == y0 + 3) ?

                        ~(JPEG2000_T1_SIG_S | JPEG2000_T1_SIG_SW | JPEG2000_T1_SIG_SE | JPEG2000_T1_SGN_S) : -1;

                    int ctxno = ff_jpeg2000_getrefctxno(t1->flags[y + 1][x + 1] & flags_mask);

                    int r     = ff_mqc_decode(&t1->mqc,

                                              t1->mqc.cx_states + ctxno)

                                ? phalf : nhalf;

                    t1->data[y][x]          += t1->data[y][x] < 0 ? -r : r;

                    t1->flags[y + 1][x + 1] |= JPEG2000_T1_REF;

                }

}

static uint32_t find_subframe_rice_params(FlacEncodeContext *s,

                                          FlacSubframe *sub, int pred_order)

{

    int pmin = get_max_p_order(s->options.min_partition_order,

                               s->frame.blocksize, pred_order);

    int pmax = get_max_p_order(s->options.max_partition_order,

                               s->frame.blocksize, pred_order);



    uint32_t bits = 8 + pred_order * sub->obits + 2 + 4;

    if (sub->type == FLAC_SUBFRAME_LPC)

        bits += 4 + 5 + pred_order * s->options.lpc_coeff_precision;

    bits += calc_rice_params(&sub->rc, pmin, pmax, sub->residual,

                             s->frame.blocksize, pred_order);

    return bits;

}

static int mmap_start(AVFormatContext *ctx)

{

    struct video_data *s = ctx->priv_data;

    enum v4l2_buf_type type;

    int i, res;



    for (i = 0; i < s->buffers; i++) {

        struct v4l2_buffer buf;



        memset(&buf, 0, sizeof(struct v4l2_buffer));

        buf.type = V4L2_BUF_TYPE_VIDEO_CAPTURE;

        buf.memory = V4L2_MEMORY_MMAP;

        buf.index  = i;



        res = ioctl(s->fd, VIDIOC_QBUF, &buf);

        if (res < 0) {

            av_log(ctx, AV_LOG_ERROR, "ioctl(VIDIOC_QBUF): %s\n",

                   strerror(errno));



            return AVERROR(errno);

        }

    }



    type = V4L2_BUF_TYPE_VIDEO_CAPTURE;

    res = ioctl(s->fd, VIDIOC_STREAMON, &type);

    if (res < 0) {

        av_log(ctx, AV_LOG_ERROR, "ioctl(VIDIOC_STREAMON): %s\n",

               strerror(errno));



        return AVERROR(errno);

    }



    return 0;

}

static int mxf_parse_mpeg2_frame(AVFormatContext *s, AVStream *st, AVPacket *pkt, int *flags)

{

    MXFStreamContext *sc = st->priv_data;

    MXFContext *mxf = s->priv_data;

    uint32_t c = -1;

    int i;



    *flags = 0;



    for(i = 0; i < pkt->size - 4; i++) {

        c = (c<<8) + pkt->data[i];

        if (c == 0x1B5) {

            if (i + 2 < pkt->size && (pkt->data[i+1] & 0xf0) == 0x10) { // seq ext

                st->codec->profile = pkt->data[i+1] & 0x07;

                st->codec->level   = pkt->data[i+2] >> 4;

            } else if (i + 5 < pkt->size && (pkt->data[i+1] & 0xf0) == 0x80) { // pict coding ext

                sc->interlaced = !(pkt->data[i+5] & 0x80); // progressive frame

                break;

            }

        } else if (c == 0x1b8) { // gop

            if (i + 4 < pkt->size) {

                if (pkt->data[i+4]>>6 & 0x01) // closed

                    *flags |= 0x80; // random access

                if (!mxf->header_written) {

                    unsigned hours   =  (pkt->data[i+1]>>2) & 0x1f;

                    unsigned minutes = ((pkt->data[i+1] & 0x03) << 4) | (pkt->data[i+2]>>4);

                    unsigned seconds = ((pkt->data[i+2] & 0x07) << 3) | (pkt->data[i+3]>>5);

                    unsigned frames  = ((pkt->data[i+3] & 0x1f) << 1) | (pkt->data[i+4]>>7);

                    mxf->timecode_drop_frame = !!(pkt->data[i+1] & 0x80);

                    mxf->timecode_start = (hours*3600 + minutes*60 + seconds) *

                        mxf->timecode_base + frames;

                    if (mxf->timecode_drop_frame) {

                        unsigned tminutes = 60 * hours + minutes;

                        mxf->timecode_start -= 2 * (tminutes - tminutes / 10);

                    }

                    av_log(s, AV_LOG_DEBUG, "frame %d %d:%d:%d%c%d\n", mxf->timecode_start,

                           hours, minutes, seconds, mxf->timecode_drop_frame ? ';':':', frames);

                }

            }

        } else if (c == 0x1b3) { // seq

            *flags |= 0x40;

            if (i + 4 < pkt->size) {

                switch ((pkt->data[i+4]>>4) & 0xf) {

                case 2:  sc->aspect_ratio = (AVRational){  4,  3}; break;

                case 3:  sc->aspect_ratio = (AVRational){ 16,  9}; break;

                case 4:  sc->aspect_ratio = (AVRational){221,100}; break;

                default:

                    av_reduce(&sc->aspect_ratio.num, &sc->aspect_ratio.den,

                              st->codec->width, st->codec->height, 1024*1024);

                }

            }

        } else if (c == 0x100) { // pic

            int pict_type = (pkt->data[i+2]>>3) & 0x07;

            if (pict_type == 2) { // P frame

                *flags |= 0x22;

                st->codec->gop_size = 1;

            } else if (pict_type == 3) { // B frame

                *flags |= 0x33;

                sc->temporal_reordering = -1;

            } else if (!pict_type) {

                av_log(s, AV_LOG_ERROR, "error parsing mpeg2 frame\n");

                return 0;

            }

        }

    }

    if (s->oformat != &mxf_d10_muxer)

        sc->codec_ul = mxf_get_mpeg2_codec_ul(st->codec);

    return !!sc->codec_ul;

}

int ffurl_register_protocol(URLProtocol *protocol)

{

    URLProtocol **p;

    p = &first_protocol;

    while (*p != NULL)

        p = &(*p)->next;

    *p             = protocol;

    protocol->next = NULL;

    return 0;

}

static av_cold int common_init(AVCodecContext *avctx){

    FFV1Context *s = avctx->priv_data;



    s->avctx= avctx;

    s->flags= avctx->flags;



    avcodec_get_frame_defaults(&s->picture);



    ff_dsputil_init(&s->dsp, avctx);



    s->width = avctx->width;

    s->height= avctx->height;



    assert(s->width && s->height);

    //defaults

    s->num_h_slices=1;

    s->num_v_slices=1;





    return 0;

}

static int dca_decode_frame(AVCodecContext * avctx,

                            void *data, int *data_size,

                            AVPacket *avpkt)

{

    const uint8_t *buf = avpkt->data;

    int buf_size = avpkt->size;



    int lfe_samples;

    int num_core_channels = 0;

    int i;

    float   *samples_flt = data;

    int16_t *samples_s16 = data;

    int out_size;

    DCAContext *s = avctx->priv_data;

    int channels;

    int core_ss_end;





    s->xch_present = 0;



    s->dca_buffer_size = dca_convert_bitstream(buf, buf_size, s->dca_buffer,

                                               DCA_MAX_FRAME_SIZE + DCA_MAX_EXSS_HEADER_SIZE);

    if (s->dca_buffer_size == AVERROR_INVALIDDATA) {

        av_log(avctx, AV_LOG_ERROR, "Not a valid DCA frame\n");

        return AVERROR_INVALIDDATA;

    }



    init_get_bits(&s->gb, s->dca_buffer, s->dca_buffer_size * 8);

    if (dca_parse_frame_header(s) < 0) {

        //seems like the frame is corrupt, try with the next one

        *data_size=0;

        return buf_size;

    }

    //set AVCodec values with parsed data

    avctx->sample_rate = s->sample_rate;

    avctx->bit_rate = s->bit_rate;

    avctx->frame_size = s->sample_blocks * 32;



    s->profile = FF_PROFILE_DTS;



    for (i = 0; i < (s->sample_blocks / 8); i++) {

        dca_decode_block(s, 0, i);

    }



    /* record number of core channels incase less than max channels are requested */

    num_core_channels = s->prim_channels;



    if (s->ext_coding)

        s->core_ext_mask = dca_ext_audio_descr_mask[s->ext_descr];

    else

        s->core_ext_mask = 0;



    core_ss_end = FFMIN(s->frame_size, s->dca_buffer_size) * 8;



    /* only scan for extensions if ext_descr was unknown or indicated a

     * supported XCh extension */

    if (s->core_ext_mask < 0 || s->core_ext_mask & DCA_EXT_XCH) {



        /* if ext_descr was unknown, clear s->core_ext_mask so that the

         * extensions scan can fill it up */

        s->core_ext_mask = FFMAX(s->core_ext_mask, 0);



        /* extensions start at 32-bit boundaries into bitstream */

        skip_bits_long(&s->gb, (-get_bits_count(&s->gb)) & 31);



    while(core_ss_end - get_bits_count(&s->gb) >= 32) {

        uint32_t bits = get_bits_long(&s->gb, 32);



        switch(bits) {

        case 0x5a5a5a5a: {

            int ext_amode, xch_fsize;



            s->xch_base_channel = s->prim_channels;



            /* validate sync word using XCHFSIZE field */

            xch_fsize = show_bits(&s->gb, 10);

            if((s->frame_size != (get_bits_count(&s->gb) >> 3) - 4 + xch_fsize) &&

               (s->frame_size != (get_bits_count(&s->gb) >> 3) - 4 + xch_fsize + 1))

                continue;



            /* skip length-to-end-of-frame field for the moment */

            skip_bits(&s->gb, 10);



            s->core_ext_mask |= DCA_EXT_XCH;



            /* extension amode should == 1, number of channels in extension */

            /* AFAIK XCh is not used for more channels */

            if ((ext_amode = get_bits(&s->gb, 4)) != 1) {

                av_log(avctx, AV_LOG_ERROR, "XCh extension amode %d not"

                       " supported!\n",ext_amode);

                continue;

            }



            /* much like core primary audio coding header */

            dca_parse_audio_coding_header(s, s->xch_base_channel);



            for (i = 0; i < (s->sample_blocks / 8); i++) {

                dca_decode_block(s, s->xch_base_channel, i);

            }



            s->xch_present = 1;

            break;

        }

        case 0x47004a03:

            /* XXCh: extended channels */

            /* usually found either in core or HD part in DTS-HD HRA streams,

             * but not in DTS-ES which contains XCh extensions instead */

            s->core_ext_mask |= DCA_EXT_XXCH;

            break;



        case 0x1d95f262: {

            int fsize96 = show_bits(&s->gb, 12) + 1;

            if (s->frame_size != (get_bits_count(&s->gb) >> 3) - 4 + fsize96)

                continue;



            av_log(avctx, AV_LOG_DEBUG, "X96 extension found at %d bits\n", get_bits_count(&s->gb));

            skip_bits(&s->gb, 12);

            av_log(avctx, AV_LOG_DEBUG, "FSIZE96 = %d bytes\n", fsize96);

            av_log(avctx, AV_LOG_DEBUG, "REVNO = %d\n", get_bits(&s->gb, 4));



            s->core_ext_mask |= DCA_EXT_X96;

            break;

        }

        }



        skip_bits_long(&s->gb, (-get_bits_count(&s->gb)) & 31);

    }



    } else {

        /* no supported extensions, skip the rest of the core substream */

        skip_bits_long(&s->gb, core_ss_end - get_bits_count(&s->gb));

    }



    if (s->core_ext_mask & DCA_EXT_X96)

        s->profile = FF_PROFILE_DTS_96_24;

    else if (s->core_ext_mask & (DCA_EXT_XCH | DCA_EXT_XXCH))

        s->profile = FF_PROFILE_DTS_ES;



    /* check for ExSS (HD part) */

    if (s->dca_buffer_size - s->frame_size > 32

        && get_bits_long(&s->gb, 32) == DCA_HD_MARKER)

        dca_exss_parse_header(s);



    avctx->profile = s->profile;



    channels = s->prim_channels + !!s->lfe;



    if (s->amode<16) {

        avctx->channel_layout = dca_core_channel_layout[s->amode];



        if (s->xch_present && (!avctx->request_channels ||

                               avctx->request_channels > num_core_channels + !!s->lfe)) {

            avctx->channel_layout |= AV_CH_BACK_CENTER;

            if (s->lfe) {

                avctx->channel_layout |= AV_CH_LOW_FREQUENCY;

                s->channel_order_tab = dca_channel_reorder_lfe_xch[s->amode];

            } else {

                s->channel_order_tab = dca_channel_reorder_nolfe_xch[s->amode];

            }

        } else {

            channels = num_core_channels + !!s->lfe;

            s->xch_present = 0; /* disable further xch processing */

            if (s->lfe) {

                avctx->channel_layout |= AV_CH_LOW_FREQUENCY;

                s->channel_order_tab = dca_channel_reorder_lfe[s->amode];

            } else

                s->channel_order_tab = dca_channel_reorder_nolfe[s->amode];

        }



        if (channels > !!s->lfe &&

            s->channel_order_tab[channels - 1 - !!s->lfe] < 0)

            return AVERROR_INVALIDDATA;



        if (avctx->request_channels == 2 && s->prim_channels > 2) {

            channels = 2;

            s->output = DCA_STEREO;

            avctx->channel_layout = AV_CH_LAYOUT_STEREO;

        }

    } else {

        av_log(avctx, AV_LOG_ERROR, "Non standard configuration %d !\n",s->amode);

        return AVERROR_INVALIDDATA;

    }





    /* There is nothing that prevents a dts frame to change channel configuration

       but Libav doesn't support that so only set the channels if it is previously

       unset. Ideally during the first probe for channels the crc should be checked

       and only set avctx->channels when the crc is ok. Right now the decoder could

       set the channels based on a broken first frame.*/

    if (s->is_channels_set == 0) {

        s->is_channels_set = 1;

        avctx->channels = channels;

    }

    if (avctx->channels != channels) {

        av_log(avctx, AV_LOG_ERROR, "DCA decoder does not support number of "

               "channels changing in stream. Skipping frame.\n");

        return AVERROR_PATCHWELCOME;

    }



    out_size = 256 / 8 * s->sample_blocks * channels *

               av_get_bytes_per_sample(avctx->sample_fmt);

    if (*data_size < out_size)

        return AVERROR(EINVAL);

    *data_size = out_size;



    /* filter to get final output */

    for (i = 0; i < (s->sample_blocks / 8); i++) {

        dca_filter_channels(s, i);



        /* If this was marked as a DTS-ES stream we need to subtract back- */

        /* channel from SL & SR to remove matrixed back-channel signal */

        if((s->source_pcm_res & 1) && s->xch_present) {

            float* back_chan = s->samples + s->channel_order_tab[s->xch_base_channel] * 256;

            float* lt_chan   = s->samples + s->channel_order_tab[s->xch_base_channel - 2] * 256;

            float* rt_chan   = s->samples + s->channel_order_tab[s->xch_base_channel - 1] * 256;

            s->dsp.vector_fmac_scalar(lt_chan, back_chan, -M_SQRT1_2, 256);

            s->dsp.vector_fmac_scalar(rt_chan, back_chan, -M_SQRT1_2, 256);

        }



        if (avctx->sample_fmt == AV_SAMPLE_FMT_FLT) {

            s->fmt_conv.float_interleave(samples_flt, s->samples_chanptr, 256,

                                         channels);

            samples_flt += 256 * channels;

        } else {

            s->fmt_conv.float_to_int16_interleave(samples_s16,

                                                  s->samples_chanptr, 256,

                                                  channels);

            samples_s16 += 256 * channels;

        }

    }



    /* update lfe history */

    lfe_samples = 2 * s->lfe * (s->sample_blocks / 8);

    for (i = 0; i < 2 * s->lfe * 4; i++) {

        s->lfe_data[i] = s->lfe_data[i + lfe_samples];

    }



    return buf_size;

}

static int find_slice_quant(AVCodecContext *avctx, const AVFrame *pic,

                            int trellis_node, int x, int y, int mbs_per_slice)

{

    ProresContext *ctx = avctx->priv_data;

    int i, q, pq, xp, yp;

    const uint16_t *src;

    int slice_width_factor = av_log2(mbs_per_slice);

    int num_cblocks[MAX_PLANES], pwidth;

    int plane_factor[MAX_PLANES], is_chroma[MAX_PLANES];

    const int min_quant = ctx->profile_info->min_quant;

    const int max_quant = ctx->profile_info->max_quant;

    int error, bits, bits_limit;

    int mbs, prev, cur, new_score;

    int slice_bits[TRELLIS_WIDTH], slice_score[TRELLIS_WIDTH];



    mbs = x + mbs_per_slice;



    for (i = 0; i < ctx->num_planes; i++) {

        is_chroma[i]    = (i == 1 || i == 2);

        plane_factor[i] = slice_width_factor + 2;

        if (is_chroma[i])

            plane_factor[i] += ctx->chroma_factor - 3;

        if (!is_chroma[i] || ctx->chroma_factor == CFACTOR_Y444) {

            xp             = x << 4;

            yp             = y << 4;

            num_cblocks[i] = 4;

            pwidth         = avctx->width;

        } else {

            xp             = x << 3;

            yp             = y << 4;

            num_cblocks[i] = 2;

            pwidth         = avctx->width >> 1;

        }

        src = (const uint16_t*)(pic->data[i] + yp * pic->linesize[i]) + xp;



        get_slice_data(ctx, src, pic->linesize[i], xp, yp,

                       pwidth, avctx->height, ctx->blocks[i],

                       mbs_per_slice, num_cblocks[i]);

    }



    for (q = min_quant; q <= max_quant; q++) {

        ctx->nodes[trellis_node + q].prev_node = -1;

        ctx->nodes[trellis_node + q].quant     = q;

    }



    // todo: maybe perform coarser quantising to fit into frame size when needed

    for (q = min_quant; q <= max_quant; q++) {

        bits  = 0;

        error = 0;

        for (i = 0; i < ctx->num_planes; i++) {

            bits += estimate_slice_plane(ctx, &error, i,

                                         src, pic->linesize[i],

                                         mbs_per_slice,

                                         num_cblocks[i], plane_factor[i],

                                         ctx->quants[q]);

        }

        if (bits > 65000 * 8) {

            error = SCORE_LIMIT;

            break;

        }

        slice_bits[q]  = bits;

        slice_score[q] = error;

    }



    bits_limit = mbs * ctx->bits_per_mb;

    for (pq = min_quant; pq <= max_quant; pq++) {

        prev = trellis_node - TRELLIS_WIDTH + pq;



        for (q = min_quant; q <= max_quant; q++) {

            cur = trellis_node + q;



            bits  = ctx->nodes[prev].bits + slice_bits[q];

            error = slice_score[q];

            if (bits > bits_limit)

                error = SCORE_LIMIT;



            if (ctx->nodes[prev].score < SCORE_LIMIT && error < SCORE_LIMIT)

                new_score = ctx->nodes[prev].score + error;

            else

                new_score = SCORE_LIMIT;

            if (ctx->nodes[cur].prev_node == -1 ||

                ctx->nodes[cur].score >= new_score) {



                ctx->nodes[cur].bits      = bits;

                ctx->nodes[cur].score     = new_score;

                ctx->nodes[cur].prev_node = prev;

            }

        }

    }



    error = ctx->nodes[trellis_node + min_quant].score;

    pq    = trellis_node + min_quant;

    for (q = min_quant + 1; q <= max_quant; q++) {

        if (ctx->nodes[trellis_node + q].score <= error) {

            error = ctx->nodes[trellis_node + q].score;

            pq    = trellis_node + q;

        }

    }



    return pq;

}

static int alac_decode_frame(AVCodecContext *avctx, void *data,

                             int *got_frame_ptr, AVPacket *avpkt)

{

    ALACContext *alac = avctx->priv_data;

    enum RawDataBlockType element;

    int channels;

    int ch, ret, got_end;



    init_get_bits(&alac->gb, avpkt->data, avpkt->size * 8);



    got_end = 0;

    alac->nb_samples = 0;

    ch = 0;

    while (get_bits_left(&alac->gb) >= 3) {

        element = get_bits(&alac->gb, 3);

        if (element == TYPE_END) {

            got_end = 1;

            break;

        }

        if (element > TYPE_CPE && element != TYPE_LFE) {

            av_log(avctx, AV_LOG_ERROR, "syntax element unsupported: %d\n", element);

            return AVERROR_PATCHWELCOME;

        }



        channels = (element == TYPE_CPE) ? 2 : 1;

        if (ch + channels > alac->channels) {

            av_log(avctx, AV_LOG_ERROR, "invalid element channel count\n");

            return AVERROR_INVALIDDATA;

        }



        ret = decode_element(avctx, data,

                             alac_channel_layout_offsets[alac->channels - 1][ch],

                             channels);

        if (ret < 0 && get_bits_left(&alac->gb))

            return ret;



        ch += channels;

    }

    if (!got_end) {

        av_log(avctx, AV_LOG_ERROR, "no end tag found. incomplete packet.\n");

        return AVERROR_INVALIDDATA;

    }



    if (avpkt->size * 8 - get_bits_count(&alac->gb) > 8) {

        av_log(avctx, AV_LOG_ERROR, "Error : %d bits left\n",

               avpkt->size * 8 - get_bits_count(&alac->gb));

    }



    *got_frame_ptr   = 1;

    *(AVFrame *)data = alac->frame;



    return avpkt->size;

}

static void update_stream_timings(AVFormatContext *ic)

{

    int64_t start_time, start_time1, start_time_text, end_time, end_time1;

    int64_t duration, duration1, filesize;

    int i;

    AVStream *st;

    AVProgram *p;



    start_time = INT64_MAX;

    start_time_text = INT64_MAX;

    end_time   = INT64_MIN;

    duration   = INT64_MIN;

    for (i = 0; i < ic->nb_streams; i++) {

        st = ic->streams[i];

        if (st->start_time != AV_NOPTS_VALUE && st->time_base.den) {

            start_time1 = av_rescale_q(st->start_time, st->time_base,

                                       AV_TIME_BASE_Q);

            if (st->codec->codec_type == AVMEDIA_TYPE_SUBTITLE || st->codec->codec_type == AVMEDIA_TYPE_DATA) {

                if (start_time1 < start_time_text)

                    start_time_text = start_time1;

            } else

                start_time = FFMIN(start_time, start_time1);

            end_time1   = AV_NOPTS_VALUE;

            if (st->duration != AV_NOPTS_VALUE) {

                end_time1 = start_time1 +

                            av_rescale_q(st->duration, st->time_base,

                                         AV_TIME_BASE_Q);

                end_time = FFMAX(end_time, end_time1);

            }

            for (p = NULL; (p = av_find_program_from_stream(ic, p, i)); ) {

                if (p->start_time == AV_NOPTS_VALUE || p->start_time > start_time1)

                    p->start_time = start_time1;

                if (p->end_time < end_time1)

                    p->end_time = end_time1;

            }

        }

        if (st->duration != AV_NOPTS_VALUE) {

            duration1 = av_rescale_q(st->duration, st->time_base,

                                     AV_TIME_BASE_Q);

            duration  = FFMAX(duration, duration1);

        }

    }

    if (start_time == INT64_MAX || (start_time > start_time_text && start_time - start_time_text < AV_TIME_BASE))

        start_time = start_time_text;

    else if (start_time > start_time_text)

        av_log(ic, AV_LOG_VERBOSE, "Ignoring outlier non primary stream starttime %f\n", start_time_text / (float)AV_TIME_BASE);



    if (start_time != INT64_MAX) {

        ic->start_time = start_time;

        if (end_time != INT64_MIN) {

            if (ic->nb_programs) {

                for (i = 0; i < ic->nb_programs; i++) {

                    p = ic->programs[i];

                    if (p->start_time != AV_NOPTS_VALUE && p->end_time > p->start_time)

                        duration = FFMAX(duration, p->end_time - p->start_time);

                }

            } else

                duration = FFMAX(duration, end_time - start_time);

        }

    }

    if (duration != INT64_MIN && duration > 0 && ic->duration == AV_NOPTS_VALUE) {

        ic->duration = duration;

    }

    if (ic->pb && (filesize = avio_size(ic->pb)) > 0 && ic->duration != AV_NOPTS_VALUE) {

        /* compute the bitrate */

        double bitrate = (double) filesize * 8.0 * AV_TIME_BASE /

                         (double) ic->duration;

        if (bitrate >= 0 && (!AV_HAVE_INCOMPATIBLE_LIBAV_ABI || bitrate <= INT_MAX))

            ic->bit_rate = bitrate;

    }

}

AVInputFormat *av_probe_input_format3(AVProbeData *pd, int is_opened,

                                      int *score_ret)

{

    AVProbeData lpd = *pd;

    AVInputFormat *fmt1 = NULL, *fmt;

    int score, nodat = 0, score_max = 0;

    const static uint8_t zerobuffer[AVPROBE_PADDING_SIZE];



    if (!lpd.buf)

        lpd.buf = zerobuffer;



    if (lpd.buf_size > 10 && ff_id3v2_match(lpd.buf, ID3v2_DEFAULT_MAGIC)) {

        int id3len = ff_id3v2_tag_len(lpd.buf);

        if (lpd.buf_size > id3len + 16) {

            lpd.buf      += id3len;

            lpd.buf_size -= id3len;

        } else

            nodat = 1;

    }



    fmt = NULL;

    while ((fmt1 = av_iformat_next(fmt1))) {

        if (!is_opened == !(fmt1->flags & AVFMT_NOFILE))

            continue;

        score = 0;

        if (fmt1->read_probe) {

            score = fmt1->read_probe(&lpd);

            if (fmt1->extensions && av_match_ext(lpd.filename, fmt1->extensions))

                score = FFMAX(score, nodat ? AVPROBE_SCORE_EXTENSION / 2 - 1 : 1);

        } else if (fmt1->extensions) {

            if (av_match_ext(lpd.filename, fmt1->extensions))

                score = AVPROBE_SCORE_EXTENSION;

        }

        if (score > score_max) {

            score_max = score;

            fmt       = fmt1;

        } else if (score == score_max)

            fmt = NULL;

    }

    if (nodat)

        score_max = FFMIN(AVPROBE_SCORE_EXTENSION / 2 - 1, score_max);

    *score_ret = score_max;



    return fmt;

}

static int rv34_decode_macroblock(RV34DecContext *r, int8_t *intra_types)

{

    MpegEncContext *s = &r->s;

    GetBitContext *gb = &s->gb;

    int cbp, cbp2;

    int i, blknum, blkoff;

    DCTELEM block16[64];

    int luma_dc_quant;

    int dist;

    int mb_pos = s->mb_x + s->mb_y * s->mb_stride;



    // Calculate which neighbours are available. Maybe it's worth optimizing too.

    memset(r->avail_cache, 0, sizeof(r->avail_cache));

    fill_rectangle(r->avail_cache + 5, 2, 2, 4, 1, 4);

    dist = (s->mb_x - s->resync_mb_x) + (s->mb_y - s->resync_mb_y) * s->mb_width;

    if(s->mb_x && dist)

        r->avail_cache[4] =

        r->avail_cache[8] = s->current_picture_ptr->mb_type[mb_pos - 1];

    if(dist >= s->mb_width)

        r->avail_cache[1] =

        r->avail_cache[2] = s->current_picture_ptr->mb_type[mb_pos - s->mb_stride];

    if(((s->mb_x+1) < s->mb_width) && dist >= s->mb_width - 1)

        r->avail_cache[3] = s->current_picture_ptr->mb_type[mb_pos - s->mb_stride + 1];

    if(s->mb_x && dist > s->mb_width)

        r->avail_cache[0] = s->current_picture_ptr->mb_type[mb_pos - s->mb_stride - 1];



    s->qscale = r->si.quant;

    cbp = cbp2 = rv34_decode_mb_header(r, intra_types);

    r->cbp_luma  [s->mb_x + s->mb_y * s->mb_stride] = cbp;

    r->cbp_chroma[s->mb_x + s->mb_y * s->mb_stride] = cbp >> 16;

    if(s->pict_type == FF_I_TYPE)

        r->deblock_coefs[mb_pos] = 0;

    else

        r->deblock_coefs[mb_pos] = rv34_set_deblock_coef(r);

    s->current_picture_ptr->qscale_table[s->mb_x + s->mb_y * s->mb_stride] = s->qscale;



    if(cbp == -1)

        return -1;



    luma_dc_quant = r->block_type == RV34_MB_P_MIX16x16 ? r->luma_dc_quant_p[s->qscale] : r->luma_dc_quant_i[s->qscale];

    if(r->is16){

        memset(block16, 0, sizeof(block16));

        rv34_decode_block(block16, gb, r->cur_vlcs, 3, 0);

        rv34_dequant4x4_16x16(block16, rv34_qscale_tab[luma_dc_quant],rv34_qscale_tab[s->qscale]);

        rv34_inv_transform_noround(block16);

    }



    for(i = 0; i < 16; i++, cbp >>= 1){

        if(!r->is16 && !(cbp & 1)) continue;

        blknum = ((i & 2) >> 1) + ((i & 8) >> 2);

        blkoff = ((i & 1) << 2) + ((i & 4) << 3);

        if(cbp & 1)

            rv34_decode_block(s->block[blknum] + blkoff, gb, r->cur_vlcs, r->luma_vlc, 0);

        rv34_dequant4x4(s->block[blknum] + blkoff, rv34_qscale_tab[s->qscale],rv34_qscale_tab[s->qscale]);

        if(r->is16) //FIXME: optimize

            s->block[blknum][blkoff] = block16[(i & 3) | ((i & 0xC) << 1)];

        rv34_inv_transform(s->block[blknum] + blkoff);

    }

    if(r->block_type == RV34_MB_P_MIX16x16)

        r->cur_vlcs = choose_vlc_set(r->si.quant, r->si.vlc_set, 1);

    for(; i < 24; i++, cbp >>= 1){

        if(!(cbp & 1)) continue;

        blknum = ((i & 4) >> 2) + 4;

        blkoff = ((i & 1) << 2) + ((i & 2) << 4);

        rv34_decode_block(s->block[blknum] + blkoff, gb, r->cur_vlcs, r->chroma_vlc, 1);

        rv34_dequant4x4(s->block[blknum] + blkoff, rv34_qscale_tab[rv34_chroma_quant[1][s->qscale]],rv34_qscale_tab[rv34_chroma_quant[0][s->qscale]]);

        rv34_inv_transform(s->block[blknum] + blkoff);

    }

    if(IS_INTRA(s->current_picture_ptr->mb_type[s->mb_x + s->mb_y*s->mb_stride]))

        rv34_output_macroblock(r, intra_types, cbp2, r->is16);

    else

        rv34_apply_differences(r, cbp2);



    return 0;

}

static int index_search_timestamp(AVIndexEntry *entries, 

                                  int nb_entries, int wanted_timestamp)

{

    int a, b, m;

    int64_t timestamp;



    if (nb_entries <= 0)

        return -1;



    a = 0;

    b = nb_entries - 1;

    while (a <= b) {

        m = (a + b) >> 1;

        timestamp = entries[m].timestamp;

        if (timestamp == wanted_timestamp)

            goto found;

        else if (timestamp > wanted_timestamp) {

            b = m - 1;

        } else {

            a = m + 1;

        }

    }

    m = a;

    if (m > 0)

        m--;

 found:

    return m;

}

void av_aes_crypt(AVAES *a, uint8_t *dst_, const uint8_t *src_,

                  int count, uint8_t *iv_, int decrypt)

{

    av_aes_block       *dst = (av_aes_block *) dst_;

    const av_aes_block *src = (const av_aes_block *) src_;

    av_aes_block        *iv = (av_aes_block *) iv_;



    while (count--) {

        addkey(&a->state[1], src, &a->round_key[a->rounds]);

        if (decrypt) {

            crypt(a, 0, inv_sbox, dec_multbl);

            if (iv) {

                addkey(&a->state[0], &a->state[0], iv);

                memcpy(iv, src, 16);

            }

            addkey(dst, &a->state[0], &a->round_key[0]);

        } else {

            if (iv)

                addkey(&a->state[1], &a->state[1], iv);

            crypt(a, 2, sbox, enc_multbl);

            addkey(dst, &a->state[0], &a->round_key[0]);

            if (iv)

                memcpy(iv, dst, 16);

        }

        src++;

        dst++;

    }

}

static int read_diff_float_data(ALSDecContext *ctx, unsigned int ra_frame) {

    AVCodecContext *avctx   = ctx->avctx;

    GetBitContext *gb       = &ctx->gb;

    SoftFloat_IEEE754 *acf  = ctx->acf;

    int *shift_value        = ctx->shift_value;

    int *last_shift_value   = ctx->last_shift_value;

    int *last_acf_mantissa  = ctx->last_acf_mantissa;

    int **raw_mantissa      = ctx->raw_mantissa;

    int *nbits              = ctx->nbits;

    unsigned char *larray   = ctx->larray;

    int frame_length        = ctx->cur_frame_length;

    SoftFloat_IEEE754 scale = av_int2sf_ieee754(0x1u, 23);

    unsigned int partA_flag;

    unsigned int highest_byte;

    unsigned int shift_amp;

    uint32_t tmp_32;

    int use_acf;

    int nchars;

    int i;

    int c;

    long k;

    long nbits_aligned;

    unsigned long acc;

    unsigned long j;

    uint32_t sign;

    uint32_t e;

    uint32_t mantissa;



    skip_bits_long(gb, 32); //num_bytes_diff_float

    use_acf = get_bits1(gb);



    if (ra_frame) {

        memset(last_acf_mantissa, 0, avctx->channels * sizeof(*last_acf_mantissa));

        memset(last_shift_value,  0, avctx->channels * sizeof(*last_shift_value) );

        ff_mlz_flush_dict(ctx->mlz);

    }



    for (c = 0; c < avctx->channels; ++c) {

        if (use_acf) {

            //acf_flag

            if (get_bits1(gb)) {

                tmp_32 = get_bits(gb, 23);

                last_acf_mantissa[c] = tmp_32;

            } else {

                tmp_32 = last_acf_mantissa[c];

            }

            acf[c] = av_bits2sf_ieee754(tmp_32);

        } else {

            acf[c] = FLOAT_1;

        }



        highest_byte = get_bits(gb, 2);

        partA_flag   = get_bits1(gb);

        shift_amp    = get_bits1(gb);



        if (shift_amp) {

            shift_value[c] = get_bits(gb, 8);

            last_shift_value[c] = shift_value[c];

        } else {

            shift_value[c] = last_shift_value[c];

        }



        if (partA_flag) {

            if (!get_bits1(gb)) { //uncompressed

                for (i = 0; i < frame_length; ++i) {

                    if (ctx->raw_samples[c][i] == 0) {

                        ctx->raw_mantissa[c][i] = get_bits_long(gb, 32);

                    }

                }

            } else { //compressed

                nchars = 0;

                for (i = 0; i < frame_length; ++i) {

                    if (ctx->raw_samples[c][i] == 0) {

                        nchars += 4;

                    }

                }



                tmp_32 = ff_mlz_decompression(ctx->mlz, gb, nchars, larray);

                if(tmp_32 != nchars) {

                    av_log(ctx->avctx, AV_LOG_ERROR, "Error in MLZ decompression (%d, %d).\n", tmp_32, nchars);

                    return AVERROR_INVALIDDATA;

                }



                for (i = 0; i < frame_length; ++i) {

                    ctx->raw_mantissa[c][i] = AV_RB32(larray);

                }

            }

        }



        //decode part B

        if (highest_byte) {

            for (i = 0; i < frame_length; ++i) {

                if (ctx->raw_samples[c][i] != 0) {

                    //The following logic is taken from Tabel 14.45 and 14.46 from the ISO spec

                    if (av_cmp_sf_ieee754(acf[c], FLOAT_1)) {

                        nbits[i] = 23 - av_log2(abs(ctx->raw_samples[c][i]));

                    } else {

                        nbits[i] = 23;

                    }

                    nbits[i] = FFMIN(nbits[i], highest_byte*8);

                }

            }



            if (!get_bits1(gb)) { //uncompressed

                for (i = 0; i < frame_length; ++i) {

                    if (ctx->raw_samples[c][i] != 0) {

                        raw_mantissa[c][i] = get_bits(gb, nbits[i]);

                    }

                }

            } else { //compressed

                nchars = 0;

                for (i = 0; i < frame_length; ++i) {

                    if (ctx->raw_samples[c][i]) {

                        nchars += (int) nbits[i] / 8;

                        if (nbits[i] & 7) {

                            ++nchars;

                        }

                    }

                }



                tmp_32 = ff_mlz_decompression(ctx->mlz, gb, nchars, larray);

                if(tmp_32 != nchars) {

                    av_log(ctx->avctx, AV_LOG_ERROR, "Error in MLZ decompression (%d, %d).\n", tmp_32, nchars);

                    return AVERROR_INVALIDDATA;

                }



                j = 0;

                for (i = 0; i < frame_length; ++i) {

                    if (ctx->raw_samples[c][i]) {

                        if (nbits[i] & 7) {

                            nbits_aligned = 8 * ((unsigned int)(nbits[i] / 8) + 1);

                        } else {

                            nbits_aligned = nbits[i];

                        }

                        acc = 0;

                        for (k = 0; k < nbits_aligned/8; ++k) {

                            acc = (acc << 8) + larray[j++];

                        }

                        acc >>= (nbits_aligned - nbits[i]);

                        raw_mantissa[c][i] = acc;

                    }

                }

            }

        }



        for (i = 0; i < frame_length; ++i) {

            SoftFloat_IEEE754 pcm_sf = av_int2sf_ieee754(ctx->raw_samples[c][i], 0);

            pcm_sf = av_div_sf_ieee754(pcm_sf, scale);



            if (ctx->raw_samples[c][i] != 0) {

                if (!av_cmp_sf_ieee754(acf[c], FLOAT_1)) {

                    pcm_sf = multiply(acf[c], pcm_sf);

                }



                sign = pcm_sf.sign;

                e = pcm_sf.exp;

                mantissa = (pcm_sf.mant | 0x800000) + raw_mantissa[c][i];



                while(mantissa >= 0x1000000) {

                    e++;

                    mantissa >>= 1;

                }



                if (mantissa) e += (shift_value[c] - 127);

                mantissa &= 0x007fffffUL;



                tmp_32 = (sign << 31) | ((e + EXP_BIAS) << 23) | (mantissa);

                ctx->raw_samples[c][i] = tmp_32;

            } else {

                ctx->raw_samples[c][i] = raw_mantissa[c][i] & 0x007fffffUL;

            }

        }

        align_get_bits(gb);

    }

    return 0;

}

static int X264_frame(AVCodecContext *ctx, uint8_t *buf,

                      int bufsize, void *data)

{

    X264Context *x4 = ctx->priv_data;

    AVFrame *frame = data;

    x264_nal_t *nal;

    int nnal, i;

    x264_picture_t pic_out;



    x264_picture_init( &x4->pic );

    x4->pic.img.i_csp   = X264_CSP_I420;

    x4->pic.img.i_plane = 3;



    if (frame) {

        for (i = 0; i < 3; i++) {

            x4->pic.img.plane[i]    = frame->data[i];

            x4->pic.img.i_stride[i] = frame->linesize[i];

        }



        x4->pic.i_pts  = frame->pts;

        x4->pic.i_type =

            frame->pict_type == AV_PICTURE_TYPE_I ? X264_TYPE_KEYFRAME :

            frame->pict_type == AV_PICTURE_TYPE_P ? X264_TYPE_P :

            frame->pict_type == AV_PICTURE_TYPE_B ? X264_TYPE_B :

                                            X264_TYPE_AUTO;

        if (x4->params.b_tff != frame->top_field_first) {

            x4->params.b_tff = frame->top_field_first;

            x264_encoder_reconfig(x4->enc, &x4->params);

        }

    }



    do {

    if (x264_encoder_encode(x4->enc, &nal, &nnal, frame? &x4->pic: NULL, &pic_out) < 0)

        return -1;



    bufsize = encode_nals(ctx, buf, bufsize, nal, nnal, 0);

    if (bufsize < 0)

        return -1;

    } while (!bufsize && !frame && x264_encoder_delayed_frames(x4->enc));



    /* FIXME: libx264 now provides DTS, but AVFrame doesn't have a field for it. */

    x4->out_pic.pts = pic_out.i_pts;



    switch (pic_out.i_type) {

    case X264_TYPE_IDR:

    case X264_TYPE_I:

        x4->out_pic.pict_type = AV_PICTURE_TYPE_I;

        break;

    case X264_TYPE_P:

        x4->out_pic.pict_type = AV_PICTURE_TYPE_P;

        break;

    case X264_TYPE_B:

    case X264_TYPE_BREF:

        x4->out_pic.pict_type = AV_PICTURE_TYPE_B;

        break;

    }



    x4->out_pic.key_frame = pic_out.b_keyframe;

    x4->out_pic.quality   = (pic_out.i_qpplus1 - 1) * FF_QP2LAMBDA;



    return bufsize;

}

static int parse_keyframes_index(AVFormatContext *s, AVIOContext *ioc, AVStream *vstream, int64_t max_pos) {

    unsigned int timeslen = 0, fileposlen = 0, i;

    char str_val[256];

    int64_t *times = NULL;

    int64_t *filepositions = NULL;

    int ret = AVERROR(ENOSYS);

    int64_t initial_pos = avio_tell(ioc);

    AVDictionaryEntry *creator = av_dict_get(s->metadata, "metadatacreator",

                                             NULL, 0);



    if (creator && !strcmp(creator->value, "MEGA")) {

        /* Files with this metadatacreator tag seem to have filepositions

         * pointing at the 4 trailer bytes of the previous packet,

         * which isn't the norm (nor what we expect here, nor what

         * jwplayer + lighttpd expect, nor what flvtool2 produces).

         * Just ignore the index in this case, instead of risking trying

         * to adjust it to something that might or might not work. */

        return 0;

    }



    if(vstream->nb_index_entries>0){

        av_log(s, AV_LOG_WARNING, "Skiping duplicate index\n");

        return 0;

    }



    while (avio_tell(ioc) < max_pos - 2 && amf_get_string(ioc, str_val, sizeof(str_val)) > 0) {

        int64_t** current_array;

        unsigned int arraylen;



        // Expect array object in context

        if (avio_r8(ioc) != AMF_DATA_TYPE_ARRAY)

            break;



        arraylen = avio_rb32(ioc);

        if(arraylen>>28)

            break;



        if       (!strcmp(KEYFRAMES_TIMESTAMP_TAG , str_val) && !times){

            current_array= &times;

            timeslen= arraylen;

        }else if (!strcmp(KEYFRAMES_BYTEOFFSET_TAG, str_val) && !filepositions){

            current_array= &filepositions;

            fileposlen= arraylen;

        }else // unexpected metatag inside keyframes, will not use such metadata for indexing

            break;



        if (!(*current_array = av_mallocz(sizeof(**current_array) * arraylen))) {

            ret = AVERROR(ENOMEM);

            goto finish;

        }



        for (i = 0; i < arraylen && avio_tell(ioc) < max_pos - 1; i++) {

            if (avio_r8(ioc) != AMF_DATA_TYPE_NUMBER)

                goto finish;

            current_array[0][i] = av_int2dbl(avio_rb64(ioc));

        }

        if (times && filepositions) {

            // All done, exiting at a position allowing amf_parse_object

            // to finish parsing the object

            ret = 0;

            break;

        }

    }



    if (timeslen == fileposlen) {

         for(i = 0; i < timeslen; i++)

             av_add_index_entry(vstream, filepositions[i], times[i]*1000, 0, 0, AVINDEX_KEYFRAME);

    } else

        av_log(s, AV_LOG_WARNING, "Invalid keyframes object, skipping.\n");



finish:

    av_freep(&times);

    av_freep(&filepositions);

    avio_seek(ioc, initial_pos, SEEK_SET);

    return ret;

}

void avcodec_default_release_buffer(AVCodecContext *s, AVFrame *pic){

    int i;

    InternalBuffer *buf, *last;

    AVCodecInternal *avci = s->internal;



    assert(s->codec_type == AVMEDIA_TYPE_VIDEO);



    assert(pic->type==FF_BUFFER_TYPE_INTERNAL);

    assert(avci->buffer_count);



    if (avci->buffer) {

        buf = NULL; /* avoids warning */

        for (i = 0; i < avci->buffer_count; i++) { //just 3-5 checks so is not worth to optimize

            buf = &avci->buffer[i];

            if (buf->data[0] == pic->data[0])

                break;

        }

        assert(i < avci->buffer_count);

        avci->buffer_count--;

        last = &avci->buffer[avci->buffer_count];



        FFSWAP(InternalBuffer, *buf, *last);

    }



    for (i = 0; i < AV_NUM_DATA_POINTERS; i++) {

        pic->data[i]=NULL;

//        pic->base[i]=NULL;

    }

//printf("R%X\n", pic->opaque);



    if(s->debug&FF_DEBUG_BUFFERS)

        av_log(s, AV_LOG_DEBUG, "default_release_buffer called on pic %p, %d "

               "buffers used\n", pic, avci->buffer_count);

}

static void iv_Decode_Chunk(Indeo3DecodeContext *s,

        uint8_t *cur, uint8_t *ref, int width, int height,

        const uint8_t *buf1, int cb_offset, const uint8_t *hdr,

        const uint8_t *buf2, int min_width_160)

{

    uint8_t bit_buf;

    unsigned int bit_pos, lv, lv1, lv2;

    int *width_tbl, width_tbl_arr[10];

    const signed char *ref_vectors;

    uint8_t *cur_frm_pos, *ref_frm_pos, *cp, *cp2;


    uint32_t *cur_lp, *ref_lp;

    const uint32_t *correction_lp[2], *correctionloworder_lp[2], *correctionhighorder_lp[2];

    uint8_t *correction_type_sp[2];

    struct ustr strip_tbl[20], *strip;

    int i, j, k, lp1, lp2, flag1, cmd, blks_width, blks_height, region_160_width,

        rle_v1, rle_v2, rle_v3;

    unsigned short res;



    bit_buf = 0;

    ref_vectors = NULL;



    width_tbl = width_tbl_arr + 1;

    i = (width < 0 ? width + 3 : width)/4;

    for(j = -1; j < 8; j++)

        width_tbl[j] = i * j;



    strip = strip_tbl;



    for(region_160_width = 0; region_160_width < (width - min_width_160); region_160_width += min_width_160);



    strip->ypos = strip->xpos = 0;

    for(strip->width = min_width_160; width > strip->width; strip->width *= 2);

    strip->height = height;

    strip->split_direction = 0;

    strip->split_flag = 0;

    strip->usl7 = 0;



    bit_pos = 0;



    rle_v1 = rle_v2 = rle_v3 = 0;



    while(strip >= strip_tbl) {

        if(bit_pos <= 0) {

            bit_pos = 8;

            bit_buf = *buf1++;

        }



        bit_pos -= 2;

        cmd = (bit_buf >> bit_pos) & 0x03;



        if(cmd == 0) {

            strip++;

            if(strip >= strip_tbl + FF_ARRAY_ELEMS(strip_tbl)) {

                av_log(s->avctx, AV_LOG_WARNING, "out of range strip\n");

                break;

            }

            memcpy(strip, strip-1, sizeof(*strip));

            strip->split_flag = 1;

            strip->split_direction = 0;

            strip->height = (strip->height > 8 ? ((strip->height+8)>>4)<<3 : 4);

            continue;

        } else if(cmd == 1) {

            strip++;

            if(strip >= strip_tbl + FF_ARRAY_ELEMS(strip_tbl)) {

                av_log(s->avctx, AV_LOG_WARNING, "out of range strip\n");

                break;

            }

            memcpy(strip, strip-1, sizeof(*strip));

            strip->split_flag = 1;

            strip->split_direction = 1;

            strip->width = (strip->width > 8 ? ((strip->width+8)>>4)<<3 : 4);

            continue;

        } else if(cmd == 2) {

            if(strip->usl7 == 0) {

                strip->usl7 = 1;

                ref_vectors = NULL;

                continue;

            }

        } else if(cmd == 3) {

            if(strip->usl7 == 0) {

                strip->usl7 = 1;

                ref_vectors = (const signed char*)buf2 + (*buf1 * 2);

                buf1++;

                continue;

            }

        }



        cur_frm_pos = cur + width * strip->ypos + strip->xpos;



        if((blks_width = strip->width) < 0)

            blks_width += 3;

        blks_width >>= 2;

        blks_height = strip->height;



        if(ref_vectors != NULL) {

            ref_frm_pos = ref + (ref_vectors[0] + strip->ypos) * width +

                ref_vectors[1] + strip->xpos;

        } else

            ref_frm_pos = cur_frm_pos - width_tbl[4];



        if(cmd == 2) {

            if(bit_pos <= 0) {

                bit_pos = 8;

                bit_buf = *buf1++;

            }



            bit_pos -= 2;

            cmd = (bit_buf >> bit_pos) & 0x03;



            if(cmd == 0 || ref_vectors != NULL) {

                for(lp1 = 0; lp1 < blks_width; lp1++) {

                    for(i = 0, j = 0; i < blks_height; i++, j += width_tbl[1])

                        ((uint32_t *)cur_frm_pos)[j] = ((uint32_t *)ref_frm_pos)[j];

                    cur_frm_pos += 4;

                    ref_frm_pos += 4;

                }

            } else if(cmd != 1)

                return;

        } else {

            k = *buf1 >> 4;

            j = *buf1 & 0x0f;

            buf1++;

            lv = j + cb_offset;



            if((lv - 8) <= 7 && (k == 0 || k == 3 || k == 10)) {

                cp2 = s->ModPred + ((lv - 8) << 7);

                cp = ref_frm_pos;

                for(i = 0; i < blks_width << 2; i++) {

                    int v = *cp >> 1;

                    *(cp++) = cp2[v];

                }

            }



            if(k == 1 || k == 4) {

                lv = (hdr[j] & 0xf) + cb_offset;

                correction_type_sp[0] = s->corrector_type + (lv << 8);

                correction_lp[0] = correction + (lv << 8);

                lv = (hdr[j] >> 4) + cb_offset;

                correction_lp[1] = correction + (lv << 8);

                correction_type_sp[1] = s->corrector_type + (lv << 8);

            } else {

                correctionloworder_lp[0] = correctionloworder_lp[1] = correctionloworder + (lv << 8);

                correctionhighorder_lp[0] = correctionhighorder_lp[1] = correctionhighorder + (lv << 8);

                correction_type_sp[0] = correction_type_sp[1] = s->corrector_type + (lv << 8);

                correction_lp[0] = correction_lp[1] = correction + (lv << 8);

            }



            switch(k) {

            case 1:

            case 0:                    /********** CASE 0 **********/

                for( ; blks_height > 0; blks_height -= 4) {

                    for(lp1 = 0; lp1 < blks_width; lp1++) {

                        for(lp2 = 0; lp2 < 4; ) {

                            k = *buf1++;

                            cur_lp = ((uint32_t *)cur_frm_pos) + width_tbl[lp2];

                            ref_lp = ((uint32_t *)ref_frm_pos) + width_tbl[lp2];

                            if ((uint8_t *)cur_lp >= cur_end-3)

                                break;



                            switch(correction_type_sp[0][k]) {

                            case 0:

                                *cur_lp = av_le2ne32(((av_le2ne32(*ref_lp) >> 1) + correction_lp[lp2 & 0x01][k]) << 1);

                                lp2++;

                                break;

                            case 1:

                                res = ((av_le2ne16(((unsigned short *)(ref_lp))[0]) >> 1) + correction_lp[lp2 & 0x01][*buf1]) << 1;

                                ((unsigned short *)cur_lp)[0] = av_le2ne16(res);

                                res = ((av_le2ne16(((unsigned short *)(ref_lp))[1]) >> 1) + correction_lp[lp2 & 0x01][k]) << 1;

                                ((unsigned short *)cur_lp)[1] = av_le2ne16(res);

                                buf1++;

                                lp2++;

                                break;

                            case 2:

                                if(lp2 == 0) {

                                    for(i = 0, j = 0; i < 2; i++, j += width_tbl[1])

                                        cur_lp[j] = ref_lp[j];

                                    lp2 += 2;

                                }

                                break;

                            case 3:

                                if(lp2 < 2) {

                                    for(i = 0, j = 0; i < (3 - lp2); i++, j += width_tbl[1])

                                        cur_lp[j] = ref_lp[j];

                                    lp2 = 3;

                                }

                                break;

                            case 8:

                                if(lp2 == 0) {

                                    RLE_V3_CHECK(buf1,rle_v1,rle_v2,rle_v3)



                                    if(rle_v1 == 1 || ref_vectors != NULL) {

                                        for(i = 0, j = 0; i < 4; i++, j += width_tbl[1])

                                            cur_lp[j] = ref_lp[j];

                                    }



                                    RLE_V2_CHECK(buf1,rle_v2, rle_v3,lp2)

                                    break;

                                } else {

                                    rle_v1 = 1;

                                    rle_v2 = *buf1 - 1;

                                }

                            case 5:

                                LP2_CHECK(buf1,rle_v3,lp2)

                            case 4:

                                for(i = 0, j = 0; i < (4 - lp2); i++, j += width_tbl[1])

                                    cur_lp[j] = ref_lp[j];

                                lp2 = 4;

                                break;



                            case 7:

                                if(rle_v3 != 0)

                                    rle_v3 = 0;

                                else {

                                    buf1--;

                                    rle_v3 = 1;

                                }

                            case 6:

                                if(ref_vectors != NULL) {

                                    for(i = 0, j = 0; i < 4; i++, j += width_tbl[1])

                                        cur_lp[j] = ref_lp[j];

                                }

                                lp2 = 4;

                                break;



                            case 9:

                                lv1 = *buf1++;

                                lv = (lv1 & 0x7F) << 1;

                                lv += (lv << 8);

                                lv += (lv << 16);

                                for(i = 0, j = 0; i < 4; i++, j += width_tbl[1])

                                    cur_lp[j] = lv;



                                LV1_CHECK(buf1,rle_v3,lv1,lp2)

                                break;

                            default:

                                return;

                            }

                        }



                        cur_frm_pos += 4;

                        ref_frm_pos += 4;

                    }



                    cur_frm_pos += ((width - blks_width) * 4);

                    ref_frm_pos += ((width - blks_width) * 4);

                }

                break;



            case 4:

            case 3:                    /********** CASE 3 **********/

                if(ref_vectors != NULL)

                    return;

                flag1 = 1;



                for( ; blks_height > 0; blks_height -= 8) {

                    for(lp1 = 0; lp1 < blks_width; lp1++) {

                        for(lp2 = 0; lp2 < 4; ) {

                            k = *buf1++;



                            cur_lp = ((uint32_t *)cur_frm_pos) + width_tbl[lp2 * 2];

                            ref_lp = ((uint32_t *)cur_frm_pos) + width_tbl[(lp2 * 2) - 1];



                            switch(correction_type_sp[lp2 & 0x01][k]) {

                            case 0:

                                cur_lp[width_tbl[1]] = av_le2ne32(((av_le2ne32(*ref_lp) >> 1) + correction_lp[lp2 & 0x01][k]) << 1);

                                if(lp2 > 0 || flag1 == 0 || strip->ypos != 0)

                                    cur_lp[0] = ((cur_lp[-width_tbl[1]] >> 1) + (cur_lp[width_tbl[1]] >> 1)) & 0xFEFEFEFE;

                                else

                                    cur_lp[0] = av_le2ne32(((av_le2ne32(*ref_lp) >> 1) + correction_lp[lp2 & 0x01][k]) << 1);

                                lp2++;

                                break;



                            case 1:

                                res = ((av_le2ne16(((unsigned short *)ref_lp)[0]) >> 1) + correction_lp[lp2 & 0x01][*buf1]) << 1;

                                ((unsigned short *)cur_lp)[width_tbl[2]] = av_le2ne16(res);

                                res = ((av_le2ne16(((unsigned short *)ref_lp)[1]) >> 1) + correction_lp[lp2 & 0x01][k]) << 1;

                                ((unsigned short *)cur_lp)[width_tbl[2]+1] = av_le2ne16(res);



                                if(lp2 > 0 || flag1 == 0 || strip->ypos != 0)

                                    cur_lp[0] = ((cur_lp[-width_tbl[1]] >> 1) + (cur_lp[width_tbl[1]] >> 1)) & 0xFEFEFEFE;

                                else

                                    cur_lp[0] = cur_lp[width_tbl[1]];

                                buf1++;

                                lp2++;

                                break;



                            case 2:

                                if(lp2 == 0) {

                                    for(i = 0, j = 0; i < 4; i++, j += width_tbl[1])

                                        cur_lp[j] = *ref_lp;

                                    lp2 += 2;

                                }

                                break;



                            case 3:

                                if(lp2 < 2) {

                                    for(i = 0, j = 0; i < 6 - (lp2 * 2); i++, j += width_tbl[1])

                                        cur_lp[j] = *ref_lp;

                                    lp2 = 3;

                                }

                                break;



                            case 6:

                                lp2 = 4;

                                break;



                            case 7:

                                if(rle_v3 != 0)

                                    rle_v3 = 0;

                                else {

                                    buf1--;

                                    rle_v3 = 1;

                                }

                                lp2 = 4;

                                break;



                            case 8:

                                if(lp2 == 0) {

                                    RLE_V3_CHECK(buf1,rle_v1,rle_v2,rle_v3)



                                    if(rle_v1 == 1) {

                                        for(i = 0, j = 0; i < 8; i++, j += width_tbl[1])

                                            cur_lp[j] = ref_lp[j];

                                    }



                                    RLE_V2_CHECK(buf1,rle_v2, rle_v3,lp2)

                                    break;

                                } else {

                                    rle_v2 = (*buf1) - 1;

                                    rle_v1 = 1;

                                }

                            case 5:

                                LP2_CHECK(buf1,rle_v3,lp2)

                            case 4:

                                for(i = 0, j = 0; i < 8 - (lp2 * 2); i++, j += width_tbl[1])

                                    cur_lp[j] = *ref_lp;

                                lp2 = 4;

                                break;



                            case 9:

                                av_log(s->avctx, AV_LOG_ERROR, "UNTESTED.\n");

                                lv1 = *buf1++;

                                lv = (lv1 & 0x7F) << 1;

                                lv += (lv << 8);

                                lv += (lv << 16);



                                for(i = 0, j = 0; i < 4; i++, j += width_tbl[1])

                                    cur_lp[j] = lv;



                                LV1_CHECK(buf1,rle_v3,lv1,lp2)

                                break;



                            default:

                                return;

                            }

                        }



                        cur_frm_pos += 4;

                    }



                    cur_frm_pos += (((width * 2) - blks_width) * 4);

                    flag1 = 0;

                }

                break;



            case 10:                    /********** CASE 10 **********/

                if(ref_vectors == NULL) {

                    flag1 = 1;



                    for( ; blks_height > 0; blks_height -= 8) {

                        for(lp1 = 0; lp1 < blks_width; lp1 += 2) {

                            for(lp2 = 0; lp2 < 4; ) {

                                k = *buf1++;

                                cur_lp = ((uint32_t *)cur_frm_pos) + width_tbl[lp2 * 2];

                                ref_lp = ((uint32_t *)cur_frm_pos) + width_tbl[(lp2 * 2) - 1];

                                lv1 = ref_lp[0];

                                lv2 = ref_lp[1];

                                if(lp2 == 0 && flag1 != 0) {

#if HAVE_BIGENDIAN

                                    lv1 = lv1 & 0xFF00FF00;

                                    lv1 = (lv1 >> 8) | lv1;

                                    lv2 = lv2 & 0xFF00FF00;

                                    lv2 = (lv2 >> 8) | lv2;

#else

                                    lv1 = lv1 & 0x00FF00FF;

                                    lv1 = (lv1 << 8) | lv1;

                                    lv2 = lv2 & 0x00FF00FF;

                                    lv2 = (lv2 << 8) | lv2;

#endif

                                }



                                switch(correction_type_sp[lp2 & 0x01][k]) {

                                case 0:

                                    cur_lp[width_tbl[1]] = av_le2ne32(((av_le2ne32(lv1) >> 1) + correctionloworder_lp[lp2 & 0x01][k]) << 1);

                                    cur_lp[width_tbl[1]+1] = av_le2ne32(((av_le2ne32(lv2) >> 1) + correctionhighorder_lp[lp2 & 0x01][k]) << 1);

                                    if(lp2 > 0 || strip->ypos != 0 || flag1 == 0) {

                                        cur_lp[0] = ((cur_lp[-width_tbl[1]] >> 1) + (cur_lp[width_tbl[1]] >> 1)) & 0xFEFEFEFE;

                                        cur_lp[1] = ((cur_lp[-width_tbl[1]+1] >> 1) + (cur_lp[width_tbl[1]+1] >> 1)) & 0xFEFEFEFE;

                                    } else {

                                        cur_lp[0] = cur_lp[width_tbl[1]];

                                        cur_lp[1] = cur_lp[width_tbl[1]+1];

                                    }

                                    lp2++;

                                    break;



                                case 1:

                                    cur_lp[width_tbl[1]] = av_le2ne32(((av_le2ne32(lv1) >> 1) + correctionloworder_lp[lp2 & 0x01][*buf1]) << 1);

                                    cur_lp[width_tbl[1]+1] = av_le2ne32(((av_le2ne32(lv2) >> 1) + correctionloworder_lp[lp2 & 0x01][k]) << 1);

                                    if(lp2 > 0 || strip->ypos != 0 || flag1 == 0) {

                                        cur_lp[0] = ((cur_lp[-width_tbl[1]] >> 1) + (cur_lp[width_tbl[1]] >> 1)) & 0xFEFEFEFE;

                                        cur_lp[1] = ((cur_lp[-width_tbl[1]+1] >> 1) + (cur_lp[width_tbl[1]+1] >> 1)) & 0xFEFEFEFE;

                                    } else {

                                        cur_lp[0] = cur_lp[width_tbl[1]];

                                        cur_lp[1] = cur_lp[width_tbl[1]+1];

                                    }

                                    buf1++;

                                    lp2++;

                                    break;



                                case 2:

                                    if(lp2 == 0) {

                                        if(flag1 != 0) {

                                            for(i = 0, j = width_tbl[1]; i < 3; i++, j += width_tbl[1]) {

                                                cur_lp[j] = lv1;

                                                cur_lp[j+1] = lv2;

                                            }

                                            cur_lp[0] = ((cur_lp[-width_tbl[1]] >> 1) + (cur_lp[width_tbl[1]] >> 1)) & 0xFEFEFEFE;

                                            cur_lp[1] = ((cur_lp[-width_tbl[1]+1] >> 1) + (cur_lp[width_tbl[1]+1] >> 1)) & 0xFEFEFEFE;

                                        } else {

                                            for(i = 0, j = 0; i < 4; i++, j += width_tbl[1]) {

                                                cur_lp[j] = lv1;

                                                cur_lp[j+1] = lv2;

                                            }

                                        }

                                        lp2 += 2;

                                    }

                                    break;



                                case 3:

                                    if(lp2 < 2) {

                                        if(lp2 == 0 && flag1 != 0) {

