static int y216_decode_frame(AVCodecContext *avctx, void *data,

                             int *got_frame, AVPacket *avpkt)

{

    AVFrame *pic = data;

    const uint16_t *src = (uint16_t *)avpkt->data;

    uint16_t *y, *u, *v, aligned_width = FFALIGN(avctx->width, 4);

    int i, j, ret;



    if (avpkt->size < 4 * avctx->height * aligned_width) {

        av_log(avctx, AV_LOG_ERROR, "Insufficient input data.\n");

        return AVERROR(EINVAL);

    }



    if ((ret = ff_get_buffer(avctx, pic, 0)) < 0)

        return ret;



    pic->key_frame = 1;

    pic->pict_type = AV_PICTURE_TYPE_I;



    y = (uint16_t *)pic->data[0];

    u = (uint16_t *)pic->data[1];

    v = (uint16_t *)pic->data[2];



    for (i = 0; i < avctx->height; i++) {

        for (j = 0; j < avctx->width >> 1; j++) {

            u[    j    ] = src[4 * j    ] << 2 | src[4 * j    ] >> 14;

            y[2 * j    ] = src[4 * j + 1] << 2 | src[4 * j + 1] >> 14;

            v[    j    ] = src[4 * j + 2] << 2 | src[4 * j + 2] >> 14;

            y[2 * j + 1] = src[4 * j + 3] << 2 | src[4 * j + 3] >> 14;

        }



        y += pic->linesize[0] >> 1;

        u += pic->linesize[1] >> 1;

        v += pic->linesize[2] >> 1;

        src += aligned_width << 1;

    }



    *got_frame = 1;



    return avpkt->size;

}

void audio_decode_example(const char *outfilename, const char *filename)

{

    AVCodec *codec;

    AVCodecContext *c= NULL;

    int out_size, size, len;

    FILE *f, *outfile;

    uint8_t *outbuf;

    uint8_t inbuf[INBUF_SIZE + FF_INPUT_BUFFER_PADDING_SIZE], *inbuf_ptr;



    printf("Audio decoding\n");



    /* set end of buffer to 0 (this ensures that no overreading happens for damaged mpeg streams) */

    memset(inbuf + INBUF_SIZE, 0, FF_INPUT_BUFFER_PADDING_SIZE);



    /* find the mpeg audio decoder */

    codec = avcodec_find_decoder(CODEC_ID_MP2);

    if (!codec) {

        fprintf(stderr, "codec not found\n");

        exit(1);

    }



    c= avcodec_alloc_context();



    /* open it */

    if (avcodec_open(c, codec) < 0) {

        fprintf(stderr, "could not open codec\n");

        exit(1);

    }



    outbuf = malloc(AVCODEC_MAX_AUDIO_FRAME_SIZE);



    f = fopen(filename, "r");

    if (!f) {

        fprintf(stderr, "could not open %s\n", filename);

        exit(1);

    }

    outfile = fopen(outfilename, "w");

    if (!outfile) {

        free(c);

        exit(1);

    }



    /* decode until eof */

    inbuf_ptr = inbuf;

    for(;;) {

        size = fread(inbuf, 1, INBUF_SIZE, f);

        if (size == 0)

            break;



        inbuf_ptr = inbuf;

        while (size > 0) {

            len = avcodec_decode_audio(c, (short *)outbuf, &out_size, 

                                       inbuf_ptr, size);

            if (len < 0) {

                fprintf(stderr, "Error while decoding\n");

                exit(1);

            }

            if (out_size > 0) {

                /* if a frame has been decoded, output it */

                fwrite(outbuf, 1, out_size, outfile);

            }

            size -= len;

            inbuf_ptr += len;

        }

    }



    fclose(outfile);

    fclose(f);

    free(outbuf);



    avcodec_close(c);

    free(c);

}

static void compute_pkt_fields(AVFormatContext *s, AVStream *st,

                               AVCodecParserContext *pc, AVPacket *pkt)

{

    int num, den, presentation_delayed, delay, i;

    int64_t offset;



    if (s->flags & AVFMT_FLAG_NOFILLIN)

        return;



    if((s->flags & AVFMT_FLAG_IGNDTS) && pkt->pts != AV_NOPTS_VALUE)

        pkt->dts= AV_NOPTS_VALUE;



    if (st->codec->codec_id != CODEC_ID_H264 && pc && pc->pict_type == FF_B_TYPE)

        //FIXME Set low_delay = 0 when has_b_frames = 1

        st->codec->has_b_frames = 1;



    /* do we have a video B-frame ? */

    delay= st->codec->has_b_frames;

    presentation_delayed = 0;

    /* XXX: need has_b_frame, but cannot get it if the codec is

        not initialized */

    if (delay &&

        pc && pc->pict_type != FF_B_TYPE)

        presentation_delayed = 1;



    if(pkt->pts != AV_NOPTS_VALUE && pkt->dts != AV_NOPTS_VALUE && pkt->dts > pkt->pts && st->pts_wrap_bits<63

       /*&& pkt->dts-(1LL<<st->pts_wrap_bits) < pkt->pts*/){

        pkt->dts -= 1LL<<st->pts_wrap_bits;

    }



    // some mpeg2 in mpeg-ps lack dts (issue171 / input_file.mpg)

    // we take the conservative approach and discard both

    // Note, if this is misbehaving for a H.264 file then possibly presentation_delayed is not set correctly.

    if(delay==1 && pkt->dts == pkt->pts && pkt->dts != AV_NOPTS_VALUE && presentation_delayed){

        av_log(s, AV_LOG_WARNING, "invalid dts/pts combination\n");

        pkt->dts= pkt->pts= AV_NOPTS_VALUE;

    }



    if (pkt->duration == 0) {

        compute_frame_duration(&num, &den, st, pc, pkt);

        if (den && num) {

            pkt->duration = av_rescale_rnd(1, num * (int64_t)st->time_base.den, den * (int64_t)st->time_base.num, AV_ROUND_DOWN);



            if(pkt->duration != 0 && s->packet_buffer)

                update_initial_durations(s, st, pkt);

        }

    }



    /* correct timestamps with byte offset if demuxers only have timestamps

       on packet boundaries */

    if(pc && st->need_parsing == AVSTREAM_PARSE_TIMESTAMPS && pkt->size){

        /* this will estimate bitrate based on this frame's duration and size */

        offset = av_rescale(pc->offset, pkt->duration, pkt->size);

        if(pkt->pts != AV_NOPTS_VALUE)

            pkt->pts += offset;

        if(pkt->dts != AV_NOPTS_VALUE)

            pkt->dts += offset;

    }



    if (pc && pc->dts_sync_point >= 0) {

        // we have synchronization info from the parser

        int64_t den = st->codec->time_base.den * (int64_t) st->time_base.num;

        if (den > 0) {

            int64_t num = st->codec->time_base.num * (int64_t) st->time_base.den;

            if (pkt->dts != AV_NOPTS_VALUE) {

                // got DTS from the stream, update reference timestamp

                st->reference_dts = pkt->dts - pc->dts_ref_dts_delta * num / den;

                pkt->pts = pkt->dts + pc->pts_dts_delta * num / den;

            } else if (st->reference_dts != AV_NOPTS_VALUE) {

                // compute DTS based on reference timestamp

                pkt->dts = st->reference_dts + pc->dts_ref_dts_delta * num / den;

                pkt->pts = pkt->dts + pc->pts_dts_delta * num / den;

            }

            if (pc->dts_sync_point > 0)

                st->reference_dts = pkt->dts; // new reference

        }

    }



    /* This may be redundant, but it should not hurt. */

    if(pkt->dts != AV_NOPTS_VALUE && pkt->pts != AV_NOPTS_VALUE && pkt->pts > pkt->dts)

        presentation_delayed = 1;



//    av_log(NULL, AV_LOG_DEBUG, "IN delayed:%d pts:%"PRId64", dts:%"PRId64" cur_dts:%"PRId64" st:%d pc:%p\n", presentation_delayed, pkt->pts, pkt->dts, st->cur_dts, pkt->stream_index, pc);

    /* interpolate PTS and DTS if they are not present */

    //We skip H264 currently because delay and has_b_frames are not reliably set

    if((delay==0 || (delay==1 && pc)) && st->codec->codec_id != CODEC_ID_H264){

        if (presentation_delayed) {

            /* DTS = decompression timestamp */

            /* PTS = presentation timestamp */

            if (pkt->dts == AV_NOPTS_VALUE)

                pkt->dts = st->last_IP_pts;

            update_initial_timestamps(s, pkt->stream_index, pkt->dts, pkt->pts);

            if (pkt->dts == AV_NOPTS_VALUE)

                pkt->dts = st->cur_dts;



            /* this is tricky: the dts must be incremented by the duration

            of the frame we are displaying, i.e. the last I- or P-frame */

            if (st->last_IP_duration == 0)

                st->last_IP_duration = pkt->duration;

            if(pkt->dts != AV_NOPTS_VALUE)

                st->cur_dts = pkt->dts + st->last_IP_duration;

            st->last_IP_duration  = pkt->duration;

            st->last_IP_pts= pkt->pts;

            /* cannot compute PTS if not present (we can compute it only

            by knowing the future */

        } else if(pkt->pts != AV_NOPTS_VALUE || pkt->dts != AV_NOPTS_VALUE || pkt->duration){

            if(pkt->pts != AV_NOPTS_VALUE && pkt->duration){

                int64_t old_diff= FFABS(st->cur_dts - pkt->duration - pkt->pts);

                int64_t new_diff= FFABS(st->cur_dts - pkt->pts);

                if(old_diff < new_diff && old_diff < (pkt->duration>>3)){

                    pkt->pts += pkt->duration;

    //                av_log(NULL, AV_LOG_DEBUG, "id:%d old:%"PRId64" new:%"PRId64" dur:%d cur:%"PRId64" size:%d\n", pkt->stream_index, old_diff, new_diff, pkt->duration, st->cur_dts, pkt->size);

                }

            }



            /* presentation is not delayed : PTS and DTS are the same */

            if(pkt->pts == AV_NOPTS_VALUE)

                pkt->pts = pkt->dts;

            update_initial_timestamps(s, pkt->stream_index, pkt->pts, pkt->pts);

            if(pkt->pts == AV_NOPTS_VALUE)

                pkt->pts = st->cur_dts;

            pkt->dts = pkt->pts;

            if(pkt->pts != AV_NOPTS_VALUE)

                st->cur_dts = pkt->pts + pkt->duration;

        }

    }



    if(pkt->pts != AV_NOPTS_VALUE && delay <= MAX_REORDER_DELAY){

        st->pts_buffer[0]= pkt->pts;

        for(i=0; i<delay && st->pts_buffer[i] > st->pts_buffer[i+1]; i++)

            FFSWAP(int64_t, st->pts_buffer[i], st->pts_buffer[i+1]);

        if(pkt->dts == AV_NOPTS_VALUE)

            pkt->dts= st->pts_buffer[0];

        if(st->codec->codec_id == CODEC_ID_H264){ //we skiped it above so we try here

            update_initial_timestamps(s, pkt->stream_index, pkt->dts, pkt->pts); // this should happen on the first packet

        }

        if(pkt->dts > st->cur_dts)

            st->cur_dts = pkt->dts;

    }



//    av_log(NULL, AV_LOG_ERROR, "OUTdelayed:%d/%d pts:%"PRId64", dts:%"PRId64" cur_dts:%"PRId64"\n", presentation_delayed, delay, pkt->pts, pkt->dts, st->cur_dts);



    /* update flags */

    if(is_intra_only(st->codec))

        pkt->flags |= AV_PKT_FLAG_KEY;

    else if (pc) {

        pkt->flags = 0;

        /* keyframe computation */

        if (pc->key_frame == 1)

            pkt->flags |= AV_PKT_FLAG_KEY;

        else if (pc->key_frame == -1 && pc->pict_type == FF_I_TYPE)

            pkt->flags |= AV_PKT_FLAG_KEY;

    }

    if (pc)

        pkt->convergence_duration = pc->convergence_duration;

}

static void avc_biwgt_8width_msa(uint8_t *src, int32_t src_stride,

                                 uint8_t *dst, int32_t dst_stride,

                                 int32_t height, int32_t log2_denom,

                                 int32_t src_weight, int32_t dst_weight,

                                 int32_t offset_in)

{

    uint8_t cnt;

    v16i8 src_wgt, dst_wgt, wgt;

    v16i8 src0, src1, src2, src3;

    v16i8 dst0, dst1, dst2, dst3;

    v8i16 temp0, temp1, temp2, temp3;

    v8i16 denom, offset, add_val;

    int32_t val = 128 * (src_weight + dst_weight);



    offset_in = ((offset_in + 1) | 1) << log2_denom;



    src_wgt = __msa_fill_b(src_weight);

    dst_wgt = __msa_fill_b(dst_weight);

    offset = __msa_fill_h(offset_in);

    denom = __msa_fill_h(log2_denom + 1);

    add_val = __msa_fill_h(val);

    offset += add_val;



    wgt = __msa_ilvev_b(dst_wgt, src_wgt);



    for (cnt = height / 4; cnt--;) {

        LOAD_4VECS_SB(src, src_stride, src0, src1, src2, src3);

        src += (4 * src_stride);



        LOAD_4VECS_SB(dst, dst_stride, dst0, dst1, dst2, dst3);



        XORI_B_4VECS_SB(src0, src1, src2, src3, src0, src1, src2, src3, 128);



        XORI_B_4VECS_SB(dst0, dst1, dst2, dst3, dst0, dst1, dst2, dst3, 128);



        ILVR_B_4VECS_SH(src0, src1, src2, src3, dst0, dst1, dst2, dst3,

                        temp0, temp1, temp2, temp3);



        temp0 = __msa_dpadd_s_h(offset, wgt, (v16i8) temp0);

        temp1 = __msa_dpadd_s_h(offset, wgt, (v16i8) temp1);

        temp2 = __msa_dpadd_s_h(offset, wgt, (v16i8) temp2);

        temp3 = __msa_dpadd_s_h(offset, wgt, (v16i8) temp3);



        SRA_4VECS(temp0, temp1, temp2, temp3,

                  temp0, temp1, temp2, temp3, denom);



        temp0 = CLIP_UNSIGNED_CHAR_H(temp0);

        temp1 = CLIP_UNSIGNED_CHAR_H(temp1);

        temp2 = CLIP_UNSIGNED_CHAR_H(temp2);

        temp3 = CLIP_UNSIGNED_CHAR_H(temp3);



        PCKEV_B_STORE_8_BYTES_4(temp0, temp1, temp2, temp3, dst, dst_stride);

        dst += 4 * dst_stride;

    }

}

static void add_input_streams(OptionsContext *o, AVFormatContext *ic)

{

    int i;

    char *next, *codec_tag = NULL;



    for (i = 0; i < ic->nb_streams; i++) {

        AVStream *st = ic->streams[i];

        AVCodecContext *dec = st->codec;

        InputStream *ist = av_mallocz(sizeof(*ist));

        char *framerate = NULL;



        if (!ist)

            exit(1);



        GROW_ARRAY(input_streams, nb_input_streams);

        input_streams[nb_input_streams - 1] = ist;



        ist->st = st;

        ist->file_index = nb_input_files;

        ist->discard = 1;

        st->discard  = AVDISCARD_ALL;



        ist->ts_scale = 1.0;

        MATCH_PER_STREAM_OPT(ts_scale, dbl, ist->ts_scale, ic, st);



        MATCH_PER_STREAM_OPT(codec_tags, str, codec_tag, ic, st);

        if (codec_tag) {

            uint32_t tag = strtol(codec_tag, &next, 0);

            if (*next)

                tag = AV_RL32(codec_tag);

            st->codec->codec_tag = tag;

        }



        ist->dec = choose_decoder(o, ic, st);

        ist->opts = filter_codec_opts(o->g->codec_opts, ist->st->codec->codec_id, ic, st, ist->dec);



        ist->reinit_filters = -1;

        MATCH_PER_STREAM_OPT(reinit_filters, i, ist->reinit_filters, ic, st);



        ist->filter_in_rescale_delta_last = AV_NOPTS_VALUE;



        switch (dec->codec_type) {

        case AVMEDIA_TYPE_VIDEO:

            if(!ist->dec)

                ist->dec = avcodec_find_decoder(dec->codec_id);

            if (dec->lowres) {

                dec->flags |= CODEC_FLAG_EMU_EDGE;

            }



            ist->resample_height  = dec->height;

            ist->resample_width   = dec->width;

            ist->resample_pix_fmt = dec->pix_fmt;



            MATCH_PER_STREAM_OPT(frame_rates, str, framerate, ic, st);

            if (framerate && av_parse_video_rate(&ist->framerate,

                                                 framerate) < 0) {

                av_log(NULL, AV_LOG_ERROR, "Error parsing framerate %s.\n",

                       framerate);

                exit(1);

            }



            ist->top_field_first = -1;

            MATCH_PER_STREAM_OPT(top_field_first, i, ist->top_field_first, ic, st);



            break;

        case AVMEDIA_TYPE_AUDIO:

            ist->guess_layout_max = INT_MAX;

            MATCH_PER_STREAM_OPT(guess_layout_max, i, ist->guess_layout_max, ic, st);

            guess_input_channel_layout(ist);



            ist->resample_sample_fmt     = dec->sample_fmt;

            ist->resample_sample_rate    = dec->sample_rate;

            ist->resample_channels       = dec->channels;

            ist->resample_channel_layout = dec->channel_layout;



            break;

        case AVMEDIA_TYPE_DATA:

        case AVMEDIA_TYPE_SUBTITLE:

            if(!ist->dec)

                ist->dec = avcodec_find_decoder(dec->codec_id);

            MATCH_PER_STREAM_OPT(fix_sub_duration, i, ist->fix_sub_duration, ic, st);

            break;

        case AVMEDIA_TYPE_ATTACHMENT:

        case AVMEDIA_TYPE_UNKNOWN:

            break;

        default:

            abort();

        }

    }

}

static av_cold int asink_init(AVFilterContext *ctx, void *opaque)

{

    BufferSinkContext *buf = ctx->priv;

    AVABufferSinkParams *params = opaque;



    if (params && params->sample_fmts) {

        buf->sample_fmts = ff_copy_int_list(params->sample_fmts);

        if (!buf->sample_fmts)

            return AVERROR(ENOMEM);

    }

    if (params && params->sample_rates) {

        buf->sample_rates = ff_copy_int_list(params->sample_rates);

        if (!buf->sample_rates)

            return AVERROR(ENOMEM);

    }

    if (params && (params->channel_layouts || params->channel_counts)) {

        if (params->all_channel_counts) {

            av_log(ctx, AV_LOG_ERROR,

                   "Conflicting all_channel_counts and list in parameters\n");

            return AVERROR(EINVAL);

        }

        buf->channel_layouts = concat_channels_lists(params->channel_layouts,

                                                     params->channel_counts);

        if (!buf->channel_layouts)

            return AVERROR(ENOMEM);

    }

    if (params)

        buf->all_channel_counts = params->all_channel_counts;

    return common_init(ctx);

}

static av_cold int set_channel_info(AC3EncodeContext *s, int channels,

                                    int64_t *channel_layout)

{

    int ch_layout;



    if (channels < 1 || channels > AC3_MAX_CHANNELS)

        return AVERROR(EINVAL);

    if ((uint64_t)*channel_layout > 0x7FF)

        return AVERROR(EINVAL);

    ch_layout = *channel_layout;

    if (!ch_layout)

        ch_layout = avcodec_guess_channel_layout(channels, CODEC_ID_AC3, NULL);

    if (av_get_channel_layout_nb_channels(ch_layout) != channels)

        return AVERROR(EINVAL);



    s->lfe_on       = !!(ch_layout & AV_CH_LOW_FREQUENCY);

    s->channels     = channels;

    s->fbw_channels = channels - s->lfe_on;

    s->lfe_channel  = s->lfe_on ? s->fbw_channels : -1;

    if (s->lfe_on)

        ch_layout -= AV_CH_LOW_FREQUENCY;



    switch (ch_layout) {

    case AV_CH_LAYOUT_MONO:           s->channel_mode = AC3_CHMODE_MONO;   break;

    case AV_CH_LAYOUT_STEREO:         s->channel_mode = AC3_CHMODE_STEREO; break;

    case AV_CH_LAYOUT_SURROUND:       s->channel_mode = AC3_CHMODE_3F;     break;

    case AV_CH_LAYOUT_2_1:            s->channel_mode = AC3_CHMODE_2F1R;   break;

    case AV_CH_LAYOUT_4POINT0:        s->channel_mode = AC3_CHMODE_3F1R;   break;

    case AV_CH_LAYOUT_QUAD:

    case AV_CH_LAYOUT_2_2:            s->channel_mode = AC3_CHMODE_2F2R;   break;

    case AV_CH_LAYOUT_5POINT0:

    case AV_CH_LAYOUT_5POINT0_BACK:   s->channel_mode = AC3_CHMODE_3F2R;   break;

    default:

        return AVERROR(EINVAL);

    }

    s->has_center   = (s->channel_mode & 0x01) && s->channel_mode != AC3_CHMODE_MONO;

    s->has_surround =  s->channel_mode & 0x04;



    s->channel_map  = ff_ac3_enc_channel_map[s->channel_mode][s->lfe_on];

    *channel_layout = ch_layout;

    if (s->lfe_on)

        *channel_layout |= AV_CH_LOW_FREQUENCY;



    return 0;

}

static int cinepak_decode (CinepakContext *s)

{

    uint8_t      *eod = (s->data + s->size);

    int           i, result, strip_size, frame_flags, num_strips;

    int           y0 = 0;

    int           encoded_buf_size;

    /* if true, Cinepak data is from a Sega FILM/CPK file */

    int           sega_film_data = 0;



    if (s->size < 10)

        return -1;



    frame_flags = s->data[0];

    num_strips  = BE_16 (&s->data[8]);

    encoded_buf_size = ((s->data[1] << 16) | BE_16 (&s->data[2]));

    if (encoded_buf_size != s->size)

        sega_film_data = 1;

    if (sega_film_data)

        s->data    += 12;

    else

        s->data    += 10;



    if (num_strips > MAX_STRIPS)

        num_strips = MAX_STRIPS;



    for (i=0; i < num_strips; i++) {

        if ((s->data + 12) > eod)

            return -1;



        s->strips[i].id = BE_16 (s->data);

        s->strips[i].y1 = y0;

        s->strips[i].x1 = 0;

        s->strips[i].y2 = y0 + BE_16 (&s->data[8]);

        s->strips[i].x2 = s->avctx->width;



        strip_size = BE_16 (&s->data[2]) - 12;

        s->data   += 12;

        strip_size = ((s->data + strip_size) > eod) ? (eod - s->data) : strip_size;



        if ((i > 0) && !(frame_flags & 0x01)) {

            memcpy (s->strips[i].v4_codebook, s->strips[i-1].v4_codebook,

                sizeof(s->strips[i].v4_codebook));

            memcpy (s->strips[i].v1_codebook, s->strips[i-1].v1_codebook,

                sizeof(s->strips[i].v1_codebook));

        }



        result = cinepak_decode_strip (s, &s->strips[i], s->data, strip_size);



        if (result != 0)

            return result;



        s->data += strip_size;

        y0    = s->strips[i].y2;

    }

    return 0;

}

int configure_filtergraph(FilterGraph *fg)

{

    AVFilterInOut *inputs, *outputs, *cur;

    int ret, i, simple = !fg->graph_desc;

    const char *graph_desc = simple ? fg->outputs[0]->ost->avfilter :

                                      fg->graph_desc;



    avfilter_graph_free(&fg->graph);

    if (!(fg->graph = avfilter_graph_alloc()))

        return AVERROR(ENOMEM);



    if (simple) {

        OutputStream *ost = fg->outputs[0]->ost;

        char args[512];

        AVDictionaryEntry *e = NULL;



        args[0] = 0;

        while ((e = av_dict_get(ost->sws_dict, "", e,

                                AV_DICT_IGNORE_SUFFIX))) {

            av_strlcatf(args, sizeof(args), "%s=%s:", e->key, e->value);

        }

        if (strlen(args))

            args[strlen(args)-1] = 0;

        fg->graph->scale_sws_opts = av_strdup(args);



        args[0] = 0;

        while ((e = av_dict_get(ost->swr_opts, "", e,

                                AV_DICT_IGNORE_SUFFIX))) {

            av_strlcatf(args, sizeof(args), "%s=%s:", e->key, e->value);

        }

        if (strlen(args))

            args[strlen(args)-1] = 0;

        av_opt_set(fg->graph, "aresample_swr_opts", args, 0);



        args[0] = '\0';

        while ((e = av_dict_get(fg->outputs[0]->ost->resample_opts, "", e,

                                AV_DICT_IGNORE_SUFFIX))) {

            av_strlcatf(args, sizeof(args), "%s=%s:", e->key, e->value);

        }

        if (strlen(args))

            args[strlen(args) - 1] = '\0';

        fg->graph->resample_lavr_opts = av_strdup(args);



        e = av_dict_get(ost->encoder_opts, "threads", NULL, 0);

        if (e)

            av_opt_set(fg->graph, "threads", e->value, 0);

    }



    if ((ret = avfilter_graph_parse2(fg->graph, graph_desc, &inputs, &outputs)) < 0)

        return ret;



    if (simple && (!inputs || inputs->next || !outputs || outputs->next)) {

        const char *num_inputs;

        const char *num_outputs;

        if (!outputs) {

            num_outputs = "0";

        } else if (outputs->next) {

            num_outputs = ">1";

        } else {

            num_outputs = "1";

        }

        if (!inputs) {

            num_inputs = "0";

        } else if (inputs->next) {

            num_inputs = ">1";

        } else {

            num_inputs = "1";

        }

        av_log(NULL, AV_LOG_ERROR, "Simple filtergraph '%s' was expected "

               "to have exactly 1 input and 1 output."

               " However, it had %s input(s) and %s output(s)."

               " Please adjust, or use a complex filtergraph (-filter_complex) instead.\n",

               graph_desc, num_inputs, num_outputs);

        return AVERROR(EINVAL);

    }



    for (cur = inputs, i = 0; cur; cur = cur->next, i++)

        if ((ret = configure_input_filter(fg, fg->inputs[i], cur)) < 0) {

            avfilter_inout_free(&inputs);

            avfilter_inout_free(&outputs);

            return ret;

        }

    avfilter_inout_free(&inputs);



    for (cur = outputs, i = 0; cur; cur = cur->next, i++)

        configure_output_filter(fg, fg->outputs[i], cur);

    avfilter_inout_free(&outputs);



    if ((ret = avfilter_graph_config(fg->graph, NULL)) < 0)

        return ret;



    fg->reconfiguration = 1;



    for (i = 0; i < fg->nb_outputs; i++) {

        OutputStream *ost = fg->outputs[i]->ost;

        if (!ost->enc) {

            /* identical to the same check in ffmpeg.c, needed because

               complex filter graphs are initialized earlier */

            av_log(NULL, AV_LOG_ERROR, "Encoder (codec %s) not found for output stream #%d:%d\n",

                     avcodec_get_name(ost->st->codec->codec_id), ost->file_index, ost->index);

            return AVERROR(EINVAL);

        }

        if (ost &&

            ost->enc->type == AVMEDIA_TYPE_AUDIO &&

            !(ost->enc->capabilities & AV_CODEC_CAP_VARIABLE_FRAME_SIZE))

            av_buffersink_set_frame_size(ost->filter->filter,

                                         ost->enc_ctx->frame_size);

    }



    return 0;

}

static int flv_write_packet(AVFormatContext *s, AVPacket *pkt)

{

    AVIOContext *pb      = s->pb;

    AVCodecContext *enc  = s->streams[pkt->stream_index]->codec;

    FLVContext *flv      = s->priv_data;

    FLVStreamContext *sc = s->streams[pkt->stream_index]->priv_data;

    unsigned ts;

    int size = pkt->size;

    uint8_t *data = NULL;

    int flags = 0, flags_size;



    if (enc->codec_id == AV_CODEC_ID_VP6F || enc->codec_id == AV_CODEC_ID_VP6A ||

        enc->codec_id == AV_CODEC_ID_AAC)

        flags_size = 2;

    else if (enc->codec_id == AV_CODEC_ID_H264)

        flags_size = 5;

    else

        flags_size = 1;



    if (flv->delay == AV_NOPTS_VALUE)

        flv->delay = -pkt->dts;



    if (pkt->dts < -flv->delay) {

        av_log(s, AV_LOG_WARNING,

               "Packets are not in the proper order with respect to DTS\n");

        return AVERROR(EINVAL);

    }



    ts = pkt->dts + flv->delay; // add delay to force positive dts



    if (s->event_flags & AVSTREAM_EVENT_FLAG_METADATA_UPDATED) {

        write_metadata(s, ts);

        s->event_flags &= ~AVSTREAM_EVENT_FLAG_METADATA_UPDATED;

    }



    switch (enc->codec_type) {

    case AVMEDIA_TYPE_VIDEO:

        avio_w8(pb, FLV_TAG_TYPE_VIDEO);



        flags = enc->codec_tag;

        if (flags == 0) {

            av_log(s, AV_LOG_ERROR,

                   "video codec %X not compatible with flv\n",

                   enc->codec_id);

            return -1;

        }



        flags |= pkt->flags & AV_PKT_FLAG_KEY ? FLV_FRAME_KEY : FLV_FRAME_INTER;

        break;

    case AVMEDIA_TYPE_AUDIO:

        flags = get_audio_flags(s, enc);



        assert(size);



        avio_w8(pb, FLV_TAG_TYPE_AUDIO);

        break;

    case AVMEDIA_TYPE_DATA:

        avio_w8(pb, FLV_TAG_TYPE_META);

        break;

    default:

        return AVERROR(EINVAL);

    }



    if (enc->codec_id == AV_CODEC_ID_H264)

        /* check if extradata looks like MP4 */

        if (enc->extradata_size > 0 && *(uint8_t*)enc->extradata != 1)

            if (ff_avc_parse_nal_units_buf(pkt->data, &data, &size) < 0)

                return -1;



    /* check Speex packet duration */

    if (enc->codec_id == AV_CODEC_ID_SPEEX && ts - sc->last_ts > 160)

        av_log(s, AV_LOG_WARNING, "Warning: Speex stream has more than "

                                  "8 frames per packet. Adobe Flash "

                                  "Player cannot handle this!\n");



    if (sc->last_ts < ts)

        sc->last_ts = ts;



    avio_wb24(pb, size + flags_size);

    avio_wb24(pb, ts);

    avio_w8(pb, (ts >> 24) & 0x7F); // timestamps are 32 bits _signed_

    avio_wb24(pb, flv->reserved);



    if (enc->codec_type == AVMEDIA_TYPE_DATA) {

        int data_size;

        int64_t metadata_size_pos = avio_tell(pb);

        avio_w8(pb, AMF_DATA_TYPE_STRING);

        put_amf_string(pb, "onTextData");

        avio_w8(pb, AMF_DATA_TYPE_MIXEDARRAY);

        avio_wb32(pb, 2);

        put_amf_string(pb, "type");

        avio_w8(pb, AMF_DATA_TYPE_STRING);

        put_amf_string(pb, "Text");

        put_amf_string(pb, "text");

        avio_w8(pb, AMF_DATA_TYPE_STRING);

        put_amf_string(pb, pkt->data);

        put_amf_string(pb, "");

        avio_w8(pb, AMF_END_OF_OBJECT);

        /* write total size of tag */

        data_size = avio_tell(pb) - metadata_size_pos;

        avio_seek(pb, metadata_size_pos - 10, SEEK_SET);

        avio_wb24(pb, data_size);

        avio_seek(pb, data_size + 10 - 3, SEEK_CUR);

        avio_wb32(pb, data_size + 11);

    } else {

        avio_w8(pb,flags);

        if (enc->codec_id == AV_CODEC_ID_VP6F || enc->codec_id == AV_CODEC_ID_VP6A) {

            if (enc->extradata_size)

                avio_w8(pb, enc->extradata[0]);

            else

                avio_w8(pb, ((FFALIGN(enc->width,  16) - enc->width) << 4) |

                             (FFALIGN(enc->height, 16) - enc->height));

        } else if (enc->codec_id == AV_CODEC_ID_AAC)

            avio_w8(pb, 1); // AAC raw

        else if (enc->codec_id == AV_CODEC_ID_H264) {

            avio_w8(pb, 1); // AVC NALU

            avio_wb24(pb, pkt->pts - pkt->dts);

        }



        avio_write(pb, data ? data : pkt->data, size);



        avio_wb32(pb, size + flags_size + 11); // previous tag size

        flv->duration = FFMAX(flv->duration,

                              pkt->pts + flv->delay + pkt->duration);

    }



    av_free(data);



    return pb->error;

}

matroska_probe (AVProbeData *p)

{

    uint64_t total = 0;

    int len_mask = 0x80, size = 1, n = 1;

    uint8_t probe_data[] = { 'm', 'a', 't', 'r', 'o', 's', 'k', 'a' };



    if (p->buf_size < 5)

        return 0;



    /* ebml header? */

    if ((p->buf[0] << 24 | p->buf[1] << 16 |

         p->buf[2] << 8 | p->buf[3]) != EBML_ID_HEADER)

        return 0;



    /* length of header */

    total = p->buf[4];

    while (size <= 8 && !(total & len_mask)) {

        size++;

        len_mask >>= 1;

    }

    if (size > 8)

      return 0;

    total &= (len_mask - 1);

    while (n < size)

        total = (total << 8) | p->buf[4 + n++];



    /* does the probe data contain the whole header? */

    if (p->buf_size < 4 + size + total)

      return 0;



    /* the header must contain the document type 'matroska'. For now,

     * we don't parse the whole header but simply check for the

     * availability of that array of characters inside the header.

     * Not fully fool-proof, but good enough. */

    for (n = 4 + size; n <= 4 + size + total - sizeof(probe_data); n++)

        if (!memcmp (&p->buf[n], probe_data, sizeof(probe_data)))

            return AVPROBE_SCORE_MAX;



    return 0;

}

static int siff_read_packet(AVFormatContext *s, AVPacket *pkt)

{

    SIFFContext *c = s->priv_data;

    int size;



    if (c->has_video){

        if (c->cur_frame >= c->frames)

            return AVERROR_EOF;

        if (c->curstrm == -1){

            c->pktsize = avio_rl32(s->pb) - 4;

            c->flags = avio_rl16(s->pb);

            c->gmcsize = (c->flags & VB_HAS_GMC) ? 4 : 0;

            if (c->gmcsize)

                avio_read(s->pb, c->gmc, c->gmcsize);

            c->sndsize = (c->flags & VB_HAS_AUDIO) ? avio_rl32(s->pb): 0;

            c->curstrm = !!(c->flags & VB_HAS_AUDIO);

        }



        if (!c->curstrm){

            size = c->pktsize - c->sndsize - c->gmcsize - 2;

            size = ffio_limit(s->pb, size);

            if(size < 0 || c->pktsize < c->sndsize)

                return AVERROR_INVALIDDATA;

            if (av_new_packet(pkt, size + c->gmcsize + 2) < 0)

                return AVERROR(ENOMEM);

            AV_WL16(pkt->data, c->flags);

            if (c->gmcsize)

                memcpy(pkt->data + 2, c->gmc, c->gmcsize);

            avio_read(s->pb, pkt->data + 2 + c->gmcsize, size);

            pkt->stream_index = 0;

            c->curstrm = -1;

        }else{

            if ((size = av_get_packet(s->pb, pkt, c->sndsize - 4)) < 0)

                return AVERROR(EIO);

            pkt->stream_index = 1;

            pkt->duration     = size;

            c->curstrm = 0;

        }

        if(!c->cur_frame || c->curstrm)

            pkt->flags |= AV_PKT_FLAG_KEY;

        if (c->curstrm == -1)

            c->cur_frame++;

    }else{

        size = av_get_packet(s->pb, pkt, c->block_align);

        if(!size)

            return AVERROR_EOF;

        if(size < 0)

            return AVERROR(EIO);

        pkt->duration = size;

    }

    return pkt->size;

}

static void dequantization_float(int x, int y, Jpeg2000Cblk *cblk,

                                 Jpeg2000Component *comp,

                                 Jpeg2000T1Context *t1, Jpeg2000Band *band)

{

    int i, j, idx;

    float *datap = &comp->data[(comp->coord[0][1] - comp->coord[0][0]) * y + x];

    for (j = 0; j < (cblk->coord[1][1] - cblk->coord[1][0]); ++j)

        for (i = 0; i < (cblk->coord[0][1] - cblk->coord[0][0]); ++i) {

            idx        = (comp->coord[0][1] - comp->coord[0][0]) * j + i;

            datap[idx] = (float)(t1->data[j][i]) * band->f_stepsize;

        }

}

