static void intra_predict_vert_8x8_msa(uint8_t *src, uint8_t *dst,

                                       int32_t dst_stride)

{

    uint32_t row;

    uint32_t src_data1, src_data2;



    src_data1 = LW(src);

    src_data2 = LW(src + 4);



    for (row = 8; row--;) {

        SW(src_data1, dst);

        SW(src_data2, (dst + 4));

        dst += dst_stride;

    }

}

static int swr_convert_internal(struct SwrContext *s, AudioData *out, int out_count,

                                                      AudioData *in , int  in_count){

    AudioData *postin, *midbuf, *preout;

    int ret/*, in_max*/;

    AudioData preout_tmp, midbuf_tmp;



    if(s->full_convert){

        av_assert0(!s->resample);

        swri_audio_convert(s->full_convert, out, in, in_count);

        return out_count;

    }



//     in_max= out_count*(int64_t)s->in_sample_rate / s->out_sample_rate + resample_filter_taps;

//     in_count= FFMIN(in_count, in_in + 2 - s->hist_buffer_count);



    if((ret=swri_realloc_audio(&s->postin, in_count))<0)

        return ret;

    if(s->resample_first){

        av_assert0(s->midbuf.ch_count == s->used_ch_count);

        if((ret=swri_realloc_audio(&s->midbuf, out_count))<0)

            return ret;

    }else{

        av_assert0(s->midbuf.ch_count ==  s->out.ch_count);

        if((ret=swri_realloc_audio(&s->midbuf,  in_count))<0)

            return ret;

    }

    if((ret=swri_realloc_audio(&s->preout, out_count))<0)

        return ret;



    postin= &s->postin;



    midbuf_tmp= s->midbuf;

    midbuf= &midbuf_tmp;

    preout_tmp= s->preout;

    preout= &preout_tmp;



    if(s->int_sample_fmt == s-> in_sample_fmt && s->in.planar && !s->channel_map)

        postin= in;



    if(s->resample_first ? !s->resample : !s->rematrix)

        midbuf= postin;



    if(s->resample_first ? !s->rematrix : !s->resample)

        preout= midbuf;



    if(s->int_sample_fmt == s->out_sample_fmt && s->out.planar

       && !(s->out_sample_fmt==AV_SAMPLE_FMT_S32P && (s->dither.output_sample_bits&31))){

        if(preout==in){

            out_count= FFMIN(out_count, in_count); //TODO check at the end if this is needed or redundant

            av_assert0(s->in.planar); //we only support planar internally so it has to be, we support copying non planar though

            copy(out, in, out_count);

            return out_count;

        }

        else if(preout==postin) preout= midbuf= postin= out;

        else if(preout==midbuf) preout= midbuf= out;

        else                    preout= out;

    }



    if(in != postin){

        swri_audio_convert(s->in_convert, postin, in, in_count);

    }



    if(s->resample_first){

        if(postin != midbuf)

            out_count= resample(s, midbuf, out_count, postin, in_count);

        if(midbuf != preout)

            swri_rematrix(s, preout, midbuf, out_count, preout==out);

    }else{

        if(postin != midbuf)

            swri_rematrix(s, midbuf, postin, in_count, midbuf==out);

        if(midbuf != preout)

            out_count= resample(s, preout, out_count, midbuf, in_count);

    }



    if(preout != out && out_count){

        AudioData *conv_src = preout;

        if(s->dither.method){

            int ch;

            int dither_count= FFMAX(out_count, 1<<16);



            if (preout == in) {

                conv_src = &s->dither.temp;

                if((ret=swri_realloc_audio(&s->dither.temp, dither_count))<0)

                    return ret;

            }



            if((ret=swri_realloc_audio(&s->dither.noise, dither_count))<0)

                return ret;

            if(ret)

                for(ch=0; ch<s->dither.noise.ch_count; ch++)

                    swri_get_dither(s, s->dither.noise.ch[ch], s->dither.noise.count, 12345678913579<<ch, s->dither.noise.fmt);

            av_assert0(s->dither.noise.ch_count == preout->ch_count);



            if(s->dither.noise_pos + out_count > s->dither.noise.count)

                s->dither.noise_pos = 0;



            if (s->dither.method < SWR_DITHER_NS){

                if (s->mix_2_1_simd) {

                    int len1= out_count&~15;

                    int off = len1 * preout->bps;



                    if(len1)

                        for(ch=0; ch<preout->ch_count; ch++)

                            s->mix_2_1_simd(conv_src->ch[ch], preout->ch[ch], s->dither.noise.ch[ch] + s->dither.noise.bps * s->dither.noise_pos, s->native_simd_one, 0, 0, len1);

                    if(out_count != len1)

                        for(ch=0; ch<preout->ch_count; ch++)

                            s->mix_2_1_f(conv_src->ch[ch] + off, preout->ch[ch] + off, s->dither.noise.ch[ch] + s->dither.noise.bps * s->dither.noise_pos + off + len1, s->native_one, 0, 0, out_count - len1);

                } else {

                    for(ch=0; ch<preout->ch_count; ch++)

                        s->mix_2_1_f(conv_src->ch[ch], preout->ch[ch], s->dither.noise.ch[ch] + s->dither.noise.bps * s->dither.noise_pos, s->native_one, 0, 0, out_count);

                }

            } else {

                switch(s->int_sample_fmt) {

                case AV_SAMPLE_FMT_S16P :swri_noise_shaping_int16(s, conv_src, preout, &s->dither.noise, out_count); break;

                case AV_SAMPLE_FMT_S32P :swri_noise_shaping_int32(s, conv_src, preout, &s->dither.noise, out_count); break;

                case AV_SAMPLE_FMT_FLTP :swri_noise_shaping_float(s, conv_src, preout, &s->dither.noise, out_count); break;

                case AV_SAMPLE_FMT_DBLP :swri_noise_shaping_double(s,conv_src, preout, &s->dither.noise, out_count); break;

                }

            }

            s->dither.noise_pos += out_count;

        }

//FIXME packed doesn't need more than 1 chan here!

        swri_audio_convert(s->out_convert, out, conv_src, out_count);

    }

    return out_count;

}

static int asf_parse_packet(AVFormatContext *s, AVIOContext *pb, AVPacket *pkt)

{

    ASFContext *asf   = s->priv_data;

    ASFStream *asf_st = 0;

    for (;;) {

        int ret;

        if (url_feof(pb))

            return AVERROR_EOF;



        if (asf->packet_size_left < FRAME_HEADER_SIZE) {

            int ret = asf->packet_size_left + asf->packet_padsize;



            assert(ret >= 0);

            /* fail safe */

            avio_skip(pb, ret);



            asf->packet_pos = avio_tell(pb);

            if (asf->data_object_size != (uint64_t)-1 &&

                (asf->packet_pos - asf->data_object_offset >= asf->data_object_size))

                return AVERROR_EOF;  /* Do not exceed the size of the data object */

            return 1;

        }

        if (asf->packet_time_start == 0) {

            if (asf_read_frame_header(s, pb) < 0) {

                asf->packet_time_start = asf->packet_segments = 0;

                continue;

            }

            if (asf->stream_index < 0 ||

                s->streams[asf->stream_index]->discard >= AVDISCARD_ALL ||

                (!asf->packet_key_frame &&

                 (s->streams[asf->stream_index]->discard >= AVDISCARD_NONKEY || asf->streams[s->streams[asf->stream_index]->id].skip_to_key))) {

                asf->packet_time_start = 0;

                /* unhandled packet (should not happen) */

                avio_skip(pb, asf->packet_frag_size);

                asf->packet_size_left -= asf->packet_frag_size;

                if (asf->stream_index < 0)

                    av_log(s, AV_LOG_ERROR, "ff asf skip %d (unknown stream)\n",

                           asf->packet_frag_size);

                continue;

            }

            asf->asf_st = &asf->streams[s->streams[asf->stream_index]->id];

            asf->asf_st->skip_to_key = 0;

        }

        asf_st = asf->asf_st;

        av_assert0(asf_st);



        if (asf->packet_replic_size == 1) {

            // frag_offset is here used as the beginning timestamp

            asf->packet_frag_timestamp = asf->packet_time_start;

            asf->packet_time_start    += asf->packet_time_delta;

            asf_st->packet_obj_size    = asf->packet_frag_size = avio_r8(pb);

            asf->packet_size_left--;

            asf->packet_multi_size--;

            if (asf->packet_multi_size < asf_st->packet_obj_size) {

                asf->packet_time_start = 0;

                avio_skip(pb, asf->packet_multi_size);

                asf->packet_size_left -= asf->packet_multi_size;

                continue;

            }

            asf->packet_multi_size -= asf_st->packet_obj_size;

        }



        if (asf_st->pkt.size != asf_st->packet_obj_size ||

            // FIXME is this condition sufficient?

            asf_st->frag_offset + asf->packet_frag_size > asf_st->pkt.size) {

            if (asf_st->pkt.data) {

                av_log(s, AV_LOG_INFO,

                       "freeing incomplete packet size %d, new %d\n",

                       asf_st->pkt.size, asf_st->packet_obj_size);

                asf_st->frag_offset = 0;

                av_free_packet(&asf_st->pkt);

            }

            /* new packet */

            av_new_packet(&asf_st->pkt, asf_st->packet_obj_size);

            asf_st->seq              = asf->packet_seq;

            asf_st->pkt.dts          = asf->packet_frag_timestamp - asf->hdr.preroll;

            asf_st->pkt.stream_index = asf->stream_index;

            asf_st->pkt.pos          = asf_st->packet_pos = asf->packet_pos;




            if (asf_st->pkt.data && asf_st->palette_changed) {

                uint8_t *pal;

                pal = av_packet_new_side_data(&asf_st->pkt, AV_PKT_DATA_PALETTE,

                                              AVPALETTE_SIZE);

                if (!pal) {

                    av_log(s, AV_LOG_ERROR, "Cannot append palette to packet\n");

                } else {

                    memcpy(pal, asf_st->palette, AVPALETTE_SIZE);

                    asf_st->palette_changed = 0;

                }

            }

            av_dlog(asf, "new packet: stream:%d key:%d packet_key:%d audio:%d size:%d\n",

                    asf->stream_index, asf->packet_key_frame,

                    asf_st->pkt.flags & AV_PKT_FLAG_KEY,

                    s->streams[asf->stream_index]->codec->codec_type == AVMEDIA_TYPE_AUDIO,

                    asf_st->packet_obj_size);

            if (s->streams[asf->stream_index]->codec->codec_type == AVMEDIA_TYPE_AUDIO)

                asf->packet_key_frame = 1;

            if (asf->packet_key_frame)

                asf_st->pkt.flags |= AV_PKT_FLAG_KEY;

        }



        /* read data */

        av_dlog(asf, "READ PACKET s:%d  os:%d  o:%d,%d  l:%d   DATA:%p\n",

                s->packet_size, asf_st->pkt.size, asf->packet_frag_offset,

                asf_st->frag_offset, asf->packet_frag_size, asf_st->pkt.data);

        asf->packet_size_left -= asf->packet_frag_size;

        if (asf->packet_size_left < 0)

            continue;



        if (asf->packet_frag_offset >= asf_st->pkt.size ||

            asf->packet_frag_size > asf_st->pkt.size - asf->packet_frag_offset) {

            av_log(s, AV_LOG_ERROR,

                   "packet fragment position invalid %u,%u not in %u\n",

                   asf->packet_frag_offset, asf->packet_frag_size,

                   asf_st->pkt.size);

            continue;

        }



        if (asf->packet_frag_offset != asf_st->frag_offset && !asf_st->pkt_clean) {

            memset(asf_st->pkt.data + asf_st->frag_offset, 0, asf_st->pkt.size - asf_st->frag_offset);

            asf_st->pkt_clean = 1;

        }



        ret = avio_read(pb, asf_st->pkt.data + asf->packet_frag_offset,

                        asf->packet_frag_size);

        if (ret != asf->packet_frag_size) {

            if (ret < 0 || asf->packet_frag_offset + ret == 0)

                return ret < 0 ? ret : AVERROR_EOF;



            if (asf_st->ds_span > 1) {

                // scrambling, we can either drop it completely or fill the remainder

                // TODO: should we fill the whole packet instead of just the current

                // fragment?

                memset(asf_st->pkt.data + asf->packet_frag_offset + ret, 0,

                       asf->packet_frag_size - ret);

                ret = asf->packet_frag_size;

            } else {

                // no scrambling, so we can return partial packets

                av_shrink_packet(&asf_st->pkt, asf->packet_frag_offset + ret);

            }

        }

        if (s->key && s->keylen == 20)

            ff_asfcrypt_dec(s->key, asf_st->pkt.data + asf->packet_frag_offset,

                            ret);

        asf_st->frag_offset += ret;

        /* test if whole packet is read */

        if (asf_st->frag_offset == asf_st->pkt.size) {

            // workaround for macroshit radio DVR-MS files

            if (s->streams[asf->stream_index]->codec->codec_id == AV_CODEC_ID_MPEG2VIDEO &&

                asf_st->pkt.size > 100) {

                int i;

                for (i = 0; i < asf_st->pkt.size && !asf_st->pkt.data[i]; i++)

                    ;

                if (i == asf_st->pkt.size) {

                    av_log(s, AV_LOG_DEBUG, "discarding ms fart\n");

                    asf_st->frag_offset = 0;

                    av_free_packet(&asf_st->pkt);

                    continue;

                }

            }



            /* return packet */

            if (asf_st->ds_span > 1) {

                if (asf_st->pkt.size != asf_st->ds_packet_size * asf_st->ds_span) {

                    av_log(s, AV_LOG_ERROR,

                           "pkt.size != ds_packet_size * ds_span (%d %d %d)\n",

                           asf_st->pkt.size, asf_st->ds_packet_size,

                           asf_st->ds_span);

                } else {

                    /* packet descrambling */

                    AVBufferRef *buf = av_buffer_alloc(asf_st->pkt.size +

                                                       FF_INPUT_BUFFER_PADDING_SIZE);

                    if (buf) {

                        uint8_t *newdata = buf->data;

                        int offset = 0;

                        memset(newdata + asf_st->pkt.size, 0,

                               FF_INPUT_BUFFER_PADDING_SIZE);

                        while (offset < asf_st->pkt.size) {

                            int off = offset / asf_st->ds_chunk_size;

                            int row = off / asf_st->ds_span;

                            int col = off % asf_st->ds_span;

                            int idx = row + col * asf_st->ds_packet_size / asf_st->ds_chunk_size;

                            assert(offset + asf_st->ds_chunk_size <= asf_st->pkt.size);

                            assert(idx + 1 <= asf_st->pkt.size / asf_st->ds_chunk_size);

                            memcpy(newdata + offset,

                                   asf_st->pkt.data + idx * asf_st->ds_chunk_size,

                                   asf_st->ds_chunk_size);

                            offset += asf_st->ds_chunk_size;

                        }

                        av_buffer_unref(&asf_st->pkt.buf);

                        asf_st->pkt.buf  = buf;

                        asf_st->pkt.data = buf->data;

                    }

                }

            }

            asf_st->frag_offset         = 0;

            *pkt                        = asf_st->pkt;

#if FF_API_DESTRUCT_PACKET

FF_DISABLE_DEPRECATION_WARNINGS

            asf_st->pkt.destruct        = NULL;

FF_ENABLE_DEPRECATION_WARNINGS

#endif

            asf_st->pkt.buf             = 0;

            asf_st->pkt.size            = 0;

            asf_st->pkt.data            = 0;

            asf_st->pkt.side_data_elems = 0;

            asf_st->pkt.side_data       = NULL;

            break; // packet completed

        }

    }

    return 0;

}

static int flic_decode_frame_8BPP(AVCodecContext *avctx,

                                  void *data, int *data_size,

                                  uint8_t *buf, int buf_size)

{

    FlicDecodeContext *s = (FlicDecodeContext *)avctx->priv_data;



    int stream_ptr = 0;

    int stream_ptr_after_color_chunk;

    int pixel_ptr;

    int palette_ptr;

    unsigned char palette_idx1;

    unsigned char palette_idx2;



    unsigned int frame_size;

    int num_chunks;



    unsigned int chunk_size;

    int chunk_type;



    int i, j;



    int color_packets;

    int color_changes;

    int color_shift;

    unsigned char r, g, b;



    int lines;

    int compressed_lines;

    int starting_line;

    signed short line_packets;

    int y_ptr;

    signed char byte_run;

    int pixel_skip;

    int pixel_countdown;

    unsigned char *pixels;

    int pixel_limit;



    s->frame.reference = 1;

    s->frame.buffer_hints = FF_BUFFER_HINTS_VALID | FF_BUFFER_HINTS_PRESERVE | FF_BUFFER_HINTS_REUSABLE;

    if (avctx->reget_buffer(avctx, &s->frame) < 0) {

        av_log(avctx, AV_LOG_ERROR, "reget_buffer() failed\n");

        return -1;

    }



    pixels = s->frame.data[0];

    pixel_limit = s->avctx->height * s->frame.linesize[0];



    frame_size = LE_32(&buf[stream_ptr]);

    stream_ptr += 6;  /* skip the magic number */

    num_chunks = LE_16(&buf[stream_ptr]);

    stream_ptr += 10;  /* skip padding */



    frame_size -= 16;



    /* iterate through the chunks */

    while ((frame_size > 0) && (num_chunks > 0)) {

        chunk_size = LE_32(&buf[stream_ptr]);

        stream_ptr += 4;

        chunk_type = LE_16(&buf[stream_ptr]);

        stream_ptr += 2;



        switch (chunk_type) {

        case FLI_256_COLOR:

        case FLI_COLOR:

            stream_ptr_after_color_chunk = stream_ptr + chunk_size - 6;



            /* check special case: If this file is from the Magic Carpet

             * game and uses 6-bit colors even though it reports 256-color

             * chunks in a 0xAF12-type file (fli_type is set to 0xAF13 during

             * initialization) */

            if ((chunk_type == FLI_256_COLOR) && (s->fli_type != FLC_MAGIC_CARPET_SYNTHETIC_TYPE_CODE))

                color_shift = 0;

            else

                color_shift = 2;

            /* set up the palette */

            color_packets = LE_16(&buf[stream_ptr]);

            stream_ptr += 2;

            palette_ptr = 0;

            for (i = 0; i < color_packets; i++) {

                /* first byte is how many colors to skip */

                palette_ptr += buf[stream_ptr++];



                /* next byte indicates how many entries to change */

                color_changes = buf[stream_ptr++];



                /* if there are 0 color changes, there are actually 256 */

                if (color_changes == 0)

                    color_changes = 256;



                for (j = 0; j < color_changes; j++) {

                    unsigned int entry;



                    /* wrap around, for good measure */

                    if ((unsigned)palette_ptr >= 256)

                        palette_ptr = 0;



                    r = buf[stream_ptr++] << color_shift;

                    g = buf[stream_ptr++] << color_shift;

                    b = buf[stream_ptr++] << color_shift;

                    entry = (r << 16) | (g << 8) | b;

                    if (s->palette[palette_ptr] != entry)

                        s->new_palette = 1;

                    s->palette[palette_ptr++] = entry;

                }

            }



            /* color chunks sometimes have weird 16-bit alignment issues;

             * therefore, take the hardline approach and set the stream_ptr

             * to the value calculated w.r.t. the size specified by the color

             * chunk header */

            stream_ptr = stream_ptr_after_color_chunk;



            break;



        case FLI_DELTA:

            y_ptr = 0;

            compressed_lines = LE_16(&buf[stream_ptr]);

            stream_ptr += 2;

            while (compressed_lines > 0) {

                line_packets = LE_16(&buf[stream_ptr]);

                stream_ptr += 2;

                if (line_packets < 0) {

                    line_packets = -line_packets;

                    y_ptr += line_packets * s->frame.linesize[0];

                } else {

                    compressed_lines--;

                    pixel_ptr = y_ptr;

                    pixel_countdown = s->avctx->width;

                    for (i = 0; i < line_packets; i++) {

                        /* account for the skip bytes */

                        pixel_skip = buf[stream_ptr++];

                        pixel_ptr += pixel_skip;

                        pixel_countdown -= pixel_skip;

                        byte_run = buf[stream_ptr++];

                        if (byte_run < 0) {

                            byte_run = -byte_run;

                            palette_idx1 = buf[stream_ptr++];

                            palette_idx2 = buf[stream_ptr++];

                            CHECK_PIXEL_PTR(byte_run);

                            for (j = 0; j < byte_run; j++, pixel_countdown -= 2) {

                                pixels[pixel_ptr++] = palette_idx1;

                                pixels[pixel_ptr++] = palette_idx2;

                            }

                        } else {

                            CHECK_PIXEL_PTR(byte_run * 2);

                            for (j = 0; j < byte_run * 2; j++, pixel_countdown--) {

                                palette_idx1 = buf[stream_ptr++];

                                pixels[pixel_ptr++] = palette_idx1;

                            }

                        }

                    }



                    y_ptr += s->frame.linesize[0];

                }

            }

            break;



        case FLI_LC:

            /* line compressed */

            starting_line = LE_16(&buf[stream_ptr]);

            stream_ptr += 2;

            y_ptr = 0;

            y_ptr += starting_line * s->frame.linesize[0];



            compressed_lines = LE_16(&buf[stream_ptr]);

            stream_ptr += 2;

            while (compressed_lines > 0) {

                pixel_ptr = y_ptr;

                pixel_countdown = s->avctx->width;

                line_packets = buf[stream_ptr++];

                if (line_packets > 0) {

                    for (i = 0; i < line_packets; i++) {

                        /* account for the skip bytes */

                        pixel_skip = buf[stream_ptr++];

                        pixel_ptr += pixel_skip;

                        pixel_countdown -= pixel_skip;

                        byte_run = buf[stream_ptr++];

                        if (byte_run > 0) {

                            CHECK_PIXEL_PTR(byte_run);

                            for (j = 0; j < byte_run; j++, pixel_countdown--) {

                                palette_idx1 = buf[stream_ptr++];

                                pixels[pixel_ptr++] = palette_idx1;

                            }

                        } else {

                            byte_run = -byte_run;

                            palette_idx1 = buf[stream_ptr++];

                            CHECK_PIXEL_PTR(byte_run);

                            for (j = 0; j < byte_run; j++, pixel_countdown--) {

                                pixels[pixel_ptr++] = palette_idx1;

                            }

                        }

                    }

                }



                y_ptr += s->frame.linesize[0];

                compressed_lines--;

            }

            break;



        case FLI_BLACK:

            /* set the whole frame to color 0 (which is usually black) */

            memset(pixels, 0,

                s->frame.linesize[0] * s->avctx->height);

            break;



        case FLI_BRUN:

            /* Byte run compression: This chunk type only occurs in the first

             * FLI frame and it will update the entire frame. */

            y_ptr = 0;

            for (lines = 0; lines < s->avctx->height; lines++) {

                pixel_ptr = y_ptr;

                /* disregard the line packets; instead, iterate through all

                 * pixels on a row */

                stream_ptr++;

                pixel_countdown = s->avctx->width;

                while (pixel_countdown > 0) {

                    byte_run = buf[stream_ptr++];

                    if (byte_run > 0) {

                        palette_idx1 = buf[stream_ptr++];

                        CHECK_PIXEL_PTR(byte_run);

                        for (j = 0; j < byte_run; j++) {

                            pixels[pixel_ptr++] = palette_idx1;

                            pixel_countdown--;

                            if (pixel_countdown < 0)

                                av_log(avctx, AV_LOG_ERROR, "pixel_countdown < 0 (%d)\n",

                                       pixel_countdown);

                        }

                    } else {  /* copy bytes if byte_run < 0 */

                        byte_run = -byte_run;

                        CHECK_PIXEL_PTR(byte_run);

                        for (j = 0; j < byte_run; j++) {

                            palette_idx1 = buf[stream_ptr++];

                            pixels[pixel_ptr++] = palette_idx1;

                            pixel_countdown--;

                            if (pixel_countdown < 0)

                                av_log(avctx, AV_LOG_ERROR, "pixel_countdown < 0 (%d)\n",

                                       pixel_countdown);

                        }

                    }

                }



                y_ptr += s->frame.linesize[0];

            }

            break;



        case FLI_COPY:

            /* copy the chunk (uncompressed frame) */

            if (chunk_size - 6 > s->avctx->width * s->avctx->height) {

                av_log(avctx, AV_LOG_ERROR, "In chunk FLI_COPY : source data (%d bytes) " \

                       "bigger than image, skipping chunk\n", chunk_size - 6);

                stream_ptr += chunk_size - 6;

            } else {

                for (y_ptr = 0; y_ptr < s->frame.linesize[0] * s->avctx->height;

                     y_ptr += s->frame.linesize[0]) {

                    memcpy(&pixels[y_ptr], &buf[stream_ptr],

                        s->avctx->width);

                    stream_ptr += s->avctx->width;

                }

            }

            break;



        case FLI_MINI:

            /* some sort of a thumbnail? disregard this chunk... */

            stream_ptr += chunk_size - 6;

            break;



        default:

            av_log(avctx, AV_LOG_ERROR, "Unrecognized chunk type: %d\n", chunk_type);

            break;

        }



        frame_size -= chunk_size;

        num_chunks--;

    }



    /* by the end of the chunk, the stream ptr should equal the frame

     * size (minus 1, possibly); if it doesn't, issue a warning */

    if ((stream_ptr != buf_size) && (stream_ptr != buf_size - 1))

        av_log(avctx, AV_LOG_ERROR, "Processed FLI chunk where chunk size = %d " \

               "and final chunk ptr = %d\n", buf_size, stream_ptr);



    /* make the palette available on the way out */

    memcpy(s->frame.data[1], s->palette, AVPALETTE_SIZE);

    if (s->new_palette) {

        s->frame.palette_has_changed = 1;

        s->new_palette = 0;

    }



    *data_size=sizeof(AVFrame);

    *(AVFrame*)data = s->frame;



    return buf_size;

}

int av_probe_input_buffer2(AVIOContext *pb, AVInputFormat **fmt,

                          const char *filename, void *logctx,

                          unsigned int offset, unsigned int max_probe_size)

{

    AVProbeData pd = { filename ? filename : "" };

    uint8_t *buf = NULL;

    uint8_t *mime_type;

    int ret = 0, probe_size, buf_offset = 0;

    int score = 0;



    if (!max_probe_size)

        max_probe_size = PROBE_BUF_MAX;

    else if (max_probe_size < PROBE_BUF_MIN) {

        av_log(logctx, AV_LOG_ERROR,

               "Specified probe size value %u cannot be < %u\n", max_probe_size, PROBE_BUF_MIN);

        return AVERROR(EINVAL);

    }



    if (offset >= max_probe_size)

        return AVERROR(EINVAL);



#ifdef FF_API_PROBE_MIME

    if (pb->av_class)

        av_opt_get(pb, "mime_type", AV_OPT_SEARCH_CHILDREN, &pd.mime_type);

#endif



#if !FF_API_PROBE_MIME

    if (!*fmt && pb->av_class && av_opt_get(pb, "mime_type", AV_OPT_SEARCH_CHILDREN, &mime_type) >= 0 && mime_type) {

        if (!av_strcasecmp(mime_type, "audio/aacp")) {

            *fmt = av_find_input_format("aac");

        }

        av_freep(&mime_type);

    }

#endif



    for (probe_size = PROBE_BUF_MIN; probe_size <= max_probe_size && !*fmt;

         probe_size = FFMIN(probe_size << 1,

                            FFMAX(max_probe_size, probe_size + 1))) {

        score = probe_size < max_probe_size ? AVPROBE_SCORE_RETRY : 0;



        /* Read probe data. */

        if ((ret = av_reallocp(&buf, probe_size + AVPROBE_PADDING_SIZE)) < 0)

            goto fail;

        if ((ret = avio_read(pb, buf + buf_offset,

                             probe_size - buf_offset)) < 0) {

            /* Fail if error was not end of file, otherwise, lower score. */

            if (ret != AVERROR_EOF)

                goto fail;



            score = 0;

            ret   = 0;          /* error was end of file, nothing read */

        }

        buf_offset += ret;

        if (buf_offset < offset)

            continue;

        pd.buf_size = buf_offset - offset;

        pd.buf = &buf[offset];



        memset(pd.buf + pd.buf_size, 0, AVPROBE_PADDING_SIZE);



        /* Guess file format. */

        *fmt = av_probe_input_format2(&pd, 1, &score);

        if (*fmt) {

            /* This can only be true in the last iteration. */

            if (score <= AVPROBE_SCORE_RETRY) {

                av_log(logctx, AV_LOG_WARNING,

                       "Format %s detected only with low score of %d, "

                       "misdetection possible!\n", (*fmt)->name, score);

            } else

                av_log(logctx, AV_LOG_DEBUG,

                       "Format %s probed with size=%d and score=%d\n",

                       (*fmt)->name, probe_size, score);

#if 0

            FILE *f = fopen("probestat.tmp", "ab");

            fprintf(f, "probe_size:%d format:%s score:%d filename:%s\n", probe_size, (*fmt)->name, score, filename);

            fclose(f);

#endif

        }

    }



    if (!*fmt)

        ret = AVERROR_INVALIDDATA;



fail:

    /* Rewind. Reuse probe buffer to avoid seeking. */

    if (ret >= 0)

        ret = ffio_rewind_with_probe_data(pb, &buf, buf_offset);



#ifdef FF_API_PROBE_MIME

    av_free(pd.mime_type);

#endif

    return ret < 0 ? ret : score;

}

static int mjpeg_decode_scan(MJpegDecodeContext *s, int nb_components, int Ah,

                             int Al, const uint8_t *mb_bitmask,

                             const AVFrame *reference)

{

    int i, mb_x, mb_y;

    uint8_t *data[MAX_COMPONENTS];

    const uint8_t *reference_data[MAX_COMPONENTS];

    int linesize[MAX_COMPONENTS];

    GetBitContext mb_bitmask_gb;



    if (mb_bitmask)

        init_get_bits(&mb_bitmask_gb, mb_bitmask, s->mb_width * s->mb_height);



    if (s->flipped && s->avctx->flags & CODEC_FLAG_EMU_EDGE) {

        av_log(s->avctx, AV_LOG_ERROR,

               "Can not flip image with CODEC_FLAG_EMU_EDGE set!\n");

        s->flipped = 0;

    }

    if (s->flipped && s->avctx->lowres) {

        av_log(s->avctx, AV_LOG_ERROR, "Can not flip image with lowres\n");

        s->flipped = 0;

    }



    for (i = 0; i < nb_components; i++) {

        int c   = s->comp_index[i];

        data[c] = s->picture_ptr->data[c];

        reference_data[c] = reference ? reference->data[c] : NULL;

        linesize[c] = s->linesize[c];

        s->coefs_finished[c] |= 1;

        if (s->flipped) {

            // picture should be flipped upside-down for this codec

            int offset = (linesize[c] * (s->v_scount[i] *

                         (8 * s->mb_height - ((s->height / s->v_max) & 7)) - 1));

            data[c]           += offset;

            reference_data[c] += offset;

            linesize[c]       *= -1;

        }

    }



    for (mb_y = 0; mb_y < s->mb_height; mb_y++) {

        for (mb_x = 0; mb_x < s->mb_width; mb_x++) {

            const int copy_mb = mb_bitmask && !get_bits1(&mb_bitmask_gb);



            if (s->restart_interval && !s->restart_count)

                s->restart_count = s->restart_interval;



            if (get_bits_left(&s->gb) < 0) {

                av_log(s->avctx, AV_LOG_ERROR, "overread %d\n",

                       -get_bits_left(&s->gb));

                return -1;

            }

            for (i = 0; i < nb_components; i++) {

                uint8_t *ptr;

                int n, h, v, x, y, c, j;

                int block_offset;

                n = s->nb_blocks[i];

                c = s->comp_index[i];

                h = s->h_scount[i];

                v = s->v_scount[i];

                x = 0;

                y = 0;

                for (j = 0; j < n; j++) {

                    block_offset = ((linesize[c] * (v * mb_y + y) * 8) +

                                    (h * mb_x + x) * 8);



                    if (s->interlaced && s->bottom_field)

                        block_offset += linesize[c] >> 1;

                    ptr = data[c] + block_offset;

                    if (!s->progressive) {

                        if (copy_mb)

                            copy_block8(ptr, reference_data[c] + block_offset,

                                        linesize[c], linesize[c], 8);

                        else {

                            s->dsp.clear_block(s->block);

                            if (decode_block(s, s->block, i,

                                             s->dc_index[i], s->ac_index[i],

                                             s->quant_matrixes[s->quant_index[c]]) < 0) {

                                av_log(s->avctx, AV_LOG_ERROR,

                                       "error y=%d x=%d\n", mb_y, mb_x);

                                return -1;

                            }

                            s->dsp.idct_put(ptr, linesize[c], s->block);

                        }

                    } else {

                        int block_idx  = s->block_stride[c] * (v * mb_y + y) +

                                         (h * mb_x + x);

                        DCTELEM *block = s->blocks[c][block_idx];

                        if (Ah)

                            block[0] += get_bits1(&s->gb) *

                                        s->quant_matrixes[s->quant_index[c]][0] << Al;

                        else if (decode_dc_progressive(s, block, i, s->dc_index[i],

                                                       s->quant_matrixes[s->quant_index[c]],

                                                       Al) < 0) {

                            av_log(s->avctx, AV_LOG_ERROR,

                                   "error y=%d x=%d\n", mb_y, mb_x);

                            return -1;

                        }

                    }

                    // av_log(s->avctx, AV_LOG_DEBUG, "mb: %d %d processed\n",

                    //        mb_y, mb_x);

                    // av_log(NULL, AV_LOG_DEBUG, "%d %d %d %d %d %d %d %d \n",

                    //        mb_x, mb_y, x, y, c, s->bottom_field,

                    //        (v * mb_y + y) * 8, (h * mb_x + x) * 8);

                    if (++x == h) {

                        x = 0;

                        y++;

                    }

                }

            }



            if (s->restart_interval) {

                s->restart_count--;

                if(s->restart_count == 0 && s->avctx->codec_id == CODEC_ID_THP){

                    align_get_bits(&s->gb);

                    for (i = 0; i < nb_components; i++) /* reset dc */

                        s->last_dc[i] = 1024;

                }



                i = 8 + ((-get_bits_count(&s->gb)) & 7);

                /* skip RSTn */

                if (show_bits(&s->gb, i) == (1 << i) - 1) {

                    int pos = get_bits_count(&s->gb);

                    align_get_bits(&s->gb);

                    while (get_bits_left(&s->gb) >= 8 && show_bits(&s->gb, 8) == 0xFF)

                        skip_bits(&s->gb, 8);

                    if (get_bits_left(&s->gb) >= 8 && (get_bits(&s->gb, 8) & 0xF8) == 0xD0) {

                        for (i = 0; i < nb_components; i++) /* reset dc */

                            s->last_dc[i] = 1024;

                    } else

                        skip_bits_long(&s->gb, pos - get_bits_count(&s->gb));

                }

            }

        }

    }

    return 0;

}

static inline void RENAME(yuv2packedX)(SwsContext *c, int16_t *lumFilter, int16_t **lumSrc, int lumFilterSize,

				    int16_t *chrFilter, int16_t **chrSrc, int chrFilterSize,

			    uint8_t *dest, long dstW, long dstY)

{

	long dummy=0;

	switch(c->dstFormat)

	{

#ifdef HAVE_MMX

	case IMGFMT_BGR32:

		{

			asm volatile(

				YSCALEYUV2RGBX

				WRITEBGR32(%4, %5, %%REGa)



			:: "r" (&c->redDither), 

			   "m" (dummy), "m" (dummy), "m" (dummy),

			   "r" (dest), "m" (dstW)

			: "%"REG_a, "%"REG_d, "%"REG_S

			);

		}

		break;

	case IMGFMT_BGR24:

		{

			asm volatile(

				YSCALEYUV2RGBX

				"lea (%%"REG_a", %%"REG_a", 2), %%"REG_b"\n\t" //FIXME optimize

				"add %4, %%"REG_b"			\n\t"

				WRITEBGR24(%%REGb, %5, %%REGa)



			:: "r" (&c->redDither), 

			   "m" (dummy), "m" (dummy), "m" (dummy),

			   "r" (dest), "m" (dstW)

			: "%"REG_a, "%"REG_b, "%"REG_d, "%"REG_S //FIXME ebx

			);

		}

		break;

	case IMGFMT_BGR15:

		{

			asm volatile(

				YSCALEYUV2RGBX

		/* mm2=B, %%mm4=G, %%mm5=R, %%mm7=0 */

#ifdef DITHER1XBPP

				"paddusb "MANGLE(b5Dither)", %%mm2\n\t"

				"paddusb "MANGLE(g5Dither)", %%mm4\n\t"

				"paddusb "MANGLE(r5Dither)", %%mm5\n\t"

#endif



				WRITEBGR15(%4, %5, %%REGa)



			:: "r" (&c->redDither), 

			   "m" (dummy), "m" (dummy), "m" (dummy),

			   "r" (dest), "m" (dstW)

			: "%"REG_a, "%"REG_d, "%"REG_S

			);

		}

		break;

	case IMGFMT_BGR16:

		{

			asm volatile(

				YSCALEYUV2RGBX

		/* mm2=B, %%mm4=G, %%mm5=R, %%mm7=0 */

#ifdef DITHER1XBPP

				"paddusb "MANGLE(b5Dither)", %%mm2\n\t"

				"paddusb "MANGLE(g6Dither)", %%mm4\n\t"

				"paddusb "MANGLE(r5Dither)", %%mm5\n\t"

#endif



				WRITEBGR16(%4, %5, %%REGa)



			:: "r" (&c->redDither), 

			   "m" (dummy), "m" (dummy), "m" (dummy),

			   "r" (dest), "m" (dstW)

			: "%"REG_a, "%"REG_d, "%"REG_S

			);

		}

		break;

	case IMGFMT_YUY2:

		{

			asm volatile(

				YSCALEYUV2PACKEDX

		/* mm2=B, %%mm4=G, %%mm5=R, %%mm7=0 */



				"psraw $3, %%mm3		\n\t"

				"psraw $3, %%mm4		\n\t"

				"psraw $3, %%mm1		\n\t"

				"psraw $3, %%mm7		\n\t"

				WRITEYUY2(%4, %5, %%REGa)



			:: "r" (&c->redDither), 

			   "m" (dummy), "m" (dummy), "m" (dummy),

			   "r" (dest), "m" (dstW)

			: "%"REG_a, "%"REG_d, "%"REG_S

			);

		}

		break;

#endif

	default:

#ifdef HAVE_ALTIVEC

		/* The following list of supported dstFormat values should

		   match what's found in the body of altivec_yuv2packedX() */

		if(c->dstFormat==IMGFMT_ABGR  || c->dstFormat==IMGFMT_BGRA  ||

		   c->dstFormat==IMGFMT_BGR24 || c->dstFormat==IMGFMT_RGB24 ||

		   c->dstFormat==IMGFMT_RGBA  || c->dstFormat==IMGFMT_ARGB)

			altivec_yuv2packedX (c, lumFilter, lumSrc, lumFilterSize,

				    chrFilter, chrSrc, chrFilterSize,

				    dest, dstW, dstY);

		else

#endif

			yuv2packedXinC(c, lumFilter, lumSrc, lumFilterSize,

				    chrFilter, chrSrc, chrFilterSize,

				    dest, dstW, dstY);

		break;

	}

}

int avfilter_parse_graph(AVFilterGraph *graph, const char *filters,

                         AVFilterInOut *openLinks, AVClass *log_ctx)

{

    int index = 0;

    char chr = 0;

    int pad = 0;



    AVFilterInOut *currInputs = NULL;



    do {

        AVFilterContext *filter;

        filters += consume_whitespace(filters);



        pad = parse_inputs(&filters, &currInputs, &openLinks, log_ctx);



        if(pad < 0)

            goto fail;



        if(!(filter = parse_filter(&filters, graph, index, log_ctx)))

            goto fail;



        if(filter->input_count == 1 && !currInputs && !index) {

            // First input can be ommitted if it is "[in]"

            const char *tmp = "[in]";

            pad = parse_inputs(&tmp, &currInputs, &openLinks, log_ctx);

            if(pad < 0)

                goto fail;

        }



        if(link_filter_inouts(filter, &currInputs, &openLinks, log_ctx) < 0)

            goto fail;



        pad = parse_outputs(&filters, &currInputs, &openLinks, log_ctx);



        if(pad < 0)

            goto fail;



        filters += consume_whitespace(filters);

        chr = *filters++;



        if(chr == ';' && currInputs) {

            av_log(log_ctx, AV_LOG_ERROR,

                   "Could not find a output to link when parsing \"%s\"\n",

                   filters - 1);

            goto fail;

        }

        index++;

    } while(chr == ',' || chr == ';');



    if(openLinks && !strcmp(openLinks->name, "out") && currInputs) {

        // Last output can be ommitted if it is "[out]"

        const char *tmp = "[out]";

        if(parse_outputs(&tmp, &currInputs, &openLinks, log_ctx) < 0)

            goto fail;

    }



    return 0;



 fail:

    avfilter_destroy_graph(graph);

    free_inout(openLinks);

    free_inout(currInputs);

    return -1;

}

static av_cold int qtrle_encode_init(AVCodecContext *avctx)

{

    QtrleEncContext *s = avctx->priv_data;



    if (av_image_check_size(avctx->width, avctx->height, 0, avctx) < 0) {

        return -1;

    }

    s->avctx=avctx;



    switch (avctx->pix_fmt) {

    case AV_PIX_FMT_RGB555BE:

        s->pixel_size = 2;

        break;

    case AV_PIX_FMT_RGB24:

        s->pixel_size = 3;

        break;

    case AV_PIX_FMT_ARGB:

        s->pixel_size = 4;

        break;

    default:

        av_log(avctx, AV_LOG_ERROR, "Unsupported colorspace.\n");

        break;

    }

    avctx->bits_per_coded_sample = s->pixel_size*8;



    s->rlecode_table = av_mallocz(s->avctx->width);

    s->skip_table    = av_mallocz(s->avctx->width);

    s->length_table  = av_mallocz((s->avctx->width + 1)*sizeof(int));

    if (!s->skip_table || !s->length_table || !s->rlecode_table) {

        av_log(avctx, AV_LOG_ERROR, "Error allocating memory.\n");

        return -1;

    }

    if (avpicture_alloc(&s->previous_frame, avctx->pix_fmt, avctx->width, avctx->height) < 0) {

        av_log(avctx, AV_LOG_ERROR, "Error allocating picture\n");

        return -1;

    }



    s->max_buf_size = s->avctx->width*s->avctx->height*s->pixel_size*2 /* image base material */

                      + 15                                           /* header + footer */

                      + s->avctx->height*2                           /* skip code+rle end */

                      + s->avctx->width/MAX_RLE_BULK + 1             /* rle codes */;



    avctx->coded_frame = av_frame_alloc();

    if (!avctx->coded_frame) {

        qtrle_encode_end(avctx);

        return AVERROR(ENOMEM);

    }



    return 0;

}

static inline void check_for_slice(AVSContext *h) {

    GetBitContext *gb = &h->s.gb;

    int align;



    if(h->mbx)

        return;

    align = (-get_bits_count(gb)) & 7;

    if((show_bits_long(gb,24+align) & 0xFFFFFF) == 0x000001) {

        skip_bits_long(gb,24+align);

        h->stc = get_bits(gb,8);

        decode_slice_header(h,gb);

    }

}

