static int fill_filter_caches(const H264Context *h, H264SliceContext *sl, int mb_type)

{

    const int mb_xy = sl->mb_xy;

    int top_xy, left_xy[LEFT_MBS];

    int top_type, left_type[LEFT_MBS];

    uint8_t *nnz;

    uint8_t *nnz_cache;



    top_xy = mb_xy - (h->mb_stride << MB_FIELD(sl));



    /* Wow, what a mess, why didn't they simplify the interlacing & intra

     * stuff, I can't imagine that these complex rules are worth it. */



    left_xy[LBOT] = left_xy[LTOP] = mb_xy - 1;

    if (FRAME_MBAFF(h)) {

        const int left_mb_field_flag = IS_INTERLACED(h->cur_pic.mb_type[mb_xy - 1]);

        const int curr_mb_field_flag = IS_INTERLACED(mb_type);

        if (sl->mb_y & 1) {

            if (left_mb_field_flag != curr_mb_field_flag)

                left_xy[LTOP] -= h->mb_stride;

        } else {

            if (curr_mb_field_flag)

                top_xy += h->mb_stride &

                          (((h->cur_pic.mb_type[top_xy] >> 7) & 1) - 1);

            if (left_mb_field_flag != curr_mb_field_flag)

                left_xy[LBOT] += h->mb_stride;

        }

    }



    sl->top_mb_xy        = top_xy;

    sl->left_mb_xy[LTOP] = left_xy[LTOP];

    sl->left_mb_xy[LBOT] = left_xy[LBOT];

    {

        /* For sufficiently low qp, filtering wouldn't do anything.

         * This is a conservative estimate: could also check beta_offset

         * and more accurate chroma_qp. */

        int qp_thresh = sl->qp_thresh; // FIXME strictly we should store qp_thresh for each mb of a slice

        int qp        = h->cur_pic.qscale_table[mb_xy];

        if (qp <= qp_thresh &&

            (left_xy[LTOP] < 0 ||

             ((qp + h->cur_pic.qscale_table[left_xy[LTOP]] + 1) >> 1) <= qp_thresh) &&

            (top_xy < 0 ||

             ((qp + h->cur_pic.qscale_table[top_xy] + 1) >> 1) <= qp_thresh)) {

            if (!FRAME_MBAFF(h))

                return 1;

            if ((left_xy[LTOP] < 0 ||

                 ((qp + h->cur_pic.qscale_table[left_xy[LBOT]] + 1) >> 1) <= qp_thresh) &&

                (top_xy < h->mb_stride ||

                 ((qp + h->cur_pic.qscale_table[top_xy - h->mb_stride] + 1) >> 1) <= qp_thresh))

                return 1;

        }

    }



    top_type        = h->cur_pic.mb_type[top_xy];

    left_type[LTOP] = h->cur_pic.mb_type[left_xy[LTOP]];

    left_type[LBOT] = h->cur_pic.mb_type[left_xy[LBOT]];

    if (sl->deblocking_filter == 2) {

        if (h->slice_table[top_xy] != sl->slice_num)

            top_type = 0;

        if (h->slice_table[left_xy[LBOT]] != sl->slice_num)

            left_type[LTOP] = left_type[LBOT] = 0;

    } else {

        if (h->slice_table[top_xy] == 0xFFFF)

            top_type = 0;

        if (h->slice_table[left_xy[LBOT]] == 0xFFFF)

            left_type[LTOP] = left_type[LBOT] = 0;

    }

    sl->top_type        = top_type;

    sl->left_type[LTOP] = left_type[LTOP];

    sl->left_type[LBOT] = left_type[LBOT];



    if (IS_INTRA(mb_type))

        return 0;



    fill_filter_caches_inter(h, sl, mb_type, top_xy, left_xy,

                             top_type, left_type, mb_xy, 0);

    if (sl->list_count == 2)

        fill_filter_caches_inter(h, sl, mb_type, top_xy, left_xy,

                                 top_type, left_type, mb_xy, 1);



    nnz       = h->non_zero_count[mb_xy];

    nnz_cache = sl->non_zero_count_cache;

    AV_COPY32(&nnz_cache[4 + 8 * 1], &nnz[0]);

    AV_COPY32(&nnz_cache[4 + 8 * 2], &nnz[4]);

    AV_COPY32(&nnz_cache[4 + 8 * 3], &nnz[8]);

    AV_COPY32(&nnz_cache[4 + 8 * 4], &nnz[12]);

    sl->cbp = h->cbp_table[mb_xy];



    if (top_type) {

        nnz = h->non_zero_count[top_xy];

        AV_COPY32(&nnz_cache[4 + 8 * 0], &nnz[3 * 4]);

    }



    if (left_type[LTOP]) {

        nnz = h->non_zero_count[left_xy[LTOP]];

        nnz_cache[3 + 8 * 1] = nnz[3 + 0 * 4];

        nnz_cache[3 + 8 * 2] = nnz[3 + 1 * 4];

        nnz_cache[3 + 8 * 3] = nnz[3 + 2 * 4];

        nnz_cache[3 + 8 * 4] = nnz[3 + 3 * 4];

    }



    /* CAVLC 8x8dct requires NNZ values for residual decoding that differ

     * from what the loop filter needs */

    if (!CABAC(h) && h->pps.transform_8x8_mode) {

        if (IS_8x8DCT(top_type)) {

            nnz_cache[4 + 8 * 0] =

            nnz_cache[5 + 8 * 0] = (h->cbp_table[top_xy] & 0x4000) >> 12;

            nnz_cache[6 + 8 * 0] =

            nnz_cache[7 + 8 * 0] = (h->cbp_table[top_xy] & 0x8000) >> 12;

        }

        if (IS_8x8DCT(left_type[LTOP])) {

            nnz_cache[3 + 8 * 1] =

            nnz_cache[3 + 8 * 2] = (h->cbp_table[left_xy[LTOP]] & 0x2000) >> 12; // FIXME check MBAFF

        }

        if (IS_8x8DCT(left_type[LBOT])) {

            nnz_cache[3 + 8 * 3] =

            nnz_cache[3 + 8 * 4] = (h->cbp_table[left_xy[LBOT]] & 0x8000) >> 12; // FIXME check MBAFF

        }



        if (IS_8x8DCT(mb_type)) {

            nnz_cache[scan8[0]] =

            nnz_cache[scan8[1]] =

            nnz_cache[scan8[2]] =

            nnz_cache[scan8[3]] = (sl->cbp & 0x1000) >> 12;



            nnz_cache[scan8[0 + 4]] =

            nnz_cache[scan8[1 + 4]] =

            nnz_cache[scan8[2 + 4]] =

            nnz_cache[scan8[3 + 4]] = (sl->cbp & 0x2000) >> 12;



            nnz_cache[scan8[0 + 8]] =

            nnz_cache[scan8[1 + 8]] =

            nnz_cache[scan8[2 + 8]] =

            nnz_cache[scan8[3 + 8]] = (sl->cbp & 0x4000) >> 12;



            nnz_cache[scan8[0 + 12]] =

            nnz_cache[scan8[1 + 12]] =

            nnz_cache[scan8[2 + 12]] =

            nnz_cache[scan8[3 + 12]] = (sl->cbp & 0x8000) >> 12;

        }

    }



    return 0;

}

static int h264_parse(AVCodecParserContext *s,

                      AVCodecContext *avctx,

                      const uint8_t **poutbuf, int *poutbuf_size,

                      const uint8_t *buf, int buf_size)

{

    H264ParseContext *p = s->priv_data;

    ParseContext *pc = &p->pc;

    int next;



    if (!p->got_first) {

        p->got_first = 1;

        if (avctx->extradata_size) {

            ff_h264_decode_extradata(avctx->extradata, avctx->extradata_size,

                                     &p->ps, &p->is_avc, &p->nal_length_size,

                                     avctx->err_recognition, avctx);

        }

    }



    if (s->flags & PARSER_FLAG_COMPLETE_FRAMES) {

        next = buf_size;

    } else {

        next = h264_find_frame_end(p, buf, buf_size, avctx);



        if (ff_combine_frame(pc, next, &buf, &buf_size) < 0) {

            *poutbuf      = NULL;

            *poutbuf_size = 0;

            return buf_size;

        }



        if (next < 0 && next != END_NOT_FOUND) {

            av_assert1(pc->last_index + next >= 0);

            h264_find_frame_end(p, &pc->buffer[pc->last_index + next], -next, avctx); // update state

        }

    }



    parse_nal_units(s, avctx, buf, buf_size);



    if (avctx->framerate.num)

        avctx->time_base = av_inv_q(av_mul_q(avctx->framerate, (AVRational){avctx->ticks_per_frame, 1}));

    if (p->sei.picture_timing.cpb_removal_delay >= 0) {

        s->dts_sync_point    = p->sei.buffering_period.present;

        s->dts_ref_dts_delta = p->sei.picture_timing.cpb_removal_delay;

        s->pts_dts_delta     = p->sei.picture_timing.dpb_output_delay;

    } else {

        s->dts_sync_point    = INT_MIN;

        s->dts_ref_dts_delta = INT_MIN;

        s->pts_dts_delta     = INT_MIN;

    }



    if (s->flags & PARSER_FLAG_ONCE) {

        s->flags &= PARSER_FLAG_COMPLETE_FRAMES;

    }



    if (s->dts_sync_point >= 0) {

        int64_t den = avctx->time_base.den * avctx->pkt_timebase.num;

        if (den > 0) {

            int64_t num = avctx->time_base.num * avctx->pkt_timebase.den;

            if (s->dts != AV_NOPTS_VALUE) {

                // got DTS from the stream, update reference timestamp

                p->reference_dts = s->dts - av_rescale(s->dts_ref_dts_delta, num, den);

            } else if (p->reference_dts != AV_NOPTS_VALUE) {

                // compute DTS based on reference timestamp

                s->dts = p->reference_dts + av_rescale(s->dts_ref_dts_delta, num, den);

            }



            if (p->reference_dts != AV_NOPTS_VALUE && s->pts == AV_NOPTS_VALUE)

                s->pts = s->dts + av_rescale(s->pts_dts_delta, num, den);



            if (s->dts_sync_point > 0)

                p->reference_dts = s->dts; // new reference

        }

    }



    *poutbuf      = buf;

    *poutbuf_size = buf_size;

    return next;

}

static int flv_read_packet(AVFormatContext *s, AVPacket *pkt)

{

    FLVContext *flv = s->priv_data;

    int ret, i, type, size, flags;

    int stream_type=-1;

    int64_t next, pos;

    int64_t dts, pts = AV_NOPTS_VALUE;

    AVStream *st = NULL;



 for(;;avio_skip(s->pb, 4)){ /* pkt size is repeated at end. skip it */

    pos = avio_tell(s->pb);

    type = avio_r8(s->pb);

    size = avio_rb24(s->pb);

    dts = avio_rb24(s->pb);

    dts |= avio_r8(s->pb) << 24;

    av_dlog(s, "type:%d, size:%d, dts:%"PRId64"\n", type, size, dts);

    if (url_feof(s->pb))

        return AVERROR_EOF;

    avio_skip(s->pb, 3); /* stream id, always 0 */

    flags = 0;



    if(size == 0)

        continue;



    next= size + avio_tell(s->pb);



    if (type == FLV_TAG_TYPE_AUDIO) {

        stream_type=FLV_STREAM_TYPE_AUDIO;

        flags = avio_r8(s->pb);

        size--;

    } else if (type == FLV_TAG_TYPE_VIDEO) {

        stream_type=FLV_STREAM_TYPE_VIDEO;

        flags = avio_r8(s->pb);

        size--;

        if ((flags & 0xf0) == 0x50) /* video info / command frame */

            goto skip;

    } else if (type == FLV_TAG_TYPE_META) {

        if (size > 13+1+4 && dts == 0) { // Header-type metadata stuff

            flv_read_metabody(s, next);

            goto skip;

        } else if (dts != 0) { // Script-data "special" metadata frames - don't skip

            stream_type=FLV_STREAM_TYPE_DATA;

        } else {

            goto skip;

        }

    } else {

        av_log(s, AV_LOG_DEBUG, "skipping flv packet: type %d, size %d, flags %d\n", type, size, flags);

    skip:

        avio_seek(s->pb, next, SEEK_SET);

        continue;

    }



    /* skip empty data packets */

    if (!size)

        continue;



    /* now find stream */

    for(i=0;i<s->nb_streams;i++) {

        st = s->streams[i];

        if (st->id == stream_type)

            break;

    }

    if(i == s->nb_streams){

        av_log(s, AV_LOG_WARNING, "Stream discovered after head already parsed\n");

        st= create_stream(s, stream_type);

        s->ctx_flags &= ~AVFMTCTX_NOHEADER;

    }

    av_dlog(s, "%d %X %d \n", stream_type, flags, st->discard);

    if(  (st->discard >= AVDISCARD_NONKEY && !((flags & FLV_VIDEO_FRAMETYPE_MASK) == FLV_FRAME_KEY || (stream_type == FLV_STREAM_TYPE_AUDIO)))

       ||(st->discard >= AVDISCARD_BIDIR  &&  ((flags & FLV_VIDEO_FRAMETYPE_MASK) == FLV_FRAME_DISP_INTER && (stream_type == FLV_STREAM_TYPE_VIDEO)))

       || st->discard >= AVDISCARD_ALL

       ){

        avio_seek(s->pb, next, SEEK_SET);

        continue;

    }

    if ((flags & FLV_VIDEO_FRAMETYPE_MASK) == FLV_FRAME_KEY)

        av_add_index_entry(st, pos, dts, size, 0, AVINDEX_KEYFRAME);

    break;

 }



    // if not streamed and no duration from metadata then seek to end to find the duration from the timestamps

    if(s->pb->seekable && (!s->duration || s->duration==AV_NOPTS_VALUE)){

        int size;

        const int64_t pos= avio_tell(s->pb);

        const int64_t fsize= avio_size(s->pb);

        avio_seek(s->pb, fsize-4, SEEK_SET);

        size= avio_rb32(s->pb);

        avio_seek(s->pb, fsize-3-size, SEEK_SET);

        if(size == avio_rb24(s->pb) + 11){

            uint32_t ts = avio_rb24(s->pb);

            ts |= avio_r8(s->pb) << 24;

            s->duration = ts * (int64_t)AV_TIME_BASE / 1000;

        }

        avio_seek(s->pb, pos, SEEK_SET);

    }



    if(stream_type == FLV_STREAM_TYPE_AUDIO){

        if(!st->codec->channels || !st->codec->sample_rate || !st->codec->bits_per_coded_sample) {

            st->codec->channels = (flags & FLV_AUDIO_CHANNEL_MASK) == FLV_STEREO ? 2 : 1;

            st->codec->sample_rate = (44100 << ((flags & FLV_AUDIO_SAMPLERATE_MASK) >> FLV_AUDIO_SAMPLERATE_OFFSET) >> 3);

            st->codec->bits_per_coded_sample = (flags & FLV_AUDIO_SAMPLESIZE_MASK) ? 16 : 8;

        }

        if(!st->codec->codec_id){

            flv_set_audio_codec(s, st, flags & FLV_AUDIO_CODECID_MASK);

        }

    } else if(stream_type == FLV_STREAM_TYPE_VIDEO) {

        size -= flv_set_video_codec(s, st, flags & FLV_VIDEO_CODECID_MASK);

    }



    if (st->codec->codec_id == CODEC_ID_AAC ||

        st->codec->codec_id == CODEC_ID_H264 ||

        st->codec->codec_id == CODEC_ID_MPEG4) {

        int type = avio_r8(s->pb);

        size--;

        if (st->codec->codec_id == CODEC_ID_H264 || st->codec->codec_id == CODEC_ID_MPEG4) {

            int32_t cts = (avio_rb24(s->pb)+0xff800000)^0xff800000; // sign extension

            pts = dts + cts;

            if (cts < 0) { // dts are wrong

                flv->wrong_dts = 1;

                av_log(s, AV_LOG_WARNING, "negative cts, previous timestamps might be wrong\n");

            }

            if (flv->wrong_dts)

                dts = AV_NOPTS_VALUE;

        }

        if (type == 0) {

            if ((ret = flv_get_extradata(s, st, size)) < 0)

                return ret;

            if (st->codec->codec_id == CODEC_ID_AAC) {

                MPEG4AudioConfig cfg;

                ff_mpeg4audio_get_config(&cfg, st->codec->extradata,

                                         st->codec->extradata_size);

                st->codec->channels = cfg.channels;

                if (cfg.ext_sample_rate)

                    st->codec->sample_rate = cfg.ext_sample_rate;

                else

                    st->codec->sample_rate = cfg.sample_rate;

                av_dlog(s, "mp4a config channels %d sample rate %d\n",

                        st->codec->channels, st->codec->sample_rate);

            }



            ret = AVERROR(EAGAIN);

            goto leave;

        }

    }



    /* skip empty data packets */

    if (!size) {

        ret = AVERROR(EAGAIN);

        goto leave;

    }



    ret= av_get_packet(s->pb, pkt, size);

    if (ret < 0) {

        return AVERROR(EIO);

    }

    /* note: we need to modify the packet size here to handle the last

       packet */

    pkt->size = ret;

    pkt->dts = dts;

    pkt->pts = pts == AV_NOPTS_VALUE ? dts : pts;

    pkt->stream_index = st->index;



    if (    stream_type == FLV_STREAM_TYPE_AUDIO ||

            ((flags & FLV_VIDEO_FRAMETYPE_MASK) == FLV_FRAME_KEY) ||

            stream_type == FLV_STREAM_TYPE_DATA)

        pkt->flags |= AV_PKT_FLAG_KEY;



leave:

    avio_skip(s->pb, 4);

    return ret;

}

static int MPA_encode_init(AVCodecContext *avctx)

{

    MpegAudioContext *s = avctx->priv_data;

    int freq = avctx->sample_rate;

    int bitrate = avctx->bit_rate;

    int channels = avctx->channels;

    int i, v, table;

    float a;



    if (channels > 2)

        return -1;

    bitrate = bitrate / 1000;

    s->nb_channels = channels;

    s->freq = freq;

    s->bit_rate = bitrate * 1000;

    avctx->frame_size = MPA_FRAME_SIZE;



    /* encoding freq */

    s->lsf = 0;

    for(i=0;i<3;i++) {

        if (mpa_freq_tab[i] == freq)

            break;

        if ((mpa_freq_tab[i] / 2) == freq) {

            s->lsf = 1;

            break;

        }

    }

    if (i == 3){

        av_log(avctx, AV_LOG_ERROR, "Sampling rate %d is not allowed in mp2\n", freq);

        return -1;

    }

    s->freq_index = i;



    /* encoding bitrate & frequency */

    for(i=0;i<15;i++) {

        if (mpa_bitrate_tab[s->lsf][1][i] == bitrate)

            break;

    }

    if (i == 15){

        av_log(avctx, AV_LOG_ERROR, "bitrate %d is not allowed in mp2\n", bitrate);

        return -1;

    }

    s->bitrate_index = i;



    /* compute total header size & pad bit */



    a = (float)(bitrate * 1000 * MPA_FRAME_SIZE) / (freq * 8.0);

    s->frame_size = ((int)a) * 8;



    /* frame fractional size to compute padding */

    s->frame_frac = 0;

    s->frame_frac_incr = (int)((a - floor(a)) * 65536.0);



    /* select the right allocation table */

    table = l2_select_table(bitrate, s->nb_channels, freq, s->lsf);



    /* number of used subbands */

    s->sblimit = sblimit_table[table];

    s->alloc_table = alloc_tables[table];



#ifdef DEBUG

    av_log(avctx, AV_LOG_DEBUG, "%d kb/s, %d Hz, frame_size=%d bits, table=%d, padincr=%x\n",

           bitrate, freq, s->frame_size, table, s->frame_frac_incr);

#endif



    for(i=0;i<s->nb_channels;i++)

        s->samples_offset[i] = 0;



    for(i=0;i<257;i++) {

        int v;

        v = mpa_enwindow[i];

#if WFRAC_BITS != 16

        v = (v + (1 << (16 - WFRAC_BITS - 1))) >> (16 - WFRAC_BITS);

#endif

        filter_bank[i] = v;

        if ((i & 63) != 0)

            v = -v;

        if (i != 0)

            filter_bank[512 - i] = v;

    }



    for(i=0;i<64;i++) {

        v = (int)(pow(2.0, (3 - i) / 3.0) * (1 << 20));

        if (v <= 0)

            v = 1;

        scale_factor_table[i] = v;

#ifdef USE_FLOATS

        scale_factor_inv_table[i] = pow(2.0, -(3 - i) / 3.0) / (float)(1 << 20);

#else

#define P 15

        scale_factor_shift[i] = 21 - P - (i / 3);

        scale_factor_mult[i] = (1 << P) * pow(2.0, (i % 3) / 3.0);

#endif

    }

    for(i=0;i<128;i++) {

        v = i - 64;

        if (v <= -3)

            v = 0;

        else if (v < 0)

            v = 1;

        else if (v == 0)

            v = 2;

        else if (v < 3)

            v = 3;

        else

            v = 4;

        scale_diff_table[i] = v;

    }



    for(i=0;i<17;i++) {

        v = quant_bits[i];

        if (v < 0)

            v = -v;

        else

            v = v * 3;

        total_quant_bits[i] = 12 * v;

    }



    avctx->coded_frame= avcodec_alloc_frame();

    avctx->coded_frame->key_frame= 1;



    return 0;

}

static void frame_thread_free(AVCodecContext *avctx, int thread_count)

{

    FrameThreadContext *fctx = avctx->thread_opaque;

    AVCodec *codec = avctx->codec;

    int i;



    park_frame_worker_threads(fctx, thread_count);



    if (fctx->prev_thread)

        update_context_from_thread(fctx->threads->avctx, fctx->prev_thread->avctx, 0);



    fctx->die = 1;



    for (i = 0; i < thread_count; i++) {

        PerThreadContext *p = &fctx->threads[i];



        pthread_mutex_lock(&p->mutex);

        pthread_cond_signal(&p->input_cond);

        pthread_mutex_unlock(&p->mutex);



        pthread_join(p->thread, NULL);



        if (codec->close)

            codec->close(p->avctx);



        avctx->codec = NULL;



        release_delayed_buffers(p);

    }



    for (i = 0; i < thread_count; i++) {

        PerThreadContext *p = &fctx->threads[i];



        avcodec_default_free_buffers(p->avctx);



        pthread_mutex_destroy(&p->mutex);

        pthread_mutex_destroy(&p->progress_mutex);

        pthread_cond_destroy(&p->input_cond);

        pthread_cond_destroy(&p->progress_cond);

        pthread_cond_destroy(&p->output_cond);

        av_freep(&p->avpkt.data);



        if (i)

            av_freep(&p->avctx->priv_data);



        av_freep(&p->avctx);

    }



    av_freep(&fctx->threads);

    pthread_mutex_destroy(&fctx->buffer_mutex);

    av_freep(&avctx->thread_opaque);

}

static av_cold int mpc8_decode_init(AVCodecContext * avctx)

{

    int i;

    MPCContext *c = avctx->priv_data;

    GetBitContext gb;

    static int vlc_initialized = 0;



    static VLC_TYPE band_table[542][2];

    static VLC_TYPE q1_table[520][2];

    static VLC_TYPE q9up_table[524][2];

    static VLC_TYPE scfi0_table[1 << MPC8_SCFI0_BITS][2];

    static VLC_TYPE scfi1_table[1 << MPC8_SCFI1_BITS][2];

    static VLC_TYPE dscf0_table[560][2];

    static VLC_TYPE dscf1_table[598][2];

    static VLC_TYPE q3_0_table[512][2];

    static VLC_TYPE q3_1_table[516][2];

    static VLC_TYPE codes_table[5708][2];



    if(avctx->extradata_size < 2){

        av_log(avctx, AV_LOG_ERROR, "Too small extradata size (%i)!\n", avctx->extradata_size);

        return -1;

    }

    memset(c->oldDSCF, 0, sizeof(c->oldDSCF));

    av_lfg_init(&c->rnd, 0xDEADBEEF);

    dsputil_init(&c->dsp, avctx);



    ff_mpc_init();



    init_get_bits(&gb, avctx->extradata, 16);



    skip_bits(&gb, 3);//sample rate

    c->maxbands = get_bits(&gb, 5) + 1;

    skip_bits(&gb, 4);//channels

    c->MSS = get_bits1(&gb);

    c->frames = 1 << (get_bits(&gb, 3) * 2);



    if(vlc_initialized) return 0;

    av_log(avctx, AV_LOG_DEBUG, "Initing VLC\n");



    band_vlc.table = band_table;

    band_vlc.table_allocated = 542;

    init_vlc(&band_vlc, MPC8_BANDS_BITS, MPC8_BANDS_SIZE,

             mpc8_bands_bits,  1, 1,

             mpc8_bands_codes, 1, 1, INIT_VLC_USE_NEW_STATIC);



    q1_vlc.table = q1_table;

    q1_vlc.table_allocated = 520;

    init_vlc(&q1_vlc, MPC8_Q1_BITS, MPC8_Q1_SIZE,

             mpc8_q1_bits,  1, 1,

             mpc8_q1_codes, 1, 1, INIT_VLC_USE_NEW_STATIC);

    q9up_vlc.table = q9up_table;

    q9up_vlc.table_allocated = 524;

    init_vlc(&q9up_vlc, MPC8_Q9UP_BITS, MPC8_Q9UP_SIZE,

             mpc8_q9up_bits,  1, 1,

             mpc8_q9up_codes, 1, 1, INIT_VLC_USE_NEW_STATIC);



    scfi_vlc[0].table = scfi0_table;

    scfi_vlc[0].table_allocated = 1 << MPC8_SCFI0_BITS;

    init_vlc(&scfi_vlc[0], MPC8_SCFI0_BITS, MPC8_SCFI0_SIZE,

             mpc8_scfi0_bits,  1, 1,

             mpc8_scfi0_codes, 1, 1, INIT_VLC_USE_NEW_STATIC);

    scfi_vlc[1].table = scfi1_table;

    scfi_vlc[1].table_allocated = 1 << MPC8_SCFI1_BITS;

    init_vlc(&scfi_vlc[1], MPC8_SCFI1_BITS, MPC8_SCFI1_SIZE,

             mpc8_scfi1_bits,  1, 1,

             mpc8_scfi1_codes, 1, 1, INIT_VLC_USE_NEW_STATIC);



    dscf_vlc[0].table = dscf0_table;

    dscf_vlc[0].table_allocated = 560;

    init_vlc(&dscf_vlc[0], MPC8_DSCF0_BITS, MPC8_DSCF0_SIZE,

             mpc8_dscf0_bits,  1, 1,

             mpc8_dscf0_codes, 1, 1, INIT_VLC_USE_NEW_STATIC);

    dscf_vlc[1].table = dscf1_table;

    dscf_vlc[1].table_allocated = 598;

    init_vlc(&dscf_vlc[1], MPC8_DSCF1_BITS, MPC8_DSCF1_SIZE,

             mpc8_dscf1_bits,  1, 1,

             mpc8_dscf1_codes, 1, 1, INIT_VLC_USE_NEW_STATIC);



    q3_vlc[0].table = q3_0_table;

    q3_vlc[0].table_allocated = 512;

    init_vlc_sparse(&q3_vlc[0], MPC8_Q3_BITS, MPC8_Q3_SIZE,

             mpc8_q3_bits,  1, 1,

             mpc8_q3_codes, 1, 1,

             mpc8_q3_syms,  1, 1, INIT_VLC_USE_NEW_STATIC);

    q3_vlc[1].table = q3_1_table;

    q3_vlc[1].table_allocated = 516;

    init_vlc_sparse(&q3_vlc[1], MPC8_Q4_BITS, MPC8_Q4_SIZE,

             mpc8_q4_bits,  1, 1,

             mpc8_q4_codes, 1, 1,

             mpc8_q4_syms,  1, 1, INIT_VLC_USE_NEW_STATIC);



    for(i = 0; i < 2; i++){

        res_vlc[i].table = &codes_table[vlc_offsets[0+i]];

        res_vlc[i].table_allocated = vlc_offsets[1+i] - vlc_offsets[0+i];

        init_vlc(&res_vlc[i], MPC8_RES_BITS, MPC8_RES_SIZE,

                 &mpc8_res_bits[i],  1, 1,

                 &mpc8_res_codes[i], 1, 1, INIT_VLC_USE_NEW_STATIC);



        q2_vlc[i].table = &codes_table[vlc_offsets[2+i]];

        q2_vlc[i].table_allocated = vlc_offsets[3+i] - vlc_offsets[2+i];

        init_vlc(&q2_vlc[i], MPC8_Q2_BITS, MPC8_Q2_SIZE,

                 &mpc8_q2_bits[i],  1, 1,

                 &mpc8_q2_codes[i], 1, 1, INIT_VLC_USE_NEW_STATIC);



        quant_vlc[0][i].table = &codes_table[vlc_offsets[4+i]];

        quant_vlc[0][i].table_allocated = vlc_offsets[5+i] - vlc_offsets[4+i];

        init_vlc(&quant_vlc[0][i], MPC8_Q5_BITS, MPC8_Q5_SIZE,

                 &mpc8_q5_bits[i],  1, 1,

                 &mpc8_q5_codes[i], 1, 1, INIT_VLC_USE_NEW_STATIC);

        quant_vlc[1][i].table = &codes_table[vlc_offsets[6+i]];

        quant_vlc[1][i].table_allocated = vlc_offsets[7+i] - vlc_offsets[6+i];

        init_vlc(&quant_vlc[1][i], MPC8_Q6_BITS, MPC8_Q6_SIZE,

                 &mpc8_q6_bits[i],  1, 1,

                 &mpc8_q6_codes[i], 1, 1, INIT_VLC_USE_NEW_STATIC);

        quant_vlc[2][i].table = &codes_table[vlc_offsets[8+i]];

        quant_vlc[2][i].table_allocated = vlc_offsets[9+i] - vlc_offsets[8+i];

        init_vlc(&quant_vlc[2][i], MPC8_Q7_BITS, MPC8_Q7_SIZE,

                 &mpc8_q7_bits[i],  1, 1,

                 &mpc8_q7_codes[i], 1, 1, INIT_VLC_USE_NEW_STATIC);

        quant_vlc[3][i].table = &codes_table[vlc_offsets[10+i]];

        quant_vlc[3][i].table_allocated = vlc_offsets[11+i] - vlc_offsets[10+i];

        init_vlc(&quant_vlc[3][i], MPC8_Q8_BITS, MPC8_Q8_SIZE,

                 &mpc8_q8_bits[i],  1, 1,

                 &mpc8_q8_codes[i], 1, 1, INIT_VLC_USE_NEW_STATIC);

    }

    vlc_initialized = 1;

    avctx->sample_fmt = SAMPLE_FMT_S16;

    avctx->channel_layout = (avctx->channels==2) ? CH_LAYOUT_STEREO : CH_LAYOUT_MONO;

    return 0;

}

static void unpack_modes(Vp3DecodeContext *s, GetBitContext *gb)

{

    int i, j, k;

    int scheme;

    int current_macroblock;

    int current_fragment;

    int coding_mode;



    debug_vp3("  vp3: unpacking encoding modes\n");



    if (s->keyframe) {

        debug_vp3("    keyframe-- all blocks are coded as INTRA\n");



        for (i = 0; i < s->fragment_count; i++)

            s->all_fragments[i].coding_method = MODE_INTRA;



    } else {



        /* fetch the mode coding scheme for this frame */

        scheme = get_bits(gb, 3);

        debug_modes("    using mode alphabet %d\n", scheme);



        /* is it a custom coding scheme? */

        if (scheme == 0) {

            debug_modes("    custom mode alphabet ahead:\n");

            for (i = 0; i < 8; i++)

                ModeAlphabet[0][i] = get_bits(gb, 3);

        }



        for (i = 0; i < 8; i++)

            debug_modes("      mode[%d][%d] = %d\n", scheme, i, 

                ModeAlphabet[scheme][i]);



        /* iterate through all of the macroblocks that contain 1 or more

         * coded fragments */

        for (i = 0; i < s->u_superblock_start; i++) {



            for (j = 0; j < 4; j++) {

                current_macroblock = s->superblock_macroblocks[i * 4 + j];

                if ((current_macroblock == -1) ||

                    (!s->macroblock_coded[current_macroblock]))

                    continue;



                /* mode 7 means get 3 bits for each coding mode */

                if (scheme == 7)

                    coding_mode = get_bits(gb, 3);

                else

                    coding_mode = ModeAlphabet[scheme][get_mode_code(gb)];



                for (k = 0; k < 6; k++) {

                    current_fragment = 

                        s->macroblock_fragments[current_macroblock * 6 + k];

                    if (s->all_fragments[current_fragment].coding_method != 

                        MODE_COPY)

                        s->all_fragments[current_fragment].coding_method =

                            coding_mode;

                }



                debug_modes("    coding method for macroblock starting @ fragment %d = %d\n",

                    s->macroblock_fragments[current_macroblock * 6], coding_mode);

            }

        }

    }

}

static int dds_decode(AVCodecContext *avctx, void *data,

                      int *got_frame, AVPacket *avpkt)

{

    DDSContext *ctx = avctx->priv_data;

    GetByteContext *gbc = &ctx->gbc;

    AVFrame *frame = data;

    int mipmap;

    int ret;



    ff_texturedsp_init(&ctx->texdsp);

    bytestream2_init(gbc, avpkt->data, avpkt->size);



    if (bytestream2_get_bytes_left(gbc) < 128) {

        av_log(avctx, AV_LOG_ERROR, "Frame is too small (%d).\n",

               bytestream2_get_bytes_left(gbc));

        return AVERROR_INVALIDDATA;

    }



    if (bytestream2_get_le32(gbc) != MKTAG('D', 'D', 'S', ' ') ||

        bytestream2_get_le32(gbc) != 124) { // header size

        av_log(avctx, AV_LOG_ERROR, "Invalid DDS header.\n");

        return AVERROR_INVALIDDATA;

    }



    bytestream2_skip(gbc, 4); // flags



    avctx->height = bytestream2_get_le32(gbc);

    avctx->width  = bytestream2_get_le32(gbc);

    ret = av_image_check_size(avctx->width, avctx->height, 0, avctx);

    if (ret < 0) {

        av_log(avctx, AV_LOG_ERROR, "Invalid image size %dx%d.\n",

               avctx->width, avctx->height);

        return ret;

    }



    /* Since codec is based on 4x4 blocks, size is aligned to 4. */

    avctx->coded_width  = FFALIGN(avctx->width,  TEXTURE_BLOCK_W);

    avctx->coded_height = FFALIGN(avctx->height, TEXTURE_BLOCK_H);



    bytestream2_skip(gbc, 4); // pitch

    bytestream2_skip(gbc, 4); // depth

    mipmap = bytestream2_get_le32(gbc);

    if (mipmap != 0)

        av_log(avctx, AV_LOG_VERBOSE, "Found %d mipmaps (ignored).\n", mipmap);



    /* Extract pixel format information, considering additional elements

     * in reserved1 and reserved2. */

    ret = parse_pixel_format(avctx);

    if (ret < 0)

        return ret;



    ret = ff_get_buffer(avctx, frame, 0);

    if (ret < 0)

        return ret;



    if (ctx->compressed) {

        int size = (avctx->coded_height / TEXTURE_BLOCK_H) *

                   (avctx->coded_width / TEXTURE_BLOCK_W) * ctx->tex_ratio;

        ctx->slice_count = av_clip(avctx->thread_count, 1,

                                   avctx->coded_height / TEXTURE_BLOCK_H);



        if (bytestream2_get_bytes_left(gbc) < size) {

            av_log(avctx, AV_LOG_ERROR,

                   "Compressed Buffer is too small (%d < %d).\n",

                   bytestream2_get_bytes_left(gbc), size);

            return AVERROR_INVALIDDATA;

        }



        /* Use the decompress function on the texture, one block per thread. */

        ctx->tex_data = gbc->buffer;

        avctx->execute2(avctx, decompress_texture_thread, frame, NULL, ctx->slice_count);

    } else {

        int linesize = av_image_get_linesize(avctx->pix_fmt, frame->width, 0);



        if (ctx->paletted) {

            int i;

            uint32_t *p = (uint32_t*) frame->data[1];



            /* Use the first 1024 bytes as palette, then copy the rest. */

            for (i = 0; i < 256; i++) {

                uint32_t rgba = 0;

                rgba |= bytestream2_get_byte(gbc) << 16;

                rgba |= bytestream2_get_byte(gbc) << 8;

                rgba |= bytestream2_get_byte(gbc) << 0;

                rgba |= bytestream2_get_byte(gbc) << 24;

                p[i] = rgba;

            }



            frame->palette_has_changed = 1;

        }



        if (bytestream2_get_bytes_left(gbc) < frame->height * linesize) {

            av_log(avctx, AV_LOG_ERROR, "Buffer is too small (%d < %d).\n",

                   bytestream2_get_bytes_left(gbc), frame->height * linesize);

            return AVERROR_INVALIDDATA;

        }



        av_image_copy_plane(frame->data[0], frame->linesize[0],

                            gbc->buffer, linesize,

                            linesize, frame->height);

    }



    /* Run any post processing here if needed. */

    if (avctx->pix_fmt == AV_PIX_FMT_BGRA ||

        avctx->pix_fmt == AV_PIX_FMT_RGBA ||

        avctx->pix_fmt == AV_PIX_FMT_YA8)

        run_postproc(avctx, frame);



    /* Frame is ready to be output. */

    frame->pict_type = AV_PICTURE_TYPE_I;

    frame->key_frame = 1;

    *got_frame = 1;



    return avpkt->size;

}

static double get_video_clock(VideoState *is)

{

    double delta;

    if (is->paused) { //FIXME timing gets messed after pause

        delta = 0;

    } else {

        delta = (av_gettime() - is->video_current_pts_time) / 1000000.0;

    }

    return is->video_current_pts + delta;

}

static void set_downmix_coeffs(AC3DecodeContext *s)

{

    int i;

    float cmix = gain_levels[s->center_mix_level];

    float smix = gain_levels[s->surround_mix_level];



    for(i=0; i<s->fbw_channels; i++) {

        s->downmix_coeffs[i][0] = gain_levels[ac3_default_coeffs[s->channel_mode][i][0]];

        s->downmix_coeffs[i][1] = gain_levels[ac3_default_coeffs[s->channel_mode][i][1]];

    }

    if(s->channel_mode > 1 && s->channel_mode & 1) {

        s->downmix_coeffs[1][0] = s->downmix_coeffs[1][1] = cmix;

    }

    if(s->channel_mode == AC3_CHMODE_2F1R || s->channel_mode == AC3_CHMODE_3F1R) {

        int nf = s->channel_mode - 2;

        s->downmix_coeffs[nf][0] = s->downmix_coeffs[nf][1] = smix * LEVEL_MINUS_3DB;

    }

    if(s->channel_mode == AC3_CHMODE_2F2R || s->channel_mode == AC3_CHMODE_3F2R) {

        int nf = s->channel_mode - 4;

        s->downmix_coeffs[nf][0] = s->downmix_coeffs[nf+1][1] = smix;

    }



    s->downmix_coeff_sum[0] = s->downmix_coeff_sum[1] = 0.0f;

    for(i=0; i<s->fbw_channels; i++) {

        s->downmix_coeff_sum[0] += s->downmix_coeffs[i][0];

        s->downmix_coeff_sum[1] += s->downmix_coeffs[i][1];

    }

}

static void calc_diffs(const DecimateContext *dm, struct qitem *q,

                       const AVFrame *f1, const AVFrame *f2)

{

    int64_t maxdiff = -1;

    int64_t *bdiffs = dm->bdiffs;

    int plane, i, j;



    memset(bdiffs, 0, dm->bdiffsize * sizeof(*bdiffs));



    for (plane = 0; plane < (dm->chroma ? 3 : 1); plane++) {

        int x, y, xl;

        const int linesize1 = f1->linesize[plane];

        const int linesize2 = f2->linesize[plane];

        const uint8_t *f1p = f1->data[plane];

        const uint8_t *f2p = f2->data[plane];

        int width    = plane ? FF_CEIL_RSHIFT(f1->width,  dm->hsub) : f1->width;

        int height   = plane ? FF_CEIL_RSHIFT(f1->height, dm->vsub) : f1->height;

        int hblockx  = dm->blockx / 2;

        int hblocky  = dm->blocky / 2;



        if (plane) {

            hblockx >>= dm->hsub;

            hblocky >>= dm->vsub;

        }



        for (y = 0; y < height; y++) {

            int ydest = y / hblocky;

            int xdest = 0;



#define CALC_DIFF(nbits) do {                               \

    for (x = 0; x < width; x += hblockx) {                  \

        int64_t acc = 0;                                    \

        int m = FFMIN(width, x + hblockx);                  \

        for (xl = x; xl < m; xl++)                          \

            acc += abs(((const uint##nbits##_t *)f1p)[xl] - \

                       ((const uint##nbits##_t *)f2p)[xl]); \

        bdiffs[ydest * dm->nxblocks + xdest] += acc;        \

        xdest++;                                            \

    }                                                       \

} while (0)

            if (dm->depth == 8) CALC_DIFF(8);

            else                CALC_DIFF(16);



            f1p += linesize1;

            f2p += linesize2;

        }

    }



    for (i = 0; i < dm->nyblocks - 1; i++) {

        for (j = 0; j < dm->nxblocks - 1; j++) {

            int64_t tmp = bdiffs[      i * dm->nxblocks + j    ]

                        + bdiffs[      i * dm->nxblocks + j + 1]

                        + bdiffs[(i + 1) * dm->nxblocks + j    ]

                        + bdiffs[(i + 1) * dm->nxblocks + j + 1];

            if (tmp > maxdiff)

                maxdiff = tmp;

        }

    }



    q->totdiff = 0;

    for (i = 0; i < dm->bdiffsize; i++)

        q->totdiff += bdiffs[i];

    q->maxbdiff = maxdiff;

}

static void compute_exp_strategy(AC3EncodeContext *s)

{

    int ch, blk, blk1;



    for (ch = !s->cpl_on; ch <= s->fbw_channels; ch++) {

        uint8_t *exp_strategy = s->exp_strategy[ch];

        uint8_t *exp          = s->blocks[0].exp[ch];

        int exp_diff;



        /* estimate if the exponent variation & decide if they should be

           reused in the next frame */

        exp_strategy[0] = EXP_NEW;

        exp += AC3_MAX_COEFS;

        for (blk = 1; blk < AC3_MAX_BLOCKS; blk++, exp += AC3_MAX_COEFS) {

            if ((ch == CPL_CH && (!s->blocks[blk].cpl_in_use || !s->blocks[blk-1].cpl_in_use)) ||

                (ch  > CPL_CH && (s->blocks[blk].channel_in_cpl[ch] != s->blocks[blk-1].channel_in_cpl[ch]))) {

                exp_strategy[blk] = EXP_NEW;

                continue;

            }

            exp_diff = s->dsp.sad[0](NULL, exp, exp - AC3_MAX_COEFS, 16, 16);

            exp_strategy[blk] = EXP_REUSE;

            if (ch == CPL_CH && exp_diff > (EXP_DIFF_THRESHOLD * (s->blocks[blk].end_freq[ch] - s->start_freq[ch]) / AC3_MAX_COEFS))

                exp_strategy[blk] = EXP_NEW;

            else if (ch > CPL_CH && exp_diff > EXP_DIFF_THRESHOLD)

                exp_strategy[blk] = EXP_NEW;

        }



        /* now select the encoding strategy type : if exponents are often

           recoded, we use a coarse encoding */

        blk = 0;

        while (blk < AC3_MAX_BLOCKS) {

            blk1 = blk + 1;

            while (blk1 < AC3_MAX_BLOCKS && exp_strategy[blk1] == EXP_REUSE)

                blk1++;

            switch (blk1 - blk) {

            case 1:  exp_strategy[blk] = EXP_D45; break;

            case 2:

            case 3:  exp_strategy[blk] = EXP_D25; break;

            default: exp_strategy[blk] = EXP_D15; break;

            }

            blk = blk1;

        }

    }

    if (s->lfe_on) {

        ch = s->lfe_channel;

        s->exp_strategy[ch][0] = EXP_D15;

        for (blk = 1; blk < AC3_MAX_BLOCKS; blk++)

            s->exp_strategy[ch][blk] = EXP_REUSE;

    }

}

static void put_frame(

                    AVFormatContext *s,

                    ASFStream       *stream,

                    AVStream        *avst,

                    int             timestamp,

                    const uint8_t   *buf,

                    int             m_obj_size,

                    int             flags

                )

{

    ASFContext *asf = s->priv_data;

    int m_obj_offset, payload_len, frag_len1;



    m_obj_offset = 0;

    while (m_obj_offset < m_obj_size) {

        payload_len = m_obj_size - m_obj_offset;

        if (asf->packet_timestamp_start == -1) {

            asf->multi_payloads_present = (payload_len < MULTI_PAYLOAD_CONSTANT);



            asf->packet_size_left = PACKET_SIZE;

            if (asf->multi_payloads_present){

                frag_len1 = MULTI_PAYLOAD_CONSTANT - 1;

            }

            else {

                frag_len1 = SINGLE_PAYLOAD_DATA_LENGTH;

            }

            asf->packet_timestamp_start = timestamp;

        }

        else {

            // multi payloads

            frag_len1 = asf->packet_size_left - PAYLOAD_HEADER_SIZE_MULTIPLE_PAYLOADS - PACKET_HEADER_MIN_SIZE - 1;



            asf->packet_timestamp_start = timestamp;



            if(frag_len1 < payload_len && avst->codec->codec_type == CODEC_TYPE_AUDIO){

                flush_packet(s);

                continue;

            }

        }

        if (frag_len1 > 0) {

            if (payload_len > frag_len1)

                payload_len = frag_len1;

            else if (payload_len == (frag_len1 - 1))

                payload_len = frag_len1 - 2;  //additional byte need to put padding length



            put_payload_header(s, stream, timestamp+PREROLL_TIME, m_obj_size, m_obj_offset, payload_len, flags);

            put_buffer(&asf->pb, buf, payload_len);



            if (asf->multi_payloads_present)

                asf->packet_size_left -= (payload_len + PAYLOAD_HEADER_SIZE_MULTIPLE_PAYLOADS);

            else

                asf->packet_size_left -= (payload_len + PAYLOAD_HEADER_SIZE_SINGLE_PAYLOAD);

            asf->packet_timestamp_end = timestamp;



            asf->packet_nb_payloads++;

        } else {

            payload_len = 0;

        }

        m_obj_offset += payload_len;

        buf += payload_len;



        if (!asf->multi_payloads_present)

            flush_packet(s);

        else if (asf->packet_size_left <= (PAYLOAD_HEADER_SIZE_MULTIPLE_PAYLOADS + PACKET_HEADER_MIN_SIZE + 1))

            flush_packet(s);

    }

    stream->seq++;

}

static void render_fragments(Vp3DecodeContext *s,
                             int first_fragment,
                             int width,
                             int height,
                             int plane /* 0 = Y, 1 = U, 2 = V */) 
{
    int x, y;
    int m, n;
    int i = first_fragment;
    int16_t *dequantizer;
    DCTELEM __align16 output_samples[64];
    unsigned char *output_plane;
    unsigned char *last_plane;
    unsigned char *golden_plane;
    int stride;
    int motion_x = 0xdeadbeef, motion_y = 0xdeadbeef;
    int upper_motion_limit, lower_motion_limit;
    int motion_halfpel_index;
    uint8_t *motion_source;
    debug_vp3("  vp3: rendering final fragments for %s\n",
        (plane == 0) ? "Y plane" : (plane == 1) ? "U plane" : "V plane");
    /* set up plane-specific parameters */
    if (plane == 0) {
        dequantizer = s->intra_y_dequant;
        output_plane = s->current_frame.data[0];
        last_plane = s->last_frame.data[0];
        golden_plane = s->golden_frame.data[0];
        stride = s->current_frame.linesize[0];
	if (!s->flipped_image) stride = -stride;
        upper_motion_limit = 7 * s->current_frame.linesize[0];
        lower_motion_limit = height * s->current_frame.linesize[0] + width - 8;
    } else if (plane == 1) {
        dequantizer = s->intra_c_dequant;
        output_plane = s->current_frame.data[1];
        last_plane = s->last_frame.data[1];
        golden_plane = s->golden_frame.data[1];
        stride = s->current_frame.linesize[1];
	if (!s->flipped_image) stride = -stride;
        upper_motion_limit = 7 * s->current_frame.linesize[1];
        lower_motion_limit = height * s->current_frame.linesize[1] + width - 8;
    } else {
        dequantizer = s->intra_c_dequant;
        output_plane = s->current_frame.data[2];
        last_plane = s->last_frame.data[2];
        golden_plane = s->golden_frame.data[2];
        stride = s->current_frame.linesize[2];
	if (!s->flipped_image) stride = -stride;
        upper_motion_limit = 7 * s->current_frame.linesize[2];
        lower_motion_limit = height * s->current_frame.linesize[2] + width - 8;
    }
    /* for each fragment row... */
    for (y = 0; y < height; y += 8) {
        /* for each fragment in a row... */
        for (x = 0; x < width; x += 8, i++) {
            if ((i < 0) || (i >= s->fragment_count)) {
                av_log(s->avctx, AV_LOG_ERROR, "  vp3:render_fragments(): bad fragment number (%d)\n", i);
                return;
            }
            /* transform if this block was coded */
            if ((s->all_fragments[i].coding_method != MODE_COPY) &&
		!((s->avctx->flags & CODEC_FLAG_GRAY) && plane)) {
                if ((s->all_fragments[i].coding_method == MODE_USING_GOLDEN) ||
                    (s->all_fragments[i].coding_method == MODE_GOLDEN_MV))
                    motion_source= golden_plane;
                else 
                    motion_source= last_plane;
                motion_source += s->all_fragments[i].first_pixel;
                motion_halfpel_index = 0;
                /* sort out the motion vector if this fragment is coded
                 * using a motion vector method */
                if ((s->all_fragments[i].coding_method > MODE_INTRA) &&
                    (s->all_fragments[i].coding_method != MODE_USING_GOLDEN)) {
                    int src_x, src_y;
                    motion_x = s->all_fragments[i].motion_x;
                    motion_y = s->all_fragments[i].motion_y;
                    if(plane){
                        motion_x= (motion_x>>1) | (motion_x&1);
                        motion_y= (motion_y>>1) | (motion_y&1);
                    }
                    src_x= (motion_x>>1) + x;
                    src_y= (motion_y>>1) + y;
if ((motion_x == 0xbeef) || (motion_y == 0xbeef))
av_log(s->avctx, AV_LOG_ERROR, " help! got beefy vector! (%X, %X)\n", motion_x, motion_y);
                    motion_halfpel_index = motion_x & 0x01;
                    motion_source += (motion_x >> 1);
//                    motion_y = -motion_y;
                    motion_halfpel_index |= (motion_y & 0x01) << 1;
                    motion_source += ((motion_y >> 1) * stride);
                    if(src_x<0 || src_y<0 || src_x + 9 >= width || src_y + 9 >= height){
                        uint8_t *temp= s->edge_emu_buffer;
                        if(stride<0) temp -= 9*stride;
			else temp += 9*stride;
                        ff_emulated_edge_mc(temp, motion_source, stride, 9, 9, src_x, src_y, width, height);
                        motion_source= temp;
                    }
                }
                /* first, take care of copying a block from either the
                 * previous or the golden frame */
                if (s->all_fragments[i].coding_method != MODE_INTRA) {
                    //Note, it is possible to implement all MC cases with put_no_rnd_pixels_l2 which would look more like the VP3 source but this would be slower as put_no_rnd_pixels_tab is better optimzed
                    if(motion_halfpel_index != 3){
                        s->dsp.put_no_rnd_pixels_tab[1][motion_halfpel_index](
                            output_plane + s->all_fragments[i].first_pixel,
                            motion_source, stride, 8);
                    }else{
                        int d= (motion_x ^ motion_y)>>31; // d is 0 if motion_x and _y have the same sign, else -1
                        s->dsp.put_no_rnd_pixels_l2[1](
                            output_plane + s->all_fragments[i].first_pixel,
                            motion_source - d, 
                            motion_source + stride + 1 + d, 
                            stride, 8);
                    }
                }
                /* dequantize the DCT coefficients */
                debug_idct("fragment %d, coding mode %d, DC = %d, dequant = %d:\n", 
                    i, s->all_fragments[i].coding_method, 
                    s->all_fragments[i].coeffs[0], dequantizer[0]);
                /* invert DCT and place (or add) in final output */
                s->dsp.vp3_idct(s->all_fragments[i].coeffs,
                    dequantizer,
                    s->all_fragments[i].coeff_count,
                    output_samples);
                if (s->all_fragments[i].coding_method == MODE_INTRA) {
                    s->dsp.put_signed_pixels_clamped(output_samples,
                        output_plane + s->all_fragments[i].first_pixel,
                        stride);
                } else {
                    s->dsp.add_pixels_clamped(output_samples,
                        output_plane + s->all_fragments[i].first_pixel,
                        stride);
                }
                debug_idct("block after idct_%s():\n",
                    (s->all_fragments[i].coding_method == MODE_INTRA)?
                    "put" : "add");
                for (m = 0; m < 8; m++) {
                    for (n = 0; n < 8; n++) {
                        debug_idct(" %3d", *(output_plane + 
                            s->all_fragments[i].first_pixel + (m * stride + n)));
                    }
                    debug_idct("\n");
                }
                debug_idct("\n");
            } else {
                /* copy directly from the previous frame */
                s->dsp.put_pixels_tab[1][0](
                    output_plane + s->all_fragments[i].first_pixel,
                    last_plane + s->all_fragments[i].first_pixel,
                    stride, 8);
            }
        }
    }
    emms_c();
}

