static int lag_decode_zero_run_line(LagarithContext *l, uint8_t *dst,

                                    const uint8_t *src, int width,

                                    int esc_count)

{

    int i = 0;

    int count;

    uint8_t zero_run = 0;

    const uint8_t *start = src;

    uint8_t mask1 = -(esc_count < 2);

    uint8_t mask2 = -(esc_count < 3);

    uint8_t *end = dst + (width - 2);



output_zeros:

    if (l->zeros_rem) {

        count = FFMIN(l->zeros_rem, width - i);

        memset(dst, 0, count);

        l->zeros_rem -= count;

        dst += count;

    }



    while (dst < end) {

        i = 0;

        while (!zero_run && dst + i < end) {

            i++;

            zero_run =

                !(src[i] | (src[i + 1] & mask1) | (src[i + 2] & mask2));

        }

        if (zero_run) {

            zero_run = 0;

            i += esc_count;

            memcpy(dst, src, i);

            dst += i;

            l->zeros_rem = lag_calc_zero_run(src[i]);



            src += i + 1;

            goto output_zeros;

        } else {

            memcpy(dst, src, i);

            src += i;

        }

    }

    return  src - start;

}

static int stream_component_open(VideoState *is, int stream_index)

{

    AVFormatContext *ic = is->ic;

    AVCodecContext *enc;

    AVCodec *codec;

    SDL_AudioSpec wanted_spec, spec;



    if (stream_index < 0 || stream_index >= ic->nb_streams)

        return -1;

    enc = ic->streams[stream_index]->codec;



    /* prepare audio output */

    if (enc->codec_type == CODEC_TYPE_AUDIO) {

        if (enc->channels > 0) {

            enc->request_channels = FFMIN(2, enc->channels);

        } else {

            enc->request_channels = 2;

        }

    }



    codec = avcodec_find_decoder(enc->codec_id);

    enc->debug_mv = debug_mv;

    enc->debug = debug;

    enc->workaround_bugs = workaround_bugs;

    enc->lowres = lowres;

    if(lowres) enc->flags |= CODEC_FLAG_EMU_EDGE;

    enc->idct_algo= idct;

    if(fast) enc->flags2 |= CODEC_FLAG2_FAST;

    enc->skip_frame= skip_frame;

    enc->skip_idct= skip_idct;

    enc->skip_loop_filter= skip_loop_filter;

    enc->error_recognition= error_recognition;

    enc->error_concealment= error_concealment;

    avcodec_thread_init(enc, thread_count);



    set_context_opts(enc, avcodec_opts[enc->codec_type], 0);



    if (!codec ||

        avcodec_open(enc, codec) < 0)

        return -1;



    /* prepare audio output */

    if (enc->codec_type == CODEC_TYPE_AUDIO) {

        wanted_spec.freq = enc->sample_rate;

        wanted_spec.format = AUDIO_S16SYS;

        wanted_spec.channels = enc->channels;

        wanted_spec.silence = 0;

        wanted_spec.samples = SDL_AUDIO_BUFFER_SIZE;

        wanted_spec.callback = sdl_audio_callback;

        wanted_spec.userdata = is;

        if (SDL_OpenAudio(&wanted_spec, &spec) < 0) {

            fprintf(stderr, "SDL_OpenAudio: %s\n", SDL_GetError());

            return -1;

        }

        is->audio_hw_buf_size = spec.size;

        is->audio_src_fmt= SAMPLE_FMT_S16;

    }



    ic->streams[stream_index]->discard = AVDISCARD_DEFAULT;

    switch(enc->codec_type) {

    case CODEC_TYPE_AUDIO:

        is->audio_stream = stream_index;

        is->audio_st = ic->streams[stream_index];

        is->audio_buf_size = 0;

        is->audio_buf_index = 0;



        /* init averaging filter */

        is->audio_diff_avg_coef = exp(log(0.01) / AUDIO_DIFF_AVG_NB);

        is->audio_diff_avg_count = 0;

        /* since we do not have a precise anough audio fifo fullness,

           we correct audio sync only if larger than this threshold */

        is->audio_diff_threshold = 2.0 * SDL_AUDIO_BUFFER_SIZE / enc->sample_rate;



        memset(&is->audio_pkt, 0, sizeof(is->audio_pkt));

        packet_queue_init(&is->audioq);

        SDL_PauseAudio(0);

        break;

    case CODEC_TYPE_VIDEO:

        is->video_stream = stream_index;

        is->video_st = ic->streams[stream_index];



        is->frame_last_delay = 40e-3;

        is->frame_timer = (double)av_gettime() / 1000000.0;

        is->video_current_pts_time = av_gettime();



        packet_queue_init(&is->videoq);

        is->video_tid = SDL_CreateThread(video_thread, is);

        break;

    case CODEC_TYPE_SUBTITLE:

        is->subtitle_stream = stream_index;

        is->subtitle_st = ic->streams[stream_index];

        packet_queue_init(&is->subtitleq);



        is->subtitle_tid = SDL_CreateThread(subtitle_thread, is);

        break;

    default:

        break;

    }

    return 0;

}

static int sls_flags_filename_process(struct AVFormatContext *s, HLSContext *hls,

                                      VariantStream *vs, HLSSegment *en,

                                      double duration, int64_t pos, int64_t size)

{

    if ((hls->flags & (HLS_SECOND_LEVEL_SEGMENT_SIZE | HLS_SECOND_LEVEL_SEGMENT_DURATION)) &&

        strlen(vs->current_segment_final_filename_fmt)) {

        av_strlcpy(vs->avf->filename, vs->current_segment_final_filename_fmt, sizeof(vs->avf->filename));

        if (hls->flags & HLS_SECOND_LEVEL_SEGMENT_SIZE) {

            char * filename = av_strdup(vs->avf->filename);  // %%s will be %s after strftime

            if (!filename) {

                av_free(en);

                return AVERROR(ENOMEM);

            }

            if (replace_int_data_in_filename(vs->avf->filename, sizeof(vs->avf->filename),

                filename, 's', pos + size) < 1) {

                av_log(hls, AV_LOG_ERROR,

                       "Invalid second level segment filename template '%s', "

                        "you can try to remove second_level_segment_size flag\n",

                       filename);

                av_free(filename);

                av_free(en);

                return AVERROR(EINVAL);

            }

            av_free(filename);

        }

        if (hls->flags & HLS_SECOND_LEVEL_SEGMENT_DURATION) {

            char * filename = av_strdup(vs->avf->filename);  // %%t will be %t after strftime

            if (!filename) {

                av_free(en);

                return AVERROR(ENOMEM);

            }

            if (replace_int_data_in_filename(vs->avf->filename, sizeof(vs->avf->filename),

                filename, 't',  (int64_t)round(duration * HLS_MICROSECOND_UNIT)) < 1) {

                av_log(hls, AV_LOG_ERROR,

                       "Invalid second level segment filename template '%s', "

                        "you can try to remove second_level_segment_time flag\n",

                       filename);

                av_free(filename);

                av_free(en);

                return AVERROR(EINVAL);

            }

            av_free(filename);

        }

    }

    return 0;

}

static void do_downmix(AC3DecodeContext *ctx)

{

    int from = ctx->bsi.acmod;

    int to = ctx->output;



    switch (from) {

        case AC3_INPUT_DUALMONO:

            switch (to) {

                case AC3_OUTPUT_MONO:

                    mix_dualmono_to_mono(ctx);

                    break;

                case AC3_OUTPUT_STEREO: /* We Assume that sum of both mono channels is requested */

                    mix_dualmono_to_stereo(ctx);

                    break;

            }

            break;

        case AC3_INPUT_MONO:

            switch (to) {

                case AC3_OUTPUT_STEREO:

                    upmix_mono_to_stereo(ctx);

                    break;

            }

            break;

        case AC3_INPUT_STEREO:

            switch (to) {

                case AC3_OUTPUT_MONO:

                    mix_stereo_to_mono(ctx);

                    break;

            }

            break;

        case AC3_INPUT_3F:

            switch (to) {

                case AC3_OUTPUT_MONO:

                    mix_3f_to_mono(ctx);

                    break;

                case AC3_OUTPUT_STEREO:

                    mix_3f_to_stereo(ctx);

                    break;

            }

            break;

        case AC3_INPUT_2F_1R:

            switch (to) {

                case AC3_OUTPUT_MONO:

                    mix_2f_1r_to_mono(ctx);

                    break;

                case AC3_OUTPUT_STEREO:

                    mix_2f_1r_to_stereo(ctx);

                    break;

                case AC3_OUTPUT_DOLBY:

                    mix_2f_1r_to_dolby(ctx);

                    break;

            }

            break;

        case AC3_INPUT_3F_1R:

            switch (to) {

                case AC3_OUTPUT_MONO:

                    mix_3f_1r_to_mono(ctx);

                    break;

                case AC3_OUTPUT_STEREO:

                    mix_3f_1r_to_stereo(ctx);

                    break;

                case AC3_OUTPUT_DOLBY:

                    mix_3f_1r_to_dolby(ctx);

                    break;

            }

            break;

        case AC3_INPUT_2F_2R:

            switch (to) {

                case AC3_OUTPUT_MONO:

                    mix_2f_2r_to_mono(ctx);

                    break;

                case AC3_OUTPUT_STEREO:

                    mix_2f_2r_to_stereo(ctx);

                    break;

                case AC3_OUTPUT_DOLBY:

                    mix_2f_2r_to_dolby(ctx);

                    break;

            }

            break;

        case AC3_INPUT_3F_2R:

            switch (to) {

                case AC3_OUTPUT_MONO:

                    mix_3f_2r_to_mono(ctx);

                    break;

                case AC3_OUTPUT_STEREO:

                    mix_3f_2r_to_stereo(ctx);

                    break;

                case AC3_OUTPUT_DOLBY:

                    mix_3f_2r_to_dolby(ctx);

                    break;

            }

            break;

    }

}

static int get_avc_nalsize(H264Context *h, const uint8_t *buf,

                           int buf_size, int *buf_index)

{

    int i, nalsize = 0;



    if (*buf_index >= buf_size - h->nal_length_size)

        return -1;



    for (i = 0; i < h->nal_length_size; i++)

        nalsize = (nalsize << 8) | buf[(*buf_index)++];

    if (nalsize <= 0 || nalsize > buf_size - *buf_index) {

        av_log(h->avctx, AV_LOG_ERROR,

               "AVC: nal size %d\n", nalsize);

        return -1;

    }

    return nalsize;

}

static int decode_13(AVCodecContext *avctx, DxaDecContext *c, uint8_t* dst,

                     int stride, uint8_t *src, uint8_t *ref)

{

    uint8_t *code, *data, *mv, *msk, *tmp, *tmp2;

    int i, j, k;

    int type, x, y, d, d2;

    uint32_t mask;



    code = src  + 12;

    data = code + ((avctx->width * avctx->height) >> 4);

    mv   = data + AV_RB32(src + 0);

    msk  = mv   + AV_RB32(src + 4);



    for(j = 0; j < avctx->height; j += 4){

        for(i = 0; i < avctx->width; i += 4){

            tmp  = dst + i;

            tmp2 = ref + i;

            type = *code++;

            switch(type){

            case 4: // motion compensation

                x = (*mv) >> 4;    if(x & 8) x = 8 - x;

                y = (*mv++) & 0xF; if(y & 8) y = 8 - y;

                if (i < -x || avctx->width  - i - 4 < x ||

                    j < -y || avctx->height - j - 4 < y) {

                    av_log(avctx, AV_LOG_ERROR, "MV %d %d out of bounds\n", x,y);

                    return AVERROR_INVALIDDATA;

                }

                tmp2 += x + y*stride;

            case 0: // skip

            case 5: // skip in method 12

                for(y = 0; y < 4; y++){

                    memcpy(tmp, tmp2, 4);

                    tmp  += stride;

                    tmp2 += stride;

                }

                break;

            case 1:  // masked change

            case 10: // masked change with only half of pixels changed

            case 11: // cases 10-15 are for method 12 only

            case 12:

            case 13:

            case 14:

            case 15:

                if(type == 1){

                    mask = AV_RB16(msk);

                    msk += 2;

                }else{

                    type -= 10;

                    mask = ((msk[0] & 0xF0) << shift1[type]) | ((msk[0] & 0xF) << shift2[type]);

                    msk++;

                }

                for(y = 0; y < 4; y++){

                    for(x = 0; x < 4; x++){

                        tmp[x] = (mask & 0x8000) ? *data++ : tmp2[x];

                        mask <<= 1;

                    }

                    tmp  += stride;

                    tmp2 += stride;

                }

                break;

            case 2: // fill block

                for(y = 0; y < 4; y++){

                    memset(tmp, data[0], 4);

                    tmp += stride;

                }

                data++;

                break;

            case 3: // raw block

                for(y = 0; y < 4; y++){

                    memcpy(tmp, data, 4);

                    data += 4;

                    tmp  += stride;

                }

                break;

            case 8: // subblocks - method 13 only

                mask = *msk++;

                for(k = 0; k < 4; k++){

                    d  = ((k & 1) << 1) + ((k & 2) * stride);

                    d2 = ((k & 1) << 1) + ((k & 2) * stride);

                    tmp2 = ref + i + d2;

                    switch(mask & 0xC0){

                    case 0x80: // motion compensation

                        x = (*mv) >> 4;    if(x & 8) x = 8 - x;

                        y = (*mv++) & 0xF; if(y & 8) y = 8 - y;

                        if (i + 2*(k & 1) < -x || avctx->width  - i - 2*(k & 1) - 2 < x ||

                            j +   (k & 2) < -y || avctx->height - j -   (k & 2) - 2 < y) {

                            av_log(avctx, AV_LOG_ERROR, "MV %d %d out of bounds\n", x,y);

                            return AVERROR_INVALIDDATA;

                        }

                        tmp2 += x + y*stride;

                    case 0x00: // skip

                        tmp[d + 0         ] = tmp2[0];

                        tmp[d + 1         ] = tmp2[1];

                        tmp[d + 0 + stride] = tmp2[0 + stride];

                        tmp[d + 1 + stride] = tmp2[1 + stride];

                        break;

                    case 0x40: // fill

                        tmp[d + 0         ] = data[0];

                        tmp[d + 1         ] = data[0];

                        tmp[d + 0 + stride] = data[0];

                        tmp[d + 1 + stride] = data[0];

                        data++;

                        break;

                    case 0xC0: // raw

                        tmp[d + 0         ] = *data++;

                        tmp[d + 1         ] = *data++;

                        tmp[d + 0 + stride] = *data++;

                        tmp[d + 1 + stride] = *data++;

                        break;

                    }

                    mask <<= 2;

                }

                break;

            case 32: // vector quantization - 2 colors

                mask = AV_RB16(msk);

                msk += 2;

                for(y = 0; y < 4; y++){

                    for(x = 0; x < 4; x++){

                        tmp[x] = data[mask & 1];

                        mask >>= 1;

                    }

                    tmp  += stride;

                    tmp2 += stride;

                }

                data += 2;

                break;

            case 33: // vector quantization - 3 or 4 colors

            case 34:

                mask = AV_RB32(msk);

                msk += 4;

                for(y = 0; y < 4; y++){

                    for(x = 0; x < 4; x++){

                        tmp[x] = data[mask & 3];

                        mask >>= 2;

                    }

                    tmp  += stride;

                    tmp2 += stride;

                }

                data += type - 30;

                break;

            default:

                av_log(avctx, AV_LOG_ERROR, "Unknown opcode %d\n", type);

                return AVERROR_INVALIDDATA;

            }

        }

        dst += stride * 4;

        ref += stride * 4;

    }

    return 0;

}

void palette8tobgr32(const uint8_t *src, uint8_t *dst, long num_pixels, const uint8_t *palette)

{

	long i;

	for(i=0; i<num_pixels; i++)

	{

		#ifdef WORDS_BIGENDIAN

			dst[3]= palette[ src[i]*4+0 ];

			dst[2]= palette[ src[i]*4+1 ];

			dst[1]= palette[ src[i]*4+2 ];

		#else

			//FIXME slow?

			dst[0]= palette[ src[i]*4+0 ];

			dst[1]= palette[ src[i]*4+1 ];

			dst[2]= palette[ src[i]*4+2 ];

			//dst[3]= 0; /* do we need this cleansing? */

		#endif



		dst+= 4;

	}

}

static int flic_decode_frame_15_16BPP(AVCodecContext *avctx,

                                      void *data, int *got_frame,

                                      const uint8_t *buf, int buf_size)

{

    /* Note, the only difference between the 15Bpp and 16Bpp */

    /* Format is the pixel format, the packets are processed the same. */

    FlicDecodeContext *s = avctx->priv_data;



    GetByteContext g2;

    int pixel_ptr;

    unsigned char palette_idx1;



    unsigned int frame_size;

    int num_chunks;



    unsigned int chunk_size;

    int chunk_type;



    int i, j, ret;



    int lines;

    int compressed_lines;

    signed short line_packets;

    int y_ptr;

    int byte_run;

    int pixel_skip;

    int pixel_countdown;

    unsigned char *pixels;

    int pixel;

    unsigned int pixel_limit;



    bytestream2_init(&g2, buf, buf_size);



    if ((ret = ff_reget_buffer(avctx, &s->frame)) < 0)

        return ret;



    pixels = s->frame.data[0];

    pixel_limit = s->avctx->height * s->frame.linesize[0];



    frame_size = bytestream2_get_le32(&g2);

    bytestream2_skip(&g2, 2);  /* skip the magic number */

    num_chunks = bytestream2_get_le16(&g2);

    bytestream2_skip(&g2, 8);  /* skip padding */

    if (frame_size > buf_size)

        frame_size = buf_size;



    frame_size -= 16;



    /* iterate through the chunks */

    while ((frame_size > 0) && (num_chunks > 0)) {

        int stream_ptr_after_chunk;

        chunk_size = bytestream2_get_le32(&g2);

        if (chunk_size > frame_size) {

            av_log(avctx, AV_LOG_WARNING,

                   "Invalid chunk_size = %u > frame_size = %u\n", chunk_size, frame_size);

            chunk_size = frame_size;

        }

        stream_ptr_after_chunk = bytestream2_tell(&g2) - 4 + chunk_size;



        chunk_type = bytestream2_get_le16(&g2);





        switch (chunk_type) {

        case FLI_256_COLOR:

        case FLI_COLOR:

            /* For some reason, it seems that non-palettized flics do

             * include one of these chunks in their first frame.

             * Why I do not know, it seems rather extraneous. */

            av_dlog(avctx,

                    "Unexpected Palette chunk %d in non-palettized FLC\n",

                    chunk_type);

            bytestream2_skip(&g2, chunk_size - 6);

            break;



        case FLI_DELTA:

        case FLI_DTA_LC:

            y_ptr = 0;

            compressed_lines = bytestream2_get_le16(&g2);

            while (compressed_lines > 0) {

                if (bytestream2_tell(&g2) + 2 > stream_ptr_after_chunk)

                    break;

                line_packets = bytestream2_get_le16(&g2);

                if (line_packets < 0) {

                    line_packets = -line_packets;

                    y_ptr += line_packets * s->frame.linesize[0];

                } else {

                    compressed_lines--;

                    pixel_ptr = y_ptr;

                    CHECK_PIXEL_PTR(0);

                    pixel_countdown = s->avctx->width;

                    for (i = 0; i < line_packets; i++) {

                        /* account for the skip bytes */

                        if (bytestream2_tell(&g2) + 2 > stream_ptr_after_chunk)

                            break;

                        pixel_skip = bytestream2_get_byte(&g2);

                        pixel_ptr += (pixel_skip*2); /* Pixel is 2 bytes wide */

                        pixel_countdown -= pixel_skip;

                        byte_run = sign_extend(bytestream2_get_byte(&g2), 8);

                        if (byte_run < 0) {

                            byte_run = -byte_run;

                            pixel    = bytestream2_get_le16(&g2);

                            CHECK_PIXEL_PTR(2 * byte_run);

                            for (j = 0; j < byte_run; j++, pixel_countdown -= 2) {

                                *((signed short*)(&pixels[pixel_ptr])) = pixel;

                                pixel_ptr += 2;

                            }

                        } else {

                            if (bytestream2_tell(&g2) + 2*byte_run > stream_ptr_after_chunk)

                                break;

                            CHECK_PIXEL_PTR(2 * byte_run);

                            for (j = 0; j < byte_run; j++, pixel_countdown--) {

                                *((signed short*)(&pixels[pixel_ptr])) = bytestream2_get_le16(&g2);

                                pixel_ptr += 2;

                            }

                        }

                    }



                    y_ptr += s->frame.linesize[0];

                }

            }

            break;



        case FLI_LC:

            av_log(avctx, AV_LOG_ERROR, "Unexpected FLI_LC chunk in non-palettized FLC\n");

            bytestream2_skip(&g2, chunk_size - 6);

            break;



        case FLI_BLACK:

            /* set the whole frame to 0x0000 which is black in both 15Bpp and 16Bpp modes. */

            memset(pixels, 0x0000,

                   s->frame.linesize[0] * s->avctx->height);

            break;



        case FLI_BRUN:

            y_ptr = 0;

            for (lines = 0; lines < s->avctx->height; lines++) {

                pixel_ptr = y_ptr;

                /* disregard the line packets; instead, iterate through all

                 * pixels on a row */

                bytestream2_skip(&g2, 1);

                pixel_countdown = (s->avctx->width * 2);



                while (pixel_countdown > 0) {

                    if (bytestream2_tell(&g2) + 1 > stream_ptr_after_chunk)

                        break;

                    byte_run = sign_extend(bytestream2_get_byte(&g2), 8);

                    if (byte_run > 0) {

                        palette_idx1 = bytestream2_get_byte(&g2);

                        CHECK_PIXEL_PTR(byte_run);

                        for (j = 0; j < byte_run; j++) {

                            pixels[pixel_ptr++] = palette_idx1;

                            pixel_countdown--;

                            if (pixel_countdown < 0)

                                av_log(avctx, AV_LOG_ERROR, "pixel_countdown < 0 (%d) (linea%d)\n",

                                       pixel_countdown, lines);

                        }

                    } else {  /* copy bytes if byte_run < 0 */

                        byte_run = -byte_run;

                        if (bytestream2_tell(&g2) + byte_run > stream_ptr_after_chunk)

                            break;

                        CHECK_PIXEL_PTR(byte_run);

                        for (j = 0; j < byte_run; j++) {

                            palette_idx1 = bytestream2_get_byte(&g2);

                            pixels[pixel_ptr++] = palette_idx1;

                            pixel_countdown--;

                            if (pixel_countdown < 0)

                                av_log(avctx, AV_LOG_ERROR, "pixel_countdown < 0 (%d) at line %d\n",

                                       pixel_countdown, lines);

                        }

                    }

                }



                /* Now FLX is strange, in that it is "byte" as opposed to "pixel" run length compressed.

                 * This does not give us any good opportunity to perform word endian conversion

                 * during decompression. So if it is required (i.e., this is not a LE target, we do

                 * a second pass over the line here, swapping the bytes.

                 */

#if HAVE_BIGENDIAN

                pixel_ptr = y_ptr;

                pixel_countdown = s->avctx->width;

                while (pixel_countdown > 0) {

                    *((signed short*)(&pixels[pixel_ptr])) = AV_RL16(&buf[pixel_ptr]);

                    pixel_ptr += 2;

                }

#endif

                y_ptr += s->frame.linesize[0];

            }

            break;



        case FLI_DTA_BRUN:

            y_ptr = 0;

            for (lines = 0; lines < s->avctx->height; lines++) {

                pixel_ptr = y_ptr;

                /* disregard the line packets; instead, iterate through all

                 * pixels on a row */

                bytestream2_skip(&g2, 1);

                pixel_countdown = s->avctx->width; /* Width is in pixels, not bytes */



                while (pixel_countdown > 0) {

                    if (bytestream2_tell(&g2) + 1 > stream_ptr_after_chunk)

                        break;

                    byte_run = sign_extend(bytestream2_get_byte(&g2), 8);

                    if (byte_run > 0) {

                        pixel    = bytestream2_get_le16(&g2);

                        CHECK_PIXEL_PTR(2 * byte_run);

                        for (j = 0; j < byte_run; j++) {

                            *((signed short*)(&pixels[pixel_ptr])) = pixel;

                            pixel_ptr += 2;

                            pixel_countdown--;

                            if (pixel_countdown < 0)

                                av_log(avctx, AV_LOG_ERROR, "pixel_countdown < 0 (%d)\n",

                                       pixel_countdown);

                        }

                    } else {  /* copy pixels if byte_run < 0 */

                        byte_run = -byte_run;

                        if (bytestream2_tell(&g2) + 2 * byte_run > stream_ptr_after_chunk)

                            break;

                        CHECK_PIXEL_PTR(2 * byte_run);

                        for (j = 0; j < byte_run; j++) {

                            *((signed short*)(&pixels[pixel_ptr])) = bytestream2_get_le16(&g2);

                            pixel_ptr  += 2;

                            pixel_countdown--;

                            if (pixel_countdown < 0)

                                av_log(avctx, AV_LOG_ERROR, "pixel_countdown < 0 (%d)\n",

                                       pixel_countdown);

                        }

                    }

                }



                y_ptr += s->frame.linesize[0];

            }

            break;



        case FLI_COPY:

        case FLI_DTA_COPY:

            /* copy the chunk (uncompressed frame) */

            if (chunk_size - 6 > (unsigned int)(s->avctx->width * s->avctx->height)*2) {

                av_log(avctx, AV_LOG_ERROR, "In chunk FLI_COPY : source data (%d bytes) " \

                       "bigger than image, skipping chunk\n", chunk_size - 6);

                bytestream2_skip(&g2, chunk_size - 6);

            } else {



                for (y_ptr = 0; y_ptr < s->frame.linesize[0] * s->avctx->height;

                     y_ptr += s->frame.linesize[0]) {



                    pixel_countdown = s->avctx->width;

                    pixel_ptr = 0;

                    while (pixel_countdown > 0) {

                      *((signed short*)(&pixels[y_ptr + pixel_ptr])) = bytestream2_get_le16(&g2);

                      pixel_ptr += 2;

                      pixel_countdown--;

                    }

                }

            }

            break;



        case FLI_MINI:

            /* some sort of a thumbnail? disregard this chunk... */

            bytestream2_skip(&g2, chunk_size - 6);

            break;



        default:

            av_log(avctx, AV_LOG_ERROR, "Unrecognized chunk type: %d\n", chunk_type);

            break;

        }



        frame_size -= chunk_size;

        num_chunks--;

    }



    /* by the end of the chunk, the stream ptr should equal the frame

     * size (minus 1, possibly); if it doesn't, issue a warning */

    if ((bytestream2_get_bytes_left(&g2) != 0) && (bytestream2_get_bytes_left(&g2) != 1))

        av_log(avctx, AV_LOG_ERROR, "Processed FLI chunk where chunk size = %d " \

               "and final chunk ptr = %d\n", buf_size, bytestream2_tell(&g2));



    if ((ret = av_frame_ref(data, &s->frame)) < 0)

        return ret;



    *got_frame = 1;



    return buf_size;

}

int check_intra_pred4x4_mode_emuedge(int mode, int mb_x, int mb_y, int *copy_buf)

{

    switch (mode) {

    case VERT_PRED:

        if (!mb_x && mb_y) {

            *copy_buf = 1;

            return mode;

        }

        /* fall-through */

    case DIAG_DOWN_LEFT_PRED:

    case VERT_LEFT_PRED:

        return !mb_y ? DC_127_PRED : mode;

    case HOR_PRED:

        if (!mb_y) {

            *copy_buf = 1;

            return mode;

        }

        /* fall-through */

    case HOR_UP_PRED:

        return !mb_x ? DC_129_PRED : mode;

    case TM_VP8_PRED:

        return check_tm_pred4x4_mode(mode, mb_x, mb_y);

    case DC_PRED: /* 4x4 DC doesn't use the same "H.264-style" exceptions

                   * as 16x16/8x8 DC */

    case DIAG_DOWN_RIGHT_PRED:

    case VERT_RIGHT_PRED:

    case HOR_DOWN_PRED:

        if (!mb_y || !mb_x)

            *copy_buf = 1;

        return mode;

    }

    return mode;

}

static int open_input(struct variant *var)

{

    struct segment *seg = var->segments[var->cur_seq_no - var->start_seq_no];

    if (seg->key_type == KEY_NONE) {

        return ffurl_open(&var->input, seg->url, AVIO_FLAG_READ,

                          &var->parent->interrupt_callback, NULL);

    } else if (seg->key_type == KEY_AES_128) {

        char iv[33], key[33], url[MAX_URL_SIZE];

        int ret;

        if (strcmp(seg->key, var->key_url)) {

            URLContext *uc;

            if (ffurl_open(&uc, seg->key, AVIO_FLAG_READ,

                           &var->parent->interrupt_callback, NULL) == 0) {

                if (ffurl_read_complete(uc, var->key, sizeof(var->key))

                    != sizeof(var->key)) {

                    av_log(NULL, AV_LOG_ERROR, "Unable to read key file %s\n",

                           seg->key);

                }

                ffurl_close(uc);

            } else {

                av_log(NULL, AV_LOG_ERROR, "Unable to open key file %s\n",

                       seg->key);

            }

            av_strlcpy(var->key_url, seg->key, sizeof(var->key_url));

        }

        ff_data_to_hex(iv, seg->iv, sizeof(seg->iv), 0);

        ff_data_to_hex(key, var->key, sizeof(var->key), 0);

        iv[32] = key[32] = '\0';

        if (strstr(seg->url, "://"))

            snprintf(url, sizeof(url), "crypto+%s", seg->url);

        else

            snprintf(url, sizeof(url), "crypto:%s", seg->url);

        if ((ret = ffurl_alloc(&var->input, url, AVIO_FLAG_READ,

                               &var->parent->interrupt_callback)) < 0)

            return ret;

        av_opt_set(var->input->priv_data, "key", key, 0);

        av_opt_set(var->input->priv_data, "iv", iv, 0);

        if ((ret = ffurl_connect(var->input, NULL)) < 0) {

            ffurl_close(var->input);

            var->input = NULL;

            return ret;

        }

        return 0;

    }

    return AVERROR(ENOSYS);

}

static int decode_frame(AVCodecContext *avctx, void *data, int *got_frame,
                        AVPacket *avpkt)
{
    AVFrame *frame = data;
    const uint8_t *buf = avpkt->data;
    const uint8_t *buf_end = buf + avpkt->size;
    KgvContext * const c = avctx->priv_data;
    int offsets[8];
    uint8_t *out, *prev;
    int outcnt = 0, maxcnt;
    int w, h, i, res;
    if (avpkt->size < 2)
    w = (buf[0] + 1) * 8;
    h = (buf[1] + 1) * 8;
    buf += 2;
    if (w != avctx->width || h != avctx->height) {
        av_freep(&c->frame_buffer);
        av_freep(&c->last_frame_buffer);
        if ((res = ff_set_dimensions(avctx, w, h)) < 0)
            return res;
    }
    if (!c->frame_buffer) {
        c->frame_buffer      = av_mallocz(avctx->width * avctx->height * 2);
        c->last_frame_buffer = av_mallocz(avctx->width * avctx->height * 2);
        if (!c->frame_buffer || !c->last_frame_buffer) {
            decode_flush(avctx);
            return AVERROR(ENOMEM);
        }
    }
    maxcnt = w * h;
    if ((res = ff_get_buffer(avctx, frame, 0)) < 0)
        return res;
    out  = (uint8_t*)c->frame_buffer;
    prev = (uint8_t*)c->last_frame_buffer;
    for (i = 0; i < 8; i++)
        offsets[i] = -1;
    while (outcnt < maxcnt && buf_end - 2 >= buf) {
        int code = AV_RL16(buf);
        buf += 2;
        if (!(code & 0x8000)) {
            AV_WN16A(&out[2 * outcnt], code); // rgb555 pixel coded directly
            outcnt++;
        } else {
            int count;
            if ((code & 0x6000) == 0x6000) {
                // copy from previous frame
                int oidx = (code >> 10) & 7;
                int start;
                count = (code & 0x3FF) + 3;
                if (offsets[oidx] < 0) {
                    if (buf_end - 3 < buf)
                        break;
                    offsets[oidx] = AV_RL24(buf);
                    buf += 3;
                }
                start = (outcnt + offsets[oidx]) % maxcnt;
                if (maxcnt - start < count || maxcnt - outcnt < count)
                    break;
                if (!prev) {
                    av_log(avctx, AV_LOG_ERROR,
                           "Frame reference does not exist\n");
                    break;
                }
                memcpy(out + 2 * outcnt, prev + 2 * start, 2 * count);
            } else {
                // copy from earlier in this frame
                int offset = (code & 0x1FFF) + 1;
                if (!(code & 0x6000)) {
                    count = 2;
                } else if ((code & 0x6000) == 0x2000) {
                    count = 3;
                } else {
                    if (buf_end - 1 < buf)
                        break;
                    count = 4 + *buf++;
                }
                if (outcnt < offset || maxcnt - outcnt < count)
                    break;
                av_memcpy_backptr(out + 2 * outcnt, 2 * offset, 2 * count);
            }
            outcnt += count;
        }
    }
    if (outcnt - maxcnt)
        av_log(avctx, AV_LOG_DEBUG, "frame finished with %d diff\n", outcnt - maxcnt);
    av_image_copy_plane(frame->data[0], frame->linesize[0],
                        (const uint8_t*)c->frame_buffer,  avctx->width * 2,
                        avctx->width * 2, avctx->height);
    FFSWAP(uint16_t *, c->frame_buffer, c->last_frame_buffer);
    *got_frame = 1;
    return avpkt->size;
}

void clamp_mv(VP8Context *s, VP56mv *dst, const VP56mv *src)

{

    dst->x = av_clip(src->x, s->mv_min.x, s->mv_max.x);

    dst->y = av_clip(src->y, s->mv_min.y, s->mv_max.y);

}

AVFilterBufferRef *avfilter_default_get_audio_buffer(AVFilterLink *link, int perms,

                                                     int nb_samples)

{

    AVFilterBufferRef *samplesref = NULL;

    int linesize[8];

    uint8_t *data[8];

    int nb_channels = av_get_channel_layout_nb_channels(link->channel_layout);



    /* Calculate total buffer size, round to multiple of 16 to be SIMD friendly */

    if (av_samples_alloc(data, linesize,

                         nb_channels, nb_samples, link->format,

                         16) < 0)

        return NULL;



    samplesref =

        avfilter_get_audio_buffer_ref_from_arrays(data, linesize, perms,

                                                  nb_samples, link->format,

                                                  link->channel_layout, link->planar);

    if (!samplesref) {

        av_free(data[0]);

        return NULL;

    }



    return samplesref;

}

static int aic_decode_coeffs(GetBitContext *gb, int16_t *dst,

                             int band, int slice_width)

{

    int has_skips, coeff_type, coeff_bits, skip_type, skip_bits;

    const int num_coeffs = aic_num_band_coeffs[band];

    const uint8_t *scan = aic_scan[band];

    int mb, idx, val;



    has_skips  = get_bits1(gb);

    coeff_type = get_bits1(gb);

    coeff_bits = get_bits(gb, 3);



    if (has_skips) {

        skip_type = get_bits1(gb);

        skip_bits = get_bits(gb, 3);



        for (mb = 0; mb < slice_width; mb++) {

            idx = -1;

            do {

                GET_CODE(val, skip_type, skip_bits);

                idx += val + 1;

                if (idx >= num_coeffs)

                    break;

                GET_CODE(val, coeff_type, coeff_bits);

                val++;

                if (val >= 0x10000)

                    return AVERROR_INVALIDDATA;

                dst[scan[idx]] = val;

            } while (idx < num_coeffs - 1);

            dst += num_coeffs;

        }

    } else {

        for (mb = 0; mb < slice_width; mb++) {

            for (idx = 0; idx < num_coeffs; idx++) {

                GET_CODE(val, coeff_type, coeff_bits);

                if (val >= 0x10000)

                    return AVERROR_INVALIDDATA;

                dst[scan[idx]] = val;

            }

            dst += num_coeffs;

        }

    }

    return 0;

}

static int sdp_probe(AVProbeData *p1)

{

    const char *p = p1->buf, *p_end = p1->buf + p1->buf_size;



    /* we look for a line beginning "c=IN IP4" */

    while (p < p_end && *p != '\0') {

        if (p + sizeof("c=IN IP4") - 1 < p_end && av_strstart(p, "c=IN IP4", NULL))

            return AVPROBE_SCORE_MAX / 2;



        while(p < p_end - 1 && *p != '\n') p++;

        if (++p >= p_end)

            break;

        if (*p == '\r')

            p++;

    }

    return 0;

}

void decode_mvs(VP8Context *s, VP8Macroblock *mb, int mb_x, int mb_y)

{

    VP8Macroblock *mb_edge[3] = { mb + 2 /* top */,

                                  mb - 1 /* left */,

                                  mb + 1 /* top-left */ };

    enum { CNT_ZERO, CNT_NEAREST, CNT_NEAR, CNT_SPLITMV };

    enum { EDGE_TOP, EDGE_LEFT, EDGE_TOPLEFT };

    int idx = CNT_ZERO;

    int cur_sign_bias = s->sign_bias[mb->ref_frame];

    int *sign_bias = s->sign_bias;

    VP56mv near_mv[4];

    uint8_t cnt[4] = { 0 };

    VP56RangeCoder *c = &s->c;



    AV_ZERO32(&near_mv[0]);

    AV_ZERO32(&near_mv[1]);

    AV_ZERO32(&near_mv[2]);



    /* Process MB on top, left and top-left */

    #define MV_EDGE_CHECK(n)\

    {\

        VP8Macroblock *edge = mb_edge[n];\

        int edge_ref = edge->ref_frame;\

        if (edge_ref != VP56_FRAME_CURRENT) {\

            uint32_t mv = AV_RN32A(&edge->mv);\

            if (mv) {\

                if (cur_sign_bias != sign_bias[edge_ref]) {\

                    /* SWAR negate of the values in mv. */\

                    mv = ~mv;\

                    mv = ((mv&0x7fff7fff) + 0x00010001) ^ (mv&0x80008000);\

                }\

                if (!n || mv != AV_RN32A(&near_mv[idx]))\

                    AV_WN32A(&near_mv[++idx], mv);\

                cnt[idx]      += 1 + (n != 2);\

            } else\

                cnt[CNT_ZERO] += 1 + (n != 2);\

        }\

    }



    MV_EDGE_CHECK(0)

    MV_EDGE_CHECK(1)

    MV_EDGE_CHECK(2)



    mb->partitioning = VP8_SPLITMVMODE_NONE;

    if (vp56_rac_get_prob_branchy(c, vp8_mode_contexts[cnt[CNT_ZERO]][0])) {

        mb->mode = VP8_MVMODE_MV;



        /* If we have three distinct MVs, merge first and last if they're the same */

        if (cnt[CNT_SPLITMV] && AV_RN32A(&near_mv[1+EDGE_TOP]) == AV_RN32A(&near_mv[1+EDGE_TOPLEFT]))

            cnt[CNT_NEAREST] += 1;



        /* Swap near and nearest if necessary */

        if (cnt[CNT_NEAR] > cnt[CNT_NEAREST]) {

            FFSWAP(uint8_t,     cnt[CNT_NEAREST],     cnt[CNT_NEAR]);

            FFSWAP( VP56mv, near_mv[CNT_NEAREST], near_mv[CNT_NEAR]);

        }



        if (vp56_rac_get_prob_branchy(c, vp8_mode_contexts[cnt[CNT_NEAREST]][1])) {

            if (vp56_rac_get_prob_branchy(c, vp8_mode_contexts[cnt[CNT_NEAR]][2])) {



                /* Choose the best mv out of 0,0 and the nearest mv */

                clamp_mv(s, &mb->mv, &near_mv[CNT_ZERO + (cnt[CNT_NEAREST] >= cnt[CNT_ZERO])]);

                cnt[CNT_SPLITMV] = ((mb_edge[EDGE_LEFT]->mode    == VP8_MVMODE_SPLIT) +

                                    (mb_edge[EDGE_TOP]->mode     == VP8_MVMODE_SPLIT)) * 2 +

                                    (mb_edge[EDGE_TOPLEFT]->mode == VP8_MVMODE_SPLIT);



                if (vp56_rac_get_prob_branchy(c, vp8_mode_contexts[cnt[CNT_SPLITMV]][3])) {

                    mb->mode = VP8_MVMODE_SPLIT;

                    mb->mv = mb->bmv[decode_splitmvs(s, c, mb) - 1];

                } else {

                    mb->mv.y += read_mv_component(c, s->prob->mvc[0]);

                    mb->mv.x += read_mv_component(c, s->prob->mvc[1]);

                    mb->bmv[0] = mb->mv;

                }

            } else {

                clamp_mv(s, &mb->mv, &near_mv[CNT_NEAR]);

                mb->bmv[0] = mb->mv;

            }

        } else {

            clamp_mv(s, &mb->mv, &near_mv[CNT_NEAREST]);

            mb->bmv[0] = mb->mv;

        }

    } else {

        mb->mode = VP8_MVMODE_ZERO;

        AV_ZERO32(&mb->mv);

        mb->bmv[0] = mb->mv;

    }

}

int ff_h264_alloc_tables(H264Context *h){

    MpegEncContext * const s = &h->s;

    const int big_mb_num= s->mb_stride * (s->mb_height+1);

    int x,y;



    FF_ALLOCZ_OR_GOTO(h->s.avctx, h->intra4x4_pred_mode, big_mb_num * 8  * sizeof(uint8_t), fail)



    FF_ALLOCZ_OR_GOTO(h->s.avctx, h->non_zero_count    , big_mb_num * 16 * sizeof(uint8_t), fail)

    FF_ALLOCZ_OR_GOTO(h->s.avctx, h->slice_table_base  , (big_mb_num+s->mb_stride) * sizeof(*h->slice_table_base), fail)

    FF_ALLOCZ_OR_GOTO(h->s.avctx, h->cbp_table, big_mb_num * sizeof(uint16_t), fail)



    FF_ALLOCZ_OR_GOTO(h->s.avctx, h->chroma_pred_mode_table, big_mb_num * sizeof(uint8_t), fail)

    FF_ALLOCZ_OR_GOTO(h->s.avctx, h->mvd_table[0], 32*big_mb_num * sizeof(uint16_t), fail);

    FF_ALLOCZ_OR_GOTO(h->s.avctx, h->mvd_table[1], 32*big_mb_num * sizeof(uint16_t), fail);

    FF_ALLOCZ_OR_GOTO(h->s.avctx, h->direct_table, 32*big_mb_num * sizeof(uint8_t) , fail);



    memset(h->slice_table_base, -1, (big_mb_num+s->mb_stride)  * sizeof(*h->slice_table_base));

    h->slice_table= h->slice_table_base + s->mb_stride*2 + 1;



    FF_ALLOCZ_OR_GOTO(h->s.avctx, h->mb2b_xy  , big_mb_num * sizeof(uint32_t), fail);

    FF_ALLOCZ_OR_GOTO(h->s.avctx, h->mb2b8_xy , big_mb_num * sizeof(uint32_t), fail);

    for(y=0; y<s->mb_height; y++){

        for(x=0; x<s->mb_width; x++){

            const int mb_xy= x + y*s->mb_stride;

            const int b_xy = 4*x + 4*y*h->b_stride;

            const int b8_xy= 2*x + 2*y*h->b8_stride;



            h->mb2b_xy [mb_xy]= b_xy;

            h->mb2b8_xy[mb_xy]= b8_xy;

        }

    }



    s->obmc_scratchpad = NULL;



    if(!h->dequant4_coeff[0])

        init_dequant_tables(h);



    return 0;

fail:

    free_tables(h);

    return -1;

}

static int mxf_read_packet(AVFormatContext *s, AVPacket *pkt)

{

    KLVPacket klv;



    while (!s->pb->eof_reached) {

        if (klv_read_packet(&klv, s->pb) < 0)

            return -1;

        PRINT_KEY(s, "read packet", klv.key);

        av_dlog(s, "size %"PRIu64" offset %#"PRIx64"\n", klv.length, klv.offset);

        if (IS_KLV_KEY(klv.key, mxf_encrypted_triplet_key)) {

            int res = mxf_decrypt_triplet(s, pkt, &klv);

            if (res < 0) {

                av_log(s, AV_LOG_ERROR, "invalid encoded triplet\n");

                return -1;

            }

            return 0;

        }

        if (IS_KLV_KEY(klv.key, mxf_essence_element_key)) {

            int index = mxf_get_stream_index(s, &klv);

            if (index < 0) {

                av_log(s, AV_LOG_ERROR, "error getting stream index %d\n", AV_RB32(klv.key+12));

                goto skip;

            }

            if (s->streams[index]->discard == AVDISCARD_ALL)

                goto skip;

            /* check for 8 channels AES3 element */

            if (klv.key[12] == 0x06 && klv.key[13] == 0x01 && klv.key[14] == 0x10) {

                if (mxf_get_d10_aes3_packet(s->pb, s->streams[index], pkt, klv.length) < 0) {

                    av_log(s, AV_LOG_ERROR, "error reading D-10 aes3 frame\n");

                    return -1;

                }

            } else

                av_get_packet(s->pb, pkt, klv.length);

            pkt->stream_index = index;

            pkt->pos = klv.offset;

            return 0;

        } else

        skip:

            avio_skip(s->pb, klv.length);

    }

    return AVERROR_EOF;

}

void ff_ivi_recompose_haar(const IVIPlaneDesc *plane, uint8_t *dst,

                           const int dst_pitch, const int num_bands)

{

    int             x, y, indx, b0, b1, b2, b3, p0, p1, p2, p3;

    const IDWTELEM *b0_ptr, *b1_ptr, *b2_ptr, *b3_ptr;

    int32_t         pitch;



    /* all bands should have the same pitch */

    pitch = plane->bands[0].pitch;



    /* get pointers to the wavelet bands */

    b0_ptr = plane->bands[0].buf;

    b1_ptr = plane->bands[1].buf;

    b2_ptr = plane->bands[2].buf;

    b3_ptr = plane->bands[3].buf;



    for (y = 0; y < plane->height; y += 2) {

        for (x = 0, indx = 0; x < plane->width; x += 2, indx++) {

            /* load coefficients */

            b0 = b0_ptr[indx]; //should be: b0 = (num_bands > 0) ? b0_ptr[indx] : 0;

            b1 = b1_ptr[indx]; //should be: b1 = (num_bands > 1) ? b1_ptr[indx] : 0;

            b2 = b2_ptr[indx]; //should be: b2 = (num_bands > 2) ? b2_ptr[indx] : 0;

            b3 = b3_ptr[indx]; //should be: b3 = (num_bands > 3) ? b3_ptr[indx] : 0;



            /* haar wavelet recomposition */

            p0 = (b0 + b1 + b2 + b3 + 2) >> 2;

            p1 = (b0 + b1 - b2 - b3 + 2) >> 2;

            p2 = (b0 - b1 + b2 - b3 + 2) >> 2;

            p3 = (b0 - b1 - b2 + b3 + 2) >> 2;



            /* bias, convert and output four pixels */

            dst[x]                 = av_clip_uint8(p0 + 128);

            dst[x + 1]             = av_clip_uint8(p1 + 128);

            dst[dst_pitch + x]     = av_clip_uint8(p2 + 128);

            dst[dst_pitch + x + 1] = av_clip_uint8(p3 + 128);

        }// for x



        dst += dst_pitch << 1;



        b0_ptr += pitch;

        b1_ptr += pitch;

        b2_ptr += pitch;

        b3_ptr += pitch;

    }// for y

}

static int find_smallest_bounding_rectangle(AVSubtitle *s)

{

    uint8_t transp_color[256] = { 0 };

    int y1, y2, x1, x2, y, w, h, i;

    uint8_t *bitmap;



    if (s->num_rects == 0 || s->rects == NULL || s->rects[0]->w <= 0 || s->rects[0]->h <= 0)

        return 0;



    for(i = 0; i < s->rects[0]->nb_colors; i++) {

        if ((((uint32_t*)s->rects[0]->pict.data[1])[i] >> 24) == 0)

            transp_color[i] = 1;

    }

    y1 = 0;

    while (y1 < s->rects[0]->h && is_transp(s->rects[0]->pict.data[0] + y1 * s->rects[0]->pict.linesize[0],

                                  1, s->rects[0]->w, transp_color))

        y1++;

    if (y1 == s->rects[0]->h) {

        av_freep(&s->rects[0]->pict.data[0]);

        s->rects[0]->w = s->rects[0]->h = 0;

        return 0;

    }



    y2 = s->rects[0]->h - 1;

    while (y2 > 0 && is_transp(s->rects[0]->pict.data[0] + y2 * s->rects[0]->pict.linesize[0], 1,

                               s->rects[0]->w, transp_color))

        y2--;

    x1 = 0;

    while (x1 < (s->rects[0]->w - 1) && is_transp(s->rects[0]->pict.data[0] + x1, s->rects[0]->pict.linesize[0],

                                        s->rects[0]->h, transp_color))

        x1++;

    x2 = s->rects[0]->w - 1;

    while (x2 > 0 && is_transp(s->rects[0]->pict.data[0] + x2, s->rects[0]->pict.linesize[0], s->rects[0]->h,

                                  transp_color))

        x2--;

    w = x2 - x1 + 1;

    h = y2 - y1 + 1;

    bitmap = av_malloc(w * h);

    if (!bitmap)

        return 1;

    for(y = 0; y < h; y++) {

        memcpy(bitmap + w * y, s->rects[0]->pict.data[0] + x1 + (y1 + y) * s->rects[0]->pict.linesize[0], w);

    }

    av_freep(&s->rects[0]->pict.data[0]);

    s->rects[0]->pict.data[0] = bitmap;

    s->rects[0]->pict.linesize[0] = w;

    s->rects[0]->w = w;

    s->rects[0]->h = h;

    s->rects[0]->x += x1;

    s->rects[0]->y += y1;

    return 1;

}

static av_cold int allocate_buffers(AVCodecContext *avctx)

{

    int blk, ch;

    AC3EncodeContext *s = avctx->priv_data;

    int channels = s->channels + 1; /* includes coupling channel */



    FF_ALLOC_OR_GOTO(avctx, s->planar_samples, s->channels * sizeof(*s->planar_samples),

                     alloc_fail);

    for (ch = 0; ch < s->channels; ch++) {

        FF_ALLOCZ_OR_GOTO(avctx, s->planar_samples[ch],

                          (AC3_FRAME_SIZE+AC3_BLOCK_SIZE) * sizeof(**s->planar_samples),

                          alloc_fail);

    }

    FF_ALLOC_OR_GOTO(avctx, s->bap_buffer,  AC3_MAX_BLOCKS * channels *

                     AC3_MAX_COEFS * sizeof(*s->bap_buffer),  alloc_fail);

    FF_ALLOC_OR_GOTO(avctx, s->bap1_buffer, AC3_MAX_BLOCKS * channels *

                     AC3_MAX_COEFS * sizeof(*s->bap1_buffer), alloc_fail);

    FF_ALLOC_OR_GOTO(avctx, s->mdct_coef_buffer, AC3_MAX_BLOCKS * channels *

                     AC3_MAX_COEFS * sizeof(*s->mdct_coef_buffer), alloc_fail);

    FF_ALLOC_OR_GOTO(avctx, s->exp_buffer, AC3_MAX_BLOCKS * channels *

                     AC3_MAX_COEFS * sizeof(*s->exp_buffer), alloc_fail);

    FF_ALLOC_OR_GOTO(avctx, s->grouped_exp_buffer, AC3_MAX_BLOCKS * channels *

                     128 * sizeof(*s->grouped_exp_buffer), alloc_fail);

    FF_ALLOC_OR_GOTO(avctx, s->psd_buffer, AC3_MAX_BLOCKS * channels *

                     AC3_MAX_COEFS * sizeof(*s->psd_buffer), alloc_fail);

    FF_ALLOC_OR_GOTO(avctx, s->band_psd_buffer, AC3_MAX_BLOCKS * channels *

                     64 * sizeof(*s->band_psd_buffer), alloc_fail);

    FF_ALLOC_OR_GOTO(avctx, s->mask_buffer, AC3_MAX_BLOCKS * channels *

                     64 * sizeof(*s->mask_buffer), alloc_fail);

    FF_ALLOC_OR_GOTO(avctx, s->qmant_buffer, AC3_MAX_BLOCKS * channels *

                     AC3_MAX_COEFS * sizeof(*s->qmant_buffer), alloc_fail);

    if (s->cpl_enabled) {

        FF_ALLOC_OR_GOTO(avctx, s->cpl_coord_exp_buffer, AC3_MAX_BLOCKS * channels *

                         16 * sizeof(*s->cpl_coord_exp_buffer), alloc_fail);

        FF_ALLOC_OR_GOTO(avctx, s->cpl_coord_mant_buffer, AC3_MAX_BLOCKS * channels *

                         16 * sizeof(*s->cpl_coord_mant_buffer), alloc_fail);

    }

    for (blk = 0; blk < AC3_MAX_BLOCKS; blk++) {

        AC3Block *block = &s->blocks[blk];

        FF_ALLOC_OR_GOTO(avctx, block->bap, channels * sizeof(*block->bap),

                         alloc_fail);

        FF_ALLOCZ_OR_GOTO(avctx, block->mdct_coef, channels * sizeof(*block->mdct_coef),

                          alloc_fail);

        FF_ALLOCZ_OR_GOTO(avctx, block->exp, channels * sizeof(*block->exp),

                          alloc_fail);

        FF_ALLOCZ_OR_GOTO(avctx, block->grouped_exp, channels * sizeof(*block->grouped_exp),

                          alloc_fail);

        FF_ALLOCZ_OR_GOTO(avctx, block->psd, channels * sizeof(*block->psd),

                          alloc_fail);

        FF_ALLOCZ_OR_GOTO(avctx, block->band_psd, channels * sizeof(*block->band_psd),

                          alloc_fail);

        FF_ALLOCZ_OR_GOTO(avctx, block->mask, channels * sizeof(*block->mask),

                          alloc_fail);

        FF_ALLOCZ_OR_GOTO(avctx, block->qmant, channels * sizeof(*block->qmant),

                          alloc_fail);

        if (s->cpl_enabled) {

            FF_ALLOCZ_OR_GOTO(avctx, block->cpl_coord_exp, channels * sizeof(*block->cpl_coord_exp),

                              alloc_fail);

            FF_ALLOCZ_OR_GOTO(avctx, block->cpl_coord_mant, channels * sizeof(*block->cpl_coord_mant),

                              alloc_fail);

        }



        for (ch = 0; ch < channels; ch++) {

            /* arrangement: block, channel, coeff */

            block->bap[ch]         = &s->bap_buffer        [AC3_MAX_COEFS * (blk * channels + ch)];

            block->grouped_exp[ch] = &s->grouped_exp_buffer[128           * (blk * channels + ch)];

            block->psd[ch]         = &s->psd_buffer        [AC3_MAX_COEFS * (blk * channels + ch)];

            block->band_psd[ch]    = &s->band_psd_buffer   [64            * (blk * channels + ch)];

            block->mask[ch]        = &s->mask_buffer       [64            * (blk * channels + ch)];

            block->qmant[ch]       = &s->qmant_buffer      [AC3_MAX_COEFS * (blk * channels + ch)];

            if (s->cpl_enabled) {

                block->cpl_coord_exp[ch]  = &s->cpl_coord_exp_buffer [16  * (blk * channels + ch)];

                block->cpl_coord_mant[ch] = &s->cpl_coord_mant_buffer[16  * (blk * channels + ch)];

            }



            /* arrangement: channel, block, coeff */

            block->exp[ch]         = &s->exp_buffer        [AC3_MAX_COEFS * (AC3_MAX_BLOCKS * ch + blk)];

            block->mdct_coef[ch]   = &s->mdct_coef_buffer  [AC3_MAX_COEFS * (AC3_MAX_BLOCKS * ch + blk)];

        }

    }



    if (CONFIG_AC3ENC_FLOAT) {

        FF_ALLOC_OR_GOTO(avctx, s->fixed_coef_buffer, AC3_MAX_BLOCKS * channels *

                         AC3_MAX_COEFS * sizeof(*s->fixed_coef_buffer), alloc_fail);

        for (blk = 0; blk < AC3_MAX_BLOCKS; blk++) {

            AC3Block *block = &s->blocks[blk];

            FF_ALLOCZ_OR_GOTO(avctx, block->fixed_coef, channels *

                              sizeof(*block->fixed_coef), alloc_fail);

            for (ch = 0; ch < channels; ch++)

                block->fixed_coef[ch] = &s->fixed_coef_buffer[AC3_MAX_COEFS * (AC3_MAX_BLOCKS * ch + blk)];

        }

    } else {

        for (blk = 0; blk < AC3_MAX_BLOCKS; blk++) {

            AC3Block *block = &s->blocks[blk];

            FF_ALLOCZ_OR_GOTO(avctx, block->fixed_coef, channels *

                              sizeof(*block->fixed_coef), alloc_fail);

            for (ch = 0; ch < channels; ch++)

                block->fixed_coef[ch] = (int32_t *)block->mdct_coef[ch];

        }

    }



    return 0;

alloc_fail:

    return AVERROR(ENOMEM);

}

static void build_file_streams(void)

{

    FFServerStream *stream, *stream_next;

    int i, ret;



    /* gather all streams */

    for(stream = config.first_stream; stream; stream = stream_next) {

        AVFormatContext *infile = NULL;

        stream_next = stream->next;

        if (stream->stream_type == STREAM_TYPE_LIVE &&

            !stream->feed) {

            /* the stream comes from a file */

            /* try to open the file */

            /* open stream */

            if (stream->fmt && !strcmp(stream->fmt->name, "rtp")) {

                /* specific case : if transport stream output to RTP,

                   we use a raw transport stream reader */

                av_dict_set(&stream->in_opts, "mpeg2ts_compute_pcr", "1", 0);

            }



            if (!stream->feed_filename[0]) {

                http_log("Unspecified feed file for stream '%s'\n",

                         stream->filename);

                goto fail;

            }



            http_log("Opening feed file '%s' for stream '%s'\n",

                     stream->feed_filename, stream->filename);

            if ((ret = avformat_open_input(&infile, stream->feed_filename, stream->ifmt, &stream->in_opts)) < 0) {

                http_log("Could not open '%s': %s\n", stream->feed_filename,

                         av_err2str(ret));

                /* remove stream (no need to spend more time on it) */

            fail:

                remove_stream(stream);

            } else {

                /* find all the AVStreams inside and reference them in

                   'stream' */

                if (avformat_find_stream_info(infile, NULL) < 0) {

                    http_log("Could not find codec parameters from '%s'\n",

                             stream->feed_filename);

                    avformat_close_input(&infile);

                    goto fail;

                }

                extract_mpeg4_header(infile);



                for(i=0;i<infile->nb_streams;i++)

                    add_av_stream1(stream, infile->streams[i]->codec, 1);



                avformat_close_input(&infile);

            }

        }

    }

}

int av_interleaved_write_frame(AVFormatContext *s, AVPacket *pkt)
{
    int ret, flush = 0;
    if (pkt) {
        AVStream *st = s->streams[pkt->stream_index];
        //FIXME/XXX/HACK drop zero sized packets
        if (st->codec->codec_type == AVMEDIA_TYPE_AUDIO && pkt->size == 0)
            return 0;
        av_dlog(s, "av_interleaved_write_frame size:%d dts:%" PRId64 " pts:%" PRId64 "\n",
                pkt->size, pkt->dts, pkt->pts);
        if ((ret = compute_pkt_fields2(s, st, pkt)) < 0 && !(s->oformat->flags & AVFMT_NOTIMESTAMPS))
        if (pkt->dts == AV_NOPTS_VALUE && !(s->oformat->flags & AVFMT_NOTIMESTAMPS))
            return AVERROR(EINVAL);
    } else {
        av_dlog(s, "av_interleaved_write_frame FLUSH\n");
        flush = 1;
    }
    for (;; ) {
        AVPacket opkt;
        int ret = interleave_packet(s, &opkt, pkt, flush);
        if (ret <= 0) //FIXME cleanup needed for ret<0 ?
        ret = write_packet(s, &opkt);
        if (ret >= 0)
            s->streams[opkt.stream_index]->nb_frames++;
        av_free_packet(&opkt);
        pkt = NULL;
    }
}

static void unref_buffer(InputStream *ist, FrameBuffer *buf)

{

    av_assert0(buf->refcount);

    buf->refcount--;

    if (!buf->refcount) {

        buf->next = ist->buffer_pool;

        ist->buffer_pool = buf;

    }

}

static void loop_filter(const H264Context *h, H264SliceContext *sl, int start_x, int end_x)

{

    uint8_t *dest_y, *dest_cb, *dest_cr;

    int linesize, uvlinesize, mb_x, mb_y;

    const int end_mb_y       = sl->mb_y + FRAME_MBAFF(h);

    const int old_slice_type = sl->slice_type;

    const int pixel_shift    = h->pixel_shift;

    const int block_h        = 16 >> h->chroma_y_shift;



    if (h->postpone_filter)

        return;



    if (sl->deblocking_filter) {

        for (mb_x = start_x; mb_x < end_x; mb_x++)

            for (mb_y = end_mb_y - FRAME_MBAFF(h); mb_y <= end_mb_y; mb_y++) {

                int mb_xy, mb_type;

                mb_xy         = sl->mb_xy = mb_x + mb_y * h->mb_stride;

                sl->slice_num = h->slice_table[mb_xy];

                mb_type       = h->cur_pic.mb_type[mb_xy];

                sl->list_count = h->list_counts[mb_xy];



                if (FRAME_MBAFF(h))

                    sl->mb_mbaff               =

                    sl->mb_field_decoding_flag = !!IS_INTERLACED(mb_type);



                sl->mb_x = mb_x;

                sl->mb_y = mb_y;

                dest_y  = h->cur_pic.f->data[0] +

                          ((mb_x << pixel_shift) + mb_y * sl->linesize) * 16;

                dest_cb = h->cur_pic.f->data[1] +

                          (mb_x << pixel_shift) * (8 << CHROMA444(h)) +

                          mb_y * sl->uvlinesize * block_h;

                dest_cr = h->cur_pic.f->data[2] +

                          (mb_x << pixel_shift) * (8 << CHROMA444(h)) +

                          mb_y * sl->uvlinesize * block_h;

                // FIXME simplify above



                if (MB_FIELD(sl)) {

                    linesize   = sl->mb_linesize   = sl->linesize   * 2;

                    uvlinesize = sl->mb_uvlinesize = sl->uvlinesize * 2;

                    if (mb_y & 1) { // FIXME move out of this function?

                        dest_y  -= sl->linesize   * 15;

                        dest_cb -= sl->uvlinesize * (block_h - 1);

                        dest_cr -= sl->uvlinesize * (block_h - 1);

                    }

                } else {

                    linesize   = sl->mb_linesize   = sl->linesize;

                    uvlinesize = sl->mb_uvlinesize = sl->uvlinesize;

                }

                backup_mb_border(h, sl, dest_y, dest_cb, dest_cr, linesize,

                                 uvlinesize, 0);

                if (fill_filter_caches(h, sl, mb_type))

                    continue;

                sl->chroma_qp[0] = get_chroma_qp(h, 0, h->cur_pic.qscale_table[mb_xy]);

                sl->chroma_qp[1] = get_chroma_qp(h, 1, h->cur_pic.qscale_table[mb_xy]);



                if (FRAME_MBAFF(h)) {

                    ff_h264_filter_mb(h, sl, mb_x, mb_y, dest_y, dest_cb, dest_cr,

                                      linesize, uvlinesize);

                } else {

                    ff_h264_filter_mb_fast(h, sl, mb_x, mb_y, dest_y, dest_cb,

                                           dest_cr, linesize, uvlinesize);

                }

            }

    }

    sl->slice_type  = old_slice_type;

    sl->mb_x         = end_x;

    sl->mb_y         = end_mb_y - FRAME_MBAFF(h);

    sl->chroma_qp[0] = get_chroma_qp(h, 0, sl->qscale);

    sl->chroma_qp[1] = get_chroma_qp(h, 1, sl->qscale);

}

static av_cold int flashsv_decode_init(AVCodecContext *avctx)

{

    FlashSVContext *s = avctx->priv_data;

    int zret; // Zlib return code



    s->avctx          = avctx;

    s->zstream.zalloc = Z_NULL;

    s->zstream.zfree  = Z_NULL;

    s->zstream.opaque = Z_NULL;

    zret = inflateInit(&s->zstream);

    if (zret != Z_OK) {

        av_log(avctx, AV_LOG_ERROR, "Inflate init error: %d\n", zret);

        return 1;

    }

    avctx->pix_fmt = AV_PIX_FMT_BGR24;

    s->frame.data[0] = NULL;



    return 0;

}

static int mov_write_trak_tag(AVIOContext *pb, MOVMuxContext *mov,

                              MOVTrack *track, AVStream *st)

{

    int64_t pos = avio_tell(pb);

    avio_wb32(pb, 0); /* size */

    ffio_wfourcc(pb, "trak");

    mov_write_tkhd_tag(pb, mov, track, st);

    if (track->mode == MODE_PSP || track->flags & MOV_TRACK_CTTS ||

        (track->entry && track->cluster[0].dts) ||

        is_clcp_track(track)) {

        if (mov->use_editlist)

            mov_write_edts_tag(pb, mov, track);  // PSP Movies require edts box

        else if ((track->entry && track->cluster[0].dts) || track->mode == MODE_PSP || is_clcp_track(track))

            av_log(mov->fc, AV_LOG_WARNING,

                   "Not writing any edit list even though one would have been required\n");

    }

    if (track->tref_tag)

        mov_write_tref_tag(pb, track);

    mov_write_mdia_tag(pb, mov, track);

    if (track->mode == MODE_PSP)

        mov_write_uuid_tag_psp(pb, track); // PSP Movies require this uuid box

    if (track->tag == MKTAG('r','t','p',' '))

        mov_write_udta_sdp(pb, track);

    if (track->mode == MODE_MOV) {

        if (track->enc->codec_type == AVMEDIA_TYPE_VIDEO) {

            double sample_aspect_ratio = av_q2d(st->sample_aspect_ratio);

            if ((0.0 != sample_aspect_ratio && 1.0 != sample_aspect_ratio)) {

                mov_write_tapt_tag(pb, track);

            }

        }

        if (is_clcp_track(track)) {

            mov_write_tapt_tag(pb, track);

        }

    }

    mov_write_track_udta_tag(pb, mov, st);

    return update_size(pb, pos);

}

static void derive_spatial_merge_candidates(HEVCContext *s, int x0, int y0,

                                            int nPbW, int nPbH,

                                            int log2_cb_size,

                                            int singleMCLFlag, int part_idx,

                                            int merge_idx,

                                            struct MvField mergecandlist[])

{

    HEVCLocalContext *lc   = &s->HEVClc;

    RefPicList *refPicList = s->ref->refPicList;

    MvField *tab_mvf       = s->ref->tab_mvf;



    const int min_pu_width = s->sps->min_pu_width;



    const int cand_bottom_left = lc->na.cand_bottom_left;

    const int cand_left        = lc->na.cand_left;

    const int cand_up_left     = lc->na.cand_up_left;

    const int cand_up          = lc->na.cand_up;

    const int cand_up_right    = lc->na.cand_up_right_sap;



    const int xA1    = x0 - 1;

    const int yA1    = y0 + nPbH - 1;

    const int xA1_pu = xA1 >> s->sps->log2_min_pu_size;

    const int yA1_pu = yA1 >> s->sps->log2_min_pu_size;



    const int xB1    = x0 + nPbW - 1;

    const int yB1    = y0 - 1;

    const int xB1_pu = xB1 >> s->sps->log2_min_pu_size;

    const int yB1_pu = yB1 >> s->sps->log2_min_pu_size;



    const int xB0    = x0 + nPbW;

    const int yB0    = y0 - 1;

    const int xB0_pu = xB0 >> s->sps->log2_min_pu_size;

    const int yB0_pu = yB0 >> s->sps->log2_min_pu_size;



    const int xA0    = x0 - 1;

    const int yA0    = y0 + nPbH;

    const int xA0_pu = xA0 >> s->sps->log2_min_pu_size;

    const int yA0_pu = yA0 >> s->sps->log2_min_pu_size;



    const int xB2    = x0 - 1;

    const int yB2    = y0 - 1;

    const int xB2_pu = xB2 >> s->sps->log2_min_pu_size;

    const int yB2_pu = yB2 >> s->sps->log2_min_pu_size;



    const int nb_refs = (s->sh.slice_type == P_SLICE) ?

                        s->sh.nb_refs[0] : FFMIN(s->sh.nb_refs[0], s->sh.nb_refs[1]);

    int check_MER   = 1;

    int check_MER_1 = 1;



    int zero_idx = 0;



    int nb_merge_cand = 0;

    int nb_orig_merge_cand = 0;



    int is_available_a0;

    int is_available_a1;

    int is_available_b0;

    int is_available_b1;

    int is_available_b2;

    int check_B0;

    int check_A0;



    //first left spatial merge candidate

    is_available_a1 = AVAILABLE(cand_left, A1);



    if (!singleMCLFlag && part_idx == 1 &&

        (lc->cu.part_mode == PART_Nx2N ||

         lc->cu.part_mode == PART_nLx2N ||

         lc->cu.part_mode == PART_nRx2N) ||

        isDiffMER(s, xA1, yA1, x0, y0)) {

        is_available_a1 = 0;

    }



    if (is_available_a1) {

        mergecandlist[0] = TAB_MVF_PU(A1);

        if (merge_idx == 0)

            return;

        nb_merge_cand++;

    }



    // above spatial merge candidate

    is_available_b1 = AVAILABLE(cand_up, B1);



    if (!singleMCLFlag && part_idx == 1 &&

        (lc->cu.part_mode == PART_2NxN ||

         lc->cu.part_mode == PART_2NxnU ||

         lc->cu.part_mode == PART_2NxnD) ||

        isDiffMER(s, xB1, yB1, x0, y0)) {

        is_available_b1 = 0;

    }



    if (is_available_a1 && is_available_b1)

        check_MER = !COMPARE_MV_REFIDX(B1, A1);



    if (is_available_b1 && check_MER)

        mergecandlist[nb_merge_cand++] = TAB_MVF_PU(B1);



    // above right spatial merge candidate

    check_MER = 1;

    check_B0  = PRED_BLOCK_AVAILABLE(B0);



    is_available_b0 = check_B0 && AVAILABLE(cand_up_right, B0);



    if (isDiffMER(s, xB0, yB0, x0, y0))

        is_available_b0 = 0;



    if (is_available_b1 && is_available_b0)

        check_MER = !COMPARE_MV_REFIDX(B0, B1);



    if (is_available_b0 && check_MER) {

        mergecandlist[nb_merge_cand] = TAB_MVF_PU(B0);

        if (merge_idx == nb_merge_cand)

            return;

        nb_merge_cand++;

    }



    // left bottom spatial merge candidate

    check_MER = 1;

    check_A0  = PRED_BLOCK_AVAILABLE(A0);



    is_available_a0 = check_A0 && AVAILABLE(cand_bottom_left, A0);



    if (isDiffMER(s, xA0, yA0, x0, y0))

        is_available_a0 = 0;



    if (is_available_a1 && is_available_a0)

        check_MER = !COMPARE_MV_REFIDX(A0, A1);



    if (is_available_a0 && check_MER) {

        mergecandlist[nb_merge_cand] = TAB_MVF_PU(A0);

        if (merge_idx == nb_merge_cand)

            return;

        nb_merge_cand++;

    }



    // above left spatial merge candidate

    check_MER = 1;



    is_available_b2 = AVAILABLE(cand_up_left, B2);



    if (isDiffMER(s, xB2, yB2, x0, y0))

        is_available_b2 = 0;



    if (is_available_a1 && is_available_b2)

        check_MER = !COMPARE_MV_REFIDX(B2, A1);



    if (is_available_b1 && is_available_b2)

        check_MER_1 = !COMPARE_MV_REFIDX(B2, B1);



    if (is_available_b2 && check_MER && check_MER_1 && nb_merge_cand != 4) {

        mergecandlist[nb_merge_cand] = TAB_MVF_PU(B2);

        if (merge_idx == nb_merge_cand)

            return;

        nb_merge_cand++;

    }



    // temporal motion vector candidate

    if (s->sh.slice_temporal_mvp_enabled_flag &&

        nb_merge_cand < s->sh.max_num_merge_cand) {

        Mv mv_l0_col, mv_l1_col;

        int available_l0 = temporal_luma_motion_vector(s, x0, y0, nPbW, nPbH,

                                                       0, &mv_l0_col, 0);

        int available_l1 = (s->sh.slice_type == B_SLICE) ?

                           temporal_luma_motion_vector(s, x0, y0, nPbW, nPbH,

                                                       0, &mv_l1_col, 1) : 0;



        if (available_l0 || available_l1) {

            mergecandlist[nb_merge_cand].is_intra     = 0;

            mergecandlist[nb_merge_cand].pred_flag[0] = available_l0;

            mergecandlist[nb_merge_cand].pred_flag[1] = available_l1;

            if (available_l0) {

                mergecandlist[nb_merge_cand].mv[0]      = mv_l0_col;

                mergecandlist[nb_merge_cand].ref_idx[0] = 0;

            }

            if (available_l1) {

                mergecandlist[nb_merge_cand].mv[1]      = mv_l1_col;

                mergecandlist[nb_merge_cand].ref_idx[1] = 0;

            }

            if (merge_idx == nb_merge_cand)

                return;

            nb_merge_cand++;

        }

    }



    nb_orig_merge_cand = nb_merge_cand;



    // combined bi-predictive merge candidates  (applies for B slices)

    if (s->sh.slice_type == B_SLICE && nb_orig_merge_cand > 1 &&

        nb_orig_merge_cand < s->sh.max_num_merge_cand) {

        int comb_idx;



        for (comb_idx = 0; nb_merge_cand < s->sh.max_num_merge_cand &&

                           comb_idx < nb_orig_merge_cand * (nb_orig_merge_cand - 1); comb_idx++) {

            int l0_cand_idx = l0_l1_cand_idx[comb_idx][0];

            int l1_cand_idx = l0_l1_cand_idx[comb_idx][1];

            MvField l0_cand = mergecandlist[l0_cand_idx];

            MvField l1_cand = mergecandlist[l1_cand_idx];



            if (l0_cand.pred_flag[0] && l1_cand.pred_flag[1] &&

                (refPicList[0].list[l0_cand.ref_idx[0]] !=

                 refPicList[1].list[l1_cand.ref_idx[1]] ||

                 AV_RN32A(&l0_cand.mv[0]) != AV_RN32A(&l1_cand.mv[1]))) {

                mergecandlist[nb_merge_cand].ref_idx[0]   = l0_cand.ref_idx[0];

                mergecandlist[nb_merge_cand].ref_idx[1]   = l1_cand.ref_idx[1];

                mergecandlist[nb_merge_cand].pred_flag[0] = 1;

                mergecandlist[nb_merge_cand].pred_flag[1] = 1;

                AV_COPY32(&mergecandlist[nb_merge_cand].mv[0], &l0_cand.mv[0]);

                AV_COPY32(&mergecandlist[nb_merge_cand].mv[1], &l1_cand.mv[1]);

                mergecandlist[nb_merge_cand].is_intra     = 0;

                if (merge_idx == nb_merge_cand)

                    return;

                nb_merge_cand++;

            }

        }

    }



    // append Zero motion vector candidates

    while (nb_merge_cand < s->sh.max_num_merge_cand) {

        mergecandlist[nb_merge_cand].pred_flag[0] = 1;

        mergecandlist[nb_merge_cand].pred_flag[1] = s->sh.slice_type == B_SLICE;

        AV_ZERO32(mergecandlist[nb_merge_cand].mv + 0);

        AV_ZERO32(mergecandlist[nb_merge_cand].mv + 1);

        mergecandlist[nb_merge_cand].is_intra     = 0;

        mergecandlist[nb_merge_cand].ref_idx[0]   = zero_idx < nb_refs ? zero_idx : 0;

        mergecandlist[nb_merge_cand].ref_idx[1]   = zero_idx < nb_refs ? zero_idx : 0;



        if (merge_idx == nb_merge_cand)

            return;

        nb_merge_cand++;

        zero_idx++;

    }

}

static void hl_decode_mb(H264Context *h){

    MpegEncContext * const s = &h->s;

    const int mb_xy= h->mb_xy;

    const int mb_type= s->current_picture.mb_type[mb_xy];

    int is_complex = h->is_complex || IS_INTRA_PCM(mb_type) || s->qscale == 0;



    if(ENABLE_H264_ENCODER && !s->decode)

        return;



    if (is_complex)

        hl_decode_mb_complex(h);

    else hl_decode_mb_simple(h);

}

