static void flush_buffer(ByteIOContext *s)

{

    if (s->buf_ptr > s->buffer) {

        if (s->write_packet)

            s->write_packet(s->opaque, s->buffer, s->buf_ptr - s->buffer);

        if(s->checksum_ptr){

            s->checksum= s->update_checksum(s->checksum, s->checksum_ptr, s->buf_ptr - s->checksum_ptr);

            s->checksum_ptr= s->buffer;

        }

        s->pos += s->buf_ptr - s->buffer;

    }

    s->buf_ptr = s->buffer;

}

static int daala_packet(AVFormatContext *s, int idx)

{

    int seg, duration = 1;

    struct ogg *ogg = s->priv_data;

    struct ogg_stream *os = ogg->streams + idx;



    /*

     * first packet handling: here we parse the duration of each packet in the

     * first page and compare the total duration to the page granule to find the

     * encoder delay and set the first timestamp

     */



    if ((!os->lastpts || os->lastpts == AV_NOPTS_VALUE) && !(os->flags & OGG_FLAG_EOS)) {

        for (seg = os->segp; seg < os->nsegs; seg++)

            if (os->segments[seg] < 255)

                duration++;



        os->lastpts = os->lastdts = daala_gptopts(s, idx, os->granule, NULL) - duration;

        if(s->streams[idx]->start_time == AV_NOPTS_VALUE) {

            s->streams[idx]->start_time = os->lastpts;

            if (s->streams[idx]->duration)

                s->streams[idx]->duration -= s->streams[idx]->start_time;

        }

    }



    /* parse packet duration */

    if (os->psize > 0)

        os->pduration = 1;



    return 0;

}

static int clv_decode_frame(AVCodecContext *avctx, void *data,

                            int *got_frame, AVPacket *avpkt)

{

    const uint8_t *buf = avpkt->data;

    int buf_size = avpkt->size;

    CLVContext *c = avctx->priv_data;

    GetByteContext gb;

    uint32_t frame_type;

    int i, j;

    int ret;

    int mb_ret = 0;



    bytestream2_init(&gb, buf, buf_size);

    if (avctx->codec_tag == MKTAG('C','L','V','1')) {

        int skip = bytestream2_get_byte(&gb);

        bytestream2_skip(&gb, (skip + 1) * 8);

    }



    frame_type = bytestream2_get_byte(&gb);

    if ((ret = ff_reget_buffer(avctx, c->pic)) < 0)

        return ret;



    c->pic->key_frame = frame_type & 0x20 ? 1 : 0;

    c->pic->pict_type = frame_type & 0x20 ? AV_PICTURE_TYPE_I : AV_PICTURE_TYPE_P;



    if (frame_type & 0x2) {

        if (buf_size < c->mb_width * c->mb_height) {

            av_log(avctx, AV_LOG_ERROR, "Packet too small\n");

            return AVERROR_INVALIDDATA;

        }



        bytestream2_get_be32(&gb); // frame size;

        c->ac_quant        = bytestream2_get_byte(&gb);

        c->luma_dc_quant   = 32;

        c->chroma_dc_quant = 32;



        if ((ret = init_get_bits8(&c->gb, buf + bytestream2_tell(&gb),

                                  (buf_size - bytestream2_tell(&gb)))) < 0)

            return ret;



        for (i = 0; i < 3; i++)

            c->top_dc[i] = 32;

        for (i = 0; i < 4; i++)

            c->left_dc[i] = 32;



        for (j = 0; j < c->mb_height; j++) {

            for (i = 0; i < c->mb_width; i++) {

                ret = decode_mb(c, i, j);

                if (ret < 0)

                    mb_ret = ret;

            }

        }

    } else {

    }



    if ((ret = av_frame_ref(data, c->pic)) < 0)

        return ret;



    *got_frame = 1;



    return mb_ret < 0 ? mb_ret : buf_size;

}

static int read_frame(BVID_DemuxContext *vid, AVIOContext *pb, AVPacket *pkt,

                      uint8_t block_type, AVFormatContext *s)

{

    uint8_t * vidbuf_start = NULL;

    int vidbuf_nbytes = 0;

    int code;

    int bytes_copied = 0;

    int position, duration, npixels;

    unsigned int vidbuf_capacity;

    int ret = 0;

    AVStream *st;



    if (vid->video_index < 0) {

        st = avformat_new_stream(s, NULL);

        if (!st)

            return AVERROR(ENOMEM);

        vid->video_index = st->index;

        if (vid->audio_index < 0) {

            av_log_ask_for_sample(s, "No audio packet before first video "

                                  "packet. Using default video time base.\n");

        }

        avpriv_set_pts_info(st, 64, 185, vid->sample_rate);

        st->codec->codec_type = AVMEDIA_TYPE_VIDEO;

        st->codec->codec_id   = AV_CODEC_ID_BETHSOFTVID;

        st->codec->width      = vid->width;

        st->codec->height     = vid->height;

    }

    st      = s->streams[vid->video_index];

    npixels = st->codec->width * st->codec->height;



    vidbuf_start = av_malloc(vidbuf_capacity = BUFFER_PADDING_SIZE);

    if(!vidbuf_start)

        return AVERROR(ENOMEM);



    // save the file position for the packet, include block type

    position = avio_tell(pb) - 1;



    vidbuf_start[vidbuf_nbytes++] = block_type;



    // get the current packet duration

    duration = vid->bethsoft_global_delay + avio_rl16(pb);



    // set the y offset if it exists (decoder header data should be in data section)

    if(block_type == VIDEO_YOFF_P_FRAME){

        if (avio_read(pb, &vidbuf_start[vidbuf_nbytes], 2) != 2) {

            ret = AVERROR(EIO);

            goto fail;

        }

        vidbuf_nbytes += 2;

    }



    do{

        vidbuf_start = av_fast_realloc(vidbuf_start, &vidbuf_capacity, vidbuf_nbytes + BUFFER_PADDING_SIZE);

        if(!vidbuf_start)

            return AVERROR(ENOMEM);



        code = avio_r8(pb);

        vidbuf_start[vidbuf_nbytes++] = code;



        if(code >= 0x80){ // rle sequence

            if(block_type == VIDEO_I_FRAME)

                vidbuf_start[vidbuf_nbytes++] = avio_r8(pb);

        } else if(code){ // plain sequence

            if (avio_read(pb, &vidbuf_start[vidbuf_nbytes], code) != code) {

                ret = AVERROR(EIO);

                goto fail;

            }

            vidbuf_nbytes += code;

        }

        bytes_copied += code & 0x7F;

        if(bytes_copied == npixels){ // sometimes no stop character is given, need to keep track of bytes copied

            // may contain a 0 byte even if read all pixels

            if(avio_r8(pb))

                avio_seek(pb, -1, SEEK_CUR);

            break;

        }

        if (bytes_copied > npixels) {

            ret = AVERROR_INVALIDDATA;

            goto fail;

        }

    } while(code);



    // copy data into packet

    if ((ret = av_new_packet(pkt, vidbuf_nbytes)) < 0)

        goto fail;

    memcpy(pkt->data, vidbuf_start, vidbuf_nbytes);

    av_free(vidbuf_start);



    pkt->pos = position;

    pkt->stream_index = vid->video_index;

    pkt->duration = duration;

    if (block_type == VIDEO_I_FRAME)

        pkt->flags |= AV_PKT_FLAG_KEY;



    /* if there is a new palette available, add it to packet side data */

    if (vid->palette) {

        uint8_t *pdata = av_packet_new_side_data(pkt, AV_PKT_DATA_PALETTE,

                                                 BVID_PALETTE_SIZE);

        memcpy(pdata, vid->palette, BVID_PALETTE_SIZE);

        av_freep(&vid->palette);

    }



    vid->nframes--;  // used to check if all the frames were read

    return 0;

fail:

    av_free(vidbuf_start);

    return ret;

}

static int nvdec_vp8_start_frame(AVCodecContext *avctx, const uint8_t *buffer, uint32_t size)

{

    VP8Context *h = avctx->priv_data;



    NVDECContext      *ctx = avctx->internal->hwaccel_priv_data;

    CUVIDPICPARAMS     *pp = &ctx->pic_params;

    FrameDecodeData *fdd;

    NVDECFrame *cf;

    AVFrame *cur_frame = h->framep[VP56_FRAME_CURRENT]->tf.f;



    int ret;



    ret = ff_nvdec_start_frame(avctx, cur_frame);

    if (ret < 0)

        return ret;



    fdd = (FrameDecodeData*)cur_frame->private_ref->data;

    cf  = (NVDECFrame*)fdd->hwaccel_priv;



    *pp = (CUVIDPICPARAMS) {

        .PicWidthInMbs     = (cur_frame->width  + 15) / 16,

        .FrameHeightInMbs  = (cur_frame->height + 15) / 16,

        .CurrPicIdx        = cf->idx,



        .CodecSpecific.vp8 = {

            .width                       = cur_frame->width,

            .height                      = cur_frame->height,



            .first_partition_size        = h->header_partition_size,



            .LastRefIdx                  = safe_get_ref_idx(h->framep[VP56_FRAME_PREVIOUS]),

            .GoldenRefIdx                = safe_get_ref_idx(h->framep[VP56_FRAME_GOLDEN]),

            .AltRefIdx                   = safe_get_ref_idx(h->framep[VP56_FRAME_GOLDEN2]),



            .frame_type                  = !h->keyframe,

            .version                     = h->profile,

            .show_frame                  = !h->invisible,

            .update_mb_segmentation_data = h->segmentation.enabled ? h->segmentation.update_feature_data : 0,

       }

    };



    return 0;

}

int msmpeg4_decode_mb(MpegEncContext *s, 

                      DCTELEM block[6][64])

{

    int cbp, code, i;

    int pred, val;

    UINT8 *coded_val;



    /* special slice handling */

    if (s->mb_x == 0) {

        if ((s->mb_y % s->slice_height) == 0) {

            int wrap;

            /* reset DC pred (set previous line to 1024) */

            wrap = 2 * s->mb_width + 2;

            memsetw(&s->dc_val[0][(1) + (2 * s->mb_y) * wrap], 

                    1024, 2 * s->mb_width);

            wrap = s->mb_width + 2;

            memsetw(&s->dc_val[1][(1) + (s->mb_y) * wrap], 

                    1024, s->mb_width);

            memsetw(&s->dc_val[2][(1) + (s->mb_y) * wrap], 

                    1024, s->mb_width);



            s->first_slice_line = 1;

        } else {

            s->first_slice_line = 0; 

        }

    }



    if (s->pict_type == P_TYPE) {

        set_stat(ST_INTER_MB);

        if (s->use_skip_mb_code) {

            if (get_bits1(&s->gb)) {

                /* skip mb */

                s->mb_intra = 0;

                for(i=0;i<6;i++)

                    s->block_last_index[i] = -1;

                s->mv_dir = MV_DIR_FORWARD;

                s->mv_type = MV_TYPE_16X16;

                s->mv[0][0][0] = 0;

                s->mv[0][0][1] = 0;

                s->mb_skiped = 1;

                return 0;

            }

        }



        code = get_vlc(&s->gb, &mb_non_intra_vlc);

        if (code < 0)

            return -1;

        if (code & 0x40)

            s->mb_intra = 0;

        else

            s->mb_intra = 1;



        cbp = code & 0x3f;

    } else {

        set_stat(ST_INTRA_MB);

        s->mb_intra = 1;

        code = get_vlc(&s->gb, &mb_intra_vlc);

        if (code < 0)

            return -1;

        /* predict coded block pattern */

        cbp = 0;

        for(i=0;i<6;i++) {

            val = ((code >> (5 - i)) & 1);

            if (i < 4) {

                pred = coded_block_pred(s, i, &coded_val);

                val = val ^ pred;

                *coded_val = val;

            }

            cbp |= val << (5 - i);

        }

    }



    if (!s->mb_intra) {

        int mx, my;

        set_stat(ST_MV);

        h263_pred_motion(s, 0, &mx, &my);

        if (msmpeg4_decode_motion(s, &mx, &my) < 0)

            return -1;

        s->mv_dir = MV_DIR_FORWARD;

        s->mv_type = MV_TYPE_16X16;

        s->mv[0][0][0] = mx;

        s->mv[0][0][1] = my;

    } else {

        set_stat(ST_INTRA_MB);

        s->ac_pred = get_bits1(&s->gb);

    }



    for (i = 0; i < 6; i++) {

        if (msmpeg4_decode_block(s, block[i], i, (cbp >> (5 - i)) & 1) < 0)

            return -1;

    }

    return 0;

}

static int matroska_parse_block(MatroskaDemuxContext *matroska, uint8_t *data,

                                int size, int64_t pos, uint64_t cluster_time,

                                uint64_t duration, int is_keyframe,

                                int64_t cluster_pos)

{

    uint64_t timecode = AV_NOPTS_VALUE;

    MatroskaTrack *track;

    int res = 0;

    AVStream *st;

    AVPacket *pkt;

    int16_t block_time;

    uint32_t *lace_size = NULL;

    int n, flags, laces = 0;

    uint64_t num;



    if ((n = matroska_ebmlnum_uint(matroska, data, size, &num)) < 0) {

        av_log(matroska->ctx, AV_LOG_ERROR, "EBML block data error\n");

        return res;

    }

    data += n;

    size -= n;



    track = matroska_find_track_by_num(matroska, num);

    if (size <= 3 || !track || !track->stream) {

        av_log(matroska->ctx, AV_LOG_INFO,

               "Invalid stream %"PRIu64" or size %u\n", num, size);

        return res;

    }

    st = track->stream;

    if (st->discard >= AVDISCARD_ALL)

        return res;

    if (duration == AV_NOPTS_VALUE)

        duration = track->default_duration / matroska->time_scale;



    block_time = AV_RB16(data);

    data += 2;

    flags = *data++;

    size -= 3;

    if (is_keyframe == -1)

        is_keyframe = flags & 0x80 ? PKT_FLAG_KEY : 0;



    if (cluster_time != (uint64_t)-1

        && (block_time >= 0 || cluster_time >= -block_time)) {

        timecode = cluster_time + block_time;

        if (track->type == MATROSKA_TRACK_TYPE_SUBTITLE

            && timecode < track->end_timecode)

            is_keyframe = 0;  /* overlapping subtitles are not key frame */

        if (is_keyframe)

            av_add_index_entry(st, cluster_pos, timecode, 0,0,AVINDEX_KEYFRAME);

        track->end_timecode = FFMAX(track->end_timecode, timecode+duration);

    }



    if (matroska->skip_to_keyframe && track->type != MATROSKA_TRACK_TYPE_SUBTITLE) {

        if (!is_keyframe || timecode < matroska->skip_to_timecode)

            return res;

        matroska->skip_to_keyframe = 0;

    }



    switch ((flags & 0x06) >> 1) {

        case 0x0: /* no lacing */

            laces = 1;

            lace_size = av_mallocz(sizeof(int));

            lace_size[0] = size;

            break;



        case 0x1: /* Xiph lacing */

        case 0x2: /* fixed-size lacing */

        case 0x3: /* EBML lacing */

            assert(size>0); // size <=3 is checked before size-=3 above

            laces = (*data) + 1;

            data += 1;

            size -= 1;

            lace_size = av_mallocz(laces * sizeof(int));



            switch ((flags & 0x06) >> 1) {

                case 0x1: /* Xiph lacing */ {

                    uint8_t temp;

                    uint32_t total = 0;

                    for (n = 0; res == 0 && n < laces - 1; n++) {

                        while (1) {

                            if (size == 0) {

                                res = -1;

                                break;

                            }

                            temp = *data;

                            lace_size[n] += temp;

                            data += 1;

                            size -= 1;

                            if (temp != 0xff)

                                break;

                        }

                        total += lace_size[n];

                    }

                    lace_size[n] = size - total;

                    break;

                }



                case 0x2: /* fixed-size lacing */

                    for (n = 0; n < laces; n++)

                        lace_size[n] = size / laces;

                    break;



                case 0x3: /* EBML lacing */ {

                    uint32_t total;

                    n = matroska_ebmlnum_uint(matroska, data, size, &num);

                    if (n < 0) {

                        av_log(matroska->ctx, AV_LOG_INFO,

                               "EBML block data error\n");

                        break;

                    }

                    data += n;

                    size -= n;

                    total = lace_size[0] = num;

                    for (n = 1; res == 0 && n < laces - 1; n++) {

                        int64_t snum;

                        int r;

                        r = matroska_ebmlnum_sint(matroska, data, size, &snum);

                        if (r < 0) {

                            av_log(matroska->ctx, AV_LOG_INFO,

                                   "EBML block data error\n");

                            break;

                        }

                        data += r;

                        size -= r;

                        lace_size[n] = lace_size[n - 1] + snum;

                        total += lace_size[n];

                    }

                    lace_size[n] = size - total;

                    break;

                }

            }

            break;

    }



    if (res == 0) {

        for (n = 0; n < laces; n++) {

            if (st->codec->codec_id == CODEC_ID_RA_288 ||

                st->codec->codec_id == CODEC_ID_COOK ||

                st->codec->codec_id == CODEC_ID_ATRAC3) {

                int a = st->codec->block_align;

                int sps = track->audio.sub_packet_size;

                int cfs = track->audio.coded_framesize;

                int h = track->audio.sub_packet_h;

                int y = track->audio.sub_packet_cnt;

                int w = track->audio.frame_size;

                int x;



                if (!track->audio.pkt_cnt) {

                    if (st->codec->codec_id == CODEC_ID_RA_288)

                        for (x=0; x<h/2; x++)

                            memcpy(track->audio.buf+x*2*w+y*cfs,

                                   data+x*cfs, cfs);

                    else

                        for (x=0; x<w/sps; x++)

                            memcpy(track->audio.buf+sps*(h*x+((h+1)/2)*(y&1)+(y>>1)), data+x*sps, sps);



                    if (++track->audio.sub_packet_cnt >= h) {

                        track->audio.sub_packet_cnt = 0;

                        track->audio.pkt_cnt = h*w / a;

                    }

                }

                while (track->audio.pkt_cnt) {

                    pkt = av_mallocz(sizeof(AVPacket));

                    av_new_packet(pkt, a);

                    memcpy(pkt->data, track->audio.buf

                           + a * (h*w / a - track->audio.pkt_cnt--), a);

                    pkt->pos = pos;

                    pkt->stream_index = st->index;

                    dynarray_add(&matroska->packets,&matroska->num_packets,pkt);

                }

            } else {

                MatroskaTrackEncoding *encodings = track->encodings.elem;

                int offset = 0, pkt_size = lace_size[n];

                uint8_t *pkt_data = data;



                if (encodings && encodings->scope & 1) {

                    offset = matroska_decode_buffer(&pkt_data,&pkt_size, track);

                    if (offset < 0)

                        continue;

                }



                pkt = av_mallocz(sizeof(AVPacket));

                /* XXX: prevent data copy... */

                if (av_new_packet(pkt, pkt_size+offset) < 0) {

                    av_free(pkt);

                    res = AVERROR(ENOMEM);

                    break;

                }

                if (offset)

                    memcpy (pkt->data, encodings->compression.settings.data, offset);

                memcpy (pkt->data+offset, pkt_data, pkt_size);



                if (pkt_data != data)

                    av_free(pkt_data);



                if (n == 0)

                    pkt->flags = is_keyframe;

                pkt->stream_index = st->index;



                pkt->pts = timecode;

                pkt->pos = pos;

                if (st->codec->codec_id == CODEC_ID_TEXT)

                    pkt->convergence_duration = duration;

                else if (track->type != MATROSKA_TRACK_TYPE_SUBTITLE)

                    pkt->duration = duration;



                if (st->codec->codec_id == CODEC_ID_SSA)

                    matroska_fix_ass_packet(matroska, pkt, duration);



                if (matroska->prev_pkt &&

                    timecode != AV_NOPTS_VALUE &&

                    matroska->prev_pkt->pts == timecode &&

                    matroska->prev_pkt->stream_index == st->index)

                    matroska_merge_packets(matroska->prev_pkt, pkt);

                else {

                    dynarray_add(&matroska->packets,&matroska->num_packets,pkt);

                    matroska->prev_pkt = pkt;

                }

            }



            if (timecode != AV_NOPTS_VALUE)

                timecode = duration ? timecode + duration : AV_NOPTS_VALUE;

            data += lace_size[n];

        }

    }



    av_free(lace_size);

    return res;

}

static void rtsp_cmd_pause(HTTPContext *c, const char *url, RTSPHeader *h)

{

    HTTPContext *rtp_c;



    rtp_c = find_rtp_session_with_url(url, h->session_id);

    if (!rtp_c) {

        rtsp_reply_error(c, RTSP_STATUS_SESSION);

        return;

    }



    if (rtp_c->state != HTTPSTATE_SEND_DATA &&

        rtp_c->state != HTTPSTATE_WAIT_FEED) {

        rtsp_reply_error(c, RTSP_STATUS_STATE);

        return;

    }



    rtp_c->state = HTTPSTATE_READY;



    /* now everything is OK, so we can send the connection parameters */

    rtsp_reply_header(c, RTSP_STATUS_OK);

    /* session ID */

    url_fprintf(c->pb, "Session: %s\r\n", rtp_c->session_id);

    url_fprintf(c->pb, "\r\n");

}

AVParserState *ff_store_parser_state(AVFormatContext *s)

{

    int i;

    AVStream *st;

    AVParserStreamState *ss;

    AVParserState *state = av_malloc(sizeof(AVParserState));

    if (!state)

        return NULL;



    state->stream_states = av_malloc(sizeof(AVParserStreamState) * s->nb_streams);

    if (!state->stream_states) {

        av_free(state);

        return NULL;

    }



    state->fpos = avio_tell(s->pb);



    // copy context structures

    state->cur_st                           = s->cur_st;

    state->packet_buffer                    = s->packet_buffer;

    state->raw_packet_buffer                = s->raw_packet_buffer;

    state->raw_packet_buffer_remaining_size = s->raw_packet_buffer_remaining_size;



    s->cur_st                               = NULL;

    s->packet_buffer                        = NULL;

    s->raw_packet_buffer                    = NULL;

    s->raw_packet_buffer_remaining_size     = RAW_PACKET_BUFFER_SIZE;



    // copy stream structures

    state->nb_streams = s->nb_streams;

    for (i = 0; i < s->nb_streams; i++) {

        st = s->streams[i];

        ss = &state->stream_states[i];



        ss->parser        = st->parser;

        ss->last_IP_pts   = st->last_IP_pts;

        ss->cur_dts       = st->cur_dts;

        ss->reference_dts = st->reference_dts;

        ss->cur_ptr       = st->cur_ptr;

        ss->cur_len       = st->cur_len;

        ss->probe_packets = st->probe_packets;

        ss->cur_pkt       = st->cur_pkt;



        st->parser        = NULL;

        st->last_IP_pts   = AV_NOPTS_VALUE;

        st->cur_dts       = AV_NOPTS_VALUE;

        st->reference_dts = AV_NOPTS_VALUE;

        st->cur_ptr       = NULL;

        st->cur_len       = 0;

        st->probe_packets = MAX_PROBE_PACKETS;

        av_init_packet(&st->cur_pkt);

    }



    return state;

}

