static int config_input(AVFilterLink *inlink)

{

    AVFilterContext *ctx = inlink->dst;

    PadContext *s = ctx->priv;

    const AVPixFmtDescriptor *pix_desc = av_pix_fmt_desc_get(inlink->format);

    uint8_t rgba_color[4];

    int ret, is_packed_rgba;

    double var_values[VARS_NB], res;

    char *expr;



    s->hsub = pix_desc->log2_chroma_w;

    s->vsub = pix_desc->log2_chroma_h;



    var_values[VAR_PI]    = M_PI;

    var_values[VAR_PHI]   = M_PHI;

    var_values[VAR_E]     = M_E;

    var_values[VAR_IN_W]  = var_values[VAR_IW] = inlink->w;

    var_values[VAR_IN_H]  = var_values[VAR_IH] = inlink->h;

    var_values[VAR_OUT_W] = var_values[VAR_OW] = NAN;

    var_values[VAR_OUT_H] = var_values[VAR_OH] = NAN;

    var_values[VAR_A]     = (double) inlink->w / inlink->h;

    var_values[VAR_HSUB]  = 1<<s->hsub;

    var_values[VAR_VSUB]  = 1<<s->vsub;



    /* evaluate width and height */

    if ((ret = av_expr_parse_and_eval(&res, (expr = s->w_expr),

                                      var_names, var_values,

                                      NULL, NULL, NULL, NULL, NULL, 0, ctx)) < 0)

        goto eval_fail;

    s->w = var_values[VAR_OUT_W] = var_values[VAR_OW] = res;

    if ((ret = av_expr_parse_and_eval(&res, (expr = s->h_expr),

                                      var_names, var_values,

                                      NULL, NULL, NULL, NULL, NULL, 0, ctx)) < 0)

        goto eval_fail;

    s->h = var_values[VAR_OUT_H] = var_values[VAR_OH] = res;

    /* evaluate the width again, as it may depend on the evaluated output height */

    if ((ret = av_expr_parse_and_eval(&res, (expr = s->w_expr),

                                      var_names, var_values,

                                      NULL, NULL, NULL, NULL, NULL, 0, ctx)) < 0)

        goto eval_fail;

    s->w = var_values[VAR_OUT_W] = var_values[VAR_OW] = res;



    /* evaluate x and y */

    if ((ret = av_expr_parse_and_eval(&res, (expr = s->x_expr),

                                      var_names, var_values,

                                      NULL, NULL, NULL, NULL, NULL, 0, ctx)) < 0)

        goto eval_fail;

    s->x = var_values[VAR_X] = res;

    if ((ret = av_expr_parse_and_eval(&res, (expr = s->y_expr),

                                      var_names, var_values,

                                      NULL, NULL, NULL, NULL, NULL, 0, ctx)) < 0)

        goto eval_fail;

    s->y = var_values[VAR_Y] = res;

    /* evaluate x again, as it may depend on the evaluated y value */

    if ((ret = av_expr_parse_and_eval(&res, (expr = s->x_expr),

                                      var_names, var_values,

                                      NULL, NULL, NULL, NULL, NULL, 0, ctx)) < 0)

        goto eval_fail;

    s->x = var_values[VAR_X] = res;



    /* sanity check params */

    if (s->w < 0 || s->h < 0 || s->x < 0 || s->y < 0) {

        av_log(ctx, AV_LOG_ERROR, "Negative values are not acceptable.\n");

        return AVERROR(EINVAL);

    }



    if (!s->w)

        s->w = inlink->w;

    if (!s->h)

        s->h = inlink->h;



    s->w &= ~((1 << s->hsub) - 1);

    s->h &= ~((1 << s->vsub) - 1);

    s->x &= ~((1 << s->hsub) - 1);

    s->y &= ~((1 << s->vsub) - 1);



    s->in_w = inlink->w & ~((1 << s->hsub) - 1);

    s->in_h = inlink->h & ~((1 << s->vsub) - 1);



    memcpy(rgba_color, s->color, sizeof(rgba_color));

    ff_fill_line_with_color(s->line, s->line_step, s->w, s->color,

                            inlink->format, rgba_color, &is_packed_rgba, NULL);



    av_log(ctx, AV_LOG_VERBOSE, "w:%d h:%d -> w:%d h:%d x:%d y:%d color:0x%02X%02X%02X%02X[%s]\n",

           inlink->w, inlink->h, s->w, s->h, s->x, s->y,

           s->color[0], s->color[1], s->color[2], s->color[3],

           is_packed_rgba ? "rgba" : "yuva");



    if (s->x <  0 || s->y <  0                      ||

        s->w <= 0 || s->h <= 0                      ||

        (unsigned)s->x + (unsigned)inlink->w > s->w ||

        (unsigned)s->y + (unsigned)inlink->h > s->h) {

        av_log(ctx, AV_LOG_ERROR,

               "Input area %d:%d:%d:%d not within the padded area 0:0:%d:%d or zero-sized\n",

               s->x, s->y, s->x + inlink->w, s->y + inlink->h, s->w, s->h);

        return AVERROR(EINVAL);

    }



    return 0;



eval_fail:

    av_log(NULL, AV_LOG_ERROR,

           "Error when evaluating the expression '%s'\n", expr);

    return ret;



}

AVRational av_guess_frame_rate(AVFormatContext *format, AVStream *st, AVFrame *frame)

{

    AVRational fr = st->r_frame_rate;

    AVRational codec_fr = st->codec->framerate;

    AVRational   avg_fr = st->avg_frame_rate;



    if (avg_fr.num > 0 && avg_fr.den > 0 && fr.num > 0 && fr.den > 0 &&

        av_q2d(avg_fr) < 70 && av_q2d(fr) > 210) {

        fr = avg_fr;

    }





    if (st->codec->ticks_per_frame > 1) {

        if (   codec_fr.num > 0 && codec_fr.den > 0 && av_q2d(codec_fr) < av_q2d(fr)*0.7

            && fabs(1.0 - av_q2d(av_div_q(avg_fr, fr))) > 0.1)

            fr = codec_fr;

    }



    return fr;

}

static void apply_mid_side_stereo(ChannelElement *cpe)

{

    int w, w2, g, i;

    IndividualChannelStream *ics = &cpe->ch[0].ics;

    if (!cpe->common_window)

        return;

    for (w = 0; w < ics->num_windows; w += ics->group_len[w]) {

        for (w2 =  0; w2 < ics->group_len[w]; w2++) {

            int start = (w+w2) * 128;

            for (g = 0; g < ics->num_swb; g++) {

                if (!cpe->ms_mask[w*16 + g]) {

                    start += ics->swb_sizes[g];

                    continue;

                }

                for (i = 0; i < ics->swb_sizes[g]; i++) {

                    float L = (cpe->ch[0].coeffs[start+i] + cpe->ch[1].coeffs[start+i]) * 0.5f;

                    float R = L - cpe->ch[1].coeffs[start+i];

                    cpe->ch[0].coeffs[start+i] = L;

                    cpe->ch[1].coeffs[start+i] = R;

                }

                start += ics->swb_sizes[g];

            }

        }

    }

}

static int ea_read_header(AVFormatContext *s,

                          AVFormatParameters *ap)

{

    EaDemuxContext *ea = s->priv_data;

    AVStream *st;



    if (!process_ea_header(s))

        return AVERROR(EIO);



    if (ea->time_base.num && ea->time_base.den) {

        /* initialize the video decoder stream */

        st = av_new_stream(s, 0);

        if (!st)

            return AVERROR(ENOMEM);

        ea->video_stream_index = st->index;

        st->codec->codec_type = CODEC_TYPE_VIDEO;

        st->codec->codec_id = ea->video_codec;

        st->codec->codec_tag = 0;  /* no fourcc */

        st->codec->time_base = ea->time_base;

    }



    if (ea->audio_codec) {

        /* initialize the audio decoder stream */

        st = av_new_stream(s, 0);

        if (!st)

            return AVERROR(ENOMEM);

        av_set_pts_info(st, 33, 1, ea->sample_rate);

        st->codec->codec_type = CODEC_TYPE_AUDIO;

        st->codec->codec_id = ea->audio_codec;

        st->codec->codec_tag = 0;  /* no tag */

        st->codec->channels = ea->num_channels;

        st->codec->sample_rate = ea->sample_rate;

        st->codec->bits_per_sample = ea->bytes * 8;

        st->codec->bit_rate = st->codec->channels * st->codec->sample_rate *

            st->codec->bits_per_sample / 4;

        st->codec->block_align = st->codec->channels*st->codec->bits_per_sample;

        ea->audio_stream_index = st->index;

        ea->audio_frame_counter = 0;

    }



    return 1;

}

static int set_format(void *obj, const char *name, int fmt, int search_flags,

                      enum AVOptionType type, const char *desc, int max)

{

    void *target_obj;

    const AVOption *o = av_opt_find2(obj, name, NULL, 0,

                                     search_flags, &target_obj);

    if (!o || !target_obj)

        return AVERROR_OPTION_NOT_FOUND;

    if (o->type != type) {

        av_log(obj, AV_LOG_ERROR,

               "The value set by option '%s' is not a %s format", name, desc);

        return AVERROR(EINVAL);

    }



    if (fmt < -1 || fmt > max) {

        av_log(obj, AV_LOG_ERROR,

               "Value %d for parameter '%s' out of %s format range [-1 - %d]\n",

               fmt, name, desc, max);

        return AVERROR(ERANGE);

    }

    *(int *)(((uint8_t *)target_obj) + o->offset) = fmt;

    return 0;

}

static int ape_read_packet(AVFormatContext * s, AVPacket * pkt)

{

    int ret;

    int nblocks;

    APEContext *ape = s->priv_data;

    uint32_t extra_size = 8;



    if (url_feof(s->pb))

        return AVERROR_EOF;

    if (ape->currentframe >= ape->totalframes)

        return AVERROR_EOF;



    if (avio_seek(s->pb, ape->frames[ape->currentframe].pos, SEEK_SET) < 0)

        return AVERROR(EIO);



    /* Calculate how many blocks there are in this frame */

    if (ape->currentframe == (ape->totalframes - 1))

        nblocks = ape->finalframeblocks;

    else

        nblocks = ape->blocksperframe;



    if (ape->frames[ape->currentframe].size <= 0 ||

        ape->frames[ape->currentframe].size > INT_MAX - extra_size) {

        av_log(s, AV_LOG_ERROR, "invalid packet size: %d\n",

               ape->frames[ape->currentframe].size);

        ape->currentframe++;

        return AVERROR(EIO);

    }



    if (av_new_packet(pkt,  ape->frames[ape->currentframe].size + extra_size) < 0)

        return AVERROR(ENOMEM);



    AV_WL32(pkt->data    , nblocks);

    AV_WL32(pkt->data + 4, ape->frames[ape->currentframe].skip);

    ret = avio_read(s->pb, pkt->data + extra_size, ape->frames[ape->currentframe].size);





    pkt->pts = ape->frames[ape->currentframe].pts;

    pkt->stream_index = 0;



    /* note: we need to modify the packet size here to handle the last

       packet */

    pkt->size = ret + extra_size;



    ape->currentframe++;



    return 0;

}

static int svq1_decode_frame_header(AVCodecContext *avctx, AVFrame *frame)

{

    SVQ1Context *s = avctx->priv_data;

    GetBitContext *bitbuf = &s->gb;

    int frame_size_code;

    int width  = s->width;

    int height = s->height;



    skip_bits(bitbuf, 8); /* temporal_reference */



    /* frame type */

    s->nonref = 0;

    switch (get_bits(bitbuf, 2)) {

    case 0:

        frame->pict_type = AV_PICTURE_TYPE_I;

        break;

    case 2:

        s->nonref = 1;

    case 1:

        frame->pict_type = AV_PICTURE_TYPE_P;

        break;

    default:

        av_log(avctx, AV_LOG_ERROR, "Invalid frame type.\n");

        return AVERROR_INVALIDDATA;

    }



    if (frame->pict_type == AV_PICTURE_TYPE_I) {

        /* unknown fields */

        if (s->frame_code == 0x50 || s->frame_code == 0x60) {

            int csum = get_bits(bitbuf, 16);



            csum = ff_svq1_packet_checksum(bitbuf->buffer,

                                           bitbuf->size_in_bits >> 3,

                                           csum);



            av_dlog(avctx, "%s checksum (%02x) for packet data\n",

                    (csum == 0) ? "correct" : "incorrect", csum);

        }



        if ((s->frame_code ^ 0x10) >= 0x50) {

            uint8_t msg[256];



            svq1_parse_string(bitbuf, msg);



            av_log(avctx, AV_LOG_INFO,

                   "embedded message:\n%s\n", (char *)msg);

        }



        skip_bits(bitbuf, 2);

        skip_bits(bitbuf, 2);

        skip_bits1(bitbuf);



        /* load frame size */

        frame_size_code = get_bits(bitbuf, 3);



        if (frame_size_code == 7) {

            /* load width, height (12 bits each) */

            width  = get_bits(bitbuf, 12);

            height = get_bits(bitbuf, 12);



            if (!width || !height)

                return AVERROR_INVALIDDATA;

        } else {

            /* get width, height from table */

            width  = ff_svq1_frame_size_table[frame_size_code][0];

            height = ff_svq1_frame_size_table[frame_size_code][1];

        }

    }



    /* unknown fields */

    if (get_bits1(bitbuf)) {

        skip_bits1(bitbuf);    /* use packet checksum if (1) */

        skip_bits1(bitbuf);    /* component checksums after image data if (1) */



        if (get_bits(bitbuf, 2) != 0)

            return AVERROR_INVALIDDATA;

    }



    if (get_bits1(bitbuf)) {

        skip_bits1(bitbuf);

        skip_bits(bitbuf, 4);

        skip_bits1(bitbuf);

        skip_bits(bitbuf, 2);



        if (skip_1stop_8data_bits(bitbuf) < 0)

            return AVERROR_INVALIDDATA;

    }



    s->width  = width;

    s->height = height;

    return 0;

}

static int64_t ftp_seek(URLContext *h, int64_t pos, int whence)

{

    FTPContext *s = h->priv_data;

    int err;

    int64_t new_pos, fake_pos;



    av_dlog(h, "ftp protocol seek %"PRId64" %d\n", pos, whence);



    switch(whence) {

    case AVSEEK_SIZE:

        return s->filesize;

    case SEEK_SET:

        new_pos = pos;

        break;

    case SEEK_CUR:

        new_pos = s->position + pos;

        break;

    case SEEK_END:

        if (s->filesize < 0)

            return AVERROR(EIO);

        new_pos = s->filesize + pos;

        break;

    default:

        return AVERROR(EINVAL);

    }



    if (h->is_streamed)

        return AVERROR(EIO);



    if (new_pos < 0) {

        av_log(h, AV_LOG_ERROR, "Seeking to nagative position.\n");

        return AVERROR(EINVAL);

    }



    fake_pos = s->filesize != -1 ? FFMIN(new_pos, s->filesize) : new_pos;

    if (fake_pos != s->position) {

        if ((err = ftp_abort(h)) < 0)

            return err;

        s->position = fake_pos;

    }

    return new_pos;

}

static int encode_superframe(AVCodecContext *avctx, AVPacket *avpkt,

                             const AVFrame *frame, int *got_packet_ptr)

{

    WMACodecContext *s = avctx->priv_data;

    int i, total_gain, ret, error;



    s->block_len_bits= s->frame_len_bits; //required by non variable block len

    s->block_len = 1 << s->block_len_bits;



    apply_window_and_mdct(avctx, frame);



    if (s->ms_stereo) {

        float a, b;

        int i;



        for(i = 0; i < s->block_len; i++) {

            a = s->coefs[0][i]*0.5;

            b = s->coefs[1][i]*0.5;

            s->coefs[0][i] = a + b;

            s->coefs[1][i] = a - b;

        }

    }



    if ((ret = ff_alloc_packet2(avctx, avpkt, 2 * MAX_CODED_SUPERFRAME_SIZE)))

        return ret;



    total_gain= 128;

    for(i=64; i; i>>=1){

        error = encode_frame(s, s->coefs, avpkt->data, avpkt->size,

                                 total_gain - i);

        if(error<=0)

            total_gain-= i;

    }



    while(total_gain <= 128 && error > 0)

        error = encode_frame(s, s->coefs, avpkt->data, avpkt->size, total_gain++);

    av_assert0((put_bits_count(&s->pb) & 7) == 0);

    i= avctx->block_align - (put_bits_count(&s->pb)+7)/8;

    av_assert0(i>=0);

    while(i--)

        put_bits(&s->pb, 8, 'N');



    flush_put_bits(&s->pb);

    av_assert0(put_bits_ptr(&s->pb) - s->pb.buf == avctx->block_align);



    if (frame->pts != AV_NOPTS_VALUE)

        avpkt->pts = frame->pts - ff_samples_to_time_base(avctx, avctx->delay);



    avpkt->size = avctx->block_align;

    *got_packet_ptr = 1;

    return 0;

}

static int g729_parse(AVCodecParserContext *s1, AVCodecContext *avctx,

                     const uint8_t **poutbuf, int *poutbuf_size,

                     const uint8_t *buf, int buf_size)

{

    G729ParseContext *s = s1->priv_data;

    ParseContext *pc = &s->pc;

    int next;



    if (!s->block_size) {

        switch (avctx->codec_id) {

        case AV_CODEC_ID_G729:

            /* FIXME: replace this heuristic block_size with more precise estimate */

            s->block_size = (avctx->bit_rate < 8000) ? G729D_6K4_BLOCK_SIZE : G729_8K_BLOCK_SIZE;

            s->duration   = avctx->frame_size;

            break;

        default:

            *poutbuf      = buf;

            *poutbuf_size = buf_size;

            av_log(avctx, AV_LOG_ERROR, "Invalid codec_id\n");

            return buf_size;

        }

    }



    if (!s->remaining)

        s->remaining = s->block_size;

    if (s->remaining <= buf_size) {

        next = s->remaining;

        s->remaining = 0;

    } else {

        next = END_NOT_FOUND;

        s->remaining -= buf_size;

    }



    if (ff_combine_frame(pc, next, &buf, &buf_size) < 0 || !buf_size) {

        *poutbuf      = NULL;

        *poutbuf_size = 0;

        return buf_size;

    }



    s1->duration = s->duration;



    *poutbuf      = buf;

    *poutbuf_size = buf_size;

    return next;

}

static int decode_audio_block(AC3DecodeContext *s, int blk)

{

    int fbw_channels = s->fbw_channels;

    int channel_mode = s->channel_mode;

    int i, bnd, seg, ch;

    int different_transforms;

    int downmix_output;

    int cpl_in_use;

    GetBitContext *gbc = &s->gbc;

    uint8_t bit_alloc_stages[AC3_MAX_CHANNELS];



    memset(bit_alloc_stages, 0, AC3_MAX_CHANNELS);



    /* block switch flags */

    different_transforms = 0;

    if (s->block_switch_syntax) {

        for (ch = 1; ch <= fbw_channels; ch++) {

            s->block_switch[ch] = get_bits1(gbc);

            if(ch > 1 && s->block_switch[ch] != s->block_switch[1])

                different_transforms = 1;

        }

    }



    /* dithering flags */

    if (s->dither_flag_syntax) {

        for (ch = 1; ch <= fbw_channels; ch++) {

            s->dither_flag[ch] = get_bits1(gbc);

        }

    }



    /* dynamic range */

    i = !(s->channel_mode);

    do {

        if(get_bits1(gbc)) {

            s->dynamic_range[i] = ((dynamic_range_tab[get_bits(gbc, 8)]-1.0) *

                                  s->avctx->drc_scale)+1.0;

        } else if(blk == 0) {

            s->dynamic_range[i] = 1.0f;

        }

    } while(i--);



    /* spectral extension strategy */

    if (s->eac3 && (!blk || get_bits1(gbc))) {

        if (get_bits1(gbc)) {

            av_log_missing_feature(s->avctx, "Spectral extension", 1);

            return -1;

        }

        /* TODO: parse spectral extension strategy info */

    }



    /* TODO: spectral extension coordinates */



    /* coupling strategy */

    if (s->eac3 ? s->cpl_strategy_exists[blk] : get_bits1(gbc)) {

        memset(bit_alloc_stages, 3, AC3_MAX_CHANNELS);

        if (!s->eac3)

            s->cpl_in_use[blk] = get_bits1(gbc);

        if (s->cpl_in_use[blk]) {

            /* coupling in use */

            int cpl_start_subband, cpl_end_subband;



            if (channel_mode < AC3_CHMODE_STEREO) {

                av_log(s->avctx, AV_LOG_ERROR, "coupling not allowed in mono or dual-mono\n");

                return -1;

            }



            /* check for enhanced coupling */

            if (s->eac3 && get_bits1(gbc)) {

                /* TODO: parse enhanced coupling strategy info */

                av_log_missing_feature(s->avctx, "Enhanced coupling", 1);

                return -1;

            }



            /* determine which channels are coupled */

            if (s->eac3 && s->channel_mode == AC3_CHMODE_STEREO) {

                s->channel_in_cpl[1] = 1;

                s->channel_in_cpl[2] = 1;

            } else {

                for (ch = 1; ch <= fbw_channels; ch++)

                    s->channel_in_cpl[ch] = get_bits1(gbc);

            }



            /* phase flags in use */

            if (channel_mode == AC3_CHMODE_STEREO)

                s->phase_flags_in_use = get_bits1(gbc);



            /* coupling frequency range */

            /* TODO: modify coupling end freq if spectral extension is used */

            cpl_start_subband = get_bits(gbc, 4);

            cpl_end_subband   = get_bits(gbc, 4) + 3;

            s->num_cpl_subbands = cpl_end_subband - cpl_start_subband;

            if (s->num_cpl_subbands < 0) {

                av_log(s->avctx, AV_LOG_ERROR, "invalid coupling range (%d > %d)\n",

                       cpl_start_subband, cpl_end_subband);

                return -1;

            }

            s->start_freq[CPL_CH] = cpl_start_subband * 12 + 37;

            s->end_freq[CPL_CH]   = cpl_end_subband   * 12 + 37;



           decode_band_structure(gbc, blk, s->eac3, 0,

                                 cpl_start_subband, cpl_end_subband,

                                 ff_eac3_default_cpl_band_struct,

                                 s->cpl_band_struct, &s->num_cpl_subbands,

                                 &s->num_cpl_bands, NULL);

        } else {

            /* coupling not in use */

            for (ch = 1; ch <= fbw_channels; ch++) {

                s->channel_in_cpl[ch] = 0;

                s->first_cpl_coords[ch] = 1;

            }

            s->first_cpl_leak = s->eac3;

            s->phase_flags_in_use = 0;

        }

    } else if (!s->eac3) {

        if(!blk) {

            av_log(s->avctx, AV_LOG_ERROR, "new coupling strategy must be present in block 0\n");

            return -1;

        } else {

            s->cpl_in_use[blk] = s->cpl_in_use[blk-1];

        }

    }

    cpl_in_use = s->cpl_in_use[blk];



    /* coupling coordinates */

    if (cpl_in_use) {

        int cpl_coords_exist = 0;



        for (ch = 1; ch <= fbw_channels; ch++) {

            if (s->channel_in_cpl[ch]) {

                if ((s->eac3 && s->first_cpl_coords[ch]) || get_bits1(gbc)) {

                    int master_cpl_coord, cpl_coord_exp, cpl_coord_mant;

                    s->first_cpl_coords[ch] = 0;

                    cpl_coords_exist = 1;

                    master_cpl_coord = 3 * get_bits(gbc, 2);

                    for (bnd = 0; bnd < s->num_cpl_bands; bnd++) {

                        cpl_coord_exp = get_bits(gbc, 4);

                        cpl_coord_mant = get_bits(gbc, 4);

                        if (cpl_coord_exp == 15)

                            s->cpl_coords[ch][bnd] = cpl_coord_mant << 22;

                        else

                            s->cpl_coords[ch][bnd] = (cpl_coord_mant + 16) << 21;

                        s->cpl_coords[ch][bnd] >>= (cpl_coord_exp + master_cpl_coord);

                    }

                } else if (!blk) {

                    av_log(s->avctx, AV_LOG_ERROR, "new coupling coordinates must be present in block 0\n");

                    return -1;

                }

            } else {

                /* channel not in coupling */

                s->first_cpl_coords[ch] = 1;

            }

        }

        /* phase flags */

        if (channel_mode == AC3_CHMODE_STEREO && cpl_coords_exist) {

            for (bnd = 0; bnd < s->num_cpl_bands; bnd++) {

                s->phase_flags[bnd] = s->phase_flags_in_use? get_bits1(gbc) : 0;

            }

        }

    }



    /* stereo rematrixing strategy and band structure */

    if (channel_mode == AC3_CHMODE_STEREO) {

        if ((s->eac3 && !blk) || get_bits1(gbc)) {

            s->num_rematrixing_bands = 4;

            if(cpl_in_use && s->start_freq[CPL_CH] <= 61)

                s->num_rematrixing_bands -= 1 + (s->start_freq[CPL_CH] == 37);

            for(bnd=0; bnd<s->num_rematrixing_bands; bnd++)

                s->rematrixing_flags[bnd] = get_bits1(gbc);

        } else if (!blk) {

            av_log(s->avctx, AV_LOG_ERROR, "new rematrixing strategy must be present in block 0\n");

            return -1;

        }

    }



    /* exponent strategies for each channel */

    for (ch = !cpl_in_use; ch <= s->channels; ch++) {

        if (!s->eac3)

            s->exp_strategy[blk][ch] = get_bits(gbc, 2 - (ch == s->lfe_ch));

        if(s->exp_strategy[blk][ch] != EXP_REUSE)

            bit_alloc_stages[ch] = 3;

    }



    /* channel bandwidth */

    for (ch = 1; ch <= fbw_channels; ch++) {

        s->start_freq[ch] = 0;

        if (s->exp_strategy[blk][ch] != EXP_REUSE) {

            int group_size;

            int prev = s->end_freq[ch];

            if (s->channel_in_cpl[ch])

                s->end_freq[ch] = s->start_freq[CPL_CH];

            else {

                int bandwidth_code = get_bits(gbc, 6);

                if (bandwidth_code > 60) {

                    av_log(s->avctx, AV_LOG_ERROR, "bandwidth code = %d > 60\n", bandwidth_code);

                    return -1;

                }

                s->end_freq[ch] = bandwidth_code * 3 + 73;

            }

            group_size = 3 << (s->exp_strategy[blk][ch] - 1);

            s->num_exp_groups[ch] = (s->end_freq[ch]+group_size-4) / group_size;

            if(blk > 0 && s->end_freq[ch] != prev)

                memset(bit_alloc_stages, 3, AC3_MAX_CHANNELS);

        }

    }

    if (cpl_in_use && s->exp_strategy[blk][CPL_CH] != EXP_REUSE) {

        s->num_exp_groups[CPL_CH] = (s->end_freq[CPL_CH] - s->start_freq[CPL_CH]) /

                                    (3 << (s->exp_strategy[blk][CPL_CH] - 1));

    }



    /* decode exponents for each channel */

    for (ch = !cpl_in_use; ch <= s->channels; ch++) {

        if (s->exp_strategy[blk][ch] != EXP_REUSE) {

            s->dexps[ch][0] = get_bits(gbc, 4) << !ch;

            if (decode_exponents(gbc, s->exp_strategy[blk][ch],

                                 s->num_exp_groups[ch], s->dexps[ch][0],

                                 &s->dexps[ch][s->start_freq[ch]+!!ch])) {

                av_log(s->avctx, AV_LOG_ERROR, "exponent out-of-range\n");

                return -1;

            }

            if(ch != CPL_CH && ch != s->lfe_ch)

                skip_bits(gbc, 2); /* skip gainrng */

        }

    }



    /* bit allocation information */

    if (s->bit_allocation_syntax) {

        if (get_bits1(gbc)) {

            s->bit_alloc_params.slow_decay = ff_ac3_slow_decay_tab[get_bits(gbc, 2)] >> s->bit_alloc_params.sr_shift;

            s->bit_alloc_params.fast_decay = ff_ac3_fast_decay_tab[get_bits(gbc, 2)] >> s->bit_alloc_params.sr_shift;

            s->bit_alloc_params.slow_gain  = ff_ac3_slow_gain_tab[get_bits(gbc, 2)];

            s->bit_alloc_params.db_per_bit = ff_ac3_db_per_bit_tab[get_bits(gbc, 2)];

            s->bit_alloc_params.floor  = ff_ac3_floor_tab[get_bits(gbc, 3)];

            for(ch=!cpl_in_use; ch<=s->channels; ch++)

                bit_alloc_stages[ch] = FFMAX(bit_alloc_stages[ch], 2);

        } else if (!blk) {

            av_log(s->avctx, AV_LOG_ERROR, "new bit allocation info must be present in block 0\n");

            return -1;

        }

    }



    /* signal-to-noise ratio offsets and fast gains (signal-to-mask ratios) */

    if(!s->eac3 || !blk){

        if(s->snr_offset_strategy && get_bits1(gbc)) {

            int snr = 0;

            int csnr;

            csnr = (get_bits(gbc, 6) - 15) << 4;

            for (i = ch = !cpl_in_use; ch <= s->channels; ch++) {

                /* snr offset */

                if (ch == i || s->snr_offset_strategy == 2)

                    snr = (csnr + get_bits(gbc, 4)) << 2;

                /* run at least last bit allocation stage if snr offset changes */

                if(blk && s->snr_offset[ch] != snr) {

                    bit_alloc_stages[ch] = FFMAX(bit_alloc_stages[ch], 1);

                }

                s->snr_offset[ch] = snr;



                /* fast gain (normal AC-3 only) */

                if (!s->eac3) {

                    int prev = s->fast_gain[ch];

                    s->fast_gain[ch] = ff_ac3_fast_gain_tab[get_bits(gbc, 3)];

                    /* run last 2 bit allocation stages if fast gain changes */

                    if(blk && prev != s->fast_gain[ch])

                        bit_alloc_stages[ch] = FFMAX(bit_alloc_stages[ch], 2);

                }

            }

        } else if (!s->eac3 && !blk) {

            av_log(s->avctx, AV_LOG_ERROR, "new snr offsets must be present in block 0\n");

            return -1;

        }

    }



    /* fast gain (E-AC-3 only) */

    if (s->fast_gain_syntax && get_bits1(gbc)) {

        for (ch = !cpl_in_use; ch <= s->channels; ch++) {

            int prev = s->fast_gain[ch];

            s->fast_gain[ch] = ff_ac3_fast_gain_tab[get_bits(gbc, 3)];

            /* run last 2 bit allocation stages if fast gain changes */

            if(blk && prev != s->fast_gain[ch])

                bit_alloc_stages[ch] = FFMAX(bit_alloc_stages[ch], 2);

        }

    } else if (s->eac3 && !blk) {

        for (ch = !cpl_in_use; ch <= s->channels; ch++)

            s->fast_gain[ch] = ff_ac3_fast_gain_tab[4];

    }



    /* E-AC-3 to AC-3 converter SNR offset */

    if (s->frame_type == EAC3_FRAME_TYPE_INDEPENDENT && get_bits1(gbc)) {

        skip_bits(gbc, 10); // skip converter snr offset

    }



    /* coupling leak information */

    if (cpl_in_use) {

        if (s->first_cpl_leak || get_bits1(gbc)) {

            int fl = get_bits(gbc, 3);

            int sl = get_bits(gbc, 3);

            /* run last 2 bit allocation stages for coupling channel if

               coupling leak changes */

            if(blk && (fl != s->bit_alloc_params.cpl_fast_leak ||

                       sl != s->bit_alloc_params.cpl_slow_leak)) {

                bit_alloc_stages[CPL_CH] = FFMAX(bit_alloc_stages[CPL_CH], 2);

            }

            s->bit_alloc_params.cpl_fast_leak = fl;

            s->bit_alloc_params.cpl_slow_leak = sl;

        } else if (!s->eac3 && !blk) {

            av_log(s->avctx, AV_LOG_ERROR, "new coupling leak info must be present in block 0\n");

            return -1;

        }

        s->first_cpl_leak = 0;

    }



    /* delta bit allocation information */

    if (s->dba_syntax && get_bits1(gbc)) {

        /* delta bit allocation exists (strategy) */

        for (ch = !cpl_in_use; ch <= fbw_channels; ch++) {

            s->dba_mode[ch] = get_bits(gbc, 2);

            if (s->dba_mode[ch] == DBA_RESERVED) {

                av_log(s->avctx, AV_LOG_ERROR, "delta bit allocation strategy reserved\n");

                return -1;

            }

            bit_alloc_stages[ch] = FFMAX(bit_alloc_stages[ch], 2);

        }

        /* channel delta offset, len and bit allocation */

        for (ch = !cpl_in_use; ch <= fbw_channels; ch++) {

            if (s->dba_mode[ch] == DBA_NEW) {

                s->dba_nsegs[ch] = get_bits(gbc, 3);

                for (seg = 0; seg <= s->dba_nsegs[ch]; seg++) {

                    s->dba_offsets[ch][seg] = get_bits(gbc, 5);

                    s->dba_lengths[ch][seg] = get_bits(gbc, 4);

                    s->dba_values[ch][seg] = get_bits(gbc, 3);

                }

                /* run last 2 bit allocation stages if new dba values */

                bit_alloc_stages[ch] = FFMAX(bit_alloc_stages[ch], 2);

            }

        }

    } else if(blk == 0) {

        for(ch=0; ch<=s->channels; ch++) {

            s->dba_mode[ch] = DBA_NONE;

        }

    }



    /* Bit allocation */

    for(ch=!cpl_in_use; ch<=s->channels; ch++) {

        if(bit_alloc_stages[ch] > 2) {

            /* Exponent mapping into PSD and PSD integration */

            ff_ac3_bit_alloc_calc_psd(s->dexps[ch],

                                      s->start_freq[ch], s->end_freq[ch],

                                      s->psd[ch], s->band_psd[ch]);

        }

        if(bit_alloc_stages[ch] > 1) {

            /* Compute excitation function, Compute masking curve, and

               Apply delta bit allocation */

            ff_ac3_bit_alloc_calc_mask(&s->bit_alloc_params, s->band_psd[ch],

                                       s->start_freq[ch], s->end_freq[ch],

                                       s->fast_gain[ch], (ch == s->lfe_ch),

                                       s->dba_mode[ch], s->dba_nsegs[ch],

                                       s->dba_offsets[ch], s->dba_lengths[ch],

                                       s->dba_values[ch], s->mask[ch]);

        }

        if(bit_alloc_stages[ch] > 0) {

            /* Compute bit allocation */

            const uint8_t *bap_tab = s->channel_uses_aht[ch] ?

                                     ff_eac3_hebap_tab : ff_ac3_bap_tab;

            ff_ac3_bit_alloc_calc_bap(s->mask[ch], s->psd[ch],

                                      s->start_freq[ch], s->end_freq[ch],

                                      s->snr_offset[ch],

                                      s->bit_alloc_params.floor,

                                      bap_tab, s->bap[ch]);

        }

    }



    /* unused dummy data */

    if (s->skip_syntax && get_bits1(gbc)) {

        int skipl = get_bits(gbc, 9);

        while(skipl--)

            skip_bits(gbc, 8);

    }



    /* unpack the transform coefficients

       this also uncouples channels if coupling is in use. */

    decode_transform_coeffs(s, blk);



    /* TODO: generate enhanced coupling coordinates and uncouple */



    /* TODO: apply spectral extension */



    /* recover coefficients if rematrixing is in use */

    if(s->channel_mode == AC3_CHMODE_STEREO)

        do_rematrixing(s);



    /* apply scaling to coefficients (headroom, dynrng) */

    for(ch=1; ch<=s->channels; ch++) {

        float gain = s->mul_bias / 4194304.0f;

        if(s->channel_mode == AC3_CHMODE_DUALMONO) {

            gain *= s->dynamic_range[ch-1];

        } else {

            gain *= s->dynamic_range[0];

        }

        s->dsp.int32_to_float_fmul_scalar(s->transform_coeffs[ch], s->fixed_coeffs[ch], gain, 256);

    }



    /* downmix and MDCT. order depends on whether block switching is used for

       any channel in this block. this is because coefficients for the long

       and short transforms cannot be mixed. */

    downmix_output = s->channels != s->out_channels &&

                     !((s->output_mode & AC3_OUTPUT_LFEON) &&

                     s->fbw_channels == s->out_channels);

    if(different_transforms) {

        /* the delay samples have already been downmixed, so we upmix the delay

           samples in order to reconstruct all channels before downmixing. */

        if(s->downmixed) {

            s->downmixed = 0;

            ac3_upmix_delay(s);

        }



        do_imdct(s, s->channels);



        if(downmix_output) {

            s->dsp.ac3_downmix(s->output, s->downmix_coeffs, s->out_channels, s->fbw_channels, 256);

        }

    } else {

        if(downmix_output) {

            s->dsp.ac3_downmix(s->transform_coeffs+1, s->downmix_coeffs, s->out_channels, s->fbw_channels, 256);

        }



        if(downmix_output && !s->downmixed) {

            s->downmixed = 1;

            s->dsp.ac3_downmix(s->delay, s->downmix_coeffs, s->out_channels, s->fbw_channels, 128);

        }



        do_imdct(s, s->out_channels);

    }



    return 0;

}

static int mxf_write_header_metadata_sets(AVFormatContext *s)

{

    AVStream *st;

    MXFStreamContext *sc = NULL;

    int i;



    mxf_write_preface(s);

    mxf_write_identification(s);

    mxf_write_content_storage(s);



    for (i = 0; i < s->nb_streams; i++) {

        st = s->streams[i];

        sc = av_mallocz(sizeof(MXFStreamContext));

        if (!sc)

            return AVERROR(ENOMEM);

        st->priv_data = sc;

        // set pts information

        if (st->codec->codec_type == CODEC_TYPE_VIDEO)

            av_set_pts_info(st, 64, 1, st->codec->time_base.den);

        else if (st->codec->codec_type == CODEC_TYPE_AUDIO)

            av_set_pts_info(st, 64, 1, st->codec->sample_rate);

    }



    mxf_build_structural_metadata(s, MaterialPackage);

    mxf_build_structural_metadata(s, SourcePackage);

    return 0;

}

int av_opencl_buffer_write_image(cl_mem dst_cl_buf, size_t cl_buffer_size, int dst_cl_offset,

                                                    uint8_t **src_data, int *plane_size, int plane_num)

{

    int i, buffer_size = 0;

    uint8_t *temp;

    cl_int status;

    void *mapped;

    if ((unsigned int)plane_num > 8) {

        return AVERROR(EINVAL);

    }

    for (i = 0;i < plane_num;i++) {

        buffer_size += plane_size[i];

    }

    if (buffer_size > cl_buffer_size) {

        av_log(&openclutils, AV_LOG_ERROR, "Cannot write image to OpenCL buffer: buffer too small\n");

        return AVERROR(EINVAL);

    }

    mapped = clEnqueueMapBuffer(gpu_env.command_queue, dst_cl_buf,

                                      CL_TRUE,CL_MAP_WRITE, 0, buffer_size + dst_cl_offset,

                                      0, NULL, NULL, &status);

    if (status != CL_SUCCESS) {

        av_log(&openclutils, AV_LOG_ERROR, "Could not map OpenCL buffer: %s\n", opencl_errstr(status));

        return AVERROR_EXTERNAL;

    }

    temp = mapped;

    temp += dst_cl_offset;

    for (i = 0; i < plane_num; i++) {

        memcpy(temp, src_data[i], plane_size[i]);

        temp += plane_size[i];

    }

    status = clEnqueueUnmapMemObject(gpu_env.command_queue, dst_cl_buf, mapped, 0, NULL, NULL);

    if (status != CL_SUCCESS) {

        av_log(&openclutils, AV_LOG_ERROR, "Could not unmap OpenCL buffer: %s\n", opencl_errstr(status));

        return AVERROR_EXTERNAL;

    }

    return 0;

}

int ff_get_wav_header(AVIOContext *pb, AVCodecContext *codec, int size)

{

    int id;



    id = avio_rl16(pb);

    codec->codec_type = AVMEDIA_TYPE_AUDIO;

    codec->channels = avio_rl16(pb);

    codec->sample_rate = avio_rl32(pb);

    codec->bit_rate = avio_rl32(pb) * 8;

    codec->block_align = avio_rl16(pb);

    if (size == 14) {  /* We're dealing with plain vanilla WAVEFORMAT */

        codec->bits_per_coded_sample = 8;

    }else

        codec->bits_per_coded_sample = avio_rl16(pb);

    if (id == 0xFFFE) {

        codec->codec_tag = 0;

    } else {

        codec->codec_tag = id;

        codec->codec_id = ff_wav_codec_get_id(id, codec->bits_per_coded_sample);

    }

    if (size >= 18) {  /* We're obviously dealing with WAVEFORMATEX */

        int cbSize = avio_rl16(pb); /* cbSize */

        size -= 18;

        cbSize = FFMIN(size, cbSize);

        if (cbSize >= 22 && id == 0xfffe) { /* WAVEFORMATEXTENSIBLE */

            ff_asf_guid subformat;

            codec->bits_per_coded_sample = avio_rl16(pb);

            codec->channel_layout = avio_rl32(pb); /* dwChannelMask */

            ff_get_guid(pb, &subformat);

            if (!memcmp(subformat + 4, (const uint8_t[]){FF_MEDIASUBTYPE_BASE_GUID}, 12)) {

                codec->codec_tag = AV_RL32(subformat);

                codec->codec_id = ff_wav_codec_get_id(codec->codec_tag, codec->bits_per_coded_sample);

            } else {

                codec->codec_id = ff_codec_guid_get_id(ff_codec_wav_guids, subformat);

                if (!codec->codec_id)

                    av_log(codec, AV_LOG_WARNING, "unknown subformat:"FF_PRI_GUID"\n", FF_ARG_GUID(subformat));

            }

            cbSize -= 22;

            size -= 22;

        }

        codec->extradata_size = cbSize;

        if (cbSize > 0) {

            av_free(codec->extradata);

            codec->extradata = av_mallocz(codec->extradata_size + FF_INPUT_BUFFER_PADDING_SIZE);

            if (!codec->extradata)

                return AVERROR(ENOMEM);

            avio_read(pb, codec->extradata, codec->extradata_size);

            size -= cbSize;

        }



        /* It is possible for the chunk to contain garbage at the end */

        if (size > 0)

            avio_skip(pb, size);

    }

    if (codec->codec_id == CODEC_ID_AAC_LATM) {

        /* channels and sample_rate values are those prior to applying SBR and/or PS */

        codec->channels    = 0;

        codec->sample_rate = 0;

    }

    /* override bits_per_coded_sample for G.726 */

    if (codec->codec_id == CODEC_ID_ADPCM_G726)

        codec->bits_per_coded_sample = codec->bit_rate / codec->sample_rate;



    return 0;

}

static int r3d_read_packet(AVFormatContext *s, AVPacket *pkt)

{

    R3DContext *r3d = s->priv_data;

    Atom atom;

    int err = 0;



    while (!err) {

        if (read_atom(s, &atom) < 0) {

            err = -1;

            break;

        }

        switch (atom.tag) {

        case MKTAG('R','E','D','V'):

            if (s->streams[0]->discard == AVDISCARD_ALL)

                goto skip;

            if (!(err = r3d_read_redv(s, pkt, &atom)))

                return 0;

            break;

        case MKTAG('R','E','D','A'):

            if (!r3d->audio_channels)

                return -1;

            if (s->streams[1]->discard == AVDISCARD_ALL)

                goto skip;

            if (!(err = r3d_read_reda(s, pkt, &atom)))

                return 0;

            break;

        default:

        skip:

            avio_skip(s->pb, atom.size-8);

        }

    }

    return err;

}

static int mov_create_timecode_track(AVFormatContext *s, int index, int src_index, const char *tcstr)

{

    int ret;

    MOVMuxContext *mov  = s->priv_data;

    MOVTrack *track     = &mov->tracks[index];

    AVStream *src_st    = s->streams[src_index];

    AVTimecode tc;

    AVPacket pkt    = {.stream_index = index, .flags = AV_PKT_FLAG_KEY, .size = 4};

    AVRational rate = find_fps(s, src_st);



    /* compute the frame number */

    ret = av_timecode_init_from_string(&tc, rate, tcstr, s);

    if (ret < 0)

        return ret;



    /* tmcd track based on video stream */

    track->mode      = mov->mode;

    track->tag       = MKTAG('t','m','c','d');

    track->src_track = src_index;

    track->timescale = mov->tracks[src_index].timescale;

    if (tc.flags & AV_TIMECODE_FLAG_DROPFRAME)

        track->timecode_flags |= MOV_TIMECODE_FLAG_DROPFRAME;



    /* set st to src_st for metadata access*/

    track->st = src_st;



    /* encode context: tmcd data stream */

    track->enc = avcodec_alloc_context3(NULL);



    track->enc->codec_type = AVMEDIA_TYPE_DATA;

    track->enc->codec_tag  = track->tag;

    track->enc->time_base  = av_inv_q(rate);



    /* the tmcd track just contains one packet with the frame number */

    pkt.data = av_malloc(pkt.size);



    AV_WB32(pkt.data, tc.start);

    ret = ff_mov_write_packet(s, &pkt);

    av_free(pkt.data);

    return ret;

}

static int rv40_decode_intra_types(RV34DecContext *r, GetBitContext *gb, int8_t *dst)

{

    MpegEncContext *s = &r->s;

    int i, j, k, v;

    int A, B, C;

    int pattern;

    int8_t *ptr;



    for(i = 0; i < 4; i++, dst += r->intra_types_stride){

        if(!i && s->first_slice_line){

            pattern = get_vlc2(gb, aic_top_vlc.table, AIC_TOP_BITS, 1);

            dst[0] = (pattern >> 2) & 2;

            dst[1] = (pattern >> 1) & 2;

            dst[2] =  pattern       & 2;

            dst[3] = (pattern << 1) & 2;

            continue;

        }

        ptr = dst;

        for(j = 0; j < 4; j++){

            /* Coefficients are read using VLC chosen by the prediction pattern

             * The first one (used for retrieving a pair of coefficients) is

             * constructed from the top, top right and left coefficients

             * The second one (used for retrieving only one coefficient) is

             * top + 10 * left.

             */

            A = ptr[-r->intra_types_stride + 1]; // it won't be used for the last coefficient in a row

            B = ptr[-r->intra_types_stride];

            C = ptr[-1];

            pattern = A + (B << 4) + (C << 8);

            for(k = 0; k < MODE2_PATTERNS_NUM; k++)

                if(pattern == rv40_aic_table_index[k])

                    break;

            if(j < 3 && k < MODE2_PATTERNS_NUM){ //pattern is found, decoding 2 coefficients

                v = get_vlc2(gb, aic_mode2_vlc[k].table, AIC_MODE2_BITS, 2);

                *ptr++ = v/9;

                *ptr++ = v%9;

                j++;

            }else{

                if(B != -1 && C != -1)

                    v = get_vlc2(gb, aic_mode1_vlc[B + C*10].table, AIC_MODE1_BITS, 1);

                else{ // tricky decoding

                    v = 0;

                    switch(C){

                    case -1: // code 0 -> 1, 1 -> 0

                        if(B < 2)

                            v = get_bits1(gb) ^ 1;

                        break;

                    case  0:

                    case  2: // code 0 -> 2, 1 -> 0

                        v = (get_bits1(gb) ^ 1) << 1;

                        break;

                    }

                }

                *ptr++ = v;

            }

        }

    }

    return 0;

}

static int update_wrap_reference(AVFormatContext *s, AVStream *st, int stream_index, AVPacket *pkt)

{

    int64_t ref = pkt->dts;



    if (ref == AV_NOPTS_VALUE)

        ref = pkt->pts;

    if (ref == AV_NOPTS_VALUE)

        return 0;

    ref &= (1LL<<st->pts_wrap_bits)-1;



    if (s->correct_ts_overflow && st->pts_wrap_bits < 63 &&

        st->pts_wrap_reference == AV_NOPTS_VALUE) {

        int i;



        // reference time stamp should be 60 s before first time stamp

        int64_t pts_wrap_reference = ref - av_rescale(60, st->time_base.den, st->time_base.num);

        // if first time stamp is not more than 1/8 and 60s before the wrap point, subtract rather than add wrap offset

        int pts_wrap_behavior = (ref < (1LL<<st->pts_wrap_bits) - (1LL<<st->pts_wrap_bits-3)) ||

            (ref < (1LL<<st->pts_wrap_bits) - av_rescale(60, st->time_base.den, st->time_base.num)) ?

            AV_PTS_WRAP_ADD_OFFSET : AV_PTS_WRAP_SUB_OFFSET;



        AVProgram *first_program = av_find_program_from_stream(s, NULL, stream_index);



        if (!first_program) {

            int default_stream_index = av_find_default_stream_index(s);

            if (s->streams[default_stream_index]->pts_wrap_reference == AV_NOPTS_VALUE) {

                for (i=0; i<s->nb_streams; i++) {

                    s->streams[i]->pts_wrap_reference = pts_wrap_reference;

                    s->streams[i]->pts_wrap_behavior = pts_wrap_behavior;

                }

            }

            else {

                st->pts_wrap_reference = s->streams[default_stream_index]->pts_wrap_reference;

                st->pts_wrap_behavior = s->streams[default_stream_index]->pts_wrap_behavior;

            }

        }

        else {

            AVProgram *program = first_program;

            while (program) {

                if (program->pts_wrap_reference != AV_NOPTS_VALUE) {

                    pts_wrap_reference = program->pts_wrap_reference;

                    pts_wrap_behavior = program->pts_wrap_behavior;

                    break;

                }

                program = av_find_program_from_stream(s, program, stream_index);

            }



            // update every program with differing pts_wrap_reference

            program = first_program;

            while(program) {

                if (program->pts_wrap_reference != pts_wrap_reference) {

                    for (i=0; i<program->nb_stream_indexes; i++) {

                        s->streams[program->stream_index[i]]->pts_wrap_reference = pts_wrap_reference;

                        s->streams[program->stream_index[i]]->pts_wrap_behavior = pts_wrap_behavior;

                    }



                    program->pts_wrap_reference = pts_wrap_reference;

                    program->pts_wrap_behavior = pts_wrap_behavior;

                }

                program = av_find_program_from_stream(s, program, stream_index);

            }

        }

        return 1;

    }

    return 0;

}

