static void vc1_put_signed_blocks_clamped(VC1Context *v)

{

    MpegEncContext *s = &v->s;

    int topleft_mb_pos, top_mb_pos;

    int stride_y, fieldtx;

    int v_dist;



    /* The put pixels loop is always one MB row behind the decoding loop,

     * because we can only put pixels when overlap filtering is done, and

     * for filtering of the bottom edge of a MB, we need the next MB row

     * present as well.

     * Within the row, the put pixels loop is also one MB col behind the

     * decoding loop. The reason for this is again, because for filtering

     * of the right MB edge, we need the next MB present. */

    if (!s->first_slice_line) {

        if (s->mb_x) {

            topleft_mb_pos = (s->mb_y - 1) * s->mb_stride + s->mb_x - 1;

            fieldtx        = v->fieldtx_plane[topleft_mb_pos];

            stride_y       = s->linesize << fieldtx;

            v_dist         = (16 - fieldtx) >> (fieldtx == 0);

            s->dsp.put_signed_pixels_clamped(v->block[v->topleft_blk_idx][0],

                                             s->dest[0] - 16 * s->linesize - 16,

                                             stride_y);

            s->dsp.put_signed_pixels_clamped(v->block[v->topleft_blk_idx][1],

                                             s->dest[0] - 16 * s->linesize - 8,

                                             stride_y);

            s->dsp.put_signed_pixels_clamped(v->block[v->topleft_blk_idx][2],

                                             s->dest[0] - v_dist * s->linesize - 16,

                                             stride_y);

            s->dsp.put_signed_pixels_clamped(v->block[v->topleft_blk_idx][3],

                                             s->dest[0] - v_dist * s->linesize - 8,

                                             stride_y);

            s->dsp.put_signed_pixels_clamped(v->block[v->topleft_blk_idx][4],

                                             s->dest[1] - 8 * s->uvlinesize - 8,

                                             s->uvlinesize);

            s->dsp.put_signed_pixels_clamped(v->block[v->topleft_blk_idx][5],

                                             s->dest[2] - 8 * s->uvlinesize - 8,

                                             s->uvlinesize);

        }

        if (s->mb_x == s->mb_width - 1) {

            top_mb_pos = (s->mb_y - 1) * s->mb_stride + s->mb_x;

            fieldtx    = v->fieldtx_plane[top_mb_pos];

            stride_y   = s->linesize << fieldtx;

            v_dist     = fieldtx ? 15 : 8;

            s->dsp.put_signed_pixels_clamped(v->block[v->top_blk_idx][0],

                                             s->dest[0] - 16 * s->linesize,

                                             stride_y);

            s->dsp.put_signed_pixels_clamped(v->block[v->top_blk_idx][1],

                                             s->dest[0] - 16 * s->linesize + 8,

                                             stride_y);

            s->dsp.put_signed_pixels_clamped(v->block[v->top_blk_idx][2],

                                             s->dest[0] - v_dist * s->linesize,

                                             stride_y);

            s->dsp.put_signed_pixels_clamped(v->block[v->top_blk_idx][3],

                                             s->dest[0] - v_dist * s->linesize + 8,

                                             stride_y);

            s->dsp.put_signed_pixels_clamped(v->block[v->top_blk_idx][4],

                                             s->dest[1] - 8 * s->uvlinesize,

                                             s->uvlinesize);

            s->dsp.put_signed_pixels_clamped(v->block[v->top_blk_idx][5],

                                             s->dest[2] - 8 * s->uvlinesize,

                                             s->uvlinesize);

        }

    }



#define inc_blk_idx(idx) do { \

        idx++; \

        if (idx >= v->n_allocated_blks) \

            idx = 0; \

    } while (0)



    inc_blk_idx(v->topleft_blk_idx);

    inc_blk_idx(v->top_blk_idx);

    inc_blk_idx(v->left_blk_idx);

    inc_blk_idx(v->cur_blk_idx);

}

int ff_h264_get_profile(SPS *sps)

{

    int profile = sps->profile_idc;



    switch (sps->profile_idc) {

    case FF_PROFILE_H264_BASELINE:

        // constraint_set1_flag set to 1

        profile |= (sps->constraint_set_flags & 1 << 1) ? FF_PROFILE_H264_CONSTRAINED : 0;

        break;

    case FF_PROFILE_H264_HIGH_10:

    case FF_PROFILE_H264_HIGH_422:

    case FF_PROFILE_H264_HIGH_444_PREDICTIVE:

        // constraint_set3_flag set to 1

        profile |= (sps->constraint_set_flags & 1 << 3) ? FF_PROFILE_H264_INTRA : 0;

        break;

    }



    return profile;

}

static int decode_iccp_chunk(PNGDecContext *s, int length, AVFrame *f)

{

    int ret, cnt = 0;

    uint8_t *data, profile_name[82];

    AVBPrint bp;

    AVFrameSideData *sd;



    while ((profile_name[cnt++] = bytestream2_get_byte(&s->gb)) && cnt < 81);

    if (cnt > 80) {

        av_log(s->avctx, AV_LOG_ERROR, "iCCP with invalid name!\n");

        return AVERROR_INVALIDDATA;

    }



    length = FFMAX(length - cnt, 0);



    if (bytestream2_get_byte(&s->gb) != 0) {

        av_log(s->avctx, AV_LOG_ERROR, "iCCP with invalid compression!\n");

        return AVERROR_INVALIDDATA;

    }



    length = FFMAX(length - 1, 0);



    if ((ret = decode_zbuf(&bp, s->gb.buffer, s->gb.buffer + length)) < 0)

        return ret;



    av_bprint_finalize(&bp, (char **)&data);





    sd = av_frame_new_side_data(f, AV_FRAME_DATA_ICC_PROFILE, bp.len);

    if (!sd) {

        av_free(data);


    }



    av_dict_set(&sd->metadata, "name", profile_name, 0);

    memcpy(sd->data, data, bp.len);

    av_free(data);



    /* ICC compressed data and CRC */

    bytestream2_skip(&s->gb, length + 4);



    return 0;

}

static int decode_buffering_period(H264Context *h)

{

    unsigned int sps_id;

    int sched_sel_idx;

    SPS *sps;



    sps_id = get_ue_golomb_31(&h->gb);

    if (sps_id > 31 || !h->sps_buffers[sps_id]) {

        av_log(h->avctx, AV_LOG_ERROR,

               "non-existing SPS %d referenced in buffering period\n", sps_id);

        return AVERROR_INVALIDDATA;

    }

    sps = h->sps_buffers[sps_id];



    // NOTE: This is really so duplicated in the standard... See H.264, D.1.1

    if (sps->nal_hrd_parameters_present_flag) {

        for (sched_sel_idx = 0; sched_sel_idx < sps->cpb_cnt; sched_sel_idx++) {

            h->initial_cpb_removal_delay[sched_sel_idx] =

                get_bits(&h->gb, sps->initial_cpb_removal_delay_length);

            // initial_cpb_removal_delay_offset

            skip_bits(&h->gb, sps->initial_cpb_removal_delay_length);

        }

    }

    if (sps->vcl_hrd_parameters_present_flag) {

        for (sched_sel_idx = 0; sched_sel_idx < sps->cpb_cnt; sched_sel_idx++) {

            h->initial_cpb_removal_delay[sched_sel_idx] =

                get_bits(&h->gb, sps->initial_cpb_removal_delay_length);

            // initial_cpb_removal_delay_offset

            skip_bits(&h->gb, sps->initial_cpb_removal_delay_length);

        }

    }



    h->sei_buffering_period_present = 1;

    return 0;

}

static int ism_write_packet(AVFormatContext *s, AVPacket *pkt)

{

    SmoothStreamingContext *c = s->priv_data;

    AVStream *st = s->streams[pkt->stream_index];

    OutputStream *os = &c->streams[pkt->stream_index];

    int64_t end_dts = (c->nb_fragments + 1) * c->min_frag_duration;

    int ret;



    if (st->first_dts == AV_NOPTS_VALUE)

        st->first_dts = pkt->dts;



    if ((!c->has_video || st->codec->codec_type == AVMEDIA_TYPE_VIDEO) &&

        av_compare_ts(pkt->dts - st->first_dts, st->time_base,

                      end_dts, AV_TIME_BASE_Q) >= 0 &&

        pkt->flags & AV_PKT_FLAG_KEY && os->packets_written) {



        if ((ret = ism_flush(s, 0)) < 0)

            return ret;

        c->nb_fragments++;

    }



    os->packets_written++;

    return ff_write_chained(os->ctx, 0, pkt, s);

}

static void avc_luma_midh_qrt_and_aver_dst_4w_msa(const uint8_t *src,

                                                  int32_t src_stride,

                                                  uint8_t *dst,

                                                  int32_t dst_stride,

                                                  int32_t height,

                                                  uint8_t horiz_offset)

{

    uint32_t row;

    v16i8 src0, src1, src2, src3, src4, src5, src6;

    v16u8 dst0, dst1, res;

    v8i16 vt_res0, vt_res1, vt_res2, vt_res3;

    v4i32 hz_res0, hz_res1;

    v8i16 res0, res1;

    v8i16 shf_vec0, shf_vec1, shf_vec2, shf_vec3, shf_vec4, shf_vec5;

    v8i16 mask0 = { 0, 5, 1, 6, 2, 7, 3, 8 };

    v8i16 mask1 = { 1, 4, 2, 5, 3, 6, 4, 7 };

    v8i16 mask2 = { 2, 3, 3, 4, 4, 5, 5, 6 };

    v8i16 minus5h = __msa_ldi_h(-5);

    v8i16 plus20h = __msa_ldi_h(20);

    v8i16 zeros = { 0 };



    LD_SB5(src, src_stride, src0, src1, src2, src3, src4);

    src += (5 * src_stride);



    XORI_B5_128_SB(src0, src1, src2, src3, src4);



    for (row = (height >> 1); row--;) {

        LD_SB2(src, src_stride, src5, src6);

        src += (2 * src_stride);



        XORI_B2_128_SB(src5, src6);

        LD_UB2(dst, dst_stride, dst0, dst1);



        dst0 = (v16u8) __msa_ilvr_w((v4i32) dst1, (v4i32) dst0);



        AVC_CALC_DPADD_B_6PIX_2COEFF_SH(src0, src1, src2, src3, src4, src5,

                                        vt_res0, vt_res1);

        AVC_CALC_DPADD_B_6PIX_2COEFF_SH(src1, src2, src3, src4, src5, src6,

                                        vt_res2, vt_res3);

        VSHF_H3_SH(vt_res0, vt_res1, vt_res0, vt_res1, vt_res0, vt_res1,

                   mask0, mask1, mask2, shf_vec0, shf_vec1, shf_vec2);

        VSHF_H3_SH(vt_res2, vt_res3, vt_res2, vt_res3, vt_res2, vt_res3,

                   mask0, mask1, mask2, shf_vec3, shf_vec4, shf_vec5);



        hz_res0 = __msa_hadd_s_w(shf_vec0, shf_vec0);

        DPADD_SH2_SW(shf_vec1, shf_vec2, minus5h, plus20h, hz_res0, hz_res0);



        hz_res1 = __msa_hadd_s_w(shf_vec3, shf_vec3);

        DPADD_SH2_SW(shf_vec4, shf_vec5, minus5h, plus20h, hz_res1, hz_res1);



        SRARI_W2_SW(hz_res0, hz_res1, 10);

        SAT_SW2_SW(hz_res0, hz_res1, 7);



        res0 = __msa_srari_h(shf_vec2, 5);

        res1 = __msa_srari_h(shf_vec5, 5);



        SAT_SH2_SH(res0, res1, 7);



        if (horiz_offset) {

            res0 = __msa_ilvod_h(zeros, res0);

            res1 = __msa_ilvod_h(zeros, res1);

        } else {

            ILVEV_H2_SH(res0, zeros, res1, zeros, res0, res1);

        }

        hz_res0 = __msa_aver_s_w(hz_res0, (v4i32) res0);

        hz_res1 = __msa_aver_s_w(hz_res1, (v4i32) res1);

        res0 = __msa_pckev_h((v8i16) hz_res1, (v8i16) hz_res0);



        res = PCKEV_XORI128_UB(res0, res0);



        dst0 = __msa_aver_u_b(res, dst0);



        ST4x2_UB(dst0, dst, dst_stride);

        dst += (2 * dst_stride);



        src0 = src2;

        src1 = src3;

        src2 = src4;

        src3 = src5;

        src4 = src6;

    }

}

static int truespeech_decode_frame(AVCodecContext *avctx,

                void *data, int *data_size,

                uint8_t *buf, int buf_size)

{

    TSContext *c = avctx->priv_data;



    int i;

    short *samples = data;

    int consumed = 0;

    int16_t out_buf[240];



    if (!buf_size)

        return 0;



    while (consumed < buf_size) {

        truespeech_read_frame(c, buf + consumed);

        consumed += 32;



        truespeech_correlate_filter(c);

        truespeech_filters_merge(c);



        memset(out_buf, 0, 240 * 2);

        for(i = 0; i < 4; i++) {

            truespeech_apply_twopoint_filter(c, i);

            truespeech_place_pulses(c, out_buf + i * 60, i);

            truespeech_update_filters(c, out_buf + i * 60, i);

            truespeech_synth(c, out_buf + i * 60, i);

        }



        truespeech_save_prevvec(c);



        /* finally output decoded frame */

        for(i = 0; i < 240; i++)

            *samples++ = out_buf[i];



    }



    *data_size = consumed * 15;



    return buf_size;

}

static int gxf_write_trailer(AVFormatContext *s)

{

    GXFContext *gxf = s->priv_data;

    AVIOContext *pb = s->pb;

    int64_t end;

    int i;



    ff_audio_interleave_close(s);



    gxf_write_eos_packet(pb);

    end = avio_tell(pb);

    avio_seek(pb, 0, SEEK_SET);

    /* overwrite map, flt and umf packets with new values */

    gxf_write_map_packet(s, 1);

    gxf_write_flt_packet(s);

    gxf_write_umf_packet(s);

    avio_flush(pb);

    /* update duration in all map packets */

    for (i = 1; i < gxf->map_offsets_nb; i++) {

        avio_seek(pb, gxf->map_offsets[i], SEEK_SET);

        gxf_write_map_packet(s, 1);

        avio_flush(pb);

    }



    avio_seek(pb, end, SEEK_SET);



    av_freep(&gxf->flt_entries);

    av_freep(&gxf->map_offsets);



    return 0;

}

