static int mpegps_probe(AVProbeData *p)

{

    uint32_t code= -1;

    int sys=0, pspack=0, priv1=0, vid=0, audio=0, invalid=0;

    int i;

    int score=0;



    for(i=0; i<p->buf_size; i++){

        code = (code<<8) + p->buf[i];

        if ((code & 0xffffff00) == 0x100) {

            int len= p->buf[i+1] << 8 | p->buf[i+2];

            int pes= check_pes(p->buf+i, p->buf+p->buf_size);



            if(code == SYSTEM_HEADER_START_CODE) sys++;

            else if(code == PACK_START_CODE)     pspack++;

            else if((code & 0xf0) == VIDEO_ID &&  pes) vid++;

            // skip pes payload to avoid start code emulation for private

            // and audio streams

            else if((code & 0xe0) == AUDIO_ID &&  pes) {audio++; i+=len;}

            else if(code == PRIVATE_STREAM_1  &&  pes) {priv1++; i+=len;}



            else if((code & 0xf0) == VIDEO_ID && !pes) invalid++;

            else if((code & 0xe0) == AUDIO_ID && !pes) invalid++;

            else if(code == PRIVATE_STREAM_1  && !pes) invalid++;

        }

    }



    if(vid+audio > invalid)     /* invalid VDR files nd short PES streams */

        score= AVPROBE_SCORE_MAX/4;



//av_log(NULL, AV_LOG_ERROR, "%d %d %d %d %d %d len:%d\n", sys, priv1, pspack,vid, audio, invalid, p->buf_size);

    if(sys>invalid && sys*9 <= pspack*10)

        return pspack > 2 ? AVPROBE_SCORE_MAX/2+2 : AVPROBE_SCORE_MAX/4; // +1 for .mpg

    if(pspack > invalid && (priv1+vid+audio)*10 >= pspack*9)

        return pspack > 2 ? AVPROBE_SCORE_MAX/2+2 : AVPROBE_SCORE_MAX/4; // +1 for .mpg

    if((!!vid ^ !!audio) && (audio > 4 || vid > 1) && !sys && !pspack && p->buf_size>2048 && vid + audio > invalid) /* PES stream */

        return (audio > 12 || vid > 3) ? AVPROBE_SCORE_MAX/2+2 : AVPROBE_SCORE_MAX/4;



    //02-Penguin.flac has sys:0 priv1:0 pspack:0 vid:0 audio:1

    //mp3_misidentified_2.mp3 has sys:0 priv1:0 pspack:0 vid:0 audio:6

    return score;

}

static int64_t http_seek(URLContext *h, int64_t off, int whence)

{

    HTTPContext *s = h->priv_data;

    URLContext *old_hd = s->hd;

    int64_t old_off = s->off;

    uint8_t old_buf[BUFFER_SIZE];

    int old_buf_size;

    AVDictionary *options = NULL;



    if (whence == AVSEEK_SIZE)

        return s->filesize;

    else if ((whence == SEEK_CUR && off == 0) || (whence == SEEK_SET && off == s->off))

        return s->off;

    else if ((s->filesize == -1 && whence == SEEK_END) || h->is_streamed)

        return -1;



    /* we save the old context in case the seek fails */

    old_buf_size = s->buf_end - s->buf_ptr;

    memcpy(old_buf, s->buf_ptr, old_buf_size);

    s->hd = NULL;

    if (whence == SEEK_CUR)

        off += s->off;

    else if (whence == SEEK_END)

        off += s->filesize;

    s->off = off;



    /* if it fails, continue on old connection */

    av_dict_copy(&options, s->chained_options, 0);

    if (http_open_cnx(h, &options) < 0) {

        av_dict_free(&options);

        memcpy(s->buffer, old_buf, old_buf_size);

        s->buf_ptr = s->buffer;

        s->buf_end = s->buffer + old_buf_size;

        s->hd = old_hd;

        s->off = old_off;

        return -1;

    }

    av_dict_free(&options);

    ffurl_close(old_hd);

    return off;

}

static int opus_packet(AVFormatContext *avf, int idx)

{

    struct ogg *ogg              = avf->priv_data;

    struct ogg_stream *os        = &ogg->streams[idx];

    AVStream *st                 = avf->streams[idx];

    struct oggopus_private *priv = os->private;

    uint8_t *packet              = os->buf + os->pstart;



    if (!os->psize)

        return AVERROR_INVALIDDATA;



    if ((!os->lastpts || os->lastpts == AV_NOPTS_VALUE) && !(os->flags & OGG_FLAG_EOS)) {

        int seg, d;

        int duration;

        uint8_t *last_pkt  = os->buf + os->pstart;

        uint8_t *next_pkt  = last_pkt;



        duration = 0;

        seg = os->segp;

        d = opus_duration(last_pkt, os->psize);

        if (d < 0) {

            os->pflags |= AV_PKT_FLAG_CORRUPT;

            return 0;

        }

        duration += d;

        last_pkt = next_pkt =  next_pkt + os->psize;

        for (; seg < os->nsegs; seg++) {

            if (os->segments[seg] < 255) {

                int d = opus_duration(last_pkt, os->segments[seg]);

                if (d < 0) {

                    duration = os->granule;

                    break;

                }

                duration += d;

                last_pkt  = next_pkt + os->segments[seg];

            }

            next_pkt += os->segments[seg];

        }

        os->lastpts                 =

        os->lastdts                 = os->granule - duration;

    }



    os->pduration = opus_duration(packet, os->psize);

    if (os->lastpts != AV_NOPTS_VALUE) {

        if (st->start_time == AV_NOPTS_VALUE)

            st->start_time = os->lastpts;

        priv->cur_dts = os->lastdts = os->lastpts -= priv->pre_skip;

    }



    priv->cur_dts += os->pduration;

    if ((os->flags & OGG_FLAG_EOS)) {

        int64_t skip = priv->cur_dts - os->granule + priv->pre_skip;

        skip = FFMIN(skip, os->pduration);

        if (skip > 0) {

            os->pduration = skip < os->pduration ? os->pduration - skip : 1;

            os->end_trimming = skip;

            av_log(avf, AV_LOG_DEBUG,

                   "Last packet was truncated to %d due to end trimming.\n",

                   os->pduration);

        }

    }



    return 0;

}

static int nsv_read_chunk(AVFormatContext *s, int fill_header)

{

    NSVContext *nsv = s->priv_data;

    AVIOContext *pb = s->pb;

    AVStream *st[2] = {NULL, NULL};

    NSVStream *nst;

    AVPacket *pkt;

    int i, err = 0;

    uint8_t auxcount; /* number of aux metadata, also 4 bits of vsize */

    uint32_t vsize;

    uint16_t asize;

    uint16_t auxsize;



    av_dlog(s, "%s(%d)\n", __FUNCTION__, fill_header);



    if (nsv->ahead[0].data || nsv->ahead[1].data)

        return 0; //-1; /* hey! eat what you've in your plate first! */



null_chunk_retry:

    if (avio_feof(pb))

        return -1;



    for (i = 0; i < NSV_MAX_RESYNC_TRIES && nsv->state < NSV_FOUND_NSVS && !err; i++)

        err = nsv_resync(s);

    if (err < 0)

        return err;

    if (nsv->state == NSV_FOUND_NSVS)

        err = nsv_parse_NSVs_header(s);

    if (err < 0)

        return err;

    if (nsv->state != NSV_HAS_READ_NSVS && nsv->state != NSV_FOUND_BEEF)

        return -1;



    auxcount = avio_r8(pb);

    vsize = avio_rl16(pb);

    asize = avio_rl16(pb);

    vsize = (vsize << 4) | (auxcount >> 4);

    auxcount &= 0x0f;

    av_dlog(s, "NSV CHUNK %d aux, %u bytes video, %d bytes audio\n", auxcount, vsize, asize);

    /* skip aux stuff */

    for (i = 0; i < auxcount; i++) {

        uint32_t av_unused auxtag;

        auxsize = avio_rl16(pb);

        auxtag = avio_rl32(pb);

        av_dlog(s, "NSV aux data: '%c%c%c%c', %d bytes\n",

              (auxtag & 0x0ff),

              ((auxtag >> 8) & 0x0ff),

              ((auxtag >> 16) & 0x0ff),

              ((auxtag >> 24) & 0x0ff),

              auxsize);

        avio_skip(pb, auxsize);

        vsize -= auxsize + sizeof(uint16_t) + sizeof(uint32_t); /* that's becoming braindead */

    }



    if (avio_feof(pb))

        return -1;

    if (!vsize && !asize) {

        nsv->state = NSV_UNSYNC;

        goto null_chunk_retry;

    }



    /* map back streams to v,a */

    if (s->nb_streams > 0)

        st[s->streams[0]->id] = s->streams[0];

    if (s->nb_streams > 1)

        st[s->streams[1]->id] = s->streams[1];



    if (vsize && st[NSV_ST_VIDEO]) {

        int ret;

        nst = st[NSV_ST_VIDEO]->priv_data;

        pkt = &nsv->ahead[NSV_ST_VIDEO];

        if ((ret = av_get_packet(pb, pkt, vsize)) < 0)

            return ret;

        pkt->stream_index = st[NSV_ST_VIDEO]->index;//NSV_ST_VIDEO;

        pkt->dts = nst->frame_offset;

        pkt->flags |= nsv->state == NSV_HAS_READ_NSVS ? AV_PKT_FLAG_KEY : 0; /* keyframe only likely on a sync frame */

        for (i = 0; i < FFMIN(8, vsize); i++)

            av_dlog(s, "NSV video: [%d] = %02x\n", i, pkt->data[i]);

    }

    if(st[NSV_ST_VIDEO])

        ((NSVStream*)st[NSV_ST_VIDEO]->priv_data)->frame_offset++;



    if (asize && st[NSV_ST_AUDIO]) {

        nst = st[NSV_ST_AUDIO]->priv_data;

        pkt = &nsv->ahead[NSV_ST_AUDIO];

        /* read raw audio specific header on the first audio chunk... */

        /* on ALL audio chunks ?? seems so! */

        if (asize && st[NSV_ST_AUDIO]->codec->codec_tag == MKTAG('P', 'C', 'M', ' ')/* && fill_header*/) {

            uint8_t bps;

            uint8_t channels;

            uint16_t samplerate;

            bps = avio_r8(pb);

            channels = avio_r8(pb);

            samplerate = avio_rl16(pb);

            asize-=4;

            av_dlog(s, "NSV RAWAUDIO: bps %d, nchan %d, srate %d\n", bps, channels, samplerate);

            if (fill_header) {

                st[NSV_ST_AUDIO]->need_parsing = AVSTREAM_PARSE_NONE; /* we know everything */

                if (bps != 16) {

                    av_dlog(s, "NSV AUDIO bit/sample != 16 (%d)!!!\n", bps);

                }

                if(channels)

                    bps /= channels; // ???

                else

                    av_log(s, AV_LOG_WARNING, "Channels is 0\n");

                if (bps == 8)

                    st[NSV_ST_AUDIO]->codec->codec_id = AV_CODEC_ID_PCM_U8;

                samplerate /= 4;/* UGH ??? XXX */

                channels = 1;

                st[NSV_ST_AUDIO]->codec->channels = channels;

                st[NSV_ST_AUDIO]->codec->sample_rate = samplerate;

                av_dlog(s, "NSV RAWAUDIO: bps %d, nchan %d, srate %d\n", bps, channels, samplerate);

            }

        }

        av_get_packet(pb, pkt, asize);

        pkt->stream_index = st[NSV_ST_AUDIO]->index;//NSV_ST_AUDIO;

        pkt->flags |= nsv->state == NSV_HAS_READ_NSVS ? AV_PKT_FLAG_KEY : 0; /* keyframe only likely on a sync frame */

        if( nsv->state == NSV_HAS_READ_NSVS && st[NSV_ST_VIDEO] ) {

            /* on a nsvs frame we have new information on a/v sync */

            pkt->dts = (((NSVStream*)st[NSV_ST_VIDEO]->priv_data)->frame_offset-1);

            pkt->dts *= (int64_t)1000        * nsv->framerate.den;

            pkt->dts += (int64_t)nsv->avsync * nsv->framerate.num;

            av_dlog(s, "NSV AUDIO: sync:%d, dts:%"PRId64, nsv->avsync, pkt->dts);

        }

        nst->frame_offset++;

    }



    nsv->state = NSV_UNSYNC;

    return 0;

}

static int decode_slice(MpegEncContext *s){

    const int part_mask= s->partitioned_frame ? (ER_AC_END|ER_AC_ERROR) : 0x7F;

    const int mb_size= 16>>s->avctx->lowres;

    int ret;



    s->last_resync_gb= s->gb;

    s->first_slice_line= 1;



    s->resync_mb_x= s->mb_x;

    s->resync_mb_y= s->mb_y;



    ff_set_qscale(s, s->qscale);



    if (s->avctx->hwaccel) {

        const uint8_t *start= s->gb.buffer + get_bits_count(&s->gb)/8;

        const uint8_t *end  = ff_h263_find_resync_marker(start + 1, s->gb.buffer_end);

        skip_bits_long(&s->gb, 8*(end - start));

        return s->avctx->hwaccel->decode_slice(s->avctx, start, end - start);

    }



    if(s->partitioned_frame){

        const int qscale= s->qscale;



        if(CONFIG_MPEG4_DECODER && s->codec_id==AV_CODEC_ID_MPEG4){

            if ((ret = ff_mpeg4_decode_partitions(s)) < 0)

                return ret;

        }



        /* restore variables which were modified */

        s->first_slice_line=1;

        s->mb_x= s->resync_mb_x;

        s->mb_y= s->resync_mb_y;

        ff_set_qscale(s, qscale);

    }



    for(; s->mb_y < s->mb_height; s->mb_y++) {

        /* per-row end of slice checks */

        if(s->msmpeg4_version){

            if(s->resync_mb_y + s->slice_height == s->mb_y){

                ff_er_add_slice(s, s->resync_mb_x, s->resync_mb_y, s->mb_x-1, s->mb_y, ER_MB_END);



                return 0;

            }

        }



        if(s->msmpeg4_version==1){

            s->last_dc[0]=

            s->last_dc[1]=

            s->last_dc[2]= 128;

        }



        ff_init_block_index(s);

        for(; s->mb_x < s->mb_width; s->mb_x++) {

            int ret;



            ff_update_block_index(s);



            if(s->resync_mb_x == s->mb_x && s->resync_mb_y+1 == s->mb_y){

                s->first_slice_line=0;

            }



            /* DCT & quantize */



            s->mv_dir = MV_DIR_FORWARD;

            s->mv_type = MV_TYPE_16X16;

//            s->mb_skipped = 0;

            av_dlog(s, "%d %d %06X\n",

                    ret, get_bits_count(&s->gb), show_bits(&s->gb, 24));

            ret= s->decode_mb(s, s->block);



            if (s->pict_type!=AV_PICTURE_TYPE_B)

                ff_h263_update_motion_val(s);



            if(ret<0){

                const int xy= s->mb_x + s->mb_y*s->mb_stride;

                if(ret==SLICE_END){

                    ff_MPV_decode_mb(s, s->block);

                    if(s->loop_filter)

                        ff_h263_loop_filter(s);



                    ff_er_add_slice(s, s->resync_mb_x, s->resync_mb_y, s->mb_x, s->mb_y, ER_MB_END&part_mask);



                    s->padding_bug_score--;



                    if(++s->mb_x >= s->mb_width){

                        s->mb_x=0;

                        ff_draw_horiz_band(s, s->mb_y*mb_size, mb_size);

                        ff_MPV_report_decode_progress(s);

                        s->mb_y++;

                    }

                    return 0;

                }else if(ret==SLICE_NOEND){

                    av_log(s->avctx, AV_LOG_ERROR, "Slice mismatch at MB: %d\n", xy);

                    ff_er_add_slice(s, s->resync_mb_x, s->resync_mb_y, s->mb_x+1, s->mb_y, ER_MB_END&part_mask);

                    return AVERROR_INVALIDDATA;

                }

                av_log(s->avctx, AV_LOG_ERROR, "Error at MB: %d\n", xy);

                ff_er_add_slice(s, s->resync_mb_x, s->resync_mb_y, s->mb_x, s->mb_y, ER_MB_ERROR&part_mask);



                return AVERROR_INVALIDDATA;

            }



            ff_MPV_decode_mb(s, s->block);

            if(s->loop_filter)

                ff_h263_loop_filter(s);

        }



        ff_draw_horiz_band(s, s->mb_y*mb_size, mb_size);

        ff_MPV_report_decode_progress(s);



        s->mb_x= 0;

    }



    assert(s->mb_x==0 && s->mb_y==s->mb_height);



    if(s->codec_id==AV_CODEC_ID_MPEG4

       && (s->workaround_bugs&FF_BUG_AUTODETECT)

       && get_bits_left(&s->gb) >= 48

       && show_bits(&s->gb, 24)==0x4010

       && !s->data_partitioning)

        s->padding_bug_score+=32;



    /* try to detect the padding bug */

    if(      s->codec_id==AV_CODEC_ID_MPEG4

       &&   (s->workaround_bugs&FF_BUG_AUTODETECT)

       &&    get_bits_left(&s->gb) >=0

       &&    get_bits_left(&s->gb) < 137

//       &&   !s->resync_marker

       &&   !s->data_partitioning){



        const int bits_count= get_bits_count(&s->gb);

        const int bits_left = s->gb.size_in_bits - bits_count;



        if(bits_left==0){

            s->padding_bug_score+=16;

        } else if(bits_left != 1){

            int v= show_bits(&s->gb, 8);

            v|= 0x7F >> (7-(bits_count&7));



            if(v==0x7F && bits_left<=8)

                s->padding_bug_score--;

            else if(v==0x7F && ((get_bits_count(&s->gb)+8)&8) && bits_left<=16)

                s->padding_bug_score+= 4;

            else

                s->padding_bug_score++;

        }

    }



    if(s->workaround_bugs&FF_BUG_AUTODETECT){

        if(s->padding_bug_score > -2 && !s->data_partitioning /*&& (s->divx_version>=0 || !s->resync_marker)*/)

            s->workaround_bugs |=  FF_BUG_NO_PADDING;

        else

            s->workaround_bugs &= ~FF_BUG_NO_PADDING;

    }



    // handle formats which don't have unique end markers

    if(s->msmpeg4_version || (s->workaround_bugs&FF_BUG_NO_PADDING)){ //FIXME perhaps solve this more cleanly

        int left= get_bits_left(&s->gb);

        int max_extra=7;



        /* no markers in M$ crap */

        if(s->msmpeg4_version && s->pict_type==AV_PICTURE_TYPE_I)

            max_extra+= 17;



        /* buggy padding but the frame should still end approximately at the bitstream end */

        if((s->workaround_bugs&FF_BUG_NO_PADDING) && (s->err_recognition&(AV_EF_BUFFER|AV_EF_AGGRESSIVE)))

            max_extra+= 48;

        else if((s->workaround_bugs&FF_BUG_NO_PADDING))

            max_extra+= 256*256*256*64;



        if(left>max_extra){

            av_log(s->avctx, AV_LOG_ERROR, "discarding %d junk bits at end, next would be %X\n", left, show_bits(&s->gb, 24));

        }

        else if(left<0){

            av_log(s->avctx, AV_LOG_ERROR, "overreading %d bits\n", -left);

        }else

            ff_er_add_slice(s, s->resync_mb_x, s->resync_mb_y, s->mb_x-1, s->mb_y, ER_MB_END);



        return 0;

    }



    av_log(s->avctx, AV_LOG_ERROR, "slice end not reached but screenspace end (%d left %06X, score= %d)\n",

            get_bits_left(&s->gb),

            show_bits(&s->gb, 24), s->padding_bug_score);



    ff_er_add_slice(s, s->resync_mb_x, s->resync_mb_y, s->mb_x, s->mb_y, ER_MB_END&part_mask);



    return AVERROR_INVALIDDATA;

}

static void get_fcb_param(FCBParam *optim, int16_t *impulse_resp,

                          int16_t *buf, int pulse_cnt, int pitch_lag)

{

    FCBParam param;

    int16_t impulse_r[SUBFRAME_LEN];

    int16_t temp_corr[SUBFRAME_LEN];

    int16_t impulse_corr[SUBFRAME_LEN];



    int ccr1[SUBFRAME_LEN];

    int ccr2[SUBFRAME_LEN];

    int amp, err, max, max_amp_index, min, scale, i, j, k, l;



    int64_t temp;



    /* Update impulse response */

    memcpy(impulse_r, impulse_resp, sizeof(int16_t) * SUBFRAME_LEN);

    param.dirac_train = 0;

    if (pitch_lag < SUBFRAME_LEN - 2) {

        param.dirac_train = 1;

        gen_dirac_train(impulse_r, pitch_lag);

    }



    for (i = 0; i < SUBFRAME_LEN; i++)

        temp_corr[i] = impulse_r[i] >> 1;



    /* Compute impulse response autocorrelation */

    temp = dot_product(temp_corr, temp_corr, SUBFRAME_LEN);



    scale = normalize_bits_int32(temp);

    impulse_corr[0] = av_clipl_int32((temp << scale) + (1 << 15)) >> 16;



    for (i = 1; i < SUBFRAME_LEN; i++) {

        temp = dot_product(temp_corr + i, temp_corr, SUBFRAME_LEN - i);

        impulse_corr[i] = av_clipl_int32((temp << scale) + (1 << 15)) >> 16;

    }



    /* Compute crosscorrelation of impulse response with residual signal */

    scale -= 4;

    for (i = 0; i < SUBFRAME_LEN; i++){

        temp = dot_product(buf + i, impulse_r, SUBFRAME_LEN - i);

        if (scale < 0)

            ccr1[i] = temp >> -scale;

        else

            ccr1[i] = av_clipl_int32(temp << scale);

    }



    /* Search loop */

    for (i = 0; i < GRID_SIZE; i++) {

        /* Maximize the crosscorrelation */

        max = 0;

        for (j = i; j < SUBFRAME_LEN; j += GRID_SIZE) {

            temp = FFABS(ccr1[j]);

            if (temp >= max) {

                max = temp;

                param.pulse_pos[0] = j;

            }

        }



        /* Quantize the gain (max crosscorrelation/impulse_corr[0]) */

        amp = max;

        min = 1 << 30;

        max_amp_index = GAIN_LEVELS - 2;

        for (j = max_amp_index; j >= 2; j--) {

            temp = av_clipl_int32((int64_t)fixed_cb_gain[j] *

                                  impulse_corr[0] << 1);

            temp = FFABS(temp - amp);

            if (temp < min) {

                min = temp;

                max_amp_index = j;

            }

        }



        max_amp_index--;

        /* Select additional gain values */

        for (j = 1; j < 5; j++) {

            for (k = i; k < SUBFRAME_LEN; k += GRID_SIZE) {

                temp_corr[k] = 0;

                ccr2[k]      = ccr1[k];

            }

            param.amp_index = max_amp_index + j - 2;

            amp = fixed_cb_gain[param.amp_index];



            param.pulse_sign[0] = (ccr2[param.pulse_pos[0]] < 0) ? -amp : amp;

            temp_corr[param.pulse_pos[0]] = 1;



            for (k = 1; k < pulse_cnt; k++) {

                max = -1 << 30;

                for (l = i; l < SUBFRAME_LEN; l += GRID_SIZE) {

                    if (temp_corr[l])

                        continue;

                    temp = impulse_corr[FFABS(l - param.pulse_pos[k - 1])];

                    temp = av_clipl_int32((int64_t)temp *

                                          param.pulse_sign[k - 1] << 1);

                    ccr2[l] -= temp;

                    temp = FFABS(ccr2[l]);

                    if (temp > max) {

                        max = temp;

                        param.pulse_pos[k] = l;

                    }

                }



                param.pulse_sign[k] = (ccr2[param.pulse_pos[k]] < 0) ?

                                      -amp : amp;

                temp_corr[param.pulse_pos[k]] = 1;

            }



            /* Create the error vector */

            memset(temp_corr, 0, sizeof(int16_t) * SUBFRAME_LEN);



            for (k = 0; k < pulse_cnt; k++)

                temp_corr[param.pulse_pos[k]] = param.pulse_sign[k];



            for (k = SUBFRAME_LEN - 1; k >= 0; k--) {

                temp = 0;

                for (l = 0; l <= k; l++) {

                    int prod = av_clipl_int32((int64_t)temp_corr[l] *

                                              impulse_r[k - l] << 1);

                    temp     = av_clipl_int32(temp + prod);

                }

                temp_corr[k] = temp << 2 >> 16;

            }



            /* Compute square of error */

            err = 0;

            for (k = 0; k < SUBFRAME_LEN; k++) {

                int64_t prod;

                prod = av_clipl_int32((int64_t)buf[k] * temp_corr[k] << 1);

                err  = av_clipl_int32(err - prod);

                prod = av_clipl_int32((int64_t)temp_corr[k] * temp_corr[k]);

                err  = av_clipl_int32(err + prod);

            }



            /* Minimize */

            if (err < optim->min_err) {

                optim->min_err     = err;

                optim->grid_index  = i;

                optim->amp_index   = param.amp_index;

                optim->dirac_train = param.dirac_train;



                for (k = 0; k < pulse_cnt; k++) {

                    optim->pulse_sign[k] = param.pulse_sign[k];

                    optim->pulse_pos[k]  = param.pulse_pos[k];

                }

            }

        }

    }

}

static int vp9_decode_update_thread_context(AVCodecContext *dst, const AVCodecContext *src)

{

    int i, res;

    VP9Context *s = dst->priv_data, *ssrc = src->priv_data;



    // FIXME scalability, size, etc.



    for (i = 0; i < 2; i++) {

        if (s->frames[i].tf.f->data[0])

            vp9_unref_frame(dst, &s->frames[i]);

        if (ssrc->frames[i].tf.f->data[0]) {

            if ((res = vp9_ref_frame(dst, &s->frames[i], &ssrc->frames[i])) < 0)

                return res;

        }

    }

    for (i = 0; i < 8; i++) {

        if (s->refs[i].f->data[0])

            ff_thread_release_buffer(dst, &s->refs[i]);

        if (ssrc->next_refs[i].f->data[0]) {

            if ((res = ff_thread_ref_frame(&s->refs[i], &ssrc->next_refs[i])) < 0)

                return res;

        }

    }



    s->invisible = ssrc->invisible;

    s->keyframe = ssrc->keyframe;

    s->uses_2pass = ssrc->uses_2pass;

    memcpy(&s->prob_ctx, &ssrc->prob_ctx, sizeof(s->prob_ctx));

    memcpy(&s->lf_delta, &ssrc->lf_delta, sizeof(s->lf_delta));

    if (ssrc->segmentation.enabled) {

        memcpy(&s->segmentation.feat, &ssrc->segmentation.feat,

               sizeof(s->segmentation.feat));

    }



    return 0;

}

static inline int h263_mv4_search(MpegEncContext *s, int mx, int my, int shift)

{

    MotionEstContext * const c= &s->me;

    const int size= 1;

    const int h=8;

    int block;

    int P[10][2];

    int dmin_sum=0, mx4_sum=0, my4_sum=0;

    int same=1;

    const int stride= c->stride;

    uint8_t *mv_penalty= c->current_mv_penalty;



    init_mv4_ref(c);



    for(block=0; block<4; block++){

        int mx4, my4;

        int pred_x4, pred_y4;

        int dmin4;

        static const int off[4]= {2, 1, 1, -1};

        const int mot_stride = s->b8_stride;

        const int mot_xy = s->block_index[block];



        P_LEFT[0] = s->current_picture.motion_val[0][mot_xy - 1][0];

        P_LEFT[1] = s->current_picture.motion_val[0][mot_xy - 1][1];



        if(P_LEFT[0]       > (c->xmax<<shift)) P_LEFT[0]       = (c->xmax<<shift);



        /* special case for first line */

        if (s->first_slice_line && block<2) {

            c->pred_x= pred_x4= P_LEFT[0];

            c->pred_y= pred_y4= P_LEFT[1];

        } else {

            P_TOP[0]      = s->current_picture.motion_val[0][mot_xy - mot_stride             ][0];

            P_TOP[1]      = s->current_picture.motion_val[0][mot_xy - mot_stride             ][1];

            P_TOPRIGHT[0] = s->current_picture.motion_val[0][mot_xy - mot_stride + off[block]][0];

            P_TOPRIGHT[1] = s->current_picture.motion_val[0][mot_xy - mot_stride + off[block]][1];

            if(P_TOP[1]      > (c->ymax<<shift)) P_TOP[1]     = (c->ymax<<shift);

            if(P_TOPRIGHT[0] < (c->xmin<<shift)) P_TOPRIGHT[0]= (c->xmin<<shift);

            if(P_TOPRIGHT[0] > (c->xmax<<shift)) P_TOPRIGHT[0]= (c->xmax<<shift);

            if(P_TOPRIGHT[1] > (c->ymax<<shift)) P_TOPRIGHT[1]= (c->ymax<<shift);



            P_MEDIAN[0]= mid_pred(P_LEFT[0], P_TOP[0], P_TOPRIGHT[0]);

            P_MEDIAN[1]= mid_pred(P_LEFT[1], P_TOP[1], P_TOPRIGHT[1]);



            c->pred_x= pred_x4 = P_MEDIAN[0];

            c->pred_y= pred_y4 = P_MEDIAN[1];

        }

        P_MV1[0]= mx;

        P_MV1[1]= my;



        dmin4 = epzs_motion_search4(s, &mx4, &my4, P, block, block, s->p_mv_table, (1<<16)>>shift);



        dmin4= c->sub_motion_search(s, &mx4, &my4, dmin4, block, block, size, h);



        if(s->dsp.me_sub_cmp[0] != s->dsp.mb_cmp[0]){

            int dxy;

            const int offset= ((block&1) + (block>>1)*stride)*8;

            uint8_t *dest_y = c->scratchpad + offset;

            if(s->quarter_sample){

                uint8_t *ref= c->ref[block][0] + (mx4>>2) + (my4>>2)*stride;

                dxy = ((my4 & 3) << 2) | (mx4 & 3);



                if(s->no_rounding)

                    s->dsp.put_no_rnd_qpel_pixels_tab[1][dxy](dest_y   , ref    , stride);

                else

                    s->dsp.put_qpel_pixels_tab       [1][dxy](dest_y   , ref    , stride);

            }else{

                uint8_t *ref= c->ref[block][0] + (mx4>>1) + (my4>>1)*stride;

                dxy = ((my4 & 1) << 1) | (mx4 & 1);



                if(s->no_rounding)

                    s->hdsp.put_no_rnd_pixels_tab[1][dxy](dest_y    , ref    , stride, h);

                else

                    s->hdsp.put_pixels_tab       [1][dxy](dest_y    , ref    , stride, h);

            }

            dmin_sum+= (mv_penalty[mx4-pred_x4] + mv_penalty[my4-pred_y4])*c->mb_penalty_factor;

        }else

            dmin_sum+= dmin4;



        if(s->quarter_sample){

            mx4_sum+= mx4/2;

            my4_sum+= my4/2;

        }else{

            mx4_sum+= mx4;

            my4_sum+= my4;

        }



        s->current_picture.motion_val[0][s->block_index[block]][0] = mx4;

        s->current_picture.motion_val[0][s->block_index[block]][1] = my4;



        if(mx4 != mx || my4 != my) same=0;

    }



    if(same)

        return INT_MAX;



    if(s->dsp.me_sub_cmp[0] != s->dsp.mb_cmp[0]){

        dmin_sum += s->dsp.mb_cmp[0](s, s->new_picture.f.data[0] + s->mb_x*16 + s->mb_y*16*stride, c->scratchpad, stride, 16);

    }



    if(c->avctx->mb_cmp&FF_CMP_CHROMA){

        int dxy;

        int mx, my;

        int offset;



        mx= ff_h263_round_chroma(mx4_sum);

        my= ff_h263_round_chroma(my4_sum);

        dxy = ((my & 1) << 1) | (mx & 1);



        offset= (s->mb_x*8 + (mx>>1)) + (s->mb_y*8 + (my>>1))*s->uvlinesize;



        if(s->no_rounding){

            s->hdsp.put_no_rnd_pixels_tab[1][dxy](c->scratchpad    , s->last_picture.f.data[1] + offset, s->uvlinesize, 8);

            s->hdsp.put_no_rnd_pixels_tab[1][dxy](c->scratchpad + 8, s->last_picture.f.data[2] + offset, s->uvlinesize, 8);

        }else{

            s->hdsp.put_pixels_tab       [1][dxy](c->scratchpad    , s->last_picture.f.data[1] + offset, s->uvlinesize, 8);

            s->hdsp.put_pixels_tab       [1][dxy](c->scratchpad + 8, s->last_picture.f.data[2] + offset, s->uvlinesize, 8);

        }



        dmin_sum += s->dsp.mb_cmp[1](s, s->new_picture.f.data[1] + s->mb_x*8 + s->mb_y*8*s->uvlinesize, c->scratchpad  , s->uvlinesize, 8);

        dmin_sum += s->dsp.mb_cmp[1](s, s->new_picture.f.data[2] + s->mb_x*8 + s->mb_y*8*s->uvlinesize, c->scratchpad+8, s->uvlinesize, 8);

    }



    c->pred_x= mx;

    c->pred_y= my;



    switch(c->avctx->mb_cmp&0xFF){

    /*case FF_CMP_SSE:

        return dmin_sum+ 32*s->qscale*s->qscale;*/

    case FF_CMP_RD:

        return dmin_sum;

    default:

        return dmin_sum+ 11*c->mb_penalty_factor;

    }

}

static int url_alloc_for_protocol(URLContext **puc, struct URLProtocol *up,

                                  const char *filename, int flags,

                                  const AVIOInterruptCB *int_cb)

{

    URLContext *uc;

    int err;



#if CONFIG_NETWORK

    if (up->flags & URL_PROTOCOL_FLAG_NETWORK && !ff_network_init())

        return AVERROR(EIO);

#endif

    uc = av_mallocz(sizeof(URLContext) + strlen(filename) + 1);

    if (!uc) {

        err = AVERROR(ENOMEM);

        goto fail;

    }

    uc->av_class = &ffurl_context_class;

    uc->filename = (char *)&uc[1];

    strcpy(uc->filename, filename);

    uc->prot            = up;

    uc->flags           = flags;

    uc->is_streamed     = 0; /* default = not streamed */

    uc->max_packet_size = 0; /* default: stream file */

    if (up->priv_data_size) {

        uc->priv_data = av_mallocz(up->priv_data_size);

        if (!uc->priv_data) {

            err = AVERROR(ENOMEM);

            goto fail;

        }

        if (up->priv_data_class) {

            *(const AVClass **)uc->priv_data = up->priv_data_class;

            av_opt_set_defaults(uc->priv_data);

        }

    }

    if (int_cb)

        uc->interrupt_callback = *int_cb;



    *puc = uc;

    return 0;

fail:

    *puc = NULL;

    if (uc)

        av_freep(&uc->priv_data);

    av_freep(&uc);

#if CONFIG_NETWORK

    if (up->flags & URL_PROTOCOL_FLAG_NETWORK)

        ff_network_close();

#endif

    return err;

}

static int rv10_decode_packet(AVCodecContext *avctx, const uint8_t *buf,

                              int buf_size, int buf_size2)

{

    RVDecContext *rv = avctx->priv_data;

    MpegEncContext *s = &rv->m;

    int mb_count, mb_pos, left, start_mb_x, active_bits_size, ret;



    active_bits_size = buf_size * 8;

    init_get_bits(&s->gb, buf, FFMAX(buf_size, buf_size2) * 8);

    if (s->codec_id == AV_CODEC_ID_RV10)

        mb_count = rv10_decode_picture_header(s);

    else

        mb_count = rv20_decode_picture_header(rv);

    if (mb_count < 0) {

        av_log(s->avctx, AV_LOG_ERROR, "HEADER ERROR\n");

        return AVERROR_INVALIDDATA;

    }



    if (s->mb_x >= s->mb_width ||

        s->mb_y >= s->mb_height) {

        av_log(s->avctx, AV_LOG_ERROR, "POS ERROR %d %d\n", s->mb_x, s->mb_y);

        return AVERROR_INVALIDDATA;

    }

    mb_pos = s->mb_y * s->mb_width + s->mb_x;

    left   = s->mb_width * s->mb_height - mb_pos;

    if (mb_count > left) {

        av_log(s->avctx, AV_LOG_ERROR, "COUNT ERROR\n");

        return AVERROR_INVALIDDATA;

    }



    if ((s->mb_x == 0 && s->mb_y == 0) || s->current_picture_ptr == NULL) {

        // FIXME write parser so we always have complete frames?

        if (s->current_picture_ptr) {

            ff_er_frame_end(&s->er);

            ff_mpv_frame_end(s);

            s->mb_x = s->mb_y = s->resync_mb_x = s->resync_mb_y = 0;

        }

        if ((ret = ff_mpv_frame_start(s, avctx)) < 0)

            return ret;

        ff_mpeg_er_frame_start(s);

    } else {

        if (s->current_picture_ptr->f->pict_type != s->pict_type) {

            av_log(s->avctx, AV_LOG_ERROR, "Slice type mismatch\n");

            return AVERROR_INVALIDDATA;

        }

    }



    av_dlog(avctx, "qscale=%d\n", s->qscale);



    /* default quantization values */

    if (s->codec_id == AV_CODEC_ID_RV10) {

        if (s->mb_y == 0)

            s->first_slice_line = 1;

    } else {

        s->first_slice_line = 1;

        s->resync_mb_x      = s->mb_x;

    }

    start_mb_x     = s->mb_x;

    s->resync_mb_y = s->mb_y;

    if (s->h263_aic) {

        s->y_dc_scale_table =

        s->c_dc_scale_table = ff_aic_dc_scale_table;

    } else {

        s->y_dc_scale_table =

        s->c_dc_scale_table = ff_mpeg1_dc_scale_table;

    }



    if (s->modified_quant)

        s->chroma_qscale_table = ff_h263_chroma_qscale_table;



    ff_set_qscale(s, s->qscale);



    s->rv10_first_dc_coded[0] = 0;

    s->rv10_first_dc_coded[1] = 0;

    s->rv10_first_dc_coded[2] = 0;

    s->block_wrap[0] =

    s->block_wrap[1] =

    s->block_wrap[2] =

    s->block_wrap[3] = s->b8_stride;

    s->block_wrap[4] =

    s->block_wrap[5] = s->mb_stride;

    ff_init_block_index(s);



    /* decode each macroblock */

    for (s->mb_num_left = mb_count; s->mb_num_left > 0; s->mb_num_left--) {

        int ret;

        ff_update_block_index(s);

        av_dlog(avctx, "**mb x=%d y=%d\n", s->mb_x, s->mb_y);



        s->mv_dir  = MV_DIR_FORWARD;

        s->mv_type = MV_TYPE_16X16;

        ret = ff_h263_decode_mb(s, s->block);



        // Repeat the slice end check from ff_h263_decode_mb with our active

        // bitstream size

        if (ret != SLICE_ERROR) {

            int v = show_bits(&s->gb, 16);



            if (get_bits_count(&s->gb) + 16 > active_bits_size)

                v >>= get_bits_count(&s->gb) + 16 - active_bits_size;



            if (!v)

                ret = SLICE_END;

        }

        if (ret != SLICE_ERROR && active_bits_size < get_bits_count(&s->gb) &&

            8 * buf_size2 >= get_bits_count(&s->gb)) {

            active_bits_size = buf_size2 * 8;

            av_log(avctx, AV_LOG_DEBUG, "update size from %d to %d\n",

                   8 * buf_size, active_bits_size);

            ret = SLICE_OK;

        }



        if (ret == SLICE_ERROR || active_bits_size < get_bits_count(&s->gb)) {

            av_log(s->avctx, AV_LOG_ERROR, "ERROR at MB %d %d\n", s->mb_x,

                   s->mb_y);

            return AVERROR_INVALIDDATA;

        }

        if (s->pict_type != AV_PICTURE_TYPE_B)

            ff_h263_update_motion_val(s);

        ff_mpv_decode_mb(s, s->block);

        if (s->loop_filter)

            ff_h263_loop_filter(s);



        if (++s->mb_x == s->mb_width) {

            s->mb_x = 0;

            s->mb_y++;

            ff_init_block_index(s);

        }

        if (s->mb_x == s->resync_mb_x)

            s->first_slice_line = 0;

        if (ret == SLICE_END)

            break;

    }



    ff_er_add_slice(&s->er, start_mb_x, s->resync_mb_y, s->mb_x - 1, s->mb_y,

                    ER_MB_END);



    return active_bits_size;

}

static int parse_pixel_format(AVCodecContext *avctx)

{

    DDSContext *ctx = avctx->priv_data;

    GetByteContext *gbc = &ctx->gbc;

    char buf[32];

    uint32_t flags, fourcc, gimp_tag;

    enum DDSDXGIFormat dxgi;

    int size, bpp, r, g, b, a;

    int alpha_exponent, ycocg_classic, ycocg_scaled, normal_map, array;



    /* Alternative DDS implementations use reserved1 as custom header. */

    bytestream2_skip(gbc, 4 * 3);

    gimp_tag = bytestream2_get_le32(gbc);

    alpha_exponent = gimp_tag == MKTAG('A', 'E', 'X', 'P');

    ycocg_classic  = gimp_tag == MKTAG('Y', 'C', 'G', '1');

    ycocg_scaled   = gimp_tag == MKTAG('Y', 'C', 'G', '2');

    bytestream2_skip(gbc, 4 * 7);



    /* Now the real DDPF starts. */

    size = bytestream2_get_le32(gbc);

    if (size != 32) {

        av_log(avctx, AV_LOG_ERROR, "Invalid pixel format header %d.\n", size);

        return AVERROR_INVALIDDATA;

    }

    flags = bytestream2_get_le32(gbc);

    ctx->compressed = flags & DDPF_FOURCC;

    ctx->paletted   = flags & DDPF_PALETTE;

    normal_map      = flags & DDPF_NORMALMAP;

    fourcc = bytestream2_get_le32(gbc);



    if (ctx->compressed && ctx->paletted) {

        av_log(avctx, AV_LOG_WARNING,

               "Disabling invalid palette flag for compressed dds.\n");

        ctx->paletted = 0;

    }



    bpp = bytestream2_get_le32(gbc); // rgbbitcount

    r   = bytestream2_get_le32(gbc); // rbitmask

    g   = bytestream2_get_le32(gbc); // gbitmask

    b   = bytestream2_get_le32(gbc); // bbitmask

    a   = bytestream2_get_le32(gbc); // abitmask



    bytestream2_skip(gbc, 4); // caps

    bytestream2_skip(gbc, 4); // caps2

    bytestream2_skip(gbc, 4); // caps3

    bytestream2_skip(gbc, 4); // caps4

    bytestream2_skip(gbc, 4); // reserved2



    av_get_codec_tag_string(buf, sizeof(buf), fourcc);

    av_log(avctx, AV_LOG_VERBOSE, "fourcc %s bpp %d "

           "r 0x%x g 0x%x b 0x%x a 0x%x\n", buf, bpp, r, g, b, a);

    if (gimp_tag) {

        av_get_codec_tag_string(buf, sizeof(buf), gimp_tag);

        av_log(avctx, AV_LOG_VERBOSE, "and GIMP-DDS tag %s\n", buf);

    }



    if (ctx->compressed)

        avctx->pix_fmt = AV_PIX_FMT_RGBA;



    if (ctx->compressed) {

        switch (fourcc) {

        case MKTAG('D', 'X', 'T', '1'):

            ctx->tex_ratio = 8;

            ctx->tex_funct = ctx->texdsp.dxt1a_block;

            break;

        case MKTAG('D', 'X', 'T', '2'):

            ctx->tex_ratio = 16;

            ctx->tex_funct = ctx->texdsp.dxt2_block;

            break;

        case MKTAG('D', 'X', 'T', '3'):

            ctx->tex_ratio = 16;

            ctx->tex_funct = ctx->texdsp.dxt3_block;

            break;

        case MKTAG('D', 'X', 'T', '4'):

            ctx->tex_ratio = 16;

            ctx->tex_funct = ctx->texdsp.dxt4_block;

            break;

        case MKTAG('D', 'X', 'T', '5'):

            ctx->tex_ratio = 16;

            if (ycocg_scaled)

                ctx->tex_funct = ctx->texdsp.dxt5ys_block;

            else if (ycocg_classic)

                ctx->tex_funct = ctx->texdsp.dxt5y_block;

            else

                ctx->tex_funct = ctx->texdsp.dxt5_block;

            break;

        case MKTAG('R', 'X', 'G', 'B'):

            ctx->tex_ratio = 16;

            ctx->tex_funct = ctx->texdsp.dxt5_block;

            /* This format may be considered as a normal map,

             * but it is handled differently in a separate postproc. */

            ctx->postproc = DDS_SWIZZLE_RXGB;

            normal_map = 0;

            break;

        case MKTAG('A', 'T', 'I', '1'):

        case MKTAG('B', 'C', '4', 'U'):

            ctx->tex_ratio = 8;

            ctx->tex_funct = ctx->texdsp.rgtc1u_block;

            break;

        case MKTAG('B', 'C', '4', 'S'):

            ctx->tex_ratio = 8;

            ctx->tex_funct = ctx->texdsp.rgtc1s_block;

            break;

        case MKTAG('A', 'T', 'I', '2'):

            /* RGT2 variant with swapped R and G (3Dc)*/

            ctx->tex_ratio = 16;

            ctx->tex_funct = ctx->texdsp.dxn3dc_block;

            break;

        case MKTAG('B', 'C', '5', 'U'):

            ctx->tex_ratio = 16;

            ctx->tex_funct = ctx->texdsp.rgtc2u_block;

            break;

        case MKTAG('B', 'C', '5', 'S'):

            ctx->tex_ratio = 16;

            ctx->tex_funct = ctx->texdsp.rgtc2s_block;

            break;

        case MKTAG('U', 'Y', 'V', 'Y'):

            ctx->compressed = 0;

            avctx->pix_fmt = AV_PIX_FMT_UYVY422;

            break;

        case MKTAG('Y', 'U', 'Y', '2'):

            ctx->compressed = 0;

            avctx->pix_fmt = AV_PIX_FMT_YUYV422;

            break;

        case MKTAG('P', '8', ' ', ' '):

            /* ATI Palette8, same as normal palette */

            ctx->compressed = 0;

            ctx->paletted   = 1;

            avctx->pix_fmt  = AV_PIX_FMT_PAL8;

            break;

        case MKTAG('D', 'X', '1', '0'):

            /* DirectX 10 extra header */

            dxgi = bytestream2_get_le32(gbc);

            bytestream2_skip(gbc, 4); // resourceDimension

            bytestream2_skip(gbc, 4); // miscFlag

            array = bytestream2_get_le32(gbc);

            bytestream2_skip(gbc, 4); // miscFlag2



            if (array != 0)

                av_log(avctx, AV_LOG_VERBOSE,

                       "Found array of size %d (ignored).\n", array);



            /* Only BC[1-5] are actually compressed. */

            ctx->compressed = (dxgi >= 70) && (dxgi <= 84);



            av_log(avctx, AV_LOG_VERBOSE, "DXGI format %d.\n", dxgi);

            switch (dxgi) {

            /* RGB types. */

            case DXGI_FORMAT_R16G16B16A16_TYPELESS:

            case DXGI_FORMAT_R16G16B16A16_FLOAT:

            case DXGI_FORMAT_R16G16B16A16_UNORM:

            case DXGI_FORMAT_R16G16B16A16_UINT:

            case DXGI_FORMAT_R16G16B16A16_SNORM:

            case DXGI_FORMAT_R16G16B16A16_SINT:

                avctx->pix_fmt = AV_PIX_FMT_BGRA64;

                break;

            case DXGI_FORMAT_R8G8B8A8_UNORM_SRGB:

                avctx->colorspace = AVCOL_SPC_RGB;

            case DXGI_FORMAT_R8G8B8A8_TYPELESS:

            case DXGI_FORMAT_R8G8B8A8_UNORM:

            case DXGI_FORMAT_R8G8B8A8_UINT:

            case DXGI_FORMAT_R8G8B8A8_SNORM:

            case DXGI_FORMAT_R8G8B8A8_SINT:

                avctx->pix_fmt = AV_PIX_FMT_BGRA;

                break;

            case DXGI_FORMAT_B8G8R8A8_UNORM_SRGB:

                avctx->colorspace = AVCOL_SPC_RGB;

            case DXGI_FORMAT_B8G8R8A8_TYPELESS:

            case DXGI_FORMAT_B8G8R8A8_UNORM:

                avctx->pix_fmt = AV_PIX_FMT_RGBA;

                break;

            case DXGI_FORMAT_B8G8R8X8_UNORM_SRGB:

                avctx->colorspace = AVCOL_SPC_RGB;

            case DXGI_FORMAT_B8G8R8X8_TYPELESS:

            case DXGI_FORMAT_B8G8R8X8_UNORM:

                avctx->pix_fmt = AV_PIX_FMT_RGBA; // opaque

                break;

            case DXGI_FORMAT_B5G6R5_UNORM:

                avctx->pix_fmt = AV_PIX_FMT_RGB565LE;

                break;

            /* Texture types. */

            case DXGI_FORMAT_BC1_UNORM_SRGB:

                avctx->colorspace = AVCOL_SPC_RGB;

            case DXGI_FORMAT_BC1_TYPELESS:

            case DXGI_FORMAT_BC1_UNORM:

                ctx->tex_ratio = 8;

                ctx->tex_funct = ctx->texdsp.dxt1a_block;

                break;

            case DXGI_FORMAT_BC2_UNORM_SRGB:

                avctx->colorspace = AVCOL_SPC_RGB;

            case DXGI_FORMAT_BC2_TYPELESS:

            case DXGI_FORMAT_BC2_UNORM:

                ctx->tex_ratio = 16;

                ctx->tex_funct = ctx->texdsp.dxt3_block;

                break;

            case DXGI_FORMAT_BC3_UNORM_SRGB:

                avctx->colorspace = AVCOL_SPC_RGB;

            case DXGI_FORMAT_BC3_TYPELESS:

            case DXGI_FORMAT_BC3_UNORM:

                ctx->tex_ratio = 16;

                ctx->tex_funct = ctx->texdsp.dxt5_block;

                break;

            case DXGI_FORMAT_BC4_TYPELESS:

            case DXGI_FORMAT_BC4_UNORM:

                ctx->tex_ratio = 8;

                ctx->tex_funct = ctx->texdsp.rgtc1u_block;

                break;

            case DXGI_FORMAT_BC4_SNORM:

                ctx->tex_ratio = 8;

                ctx->tex_funct = ctx->texdsp.rgtc1s_block;

                break;

            case DXGI_FORMAT_BC5_TYPELESS:

            case DXGI_FORMAT_BC5_UNORM:

                ctx->tex_ratio = 16;

                ctx->tex_funct = ctx->texdsp.rgtc2u_block;

                break;

            case DXGI_FORMAT_BC5_SNORM:

                ctx->tex_ratio = 16;

                ctx->tex_funct = ctx->texdsp.rgtc2s_block;

                break;

            default:

                av_log(avctx, AV_LOG_ERROR,

                       "Unsupported DXGI format %d.\n", dxgi);

                return AVERROR_INVALIDDATA;

            }

            break;

        default:

            av_log(avctx, AV_LOG_ERROR, "Unsupported %s fourcc.\n", buf);

            return AVERROR_INVALIDDATA;

        }

    } else if (ctx->paletted) {

        if (bpp == 8) {

            avctx->pix_fmt = AV_PIX_FMT_PAL8;

        } else {

            av_log(avctx, AV_LOG_ERROR, "Unsupported palette bpp %d.\n", bpp);

            return AVERROR_INVALIDDATA;

        }

    } else {

        /*  8 bpp */

        if (bpp == 8 && r == 0xff && g == 0 && b == 0 && a == 0)

            avctx->pix_fmt = AV_PIX_FMT_GRAY8;

        else if (bpp == 8 && r == 0 && g == 0 && b == 0 && a == 0xff)

            avctx->pix_fmt = AV_PIX_FMT_GRAY8;

        /* 16 bpp */

        else if (bpp == 16 && r == 0xff && g == 0 && b == 0 && a == 0xff00)

            avctx->pix_fmt = AV_PIX_FMT_YA8;

        else if (bpp == 16 && r == 0xffff && g == 0 && b == 0 && a == 0)

            avctx->pix_fmt = AV_PIX_FMT_GRAY16LE;

        else if (bpp == 16 && r == 0x7c00 && g == 0x3e0 && b == 0x1f && a == 0)

            avctx->pix_fmt = AV_PIX_FMT_RGB555LE;

        else if (bpp == 16 && r == 0x7c00 && g == 0x3e0 && b == 0x1f && a == 0x8000)

            avctx->pix_fmt = AV_PIX_FMT_RGB555LE; // alpha ignored

        else if (bpp == 16 && r == 0xf800 && g == 0x7e0 && b == 0x1f && a == 0)

            avctx->pix_fmt = AV_PIX_FMT_RGB565LE;

        /* 24 bpp */

        else if (bpp == 24 && r == 0xff0000 && g == 0xff00 && b == 0xff && a == 0)

            avctx->pix_fmt = AV_PIX_FMT_BGR24;

        /* 32 bpp */

        else if (bpp == 32 && r == 0xff0000 && g == 0xff00 && b == 0xff && a == 0)

            avctx->pix_fmt = AV_PIX_FMT_BGRA; // opaque

        else if (bpp == 32 && r == 0xff && g == 0xff00 && b == 0xff0000 && a == 0)

            avctx->pix_fmt = AV_PIX_FMT_RGBA; // opaque

        else if (bpp == 32 && r == 0xff0000 && g == 0xff00 && b == 0xff && a == 0xff000000)

            avctx->pix_fmt = AV_PIX_FMT_BGRA;

        else if (bpp == 32 && r == 0xff && g == 0xff00 && b == 0xff0000 && a == 0xff000000)

            avctx->pix_fmt = AV_PIX_FMT_RGBA;

        /* give up */

        else {

            av_log(avctx, AV_LOG_ERROR, "Unknown pixel format "

                   "[bpp %d r 0x%x g 0x%x b 0x%x a 0x%x].\n", bpp, r, g, b, a);

            return AVERROR_INVALIDDATA;

        }

    }



    /* Set any remaining post-proc that should happen before frame is ready. */

    if (alpha_exponent)

        ctx->postproc = DDS_ALPHA_EXP;

    else if (normal_map)

        ctx->postproc = DDS_NORMAL_MAP;

    else if (ycocg_classic && !ctx->compressed)

        ctx->postproc = DDS_RAW_YCOCG;

    else if (avctx->pix_fmt == AV_PIX_FMT_YA8)

        ctx->postproc = DDS_SWAP_ALPHA;



    /* ATI/NVidia variants sometimes add swizzling in bpp. */

    switch (bpp) {

    case MKTAG('A', '2', 'X', 'Y'):

        ctx->postproc = DDS_SWIZZLE_A2XY;

        break;

    case MKTAG('x', 'G', 'B', 'R'):

        ctx->postproc = DDS_SWIZZLE_XGBR;

        break;

    case MKTAG('x', 'R', 'B', 'G'):

        ctx->postproc = DDS_SWIZZLE_XRBG;

        break;

    case MKTAG('R', 'B', 'x', 'G'):

        ctx->postproc = DDS_SWIZZLE_RBXG;

        break;

    case MKTAG('R', 'G', 'x', 'B'):

        ctx->postproc = DDS_SWIZZLE_RGXB;

        break;

    case MKTAG('R', 'x', 'B', 'G'):

        ctx->postproc = DDS_SWIZZLE_RXBG;

        break;

    case MKTAG('x', 'G', 'x', 'R'):

        ctx->postproc = DDS_SWIZZLE_XGXR;

        break;

    case MKTAG('A', '2', 'D', '5'):

        ctx->postproc = DDS_NORMAL_MAP;

        break;

    }



    return 0;

}

static int svc_decode_frame(AVCodecContext *avctx, void *data,

                            int *got_frame, AVPacket *avpkt)

{

    SVCContext *s = avctx->priv_data;

    SBufferInfo info = { 0 };

    uint8_t* ptrs[3];

    int linesize[3];

    AVFrame *avframe = data;

    DECODING_STATE state;



    state = (*s->decoder)->DecodeFrame2(s->decoder, avpkt->data, avpkt->size, ptrs, &info);

    if (state != dsErrorFree) {

        av_log(avctx, AV_LOG_ERROR, "DecodeFrame2 failed\n");

        return AVERROR_UNKNOWN;

    }

    if (info.iBufferStatus != 1) {

        av_log(avctx, AV_LOG_DEBUG, "No frame produced\n");

        return avpkt->size;

    }



    ff_set_dimensions(avctx, info.UsrData.sSystemBuffer.iWidth, info.UsrData.sSystemBuffer.iHeight);

    // The decoder doesn't (currently) support decoding into a user

    // provided buffer, so do a copy instead.

    if (ff_get_buffer(avctx, avframe, 0) < 0) {

        av_log(avctx, AV_LOG_ERROR, "Unable to allocate buffer\n");

        return AVERROR(ENOMEM);

    }



    linesize[0] = info.UsrData.sSystemBuffer.iStride[0];

    linesize[1] = linesize[2] = info.UsrData.sSystemBuffer.iStride[1];

    av_image_copy(avframe->data, avframe->linesize, (const uint8_t **) ptrs, linesize, avctx->pix_fmt, avctx->width, avctx->height);



    avframe->pts     = avpkt->pts;

    avframe->pkt_dts = avpkt->dts;

#if FF_API_PKT_PTS

FF_DISABLE_DEPRECATION_WARNINGS

    avframe->pkt_pts = avpkt->pts;

FF_ENABLE_DEPRECATION_WARNINGS

#endif



    *got_frame = 1;

    return avpkt->size;

}

