static int flv_write_header(AVFormatContext *s)

{

    AVIOContext *pb = s->pb;

    FLVContext *flv = s->priv_data;

    AVCodecContext *audio_enc = NULL, *video_enc = NULL;

    int i, metadata_count = 0;

    double framerate = 0.0;

    int64_t metadata_size_pos, data_size, metadata_count_pos;

    AVDictionaryEntry *tag = NULL;



    for(i=0; i<s->nb_streams; i++){

        AVCodecContext *enc = s->streams[i]->codec;

        if (enc->codec_type == AVMEDIA_TYPE_VIDEO) {

            if (s->streams[i]->r_frame_rate.den && s->streams[i]->r_frame_rate.num) {

                framerate = av_q2d(s->streams[i]->r_frame_rate);

            } else {

                framerate = 1/av_q2d(s->streams[i]->codec->time_base);

            }

            video_enc = enc;

            if(enc->codec_tag == 0) {

                av_log(enc, AV_LOG_ERROR, "video codec not compatible with flv\n");

                return -1;

            }

        } else {

            audio_enc = enc;

            if(get_audio_flags(enc)<0)

                return -1;

        }

        av_set_pts_info(s->streams[i], 32, 1, 1000); /* 32 bit pts in ms */

    }

    avio_write(pb, "FLV", 3);

    avio_w8(pb,1);

    avio_w8(pb,   FLV_HEADER_FLAG_HASAUDIO * !!audio_enc

                 + FLV_HEADER_FLAG_HASVIDEO * !!video_enc);

    avio_wb32(pb,9);

    avio_wb32(pb,0);



    for(i=0; i<s->nb_streams; i++){

        if(s->streams[i]->codec->codec_tag == 5){

            avio_w8(pb,8); // message type

            avio_wb24(pb,0); // include flags

            avio_wb24(pb,0); // time stamp

            avio_wb32(pb,0); // reserved

            avio_wb32(pb,11); // size

            flv->reserved=5;

        }

    }



    flv->last_video_ts = -1;



    /* write meta_tag */

    avio_w8(pb, 18);         // tag type META

    metadata_size_pos= avio_tell(pb);

    avio_wb24(pb, 0);          // size of data part (sum of all parts below)

    avio_wb24(pb, 0);          // time stamp

    avio_wb32(pb, 0);          // reserved



    /* now data of data_size size */



    /* first event name as a string */

    avio_w8(pb, AMF_DATA_TYPE_STRING);

    put_amf_string(pb, "onMetaData"); // 12 bytes



    /* mixed array (hash) with size and string/type/data tuples */

    avio_w8(pb, AMF_DATA_TYPE_MIXEDARRAY);

    metadata_count_pos = avio_tell(pb);

    metadata_count = 5*!!video_enc + 5*!!audio_enc + 2; // +2 for duration and file size

    avio_wb32(pb, metadata_count);



    put_amf_string(pb, "duration");

    flv->duration_offset= avio_tell(pb);

    put_amf_double(pb, s->duration / AV_TIME_BASE); // fill in the guessed duration, it'll be corrected later if incorrect



    if(video_enc){

        put_amf_string(pb, "width");

        put_amf_double(pb, video_enc->width);



        put_amf_string(pb, "height");

        put_amf_double(pb, video_enc->height);



        put_amf_string(pb, "videodatarate");

        put_amf_double(pb, video_enc->bit_rate / 1024.0);



        put_amf_string(pb, "framerate");

        put_amf_double(pb, framerate);



        put_amf_string(pb, "videocodecid");

        put_amf_double(pb, video_enc->codec_tag);

    }



    if(audio_enc){

        put_amf_string(pb, "audiodatarate");

        put_amf_double(pb, audio_enc->bit_rate / 1024.0);



        put_amf_string(pb, "audiosamplerate");

        put_amf_double(pb, audio_enc->sample_rate);



        put_amf_string(pb, "audiosamplesize");

        put_amf_double(pb, audio_enc->codec_id == CODEC_ID_PCM_U8 ? 8 : 16);



        put_amf_string(pb, "stereo");

        put_amf_bool(pb, audio_enc->channels == 2);



        put_amf_string(pb, "audiocodecid");

        put_amf_double(pb, audio_enc->codec_tag);

    }



    while ((tag = av_dict_get(s->metadata, "", tag, AV_DICT_IGNORE_SUFFIX))) {

        put_amf_string(pb, tag->key);

        avio_w8(pb, AMF_DATA_TYPE_STRING);

        put_amf_string(pb, tag->value);

        metadata_count++;

    }



    put_amf_string(pb, "filesize");

    flv->filesize_offset= avio_tell(pb);

    put_amf_double(pb, 0); // delayed write



    put_amf_string(pb, "");

    avio_w8(pb, AMF_END_OF_OBJECT);



    /* write total size of tag */

    data_size= avio_tell(pb) - metadata_size_pos - 10;



    avio_seek(pb, metadata_count_pos, SEEK_SET);

    avio_wb32(pb, metadata_count);



    avio_seek(pb, metadata_size_pos, SEEK_SET);

    avio_wb24(pb, data_size);

    avio_skip(pb, data_size + 10 - 3);

    avio_wb32(pb, data_size + 11);



    for (i = 0; i < s->nb_streams; i++) {

        AVCodecContext *enc = s->streams[i]->codec;

        if (enc->codec_id == CODEC_ID_AAC || enc->codec_id == CODEC_ID_H264) {

            int64_t pos;

            avio_w8(pb, enc->codec_type == AVMEDIA_TYPE_VIDEO ?

                     FLV_TAG_TYPE_VIDEO : FLV_TAG_TYPE_AUDIO);

            avio_wb24(pb, 0); // size patched later

            avio_wb24(pb, 0); // ts

            avio_w8(pb, 0); // ts ext

            avio_wb24(pb, 0); // streamid

            pos = avio_tell(pb);

            if (enc->codec_id == CODEC_ID_AAC) {

                avio_w8(pb, get_audio_flags(enc));

                avio_w8(pb, 0); // AAC sequence header

                avio_write(pb, enc->extradata, enc->extradata_size);

            } else {

                avio_w8(pb, enc->codec_tag | FLV_FRAME_KEY); // flags

                avio_w8(pb, 0); // AVC sequence header

                avio_wb24(pb, 0); // composition time

                ff_isom_write_avcc(pb, enc->extradata, enc->extradata_size);

            }

            data_size = avio_tell(pb) - pos;

            avio_seek(pb, -data_size - 10, SEEK_CUR);

            avio_wb24(pb, data_size);

            avio_skip(pb, data_size + 10 - 3);

            avio_wb32(pb, data_size + 11); // previous tag size

        }

    }



    return 0;

}

static void filter_edges(void *dst1, void *prev1, void *cur1, void *next1,

                         int w, int prefs, int mrefs, int parity, int mode)

{

    uint8_t *dst  = dst1;

    uint8_t *prev = prev1;

    uint8_t *cur  = cur1;

    uint8_t *next = next1;

    int x;

    uint8_t *prev2 = parity ? prev : cur ;

    uint8_t *next2 = parity ? cur  : next;



    /* Only edge pixels need to be processed here.  A constant value of false

     * for is_not_edge should let the compiler ignore the whole branch. */

    FILTER(0, 3, 0)



    dst  = (uint8_t*)dst1  + w - 3;

    prev = (uint8_t*)prev1 + w - 3;

    cur  = (uint8_t*)cur1  + w - 3;

    next = (uint8_t*)next1 + w - 3;

    prev2 = (uint8_t*)(parity ? prev : cur);

    next2 = (uint8_t*)(parity ? cur  : next);



    FILTER(w - 3, w, 0)

}

static int decode_frame(AVCodecContext *avctx, void *data, int *data_size,

                        AVPacket *avpkt)

{

    V210DecContext *s = avctx->priv_data;



    int h, w, stride, aligned_input;

    AVFrame *pic = avctx->coded_frame;

    const uint8_t *psrc = avpkt->data;

    uint16_t *y, *u, *v;



    if (s->custom_stride )

        stride = s->custom_stride;

    else {

        int aligned_width = ((avctx->width + 47) / 48) * 48;

        stride = aligned_width * 8 / 3;

    }



    aligned_input = !((uintptr_t)psrc & 0xf) && !(stride & 0xf);

    if (aligned_input != s->aligned_input) {

        s->aligned_input = aligned_input;

        if (HAVE_MMX)

            v210_x86_init(s);

    }



    if (pic->data[0])

        avctx->release_buffer(avctx, pic);



    if (avpkt->size < stride * avctx->height) {

        av_log(avctx, AV_LOG_ERROR, "packet too small\n");

        return -1;

    }



    pic->reference = 0;

    if (avctx->get_buffer(avctx, pic) < 0)

        return -1;



    y = (uint16_t*)pic->data[0];

    u = (uint16_t*)pic->data[1];

    v = (uint16_t*)pic->data[2];

    pic->pict_type = AV_PICTURE_TYPE_I;

    pic->key_frame = 1;



    for (h = 0; h < avctx->height; h++) {

        const uint32_t *src = (const uint32_t*)psrc;

        uint32_t val;



        w = (avctx->width / 6) * 6;

        s->unpack_frame(src, y, u, v, w);



        y += w;

        u += w >> 1;

        v += w >> 1;

        src += (w << 1) / 3;



        if (w < avctx->width - 1) {

            READ_PIXELS(u, y, v);



            val  = av_le2ne32(*src++);

            *y++ =  val & 0x3FF;

        }

        if (w < avctx->width - 3) {

            *u++ = (val >> 10) & 0x3FF;

            *y++ = (val >> 20) & 0x3FF;



            val  = av_le2ne32(*src++);

            *v++ =  val & 0x3FF;

            *y++ = (val >> 10) & 0x3FF;

        }



        psrc += stride;

        y += pic->linesize[0] / 2 - avctx->width;

        u += pic->linesize[1] / 2 - avctx->width / 2;

        v += pic->linesize[2] / 2 - avctx->width / 2;

    }



    *data_size = sizeof(AVFrame);

    *(AVFrame*)data = *avctx->coded_frame;



    return avpkt->size;

}

static int read_shape_from_file(int *cols, int *rows, int **values, const char *filename,

                                void *log_ctx)

{

    uint8_t *buf, *p, *pend;

    size_t size;

    int ret, i, j, w;



    if ((ret = av_file_map(filename, &buf, &size, 0, log_ctx)) < 0)

        return ret;



    /* prescan file to get the number of lines and the maximum width */

    w = 0;

    for (i = 0; i < size; i++) {

        if (buf[i] == '\n') {

            if (*rows == INT_MAX) {

                av_log(log_ctx, AV_LOG_ERROR, "Overflow on the number of rows in the file\n");

                return AVERROR_INVALIDDATA;

            }

            ++(*rows);

            *cols = FFMAX(*cols, w);

            w = 0;

        } else if (w == INT_MAX) {

            av_log(log_ctx, AV_LOG_ERROR, "Overflow on the number of columns in the file\n");

            return AVERROR_INVALIDDATA;

        }

        w++;

    }

    if (*rows > (SIZE_MAX / sizeof(int) / *cols)) {

        av_log(log_ctx, AV_LOG_ERROR, "File with size %dx%d is too big\n",

               *rows, *cols);

        return AVERROR_INVALIDDATA;

    }

    if (!(*values = av_mallocz_array(sizeof(int) * *rows, *cols)))

        return AVERROR(ENOMEM);



    /* fill *values */

    p    = buf;

    pend = buf + size-1;

    for (i = 0; i < *rows; i++) {

        for (j = 0;; j++) {

            if (p > pend || *p == '\n') {

                p++;

                break;

            } else

                (*values)[*cols*i + j] = !!av_isgraph(*(p++));

        }

    }

    av_file_unmap(buf, size);



#ifdef DEBUG

    {

        char *line;

        if (!(line = av_malloc(*cols + 1)))

            return AVERROR(ENOMEM);

        for (i = 0; i < *rows; i++) {

            for (j = 0; j < *cols; j++)

                line[j] = (*values)[i * *cols + j] ? '@' : ' ';

            line[j] = 0;

            av_log(log_ctx, AV_LOG_DEBUG, "%3d: %s\n", i, line);

        }

        av_free(line);

    }

#endif



    return 0;

}

static inline void RENAME(rgb16to32)(const uint8_t *src, uint8_t *dst, long src_size)

{

	const uint16_t *end;

#ifdef HAVE_MMX

	const uint16_t *mm_end;

#endif

	uint8_t *d = (uint8_t *)dst;

	const uint16_t *s = (uint16_t *)src;

	end = s + src_size/2;

#ifdef HAVE_MMX

	__asm __volatile(PREFETCH"	%0"::"m"(*s):"memory");

	__asm __volatile("pxor	%%mm7,%%mm7\n\t":::"memory");

	mm_end = end - 3;

	while(s < mm_end)

	{

	    __asm __volatile(

		PREFETCH" 32%1\n\t"

		"movq	%1, %%mm0\n\t"

		"movq	%1, %%mm1\n\t"

		"movq	%1, %%mm2\n\t"

		"pand	%2, %%mm0\n\t"

		"pand	%3, %%mm1\n\t"

		"pand	%4, %%mm2\n\t"

		"psllq	$3, %%mm0\n\t"

		"psrlq	$3, %%mm1\n\t"

		"psrlq	$8, %%mm2\n\t"

		"movq	%%mm0, %%mm3\n\t"

		"movq	%%mm1, %%mm4\n\t"

		"movq	%%mm2, %%mm5\n\t"

		"punpcklwd %%mm7, %%mm0\n\t"

		"punpcklwd %%mm7, %%mm1\n\t"

		"punpcklwd %%mm7, %%mm2\n\t"

		"punpckhwd %%mm7, %%mm3\n\t"

		"punpckhwd %%mm7, %%mm4\n\t"

		"punpckhwd %%mm7, %%mm5\n\t"

		"psllq	$8, %%mm1\n\t"

		"psllq	$16, %%mm2\n\t"

		"por	%%mm1, %%mm0\n\t"

		"por	%%mm2, %%mm0\n\t"

		"psllq	$8, %%mm4\n\t"

		"psllq	$16, %%mm5\n\t"

		"por	%%mm4, %%mm3\n\t"

		"por	%%mm5, %%mm3\n\t"

		MOVNTQ"	%%mm0, %0\n\t"

		MOVNTQ"	%%mm3, 8%0\n\t"

		:"=m"(*d)

		:"m"(*s),"m"(mask16b),"m"(mask16g),"m"(mask16r)

		:"memory");

		d += 16;

		s += 4;

	}

	__asm __volatile(SFENCE:::"memory");

	__asm __volatile(EMMS:::"memory");

#endif

	while(s < end)

	{

		register uint16_t bgr;

		bgr = *s++;

#ifdef WORDS_BIGENDIAN

		*d++ = 0;

		*d++ = (bgr&0xF800)>>8;

		*d++ = (bgr&0x7E0)>>3;

		*d++ = (bgr&0x1F)<<3;

#else

		*d++ = (bgr&0x1F)<<3;

		*d++ = (bgr&0x7E0)>>3;

		*d++ = (bgr&0xF800)>>8;

		*d++ = 0;

#endif

	}

}

int ff_packet_split_and_drop_side_data(AVPacket *pkt){

    if (!pkt->side_data_elems && pkt->size >12 && AV_RB64(pkt->data + pkt->size - 8) == FF_MERGE_MARKER){

        int i;

        unsigned int size;

        uint8_t *p;



        p = pkt->data + pkt->size - 8 - 5;

        for (i=1; ; i++){

            size = AV_RB32(p);

            if (size>INT_MAX - 5 || p - pkt->data < size)


            if (p[4]&128)

                break;

            if (p - pkt->data < size + 5)


            p-= size+5;



        }

        pkt->size = p - pkt->data - size;

        av_assert0(pkt->size >= 0);

        return 1;

    }


}

static float get_band_cost_SPAIR_mips(struct AACEncContext *s,

                                      PutBitContext *pb, const float *in,

                                      const float *scaled, int size, int scale_idx,

                                      int cb, const float lambda, const float uplim,

                                      int *bits)

{

    const float Q34 = ff_aac_pow34sf_tab[POW_SF2_ZERO - scale_idx + SCALE_ONE_POS - SCALE_DIV_512];

    const float IQ  = ff_aac_pow2sf_tab [POW_SF2_ZERO + scale_idx - SCALE_ONE_POS + SCALE_DIV_512];

    int i;

    float cost = 0;

    int qc1, qc2, qc3, qc4;

    int curbits = 0;



    uint8_t *p_bits  = (uint8_t *)ff_aac_spectral_bits[cb-1];

    float   *p_codes = (float   *)ff_aac_codebook_vectors[cb-1];



    for (i = 0; i < size; i += 4) {

        const float *vec, *vec2;

        int curidx, curidx2;

        int   *in_int = (int   *)&in[i];

        float *in_pos = (float *)&in[i];

        float di0, di1, di2, di3;

        int t0, t1, t2, t3, t4, t5, t6, t7;



        qc1 = scaled[i  ] * Q34 + ROUND_STANDARD;

        qc2 = scaled[i+1] * Q34 + ROUND_STANDARD;

        qc3 = scaled[i+2] * Q34 + ROUND_STANDARD;

        qc4 = scaled[i+3] * Q34 + ROUND_STANDARD;



        __asm__ volatile (

            ".set push                                  \n\t"

            ".set noreorder                             \n\t"



            "ori        %[t4],  $zero,  4               \n\t"

            "slt        %[t0],  %[t4],  %[qc1]          \n\t"

            "slt        %[t1],  %[t4],  %[qc2]          \n\t"

            "slt        %[t2],  %[t4],  %[qc3]          \n\t"

            "slt        %[t3],  %[t4],  %[qc4]          \n\t"

            "movn       %[qc1], %[t4],  %[t0]           \n\t"

            "movn       %[qc2], %[t4],  %[t1]           \n\t"

            "movn       %[qc3], %[t4],  %[t2]           \n\t"

            "movn       %[qc4], %[t4],  %[t3]           \n\t"

            "lw         %[t0],  0(%[in_int])            \n\t"

            "lw         %[t1],  4(%[in_int])            \n\t"

            "lw         %[t2],  8(%[in_int])            \n\t"

            "lw         %[t3],  12(%[in_int])           \n\t"

            "srl        %[t0],  %[t0],  31              \n\t"

            "srl        %[t1],  %[t1],  31              \n\t"

            "srl        %[t2],  %[t2],  31              \n\t"

            "srl        %[t3],  %[t3],  31              \n\t"

            "subu       %[t4],  $zero,  %[qc1]          \n\t"

            "subu       %[t5],  $zero,  %[qc2]          \n\t"

            "subu       %[t6],  $zero,  %[qc3]          \n\t"

            "subu       %[t7],  $zero,  %[qc4]          \n\t"

            "movn       %[qc1], %[t4],  %[t0]           \n\t"

            "movn       %[qc2], %[t5],  %[t1]           \n\t"

            "movn       %[qc3], %[t6],  %[t2]           \n\t"

            "movn       %[qc4], %[t7],  %[t3]           \n\t"



            ".set pop                                   \n\t"



            : [qc1]"+r"(qc1), [qc2]"+r"(qc2),

              [qc3]"+r"(qc3), [qc4]"+r"(qc4),

              [t0]"=&r"(t0), [t1]"=&r"(t1), [t2]"=&r"(t2), [t3]"=&r"(t3),

              [t4]"=&r"(t4), [t5]"=&r"(t5), [t6]"=&r"(t6), [t7]"=&r"(t7)

            : [in_int]"r"(in_int)

            : "memory"

        );



        curidx = 9 * qc1;

        curidx += qc2 + 40;



        curidx2 = 9 * qc3;

        curidx2 += qc4 + 40;



        curbits += p_bits[curidx];

        curbits += p_bits[curidx2];



        vec     = &p_codes[curidx*2];

        vec2    = &p_codes[curidx2*2];



        __asm__ volatile (

            ".set push                                  \n\t"

            ".set noreorder                             \n\t"



            "lwc1       $f0,    0(%[in_pos])            \n\t"

            "lwc1       $f1,    0(%[vec])               \n\t"

            "lwc1       $f2,    4(%[in_pos])            \n\t"

            "lwc1       $f3,    4(%[vec])               \n\t"

            "lwc1       $f4,    8(%[in_pos])            \n\t"

            "lwc1       $f5,    0(%[vec2])              \n\t"

            "lwc1       $f6,    12(%[in_pos])           \n\t"

            "lwc1       $f7,    4(%[vec2])              \n\t"

            "nmsub.s    %[di0], $f0,    $f1,    %[IQ]   \n\t"

            "nmsub.s    %[di1], $f2,    $f3,    %[IQ]   \n\t"

            "nmsub.s    %[di2], $f4,    $f5,    %[IQ]   \n\t"

            "nmsub.s    %[di3], $f6,    $f7,    %[IQ]   \n\t"



            ".set pop                                   \n\t"



            : [di0]"=&f"(di0), [di1]"=&f"(di1),

              [di2]"=&f"(di2), [di3]"=&f"(di3)

            : [in_pos]"r"(in_pos), [vec]"r"(vec),

              [vec2]"r"(vec2), [IQ]"f"(IQ)

            : "$f0", "$f1", "$f2", "$f3",

              "$f4", "$f5", "$f6", "$f7",

              "memory"

        );



        cost += di0 * di0 + di1 * di1

                + di2 * di2 + di3 * di3;

    }



    if (bits)

        *bits = curbits;

    return cost * lambda + curbits;

}

