int ff_raw_read_header(AVFormatContext *s, AVFormatParameters *ap)

{

    AVStream *st;

    enum CodecID id;



    st = av_new_stream(s, 0);

    if (!st)

        return AVERROR(ENOMEM);



        id = s->iformat->value;

        if (id == CODEC_ID_RAWVIDEO) {

            st->codec->codec_type = AVMEDIA_TYPE_VIDEO;

        } else {

            st->codec->codec_type = AVMEDIA_TYPE_AUDIO;

        }

        st->codec->codec_id = id;



        switch(st->codec->codec_type) {

        case AVMEDIA_TYPE_AUDIO: {

            RawAudioDemuxerContext *s1 = s->priv_data;



#if FF_API_FORMAT_PARAMETERS

            if (ap->sample_rate)

                st->codec->sample_rate = ap->sample_rate;

            if (ap->channels)

                st->codec->channels    = ap->channels;

            else st->codec->channels   = 1;

#endif



            if (s1->sample_rate)

                st->codec->sample_rate = s1->sample_rate;

            if (s1->channels)

                st->codec->channels    = s1->channels;



            st->codec->bits_per_coded_sample = av_get_bits_per_sample(st->codec->codec_id);

            assert(st->codec->bits_per_coded_sample > 0);

            st->codec->block_align = st->codec->bits_per_coded_sample*st->codec->channels/8;

            av_set_pts_info(st, 64, 1, st->codec->sample_rate);

            break;

            }

        case AVMEDIA_TYPE_VIDEO: {

            FFRawVideoDemuxerContext *s1 = s->priv_data;

            int width = 0, height = 0, ret;

            enum PixelFormat pix_fmt;



            if(ap->time_base.num)

                av_set_pts_info(st, 64, ap->time_base.num, ap->time_base.den);

            else

                av_set_pts_info(st, 64, 1, 25);

            if (s1->video_size && (ret = av_parse_video_size(&width, &height, s1->video_size)) < 0) {

                av_log(s, AV_LOG_ERROR, "Couldn't parse video size.\n");

                goto fail;

            }

            if ((pix_fmt = av_get_pix_fmt(s1->pixel_format)) == PIX_FMT_NONE) {

                av_log(s, AV_LOG_ERROR, "No such pixel format: %s.\n", s1->pixel_format);

                ret = AVERROR(EINVAL);

                goto fail;

            }

#if FF_API_FORMAT_PARAMETERS

            if (ap->width > 0)

                width = ap->width;

            if (ap->height > 0)

                height = ap->height;

            if (ap->pix_fmt)

                pix_fmt = ap->pix_fmt;

#endif

            st->codec->width  = width;

            st->codec->height = height;

            st->codec->pix_fmt = pix_fmt;

fail:

            av_freep(&s1->video_size);

            av_freep(&s1->pixel_format);

            return ret;

            }

        default:

            return -1;

        }

    return 0;

}

static int read_access_unit(AVCodecContext *avctx, void* data, int *data_size,

                            AVPacket *avpkt)

{

    const uint8_t *buf = avpkt->data;

    int buf_size = avpkt->size;

    MLPDecodeContext *m = avctx->priv_data;

    GetBitContext gb;

    unsigned int length, substr;

    unsigned int substream_start;

    unsigned int header_size = 4;

    unsigned int substr_header_size = 0;

    uint8_t substream_parity_present[MAX_SUBSTREAMS];

    uint16_t substream_data_len[MAX_SUBSTREAMS];

    uint8_t parity_bits;



    if (buf_size < 4)

        return 0;



    length = (AV_RB16(buf) & 0xfff) * 2;



    if (length > buf_size)

        return -1;



    init_get_bits(&gb, (buf + 4), (length - 4) * 8);



    m->is_major_sync_unit = 0;

    if (show_bits_long(&gb, 31) == (0xf8726fba >> 1)) {

        if (read_major_sync(m, &gb) < 0)

            goto error;

        m->is_major_sync_unit = 1;

        header_size += 28;

    }



    if (!m->params_valid) {

        av_log(m->avctx, AV_LOG_WARNING,

               "Stream parameters not seen; skipping frame.\n");

        *data_size = 0;

        return length;

    }



    substream_start = 0;



    for (substr = 0; substr < m->num_substreams; substr++) {

        int extraword_present, checkdata_present, end, nonrestart_substr;



        extraword_present = get_bits1(&gb);

        nonrestart_substr = get_bits1(&gb);

        checkdata_present = get_bits1(&gb);

        skip_bits1(&gb);



        end = get_bits(&gb, 12) * 2;



        substr_header_size += 2;



        if (extraword_present) {

            if (m->avctx->codec_id == CODEC_ID_MLP) {

                av_log(m->avctx, AV_LOG_ERROR, "There must be no extraword for MLP.\n");

                goto error;

            }

            skip_bits(&gb, 16);

            substr_header_size += 2;

        }



        if (!(nonrestart_substr ^ m->is_major_sync_unit)) {

            av_log(m->avctx, AV_LOG_ERROR, "Invalid nonrestart_substr.\n");

            goto error;

        }



        if (end + header_size + substr_header_size > length) {

            av_log(m->avctx, AV_LOG_ERROR,

                   "Indicated length of substream %d data goes off end of "

                   "packet.\n", substr);

            end = length - header_size - substr_header_size;

        }



        if (end < substream_start) {

            av_log(avctx, AV_LOG_ERROR,

                   "Indicated end offset of substream %d data "

                   "is smaller than calculated start offset.\n",

                   substr);

            goto error;

        }



        if (substr > m->max_decoded_substream)

            continue;



        substream_parity_present[substr] = checkdata_present;

        substream_data_len[substr] = end - substream_start;

        substream_start = end;

    }



    parity_bits  = ff_mlp_calculate_parity(buf, 4);

    parity_bits ^= ff_mlp_calculate_parity(buf + header_size, substr_header_size);



    if ((((parity_bits >> 4) ^ parity_bits) & 0xF) != 0xF) {

        av_log(avctx, AV_LOG_ERROR, "Parity check failed.\n");

        goto error;

    }



    buf += header_size + substr_header_size;



    for (substr = 0; substr <= m->max_decoded_substream; substr++) {

        SubStream *s = &m->substream[substr];

        init_get_bits(&gb, buf, substream_data_len[substr] * 8);



        m->matrix_changed = 0;

        memset(m->filter_changed, 0, sizeof(m->filter_changed));



        s->blockpos = 0;

        do {

            if (get_bits1(&gb)) {

                if (get_bits1(&gb)) {

                    /* A restart header should be present. */

                    if (read_restart_header(m, &gb, buf, substr) < 0)

                        goto next_substr;

                    s->restart_seen = 1;

                }



                if (!s->restart_seen)

                    goto next_substr;

                if (read_decoding_params(m, &gb, substr) < 0)

                    goto next_substr;

            }



            if (!s->restart_seen)

                goto next_substr;



            if (read_block_data(m, &gb, substr) < 0)

                return -1;



            if (get_bits_count(&gb) >= substream_data_len[substr] * 8)

                goto substream_length_mismatch;



        } while (!get_bits1(&gb));



        skip_bits(&gb, (-get_bits_count(&gb)) & 15);



        if (substream_data_len[substr] * 8 - get_bits_count(&gb) >= 32) {

            int shorten_by;



            if (get_bits(&gb, 16) != 0xD234)

                return -1;



            shorten_by = get_bits(&gb, 16);

            if      (m->avctx->codec_id == CODEC_ID_TRUEHD && shorten_by  & 0x2000)

                s->blockpos -= FFMIN(shorten_by & 0x1FFF, s->blockpos);

            else if (m->avctx->codec_id == CODEC_ID_MLP    && shorten_by != 0xD234)

                return -1;



            if (substr == m->max_decoded_substream)

                av_log(m->avctx, AV_LOG_INFO, "End of stream indicated.\n");

        }



        if (substream_parity_present[substr]) {

            uint8_t parity, checksum;



            if (substream_data_len[substr] * 8 - get_bits_count(&gb) != 16)

                goto substream_length_mismatch;



            parity   = ff_mlp_calculate_parity(buf, substream_data_len[substr] - 2);

            checksum = ff_mlp_checksum8       (buf, substream_data_len[substr] - 2);



            if ((get_bits(&gb, 8) ^ parity) != 0xa9    )

                av_log(m->avctx, AV_LOG_ERROR, "Substream %d parity check failed.\n", substr);

            if ( get_bits(&gb, 8)           != checksum)

                av_log(m->avctx, AV_LOG_ERROR, "Substream %d checksum failed.\n"    , substr);

        }



        if (substream_data_len[substr] * 8 != get_bits_count(&gb))

            goto substream_length_mismatch;



next_substr:

        if (!s->restart_seen)

            av_log(m->avctx, AV_LOG_ERROR,

                   "No restart header present in substream %d.\n", substr);



        buf += substream_data_len[substr];

    }



    rematrix_channels(m, m->max_decoded_substream);



    if (output_data(m, m->max_decoded_substream, data, data_size) < 0)

        return -1;



    return length;



substream_length_mismatch:

    av_log(m->avctx, AV_LOG_ERROR, "substream %d length mismatch\n", substr);

    return -1;



error:

    m->params_valid = 0;

    return -1;

}

static void sunrast_image_write_image(AVCodecContext *avctx,

                                      const uint8_t *pixels,

                                      const uint32_t *palette_data,

                                      int linesize)

{

    SUNRASTContext *s = avctx->priv_data;

    const uint8_t *ptr;

    int len, alen, x;



    if (s->maplength) {     // palettized

        PutByteContext pb_r, pb_g;

        int len = s->maplength / 3;



        pb_r = s->p;

        bytestream2_skip_p(&s->p, len);

        pb_g = s->p;

        bytestream2_skip_p(&s->p, len);



        for (x = 0; x < len; x++) {

            uint32_t pixel = palette_data[x];



            bytestream2_put_byteu(&pb_r, (pixel >> 16) & 0xFF);

            bytestream2_put_byteu(&pb_g, (pixel >> 8)  & 0xFF);

            bytestream2_put_byteu(&s->p,  pixel        & 0xFF);

        }

    }



    len  = (s->depth * avctx->width + 7) >> 3;

    alen = len + (len & 1);

    ptr  = pixels;



     if (s->type == RT_BYTE_ENCODED) {

        uint8_t value, value2;

        int run;

        const uint8_t *end = pixels + avctx->height * linesize;



        ptr = pixels;



#define GET_VALUE ptr >= end ? 0 : x >= len ? ptr[len-1] : ptr[x]



        x = 0;

        value2 = GET_VALUE;

        while (ptr < end) {

            run = 1;

            value = value2;

            x++;

            if (x >= alen) {

                x = 0;

                ptr += linesize;

            }



            value2 = GET_VALUE;

            while (value2 == value && run < 256 && ptr < end) {

                x++;

                run++;

                if (x >= alen) {

                    x = 0;

                    ptr += linesize;

                }

                value2 = GET_VALUE;

            }



            if (run > 2 || value == RLE_TRIGGER) {

                bytestream2_put_byteu(&s->p, RLE_TRIGGER);

                bytestream2_put_byteu(&s->p, run - 1);

                if (run > 1)

                    bytestream2_put_byteu(&s->p, value);

            } else if (run == 1) {

                bytestream2_put_byteu(&s->p, value);

            } else

                bytestream2_put_be16u(&s->p, (value << 8) | value);

        }



        // update data length for header

        s->length = bytestream2_tell_p(&s->p) - 32 - s->maplength;

    } else {

        int y;

        for (y = 0; y < avctx->height; y++) {

            bytestream2_put_buffer(&s->p, ptr, len);

            if (len < alen)

                bytestream2_put_byteu(&s->p, 0);

            ptr += linesize;

        }

    }

}

static int sol_probe(AVProbeData *p)

{

    /* check file header */

    uint16_t magic;

    if (p->buf_size <= 14)

        return 0;

    magic=le2me_16(*((uint16_t*)p->buf));

    if ((magic == 0x0B8D || magic == 0x0C0D || magic == 0x0C8D) &&

        p->buf[2] == 'S' && p->buf[3] == 'O' &&

        p->buf[4] == 'L' && p->buf[5] == 0)

        return AVPROBE_SCORE_MAX;

    else

        return 0;

}

static int daala_header(AVFormatContext *s, int idx)

{

    int i, err;

    uint8_t *cdp;

    GetByteContext gb;

    AVRational timebase;

    struct ogg *ogg        = s->priv_data;

    struct ogg_stream *os  = ogg->streams + idx;

    AVStream *st           = s->streams[idx];

    int cds                = st->codec->extradata_size + os->psize + 2;

    DaalaInfoHeader *hdr   = os->private;



    if (!(os->buf[os->pstart] & 0x80))

        return 0;



    if (!hdr) {

        hdr = av_mallocz(sizeof(*hdr));

        if (!hdr)

            return AVERROR(ENOMEM);

        os->private = hdr;




    switch (os->buf[os->pstart]) {

    case 0x80:

        bytestream2_init(&gb, os->buf + os->pstart, os->psize);

        bytestream2_skip(&gb, ff_daala_codec.magicsize);



        hdr->version_maj = bytestream2_get_byte(&gb);

        hdr->version_min = bytestream2_get_byte(&gb);

        hdr->version_sub = bytestream2_get_byte(&gb);



        st->codec->width  = bytestream2_get_ne32(&gb);

        st->codec->height = bytestream2_get_ne32(&gb);



        st->sample_aspect_ratio.num = bytestream2_get_ne32(&gb);

        st->sample_aspect_ratio.den = bytestream2_get_ne32(&gb);



        timebase.num = bytestream2_get_ne32(&gb);

        timebase.den = bytestream2_get_ne32(&gb);

        if (timebase.num < 0 && timebase.den < 0) {

            av_log(s, AV_LOG_WARNING, "Invalid timebase, assuming 30 FPS\n");

            timebase.num = 1;

            timebase.den = 30;


        avpriv_set_pts_info(st, 64, timebase.den, timebase.num);



        hdr->frame_duration = bytestream2_get_ne32(&gb);

        hdr->gpshift = bytestream2_get_byte(&gb);

        hdr->gpmask  = (1 << hdr->gpshift) - 1;



        hdr->format.depth  = 8 + 2*(bytestream2_get_byte(&gb)-1);



        hdr->fpr = bytestream2_get_byte(&gb);



        hdr->format.planes = bytestream2_get_byte(&gb);







        for (i = 0; i < hdr->format.planes; i++) {

            hdr->format.xdec[i] = bytestream2_get_byte(&gb);

            hdr->format.ydec[i] = bytestream2_get_byte(&gb);




        if ((st->codec->pix_fmt = daala_match_pix_fmt(&hdr->format)) < 0)

            av_log(s, AV_LOG_ERROR, "Unsupported pixel format - %i %i\n",

                   hdr->format.depth, hdr->format.planes);



        st->codec->codec_id   = AV_CODEC_ID_DAALA;

        st->codec->codec_type = AVMEDIA_TYPE_VIDEO;

        st->need_parsing      = AVSTREAM_PARSE_HEADERS;



        hdr->init_d = 1;

        break;

    case 0x81:

        if (!hdr->init_d)


        ff_vorbis_stream_comment(s, st,

                                 os->buf + os->pstart + ff_daala_codec.magicsize,

                                 os->psize - ff_daala_codec.magicsize);

        break;

    case 0x82:

        if (!hdr->init_d)


        break;

    default:

        av_log(s, AV_LOG_ERROR, "Unknown header type %X\n", os->buf[os->pstart]);


        break;




    if ((err = av_reallocp(&st->codec->extradata,

                           cds + AV_INPUT_BUFFER_PADDING_SIZE)) < 0) {

        st->codec->extradata_size = 0;

        return err;




    memset(st->codec->extradata + cds, 0, AV_INPUT_BUFFER_PADDING_SIZE);

    cdp    = st->codec->extradata + st->codec->extradata_size;

    *cdp++ = os->psize >> 8;

    *cdp++ = os->psize & 0xff;

    memcpy(cdp, os->buf + os->pstart, os->psize);

    st->codec->extradata_size = cds;



    return 1;

static int vorbis_parse_setup_hdr_mappings(vorbis_context *vc) {

    GetBitContext *gb=&vc->gb;

    uint_fast8_t i, j;



    vc->mapping_count=get_bits(gb, 6)+1;

    vc->mappings=av_mallocz(vc->mapping_count * sizeof(vorbis_mapping));



    AV_DEBUG(" There are %d mappings. \n", vc->mapping_count);



    for(i=0;i<vc->mapping_count;++i) {

        vorbis_mapping *mapping_setup=&vc->mappings[i];



        if (get_bits(gb, 16)) {

            av_log(vc->avccontext, AV_LOG_ERROR, "Other mappings than type 0 are not compliant with the Vorbis I specification. \n");

            return 1;

        }

        if (get_bits1(gb)) {

            mapping_setup->submaps=get_bits(gb, 4)+1;

        } else {

            mapping_setup->submaps=1;

        }



        if (get_bits1(gb)) {

            mapping_setup->coupling_steps=get_bits(gb, 8)+1;

            mapping_setup->magnitude=av_mallocz(mapping_setup->coupling_steps * sizeof(uint_fast8_t));

            mapping_setup->angle    =av_mallocz(mapping_setup->coupling_steps * sizeof(uint_fast8_t));

            for(j=0;j<mapping_setup->coupling_steps;++j) {

                mapping_setup->magnitude[j]=get_bits(gb, ilog(vc->audio_channels-1));

                mapping_setup->angle[j]=get_bits(gb, ilog(vc->audio_channels-1));

                // FIXME: sanity checks

            }

        } else {

            mapping_setup->coupling_steps=0;

        }



        AV_DEBUG("   %d mapping coupling steps: %d \n", i, mapping_setup->coupling_steps);



        if(get_bits(gb, 2)) {

            av_log(vc->avccontext, AV_LOG_ERROR, "%d. mapping setup data invalid. \n", i);

            return 1; // following spec.

        }



        if (mapping_setup->submaps>1) {

            mapping_setup->mux=av_mallocz(vc->audio_channels * sizeof(uint_fast8_t));

            for(j=0;j<vc->audio_channels;++j) {

                mapping_setup->mux[j]=get_bits(gb, 4);

            }

        }



        for(j=0;j<mapping_setup->submaps;++j) {

            skip_bits(gb, 8); // FIXME check?

            mapping_setup->submap_floor[j]=get_bits(gb, 8);

            mapping_setup->submap_residue[j]=get_bits(gb, 8);



            AV_DEBUG("   %d mapping %d submap : floor %d, residue %d \n", i, j, mapping_setup->submap_floor[j], mapping_setup->submap_residue[j]);

        }

    }

    return 0;

}

static void residue_encode(venc_context_t * venc, residue_t * rc, PutBitContext * pb, float * coeffs, int samples, int real_ch) {

    int pass, i, j, p, k;

    int psize = rc->partition_size;

    int partitions = (rc->end - rc->begin) / psize;

    int channels = (rc->type == 2) ? 1 : real_ch;

    int classes[channels][partitions];

    int classwords = venc->codebooks[rc->classbook].ndimentions;



    assert(rc->type == 2);

    assert(real_ch == 2);

    for (p = 0; p < partitions; p++) {

        float max1 = 0., max2 = 0.;

        int s = rc->begin + p * psize;

        for (k = s; k < s + psize; k += 2) {

            max1 = FFMAX(max1, fabs(coeffs[          k / real_ch]));

            max2 = FFMAX(max2, fabs(coeffs[samples + k / real_ch]));

        }



        for (i = 0; i < rc->classifications - 1; i++) {

            if (max1 < rc->maxes[i][0] && max2 < rc->maxes[i][1]) break;

        }

        classes[0][p] = i;

    }



    for (pass = 0; pass < 8; pass++) {

        p = 0;

        while (p < partitions) {

            if (pass == 0) for (j = 0; j < channels; j++) {

                codebook_t * book = &venc->codebooks[rc->classbook];

                int entry = 0;

                for (i = 0; i < classwords; i++) {

                    entry *= rc->classifications;

                    entry += classes[j][p + i];

                }

                put_codeword(pb, book, entry);

            }

            for (i = 0; i < classwords && p < partitions; i++, p++) {

                for (j = 0; j < channels; j++) {

                    int nbook = rc->books[classes[j][p]][pass];

                    codebook_t * book = &venc->codebooks[nbook];

                    float * buf = coeffs + samples*j + rc->begin + p*psize;

                    if (nbook == -1) continue;



                    assert(rc->type == 0 || rc->type == 2);

                    assert(!(psize % book->ndimentions));



                    if (rc->type == 0) {

                        for (k = 0; k < psize; k += book->ndimentions) {

                            float * a = put_vector(book, pb, &buf[k]);

                            int l;

                            for (l = 0; l < book->ndimentions; l++) buf[k + l] -= a[l];

                        }

                    } else {

                        for (k = 0; k < psize; k += book->ndimentions) {

                            int dim = book->ndimentions, s = rc->begin + p * psize + k, l;

                            float vec[dim], * a = vec;

                            for (l = s; l < s + dim; l++)

                                *a++ = coeffs[(l % real_ch) * samples + l / real_ch];

                            a = put_vector(book, pb, vec);

                            for (l = s; l < s + dim; l++)

                                coeffs[(l % real_ch) * samples + l / real_ch] -= *a++;

                        }

                    }

                }

            }

        }

    }

}

static void ff_compute_band_indexes(MPADecodeContext *s, GranuleDef *g)

{

    if (g->block_type == 2) {

        if (g->switch_point) {

            /* if switched mode, we handle the 36 first samples as

                long blocks.  For 8000Hz, we handle the 72 first

                exponents as long blocks */

            if (s->sample_rate_index <= 2)

                g->long_end = 8;

            else

                g->long_end = 6;



            g->short_start = 2 + (s->sample_rate_index != 8);

        } else {

            g->long_end    = 0;

            g->short_start = 0;

        }

    } else {

        g->short_start = 13;

        g->long_end    = 22;

    }

}

