static void yuv_from_cqt(ColorFloat *c, const FFTComplex *v, float gamma, int len)

{

    int x;

    for (x = 0; x < len; x++) {

        float r, g, b;

        r = calculate_gamma(FFMIN(1.0f, v[x].re), gamma);

        g = calculate_gamma(FFMIN(1.0f, 0.5f * (v[x].re + v[x].im)), gamma);

        b = calculate_gamma(FFMIN(1.0f, v[x].im), gamma);

        c[x].yuv.y = 16.0f + 65.481f * r + 128.553f * g + 24.966f * b;

        c[x].yuv.u = 128.0f - 37.797f * r - 74.203f * g + 112.0f * b;

        c[x].yuv.v = 128.0f + 112.0f * r - 93.786f * g - 18.214 * b;

    }

}

static int rtsp_read_packet(AVFormatContext *s, AVPacket *pkt)

{

    RTSPState *rt = s->priv_data;

    int ret;

    RTSPMessageHeader reply1, *reply = &reply1;

    char cmd[1024];



    if (rt->server_type == RTSP_SERVER_REAL) {

        int i;

        enum AVDiscard cache[MAX_STREAMS];



        for (i = 0; i < s->nb_streams; i++)

            cache[i] = s->streams[i]->discard;



        if (!rt->need_subscription) {

            if (memcmp (cache, rt->real_setup_cache,

                        sizeof(enum AVDiscard) * s->nb_streams)) {

                av_strlcatf(cmd, sizeof(cmd),

                            "SET_PARAMETER %s RTSP/1.0\r\n"

                            "Unsubscribe: %s\r\n",

                            s->filename, rt->last_subscription);

                rtsp_send_cmd(s, cmd, reply, NULL);

                if (reply->status_code != RTSP_STATUS_OK)

                    return AVERROR_INVALIDDATA;

                rt->need_subscription = 1;

            }

        }



        if (rt->need_subscription) {

            int r, rule_nr, first = 1;



            memcpy(rt->real_setup_cache, cache,

                   sizeof(enum AVDiscard) * s->nb_streams);

            rt->last_subscription[0] = 0;



            snprintf(cmd, sizeof(cmd),

                     "SET_PARAMETER %s RTSP/1.0\r\n"

                     "Subscribe: ",

                     s->filename);

            for (i = 0; i < rt->nb_rtsp_streams; i++) {

                rule_nr = 0;

                for (r = 0; r < s->nb_streams; r++) {

                    if (s->streams[r]->priv_data == rt->rtsp_streams[i]) {

                        if (s->streams[r]->discard != AVDISCARD_ALL) {

                            if (!first)

                                av_strlcat(rt->last_subscription, ",",

                                           sizeof(rt->last_subscription));

                            ff_rdt_subscribe_rule(

                                rt->last_subscription,

                                sizeof(rt->last_subscription), i, rule_nr);

                            first = 0;

                        }

                        rule_nr++;

                    }

                }

            }

            av_strlcatf(cmd, sizeof(cmd), "%s\r\n", rt->last_subscription);

            rtsp_send_cmd(s, cmd, reply, NULL);

            if (reply->status_code != RTSP_STATUS_OK)

                return AVERROR_INVALIDDATA;

            rt->need_subscription = 0;



            if (rt->state == RTSP_STATE_PLAYING)

                rtsp_read_play (s);

        }

    }



    ret = rtsp_fetch_packet(s, pkt);

    if (ret < 0)

        return ret;



    /* send dummy request to keep TCP connection alive */

    if ((rt->server_type == RTSP_SERVER_WMS ||

         rt->server_type == RTSP_SERVER_REAL) &&

        (av_gettime() - rt->last_cmd_time) / 1000000 >= rt->timeout / 2) {

        if (rt->server_type == RTSP_SERVER_WMS) {

            snprintf(cmd, sizeof(cmd) - 1,

                     "GET_PARAMETER %s RTSP/1.0\r\n",

                     s->filename);

            rtsp_send_cmd_async(s, cmd, reply, NULL);

        } else {

            rtsp_send_cmd_async(s, "OPTIONS * RTSP/1.0\r\n",

                                reply, NULL);

        }

    }



    return 0;

}

static int split_field_half_ref_list(Picture *dest, int dest_len,

                                     Picture *src,  int src_len,  int parity){

    int same_parity   = 1;

    int same_i        = 0;

    int opp_i         = 0;

    int out_i;

    int field_output;



    for (out_i = 0; out_i < dest_len; out_i += field_output) {

        if (same_parity && same_i < src_len) {

            field_output = split_field_copy(dest + out_i, src + same_i,

                                            parity, 1);

            same_parity = !field_output;

            same_i++;



        } else if (opp_i < src_len) {

            field_output = split_field_copy(dest + out_i, src + opp_i,

                                            PICT_FRAME - parity, 0);

            same_parity = field_output;

            opp_i++;



        } else {

            break;

        }

    }



    return out_i;

}

static void count_usage(uint8_t *src, int width,

                        int height, uint32_t *counts)

{

    int i, j;



    for (j = 0; j < height; j++) {

        for (i = 0; i < width; i++) {

            counts[src[i]]++;

        }

        src += width;

    }

}

void ff_rtp_send_hevc(AVFormatContext *ctx, const uint8_t *frame_buf, int frame_size)

{

    const uint8_t *next_NAL_unit;

    const uint8_t *buf_ptr, *buf_end = frame_buf + frame_size;

    RTPMuxContext *rtp_ctx = ctx->priv_data;



    /* use the default 90 KHz time stamp */

    rtp_ctx->timestamp = rtp_ctx->cur_timestamp;

    rtp_ctx->buf_ptr   = rtp_ctx->buf;



    if (rtp_ctx->nal_length_size)

        buf_ptr = ff_avc_mp4_find_startcode(frame_buf, buf_end, rtp_ctx->nal_length_size) ? frame_buf : buf_end;

    else

        buf_ptr = ff_avc_find_startcode(frame_buf, buf_end);



    /* find all NAL units and send them as separate packets */

    while (buf_ptr < buf_end) {

        if (rtp_ctx->nal_length_size) {

            next_NAL_unit = ff_avc_mp4_find_startcode(buf_ptr, buf_end, rtp_ctx->nal_length_size);

            if (!next_NAL_unit)

                next_NAL_unit = buf_end;



            buf_ptr += rtp_ctx->nal_length_size;

        } else {

            while (!*(buf_ptr++))

                ;

            next_NAL_unit = ff_avc_find_startcode(buf_ptr, buf_end);

        }

        /* send the next NAL unit */

        nal_send(ctx, buf_ptr, next_NAL_unit - buf_ptr, next_NAL_unit == buf_end);



        /* jump to the next NAL unit */

        buf_ptr = next_NAL_unit;

    }

    flush_buffered(ctx, 1);

}

static inline int dc1394_read_common(AVFormatContext *c, AVFormatParameters *ap,

                                     struct dc1394_frame_format **select_fmt, struct dc1394_frame_rate **select_fps)

{

    dc1394_data* dc1394 = c->priv_data;

    AVStream* vst;

    struct dc1394_frame_format *fmt;

    struct dc1394_frame_rate *fps;

    enum PixelFormat pix_fmt;

    int width, height;

    AVRational framerate;

    int ret = 0;



    if ((pix_fmt = av_get_pix_fmt(dc1394->pixel_format)) == PIX_FMT_NONE) {

        av_log(c, AV_LOG_ERROR, "No such pixel format: %s.\n", dc1394->pixel_format);

        ret = AVERROR(EINVAL);

        goto out;

    }



    if ((ret = av_parse_video_size(&width, &height, dc1394->video_size)) < 0) {

        av_log(c, AV_LOG_ERROR, "Couldn't parse video size.\n");

        goto out;

    }

    if ((ret = av_parse_video_rate(&framerate, dc1394->framerate)) < 0) {

        av_log(c, AV_LOG_ERROR, "Couldn't parse framerate.\n");

        goto out;

    }

#if FF_API_FORMAT_PARAMETERS

    if (ap->width > 0)

        width = ap->width;

    if (ap->height > 0)

        height = ap->height;

    if (ap->pix_fmt)

        pix_fmt = ap->pix_fmt;

    if (ap->time_base.num)

        framerate = (AVRational){ap->time_base.den, ap->time_base.num};

#endif

    dc1394->frame_rate = av_rescale(1000, framerate.num, framerate.den);



    for (fmt = dc1394_frame_formats; fmt->width; fmt++)

         if (fmt->pix_fmt == pix_fmt && fmt->width == width && fmt->height == height)

             break;



    for (fps = dc1394_frame_rates; fps->frame_rate; fps++)

         if (fps->frame_rate == dc1394->frame_rate)

             break;



    if (!fps->frame_rate || !fmt->width) {

        av_log(c, AV_LOG_ERROR, "Can't find matching camera format for %s, %dx%d@%d:1000fps\n", av_get_pix_fmt_name(pix_fmt),

                                                                                                width, height, dc1394->frame_rate);

        ret = AVERROR(EINVAL);

        goto out;

    }



    /* create a video stream */

    vst = av_new_stream(c, 0);

    if (!vst) {

        ret = AVERROR(ENOMEM);

        goto out;

    }

    av_set_pts_info(vst, 64, 1, 1000);

    vst->codec->codec_type = AVMEDIA_TYPE_VIDEO;

    vst->codec->codec_id = CODEC_ID_RAWVIDEO;

    vst->codec->time_base.den = framerate.num;

    vst->codec->time_base.num = framerate.den;

    vst->codec->width = fmt->width;

    vst->codec->height = fmt->height;

    vst->codec->pix_fmt = fmt->pix_fmt;



    /* packet init */

    av_init_packet(&dc1394->packet);

    dc1394->packet.size = avpicture_get_size(fmt->pix_fmt, fmt->width, fmt->height);

    dc1394->packet.stream_index = vst->index;

    dc1394->packet.flags |= AV_PKT_FLAG_KEY;



    dc1394->current_frame = 0;



    vst->codec->bit_rate = av_rescale(dc1394->packet.size * 8, fps->frame_rate, 1000);

    *select_fps = fps;

    *select_fmt = fmt;

out:

    return ret;

}

int av_tempfile(const char *prefix, char **filename, int log_offset, void *log_ctx) {

    FileLogContext file_log_ctx = { &file_log_ctx_class, log_offset, log_ctx };

    int fd=-1;

#if !HAVE_MKSTEMP

    void *ptr= tempnam(NULL, prefix);

    if(!ptr)

        ptr= tempnam(".", prefix);

    *filename = av_strdup(ptr);

#undef free

    free(ptr);

#else

    size_t len = strlen(prefix) + 12; /* room for "/tmp/" and "XXXXXX\0" */

    *filename = av_malloc(len);

#endif

    /* -----common section-----*/

    if (*filename == NULL) {

        av_log(&file_log_ctx, AV_LOG_ERROR, "ff_tempfile: Cannot allocate file name\n");

        return AVERROR(ENOMEM);

    }

#if !HAVE_MKSTEMP

#   ifndef O_BINARY

#       define O_BINARY 0

#   endif

#   ifndef O_EXCL

#       define O_EXCL 0

#   endif

    fd = open(*filename, O_RDWR | O_BINARY | O_CREAT | O_EXCL, 0600);

#else

    snprintf(*filename, len, "/tmp/%sXXXXXX", prefix);

    fd = mkstemp(*filename);

#ifdef _WIN32

    if (fd < 0) {

        snprintf(*filename, len, "./%sXXXXXX", prefix);

        fd = mkstemp(*filename);

    }

#endif

#endif

    /* -----common section-----*/

    if (fd < 0) {

        int err = AVERROR(errno);

        av_log(&file_log_ctx, AV_LOG_ERROR, "ff_tempfile: Cannot open temporary file %s\n", *filename);


        return err;

    }

    return fd; /* success */

}

static int decode_frame_header(NUTContext *nut, int *flags_ret, int64_t *pts, int *stream_id, int frame_code){

    AVFormatContext *s= nut->avf;

    ByteIOContext *bc = &s->pb;

    StreamContext *stc;

    int size, flags, size_mul, pts_delta, i, reserved_count;

    uint64_t tmp;



    if(url_ftell(bc) > nut->last_syncpoint_pos + nut->max_distance){

        av_log(s, AV_LOG_ERROR, "last frame must have been damaged %Ld > %Ld + %d\n", url_ftell(bc), nut->last_syncpoint_pos, nut->max_distance);

        return -1;

    }



    flags          = nut->frame_code[frame_code].flags;

    size_mul       = nut->frame_code[frame_code].size_mul;

    size           = nut->frame_code[frame_code].size_lsb;

    *stream_id     = nut->frame_code[frame_code].stream_id;

    pts_delta      = nut->frame_code[frame_code].pts_delta;

    reserved_count = nut->frame_code[frame_code].reserved_count;



    if(flags & FLAG_INVALID)

        return -1;

    if(flags & FLAG_CODED)

        flags ^= get_v(bc);

    if(flags & FLAG_STREAM_ID){

        GET_V(*stream_id, tmp < s->nb_streams)

    }

    stc= &nut->stream[*stream_id];

    if(flags&FLAG_CODED_PTS){

        int coded_pts= get_v(bc);

//FIXME check last_pts validity?

        if(coded_pts < (1<<stc->msb_pts_shift)){

            *pts=lsb2full(stc, coded_pts);

        }else

            *pts=coded_pts - (1<<stc->msb_pts_shift);

    }else

        *pts= stc->last_pts + pts_delta;

    if(flags&FLAG_SIZE_MSB){

        size += size_mul*get_v(bc);

    }

    if(flags&FLAG_RESERVED)

        reserved_count= get_v(bc);

    for(i=0; i<reserved_count; i++)

        get_v(bc);

    if(flags&FLAG_CHECKSUM){

        get_be32(bc); //FIXME check this

    }else if(size > 2*nut->max_distance){

        av_log(s, AV_LOG_ERROR, "frame size > 2max_distance and no checksum\n");

        return -1;

    }

    *flags_ret= flags;



    stc->last_pts= *pts;

    stc->last_key_frame= flags&FLAG_KEY; //FIXME change to last flags



    return size;

}

static av_cold int alac_encode_init(AVCodecContext *avctx)

{

    AlacEncodeContext *s = avctx->priv_data;

    int ret;

    uint8_t *alac_extradata;



    avctx->frame_size = s->frame_size = DEFAULT_FRAME_SIZE;



    if (avctx->sample_fmt != AV_SAMPLE_FMT_S16) {

        av_log(avctx, AV_LOG_ERROR, "only pcm_s16 input samples are supported\n");

        return -1;

    }



    /* TODO: Correctly implement multi-channel ALAC.

             It is similar to multi-channel AAC, in that it has a series of

             single-channel (SCE), channel-pair (CPE), and LFE elements. */

    if (avctx->channels > 2) {

        av_log(avctx, AV_LOG_ERROR, "only mono or stereo input is currently supported\n");

        return AVERROR_PATCHWELCOME;

    }



    // Set default compression level

    if (avctx->compression_level == FF_COMPRESSION_DEFAULT)

        s->compression_level = 2;

    else

        s->compression_level = av_clip(avctx->compression_level, 0, 2);



    // Initialize default Rice parameters

    s->rc.history_mult    = 40;

    s->rc.initial_history = 10;

    s->rc.k_modifier      = 14;

    s->rc.rice_modifier   = 4;



    s->max_coded_frame_size = get_max_frame_size(avctx->frame_size,

                                                 avctx->channels,

                                                 DEFAULT_SAMPLE_SIZE);



    // FIXME: consider wasted_bytes

    s->write_sample_size  = DEFAULT_SAMPLE_SIZE + avctx->channels - 1;



    avctx->extradata = av_mallocz(ALAC_EXTRADATA_SIZE + FF_INPUT_BUFFER_PADDING_SIZE);

    if (!avctx->extradata) {

        ret = AVERROR(ENOMEM);

        goto error;

    }

    avctx->extradata_size = ALAC_EXTRADATA_SIZE;



    alac_extradata = avctx->extradata;

    AV_WB32(alac_extradata,    ALAC_EXTRADATA_SIZE);

    AV_WB32(alac_extradata+4,  MKBETAG('a','l','a','c'));

    AV_WB32(alac_extradata+12, avctx->frame_size);

    AV_WB8 (alac_extradata+17, DEFAULT_SAMPLE_SIZE);

    AV_WB8 (alac_extradata+21, avctx->channels);

    AV_WB32(alac_extradata+24, s->max_coded_frame_size);

    AV_WB32(alac_extradata+28,

            avctx->sample_rate * avctx->channels * DEFAULT_SAMPLE_SIZE); // average bitrate

    AV_WB32(alac_extradata+32, avctx->sample_rate);



    // Set relevant extradata fields

    if (s->compression_level > 0) {

        AV_WB8(alac_extradata+18, s->rc.history_mult);

        AV_WB8(alac_extradata+19, s->rc.initial_history);

        AV_WB8(alac_extradata+20, s->rc.k_modifier);

    }



    s->min_prediction_order = DEFAULT_MIN_PRED_ORDER;

    if (avctx->min_prediction_order >= 0) {

        if (avctx->min_prediction_order < MIN_LPC_ORDER ||

           avctx->min_prediction_order > ALAC_MAX_LPC_ORDER) {

            av_log(avctx, AV_LOG_ERROR, "invalid min prediction order: %d\n",

                   avctx->min_prediction_order);

            ret = AVERROR(EINVAL);

            goto error;

        }



        s->min_prediction_order = avctx->min_prediction_order;

    }



    s->max_prediction_order = DEFAULT_MAX_PRED_ORDER;

    if (avctx->max_prediction_order >= 0) {

        if (avctx->max_prediction_order < MIN_LPC_ORDER ||

            avctx->max_prediction_order > ALAC_MAX_LPC_ORDER) {

            av_log(avctx, AV_LOG_ERROR, "invalid max prediction order: %d\n",

                   avctx->max_prediction_order);

            ret = AVERROR(EINVAL);

            goto error;

        }



        s->max_prediction_order = avctx->max_prediction_order;

    }



    if (s->max_prediction_order < s->min_prediction_order) {

        av_log(avctx, AV_LOG_ERROR,

               "invalid prediction orders: min=%d max=%d\n",

               s->min_prediction_order, s->max_prediction_order);

        ret = AVERROR(EINVAL);

        goto error;

    }



    avctx->coded_frame = avcodec_alloc_frame();

    if (!avctx->coded_frame) {

        ret = AVERROR(ENOMEM);

        goto error;

    }



    s->avctx = avctx;



    if ((ret = ff_lpc_init(&s->lpc_ctx, avctx->frame_size,

                           s->max_prediction_order,

                           FF_LPC_TYPE_LEVINSON)) < 0) {

        goto error;

    }



    return 0;

error:

    alac_encode_close(avctx);

    return ret;

}

static int rv34_decode_mv(RV34DecContext *r, int block_type)

{

    MpegEncContext *s = &r->s;

    GetBitContext *gb = &s->gb;

    int i, j, k, l;

    int mv_pos = s->mb_x * 2 + s->mb_y * 2 * s->b8_stride;

    int next_bt;



    memset(r->dmv, 0, sizeof(r->dmv));

    for(i = 0; i < num_mvs[block_type]; i++){

        r->dmv[i][0] = get_interleaved_se_golomb(gb);

        r->dmv[i][1] = get_interleaved_se_golomb(gb);







    switch(block_type){

    case RV34_MB_TYPE_INTRA:

    case RV34_MB_TYPE_INTRA16x16:

        ZERO8x2(s->current_picture_ptr->motion_val[0][s->mb_x * 2 + s->mb_y * 2 * s->b8_stride], s->b8_stride);

        return 0;

    case RV34_MB_SKIP:

        if(s->pict_type == AV_PICTURE_TYPE_P){

            ZERO8x2(s->current_picture_ptr->motion_val[0][s->mb_x * 2 + s->mb_y * 2 * s->b8_stride], s->b8_stride);

            rv34_mc_1mv (r, block_type, 0, 0, 0, 2, 2, 0);

            break;


    case RV34_MB_B_DIRECT:

        //surprisingly, it uses motion scheme from next reference frame

        /* wait for the current mb row to be finished */

        if (HAVE_THREADS && (s->avctx->active_thread_type & FF_THREAD_FRAME))

            ff_thread_await_progress(&s->next_picture_ptr->tf, FFMAX(0, s->mb_y-1), 0);



        next_bt = s->next_picture_ptr->mb_type[s->mb_x + s->mb_y * s->mb_stride];

        if(IS_INTRA(next_bt) || IS_SKIP(next_bt)){

            ZERO8x2(s->current_picture_ptr->motion_val[0][s->mb_x * 2 + s->mb_y * 2 * s->b8_stride], s->b8_stride);

            ZERO8x2(s->current_picture_ptr->motion_val[1][s->mb_x * 2 + s->mb_y * 2 * s->b8_stride], s->b8_stride);

        }else

            for(j = 0; j < 2; j++)

                for(i = 0; i < 2; i++)

                    for(k = 0; k < 2; k++)

                        for(l = 0; l < 2; l++)

                            s->current_picture_ptr->motion_val[l][mv_pos + i + j*s->b8_stride][k] = calc_add_mv(r, l, s->next_picture_ptr->motion_val[0][mv_pos + i + j*s->b8_stride][k]);

        if(!(IS_16X8(next_bt) || IS_8X16(next_bt) || IS_8X8(next_bt))) //we can use whole macroblock MC

            rv34_mc_2mv(r, block_type);

        else

            rv34_mc_2mv_skip(r);

        ZERO8x2(s->current_picture_ptr->motion_val[0][s->mb_x * 2 + s->mb_y * 2 * s->b8_stride], s->b8_stride);

        break;

    case RV34_MB_P_16x16:

    case RV34_MB_P_MIX16x16:

        rv34_pred_mv(r, block_type, 0, 0);

        rv34_mc_1mv (r, block_type, 0, 0, 0, 2, 2, 0);

        break;

    case RV34_MB_B_FORWARD:

    case RV34_MB_B_BACKWARD:

        r->dmv[1][0] = r->dmv[0][0];

        r->dmv[1][1] = r->dmv[0][1];

        if(r->rv30)

            rv34_pred_mv_rv3(r, block_type, block_type == RV34_MB_B_BACKWARD);

        else

            rv34_pred_mv_b  (r, block_type, block_type == RV34_MB_B_BACKWARD);

        rv34_mc_1mv     (r, block_type, 0, 0, 0, 2, 2, block_type == RV34_MB_B_BACKWARD);

        break;

    case RV34_MB_P_16x8:

    case RV34_MB_P_8x16:

        rv34_pred_mv(r, block_type, 0, 0);

        rv34_pred_mv(r, block_type, 1 + (block_type == RV34_MB_P_16x8), 1);

        if(block_type == RV34_MB_P_16x8){

            rv34_mc_1mv(r, block_type, 0, 0, 0,            2, 1, 0);

            rv34_mc_1mv(r, block_type, 0, 8, s->b8_stride, 2, 1, 0);


        if(block_type == RV34_MB_P_8x16){

            rv34_mc_1mv(r, block_type, 0, 0, 0, 1, 2, 0);

            rv34_mc_1mv(r, block_type, 8, 0, 1, 1, 2, 0);


        break;

    case RV34_MB_B_BIDIR:

        rv34_pred_mv_b  (r, block_type, 0);

        rv34_pred_mv_b  (r, block_type, 1);

        rv34_mc_2mv     (r, block_type);

        break;

    case RV34_MB_P_8x8:

        for(i=0;i< 4;i++){

            rv34_pred_mv(r, block_type, i, i);

            rv34_mc_1mv (r, block_type, (i&1)<<3, (i&2)<<2, (i&1)+(i>>1)*s->b8_stride, 1, 1, 0);


        break;




    return 0;

