static int ogg_packet(AVFormatContext *s, int *str, int *dstart, int *dsize,

                      int64_t *fpos)

{

    struct ogg *ogg = s->priv_data;

    int idx, i, ret;

    struct ogg_stream *os;

    int complete = 0;

    int segp = 0, psize = 0;



    av_dlog(s, "ogg_packet: curidx=%i\n", ogg->curidx);



    do{

        idx = ogg->curidx;



        while (idx < 0){

            ret = ogg_read_page(s, &idx);

            if (ret < 0)

                return ret;

        }



        os = ogg->streams + idx;



        av_dlog(s, "ogg_packet: idx=%d pstart=%d psize=%d segp=%d nsegs=%d\n",

                idx, os->pstart, os->psize, os->segp, os->nsegs);



        if (!os->codec){

            if (os->header < 0){

                os->codec = ogg_find_codec (os->buf, os->bufpos);

                if (!os->codec){

                    av_log(s, AV_LOG_WARNING, "Codec not found\n");

                    os->header = 0;

                    return 0;

                }

            }else{

                return 0;

            }

        }



        segp = os->segp;

        psize = os->psize;



        while (os->segp < os->nsegs){

            int ss = os->segments[os->segp++];

            os->psize += ss;

            if (ss < 255){

                complete = 1;

                break;

            }

        }



        if (!complete && os->segp == os->nsegs){

            ogg->curidx = -1;

            os->incomplete = 1;

        }

    }while (!complete);





    if (os->granule == -1)

        av_log(s, AV_LOG_WARNING, "Page at %"PRId64" is missing granule\n", os->page_pos);



    ogg->curidx = idx;

    os->incomplete = 0;



    if (os->header) {

        os->header = os->codec->header (s, idx);

        if (!os->header){

            os->segp = segp;

            os->psize = psize;



            // We have reached the first non-header packet in this stream.

            // Unfortunately more header packets may still follow for others,

            // but if we continue with header parsing we may lose data packets.

            ogg->headers = 1;



            // Update the header state for all streams and

            // compute the data_offset.

            if (!s->data_offset)

                s->data_offset = os->sync_pos;

            for (i = 0; i < ogg->nstreams; i++) {

                struct ogg_stream *cur_os = ogg->streams + i;



                // if we have a partial non-header packet, its start is

                // obviously at or after the data start

                if (cur_os->incomplete)

                    s->data_offset = FFMIN(s->data_offset, cur_os->sync_pos);

            }

        }else{

            os->pstart += os->psize;

            os->psize = 0;

        }

    } else {

        os->pflags = 0;

        os->pduration = 0;

        if (os->codec && os->codec->packet)

            os->codec->packet (s, idx);

        if (str)

            *str = idx;

        if (dstart)

            *dstart = os->pstart;

        if (dsize)

            *dsize = os->psize;

        if (fpos)

            *fpos = os->sync_pos;

        os->pstart += os->psize;

        os->psize = 0;

        if(os->pstart == os->bufpos)

            os->bufpos = os->pstart = 0;

        os->sync_pos = os->page_pos;

    }



    // determine whether there are more complete packets in this page

    // if not, the page's granule will apply to this packet

    os->page_end = 1;

    for (i = os->segp; i < os->nsegs; i++)

        if (os->segments[i] < 255) {

            os->page_end = 0;

            break;

        }



    if (os->segp == os->nsegs)

        ogg->curidx = -1;



    return 0;

}

void av_log_default_callback(void* ptr, int level, const char* fmt, va_list vl)

{

    static int print_prefix = 1;

    static int count;

    static char prev[LINE_SZ];

    AVBPrint part[4];

    char line[LINE_SZ];

    static int is_atty;

    int type[2];

    unsigned tint = 0;



    if (level >= 0) {

        tint = level & 0xff00;

        level &= 0xff;

    }



    if (level > av_log_level)

        return;

#if HAVE_PTHREADS

    pthread_mutex_lock(&mutex);

#endif



    format_line(ptr, level, fmt, vl, part, &print_prefix, type);

    snprintf(line, sizeof(line), "%s%s%s%s", part[0].str, part[1].str, part[2].str, part[3].str);



#if HAVE_ISATTY

    if (!is_atty)

        is_atty = isatty(2) ? 1 : -1;

#endif



    if (print_prefix && (flags & AV_LOG_SKIP_REPEATED) && !strcmp(line, prev) &&

        *line && line[strlen(line) - 1] != '\r'){

        count++;

        if (is_atty == 1)

            fprintf(stderr, "    Last message repeated %d times\r", count);

        goto end;

    }

    if (count > 0) {

        fprintf(stderr, "    Last message repeated %d times\n", count);

        count = 0;

    }

    strcpy(prev, line);

    sanitize(part[0].str);

    colored_fputs(type[0], 0, part[0].str);

    sanitize(part[1].str);

    colored_fputs(type[1], 0, part[1].str);

    sanitize(part[2].str);

    colored_fputs(av_clip(level >> 3, 0, NB_LEVELS - 1), tint >> 8, part[2].str);

    sanitize(part[3].str);

    colored_fputs(av_clip(level >> 3, 0, NB_LEVELS - 1), tint >> 8, part[3].str);



#if CONFIG_VALGRIND_BACKTRACE

    if (level <= BACKTRACE_LOGLEVEL)

        VALGRIND_PRINTF_BACKTRACE("%s", "");

#endif

end:

    av_bprint_finalize(part+3, NULL);

#if HAVE_PTHREADS

    pthread_mutex_unlock(&mutex);

#endif

}

int ff_parse_mpeg2_descriptor(AVFormatContext *fc, AVStream *st, int stream_type,

                              const uint8_t **pp, const uint8_t *desc_list_end,

                              Mp4Descr *mp4_descr, int mp4_descr_count, int pid,

                              MpegTSContext *ts)

{

    const uint8_t *desc_end;

    int desc_len, desc_tag, desc_es_id;

    char language[252];

    int i;



    desc_tag = get8(pp, desc_list_end);

    if (desc_tag < 0)

        return AVERROR_INVALIDDATA;

    desc_len = get8(pp, desc_list_end);

    if (desc_len < 0)

        return AVERROR_INVALIDDATA;

    desc_end = *pp + desc_len;

    if (desc_end > desc_list_end)

        return AVERROR_INVALIDDATA;



    av_dlog(fc, "tag: 0x%02x len=%d\n", desc_tag, desc_len);



    if (st->codec->codec_id == AV_CODEC_ID_NONE &&

        stream_type == STREAM_TYPE_PRIVATE_DATA)

        mpegts_find_stream_type(st, desc_tag, DESC_types);



    switch (desc_tag) {

    case 0x1E: /* SL descriptor */

        desc_es_id = get16(pp, desc_end);

        if (ts && ts->pids[pid])

            ts->pids[pid]->es_id = desc_es_id;

        for (i = 0; i < mp4_descr_count; i++)

            if (mp4_descr[i].dec_config_descr_len &&

                mp4_descr[i].es_id == desc_es_id) {

                AVIOContext pb;

                ffio_init_context(&pb, mp4_descr[i].dec_config_descr,

                                  mp4_descr[i].dec_config_descr_len, 0,

                                  NULL, NULL, NULL, NULL);

                ff_mp4_read_dec_config_descr(fc, st, &pb);

                if (st->codec->codec_id == AV_CODEC_ID_AAC &&

                    st->codec->extradata_size > 0)

                    st->need_parsing = 0;

                if (st->codec->codec_id == AV_CODEC_ID_MPEG4SYSTEMS)

                    mpegts_open_section_filter(ts, pid, m4sl_cb, ts, 1);

            }

        break;

    case 0x1F: /* FMC descriptor */

        get16(pp, desc_end);

        if (mp4_descr_count > 0 &&

            st->codec->codec_id == AV_CODEC_ID_AAC_LATM &&

            mp4_descr->dec_config_descr_len && mp4_descr->es_id == pid) {

            AVIOContext pb;

            ffio_init_context(&pb, mp4_descr->dec_config_descr,

                              mp4_descr->dec_config_descr_len, 0,

                              NULL, NULL, NULL, NULL);

            ff_mp4_read_dec_config_descr(fc, st, &pb);

            if (st->codec->codec_id == AV_CODEC_ID_AAC &&

                st->codec->extradata_size > 0)

                st->need_parsing = 0;

        }

        break;

    case 0x56: /* DVB teletext descriptor */

        language[0] = get8(pp, desc_end);

        language[1] = get8(pp, desc_end);

        language[2] = get8(pp, desc_end);

        language[3] = 0;

        av_dict_set(&st->metadata, "language", language, 0);

        break;

    case 0x59: /* subtitling descriptor */

        language[0] = get8(pp, desc_end);

        language[1] = get8(pp, desc_end);

        language[2] = get8(pp, desc_end);

        language[3] = 0;

        /* hearing impaired subtitles detection */

        switch (get8(pp, desc_end)) {

        case 0x20: /* DVB subtitles (for the hard of hearing) with no monitor aspect ratio criticality */

        case 0x21: /* DVB subtitles (for the hard of hearing) for display on 4:3 aspect ratio monitor */

        case 0x22: /* DVB subtitles (for the hard of hearing) for display on 16:9 aspect ratio monitor */

        case 0x23: /* DVB subtitles (for the hard of hearing) for display on 2.21:1 aspect ratio monitor */

        case 0x24: /* DVB subtitles (for the hard of hearing) for display on a high definition monitor */

        case 0x25: /* DVB subtitles (for the hard of hearing) with plano-stereoscopic disparity for display on a high definition monitor */

            st->disposition |= AV_DISPOSITION_HEARING_IMPAIRED;

            break;

        }

        if (st->codec->extradata) {

            if (st->codec->extradata_size == 4 &&

                memcmp(st->codec->extradata, *pp, 4))

                avpriv_request_sample(fc, "DVB sub with multiple IDs");

        } else {

            st->codec->extradata = av_malloc(4 + FF_INPUT_BUFFER_PADDING_SIZE);

            if (st->codec->extradata) {

                st->codec->extradata_size = 4;

                memcpy(st->codec->extradata, *pp, 4);

            }

        }

        *pp += 4;

        av_dict_set(&st->metadata, "language", language, 0);

        break;

    case 0x0a: /* ISO 639 language descriptor */

        for (i = 0; i + 4 <= desc_len; i += 4) {

            language[i + 0] = get8(pp, desc_end);

            language[i + 1] = get8(pp, desc_end);

            language[i + 2] = get8(pp, desc_end);

            language[i + 3] = ',';

            switch (get8(pp, desc_end)) {

            case 0x01:

                st->disposition |= AV_DISPOSITION_CLEAN_EFFECTS;

                break;

            case 0x02:

                st->disposition |= AV_DISPOSITION_HEARING_IMPAIRED;

                break;

            case 0x03:

                st->disposition |= AV_DISPOSITION_VISUAL_IMPAIRED;

                break;

            }

        }

        if (i && language[0]) {

            language[i - 1] = 0;

            av_dict_set(&st->metadata, "language", language, 0);

        }

        break;

    case 0x05: /* registration descriptor */

        st->codec->codec_tag = bytestream_get_le32(pp);

        av_dlog(fc, "reg_desc=%.4s\n", (char *)&st->codec->codec_tag);

        if (st->codec->codec_id == AV_CODEC_ID_NONE)

            mpegts_find_stream_type(st, st->codec->codec_tag, REGD_types);

        break;

    default:

        break;

    }

    *pp = desc_end;

    return 0;

}

void av_register_output_format(AVOutputFormat *format)

{

    AVOutputFormat **p = last_oformat;



    format->next = NULL;

    while(*p || avpriv_atomic_ptr_cas((void * volatile *)p, NULL, format))

        p = &(*p)->next;

    last_oformat = &format->next;

}

static void select_input_picture(MpegEncContext *s){

    int i;



    for(i=1; i<MAX_PICTURE_COUNT; i++)

        s->reordered_input_picture[i-1]= s->reordered_input_picture[i];

    s->reordered_input_picture[MAX_PICTURE_COUNT-1]= NULL;



    /* set next picture type & ordering */

    if(s->reordered_input_picture[0]==NULL && s->input_picture[0]){

        if(/*s->picture_in_gop_number >= s->gop_size ||*/ s->next_picture_ptr==NULL || s->intra_only){

            s->reordered_input_picture[0]= s->input_picture[0];

            s->reordered_input_picture[0]->pict_type= I_TYPE;

            s->reordered_input_picture[0]->coded_picture_number= s->coded_picture_number++;

        }else{

            int b_frames;



            if(s->avctx->frame_skip_threshold || s->avctx->frame_skip_factor){

                if(skip_check(s, s->input_picture[0], s->next_picture_ptr)){

//av_log(NULL, AV_LOG_DEBUG, "skip %p %Ld\n", s->input_picture[0]->data[0], s->input_picture[0]->pts);



                    if(s->input_picture[0]->type == FF_BUFFER_TYPE_SHARED){

                        for(i=0; i<4; i++)

                            s->input_picture[0]->data[i]= NULL;

                        s->input_picture[0]->type= 0;            

                    }else{

                        assert(   s->input_picture[0]->type==FF_BUFFER_TYPE_USER 

                               || s->input_picture[0]->type==FF_BUFFER_TYPE_INTERNAL);



                        s->avctx->release_buffer(s->avctx, (AVFrame*)s->input_picture[0]);

                    }



                    goto no_output_pic;

                }

            }



            if(s->flags&CODEC_FLAG_PASS2){

                for(i=0; i<s->max_b_frames+1; i++){

                    int pict_num= s->input_picture[0]->display_picture_number + i;



                    if(pict_num >= s->rc_context.num_entries) 

                        break;

                    if(!s->input_picture[i]){

                        s->rc_context.entry[pict_num-1].new_pict_type = P_TYPE;

                        break;

                    }



                    s->input_picture[i]->pict_type= 

                        s->rc_context.entry[pict_num].new_pict_type;

                }

            }



            if(s->avctx->b_frame_strategy==0){

                b_frames= s->max_b_frames;

                while(b_frames && !s->input_picture[b_frames]) b_frames--;

            }else if(s->avctx->b_frame_strategy==1){

                for(i=1; i<s->max_b_frames+1; i++){

                    if(s->input_picture[i] && s->input_picture[i]->b_frame_score==0){

                        s->input_picture[i]->b_frame_score= 

                            get_intra_count(s, s->input_picture[i  ]->data[0], 

                                               s->input_picture[i-1]->data[0], s->linesize) + 1;

                    }

                }

                for(i=0; i<s->max_b_frames+1; i++){

                    if(s->input_picture[i]==NULL || s->input_picture[i]->b_frame_score - 1 > s->mb_num/40) break;

                }



                b_frames= FFMAX(0, i-1);



                /* reset scores */

                for(i=0; i<b_frames+1; i++){

                    s->input_picture[i]->b_frame_score=0;

                }

            }else{

                av_log(s->avctx, AV_LOG_ERROR, "illegal b frame strategy\n");

                b_frames=0;

            }



            emms_c();

//static int b_count=0;

//b_count+= b_frames;

//av_log(s->avctx, AV_LOG_DEBUG, "b_frames: %d\n", b_count);



            for(i= b_frames - 1; i>=0; i--){

                int type= s->input_picture[i]->pict_type;

                if(type && type != B_TYPE)

                    b_frames= i;

            }

            if(s->input_picture[b_frames]->pict_type == B_TYPE && b_frames == s->max_b_frames){

                av_log(s->avctx, AV_LOG_ERROR, "warning, too many b frames in a row\n");

            }



            if(s->picture_in_gop_number + b_frames >= s->gop_size){

              if((s->flags2 & CODEC_FLAG2_STRICT_GOP) && s->gop_size > s->picture_in_gop_number){

                    b_frames= s->gop_size - s->picture_in_gop_number - 1;

              }else{

                if(s->flags & CODEC_FLAG_CLOSED_GOP)

                    b_frames=0;

                s->input_picture[b_frames]->pict_type= I_TYPE;

              }

            }



            if(   (s->flags & CODEC_FLAG_CLOSED_GOP)

               && b_frames

               && s->input_picture[b_frames]->pict_type== I_TYPE)

                b_frames--;



            s->reordered_input_picture[0]= s->input_picture[b_frames];

            if(s->reordered_input_picture[0]->pict_type != I_TYPE)

                s->reordered_input_picture[0]->pict_type= P_TYPE;

            s->reordered_input_picture[0]->coded_picture_number= s->coded_picture_number++;

            for(i=0; i<b_frames; i++){

                s->reordered_input_picture[i+1]= s->input_picture[i];

                s->reordered_input_picture[i+1]->pict_type= B_TYPE;

                s->reordered_input_picture[i+1]->coded_picture_number= s->coded_picture_number++;

            }

        }

    }

no_output_pic:

    if(s->reordered_input_picture[0]){

        s->reordered_input_picture[0]->reference= s->reordered_input_picture[0]->pict_type!=B_TYPE ? 3 : 0;



        copy_picture(&s->new_picture, s->reordered_input_picture[0]);



        if(s->reordered_input_picture[0]->type == FF_BUFFER_TYPE_SHARED){

            // input is a shared pix, so we can't modifiy it -> alloc a new one & ensure that the shared one is reuseable



            int i= ff_find_unused_picture(s, 0);

            Picture *pic= &s->picture[i];



            /* mark us unused / free shared pic */

            for(i=0; i<4; i++)

                s->reordered_input_picture[0]->data[i]= NULL;

            s->reordered_input_picture[0]->type= 0;



            pic->reference              = s->reordered_input_picture[0]->reference;



            alloc_picture(s, pic, 0);



            copy_picture_attributes(s, (AVFrame*)pic, (AVFrame*)s->reordered_input_picture[0]);



            s->current_picture_ptr= pic;

        }else{

            // input is not a shared pix -> reuse buffer for current_pix



            assert(   s->reordered_input_picture[0]->type==FF_BUFFER_TYPE_USER 

                   || s->reordered_input_picture[0]->type==FF_BUFFER_TYPE_INTERNAL);



            s->current_picture_ptr= s->reordered_input_picture[0];

            for(i=0; i<4; i++){

                s->new_picture.data[i]+=16;

            }

        }

        copy_picture(&s->current_picture, s->current_picture_ptr);



        s->picture_number= s->new_picture.display_picture_number;

//printf("dpn:%d\n", s->picture_number);

    }else{

       memset(&s->new_picture, 0, sizeof(Picture));

    }

}

static inline void xchg_mb_border(H264Context *h, uint8_t *src_y, uint8_t *src_cb, uint8_t *src_cr, int linesize, int uvlinesize, int xchg, int simple){

    MpegEncContext * const s = &h->s;

    int temp8, i;

    uint64_t temp64;

    int deblock_left;

    int deblock_top;

    int mb_xy;

    int step    = 1;

    int offset  = 1;

    int uvoffset= 1;

    int top_idx = 1;



    if(!simple && FRAME_MBAFF){

        if(s->mb_y&1){

            offset  = MB_MBAFF ? 1 : 17;

            uvoffset= MB_MBAFF ? 1 : 9;

        }else{

            offset  =

            uvoffset=

            top_idx = MB_MBAFF ? 0 : 1;

        }

        step= MB_MBAFF ? 2 : 1;

    }



    if(h->deblocking_filter == 2) {

        mb_xy = h->mb_xy;

        deblock_left = h->slice_table[mb_xy] == h->slice_table[mb_xy - 1];

        deblock_top  = h->slice_table[mb_xy] == h->slice_table[h->top_mb_xy];

    } else {

        deblock_left = (s->mb_x > 0);

        deblock_top =  (s->mb_y > !!MB_FIELD);

    }



    src_y  -=   linesize + 1;

    src_cb -= uvlinesize + 1;

    src_cr -= uvlinesize + 1;



#define XCHG(a,b,t,xchg)\

t= a;\

if(xchg)\

    a= b;\

b= t;



    if(deblock_left){

        for(i = !deblock_top; i<16; i++){

            XCHG(h->left_border[offset+i*step], src_y [i*  linesize], temp8, xchg);

        }

        XCHG(h->left_border[offset+i*step], src_y [i*  linesize], temp8, 1);

    }



    if(deblock_top){

        XCHG(*(uint64_t*)(h->top_borders[top_idx][s->mb_x]+0), *(uint64_t*)(src_y +1), temp64, xchg);

        XCHG(*(uint64_t*)(h->top_borders[top_idx][s->mb_x]+8), *(uint64_t*)(src_y +9), temp64, 1);

        if(s->mb_x+1 < s->mb_width){

            XCHG(*(uint64_t*)(h->top_borders[top_idx][s->mb_x+1]), *(uint64_t*)(src_y +17), temp64, 1);

        }

    }



    if(simple || !CONFIG_GRAY || !(s->flags&CODEC_FLAG_GRAY)){

        if(deblock_left){

            for(i = !deblock_top; i<8; i++){

                XCHG(h->left_border[uvoffset+34   +i*step], src_cb[i*uvlinesize], temp8, xchg);

                XCHG(h->left_border[uvoffset+34+18+i*step], src_cr[i*uvlinesize], temp8, xchg);

            }

            XCHG(h->left_border[uvoffset+34   +i*step], src_cb[i*uvlinesize], temp8, 1);

            XCHG(h->left_border[uvoffset+34+18+i*step], src_cr[i*uvlinesize], temp8, 1);

        }

        if(deblock_top){

            XCHG(*(uint64_t*)(h->top_borders[top_idx][s->mb_x]+16), *(uint64_t*)(src_cb+1), temp64, 1);

            XCHG(*(uint64_t*)(h->top_borders[top_idx][s->mb_x]+24), *(uint64_t*)(src_cr+1), temp64, 1);

        }

    }

}

static void rv34_pred_4x4_block(RV34DecContext *r, uint8_t *dst, int stride, int itype, int up, int left, int down, int right)

{

    uint8_t *prev = dst - stride + 4;

    uint32_t topleft;



    if(!up && !left)

        itype = DC_128_PRED;

    else if(!up){

        if(itype == VERT_PRED) itype = HOR_PRED;

        if(itype == DC_PRED)   itype = LEFT_DC_PRED;

    }else if(!left){

        if(itype == HOR_PRED)  itype = VERT_PRED;

        if(itype == DC_PRED)   itype = TOP_DC_PRED;

        if(itype == DIAG_DOWN_LEFT_PRED) itype = DIAG_DOWN_LEFT_PRED_RV40_NODOWN;

    }

    if(!down){

        if(itype == DIAG_DOWN_LEFT_PRED) itype = DIAG_DOWN_LEFT_PRED_RV40_NODOWN;

        if(itype == HOR_UP_PRED) itype = HOR_UP_PRED_RV40_NODOWN;

        if(itype == VERT_LEFT_PRED) itype = VERT_LEFT_PRED_RV40_NODOWN;

    }

    if(!right && up){

        topleft = dst[-stride + 3] * 0x01010101;

        prev = (uint8_t*)&topleft;

    }

    r->h.pred4x4[itype](dst, prev, stride);

}

static av_cold int MP3lame_encode_init(AVCodecContext *avctx)

{

    Mp3AudioContext *s = avctx->priv_data;



    if (avctx->channels > 2)

        return -1;



    s->stereo = avctx->channels > 1 ? 1 : 0;



    if ((s->gfp = lame_init()) == NULL)

        goto err;

    lame_set_in_samplerate(s->gfp, avctx->sample_rate);

    lame_set_out_samplerate(s->gfp, avctx->sample_rate);

    lame_set_num_channels(s->gfp, avctx->channels);

    if(avctx->compression_level == FF_COMPRESSION_DEFAULT) {

        lame_set_quality(s->gfp, 5);

    } else {

        lame_set_quality(s->gfp, avctx->compression_level);

    }

    lame_set_mode(s->gfp, s->stereo ? JOINT_STEREO : MONO);

    lame_set_brate(s->gfp, avctx->bit_rate/1000);

    if(avctx->flags & CODEC_FLAG_QSCALE) {

        lame_set_brate(s->gfp, 0);

        lame_set_VBR(s->gfp, vbr_default);

        lame_set_VBR_quality(s->gfp, avctx->global_quality/(float)FF_QP2LAMBDA);

    }

    lame_set_bWriteVbrTag(s->gfp,0);

    lame_set_disable_reservoir(s->gfp, avctx->flags2 & CODEC_FLAG2_BIT_RESERVOIR ? 0 : 1);

    if (lame_init_params(s->gfp) < 0)

        goto err_close;



    avctx->frame_size = lame_get_framesize(s->gfp);



    avctx->coded_frame= avcodec_alloc_frame();

    avctx->coded_frame->key_frame= 1;



    return 0;



err_close:

    lame_close(s->gfp);

err:

    return -1;

}

int av_strerror(int errnum, char *errbuf, size_t errbuf_size)

{

    int ret = 0;

    const char *errstr = NULL;



    switch (errnum) {

    case AVERROR_EOF:               errstr = "End of file"; break;

    case AVERROR_INVALIDDATA:       errstr = "Invalid data found when processing input"; break;

    case AVERROR_NUMEXPECTED:       errstr = "Number syntax expected in filename"; break;

    case AVERROR_PATCHWELCOME:      errstr = "Not yet implemented in FFmpeg, patches welcome"; break;

    }



    if (errstr) {

        av_strlcpy(errbuf, errstr, errbuf_size);

    } else {

#if HAVE_STRERROR_R

        ret = strerror_r(AVUNERROR(errnum), errbuf, errbuf_size);

#endif

        if (!HAVE_STRERROR_R || ret < 0)

            snprintf(errbuf, errbuf_size, "Error number %d occurred", errnum);

    }



    return ret;

}

static int h263_decode_gob_header(MpegEncContext *s)

{

    unsigned int val, gob_number;

    int left;



    /* Check for GOB Start Code */

    val = show_bits(&s->gb, 16);

    if(val)

        return -1;



        /* We have a GBSC probably with GSTUFF */

    skip_bits(&s->gb, 16); /* Drop the zeros */

    left= get_bits_left(&s->gb);

    //MN: we must check the bits left or we might end in a infinite loop (or segfault)

    for(;left>13; left--){

        if(get_bits1(&s->gb)) break; /* Seek the '1' bit */

    }

    if(left<=13)

        return -1;



    if(s->h263_slice_structured){

        if(get_bits1(&s->gb)==0)

            return -1;



        ff_h263_decode_mba(s);



        if(s->mb_num > 1583)

            if(get_bits1(&s->gb)==0)

                return -1;



        s->qscale = get_bits(&s->gb, 5); /* SQUANT */

        if(get_bits1(&s->gb)==0)

            return -1;

        skip_bits(&s->gb, 2); /* GFID */

    }else{

        gob_number = get_bits(&s->gb, 5); /* GN */

        s->mb_x= 0;

        s->mb_y= s->gob_index* gob_number;

        skip_bits(&s->gb, 2); /* GFID */

        s->qscale = get_bits(&s->gb, 5); /* GQUANT */

    }



    if(s->mb_y >= s->mb_height)

        return -1;



    if(s->qscale==0)

        return -1;



    return 0;

}

static void FUNCC(pred4x4_dc)(uint8_t *_src, const uint8_t *topright, int _stride){

    pixel *src = (pixel*)_src;

    int stride = _stride/sizeof(pixel);

    const int dc= (  src[-stride] + src[1-stride] + src[2-stride] + src[3-stride]

                   + src[-1+0*stride] + src[-1+1*stride] + src[-1+2*stride] + src[-1+3*stride] + 4) >>3;



    ((pixel4*)(src+0*stride))[0]=

    ((pixel4*)(src+1*stride))[0]=

    ((pixel4*)(src+2*stride))[0]=

    ((pixel4*)(src+3*stride))[0]= PIXEL_SPLAT_X4(dc);

}

static void unpack_dct_coeffs(Vp3DecodeContext *s, GetBitContext *gb)

{

    int i;

    int dc_y_table;

    int dc_c_table;

    int ac_y_table;

    int ac_c_table;

    int residual_eob_run = 0;



    /* fetch the DC table indices */

    dc_y_table = get_bits(gb, 4);

    dc_c_table = get_bits(gb, 4);



    /* unpack the Y plane DC coefficients */

    debug_vp3("  vp3: unpacking Y plane DC coefficients using table %d\n",

        dc_y_table);

    residual_eob_run = unpack_vlcs(s, gb, &s->dc_vlc[dc_y_table], 0, 

        s->first_coded_y_fragment, s->last_coded_y_fragment, residual_eob_run);



    /* unpack the C plane DC coefficients */

    debug_vp3("  vp3: unpacking C plane DC coefficients using table %d\n",

        dc_c_table);

    residual_eob_run = unpack_vlcs(s, gb, &s->dc_vlc[dc_c_table], 0,

        s->first_coded_c_fragment, s->last_coded_c_fragment, residual_eob_run);



    /* fetch the AC table indices */

    ac_y_table = get_bits(gb, 4);

    ac_c_table = get_bits(gb, 4);



    /* unpack the group 1 AC coefficients (coeffs 1-5) */

    for (i = 1; i <= 5; i++) {



        debug_vp3("  vp3: unpacking level %d Y plane AC coefficients using table %d\n",

            i, ac_y_table);

        residual_eob_run = unpack_vlcs(s, gb, &s->ac_vlc_1[ac_y_table], i, 

            s->first_coded_y_fragment, s->last_coded_y_fragment, residual_eob_run);



        debug_vp3("  vp3: unpacking level %d C plane AC coefficients using table %d\n",

            i, ac_c_table);

        residual_eob_run = unpack_vlcs(s, gb, &s->ac_vlc_1[ac_c_table], i, 

            s->first_coded_c_fragment, s->last_coded_c_fragment, residual_eob_run);

    }



    /* unpack the group 2 AC coefficients (coeffs 6-14) */

    for (i = 6; i <= 14; i++) {



        debug_vp3("  vp3: unpacking level %d Y plane AC coefficients using table %d\n",

            i, ac_y_table);

        residual_eob_run = unpack_vlcs(s, gb, &s->ac_vlc_2[ac_y_table], i, 

            s->first_coded_y_fragment, s->last_coded_y_fragment, residual_eob_run);



        debug_vp3("  vp3: unpacking level %d C plane AC coefficients using table %d\n",

            i, ac_c_table);

        residual_eob_run = unpack_vlcs(s, gb, &s->ac_vlc_2[ac_c_table], i, 

            s->first_coded_c_fragment, s->last_coded_c_fragment, residual_eob_run);

    }



    /* unpack the group 3 AC coefficients (coeffs 15-27) */

    for (i = 15; i <= 27; i++) {



        debug_vp3("  vp3: unpacking level %d Y plane AC coefficients using table %d\n",

            i, ac_y_table);

        residual_eob_run = unpack_vlcs(s, gb, &s->ac_vlc_3[ac_y_table], i, 

            s->first_coded_y_fragment, s->last_coded_y_fragment, residual_eob_run);



        debug_vp3("  vp3: unpacking level %d C plane AC coefficients using table %d\n",

            i, ac_c_table);

        residual_eob_run = unpack_vlcs(s, gb, &s->ac_vlc_3[ac_c_table], i, 

            s->first_coded_c_fragment, s->last_coded_c_fragment, residual_eob_run);

    }



    /* unpack the group 4 AC coefficients (coeffs 28-63) */

    for (i = 28; i <= 63; i++) {



        debug_vp3("  vp3: unpacking level %d Y plane AC coefficients using table %d\n",

            i, ac_y_table);

        residual_eob_run = unpack_vlcs(s, gb, &s->ac_vlc_4[ac_y_table], i, 

            s->first_coded_y_fragment, s->last_coded_y_fragment, residual_eob_run);



        debug_vp3("  vp3: unpacking level %d C plane AC coefficients using table %d\n",

            i, ac_c_table);

        residual_eob_run = unpack_vlcs(s, gb, &s->ac_vlc_4[ac_c_table], i, 

            s->first_coded_c_fragment, s->last_coded_c_fragment, residual_eob_run);

    }

}

void ff_fix_long_mvs(MpegEncContext * s, uint8_t *field_select_table, int field_select,

                     int16_t (*mv_table)[2], int f_code, int type, int truncate)

{

    MotionEstContext * const c= &s->me;

    int y, h_range, v_range;



    // RAL: 8 in MPEG-1, 16 in MPEG-4

    int range = (((s->out_format == FMT_MPEG1 || s->msmpeg4_version) ? 8 : 16) << f_code);



    if(c->avctx->me_range && range > c->avctx->me_range) range= c->avctx->me_range;



    h_range= range;

    v_range= field_select_table ? range>>1 : range;



    /* clip / convert to intra 16x16 type MVs */

    for(y=0; y<s->mb_height; y++){

        int x;

        int xy= y*s->mb_stride;

        for(x=0; x<s->mb_width; x++){

            if (s->mb_type[xy] & type){    // RAL: "type" test added...

                if(field_select_table==NULL || field_select_table[xy] == field_select){

                    if(   mv_table[xy][0] >=h_range || mv_table[xy][0] <-h_range

                       || mv_table[xy][1] >=v_range || mv_table[xy][1] <-v_range){



                        if(truncate){

                            if     (mv_table[xy][0] > h_range-1) mv_table[xy][0]=  h_range-1;

                            else if(mv_table[xy][0] < -h_range ) mv_table[xy][0]= -h_range;

                            if     (mv_table[xy][1] > v_range-1) mv_table[xy][1]=  v_range-1;

                            else if(mv_table[xy][1] < -v_range ) mv_table[xy][1]= -v_range;

                        }else{

                            s->mb_type[xy] &= ~type;

                            s->mb_type[xy] |= CANDIDATE_MB_TYPE_INTRA;

                            mv_table[xy][0]=

                            mv_table[xy][1]= 0;

                        }

                    }

                }

            }

            xy++;

        }

    }

}

static int ftp_write(URLContext *h, const unsigned char *buf, int size)

{

    int err;

    FTPContext *s = h->priv_data;

    int written;



    av_dlog(h, "ftp protocol write %d bytes\n", size);



    if (s->state == DISCONNECTED) {

        if ((err = ftp_connect_data_connection(h)) < 0)

            return err;

    }

    if (s->state == READY) {

        if ((err = ftp_store(s)) < 0)

            return err;

    }

    if (s->conn_data && s->state == UPLOADING) {

        written = ffurl_write(s->conn_data, buf, size);

        if (written > 0) {

            s->position += written;

            s->filesize = FFMAX(s->filesize, s->position);

        }

        return written;

    }



    av_log(h, AV_LOG_ERROR, "FTP write failed\n");

    return AVERROR(EIO);

}

static int udp_write(URLContext *h, const uint8_t *buf, int size)

{

    UDPContext *s = h->priv_data;

    int ret;



#if HAVE_PTHREAD_CANCEL

    if (s->fifo) {

        uint8_t tmp[4];



        pthread_mutex_lock(&s->mutex);



        /*

          Return error if last tx failed.

          Here we can't know on which packet error was, but it needs to know that error exists.

        */

        if (s->circular_buffer_error<0) {

            int err=s->circular_buffer_error;

            s->circular_buffer_error=0;

            pthread_mutex_unlock(&s->mutex);

            return err;

        }



        if(av_fifo_space(s->fifo) < size + 4) {

            /* What about a partial packet tx ? */

            pthread_mutex_unlock(&s->mutex);

            return AVERROR(ENOMEM);

        }

        AV_WL32(tmp, size);

        av_fifo_generic_write(s->fifo, tmp, 4, NULL); /* size of packet */

        av_fifo_generic_write(s->fifo, (uint8_t *)buf, size, NULL); /* the data */

        pthread_cond_signal(&s->cond);

        pthread_mutex_unlock(&s->mutex);

        return size;

    }

#endif

    if (!(h->flags & AVIO_FLAG_NONBLOCK)) {

        ret = ff_network_wait_fd(s->udp_fd, 1);

        if (ret < 0)

            return ret;

    }



    if (!s->is_connected) {

        ret = sendto (s->udp_fd, buf, size, 0,

                      (struct sockaddr *) &s->dest_addr,

                      s->dest_addr_len);

    } else

        ret = send(s->udp_fd, buf, size, 0);



    return ret < 0 ? ff_neterrno() : ret;

}

static void compute_frame_duration(int *pnum, int *pden, AVStream *st,

                                   AVCodecParserContext *pc, AVPacket *pkt)

{

    int frame_size;



    *pnum = 0;

    *pden = 0;

    switch(st->codec->codec_type) {

    case AVMEDIA_TYPE_VIDEO:

        if (st->r_frame_rate.num) {

            *pnum = st->r_frame_rate.den;

            *pden = st->r_frame_rate.num;

        } else if(st->time_base.num*1000LL > st->time_base.den) {

            *pnum = st->time_base.num;

            *pden = st->time_base.den;

        }else if(st->codec->time_base.num*1000LL > st->codec->time_base.den){

            *pnum = st->codec->time_base.num;

            *pden = st->codec->time_base.den;

            if (pc && pc->repeat_pict) {

                *pnum = (*pnum) * (1 + pc->repeat_pict);

            }

            //If this codec can be interlaced or progressive then we need a parser to compute duration of a packet

            //Thus if we have no parser in such case leave duration undefined.

            if(st->codec->ticks_per_frame>1 && !pc){

                *pnum = *pden = 0;

            }

        }

        break;

    case AVMEDIA_TYPE_AUDIO:

        frame_size = get_audio_frame_size(st->codec, pkt->size, 0);

        if (frame_size <= 0 || st->codec->sample_rate <= 0)

            break;

        *pnum = frame_size;

        *pden = st->codec->sample_rate;

        break;

    default:

        break;

    }

}

static int zerocodec_decode_frame(AVCodecContext *avctx, void *data,

                                  int *data_size, AVPacket *avpkt)

{

    ZeroCodecContext *zc = avctx->priv_data;

    AVFrame *pic         = avctx->coded_frame;

    AVFrame *prev_pic    = &zc->previous_frame;

    z_stream *zstream    = &zc->zstream;

    uint8_t *prev, *dst;

    int i, j, zret;



    pic->reference = 3;



    if (avctx->get_buffer(avctx, pic) < 0) {

        av_log(avctx, AV_LOG_ERROR, "Could not allocate buffer.\n");

        return AVERROR(ENOMEM);

    }



    zret = inflateReset(zstream);



    if (zret != Z_OK) {

        av_log(avctx, AV_LOG_ERROR, "Could not reset inflate: %d\n", zret);

        return AVERROR(EINVAL);

    }



    zstream->next_in  = avpkt->data;

    zstream->avail_in = avpkt->size;



    prev = prev_pic->data[0];

    dst  = pic->data[0];



    /**

     * ZeroCodec has very simple interframe compression. If a value

     * is the same as the previous frame, set it to 0.

     */



    if (avpkt->flags & AV_PKT_FLAG_KEY) {



        pic->key_frame = 1;

        pic->pict_type = AV_PICTURE_TYPE_I;



        for (i = 0; i < avctx->height; i++) {



            zstream->next_out  = dst;

            zstream->avail_out = avctx->width << 1;



            zret = inflate(zstream, Z_SYNC_FLUSH);



            if (zret != Z_OK && zret != Z_STREAM_END) {

                av_log(avctx, AV_LOG_ERROR,

                       "Inflate failed with return code: %d\n", zret);

                return AVERROR(EINVAL);

            }



            dst += pic->linesize[0];

        }

    } else {



        pic->key_frame = 0;

        pic->pict_type = AV_PICTURE_TYPE_P;



        for (i = 0; i < avctx->height; i++) {



            zstream->next_out  = dst;

            zstream->avail_out = avctx->width << 1;



            zret = inflate(zstream, Z_SYNC_FLUSH);



            if (zret != Z_OK && zret != Z_STREAM_END) {

                av_log(avctx, AV_LOG_ERROR,

                       "Inflate failed with return code: %d\n", zret);

                return AVERROR(EINVAL);

            }



            for (j = 0; j < avctx->width << 1; j++)

                dst[j] += prev[j] & -!dst[j];



            prev += prev_pic->linesize[0];

            dst  += pic->linesize[0];

        }

    }



    /* Release the previous buffer if need be */

    if (prev_pic->data[0])

        avctx->release_buffer(avctx, prev_pic);



    /* Store the previouse frame for use later */

    *prev_pic = *pic;



    *data_size       = sizeof(AVFrame);

    *(AVFrame *)data = *pic;



    return avpkt->size;

}

int update_dimensions(VP8Context *s, int width, int height, int is_vp7)

{

    AVCodecContext *avctx = s->avctx;

    int i, ret;



    if (width  != s->avctx->width || ((width+15)/16 != s->mb_width || (height+15)/16 != s->mb_height) && s->macroblocks_base ||

        height != s->avctx->height) {

        vp8_decode_flush_impl(s->avctx, 1);



        ret = ff_set_dimensions(s->avctx, width, height);

        if (ret < 0)

            return ret;

    }



    s->mb_width  = (s->avctx->coded_width  + 15) / 16;

    s->mb_height = (s->avctx->coded_height + 15) / 16;



    s->mb_layout = is_vp7 || avctx->active_thread_type == FF_THREAD_SLICE &&

                   FFMIN(s->num_coeff_partitions, avctx->thread_count) > 1;

    if (!s->mb_layout) { // Frame threading and one thread

        s->macroblocks_base       = av_mallocz((s->mb_width + s->mb_height * 2 + 1) *

                                               sizeof(*s->macroblocks));

        s->intra4x4_pred_mode_top = av_mallocz(s->mb_width * 4);

    } else // Sliced threading

        s->macroblocks_base = av_mallocz((s->mb_width + 2) * (s->mb_height + 2) *

                                         sizeof(*s->macroblocks));

    s->top_nnz     = av_mallocz(s->mb_width * sizeof(*s->top_nnz));

    s->top_border  = av_mallocz((s->mb_width + 1) * sizeof(*s->top_border));

    s->thread_data = av_mallocz(MAX_THREADS * sizeof(VP8ThreadData));



    if (!s->macroblocks_base || !s->top_nnz || !s->top_border ||

        !s->thread_data || (!s->intra4x4_pred_mode_top && !s->mb_layout)) {

        free_buffers(s);

        return AVERROR(ENOMEM);

    }



    for (i = 0; i < MAX_THREADS; i++) {

        s->thread_data[i].filter_strength =

            av_mallocz(s->mb_width * sizeof(*s->thread_data[0].filter_strength));

        if (!s->thread_data[i].filter_strength) {

            free_buffers(s);

            return AVERROR(ENOMEM);

        }

#if HAVE_THREADS

        pthread_mutex_init(&s->thread_data[i].lock, NULL);

        pthread_cond_init(&s->thread_data[i].cond, NULL);

#endif

    }



    s->macroblocks = s->macroblocks_base + 1;



    return 0;

}

static int mpeg_decode_frame(AVCodecContext *avctx,

                             void *data, int *data_size,

                             uint8_t *buf, int buf_size)

{

    Mpeg1Context *s = avctx->priv_data;

    const uint8_t *buf_end;

    const uint8_t *buf_ptr;

    uint32_t start_code;

    int ret, input_size;

    AVFrame *picture = data;

    MpegEncContext *s2 = &s->mpeg_enc_ctx;

    dprintf(avctx, "fill_buffer\n");



    if (buf_size == 0 || (buf_size == 4 && AV_RB32(buf) == SEQ_END_CODE)) {

        /* special case for last picture */

        if (s2->low_delay==0 && s2->next_picture_ptr) {

            *picture= *(AVFrame*)s2->next_picture_ptr;

            s2->next_picture_ptr= NULL;



            *data_size = sizeof(AVFrame);

        }

        return 0;

    }



    if(s2->flags&CODEC_FLAG_TRUNCATED){

        int next= ff_mpeg1_find_frame_end(&s2->parse_context, buf, buf_size);



        if( ff_combine_frame(&s2->parse_context, next, (const uint8_t **)&buf, &buf_size) < 0 )

            return buf_size;

    }



    buf_ptr = buf;

    buf_end = buf + buf_size;



#if 0

    if (s->repeat_field % 2 == 1) {

        s->repeat_field++;

        //fprintf(stderr,"\nRepeating last frame: %d -> %d! pict: %d %d", avctx->frame_number-1, avctx->frame_number,

        //        s2->picture_number, s->repeat_field);

        if (avctx->flags & CODEC_FLAG_REPEAT_FIELD) {

            *data_size = sizeof(AVPicture);

            goto the_end;

        }

    }

#endif



    if(s->mpeg_enc_ctx_allocated==0 && avctx->codec_tag == ff_get_fourcc("VCR2"))

        vcr2_init_sequence(avctx);



    s->slice_count= 0;



    for(;;) {

        /* find start next code */

        start_code = -1;

        buf_ptr = ff_find_start_code(buf_ptr,buf_end, &start_code);

        if (start_code > 0x1ff){

            if(s2->pict_type != B_TYPE || avctx->skip_frame <= AVDISCARD_DEFAULT){

                if(avctx->thread_count > 1){

                    int i;



                    avctx->execute(avctx, slice_decode_thread,  (void**)&(s2->thread_context[0]), NULL, s->slice_count);

                    for(i=0; i<s->slice_count; i++)

                        s2->error_count += s2->thread_context[i]->error_count;

                }

                if (slice_end(avctx, picture)) {

                    if(s2->last_picture_ptr || s2->low_delay) //FIXME merge with the stuff in mpeg_decode_slice

                        *data_size = sizeof(AVPicture);

                }

            }

            return FFMAX(0, buf_ptr - buf - s2->parse_context.last_index);

        }



        input_size = buf_end - buf_ptr;



        if(avctx->debug & FF_DEBUG_STARTCODE){

            av_log(avctx, AV_LOG_DEBUG, "%3X at %zd left %d\n", start_code, buf_ptr-buf, input_size);

        }



        /* prepare data for next start code */

        switch(start_code) {

        case SEQ_START_CODE:

            mpeg1_decode_sequence(avctx, buf_ptr,

                                    input_size);

            break;



        case PICTURE_START_CODE:

            /* we have a complete image : we try to decompress it */

            mpeg1_decode_picture(avctx,

                                    buf_ptr, input_size);

            break;

        case EXT_START_CODE:

            mpeg_decode_extension(avctx,

                                    buf_ptr, input_size);

            break;

        case USER_START_CODE:

            mpeg_decode_user_data(avctx,

                                    buf_ptr, input_size);

            break;

        case GOP_START_CODE:

            s2->first_field=0;

            mpeg_decode_gop(avctx,

                                    buf_ptr, input_size);

            break;

        default:

            if (start_code >= SLICE_MIN_START_CODE &&

                start_code <= SLICE_MAX_START_CODE) {

                int mb_y= start_code - SLICE_MIN_START_CODE;



                if(s2->last_picture_ptr==NULL){

                /* Skip B-frames if we do not have reference frames. */

                    if(s2->pict_type==B_TYPE) break;

                /* Skip P-frames if we do not have reference frame no valid header. */

//                    if(s2->pict_type==P_TYPE && s2->first_field && !s2->first_slice) break;

                }

                /* Skip B-frames if we are in a hurry. */

                if(avctx->hurry_up && s2->pict_type==B_TYPE) break;

                if(  (avctx->skip_frame >= AVDISCARD_NONREF && s2->pict_type==B_TYPE)

                    ||(avctx->skip_frame >= AVDISCARD_NONKEY && s2->pict_type!=I_TYPE)

                    || avctx->skip_frame >= AVDISCARD_ALL)

                    break;

                /* Skip everything if we are in a hurry>=5. */

                if(avctx->hurry_up>=5) break;



                if (!s->mpeg_enc_ctx_allocated) break;



                if(s2->codec_id == CODEC_ID_MPEG2VIDEO){

                    if(mb_y < avctx->skip_top || mb_y >= s2->mb_height - avctx->skip_bottom)

                        break;

                }



                if(s2->first_slice){

                    s2->first_slice=0;

                            if(mpeg_field_start(s2) < 0)

                        return -1;

                    }

                if(!s2->current_picture_ptr){

                    av_log(avctx, AV_LOG_ERROR, "current_picture not initialized\n");

                    return -1;

                }



                if(avctx->thread_count > 1){

                    int threshold= (s2->mb_height*s->slice_count + avctx->thread_count/2) / avctx->thread_count;

                    if(threshold <= mb_y){

                        MpegEncContext *thread_context= s2->thread_context[s->slice_count];



                        thread_context->start_mb_y= mb_y;

                        thread_context->end_mb_y  = s2->mb_height;

                        if(s->slice_count){

                            s2->thread_context[s->slice_count-1]->end_mb_y= mb_y;

                            ff_update_duplicate_context(thread_context, s2);

                        }

                        init_get_bits(&thread_context->gb, buf_ptr, input_size*8);

                        s->slice_count++;

                    }

                    buf_ptr += 2; //FIXME add minimum num of bytes per slice

                }else{

                    ret = mpeg_decode_slice(s, mb_y, &buf_ptr, input_size);

                    emms_c();



                    if(ret < 0){

                        if(s2->resync_mb_x>=0 && s2->resync_mb_y>=0)

                            ff_er_add_slice(s2, s2->resync_mb_x, s2->resync_mb_y, s2->mb_x, s2->mb_y, AC_ERROR|DC_ERROR|MV_ERROR);

                    }else{

                        ff_er_add_slice(s2, s2->resync_mb_x, s2->resync_mb_y, s2->mb_x-1, s2->mb_y, AC_END|DC_END|MV_END);

                    }

                }

            }

            break;

        }

    }

}

