static int transcode_subtitles(InputStream *ist, AVPacket *pkt, int *got_output)

{

    AVSubtitle subtitle;

    int i, ret = avcodec_decode_subtitle2(ist->dec_ctx,

                                          &subtitle, got_output, pkt);



    check_decode_result(got_output, ret);



    if (ret < 0 || !*got_output) {

        if (!pkt->size)

            sub2video_flush(ist);

        return ret;

    }



    if (ist->fix_sub_duration) {

        int end = 1;

        if (ist->prev_sub.got_output) {

            end = av_rescale(subtitle.pts - ist->prev_sub.subtitle.pts,

                             1000, AV_TIME_BASE);

            if (end < ist->prev_sub.subtitle.end_display_time) {

                av_log(ist->dec_ctx, AV_LOG_DEBUG,

                       "Subtitle duration reduced from %d to %d%s\n",

                       ist->prev_sub.subtitle.end_display_time, end,

                       end <= 0 ? ", dropping it" : "");

                ist->prev_sub.subtitle.end_display_time = end;

            }

        }

        FFSWAP(int,        *got_output, ist->prev_sub.got_output);

        FFSWAP(int,        ret,         ist->prev_sub.ret);

        FFSWAP(AVSubtitle, subtitle,    ist->prev_sub.subtitle);

        if (end <= 0)

            goto out;

    }



    if (!*got_output)

        return ret;



    sub2video_update(ist, &subtitle);



    if (!subtitle.num_rects)

        goto out;



    ist->frames_decoded++;



    for (i = 0; i < nb_output_streams; i++) {

        OutputStream *ost = output_streams[i];



        if (!check_output_constraints(ist, ost) || !ost->encoding_needed

            || ost->enc->type != AVMEDIA_TYPE_SUBTITLE)

            continue;



        do_subtitle_out(output_files[ost->file_index]->ctx, ost, ist, &subtitle);

    }



out:

    avsubtitle_free(&subtitle);

    return ret;

}

static int yuv4_read_header(AVFormatContext *s, AVFormatParameters *ap)

{

    char header[MAX_YUV4_HEADER+10];  // Include headroom for the longest option

    char *tokstart,*tokend,*header_end;

    int i;

    ByteIOContext *pb = s->pb;

    int width=-1, height=-1, raten=0, rated=0, aspectn=0, aspectd=0;

    enum PixelFormat pix_fmt=PIX_FMT_NONE,alt_pix_fmt=PIX_FMT_NONE;

    enum AVChromaLocation chroma_sample_location = AVCHROMA_LOC_UNSPECIFIED;

    AVStream *st;

    struct frame_attributes *s1 = s->priv_data;



    for (i=0; i<MAX_YUV4_HEADER; i++) {

        header[i] = get_byte(pb);

        if (header[i] == '\n') {

            header[i+1] = 0x20;  // Add a space after last option. Makes parsing "444" vs "444alpha" easier.

            header[i+2] = 0;

            break;

        }

    }

    if (i == MAX_YUV4_HEADER) return -1;

    if (strncmp(header, Y4M_MAGIC, strlen(Y4M_MAGIC))) return -1;



    s1->interlaced_frame = 0;

    s1->top_field_first = 0;

    header_end = &header[i+1]; // Include space

    for(tokstart = &header[strlen(Y4M_MAGIC) + 1]; tokstart < header_end; tokstart++) {

        if (*tokstart==0x20) continue;

        switch (*tokstart++) {

        case 'W': // Width. Required.

            width = strtol(tokstart, &tokend, 10);

            tokstart=tokend;

            break;

        case 'H': // Height. Required.

            height = strtol(tokstart, &tokend, 10);

            tokstart=tokend;

            break;

        case 'C': // Color space

            if (strncmp("420jpeg",tokstart,7)==0) {

                pix_fmt = PIX_FMT_YUV420P;

                chroma_sample_location = AVCHROMA_LOC_CENTER;

            } else if (strncmp("420mpeg2",tokstart,8)==0) {

                pix_fmt = PIX_FMT_YUV420P;

                chroma_sample_location = AVCHROMA_LOC_LEFT;

            } else if (strncmp("420paldv", tokstart, 8)==0) {

                pix_fmt = PIX_FMT_YUV420P;

                chroma_sample_location = AVCHROMA_LOC_TOPLEFT;

            } else if (strncmp("411", tokstart, 3)==0)

                pix_fmt = PIX_FMT_YUV411P;

            else if (strncmp("422", tokstart, 3)==0)

                pix_fmt = PIX_FMT_YUV422P;

            else if (strncmp("444alpha", tokstart, 8)==0) {

                av_log(s, AV_LOG_ERROR, "Cannot handle 4:4:4:4 YUV4MPEG stream.\n");

                return -1;

            } else if (strncmp("444", tokstart, 3)==0)

                pix_fmt = PIX_FMT_YUV444P;

            else if (strncmp("mono",tokstart, 4)==0) {

                pix_fmt = PIX_FMT_GRAY8;

            } else {

                av_log(s, AV_LOG_ERROR, "YUV4MPEG stream contains an unknown pixel format.\n");

                return -1;

            }

            while(tokstart<header_end&&*tokstart!=0x20) tokstart++;

            break;

        case 'I': // Interlace type

            switch (*tokstart++){

            case '?':

                break;

            case 'p':

                s1->interlaced_frame=0;

                break;

            case 't':

                s1->interlaced_frame=1;

                s1->top_field_first=1;

                break;

            case 'b':

                s1->interlaced_frame=1;

                s1->top_field_first=0;

                break;

            case 'm':

                av_log(s, AV_LOG_ERROR, "YUV4MPEG stream contains mixed interlaced and non-interlaced frames.\n");

                return -1;

            default:

                av_log(s, AV_LOG_ERROR, "YUV4MPEG has invalid header.\n");

                return -1;

            }

            break;

        case 'F': // Frame rate

            sscanf(tokstart,"%d:%d",&raten,&rated); // 0:0 if unknown

            while(tokstart<header_end&&*tokstart!=0x20) tokstart++;

            break;

        case 'A': // Pixel aspect

            sscanf(tokstart,"%d:%d",&aspectn,&aspectd); // 0:0 if unknown

            while(tokstart<header_end&&*tokstart!=0x20) tokstart++;

            break;

        case 'X': // Vendor extensions

            if (strncmp("YSCSS=",tokstart,6)==0) {

                // Older nonstandard pixel format representation

                tokstart+=6;

                if (strncmp("420JPEG",tokstart,7)==0)

                    alt_pix_fmt=PIX_FMT_YUV420P;

                else if (strncmp("420MPEG2",tokstart,8)==0)

                    alt_pix_fmt=PIX_FMT_YUV420P;

                else if (strncmp("420PALDV",tokstart,8)==0)

                    alt_pix_fmt=PIX_FMT_YUV420P;

                else if (strncmp("411",tokstart,3)==0)

                    alt_pix_fmt=PIX_FMT_YUV411P;

                else if (strncmp("422",tokstart,3)==0)

                    alt_pix_fmt=PIX_FMT_YUV422P;

                else if (strncmp("444",tokstart,3)==0)

                    alt_pix_fmt=PIX_FMT_YUV444P;

            }

            while(tokstart<header_end&&*tokstart!=0x20) tokstart++;

            break;

        }

    }



    if ((width == -1) || (height == -1)) {

        av_log(s, AV_LOG_ERROR, "YUV4MPEG has invalid header.\n");

        return -1;

    }



    if (pix_fmt == PIX_FMT_NONE) {

        if (alt_pix_fmt == PIX_FMT_NONE)

            pix_fmt = PIX_FMT_YUV420P;

        else

            pix_fmt = alt_pix_fmt;

    }



    if (raten == 0 && rated == 0) {

        // Frame rate unknown

        raten = 25;

        rated = 1;

    }



    if (aspectn == 0 && aspectd == 0) {

        // Pixel aspect unknown

        aspectd = 1;

    }



    st = av_new_stream(s, 0);

    if(!st)

        return AVERROR(ENOMEM);

    st->codec->width = width;

    st->codec->height = height;

    av_reduce(&raten, &rated, raten, rated, (1UL<<31)-1);

    av_set_pts_info(st, 64, rated, raten);

    st->codec->pix_fmt = pix_fmt;

    st->codec->codec_type = AVMEDIA_TYPE_VIDEO;

    st->codec->codec_id = CODEC_ID_RAWVIDEO;

    st->sample_aspect_ratio= (AVRational){aspectn, aspectd};

    st->codec->chroma_sample_location = chroma_sample_location;



    return 0;

}

static int get_coc(Jpeg2000DecoderContext *s, Jpeg2000CodingStyle *c,

                   uint8_t *properties)

{

    int compno;



    if (s->buf_end - s->buf < 2)

        return AVERROR_INVALIDDATA;



    compno = bytestream_get_byte(&s->buf);



    c      += compno;

    c->csty = bytestream_get_byte(&s->buf);

    get_cox(s, c);



    properties[compno] |= HAD_COC;

    return 0;

}

static int decode_frame_packing_arrangement(H264Context *h)

{

    h->sei_fpa.frame_packing_arrangement_id          = get_ue_golomb(&h->gb);

    h->sei_fpa.frame_packing_arrangement_cancel_flag = get_bits1(&h->gb);

    h->sei_frame_packing_present = !h->sei_fpa.frame_packing_arrangement_cancel_flag;



    if (h->sei_frame_packing_present) {

        h->sei_fpa.frame_packing_arrangement_type =

        h->frame_packing_arrangement_type = get_bits(&h->gb, 7);

        h->sei_fpa.quincunx_sampling_flag         =

        h->quincunx_subsampling           = get_bits1(&h->gb);

        h->sei_fpa.content_interpretation_type    =

        h->content_interpretation_type    = get_bits(&h->gb, 6);



        // the following skips: spatial_flipping_flag, frame0_flipped_flag,

        // field_views_flag, current_frame_is_frame0_flag,

        // frame0_self_contained_flag, frame1_self_contained_flag

        skip_bits(&h->gb, 6);



        if (!h->quincunx_subsampling && h->frame_packing_arrangement_type != 5)

            skip_bits(&h->gb, 16);      // frame[01]_grid_position_[xy]

        skip_bits(&h->gb, 8);           // frame_packing_arrangement_reserved_byte

        h->sei_fpa.frame_packing_arrangement_repetition_period = get_ue_golomb(&h->gb) /* frame_packing_arrangement_repetition_period */;

    }

    skip_bits1(&h->gb);                 // frame_packing_arrangement_extension_flag



    if (h->avctx->debug & FF_DEBUG_PICT_INFO)

        av_log(h->avctx, AV_LOG_DEBUG, "SEI FPA %d %d %d %d %d %d\n",

                                       h->sei_fpa.frame_packing_arrangement_id,

                                       h->sei_fpa.frame_packing_arrangement_cancel_flag,

                                       h->sei_fpa.frame_packing_arrangement_type,

                                       h->sei_fpa.quincunx_sampling_flag,

                                       h->sei_fpa.content_interpretation_type,

                                       h->sei_fpa.frame_packing_arrangement_repetition_period);



    return 0;

}

av_cold int ff_MPV_encode_init(AVCodecContext *avctx)

{

    MpegEncContext *s = avctx->priv_data;

    int i, ret;



    MPV_encode_defaults(s);



    switch (avctx->codec_id) {

    case AV_CODEC_ID_MPEG2VIDEO:

        if (avctx->pix_fmt != AV_PIX_FMT_YUV420P &&

            avctx->pix_fmt != AV_PIX_FMT_YUV422P) {

            av_log(avctx, AV_LOG_ERROR,

                   "only YUV420 and YUV422 are supported\n");

            return -1;

        }

        break;

    case AV_CODEC_ID_MJPEG:

    case AV_CODEC_ID_AMV:

        if (avctx->pix_fmt != AV_PIX_FMT_YUVJ420P &&

            avctx->pix_fmt != AV_PIX_FMT_YUVJ422P &&

            avctx->pix_fmt != AV_PIX_FMT_YUVJ444P &&

            ((avctx->pix_fmt != AV_PIX_FMT_YUV420P &&

              avctx->pix_fmt != AV_PIX_FMT_YUV422P &&

              avctx->pix_fmt != AV_PIX_FMT_YUV444P) ||

             avctx->strict_std_compliance > FF_COMPLIANCE_UNOFFICIAL)) {

            av_log(avctx, AV_LOG_ERROR, "colorspace not supported in jpeg\n");

            return -1;

        }

        break;

    default:

        if (avctx->pix_fmt != AV_PIX_FMT_YUV420P) {

            av_log(avctx, AV_LOG_ERROR, "only YUV420 is supported\n");

            return -1;

        }

    }



    switch (avctx->pix_fmt) {

    case AV_PIX_FMT_YUVJ444P:

    case AV_PIX_FMT_YUV444P:

        s->chroma_format = CHROMA_444;

        break;

    case AV_PIX_FMT_YUVJ422P:

    case AV_PIX_FMT_YUV422P:

        s->chroma_format = CHROMA_422;

        break;

    case AV_PIX_FMT_YUVJ420P:

    case AV_PIX_FMT_YUV420P:

    default:

        s->chroma_format = CHROMA_420;

        break;

    }



    s->bit_rate = avctx->bit_rate;

    s->width    = avctx->width;

    s->height   = avctx->height;

    if (avctx->gop_size > 600 &&

        avctx->strict_std_compliance > FF_COMPLIANCE_EXPERIMENTAL) {

        av_log(avctx, AV_LOG_WARNING,

               "keyframe interval too large!, reducing it from %d to %d\n",

               avctx->gop_size, 600);

        avctx->gop_size = 600;

    }

    s->gop_size     = avctx->gop_size;

    s->avctx        = avctx;

    s->flags        = avctx->flags;

    s->flags2       = avctx->flags2;

    if (avctx->max_b_frames > MAX_B_FRAMES) {

        av_log(avctx, AV_LOG_ERROR, "Too many B-frames requested, maximum "

               "is %d.\n", MAX_B_FRAMES);

        avctx->max_b_frames = MAX_B_FRAMES;

    }

    s->max_b_frames = avctx->max_b_frames;

    s->codec_id     = avctx->codec->id;

    s->strict_std_compliance = avctx->strict_std_compliance;

    s->quarter_sample     = (avctx->flags & CODEC_FLAG_QPEL) != 0;

    s->mpeg_quant         = avctx->mpeg_quant;

    s->rtp_mode           = !!avctx->rtp_payload_size;

    s->intra_dc_precision = avctx->intra_dc_precision;

    s->user_specified_pts = AV_NOPTS_VALUE;



    if (s->gop_size <= 1) {

        s->intra_only = 1;

        s->gop_size   = 12;

    } else {

        s->intra_only = 0;

    }



    s->me_method = avctx->me_method;



    /* Fixed QSCALE */

    s->fixed_qscale = !!(avctx->flags & CODEC_FLAG_QSCALE);



    s->adaptive_quant = (s->avctx->lumi_masking ||

                         s->avctx->dark_masking ||

                         s->avctx->temporal_cplx_masking ||

                         s->avctx->spatial_cplx_masking  ||

                         s->avctx->p_masking      ||

                         s->avctx->border_masking ||

                         (s->mpv_flags & FF_MPV_FLAG_QP_RD)) &&

                        !s->fixed_qscale;



    s->loop_filter      = !!(s->flags & CODEC_FLAG_LOOP_FILTER);



    if (avctx->rc_max_rate && !avctx->rc_buffer_size) {

        switch(avctx->codec_id) {

        case AV_CODEC_ID_MPEG1VIDEO:

        case AV_CODEC_ID_MPEG2VIDEO:

            avctx->rc_buffer_size = FFMAX(avctx->rc_max_rate, 15000000) * 112L / 15000000 * 16384;

            break;

        case AV_CODEC_ID_MPEG4:

        case AV_CODEC_ID_MSMPEG4V1:

        case AV_CODEC_ID_MSMPEG4V2:

        case AV_CODEC_ID_MSMPEG4V3:

            if       (avctx->rc_max_rate >= 15000000) {

                avctx->rc_buffer_size = 320 + (avctx->rc_max_rate - 15000000L) * (760-320) / (38400000 - 15000000);

            } else if(avctx->rc_max_rate >=  2000000) {

                avctx->rc_buffer_size =  80 + (avctx->rc_max_rate -  2000000L) * (320- 80) / (15000000 -  2000000);

            } else if(avctx->rc_max_rate >=   384000) {

                avctx->rc_buffer_size =  40 + (avctx->rc_max_rate -   384000L) * ( 80- 40) / ( 2000000 -   384000);

            } else

                avctx->rc_buffer_size = 40;

            avctx->rc_buffer_size *= 16384;

            break;

        }

        if (avctx->rc_buffer_size) {

            av_log(avctx, AV_LOG_INFO, "Automatically choosing VBV buffer size of %d kbyte\n", avctx->rc_buffer_size/8192);

        }

    }



    if ((!avctx->rc_max_rate) != (!avctx->rc_buffer_size)) {

        av_log(avctx, AV_LOG_ERROR, "Either both buffer size and max rate or neither must be specified\n");

        if (avctx->rc_max_rate && !avctx->rc_buffer_size)

            return -1;

    }



    if (avctx->rc_min_rate && avctx->rc_max_rate != avctx->rc_min_rate) {

        av_log(avctx, AV_LOG_INFO,

               "Warning min_rate > 0 but min_rate != max_rate isn't recommended!\n");

    }



    if (avctx->rc_min_rate && avctx->rc_min_rate > avctx->bit_rate) {

        av_log(avctx, AV_LOG_ERROR, "bitrate below min bitrate\n");

        return -1;

    }



    if (avctx->rc_max_rate && avctx->rc_max_rate < avctx->bit_rate) {

        av_log(avctx, AV_LOG_ERROR, "bitrate above max bitrate\n");

        return -1;

    }



    if (avctx->rc_max_rate &&

        avctx->rc_max_rate == avctx->bit_rate &&

        avctx->rc_max_rate != avctx->rc_min_rate) {

        av_log(avctx, AV_LOG_INFO,

               "impossible bitrate constraints, this will fail\n");

    }



    if (avctx->rc_buffer_size &&

        avctx->bit_rate * (int64_t)avctx->time_base.num >

            avctx->rc_buffer_size * (int64_t)avctx->time_base.den) {

        av_log(avctx, AV_LOG_ERROR, "VBV buffer too small for bitrate\n");

        return -1;

    }



    if (!s->fixed_qscale &&

        avctx->bit_rate * av_q2d(avctx->time_base) >

            avctx->bit_rate_tolerance) {

        av_log(avctx, AV_LOG_ERROR,

               "bitrate tolerance %d too small for bitrate %d\n", avctx->bit_rate_tolerance, avctx->bit_rate);

        return -1;

    }



    if (s->avctx->rc_max_rate &&

        s->avctx->rc_min_rate == s->avctx->rc_max_rate &&

        (s->codec_id == AV_CODEC_ID_MPEG1VIDEO ||

         s->codec_id == AV_CODEC_ID_MPEG2VIDEO) &&

        90000LL * (avctx->rc_buffer_size - 1) >

            s->avctx->rc_max_rate * 0xFFFFLL) {

        av_log(avctx, AV_LOG_INFO,

               "Warning vbv_delay will be set to 0xFFFF (=VBR) as the "

               "specified vbv buffer is too large for the given bitrate!\n");

    }



    if ((s->flags & CODEC_FLAG_4MV)  && s->codec_id != AV_CODEC_ID_MPEG4 &&

        s->codec_id != AV_CODEC_ID_H263 && s->codec_id != AV_CODEC_ID_H263P &&

        s->codec_id != AV_CODEC_ID_FLV1) {

        av_log(avctx, AV_LOG_ERROR, "4MV not supported by codec\n");

        return -1;

    }



    if (s->obmc && s->avctx->mb_decision != FF_MB_DECISION_SIMPLE) {

        av_log(avctx, AV_LOG_ERROR,

               "OBMC is only supported with simple mb decision\n");

        return -1;

    }



    if (s->quarter_sample && s->codec_id != AV_CODEC_ID_MPEG4) {

        av_log(avctx, AV_LOG_ERROR, "qpel not supported by codec\n");

        return -1;

    }



    if (s->max_b_frames                    &&

        s->codec_id != AV_CODEC_ID_MPEG4      &&

        s->codec_id != AV_CODEC_ID_MPEG1VIDEO &&

        s->codec_id != AV_CODEC_ID_MPEG2VIDEO) {

        av_log(avctx, AV_LOG_ERROR, "b frames not supported by codec\n");

        return -1;

    }

    if (s->max_b_frames < 0) {

        av_log(avctx, AV_LOG_ERROR,

               "max b frames must be 0 or positive for mpegvideo based encoders\n");

        return -1;

    }



    if ((s->codec_id == AV_CODEC_ID_MPEG4 ||

         s->codec_id == AV_CODEC_ID_H263  ||

         s->codec_id == AV_CODEC_ID_H263P) &&

        (avctx->sample_aspect_ratio.num > 255 ||

         avctx->sample_aspect_ratio.den > 255)) {

        av_log(avctx, AV_LOG_WARNING,

               "Invalid pixel aspect ratio %i/%i, limit is 255/255 reducing\n",

               avctx->sample_aspect_ratio.num, avctx->sample_aspect_ratio.den);

        av_reduce(&avctx->sample_aspect_ratio.num, &avctx->sample_aspect_ratio.den,

                   avctx->sample_aspect_ratio.num,  avctx->sample_aspect_ratio.den, 255);

    }



    if ((s->codec_id == AV_CODEC_ID_H263  ||

         s->codec_id == AV_CODEC_ID_H263P) &&

        (avctx->width  > 2048 ||

         avctx->height > 1152 )) {

        av_log(avctx, AV_LOG_ERROR, "H.263 does not support resolutions above 2048x1152\n");

        return -1;

    }

    if ((s->codec_id == AV_CODEC_ID_H263  ||

         s->codec_id == AV_CODEC_ID_H263P) &&

        ((avctx->width &3) ||

         (avctx->height&3) )) {

        av_log(avctx, AV_LOG_ERROR, "w/h must be a multiple of 4\n");

        return -1;

    }



    if (s->codec_id == AV_CODEC_ID_MPEG1VIDEO &&

        (avctx->width  > 4095 ||

         avctx->height > 4095 )) {

        av_log(avctx, AV_LOG_ERROR, "MPEG-1 does not support resolutions above 4095x4095\n");

        return -1;

    }



    if (s->codec_id == AV_CODEC_ID_MPEG2VIDEO &&

        (avctx->width  > 16383 ||

         avctx->height > 16383 )) {

        av_log(avctx, AV_LOG_ERROR, "MPEG-2 does not support resolutions above 16383x16383\n");

        return -1;

    }



    if (s->codec_id == AV_CODEC_ID_RV10 &&

        (avctx->width &15 ||

         avctx->height&15 )) {

        av_log(avctx, AV_LOG_ERROR, "width and height must be a multiple of 16\n");

        return AVERROR(EINVAL);

    }



    if (s->codec_id == AV_CODEC_ID_RV20 &&

        (avctx->width &3 ||

         avctx->height&3 )) {

        av_log(avctx, AV_LOG_ERROR, "width and height must be a multiple of 4\n");

        return AVERROR(EINVAL);

    }



    if ((s->codec_id == AV_CODEC_ID_WMV1 ||

         s->codec_id == AV_CODEC_ID_WMV2) &&

         avctx->width & 1) {

         av_log(avctx, AV_LOG_ERROR, "width must be multiple of 2\n");

         return -1;

    }



    if ((s->flags & (CODEC_FLAG_INTERLACED_DCT | CODEC_FLAG_INTERLACED_ME)) &&

        s->codec_id != AV_CODEC_ID_MPEG4 && s->codec_id != AV_CODEC_ID_MPEG2VIDEO) {

        av_log(avctx, AV_LOG_ERROR, "interlacing not supported by codec\n");

        return -1;

    }



    // FIXME mpeg2 uses that too

    if (s->mpeg_quant && (   s->codec_id != AV_CODEC_ID_MPEG4

                          && s->codec_id != AV_CODEC_ID_MPEG2VIDEO)) {

        av_log(avctx, AV_LOG_ERROR,

               "mpeg2 style quantization not supported by codec\n");

        return -1;

    }



    if ((s->mpv_flags & FF_MPV_FLAG_CBP_RD) && !avctx->trellis) {

        av_log(avctx, AV_LOG_ERROR, "CBP RD needs trellis quant\n");

        return -1;

    }



    if ((s->mpv_flags & FF_MPV_FLAG_QP_RD) &&

        s->avctx->mb_decision != FF_MB_DECISION_RD) {

        av_log(avctx, AV_LOG_ERROR, "QP RD needs mbd=2\n");

        return -1;

    }



    if (s->avctx->scenechange_threshold < 1000000000 &&

        (s->flags & CODEC_FLAG_CLOSED_GOP)) {

        av_log(avctx, AV_LOG_ERROR,

               "closed gop with scene change detection are not supported yet, "

               "set threshold to 1000000000\n");

        return -1;

    }



    if (s->flags & CODEC_FLAG_LOW_DELAY) {

        if (s->codec_id != AV_CODEC_ID_MPEG2VIDEO) {

            av_log(avctx, AV_LOG_ERROR,

                  "low delay forcing is only available for mpeg2\n");

            return -1;

        }

        if (s->max_b_frames != 0) {

            av_log(avctx, AV_LOG_ERROR,

                   "b frames cannot be used with low delay\n");

            return -1;

        }

    }



    if (s->q_scale_type == 1) {

        if (avctx->qmax > 12) {

            av_log(avctx, AV_LOG_ERROR,

                   "non linear quant only supports qmax <= 12 currently\n");

            return -1;

        }

    }



    if (s->avctx->thread_count > 1         &&

        s->codec_id != AV_CODEC_ID_MPEG4      &&

        s->codec_id != AV_CODEC_ID_MPEG1VIDEO &&

        s->codec_id != AV_CODEC_ID_MPEG2VIDEO &&

        s->codec_id != AV_CODEC_ID_MJPEG      &&

        (s->codec_id != AV_CODEC_ID_H263P)) {

        av_log(avctx, AV_LOG_ERROR,

               "multi threaded encoding not supported by codec\n");

        return -1;

    }



    if (s->avctx->thread_count < 1) {

        av_log(avctx, AV_LOG_ERROR,

               "automatic thread number detection not supported by codec, "

               "patch welcome\n");

        return -1;

    }



    if (s->avctx->slices > 1 || s->avctx->thread_count > 1)

        s->rtp_mode = 1;



    if (s->avctx->thread_count > 1 && s->codec_id == AV_CODEC_ID_H263P)

        s->h263_slice_structured = 1;



    if (!avctx->time_base.den || !avctx->time_base.num) {

        av_log(avctx, AV_LOG_ERROR, "framerate not set\n");

        return -1;

    }



    i = (INT_MAX / 2 + 128) >> 8;

    if (avctx->mb_threshold >= i) {

        av_log(avctx, AV_LOG_ERROR, "mb_threshold too large, max is %d\n",

               i - 1);

        return -1;

    }



    if (avctx->b_frame_strategy && (avctx->flags & CODEC_FLAG_PASS2)) {

        av_log(avctx, AV_LOG_INFO,

               "notice: b_frame_strategy only affects the first pass\n");

        avctx->b_frame_strategy = 0;

    }



    i = av_gcd(avctx->time_base.den, avctx->time_base.num);

    if (i > 1) {

        av_log(avctx, AV_LOG_INFO, "removing common factors from framerate\n");

        avctx->time_base.den /= i;

        avctx->time_base.num /= i;

        //return -1;

    }



    if (s->mpeg_quant || s->codec_id == AV_CODEC_ID_MPEG1VIDEO || s->codec_id == AV_CODEC_ID_MPEG2VIDEO || s->codec_id == AV_CODEC_ID_MJPEG || s->codec_id==AV_CODEC_ID_AMV) {

        // (a + x * 3 / 8) / x

        s->intra_quant_bias = 3 << (QUANT_BIAS_SHIFT - 3);

        s->inter_quant_bias = 0;

    } else {

        s->intra_quant_bias = 0;

        // (a - x / 4) / x

        s->inter_quant_bias = -(1 << (QUANT_BIAS_SHIFT - 2));

    }



    if (avctx->qmin > avctx->qmax || avctx->qmin <= 0) {

        av_log(avctx, AV_LOG_ERROR, "qmin and or qmax are invalid, they must be 0 < min <= max\n");

        return AVERROR(EINVAL);

    }



    if (avctx->intra_quant_bias != FF_DEFAULT_QUANT_BIAS)

        s->intra_quant_bias = avctx->intra_quant_bias;

    if (avctx->inter_quant_bias != FF_DEFAULT_QUANT_BIAS)

        s->inter_quant_bias = avctx->inter_quant_bias;



    av_log(avctx, AV_LOG_DEBUG, "intra_quant_bias = %d inter_quant_bias = %d\n",s->intra_quant_bias,s->inter_quant_bias);



    if (avctx->codec_id == AV_CODEC_ID_MPEG4 &&

        s->avctx->time_base.den > (1 << 16) - 1) {

        av_log(avctx, AV_LOG_ERROR,

               "timebase %d/%d not supported by MPEG 4 standard, "

               "the maximum admitted value for the timebase denominator "

               "is %d\n", s->avctx->time_base.num, s->avctx->time_base.den,

               (1 << 16) - 1);

        return -1;

    }

    s->time_increment_bits = av_log2(s->avctx->time_base.den - 1) + 1;



    switch (avctx->codec->id) {

    case AV_CODEC_ID_MPEG1VIDEO:

        s->out_format = FMT_MPEG1;

        s->low_delay  = !!(s->flags & CODEC_FLAG_LOW_DELAY);

        avctx->delay  = s->low_delay ? 0 : (s->max_b_frames + 1);

        break;

    case AV_CODEC_ID_MPEG2VIDEO:

        s->out_format = FMT_MPEG1;

        s->low_delay  = !!(s->flags & CODEC_FLAG_LOW_DELAY);

        avctx->delay  = s->low_delay ? 0 : (s->max_b_frames + 1);

        s->rtp_mode   = 1;

        break;

    case AV_CODEC_ID_MJPEG:

    case AV_CODEC_ID_AMV:

        s->out_format = FMT_MJPEG;

        s->intra_only = 1; /* force intra only for jpeg */

        if (!CONFIG_MJPEG_ENCODER ||

            ff_mjpeg_encode_init(s) < 0)

            return -1;

        avctx->delay = 0;

        s->low_delay = 1;

        break;

    case AV_CODEC_ID_H261:

        if (!CONFIG_H261_ENCODER)

            return -1;

        if (ff_h261_get_picture_format(s->width, s->height) < 0) {

            av_log(avctx, AV_LOG_ERROR,

                   "The specified picture size of %dx%d is not valid for the "

                   "H.261 codec.\nValid sizes are 176x144, 352x288\n",

                    s->width, s->height);

            return -1;

        }

        s->out_format = FMT_H261;

        avctx->delay  = 0;

        s->low_delay  = 1;

        break;

    case AV_CODEC_ID_H263:

        if (!CONFIG_H263_ENCODER)

            return -1;

        if (ff_match_2uint16(ff_h263_format, FF_ARRAY_ELEMS(ff_h263_format),

                             s->width, s->height) == 8) {

            av_log(avctx, AV_LOG_ERROR,

                   "The specified picture size of %dx%d is not valid for "

                   "the H.263 codec.\nValid sizes are 128x96, 176x144, "

                   "352x288, 704x576, and 1408x1152. "

                   "Try H.263+.\n", s->width, s->height);

            return -1;

        }

        s->out_format = FMT_H263;

        avctx->delay  = 0;

        s->low_delay  = 1;

        break;

    case AV_CODEC_ID_H263P:

        s->out_format = FMT_H263;

        s->h263_plus  = 1;

        /* Fx */

        s->h263_aic        = (avctx->flags & CODEC_FLAG_AC_PRED) ? 1 : 0;

        s->modified_quant  = s->h263_aic;

        s->loop_filter     = (avctx->flags & CODEC_FLAG_LOOP_FILTER) ? 1 : 0;

        s->unrestricted_mv = s->obmc || s->loop_filter || s->umvplus;



        /* /Fx */

        /* These are just to be sure */

        avctx->delay = 0;

        s->low_delay = 1;

        break;

    case AV_CODEC_ID_FLV1:

        s->out_format      = FMT_H263;

        s->h263_flv        = 2; /* format = 1; 11-bit codes */

        s->unrestricted_mv = 1;

        s->rtp_mode  = 0; /* don't allow GOB */

        avctx->delay = 0;

        s->low_delay = 1;

        break;

    case AV_CODEC_ID_RV10:

        s->out_format = FMT_H263;

        avctx->delay  = 0;

        s->low_delay  = 1;

        break;

    case AV_CODEC_ID_RV20:

        s->out_format      = FMT_H263;

        avctx->delay       = 0;

        s->low_delay       = 1;

        s->modified_quant  = 1;

        s->h263_aic        = 1;

        s->h263_plus       = 1;

        s->loop_filter     = 1;

        s->unrestricted_mv = 0;

        break;

    case AV_CODEC_ID_MPEG4:

        s->out_format      = FMT_H263;

        s->h263_pred       = 1;

        s->unrestricted_mv = 1;

        s->low_delay       = s->max_b_frames ? 0 : 1;

        avctx->delay       = s->low_delay ? 0 : (s->max_b_frames + 1);

        break;

    case AV_CODEC_ID_MSMPEG4V2:

        s->out_format      = FMT_H263;

        s->h263_pred       = 1;

        s->unrestricted_mv = 1;

        s->msmpeg4_version = 2;

        avctx->delay       = 0;

        s->low_delay       = 1;

        break;

    case AV_CODEC_ID_MSMPEG4V3:

        s->out_format        = FMT_H263;

        s->h263_pred         = 1;

        s->unrestricted_mv   = 1;

        s->msmpeg4_version   = 3;

        s->flipflop_rounding = 1;

        avctx->delay         = 0;

        s->low_delay         = 1;

        break;

    case AV_CODEC_ID_WMV1:

        s->out_format        = FMT_H263;

        s->h263_pred         = 1;

        s->unrestricted_mv   = 1;

        s->msmpeg4_version   = 4;

        s->flipflop_rounding = 1;

        avctx->delay         = 0;

        s->low_delay         = 1;

        break;

    case AV_CODEC_ID_WMV2:

        s->out_format        = FMT_H263;

        s->h263_pred         = 1;

        s->unrestricted_mv   = 1;

        s->msmpeg4_version   = 5;

        s->flipflop_rounding = 1;

        avctx->delay         = 0;

        s->low_delay         = 1;

        break;

    default:

        return -1;

    }



    avctx->has_b_frames = !s->low_delay;



    s->encoding = 1;



    s->progressive_frame    =

    s->progressive_sequence = !(avctx->flags & (CODEC_FLAG_INTERLACED_DCT |

                                                CODEC_FLAG_INTERLACED_ME) ||

                                s->alternate_scan);



    /* init */

    if (ff_MPV_common_init(s) < 0)

        return -1;



    s->avctx->coded_frame = s->current_picture.f;



    if (s->msmpeg4_version) {

        FF_ALLOCZ_OR_GOTO(s->avctx, s->ac_stats,

                          2 * 2 * (MAX_LEVEL + 1) *

                          (MAX_RUN + 1) * 2 * sizeof(int), fail);

    }

    FF_ALLOCZ_OR_GOTO(s->avctx, s->avctx->stats_out, 256, fail);



    FF_ALLOCZ_OR_GOTO(s->avctx, s->q_intra_matrix,   64 * 32 * sizeof(int), fail);

    FF_ALLOCZ_OR_GOTO(s->avctx, s->q_chroma_intra_matrix, 64 * 32 * sizeof(int), fail);

    FF_ALLOCZ_OR_GOTO(s->avctx, s->q_inter_matrix,   64 * 32 * sizeof(int), fail);

    FF_ALLOCZ_OR_GOTO(s->avctx, s->q_intra_matrix16, 64 * 32 * 2 * sizeof(uint16_t), fail);

    FF_ALLOCZ_OR_GOTO(s->avctx, s->q_chroma_intra_matrix16, 64 * 32 * 2 * sizeof(uint16_t), fail);

    FF_ALLOCZ_OR_GOTO(s->avctx, s->q_inter_matrix16, 64 * 32 * 2 * sizeof(uint16_t), fail);

    FF_ALLOCZ_OR_GOTO(s->avctx, s->input_picture,

                      MAX_PICTURE_COUNT * sizeof(Picture *), fail);

    FF_ALLOCZ_OR_GOTO(s->avctx, s->reordered_input_picture,

                      MAX_PICTURE_COUNT * sizeof(Picture *), fail);



    if (s->avctx->noise_reduction) {

        FF_ALLOCZ_OR_GOTO(s->avctx, s->dct_offset,

                          2 * 64 * sizeof(uint16_t), fail);

    }



    ff_dct_encode_init(s);



    if ((CONFIG_H263P_ENCODER || CONFIG_RV20_ENCODER) && s->modified_quant)

        s->chroma_qscale_table = ff_h263_chroma_qscale_table;



    s->quant_precision = 5;



    ff_set_cmp(&s->dsp, s->dsp.ildct_cmp, s->avctx->ildct_cmp);

    ff_set_cmp(&s->dsp, s->dsp.frame_skip_cmp, s->avctx->frame_skip_cmp);



    if (CONFIG_H261_ENCODER && s->out_format == FMT_H261)

        ff_h261_encode_init(s);

    if (CONFIG_H263_ENCODER && s->out_format == FMT_H263)

        ff_h263_encode_init(s);

    if (CONFIG_MSMPEG4_ENCODER && s->msmpeg4_version)

        ff_msmpeg4_encode_init(s);

    if ((CONFIG_MPEG1VIDEO_ENCODER || CONFIG_MPEG2VIDEO_ENCODER)

        && s->out_format == FMT_MPEG1)

        ff_mpeg1_encode_init(s);



    /* init q matrix */

    for (i = 0; i < 64; i++) {

        int j = s->dsp.idct_permutation[i];

        if (CONFIG_MPEG4_ENCODER && s->codec_id == AV_CODEC_ID_MPEG4 &&

            s->mpeg_quant) {

            s->intra_matrix[j] = ff_mpeg4_default_intra_matrix[i];

            s->inter_matrix[j] = ff_mpeg4_default_non_intra_matrix[i];

        } else if (s->out_format == FMT_H263 || s->out_format == FMT_H261) {

            s->intra_matrix[j] =

            s->inter_matrix[j] = ff_mpeg1_default_non_intra_matrix[i];

        } else {

            /* mpeg1/2 */

            s->intra_matrix[j] = ff_mpeg1_default_intra_matrix[i];

            s->inter_matrix[j] = ff_mpeg1_default_non_intra_matrix[i];

        }

        if (s->avctx->intra_matrix)

            s->intra_matrix[j] = s->avctx->intra_matrix[i];

        if (s->avctx->inter_matrix)

            s->inter_matrix[j] = s->avctx->inter_matrix[i];

    }



    /* precompute matrix */

    /* for mjpeg, we do include qscale in the matrix */

    if (s->out_format != FMT_MJPEG) {

        ff_convert_matrix(&s->dsp, s->q_intra_matrix, s->q_intra_matrix16,

                          s->intra_matrix, s->intra_quant_bias, avctx->qmin,

                          31, 1);

        ff_convert_matrix(&s->dsp, s->q_inter_matrix, s->q_inter_matrix16,

                          s->inter_matrix, s->inter_quant_bias, avctx->qmin,

                          31, 0);

    }



    if (ff_rate_control_init(s) < 0)

        return -1;



#if FF_API_ERROR_RATE

    FF_DISABLE_DEPRECATION_WARNINGS

    if (avctx->error_rate)

        s->error_rate = avctx->error_rate;

    FF_ENABLE_DEPRECATION_WARNINGS;

#endif



    if (avctx->b_frame_strategy == 2) {

        for (i = 0; i < s->max_b_frames + 2; i++) {

            s->tmp_frames[i] = av_frame_alloc();

            if (!s->tmp_frames[i])

                return AVERROR(ENOMEM);



            s->tmp_frames[i]->format = AV_PIX_FMT_YUV420P;

            s->tmp_frames[i]->width  = s->width  >> avctx->brd_scale;

            s->tmp_frames[i]->height = s->height >> avctx->brd_scale;



            ret = av_frame_get_buffer(s->tmp_frames[i], 32);

            if (ret < 0)

                return ret;

        }

    }



    return 0;

fail:

    ff_MPV_encode_end(avctx);

    return AVERROR_UNKNOWN;

}

static int au_write_trailer(AVFormatContext *s)

{

    AVIOContext *pb = s->pb;

    int64_t file_size;



    if (s->pb->seekable) {

        /* update file size */

        file_size = avio_tell(pb);

        avio_seek(pb, 8, SEEK_SET);

        avio_wb32(pb, (uint32_t)(file_size - 24));

        avio_seek(pb, file_size, SEEK_SET);

        avio_flush(pb);

    }



    return 0;

}

static int xa_read_packet(AVFormatContext *s,

                          AVPacket *pkt)

{

    MaxisXADemuxContext *xa = s->priv_data;

    AVStream *st = s->streams[0];

    ByteIOContext *pb = s->pb;

    unsigned int packet_size;

    int ret;



    if(xa->sent_bytes > xa->out_size)

        return AVERROR(EIO);

    /* 1 byte header and 14 bytes worth of samples * number channels per block */

    packet_size = 15*st->codec->channels;



    ret = av_get_packet(pb, pkt, packet_size);

    if(ret != packet_size)

        return AVERROR(EIO);



    pkt->stream_index = st->index;

    xa->sent_bytes += packet_size;

    pkt->pts = xa->audio_frame_counter;

    /* 14 bytes Samples per channel with 2 samples per byte */

    xa->audio_frame_counter += 28 * st->codec->channels;



    return ret;

}

static int unpack_superblocks(Vp3DecodeContext *s, GetBitContext *gb)

{

    int superblock_starts[3] = {

        0, s->u_superblock_start, s->v_superblock_start

    };

    int bit = 0;

    int current_superblock = 0;

    int current_run = 0;

    int num_partial_superblocks = 0;



    int i, j;

    int current_fragment;

    int plane;



    if (s->keyframe) {

        memset(s->superblock_coding, SB_FULLY_CODED, s->superblock_count);

    } else {

        /* unpack the list of partially-coded superblocks */

        bit         = get_bits1(gb) ^ 1;

        current_run = 0;



        while (current_superblock < s->superblock_count && get_bits_left(gb) > 0) {

            if (s->theora && current_run == MAXIMUM_LONG_BIT_RUN)

                bit = get_bits1(gb);

            else

                bit ^= 1;



            current_run = get_vlc2(gb, s->superblock_run_length_vlc.table,

                                   6, 2) + 1;

            if (current_run == 34)

                current_run += get_bits(gb, 12);



            if (current_superblock + current_run > s->superblock_count) {

                av_log(s->avctx, AV_LOG_ERROR,

                       "Invalid partially coded superblock run length\n");

                return -1;

            }



            memset(s->superblock_coding + current_superblock, bit, current_run);



            current_superblock += current_run;

            if (bit)

                num_partial_superblocks += current_run;

        }



        /* unpack the list of fully coded superblocks if any of the blocks were

         * not marked as partially coded in the previous step */

        if (num_partial_superblocks < s->superblock_count) {

            int superblocks_decoded = 0;



            current_superblock = 0;

            bit                = get_bits1(gb) ^ 1;

            current_run        = 0;



            while (superblocks_decoded < s->superblock_count - num_partial_superblocks &&

                   get_bits_left(gb) > 0) {

                if (s->theora && current_run == MAXIMUM_LONG_BIT_RUN)

                    bit = get_bits1(gb);

                else

                    bit ^= 1;



                current_run = get_vlc2(gb, s->superblock_run_length_vlc.table,

                                       6, 2) + 1;

                if (current_run == 34)

                    current_run += get_bits(gb, 12);



                for (j = 0; j < current_run; current_superblock++) {

                    if (current_superblock >= s->superblock_count) {

                        av_log(s->avctx, AV_LOG_ERROR,

                               "Invalid fully coded superblock run length\n");

                        return -1;

                    }



                    /* skip any superblocks already marked as partially coded */

                    if (s->superblock_coding[current_superblock] == SB_NOT_CODED) {

                        s->superblock_coding[current_superblock] = 2 * bit;

                        j++;

                    }

                }

                superblocks_decoded += current_run;

            }

        }



        /* if there were partial blocks, initialize bitstream for

         * unpacking fragment codings */

        if (num_partial_superblocks) {

            current_run = 0;

            bit         = get_bits1(gb);

            /* toggle the bit because as soon as the first run length is

             * fetched the bit will be toggled again */

            bit ^= 1;

        }

    }



    /* figure out which fragments are coded; iterate through each

     * superblock (all planes) */

    s->total_num_coded_frags = 0;

    memset(s->macroblock_coding, MODE_COPY, s->macroblock_count);



    for (plane = 0; plane < 3; plane++) {

        int sb_start = superblock_starts[plane];

        int sb_end   = sb_start + (plane ? s->c_superblock_count

                                         : s->y_superblock_count);

        int num_coded_frags = 0;



        for (i = sb_start; i < sb_end && get_bits_left(gb) > 0; i++) {

            /* iterate through all 16 fragments in a superblock */

            for (j = 0; j < 16; j++) {

                /* if the fragment is in bounds, check its coding status */

                current_fragment = s->superblock_fragments[i * 16 + j];

                if (current_fragment != -1) {

                    int coded = s->superblock_coding[i];



                    if (s->superblock_coding[i] == SB_PARTIALLY_CODED) {

                        /* fragment may or may not be coded; this is the case

                         * that cares about the fragment coding runs */

                        if (current_run-- == 0) {

                            bit        ^= 1;

                            current_run = get_vlc2(gb, s->fragment_run_length_vlc.table, 5, 2);

                        }

                        coded = bit;

                    }



                    if (coded) {

                        /* default mode; actual mode will be decoded in

                         * the next phase */

                        s->all_fragments[current_fragment].coding_method =

                            MODE_INTER_NO_MV;

                        s->coded_fragment_list[plane][num_coded_frags++] =

                            current_fragment;

                    } else {

                        /* not coded; copy this fragment from the prior frame */

                        s->all_fragments[current_fragment].coding_method =

                            MODE_COPY;

                    }

                }

            }

        }

        s->total_num_coded_frags += num_coded_frags;

        for (i = 0; i < 64; i++)

            s->num_coded_frags[plane][i] = num_coded_frags;

        if (plane < 2)

            s->coded_fragment_list[plane + 1] = s->coded_fragment_list[plane] +

                                                num_coded_frags;

    }

    return 0;

}

static int init_video_param(AVCodecContext *avctx, QSVEncContext *q)

{

    float quant;

    int ret;



    ret = ff_qsv_codec_id_to_mfx(avctx->codec_id);

    if (ret < 0)

        return AVERROR_BUG;

    q->param.mfx.CodecId = ret;



    q->width_align = avctx->codec_id == AV_CODEC_ID_HEVC ? 32 : 16;



    if (avctx->level > 0)

        q->param.mfx.CodecLevel = avctx->level;



    q->param.mfx.CodecProfile       = q->profile;

    q->param.mfx.TargetUsage        = q->preset;

    q->param.mfx.GopPicSize         = FFMAX(0, avctx->gop_size);

    q->param.mfx.GopRefDist         = FFMAX(-1, avctx->max_b_frames) + 1;

    q->param.mfx.GopOptFlag         = avctx->flags & AV_CODEC_FLAG_CLOSED_GOP ?

                                      MFX_GOP_CLOSED : 0;

    q->param.mfx.IdrInterval        = q->idr_interval;

    q->param.mfx.NumSlice           = avctx->slices;

    q->param.mfx.NumRefFrame        = FFMAX(0, avctx->refs);

    q->param.mfx.EncodedOrder       = 0;

    q->param.mfx.BufferSizeInKB     = 0;



    q->param.mfx.FrameInfo.FourCC         = MFX_FOURCC_NV12;

    q->param.mfx.FrameInfo.Width          = FFALIGN(avctx->width, q->width_align);

    q->param.mfx.FrameInfo.Height         = FFALIGN(avctx->height, 32);

    q->param.mfx.FrameInfo.CropX          = 0;

    q->param.mfx.FrameInfo.CropY          = 0;

    q->param.mfx.FrameInfo.CropW          = avctx->width;

    q->param.mfx.FrameInfo.CropH          = avctx->height;

    q->param.mfx.FrameInfo.AspectRatioW   = avctx->sample_aspect_ratio.num;

    q->param.mfx.FrameInfo.AspectRatioH   = avctx->sample_aspect_ratio.den;

    q->param.mfx.FrameInfo.PicStruct      = MFX_PICSTRUCT_PROGRESSIVE;

    q->param.mfx.FrameInfo.ChromaFormat   = MFX_CHROMAFORMAT_YUV420;

    q->param.mfx.FrameInfo.BitDepthLuma   = 8;

    q->param.mfx.FrameInfo.BitDepthChroma = 8;



    if (avctx->framerate.den > 0 && avctx->framerate.num > 0) {

        q->param.mfx.FrameInfo.FrameRateExtN = avctx->framerate.num;

        q->param.mfx.FrameInfo.FrameRateExtD = avctx->framerate.den;

    } else {

        q->param.mfx.FrameInfo.FrameRateExtN  = avctx->time_base.den;

        q->param.mfx.FrameInfo.FrameRateExtD  = avctx->time_base.num;

    }



    ret = select_rc_mode(avctx, q);

    if (ret < 0)

        return ret;



    switch (q->param.mfx.RateControlMethod) {

    case MFX_RATECONTROL_CBR:

    case MFX_RATECONTROL_VBR:

#if QSV_HAVE_VCM

    case MFX_RATECONTROL_VCM:

#endif

        q->param.mfx.InitialDelayInKB = avctx->rc_initial_buffer_occupancy / 1000;

        q->param.mfx.TargetKbps       = avctx->bit_rate / 1000;

        q->param.mfx.MaxKbps          = avctx->rc_max_rate / 1000;

        break;

    case MFX_RATECONTROL_CQP:

        quant = avctx->global_quality / FF_QP2LAMBDA;



        q->param.mfx.QPI = av_clip(quant * fabs(avctx->i_quant_factor) + avctx->i_quant_offset, 0, 51);

        q->param.mfx.QPP = av_clip(quant, 0, 51);

        q->param.mfx.QPB = av_clip(quant * fabs(avctx->b_quant_factor) + avctx->b_quant_offset, 0, 51);



        break;

    case MFX_RATECONTROL_AVBR:

        q->param.mfx.TargetKbps  = avctx->bit_rate / 1000;

        q->param.mfx.Convergence = q->avbr_convergence;

        q->param.mfx.Accuracy    = q->avbr_accuracy;

        break;

#if QSV_HAVE_LA

    case MFX_RATECONTROL_LA:

        q->param.mfx.TargetKbps  = avctx->bit_rate / 1000;

        q->extco2.LookAheadDepth = q->la_depth;

        break;

#if QSV_HAVE_ICQ

    case MFX_RATECONTROL_LA_ICQ:

        q->extco2.LookAheadDepth = q->la_depth;

    case MFX_RATECONTROL_ICQ:

        q->param.mfx.ICQQuality  = avctx->global_quality;

        break;

#endif

#endif

    }



    // the HEVC encoder plugin currently fails if coding options

    // are provided

    if (avctx->codec_id != AV_CODEC_ID_HEVC) {

        q->extco.Header.BufferId      = MFX_EXTBUFF_CODING_OPTION;

        q->extco.Header.BufferSz      = sizeof(q->extco);

        q->extco.CAVLC                = avctx->coder_type == FF_CODER_TYPE_VLC ?

                                        MFX_CODINGOPTION_ON : MFX_CODINGOPTION_UNKNOWN;



        if (q->rdo >= 0)

            q->extco.RateDistortionOpt = q->rdo > 0 ? MFX_CODINGOPTION_ON : MFX_CODINGOPTION_OFF;



        if (avctx->codec_id == AV_CODEC_ID_H264) {

            if (avctx->strict_std_compliance != FF_COMPLIANCE_NORMAL)

                q->extco.NalHrdConformance = avctx->strict_std_compliance > FF_COMPLIANCE_NORMAL ?

                                             MFX_CODINGOPTION_ON : MFX_CODINGOPTION_OFF;



            if (q->single_sei_nal_unit >= 0)

                q->extco.SingleSeiNalUnit = q->single_sei_nal_unit ? MFX_CODINGOPTION_ON : MFX_CODINGOPTION_OFF;

            if (q->recovery_point_sei >= 0)

                q->extco.RecoveryPointSEI = q->recovery_point_sei ? MFX_CODINGOPTION_ON : MFX_CODINGOPTION_OFF;

            q->extco.MaxDecFrameBuffering = q->max_dec_frame_buffering;

        }



        q->extparam_internal[q->nb_extparam_internal++] = (mfxExtBuffer *)&q->extco;



#if QSV_HAVE_CO2

        if (avctx->codec_id == AV_CODEC_ID_H264) {

            q->extco2.Header.BufferId     = MFX_EXTBUFF_CODING_OPTION2;

            q->extco2.Header.BufferSz     = sizeof(q->extco2);



            if (q->int_ref_type >= 0)

                q->extco2.IntRefType = q->int_ref_type;

            if (q->int_ref_cycle_size >= 0)

                q->extco2.IntRefCycleSize = q->int_ref_cycle_size;

            if (q->int_ref_qp_delta != INT16_MIN)

                q->extco2.IntRefQPDelta = q->int_ref_qp_delta;



            if (q->bitrate_limit >= 0)

                q->extco2.BitrateLimit = q->bitrate_limit ? MFX_CODINGOPTION_ON : MFX_CODINGOPTION_OFF;

            if (q->mbbrc >= 0)

                q->extco2.MBBRC = q->mbbrc ? MFX_CODINGOPTION_ON : MFX_CODINGOPTION_OFF;

            if (q->extbrc >= 0)

                q->extco2.ExtBRC = q->extbrc ? MFX_CODINGOPTION_ON : MFX_CODINGOPTION_OFF;



            if (q->max_frame_size >= 0)

                q->extco2.MaxFrameSize = q->max_frame_size;

#if QSV_HAVE_MAX_SLICE_SIZE

            if (q->max_slice_size >= 0)

                q->extco2.MaxSliceSize = q->max_slice_size;

#endif



#if QSV_HAVE_TRELLIS

            q->extco2.Trellis = q->trellis;

#endif



#if QSV_HAVE_BREF_TYPE

            if (avctx->b_frame_strategy >= 0)

                q->extco2.BRefType = avctx->b_frame_strategy ? MFX_B_REF_PYRAMID : MFX_B_REF_OFF;

            if (q->adaptive_i >= 0)

                q->extco2.AdaptiveI = q->adaptive_i ? MFX_CODINGOPTION_ON : MFX_CODINGOPTION_OFF;

            if (q->adaptive_b >= 0)

                q->extco2.AdaptiveB = q->adaptive_b ? MFX_CODINGOPTION_ON : MFX_CODINGOPTION_OFF;

#endif



            q->extparam_internal[q->nb_extparam_internal++] = (mfxExtBuffer *)&q->extco2;

        }

#endif

    }



    if (!rc_supported(q)) {

        av_log(avctx, AV_LOG_ERROR,

               "Selected ratecontrol mode is not supported by the QSV "

               "runtime. Choose a different mode.\n");

        return AVERROR(ENOSYS);

    }



    return 0;

}

static void ff_acelp_interpolatef_mips(float *out, const float *in,

                           const float *filter_coeffs, int precision,

                           int frac_pos, int filter_length, int length)

{

    int n, i;

    int prec = precision * 4;

    int fc_offset = precision - frac_pos;

    float in_val_p, in_val_m, fc_val_p, fc_val_m;



    for (n = 0; n < length; n++) {

        /**

        * four pointers are defined in order to minimize number of

        * computations done in inner loop

        */

        const float *p_in_p = &in[n];

        const float *p_in_m = &in[n-1];

        const float *p_filter_coeffs_p = &filter_coeffs[frac_pos];

        const float *p_filter_coeffs_m = filter_coeffs + fc_offset;

        float v = 0;



        for (i = 0; i < filter_length;i++) {

            __asm__ volatile (

                "lwc1   %[in_val_p],           0(%[p_in_p])                    \n\t"

                "lwc1   %[fc_val_p],           0(%[p_filter_coeffs_p])         \n\t"

                "lwc1   %[in_val_m],           0(%[p_in_m])                    \n\t"

                "lwc1   %[fc_val_m],           0(%[p_filter_coeffs_m])         \n\t"

                "addiu  %[p_in_p],             %[p_in_p],              4       \n\t"

                "madd.s %[v],%[v],             %[in_val_p],%[fc_val_p]         \n\t"

                "addiu  %[p_in_m],             %[p_in_m],              -4      \n\t"

                "addu   %[p_filter_coeffs_p],  %[p_filter_coeffs_p],   %[prec] \n\t"

                "addu   %[p_filter_coeffs_m],  %[p_filter_coeffs_m],   %[prec] \n\t"

                "madd.s %[v],%[v],%[in_val_m], %[fc_val_m]                     \n\t"



                : [v] "=&f" (v),[p_in_p] "+r" (p_in_p), [p_in_m] "+r" (p_in_m),

                  [p_filter_coeffs_p] "+r" (p_filter_coeffs_p),

                  [in_val_p] "=&f" (in_val_p), [in_val_m] "=&f" (in_val_m),

                  [fc_val_p] "=&f" (fc_val_p), [fc_val_m] "=&f" (fc_val_m),

                  [p_filter_coeffs_m] "+r" (p_filter_coeffs_m)

                : [prec] "r" (prec)

                : "memory"

            );

        }

        out[n] = v;

    }

}

static int mpegts_push_data(MpegTSFilter *filter,

                            const uint8_t *buf, int buf_size, int is_start,

                            int64_t pos)

{

    PESContext *pes = filter->u.pes_filter.opaque;

    MpegTSContext *ts = pes->ts;

    const uint8_t *p;

    int len, code;



    if(!ts->pkt)

        return 0;



    if (is_start) {

        if (pes->state == MPEGTS_PAYLOAD && pes->data_index > 0) {

            new_pes_packet(pes, ts->pkt);

            ts->stop_parse = 1;

        }

        pes->state = MPEGTS_HEADER;

        pes->data_index = 0;

        pes->ts_packet_pos = pos;

    }

    p = buf;

    while (buf_size > 0) {

        switch(pes->state) {

        case MPEGTS_HEADER:

            len = PES_START_SIZE - pes->data_index;

            if (len > buf_size)

                len = buf_size;

            memcpy(pes->header + pes->data_index, p, len);

            pes->data_index += len;

            p += len;

            buf_size -= len;

            if (pes->data_index == PES_START_SIZE) {

                /* we got all the PES or section header. We can now

                   decide */

                if (pes->header[0] == 0x00 && pes->header[1] == 0x00 &&

                    pes->header[2] == 0x01) {

                    /* it must be an mpeg2 PES stream */

                    code = pes->header[3] | 0x100;

                    av_dlog(pes->stream, "pid=%x pes_code=%#x\n", pes->pid, code);



                    if ((pes->st && pes->st->discard == AVDISCARD_ALL) ||

                        code == 0x1be) /* padding_stream */

                        goto skip;



                    /* stream not present in PMT */

                    if (!pes->st) {

                        pes->st = av_new_stream(ts->stream, pes->pid);

                        if (!pes->st)

                            return AVERROR(ENOMEM);

                        mpegts_set_stream_info(pes->st, pes, 0, 0);

                    }



                    pes->total_size = AV_RB16(pes->header + 4);

                    /* NOTE: a zero total size means the PES size is

                       unbounded */

                    if (!pes->total_size)

                        pes->total_size = MAX_PES_PAYLOAD;



                    /* allocate pes buffer */

                    pes->buffer = av_malloc(pes->total_size+FF_INPUT_BUFFER_PADDING_SIZE);

                    if (!pes->buffer)

                        return AVERROR(ENOMEM);



                    if (code != 0x1bc && code != 0x1bf && /* program_stream_map, private_stream_2 */

                        code != 0x1f0 && code != 0x1f1 && /* ECM, EMM */

                        code != 0x1ff && code != 0x1f2 && /* program_stream_directory, DSMCC_stream */

                        code != 0x1f8) {                  /* ITU-T Rec. H.222.1 type E stream */

                        pes->state = MPEGTS_PESHEADER;

                        if (pes->st->codec->codec_id == CODEC_ID_NONE) {

                            av_dlog(pes->stream, "pid=%x stream_type=%x probing\n",

                                    pes->pid, pes->stream_type);

                            pes->st->codec->codec_id = CODEC_ID_PROBE;

                        }

                    } else {

                        pes->state = MPEGTS_PAYLOAD;

                        pes->data_index = 0;

                    }

                } else {

                    /* otherwise, it should be a table */

                    /* skip packet */

                skip:

                    pes->state = MPEGTS_SKIP;

                    continue;

                }

            }

            break;

            /**********************************************/

            /* PES packing parsing */

        case MPEGTS_PESHEADER:

            len = PES_HEADER_SIZE - pes->data_index;

            if (len < 0)

                return -1;

            if (len > buf_size)

                len = buf_size;

            memcpy(pes->header + pes->data_index, p, len);

            pes->data_index += len;

            p += len;

            buf_size -= len;

            if (pes->data_index == PES_HEADER_SIZE) {

                pes->pes_header_size = pes->header[8] + 9;

                pes->state = MPEGTS_PESHEADER_FILL;

            }

            break;

        case MPEGTS_PESHEADER_FILL:

            len = pes->pes_header_size - pes->data_index;

            if (len < 0)

                return -1;

            if (len > buf_size)

                len = buf_size;

            memcpy(pes->header + pes->data_index, p, len);

            pes->data_index += len;

            p += len;

            buf_size -= len;

            if (pes->data_index == pes->pes_header_size) {

                const uint8_t *r;

                unsigned int flags, pes_ext, skip;



                flags = pes->header[7];

                r = pes->header + 9;

                pes->pts = AV_NOPTS_VALUE;

                pes->dts = AV_NOPTS_VALUE;

                if ((flags & 0xc0) == 0x80) {

                    pes->dts = pes->pts = ff_parse_pes_pts(r);

                    r += 5;

                } else if ((flags & 0xc0) == 0xc0) {

                    pes->pts = ff_parse_pes_pts(r);

                    r += 5;

                    pes->dts = ff_parse_pes_pts(r);

                    r += 5;

                }

                pes->extended_stream_id = -1;

                if (flags & 0x01) { /* PES extension */

                    pes_ext = *r++;

                    /* Skip PES private data, program packet sequence counter and P-STD buffer */

                    skip = (pes_ext >> 4) & 0xb;

                    skip += skip & 0x9;

                    r += skip;

                    if ((pes_ext & 0x41) == 0x01 &&

                        (r + 2) <= (pes->header + pes->pes_header_size)) {

                        /* PES extension 2 */

                        if ((r[0] & 0x7f) > 0 && (r[1] & 0x80) == 0)

                            pes->extended_stream_id = r[1];

                    }

                }



                /* we got the full header. We parse it and get the payload */

                pes->state = MPEGTS_PAYLOAD;

                pes->data_index = 0;

            }

            break;

        case MPEGTS_PAYLOAD:

            if (buf_size > 0 && pes->buffer) {

                if (pes->data_index > 0 && pes->data_index+buf_size > pes->total_size) {

                    new_pes_packet(pes, ts->pkt);

                    pes->total_size = MAX_PES_PAYLOAD;

                    pes->buffer = av_malloc(pes->total_size+FF_INPUT_BUFFER_PADDING_SIZE);

                    if (!pes->buffer)

                        return AVERROR(ENOMEM);

                    ts->stop_parse = 1;

                } else if (pes->data_index == 0 && buf_size > pes->total_size) {

                    // pes packet size is < ts size packet and pes data is padded with 0xff

                    // not sure if this is legal in ts but see issue #2392

                    buf_size = pes->total_size;

                    pes->flags |= AV_PKT_FLAG_CORRUPT;

                }

                memcpy(pes->buffer+pes->data_index, p, buf_size);

                pes->data_index += buf_size;

            }

            buf_size = 0;

            /* emit complete packets with known packet size

             * decreases demuxer delay for infrequent packets like subtitles from

             * a couple of seconds to milliseconds for properly muxed files.

             * total_size is the number of bytes following pes_packet_length

             * in the pes header, i.e. not counting the first 6 bytes */

            if (!ts->stop_parse && pes->total_size < MAX_PES_PAYLOAD &&

                pes->pes_header_size + pes->data_index == pes->total_size + 6) {

                ts->stop_parse = 1;

                new_pes_packet(pes, ts->pkt);

            }

            break;

        case MPEGTS_SKIP:

            buf_size = 0;

            break;

        }

    }



    return 0;

}

static void mov_build_index(MOVContext *mov, AVStream *st)

{

    MOVStreamContext *sc = st->priv_data;

    int64_t current_offset;

    int64_t current_dts = 0;

    unsigned int stts_index = 0;

    unsigned int stsc_index = 0;

    unsigned int stss_index = 0;

    unsigned int stps_index = 0;

    unsigned int i, j;

    uint64_t stream_size = 0;



    /* adjust first dts according to edit list */

    if (sc->time_offset && mov->time_scale > 0) {

        if (sc->time_offset < 0)

            sc->time_offset = av_rescale(sc->time_offset, sc->time_scale, mov->time_scale);

        current_dts = -sc->time_offset;

        if (sc->ctts_data && sc->stts_data && sc->stts_data[0].duration &&

            sc->ctts_data[0].duration / sc->stts_data[0].duration > 16) {

            /* more than 16 frames delay, dts are likely wrong

               this happens with files created by iMovie */

            sc->wrong_dts = 1;

            st->internal->avctx->has_b_frames = 1;

        }

    }



    /* only use old uncompressed audio chunk demuxing when stts specifies it */

    if (!(st->codecpar->codec_type == AVMEDIA_TYPE_AUDIO &&

          sc->stts_count == 1 && sc->stts_data[0].duration == 1)) {

        unsigned int current_sample = 0;

        unsigned int stts_sample = 0;

        unsigned int sample_size;

        unsigned int distance = 0;

        unsigned int rap_group_index = 0;

        unsigned int rap_group_sample = 0;

        int rap_group_present = sc->rap_group_count && sc->rap_group;

        int key_off = (sc->keyframes && sc->keyframes[0] > 0) || (sc->stps_data && sc->stps_data[0] > 0);



        current_dts -= sc->dts_shift;



        if (!sc->sample_count)

            return;

        if (sc->sample_count >= UINT_MAX / sizeof(*st->index_entries) - st->nb_index_entries)

            return;

        if (av_reallocp_array(&st->index_entries,

                              st->nb_index_entries + sc->sample_count,

                              sizeof(*st->index_entries)) < 0) {

            st->nb_index_entries = 0;

            return;

        }

        st->index_entries_allocated_size = (st->nb_index_entries + sc->sample_count) * sizeof(*st->index_entries);



        for (i = 0; i < sc->chunk_count; i++) {

            current_offset = sc->chunk_offsets[i];

            while (mov_stsc_index_valid(stsc_index, sc->stsc_count) &&

                i + 1 == sc->stsc_data[stsc_index + 1].first)

                stsc_index++;

            for (j = 0; j < sc->stsc_data[stsc_index].count; j++) {

                int keyframe = 0;

                if (current_sample >= sc->sample_count) {

                    av_log(mov->fc, AV_LOG_ERROR, "wrong sample count\n");

                    return;

                }



                if (!sc->keyframe_absent && (!sc->keyframe_count || current_sample+key_off == sc->keyframes[stss_index])) {

                    keyframe = 1;

                    if (stss_index + 1 < sc->keyframe_count)

                        stss_index++;

                } else if (sc->stps_count && current_sample+key_off == sc->stps_data[stps_index]) {

                    keyframe = 1;

                    if (stps_index + 1 < sc->stps_count)

                        stps_index++;

                }

                if (rap_group_present && rap_group_index < sc->rap_group_count) {

                    if (sc->rap_group[rap_group_index].index > 0)

                        keyframe = 1;

                    if (++rap_group_sample == sc->rap_group[rap_group_index].count) {

                        rap_group_sample = 0;

                        rap_group_index++;

                    }

                }

                if (keyframe)

                    distance = 0;

                sample_size = sc->sample_size > 0 ? sc->sample_size : sc->sample_sizes[current_sample];

                if (sc->pseudo_stream_id == -1 ||

                   sc->stsc_data[stsc_index].id - 1 == sc->pseudo_stream_id) {

                    AVIndexEntry *e = &st->index_entries[st->nb_index_entries++];

                    e->pos = current_offset;

                    e->timestamp = current_dts;

                    e->size = sample_size;

                    e->min_distance = distance;

                    e->flags = keyframe ? AVINDEX_KEYFRAME : 0;

                    av_log(mov->fc, AV_LOG_TRACE, "AVIndex stream %d, sample %d, offset %"PRIx64", dts %"PRId64", "

                            "size %d, distance %d, keyframe %d\n", st->index, current_sample,

                            current_offset, current_dts, sample_size, distance, keyframe);

                }



                current_offset += sample_size;

                stream_size += sample_size;

                current_dts += sc->stts_data[stts_index].duration;

                distance++;

                stts_sample++;

                current_sample++;

                if (stts_index + 1 < sc->stts_count && stts_sample == sc->stts_data[stts_index].count) {

                    stts_sample = 0;

                    stts_index++;

                }

            }

        }

        if (st->duration > 0)

            st->codecpar->bit_rate = stream_size*8*sc->time_scale/st->duration;

    } else {

        unsigned chunk_samples, total = 0;



        // compute total chunk count

        for (i = 0; i < sc->stsc_count; i++) {

            unsigned count, chunk_count;



            chunk_samples = sc->stsc_data[i].count;

            if (i != sc->stsc_count - 1 &&

                sc->samples_per_frame && chunk_samples % sc->samples_per_frame) {

                av_log(mov->fc, AV_LOG_ERROR, "error unaligned chunk\n");

                return;

            }



            if (sc->samples_per_frame >= 160) { // gsm

                count = chunk_samples / sc->samples_per_frame;

            } else if (sc->samples_per_frame > 1) {

                unsigned samples = (1024/sc->samples_per_frame)*sc->samples_per_frame;

                count = (chunk_samples+samples-1) / samples;

            } else {

                count = (chunk_samples+1023) / 1024;

            }



            if (mov_stsc_index_valid(i, sc->stsc_count))

                chunk_count = sc->stsc_data[i+1].first - sc->stsc_data[i].first;

            else

                chunk_count = sc->chunk_count - (sc->stsc_data[i].first - 1);

            total += chunk_count * count;

        }



        av_log(mov->fc, AV_LOG_TRACE, "chunk count %d\n", total);

        if (total >= UINT_MAX / sizeof(*st->index_entries) - st->nb_index_entries)

            return;

        if (av_reallocp_array(&st->index_entries,

                              st->nb_index_entries + total,

                              sizeof(*st->index_entries)) < 0) {

            st->nb_index_entries = 0;

            return;

        }

        st->index_entries_allocated_size = (st->nb_index_entries + total) * sizeof(*st->index_entries);



        // populate index

        for (i = 0; i < sc->chunk_count; i++) {

            current_offset = sc->chunk_offsets[i];

            if (mov_stsc_index_valid(stsc_index, sc->stsc_count) &&

                i + 1 == sc->stsc_data[stsc_index + 1].first)

                stsc_index++;

            chunk_samples = sc->stsc_data[stsc_index].count;



            while (chunk_samples > 0) {

                AVIndexEntry *e;

                unsigned size, samples;



                if (sc->samples_per_frame > 1 && !sc->bytes_per_frame) {

                    avpriv_request_sample(mov->fc,

                           "Zero bytes per frame, but %d samples per frame",

                           sc->samples_per_frame);

                    return;

                }



                if (sc->samples_per_frame >= 160) { // gsm

                    samples = sc->samples_per_frame;

                    size = sc->bytes_per_frame;

                } else {

                    if (sc->samples_per_frame > 1) {

                        samples = FFMIN((1024 / sc->samples_per_frame)*

                                        sc->samples_per_frame, chunk_samples);

                        size = (samples / sc->samples_per_frame) * sc->bytes_per_frame;

                    } else {

                        samples = FFMIN(1024, chunk_samples);

                        size = samples * sc->sample_size;

                    }

                }



                if (st->nb_index_entries >= total) {

                    av_log(mov->fc, AV_LOG_ERROR, "wrong chunk count %d\n", total);

                    return;

                }

                e = &st->index_entries[st->nb_index_entries++];

                e->pos = current_offset;

                e->timestamp = current_dts;

                e->size = size;

                e->min_distance = 0;

                e->flags = AVINDEX_KEYFRAME;

                av_log(mov->fc, AV_LOG_TRACE, "AVIndex stream %d, chunk %d, offset %"PRIx64", dts %"PRId64", "

                        "size %d, duration %d\n", st->index, i, current_offset, current_dts,

                        size, samples);



                current_offset += size;

                current_dts += samples;

                chunk_samples -= samples;

            }

        }

    }

}

static void video_audio_display(VideoState *s)

{

    int i, i_start, x, y1, y, ys, delay, n, nb_display_channels;

    int ch, channels, h, h2, bgcolor, fgcolor;

    int16_t time_diff;

    int rdft_bits, nb_freq;



    for (rdft_bits = 1; (1 << rdft_bits) < 2 * s->height; rdft_bits++)

        ;

    nb_freq = 1 << (rdft_bits - 1);



    /* compute display index : center on currently output samples */

    channels = s->audio_st->codec->channels;

    nb_display_channels = channels;

    if (!s->paused) {

        int data_used = s->show_audio == 1 ? s->width : (2 * nb_freq);

        n = 2 * channels;

        delay = audio_write_get_buf_size(s);

        delay /= n;



        /* to be more precise, we take into account the time spent since

           the last buffer computation */

        if (audio_callback_time) {

            time_diff = av_gettime() - audio_callback_time;

            delay -= (time_diff * s->audio_st->codec->sample_rate) / 1000000;

        }



        delay += 2 * data_used;

        if (delay < data_used)

            delay = data_used;



        i_start= x = compute_mod(s->sample_array_index - delay * channels, SAMPLE_ARRAY_SIZE);

        if (s->show_audio == 1) {

            h = INT_MIN;

            for (i = 0; i < 1000; i += channels) {

                int idx = (SAMPLE_ARRAY_SIZE + x - i) % SAMPLE_ARRAY_SIZE;

                int a = s->sample_array[idx];

                int b = s->sample_array[(idx + 4 * channels) % SAMPLE_ARRAY_SIZE];

                int c = s->sample_array[(idx + 5 * channels) % SAMPLE_ARRAY_SIZE];

                int d = s->sample_array[(idx + 9 * channels) % SAMPLE_ARRAY_SIZE];

                int score = a - d;

                if (h < score && (b ^ c) < 0) {

                    h = score;

                    i_start = idx;

                }

            }

        }



        s->last_i_start = i_start;

    } else {

        i_start = s->last_i_start;

    }



    bgcolor = SDL_MapRGB(screen->format, 0x00, 0x00, 0x00);

    if (s->show_audio == 1) {

        fill_rectangle(screen,

                       s->xleft, s->ytop, s->width, s->height,

                       bgcolor);



        fgcolor = SDL_MapRGB(screen->format, 0xff, 0xff, 0xff);



        /* total height for one channel */

        h = s->height / nb_display_channels;

        /* graph height / 2 */

        h2 = (h * 9) / 20;

        for (ch = 0; ch < nb_display_channels; ch++) {

            i = i_start + ch;

            y1 = s->ytop + ch * h + (h / 2); /* position of center line */

            for (x = 0; x < s->width; x++) {

                y = (s->sample_array[i] * h2) >> 15;

                if (y < 0) {

                    y = -y;

                    ys = y1 - y;

                } else {

                    ys = y1;

                }

                fill_rectangle(screen,

                               s->xleft + x, ys, 1, y,

                               fgcolor);

                i += channels;

                if (i >= SAMPLE_ARRAY_SIZE)

                    i -= SAMPLE_ARRAY_SIZE;

            }

        }



        fgcolor = SDL_MapRGB(screen->format, 0x00, 0x00, 0xff);



        for (ch = 1; ch < nb_display_channels; ch++) {

            y = s->ytop + ch * h;

            fill_rectangle(screen,

                           s->xleft, y, s->width, 1,

                           fgcolor);

        }

        SDL_UpdateRect(screen, s->xleft, s->ytop, s->width, s->height);

    } else {

        nb_display_channels= FFMIN(nb_display_channels, 2);

        if (rdft_bits != s->rdft_bits) {

            av_rdft_end(s->rdft);

            av_free(s->rdft_data);

            s->rdft = av_rdft_init(rdft_bits, DFT_R2C);

            s->rdft_bits = rdft_bits;

            s->rdft_data = av_malloc(4 * nb_freq * sizeof(*s->rdft_data));

        }

        {

            FFTSample *data[2];

            for (ch = 0; ch < nb_display_channels; ch++) {

                data[ch] = s->rdft_data + 2 * nb_freq * ch;

                i = i_start + ch;

                for (x = 0; x < 2 * nb_freq; x++) {

                    double w = (x-nb_freq) * (1.0 / nb_freq);

                    data[ch][x] = s->sample_array[i] * (1.0 - w * w);

                    i += channels;

                    if (i >= SAMPLE_ARRAY_SIZE)

                        i -= SAMPLE_ARRAY_SIZE;

                }

                av_rdft_calc(s->rdft, data[ch]);

            }

            // least efficient way to do this, we should of course directly access it but its more than fast enough

            for (y = 0; y < s->height; y++) {

                double w = 1 / sqrt(nb_freq);

                int a = sqrt(w * sqrt(data[0][2 * y + 0] * data[0][2 * y + 0] + data[0][2 * y + 1] * data[0][2 * y + 1]));

                int b = (nb_display_channels == 2 ) ? sqrt(w * sqrt(data[1][2 * y + 0] * data[1][2 * y + 0]

                       + data[1][2 * y + 1] * data[1][2 * y + 1])) : a;

                a = FFMIN(a, 255);

                b = FFMIN(b, 255);

                fgcolor = SDL_MapRGB(screen->format, a, b, (a + b) / 2);



                fill_rectangle(screen,

                            s->xpos, s->height-y, 1, 1,

                            fgcolor);

            }

        }

        SDL_UpdateRect(screen, s->xpos, s->ytop, 1, s->height);

        s->xpos++;

        if (s->xpos >= s->width)

            s->xpos= s->xleft;

    }

}

int ff_get_cpu_flags_arm(void)
{
    int flags = CORE_CPU_FLAGS;
    uint32_t hwcap;
    if (get_hwcap(&hwcap) < 0)
        if (get_cpuinfo(&hwcap) < 0)
            return flags;
#define check_cap(cap, flag) do {               \
        if (hwcap & HWCAP_ ## cap)              \
            flags |= AV_CPU_FLAG_ ## flag;      \
    } while (0)
    /* No flags explicitly indicate v6 or v6T2 so check others which
       imply support. */
    check_cap(EDSP,    ARMV5TE);
    check_cap(TLS,     ARMV6);
    check_cap(THUMBEE, ARMV6T2);
    check_cap(VFP,     VFP);
    check_cap(VFPv3,   VFPV3);
    check_cap(NEON,    NEON);
    /* The v6 checks above are not reliable so let higher flags
       trickle down. */
    if (flags & (AV_CPU_FLAG_VFPV3 | AV_CPU_FLAG_NEON))
        flags |= AV_CPU_FLAG_ARMV6T2;
    if (flags & AV_CPU_FLAG_ARMV6T2)
        flags |= AV_CPU_FLAG_ARMV6;
    return flags;
}

static void avc_luma_vt_4w_msa(const uint8_t *src, int32_t src_stride,

                               uint8_t *dst, int32_t dst_stride,

                               int32_t height)

{

    int32_t loop_cnt;

    int16_t filt_const0 = 0xfb01;

    int16_t filt_const1 = 0x1414;

    int16_t filt_const2 = 0x1fb;

    v16i8 src0, src1, src2, src3, src4, src5, src6, src7, src8;

    v16i8 src10_r, src32_r, src54_r, src76_r, src21_r, src43_r, src65_r;

    v16i8 src87_r, src2110, src4332, src6554, src8776;

    v16i8 filt0, filt1, filt2;

    v8i16 out10, out32;

    v16u8 out;



    filt0 = (v16i8) __msa_fill_h(filt_const0);

    filt1 = (v16i8) __msa_fill_h(filt_const1);

    filt2 = (v16i8) __msa_fill_h(filt_const2);



    LD_SB5(src, src_stride, src0, src1, src2, src3, src4);

    src += (5 * src_stride);



    ILVR_B4_SB(src1, src0, src2, src1, src3, src2, src4, src3,

               src10_r, src21_r, src32_r, src43_r);

    ILVR_D2_SB(src21_r, src10_r, src43_r, src32_r, src2110, src4332);

    XORI_B2_128_SB(src2110, src4332);



    for (loop_cnt = (height >> 2); loop_cnt--;) {

        LD_SB4(src, src_stride, src5, src6, src7, src8);

        src += (4 * src_stride);



        ILVR_B4_SB(src5, src4, src6, src5, src7, src6, src8, src7,

                   src54_r, src65_r, src76_r, src87_r);

        ILVR_D2_SB(src65_r, src54_r, src87_r, src76_r, src6554, src8776);

        XORI_B2_128_SB(src6554, src8776);

        out10 = DPADD_SH3_SH(src2110, src4332, src6554, filt0, filt1, filt2);

        out32 = DPADD_SH3_SH(src4332, src6554, src8776, filt0, filt1, filt2);

        SRARI_H2_SH(out10, out32, 5);

        SAT_SH2_SH(out10, out32, 7);

        out = PCKEV_XORI128_UB(out10, out32);

        ST4x4_UB(out, out, 0, 1, 2, 3, dst, dst_stride);



        dst += (4 * dst_stride);

        src2110 = src6554;

        src4332 = src8776;

        src4 = src8;

    }

}

static int flashsv_decode_frame(AVCodecContext *avctx, void *data,

                                int *got_frame, AVPacket *avpkt)

{

    int buf_size       = avpkt->size;

    FlashSVContext *s  = avctx->priv_data;

    int h_blocks, v_blocks, h_part, v_part, i, j;

    GetBitContext gb;



    /* no supplementary picture */

    if (buf_size == 0)

        return 0;

    if (buf_size < 4)

        return -1;



    init_get_bits(&gb, avpkt->data, buf_size * 8);



    /* start to parse the bitstream */

    s->block_width  = 16 * (get_bits(&gb,  4) + 1);

    s->image_width  =       get_bits(&gb, 12);

    s->block_height = 16 * (get_bits(&gb,  4) + 1);

    s->image_height =       get_bits(&gb, 12);



    if (s->ver == 2) {

        skip_bits(&gb, 6);

        if (get_bits1(&gb)) {

            av_log_missing_feature(avctx, "iframe", 1);

            return AVERROR_PATCHWELCOME;

        }

        if (get_bits1(&gb)) {

            av_log_missing_feature(avctx, "Custom palette", 1);

            return AVERROR_PATCHWELCOME;

        }

    }



    /* calculate number of blocks and size of border (partial) blocks */

    h_blocks = s->image_width  / s->block_width;

    h_part   = s->image_width  % s->block_width;

    v_blocks = s->image_height / s->block_height;

    v_part   = s->image_height % s->block_height;



    /* the block size could change between frames, make sure the buffer

     * is large enough, if not, get a larger one */

    if (s->block_size < s->block_width * s->block_height) {

        int tmpblock_size = 3 * s->block_width * s->block_height;



        s->tmpblock = av_realloc(s->tmpblock, tmpblock_size);

        if (!s->tmpblock) {

            av_log(avctx, AV_LOG_ERROR, "Can't allocate decompression buffer.\n");

            return AVERROR(ENOMEM);

        }

        if (s->ver == 2) {

            s->deflate_block_size = calc_deflate_block_size(tmpblock_size);

            if (s->deflate_block_size <= 0) {

                av_log(avctx, AV_LOG_ERROR, "Can't determine deflate buffer size.\n");

                return -1;

            }

            s->deflate_block = av_realloc(s->deflate_block, s->deflate_block_size);

            if (!s->deflate_block) {

                av_log(avctx, AV_LOG_ERROR, "Can't allocate deflate buffer.\n");

                return AVERROR(ENOMEM);

            }

        }

    }

    s->block_size = s->block_width * s->block_height;



    /* initialize the image size once */

    if (avctx->width == 0 && avctx->height == 0) {

        avcodec_set_dimensions(avctx, s->image_width, s->image_height);

    }



    /* check for changes of image width and image height */

    if (avctx->width != s->image_width || avctx->height != s->image_height) {

        av_log(avctx, AV_LOG_ERROR,

               "Frame width or height differs from first frame!\n");

        av_log(avctx, AV_LOG_ERROR, "fh = %d, fv %d  vs  ch = %d, cv = %d\n",

               avctx->height, avctx->width, s->image_height, s->image_width);

        return AVERROR_INVALIDDATA;

    }



    /* we care for keyframes only in Screen Video v2 */

    s->is_keyframe = (avpkt->flags & AV_PKT_FLAG_KEY) && (s->ver == 2);

    if (s->is_keyframe) {

        s->keyframedata = av_realloc(s->keyframedata, avpkt->size);

        memcpy(s->keyframedata, avpkt->data, avpkt->size);

    }

    if(s->ver == 2)

        s->blocks = av_realloc(s->blocks,

                                (v_blocks + !!v_part) * (h_blocks + !!h_part)

                                * sizeof(s->blocks[0]));



    av_dlog(avctx, "image: %dx%d block: %dx%d num: %dx%d part: %dx%d\n",

            s->image_width, s->image_height, s->block_width, s->block_height,

            h_blocks, v_blocks, h_part, v_part);



    s->frame.reference    = 3;

    s->frame.buffer_hints = FF_BUFFER_HINTS_VALID    |

                            FF_BUFFER_HINTS_PRESERVE |

                            FF_BUFFER_HINTS_REUSABLE;

    if (avctx->reget_buffer(avctx, &s->frame) < 0) {

        av_log(avctx, AV_LOG_ERROR, "reget_buffer() failed\n");

        return -1;

    }



    /* loop over all block columns */

    for (j = 0; j < v_blocks + (v_part ? 1 : 0); j++) {



        int y_pos  = j * s->block_height; // vertical position in frame

        int cur_blk_height = (j < v_blocks) ? s->block_height : v_part;



        /* loop over all block rows */

        for (i = 0; i < h_blocks + (h_part ? 1 : 0); i++) {

            int x_pos = i * s->block_width; // horizontal position in frame

            int cur_blk_width = (i < h_blocks) ? s->block_width : h_part;

            int has_diff = 0;



            /* get the size of the compressed zlib chunk */

            int size = get_bits(&gb, 16);



            s->color_depth    = 0;

            s->zlibprime_curr = 0;

            s->zlibprime_prev = 0;

            s->diff_start     = 0;

            s->diff_height    = cur_blk_height;



            if (8 * size > get_bits_left(&gb)) {

                avctx->release_buffer(avctx, &s->frame);

                s->frame.data[0] = NULL;

                return AVERROR_INVALIDDATA;

            }



            if (s->ver == 2 && size) {

                skip_bits(&gb, 3);

                s->color_depth    = get_bits(&gb, 2);

                has_diff          = get_bits1(&gb);

                s->zlibprime_curr = get_bits1(&gb);

                s->zlibprime_prev = get_bits1(&gb);



                if (s->color_depth != 0 && s->color_depth != 2) {

                    av_log(avctx, AV_LOG_ERROR,

                           "%dx%d invalid color depth %d\n", i, j, s->color_depth);

                    return AVERROR_INVALIDDATA;

                }



                if (has_diff) {

                    if (!s->keyframe) {

                        av_log(avctx, AV_LOG_ERROR,

                               "inter frame without keyframe\n");

                        return AVERROR_INVALIDDATA;

                    }

                    s->diff_start  = get_bits(&gb, 8);

                    s->diff_height = get_bits(&gb, 8);

                    av_log(avctx, AV_LOG_DEBUG,

                           "%dx%d diff start %d height %d\n",

                           i, j, s->diff_start, s->diff_height);

                    size -= 2;

                }



                if (s->zlibprime_prev)

                    av_log(avctx, AV_LOG_DEBUG, "%dx%d zlibprime_prev\n", i, j);



                if (s->zlibprime_curr) {

                    int col = get_bits(&gb, 8);

                    int row = get_bits(&gb, 8);

                    av_log(avctx, AV_LOG_DEBUG, "%dx%d zlibprime_curr %dx%d\n", i, j, col, row);

                    size -= 2;

                    av_log_missing_feature(avctx, "zlibprime_curr", 1);

                    return AVERROR_PATCHWELCOME;

                }

                if (!s->blocks && (s->zlibprime_curr || s->zlibprime_prev)) {

                    av_log(avctx, AV_LOG_ERROR, "no data available for zlib "

                           "priming\n");

                    return AVERROR_INVALIDDATA;

                }

                size--; // account for flags byte

            }



            if (has_diff) {

                int k;

                int off = (s->image_height - y_pos - 1) * s->frame.linesize[0];



                for (k = 0; k < cur_blk_height; k++)

                    memcpy(s->frame.data[0] + off - k*s->frame.linesize[0] + x_pos*3,

                           s->keyframe + off - k*s->frame.linesize[0] + x_pos*3,

                           cur_blk_width * 3);

            }



            /* skip unchanged blocks, which have size 0 */

            if (size) {

                if (flashsv_decode_block(avctx, avpkt, &gb, size,

                                         cur_blk_width, cur_blk_height,

                                         x_pos, y_pos,

                                         i + j * (h_blocks + !!h_part)))

                    av_log(avctx, AV_LOG_ERROR,

                           "error in decompression of block %dx%d\n", i, j);

            }

        }

    }

    if (s->is_keyframe && s->ver == 2) {

        if (!s->keyframe) {

            s->keyframe = av_malloc(s->frame.linesize[0] * avctx->height);

            if (!s->keyframe) {

                av_log(avctx, AV_LOG_ERROR, "Cannot allocate image data\n");

                return AVERROR(ENOMEM);

            }

        }

        memcpy(s->keyframe, s->frame.data[0], s->frame.linesize[0] * avctx->height);

    }



    *got_frame = 1;

    *(AVFrame*)data = s->frame;



    if ((get_bits_count(&gb) / 8) != buf_size)

        av_log(avctx, AV_LOG_ERROR, "buffer not fully consumed (%d != %d)\n",

               buf_size, (get_bits_count(&gb) / 8));



    /* report that the buffer was completely consumed */

    return buf_size;

}

static void decode_subband(DiracContext *s, GetBitContext *gb, int quant,

                           int slice_x, int slice_y, int bits_end,

                           SubBand *b1, SubBand *b2)

{

    int left   = b1->width  * slice_x    / s->num_x;

    int right  = b1->width  *(slice_x+1) / s->num_x;

    int top    = b1->height * slice_y    / s->num_y;

    int bottom = b1->height *(slice_y+1) / s->num_y;



    int qfactor, qoffset;



    uint8_t *buf1 =      b1->ibuf + top * b1->stride;

    uint8_t *buf2 = b2 ? b2->ibuf + top * b2->stride: NULL;

    int x, y;



    if (quant > 115) {

        av_log(s->avctx, AV_LOG_ERROR, "Unsupported quant %d\n", quant);

        return;

    }

    qfactor = ff_dirac_qscale_tab[quant & 0x7f];

    qoffset = ff_dirac_qoffset_intra_tab[quant & 0x7f] + 2;

    /* we have to constantly check for overread since the spec explicitly

       requires this, with the meaning that all remaining coeffs are set to 0 */

    if (get_bits_count(gb) >= bits_end)

        return;



    if (s->pshift) {

        for (y = top; y < bottom; y++) {

            for (x = left; x < right; x++) {

                PARSE_VALUES(int32_t, x, gb, bits_end, buf1, buf2);

            }

            buf1 += b1->stride;

            if (buf2)

                buf2 += b2->stride;

        }

    }

    else {

        for (y = top; y < bottom; y++) {

            for (x = left; x < right; x++) {

                PARSE_VALUES(int16_t, x, gb, bits_end, buf1, buf2);

            }

            buf1 += b1->stride;

            if (buf2)

                buf2 += b2->stride;

        }

    }

}

static int decode_p_block(FourXContext *f, uint16_t *dst, uint16_t *src,

                          int log2w, int log2h, int stride)

{

    const int index = size2index[log2h][log2w];

    const int h     = 1 << log2h;

    int code        = get_vlc2(&f->gb,

                               block_type_vlc[1 - (f->version > 1)][index].table,

                               BLOCK_TYPE_VLC_BITS, 1);

    uint16_t *start = (uint16_t *)f->last_picture->data[0];

    uint16_t *end   = start + stride * (f->avctx->height - h + 1) - (1 << log2w);

    int ret;



    if (code < 0 || code > 6 || log2w < 0)

        return AVERROR_INVALIDDATA;



    if (code == 0) {

        src += f->mv[bytestream2_get_byte(&f->g)];

        if (start > src || src > end) {

            av_log(f->avctx, AV_LOG_ERROR, "mv out of pic\n");

            return AVERROR_INVALIDDATA;

        }

        mcdc(dst, src, log2w, h, stride, 1, 0);

    } else if (code == 1) {

        log2h--;

        if ((ret = decode_p_block(f, dst, src, log2w, log2h, stride)) < 0)

            return ret;

        if ((ret = decode_p_block(f, dst + (stride << log2h),

                                  src + (stride << log2h),

                                  log2w, log2h, stride)) < 0)

            return ret;

    } else if (code == 2) {

        log2w--;

        if ((ret = decode_p_block(f, dst , src, log2w, log2h, stride)) < 0)

            return ret;

        if ((ret = decode_p_block(f, dst + (1 << log2w),

                                  src + (1 << log2w),

                                  log2w, log2h, stride)) < 0)

            return ret;

    } else if (code == 3 && f->version < 2) {

        if (start > src || src > end) {

            av_log(f->avctx, AV_LOG_ERROR, "mv out of pic\n");

            return AVERROR_INVALIDDATA;

        }

        mcdc(dst, src, log2w, h, stride, 1, 0);

    } else if (code == 4) {

        src += f->mv[bytestream2_get_byte(&f->g)];

        if (start > src || src > end) {

            av_log(f->avctx, AV_LOG_ERROR, "mv out of pic\n");

            return AVERROR_INVALIDDATA;

        }

        mcdc(dst, src, log2w, h, stride, 1, bytestream2_get_le16(&f->g2));

    } else if (code == 5) {

        if (start > src || src > end) {

            av_log(f->avctx, AV_LOG_ERROR, "mv out of pic\n");

            return AVERROR_INVALIDDATA;

        }

        mcdc(dst, src, log2w, h, stride, 0, bytestream2_get_le16(&f->g2));

    } else if (code == 6) {

        if (log2w) {

            dst[0]      = bytestream2_get_le16(&f->g2);

            dst[1]      = bytestream2_get_le16(&f->g2);

        } else {

            dst[0]      = bytestream2_get_le16(&f->g2);

            dst[stride] = bytestream2_get_le16(&f->g2);

        }

    }

    return 0;

}

static inline int wv_unpack_mono(WavpackFrameContext *s, GetBitContext *gb, void *dst, const int type)

{

    int i, j, count = 0;

    int last, t;

    int A, S, T;

    int pos = s->pos;

    uint32_t crc = s->sc.crc;

    uint32_t crc_extra_bits = s->extra_sc.crc;

    int16_t *dst16 = dst;

    int32_t *dst32 = dst;

    float   *dstfl = dst;

    const int channel_stride = s->avctx->channels;



    if(s->samples_left == s->samples)

        s->one = s->zero = s->zeroes = 0;

    do{

        T = wv_get_value(s, gb, 0, &last);

        S = 0;

        if(last) break;

        for(i = 0; i < s->terms; i++){

            t = s->decorr[i].value;

            if(t > 8){

                if(t & 1)

                    A = 2 * s->decorr[i].samplesA[0] - s->decorr[i].samplesA[1];

                else

                    A = (3 * s->decorr[i].samplesA[0] - s->decorr[i].samplesA[1]) >> 1;

                s->decorr[i].samplesA[1] = s->decorr[i].samplesA[0];

                j = 0;

            }else{

                A = s->decorr[i].samplesA[pos];

                j = (pos + t) & 7;

            }

            if(type != AV_SAMPLE_FMT_S16)

                S = T + ((s->decorr[i].weightA * (int64_t)A + 512) >> 10);

            else

                S = T + ((s->decorr[i].weightA * A + 512) >> 10);

            if(A && T) s->decorr[i].weightA -= ((((T ^ A) >> 30) & 2) - 1) * s->decorr[i].delta;

            s->decorr[i].samplesA[j] = T = S;

        }

        pos = (pos + 1) & 7;

        crc = crc * 3 + S;



        if(type == AV_SAMPLE_FMT_FLT){

            *dstfl = wv_get_value_float(s, &crc_extra_bits, S);

            dstfl += channel_stride;

        }else if(type == AV_SAMPLE_FMT_S32){

            *dst32 = wv_get_value_integer(s, &crc_extra_bits, S);

            dst32 += channel_stride;

        }else{

            *dst16 = wv_get_value_integer(s, &crc_extra_bits, S);

            dst16 += channel_stride;

        }

        count++;

    }while(!last && count < s->max_samples);



    s->samples_left -= count;

    if(!s->samples_left){

        wv_reset_saved_context(s);

        if(crc != s->CRC){

            av_log(s->avctx, AV_LOG_ERROR, "CRC error\n");

            return -1;

        }

        if(s->got_extra_bits && crc_extra_bits != s->crc_extra_bits){

            av_log(s->avctx, AV_LOG_ERROR, "Extra bits CRC error\n");

            return -1;

        }

    }else{

        s->pos = pos;

        s->sc.crc = crc;

        s->sc.bits_used = get_bits_count(&s->gb);

        if(s->got_extra_bits){

            s->extra_sc.crc = crc_extra_bits;

            s->extra_sc.bits_used = get_bits_count(&s->gb_extra_bits);

        }

    }

    return count;

}

static void FUNC(hevc_loop_filter_luma)(uint8_t *_pix,

                                        ptrdiff_t _xstride, ptrdiff_t _ystride,

                                        int *_beta, int *_tc,

                                        uint8_t *_no_p, uint8_t *_no_q)

{

    int d, j;

    pixel *pix        = (pixel *)_pix;

    ptrdiff_t xstride = _xstride / sizeof(pixel);

    ptrdiff_t ystride = _ystride / sizeof(pixel);



    for (j = 0; j < 2; j++) {

        const int dp0  = abs(P2  - 2 * P1  + P0);

        const int dq0  = abs(Q2  - 2 * Q1  + Q0);

        const int dp3  = abs(TP2 - 2 * TP1 + TP0);

        const int dq3  = abs(TQ2 - 2 * TQ1 + TQ0);

        const int d0   = dp0 + dq0;

        const int d3   = dp3 + dq3;

        const int beta = _beta[j] << (BIT_DEPTH - 8);

        const int tc   = _tc[j]   << (BIT_DEPTH - 8);

        const int no_p = _no_p[j];

        const int no_q = _no_q[j];



        if (d0 + d3 >= beta) {

            pix += 4 * ystride;

            continue;

        } else {

            const int beta_3 = beta >> 3;

            const int beta_2 = beta >> 2;

            const int tc25   = ((tc * 5 + 1) >> 1);



            if (abs(P3  -  P0) + abs(Q3  -  Q0) < beta_3 && abs(P0  -  Q0) < tc25 &&

                abs(TP3 - TP0) + abs(TQ3 - TQ0) < beta_3 && abs(TP0 - TQ0) < tc25 &&

                                      (d0 << 1) < beta_2 &&      (d3 << 1) < beta_2) {

                // strong filtering

                const int tc2 = tc << 1;

                for (d = 0; d < 4; d++) {

                    const int p3 = P3;

                    const int p2 = P2;

                    const int p1 = P1;

                    const int p0 = P0;

                    const int q0 = Q0;

                    const int q1 = Q1;

                    const int q2 = Q2;

                    const int q3 = Q3;

                    if (!no_p) {

                        P0 = p0 + av_clip(((p2 + 2 * p1 + 2 * p0 + 2 * q0 + q1 + 4) >> 3) - p0, -tc2, tc2);

                        P1 = p1 + av_clip(((p2 + p1 + p0 + q0 + 2) >> 2) - p1, -tc2, tc2);

                        P2 = p2 + av_clip(((2 * p3 + 3 * p2 + p1 + p0 + q0 + 4) >> 3) - p2, -tc2, tc2);

                    }

                    if (!no_q) {

                        Q0 = q0 + av_clip(((p1 + 2 * p0 + 2 * q0 + 2 * q1 + q2 + 4) >> 3) - q0, -tc2, tc2);

                        Q1 = q1 + av_clip(((p0 + q0 + q1 + q2 + 2) >> 2) - q1, -tc2, tc2);

                        Q2 = q2 + av_clip(((2 * q3 + 3 * q2 + q1 + q0 + p0 + 4) >> 3) - q2, -tc2, tc2);

                    }

                    pix += ystride;

                }

            } else { // normal filtering

                int nd_p = 1;

                int nd_q = 1;

                const int tc_2 = tc >> 1;

                if (dp0 + dp3 < ((beta + (beta >> 1)) >> 3))

                    nd_p = 2;

                if (dq0 + dq3 < ((beta + (beta >> 1)) >> 3))

                    nd_q = 2;



                for (d = 0; d < 4; d++) {

                    const int p2 = P2;

                    const int p1 = P1;

                    const int p0 = P0;

                    const int q0 = Q0;

                    const int q1 = Q1;

                    const int q2 = Q2;

                    int delta0   = (9 * (q0 - p0) - 3 * (q1 - p1) + 8) >> 4;

                    if (abs(delta0) < 10 * tc) {

                        delta0 = av_clip(delta0, -tc, tc);

                        if (!no_p)

                            P0 = av_clip_pixel(p0 + delta0);

                        if (!no_q)

                            Q0 = av_clip_pixel(q0 - delta0);

                        if (!no_p && nd_p > 1) {

                            const int deltap1 = av_clip((((p2 + p0 + 1) >> 1) - p1 + delta0) >> 1, -tc_2, tc_2);

                            P1 = av_clip_pixel(p1 + deltap1);

                        }

                        if (!no_q && nd_q > 1) {

                            const int deltaq1 = av_clip((((q2 + q0 + 1) >> 1) - q1 - delta0) >> 1, -tc_2, tc_2);

                            Q1 = av_clip_pixel(q1 + deltaq1);

                        }

                    }

                    pix += ystride;

                }

            }

        }

    }

}

static inline void RENAME(rgb24to16)(const uint8_t *src, uint8_t *dst, long src_size)

{

	const uint8_t *s = src;

	const uint8_t *end;

#ifdef HAVE_MMX

	const uint8_t *mm_end;

#endif

	uint16_t *d = (uint16_t *)dst;

	end = s + src_size;

#ifdef HAVE_MMX

	__asm __volatile(PREFETCH"	%0"::"m"(*src):"memory");

	__asm __volatile(

	    "movq	%0, %%mm7\n\t"

	    "movq	%1, %%mm6\n\t"

	    ::"m"(red_16mask),"m"(green_16mask));

	mm_end = end - 11;

	while(s < mm_end)

	{

	    __asm __volatile(

		PREFETCH" 32%1\n\t"

		"movd	%1, %%mm0\n\t"

		"movd	3%1, %%mm3\n\t"

		"punpckldq 6%1, %%mm0\n\t"

		"punpckldq 9%1, %%mm3\n\t"

		"movq	%%mm0, %%mm1\n\t"

		"movq	%%mm0, %%mm2\n\t"

		"movq	%%mm3, %%mm4\n\t"

		"movq	%%mm3, %%mm5\n\t"

		"psrlq	$3, %%mm0\n\t"

		"psrlq	$3, %%mm3\n\t"

		"pand	%2, %%mm0\n\t"

		"pand	%2, %%mm3\n\t"

		"psrlq	$5, %%mm1\n\t"

		"psrlq	$5, %%mm4\n\t"

		"pand	%%mm6, %%mm1\n\t"

		"pand	%%mm6, %%mm4\n\t"

		"psrlq	$8, %%mm2\n\t"

		"psrlq	$8, %%mm5\n\t"

		"pand	%%mm7, %%mm2\n\t"

		"pand	%%mm7, %%mm5\n\t"

		"por	%%mm1, %%mm0\n\t"

		"por	%%mm4, %%mm3\n\t"

		"por	%%mm2, %%mm0\n\t"

		"por	%%mm5, %%mm3\n\t"

		"psllq	$16, %%mm3\n\t"

		"por	%%mm3, %%mm0\n\t"

		MOVNTQ"	%%mm0, %0\n\t"

		:"=m"(*d):"m"(*s),"m"(blue_16mask):"memory");

		d += 4;

		s += 12;

	}

	__asm __volatile(SFENCE:::"memory");

	__asm __volatile(EMMS:::"memory");

#endif

	while(s < end)

	{

		const int b= *s++;

		const int g= *s++;

		const int r= *s++;

		*d++ = (b>>3) | ((g&0xFC)<<3) | ((r&0xF8)<<8);

	}

}

static int mp3_read_probe(AVProbeData *p)

{

    int max_frames, first_frames = 0;

    int fsize, frames, sample_rate;

    uint32_t header;

    uint8_t *buf, *buf2, *end;

    AVCodecContext avctx;



    if(id3v2_match(p->buf))

        return AVPROBE_SCORE_MAX/2+1; // this must be less than mpeg-ps because some retards put id3v2 tags before mpeg-ps files



    max_frames = 0;

    buf = p->buf;

    end = buf + p->buf_size - sizeof(uint32_t);



    for(; buf < end; buf= buf2+1) {

        buf2 = buf;



        for(frames = 0; buf2 < end; frames++) {

            header = AV_RB32(buf2);

            fsize = ff_mpa_decode_header(&avctx, header, &sample_rate);

            if(fsize < 0)

                break;

            buf2 += fsize;

        }

        max_frames = FFMAX(max_frames, frames);

        if(buf == p->buf)

            first_frames= frames;

    }

    if   (first_frames>=3) return AVPROBE_SCORE_MAX/2+1;

    else if(max_frames>500)return AVPROBE_SCORE_MAX/2;

    else if(max_frames>=3) return AVPROBE_SCORE_MAX/4;

    else if(max_frames>=1) return 1;

    else                   return 0;

}

static int ljpeg_encode_yuv(AVCodecContext *avctx, PutBitContext *pb,

                            const AVFrame *frame)

{

    const int predictor = avctx->prediction_method + 1;

    LJpegEncContext *s  = avctx->priv_data;

    const int mb_width  = (avctx->width  + s->hsample[0] - 1) / s->hsample[0];

    const int mb_height = (avctx->height + s->vsample[0] - 1) / s->vsample[0];

    int mb_x, mb_y;



    for (mb_y = 0; mb_y < mb_height; mb_y++) {

        if (pb->buf_end - pb->buf - (put_bits_count(pb) >> 3) <

            mb_width * 4 * 3 * s->hsample[0] * s->vsample[0]) {

            av_log(avctx, AV_LOG_ERROR, "encoded frame too large\n");

            return -1;

        }



        for (mb_x = 0; mb_x < mb_width; mb_x++)

            ljpeg_encode_yuv_mb(s, pb, frame, predictor, mb_x, mb_y);

    }



    return 0;

}

static av_cold int ra144_decode_init(AVCodecContext * avctx)
{
    RA144Context *ractx = avctx->priv_data;
    ractx->avctx = avctx;
    ractx->lpc_coef[0] = ractx->lpc_tables[0];
    ractx->lpc_coef[1] = ractx->lpc_tables[1];
    avctx->channels       = 1;
    avctx->channel_layout = AV_CH_LAYOUT_MONO;
    avctx->sample_fmt     = AV_SAMPLE_FMT_S16;
    return 0;
}

static int alloc_tables(H264Context *h){

    MpegEncContext * const s = &h->s;

    const int big_mb_num= s->mb_stride * (s->mb_height+1);

    int x,y;



    CHECKED_ALLOCZ(h->intra4x4_pred_mode, big_mb_num * 8  * sizeof(uint8_t))



    CHECKED_ALLOCZ(h->non_zero_count    , big_mb_num * 16 * sizeof(uint8_t))

    CHECKED_ALLOCZ(h->slice_table_base  , (big_mb_num+s->mb_stride) * sizeof(uint8_t))

    CHECKED_ALLOCZ(h->cbp_table, big_mb_num * sizeof(uint16_t))



    if( h->pps.cabac ) {

        CHECKED_ALLOCZ(h->chroma_pred_mode_table, big_mb_num * sizeof(uint8_t))

        CHECKED_ALLOCZ(h->mvd_table[0], 32*big_mb_num * sizeof(uint16_t));

        CHECKED_ALLOCZ(h->mvd_table[1], 32*big_mb_num * sizeof(uint16_t));

        CHECKED_ALLOCZ(h->direct_table, 32*big_mb_num * sizeof(uint8_t));

    }



    memset(h->slice_table_base, -1, (big_mb_num+s->mb_stride)  * sizeof(uint8_t));

    h->slice_table= h->slice_table_base + s->mb_stride*2 + 1;



    CHECKED_ALLOCZ(h->mb2b_xy  , big_mb_num * sizeof(uint32_t));

    CHECKED_ALLOCZ(h->mb2b8_xy , big_mb_num * sizeof(uint32_t));

    for(y=0; y<s->mb_height; y++){

        for(x=0; x<s->mb_width; x++){

            const int mb_xy= x + y*s->mb_stride;

            const int b_xy = 4*x + 4*y*h->b_stride;

            const int b8_xy= 2*x + 2*y*h->b8_stride;



            h->mb2b_xy [mb_xy]= b_xy;

            h->mb2b8_xy[mb_xy]= b8_xy;

        }

    }



    s->obmc_scratchpad = NULL;



    if(!h->dequant4_coeff[0])

        init_dequant_tables(h);



    return 0;

fail:

    free_tables(h);

    return -1;

}

static void RENAME(swScale)(SwsContext *c, uint8_t* srcParam[], int srcStrideParam[], int srcSliceY,

             int srcSliceH, uint8_t* dstParam[], int dstStrideParam[]){



	/* load a few things into local vars to make the code more readable? and faster */

	const int srcW= c->srcW;

	const int dstW= c->dstW;

	const int dstH= c->dstH;

	const int chrDstW= c->chrDstW;

	const int lumXInc= c->lumXInc;

	const int chrXInc= c->chrXInc;

	const int dstFormat= c->dstFormat;

	const int flags= c->flags;

	const int canMMX2BeUsed= c->canMMX2BeUsed;

	int16_t *vLumFilterPos= c->vLumFilterPos;

	int16_t *vChrFilterPos= c->vChrFilterPos;

	int16_t *hLumFilterPos= c->hLumFilterPos;

	int16_t *hChrFilterPos= c->hChrFilterPos;

	int16_t *vLumFilter= c->vLumFilter;

	int16_t *vChrFilter= c->vChrFilter;

	int16_t *hLumFilter= c->hLumFilter;

	int16_t *hChrFilter= c->hChrFilter;

	int16_t *lumMmxFilter= c->lumMmxFilter;

	int16_t *chrMmxFilter= c->chrMmxFilter;

	const int vLumFilterSize= c->vLumFilterSize;

	const int vChrFilterSize= c->vChrFilterSize;

	const int hLumFilterSize= c->hLumFilterSize;

	const int hChrFilterSize= c->hChrFilterSize;

	int16_t **lumPixBuf= c->lumPixBuf;

	int16_t **chrPixBuf= c->chrPixBuf;

	const int vLumBufSize= c->vLumBufSize;

	const int vChrBufSize= c->vChrBufSize;

	uint8_t *funnyYCode= c->funnyYCode;

	uint8_t *funnyUVCode= c->funnyUVCode;

	uint8_t *formatConvBuffer= c->formatConvBuffer;



	/* vars whch will change and which we need to storw back in the context */

	int dstY= c->dstY;

	int lumBufIndex= c->lumBufIndex;

	int chrBufIndex= c->chrBufIndex;

	int lastInLumBuf= c->lastInLumBuf;

	int lastInChrBuf= c->lastInChrBuf;

	int srcStride[3];

	int dstStride[3];

	uint8_t *src[3];

	uint8_t *dst[3];



	if(c->srcFormat == IMGFMT_I420){

		src[0]= srcParam[0];

		src[1]= srcParam[2];

		src[2]= srcParam[1];

		srcStride[0]= srcStrideParam[0];

		srcStride[1]= srcStrideParam[2];

		srcStride[2]= srcStrideParam[1];

	}

	else if(c->srcFormat==IMGFMT_YV12){

		src[0]= srcParam[0];

		src[1]= srcParam[1];

		src[2]= srcParam[2];

		srcStride[0]= srcStrideParam[0];

		srcStride[1]= srcStrideParam[1];

		srcStride[2]= srcStrideParam[2];

	}

	else if(isPacked(c->srcFormat)){

		src[0]=

		src[1]=

		src[2]= srcParam[0];

		srcStride[0]= srcStrideParam[0];

		srcStride[1]=

		srcStride[2]= srcStrideParam[0]<<1;

	}

	else if(isGray(c->srcFormat)){

		src[0]= srcParam[0];

		src[1]=

		src[2]= NULL;

		srcStride[0]= srcStrideParam[0];

		srcStride[1]=

		srcStride[2]= 0;

	}



	if(dstFormat == IMGFMT_I420){

		dst[0]= dstParam[0];

		dst[1]= dstParam[2];

		dst[2]= dstParam[1];

		dstStride[0]= dstStrideParam[0];

		dstStride[1]= dstStrideParam[2];

		dstStride[2]= dstStrideParam[1];

	}else{

		dst[0]= dstParam[0];

		dst[1]= dstParam[1];

		dst[2]= dstParam[2];

		dstStride[0]= dstStrideParam[0];

