static av_cold int ac3_encode_init(AVCodecContext *avctx)

{

    int freq = avctx->sample_rate;

    int bitrate = avctx->bit_rate;

    AC3EncodeContext *s = avctx->priv_data;

    int i, j, ch;

    int bw_code;



    avctx->frame_size = AC3_FRAME_SIZE;



    ac3_common_init();



    if (!avctx->channel_layout) {

        av_log(avctx, AV_LOG_WARNING, "No channel layout specified. The "

                                      "encoder will guess the layout, but it "

                                      "might be incorrect.\n");

    }

    if (set_channel_info(s, avctx->channels, &avctx->channel_layout)) {

        av_log(avctx, AV_LOG_ERROR, "invalid channel layout\n");

        return -1;

    }



    /* frequency */

    for (i = 0; i < 3; i++) {

        for (j = 0; j < 3; j++)

            if ((ff_ac3_sample_rate_tab[j] >> i) == freq)

                goto found;

    }

    return -1;

 found:

    s->sample_rate        = freq;

    s->bit_alloc.sr_shift = i;

    s->bit_alloc.sr_code  = j;

    s->bitstream_id       = 8 + s->bit_alloc.sr_shift;

    s->bitstream_mode     = 0; /* complete main audio service */



    /* bitrate & frame size */

    for (i = 0; i < 19; i++) {

        if ((ff_ac3_bitrate_tab[i] >> s->bit_alloc.sr_shift)*1000 == bitrate)

            break;

    }

    if (i == 19)

        return -1;

    s->bit_rate        = bitrate;

    s->frame_size_code = i << 1;

    s->frame_size_min  = 2 * ff_ac3_frame_size_tab[s->frame_size_code][s->bit_alloc.sr_code];

    s->bits_written    = 0;

    s->samples_written = 0;

    s->frame_size      = s->frame_size_min;



    /* set bandwidth */

    if (avctx->cutoff) {

        /* calculate bandwidth based on user-specified cutoff frequency */

        int cutoff     = av_clip(avctx->cutoff, 1, s->sample_rate >> 1);

        int fbw_coeffs = cutoff * 2 * AC3_MAX_COEFS / s->sample_rate;

        bw_code        = av_clip((fbw_coeffs - 73) / 3, 0, 60);

    } else {

        /* use default bandwidth setting */

        /* XXX: should compute the bandwidth according to the frame

           size, so that we avoid annoying high frequency artifacts */

        bw_code = 50;

    }

    for (ch = 0; ch < s->fbw_channels; ch++) {

        /* bandwidth for each channel */

        s->bandwidth_code[ch] = bw_code;

        s->nb_coefs[ch]       = bw_code * 3 + 73;

    }

    if (s->lfe_on)

        s->nb_coefs[s->lfe_channel] = 7; /* LFE channel always has 7 coefs */



    /* initial snr offset */

    s->coarse_snr_offset = 40;



    mdct_init(9);



    avctx->coded_frame= avcodec_alloc_frame();

    avctx->coded_frame->key_frame= 1;



    return 0;

}

static void gen_connect(URLContext *s, RTMPContext *rt)

{

    RTMPPacket pkt;

    uint8_t ver[64], *p;



    ff_rtmp_packet_create(&pkt, RTMP_SYSTEM_CHANNEL, RTMP_PT_INVOKE, 0, 4096);

    p = pkt.data;



    ff_amf_write_string(&p, "connect");

    ff_amf_write_number(&p, ++rt->nb_invokes);

    ff_amf_write_object_start(&p);

    ff_amf_write_field_name(&p, "app");

    ff_amf_write_string(&p, rt->app);



    if (rt->is_input) {

        snprintf(ver, sizeof(ver), "%s %d,%d,%d,%d", RTMP_CLIENT_PLATFORM, RTMP_CLIENT_VER1,

                 RTMP_CLIENT_VER2, RTMP_CLIENT_VER3, RTMP_CLIENT_VER4);

    } else {

        snprintf(ver, sizeof(ver), "FMLE/3.0 (compatible; %s)", LIBAVFORMAT_IDENT);

        ff_amf_write_field_name(&p, "type");

        ff_amf_write_string(&p, "nonprivate");

    }

    ff_amf_write_field_name(&p, "flashVer");

    ff_amf_write_string(&p, ver);

    ff_amf_write_field_name(&p, "tcUrl");

    ff_amf_write_string(&p, rt->tcurl);

    if (rt->is_input) {

        ff_amf_write_field_name(&p, "fpad");

        ff_amf_write_bool(&p, 0);

        ff_amf_write_field_name(&p, "capabilities");

        ff_amf_write_number(&p, 15.0);



        /* Tell the server we support all the audio codecs except

         * SUPPORT_SND_INTEL (0x0008) and SUPPORT_SND_UNUSED (0x0010)

         * which are unused in the RTMP protocol implementation. */

        ff_amf_write_field_name(&p, "audioCodecs");

        ff_amf_write_number(&p, 4071.0);

        ff_amf_write_field_name(&p, "videoCodecs");

        ff_amf_write_number(&p, 252.0);

        ff_amf_write_field_name(&p, "videoFunction");

        ff_amf_write_number(&p, 1.0);

    }

    ff_amf_write_object_end(&p);



    pkt.data_size = p - pkt.data;



    ff_rtmp_packet_write(rt->stream, &pkt, rt->chunk_size, rt->prev_pkt[1]);

    ff_rtmp_packet_destroy(&pkt);

}

static int wrapped_avframe_encode(AVCodecContext *avctx, AVPacket *pkt,

                     const AVFrame *frame, int *got_packet)

{

    AVFrame *wrapped = av_frame_clone(frame);



    if (!wrapped)

        return AVERROR(ENOMEM);



    pkt->buf = av_buffer_create((uint8_t *)wrapped, sizeof(*wrapped),

                                wrapped_avframe_release_buffer, NULL,

                                AV_BUFFER_FLAG_READONLY);

    if (!pkt->buf) {

        av_frame_free(&wrapped);

        return AVERROR(ENOMEM);

    }



    pkt->data = (uint8_t *)wrapped;

    pkt->size = sizeof(*wrapped);



    pkt->flags |= AV_PKT_FLAG_KEY;

    *got_packet = 1;

    return 0;

}

int MPV_encode_init(AVCodecContext *avctx)

{

    MpegEncContext *s = avctx->priv_data;

    int i;



    avctx->pix_fmt = PIX_FMT_YUV420P;



    s->bit_rate = avctx->bit_rate;

    s->bit_rate_tolerance = avctx->bit_rate_tolerance;

    s->frame_rate = avctx->frame_rate;

    s->width = avctx->width;

    s->height = avctx->height;

    s->gop_size = avctx->gop_size;

    s->rtp_mode = avctx->rtp_mode;

    s->rtp_payload_size = avctx->rtp_payload_size;

    if (avctx->rtp_callback)

        s->rtp_callback = avctx->rtp_callback;

    s->qmin= avctx->qmin;

    s->qmax= avctx->qmax;

    s->max_qdiff= avctx->max_qdiff;

    s->qcompress= avctx->qcompress;

    s->qblur= avctx->qblur;

    s->b_quant_factor= avctx->b_quant_factor;

    s->avctx = avctx;

    s->aspect_ratio_info= avctx->aspect_ratio_info;

    s->flags= avctx->flags;

    s->max_b_frames= avctx->max_b_frames;

    s->rc_strategy= avctx->rc_strategy;

    s->b_frame_strategy= avctx->b_frame_strategy;

    s->codec_id= avctx->codec->id;



    if (s->gop_size <= 1) {

        s->intra_only = 1;

        s->gop_size = 12;

    } else {

        s->intra_only = 0;

    }



    /* ME algorithm */

    if (avctx->me_method == 0)

        /* For compatibility */

        s->me_method = motion_estimation_method;

    else

        s->me_method = avctx->me_method;



    /* Fixed QSCALE */

    s->fixed_qscale = (avctx->flags & CODEC_FLAG_QSCALE);



    switch(avctx->codec->id) {

    case CODEC_ID_MPEG1VIDEO:

        s->out_format = FMT_MPEG1;

        avctx->delay=0; //FIXME not sure, should check the spec

        break;

    case CODEC_ID_MJPEG:

        s->out_format = FMT_MJPEG;

        s->intra_only = 1; /* force intra only for jpeg */

        s->mjpeg_write_tables = 1; /* write all tables */

	s->mjpeg_data_only_frames = 0; /* write all the needed headers */

        s->mjpeg_vsample[0] = 2; /* set up default sampling factors */

        s->mjpeg_vsample[1] = 1; /* the only currently supported values */

        s->mjpeg_vsample[2] = 1; 

        s->mjpeg_hsample[0] = 2;

        s->mjpeg_hsample[1] = 1; 

        s->mjpeg_hsample[2] = 1; 

        if (mjpeg_init(s) < 0)

            return -1;

        avctx->delay=0;

        break;

    case CODEC_ID_H263:

        if (h263_get_picture_format(s->width, s->height) == 7) {

            printf("Input picture size isn't suitable for h263 codec! try h263+\n");

            return -1;

        }

        s->out_format = FMT_H263;

        avctx->delay=0;

        break;

    case CODEC_ID_H263P:

        s->out_format = FMT_H263;

        s->rtp_mode = 1;

        s->rtp_payload_size = 1200; 

        s->h263_plus = 1;

        s->unrestricted_mv = 1;

        s->h263_aic = 1;



        /* These are just to be sure */

        s->umvplus = 0;

        s->umvplus_dec = 0;

        avctx->delay=0;

        break;

    case CODEC_ID_RV10:

        s->out_format = FMT_H263;

        s->h263_rv10 = 1;

        avctx->delay=0;

        break;

    case CODEC_ID_MPEG4:

        s->out_format = FMT_H263;

        s->h263_pred = 1;

        s->unrestricted_mv = 1;

        s->has_b_frames= s->max_b_frames ? 1 : 0;

        s->low_delay=0;

        avctx->delay= s->low_delay ? 0 : (s->max_b_frames + 1); 

        break;

    case CODEC_ID_MSMPEG4V1:

        s->out_format = FMT_H263;

        s->h263_msmpeg4 = 1;

        s->h263_pred = 1;

        s->unrestricted_mv = 1;

        s->msmpeg4_version= 1;

        avctx->delay=0;

        break;

    case CODEC_ID_MSMPEG4V2:

        s->out_format = FMT_H263;

        s->h263_msmpeg4 = 1;

        s->h263_pred = 1;

        s->unrestricted_mv = 1;

        s->msmpeg4_version= 2;

        avctx->delay=0;

        break;

    case CODEC_ID_MSMPEG4V3:

        s->out_format = FMT_H263;

        s->h263_msmpeg4 = 1;

        s->h263_pred = 1;

        s->unrestricted_mv = 1;

        s->msmpeg4_version= 3;

        avctx->delay=0;

        break;

    default:

        return -1;

    }



    if((s->flags&CODEC_FLAG_4MV) && !(s->flags&CODEC_FLAG_HQ)){

        printf("4MV is currently only supported in HQ mode\n");

        return -1;

    }



    { /* set up some save defaults, some codecs might override them later */

        static int done=0;

        if(!done){

            int i;

            done=1;

            memset(default_mv_penalty, 0, sizeof(UINT16)*(MAX_FCODE+1)*(2*MAX_MV+1));

            memset(default_fcode_tab , 0, sizeof(UINT8)*(2*MAX_MV+1));



            for(i=-16; i<16; i++){

                default_fcode_tab[i + MAX_MV]= 1;

            }

        }

    }

    s->mv_penalty= default_mv_penalty;

    s->fcode_tab= default_fcode_tab;



    if (s->out_format == FMT_H263)

        h263_encode_init(s);

    else if (s->out_format == FMT_MPEG1)

        mpeg1_encode_init(s);



    /* dont use mv_penalty table for crap MV as it would be confused */

    if (s->me_method < ME_EPZS) s->mv_penalty = default_mv_penalty;



    s->encoding = 1;



    /* init */

    if (MPV_common_init(s) < 0)

        return -1;



    /* init default q matrix */

    for(i=0;i<64;i++) {

        if(s->out_format == FMT_H263)

            s->intra_matrix[i] = default_non_intra_matrix[i];

        else

            s->intra_matrix[i] = default_intra_matrix[i];



        s->inter_matrix[i] = default_non_intra_matrix[i];

    }



    /* precompute matrix */

    /* for mjpeg, we do include qscale in the matrix */

    if (s->out_format != FMT_MJPEG) {

        convert_matrix(s->q_intra_matrix, s->q_intra_matrix16, s->q_intra_matrix16_bias, 

                       s->intra_matrix, s->intra_quant_bias);

        convert_matrix(s->q_inter_matrix, s->q_inter_matrix16, s->q_inter_matrix16_bias, 

                       s->inter_matrix, s->inter_quant_bias);

    }



    if(ff_rate_control_init(s) < 0)

        return -1;



    s->picture_number = 0;

    s->picture_in_gop_number = 0;

    s->fake_picture_number = 0;

    /* motion detector init */

    s->f_code = 1;

    s->b_code = 1;



    return 0;

}

static void inline xan_wc3_output_pixel_run(XanContext *s, 

    unsigned char *pixel_buffer, int x, int y, int pixel_count)

{

    int stride;

    int line_inc;

    int index;

    int current_x;

    int width = s->avctx->width;

    unsigned char pix;

    unsigned char *palette_plane;

    unsigned char *y_plane;

    unsigned char *u_plane;

    unsigned char *v_plane;

    unsigned char *rgb_plane;

    unsigned short *rgb16_plane;

    unsigned short *palette16;

    unsigned int *rgb32_plane;

    unsigned int *palette32;



    switch (s->avctx->pix_fmt) {



    case PIX_FMT_PAL8:

        palette_plane = s->current_frame.data[0];

        stride = s->current_frame.linesize[0];

        line_inc = stride - width;

        index = y * stride + x;

        current_x = x;

        while(pixel_count--) {



            /* don't do a memcpy() here; keyframes generally copy an entire

             * frame of data and the stride needs to be accounted for */

            palette_plane[index++] = *pixel_buffer++;



            ADVANCE_CURRENT_X();

        }

        break;



    case PIX_FMT_RGB555:

    case PIX_FMT_RGB565:

        rgb16_plane = (unsigned short *)s->current_frame.data[0];

        palette16 = (unsigned short *)s->palette;

        stride = s->current_frame.linesize[0] / 2;

        line_inc = stride - width;

        index = y * stride + x;

        current_x = x;

        while(pixel_count--) {



            rgb16_plane[index++] = palette16[*pixel_buffer++];



            ADVANCE_CURRENT_X();

        }

        break;



    case PIX_FMT_RGB24:

    case PIX_FMT_BGR24:

        rgb_plane = s->current_frame.data[0];

        stride = s->current_frame.linesize[0];

        line_inc = stride - width * 3;

        index = y * stride + x * 3;

        current_x = x;

        while(pixel_count--) {

            pix = *pixel_buffer++;



            rgb_plane[index++] = s->palette[pix * 4 + 0];

            rgb_plane[index++] = s->palette[pix * 4 + 1];

            rgb_plane[index++] = s->palette[pix * 4 + 2];



            ADVANCE_CURRENT_X();

        }

        break;



    case PIX_FMT_RGBA32:

        rgb32_plane = (unsigned int *)s->current_frame.data[0];

        palette32 = (unsigned int *)s->palette;

        stride = s->current_frame.linesize[0] / 4;

        line_inc = stride - width;

        index = y * stride + x;

        current_x = x;

        while(pixel_count--) {



            rgb32_plane[index++] = palette32[*pixel_buffer++];



            ADVANCE_CURRENT_X();

        }

        break;



    case PIX_FMT_YUV444P:

        y_plane = s->current_frame.data[0];

        u_plane = s->current_frame.data[1];

        v_plane = s->current_frame.data[2];

        stride = s->current_frame.linesize[0];

        line_inc = stride - width;

        index = y * stride + x;

        current_x = x;

        while(pixel_count--) {

            pix = *pixel_buffer++;



            y_plane[index] = s->palette[pix * 4 + 0];

            u_plane[index] = s->palette[pix * 4 + 1];

            v_plane[index] = s->palette[pix * 4 + 2];



            index++;

            ADVANCE_CURRENT_X();

        }

        break;



    default:

        av_log(s->avctx, AV_LOG_ERROR, " Xan WC3: Unhandled colorspace\n");

        break;

    }

}

static int mov_read_hdlr(MOVContext *c, ByteIOContext *pb, MOVAtom atom)

{

    AVStream *st = c->fc->streams[c->fc->nb_streams-1];

    uint32_t type;

    uint32_t ctype;



    get_byte(pb); /* version */

    get_be24(pb); /* flags */



    /* component type */

    ctype = get_le32(pb);

    type = get_le32(pb); /* component subtype */



    dprintf(c->fc, "ctype= %c%c%c%c (0x%08x)\n", *((char *)&ctype), ((char *)&ctype)[1],

            ((char *)&ctype)[2], ((char *)&ctype)[3], (int) ctype);

    dprintf(c->fc, "stype= %c%c%c%c\n",

            *((char *)&type), ((char *)&type)[1], ((char *)&type)[2], ((char *)&type)[3]);

    if(!ctype)

        c->isom = 1;

    if     (type == MKTAG('v','i','d','e'))

        st->codec->codec_type = CODEC_TYPE_VIDEO;

    else if(type == MKTAG('s','o','u','n'))

        st->codec->codec_type = CODEC_TYPE_AUDIO;

    else if(type == MKTAG('m','1','a',' '))

        st->codec->codec_id = CODEC_ID_MP2;

    else if(type == MKTAG('s','u','b','p')) {

        st->codec->codec_type = CODEC_TYPE_SUBTITLE;

    }

    get_be32(pb); /* component  manufacture */

    get_be32(pb); /* component flags */

    get_be32(pb); /* component flags mask */



    if(atom.size <= 24)

        return 0; /* nothing left to read */



    url_fskip(pb, atom.size - (url_ftell(pb) - atom.offset));

    return 0;

}

static int mxf_read_cryptographic_context(MXFCryptoContext *cryptocontext, ByteIOContext *pb, int tag, int size, UID uid)

{

