        if (len < 0) {

#ifdef DEBUG_SEEK

            printf("none (ret=%d)\n", len);

#endif

            return AV_NOPTS_VALUE;

        }

        if (startcode == s->streams[stream_index]->id &&

            dts != AV_NOPTS_VALUE) {

            break;

        }

        url_fskip(s->pb, len);

    }

#ifdef DEBUG_SEEK

    printf("pos=0x%"PRIx64" dts=0x%"PRIx64" %0.3f\n", pos, dts, dts / 90000.0);

#endif

    *ppos = pos;

    return dts;

}

static int libssh_open(URLContext *h, const char *url, int flags)

{

    static const int verbosity = SSH_LOG_NOLOG;

    LIBSSHContext *s = h->priv_data;

    char proto[10], path[MAX_URL_SIZE], hostname[1024], credencials[1024];

    int port = 22, access, ret;

    long timeout = s->rw_timeout * 1000;

    const char *user = NULL, *pass = NULL;

    char *end = NULL;

    sftp_attributes stat;



    av_url_split(proto, sizeof(proto),

                 credencials, sizeof(credencials),

                 hostname, sizeof(hostname),

                 &port,

                 path, sizeof(path),

                 url);



    if (port <= 0 || port > 65535)

        port = 22;



    if (!(s->session = ssh_new())) {

        ret = AVERROR(ENOMEM);

        goto fail;

    }

    user = av_strtok(credencials, ":", &end);

    pass = av_strtok(end, ":", &end);

    ssh_options_set(s->session, SSH_OPTIONS_HOST, hostname);

    ssh_options_set(s->session, SSH_OPTIONS_PORT, &port);

    ssh_options_set(s->session, SSH_OPTIONS_LOG_VERBOSITY, &verbosity);

    if (timeout > 0)

        ssh_options_set(s->session, SSH_OPTIONS_TIMEOUT_USEC, &timeout);

    if (user)

        ssh_options_set(s->session, SSH_OPTIONS_USER, user);



    if (ssh_connect(s->session) != SSH_OK) {

        av_log(h, AV_LOG_ERROR, "Connection failed. %s\n", ssh_get_error(s->session));

        ret = AVERROR(EIO);

        goto fail;

    }



    if (pass && ssh_userauth_password(s->session, NULL, pass) != SSH_AUTH_SUCCESS) {

        av_log(h, AV_LOG_ERROR, "Error authenticating with password: %s\n", ssh_get_error(s->session));

        ret = AVERROR(EACCES);

        goto fail;

    }



    if (!(s->sftp = sftp_new(s->session))) {

        av_log(h, AV_LOG_ERROR, "SFTP session creation failed: %s\n", ssh_get_error(s->session));

        ret = AVERROR(ENOMEM);

        goto fail;

    }



    if (sftp_init(s->sftp) != SSH_OK) {

        av_log(h, AV_LOG_ERROR, "Error initializing sftp session: %s\n", ssh_get_error(s->session));

        ret = AVERROR(EIO);

        goto fail;

    }



    if ((flags & AVIO_FLAG_WRITE) && (flags & AVIO_FLAG_READ)) {

        access = O_CREAT | O_RDWR;

        if (s->trunc)

            access |= O_TRUNC;

    } else if (flags & AVIO_FLAG_WRITE) {

        access = O_CREAT | O_WRONLY;

        if (s->trunc)

            access |= O_TRUNC;

    } else {

        access = O_RDONLY;

    }



    /* 0666 = -rw-rw-rw- = read+write for everyone, minus umask */

    if (!(s->file = sftp_open(s->sftp, path, access, 0666))) {

        av_log(h, AV_LOG_ERROR, "Error opening sftp file: %s\n", ssh_get_error(s->session));

        ret = AVERROR(EIO);

        goto fail;

    }



    if (!(stat = sftp_fstat(s->file))) {

        av_log(h, AV_LOG_WARNING, "Cannot stat remote file %s.\n", path);

        s->filesize = -1;

    } else {

        s->filesize = stat->size;

        sftp_attributes_free(stat);

    }



    return 0;



  fail:

    libssh_close(h);

    return ret;

}

static int hevc_init(AVCodecParserContext *s)

{

    HEVCContext  *h  = &((HEVCParseContext *)s->priv_data)->h;

    h->HEVClc = av_mallocz(sizeof(HEVCLocalContext));



    h->skipped_bytes_pos_size = INT_MAX;



    return 0;

}

matroska_probe (AVProbeData *p)

{

    uint64_t total = 0;

    int len_mask = 0x80, size = 1, n = 1;

    uint8_t probe_data[] = { 'm', 'a', 't', 'r', 'o', 's', 'k', 'a' };



    if (p->buf_size < 5)

        return 0;



    /* ebml header? */

    if ((p->buf[0] << 24 | p->buf[1] << 16 |

         p->buf[2] << 8 | p->buf[3]) != EBML_ID_HEADER)

        return 0;



    /* length of header */

    total = p->buf[4];

    while (size <= 8 && !(total & len_mask)) {

        size++;

        len_mask >>= 1;

    }

    if (size > 8)

      return 0;

    total &= (len_mask - 1);

    while (n < size)

        total = (total << 8) | p->buf[4 + n++];



    /* does the probe data contain the whole header? */

    if (p->buf_size < 4 + size + total)

      return 0;



    /* the header must contain the document type 'matroska'. For now,

     * we don't parse the whole header but simply check for the

     * availability of that array of characters inside the header.

     * Not fully fool-proof, but good enough. */

    for (n = 4 + size; n < 4 + size + total - sizeof(probe_data); n++)

        if (!memcmp (&p->buf[n], probe_data, sizeof(probe_data)))

            return AVPROBE_SCORE_MAX;



    return 0;

}

static void FUNCC(pred16x16_vertical)(uint8_t *_src, int _stride){

    int i;

    pixel *src = (pixel*)_src;

    int stride = _stride/sizeof(pixel);

    const pixel4 a = ((pixel4*)(src-stride))[0];

    const pixel4 b = ((pixel4*)(src-stride))[1];

    const pixel4 c = ((pixel4*)(src-stride))[2];

    const pixel4 d = ((pixel4*)(src-stride))[3];



    for(i=0; i<16; i++){

        ((pixel4*)(src+i*stride))[0] = a;

        ((pixel4*)(src+i*stride))[1] = b;

        ((pixel4*)(src+i*stride))[2] = c;

        ((pixel4*)(src+i*stride))[3] = d;

    }

}

static void rgb24_to_pal8(AVPicture *dst, AVPicture *src,

                          int width, int height)

{

    const unsigned char *p;

    unsigned char *q;

    int r, g, b, dst_wrap, src_wrap;

    int x, y, i;

    static const uint8_t pal_value[6] = { 0x00, 0x33, 0x66, 0x99, 0xcc, 0xff };

    uint32_t *pal;



    p = src->data[0];

    src_wrap = src->linesize[0] - 3 * width;



    q = dst->data[0];

    dst_wrap = dst->linesize[0] - width;



    for(y=0;y<height;y++) {

        for(x=0;x<width;x++) {

            r = p[0];

            g = p[1];

            b = p[2];



            q[0] = gif_clut_index(r, g, b);

            q++;

            p += 3;

        }

        p += src_wrap;

        q += dst_wrap;

    }



    /* build palette */

    pal = (uint32_t *)dst->data[1];

    i = 0;

    for(r = 0; r < 6; r++) {

        for(g = 0; g < 6; g++) {

            for(b = 0; b < 6; b++) {

                pal[i++] = (0xff << 24) | (pal_value[r] << 16) | 

                    (pal_value[g] << 8) | pal_value[b];

            }

        }

    }

    while (i < 256)

        pal[i++] = 0;

}

int ff_h264_decode_mb_cabac(const H264Context *h, H264SliceContext *sl)

{

    int mb_xy;

    int mb_type, partition_count, cbp = 0;

    int dct8x8_allowed= h->pps.transform_8x8_mode;

    int decode_chroma = h->sps.chroma_format_idc == 1 || h->sps.chroma_format_idc == 2;

    const int pixel_shift = h->pixel_shift;



    mb_xy = sl->mb_xy = sl->mb_x + sl->mb_y*h->mb_stride;



    ff_tlog(h->avctx, "pic:%d mb:%d/%d\n", h->frame_num, sl->mb_x, sl->mb_y);

    if (sl->slice_type_nos != AV_PICTURE_TYPE_I) {

        int skip;

        /* a skipped mb needs the aff flag from the following mb */

        if (FRAME_MBAFF(h) && (sl->mb_y & 1) == 1 && sl->prev_mb_skipped)

            skip = sl->next_mb_skipped;

        else

            skip = decode_cabac_mb_skip(h, sl, sl->mb_x, sl->mb_y );

        /* read skip flags */

        if( skip ) {

            if (FRAME_MBAFF(h) && (sl->mb_y & 1) == 0) {

                h->cur_pic.mb_type[mb_xy] = MB_TYPE_SKIP;

                sl->next_mb_skipped = decode_cabac_mb_skip(h, sl, sl->mb_x, sl->mb_y+1 );

                if(!sl->next_mb_skipped)

                    sl->mb_mbaff = sl->mb_field_decoding_flag = decode_cabac_field_decoding_flag(h, sl);

            }



            decode_mb_skip(h, sl);



            h->cbp_table[mb_xy] = 0;

            h->chroma_pred_mode_table[mb_xy] = 0;

            sl->last_qscale_diff = 0;



            return 0;



        }

    }

    if (FRAME_MBAFF(h)) {

        if ((sl->mb_y & 1) == 0)

            sl->mb_mbaff =

            sl->mb_field_decoding_flag = decode_cabac_field_decoding_flag(h, sl);

    }



    sl->prev_mb_skipped = 0;



    fill_decode_neighbors(h, sl, -(MB_FIELD(sl)));



    if (sl->slice_type_nos == AV_PICTURE_TYPE_B) {

        int ctx = 0;

        av_assert2(sl->slice_type_nos == AV_PICTURE_TYPE_B);



        if (!IS_DIRECT(sl->left_type[LTOP] - 1))

            ctx++;

        if (!IS_DIRECT(sl->top_type - 1))

            ctx++;



        if( !get_cabac_noinline( &sl->cabac, &sl->cabac_state[27+ctx] ) ){

            mb_type= 0; /* B_Direct_16x16 */

        }else if( !get_cabac_noinline( &sl->cabac, &sl->cabac_state[27+3] ) ) {

            mb_type= 1 + get_cabac_noinline( &sl->cabac, &sl->cabac_state[27+5] ); /* B_L[01]_16x16 */

        }else{

            int bits;

            bits = get_cabac_noinline( &sl->cabac, &sl->cabac_state[27+4] ) << 3;

            bits+= get_cabac_noinline( &sl->cabac, &sl->cabac_state[27+5] ) << 2;

            bits+= get_cabac_noinline( &sl->cabac, &sl->cabac_state[27+5] ) << 1;

            bits+= get_cabac_noinline( &sl->cabac, &sl->cabac_state[27+5] );

            if( bits < 8 ){

                mb_type= bits + 3; /* B_Bi_16x16 through B_L1_L0_16x8 */

            }else if( bits == 13 ){

                mb_type = decode_cabac_intra_mb_type(sl, 32, 0);

                goto decode_intra_mb;

            }else if( bits == 14 ){

                mb_type= 11; /* B_L1_L0_8x16 */

            }else if( bits == 15 ){

                mb_type= 22; /* B_8x8 */

            }else{

                bits= ( bits<<1 ) + get_cabac_noinline( &sl->cabac, &sl->cabac_state[27+5] );

                mb_type= bits - 4; /* B_L0_Bi_* through B_Bi_Bi_* */

            }

        }

            partition_count= b_mb_type_info[mb_type].partition_count;

            mb_type=         b_mb_type_info[mb_type].type;

    } else if (sl->slice_type_nos == AV_PICTURE_TYPE_P) {

        if( get_cabac_noinline( &sl->cabac, &sl->cabac_state[14] ) == 0 ) {

            /* P-type */

            if( get_cabac_noinline( &sl->cabac, &sl->cabac_state[15] ) == 0 ) {

                /* P_L0_D16x16, P_8x8 */

                mb_type= 3 * get_cabac_noinline( &sl->cabac, &sl->cabac_state[16] );

            } else {

                /* P_L0_D8x16, P_L0_D16x8 */

                mb_type= 2 - get_cabac_noinline( &sl->cabac, &sl->cabac_state[17] );

            }

            partition_count= p_mb_type_info[mb_type].partition_count;

            mb_type=         p_mb_type_info[mb_type].type;

        } else {

            mb_type = decode_cabac_intra_mb_type(sl, 17, 0);

            goto decode_intra_mb;

        }

    } else {

        mb_type = decode_cabac_intra_mb_type(sl, 3, 1);

        if (sl->slice_type == AV_PICTURE_TYPE_SI && mb_type)

            mb_type--;

        av_assert2(sl->slice_type_nos == AV_PICTURE_TYPE_I);

decode_intra_mb:

        partition_count = 0;

        cbp= i_mb_type_info[mb_type].cbp;

        sl->intra16x16_pred_mode = i_mb_type_info[mb_type].pred_mode;

        mb_type= i_mb_type_info[mb_type].type;

    }

    if (MB_FIELD(sl))

        mb_type |= MB_TYPE_INTERLACED;



    h->slice_table[mb_xy] = sl->slice_num;



    if(IS_INTRA_PCM(mb_type)) {

        const int mb_size = ff_h264_mb_sizes[h->sps.chroma_format_idc] *

                            h->sps.bit_depth_luma >> 3;

        const uint8_t *ptr;



        // We assume these blocks are very rare so we do not optimize it.

        // FIXME The two following lines get the bitstream position in the cabac

        // decode, I think it should be done by a function in cabac.h (or cabac.c).

        ptr= sl->cabac.bytestream;

        if(sl->cabac.low&0x1) ptr--;

        if(CABAC_BITS==16){

            if(sl->cabac.low&0x1FF) ptr--;

        }



        // The pixels are stored in the same order as levels in h->mb array.

        if ((int) (sl->cabac.bytestream_end - ptr) < mb_size)

            return -1;

        sl->intra_pcm_ptr = ptr;

        ptr += mb_size;



        ff_init_cabac_decoder(&sl->cabac, ptr, sl->cabac.bytestream_end - ptr);



        // All blocks are present

        h->cbp_table[mb_xy] = 0xf7ef;

        h->chroma_pred_mode_table[mb_xy] = 0;

        // In deblocking, the quantizer is 0

        h->cur_pic.qscale_table[mb_xy] = 0;

        // All coeffs are present

        memset(h->non_zero_count[mb_xy], 16, 48);

        h->cur_pic.mb_type[mb_xy] = mb_type;

        sl->last_qscale_diff = 0;

        return 0;

    }



    fill_decode_caches(h, sl, mb_type);



    if( IS_INTRA( mb_type ) ) {

        int i, pred_mode;

        if( IS_INTRA4x4( mb_type ) ) {

            if (dct8x8_allowed && get_cabac_noinline(&sl->cabac, &sl->cabac_state[399 + sl->neighbor_transform_size])) {

                mb_type |= MB_TYPE_8x8DCT;

                for( i = 0; i < 16; i+=4 ) {

                    int pred = pred_intra_mode(h, sl, i);

                    int mode = decode_cabac_mb_intra4x4_pred_mode(sl, pred);

                    fill_rectangle(&sl->intra4x4_pred_mode_cache[scan8[i]], 2, 2, 8, mode, 1);

                }

            } else {

                for( i = 0; i < 16; i++ ) {

                    int pred = pred_intra_mode(h, sl, i);

                    sl->intra4x4_pred_mode_cache[scan8[i]] = decode_cabac_mb_intra4x4_pred_mode(sl, pred);



                    ff_tlog(h->avctx, "i4x4 pred=%d mode=%d\n", pred,

                            sl->intra4x4_pred_mode_cache[scan8[i]]);

                }

            }

            write_back_intra_pred_mode(h, sl);

            if (ff_h264_check_intra4x4_pred_mode(h, sl) < 0 ) return -1;

        } else {

            sl->intra16x16_pred_mode = ff_h264_check_intra_pred_mode(h, sl, sl->intra16x16_pred_mode, 0);

            if (sl->intra16x16_pred_mode < 0) return -1;

        }

        if(decode_chroma){

            h->chroma_pred_mode_table[mb_xy] =

            pred_mode                        = decode_cabac_mb_chroma_pre_mode(h, sl);



            pred_mode= ff_h264_check_intra_pred_mode(h, sl, pred_mode, 1 );

            if( pred_mode < 0 ) return -1;

            sl->chroma_pred_mode = pred_mode;

        } else {

            sl->chroma_pred_mode = DC_128_PRED8x8;

        }

    } else if( partition_count == 4 ) {

        int i, j, sub_partition_count[4], list, ref[2][4];



        if (sl->slice_type_nos == AV_PICTURE_TYPE_B ) {

            for( i = 0; i < 4; i++ ) {

                sl->sub_mb_type[i] = decode_cabac_b_mb_sub_type(sl);

                sub_partition_count[i] = b_sub_mb_type_info[sl->sub_mb_type[i]].partition_count;

                sl->sub_mb_type[i]     = b_sub_mb_type_info[sl->sub_mb_type[i]].type;

            }

            if (IS_DIRECT(sl->sub_mb_type[0] | sl->sub_mb_type[1] |

                          sl->sub_mb_type[2] | sl->sub_mb_type[3])) {

                ff_h264_pred_direct_motion(h, sl, &mb_type);

                sl->ref_cache[0][scan8[4]] =

                sl->ref_cache[1][scan8[4]] =

                sl->ref_cache[0][scan8[12]] =

                sl->ref_cache[1][scan8[12]] = PART_NOT_AVAILABLE;

                    for( i = 0; i < 4; i++ )

                        fill_rectangle(&sl->direct_cache[scan8[4*i]], 2, 2, 8, (sl->sub_mb_type[i] >> 1) & 0xFF, 1);

            }

        } else {

            for( i = 0; i < 4; i++ ) {

                sl->sub_mb_type[i] = decode_cabac_p_mb_sub_type(sl);

                sub_partition_count[i] = p_sub_mb_type_info[sl->sub_mb_type[i]].partition_count;

                sl->sub_mb_type[i]     = p_sub_mb_type_info[sl->sub_mb_type[i]].type;

            }

        }



        for( list = 0; list < sl->list_count; list++ ) {

                for( i = 0; i < 4; i++ ) {

                    if(IS_DIRECT(sl->sub_mb_type[i])) continue;

                    if(IS_DIR(sl->sub_mb_type[i], 0, list)){

                        unsigned rc = sl->ref_count[list] << MB_MBAFF(sl);

                        if (rc > 1) {

                            ref[list][i] = decode_cabac_mb_ref(sl, list, 4 * i);

                            if (ref[list][i] >= rc) {

                                av_log(h->avctx, AV_LOG_ERROR, "Reference %d >= %d\n", ref[list][i], rc);

                                return -1;

                            }

                        }else

                            ref[list][i] = 0;

                    } else {

                        ref[list][i] = -1;

                    }

                    sl->ref_cache[list][scan8[4 * i] + 1] =

                    sl->ref_cache[list][scan8[4 * i] + 8] = sl->ref_cache[list][scan8[4 * i] + 9] = ref[list][i];

                }

        }



        if(dct8x8_allowed)

            dct8x8_allowed = get_dct8x8_allowed(h, sl);



        for (list = 0; list < sl->list_count; list++) {

            for(i=0; i<4; i++){

                sl->ref_cache[list][scan8[4 * i]] = sl->ref_cache[list][scan8[4 * i] + 1];

                if(IS_DIRECT(sl->sub_mb_type[i])){

                    fill_rectangle(sl->mvd_cache[list][scan8[4*i]], 2, 2, 8, 0, 2);

                    continue;

                }



                if(IS_DIR(sl->sub_mb_type[i], 0, list) && !IS_DIRECT(sl->sub_mb_type[i])){

                    const int sub_mb_type= sl->sub_mb_type[i];

                    const int block_width= (sub_mb_type & (MB_TYPE_16x16|MB_TYPE_16x8)) ? 2 : 1;

                    for(j=0; j<sub_partition_count[i]; j++){

                        int mpx, mpy;

                        int mx, my;

                        const int index= 4*i + block_width*j;

                        int16_t (* mv_cache)[2] = &sl->mv_cache[list][ scan8[index] ];

                        uint8_t (* mvd_cache)[2]= &sl->mvd_cache[list][ scan8[index] ];

                        pred_motion(h, sl, index, block_width, list, sl->ref_cache[list][ scan8[index] ], &mx, &my);

                        DECODE_CABAC_MB_MVD(sl, list, index)

                        ff_tlog(h->avctx, "final mv:%d %d\n", mx, my);



                        if(IS_SUB_8X8(sub_mb_type)){

                            mv_cache[ 1 ][0]=

                            mv_cache[ 8 ][0]= mv_cache[ 9 ][0]= mx;

                            mv_cache[ 1 ][1]=

                            mv_cache[ 8 ][1]= mv_cache[ 9 ][1]= my;



                            mvd_cache[ 1 ][0]=

                            mvd_cache[ 8 ][0]= mvd_cache[ 9 ][0]= mpx;

                            mvd_cache[ 1 ][1]=

                            mvd_cache[ 8 ][1]= mvd_cache[ 9 ][1]= mpy;

                        }else if(IS_SUB_8X4(sub_mb_type)){

                            mv_cache[ 1 ][0]= mx;

                            mv_cache[ 1 ][1]= my;



                            mvd_cache[ 1 ][0]=  mpx;

                            mvd_cache[ 1 ][1]= mpy;

                        }else if(IS_SUB_4X8(sub_mb_type)){

                            mv_cache[ 8 ][0]= mx;

                            mv_cache[ 8 ][1]= my;



                            mvd_cache[ 8 ][0]= mpx;

                            mvd_cache[ 8 ][1]= mpy;

                        }

                        mv_cache[ 0 ][0]= mx;

                        mv_cache[ 0 ][1]= my;



                        mvd_cache[ 0 ][0]= mpx;

                        mvd_cache[ 0 ][1]= mpy;

                    }

                }else{

                    fill_rectangle(sl->mv_cache [list][ scan8[4*i] ], 2, 2, 8, 0, 4);

                    fill_rectangle(sl->mvd_cache[list][ scan8[4*i] ], 2, 2, 8, 0, 2);

                }

            }

        }

    } else if( IS_DIRECT(mb_type) ) {

        ff_h264_pred_direct_motion(h, sl, &mb_type);

        fill_rectangle(sl->mvd_cache[0][scan8[0]], 4, 4, 8, 0, 2);

        fill_rectangle(sl->mvd_cache[1][scan8[0]], 4, 4, 8, 0, 2);

        dct8x8_allowed &= h->sps.direct_8x8_inference_flag;

    } else {

        int list, i;

        if(IS_16X16(mb_type)){

            for (list = 0; list < sl->list_count; list++) {

                if(IS_DIR(mb_type, 0, list)){

                    int ref;

                    unsigned rc = sl->ref_count[list] << MB_MBAFF(sl);

                    if (rc > 1) {

                        ref= decode_cabac_mb_ref(sl, list, 0);

                        if (ref >= rc) {

                            av_log(h->avctx, AV_LOG_ERROR, "Reference %d >= %d\n", ref, rc);

                            return -1;

                        }

                    }else

                        ref=0;

                    fill_rectangle(&sl->ref_cache[list][ scan8[0] ], 4, 4, 8, ref, 1);

                }

            }

            for (list = 0; list < sl->list_count; list++) {

                if(IS_DIR(mb_type, 0, list)){

                    int mx,my,mpx,mpy;

                    pred_motion(h, sl, 0, 4, list, sl->ref_cache[list][ scan8[0] ], &mx, &my);

                    DECODE_CABAC_MB_MVD(sl, list, 0)

                    ff_tlog(h->avctx, "final mv:%d %d\n", mx, my);



                    fill_rectangle(sl->mvd_cache[list][ scan8[0] ], 4, 4, 8, pack8to16(mpx,mpy), 2);

                    fill_rectangle(sl->mv_cache[list][ scan8[0] ], 4, 4, 8, pack16to32(mx,my), 4);

                }

            }

        }

        else if(IS_16X8(mb_type)){

            for (list = 0; list < sl->list_count; list++) {

                    for(i=0; i<2; i++){

                        if(IS_DIR(mb_type, i, list)){

                            int ref;

                            unsigned rc = sl->ref_count[list] << MB_MBAFF(sl);

                            if (rc > 1) {

                                ref= decode_cabac_mb_ref(sl, list, 8 * i);

                                if (ref >= rc) {

                                    av_log(h->avctx, AV_LOG_ERROR, "Reference %d >= %d\n", ref, rc);

                                    return -1;

                                }

                            }else

                                ref=0;

                            fill_rectangle(&sl->ref_cache[list][ scan8[0] + 16*i ], 4, 2, 8, ref, 1);

                        }else

                            fill_rectangle(&sl->ref_cache[list][ scan8[0] + 16*i ], 4, 2, 8, (LIST_NOT_USED&0xFF), 1);

                    }

            }

            for (list = 0; list < sl->list_count; list++) {

                for(i=0; i<2; i++){

                    if(IS_DIR(mb_type, i, list)){

                        int mx,my,mpx,mpy;

                        pred_16x8_motion(h, sl, 8*i, list, sl->ref_cache[list][scan8[0] + 16*i], &mx, &my);

                        DECODE_CABAC_MB_MVD(sl, list, 8*i)

                        ff_tlog(h->avctx, "final mv:%d %d\n", mx, my);



                        fill_rectangle(sl->mvd_cache[list][ scan8[0] + 16*i ], 4, 2, 8, pack8to16(mpx,mpy), 2);

                        fill_rectangle(sl->mv_cache[list][ scan8[0] + 16*i ], 4, 2, 8, pack16to32(mx,my), 4);

                    }else{

                        fill_rectangle(sl->mvd_cache[list][ scan8[0] + 16*i ], 4, 2, 8, 0, 2);

                        fill_rectangle(sl->mv_cache[list][ scan8[0] + 16*i ], 4, 2, 8, 0, 4);

                    }

                }

            }

        }else{

            av_assert2(IS_8X16(mb_type));

            for (list = 0; list < sl->list_count; list++) {

                    for(i=0; i<2; i++){

                        if(IS_DIR(mb_type, i, list)){ //FIXME optimize

                            int ref;

                            unsigned rc = sl->ref_count[list] << MB_MBAFF(sl);

                            if (rc > 1) {

                                ref = decode_cabac_mb_ref(sl, list, 4 * i);

                                if (ref >= rc) {

                                    av_log(h->avctx, AV_LOG_ERROR, "Reference %d >= %d\n", ref, rc);

                                    return -1;

                                }

                            }else

                                ref=0;

                            fill_rectangle(&sl->ref_cache[list][ scan8[0] + 2*i ], 2, 4, 8, ref, 1);

                        }else

                            fill_rectangle(&sl->ref_cache[list][ scan8[0] + 2*i ], 2, 4, 8, (LIST_NOT_USED&0xFF), 1);

                    }

            }

            for (list = 0; list < sl->list_count; list++) {

                for(i=0; i<2; i++){

                    if(IS_DIR(mb_type, i, list)){

                        int mx,my,mpx,mpy;

                        pred_8x16_motion(h, sl, i*4, list, sl->ref_cache[list][ scan8[0] + 2*i ], &mx, &my);

                        DECODE_CABAC_MB_MVD(sl, list, 4*i)



                        ff_tlog(h->avctx, "final mv:%d %d\n", mx, my);

                        fill_rectangle(sl->mvd_cache[list][ scan8[0] + 2*i ], 2, 4, 8, pack8to16(mpx,mpy), 2);

                        fill_rectangle(sl->mv_cache[list][ scan8[0] + 2*i ], 2, 4, 8, pack16to32(mx,my), 4);

                    }else{

                        fill_rectangle(sl->mvd_cache[list][ scan8[0] + 2*i ], 2, 4, 8, 0, 2);

                        fill_rectangle(sl->mv_cache[list][ scan8[0] + 2*i ], 2, 4, 8, 0, 4);

                    }

                }

            }

        }

    }



   if( IS_INTER( mb_type ) ) {

        h->chroma_pred_mode_table[mb_xy] = 0;

        write_back_motion(h, sl, mb_type);

   }



    if( !IS_INTRA16x16( mb_type ) ) {

        cbp  = decode_cabac_mb_cbp_luma(sl);

        if(decode_chroma)

            cbp |= decode_cabac_mb_cbp_chroma(sl) << 4;

    } else {

        if (!decode_chroma && cbp>15) {

            av_log(h->avctx, AV_LOG_ERROR, "gray chroma\n");

            return AVERROR_INVALIDDATA;

        }

    }



    h->cbp_table[mb_xy] = sl->cbp = cbp;



    if( dct8x8_allowed && (cbp&15) && !IS_INTRA( mb_type ) ) {

        mb_type |= MB_TYPE_8x8DCT * get_cabac_noinline(&sl->cabac, &sl->cabac_state[399 + sl->neighbor_transform_size]);

    }



    /* It would be better to do this in fill_decode_caches, but we don't know

     * the transform mode of the current macroblock there. */

    if (CHROMA444(h) && IS_8x8DCT(mb_type)){

        int i;

        uint8_t *nnz_cache = sl->non_zero_count_cache;

        for (i = 0; i < 2; i++){

            if (sl->left_type[LEFT(i)] && !IS_8x8DCT(sl->left_type[LEFT(i)])) {

                nnz_cache[3+8* 1 + 2*8*i]=

                nnz_cache[3+8* 2 + 2*8*i]=

                nnz_cache[3+8* 6 + 2*8*i]=

                nnz_cache[3+8* 7 + 2*8*i]=

                nnz_cache[3+8*11 + 2*8*i]=

                nnz_cache[3+8*12 + 2*8*i]= IS_INTRA(mb_type) ? 64 : 0;

            }

        }

        if (sl->top_type && !IS_8x8DCT(sl->top_type)){

            uint32_t top_empty = CABAC(h) && !IS_INTRA(mb_type) ? 0 : 0x40404040;

            AV_WN32A(&nnz_cache[4+8* 0], top_empty);

            AV_WN32A(&nnz_cache[4+8* 5], top_empty);

            AV_WN32A(&nnz_cache[4+8*10], top_empty);

        }

    }

    h->cur_pic.mb_type[mb_xy] = mb_type;



    if( cbp || IS_INTRA16x16( mb_type ) ) {

        const uint8_t *scan, *scan8x8;

        const uint32_t *qmul;



        if(IS_INTERLACED(mb_type)){

            scan8x8 = sl->qscale ? h->field_scan8x8 : h->field_scan8x8_q0;

            scan    = sl->qscale ? h->field_scan : h->field_scan_q0;

        }else{

            scan8x8 = sl->qscale ? h->zigzag_scan8x8 : h->zigzag_scan8x8_q0;

            scan    = sl->qscale ? h->zigzag_scan : h->zigzag_scan_q0;

        }



        // decode_cabac_mb_dqp

        if(get_cabac_noinline( &sl->cabac, &sl->cabac_state[60 + (sl->last_qscale_diff != 0)])){

            int val = 1;

            int ctx= 2;

            const int max_qp = 51 + 6*(h->sps.bit_depth_luma-8);



            while( get_cabac_noinline( &sl->cabac, &sl->cabac_state[60 + ctx] ) ) {

                ctx= 3;

                val++;

                if(val > 2*max_qp){ //prevent infinite loop

                    av_log(h->avctx, AV_LOG_ERROR, "cabac decode of qscale diff failed at %d %d\n", sl->mb_x, sl->mb_y);

                    return -1;

                }

            }



            if( val&0x01 )

                val=   (val + 1)>>1 ;

            else

                val= -((val + 1)>>1);

            sl->last_qscale_diff = val;

            sl->qscale += val;

            if (((unsigned)sl->qscale) > max_qp){

                if (sl->qscale < 0) sl->qscale += max_qp + 1;

                else                sl->qscale -= max_qp + 1;

            }

            sl->chroma_qp[0] = get_chroma_qp(h, 0, sl->qscale);

            sl->chroma_qp[1] = get_chroma_qp(h, 1, sl->qscale);

        }else

            sl->last_qscale_diff=0;



        decode_cabac_luma_residual(h, sl, scan, scan8x8, pixel_shift, mb_type, cbp, 0);

        if (CHROMA444(h)) {

            decode_cabac_luma_residual(h, sl, scan, scan8x8, pixel_shift, mb_type, cbp, 1);

            decode_cabac_luma_residual(h, sl, scan, scan8x8, pixel_shift, mb_type, cbp, 2);

        } else if (CHROMA422(h)) {

            if( cbp&0x30 ){

                int c;

                for (c = 0; c < 2; c++)

                    decode_cabac_residual_dc_422(h, sl, sl->mb + ((256 + 16*16*c) << pixel_shift), 3,

                                                 CHROMA_DC_BLOCK_INDEX + c,

                                                 chroma422_dc_scan, 8);

            }



            if( cbp&0x20 ) {

                int c, i, i8x8;

                for( c = 0; c < 2; c++ ) {

                    int16_t *mb = sl->mb + (16*(16 + 16*c) << pixel_shift);

                    qmul = h->dequant4_coeff[c+1+(IS_INTRA( mb_type ) ? 0:3)][sl->chroma_qp[c]];

                    for (i8x8 = 0; i8x8 < 2; i8x8++) {

                        for (i = 0; i < 4; i++) {

                            const int index = 16 + 16 * c + 8*i8x8 + i;

                            decode_cabac_residual_nondc(h, sl, mb, 4, index, scan + 1, qmul, 15);

                            mb += 16<<pixel_shift;

                        }

                    }

                }

            } else {

                fill_rectangle(&sl->non_zero_count_cache[scan8[16]], 4, 4, 8, 0, 1);

                fill_rectangle(&sl->non_zero_count_cache[scan8[32]], 4, 4, 8, 0, 1);

            }

        } else /* yuv420 */ {

            if( cbp&0x30 ){

                int c;

                for (c = 0; c < 2; c++)

                    decode_cabac_residual_dc(h, sl, sl->mb + ((256 + 16*16*c) << pixel_shift), 3, CHROMA_DC_BLOCK_INDEX+c, chroma_dc_scan, 4);

            }



            if( cbp&0x20 ) {

                int c, i;

                for( c = 0; c < 2; c++ ) {

                    qmul = h->dequant4_coeff[c+1+(IS_INTRA( mb_type ) ? 0:3)][sl->chroma_qp[c]];

                    for( i = 0; i < 4; i++ ) {

                        const int index = 16 + 16 * c + i;

                        decode_cabac_residual_nondc(h, sl, sl->mb + (16*index << pixel_shift), 4, index, scan + 1, qmul, 15);

                    }

                }

            } else {

                fill_rectangle(&sl->non_zero_count_cache[scan8[16]], 4, 4, 8, 0, 1);

                fill_rectangle(&sl->non_zero_count_cache[scan8[32]], 4, 4, 8, 0, 1);

            }

        }

    } else {

        fill_rectangle(&sl->non_zero_count_cache[scan8[ 0]], 4, 4, 8, 0, 1);

        fill_rectangle(&sl->non_zero_count_cache[scan8[16]], 4, 4, 8, 0, 1);

        fill_rectangle(&sl->non_zero_count_cache[scan8[32]], 4, 4, 8, 0, 1);

        sl->last_qscale_diff = 0;

    }



    h->cur_pic.qscale_table[mb_xy] = sl->qscale;

    write_back_non_zero_count(h, sl);



    return 0;

}

static int swf_write_header(AVFormatContext *s)

{

    SWFContext *swf = s->priv_data;

    AVIOContext *pb = s->pb;

    PutBitContext p;

    uint8_t buf1[256];

    int i, width, height, rate, rate_base;

    int version;



    swf->sound_samples = 0;

    swf->swf_frame_number = 0;

    swf->video_frame_number = 0;



    for(i=0;i<s->nb_streams;i++) {

        AVCodecContext *enc = s->streams[i]->codec;

        if (enc->codec_type == AVMEDIA_TYPE_AUDIO) {

            if (swf->audio_enc) {

                av_log(s, AV_LOG_ERROR, "SWF muxer only supports 1 audio stream\n");

                return AVERROR_INVALIDDATA;


            if (enc->codec_id == AV_CODEC_ID_MP3) {

                if (!enc->frame_size) {

                    av_log(s, AV_LOG_ERROR, "audio frame size not set\n");

                    return -1;


                swf->audio_enc = enc;

                swf->audio_fifo= av_fifo_alloc(AUDIO_FIFO_SIZE);

                if (!swf->audio_fifo)

                    return AVERROR(ENOMEM);

            } else {

                av_log(s, AV_LOG_ERROR, "SWF muxer only supports MP3\n");

                return -1;


        } else {

            if (swf->video_enc) {

                av_log(s, AV_LOG_ERROR, "SWF muxer only supports 1 video stream\n");

                return AVERROR_INVALIDDATA;


            if (enc->codec_id == AV_CODEC_ID_VP6F ||

                enc->codec_id == AV_CODEC_ID_FLV1 ||

                enc->codec_id == AV_CODEC_ID_MJPEG) {

                swf->video_st  = s->streams[i];

                swf->video_enc = enc;

            } else {

                av_log(s, AV_LOG_ERROR, "SWF muxer only supports VP6, FLV1 and MJPEG\n");

                return -1;






    if (!swf->video_enc) {

        /* currently, cannot work correctly if audio only */

        width = 320;

        height = 200;

        rate = 10;

        rate_base= 1;

    } else {

        width = swf->video_enc->width;

        height = swf->video_enc->height;

        // TODO: should be avg_frame_rate

        rate = swf->video_st->time_base.den;

        rate_base = swf->video_st->time_base.num;




    if (!swf->audio_enc)

        swf->samples_per_frame = (44100LL * rate_base) / rate;

    else

        swf->samples_per_frame = (swf->audio_enc->sample_rate * rate_base) / rate;



    avio_write(pb, "FWS", 3);



    if (!strcmp("avm2", s->oformat->name))

        version = 9;

    else if (swf->video_enc && swf->video_enc->codec_id == AV_CODEC_ID_VP6F)

        version = 8; /* version 8 and above support VP6 codec */

    else if (swf->video_enc && swf->video_enc->codec_id == AV_CODEC_ID_FLV1)

        version = 6; /* version 6 and above support FLV1 codec */

    else

        version = 4; /* version 4 for mpeg audio support */

    avio_w8(pb, version);



    avio_wl32(pb, DUMMY_FILE_SIZE); /* dummy size

                                      (will be patched if not streamed) */



    put_swf_rect(pb, 0, width * 20, 0, height * 20);





    avio_wl16(pb, (rate * 256) / rate_base); /* frame rate */

    swf->duration_pos = avio_tell(pb);

    avio_wl16(pb, (uint16_t)(DUMMY_DURATION * (int64_t)rate / rate_base)); /* frame count */



    /* avm2/swf v9 (also v8?) files require a file attribute tag */

    if (version == 9) {

        put_swf_tag(s, TAG_FILEATTRIBUTES);

        avio_wl32(pb, 1<<3); /* set ActionScript v3/AVM2 flag */

        put_swf_end_tag(s);




    /* define a shape with the jpeg inside */

    if (swf->video_enc && swf->video_enc->codec_id == AV_CODEC_ID_MJPEG) {

        put_swf_tag(s, TAG_DEFINESHAPE);



        avio_wl16(pb, SHAPE_ID); /* ID of shape */

        /* bounding rectangle */

        put_swf_rect(pb, 0, width, 0, height);

        /* style info */

        avio_w8(pb, 1); /* one fill style */

        avio_w8(pb, 0x41); /* clipped bitmap fill */

        avio_wl16(pb, BITMAP_ID); /* bitmap ID */

        /* position of the bitmap */

        put_swf_matrix(pb, 1 << FRAC_BITS, 0,

                       0,  1 << FRAC_BITS, 0, 0);

        avio_w8(pb, 0); /* no line style */



        /* shape drawing */

        init_put_bits(&p, buf1, sizeof(buf1));

        put_bits(&p, 4, 1); /* one fill bit */

        put_bits(&p, 4, 0); /* zero line bit */



        put_bits(&p, 1, 0); /* not an edge */

        put_bits(&p, 5, FLAG_MOVETO | FLAG_SETFILL0);

        put_bits(&p, 5, 1); /* nbits */

        put_bits(&p, 1, 0); /* X */

        put_bits(&p, 1, 0); /* Y */

        put_bits(&p, 1, 1); /* set fill style 1 */



        /* draw the rectangle ! */

        put_swf_line_edge(&p, width, 0);

        put_swf_line_edge(&p, 0, height);

        put_swf_line_edge(&p, -width, 0);

        put_swf_line_edge(&p, 0, -height);



        /* end of shape */

        put_bits(&p, 1, 0); /* not an edge */

        put_bits(&p, 5, 0);



        flush_put_bits(&p);

        avio_write(pb, buf1, put_bits_ptr(&p) - p.buf);



        put_swf_end_tag(s);




    if (swf->audio_enc && swf->audio_enc->codec_id == AV_CODEC_ID_MP3) {

        int v = 0;



        /* start sound */

        put_swf_tag(s, TAG_STREAMHEAD2);

        switch(swf->audio_enc->sample_rate) {

        case 11025: v |= 1 << 2; break;

        case 22050: v |= 2 << 2; break;

        case 44100: v |= 3 << 2; break;

        default:

            /* not supported */

            av_log(s, AV_LOG_ERROR, "swf does not support that sample rate, choose from (44100, 22050, 11025).\n");

            return -1;


        v |= 0x02; /* 16 bit playback */

        if (swf->audio_enc->channels == 2)

            v |= 0x01; /* stereo playback */

        avio_w8(s->pb, v);

        v |= 0x20; /* mp3 compressed */

        avio_w8(s->pb, v);

        avio_wl16(s->pb, swf->samples_per_frame);  /* avg samples per frame */

        avio_wl16(s->pb, 0);



        put_swf_end_tag(s);




    avio_flush(s->pb);

    return 0;

static void decode(AVCodecContext *dec_ctx, AVFrame *frame, AVPacket *pkt,

                   const char *filename)

{

    char buf[1024];

    int ret;



    ret = avcodec_send_packet(dec_ctx, pkt);

    if (ret < 0) {

        fprintf(stderr, "Error sending a packet for decoding\n");

        exit(1);

    }



    while (ret >= 0) {

        ret = avcodec_receive_frame(dec_ctx, frame);

        if (ret == AVERROR(EAGAIN) || ret == AVERROR_EOF)

            return;

        else if (ret < 0) {

            fprintf(stderr, "Error during decoding\n");

            exit(1);

        }



        printf("saving frame %3d\n", dec_ctx->frame_number);

        fflush(stdout);



        /* the picture is allocated by the decoder. no need to

           free it */

        snprintf(buf, sizeof(buf), filename, dec_ctx->frame_number);

        pgm_save(frame->data[0], frame->linesize[0],

                 frame->width, frame->height, buf);

    }

}

static void ripemd128_transform(uint32_t *state, const uint8_t buffer[64], int ext)

{

    uint32_t a, b, c, d, e, f, g, h;

    uint32_t block[16];

    int n;



    if (ext) {

        a = state[0]; b = state[1]; c = state[2]; d = state[3];

        e = state[4]; f = state[5]; g = state[6]; h = state[7];

    } else {

        a = e = state[0];

        b = f = state[1];

        c = g = state[2];

        d = h = state[3];

    }



    for (n = 0; n < 16; n++)

        block[n] = AV_RL32(buffer + 4 * n);



    for (n = 0; n < 16;) {

        ROUND128_0_TO_15(a,b,c,d,e,f,g,h);

        ROUND128_0_TO_15(d,a,b,c,h,e,f,g);

        ROUND128_0_TO_15(c,d,a,b,g,h,e,f);

        ROUND128_0_TO_15(b,c,d,a,f,g,h,e);

    }

    SWAP(a,e)



    for (; n < 32;) {

        ROUND128_16_TO_31(a,b,c,d,e,f,g,h);

        ROUND128_16_TO_31(d,a,b,c,h,e,f,g);

        ROUND128_16_TO_31(c,d,a,b,g,h,e,f);

        ROUND128_16_TO_31(b,c,d,a,f,g,h,e);

    }

    SWAP(b,f)



    for (; n < 48;) {

        ROUND128_32_TO_47(a,b,c,d,e,f,g,h);

        ROUND128_32_TO_47(d,a,b,c,h,e,f,g);

        ROUND128_32_TO_47(c,d,a,b,g,h,e,f);

        ROUND128_32_TO_47(b,c,d,a,f,g,h,e);

    }

    SWAP(c,g)



    for (; n < 64;) {

        ROUND128_48_TO_63(a,b,c,d,e,f,g,h);

        ROUND128_48_TO_63(d,a,b,c,h,e,f,g);

        ROUND128_48_TO_63(c,d,a,b,g,h,e,f);

        ROUND128_48_TO_63(b,c,d,a,f,g,h,e);

    }

    SWAP(d,h)



    if (ext) {

        state[0] += a; state[1] += b; state[2] += c; state[3] += d;

        state[4] += e; state[5] += f; state[6] += g; state[7] += h;

    } else {

        h += c + state[1];

        state[1] = state[2] + d + e;

        state[2] = state[3] + a + f;

        state[3] = state[0] + b + g;

        state[0] = h;

    }

}

static av_cold int a64multi_init_encoder(AVCodecContext *avctx)

{

    A64Context *c = avctx->priv_data;

    int a;

    av_lfg_init(&c->randctx, 1);



    if (avctx->global_quality < 1) {

        c->mc_lifetime = 4;

    } else {

        c->mc_lifetime = avctx->global_quality /= FF_QP2LAMBDA;

    }



    av_log(avctx, AV_LOG_INFO, "charset lifetime set to %d frame(s)\n", c->mc_lifetime);



    /* precalc luma values for later use */

    for (a = 0; a < 5; a++) {

        c->mc_luma_vals[a]=a64_palette[mc_colors[a]][0] * 0.30 +

                           a64_palette[mc_colors[a]][1] * 0.59 +

                           a64_palette[mc_colors[a]][2] * 0.11;

    }



    c->mc_frame_counter = 0;

    c->mc_use_5col      = avctx->codec->id == CODEC_ID_A64_MULTI5;

    c->mc_meta_charset  = av_malloc (32000 * c->mc_lifetime * sizeof(int));

    c->mc_best_cb       = av_malloc (CHARSET_CHARS * 32 * sizeof(int));

    c->mc_charmap       = av_mallocz(1000 * c->mc_lifetime * sizeof(int));

    c->mc_colram        = av_mallocz(CHARSET_CHARS * sizeof(uint8_t));

    c->mc_charset       = av_malloc (0x800 * (INTERLACED+1) * sizeof(uint8_t));



    /* set up extradata */

    avctx->extradata      = av_mallocz(8 * 4 + FF_INPUT_BUFFER_PADDING_SIZE);

    avctx->extradata_size = 8 * 4;

    AV_WB32(avctx->extradata, c->mc_lifetime);

    AV_WB32(avctx->extradata+16, INTERLACED);



    avcodec_get_frame_defaults(&c->picture);

    avctx->coded_frame            = &c->picture;

    avctx->coded_frame->pict_type = FF_I_TYPE;

    avctx->coded_frame->key_frame = 1;

    if (!avctx->codec_tag)

         avctx->codec_tag = AV_RL32("a64m");



    return 0;

}

static int webm_dash_manifest_write_header(AVFormatContext *s)

{

    int i;

    double start = 0.0;

    WebMDashMuxContext *w = s->priv_data;

    parse_adaptation_sets(s);

    write_header(s);

    avio_printf(s->pb, "<Period id=\"0\"");

    avio_printf(s->pb, " start=\"PT%gS\"", start);

    if (!w->is_live) {

        avio_printf(s->pb, " duration=\"PT%gS\"", get_duration(s));

    }

    avio_printf(s->pb, " >\n");



    for (i = 0; i < w->nb_as; i++) {

        if (write_adaptation_set(s, i) < 0) return -1;

    }



    avio_printf(s->pb, "</Period>\n");

    write_footer(s);

    return 0;

}

static int analyze_chunk(AVFormatContext *s, const uint8_t *chunk)
{
    TYDemuxContext *ty = s->priv_data;
    int num_recs, i;
    TyRecHdr *hdrs;
    int num_6e0, num_be0, num_9c0, num_3c0;
    /* skip if it's a Part header */
    if (AV_RB32(&chunk[0]) == TIVO_PES_FILEID)
        return 0;
    /* number of records in chunk (we ignore high order byte;
     * rarely are there > 256 chunks & we don't need that many anyway) */
    num_recs = chunk[0];
    if (num_recs < 5) {
        /* try again with the next chunk.  Sometimes there are dead ones */
        return 0;
    }
    chunk += 4;       /* skip past rec count & SEQ bytes */
    ff_dlog(s, "probe: chunk has %d recs\n", num_recs);
    hdrs = parse_chunk_headers(chunk, num_recs);
    if (!hdrs)
        return AVERROR(ENOMEM);
    /* scan headers.
     * 1. check video packets.  Presence of 0x6e0 means S1.
     *    No 6e0 but have be0 means S2.
     * 2. probe for audio 0x9c0 vs 0x3c0 (AC3 vs Mpeg)
     *    If AC-3, then we have DTivo.
     *    If MPEG, search for PTS offset.  This will determine SA vs. DTivo.
     */
    num_6e0 = num_be0 = num_9c0 = num_3c0 = 0;
    for (i = 0; i < num_recs; i++) {
        switch (hdrs[i].subrec_type << 8 | hdrs[i].rec_type) {
        case 0x6e0:
            num_6e0++;
        case 0xbe0:
            num_be0++;
        case 0x3c0:
            num_3c0++;
        case 0x9c0:
            num_9c0++;
        }
    }
    ff_dlog(s, "probe: chunk has %d 0x6e0 recs, %d 0xbe0 recs.\n",
            num_6e0, num_be0);
    /* set up our variables */
    if (num_6e0 > 0) {
        ff_dlog(s, "detected Series 1 Tivo\n");
        ty->tivo_series = TIVO_SERIES1;
        ty->pes_length = SERIES1_PES_LENGTH;
    } else if (num_be0 > 0) {
        ff_dlog(s, "detected Series 2 Tivo\n");
        ty->tivo_series = TIVO_SERIES2;
        ty->pes_length = SERIES2_PES_LENGTH;
    }
    if (num_9c0 > 0) {
        ff_dlog(s, "detected AC-3 Audio (DTivo)\n");
        ty->audio_type = TIVO_AUDIO_AC3;
        ty->tivo_type = TIVO_TYPE_DTIVO;
        ty->pts_offset = AC3_PTS_OFFSET;
        ty->pes_length = AC3_PES_LENGTH;
    } else if (num_3c0 > 0) {
        ty->audio_type = TIVO_AUDIO_MPEG;
        ff_dlog(s, "detected MPEG Audio\n");
    }
    /* if tivo_type still unknown, we can check PTS location
     * in MPEG packets to determine tivo_type */
    if (ty->tivo_type == TIVO_TYPE_UNKNOWN) {
        uint32_t data_offset = 16 * num_recs;
        for (i = 0; i < num_recs; i++) {
            if ((hdrs[i].subrec_type << 0x08 | hdrs[i].rec_type) == 0x3c0 && hdrs[i].rec_size > 15) {
                /* first make sure we're aligned */
                int pes_offset = find_es_header(ty_MPEGAudioPacket,
                        &chunk[data_offset], 5);
                if (pes_offset >= 0) {
                    /* pes found. on SA, PES has hdr data at offset 6, not PTS. */
                    if ((chunk[data_offset + 6 + pes_offset] & 0x80) == 0x80) {
                        /* S1SA or S2(any) Mpeg Audio (PES hdr, not a PTS start) */
                        if (ty->tivo_series == TIVO_SERIES1)
                            ff_dlog(s, "detected Stand-Alone Tivo\n");
                        ty->tivo_type = TIVO_TYPE_SA;
                        ty->pts_offset = SA_PTS_OFFSET;
                    } else {
                        if (ty->tivo_series == TIVO_SERIES1)
                            ff_dlog(s, "detected DirecTV Tivo\n");
                        ty->tivo_type = TIVO_TYPE_DTIVO;
                        ty->pts_offset = DTIVO_PTS_OFFSET;
                    }
                }
            }
            data_offset += hdrs[i].rec_size;
        }
    }
    av_free(hdrs);
    return 0;
}

static inline int writer_print_string(WriterContext *wctx,

                                      const char *key, const char *val, int opt)

{

    const struct section *section = wctx->section[wctx->level];

    int ret = 0;



    if (opt && !(wctx->writer->flags & WRITER_FLAG_DISPLAY_OPTIONAL_FIELDS))

        return 0;



    if (section->show_all_entries || av_dict_get(section->entries_to_show, key, NULL, 0)) {

        wctx->writer->print_string(wctx, key, val);

        wctx->nb_item[wctx->level]++;

    }



    return ret;

}

static av_always_inline float quantize_and_encode_band_cost_template(

                                struct AACEncContext *s,

                                PutBitContext *pb, const float *in,

                                const float *scaled, int size, int scale_idx,

                                int cb, const float lambda, const float uplim,

                                int *bits, int BT_ZERO, int BT_UNSIGNED,

                                int BT_PAIR, int BT_ESC)

{

    const int q_idx = POW_SF2_ZERO - scale_idx + SCALE_ONE_POS - SCALE_DIV_512;

    const float Q   = ff_aac_pow2sf_tab [q_idx];

    const float Q34 = ff_aac_pow34sf_tab[q_idx];

    const float IQ  = ff_aac_pow2sf_tab [POW_SF2_ZERO + scale_idx - SCALE_ONE_POS + SCALE_DIV_512];

    const float CLIPPED_ESCAPE = 165140.0f*IQ;

    int i, j;

    float cost = 0;

    const int dim = BT_PAIR ? 2 : 4;

    int resbits = 0;

    const int range  = aac_cb_range[cb];

    const int maxval = aac_cb_maxval[cb];

    int off;



    if (BT_ZERO) {

        for (i = 0; i < size; i++)

            cost += in[i]*in[i];

        if (bits)

            *bits = 0;

        return cost * lambda;

    }

    if (!scaled) {

        abs_pow34_v(s->scoefs, in, size);

        scaled = s->scoefs;

    }

    quantize_bands(s->qcoefs, in, scaled, size, Q34, !BT_UNSIGNED, maxval);

    if (BT_UNSIGNED) {

        off = 0;

    } else {

        off = maxval;

    }

    for (i = 0; i < size; i += dim) {

        const float *vec;

        int *quants = s->qcoefs + i;

        int curidx = 0;

        int curbits;

        float rd = 0.0f;

        for (j = 0; j < dim; j++) {

            curidx *= range;

            curidx += quants[j] + off;

        }

        curbits =  ff_aac_spectral_bits[cb-1][curidx];

        vec     = &ff_aac_codebook_vectors[cb-1][curidx*dim];

        if (BT_UNSIGNED) {

            for (j = 0; j < dim; j++) {

                float t = fabsf(in[i+j]);

                float di;

                if (BT_ESC && vec[j] == 64.0f) { //FIXME: slow

                    if (t >= CLIPPED_ESCAPE) {

                        di = t - CLIPPED_ESCAPE;

                        curbits += 21;

                    } else {

                        int c = av_clip_uintp2(quant(t, Q), 13);

                        di = t - c*cbrtf(c)*IQ;

                        curbits += av_log2(c)*2 - 4 + 1;

                    }

                } else {

                    di = t - vec[j]*IQ;

                }

                if (vec[j] != 0.0f)

                    curbits++;

                rd += di*di;

            }

        } else {

            for (j = 0; j < dim; j++) {

                float di = in[i+j] - vec[j]*IQ;

                rd += di*di;

            }

        }

        cost    += rd * lambda + curbits;

        resbits += curbits;

        if (cost >= uplim)

            return uplim;

        if (pb) {

            put_bits(pb, ff_aac_spectral_bits[cb-1][curidx], ff_aac_spectral_codes[cb-1][curidx]);

            if (BT_UNSIGNED)

                for (j = 0; j < dim; j++)

                    if (ff_aac_codebook_vectors[cb-1][curidx*dim+j] != 0.0f)

                        put_bits(pb, 1, in[i+j] < 0.0f);

            if (BT_ESC) {

                for (j = 0; j < 2; j++) {

                    if (ff_aac_codebook_vectors[cb-1][curidx*2+j] == 64.0f) {

                        int coef = av_clip_uintp2(quant(fabsf(in[i+j]), Q), 13);

                        int len = av_log2(coef);



                        put_bits(pb, len - 4 + 1, (1 << (len - 4 + 1)) - 2);

                        put_bits(pb, len, coef & ((1 << len) - 1));

                    }

                }

            }

        }

    }



    if (bits)

        *bits = resbits;

    return cost;

}

static int encode_init(AVCodecContext * avctx){

    WMACodecContext *s = avctx->priv_data;

    int i, flags1, flags2;

    uint8_t *extradata;



    s->avctx = avctx;



    if(avctx->channels > MAX_CHANNELS) {

        av_log(avctx, AV_LOG_ERROR, "too many channels: got %i, need %i or fewer",

               avctx->channels, MAX_CHANNELS);

        return AVERROR(EINVAL);

    }



    if (avctx->sample_rate > 48000) {

        av_log(avctx, AV_LOG_ERROR, "sample rate is too high: %d > 48kHz",

               avctx->sample_rate);

        return AVERROR(EINVAL);

    }



    if(avctx->bit_rate < 24*1000) {

        av_log(avctx, AV_LOG_ERROR, "bitrate too low: got %i, need 24000 or higher\n",

               avctx->bit_rate);

        return AVERROR(EINVAL);

    }



    /* extract flag infos */

    flags1 = 0;

    flags2 = 1;

    if (avctx->codec->id == CODEC_ID_WMAV1) {

        extradata= av_malloc(4);

        avctx->extradata_size= 4;

        AV_WL16(extradata, flags1);

        AV_WL16(extradata+2, flags2);

    } else if (avctx->codec->id == CODEC_ID_WMAV2) {

        extradata= av_mallocz(10);

        avctx->extradata_size= 10;

        AV_WL32(extradata, flags1);

        AV_WL16(extradata+4, flags2);

    }else

        av_assert0(0);

    avctx->extradata= extradata;

    s->use_exp_vlc = flags2 & 0x0001;

    s->use_bit_reservoir = flags2 & 0x0002;

    s->use_variable_block_len = flags2 & 0x0004;

    if (avctx->channels == 2)

        s->ms_stereo = 1;



    ff_wma_init(avctx, flags2);



    /* init MDCT */

    for(i = 0; i < s->nb_block_sizes; i++)

        ff_mdct_init(&s->mdct_ctx[i], s->frame_len_bits - i + 1, 0, 1.0);



    s->block_align     = avctx->bit_rate * (int64_t)s->frame_len /

                         (avctx->sample_rate * 8);

    s->block_align     = FFMIN(s->block_align, MAX_CODED_SUPERFRAME_SIZE);

    avctx->block_align = s->block_align;

    avctx->bit_rate    = avctx->block_align * 8LL * avctx->sample_rate /

                         s->frame_len;

//av_log(NULL, AV_LOG_ERROR, "%d %d %d %d\n", s->block_align, avctx->bit_rate, s->frame_len, avctx->sample_rate);

    avctx->frame_size = avctx->delay = s->frame_len;



#if FF_API_OLD_ENCODE_AUDIO

    avctx->coded_frame = &s->frame;

    avcodec_get_frame_defaults(avctx->coded_frame);

#endif



    return 0;

}

void ff_aac_search_for_is(AACEncContext *s, AVCodecContext *avctx, ChannelElement *cpe)

{

    SingleChannelElement *sce0 = &cpe->ch[0];

    SingleChannelElement *sce1 = &cpe->ch[1];

    int start = 0, count = 0, w, w2, g, i, prev_sf1 = -1;

    const float freq_mult = avctx->sample_rate/(1024.0f/sce0->ics.num_windows)/2.0f;

    uint8_t nextband1[128];



    if (!cpe->common_window)

        return;



    /** Scout out next nonzero bands */

    ff_init_nextband_map(sce1, nextband1);



    for (w = 0; w < sce0->ics.num_windows; w += sce0->ics.group_len[w]) {

        start = 0;

        for (g = 0;  g < sce0->ics.num_swb; g++) {

            if (start*freq_mult > INT_STEREO_LOW_LIMIT*(s->lambda/170.0f) &&

                cpe->ch[0].band_type[w*16+g] != NOISE_BT && !cpe->ch[0].zeroes[w*16+g] &&

                cpe->ch[1].band_type[w*16+g] != NOISE_BT && !cpe->ch[1].zeroes[w*16+g] &&

                ff_sfdelta_can_remove_band(sce1, nextband1, prev_sf1, w*16+g)) {

                float ener0 = 0.0f, ener1 = 0.0f, ener01 = 0.0f, ener01p = 0.0f;

                struct AACISError ph_err1, ph_err2, *best;

                if (sce0->band_type[w*16+g] == NOISE_BT ||

                    sce1->band_type[w*16+g] == NOISE_BT) {

                    start += sce0->ics.swb_sizes[g];

                    continue;

                }

                for (w2 = 0; w2 < sce0->ics.group_len[w]; w2++) {

                    for (i = 0; i < sce0->ics.swb_sizes[g]; i++) {

                        float coef0 = fabsf(sce0->coeffs[start+(w+w2)*128+i]);

                        float coef1 = fabsf(sce1->coeffs[start+(w+w2)*128+i]);

                        ener0  += coef0*coef0;

                        ener1  += coef1*coef1;

                        ener01 += (coef0 + coef1)*(coef0 + coef1);

                        ener01p += (coef0 - coef1)*(coef0 - coef1);

                    }

                }

                ph_err1 = ff_aac_is_encoding_err(s, cpe, start, w, g,

                                                 ener0, ener1, ener01p, 0, -1);

                ph_err2 = ff_aac_is_encoding_err(s, cpe, start, w, g,

                                                 ener0, ener1, ener01, 0, +1);

                best = (ph_err1.pass && ph_err1.error < ph_err2.error) ? &ph_err1 : &ph_err2;

                if (best->pass) {

                    cpe->is_mask[w*16+g] = 1;

                    cpe->ms_mask[w*16+g] = 0;

                    cpe->ch[0].is_ener[w*16+g] = sqrt(ener0 / best->ener01);

                    cpe->ch[1].is_ener[w*16+g] = ener0/ener1;

                    cpe->ch[1].band_type[w*16+g] = (best->phase > 0) ? INTENSITY_BT : INTENSITY_BT2;

                    count++;

                }

            }

            if (!sce1->zeroes[w*16+g] && sce1->band_type[w*16+g] < RESERVED_BT)

                prev_sf1 = sce1->sf_idx[w*16+g];

            start += sce0->ics.swb_sizes[g];

        }

    }

    cpe->is_mode = !!count;

}

static int ivi_decode_blocks(GetBitContext *gb, IVIBandDesc *band, IVITile *tile,
                             AVCodecContext *avctx)
{
    int         mbn, blk, num_blocks, num_coeffs, blk_size, scan_pos, run, val,
                pos, is_intra, mc_type = 0, mv_x, mv_y, col_mask;
    uint8_t     col_flags[8];
    int32_t     prev_dc, trvec[64];
    uint32_t    cbp, sym, lo, hi, quant, buf_offs, q;
    IVIMbInfo   *mb;
    RVMapDesc   *rvmap = band->rv_map;
    void (*mc_with_delta_func)(int16_t *buf, const int16_t *ref_buf, uint32_t pitch, int mc_type);
    void (*mc_no_delta_func)  (int16_t *buf, const int16_t *ref_buf, uint32_t pitch, int mc_type);
    const uint16_t  *base_tab;
    const uint8_t   *scale_tab;
    prev_dc = 0; /* init intra prediction for the DC coefficient */
    blk_size   = band->blk_size;
    col_mask   = blk_size - 1; /* column mask for tracking non-zero coeffs */
    num_blocks = (band->mb_size != blk_size) ? 4 : 1; /* number of blocks per mb */
    num_coeffs = blk_size * blk_size;
    if (blk_size == 8) {
        mc_with_delta_func = ff_ivi_mc_8x8_delta;
        mc_no_delta_func   = ff_ivi_mc_8x8_no_delta;
    } else {
        mc_with_delta_func = ff_ivi_mc_4x4_delta;
        mc_no_delta_func   = ff_ivi_mc_4x4_no_delta;
    for (mbn = 0, mb = tile->mbs; mbn < tile->num_MBs; mb++, mbn++) {
        is_intra = !mb->type;
        cbp      = mb->cbp;
        buf_offs = mb->buf_offs;
        quant = av_clip(band->glob_quant + mb->q_delta, 0, 23);
        base_tab  = is_intra ? band->intra_base  : band->inter_base;
        scale_tab = is_intra ? band->intra_scale : band->inter_scale;
        if (scale_tab)
            quant = scale_tab[quant];
        if (!is_intra) {
            mv_x = mb->mv_x;
            mv_y = mb->mv_y;
            if (band->is_halfpel) {
                mc_type = ((mv_y & 1) << 1) | (mv_x & 1);
                mv_x >>= 1;
                mv_y >>= 1; /* convert halfpel vectors into fullpel ones */
            if (mb->type) {
                int dmv_x, dmv_y, cx, cy;
                dmv_x = mb->mv_x >> band->is_halfpel;
                dmv_y = mb->mv_y >> band->is_halfpel;
                cx    = mb->mv_x &  band->is_halfpel;
                cy    = mb->mv_y &  band->is_halfpel;
                if (   mb->xpos + dmv_x < 0
                    || mb->xpos + dmv_x + band->mb_size + cx > band->pitch
                    || mb->ypos + dmv_y < 0
                    || mb->ypos + dmv_y + band->mb_size + cy > band->aheight) {
        for (blk = 0; blk < num_blocks; blk++) {
            /* adjust block position in the buffer according to its number */
            if (blk & 1) {
                buf_offs += blk_size;
            } else if (blk == 2) {
                buf_offs -= blk_size;
                buf_offs += blk_size * band->pitch;
            if (cbp & 1) { /* block coded ? */
                scan_pos = -1;
                memset(trvec, 0, num_coeffs*sizeof(trvec[0])); /* zero transform vector */
                memset(col_flags, 0, sizeof(col_flags));      /* zero column flags */
                while (scan_pos <= num_coeffs) {
                    sym = get_vlc2(gb, band->blk_vlc.tab->table, IVI_VLC_BITS, 1);
                    if (sym == rvmap->eob_sym)
                        break; /* End of block */
                    if (sym == rvmap->esc_sym) { /* Escape - run/val explicitly coded using 3 vlc codes */
                        run = get_vlc2(gb, band->blk_vlc.tab->table, IVI_VLC_BITS, 1) + 1;
                        lo  = get_vlc2(gb, band->blk_vlc.tab->table, IVI_VLC_BITS, 1);
                        hi  = get_vlc2(gb, band->blk_vlc.tab->table, IVI_VLC_BITS, 1);
                        val = IVI_TOSIGNED((hi << 6) | lo); /* merge them and convert into signed val */
                    } else {
                        if (sym >= 256U) {
                            av_log(avctx, AV_LOG_ERROR, "Invalid sym encountered: %d.\n", sym);
                            return -1;
                        run = rvmap->runtab[sym];
                        val = rvmap->valtab[sym];
                    /* de-zigzag and dequantize */
                    scan_pos += run;
                    if (scan_pos >= num_coeffs)
                        break;
                    pos = band->scan[scan_pos];
                    if (!val)
                        av_dlog(avctx, "Val = 0 encountered!\n");
                    q = (base_tab[pos] * quant) >> 9;
                    if (q > 1)
                        val = val * q + FFSIGN(val) * (((q ^ 1) - 1) >> 1);
                    trvec[pos] = val;
                    col_flags[pos & col_mask] |= !!val; /* track columns containing non-zero coeffs */
                }// while
                if (scan_pos >= num_coeffs && sym != rvmap->eob_sym)
                    return -1; /* corrupt block data */
                /* undoing DC coeff prediction for intra-blocks */
                if (is_intra && band->is_2d_trans) {
                    prev_dc      += trvec[0];
                    trvec[0]      = prev_dc;
                    col_flags[0] |= !!prev_dc;
                /* apply inverse transform */
                band->inv_transform(trvec, band->buf + buf_offs,
                                    band->pitch, col_flags);
                /* apply motion compensation */
                if (!is_intra)
                    mc_with_delta_func(band->buf + buf_offs,
                                       band->ref_buf + buf_offs + mv_y * band->pitch + mv_x,
                                       band->pitch, mc_type);
            } else {
                /* block not coded */
                /* for intra blocks apply the dc slant transform */
                /* for inter - perform the motion compensation without delta */
                if (is_intra && band->dc_transform) {
                    band->dc_transform(&prev_dc, band->buf + buf_offs,
                                       band->pitch, blk_size);
                } else
                    mc_no_delta_func(band->buf + buf_offs,
                                     band->ref_buf + buf_offs + mv_y * band->pitch + mv_x,
                                     band->pitch, mc_type);
            cbp >>= 1;
        }// for blk
    }// for mbn
    align_get_bits(gb);
    return 0;

static int skip_data_stream_element(AACContext *ac, GetBitContext *gb)

{

    int byte_align = get_bits1(gb);

    int count = get_bits(gb, 8);

    if (count == 255)

        count += get_bits(gb, 8);

    if (byte_align)

        align_get_bits(gb);



    if (get_bits_left(gb) < 8 * count) {

        av_log(ac->avctx, AV_LOG_ERROR, overread_err);

        return -1;

    }

    skip_bits_long(gb, 8 * count);

    return 0;

}

static int filter_frame(AVFilterLink *inlink, AVFrame *inbuf)

{

    AudioPhaserContext *s = inlink->dst->priv;

    AVFilterLink *outlink = inlink->dst->outputs[0];

    AVFrame *outbuf;



    if (av_frame_is_writable(inbuf)) {

        outbuf = inbuf;

    } else {

        outbuf = ff_get_audio_buffer(inlink, inbuf->nb_samples);

        if (!outbuf)

            return AVERROR(ENOMEM);

        av_frame_copy_props(outbuf, inbuf);

    }



    s->phaser(s, inbuf->extended_data, outbuf->extended_data,

              outbuf->nb_samples, outbuf->channels);



    if (inbuf != outbuf)

        av_frame_free(&inbuf);



    return ff_filter_frame(outlink, outbuf);

}

static AVStream *find_stream(void *log, AVFormatContext *avf, const char *spec)

{

    int i, ret, already = 0, stream_id = -1;

    char type_char, dummy;

    AVStream *found = NULL;

    enum AVMediaType type;



    ret = sscanf(spec, "d%[av]%d%c", &type_char, &stream_id, &dummy);

    if (ret >= 1 && ret <= 2) {

        type = type_char == 'v' ? AVMEDIA_TYPE_VIDEO : AVMEDIA_TYPE_AUDIO;

        ret = av_find_best_stream(avf, type, stream_id, -1, NULL, 0);

        if (ret < 0) {

            av_log(log, AV_LOG_ERROR, "No %s stream with index '%d' found\n",

                   av_get_media_type_string(type), stream_id);

            return NULL;

        }

        return avf->streams[ret];

    }

    for (i = 0; i < avf->nb_streams; i++) {

        ret = avformat_match_stream_specifier(avf, avf->streams[i], spec);

        if (ret < 0) {

            av_log(log, AV_LOG_ERROR,

                   "Invalid stream specifier \"%s\"\n", spec);

            return NULL;

        }

        if (!ret)

            continue;

        if (avf->streams[i]->discard != AVDISCARD_ALL) {

            already++;

            continue;

        }

        if (found) {

            av_log(log, AV_LOG_WARNING,

                   "Ambiguous stream specifier \"%s\", using #%d\n", spec, i);

            break;

        }

        found = avf->streams[i];

    }

    if (!found) {

        av_log(log, AV_LOG_WARNING, "Stream specifier \"%s\" %s\n", spec,

               already ? "matched only already used streams" :

                         "did not match any stream");

        return NULL;

    }

    if (found->codec->codec_type != AVMEDIA_TYPE_VIDEO &&

        found->codec->codec_type != AVMEDIA_TYPE_AUDIO) {

        av_log(log, AV_LOG_ERROR, "Stream specifier \"%s\" matched a %s stream,"

               "currently unsupported by libavfilter\n", spec,

               av_get_media_type_string(found->codec->codec_type));

        return NULL;

    }

    return found;

}

static void check_rgb2yuv(void)

{

    declare_func(void, uint8_t *dst[3], ptrdiff_t dst_stride[3],

                 int16_t *src[3], ptrdiff_t src_stride,

                 int w, int h, const int16_t coeff[3][3][8],

                 const int16_t off[8]);

    ColorSpaceDSPContext dsp;

    int odepth, fmt, n;

    LOCAL_ALIGNED_32(int16_t, src_y, [W * H * 2]);

    LOCAL_ALIGNED_32(int16_t, src_u, [W * H * 2]);

    LOCAL_ALIGNED_32(int16_t, src_v, [W * H * 2]);

    int16_t *src[3] = { src_y, src_u, src_v };

    LOCAL_ALIGNED_32(uint8_t, dst0_y, [W * H]);

    LOCAL_ALIGNED_32(uint8_t, dst0_u, [W * H]);

    LOCAL_ALIGNED_32(uint8_t, dst0_v, [W * H]);

    LOCAL_ALIGNED_32(uint8_t, dst1_y, [W * H]);

    LOCAL_ALIGNED_32(uint8_t, dst1_u, [W * H]);

    LOCAL_ALIGNED_32(uint8_t, dst1_v, [W * H]);

    uint8_t *dst0[3] = { dst0_y, dst0_u, dst0_v }, *dst1[3] = { dst1_y, dst1_u, dst1_v };

    LOCAL_ALIGNED_32(int16_t, offset, [8]);

    LOCAL_ALIGNED_32(int16_t, coeff_buf, [3 * 3 * 8]);

    int16_t (*coeff)[3][8] = (int16_t(*)[3][8]) coeff_buf;



    ff_colorspacedsp_init(&dsp);

    for (n = 0; n < 8; n++) {

        offset[n] = 16;



        // these somewhat resemble bt601/smpte170m coefficients

        coeff[0][0][n] = lrint(0.3 * (1 << 14));

        coeff[0][1][n] = lrint(0.6 * (1 << 14));

        coeff[0][2][n] = lrint(0.1 * (1 << 14));

        coeff[1][0][n] = lrint(-0.15 * (1 << 14));

        coeff[1][1][n] = lrint(-0.35 * (1 << 14));

        coeff[1][2][n] = lrint(0.5 * (1 << 14));

        coeff[2][0][n] = lrint(0.5 * (1 << 14));

        coeff[2][1][n] = lrint(-0.42 * (1 << 14));

        coeff[2][2][n] = lrint(-0.08 * (1 << 14));

    }

    for (odepth = 0; odepth < 3; odepth++) {

        for (fmt = 0; fmt < 3; fmt++) {

            if (check_func(dsp.rgb2yuv[odepth][fmt],

                           "ff_colorspacedsp_rgb2yuv_%sp%d",

                           format_string[fmt], odepth * 2 + 8)) {

                int ss_w = !!fmt, ss_h = fmt == 2;

                int y_dst_stride = W << !!odepth;

                int uv_dst_stride = y_dst_stride >> ss_w;



                randomize_buffers();

                call_ref(dst0, (ptrdiff_t[3]) { y_dst_stride, uv_dst_stride, uv_dst_stride },

                         src, W, W, H, coeff, offset);

                call_new(dst1, (ptrdiff_t[3]) { y_dst_stride, uv_dst_stride, uv_dst_stride },

                         src, W, W, H, coeff, offset);

                if (memcmp(dst0[0], dst1[0], H * y_dst_stride) ||

                    memcmp(dst0[1], dst1[1], H * uv_dst_stride >> ss_h) ||

                    memcmp(dst0[2], dst1[2], H * uv_dst_stride >> ss_h)) {

                    fail();

                }

            }

        }

    }



    report("rgb2yuv");

}

flac_header (AVFormatContext * s, int idx)

{

    struct ogg *ogg = s->priv_data;

    struct ogg_stream *os = ogg->streams + idx;

    AVStream *st = s->streams[idx];

    GetBitContext gb;

    FLACStreaminfo si;

    int mdt;



    if (os->buf[os->pstart] == 0xff)

        return 0;



    init_get_bits(&gb, os->buf + os->pstart, os->psize*8);

    skip_bits1(&gb); /* metadata_last */

    mdt = get_bits(&gb, 7);



    if (mdt == OGG_FLAC_METADATA_TYPE_STREAMINFO) {

        uint8_t *streaminfo_start = os->buf + os->pstart + 5 + 4 + 4 + 4;

        skip_bits_long(&gb, 4*8); /* "FLAC" */

        if(get_bits(&gb, 8) != 1) /* unsupported major version */

            return -1;

        skip_bits_long(&gb, 8 + 16); /* minor version + header count */

        skip_bits_long(&gb, 4*8); /* "fLaC" */



        /* METADATA_BLOCK_HEADER */

        if (get_bits_long(&gb, 32) != FLAC_STREAMINFO_SIZE)

            return -1;



        avpriv_flac_parse_streaminfo(st->codec, &si, streaminfo_start);



        st->codec->codec_type = AVMEDIA_TYPE_AUDIO;

        st->codec->codec_id = AV_CODEC_ID_FLAC;

        st->need_parsing = AVSTREAM_PARSE_HEADERS;



        ff_alloc_extradata(st->codec, FLAC_STREAMINFO_SIZE);

        memcpy(st->codec->extradata, streaminfo_start, st->codec->extradata_size);



        avpriv_set_pts_info(st, 64, 1, st->codec->sample_rate);

    } else if (mdt == FLAC_METADATA_TYPE_VORBIS_COMMENT) {

        ff_vorbis_comment (s, &st->metadata, os->buf + os->pstart + 4, os->psize - 4);

    }



    return 1;

}

static int decode_i_picture_header(VC9Context *v)

{

  int pqindex, status = 0, ac_pred, condover;



    /* Prolog common to all frametypes should be done in caller */

    //BF = Buffer Fullness

    if (v->profile <= PROFILE_MAIN && get_bits(&v->gb, 7))

    {

        av_log(v, AV_LOG_DEBUG, "I BufferFullness not 0\n");

    }



    /* Quantizer stuff */

    pqindex = get_bits(&v->gb, 5);

    if (v->quantizer_mode == QUANT_FRAME_IMPLICIT)

        v->pq = pquant_table[0][pqindex];

    else

    {

        v->pq = pquant_table[v->quantizer_mode-1][pqindex];

    }

    if (pqindex < 9) v->halfpq = get_bits(&v->gb, 1);

    if (v->quantizer_mode == QUANT_FRAME_EXPLICIT)

        v->pquantizer = get_bits(&v->gb, 1);

    av_log(v->avctx, AV_LOG_DEBUG, "I frame: QP=%i (+%i/2)\n",

           v->pq, v->halfpq);

#if HAS_ADVANCED_PROFILE

    if (v->profile <= PROFILE_MAIN)

#endif

    {

        if (v->extended_mv) v->mvrange = get_prefix(&v->gb, 0, 3);

        if (v->multires) v->respic = get_bits(&v->gb, 2);

    }

#if HAS_ADVANCED_PROFILE

    else

    {

        ac_pred = get_bits(&v->gb, 1);

        if (v->postprocflag) v->postproc = get_bits(&v->gb, 1);

        /* 7.1.1.34 + 8.5.2 */

        if (v->overlap && v->pq<9)

        {

            condover = get_bits(&v->gb, 1);

            if (condover)

            {

                condover = 2+get_bits(&v->gb, 1);

                if (condover == 3)

                    status = bitplane_decoding(v->over_flags_plane,

                                                   v->width_mb, v->height_mb, v);

            }

        }

    }

#endif



    /* Epilog should be done in caller */

    return status;

}

static char *time_value_string(char *buf, int buf_size, int64_t val, const AVRational *time_base)

{

    if (val == AV_NOPTS_VALUE) {

        snprintf(buf, buf_size, "N/A");

    } else {

        double d = val * av_q2d(*time_base);

        value_string(buf, buf_size, (struct unit_value){.val.d=d, .unit=unit_second_str});

    }



    return buf;

}

static int read_sbr_single_channel_element(AACContext *ac,

                                            SpectralBandReplication *sbr,

                                            GetBitContext *gb)

{

    int ret;



    if (get_bits1(gb)) // bs_data_extra

        skip_bits(gb, 4); // bs_reserved



    if (read_sbr_grid(ac, sbr, gb, &sbr->data[0]))

        return -1;

    read_sbr_dtdf(sbr, gb, &sbr->data[0]);

    read_sbr_invf(sbr, gb, &sbr->data[0]);

    read_sbr_envelope(sbr, gb, &sbr->data[0], 0);

    if((ret = read_sbr_noise(ac, sbr, gb, &sbr->data[0], 0)) < 0)

        return ret;



    if ((sbr->data[0].bs_add_harmonic_flag = get_bits1(gb)))

        get_bits1_vector(gb, sbr->data[0].bs_add_harmonic, sbr->n[1]);



    return 0;

}

