static int tak_parse(AVCodecParserContext *s, AVCodecContext *avctx,

                     const uint8_t **poutbuf, int *poutbuf_size,

                     const uint8_t *buf, int buf_size)

{

    TAKParseContext *t = s->priv_data;

    ParseContext *pc = &t->pc;

    int next = END_NOT_FOUND;

    GetBitContext gb;

    int consumed = 0;

    int needed = buf_size ? TAK_MAX_FRAME_HEADER_BYTES : 8;



    if (s->flags & PARSER_FLAG_COMPLETE_FRAMES) {

        TAKStreamInfo ti;

        init_get_bits(&gb, buf, buf_size);

        if (!ff_tak_decode_frame_header(avctx, &gb, &ti, 127))

            s->duration = t->ti.last_frame_samples ? t->ti.last_frame_samples :

                                                     t->ti.frame_samples;

        *poutbuf      = buf;

        *poutbuf_size = buf_size;

        return buf_size;

    }



    while (buf_size || t->index + needed <= pc->index) {

        if (buf_size && t->index + TAK_MAX_FRAME_HEADER_BYTES > pc->index) {

            int tmp_buf_size = FFMIN(2 * TAK_MAX_FRAME_HEADER_BYTES, buf_size);

            const uint8_t *tmp_buf = buf;



            ff_combine_frame(pc, END_NOT_FOUND, &tmp_buf, &tmp_buf_size);

            consumed += tmp_buf_size;

            buf      += tmp_buf_size;

            buf_size -= tmp_buf_size;

        }



        for (; t->index + needed <= pc->index; t->index++) {

            if (pc->buffer[ t->index     ] == 0xFF &&

                pc->buffer[ t->index + 1 ] == 0xA0) {

                TAKStreamInfo ti;



                init_get_bits(&gb, pc->buffer + t->index,

                              8 * (pc->index - t->index));

                if (!ff_tak_decode_frame_header(avctx, &gb,

                        pc->frame_start_found ? &ti : &t->ti, 127) &&

                    !ff_tak_check_crc(pc->buffer + t->index,

                                      get_bits_count(&gb) / 8)) {

                    if (!pc->frame_start_found) {

                        pc->frame_start_found = 1;

                        s->duration = t->ti.last_frame_samples ?

                                      t->ti.last_frame_samples :

                                      t->ti.frame_samples;

                    } else {

                        pc->frame_start_found = 0;

                        next = t->index - pc->index;

                        t->index = 0;

                        goto found;

                    }

                }

            }

        }

    }

found:



    if (consumed && !buf_size && next == END_NOT_FOUND ||

        ff_combine_frame(pc, next, &buf, &buf_size) < 0) {

        *poutbuf      = NULL;

        *poutbuf_size = 0;

        return buf_size + consumed;

    }



    if (next != END_NOT_FOUND) {

        next += consumed;

        pc->overread = FFMAX(0, -next);

    }



    *poutbuf      = buf;

    *poutbuf_size = buf_size;

    return next;

}

static int gif_read_header(AVFormatContext * s1,

                           AVFormatParameters * ap)

{

    GifState *s = s1->priv_data;

    ByteIOContext *f = s1->pb;

    AVStream *st;



    s->f = f;

    if (gif_read_header1(s) < 0)

        return -1;



    /* allocate image buffer */

    s->image_linesize = s->screen_width * 3;

    s->image_buf = av_malloc(s->screen_height * s->image_linesize);

    if (!s->image_buf)

        return AVERROR(ENOMEM);

    s->pix_fmt = PIX_FMT_RGB24;

    /* now we are ready: build format streams */

    st = av_new_stream(s1, 0);

    if (!st)

        return -1;



    st->codec->codec_type = CODEC_TYPE_VIDEO;

    st->codec->codec_id = CODEC_ID_RAWVIDEO;

    st->codec->time_base.den = 5;

    st->codec->time_base.num = 1;

    /* XXX: check if screen size is always valid */

    st->codec->width = s->screen_width;

    st->codec->height = s->screen_height;

    st->codec->pix_fmt = PIX_FMT_RGB24;

    return 0;

}

static int decode_frame_common(AVCodecContext *avctx, PNGDecContext *s,

                               AVFrame *p, AVPacket *avpkt)

{

    AVDictionary **metadatap = NULL;

    uint32_t tag, length;

    int decode_next_dat = 0;

    int ret;



    for (;;) {

        length = bytestream2_get_bytes_left(&s->gb);

        if (length <= 0) {



            if (avctx->codec_id == AV_CODEC_ID_PNG &&

                avctx->skip_frame == AVDISCARD_ALL) {

                return 0;

            }



            if (CONFIG_APNG_DECODER && avctx->codec_id == AV_CODEC_ID_APNG && length == 0) {

                if (!(s->pic_state & PNG_IDAT))

                    return 0;

                else

                    goto exit_loop;

            }

            av_log(avctx, AV_LOG_ERROR, "%d bytes left\n", length);

            if (   s->pic_state & PNG_ALLIMAGE

                && avctx->strict_std_compliance <= FF_COMPLIANCE_NORMAL)

                goto exit_loop;

            ret = AVERROR_INVALIDDATA;

            goto fail;

        }



        length = bytestream2_get_be32(&s->gb);

        if (length > 0x7fffffff || length > bytestream2_get_bytes_left(&s->gb)) {

            av_log(avctx, AV_LOG_ERROR, "chunk too big\n");

            ret = AVERROR_INVALIDDATA;

            goto fail;

        }

        tag = bytestream2_get_le32(&s->gb);

        if (avctx->debug & FF_DEBUG_STARTCODE)

            av_log(avctx, AV_LOG_DEBUG, "png: tag=%s length=%u\n",

                   av_fourcc2str(tag), length);



        if (avctx->codec_id == AV_CODEC_ID_PNG &&

            avctx->skip_frame == AVDISCARD_ALL) {

            switch(tag) {

            case MKTAG('I', 'H', 'D', 'R'):

            case MKTAG('p', 'H', 'Y', 's'):

            case MKTAG('t', 'E', 'X', 't'):

            case MKTAG('I', 'D', 'A', 'T'):

            case MKTAG('t', 'R', 'N', 'S'):

                break;

            default:

                goto skip_tag;

            }

        }



        metadatap = &p->metadata;

        switch (tag) {

        case MKTAG('I', 'H', 'D', 'R'):

            if ((ret = decode_ihdr_chunk(avctx, s, length)) < 0)

                goto fail;

            break;

        case MKTAG('p', 'H', 'Y', 's'):

            if ((ret = decode_phys_chunk(avctx, s)) < 0)

                goto fail;

            break;

        case MKTAG('f', 'c', 'T', 'L'):

            if (!CONFIG_APNG_DECODER || avctx->codec_id != AV_CODEC_ID_APNG)

                goto skip_tag;

            if ((ret = decode_fctl_chunk(avctx, s, length)) < 0)

                goto fail;

            decode_next_dat = 1;

            break;

        case MKTAG('f', 'd', 'A', 'T'):

            if (!CONFIG_APNG_DECODER || avctx->codec_id != AV_CODEC_ID_APNG)

                goto skip_tag;

            if (!decode_next_dat) {

                ret = AVERROR_INVALIDDATA;

                goto fail;

            }

            bytestream2_get_be32(&s->gb);

            length -= 4;

            /* fallthrough */

        case MKTAG('I', 'D', 'A', 'T'):

            if (CONFIG_APNG_DECODER && avctx->codec_id == AV_CODEC_ID_APNG && !decode_next_dat)

                goto skip_tag;

            if ((ret = decode_idat_chunk(avctx, s, length, p)) < 0)

                goto fail;

            break;

        case MKTAG('P', 'L', 'T', 'E'):

            if (decode_plte_chunk(avctx, s, length) < 0)

                goto skip_tag;

            break;

        case MKTAG('t', 'R', 'N', 'S'):

            if (decode_trns_chunk(avctx, s, length) < 0)

                goto skip_tag;

            break;

        case MKTAG('t', 'E', 'X', 't'):

            if (decode_text_chunk(s, length, 0, metadatap) < 0)

                av_log(avctx, AV_LOG_WARNING, "Broken tEXt chunk\n");

            bytestream2_skip(&s->gb, length + 4);

            break;

        case MKTAG('z', 'T', 'X', 't'):

            if (decode_text_chunk(s, length, 1, metadatap) < 0)

                av_log(avctx, AV_LOG_WARNING, "Broken zTXt chunk\n");

            bytestream2_skip(&s->gb, length + 4);

            break;

        case MKTAG('s', 'T', 'E', 'R'): {

            int mode = bytestream2_get_byte(&s->gb);

            AVStereo3D *stereo3d = av_stereo3d_create_side_data(p);

            if (!stereo3d)

                goto fail;



            if (mode == 0 || mode == 1) {

                stereo3d->type  = AV_STEREO3D_SIDEBYSIDE;

                stereo3d->flags = mode ? 0 : AV_STEREO3D_FLAG_INVERT;

            } else {

                 av_log(avctx, AV_LOG_WARNING,

                        "Unknown value in sTER chunk (%d)\n", mode);

            }

            bytestream2_skip(&s->gb, 4); /* crc */

            break;

        }

        case MKTAG('i', 'C', 'C', 'P'): {

            if (decode_iccp_chunk(s, length, p) < 0)

                goto fail;

            break;

        }

        case MKTAG('I', 'E', 'N', 'D'):

            if (!(s->pic_state & PNG_ALLIMAGE))

                av_log(avctx, AV_LOG_ERROR, "IEND without all image\n");

            if (!(s->pic_state & (PNG_ALLIMAGE|PNG_IDAT))) {

                ret = AVERROR_INVALIDDATA;

                goto fail;

            }

            bytestream2_skip(&s->gb, 4); /* crc */

            goto exit_loop;

        default:

            /* skip tag */

skip_tag:

            bytestream2_skip(&s->gb, length + 4);

            break;

        }

    }

exit_loop:



    if (avctx->codec_id == AV_CODEC_ID_PNG &&

        avctx->skip_frame == AVDISCARD_ALL) {

        return 0;

    }



    if (s->bits_per_pixel <= 4)

        handle_small_bpp(s, p);



    /* apply transparency if needed */

    if (s->has_trns && s->color_type != PNG_COLOR_TYPE_PALETTE) {

        size_t byte_depth = s->bit_depth > 8 ? 2 : 1;

        size_t raw_bpp = s->bpp - byte_depth;

        unsigned x, y;



        av_assert0(s->bit_depth > 1);



        for (y = 0; y < s->height; ++y) {

            uint8_t *row = &s->image_buf[s->image_linesize * y];



            /* since we're updating in-place, we have to go from right to left */

            for (x = s->width; x > 0; --x) {

                uint8_t *pixel = &row[s->bpp * (x - 1)];

                memmove(pixel, &row[raw_bpp * (x - 1)], raw_bpp);



                if (!memcmp(pixel, s->transparent_color_be, raw_bpp)) {

                    memset(&pixel[raw_bpp], 0, byte_depth);

                } else {

                    memset(&pixel[raw_bpp], 0xff, byte_depth);

                }

            }

        }

    }



    /* handle P-frames only if a predecessor frame is available */

    if (s->last_picture.f->data[0]) {

        if (   !(avpkt->flags & AV_PKT_FLAG_KEY) && avctx->codec_tag != AV_RL32("MPNG")

            && s->last_picture.f->width == p->width

            && s->last_picture.f->height== p->height

            && s->last_picture.f->format== p->format

         ) {

            if (CONFIG_PNG_DECODER && avctx->codec_id != AV_CODEC_ID_APNG)

                handle_p_frame_png(s, p);

            else if (CONFIG_APNG_DECODER &&

                     avctx->codec_id == AV_CODEC_ID_APNG &&

                     (ret = handle_p_frame_apng(avctx, s, p)) < 0)

                goto fail;

        }

    }

    ff_thread_report_progress(&s->picture, INT_MAX, 0);

    ff_thread_report_progress(&s->previous_picture, INT_MAX, 0);



    return 0;



fail:

    ff_thread_report_progress(&s->picture, INT_MAX, 0);

    ff_thread_report_progress(&s->previous_picture, INT_MAX, 0);

    return ret;

}

static int sync(AVFormatContext *s, int64_t *timestamp, int *flags, int *stream_index, int64_t *pos){

    RMDemuxContext *rm = s->priv_data;

    ByteIOContext *pb = s->pb;

    int len, num, res, i;

    AVStream *st;

    uint32_t state=0xFFFFFFFF;



    while(!url_feof(pb)){

        *pos= url_ftell(pb) - 3;

        if(rm->remaining_len > 0){

            num= rm->current_stream;

            len= rm->remaining_len;

            *timestamp = AV_NOPTS_VALUE;

            *flags= 0;

        }else{

            state= (state<<8) + get_byte(pb);



            if(state == MKBETAG('I', 'N', 'D', 'X')){

                int n_pkts, expected_len;

                len = get_be32(pb);

                url_fskip(pb, 2);

                n_pkts = get_be32(pb);

                expected_len = 20 + n_pkts * 14;

                if (len == 20)

                    /* some files don't add index entries to chunk size... */

                    len = expected_len;

                else if (len != expected_len)

                    av_log(s, AV_LOG_WARNING,

                           "Index size %d (%d pkts) is wrong, should be %d.\n",

                           len, n_pkts, expected_len);

                len -= 14; // we already read part of the index header

                if(len<0)

                    continue;

                goto skip;

            }



            if(state > (unsigned)0xFFFF || state < 12)

                continue;

            len=state;

            state= 0xFFFFFFFF;



            num = get_be16(pb);

            *timestamp = get_be32(pb);

            res= get_byte(pb); /* reserved */

            *flags = get_byte(pb); /* flags */





            len -= 12;

        }

        for(i=0;i<s->nb_streams;i++) {

            st = s->streams[i];

            if (num == st->id)

                break;

        }

        if (i == s->nb_streams) {

skip:

            /* skip packet if unknown number */

            url_fskip(pb, len);

            rm->remaining_len = 0;

            continue;

        }

        *stream_index= i;



        return len;

    }

    return -1;

}

static int config_props(AVFilterLink *link)

{

    UnsharpContext *unsharp = link->dst->priv;

    const AVPixFmtDescriptor *desc = av_pix_fmt_desc_get(link->format);



    unsharp->hsub = desc->log2_chroma_w;

    unsharp->vsub = desc->log2_chroma_h;



    init_filter_param(link->dst, &unsharp->luma,   "luma",   link->w);

    init_filter_param(link->dst, &unsharp->chroma, "chroma", SHIFTUP(link->w, unsharp->hsub));



    return 0;

}

static int64_t wav_seek_tag(AVIOContext *s, int64_t offset, int whence)

{

    offset += offset < INT64_MAX && offset & 1;



    return avio_seek(s, offset, whence);

}

static int av_seek_frame_generic(AVFormatContext *s, 

                                 int stream_index, int64_t timestamp)

{

    int index;

    AVStream *st;

    AVIndexEntry *ie;



    if (!s->index_built) {

        if (is_raw_stream(s)) {

            av_build_index_raw(s);

        } else {

            return -1;

        }

        s->index_built = 1;

    }



    if (stream_index < 0)

        stream_index = 0;

    st = s->streams[stream_index];

    index = index_search_timestamp(st->index_entries, st->nb_index_entries,

                                   timestamp);

    if (index < 0)

        return -1;



    /* now we have found the index, we can seek */

    ie = &st->index_entries[index];

    av_read_frame_flush(s);

    url_fseek(&s->pb, ie->pos, SEEK_SET);

    st->cur_dts = ie->timestamp;

    return 0;

}

static int mxf_read_index_table_segment(void *arg, AVIOContext *pb, int tag, int size, UID uid)

{

    MXFIndexTableSegment *segment = arg;

    switch(tag) {

    case 0x3F05:

        segment->edit_unit_byte_count = avio_rb32(pb);

        av_dlog(NULL, "EditUnitByteCount %d\n", segment->edit_unit_byte_count);

        break;

    case 0x3F06:

        segment->index_sid = avio_rb32(pb);

        av_dlog(NULL, "IndexSID %d\n", segment->index_sid);

        break;

    case 0x3F07:

        segment->body_sid = avio_rb32(pb);

        av_dlog(NULL, "BodySID %d\n", segment->body_sid);

        break;

    case 0x3F08:

        segment->slice_count = avio_r8(pb);

        av_dlog(NULL, "SliceCount %d\n", segment->slice_count);

        break;

    case 0x3F09:

        av_dlog(NULL, "DeltaEntryArray found\n");

        return mxf_read_delta_entry_array(pb, segment);

    case 0x3F0A:

        av_dlog(NULL, "IndexEntryArray found\n");

        return mxf_read_index_entry_array(pb, segment);

    case 0x3F0B:

        segment->index_edit_rate.num = avio_rb32(pb);

        segment->index_edit_rate.den = avio_rb32(pb);

        av_dlog(NULL, "IndexEditRate %d/%d\n", segment->index_edit_rate.num,

                segment->index_edit_rate.den);

        break;

    case 0x3F0C:

        segment->index_start_position = avio_rb64(pb);

        av_dlog(NULL, "IndexStartPosition %"PRId64"\n", segment->index_start_position);

        break;

    case 0x3F0D:

        segment->index_duration = avio_rb64(pb);

        av_dlog(NULL, "IndexDuration %"PRId64"\n", segment->index_duration);

        break;

    }

    return 0;

}

static int mov_write_video_tag(AVIOContext *pb, MOVMuxContext *mov, MOVTrack *track)

{

    int64_t pos = avio_tell(pb);

    char compressor_name[32] = { 0 };



    avio_wb32(pb, 0); /* size */

    avio_wl32(pb, track->tag); // store it byteswapped

    avio_wb32(pb, 0); /* Reserved */

    avio_wb16(pb, 0); /* Reserved */

    avio_wb16(pb, 1); /* Data-reference index */



    avio_wb16(pb, 0); /* Codec stream version */

    avio_wb16(pb, 0); /* Codec stream revision (=0) */

    if (track->mode == MODE_MOV) {

        ffio_wfourcc(pb, "FFMP"); /* Vendor */

        if (track->enc->codec_id == AV_CODEC_ID_RAWVIDEO) {

            avio_wb32(pb, 0); /* Temporal Quality */

            avio_wb32(pb, 0x400); /* Spatial Quality = lossless*/

        } else {

            avio_wb32(pb, 0x200); /* Temporal Quality = normal */

            avio_wb32(pb, 0x200); /* Spatial Quality = normal */

        }

    } else {

        avio_wb32(pb, 0); /* Reserved */

        avio_wb32(pb, 0); /* Reserved */

        avio_wb32(pb, 0); /* Reserved */

    }

    avio_wb16(pb, track->enc->width); /* Video width */

    avio_wb16(pb, track->height); /* Video height */

    avio_wb32(pb, 0x00480000); /* Horizontal resolution 72dpi */

    avio_wb32(pb, 0x00480000); /* Vertical resolution 72dpi */

    avio_wb32(pb, 0); /* Data size (= 0) */

    avio_wb16(pb, 1); /* Frame count (= 1) */



    /* FIXME not sure, ISO 14496-1 draft where it shall be set to 0 */

    find_compressor(compressor_name, 32, track);

    avio_w8(pb, strlen(compressor_name));

    avio_write(pb, compressor_name, 31);



    if (track->mode == MODE_MOV && track->enc->bits_per_coded_sample)

        avio_wb16(pb, track->enc->bits_per_coded_sample);

    else

        avio_wb16(pb, 0x18); /* Reserved */

    avio_wb16(pb, 0xffff); /* Reserved */

    if (track->tag == MKTAG('m','p','4','v'))

        mov_write_esds_tag(pb, track);

    else if (track->enc->codec_id == AV_CODEC_ID_H263)

        mov_write_d263_tag(pb);

    else if (track->enc->codec_id == AV_CODEC_ID_AVUI ||

            track->enc->codec_id == AV_CODEC_ID_SVQ3) {

        mov_write_extradata_tag(pb, track);

        avio_wb32(pb, 0);

    } else if (track->enc->codec_id == AV_CODEC_ID_DNXHD)

        mov_write_avid_tag(pb, track);

    else if (track->enc->codec_id == AV_CODEC_ID_HEVC)

        mov_write_hvcc_tag(pb, track);

    else if (track->enc->codec_id == AV_CODEC_ID_H264 && !TAG_IS_AVCI(track->tag)) {

        mov_write_avcc_tag(pb, track);

        if (track->mode == MODE_IPOD)

            mov_write_uuid_tag_ipod(pb);

    } else if (track->enc->codec_id == AV_CODEC_ID_VC1 && track->vos_len > 0)

        mov_write_dvc1_tag(pb, track);

    else if (track->enc->codec_id == AV_CODEC_ID_VP6F ||

             track->enc->codec_id == AV_CODEC_ID_VP6A) {

        /* Don't write any potential extradata here - the cropping

         * is signalled via the normal width/height fields. */

    } else if (track->enc->codec_id == AV_CODEC_ID_R10K) {

        if (track->enc->codec_tag == MKTAG('R','1','0','k'))

            mov_write_dpxe_tag(pb, track);

    } else if (track->vos_len > 0)

        mov_write_glbl_tag(pb, track);



    if (track->enc->codec_id != AV_CODEC_ID_H264 &&

        track->enc->codec_id != AV_CODEC_ID_MPEG4 &&

        track->enc->codec_id != AV_CODEC_ID_DNXHD)

        if (track->enc->field_order != AV_FIELD_UNKNOWN)

            mov_write_fiel_tag(pb, track);



    if (mov->flags & FF_MOV_FLAG_WRITE_COLR)

        mov_write_colr_tag(pb, track);



    if (track->enc->sample_aspect_ratio.den && track->enc->sample_aspect_ratio.num &&

        track->enc->sample_aspect_ratio.den != track->enc->sample_aspect_ratio.num) {

        mov_write_pasp_tag(pb, track);

    }



    return update_size(pb, pos);

}

D(float, sse)

