                    fprintf(stderr, "illegal vlc code in ESC3 level=%d\n", level);

                else if((i>62 && i<192) || i>192+63)

                    fprintf(stderr, "run overflow in ESC3 i=%d run=%d level=%d\n", i, run, level);

#endif

                } else {

                    /* second escape */

#if MIN_CACHE_BITS < 23

                    LAST_SKIP_BITS(re, &s->gb, 2);

                    UPDATE_CACHE(re, &s->gb);

#else

                    SKIP_BITS(re, &s->gb, 2);

#endif

                    GET_RL_VLC(level, run, re, &s->gb, rl_vlc, TEX_VLC_BITS, 2);

                    i+= run + rl->max_run[run>>7][level/qmul] + run_diff; //FIXME opt indexing

                    level = (level ^ SHOW_SBITS(re, &s->gb, 1)) - SHOW_SBITS(re, &s->gb, 1);

                    LAST_SKIP_BITS(re, &s->gb, 1);

#ifdef ERROR_DETAILS

                if(run==66)

                    fprintf(stderr, "illegal vlc code in ESC2 level=%d\n", level);

                else if((i>62 && i<192) || i>192+63)

                    fprintf(stderr, "run overflow in ESC2 i=%d run=%d level=%d\n", i, run, level);

#endif

                }

            } else {

                /* first escape */

#if MIN_CACHE_BITS < 22

                LAST_SKIP_BITS(re, &s->gb, 1);

                UPDATE_CACHE(re, &s->gb);

#else

                SKIP_BITS(re, &s->gb, 1);

#endif

                GET_RL_VLC(level, run, re, &s->gb, rl_vlc, TEX_VLC_BITS, 2);

                i+= run;

                level = level + rl->max_level[run>>7][(run-1)&63] * qmul;//FIXME opt indexing

                level = (level ^ SHOW_SBITS(re, &s->gb, 1)) - SHOW_SBITS(re, &s->gb, 1);

                LAST_SKIP_BITS(re, &s->gb, 1);

#ifdef ERROR_DETAILS

                if(run==66)

                    fprintf(stderr, "illegal vlc code in ESC1 level=%d\n", level);

                else if((i>62 && i<192) || i>192+63)

                    fprintf(stderr, "run overflow in ESC1 i=%d run=%d level=%d\n", i, run, level);

#endif

            }

        } else {

            i+= run;

            level = (level ^ SHOW_SBITS(re, &s->gb, 1)) - SHOW_SBITS(re, &s->gb, 1);

            LAST_SKIP_BITS(re, &s->gb, 1);

#ifdef ERROR_DETAILS

                if(run==66)

                    fprintf(stderr, "illegal vlc code level=%d\n", level);

                else if((i>62 && i<192) || i>192+63)

                    fprintf(stderr, "run overflow i=%d run=%d level=%d\n", i, run, level);

#endif

        }

        if (i > 62){

            i-= 192;

            if(i&(~63)){

                if(i+192 == 64 && level/qmul==-1){

                    fprintf(stderr, "ignoring overflow at %d %d\n", s->mb_x, s->mb_y);

                    break;

                }else{

                    fprintf(stderr, "ac-tex damaged at %d %d\n", s->mb_x, s->mb_y);

                    return -1;

                }

            }



            block[scan_table[i]] = level;

            break;

        }



        block[scan_table[i]] = level;

    }

    CLOSE_READER(re, &s->gb);

  }

 not_coded:

    if (s->mb_intra) {

        mpeg4_pred_ac(s, block, n, dc_pred_dir);

        if (s->ac_pred) {

            i = 63; /* XXX: not optimal */

        }

    }

    if(s->msmpeg4_version==4 && i>0) i=63; //FIXME/XXX optimize

    s->block_last_index[n] = i;



    return 0;

}

static void revert_acfilter(WmallDecodeCtx *s, int tile_size)

{

    int ich, pred, i, j;

    int16_t *filter_coeffs = s->acfilter_coeffs;

    int scaling            = s->acfilter_scaling;

    int order              = s->acfilter_order;



    for (ich = 0; ich < s->num_channels; ich++) {

        int *prevvalues = s->acfilter_prevvalues[ich];

        for (i = 0; i < order; i++) {

            pred = 0;

            for (j = 0; j < order; j++) {

                if (i <= j)

                    pred += filter_coeffs[j] * prevvalues[j - i];

                else

                    pred += s->channel_residues[ich][i - j - 1] * filter_coeffs[j];

            }

            pred >>= scaling;

            s->channel_residues[ich][i] += pred;

        }

        for (i = order; i < tile_size; i++) {

            pred = 0;

            for (j = 0; j < order; j++)

                pred += s->channel_residues[ich][i - j - 1] * filter_coeffs[j];

            pred >>= scaling;

            s->channel_residues[ich][i] += pred;

        }

        for (j = 0; j < order; j++)

            prevvalues[j] = s->channel_residues[ich][tile_size - j - 1];

    }

}

static int mp3_write_xing(AVFormatContext *s)

{

    MP3Context       *mp3 = s->priv_data;

    AVCodecContext *codec = s->streams[mp3->audio_stream_idx]->codec;

    AVDictionaryEntry *enc = av_dict_get(s->streams[mp3->audio_stream_idx]->metadata, "encoder", NULL, 0);

    AVIOContext *dyn_ctx;

    int32_t        header;

    MPADecodeHeader  mpah;

    int srate_idx, i, channels;

    int bitrate_idx;

    int best_bitrate_idx = -1;

    int best_bitrate_error = INT_MAX;

    int ret;

    int ver = 0;

    int bytes_needed;



    if (!s->pb->seekable || !mp3->write_xing)

        return 0;



    for (i = 0; i < FF_ARRAY_ELEMS(avpriv_mpa_freq_tab); i++) {

        const uint16_t base_freq = avpriv_mpa_freq_tab[i];



        if      (codec->sample_rate == base_freq)     ver = 0x3; // MPEG 1

        else if (codec->sample_rate == base_freq / 2) ver = 0x2; // MPEG 2

        else if (codec->sample_rate == base_freq / 4) ver = 0x0; // MPEG 2.5

        else continue;



        srate_idx = i;

        break;

    }

    if (i == FF_ARRAY_ELEMS(avpriv_mpa_freq_tab)) {

        av_log(s, AV_LOG_WARNING, "Unsupported sample rate, not writing Xing header.\n");

        return -1;

    }



    switch (codec->channels) {

    case 1:  channels = MPA_MONO;                                          break;

    case 2:  channels = MPA_STEREO;                                        break;

    default: av_log(s, AV_LOG_WARNING, "Unsupported number of channels, "

                    "not writing Xing header.\n");

             return -1;

    }



    /* dummy MPEG audio header */

    header  =  0xffU                                 << 24; // sync

    header |= (0x7 << 5 | ver << 3 | 0x1 << 1 | 0x1) << 16; // sync/audio-version/layer 3/no crc*/

    header |= (srate_idx << 2) << 8;

    header |= channels << 6;



    for (bitrate_idx = 1; bitrate_idx < 15; bitrate_idx++) {

        int bit_rate = 1000 * avpriv_mpa_bitrate_tab[ver != 3][3 - 1][bitrate_idx];

        int error    = FFABS(bit_rate - codec->bit_rate);



        if (error < best_bitrate_error) {

            best_bitrate_error = error;

            best_bitrate_idx   = bitrate_idx;

        }

    }

    av_assert0(best_bitrate_idx >= 0);



    for (bitrate_idx = best_bitrate_idx; ; bitrate_idx++) {

        int32_t mask = bitrate_idx << (4 + 8);

        if (15 == bitrate_idx)

            return -1;

        header |= mask;



        avpriv_mpegaudio_decode_header(&mpah, header);

        mp3->xing_offset = xing_offtbl[mpah.lsf == 1][mpah.nb_channels == 1] + 4;

        bytes_needed     = mp3->xing_offset + XING_SIZE;



        if (bytes_needed <= mpah.frame_size)

            break;



        header &= ~mask;

    }



    ret = avio_open_dyn_buf(&dyn_ctx);

    if (ret < 0)

        return ret;



    avio_wb32(dyn_ctx, header);



    ffio_fill(dyn_ctx, 0, mp3->xing_offset - 4);

    ffio_wfourcc(dyn_ctx, "Xing");

    avio_wb32(dyn_ctx, 0x01 | 0x02 | 0x04 | 0x08);  // frames / size / TOC / vbr scale



    mp3->size = mpah.frame_size;

    mp3->want=1;

    mp3->seen=0;

    mp3->pos=0;



    avio_wb32(dyn_ctx, 0);  // frames

    avio_wb32(dyn_ctx, 0);  // size



    // TOC

    for (i = 0; i < XING_TOC_SIZE; i++)

        avio_w8(dyn_ctx, (uint8_t)(255 * i / XING_TOC_SIZE));



    // vbr quality

    // we write it, because some (broken) tools always expect it to be present

    avio_wb32(dyn_ctx, 0);



    // encoder short version string

    if (enc) {

        uint8_t encoder_str[9] = { 0 };

        if (   strlen(enc->value) > sizeof(encoder_str)

            && !strcmp("Lavc libmp3lame", enc->value)) {

            memcpy(encoder_str, "Lavf lame", 9);

        } else

            memcpy(encoder_str, enc->value, FFMIN(strlen(enc->value), sizeof(encoder_str)));



        avio_write(dyn_ctx, encoder_str, sizeof(encoder_str));

    } else

        avio_write(dyn_ctx, "Lavf\0\0\0\0\0", 9);



    avio_w8(dyn_ctx, 0);      // tag revision 0 / unknown vbr method

    avio_w8(dyn_ctx, 0);      // unknown lowpass filter value

    ffio_fill(dyn_ctx, 0, 8); // empty replaygain fields

    avio_w8(dyn_ctx, 0);      // unknown encoding flags

    avio_w8(dyn_ctx, 0);      // unknown abr/minimal bitrate



    // encoder delay

    if (codec->initial_padding - 528 - 1 >= 1 << 12) {

        av_log(s, AV_LOG_WARNING, "Too many samples of initial padding.\n");

    }

    avio_wb24(dyn_ctx, FFMAX(codec->initial_padding - 528 - 1, 0)<<12);



    avio_w8(dyn_ctx,   0); // misc

    avio_w8(dyn_ctx,   0); // mp3gain

    avio_wb16(dyn_ctx, 0); // preset



    // audio length and CRCs (will be updated later)

    avio_wb32(dyn_ctx, 0); // music length

    avio_wb16(dyn_ctx, 0); // music crc

    avio_wb16(dyn_ctx, 0); // tag crc



    ffio_fill(dyn_ctx, 0, mpah.frame_size - bytes_needed);



    mp3->xing_frame_size   = avio_close_dyn_buf(dyn_ctx, &mp3->xing_frame);

    mp3->xing_frame_offset = avio_tell(s->pb);

    avio_write(s->pb, mp3->xing_frame, mp3->xing_frame_size);



    mp3->audio_size = mp3->xing_frame_size;



    return 0;

}

static void dwt_decode97_int(DWTContext *s, int32_t *t)

{

    int lev;

    int w       = s->linelen[s->ndeclevels - 1][0];

    int h       = s->linelen[s->ndeclevels - 1][1];

    int i;

    int32_t *line = s->i_linebuf;

    int32_t *data = t;

    /* position at index O of line range [0-5,w+5] cf. extend function */

    line += 5;



    for (i = 0; i < w * h; i++)

        data[i] *= 1 << I_PRESHIFT;



    for (lev = 0; lev < s->ndeclevels; lev++) {

        int lh = s->linelen[lev][0],

            lv = s->linelen[lev][1],

            mh = s->mod[lev][0],

            mv = s->mod[lev][1],

            lp;

        int32_t *l;

        // HOR_SD

        l = line + mh;

        for (lp = 0; lp < lv; lp++) {

            int i, j = 0;

            // rescale with interleaving

            for (i = mh; i < lh; i += 2, j++)

                l[i] = ((data[w * lp + j] * I_LFTG_K) + (1 << 15)) >> 16;

            for (i = 1 - mh; i < lh; i += 2, j++)

                l[i] = data[w * lp + j];



            sr_1d97_int(line, mh, mh + lh);



            for (i = 0; i < lh; i++)

                data[w * lp + i] = l[i];

        }



        // VER_SD

        l = line + mv;

        for (lp = 0; lp < lh; lp++) {

            int i, j = 0;

            // rescale with interleaving

            for (i = mv; i < lv; i += 2, j++)

                l[i] = ((data[w * j + lp] * I_LFTG_K) + (1 << 15)) >> 16;

            for (i = 1 - mv; i < lv; i += 2, j++)

                l[i] = data[w * j + lp];



            sr_1d97_int(line, mv, mv + lv);



            for (i = 0; i < lv; i++)

                data[w * i + lp] = l[i];

        }

    }



    for (i = 0; i < w * h; i++)

        data[i] = (data[i] + ((1<<I_PRESHIFT)>>1)) >> I_PRESHIFT;

}

static int get_http_header_data(MMSHContext *mmsh)

{

    MMSContext *mms = &mmsh->mms;

    int res, len;

    ChunkType chunk_type;



    for (;;) {

        len = 0;

        res = chunk_type = get_chunk_header(mmsh, &len);

        if (res < 0) {

            return res;

        } else if (chunk_type == CHUNK_TYPE_ASF_HEADER){

            // get asf header and stored it

            if (!mms->header_parsed) {

                if (mms->asf_header) {

                    if (len != mms->asf_header_size) {

                        mms->asf_header_size = len;

                        av_dlog(NULL, "Header len changed from %d to %d\n",

                                mms->asf_header_size, len);

                        av_freep(&mms->asf_header);

                    }

                }

                mms->asf_header = av_mallocz(len);

                if (!mms->asf_header) {

                    return AVERROR(ENOMEM);

                }

                mms->asf_header_size = len;

            }

            if (len > mms->asf_header_size) {

                av_log(NULL, AV_LOG_ERROR,

                       "Asf header packet len = %d exceed the asf header buf size %d\n",

                       len, mms->asf_header_size);

                return AVERROR(EIO);

            }

            res = ffurl_read_complete(mms->mms_hd, mms->asf_header, len);

            if (res != len) {

                av_log(NULL, AV_LOG_ERROR,

                       "Recv asf header data len %d != expected len %d\n", res, len);

                return AVERROR(EIO);

            }

            mms->asf_header_size = len;

            if (!mms->header_parsed) {

                res = ff_mms_asf_header_parser(mms);

                mms->header_parsed = 1;

                return res;

            }

        } else if (chunk_type == CHUNK_TYPE_DATA) {

            // read data packet and do padding

            return read_data_packet(mmsh, len);

        } else {

            if (len) {

                if (len > sizeof(mms->in_buffer)) {

                    av_log(NULL, AV_LOG_ERROR,

                           "Other packet len = %d exceed the in_buffer size %zu\n",

                           len, sizeof(mms->in_buffer));

                    return AVERROR(EIO);

                }

                res = ffurl_read_complete(mms->mms_hd, mms->in_buffer, len);

                if (res != len) {

                    av_log(NULL, AV_LOG_ERROR, "Read other chunk type data failed!\n");

                    return AVERROR(EIO);

                } else {

                    av_dlog(NULL, "Skip chunk type %d \n", chunk_type);

                    continue;

                }

            }

        }

    }

    return 0;

}

static int pnm_decode_frame(AVCodecContext *avctx, void *data,

                            int *data_size, AVPacket *avpkt)

{

    const uint8_t *buf   = avpkt->data;

    int buf_size         = avpkt->size;

    PNMContext * const s = avctx->priv_data;

    AVFrame *picture     = data;

    AVFrame * const p    = (AVFrame*)&s->picture;

    int i, j, n, linesize, h, upgrade = 0;

    unsigned char *ptr;

    int components, sample_len;



    s->bytestream_start =

    s->bytestream       = buf;

    s->bytestream_end   = buf + buf_size;



    if (ff_pnm_decode_header(avctx, s) < 0)

        return -1;



    if (p->data[0])

        avctx->release_buffer(avctx, p);



    p->reference = 0;

    if (avctx->get_buffer(avctx, p) < 0) {

        av_log(avctx, AV_LOG_ERROR, "get_buffer() failed\n");

        return -1;

    }

    p->pict_type = AV_PICTURE_TYPE_I;

    p->key_frame = 1;



    switch (avctx->pix_fmt) {

    default:

        return -1;

    case PIX_FMT_RGB48BE:

        n = avctx->width * 6;

        components=3;

        sample_len=16;

        goto do_read;

    case PIX_FMT_RGB24:

        n = avctx->width * 3;

        components=3;

        sample_len=8;

        goto do_read;

    case PIX_FMT_GRAY8:

        n = avctx->width;

        components=1;

        sample_len=8;

        if (s->maxval < 255)

            upgrade = 1;

        goto do_read;

    case PIX_FMT_GRAY16BE:

    case PIX_FMT_GRAY16LE:

        n = avctx->width * 2;

        components=1;

        sample_len=16;

        if (s->maxval < 65535)

            upgrade = 2;

        goto do_read;

    case PIX_FMT_MONOWHITE:

    case PIX_FMT_MONOBLACK:

        n = (avctx->width + 7) >> 3;

        components=1;

        sample_len=1;

    do_read:

        ptr      = p->data[0];

        linesize = p->linesize[0];

        if (s->bytestream + n * avctx->height > s->bytestream_end)

            return -1;

        if(s->type < 4){

            for (i=0; i<avctx->height; i++) {

                PutBitContext pb;

                init_put_bits(&pb, ptr, linesize);

                for(j=0; j<avctx->width * components; j++){

                    unsigned int c=0;

                    int v=0;

                    while(s->bytestream < s->bytestream_end && (*s->bytestream < '0' || *s->bytestream > '9' ))

                        s->bytestream++;

                    if(s->bytestream >= s->bytestream_end)

                        return -1;

                    do{

                        v= 10*v + c;

                        c= (*s->bytestream++) - '0';

                    }while(c <= 9);

                    put_bits(&pb, sample_len, (((1<<sample_len)-1)*v + (s->maxval>>1))/s->maxval);

                }

                flush_put_bits(&pb);

                ptr+= linesize;

            }

        }else{

        for (i = 0; i < avctx->height; i++) {

            if (!upgrade)

                memcpy(ptr, s->bytestream, n);

            else if (upgrade == 1) {

                unsigned int j, f = (255 * 128 + s->maxval / 2) / s->maxval;

                for (j = 0; j < n; j++)

                    ptr[j] = (s->bytestream[j] * f + 64) >> 7;

            } else if (upgrade == 2) {

                unsigned int j, v, f = (65535 * 32768 + s->maxval / 2) / s->maxval;

                for (j = 0; j < n / 2; j++) {

                    v = av_be2ne16(((uint16_t *)s->bytestream)[j]);

                    ((uint16_t *)ptr)[j] = (v * f + 16384) >> 15;

                }

            }

            s->bytestream += n;

            ptr           += linesize;

        }

        }

        break;

    case PIX_FMT_YUV420P:

        {

            unsigned char *ptr1, *ptr2;



            n        = avctx->width;

            ptr      = p->data[0];

            linesize = p->linesize[0];

            if (s->bytestream + n * avctx->height * 3 / 2 > s->bytestream_end)

                return -1;

            for (i = 0; i < avctx->height; i++) {

                memcpy(ptr, s->bytestream, n);

                s->bytestream += n;

                ptr           += linesize;

            }

            ptr1 = p->data[1];

            ptr2 = p->data[2];

            n >>= 1;

            h = avctx->height >> 1;

            for (i = 0; i < h; i++) {

                memcpy(ptr1, s->bytestream, n);

                s->bytestream += n;

                memcpy(ptr2, s->bytestream, n);

                s->bytestream += n;

                ptr1 += p->linesize[1];

                ptr2 += p->linesize[2];

            }

        }

        break;

    case PIX_FMT_RGB32:

        ptr      = p->data[0];

        linesize = p->linesize[0];

        if (s->bytestream + avctx->width * avctx->height * 4 > s->bytestream_end)

            return -1;

        for (i = 0; i < avctx->height; i++) {

            int j, r, g, b, a;



            for (j = 0; j < avctx->width; j++) {

                r = *s->bytestream++;

                g = *s->bytestream++;

                b = *s->bytestream++;

                a = *s->bytestream++;

                ((uint32_t *)ptr)[j] = (a << 24) | (r << 16) | (g << 8) | b;

            }

            ptr += linesize;

        }

        break;

    }

    *picture   = *(AVFrame*)&s->picture;

    *data_size = sizeof(AVPicture);



    return s->bytestream - s->bytestream_start;

}

static int estimate_best_b_count(MpegEncContext *s)

{

    AVCodec *codec    = avcodec_find_encoder(s->avctx->codec_id);

    AVCodecContext *c = avcodec_alloc_context3(NULL);

    const int scale = s->avctx->brd_scale;

    int i, j, out_size, p_lambda, b_lambda, lambda2;

    int64_t best_rd  = INT64_MAX;

    int best_b_count = -1;



    assert(scale >= 0 && scale <= 3);



    //emms_c();

    //s->next_picture_ptr->quality;

    p_lambda = s->last_lambda_for[AV_PICTURE_TYPE_P];

    //p_lambda * FFABS(s->avctx->b_quant_factor) + s->avctx->b_quant_offset;

    b_lambda = s->last_lambda_for[AV_PICTURE_TYPE_B];

    if (!b_lambda) // FIXME we should do this somewhere else

        b_lambda = p_lambda;

    lambda2  = (b_lambda * b_lambda + (1 << FF_LAMBDA_SHIFT) / 2) >>

               FF_LAMBDA_SHIFT;



    c->width        = s->width  >> scale;

    c->height       = s->height >> scale;

    c->flags        = CODEC_FLAG_QSCALE | CODEC_FLAG_PSNR |

                      CODEC_FLAG_INPUT_PRESERVED;

    c->flags       |= s->avctx->flags & CODEC_FLAG_QPEL;

    c->mb_decision  = s->avctx->mb_decision;

    c->me_cmp       = s->avctx->me_cmp;

    c->mb_cmp       = s->avctx->mb_cmp;

    c->me_sub_cmp   = s->avctx->me_sub_cmp;

    c->pix_fmt      = AV_PIX_FMT_YUV420P;

    c->time_base    = s->avctx->time_base;

    c->max_b_frames = s->max_b_frames;



    if (avcodec_open2(c, codec, NULL) < 0)

        return -1;



    for (i = 0; i < s->max_b_frames + 2; i++) {

        Picture pre_input, *pre_input_ptr = i ? s->input_picture[i - 1] :

                                                s->next_picture_ptr;



        if (pre_input_ptr && (!i || s->input_picture[i - 1])) {

            pre_input = *pre_input_ptr;



            if (!pre_input.shared && i) {

                pre_input.f.data[0] += INPLACE_OFFSET;

                pre_input.f.data[1] += INPLACE_OFFSET;

                pre_input.f.data[2] += INPLACE_OFFSET;

            }



            s->dsp.shrink[scale](s->tmp_frames[i]->data[0], s->tmp_frames[i]->linesize[0],

                                 pre_input.f.data[0], pre_input.f.linesize[0],

                                 c->width,      c->height);

            s->dsp.shrink[scale](s->tmp_frames[i]->data[1], s->tmp_frames[i]->linesize[1],

                                 pre_input.f.data[1], pre_input.f.linesize[1],

                                 c->width >> 1, c->height >> 1);

            s->dsp.shrink[scale](s->tmp_frames[i]->data[2], s->tmp_frames[i]->linesize[2],

                                 pre_input.f.data[2], pre_input.f.linesize[2],

                                 c->width >> 1, c->height >> 1);

        }

    }



    for (j = 0; j < s->max_b_frames + 1; j++) {

        int64_t rd = 0;



        if (!s->input_picture[j])

            break;



        c->error[0] = c->error[1] = c->error[2] = 0;



        s->tmp_frames[0]->pict_type = AV_PICTURE_TYPE_I;

        s->tmp_frames[0]->quality   = 1 * FF_QP2LAMBDA;



        out_size = encode_frame(c, s->tmp_frames[0]);



        //rd += (out_size * lambda2) >> FF_LAMBDA_SHIFT;



        for (i = 0; i < s->max_b_frames + 1; i++) {

            int is_p = i % (j + 1) == j || i == s->max_b_frames;



            s->tmp_frames[i + 1]->pict_type = is_p ?

                                     AV_PICTURE_TYPE_P : AV_PICTURE_TYPE_B;

            s->tmp_frames[i + 1]->quality   = is_p ? p_lambda : b_lambda;



            out_size = encode_frame(c, s->tmp_frames[i + 1]);



            rd += (out_size * lambda2) >> (FF_LAMBDA_SHIFT - 3);

        }



        /* get the delayed frames */

        while (out_size) {

            out_size = encode_frame(c, NULL);

            rd += (out_size * lambda2) >> (FF_LAMBDA_SHIFT - 3);

        }



        rd += c->error[0] + c->error[1] + c->error[2];



        if (rd < best_rd) {

            best_rd = rd;

            best_b_count = j;

        }

    }



    avcodec_close(c);

    av_freep(&c);



    return best_b_count;

}

static int str_read_packet(AVFormatContext *s,

                           AVPacket *ret_pkt)

{

    ByteIOContext *pb = s->pb;

    StrDemuxContext *str = s->priv_data;

    unsigned char sector[RAW_CD_SECTOR_SIZE];

    int channel;

    AVPacket *pkt;

    AVStream *st;



    while (1) {



        if (get_buffer(pb, sector, RAW_CD_SECTOR_SIZE) != RAW_CD_SECTOR_SIZE)

            return AVERROR(EIO);



        channel = sector[0x11];

        if (channel >= 32)

            return AVERROR_INVALIDDATA;



        switch (sector[0x12] & CDXA_TYPE_MASK) {



        case CDXA_TYPE_DATA:

        case CDXA_TYPE_VIDEO:

            {



                int current_sector = AV_RL16(&sector[0x1C]);

                int sector_count   = AV_RL16(&sector[0x1E]);

                int frame_size = AV_RL32(&sector[0x24]);



                if(!(   frame_size>=0

                     && current_sector < sector_count

                     && sector_count*VIDEO_DATA_CHUNK_SIZE >=frame_size)){

                    av_log(s, AV_LOG_ERROR, "Invalid parameters %d %d %d\n", current_sector, sector_count, frame_size);

                    return AVERROR_INVALIDDATA;

                }



                if(str->channels[channel].video_stream_index < 0){

                    /* allocate a new AVStream */

                    st = av_new_stream(s, 0);

                    if (!st)

                        return AVERROR(ENOMEM);

                    av_set_pts_info(st, 64, 1, 15);



                    str->channels[channel].video_stream_index = st->index;



                    st->codec->codec_type = CODEC_TYPE_VIDEO;

                    st->codec->codec_id   = CODEC_ID_MDEC;

                    st->codec->codec_tag  = 0;  /* no fourcc */

                    st->codec->width      = AV_RL16(&sector[0x28]);

                    st->codec->height     = AV_RL16(&sector[0x2A]);

                }



                /* if this is the first sector of the frame, allocate a pkt */

                pkt = &str->channels[channel].tmp_pkt;



                if(pkt->size != sector_count*VIDEO_DATA_CHUNK_SIZE){

                    if(pkt->data)

                        av_log(s, AV_LOG_ERROR, "missmatching sector_count\n");

                    av_free_packet(pkt);

                    if (av_new_packet(pkt, sector_count*VIDEO_DATA_CHUNK_SIZE))

                        return AVERROR(EIO);



                    pkt->pos= url_ftell(pb) - RAW_CD_SECTOR_SIZE;

                    pkt->stream_index =

                        str->channels[channel].video_stream_index;

                }



                memcpy(pkt->data + current_sector*VIDEO_DATA_CHUNK_SIZE,

                       sector + VIDEO_DATA_HEADER_SIZE,

                       VIDEO_DATA_CHUNK_SIZE);



                if (current_sector == sector_count-1) {

                    pkt->size= frame_size;

                    *ret_pkt = *pkt;

                    pkt->data= NULL;

                    pkt->size= -1;

                    return 0;

                }



            }

            break;



        case CDXA_TYPE_AUDIO:

            if(str->channels[channel].audio_stream_index < 0){

                int fmt = sector[0x13];

                /* allocate a new AVStream */

                st = av_new_stream(s, 0);

                if (!st)

                    return AVERROR(ENOMEM);



                str->channels[channel].audio_stream_index = st->index;



                st->codec->codec_type  = CODEC_TYPE_AUDIO;

                st->codec->codec_id    = CODEC_ID_ADPCM_XA;

                st->codec->codec_tag   = 0;  /* no fourcc */

                st->codec->channels    = (fmt&1)?2:1;

                st->codec->sample_rate = (fmt&4)?18900:37800;

            //    st->codec->bit_rate = 0; //FIXME;

                st->codec->block_align = 128;



                av_set_pts_info(st, 64, 128, st->codec->sample_rate);

            }

                pkt = ret_pkt;

                if (av_new_packet(pkt, 2304))

                    return AVERROR(EIO);

                memcpy(pkt->data,sector+24,2304);



                pkt->stream_index =

                    str->channels[channel].audio_stream_index;

                return 0;

            break;

        default:

            /* drop the sector and move on */

            break;

        }



        if (url_feof(pb))

            return AVERROR(EIO);

    }

}

static inline void RENAME(rgb32tobgr24)(const uint8_t *src, uint8_t *dst, long src_size)

{

    uint8_t *dest = dst;

    const uint8_t *s = src;

    const uint8_t *end;

#if COMPILE_TEMPLATE_MMX

    const uint8_t *mm_end;

#endif

    end = s + src_size;

#if COMPILE_TEMPLATE_MMX

    __asm__ volatile(PREFETCH"    %0"::"m"(*s):"memory");

    mm_end = end - 31;

    while (s < mm_end) {

        __asm__ volatile(

            PREFETCH"    32%1           \n\t"

            "movq          %1, %%mm0    \n\t"

            "movq         8%1, %%mm1    \n\t"

            "movq        16%1, %%mm4    \n\t"

            "movq        24%1, %%mm5    \n\t"

            "movq       %%mm0, %%mm2    \n\t"

            "movq       %%mm1, %%mm3    \n\t"

            "movq       %%mm4, %%mm6    \n\t"

            "movq       %%mm5, %%mm7    \n\t"

            STORE_BGR24_MMX

            :"=m"(*dest)

            :"m"(*s)

            :"memory");

        dest += 24;

        s += 32;

    }

    __asm__ volatile(SFENCE:::"memory");

    __asm__ volatile(EMMS:::"memory");

#endif

    while (s < end) {

#if HAVE_BIGENDIAN

        /* RGB32 (= A,B,G,R) -> RGB24 (= R,G,B) */

        s++;

        dest[2] = *s++;

        dest[1] = *s++;

        dest[0] = *s++;

        dest += 3;

#else

        *dest++ = *s++;

        *dest++ = *s++;

        *dest++ = *s++;

        s++;

#endif

    }

}

static void search_for_ms_mips(AACEncContext *s, ChannelElement *cpe)

{

    int start = 0, i, w, w2, g;

    float M[128], S[128];

    float *L34 = s->scoefs, *R34 = s->scoefs + 128, *M34 = s->scoefs + 128*2, *S34 = s->scoefs + 128*3;

    const float lambda = s->lambda;

    SingleChannelElement *sce0 = &cpe->ch[0];

    SingleChannelElement *sce1 = &cpe->ch[1];

    if (!cpe->common_window)

        return;

    for (w = 0; w < sce0->ics.num_windows; w += sce0->ics.group_len[w]) {

        start = 0;

        for (g = 0;  g < sce0->ics.num_swb; g++) {

            if (!cpe->ch[0].zeroes[w*16+g] && !cpe->ch[1].zeroes[w*16+g]) {

                float dist1 = 0.0f, dist2 = 0.0f;

                for (w2 = 0; w2 < sce0->ics.group_len[w]; w2++) {

                    FFPsyBand *band0 = &s->psy.ch[s->cur_channel+0].psy_bands[(w+w2)*16+g];

                    FFPsyBand *band1 = &s->psy.ch[s->cur_channel+1].psy_bands[(w+w2)*16+g];

                    float minthr = FFMIN(band0->threshold, band1->threshold);

                    float maxthr = FFMAX(band0->threshold, band1->threshold);

                    for (i = 0; i < sce0->ics.swb_sizes[g]; i+=4) {

                        M[i  ] = (sce0->coeffs[start+w2*128+i  ]

                                + sce1->coeffs[start+w2*128+i  ]) * 0.5;

                        M[i+1] = (sce0->coeffs[start+w2*128+i+1]

                                + sce1->coeffs[start+w2*128+i+1]) * 0.5;

                        M[i+2] = (sce0->coeffs[start+w2*128+i+2]

                                + sce1->coeffs[start+w2*128+i+2]) * 0.5;

                        M[i+3] = (sce0->coeffs[start+w2*128+i+3]

                                + sce1->coeffs[start+w2*128+i+3]) * 0.5;



                        S[i  ] =  M[i  ]

                                - sce1->coeffs[start+w2*128+i  ];

                        S[i+1] =  M[i+1]

                                - sce1->coeffs[start+w2*128+i+1];

                        S[i+2] =  M[i+2]

                                - sce1->coeffs[start+w2*128+i+2];

                        S[i+3] =  M[i+3]

                                - sce1->coeffs[start+w2*128+i+3];

                   }

                    abs_pow34_v(L34, sce0->coeffs+start+(w+w2)*128, sce0->ics.swb_sizes[g]);

                    abs_pow34_v(R34, sce1->coeffs+start+(w+w2)*128, sce0->ics.swb_sizes[g]);

                    abs_pow34_v(M34, M,                         sce0->ics.swb_sizes[g]);

                    abs_pow34_v(S34, S,                         sce0->ics.swb_sizes[g]);

                    dist1 += quantize_band_cost(s, &sce0->coeffs[start + (w+w2)*128],

                                                L34,

                                                sce0->ics.swb_sizes[g],

                                                sce0->sf_idx[(w+w2)*16+g],

                                                sce0->band_type[(w+w2)*16+g],

                                                lambda / band0->threshold, INFINITY, NULL, NULL, 0);

                    dist1 += quantize_band_cost(s, &sce1->coeffs[start + (w+w2)*128],

                                                R34,

                                                sce1->ics.swb_sizes[g],

                                                sce1->sf_idx[(w+w2)*16+g],

                                                sce1->band_type[(w+w2)*16+g],

                                                lambda / band1->threshold, INFINITY, NULL, NULL, 0);

                    dist2 += quantize_band_cost(s, M,

                                                M34,

                                                sce0->ics.swb_sizes[g],

                                                sce0->sf_idx[(w+w2)*16+g],

                                                sce0->band_type[(w+w2)*16+g],

                                                lambda / maxthr, INFINITY, NULL, NULL, 0);

                    dist2 += quantize_band_cost(s, S,

                                                S34,

                                                sce1->ics.swb_sizes[g],

                                                sce1->sf_idx[(w+w2)*16+g],

                                                sce1->band_type[(w+w2)*16+g],

                                                lambda / minthr, INFINITY, NULL, NULL, 0);

                }

                cpe->ms_mask[w*16+g] = dist2 < dist1;

            }

            start += sce0->ics.swb_sizes[g];

        }

    }

}

