static int decode_packet(AVCodecContext *avctx, void *data,

                         int *got_frame_ptr, AVPacket* avpkt)

{

    WMAProDecodeCtx *s = avctx->priv_data;

    GetBitContext* gb  = &s->pgb;

    const uint8_t* buf = avpkt->data;

    int buf_size       = avpkt->size;

    int num_bits_prev_frame;

    int packet_sequence_number;



    *got_frame_ptr = 0;



    if (s->packet_done || s->packet_loss) {

        s->packet_done = 0;



        /** sanity check for the buffer length */

        if (buf_size < avctx->block_align)

            return 0;



        s->next_packet_start = buf_size - avctx->block_align;

        buf_size = avctx->block_align;

        s->buf_bit_size = buf_size << 3;



        /** parse packet header */

        init_get_bits(gb, buf, s->buf_bit_size);

        packet_sequence_number = get_bits(gb, 4);

        skip_bits(gb, 2);



        /** get number of bits that need to be added to the previous frame */

        num_bits_prev_frame = get_bits(gb, s->log2_frame_size);

        av_dlog(avctx, "packet[%d]: nbpf %x\n", avctx->frame_number,

                num_bits_prev_frame);



        /** check for packet loss */

        if (!s->packet_loss &&

            ((s->packet_sequence_number + 1) & 0xF) != packet_sequence_number) {

            s->packet_loss = 1;

            av_log(avctx, AV_LOG_ERROR, "Packet loss detected! seq %x vs %x\n",

                   s->packet_sequence_number, packet_sequence_number);

        }

        s->packet_sequence_number = packet_sequence_number;



        if (num_bits_prev_frame > 0) {

            int remaining_packet_bits = s->buf_bit_size - get_bits_count(gb);

            if (num_bits_prev_frame >= remaining_packet_bits) {

                num_bits_prev_frame = remaining_packet_bits;

                s->packet_done = 1;

            }



            /** append the previous frame data to the remaining data from the

                previous packet to create a full frame */

            save_bits(s, gb, num_bits_prev_frame, 1);

            av_dlog(avctx, "accumulated %x bits of frame data\n",

                    s->num_saved_bits - s->frame_offset);



            /** decode the cross packet frame if it is valid */

            if (!s->packet_loss)

                decode_frame(s, data, got_frame_ptr);

        } else if (s->num_saved_bits - s->frame_offset) {

            av_dlog(avctx, "ignoring %x previously saved bits\n",

                    s->num_saved_bits - s->frame_offset);

        }



        if (s->packet_loss) {

            /** reset number of saved bits so that the decoder

                does not start to decode incomplete frames in the

                s->len_prefix == 0 case */

            s->num_saved_bits = 0;

            s->packet_loss = 0;

        }



    } else {

        int frame_size;

        s->buf_bit_size = (avpkt->size - s->next_packet_start) << 3;

        init_get_bits(gb, avpkt->data, s->buf_bit_size);

        skip_bits(gb, s->packet_offset);

        if (s->len_prefix && remaining_bits(s, gb) > s->log2_frame_size &&

            (frame_size = show_bits(gb, s->log2_frame_size)) &&

            frame_size <= remaining_bits(s, gb)) {

            save_bits(s, gb, frame_size, 0);

            s->packet_done = !decode_frame(s, data, got_frame_ptr);

        } else if (!s->len_prefix

                   && s->num_saved_bits > get_bits_count(&s->gb)) {

            /** when the frames do not have a length prefix, we don't know

                the compressed length of the individual frames

                however, we know what part of a new packet belongs to the

                previous frame

                therefore we save the incoming packet first, then we append

                the "previous frame" data from the next packet so that

                we get a buffer that only contains full frames */

            s->packet_done = !decode_frame(s, data, got_frame_ptr);

        } else

            s->packet_done = 1;

    }



    if (s->packet_done && !s->packet_loss &&

        remaining_bits(s, gb) > 0) {

        /** save the rest of the data so that it can be decoded

            with the next packet */

        save_bits(s, gb, remaining_bits(s, gb), 0);

    }



    s->packet_offset = get_bits_count(gb) & 7;

    if (s->packet_loss)

        return AVERROR_INVALIDDATA;



    return get_bits_count(gb) >> 3;

}

static int avi_read_packet(AVFormatContext *s, AVPacket *pkt)

{

    AVIContext *avi = s->priv_data;

    ByteIOContext *pb = &s->pb;

    int n, d[8], size;

    offset_t i;

    void* dstr;



    memset(d, -1, sizeof(int)*8);



    if (avi->dv_demux) {

        size = dv_get_packet(avi->dv_demux, pkt);

	if (size >= 0)

	    return size;

    }



    for(i=url_ftell(pb); !url_feof(pb); i++) {

        int j;



	if (i >= avi->movi_end) {

	    if (avi->is_odml) {

		url_fskip(pb, avi->riff_end - i);

	        avi->riff_end = avi->movi_end = url_filesize(url_fileno(pb));

	    } else

	        break;

	}



        for(j=0; j<7; j++)

            d[j]= d[j+1];

        d[7]= get_byte(pb);



        size= d[4] + (d[5]<<8) + (d[6]<<16) + (d[7]<<24);



        //parse ix##

        n= (d[2] - '0') * 10 + (d[3] - '0');

        if(    d[2] >= '0' && d[2] <= '9'

            && d[3] >= '0' && d[3] <= '9'

            && d[0] == 'i' && d[1] == 'x'

            && n < s->nb_streams

            && i + size <= avi->movi_end){



            url_fskip(pb, size);

        }



	//parse JUNK

        if(d[0] == 'J' && d[1] == 'U' && d[2] == 'N' && d[3] == 'K' &&

           i + size <= avi->movi_end) {



            url_fskip(pb, size);

        }



        //parse ##dc/##wb

        n= (d[0] - '0') * 10 + (d[1] - '0');

        if(    d[0] >= '0' && d[0] <= '9'

            && d[1] >= '0' && d[1] <= '9'

            && ((d[2] == 'd' && d[3] == 'c') || 

	        (d[2] == 'w' && d[3] == 'b') || 

		(d[2] == 'd' && d[3] == 'b') ||

		(d[2] == '_' && d[3] == '_'))

            && n < s->nb_streams

            && i + size <= avi->movi_end) {



            av_new_packet(pkt, size);

            get_buffer(pb, pkt->data, size);

            if (size & 1) {

                get_byte(pb);

		size++;

	    }



	    if (avi->dv_demux) {

	        dstr = pkt->destruct;

	        size = dv_produce_packet(avi->dv_demux, pkt,

		                         pkt->data, pkt->size);

		pkt->destruct = dstr;

                pkt->flags |= PKT_FLAG_KEY;

	    } else {

                AVStream *st;

                AVIStream *ast;

                st = s->streams[n];

                ast = st->priv_data;



                /* XXX: how to handle B frames in avi ? */

                pkt->dts = ast->frame_offset;

//                pkt->dts += ast->start;

                if(ast->sample_size)

                    pkt->dts /= ast->sample_size;

//av_log(NULL, AV_LOG_DEBUG, "dts:%Ld offset:%d %d/%d smpl_siz:%d base:%d st:%d size:%d\n", pkt->dts, ast->frame_offset, ast->scale, ast->rate, ast->sample_size, AV_TIME_BASE, n, size);

                pkt->stream_index = n;

                /* FIXME: We really should read index for that */

                if (st->codec.codec_type == CODEC_TYPE_VIDEO) {

                    if (ast->frame_offset < ast->nb_index_entries) {

                        if (ast->index_entries[ast->frame_offset].flags & AVIIF_INDEX)

                            pkt->flags |= PKT_FLAG_KEY; 

                    } else {

                        /* if no index, better to say that all frames

                           are key frames */

                        pkt->flags |= PKT_FLAG_KEY;

                    }

                } else {

                    pkt->flags |= PKT_FLAG_KEY; 

                }

                if(ast->sample_size)

                    ast->frame_offset += pkt->size;

                else

                    ast->frame_offset++;

	    }

            return size;

        }

    }

    return -1;

}

static int decode_slice(struct AVCodecContext *avctx, void *arg){

    H264Context *h = *(void**)arg;

    MpegEncContext * const s = &h->s;

    const int part_mask= s->partitioned_frame ? (AC_END|AC_ERROR) : 0x7F;

    int lf_x_start = s->mb_x;



    s->mb_skip_run= -1;



    h->is_complex = FRAME_MBAFF || s->picture_structure != PICT_FRAME || s->codec_id != CODEC_ID_H264 ||

                    (CONFIG_GRAY && (s->flags&CODEC_FLAG_GRAY));



    if( h->pps.cabac ) {

        /* realign */

        align_get_bits( &s->gb );



        /* init cabac */

        ff_init_cabac_states( &h->cabac);

        ff_init_cabac_decoder( &h->cabac,

                               s->gb.buffer + get_bits_count(&s->gb)/8,

                               (get_bits_left(&s->gb) + 7)/8);



        ff_h264_init_cabac_states(h);



        for(;;){

//START_TIMER

            int ret = ff_h264_decode_mb_cabac(h);

            int eos;

//STOP_TIMER("decode_mb_cabac")



            if(ret>=0) ff_h264_hl_decode_mb(h);



            if( ret >= 0 && FRAME_MBAFF ) { //FIXME optimal? or let mb_decode decode 16x32 ?

                s->mb_y++;



                ret = ff_h264_decode_mb_cabac(h);



                if(ret>=0) ff_h264_hl_decode_mb(h);

                s->mb_y--;

            }

            eos = get_cabac_terminate( &h->cabac );



            if((s->workaround_bugs & FF_BUG_TRUNCATED) && h->cabac.bytestream > h->cabac.bytestream_end + 2){

                ff_er_add_slice(s, s->resync_mb_x, s->resync_mb_y, s->mb_x-1, s->mb_y, (AC_END|DC_END|MV_END)&part_mask);

                if (s->mb_x >= lf_x_start) loop_filter(h, lf_x_start, s->mb_x + 1);

                return 0;

            }

            if( ret < 0 || h->cabac.bytestream > h->cabac.bytestream_end + 2) {

                av_log(h->s.avctx, AV_LOG_ERROR, "error while decoding MB %d %d, bytestream (%td)\n", s->mb_x, s->mb_y, h->cabac.bytestream_end - h->cabac.bytestream);

                ff_er_add_slice(s, s->resync_mb_x, s->resync_mb_y, s->mb_x, s->mb_y, (AC_ERROR|DC_ERROR|MV_ERROR)&part_mask);

                return -1;

            }



            if( ++s->mb_x >= s->mb_width ) {

                loop_filter(h, lf_x_start, s->mb_x);

                s->mb_x = lf_x_start = 0;

                decode_finish_row(h);

                ++s->mb_y;

                if(FIELD_OR_MBAFF_PICTURE) {

                    ++s->mb_y;

                    if(FRAME_MBAFF && s->mb_y < s->mb_height)

                        predict_field_decoding_flag(h);

                }

            }



            if( eos || s->mb_y >= s->mb_height ) {

                tprintf(s->avctx, "slice end %d %d\n", get_bits_count(&s->gb), s->gb.size_in_bits);

                ff_er_add_slice(s, s->resync_mb_x, s->resync_mb_y, s->mb_x-1, s->mb_y, (AC_END|DC_END|MV_END)&part_mask);

                if (s->mb_x > lf_x_start) loop_filter(h, lf_x_start, s->mb_x);

                return 0;

            }

        }



    } else {

        for(;;){

            int ret = ff_h264_decode_mb_cavlc(h);



            if(ret>=0) ff_h264_hl_decode_mb(h);



            if(ret>=0 && FRAME_MBAFF){ //FIXME optimal? or let mb_decode decode 16x32 ?

                s->mb_y++;

                ret = ff_h264_decode_mb_cavlc(h);



                if(ret>=0) ff_h264_hl_decode_mb(h);

                s->mb_y--;

            }



            if(ret<0){

                av_log(h->s.avctx, AV_LOG_ERROR, "error while decoding MB %d %d\n", s->mb_x, s->mb_y);

                ff_er_add_slice(s, s->resync_mb_x, s->resync_mb_y, s->mb_x, s->mb_y, (AC_ERROR|DC_ERROR|MV_ERROR)&part_mask);

                return -1;

            }



            if(++s->mb_x >= s->mb_width){

                loop_filter(h, lf_x_start, s->mb_x);

                s->mb_x = lf_x_start = 0;

                decode_finish_row(h);

                ++s->mb_y;

                if(FIELD_OR_MBAFF_PICTURE) {

                    ++s->mb_y;

                    if(FRAME_MBAFF && s->mb_y < s->mb_height)

                        predict_field_decoding_flag(h);

                }

                if(s->mb_y >= s->mb_height){

                    tprintf(s->avctx, "slice end %d %d\n", get_bits_count(&s->gb), s->gb.size_in_bits);



                    if(get_bits_count(&s->gb) == s->gb.size_in_bits ) {

                        ff_er_add_slice(s, s->resync_mb_x, s->resync_mb_y, s->mb_x-1, s->mb_y, (AC_END|DC_END|MV_END)&part_mask);



                        return 0;

                    }else{

                        ff_er_add_slice(s, s->resync_mb_x, s->resync_mb_y, s->mb_x, s->mb_y, (AC_END|DC_END|MV_END)&part_mask);



                        return -1;

                    }

                }

            }



            if(get_bits_count(&s->gb) >= s->gb.size_in_bits && s->mb_skip_run<=0){

                tprintf(s->avctx, "slice end %d %d\n", get_bits_count(&s->gb), s->gb.size_in_bits);

                if(get_bits_count(&s->gb) == s->gb.size_in_bits ){

                    ff_er_add_slice(s, s->resync_mb_x, s->resync_mb_y, s->mb_x-1, s->mb_y, (AC_END|DC_END|MV_END)&part_mask);

                    if (s->mb_x > lf_x_start) loop_filter(h, lf_x_start, s->mb_x);



                    return 0;

                }else{

                    ff_er_add_slice(s, s->resync_mb_x, s->resync_mb_y, s->mb_x, s->mb_y, (AC_ERROR|DC_ERROR|MV_ERROR)&part_mask);



                    return -1;

                }

            }

        }

    }



#if 0

    for(;s->mb_y < s->mb_height; s->mb_y++){

        for(;s->mb_x < s->mb_width; s->mb_x++){

            int ret= decode_mb(h);



            ff_h264_hl_decode_mb(h);



            if(ret<0){

                av_log(s->avctx, AV_LOG_ERROR, "error while decoding MB %d %d\n", s->mb_x, s->mb_y);

                ff_er_add_slice(s, s->resync_mb_x, s->resync_mb_y, s->mb_x, s->mb_y, (AC_ERROR|DC_ERROR|MV_ERROR)&part_mask);



                return -1;

            }



            if(++s->mb_x >= s->mb_width){

                s->mb_x=0;

                if(++s->mb_y >= s->mb_height){

                    if(get_bits_count(s->gb) == s->gb.size_in_bits){

                        ff_er_add_slice(s, s->resync_mb_x, s->resync_mb_y, s->mb_x-1, s->mb_y, (AC_END|DC_END|MV_END)&part_mask);



                        return 0;

                    }else{

                        ff_er_add_slice(s, s->resync_mb_x, s->resync_mb_y, s->mb_x, s->mb_y, (AC_END|DC_END|MV_END)&part_mask);



                        return -1;

                    }

                }

            }



            if(get_bits_count(s->?gb) >= s->gb?.size_in_bits){

                if(get_bits_count(s->gb) == s->gb.size_in_bits){

                    ff_er_add_slice(s, s->resync_mb_x, s->resync_mb_y, s->mb_x-1, s->mb_y, (AC_END|DC_END|MV_END)&part_mask);



                    return 0;

                }else{

                    ff_er_add_slice(s, s->resync_mb_x, s->resync_mb_y, s->mb_x, s->mb_y, (AC_ERROR|DC_ERROR|MV_ERROR)&part_mask);



                    return -1;

                }

            }

        }

        s->mb_x=0;

        ff_draw_horiz_band(s, 16*s->mb_y, 16);

    }

#endif

    return -1; //not reached

}

void updateMMXDitherTables(SwsContext *c, int dstY, int lumBufIndex, int chrBufIndex,
                           int lastInLumBuf, int lastInChrBuf)
{
    const int dstH= c->dstH;
    const int flags= c->flags;
    int16_t **lumPixBuf= c->lumPixBuf;
    int16_t **chrUPixBuf= c->chrUPixBuf;
    int16_t **alpPixBuf= c->alpPixBuf;
    const int vLumBufSize= c->vLumBufSize;
    const int vChrBufSize= c->vChrBufSize;
    int16_t *vLumFilterPos= c->vLumFilterPos;
    int16_t *vChrFilterPos= c->vChrFilterPos;
    int16_t *vLumFilter= c->vLumFilter;
    int16_t *vChrFilter= c->vChrFilter;
    int32_t *lumMmxFilter= c->lumMmxFilter;
    int32_t *chrMmxFilter= c->chrMmxFilter;
    int32_t av_unused *alpMmxFilter= c->alpMmxFilter;
    const int vLumFilterSize= c->vLumFilterSize;
    const int vChrFilterSize= c->vChrFilterSize;
    const int chrDstY= dstY>>c->chrDstVSubSample;
    const int firstLumSrcY= vLumFilterPos[dstY]; //First line needed as input
    const int firstChrSrcY= vChrFilterPos[chrDstY]; //First line needed as input
    c->blueDither= ff_dither8[dstY&1];
    if (c->dstFormat == PIX_FMT_RGB555 || c->dstFormat == PIX_FMT_BGR555)
        c->greenDither= ff_dither8[dstY&1];
    else
        c->greenDither= ff_dither4[dstY&1];
    c->redDither= ff_dither8[(dstY+1)&1];
    if (dstY < dstH - 2) {
        const int16_t **lumSrcPtr= (const int16_t **) lumPixBuf + lumBufIndex + firstLumSrcY - lastInLumBuf + vLumBufSize;
        const int16_t **chrUSrcPtr= (const int16_t **) chrUPixBuf + chrBufIndex + firstChrSrcY - lastInChrBuf + vChrBufSize;
        const int16_t **alpSrcPtr= (CONFIG_SWSCALE_ALPHA && alpPixBuf) ? (const int16_t **) alpPixBuf + lumBufIndex + firstLumSrcY - lastInLumBuf + vLumBufSize : NULL;
        int i;
        if (flags & SWS_ACCURATE_RND) {
            int s= APCK_SIZE / 8;
            for (i=0; i<vLumFilterSize; i+=2) {
                *(const void**)&lumMmxFilter[s*i              ]= lumSrcPtr[i  ];
                *(const void**)&lumMmxFilter[s*i+APCK_PTR2/4  ]= lumSrcPtr[i+(vLumFilterSize>1)];
                lumMmxFilter[s*i+APCK_COEF/4  ]=
                lumMmxFilter[s*i+APCK_COEF/4+1]= vLumFilter[dstY*vLumFilterSize + i    ]
                + (vLumFilterSize>1 ? vLumFilter[dstY*vLumFilterSize + i + 1]<<16 : 0);
                if (CONFIG_SWSCALE_ALPHA && alpPixBuf) {
                    *(const void**)&alpMmxFilter[s*i              ]= alpSrcPtr[i  ];
                    *(const void**)&alpMmxFilter[s*i+APCK_PTR2/4  ]= alpSrcPtr[i+(vLumFilterSize>1)];
                    alpMmxFilter[s*i+APCK_COEF/4  ]=
                    alpMmxFilter[s*i+APCK_COEF/4+1]= lumMmxFilter[s*i+APCK_COEF/4  ];
            for (i=0; i<vChrFilterSize; i+=2) {
                *(const void**)&chrMmxFilter[s*i              ]= chrUSrcPtr[i  ];
                *(const void**)&chrMmxFilter[s*i+APCK_PTR2/4  ]= chrUSrcPtr[i+(vChrFilterSize>1)];
                chrMmxFilter[s*i+APCK_COEF/4  ]=
                chrMmxFilter[s*i+APCK_COEF/4+1]= vChrFilter[chrDstY*vChrFilterSize + i    ]
                + (vChrFilterSize>1 ? vChrFilter[chrDstY*vChrFilterSize + i + 1]<<16 : 0);
        } else {
            for (i=0; i<vLumFilterSize; i++) {
                *(const void**)&lumMmxFilter[4*i+0]= lumSrcPtr[i];
                lumMmxFilter[4*i+2]=
                lumMmxFilter[4*i+3]=
                ((uint16_t)vLumFilter[dstY*vLumFilterSize + i])*0x10001;
                if (CONFIG_SWSCALE_ALPHA && alpPixBuf) {
                    *(const void**)&alpMmxFilter[4*i+0]= alpSrcPtr[i];
                    alpMmxFilter[4*i+2]=
                    alpMmxFilter[4*i+3]= lumMmxFilter[4*i+2];
            for (i=0; i<vChrFilterSize; i++) {
                *(const void**)&chrMmxFilter[4*i+0]= chrUSrcPtr[i];
                chrMmxFilter[4*i+2]=
                chrMmxFilter[4*i+3]=
                ((uint16_t)vChrFilter[chrDstY*vChrFilterSize + i])*0x10001;

static void mp3_parse_vbr_tags(AVFormatContext *s, AVStream *st, int64_t base)

{

    uint32_t v, spf;

    int frames = -1; /* Total number of frames in file */

    const int64_t xing_offtbl[2][2] = {{32, 17}, {17,9}};

    MPADecodeContext c;



    v = get_be32(s->pb);

    if(ff_mpa_check_header(v) < 0)

      return;



    ff_mpegaudio_decode_header(&c, v);

    if(c.layer != 3)

        return;



    /* Check for Xing / Info tag */

    url_fseek(s->pb, xing_offtbl[c.lsf == 1][c.nb_channels == 1], SEEK_CUR);

    v = get_be32(s->pb);

    if(v == MKBETAG('X', 'i', 'n', 'g') || v == MKBETAG('I', 'n', 'f', 'o')) {

        v = get_be32(s->pb);

        if(v & 0x1)

            frames = get_be32(s->pb);

    }



    /* Check for VBRI tag (always 32 bytes after end of mpegaudio header) */

    url_fseek(s->pb, base + 4 + 32, SEEK_SET);

    v = get_be32(s->pb);

    if(v == MKBETAG('V', 'B', 'R', 'I')) {

        /* Check tag version */

        if(get_be16(s->pb) == 1) {

            /* skip delay, quality and total bytes */

            url_fseek(s->pb, 8, SEEK_CUR);

            frames = get_be32(s->pb);

        }

    }



    if(frames < 0)

        return;



    spf = c.lsf ? 576 : 1152; /* Samples per frame, layer 3 */

    st->duration = av_rescale_q(frames, (AVRational){spf, c.sample_rate},

                                st->time_base);

}

static void mdct512(int32_t *out, int16_t *in)

{

    int i, re, im, re1, im1;

    int16_t rot[MDCT_SAMPLES];

    IComplex x[MDCT_SAMPLES/4];



    /* shift to simplify computations */

    for (i = 0; i < MDCT_SAMPLES/4; i++)

        rot[i] = -in[i + 3*MDCT_SAMPLES/4];

    for (;i < MDCT_SAMPLES; i++)

        rot[i] =  in[i -   MDCT_SAMPLES/4];



    /* pre rotation */

    for (i = 0; i < MDCT_SAMPLES/4; i++) {

        re =  ((int)rot[               2*i] - (int)rot[MDCT_SAMPLES  -1-2*i]) >> 1;

        im = -((int)rot[MDCT_SAMPLES/2+2*i] - (int)rot[MDCT_SAMPLES/2-1-2*i]) >> 1;

        CMUL(x[i].re, x[i].im, re, im, -xcos1[i], xsin1[i]);

    }



    fft(x, MDCT_NBITS - 2);



    /* post rotation */

    for (i = 0; i < MDCT_SAMPLES/4; i++) {

        re = x[i].re;

        im = x[i].im;

        CMUL(re1, im1, re, im, xsin1[i], xcos1[i]);

        out[                 2*i] = im1;

        out[MDCT_SAMPLES/2-1-2*i] = re1;

    }

}

static int flic_decode_frame_15_16BPP(AVCodecContext *avctx,

                                      void *data, int *data_size,

                                      const uint8_t *buf, int buf_size)

{

    /* Note, the only difference between the 15Bpp and 16Bpp */

    /* Format is the pixel format, the packets are processed the same. */

    FlicDecodeContext *s = avctx->priv_data;



    int stream_ptr = 0;

    int pixel_ptr;

    unsigned char palette_idx1;



    unsigned int frame_size;

    int num_chunks;



    unsigned int chunk_size;

    int chunk_type;



    int i, j;



    int lines;

    int compressed_lines;

    signed short line_packets;

    int y_ptr;

    int byte_run;

    int pixel_skip;

    int pixel_countdown;

    unsigned char *pixels;

    int pixel;

    unsigned int pixel_limit;



    s->frame.reference = 1;

    s->frame.buffer_hints = FF_BUFFER_HINTS_VALID | FF_BUFFER_HINTS_PRESERVE | FF_BUFFER_HINTS_REUSABLE;

    if (avctx->reget_buffer(avctx, &s->frame) < 0) {

        av_log(avctx, AV_LOG_ERROR, "reget_buffer() failed\n");

        return -1;

    }



    pixels = s->frame.data[0];

    pixel_limit = s->avctx->height * s->frame.linesize[0];



    frame_size = AV_RL32(&buf[stream_ptr]);

    stream_ptr += 6;  /* skip the magic number */

    num_chunks = AV_RL16(&buf[stream_ptr]);

    stream_ptr += 10;  /* skip padding */



    frame_size -= 16;



    /* iterate through the chunks */

    while ((frame_size > 0) && (num_chunks > 0)) {

        chunk_size = AV_RL32(&buf[stream_ptr]);

        stream_ptr += 4;

        chunk_type = AV_RL16(&buf[stream_ptr]);

        stream_ptr += 2;



        switch (chunk_type) {

        case FLI_256_COLOR:

        case FLI_COLOR:

            /* For some reason, it seems that non-palettized flics do

             * include one of these chunks in their first frame.

             * Why I do not know, it seems rather extraneous. */

/*            av_log(avctx, AV_LOG_ERROR, "Unexpected Palette chunk %d in non-paletised FLC\n",chunk_type);*/

            stream_ptr = stream_ptr + chunk_size - 6;

            break;



        case FLI_DELTA:

        case FLI_DTA_LC:

            y_ptr = 0;

            compressed_lines = AV_RL16(&buf[stream_ptr]);

            stream_ptr += 2;

            while (compressed_lines > 0) {

                line_packets = AV_RL16(&buf[stream_ptr]);

                stream_ptr += 2;

                if (line_packets < 0) {

                    line_packets = -line_packets;

                    y_ptr += line_packets * s->frame.linesize[0];

                } else {

                    compressed_lines--;

                    pixel_ptr = y_ptr;

                    CHECK_PIXEL_PTR(0);

                    pixel_countdown = s->avctx->width;

                    for (i = 0; i < line_packets; i++) {

                        /* account for the skip bytes */

                        pixel_skip = buf[stream_ptr++];

                        pixel_ptr += (pixel_skip*2); /* Pixel is 2 bytes wide */

                        pixel_countdown -= pixel_skip;

                        byte_run = (signed char)(buf[stream_ptr++]);

                        if (byte_run < 0) {

                            byte_run = -byte_run;

                            pixel    = AV_RL16(&buf[stream_ptr]);

                            stream_ptr += 2;

                            CHECK_PIXEL_PTR(2 * byte_run);

                            for (j = 0; j < byte_run; j++, pixel_countdown -= 2) {

                                *((signed short*)(&pixels[pixel_ptr])) = pixel;

                                pixel_ptr += 2;

                            }

                        } else {

                            CHECK_PIXEL_PTR(2 * byte_run);

                            for (j = 0; j < byte_run; j++, pixel_countdown--) {

                                *((signed short*)(&pixels[pixel_ptr])) = AV_RL16(&buf[stream_ptr]);

                                stream_ptr += 2;

                                pixel_ptr += 2;

                            }

                        }

                    }



                    y_ptr += s->frame.linesize[0];

                }

            }

            break;



        case FLI_LC:

            av_log(avctx, AV_LOG_ERROR, "Unexpected FLI_LC chunk in non-paletised FLC\n");

            stream_ptr = stream_ptr + chunk_size - 6;

            break;



        case FLI_BLACK:

            /* set the whole frame to 0x0000 which is black in both 15Bpp and 16Bpp modes. */

            memset(pixels, 0x0000,

                   s->frame.linesize[0] * s->avctx->height);

            break;



        case FLI_BRUN:

            y_ptr = 0;

            for (lines = 0; lines < s->avctx->height; lines++) {

                pixel_ptr = y_ptr;

                /* disregard the line packets; instead, iterate through all

                 * pixels on a row */

                stream_ptr++;

                pixel_countdown = (s->avctx->width * 2);



                while (pixel_countdown > 0) {

                    byte_run = (signed char)(buf[stream_ptr++]);

                    if (byte_run > 0) {

                        palette_idx1 = buf[stream_ptr++];

                        CHECK_PIXEL_PTR(byte_run);

                        for (j = 0; j < byte_run; j++) {

                            pixels[pixel_ptr++] = palette_idx1;

                            pixel_countdown--;

                            if (pixel_countdown < 0)

                                av_log(avctx, AV_LOG_ERROR, "pixel_countdown < 0 (%d) (linea%d)\n",

                                       pixel_countdown, lines);

                        }

                    } else {  /* copy bytes if byte_run < 0 */

                        byte_run = -byte_run;

                        CHECK_PIXEL_PTR(byte_run);

                        for (j = 0; j < byte_run; j++) {

                            palette_idx1 = buf[stream_ptr++];

                            pixels[pixel_ptr++] = palette_idx1;

                            pixel_countdown--;

                            if (pixel_countdown < 0)

                                av_log(avctx, AV_LOG_ERROR, "pixel_countdown < 0 (%d) at line %d\n",

                                       pixel_countdown, lines);

                        }

                    }

                }



                /* Now FLX is strange, in that it is "byte" as opposed to "pixel" run length compressed.

                 * This does not give us any good oportunity to perform word endian conversion

                 * during decompression. So if it is required (i.e., this is not a LE target, we do

                 * a second pass over the line here, swapping the bytes.

                 */

#if HAVE_BIGENDIAN

                pixel_ptr = y_ptr;

                pixel_countdown = s->avctx->width;

                while (pixel_countdown > 0) {

                    *((signed short*)(&pixels[pixel_ptr])) = AV_RL16(&buf[pixel_ptr]);

                    pixel_ptr += 2;

                }

#endif

                y_ptr += s->frame.linesize[0];

            }

            break;



        case FLI_DTA_BRUN:

            y_ptr = 0;

            for (lines = 0; lines < s->avctx->height; lines++) {

                pixel_ptr = y_ptr;

                /* disregard the line packets; instead, iterate through all

                 * pixels on a row */

                stream_ptr++;

                pixel_countdown = s->avctx->width; /* Width is in pixels, not bytes */



                while (pixel_countdown > 0) {

                    byte_run = (signed char)(buf[stream_ptr++]);

                    if (byte_run > 0) {

                        pixel    = AV_RL16(&buf[stream_ptr]);

                        stream_ptr += 2;

                        CHECK_PIXEL_PTR(2 * byte_run);

                        for (j = 0; j < byte_run; j++) {

                            *((signed short*)(&pixels[pixel_ptr])) = pixel;

                            pixel_ptr += 2;

                            pixel_countdown--;

                            if (pixel_countdown < 0)

                                av_log(avctx, AV_LOG_ERROR, "pixel_countdown < 0 (%d)\n",

                                       pixel_countdown);

                        }

                    } else {  /* copy pixels if byte_run < 0 */

                        byte_run = -byte_run;

                        CHECK_PIXEL_PTR(2 * byte_run);

                        for (j = 0; j < byte_run; j++) {

                            *((signed short*)(&pixels[pixel_ptr])) = AV_RL16(&buf[stream_ptr]);

                            stream_ptr += 2;

                            pixel_ptr  += 2;

                            pixel_countdown--;

                            if (pixel_countdown < 0)

                                av_log(avctx, AV_LOG_ERROR, "pixel_countdown < 0 (%d)\n",

                                       pixel_countdown);

                        }

                    }

                }



                y_ptr += s->frame.linesize[0];

            }

            break;



        case FLI_COPY:

        case FLI_DTA_COPY:

            /* copy the chunk (uncompressed frame) */

            if (chunk_size - 6 > (unsigned int)(s->avctx->width * s->avctx->height)*2) {

                av_log(avctx, AV_LOG_ERROR, "In chunk FLI_COPY : source data (%d bytes) " \

                       "bigger than image, skipping chunk\n", chunk_size - 6);

                stream_ptr += chunk_size - 6;

            } else {



                for (y_ptr = 0; y_ptr < s->frame.linesize[0] * s->avctx->height;

                     y_ptr += s->frame.linesize[0]) {



                    pixel_countdown = s->avctx->width;

                    pixel_ptr = 0;

                    while (pixel_countdown > 0) {

                      *((signed short*)(&pixels[y_ptr + pixel_ptr])) = AV_RL16(&buf[stream_ptr+pixel_ptr]);

                      pixel_ptr += 2;

                      pixel_countdown--;

                    }

                    stream_ptr += s->avctx->width*2;

                }

            }

            break;



        case FLI_MINI:

            /* some sort of a thumbnail? disregard this chunk... */

            stream_ptr += chunk_size - 6;

            break;



        default:

            av_log(avctx, AV_LOG_ERROR, "Unrecognized chunk type: %d\n", chunk_type);

            break;

        }



        frame_size -= chunk_size;

        num_chunks--;

    }



    /* by the end of the chunk, the stream ptr should equal the frame

     * size (minus 1, possibly); if it doesn't, issue a warning */

    if ((stream_ptr != buf_size) && (stream_ptr != buf_size - 1))

        av_log(avctx, AV_LOG_ERROR, "Processed FLI chunk where chunk size = %d " \

               "and final chunk ptr = %d\n", buf_size, stream_ptr);





    *data_size=sizeof(AVFrame);

    *(AVFrame*)data = s->frame;



    return buf_size;

}

static void write_audio_frame(AVFormatContext *oc, AVStream *st)

{

    AVCodecContext *c;

    AVPacket pkt = { 0 }; // data and size must be 0;

    int got_packet, ret, dst_nb_samples;



    av_init_packet(&pkt);

    c = st->codec;



    get_audio_frame((int16_t *)src_samples_data[0], src_nb_samples, c->channels);



    /* convert samples from native format to destination codec format, using the resampler */

    if (swr_ctx) {

        /* compute destination number of samples */

        dst_nb_samples = av_rescale_rnd(swr_get_delay(swr_ctx, c->sample_rate) + src_nb_samples,

                                        c->sample_rate, c->sample_rate, AV_ROUND_UP);

        if (dst_nb_samples > max_dst_nb_samples) {

            av_free(dst_samples_data[0]);

            ret = av_samples_alloc(dst_samples_data, &dst_samples_linesize, c->channels,

                                   dst_nb_samples, c->sample_fmt, 0);

            if (ret < 0)

                exit(1);

            max_dst_nb_samples = dst_nb_samples;

            dst_samples_size = av_samples_get_buffer_size(NULL, c->channels, dst_nb_samples,

                                                          c->sample_fmt, 0);

        }



        /* convert to destination format */

        ret = swr_convert(swr_ctx,

                          dst_samples_data, dst_nb_samples,

                          (const uint8_t **)src_samples_data, src_nb_samples);

        if (ret < 0) {

            fprintf(stderr, "Error while converting\n");

            exit(1);

        }

    } else {

        dst_nb_samples = src_nb_samples;

    }



    audio_frame->nb_samples = dst_nb_samples;

    audio_frame->pts = av_rescale_q(samples_count, (AVRational){1, c->sample_rate}, c->time_base);

    avcodec_fill_audio_frame(audio_frame, c->channels, c->sample_fmt,

                             dst_samples_data[0], dst_samples_size, 0);

    samples_count += dst_nb_samples;



    ret = avcodec_encode_audio2(c, &pkt, audio_frame, &got_packet);

    if (ret < 0) {

        fprintf(stderr, "Error encoding audio frame: %s\n", av_err2str(ret));

        exit(1);

    }



    if (!got_packet)

        return;



    ret = write_frame(oc, &c->time_base, st, &pkt);

    if (ret != 0) {

        fprintf(stderr, "Error while writing audio frame: %s\n",

                av_err2str(ret));

        exit(1);

    }

}

AVFrame *avcodec_alloc_frame(void)

{

    AVFrame *frame = av_malloc(sizeof(AVFrame));



    if (frame == NULL)

        return NULL;



    avcodec_get_frame_defaults(frame);



    return frame;

}

static int mov_write_hdlr_tag(ByteIOContext *pb, MOVTrack *track)

{

    const char *descr, *hdlr, *hdlr_type;

    int64_t pos = url_ftell(pb);



    if (!track) { /* no media --> data handler */

        hdlr = "dhlr";

        hdlr_type = "url ";

        descr = "DataHandler";

    } else {

        hdlr = (track->mode == MODE_MOV) ? "mhlr" : "\0\0\0\0";

        if (track->enc->codec_type == CODEC_TYPE_VIDEO) {

            hdlr_type = "vide";

            descr = "VideoHandler";

        } else if (track->enc->codec_type == CODEC_TYPE_AUDIO){

            hdlr_type = "soun";

            descr = "SoundHandler";

        } else if (track->enc->codec_type == CODEC_TYPE_SUBTITLE){

            if (track->mode == MODE_IPOD) hdlr_type = "sbtl";

            else                          hdlr_type = "text";

            descr = "SubtitleHandler";

        }

    }



    put_be32(pb, 0); /* size */

    put_tag(pb, "hdlr");

    put_be32(pb, 0); /* Version & flags */

    put_buffer(pb, hdlr, 4); /* handler */

    put_tag(pb, hdlr_type); /* handler type */

    put_be32(pb ,0); /* reserved */

    put_be32(pb ,0); /* reserved */

    put_be32(pb ,0); /* reserved */

    put_byte(pb, strlen(descr)); /* string counter */

    put_buffer(pb, descr, strlen(descr)); /* handler description */

    return updateSize(pb, pos);

}

static av_always_inline void decode_cabac_residual_internal( H264Context *h, DCTELEM *block, int cat, int n, const uint8_t *scantable, const uint32_t *qmul, int max_coeff, int is_dc ) {

    static const int significant_coeff_flag_offset[2][6] = {

      { 105+0, 105+15, 105+29, 105+44, 105+47, 402 },

      { 277+0, 277+15, 277+29, 277+44, 277+47, 436 }

    };

    static const int last_coeff_flag_offset[2][6] = {

      { 166+0, 166+15, 166+29, 166+44, 166+47, 417 },

      { 338+0, 338+15, 338+29, 338+44, 338+47, 451 }

    };

    static const int coeff_abs_level_m1_offset[6] = {

        227+0, 227+10, 227+20, 227+30, 227+39, 426

    };

    static const uint8_t significant_coeff_flag_offset_8x8[2][63] = {

      { 0, 1, 2, 3, 4, 5, 5, 4, 4, 3, 3, 4, 4, 4, 5, 5,

        4, 4, 4, 4, 3, 3, 6, 7, 7, 7, 8, 9,10, 9, 8, 7,

        7, 6,11,12,13,11, 6, 7, 8, 9,14,10, 9, 8, 6,11,

       12,13,11, 6, 9,14,10, 9,11,12,13,11,14,10,12 },

      { 0, 1, 1, 2, 2, 3, 3, 4, 5, 6, 7, 7, 7, 8, 4, 5,

        6, 9,10,10, 8,11,12,11, 9, 9,10,10, 8,11,12,11,

        9, 9,10,10, 8,11,12,11, 9, 9,10,10, 8,13,13, 9,

        9,10,10, 8,13,13, 9, 9,10,10,14,14,14,14,14 }

    };

    /* node ctx: 0..3: abslevel1 (with abslevelgt1 == 0).

     * 4..7: abslevelgt1 + 3 (and abslevel1 doesn't matter).

     * map node ctx => cabac ctx for level=1 */

    static const uint8_t coeff_abs_level1_ctx[8] = { 1, 2, 3, 4, 0, 0, 0, 0 };

    /* map node ctx => cabac ctx for level>1 */

    static const uint8_t coeff_abs_levelgt1_ctx[8] = { 5, 5, 5, 5, 6, 7, 8, 9 };

    static const uint8_t coeff_abs_level_transition[2][8] = {

    /* update node ctx after decoding a level=1 */

        { 1, 2, 3, 3, 4, 5, 6, 7 },

    /* update node ctx after decoding a level>1 */

        { 4, 4, 4, 4, 5, 6, 7, 7 }

    };



    int index[64];



    int av_unused last;

    int coeff_count = 0;

    int node_ctx = 0;



    uint8_t *significant_coeff_ctx_base;

    uint8_t *last_coeff_ctx_base;

    uint8_t *abs_level_m1_ctx_base;



#ifndef ARCH_X86

#define CABAC_ON_STACK

#endif

#ifdef CABAC_ON_STACK

#define CC &cc

    CABACContext cc;

    cc.range     = h->cabac.range;

    cc.low       = h->cabac.low;

    cc.bytestream= h->cabac.bytestream;

#else

#define CC &h->cabac

#endif





    /* cat: 0-> DC 16x16  n = 0

     *      1-> AC 16x16  n = luma4x4idx

     *      2-> Luma4x4   n = luma4x4idx

     *      3-> DC Chroma n = iCbCr

     *      4-> AC Chroma n = 4 * iCbCr + chroma4x4idx

     *      5-> Luma8x8   n = 4 * luma8x8idx

     */



    /* read coded block flag */

    if( is_dc || cat != 5 ) {

        if( get_cabac( CC, &h->cabac_state[85 + get_cabac_cbf_ctx( h, cat, n, is_dc ) ] ) == 0 ) {

            if( !is_dc ) {

                if( cat == 1 || cat == 2 )

                    h->non_zero_count_cache[scan8[n]] = 0;

                else

                    h->non_zero_count_cache[scan8[16+n]] = 0;

            }



#ifdef CABAC_ON_STACK

            h->cabac.range     = cc.range     ;

            h->cabac.low       = cc.low       ;

            h->cabac.bytestream= cc.bytestream;

#endif

            return;

        }

    }



    significant_coeff_ctx_base = h->cabac_state

        + significant_coeff_flag_offset[MB_FIELD][cat];

    last_coeff_ctx_base = h->cabac_state

        + last_coeff_flag_offset[MB_FIELD][cat];

    abs_level_m1_ctx_base = h->cabac_state

        + coeff_abs_level_m1_offset[cat];



    if( !is_dc && cat == 5 ) {

#define DECODE_SIGNIFICANCE( coefs, sig_off, last_off ) \

        for(last= 0; last < coefs; last++) { \

            uint8_t *sig_ctx = significant_coeff_ctx_base + sig_off; \

            if( get_cabac( CC, sig_ctx )) { \

                uint8_t *last_ctx = last_coeff_ctx_base + last_off; \

                index[coeff_count++] = last; \

                if( get_cabac( CC, last_ctx ) ) { \

                    last= max_coeff; \

                    break; \

                } \

            } \

        }\

        if( last == max_coeff -1 ) {\

            index[coeff_count++] = last;\

        }

        const uint8_t *sig_off = significant_coeff_flag_offset_8x8[MB_FIELD];

#if defined(ARCH_X86) && defined(HAVE_7REGS) && defined(HAVE_EBX_AVAILABLE) && !defined(BROKEN_RELOCATIONS)

        coeff_count= decode_significance_8x8_x86(CC, significant_coeff_ctx_base, index, sig_off);

    } else {

        coeff_count= decode_significance_x86(CC, max_coeff, significant_coeff_ctx_base, index);

#else

        DECODE_SIGNIFICANCE( 63, sig_off[last], last_coeff_flag_offset_8x8[last] );

    } else {

        DECODE_SIGNIFICANCE( max_coeff - 1, last, last );

#endif

    }

    assert(coeff_count > 0);



    if( is_dc ) {

        if( cat == 0 )

            h->cbp_table[h->mb_xy] |= 0x100;

        else

            h->cbp_table[h->mb_xy] |= 0x40 << n;

    } else {

        if( cat == 1 || cat == 2 )

            h->non_zero_count_cache[scan8[n]] = coeff_count;

        else if( cat == 4 )

            h->non_zero_count_cache[scan8[16+n]] = coeff_count;

        else {

            assert( cat == 5 );

            fill_rectangle(&h->non_zero_count_cache[scan8[n]], 2, 2, 8, coeff_count, 1);

        }

    }



    for( coeff_count--; coeff_count >= 0; coeff_count-- ) {

        uint8_t *ctx = coeff_abs_level1_ctx[node_ctx] + abs_level_m1_ctx_base;



        int j= scantable[index[coeff_count]];



        if( get_cabac( CC, ctx ) == 0 ) {

            node_ctx = coeff_abs_level_transition[0][node_ctx];

            if( is_dc ) {

                block[j] = get_cabac_bypass_sign( CC, -1);

            }else{

                block[j] = (get_cabac_bypass_sign( CC, -qmul[j]) + 32) >> 6;

            }

        } else {

            int coeff_abs = 2;

            ctx = coeff_abs_levelgt1_ctx[node_ctx] + abs_level_m1_ctx_base;

            node_ctx = coeff_abs_level_transition[1][node_ctx];



            while( coeff_abs < 15 && get_cabac( CC, ctx ) ) {

                coeff_abs++;

            }



            if( coeff_abs >= 15 ) {

                int j = 0;

                while( get_cabac_bypass( CC ) ) {

                    j++;

                }



                coeff_abs=1;

                while( j-- ) {

                    coeff_abs += coeff_abs + get_cabac_bypass( CC );

                }

                coeff_abs+= 14;

            }



            if( is_dc ) {

                if( get_cabac_bypass( CC ) ) block[j] = -coeff_abs;

                else                                block[j] =  coeff_abs;

            }else{

                if( get_cabac_bypass( CC ) ) block[j] = (-coeff_abs * qmul[j] + 32) >> 6;

                else                                block[j] = ( coeff_abs * qmul[j] + 32) >> 6;

            }

        }

    }

#ifdef CABAC_ON_STACK

            h->cabac.range     = cc.range     ;

            h->cabac.low       = cc.low       ;

            h->cabac.bytestream= cc.bytestream;

#endif



}

static void mpc8_parse_seektable(AVFormatContext *s, int64_t off)

{

    MPCContext *c = s->priv_data;

    int tag;

    int64_t size, pos, ppos[2];

    uint8_t *buf;

    int i, t, seekd;

    GetBitContext gb;



    if (s->nb_streams == 0) {

        av_log(s, AV_LOG_ERROR, "No stream added before parsing seek table\n");

        return;

    }



    avio_seek(s->pb, off, SEEK_SET);

    mpc8_get_chunk_header(s->pb, &tag, &size);

    if(tag != TAG_SEEKTABLE){

        av_log(s, AV_LOG_ERROR, "No seek table at given position\n");

        return;

    }

    if (size > INT_MAX/10 || size<=0) {

        av_log(s, AV_LOG_ERROR, "Bad seek table size\n");

        return;

    }

    if(!(buf = av_malloc(size + FF_INPUT_BUFFER_PADDING_SIZE)))

        return;

    avio_read(s->pb, buf, size);

    memset(buf+size, 0, FF_INPUT_BUFFER_PADDING_SIZE);



    init_get_bits(&gb, buf, size * 8);

    size = gb_get_v(&gb);

    if(size > UINT_MAX/4 || size > c->samples/1152){

        av_log(s, AV_LOG_ERROR, "Seek table is too big\n");

        return;

    }

    seekd = get_bits(&gb, 4);

    for(i = 0; i < 2; i++){

        pos = gb_get_v(&gb) + c->header_pos;

        ppos[1 - i] = pos;

        av_add_index_entry(s->streams[0], pos, i, 0, 0, AVINDEX_KEYFRAME);

    }

    for(; i < size; i++){

        t = get_unary(&gb, 1, 33) << 12;

        t += get_bits(&gb, 12);

        if(t & 1)

            t = -(t & ~1);

        pos = (t >> 1) + ppos[0]*2 - ppos[1];

        av_add_index_entry(s->streams[0], pos, i << seekd, 0, 0, AVINDEX_KEYFRAME);

        ppos[1] = ppos[0];

        ppos[0] = pos;

    }

    av_free(buf);

}

static int ftp_features(FTPContext *s)

{

    static const char *feat_command        = "FEAT\r\n";

    static const char *enable_utf8_command = "OPTS UTF8 ON\r\n";

    static const int feat_codes[] = {211, 0};

    static const int opts_codes[] = {200, 451};

    char *feat;



    if (ftp_send_command(s, feat_command, feat_codes, &feat) == 211) {

        if (av_stristr(feat, "UTF8"))

            ftp_send_command(s, enable_utf8_command, opts_codes, NULL);

    }

    return 0;

}

static int ffserver_apply_stream_config(AVCodecContext *enc, const AVDictionary *conf, AVDictionary **opts)

{

    AVDictionaryEntry *e;

    int ret = 0;



    /* Return values from ffserver_set_*_param are ignored.

       Values are initially parsed and checked before inserting to AVDictionary. */



    //video params

    if ((e = av_dict_get(conf, "VideoBitRateRangeMin", NULL, 0)))

        ffserver_set_int_param(&enc->rc_min_rate, e->value, 1000, INT_MIN, INT_MAX, NULL, 0, NULL);

    if ((e = av_dict_get(conf, "VideoBitRateRangeMax", NULL, 0)))

        ffserver_set_int_param(&enc->rc_max_rate, e->value, 1000, INT_MIN, INT_MAX, NULL, 0, NULL);

    if ((e = av_dict_get(conf, "Debug", NULL, 0)))

        ffserver_set_int_param(&enc->debug, e->value, 0, INT_MIN, INT_MAX, NULL, 0, NULL);

    if ((e = av_dict_get(conf, "Strict", NULL, 0)))

        ffserver_set_int_param(&enc->strict_std_compliance, e->value, 0, INT_MIN, INT_MAX, NULL, 0, NULL);

    if ((e = av_dict_get(conf, "VideoBufferSize", NULL, 0)))

        ffserver_set_int_param(&enc->rc_buffer_size, e->value, 8*1024, INT_MIN, INT_MAX, NULL, 0, NULL);

    if ((e = av_dict_get(conf, "VideoBitRateTolerance", NULL, 0)))

        ffserver_set_int_param(&enc->bit_rate_tolerance, e->value, 1000, INT_MIN, INT_MAX, NULL, 0, NULL);

    if ((e = av_dict_get(conf, "VideoBitRate", NULL, 0)))

        ffserver_set_int_param(&enc->bit_rate, e->value, 1000, INT_MIN, INT_MAX, NULL, 0, NULL);

    if ((e = av_dict_get(conf, "VideoSizeWidth", NULL, 0)))

        ffserver_set_int_param(&enc->width, e->value, 0, INT_MIN, INT_MAX, NULL, 0, NULL);

    if ((e = av_dict_get(conf, "VideoSizeHeight", NULL, 0)))

        ffserver_set_int_param(&enc->height, e->value, 0, INT_MIN, INT_MAX, NULL, 0, NULL);

    if ((e = av_dict_get(conf, "PixelFormat", NULL, 0))) {

        int val;

        ffserver_set_int_param(&val, e->value, 0, INT_MIN, INT_MAX, NULL, 0, NULL);

        enc->pix_fmt = val;

    }

    if ((e = av_dict_get(conf, "VideoGopSize", NULL, 0)))

        ffserver_set_int_param(&enc->gop_size, e->value, 0, INT_MIN, INT_MAX, NULL, 0, NULL);

    if ((e = av_dict_get(conf, "VideoFrameRateNum", NULL, 0)))

        ffserver_set_int_param(&enc->time_base.num, e->value, 0, INT_MIN, INT_MAX, NULL, 0, NULL);

    if ((e = av_dict_get(conf, "VideoFrameRateDen", NULL, 0)))

        ffserver_set_int_param(&enc->time_base.den, e->value, 0, INT_MIN, INT_MAX, NULL, 0, NULL);

    if ((e = av_dict_get(conf, "VideoQDiff", NULL, 0)))

        ffserver_set_int_param(&enc->max_qdiff, e->value, 0, INT_MIN, INT_MAX, NULL, 0, NULL);

    if ((e = av_dict_get(conf, "VideoQMax", NULL, 0)))

        ffserver_set_int_param(&enc->qmax, e->value, 0, INT_MIN, INT_MAX, NULL, 0, NULL);

    if ((e = av_dict_get(conf, "VideoQMin", NULL, 0)))

        ffserver_set_int_param(&enc->qmin, e->value, 0, INT_MIN, INT_MAX, NULL, 0, NULL);

    if ((e = av_dict_get(conf, "LumiMask", NULL, 0)))

        ffserver_set_float_param(&enc->lumi_masking, e->value, 0, -FLT_MAX, FLT_MAX, NULL, 0, NULL);

    if ((e = av_dict_get(conf, "DarkMask", NULL, 0)))

        ffserver_set_float_param(&enc->dark_masking, e->value, 0, -FLT_MAX, FLT_MAX, NULL, 0, NULL);

    if (av_dict_get(conf, "BitExact", NULL, 0))

        enc->flags |= CODEC_FLAG_BITEXACT;

    if (av_dict_get(conf, "DctFastint", NULL, 0))

        enc->dct_algo  = FF_DCT_FASTINT;

    if (av_dict_get(conf, "IdctSimple", NULL, 0))

        enc->idct_algo = FF_IDCT_SIMPLE;

    if (av_dict_get(conf, "VideoHighQuality", NULL, 0))

        enc->mb_decision = FF_MB_DECISION_BITS;

    if ((e = av_dict_get(conf, "VideoTag", NULL, 0)))

        enc->codec_tag = MKTAG(e->value[0], e->value[1], e->value[2], e->value[3]);

    if (av_dict_get(conf, "Qscale", NULL, 0)) {

        enc->flags |= CODEC_FLAG_QSCALE;

        ffserver_set_int_param(&enc->global_quality, e->value, FF_QP2LAMBDA, INT_MIN, INT_MAX, NULL, 0, NULL);

    }

    if (av_dict_get(conf, "Video4MotionVector", NULL, 0)) {

        enc->mb_decision = FF_MB_DECISION_BITS; //FIXME remove

        enc->flags |= CODEC_FLAG_4MV;

    }

    //audio params

    if ((e = av_dict_get(conf, "AudioChannels", NULL, 0)))

        ffserver_set_int_param(&enc->channels, e->value, 0, INT_MIN, INT_MAX, NULL, 0, NULL);

    if ((e = av_dict_get(conf, "AudioSampleRate", NULL, 0)))

        ffserver_set_int_param(&enc->sample_rate, e->value, 0, INT_MIN, INT_MAX, NULL, 0, NULL);

    if ((e = av_dict_get(conf, "AudioBitRate", NULL, 0)))

        ffserver_set_int_param(&enc->bit_rate, e->value, 0, INT_MIN, INT_MAX, NULL, 0, NULL);



    av_opt_set_dict2(enc, opts, AV_OPT_SEARCH_CHILDREN);

    e = NULL;

    while (e = av_dict_get(*opts, "", e, AV_DICT_IGNORE_SUFFIX)) {

        av_log(NULL, AV_LOG_ERROR, "Provided AVOption '%s' doesn't match any existing option.\n", e->key);

        ret = AVERROR(EINVAL);

    }



    return ret;

}

int avfilter_graph_parse(AVFilterGraph *graph, const char *filters,

                         AVFilterInOut **open_inputs, AVFilterInOut **open_outputs,

                         void *log_ctx)

{

    int index = 0, ret;

    char chr = 0;



    AVFilterInOut *curr_inputs = NULL;



    do {

        AVFilterContext *filter;

        const char *filterchain = filters;

        filters += strspn(filters, WHITESPACES);



        if ((ret = parse_inputs(&filters, &curr_inputs, open_outputs, log_ctx)) < 0)

            goto fail;



        if ((ret = parse_filter(&filter, &filters, graph, index, log_ctx)) < 0)

            goto fail;



        if (filter->input_count == 1 && !curr_inputs && !index) {

            /* First input can be omitted if it is "[in]" */

            const char *tmp = "[in]";

            if ((ret = parse_inputs(&tmp, &curr_inputs, open_outputs, log_ctx)) < 0)

                goto fail;

        }



        if ((ret = link_filter_inouts(filter, &curr_inputs, open_inputs, log_ctx)) < 0)

            goto fail;



        if ((ret = parse_outputs(&filters, &curr_inputs, open_inputs, open_outputs,

                                 log_ctx)) < 0)

            goto fail;



        filters += strspn(filters, WHITESPACES);

        chr = *filters++;



        if (chr == ';' && curr_inputs) {

            av_log(log_ctx, AV_LOG_ERROR,

                   "Invalid filterchain containing an unlabelled output pad: \"%s\"\n",

                   filterchain);

            ret = AVERROR(EINVAL);

            goto fail;

        }

        index++;

    } while (chr == ',' || chr == ';');



    if (chr) {

        av_log(log_ctx, AV_LOG_ERROR,

               "Unable to parse graph description substring: \"%s\"\n",

               filters - 1);

        ret = AVERROR(EINVAL);

        goto fail;

    }



    if (*open_inputs && !strcmp((*open_inputs)->name, "out") && curr_inputs) {

        /* Last output can be omitted if it is "[out]" */

        const char *tmp = "[out]";

        if ((ret = parse_outputs(&tmp, &curr_inputs, open_inputs, open_outputs,

                                 log_ctx)) < 0)

            goto fail;

    }



    return 0;



 fail:

    for (; graph->filter_count > 0; graph->filter_count--)

        avfilter_free(graph->filters[graph->filter_count - 1]);

    av_freep(&graph->filters);

    avfilter_inout_free(open_inputs);

    avfilter_inout_free(open_outputs);

    avfilter_inout_free(&curr_inputs);

    return ret;

}

static int libopenjpeg_decode_frame(AVCodecContext *avctx,

                                    void *data, int *data_size,

                                    AVPacket *avpkt)

{

    uint8_t *buf = avpkt->data;

    int buf_size = avpkt->size;

    LibOpenJPEGContext *ctx = avctx->priv_data;

    AVFrame *picture = &ctx->image, *output = data;

    opj_dinfo_t *dec;

    opj_cio_t *stream;

    opj_image_t *image;

    int width, height, ret = -1;

    int pixel_size = 0;

    int ispacked = 0;



    *data_size = 0;



    // Check if input is a raw jpeg2k codestream or in jp2 wrapping

    if((AV_RB32(buf) == 12) &&

       (AV_RB32(buf + 4) == JP2_SIG_TYPE) &&

       (AV_RB32(buf + 8) == JP2_SIG_VALUE)) {

        dec = opj_create_decompress(CODEC_JP2);

    } else {

        // If the AVPacket contains a jp2c box, then skip to

        // the starting byte of the codestream.

        if (AV_RB32(buf + 4) == AV_RB32("jp2c"))

            buf += 8;

        dec = opj_create_decompress(CODEC_J2K);




    if(!dec) {

        av_log(avctx, AV_LOG_ERROR, "Error initializing decoder.\n");



    opj_set_event_mgr((opj_common_ptr)dec, NULL, NULL);



    ctx->dec_params.cp_limit_decoding = LIMIT_TO_MAIN_HEADER;

    // Tie decoder with decoding parameters

    opj_setup_decoder(dec, &ctx->dec_params);

    stream = opj_cio_open((opj_common_ptr)dec, buf, buf_size);

    if(!stream) {

        av_log(avctx, AV_LOG_ERROR, "Codestream could not be opened for reading.\n");






    // Decode the header only

    image = opj_decode_with_info(dec, stream, NULL);

    opj_cio_close(stream);






    width  = image->x1 - image->x0;

    height = image->y1 - image->y0;

    if(av_image_check_size(width, height, 0, avctx) < 0) {

        av_log(avctx, AV_LOG_ERROR, "%dx%d dimension invalid.\n", width, height);

        goto done;


    avcodec_set_dimensions(avctx, width, height);



    switch (image->numcomps) {

    case 1:  avctx->pix_fmt = (image->comps[0].bpp == 8) ? PIX_FMT_GRAY8 : PIX_FMT_GRAY16;

             break;

    case 2:  avctx->pix_fmt = PIX_FMT_GRAY8A;

             break;

    case 3:

    case 4:  avctx->pix_fmt = check_image_attributes(avctx, image);

             break;

    default: av_log(avctx, AV_LOG_ERROR, "%d components unsupported.\n", image->numcomps);

             goto done;




    if(picture->data[0])

        ff_thread_release_buffer(avctx, picture);



    if(ff_thread_get_buffer(avctx, picture) < 0){

        av_log(avctx, AV_LOG_ERROR, "ff_thread_get_buffer() failed\n");





    ctx->dec_params.cp_limit_decoding = NO_LIMITATION;

    ctx->dec_params.cp_reduce = avctx->lowres;

    // Tie decoder with decoding parameters

    opj_setup_decoder(dec, &ctx->dec_params);

    stream = opj_cio_open((opj_common_ptr)dec, buf, buf_size);

    if(!stream) {

        av_log(avctx, AV_LOG_ERROR, "Codestream could not be opened for reading.\n");






    // Decode the codestream

    image = opj_decode_with_info(dec, stream, NULL);

    opj_cio_close(stream);








    pixel_size = av_pix_fmt_descriptors[avctx->pix_fmt].comp[0].step_minus1 + 1;

    ispacked = libopenjpeg_ispacked(avctx->pix_fmt);



    switch (pixel_size) {

    case 1:

        if (ispacked) {

            libopenjpeg_copy_to_packed8(picture, image);

        } else {

            libopenjpeg_copyto8(picture, image);


        break;

    case 2:

        if (ispacked) {

            libopenjpeg_copy_to_packed8(picture, image);

        } else {

            libopenjpeg_copyto16(picture, image);


        break;

    case 3:

    case 4:

        if (ispacked) {

            libopenjpeg_copy_to_packed8(picture, image);


        break;

    case 6:

    case 8:

        if (ispacked) {

            libopenjpeg_copy_to_packed16(picture, image);


        break;

    default:

        av_log(avctx, AV_LOG_ERROR, "unsupported pixel size %d\n", pixel_size);

        goto done;




    *output    = ctx->image;

    *data_size = sizeof(AVPicture);

    ret = buf_size;



done:

    opj_image_destroy(image);


    return ret;

void ffv1_clear_slice_state(FFV1Context *f, FFV1Context *fs)

{

    int i, j;



    for (i = 0; i < f->plane_count; i++) {

        PlaneContext *p = &fs->plane[i];



        p->interlace_bit_state[0] = 128;

        p->interlace_bit_state[1] = 128;



        if (fs->ac) {

            if (f->initial_states[p->quant_table_index]) {

                memcpy(p->state, f->initial_states[p->quant_table_index],

                       CONTEXT_SIZE * p->context_count);

            } else

                memset(p->state, 128, CONTEXT_SIZE * p->context_count);

        } else {

            for (j = 0; j < p->context_count; j++) {

                p->vlc_state[j].drift     = 0;

                p->vlc_state[j].error_sum = 4;    //FFMAX((RANGE + 32)/64, 2);

                p->vlc_state[j].bias      = 0;

                p->vlc_state[j].count     = 1;

            }

        }

    }

}

static int av_buffersrc_add_frame_internal(AVFilterContext *ctx,

                                           AVFrame *frame, int flags)

{

    BufferSourceContext *s = ctx->priv;

    AVFrame *copy;

    int ret;



    if (!frame) {

        s->eof = 1;

        return 0;

    } else if (s->eof)

        return AVERROR(EINVAL);



    if (!(flags & AV_BUFFERSRC_FLAG_NO_CHECK_FORMAT)) {



    switch (ctx->outputs[0]->type) {

    case AVMEDIA_TYPE_VIDEO:

        CHECK_VIDEO_PARAM_CHANGE(ctx, s, frame->width, frame->height,

                                 frame->format);

        break;

    case AVMEDIA_TYPE_AUDIO:

        CHECK_AUDIO_PARAM_CHANGE(ctx, s, frame->sample_rate, frame->channel_layout,

                                 frame->format);

        break;

    default:

        return AVERROR(EINVAL);

    }



    }



    if (!av_fifo_space(s->fifo) &&

        (ret = av_fifo_realloc2(s->fifo, av_fifo_size(s->fifo) +

                                         sizeof(copy))) < 0)

        return ret;



    if (!(copy = av_frame_alloc()))

        return AVERROR(ENOMEM);

    av_frame_move_ref(copy, frame);



    if ((ret = av_fifo_generic_write(s->fifo, &copy, sizeof(copy), NULL)) < 0) {

        av_frame_move_ref(frame, copy);

        av_frame_free(&copy);

        return ret;

    }



    if ((flags & AV_BUFFERSRC_FLAG_PUSH))

        if ((ret = ctx->output_pads[0].request_frame(ctx->outputs[0])) < 0)

            return ret;



    return 0;

}

static int asf_read_seek(AVFormatContext *s, int stream_index, int64_t pts, int flags)

{

    ASFContext *asf = s->priv_data;

    AVStream *st = s->streams[stream_index];

    int64_t pos;

    int index;



    if (s->packet_size <= 0)

        return -1;



    /* Try using the protocol's read_seek if available */

    if(s->pb) {

        int ret = avio_seek_time(s->pb, stream_index, pts, flags);

        if(ret >= 0)

            asf_reset_header(s);

        if (ret != AVERROR(ENOSYS))

            return ret;

    }



    if (!asf->index_read)

        asf_build_simple_index(s, stream_index);



    if((asf->index_read && st->index_entries)){

        index= av_index_search_timestamp(st, pts, flags);

        if(index >= 0) {

            /* find the position */

            pos = st->index_entries[index].pos;



            /* do the seek */

            av_log(s, AV_LOG_DEBUG, "SEEKTO: %"PRId64"\n", pos);

            avio_seek(s->pb, pos, SEEK_SET);

            asf_reset_header(s);

            return 0;

        }

    }

    /* no index or seeking by index failed */

    if(av_seek_frame_binary(s, stream_index, pts, flags)<0)

        return -1;

    asf_reset_header(s);

    return 0;

}

static void decode(RA288Context *ractx, float gain, int cb_coef)

{

    int i, j;

    double sumsum;

    float sum, buffer[5];



    memmove(ractx->sp_block + 5, ractx->sp_block, 36*sizeof(*ractx->sp_block));



    for (i=4; i >= 0; i--)

        ractx->sp_block[i] = -scalar_product_float(ractx->sp_block + i + 1,

                                             ractx->sp_lpc, 36);



    /* block 46 of G.728 spec */

    sum = 32. - scalar_product_float(ractx->gain_lpc, ractx->gain_block, 10);



    /* block 47 of G.728 spec */

    sum = av_clipf(sum, 0, 60);



    /* block 48 of G.728 spec */

    sumsum = exp(sum * 0.1151292546497) * gain; /* pow(10.0,sum/20)*gain */



    for (i=0; i < 5; i++)

        buffer[i] = codetable[cb_coef][i] * sumsum;



    sum = scalar_product_float(buffer, buffer, 5) / 5;



    sum = FFMAX(sum, 1);



    /* shift and store */

    memmove(ractx->gain_block, ractx->gain_block - 1,

            10 * sizeof(*ractx->gain_block));



    *ractx->gain_block = 10 * log10(sum) - 32;



    for (i=1; i < 5; i++)

        for (j=i-1; j >= 0; j--)

            buffer[i] -= ractx->sp_lpc[i-j-1] * buffer[j];



    /* output */

    for (i=0; i < 5; i++)

        ractx->sp_block[4-i] =

            av_clipf(ractx->sp_block[4-i] + buffer[i], -4095, 4095);

}

static void color16(WaveformContext *s, AVFrame *in, AVFrame *out,

                    int component, int intensity, int offset, int column)

{

    const int plane = s->desc->comp[component].plane;

    const int mirror = s->mirror;

    const int limit = s->size - 1;

    const uint16_t *c0_data = (const uint16_t *)in->data[plane + 0];

    const uint16_t *c1_data = (const uint16_t *)in->data[(plane + 1) % s->ncomp];

    const uint16_t *c2_data = (const uint16_t *)in->data[(plane + 2) % s->ncomp];

    const int c0_linesize = in->linesize[ plane + 0 ] / 2;

    const int c1_linesize = in->linesize[(plane + 1) % s->ncomp] / 2;

    const int c2_linesize = in->linesize[(plane + 2) % s->ncomp] / 2;

    const int d0_linesize = out->linesize[ plane + 0 ] / 2;

    const int d1_linesize = out->linesize[(plane + 1) % s->ncomp] / 2;

    const int d2_linesize = out->linesize[(plane + 2) % s->ncomp] / 2;

    const int src_h = in->height;

    const int src_w = in->width;

    int x, y;



    if (s->mode) {

        const int d0_signed_linesize = d0_linesize * (mirror == 1 ? -1 : 1);

        const int d1_signed_linesize = d1_linesize * (mirror == 1 ? -1 : 1);

        const int d2_signed_linesize = d2_linesize * (mirror == 1 ? -1 : 1);

        uint16_t *d0_data = (uint16_t *)out->data[plane] + offset * d0_linesize;

        uint16_t *d1_data = (uint16_t *)out->data[(plane + 1) % s->ncomp] + offset * d1_linesize;

        uint16_t *d2_data = (uint16_t *)out->data[(plane + 2) % s->ncomp] + offset * d2_linesize;

        uint16_t * const d0_bottom_line = d0_data + d0_linesize * (s->size - 1);

        uint16_t * const d0 = (mirror ? d0_bottom_line : d0_data);

        uint16_t * const d1_bottom_line = d1_data + d1_linesize * (s->size - 1);

        uint16_t * const d1 = (mirror ? d1_bottom_line : d1_data);

        uint16_t * const d2_bottom_line = d2_data + d2_linesize * (s->size - 1);

        uint16_t * const d2 = (mirror ? d2_bottom_line : d2_data);



        for (y = 0; y < src_h; y++) {

            for (x = 0; x < src_w; x++) {

                const int c0 = FFMIN(c0_data[x], limit);

                const int c1 = c1_data[x];

                const int c2 = c2_data[x];



                *(d0 + d0_signed_linesize * c0 + x) = c0;

                *(d1 + d1_signed_linesize * c0 + x) = c1;

                *(d2 + d2_signed_linesize * c0 + x) = c2;

            }



            c0_data += c0_linesize;

            c1_data += c1_linesize;

            c2_data += c2_linesize;

            d0_data += d0_linesize;

            d1_data += d1_linesize;

            d2_data += d2_linesize;

        }

    } else {

        uint16_t *d0_data = (uint16_t *)out->data[plane] + offset;

        uint16_t *d1_data = (uint16_t *)out->data[(plane + 1) % s->ncomp] + offset;

        uint16_t *d2_data = (uint16_t *)out->data[(plane + 2) % s->ncomp] + offset;



        if (mirror) {

            d0_data += s->size - 1;

            d1_data += s->size - 1;

            d2_data += s->size - 1;

        }



        for (y = 0; y < src_h; y++) {

            for (x = 0; x < src_w; x++) {

                const int c0 = FFMIN(c0_data[x], limit);

                const int c1 = c1_data[x];

                const int c2 = c2_data[x];



                if (mirror) {

                    *(d0_data - c0) = c0;

                    *(d1_data - c0) = c1;

                    *(d2_data - c0) = c2;

                } else {

                    *(d0_data + c0) = c0;

                    *(d1_data + c0) = c1;

                    *(d2_data + c0) = c2;

                }

            }



            c0_data += c0_linesize;

            c1_data += c1_linesize;

            c2_data += c2_linesize;

            d0_data += d0_linesize;

            d1_data += d1_linesize;

            d2_data += d2_linesize;

        }

    }



    envelope16(s, out, plane, plane);

}

static inline void RENAME(yuvPlanartoyuy2)(const uint8_t *ysrc, const uint8_t *usrc, const uint8_t *vsrc, uint8_t *dst,

	unsigned int width, unsigned int height,

	int lumStride, int chromStride, int dstStride, int vertLumPerChroma)

{

	unsigned y;

	const unsigned chromWidth= width>>1;

	for(y=0; y<height; y++)

	{

#ifdef HAVE_MMX

//FIXME handle 2 lines a once (fewer prefetch, reuse some chrom, but very likely limited by mem anyway)

		asm volatile(

			"xor %%"REG_a", %%"REG_a"	\n\t"

			".balign 16			\n\t"

			"1:				\n\t"

			PREFETCH" 32(%1, %%"REG_a", 2)	\n\t"

			PREFETCH" 32(%2, %%"REG_a")	\n\t"

			PREFETCH" 32(%3, %%"REG_a")	\n\t"

			"movq (%2, %%"REG_a"), %%mm0	\n\t" // U(0)

			"movq %%mm0, %%mm2		\n\t" // U(0)

			"movq (%3, %%"REG_a"), %%mm1	\n\t" // V(0)

			"punpcklbw %%mm1, %%mm0		\n\t" // UVUV UVUV(0)

			"punpckhbw %%mm1, %%mm2		\n\t" // UVUV UVUV(8)



			"movq (%1, %%"REG_a",2), %%mm3	\n\t" // Y(0)

			"movq 8(%1, %%"REG_a",2), %%mm5	\n\t" // Y(8)

			"movq %%mm3, %%mm4		\n\t" // Y(0)

			"movq %%mm5, %%mm6		\n\t" // Y(8)

			"punpcklbw %%mm0, %%mm3		\n\t" // YUYV YUYV(0)

			"punpckhbw %%mm0, %%mm4		\n\t" // YUYV YUYV(4)

			"punpcklbw %%mm2, %%mm5		\n\t" // YUYV YUYV(8)

			"punpckhbw %%mm2, %%mm6		\n\t" // YUYV YUYV(12)



			MOVNTQ" %%mm3, (%0, %%"REG_a", 4)\n\t"

			MOVNTQ" %%mm4, 8(%0, %%"REG_a", 4)\n\t"

			MOVNTQ" %%mm5, 16(%0, %%"REG_a", 4)\n\t"

			MOVNTQ" %%mm6, 24(%0, %%"REG_a", 4)\n\t"



			"add $8, %%"REG_a"		\n\t"

			"cmp %4, %%"REG_a"		\n\t"

			" jb 1b				\n\t"

			::"r"(dst), "r"(ysrc), "r"(usrc), "r"(vsrc), "g" ((long)chromWidth)

			: "%"REG_a

		);

#else



#if defined ARCH_ALPHA && defined HAVE_MVI

#define pl2yuy2(n)					\

	y1 = yc[n];					\

	y2 = yc2[n];					\

	u = uc[n];					\

	v = vc[n];					\

	asm("unpkbw %1, %0" : "=r"(y1) : "r"(y1));	\

	asm("unpkbw %1, %0" : "=r"(y2) : "r"(y2));	\

	asm("unpkbl %1, %0" : "=r"(u) : "r"(u));	\

	asm("unpkbl %1, %0" : "=r"(v) : "r"(v));	\

	yuv1 = (u << 8) + (v << 24);			\

	yuv2 = yuv1 + y2;				\

	yuv1 += y1;					\

	qdst[n] = yuv1;					\

	qdst2[n] = yuv2;



		int i;

		uint64_t *qdst = (uint64_t *) dst;

		uint64_t *qdst2 = (uint64_t *) (dst + dstStride);

		const uint32_t *yc = (uint32_t *) ysrc;

		const uint32_t *yc2 = (uint32_t *) (ysrc + lumStride);

		const uint16_t *uc = (uint16_t*) usrc, *vc = (uint16_t*) vsrc;

		for(i = 0; i < chromWidth; i += 8){

			uint64_t y1, y2, yuv1, yuv2;

			uint64_t u, v;

			/* Prefetch */

			asm("ldq $31,64(%0)" :: "r"(yc));

			asm("ldq $31,64(%0)" :: "r"(yc2));

			asm("ldq $31,64(%0)" :: "r"(uc));

			asm("ldq $31,64(%0)" :: "r"(vc));



			pl2yuy2(0);

			pl2yuy2(1);

			pl2yuy2(2);

			pl2yuy2(3);



			yc += 4;

			yc2 += 4;

			uc += 4;

			vc += 4;

			qdst += 4;

			qdst2 += 4;

		}

		y++;

		ysrc += lumStride;

		dst += dstStride;



#elif __WORDSIZE >= 64

		int i;

		uint64_t *ldst = (uint64_t *) dst;

		const uint8_t *yc = ysrc, *uc = usrc, *vc = vsrc;

		for(i = 0; i < chromWidth; i += 2){

			uint64_t k, l;

			k = yc[0] + (uc[0] << 8) +

			    (yc[1] << 16) + (vc[0] << 24);

			l = yc[2] + (uc[1] << 8) +

			    (yc[3] << 16) + (vc[1] << 24);

			*ldst++ = k + (l << 32);

			yc += 4;

			uc += 2;

			vc += 2;

		}



#else

		int i, *idst = (int32_t *) dst;

		const uint8_t *yc = ysrc, *uc = usrc, *vc = vsrc;

		for(i = 0; i < chromWidth; i++){

#ifdef WORDS_BIGENDIAN

			*idst++ = (yc[0] << 24)+ (uc[0] << 16) +

			    (yc[1] << 8) + (vc[0] << 0);

#else

			*idst++ = yc[0] + (uc[0] << 8) +

			    (yc[1] << 16) + (vc[0] << 24);

#endif

			yc += 2;

			uc++;

			vc++;

		}

#endif

#endif

		if((y&(vertLumPerChroma-1))==(vertLumPerChroma-1) )

		{

			usrc += chromStride;

			vsrc += chromStride;

		}

		ysrc += lumStride;

		dst += dstStride;

	}

#ifdef HAVE_MMX

asm(    EMMS" \n\t"

        SFENCE" \n\t"

        :::"memory");

#endif

}

static void vc1_inv_trans_4x4_dc_c(uint8_t *dest, int linesize, DCTELEM *block)

{

    int i;

    int dc = block[0];

    const uint8_t *cm;

    dc = (17 * dc +  4) >> 3;

    dc = (17 * dc + 64) >> 7;

    cm = ff_cropTbl + MAX_NEG_CROP + dc;

    for(i = 0; i < 4; i++){

        dest[0] = cm[dest[0]];

        dest[1] = cm[dest[1]];

        dest[2] = cm[dest[2]];

        dest[3] = cm[dest[3]];

        dest += linesize;

    }

}

static void read_sbr_noise(SpectralBandReplication *sbr, GetBitContext *gb,

                           SBRData *ch_data, int ch)

{

    int i, j;

    VLC_TYPE (*t_huff)[2], (*f_huff)[2];

    int t_lav, f_lav;

    int delta = (ch == 1 && sbr->bs_coupling == 1) + 1;



    if (sbr->bs_coupling && ch) {

        t_huff = vlc_sbr[T_HUFFMAN_NOISE_BAL_3_0DB].table;

        t_lav  = vlc_sbr_lav[T_HUFFMAN_NOISE_BAL_3_0DB];

        f_huff = vlc_sbr[F_HUFFMAN_ENV_BAL_3_0DB].table;

        f_lav  = vlc_sbr_lav[F_HUFFMAN_ENV_BAL_3_0DB];

    } else {

        t_huff = vlc_sbr[T_HUFFMAN_NOISE_3_0DB].table;

        t_lav  = vlc_sbr_lav[T_HUFFMAN_NOISE_3_0DB];

        f_huff = vlc_sbr[F_HUFFMAN_ENV_3_0DB].table;

        f_lav  = vlc_sbr_lav[F_HUFFMAN_ENV_3_0DB];

    }



#if USE_FIXED

    for (i = 0; i < ch_data->bs_num_noise; i++) {

        if (ch_data->bs_df_noise[i]) {

            for (j = 0; j < sbr->n_q; j++)

                ch_data->noise_facs[i + 1][j].mant = ch_data->noise_facs[i][j].mant + delta * (get_vlc2(gb, t_huff, 9, 2) - t_lav);

        } else {

            ch_data->noise_facs[i + 1][0].mant = delta * get_bits(gb, 5); // bs_noise_start_value_balance or bs_noise_start_value_level

            for (j = 1; j < sbr->n_q; j++)

                ch_data->noise_facs[i + 1][j].mant = ch_data->noise_facs[i + 1][j - 1].mant + delta * (get_vlc2(gb, f_huff, 9, 3) - f_lav);

        }

    }

#else

    for (i = 0; i < ch_data->bs_num_noise; i++) {

        if (ch_data->bs_df_noise[i]) {

            for (j = 0; j < sbr->n_q; j++)

                ch_data->noise_facs[i + 1][j] = ch_data->noise_facs[i][j] + delta * (get_vlc2(gb, t_huff, 9, 2) - t_lav);

        } else {

            ch_data->noise_facs[i + 1][0] = delta * get_bits(gb, 5); // bs_noise_start_value_balance or bs_noise_start_value_level

            for (j = 1; j < sbr->n_q; j++)

                ch_data->noise_facs[i + 1][j] = ch_data->noise_facs[i + 1][j - 1] + delta * (get_vlc2(gb, f_huff, 9, 3) - f_lav);

        }

    }

#endif /* USE_FIXED */



    //assign 0th elements of noise_facs from last elements

    memcpy(ch_data->noise_facs[0], ch_data->noise_facs[ch_data->bs_num_noise],

           sizeof(ch_data->noise_facs[0]));

}

int av_image_fill_pointers(uint8_t *data[4], enum PixelFormat pix_fmt, int height,

                           uint8_t *ptr, const int linesizes[4])

{

    int i, total_size, size[4], has_plane[4];



    const AVPixFmtDescriptor *desc = &av_pix_fmt_descriptors[pix_fmt];

    memset(data     , 0, sizeof(data[0])*4);

    memset(size     , 0, sizeof(size));

    memset(has_plane, 0, sizeof(has_plane));



    if (desc->flags & PIX_FMT_HWACCEL)

        return AVERROR(EINVAL);



    data[0] = ptr;

    size[0] = linesizes[0] * height;



    if (desc->flags & PIX_FMT_PAL) {

        size[0] = (size[0] + 3) & ~3;

        data[1] = ptr + size[0]; /* palette is stored here as 256 32 bits words */

        return size[0] + 256 * 4;

    }



    for (i = 0; i < 4; i++)

        has_plane[desc->comp[i].plane] = 1;



    total_size = size[0];

    for (i = 1; has_plane[i] && i < 4; i++) {

        int h, s = (i == 1 || i == 2) ? desc->log2_chroma_h : 0;

        data[i] = data[i-1] + size[i-1];

        h = (height + (1 << s) - 1) >> s;

        size[i] = h * linesizes[i];

        total_size += size[i];

    }



    return total_size;

}

static int pcm_decode_frame(AVCodecContext *avctx, void *data,

                            int *got_frame_ptr, AVPacket *avpkt)

{

    const uint8_t *src = avpkt->data;

    int buf_size       = avpkt->size;

    PCMDecode *s       = avctx->priv_data;

    AVFrame *frame     = data;

    int sample_size, c, n, ret, samples_per_block;

    uint8_t *samples;

    int32_t *dst_int32_t;



    sample_size = av_get_bits_per_sample(avctx->codec_id) / 8;



    /* av_get_bits_per_sample returns 0 for AV_CODEC_ID_PCM_DVD */

    samples_per_block = 1;

    if (avctx->codec->id == AV_CODEC_ID_PCM_DVD) {

        if (avctx->bits_per_coded_sample != 20 &&

            avctx->bits_per_coded_sample != 24) {

            av_log(avctx, AV_LOG_ERROR, "PCM DVD unsupported sample depth\n");

            return AVERROR(EINVAL);

        }

        /* 2 samples are interleaved per block in PCM_DVD */

        samples_per_block = 2;

        sample_size       = avctx->bits_per_coded_sample * 2 / 8;

    } else if (avctx->codec_id == AV_CODEC_ID_PCM_LXF) {

        /* we process 40-bit blocks per channel for LXF */

        samples_per_block = 2;

        sample_size       = 5;

    }



    if (sample_size == 0) {

        av_log(avctx, AV_LOG_ERROR, "Invalid sample_size\n");

        return AVERROR(EINVAL);

    }



    n = avctx->channels * sample_size;



    if (n && buf_size % n) {

        if (buf_size < n) {

            av_log(avctx, AV_LOG_ERROR, "invalid PCM packet\n");

            return -1;

        } else

            buf_size -= buf_size % n;

    }



    n = buf_size / sample_size;



    /* get output buffer */

    frame->nb_samples = n * samples_per_block / avctx->channels;

    if ((ret = ff_get_buffer(avctx, frame, 0)) < 0) {

        av_log(avctx, AV_LOG_ERROR, "get_buffer() failed\n");

        return ret;

    }

    samples = frame->data[0];



    switch (avctx->codec->id) {

    case AV_CODEC_ID_PCM_U32LE:

        DECODE(32, le32, src, samples, n, 0, 0x80000000)

        break;

    case AV_CODEC_ID_PCM_U32BE:

        DECODE(32, be32, src, samples, n, 0, 0x80000000)

        break;

    case AV_CODEC_ID_PCM_S24LE:

        DECODE(32, le24, src, samples, n, 8, 0)

        break;

    case AV_CODEC_ID_PCM_S24BE:

        DECODE(32, be24, src, samples, n, 8, 0)

        break;

    case AV_CODEC_ID_PCM_U24LE:

        DECODE(32, le24, src, samples, n, 8, 0x800000)

        break;

    case AV_CODEC_ID_PCM_U24BE:

        DECODE(32, be24, src, samples, n, 8, 0x800000)

        break;

    case AV_CODEC_ID_PCM_S24DAUD:

        for (; n > 0; n--) {

            uint32_t v = bytestream_get_be24(&src);

            v >>= 4; // sync flags are here

            AV_WN16A(samples, ff_reverse[(v >> 8) & 0xff] +

                             (ff_reverse[v        & 0xff] << 8));

            samples += 2;

        }

        break;

    case AV_CODEC_ID_PCM_S16LE_PLANAR:

    {

        int av_unused n2;

        n /= avctx->channels;

        for (c = 0; c < avctx->channels; c++) {

            samples = frame->extended_data[c];

#if HAVE_BIGENDIAN

            n2 = n;

            DECODE(16, le16, src, samples, n2, 0, 0)

#else

            memcpy(samples, src, n * 2);

            src += n * 2;

#endif

        }

        break;

    }

    case AV_CODEC_ID_PCM_U16LE:

        DECODE(16, le16, src, samples, n, 0, 0x8000)

        break;

    case AV_CODEC_ID_PCM_U16BE:

        DECODE(16, be16, src, samples, n, 0, 0x8000)

        break;

    case AV_CODEC_ID_PCM_S8:

        for (; n > 0; n--)

            *samples++ = *src++ + 128;

        break;

#if HAVE_BIGENDIAN

    case AV_CODEC_ID_PCM_F64LE:

        DECODE(64, le64, src, samples, n, 0, 0)

        break;

    case AV_CODEC_ID_PCM_S32LE:

    case AV_CODEC_ID_PCM_F32LE:

        DECODE(32, le32, src, samples, n, 0, 0)

        break;

    case AV_CODEC_ID_PCM_S16LE:

        DECODE(16, le16, src, samples, n, 0, 0)

        break;

    case AV_CODEC_ID_PCM_F64BE:

    case AV_CODEC_ID_PCM_F32BE:

    case AV_CODEC_ID_PCM_S32BE:

    case AV_CODEC_ID_PCM_S16BE:

#else

    case AV_CODEC_ID_PCM_F64BE:

        DECODE(64, be64, src, samples, n, 0, 0)

        break;

    case AV_CODEC_ID_PCM_F32BE:

    case AV_CODEC_ID_PCM_S32BE:

        DECODE(32, be32, src, samples, n, 0, 0)

        break;

    case AV_CODEC_ID_PCM_S16BE:

        DECODE(16, be16, src, samples, n, 0, 0)

        break;

    case AV_CODEC_ID_PCM_F64LE:

    case AV_CODEC_ID_PCM_F32LE:

    case AV_CODEC_ID_PCM_S32LE:

    case AV_CODEC_ID_PCM_S16LE:

#endif /* HAVE_BIGENDIAN */

    case AV_CODEC_ID_PCM_U8:

        memcpy(samples, src, n * sample_size);

        break;

    case AV_CODEC_ID_PCM_ZORK:

        for (; n > 0; n--) {

            int v = *src++;

            if (v < 128)

                v = 128 - v;

            *samples++ = v;

        }

        break;

    case AV_CODEC_ID_PCM_ALAW:

    case AV_CODEC_ID_PCM_MULAW:

        for (; n > 0; n--) {

            AV_WN16A(samples, s->table[*src++]);

            samples += 2;

        }

        break;

    case AV_CODEC_ID_PCM_DVD:

    {

        const uint8_t *src8;

        dst_int32_t = (int32_t *)frame->data[0];

        n /= avctx->channels;

        switch (avctx->bits_per_coded_sample) {

        case 20:

            while (n--) {

                c    = avctx->channels;

                src8 = src + 4 * c;

                while (c--) {

                    *dst_int32_t++ = (bytestream_get_be16(&src) << 16) + ((*src8   & 0xf0) <<  8);

                    *dst_int32_t++ = (bytestream_get_be16(&src) << 16) + ((*src8++ & 0x0f) << 12);

                }

                src = src8;

            }

            break;

        case 24:

            while (n--) {

                c    = avctx->channels;

                src8 = src + 4 * c;

                while (c--) {

                    *dst_int32_t++ = (bytestream_get_be16(&src) << 16) + ((*src8++) << 8);

                    *dst_int32_t++ = (bytestream_get_be16(&src) << 16) + ((*src8++) << 8);

                }

                src = src8;

            }

            break;

        }

        break;

    }

    case AV_CODEC_ID_PCM_LXF:

    {

        int i;

        n /= avctx->channels;

        for (c = 0; c < avctx->channels; c++) {

            dst_int32_t = (int32_t *)frame->extended_data[c];

            for (i = 0; i < n; i++) {

                // extract low 20 bits and expand to 32 bits

                *dst_int32_t++ =  (src[2]         << 28) |

                                  (src[1]         << 20) |

                                  (src[0]         << 12) |

                                 ((src[2] & 0x0F) <<  8) |

                                   src[1];

                // extract high 20 bits and expand to 32 bits

                *dst_int32_t++ =  (src[4]         << 24) |

                                  (src[3]         << 16) |

                                 ((src[2] & 0xF0) <<  8) |

                                  (src[4]         <<  4) |

                                  (src[3]         >>  4);

                src += 5;

            }

        }

        break;

    }

    default:

        return -1;

    }



    *got_frame_ptr = 1;



    return buf_size;

}

void ff_thread_await_progress(ThreadFrame *f, int n, int field)

{

    PerThreadContext *p;

    atomic_int *progress = f->progress ? (atomic_int*)f->progress->data : NULL;



    if (!progress ||

        atomic_load_explicit(&progress[field], memory_order_acquire) >= n)

        return;



    p = f->owner[field]->internal->thread_ctx;



    pthread_mutex_lock(&p->progress_mutex);

    if (f->owner[field]->debug&FF_DEBUG_THREADS)

        av_log(f->owner[field], AV_LOG_DEBUG,

               "thread awaiting %d field %d from %p\n", n, field, progress);

    while (atomic_load_explicit(&progress[field], memory_order_relaxed) < n)

        pthread_cond_wait(&p->progress_cond, &p->progress_mutex);

    pthread_mutex_unlock(&p->progress_mutex);

}

AVResampleContext *av_resample_init(int out_rate, int in_rate, int filter_size, int phase_shift, int linear, double cutoff){

    AVResampleContext *c= av_mallocz(sizeof(AVResampleContext));

    double factor= FFMIN(out_rate * cutoff / in_rate, 1.0);

    int phase_count= 1<<phase_shift;



    c->phase_shift= phase_shift;

    c->phase_mask= phase_count-1;

    c->linear= linear;



    c->filter_length= FFMAX(ceil(filter_size/factor), 1);

    c->filter_bank= av_mallocz(c->filter_length*(phase_count+1)*sizeof(FELEM));

    av_build_filter(c->filter_bank, factor, c->filter_length, phase_count, 1<<FILTER_SHIFT, 1);

    memcpy(&c->filter_bank[c->filter_length*phase_count+1], c->filter_bank, (c->filter_length-1)*sizeof(FELEM));

    c->filter_bank[c->filter_length*phase_count]= c->filter_bank[c->filter_length - 1];



    c->src_incr= out_rate;

    c->ideal_dst_incr= c->dst_incr= in_rate * phase_count;

    c->index= -phase_count*((c->filter_length-1)/2);



    return c;

}

static int mov_read_elst(MOVContext *c, ByteIOContext *pb, MOVAtom atom)

{

    MOVStreamContext *sc = c->fc->streams[c->fc->nb_streams-1]->priv_data;

    int i, edit_count;



    get_byte(pb); /* version */

    get_be24(pb); /* flags */

    edit_count= sc->edit_count = get_be32(pb);     /* entries */



    for(i=0; i<edit_count; i++){

        int time;

        get_be32(pb); /* Track duration */

        time = get_be32(pb); /* Media time */

        get_be32(pb); /* Media rate */

        if (time != 0)

            av_log(c->fc, AV_LOG_WARNING, "edit list not starting at 0, "

                   "a/v desync might occur, patch welcome\n");

    }

    dprintf(c->fc, "track[%i].edit_count = %i\n", c->fc->nb_streams-1, sc->edit_count);

    return 0;

}

static int decode_vop_header(MpegEncContext *s, GetBitContext *gb){

    int time_incr, time_increment;



    s->pict_type = get_bits(gb, 2) + I_TYPE;	/* pict type: I = 0 , P = 1 */

    if(s->pict_type==B_TYPE && s->low_delay && s->vol_control_parameters==0 && !(s->flags & CODEC_FLAG_LOW_DELAY)){

        av_log(s->avctx, AV_LOG_ERROR, "low_delay flag set, but shouldnt, clearing it\n");

        s->low_delay=0;

    }



    s->partitioned_frame= s->data_partitioning && s->pict_type!=B_TYPE;

    if(s->partitioned_frame)

        s->decode_mb= mpeg4_decode_partitioned_mb;

    else

        s->decode_mb= ff_h263_decode_mb;



    if(s->time_increment_resolution==0){

        s->time_increment_resolution=1;

//        fprintf(stderr, "time_increment_resolution is illegal\n");

    }

    time_incr=0;

    while (get_bits1(gb) != 0) 

        time_incr++;



    check_marker(gb, "before time_increment");



    if(s->time_increment_bits==0){

        av_log(s->avctx, AV_LOG_ERROR, "hmm, seems the headers arnt complete, trying to guess time_increment_bits\n");



        for(s->time_increment_bits=1 ;s->time_increment_bits<16; s->time_increment_bits++){

            if(show_bits(gb, s->time_increment_bits+1)&1) break;

        }



        av_log(s->avctx, AV_LOG_ERROR, "my guess is %d bits ;)\n",s->time_increment_bits);

    }



    if(IS_3IV1) time_increment= get_bits1(gb); //FIXME investigate further

    else time_increment= get_bits(gb, s->time_increment_bits);



//    printf("%d %X\n", s->time_increment_bits, time_increment);

//printf(" type:%d modulo_time_base:%d increment:%d\n", s->pict_type, time_incr, time_increment);

    if(s->pict_type!=B_TYPE){

        s->last_time_base= s->time_base;

        s->time_base+= time_incr;

        s->time= s->time_base*s->time_increment_resolution + time_increment;

        if(s->workaround_bugs&FF_BUG_UMP4){

            if(s->time < s->last_non_b_time){

//                fprintf(stderr, "header is not mpeg4 compatible, broken encoder, trying to workaround\n");

                s->time_base++;

                s->time+= s->time_increment_resolution;

            }

        }

        s->pp_time= s->time - s->last_non_b_time;

        s->last_non_b_time= s->time;

    }else{

        s->time= (s->last_time_base + time_incr)*s->time_increment_resolution + time_increment;

        s->pb_time= s->pp_time - (s->last_non_b_time - s->time);

        if(s->pp_time <=s->pb_time || s->pp_time <= s->pp_time - s->pb_time || s->pp_time<=0){

//            printf("messed up order, seeking?, skiping current b frame\n");

            return FRAME_SKIPED;

        }



        if(s->t_frame==0) s->t_frame= s->time - s->last_time_base;

        if(s->t_frame==0) s->t_frame=1; // 1/0 protection

//printf("%Ld %Ld %d %d\n", s->last_non_b_time, s->time, s->pp_time, s->t_frame); fflush(stdout);

        s->pp_field_time= (  ROUNDED_DIV(s->last_non_b_time, s->t_frame) 

                           - ROUNDED_DIV(s->last_non_b_time - s->pp_time, s->t_frame))*2;

        s->pb_field_time= (  ROUNDED_DIV(s->time, s->t_frame) 

                           - ROUNDED_DIV(s->last_non_b_time - s->pp_time, s->t_frame))*2;

    }



    s->current_picture_ptr->pts= s->time*1000LL*1000LL / s->time_increment_resolution;

    if(s->avctx->debug&FF_DEBUG_PTS)

        av_log(s->avctx, AV_LOG_DEBUG, "MPEG4 PTS: %f\n", s->current_picture_ptr->pts/(1000.0*1000.0));



    check_marker(gb, "before vop_coded");



    /* vop coded */

    if (get_bits1(gb) != 1){

        av_log(s->avctx, AV_LOG_ERROR, "vop not coded\n");

        return FRAME_SKIPED;

    }

//printf("time %d %d %d || %Ld %Ld %Ld\n", s->time_increment_bits, s->time_increment_resolution, s->time_base,

//s->time, s->last_non_b_time, s->last_non_b_time - s->pp_time);  

    if (s->shape != BIN_ONLY_SHAPE && ( s->pict_type == P_TYPE

                          || (s->pict_type == S_TYPE && s->vol_sprite_usage==GMC_SPRITE))) {

        /* rounding type for motion estimation */

	s->no_rounding = get_bits1(gb);

    } else {

	s->no_rounding = 0;

    }

//FIXME reduced res stuff



     if (s->shape != RECT_SHAPE) {

         if (s->vol_sprite_usage != 1 || s->pict_type != I_TYPE) {

             int width, height, hor_spat_ref, ver_spat_ref;



             width = get_bits(gb, 13);

             skip_bits1(gb);   /* marker */

             height = get_bits(gb, 13);

             skip_bits1(gb);   /* marker */

             hor_spat_ref = get_bits(gb, 13); /* hor_spat_ref */

             skip_bits1(gb);   /* marker */

             ver_spat_ref = get_bits(gb, 13); /* ver_spat_ref */

         }

         skip_bits1(gb); /* change_CR_disable */



         if (get_bits1(gb) != 0) {

             skip_bits(gb, 8); /* constant_alpha_value */

         }

     }

//FIXME complexity estimation stuff



     if (s->shape != BIN_ONLY_SHAPE) {

         s->intra_dc_threshold= mpeg4_dc_threshold[ get_bits(gb, 3) ];

         if(!s->progressive_sequence){

             s->top_field_first= get_bits1(gb);

             s->alternate_scan= get_bits1(gb);

         }else

             s->alternate_scan= 0;

     }



     if(s->alternate_scan){

         ff_init_scantable(s->dsp.idct_permutation, &s->inter_scantable  , ff_alternate_vertical_scan);

         ff_init_scantable(s->dsp.idct_permutation, &s->intra_scantable  , ff_alternate_vertical_scan);

         ff_init_scantable(s->dsp.idct_permutation, &s->intra_h_scantable, ff_alternate_vertical_scan);

         ff_init_scantable(s->dsp.idct_permutation, &s->intra_v_scantable, ff_alternate_vertical_scan);

     } else{

         ff_init_scantable(s->dsp.idct_permutation, &s->inter_scantable  , ff_zigzag_direct);

         ff_init_scantable(s->dsp.idct_permutation, &s->intra_scantable  , ff_zigzag_direct);

         ff_init_scantable(s->dsp.idct_permutation, &s->intra_h_scantable, ff_alternate_horizontal_scan);

         ff_init_scantable(s->dsp.idct_permutation, &s->intra_v_scantable, ff_alternate_vertical_scan);

     }



     if(s->pict_type == S_TYPE && (s->vol_sprite_usage==STATIC_SPRITE || s->vol_sprite_usage==GMC_SPRITE)){

         mpeg4_decode_sprite_trajectory(s);

         if(s->sprite_brightness_change) av_log(s->avctx, AV_LOG_ERROR, "sprite_brightness_change not supported\n");

         if(s->vol_sprite_usage==STATIC_SPRITE) av_log(s->avctx, AV_LOG_ERROR, "static sprite not supported\n");

     }



     if (s->shape != BIN_ONLY_SHAPE) {

         s->qscale = get_bits(gb, s->quant_precision);

         if(s->qscale==0){

             av_log(s->avctx, AV_LOG_ERROR, "Error, header damaged or not MPEG4 header (qscale=0)\n");

             return -1; // makes no sense to continue, as there is nothing left from the image then

         }



         if (s->pict_type != I_TYPE) {

             s->f_code = get_bits(gb, 3);	/* fcode_for */

             if(s->f_code==0){

                 av_log(s->avctx, AV_LOG_ERROR, "Error, header damaged or not MPEG4 header (f_code=0)\n");

                 return -1; // makes no sense to continue, as the MV decoding will break very quickly

             }

         }else

             s->f_code=1;



         if (s->pict_type == B_TYPE) {

             s->b_code = get_bits(gb, 3);

         }else

             s->b_code=1;



         if(s->avctx->debug&FF_DEBUG_PICT_INFO){

             av_log(s->avctx, AV_LOG_DEBUG, "qp:%d fc:%d,%d %s size:%d pro:%d alt:%d top:%d %spel part:%d resync:%d w:%d a:%d rnd:%d vot:%d%s dc:%d\n", 

                 s->qscale, s->f_code, s->b_code, 

                 s->pict_type == I_TYPE ? "I" : (s->pict_type == P_TYPE ? "P" : (s->pict_type == B_TYPE ? "B" : "S")), 

                 gb->size_in_bits,s->progressive_sequence, s->alternate_scan, s->top_field_first, 

                 s->quarter_sample ? "q" : "h", s->data_partitioning, s->resync_marker, s->num_sprite_warping_points,

                 s->sprite_warping_accuracy, 1-s->no_rounding, s->vo_type, s->vol_control_parameters ? " VOLC" : " ", s->intra_dc_threshold); 

         }



         if(!s->scalability){

             if (s->shape!=RECT_SHAPE && s->pict_type!=I_TYPE) {

                 skip_bits1(gb); // vop shape coding type

             }

         }else{

             if(s->enhancement_type){

                 int load_backward_shape= get_bits1(gb);

                 if(load_backward_shape){

                     av_log(s->avctx, AV_LOG_ERROR, "load backward shape isnt supported\n");

                 }

             }

             skip_bits(gb, 2); //ref_select_code

         }

     }

     /* detect buggy encoders which dont set the low_delay flag (divx4/xvid/opendivx)*/

     // note we cannot detect divx5 without b-frames easyly (allthough its buggy too)

     if(s->vo_type==0 && s->vol_control_parameters==0 && s->divx_version==0 && s->picture_number==0){

         av_log(s->avctx, AV_LOG_ERROR, "looks like this file was encoded with (divx4/(old)xvid/opendivx) -> forcing low_delay flag\n");

         s->low_delay=1;

     }



     s->picture_number++; // better than pic number==0 allways ;)



     s->y_dc_scale_table= ff_mpeg4_y_dc_scale_table; //FIXME add short header support 

     s->c_dc_scale_table= ff_mpeg4_c_dc_scale_table;



     if(s->workaround_bugs&FF_BUG_EDGE){

         s->h_edge_pos= s->width;

         s->v_edge_pos= s->height;

     }

     return 0;

}

static inline void RENAME(uyvytoyv12)(const uint8_t *src, uint8_t *ydst, uint8_t *udst, uint8_t *vdst,

	long width, long height,

	long lumStride, long chromStride, long srcStride)

{

	long y;

	const long chromWidth= width>>1;

	for(y=0; y<height; y+=2)

	{

#ifdef HAVE_MMX

		asm volatile(

			"xorl %%eax, %%eax		\n\t"

			"pcmpeqw %%mm7, %%mm7		\n\t"

			"psrlw $8, %%mm7		\n\t" // FF,00,FF,00...

			ASMALIGN(4)

			"1:				\n\t"

			PREFETCH" 64(%0, %%eax, 4)	\n\t"

			"movq (%0, %%eax, 4), %%mm0	\n\t" // UYVY UYVY(0)

			"movq 8(%0, %%eax, 4), %%mm1	\n\t" // UYVY UYVY(4)

			"movq %%mm0, %%mm2		\n\t" // UYVY UYVY(0)

			"movq %%mm1, %%mm3		\n\t" // UYVY UYVY(4)

			"pand %%mm7, %%mm0		\n\t" // U0V0 U0V0(0)

			"pand %%mm7, %%mm1		\n\t" // U0V0 U0V0(4)

			"psrlw $8, %%mm2		\n\t" // Y0Y0 Y0Y0(0)

			"psrlw $8, %%mm3		\n\t" // Y0Y0 Y0Y0(4)

			"packuswb %%mm1, %%mm0		\n\t" // UVUV UVUV(0)

			"packuswb %%mm3, %%mm2		\n\t" // YYYY YYYY(0)



			MOVNTQ" %%mm2, (%1, %%eax, 2)	\n\t"



			"movq 16(%0, %%eax, 4), %%mm1	\n\t" // UYVY UYVY(8)

			"movq 24(%0, %%eax, 4), %%mm2	\n\t" // UYVY UYVY(12)

			"movq %%mm1, %%mm3		\n\t" // UYVY UYVY(8)

			"movq %%mm2, %%mm4		\n\t" // UYVY UYVY(12)

			"pand %%mm7, %%mm1		\n\t" // U0V0 U0V0(8)

			"pand %%mm7, %%mm2		\n\t" // U0V0 U0V0(12)

			"psrlw $8, %%mm3		\n\t" // Y0Y0 Y0Y0(8)

			"psrlw $8, %%mm4		\n\t" // Y0Y0 Y0Y0(12)

			"packuswb %%mm2, %%mm1		\n\t" // UVUV UVUV(8)

			"packuswb %%mm4, %%mm3		\n\t" // YYYY YYYY(8)



			MOVNTQ" %%mm3, 8(%1, %%eax, 2)	\n\t"



			"movq %%mm0, %%mm2		\n\t" // UVUV UVUV(0)

			"movq %%mm1, %%mm3		\n\t" // UVUV UVUV(8)

			"psrlw $8, %%mm0		\n\t" // V0V0 V0V0(0)

			"psrlw $8, %%mm1		\n\t" // V0V0 V0V0(8)

			"pand %%mm7, %%mm2		\n\t" // U0U0 U0U0(0)

			"pand %%mm7, %%mm3		\n\t" // U0U0 U0U0(8)

			"packuswb %%mm1, %%mm0		\n\t" // VVVV VVVV(0)

			"packuswb %%mm3, %%mm2		\n\t" // UUUU UUUU(0)



			MOVNTQ" %%mm0, (%3, %%eax)	\n\t"

			MOVNTQ" %%mm2, (%2, %%eax)	\n\t"



			"addl $8, %%eax			\n\t"

			"cmpl %4, %%eax			\n\t"

			" jb 1b				\n\t"

			::"r"(src), "r"(ydst), "r"(udst), "r"(vdst), "g" (chromWidth)

			: "memory", "%eax"

		);



		ydst += lumStride;

		src  += srcStride;



		asm volatile(

			"xorl %%eax, %%eax		\n\t"

			ASMALIGN(4)

			"1:				\n\t"

			PREFETCH" 64(%0, %%eax, 4)	\n\t"

			"movq (%0, %%eax, 4), %%mm0	\n\t" // YUYV YUYV(0)

			"movq 8(%0, %%eax, 4), %%mm1	\n\t" // YUYV YUYV(4)

			"movq 16(%0, %%eax, 4), %%mm2	\n\t" // YUYV YUYV(8)

			"movq 24(%0, %%eax, 4), %%mm3	\n\t" // YUYV YUYV(12)

			"psrlw $8, %%mm0		\n\t" // Y0Y0 Y0Y0(0)

			"psrlw $8, %%mm1		\n\t" // Y0Y0 Y0Y0(4)

			"psrlw $8, %%mm2		\n\t" // Y0Y0 Y0Y0(8)

			"psrlw $8, %%mm3		\n\t" // Y0Y0 Y0Y0(12)

			"packuswb %%mm1, %%mm0		\n\t" // YYYY YYYY(0)

			"packuswb %%mm3, %%mm2		\n\t" // YYYY YYYY(8)



			MOVNTQ" %%mm0, (%1, %%eax, 2)	\n\t"

			MOVNTQ" %%mm2, 8(%1, %%eax, 2)	\n\t"



			"addl $8, %%eax			\n\t"

			"cmpl %4, %%eax			\n\t"

			" jb 1b				\n\t"



			::"r"(src), "r"(ydst), "r"(udst), "r"(vdst), "g" (chromWidth)

			: "memory", "%eax"

		);

#else

		long i;

		for(i=0; i<chromWidth; i++)

		{

			udst[i] 	= src[4*i+0];

			ydst[2*i+0] 	= src[4*i+1];

			vdst[i] 	= src[4*i+2];

			ydst[2*i+1] 	= src[4*i+3];

		}

		ydst += lumStride;

		src  += srcStride;



		for(i=0; i<chromWidth; i++)

		{

			ydst[2*i+0] 	= src[4*i+1];

			ydst[2*i+1] 	= src[4*i+3];

		}

#endif

		udst += chromStride;

		vdst += chromStride;

		ydst += lumStride;

		src  += srcStride;

	}

#ifdef HAVE_MMX

asm volatile(   EMMS" \n\t"

        	SFENCE" \n\t"

        	:::"memory");

#endif

}

static int hls_read_packet(AVFormatContext *s, AVPacket *pkt)

{

    HLSContext *c = s->priv_data;

    int ret, i, minvariant = -1;



    if (c->first_packet) {

        recheck_discard_flags(s, 1);

        c->first_packet = 0;

    }



start:

    c->end_of_segment = 0;

    for (i = 0; i < c->n_variants; i++) {

        struct variant *var = c->variants[i];

        /* Make sure we've got one buffered packet from each open variant

         * stream */

        if (var->needed && !var->pkt.data) {

            while (1) {

                int64_t ts_diff;

                AVStream *st;

                ret = av_read_frame(var->ctx, &var->pkt);

                if (ret < 0) {

                    if (!var->pb.eof_reached)

                        return ret;


                    break;

                } else {

                    if (c->first_timestamp == AV_NOPTS_VALUE &&

                        var->pkt.dts       != AV_NOPTS_VALUE)

                        c->first_timestamp = av_rescale_q(var->pkt.dts,

                            var->ctx->streams[var->pkt.stream_index]->time_base,

                            AV_TIME_BASE_Q);

                }



                if (c->seek_timestamp == AV_NOPTS_VALUE)

                    break;



                if (var->pkt.dts == AV_NOPTS_VALUE) {

                    c->seek_timestamp = AV_NOPTS_VALUE;

                    break;

                }



                st = var->ctx->streams[var->pkt.stream_index];

                ts_diff = av_rescale_rnd(var->pkt.dts, AV_TIME_BASE,

                                         st->time_base.den, AV_ROUND_DOWN) -

                          c->seek_timestamp;

                if (ts_diff >= 0 && (c->seek_flags  & AVSEEK_FLAG_ANY ||

                                     var->pkt.flags & AV_PKT_FLAG_KEY)) {

                    c->seek_timestamp = AV_NOPTS_VALUE;

                    break;

                }



            }

        }

        /* Check if this stream still is on an earlier segment number, or

         * has the packet with the lowest dts */

        if (var->pkt.data) {

            struct variant *minvar = c->variants[minvariant];

            if (minvariant < 0 || var->cur_seq_no < minvar->cur_seq_no) {

                minvariant = i;

            } else if (var->cur_seq_no == minvar->cur_seq_no) {

                int64_t dts     =    var->pkt.dts;

                int64_t mindts  = minvar->pkt.dts;

                AVStream *st    =    var->ctx->streams[var->pkt.stream_index];

                AVStream *minst = minvar->ctx->streams[minvar->pkt.stream_index];



                if (dts == AV_NOPTS_VALUE) {

                    minvariant = i;

                } else if (mindts != AV_NOPTS_VALUE) {

                    if (st->start_time    != AV_NOPTS_VALUE)

                        dts    -= st->start_time;

                    if (minst->start_time != AV_NOPTS_VALUE)

                        mindts -= minst->start_time;



                    if (av_compare_ts(dts, st->time_base,

                                      mindts, minst->time_base) < 0)

                        minvariant = i;

                }

            }

        }

    }

    if (c->end_of_segment) {

        if (recheck_discard_flags(s, 0))

            goto start;

    }

    /* If we got a packet, return it */

    if (minvariant >= 0) {

        *pkt = c->variants[minvariant]->pkt;

        pkt->stream_index += c->variants[minvariant]->stream_offset;

        reset_packet(&c->variants[minvariant]->pkt);

        return 0;

    }

    return AVERROR_EOF;

}

static int jpeg2000_decode_packets(Jpeg2000DecoderContext *s, Jpeg2000Tile *tile)

{

    int layno, reslevelno, compno, precno, ok_reslevel, ret;

    uint8_t prog_order = tile->codsty[0].prog_order;

    uint16_t x;

    uint16_t y;



    s->bit_index = 8;

    switch (prog_order) {

    case JPEG2000_PGOD_LRCP:

        for (layno = 0; layno < tile->codsty[0].nlayers; layno++) {

            ok_reslevel = 1;

            for (reslevelno = 0; ok_reslevel; reslevelno++) {

                ok_reslevel = 0;

                for (compno = 0; compno < s->ncomponents; compno++) {

                    Jpeg2000CodingStyle *codsty = tile->codsty + compno;

                    Jpeg2000QuantStyle *qntsty  = tile->qntsty + compno;

                    if (reslevelno < codsty->nreslevels) {

                        Jpeg2000ResLevel *rlevel = tile->comp[compno].reslevel +

                                                   reslevelno;

                        ok_reslevel = 1;

                        for (precno = 0; precno < rlevel->num_precincts_x * rlevel->num_precincts_y; precno++)

                            if ((ret = jpeg2000_decode_packet(s,

                                                              codsty, rlevel,

                                                              precno, layno,

                                                              qntsty->expn + (reslevelno ? 3 * (reslevelno - 1) + 1 : 0),

                                                              qntsty->nguardbits)) < 0)

                                return ret;

                    }

                }

            }

        }

        break;



    case JPEG2000_PGOD_CPRL:

        for (compno = 0; compno < s->ncomponents; compno++) {

            Jpeg2000CodingStyle *codsty = tile->codsty + compno;

            Jpeg2000QuantStyle *qntsty  = tile->qntsty + compno;



            /* Set bit stream buffer address according to tile-part.

             * For DCinema one tile-part per component, so can be

             * indexed by component. */

            s->buf = tile->tile_part[compno].tp_start_bstrm;



            /* Position loop (y axis)

             * TODO: Automate computing of step 256.

             * Fixed here, but to be computed before entering here. */

            for (y = 0; y < s->height; y += 256) {

                /* Position loop (y axis)

                 * TODO: automate computing of step 256.

                 * Fixed here, but to be computed before entering here. */

                for (x = 0; x < s->width; x += 256) {

                    for (reslevelno = 0; reslevelno < codsty->nreslevels; reslevelno++) {

                        uint16_t prcx, prcy;

                        uint8_t reducedresno = codsty->nreslevels - 1 -reslevelno; //  ==> N_L - r

                        Jpeg2000ResLevel *rlevel = tile->comp[compno].reslevel + reslevelno;



                        if (!((y % (1 << (rlevel->log2_prec_height + reducedresno)) == 0) ||

                              (y == 0))) // TODO: 2nd condition simplified as try0 always =0 for dcinema

                            continue;



                        if (!((x % (1 << (rlevel->log2_prec_width + reducedresno)) == 0) ||

                              (x == 0))) // TODO: 2nd condition simplified as try0 always =0 for dcinema

                            continue;



                        // check if a precinct exists

                        prcx   = ff_jpeg2000_ceildivpow2(x, reducedresno) >> rlevel->log2_prec_width;

                        prcy   = ff_jpeg2000_ceildivpow2(y, reducedresno) >> rlevel->log2_prec_height;

                        precno = prcx + rlevel->num_precincts_x * prcy;

                        for (layno = 0; layno < tile->codsty[0].nlayers; layno++) {

                            if ((ret = jpeg2000_decode_packet(s, codsty, rlevel,

                                                              precno, layno,

                                                              qntsty->expn + (reslevelno ? 3 * (reslevelno - 1) + 1 : 0),

                                                              qntsty->nguardbits)) < 0)

                                return ret;

                        }

                    }

                }

            }

        }

        break;



    default:

        break;

    }



    /* EOC marker reached */

    s->buf += 2;



    return 0;

}

